insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 1 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-1-1', 1, 'Ayodhya Kanda, Sarga 1, Verse 1', 'कस्य चित्त्वथ कालस्य राजा दशरथः सुतम्।
भरतं केकयीपुत्रमब्रवीद्रघुनन्दनः॥', 'kasya cit tv atha kālasya rājā daśarathaḥ sutam
bharataṃ kekayīputram abravīd raghunandanaḥ', null, 2001001),
('ramayana-2-1-2', 2, 'Ayodhya Kanda, Sarga 1, Verse 2', 'अयं केकयराजस्य पुत्रो वसति पुत्रक।
त्वां नेतुमागतो वीर युधाजिन्मातुलस्तव॥', 'ayaṃ kekayarājasya putro vasati putraka
tvāṃ netum āgato vīra yudhājin mātulas tava', null, 2001002),
('ramayana-2-1-3', 3, 'Ayodhya Kanda, Sarga 1, Verse 3', 'श्रुत्वा दशरथस्यैतद्भरतः केकयीसुतः।
गमनायाभिचक्राम शत्रुघ्नसहितस्तदा॥', 'śrutvā daśarathasyaitad bharataḥ kekayīsutaḥ
gamanāyābhicakrāma śatrughnasahitas tadā', null, 2001003),
('ramayana-2-1-4', 4, 'Ayodhya Kanda, Sarga 1, Verse 4', 'आपृच्छ्य पितरं शूरो रामं चाक्लिष्टकारिणम्।
मातॄंश्चापि नरश्रेष्ठः शत्रुघ्नसहितो ययौ॥', 'āpṛcchya pitaraṃ śūro rāmaṃ cākliṣṭakāriṇam
mātṝṃś cāpi naraśreṣṭhaḥ śatrughnasahito yayau', null, 2001004),
('ramayana-2-1-5', 5, 'Ayodhya Kanda, Sarga 1, Verse 5', 'युधाजित्प्राप्य भरतं सशत्रुघ्नं प्रहर्षितः।
स्वपुरं प्राविशद्वीरः पिता तस्य तुतोष ह॥', 'yudhājit prāpya bharataṃ saśatrughnaṃ praharṣitaḥ
svapuraṃ prāviśad vīraḥ pitā tasya tutoṣa ha', null, 2001005),
('ramayana-2-1-6', 6, 'Ayodhya Kanda, Sarga 1, Verse 6', 'स तत्र न्यवसद्भ्रात्रा सह सत्कारसत्कृतः।
मातुलेनाश्वपतिना पुत्रस्नेहेन लालितः॥', 'sa tatra nyavasad bhrātrā saha satkārasatkṛtaḥ
mātulenāśvapatinā putrasnehena lālitaḥ', null, 2001006),
('ramayana-2-1-7', 7, 'Ayodhya Kanda, Sarga 1, Verse 7', 'तत्रापि निवसन्तौ तौ तर्प्यमाणौ च कामतः।
भ्रातरौ स्मरतां वीरौ वृद्धं दशरथं नृपम्॥', 'tatrāpi nivasantau tau tarpyamāṇau ca kāmataḥ
bhrātarau smaratāṃ vīrau vṛddhaṃ daśarathaṃ nṛpam', null, 2001007),
('ramayana-2-1-8', 8, 'Ayodhya Kanda, Sarga 1, Verse 8', 'राजापि तौ महातेजाः सस्मार प्रोषितौ सुतौ।
उभौ भरतशत्रुघ्नौ महेन्द्रवरुणोपमौ॥', 'rājāpi tau mahātejāḥ sasmāra proṣitau sutau
ubhau bharataśatrughnau mahendravaruṇopamau', null, 2001008),
('ramayana-2-1-9', 9, 'Ayodhya Kanda, Sarga 1, Verse 9', 'सर्व एव तु तस्येष्टाश्चत्वारः पुरुषर्षभाः।
स्वशरीराद्विनिर्वृत्ताश्चत्वार इव बाहवः॥', 'sarva eva tu tasyeṣṭāś catvāraḥ puruṣarṣabhāḥ
svaśarīrād vinirvṛttāś catvāra iva bāhavaḥ', null, 2001009),
('ramayana-2-1-10', 10, 'Ayodhya Kanda, Sarga 1, Verse 10', 'तेषामपि महातेजा रामो रतिकरः पितुः।
स्वयम्भूरिव भूतानां बभूव गुणवत्तरः॥', 'teṣām api mahātejā rāmo ratikaraḥ pituḥ
svayambhūr iva bhūtānāṃ babhūva guṇavattaraḥ', null, 2001010),
('ramayana-2-1-11', 11, 'Ayodhya Kanda, Sarga 1, Verse 11', 'गते च भरते रामो लक्ष्मणश्च महाबलः।
पितरं देवसंकाशं पूजयामासतुस्तदा॥', 'gate ca bharate rāmo lakṣmaṇaś ca mahābalaḥ
pitaraṃ devasaṃkāśaṃ pūjayām āsatus tadā', null, 2001011),
('ramayana-2-1-12', 12, 'Ayodhya Kanda, Sarga 1, Verse 12', 'पितुराज्ञां पुरस्कृत्य पौरकार्याणि सर्वशः।
चकार रामो धर्मात्मा प्रियाणि च हितानि च॥', 'pitur ājñāṃ puraskṛtya paurakāryāṇi sarvaśaḥ
cakāra rāmo dharmātmā priyāṇi ca hitāni ca', null, 2001012),
('ramayana-2-1-13', 13, 'Ayodhya Kanda, Sarga 1, Verse 13', 'मातृभ्यो मातृकार्याणि कृत्वा परमयन्त्रितः।
गुरूणां गुरुकार्याणि काले कालेऽन्ववैक्षत॥', 'mātṛbhyo mātṛkāryāṇi kṛtvā paramayantritaḥ
gurūṇāṃ gurukāryāṇi kāle kāle ''nvavaikṣata', null, 2001013),
('ramayana-2-1-14', 14, 'Ayodhya Kanda, Sarga 1, Verse 14', 'एवं दशरथः प्रीतो ब्राह्मणा नैगमास्तथा।
रामस्य शीलवृत्तेन सर्वे विषयवासिनः॥', 'evaṃ daśarathaḥ prīto brāhmaṇā naigamās tathā
rāmasya śīlavṛttena sarve viṣayavāsinaḥ', null, 2001014),
('ramayana-2-1-15', 15, 'Ayodhya Kanda, Sarga 1, Verse 15', 'स हि नित्यं प्रशान्तात्मा मृदुपूर्वं च भाषते।
उच्यमानोऽपि परुषं नोत्तरं प्रतिपद्यते॥', 'sa hi nityaṃ praśāntātmā mṛdupūrvaṃ ca bhāṣate
ucyamāno ''pi paruṣaṃ nottaraṃ pratipadyate', null, 2001015),
('ramayana-2-1-16', 16, 'Ayodhya Kanda, Sarga 1, Verse 16', 'कथं चिदुपकारेण कृतेनैकेन तुष्यति।
न स्मरत्यपकाराणां शतमप्यात्मवत्तया॥', 'kathaṃ cid upakāreṇa kṛtenaikena tuṣyati
na smaraty apakārāṇāṃ śatam apy ātmavattayā', null, 2001016),
('ramayana-2-1-17', 17, 'Ayodhya Kanda, Sarga 1, Verse 17', 'शीलवृद्धैर्ज्ञानवृद्धैर्वयोवृद्धैश्च सज्जनैः।
कथयन्नास्त वै नित्यमस्त्रयोग्यान्तरेष्वपि॥', 'śīlavṛddhair jñānavṛddhair vayovṛddhaiś ca sajjanaiḥ
kathayann āsta vai nityam astrayogyāntareṣv api', null, 2001017),
('ramayana-2-1-18', 18, 'Ayodhya Kanda, Sarga 1, Verse 18', 'कल्याणाभिजनः साधुरदीनः सत्यवागृजुः।
वृद्धैरभिविनीतश्च द्विजैर्धर्मार्थदर्शिभिः॥', 'kalyāṇābhijanaḥ sādhur adīnaḥ satyavāg ṛjuḥ
vṛddhair abhivinītaś ca dvijair dharmārthadarśibhiḥ', null, 2001018),
('ramayana-2-1-19', 19, 'Ayodhya Kanda, Sarga 1, Verse 19', 'धर्मार्थकामतत्त्वज्ञः स्मृतिमान्प्रतिभावनान्।
लौकिके समयाचरे कृतकल्पो विशारदः॥', 'dharmārthakāmatattvajñaḥ smṛtimān pratibhāvanān
laukike samayācare kṛtakalpo viśāradaḥ', null, 2001019),
('ramayana-2-1-20', 20, 'Ayodhya Kanda, Sarga 1, Verse 20', 'शास्त्रज्ञश्च कृतज्ञश्च पुरुषान्तरकोविदः।
यः प्रग्रहानुग्रहयोर्यथान्यायं विचक्षणः॥', 'śāstrajñaś ca kṛtajñaś ca puruṣāntarakovidaḥ
yaḥ pragrahānugrahayor yathānyāyaṃ vicakṣaṇaḥ', null, 2001020),
('ramayana-2-1-21', 21, 'Ayodhya Kanda, Sarga 1, Verse 21', 'आयकर्मण्युपायज्ञः संदृष्टव्ययकर्मवित्।
श्रैष्ठ्यं शास्त्रसमूहेषु प्राप्तो व्यामिश्रकेष्वपि॥', 'āyakarmaṇy upāyajñaḥ saṃdṛṣṭavyayakarmavit
śraiṣṭhyaṃ śāstrasamūheṣu prāpto vyāmiśrakeṣv api', null, 2001021),
('ramayana-2-1-22', 22, 'Ayodhya Kanda, Sarga 1, Verse 22', 'अर्थधर्मौ च संगृह्य सुखतन्त्रो न चालसः।
वैहारिकाणां शिल्पानां विज्ञातार्थविभागवित्॥', 'arthadharmau ca saṃgṛhya sukhatantro na cālasaḥ
vaihārikāṇāṃ śilpānāṃ vijñātārthavibhāgavit', null, 2001022),
('ramayana-2-1-23', 23, 'Ayodhya Kanda, Sarga 1, Verse 23', 'आरोहे विनये चैव युक्तो वारणवाजिनाम्।
धनुर्वेदविदां श्रेष्ठो लोकेऽतिरथसंमतः॥', 'ārohe vinaye caiva yukto vāraṇavājinām
dhanurvedavidāṃ śreṣṭho loke ''tirathasaṃmataḥ', null, 2001023),
('ramayana-2-1-24', 24, 'Ayodhya Kanda, Sarga 1, Verse 24', 'अभियाता प्रहर्ता च सेनानयविशारदः।
अप्रधृष्यश्च संग्रामे क्रुद्धैरपि सुरासुरैः॥', 'abhiyātā prahartā ca senānayaviśāradaḥ
apradhṛṣyaś ca saṃgrāme kruddhair api surāsuraiḥ', null, 2001024),
('ramayana-2-1-25', 25, 'Ayodhya Kanda, Sarga 1, Verse 25', 'अनसूयो जितक्रोधो न दृप्तो न च मत्सरी।
न चावमन्ता भूतानां न च कालवशानुगः॥', 'anasūyo jitakrodho na dṛpto na ca matsarī
na cāvamantā bhūtānāṃ na ca kālavaśānugaḥ', null, 2001025),
('ramayana-2-1-26', 26, 'Ayodhya Kanda, Sarga 1, Verse 26', 'एवं श्रेष्ठैर्गुणैर्युक्तः प्रजानां पार्थिवात्मजः।
संमतस्त्रिषु लोकेषु वसुधायाः क्षमागुणैः।
बुद्ध्या बृहस्पतेस्तुल्यो वीर्येणापि शचीपतेः॥', 'evaṃ śreṣṭhair guṇair yuktaḥ prajānāṃ pārthivātmajaḥ
saṃmatas triṣu lokeṣu vasudhāyāḥ kṣamāguṇaiḥ
buddhyā bṛhaspates tulyo vīryeṇāpi śacīpateḥ', null, 2001026),
('ramayana-2-1-27', 27, 'Ayodhya Kanda, Sarga 1, Verse 27', 'तथा सर्वप्रजाकान्तैः प्रीतिसंजननैः पितुः।
गुणैर्विरुरुचे रामो दीप्तः सूर्य इवांशुभिः॥', 'tathā sarvaprajākāntaiḥ prītisaṃjananaiḥ pituḥ
guṇair viruruce rāmo dīptaḥ sūrya ivāṃśubhiḥ', null, 2001027),
('ramayana-2-1-28', 28, 'Ayodhya Kanda, Sarga 1, Verse 28', 'तमेवंवृत्तसंपन्नमप्रधृष्य पराक्रमम्।
लोकपालोपमं नाथमकामयत मेदिनी॥', 'tam evaṃvṛttasaṃpannam apradhṛṣya parākramam
lokapālopamaṃ nātham akāmayata medinī', null, 2001028),
('ramayana-2-1-29', 29, 'Ayodhya Kanda, Sarga 1, Verse 29', 'एतैस्तु बहुभिर्युक्तं गुणैरनुपमैः सुतम्।
दृष्ट्वा दशरथो राजा चक्रे चिन्तां परंतपः॥', 'etais tu bahubhir yuktaṃ guṇair anupamaiḥ sutam
dṛṣṭvā daśaratho rājā cakre cintāṃ paraṃtapaḥ', null, 2001029),
('ramayana-2-1-30', 30, 'Ayodhya Kanda, Sarga 1, Verse 30', 'एषा ह्यस्य परा प्रीतिर्हृदि संपरिवर्तते।
कदा नाम सुतं द्रक्ष्याम्यभिषिक्तमहं प्रियम्॥', 'eṣā hy asya parā prītir hṛdi saṃparivartate
kadā nāma sutaṃ drakṣyāmy abhiṣiktam ahaṃ priyam', null, 2001030),
('ramayana-2-1-31', 31, 'Ayodhya Kanda, Sarga 1, Verse 31', 'वृद्धिकामो हि लोकस्य सर्वभूतानुकम्पनः।
मत्तः प्रियतरो लोके पर्जन्य इव वृष्टिमान्॥', 'vṛddhikāmo hi lokasya sarvabhūtānukampanaḥ
mattaḥ priyataro loke parjanya iva vṛṣṭimān', null, 2001031),
('ramayana-2-1-32', 32, 'Ayodhya Kanda, Sarga 1, Verse 32', 'यमशक्रसमो वीर्ये बृहस्पतिसमो मतौ।
महीधरसमो धृत्यां मत्तश्च गुणवत्तरः॥', 'yamaśakrasamo vīrye bṛhaspatisamo matau
mahīdharasamo dhṛtyāṃ mattaś ca guṇavattaraḥ', null, 2001032),
('ramayana-2-1-33', 33, 'Ayodhya Kanda, Sarga 1, Verse 33', 'महीमहमिमां कृत्स्नामधितिष्ठन्तमात्मजम्।
अनेन वयसा दृष्ट्वा यथा स्वर्गमवाप्नुयाम्॥', 'mahīm aham imāṃ kṛtsnām adhitiṣṭhantam ātmajam
anena vayasā dṛṣṭvā yathā svargam avāpnuyām', null, 2001033),
('ramayana-2-1-34', 34, 'Ayodhya Kanda, Sarga 1, Verse 34', 'तं समीक्ष्य महाराजो युक्तं समुदितैर्गुणैः।
निश्चित्य सचिवैः सार्धं युवराजममन्यत॥', 'taṃ samīkṣya mahārājo yuktaṃ samuditair guṇaiḥ
niścitya sacivaiḥ sārdhaṃ yuvarājam amanyata', null, 2001034),
('ramayana-2-1-35', 35, 'Ayodhya Kanda, Sarga 1, Verse 35', 'नानानगरवास्तव्यान्पृथग्जानपदानपि।
समानिनाय मेदिन्याः प्रधानान्पृथिवीपतिः॥', 'nānānagaravāstavyān pṛthagjānapadān api
samānināya medinyāḥ pradhānān pṛthivīpatiḥ', null, 2001035),
('ramayana-2-1-36', 36, 'Ayodhya Kanda, Sarga 1, Verse 36', 'अथ राजवितीर्णेषु विविधेष्वासनेषु च।
राजानमेवाभिमुखा निषेदुर्नियता नृपाः॥', 'atha rājavitīrṇeṣu vividheṣv āsaneṣu ca
rājānam evābhimukhā niṣedur niyatā nṛpāḥ', null, 2001036),
('ramayana-2-1-37', 37, 'Ayodhya Kanda, Sarga 1, Verse 37', 'स लब्धमानैर्विनयान्वितैर्नृपैः पुरालयैर्जानपदैश्च मानवैः।
उपोपविष्टैर्नृपतिर्वृतो बभौ सहस्रचक्षुर्भगवानिवामरैः॥', 'sa labdhamānair vinayānvitair nṛpaiḥ purālayair jānapadaiś ca mānavaiḥ
upopaviṣṭair nṛpatir vṛto babhau sahasracakṣur bhagavān ivāmaraiḥ', null, 2001037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 2 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-2-1', 1, 'Ayodhya Kanda, Sarga 2, Verse 1', 'ततः परिषदं सर्वामामन्त्र्य वसुधाधिपः।
हितमुद्धर्षणं चेदमुवाचाप्रतिमं वचः॥', 'tataḥ pariṣadaṃ sarvām āmantrya vasudhādhipaḥ
hitam uddharṣaṇaṃ cedam uvācāpratimaṃ vacaḥ', null, 2002001),
('ramayana-2-2-2', 2, 'Ayodhya Kanda, Sarga 2, Verse 2', 'दुन्दुभिस्वनकल्पेन गम्भीरेणानुनादिना।
स्वरेण महता राजा जीग्मूत इव नादयन्॥', 'dundubhisvanakalpena gambhīreṇānunādinā
svareṇa mahatā rājā jīgmūta iva nādayan', null, 2002002),
('ramayana-2-2-3', 3, 'Ayodhya Kanda, Sarga 2, Verse 3', 'सोऽहमिक्ष्वाकुभिः पूर्वैर्नरेन्द्रैः परिपालितम्।
श्रेयसा योक्तुकामोऽस्मि सुखार्हमखिलं जगत्॥', 'so ''ham ikṣvākubhiḥ pūrvair narendraiḥ paripālitam
śreyasā yoktukāmo ''smi sukhārham akhilaṃ jagat', null, 2002003),
('ramayana-2-2-4', 4, 'Ayodhya Kanda, Sarga 2, Verse 4', 'मयाप्याचरितं पूर्वैः पन्थानमनुगच्छता।
प्रजा नित्यमतन्द्रेण यथाशक्त्यभिरक्षता॥', 'mayāpy ācaritaṃ pūrvaiḥ panthānam anugacchatā
prajā nityam atandreṇa yathāśakty abhirakṣatā', null, 2002004),
('ramayana-2-2-5', 5, 'Ayodhya Kanda, Sarga 2, Verse 5', 'इदं शरीरं कृत्स्नस्य लोकस्य चरता हितम्।
पाण्डुरस्यातपत्रस्यच्छायायां जरितं मया॥', 'idaṃ śarīraṃ kṛtsnasya lokasya caratā hitam
pāṇḍur asyātapatrasyac chāyāyāṃ jaritaṃ mayā', null, 2002005),
('ramayana-2-2-6', 6, 'Ayodhya Kanda, Sarga 2, Verse 6', 'प्राप्य वर्षसहस्राणि बहून्यायूंषि जीवितः।
जीर्णस्यास्य शरीरस्य विश्रान्तिमभिरोचये॥', 'prāpya varṣasahasrāṇi bahūny āyūṃṣi jīvitaḥ
jīrṇasyāsya śarīrasya viśrāntim abhirocaye', null, 2002006),
('ramayana-2-2-7', 7, 'Ayodhya Kanda, Sarga 2, Verse 7', 'राजप्रभावजुष्टां हि दुर्वहामजितेन्द्रियैः।
परिश्रान्तोऽस्मि लोकस्य गुर्वीं धर्मधुरं वहन्॥', 'rājaprabhāvajuṣṭāṃ hi durvahām ajitendriyaiḥ
pariśrānto ''smi lokasya gurvīṃ dharmadhuraṃ vahan', null, 2002007),
('ramayana-2-2-8', 8, 'Ayodhya Kanda, Sarga 2, Verse 8', 'सोऽहं विश्रममिच्छामि पुत्रं कृत्वा प्रजाहिते।
संनिकृष्टानिमान्सर्वाननुमान्य द्विजर्षभान्॥', 'so ''haṃ viśramam icchāmi putraṃ kṛtvā prajāhite
saṃnikṛṣṭān imān sarvān anumānya dvijarṣabhān', null, 2002008),
('ramayana-2-2-9', 9, 'Ayodhya Kanda, Sarga 2, Verse 9', 'अनुजातो हि मे सर्वैर्गुणैर्ज्येष्ठो ममात्मजः।
पुरंदरसमो वीर्ये रामः परपुरंजयः॥', 'anujāto hi me sarvair guṇair jyeṣṭho mamātmajaḥ
puraṃdarasamo vīrye rāmaḥ parapuraṃjayaḥ', null, 2002009),
('ramayana-2-2-10', 10, 'Ayodhya Kanda, Sarga 2, Verse 10', 'तं चन्द्रमिव पुष्येण युक्तं धर्मभृतां वरम्।
यौवराज्येन योक्तास्मि प्रीतः पुरुषपुंगवम्॥', 'taṃ candram iva puṣyeṇa yuktaṃ dharmabhṛtāṃ varam
yauvarājyena yoktāsmi prītaḥ puruṣapuṃgavam', null, 2002010),
('ramayana-2-2-11', 11, 'Ayodhya Kanda, Sarga 2, Verse 11', 'अनुरूपः स वो नाथो लक्ष्मीवांल्लक्ष्मणाग्रजः।
त्रैलोक्यमपि नाथेन येन स्यान्नाथवत्तरम्॥', 'anurūpaḥ sa vo nātho lakṣmīvāṃl lakṣmaṇāgrajaḥ
trailokyam api nāthena yena syān nāthavattaram', null, 2002011),
('ramayana-2-2-12', 12, 'Ayodhya Kanda, Sarga 2, Verse 12', 'अनेन श्रेयसा सद्यः संयोज्याहमिमां महीम्।
गतक्लेशो भविष्यामि सुते तस्मिन्निवेश्य वै॥', 'anena śreyasā sadyaḥ saṃyojyāham imāṃ mahīm
gatakleśo bhaviṣyāmi sute tasmin niveśya vai', null, 2002012),
('ramayana-2-2-13', 13, 'Ayodhya Kanda, Sarga 2, Verse 13', 'इति ब्रुवन्तं मुदिताः प्रत्यनन्दन्नृपा नृपम्।
वृष्टिमन्तं महामेघं नर्दन्तमिव बर्हिणः॥', 'iti bruvantaṃ muditāḥ pratyanandan nṛpā nṛpam
vṛṣṭimantaṃ mahāmeghaṃ nardantam iva barhiṇaḥ', null, 2002013),
('ramayana-2-2-14', 14, 'Ayodhya Kanda, Sarga 2, Verse 14', 'तस्य धर्मार्थविदुषो भावमाज्ञाय सर्वशः।
ऊचुश्च मनसा ज्ञात्वा वृद्धं दशरथं नृपम्॥', 'tasya dharmārthaviduṣo bhāvam ājñāya sarvaśaḥ
ūcuś ca manasā jñātvā vṛddhaṃ daśarathaṃ nṛpam', null, 2002014),
('ramayana-2-2-15', 15, 'Ayodhya Kanda, Sarga 2, Verse 15', 'अनेकवर्षसाहस्रो वृद्धस्त्वमसि पार्थिव।
स रामं युवराजानमभिषिञ्चस्व पार्थिवम्॥', 'anekavarṣasāhasro vṛddhas tvam asi pārthiva
sa rāmaṃ yuvarājānam abhiṣiñcasva pārthivam', null, 2002015),
('ramayana-2-2-16', 16, 'Ayodhya Kanda, Sarga 2, Verse 16', 'इति तद्वचनं श्रुत्वा राजा तेषां मनःप्रियम्।
अजानन्निव जिज्ञासुरिदं वचनमब्रवीत्॥', 'iti tad vacanaṃ śrutvā rājā teṣāṃ manaḥpriyam
ajānann iva jijñāsur idaṃ vacanam abravīt', null, 2002016),
('ramayana-2-2-17', 17, 'Ayodhya Kanda, Sarga 2, Verse 17', 'कथं नु मयि धर्मेण पृथिवीमनुशासति।
भवन्तो द्रष्टुमिच्छन्ति युवराजं ममात्मजम्॥', 'kathaṃ nu mayi dharmeṇa pṛthivīm anuśāsati
bhavanto draṣṭum icchanti yuvarājaṃ mamātmajam', null, 2002017),
('ramayana-2-2-18', 18, 'Ayodhya Kanda, Sarga 2, Verse 18', 'ते तमूचुर्महात्मानं पौरजानपदैः सह।
बहवो नृप कल्याणा गुणाः पुत्रस्य सन्ति ते॥', 'te tam ūcur mahātmānaṃ paurajānapadaiḥ saha
bahavo nṛpa kalyāṇā guṇāḥ putrasya santi te', null, 2002018),
('ramayana-2-2-19', 19, 'Ayodhya Kanda, Sarga 2, Verse 19', 'दिव्यैर्गुणैः शक्रसमो रामः सत्यपराक्रमः।
इक्ष्वाकुभ्यो हि सर्वेभ्योऽप्यतिरक्तो विशाम्पते॥', 'divyair guṇaiḥ śakrasamo rāmaḥ satyaparākramaḥ
ikṣvākubhyo hi sarvebhyo ''py atirakto viśāmpate', null, 2002019),
('ramayana-2-2-20', 20, 'Ayodhya Kanda, Sarga 2, Verse 20', 'रामः सत्पुरुषो लोके सत्यधर्मपरायणः।
धर्मज्ञः सत्यसंधश्च शीलवाननसूयकः॥', 'rāmaḥ satpuruṣo loke satyadharmaparāyaṇaḥ
dharmajñaḥ satyasaṃdhaś ca śīlavān anasūyakaḥ', null, 2002020),
('ramayana-2-2-21', 21, 'Ayodhya Kanda, Sarga 2, Verse 21', 'क्षान्तः सान्त्वयिता श्लक्ष्णः कृतज्ञो विजितेन्द्रियः।
मृदुश्च स्थिरचित्तश्च सदा भव्योऽनसूयकः॥', 'kṣāntaḥ sāntvayitā ślakṣṇaḥ kṛtajño vijitendriyaḥ
mṛduś ca sthiracittaś ca sadā bhavyo ''nasūyakaḥ', null, 2002021),
('ramayana-2-2-22', 22, 'Ayodhya Kanda, Sarga 2, Verse 22', 'प्रियवादी च भूतानां सत्यवादी च राघवः।
बहुश्रुतानां वृद्धानां ब्राह्मणानामुपासिता॥', 'priyavādī ca bhūtānāṃ satyavādī ca rāghavaḥ
bahuśrutānāṃ vṛddhānāṃ brāhmaṇānām upāsitā', null, 2002022),
('ramayana-2-2-23', 23, 'Ayodhya Kanda, Sarga 2, Verse 23', 'तेनास्येहातुला कीर्तिर्यशस्तेजश्च वर्धते।
देवासुरमनुष्याणां सर्वास्त्रेषु विशारदः॥', 'tenāsyehātulā kīrtir yaśas tejaś ca vardhate
devāsuramanuṣyāṇāṃ sarvāstreṣu viśāradaḥ', null, 2002023),
('ramayana-2-2-24', 24, 'Ayodhya Kanda, Sarga 2, Verse 24', 'यदा व्रजति संग्रामं ग्रामार्थे नगरस्य वा।
गत्वा सौमित्रिसहितो नाविजित्य निवर्तते॥', 'yadā vrajati saṃgrāmaṃ grāmārthe nagarasya vā
gatvā saumitrisahito nāvijitya nivartate', null, 2002024),
('ramayana-2-2-25', 25, 'Ayodhya Kanda, Sarga 2, Verse 25', 'संग्रामात्पुनरागम्य कुञ्जरेण रथेन वा।
पौरान्स्वजनवन्नित्यं कुशलं परिपृच्छति॥', 'saṃgrāmāt punar āgamya kuñjareṇa rathena vā
paurān svajanavan nityaṃ kuśalaṃ paripṛcchati', null, 2002025),
('ramayana-2-2-26', 26, 'Ayodhya Kanda, Sarga 2, Verse 26', 'पुत्रेष्वग्निषु दारेषु प्रेष्यशिष्यगणेषु च।
निखिलेनानुपूर्व्या च पिता पुत्रानिवौरसान्॥', 'putreṣv agniṣu dāreṣu preṣyaśiṣyagaṇeṣu ca
nikhilenānupūrvyā ca pitā putrān ivaurasān', null, 2002026),
('ramayana-2-2-27', 27, 'Ayodhya Kanda, Sarga 2, Verse 27', 'शुश्रूषन्ते च वः शिष्याः कच्चित्कर्मसु दंशिताः।
इति नः पुरुषव्याघ्रः सदा रामोऽभिभाषते॥', 'śuśrūṣante ca vaḥ śiṣyāḥ kaccit karmasu daṃśitāḥ
iti naḥ puruṣavyāghraḥ sadā rāmo ''bhibhāṣate', null, 2002027),
('ramayana-2-2-28', 28, 'Ayodhya Kanda, Sarga 2, Verse 28', 'व्यसनेषु मनुष्याणां भृशं भवति दुःखितः।
उत्सवेषु च सर्वेषु पितेव परितुष्यति॥', 'vyasaneṣu manuṣyāṇāṃ bhṛśaṃ bhavati duḥkhitaḥ
utsaveṣu ca sarveṣu piteva parituṣyati', null, 2002028),
('ramayana-2-2-29', 29, 'Ayodhya Kanda, Sarga 2, Verse 29', 'सत्यवादी महेष्वासो वृद्धसेवी जितेन्द्रियः।
वत्सः श्रेयसि जातस्ते दिष्ट्यासौ तव राघवः।
दिष्ट्या पुत्रगुणैर्युक्तो मारीच इव कश्यपः॥', 'satyavādī maheṣvāso vṛddhasevī jitendriyaḥ
vatsaḥ śreyasi jātas te diṣṭyāsau tava rāghavaḥ
diṣṭyā putraguṇair yukto mārīca iva kaśyapaḥ', null, 2002029),
('ramayana-2-2-30', 30, 'Ayodhya Kanda, Sarga 2, Verse 30', 'बलमारोग्यमायुश्च रामस्य विदितात्मनः।
आशंसते जनः सर्वो राष्ट्रे पुरवरे तथा॥', 'balam ārogyam āyuś ca rāmasya viditātmanaḥ
āśaṃsate janaḥ sarvo rāṣṭre puravare tathā', null, 2002030),
('ramayana-2-2-31', 31, 'Ayodhya Kanda, Sarga 2, Verse 31', 'अभ्यन्तरश्च बाह्यश्च पौरजानपदो जनः।
स्त्रियो वृद्धास्तरुण्यश्च सायंप्रातः समाहिताः॥', 'abhyantaraś ca bāhyaś ca paurajānapado janaḥ
striyo vṛddhās taruṇyaś ca sāyaṃprātaḥ samāhitāḥ', null, 2002031),
('ramayana-2-2-32', 32, 'Ayodhya Kanda, Sarga 2, Verse 32', 'सर्वान्देवान्नमस्यन्ति रामस्यार्थे यशस्विनः।
तेषामायाचितं देव त्वत्प्रसादात्समृध्यताम्॥', 'sarvān devān namasyanti rāmasyārthe yaśasvinaḥ
teṣām āyācitaṃ deva tvatprasādāt samṛdhyatām', null, 2002032),
('ramayana-2-2-33', 33, 'Ayodhya Kanda, Sarga 2, Verse 33', 'राममिन्दीवरश्यामं सर्वशत्रुनिबर्हणम्।
पश्यामो यौवराज्यस्थं तव राजोत्तमात्मजम्॥', 'rāmam indīvaraśyāmaṃ sarvaśatrunibarhaṇam
paśyāmo yauvarājyasthaṃ tava rājottamātmajam', null, 2002033),
('ramayana-2-2-34', 34, 'Ayodhya Kanda, Sarga 2, Verse 34', 'तं देवदेवोपममात्मजं ते सर्वस्य लोकस्य हिते निविष्टम्।
हिताय नः क्षिप्रमुदारजुष्टं मुदाभिषेक्तुं वरद त्वमर्हसि॥', 'taṃ devadevopamam ātmajaṃ te sarvasya lokasya hite niviṣṭam
hitāya naḥ kṣipram udārajuṣṭaṃ mudābhiṣektuṃ varada tvam arhasi', null, 2002034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 3 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-3-1', 1, 'Ayodhya Kanda, Sarga 3, Verse 1', 'तेषामज्ञलिपद्मानि प्रगृहीतानि सर्वशः।
प्रतिगृह्याब्रवीद्राजा तेभ्यः प्रियहितं वचः॥', 'teṣām ajñalipadmāni pragṛhītāni sarvaśaḥ
pratigṛhyābravīd rājā tebhyaḥ priyahitaṃ vacaḥ', null, 2003001),
('ramayana-2-3-2', 2, 'Ayodhya Kanda, Sarga 3, Verse 2', 'अहोऽस्मि परमप्रीतः प्रभावश्चातुलो मम।
यन्मे ज्येष्ठं प्रियं पुत्रं यौवराज्यस्थमिच्छथ॥', 'aho ''smi paramaprītaḥ prabhāvaś cātulo mama
yan me jyeṣṭhaṃ priyaṃ putraṃ yauvarājyastham icchatha', null, 2003002),
('ramayana-2-3-3', 3, 'Ayodhya Kanda, Sarga 3, Verse 3', 'इति प्रत्यर्च्य तान्राजा ब्राह्मणानिदमब्रवीत्।
वसिष्ठं वामदेवं च तेषामेवोपशृण्वताम्॥', 'iti pratyarcya tān rājā brāhmaṇān idam abravīt
vasiṣṭhaṃ vāmadevaṃ ca teṣām evopaśṛṇvatām', null, 2003003),
('ramayana-2-3-4', 4, 'Ayodhya Kanda, Sarga 3, Verse 4', 'चैत्रः श्रीमानयं मासः पुण्यः पुष्पितकाननः।
यौवराज्याय रामस्य सर्वमेवोपकल्प्यताम्॥', 'caitraḥ śrīmān ayaṃ māsaḥ puṇyaḥ puṣpitakānanaḥ
yauvarājyāya rāmasya sarvam evopakalpyatām', null, 2003004),
('ramayana-2-3-5', 5, 'Ayodhya Kanda, Sarga 3, Verse 5', 'कृतमित्येव चाब्रूतामभिगम्य जगत्पतिम्।
यथोक्तवचनं प्रीतौ हर्षयुक्तौ द्विजर्षभौ॥', 'kṛtam ity eva cābrūtām abhigamya jagatpatim
yathoktavacanaṃ prītau harṣayuktau dvijarṣabhau', null, 2003005),
('ramayana-2-3-6', 6, 'Ayodhya Kanda, Sarga 3, Verse 6', 'ततः सुमन्त्रं द्युतिमान्राजा वचनमब्रवीत्।
रामः कृतात्मा भवता शीघ्रमानीयतामिति॥', 'tataḥ sumantraṃ dyutimān rājā vacanam abravīt
rāmaḥ kṛtātmā bhavatā śīghram ānīyatām iti', null, 2003006),
('ramayana-2-3-7', 7, 'Ayodhya Kanda, Sarga 3, Verse 7', 'स तथेति प्रतिज्ञाय सुमन्त्रो राजशासनात्।
रामं तत्रानयां चक्रे रथेन रथिनां वरम्॥', 'sa tatheti pratijñāya sumantro rājaśāsanāt
rāmaṃ tatrānayāṃ cakre rathena rathināṃ varam', null, 2003007),
('ramayana-2-3-8', 8, 'Ayodhya Kanda, Sarga 3, Verse 8', 'अथ तत्र समासीनास्तदा दशरथं नृपम्।
प्राच्योदीच्याः प्रतीच्याश्च दाक्षिणात्याश्च भूमिपाः॥', 'atha tatra samāsīnās tadā daśarathaṃ nṛpam
prācyodīcyāḥ pratīcyāś ca dākṣiṇātyāś ca bhūmipāḥ', null, 2003008),
('ramayana-2-3-9', 9, 'Ayodhya Kanda, Sarga 3, Verse 9', 'म्लेच्छाश्चार्याश्च ये चान्ये वनशैलान्तवासिनः।
उपासां चक्रिरे सर्वे तं देवा इव वासवम्॥', 'mlecchāś cāryāś ca ye cānye vanaśailāntavāsinaḥ
upāsāṃ cakrire sarve taṃ devā iva vāsavam', null, 2003009),
('ramayana-2-3-10', 10, 'Ayodhya Kanda, Sarga 3, Verse 10', 'तेषां मध्ये स राजर्षिर्मरुतामिव वासवः।
प्रासादस्थो रथगतं ददर्शायान्तमात्मजम्॥', 'teṣāṃ madhye sa rājarṣir marutām iva vāsavaḥ
prāsādastho rathagataṃ dadarśāyāntam ātmajam', null, 2003010),
('ramayana-2-3-11', 11, 'Ayodhya Kanda, Sarga 3, Verse 11', 'गन्धर्वराजप्रतिमं लोके विख्यातपौरुषम्।
दीर्घबाहुं महासत्त्वं मत्तमातङ्गगामिनम्॥', 'gandharvarājapratimaṃ loke vikhyātapauruṣam
dīrghabāhuṃ mahāsattvaṃ mattamātaṅgagāminam', null, 2003011),
('ramayana-2-3-12', 12, 'Ayodhya Kanda, Sarga 3, Verse 12', 'चन्द्रकान्ताननं राममतीव प्रियदर्शनम्।
रूपौदार्यगुणैः पुंसां दृष्टिचित्तापहारिणम्॥', 'candrakāntānanaṃ rāmam atīva priyadarśanam
rūpaudāryaguṇaiḥ puṃsāṃ dṛṣṭicittāpahāriṇam', null, 2003012),
('ramayana-2-3-13', 13, 'Ayodhya Kanda, Sarga 3, Verse 13', 'घर्माभितप्ताः पर्जन्यं ह्लादयन्तमिव प्रजाः।
न ततर्प समायान्तं पश्यमानो नराधिपः॥', 'gharmābhitaptāḥ parjanyaṃ hlādayantam iva prajāḥ
na tatarpa samāyāntaṃ paśyamāno narādhipaḥ', null, 2003013),
('ramayana-2-3-14', 14, 'Ayodhya Kanda, Sarga 3, Verse 14', 'अवतार्य सुमन्त्रस्तं राघवं स्यन्दनोत्तमात्।
पितुः समीपं गच्छन्तं प्राञ्जलिः पृष्ठतोऽन्वगात्॥', 'avatārya sumantras taṃ rāghavaṃ syandanottamāt
pituḥ samīpaṃ gacchantaṃ prāñjaliḥ pṛṣṭhato ''nvagāt', null, 2003014),
('ramayana-2-3-15', 15, 'Ayodhya Kanda, Sarga 3, Verse 15', 'स तं कैलासशृङ्गाभं प्रासादं नरपुंगवः।
आरुरोह नृपं द्रष्टुं सह सूतेन राघवः॥', 'sa taṃ kailāsaśṛṅgābhaṃ prāsādaṃ narapuṃgavaḥ
āruroha nṛpaṃ draṣṭuṃ saha sūtena rāghavaḥ', null, 2003015),
('ramayana-2-3-16', 16, 'Ayodhya Kanda, Sarga 3, Verse 16', 'स प्राञ्जलिरभिप्रेत्य प्रणतः पितुरन्तिके।
नाम स्वं श्रावयन्रामो ववन्दे चरणौ पितुः॥', 'sa prāñjalir abhipretya praṇataḥ pitur antike
nāma svaṃ śrāvayan rāmo vavande caraṇau pituḥ', null, 2003016),
('ramayana-2-3-17', 17, 'Ayodhya Kanda, Sarga 3, Verse 17', 'तं दृष्ट्वा प्रणतं पार्श्वे कृताञ्जलिपुटं नृपः।
गृह्याञ्जलौ समाकृष्य सस्वजे प्रियमात्मजम्॥', 'taṃ dṛṣṭvā praṇataṃ pārśve kṛtāñjalipuṭaṃ nṛpaḥ
gṛhyāñjalau samākṛṣya sasvaje priyam ātmajam', null, 2003017),
('ramayana-2-3-18', 18, 'Ayodhya Kanda, Sarga 3, Verse 18', 'तस्मै चाभ्युद्यतं श्रीमान्मणिकाञ्चनभूषितम्।
दिदेश राजा रुचिरं रामाय परमासनम्॥', 'tasmai cābhyudyataṃ śrīmān maṇikāñcanabhūṣitam
dideśa rājā ruciraṃ rāmāya paramāsanam', null, 2003018),
('ramayana-2-3-19', 19, 'Ayodhya Kanda, Sarga 3, Verse 19', 'तदासनवरं प्राप्य व्यदीपयत राघवः।
स्वयेव प्रभया मेरुमुदये विमलो रविः॥', 'tad āsanavaraṃ prāpya vyadīpayata rāghavaḥ
svayeva prabhayā merum udaye vimalo raviḥ', null, 2003019),
('ramayana-2-3-20', 20, 'Ayodhya Kanda, Sarga 3, Verse 20', 'तेन विभ्राजिता तत्र सा सभाभिव्यरोचत।
विमलग्रहनक्षत्रा शारदी द्यौरिवेन्दुना॥', 'tena vibhrājitā tatra sā sabhābhivyarocata
vimalagrahanakṣatrā śāradī dyaur ivendunā', null, 2003020),
('ramayana-2-3-21', 21, 'Ayodhya Kanda, Sarga 3, Verse 21', 'तं पश्यमानो नृपतिस्तुतोष प्रियमात्मजम्।
अलंकृतमिवात्मानमादर्शतलसंस्थितम्॥', 'taṃ paśyamāno nṛpatis tutoṣa priyam ātmajam
alaṃkṛtam ivātmānam ādarśatalasaṃsthitam', null, 2003021),
('ramayana-2-3-22', 22, 'Ayodhya Kanda, Sarga 3, Verse 22', 'स तं सस्मितमाभाष्य पुत्रं पुत्रवतां वरः।
उवाचेदं वचो राजा देवेन्द्रमिव कश्यपः॥', 'sa taṃ sasmitam ābhāṣya putraṃ putravatāṃ varaḥ
uvācedaṃ vaco rājā devendram iva kaśyapaḥ', null, 2003022),
('ramayana-2-3-23', 23, 'Ayodhya Kanda, Sarga 3, Verse 23', 'ज्येष्ठायामसि मे पत्न्यां सदृश्यां सदृशः सुतः।
उत्पन्नस्त्वं गुणश्रेष्ठो मम रामात्मजः प्रियः॥', 'jyeṣṭhāyām asi me patnyāṃ sadṛśyāṃ sadṛśaḥ sutaḥ
utpannas tvaṃ guṇaśreṣṭho mama rāmātmajaḥ priyaḥ', null, 2003023),
('ramayana-2-3-24', 24, 'Ayodhya Kanda, Sarga 3, Verse 24', 'त्वया यतः प्रजाश्चेमाः स्वगुणैरनुरञ्जिताः।
तस्मात्त्वं पुष्ययोगेन यौवराज्यमवाप्नुहि॥', 'tvayā yataḥ prajāś cemāḥ svaguṇair anurañjitāḥ
tasmāt tvaṃ puṣyayogena yauvarājyam avāpnuhi', null, 2003024),
('ramayana-2-3-25', 25, 'Ayodhya Kanda, Sarga 3, Verse 25', 'कामतस्त्वं प्रकृत्यैव विनीतो गुणवानसि।
गुणवत्यपि तु स्नेहात्पुत्र वक्ष्यामि ते हितम्॥', 'kāmatas tvaṃ prakṛtyaiva vinīto guṇavān asi
guṇavaty api tu snehāt putra vakṣyāmi te hitam', null, 2003025),
('ramayana-2-3-26', 26, 'Ayodhya Kanda, Sarga 3, Verse 26', 'भूयो विनयमास्थाय भव नित्यं जितेन्द्रियः।
कामक्रोधसमुत्थानि त्यजेथा व्यसनानि च॥', 'bhūyo vinayam āsthāya bhava nityaṃ jitendriyaḥ
kāmakrodhasamutthāni tyajethā vyasanāni ca', null, 2003026),
('ramayana-2-3-27', 27, 'Ayodhya Kanda, Sarga 3, Verse 27', 'परोक्षया वर्तमानो वृत्त्या प्रत्यक्षया तथा।
अमात्यप्रभृतीः सर्वाः प्रकृतीश्चानुरञ्जय॥', 'parokṣayā vartamāno vṛttyā pratyakṣayā tathā
amātyaprabhṛtīḥ sarvāḥ prakṛtīś cānurañjaya', null, 2003027),
('ramayana-2-3-28', 28, 'Ayodhya Kanda, Sarga 3, Verse 28', 'तुष्टानुरक्तप्रकृतिर्यः पालयति मेदिनीम्।
तस्य नन्दन्ति मित्राणि लब्ध्वामृतमिवामराः।
तस्मात्पुत्र त्वमात्मानं नियम्यैव समाचर॥', 'tuṣṭānuraktaprakṛtir yaḥ pālayati medinīm
tasya nandanti mitrāṇi labdhvāmṛtam ivāmarāḥ
tasmāt putra tvam ātmānaṃ niyamyaiva samācara', null, 2003028),
('ramayana-2-3-29', 29, 'Ayodhya Kanda, Sarga 3, Verse 29', 'तच्छ्रुत्वा सुहृदस्तस्य रामस्य प्रियकारिणः।
त्वरिताः शीघ्रमभ्येत्य कौसल्यायै न्यवेदयन्॥', 'tac chrutvā suhṛdas tasya rāmasya priyakāriṇaḥ
tvaritāḥ śīghram abhyetya kausalyāyai nyavedayan', null, 2003029),
('ramayana-2-3-30', 30, 'Ayodhya Kanda, Sarga 3, Verse 30', 'सा हिरण्यं च गाश्चैव रत्नानि विविधानि च।
व्यादिदेश प्रियाख्येभ्यः कौसल्या प्रमदोत्तमा॥', 'sā hiraṇyaṃ ca gāś caiva ratnāni vividhāni ca
vyādideśa priyākhyebhyaḥ kausalyā pramadottamā', null, 2003030),
('ramayana-2-3-31', 31, 'Ayodhya Kanda, Sarga 3, Verse 31', 'अथाभिवाद्य राजानं रथमारुह्य राघवः।
ययौ स्वं द्युतिमद्वेश्म जनौघैः प्रतिपूजितः॥', 'athābhivādya rājānaṃ ratham āruhya rāghavaḥ
yayau svaṃ dyutimad veśma janaughaiḥ pratipūjitaḥ', null, 2003031),
('ramayana-2-3-32', 32, 'Ayodhya Kanda, Sarga 3, Verse 32', 'ते चापि पौरा नृपतेर्वचस्तच्छ्रुत्वा तदा लाभमिवेष्टमाप्य।
नरेन्द्रमामन्त्य गृहाणि गत्वा देवान्समानर्चुरतीव हृष्टाः॥', 'te cāpi paurā nṛpater vacas tac chrutvā tadā lābham iveṣṭam āpya
narendram āmantya gṛhāṇi gatvā devān samānarcur atīva hṛṣṭāḥ', null, 2003032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 4 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-4-1', 1, 'Ayodhya Kanda, Sarga 4, Verse 1', 'गतेष्वथ नृपो भूयः पौरेषु सह मन्त्रिभिः।
मन्त्रयित्वा ततश्चक्रे निश्चयज्ञः स निश्चयम्॥', 'gateṣv atha nṛpo bhūyaḥ paureṣu saha mantribhiḥ
mantrayitvā tataś cakre niścayajñaḥ sa niścayam', null, 2004001),
('ramayana-2-4-2', 2, 'Ayodhya Kanda, Sarga 4, Verse 2', 'श्व एव पुष्यो भविता श्वोऽभिषेच्येत मे सुतः।
रामो राजीवताम्राक्षो यौवराज्य इति प्रभुः॥', 'śva eva puṣyo bhavitā śvo ''bhiṣecyeta me sutaḥ
rāmo rājīvatāmrākṣo yauvarājya iti prabhuḥ', null, 2004002),
('ramayana-2-4-3', 3, 'Ayodhya Kanda, Sarga 4, Verse 3', 'अथान्तर्गृहमाविश्य राजा दशरथस्तदा।
सूतमाज्ञापयामास रामं पुनरिहानय॥', 'athāntargṛham āviśya rājā daśarathas tadā
sūtam ājñāpayām āsa rāmaṃ punar ihānaya', null, 2004003),
('ramayana-2-4-4', 4, 'Ayodhya Kanda, Sarga 4, Verse 4', 'प्रतिगृह्य स तद्वाक्यं सूतः पुनरुपाययौ।
रामस्य भवनं शीघ्रं राममानयितुं पुनः॥', 'pratigṛhya sa tadvākyaṃ sūtaḥ punar upāyayau
rāmasya bhavanaṃ śīghraṃ rāmam ānayituṃ punaḥ', null, 2004004),
('ramayana-2-4-5', 5, 'Ayodhya Kanda, Sarga 4, Verse 5', 'द्वाःस्थैरावेदितं तस्य रामायागमनं पुनः।
श्रुत्वैव चापि रामस्तं प्राप्तं शङ्कान्वितोऽभवत्॥', 'dvāḥsthair āveditaṃ tasya rāmāyāgamanaṃ punaḥ
śrutvaiva cāpi rāmas taṃ prāptaṃ śaṅkānvito ''bhavat', null, 2004005),
('ramayana-2-4-6', 6, 'Ayodhya Kanda, Sarga 4, Verse 6', 'प्रवेश्य चैनं त्वरितं रामो वचनमब्रवीत्।
यदागमनकृत्यं ते भूयस्तद्ब्रूह्यशेषतः॥', 'praveśya cainaṃ tvaritaṃ rāmo vacanam abravīt
yad āgamanakṛtyaṃ te bhūyas tad brūhy aśeṣataḥ', null, 2004006),
('ramayana-2-4-7', 7, 'Ayodhya Kanda, Sarga 4, Verse 7', 'तमुवाच ततः सूतो राजा त्वां द्रष्टुमिच्छति।
श्रुत्वा प्रमाणमत्र त्वं गमनायेतराय वा॥', 'tam uvāca tataḥ sūto rājā tvāṃ draṣṭum icchati
śrutvā pramāṇam atra tvaṃ gamanāyetarāya vā', null, 2004007),
('ramayana-2-4-8', 8, 'Ayodhya Kanda, Sarga 4, Verse 8', 'इति सूतवचः श्रुत्वा रामोऽथ त्वरयान्वितः।
प्रययौ राजभवनं पुनर्द्रष्टुं नरेश्वरम्॥', 'iti sūtavacaḥ śrutvā rāmo ''tha tvarayānvitaḥ
prayayau rājabhavanaṃ punar draṣṭuṃ nareśvaram', null, 2004008),
('ramayana-2-4-9', 9, 'Ayodhya Kanda, Sarga 4, Verse 9', 'तं श्रुत्वा समनुप्राप्तं रामं दशरथो नृपः।
प्रवेशयामास गृहं विविक्षुः प्रियमुत्तमम्॥', 'taṃ śrutvā samanuprāptaṃ rāmaṃ daśaratho nṛpaḥ
praveśayām āsa gṛhaṃ vivikṣuḥ priyam uttamam', null, 2004009),
('ramayana-2-4-10', 10, 'Ayodhya Kanda, Sarga 4, Verse 10', 'प्रविशन्नेव च श्रीमान्राघवो भवनं पितुः।
ददर्श पितरं दूरात्प्रणिपत्य कृताञ्जलिः॥', 'praviśann eva ca śrīmān rāghavo bhavanaṃ pituḥ
dadarśa pitaraṃ dūrāt praṇipatya kṛtāñjaliḥ', null, 2004010),
('ramayana-2-4-11', 11, 'Ayodhya Kanda, Sarga 4, Verse 11', 'प्रणमन्तं समुत्थाप्य तं परिष्वज्य भूमिपः।
प्रदिश्य चास्मै रुचिरमासनं पुनरब्रवीत्॥', 'praṇamantaṃ samutthāpya taṃ pariṣvajya bhūmipaḥ
pradiśya cāsmai ruciram āsanaṃ punar abravīt', null, 2004011),
('ramayana-2-4-12', 12, 'Ayodhya Kanda, Sarga 4, Verse 12', 'राम वृद्धोऽस्मि दीर्घायुर्भुक्ता भोगा मयेप्सिताः।
अन्नवद्भिः क्रतुशतैस्तथेष्टं भूरिदक्षिणैः॥', 'rāma vṛddho ''smi dīrghāyur bhuktā bhogā mayepsitāḥ
annavadbhiḥ kratuśatais tatheṣṭaṃ bhūridakṣiṇaiḥ', null, 2004012),
('ramayana-2-4-13', 13, 'Ayodhya Kanda, Sarga 4, Verse 13', 'जातमिष्टमपत्यं मे त्वमद्यानुपमं भुवि।
दत्तमिष्टमधीतं च मया पुरुषसत्तम॥', 'jātam iṣṭam apatyaṃ me tvam adyānupamaṃ bhuvi
dattam iṣṭam adhītaṃ ca mayā puruṣasattama', null, 2004013),
('ramayana-2-4-14', 14, 'Ayodhya Kanda, Sarga 4, Verse 14', 'अनुभूतानि चेष्टानि मया वीर सुखानि च।
देवर्षि पितृविप्राणामनृणोऽस्मि तथात्मनः॥', 'anubhūtāni ceṣṭāni mayā vīra sukhāni ca
devarṣi pitṛviprāṇām anṛṇo ''smi tathātmanaḥ', null, 2004014),
('ramayana-2-4-15', 15, 'Ayodhya Kanda, Sarga 4, Verse 15', 'न किं चिन्मम कर्तव्यं तवान्यत्राभिषेचनात्।
अतो यत्त्वामहं ब्रूयां तन्मे त्वं कर्तुमर्हसि॥', 'na kiṃ cin mama kartavyaṃ tavānyatrābhiṣecanāt
ato yat tvām ahaṃ brūyāṃ tan me tvaṃ kartum arhasi', null, 2004015),
('ramayana-2-4-16', 16, 'Ayodhya Kanda, Sarga 4, Verse 16', 'अद्य प्रकृतयः सर्वास्त्वामिच्छन्ति नराधिपम्।
अतस्त्वां युवराजानमभिषेक्ष्यामि पुत्रक॥', 'adya prakṛtayaḥ sarvās tvām icchanti narādhipam
atas tvāṃ yuvarājānam abhiṣekṣyāmi putraka', null, 2004016),
('ramayana-2-4-17', 17, 'Ayodhya Kanda, Sarga 4, Verse 17', 'अपि चाद्याशुभान्राम स्वप्नान्पश्यामि दारुणान्।
सनिर्घाता महोल्काश्च पतन्तीह महास्वनाः॥', 'api cādyāśubhān rāma svapnān paśyāmi dāruṇān
sanirghātā maholkāś ca patantīha mahāsvanāḥ', null, 2004017),
('ramayana-2-4-18', 18, 'Ayodhya Kanda, Sarga 4, Verse 18', 'अवष्टब्धं च मे राम नक्षत्रं दारुणैर्ग्रहैः।
आवेदयन्ति दैवज्ञाः सूर्याङ्गारकराहुभिः॥', 'avaṣṭabdhaṃ ca me rāma nakṣatraṃ dāruṇair grahaiḥ
āvedayanti daivajñāḥ sūryāṅgārakarāhubhiḥ', null, 2004018),
('ramayana-2-4-19', 19, 'Ayodhya Kanda, Sarga 4, Verse 19', 'प्रायेण हि निमित्तानामीदृशानां समुद्भवे।
राजा वा मृत्युमाप्नोति घोरां वापदमृच्छति॥', 'prāyeṇa hi nimittānām īdṛśānāṃ samudbhave
rājā vā mṛtyum āpnoti ghorāṃ vāpadam ṛcchati', null, 2004019),
('ramayana-2-4-20', 20, 'Ayodhya Kanda, Sarga 4, Verse 20', 'तद्यावदेव मे चेतो न विमुह्यति राघव।
तावदेवाभिषिञ्चस्व चला हि प्राणिनां मतिः॥', 'tad yāvad eva me ceto na vimuhyati rāghava
tāvad evābhiṣiñcasva calā hi prāṇināṃ matiḥ', null, 2004020),
('ramayana-2-4-21', 21, 'Ayodhya Kanda, Sarga 4, Verse 21', 'अद्य चन्द्रोऽभ्युपगतः पुष्यात्पूर्वं पुनर्वसुम्।
श्वः पुष्य योगं नियतं वक्ष्यन्ते दैवचिन्तकाः॥', 'adya candro ''bhyupagataḥ puṣyāt pūrvaṃ punar vasum
śvaḥ puṣya yogaṃ niyataṃ vakṣyante daivacintakāḥ', null, 2004021),
('ramayana-2-4-22', 22, 'Ayodhya Kanda, Sarga 4, Verse 22', 'तत्र पुष्येऽभिषिञ्चस्व मनस्त्वरयतीव माम्।
श्वस्त्वाहमभिषेक्ष्यामि यौवराज्ये परंतप॥', 'tatra puṣye ''bhiṣiñcasva manas tvarayatīva mām
śvas tvāham abhiṣekṣyāmi yauvarājye paraṃtapa', null, 2004022),
('ramayana-2-4-23', 23, 'Ayodhya Kanda, Sarga 4, Verse 23', 'तस्मात्त्वयाद्य व्रतिना निशेयं नियतात्मना।
सह वध्वोपवस्तव्या दर्भप्रस्तरशायिना॥', 'tasmāt tvayādya vratinā niśeyaṃ niyatātmanā
saha vadhvopavastavyā darbhaprastaraśāyinā', null, 2004023),
('ramayana-2-4-24', 24, 'Ayodhya Kanda, Sarga 4, Verse 24', 'सुहृदश्चाप्रमत्तास्त्वां रक्षन्त्वद्य समन्ततः।
भवन्ति बहुविघ्नानि कार्याण्येवंविधानि हि॥', 'suhṛdaś cāpramattās tvāṃ rakṣantv adya samantataḥ
bhavanti bahuvighnāni kāryāṇy evaṃvidhāni hi', null, 2004024),
('ramayana-2-4-25', 25, 'Ayodhya Kanda, Sarga 4, Verse 25', 'विप्रोषितश्च भरतो यावदेव पुरादितः।
तावदेवाभिषेकस्ते प्राप्तकालो मतो मम॥', 'viproṣitaś ca bharato yāvad eva purād itaḥ
tāvad evābhiṣekas te prāptakālo mato mama', null, 2004025),
('ramayana-2-4-26', 26, 'Ayodhya Kanda, Sarga 4, Verse 26', 'कामं खलु सतां वृत्ते भ्राता ते भरतः स्थितः।
ज्येष्ठानुवर्ती धर्मात्मा सानुक्रोशो जितेन्द्रियः॥', 'kāmaṃ khalu satāṃ vṛtte bhrātā te bharataḥ sthitaḥ
jyeṣṭhānuvartī dharmātmā sānukrośo jitendriyaḥ', null, 2004026),
('ramayana-2-4-27', 27, 'Ayodhya Kanda, Sarga 4, Verse 27', 'किं तु चित्तं मनुष्याणामनित्यमिति मे मतिः।
सतां च धर्मनित्यानां कृतशोभि च राघव॥', 'kiṃ tu cittaṃ manuṣyāṇām anityam iti me matiḥ
satāṃ ca dharmanityānāṃ kṛtaśobhi ca rāghava', null, 2004027),
('ramayana-2-4-28', 28, 'Ayodhya Kanda, Sarga 4, Verse 28', 'इत्युक्तः सोऽभ्यनुज्ञातः श्वोभाविन्यभिषेचने।
व्रजेति रामः पितरमभिवाद्याभ्ययाद्गृहम्॥', 'ity uktaḥ so ''bhyanujñātaḥ śvobhāviny abhiṣecane
vrajeti rāmaḥ pitaram abhivādyābhyayād gṛham', null, 2004028),
('ramayana-2-4-29', 29, 'Ayodhya Kanda, Sarga 4, Verse 29', 'प्रविश्य चात्मनो वेश्म राज्ञोद्दिष्टेऽभिषेचने।
तस्मिन्क्षणे विनिर्गत्य मातुरन्तःपुरं ययौ॥', 'praviśya cātmano veśma rājñoddiṣṭe ''bhiṣecane
tasmin kṣaṇe vinirgatya mātur antaḥpuraṃ yayau', null, 2004029),
('ramayana-2-4-30', 30, 'Ayodhya Kanda, Sarga 4, Verse 30', 'तत्र तां प्रवणामेव मातरं क्षौमवासिनीम्।
वाग्यतां देवतागारे ददर्श याचतीं श्रियम्॥', 'tatra tāṃ pravaṇām eva mātaraṃ kṣaumavāsinīm
vāgyatāṃ devatāgāre dadarśa yācatīṃ śriyam', null, 2004030),
('ramayana-2-4-31', 31, 'Ayodhya Kanda, Sarga 4, Verse 31', 'प्रागेव चागता तत्र सुमित्रा लक्ष्मणस्तथा।
सीता चानायिता श्रुत्वा प्रियं रामाभिषेचनम्॥', 'prāg eva cāgatā tatra sumitrā lakṣmaṇas tathā
sītā cānāyitā śrutvā priyaṃ rāmābhiṣecanam', null, 2004031),
('ramayana-2-4-32', 32, 'Ayodhya Kanda, Sarga 4, Verse 32', 'तस्मिन्काले हि कौसल्या तस्थावामीलितेक्षणा।
सुमित्रयान्वास्यमाना सीतया लक्ष्मणेन च॥', 'tasmin kāle hi kausalyā tasthāv āmīlitekṣaṇā
sumitrayānvāsyamānā sītayā lakṣmaṇena ca', null, 2004032),
('ramayana-2-4-33', 33, 'Ayodhya Kanda, Sarga 4, Verse 33', 'श्रुत्वा पुष्येण पुत्रस्य यौवराज्याभिषेचनम्।
प्राणायामेन पुरुषं ध्यायमाना जनार्दनम्॥', 'śrutvā puṣyeṇa putrasya yauvarājyābhiṣecanam
prāṇāyāmena puruṣaṃ dhyāyamānā janārdanam', null, 2004033),
('ramayana-2-4-34', 34, 'Ayodhya Kanda, Sarga 4, Verse 34', 'तथा सनियमामेव सोऽभिगम्याभिवाद्य च।
उवाच वचनं रामो हर्षयंस्तामिदं तदा॥', 'tathā saniyamām eva so ''bhigamyābhivādya ca
uvāca vacanaṃ rāmo harṣayaṃs tām idaṃ tadā', null, 2004034),
('ramayana-2-4-35', 35, 'Ayodhya Kanda, Sarga 4, Verse 35', 'अम्ब पित्रा नियुक्तोऽस्मि प्रजापालनकर्मणि।
भविता श्वोऽभिषेको मे यथा मे शासनं पितुः॥', 'amba pitrā niyukto ''smi prajāpālanakarmaṇi
bhavitā śvo ''bhiṣeko me yathā me śāsanaṃ pituḥ', null, 2004035),
('ramayana-2-4-36', 36, 'Ayodhya Kanda, Sarga 4, Verse 36', 'सीतयाप्युपवस्तव्या रजनीयं मया सह।
एवमृत्विगुपाध्यायैः सह मामुक्तवान्पिता॥', 'sītayāpy upavastavyā rajanīyaṃ mayā saha
evam ṛtvigupādhyāyaiḥ saha mām uktavān pitā', null, 2004036),
('ramayana-2-4-37', 37, 'Ayodhya Kanda, Sarga 4, Verse 37', 'यानि यान्यत्र योग्यानि श्वोभाविन्यभिषेचने।
तानि मे मङ्गलान्यद्य वैदेह्याश्चैव कारय॥', 'yāni yāny atra yogyāni śvobhāviny abhiṣecane
tāni me maṅgalāny adya vaidehyāś caiva kāraya', null, 2004037),
('ramayana-2-4-38', 38, 'Ayodhya Kanda, Sarga 4, Verse 38', 'एतच्छ्रुत्वा तु कौसल्या चिरकालाभिकाङ्क्षितम्।
हर्षबाष्पकलं वाक्यमिदं राममभाषत॥', 'etac chrutvā tu kausalyā cirakālābhikāṅkṣitam
harṣabāṣpakalaṃ vākyam idaṃ rāmam abhāṣata', null, 2004038),
('ramayana-2-4-39', 39, 'Ayodhya Kanda, Sarga 4, Verse 39', 'वत्स राम चिरं जीव हतास्ते परिपन्थिनः।
ज्ञातीन्मे त्वं श्रिया युक्तः सुमित्रायाश्च नन्दय॥', 'vatsa rāma ciraṃ jīva hatās te paripanthinaḥ
jñātīn me tvaṃ śriyā yuktaḥ sumitrāyāś ca nandaya', null, 2004039),
('ramayana-2-4-40', 40, 'Ayodhya Kanda, Sarga 4, Verse 40', 'कल्याणे बत नक्षत्रे मयि जातोऽसि पुत्रक।
येन त्वया दशरथो गुणैराराधितः पिता॥', 'kalyāṇe bata nakṣatre mayi jāto ''si putraka
yena tvayā daśaratho guṇair ārādhitaḥ pitā', null, 2004040),
('ramayana-2-4-41', 41, 'Ayodhya Kanda, Sarga 4, Verse 41', 'अमोघं बत मे क्षान्तं पुरुषे पुष्करेक्षणे।
येयमिक्ष्वाकुराज्यश्रीः पुत्र त्वां संश्रयिष्यति॥', 'amoghaṃ bata me kṣāntaṃ puruṣe puṣkarekṣaṇe
yeyam ikṣvākurājyaśrīḥ putra tvāṃ saṃśrayiṣyati', null, 2004041),
('ramayana-2-4-42', 42, 'Ayodhya Kanda, Sarga 4, Verse 42', 'इत्येवमुक्तो मात्रेदं रामो भारतमब्रवीत्।
प्राञ्जलिं प्रह्वमासीनमभिवीक्ष्य स्मयन्निव॥', 'ity evam ukto mātredaṃ rāmo bhāratam abravīt
prāñjaliṃ prahvam āsīnam abhivīkṣya smayann iva', null, 2004042),
('ramayana-2-4-43', 43, 'Ayodhya Kanda, Sarga 4, Verse 43', 'लक्ष्मणेमां मया सार्धं प्रशाधि त्वं वसुंधराम्।
द्वितीयं मेऽन्तरात्मानं त्वामियं श्रीरुपस्थिता॥', 'lakṣmaṇemāṃ mayā sārdhaṃ praśādhi tvaṃ vasuṃdharām
dvitīyaṃ me ''ntarātmānaṃ tvām iyaṃ śrīr upasthitā', null, 2004043),
('ramayana-2-4-44', 44, 'Ayodhya Kanda, Sarga 4, Verse 44', 'सौमित्रे भुङ्क्ष्व भोगांस्त्वमिष्टान्राज्यफलानि च।
जीवितं च हि राज्यं च त्वदर्थमभिकामये॥', 'saumitre bhuṅkṣva bhogāṃs tvam iṣṭān rājyaphalāni ca
jīvitaṃ ca hi rājyaṃ ca tvadartham abhikāmaye', null, 2004044),
('ramayana-2-4-45', 45, 'Ayodhya Kanda, Sarga 4, Verse 45', 'इत्युक्त्वा लक्ष्मणं रामो मातरावभिवाद्य च।
अभ्यनुज्ञाप्य सीतां च जगाम स्वं निवेशनम्॥', 'ity uktvā lakṣmaṇaṃ rāmo mātarāv abhivādya ca
abhyanujñāpya sītāṃ ca jagāma svaṃ niveśanam', null, 2004045)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 5 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-5-1', 1, 'Ayodhya Kanda, Sarga 5, Verse 1', 'संदिश्य रामं नृपतिः श्वोभाविन्यभिषेचने।
पुरोहितं समाहूय वसिष्ठमिदमब्रवीत्॥', 'saṃdiśya rāmaṃ nṛpatiḥ śvobhāviny abhiṣecane
purohitaṃ samāhūya vasiṣṭham idam abravīt', null, 2005001),
('ramayana-2-5-2', 2, 'Ayodhya Kanda, Sarga 5, Verse 2', 'गच्छोपवासं काकुत्स्थं कारयाद्य तपोधन।
श्रीयशोराज्यलाभाय वध्वा सह यतव्रतम्॥', 'gacchopavāsaṃ kākutsthaṃ kārayādya tapodhana
śrīyaśorājyalābhāya vadhvā saha yatavratam', null, 2005002),
('ramayana-2-5-3', 3, 'Ayodhya Kanda, Sarga 5, Verse 3', 'तथेति च स राजानमुक्त्वा वेदविदां वरः।
स्वयं वसिष्ठो भगवान्ययौ रामनिवेशनम्॥', 'tatheti ca sa rājānam uktvā vedavidāṃ varaḥ
svayaṃ vasiṣṭho bhagavān yayau rāmaniveśanam', null, 2005003),
('ramayana-2-5-4', 4, 'Ayodhya Kanda, Sarga 5, Verse 4', 'स रामभवनं प्राप्य पाण्डुराभ्रघनप्रभम्।
तिस्रः कक्ष्या रथेनैव विवेश मुनिसत्तमः॥', 'sa rāmabhavanaṃ prāpya pāṇḍurābhraghanaprabham
tisraḥ kakṣyā rathenaiva viveśa munisattamaḥ', null, 2005004),
('ramayana-2-5-5', 5, 'Ayodhya Kanda, Sarga 5, Verse 5', 'तमागतमृषिं रामस्त्वरन्निव ससंभ्रमः।
मानयिष्यन्स मानार्हं निश्चक्राम निवेशनात्॥', 'tam āgatam ṛṣiṃ rāmas tvarann iva sasaṃbhramaḥ
mānayiṣyan sa mānārhaṃ niścakrāma niveśanāt', null, 2005005),
('ramayana-2-5-6', 6, 'Ayodhya Kanda, Sarga 5, Verse 6', 'अभ्येत्य त्वरमाणश्च रथाभ्याशं मनीषिणः।
ततोऽवतारयामास परिगृह्य रथात्स्वयम्॥', 'abhyetya tvaramāṇaś ca rathābhyāśaṃ manīṣiṇaḥ
tato ''vatārayām āsa parigṛhya rathāt svayam', null, 2005006),
('ramayana-2-5-7', 7, 'Ayodhya Kanda, Sarga 5, Verse 7', 'स चैनं प्रश्रितं दृष्ट्वा संभाष्याभिप्रसाद्य च।
प्रियार्हं हर्षयन्राममित्युवाच पुरोहितः॥', 'sa cainaṃ praśritaṃ dṛṣṭvā saṃbhāṣyābhiprasādya ca
priyārhaṃ harṣayan rāmam ity uvāca purohitaḥ', null, 2005007),
('ramayana-2-5-8', 8, 'Ayodhya Kanda, Sarga 5, Verse 8', 'प्रसन्नस्ते पिता राम यौवराज्यमवाप्स्यसि।
उपवासं भवानद्य करोतु सह सीतया॥', 'prasannas te pitā rāma yauvarājyam avāpsyasi
upavāsaṃ bhavān adya karotu saha sītayā', null, 2005008),
('ramayana-2-5-9', 9, 'Ayodhya Kanda, Sarga 5, Verse 9', 'प्रातस्त्वामभिषेक्ता हि यौवराज्ये नराधिपः।
पिता दशरथः प्रीत्या ययातिं नहुषो यथा॥', 'prātas tvām abhiṣektā hi yauvarājye narādhipaḥ
pitā daśarathaḥ prītyā yayātiṃ nahuṣo yathā', null, 2005009),
('ramayana-2-5-10', 10, 'Ayodhya Kanda, Sarga 5, Verse 10', 'इत्युक्त्वा स तदा राममुपवासं यतव्रतम्।
मन्त्रवत्कारयामास वैदेह्या सहितं मुनिः॥', 'ity uktvā sa tadā rāmam upavāsaṃ yatavratam
mantravat kārayām āsa vaidehyā sahitaṃ muniḥ', null, 2005010),
('ramayana-2-5-11', 11, 'Ayodhya Kanda, Sarga 5, Verse 11', 'ततो यथावद्रामेण स राज्ञो गुरुरर्चितः।
अभ्यनुज्ञाप्य काकुत्स्थं ययौ रामनिवेशनात्॥', 'tato yathāvad rāmeṇa sa rājño gurur arcitaḥ
abhyanujñāpya kākutsthaṃ yayau rāmaniveśanāt', null, 2005011),
('ramayana-2-5-12', 12, 'Ayodhya Kanda, Sarga 5, Verse 12', 'सुहृद्भिस्तत्र रामोऽपि ताननुज्ञाप्य सर्वशः।
सभाजितो विवेशाथ ताननुज्ञाप्य सर्वशः॥', 'suhṛdbhis tatra rāmo ''pi tān anujñāpya sarvaśaḥ
sabhājito viveśātha tān anujñāpya sarvaśaḥ', null, 2005012),
('ramayana-2-5-13', 13, 'Ayodhya Kanda, Sarga 5, Verse 13', 'हृष्टनारी नरयुतं रामवेश्म तदा बभौ।
यथा मत्तद्विजगणं प्रफुल्लनलिनं सरः॥', 'hṛṣṭanārī narayutaṃ rāmaveśma tadā babhau
yathā mattadvijagaṇaṃ praphullanalinaṃ saraḥ', null, 2005013),
('ramayana-2-5-14', 14, 'Ayodhya Kanda, Sarga 5, Verse 14', 'स राजभवनप्रख्यात्तस्माद्रामनिवेशनात्।
निर्गत्य ददृशे मार्गं वसिष्ठो जनसंवृतम्॥', 'sa rājabhavanaprakhyāt tasmād rāmaniveśanāt
nirgatya dadṛśe mārgaṃ vasiṣṭho janasaṃvṛtam', null, 2005014),
('ramayana-2-5-15', 15, 'Ayodhya Kanda, Sarga 5, Verse 15', 'वृन्दवृन्दैरयोध्यायां राजमार्गाः समन्ततः।
बभूवुरभिसंबाधाः कुतूहलजनैर्वृताः॥', 'vṛndavṛndair ayodhyāyāṃ rājamārgāḥ samantataḥ
babhūvur abhisaṃbādhāḥ kutūhalajanair vṛtāḥ', null, 2005015),
('ramayana-2-5-16', 16, 'Ayodhya Kanda, Sarga 5, Verse 16', 'जनवृन्दोर्मिसंघर्षहर्षस्वनवतस्तदा।
बभूव राजमार्गस्य सागरस्येव निस्वनः॥', 'janavṛndormisaṃgharṣaharṣasvanavatas tadā
babhūva rājamārgasya sāgarasyeva nisvanaḥ', null, 2005016),
('ramayana-2-5-17', 17, 'Ayodhya Kanda, Sarga 5, Verse 17', 'सिक्तसंमृष्टरथ्या हि तदहर्वनमालिनी।
आसीदयोध्या नगरी समुच्छ्रितगृहध्वजा॥', 'siktasaṃmṛṣṭarathyā hi tad ahar vanamālinī
āsīd ayodhyā nagarī samucchritagṛhadhvajā', null, 2005017),
('ramayana-2-5-18', 18, 'Ayodhya Kanda, Sarga 5, Verse 18', 'तदा ह्ययोध्या निलयः सस्त्रीबालाबलो जनः।
रामाभिषेकमाकाङ्क्षन्नाकाङ्क्षन्नुदयं रवेः॥', 'tadā hy ayodhyā nilayaḥ sastrībālābalo janaḥ
rāmābhiṣekam ākāṅkṣann ākāṅkṣann udayaṃ raveḥ', null, 2005018),
('ramayana-2-5-19', 19, 'Ayodhya Kanda, Sarga 5, Verse 19', 'प्रजालंकारभूतं च जनस्यानन्दवर्धनम्।
उत्सुकोऽभूज्जनो द्रष्टुं तमयोध्या महोत्सवम्॥', 'prajālaṃkārabhūtaṃ ca janasyānandavardhanam
utsuko ''bhūj jano draṣṭuṃ tam ayodhyā mahotsavam', null, 2005019),
('ramayana-2-5-20', 20, 'Ayodhya Kanda, Sarga 5, Verse 20', 'एवं तं जनसंबाधं राजमार्गं पुरोहितः।
व्यूहन्निव जनौघं तं शनै राज कुलं ययौ॥', 'evaṃ taṃ janasaṃbādhaṃ rājamārgaṃ purohitaḥ
vyūhann iva janaughaṃ taṃ śanai rāja kulaṃ yayau', null, 2005020),
('ramayana-2-5-21', 21, 'Ayodhya Kanda, Sarga 5, Verse 21', 'सिताभ्रशिखरप्रख्यं प्रासदमधिरुह्य सः।
समियाय नरेन्द्रेण शक्रेणेव बृहस्पतिः॥', 'sitābhraśikharaprakhyaṃ prāsadam adhiruhya saḥ
samiyāya narendreṇa śakreṇeva bṛhaspatiḥ', null, 2005021),
('ramayana-2-5-22', 22, 'Ayodhya Kanda, Sarga 5, Verse 22', 'तमागतमभिप्रेक्ष्य हित्वा राजासनं नृपः।
पप्रच्छ स च तस्मै तत्कृतमित्यभ्यवेदयत्॥', 'tam āgatam abhiprekṣya hitvā rājāsanaṃ nṛpaḥ
papraccha sa ca tasmai tat kṛtam ity abhyavedayat', null, 2005022),
('ramayana-2-5-23', 23, 'Ayodhya Kanda, Sarga 5, Verse 23', 'गुरुणा त्वभ्यनुज्ञातो मनुजौघं विसृज्य तम्।
विवेशान्तःपुरं राजा सिंहो गिरिगुहामिव॥', 'guruṇā tv abhyanujñāto manujaughaṃ visṛjya tam
viveśāntaḥpuraṃ rājā siṃho giriguhām iva', null, 2005023),
('ramayana-2-5-24', 24, 'Ayodhya Kanda, Sarga 5, Verse 24', 'तदग्र्यवेषप्रमदाजनाकुलं महेन्द्रवेश्मप्रतिमं निवेशनम्।
व्यदीपयंश्चारु विवेश पार्थिवः शशीव तारागणसंकुलं नभः॥', 'tad agryaveṣapramadājanākulaṃ mahendraveśmapratimaṃ niveśanam
vyadīpayaṃś cāru viveśa pārthivaḥ śaśīva tārāgaṇasaṃkulaṃ nabhaḥ', null, 2005024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 6 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-6-1', 1, 'Ayodhya Kanda, Sarga 6, Verse 1', 'गते पुरोहिते रामः स्नातो नियतमानसः।
सह पत्न्या विशालाक्ष्या नारायणमुपागमत्॥', 'gate purohite rāmaḥ snāto niyatamānasaḥ
saha patnyā viśālākṣyā nārāyaṇam upāgamat', null, 2006001),
('ramayana-2-6-2', 2, 'Ayodhya Kanda, Sarga 6, Verse 2', 'प्रगृह्य शिरसा पात्रीं हविषो विधिवत्तदा।
महते दैवतायाज्यं जुहाव ज्वलितेऽनले॥', 'pragṛhya śirasā pātrīṃ haviṣo vidhivat tadā
mahate daivatāyājyaṃ juhāva jvalite ''nale', null, 2006002),
('ramayana-2-6-3', 3, 'Ayodhya Kanda, Sarga 6, Verse 3', 'शेषं च हविषस्तस्य प्राश्याशास्यात्मनः प्रियम्।
ध्यायन्नारायणं देवं स्वास्तीर्णे कुशसंस्तरे॥', 'śeṣaṃ ca haviṣas tasya prāśyāśāsyātmanaḥ priyam
dhyāyan nārāyaṇaṃ devaṃ svāstīrṇe kuśasaṃstare', null, 2006003),
('ramayana-2-6-4', 4, 'Ayodhya Kanda, Sarga 6, Verse 4', 'वाग्यतः सह वैदेह्या भूत्वा नियतमानसः।
श्रीमत्यायतने विष्णोः शिश्ये नरवरात्मजः॥', 'vāgyataḥ saha vaidehyā bhūtvā niyatamānasaḥ
śrīmaty āyatane viṣṇoḥ śiśye naravarātmajaḥ', null, 2006004),
('ramayana-2-6-5', 5, 'Ayodhya Kanda, Sarga 6, Verse 5', 'एकयामावशिष्टायां रात्र्यां प्रतिविबुध्य सः।
अलंकारविधिं कृत्स्नं कारयामास वेश्मनः॥', 'ekayāmāvaśiṣṭāyāṃ rātryāṃ prativibudhya saḥ
alaṃkāravidhiṃ kṛtsnaṃ kārayām āsa veśmanaḥ', null, 2006005),
('ramayana-2-6-6', 6, 'Ayodhya Kanda, Sarga 6, Verse 6', 'तत्र शृण्वन्सुखा वाचः सूतमागधबन्दिनाम्।
पूर्वां संध्यामुपासीनो जजाप यतमानसः॥', 'tatra śṛṇvan sukhā vācaḥ sūtamāgadhabandinām
pūrvāṃ saṃdhyām upāsīno jajāpa yatamānasaḥ', null, 2006006),
('ramayana-2-6-7', 7, 'Ayodhya Kanda, Sarga 6, Verse 7', 'तुष्टाव प्रणतश्चैव शिरसा मधुसूदनम्।
विमलक्षौमसंवीतो वाचयामास च द्विजान्॥', 'tuṣṭāva praṇataś caiva śirasā madhusūdanam
vimalakṣaumasaṃvīto vācayām āsa ca dvijān', null, 2006007),
('ramayana-2-6-8', 8, 'Ayodhya Kanda, Sarga 6, Verse 8', 'तेषां पुण्याहघोषोऽथ गम्भीरमधुरस्तदा।
अयोध्यां पूरयामास तूर्यघोषानुनादितः॥', 'teṣāṃ puṇyāhaghoṣo ''tha gambhīramadhuras tadā
ayodhyāṃ pūrayām āsa tūryaghoṣānunāditaḥ', null, 2006008),
('ramayana-2-6-9', 9, 'Ayodhya Kanda, Sarga 6, Verse 9', 'कृतोपवासं तु तदा वैदेह्या सह राघवम्।
अयोध्या निलयः श्रुत्वा सर्वः प्रमुदितो जनः॥', 'kṛtopavāsaṃ tu tadā vaidehyā saha rāghavam
ayodhyā nilayaḥ śrutvā sarvaḥ pramudito janaḥ', null, 2006009),
('ramayana-2-6-10', 10, 'Ayodhya Kanda, Sarga 6, Verse 10', 'ततः पौरजनः सर्वः श्रुत्वा रामाभिषेचनम्।
प्रभातां रजनीं दृष्ट्वा चक्रे शोभां परां पुनः॥', 'tataḥ paurajanaḥ sarvaḥ śrutvā rāmābhiṣecanam
prabhātāṃ rajanīṃ dṛṣṭvā cakre śobhāṃ parāṃ punaḥ', null, 2006010),
('ramayana-2-6-11', 11, 'Ayodhya Kanda, Sarga 6, Verse 11', 'सिताभ्रशिखराभेषु देवतायतनेषु च।
चतुष्पथेषु रथ्यासु चैत्येष्वट्टालकेषु च॥', 'sitābhraśikharābheṣu devatāyataneṣu ca
catuṣpatheṣu rathyāsu caityeṣv aṭṭālakeṣu ca', null, 2006011),
('ramayana-2-6-12', 12, 'Ayodhya Kanda, Sarga 6, Verse 12', 'नानापण्यसमृद्धेषु वणिजामापणेषु च।
कुटुम्बिनां समृद्धेषु श्रीमत्सु भवनेषु च॥', 'nānāpaṇyasamṛddheṣu vaṇijām āpaṇeṣu ca
kuṭumbināṃ samṛddheṣu śrīmatsu bhavaneṣu ca', null, 2006012),
('ramayana-2-6-13', 13, 'Ayodhya Kanda, Sarga 6, Verse 13', 'सभासु चैव सर्वासु वृक्षेष्वालक्षितेषु च।
ध्वजाः समुच्छ्रिताश्चित्राः पताकाश्चाभवंस्तदा॥', 'sabhāsu caiva sarvāsu vṛkṣeṣv ālakṣiteṣu ca
dhvajāḥ samucchritāś citrāḥ patākāś cābhavaṃs tadā', null, 2006013),
('ramayana-2-6-14', 14, 'Ayodhya Kanda, Sarga 6, Verse 14', 'नटनर्तकसंघानां गायकानां च गायताम्।
मनःकर्णसुखा वाचः शुश्रुवुश्च ततस्ततः॥', 'naṭanartakasaṃghānāṃ gāyakānāṃ ca gāyatām
manaḥkarṇasukhā vācaḥ śuśruvuś ca tatas tataḥ', null, 2006014),
('ramayana-2-6-15', 15, 'Ayodhya Kanda, Sarga 6, Verse 15', 'रामाभिषेकयुक्ताश्च कथाश्चक्रुर्मिथो जनाः।
रामाभिषेके संप्राप्ते चत्वरेषु गृहेषु च॥', 'rāmābhiṣekayuktāś ca kathāś cakrur mitho janāḥ
rāmābhiṣeke saṃprāpte catvareṣu gṛheṣu ca', null, 2006015),
('ramayana-2-6-16', 16, 'Ayodhya Kanda, Sarga 6, Verse 16', 'बाला अपि क्रीडमाना गृहद्वारेषु संघशः।
रामाभिषेकसंयुक्ताश्चक्रुरेव मिथः कथाः॥', 'bālā api krīḍamānā gṛhadvāreṣu saṃghaśaḥ
rāmābhiṣekasaṃyuktāś cakrur eva mithaḥ kathāḥ', null, 2006016),
('ramayana-2-6-17', 17, 'Ayodhya Kanda, Sarga 6, Verse 17', 'कृतपुष्पोपहारश्च धूपगन्धाधिवासितः।
राजमार्गः कृतः श्रीमान्पौरै रामाभिषेचने॥', 'kṛtapuṣpopahāraś ca dhūpagandhādhivāsitaḥ
rājamārgaḥ kṛtaḥ śrīmān paurai rāmābhiṣecane', null, 2006017),
('ramayana-2-6-18', 18, 'Ayodhya Kanda, Sarga 6, Verse 18', 'प्रकाशीकरणार्थं च निशागमनशङ्कया।
दीपवृक्षांस्तथा चक्रुरनु रथ्यासु सर्वशः॥', 'prakāśīkaraṇārthaṃ ca niśāgamanaśaṅkayā
dīpavṛkṣāṃs tathā cakrur anu rathyāsu sarvaśaḥ', null, 2006018),
('ramayana-2-6-19', 19, 'Ayodhya Kanda, Sarga 6, Verse 19', 'अलंकारं पुरस्यैवं कृत्वा तत्पुरवासिनः।
आकाङ्क्षमाणा रामस्य यौवराज्याभिषेचनम्॥', 'alaṃkāraṃ purasyaivaṃ kṛtvā tat puravāsinaḥ
ākāṅkṣamāṇā rāmasya yauvarājyābhiṣecanam', null, 2006019),
('ramayana-2-6-20', 20, 'Ayodhya Kanda, Sarga 6, Verse 20', 'समेत्य संघशः सर्वे चत्वरेषु सभासु च।
कथयन्तो मिथस्तत्र प्रशशंसुर्जनाधिपम्॥', 'sametya saṃghaśaḥ sarve catvareṣu sabhāsu ca
kathayanto mithas tatra praśaśaṃsur janādhipam', null, 2006020),
('ramayana-2-6-21', 21, 'Ayodhya Kanda, Sarga 6, Verse 21', 'अहो महात्मा राजायमिक्ष्वाकुकुलनन्दनः।
ज्ञात्वा यो वृद्धमात्मानं रामं राज्येऽभिषेक्ष्यति॥', 'aho mahātmā rājāyam ikṣvākukulanandanaḥ
jñātvā yo vṛddham ātmānaṃ rāmaṃ rājye ''bhiṣekṣyati', null, 2006021),
('ramayana-2-6-22', 22, 'Ayodhya Kanda, Sarga 6, Verse 22', 'सर्वे ह्यनुगृहीताः स्म यन्नो रामो महीपतिः।
चिराय भविता गोप्ता दृष्टलोकपरावरः॥', 'sarve hy anugṛhītāḥ sma yan no rāmo mahīpatiḥ
cirāya bhavitā goptā dṛṣṭalokaparāvaraḥ', null, 2006022),
('ramayana-2-6-23', 23, 'Ayodhya Kanda, Sarga 6, Verse 23', 'अनुद्धतमना विद्वान्धर्मात्मा भ्रातृवत्सलः।
यथा च भ्रातृषु स्निग्धस्तथास्मास्वपि राघवः॥', 'anuddhatamanā vidvān dharmātmā bhrātṛvatsalaḥ
yathā ca bhrātṛṣu snigdhas tathāsmāsv api rāghavaḥ', null, 2006023),
('ramayana-2-6-24', 24, 'Ayodhya Kanda, Sarga 6, Verse 24', 'चिरं जीवतु धर्मात्मा राजा दशरथोऽनघः।
यत्प्रसादेनाभिषिक्तं रामं द्रक्ष्यामहे वयम्॥', 'ciraṃ jīvatu dharmātmā rājā daśaratho ''naghaḥ
yatprasādenābhiṣiktaṃ rāmaṃ drakṣyāmahe vayam', null, 2006024),
('ramayana-2-6-25', 25, 'Ayodhya Kanda, Sarga 6, Verse 25', 'एवंविधं कथयतां पौराणां शुश्रुवुस्तदा।
दिग्भ्योऽपि श्रुतवृत्तान्ताः प्राप्ता जानपदा जनाः॥', 'evaṃvidhaṃ kathayatāṃ paurāṇāṃ śuśruvus tadā
digbhyo ''pi śrutavṛttāntāḥ prāptā jānapadā janāḥ', null, 2006025),
('ramayana-2-6-26', 26, 'Ayodhya Kanda, Sarga 6, Verse 26', 'ते तु दिग्भ्यः पुरीं प्राप्ता द्रष्टुं रामाभिषेचनम्।
रामस्य पूरयामासुः पुरीं जानपदा जनाः॥', 'te tu digbhyaḥ purīṃ prāptā draṣṭuṃ rāmābhiṣecanam
rāmasya pūrayām āsuḥ purīṃ jānapadā janāḥ', null, 2006026),
('ramayana-2-6-27', 27, 'Ayodhya Kanda, Sarga 6, Verse 27', 'जनौघैस्तैर्विसर्पद्भिः शुश्रुवे तत्र निःस्वनः।
पर्वसूदीर्णवेगस्य सागरस्येव निःस्वनः॥', 'janaughais tair visarpadbhiḥ śuśruve tatra niḥsvanaḥ
parvasūdīrṇavegasya sāgarasyeva niḥsvanaḥ', null, 2006027),
('ramayana-2-6-28', 28, 'Ayodhya Kanda, Sarga 6, Verse 28', 'ततस्तदिन्द्रक्षयसंनिभं पुरं दिदृक्षुभिर्जानपदैरुपागतैः।
समन्ततः सस्वनमाकुलं बभौ समुद्रयादोभिरिवार्णवोदकम्॥', 'tatas tad indrakṣayasaṃnibhaṃ puraṃ didṛkṣubhir jānapadair upāgataiḥ
samantataḥ sasvanam ākulaṃ babhau samudrayādobhir ivārṇavodakam', null, 2006028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 7 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-7-1', 1, 'Ayodhya Kanda, Sarga 7, Verse 1', 'ज्ञातिदासी यतो जाता कैकेय्यास्तु सहोषिता।
प्रासादं चन्द्रसंकाशमारुरोह यदृच्छया॥', 'jñātidāsī yato jātā kaikeyyās tu sahoṣitā
prāsādaṃ candrasaṃkāśam āruroha yadṛcchayā', null, 2007001),
('ramayana-2-7-2', 2, 'Ayodhya Kanda, Sarga 7, Verse 2', 'सिक्तराजपथां कृत्स्नां प्रकीर्णकमलोत्पलाम्।
अयोध्यां मन्थरा तस्मात्प्रासादादन्ववैक्षत॥', 'siktarājapathāṃ kṛtsnāṃ prakīrṇakamalotpalām
ayodhyāṃ mantharā tasmāt prāsādād anvavaikṣata', null, 2007002),
('ramayana-2-7-3', 3, 'Ayodhya Kanda, Sarga 7, Verse 3', 'पताकाभिर्वरार्हाभिर्ध्वजैश्च समलंकृताम्।
सिक्तां चन्दनतोयैश्च शिरःस्नातजनैर्वृताम्॥', 'patākābhir varārhābhir dhvajaiś ca samalaṃkṛtām
siktāṃ candanatoyaiś ca śiraḥsnātajanair vṛtām', null, 2007003),
('ramayana-2-7-4', 4, 'Ayodhya Kanda, Sarga 7, Verse 4', 'अविदूरे स्थितां दृष्ट्वा धात्रीं पप्रच्छ मन्थरा।
उत्तमेनाभिसंयुक्ता हर्षेणार्थपरा सती॥', 'avidūre sthitāṃ dṛṣṭvā dhātrīṃ papraccha mantharā
uttamenābhisaṃyuktā harṣeṇārthaparā satī', null, 2007004),
('ramayana-2-7-5', 5, 'Ayodhya Kanda, Sarga 7, Verse 5', 'राममाता धनं किं नु जनेभ्यः संप्रयच्छति।
अतिमात्रं प्रहर्षोऽयं किं जनस्य च शंस मे।
कारयिष्यति किं वापि संप्रहृष्टो महीपतिः॥', 'rāmamātā dhanaṃ kiṃ nu janebhyaḥ saṃprayacchati
atimātraṃ praharṣo ''yaṃ kiṃ janasya ca śaṃsa me
kārayiṣyati kiṃ vāpi saṃprahṛṣṭo mahīpatiḥ', null, 2007005),
('ramayana-2-7-6', 6, 'Ayodhya Kanda, Sarga 7, Verse 6', 'विदीर्यमाणा हर्षेण धात्री परमया मुदा।
आचचक्षेऽथ कुब्जायै भूयसीं राघवे श्रियम्॥', 'vidīryamāṇā harṣeṇa dhātrī paramayā mudā
ācacakṣe ''tha kubjāyai bhūyasīṃ rāghave śriyam', null, 2007006),
('ramayana-2-7-7', 7, 'Ayodhya Kanda, Sarga 7, Verse 7', 'श्वः पुष्येण जितक्रोधं यौवराज्येन राघवम्।
राजा दशरथो राममभिषेचयितानघम्॥', 'śvaḥ puṣyeṇa jitakrodhaṃ yauvarājyena rāghavam
rājā daśaratho rāmam abhiṣecayitānagham', null, 2007007),
('ramayana-2-7-8', 8, 'Ayodhya Kanda, Sarga 7, Verse 8', 'धात्र्यास्तु वचनं श्रुत्वा कुब्जा क्षिप्रममर्षिता।
कैलास शिखराकारात्प्रासादादवरोहत॥', 'dhātryās tu vacanaṃ śrutvā kubjā kṣipram amarṣitā
kailāsa śikharākārāt prāsādād avarohata', null, 2007008),
('ramayana-2-7-9', 9, 'Ayodhya Kanda, Sarga 7, Verse 9', 'सा दह्यमाना कोपेन मन्थरा पापदर्शिनी।
शयानामेत्य कैकेयीमिदं वचनमब्रवीत्॥', 'sā dahyamānā kopena mantharā pāpadarśinī
śayānām etya kaikeyīm idaṃ vacanam abravīt', null, 2007009),
('ramayana-2-7-10', 10, 'Ayodhya Kanda, Sarga 7, Verse 10', 'उत्तिष्ठ मूढे किं शेषे भयं त्वामभिवर्तते।
उपप्लुतमहौघेन किमात्मानं न बुध्यसे॥', 'uttiṣṭha mūḍhe kiṃ śeṣe bhayaṃ tvām abhivartate
upaplutamahaughena kim ātmānaṃ na budhyase', null, 2007010),
('ramayana-2-7-11', 11, 'Ayodhya Kanda, Sarga 7, Verse 11', 'अनिष्टे सुभगाकारे सौभाग्येन विकत्थसे।
चलं हि तव सौभाग्यं नद्यः स्रोत इवोष्णगे॥', 'aniṣṭe subhagākāre saubhāgyena vikatthase
calaṃ hi tava saubhāgyaṃ nadyaḥ srota ivoṣṇage', null, 2007011),
('ramayana-2-7-12', 12, 'Ayodhya Kanda, Sarga 7, Verse 12', 'एवमुक्ता तु कैकेयी रुष्टया परुषं वचः।
कुब्जया पापदर्शिन्या विषादमगमत्परम्॥', 'evam uktā tu kaikeyī ruṣṭayā paruṣaṃ vacaḥ
kubjayā pāpadarśinyā viṣādam agamat param', null, 2007012),
('ramayana-2-7-13', 13, 'Ayodhya Kanda, Sarga 7, Verse 13', 'कैकेयी त्वब्रवीत्कुब्जां कच्चित्क्षेमं न मन्थरे।
विषण्णवदनां हि त्वां लक्षये भृशदुःखिताम्॥', 'kaikeyī tv abravīt kubjāṃ kaccit kṣemaṃ na manthare
viṣaṇṇavadanāṃ hi tvāṃ lakṣaye bhṛśaduḥkhitām', null, 2007013),
('ramayana-2-7-14', 14, 'Ayodhya Kanda, Sarga 7, Verse 14', 'मन्थरा तु वचः श्रुत्वा कैकेय्या मधुराक्षरम्।
उवाच क्रोधसंयुक्ता वाक्यं वाक्यविशारदा॥', 'mantharā tu vacaḥ śrutvā kaikeyyā madhurākṣaram
uvāca krodhasaṃyuktā vākyaṃ vākyaviśāradā', null, 2007014),
('ramayana-2-7-15', 15, 'Ayodhya Kanda, Sarga 7, Verse 15', 'सा विषण्णतरा भूत्वा कुब्जा तस्या हितैषिणी।
विषादयन्ती प्रोवाच भेदयन्ती च राघवम्॥', 'sā viṣaṇṇatarā bhūtvā kubjā tasyā hitaiṣiṇī
viṣādayantī provāca bhedayantī ca rāghavam', null, 2007015),
('ramayana-2-7-16', 16, 'Ayodhya Kanda, Sarga 7, Verse 16', 'अक्षेमं सुमहद्देवि प्रवृत्तं त्वद्विनाशनम्।
रामं दशरथो राजा यौवराज्येऽभिषेक्ष्यति॥', 'akṣemaṃ sumahad devi pravṛttaṃ tvadvināśanam
rāmaṃ daśaratho rājā yauvarājye ''bhiṣekṣyati', null, 2007016),
('ramayana-2-7-17', 17, 'Ayodhya Kanda, Sarga 7, Verse 17', 'सास्म्यगाधे भये मग्ना दुःखशोकसमन्विता।
दह्यमानानलेनेव त्वद्धितार्थमिहागता॥', 'sāsmy agādhe bhaye magnā duḥkhaśokasamanvitā
dahyamānānaleneva tvaddhitārtham ihāgatā', null, 2007017),
('ramayana-2-7-18', 18, 'Ayodhya Kanda, Sarga 7, Verse 18', 'तव दुःखेन कैकेयि मम दुःखं महद्भवेत्।
त्वद्वृद्धौ मम वृद्धिश्च भवेदत्र न संशयः॥', 'tava duḥkhena kaikeyi mama duḥkhaṃ mahad bhavet
tvadvṛddhau mama vṛddhiś ca bhaved atra na saṃśayaḥ', null, 2007018),
('ramayana-2-7-19', 19, 'Ayodhya Kanda, Sarga 7, Verse 19', 'नराधिपकुले जाता महिषी त्वं महीपतेः।
उग्रत्वं राजधर्माणां कथं देवि न बुध्यसे॥', 'narādhipakule jātā mahiṣī tvaṃ mahīpateḥ
ugratvaṃ rājadharmāṇāṃ kathaṃ devi na budhyase', null, 2007019),
('ramayana-2-7-20', 20, 'Ayodhya Kanda, Sarga 7, Verse 20', 'धर्मवादी शठो भर्ता श्लक्ष्णवादी च दारुणः।
शुद्धभावे न जानीषे तेनैवमतिसंधिता॥', 'dharmavādī śaṭho bhartā ślakṣṇavādī ca dāruṇaḥ
śuddhabhāve na jānīṣe tenaivam atisaṃdhitā', null, 2007020),
('ramayana-2-7-21', 21, 'Ayodhya Kanda, Sarga 7, Verse 21', 'उपस्थितं प्रयुञ्जानस्त्वयि सान्त्वमनर्थकम्।
अर्थेनैवाद्य ते भर्ता कौसल्यां योजयिष्यति॥', 'upasthitaṃ prayuñjānas tvayi sāntvam anarthakam
arthenaivādya te bhartā kausalyāṃ yojayiṣyati', null, 2007021),
('ramayana-2-7-22', 22, 'Ayodhya Kanda, Sarga 7, Verse 22', 'अपवाह्य स दुष्टात्मा भरतं तव बन्धुषु।
काल्यं स्थापयिता रामं राज्ये निहतकण्टके॥', 'apavāhya sa duṣṭātmā bharataṃ tava bandhuṣu
kālyaṃ sthāpayitā rāmaṃ rājye nihatakaṇṭake', null, 2007022),
('ramayana-2-7-23', 23, 'Ayodhya Kanda, Sarga 7, Verse 23', 'शत्रुः पतिप्रवादेन मात्रेव हितकाम्यया।
आशीविष इवाङ्केन बाले परिधृतस्त्वया॥', 'śatruḥ patipravādena mātreva hitakāmyayā
āśīviṣa ivāṅkena bāle paridhṛtas tvayā', null, 2007023),
('ramayana-2-7-24', 24, 'Ayodhya Kanda, Sarga 7, Verse 24', 'यथा हि कुर्यात्सर्पो वा शत्रुर्वा प्रत्युपेक्षितः।
राज्ञा दशरथेनाद्य सपुत्रा त्वं तथा कृता॥', 'yathā hi kuryāt sarpo vā śatrur vā pratyupekṣitaḥ
rājñā daśarathenādya saputrā tvaṃ tathā kṛtā', null, 2007024),
('ramayana-2-7-25', 25, 'Ayodhya Kanda, Sarga 7, Verse 25', 'पापेनानृतसान्त्वेन बाले नित्यं सुखोचिते।
रामं स्थापयता राज्ये सानुबन्धा हता ह्यसि॥', 'pāpenānṛtasāntvena bāle nityaṃ sukhocite
rāmaṃ sthāpayatā rājye sānubandhā hatā hy asi', null, 2007025),
('ramayana-2-7-26', 26, 'Ayodhya Kanda, Sarga 7, Verse 26', 'सा प्राप्तकालं कैकेयि क्षिप्रं कुरु हितं तव।
त्रायस्व पुत्रमात्मानं मां च विस्मयदर्शने॥', 'sā prāptakālaṃ kaikeyi kṣipraṃ kuru hitaṃ tava
trāyasva putram ātmānaṃ māṃ ca vismayadarśane', null, 2007026),
('ramayana-2-7-27', 27, 'Ayodhya Kanda, Sarga 7, Verse 27', 'मन्थराया वचः श्रुत्वा शयनात्सा शुभानना।
एकमाभरणं तस्यै कुब्जायै प्रददौ शुभम्॥', 'mantharāyā vacaḥ śrutvā śayanāt sā śubhānanā
ekam ābharaṇaṃ tasyai kubjāyai pradadau śubham', null, 2007027),
('ramayana-2-7-28', 28, 'Ayodhya Kanda, Sarga 7, Verse 28', 'दत्त्वा त्वाभरणं तस्यै कुब्जायै प्रमदोत्तमा।
कैकेयी मन्थरां हृष्टा पुनरेवाब्रवीदिदम्॥', 'dattvā tv ābharaṇaṃ tasyai kubjāyai pramadottamā
kaikeyī mantharāṃ hṛṣṭā punar evābravīd idam', null, 2007028),
('ramayana-2-7-29', 29, 'Ayodhya Kanda, Sarga 7, Verse 29', 'इदं तु मन्थरे मह्यमाख्यासि परमं प्रियम्।
एतन्मे प्रियमाख्यातुः किं वा भूयः करोमि ते॥', 'idaṃ tu manthare mahyam ākhyāsi paramaṃ priyam
etan me priyam ākhyātuḥ kiṃ vā bhūyaḥ karomi te', null, 2007029),
('ramayana-2-7-30', 30, 'Ayodhya Kanda, Sarga 7, Verse 30', 'रामे वा भरते वाहं विशेषं नोपलक्षये।
तस्मात्तुष्टास्मि यद्राजा रामं राज्येऽभिषेक्ष्यति॥', 'rāme vā bharate vāhaṃ viśeṣaṃ nopalakṣaye
tasmāt tuṣṭāsmi yad rājā rāmaṃ rājye ''bhiṣekṣyati', null, 2007030),
('ramayana-2-7-31', 31, 'Ayodhya Kanda, Sarga 7, Verse 31', 'न मे परं किं चिदितस्त्वया पुनः प्रियं प्रियार्हे सुवचं वचो वरम्।
तथा ह्यवोचस्त्वमतः प्रियोत्तरं वरं परं ते प्रददामि तं वृणु॥', 'na me paraṃ kiṃ cid itas tvayā punaḥ priyaṃ priyārhe suvacaṃ vaco varam
tathā hy avocas tvam ataḥ priyottaraṃ varaṃ paraṃ te pradadāmi taṃ vṛṇu', null, 2007031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 8 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-8-1', 1, 'Ayodhya Kanda, Sarga 8, Verse 1', 'मन्थरा त्वभ्यसूय्यैनामुत्सृज्याभरणं च तत्।
उवाचेदं ततो वाक्यं कोपदुःखसमन्विता॥', 'mantharā tv abhyasūyyainām utsṛjyābharaṇaṃ ca tat
uvācedaṃ tato vākyaṃ kopaduḥkhasamanvitā', null, 2008001),
('ramayana-2-8-2', 2, 'Ayodhya Kanda, Sarga 8, Verse 2', 'हर्षं किमिदमस्थाने कृतवत्यसि बालिशे।
शोकसागरमध्यस्थमात्मानं नावबुध्यसे॥', 'harṣaṃ kim idam asthāne kṛtavaty asi bāliśe
śokasāgaramadhyastham ātmānaṃ nāvabudhyase', null, 2008002),
('ramayana-2-8-3', 3, 'Ayodhya Kanda, Sarga 8, Verse 3', 'सुभगा खलु कौसल्या यस्याः पुत्रोऽभिषेक्ष्यते।
यौवराज्येन महता श्वः पुष्येण द्विजोत्तमैः॥', 'subhagā khalu kausalyā yasyāḥ putro ''bhiṣekṣyate
yauvarājyena mahatā śvaḥ puṣyeṇa dvijottamaiḥ', null, 2008003),
('ramayana-2-8-4', 4, 'Ayodhya Kanda, Sarga 8, Verse 4', 'प्राप्तां सुमहतीं प्रीतिं प्रतीतां तां हतद्विषम्।
उपस्थास्यसि कौसल्यां दासीव त्वं कृताञ्जलिः॥', 'prāptāṃ sumahatīṃ prītiṃ pratītāṃ tāṃ hatadviṣam
upasthāsyasi kausalyāṃ dāsīva tvaṃ kṛtāñjaliḥ', null, 2008004),
('ramayana-2-8-5', 5, 'Ayodhya Kanda, Sarga 8, Verse 5', 'हृष्टाः खलु भविष्यन्ति रामस्य परमाः स्त्रियः।
अप्रहृष्टा भविष्यन्ति स्नुषास्ते भरतक्षये॥', 'hṛṣṭāḥ khalu bhaviṣyanti rāmasya paramāḥ striyaḥ
aprahṛṣṭā bhaviṣyanti snuṣās te bharatakṣaye', null, 2008005),
('ramayana-2-8-6', 6, 'Ayodhya Kanda, Sarga 8, Verse 6', 'तां दृष्ट्वा परमप्रीतां ब्रुवन्तीं मन्थरां ततः।
रामस्यैव गुणान्देवी कैकेयी प्रशशंस ह॥', 'tāṃ dṛṣṭvā paramaprītāṃ bruvantīṃ mantharāṃ tataḥ
rāmasyaiva guṇān devī kaikeyī praśaśaṃsa ha', null, 2008006),
('ramayana-2-8-7', 7, 'Ayodhya Kanda, Sarga 8, Verse 7', 'धर्मज्ञो गुरुभिर्दान्तः कृतज्ञः सत्यवाक्शुचिः।
रामो राज्ञः सुतो ज्येष्ठो यौवराज्यमतोऽर्हति॥', 'dharmajño gurubhir dāntaḥ kṛtajñaḥ satyavāk śuciḥ
rāmo rājñaḥ suto jyeṣṭho yauvarājyam ato ''rhati', null, 2008007),
('ramayana-2-8-8', 8, 'Ayodhya Kanda, Sarga 8, Verse 8', 'भ्रातॄन्भृत्यांश्च दीर्घायुः पितृवत्पालयिष्यति।
संतप्यसे कथं कुब्जे श्रुत्वा रामाभिषेचनम्॥', 'bhrātṝn bhṛtyāṃś ca dīrghāyuḥ pitṛvat pālayiṣyati
saṃtapyase kathaṃ kubje śrutvā rāmābhiṣecanam', null, 2008008),
('ramayana-2-8-9', 9, 'Ayodhya Kanda, Sarga 8, Verse 9', 'भरतश्चापि रामस्य ध्रुवं वर्षशतात्परम्।
पितृपैतामहं राज्यमवाप्स्यति नरर्षभः॥', 'bharataś cāpi rāmasya dhruvaṃ varṣaśatāt param
pitṛpaitāmahaṃ rājyam avāpsyati nararṣabhaḥ', null, 2008009),
('ramayana-2-8-10', 10, 'Ayodhya Kanda, Sarga 8, Verse 10', 'सा त्वमभ्युदये प्राप्ते वर्तमाने च मन्थरे।
भविष्यति च कल्याणे किमर्थं परितप्यसे।
कौसल्यातोऽतिरिक्तं च स तु शुश्रूषते हि माम्॥', 'sā tvam abhyudaye prāpte vartamāne ca manthare
bhaviṣyati ca kalyāṇe kimarthaṃ paritapyase
kausalyāto ''tiriktaṃ ca sa tu śuśrūṣate hi mām', null, 2008010),
('ramayana-2-8-11', 11, 'Ayodhya Kanda, Sarga 8, Verse 11', 'कैकेय्या वचनं श्रुत्वा मन्थरा भृशदुःखिता।
दीर्घमुष्णं विनिःश्वस्य कैकेयीमिदमब्रवीत्॥', 'kaikeyyā vacanaṃ śrutvā mantharā bhṛśaduḥkhitā
dīrgham uṣṇaṃ viniḥśvasya kaikeyīm idam abravīt', null, 2008011),
('ramayana-2-8-12', 12, 'Ayodhya Kanda, Sarga 8, Verse 12', 'अनर्थदर्शिनी मौर्ख्यान्नात्मानमवबुध्यसे।
शोकव्यसनविस्तीर्णे मज्जन्ती दुःखसागरे॥', 'anarthadarśinī maurkhyān nātmānam avabudhyase
śokavyasanavistīrṇe majjantī duḥkhasāgare', null, 2008012),
('ramayana-2-8-13', 13, 'Ayodhya Kanda, Sarga 8, Verse 13', 'भविता राघवो राजा राघवस्य च यः सुतः।
राजवंशात्तु भरतः कैकेयि परिहास्यते॥', 'bhavitā rāghavo rājā rāghavasya ca yaḥ sutaḥ
rājavaṃśāt tu bharataḥ kaikeyi parihāsyate', null, 2008013),
('ramayana-2-8-14', 14, 'Ayodhya Kanda, Sarga 8, Verse 14', 'न हि राज्ञः सुताः सर्वे राज्ये तिष्ठन्ति भामिनि।
स्थाप्यमानेषु सर्वेषु सुमहाननयो भवेत्॥', 'na hi rājñaḥ sutāḥ sarve rājye tiṣṭhanti bhāmini
sthāpyamāneṣu sarveṣu sumahān anayo bhavet', null, 2008014),
('ramayana-2-8-15', 15, 'Ayodhya Kanda, Sarga 8, Verse 15', 'तस्माज्ज्येष्ठे हि कैकेयि राज्यतन्त्राणि पार्थिवाः।
स्थापयन्त्यनवद्याङ्गि गुणवत्स्वितरेष्वपि॥', 'tasmāj jyeṣṭhe hi kaikeyi rājyatantrāṇi pārthivāḥ
sthāpayanty anavadyāṅgi guṇavatsv itareṣv api', null, 2008015),
('ramayana-2-8-16', 16, 'Ayodhya Kanda, Sarga 8, Verse 16', 'असावत्यन्तनिर्भग्नस्तव पुत्रो भविष्यति।
अनाथवत्सुखेभ्यश्च राजवंशाच्च वत्सले॥', 'asāv atyantanirbhagnas tava putro bhaviṣyati
anāthavat sukhebhyaś ca rājavaṃśāc ca vatsale', null, 2008016),
('ramayana-2-8-17', 17, 'Ayodhya Kanda, Sarga 8, Verse 17', 'साहं त्वदर्थे संप्राप्ता त्वं तु मां नावबुध्यसे।
सपत्निवृद्धौ या मे त्वं प्रदेयं दातुमिच्छसि॥', 'sāhaṃ tvadarthe saṃprāptā tvaṃ tu māṃ nāvabudhyase
sapatnivṛddhau yā me tvaṃ pradeyaṃ dātum icchasi', null, 2008017),
('ramayana-2-8-18', 18, 'Ayodhya Kanda, Sarga 8, Verse 18', 'ध्रुवं तु भरतं रामः प्राप्य राज्यमकण्टकम्।
देशान्तरं नाययिता लोकान्तरमथापि वा॥', 'dhruvaṃ tu bharataṃ rāmaḥ prāpya rājyam akaṇṭakam
deśāntaraṃ nāyayitā lokāntaram athāpi vā', null, 2008018),
('ramayana-2-8-19', 19, 'Ayodhya Kanda, Sarga 8, Verse 19', 'बाल एव हि मातुल्यं भरतो नायितस्त्वया।
संनिकर्षाच्च सौहार्दं जायते स्थावरेष्वपि॥', 'bāla eva hi mātulyaṃ bharato nāyitas tvayā
saṃnikarṣāc ca sauhārdaṃ jāyate sthāvareṣv api', null, 2008019),
('ramayana-2-8-20', 20, 'Ayodhya Kanda, Sarga 8, Verse 20', 'गोप्ता हि रामं सौमित्रिर्लक्ष्मणं चापि राघवः।
अश्विनोरिव सौभ्रात्रं तयोर्लोकेषु विश्रुतम्॥', 'goptā hi rāmaṃ saumitrir lakṣmaṇaṃ cāpi rāghavaḥ
aśvinor iva saubhrātraṃ tayor lokeṣu viśrutam', null, 2008020),
('ramayana-2-8-21', 21, 'Ayodhya Kanda, Sarga 8, Verse 21', 'तस्मान्न लक्ष्मणे रामः पापं किं चित्करिष्यति।
रामस्तु भरते पापं कुर्यादिति न संशयः॥', 'tasmān na lakṣmaṇe rāmaḥ pāpaṃ kiṃ cit kariṣyati
rāmas tu bharate pāpaṃ kuryād iti na saṃśayaḥ', null, 2008021),
('ramayana-2-8-22', 22, 'Ayodhya Kanda, Sarga 8, Verse 22', 'तस्माद्राजगृहादेव वनं गच्छतु ते सुतः।
एतद्धि रोचते मह्यं भृशं चापि हितं तव॥', 'tasmād rājagṛhād eva vanaṃ gacchatu te sutaḥ
etad dhi rocate mahyaṃ bhṛśaṃ cāpi hitaṃ tava', null, 2008022),
('ramayana-2-8-23', 23, 'Ayodhya Kanda, Sarga 8, Verse 23', 'एवं ते ज्ञातिपक्षस्य श्रेयश्चैव भविष्यति।
यदि चेद्भरतो धर्मात्पित्र्यं राज्यमवाप्स्यति॥', 'evaṃ te jñātipakṣasya śreyaś caiva bhaviṣyati
yadi ced bharato dharmāt pitryaṃ rājyam avāpsyati', null, 2008023),
('ramayana-2-8-24', 24, 'Ayodhya Kanda, Sarga 8, Verse 24', 'स ते सुखोचितो बालो रामस्य सहजो रिपुः।
समृद्धार्थस्य नष्टार्थो जीविष्यति कथं वशे॥', 'sa te sukhocito bālo rāmasya sahajo ripuḥ
samṛddhārthasya naṣṭārtho jīviṣyati kathaṃ vaśe', null, 2008024),
('ramayana-2-8-25', 25, 'Ayodhya Kanda, Sarga 8, Verse 25', 'अभिद्रुतमिवारण्ये सिंहेन गजयूथपम्।
प्रच्छाद्यमानं रामेण भरतं त्रातुमर्हसि॥', 'abhidrutam ivāraṇye siṃhena gajayūthapam
pracchādyamānaṃ rāmeṇa bharataṃ trātum arhasi', null, 2008025),
('ramayana-2-8-26', 26, 'Ayodhya Kanda, Sarga 8, Verse 26', 'दर्पान्निराकृता पूर्वं त्वया सौभाग्यवत्तया।
राममाता सपत्नी ते कथं वैरं न यातयेत्॥', 'darpān nirākṛtā pūrvaṃ tvayā saubhāgyavattayā
rāmamātā sapatnī te kathaṃ vairaṃ na yātayet', null, 2008026),
('ramayana-2-8-27', 27, 'Ayodhya Kanda, Sarga 8, Verse 27', 'यदा हि रामः पृथिवीमवाप्स्यति ध्रुवं प्रनष्टो भरतो भविष्यति।
अतो हि संचिन्तय राज्यमात्मजे परस्य चाद्यैव विवासकारणम्॥', 'yadā hi rāmaḥ pṛthivīm avāpsyati dhruvaṃ pranaṣṭo bharato bhaviṣyati
ato hi saṃcintaya rājyam ātmaje parasya cādyaiva vivāsakāraṇam', null, 2008027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 9 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-9-1', 1, 'Ayodhya Kanda, Sarga 9, Verse 1', 'एवमुक्ता तु कैकेयी क्रोधेन ज्वलितानना।
दीर्घमुष्णं विनिःश्वस्य मन्थरामिदमब्रवीत्॥', 'evam uktā tu kaikeyī krodhena jvalitānanā
dīrgham uṣṇaṃ viniḥśvasya mantharām idam abravīt', null, 2009001),
('ramayana-2-9-2', 2, 'Ayodhya Kanda, Sarga 9, Verse 2', 'अद्य राममितः क्षिप्रं वनं प्रस्थापयाम्यहम्।
यौवराज्येन भरतं क्षिप्रमेवाभिषेचये॥', 'adya rāmam itaḥ kṣipraṃ vanaṃ prasthāpayāmy aham
yauvarājyena bharataṃ kṣipram evābhiṣecaye', null, 2009002),
('ramayana-2-9-3', 3, 'Ayodhya Kanda, Sarga 9, Verse 3', 'इदं त्विदानीं संपश्य केनोपायेन मन्थरे।
भरतः प्राप्नुयाद्राज्यं न तु रामः कथं चन॥', 'idaṃ tv idānīṃ saṃpaśya kenopāyena manthare
bharataḥ prāpnuyād rājyaṃ na tu rāmaḥ kathaṃ cana', null, 2009003),
('ramayana-2-9-4', 4, 'Ayodhya Kanda, Sarga 9, Verse 4', 'एवमुक्ता तया देव्या मन्थरा पापदर्शिनी।
रामार्थमुपहिंसन्ती कैकेयीमिदमब्रवीत्॥', 'evam uktā tayā devyā mantharā pāpadarśinī
rāmārtham upahiṃsantī kaikeyīm idam abravīt', null, 2009004),
('ramayana-2-9-5', 5, 'Ayodhya Kanda, Sarga 9, Verse 5', 'हन्तेदानीं प्रवक्ष्यामि कैकेयि श्रूयतां च मे।
यथा ते भरतो राज्यं पुत्रः प्राप्स्यति केवलम्॥', 'hantedānīṃ pravakṣyāmi kaikeyi śrūyatāṃ ca me
yathā te bharato rājyaṃ putraḥ prāpsyati kevalam', null, 2009005),
('ramayana-2-9-6', 6, 'Ayodhya Kanda, Sarga 9, Verse 6', 'श्रुत्वैवं वचनं तस्या मन्थरायास्तु कैकयी।
किं चिदुत्थाय शयनात्स्वास्तीर्णादिदमब्रवीत्॥', 'śrutvaivaṃ vacanaṃ tasyā mantharāyās tu kaikayī
kiṃ cid utthāya śayanāt svāstīrṇād idam abravīt', null, 2009006),
('ramayana-2-9-7', 7, 'Ayodhya Kanda, Sarga 9, Verse 7', 'कथय त्वं ममोपायं केनोपायेन मन्थरे।
भरतः प्राप्नुयाद्राज्यं न तु रामः कथं चन॥', 'kathaya tvaṃ mamopāyaṃ kenopāyena manthare
bharataḥ prāpnuyād rājyaṃ na tu rāmaḥ kathaṃ cana', null, 2009007),
('ramayana-2-9-8', 8, 'Ayodhya Kanda, Sarga 9, Verse 8', 'एवमुक्ता तया देव्या मन्थरा पापदर्शिनी।
रामार्थमुपहिंसन्ती कुब्जा वचनमब्रवीत्॥', 'evam uktā tayā devyā mantharā pāpadarśinī
rāmārtham upahiṃsantī kubjā vacanam abravīt', null, 2009008),
('ramayana-2-9-9', 9, 'Ayodhya Kanda, Sarga 9, Verse 9', 'तव देवासुरे युद्धे सह राजर्षिभिः पतिः।
अगच्छत्त्वामुपादाय देवराजस्य साह्यकृत्॥', 'tava devāsure yuddhe saha rājarṣibhiḥ patiḥ
agacchat tvām upādāya devarājasya sāhyakṛt', null, 2009009),
('ramayana-2-9-10', 10, 'Ayodhya Kanda, Sarga 9, Verse 10', 'दिशमास्थाय कैकेयि दक्षिणां दण्डकान्प्रति।
वैजयन्तमिति ख्यातं पुरं यत्र तिमिध्वजः॥', 'diśam āsthāya kaikeyi dakṣiṇāṃ daṇḍakān prati
vaijayantam iti khyātaṃ puraṃ yatra timidhvajaḥ', null, 2009010),
('ramayana-2-9-11', 11, 'Ayodhya Kanda, Sarga 9, Verse 11', 'स शम्बर इति ख्यातः शतमायो महासुरः।
ददौ शक्रस्य संग्रामं देवसंघैरनिर्जितः॥', 'sa śambara iti khyātaḥ śatamāyo mahāsuraḥ
dadau śakrasya saṃgrāmaṃ devasaṃghair anirjitaḥ', null, 2009011),
('ramayana-2-9-12', 12, 'Ayodhya Kanda, Sarga 9, Verse 12', 'तस्मिन्महति संग्रामे राजा दशरथस्तदा।
अपवाह्य त्वया देवि संग्रामान्नष्टचेतनः॥', 'tasmin mahati saṃgrāme rājā daśarathas tadā
apavāhya tvayā devi saṃgrāmān naṣṭacetanaḥ', null, 2009012),
('ramayana-2-9-13', 13, 'Ayodhya Kanda, Sarga 9, Verse 13', 'तत्रापि विक्षतः शस्त्रैः पतिस्ते रक्षितस्त्वया।
तुष्टेन तेन दत्तौ ते द्वौ वरौ शुभदर्शने॥', 'tatrāpi vikṣataḥ śastraiḥ patis te rakṣitas tvayā
tuṣṭena tena dattau te dvau varau śubhadarśane', null, 2009013),
('ramayana-2-9-14', 14, 'Ayodhya Kanda, Sarga 9, Verse 14', 'स त्वयोक्तः पतिर्देवि यदेच्छेयं तदा वरौ।
गृह्णीयामिति तत्तेन तथेत्युक्तं महात्मना।
अनभिज्ञा ह्यहं देवि त्वयैव कथितं पुरा॥', 'sa tvayoktaḥ patir devi yadeccheyaṃ tadā varau
gṛhṇīyām iti tat tena tathety uktaṃ mahātmanā
anabhijñā hy ahaṃ devi tvayaiva kathitaṃ purā', null, 2009014),
('ramayana-2-9-15', 15, 'Ayodhya Kanda, Sarga 9, Verse 15', 'तौ वरौ याच भर्तारं भरतस्याभिषेचनम्।
प्रव्राजनं च रामस्य त्वं वर्षाणि चतुर्दश॥', 'tau varau yāca bhartāraṃ bharatasyābhiṣecanam
pravrājanaṃ ca rāmasya tvaṃ varṣāṇi caturdaśa', null, 2009015),
('ramayana-2-9-16', 16, 'Ayodhya Kanda, Sarga 9, Verse 16', 'क्रोधागारं प्रविश्याद्य क्रुद्धेवाश्वपतेः सुते।
शेष्वानन्तर्हितायां त्वं भूमौ मलिनवासिनी।
मा स्मैनं प्रत्युदीक्षेथा मा चैनमभिभाषथाः॥', 'krodhāgāraṃ praviśyādya kruddhevāśvapateḥ sute
śeṣvānantarhitāyāṃ tvaṃ bhūmau malinavāsinī
mā smainaṃ pratyudīkṣethā mā cainam abhibhāṣathāḥ', null, 2009016),
('ramayana-2-9-17', 17, 'Ayodhya Kanda, Sarga 9, Verse 17', 'दयिता त्वं सदा भर्तुरत्र मे नास्ति संशयः।
त्वत्कृते च महाराजो विशेदपि हुताशनम्॥', 'dayitā tvaṃ sadā bhartur atra me nāsti saṃśayaḥ
tvatkṛte ca mahārājo viśed api hutāśanam', null, 2009017),
('ramayana-2-9-18', 18, 'Ayodhya Kanda, Sarga 9, Verse 18', 'न त्वां क्रोधयितुं शक्तो न क्रुद्धां प्रत्युदीक्षितुम्।
तव प्रियार्थं राजा हि प्राणानपि परित्यजेत्॥', 'na tvāṃ krodhayituṃ śakto na kruddhāṃ pratyudīkṣitum
tava priyārthaṃ rājā hi prāṇān api parityajet', null, 2009018),
('ramayana-2-9-19', 19, 'Ayodhya Kanda, Sarga 9, Verse 19', 'न ह्यतिक्रमितुं शक्तस्तव वाक्यं महीपतिः।
मन्दस्वभावे बुध्यस्व सौभाग्यबलमात्मनः॥', 'na hy atikramituṃ śaktas tava vākyaṃ mahīpatiḥ
mandasvabhāve budhyasva saubhāgyabalam ātmanaḥ', null, 2009019),
('ramayana-2-9-20', 20, 'Ayodhya Kanda, Sarga 9, Verse 20', 'मणिमुक्तासुवर्णानि रत्नानि विविधानि च।
दद्याद्दशरथो राजा मा स्म तेषु मनः कृथाः॥', 'maṇimuktāsuvarṇāni ratnāni vividhāni ca
dadyād daśaratho rājā mā sma teṣu manaḥ kṛthāḥ', null, 2009020),
('ramayana-2-9-21', 21, 'Ayodhya Kanda, Sarga 9, Verse 21', 'यौ तौ देवासुरे युद्धे वरौ दशरथोऽददात्।
तौ स्मारय महाभागे सोऽर्थो मा त्वामतिक्रमेत्॥', 'yau tau devāsure yuddhe varau daśaratho ''dadāt
tau smāraya mahābhāge so ''rtho mā tvām atikramet', null, 2009021),
('ramayana-2-9-22', 22, 'Ayodhya Kanda, Sarga 9, Verse 22', 'यदा तु ते वरं दद्यात्स्वयमुत्थाप्य राघवः।
व्यवस्थाप्य महाराजं त्वमिमं वृणुया वरम्॥', 'yadā tu te varaṃ dadyāt svayam utthāpya rāghavaḥ
vyavasthāpya mahārājaṃ tvam imaṃ vṛṇuyā varam', null, 2009022),
('ramayana-2-9-23', 23, 'Ayodhya Kanda, Sarga 9, Verse 23', 'रामं प्रव्राजयारण्ये नव वर्षाणि पञ्च च।
भरतः क्रियतां राजा पृथिव्यां पार्थिवर्षभः॥', 'rāmaṃ pravrājayāraṇye nava varṣāṇi pañca ca
bharataḥ kriyatāṃ rājā pṛthivyāṃ pārthivarṣabhaḥ', null, 2009023),
('ramayana-2-9-24', 24, 'Ayodhya Kanda, Sarga 9, Verse 24', 'एवं प्रव्राजितश्चैव रामोऽरामो भविष्यति।
भरतश्च हतामित्रस्तव राजा भविष्यति॥', 'evaṃ pravrājitaś caiva rāmo ''rāmo bhaviṣyati
bharataś ca hatāmitras tava rājā bhaviṣyati', null, 2009024),
('ramayana-2-9-25', 25, 'Ayodhya Kanda, Sarga 9, Verse 25', 'येन कालेन रामश्च वनात्प्रत्यागमिष्यति।
तेन कालेन पुत्रस्ते कृतमूलो भविष्यति।
संगृहीतमनुष्यश्च सुहृद्भिः सार्धमात्मवान्॥', 'yena kālena rāmaś ca vanāt pratyāgamiṣyati
tena kālena putras te kṛtamūlo bhaviṣyati
saṃgṛhītamanuṣyaś ca suhṛdbhiḥ sārdham ātmavān', null, 2009025),
('ramayana-2-9-26', 26, 'Ayodhya Kanda, Sarga 9, Verse 26', 'प्राप्तकालं तु ते मन्ये राजानं वीतसाध्वसा।
रामाभिषेकसंकल्पान्निगृह्य विनिवर्तय॥', 'prāptakālaṃ tu te manye rājānaṃ vītasādhvasā
rāmābhiṣekasaṃkalpān nigṛhya vinivartaya', null, 2009026),
('ramayana-2-9-27', 27, 'Ayodhya Kanda, Sarga 9, Verse 27', 'अनर्थमर्थरूपेण ग्राहिता सा ततस्तया।
हृष्टा प्रतीता कैकेयी मन्थरामिदमब्रवीत्॥', 'anartham artharūpeṇa grāhitā sā tatas tayā
hṛṣṭā pratītā kaikeyī mantharām idam abravīt', null, 2009027),
('ramayana-2-9-28', 28, 'Ayodhya Kanda, Sarga 9, Verse 28', 'कुब्जे त्वां नाभिजानामि श्रेष्ठां श्रेष्ठाभिधायिनीम्।
पृथिव्यामसि कुब्जानामुत्तमा बुद्धिनिश्चये॥', 'kubje tvāṃ nābhijānāmi śreṣṭhāṃ śreṣṭhābhidhāyinīm
pṛthivyām asi kubjānām uttamā buddhiniścaye', null, 2009028),
('ramayana-2-9-29', 29, 'Ayodhya Kanda, Sarga 9, Verse 29', 'त्वमेव तु ममार्थेषु नित्ययुक्ता हितैषिणी।
नाहं समवबुध्येयं कुब्जे राज्ञश्चिकीर्षितम्॥', 'tvam eva tu mamārtheṣu nityayuktā hitaiṣiṇī
nāhaṃ samavabudhyeyaṃ kubje rājñaś cikīrṣitam', null, 2009029),
('ramayana-2-9-30', 30, 'Ayodhya Kanda, Sarga 9, Verse 30', 'सन्ति दुःसंस्थिताः कुब्जा वक्राः परमपापिकाः।
त्वं पद्ममिव वातेन संनता प्रियदर्शना॥', 'santi duḥsaṃsthitāḥ kubjā vakrāḥ paramapāpikāḥ
tvaṃ padmam iva vātena saṃnatā priyadarśanā', null, 2009030),
('ramayana-2-9-31', 31, 'Ayodhya Kanda, Sarga 9, Verse 31', 'उरस्तेऽभिनिविष्टं वै यावत्स्कन्धात्समुन्नतम्।
अधस्ताच्चोदरं शान्तं सुनाभमिव लज्जितम्॥', 'uras te ''bhiniviṣṭaṃ vai yāvat skandhāt samunnatam
adhastāc codaraṃ śāntaṃ sunābham iva lajjitam', null, 2009031),
('ramayana-2-9-32', 32, 'Ayodhya Kanda, Sarga 9, Verse 32', 'जघनं तव निर्घुष्टं रशनादामशोभितम्।
जङ्घे भृशमुपन्यस्ते पादौ चाप्यायतावुभौ॥', 'jaghanaṃ tava nirghuṣṭaṃ raśanādāmaśobhitam
jaṅghe bhṛśam upanyaste pādau cāpy āyatāv ubhau', null, 2009032),
('ramayana-2-9-33', 33, 'Ayodhya Kanda, Sarga 9, Verse 33', 'त्वमायताभ्यां सक्थिभ्यां मन्थरे क्षौमवासिनि।
अग्रतो मम गच्छन्ती राजहंसीव राजसे॥', 'tvam āyatābhyāṃ sakthibhyāṃ manthare kṣaumavāsini
agrato mama gacchantī rājahaṃsīva rājase', null, 2009033),
('ramayana-2-9-34', 34, 'Ayodhya Kanda, Sarga 9, Verse 34', 'तवेदं स्थगु यद्दीर्घं रथघोणमिवायतम्।
मतयः क्षत्रविद्याश्च मायाश्चात्र वसन्ति ते॥', 'tavedaṃ sthagu yad dīrghaṃ rathaghoṇam ivāyatam
matayaḥ kṣatravidyāś ca māyāś cātra vasanti te', null, 2009034),
('ramayana-2-9-35', 35, 'Ayodhya Kanda, Sarga 9, Verse 35', 'अत्र ते प्रतिमोक्ष्यामि मालां कुब्जे हिरण्मयीम्।
अभिषिक्ते च भरते राघवे च वनं गते॥', 'atra te pratimokṣyāmi mālāṃ kubje hiraṇmayīm
abhiṣikte ca bharate rāghave ca vanaṃ gate', null, 2009035),
('ramayana-2-9-36', 36, 'Ayodhya Kanda, Sarga 9, Verse 36', 'जात्येन च सुवर्णेन सुनिष्टप्तेन सुन्दरि।
लब्धार्था च प्रतीता च लेपयिष्यामि ते स्थगु॥', 'jātyena ca suvarṇena suniṣṭaptena sundari
labdhārthā ca pratītā ca lepayiṣyāmi te sthagu', null, 2009036),
('ramayana-2-9-37', 37, 'Ayodhya Kanda, Sarga 9, Verse 37', 'मुखे च तिलकं चित्रं जातरूपमयं शुभम्।
कारयिष्यामि ते कुब्जे शुभान्याभरणानि च॥', 'mukhe ca tilakaṃ citraṃ jātarūpamayaṃ śubham
kārayiṣyāmi te kubje śubhāny ābharaṇāni ca', null, 2009037),
('ramayana-2-9-38', 38, 'Ayodhya Kanda, Sarga 9, Verse 38', 'परिधाय शुभे वस्त्रे देवदेव चरिष्यसि।
चन्द्रमाह्वयमानेन मुखेनाप्रतिमानना।
गमिष्यसि गतिं मुख्यां गर्वयन्ती द्विषज्जनम्॥', 'paridhāya śubhe vastre devadeva cariṣyasi
candram āhvayamānena mukhenāpratimānanā
gamiṣyasi gatiṃ mukhyāṃ garvayantī dviṣajjanam', null, 2009038),
('ramayana-2-9-39', 39, 'Ayodhya Kanda, Sarga 9, Verse 39', 'तवापि कुब्जाः कुब्जायाः सर्वाभरणभूषिताः।
पादौ परिचरिष्यन्ति यथैव त्वं सदा मम॥', 'tavāpi kubjāḥ kubjāyāḥ sarvābharaṇabhūṣitāḥ
pādau paricariṣyanti yathaiva tvaṃ sadā mama', null, 2009039),
('ramayana-2-9-40', 40, 'Ayodhya Kanda, Sarga 9, Verse 40', 'इति प्रशस्यमाना सा कैकेयीमिदमब्रवीत्।
शयानां शयने शुभ्रे वेद्यामग्निशिखामिव॥', 'iti praśasyamānā sā kaikeyīm idam abravīt
śayānāṃ śayane śubhre vedyām agniśikhām iva', null, 2009040),
('ramayana-2-9-41', 41, 'Ayodhya Kanda, Sarga 9, Verse 41', 'गतोदके सेतुबन्धो न कल्याणि विधीयते।
उत्तिष्ठ कुरु कल्याणं राजानमनुदर्शय॥', 'gatodake setubandho na kalyāṇi vidhīyate
uttiṣṭha kuru kalyāṇaṃ rājānam anudarśaya', null, 2009041),
('ramayana-2-9-42', 42, 'Ayodhya Kanda, Sarga 9, Verse 42', 'तथा प्रोत्साहिता देवी गत्वा मन्थरया सह।
क्रोधागारं विशालाक्षी सौभाग्यमदगर्विता॥', 'tathā protsāhitā devī gatvā mantharayā saha
krodhāgāraṃ viśālākṣī saubhāgyamadagarvitā', null, 2009042),
('ramayana-2-9-43', 43, 'Ayodhya Kanda, Sarga 9, Verse 43', 'अनेकशतसाहस्रं मुक्ताहारं वराङ्गना।
अवमुच्य वरार्हाणि शुभान्याभरणानि च॥', 'anekaśatasāhasraṃ muktāhāraṃ varāṅganā
avamucya varārhāṇi śubhāny ābharaṇāni ca', null, 2009043),
('ramayana-2-9-44', 44, 'Ayodhya Kanda, Sarga 9, Verse 44', 'ततो हेमोपमा तत्र कुब्जा वाक्यं वशं गता।
संविश्य भूमौ कैकेयी मन्थरामिदमब्रवीत्॥', 'tato hemopamā tatra kubjā vākyaṃ vaśaṃ gatā
saṃviśya bhūmau kaikeyī mantharām idam abravīt', null, 2009044),
('ramayana-2-9-45', 45, 'Ayodhya Kanda, Sarga 9, Verse 45', 'इह वा मां मृतां कुब्जे नृपायावेदयिष्यसि।
वनं तु राघवे प्राप्ते भरतः प्राप्स्यति क्षितिम्॥', 'iha vā māṃ mṛtāṃ kubje nṛpāyāvedayiṣyasi
vanaṃ tu rāghave prāpte bharataḥ prāpsyati kṣitim', null, 2009045),
('ramayana-2-9-46', 46, 'Ayodhya Kanda, Sarga 9, Verse 46', 'अथैतदुक्त्वा वचनं सुदारुणं निधाय सर्वाभरणानि भामिनी।
असंवृतामास्तरणेन मेदिनीं तदाधिशिश्ये पतितेव किन्नरी॥', 'athaitad uktvā vacanaṃ sudāruṇaṃ nidhāya sarvābharaṇāni bhāminī
asaṃvṛtām āstaraṇena medinīṃ tadādhiśiśye patiteva kinnarī', null, 2009046),
('ramayana-2-9-47', 47, 'Ayodhya Kanda, Sarga 9, Verse 47', 'उदीर्णसंरम्भतमोवृतानना तथावमुक्तोत्तममाल्यभूषणा।
नरेन्द्रपत्नी विमना बभूव सा तमोवृता द्यौरिव मग्नतारका॥', 'udīrṇasaṃrambhatamovṛtānanā tathāvamuktottamamālyabhūṣaṇā
narendrapatnī vimanā babhūva sā tamovṛtā dyaur iva magnatārakā', null, 2009047)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 10 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-10-1', 1, 'Ayodhya Kanda, Sarga 10, Verse 1', 'आज्ञाप्य तु महाराजो राघवस्याभिषेचनम्।
प्रियार्हां प्रियमाख्यातुं विवेशान्तःपुरं वशी॥', 'ājñāpya tu mahārājo rāghavasyābhiṣecanam
priyārhāṃ priyam ākhyātuṃ viveśāntaḥpuraṃ vaśī', null, 2010001),
('ramayana-2-10-2', 2, 'Ayodhya Kanda, Sarga 10, Verse 2', 'तां तत्र पतितां भूमौ शयानामतथोचिताम्।
प्रतप्त इव दुःखेन सोऽपश्यज्जगतीपतिः॥', 'tāṃ tatra patitāṃ bhūmau śayānām atathocitām
pratapta iva duḥkhena so ''paśyaj jagatīpatiḥ', null, 2010002),
('ramayana-2-10-3', 3, 'Ayodhya Kanda, Sarga 10, Verse 3', 'स वृद्धस्तरुणीं भार्यां प्राणेभ्योऽपि गरीयसीम्।
अपापः पापसंकल्पां ददर्श धरणीतले॥', 'sa vṛddhas taruṇīṃ bhāryāṃ prāṇebhyo ''pi garīyasīm
apāpaḥ pāpasaṃkalpāṃ dadarśa dharaṇītale', null, 2010003),
('ramayana-2-10-4', 4, 'Ayodhya Kanda, Sarga 10, Verse 4', 'करेणुमिव दिग्धेन विद्धां मृगयुणा वने।
महागज इवारण्ये स्नेहात्परिममर्श ताम्॥', 'kareṇum iva digdhena viddhāṃ mṛgayuṇā vane
mahāgaja ivāraṇye snehāt parimamarśa tām', null, 2010004),
('ramayana-2-10-5', 5, 'Ayodhya Kanda, Sarga 10, Verse 5', 'परिमृश्य च पाणिभ्यामभिसंत्रस्तचेतनः।
कामी कमलपत्राक्षीमुवाच वनितामिदम्॥', 'parimṛśya ca pāṇibhyām abhisaṃtrastacetanaḥ
kāmī kamalapatrākṣīm uvāca vanitām idam', null, 2010005),
('ramayana-2-10-6', 6, 'Ayodhya Kanda, Sarga 10, Verse 6', 'न तेऽहमभिजानामि क्रोधमात्मनि संश्रितम्।
देवि केनाभियुक्तासि केन वासि विमानिता॥', 'na te ''ham abhijānāmi krodham ātmani saṃśritam
devi kenābhiyuktāsi kena vāsi vimānitā', null, 2010006),
('ramayana-2-10-7', 7, 'Ayodhya Kanda, Sarga 10, Verse 7', 'यदिदं मम दुःखाय शेषे कल्याणि पांसुषु।
भूमौ शेषे किमर्थं त्वं मयि कल्याण चेतसि।
भूतोपहतचित्तेव मम चित्तप्रमाथिनी॥', 'yad idaṃ mama duḥkhāya śeṣe kalyāṇi pāṃsuṣu
bhūmau śeṣe kimarthaṃ tvaṃ mayi kalyāṇa cetasi
bhūtopahatacitteva mama cittapramāthinī', null, 2010007),
('ramayana-2-10-8', 8, 'Ayodhya Kanda, Sarga 10, Verse 8', 'सन्ति मे कुशला वैद्या अभितुष्टाश्च सर्वशः।
सुखितां त्वां करिष्यन्ति व्याधिमाचक्ष्व भामिनि॥', 'santi me kuśalā vaidyā abhituṣṭāś ca sarvaśaḥ
sukhitāṃ tvāṃ kariṣyanti vyādhim ācakṣva bhāmini', null, 2010008),
('ramayana-2-10-9', 9, 'Ayodhya Kanda, Sarga 10, Verse 9', 'कस्य वा ते प्रियं कार्यं केन वा विप्रियं कृतम्।
कः प्रियं लभतामद्य को वा सुमहदप्रियम्॥', 'kasya vā te priyaṃ kāryaṃ kena vā vipriyaṃ kṛtam
kaḥ priyaṃ labhatām adya ko vā sumahad apriyam', null, 2010009),
('ramayana-2-10-10', 10, 'Ayodhya Kanda, Sarga 10, Verse 10', 'अवध्यो वध्यतां को वा वध्यः को वा विमुच्यताम्।
दरिद्रः को भवत्वाढ्यो द्रव्यवान्वाप्यकिंचनः॥', 'avadhyo vadhyatāṃ ko vā vadhyaḥ ko vā vimucyatām
daridraḥ ko bhavatv āḍhyo dravyavān vāpy akiṃcanaḥ', null, 2010010),
('ramayana-2-10-11', 11, 'Ayodhya Kanda, Sarga 10, Verse 11', 'अहं चैव मदीयाश्च सर्वे तव वशानुगाः।
न ते कं चिदभिप्रायं व्याहन्तुमहमुत्सहे॥', 'ahaṃ caiva madīyāś ca sarve tava vaśānugāḥ
na te kaṃ cid abhiprāyaṃ vyāhantum aham utsahe', null, 2010011),
('ramayana-2-10-12', 12, 'Ayodhya Kanda, Sarga 10, Verse 12', 'आत्मनो जीवितेनापि ब्रूहि यन्मनसेच्छसि।
यावदावर्तते चक्रं तावती मे वसुंधरा॥', 'ātmano jīvitenāpi brūhi yan manasecchasi
yāvad āvartate cakraṃ tāvatī me vasuṃdharā', null, 2010012),
('ramayana-2-10-13', 13, 'Ayodhya Kanda, Sarga 10, Verse 13', 'तथोक्ता सा समाश्वस्ता वक्तुकामा तदप्रियम्।
परिपीडयितुं भूयो भर्तारमुपचक्रमे॥', 'tathoktā sā samāśvastā vaktukāmā tad apriyam
paripīḍayituṃ bhūyo bhartāram upacakrame', null, 2010013),
('ramayana-2-10-14', 14, 'Ayodhya Kanda, Sarga 10, Verse 14', 'नास्मि विप्रकृता देव केन चिन्न विमानिता।
अभिप्रायस्तु मे कश्चित्तमिच्छामि त्वया कृतम्॥', 'nāsmi viprakṛtā deva kena cin na vimānitā
abhiprāyas tu me kaś cit tam icchāmi tvayā kṛtam', null, 2010014),
('ramayana-2-10-15', 15, 'Ayodhya Kanda, Sarga 10, Verse 15', 'प्रतिज्ञां प्रतिजानीष्व यदि त्वं कर्तुमिच्छसि।
अथ तद्व्याहरिष्यामि यदभिप्रार्थितं मया॥', 'pratijñāṃ pratijānīṣva yadi tvaṃ kartum icchasi
atha tad vyāhariṣyāmi yad abhiprārthitaṃ mayā', null, 2010015),
('ramayana-2-10-16', 16, 'Ayodhya Kanda, Sarga 10, Verse 16', 'एवमुक्तस्तया राजा प्रियया स्त्रीवशं गतः।
तामुवाच महातेजाः कैकेयीमीषदुत्स्मितः॥', 'evam uktas tayā rājā priyayā strīvaśaṃ gataḥ
tām uvāca mahātejāḥ kaikeyīm īṣadutsmitaḥ', null, 2010016),
('ramayana-2-10-17', 17, 'Ayodhya Kanda, Sarga 10, Verse 17', 'अवलिप्ते न जानासि त्वत्तः प्रियतरो मम।
मनुजो मनुजव्याघ्राद्रामादन्यो न विद्यते॥', 'avalipte na jānāsi tvattaḥ priyataro mama
manujo manujavyāghrād rāmād anyo na vidyate', null, 2010017),
('ramayana-2-10-18', 18, 'Ayodhya Kanda, Sarga 10, Verse 18', 'भद्रे हृदयमप्येतदनुमृश्श्योद्धरस्व मे।
एतत्समीक्ष्य कैकेयि ब्रूहि यत्साधु मन्यसे॥', 'bhadre hṛdayam apy etad anumṛśśyoddharasva me
etat samīkṣya kaikeyi brūhi yat sādhu manyase', null, 2010018),
('ramayana-2-10-19', 19, 'Ayodhya Kanda, Sarga 10, Verse 19', 'बलमात्मनि पश्यन्ती न मां शङ्कितुमर्हसि।
करिष्यामि तव प्रीतिं सुकृतेनापि ते शपे॥', 'balam ātmani paśyantī na māṃ śaṅkitum arhasi
kariṣyāmi tava prītiṃ sukṛtenāpi te śape', null, 2010019),
('ramayana-2-10-20', 20, 'Ayodhya Kanda, Sarga 10, Verse 20', 'तेन वाक्येन संहृष्टा तमभिप्रायमात्मनः।
व्याजहार महाघोरमभ्यागतमिवान्तकम्॥', 'tena vākyena saṃhṛṣṭā tam abhiprāyam ātmanaḥ
vyājahāra mahāghoram abhyāgatam ivāntakam', null, 2010020),
('ramayana-2-10-21', 21, 'Ayodhya Kanda, Sarga 10, Verse 21', 'यथाक्रमेण शपसि वरं मम ददासि च।
तच्छृण्वन्तु त्रयस्त्रिंशद्देवाः सेन्द्रपुरोगमाः॥', 'yathākrameṇa śapasi varaṃ mama dadāsi ca
tac chṛṇvantu trayastriṃśad devāḥ sendrapurogamāḥ', null, 2010021),
('ramayana-2-10-22', 22, 'Ayodhya Kanda, Sarga 10, Verse 22', 'चन्द्रादित्यौ नभश्चैव ग्रहा रात्र्यहनी दिशः।
जगच्च पृथिवी चैव सगन्धर्वा सराक्षसा॥', 'candrādityau nabhaś caiva grahā rātryahanī diśaḥ
jagac ca pṛthivī caiva sagandharvā sarākṣasā', null, 2010022),
('ramayana-2-10-23', 23, 'Ayodhya Kanda, Sarga 10, Verse 23', 'निशाचराणि भूतानि गृहेषु गृहदेवताः।
यानि चान्यानि भूतानि जानीयुर्भाषितं तव॥', 'niśācarāṇi bhūtāni gṛheṣu gṛhadevatāḥ
yāni cānyāni bhūtāni jānīyur bhāṣitaṃ tava', null, 2010023),
('ramayana-2-10-24', 24, 'Ayodhya Kanda, Sarga 10, Verse 24', 'सत्यसंधो महातेजा धर्मज्ञः सुसमाहितः।
वरं मम ददात्येष तन्मे शृण्वन्तु देवताः॥', 'satyasaṃdho mahātejā dharmajñaḥ susamāhitaḥ
varaṃ mama dadāty eṣa tan me śṛṇvantu devatāḥ', null, 2010024),
('ramayana-2-10-25', 25, 'Ayodhya Kanda, Sarga 10, Verse 25', 'इति देवी महेष्वासं परिगृह्याभिशस्य च।
ततः परमुवाचेदं वरदं काममोहितम्॥', 'iti devī maheṣvāsaṃ parigṛhyābhiśasya ca
tataḥ param uvācedaṃ varadaṃ kāmamohitam', null, 2010025),
('ramayana-2-10-26', 26, 'Ayodhya Kanda, Sarga 10, Verse 26', 'वरौ यौ मे त्वया देव तदा दत्तौ महीपते।
तौ तावदहमद्यैव वक्ष्यामि शृणु मे वचः॥', 'varau yau me tvayā deva tadā dattau mahīpate
tau tāvad aham adyaiva vakṣyāmi śṛṇu me vacaḥ', null, 2010026),
('ramayana-2-10-27', 27, 'Ayodhya Kanda, Sarga 10, Verse 27', 'अभिषेक समारम्भो राघवस्योपकल्पितः।
अनेनैवाभिषेकेण भरतो मेऽभिषिच्यताम्॥', 'abhiṣeka samārambho rāghavasyopakalpitaḥ
anenaivābhiṣekeṇa bharato me ''bhiṣicyatām', null, 2010027),
('ramayana-2-10-28', 28, 'Ayodhya Kanda, Sarga 10, Verse 28', 'नव पञ्च च वर्षाणि दण्डकारण्यमाश्रितः।
चीराजिनजटाधारी रामो भवतु तापसः॥', 'nava pañca ca varṣāṇi daṇḍakāraṇyam āśritaḥ
cīrājinajaṭādhārī rāmo bhavatu tāpasaḥ', null, 2010028),
('ramayana-2-10-29', 29, 'Ayodhya Kanda, Sarga 10, Verse 29', 'भरतो भजतामद्य यौवराज्यमकण्टकम्।
अद्य चैव हि पश्येयं प्रयान्तं राघवं वने॥', 'bharato bhajatām adya yauvarājyam akaṇṭakam
adya caiva hi paśyeyaṃ prayāntaṃ rāghavaṃ vane', null, 2010029),
('ramayana-2-10-30', 30, 'Ayodhya Kanda, Sarga 10, Verse 30', 'ततः श्रुत्वा महाराजः कैकेय्या दारुणं वचः।
व्यथितो विक्लवश्चैव व्याघ्रीं दृष्ट्वा यथा मृगः॥', 'tataḥ śrutvā mahārājaḥ kaikeyyā dāruṇaṃ vacaḥ
vyathito viklavaś caiva vyāghrīṃ dṛṣṭvā yathā mṛgaḥ', null, 2010030),
('ramayana-2-10-31', 31, 'Ayodhya Kanda, Sarga 10, Verse 31', 'असंवृतायामासीनो जगत्यां दीर्घमुच्छ्वसन्।
अहो धिगिति सामर्षो वाचमुक्त्वा नराधिपः।
मोहमापेदिवान्भूयः शोकोपहतचेतनः॥', 'asaṃvṛtāyām āsīno jagatyāṃ dīrgham ucchvasan
aho dhig iti sāmarṣo vācam uktvā narādhipaḥ
moham āpedivān bhūyaḥ śokopahatacetanaḥ', null, 2010031),
('ramayana-2-10-32', 32, 'Ayodhya Kanda, Sarga 10, Verse 32', 'चिरेण तु नृपः संज्ञां प्रतिलभ्य सुदुःखितः।
कैकेयीमब्रवीत्क्रुद्धः प्रदहन्निव चक्षुषा॥', 'cireṇa tu nṛpaḥ saṃjñāṃ pratilabhya suduḥkhitaḥ
kaikeyīm abravīt kruddhaḥ pradahann iva cakṣuṣā', null, 2010032),
('ramayana-2-10-33', 33, 'Ayodhya Kanda, Sarga 10, Verse 33', 'नृशंसे दुष्टचारित्रे कुलस्यास्य विनाशिनि।
किं कृतं तव रामेण पापे पापं मयापि वा॥', 'nṛśaṃse duṣṭacāritre kulasyāsya vināśini
kiṃ kṛtaṃ tava rāmeṇa pāpe pāpaṃ mayāpi vā', null, 2010033),
('ramayana-2-10-34', 34, 'Ayodhya Kanda, Sarga 10, Verse 34', 'सदा ते जननी तुल्यां वृत्तिं वहति राघवः।
तस्यैव त्वमनर्थाय किंनिमित्तमिहोद्यता॥', 'sadā te jananī tulyāṃ vṛttiṃ vahati rāghavaḥ
tasyaiva tvam anarthāya kiṃnimittam ihodyatā', null, 2010034),
('ramayana-2-10-35', 35, 'Ayodhya Kanda, Sarga 10, Verse 35', 'त्वं मयात्मविनाशाय भवनं स्वं प्रवेशिता।
अविज्ञानान्नृपसुता व्याली तीक्ष्णविषा यथा॥', 'tvaṃ mayātmavināśāya bhavanaṃ svaṃ praveśitā
avijñānān nṛpasutā vyālī tīkṣṇaviṣā yathā', null, 2010035),
('ramayana-2-10-36', 36, 'Ayodhya Kanda, Sarga 10, Verse 36', 'जीवलोको यदा सर्वो रामस्येह गुणस्तवम्।
अपराधं कमुद्दिश्य त्यक्ष्यामीष्टमहं सुतम्॥', 'jīvaloko yadā sarvo rāmasyeha guṇastavam
aparādhaṃ kam uddiśya tyakṣyāmīṣṭam ahaṃ sutam', null, 2010036),
('ramayana-2-10-37', 37, 'Ayodhya Kanda, Sarga 10, Verse 37', 'कौसल्यां वा सुमित्रां वा त्यजेयमपि वा श्रियम्।
जीवितं वात्मनो रामं न त्वेव पितृवत्सलम्॥', 'kausalyāṃ vā sumitrāṃ vā tyajeyam api vā śriyam
jīvitaṃ vātmano rāmaṃ na tv eva pitṛvatsalam', null, 2010037),
('ramayana-2-10-38', 38, 'Ayodhya Kanda, Sarga 10, Verse 38', 'परा भवति मे प्रीतिर्दृष्ट्वा तनयमग्रजम्।
अपश्यतस्तु मे रामं नष्टा भवति चेतना॥', 'parā bhavati me prītir dṛṣṭvā tanayam agrajam
apaśyatas tu me rāmaṃ naṣṭā bhavati cetanā', null, 2010038),
('ramayana-2-10-39', 39, 'Ayodhya Kanda, Sarga 10, Verse 39', 'तिष्ठेल्लोको विना सूर्यं सस्यं वा सलिलं विना।
न तु रामं विना देहे तिष्ठेत्तु मम जीवितम्॥', 'tiṣṭhel loko vinā sūryaṃ sasyaṃ vā salilaṃ vinā
na tu rāmaṃ vinā dehe tiṣṭhet tu mama jīvitam', null, 2010039),
('ramayana-2-10-40', 40, 'Ayodhya Kanda, Sarga 10, Verse 40', 'तदलं त्यज्यतामेष निश्चयः पापनिश्चये।
अपि ते चरणौ मूर्ध्ना स्पृशाम्येष प्रसीद मे॥', 'tad alaṃ tyajyatām eṣa niścayaḥ pāpaniścaye
api te caraṇau mūrdhnā spṛśāmy eṣa prasīda me', null, 2010040),
('ramayana-2-10-41', 41, 'Ayodhya Kanda, Sarga 10, Verse 41', 'स भूमिपालो विलपन्ननाथवत्स्त्रिया गृहीतो दृहयेऽतिमात्रता।
पपात देव्याश्चरणौ प्रसारितावुभावसंस्पृश्य यथातुरस्तथा॥', 'sa bhūmipālo vilapann anāthavat striyā gṛhīto dṛhaye ''timātratā
papāta devyāś caraṇau prasāritāv ubhāv asaṃspṛśya yathāturas tathā', null, 2010041)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 11 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-11-1', 1, 'Ayodhya Kanda, Sarga 11, Verse 1', 'अतदर्हं महाराजं शयानमतथोचितम्।
ययातिमिव पुण्यान्ते देवलोकात्परिच्युतम्॥', 'atadarhaṃ mahārājaṃ śayānam atathocitam
yayātim iva puṇyānte devalokāt paricyutam', null, 2011001),
('ramayana-2-11-2', 2, 'Ayodhya Kanda, Sarga 11, Verse 2', 'अनर्थरूपा सिद्धार्था अभीता भयदर्शिनी।
पुनराकारयामास तमेव वरमङ्गना॥', 'anartharūpā siddhārthā abhītā bhayadarśinī
punar ākārayām āsa tam eva varam aṅganā', null, 2011002),
('ramayana-2-11-3', 3, 'Ayodhya Kanda, Sarga 11, Verse 3', 'त्वं कत्थसे महाराज सत्यवादी दृढव्रतः।
मम चेमं वरं कस्माद्विधारयितुमिच्छसि॥', 'tvaṃ katthase mahārāja satyavādī dṛḍhavrataḥ
mama cemaṃ varaṃ kasmād vidhārayitum icchasi', null, 2011003),
('ramayana-2-11-4', 4, 'Ayodhya Kanda, Sarga 11, Verse 4', 'एवमुक्तस्तु कैकेय्या राजा दशरथस्तदा।
प्रत्युवाच ततः क्रुद्धो मुहूर्तं विह्वलन्निव॥', 'evam uktas tu kaikeyyā rājā daśarathas tadā
pratyuvāca tataḥ kruddho muhūrtaṃ vihvalann iva', null, 2011004),
('ramayana-2-11-5', 5, 'Ayodhya Kanda, Sarga 11, Verse 5', 'मृते मयि गते रामे वनं मनुजपुंगवे।
हन्तानार्ये ममामित्रे रामः प्रव्राजितो वनम्॥', 'mṛte mayi gate rāme vanaṃ manujapuṃgave
hantānārye mamāmitre rāmaḥ pravrājito vanam', null, 2011005),
('ramayana-2-11-6', 6, 'Ayodhya Kanda, Sarga 11, Verse 6', 'यदि सत्यं ब्रवीम्येतत्तदसत्यं भविष्यति।
अकीर्तिरतुला लोके ध्रुवं परिभवश्च मे॥', 'yadi satyaṃ bravīmy etat tad asatyaṃ bhaviṣyati
akīrtir atulā loke dhruvaṃ paribhavaś ca me', null, 2011006),
('ramayana-2-11-7', 7, 'Ayodhya Kanda, Sarga 11, Verse 7', 'तथा विलपतस्तस्य परिभ्रमितचेतसः।
अस्तमभ्यगमत्सूर्यो रजनी चाभ्यवर्तत॥', 'tathā vilapatas tasya paribhramitacetasaḥ
astam abhyagamat sūryo rajanī cābhyavartata', null, 2011007),
('ramayana-2-11-8', 8, 'Ayodhya Kanda, Sarga 11, Verse 8', 'स त्रियामा तथार्तस्य चन्द्रमण्डलमण्डिता।
राज्ञो विलपमानस्य न व्यभासत शर्वरी॥', 'sa triyāmā tathārtasya candramaṇḍalamaṇḍitā
rājño vilapamānasya na vyabhāsata śarvarī', null, 2011008),
('ramayana-2-11-9', 9, 'Ayodhya Kanda, Sarga 11, Verse 9', 'तथैवोष्णं विनिःश्वस्य वृद्धो दशरथो नृपः।
विललापार्तवद्दुःखं गगनासक्तलोचनः॥', 'tathaivoṣṇaṃ viniḥśvasya vṛddho daśaratho nṛpaḥ
vilalāpārtavad duḥkhaṃ gaganāsaktalocanaḥ', null, 2011009),
('ramayana-2-11-10', 10, 'Ayodhya Kanda, Sarga 11, Verse 10', 'न प्रभातं त्वयेच्छामि मयायं रचितोऽञ्जलिः।
अथ वा गम्यतां शीघ्रं नाहमिच्छामि निर्घृणाम्।
नृशंसां कैकेयीं द्रष्टुं यत्कृते व्यसनं महत्॥', 'na prabhātaṃ tvayecchāmi mayāyaṃ racito ''ñjaliḥ
atha vā gamyatāṃ śīghraṃ nāham icchāmi nirghṛṇām
nṛśaṃsāṃ kaikeyīṃ draṣṭuṃ yatkṛte vyasanaṃ mahat', null, 2011010),
('ramayana-2-11-11', 11, 'Ayodhya Kanda, Sarga 11, Verse 11', 'एवमुक्त्वा ततो राजा कैकेयीं संयताञ्जलिः।
प्रसादयामास पुनः कैकेयीं चेदमब्रवीत्॥', 'evam uktvā tato rājā kaikeyīṃ saṃyatāñjaliḥ
prasādayām āsa punaḥ kaikeyīṃ cedam abravīt', null, 2011011),
('ramayana-2-11-12', 12, 'Ayodhya Kanda, Sarga 11, Verse 12', 'साधुवृत्तस्य दीनस्य त्वद्गतस्य गतायुषः।
प्रसादः क्रियतां देवि भद्रे राज्ञो विशेषतः॥', 'sādhuvṛttasya dīnasya tvadgatasya gatāyuṣaḥ
prasādaḥ kriyatāṃ devi bhadre rājño viśeṣataḥ', null, 2011012),
('ramayana-2-11-13', 13, 'Ayodhya Kanda, Sarga 11, Verse 13', 'शून्येन खलु सुश्रोणि मयेदं समुदाहृतम्।
कुरु साधु प्रसादं मे बाले सहृदया ह्यसि॥', 'śūnyena khalu suśroṇi mayedaṃ samudāhṛtam
kuru sādhu prasādaṃ me bāle sahṛdayā hy asi', null, 2011013),
('ramayana-2-11-14', 14, 'Ayodhya Kanda, Sarga 11, Verse 14', 'विशुद्धभावस्य हि दुष्टभावा ताम्रेक्षणस्याश्रुकलस्य राज्ञः।
श्रुत्वा विचित्रं करुणं विलापं भर्तुर्नृशंसा न चकार वाक्यम्॥', 'viśuddhabhāvasya hi duṣṭabhāvā tāmrekṣaṇasyāśrukalasya rājñaḥ
śrutvā vicitraṃ karuṇaṃ vilāpaṃ bhartur nṛśaṃsā na cakāra vākyam', null, 2011014),
('ramayana-2-11-15', 15, 'Ayodhya Kanda, Sarga 11, Verse 15', 'ततः स राजा पुनरेव मूर्छितः प्रियामतुष्टां प्रतिकूलभाषिणीम्।
समीक्ष्य पुत्रस्य विवासनं प्रति क्षितौ विसंज्ञो निपपात दुःखितः॥', 'tataḥ sa rājā punar eva mūrchitaḥ priyām atuṣṭāṃ pratikūlabhāṣiṇīm
samīkṣya putrasya vivāsanaṃ prati kṣitau visaṃjño nipapāta duḥkhitaḥ', null, 2011015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 12 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-12-1', 1, 'Ayodhya Kanda, Sarga 12, Verse 1', 'पुत्रशोकार्दितं पापा विसंज्ञं पतितं भुवि।
विवेष्टमानमुदीक्ष्य सैक्ष्वाकमिदमब्रवीत्॥', 'putraśokārditaṃ pāpā visaṃjñaṃ patitaṃ bhuvi
viveṣṭamānam udīkṣya saikṣvākam idam abravīt', null, 2012001),
('ramayana-2-12-2', 2, 'Ayodhya Kanda, Sarga 12, Verse 2', 'पापं कृत्वेव किमिदं मम संश्रुत्य संश्रवम्।
शेषे क्षितितले सन्नः स्थित्यां स्थातुं त्वमर्हसि॥', 'pāpaṃ kṛtveva kim idaṃ mama saṃśrutya saṃśravam
śeṣe kṣititale sannaḥ sthityāṃ sthātuṃ tvam arhasi', null, 2012002),
('ramayana-2-12-3', 3, 'Ayodhya Kanda, Sarga 12, Verse 3', 'आहुः सत्यं हि परमं धर्मं धर्मविदो जनाः।
सत्यमाश्रित्य हि मया त्वं च धर्मं प्रचोदितः॥', 'āhuḥ satyaṃ hi paramaṃ dharmaṃ dharmavido janāḥ
satyam āśritya hi mayā tvaṃ ca dharmaṃ pracoditaḥ', null, 2012003),
('ramayana-2-12-4', 4, 'Ayodhya Kanda, Sarga 12, Verse 4', 'संश्रुत्य शैब्यः श्येनाय स्वां तनुं जगतीपतिः।
प्रदाय पक्षिणो राजञ्जगाम गतिमुत्तमाम्॥', 'saṃśrutya śaibyaḥ śyenāya svāṃ tanuṃ jagatīpatiḥ
pradāya pakṣiṇo rājañ jagāma gatim uttamām', null, 2012004),
('ramayana-2-12-5', 5, 'Ayodhya Kanda, Sarga 12, Verse 5', 'तथ ह्यलर्कस्तेजस्वी ब्राह्मणे वेदपारगे।
याचमाने स्वके नेत्रे उद्धृत्याविमना ददौ॥', 'tatha hy alarkas tejasvī brāhmaṇe vedapārage
yācamāne svake netre uddhṛtyāvimanā dadau', null, 2012005),
('ramayana-2-12-6', 6, 'Ayodhya Kanda, Sarga 12, Verse 6', 'सरितां तु पतिः स्वल्पां मर्यादां सत्यमन्वितः।
सत्यानुरोधात्समये वेलां खां नातिवर्तते॥', 'saritāṃ tu patiḥ svalpāṃ maryādāṃ satyam anvitaḥ
satyānurodhāt samaye velāṃ khāṃ nātivartate', null, 2012006),
('ramayana-2-12-7', 7, 'Ayodhya Kanda, Sarga 12, Verse 7', 'समयं च ममार्येमं यदि त्वं न करिष्यसि।
अग्रतस्ते परित्यक्ता परित्यक्ष्यामि जीवितम्॥', 'samayaṃ ca mamāryemaṃ yadi tvaṃ na kariṣyasi
agratas te parityaktā parityakṣyāmi jīvitam', null, 2012007),
('ramayana-2-12-8', 8, 'Ayodhya Kanda, Sarga 12, Verse 8', 'एवं प्रचोदितो राजा कैकेय्या निर्विशङ्कया।
नाशकत्पाशमुन्मोक्तुं बलिरिन्द्रकृतं यथा॥', 'evaṃ pracodito rājā kaikeyyā nirviśaṅkayā
nāśakat pāśam unmoktuṃ balir indrakṛtaṃ yathā', null, 2012008),
('ramayana-2-12-9', 9, 'Ayodhya Kanda, Sarga 12, Verse 9', 'उद्भ्रान्तहृदयश्चापि विवर्णवनदोऽभवत्।
स धुर्यो वै परिस्पन्दन्युगचक्रान्तरं यथा॥', 'udbhrāntahṛdayaś cāpi vivarṇavanado ''bhavat
sa dhuryo vai parispandan yugacakrāntaraṃ yathā', null, 2012009),
('ramayana-2-12-10', 10, 'Ayodhya Kanda, Sarga 12, Verse 10', 'विह्वलाभ्यां च नेत्राभ्यामपश्यन्निव भूमिपः।
कृच्छ्राद्धैर्येण संस्तभ्य कैकेयीमिदमब्रवीत्॥', 'vihvalābhyāṃ ca netrābhyām apaśyann iva bhūmipaḥ
kṛcchrād dhairyeṇa saṃstabhya kaikeyīm idam abravīt', null, 2012010),
('ramayana-2-12-11', 11, 'Ayodhya Kanda, Sarga 12, Verse 11', 'यस्ते मन्त्रकृतः पाणिरग्नौ पापे मया धृतः।
तं त्यजामि स्वजं चैव तव पुत्रं सह त्वया॥', 'yas te mantrakṛtaḥ pāṇir agnau pāpe mayā dhṛtaḥ
taṃ tyajāmi svajaṃ caiva tava putraṃ saha tvayā', null, 2012011),
('ramayana-2-12-12', 12, 'Ayodhya Kanda, Sarga 12, Verse 12', 'ततः पापसमाचारा कैकेयी पार्थिवं पुनः।
उवाच परुषं वाक्यं वाक्यज्ञा रोषमूर्छिता॥', 'tataḥ pāpasamācārā kaikeyī pārthivaṃ punaḥ
uvāca paruṣaṃ vākyaṃ vākyajñā roṣamūrchitā', null, 2012012),
('ramayana-2-12-13', 13, 'Ayodhya Kanda, Sarga 12, Verse 13', 'किमिदं भाषसे राजन्वाक्यं गररुजोपमम्।
आनाययितुमक्लिष्टं पुत्रं राममिहार्हसि॥', 'kim idaṃ bhāṣase rājan vākyaṃ gararujopamam
ānāyayitum akliṣṭaṃ putraṃ rāmam ihārhasi', null, 2012013),
('ramayana-2-12-14', 14, 'Ayodhya Kanda, Sarga 12, Verse 14', 'स्थाप्य राज्ये मम सुतं कृत्वा रामं वनेचरम्।
निःसपत्नां च मां कृत्वा कृतकृत्यो भविष्यसि॥', 'sthāpya rājye mama sutaṃ kṛtvā rāmaṃ vanecaram
niḥsapatnāṃ ca māṃ kṛtvā kṛtakṛtyo bhaviṣyasi', null, 2012014),
('ramayana-2-12-15', 15, 'Ayodhya Kanda, Sarga 12, Verse 15', 'स नुन्न इव तीक्षेण प्रतोदेन हयोत्तमः।
राजा प्रदोचितोऽभीक्ष्णं कैकेयीमिदमब्रवीत्॥', 'sa nunna iva tīkṣeṇa pratodena hayottamaḥ
rājā pradocito ''bhīkṣṇaṃ kaikeyīm idam abravīt', null, 2012015),
('ramayana-2-12-16', 16, 'Ayodhya Kanda, Sarga 12, Verse 16', 'धर्मबन्धेन बद्धोऽस्मि नष्टा च मम चेतना।
ज्येष्ठं पुत्रं प्रियं रामं द्रष्टुमिच्छामि धार्मिकम्॥', 'dharmabandhena baddho ''smi naṣṭā ca mama cetanā
jyeṣṭhaṃ putraṃ priyaṃ rāmaṃ draṣṭum icchāmi dhārmikam', null, 2012016),
('ramayana-2-12-17', 17, 'Ayodhya Kanda, Sarga 12, Verse 17', 'इति राज्ञो वचः श्रुत्वा कैकेयी तदनन्तरम्।
स्वयमेवाब्रवीत्सूतं गच्छ त्वं राममानय॥', 'iti rājño vacaḥ śrutvā kaikeyī tadanantaram
svayam evābravīt sūtaṃ gaccha tvaṃ rāmam ānaya', null, 2012017),
('ramayana-2-12-18', 18, 'Ayodhya Kanda, Sarga 12, Verse 18', 'ततः स राजा तं सूतं सन्नहर्षः सुतं प्रति।
शोकारक्तेक्षणः श्रीमानुद्वीक्ष्योवाच धार्मिकः॥', 'tataḥ sa rājā taṃ sūtaṃ sannaharṣaḥ sutaṃ prati
śokāraktekṣaṇaḥ śrīmān udvīkṣyovāca dhārmikaḥ', null, 2012018),
('ramayana-2-12-19', 19, 'Ayodhya Kanda, Sarga 12, Verse 19', 'सुमन्त्रः करुणं श्रुत्वा दृष्ट्वा दीनं च पार्थिवम्।
प्रगृहीताञ्जलिः किं चित्तस्माद्देशादपाक्रमन्॥', 'sumantraḥ karuṇaṃ śrutvā dṛṣṭvā dīnaṃ ca pārthivam
pragṛhītāñjaliḥ kiṃ cit tasmād deśād apākraman', null, 2012019),
('ramayana-2-12-20', 20, 'Ayodhya Kanda, Sarga 12, Verse 20', 'यदा वक्तुं स्वयं दैन्यान्न शशाक महीपतिः।
तदा सुमन्त्रं मन्त्रज्ञा कैकेयी प्रत्युवाच ह॥', 'yadā vaktuṃ svayaṃ dainyān na śaśāka mahīpatiḥ
tadā sumantraṃ mantrajñā kaikeyī pratyuvāca ha', null, 2012020),
('ramayana-2-12-21', 21, 'Ayodhya Kanda, Sarga 12, Verse 21', 'सुमन्त्र रामं द्रक्ष्यामि शीघ्रमानय सुन्दरम्।
स मन्यमानः कल्याणं हृदयेन ननन्द च॥', 'sumantra rāmaṃ drakṣyāmi śīghram ānaya sundaram
sa manyamānaḥ kalyāṇaṃ hṛdayena nananda ca', null, 2012021),
('ramayana-2-12-22', 22, 'Ayodhya Kanda, Sarga 12, Verse 22', 'सुमन्त्रश्चिन्तयामास त्वरितं चोदितस्तया।
व्यक्तं रामोऽभिषेकार्थमिहायास्यति धर्मवित्॥', 'sumantraś cintayām āsa tvaritaṃ coditas tayā
vyaktaṃ rāmo ''bhiṣekārtham ihāyāsyati dharmavit', null, 2012022),
('ramayana-2-12-23', 23, 'Ayodhya Kanda, Sarga 12, Verse 23', 'इति सूतो मतिं कृत्वा हर्षेण महता पुनः।
निर्जगाम महातेजा राघवस्य दिदृक्षया॥', 'iti sūto matiṃ kṛtvā harṣeṇa mahatā punaḥ
nirjagāma mahātejā rāghavasya didṛkṣayā', null, 2012023),
('ramayana-2-12-24', 24, 'Ayodhya Kanda, Sarga 12, Verse 24', 'ततः पुरस्तात्सहसा विनिर्गतो महीपतीन्द्वारगतान्विलोकयन्।
ददर्श पौरान्विविधान्महाधनानुपस्थितान्द्वारमुपेत्य विष्ठितान्॥', 'tataḥ purastāt sahasā vinirgato mahīpatīn dvāragatān vilokayan
dadarśa paurān vividhān mahādhanān upasthitān dvāram upetya viṣṭhitān', null, 2012024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 13 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-13-1', 1, 'Ayodhya Kanda, Sarga 13, Verse 1', 'ते तु तां रजनीमुष्य ब्राह्मणा वेदपारगाः।
उपतस्थुरुपस्थानं सहराजपुरोहिताः॥', 'te tu tāṃ rajanīm uṣya brāhmaṇā vedapāragāḥ
upatasthur upasthānaṃ saharājapurohitāḥ', null, 2013001),
('ramayana-2-13-2', 2, 'Ayodhya Kanda, Sarga 13, Verse 2', 'अमात्या बलमुख्याश्च मुख्या ये निगमस्य च।
राघवस्याभिषेकार्थे प्रीयमाणास्तु संगताः॥', 'amātyā balamukhyāś ca mukhyā ye nigamasya ca
rāghavasyābhiṣekārthe prīyamāṇās tu saṃgatāḥ', null, 2013002),
('ramayana-2-13-3', 3, 'Ayodhya Kanda, Sarga 13, Verse 3', 'उदिते विमले सूर्ये पुष्ये चाभ्यागतेऽहनि।
अभिषेकाय रामस्य द्विजेन्द्रैरुपकल्पितम्॥', 'udite vimale sūrye puṣye cābhyāgate ''hani
abhiṣekāya rāmasya dvijendrair upakalpitam', null, 2013003),
('ramayana-2-13-4', 4, 'Ayodhya Kanda, Sarga 13, Verse 4', 'काञ्चना जलकुम्भाश्च भद्रपीठं स्वलंकृतम्।
रामश्च सम्यगास्तीर्णो भास्वरा व्याघ्रचर्मणा॥', 'kāñcanā jalakumbhāś ca bhadrapīṭhaṃ svalaṃkṛtam
rāmaś ca samyagāstīrṇo bhāsvarā vyāghracarmaṇā', null, 2013004),
('ramayana-2-13-5', 5, 'Ayodhya Kanda, Sarga 13, Verse 5', 'गङ्गायमुनयोः पुण्यात्संगमादाहृतं जलम्।
याश्चान्याः सरितः पुण्या ह्रदाः कूपाः सरांसि च॥', 'gaṅgāyamunayoḥ puṇyāt saṃgamād āhṛtaṃ jalam
yāś cānyāḥ saritaḥ puṇyā hradāḥ kūpāḥ sarāṃsi ca', null, 2013005),
('ramayana-2-13-6', 6, 'Ayodhya Kanda, Sarga 13, Verse 6', 'प्राग्वाहाश्चोर्ध्ववाहाश्च तिर्यग्वाहाः समाहिताः।
ताभ्यश्चैवाहृतं तोयं समुद्रेभ्यश्च सर्वशः॥', 'prāgvāhāś cordhvavāhāś ca tiryagvāhāḥ samāhitāḥ
tābhyaś caivāhṛtaṃ toyaṃ samudrebhyaś ca sarvaśaḥ', null, 2013006),
('ramayana-2-13-7', 7, 'Ayodhya Kanda, Sarga 13, Verse 7', 'क्षौद्रं दधि घृतं लाजा दर्भाः सुमनसः पयः।
सलाजाः क्षीरिभिश्छन्ना घटाः काञ्चनराजताः।
पद्मोत्पलयुता भान्ति पूर्णाः परमवारिणा॥', 'kṣaudraṃ dadhi ghṛtaṃ lājā darbhāḥ sumanasaḥ payaḥ
salājāḥ kṣīribhiś channā ghaṭāḥ kāñcanarājatāḥ
padmotpalayutā bhānti pūrṇāḥ paramavāriṇā', null, 2013007),
('ramayana-2-13-8', 8, 'Ayodhya Kanda, Sarga 13, Verse 8', 'चन्द्रांशुविकचप्रख्यं पाण्डुरं रत्नभूषितम्।
सज्जं तिष्ठति रामस्य वालव्यजनमुत्तमम्॥', 'candrāṃśuvikacaprakhyaṃ pāṇḍuraṃ ratnabhūṣitam
sajjaṃ tiṣṭhati rāmasya vālavyajanam uttamam', null, 2013008),
('ramayana-2-13-9', 9, 'Ayodhya Kanda, Sarga 13, Verse 9', 'चन्द्रमण्डलसंकाशमातपत्रं च पाण्डुरम्।
सज्जं द्युतिकरं श्रीमदभिषेकपुरस्कृतम्॥', 'candramaṇḍalasaṃkāśam ātapatraṃ ca pāṇḍuram
sajjaṃ dyutikaraṃ śrīmad abhiṣekapuraskṛtam', null, 2013009),
('ramayana-2-13-10', 10, 'Ayodhya Kanda, Sarga 13, Verse 10', 'पाण्डुरश्च वृषः सज्जः पाण्डुराश्वश्च सुस्थितः।
प्रस्रुतश्च गजः श्रीमानौपवाह्यः प्रतीक्षते॥', 'pāṇḍuraś ca vṛṣaḥ sajjaḥ pāṇḍurāśvaś ca susthitaḥ
prasrutaś ca gajaḥ śrīmān aupavāhyaḥ pratīkṣate', null, 2013010),
('ramayana-2-13-11', 11, 'Ayodhya Kanda, Sarga 13, Verse 11', 'अष्टौ कन्याश्च मङ्गल्याः सर्वाभरणभूषिताः।
वादित्राणि च सर्वाणि बन्दिनश्च तथापरे॥', 'aṣṭau kanyāś ca maṅgalyāḥ sarvābharaṇabhūṣitāḥ
vāditrāṇi ca sarvāṇi bandinaś ca tathāpare', null, 2013011),
('ramayana-2-13-12', 12, 'Ayodhya Kanda, Sarga 13, Verse 12', 'इक्ष्वाकूणां यथा राज्ये संभ्रियेताभिषेचनम्।
तथा जातीयामादाय राजपुत्राभिषेचनम्॥', 'ikṣvākūṇāṃ yathā rājye saṃbhriyetābhiṣecanam
tathā jātīyām ādāya rājaputrābhiṣecanam', null, 2013012),
('ramayana-2-13-13', 13, 'Ayodhya Kanda, Sarga 13, Verse 13', 'ते राजवचनात्तत्र समवेता महीपतिम्।
अपश्यन्तोऽब्रुवन्को नु राज्ञो नः प्रतिवेदयेत्॥', 'te rājavacanāt tatra samavetā mahīpatim
apaśyanto ''bruvan ko nu rājño naḥ prativedayet', null, 2013013),
('ramayana-2-13-14', 14, 'Ayodhya Kanda, Sarga 13, Verse 14', 'न पश्यामश्च राजानमुदितश्च दिवाकरः।
यौवराज्याभिषेकश्च सज्जो रामस्य धीमतः॥', 'na paśyāmaś ca rājānam uditaś ca divākaraḥ
yauvarājyābhiṣekaś ca sajjo rāmasya dhīmataḥ', null, 2013014),
('ramayana-2-13-15', 15, 'Ayodhya Kanda, Sarga 13, Verse 15', 'इति तेषु ब्रुवाणेषु सार्वभौमान्महीपतीन्।
अब्रवीत्तानिदं सर्वान्सुमन्त्रो राजसत्कृतः॥', 'iti teṣu bruvāṇeṣu sārvabhaumān mahīpatīn
abravīt tān idaṃ sarvān sumantro rājasatkṛtaḥ', null, 2013015),
('ramayana-2-13-16', 16, 'Ayodhya Kanda, Sarga 13, Verse 16', 'अयं पृच्छामि वचनात्सुखमायुष्मतामहम्।
राज्ञः संप्रतिबुद्धस्य यच्चागमनकारणम्॥', 'ayaṃ pṛcchāmi vacanāt sukham āyuṣmatām aham
rājñaḥ saṃpratibuddhasya yac cāgamanakāraṇam', null, 2013016),
('ramayana-2-13-17', 17, 'Ayodhya Kanda, Sarga 13, Verse 17', 'इत्युक्त्वान्तःपुरद्वारमाजगाम पुराणवित्।
आशीर्भिर्गुणयुक्ताभिरभितुष्टाव राघवम्॥', 'ity uktvāntaḥpuradvāram ājagāma purāṇavit
āśīrbhir guṇayuktābhir abhituṣṭāva rāghavam', null, 2013017),
('ramayana-2-13-18', 18, 'Ayodhya Kanda, Sarga 13, Verse 18', 'गता भगवती रात्रिरहः शिवमुपस्थितम्।
बुध्यस्व नृपशार्दूल कुरु कार्यमनन्तरम्॥', 'gatā bhagavatī rātrirahaḥ śivam upasthitam
budhyasva nṛpaśārdūla kuru kāryam anantaram', null, 2013018),
('ramayana-2-13-19', 19, 'Ayodhya Kanda, Sarga 13, Verse 19', 'ब्राह्मणा बलमुख्याश्च नैगमाश्चागता नृप।
दर्शनं प्रतिकाङ्क्षन्ते प्रतिबुध्यस्व राघव॥', 'brāhmaṇā balamukhyāś ca naigamāś cāgatā nṛpa
darśanaṃ pratikāṅkṣante pratibudhyasva rāghava', null, 2013019),
('ramayana-2-13-20', 20, 'Ayodhya Kanda, Sarga 13, Verse 20', 'स्तुवन्तं तं तदा सूतं सुमन्त्रं मन्त्रकोविदम्।
प्रतिबुध्य ततो राजा इदं वचनमब्रवीत्॥', 'stuvantaṃ taṃ tadā sūtaṃ sumantraṃ mantrakovidam
pratibudhya tato rājā idaṃ vacanam abravīt', null, 2013020),
('ramayana-2-13-21', 21, 'Ayodhya Kanda, Sarga 13, Verse 21', 'न चैव संप्रसुतोऽहमानयेदाशु राघवम्।
इति राजा दशरथः सूतं तत्रान्वशात्पुनः॥', 'na caiva saṃprasuto ''ham ānayed āśu rāghavam
iti rājā daśarathaḥ sūtaṃ tatrānvaśāt punaḥ', null, 2013021),
('ramayana-2-13-22', 22, 'Ayodhya Kanda, Sarga 13, Verse 22', 'स राजवचनं श्रुत्वा शिरसा प्रतिपूज्य तम्।
निर्जगाम नृपावासान्मन्यमानः प्रियं महत्॥', 'sa rājavacanaṃ śrutvā śirasā pratipūjya tam
nirjagāma nṛpāvāsān manyamānaḥ priyaṃ mahat', null, 2013022),
('ramayana-2-13-23', 23, 'Ayodhya Kanda, Sarga 13, Verse 23', 'प्रपन्नो राजमार्गं च पताका ध्वजशोभितम्।
स सूतस्तत्र शुश्राव रामाधिकरणाः कथाः॥', 'prapanno rājamārgaṃ ca patākā dhvajaśobhitam
sa sūtas tatra śuśrāva rāmādhikaraṇāḥ kathāḥ', null, 2013023),
('ramayana-2-13-24', 24, 'Ayodhya Kanda, Sarga 13, Verse 24', 'ततो ददर्श रुचिरं कैलाससदृशप्रभम्।
रामवेश्म सुमन्त्रस्तु शक्रवेश्मसमप्रभम्॥', 'tato dadarśa ruciraṃ kailāsasadṛśaprabham
rāmaveśma sumantras tu śakraveśmasamaprabham', null, 2013024),
('ramayana-2-13-25', 25, 'Ayodhya Kanda, Sarga 13, Verse 25', 'महाकपाटपिहितं वितर्दिशतशोभितम्।
काञ्चनप्रतिमैकाग्रं मणिविद्रुमतोरणम्॥', 'mahākapāṭapihitaṃ vitardiśataśobhitam
kāñcanapratimaikāgraṃ maṇividrumatoraṇam', null, 2013025),
('ramayana-2-13-26', 26, 'Ayodhya Kanda, Sarga 13, Verse 26', 'शारदाभ्रघनप्रख्यं दीप्तं मेरुगुहोपमम्।
दामभिर्वरमाल्यानां सुमहद्भिरलंकृतम्॥', 'śāradābhraghanaprakhyaṃ dīptaṃ meruguhopamam
dāmabhir varamālyānāṃ sumahadbhir alaṃkṛtam', null, 2013026),
('ramayana-2-13-27', 27, 'Ayodhya Kanda, Sarga 13, Verse 27', 'स वाजियुक्तेन रथेन सारथिर्नराकुलं राजकुलं विलोकयन्।
ततः समासाद्य महाधनं महत्प्रहृष्टरोमा स बभूव सारथिः॥', 'sa vājiyuktena rathena sārathir narākulaṃ rājakulaṃ vilokayan
tataḥ samāsādya mahādhanaṃ mahat prahṛṣṭaromā sa babhūva sārathiḥ', null, 2013027),
('ramayana-2-13-28', 28, 'Ayodhya Kanda, Sarga 13, Verse 28', 'तदद्रिकूटाचलमेघसंनिभं महाविमानोत्तमवेश्मसंघवत्।
अवार्यमाणः प्रविवेश सारथिः प्रभूतरत्नं मकरो यथार्णवम्॥', 'tad adrikūṭācalameghasaṃnibhaṃ mahāvimānottamaveśmasaṃghavat
avāryamāṇaḥ praviveśa sārathiḥ prabhūtaratnaṃ makaro yathārṇavam', null, 2013028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 14 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-14-1', 1, 'Ayodhya Kanda, Sarga 14, Verse 1', 'स तदन्तःपुरद्वारं समतीत्य जनाकुलम्।
प्रविविक्तां ततः कक्ष्यामाससाद पुराणवित्॥', 'sa tad antaḥpuradvāraṃ samatītya janākulam
praviviktāṃ tataḥ kakṣyām āsasāda purāṇavit', null, 2014001),
('ramayana-2-14-2', 2, 'Ayodhya Kanda, Sarga 14, Verse 2', 'प्रासकार्मुकबिभ्रद्भिर्युवभिर्मृष्टकुण्डलैः।
अप्रमादिभिरेकाग्रैः स्वनुरक्तैरधिष्ठिताम्॥', 'prāsakārmukabibhradbhir yuvabhir mṛṣṭakuṇḍalaiḥ
apramādibhir ekāgraiḥ svanuraktair adhiṣṭhitām', null, 2014002),
('ramayana-2-14-3', 3, 'Ayodhya Kanda, Sarga 14, Verse 3', 'तत्र काषायिणो वृद्धान्वेत्रपाणीन्स्वलंकृतान्।
ददर्श विष्ठितान्द्वारि स्त्र्यध्यक्षान्सुसमाहितान्॥', 'tatra kāṣāyiṇo vṛddhān vetrapāṇīn svalaṃkṛtān
dadarśa viṣṭhitān dvāri stryadhyakṣān susamāhitān', null, 2014003),
('ramayana-2-14-4', 4, 'Ayodhya Kanda, Sarga 14, Verse 4', 'ते समीक्ष्य समायान्तं रामप्रियचिकीर्षवः।
सहभार्याय रामाय क्षिप्रमेवाचचक्षिरे॥', 'te samīkṣya samāyāntaṃ rāmapriyacikīrṣavaḥ
sahabhāryāya rāmāya kṣipram evācacakṣire', null, 2014004),
('ramayana-2-14-5', 5, 'Ayodhya Kanda, Sarga 14, Verse 5', 'प्रतिवेदितमाज्ञाय सूतमभ्यन्तरं पितुः।
तत्रैवानाययामास राघवः प्रियकाम्यया॥', 'prativeditam ājñāya sūtam abhyantaraṃ pituḥ
tatraivānāyayām āsa rāghavaḥ priyakāmyayā', null, 2014005),
('ramayana-2-14-6', 6, 'Ayodhya Kanda, Sarga 14, Verse 6', 'तं वैश्रवणसंकाशमुपविष्टं स्वलंकृतम्।
दादर्श सूतः पर्यङ्के सौवणो सोत्तरच्छदे॥', 'taṃ vaiśravaṇasaṃkāśam upaviṣṭaṃ svalaṃkṛtam
dādarśa sūtaḥ paryaṅke sauvaṇo sottaracchade', null, 2014006),
('ramayana-2-14-7', 7, 'Ayodhya Kanda, Sarga 14, Verse 7', 'वराहरुधिराभेण शुचिना च सुगन्धिना।
अनुलिप्तं परार्ध्येन चन्दनेन परंतपम्॥', 'varāharudhirābheṇa śucinā ca sugandhinā
anuliptaṃ parārdhyena candanena paraṃtapam', null, 2014007),
('ramayana-2-14-8', 8, 'Ayodhya Kanda, Sarga 14, Verse 8', 'स्थितया पार्श्वतश्चापि वालव्यजनहस्तया।
उपेतं सीतया भूयश्चित्रया शशिनं यथा॥', 'sthitayā pārśvataś cāpi vālavyajanahastayā
upetaṃ sītayā bhūyaś citrayā śaśinaṃ yathā', null, 2014008),
('ramayana-2-14-9', 9, 'Ayodhya Kanda, Sarga 14, Verse 9', 'तं तपन्तमिवादित्यमुपपन्नं स्वतेजसा।
ववन्दे वरदं बन्दी नियमज्ञो विनीतवत्॥', 'taṃ tapantam ivādityam upapannaṃ svatejasā
vavande varadaṃ bandī niyamajño vinītavat', null, 2014009),
('ramayana-2-14-10', 10, 'Ayodhya Kanda, Sarga 14, Verse 10', 'प्राञ्जलिस्तु सुखं पृष्ट्वा विहारशयनासने।
राजपुत्रमुवाचेदं सुमन्त्रो राजसत्कृतः॥', 'prāñjalis tu sukhaṃ pṛṣṭvā vihāraśayanāsane
rājaputram uvācedaṃ sumantro rājasatkṛtaḥ', null, 2014010),
('ramayana-2-14-11', 11, 'Ayodhya Kanda, Sarga 14, Verse 11', 'कौसल्या सुप्रभा देव पिता त्वं द्रष्टुमिच्छति।
महिष्या सह कैकेय्या गम्यतां तत्र माचिरम्॥', 'kausalyā suprabhā deva pitā tvaṃ draṣṭum icchati
mahiṣyā saha kaikeyyā gamyatāṃ tatra māciram', null, 2014011),
('ramayana-2-14-12', 12, 'Ayodhya Kanda, Sarga 14, Verse 12', 'एवमुक्तस्तु संहृष्टो नरसिंहो महाद्युतिः।
ततः संमानयामास सीतामिदमुवाच ह॥', 'evam uktas tu saṃhṛṣṭo narasiṃho mahādyutiḥ
tataḥ saṃmānayām āsa sītām idam uvāca ha', null, 2014012),
('ramayana-2-14-13', 13, 'Ayodhya Kanda, Sarga 14, Verse 13', 'देवि देवश्च देवी च समागम्य मदन्तरे।
मन्त्रेयेते ध्रुवं किं चिदभिषेचनसंहितम्॥', 'devi devaś ca devī ca samāgamya madantare
mantreyete dhruvaṃ kiṃ cid abhiṣecanasaṃhitam', null, 2014013),
('ramayana-2-14-14', 14, 'Ayodhya Kanda, Sarga 14, Verse 14', 'लक्षयित्वा ह्यभिप्रायं प्रियकामा सुदक्षिणा।
संचोदयति राजानं मदर्थं मदिरेक्षणा॥', 'lakṣayitvā hy abhiprāyaṃ priyakāmā sudakṣiṇā
saṃcodayati rājānaṃ madarthaṃ madirekṣaṇā', null, 2014014),
('ramayana-2-14-15', 15, 'Ayodhya Kanda, Sarga 14, Verse 15', 'यादृशी परिषत्तत्र तादृशो दूत आगतः।
ध्रुवमद्यैव मां राजा यौवराज्येऽभिषेक्ष्यति॥', 'yādṛśī pariṣat tatra tādṛśo dūta āgataḥ
dhruvam adyaiva māṃ rājā yauvarājye ''bhiṣekṣyati', null, 2014015),
('ramayana-2-14-16', 16, 'Ayodhya Kanda, Sarga 14, Verse 16', 'हन्त शीघ्रमितो गत्वा द्रक्ष्यामि च महीपतिः।
सह त्वं परिवारेण सुखमास्स्व रमस्य च॥', 'hanta śīghram ito gatvā drakṣyāmi ca mahīpatiḥ
saha tvaṃ parivāreṇa sukham āssva ramasya ca', null, 2014016),
('ramayana-2-14-17', 17, 'Ayodhya Kanda, Sarga 14, Verse 17', 'पतिसंमानिता सीता भर्तारमसितेक्षणा।
आद्वारमनुवव्राज मङ्गलान्यभिदध्युषी॥', 'patisaṃmānitā sītā bhartāram asitekṣaṇā
ādvāram anuvavrāja maṅgalāny abhidadhyuṣī', null, 2014017),
('ramayana-2-14-18', 18, 'Ayodhya Kanda, Sarga 14, Verse 18', 'स सर्वानर्थिनो दृष्ट्वा समेत्य प्रतिनन्द्य च।
ततः पावकसंकाशमारुरोह रथोत्तमम्॥', 'sa sarvān arthino dṛṣṭvā sametya pratinandya ca
tataḥ pāvakasaṃkāśam āruroha rathottamam', null, 2014018),
('ramayana-2-14-19', 19, 'Ayodhya Kanda, Sarga 14, Verse 19', 'मुष्णन्तमिव चक्षूंषि प्रभया हेमवर्चसं।
करेणुशिशुकल्पैश्च युक्तं परमवाजिभिः॥', 'muṣṇantam iva cakṣūṃṣi prabhayā hemavarcasaṃ
kareṇuśiśukalpaiś ca yuktaṃ paramavājibhiḥ', null, 2014019),
('ramayana-2-14-20', 20, 'Ayodhya Kanda, Sarga 14, Verse 20', 'हरियुक्तं सहस्राक्षो रथमिन्द्र इवाशुगम्।
प्रययौ तूर्णमास्थाय राघवो ज्वलितः श्रिया॥', 'hariyuktaṃ sahasrākṣo ratham indra ivāśugam
prayayau tūrṇam āsthāya rāghavo jvalitaḥ śriyā', null, 2014020),
('ramayana-2-14-21', 21, 'Ayodhya Kanda, Sarga 14, Verse 21', 'स पर्जन्य इवाकाशे स्वनवानभिनादयन्।
निकेतान्निर्ययौ श्रीमान्महाभ्रादिव चन्द्रमाः॥', 'sa parjanya ivākāśe svanavān abhinādayan
niketān niryayau śrīmān mahābhrād iva candramāḥ', null, 2014021),
('ramayana-2-14-22', 22, 'Ayodhya Kanda, Sarga 14, Verse 22', 'छत्रचामरपाणिस्तु लक्ष्मणो राघवानुजः।
जुगोप भ्रातरं भ्राता रथमास्थाय पृष्ठतः॥', 'chatracāmarapāṇis tu lakṣmaṇo rāghavānujaḥ
jugopa bhrātaraṃ bhrātā ratham āsthāya pṛṣṭhataḥ', null, 2014022),
('ramayana-2-14-23', 23, 'Ayodhya Kanda, Sarga 14, Verse 23', 'ततो हलहलाशब्दस्तुमुलः समजायत।
तस्य निष्क्रममाणस्य जनौघस्य समन्ततः॥', 'tato halahalāśabdas tumulaḥ samajāyata
tasya niṣkramamāṇasya janaughasya samantataḥ', null, 2014023),
('ramayana-2-14-24', 24, 'Ayodhya Kanda, Sarga 14, Verse 24', 'स राघवस्तत्र कथाप्रलापं शुश्राव लोकस्य समागतस्य।
आत्माधिकारा विविधाश्च वाचः प्रहृष्टरूपस्य पुरे जनस्य॥', 'sa rāghavas tatra kathāpralāpaṃ śuśrāva lokasya samāgatasya
ātmādhikārā vividhāś ca vācaḥ prahṛṣṭarūpasya pure janasya', null, 2014024),
('ramayana-2-14-25', 25, 'Ayodhya Kanda, Sarga 14, Verse 25', 'एष श्रियं गच्छति राघवोऽद्य राजप्रसादाद्विपुलां गमिष्यन्।
एते वयं सर्वसमृद्धकामा येषामयं नो भविता प्रशास्ता।
लाभो जनस्यास्य यदेष सर्वं प्रपत्स्यते राष्ट्रमिदं चिराय॥', 'eṣa śriyaṃ gacchati rāghavo ''dya rājaprasādād vipulāṃ gamiṣyan
ete vayaṃ sarvasamṛddhakāmā yeṣām ayaṃ no bhavitā praśāstā
lābho janasyāsya yad eṣa sarvaṃ prapatsyate rāṣṭram idaṃ cirāya', null, 2014025),
('ramayana-2-14-26', 26, 'Ayodhya Kanda, Sarga 14, Verse 26', 'स घोषवद्भिश्च हयैः सनागैः पुरःसरैः स्वस्तिकसूतमागधैः।
महीयमानः प्रवरैश्च वादकैरभिष्टुतो वैश्रवणो यथा ययौ॥', 'sa ghoṣavadbhiś ca hayaiḥ sanāgaiḥ puraḥsaraiḥ svastikasūtamāgadhaiḥ
mahīyamānaḥ pravaraiś ca vādakair abhiṣṭuto vaiśravaṇo yathā yayau', null, 2014026),
('ramayana-2-14-27', 27, 'Ayodhya Kanda, Sarga 14, Verse 27', 'करेणुमातङ्गरथाश्वसंकुलं महाजनौघैः परिपूर्णचत्वरम्।
प्रभूतरत्नं बहुपण्यसंचयं ददर्श रामो रुचिरं महापथम्॥', 'kareṇumātaṅgarathāśvasaṃkulaṃ mahājanaughaiḥ paripūrṇacatvaram
prabhūtaratnaṃ bahupaṇyasaṃcayaṃ dadarśa rāmo ruciraṃ mahāpatham', null, 2014027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 15 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-15-1', 1, 'Ayodhya Kanda, Sarga 15, Verse 1', 'स रामो रथमास्थाय संप्रहृष्टसुहृज्जनः।
अपश्यन्नगरं श्रीमान्नानाजनसमाकुलम्॥', 'sa rāmo ratham āsthāya saṃprahṛṣṭasuhṛjjanaḥ
apaśyan nagaraṃ śrīmān nānājanasamākulam', null, 2015001),
('ramayana-2-15-2', 2, 'Ayodhya Kanda, Sarga 15, Verse 2', 'स गृहैरभ्रसंकाशैः पाण्डुरैरुपशोभितम्।
राजमार्गं ययौ रामो मध्येनागरुधूपितम्॥', 'sa gṛhair abhrasaṃkāśaiḥ pāṇḍurair upaśobhitam
rājamārgaṃ yayau rāmo madhyenāgarudhūpitam', null, 2015002),
('ramayana-2-15-3', 3, 'Ayodhya Kanda, Sarga 15, Verse 3', 'शोभमानमसंबाधं तं राजपथमुत्तमम्।
संवृतं विविधैः पण्यैर्भक्ष्यैरुच्चावचैरपि॥', 'śobhamānam asaṃbādhaṃ taṃ rājapatham uttamam
saṃvṛtaṃ vividhaiḥ paṇyair bhakṣyair uccāvacair api', null, 2015003),
('ramayana-2-15-4', 4, 'Ayodhya Kanda, Sarga 15, Verse 4', 'आशीर्वादान्बहूञ्शृण्वन्सुहृद्भिः समुदीरितान्।
यथार्हं चापि संपूज्य सर्वानेव नरान्ययौ॥', 'āśīrvādān bahūñ śṛṇvan suhṛdbhiḥ samudīritān
yathārhaṃ cāpi saṃpūjya sarvān eva narān yayau', null, 2015004),
('ramayana-2-15-5', 5, 'Ayodhya Kanda, Sarga 15, Verse 5', 'पितामहैराचरितं तथैव प्रपितामहैः।
अद्योपादाय तं मार्गमभिषिक्तोऽनुपालय॥', 'pitāmahair ācaritaṃ tathaiva prapitāmahaiḥ
adyopādāya taṃ mārgam abhiṣikto ''nupālaya', null, 2015005),
('ramayana-2-15-6', 6, 'Ayodhya Kanda, Sarga 15, Verse 6', 'यथा स्म लालिताः पित्रा यथा पूर्वैः पितामहैः।
ततः सुखतरं सर्वे रामे वत्स्याम राजनि॥', 'yathā sma lālitāḥ pitrā yathā pūrvaiḥ pitāmahaiḥ
tataḥ sukhataraṃ sarve rāme vatsyāma rājani', null, 2015006),
('ramayana-2-15-7', 7, 'Ayodhya Kanda, Sarga 15, Verse 7', 'अलमद्य हि भुक्तेन परमार्थैरलं च नः।
यथा पश्याम निर्यान्तं रामं राज्ये प्रतिष्ठितम्॥', 'alam adya hi bhuktena paramārthair alaṃ ca naḥ
yathā paśyāma niryāntaṃ rāmaṃ rājye pratiṣṭhitam', null, 2015007),
('ramayana-2-15-8', 8, 'Ayodhya Kanda, Sarga 15, Verse 8', 'अतो हि न प्रियतरं नान्यत्किं चिद्भविष्यति।
यथाभिषेको रामस्य राज्येनामिततेजसः॥', 'ato hi na priyataraṃ nānyat kiṃ cid bhaviṣyati
yathābhiṣeko rāmasya rājyenāmitatejasaḥ', null, 2015008),
('ramayana-2-15-9', 9, 'Ayodhya Kanda, Sarga 15, Verse 9', 'एताश्चान्याश्च सुहृदामुदासीनः कथाः शुभाः।
आत्मसंपूजनीः शृण्वन्ययौ रामो महापथम्॥', 'etāś cānyāś ca suhṛdām udāsīnaḥ kathāḥ śubhāḥ
ātmasaṃpūjanīḥ śṛṇvan yayau rāmo mahāpatham', null, 2015009),
('ramayana-2-15-10', 10, 'Ayodhya Kanda, Sarga 15, Verse 10', 'न हि तस्मान्मनः कश्चिच्चक्षुषी वा नरोत्तमात्।
नरः शक्नोत्यपाक्रष्टुमतिक्रान्तेऽपि राघवे॥', 'na hi tasmān manaḥ kaś cic cakṣuṣī vā narottamāt
naraḥ śaknoty apākraṣṭum atikrānte ''pi rāghave', null, 2015010),
('ramayana-2-15-11', 11, 'Ayodhya Kanda, Sarga 15, Verse 11', 'सर्वेषां स हि धर्मात्मा वर्णानां कुरुते दयाम्।
चतुर्णां हि वयःस्थानां तेन ते तमनुव्रताः॥', 'sarveṣāṃ sa hi dharmātmā varṇānāṃ kurute dayām
caturṇāṃ hi vayaḥsthānāṃ tena te tam anuvratāḥ', null, 2015011),
('ramayana-2-15-12', 12, 'Ayodhya Kanda, Sarga 15, Verse 12', 'स राजकुलमासाद्य महेन्द्रभवनोपमम्।
राजपुत्रः पितुर्वेश्म प्रविवेश श्रिया ज्वलन्॥', 'sa rājakulam āsādya mahendrabhavanopamam
rājaputraḥ pitur veśma praviveśa śriyā jvalan', null, 2015012),
('ramayana-2-15-13', 13, 'Ayodhya Kanda, Sarga 15, Verse 13', 'स सर्वाः समतिक्रम्य कक्ष्या दशरथात्मजः।
संनिवर्त्य जनं सर्वं शुद्धान्तःपुरमभ्यगात्॥', 'sa sarvāḥ samatikramya kakṣyā daśarathātmajaḥ
saṃnivartya janaṃ sarvaṃ śuddhāntaḥpuram abhyagāt', null, 2015013),
('ramayana-2-15-14', 14, 'Ayodhya Kanda, Sarga 15, Verse 14', 'ततः प्रविष्टे पितुरन्तिकं तदा जनः स सर्वो मुदितो नृपात्मजे।
प्रतीक्षते तस्य पुनः स्म निर्गमं यथोदयं चन्द्रमसः सरित्पतिः॥', 'tataḥ praviṣṭe pitur antikaṃ tadā janaḥ sa sarvo mudito nṛpātmaje
pratīkṣate tasya punaḥ sma nirgamaṃ yathodayaṃ candramasaḥ saritpatiḥ', null, 2015014)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 16 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-16-1', 1, 'Ayodhya Kanda, Sarga 16, Verse 1', 'स ददर्शासने रामो निषण्णं पितरं शुभे।
कैकेयीसहितं दीनं मुखेन परिशुष्यता॥', 'sa dadarśāsane rāmo niṣaṇṇaṃ pitaraṃ śubhe
kaikeyīsahitaṃ dīnaṃ mukhena pariśuṣyatā', null, 2016001),
('ramayana-2-16-2', 2, 'Ayodhya Kanda, Sarga 16, Verse 2', 'स पितुश्चरणौ पूर्वमभिवाद्य विनीतवत्।
ततो ववन्दे चरणौ कैकेय्याः सुसमाहितः॥', 'sa pituś caraṇau pūrvam abhivādya vinītavat
tato vavande caraṇau kaikeyyāḥ susamāhitaḥ', null, 2016002),
('ramayana-2-16-3', 3, 'Ayodhya Kanda, Sarga 16, Verse 3', 'रामेत्युक्त्वा च वचनं वाष्पपर्याकुलेक्षणः।
शशाक नृपतिर्दीनो नेक्षितुं नाभिभाषितुम्॥', 'rāmety uktvā ca vacanaṃ vāṣpaparyākulekṣaṇaḥ
śaśāka nṛpatir dīno nekṣituṃ nābhibhāṣitum', null, 2016003),
('ramayana-2-16-4', 4, 'Ayodhya Kanda, Sarga 16, Verse 4', 'तदपूर्वं नरपतेर्दृष्ट्वा रूपं भयावहम्।
रामोऽपि भयमापन्नः पदा स्पृष्ट्वेव पन्नगम्॥', 'tad apūrvaṃ narapater dṛṣṭvā rūpaṃ bhayāvaham
rāmo ''pi bhayam āpannaḥ padā spṛṣṭveva pannagam', null, 2016004),
('ramayana-2-16-5', 5, 'Ayodhya Kanda, Sarga 16, Verse 5', 'इन्द्रियैरप्रहृष्टैस्तं शोकसंतापकर्शितम्।
निःश्वसन्तं महाराजं व्यथिताकुलचेतसं॥', 'indriyair aprahṛṣṭais taṃ śokasaṃtāpakarśitam
niḥśvasantaṃ mahārājaṃ vyathitākulacetasaṃ', null, 2016005),
('ramayana-2-16-6', 6, 'Ayodhya Kanda, Sarga 16, Verse 6', 'ऊर्मि मालिनमक्षोभ्यं क्षुभ्यन्तमिव सागरम्।
उपप्लुतमिवादित्यमुक्तानृतमृषिं यथा॥', 'ūrmi mālinam akṣobhyaṃ kṣubhyantam iva sāgaram
upaplutam ivādityam uktānṛtam ṛṣiṃ yathā', null, 2016006),
('ramayana-2-16-7', 7, 'Ayodhya Kanda, Sarga 16, Verse 7', 'अचिन्त्यकल्पं हि पितुस्तं शोकमुपधारयन्।
बभूव संरब्धतरः समुद्र इव पर्वणि॥', 'acintyakalpaṃ hi pitus taṃ śokam upadhārayan
babhūva saṃrabdhataraḥ samudra iva parvaṇi', null, 2016007),
('ramayana-2-16-8', 8, 'Ayodhya Kanda, Sarga 16, Verse 8', 'चिन्तयामास च तदा रामः पितृहिते रतः।
किंस्विदद्यैव नृपतिर्न मां प्रत्यभिनन्दति॥', 'cintayām āsa ca tadā rāmaḥ pitṛhite rataḥ
kiṃsvid adyaiva nṛpatir na māṃ pratyabhinandati', null, 2016008),
('ramayana-2-16-9', 9, 'Ayodhya Kanda, Sarga 16, Verse 9', 'अन्यदा मां पिता दृष्ट्वा कुपितोऽपि प्रसीदति।
तस्य मामद्य संप्रेक्ष्य किमायासः प्रवर्तते॥', 'anyadā māṃ pitā dṛṣṭvā kupito ''pi prasīdati
tasya mām adya saṃprekṣya kimāyāsaḥ pravartate', null, 2016009),
('ramayana-2-16-10', 10, 'Ayodhya Kanda, Sarga 16, Verse 10', 'स दीन इव शोकार्तो विषण्णवदनद्युतिः।
कैकेयीमभिवाद्यैव रामो वचनमब्रवीत्॥', 'sa dīna iva śokārto viṣaṇṇavadanadyutiḥ
kaikeyīm abhivādyaiva rāmo vacanam abravīt', null, 2016010),
('ramayana-2-16-11', 11, 'Ayodhya Kanda, Sarga 16, Verse 11', 'कच्चिन्मया नापराद्धमज्ञानाद्येन मे पिता।
कुपितस्तन्ममाचक्ष्व त्वं चैवैनं प्रसादय॥', 'kaccin mayā nāparāddham ajñānād yena me pitā
kupitas tan mamācakṣva tvaṃ caivainaṃ prasādaya', null, 2016011),
('ramayana-2-16-12', 12, 'Ayodhya Kanda, Sarga 16, Verse 12', 'विवर्णवदनो दीनो न हि मामभिभाषते।
शारीरो मानसो वापि कच्चिदेनं न बाधते।
संतापो वाभितापो वा दुर्लभं हि सदा सुखम्॥', 'vivarṇavadano dīno na hi mām abhibhāṣate
śārīro mānaso vāpi kaccid enaṃ na bādhate
saṃtāpo vābhitāpo vā durlabhaṃ hi sadā sukham', null, 2016012),
('ramayana-2-16-13', 13, 'Ayodhya Kanda, Sarga 16, Verse 13', 'कच्चिन्न किं चिद्भरते कुमारे प्रियदर्शने।
शत्रुघ्ने वा महासत्त्वे मातॄणां वा ममाशुभम्॥', 'kaccin na kiṃ cid bharate kumāre priyadarśane
śatrughne vā mahāsattve mātṝṇāṃ vā mamāśubham', null, 2016013),
('ramayana-2-16-14', 14, 'Ayodhya Kanda, Sarga 16, Verse 14', 'अतोषयन्महाराजमकुर्वन्वा पितुर्वचः।
मुहूर्तमपि नेच्छेयं जीवितुं कुपिते नृपे॥', 'atoṣayan mahārājam akurvan vā pitur vacaḥ
muhūrtam api neccheyaṃ jīvituṃ kupite nṛpe', null, 2016014),
('ramayana-2-16-15', 15, 'Ayodhya Kanda, Sarga 16, Verse 15', 'यतोमूलं नरः पश्येत्प्रादुर्भावमिहात्मनः।
कथं तस्मिन्न वर्तेत प्रत्यक्षे सति दैवते॥', 'yatomūlaṃ naraḥ paśyet prādurbhāvam ihātmanaḥ
kathaṃ tasmin na varteta pratyakṣe sati daivate', null, 2016015),
('ramayana-2-16-16', 16, 'Ayodhya Kanda, Sarga 16, Verse 16', 'कच्चित्ते परुषं किं चिदभिमानात्पिता मम।
उक्तो भवत्या कोपेन यत्रास्य लुलितं मनः॥', 'kaccit te paruṣaṃ kiṃ cid abhimānāt pitā mama
ukto bhavatyā kopena yatrāsya lulitaṃ manaḥ', null, 2016016),
('ramayana-2-16-17', 17, 'Ayodhya Kanda, Sarga 16, Verse 17', 'एतदाचक्ष्व मे देवि तत्त्वेन परिपृच्छतः।
किंनिमित्तमपूर्वोऽयं विकारो मनुजाधिपे॥', 'etad ācakṣva me devi tattvena paripṛcchataḥ
kiṃnimittam apūrvo ''yaṃ vikāro manujādhipe', null, 2016017),
('ramayana-2-16-18', 18, 'Ayodhya Kanda, Sarga 16, Verse 18', 'अहं हि वचनाद्राज्ञः पतेयमपि पावके।
भक्षयेयं विषं तीक्ष्णं मज्जेयमपि चार्णवे।
नियुक्तो गुरुणा पित्रा नृपेण च हितेन च॥', 'ahaṃ hi vacanād rājñaḥ pateyam api pāvake
bhakṣayeyaṃ viṣaṃ tīkṣṇaṃ majjeyam api cārṇave
niyukto guruṇā pitrā nṛpeṇa ca hitena ca', null, 2016018),
('ramayana-2-16-19', 19, 'Ayodhya Kanda, Sarga 16, Verse 19', 'तद्ब्रूहि वचनं देवि राज्ञो यदभिकाङ्क्षितम्।
करिष्ये प्रतिजाने च रामो द्विर्नाभिभाषते॥', 'tad brūhi vacanaṃ devi rājño yad abhikāṅkṣitam
kariṣye pratijāne ca rāmo dvir nābhibhāṣate', null, 2016019),
('ramayana-2-16-20', 20, 'Ayodhya Kanda, Sarga 16, Verse 20', 'तमार्जवसमायुक्तमनार्या सत्यवादिनम्।
उवाच रामं कैकेयी वचनं भृशदारुणम्॥', 'tam ārjavasamāyuktam anāryā satyavādinam
uvāca rāmaṃ kaikeyī vacanaṃ bhṛśadāruṇam', null, 2016020),
('ramayana-2-16-21', 21, 'Ayodhya Kanda, Sarga 16, Verse 21', 'पुरा देवासुरे युद्धे पित्रा ते मम राघव।
रक्षितेन वरौ दत्तौ सशल्येन महारणे॥', 'purā devāsure yuddhe pitrā te mama rāghava
rakṣitena varau dattau saśalyena mahāraṇe', null, 2016021),
('ramayana-2-16-22', 22, 'Ayodhya Kanda, Sarga 16, Verse 22', 'तत्र मे याचितो राजा भरतस्याभिषेचनम्।
गमनं दण्डकारण्ये तव चाद्यैव राघव॥', 'tatra me yācito rājā bharatasyābhiṣecanam
gamanaṃ daṇḍakāraṇye tava cādyaiva rāghava', null, 2016022),
('ramayana-2-16-23', 23, 'Ayodhya Kanda, Sarga 16, Verse 23', 'यदि सत्यप्रतिज्ञं त्वं पितरं कर्तुमिच्छसि।
आत्मानं च नररेष्ठ मम वाक्यमिदं शृणु॥', 'yadi satyapratijñaṃ tvaṃ pitaraṃ kartum icchasi
ātmānaṃ ca narareṣṭha mama vākyam idaṃ śṛṇu', null, 2016023),
('ramayana-2-16-24', 24, 'Ayodhya Kanda, Sarga 16, Verse 24', 'स निदेशे पितुस्तिष्ठ यथा तेन प्रतिश्रुतम्।
त्वयारण्यं प्रवेष्टव्यं नव वर्षाणि पञ्च च॥', 'sa nideśe pitus tiṣṭha yathā tena pratiśrutam
tvayāraṇyaṃ praveṣṭavyaṃ nava varṣāṇi pañca ca', null, 2016024),
('ramayana-2-16-25', 25, 'Ayodhya Kanda, Sarga 16, Verse 25', 'सप्त सप्त च वर्षाणि दण्डकारण्यमाश्रितः।
अभिषेकमिमं त्यक्त्वा जटाचीरधरो वस॥', 'sapta sapta ca varṣāṇi daṇḍakāraṇyam āśritaḥ
abhiṣekam imaṃ tyaktvā jaṭācīradharo vasa', null, 2016025),
('ramayana-2-16-26', 26, 'Ayodhya Kanda, Sarga 16, Verse 26', 'भरतः कोसलपुरे प्रशास्तु वसुधामिमाम्।
नानारत्नसमाकीर्णां सवाजिरथकुञ्जराम्॥', 'bharataḥ kosalapure praśāstu vasudhām imām
nānāratnasamākīrṇāṃ savājirathakuñjarām', null, 2016026),
('ramayana-2-16-27', 27, 'Ayodhya Kanda, Sarga 16, Verse 27', 'तदप्रियममित्रघ्नो वचनं मरणोपमम्।
श्रुत्वा न विव्यथे रामः कैकेयीं चेदमब्रवीत्॥', 'tad apriyam amitraghno vacanaṃ maraṇopamam
śrutvā na vivyathe rāmaḥ kaikeyīṃ cedam abravīt', null, 2016027),
('ramayana-2-16-28', 28, 'Ayodhya Kanda, Sarga 16, Verse 28', 'एवमस्तु गमिष्यामि वनं वस्तुमहं त्वतः।
जटाचीरधरो राज्ञः प्रतिज्ञामनुपालयन्॥', 'evam astu gamiṣyāmi vanaṃ vastum ahaṃ tv ataḥ
jaṭācīradharo rājñaḥ pratijñām anupālayan', null, 2016028),
('ramayana-2-16-29', 29, 'Ayodhya Kanda, Sarga 16, Verse 29', 'इदं तु ज्ञातुमिच्छामि किमर्थं मां महीपतिः।
नाभिनन्दति दुर्धर्षो यथापुरमरिंदमः॥', 'idaṃ tu jñātum icchāmi kimarthaṃ māṃ mahīpatiḥ
nābhinandati durdharṣo yathāpuram ariṃdamaḥ', null, 2016029),
('ramayana-2-16-30', 30, 'Ayodhya Kanda, Sarga 16, Verse 30', 'मन्युर्न च त्वया कार्यो देवि ब्रूहि तवाग्रतः।
यास्यामि भव सुप्रीता वनं चीरजटाधरः॥', 'manyur na ca tvayā kāryo devi brūhi tavāgrataḥ
yāsyāmi bhava suprītā vanaṃ cīrajaṭādharaḥ', null, 2016030),
('ramayana-2-16-31', 31, 'Ayodhya Kanda, Sarga 16, Verse 31', 'हितेन गुरुणा पित्रा कृतज्ञेन नृपेण च।
नियुज्यमानो विश्रब्धं किं न कुर्यादहं प्रियम्॥', 'hitena guruṇā pitrā kṛtajñena nṛpeṇa ca
niyujyamāno viśrabdhaṃ kiṃ na kuryād ahaṃ priyam', null, 2016031),
('ramayana-2-16-32', 32, 'Ayodhya Kanda, Sarga 16, Verse 32', 'अलीकं मानसं त्वेकं हृदयं दहतीव मे।
स्वयं यन्नाह मां राजा भरतस्याभिषेचनम्॥', 'alīkaṃ mānasaṃ tv ekaṃ hṛdayaṃ dahatīva me
svayaṃ yan nāha māṃ rājā bharatasyābhiṣecanam', null, 2016032),
('ramayana-2-16-33', 33, 'Ayodhya Kanda, Sarga 16, Verse 33', 'अहं हि सीतां राज्यं च प्राणानिष्टान्धनानि च।
हृष्टो भ्रात्रे स्वयं दद्यां भरतायाप्रचोदितः॥', 'ahaṃ hi sītāṃ rājyaṃ ca prāṇān iṣṭān dhanāni ca
hṛṣṭo bhrātre svayaṃ dadyāṃ bharatāyāpracoditaḥ', null, 2016033),
('ramayana-2-16-34', 34, 'Ayodhya Kanda, Sarga 16, Verse 34', 'किं पुनर्मनुजेन्द्रेण स्वयं पित्रा प्रचोदितः।
तव च प्रियकामार्थं प्रतिज्ञामनुपालयन्॥', 'kiṃ punar manujendreṇa svayaṃ pitrā pracoditaḥ
tava ca priyakāmārthaṃ pratijñām anupālayan', null, 2016034),
('ramayana-2-16-35', 35, 'Ayodhya Kanda, Sarga 16, Verse 35', 'तदाश्वासय हीमं त्वं किं न्विदं यन्महीपतिः।
वसुधासक्तनयनो मन्दमश्रूणि मुञ्चति॥', 'tad āśvāsaya hīmaṃ tvaṃ kiṃ nv idaṃ yan mahīpatiḥ
vasudhāsaktanayano mandam aśrūṇi muñcati', null, 2016035),
('ramayana-2-16-36', 36, 'Ayodhya Kanda, Sarga 16, Verse 36', 'गच्छन्तु चैवानयितुं दूताः शीघ्रजवैर्हयैः।
भरतं मातुलकुलादद्यैव नृपशासनात्॥', 'gacchantu caivānayituṃ dūtāḥ śīghrajavair hayaiḥ
bharataṃ mātulakulād adyaiva nṛpaśāsanāt', null, 2016036),
('ramayana-2-16-37', 37, 'Ayodhya Kanda, Sarga 16, Verse 37', 'दण्डकारण्यमेषोऽहमितो गच्छामि सत्वरः।
अविचार्य पितुर्वाक्यं समावस्तुं चतुर्दश॥', 'daṇḍakāraṇyam eṣo ''ham ito gacchāmi satvaraḥ
avicārya pitur vākyaṃ samāvastuṃ caturdaśa', null, 2016037),
('ramayana-2-16-38', 38, 'Ayodhya Kanda, Sarga 16, Verse 38', 'सा हृष्टा तस्य तद्वाक्यं श्रुत्वा रामस्य कैकयी।
प्रस्थानं श्रद्दधाना हि त्वरयामास राघवम्॥', 'sā hṛṣṭā tasya tadvākyaṃ śrutvā rāmasya kaikayī
prasthānaṃ śraddadhānā hi tvarayām āsa rāghavam', null, 2016038),
('ramayana-2-16-39', 39, 'Ayodhya Kanda, Sarga 16, Verse 39', 'एवं भवतु यास्यन्ति दूताः शीघ्रजवैर्हयैः।
भरतं मातुलकुलादुपावर्तयितुं नराः॥', 'evaṃ bhavatu yāsyanti dūtāḥ śīghrajavair hayaiḥ
bharataṃ mātulakulād upāvartayituṃ narāḥ', null, 2016039),
('ramayana-2-16-40', 40, 'Ayodhya Kanda, Sarga 16, Verse 40', 'तव त्वहं क्षमं मन्ये नोत्सुकस्य विलम्बनम्।
राम तस्मादितः शीघ्रं वनं त्वं गन्तुमर्हसि॥', 'tava tv ahaṃ kṣamaṃ manye notsukasya vilambanam
rāma tasmād itaḥ śīghraṃ vanaṃ tvaṃ gantum arhasi', null, 2016040),
('ramayana-2-16-41', 41, 'Ayodhya Kanda, Sarga 16, Verse 41', 'व्रीडान्वितः स्वयं यच्च नृपस्त्वां नाभिभाषते।
नैतत्किं चिन्नरश्रेष्ठ मन्युरेषोऽपनीयताम्॥', 'vrīḍānvitaḥ svayaṃ yac ca nṛpas tvāṃ nābhibhāṣate
naitat kiṃ cin naraśreṣṭha manyur eṣo ''panīyatām', null, 2016041),
('ramayana-2-16-42', 42, 'Ayodhya Kanda, Sarga 16, Verse 42', 'यावत्त्वं न वनं यातः पुरादस्मादभित्वरन्।
पिता तावन्न ते राम स्नास्यते भोक्ष्यतेऽपि वा॥', 'yāvat tvaṃ na vanaṃ yātaḥ purād asmād abhitvaran
pitā tāvan na te rāma snāsyate bhokṣyate ''pi vā', null, 2016042),
('ramayana-2-16-43', 43, 'Ayodhya Kanda, Sarga 16, Verse 43', 'धिक्कष्टमिति निःश्वस्य राजा शोकपरिप्लुतः।
मूर्छितो न्यपतत्तस्मिन्पर्यङ्के हेमभूषिते॥', 'dhik kaṣṭam iti niḥśvasya rājā śokapariplutaḥ
mūrchito nyapatat tasmin paryaṅke hemabhūṣite', null, 2016043),
('ramayana-2-16-44', 44, 'Ayodhya Kanda, Sarga 16, Verse 44', 'रामोऽप्युत्थाप्य राजानं कैकेय्याभिप्रचोदितः।
कशयेवाहतो वाजी वनं गन्तुं कृतत्वरः॥', 'rāmo ''py utthāpya rājānaṃ kaikeyyābhipracoditaḥ
kaśayevāhato vājī vanaṃ gantuṃ kṛtatvaraḥ', null, 2016044),
('ramayana-2-16-45', 45, 'Ayodhya Kanda, Sarga 16, Verse 45', 'तदप्रियमनार्याया वचनं दारुणोदरम्।
श्रुत्वा गतव्यथो रामः कैकेयीं वाक्यमब्रवीत्॥', 'tad apriyam anāryāyā vacanaṃ dāruṇodaram
śrutvā gatavyatho rāmaḥ kaikeyīṃ vākyam abravīt', null, 2016045),
('ramayana-2-16-46', 46, 'Ayodhya Kanda, Sarga 16, Verse 46', 'नाहमर्थपरो देवि लोकमावस्तुमुत्सहे।
विद्धि मामृषिभिस्तुल्यं केवलं धर्ममास्थितम्॥', 'nāham arthaparo devi lokam āvastum utsahe
viddhi mām ṛṣibhis tulyaṃ kevalaṃ dharmam āsthitam', null, 2016046),
('ramayana-2-16-47', 47, 'Ayodhya Kanda, Sarga 16, Verse 47', 'यदत्रभवतः किं चिच्छक्यं कर्तुं प्रियं मया।
प्राणानपि परित्यज्य सर्वथा कृतमेव तत्॥', 'yad atrabhavataḥ kiṃ cic chakyaṃ kartuṃ priyaṃ mayā
prāṇān api parityajya sarvathā kṛtam eva tat', null, 2016047),
('ramayana-2-16-48', 48, 'Ayodhya Kanda, Sarga 16, Verse 48', 'न ह्यतो धर्मचरणं किं चिदस्ति महत्तरम्।
यथा पितरि शुश्रूषा तस्य वा वचनक्रिया॥', 'na hy ato dharmacaraṇaṃ kiṃ cid asti mahattaram
yathā pitari śuśrūṣā tasya vā vacanakriyā', null, 2016048),
('ramayana-2-16-49', 49, 'Ayodhya Kanda, Sarga 16, Verse 49', 'अनुक्तोऽप्यत्रभवता भवत्या वचनादहम्।
वने वत्स्यामि विजने वर्षाणीह चतुर्दश॥', 'anukto ''py atrabhavatā bhavatyā vacanād aham
vane vatsyāmi vijane varṣāṇīha caturdaśa', null, 2016049),
('ramayana-2-16-50', 50, 'Ayodhya Kanda, Sarga 16, Verse 50', 'न नूनं मयि कैकेयि किं चिदाशंससे गुणम्।
यद्राजानमवोचस्त्वं ममेश्वरतरा सती॥', 'na nūnaṃ mayi kaikeyi kiṃ cid āśaṃsase guṇam
yad rājānam avocas tvaṃ mameśvaratarā satī', null, 2016050),
('ramayana-2-16-51', 51, 'Ayodhya Kanda, Sarga 16, Verse 51', 'यावन्मातरमापृच्छे सीतां चानुनयाम्यहम्।
ततोऽद्यैव गमिष्यामि दण्डकानां महद्वनम्॥', 'yāvan mātaram āpṛcche sītāṃ cānunayāmy aham
tato ''dyaiva gamiṣyāmi daṇḍakānāṃ mahad vanam', null, 2016051),
('ramayana-2-16-52', 52, 'Ayodhya Kanda, Sarga 16, Verse 52', 'भरतः पालयेद्राज्यं शुश्रूषेच्च पितुर्यथा।
तथा भवत्या कर्तव्यं स हि धर्मः सनातनः॥', 'bharataḥ pālayed rājyaṃ śuśrūṣec ca pitur yathā
tathā bhavatyā kartavyaṃ sa hi dharmaḥ sanātanaḥ', null, 2016052),
('ramayana-2-16-53', 53, 'Ayodhya Kanda, Sarga 16, Verse 53', 'स रामस्य वचः श्रुत्वा भृशं दुःखहतः पिता।
शोकादशक्नुवन्बाष्पं प्ररुरोद महास्वनम्॥', 'sa rāmasya vacaḥ śrutvā bhṛśaṃ duḥkhahataḥ pitā
śokād aśaknuvan bāṣpaṃ praruroda mahāsvanam', null, 2016053),
('ramayana-2-16-54', 54, 'Ayodhya Kanda, Sarga 16, Verse 54', 'वन्दित्वा चरणौ रामो विसंज्ञस्य पितुस्तदा।
कैकेय्याश्चाप्यनार्याया निष्पपात महाद्युतिः॥', 'vanditvā caraṇau rāmo visaṃjñasya pitus tadā
kaikeyyāś cāpy anāryāyā niṣpapāta mahādyutiḥ', null, 2016054),
('ramayana-2-16-55', 55, 'Ayodhya Kanda, Sarga 16, Verse 55', 'स रामः पितरं कृत्वा कैकेयीं च प्रदक्षिणम्।
निष्क्रम्यान्तःपुरात्तस्मात्स्वं ददर्श सुहृज्जनम्॥', 'sa rāmaḥ pitaraṃ kṛtvā kaikeyīṃ ca pradakṣiṇam
niṣkramyāntaḥpurāt tasmāt svaṃ dadarśa suhṛjjanam', null, 2016055),
('ramayana-2-16-56', 56, 'Ayodhya Kanda, Sarga 16, Verse 56', 'तं बाष्पपरिपूर्णाक्षः पृष्ठतोऽनुजगाम ह।
लक्ष्मणः परमक्रुद्धः सुमित्रानन्दवर्धनः॥', 'taṃ bāṣpaparipūrṇākṣaḥ pṛṣṭhato ''nujagāma ha
lakṣmaṇaḥ paramakruddhaḥ sumitrānandavardhanaḥ', null, 2016056),
('ramayana-2-16-57', 57, 'Ayodhya Kanda, Sarga 16, Verse 57', 'आभिषेचनिकं भाण्डं कृत्वा रामः प्रदक्षिणम्।
शनैर्जगाम सापेक्षो दृष्टिं तत्राविचालयन्॥', 'ābhiṣecanikaṃ bhāṇḍaṃ kṛtvā rāmaḥ pradakṣiṇam
śanair jagāma sāpekṣo dṛṣṭiṃ tatrāvicālayan', null, 2016057),
('ramayana-2-16-58', 58, 'Ayodhya Kanda, Sarga 16, Verse 58', 'न चास्य महतीं लक्ष्मीं राज्यनाशोऽपकर्षति।
लोककान्तस्य कान्तत्वं शीतरश्मेरिव क्षपा॥', 'na cāsya mahatīṃ lakṣmīṃ rājyanāśo ''pakarṣati
lokakāntasya kāntatvaṃ śītaraśmer iva kṣapā', null, 2016058),
('ramayana-2-16-59', 59, 'Ayodhya Kanda, Sarga 16, Verse 59', 'न वनं गन्तुकामस्य त्यजतश्च वसुंधराम्।
सर्वलोकातिगस्येव लक्ष्यते चित्तविक्रिया॥', 'na vanaṃ gantukāmasya tyajataś ca vasuṃdharām
sarvalokātigasyeva lakṣyate cittavikriyā', null, 2016059),
('ramayana-2-16-60', 60, 'Ayodhya Kanda, Sarga 16, Verse 60', 'धारयन्मनसा दुःखमिन्द्रियाणि निगृह्य च।
प्रविवेशात्मवान्वेश्म मातुरप्रियशंसिवान्॥', 'dhārayan manasā duḥkham indriyāṇi nigṛhya ca
praviveśātmavān veśma māturapriyaśaṃsivān', null, 2016060),
('ramayana-2-16-61', 61, 'Ayodhya Kanda, Sarga 16, Verse 61', 'प्रविश्य वेश्मातिभृशं मुदान्वितं समीक्ष्य तां चार्थविपत्तिमागताम्।
न चैव रामोऽत्र जगाम विक्रियां सुहृज्जनस्यात्मविपत्तिशङ्कया॥', 'praviśya veśmātibhṛśaṃ mudānvitaṃ samīkṣya tāṃ cārthavipattim āgatām
na caiva rāmo ''tra jagāma vikriyāṃ suhṛjjanasyātmavipattiśaṅkayā', null, 2016061)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 17 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-17-1', 1, 'Ayodhya Kanda, Sarga 17, Verse 1', 'रामस्तु भृशमायस्तो निःश्वसन्निव कुञ्जरः।
जगाम सहितो भ्रात्रा मातुरन्तःपुरं वशी॥', 'rāmas tu bhṛśam āyasto niḥśvasann iva kuñjaraḥ
jagāma sahito bhrātrā mātur antaḥpuraṃ vaśī', null, 2017001),
('ramayana-2-17-2', 2, 'Ayodhya Kanda, Sarga 17, Verse 2', 'सोऽपश्यत्पुरुषं तत्र वृद्धं परमपूजितम्।
उपविष्टं गृहद्वारि तिष्ठतश्चापरान्बहून्॥', 'so ''paśyat puruṣaṃ tatra vṛddhaṃ paramapūjitam
upaviṣṭaṃ gṛhadvāri tiṣṭhataś cāparān bahūn', null, 2017002),
('ramayana-2-17-3', 3, 'Ayodhya Kanda, Sarga 17, Verse 3', 'प्रविश्य प्रथमां कक्ष्यां द्वितीयायां ददर्श सः।
ब्राह्मणान्वेदसंपन्नान्वृद्धान्राज्ञाभिसत्कृतान्॥', 'praviśya prathamāṃ kakṣyāṃ dvitīyāyāṃ dadarśa saḥ
brāhmaṇān vedasaṃpannān vṛddhān rājñābhisatkṛtān', null, 2017003),
('ramayana-2-17-4', 4, 'Ayodhya Kanda, Sarga 17, Verse 4', 'प्रणम्य रामस्तान्वृद्धांस्तृतीयायां ददर्श सः।
स्त्रियो वृद्धाश्च बालाश्च द्वाररक्षणतत्पराः॥', 'praṇamya rāmas tān vṛddhāṃs tṛtīyāyāṃ dadarśa saḥ
striyo vṛddhāś ca bālāś ca dvārarakṣaṇatatparāḥ', null, 2017004),
('ramayana-2-17-5', 5, 'Ayodhya Kanda, Sarga 17, Verse 5', 'वर्धयित्वा प्रहृष्टास्ताः प्रविश्य च गृहं स्त्रियः।
न्यवेदयन्त त्वरिता राम मातुः प्रियं तदा॥', 'vardhayitvā prahṛṣṭās tāḥ praviśya ca gṛhaṃ striyaḥ
nyavedayanta tvaritā rāma mātuḥ priyaṃ tadā', null, 2017005),
('ramayana-2-17-6', 6, 'Ayodhya Kanda, Sarga 17, Verse 6', 'कौसल्यापि तदा देवी रात्रिं स्थित्वा समाहिता।
प्रभाते त्वकरोत्पूजां विष्णोः पुत्रहितैषिणी॥', 'kausalyāpi tadā devī rātriṃ sthitvā samāhitā
prabhāte tv akarot pūjāṃ viṣṇoḥ putrahitaiṣiṇī', null, 2017006),
('ramayana-2-17-7', 7, 'Ayodhya Kanda, Sarga 17, Verse 7', 'सा क्षौमवसना हृष्टा नित्यं व्रतपरायणा।
अग्निं जुहोति स्म तदा मन्त्रवत्कृतमङ्गला॥', 'sā kṣaumavasanā hṛṣṭā nityaṃ vrataparāyaṇā
agniṃ juhoti sma tadā mantravat kṛtamaṅgalā', null, 2017007),
('ramayana-2-17-8', 8, 'Ayodhya Kanda, Sarga 17, Verse 8', 'प्रविश्य च तदा रामो मातुरन्तःपुरं शुभम्।
ददर्श मातरं तत्र हावयन्तीं हुताशनम्॥', 'praviśya ca tadā rāmo mātur antaḥpuraṃ śubham
dadarśa mātaraṃ tatra hāvayantīṃ hutāśanam', null, 2017008),
('ramayana-2-17-9', 9, 'Ayodhya Kanda, Sarga 17, Verse 9', 'सा चिरस्यात्मजं दृष्ट्वा मातृनन्दनमागतम्।
अभिचक्राम संहृष्टा किशोरं वडवा यथा॥', 'sā cirasyātmajaṃ dṛṣṭvā mātṛnandanam āgatam
abhicakrāma saṃhṛṣṭā kiśoraṃ vaḍavā yathā', null, 2017009),
('ramayana-2-17-10', 10, 'Ayodhya Kanda, Sarga 17, Verse 10', 'तमुवाच दुराधर्षं राघवं सुतमात्मनः।
कौसल्या पुत्रवात्सल्यादिदं प्रियहितं वचः॥', 'tam uvāca durādharṣaṃ rāghavaṃ sutam ātmanaḥ
kausalyā putravātsalyād idaṃ priyahitaṃ vacaḥ', null, 2017010),
('ramayana-2-17-11', 11, 'Ayodhya Kanda, Sarga 17, Verse 11', 'वृद्धानां धर्मशीलानां राजर्षीणां महात्मनाम्।
प्राप्नुह्यायुश्च कीर्तिं च धर्मं चोपहितं कुले॥', 'vṛddhānāṃ dharmaśīlānāṃ rājarṣīṇāṃ mahātmanām
prāpnuhy āyuś ca kīrtiṃ ca dharmaṃ copahitaṃ kule', null, 2017011),
('ramayana-2-17-12', 12, 'Ayodhya Kanda, Sarga 17, Verse 12', 'सत्यप्रतिज्ञं पितरं राजानं पश्य राघव।
अद्यैव हि त्वां धर्मात्मा यौवराज्येऽभिषेक्ष्यति॥', 'satyapratijñaṃ pitaraṃ rājānaṃ paśya rāghava
adyaiva hi tvāṃ dharmātmā yauvarājye ''bhiṣekṣyati', null, 2017012),
('ramayana-2-17-13', 13, 'Ayodhya Kanda, Sarga 17, Verse 13', 'मातरं राघवः किं चित्प्रसार्याञ्जलिमब्रवीत्।
स स्वभावविनीतश्च गौरवाच्च तदानतः॥', 'mātaraṃ rāghavaḥ kiṃ cit prasāryāñjalim abravīt
sa svabhāvavinītaś ca gauravāc ca tadānataḥ', null, 2017013),
('ramayana-2-17-14', 14, 'Ayodhya Kanda, Sarga 17, Verse 14', 'देवि नूनं न जानीषे महद्भयमुपस्थितम्।
इदं तव च दुःखाय वैदेह्या लक्ष्मणस्य च॥', 'devi nūnaṃ na jānīṣe mahad bhayam upasthitam
idaṃ tava ca duḥkhāya vaidehyā lakṣmaṇasya ca', null, 2017014),
('ramayana-2-17-15', 15, 'Ayodhya Kanda, Sarga 17, Verse 15', 'चतुर्दश हि वर्षाणि वत्स्यामि विजने वने।
मधुमूलफलैर्जीवन्हित्वा मुनिवदामिषम्॥', 'caturdaśa hi varṣāṇi vatsyāmi vijane vane
madhumūlaphalair jīvan hitvā munivad āmiṣam', null, 2017015),
('ramayana-2-17-16', 16, 'Ayodhya Kanda, Sarga 17, Verse 16', 'भरताय महाराजो यौवराज्यं प्रयच्छति।
मां पुनर्दण्डकारण्यं विवासयति तापसं॥', 'bharatāya mahārājo yauvarājyaṃ prayacchati
māṃ punar daṇḍakāraṇyaṃ vivāsayati tāpasaṃ', null, 2017016),
('ramayana-2-17-17', 17, 'Ayodhya Kanda, Sarga 17, Verse 17', 'तामदुःखोचितां दृष्ट्वा पतितां कदलीमिव।
रामस्तूत्थापयामास मातरं गतचेतसं॥', 'tām aduḥkhocitāṃ dṛṣṭvā patitāṃ kadalīm iva
rāmas tūtthāpayām āsa mātaraṃ gatacetasaṃ', null, 2017017),
('ramayana-2-17-18', 18, 'Ayodhya Kanda, Sarga 17, Verse 18', 'उपावृत्योत्थितां दीनां वडवामिव वाहिताम्।
पांशुगुण्ठितसर्वाग्नीं विममर्श च पाणिना॥', 'upāvṛtyotthitāṃ dīnāṃ vaḍavām iva vāhitām
pāṃśuguṇṭhitasarvāgnīṃ vimamarśa ca pāṇinā', null, 2017018),
('ramayana-2-17-19', 19, 'Ayodhya Kanda, Sarga 17, Verse 19', 'सा राघवमुपासीनमसुखार्ता सुखोचिता।
उवाच पुरुषव्याघ्रमुपशृण्वति लक्ष्मणे॥', 'sā rāghavam upāsīnam asukhārtā sukhocitā
uvāca puruṣavyāghram upaśṛṇvati lakṣmaṇe', null, 2017019),
('ramayana-2-17-20', 20, 'Ayodhya Kanda, Sarga 17, Verse 20', 'यदि पुत्र न जायेथा मम शोकाय राघव।
न स्म दुःखमतो भूयः पश्येयमहमप्रजा॥', 'yadi putra na jāyethā mama śokāya rāghava
na sma duḥkham ato bhūyaḥ paśyeyam aham aprajā', null, 2017020),
('ramayana-2-17-21', 21, 'Ayodhya Kanda, Sarga 17, Verse 21', 'एक एव हि वन्ध्यायाः शोको भवति मानवः।
अप्रजास्मीति संतापो न ह्यन्यः पुत्र विद्यते॥', 'eka eva hi vandhyāyāḥ śoko bhavati mānavaḥ
aprajāsmīti saṃtāpo na hy anyaḥ putra vidyate', null, 2017021),
('ramayana-2-17-22', 22, 'Ayodhya Kanda, Sarga 17, Verse 22', 'न दृष्टपूर्वं कल्याणं सुखं वा पतिपौरुषे।
अपि पुत्रे विपश्येयमिति रामास्थितं मया॥', 'na dṛṣṭapūrvaṃ kalyāṇaṃ sukhaṃ vā patipauruṣe
api putre vipaśyeyam iti rāmāsthitaṃ mayā', null, 2017022),
('ramayana-2-17-23', 23, 'Ayodhya Kanda, Sarga 17, Verse 23', 'सा बहून्यमनोज्ञानि वाक्यानि हृदयच्छिदाम्।
अहं श्रोष्ये सपत्नीनामवराणां वरा सती।
अतो दुःखतरं किं नु प्रमदानां भविष्यति॥', 'sā bahūny amanojñāni vākyāni hṛdayacchidām
ahaṃ śroṣye sapatnīnām avarāṇāṃ varā satī
ato duḥkhataraṃ kiṃ nu pramadānāṃ bhaviṣyati', null, 2017023),
('ramayana-2-17-24', 24, 'Ayodhya Kanda, Sarga 17, Verse 24', 'त्वयि संनिहितेऽप्येवमहमासं निराकृता।
किं पुनः प्रोषिते तात ध्रुवं मरणमेव मे॥', 'tvayi saṃnihite ''py evam aham āsaṃ nirākṛtā
kiṃ punaḥ proṣite tāta dhruvaṃ maraṇam eva me', null, 2017024),
('ramayana-2-17-25', 25, 'Ayodhya Kanda, Sarga 17, Verse 25', 'यो हि मां सेवते कश्चिदथ वाप्यनुवर्तते।
कैकेय्याः पुत्रमन्वीक्ष्य स जनो नाभिभाषते॥', 'yo hi māṃ sevate kaś cid atha vāpy anuvartate
kaikeyyāḥ putram anvīkṣya sa jano nābhibhāṣate', null, 2017025),
('ramayana-2-17-26', 26, 'Ayodhya Kanda, Sarga 17, Verse 26', 'दश सप्त च वर्षाणि तव जातस्य राघव।
अतीतानि प्रकाङ्क्षन्त्या मया दुःखपरिक्षयम्॥', 'daśa sapta ca varṣāṇi tava jātasya rāghava
atītāni prakāṅkṣantyā mayā duḥkhaparikṣayam', null, 2017026),
('ramayana-2-17-27', 27, 'Ayodhya Kanda, Sarga 17, Verse 27', 'उपवासैश्च योगैश्च बहुभिश्च परिश्रमैः।
दुःखं संवर्धितो मोघं त्वं हि दुर्गतया मया॥', 'upavāsaiś ca yogaiś ca bahubhiś ca pariśramaiḥ
duḥkhaṃ saṃvardhito moghaṃ tvaṃ hi durgatayā mayā', null, 2017027),
('ramayana-2-17-28', 28, 'Ayodhya Kanda, Sarga 17, Verse 28', 'स्थिरं तु हृदयं मन्ये ममेदं यन्न दीर्यते।
प्रावृषीव महानद्याः स्पृष्टं कूलं नवाम्भसा॥', 'sthiraṃ tu hṛdayaṃ manye mamedaṃ yan na dīryate
prāvṛṣīva mahānadyāḥ spṛṣṭaṃ kūlaṃ navāmbhasā', null, 2017028),
('ramayana-2-17-29', 29, 'Ayodhya Kanda, Sarga 17, Verse 29', 'ममैव नूनं मरणं न विद्यते न चावकाशोऽस्ति यमक्षये मम।
यदन्तकोऽद्यैव न मां जिहीर्षति प्रसह्य सिंहो रुदतीं मृगीमिव॥', 'mamaiva nūnaṃ maraṇaṃ na vidyate na cāvakāśo ''sti yamakṣaye mama
yad antako ''dyaiva na māṃ jihīrṣati prasahya siṃho rudatīṃ mṛgīm iva', null, 2017029),
('ramayana-2-17-30', 30, 'Ayodhya Kanda, Sarga 17, Verse 30', 'स्थिरं हि नूनं हृदयं ममायसं न भिद्यते यद्भुवि नावदीर्यते।
अनेन दुःखेन च देहमर्पितं ध्रुवं ह्यकाले मरणं न विद्यते॥', 'sthiraṃ hi nūnaṃ hṛdayaṃ mamāyasaṃ na bhidyate yad bhuvi nāvadīryate
anena duḥkhena ca deham arpitaṃ dhruvaṃ hy akāle maraṇaṃ na vidyate', null, 2017030),
('ramayana-2-17-31', 31, 'Ayodhya Kanda, Sarga 17, Verse 31', 'इदं तु दुःखं यदनर्थकानि मे व्रतानि दानानि च संयमाश्च हि।
तपश्च तप्तं यदपत्यकारणात्सुनिष्फलं बीजमिवोप्तमूषरे॥', 'idaṃ tu duḥkhaṃ yad anarthakāni me vratāni dānāni ca saṃyamāś ca hi
tapaś ca taptaṃ yad apatyakāraṇāt suniṣphalaṃ bījam ivoptam ūṣare', null, 2017031),
('ramayana-2-17-32', 32, 'Ayodhya Kanda, Sarga 17, Verse 32', 'यदि ह्यकाले मरणं स्वयेच्छया लभेत कश्चिद्गुरु दुःख कर्शितः।
गताहमद्यैव परेत संसदं विना त्वया धेनुरिवात्मजेन वै॥', 'yadi hy akāle maraṇaṃ svayecchayā labheta kaś cid guru duḥkha karśitaḥ
gatāham adyaiva pareta saṃsadaṃ vinā tvayā dhenur ivātmajena vai', null, 2017032),
('ramayana-2-17-33', 33, 'Ayodhya Kanda, Sarga 17, Verse 33', 'भृशमसुखममर्षिता तदा बहु विललाप समीक्ष्य राघवम्।
व्यसनमुपनिशाम्य सा महत्सुतमिव बद्धमवेक्ष्य किंनरी॥', 'bhṛśam asukham amarṣitā tadā bahu vilalāpa samīkṣya rāghavam
vyasanam upaniśāmya sā mahat sutam iva baddham avekṣya kiṃnarī', null, 2017033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 18 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-18-1', 1, 'Ayodhya Kanda, Sarga 18, Verse 1', 'तथा तु विलपन्तीं तां कौसल्यां राममातरम्।
उवाच लक्ष्मणो दीनस्तत्कालसदृशं वचः॥', 'tathā tu vilapantīṃ tāṃ kausalyāṃ rāmamātaram
uvāca lakṣmaṇo dīnas tat kālasadṛśaṃ vacaḥ', null, 2018001),
('ramayana-2-18-2', 2, 'Ayodhya Kanda, Sarga 18, Verse 2', 'न रोचते ममाप्येतदार्ये यद्राघवो वनम्।
त्यक्त्वा राज्यश्रियं गच्छेत्स्त्रिया वाक्यवशं गतः॥', 'na rocate mamāpy etad ārye yad rāghavo vanam
tyaktvā rājyaśriyaṃ gacchet striyā vākyavaśaṃ gataḥ', null, 2018002),
('ramayana-2-18-3', 3, 'Ayodhya Kanda, Sarga 18, Verse 3', 'विपरीतश्च वृद्धश्च विषयैश्च प्रधर्षितः।
नृपः किमिव न ब्रूयाच्चोद्यमानः समन्मथः॥', 'viparītaś ca vṛddhaś ca viṣayaiś ca pradharṣitaḥ
nṛpaḥ kim iva na brūyāc codyamānaḥ samanmathaḥ', null, 2018003),
('ramayana-2-18-4', 4, 'Ayodhya Kanda, Sarga 18, Verse 4', 'नास्यापराधं पश्यामि नापि दोषं तथा विधम्।
येन निर्वास्यते राष्ट्राद्वनवासाय राघवः॥', 'nāsyāparādhaṃ paśyāmi nāpi doṣaṃ tathā vidham
yena nirvāsyate rāṣṭrād vanavāsāya rāghavaḥ', null, 2018004),
('ramayana-2-18-5', 5, 'Ayodhya Kanda, Sarga 18, Verse 5', 'न तं पश्याम्यहं लोके परोक्षमपि यो नरः।
अमित्रोऽपि निरस्तोऽपि योऽस्य दोषमुदाहरेत्॥', 'na taṃ paśyāmy ahaṃ loke parokṣam api yo naraḥ
amitro ''pi nirasto ''pi yo ''sya doṣam udāharet', null, 2018005),
('ramayana-2-18-6', 6, 'Ayodhya Kanda, Sarga 18, Verse 6', 'देवकल्पमृजुं दान्तं रिपूणामपि वत्सलम्।
अवेक्षमाणः को धर्मं त्यजेत्पुत्रमकारणात्॥', 'devakalpam ṛjuṃ dāntaṃ ripūṇām api vatsalam
avekṣamāṇaḥ ko dharmaṃ tyajet putram akāraṇāt', null, 2018006),
('ramayana-2-18-7', 7, 'Ayodhya Kanda, Sarga 18, Verse 7', 'तदिदं वचनं राज्ञः पुनर्बाल्यमुपेयुषः।
पुत्रः को हृदये कुर्याद्राजवृत्तमनुस्मरन्॥', 'tad idaṃ vacanaṃ rājñaḥ punar bālyam upeyuṣaḥ
putraḥ ko hṛdaye kuryād rājavṛttam anusmaran', null, 2018007),
('ramayana-2-18-8', 8, 'Ayodhya Kanda, Sarga 18, Verse 8', 'यावदेव न जानाति कश्चिदर्थमिमं नरः।
तावदेव मया सार्धमात्मस्थं कुरु शासनम्॥', 'yāvad eva na jānāti kaś cid artham imaṃ naraḥ
tāvad eva mayā sārdham ātmasthaṃ kuru śāsanam', null, 2018008),
('ramayana-2-18-9', 9, 'Ayodhya Kanda, Sarga 18, Verse 9', 'मया पार्श्वे सधनुषा तव गुप्तस्य राघव।
कः समर्थोऽधिकं कर्तुं कृतान्तस्येव तिष्ठतः॥', 'mayā pārśve sadhanuṣā tava guptasya rāghava
kaḥ samartho ''dhikaṃ kartuṃ kṛtāntasyeva tiṣṭhataḥ', null, 2018009),
('ramayana-2-18-10', 10, 'Ayodhya Kanda, Sarga 18, Verse 10', 'निर्मनुष्यामिमां सर्वामयोध्यां मनुजर्षभ।
करिष्यामि शरैस्तीक्ष्णैर्यदि स्थास्यति विप्रिये॥', 'nirmanuṣyām imāṃ sarvām ayodhyāṃ manujarṣabha
kariṣyāmi śarais tīkṣṇair yadi sthāsyati vipriye', null, 2018010),
('ramayana-2-18-11', 11, 'Ayodhya Kanda, Sarga 18, Verse 11', 'भरतस्याथ पक्ष्यो वा यो वास्य हितमिच्छति।
सर्वानेतान्वधिष्यामि मृदुर्हि परिभूयते॥', 'bharatasyātha pakṣyo vā yo vāsya hitam icchati
sarvān etān vadhiṣyāmi mṛdur hi paribhūyate', null, 2018011),
('ramayana-2-18-12', 12, 'Ayodhya Kanda, Sarga 18, Verse 12', 'त्वया चैव मया चैव कृत्वा वैरमनुत्तमम्।
कस्य शक्तिः श्रियं दातुं भरतायारिशासन॥', 'tvayā caiva mayā caiva kṛtvā vairam anuttamam
kasya śaktiḥ śriyaṃ dātuṃ bharatāyāriśāsana', null, 2018012),
('ramayana-2-18-13', 13, 'Ayodhya Kanda, Sarga 18, Verse 13', 'अनुरक्तोऽस्मि भावेन भ्रातरं देवि तत्त्वतः।
सत्येन धनुषा चैव दत्तेनेष्टेन ते शपे॥', 'anurakto ''smi bhāvena bhrātaraṃ devi tattvataḥ
satyena dhanuṣā caiva datteneṣṭena te śape', null, 2018013),
('ramayana-2-18-14', 14, 'Ayodhya Kanda, Sarga 18, Verse 14', 'दीप्तमग्निमरण्यं वा यदि रामः प्रवेक्ष्यते।
प्रविष्टं तत्र मां देवि त्वं पूर्वमवधारय॥', 'dīptam agnim araṇyaṃ vā yadi rāmaḥ pravekṣyate
praviṣṭaṃ tatra māṃ devi tvaṃ pūrvam avadhāraya', null, 2018014),
('ramayana-2-18-15', 15, 'Ayodhya Kanda, Sarga 18, Verse 15', 'हरामि वीर्याद्दुःखं ते तमः सूर्य इवोदितः।
देवी पश्यतु मे वीर्यं राघवश्चैव पश्यतु॥', 'harāmi vīryād duḥkhaṃ te tamaḥ sūrya ivoditaḥ
devī paśyatu me vīryaṃ rāghavaś caiva paśyatu', null, 2018015),
('ramayana-2-18-16', 16, 'Ayodhya Kanda, Sarga 18, Verse 16', 'एतत्तु वचनं श्रुत्वा लक्ष्मणस्य महात्मनः।
उवाच रामं कौसल्या रुदन्ती शोकलालसा॥', 'etat tu vacanaṃ śrutvā lakṣmaṇasya mahātmanaḥ
uvāca rāmaṃ kausalyā rudantī śokalālasā', null, 2018016),
('ramayana-2-18-17', 17, 'Ayodhya Kanda, Sarga 18, Verse 17', 'भ्रातुस्ते वदतः पुत्र लक्ष्मणस्य श्रुतं त्वया।
यदत्रानन्तरं तत्त्वं कुरुष्व यदि रोचते॥', 'bhrātus te vadataḥ putra lakṣmaṇasya śrutaṃ tvayā
yad atrānantaraṃ tat tvaṃ kuruṣva yadi rocate', null, 2018017),
('ramayana-2-18-18', 18, 'Ayodhya Kanda, Sarga 18, Verse 18', 'न चाधर्म्यं वचः श्रुत्वा सपत्न्या मम भाषितम्।
विहाय शोकसंतप्तां गन्तुमर्हसि मामितः॥', 'na cādharmyaṃ vacaḥ śrutvā sapatnyā mama bhāṣitam
vihāya śokasaṃtaptāṃ gantum arhasi mām itaḥ', null, 2018018),
('ramayana-2-18-19', 19, 'Ayodhya Kanda, Sarga 18, Verse 19', 'धर्मज्ञ यदि धर्मिष्ठो धर्मं चरितुमिच्छसि।
शुश्रूष मामिहस्थस्त्वं चर धर्ममनुत्तमम्॥', 'dharmajña yadi dharmiṣṭho dharmaṃ caritum icchasi
śuśrūṣa mām ihasthas tvaṃ cara dharmam anuttamam', null, 2018019),
('ramayana-2-18-20', 20, 'Ayodhya Kanda, Sarga 18, Verse 20', 'शुश्रूषुर्जननीं पुत्र स्वगृहे नियतो वसन्।
परेण तपसा युक्तः काश्यपस्त्रिदिवं गतः॥', 'śuśrūṣur jananīṃ putra svagṛhe niyato vasan
pareṇa tapasā yuktaḥ kāśyapas tridivaṃ gataḥ', null, 2018020),
('ramayana-2-18-21', 21, 'Ayodhya Kanda, Sarga 18, Verse 21', 'यथैव राजा पूज्यस्ते गौरवेण तथा ह्यहम्।
त्वां नाहमनुजानामि न गन्तव्यमितो वनम्॥', 'yathaiva rājā pūjyas te gauraveṇa tathā hy aham
tvāṃ nāham anujānāmi na gantavyam ito vanam', null, 2018021),
('ramayana-2-18-22', 22, 'Ayodhya Kanda, Sarga 18, Verse 22', 'त्वद्वियोगान्न मे कार्यं जीवितेन सुखेन वा।
त्वया सह मम श्रेयस्तृणानामपि भक्षणम्॥', 'tvadviyogān na me kāryaṃ jīvitena sukhena vā
tvayā saha mama śreyas tṛṇānām api bhakṣaṇam', null, 2018022),
('ramayana-2-18-23', 23, 'Ayodhya Kanda, Sarga 18, Verse 23', 'यदि त्वं यास्यसि वनं त्यक्त्वा मां शोकलालसाम्।
अहं प्रायमिहासिष्ये न हि शक्ष्यामि जीवितुम्॥', 'yadi tvaṃ yāsyasi vanaṃ tyaktvā māṃ śokalālasām
ahaṃ prāyam ihāsiṣye na hi śakṣyāmi jīvitum', null, 2018023),
('ramayana-2-18-24', 24, 'Ayodhya Kanda, Sarga 18, Verse 24', 'ततस्त्वं प्राप्स्यसे पुत्र निरयं लोकविश्रुतम्।
ब्रह्महत्यामिवाधर्मात्समुद्रः सरितां पतिः॥', 'tatas tvaṃ prāpsyase putra nirayaṃ lokaviśrutam
brahmahatyām ivādharmāt samudraḥ saritāṃ patiḥ', null, 2018024),
('ramayana-2-18-25', 25, 'Ayodhya Kanda, Sarga 18, Verse 25', 'विलपन्तीं तथा दीनां कौसल्यां जननीं ततः।
उवाच रामो धर्मात्मा वचनं धर्मसंहितम्॥', 'vilapantīṃ tathā dīnāṃ kausalyāṃ jananīṃ tataḥ
uvāca rāmo dharmātmā vacanaṃ dharmasaṃhitam', null, 2018025),
('ramayana-2-18-26', 26, 'Ayodhya Kanda, Sarga 18, Verse 26', 'नास्ति शक्तिः पितुर्वाक्यं समतिक्रमितुं मम।
प्रसादये त्वां शिरसा गन्तुमिच्छाम्यहं वनम्॥', 'nāsti śaktiḥ pitur vākyaṃ samatikramituṃ mama
prasādaye tvāṃ śirasā gantum icchāmy ahaṃ vanam', null, 2018026),
('ramayana-2-18-27', 27, 'Ayodhya Kanda, Sarga 18, Verse 27', 'ऋषिणा च पितुर्वाक्यं कुर्वता व्रतचारिणा।
गौर्हता जानता धर्मं कण्डुनापि विपश्चिता॥', 'ṛṣiṇā ca pitur vākyaṃ kurvatā vratacāriṇā
gaur hatā jānatā dharmaṃ kaṇḍunāpi vipaścitā', null, 2018027),
('ramayana-2-18-28', 28, 'Ayodhya Kanda, Sarga 18, Verse 28', 'अस्माकं च कुले पूर्वं सगरस्याज्ञया पितुः।
खनद्भिः सागरैर्भूतिमवाप्तः सुमहान्वधः॥', 'asmākaṃ ca kule pūrvaṃ sagarasyājñayā pituḥ
khanadbhiḥ sāgarair bhūtim avāptaḥ sumahān vadhaḥ', null, 2018028),
('ramayana-2-18-29', 29, 'Ayodhya Kanda, Sarga 18, Verse 29', 'जामदग्न्येन रामेण रेणुका जननी स्वयम्।
कृत्ता परशुनारण्ये पितुर्वचनकारिणा॥', 'jāmadagnyena rāmeṇa reṇukā jananī svayam
kṛttā paraśunāraṇye pitur vacanakāriṇā', null, 2018029),
('ramayana-2-18-30', 30, 'Ayodhya Kanda, Sarga 18, Verse 30', 'न खल्वेतन्मयैकेन क्रियते पितृशासनम्।
पूर्वैरयमभिप्रेतो गतो मार्गोऽनुगम्यते॥', 'na khalv etan mayaikena kriyate pitṛśāsanam
pūrvair ayam abhipreto gato mārgo ''nugamyate', null, 2018030),
('ramayana-2-18-31', 31, 'Ayodhya Kanda, Sarga 18, Verse 31', 'तदेतत्तु मया कार्यं क्रियते भुवि नान्यथा।
पितुर्हि वचनं कुर्वन्न कश्चिन्नाम हीयते॥', 'tad etat tu mayā kāryaṃ kriyate bhuvi nānyathā
pitur hi vacanaṃ kurvan na kaś cin nāma hīyate', null, 2018031),
('ramayana-2-18-32', 32, 'Ayodhya Kanda, Sarga 18, Verse 32', 'तामेवमुक्त्वा जननीं लक्ष्मणं पुनरब्रवीत्।
तव लक्ष्मण जानामि मयि स्नेहमनुत्तमम्।
अभिप्रायमविज्ञाय सत्यस्य च शमस्य च॥', 'tām evam uktvā jananīṃ lakṣmaṇaṃ punar abravīt
tava lakṣmaṇa jānāmi mayi sneham anuttamam
abhiprāyam avijñāya satyasya ca śamasya ca', null, 2018032),
('ramayana-2-18-33', 33, 'Ayodhya Kanda, Sarga 18, Verse 33', 'धर्मो हि परमो लोके धर्मे सत्यं प्रतिष्ठितम्।
धर्मसंश्रितमेतच्च पितुर्वचनमुत्तमम्॥', 'dharmo hi paramo loke dharme satyaṃ pratiṣṭhitam
dharmasaṃśritam etac ca pitur vacanam uttamam', null, 2018033),
('ramayana-2-18-34', 34, 'Ayodhya Kanda, Sarga 18, Verse 34', 'संश्रुत्य च पितुर्वाक्यं मातुर्वा ब्राह्मणस्य वा।
न कर्तव्यं वृथा वीर धर्ममाश्रित्य तिष्ठता॥', 'saṃśrutya ca pitur vākyaṃ mātur vā brāhmaṇasya vā
na kartavyaṃ vṛthā vīra dharmam āśritya tiṣṭhatā', null, 2018034),
('ramayana-2-18-35', 35, 'Ayodhya Kanda, Sarga 18, Verse 35', 'सोऽहं न शक्ष्यामि पितुर्नियोगमतिवर्तितुम्।
पितुर्हि वचनाद्वीर कैकेय्याहं प्रचोदितः॥', 'so ''haṃ na śakṣyāmi pitur niyogam ativartitum
pitur hi vacanād vīra kaikeyyāhaṃ pracoditaḥ', null, 2018035),
('ramayana-2-18-36', 36, 'Ayodhya Kanda, Sarga 18, Verse 36', 'तदेनां विसृजानार्यां क्षत्रधर्माश्रितां मतिम्।
धर्ममाश्रय मा तैक्ष्ण्यं मद्बुद्धिरनुगम्यताम्॥', 'tad enāṃ visṛjānāryāṃ kṣatradharmāśritāṃ matim
dharmam āśraya mā taikṣṇyaṃ madbuddhir anugamyatām', null, 2018036),
('ramayana-2-18-37', 37, 'Ayodhya Kanda, Sarga 18, Verse 37', 'तमेवमुक्त्वा सौहार्दाद्भ्रातरं लक्ष्मणाग्रजः।
उवाच भूयः कौसल्यां प्राञ्जलिः शिरसानतः॥', 'tam evam uktvā sauhārdād bhrātaraṃ lakṣmaṇāgrajaḥ
uvāca bhūyaḥ kausalyāṃ prāñjaliḥ śirasānataḥ', null, 2018037),
('ramayana-2-18-38', 38, 'Ayodhya Kanda, Sarga 18, Verse 38', 'अनुमन्यस्व मां देवि गमिष्यन्तमितो वनम्।
शापितासि मम प्राणैः कुरु स्वस्त्ययनानि मे।
तीर्णप्रतिज्ञश्च वनात्पुनरेष्याम्यहं पुरीम्॥', 'anumanyasva māṃ devi gamiṣyantam ito vanam
śāpitāsi mama prāṇaiḥ kuru svastyayanāni me
tīrṇapratijñaś ca vanāt punar eṣyāmy ahaṃ purīm', null, 2018038),
('ramayana-2-18-39', 39, 'Ayodhya Kanda, Sarga 18, Verse 39', 'यशो ह्यहं केवलराज्यकारणान्न पृष्ठतः कर्तुमलं महोदयम्।
अदीर्घकाले न तु देवि जीविते वृणेऽवरामद्य महीमधर्मतः॥', 'yaśo hy ahaṃ kevalarājyakāraṇān na pṛṣṭhataḥ kartum alaṃ mahodayam
adīrghakāle na tu devi jīvite vṛṇe ''varām adya mahīm adharmataḥ', null, 2018039),
('ramayana-2-18-40', 40, 'Ayodhya Kanda, Sarga 18, Verse 40', 'प्रसादयन्नरवृषभः स मातरं पराक्रमाज्जिगमिषुरेव दण्डकान्।
अथानुजं भृशमनुशास्य दर्शनं चकार तां हृदि जननीं प्रदक्षिणम्॥', 'prasādayan naravṛṣabhaḥ sa mātaraṃ parākramāj jigamiṣur eva daṇḍakān
athānujaṃ bhṛśam anuśāsya darśanaṃ cakāra tāṃ hṛdi jananīṃ pradakṣiṇam', null, 2018040)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 19 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-19-1', 1, 'Ayodhya Kanda, Sarga 19, Verse 1', 'अथ तं व्यथया दीनं सविशेषममर्षितम्।
श्वसन्तमिव नागेन्द्रं रोषविस्फारितेक्षणम्॥', 'atha taṃ vyathayā dīnaṃ saviśeṣam amarṣitam
śvasantam iva nāgendraṃ roṣavisphāritekṣaṇam', null, 2019001),
('ramayana-2-19-2', 2, 'Ayodhya Kanda, Sarga 19, Verse 2', 'आसाद्य रामः सौमित्रिं सुहृदं भ्रातरं प्रियम्।
उवाचेदं स धैर्येण धारयन्सत्त्वमात्मवान्॥', 'āsādya rāmaḥ saumitriṃ suhṛdaṃ bhrātaraṃ priyam
uvācedaṃ sa dhairyeṇa dhārayan sattvam ātmavān', null, 2019002),
('ramayana-2-19-3', 3, 'Ayodhya Kanda, Sarga 19, Verse 3', 'सौमित्रे योऽभिषेकार्थे मम संभारसंभ्रमः।
अभिषेकनिवृत्त्यर्थे सोऽस्तु संभारसंभ्रमः॥', 'saumitre yo ''bhiṣekārthe mama saṃbhārasaṃbhramaḥ
abhiṣekanivṛttyarthe so ''stu saṃbhārasaṃbhramaḥ', null, 2019003),
('ramayana-2-19-4', 4, 'Ayodhya Kanda, Sarga 19, Verse 4', 'यस्या मदभिषेकार्थं मानसं परितप्यते।
माता नः सा यथा न स्यात्सविशङ्का तथा कुरु॥', 'yasyā madabhiṣekārthaṃ mānasaṃ paritapyate
mātā naḥ sā yathā na syāt saviśaṅkā tathā kuru', null, 2019004),
('ramayana-2-19-5', 5, 'Ayodhya Kanda, Sarga 19, Verse 5', 'तस्याः शङ्कामयं दुःखं मुहूर्तमपि नोत्सहे।
मनसि प्रतिसंजातं सौमित्रेऽहमुपेक्षितुम्॥', 'tasyāḥ śaṅkāmayaṃ duḥkhaṃ muhūrtam api notsahe
manasi pratisaṃjātaṃ saumitre ''ham upekṣitum', null, 2019005),
('ramayana-2-19-6', 6, 'Ayodhya Kanda, Sarga 19, Verse 6', 'न बुद्धिपूर्वं नाबुद्धं स्मरामीह कदा चन।
मातॄणां वा पितुर्वाहं कृतमल्पं च विप्रियम्॥', 'na buddhipūrvaṃ nābuddhaṃ smarāmīha kadā cana
mātṝṇāṃ vā pitur vāhaṃ kṛtam alpaṃ ca vipriyam', null, 2019006),
('ramayana-2-19-7', 7, 'Ayodhya Kanda, Sarga 19, Verse 7', 'सत्यः सत्याभिसंधश्च नित्यं सत्यपराक्रमः।
परलोकभयाद्भीतो निर्भयोऽस्तु पिता मम॥', 'satyaḥ satyābhisaṃdhaś ca nityaṃ satyaparākramaḥ
paralokabhayād bhīto nirbhayo ''stu pitā mama', null, 2019007),
('ramayana-2-19-8', 8, 'Ayodhya Kanda, Sarga 19, Verse 8', 'तस्यापि हि भवेदस्मिन्कर्मण्यप्रतिसंहृते।
सत्यं नेति मनस्तापस्तस्य तापस्तपेच्च माम्॥', 'tasyāpi hi bhaved asmin karmaṇy apratisaṃhṛte
satyaṃ neti manastāpas tasya tāpas tapec ca mām', null, 2019008),
('ramayana-2-19-9', 9, 'Ayodhya Kanda, Sarga 19, Verse 9', 'अभिषेकविधानं तु तस्मात्संहृत्य लक्ष्मण।
अन्वगेवाहमिच्छामि वनं गन्तुमितः पुनः॥', 'abhiṣekavidhānaṃ tu tasmāt saṃhṛtya lakṣmaṇa
anvag evāham icchāmi vanaṃ gantum itaḥ punaḥ', null, 2019009),
('ramayana-2-19-10', 10, 'Ayodhya Kanda, Sarga 19, Verse 10', 'मम प्रव्राजनादद्य कृतकृत्या नृपात्मजा।
सुतं भरतमव्यग्रमभिषेचयिता ततः॥', 'mama pravrājanād adya kṛtakṛtyā nṛpātmajā
sutaṃ bharatam avyagram abhiṣecayitā tataḥ', null, 2019010),
('ramayana-2-19-11', 11, 'Ayodhya Kanda, Sarga 19, Verse 11', 'मयि चीराजिनधरे जटामण्डलधारिणि।
गतेऽरण्यं च कैकेय्या भविष्यति मनःसुखम्॥', 'mayi cīrājinadhare jaṭāmaṇḍaladhāriṇi
gate ''raṇyaṃ ca kaikeyyā bhaviṣyati manaḥsukham', null, 2019011),
('ramayana-2-19-12', 12, 'Ayodhya Kanda, Sarga 19, Verse 12', 'बुद्धिः प्रणीता येनेयं मनश्च सुसमाहितम्।
तत्तु नार्हामि संक्लेष्टुं प्रव्रजिष्यामि माचिरम्॥', 'buddhiḥ praṇītā yeneyaṃ manaś ca susamāhitam
tat tu nārhāmi saṃkleṣṭuṃ pravrajiṣyāmi māciram', null, 2019012),
('ramayana-2-19-13', 13, 'Ayodhya Kanda, Sarga 19, Verse 13', 'कृतान्तस्त्वेव सौमित्रे द्रष्टव्यो मत्प्रवासने।
राज्यस्य च वितीर्णस्य पुनरेव निवर्तने॥', 'kṛtāntas tv eva saumitre draṣṭavyo matpravāsane
rājyasya ca vitīrṇasya punar eva nivartane', null, 2019013),
('ramayana-2-19-14', 14, 'Ayodhya Kanda, Sarga 19, Verse 14', 'कैकेय्याः प्रतिपत्तिर्हि कथं स्यान्मम पीडने।
यदि भावो न दैवोऽयं कृतान्तविहितो भवेत्॥', 'kaikeyyāḥ pratipattir hi kathaṃ syān mama pīḍane
yadi bhāvo na daivo ''yaṃ kṛtāntavihito bhavet', null, 2019014),
('ramayana-2-19-15', 15, 'Ayodhya Kanda, Sarga 19, Verse 15', 'जानासि हि यथा सौम्य न मातृषु ममान्तरम्।
भूतपूर्वं विशेषो वा तस्या मयि सुतेऽपि वा॥', 'jānāsi hi yathā saumya na mātṛṣu mamāntaram
bhūtapūrvaṃ viśeṣo vā tasyā mayi sute ''pi vā', null, 2019015),
('ramayana-2-19-16', 16, 'Ayodhya Kanda, Sarga 19, Verse 16', 'सोऽभिषेकनिवृत्त्यर्थैः प्रवासार्थैश्च दुर्वचैः।
उग्रैर्वाक्यैरहं तस्या नान्यद्दैवात्समर्थये॥', 'so ''bhiṣekanivṛttyarthaiḥ pravāsārthaiś ca durvacaiḥ
ugrair vākyair ahaṃ tasyā nānyad daivāt samarthaye', null, 2019016),
('ramayana-2-19-17', 17, 'Ayodhya Kanda, Sarga 19, Verse 17', 'कथं प्रकृतिसंपन्ना राजपुत्री तथागुणा।
ब्रूयात्सा प्राकृतेव स्त्री मत्पीडां भर्तृसंनिधौ॥', 'kathaṃ prakṛtisaṃpannā rājaputrī tathāguṇā
brūyāt sā prākṛteva strī matpīḍāṃ bhartṛsaṃnidhau', null, 2019017),
('ramayana-2-19-18', 18, 'Ayodhya Kanda, Sarga 19, Verse 18', 'यदचिन्त्यं तु तद्दैवं भूतेष्वपि न हन्यते।
व्यक्तं मयि च तस्यां च पतितो हि विपर्ययः॥', 'yad acintyaṃ tu tad daivaṃ bhūteṣv api na hanyate
vyaktaṃ mayi ca tasyāṃ ca patito hi viparyayaḥ', null, 2019018),
('ramayana-2-19-19', 19, 'Ayodhya Kanda, Sarga 19, Verse 19', 'कश्चिद्दैवेन सौमित्रे योद्धुमुत्सहते पुमान्।
यस्य न ग्रहणं किं चित्कर्मणोऽन्यत्र दृश्यते॥', 'kaś cid daivena saumitre yoddhum utsahate pumān
yasya na grahaṇaṃ kiṃ cit karmaṇo ''nyatra dṛśyate', null, 2019019),
('ramayana-2-19-20', 20, 'Ayodhya Kanda, Sarga 19, Verse 20', 'सुखदुःखे भयक्रोधौ लाभालाभौ भवाभवौ।
यस्य किं चित्तथाभूतं ननु दैवस्य कर्म तत्॥', 'sukhaduḥkhe bhayakrodhau lābhālābhau bhavābhavau
yasya kiṃ cit tathābhūtaṃ nanu daivasya karma tat', null, 2019020),
('ramayana-2-19-21', 21, 'Ayodhya Kanda, Sarga 19, Verse 21', 'व्याहतेऽप्यभिषेके मे परितापो न विद्यते।
तस्मादपरितापः संस्त्वमप्यनुविधाय माम्।
प्रतिसंहारय क्षिप्रमाभिषेचनिकीं क्रियाम्॥', 'vyāhate ''py abhiṣeke me paritāpo na vidyate
tasmād aparitāpaḥ saṃs tvam apy anuvidhāya mām
pratisaṃhāraya kṣipram ābhiṣecanikīṃ kriyām', null, 2019021),
('ramayana-2-19-22', 22, 'Ayodhya Kanda, Sarga 19, Verse 22', 'न लक्ष्मणास्मिन्मम राज्यविघ्ने माता यवीयस्यतिशङ्कनीया।
दैवाभिपन्ना हि वदन्त्यनिष्टं जानासि दैवं च तथाप्रभावम्॥', 'na lakṣmaṇāsmin mama rājyavighne mātā yavīyasy atiśaṅkanīyā
daivābhipannā hi vadanty aniṣṭaṃ jānāsi daivaṃ ca tathāprabhāvam', null, 2019022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 20 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-20-1', 1, 'Ayodhya Kanda, Sarga 20, Verse 1', 'इति ब्रुवति रामे तु लक्ष्मणोऽधःशिरा मुहुः।
श्रुत्वा मध्यं जगामेव मनसा दुःखहर्षयोः॥', 'iti bruvati rāme tu lakṣmaṇo ''dhaḥśirā muhuḥ
śrutvā madhyaṃ jagāmeva manasā duḥkhaharṣayoḥ', null, 2020001),
('ramayana-2-20-2', 2, 'Ayodhya Kanda, Sarga 20, Verse 2', 'तदा तु बद्ध्वा भ्रुकुटीं भ्रुवोर्मध्ये नरर्षभ।
निशश्वास महासर्पो बिलस्थ इव रोषितः॥', 'tadā tu baddhvā bhrukuṭīṃ bhruvor madhye nararṣabha
niśaśvāsa mahāsarpo bilastha iva roṣitaḥ', null, 2020002),
('ramayana-2-20-3', 3, 'Ayodhya Kanda, Sarga 20, Verse 3', 'तस्य दुष्प्रतिवीक्ष्यं तद्भ्रुकुटीसहितं तदा।
बभौ क्रुद्धस्य सिंहस्य मुखस्य सदृशं मुखम्॥', 'tasya duṣprativīkṣyaṃ tad bhrukuṭīsahitaṃ tadā
babhau kruddhasya siṃhasya mukhasya sadṛśaṃ mukham', null, 2020003),
('ramayana-2-20-4', 4, 'Ayodhya Kanda, Sarga 20, Verse 4', 'अग्रहस्तं विधुन्वंस्तु हस्ती हस्तमिवात्मनः।
तिर्यगूर्ध्वं शरीरे च पातयित्वा शिरोधराम्॥', 'agrahas taṃ vidhunvaṃs tu hastī hastam ivātmanaḥ
tiryag ūrdhvaṃ śarīre ca pātayitvā śirodharām', null, 2020004),
('ramayana-2-20-5', 5, 'Ayodhya Kanda, Sarga 20, Verse 5', 'अग्राक्ष्णा वीक्षमाणस्तु तिर्यग्भ्रातरमब्रवीत्।
अस्थाने संभ्रमो यस्य जातो वै सुमहानयम्॥', 'agrākṣṇā vīkṣamāṇas tu tiryag bhrātaram abravīt
asthāne saṃbhramo yasya jāto vai sumahān ayam', null, 2020005),
('ramayana-2-20-6', 6, 'Ayodhya Kanda, Sarga 20, Verse 6', 'धर्मदोषप्रसङ्गेन लोकस्यानतिशङ्कया।
कथं ह्येतदसंभ्रान्तस्त्वद्विधो वक्तुमर्हति॥', 'dharmadoṣaprasaṅgena lokasyānatiśaṅkayā
kathaṃ hy etad asaṃbhrāntas tvadvidho vaktum arhati', null, 2020006),
('ramayana-2-20-7', 7, 'Ayodhya Kanda, Sarga 20, Verse 7', 'यथा दैवमशौण्डीरं शौण्डीरः क्षत्रियर्षभः।
किं नाम कृपणं दैवमशक्तमभिशंससि॥', 'yathā daivam aśauṇḍīraṃ śauṇḍīraḥ kṣatriyarṣabhaḥ
kiṃ nāma kṛpaṇaṃ daivam aśaktam abhiśaṃsasi', null, 2020007),
('ramayana-2-20-8', 8, 'Ayodhya Kanda, Sarga 20, Verse 8', 'पापयोस्ते कथं नाम तयोः शङ्का न विद्यते।
सन्ति धर्मोपधाः श्लक्ष्णा धर्मात्मन्किं न बुध्यसे॥', 'pāpayos te kathaṃ nāma tayoḥ śaṅkā na vidyate
santi dharmopadhāḥ ślakṣṇā dharmātman kiṃ na budhyase', null, 2020008),
('ramayana-2-20-9', 9, 'Ayodhya Kanda, Sarga 20, Verse 9', 'लोकविद्विष्टमारब्धं त्वदन्यस्याभिषेचनम्।
येनेयमागता द्वैधं तव बुद्धिर्महीपते।
स हि धर्मो मम द्वेष्यः प्रसङ्गाद्यस्य मुह्यसि॥', 'lokavidviṣṭam ārabdhaṃ tvadanyasyābhiṣecanam
yeneyam āgatā dvaidhaṃ tava buddhir mahīpate
sa hi dharmo mama dveṣyaḥ prasaṅgād yasya muhyasi', null, 2020009),
('ramayana-2-20-10', 10, 'Ayodhya Kanda, Sarga 20, Verse 10', 'यद्यपि प्रतिपत्तिस्ते दैवी चापि तयोर्मतम्।
तथाप्युपेक्षणीयं ते न मे तदपि रोचते॥', 'yady api pratipattis te daivī cāpi tayor matam
tathāpy upekṣaṇīyaṃ te na me tad api rocate', null, 2020010),
('ramayana-2-20-11', 11, 'Ayodhya Kanda, Sarga 20, Verse 11', 'विक्लवो वीर्यहीनो यः स दैवमनुवर्तते।
वीराः संभावितात्मानो न दैवं पर्युपासते॥', 'viklavo vīryahīno yaḥ sa daivam anuvartate
vīrāḥ saṃbhāvitātmāno na daivaṃ paryupāsate', null, 2020011),
('ramayana-2-20-12', 12, 'Ayodhya Kanda, Sarga 20, Verse 12', 'दैवं पुरुषकारेण यः समर्थः प्रबाधितुम्।
न दैवेन विपन्नार्थः पुरुषः सोऽवसीदति॥', 'daivaṃ puruṣakāreṇa yaḥ samarthaḥ prabādhitum
na daivena vipannārthaḥ puruṣaḥ so ''vasīdati', null, 2020012),
('ramayana-2-20-13', 13, 'Ayodhya Kanda, Sarga 20, Verse 13', 'द्रक्ष्यन्ति त्वद्य दैवस्य पौरुषं पुरुषस्य च।
दैवमानुषयोरद्य व्यक्ता व्यक्तिर्भविष्यति॥', 'drakṣyanti tv adya daivasya pauruṣaṃ puruṣasya ca
daivamānuṣayor adya vyaktā vyaktir bhaviṣyati', null, 2020013),
('ramayana-2-20-14', 14, 'Ayodhya Kanda, Sarga 20, Verse 14', 'अद्य मत्पौरुषहतं दैवं द्रक्ष्यन्ति वै जनाः।
यद्दैवादाहतं तेऽद्य दृष्टं राज्याभिषेचनम्॥', 'adya matpauruṣahataṃ daivaṃ drakṣyanti vai janāḥ
yad daivād āhataṃ te ''dya dṛṣṭaṃ rājyābhiṣecanam', null, 2020014),
('ramayana-2-20-15', 15, 'Ayodhya Kanda, Sarga 20, Verse 15', 'अत्यङ्कुशमिवोद्दामं गजं मदबलोद्धतम्।
प्रधावितमहं दैवं पौरुषेण निवर्तये॥', 'atyaṅkuśam ivoddāmaṃ gajaṃ madabaloddhatam
pradhāvitam ahaṃ daivaṃ pauruṣeṇa nivartaye', null, 2020015),
('ramayana-2-20-16', 16, 'Ayodhya Kanda, Sarga 20, Verse 16', 'लोकपालाः समस्तास्ते नाद्य रामाभिषेचनम्।
न च कृत्स्नास्त्रयो लोका विहन्युः किं पुनः पिता॥', 'lokapālāḥ samastās te nādya rāmābhiṣecanam
na ca kṛtsnās trayo lokā vihanyuḥ kiṃ punaḥ pitā', null, 2020016),
('ramayana-2-20-17', 17, 'Ayodhya Kanda, Sarga 20, Verse 17', 'यैर्विवासस्तवारण्ये मिथो राजन्समर्थितः।
अरण्ये ते विवत्स्यन्ति चतुर्दश समास्तथा॥', 'yair vivāsas tavāraṇye mitho rājan samarthitaḥ
araṇye te vivatsyanti caturdaśa samās tathā', null, 2020017),
('ramayana-2-20-18', 18, 'Ayodhya Kanda, Sarga 20, Verse 18', 'अहं तदाशां छेत्स्यामि पितुस्तस्याश्च या तव।
अभिषेकविघातेन पुत्रराज्याय वर्तते॥', 'ahaṃ tadāśāṃ chetsyāmi pitus tasyāś ca yā tava
abhiṣekavighātena putrarājyāya vartate', null, 2020018),
('ramayana-2-20-19', 19, 'Ayodhya Kanda, Sarga 20, Verse 19', 'मद्बलेन विरुद्धाय न स्याद्दैवबलं तथा।
प्रभविष्यति दुःखाय यथोग्रं पौरुषं मम॥', 'madbalena viruddhāya na syād daivabalaṃ tathā
prabhaviṣyati duḥkhāya yathograṃ pauruṣaṃ mama', null, 2020019),
('ramayana-2-20-20', 20, 'Ayodhya Kanda, Sarga 20, Verse 20', 'ऊर्ध्वं वर्षसहस्रान्ते प्रजापाल्यमनन्तरम्।
आर्यपुत्राः करिष्यन्ति वनवासं गते त्वयि॥', 'ūrdhvaṃ varṣasahasrānte prajāpālyam anantaram
āryaputrāḥ kariṣyanti vanavāsaṃ gate tvayi', null, 2020020),
('ramayana-2-20-21', 21, 'Ayodhya Kanda, Sarga 20, Verse 21', 'पूर्वराजर्षिवृत्त्या हि वनवासो विधीयते।
प्रजा निक्षिप्य पुत्रेषु पुत्रवत्परिपालने॥', 'pūrvarājarṣivṛttyā hi vanavāso vidhīyate
prajā nikṣipya putreṣu putravat paripālane', null, 2020021),
('ramayana-2-20-22', 22, 'Ayodhya Kanda, Sarga 20, Verse 22', 'स चेद्राजन्यनेकाग्रे राज्यविभ्रमशङ्कया।
नैवमिच्छसि धर्मात्मन्राज्यं राम त्वमात्मनि॥', 'sa ced rājany anekāgre rājyavibhramaśaṅkayā
naivam icchasi dharmātman rājyaṃ rāma tvam ātmani', null, 2020022),
('ramayana-2-20-23', 23, 'Ayodhya Kanda, Sarga 20, Verse 23', 'प्रतिजाने च ते वीर मा भूवं वीरलोकभाक्।
राज्यं च तव रक्षेयमहं वेलेव सागरम्॥', 'pratijāne ca te vīra mā bhūvaṃ vīralokabhāk
rājyaṃ ca tava rakṣeyam ahaṃ veleva sāgaram', null, 2020023),
('ramayana-2-20-24', 24, 'Ayodhya Kanda, Sarga 20, Verse 24', 'मङ्गलैरभिषिञ्चस्व तत्र त्वं व्यापृतो भव।
अहमेको महीपालानलं वारयितुं बलात्॥', 'maṅgalair abhiṣiñcasva tatra tvaṃ vyāpṛto bhava
aham eko mahīpālān alaṃ vārayituṃ balāt', null, 2020024),
('ramayana-2-20-25', 25, 'Ayodhya Kanda, Sarga 20, Verse 25', 'न शोभार्थाविमौ बाहू न धनुर्भूषणाय मे।
नासिराबन्धनार्थाय न शराः स्तम्भहेतवः॥', 'na śobhārthāv imau bāhū na dhanur bhūṣaṇāya me
nāsirābandhanārthāya na śarāḥ stambhahetavaḥ', null, 2020025),
('ramayana-2-20-26', 26, 'Ayodhya Kanda, Sarga 20, Verse 26', 'अमित्रदमनार्थं मे सर्वमेतच्चतुष्टयम्।
न चाहं कामयेऽत्यर्थं यः स्याच्छत्रुर्मतो मम॥', 'amitradamanārthaṃ me sarvam etac catuṣṭayam
na cāhaṃ kāmaye ''tyarthaṃ yaḥ syāc chatrur mato mama', null, 2020026),
('ramayana-2-20-27', 27, 'Ayodhya Kanda, Sarga 20, Verse 27', 'असिना तीक्ष्णधारेण विद्युच्चलितवर्चसा।
प्रगृहीतेन वै शत्रुं वज्रिणं वा न कल्पये॥', 'asinā tīkṣṇadhāreṇa vidyuccalitavarcasā
pragṛhītena vai śatruṃ vajriṇaṃ vā na kalpaye', null, 2020027),
('ramayana-2-20-28', 28, 'Ayodhya Kanda, Sarga 20, Verse 28', 'खड्गनिष्पेषनिष्पिष्टैर्गहना दुश्चरा च मे।
हस्त्यश्वनरहस्तोरुशिरोभिर्भविता मही॥', 'khaḍganiṣpeṣaniṣpiṣṭair gahanā duścarā ca me
hastyaśvanarahastoruśirobhir bhavitā mahī', null, 2020028),
('ramayana-2-20-29', 29, 'Ayodhya Kanda, Sarga 20, Verse 29', 'खड्गधाराहता मेऽद्य दीप्यमाना इवाद्रयः।
पतिष्यन्ति द्विपा भूमौ मेघा इव सविद्युतः॥', 'khaḍgadhārāhatā me ''dya dīpyamānā ivādrayaḥ
patiṣyanti dvipā bhūmau meghā iva savidyutaḥ', null, 2020029),
('ramayana-2-20-30', 30, 'Ayodhya Kanda, Sarga 20, Verse 30', 'बद्धगोधाङ्गुलित्राणे प्रगृहीतशरासने।
कथं पुरुषमानी स्यात्पुरुषाणां मयि स्थिते॥', 'baddhagodhāṅgulitrāṇe pragṛhītaśarāsane
kathaṃ puruṣamānī syāt puruṣāṇāṃ mayi sthite', null, 2020030),
('ramayana-2-20-31', 31, 'Ayodhya Kanda, Sarga 20, Verse 31', 'बहुभिश्चैकमत्यस्यन्नेकेन च बहूञ्जनान्।
विनियोक्ष्याम्यहं बाणान्नृवाजिगजमर्मसु॥', 'bahubhiś caikam atyasyann ekena ca bahūñ janān
viniyokṣyāmy ahaṃ bāṇān nṛvājigajamarmasu', null, 2020031),
('ramayana-2-20-32', 32, 'Ayodhya Kanda, Sarga 20, Verse 32', 'अद्य मेऽस्त्रप्रभावस्य प्रभावः प्रभविष्यति।
राज्ञश्चाप्रभुतां कर्तुं प्रभुत्वं च तव प्रभो॥', 'adya me ''straprabhāvasya prabhāvaḥ prabhaviṣyati
rājñaś cāprabhutāṃ kartuṃ prabhutvaṃ ca tava prabho', null, 2020032),
('ramayana-2-20-33', 33, 'Ayodhya Kanda, Sarga 20, Verse 33', 'अद्य चन्दनसारस्य केयूरामोक्षणस्य च।
वसूनां च विमोक्षस्य सुहृदां पालनस्य च॥', 'adya candanasārasya keyūrāmokṣaṇasya ca
vasūnāṃ ca vimokṣasya suhṛdāṃ pālanasya ca', null, 2020033),
('ramayana-2-20-34', 34, 'Ayodhya Kanda, Sarga 20, Verse 34', 'अनुरूपाविमौ बाहू राम कर्म करिष्यतः।
अभिषेचनविघ्नस्य कर्तॄणां ते निवारणे॥', 'anurūpāv imau bāhū rāma karma kariṣyataḥ
abhiṣecanavighnasya kartṝṇāṃ te nivāraṇe', null, 2020034),
('ramayana-2-20-35', 35, 'Ayodhya Kanda, Sarga 20, Verse 35', 'ब्रवीहि कोऽद्यैव मया वियुज्यतां तवासुहृत्प्राणयशः सुहृज्जनैः।
यथा तवेयं वसुधा वशे भवेत्तथैव मां शाधि तवास्मि किंकरः॥', 'bravīhi ko ''dyaiva mayā viyujyatāṃ tavāsuhṛt prāṇayaśaḥ suhṛjjanaiḥ
yathā taveyaṃ vasudhā vaśe bhavet tathaiva māṃ śādhi tavāsmi kiṃkaraḥ', null, 2020035),
('ramayana-2-20-36', 36, 'Ayodhya Kanda, Sarga 20, Verse 36', 'विमृज्य बाष्पं परिसान्त्व्य चासकृत्स लक्ष्मणं राघववंशवर्धनः।
उवाच पित्र्ये वचने व्यवस्थितं निबोध मामेष हि सौम्य सत्पथः॥', 'vimṛjya bāṣpaṃ parisāntvya cāsakṛt sa lakṣmaṇaṃ rāghavavaṃśavardhanaḥ
uvāca pitrye vacane vyavasthitaṃ nibodha mām eṣa hi saumya satpathaḥ', null, 2020036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 21 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-21-1', 1, 'Ayodhya Kanda, Sarga 21, Verse 1', 'तं समीक्ष्य त्ववहितं पितुर्निर्देशपालने।
कौसल्या बाष्पसंरुद्धा वचो धर्मिष्ठमब्रवीत्॥', 'taṃ samīkṣya tv avahitaṃ pitur nirdeśapālane
kausalyā bāṣpasaṃruddhā vaco dharmiṣṭham abravīt', null, 2021001),
('ramayana-2-21-2', 2, 'Ayodhya Kanda, Sarga 21, Verse 2', 'अदृष्टदुःखो धर्मात्मा सर्वभूतप्रियंवदः।
मयि जातो दशरथात्कथमुञ्छेन वर्तयेत्॥', 'adṛṣṭaduḥkho dharmātmā sarvabhūtapriyaṃvadaḥ
mayi jāto daśarathāt katham uñchena vartayet', null, 2021002),
('ramayana-2-21-3', 3, 'Ayodhya Kanda, Sarga 21, Verse 3', 'यस्य भृत्याश्च दासाश्च मृष्टान्यन्नानि भुञ्जते।
कथं स भोक्ष्यते नाथो वने मूलफलान्ययम्॥', 'yasya bhṛtyāś ca dāsāś ca mṛṣṭāny annāni bhuñjate
kathaṃ sa bhokṣyate nātho vane mūlaphalāny ayam', null, 2021003),
('ramayana-2-21-4', 4, 'Ayodhya Kanda, Sarga 21, Verse 4', 'क एतच्छ्रद्दधेच्छ्रुत्वा कस्य वा न भवेद्भयम्।
गुणवान्दयितो राज्ञो राघवो यद्विवास्यते॥', 'ka etac chraddadhec chrutvā kasya vā na bhaved bhayam
guṇavān dayito rājño rāghavo yad vivāsyate', null, 2021004),
('ramayana-2-21-5', 5, 'Ayodhya Kanda, Sarga 21, Verse 5', 'त्वया विहीनामिह मां शोकाग्निरतुलो महान्।
प्रधक्ष्यति यथा कक्षं चित्रभानुर्हिमात्यये॥', 'tvayā vihīnām iha māṃ śokāgnir atulo mahān
pradhakṣyati yathā kakṣaṃ citrabhānur himātyaye', null, 2021005),
('ramayana-2-21-6', 6, 'Ayodhya Kanda, Sarga 21, Verse 6', 'कथं हि धेनुः स्वं वत्सं गच्छन्तं नानुगच्छति।
अहं त्वानुगमिष्यामि यत्र पुत्र गमिष्यसि॥', 'kathaṃ hi dhenuḥ svaṃ vatsaṃ gacchantaṃ nānugacchati
ahaṃ tvānugamiṣyāmi yatra putra gamiṣyasi', null, 2021006),
('ramayana-2-21-7', 7, 'Ayodhya Kanda, Sarga 21, Verse 7', 'तथा निगदितं मात्रा तद्वाक्यं पुरुषर्षभः।
श्रुत्वा रामोऽब्रवीद्वाक्यं मातरं भृशदुःखिताम्॥', 'tathā nigaditaṃ mātrā tad vākyaṃ puruṣarṣabhaḥ
śrutvā rāmo ''bravīd vākyaṃ mātaraṃ bhṛśaduḥkhitām', null, 2021007),
('ramayana-2-21-8', 8, 'Ayodhya Kanda, Sarga 21, Verse 8', 'कैकेय्या वञ्चितो राजा मयि चारण्यमाश्रिते।
भवत्या च परित्यक्तो न नूनं वर्तयिष्यति॥', 'kaikeyyā vañcito rājā mayi cāraṇyam āśrite
bhavatyā ca parityakto na nūnaṃ vartayiṣyati', null, 2021008),
('ramayana-2-21-9', 9, 'Ayodhya Kanda, Sarga 21, Verse 9', 'भर्तुः किल परित्यागो नृशंसः केवलं स्त्रियाः।
स भवत्या न कर्तव्यो मनसापि विगर्हितः॥', 'bhartuḥ kila parityāgo nṛśaṃsaḥ kevalaṃ striyāḥ
sa bhavatyā na kartavyo manasāpi vigarhitaḥ', null, 2021009),
('ramayana-2-21-10', 10, 'Ayodhya Kanda, Sarga 21, Verse 10', 'यावज्जीवति काकुत्स्थः पिता मे जगतीपतिः।
शुश्रूषा क्रियतां तावत्स हि धर्मः सनातनः॥', 'yāvaj jīvati kākutsthaḥ pitā me jagatīpatiḥ
śuśrūṣā kriyatāṃ tāvat sa hi dharmaḥ sanātanaḥ', null, 2021010),
('ramayana-2-21-11', 11, 'Ayodhya Kanda, Sarga 21, Verse 11', 'एवमुक्ता तु रामेण कौसल्या शुभ दर्शना।
तथेत्युवाच सुप्रीता राममक्लिष्टकारिणम्॥', 'evam uktā tu rāmeṇa kausalyā śubha darśanā
tathety uvāca suprītā rāmam akliṣṭakāriṇam', null, 2021011),
('ramayana-2-21-12', 12, 'Ayodhya Kanda, Sarga 21, Verse 12', 'एवमुक्तस्तु वचनं रामो धर्मभृतां वरः।
भूयस्तामब्रवीद्वाक्यं मातरं भृशदुःखिताम्॥', 'evam uktas tu vacanaṃ rāmo dharmabhṛtāṃ varaḥ
bhūyas tām abravīd vākyaṃ mātaraṃ bhṛśaduḥkhitām', null, 2021012),
('ramayana-2-21-13', 13, 'Ayodhya Kanda, Sarga 21, Verse 13', 'मया चैव भवत्या च कर्तव्यं वचनं पितुः।
राजा भर्ता गुरुः श्रेष्ठः सर्वेषामीश्वरः प्रभुः॥', 'mayā caiva bhavatyā ca kartavyaṃ vacanaṃ pituḥ
rājā bhartā guruḥ śreṣṭhaḥ sarveṣām īśvaraḥ prabhuḥ', null, 2021013),
('ramayana-2-21-14', 14, 'Ayodhya Kanda, Sarga 21, Verse 14', 'इमानि तु महारण्ये विहृत्य नव पञ्च च।
वर्षाणि परमप्रीतः स्थास्यामि वचने तव॥', 'imāni tu mahāraṇye vihṛtya nava pañca ca
varṣāṇi paramaprītaḥ sthāsyāmi vacane tava', null, 2021014),
('ramayana-2-21-15', 15, 'Ayodhya Kanda, Sarga 21, Verse 15', 'एवमुक्ता प्रियं पुत्रं बाष्पपूर्णानना तदा।
उवाच परमार्ता तु कौसल्या पुत्रवत्सला॥', 'evam uktā priyaṃ putraṃ bāṣpapūrṇānanā tadā
uvāca paramārtā tu kausalyā putravatsalā', null, 2021015),
('ramayana-2-21-16', 16, 'Ayodhya Kanda, Sarga 21, Verse 16', 'आसां राम सपत्नीनां वस्तुं मध्ये न मे क्षमम्।
नय मामपि काकुत्स्थ वनं वन्यं मृगीं यथा।
यदि ते गमने बुद्धिः कृता पितुरपेक्षया॥', 'āsāṃ rāma sapatnīnāṃ vastuṃ madhye na me kṣamam
naya mām api kākutstha vanaṃ vanyaṃ mṛgīṃ yathā
yadi te gamane buddhiḥ kṛtā pitur apekṣayā', null, 2021016),
('ramayana-2-21-17', 17, 'Ayodhya Kanda, Sarga 21, Verse 17', 'तां तथा रुदतीं रामो रुदन्वचनमब्रवीत्।
जीवन्त्या हि स्त्रिया भर्ता दैवतं प्रभुरेव च।
भवत्या मम चैवाद्य राजा प्रभवति प्रभुः॥', 'tāṃ tathā rudatīṃ rāmo rudan vacanam abravīt
jīvantyā hi striyā bhartā daivataṃ prabhur eva ca
bhavatyā mama caivādya rājā prabhavati prabhuḥ', null, 2021017),
('ramayana-2-21-18', 18, 'Ayodhya Kanda, Sarga 21, Verse 18', 'भरतश्चापि धर्मात्मा सर्वभूतप्रियंवदः।
भवतीमनुवर्तेत स हि धर्मरतः सदा॥', 'bharataś cāpi dharmātmā sarvabhūtapriyaṃvadaḥ
bhavatīm anuvarteta sa hi dharmarataḥ sadā', null, 2021018),
('ramayana-2-21-19', 19, 'Ayodhya Kanda, Sarga 21, Verse 19', 'यथा मयि तु निष्क्रान्ते पुत्रशोकेन पार्थिवः।
श्रमं नावाप्नुयात्किं चिदप्रमत्ता तथा कुरु॥', 'yathā mayi tu niṣkrānte putraśokena pārthivaḥ
śramaṃ nāvāpnuyāt kiṃ cid apramattā tathā kuru', null, 2021019),
('ramayana-2-21-20', 20, 'Ayodhya Kanda, Sarga 21, Verse 20', 'व्रतोपवासनिरता या नारी परमोत्तमा।
भर्तारं नानुवर्तेत सा च पापगतिर्भवेत्॥', 'vratopavāsaniratā yā nārī paramottamā
bhartāraṃ nānuvarteta sā ca pāpagatir bhavet', null, 2021020),
('ramayana-2-21-21', 21, 'Ayodhya Kanda, Sarga 21, Verse 21', 'शुश्रूषमेव कुर्वीत भर्तुः प्रियहिते रता।
एष धर्मः पुरा दृष्टो लोके वेदे श्रुतः स्मृतः॥', 'śuśrūṣam eva kurvīta bhartuḥ priyahite ratā
eṣa dharmaḥ purā dṛṣṭo loke vede śrutaḥ smṛtaḥ', null, 2021021),
('ramayana-2-21-22', 22, 'Ayodhya Kanda, Sarga 21, Verse 22', 'पूज्यास्ते मत्कृते देवि ब्राह्मणाश्चैव सुव्रताः।
एवं कालं प्रतीक्षस्व ममागमनकाङ्क्षिणी॥', 'pūjyās te matkṛte devi brāhmaṇāś caiva suvratāḥ
evaṃ kālaṃ pratīkṣasva mamāgamanakāṅkṣiṇī', null, 2021022),
('ramayana-2-21-23', 23, 'Ayodhya Kanda, Sarga 21, Verse 23', 'प्राप्स्यसे परमं कामं मयि प्रत्यागते सति।
यदि धर्मभृतां श्रेष्ठो धारयिष्यति जीवितम्॥', 'prāpsyase paramaṃ kāmaṃ mayi pratyāgate sati
yadi dharmabhṛtāṃ śreṣṭho dhārayiṣyati jīvitam', null, 2021023),
('ramayana-2-21-24', 24, 'Ayodhya Kanda, Sarga 21, Verse 24', 'एवमुक्ता तु रामेण बाष्पपर्याकुलेक्षणा।
कौसल्या पुत्रशोकार्ता रामं वचनमब्रवीत्।
गच्छ पुत्र त्वमेकाग्रो भद्रं तेऽस्तु सदा विभो॥', 'evam uktā tu rāmeṇa bāṣpaparyākulekṣaṇā
kausalyā putraśokārtā rāmaṃ vacanam abravīt
gaccha putra tvam ekāgro bhadraṃ te ''stu sadā vibho', null, 2021024),
('ramayana-2-21-25', 25, 'Ayodhya Kanda, Sarga 21, Verse 25', 'तथा हि रामं वनवासनिश्चितं समीक्ष्य देवी परमेण चेतसा।
उवाच रामं शुभलक्षणं वचो बभूव च स्वस्त्ययनाभिकाङ्क्षिणी॥', 'tathā hi rāmaṃ vanavāsaniścitaṃ samīkṣya devī parameṇa cetasā
uvāca rāmaṃ śubhalakṣaṇaṃ vaco babhūva ca svastyayanābhikāṅkṣiṇī', null, 2021025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 22 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-22-1', 1, 'Ayodhya Kanda, Sarga 22, Verse 1', 'सापनीय तमायासमुपस्पृश्य जलं शुचि।
चकार माता रामस्य मङ्गलानि मनस्विनी॥', 'sāpanīya tam āyāsam upaspṛśya jalaṃ śuci
cakāra mātā rāmasya maṅgalāni manasvinī', null, 2022001),
('ramayana-2-22-2', 2, 'Ayodhya Kanda, Sarga 22, Verse 2', 'स्वस्ति साध्याश्च विश्वे च मरुतश्च महर्षयः।
स्वस्ति धाता विधाता च स्वस्ति पूषा भगोऽर्यमा॥', 'svasti sādhyāś ca viśve ca marutaś ca maharṣayaḥ
svasti dhātā vidhātā ca svasti pūṣā bhago ''ryamā', null, 2022002),
('ramayana-2-22-3', 3, 'Ayodhya Kanda, Sarga 22, Verse 3', 'ऋतवश्चैव पक्षाश्च मासाः संवत्सराः क्षपाः।
दिनानि च मुहूर्ताश्च स्वस्ति कुर्वन्तु ते सदा॥', 'ṛtavaś caiva pakṣāś ca māsāḥ saṃvatsarāḥ kṣapāḥ
dināni ca muhūrtāś ca svasti kurvantu te sadā', null, 2022003),
('ramayana-2-22-4', 4, 'Ayodhya Kanda, Sarga 22, Verse 4', 'स्मृतिर्धृतिश्च धर्मश्च पान्तु त्वां पुत्र सर्वतः।
स्कन्दश्च भगवान्देवः सोमश्च सबृहस्पतिः॥', 'smṛtir dhṛtiś ca dharmaś ca pāntu tvāṃ putra sarvataḥ
skandaś ca bhagavān devaḥ somaś ca sabṛhaspatiḥ', null, 2022004),
('ramayana-2-22-5', 5, 'Ayodhya Kanda, Sarga 22, Verse 5', 'सप्तर्षयो नारदश्च ते त्वां रक्षन्तु सर्वतः।
नक्षत्राणि च सर्वाणि ग्रहाश्च सहदेवताः।
महावनानि चरतो मुनिवेषस्य धीमतः॥', 'saptarṣayo nāradaś ca te tvāṃ rakṣantu sarvataḥ
nakṣatrāṇi ca sarvāṇi grahāś ca sahadevatāḥ
mahāvanāni carato muniveṣasya dhīmataḥ', null, 2022005),
('ramayana-2-22-6', 6, 'Ayodhya Kanda, Sarga 22, Verse 6', 'प्लवगा वृश्चिका दंशा मशकाश्चैव कानने।
सरीसृपाश्च कीटाश्च मा भूवन्गहने तव॥', 'plavagā vṛścikā daṃśā maśakāś caiva kānane
sarīsṛpāś ca kīṭāś ca mā bhūvan gahane tava', null, 2022006),
('ramayana-2-22-7', 7, 'Ayodhya Kanda, Sarga 22, Verse 7', 'महाद्विपाश्च सिंहाश्च व्याघ्रा ऋक्षाश्च दंष्ट्रिणः।
महिषाः शृङ्गिणो रौद्रा न ते द्रुह्यन्तु पुत्रक॥', 'mahādvipāś ca siṃhāś ca vyāghrā ṛkṣāś ca daṃṣṭriṇaḥ
mahiṣāḥ śṛṅgiṇo raudrā na te druhyantu putraka', null, 2022007),
('ramayana-2-22-8', 8, 'Ayodhya Kanda, Sarga 22, Verse 8', 'नृमांसभोजना रौद्रा ये चान्ये सत्त्वजातयः।
मा च त्वां हिंसिषुः पुत्र मया संपूजितास्त्विह॥', 'nṛmāṃsabhojanā raudrā ye cānye sattvajātayaḥ
mā ca tvāṃ hiṃsiṣuḥ putra mayā saṃpūjitās tv iha', null, 2022008),
('ramayana-2-22-9', 9, 'Ayodhya Kanda, Sarga 22, Verse 9', 'आगमास्ते शिवाः सन्तु सिध्यन्तु च पराक्रमाः।
सर्वसंपत्तयो राम स्वस्तिमान्गच्छ पुत्रक॥', 'āgamās te śivāḥ santu sidhyantu ca parākramāḥ
sarvasaṃpattayo rāma svastimān gaccha putraka', null, 2022009),
('ramayana-2-22-10', 10, 'Ayodhya Kanda, Sarga 22, Verse 10', 'स्वस्ति तेऽस्त्वान्तरिक्षेभ्यः पार्थिवेभ्यः पुनः पुनः।
सर्वेभ्यश्चैव देवेभ्यो ये च ते परिपन्थिनः॥', 'svasti te ''stv āntarikṣebhyaḥ pārthivebhyaḥ punaḥ punaḥ
sarvebhyaś caiva devebhyo ye ca te paripanthinaḥ', null, 2022010),
('ramayana-2-22-11', 11, 'Ayodhya Kanda, Sarga 22, Verse 11', 'सर्वलोकप्रभुर्ब्रह्मा भूतभर्ता तथर्षयः।
ये च शेषाः सुरास्ते त्वां रक्षन्तु वनवासिनम्॥', 'sarvalokaprabhur brahmā bhūtabhartā tatharṣayaḥ
ye ca śeṣāḥ surās te tvāṃ rakṣantu vanavāsinam', null, 2022011),
('ramayana-2-22-12', 12, 'Ayodhya Kanda, Sarga 22, Verse 12', 'इति माल्यैः सुरगणान्गन्धैश्चापि यशस्विनी।
स्तुतिभिश्चानुरूपाभिरानर्चायतलोचना॥', 'iti mālyaiḥ suragaṇān gandhaiś cāpi yaśasvinī
stutibhiś cānurūpābhir ānarcāyatalocanā', null, 2022012),
('ramayana-2-22-13', 13, 'Ayodhya Kanda, Sarga 22, Verse 13', 'यन्मङ्गलं सहस्राक्षे सर्वदेवनमस्कृते।
वृत्रनाशे समभवत्तत्ते भवतु मङ्गलम्॥', 'yan maṅgalaṃ sahasrākṣe sarvadevanamaskṛte
vṛtranāśe samabhavat tat te bhavatu maṅgalam', null, 2022013),
('ramayana-2-22-14', 14, 'Ayodhya Kanda, Sarga 22, Verse 14', 'यन्मङ्गलं सुपर्णस्य विनताकल्पयत्पुरा।
अमृतं प्रार्थयानस्य तत्ते भवतु मङ्गलम्॥', 'yan maṅgalaṃ suparṇasya vinatākalpayat purā
amṛtaṃ prārthayānasya tat te bhavatu maṅgalam', null, 2022014),
('ramayana-2-22-15', 15, 'Ayodhya Kanda, Sarga 22, Verse 15', 'ओषधीं चापि सिद्धार्थां विशल्यकरणीं शुभाम्।
चकार रक्षां कौसल्या मन्त्रैरभिजजाप च॥', 'oṣadhīṃ cāpi siddhārthāṃ viśalyakaraṇīṃ śubhām
cakāra rakṣāṃ kausalyā mantrair abhijajāpa ca', null, 2022015),
('ramayana-2-22-16', 16, 'Ayodhya Kanda, Sarga 22, Verse 16', 'आनम्य मूर्ध्नि चाघ्राय परिष्वज्य यशस्विनी।
अवदत्पुत्र सिद्धार्थो गच्छ राम यथासुखम्॥', 'ānamya mūrdhni cāghrāya pariṣvajya yaśasvinī
avadat putra siddhārtho gaccha rāma yathāsukham', null, 2022016),
('ramayana-2-22-17', 17, 'Ayodhya Kanda, Sarga 22, Verse 17', 'अरोगं सर्वसिद्धार्थमयोध्यां पुनरागतम्।
पश्यामि त्वां सुखं वत्स सुस्थितं राजवेश्मनि॥', 'arogaṃ sarvasiddhārtham ayodhyāṃ punar āgatam
paśyāmi tvāṃ sukhaṃ vatsa susthitaṃ rājaveśmani', null, 2022017),
('ramayana-2-22-18', 18, 'Ayodhya Kanda, Sarga 22, Verse 18', 'मयार्चिता देवगणाः शिवादयो महर्षयो भूतमहासुरोरगाः।
अभिप्रयातस्य वनं चिराय ते हितानि काङ्क्षन्तु दिशश्च राघव॥', 'mayārcitā devagaṇāḥ śivādayo maharṣayo bhūtamahāsuroragāḥ
abhiprayātasya vanaṃ cirāya te hitāni kāṅkṣantu diśaś ca rāghava', null, 2022018),
('ramayana-2-22-19', 19, 'Ayodhya Kanda, Sarga 22, Verse 19', 'इतीव चाश्रुप्रतिपूर्णलोचना समाप्य च स्वस्त्ययनं यथाविधि।
प्रदक्षिणं चैव चकार राघवं पुनः पुनश्चापि निपीड्य सस्वजे॥', 'itīva cāśrupratipūrṇalocanā samāpya ca svastyayanaṃ yathāvidhi
pradakṣiṇaṃ caiva cakāra rāghavaṃ punaḥ punaś cāpi nipīḍya sasvaje', null, 2022019),
('ramayana-2-22-20', 20, 'Ayodhya Kanda, Sarga 22, Verse 20', 'तथा तु देव्या स कृतप्रदक्षिणो निपीड्य मातुश्चरणौ पुनः पुनः।
जगाम सीतानिलयं महायशाः स राघवः प्रज्वलितः स्वया श्रिया॥', 'tathā tu devyā sa kṛtapradakṣiṇo nipīḍya mātuś caraṇau punaḥ punaḥ
jagāma sītānilayaṃ mahāyaśāḥ sa rāghavaḥ prajvalitaḥ svayā śriyā', null, 2022020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 23 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-23-1', 1, 'Ayodhya Kanda, Sarga 23, Verse 1', 'अभिवाद्य तु कौसल्यां रामः संप्रस्थितो वनम्।
कृतस्वस्त्ययनो मात्रा धर्मिष्ठे वर्त्मनि स्थितः॥', 'abhivādya tu kausalyāṃ rāmaḥ saṃprasthito vanam
kṛtasvastyayano mātrā dharmiṣṭhe vartmani sthitaḥ', null, 2023001),
('ramayana-2-23-2', 2, 'Ayodhya Kanda, Sarga 23, Verse 2', 'विराजयन्राजसुतो राजमार्गं नरैर्वृतम्।
हृदयान्याममन्थेव जनस्य गुणवत्तया॥', 'virājayan rājasuto rājamārgaṃ narair vṛtam
hṛdayāny āmamantheva janasya guṇavattayā', null, 2023002),
('ramayana-2-23-3', 3, 'Ayodhya Kanda, Sarga 23, Verse 3', 'वैदेही चापि तत्सर्वं न शुश्राव तपस्विनी।
तदेव हृदि तस्याश्च यौवराज्याभिषेचनम्॥', 'vaidehī cāpi tat sarvaṃ na śuśrāva tapasvinī
tad eva hṛdi tasyāś ca yauvarājyābhiṣecanam', null, 2023003),
('ramayana-2-23-4', 4, 'Ayodhya Kanda, Sarga 23, Verse 4', 'देवकार्यं स्म सा कृत्वा कृतज्ञा हृष्टचेतना।
अभिज्ञा राजधर्माणां राजपुत्रं प्रतीक्षते॥', 'devakāryaṃ sma sā kṛtvā kṛtajñā hṛṣṭacetanā
abhijñā rājadharmāṇāṃ rājaputraṃ pratīkṣate', null, 2023004),
('ramayana-2-23-5', 5, 'Ayodhya Kanda, Sarga 23, Verse 5', 'प्रविवेशाथ रामस्तु स्ववेश्म सुविभूषितम्।
प्रहृष्टजनसंपूर्णं ह्रिया किं चिदवाङ्मुखः॥', 'praviveśātha rāmas tu svaveśma suvibhūṣitam
prahṛṣṭajanasaṃpūrṇaṃ hriyā kiṃ cid avāṅmukhaḥ', null, 2023005),
('ramayana-2-23-6', 6, 'Ayodhya Kanda, Sarga 23, Verse 6', 'अथ सीता समुत्पत्य वेपमाना च तं पतिम्।
अपश्यच्छोकसंतप्तं चिन्ताव्याकुलिलेन्द्रियम्॥', 'atha sītā samutpatya vepamānā ca taṃ patim
apaśyac chokasaṃtaptaṃ cintāvyākulilendriyam', null, 2023006),
('ramayana-2-23-7', 7, 'Ayodhya Kanda, Sarga 23, Verse 7', 'विवर्णवदनं दृष्ट्वा तं प्रस्विन्नममर्षणम्।
आह दुःखाभिसंतप्ता किमिदानीमिदं प्रभो॥', 'vivarṇavadanaṃ dṛṣṭvā taṃ prasvinnam amarṣaṇam
āha duḥkhābhisaṃtaptā kim idānīm idaṃ prabho', null, 2023007),
('ramayana-2-23-8', 8, 'Ayodhya Kanda, Sarga 23, Verse 8', 'अद्य बार्हस्पतः श्रीमान्युक्तः पुष्यो न राघव।
प्रोच्यते ब्राह्मणैः प्राज्ञैः केन त्वमसि दुर्मनाः॥', 'adya bārhaspataḥ śrīmān yuktaḥ puṣyo na rāghava
procyate brāhmaṇaiḥ prājñaiḥ kena tvam asi durmanāḥ', null, 2023008),
('ramayana-2-23-9', 9, 'Ayodhya Kanda, Sarga 23, Verse 9', 'न ते शतशलाकेन जलफेननिभेन च।
आवृतं वदनं वल्गु छत्रेणाभिविराजते॥', 'na te śataśalākena jalaphenanibhena ca
āvṛtaṃ vadanaṃ valgu chatreṇābhivirājate', null, 2023009),
('ramayana-2-23-10', 10, 'Ayodhya Kanda, Sarga 23, Verse 10', 'व्यजनाभ्यां च मुख्याभ्यां शतपत्रनिभेक्षणम्।
चन्द्रहंसप्रकाशाभ्यां वीज्यते न तवाननम्॥', 'vyajanābhyāṃ ca mukhyābhyāṃ śatapatranibhekṣaṇam
candrahaṃsaprakāśābhyāṃ vījyate na tavānanam', null, 2023010),
('ramayana-2-23-11', 11, 'Ayodhya Kanda, Sarga 23, Verse 11', 'वाग्मिनो बन्दिनश्चापि प्रहृष्टास्त्वं नरर्षभ।
स्तुवन्तो नाद्य दृश्यन्ते मङ्गलैः सूतमागधाः॥', 'vāgmino bandinaś cāpi prahṛṣṭās tvaṃ nararṣabha
stuvanto nādya dṛśyante maṅgalaiḥ sūtamāgadhāḥ', null, 2023011),
('ramayana-2-23-12', 12, 'Ayodhya Kanda, Sarga 23, Verse 12', 'न ते क्षौद्रं च दधि च ब्राह्मणा वेदपारगाः।
मूर्ध्नि मूर्धावसिक्तस्य दधति स्म विधानतः॥', 'na te kṣaudraṃ ca dadhi ca brāhmaṇā vedapāragāḥ
mūrdhni mūrdhāvasiktasya dadhati sma vidhānataḥ', null, 2023012),
('ramayana-2-23-13', 13, 'Ayodhya Kanda, Sarga 23, Verse 13', 'न त्वां प्रकृतयः सर्वा श्रेणीमुख्याश्च भूषिताः।
अनुव्रजितुमिच्छन्ति पौरजापपदास्तथा॥', 'na tvāṃ prakṛtayaḥ sarvā śreṇīmukhyāś ca bhūṣitāḥ
anuvrajitum icchanti paurajāpapadās tathā', null, 2023013),
('ramayana-2-23-14', 14, 'Ayodhya Kanda, Sarga 23, Verse 14', 'चतुर्भिर्वेगसंपन्नैर्हयैः काञ्चनभूषणैः।
मुख्यः पुष्यरथो युक्तः किं न गच्छति तेऽग्रतः॥', 'caturbhir vegasaṃpannair hayaiḥ kāñcanabhūṣaṇaiḥ
mukhyaḥ puṣyaratho yuktaḥ kiṃ na gacchati te ''grataḥ', null, 2023014),
('ramayana-2-23-15', 15, 'Ayodhya Kanda, Sarga 23, Verse 15', 'न हस्ती चाग्रतः श्रीमांस्तव लक्षणपूजितः।
प्रयाणे लक्ष्यते वीर कृष्णमेघगिरि प्रभः॥', 'na hastī cāgrataḥ śrīmāṃs tava lakṣaṇapūjitaḥ
prayāṇe lakṣyate vīra kṛṣṇameghagiri prabhaḥ', null, 2023015),
('ramayana-2-23-16', 16, 'Ayodhya Kanda, Sarga 23, Verse 16', 'न च काञ्चनचित्रं ते पश्यामि प्रियदर्शन।
भद्रासनं पुरस्कृत्य यान्तं वीरपुरःसरम्॥', 'na ca kāñcanacitraṃ te paśyāmi priyadarśana
bhadrāsanaṃ puraskṛtya yāntaṃ vīrapuraḥsaram', null, 2023016),
('ramayana-2-23-17', 17, 'Ayodhya Kanda, Sarga 23, Verse 17', 'अभिषेको यदा सज्जः किमिदानीमिदं तव।
अपूर्वो मुखवर्णश्च न प्रहर्षश्च लक्ष्यते॥', 'abhiṣeko yadā sajjaḥ kim idānīm idaṃ tava
apūrvo mukhavarṇaś ca na praharṣaś ca lakṣyate', null, 2023017),
('ramayana-2-23-18', 18, 'Ayodhya Kanda, Sarga 23, Verse 18', 'इतीव विलपन्तीं तां प्रोवाच रघुनन्दनः।
सीते तत्रभवांस्तात प्रव्राजयति मां वनम्॥', 'itīva vilapantīṃ tāṃ provāca raghunandanaḥ
sīte tatrabhavāṃs tāta pravrājayati māṃ vanam', null, 2023018),
('ramayana-2-23-19', 19, 'Ayodhya Kanda, Sarga 23, Verse 19', 'कुले महति संभूते धर्मज्ञे धर्मचारिणि।
शृणु जानकि येनेदं क्रमेणाभ्यागतं मम॥', 'kule mahati saṃbhūte dharmajñe dharmacāriṇi
śṛṇu jānaki yenedaṃ krameṇābhyāgataṃ mama', null, 2023019),
('ramayana-2-23-20', 20, 'Ayodhya Kanda, Sarga 23, Verse 20', 'राज्ञा सत्यप्रतिज्ञेन पित्रा दशरथेन मे।
कैकेय्यै प्रीतमनसा पुरा दत्तौ महावरौ॥', 'rājñā satyapratijñena pitrā daśarathena me
kaikeyyai prītamanasā purā dattau mahāvarau', null, 2023020),
('ramayana-2-23-21', 21, 'Ayodhya Kanda, Sarga 23, Verse 21', 'तयाद्य मम सज्जेऽस्मिन्नभिषेके नृपोद्यते।
प्रचोदितः स समयो धर्मेण प्रतिनिर्जितः॥', 'tayādya mama sajje ''sminn abhiṣeke nṛpodyate
pracoditaḥ sa samayo dharmeṇa pratinirjitaḥ', null, 2023021),
('ramayana-2-23-22', 22, 'Ayodhya Kanda, Sarga 23, Verse 22', 'चतुर्दश हि वर्षाणि वस्तव्यं दण्डके मया।
पित्रा मे भरतश्चापि यौवराज्ये नियोजितः।
सोऽहं त्वामागतो द्रष्टुं प्रस्थितो विजनं वनम्॥', 'caturdaśa hi varṣāṇi vastavyaṃ daṇḍake mayā
pitrā me bharataś cāpi yauvarājye niyojitaḥ
so ''haṃ tvām āgato draṣṭuṃ prasthito vijanaṃ vanam', null, 2023022),
('ramayana-2-23-23', 23, 'Ayodhya Kanda, Sarga 23, Verse 23', 'भरतस्य समीपे ते नाहं कथ्यः कदा चन।
ऋद्धियुक्ता हि पुरुषा न सहन्ते परस्तवम्।
तस्मान्न ते गुणाः कथ्या भरतस्याग्रतो मम॥', 'bharatasya samīpe te nāhaṃ kathyaḥ kadā cana
ṛddhiyuktā hi puruṣā na sahante parastavam
tasmān na te guṇāḥ kathyā bharatasyāgrato mama', null, 2023023),
('ramayana-2-23-24', 24, 'Ayodhya Kanda, Sarga 23, Verse 24', 'नापि त्वं तेन भर्तव्या विशेषेण कदा चन।
अनुकूलतया शक्यं समीपे तस्य वर्तितुम्॥', 'nāpi tvaṃ tena bhartavyā viśeṣeṇa kadā cana
anukūlatayā śakyaṃ samīpe tasya vartitum', null, 2023024),
('ramayana-2-23-25', 25, 'Ayodhya Kanda, Sarga 23, Verse 25', 'अहं चापि प्रतिज्ञां तां गुरोः समनुपालयन्।
वनमद्यैव यास्यामि स्थिरा भव मनस्विनि॥', 'ahaṃ cāpi pratijñāṃ tāṃ guroḥ samanupālayan
vanam adyaiva yāsyāmi sthirā bhava manasvini', null, 2023025),
('ramayana-2-23-26', 26, 'Ayodhya Kanda, Sarga 23, Verse 26', 'याते च मयि कल्याणि वनं मुनिनिषेवितम्।
व्रतोपवासरतया भवितव्यं त्वयानघे॥', 'yāte ca mayi kalyāṇi vanaṃ muniniṣevitam
vratopavāsaratayā bhavitavyaṃ tvayānaghe', null, 2023026),
('ramayana-2-23-27', 27, 'Ayodhya Kanda, Sarga 23, Verse 27', 'काल्यमुत्थाय देवानां कृत्वा पूजां यथाविधि।
वन्दितव्यो दशरथः पिता मम नरेश्वरः॥', 'kālyam utthāya devānāṃ kṛtvā pūjāṃ yathāvidhi
vanditavyo daśarathaḥ pitā mama nareśvaraḥ', null, 2023027),
('ramayana-2-23-28', 28, 'Ayodhya Kanda, Sarga 23, Verse 28', 'माता च मम कौसल्या वृद्धा संतापकर्शिता।
धर्ममेवाग्रतः कृत्वा त्वत्तः संमानमर्हति॥', 'mātā ca mama kausalyā vṛddhā saṃtāpakarśitā
dharmam evāgrataḥ kṛtvā tvattaḥ saṃmānam arhati', null, 2023028),
('ramayana-2-23-29', 29, 'Ayodhya Kanda, Sarga 23, Verse 29', 'वन्दितव्याश्च ते नित्यं याः शेषा मम मातरः।
स्नेहप्रणयसंभोगैः समा हि मम मातरः॥', 'vanditavyāś ca te nityaṃ yāḥ śeṣā mama mātaraḥ
snehapraṇayasaṃbhogaiḥ samā hi mama mātaraḥ', null, 2023029),
('ramayana-2-23-30', 30, 'Ayodhya Kanda, Sarga 23, Verse 30', 'भ्रातृपुत्रसमौ चापि द्रष्टव्यौ च विशेषतः।
त्वया लक्ष्मणशत्रुघ्नौ प्राणैः प्रियतरौ मम॥', 'bhrātṛputrasamau cāpi draṣṭavyau ca viśeṣataḥ
tvayā lakṣmaṇaśatrughnau prāṇaiḥ priyatarau mama', null, 2023030),
('ramayana-2-23-31', 31, 'Ayodhya Kanda, Sarga 23, Verse 31', 'विप्रियं न च कर्तव्यं भरतस्य कदा चन।
स हि राजा प्रभुश्चैव देशस्य च कुलस्य च॥', 'vipriyaṃ na ca kartavyaṃ bharatasya kadā cana
sa hi rājā prabhuś caiva deśasya ca kulasya ca', null, 2023031),
('ramayana-2-23-32', 32, 'Ayodhya Kanda, Sarga 23, Verse 32', 'आराधिता हि शीलेन प्रयत्नैश्चोपसेविताः।
राजानः संप्रसीदन्ति प्रकुप्यन्ति विपर्यये॥', 'ārādhitā hi śīlena prayatnaiś copasevitāḥ
rājānaḥ saṃprasīdanti prakupyanti viparyaye', null, 2023032),
('ramayana-2-23-33', 33, 'Ayodhya Kanda, Sarga 23, Verse 33', 'औरसानपि पुत्रान्हि त्यजन्त्यहितकारिणः।
समर्थान्संप्रगृह्णन्ति जनानपि नराधिपाः॥', 'aurasān api putrān hi tyajanty ahitakāriṇaḥ
samarthān saṃpragṛhṇanti janān api narādhipāḥ', null, 2023033),
('ramayana-2-23-34', 34, 'Ayodhya Kanda, Sarga 23, Verse 34', 'अहं गमिष्यामि महावनं प्रिये त्वया हि वस्तव्यमिहैव भामिनि।
यथा व्यलीकं कुरुषे न कस्य चित्तथा त्वया कार्यमिदं वचो मम॥', 'ahaṃ gamiṣyāmi mahāvanaṃ priye tvayā hi vastavyam ihaiva bhāmini
yathā vyalīkaṃ kuruṣe na kasya cit tathā tvayā kāryam idaṃ vaco mama', null, 2023034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 24 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-24-1', 1, 'Ayodhya Kanda, Sarga 24, Verse 1', 'एवमुक्ता तु वैदेही प्रियार्हा प्रियवादिनी।
प्रणयादेव संक्रुद्धा भर्तारमिदमब्रवीत्॥', 'evam uktā tu vaidehī priyārhā priyavādinī
praṇayād eva saṃkruddhā bhartāram idam abravīt', null, 2024001),
('ramayana-2-24-2', 2, 'Ayodhya Kanda, Sarga 24, Verse 2', 'आर्यपुत्र पिता माता भ्राता पुत्रस्तथा स्नुषा।
स्वानि पुण्यानि भुञ्जानाः स्वं स्वं भाग्यमुपासते॥', 'āryaputra pitā mātā bhrātā putras tathā snuṣā
svāni puṇyāni bhuñjānāḥ svaṃ svaṃ bhāgyam upāsate', null, 2024002),
('ramayana-2-24-3', 3, 'Ayodhya Kanda, Sarga 24, Verse 3', 'भर्तुर्भाग्यं तु भार्यैका प्राप्नोति पुरुषर्षभ।
अतश्चैवाहमादिष्टा वने वस्तव्यमित्यपि॥', 'bhartur bhāgyaṃ tu bhāryaikā prāpnoti puruṣarṣabha
ataś caivāham ādiṣṭā vane vastavyam ity api', null, 2024003),
('ramayana-2-24-4', 4, 'Ayodhya Kanda, Sarga 24, Verse 4', 'न पिता नात्मजो नात्मा न माता न सखीजनः।
इह प्रेत्य च नारीणां पतिरेको गतिः सदा॥', 'na pitā nātmajo nātmā na mātā na sakhījanaḥ
iha pretya ca nārīṇāṃ patir eko gatiḥ sadā', null, 2024004),
('ramayana-2-24-5', 5, 'Ayodhya Kanda, Sarga 24, Verse 5', 'यदि त्वं प्रस्थितो दुर्गं वनमद्यैव राघव।
अग्रतस्ते गमिष्यामि मृद्नन्ती कुशकण्टकान्॥', 'yadi tvaṃ prasthito durgaṃ vanam adyaiva rāghava
agratas te gamiṣyāmi mṛdnantī kuśakaṇṭakān', null, 2024005),
('ramayana-2-24-6', 6, 'Ayodhya Kanda, Sarga 24, Verse 6', 'ईर्ष्या रोषौ बहिष्कृत्य भुक्तशेषमिवोदकम्।
नय मां वीर विश्रब्धः पापं मयि न विद्यते॥', 'īrṣyā roṣau bahiṣkṛtya bhuktaśeṣam ivodakam
naya māṃ vīra viśrabdhaḥ pāpaṃ mayi na vidyate', null, 2024006),
('ramayana-2-24-7', 7, 'Ayodhya Kanda, Sarga 24, Verse 7', 'प्रासादाग्रैर्विमानैर्वा वैहायसगतेन वा।
सर्वावस्थागता भर्तुः पादच्छाया विशिष्यते॥', 'prāsādāgrair vimānair vā vaihāyasagatena vā
sarvāvasthāgatā bhartuḥ pādacchāyā viśiṣyate', null, 2024007),
('ramayana-2-24-8', 8, 'Ayodhya Kanda, Sarga 24, Verse 8', 'अनुशिष्टास्मि मात्रा च पित्रा च विविधाश्रयम्।
नास्मि संप्रति वक्तव्या वर्तितव्यं यथा मया॥', 'anuśiṣṭāsmi mātrā ca pitrā ca vividhāśrayam
nāsmi saṃprati vaktavyā vartitavyaṃ yathā mayā', null, 2024008),
('ramayana-2-24-9', 9, 'Ayodhya Kanda, Sarga 24, Verse 9', 'सुखं वने निवत्स्यामि यथैव भवने पितुः।
अचिन्तयन्ती त्रींल्लोकांश्चिन्तयन्ती पतिव्रतम्॥', 'sukhaṃ vane nivatsyāmi yathaiva bhavane pituḥ
acintayantī trīṃl lokāṃś cintayantī pativratam', null, 2024009),
('ramayana-2-24-10', 10, 'Ayodhya Kanda, Sarga 24, Verse 10', 'शुश्रूषमाणा ते नित्यं नियता ब्रह्मचारिणी।
सह रंस्ये त्वया वीर वनेषु मधुगन्धिषु॥', 'śuśrūṣamāṇā te nityaṃ niyatā brahmacāriṇī
saha raṃsye tvayā vīra vaneṣu madhugandhiṣu', null, 2024010),
('ramayana-2-24-11', 11, 'Ayodhya Kanda, Sarga 24, Verse 11', 'त्वं हि कर्तुं वने शक्तो राम संपरिपालनम्।
अन्यस्य पै जनस्येह किं पुनर्मम मानद॥', 'tvaṃ hi kartuṃ vane śakto rāma saṃparipālanam
anyasya pai janasyeha kiṃ punar mama mānada', null, 2024011),
('ramayana-2-24-12', 12, 'Ayodhya Kanda, Sarga 24, Verse 12', 'फलमूलाशना नित्यं भविष्यामि न संशयः।
न ते दुःखं करिष्यामि निवसन्ती सह त्वया॥', 'phalamūlāśanā nityaṃ bhaviṣyāmi na saṃśayaḥ
na te duḥkhaṃ kariṣyāmi nivasantī saha tvayā', null, 2024012),
('ramayana-2-24-13', 13, 'Ayodhya Kanda, Sarga 24, Verse 13', 'इच्छामि सरितः शैलान्पल्वलानि वनानि च।
द्रष्टुं सर्वत्र निर्भीता त्वया नाथेन धीमता॥', 'icchāmi saritaḥ śailān palvalāni vanāni ca
draṣṭuṃ sarvatra nirbhītā tvayā nāthena dhīmatā', null, 2024013),
('ramayana-2-24-14', 14, 'Ayodhya Kanda, Sarga 24, Verse 14', 'हंसकारण्डवाकीर्णाः पद्मिनीः साधुपुष्पिताः।
इच्छेयं सुखिनी द्रष्टुं त्वया वीरेण संगता॥', 'haṃsakāraṇḍavākīrṇāḥ padminīḥ sādhupuṣpitāḥ
iccheyaṃ sukhinī draṣṭuṃ tvayā vīreṇa saṃgatā', null, 2024014),
('ramayana-2-24-15', 15, 'Ayodhya Kanda, Sarga 24, Verse 15', 'सह त्वया विशालाक्ष रंस्ये परमनन्दिनी।
एवं वर्षसहस्राणां शतं वाहं त्वया सह॥', 'saha tvayā viśālākṣa raṃsye paramanandinī
evaṃ varṣasahasrāṇāṃ śataṃ vāhaṃ tvayā saha', null, 2024015),
('ramayana-2-24-16', 16, 'Ayodhya Kanda, Sarga 24, Verse 16', 'स्वर्गेऽपि च विना वासो भविता यदि राघव।
त्वया मम नरव्याघ्र नाहं तमपि रोचये॥', 'svarge ''pi ca vinā vāso bhavitā yadi rāghava
tvayā mama naravyāghra nāhaṃ tam api rocaye', null, 2024016),
('ramayana-2-24-17', 17, 'Ayodhya Kanda, Sarga 24, Verse 17', 'अहं गमिष्यामि वनं सुदुर्गमं मृगायुतं वानरवारणैर्युतम्।
वने निवत्स्यामि यथा पितुर्गृहे तवैव पादावुपगृह्य संमता॥', 'ahaṃ gamiṣyāmi vanaṃ sudurgamaṃ mṛgāyutaṃ vānaravāraṇair yutam
vane nivatsyāmi yathā pitur gṛhe tavaiva pādāv upagṛhya saṃmatā', null, 2024017),
('ramayana-2-24-18', 18, 'Ayodhya Kanda, Sarga 24, Verse 18', 'अनन्यभावामनुरक्तचेतसं त्वया वियुक्तां मरणाय निश्चिताम्।
नयस्व मां साधु कुरुष्व याचनां न ते मयातो गुरुता भविष्यति॥', 'ananyabhāvām anuraktacetasaṃ tvayā viyuktāṃ maraṇāya niścitām
nayasva māṃ sādhu kuruṣva yācanāṃ na te mayāto gurutā bhaviṣyati', null, 2024018),
('ramayana-2-24-19', 19, 'Ayodhya Kanda, Sarga 24, Verse 19', 'तथा ब्रुवाणामपि धर्मवत्सलो न च स्म सीतां नृवरो निनीषति।
उवाच चैनां बहु संनिवर्तने वने निवासस्य च दुःखितां प्रति॥', 'tathā bruvāṇām api dharmavatsalo na ca sma sītāṃ nṛvaro ninīṣati
uvāca caināṃ bahu saṃnivartane vane nivāsasya ca duḥkhitāṃ prati', null, 2024019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 25 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-25-1', 1, 'Ayodhya Kanda, Sarga 25, Verse 1', 'स एवं ब्रुवतीं सीतां धर्मज्ञो धर्मवत्सलः।
निवर्तनार्थे धर्मात्मा वाक्यमेतदुवाच ह॥', 'sa evaṃ bruvatīṃ sītāṃ dharmajño dharmavatsalaḥ
nivartanārthe dharmātmā vākyam etad uvāca ha', null, 2025001),
('ramayana-2-25-2', 2, 'Ayodhya Kanda, Sarga 25, Verse 2', 'सीते महाकुलीनासि धर्मे च निरता सदा।
इहाचर स्वधर्मं त्वं मा यथा मनसः सुखम्॥', 'sīte mahākulīnāsi dharme ca niratā sadā
ihācara svadharmaṃ tvaṃ mā yathā manasaḥ sukham', null, 2025002),
('ramayana-2-25-3', 3, 'Ayodhya Kanda, Sarga 25, Verse 3', 'सीते यथा त्वां वक्ष्यामि तथा कार्यं त्वयाबले।
वने दोषा हि बहवो वदतस्तान्निबोध मे॥', 'sīte yathā tvāṃ vakṣyāmi tathā kāryaṃ tvayābale
vane doṣā hi bahavo vadatas tān nibodha me', null, 2025003),
('ramayana-2-25-4', 4, 'Ayodhya Kanda, Sarga 25, Verse 4', 'सीते विमुच्यतामेषा वनवासकृता मतिः।
बहुदोषं हि कान्तारं वनमित्यभिधीयते॥', 'sīte vimucyatām eṣā vanavāsakṛtā matiḥ
bahudoṣaṃ hi kāntāraṃ vanam ity abhidhīyate', null, 2025004),
('ramayana-2-25-5', 5, 'Ayodhya Kanda, Sarga 25, Verse 5', 'हितबुद्ध्या खलु वचो मयैतदभिधीयते।
सदा सुखं न जानामि दुःखमेव सदा वनम्॥', 'hitabuddhyā khalu vaco mayaitad abhidhīyate
sadā sukhaṃ na jānāmi duḥkham eva sadā vanam', null, 2025005),
('ramayana-2-25-6', 6, 'Ayodhya Kanda, Sarga 25, Verse 6', 'गिरिनिर्झरसंभूता गिरिकन्दरवासिनाम्।
सिंहानां निनदा दुःखाः श्रोतुं दुःखमतो वनम्॥', 'girinirjharasaṃbhūtā girikandaravāsinām
siṃhānāṃ ninadā duḥkhāḥ śrotuṃ duḥkham ato vanam', null, 2025006),
('ramayana-2-25-7', 7, 'Ayodhya Kanda, Sarga 25, Verse 7', 'सुप्यते पर्णशय्यासु स्वयं भग्नासु भूतले।
रात्रिषु श्रमखिन्नेन तस्माद्दुःखतरं वनम्॥', 'supyate parṇaśayyāsu svayaṃ bhagnāsu bhūtale
rātriṣu śramakhinnena tasmād duḥkhataraṃ vanam', null, 2025007),
('ramayana-2-25-8', 8, 'Ayodhya Kanda, Sarga 25, Verse 8', 'उपवासश्च कर्तव्या यथाप्राणेन मैथिलि।
जटाभारश्च कर्तव्यो वल्कलाम्बरधारिणा॥', 'upavāsaś ca kartavyā yathāprāṇena maithili
jaṭābhāraś ca kartavyo valkalāmbaradhāriṇā', null, 2025008),
('ramayana-2-25-9', 9, 'Ayodhya Kanda, Sarga 25, Verse 9', 'अतीव वातस्तिमिरं बुभुक्षा चात्र नित्यशः।
भयानि च महान्त्यत्र ततो दुःखतरं वनम्॥', 'atīva vātas timiraṃ bubhukṣā cātra nityaśaḥ
bhayāni ca mahānty atra tato duḥkhataraṃ vanam', null, 2025009),
('ramayana-2-25-10', 10, 'Ayodhya Kanda, Sarga 25, Verse 10', 'सरीसृपाश्च बहवो बहुरूपाश्च भामिनि।
चरन्ति पृथिवीं दर्पादतो दुखतरं वनम्॥', 'sarīsṛpāś ca bahavo bahurūpāś ca bhāmini
caranti pṛthivīṃ darpād ato dukhataraṃ vanam', null, 2025010),
('ramayana-2-25-11', 11, 'Ayodhya Kanda, Sarga 25, Verse 11', 'नदीनिलयनाः सर्पा नदीकुटिलगामिनः।
तिष्ठन्त्यावृत्य पन्थानमतो दुःखतरं वनम्॥', 'nadīnilayanāḥ sarpā nadīkuṭilagāminaḥ
tiṣṭhanty āvṛtya panthānam ato duḥkhataraṃ vanam', null, 2025011),
('ramayana-2-25-12', 12, 'Ayodhya Kanda, Sarga 25, Verse 12', 'पतंगा वृश्चिकाः कीटा दंशाश्च मशकैः सह।
बाधन्ते नित्यमबले सर्वं दुःखमतो वनम्॥', 'pataṃgā vṛścikāḥ kīṭā daṃśāś ca maśakaiḥ saha
bādhante nityam abale sarvaṃ duḥkham ato vanam', null, 2025012),
('ramayana-2-25-13', 13, 'Ayodhya Kanda, Sarga 25, Verse 13', 'द्रुमाः कण्टकिनश्चैव कुशकाशाश्च भामिनि।
वने व्याकुलशाखाग्रास्तेन दुःखतरं वनम्॥', 'drumāḥ kaṇṭakinaś caiva kuśakāśāś ca bhāmini
vane vyākulaśākhāgrās tena duḥkhataraṃ vanam', null, 2025013),
('ramayana-2-25-14', 14, 'Ayodhya Kanda, Sarga 25, Verse 14', 'तदलं ते वनं गत्वा क्षमं न हि वनं तव।
विमृशन्निह पश्यामि बहुदोषतरं वनम्॥', 'tad alaṃ te vanaṃ gatvā kṣamaṃ na hi vanaṃ tava
vimṛśann iha paśyāmi bahudoṣataraṃ vanam', null, 2025014),
('ramayana-2-25-15', 15, 'Ayodhya Kanda, Sarga 25, Verse 15', 'वनं तु नेतुं न कृता मतिस्तदा बभूव रामेण यदा महात्मना।
न तस्य सीता वचनं चकार तत्ततोऽब्रवीद्राममिदं सुदुःखिता॥', 'vanaṃ tu netuṃ na kṛtā matis tadā babhūva rāmeṇa yadā mahātmanā
na tasya sītā vacanaṃ cakāra tat tato ''bravīd rāmam idaṃ suduḥkhitā', null, 2025015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 26 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-26-1', 1, 'Ayodhya Kanda, Sarga 26, Verse 1', 'एतत्तु वचनं श्रुत्वा सीता रामस्य दुःखिता।
प्रसक्ताश्रुमुखी मन्दमिदं वचनमब्रवीत्॥', 'etat tu vacanaṃ śrutvā sītā rāmasya duḥkhitā
prasaktāśrumukhī mandam idaṃ vacanam abravīt', null, 2026001),
('ramayana-2-26-2', 2, 'Ayodhya Kanda, Sarga 26, Verse 2', 'ये त्वया कीर्तिता दोषा वने वस्तव्यतां प्रति।
गुणानित्येव तान्विद्धि तव स्नेहपुरस्कृतान्॥', 'ye tvayā kīrtitā doṣā vane vastavyatāṃ prati
guṇān ity eva tān viddhi tava snehapuraskṛtān', null, 2026002),
('ramayana-2-26-3', 3, 'Ayodhya Kanda, Sarga 26, Verse 3', 'त्वया च सह गन्तव्यं मया गुरुजनाज्ञया।
त्वद्वियोगेन मे राम त्यक्तव्यमिह जीवितम्॥', 'tvayā ca saha gantavyaṃ mayā gurujanājñayā
tvadviyogena me rāma tyaktavyam iha jīvitam', null, 2026003),
('ramayana-2-26-4', 4, 'Ayodhya Kanda, Sarga 26, Verse 4', 'न च मां त्वत्समीपस्थमपि शक्नोति राघव।
सुराणामीश्वरः शक्रः प्रधर्षयितुमोजसा॥', 'na ca māṃ tvatsamīpastham api śaknoti rāghava
surāṇām īśvaraḥ śakraḥ pradharṣayitum ojasā', null, 2026004),
('ramayana-2-26-5', 5, 'Ayodhya Kanda, Sarga 26, Verse 5', 'पतिहीना तु या नारी न सा शक्ष्यति जीवितुम्।
काममेवंविधं राम त्वया मम विदर्शितम्॥', 'patihīnā tu yā nārī na sā śakṣyati jīvitum
kāmam evaṃvidhaṃ rāma tvayā mama vidarśitam', null, 2026005),
('ramayana-2-26-6', 6, 'Ayodhya Kanda, Sarga 26, Verse 6', 'अथ चापि महाप्राज्ञ ब्राह्मणानां मया श्रुतम्।
पुरा पितृगृहे सत्यं वस्तव्यं किल मे वने॥', 'atha cāpi mahāprājña brāhmaṇānāṃ mayā śrutam
purā pitṛgṛhe satyaṃ vastavyaṃ kila me vane', null, 2026006),
('ramayana-2-26-7', 7, 'Ayodhya Kanda, Sarga 26, Verse 7', 'लक्षणिभ्यो द्विजातिभ्यः श्रुत्वाहं वचनं गृहे।
वनवासकृतोत्साहा नित्यमेव महाबल॥', 'lakṣaṇibhyo dvijātibhyaḥ śrutvāhaṃ vacanaṃ gṛhe
vanavāsakṛtotsāhā nityam eva mahābala', null, 2026007),
('ramayana-2-26-8', 8, 'Ayodhya Kanda, Sarga 26, Verse 8', 'आदेशो वनवासस्य प्राप्तव्यः स मया किल।
सा त्वया सह तत्राहं यास्यामि प्रिय नान्यथा॥', 'ādeśo vanavāsasya prāptavyaḥ sa mayā kila
sā tvayā saha tatrāhaṃ yāsyāmi priya nānyathā', null, 2026008),
('ramayana-2-26-9', 9, 'Ayodhya Kanda, Sarga 26, Verse 9', 'कृतादेशा भविष्यामि गमिष्यामि सह त्वया।
कालश्चायं समुत्पन्नः सत्यवाग्भवतु द्विजः॥', 'kṛtādeśā bhaviṣyāmi gamiṣyāmi saha tvayā
kālaś cāyaṃ samutpannaḥ satyavāg bhavatu dvijaḥ', null, 2026009),
('ramayana-2-26-10', 10, 'Ayodhya Kanda, Sarga 26, Verse 10', 'वनवासे हि जानामि दुःखानि बहुधा किल।
प्राप्यन्ते नियतं वीर पुरुषैरकृतात्मभिः॥', 'vanavāse hi jānāmi duḥkhāni bahudhā kila
prāpyante niyataṃ vīra puruṣair akṛtātmabhiḥ', null, 2026010),
('ramayana-2-26-11', 11, 'Ayodhya Kanda, Sarga 26, Verse 11', 'कन्यया च पितुर्गेहे वनवासः श्रुतो मया।
भिक्षिण्याः साधुवृत्ताया मम मातुरिहाग्रतः॥', 'kanyayā ca pitur gehe vanavāsaḥ śruto mayā
bhikṣiṇyāḥ sādhuvṛttāyā mama mātur ihāgrataḥ', null, 2026011),
('ramayana-2-26-12', 12, 'Ayodhya Kanda, Sarga 26, Verse 12', 'प्रसादितश्च वै पूर्वं त्वं वै बहुविधं प्रभो।
गमनं वनवासस्य काङ्क्षितं हि सह त्वया॥', 'prasāditaś ca vai pūrvaṃ tvaṃ vai bahuvidhaṃ prabho
gamanaṃ vanavāsasya kāṅkṣitaṃ hi saha tvayā', null, 2026012),
('ramayana-2-26-13', 13, 'Ayodhya Kanda, Sarga 26, Verse 13', 'कृतक्षणाहं भद्रं ते गमनं प्रति राघव।
वनवासस्य शूरस्य चर्या हि मम रोचते॥', 'kṛtakṣaṇāhaṃ bhadraṃ te gamanaṃ prati rāghava
vanavāsasya śūrasya caryā hi mama rocate', null, 2026013),
('ramayana-2-26-14', 14, 'Ayodhya Kanda, Sarga 26, Verse 14', 'शुद्धात्मन्प्रेमभावाद्धि भविष्यामि विकल्मषा।
भर्तारमनुगच्छन्ती भर्ता हि मम दैवतम्॥', 'śuddhātman premabhāvād dhi bhaviṣyāmi vikalmaṣā
bhartāram anugacchantī bhartā hi mama daivatam', null, 2026014),
('ramayana-2-26-15', 15, 'Ayodhya Kanda, Sarga 26, Verse 15', 'प्रेत्यभावेऽपि कल्याणः संगमो मे सह त्वया।
श्रुतिर्हि श्रूयते पुण्या ब्राह्मणानां यशस्विनाम्॥', 'pretyabhāve ''pi kalyāṇaḥ saṃgamo me saha tvayā
śrutir hi śrūyate puṇyā brāhmaṇānāṃ yaśasvinām', null, 2026015),
('ramayana-2-26-16', 16, 'Ayodhya Kanda, Sarga 26, Verse 16', 'इह लोके च पितृभिर्या स्त्री यस्य महामते।
अद्भिर्दत्ता स्वधर्मेण प्रेत्यभावेऽपि तस्य सा॥', 'iha loke ca pitṛbhir yā strī yasya mahāmate
adbhir dattā svadharmeṇa pretyabhāve ''pi tasya sā', null, 2026016),
('ramayana-2-26-17', 17, 'Ayodhya Kanda, Sarga 26, Verse 17', 'एवमस्मात्स्वकां नारीं सुवृत्तां हि पतिव्रताम्।
नाभिरोचयसे नेतुं त्वं मां केनेह हेतुना॥', 'evam asmāt svakāṃ nārīṃ suvṛttāṃ hi pativratām
nābhirocayase netuṃ tvaṃ māṃ keneha hetunā', null, 2026017),
('ramayana-2-26-18', 18, 'Ayodhya Kanda, Sarga 26, Verse 18', 'भक्तां पतिव्रतां दीनां मां समां सुखदुःखयोः।
नेतुमर्हसि काकुत्स्थ समानसुखदुःखिनीम्॥', 'bhaktāṃ pativratāṃ dīnāṃ māṃ samāṃ sukhaduḥkhayoḥ
netum arhasi kākutstha samānasukhaduḥkhinīm', null, 2026018),
('ramayana-2-26-19', 19, 'Ayodhya Kanda, Sarga 26, Verse 19', 'यदि मां दुःखितामेवं वनं नेतुं न चेच्छसि।
विषमग्निं जलं वाहमास्थास्ये मृत्युकारणात्॥', 'yadi māṃ duḥkhitām evaṃ vanaṃ netuṃ na cecchasi
viṣam agniṃ jalaṃ vāham āsthāsye mṛtyukāraṇāt', null, 2026019),
('ramayana-2-26-20', 20, 'Ayodhya Kanda, Sarga 26, Verse 20', 'एवं बहुविधं तं सा याचते गमनं प्रति।
नानुमेने महाबाहुस्तां नेतुं विजनं वनम्॥', 'evaṃ bahuvidhaṃ taṃ sā yācate gamanaṃ prati
nānumene mahābāhus tāṃ netuṃ vijanaṃ vanam', null, 2026020),
('ramayana-2-26-21', 21, 'Ayodhya Kanda, Sarga 26, Verse 21', 'एवमुक्ता तु सा चिन्तां मैथिली समुपागता।
स्नापयन्तीव गामुष्णैरश्रुभिर्नयनच्युतैः॥', 'evam uktā tu sā cintāṃ maithilī samupāgatā
snāpayantīva gām uṣṇair aśrubhir nayanacyutaiḥ', null, 2026021),
('ramayana-2-26-22', 22, 'Ayodhya Kanda, Sarga 26, Verse 22', 'चिन्तयन्तीं तथा तां तु निवर्तयितुमात्मवान्।
क्रोधाविष्टां तु वैदेहीं काकुत्स्थो बह्वसान्त्वयत्॥', 'cintayantīṃ tathā tāṃ tu nivartayitum ātmavān
krodhāviṣṭāṃ tu vaidehīṃ kākutstho bahv asāntvayat', null, 2026022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 27 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-27-1', 1, 'Ayodhya Kanda, Sarga 27, Verse 1', 'सान्त्व्यमाना तु रामेण मैथिली जनकात्मजा।
वनवासनिमित्ताय भर्तारमिदमब्रवीत्॥', 'sāntvyamānā tu rāmeṇa maithilī janakātmajā
vanavāsanimittāya bhartāram idam abravīt', null, 2027001),
('ramayana-2-27-2', 2, 'Ayodhya Kanda, Sarga 27, Verse 2', 'सा तमुत्तमसंविग्ना सीता विपुलवक्षसं।
प्रणयाच्चाभिमानाच्च परिचिक्षेप राघवम्॥', 'sā tam uttamasaṃvignā sītā vipulavakṣasaṃ
praṇayāc cābhimānāc ca paricikṣepa rāghavam', null, 2027002),
('ramayana-2-27-3', 3, 'Ayodhya Kanda, Sarga 27, Verse 3', 'किं त्वामन्यत वैदेहः पिता मे मिथिलाधिपः।
राम जामातरं प्राप्य स्त्रियं पुरुषविग्रहम्॥', 'kiṃ tvāmanyata vaidehaḥ pitā me mithilādhipaḥ
rāma jāmātaraṃ prāpya striyaṃ puruṣavigraham', null, 2027003),
('ramayana-2-27-4', 4, 'Ayodhya Kanda, Sarga 27, Verse 4', 'अनृतं बललोकोऽयमज्ञानाद्यद्धि वक्ष्यति।
तेजो नास्ति परं रामे तपतीव दिवाकरे॥', 'anṛtaṃ balaloko ''yam ajñānād yad dhi vakṣyati
tejo nāsti paraṃ rāme tapatīva divākare', null, 2027004),
('ramayana-2-27-5', 5, 'Ayodhya Kanda, Sarga 27, Verse 5', 'किं हि कृत्वा विषण्णस्त्वं कुतो वा भयमस्ति ते।
यत्परित्यक्तुकामस्त्वं मामनन्यपरायणाम्॥', 'kiṃ hi kṛtvā viṣaṇṇas tvaṃ kuto vā bhayam asti te
yat parityaktukāmas tvaṃ mām ananyaparāyaṇām', null, 2027005),
('ramayana-2-27-6', 6, 'Ayodhya Kanda, Sarga 27, Verse 6', 'द्युमत्सेनसुतं वीर सत्यवन्तमनुव्रताम्।
सावित्रीमिव मां विद्धि त्वमात्मवशवर्तिनीम्॥', 'dyumatsenasutaṃ vīra satyavantam anuvratām
sāvitrīm iva māṃ viddhi tvam ātmavaśavartinīm', null, 2027006),
('ramayana-2-27-7', 7, 'Ayodhya Kanda, Sarga 27, Verse 7', 'न त्वहं मनसाप्यन्यं द्रष्टास्मि त्वदृतेऽनघ।
त्वया राघव गच्छेयं यथान्या कुलपांसनी॥', 'na tv ahaṃ manasāpy anyaṃ draṣṭāsmi tvadṛte ''nagha
tvayā rāghava gaccheyaṃ yathānyā kulapāṃsanī', null, 2027007),
('ramayana-2-27-8', 8, 'Ayodhya Kanda, Sarga 27, Verse 8', 'स्वयं तु भार्यां कौमारीं चिरमध्युषितां सतीम्।
शैलूष इव मां राम परेभ्यो दातुमिच्छसि॥', 'svayaṃ tu bhāryāṃ kaumārīṃ ciram adhyuṣitāṃ satīm
śailūṣa iva māṃ rāma parebhyo dātum icchasi', null, 2027008),
('ramayana-2-27-9', 9, 'Ayodhya Kanda, Sarga 27, Verse 9', 'स मामनादाय वनं न त्वं प्रस्थातुमर्हसि।
तपो वा यदि वारण्यं स्वर्गो वा स्यात्सह त्वया॥', 'sa mām anādāya vanaṃ na tvaṃ prasthātum arhasi
tapo vā yadi vāraṇyaṃ svargo vā syāt saha tvayā', null, 2027009),
('ramayana-2-27-10', 10, 'Ayodhya Kanda, Sarga 27, Verse 10', 'न च मे भविता तत्र कश्चित्पथि परिश्रमः।
पृष्ठतस्तव गच्छन्त्या विहारशयनेष्वपि॥', 'na ca me bhavitā tatra kaś cit pathi pariśramaḥ
pṛṣṭhatas tava gacchantyā vihāraśayaneṣv api', null, 2027010),
('ramayana-2-27-11', 11, 'Ayodhya Kanda, Sarga 27, Verse 11', 'कुशकाशशरेषीका ये च कण्टकिनो द्रुमाः।
तूलाजिनसमस्पर्शा मार्गे मम सह त्वया॥', 'kuśakāśaśareṣīkā ye ca kaṇṭakino drumāḥ
tūlājinasamasparśā mārge mama saha tvayā', null, 2027011),
('ramayana-2-27-12', 12, 'Ayodhya Kanda, Sarga 27, Verse 12', 'महावात समुद्धूतं यन्मामवकरिष्यति।
रजो रमण तन्मन्ये परार्ध्यमिव चन्दनम्॥', 'mahāvāta samuddhūtaṃ yan mām avakariṣyati
rajo ramaṇa tan manye parārdhyam iva candanam', null, 2027012),
('ramayana-2-27-13', 13, 'Ayodhya Kanda, Sarga 27, Verse 13', 'शाद्वलेषु यदासिष्ये वनान्ते वनगोरचा।
कुथास्तरणतल्पेषु किं स्यात्सुखतरं ततः॥', 'śādvaleṣu yad āsiṣye vanānte vanagoracā
kuthāstaraṇatalpeṣu kiṃ syāt sukhataraṃ tataḥ', null, 2027013),
('ramayana-2-27-14', 14, 'Ayodhya Kanda, Sarga 27, Verse 14', 'पत्रं मूलं फलं यत्त्वमल्पं वा यदि वा बहु।
दास्यसि स्वयमाहृत्य तन्मेऽमृतरसोपमम्॥', 'patraṃ mūlaṃ phalaṃ yat tvam alpaṃ vā yadi vā bahu
dāsyasi svayam āhṛtya tan me ''mṛtarasopamam', null, 2027014),
('ramayana-2-27-15', 15, 'Ayodhya Kanda, Sarga 27, Verse 15', 'न मातुर्न पितुस्तत्र स्मरिष्यामि न वेश्मनः।
आर्तवान्युपभुञ्जाना पुष्पाणि च फलानि च॥', 'na mātur na pitus tatra smariṣyāmi na veśmanaḥ
ārtavāny upabhuñjānā puṣpāṇi ca phalāni ca', null, 2027015),
('ramayana-2-27-16', 16, 'Ayodhya Kanda, Sarga 27, Verse 16', 'न च तत्र गतः किं चिद्द्रष्टुमर्हसि विप्रियम्।
मत्कृते न च ते शोको न भविष्यामि दुर्भरा॥', 'na ca tatra gataḥ kiṃ cid draṣṭum arhasi vipriyam
matkṛte na ca te śoko na bhaviṣyāmi durbharā', null, 2027016),
('ramayana-2-27-17', 17, 'Ayodhya Kanda, Sarga 27, Verse 17', 'यस्त्वया सह स स्वर्गो निरयो यस्त्वया विना।
इति जानन्परां प्रीतिं गच्छ राम मया सह॥', 'yas tvayā saha sa svargo nirayo yas tvayā vinā
iti jānan parāṃ prītiṃ gaccha rāma mayā saha', null, 2027017),
('ramayana-2-27-18', 18, 'Ayodhya Kanda, Sarga 27, Verse 18', 'अथ मामेवमव्यग्रां वनं नैव नयिष्यसि।
विषमद्यैव पास्यामि मा विशं द्विषतां वशम्॥', 'atha mām evam avyagrāṃ vanaṃ naiva nayiṣyasi
viṣam adyaiva pāsyāmi mā viśaṃ dviṣatāṃ vaśam', null, 2027018),
('ramayana-2-27-19', 19, 'Ayodhya Kanda, Sarga 27, Verse 19', 'पश्चादपि हि दुःखेन मम नैवास्ति जीवितम्।
उज्झितायास्त्वया नाथ तदैव मरणं वरम्॥', 'paścād api hi duḥkhena mama naivāsti jīvitam
ujjhitāyās tvayā nātha tadaiva maraṇaṃ varam', null, 2027019),
('ramayana-2-27-20', 20, 'Ayodhya Kanda, Sarga 27, Verse 20', 'इदं हि सहितुं शोकं मुहूर्तमपि नोत्सहे।
किं पुनर्दशवर्षाणि त्रीणि चैकं च दुःखिता॥', 'idaṃ hi sahituṃ śokaṃ muhūrtam api notsahe
kiṃ punar daśavarṣāṇi trīṇi caikaṃ ca duḥkhitā', null, 2027020),
('ramayana-2-27-21', 21, 'Ayodhya Kanda, Sarga 27, Verse 21', 'इति सा शोकसंतप्ता विलप्य करुणं बहु।
चुक्रोश पतिमायस्ता भृशमालिङ्ग्य सस्वरम्॥', 'iti sā śokasaṃtaptā vilapya karuṇaṃ bahu
cukrośa patim āyastā bhṛśam āliṅgya sasvaram', null, 2027021),
('ramayana-2-27-22', 22, 'Ayodhya Kanda, Sarga 27, Verse 22', 'सा विद्धा बहुभिर्वाक्यैर्दिग्धैरिव गजाङ्गना।
चिर संनियतं बाष्पं मुमोचाग्निमिवारणिः॥', 'sā viddhā bahubhir vākyair digdhair iva gajāṅganā
cira saṃniyataṃ bāṣpaṃ mumocāgnim ivāraṇiḥ', null, 2027022),
('ramayana-2-27-23', 23, 'Ayodhya Kanda, Sarga 27, Verse 23', 'तस्याः स्फटिकसंकाशं वारि संतापसंभवम्।
नेत्राभ्यां परिसुस्राव पङ्कजाभ्यामिवोदकम्॥', 'tasyāḥ sphaṭikasaṃkāśaṃ vāri saṃtāpasaṃbhavam
netrābhyāṃ parisusrāva paṅkajābhyām ivodakam', null, 2027023),
('ramayana-2-27-24', 24, 'Ayodhya Kanda, Sarga 27, Verse 24', 'तां परिष्वज्य बाहुभ्यां विसंज्ञामिव दुःखिताम्।
उवाच वचनं रामः परिविश्वासयंस्तदा॥', 'tāṃ pariṣvajya bāhubhyāṃ visaṃjñām iva duḥkhitām
uvāca vacanaṃ rāmaḥ pariviśvāsayaṃs tadā', null, 2027024),
('ramayana-2-27-25', 25, 'Ayodhya Kanda, Sarga 27, Verse 25', 'न देवि तव दुःखेन स्वर्गमप्यभिरोचये।
न हि मेऽस्ति भयं किं चित्स्वयम्भोरिव सर्वतः॥', 'na devi tava duḥkhena svargam apy abhirocaye
na hi me ''sti bhayaṃ kiṃ cit svayambhor iva sarvataḥ', null, 2027025),
('ramayana-2-27-26', 26, 'Ayodhya Kanda, Sarga 27, Verse 26', 'तव सर्वमभिप्रायमविज्ञाय शुभानने।
वासं न रोचयेऽरण्ये शक्तिमानपि रक्षणे॥', 'tava sarvam abhiprāyam avijñāya śubhānane
vāsaṃ na rocaye ''raṇye śaktimān api rakṣaṇe', null, 2027026),
('ramayana-2-27-27', 27, 'Ayodhya Kanda, Sarga 27, Verse 27', 'यत्सृष्टासि मया सार्धं वनवासाय मैथिलि।
न विहातुं मया शक्या कीर्तिरात्मवता यथा॥', 'yat sṛṣṭāsi mayā sārdhaṃ vanavāsāya maithili
na vihātuṃ mayā śakyā kīrtir ātmavatā yathā', null, 2027027),
('ramayana-2-27-28', 28, 'Ayodhya Kanda, Sarga 27, Verse 28', 'धर्मस्तु गजनासोरु सद्भिराचरितः पुरा।
तं चाहमनुवर्तेऽद्य यथा सूर्यं सुवर्चला॥', 'dharmas tu gajanāsoru sadbhir ācaritaḥ purā
taṃ cāham anuvarte ''dya yathā sūryaṃ suvarcalā', null, 2027028),
('ramayana-2-27-29', 29, 'Ayodhya Kanda, Sarga 27, Verse 29', 'एष धर्मस्तु सुश्रोणि पितुर्मातुश्च वश्यता।
अतश्चाज्ञां व्यतिक्रम्य नाहं जीवितुमुत्सहे॥', 'eṣa dharmas tu suśroṇi pitur mātuś ca vaśyatā
ataś cājñāṃ vyatikramya nāhaṃ jīvitum utsahe', null, 2027029),
('ramayana-2-27-30', 30, 'Ayodhya Kanda, Sarga 27, Verse 30', 'स मां पिता यथा शास्ति सत्यधर्मपथे स्थितः।
तथा वर्तितुमिच्छामि स हि धर्मः सनातनः।
अनुगच्छस्व मां भीरु सहधर्मचरी भव॥', 'sa māṃ pitā yathā śāsti satyadharmapathe sthitaḥ
tathā vartitum icchāmi sa hi dharmaḥ sanātanaḥ
anugacchasva māṃ bhīru sahadharmacarī bhava', null, 2027030),
('ramayana-2-27-31', 31, 'Ayodhya Kanda, Sarga 27, Verse 31', 'ब्राह्मणेभ्यश्च रत्नानि भिक्षुकेभ्यश्च भोजनम्।
देहि चाशंसमानेभ्यः संत्वरस्व च माचिरम्॥', 'brāhmaṇebhyaś ca ratnāni bhikṣukebhyaś ca bhojanam
dehi cāśaṃsamānebhyaḥ saṃtvarasva ca māciram', null, 2027031),
('ramayana-2-27-32', 32, 'Ayodhya Kanda, Sarga 27, Verse 32', 'अनुकूलं तु सा भर्तुर्ज्ञात्वा गमनमात्मनः।
क्षिप्रं प्रमुदिता देवी दातुमेवोपचक्रमे॥', 'anukūlaṃ tu sā bhartur jñātvā gamanam ātmanaḥ
kṣipraṃ pramuditā devī dātum evopacakrame', null, 2027032),
('ramayana-2-27-33', 33, 'Ayodhya Kanda, Sarga 27, Verse 33', 'ततः प्रहृष्टा परिपूर्णमानसा यशस्विनी भर्तुरवेक्ष्य भाषितम्।
धनानि रत्नानि च दातुमङ्गना प्रचक्रमे धर्मभृतां मनस्विनी॥', 'tataḥ prahṛṣṭā paripūrṇamānasā yaśasvinī bhartur avekṣya bhāṣitam
dhanāni ratnāni ca dātum aṅganā pracakrame dharmabhṛtāṃ manasvinī', null, 2027033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 28 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-28-1', 1, 'Ayodhya Kanda, Sarga 28, Verse 1', 'ततोऽब्रवीन्महातेजा रामो लक्ष्मणमग्रतः।
स्थितं प्राग्गामिनं वीरं याचमानं कृताञ्जलिम्॥', 'tato ''bravīn mahātejā rāmo lakṣmaṇam agrataḥ
sthitaṃ prāggāminaṃ vīraṃ yācamānaṃ kṛtāñjalim', null, 2028001),
('ramayana-2-28-2', 2, 'Ayodhya Kanda, Sarga 28, Verse 2', 'मयाद्य सह सौमित्रे त्वयि गच्छति तद्वनम्।
को भरिष्यति कौसल्यां सुमित्रां वा यशस्विनीम्॥', 'mayādya saha saumitre tvayi gacchati tad vanam
ko bhariṣyati kausalyāṃ sumitrāṃ vā yaśasvinīm', null, 2028002),
('ramayana-2-28-3', 3, 'Ayodhya Kanda, Sarga 28, Verse 3', 'अभिवर्षति कामैर्यः पर्जन्यः पृथिवीमिव।
स कामपाशपर्यस्तो महातेजा महीपतिः॥', 'abhivarṣati kāmair yaḥ parjanyaḥ pṛthivīm iva
sa kāmapāśaparyasto mahātejā mahīpatiḥ', null, 2028003),
('ramayana-2-28-4', 4, 'Ayodhya Kanda, Sarga 28, Verse 4', 'सा हि राज्यमिदं प्राप्य नृपस्याश्वपतेः सुता।
दुःखितानां सपत्नीनां न करिष्यति शोभनम्॥', 'sā hi rājyam idaṃ prāpya nṛpasyāśvapateḥ sutā
duḥkhitānāṃ sapatnīnāṃ na kariṣyati śobhanam', null, 2028004),
('ramayana-2-28-5', 5, 'Ayodhya Kanda, Sarga 28, Verse 5', 'एवमुक्तस्तु रामेण लक्ष्मणः श्लक्ष्णया गिरा।
प्रत्युवाच तदा रामं वाक्यज्ञो वाक्यकोविदम्॥', 'evam uktas tu rāmeṇa lakṣmaṇaḥ ślakṣṇayā girā
pratyuvāca tadā rāmaṃ vākyajño vākyakovidam', null, 2028005),
('ramayana-2-28-6', 6, 'Ayodhya Kanda, Sarga 28, Verse 6', 'तवैव तेजसा वीर भरतः पूजयिष्यति।
कौसल्यां च सुमित्रां च प्रयतो नात्र संशयः॥', 'tavaiva tejasā vīra bharataḥ pūjayiṣyati
kausalyāṃ ca sumitrāṃ ca prayato nātra saṃśayaḥ', null, 2028006),
('ramayana-2-28-7', 7, 'Ayodhya Kanda, Sarga 28, Verse 7', 'कौसल्या बिभृयादार्या सहस्रमपि मद्विधान्।
यस्याः सहस्रं ग्रामाणां संप्राप्तमुपजीवनम्॥', 'kausalyā bibhṛyād āryā sahasram api madvidhān
yasyāḥ sahasraṃ grāmāṇāṃ saṃprāptam upajīvanam', null, 2028007),
('ramayana-2-28-8', 8, 'Ayodhya Kanda, Sarga 28, Verse 8', 'धनुरादाय सशरं खनित्रपिटकाधरः।
अग्रतस्ते गमिष्यामि पन्थानमनुदर्शयन्॥', 'dhanur ādāya saśaraṃ khanitrapiṭakādharaḥ
agratas te gamiṣyāmi panthānam anudarśayan', null, 2028008),
('ramayana-2-28-9', 9, 'Ayodhya Kanda, Sarga 28, Verse 9', 'आहरिष्यामि ते नित्यं मूलानि च फलानि च।
वन्यानि यानि चान्यानि स्वाहाराणि तपस्विनाम्॥', 'āhariṣyāmi te nityaṃ mūlāni ca phalāni ca
vanyāni yāni cānyāni svāhārāṇi tapasvinām', null, 2028009),
('ramayana-2-28-10', 10, 'Ayodhya Kanda, Sarga 28, Verse 10', 'भवांस्तु सह वैदेह्या गिरिसानुषु रंस्यते।
अहं सर्वं करिष्यामि जाग्रतः स्वपतश्च ते॥', 'bhavāṃs tu saha vaidehyā girisānuṣu raṃsyate
ahaṃ sarvaṃ kariṣyāmi jāgrataḥ svapataś ca te', null, 2028010),
('ramayana-2-28-11', 11, 'Ayodhya Kanda, Sarga 28, Verse 11', 'रामस्त्वनेन वाक्येन सुप्रीतः प्रत्युवाच तम्।
व्रजापृच्छस्व सौमित्रे सर्वमेव सुहृज्जनम्॥', 'rāmas tv anena vākyena suprītaḥ pratyuvāca tam
vrajāpṛcchasva saumitre sarvam eva suhṛjjanam', null, 2028011),
('ramayana-2-28-12', 12, 'Ayodhya Kanda, Sarga 28, Verse 12', 'ये च राज्ञो ददौ दिव्ये महात्मा वरुणः स्वयम्।
जनकस्य महायज्ञे धनुषी रौद्रदर्शने॥', 'ye ca rājño dadau divye mahātmā varuṇaḥ svayam
janakasya mahāyajñe dhanuṣī raudradarśane', null, 2028012),
('ramayana-2-28-13', 13, 'Ayodhya Kanda, Sarga 28, Verse 13', 'अभेद्यकवचे दिव्ये तूणी चाक्षयसायकौ।
आदित्यविमलौ चोभौ खड्गौ हेमपरिष्कृतौ॥', 'abhedyakavace divye tūṇī cākṣayasāyakau
ādityavimalau cobhau khaḍgau hemapariṣkṛtau', null, 2028013),
('ramayana-2-28-14', 14, 'Ayodhya Kanda, Sarga 28, Verse 14', 'सत्कृत्य निहितं सर्वमेतदाचार्यसद्मनि।
स त्वमायुधमादाय क्षिप्रमाव्रज लक्ष्मण॥', 'satkṛtya nihitaṃ sarvam etad ācāryasadmani
sa tvam āyudham ādāya kṣipram āvraja lakṣmaṇa', null, 2028014),
('ramayana-2-28-15', 15, 'Ayodhya Kanda, Sarga 28, Verse 15', 'स सुहृज्जनमामन्त्र्य वनवासाय निश्चितः।
इक्ष्वाकुगुरुमामन्त्र्य जग्राहायुधमुत्तमम्॥', 'sa suhṛjjanam āmantrya vanavāsāya niścitaḥ
ikṣvākugurum āmantrya jagrāhāyudham uttamam', null, 2028015),
('ramayana-2-28-16', 16, 'Ayodhya Kanda, Sarga 28, Verse 16', 'तद्दिव्यं राजशार्दूलः सत्कृतं माल्यभूषितम्।
रामाय दर्शयामास सौमित्रिः सर्वमायुधम्॥', 'tad divyaṃ rājaśārdūlaḥ satkṛtaṃ mālyabhūṣitam
rāmāya darśayām āsa saumitriḥ sarvam āyudham', null, 2028016),
('ramayana-2-28-17', 17, 'Ayodhya Kanda, Sarga 28, Verse 17', 'तमुवाचात्मवान्रामः प्रीत्या लक्ष्मणमागतम्।
काले त्वमागतः सौम्य काङ्क्षिते मम लक्ष्मण॥', 'tam uvācātmavān rāmaḥ prītyā lakṣmaṇam āgatam
kāle tvam āgataḥ saumya kāṅkṣite mama lakṣmaṇa', null, 2028017),
('ramayana-2-28-18', 18, 'Ayodhya Kanda, Sarga 28, Verse 18', 'अहं प्रदातुमिच्छामि यदिदं मामकं धनम्।
ब्राह्मणेभ्यस्तपस्विभ्यस्त्वया सह परंतप॥', 'ahaṃ pradātum icchāmi yad idaṃ māmakaṃ dhanam
brāhmaṇebhyas tapasvibhyas tvayā saha paraṃtapa', null, 2028018),
('ramayana-2-28-19', 19, 'Ayodhya Kanda, Sarga 28, Verse 19', 'वसन्तीह दृढं भक्त्या गुरुषु द्विजसत्तमाः।
तेषामपि च मे भूयः सर्वेषां चोपजीविनाम्॥', 'vasantīha dṛḍhaṃ bhaktyā guruṣu dvijasattamāḥ
teṣām api ca me bhūyaḥ sarveṣāṃ copajīvinām', null, 2028019),
('ramayana-2-28-20', 20, 'Ayodhya Kanda, Sarga 28, Verse 20', 'वसिष्ठपुत्रं तु सुयज्ञमार्यं त्वमानयाशु प्रवरं द्विजानाम्।
अभिप्रयास्यामि वनं समस्तानभ्यर्च्य शिष्टानपरान्द्विजातीन्॥', 'vasiṣṭhaputraṃ tu suyajñam āryaṃ tvam ānayāśu pravaraṃ dvijānām
abhiprayāsyāmi vanaṃ samastān abhyarcya śiṣṭān aparān dvijātīn', null, 2028020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 29 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-29-1', 1, 'Ayodhya Kanda, Sarga 29, Verse 1', 'ततः शासनमाज्ञाय भ्रातुः शुभतरं प्रियम्।
गत्वा स प्रविवेशाशु सुयज्ञस्य निवेशनम्॥', 'tataḥ śāsanam ājñāya bhrātuḥ śubhataraṃ priyam
gatvā sa praviveśāśu suyajñasya niveśanam', null, 2029001),
('ramayana-2-29-2', 2, 'Ayodhya Kanda, Sarga 29, Verse 2', 'तं विप्रमग्न्यगारस्थं वन्दित्वा लक्ष्मणोऽब्रवीत्।
सखेऽभ्यागच्छ पश्य त्वं वेश्म दुष्करकारिणः॥', 'taṃ vipram agnyagārasthaṃ vanditvā lakṣmaṇo ''bravīt
sakhe ''bhyāgaccha paśya tvaṃ veśma duṣkarakāriṇaḥ', null, 2029002),
('ramayana-2-29-3', 3, 'Ayodhya Kanda, Sarga 29, Verse 3', 'ततः संध्यामुपास्याशु गत्वा सौमित्रिणा सह।
जुष्टं तत्प्राविशल्लक्ष्म्या रम्यं रामनिवेशनम्॥', 'tataḥ saṃdhyām upāsyāśu gatvā saumitriṇā saha
juṣṭaṃ tat prāviśal lakṣmyā ramyaṃ rāmaniveśanam', null, 2029003),
('ramayana-2-29-4', 4, 'Ayodhya Kanda, Sarga 29, Verse 4', 'तमागतं वेदविदं प्राञ्जलिः सीतया सह।
सुयज्ञमभिचक्राम राघवोऽग्निमिवार्चितम्॥', 'tam āgataṃ vedavidaṃ prāñjaliḥ sītayā saha
suyajñam abhicakrāma rāghavo ''gnim ivārcitam', null, 2029004),
('ramayana-2-29-5', 5, 'Ayodhya Kanda, Sarga 29, Verse 5', 'जातरूपमयैर्मुख्यैरङ्गदैः कुण्डलैः शुभैः।
सहेम सूत्रैर्मणिभिः केयूरैर्वलयैरपि॥', 'jātarūpamayair mukhyair aṅgadaiḥ kuṇḍalaiḥ śubhaiḥ
sahema sūtrair maṇibhiḥ keyūrair valayair api', null, 2029005),
('ramayana-2-29-6', 6, 'Ayodhya Kanda, Sarga 29, Verse 6', 'अन्यैश्च रत्नैर्बहुभिः काकुत्स्थः प्रत्यपूजयत्।
सुयज्ञं स तदोवाच रामः सीताप्रचोदितः॥', 'anyaiś ca ratnair bahubhiḥ kākutsthaḥ pratyapūjayat
suyajñaṃ sa tadovāca rāmaḥ sītāpracoditaḥ', null, 2029006),
('ramayana-2-29-7', 7, 'Ayodhya Kanda, Sarga 29, Verse 7', 'हारं च हेमसूत्रं च भार्यायै सौम्य हारय।
रशनां चाधुना सीता दातुमिच्छति ते सखे॥', 'hāraṃ ca hemasūtraṃ ca bhāryāyai saumya hāraya
raśanāṃ cādhunā sītā dātum icchati te sakhe', null, 2029007),
('ramayana-2-29-8', 8, 'Ayodhya Kanda, Sarga 29, Verse 8', 'पर्यङ्कमग्र्यास्तरणं नानारत्नविभूषितम्।
तमपीच्छति वैदेही प्रतिष्ठापयितुं त्वयि॥', 'paryaṅkam agryāstaraṇaṃ nānāratnavibhūṣitam
tam apīcchati vaidehī pratiṣṭhāpayituṃ tvayi', null, 2029008),
('ramayana-2-29-9', 9, 'Ayodhya Kanda, Sarga 29, Verse 9', 'नागः शत्रुं जयो नाम मातुलो यं ददौ मम।
तं ते गजसहस्रेण ददामि द्विजपुंगव॥', 'nāgaḥ śatruṃ jayo nāma mātulo yaṃ dadau mama
taṃ te gajasahasreṇa dadāmi dvijapuṃgava', null, 2029009),
('ramayana-2-29-10', 10, 'Ayodhya Kanda, Sarga 29, Verse 10', 'इत्युक्तः स हि रामेण सुयज्ञः प्रतिगृह्य तत्।
रामलक्ष्मणसीतानां प्रयुयोजाशिषः शिवाः॥', 'ity uktaḥ sa hi rāmeṇa suyajñaḥ pratigṛhya tat
rāmalakṣmaṇasītānāṃ prayuyojāśiṣaḥ śivāḥ', null, 2029010),
('ramayana-2-29-11', 11, 'Ayodhya Kanda, Sarga 29, Verse 11', 'अथ भ्रातरमव्यग्रं प्रियं रामः प्रियंवदः।
सौमित्रिं तमुवाचेदं ब्रह्मेव त्रिदशेश्वरम्॥', 'atha bhrātaram avyagraṃ priyaṃ rāmaḥ priyaṃvadaḥ
saumitriṃ tam uvācedaṃ brahmeva tridaśeśvaram', null, 2029011),
('ramayana-2-29-12', 12, 'Ayodhya Kanda, Sarga 29, Verse 12', 'अगस्त्यं कौशिकं चैव तावुभौ ब्राह्मणोत्तमौ।
अर्चयाहूय सौमित्रे रत्नैः सस्यमिवाम्बुभिः॥', 'agastyaṃ kauśikaṃ caiva tāv ubhau brāhmaṇottamau
arcayāhūya saumitre ratnaiḥ sasyam ivāmbubhiḥ', null, 2029012),
('ramayana-2-29-13', 13, 'Ayodhya Kanda, Sarga 29, Verse 13', 'कौसल्यां च य आशीर्भिर्भक्तः पर्युपतिष्ठति।
आचार्यस्तैत्तिरीयाणामभिरूपश्च वेदवित्॥', 'kausalyāṃ ca ya āśīrbhir bhaktaḥ paryupatiṣṭhati
ācāryas taittirīyāṇām abhirūpaś ca vedavit', null, 2029013),
('ramayana-2-29-14', 14, 'Ayodhya Kanda, Sarga 29, Verse 14', 'तस्य यानं च दासीश्च सौमित्रे संप्रदापय।
कौशेयानि च वस्त्राणि यावत्तुष्यति स द्विजः॥', 'tasya yānaṃ ca dāsīś ca saumitre saṃpradāpaya
kauśeyāni ca vastrāṇi yāvat tuṣyati sa dvijaḥ', null, 2029014),
('ramayana-2-29-15', 15, 'Ayodhya Kanda, Sarga 29, Verse 15', 'सूतश्चित्ररथश्चार्यः सचिवः सुचिरोषितः।
तोषयैनं महार्हैश्च रत्नैर्वस्त्रैर्धनैस्तथा॥', 'sūtaś citrarathaś cāryaḥ sacivaḥ suciroṣitaḥ
toṣayainaṃ mahārhaiś ca ratnair vastrair dhanais tathā', null, 2029015),
('ramayana-2-29-16', 16, 'Ayodhya Kanda, Sarga 29, Verse 16', 'शालिवाहसहस्रं च द्वे शते भद्रकांस्तथा।
व्यञ्जनार्थं च सौमित्रे गोसहस्रमुपाकुरु॥', 'śālivāhasahasraṃ ca dve śate bhadrakāṃs tathā
vyañjanārthaṃ ca saumitre gosahasram upākuru', null, 2029016),
('ramayana-2-29-17', 17, 'Ayodhya Kanda, Sarga 29, Verse 17', 'ततः स पुरुषव्याघ्रस्तद्धनं लक्ष्मणः स्वयम्।
यथोक्तं ब्राह्मणेन्द्राणामददाद्धनदो यथा॥', 'tataḥ sa puruṣavyāghras tad dhanaṃ lakṣmaṇaḥ svayam
yathoktaṃ brāhmaṇendrāṇām adadād dhanado yathā', null, 2029017),
('ramayana-2-29-18', 18, 'Ayodhya Kanda, Sarga 29, Verse 18', 'अथाब्रवीद्बाष्पकलांस्तिष्ठतश्चोपजीविनः।
संप्रदाय बहु द्रव्यमेकैकस्योपजीविनः॥', 'athābravīd bāṣpakalāṃs tiṣṭhataś copajīvinaḥ
saṃpradāya bahu dravyam ekaikasyopajīvinaḥ', null, 2029018),
('ramayana-2-29-19', 19, 'Ayodhya Kanda, Sarga 29, Verse 19', 'लक्ष्मणस्य च यद्वेश्म गृहं च यदिदं मम।
अशून्यं कार्यमेकैकं यावदागमनं मम॥', 'lakṣmaṇasya ca yad veśma gṛhaṃ ca yad idaṃ mama
aśūnyaṃ kāryam ekaikaṃ yāvadāgamanaṃ mama', null, 2029019),
('ramayana-2-29-20', 20, 'Ayodhya Kanda, Sarga 29, Verse 20', 'इत्युक्त्वा दुःखितं सर्वं जनं तमुपजीविनम्।
उवाचेदं धनध्यक्षं धनमानीयतामिति।
ततोऽस्य धनमाजह्रुः सर्वमेवोपजीविनः॥', 'ity uktvā duḥkhitaṃ sarvaṃ janaṃ tam upajīvinam
uvācedaṃ dhanadhyakṣaṃ dhanam ānīyatām iti
tato ''sya dhanam ājahruḥ sarvam evopajīvinaḥ', null, 2029020),
('ramayana-2-29-21', 21, 'Ayodhya Kanda, Sarga 29, Verse 21', 'ततः स पुरुषव्याघ्रस्तद्धनं सहलक्ष्मणः।
द्विजेभ्यो बालवृद्धेभ्यः कृपणेभ्योऽभ्यदापयत्॥', 'tataḥ sa puruṣavyāghras tad dhanaṃ sahalakṣmaṇaḥ
dvijebhyo bālavṛddhebhyaḥ kṛpaṇebhyo ''bhyadāpayat', null, 2029021),
('ramayana-2-29-22', 22, 'Ayodhya Kanda, Sarga 29, Verse 22', 'तत्रासीत्पिङ्गलो गार्ग्यस्त्रिजटो नाम वै द्विजः।
आ पञ्चमायाः कक्ष्याया नैनं कश्चिदवारयत्॥', 'tatrāsīt piṅgalo gārgyas trijaṭo nāma vai dvijaḥ
ā pañcamāyāḥ kakṣyāyā nainaṃ kaś cid avārayat', null, 2029022),
('ramayana-2-29-23', 23, 'Ayodhya Kanda, Sarga 29, Verse 23', 'स राजपुत्रमासाद्य त्रिजटो वाक्यमब्रवीत्।
निर्धनो बहुपुत्रोऽस्मि राजपुत्र महायशः।
उञ्छवृत्तिर्वने नित्यं प्रत्यवेक्षस्व मामिति॥', 'sa rājaputram āsādya trijaṭo vākyam abravīt
nirdhano bahuputro ''smi rājaputra mahāyaśaḥ
uñchavṛttir vane nityaṃ pratyavekṣasva mām iti', null, 2029023),
('ramayana-2-29-24', 24, 'Ayodhya Kanda, Sarga 29, Verse 24', 'तमुवाच ततो रामः परिहाससमन्वितम्।
गवां सहस्रमप्येकं न तु विश्राणितं मया।
परिक्षिपसि दण्डेन यावत्तावदवाप्स्यसि॥', 'tam uvāca tato rāmaḥ parihāsasamanvitam
gavāṃ sahasram apy ekaṃ na tu viśrāṇitaṃ mayā
parikṣipasi daṇḍena yāvat tāvad avāpsyasi', null, 2029024),
('ramayana-2-29-25', 25, 'Ayodhya Kanda, Sarga 29, Verse 25', 'स शाटीं त्वरितः कट्यां संभ्रान्तः परिवेष्ट्य ताम्।
आविध्य दण्डं चिक्षेप सर्वप्राणेन वेगितः॥', 'sa śāṭīṃ tvaritaḥ kaṭyāṃ saṃbhrāntaḥ pariveṣṭya tām
āvidhya daṇḍaṃ cikṣepa sarvaprāṇena vegitaḥ', null, 2029025),
('ramayana-2-29-26', 26, 'Ayodhya Kanda, Sarga 29, Verse 26', 'उवाच च ततो रामस्तं गार्ग्यमभिसान्त्वयन्।
मन्युर्न खलु कर्तव्यः परिहासो ह्ययं मम॥', 'uvāca ca tato rāmas taṃ gārgyam abhisāntvayan
manyur na khalu kartavyaḥ parihāso hy ayaṃ mama', null, 2029026),
('ramayana-2-29-27', 27, 'Ayodhya Kanda, Sarga 29, Verse 27', 'ततः सभार्यस्त्रिजटो महामुनिर्गवामनीकं प्रतिगृह्य मोदितः।
यशोबलप्रीतिसुखोपबृंहिणीस्तदाशिषः प्रत्यवदन्महात्मनः॥', 'tataḥ sabhāryas trijaṭo mahāmunir gavām anīkaṃ pratigṛhya moditaḥ
yaśobalaprītisukhopabṛṃhiṇīs tad āśiṣaḥ pratyavadan mahātmanaḥ', null, 2029027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 30 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-30-1', 1, 'Ayodhya Kanda, Sarga 30, Verse 1', 'दत्त्वा तु सह वैदेह्या ब्राह्मणेभ्यो धनं बहु।
जग्मतुः पितरं द्रष्टुं सीतया सह राघवौ॥', 'dattvā tu saha vaidehyā brāhmaṇebhyo dhanaṃ bahu
jagmatuḥ pitaraṃ draṣṭuṃ sītayā saha rāghavau', null, 2030001),
('ramayana-2-30-2', 2, 'Ayodhya Kanda, Sarga 30, Verse 2', 'ततो गृहीते दुष्प्रेक्ष्ये अशोभेतां तदायुधे।
मालादामभिरासक्ते सीतया समलंकृते॥', 'tato gṛhīte duṣprekṣye aśobhetāṃ tadāyudhe
mālādāmabhir āsakte sītayā samalaṃkṛte', null, 2030002),
('ramayana-2-30-3', 3, 'Ayodhya Kanda, Sarga 30, Verse 3', 'ततः प्रासादहर्म्याणि विमानशिखराणि च।
अधिरुह्य जनः श्रीमानुदासीनो व्यलोकयत्॥', 'tataḥ prāsādaharmyāṇi vimānaśikharāṇi ca
adhiruhya janaḥ śrīmān udāsīno vyalokayat', null, 2030003),
('ramayana-2-30-4', 4, 'Ayodhya Kanda, Sarga 30, Verse 4', 'न हि रथ्याः स्म शक्यन्ते गन्तुं बहुजनाकुलाः।
आरुह्य तस्मात्प्रासादान्दीनाः पश्यन्ति राघवम्॥', 'na hi rathyāḥ sma śakyante gantuṃ bahujanākulāḥ
āruhya tasmāt prāsādān dīnāḥ paśyanti rāghavam', null, 2030004),
('ramayana-2-30-5', 5, 'Ayodhya Kanda, Sarga 30, Verse 5', 'पदातिं वर्जितच्छत्रं रामं दृष्ट्वा तदा जनाः।
ऊचुर्बहुविधा वाचः शोकोपहतचेतसः॥', 'padātiṃ varjitacchatraṃ rāmaṃ dṛṣṭvā tadā janāḥ
ūcur bahuvidhā vācaḥ śokopahatacetasaḥ', null, 2030005),
('ramayana-2-30-6', 6, 'Ayodhya Kanda, Sarga 30, Verse 6', 'यं यान्तमनुयाति स्म चतुरङ्गबलं महत्।
तमेकं सीतया सार्धमनुयाति स्म लक्ष्मणः॥', 'yaṃ yāntam anuyāti sma caturaṅgabalaṃ mahat
tam ekaṃ sītayā sārdham anuyāti sma lakṣmaṇaḥ', null, 2030006),
('ramayana-2-30-7', 7, 'Ayodhya Kanda, Sarga 30, Verse 7', 'ऐश्वर्यस्य रसज्ञः सन्कामिनां चैव कामदः।
नेच्छत्येवानृतं कर्तुं पितरं धर्मगौरवात्॥', 'aiśvaryasya rasajñaḥ san kāmināṃ caiva kāmadaḥ
necchaty evānṛtaṃ kartuṃ pitaraṃ dharmagauravāt', null, 2030007),
('ramayana-2-30-8', 8, 'Ayodhya Kanda, Sarga 30, Verse 8', 'या न शक्या पुरा द्रष्टुं भूतैराकाशगैरपि।
तामद्य सीतां पश्यन्ति राजमार्गगता जनाः॥', 'yā na śakyā purā draṣṭuṃ bhūtair ākāśagair api
tām adya sītāṃ paśyanti rājamārgagatā janāḥ', null, 2030008),
('ramayana-2-30-9', 9, 'Ayodhya Kanda, Sarga 30, Verse 9', 'अङ्गरागोचितां सीतां रक्तचन्दन सेविनीम्।
वर्षमुष्णं च शीतं च नेष्यत्याशु विवर्णताम्॥', 'aṅgarāgocitāṃ sītāṃ raktacandana sevinīm
varṣam uṣṇaṃ ca śītaṃ ca neṣyaty āśu vivarṇatām', null, 2030009),
('ramayana-2-30-10', 10, 'Ayodhya Kanda, Sarga 30, Verse 10', 'अद्य नूनं दशरथः सत्त्वमाविश्य भाषते।
न हि राजा प्रियं पुत्रं विवासयितुमर्हति॥', 'adya nūnaṃ daśarathaḥ sattvam āviśya bhāṣate
na hi rājā priyaṃ putraṃ vivāsayitum arhati', null, 2030010),
('ramayana-2-30-11', 11, 'Ayodhya Kanda, Sarga 30, Verse 11', 'निर्गुणस्यापि पुत्रस्या काथं स्याद्विप्रवासनम्।
किं पुनर्यस्य लोकोऽयं जितो वृत्तेन केवलम्॥', 'nirguṇasyāpi putrasyā kāthaṃ syād vipravāsanam
kiṃ punar yasya loko ''yaṃ jito vṛttena kevalam', null, 2030011),
('ramayana-2-30-12', 12, 'Ayodhya Kanda, Sarga 30, Verse 12', 'आनृशंस्यमनुक्रोशः श्रुतं शीलं दमः शमः।
राघवं शोभयन्त्येते षड्गुणाः पुरुषोत्तमम्॥', 'ānṛśaṃsyam anukrośaḥ śrutaṃ śīlaṃ damaḥ śamaḥ
rāghavaṃ śobhayanty ete ṣaḍguṇāḥ puruṣottamam', null, 2030012),
('ramayana-2-30-13', 13, 'Ayodhya Kanda, Sarga 30, Verse 13', 'तस्मात्तस्योपघातेन प्रजाः परमपीडिताः।
औदकानीव सत्त्वानि ग्रीष्मे सलिलसंक्षयात्॥', 'tasmāt tasyopaghātena prajāḥ paramapīḍitāḥ
audakānīva sattvāni grīṣme salilasaṃkṣayāt', null, 2030013),
('ramayana-2-30-14', 14, 'Ayodhya Kanda, Sarga 30, Verse 14', 'पीडया पीडितं सर्वं जगदस्य जगत्पतेः।
मूलस्येवोपघातेन वृक्षः पुष्पफलोपगः॥', 'pīḍayā pīḍitaṃ sarvaṃ jagad asya jagatpateḥ
mūlasyevopaghātena vṛkṣaḥ puṣpaphalopagaḥ', null, 2030014),
('ramayana-2-30-15', 15, 'Ayodhya Kanda, Sarga 30, Verse 15', 'ते लक्ष्मण इव क्षिप्रं सपत्न्यः सहबान्धवाः।
गच्छन्तमनुगच्छामो येन गच्छति राघवः॥', 'te lakṣmaṇa iva kṣipraṃ sapatnyaḥ sahabāndhavāḥ
gacchantam anugacchāmo yena gacchati rāghavaḥ', null, 2030015),
('ramayana-2-30-16', 16, 'Ayodhya Kanda, Sarga 30, Verse 16', 'उद्यानानि परित्यज्य क्षेत्राणि च गृहाणि च।
एकदुःखसुखा राममनुगच्छाम धार्मिकम्॥', 'udyānāni parityajya kṣetrāṇi ca gṛhāṇi ca
ekaduḥkhasukhā rāmam anugacchāma dhārmikam', null, 2030016),
('ramayana-2-30-17', 17, 'Ayodhya Kanda, Sarga 30, Verse 17', 'समुद्धृतनिधानानि परिध्वस्ताजिराणि च।
उपात्तधनधान्यानि हृतसाराणि सर्वशः॥', 'samuddhṛtanidhānāni paridhvastājirāṇi ca
upāttadhanadhānyāni hṛtasārāṇi sarvaśaḥ', null, 2030017),
('ramayana-2-30-18', 18, 'Ayodhya Kanda, Sarga 30, Verse 18', 'रजसाभ्यवकीर्णानि परित्यक्तानि दैवतैः।
अस्मत्त्यक्तानि वेश्मानि कैकेयी प्रतिपद्यताम्॥', 'rajasābhyavakīrṇāni parityaktāni daivataiḥ
asmattyaktāni veśmāni kaikeyī pratipadyatām', null, 2030018),
('ramayana-2-30-19', 19, 'Ayodhya Kanda, Sarga 30, Verse 19', 'वनं नगरमेवास्तु येन गच्छति राघवः।
अस्माभिश्च परित्यक्तं पुरं संपद्यतां वनम्॥', 'vanaṃ nagaram evāstu yena gacchati rāghavaḥ
asmābhiś ca parityaktaṃ puraṃ saṃpadyatāṃ vanam', null, 2030019),
('ramayana-2-30-20', 20, 'Ayodhya Kanda, Sarga 30, Verse 20', 'बिलानि दंष्ट्रिणः सर्वे सानूनि मृगपक्षिणः।
अस्मत्त्यक्तं प्रपद्यन्तां सेव्यमानं त्यजन्तु च॥', 'bilāni daṃṣṭriṇaḥ sarve sānūni mṛgapakṣiṇaḥ
asmattyaktaṃ prapadyantāṃ sevyamānaṃ tyajantu ca', null, 2030020),
('ramayana-2-30-21', 21, 'Ayodhya Kanda, Sarga 30, Verse 21', 'इत्येवं विविधा वाचो नानाजनसमीरिताः।
शुश्राव रामः श्रुत्वा च न विचक्रेऽस्य मानसं॥', 'ity evaṃ vividhā vāco nānājanasamīritāḥ
śuśrāva rāmaḥ śrutvā ca na vicakre ''sya mānasaṃ', null, 2030021),
('ramayana-2-30-22', 22, 'Ayodhya Kanda, Sarga 30, Verse 22', 'प्रतीक्षमाणोऽभिजनं तदार्तमनार्तरूपः प्रहसन्निवाथ।
जगाम रामः पितरं दिदृक्षुः पितुर्निदेशं विधिवच्चिकीर्षुः॥', 'pratīkṣamāṇo ''bhijanaṃ tadārtam anārtarūpaḥ prahasann ivātha
jagāma rāmaḥ pitaraṃ didṛkṣuḥ pitur nideśaṃ vidhivac cikīrṣuḥ', null, 2030022),
('ramayana-2-30-23', 23, 'Ayodhya Kanda, Sarga 30, Verse 23', 'तत्पूर्वमैक्ष्वाकसुतो महात्मा रामो गमिष्यन्वनमार्तरूपम्।
व्यतिष्ठत प्रेक्ष्य तदा सुमन्त्रं पितुर्महात्मा प्रतिहारणार्थम्॥', 'tat pūrvam aikṣvākasuto mahātmā rāmo gamiṣyan vanam ārtarūpam
vyatiṣṭhata prekṣya tadā sumantraṃ pitur mahātmā pratihāraṇārtham', null, 2030023),
('ramayana-2-30-24', 24, 'Ayodhya Kanda, Sarga 30, Verse 24', 'पितुर्निदेशेन तु धर्मवत्सलो वनप्रवेशे कृतबुद्धिनिश्चयः।
स राघवः प्रेक्ष्य सुमन्त्रमब्रवीन्निवेदयस्वागमनं नृपाय मे॥', 'pitur nideśena tu dharmavatsalo vanapraveśe kṛtabuddhiniścayaḥ
sa rāghavaḥ prekṣya sumantram abravīn nivedayasvāgamanaṃ nṛpāya me', null, 2030024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 31 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-31-1', 1, 'Ayodhya Kanda, Sarga 31, Verse 1', 'स रामप्रेषितः क्षिप्रं संतापकलुषेन्द्रियः।
प्रविश्य नृपतिं सूतो निःश्वसन्तं ददर्श ह॥', 'sa rāmapreṣitaḥ kṣipraṃ saṃtāpakaluṣendriyaḥ
praviśya nṛpatiṃ sūto niḥśvasantaṃ dadarśa ha', null, 2031001),
('ramayana-2-31-2', 2, 'Ayodhya Kanda, Sarga 31, Verse 2', 'आलोक्य तु महाप्राज्ञः परमाकुल चेतसं।
राममेवानुशोचन्तं सूतः प्राञ्जलिरासदत्॥', 'ālokya tu mahāprājñaḥ paramākula cetasaṃ
rāmam evānuśocantaṃ sūtaḥ prāñjalir āsadat', null, 2031002),
('ramayana-2-31-3', 3, 'Ayodhya Kanda, Sarga 31, Verse 3', 'अयं स पुरुषव्याघ्र द्वारि तिष्ठति ते सुतः।
ब्राह्मणेभ्यो धनं दत्त्वा सर्वं चैवोपजीविनाम्॥', 'ayaṃ sa puruṣavyāghra dvāri tiṣṭhati te sutaḥ
brāhmaṇebhyo dhanaṃ dattvā sarvaṃ caivopajīvinām', null, 2031003),
('ramayana-2-31-4', 4, 'Ayodhya Kanda, Sarga 31, Verse 4', 'स त्वा पश्यतु भद्रं ते रामः सत्यपराक्रमः।
सर्वान्सुहृद आपृच्छ्य त्वामिदानीं दिदृक्षते॥', 'sa tvā paśyatu bhadraṃ te rāmaḥ satyaparākramaḥ
sarvān suhṛda āpṛcchya tvām idānīṃ didṛkṣate', null, 2031004),
('ramayana-2-31-5', 5, 'Ayodhya Kanda, Sarga 31, Verse 5', 'गमिष्यति महारण्यं तं पश्य जगतीपते।
वृतं राजगुणैः सर्वैरादित्यमिव रश्मिभिः॥', 'gamiṣyati mahāraṇyaṃ taṃ paśya jagatīpate
vṛtaṃ rājaguṇaiḥ sarvair ādityam iva raśmibhiḥ', null, 2031005),
('ramayana-2-31-6', 6, 'Ayodhya Kanda, Sarga 31, Verse 6', 'स सत्यवादी धर्मात्मा गाम्भीर्यात्सागरोपमः।
आकाश इव निष्पङ्को नरेन्द्रः प्रत्युवाच तम्॥', 'sa satyavādī dharmātmā gāmbhīryāt sāgaropamaḥ
ākāśa iva niṣpaṅko narendraḥ pratyuvāca tam', null, 2031006),
('ramayana-2-31-7', 7, 'Ayodhya Kanda, Sarga 31, Verse 7', 'सुमन्त्रानय मे दारान्ये के चिदिह मामकाः।
दारैः परिवृतः सर्वैर्द्रष्टुमिच्छामि राघवम्॥', 'sumantrānaya me dārān ye ke cid iha māmakāḥ
dāraiḥ parivṛtaḥ sarvair draṣṭum icchāmi rāghavam', null, 2031007),
('ramayana-2-31-8', 8, 'Ayodhya Kanda, Sarga 31, Verse 8', 'सोऽन्तःपुरमतीत्यैव स्त्रियस्ता वाक्यमब्रवीत्।
आर्यो ह्वयति वो राजा गम्यतां तत्र माचिरम्॥', 'so ''ntaḥpuram atītyaiva striyas tā vākyam abravīt
āryo hvayati vo rājā gamyatāṃ tatra māciram', null, 2031008),
('ramayana-2-31-9', 9, 'Ayodhya Kanda, Sarga 31, Verse 9', 'एवमुक्ताः स्त्रियः सर्वाः सुमन्त्रेण नृपाज्ञया।
प्रचक्रमुस्तद्भवनं भर्तुराज्ञाय शासनम्॥', 'evam uktāḥ striyaḥ sarvāḥ sumantreṇa nṛpājñayā
pracakramus tad bhavanaṃ bhartur ājñāya śāsanam', null, 2031009),
('ramayana-2-31-10', 10, 'Ayodhya Kanda, Sarga 31, Verse 10', 'अर्धसप्तशतास्तास्तु प्रमदास्ताम्रलोचनाः।
कौसल्यां परिवार्याथ शनैर्जग्मुर्धृतव्रताः॥', 'ardhasaptaśatās tās tu pramadās tāmralocanāḥ
kausalyāṃ parivāryātha śanair jagmur dhṛtavratāḥ', null, 2031010),
('ramayana-2-31-11', 11, 'Ayodhya Kanda, Sarga 31, Verse 11', 'आगतेषु च दारेषु समवेक्ष्य महीपतिः।
उवाच राजा तं सूतं सुमन्त्रानय मे सुतम्॥', 'āgateṣu ca dāreṣu samavekṣya mahīpatiḥ
uvāca rājā taṃ sūtaṃ sumantrānaya me sutam', null, 2031011),
('ramayana-2-31-12', 12, 'Ayodhya Kanda, Sarga 31, Verse 12', 'स सूतो राममादाय लक्ष्मणं मैथिलीं तदा।
जगामाभिमुखस्तूर्णं सकाशं जगतीपतेः॥', 'sa sūto rāmam ādāya lakṣmaṇaṃ maithilīṃ tadā
jagāmābhimukhas tūrṇaṃ sakāśaṃ jagatīpateḥ', null, 2031012),
('ramayana-2-31-13', 13, 'Ayodhya Kanda, Sarga 31, Verse 13', 'स राजा पुत्रमायान्तं दृष्ट्वा दूरात्कृताञ्जलिम्।
उत्पपातासनात्तूर्णमार्तः स्त्रीजनसंवृतः॥', 'sa rājā putram āyāntaṃ dṛṣṭvā dūrāt kṛtāñjalim
utpapātāsanāt tūrṇam ārtaḥ strījanasaṃvṛtaḥ', null, 2031013),
('ramayana-2-31-14', 14, 'Ayodhya Kanda, Sarga 31, Verse 14', 'सोऽभिदुद्राव वेगेन रामं दृष्ट्वा विशां पतिः।
तमसंप्राप्य दुःखार्तः पपात भुवि मूर्छितः॥', 'so ''bhidudrāva vegena rāmaṃ dṛṣṭvā viśāṃ patiḥ
tam asaṃprāpya duḥkhārtaḥ papāta bhuvi mūrchitaḥ', null, 2031014),
('ramayana-2-31-15', 15, 'Ayodhya Kanda, Sarga 31, Verse 15', 'तं रामोऽभ्यपातत्क्षिप्रं लक्ष्मणश्च महारथः।
विसंज्ञमिव दुःखेन सशोकं नृपतिं तदा॥', 'taṃ rāmo ''bhyapātat kṣipraṃ lakṣmaṇaś ca mahārathaḥ
visaṃjñam iva duḥkhena saśokaṃ nṛpatiṃ tadā', null, 2031015),
('ramayana-2-31-16', 16, 'Ayodhya Kanda, Sarga 31, Verse 16', 'स्त्रीसहस्रनिनादश्च संजज्ञे राजवेश्मनि।
हाहा रामेति सहसा भूषणध्वनिमूर्छितः॥', 'strīsahasraninādaś ca saṃjajñe rājaveśmani
hāhā rāmeti sahasā bhūṣaṇadhvanimūrchitaḥ', null, 2031016),
('ramayana-2-31-17', 17, 'Ayodhya Kanda, Sarga 31, Verse 17', 'तं परिष्वज्य बाहुभ्यां तावुभौ रामलक्ष्मणौ।
पर्यङ्के सीतया सार्धं रुदन्तः समवेशयन्॥', 'taṃ pariṣvajya bāhubhyāṃ tāv ubhau rāmalakṣmaṇau
paryaṅke sītayā sārdhaṃ rudantaḥ samaveśayan', null, 2031017),
('ramayana-2-31-18', 18, 'Ayodhya Kanda, Sarga 31, Verse 18', 'अथ रामो मुहूर्तेन लब्धसंज्ञं महीपतिम्।
उवाच प्राञ्जलिर्भूत्वा शोकार्णवपरिप्लुतम्॥', 'atha rāmo muhūrtena labdhasaṃjñaṃ mahīpatim
uvāca prāñjalir bhūtvā śokārṇavapariplutam', null, 2031018),
('ramayana-2-31-19', 19, 'Ayodhya Kanda, Sarga 31, Verse 19', 'आपृच्छे त्वां महाराज सर्वेषामीश्वरोऽसि नः।
प्रस्थितं दण्डकारण्यं पश्य त्वं कुशलेन माम्॥', 'āpṛcche tvāṃ mahārāja sarveṣām īśvaro ''si naḥ
prasthitaṃ daṇḍakāraṇyaṃ paśya tvaṃ kuśalena mām', null, 2031019),
('ramayana-2-31-20', 20, 'Ayodhya Kanda, Sarga 31, Verse 20', 'लक्ष्मणं चानुजानीहि सीता चान्वेति मां वनम्।
कारणैर्बहुभिस्तथ्यैर्वार्यमाणौ न चेच्छतः॥', 'lakṣmaṇaṃ cānujānīhi sītā cānveti māṃ vanam
kāraṇair bahubhis tathyair vāryamāṇau na cecchataḥ', null, 2031020),
('ramayana-2-31-21', 21, 'Ayodhya Kanda, Sarga 31, Verse 21', 'अनुजानीहि सर्वान्नः शोकमुत्सृज्य मानद।
लक्ष्मणं मां च सीतां च प्रजापतिरिव प्रजाः॥', 'anujānīhi sarvān naḥ śokam utsṛjya mānada
lakṣmaṇaṃ māṃ ca sītāṃ ca prajāpatir iva prajāḥ', null, 2031021),
('ramayana-2-31-22', 22, 'Ayodhya Kanda, Sarga 31, Verse 22', 'प्रतीक्षमाणमव्यग्रमनुज्ञां जगतीपतेः।
उवाच रर्जा संप्रेक्ष्य वनवासाय राघवम्॥', 'pratīkṣamāṇam avyagram anujñāṃ jagatīpateḥ
uvāca rarjā saṃprekṣya vanavāsāya rāghavam', null, 2031022),
('ramayana-2-31-23', 23, 'Ayodhya Kanda, Sarga 31, Verse 23', 'अहं राघव कैकेय्या वरदानेन मोहितः।
अयोध्यायास्त्वमेवाद्य भव राजा निगृह्य माम्॥', 'ahaṃ rāghava kaikeyyā varadānena mohitaḥ
ayodhyāyās tvam evādya bhava rājā nigṛhya mām', null, 2031023),
('ramayana-2-31-24', 24, 'Ayodhya Kanda, Sarga 31, Verse 24', 'एवमुक्तो नृपतिना रामो धर्मभृतां वरः।
प्रत्युवाचाञ्जलिं कृत्वा पितरं वाक्यकोविदः॥', 'evam ukto nṛpatinā rāmo dharmabhṛtāṃ varaḥ
pratyuvācāñjaliṃ kṛtvā pitaraṃ vākyakovidaḥ', null, 2031024),
('ramayana-2-31-25', 25, 'Ayodhya Kanda, Sarga 31, Verse 25', 'भवान्वर्षसहस्राय पृथिव्या नृपते पतिः।
अहं त्वरण्ये वत्स्यामि न मे कार्यं त्वयानृतम्॥', 'bhavān varṣasahasrāya pṛthivyā nṛpate patiḥ
ahaṃ tv araṇye vatsyāmi na me kāryaṃ tvayānṛtam', null, 2031025),
('ramayana-2-31-26', 26, 'Ayodhya Kanda, Sarga 31, Verse 26', 'श्रेयसे वृद्धये तात पुनरागमनाय च।
गच्छस्वारिष्टमव्यग्रः पन्थानमकुतोभयम्॥', 'śreyase vṛddhaye tāta punarāgamanāya ca
gacchasvāriṣṭam avyagraḥ panthānam akutobhayam', null, 2031026),
('ramayana-2-31-27', 27, 'Ayodhya Kanda, Sarga 31, Verse 27', 'अद्य त्विदानीं रजनीं पुत्र मा गच्छ सर्वथा।
मातरं मां च संपश्यन्वसेमामद्य शर्वरीम्।
तर्पितः सर्वकामैस्त्वं श्वःकाले साधयिष्यसि॥', 'adya tv idānīṃ rajanīṃ putra mā gaccha sarvathā
mātaraṃ māṃ ca saṃpaśyan vasemām adya śarvarīm
tarpitaḥ sarvakāmais tvaṃ śvaḥkāle sādhayiṣyasi', null, 2031027),
('ramayana-2-31-28', 28, 'Ayodhya Kanda, Sarga 31, Verse 28', 'अथ रामस्तथा श्रुत्वा पितुरार्तस्य भाषितम्।
लक्ष्मणेन सह भ्रात्रा दीनो वचनमब्रवीत्॥', 'atha rāmas tathā śrutvā pitur ārtasya bhāṣitam
lakṣmaṇena saha bhrātrā dīno vacanam abravīt', null, 2031028),
('ramayana-2-31-29', 29, 'Ayodhya Kanda, Sarga 31, Verse 29', 'प्राप्स्यामि यानद्य गुणान्को मे श्वस्तान्प्रदास्यति।
अपक्रमणमेवातः सर्वकामैरहं वृणे॥', 'prāpsyāmi yān adya guṇān ko me śvastān pradāsyati
apakramaṇam evātaḥ sarvakāmair ahaṃ vṛṇe', null, 2031029),
('ramayana-2-31-30', 30, 'Ayodhya Kanda, Sarga 31, Verse 30', 'इयं सराष्ट्रा सजना धनधान्यसमाकुला।
मया विसृष्टा वसुधा भरताय प्रदीयताम्॥', 'iyaṃ sarāṣṭrā sajanā dhanadhānyasamākulā
mayā visṛṣṭā vasudhā bharatāya pradīyatām', null, 2031030),
('ramayana-2-31-31', 31, 'Ayodhya Kanda, Sarga 31, Verse 31', 'अपगच्छतु ते दुःखं मा भूर्बाष्पपरिप्लुतः।
न हि क्षुभ्यति दुर्धर्षः समुद्रः सरितां पतिः॥', 'apagacchatu te duḥkhaṃ mā bhūr bāṣpapariplutaḥ
na hi kṣubhyati durdharṣaḥ samudraḥ saritāṃ patiḥ', null, 2031031),
('ramayana-2-31-32', 32, 'Ayodhya Kanda, Sarga 31, Verse 32', 'नैवाहं राज्यमिच्छामि न सुखं न च मैथिलीम्।
त्वामहं सत्यमिच्छामि नानृतं पुरुषर्षभ॥', 'naivāhaṃ rājyam icchāmi na sukhaṃ na ca maithilīm
tvām ahaṃ satyam icchāmi nānṛtaṃ puruṣarṣabha', null, 2031032),
('ramayana-2-31-33', 33, 'Ayodhya Kanda, Sarga 31, Verse 33', 'पुरं च राष्ट्रं च मही च केवला मया निसृष्टा भरताय दीयताम्।
अहं निदेशं भवतोऽनुपालयन्वनं गमिष्यामि चिराय सेवितुम्॥', 'puraṃ ca rāṣṭraṃ ca mahī ca kevalā mayā nisṛṣṭā bharatāya dīyatām
ahaṃ nideśaṃ bhavato ''nupālayan vanaṃ gamiṣyāmi cirāya sevitum', null, 2031033),
('ramayana-2-31-34', 34, 'Ayodhya Kanda, Sarga 31, Verse 34', 'मया निसृष्टां भरतो महीमिमां सशैलखण्डां सपुरां सकाननाम्।
शिवां सुसीमामनुशास्तु केवलं त्वया यदुक्तं नृपते यथास्तु तत्॥', 'mayā nisṛṣṭāṃ bharato mahīm imāṃ saśailakhaṇḍāṃ sapurāṃ sakānanām
śivāṃ susīmām anuśāstu kevalaṃ tvayā yad uktaṃ nṛpate yathāstu tat', null, 2031034),
('ramayana-2-31-35', 35, 'Ayodhya Kanda, Sarga 31, Verse 35', 'न मे तथा पार्थिव धीयते मनो महत्सु कामेषु न चात्मनः प्रिये।
यथा निदेशे तव शिष्टसंमते व्यपैतु दुःखं तव मत्कृतेऽनघ॥', 'na me tathā pārthiva dhīyate mano mahatsu kāmeṣu na cātmanaḥ priye
yathā nideśe tava śiṣṭasaṃmate vyapaitu duḥkhaṃ tava matkṛte ''nagha', null, 2031035),
('ramayana-2-31-36', 36, 'Ayodhya Kanda, Sarga 31, Verse 36', 'तदद्य नैवानघ राज्यमव्ययं न सर्वकामान्न सुखं न मैथिलीम्।
न जीवितं त्वामनृतेन योजयन्वृणीय सत्यं व्रतमस्तु ते तथा॥', 'tad adya naivānagha rājyam avyayaṃ na sarvakāmān na sukhaṃ na maithilīm
na jīvitaṃ tvām anṛtena yojayan vṛṇīya satyaṃ vratam astu te tathā', null, 2031036),
('ramayana-2-31-37', 37, 'Ayodhya Kanda, Sarga 31, Verse 37', 'फलानि मूलानि च भक्षयन्वने गिरींश्च पश्यन्सरितः सरांसि च।
वनं प्रविश्यैव विचित्रपादपं सुखी भविष्यामि तवास्तु निर्वृतिः॥', 'phalāni mūlāni ca bhakṣayan vane girīṃś ca paśyan saritaḥ sarāṃsi ca
vanaṃ praviśyaiva vicitrapādapaṃ sukhī bhaviṣyāmi tavāstu nirvṛtiḥ', null, 2031037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 32 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-32-1', 1, 'Ayodhya Kanda, Sarga 32, Verse 1', 'ततः सुमन्त्रमैक्ष्वाकः पीडितोऽत्र प्रतिज्ञया।
सबाष्पमतिनिःश्वस्य जगादेदं पुनः पुनः॥', 'tataḥ sumantram aikṣvākaḥ pīḍito ''tra pratijñayā
sabāṣpam atiniḥśvasya jagādedaṃ punaḥ punaḥ', null, 2032001),
('ramayana-2-32-2', 2, 'Ayodhya Kanda, Sarga 32, Verse 2', 'सूत रत्नसुसंपूर्णा चतुर्विधबला चमूः।
रागवस्यानुयात्रार्थं क्षिप्रं प्रतिविधीयताम्॥', 'sūta ratnasusaṃpūrṇā caturvidhabalā camūḥ
rāgavasyānuyātrārthaṃ kṣipraṃ pratividhīyatām', null, 2032002),
('ramayana-2-32-3', 3, 'Ayodhya Kanda, Sarga 32, Verse 3', 'रूपाजीवा च शालिन्यो वणिजश्च महाधनाः।
शोभयन्तु कुमारस्य वाहिनीं सुप्रसारिताः॥', 'rūpājīvā ca śālinyo vaṇijaś ca mahādhanāḥ
śobhayantu kumārasya vāhinīṃ suprasāritāḥ', null, 2032003),
('ramayana-2-32-4', 4, 'Ayodhya Kanda, Sarga 32, Verse 4', 'ये चैनमुपजीवन्ति रमते यैश्च वीर्यतः।
तेषां बहुविधं दत्त्वा तानप्यत्र नियोजय॥', 'ye cainam upajīvanti ramate yaiś ca vīryataḥ
teṣāṃ bahuvidhaṃ dattvā tān apy atra niyojaya', null, 2032004),
('ramayana-2-32-5', 5, 'Ayodhya Kanda, Sarga 32, Verse 5', 'निघ्नन्मृगान्कुञ्जरांश्च पिबंश्चारण्यकं मधु।
नदीश्च विविधाः पश्यन्न राज्यं संस्मरिष्यति॥', 'nighnan mṛgān kuñjarāṃś ca pibaṃś cāraṇyakaṃ madhu
nadīś ca vividhāḥ paśyan na rājyaṃ saṃsmariṣyati', null, 2032005),
('ramayana-2-32-6', 6, 'Ayodhya Kanda, Sarga 32, Verse 6', 'धान्यकोशश्च यः कश्चिद्धनकोशश्च मामकः।
तौ राममनुगच्छेतां वसन्तं निर्जने वने॥', 'dhānyakośaś ca yaḥ kaś cid dhanakośaś ca māmakaḥ
tau rāmam anugacchetāṃ vasantaṃ nirjane vane', null, 2032006),
('ramayana-2-32-7', 7, 'Ayodhya Kanda, Sarga 32, Verse 7', 'यजन्पुण्येषु देशेषु विसृजंश्चाप्तदक्षिणाः।
ऋषिभिश्च समागम्य प्रवत्स्यति सुखं वने॥', 'yajan puṇyeṣu deśeṣu visṛjaṃś cāptadakṣiṇāḥ
ṛṣibhiś ca samāgamya pravatsyati sukhaṃ vane', null, 2032007),
('ramayana-2-32-8', 8, 'Ayodhya Kanda, Sarga 32, Verse 8', 'भरतश्च महाबाहुरयोध्यां पालयिष्यति।
सर्वकामैः पुनः श्रीमान्रामः संसाध्यतामिति॥', 'bharataś ca mahābāhur ayodhyāṃ pālayiṣyati
sarvakāmaiḥ punaḥ śrīmān rāmaḥ saṃsādhyatām iti', null, 2032008),
('ramayana-2-32-9', 9, 'Ayodhya Kanda, Sarga 32, Verse 9', 'एवं ब्रुवति काकुत्स्थे कैकेय्या भयमागतम्।
मुखं चाप्यगमाच्छोषं स्वरश्चापि न्यरुध्यत॥', 'evaṃ bruvati kākutsthe kaikeyyā bhayam āgatam
mukhaṃ cāpy agamāc choṣaṃ svaraś cāpi nyarudhyata', null, 2032009),
('ramayana-2-32-10', 10, 'Ayodhya Kanda, Sarga 32, Verse 10', 'सा विषण्णा च संत्रस्ता कैकेयी वाक्यमब्रवीत्।
राज्यं गतजनं साधो पीतमण्डां सुरामिव।
निरास्वाद्यतमं शून्यं भरतो नाभिपत्स्यते॥', 'sā viṣaṇṇā ca saṃtrastā kaikeyī vākyam abravīt
rājyaṃ gatajanaṃ sādho pītamaṇḍāṃ surām iva
nirāsvādyatamaṃ śūnyaṃ bharato nābhipatsyate', null, 2032010),
('ramayana-2-32-11', 11, 'Ayodhya Kanda, Sarga 32, Verse 11', 'कैकेय्यां मुक्तलज्जायां वदन्त्यामतिदारुणम्।
राजा दशरथो वाक्यमुवाचायतलोचनाम्।
वहन्तं किं तुदसि मां नियुज्य धुरि माहिते॥', 'kaikeyyāṃ muktalajjāyāṃ vadantyām atidāruṇam
rājā daśaratho vākyam uvācāyatalocanām
vahantaṃ kiṃ tudasi māṃ niyujya dhuri māhite', null, 2032011),
('ramayana-2-32-12', 12, 'Ayodhya Kanda, Sarga 32, Verse 12', 'कैकेयी द्विगुणं क्रुद्धा राजानमिदमब्रवीत्।
तवैव वंशे सगरो ज्येष्ठं पुत्रमुपारुधत्।
असमञ्ज इति ख्यातं तथायं गन्तुमर्हति॥', 'kaikeyī dviguṇaṃ kruddhā rājānam idam abravīt
tavaiva vaṃśe sagaro jyeṣṭhaṃ putram upārudhat
asamañja iti khyātaṃ tathāyaṃ gantum arhati', null, 2032012),
('ramayana-2-32-13', 13, 'Ayodhya Kanda, Sarga 32, Verse 13', 'एवमुक्तो धिगित्येव राजा दशरथोऽब्रवीत्।
व्रीडितश्च जनः सर्वः सा च तन्नावबुध्यत॥', 'evam ukto dhig ity eva rājā daśaratho ''bravīt
vrīḍitaś ca janaḥ sarvaḥ sā ca tan nāvabudhyata', null, 2032013),
('ramayana-2-32-14', 14, 'Ayodhya Kanda, Sarga 32, Verse 14', 'तत्र वृद्धो महामात्रः सिद्धार्थो नाम नामतः।
शुचिर्बहुमतो राज्ञः कैकेयीमिदमब्रवीत्॥', 'tatra vṛddho mahāmātraḥ siddhārtho nāma nāmataḥ
śucir bahumato rājñaḥ kaikeyīm idam abravīt', null, 2032014),
('ramayana-2-32-15', 15, 'Ayodhya Kanda, Sarga 32, Verse 15', 'असमञ्जो गृहीत्वा तु क्रीडितः पथि दारकान्।
सरय्वाः प्रक्षिपन्नप्सु रमते तेन दुर्मतिः॥', 'asamañjo gṛhītvā tu krīḍitaḥ pathi dārakān
sarayvāḥ prakṣipann apsu ramate tena durmatiḥ', null, 2032015),
('ramayana-2-32-16', 16, 'Ayodhya Kanda, Sarga 32, Verse 16', 'तं दृष्ट्वा नागरः सर्वे क्रुद्धा राजानमब्रुवन्।
असमञ्जं वृषीण्वैकमस्मान्वा राष्ट्रवर्धन॥', 'taṃ dṛṣṭvā nāgaraḥ sarve kruddhā rājānam abruvan
asamañjaṃ vṛṣīṇvaikam asmān vā rāṣṭravardhana', null, 2032016),
('ramayana-2-32-17', 17, 'Ayodhya Kanda, Sarga 32, Verse 17', 'तानुवाच ततो राजा किंनिमित्तमिदं भयम्।
ताश्चापि राज्ञा संपृष्टा वाक्यं प्रकृतयोऽब्रुवन्॥', 'tān uvāca tato rājā kiṃnimittam idaṃ bhayam
tāś cāpi rājñā saṃpṛṣṭā vākyaṃ prakṛtayo ''bruvan', null, 2032017),
('ramayana-2-32-18', 18, 'Ayodhya Kanda, Sarga 32, Verse 18', 'क्रीडितस्त्वेष नः पुत्रान्बालानुद्भ्रान्तचेतनः।
सरय्वां प्रक्षिपन्मौर्ख्यादतुलां प्रीतिमश्नुते॥', 'krīḍitas tv eṣa naḥ putrān bālān udbhrāntacetanaḥ
sarayvāṃ prakṣipan maurkhyād atulāṃ prītim aśnute', null, 2032018),
('ramayana-2-32-19', 19, 'Ayodhya Kanda, Sarga 32, Verse 19', 'स तासां वचनं श्रुत्वा प्रकृतीनां नराधिप।
तं तत्याजाहितं पुत्रं तासां प्रियचिकीर्षया॥', 'sa tāsāṃ vacanaṃ śrutvā prakṛtīnāṃ narādhipa
taṃ tatyājāhitaṃ putraṃ tāsāṃ priyacikīrṣayā', null, 2032019),
('ramayana-2-32-20', 20, 'Ayodhya Kanda, Sarga 32, Verse 20', 'इत्येवमत्यजद्राजा सगरो वै सुधार्मिकः।
रामः किमकरोत्पापं येनैवमुपरुध्यते॥', 'ity evam atyajad rājā sagaro vai sudhārmikaḥ
rāmaḥ kim akarot pāpaṃ yenaivam uparudhyate', null, 2032020),
('ramayana-2-32-21', 21, 'Ayodhya Kanda, Sarga 32, Verse 21', 'श्रुत्वा तु सिद्धार्थवचो राजा श्रान्ततरस्वनः।
शोकोपहतया वाचा कैकेयीमिदमब्रवीत्॥', 'śrutvā tu siddhārthavaco rājā śrāntatarasvanaḥ
śokopahatayā vācā kaikeyīm idam abravīt', null, 2032021),
('ramayana-2-32-22', 22, 'Ayodhya Kanda, Sarga 32, Verse 22', 'अनुव्रजिष्याम्यहमद्य रामं राज्यं परित्यज्य सुखं धनं च।
सहैव राज्ञा भरतेन च त्वं यथा सुखं भुङ्क्ष्व चिराय राज्यम्॥', 'anuvrajiṣyāmy aham adya rāmaṃ rājyaṃ parityajya sukhaṃ dhanaṃ ca
sahaiva rājñā bharatena ca tvaṃ yathā sukhaṃ bhuṅkṣva cirāya rājyam', null, 2032022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 33 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-33-1', 1, 'Ayodhya Kanda, Sarga 33, Verse 1', 'महामात्रवचः श्रुत्वा रामो दशरथं तदा।
अन्वभाषत वाक्यं तु विनयज्ञो विनीतवत्॥', 'mahāmātravacaḥ śrutvā rāmo daśarathaṃ tadā
anvabhāṣata vākyaṃ tu vinayajño vinītavat', null, 2033001),
('ramayana-2-33-2', 2, 'Ayodhya Kanda, Sarga 33, Verse 2', 'त्यक्तभोगस्य मे राजन्वने वन्येन जीवतः।
किं कार्यमनुयात्रेण त्यक्तसङ्गस्य सर्वतः॥', 'tyaktabhogasya me rājan vane vanyena jīvataḥ
kiṃ kāryam anuyātreṇa tyaktasaṅgasya sarvataḥ', null, 2033002),
('ramayana-2-33-3', 3, 'Ayodhya Kanda, Sarga 33, Verse 3', 'यो हि दत्त्वा द्विपश्रेष्ठं कक्ष्यायां कुरुते मनः।
रज्जुस्नेहेन किं तस्य त्यजतः कुञ्जरोत्तमम्॥', 'yo hi dattvā dvipaśreṣṭhaṃ kakṣyāyāṃ kurute manaḥ
rajjusnehena kiṃ tasya tyajataḥ kuñjarottamam', null, 2033003),
('ramayana-2-33-4', 4, 'Ayodhya Kanda, Sarga 33, Verse 4', 'तथा मम सतां श्रेष्ठ किं ध्वजिन्या जगत्पते।
सर्वाण्येवानुजानामि चीराण्येवानयन्तु मे॥', 'tathā mama satāṃ śreṣṭha kiṃ dhvajinyā jagatpate
sarvāṇy evānujānāmi cīrāṇy evānayantu me', null, 2033004),
('ramayana-2-33-5', 5, 'Ayodhya Kanda, Sarga 33, Verse 5', 'खनित्रपिटके चोभे ममानयत गच्छतः।
चतुर्दश वने वासं वर्षाणि वसतो मम॥', 'khanitrapiṭake cobhe mamānayata gacchataḥ
caturdaśa vane vāsaṃ varṣāṇi vasato mama', null, 2033005),
('ramayana-2-33-6', 6, 'Ayodhya Kanda, Sarga 33, Verse 6', 'अथ चीराणि कैकेयी स्वयमाहृत्य राघवम्।
उवाच परिधत्स्वेति जनौघे निरपत्रपा॥', 'atha cīrāṇi kaikeyī svayam āhṛtya rāghavam
uvāca paridhatsveti janaughe nirapatrapā', null, 2033006),
('ramayana-2-33-7', 7, 'Ayodhya Kanda, Sarga 33, Verse 7', 'स चीरे पुरुषव्याघ्रः कैकेय्याः प्रतिगृह्य ते।
सूक्ष्मवस्त्रमवक्षिप्य मुनिवस्त्राण्यवस्त ह॥', 'sa cīre puruṣavyāghraḥ kaikeyyāḥ pratigṛhya te
sūkṣmavastram avakṣipya munivastrāṇy avasta ha', null, 2033007),
('ramayana-2-33-8', 8, 'Ayodhya Kanda, Sarga 33, Verse 8', 'लक्ष्मणश्चापि तत्रैव विहाय वसने शुभे।
तापसाच्छादने चैव जग्राह पितुरग्रतः॥', 'lakṣmaṇaś cāpi tatraiva vihāya vasane śubhe
tāpasāc chādane caiva jagrāha pitur agrataḥ', null, 2033008),
('ramayana-2-33-9', 9, 'Ayodhya Kanda, Sarga 33, Verse 9', 'अथात्मपरिधानार्थं सीता कौशेयवासिनी।
समीक्ष्य चीरं संत्रस्ता पृषती वागुरामिव॥', 'athātmaparidhānārthaṃ sītā kauśeyavāsinī
samīkṣya cīraṃ saṃtrastā pṛṣatī vāgurām iva', null, 2033009),
('ramayana-2-33-10', 10, 'Ayodhya Kanda, Sarga 33, Verse 10', 'सा व्यपत्रपमाणेव प्रतिगृह्य च दुर्मनाः।
गन्धर्वराजप्रतिमं भर्तारमिदमब्रवीत्।
कथं नु चीरं बध्नन्ति मुनयो वनवासिनः॥', 'sā vyapatrapamāṇeva pratigṛhya ca durmanāḥ
gandharvarājapratimaṃ bhartāram idam abravīt
kathaṃ nu cīraṃ badhnanti munayo vanavāsinaḥ', null, 2033010),
('ramayana-2-33-11', 11, 'Ayodhya Kanda, Sarga 33, Verse 11', 'कृत्वा कण्ठे च सा चीरमेकमादाय पाणिना।
तस्थौ ह्यकुषला तत्र व्रीडिता जनकात्मज॥', 'kṛtvā kaṇṭhe ca sā cīram ekam ādāya pāṇinā
tasthau hy akuṣalā tatra vrīḍitā janakātmaja', null, 2033011),
('ramayana-2-33-12', 12, 'Ayodhya Kanda, Sarga 33, Verse 12', 'तस्यास्तत्क्षिप्रमागम्य रामो धर्मभृतां वरः।
चीरं बबन्ध सीतायाः कौशेयस्योपरि स्वयम्॥', 'tasyās tat kṣipram āgamya rāmo dharmabhṛtāṃ varaḥ
cīraṃ babandha sītāyāḥ kauśeyasyopari svayam', null, 2033012),
('ramayana-2-33-13', 13, 'Ayodhya Kanda, Sarga 33, Verse 13', 'तस्यां चीरं वसानायां नाथवत्यामनाथवत्।
प्रचुक्रोश जनः सर्वो धिक्त्वां दशरथं त्विति॥', 'tasyāṃ cīraṃ vasānāyāṃ nāthavatyām anāthavat
pracukrośa janaḥ sarvo dhik tvāṃ daśarathaṃ tv iti', null, 2033013),
('ramayana-2-33-14', 14, 'Ayodhya Kanda, Sarga 33, Verse 14', 'स निःश्वस्योष्णमैक्ष्वाकस्तां भार्यामिदमब्रवीत्।
कैकेयि कुशचीरेण न सीता गन्तुमर्हति॥', 'sa niḥśvasyoṣṇam aikṣvākas tāṃ bhāryām idam abravīt
kaikeyi kuśacīreṇa na sītā gantum arhati', null, 2033014),
('ramayana-2-33-15', 15, 'Ayodhya Kanda, Sarga 33, Verse 15', 'ननु पर्याप्तमेतत्ते पापे रामविवासनम्।
किमेभिः कृपणैर्भूयः पातकैरपि ते कृतैः॥', 'nanu paryāptam etat te pāpe rāmavivāsanam
kim ebhiḥ kṛpaṇair bhūyaḥ pātakair api te kṛtaiḥ', null, 2033015),
('ramayana-2-33-16', 16, 'Ayodhya Kanda, Sarga 33, Verse 16', 'एवं ब्रुवन्तं पितरं रामः संप्रस्थितो वनम्।
अवाक्शिरसमासीनमिदं वचनमब्रवीत्॥', 'evaṃ bruvantaṃ pitaraṃ rāmaḥ saṃprasthito vanam
avākśirasam āsīnam idaṃ vacanam abravīt', null, 2033016),
('ramayana-2-33-17', 17, 'Ayodhya Kanda, Sarga 33, Verse 17', 'इयं धार्मिक कौसल्या मम माता यशस्विनी।
वृद्धा चाक्षुद्रशीला च न च त्वां देवगर्हिते॥', 'iyaṃ dhārmika kausalyā mama mātā yaśasvinī
vṛddhā cākṣudraśīlā ca na ca tvāṃ devagarhite', null, 2033017),
('ramayana-2-33-18', 18, 'Ayodhya Kanda, Sarga 33, Verse 18', 'मया विहीनां वरद प्रपन्नां शोकसागरम्।
अदृष्टपूर्वव्यसनां भूयः संमन्तुमर्हसि॥', 'mayā vihīnāṃ varada prapannāṃ śokasāgaram
adṛṣṭapūrvavyasanāṃ bhūyaḥ saṃmantum arhasi', null, 2033018),
('ramayana-2-33-19', 19, 'Ayodhya Kanda, Sarga 33, Verse 19', 'इमां महेन्द्रोपमजातगर्भिणीं तथा विधातुं जनमीं ममार्हसि।
यथा वनस्थे मयि शोककर्शिता न जीवितं न्यस्य यमक्षयं व्रजेत्॥', 'imāṃ mahendropamajātagarbhiṇīṃ tathā vidhātuṃ janamīṃ mamārhasi
yathā vanasthe mayi śokakarśitā na jīvitaṃ nyasya yamakṣayaṃ vrajet', null, 2033019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 34 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-34-1', 1, 'Ayodhya Kanda, Sarga 34, Verse 1', 'रामस्य तु वचः श्रुत्वा मुनिवेषधरं च तम्।
समीक्ष्य सह भार्याभी राजा विगतचेतनः॥', 'rāmasya tu vacaḥ śrutvā muniveṣadharaṃ ca tam
samīkṣya saha bhāryābhī rājā vigatacetanaḥ', null, 2034001),
('ramayana-2-34-2', 2, 'Ayodhya Kanda, Sarga 34, Verse 2', 'नैनं दुःखेन संतप्तः प्रत्यवैक्षत राघवम्।
न चैनमभिसंप्रेक्ष्य प्रत्यभाषत दुर्मनाः॥', 'nainaṃ duḥkhena saṃtaptaḥ pratyavaikṣata rāghavam
na cainam abhisaṃprekṣya pratyabhāṣata durmanāḥ', null, 2034002),
('ramayana-2-34-3', 3, 'Ayodhya Kanda, Sarga 34, Verse 3', 'स मुहूर्तमिवासंज्ञो दुःखितश्च महीपतिः।
विललाप महाबाहू राममेवानुचिन्तयन्॥', 'sa muhūrtam ivāsaṃjño duḥkhitaś ca mahīpatiḥ
vilalāpa mahābāhū rāmam evānucintayan', null, 2034003),
('ramayana-2-34-4', 4, 'Ayodhya Kanda, Sarga 34, Verse 4', 'मन्ये खलु मया पूर्वं विवत्सा बहवः कृताः।
प्राणिनो हिंसिता वापि तस्मादिदमुपस्थितम्॥', 'manye khalu mayā pūrvaṃ vivatsā bahavaḥ kṛtāḥ
prāṇino hiṃsitā vāpi tasmād idam upasthitam', null, 2034004),
('ramayana-2-34-5', 5, 'Ayodhya Kanda, Sarga 34, Verse 5', 'न त्वेवानागते काले देहाच्च्यवति जीवितम्।
कैकेय्या क्लिश्यमानस्य मृत्युर्मम न विद्यते॥', 'na tv evānāgate kāle dehāc cyavati jīvitam
kaikeyyā kliśyamānasya mṛtyur mama na vidyate', null, 2034005),
('ramayana-2-34-6', 6, 'Ayodhya Kanda, Sarga 34, Verse 6', 'योऽहं पावकसंकाशं पश्यामि पुरतः स्थितम्।
विहाय वसने सूक्ष्मे तापसाच्छादमात्मजम्॥', 'yo ''haṃ pāvakasaṃkāśaṃ paśyāmi purataḥ sthitam
vihāya vasane sūkṣme tāpasācchādam ātmajam', null, 2034006),
('ramayana-2-34-7', 7, 'Ayodhya Kanda, Sarga 34, Verse 7', 'एकस्याः खलु कैकेय्याः कृतेऽयं क्लिश्यते जनः।
स्वार्थे प्रयतमानायाः संश्रित्य निकृतिं त्विमाम्॥', 'ekasyāḥ khalu kaikeyyāḥ kṛte ''yaṃ kliśyate janaḥ
svārthe prayatamānāyāḥ saṃśritya nikṛtiṃ tv imām', null, 2034007),
('ramayana-2-34-8', 8, 'Ayodhya Kanda, Sarga 34, Verse 8', 'एवमुक्त्वा तु वचनं बाष्पेण पिहितेक्ष्णह।
रामेति सकृदेवोक्त्वा व्याहर्तुं न शशाक ह॥', 'evam uktvā tu vacanaṃ bāṣpeṇa pihitekṣṇaha
rāmeti sakṛd evoktvā vyāhartuṃ na śaśāka ha', null, 2034008),
('ramayana-2-34-9', 9, 'Ayodhya Kanda, Sarga 34, Verse 9', 'संज्ञां तु प्रतिलभ्यैव मुहूर्तात्स महीपतिः।
नेत्राभ्यामश्रुपूर्णाभ्यां सुमन्त्रमिदमब्रवीत्॥', 'saṃjñāṃ tu pratilabhyaiva muhūrtāt sa mahīpatiḥ
netrābhyām aśrupūrṇābhyāṃ sumantram idam abravīt', null, 2034009),
('ramayana-2-34-10', 10, 'Ayodhya Kanda, Sarga 34, Verse 10', 'औपवाह्यं रथं युक्त्वा त्वमायाहि हयोत्तमैः।
प्रापयैनं महाभागमितो जनपदात्परम्॥', 'aupavāhyaṃ rathaṃ yuktvā tvam āyāhi hayottamaiḥ
prāpayainaṃ mahābhāgam ito janapadāt param', null, 2034010),
('ramayana-2-34-11', 11, 'Ayodhya Kanda, Sarga 34, Verse 11', 'एवं मन्ये गुणवतां गुणानां फलमुच्यते।
पित्रा मात्रा च यत्साधुर्वीरो निर्वास्यते वनम्॥', 'evaṃ manye guṇavatāṃ guṇānāṃ phalam ucyate
pitrā mātrā ca yat sādhur vīro nirvāsyate vanam', null, 2034011),
('ramayana-2-34-12', 12, 'Ayodhya Kanda, Sarga 34, Verse 12', 'राज्ञो वचनमाज्ञाय सुमन्त्रः शीघ्रविक्रमः।
योजयित्वाययौ तत्र रथमश्वैरलंकृतम्॥', 'rājño vacanam ājñāya sumantraḥ śīghravikramaḥ
yojayitvāyayau tatra ratham aśvair alaṃkṛtam', null, 2034012),
('ramayana-2-34-13', 13, 'Ayodhya Kanda, Sarga 34, Verse 13', 'तं रथं राजपुत्राय सूतः कनकभूषितम्।
आचचक्षेऽञ्जलिं कृत्वा युक्तं परमवाजिभिः॥', 'taṃ rathaṃ rājaputrāya sūtaḥ kanakabhūṣitam
ācacakṣe ''ñjaliṃ kṛtvā yuktaṃ paramavājibhiḥ', null, 2034013),
('ramayana-2-34-14', 14, 'Ayodhya Kanda, Sarga 34, Verse 14', 'राजा सत्वरमाहूय व्यापृतं वित्तसंचये।
उवाच देशकालज्ञो निश्चितं सर्वतः शुचि॥', 'rājā satvaram āhūya vyāpṛtaṃ vittasaṃcaye
uvāca deśakālajño niścitaṃ sarvataḥ śuci', null, 2034014),
('ramayana-2-34-15', 15, 'Ayodhya Kanda, Sarga 34, Verse 15', 'वासांसि च महार्हाणि भूषणानि वराणि च।
वर्षाण्येतानि संख्याय वैदेह्याः क्षिप्रमानय॥', 'vāsāṃsi ca mahārhāṇi bhūṣaṇāni varāṇi ca
varṣāṇy etāni saṃkhyāya vaidehyāḥ kṣipram ānaya', null, 2034015),
('ramayana-2-34-16', 16, 'Ayodhya Kanda, Sarga 34, Verse 16', 'नरेन्द्रेणैवमुक्तस्तु गत्वा कोशगृहं ततः।
प्रायच्छत्सर्वमाहृत्य सीतायै क्षिप्रमेव तत्॥', 'narendreṇaivam uktas tu gatvā kośagṛhaṃ tataḥ
prāyacchat sarvam āhṛtya sītāyai kṣipram eva tat', null, 2034016),
('ramayana-2-34-17', 17, 'Ayodhya Kanda, Sarga 34, Verse 17', 'सा सुजाता सुजातानि वैदेही प्रस्थिता वनम्।
भूषयामास गात्राणि तैर्विचित्रैर्विभूषणैः॥', 'sā sujātā sujātāni vaidehī prasthitā vanam
bhūṣayām āsa gātrāṇi tair vicitrair vibhūṣaṇaiḥ', null, 2034017),
('ramayana-2-34-18', 18, 'Ayodhya Kanda, Sarga 34, Verse 18', 'व्यराजयत वैदेही वेश्म तत्सुविभूषिता।
उद्यतोऽंशुमतः काले खं प्रभेव विवस्वतः॥', 'vyarājayata vaidehī veśma tat suvibhūṣitā
udyato ''ṃśumataḥ kāle khaṃ prabheva vivasvataḥ', null, 2034018),
('ramayana-2-34-19', 19, 'Ayodhya Kanda, Sarga 34, Verse 19', 'तां भुजाभ्यां परिष्वज्य श्वश्रूर्वचनमब्रवीत्।
अनाचरन्तीं कृपणं मूध्न्युपाघ्राय मैथिलीम्॥', 'tāṃ bhujābhyāṃ pariṣvajya śvaśrūr vacanam abravīt
anācarantīṃ kṛpaṇaṃ mūdhny upāghrāya maithilīm', null, 2034019),
('ramayana-2-34-20', 20, 'Ayodhya Kanda, Sarga 34, Verse 20', 'असत्यः सर्वलोकेऽस्मिन्सततं सत्कृताः प्रियैः।
भर्तारं नानुमन्यन्ते विनिपातगतं स्त्रियः॥', 'asatyaḥ sarvaloke ''smin satataṃ satkṛtāḥ priyaiḥ
bhartāraṃ nānumanyante vinipātagataṃ striyaḥ', null, 2034020),
('ramayana-2-34-21', 21, 'Ayodhya Kanda, Sarga 34, Verse 21', 'स त्वया नावमन्तव्यः पुत्रः प्रव्राजितो मम।
तव दैवतमस्त्वेष निर्धनः सधनोऽपि वा॥', 'sa tvayā nāvamantavyaḥ putraḥ pravrājito mama
tava daivatam astv eṣa nirdhanaḥ sadhano ''pi vā', null, 2034021),
('ramayana-2-34-22', 22, 'Ayodhya Kanda, Sarga 34, Verse 22', 'विज्ञाय वचनं सीता तस्या धर्मार्थसंहितम्।
कृताञ्जलिरुवाचेदं श्वश्रूमभिमुखे स्थिता॥', 'vijñāya vacanaṃ sītā tasyā dharmārthasaṃhitam
kṛtāñjalir uvācedaṃ śvaśrūm abhimukhe sthitā', null, 2034022),
('ramayana-2-34-23', 23, 'Ayodhya Kanda, Sarga 34, Verse 23', 'करिष्ये सर्वमेवाहमार्या यदनुशास्ति माम्।
अभिज्ञास्मि यथा भर्तुर्वर्तितव्यं श्रुतं च मे॥', 'kariṣye sarvam evāham āryā yad anuśāsti mām
abhijñāsmi yathā bhartur vartitavyaṃ śrutaṃ ca me', null, 2034023),
('ramayana-2-34-24', 24, 'Ayodhya Kanda, Sarga 34, Verse 24', 'न मामसज्जनेनार्या समानयितुमर्हति।
धर्माद्विचलितुं नाहमलं चन्द्रादिव प्रभा॥', 'na mām asajjanenāryā samānayitum arhati
dharmād vicalituṃ nāham alaṃ candrād iva prabhā', null, 2034024),
('ramayana-2-34-25', 25, 'Ayodhya Kanda, Sarga 34, Verse 25', 'नातन्त्री वाद्यते वीणा नाचक्रो वर्तते रथः।
नापतिः सुखमेधते या स्यादपि शतात्मजा॥', 'nātantrī vādyate vīṇā nācakro vartate rathaḥ
nāpatiḥ sukham edhate yā syād api śatātmajā', null, 2034025),
('ramayana-2-34-26', 26, 'Ayodhya Kanda, Sarga 34, Verse 26', 'मितं ददाति हि पिता मितं माता मितं सुतः।
अमितस्य हि दातारं भर्तारं का न पूजयेत्॥', 'mitaṃ dadāti hi pitā mitaṃ mātā mitaṃ sutaḥ
amitasya hi dātāraṃ bhartāraṃ kā na pūjayet', null, 2034026),
('ramayana-2-34-27', 27, 'Ayodhya Kanda, Sarga 34, Verse 27', 'साहमेवंगता श्रेष्ठा श्रुतधर्मपरावरा।
आर्ये किमवमन्येयं स्त्रीणां भर्ता हि दैवतम्॥', 'sāham evaṃgatā śreṣṭhā śrutadharmaparāvarā
ārye kim avamanyeyaṃ strīṇāṃ bhartā hi daivatam', null, 2034027),
('ramayana-2-34-28', 28, 'Ayodhya Kanda, Sarga 34, Verse 28', 'सीताया वचनं श्रुत्वा कौसल्या हृदयंगमम्।
शुद्धसत्त्वा मुमोचाश्रु सहसा दुःखहर्षजम्॥', 'sītāyā vacanaṃ śrutvā kausalyā hṛdayaṃgamam
śuddhasattvā mumocāśru sahasā duḥkhaharṣajam', null, 2034028),
('ramayana-2-34-29', 29, 'Ayodhya Kanda, Sarga 34, Verse 29', 'तां प्राञ्जलिरभिक्रम्य मातृमध्येऽतिसत्कृताम्।
रामः परमधर्मज्ञो मातरं वाक्यमब्रवीत्॥', 'tāṃ prāñjalir abhikramya mātṛmadhye ''tisatkṛtām
rāmaḥ paramadharmajño mātaraṃ vākyam abravīt', null, 2034029),
('ramayana-2-34-30', 30, 'Ayodhya Kanda, Sarga 34, Verse 30', 'अम्ब मा दुःखिता भूस्त्वं पश्य त्वं पितरं मम।
क्षयो हि वनवासस्य क्षिप्रमेव भविष्यति॥', 'amba mā duḥkhitā bhūs tvaṃ paśya tvaṃ pitaraṃ mama
kṣayo hi vanavāsasya kṣipram eva bhaviṣyati', null, 2034030),
('ramayana-2-34-31', 31, 'Ayodhya Kanda, Sarga 34, Verse 31', 'सुप्तायास्ते गमिष्यन्ति नववर्षाणि पञ्च च।
सा समग्रमिह प्राप्तं मां द्रक्ष्यसि सुहृद्वृतम्॥', 'suptāyās te gamiṣyanti navavarṣāṇi pañca ca
sā samagram iha prāptaṃ māṃ drakṣyasi suhṛdvṛtam', null, 2034031),
('ramayana-2-34-32', 32, 'Ayodhya Kanda, Sarga 34, Verse 32', 'एतावदभिनीतार्थमुक्त्वा स जननीं वचः।
त्रयः शतशतार्धा हि ददर्शावेक्ष्य मातरः॥', 'etāvad abhinītārtham uktvā sa jananīṃ vacaḥ
trayaḥ śataśatārdhā hi dadarśāvekṣya mātaraḥ', null, 2034032),
('ramayana-2-34-33', 33, 'Ayodhya Kanda, Sarga 34, Verse 33', 'ताश्चापि स तथैवार्ता मातॄर्दशरथात्मजः।
धर्मयुक्तमिदं वाक्यं निजगाद कृताञ्जलिः॥', 'tāś cāpi sa tathaivārtā mātṝr daśarathātmajaḥ
dharmayuktam idaṃ vākyaṃ nijagāda kṛtāñjaliḥ', null, 2034033),
('ramayana-2-34-34', 34, 'Ayodhya Kanda, Sarga 34, Verse 34', 'संवासात्परुषं किं चिदज्ञानाद्वापि यत्कृतम्।
तन्मे समनुजानीत सर्वाश्चामन्त्रयामि वः॥', 'saṃvāsāt paruṣaṃ kiṃ cid ajñānād vāpi yat kṛtam
tan me samanujānīta sarvāś cāmantrayāmi vaḥ', null, 2034034),
('ramayana-2-34-35', 35, 'Ayodhya Kanda, Sarga 34, Verse 35', 'जज्ञेऽथ तासां संनादः क्रौञ्चीनामिव निःस्वनः।
मानवेन्द्रस्य भार्याणामेवं वदति राघवे॥', 'jajñe ''tha tāsāṃ saṃnādaḥ krauñcīnām iva niḥsvanaḥ
mānavendrasya bhāryāṇām evaṃ vadati rāghave', null, 2034035),
('ramayana-2-34-36', 36, 'Ayodhya Kanda, Sarga 34, Verse 36', 'मुरजपणवमेघघोषवद्दशरथवेश्म बभूव यत्पुरा।
विलपित परिदेवनाकुलं व्यसनगतं तदभूत्सुदुःखितम्॥', 'murajapaṇavameghaghoṣavad daśarathaveśma babhūva yat purā
vilapita paridevanākulaṃ vyasanagataṃ tad abhūt suduḥkhitam', null, 2034036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 35 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-35-1', 1, 'Ayodhya Kanda, Sarga 35, Verse 1', 'अथ रामश्च सीता च लक्ष्मणश्च कृताञ्जलिः।
उपसंगृह्य राजानं चक्रुर्दीनाः प्रदक्षिणम्॥', 'atha rāmaś ca sītā ca lakṣmaṇaś ca kṛtāñjaliḥ
upasaṃgṛhya rājānaṃ cakrur dīnāḥ pradakṣiṇam', null, 2035001),
('ramayana-2-35-2', 2, 'Ayodhya Kanda, Sarga 35, Verse 2', 'तं चापि समनुज्ञाप्य धर्मज्ञः सीतया सह।
राघवः शोकसंमूढो जननीमभ्यवादयत्॥', 'taṃ cāpi samanujñāpya dharmajñaḥ sītayā saha
rāghavaḥ śokasaṃmūḍho jananīm abhyavādayat', null, 2035002),
('ramayana-2-35-3', 3, 'Ayodhya Kanda, Sarga 35, Verse 3', 'अन्वक्षं लक्ष्मणो भ्रातुः कौसल्यामभ्यवादयत्।
अथ मातुः सुमित्राया जग्राह चरणौ पुनः॥', 'anvakṣaṃ lakṣmaṇo bhrātuḥ kausalyām abhyavādayat
atha mātuḥ sumitrāyā jagrāha caraṇau punaḥ', null, 2035003),
('ramayana-2-35-4', 4, 'Ayodhya Kanda, Sarga 35, Verse 4', 'तं वन्दमानं रुदती माता सौमित्रिमब्रवीत्।
हितकामा महाबाहुं मूर्ध्न्युपाघ्राय लक्ष्मणम्॥', 'taṃ vandamānaṃ rudatī mātā saumitrim abravīt
hitakāmā mahābāhuṃ mūrdhny upāghrāya lakṣmaṇam', null, 2035004),
('ramayana-2-35-5', 5, 'Ayodhya Kanda, Sarga 35, Verse 5', 'सृष्टस्त्वं वनवासाय स्वनुरक्तः सुहृज्जने।
रामे प्रमादं मा कार्षीः पुत्र भ्रातरि गच्छति॥', 'sṛṣṭas tvaṃ vanavāsāya svanuraktaḥ suhṛjjane
rāme pramādaṃ mā kārṣīḥ putra bhrātari gacchati', null, 2035005),
('ramayana-2-35-6', 6, 'Ayodhya Kanda, Sarga 35, Verse 6', 'व्यसनी वा समृद्धो वा गतिरेष तवानघ।
एष लोके सतां धर्मो यज्ज्येष्ठवशगो भवेत्॥', 'vyasanī vā samṛddho vā gatir eṣa tavānagha
eṣa loke satāṃ dharmo yaj jyeṣṭhavaśago bhavet', null, 2035006),
('ramayana-2-35-7', 7, 'Ayodhya Kanda, Sarga 35, Verse 7', 'इदं हि वृत्तमुचितं कुलस्यास्य सनातनम्।
दानं दीक्षा च यज्ञेषु तनुत्यागो मृधेषु च॥', 'idaṃ hi vṛttam ucitaṃ kulasyāsya sanātanam
dānaṃ dīkṣā ca yajñeṣu tanutyāgo mṛdheṣu ca', null, 2035007),
('ramayana-2-35-8', 8, 'Ayodhya Kanda, Sarga 35, Verse 8', 'रामं दशरथं विद्धि मां विद्धि जनकात्मजाम्।
अयोध्यामटवीं विद्धि गच्छ तात यथासुखम्॥', 'rāmaṃ daśarathaṃ viddhi māṃ viddhi janakātmajām
ayodhyām aṭavīṃ viddhi gaccha tāta yathāsukham', null, 2035008),
('ramayana-2-35-9', 9, 'Ayodhya Kanda, Sarga 35, Verse 9', 'ततः सुमन्त्रः काकुत्स्थं प्राञ्जलिर्वाक्यमब्रवीत्।
विनीतो विनयज्ञश्च मातलिर्वासवं यथा॥', 'tataḥ sumantraḥ kākutsthaṃ prāñjalir vākyam abravīt
vinīto vinayajñaś ca mātalir vāsavaṃ yathā', null, 2035009),
('ramayana-2-35-10', 10, 'Ayodhya Kanda, Sarga 35, Verse 10', 'रथमारोह भद्रं ते राजपुत्र महायशः।
क्षिप्रं त्वां प्रापयिष्यामि यत्र मां राम वक्ष्यसि॥', 'ratham āroha bhadraṃ te rājaputra mahāyaśaḥ
kṣipraṃ tvāṃ prāpayiṣyāmi yatra māṃ rāma vakṣyasi', null, 2035010),
('ramayana-2-35-11', 11, 'Ayodhya Kanda, Sarga 35, Verse 11', 'चतुर्दश हि वर्षाणि वस्तव्यानि वने त्वया।
तान्युपक्रमितव्यानि यानि देव्यासि चोदितः॥', 'caturdaśa hi varṣāṇi vastavyāni vane tvayā
tāny upakramitavyāni yāni devyāsi coditaḥ', null, 2035011),
('ramayana-2-35-12', 12, 'Ayodhya Kanda, Sarga 35, Verse 12', 'तं रथं सूर्यसंकाशं सीता हृष्टेन चेतसा।
आरुरोह वरारोहा कृत्वालंकारमात्मनः॥', 'taṃ rathaṃ sūryasaṃkāśaṃ sītā hṛṣṭena cetasā
āruroha varārohā kṛtvālaṃkāram ātmanaḥ', null, 2035012),
('ramayana-2-35-13', 13, 'Ayodhya Kanda, Sarga 35, Verse 13', 'तथैवायुधजातानि भ्रातृभ्यां कवचानि च।
रथोपस्थे प्रतिन्यस्य सचर्मकठिनं च तत्॥', 'tathaivāyudhajātāni bhrātṛbhyāṃ kavacāni ca
rathopasthe pratinyasya sacarmakaṭhinaṃ ca tat', null, 2035013),
('ramayana-2-35-14', 14, 'Ayodhya Kanda, Sarga 35, Verse 14', 'सीतातृतीयानारूढान्दृष्ट्वा धृष्टमचोदयत्।
सुमन्त्रः संमतानश्वान्वायुवेगसमाञ्जवे॥', 'sītātṛtīyān ārūḍhān dṛṣṭvā dhṛṣṭam acodayat
sumantraḥ saṃmatān aśvān vāyuvegasamāñ jave', null, 2035014),
('ramayana-2-35-15', 15, 'Ayodhya Kanda, Sarga 35, Verse 15', 'प्रयाते तु महारण्यं चिररात्राय राघवे।
बभूव नगरे मूर्च्छा बलमूर्च्छा जनस्य च॥', 'prayāte tu mahāraṇyaṃ cirarātrāya rāghave
babhūva nagare mūrcchā balamūrcchā janasya ca', null, 2035015),
('ramayana-2-35-16', 16, 'Ayodhya Kanda, Sarga 35, Verse 16', 'तत्समाकुलसंभ्रान्तं मत्तसंकुपित द्विपम्।
हयशिञ्जितनिर्घोषं पुरमासीन्महास्वनम्॥', 'tat samākulasaṃbhrāntaṃ mattasaṃkupita dvipam
hayaśiñjitanirghoṣaṃ puram āsīn mahāsvanam', null, 2035016),
('ramayana-2-35-17', 17, 'Ayodhya Kanda, Sarga 35, Verse 17', 'ततः सबालवृद्धा सा पुरी परमपीडिता।
राममेवाभिदुद्राव घर्मार्तः सलिलं यथा॥', 'tataḥ sabālavṛddhā sā purī paramapīḍitā
rāmam evābhidudrāva gharmārtaḥ salilaṃ yathā', null, 2035017),
('ramayana-2-35-18', 18, 'Ayodhya Kanda, Sarga 35, Verse 18', 'पार्श्वतः पृष्ठतश्चापि लम्बमानास्तदुन्मुखाः।
बाष्पपूर्णमुखाः सर्वे तमूचुर्भृशदुःखिताः॥', 'pārśvataḥ pṛṣṭhataś cāpi lambamānās tadunmukhāḥ
bāṣpapūrṇamukhāḥ sarve tam ūcur bhṛśaduḥkhitāḥ', null, 2035018),
('ramayana-2-35-19', 19, 'Ayodhya Kanda, Sarga 35, Verse 19', 'संयच्छ वाजिनां रश्मीन्सूत याहि शनैः शनैः।
मुखं द्रक्ष्यामि रामस्य दुर्दर्शं नो भविष्यति॥', 'saṃyaccha vājināṃ raśmīn sūta yāhi śanaiḥ śanaiḥ
mukhaṃ drakṣyāmi rāmasya durdarśaṃ no bhaviṣyati', null, 2035019),
('ramayana-2-35-20', 20, 'Ayodhya Kanda, Sarga 35, Verse 20', 'आयसं हृदयं नूनं राममातुरसंशयम्।
यद्देवगर्भप्रतिमे वनं याति न भिद्यते॥', 'āyasaṃ hṛdayaṃ nūnaṃ rāmamātur asaṃśayam
yad devagarbhapratime vanaṃ yāti na bhidyate', null, 2035020),
('ramayana-2-35-21', 21, 'Ayodhya Kanda, Sarga 35, Verse 21', 'कृतकृत्या हि वैदेही छायेवानुगता पतिम्।
न जहाति रता धर्मे मेरुमर्कप्रभा यथा॥', 'kṛtakṛtyā hi vaidehī chāyevānugatā patim
na jahāti ratā dharme merum arkaprabhā yathā', null, 2035021),
('ramayana-2-35-22', 22, 'Ayodhya Kanda, Sarga 35, Verse 22', 'अहो लक्ष्मण सिद्धार्थः सततां प्रियवादिनम्।
भ्रातरं देवसंकाशं यस्त्वं परिचरिष्यसि॥', 'aho lakṣmaṇa siddhārthaḥ satatāṃ priyavādinam
bhrātaraṃ devasaṃkāśaṃ yas tvaṃ paricariṣyasi', null, 2035022),
('ramayana-2-35-23', 23, 'Ayodhya Kanda, Sarga 35, Verse 23', 'महत्येषा हि ते सिद्धिरेष चाभ्युदयो महान्।
एष स्वर्गस्य मार्गश्च यदेनमनुगच्छसि।
एवं वदन्तस्ते सोढुं न शेकुर्बाष्पमागतम्॥', 'mahaty eṣā hi te siddhir eṣa cābhyudayo mahān
eṣa svargasya mārgaś ca yad enam anugacchasi
evaṃ vadantas te soḍhuṃ na śekur bāṣpam āgatam', null, 2035023),
('ramayana-2-35-24', 24, 'Ayodhya Kanda, Sarga 35, Verse 24', 'अथ राजा वृतः स्त्रीभिर्दीनाभिर्दीनचेतनः।
निर्जगाम प्रियं पुत्रं द्रक्ष्यामीति ब्रुवन्गृहात्॥', 'atha rājā vṛtaḥ strībhir dīnābhir dīnacetanaḥ
nirjagāma priyaṃ putraṃ drakṣyāmīti bruvan gṛhāt', null, 2035024),
('ramayana-2-35-25', 25, 'Ayodhya Kanda, Sarga 35, Verse 25', 'शुश्रुवे चाग्रतः स्त्रीणां रुदन्तीनां महास्वनः।
यथा नादः करेणूनां बद्धे महति कुञ्जरे॥', 'śuśruve cāgrataḥ strīṇāṃ rudantīnāṃ mahāsvanaḥ
yathā nādaḥ kareṇūnāṃ baddhe mahati kuñjare', null, 2035025),
('ramayana-2-35-26', 26, 'Ayodhya Kanda, Sarga 35, Verse 26', 'पिता च राजा काकुत्स्थः श्रीमान्सन्नस्तदा बभौ।
परिपूर्णः शशी काले ग्रहेणोपप्लुतो यथा॥', 'pitā ca rājā kākutsthaḥ śrīmān sannas tadā babhau
paripūrṇaḥ śaśī kāle graheṇopapluto yathā', null, 2035026),
('ramayana-2-35-27', 27, 'Ayodhya Kanda, Sarga 35, Verse 27', 'ततो हलहलाशब्दो जज्ञे रामस्य पृष्ठतः।
नराणां प्रेक्ष्य राजानं सीदन्तं भृशदुःखितम्॥', 'tato halahalāśabdo jajñe rāmasya pṛṣṭhataḥ
narāṇāṃ prekṣya rājānaṃ sīdantaṃ bhṛśaduḥkhitam', null, 2035027),
('ramayana-2-35-28', 28, 'Ayodhya Kanda, Sarga 35, Verse 28', 'हा रामेति जनाः के चिद्राममातेति चापरे।
अन्तःपुरं समृद्धं च क्रोशन्तं पर्यदेवयन्॥', 'hā rāmeti janāḥ ke cid rāmamāteti cāpare
antaḥpuraṃ samṛddhaṃ ca krośantaṃ paryadevayan', null, 2035028),
('ramayana-2-35-29', 29, 'Ayodhya Kanda, Sarga 35, Verse 29', 'अन्वीक्षमाणो रामस्तु विषण्णं भ्रान्तचेतसं।
राजानं मातरं चैव ददर्शानुगतौ पथि।
धर्मपाशेन संक्षिप्तः प्रकाशं नाभ्युदैक्षत॥', 'anvīkṣamāṇo rāmas tu viṣaṇṇaṃ bhrāntacetasaṃ
rājānaṃ mātaraṃ caiva dadarśānugatau pathi
dharmapāśena saṃkṣiptaḥ prakāśaṃ nābhyudaikṣata', null, 2035029),
('ramayana-2-35-30', 30, 'Ayodhya Kanda, Sarga 35, Verse 30', 'पदातिनौ च यानार्हावदुःखार्हौ सुखोचितौ।
दृष्ट्वा संचोदयामास शीघ्रं याहीति सारथिम्॥', 'padātinau ca yānārhāv aduḥkhārhau sukhocitau
dṛṣṭvā saṃcodayām āsa śīghraṃ yāhīti sārathim', null, 2035030),
('ramayana-2-35-31', 31, 'Ayodhya Kanda, Sarga 35, Verse 31', 'न हि तत्पुरुषव्याघ्रो दुःखदं दर्शनं पितुः।
मातुश्च सहितुं शक्तस्तोत्रार्दित इव द्विपः॥', 'na hi tat puruṣavyāghro duḥkhadaṃ darśanaṃ pituḥ
mātuś ca sahituṃ śaktas totrārdita iva dvipaḥ', null, 2035031),
('ramayana-2-35-32', 32, 'Ayodhya Kanda, Sarga 35, Verse 32', 'तथा रुदन्तीं कौसल्यां रथं तमनुधावतीम्।
क्रोशन्तीं राम रामेति हा सीते लक्ष्मणेति च।
असकृत्प्रैक्षत तदा नृत्यन्तीमिव मातरम्॥', 'tathā rudantīṃ kausalyāṃ rathaṃ tam anudhāvatīm
krośantīṃ rāma rāmeti hā sīte lakṣmaṇeti ca
asakṛt praikṣata tadā nṛtyantīm iva mātaram', null, 2035032),
('ramayana-2-35-33', 33, 'Ayodhya Kanda, Sarga 35, Verse 33', 'तिष्ठेति राजा चुक्रोष याहि याहीति राघवः।
सुमन्त्रस्य बभूवात्मा चक्रयोरिव चान्तरा॥', 'tiṣṭheti rājā cukroṣa yāhi yāhīti rāghavaḥ
sumantrasya babhūvātmā cakrayor iva cāntarā', null, 2035033),
('ramayana-2-35-34', 34, 'Ayodhya Kanda, Sarga 35, Verse 34', 'नाश्रौषमिति राजानमुपालब्धोऽपि वक्ष्यसि।
चिरं दुःखस्य पापिष्ठमिति रामस्तमब्रवीत्॥', 'nāśrauṣam iti rājānam upālabdho ''pi vakṣyasi
ciraṃ duḥkhasya pāpiṣṭham iti rāmas tam abravīt', null, 2035034),
('ramayana-2-35-35', 35, 'Ayodhya Kanda, Sarga 35, Verse 35', 'रामस्य स वचः कुर्वन्ननुज्ञाप्य च तं जनम्।
व्रजतोऽपि हयाञ्शीघ्रं चोदयामास सारथिः॥', 'rāmasya sa vacaḥ kurvann anujñāpya ca taṃ janam
vrajato ''pi hayāñ śīghraṃ codayām āsa sārathiḥ', null, 2035035),
('ramayana-2-35-36', 36, 'Ayodhya Kanda, Sarga 35, Verse 36', 'न्यवर्तत जनो राज्ञो रामं कृत्वा प्रदक्षिणम्।
मनसाप्यश्रुवेगैश्च न न्यवर्तत मानुषम्॥', 'nyavartata jano rājño rāmaṃ kṛtvā pradakṣiṇam
manasāpy aśruvegaiś ca na nyavartata mānuṣam', null, 2035036),
('ramayana-2-35-37', 37, 'Ayodhya Kanda, Sarga 35, Verse 37', 'यमिच्छेत्पुनरायान्तं नैनं दूरमनुव्रजेत्।
इत्यमात्या महाराजमूचुर्दशरथं वचः॥', 'yam icchet punar āyāntaṃ nainaṃ dūram anuvrajet
ity amātyā mahārājam ūcur daśarathaṃ vacaḥ', null, 2035037),
('ramayana-2-35-38', 38, 'Ayodhya Kanda, Sarga 35, Verse 38', 'तेषां वचः सर्वगुणोपपन्नं प्रस्विन्नगात्रः प्रविषण्णरूपः।
निशम्य राजा कृपणः सभार्यो व्यवस्थितस्तं सुतमीक्षमाणः॥', 'teṣāṃ vacaḥ sarvaguṇopapannaṃ prasvinnagātraḥ praviṣaṇṇarūpaḥ
niśamya rājā kṛpaṇaḥ sabhāryo vyavasthitas taṃ sutam īkṣamāṇaḥ', null, 2035038)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 36 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-36-1', 1, 'Ayodhya Kanda, Sarga 36, Verse 1', 'तस्मिंस्तु पुरुषव्याघ्रे निष्क्रामति कृताञ्जलौ।
आर्तशब्दो हि संजज्ञे स्त्रीणामन्तःपुरे महान्॥', 'tasmiṃs tu puruṣavyāghre niṣkrāmati kṛtāñjalau
ārtaśabdo hi saṃjajñe strīṇām antaḥpure mahān', null, 2036001),
('ramayana-2-36-2', 2, 'Ayodhya Kanda, Sarga 36, Verse 2', 'अनाथस्य जनस्यास्य दुर्बलस्य तपस्विनः।
यो गतिं शरणं चासीत्स नाथः क्व नु गच्छति॥', 'anāthasya janasyāsya durbalasya tapasvinaḥ
yo gatiṃ śaraṇaṃ cāsīt sa nāthaḥ kva nu gacchati', null, 2036002),
('ramayana-2-36-3', 3, 'Ayodhya Kanda, Sarga 36, Verse 3', 'न क्रुध्यत्यभिशस्तोऽपि क्रोधनीयानि वर्जयन्।
क्रुद्धान्प्रसादयन्सर्वान्समदुःखः क्व गच्छति॥', 'na krudhyaty abhiśasto ''pi krodhanīyāni varjayan
kruddhān prasādayan sarvān samaduḥkhaḥ kva gacchati', null, 2036003),
('ramayana-2-36-4', 4, 'Ayodhya Kanda, Sarga 36, Verse 4', 'कौसल्यायां महातेजा यथा मातरि वर्तते।
तथा यो वर्ततेऽस्मासु महात्मा क्व नु गच्छति॥', 'kausalyāyāṃ mahātejā yathā mātari vartate
tathā yo vartate ''smāsu mahātmā kva nu gacchati', null, 2036004),
('ramayana-2-36-5', 5, 'Ayodhya Kanda, Sarga 36, Verse 5', 'कैकेय्या क्लिश्यमानेन राज्ञा संचोदितो वनम्।
परित्राता जनस्यास्य जगतः क्व नु गच्छति॥', 'kaikeyyā kliśyamānena rājñā saṃcodito vanam
paritrātā janasyāsya jagataḥ kva nu gacchati', null, 2036005),
('ramayana-2-36-6', 6, 'Ayodhya Kanda, Sarga 36, Verse 6', 'अहो निश्चेतनो राजा जीवलोकस्य संप्रियम्।
धर्म्यं सत्यव्रतं रामं वनवासो प्रवत्स्यति॥', 'aho niścetano rājā jīvalokasya saṃpriyam
dharmyaṃ satyavrataṃ rāmaṃ vanavāso pravatsyati', null, 2036006),
('ramayana-2-36-7', 7, 'Ayodhya Kanda, Sarga 36, Verse 7', 'इति सर्वा महिष्यस्ता विवत्सा इव धेनवः।
रुरुदुश्चैव दुःखार्ताः सस्वरं च विचुक्रुशुः॥', 'iti sarvā mahiṣyas tā vivatsā iva dhenavaḥ
ruruduś caiva duḥkhārtāḥ sasvaraṃ ca vicukruśuḥ', null, 2036007),
('ramayana-2-36-8', 8, 'Ayodhya Kanda, Sarga 36, Verse 8', 'स तमन्तःपुरे घोरमार्तशब्दं महीपतिः।
पुत्रशोकाभिसंतप्तः श्रुत्वा चासीत्सुदुःखितः॥', 'sa tam antaḥpure ghoram ārtaśabdaṃ mahīpatiḥ
putraśokābhisaṃtaptaḥ śrutvā cāsīt suduḥkhitaḥ', null, 2036008),
('ramayana-2-36-9', 9, 'Ayodhya Kanda, Sarga 36, Verse 9', 'नाग्निहोत्राण्यहूयन्त सूर्यश्चान्तरधीयत।
व्यसृजन्कवलान्नागा गावो वत्सान्न पाययन्॥', 'nāgnihotrāṇy ahūyanta sūryaś cāntaradhīyata
vyasṛjan kavalān nāgā gāvo vatsān na pāyayan', null, 2036009),
('ramayana-2-36-10', 10, 'Ayodhya Kanda, Sarga 36, Verse 10', 'त्रिशङ्कुर्लोहिताङ्गश्च बृहस्पतिबुधावपि।
दारुणाः सोममभ्येत्य ग्रहाः सर्वे व्यवस्थिताः॥', 'triśaṅkur lohitāṅgaś ca bṛhaspatibudhāv api
dāruṇāḥ somam abhyetya grahāḥ sarve vyavasthitāḥ', null, 2036010),
('ramayana-2-36-11', 11, 'Ayodhya Kanda, Sarga 36, Verse 11', 'नक्षत्राणि गतार्चींषि ग्रहाश्च गततेजसः।
विशाखाश्च सधूमाश्च नभसि प्रचकाशिरे॥', 'nakṣatrāṇi gatārcīṃṣi grahāś ca gatatejasaḥ
viśākhāś ca sadhūmāś ca nabhasi pracakāśire', null, 2036011),
('ramayana-2-36-12', 12, 'Ayodhya Kanda, Sarga 36, Verse 12', 'अकस्मान्नागरः सर्वो जनो दैन्यमुपागमत्।
आहारे वा विहारे वा न कश्चिदकरोन्मनः॥', 'akasmān nāgaraḥ sarvo jano dainyam upāgamat
āhāre vā vihāre vā na kaś cid akaron manaḥ', null, 2036012),
('ramayana-2-36-13', 13, 'Ayodhya Kanda, Sarga 36, Verse 13', 'बाष्पपर्याकुलमुखो राजमार्गगतो जनः।
न हृष्टो लक्ष्यते कश्चित्सर्वः शोकपरायणः॥', 'bāṣpaparyākulamukho rājamārgagato janaḥ
na hṛṣṭo lakṣyate kaś cit sarvaḥ śokaparāyaṇaḥ', null, 2036013),
('ramayana-2-36-14', 14, 'Ayodhya Kanda, Sarga 36, Verse 14', 'न वाति पवनः शीतो न शशी सौम्यदर्शनः।
न सूर्यस्तपते लोकं सर्वं पर्याकुलं जगत्॥', 'na vāti pavanaḥ śīto na śaśī saumyadarśanaḥ
na sūryas tapate lokaṃ sarvaṃ paryākulaṃ jagat', null, 2036014),
('ramayana-2-36-15', 15, 'Ayodhya Kanda, Sarga 36, Verse 15', 'अनर्थिनः सुताः स्त्रीणां भर्तारो भ्रातरस्तथा।
सर्वे सर्वं परित्यज्य राममेवान्वचिन्तयन्॥', 'anarthinaḥ sutāḥ strīṇāṃ bhartāro bhrātaras tathā
sarve sarvaṃ parityajya rāmam evānvacintayan', null, 2036015),
('ramayana-2-36-16', 16, 'Ayodhya Kanda, Sarga 36, Verse 16', 'ये तु रामस्य सुहृदः सर्वे ते मूढचेतसः।
शोकभारेण चाक्रान्ताः शयनं न जुहुस्तदा॥', 'ye tu rāmasya suhṛdaḥ sarve te mūḍhacetasaḥ
śokabhāreṇa cākrāntāḥ śayanaṃ na juhus tadā', null, 2036016),
('ramayana-2-36-17', 17, 'Ayodhya Kanda, Sarga 36, Verse 17', 'ततस्त्वयोध्या रहिता महात्मना पुरंदरेणेव मही सपर्वता।
चचाल घोरं भयभारपीडिता सनागयोधाश्वगणा ननाद च॥', 'tatas tv ayodhyā rahitā mahātmanā puraṃdareṇeva mahī saparvatā
cacāla ghoraṃ bhayabhārapīḍitā sanāgayodhāśvagaṇā nanāda ca', null, 2036017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 37 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-37-1', 1, 'Ayodhya Kanda, Sarga 37, Verse 1', 'यावत्तु निर्यतस्तस्य रजोरूपमदृश्यत।
नैवेक्ष्वाकुवरस्तावत्संजहारात्मचक्षुषी॥', 'yāvat tu niryatas tasya rajorūpam adṛśyata
naivekṣvākuvaras tāvat saṃjahārātmacakṣuṣī', null, 2037001),
('ramayana-2-37-2', 2, 'Ayodhya Kanda, Sarga 37, Verse 2', 'यावद्राजा प्रियं पुत्रं पश्यत्यत्यन्तधार्मिकम्।
तावद्व्यवर्धतेवास्य धरण्यां पुत्रदर्शने॥', 'yāvad rājā priyaṃ putraṃ paśyaty atyantadhārmikam
tāvad vyavardhatevāsya dharaṇyāṃ putradarśane', null, 2037002),
('ramayana-2-37-3', 3, 'Ayodhya Kanda, Sarga 37, Verse 3', 'न पश्यति रजोऽप्यस्य यदा रामस्य भूमिपः।
तदार्तश्च विषण्णश्च पपात धरणीतले॥', 'na paśyati rajo ''py asya yadā rāmasya bhūmipaḥ
tadārtaś ca viṣaṇṇaś ca papāta dharaṇītale', null, 2037003),
('ramayana-2-37-4', 4, 'Ayodhya Kanda, Sarga 37, Verse 4', 'तस्य दक्षिणमन्वगात्कौसल्या बाहुमङ्गना।
वामं चास्यान्वगात्पार्श्वं कैकेयी भरतप्रिया॥', 'tasya dakṣiṇam anvagāt kausalyā bāhum aṅganā
vāmaṃ cāsyānvagāt pārśvaṃ kaikeyī bharatapriyā', null, 2037004),
('ramayana-2-37-5', 5, 'Ayodhya Kanda, Sarga 37, Verse 5', 'तां नयेन च संपन्नो धर्मेण निवयेन च।
उवाच राजा कैकेयीं समीक्ष्य व्यथितेन्द्रियः॥', 'tāṃ nayena ca saṃpanno dharmeṇa nivayena ca
uvāca rājā kaikeyīṃ samīkṣya vyathitendriyaḥ', null, 2037005),
('ramayana-2-37-6', 6, 'Ayodhya Kanda, Sarga 37, Verse 6', 'कैकेयि मा ममाङ्गानि स्प्राक्षीस्त्वं दुष्टचारिणी।
न हि त्वां द्रष्टुमिच्छामि न भार्या न च बान्धवी॥', 'kaikeyi mā mamāṅgāni sprākṣīs tvaṃ duṣṭacāriṇī
na hi tvāṃ draṣṭum icchāmi na bhāryā na ca bāndhavī', null, 2037006),
('ramayana-2-37-7', 7, 'Ayodhya Kanda, Sarga 37, Verse 7', 'ये च त्वामुपजीवन्ति नाहं तेषां न ते मम।
केवलार्थपरां हि त्वां त्यक्तधर्मां त्यजाम्यहम्॥', 'ye ca tvām upajīvanti nāhaṃ teṣāṃ na te mama
kevalārthaparāṃ hi tvāṃ tyaktadharmāṃ tyajāmy aham', null, 2037007),
('ramayana-2-37-8', 8, 'Ayodhya Kanda, Sarga 37, Verse 8', 'अगृह्णां यच्च ते पाणिमग्निं पर्यणयं च यत्।
अनुजानामि तत्सर्वमस्मिंल्लोके परत्र च॥', 'agṛhṇāṃ yac ca te pāṇim agniṃ paryaṇayaṃ ca yat
anujānāmi tat sarvam asmiṃl loke paratra ca', null, 2037008),
('ramayana-2-37-9', 9, 'Ayodhya Kanda, Sarga 37, Verse 9', 'भरतश्चेत्प्रतीतः स्याद्राज्यं प्राप्येदमव्ययम्।
यन्मे स दद्यात्पित्रर्थं मा मा तद्दत्तमागमत्॥', 'bharataś cet pratītaḥ syād rājyaṃ prāpyedam avyayam
yan me sa dadyāt pitrarthaṃ mā mā tad dattam āgamat', null, 2037009),
('ramayana-2-37-10', 10, 'Ayodhya Kanda, Sarga 37, Verse 10', 'अथ रेणुसमुध्वस्तं तमुत्थाप्य नराधिपम्।
न्यवर्तत तदा देवी कौसल्या शोककर्शिता॥', 'atha reṇusamudhvastaṃ tam utthāpya narādhipam
nyavartata tadā devī kausalyā śokakarśitā', null, 2037010),
('ramayana-2-37-11', 11, 'Ayodhya Kanda, Sarga 37, Verse 11', 'हत्वेव ब्राह्मणं कामात्स्पृष्ट्वाग्निमिव पाणिना।
अन्वतप्यत धर्मात्मा पुत्रं संचिन्त्य तापसं॥', 'hatveva brāhmaṇaṃ kāmāt spṛṣṭvāgnim iva pāṇinā
anvatapyata dharmātmā putraṃ saṃcintya tāpasaṃ', null, 2037011),
('ramayana-2-37-12', 12, 'Ayodhya Kanda, Sarga 37, Verse 12', 'निवृत्यैव निवृत्यैव सीदतो रथवर्त्मसु।
राज्ञो नातिबभौ रूपं ग्रस्तस्यांशुमतो यथा॥', 'nivṛtyaiva nivṛtyaiva sīdato rathavartmasu
rājño nātibabhau rūpaṃ grastasyāṃśumato yathā', null, 2037012),
('ramayana-2-37-13', 13, 'Ayodhya Kanda, Sarga 37, Verse 13', 'विललाप च दुःखार्तः प्रियं पुत्रमनुस्मरन्।
नगरान्तमनुप्राप्तं बुद्ध्वा पुत्रमथाब्रवीत्॥', 'vilalāpa ca duḥkhārtaḥ priyaṃ putram anusmaran
nagarāntam anuprāptaṃ buddhvā putram athābravīt', null, 2037013),
('ramayana-2-37-14', 14, 'Ayodhya Kanda, Sarga 37, Verse 14', 'वाहनानां च मुख्यानां वहतां तं ममात्मजम्।
पदानि पथि दृश्यन्ते स महात्मा न दृश्यते॥', 'vāhanānāṃ ca mukhyānāṃ vahatāṃ taṃ mamātmajam
padāni pathi dṛśyante sa mahātmā na dṛśyate', null, 2037014),
('ramayana-2-37-15', 15, 'Ayodhya Kanda, Sarga 37, Verse 15', 'स नूनं क्व चिदेवाद्य वृक्षमूलमुपाश्रितः।
काष्ठं वा यदि वाश्मानमुपधाय शयिष्यते॥', 'sa nūnaṃ kva cid evādya vṛkṣamūlam upāśritaḥ
kāṣṭhaṃ vā yadi vāśmānam upadhāya śayiṣyate', null, 2037015),
('ramayana-2-37-16', 16, 'Ayodhya Kanda, Sarga 37, Verse 16', 'उत्थास्यति च मेदिन्याः कृपणः पांशुगुण्ठितः।
विनिःश्वसन्प्रस्रवणात्करेणूनामिवर्षभः॥', 'utthāsyati ca medinyāḥ kṛpaṇaḥ pāṃśuguṇṭhitaḥ
viniḥśvasan prasravaṇāt kareṇūnām ivarṣabhaḥ', null, 2037016),
('ramayana-2-37-17', 17, 'Ayodhya Kanda, Sarga 37, Verse 17', 'द्रक्ष्यन्ति नूनं पुरुषा दीर्घबाहुं वनेचराः।
राममुत्थाय गच्छन्तं लोकनाथमनाथवत्॥', 'drakṣyanti nūnaṃ puruṣā dīrghabāhuṃ vanecarāḥ
rāmam utthāya gacchantaṃ lokanātham anāthavat', null, 2037017),
('ramayana-2-37-18', 18, 'Ayodhya Kanda, Sarga 37, Verse 18', 'सकामा भव कैकेयि विधवा राज्यमावस।
न हि तं पुरुषव्याघ्रं विना जीवितुमुत्सहे॥', 'sakāmā bhava kaikeyi vidhavā rājyam āvasa
na hi taṃ puruṣavyāghraṃ vinā jīvitum utsahe', null, 2037018),
('ramayana-2-37-19', 19, 'Ayodhya Kanda, Sarga 37, Verse 19', 'इत्येवं विलपन्राजा जनौघेनाभिसंवृतः।
अपस्नात इवारिष्टं प्रविवेश पुरोत्तमम्॥', 'ity evaṃ vilapan rājā janaughenābhisaṃvṛtaḥ
apasnāta ivāriṣṭaṃ praviveśa purottamam', null, 2037019),
('ramayana-2-37-20', 20, 'Ayodhya Kanda, Sarga 37, Verse 20', 'शून्यचत्वरवेश्मान्तां संवृतापणदेवताम्।
क्लान्तदुर्बलदुःखार्तां नात्याकीर्णमहापथाम्॥', 'śūnyacatvaraveśmāntāṃ saṃvṛtāpaṇadevatām
klāntadurbaladuḥkhārtāṃ nātyākīrṇamahāpathām', null, 2037020),
('ramayana-2-37-21', 21, 'Ayodhya Kanda, Sarga 37, Verse 21', 'तामवेक्ष्य पुरीं सर्वां राममेवानुचिन्तयन्।
विलपन्प्राविशद्राजा गृहं सूर्य इवाम्बुदम्॥', 'tām avekṣya purīṃ sarvāṃ rāmam evānucintayan
vilapan prāviśad rājā gṛhaṃ sūrya ivāmbudam', null, 2037021),
('ramayana-2-37-22', 22, 'Ayodhya Kanda, Sarga 37, Verse 22', 'महाह्रदमिवाक्षोभ्यं सुपर्णेन हृतोरगम्।
रामेण रहितं वेश्म वैदेह्या लक्ष्मणेन च॥', 'mahāhradam ivākṣobhyaṃ suparṇena hṛtoragam
rāmeṇa rahitaṃ veśma vaidehyā lakṣmaṇena ca', null, 2037022),
('ramayana-2-37-23', 23, 'Ayodhya Kanda, Sarga 37, Verse 23', 'कौसल्याया गृहं शीघ्रं राम मातुर्नयन्तु माम्।
इति ब्रुवन्तं राजानमनयन्द्वारदर्शितः॥', 'kausalyāyā gṛhaṃ śīghraṃ rāma mātur nayantu mām
iti bruvantaṃ rājānam anayan dvāradarśitaḥ', null, 2037023),
('ramayana-2-37-24', 24, 'Ayodhya Kanda, Sarga 37, Verse 24', 'ततस्तत्र प्रविष्टस्य कौसल्याया निवेशनम्।
अधिरुह्यापि शयनं बभूव लुलितं मनः॥', 'tatas tatra praviṣṭasya kausalyāyā niveśanam
adhiruhyāpi śayanaṃ babhūva lulitaṃ manaḥ', null, 2037024),
('ramayana-2-37-25', 25, 'Ayodhya Kanda, Sarga 37, Verse 25', 'तच्च दृष्ट्वा महाराजो भुजमुद्यम्य वीर्यवान्।
उच्चैः स्वरेण चुक्रोश हा राघव जहासि माम्॥', 'tac ca dṛṣṭvā mahārājo bhujam udyamya vīryavān
uccaiḥ svareṇa cukrośa hā rāghava jahāsi mām', null, 2037025),
('ramayana-2-37-26', 26, 'Ayodhya Kanda, Sarga 37, Verse 26', 'सुखिता बत तं कालं जीविष्यन्ति नरोत्तमाः।
परिष्वजन्तो ये रामं द्रक्ष्यन्ति पुनरागतम्॥', 'sukhitā bata taṃ kālaṃ jīviṣyanti narottamāḥ
pariṣvajanto ye rāmaṃ drakṣyanti punar āgatam', null, 2037026),
('ramayana-2-37-27', 27, 'Ayodhya Kanda, Sarga 37, Verse 27', 'न त्वां पश्यामि कौसल्ये साधु मां पाणिना स्पृश।
रामं मेऽनुगता दृष्टिरद्यापि न निवर्तते॥', 'na tvāṃ paśyāmi kausalye sādhu māṃ pāṇinā spṛśa
rāmaṃ me ''nugatā dṛṣṭir adyāpi na nivartate', null, 2037027),
('ramayana-2-37-28', 28, 'Ayodhya Kanda, Sarga 37, Verse 28', 'तं राममेवानुविचिन्तयन्तं समीक्ष्य देवी शयने नरेन्द्रम्।
उपोपविश्याधिकमार्तरूपा विनिःश्वसन्ती विललाप कृच्छ्रं॥', 'taṃ rāmam evānuvicintayantaṃ samīkṣya devī śayane narendram
upopaviśyādhikam ārtarūpā viniḥśvasantī vilalāpa kṛcchraṃ', null, 2037028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 38 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-38-1', 1, 'Ayodhya Kanda, Sarga 38, Verse 1', 'ततः समीक्ष्य शयने सन्नं शोकेन पार्थिवम्।
कौसल्या पुत्रशोकार्ता तमुवाच महीपतिम्॥', 'tataḥ samīkṣya śayane sannaṃ śokena pārthivam
kausalyā putraśokārtā tam uvāca mahīpatim', null, 2038001),
('ramayana-2-38-2', 2, 'Ayodhya Kanda, Sarga 38, Verse 2', 'राघवो नरशार्दूल विषमुप्त्वा द्विजिह्ववत्।
विचरिष्यति कैकेयी निर्मुक्तेव हि पन्नगी॥', 'rāghavo naraśārdūla viṣam uptvā dvijihvavat
vicariṣyati kaikeyī nirmukteva hi pannagī', null, 2038002),
('ramayana-2-38-3', 3, 'Ayodhya Kanda, Sarga 38, Verse 3', 'विवास्य रामं सुभगा लब्धकामा समाहिता।
त्रासयिष्यति मां भूयो दुष्टाहिरिव वेश्मनि॥', 'vivāsya rāmaṃ subhagā labdhakāmā samāhitā
trāsayiṣyati māṃ bhūyo duṣṭāhir iva veśmani', null, 2038003),
('ramayana-2-38-4', 4, 'Ayodhya Kanda, Sarga 38, Verse 4', 'अथ स्म नगरे रामश्चरन्भैक्षं गृहे वसेत्।
कामकारो वरं दातुमपि दासं ममात्मजम्॥', 'atha sma nagare rāmaś caran bhaikṣaṃ gṛhe vaset
kāmakāro varaṃ dātum api dāsaṃ mamātmajam', null, 2038004),
('ramayana-2-38-5', 5, 'Ayodhya Kanda, Sarga 38, Verse 5', 'पातयित्वा तु कैकेय्या रामं स्थानाद्यथेष्टतः।
प्रदिष्टो रक्षसां भागः पर्वणीवाहिताग्निना॥', 'pātayitvā tu kaikeyyā rāmaṃ sthānād yatheṣṭataḥ
pradiṣṭo rakṣasāṃ bhāgaḥ parvaṇīvāhitāgninā', null, 2038005),
('ramayana-2-38-6', 6, 'Ayodhya Kanda, Sarga 38, Verse 6', 'गजराजगतिर्वीरो महाबाहुर्धनुर्धरः।
वनमाविशते नूनं सभार्यः सहलक्ष्मणः॥', 'gajarājagatir vīro mahābāhur dhanurdharaḥ
vanam āviśate nūnaṃ sabhāryaḥ sahalakṣmaṇaḥ', null, 2038006),
('ramayana-2-38-7', 7, 'Ayodhya Kanda, Sarga 38, Verse 7', 'वने त्वदृष्टदुःखानां कैकेय्यानुमते त्वया।
त्यक्तानां वनवासाय का न्ववस्था भविष्यति॥', 'vane tv adṛṣṭaduḥkhānāṃ kaikeyyānumate tvayā
tyaktānāṃ vanavāsāya kā nv avasthā bhaviṣyati', null, 2038007),
('ramayana-2-38-8', 8, 'Ayodhya Kanda, Sarga 38, Verse 8', 'ते रत्नहीनास्तरुणाः फलकाले विवासिताः।
कथं वत्स्यन्ति कृपणाः फलमूलैः कृताशनाः॥', 'te ratnahīnās taruṇāḥ phalakāle vivāsitāḥ
kathaṃ vatsyanti kṛpaṇāḥ phalamūlaiḥ kṛtāśanāḥ', null, 2038008),
('ramayana-2-38-9', 9, 'Ayodhya Kanda, Sarga 38, Verse 9', 'अपीदानीं स कालः स्यान्मम शोकक्षयः शिवः।
सभार्यं यत्सह भ्रात्रा पश्येयमिह राघवम्॥', 'apīdānīṃ sa kālaḥ syān mama śokakṣayaḥ śivaḥ
sabhāryaṃ yat saha bhrātrā paśyeyam iha rāghavam', null, 2038009),
('ramayana-2-38-10', 10, 'Ayodhya Kanda, Sarga 38, Verse 10', 'श्रुत्वैवोपस्थितौ वीरौ कदायोध्या भविष्यति।
यशस्विनी हृष्टजना सूच्छ्रितध्वजमालिनी॥', 'śrutvaivopasthitau vīrau kadāyodhyā bhaviṣyati
yaśasvinī hṛṣṭajanā sūcchritadhvajamālinī', null, 2038010),
('ramayana-2-38-11', 11, 'Ayodhya Kanda, Sarga 38, Verse 11', 'कदा प्रेक्ष्य नरव्याघ्रावरण्यात्पुनरागतौ।
नन्दिष्यति पुरी हृष्टा समुद्र इव पर्वणि॥', 'kadā prekṣya naravyāghrāv araṇyāt punarāgatau
nandiṣyati purī hṛṣṭā samudra iva parvaṇi', null, 2038011),
('ramayana-2-38-12', 12, 'Ayodhya Kanda, Sarga 38, Verse 12', 'कदायोध्यां महाबाहुः पुरीं वीरः प्रवेक्ष्यति।
पुरस्कृत्य रथे सीतां वृषभो गोवधूमिव॥', 'kadāyodhyāṃ mahābāhuḥ purīṃ vīraḥ pravekṣyati
puraskṛtya rathe sītāṃ vṛṣabho govadhūm iva', null, 2038012),
('ramayana-2-38-13', 13, 'Ayodhya Kanda, Sarga 38, Verse 13', 'कदा प्राणिसहस्राणि राजमार्गे ममात्मजौ।
लाजैरवकरिष्यन्ति प्रविशन्तावरिंदमौ॥', 'kadā prāṇisahasrāṇi rājamārge mamātmajau
lājair avakariṣyanti praviśantāv ariṃdamau', null, 2038013),
('ramayana-2-38-14', 14, 'Ayodhya Kanda, Sarga 38, Verse 14', 'कदा सुमनसः कन्या द्विजातीनां फलानि च।
प्रदिशन्त्यः पुरीं हृष्टाः करिष्यन्ति प्रदक्षिणम्॥', 'kadā sumanasaḥ kanyā dvijātīnāṃ phalāni ca
pradiśantyaḥ purīṃ hṛṣṭāḥ kariṣyanti pradakṣiṇam', null, 2038014),
('ramayana-2-38-15', 15, 'Ayodhya Kanda, Sarga 38, Verse 15', 'कदा परिणतो बुद्ध्या वयसा चामरप्रभः।
अभ्युपैष्यति धर्मज्ञस्त्रिवर्ष इव मां ललन्॥', 'kadā pariṇato buddhyā vayasā cāmaraprabhaḥ
abhyupaiṣyati dharmajñas trivarṣa iva māṃ lalan', null, 2038015),
('ramayana-2-38-16', 16, 'Ayodhya Kanda, Sarga 38, Verse 16', 'निःसंशयं मया मन्ये पुरा वीर कदर्यया।
पातु कामेषु वत्सेषु मातॄणां शातिताः स्तनाः॥', 'niḥsaṃśayaṃ mayā manye purā vīra kadaryayā
pātu kāmeṣu vatseṣu mātṝṇāṃ śātitāḥ stanāḥ', null, 2038016),
('ramayana-2-38-17', 17, 'Ayodhya Kanda, Sarga 38, Verse 17', 'साहं गौरिव सिंहेन विवत्सा वत्सला कृता।
कैकेय्या पुरुषव्याघ्र बालवत्सेव गौर्बलात्॥', 'sāhaṃ gaur iva siṃhena vivatsā vatsalā kṛtā
kaikeyyā puruṣavyāghra bālavatseva gaur balāt', null, 2038017),
('ramayana-2-38-18', 18, 'Ayodhya Kanda, Sarga 38, Verse 18', 'न हि तावद्गुणैर्जुष्टं सर्वशास्त्रविशारदम्।
एकपुत्रा विना पुत्रमहं जीवितुमुत्सहे॥', 'na hi tāvad guṇair juṣṭaṃ sarvaśāstraviśāradam
ekaputrā vinā putram ahaṃ jīvitum utsahe', null, 2038018),
('ramayana-2-38-19', 19, 'Ayodhya Kanda, Sarga 38, Verse 19', 'न हि मे जीविते किं चित्सामर्थमिह कल्प्यते।
अपश्यन्त्याः प्रियं पुत्रं महाबाहुं महाबलम्॥', 'na hi me jīvite kiṃ cit sāmartham iha kalpyate
apaśyantyāḥ priyaṃ putraṃ mahābāhuṃ mahābalam', null, 2038019),
('ramayana-2-38-20', 20, 'Ayodhya Kanda, Sarga 38, Verse 20', 'अयं हि मां दीपयते समुत्थितस्तनूजशोकप्रभवो हुताशनः।
महीमिमां रश्मिभिरुत्तमप्रभो यथा निदाघे भगवान्दिवाकरः॥', 'ayaṃ hi māṃ dīpayate samutthitas tanūjaśokaprabhavo hutāśanaḥ
mahīm imāṃ raśmibhir uttamaprabho yathā nidāghe bhagavān divākaraḥ', null, 2038020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 39 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-39-1', 1, 'Ayodhya Kanda, Sarga 39, Verse 1', 'विलपन्तीं तथा तां तु कौसल्यां प्रमदोत्तमाम्।
इदं धर्मे स्थिता धर्म्यं सुमित्रा वाक्यमब्रवीत्॥', 'vilapantīṃ tathā tāṃ tu kausalyāṃ pramadottamām
idaṃ dharme sthitā dharmyaṃ sumitrā vākyam abravīt', null, 2039001),
('ramayana-2-39-2', 2, 'Ayodhya Kanda, Sarga 39, Verse 2', 'तवार्ये सद्गुणैर्युक्तः पुत्रः स पुरुषोत्तमः।
किं ते विलपितेनैवं कृपणं रुदितेन वा॥', 'tavārye sadguṇair yuktaḥ putraḥ sa puruṣottamaḥ
kiṃ te vilapitenaivaṃ kṛpaṇaṃ ruditena vā', null, 2039002),
('ramayana-2-39-3', 3, 'Ayodhya Kanda, Sarga 39, Verse 3', 'यस्तवार्ये गतः पुत्रस्त्यक्त्वा राज्यं महाबलः।
साधु कुर्वन्महात्मानं पितरं सत्यवादिनाम्॥', 'yas tavārye gataḥ putras tyaktvā rājyaṃ mahābalaḥ
sādhu kurvan mahātmānaṃ pitaraṃ satyavādinām', null, 2039003),
('ramayana-2-39-4', 4, 'Ayodhya Kanda, Sarga 39, Verse 4', 'शिष्टैराचरिते सम्यक्शश्वत्प्रेत्य फलोदये।
रामो धर्मे स्थितः श्रेष्ठो न स शोच्यः कदा चन॥', 'śiṣṭair ācarite samyak śaśvat pretya phalodaye
rāmo dharme sthitaḥ śreṣṭho na sa śocyaḥ kadā cana', null, 2039004),
('ramayana-2-39-5', 5, 'Ayodhya Kanda, Sarga 39, Verse 5', 'वर्तते चोत्तमां वृत्तिं लक्ष्मणोऽस्मिन्सदानघः।
दयावान्सर्वभूतेषु लाभस्तस्य महात्मनः॥', 'vartate cottamāṃ vṛttiṃ lakṣmaṇo ''smin sadānaghaḥ
dayāvān sarvabhūteṣu lābhas tasya mahātmanaḥ', null, 2039005),
('ramayana-2-39-6', 6, 'Ayodhya Kanda, Sarga 39, Verse 6', 'अरण्यवासे यद्दुःखं जानती वै सुखोचिता।
अनुगच्छति वैदेही धर्मात्मानं तवात्मजम्॥', 'araṇyavāse yad duḥkhaṃ jānatī vai sukhocitā
anugacchati vaidehī dharmātmānaṃ tavātmajam', null, 2039006),
('ramayana-2-39-7', 7, 'Ayodhya Kanda, Sarga 39, Verse 7', 'कीर्तिभूतां पताकां यो लोके भ्रामयति प्रभुः।
दमसत्यव्रतपरः किं न प्राप्तस्तवात्मजः॥', 'kīrtibhūtāṃ patākāṃ yo loke bhrāmayati prabhuḥ
damasatyavrataparaḥ kiṃ na prāptas tavātmajaḥ', null, 2039007),
('ramayana-2-39-8', 8, 'Ayodhya Kanda, Sarga 39, Verse 8', 'व्यक्तं रामस्य विज्ञाय शौचं माहात्म्यमुत्तमम्।
न गात्रमंशुभिः सूर्यः संतापयितुमर्हति॥', 'vyaktaṃ rāmasya vijñāya śaucaṃ māhātmyam uttamam
na gātram aṃśubhiḥ sūryaḥ saṃtāpayitum arhati', null, 2039008),
('ramayana-2-39-9', 9, 'Ayodhya Kanda, Sarga 39, Verse 9', 'शिवः सर्वेषु कालेषु काननेभ्यो विनिःसृतः।
राघवं युक्तशीतोष्णः सेविष्यति सुखोऽनिलः॥', 'śivaḥ sarveṣu kāleṣu kānanebhyo viniḥsṛtaḥ
rāghavaṃ yuktaśītoṣṇaḥ seviṣyati sukho ''nilaḥ', null, 2039009),
('ramayana-2-39-10', 10, 'Ayodhya Kanda, Sarga 39, Verse 10', 'शयानमनघं रात्रौ पितेवाभिपरिष्वजन्।
रश्मिभिः संस्पृशञ्शीतैश्चन्द्रमा ह्लादयिष्यति॥', 'śayānam anaghaṃ rātrau pitevābhipariṣvajan
raśmibhiḥ saṃspṛśañ śītaiś candramā hlādayiṣyati', null, 2039010),
('ramayana-2-39-11', 11, 'Ayodhya Kanda, Sarga 39, Verse 11', 'ददौ चास्त्राणि दिव्यानि यस्मै ब्रह्मा महौजसे।
दानवेन्द्रं हतं दृष्ट्वा तिमिध्वजसुतं रणे॥', 'dadau cāstrāṇi divyāni yasmai brahmā mahaujase
dānavendraṃ hataṃ dṛṣṭvā timidhvajasutaṃ raṇe', null, 2039011),
('ramayana-2-39-12', 12, 'Ayodhya Kanda, Sarga 39, Verse 12', 'पृथिव्या सह वैदेह्या श्रिया च पुरुषर्षभः।
क्षिप्रं तिसृभिरेताभिः सह रामोऽभिषेक्ष्यते॥', 'pṛthivyā saha vaidehyā śriyā ca puruṣarṣabhaḥ
kṣipraṃ tisṛbhir etābhiḥ saha rāmo ''bhiṣekṣyate', null, 2039012),
('ramayana-2-39-13', 13, 'Ayodhya Kanda, Sarga 39, Verse 13', 'दुःखजं विसृजन्त्यस्रं निष्क्रामन्तमुदीक्ष्य यम्।
समुत्स्रक्ष्यसि नेत्राभ्यां क्षिप्रमानन्दजं पयः॥', 'duḥkhajaṃ visṛjanty asraṃ niṣkrāmantam udīkṣya yam
samutsrakṣyasi netrābhyāṃ kṣipram ānandajaṃ payaḥ', null, 2039013),
('ramayana-2-39-14', 14, 'Ayodhya Kanda, Sarga 39, Verse 14', 'अभिवादयमानं तं दृष्ट्वा ससुहृदं सुतम्।
मुदाश्रु मोक्ष्यसे क्षिप्रं मेघलेकेव वार्षिकी॥', 'abhivādayamānaṃ taṃ dṛṣṭvā sasuhṛdaṃ sutam
mudāśru mokṣyase kṣipraṃ meghalekeva vārṣikī', null, 2039014),
('ramayana-2-39-15', 15, 'Ayodhya Kanda, Sarga 39, Verse 15', 'पुत्रस्ते वरदः क्षिप्रमयोध्यां पुनरागतः।
कराभ्यां मृदुपीनाभ्यां चरणौ पीडयिष्यति॥', 'putras te varadaḥ kṣipram ayodhyāṃ punar āgataḥ
karābhyāṃ mṛdupīnābhyāṃ caraṇau pīḍayiṣyati', null, 2039015),
('ramayana-2-39-16', 16, 'Ayodhya Kanda, Sarga 39, Verse 16', 'निशम्य तल्लक्ष्मणमातृवाक्यं रामस्य मातुर्नरदेवपत्न्याः।
सद्यः शरीरे विननाश शोकः शरद्गतो मेघ इवाल्पतोयः॥', 'niśamya tal lakṣmaṇamātṛvākyaṃ rāmasya mātur naradevapatnyāḥ
sadyaḥ śarīre vinanāśa śokaḥ śaradgato megha ivālpatoyaḥ', null, 2039016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 40 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-40-1', 1, 'Ayodhya Kanda, Sarga 40, Verse 1', 'अनुरक्ता महात्मानं रामं सत्यपरक्रमम्।
अनुजग्मुः प्रयान्तं तं वनवासाय मानवाः॥', 'anuraktā mahātmānaṃ rāmaṃ satyaparakramam
anujagmuḥ prayāntaṃ taṃ vanavāsāya mānavāḥ', null, 2040001),
('ramayana-2-40-2', 2, 'Ayodhya Kanda, Sarga 40, Verse 2', 'निवर्तितेऽपि च बलात्सुहृद्वर्गे च राजिनि।
नैव ते संन्यवर्तन्त रामस्यानुगता रथम्॥', 'nivartite ''pi ca balāt suhṛdvarge ca rājini
naiva te saṃnyavartanta rāmasyānugatā ratham', null, 2040002),
('ramayana-2-40-3', 3, 'Ayodhya Kanda, Sarga 40, Verse 3', 'अयोध्यानिलयानां हि पुरुषाणां महायशाः।
बभूव गुणसंपन्नः पूर्णचन्द्र इव प्रियः॥', 'ayodhyānilayānāṃ hi puruṣāṇāṃ mahāyaśāḥ
babhūva guṇasaṃpannaḥ pūrṇacandra iva priyaḥ', null, 2040003),
('ramayana-2-40-4', 4, 'Ayodhya Kanda, Sarga 40, Verse 4', 'स याच्यमानः काकुत्स्थः स्वाभिः प्रकृतिभिस्तदा।
कुर्वाणः पितरं सत्यं वनमेवान्वपद्यत॥', 'sa yācyamānaḥ kākutsthaḥ svābhiḥ prakṛtibhis tadā
kurvāṇaḥ pitaraṃ satyaṃ vanam evānvapadyata', null, 2040004),
('ramayana-2-40-5', 5, 'Ayodhya Kanda, Sarga 40, Verse 5', 'अवेक्षमाणः सस्नेहं चक्षुषा प्रपिबन्निव।
उवाच रामः स्नेहेन ताः प्रजाः स्वाः प्रजा इव॥', 'avekṣamāṇaḥ sasnehaṃ cakṣuṣā prapibann iva
uvāca rāmaḥ snehena tāḥ prajāḥ svāḥ prajā iva', null, 2040005),
('ramayana-2-40-6', 6, 'Ayodhya Kanda, Sarga 40, Verse 6', 'या प्रीतिर्बहुमानश्च मय्ययोध्यानिवासिनाम्।
मत्प्रियार्थं विशेषेण भरते सा निवेश्यताम्॥', 'yā prītir bahumānaś ca mayy ayodhyānivāsinām
matpriyārthaṃ viśeṣeṇa bharate sā niveśyatām', null, 2040006),
('ramayana-2-40-7', 7, 'Ayodhya Kanda, Sarga 40, Verse 7', 'स हि कल्याण चारित्रः कैकेय्यानन्दवर्धनः।
करिष्यति यथावद्वः प्रियाणि च हितानि च॥', 'sa hi kalyāṇa cāritraḥ kaikeyyānandavardhanaḥ
kariṣyati yathāvad vaḥ priyāṇi ca hitāni ca', null, 2040007),
('ramayana-2-40-8', 8, 'Ayodhya Kanda, Sarga 40, Verse 8', 'ज्ञानवृद्धो वयोबालो मृदुर्वीर्यगुणान्वितः।
अनुरूपः स वो भर्ता भविष्यति भयापहः॥', 'jñānavṛddho vayobālo mṛdur vīryaguṇānvitaḥ
anurūpaḥ sa vo bhartā bhaviṣyati bhayāpahaḥ', null, 2040008),
('ramayana-2-40-9', 9, 'Ayodhya Kanda, Sarga 40, Verse 9', 'स हि राजगुणैर्युक्तो युवराजः समीक्षितः।
अपि चापि मया शिष्टैः कार्यं वो भर्तृशासनम्॥', 'sa hi rājaguṇair yukto yuvarājaḥ samīkṣitaḥ
api cāpi mayā śiṣṭaiḥ kāryaṃ vo bhartṛśāsanam', null, 2040009),
('ramayana-2-40-10', 10, 'Ayodhya Kanda, Sarga 40, Verse 10', 'न च तप्येद्यथा चासौ वनवासं गते मयि।
महाराजस्तथा कार्यो मम प्रियचिकीर्षया॥', 'na ca tapyed yathā cāsau vanavāsaṃ gate mayi
mahārājas tathā kāryo mama priyacikīrṣayā', null, 2040010),
('ramayana-2-40-11', 11, 'Ayodhya Kanda, Sarga 40, Verse 11', 'यथा यथा दाशरथिर्धर्ममेवास्थितोऽभवत्।
तथा तथा प्रकृतयो रामं पतिमकामयन्॥', 'yathā yathā dāśarathir dharmam evāsthito ''bhavat
tathā tathā prakṛtayo rāmaṃ patim akāmayan', null, 2040011),
('ramayana-2-40-12', 12, 'Ayodhya Kanda, Sarga 40, Verse 12', 'बाष्पेण पिहितं दीनं रामः सौमित्रिणा सह।
चकर्षेव गुणैर्बद्ध्वा जनं पुनरिवासनम्॥', 'bāṣpeṇa pihitaṃ dīnaṃ rāmaḥ saumitriṇā saha
cakarṣeva guṇair baddhvā janaṃ punar ivāsanam', null, 2040012),
('ramayana-2-40-13', 13, 'Ayodhya Kanda, Sarga 40, Verse 13', 'ते द्विजास्त्रिविधं वृद्धा ज्ञानेन वयसौजसा।
वयःप्रकम्पशिरसो दूरादूचुरिदं वचः॥', 'te dvijās trividhaṃ vṛddhā jñānena vayasaujasā
vayaḥprakampaśiraso dūrād ūcur idaṃ vacaḥ', null, 2040013),
('ramayana-2-40-14', 14, 'Ayodhya Kanda, Sarga 40, Verse 14', 'वहन्तो जवना रामं भो भो जात्यास्तुरंगमाः।
निवर्तध्वं न गन्तव्यं हिता भवत भर्तरि।
उपवाह्यस्तु वो भर्ता नापवाह्यः पुराद्वनम्॥', 'vahanto javanā rāmaṃ bho bho jātyās turaṃgamāḥ
nivartadhvaṃ na gantavyaṃ hitā bhavata bhartari
upavāhyas tu vo bhartā nāpavāhyaḥ purād vanam', null, 2040014),
('ramayana-2-40-15', 15, 'Ayodhya Kanda, Sarga 40, Verse 15', 'एवमार्तप्रलापांस्तान्वृद्धान्प्रलपतो द्विजान्।
अवेक्ष्य सहसा रामो रथादवततार ह॥', 'evam ārtapralāpāṃs tān vṛddhān pralapato dvijān
avekṣya sahasā rāmo rathād avatatāra ha', null, 2040015),
('ramayana-2-40-16', 16, 'Ayodhya Kanda, Sarga 40, Verse 16', 'पद्भ्यामेव जगामाथ ससीतः सहलक्ष्मणः।
संनिकृष्टपदन्यासो रामो वनपरायणः॥', 'padbhyām eva jagāmātha sasītaḥ sahalakṣmaṇaḥ
saṃnikṛṣṭapadanyāso rāmo vanaparāyaṇaḥ', null, 2040016),
('ramayana-2-40-17', 17, 'Ayodhya Kanda, Sarga 40, Verse 17', 'द्विजातींस्तु पदातींस्तान्रामश्चारित्रवत्सलः।
न शशाक घृणाचक्षुः परिमोक्तुं रथेन सः॥', 'dvijātīṃs tu padātīṃs tān rāmaś cāritravatsalaḥ
na śaśāka ghṛṇācakṣuḥ parimoktuṃ rathena saḥ', null, 2040017),
('ramayana-2-40-18', 18, 'Ayodhya Kanda, Sarga 40, Verse 18', 'गच्छन्तमेव तं दृष्ट्वा रामं संभ्रान्तमानसाः।
ऊचुः परमसंतप्ता रामं वाक्यमिदं द्विजाः॥', 'gacchantam eva taṃ dṛṣṭvā rāmaṃ saṃbhrāntamānasāḥ
ūcuḥ paramasaṃtaptā rāmaṃ vākyam idaṃ dvijāḥ', null, 2040018),
('ramayana-2-40-19', 19, 'Ayodhya Kanda, Sarga 40, Verse 19', 'ब्राह्मण्यं कृत्स्नमेतत्त्वां ब्रह्मण्यमनुगच्छति।
द्विजस्कन्धाधिरूढास्त्वामग्नयोऽप्यनुयान्त्यमी॥', 'brāhmaṇyaṃ kṛtsnam etat tvāṃ brahmaṇyam anugacchati
dvijaskandhādhirūḍhās tvām agnayo ''py anuyānty amī', null, 2040019),
('ramayana-2-40-20', 20, 'Ayodhya Kanda, Sarga 40, Verse 20', 'वाजपेयसमुत्थानि छत्राण्येतानि पश्य नः।
पृष्ठतोऽनुप्रयातानि हंसानिव जलात्यये॥', 'vājapeyasamutthāni chatrāṇy etāni paśya naḥ
pṛṣṭhato ''nuprayātāni haṃsān iva jalātyaye', null, 2040020),
('ramayana-2-40-21', 21, 'Ayodhya Kanda, Sarga 40, Verse 21', 'अनवाप्तातपत्रस्य रश्मिसंतापितस्य ते।
एभिश्छायां करिष्यामः स्वैश्छत्रैर्वाजपेयिकैः॥', 'anavāptātapatrasya raśmisaṃtāpitasya te
ebhiś chāyāṃ kariṣyāmaḥ svaiś chatrair vājapeyikaiḥ', null, 2040021),
('ramayana-2-40-22', 22, 'Ayodhya Kanda, Sarga 40, Verse 22', 'या हि नः सततं बुद्धिर्वेदमन्त्रानुसारिणी।
त्वत्कृते सा कृता वत्स वनवासानुसारिणी॥', 'yā hi naḥ satataṃ buddhir vedamantrānusāriṇī
tvatkṛte sā kṛtā vatsa vanavāsānusāriṇī', null, 2040022),
('ramayana-2-40-23', 23, 'Ayodhya Kanda, Sarga 40, Verse 23', 'हृदयेष्ववतिष्ठन्ते वेदा ये नः परं धनम्।
वत्स्यन्त्यपि गृहेष्वेव दाराश्चारित्ररक्षिताः॥', 'hṛdayeṣv avatiṣṭhante vedā ye naḥ paraṃ dhanam
vatsyanty api gṛheṣv eva dārāś cāritrarakṣitāḥ', null, 2040023),
('ramayana-2-40-24', 24, 'Ayodhya Kanda, Sarga 40, Verse 24', 'न पुनर्निश्चयः कार्यस्त्वद्गतौ सुकृता मतिः।
त्वयि धर्मव्यपेक्षे तु किं स्याद्धर्ममवेक्षितुम्॥', 'na punar niścayaḥ kāryas tvadgatau sukṛtā matiḥ
tvayi dharmavyapekṣe tu kiṃ syād dharmam avekṣitum', null, 2040024),
('ramayana-2-40-25', 25, 'Ayodhya Kanda, Sarga 40, Verse 25', 'याचितो नो निवर्तस्व हंसशुक्लशिरोरुहैः।
शिरोभिर्निभृताचार महीपतनपांशुलैः॥', 'yācito no nivartasva haṃsaśuklaśiroruhaiḥ
śirobhir nibhṛtācāra mahīpatanapāṃśulaiḥ', null, 2040025),
('ramayana-2-40-26', 26, 'Ayodhya Kanda, Sarga 40, Verse 26', 'बहूनां वितता यज्ञा द्विजानां य इहागताः।
तेषां समाप्तिरायत्ता तव वत्स निवर्तने॥', 'bahūnāṃ vitatā yajñā dvijānāṃ ya ihāgatāḥ
teṣāṃ samāptir āyattā tava vatsa nivartane', null, 2040026),
('ramayana-2-40-27', 27, 'Ayodhya Kanda, Sarga 40, Verse 27', 'भक्तिमन्ति हि भूतानि जंगमाजंगमानि च।
याचमानेषु तेषु त्वं भक्तिं भक्तेषु दर्शय॥', 'bhaktimanti hi bhūtāni jaṃgamājaṃgamāni ca
yācamāneṣu teṣu tvaṃ bhaktiṃ bhakteṣu darśaya', null, 2040027),
('ramayana-2-40-28', 28, 'Ayodhya Kanda, Sarga 40, Verse 28', 'अनुगंतुमशक्तास्त्वां मूलैरुद्धृतवेगिभिः।
उन्नता वायुवेगेन विक्रोशन्तीव पादपाः॥', 'anugaṃtum aśaktās tvāṃ mūlair uddhṛtavegibhiḥ
unnatā vāyuvegena vikrośantīva pādapāḥ', null, 2040028),
('ramayana-2-40-29', 29, 'Ayodhya Kanda, Sarga 40, Verse 29', 'निश्चेष्टाहारसंचारा वृक्षैकस्थानविष्ठिताः।
पक्षिणोऽपि प्रयाचन्ते सर्वभूतानुकम्पिनम्॥', 'niśceṣṭāhārasaṃcārā vṛkṣaikasthānaviṣṭhitāḥ
pakṣiṇo ''pi prayācante sarvabhūtānukampinam', null, 2040029),
('ramayana-2-40-30', 30, 'Ayodhya Kanda, Sarga 40, Verse 30', 'एवं विक्रोशतां तेषां द्विजातीनां निवर्तने।
ददृशे तमसा तत्र वारयन्तीव राघवम्॥', 'evaṃ vikrośatāṃ teṣāṃ dvijātīnāṃ nivartane
dadṛśe tamasā tatra vārayantīva rāghavam', null, 2040030)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 41 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-41-1', 1, 'Ayodhya Kanda, Sarga 41, Verse 1', 'ततस्तु तमसा तीरं रम्यमाश्रित्य राघवः।
सीतामुद्वीक्ष्य सौमित्रिमिदं वचनमब्रवीत्॥', 'tatas tu tamasā tīraṃ ramyam āśritya rāghavaḥ
sītām udvīkṣya saumitrim idaṃ vacanam abravīt', null, 2041001),
('ramayana-2-41-2', 2, 'Ayodhya Kanda, Sarga 41, Verse 2', 'इयमद्य निशा पूर्वा सौमित्रे प्रस्थिता वनम्।
वनवासस्य भद्रं ते स नोत्कण्ठितुमर्हसि॥', 'iyam adya niśā pūrvā saumitre prasthitā vanam
vanavāsasya bhadraṃ te sa notkaṇṭhitum arhasi', null, 2041002),
('ramayana-2-41-3', 3, 'Ayodhya Kanda, Sarga 41, Verse 3', 'पश्य शून्यान्यरण्यानि रुदन्तीव समन्ततः।
यथानिलयमायद्भिर्निलीनानि मृगद्विजैः॥', 'paśya śūnyāny araṇyāni rudantīva samantataḥ
yathānilayam āyadbhir nilīnāni mṛgadvijaiḥ', null, 2041003),
('ramayana-2-41-4', 4, 'Ayodhya Kanda, Sarga 41, Verse 4', 'अद्यायोध्या तु नगरी राजधानी पितुर्मम।
सस्त्रीपुंसा गतानस्माञ्शोचिष्यति न संशयः॥', 'adyāyodhyā tu nagarī rājadhānī pitur mama
sastrīpuṃsā gatān asmāñ śociṣyati na saṃśayaḥ', null, 2041004),
('ramayana-2-41-5', 5, 'Ayodhya Kanda, Sarga 41, Verse 5', 'भरतः खलु धर्मात्मा पितरं मातरं च मे।
धर्मार्थकामसहितैर्वाक्यैराश्वासयिष्यति॥', 'bharataḥ khalu dharmātmā pitaraṃ mātaraṃ ca me
dharmārthakāmasahitair vākyair āśvāsayiṣyati', null, 2041005),
('ramayana-2-41-6', 6, 'Ayodhya Kanda, Sarga 41, Verse 6', 'भरतस्यानृशंसत्वं संचिन्त्याहं पुनः पुनः।
नानुशोचामि पितरं मातरं चापि लक्ष्मण॥', 'bharatasyānṛśaṃsatvaṃ saṃcintyāhaṃ punaḥ punaḥ
nānuśocāmi pitaraṃ mātaraṃ cāpi lakṣmaṇa', null, 2041006),
('ramayana-2-41-7', 7, 'Ayodhya Kanda, Sarga 41, Verse 7', 'त्वया कार्यं नरव्याघ्र मामनुव्रजता कृतम्।
अन्वेष्टव्या हि वैदेह्या रक्षणार्थे सहायता॥', 'tvayā kāryaṃ naravyāghra mām anuvrajatā kṛtam
anveṣṭavyā hi vaidehyā rakṣaṇārthe sahāyatā', null, 2041007),
('ramayana-2-41-8', 8, 'Ayodhya Kanda, Sarga 41, Verse 8', 'अद्भिरेव तु सौमित्रे वत्स्याम्यद्य निशामिमाम्।
एतद्धि रोचते मह्यं वन्येऽपि विविधे सति॥', 'adbhir eva tu saumitre vatsyāmy adya niśām imām
etad dhi rocate mahyaṃ vanye ''pi vividhe sati', null, 2041008),
('ramayana-2-41-9', 9, 'Ayodhya Kanda, Sarga 41, Verse 9', 'एवमुक्त्वा तु सौमित्रं सुमन्त्रमपि राघवः।
अप्रमत्तस्त्वमश्वेषु भव सौम्येत्युवाच ह॥', 'evam uktvā tu saumitraṃ sumantram api rāghavaḥ
apramattas tvam aśveṣu bhava saumyety uvāca ha', null, 2041009),
('ramayana-2-41-10', 10, 'Ayodhya Kanda, Sarga 41, Verse 10', 'सोऽश्वान्सुमन्त्रः संयम्य सूर्येऽस्तं समुपागते।
प्रभूतयवसान्कृत्वा बभूव प्रत्यनन्तरः॥', 'so ''śvān sumantraḥ saṃyamya sūrye ''staṃ samupāgate
prabhūtayavasān kṛtvā babhūva pratyanantaraḥ', null, 2041010),
('ramayana-2-41-11', 11, 'Ayodhya Kanda, Sarga 41, Verse 11', 'उपास्यतु शिवां संध्यां दृष्ट्वा रात्रिमुपस्थिताम्।
रामस्य शयनं चक्रे सूतः सौमित्रिणा सह॥', 'upāsyatu śivāṃ saṃdhyāṃ dṛṣṭvā rātrim upasthitām
rāmasya śayanaṃ cakre sūtaḥ saumitriṇā saha', null, 2041011),
('ramayana-2-41-12', 12, 'Ayodhya Kanda, Sarga 41, Verse 12', 'तां शय्यां तमसातीरे वीक्ष्य वृक्षदलैः कृताम्।
रामः सौमित्रिणां सार्धं सभार्यः संविवेश ह॥', 'tāṃ śayyāṃ tamasātīre vīkṣya vṛkṣadalaiḥ kṛtām
rāmaḥ saumitriṇāṃ sārdhaṃ sabhāryaḥ saṃviveśa ha', null, 2041012),
('ramayana-2-41-13', 13, 'Ayodhya Kanda, Sarga 41, Verse 13', 'सभार्यं संप्रसुप्तं तं भ्रातरं वीक्ष्य लक्ष्मणः।
कथयामास सूताय रामस्य विविधान्गुणान्॥', 'sabhāryaṃ saṃprasuptaṃ taṃ bhrātaraṃ vīkṣya lakṣmaṇaḥ
kathayām āsa sūtāya rāmasya vividhān guṇān', null, 2041013),
('ramayana-2-41-14', 14, 'Ayodhya Kanda, Sarga 41, Verse 14', 'जाग्रतो ह्येव तां रात्रिं सौमित्रेरुदितो रविः।
सूतस्य तमसातीरे रामस्य ब्रुवतो गुणान्॥', 'jāgrato hy eva tāṃ rātriṃ saumitrer udito raviḥ
sūtasya tamasātīre rāmasya bruvato guṇān', null, 2041014),
('ramayana-2-41-15', 15, 'Ayodhya Kanda, Sarga 41, Verse 15', 'गोकुलाकुलतीरायास्तमसाया विदूरतः।
अवसत्तत्र तां रात्रिं रामः प्रकृतिभिः सह॥', 'gokulākulatīrāyās tamasāyā vidūrataḥ
avasat tatra tāṃ rātriṃ rāmaḥ prakṛtibhiḥ saha', null, 2041015),
('ramayana-2-41-16', 16, 'Ayodhya Kanda, Sarga 41, Verse 16', 'उत्थाय तु महातेजाः प्रकृतीस्ता निशाम्य च।
अब्रवीद्भ्रातरं रामो लक्ष्मणं पुण्यलक्षणम्॥', 'utthāya tu mahātejāḥ prakṛtīs tā niśāmya ca
abravīd bhrātaraṃ rāmo lakṣmaṇaṃ puṇyalakṣaṇam', null, 2041016),
('ramayana-2-41-17', 17, 'Ayodhya Kanda, Sarga 41, Verse 17', 'अस्मद्व्यपेक्षान्सौमित्रे निरपेक्षान्गृहेष्वपि।
वृक्षमूलेषु संसुप्तान्पश्य लक्ष्मण साम्प्रतम्॥', 'asmadvyapekṣān saumitre nirapekṣān gṛheṣv api
vṛkṣamūleṣu saṃsuptān paśya lakṣmaṇa sāmpratam', null, 2041017),
('ramayana-2-41-18', 18, 'Ayodhya Kanda, Sarga 41, Verse 18', 'यथैते नियमं पौराः कुर्वन्त्यस्मन्निवर्तने।
अपि प्राणानसिष्यन्ति न तु त्यक्ष्यन्ति निश्चयम्॥', 'yathaite niyamaṃ paurāḥ kurvanty asmannivartane
api prāṇān asiṣyanti na tu tyakṣyanti niścayam', null, 2041018),
('ramayana-2-41-19', 19, 'Ayodhya Kanda, Sarga 41, Verse 19', 'यावदेव तु संसुप्तास्तावदेव वयं लघु।
रथमारुह्य गच्छामः पन्थानमकुतोभयम्॥', 'yāvad eva tu saṃsuptās tāvad eva vayaṃ laghu
ratham āruhya gacchāmaḥ panthānam akutobhayam', null, 2041019),
('ramayana-2-41-20', 20, 'Ayodhya Kanda, Sarga 41, Verse 20', 'अतो भूयोऽपि नेदानीमिक्ष्वाकुपुरवासिनः।
स्वपेयुरनुरक्ता मां वृक्षमूलानि संश्रिताः॥', 'ato bhūyo ''pi nedānīm ikṣvākupuravāsinaḥ
svapeyur anuraktā māṃ vṛkṣamūlāni saṃśritāḥ', null, 2041020),
('ramayana-2-41-21', 21, 'Ayodhya Kanda, Sarga 41, Verse 21', 'पौरा ह्यात्मकृताद्दुःखाद्विप्रमोच्या नृपात्मजैः।
न तु खल्वात्मना योज्या दुःखेन पुरवासिनः॥', 'paurā hy ātmakṛtād duḥkhād vipramocyā nṛpātmajaiḥ
na tu khalv ātmanā yojyā duḥkhena puravāsinaḥ', null, 2041021),
('ramayana-2-41-22', 22, 'Ayodhya Kanda, Sarga 41, Verse 22', 'अब्रवील्लक्ष्मणो रामं साक्षाद्धर्ममिव स्थितम्।
रोचते मे महाप्राज्ञ क्षिप्रमारुह्यतामिति॥', 'abravīl lakṣmaṇo rāmaṃ sākṣād dharmam iva sthitam
rocate me mahāprājña kṣipram āruhyatām iti', null, 2041022),
('ramayana-2-41-23', 23, 'Ayodhya Kanda, Sarga 41, Verse 23', 'सूतस्ततः संत्वरितः स्यन्दनं तैर्हयोत्तमैः।
योजयित्वाथ रामाय प्राञ्जलिः प्रत्यवेदयत्॥', 'sūtas tataḥ saṃtvaritaḥ syandanaṃ tair hayottamaiḥ
yojayitvātha rāmāya prāñjaliḥ pratyavedayat', null, 2041023),
('ramayana-2-41-24', 24, 'Ayodhya Kanda, Sarga 41, Verse 24', 'मोहनार्थं तु पौराणां सूतं रामोऽब्रवीद्वचः।
उदङ्मुखः प्रयाहि त्वं रथमास्थाय सारथे॥', 'mohanārthaṃ tu paurāṇāṃ sūtaṃ rāmo ''bravīd vacaḥ
udaṅmukhaḥ prayāhi tvaṃ ratham āsthāya sārathe', null, 2041024),
('ramayana-2-41-25', 25, 'Ayodhya Kanda, Sarga 41, Verse 25', 'मुहूर्तं त्वरितं गत्वा निर्गतय रथं पुनः।
यथा न विद्युः पौरा मां तथा कुरु समाहितः॥', 'muhūrtaṃ tvaritaṃ gatvā nirgataya rathaṃ punaḥ
yathā na vidyuḥ paurā māṃ tathā kuru samāhitaḥ', null, 2041025),
('ramayana-2-41-26', 26, 'Ayodhya Kanda, Sarga 41, Verse 26', 'रामस्य वचनं श्रुत्वा तथा चक्रे स सारथिः।
प्रत्यागम्य च रामस्य स्यन्दनं प्रत्यवेदयत्॥', 'rāmasya vacanaṃ śrutvā tathā cakre sa sārathiḥ
pratyāgamya ca rāmasya syandanaṃ pratyavedayat', null, 2041026),
('ramayana-2-41-27', 27, 'Ayodhya Kanda, Sarga 41, Verse 27', 'तं स्यन्दनमधिष्ठाय राघवः सपरिच्छदः।
शीघ्रगामाकुलावर्तां तमसामतरन्नदीम्॥', 'taṃ syandanam adhiṣṭhāya rāghavaḥ saparicchadaḥ
śīghragām ākulāvartāṃ tamasām ataran nadīm', null, 2041027),
('ramayana-2-41-28', 28, 'Ayodhya Kanda, Sarga 41, Verse 28', 'स संतीर्य महाबाहुः श्रीमाञ्शिवमकण्टकम्।
प्रापद्यत महामार्गमभयं भयदर्शिनाम्॥', 'sa saṃtīrya mahābāhuḥ śrīmāñ śivam akaṇṭakam
prāpadyata mahāmārgam abhayaṃ bhayadarśinām', null, 2041028),
('ramayana-2-41-29', 29, 'Ayodhya Kanda, Sarga 41, Verse 29', 'प्रभातायां तु शर्वर्यां पौरास्ते राघवो विना।
शोकोपहतनिश्चेष्टा बभूवुर्हतचेतसः॥', 'prabhātāyāṃ tu śarvaryāṃ paurās te rāghavo vinā
śokopahataniśceṣṭā babhūvur hatacetasaḥ', null, 2041029),
('ramayana-2-41-30', 30, 'Ayodhya Kanda, Sarga 41, Verse 30', 'शोकजाश्रुपरिद्यूना वीक्षमाणास्ततस्ततः।
आलोकमपि रामस्य न पश्यन्ति स्म दुःखिताः॥', 'śokajāśruparidyūnā vīkṣamāṇās tatas tataḥ
ālokam api rāmasya na paśyanti sma duḥkhitāḥ', null, 2041030),
('ramayana-2-41-31', 31, 'Ayodhya Kanda, Sarga 41, Verse 31', 'ततो मार्गानुसारेण गत्वा किं चित्क्षणं पुनः।
मार्गनाशाद्विषादेन महता समभिप्लुतः॥', 'tato mārgānusāreṇa gatvā kiṃ cit kṣaṇaṃ punaḥ
mārganāśād viṣādena mahatā samabhiplutaḥ', null, 2041031),
('ramayana-2-41-32', 32, 'Ayodhya Kanda, Sarga 41, Verse 32', 'रथस्य मार्गनाशेन न्यवर्तन्त मनस्विनः।
किमिदं किं करिष्यामो दैवेनोपहता इति॥', 'rathasya mārganāśena nyavartanta manasvinaḥ
kim idaṃ kiṃ kariṣyāmo daivenopahatā iti', null, 2041032),
('ramayana-2-41-33', 33, 'Ayodhya Kanda, Sarga 41, Verse 33', 'ततो यथागतेनैव मार्गेण क्लान्तचेतसः।
अयोध्यामगमन्सर्वे पुरीं व्यथितसज्जनाम्॥', 'tato yathāgatenaiva mārgeṇa klāntacetasaḥ
ayodhyām agaman sarve purīṃ vyathitasajjanām', null, 2041033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 42 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-42-1', 1, 'Ayodhya Kanda, Sarga 42, Verse 1', 'अनुगम्य निवृत्तानां रामं नगरवासिनाम्।
उद्गतानीव सत्त्वानि बभूवुरमनस्विनाम्॥', 'anugamya nivṛttānāṃ rāmaṃ nagaravāsinām
udgatānīva sattvāni babhūvur amanasvinām', null, 2042001),
('ramayana-2-42-2', 2, 'Ayodhya Kanda, Sarga 42, Verse 2', 'स्वं स्वं निलयमागम्य पुत्रदारैः समावृताः।
अश्रूणि मुमुचुः सर्वे बाष्पेण पिहिताननाः॥', 'svaṃ svaṃ nilayam āgamya putradāraiḥ samāvṛtāḥ
aśrūṇi mumucuḥ sarve bāṣpeṇa pihitānanāḥ', null, 2042002),
('ramayana-2-42-3', 3, 'Ayodhya Kanda, Sarga 42, Verse 3', 'न चाहृष्यन्न चामोदन्वणिजो न प्रसारयन्।
न चाशोभन्त पण्यानि नापचन्गृहमेधिनः॥', 'na cāhṛṣyan na cāmodan vaṇijo na prasārayan
na cāśobhanta paṇyāni nāpacan gṛhamedhinaḥ', null, 2042003),
('ramayana-2-42-4', 4, 'Ayodhya Kanda, Sarga 42, Verse 4', 'नष्टं दृष्ट्वा नाभ्यनन्दन्विपुलं वा धनागमम्।
पुत्रं प्रथमजं लब्ध्वा जननी नाभ्यनन्दत॥', 'naṣṭaṃ dṛṣṭvā nābhyanandan vipulaṃ vā dhanāgamam
putraṃ prathamajaṃ labdhvā jananī nābhyanandata', null, 2042004),
('ramayana-2-42-5', 5, 'Ayodhya Kanda, Sarga 42, Verse 5', 'गृहे गृहे रुदन्त्यश्च भर्तारं गृहमागतम्।
व्यगर्हयन्तो दुःखार्ता वाग्भिस्तोत्रैरिव द्विपान्॥', 'gṛhe gṛhe rudantyaś ca bhartāraṃ gṛham āgatam
vyagarhayanto duḥkhārtā vāgbhis totrair iva dvipān', null, 2042005),
('ramayana-2-42-6', 6, 'Ayodhya Kanda, Sarga 42, Verse 6', 'किं नु तेषां गृहैः कार्यं किं दारैः किं धनेन वा।
पुत्रैर्वा किं सुखैर्वापि ये न पश्यन्ति राघवम्॥', 'kiṃ nu teṣāṃ gṛhaiḥ kāryaṃ kiṃ dāraiḥ kiṃ dhanena vā
putrair vā kiṃ sukhair vāpi ye na paśyanti rāghavam', null, 2042006),
('ramayana-2-42-7', 7, 'Ayodhya Kanda, Sarga 42, Verse 7', 'एकः सत्पुरुषो लोके लक्ष्मणः सह सीतया।
योऽनुगच्छति काकुत्स्थं रामं परिचरन्वने॥', 'ekaḥ satpuruṣo loke lakṣmaṇaḥ saha sītayā
yo ''nugacchati kākutsthaṃ rāmaṃ paricaran vane', null, 2042007),
('ramayana-2-42-8', 8, 'Ayodhya Kanda, Sarga 42, Verse 8', 'आपगाः कृतपुण्यास्ताः पद्मिन्यश्च सरांसि च।
येषु स्नास्यति काकुत्स्थो विगाह्य सलिलं शुचि॥', 'āpagāḥ kṛtapuṇyās tāḥ padminyaś ca sarāṃsi ca
yeṣu snāsyati kākutstho vigāhya salilaṃ śuci', null, 2042008),
('ramayana-2-42-9', 9, 'Ayodhya Kanda, Sarga 42, Verse 9', 'शोभयिष्यन्ति काकुत्स्थमटव्यो रम्यकाननाः।
आपगाश्च महानूपाः सानुमन्तश्च पर्वताः॥', 'śobhayiṣyanti kākutstham aṭavyo ramyakānanāḥ
āpagāś ca mahānūpāḥ sānumantaś ca parvatāḥ', null, 2042009),
('ramayana-2-42-10', 10, 'Ayodhya Kanda, Sarga 42, Verse 10', 'काननं वापि शैलं वा यं रामोऽभिगमिष्यति।
प्रियातिथिमिव प्राप्तं नैनं शक्ष्यन्त्यनर्चितुम्॥', 'kānanaṃ vāpi śailaṃ vā yaṃ rāmo ''bhigamiṣyati
priyātithim iva prāptaṃ nainaṃ śakṣyanty anarcitum', null, 2042010),
('ramayana-2-42-11', 11, 'Ayodhya Kanda, Sarga 42, Verse 11', 'विचित्रकुसुमापीडा बहुमञ्जरिधारिणः।
अकाले चापि मुख्यानि पुष्पाणि च फलानि च।
दर्शयिष्यन्त्यनुक्रोशाद्गिरयो राममागतम्॥', 'vicitrakusumāpīḍā bahumañjaridhāriṇaḥ
akāle cāpi mukhyāni puṣpāṇi ca phalāni ca
darśayiṣyanty anukrośād girayo rāmam āgatam', null, 2042011),
('ramayana-2-42-12', 12, 'Ayodhya Kanda, Sarga 42, Verse 12', 'विदर्शयन्तो विविधान्भूयश्चित्रांश्च निर्झरान्।
पादपाः पर्वताग्रेषु रमयिष्यन्ति राघवम्॥', 'vidarśayanto vividhān bhūyaś citrāṃś ca nirjharān
pādapāḥ parvatāgreṣu ramayiṣyanti rāghavam', null, 2042012),
('ramayana-2-42-13', 13, 'Ayodhya Kanda, Sarga 42, Verse 13', 'यत्र रामो भयं नात्र नास्ति तत्र पराभवः।
स हि शूरो महाबाहुः पुत्रो दशरथस्य च॥', 'yatra rāmo bhayaṃ nātra nāsti tatra parābhavaḥ
sa hi śūro mahābāhuḥ putro daśarathasya ca', null, 2042013),
('ramayana-2-42-14', 14, 'Ayodhya Kanda, Sarga 42, Verse 14', 'पुरा भवति नो दूरादनुगच्छाम राघवम्।
पादच्छाया सुखा भर्तुस्तादृशस्य महात्मनः।
स हि नाथो जनस्यास्य स गतिः स परायणम्॥', 'purā bhavati no dūrād anugacchāma rāghavam
pādacchāyā sukhā bhartus tādṛśasya mahātmanaḥ
sa hi nātho janasyāsya sa gatiḥ sa parāyaṇam', null, 2042014),
('ramayana-2-42-15', 15, 'Ayodhya Kanda, Sarga 42, Verse 15', 'वयं परिचरिष्यामः सीतां यूयं तु राघवम्।
इति पौरस्त्रियो भर्तॄन्दुःखार्तास्तत्तदब्रुवन्॥', 'vayaṃ paricariṣyāmaḥ sītāṃ yūyaṃ tu rāghavam
iti paurastriyo bhartṝn duḥkhārtās tat tad abruvan', null, 2042015),
('ramayana-2-42-16', 16, 'Ayodhya Kanda, Sarga 42, Verse 16', 'युष्माकं राघवोऽरण्ये योगक्षेमं विधास्यति।
सीता नारीजनस्यास्य योगक्षेमं करिष्यति॥', 'yuṣmākaṃ rāghavo ''raṇye yogakṣemaṃ vidhāsyati
sītā nārījanasyāsya yogakṣemaṃ kariṣyati', null, 2042016),
('ramayana-2-42-17', 17, 'Ayodhya Kanda, Sarga 42, Verse 17', 'को न्वनेनाप्रतीतेन सोत्कण्ठितजनेन च।
संप्रीयेतामनोज्ञेन वासेन हृतचेतसा॥', 'ko nv anenāpratītena sotkaṇṭhitajanena ca
saṃprīyetāmanojñena vāsena hṛtacetasā', null, 2042017),
('ramayana-2-42-18', 18, 'Ayodhya Kanda, Sarga 42, Verse 18', 'कैकेय्या यदि चेद्राज्यं स्यादधर्म्यमनाथवत्।
न हि नो जीवितेनार्थः कुतः पुत्रैः कुतो धनैः॥', 'kaikeyyā yadi ced rājyaṃ syād adharmyam anāthavat
na hi no jīvitenārthaḥ kutaḥ putraiḥ kuto dhanaiḥ', null, 2042018),
('ramayana-2-42-19', 19, 'Ayodhya Kanda, Sarga 42, Verse 19', 'यया पुत्रश्च भर्ता च त्यक्तावैश्वर्यकारणात्।
कं सा परिहरेदन्यं कैकेयी कुलपांसनी॥', 'yayā putraś ca bhartā ca tyaktāv aiśvaryakāraṇāt
kaṃ sā parihared anyaṃ kaikeyī kulapāṃsanī', null, 2042019),
('ramayana-2-42-20', 20, 'Ayodhya Kanda, Sarga 42, Verse 20', 'कैकेय्या न वयं राज्ये भृतका निवसेमहि।
जीवन्त्या जातु जीवन्त्यः पुत्रैरपि शपामहे॥', 'kaikeyyā na vayaṃ rājye bhṛtakā nivasemahi
jīvantyā jātu jīvantyaḥ putrair api śapāmahe', null, 2042020),
('ramayana-2-42-21', 21, 'Ayodhya Kanda, Sarga 42, Verse 21', 'या पुत्रं पार्थिवेन्द्रस्य प्रवासयति निर्घृणा।
कस्तां प्राप्य सुखं जीवेदधर्म्यां दुष्टचारिणीम्॥', 'yā putraṃ pārthivendrasya pravāsayati nirghṛṇā
kas tāṃ prāpya sukhaṃ jīved adharmyāṃ duṣṭacāriṇīm', null, 2042021),
('ramayana-2-42-22', 22, 'Ayodhya Kanda, Sarga 42, Verse 22', 'न हि प्रव्रजिते रामे जीविष्यति महीपतिः।
मृते दशरथे व्यक्तं विलोपस्तदनन्तरम्॥', 'na hi pravrajite rāme jīviṣyati mahīpatiḥ
mṛte daśarathe vyaktaṃ vilopas tadanantaram', null, 2042022),
('ramayana-2-42-23', 23, 'Ayodhya Kanda, Sarga 42, Verse 23', 'ते विषं पिबतालोड्य क्षीणपुण्याः सुदुर्गताः।
राघवं वानुगच्छध्वमश्रुतिं वापि गच्छत॥', 'te viṣaṃ pibatāloḍya kṣīṇapuṇyāḥ sudurgatāḥ
rāghavaṃ vānugacchadhvam aśrutiṃ vāpi gacchata', null, 2042023),
('ramayana-2-42-24', 24, 'Ayodhya Kanda, Sarga 42, Verse 24', 'मिथ्या प्रव्राजितो रामः सभार्यः सहलक्ष्मणः।
भरते संनिषृष्टाः स्मः सौनिके पशवो यथा॥', 'mithyā pravrājito rāmaḥ sabhāryaḥ sahalakṣmaṇaḥ
bharate saṃniṣṛṣṭāḥ smaḥ saunike paśavo yathā', null, 2042024),
('ramayana-2-42-25', 25, 'Ayodhya Kanda, Sarga 42, Verse 25', 'तास्तथा विलपन्त्यस्तु नगरे नागरस्त्रियः।
चुक्रुशुर्भृशसंतप्ता मृत्योरिव भयागमे॥', 'tās tathā vilapantyas tu nagare nāgarastriyaḥ
cukruśur bhṛśasaṃtaptā mṛtyor iva bhayāgame', null, 2042025),
('ramayana-2-42-26', 26, 'Ayodhya Kanda, Sarga 42, Verse 26', 'तथा स्त्रियो रामनिमित्तमातुरा यथा सुते भ्रातरि वा विवासिते।
विलप्य दीना रुरुदुर्विचेतसः सुतैर्हि तासामधिको हि सोऽभवत्॥', 'tathā striyo rāmanimittam āturā yathā sute bhrātari vā vivāsite
vilapya dīnā rurudur vicetasaḥ sutair hi tāsām adhiko hi so ''bhavat', null, 2042026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 43 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-43-1', 1, 'Ayodhya Kanda, Sarga 43, Verse 1', 'रामोऽपि रात्रिशेषेण तेनैव महदन्तरम्।
जगाम पुरुषव्याघ्रः पितुराज्ञामनुस्मरन्॥', 'rāmo ''pi rātriśeṣeṇa tenaiva mahad antaram
jagāma puruṣavyāghraḥ pitur ājñām anusmaran', null, 2043001),
('ramayana-2-43-2', 2, 'Ayodhya Kanda, Sarga 43, Verse 2', 'तथैव गच्छतस्तस्य व्यपायाद्रजनी शिवा।
उपास्य स शिवां संध्यां विषयान्तं व्यगाहत॥', 'tathaiva gacchatas tasya vyapāyād rajanī śivā
upāsya sa śivāṃ saṃdhyāṃ viṣayāntaṃ vyagāhata', null, 2043002),
('ramayana-2-43-3', 3, 'Ayodhya Kanda, Sarga 43, Verse 3', 'ग्रामान्विकृष्टसीमांस्तान्पुष्पितानि वनानि च।
पश्यन्नतिययौ शीघ्रं शरैरिव हयोत्तमैः॥', 'grāmān vikṛṣṭasīmāṃs tān puṣpitāni vanāni ca
paśyann atiyayau śīghraṃ śarair iva hayottamaiḥ', null, 2043003),
('ramayana-2-43-4', 4, 'Ayodhya Kanda, Sarga 43, Verse 4', 'शृण्वन्वाचो मनुष्याणां ग्रामसंवासवासिनाम्।
राजानं धिग्दशरथं कामस्य वशमागतम्॥', 'śṛṇvan vāco manuṣyāṇāṃ grāmasaṃvāsavāsinām
rājānaṃ dhig daśarathaṃ kāmasya vaśam āgatam', null, 2043004),
('ramayana-2-43-5', 5, 'Ayodhya Kanda, Sarga 43, Verse 5', 'हा नृशंसाद्य कैकेयी पापा पापानुबन्धिनी।
तीक्ष्णा संभिन्नमर्यादा तीक्ष्णे कर्मणि वर्तते॥', 'hā nṛśaṃsādya kaikeyī pāpā pāpānubandhinī
tīkṣṇā saṃbhinnamaryādā tīkṣṇe karmaṇi vartate', null, 2043005),
('ramayana-2-43-6', 6, 'Ayodhya Kanda, Sarga 43, Verse 6', 'या पुत्रमीदृशं राज्ञः प्रवासयति धार्मिकम्।
वन वासे महाप्राज्ञं सानुक्रोशमतन्द्रितम्॥', 'yā putram īdṛśaṃ rājñaḥ pravāsayati dhārmikam
vana vāse mahāprājñaṃ sānukrośam atandritam', null, 2043006),
('ramayana-2-43-7', 7, 'Ayodhya Kanda, Sarga 43, Verse 7', 'एता वाचो मनुष्याणां ग्रामसंवासवासिनाम्।
शृण्वन्नतिययौ वीरः कोसलान्कोसलेश्वरः॥', 'etā vāco manuṣyāṇāṃ grāmasaṃvāsavāsinām
śṛṇvann atiyayau vīraḥ kosalān kosaleśvaraḥ', null, 2043007),
('ramayana-2-43-8', 8, 'Ayodhya Kanda, Sarga 43, Verse 8', 'ततो वेदश्रुतिं नाम शिववारिवहां नदीम्।
उत्तीर्याभिमुखः प्रायादगस्त्याध्युषितां दिशम्॥', 'tato vedaśrutiṃ nāma śivavārivahāṃ nadīm
uttīryābhimukhaḥ prāyād agastyādhyuṣitāṃ diśam', null, 2043008),
('ramayana-2-43-9', 9, 'Ayodhya Kanda, Sarga 43, Verse 9', 'गत्वा तु सुचिरं कालं ततः शीतजलां नदीम्।
गोमतीं गोयुतानूपामतरत्सागरंगमाम्॥', 'gatvā tu suciraṃ kālaṃ tataḥ śītajalāṃ nadīm
gomatīṃ goyutānūpām atarat sāgaraṃgamām', null, 2043009),
('ramayana-2-43-10', 10, 'Ayodhya Kanda, Sarga 43, Verse 10', 'गोमतीं चाप्यतिक्रम्य राघवः शीघ्रगैर्हयैः।
मयूरहंसाभिरुतां ततार स्यन्दिकां नदीम्॥', 'gomatīṃ cāpy atikramya rāghavaḥ śīghragair hayaiḥ
mayūrahaṃsābhirutāṃ tatāra syandikāṃ nadīm', null, 2043010),
('ramayana-2-43-11', 11, 'Ayodhya Kanda, Sarga 43, Verse 11', 'स महीं मनुना राज्ञा दत्तामिक्ष्वाकवे पुरा।
स्फीतां राष्ट्रावृतां रामो वैदेहीमन्वदर्शयत्॥', 'sa mahīṃ manunā rājñā dattām ikṣvākave purā
sphītāṃ rāṣṭrāvṛtāṃ rāmo vaidehīm anvadarśayat', null, 2043011),
('ramayana-2-43-12', 12, 'Ayodhya Kanda, Sarga 43, Verse 12', 'सूत इत्येव चाभाष्य सारथिं तमभीक्ष्णशः।
हंसमत्तस्वरः श्रीमानुवाच पुरुषर्षभः॥', 'sūta ity eva cābhāṣya sārathiṃ tam abhīkṣṇaśaḥ
haṃsamattasvaraḥ śrīmān uvāca puruṣarṣabhaḥ', null, 2043012),
('ramayana-2-43-13', 13, 'Ayodhya Kanda, Sarga 43, Verse 13', 'कदाहं पुनरागम्य सरय्वाः पुष्पिते वने।
मृगयां पर्याटष्यामि मात्रा पित्रा च संगतः॥', 'kadāhaṃ punar āgamya sarayvāḥ puṣpite vane
mṛgayāṃ paryāṭaṣyāmi mātrā pitrā ca saṃgataḥ', null, 2043013),
('ramayana-2-43-14', 14, 'Ayodhya Kanda, Sarga 43, Verse 14', 'नात्यर्थमभिकाङ्क्षामि मृगयां सरयूवने।
रतिर्ह्येषातुला लोके राजर्षिगणसंमता॥', 'nātyartham abhikāṅkṣāmi mṛgayāṃ sarayūvane
ratir hy eṣātulā loke rājarṣigaṇasaṃmatā', null, 2043014),
('ramayana-2-43-15', 15, 'Ayodhya Kanda, Sarga 43, Verse 15', 'स तमध्वानमैक्ष्वाकः सूतं मधुरया गिरा।
तं तमर्थमभिप्रेत्य ययौवाक्यमुदीरयन्॥', 'sa tam adhvānam aikṣvākaḥ sūtaṃ madhurayā girā
taṃ tam artham abhipretya yayauvākyam udīrayan', null, 2043015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 44 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-44-1', 1, 'Ayodhya Kanda, Sarga 44, Verse 1', 'विशालान्कोसलान्रम्यान्यात्वा लक्ष्मणपूर्वजः।
आससाद महाबाहुः शृङ्गवेरपुरं प्रति॥', 'viśālān kosalān ramyān yātvā lakṣmaṇapūrvajaḥ
āsasāda mahābāhuḥ śṛṅgaverapuraṃ prati', null, 2044001),
('ramayana-2-44-2', 2, 'Ayodhya Kanda, Sarga 44, Verse 2', 'तत्र त्रिपथगां दिव्यां शिवतोयामशैवलाम्।
ददर्श राघवो गङ्गां पुण्यामृषिनिसेविताम्॥', 'tatra tripathagāṃ divyāṃ śivatoyām aśaivalām
dadarśa rāghavo gaṅgāṃ puṇyām ṛṣinisevitām', null, 2044002),
('ramayana-2-44-3', 3, 'Ayodhya Kanda, Sarga 44, Verse 3', 'हंससारससंघुष्टां चक्रवाकोपकूजिताम्।
शिंशुमरैश्च नक्रैश्च भुजंगैश्च निषेविताम्॥', 'haṃsasārasasaṃghuṣṭāṃ cakravākopakūjitām
śiṃśumaraiś ca nakraiś ca bhujaṃgaiś ca niṣevitām', null, 2044003),
('ramayana-2-44-4', 4, 'Ayodhya Kanda, Sarga 44, Verse 4', 'तामूर्मिकलिलावर्तामन्ववेक्ष्य महारथः।
सुमन्त्रमब्रवीत्सूतमिहैवाद्य वसामहे॥', 'tām ūrmikalilāvartām anvavekṣya mahārathaḥ
sumantram abravīt sūtam ihaivādya vasāmahe', null, 2044004),
('ramayana-2-44-5', 5, 'Ayodhya Kanda, Sarga 44, Verse 5', 'अविदूरादयं नद्या बहुपुष्पप्रवालवान्।
सुमहानिङ्गुदीवृक्षो वसामोऽत्रैव सारथे॥', 'avidūrād ayaṃ nadyā bahupuṣpapravālavān
sumahān iṅgudīvṛkṣo vasāmo ''traiva sārathe', null, 2044005),
('ramayana-2-44-6', 6, 'Ayodhya Kanda, Sarga 44, Verse 6', 'लक्षणश्च सुमन्त्रश्च बाढमित्येव राघवम्।
उक्त्वा तमिङ्गुदीवृक्षं तदोपययतुर्हयैः॥', 'lakṣaṇaś ca sumantraś ca bāḍham ity eva rāghavam
uktvā tam iṅgudīvṛkṣaṃ tadopayayatur hayaiḥ', null, 2044006),
('ramayana-2-44-7', 7, 'Ayodhya Kanda, Sarga 44, Verse 7', 'रामोऽभियाय तं रम्यं वृक्षमिक्ष्वाकुनन्दनः।
रथादवातरत्तस्मात्सभार्यः सहलक्ष्मणः॥', 'rāmo ''bhiyāya taṃ ramyaṃ vṛkṣam ikṣvākunandanaḥ
rathād avātarat tasmāt sabhāryaḥ sahalakṣmaṇaḥ', null, 2044007),
('ramayana-2-44-8', 8, 'Ayodhya Kanda, Sarga 44, Verse 8', 'सुमन्त्रोऽप्यवतीर्यैव मोचयित्वा हयोत्तमान्।
वृक्षमूलगतं राममुपतस्थे कृताञ्जलिः॥', 'sumantro ''py avatīryaiva mocayitvā hayottamān
vṛkṣamūlagataṃ rāmam upatasthe kṛtāñjaliḥ', null, 2044008),
('ramayana-2-44-9', 9, 'Ayodhya Kanda, Sarga 44, Verse 9', 'तत्र राजा गुहो नाम रामस्यात्मसमः सखा।
निषादजात्यो बलवान्स्थपतिश्चेति विश्रुतः॥', 'tatra rājā guho nāma rāmasyātmasamaḥ sakhā
niṣādajātyo balavān sthapatiś ceti viśrutaḥ', null, 2044009),
('ramayana-2-44-10', 10, 'Ayodhya Kanda, Sarga 44, Verse 10', 'स श्रुत्वा पुरुषव्याघ्रं रामं विषयमागतम्।
वृद्धैः परिवृतोऽमात्यैर्ज्ञातिभिश्चाप्युपागतः॥', 'sa śrutvā puruṣavyāghraṃ rāmaṃ viṣayam āgatam
vṛddhaiḥ parivṛto ''mātyair jñātibhiś cāpy upāgataḥ', null, 2044010),
('ramayana-2-44-11', 11, 'Ayodhya Kanda, Sarga 44, Verse 11', 'ततो निषादाधिपतिं दृष्ट्वा दूरादवस्थितम्।
सह सौमित्रिणा रामः समागच्छद्गुहेन सः॥', 'tato niṣādādhipatiṃ dṛṣṭvā dūrād avasthitam
saha saumitriṇā rāmaḥ samāgacchad guhena saḥ', null, 2044011),
('ramayana-2-44-12', 12, 'Ayodhya Kanda, Sarga 44, Verse 12', 'तमार्तः संपरिष्वज्य गुहो राघवमब्रवीत्।
यथायोध्या तथेदं ते राम किं करवाणि ते॥', 'tam ārtaḥ saṃpariṣvajya guho rāghavam abravīt
yathāyodhyā tathedaṃ te rāma kiṃ karavāṇi te', null, 2044012),
('ramayana-2-44-13', 13, 'Ayodhya Kanda, Sarga 44, Verse 13', 'ततो गुणवदन्नाद्यमुपादाय पृथग्विधम्।
अर्घ्यं चोपानयत्क्षिप्रं वाक्यं चेदमुवाच ह॥', 'tato guṇavadannādyam upādāya pṛthagvidham
arghyaṃ copānayat kṣipraṃ vākyaṃ cedam uvāca ha', null, 2044013),
('ramayana-2-44-14', 14, 'Ayodhya Kanda, Sarga 44, Verse 14', 'स्वागतं ते महाबाहो तवेयमखिला मही।
वयं प्रेष्या भवान्भर्ता साधु राज्यं प्रशाधि नः॥', 'svāgataṃ te mahābāho taveyam akhilā mahī
vayaṃ preṣyā bhavān bhartā sādhu rājyaṃ praśādhi naḥ', null, 2044014),
('ramayana-2-44-15', 15, 'Ayodhya Kanda, Sarga 44, Verse 15', 'भक्ष्यं भोज्यं च पेयं च लेह्यं चेदमुपस्थितम्।
शयनानि च मुख्यानि वाजिनां खादनं च ते॥', 'bhakṣyaṃ bhojyaṃ ca peyaṃ ca lehyaṃ cedam upasthitam
śayanāni ca mukhyāni vājināṃ khādanaṃ ca te', null, 2044015),
('ramayana-2-44-16', 16, 'Ayodhya Kanda, Sarga 44, Verse 16', 'गुहमेव ब्रुवाणं तं राघवः प्रत्युवाच ह।
अर्चिताश्चैव हृष्टाश्च भवता सर्वथा वयम्॥', 'guham eva bruvāṇaṃ taṃ rāghavaḥ pratyuvāca ha
arcitāś caiva hṛṣṭāś ca bhavatā sarvathā vayam', null, 2044016),
('ramayana-2-44-17', 17, 'Ayodhya Kanda, Sarga 44, Verse 17', 'पद्भ्यामभिगमाच्चैव स्नेहसंदर्शनेन च।
भुजाभ्यां साधुवृत्ताभ्यां पीडयन्वाक्यमब्रवीत्॥', 'padbhyām abhigamāc caiva snehasaṃdarśanena ca
bhujābhyāṃ sādhuvṛttābhyāṃ pīḍayan vākyam abravīt', null, 2044017),
('ramayana-2-44-18', 18, 'Ayodhya Kanda, Sarga 44, Verse 18', 'दिष्ट्या त्वां गुह पश्यामि अरोगं सह बान्धवैः।
अपि ते कूशलं राष्ट्रे मित्रेषु च धनेषु च॥', 'diṣṭyā tvāṃ guha paśyāmi arogaṃ saha bāndhavaiḥ
api te kūśalaṃ rāṣṭre mitreṣu ca dhaneṣu ca', null, 2044018),
('ramayana-2-44-19', 19, 'Ayodhya Kanda, Sarga 44, Verse 19', 'यत्त्विदं भवता किं चित्प्रीत्या समुपकल्पितम्।
सर्वं तदनुजानामि न हि वर्ते प्रतिग्रहे॥', 'yat tv idaṃ bhavatā kiṃ cit prītyā samupakalpitam
sarvaṃ tad anujānāmi na hi varte pratigrahe', null, 2044019),
('ramayana-2-44-20', 20, 'Ayodhya Kanda, Sarga 44, Verse 20', 'कुशचीराजिनधरं फलमूलाशनं च माम्।
विद्धि प्रणिहितं धर्मे तापसं वनगोचरम्॥', 'kuśacīrājinadharaṃ phalamūlāśanaṃ ca mām
viddhi praṇihitaṃ dharme tāpasaṃ vanagocaram', null, 2044020),
('ramayana-2-44-21', 21, 'Ayodhya Kanda, Sarga 44, Verse 21', 'अश्वानां खादनेनाहमर्थी नान्येन केन चित्।
एतावतात्रभवता भविष्यामि सुपूजितः॥', 'aśvānāṃ khādanenāham arthī nānyena kena cit
etāvatātrabhavatā bhaviṣyāmi supūjitaḥ', null, 2044021),
('ramayana-2-44-22', 22, 'Ayodhya Kanda, Sarga 44, Verse 22', 'एते हि दयिता राज्ञः पितुर्दशरथस्य मे।
एतैः सुविहितैरश्वैर्भविष्याम्यहमर्चितः॥', 'ete hi dayitā rājñaḥ pitur daśarathasya me
etaiḥ suvihitair aśvair bhaviṣyāmy aham arcitaḥ', null, 2044022),
('ramayana-2-44-23', 23, 'Ayodhya Kanda, Sarga 44, Verse 23', 'अश्वानां प्रतिपानं च खादनं चैव सोऽन्वशात्।
गुहस्तत्रैव पुरुषांस्त्वरितं दीयतामिति॥', 'aśvānāṃ pratipānaṃ ca khādanaṃ caiva so ''nvaśāt
guhas tatraiva puruṣāṃs tvaritaṃ dīyatām iti', null, 2044023),
('ramayana-2-44-24', 24, 'Ayodhya Kanda, Sarga 44, Verse 24', 'ततश्चीरोत्तरासङ्गः संध्यामन्वास्य पश्चिमाम्।
जलमेवाददे भोज्यं लक्ष्मणेनाहृतं स्वयम्॥', 'tataś cīrottarāsaṅgaḥ saṃdhyām anvāsya paścimām
jalam evādade bhojyaṃ lakṣmaṇenāhṛtaṃ svayam', null, 2044024),
('ramayana-2-44-25', 25, 'Ayodhya Kanda, Sarga 44, Verse 25', 'तस्य भूमौ शयानस्य पादौ प्रक्षाल्य लक्ष्मणः।
सभार्यस्य ततोऽभ्येत्य तस्थौ वृक्षमुपाश्रितः॥', 'tasya bhūmau śayānasya pādau prakṣālya lakṣmaṇaḥ
sabhāryasya tato ''bhyetya tasthau vṛkṣam upāśritaḥ', null, 2044025),
('ramayana-2-44-26', 26, 'Ayodhya Kanda, Sarga 44, Verse 26', 'गुहोऽपि सह सूतेन सौमित्रिमनुभाषयन्।
अन्वजाग्रत्ततो राममप्रमत्तो धनुर्धरः॥', 'guho ''pi saha sūtena saumitrim anubhāṣayan
anvajāgrat tato rāmam apramatto dhanurdharaḥ', null, 2044026),
('ramayana-2-44-27', 27, 'Ayodhya Kanda, Sarga 44, Verse 27', 'तथा शयानस्य ततोऽस्य धीमतो यशस्विनो दाशरथेर्महात्मनः।
अदृष्टदुःखस्य सुखोचितस्य सा तदा व्यतीयाय चिरेण शर्वरी॥', 'tathā śayānasya tato ''sya dhīmato yaśasvino dāśarather mahātmanaḥ
adṛṣṭaduḥkhasya sukhocitasya sā tadā vyatīyāya cireṇa śarvarī', null, 2044027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 45 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-45-1', 1, 'Ayodhya Kanda, Sarga 45, Verse 1', 'तं जाग्रतमदम्भेन भ्रातुरर्थाय लक्ष्मणम्।
गुहः संतापसंतप्तो राघवं वाक्यमब्रवीत्॥', 'taṃ jāgratam adambhena bhrātur arthāya lakṣmaṇam
guhaḥ saṃtāpasaṃtapto rāghavaṃ vākyam abravīt', null, 2045001),
('ramayana-2-45-2', 2, 'Ayodhya Kanda, Sarga 45, Verse 2', 'इयं तात सुखा शय्या त्वदर्थमुपकल्पिता।
प्रत्याश्वसिहि साध्वस्यां राजपुत्र यथासुखम्॥', 'iyaṃ tāta sukhā śayyā tvadartham upakalpitā
pratyāśvasihi sādhv asyāṃ rājaputra yathāsukham', null, 2045002),
('ramayana-2-45-3', 3, 'Ayodhya Kanda, Sarga 45, Verse 3', 'उचितोऽयं जनः सर्वः क्लेशानां त्वं सुखोचितः।
गुप्त्यर्थं जागरिष्यामः काकुत्स्थस्य वयं निशाम्॥', 'ucito ''yaṃ janaḥ sarvaḥ kleśānāṃ tvaṃ sukhocitaḥ
guptyarthaṃ jāgariṣyāmaḥ kākutsthasya vayaṃ niśām', null, 2045003),
('ramayana-2-45-4', 4, 'Ayodhya Kanda, Sarga 45, Verse 4', 'न हि रामात्प्रियतरो ममास्ति भुवि कश्चन।
ब्रवीम्येतदहं सत्यं सत्येनैव च ते शपे॥', 'na hi rāmāt priyataro mamāsti bhuvi kaś cana
bravīmy etad ahaṃ satyaṃ satyenaiva ca te śape', null, 2045004),
('ramayana-2-45-5', 5, 'Ayodhya Kanda, Sarga 45, Verse 5', 'अस्य प्रसादादाशंसे लोकेऽस्मिन्सुमहद्यशः।
धर्मावाप्तिं च विपुलामर्थावाप्तिं च केवलाम्॥', 'asya prasādād āśaṃse loke ''smin sumahad yaśaḥ
dharmāvāptiṃ ca vipulām arthāvāptiṃ ca kevalām', null, 2045005),
('ramayana-2-45-6', 6, 'Ayodhya Kanda, Sarga 45, Verse 6', 'सोऽहं प्रियसखं रामं शयानं सह सीतया।
रक्षिष्यामि धनुष्पाणिः सर्वतो ज्ञातिभिः सह॥', 'so ''haṃ priyasakhaṃ rāmaṃ śayānaṃ saha sītayā
rakṣiṣyāmi dhanuṣpāṇiḥ sarvato jñātibhiḥ saha', null, 2045006),
('ramayana-2-45-7', 7, 'Ayodhya Kanda, Sarga 45, Verse 7', 'न हि मेऽविदितं किं चिद्वनेऽस्मिंश्चरतः सदा।
चतुरङ्गं ह्यपि बलं सुमहत्प्रसहेमहि॥', 'na hi me ''viditaṃ kiṃ cid vane ''smiṃś carataḥ sadā
caturaṅgaṃ hy api balaṃ sumahat prasahemahi', null, 2045007),
('ramayana-2-45-8', 8, 'Ayodhya Kanda, Sarga 45, Verse 8', 'लक्ष्मणस्तं तदोवाच रक्ष्यमाणास्त्वयानघ।
नात्र भीता वयं सर्वे धर्ममेवानुपश्यता॥', 'lakṣmaṇas taṃ tadovāca rakṣyamāṇās tvayānagha
nātra bhītā vayaṃ sarve dharmam evānupaśyatā', null, 2045008),
('ramayana-2-45-9', 9, 'Ayodhya Kanda, Sarga 45, Verse 9', 'कथं दाशरथौ भूमौ शयाने सह सीतया।
शक्या निद्रा मया लब्धुं जीवितं वा सुखानि वा॥', 'kathaṃ dāśarathau bhūmau śayāne saha sītayā
śakyā nidrā mayā labdhuṃ jīvitaṃ vā sukhāni vā', null, 2045009),
('ramayana-2-45-10', 10, 'Ayodhya Kanda, Sarga 45, Verse 10', 'यो न देवासुरैः सर्वैः शक्यः प्रसहितुं युधि।
तं पश्य सुखसंविष्टं तृणेषु सह सीतया॥', 'yo na devāsuraiḥ sarvaiḥ śakyaḥ prasahituṃ yudhi
taṃ paśya sukhasaṃviṣṭaṃ tṛṇeṣu saha sītayā', null, 2045010),
('ramayana-2-45-11', 11, 'Ayodhya Kanda, Sarga 45, Verse 11', 'यो मन्त्र तपसा लब्धो विविधैश्च परिश्रमैः।
एको दशरथस्यैष पुत्रः सदृशलक्षणः॥', 'yo mantra tapasā labdho vividhaiś ca pariśramaiḥ
eko daśarathasyaiṣa putraḥ sadṛśalakṣaṇaḥ', null, 2045011),
('ramayana-2-45-12', 12, 'Ayodhya Kanda, Sarga 45, Verse 12', 'अस्मिन्प्रव्रजितो राजा न चिरं वर्तयिष्यति।
विधवा मेदिनी नूनं क्षिप्रमेव भविष्यति॥', 'asmin pravrajito rājā na ciraṃ vartayiṣyati
vidhavā medinī nūnaṃ kṣipram eva bhaviṣyati', null, 2045012),
('ramayana-2-45-13', 13, 'Ayodhya Kanda, Sarga 45, Verse 13', 'विनद्य सुमहानादं श्रमेणोपरताः स्त्रियः।
निर्घोषोपरतं तात मन्ये राजनिवेशनम्॥', 'vinadya sumahānādaṃ śrameṇoparatāḥ striyaḥ
nirghoṣoparataṃ tāta manye rājaniveśanam', null, 2045013),
('ramayana-2-45-14', 14, 'Ayodhya Kanda, Sarga 45, Verse 14', 'कौसल्या चैव राजा च तथैव जननी मम।
नाशंसे यदि जीवन्ति सर्वे ते शर्वरीमिमाम्॥', 'kausalyā caiva rājā ca tathaiva jananī mama
nāśaṃse yadi jīvanti sarve te śarvarīm imām', null, 2045014),
('ramayana-2-45-15', 15, 'Ayodhya Kanda, Sarga 45, Verse 15', 'जीवेदपि हि मे माता शत्रुघ्नस्यान्ववेक्षया।
तद्दुःखं यत्तु कौसल्या वीरसूर्विनशिष्यति॥', 'jīved api hi me mātā śatrughnasyānvavekṣayā
tad duḥkhaṃ yat tu kausalyā vīrasūr vinaśiṣyati', null, 2045015),
('ramayana-2-45-16', 16, 'Ayodhya Kanda, Sarga 45, Verse 16', 'अनुरक्तजनाकीर्णा सुखालोकप्रियावहा।
राजव्यसनसंसृष्टा सा पुरी विनशिष्यति॥', 'anuraktajanākīrṇā sukhālokapriyāvahā
rājavyasanasaṃsṛṣṭā sā purī vinaśiṣyati', null, 2045016),
('ramayana-2-45-17', 17, 'Ayodhya Kanda, Sarga 45, Verse 17', 'अतिक्रान्तमतिक्रान्तमनवाप्य मनोरथम्।
राज्ये राममनिक्षिप्य पिता मे विनशिष्यति॥', 'atikrāntam atikrāntam anavāpya manoratham
rājye rāmam anikṣipya pitā me vinaśiṣyati', null, 2045017),
('ramayana-2-45-18', 18, 'Ayodhya Kanda, Sarga 45, Verse 18', 'सिद्धार्थाः पितरं वृत्तं तस्मिन्काले ह्युपस्थिते।
प्रेतकार्येषु सर्वेषु संस्करिष्यन्ति भूमिपम्॥', 'siddhārthāḥ pitaraṃ vṛttaṃ tasmin kāle hy upasthite
pretakāryeṣu sarveṣu saṃskariṣyanti bhūmipam', null, 2045018),
('ramayana-2-45-19', 19, 'Ayodhya Kanda, Sarga 45, Verse 19', 'रम्यचत्वरसंस्थानां सुविभक्तमहापथाम्।
हर्म्यप्रासादसंपन्नां गणिकावरशोभिताम्॥', 'ramyacatvarasaṃsthānāṃ suvibhaktamahāpathām
harmyaprāsādasaṃpannāṃ gaṇikāvaraśobhitām', null, 2045019),
('ramayana-2-45-20', 20, 'Ayodhya Kanda, Sarga 45, Verse 20', 'रथाश्वगजसंबाधां तूर्यनादविनादिताम्।
सर्वकल्याणसंपूर्णां हृष्टपुष्टजनाकुलाम्॥', 'rathāśvagajasaṃbādhāṃ tūryanādavināditām
sarvakalyāṇasaṃpūrṇāṃ hṛṣṭapuṣṭajanākulām', null, 2045020),
('ramayana-2-45-21', 21, 'Ayodhya Kanda, Sarga 45, Verse 21', 'आरामोद्यानसंपन्नां समाजोत्सवशालिनीम्।
सुखिता विचरिष्यन्ति राजधानीं पितुर्मम॥', 'ārāmodyānasaṃpannāṃ samājotsavaśālinīm
sukhitā vicariṣyanti rājadhānīṃ pitur mama', null, 2045021),
('ramayana-2-45-22', 22, 'Ayodhya Kanda, Sarga 45, Verse 22', 'अपि सत्यप्रतिज्ञेन सार्धं कुशलिना वयम्।
निवृत्ते वनवासेऽस्मिन्नयोध्यां प्रविशेमहि॥', 'api satyapratijñena sārdhaṃ kuśalinā vayam
nivṛtte vanavāse ''sminn ayodhyāṃ praviśemahi', null, 2045022),
('ramayana-2-45-23', 23, 'Ayodhya Kanda, Sarga 45, Verse 23', 'परिदेवयमानस्य दुःखार्तस्य महात्मनः।
तिष्ठतो राजपुत्रस्य शर्वरी सात्यवर्तत॥', 'paridevayamānasya duḥkhārtasya mahātmanaḥ
tiṣṭhato rājaputrasya śarvarī sātyavartata', null, 2045023),
('ramayana-2-45-24', 24, 'Ayodhya Kanda, Sarga 45, Verse 24', 'तथा हि सत्यं ब्रुवति प्रजाहिते नरेन्द्रपुत्रे गुरुसौहृदाद्गुहः।
मुमोच बाष्पं व्यसनाभिपीडितो ज्वरातुरो नाग इव व्यथातुरः॥', 'tathā hi satyaṃ bruvati prajāhite narendraputre gurusauhṛdād guhaḥ
mumoca bāṣpaṃ vyasanābhipīḍito jvarāturo nāga iva vyathāturaḥ', null, 2045024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 46 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-46-1', 1, 'Ayodhya Kanda, Sarga 46, Verse 1', 'प्रभातायां तु शर्वर्यां पृथु वृक्षा महायशाः।
उवाच रामः सौमित्रिं लक्ष्मणं शुभलक्षणम्॥', 'prabhātāyāṃ tu śarvaryāṃ pṛthu vṛkṣā mahāyaśāḥ
uvāca rāmaḥ saumitriṃ lakṣmaṇaṃ śubhalakṣaṇam', null, 2046001),
('ramayana-2-46-2', 2, 'Ayodhya Kanda, Sarga 46, Verse 2', 'भास्करोदयकालोऽयं गता भगवती निशा।
असौ सुकृष्णो विहगः कोकिलस्तात कूजति॥', 'bhāskarodayakālo ''yaṃ gatā bhagavatī niśā
asau sukṛṣṇo vihagaḥ kokilas tāta kūjati', null, 2046002),
('ramayana-2-46-3', 3, 'Ayodhya Kanda, Sarga 46, Verse 3', 'बर्हिणानां च निर्घोषः श्रूयते नदतां वने।
तराम जाह्नवीं सौम्य शीघ्रगां सागरंगमाम्॥', 'barhiṇānāṃ ca nirghoṣaḥ śrūyate nadatāṃ vane
tarāma jāhnavīṃ saumya śīghragāṃ sāgaraṃgamām', null, 2046003),
('ramayana-2-46-4', 4, 'Ayodhya Kanda, Sarga 46, Verse 4', 'विज्ञाय रामस्य वचः सौमित्रिर्मित्रनन्दनः।
गुहमामन्त्र्य सूतं च सोऽतिष्ठद्भ्रातुरग्रतः॥', 'vijñāya rāmasya vacaḥ saumitrir mitranandanaḥ
guham āmantrya sūtaṃ ca so ''tiṣṭhad bhrātur agrataḥ', null, 2046004),
('ramayana-2-46-5', 5, 'Ayodhya Kanda, Sarga 46, Verse 5', 'ततः कलापान्संनह्य खड्गौ बद्ध्वा च धन्विनौ।
जग्मतुर्येन तौ गङ्गां सीतया सह राघवौ॥', 'tataḥ kalāpān saṃnahya khaḍgau baddhvā ca dhanvinau
jagmatur yena tau gaṅgāṃ sītayā saha rāghavau', null, 2046005),
('ramayana-2-46-6', 6, 'Ayodhya Kanda, Sarga 46, Verse 6', 'राममेव तु धर्मज्ञमुपगम्य विनीतवत्।
किमहं करवाणीति सूतः प्राञ्जलिरब्रवीत्॥', 'rāmam eva tu dharmajñam upagamya vinītavat
kim ahaṃ karavāṇīti sūtaḥ prāñjalir abravīt', null, 2046006),
('ramayana-2-46-7', 7, 'Ayodhya Kanda, Sarga 46, Verse 7', 'निवर्तस्वेत्युवाचैनमेतावद्धि कृतं मम।
यानं विहाय पद्भ्यां तु गमिष्यामो महावनम्॥', 'nivartasvety uvācainam etāvad dhi kṛtaṃ mama
yānaṃ vihāya padbhyāṃ tu gamiṣyāmo mahāvanam', null, 2046007),
('ramayana-2-46-8', 8, 'Ayodhya Kanda, Sarga 46, Verse 8', 'आत्मानं त्वभ्यनुज्ञातमवेक्ष्यार्तः स सारथिः।
सुमन्त्रः पुरुषव्याघ्रमैक्ष्वाकमिदमब्रवीत्॥', 'ātmānaṃ tv abhyanujñātam avekṣyārtaḥ sa sārathiḥ
sumantraḥ puruṣavyāghram aikṣvākam idam abravīt', null, 2046008),
('ramayana-2-46-9', 9, 'Ayodhya Kanda, Sarga 46, Verse 9', 'नातिक्रान्तमिदं लोके पुरुषेणेह केन चित्।
तव सभ्रातृभार्यस्य वासः प्राकृतवद्वने॥', 'nātikrāntam idaṃ loke puruṣeṇeha kena cit
tava sabhrātṛbhāryasya vāsaḥ prākṛtavad vane', null, 2046009),
('ramayana-2-46-10', 10, 'Ayodhya Kanda, Sarga 46, Verse 10', 'न मन्ये ब्रह्मचर्येऽस्ति स्वधीते वा फलोदयः।
मार्दवार्जवयोर्वापि त्वां चेद्व्यसनमागतम्॥', 'na manye brahmacarye ''sti svadhīte vā phalodayaḥ
mārdavārjavayor vāpi tvāṃ ced vyasanam āgatam', null, 2046010),
('ramayana-2-46-11', 11, 'Ayodhya Kanda, Sarga 46, Verse 11', 'सह राघव वैदेह्या भ्रात्रा चैव वने वसन्।
त्वं गतिं प्राप्स्यसे वीर त्रींल्लोकांस्तु जयन्निव॥', 'saha rāghava vaidehyā bhrātrā caiva vane vasan
tvaṃ gatiṃ prāpsyase vīra trīṃl lokāṃs tu jayann iva', null, 2046011),
('ramayana-2-46-12', 12, 'Ayodhya Kanda, Sarga 46, Verse 12', 'वयं खलु हता राम ये तयाप्युपवञ्चिताः।
कैकेय्या वशमेष्यामः पापाया दुःखभागिनः॥', 'vayaṃ khalu hatā rāma ye tayāpy upavañcitāḥ
kaikeyyā vaśam eṣyāmaḥ pāpāyā duḥkhabhāginaḥ', null, 2046012),
('ramayana-2-46-13', 13, 'Ayodhya Kanda, Sarga 46, Verse 13', 'इति ब्रुवन्नात्म समं सुमन्त्रः सारथिस्तदा।
दृष्ट्वा दुर गतं रामं दुःखार्तो रुरुदे चिरम्॥', 'iti bruvann ātma samaṃ sumantraḥ sārathis tadā
dṛṣṭvā dura gataṃ rāmaṃ duḥkhārto rurude ciram', null, 2046013),
('ramayana-2-46-14', 14, 'Ayodhya Kanda, Sarga 46, Verse 14', 'ततस्तु विगते बाष्पे सूतं स्पृष्टोदकं शुचिम्।
रामस्तु मधुरं वाक्यं पुनः पुनरुवाच तम्॥', 'tatas tu vigate bāṣpe sūtaṃ spṛṣṭodakaṃ śucim
rāmas tu madhuraṃ vākyaṃ punaḥ punar uvāca tam', null, 2046014),
('ramayana-2-46-15', 15, 'Ayodhya Kanda, Sarga 46, Verse 15', 'इक्ष्वाकूणां त्वया तुल्यं सुहृदं नोपलक्षये।
यथा दशरथो राजा मां न शोचेत्तथा कुरु॥', 'ikṣvākūṇāṃ tvayā tulyaṃ suhṛdaṃ nopalakṣaye
yathā daśaratho rājā māṃ na śocet tathā kuru', null, 2046015),
('ramayana-2-46-16', 16, 'Ayodhya Kanda, Sarga 46, Verse 16', 'शोकोपहत चेताश्च वृद्धश्च जगतीपतिः।
काम भारावसन्नश्च तस्मादेतद्ब्रवीमि ते॥', 'śokopahata cetāś ca vṛddhaś ca jagatīpatiḥ
kāma bhārāvasannaś ca tasmād etad bravīmi te', null, 2046016),
('ramayana-2-46-17', 17, 'Ayodhya Kanda, Sarga 46, Verse 17', 'यद्यदाज्ञापयेत्किं चित्स महात्मा महीपतिः।
कैकेय्याः प्रियकामार्थं कार्यं तदविकाङ्क्षया॥', 'yad yad ājñāpayet kiṃ cit sa mahātmā mahīpatiḥ
kaikeyyāḥ priyakāmārthaṃ kāryaṃ tad avikāṅkṣayā', null, 2046017),
('ramayana-2-46-18', 18, 'Ayodhya Kanda, Sarga 46, Verse 18', 'एतदर्थं हि राज्यानि प्रशासति नरेश्वराः।
यदेषां सर्वकृत्येषु मनो न प्रतिहन्यते॥', 'etadarthaṃ hi rājyāni praśāsati nareśvarāḥ
yad eṣāṃ sarvakṛtyeṣu mano na pratihanyate', null, 2046018),
('ramayana-2-46-19', 19, 'Ayodhya Kanda, Sarga 46, Verse 19', 'तद्यथा स महाराजो नालीकमधिगच्छति।
न च ताम्यति दुःखेन सुमन्त्र कुरु तत्तथा॥', 'tad yathā sa mahārājo nālīkam adhigacchati
na ca tāmyati duḥkhena sumantra kuru tat tathā', null, 2046019),
('ramayana-2-46-20', 20, 'Ayodhya Kanda, Sarga 46, Verse 20', 'अदृष्टदुःखं राजानं वृद्धमार्यं जितेन्द्रियम्।
ब्रूयास्त्वमभिवाद्यैव मम हेतोरिदं वचः॥', 'adṛṣṭaduḥkhaṃ rājānaṃ vṛddham āryaṃ jitendriyam
brūyās tvam abhivādyaiva mama hetor idaṃ vacaḥ', null, 2046020),
('ramayana-2-46-21', 21, 'Ayodhya Kanda, Sarga 46, Verse 21', 'नैवाहमनुशोचामि लक्ष्मणो न च मैथिली।
अयोध्यायाश्च्युताश्चेति वने वत्स्यामहेति वा॥', 'naivāham anuśocāmi lakṣmaṇo na ca maithilī
ayodhyāyāś cyutāś ceti vane vatsyāmaheti vā', null, 2046021),
('ramayana-2-46-22', 22, 'Ayodhya Kanda, Sarga 46, Verse 22', 'चतुर्दशसु वर्षेषु निवृत्तेषु पुनः पुनः।
लक्ष्मणं मां च सीतां च द्रक्ष्यसि क्षिप्रमागतान्॥', 'caturdaśasu varṣeṣu nivṛtteṣu punaḥ punaḥ
lakṣmaṇaṃ māṃ ca sītāṃ ca drakṣyasi kṣipram āgatān', null, 2046022),
('ramayana-2-46-23', 23, 'Ayodhya Kanda, Sarga 46, Verse 23', 'एवमुक्त्वा तु राजानं मातरं च सुमन्त्र मे।
अन्याश्च देवीः सहिताः कैकेयीं च पुनः पुनः॥', 'evam uktvā tu rājānaṃ mātaraṃ ca sumantra me
anyāś ca devīḥ sahitāḥ kaikeyīṃ ca punaḥ punaḥ', null, 2046023),
('ramayana-2-46-24', 24, 'Ayodhya Kanda, Sarga 46, Verse 24', 'आरोग्यं ब्रूहि कौसल्यामथ पादाभिवन्दनम्।
सीताया मम चार्यस्य वचनाल्लक्ष्मणस्य च॥', 'ārogyaṃ brūhi kausalyām atha pādābhivandanam
sītāyā mama cāryasya vacanāl lakṣmaṇasya ca', null, 2046024),
('ramayana-2-46-25', 25, 'Ayodhya Kanda, Sarga 46, Verse 25', 'ब्रूयाश्च हि महाराजं भरतं क्षिप्रमानय।
आगतश्चापि भरतः स्थाप्यो नृपमते पदे॥', 'brūyāś ca hi mahārājaṃ bharataṃ kṣipram ānaya
āgataś cāpi bharataḥ sthāpyo nṛpamate pade', null, 2046025),
('ramayana-2-46-26', 26, 'Ayodhya Kanda, Sarga 46, Verse 26', 'भरतं च परिष्वज्य यौवराज्येऽभिषिच्य च।
अस्मत्संतापजं दुःखं न त्वामभिभविष्यति॥', 'bharataṃ ca pariṣvajya yauvarājye ''bhiṣicya ca
asmatsaṃtāpajaṃ duḥkhaṃ na tvām abhibhaviṣyati', null, 2046026),
('ramayana-2-46-27', 27, 'Ayodhya Kanda, Sarga 46, Verse 27', 'भरतश्चापि वक्तव्यो यथा राजनि वर्तसे।
तथा मातृषु वर्तेथाः सर्वास्वेवाविशेषतः॥', 'bharataś cāpi vaktavyo yathā rājani vartase
tathā mātṛṣu vartethāḥ sarvāsv evāviśeṣataḥ', null, 2046027),
('ramayana-2-46-28', 28, 'Ayodhya Kanda, Sarga 46, Verse 28', 'यथा च तव कैकेयी सुमित्रा चाविशेषतः।
तथैव देवी कौसल्या मम माता विशेषतः॥', 'yathā ca tava kaikeyī sumitrā cāviśeṣataḥ
tathaiva devī kausalyā mama mātā viśeṣataḥ', null, 2046028),
('ramayana-2-46-29', 29, 'Ayodhya Kanda, Sarga 46, Verse 29', 'निवर्त्यमानो रामेण सुमन्त्रः शोककर्शितः।
तत्सर्वं वचनं श्रुत्वा स्नेहात्काकुत्स्थमब्रवीत्॥', 'nivartyamāno rāmeṇa sumantraḥ śokakarśitaḥ
tat sarvaṃ vacanaṃ śrutvā snehāt kākutstham abravīt', null, 2046029),
('ramayana-2-46-30', 30, 'Ayodhya Kanda, Sarga 46, Verse 30', 'यदहं नोपचारेण ब्रूयां स्नेहादविक्लवः।
भक्तिमानिति तत्तावद्वाक्यं त्वं क्षन्तुमर्हसि॥', 'yad ahaṃ nopacāreṇa brūyāṃ snehād aviklavaḥ
bhaktimān iti tat tāvad vākyaṃ tvaṃ kṣantum arhasi', null, 2046030),
('ramayana-2-46-31', 31, 'Ayodhya Kanda, Sarga 46, Verse 31', 'कथं हि त्वद्विहीनोऽहं प्रतियास्यामि तां पुरीम्।
तव तात वियोगेन पुत्रशोकाकुलामिव॥', 'kathaṃ hi tvadvihīno ''haṃ pratiyāsyāmi tāṃ purīm
tava tāta viyogena putraśokākulām iva', null, 2046031),
('ramayana-2-46-32', 32, 'Ayodhya Kanda, Sarga 46, Verse 32', 'सराममपि तावन्मे रथं दृष्ट्वा तदा जनः।
विना रामं रथं दृष्ट्वा विदीर्येतापि सा पुरी॥', 'sarāmam api tāvan me rathaṃ dṛṣṭvā tadā janaḥ
vinā rāmaṃ rathaṃ dṛṣṭvā vidīryetāpi sā purī', null, 2046032),
('ramayana-2-46-33', 33, 'Ayodhya Kanda, Sarga 46, Verse 33', 'दैन्यं हि नगरी गच्छेद्दृष्ट्वा शून्यमिमं रथम्।
सूतावशेषं स्वं सैन्यं हतवीरमिवाहवे॥', 'dainyaṃ hi nagarī gacched dṛṣṭvā śūnyam imaṃ ratham
sūtāvaśeṣaṃ svaṃ sainyaṃ hatavīram ivāhave', null, 2046033),
('ramayana-2-46-34', 34, 'Ayodhya Kanda, Sarga 46, Verse 34', 'दूरेऽपि निवसन्तं त्वां मानसेनाग्रतः स्थितम्।
चिन्तयन्त्योऽद्य नूनं त्वां निराहाराः कृताः प्रजाः॥', 'dūre ''pi nivasantaṃ tvāṃ mānasenāgrataḥ sthitam
cintayantyo ''dya nūnaṃ tvāṃ nirāhārāḥ kṛtāḥ prajāḥ', null, 2046034),
('ramayana-2-46-35', 35, 'Ayodhya Kanda, Sarga 46, Verse 35', 'आर्तनादो हि यः पौरैर्मुक्तस्तद्विप्रवासने।
रथस्थं मां निशाम्यैव कुर्युः शतगुणं ततः॥', 'ārtanādo hi yaḥ paurair muktas tadvipravāsane
rathasthaṃ māṃ niśāmyaiva kuryuḥ śataguṇaṃ tataḥ', null, 2046035),
('ramayana-2-46-36', 36, 'Ayodhya Kanda, Sarga 46, Verse 36', 'अहं किं चापि वक्ष्यामि देवीं तव सुतो मया।
नीतोऽसौ मातुलकुलं संतापं मा कृथा इति॥', 'ahaṃ kiṃ cāpi vakṣyāmi devīṃ tava suto mayā
nīto ''sau mātulakulaṃ saṃtāpaṃ mā kṛthā iti', null, 2046036),
('ramayana-2-46-37', 37, 'Ayodhya Kanda, Sarga 46, Verse 37', 'असत्यमपि नैवाहं ब्रूयां वचनमीदृशम्।
कथमप्रियमेवाहं ब्रूयां सत्यमिदं वचः॥', 'asatyam api naivāhaṃ brūyāṃ vacanam īdṛśam
katham apriyam evāhaṃ brūyāṃ satyam idaṃ vacaḥ', null, 2046037),
('ramayana-2-46-38', 38, 'Ayodhya Kanda, Sarga 46, Verse 38', 'मम तावन्नियोगस्थास्त्वद्बन्धुजनवाहिनः।
कथं रथं त्वया हीनं प्रवक्ष्यन्ति हयोत्तमाः॥', 'mama tāvan niyogasthās tvadbandhujanavāhinaḥ
kathaṃ rathaṃ tvayā hīnaṃ pravakṣyanti hayottamāḥ', null, 2046038),
('ramayana-2-46-39', 39, 'Ayodhya Kanda, Sarga 46, Verse 39', 'यदि मे याचमानस्य त्यागमेव करिष्यसि।
सरथोऽग्निं प्रवेक्ष्यामि त्यक्त मात्र इह त्वया॥', 'yadi me yācamānasya tyāgam eva kariṣyasi
saratho ''gniṃ pravekṣyāmi tyakta mātra iha tvayā', null, 2046039),
('ramayana-2-46-40', 40, 'Ayodhya Kanda, Sarga 46, Verse 40', 'भविष्यन्ति वने यानि तपोविघ्नकराणि ते।
रथेन प्रतिबाधिष्ये तानि सत्त्वानि राघव॥', 'bhaviṣyanti vane yāni tapovighnakarāṇi te
rathena pratibādhiṣye tāni sattvāni rāghava', null, 2046040),
('ramayana-2-46-41', 41, 'Ayodhya Kanda, Sarga 46, Verse 41', 'तत्कृतेन मया प्राप्तं रथ चर्या कृतं सुखम्।
आशंसे त्वत्कृतेनाहं वनवासकृतं सुखम्॥', 'tat kṛtena mayā prāptaṃ ratha caryā kṛtaṃ sukham
āśaṃse tvatkṛtenāhaṃ vanavāsakṛtaṃ sukham', null, 2046041),
('ramayana-2-46-42', 42, 'Ayodhya Kanda, Sarga 46, Verse 42', 'प्रसीदेच्छामि तेऽरण्ये भवितुं प्रत्यनन्तरः।
प्रीत्याभिहितमिच्छामि भव मे पत्यनन्तरः॥', 'prasīdecchāmi te ''raṇye bhavituṃ pratyanantaraḥ
prītyābhihitam icchāmi bhava me patyanantaraḥ', null, 2046042),
('ramayana-2-46-43', 43, 'Ayodhya Kanda, Sarga 46, Verse 43', 'तव शुश्रूषणं मूर्ध्ना करिष्यामि वने वसन्।
अयोध्यां देवलोकं वा सर्वथा प्रजहाम्यहम्॥', 'tava śuśrūṣaṇaṃ mūrdhnā kariṣyāmi vane vasan
ayodhyāṃ devalokaṃ vā sarvathā prajahāmy aham', null, 2046043),
('ramayana-2-46-44', 44, 'Ayodhya Kanda, Sarga 46, Verse 44', 'न हि शक्या प्रवेष्टुं सा मयायोध्या त्वया विना।
राजधानी महेन्द्रस्य यथा दुष्कृतकर्मणा॥', 'na hi śakyā praveṣṭuṃ sā mayāyodhyā tvayā vinā
rājadhānī mahendrasya yathā duṣkṛtakarmaṇā', null, 2046044),
('ramayana-2-46-45', 45, 'Ayodhya Kanda, Sarga 46, Verse 45', 'इमे चापि हया वीर यदि ते वनवासिनः।
परिचर्यां करिष्यन्ति प्राप्स्यन्ति परमां गतिम्॥', 'ime cāpi hayā vīra yadi te vanavāsinaḥ
paricaryāṃ kariṣyanti prāpsyanti paramāṃ gatim', null, 2046045),
('ramayana-2-46-46', 46, 'Ayodhya Kanda, Sarga 46, Verse 46', 'वनवासे क्षयं प्राप्ते ममैष हि मनोरथः।
यदनेन रथेनैव त्वां वहेयं पुरीं पुनः॥', 'vanavāse kṣayaṃ prāpte mamaiṣa hi manorathaḥ
yad anena rathenaiva tvāṃ vaheyaṃ purīṃ punaḥ', null, 2046046),
('ramayana-2-46-47', 47, 'Ayodhya Kanda, Sarga 46, Verse 47', 'चतुर्दश हि वर्षाणि सहितस्य त्वया वने।
क्षणभूतानि यास्यन्ति शतशस्तु ततोऽन्यथा॥', 'caturdaśa hi varṣāṇi sahitasya tvayā vane
kṣaṇabhūtāni yāsyanti śataśas tu tato ''nyathā', null, 2046047),
('ramayana-2-46-48', 48, 'Ayodhya Kanda, Sarga 46, Verse 48', 'भृत्यवत्सल तिष्ठन्तं भर्तृपुत्रगते पथि।
भक्तं भृत्यं स्थितं स्थित्यां त्वं न मां हातुमर्हसि॥', 'bhṛtyavatsala tiṣṭhantaṃ bhartṛputragate pathi
bhaktaṃ bhṛtyaṃ sthitaṃ sthityāṃ tvaṃ na māṃ hātum arhasi', null, 2046048),
('ramayana-2-46-49', 49, 'Ayodhya Kanda, Sarga 46, Verse 49', 'एवं बहुविधं दीनं याचमानं पुनः पुनः।
रामो भृत्यानुकम्पी तु सुमन्त्रमिदमब्रवीत्॥', 'evaṃ bahuvidhaṃ dīnaṃ yācamānaṃ punaḥ punaḥ
rāmo bhṛtyānukampī tu sumantram idam abravīt', null, 2046049),
('ramayana-2-46-50', 50, 'Ayodhya Kanda, Sarga 46, Verse 50', 'जानामि परमां भक्तिं मयि ते भर्तृवत्सल।
शृणु चापि यदर्थं त्वां प्रेषयामि पुरीमितः॥', 'jānāmi paramāṃ bhaktiṃ mayi te bhartṛvatsala
śṛṇu cāpi yadarthaṃ tvāṃ preṣayāmi purīm itaḥ', null, 2046050),
('ramayana-2-46-51', 51, 'Ayodhya Kanda, Sarga 46, Verse 51', 'नगरीं त्वां गतं दृष्ट्वा जननी मे यवीयसी।
कैकेयी प्रत्ययं गच्छेदिति रामो वनं गतः॥', 'nagarīṃ tvāṃ gataṃ dṛṣṭvā jananī me yavīyasī
kaikeyī pratyayaṃ gacched iti rāmo vanaṃ gataḥ', null, 2046051),
('ramayana-2-46-52', 52, 'Ayodhya Kanda, Sarga 46, Verse 52', 'परितुष्टा हि सा देवि वनवासं गते मयि।
राजानं नातिशङ्केत मिथ्यावादीति धार्मिकम्॥', 'parituṣṭā hi sā devi vanavāsaṃ gate mayi
rājānaṃ nātiśaṅketa mithyāvādīti dhārmikam', null, 2046052),
('ramayana-2-46-53', 53, 'Ayodhya Kanda, Sarga 46, Verse 53', 'एष मे प्रथमः कल्पो यदम्बा मे यवीयसी।
भरतारक्षितं स्फीतं पुत्रराज्यमवाप्नुयात्॥', 'eṣa me prathamaḥ kalpo yad ambā me yavīyasī
bharatārakṣitaṃ sphītaṃ putrarājyam avāpnuyāt', null, 2046053),
('ramayana-2-46-54', 54, 'Ayodhya Kanda, Sarga 46, Verse 54', 'मम प्रियार्थं राज्ञश्च सरथस्त्वं पुरीं व्रज।
संदिष्टश्चासि यानर्थांस्तांस्तान्ब्रूयास्तथातथा॥', 'mama priyārthaṃ rājñaś ca sarathas tvaṃ purīṃ vraja
saṃdiṣṭaś cāsi yān arthāṃs tāṃs tān brūyās tathātathā', null, 2046054),
('ramayana-2-46-55', 55, 'Ayodhya Kanda, Sarga 46, Verse 55', 'इत्युक्त्वा वचनं सूतं सान्त्वयित्वा पुनः पुनः।
गुहं वचनमक्लीबं रामो हेतुमदब्रवीत्।
जटाः कृत्वा गमिष्यामि न्यग्रोधक्षीरमानय॥', 'ity uktvā vacanaṃ sūtaṃ sāntvayitvā punaḥ punaḥ
guhaṃ vacanam aklībaṃ rāmo hetumad abravīt
jaṭāḥ kṛtvā gamiṣyāmi nyagrodhakṣīram ānaya', null, 2046055),
('ramayana-2-46-56', 56, 'Ayodhya Kanda, Sarga 46, Verse 56', 'तत्क्षीरं राजपुत्राय गुहः क्षिप्रमुपाहरत्।
लक्ष्मणस्यात्मनश्चैव रामस्तेनाकरोज्जटाः॥', 'tat kṣīraṃ rājaputrāya guhaḥ kṣipram upāharat
lakṣmaṇasyātmanaś caiva rāmas tenākaroj jaṭāḥ', null, 2046056),
('ramayana-2-46-57', 57, 'Ayodhya Kanda, Sarga 46, Verse 57', 'तौ तदा चीरवसनौ जटामण्डलधारिणौ।
अशोभेतामृषिसमौ भ्रातरौ रामलक्ष्मणौ॥', 'tau tadā cīravasanau jaṭāmaṇḍaladhāriṇau
aśobhetām ṛṣisamau bhrātarau rāmalakṣmaṇau', null, 2046057),
('ramayana-2-46-58', 58, 'Ayodhya Kanda, Sarga 46, Verse 58', 'ततो वैखानसं मार्गमास्थितः सहलक्ष्मणः।
व्रतमादिष्टवान्रामः सहायं गुहमब्रवीत्॥', 'tato vaikhānasaṃ mārgam āsthitaḥ sahalakṣmaṇaḥ
vratam ādiṣṭavān rāmaḥ sahāyaṃ guham abravīt', null, 2046058),
('ramayana-2-46-59', 59, 'Ayodhya Kanda, Sarga 46, Verse 59', 'अप्रमत्तो बले कोशे दुर्गे जनपदे तथा।
भवेथा गुह राज्यं हि दुरारक्षतमं मतम्॥', 'apramatto bale kośe durge janapade tathā
bhavethā guha rājyaṃ hi durārakṣatamaṃ matam', null, 2046059),
('ramayana-2-46-60', 60, 'Ayodhya Kanda, Sarga 46, Verse 60', 'ततस्तं समनुज्ञाय गुहमिक्ष्वाकुनन्दनः।
जगाम तूर्णमव्यग्रः सभार्यः सहलक्ष्मणः॥', 'tatas taṃ samanujñāya guham ikṣvākunandanaḥ
jagāma tūrṇam avyagraḥ sabhāryaḥ sahalakṣmaṇaḥ', null, 2046060),
('ramayana-2-46-61', 61, 'Ayodhya Kanda, Sarga 46, Verse 61', 'स तु दृष्ट्वा नदीतीरे नावमिक्ष्वाकुनन्दनः।
तितीर्षुः शीघ्रगां गङ्गामिदं लक्ष्मणमब्रवीत्॥', 'sa tu dṛṣṭvā nadītīre nāvam ikṣvākunandanaḥ
titīrṣuḥ śīghragāṃ gaṅgām idaṃ lakṣmaṇam abravīt', null, 2046061),
('ramayana-2-46-62', 62, 'Ayodhya Kanda, Sarga 46, Verse 62', 'आरोह त्वं नर व्याघ्र स्थितां नावमिमां शनैः।
सीतां चारोपयान्वक्षं परिगृह्य मनस्विनीम्॥', 'āroha tvaṃ nara vyāghra sthitāṃ nāvam imāṃ śanaiḥ
sītāṃ cāropayānvakṣaṃ parigṛhya manasvinīm', null, 2046062),
('ramayana-2-46-63', 63, 'Ayodhya Kanda, Sarga 46, Verse 63', 'स भ्रातुः शासनं श्रुत्वा सर्वमप्रतिकूलयन्।
आरोप्य मैथिलीं पूर्वमारुरोहात्मवांस्ततः॥', 'sa bhrātuḥ śāsanaṃ śrutvā sarvam apratikūlayan
āropya maithilīṃ pūrvam ārurohātmavāṃs tataḥ', null, 2046063),
('ramayana-2-46-64', 64, 'Ayodhya Kanda, Sarga 46, Verse 64', 'अथारुरोह तेजस्वी स्वयं लक्ष्मणपूर्वजः।
ततो निषादाधिपतिर्गुहो ज्ञातीनचोदयत्॥', 'athāruroha tejasvī svayaṃ lakṣmaṇapūrvajaḥ
tato niṣādādhipatir guho jñātīn acodayat', null, 2046064),
('ramayana-2-46-65', 65, 'Ayodhya Kanda, Sarga 46, Verse 65', 'अनुज्ञाय सुमन्त्रं च सबलं चैव तं गुहम्।
आस्थाय नावं रामस्तु चोदयामास नाविकान्॥', 'anujñāya sumantraṃ ca sabalaṃ caiva taṃ guham
āsthāya nāvaṃ rāmas tu codayām āsa nāvikān', null, 2046065),
('ramayana-2-46-66', 66, 'Ayodhya Kanda, Sarga 46, Verse 66', 'ततस्तैश्चोदिता सा नौः कर्णधारसमाहिता।
शुभस्फ्यवेगाभिहता शीघ्रं सलिलमत्यगात्॥', 'tatas taiś coditā sā nauḥ karṇadhārasamāhitā
śubhasphyavegābhihatā śīghraṃ salilam atyagāt', null, 2046066),
('ramayana-2-46-67', 67, 'Ayodhya Kanda, Sarga 46, Verse 67', 'मध्यं तु समनुप्राप्य भागीरथ्यास्त्वनिन्दिता।
वैदेही प्राञ्जलिर्भूत्वा तां नदीमिदमब्रवीत्॥', 'madhyaṃ tu samanuprāpya bhāgīrathyās tv aninditā
vaidehī prāñjalir bhūtvā tāṃ nadīm idam abravīt', null, 2046067),
('ramayana-2-46-68', 68, 'Ayodhya Kanda, Sarga 46, Verse 68', 'पुत्रो दशरथस्यायं महाराजस्य धीमतः।
निदेशं पालयत्वेनं गङ्गे त्वदभिरक्षितः॥', 'putro daśarathasyāyaṃ mahārājasya dhīmataḥ
nideśaṃ pālayatv enaṃ gaṅge tvadabhirakṣitaḥ', null, 2046068),
('ramayana-2-46-69', 69, 'Ayodhya Kanda, Sarga 46, Verse 69', 'चतुर्दश हि वर्षाणि समग्राण्युष्य कानने।
भ्रात्रा सह मया चैव पुनः प्रत्यागमिष्यति॥', 'caturdaśa hi varṣāṇi samagrāṇy uṣya kānane
bhrātrā saha mayā caiva punaḥ pratyāgamiṣyati', null, 2046069),
('ramayana-2-46-70', 70, 'Ayodhya Kanda, Sarga 46, Verse 70', 'ततस्त्वां देवि सुभगे क्षेमेण पुनरागता।
यक्ष्ये प्रमुदिता गङ्गे सर्वकामसमृद्धये॥', 'tatas tvāṃ devi subhage kṣemeṇa punar āgatā
yakṣye pramuditā gaṅge sarvakāmasamṛddhaye', null, 2046070),
('ramayana-2-46-71', 71, 'Ayodhya Kanda, Sarga 46, Verse 71', 'त्वं हि त्रिपथगा देवि ब्रह्म लोकं समीक्षसे।
भार्या चोदधिराजस्य लोकेऽस्मिन्संप्रदृश्यसे॥', 'tvaṃ hi tripathagā devi brahma lokaṃ samīkṣase
bhāryā codadhirājasya loke ''smin saṃpradṛśyase', null, 2046071),
('ramayana-2-46-72', 72, 'Ayodhya Kanda, Sarga 46, Verse 72', 'सा त्वां देवि नमस्यामि प्रशंसामि च शोभने।
प्राप्त राज्ये नरव्याघ्र शिवेन पुनरागते॥', 'sā tvāṃ devi namasyāmi praśaṃsāmi ca śobhane
prāpta rājye naravyāghra śivena punar āgate', null, 2046072),
('ramayana-2-46-73', 73, 'Ayodhya Kanda, Sarga 46, Verse 73', 'गवां शतसहस्राणि वस्त्राण्यन्नं च पेशलम्।
ब्राह्मणेभ्यः प्रदास्यामि तव प्रियचिकीर्षया॥', 'gavāṃ śatasahasrāṇi vastrāṇy annaṃ ca peśalam
brāhmaṇebhyaḥ pradāsyāmi tava priyacikīrṣayā', null, 2046073),
('ramayana-2-46-74', 74, 'Ayodhya Kanda, Sarga 46, Verse 74', 'तथा संभाषमाणा सा सीता गङ्गामनिन्दिता।
दक्षिणा दक्षिणं तीरं क्षिप्रमेवाभ्युपागमत्॥', 'tathā saṃbhāṣamāṇā sā sītā gaṅgām aninditā
dakṣiṇā dakṣiṇaṃ tīraṃ kṣipram evābhyupāgamat', null, 2046074),
('ramayana-2-46-75', 75, 'Ayodhya Kanda, Sarga 46, Verse 75', 'तीरं तु समनुप्राप्य नावं हित्वा नरर्षभः।
प्रातिष्ठत सह भ्रात्रा वैदेह्या च परंतपः॥', 'tīraṃ tu samanuprāpya nāvaṃ hitvā nararṣabhaḥ
prātiṣṭhata saha bhrātrā vaidehyā ca paraṃtapaḥ', null, 2046075),
('ramayana-2-46-76', 76, 'Ayodhya Kanda, Sarga 46, Verse 76', 'अथाब्रवीन्महाबाहुः सुमित्रानन्दवर्धनम्।
अग्रतो गच्छ सौमित्रे सीता त्वामनुगच्छतु॥', 'athābravīn mahābāhuḥ sumitrānandavardhanam
agrato gaccha saumitre sītā tvām anugacchatu', null, 2046076),
('ramayana-2-46-77', 77, 'Ayodhya Kanda, Sarga 46, Verse 77', 'पृष्ठतोऽहं गमिष्यामि त्वां च सीतां च पालयन्।
अद्य दुःखं तु वैदेही वनवासस्य वेत्स्यति॥', 'pṛṣṭhato ''haṃ gamiṣyāmi tvāṃ ca sītāṃ ca pālayan
adya duḥkhaṃ tu vaidehī vanavāsasya vetsyati', null, 2046077),
('ramayana-2-46-78', 78, 'Ayodhya Kanda, Sarga 46, Verse 78', 'गतं तु गङ्गापरपारमाशु रामं सुमन्त्रः प्रततं निरीक्ष्य।
अध्वप्रकर्षाद्विनिवृत्तदृष्टिर्मुमोच बाष्पं व्यथितस्तपस्वी॥', 'gataṃ tu gaṅgāparapāram āśu rāmaṃ sumantraḥ pratataṃ nirīkṣya
adhvaprakarṣād vinivṛttadṛṣṭir mumoca bāṣpaṃ vyathitas tapasvī', null, 2046078),
('ramayana-2-46-79', 79, 'Ayodhya Kanda, Sarga 46, Verse 79', 'तौ तत्र हत्वा चतुरो महामृगान्वराहमृश्यं पृषतं महारुरुम्।
आदाय मेध्यं त्वरितं बुभुक्षितौ वासाय काले ययतुर्वनस्पतिम्॥', 'tau tatra hatvā caturo mahāmṛgān varāham ṛśyaṃ pṛṣataṃ mahārurum
ādāya medhyaṃ tvaritaṃ bubhukṣitau vāsāya kāle yayatur vanaspatim', null, 2046079)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 47 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-47-1', 1, 'Ayodhya Kanda, Sarga 47, Verse 1', 'स तं वृक्षं समासाद्य संध्यामन्वास्य पश्चिमाम्।
रामो रमयतां श्रेष्ठ इति होवाच लक्ष्मणम्॥', 'sa taṃ vṛkṣaṃ samāsādya saṃdhyām anvāsya paścimām
rāmo ramayatāṃ śreṣṭha iti hovāca lakṣmaṇam', null, 2047001),
('ramayana-2-47-2', 2, 'Ayodhya Kanda, Sarga 47, Verse 2', 'अद्येयं प्रथमा रात्रिर्याता जनपदाद्बहिः।
या सुमन्त्रेण रहिता तां नोत्कण्ठितुमर्हसि॥', 'adyeyaṃ prathamā rātrir yātā janapadād bahiḥ
yā sumantreṇa rahitā tāṃ notkaṇṭhitum arhasi', null, 2047002),
('ramayana-2-47-3', 3, 'Ayodhya Kanda, Sarga 47, Verse 3', 'जागर्तव्यमतन्द्रिभ्यामद्य प्रभृति रात्रिषु।
योगक्षेमो हि सीताया वर्तते लक्ष्मणावयोः॥', 'jāgartavyam atandribhyām adya prabhṛti rātriṣu
yogakṣemo hi sītāyā vartate lakṣmaṇāvayoḥ', null, 2047003),
('ramayana-2-47-4', 4, 'Ayodhya Kanda, Sarga 47, Verse 4', 'रात्रिं कथं चिदेवेमां सौमित्रे वर्तयामहे।
उपावर्तामहे भूमावास्तीर्य स्वयमार्जितैः॥', 'rātriṃ kathaṃ cid evemāṃ saumitre vartayāmahe
upāvartāmahe bhūmāv āstīrya svayam ārjitaiḥ', null, 2047004),
('ramayana-2-47-5', 5, 'Ayodhya Kanda, Sarga 47, Verse 5', 'स तु संविश्य मेदिन्यां महार्हशयनोचितः।
इमाः सौमित्रये रामो व्याजहार कथाः शुभाः॥', 'sa tu saṃviśya medinyāṃ mahārhaśayanocitaḥ
imāḥ saumitraye rāmo vyājahāra kathāḥ śubhāḥ', null, 2047005),
('ramayana-2-47-6', 6, 'Ayodhya Kanda, Sarga 47, Verse 6', 'ध्रुवमद्य महाराजो दुःखं स्वपिति लक्ष्मण।
कृतकामा तु कैकेयी तुष्टा भवितुमर्हति॥', 'dhruvam adya mahārājo duḥkhaṃ svapiti lakṣmaṇa
kṛtakāmā tu kaikeyī tuṣṭā bhavitum arhati', null, 2047006),
('ramayana-2-47-7', 7, 'Ayodhya Kanda, Sarga 47, Verse 7', 'सा हि देवी महाराजं कैकेयी राज्यकारणात्।
अपि न च्यावयेत्प्राणान्दृष्ट्वा भरतमागतम्॥', 'sā hi devī mahārājaṃ kaikeyī rājyakāraṇāt
api na cyāvayet prāṇān dṛṣṭvā bharatam āgatam', null, 2047007),
('ramayana-2-47-8', 8, 'Ayodhya Kanda, Sarga 47, Verse 8', 'अनाथश्चैव वृद्धश्च मया चैव विनाकृतः।
किं करिष्यति कामात्मा कैकेय्या वशमागतः॥', 'anāthaś caiva vṛddhaś ca mayā caiva vinākṛtaḥ
kiṃ kariṣyati kāmātmā kaikeyyā vaśam āgataḥ', null, 2047008),
('ramayana-2-47-9', 9, 'Ayodhya Kanda, Sarga 47, Verse 9', 'इदं व्यसनमालोक्य राज्ञश्च मतिविभ्रमम्।
काम एवार्धधर्माभ्यां गरीयानिति मे मतिः॥', 'idaṃ vyasanam ālokya rājñaś ca mativibhramam
kāma evārdhadharmābhyāṃ garīyān iti me matiḥ', null, 2047009),
('ramayana-2-47-10', 10, 'Ayodhya Kanda, Sarga 47, Verse 10', 'को ह्यविद्वानपि पुमान्प्रमदायाः कृते त्यजेत्।
छन्दानुवर्तिनं पुत्रं तातो मामिव लक्ष्मण॥', 'ko hy avidvān api pumān pramadāyāḥ kṛte tyajet
chandānuvartinaṃ putraṃ tāto mām iva lakṣmaṇa', null, 2047010),
('ramayana-2-47-11', 11, 'Ayodhya Kanda, Sarga 47, Verse 11', 'सुखी बत सभार्यश्च भरतः केकयीसुतः।
मुदितान्कोसलानेको यो भोक्ष्यत्यधिराजवत्॥', 'sukhī bata sabhāryaś ca bharataḥ kekayīsutaḥ
muditān kosalān eko yo bhokṣyaty adhirājavat', null, 2047011),
('ramayana-2-47-12', 12, 'Ayodhya Kanda, Sarga 47, Verse 12', 'स हि सर्वस्य राज्यस्य मुखमेकं भविष्यति।
ताते च वयसातीते मयि चारण्यमाश्रिते॥', 'sa hi sarvasya rājyasya mukham ekaṃ bhaviṣyati
tāte ca vayasātīte mayi cāraṇyam āśrite', null, 2047012),
('ramayana-2-47-13', 13, 'Ayodhya Kanda, Sarga 47, Verse 13', 'अर्थधर्मौ परित्यज्य यः काममनुवर्तते।
एवमापद्यते क्षिप्रं राजा दशरथो यथा॥', 'arthadharmau parityajya yaḥ kāmam anuvartate
evam āpadyate kṣipraṃ rājā daśaratho yathā', null, 2047013),
('ramayana-2-47-14', 14, 'Ayodhya Kanda, Sarga 47, Verse 14', 'मन्ये दशरथान्ताय मम प्रव्राजनाय च।
कैकेयी सौम्य संप्राप्ता राज्याय भरतस्य च॥', 'manye daśarathāntāya mama pravrājanāya ca
kaikeyī saumya saṃprāptā rājyāya bharatasya ca', null, 2047014),
('ramayana-2-47-15', 15, 'Ayodhya Kanda, Sarga 47, Verse 15', 'अपीदानीं न कैकेयी सौभाग्यमदमोहिता।
कौसल्यां च सुमित्रां च संप्रबाधेत मत्कृते॥', 'apīdānīṃ na kaikeyī saubhāgyamadamohitā
kausalyāṃ ca sumitrāṃ ca saṃprabādheta matkṛte', null, 2047015),
('ramayana-2-47-16', 16, 'Ayodhya Kanda, Sarga 47, Verse 16', 'मा स्म मत्कारणाद्देवी सुमित्रा दुःखमावसेत्।
अयोध्यामित एव त्वं काले प्रविश लक्ष्मण॥', 'mā sma matkāraṇād devī sumitrā duḥkham āvaset
ayodhyām ita eva tvaṃ kāle praviśa lakṣmaṇa', null, 2047016),
('ramayana-2-47-17', 17, 'Ayodhya Kanda, Sarga 47, Verse 17', 'अहमेको गमिष्यामि सीतया सह दण्डकान्।
अनाथाया हि नाथस्त्वं कौसल्याया भविष्यसि॥', 'aham eko gamiṣyāmi sītayā saha daṇḍakān
anāthāyā hi nāthas tvaṃ kausalyāyā bhaviṣyasi', null, 2047017),
('ramayana-2-47-18', 18, 'Ayodhya Kanda, Sarga 47, Verse 18', 'क्षुद्रकर्मा हि कैकेयी द्वेषादन्याय्यमाचरेत्।
परिदद्या हि धर्मज्ञे भरते मम मातरम्॥', 'kṣudrakarmā hi kaikeyī dveṣād anyāyyam ācaret
paridadyā hi dharmajñe bharate mama mātaram', null, 2047018),
('ramayana-2-47-19', 19, 'Ayodhya Kanda, Sarga 47, Verse 19', 'नूनं जात्यन्तरे कस्मिं स्त्रियः पुत्रैर्वियोजिताः।
जनन्या मम सौमित्रे तदप्येतदुपस्थितम्॥', 'nūnaṃ jātyantare kasmiṃ striyaḥ putrair viyojitāḥ
jananyā mama saumitre tad apy etad upasthitam', null, 2047019),
('ramayana-2-47-20', 20, 'Ayodhya Kanda, Sarga 47, Verse 20', 'मया हि चिरपुष्टेन दुःखसंवर्धितेन च।
विप्रायुज्यत कौसल्या फलकाले धिगस्तु माम्॥', 'mayā hi cirapuṣṭena duḥkhasaṃvardhitena ca
viprāyujyata kausalyā phalakāle dhig astu mām', null, 2047020),
('ramayana-2-47-21', 21, 'Ayodhya Kanda, Sarga 47, Verse 21', 'मा स्म सीमन्तिनी का चिज्जनयेत्पुत्रमीदृशम्।
सौमित्रे योऽहमम्बाया दद्मि शोकमनन्तकम्॥', 'mā sma sīmantinī kā cij janayet putram īdṛśam
saumitre yo ''ham ambāyā dadmi śokam anantakam', null, 2047021),
('ramayana-2-47-22', 22, 'Ayodhya Kanda, Sarga 47, Verse 22', 'मन्ये प्रीतिविशिष्टा सा मत्तो लक्ष्मणसारिका।
यस्यास्तच्छ्रूयते वाक्यं शुक पादमरेर्दश॥', 'manye prītiviśiṣṭā sā matto lakṣmaṇasārikā
yasyās tac chrūyate vākyaṃ śuka pādam arer daśa', null, 2047022),
('ramayana-2-47-23', 23, 'Ayodhya Kanda, Sarga 47, Verse 23', 'शोचन्त्याश्चाल्पभाग्याया न किं चिदुपकुर्वता।
पुर्त्रेण किमपुत्राया मया कार्यमरिंदम॥', 'śocantyāś cālpabhāgyāyā na kiṃ cid upakurvatā
purtreṇa kim aputrāyā mayā kāryam ariṃdama', null, 2047023),
('ramayana-2-47-24', 24, 'Ayodhya Kanda, Sarga 47, Verse 24', 'अल्पभाग्या हि मे माता कौसल्या रहिता मया।
शेते परमदुःखार्ता पतिता शोकसागरे॥', 'alpabhāgyā hi me mātā kausalyā rahitā mayā
śete paramaduḥkhārtā patitā śokasāgare', null, 2047024),
('ramayana-2-47-25', 25, 'Ayodhya Kanda, Sarga 47, Verse 25', 'एको ह्यहमयोध्यां च पृथिवीं चापि लक्ष्मण।
तरेयमिषुभिः क्रुद्धो ननु वीर्यमकारणम्॥', 'eko hy aham ayodhyāṃ ca pṛthivīṃ cāpi lakṣmaṇa
tareyam iṣubhiḥ kruddho nanu vīryam akāraṇam', null, 2047025),
('ramayana-2-47-26', 26, 'Ayodhya Kanda, Sarga 47, Verse 26', 'अधर्मभय भीतश्च परलोकस्य चानघ।
तेन लक्ष्मण नाद्याहमात्मानमभिषेचये॥', 'adharmabhaya bhītaś ca paralokasya cānagha
tena lakṣmaṇa nādyāham ātmānam abhiṣecaye', null, 2047026),
('ramayana-2-47-27', 27, 'Ayodhya Kanda, Sarga 47, Verse 27', 'एतदन्यच्च करुणं विलप्य विजने बहु।
अश्रुपूर्णमुखो रामो निशि तूष्णीमुपाविशत्॥', 'etad anyac ca karuṇaṃ vilapya vijane bahu
aśrupūrṇamukho rāmo niśi tūṣṇīm upāviśat', null, 2047027),
('ramayana-2-47-28', 28, 'Ayodhya Kanda, Sarga 47, Verse 28', 'विलप्योपरतं रामं गतार्चिषमिवानलम्।
समुद्रमिव निर्वेगमाश्वासयत लक्ष्मणः॥', 'vilapyoparataṃ rāmaṃ gatārciṣam ivānalam
samudram iva nirvegam āśvāsayata lakṣmaṇaḥ', null, 2047028),
('ramayana-2-47-29', 29, 'Ayodhya Kanda, Sarga 47, Verse 29', 'ध्रुवमद्य पुरी राम अयोध्या युधिनां वर।
निष्प्रभा त्वयि निष्क्रान्ते गतचन्द्रेव शर्वरी॥', 'dhruvam adya purī rāma ayodhyā yudhināṃ vara
niṣprabhā tvayi niṣkrānte gatacandreva śarvarī', null, 2047029),
('ramayana-2-47-30', 30, 'Ayodhya Kanda, Sarga 47, Verse 30', 'नैतदौपयिकं राम यदिदं परितप्यसे।
विषादयसि सीतां च मां चैव पुरुषर्षभ॥', 'naitad aupayikaṃ rāma yad idaṃ paritapyase
viṣādayasi sītāṃ ca māṃ caiva puruṣarṣabha', null, 2047030),
('ramayana-2-47-31', 31, 'Ayodhya Kanda, Sarga 47, Verse 31', 'न च सीता त्वया हीना न चाहमपि राघव।
मुहूर्तमपि जीवावो जलान्मत्स्याविवोद्धृतौ॥', 'na ca sītā tvayā hīnā na cāham api rāghava
muhūrtam api jīvāvo jalān matsyāv ivoddhṛtau', null, 2047031),
('ramayana-2-47-32', 32, 'Ayodhya Kanda, Sarga 47, Verse 32', 'न हि तातं न शत्रुघ्नं न सुमित्रां परंतप।
द्रष्टुमिच्छेयमद्याहं स्वर्गं वापि त्वया विना॥', 'na hi tātaṃ na śatrughnaṃ na sumitrāṃ paraṃtapa
draṣṭum iccheyam adyāhaṃ svargaṃ vāpi tvayā vinā', null, 2047032),
('ramayana-2-47-33', 33, 'Ayodhya Kanda, Sarga 47, Verse 33', 'स लक्ष्मणस्योत्तम पुष्कलं वचो निशम्य चैवं वनवासमादरात्।
समाः समस्ता विदधे परंतपः प्रपद्य धर्मं सुचिराय राघवः॥', 'sa lakṣmaṇasyottama puṣkalaṃ vaco niśamya caivaṃ vanavāsam ādarāt
samāḥ samastā vidadhe paraṃtapaḥ prapadya dharmaṃ sucirāya rāghavaḥ', null, 2047033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 48 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-48-1', 1, 'Ayodhya Kanda, Sarga 48, Verse 1', 'ते तु तस्मिन्महावृक्ष उषित्वा रजनीं शिवाम्।
विमलेऽभ्युदिते सूर्ये तस्माद्देशात्प्रतस्थिरे॥', 'te tu tasmin mahāvṛkṣa uṣitvā rajanīṃ śivām
vimale ''bhyudite sūrye tasmād deśāt pratasthire', null, 2048001),
('ramayana-2-48-2', 2, 'Ayodhya Kanda, Sarga 48, Verse 2', 'यत्र भागीरथी गङ्गा यमुनामभिवर्तते।
जग्मुस्तं देशमुद्दिश्य विगाह्य सुमहद्वनम्॥', 'yatra bhāgīrathī gaṅgā yamunām abhivartate
jagmus taṃ deśam uddiśya vigāhya sumahad vanam', null, 2048002),
('ramayana-2-48-3', 3, 'Ayodhya Kanda, Sarga 48, Verse 3', 'ते भूमिमागान्विविधान्देशांश्चापि मनोरमान्।
अदृष्टपूर्वान्पश्यन्तस्तत्र तत्र यशस्विनः॥', 'te bhūmim āgān vividhān deśāṃś cāpi manoramān
adṛṣṭapūrvān paśyantas tatra tatra yaśasvinaḥ', null, 2048003),
('ramayana-2-48-4', 4, 'Ayodhya Kanda, Sarga 48, Verse 4', 'यथाक्षेमेण गच्छन्स पश्यंश्च विविधान्द्रुमान्।
निवृत्तमात्रे दिवसे रामः सौमित्रिमब्रवीत्॥', 'yathākṣemeṇa gacchan sa paśyaṃś ca vividhān drumān
nivṛttamātre divase rāmaḥ saumitrim abravīt', null, 2048004),
('ramayana-2-48-5', 5, 'Ayodhya Kanda, Sarga 48, Verse 5', 'प्रयागमभितः पश्य सौमित्रे धूममुन्नतम्।
अग्नेर्भगवतः केतुं मन्ये संनिहितो मुनिः॥', 'prayāgam abhitaḥ paśya saumitre dhūmam unnatam
agner bhagavataḥ ketuṃ manye saṃnihito muniḥ', null, 2048005),
('ramayana-2-48-6', 6, 'Ayodhya Kanda, Sarga 48, Verse 6', 'नूनं प्राप्ताः स्म संभेदं गङ्गायमुनयोर्वयम्।
तथा हि श्रूयते शम्ब्दो वारिणा वारिघट्टितः॥', 'nūnaṃ prāptāḥ sma saṃbhedaṃ gaṅgāyamunayor vayam
tathā hi śrūyate śambdo vāriṇā vārighaṭṭitaḥ', null, 2048006),
('ramayana-2-48-7', 7, 'Ayodhya Kanda, Sarga 48, Verse 7', 'दारूणि परिभिन्नानि वनजैरुपजीविभिः।
भरद्वाजाश्रमे चैते दृश्यन्ते विविधा द्रुमाः॥', 'dārūṇi paribhinnāni vanajair upajīvibhiḥ
bharadvājāśrame caite dṛśyante vividhā drumāḥ', null, 2048007),
('ramayana-2-48-8', 8, 'Ayodhya Kanda, Sarga 48, Verse 8', 'धन्विनौ तौ सुखं गत्वा लम्बमाने दिवाकरे।
गङ्गायमुनयोः संधौ प्रापतुर्निलयं मुनेः॥', 'dhanvinau tau sukhaṃ gatvā lambamāne divākare
gaṅgāyamunayoḥ saṃdhau prāpatur nilayaṃ muneḥ', null, 2048008),
('ramayana-2-48-9', 9, 'Ayodhya Kanda, Sarga 48, Verse 9', 'रामस्त्वाश्रममासाद्य त्रासयन्मृगपक्षिणः।
गत्वा मुहूर्तमध्वानं भरद्वाजमुपागमत्॥', 'rāmas tv āśramam āsādya trāsayan mṛgapakṣiṇaḥ
gatvā muhūrtam adhvānaṃ bharadvājam upāgamat', null, 2048009),
('ramayana-2-48-10', 10, 'Ayodhya Kanda, Sarga 48, Verse 10', 'ततस्त्वाश्रममासाद्य मुनेर्दर्शनकाङ्क्षिणौ।
सीतयानुगतौ वीरौ दूरादेवावतस्थतुः॥', 'tatas tv āśramam āsādya muner darśanakāṅkṣiṇau
sītayānugatau vīrau dūrād evāvatasthatuḥ', null, 2048010),
('ramayana-2-48-11', 11, 'Ayodhya Kanda, Sarga 48, Verse 11', 'हुताग्निहोत्रं दृष्ट्वैव महाभागं कृताञ्जलिः।
रामः सौमित्रिणा सार्धं सीतया चाभ्यवादयत्॥', 'hutāgnihotraṃ dṛṣṭvaiva mahābhāgaṃ kṛtāñjaliḥ
rāmaḥ saumitriṇā sārdhaṃ sītayā cābhyavādayat', null, 2048011),
('ramayana-2-48-12', 12, 'Ayodhya Kanda, Sarga 48, Verse 12', 'न्यवेदयत चात्मानं तस्मै लक्ष्मणपूर्वजः।
पुत्रौ दशरथस्यावां भगवन्रामलक्ष्मणौ॥', 'nyavedayata cātmānaṃ tasmai lakṣmaṇapūrvajaḥ
putrau daśarathasyāvāṃ bhagavan rāmalakṣmaṇau', null, 2048012),
('ramayana-2-48-13', 13, 'Ayodhya Kanda, Sarga 48, Verse 13', 'भार्या ममेयं वैदेही कल्याणी जनकात्मजा।
मां चानुयाता विजनं तपोवनमनिन्दिता॥', 'bhāryā mameyaṃ vaidehī kalyāṇī janakātmajā
māṃ cānuyātā vijanaṃ tapovanam aninditā', null, 2048013),
('ramayana-2-48-14', 14, 'Ayodhya Kanda, Sarga 48, Verse 14', 'पित्रा प्रव्राज्यमानं मां सौमित्रिरनुजः प्रियः।
अयमन्वगमद्भ्राता वनमेव दृढव्रतः॥', 'pitrā pravrājyamānaṃ māṃ saumitrir anujaḥ priyaḥ
ayam anvagamad bhrātā vanam eva dṛḍhavrataḥ', null, 2048014),
('ramayana-2-48-15', 15, 'Ayodhya Kanda, Sarga 48, Verse 15', 'पित्रा नियुक्ता भगवन्प्रवेष्यामस्तपोवनम्।
धर्ममेवाचरिष्यामस्तत्र मूलफलाशनाः॥', 'pitrā niyuktā bhagavan praveṣyāmas tapovanam
dharmam evācariṣyāmas tatra mūlaphalāśanāḥ', null, 2048015),
('ramayana-2-48-16', 16, 'Ayodhya Kanda, Sarga 48, Verse 16', 'तस्य तद्वचनं श्रुत्वा राजपुत्रस्य धीमतः।
उपानयत धर्मात्मा गामर्घ्यमुदकं ततः॥', 'tasya tad vacanaṃ śrutvā rājaputrasya dhīmataḥ
upānayata dharmātmā gām arghyam udakaṃ tataḥ', null, 2048016),
('ramayana-2-48-17', 17, 'Ayodhya Kanda, Sarga 48, Verse 17', 'मृगपक्षिभिरासीनो मुनिभिश्च समन्ततः।
राममागतमभ्यर्च्य स्वागतेनाह तं मुनिः॥', 'mṛgapakṣibhir āsīno munibhiś ca samantataḥ
rāmam āgatam abhyarcya svāgatenāha taṃ muniḥ', null, 2048017),
('ramayana-2-48-18', 18, 'Ayodhya Kanda, Sarga 48, Verse 18', 'प्रतिगृह्य च तामर्चामुपविष्टं सराघवम्।
भरद्वाजोऽब्रवीद्वाक्यं धर्मयुक्तमिदं तदा॥', 'pratigṛhya ca tām arcām upaviṣṭaṃ sarāghavam
bharadvājo ''bravīd vākyaṃ dharmayuktam idaṃ tadā', null, 2048018),
('ramayana-2-48-19', 19, 'Ayodhya Kanda, Sarga 48, Verse 19', 'चिरस्य खलु काकुत्स्थ पश्यामि त्वामिहागतम्।
श्रुतं तव मया चेदं विवासनमकारणम्॥', 'cirasya khalu kākutstha paśyāmi tvām ihāgatam
śrutaṃ tava mayā cedaṃ vivāsanam akāraṇam', null, 2048019),
('ramayana-2-48-20', 20, 'Ayodhya Kanda, Sarga 48, Verse 20', 'अवकाशो विविक्तोऽयं महानद्योः समागमे।
पुण्यश्च रमणीयश्च वसत्विह भगान्सुखम्॥', 'avakāśo vivikto ''yaṃ mahānadyoḥ samāgame
puṇyaś ca ramaṇīyaś ca vasatv iha bhagān sukham', null, 2048020),
('ramayana-2-48-21', 21, 'Ayodhya Kanda, Sarga 48, Verse 21', 'एवमुक्तस्तु वचनं भरद्वाजेन राघवः।
प्रत्युवाच शुभं वाक्यं रामः सर्वहिते रतः॥', 'evam uktas tu vacanaṃ bharadvājena rāghavaḥ
pratyuvāca śubhaṃ vākyaṃ rāmaḥ sarvahite rataḥ', null, 2048021),
('ramayana-2-48-22', 22, 'Ayodhya Kanda, Sarga 48, Verse 22', 'भगवन्नित आसन्नः पौरजानपदो जनः।
आगमिष्यति वैदेहीं मां चापि प्रेक्षको जनः।
अनेन कारणेनाहमिह वासं न रोचये॥', 'bhagavann ita āsannaḥ paurajānapado janaḥ
āgamiṣyati vaidehīṃ māṃ cāpi prekṣako janaḥ
anena kāraṇenāham iha vāsaṃ na rocaye', null, 2048022),
('ramayana-2-48-23', 23, 'Ayodhya Kanda, Sarga 48, Verse 23', 'एकान्ते पश्य भगवन्नाश्रमस्थानमुत्तमम्।
रमते यत्र वैदेही सुखार्हा जनकात्मजा॥', 'ekānte paśya bhagavann āśramasthānam uttamam
ramate yatra vaidehī sukhārhā janakātmajā', null, 2048023),
('ramayana-2-48-24', 24, 'Ayodhya Kanda, Sarga 48, Verse 24', 'एतच्छ्रुत्वा शुभं वाक्यं भरद्वाजो महामुनिः।
राघवस्य ततो वाक्यमर्थ ग्राहकमब्रवीत्॥', 'etac chrutvā śubhaṃ vākyaṃ bharadvājo mahāmuniḥ
rāghavasya tato vākyam artha grāhakam abravīt', null, 2048024),
('ramayana-2-48-25', 25, 'Ayodhya Kanda, Sarga 48, Verse 25', 'दशक्रोश इतस्तात गिरिर्यस्मिन्निवत्स्यसि।
महर्षिसेवितः पुण्यः सर्वतः सुख दर्शनः॥', 'daśakrośa itas tāta girir yasmin nivatsyasi
maharṣisevitaḥ puṇyaḥ sarvataḥ sukha darśanaḥ', null, 2048025),
('ramayana-2-48-26', 26, 'Ayodhya Kanda, Sarga 48, Verse 26', 'गोलाङ्गूलानुचरितो वानरर्क्षनिषेवितः।
चित्रकूट इति ख्यातो गन्धमादनसंनिभः॥', 'golāṅgūlānucarito vānararkṣaniṣevitaḥ
citrakūṭa iti khyāto gandhamādanasaṃnibhaḥ', null, 2048026),
('ramayana-2-48-27', 27, 'Ayodhya Kanda, Sarga 48, Verse 27', 'यावता चित्र कूटस्य नरः शृङ्गाण्यवेक्षते।
कल्याणानि समाधत्ते न पापे कुरुते मनः॥', 'yāvatā citra kūṭasya naraḥ śṛṅgāṇy avekṣate
kalyāṇāni samādhatte na pāpe kurute manaḥ', null, 2048027),
('ramayana-2-48-28', 28, 'Ayodhya Kanda, Sarga 48, Verse 28', 'ऋषयस्तत्र बहवो विहृत्य शरदां शतम्।
तपसा दिवमारूढाः कपालशिरसा सह॥', 'ṛṣayas tatra bahavo vihṛtya śaradāṃ śatam
tapasā divam ārūḍhāḥ kapālaśirasā saha', null, 2048028),
('ramayana-2-48-29', 29, 'Ayodhya Kanda, Sarga 48, Verse 29', 'प्रविविक्तमहं मन्ये तं वासं भवतः सुखम्।
इह वा वनवासाय वस राम मया सह॥', 'praviviktam ahaṃ manye taṃ vāsaṃ bhavataḥ sukham
iha vā vanavāsāya vasa rāma mayā saha', null, 2048029),
('ramayana-2-48-30', 30, 'Ayodhya Kanda, Sarga 48, Verse 30', 'स रामं सर्वकामैस्तं भरद्वाजः प्रियातिथिम्।
सभार्यं सह च भ्रात्रा प्रतिजग्राह धर्मवित्॥', 'sa rāmaṃ sarvakāmais taṃ bharadvājaḥ priyātithim
sabhāryaṃ saha ca bhrātrā pratijagrāha dharmavit', null, 2048030),
('ramayana-2-48-31', 31, 'Ayodhya Kanda, Sarga 48, Verse 31', 'तस्य प्रयागे रामस्य तं महर्षिमुपेयुषः।
प्रपन्ना रजनी पुण्या चित्राः कथयतः कथाः॥', 'tasya prayāge rāmasya taṃ maharṣim upeyuṣaḥ
prapannā rajanī puṇyā citrāḥ kathayataḥ kathāḥ', null, 2048031),
('ramayana-2-48-32', 32, 'Ayodhya Kanda, Sarga 48, Verse 32', 'प्रभातायां रजन्यां तु भरद्वाजमुपागमत्।
उवाच नरशार्दूलो मुनिं ज्वलिततेजसं॥', 'prabhātāyāṃ rajanyāṃ tu bharadvājam upāgamat
uvāca naraśārdūlo muniṃ jvalitatejasaṃ', null, 2048032),
('ramayana-2-48-33', 33, 'Ayodhya Kanda, Sarga 48, Verse 33', 'शर्वरीं भवनन्नद्य सत्यशील तवाश्रमे।
उषिताः स्मेह वसतिमनुजानातु नो भवान्॥', 'śarvarīṃ bhavanann adya satyaśīla tavāśrame
uṣitāḥ smeha vasatim anujānātu no bhavān', null, 2048033),
('ramayana-2-48-34', 34, 'Ayodhya Kanda, Sarga 48, Verse 34', 'रात्र्यां तु तस्यां व्युष्टायां भरद्वाजोऽब्रवीदिदम्।
मधुमूलफलोपेतं चित्रकूटं व्रजेति ह॥', 'rātryāṃ tu tasyāṃ vyuṣṭāyāṃ bharadvājo ''bravīd idam
madhumūlaphalopetaṃ citrakūṭaṃ vrajeti ha', null, 2048034),
('ramayana-2-48-35', 35, 'Ayodhya Kanda, Sarga 48, Verse 35', 'तत्र कुञ्जरयूथानि मृगयूथानि चाभितः।
विचरन्ति वनान्तेषु तानि द्रक्ष्यसि राघव॥', 'tatra kuñjarayūthāni mṛgayūthāni cābhitaḥ
vicaranti vanānteṣu tāni drakṣyasi rāghava', null, 2048035),
('ramayana-2-48-36', 36, 'Ayodhya Kanda, Sarga 48, Verse 36', 'प्रहृष्टकोयष्टिककोकिलस्वनैर्विनादितं तं वसुधाधरं शिवम्।
मृगैश्च मत्तैर्बहुभिश्च कुञ्जरैः सुरम्यमासाद्य समावसाश्रमम्॥', 'prahṛṣṭakoyaṣṭikakokilasvanair vināditaṃ taṃ vasudhādharaṃ śivam
mṛgaiś ca mattair bahubhiś ca kuñjaraiḥ suramyam āsādya samāvasāśramam', null, 2048036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 49 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-49-1', 1, 'Ayodhya Kanda, Sarga 49, Verse 1', 'उषित्वा रजनीं तत्र राजपुत्रावरिंदमौ।
महर्षिमभिवाद्याथ जग्मतुस्तं गिरिं प्रति॥', 'uṣitvā rajanīṃ tatra rājaputrāv ariṃdamau
maharṣim abhivādyātha jagmatus taṃ giriṃ prati', null, 2049001),
('ramayana-2-49-2', 2, 'Ayodhya Kanda, Sarga 49, Verse 2', 'प्रस्थितांश्चैव तान्प्रेक्ष्य पिता पुत्रानिवान्वगात्।
ततः प्रचक्रमे वक्तुं वचनं स महामुनिः॥', 'prasthitāṃś caiva tān prekṣya pitā putrān ivānvagāt
tataḥ pracakrame vaktuṃ vacanaṃ sa mahāmuniḥ', null, 2049002),
('ramayana-2-49-3', 3, 'Ayodhya Kanda, Sarga 49, Verse 3', 'अथासाद्य तु कालिन्दीं शीघ्रस्रोतसमापगाम्।
तत्र यूयं प्लवं कृत्वा तरतांशुमतीं नदीम्॥', 'athāsādya tu kālindīṃ śīghrasrotasamāpagām
tatra yūyaṃ plavaṃ kṛtvā taratāṃśumatīṃ nadīm', null, 2049003),
('ramayana-2-49-4', 4, 'Ayodhya Kanda, Sarga 49, Verse 4', 'ततो न्यग्रोधमासाद्य महान्तं हरितच्छदम्।
विवृद्धं बहुभिर्वृक्षैः श्यामं सिद्धोपसेवितम्॥', 'tato nyagrodham āsādya mahāntaṃ haritacchadam
vivṛddhaṃ bahubhir vṛkṣaiḥ śyāmaṃ siddhopasevitam', null, 2049004),
('ramayana-2-49-5', 5, 'Ayodhya Kanda, Sarga 49, Verse 5', 'क्रोशमात्रं ततो गत्वा नीलं द्रक्ष्यथ काननम्।
पलाशबदरीमिश्रं राम वंशैश्च यामुनैः॥', 'krośamātraṃ tato gatvā nīlaṃ drakṣyatha kānanam
palāśabadarīmiśraṃ rāma vaṃśaiś ca yāmunaiḥ', null, 2049005),
('ramayana-2-49-6', 6, 'Ayodhya Kanda, Sarga 49, Verse 6', 'स पन्थाश्चित्रकूटस्य गतः सुबहुशो मया।
रम्यो मार्दवयुक्तश्च वनदावैर्विवर्जितः।
इति पन्थानमावेद्य महर्षिः स न्यवर्तत॥', 'sa panthāś citrakūṭasya gataḥ subahuśo mayā
ramyo mārdavayuktaś ca vanadāvair vivarjitaḥ
iti panthānam āvedya maharṣiḥ sa nyavartata', null, 2049006),
('ramayana-2-49-7', 7, 'Ayodhya Kanda, Sarga 49, Verse 7', 'उपावृत्ते मुनौ तस्मिन्रामो लक्ष्मणमब्रवीत्।
कृतपुण्याः स्म सौमित्रे मुनिर्यन्नोऽनुकम्पते॥', 'upāvṛtte munau tasmin rāmo lakṣmaṇam abravīt
kṛtapuṇyāḥ sma saumitre munir yan no ''nukampate', null, 2049007),
('ramayana-2-49-8', 8, 'Ayodhya Kanda, Sarga 49, Verse 8', 'इति तौ पुरुषव्याघ्रौ मन्त्रयित्वा मनस्विनौ।
सीतामेवाग्रतः कृत्वा कालिन्दीं जग्मतुर्नदीम्॥', 'iti tau puruṣavyāghrau mantrayitvā manasvinau
sītām evāgrataḥ kṛtvā kālindīṃ jagmatur nadīm', null, 2049008),
('ramayana-2-49-9', 9, 'Ayodhya Kanda, Sarga 49, Verse 9', 'तौ काष्ठसंघाटमथो चक्रतुः सुमहाप्लवम्।
चकार लक्ष्मणश्छित्त्वा सीतायाः सुखमानसं॥', 'tau kāṣṭhasaṃghāṭam atho cakratuḥ sumahāplavam
cakāra lakṣmaṇaś chittvā sītāyāḥ sukhamānasaṃ', null, 2049009),
('ramayana-2-49-10', 10, 'Ayodhya Kanda, Sarga 49, Verse 10', 'तत्र श्रियमिवाचिन्त्यां रामो दाशरथिः प्रियाम्।
ईषत्संलज्जमानां तामध्यारोपयत प्लवम्॥', 'tatra śriyam ivācintyāṃ rāmo dāśarathiḥ priyām
īṣatsaṃlajjamānāṃ tām adhyāropayata plavam', null, 2049010),
('ramayana-2-49-11', 11, 'Ayodhya Kanda, Sarga 49, Verse 11', 'ततः प्लवेनांशुमतीं शीघ्रगामूर्मिमालिनीम्।
तीरजैर्बहुभिर्वृक्षैः संतेरुर्यमुनां नदीम्॥', 'tataḥ plavenāṃśumatīṃ śīghragām ūrmimālinīm
tīrajair bahubhir vṛkṣaiḥ saṃterur yamunāṃ nadīm', null, 2049011),
('ramayana-2-49-12', 12, 'Ayodhya Kanda, Sarga 49, Verse 12', 'ते तीर्णाः प्लवमुत्सृज्य प्रस्थाय यमुनावनात्।
श्यामं न्यग्रोधमासेदुः शीतलं हरितच्छदम्॥', 'te tīrṇāḥ plavam utsṛjya prasthāya yamunāvanāt
śyāmaṃ nyagrodham āseduḥ śītalaṃ haritacchadam', null, 2049012),
('ramayana-2-49-13', 13, 'Ayodhya Kanda, Sarga 49, Verse 13', 'कौसल्यां चैव पश्येयं सुमित्रां च यशस्विनीम्।
इति सीताञ्जलिं कृत्वा पर्यगछद्वनस्पतिम्॥', 'kausalyāṃ caiva paśyeyaṃ sumitrāṃ ca yaśasvinīm
iti sītāñjaliṃ kṛtvā paryagachad vanaspatim', null, 2049013),
('ramayana-2-49-14', 14, 'Ayodhya Kanda, Sarga 49, Verse 14', 'क्रोशमात्रं ततो गत्वा भ्रातरौ रामलक्ष्मणौ।
बहून्मेध्यान्मृगान्हत्वा चेरतुर्यमुनावने॥', 'krośamātraṃ tato gatvā bhrātarau rāmalakṣmaṇau
bahūn medhyān mṛgān hatvā ceratur yamunāvane', null, 2049014),
('ramayana-2-49-15', 15, 'Ayodhya Kanda, Sarga 49, Verse 15', 'विहृत्य ते बर्हिणपूगनादिते शुभे वने वारणवानरायुते।
समं नदीवप्रमुपेत्य संमतं निवासमाजग्मुरदीनदर्शनः॥', 'vihṛtya te barhiṇapūganādite śubhe vane vāraṇavānarāyute
samaṃ nadīvapram upetya saṃmataṃ nivāsam ājagmur adīnadarśanaḥ', null, 2049015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 50 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-50-1', 1, 'Ayodhya Kanda, Sarga 50, Verse 1', 'अथ रात्र्यां व्यतीतायामवसुप्तमनन्तरम्।
प्रबोधयामास शनैर्लक्ष्मणं रघुनन्दनः॥', 'atha rātryāṃ vyatītāyām avasuptam anantaram
prabodhayām āsa śanair lakṣmaṇaṃ raghunandanaḥ', null, 2050001),
('ramayana-2-50-2', 2, 'Ayodhya Kanda, Sarga 50, Verse 2', 'सौमित्रे शृणु वन्यानां वल्गु व्याहरतां स्वनम्।
संप्रतिष्ठामहे कालः प्रस्थानस्य परंतप॥', 'saumitre śṛṇu vanyānāṃ valgu vyāharatāṃ svanam
saṃpratiṣṭhāmahe kālaḥ prasthānasya paraṃtapa', null, 2050002),
('ramayana-2-50-3', 3, 'Ayodhya Kanda, Sarga 50, Verse 3', 'स सुप्तः समये भ्रात्रा लक्ष्मणः प्रतिबोधितः।
जहौ निद्रां च तन्द्रीं च प्रसक्तं च पथि श्रमम्॥', 'sa suptaḥ samaye bhrātrā lakṣmaṇaḥ pratibodhitaḥ
jahau nidrāṃ ca tandrīṃ ca prasaktaṃ ca pathi śramam', null, 2050003),
('ramayana-2-50-4', 4, 'Ayodhya Kanda, Sarga 50, Verse 4', 'तत उत्थाय ते सर्वे स्पृष्ट्वा नद्याः शिवं जलम्।
पन्थानमृषिणोद्दिष्टं चित्रकूटस्य तं ययुः॥', 'tata utthāya te sarve spṛṣṭvā nadyāḥ śivaṃ jalam
panthānam ṛṣiṇoddiṣṭaṃ citrakūṭasya taṃ yayuḥ', null, 2050004),
('ramayana-2-50-5', 5, 'Ayodhya Kanda, Sarga 50, Verse 5', 'ततः संप्रस्थितः काले रामः सौमित्रिणा सह।
सीतां कमलपत्राक्षीमिदं वचनमब्रवीत्॥', 'tataḥ saṃprasthitaḥ kāle rāmaḥ saumitriṇā saha
sītāṃ kamalapatrākṣīm idaṃ vacanam abravīt', null, 2050005),
('ramayana-2-50-6', 6, 'Ayodhya Kanda, Sarga 50, Verse 6', 'आदीप्तानिव वैदेहि सर्वतः पुष्पितान्नगान्।
स्वैः पुष्पैः किंशुकान्पश्य मालिनः शिशिरात्यये॥', 'ādīptān iva vaidehi sarvataḥ puṣpitān nagān
svaiḥ puṣpaiḥ kiṃśukān paśya mālinaḥ śiśirātyaye', null, 2050006),
('ramayana-2-50-7', 7, 'Ayodhya Kanda, Sarga 50, Verse 7', 'पश्य भल्लातकान्फुल्लान्नरैरनुपसेवितान्।
फलपत्रैरवनतान्नूनं शक्ष्यामि जीवितुम्॥', 'paśya bhallātakān phullān narair anupasevitān
phalapatrair avanatān nūnaṃ śakṣyāmi jīvitum', null, 2050007),
('ramayana-2-50-8', 8, 'Ayodhya Kanda, Sarga 50, Verse 8', 'पश्य द्रोणप्रमाणानि लम्बमानानि लक्ष्मण।
मधूनि मधुकारीभिः संभृतानि नगे नगे॥', 'paśya droṇapramāṇāni lambamānāni lakṣmaṇa
madhūni madhukārībhiḥ saṃbhṛtāni nage nage', null, 2050008),
('ramayana-2-50-9', 9, 'Ayodhya Kanda, Sarga 50, Verse 9', 'एष क्रोशति नत्यूहस्तं शिखी प्रतिकूजति।
रमणीये वनोद्देशे पुष्पसंस्तरसंकटे॥', 'eṣa krośati natyūhas taṃ śikhī pratikūjati
ramaṇīye vanoddeśe puṣpasaṃstarasaṃkaṭe', null, 2050009),
('ramayana-2-50-10', 10, 'Ayodhya Kanda, Sarga 50, Verse 10', 'मातंगयूथानुसृतं पक्षिसंघानुनादितम्।
चित्रकूटमिमं पश्य प्रवृद्धशिखरं गिरिम्॥', 'mātaṃgayūthānusṛtaṃ pakṣisaṃghānunāditam
citrakūṭam imaṃ paśya pravṛddhaśikharaṃ girim', null, 2050010),
('ramayana-2-50-11', 11, 'Ayodhya Kanda, Sarga 50, Verse 11', 'ततस्तौ पादचारेण गच्छन्तौ सह सीतया।
रम्यमासेदतुः शैलं चित्रकूटं मनोरमम्॥', 'tatas tau pādacāreṇa gacchantau saha sītayā
ramyam āsedatuḥ śailaṃ citrakūṭaṃ manoramam', null, 2050011),
('ramayana-2-50-12', 12, 'Ayodhya Kanda, Sarga 50, Verse 12', 'तं तु पर्वतमासाद्य नानापक्षिगणायुतम्।
अयं वासो भवेत्तावदत्र सौम्य रमेमहि॥', 'taṃ tu parvatam āsādya nānāpakṣigaṇāyutam
ayaṃ vāso bhavet tāvad atra saumya ramemahi', null, 2050012),
('ramayana-2-50-13', 13, 'Ayodhya Kanda, Sarga 50, Verse 13', 'लक्ष्मणानय दारूणि दृढानि च वराणि च।
कुरुष्वावसथं सौम्य वासे मेऽभिरतं मनः॥', 'lakṣmaṇānaya dārūṇi dṛḍhāni ca varāṇi ca
kuruṣvāvasathaṃ saumya vāse me ''bhirataṃ manaḥ', null, 2050013),
('ramayana-2-50-14', 14, 'Ayodhya Kanda, Sarga 50, Verse 14', 'तस्य तद्वचनं श्रुत्वा सौमित्रिर्विविधान्द्रुमान्।
आजहार ततश्चक्रे पर्ण शालामरिं दम॥', 'tasya tad vacanaṃ śrutvā saumitrir vividhān drumān
ājahāra tataś cakre parṇa śālām ariṃ dama', null, 2050014),
('ramayana-2-50-15', 15, 'Ayodhya Kanda, Sarga 50, Verse 15', 'शुश्रूषमाणमेकाग्रमिदं वचनमब्रवीत्।
ऐणेयं मांसमाहृत्य शालां यक्ष्यामहे वयम्॥', 'śuśrūṣamāṇam ekāgram idaṃ vacanam abravīt
aiṇeyaṃ māṃsam āhṛtya śālāṃ yakṣyāmahe vayam', null, 2050015),
('ramayana-2-50-16', 16, 'Ayodhya Kanda, Sarga 50, Verse 16', 'स लक्ष्मणः कृष्णमृगं हत्वा मेध्यं पतापवान्।
अथ चिक्षेप सौमित्रिः समिद्धे जातवेदसि॥', 'sa lakṣmaṇaḥ kṛṣṇamṛgaṃ hatvā medhyaṃ patāpavān
atha cikṣepa saumitriḥ samiddhe jātavedasi', null, 2050016),
('ramayana-2-50-17', 17, 'Ayodhya Kanda, Sarga 50, Verse 17', 'तं तु पक्वं समाज्ञाय निष्टप्तं छिन्नशोणितम्।
लक्ष्मणः पुरुषव्याघ्रमथ राघवमब्रवीत्॥', 'taṃ tu pakvaṃ samājñāya niṣṭaptaṃ chinnaśoṇitam
lakṣmaṇaḥ puruṣavyāghram atha rāghavam abravīt', null, 2050017),
('ramayana-2-50-18', 18, 'Ayodhya Kanda, Sarga 50, Verse 18', 'अयं कृष्णः समाप्ताङ्गः शृतः कृष्ण मृगो यथा।
देवता देवसंकाश यजस्व कुशलो ह्यसि॥', 'ayaṃ kṛṣṇaḥ samāptāṅgaḥ śṛtaḥ kṛṣṇa mṛgo yathā
devatā devasaṃkāśa yajasva kuśalo hy asi', null, 2050018),
('ramayana-2-50-19', 19, 'Ayodhya Kanda, Sarga 50, Verse 19', 'रामः स्नात्वा तु नियतो गुणवाञ्जप्यकोविदः।
पापसंशमनं रामश्चकार बलिमुत्तमम्॥', 'rāmaḥ snātvā tu niyato guṇavāñ japyakovidaḥ
pāpasaṃśamanaṃ rāmaś cakāra balim uttamam', null, 2050019),
('ramayana-2-50-20', 20, 'Ayodhya Kanda, Sarga 50, Verse 20', 'तां वृक्षपर्णच्छदनां मनोज्ञां यथाप्रदेशं सुकृतां निवाताम्।
वासाय सर्वे विविशुः समेताः सभां यथा देव गणाः सुधर्माम्॥', 'tāṃ vṛkṣaparṇac chadanāṃ manojñāṃ yathāpradeśaṃ sukṛtāṃ nivātām
vāsāya sarve viviśuḥ sametāḥ sabhāṃ yathā deva gaṇāḥ sudharmām', null, 2050020),
('ramayana-2-50-21', 21, 'Ayodhya Kanda, Sarga 50, Verse 21', 'अनेकनानामृगपक्षिसंकुले विचित्रपुष्पस्तबलैर्द्रुमैर्युते।
वनोत्तमे व्यालमृगानुनादिते तथा विजह्रुः सुसुखं जितेन्द्रियाः॥', 'anekanānāmṛgapakṣisaṃkule vicitrapuṣpastabalair drumair yute
vanottame vyālamṛgānunādite tathā vijahruḥ susukhaṃ jitendriyāḥ', null, 2050021),
('ramayana-2-50-22', 22, 'Ayodhya Kanda, Sarga 50, Verse 22', 'सुरम्यमासाद्य तु चित्रकूटं नदीं च तां माल्यवतीं सुतीर्थाम्।
ननन्द हृष्टो मृगपक्षिजुष्टां जहौ च दुःखं पुरविप्रवासात्॥', 'suramyam āsādya tu citrakūṭaṃ nadīṃ ca tāṃ mālyavatīṃ sutīrthām
nananda hṛṣṭo mṛgapakṣijuṣṭāṃ jahau ca duḥkhaṃ puravipravāsāt', null, 2050022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 51 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-51-1', 1, 'Ayodhya Kanda, Sarga 51, Verse 1', 'कथयित्वा सुदुःखार्तः सुमन्त्रेण चिरं सह।
रामे दक्षिण कूलस्थे जगाम स्वगृहं गुहः॥', 'kathayitvā suduḥkhārtaḥ sumantreṇa ciraṃ saha
rāme dakṣiṇa kūlasthe jagāma svagṛhaṃ guhaḥ', null, 2051001),
('ramayana-2-51-2', 2, 'Ayodhya Kanda, Sarga 51, Verse 2', 'अनुज्ञातः सुमन्त्रोऽथ योजयित्वा हयोत्तमान्।
अयोध्यामेव नगरीं प्रययौ गाढदुर्मनाः॥', 'anujñātaḥ sumantro ''tha yojayitvā hayottamān
ayodhyām eva nagarīṃ prayayau gāḍhadurmanāḥ', null, 2051002),
('ramayana-2-51-3', 3, 'Ayodhya Kanda, Sarga 51, Verse 3', 'स वनानि सुगन्धीनि सरितश्च सरांसि च।
पश्यन्नतिययौ शीघ्रं ग्रामाणि नगराणि च॥', 'sa vanāni sugandhīni saritaś ca sarāṃsi ca
paśyann atiyayau śīghraṃ grāmāṇi nagarāṇi ca', null, 2051003),
('ramayana-2-51-4', 4, 'Ayodhya Kanda, Sarga 51, Verse 4', 'ततः सायाह्नसमये तृतीयेऽहनि सारथिः।
अयोध्यां समनुप्राप्य निरानन्दां ददर्श ह॥', 'tataḥ sāyāhnasamaye tṛtīye ''hani sārathiḥ
ayodhyāṃ samanuprāpya nirānandāṃ dadarśa ha', null, 2051004),
('ramayana-2-51-5', 5, 'Ayodhya Kanda, Sarga 51, Verse 5', 'स शून्यामिव निःशब्दां दृष्ट्वा परमदुर्मनाः।
सुमन्त्रश्चिन्तयामास शोकवेगसमाहतः॥', 'sa śūnyām iva niḥśabdāṃ dṛṣṭvā paramadurmanāḥ
sumantraś cintayām āsa śokavegasamāhataḥ', null, 2051005),
('ramayana-2-51-6', 6, 'Ayodhya Kanda, Sarga 51, Verse 6', 'कच्चिन्न सगजा साश्वा सजना सजनाधिपा।
रामसंतापदुःखेन दग्धा शोकाग्निना पुरी।
इति चिन्तापरः सूतस्त्वरितः प्रविवेश ह॥', 'kaccin na sagajā sāśvā sajanā sajanādhipā
rāmasaṃtāpaduḥkhena dagdhā śokāgninā purī
iti cintāparaḥ sūtas tvaritaḥ praviveśa ha', null, 2051006),
('ramayana-2-51-7', 7, 'Ayodhya Kanda, Sarga 51, Verse 7', 'सुमन्त्रमभियान्तं तं शतशोऽथ सहस्रशः।
क्व राम इति पृच्छन्तः सूतमभ्यद्रवन्नराः॥', 'sumantram abhiyāntaṃ taṃ śataśo ''tha sahasraśaḥ
kva rāma iti pṛcchantaḥ sūtam abhyadravan narāḥ', null, 2051007),
('ramayana-2-51-8', 8, 'Ayodhya Kanda, Sarga 51, Verse 8', 'तेषां शशंस गङ्गायामहमापृच्छ्य राघवम्।
अनुज्ञातो निवृत्तोऽस्मि धार्मिकेण महात्मना॥', 'teṣāṃ śaśaṃsa gaṅgāyām aham āpṛcchya rāghavam
anujñāto nivṛtto ''smi dhārmikeṇa mahātmanā', null, 2051008),
('ramayana-2-51-9', 9, 'Ayodhya Kanda, Sarga 51, Verse 9', 'ते तीर्णा इति विज्ञाय बाष्पपूर्णमुखा जनाः।
अहो धिगिति निःश्वस्य हा रामेति च चुक्रुशुः॥', 'te tīrṇā iti vijñāya bāṣpapūrṇamukhā janāḥ
aho dhig iti niḥśvasya hā rāmeti ca cukruśuḥ', null, 2051009),
('ramayana-2-51-10', 10, 'Ayodhya Kanda, Sarga 51, Verse 10', 'शुश्राव च वचस्तेषां वृन्दं वृन्दं च तिष्ठताम्।
हताः स्म खलु ये नेह पश्याम इति राघवम्॥', 'śuśrāva ca vacas teṣāṃ vṛndaṃ vṛndaṃ ca tiṣṭhatām
hatāḥ sma khalu ye neha paśyāma iti rāghavam', null, 2051010),
('ramayana-2-51-11', 11, 'Ayodhya Kanda, Sarga 51, Verse 11', 'दानयज्ञविवाहेषु समाजेषु महत्सु च।
न द्रक्ष्यामः पुनर्जातु धार्मिकं राममन्तरा॥', 'dānayajñavivāheṣu samājeṣu mahatsu ca
na drakṣyāmaḥ punar jātu dhārmikaṃ rāmam antarā', null, 2051011),
('ramayana-2-51-12', 12, 'Ayodhya Kanda, Sarga 51, Verse 12', 'किं समर्थं जनस्यास्य किं प्रियं किं सुखावहम्।
इति रामेण नगरं पितृवत्परिपालितम्॥', 'kiṃ samarthaṃ janasyāsya kiṃ priyaṃ kiṃ sukhāvaham
iti rāmeṇa nagaraṃ pitṛvat paripālitam', null, 2051012),
('ramayana-2-51-13', 13, 'Ayodhya Kanda, Sarga 51, Verse 13', 'वातायनगतानां च स्त्रीणामन्वन्तरापणम्।
रामशोकाभितप्तानां शुश्राव परिदेवनम्॥', 'vātāyanagatānāṃ ca strīṇām anvantarāpaṇam
rāmaśokābhitaptānāṃ śuśrāva paridevanam', null, 2051013),
('ramayana-2-51-14', 14, 'Ayodhya Kanda, Sarga 51, Verse 14', 'स राजमार्गमध्येन सुमन्त्रः पिहिताननः।
यत्र राजा दशरथस्तदेवोपययौ गृहम्॥', 'sa rājamārgamadhyena sumantraḥ pihitānanaḥ
yatra rājā daśarathas tad evopayayau gṛham', null, 2051014),
('ramayana-2-51-15', 15, 'Ayodhya Kanda, Sarga 51, Verse 15', 'सोऽवतीर्य रथाच्छीघ्रं राजवेश्म प्रविश्य च।
कक्ष्याः सप्ताभिचक्राम महाजनसमाकुलाः॥', 'so ''vatīrya rathāc chīghraṃ rājaveśma praviśya ca
kakṣyāḥ saptābhicakrāma mahājanasamākulāḥ', null, 2051015),
('ramayana-2-51-16', 16, 'Ayodhya Kanda, Sarga 51, Verse 16', 'ततो दशरथस्त्रीणां प्रासादेभ्यस्ततस्ततः।
रामशोकाभितप्तानां मन्दं शुश्राव जल्पितम्॥', 'tato daśarathastrīṇāṃ prāsādebhyas tatas tataḥ
rāmaśokābhitaptānāṃ mandaṃ śuśrāva jalpitam', null, 2051016),
('ramayana-2-51-17', 17, 'Ayodhya Kanda, Sarga 51, Verse 17', 'सह रामेण निर्यातो विना राममिहागतः।
सूतः किं नाम कौसल्यां शोचन्तीं प्रतिवक्ष्यति॥', 'saha rāmeṇa niryāto vinā rāmam ihāgataḥ
sūtaḥ kiṃ nāma kausalyāṃ śocantīṃ prativakṣyati', null, 2051017),
('ramayana-2-51-18', 18, 'Ayodhya Kanda, Sarga 51, Verse 18', 'यथा च मन्ये दुर्जीवमेवं न सुकरं ध्रुवम्।
आच्छिद्य पुत्रे निर्याते कौसल्या यत्र जीवति॥', 'yathā ca manye durjīvam evaṃ na sukaraṃ dhruvam
ācchidya putre niryāte kausalyā yatra jīvati', null, 2051018),
('ramayana-2-51-19', 19, 'Ayodhya Kanda, Sarga 51, Verse 19', 'सत्य रूपं तु तद्वाक्यं राज्ञः स्त्रीणां निशामयन्।
प्रदीप्तमिव शोकेन विवेश सहसा गृहम्॥', 'satya rūpaṃ tu tadvākyaṃ rājñaḥ strīṇāṃ niśāmayan
pradīptam iva śokena viveśa sahasā gṛham', null, 2051019),
('ramayana-2-51-20', 20, 'Ayodhya Kanda, Sarga 51, Verse 20', 'स प्रविश्याष्टमीं कक्ष्यां राजानं दीनमातुलम्।
पुत्रशोकपरिद्यूनमपश्यत्पाण्डरे गृहे॥', 'sa praviśyāṣṭamīṃ kakṣyāṃ rājānaṃ dīnam ātulam
putraśokaparidyūnam apaśyat pāṇḍare gṛhe', null, 2051020),
('ramayana-2-51-21', 21, 'Ayodhya Kanda, Sarga 51, Verse 21', 'अभिगम्य तमासीनं नरेन्द्रमभिवाद्य च।
सुमन्त्रो रामवचनं यथोक्तं प्रत्यवेदयत्॥', 'abhigamya tam āsīnaṃ narendram abhivādya ca
sumantro rāmavacanaṃ yathoktaṃ pratyavedayat', null, 2051021),
('ramayana-2-51-22', 22, 'Ayodhya Kanda, Sarga 51, Verse 22', 'स तूष्णीमेव तच्छ्रुत्वा राजा विभ्रान्त चेतनः।
मूर्छितो न्यपतद्भूमौ रामशोकाभिपीडितः॥', 'sa tūṣṇīm eva tac chrutvā rājā vibhrānta cetanaḥ
mūrchito nyapatad bhūmau rāmaśokābhipīḍitaḥ', null, 2051022),
('ramayana-2-51-23', 23, 'Ayodhya Kanda, Sarga 51, Verse 23', 'ततोऽन्तःपुरमाविद्धं मूर्छिते पृथिवीपतौ।
उद्धृत्य बाहू चुक्रोश नृपतौ पतिते क्षितौ॥', 'tato ''ntaḥpuram āviddhaṃ mūrchite pṛthivīpatau
uddhṛtya bāhū cukrośa nṛpatau patite kṣitau', null, 2051023),
('ramayana-2-51-24', 24, 'Ayodhya Kanda, Sarga 51, Verse 24', 'सुमित्रया तु सहिता कौसल्या पतितं पतिम्।
उत्थापयामास तदा वचनं चेदमब्रवीत्॥', 'sumitrayā tu sahitā kausalyā patitaṃ patim
utthāpayām āsa tadā vacanaṃ cedam abravīt', null, 2051024),
('ramayana-2-51-25', 25, 'Ayodhya Kanda, Sarga 51, Verse 25', 'इमं तस्य महाभाग दूतं दुष्करकारिणः।
वनवासादनुप्राप्तं कस्मान्न प्रतिभाषसे॥', 'imaṃ tasya mahābhāga dūtaṃ duṣkarakāriṇaḥ
vanavāsād anuprāptaṃ kasmān na pratibhāṣase', null, 2051025),
('ramayana-2-51-26', 26, 'Ayodhya Kanda, Sarga 51, Verse 26', 'अद्येममनयं कृत्वा व्यपत्रपसि राघव।
उत्तिष्ठ सुकृतं तेऽस्तु शोके न स्यात्सहायता॥', 'adyemam anayaṃ kṛtvā vyapatrapasi rāghava
uttiṣṭha sukṛtaṃ te ''stu śoke na syāt sahāyatā', null, 2051026),
('ramayana-2-51-27', 27, 'Ayodhya Kanda, Sarga 51, Verse 27', 'देव यस्या भयाद्रामं नानुपृच्छसि सारथिम्।
नेह तिष्ठति कैकेयी विश्रब्धं प्रतिभाष्यताम्॥', 'deva yasyā bhayād rāmaṃ nānupṛcchasi sārathim
neha tiṣṭhati kaikeyī viśrabdhaṃ pratibhāṣyatām', null, 2051027),
('ramayana-2-51-28', 28, 'Ayodhya Kanda, Sarga 51, Verse 28', 'सा तथोक्त्वा महाराजं कौसल्या शोकलालसा।
धरण्यां निपपाताशु बाष्पविप्लुतभाषिणी॥', 'sā tathoktvā mahārājaṃ kausalyā śokalālasā
dharaṇyāṃ nipapātāśu bāṣpaviplutabhāṣiṇī', null, 2051028),
('ramayana-2-51-29', 29, 'Ayodhya Kanda, Sarga 51, Verse 29', 'एवं विलपतीं दृष्ट्वा कौसल्यां पतितां भुवि।
पतिं चावेक्ष्य ताः सर्वाः सस्वरं रुरुदुः स्त्रियः॥', 'evaṃ vilapatīṃ dṛṣṭvā kausalyāṃ patitāṃ bhuvi
patiṃ cāvekṣya tāḥ sarvāḥ sasvaraṃ ruruduḥ striyaḥ', null, 2051029),
('ramayana-2-51-30', 30, 'Ayodhya Kanda, Sarga 51, Verse 30', 'ततस्तमन्तःपुरनादमुत्थितं समीक्ष्य वृद्धास्तरुणाश्च मानवाः।
स्त्रियश्च सर्वा रुरुदुः समन्ततः पुरं तदासीत्पुनरेव संकुलम्॥', 'tatas tam antaḥpuranādam utthitaṃ samīkṣya vṛddhās taruṇāś ca mānavāḥ
striyaś ca sarvā ruruduḥ samantataḥ puraṃ tadāsīt punar eva saṃkulam', null, 2051030)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 52 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-52-1', 1, 'Ayodhya Kanda, Sarga 52, Verse 1', 'प्रत्याश्वस्तो यदा राजा मोहात्प्रत्यागतः पुनः।
अथाजुहाव तं सूतं रामवृत्तान्तकारणात्॥', 'pratyāśvasto yadā rājā mohāt pratyāgataḥ punaḥ
athājuhāva taṃ sūtaṃ rāmavṛttāntakāraṇāt', null, 2052001),
('ramayana-2-52-2', 2, 'Ayodhya Kanda, Sarga 52, Verse 2', 'वृद्धं परमसंतप्तं नवग्रहमिव द्विपम्।
विनिःश्वसन्तं ध्यायन्तमस्वस्थमिव कुञ्जरम्॥', 'vṛddhaṃ paramasaṃtaptaṃ navagraham iva dvipam
viniḥśvasantaṃ dhyāyantam asvastham iva kuñjaram', null, 2052002),
('ramayana-2-52-3', 3, 'Ayodhya Kanda, Sarga 52, Verse 3', 'राजा तु रजसा सूतं ध्वस्ताङ्गं समुपस्थितम्।
अश्रुपूर्णमुखं दीनमुवाच परमार्तवत्॥', 'rājā tu rajasā sūtaṃ dhvastāṅgaṃ samupasthitam
aśrupūrṇamukhaṃ dīnam uvāca paramārtavat', null, 2052003),
('ramayana-2-52-4', 4, 'Ayodhya Kanda, Sarga 52, Verse 4', 'क्व नु वत्स्यति धर्मात्मा वृक्षमूलमुपाश्रितः।
सोऽत्यन्तसुखितः सूत किमशिष्यति राघवः।
भूमिपालात्मजो भूमौ शेते कथमनाथवत्॥', 'kva nu vatsyati dharmātmā vṛkṣamūlam upāśritaḥ
so ''tyantasukhitaḥ sūta kim aśiṣyati rāghavaḥ
bhūmipālātmajo bhūmau śete katham anāthavat', null, 2052004),
('ramayana-2-52-5', 5, 'Ayodhya Kanda, Sarga 52, Verse 5', 'यं यान्तमनुयान्ति स्म पदाति रथकुञ्जराः।
स वत्स्यति कथं रामो विजनं वनमाश्रितः॥', 'yaṃ yāntam anuyānti sma padāti rathakuñjarāḥ
sa vatsyati kathaṃ rāmo vijanaṃ vanam āśritaḥ', null, 2052005),
('ramayana-2-52-6', 6, 'Ayodhya Kanda, Sarga 52, Verse 6', 'व्यालैर्मृगैराचरितं कृष्णसर्पनिषेवितम्।
कथं कुमारौ वैदेह्या सार्धं वनमुपस्थितौ॥', 'vyālair mṛgair ācaritaṃ kṛṣṇasarpaniṣevitam
kathaṃ kumārau vaidehyā sārdhaṃ vanam upasthitau', null, 2052006),
('ramayana-2-52-7', 7, 'Ayodhya Kanda, Sarga 52, Verse 7', 'सुकुमार्या तपस्विन्या सुमन्त्र सह सीतया।
राजपुत्रौ कथं पादैरवरुह्य रथाद्गतौ॥', 'sukumāryā tapasvinyā sumantra saha sītayā
rājaputrau kathaṃ pādair avaruhya rathād gatau', null, 2052007),
('ramayana-2-52-8', 8, 'Ayodhya Kanda, Sarga 52, Verse 8', 'सिद्धार्थः खलु सूत त्वं येन दृष्टौ ममात्मजौ।
वनान्तं प्रविशन्तौ तावश्विनाविव मन्दरम्॥', 'siddhārthaḥ khalu sūta tvaṃ yena dṛṣṭau mamātmajau
vanāntaṃ praviśantau tāv aśvināv iva mandaram', null, 2052008),
('ramayana-2-52-9', 9, 'Ayodhya Kanda, Sarga 52, Verse 9', 'किमुवाच वचो रामः किमुवाच च लक्ष्मणः।
सुमन्त्र वनमासाद्य किमुवाच च मैथिली।
आसितं शयितं भुक्तं सूत रामस्य कीर्तय॥', 'kim uvāca vaco rāmaḥ kim uvāca ca lakṣmaṇaḥ
sumantra vanam āsādya kim uvāca ca maithilī
āsitaṃ śayitaṃ bhuktaṃ sūta rāmasya kīrtaya', null, 2052009),
('ramayana-2-52-10', 10, 'Ayodhya Kanda, Sarga 52, Verse 10', 'इति सूतो नरेन्द्रेण चोदितः सज्जमानया।
उवाच वाचा राजानं सबाष्पपरिरब्धया॥', 'iti sūto narendreṇa coditaḥ sajjamānayā
uvāca vācā rājānaṃ sabāṣpaparirabdhayā', null, 2052010),
('ramayana-2-52-11', 11, 'Ayodhya Kanda, Sarga 52, Verse 11', 'अब्रवीन्मां महाराज धर्ममेवानुपालयन्।
अञ्जलिं राघवः कृत्वा शिरसाभिप्रणम्य च॥', 'abravīn māṃ mahārāja dharmam evānupālayan
añjaliṃ rāghavaḥ kṛtvā śirasābhipraṇamya ca', null, 2052011),
('ramayana-2-52-12', 12, 'Ayodhya Kanda, Sarga 52, Verse 12', 'सूत मद्वचनात्तस्य तातस्य विदितात्मनः।
शिरसा वन्दनीयस्य वन्द्यौ पादौ महात्मनः॥', 'sūta madvacanāt tasya tātasya viditātmanaḥ
śirasā vandanīyasya vandyau pādau mahātmanaḥ', null, 2052012),
('ramayana-2-52-13', 13, 'Ayodhya Kanda, Sarga 52, Verse 13', 'सर्वमन्तःपुरं वाच्यं सूत मद्वचनात्त्वया।
आरोग्यमविशेषेण यथार्हं चाभिवादनम्॥', 'sarvam antaḥpuraṃ vācyaṃ sūta mad vacanāt tvayā
ārogyam aviśeṣeṇa yathārhaṃ cābhivādanam', null, 2052013),
('ramayana-2-52-14', 14, 'Ayodhya Kanda, Sarga 52, Verse 14', 'माता च मम कौसल्या कुशलं चाभिवादनम्।
देवि देवस्य पादौ च देववत्परिपालय॥', 'mātā ca mama kausalyā kuśalaṃ cābhivādanam
devi devasya pādau ca devavat paripālaya', null, 2052014),
('ramayana-2-52-15', 15, 'Ayodhya Kanda, Sarga 52, Verse 15', 'भरतः कुशलं वाच्यो वाच्यो मद्वचनेन च।
सर्वास्वेव यथान्यायं वृत्तिं वर्तस्व मातृषु॥', 'bharataḥ kuśalaṃ vācyo vācyo madvacanena ca
sarvāsv eva yathānyāyaṃ vṛttiṃ vartasva mātṛṣu', null, 2052015),
('ramayana-2-52-16', 16, 'Ayodhya Kanda, Sarga 52, Verse 16', 'वक्तव्यश्च महाबाहुरिक्ष्वाकुकुलनन्दनः।
पितरं यौवराज्यस्थो राज्यस्थमनुपालय॥', 'vaktavyaś ca mahābāhur ikṣvākukulanandanaḥ
pitaraṃ yauvarājyastho rājyastham anupālaya', null, 2052016),
('ramayana-2-52-17', 17, 'Ayodhya Kanda, Sarga 52, Verse 17', 'इत्येवं मां महाराज ब्रुवन्नेव महायशाः।
रामो राजीवताम्राक्षो भृशमश्रूण्यवर्तयत्॥', 'ity evaṃ māṃ mahārāja bruvann eva mahāyaśāḥ
rāmo rājīvatāmrākṣo bhṛśam aśrūṇy avartayat', null, 2052017),
('ramayana-2-52-18', 18, 'Ayodhya Kanda, Sarga 52, Verse 18', 'लक्ष्मणस्तु सुसंक्रुद्धो निःश्वसन्वाक्यमब्रवीत्।
केनायमपराधेन राजपुत्रो विवासितः॥', 'lakṣmaṇas tu susaṃkruddho niḥśvasan vākyam abravīt
kenāyam aparādhena rājaputro vivāsitaḥ', null, 2052018),
('ramayana-2-52-19', 19, 'Ayodhya Kanda, Sarga 52, Verse 19', 'यदि प्रव्राजितो रामो लोभकारणकारितम्।
वरदाननिमित्तं वा सर्वथा दुष्कृतं कृतम्।
रामस्य तु परित्यागे न हेतुमुपलक्षये॥', 'yadi pravrājito rāmo lobhakāraṇakāritam
varadānanimittaṃ vā sarvathā duṣkṛtaṃ kṛtam
rāmasya tu parityāge na hetum upalakṣaye', null, 2052019),
('ramayana-2-52-20', 20, 'Ayodhya Kanda, Sarga 52, Verse 20', 'असमीक्ष्य समारब्धं विरुद्धं बुद्धिलाघवात्।
जनयिष्यति संक्रोशं राघवस्य विवासनम्॥', 'asamīkṣya samārabdhaṃ viruddhaṃ buddhilāghavāt
janayiṣyati saṃkrośaṃ rāghavasya vivāsanam', null, 2052020),
('ramayana-2-52-21', 21, 'Ayodhya Kanda, Sarga 52, Verse 21', 'अहं तावन्महाराजे पितृत्वं नोपलक्षये।
भ्राता भर्ता च बन्धुश्च पिता च मम राघवः॥', 'ahaṃ tāvan mahārāje pitṛtvaṃ nopalakṣaye
bhrātā bhartā ca bandhuś ca pitā ca mama rāghavaḥ', null, 2052021),
('ramayana-2-52-22', 22, 'Ayodhya Kanda, Sarga 52, Verse 22', 'सर्वलोकप्रियं त्यक्त्वा सर्वलोकहिते रतम्।
सर्वलोकोऽनुरज्येत कथं त्वानेन कर्मणा॥', 'sarvalokapriyaṃ tyaktvā sarvalokahite ratam
sarvaloko ''nurajyeta kathaṃ tvānena karmaṇā', null, 2052022),
('ramayana-2-52-23', 23, 'Ayodhya Kanda, Sarga 52, Verse 23', 'जानकी तु महाराज निःश्वसन्ती तपस्विनी।
भूतोपहतचित्तेव विष्ठिता वृष्मृता स्थिता॥', 'jānakī tu mahārāja niḥśvasantī tapasvinī
bhūtopahatacitteva viṣṭhitā vṛṣmṛtā sthitā', null, 2052023),
('ramayana-2-52-24', 24, 'Ayodhya Kanda, Sarga 52, Verse 24', 'अदृष्टपूर्वव्यसना राजपुत्री यशस्विनी।
तेन दुःखेन रुदती नैव मां किं चिदब्रवीत्॥', 'adṛṣṭapūrvavyasanā rājaputrī yaśasvinī
tena duḥkhena rudatī naiva māṃ kiṃ cid abravīt', null, 2052024),
('ramayana-2-52-25', 25, 'Ayodhya Kanda, Sarga 52, Verse 25', 'उद्वीक्षमाणा भर्तारं मुखेन परिशुष्यता।
मुमोच सहसा बाष्पं मां प्रयान्तमुदीक्ष्य सा॥', 'udvīkṣamāṇā bhartāraṃ mukhena pariśuṣyatā
mumoca sahasā bāṣpaṃ māṃ prayāntam udīkṣya sā', null, 2052025),
('ramayana-2-52-26', 26, 'Ayodhya Kanda, Sarga 52, Verse 26', 'तथैव रामोऽश्रुमुखः कृताञ्जलिः स्थितोऽभवल्लक्ष्मणबाहुपालितः।
तथैव सीता रुदती तपस्विनी निरीक्षते राजरथं तथैव माम्॥', 'tathaiva rāmo ''śrumukhaḥ kṛtāñjaliḥ sthito ''bhaval lakṣmaṇabāhupālitaḥ
tathaiva sītā rudatī tapasvinī nirīkṣate rājarathaṃ tathaiva mām', null, 2052026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 53 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-53-1', 1, 'Ayodhya Kanda, Sarga 53, Verse 1', 'मम त्वश्वा निवृत्तस्य न प्रावर्तन्त वर्त्मनि।
उष्णमश्रु विमुञ्चन्तो रामे संप्रस्थिते वनम्॥', 'mama tv aśvā nivṛttasya na prāvartanta vartmani
uṣṇam aśru vimuñcanto rāme saṃprasthite vanam', null, 2053001),
('ramayana-2-53-2', 2, 'Ayodhya Kanda, Sarga 53, Verse 2', 'उभाभ्यां राजपुत्राभ्यामथ कृत्वाहमज्ञलिम्।
प्रस्थितो रथमास्थाय तद्दुःखमपि धारयन्॥', 'ubhābhyāṃ rājaputrābhyām atha kṛtvāham ajñalim
prasthito ratham āsthāya tad duḥkham api dhārayan', null, 2053002),
('ramayana-2-53-3', 3, 'Ayodhya Kanda, Sarga 53, Verse 3', 'गुहेव सार्धं तत्रैव स्थितोऽस्मि दिवसान्बहून्।
आशया यदि मां रामः पुनः शब्दापयेदिति॥', 'guheva sārdhaṃ tatraiva sthito ''smi divasān bahūn
āśayā yadi māṃ rāmaḥ punaḥ śabdāpayed iti', null, 2053003),
('ramayana-2-53-4', 4, 'Ayodhya Kanda, Sarga 53, Verse 4', 'विषये ते महाराज रामव्यसनकर्शिताः।
अपि वृक्षाः परिम्लानः सपुष्पाङ्कुरकोरकाः॥', 'viṣaye te mahārāja rāmavyasanakarśitāḥ
api vṛkṣāḥ parimlānaḥ sapuṣpāṅkurakorakāḥ', null, 2053004),
('ramayana-2-53-5', 5, 'Ayodhya Kanda, Sarga 53, Verse 5', 'न च सर्पन्ति सत्त्वानि व्याला न प्रसरन्ति च।
रामशोकाभिभूतं तन्निष्कूजमभवद्वनम्॥', 'na ca sarpanti sattvāni vyālā na prasaranti ca
rāmaśokābhibhūtaṃ tan niṣkūjam abhavad vanam', null, 2053005),
('ramayana-2-53-6', 6, 'Ayodhya Kanda, Sarga 53, Verse 6', 'लीनपुष्करपत्राश्च नरेन्द्र कलुषोदकाः।
संतप्तपद्माः पद्मिन्यो लीनमीनविहंगमाः॥', 'līnapuṣkarapatrāś ca narendra kaluṣodakāḥ
saṃtaptapadmāḥ padminyo līnamīnavihaṃgamāḥ', null, 2053006),
('ramayana-2-53-7', 7, 'Ayodhya Kanda, Sarga 53, Verse 7', 'जलजानि च पुष्पाणि माल्यानि स्थलजानि च।
नाद्य भान्त्यल्पगन्धीनि फलानि च यथा पुरम्॥', 'jalajāni ca puṣpāṇi mālyāni sthalajāni ca
nādya bhānty alpagandhīni phalāni ca yathā puram', null, 2053007),
('ramayana-2-53-8', 8, 'Ayodhya Kanda, Sarga 53, Verse 8', 'प्रविशन्तमयोध्यां मां न कश्चिदभिनन्दति।
नरा राममपश्यन्तो निःश्वसन्ति मुहुर्मुहुः॥', 'praviśantam ayodhyāṃ māṃ na kaś cid abhinandati
narā rāmam apaśyanto niḥśvasanti muhur muhuḥ', null, 2053008),
('ramayana-2-53-9', 9, 'Ayodhya Kanda, Sarga 53, Verse 9', 'हर्म्यैर्विमानैः प्रासादैरवेक्ष्य रथमागतम्।
हाहाकारकृता नार्यो रामादर्शनकर्शिताः॥', 'harmyair vimānaiḥ prāsādair avekṣya ratham āgatam
hāhākārakṛtā nāryo rāmādarśanakarśitāḥ', null, 2053009),
('ramayana-2-53-10', 10, 'Ayodhya Kanda, Sarga 53, Verse 10', 'आयतैर्विमलैर्नेत्रैरश्रुवेगपरिप्लुतैः।
अन्योन्यमभिवीक्षन्ते व्यक्तमार्ततराः स्त्रियः॥', 'āyatair vimalair netrair aśruvegapariplutaiḥ
anyonyam abhivīkṣante vyaktam ārtatarāḥ striyaḥ', null, 2053010),
('ramayana-2-53-11', 11, 'Ayodhya Kanda, Sarga 53, Verse 11', 'नामित्राणां न मित्राणामुदासीनजनस्य च।
अहमार्ततया कं चिद्विशेषं नोपलक्षये॥', 'nāmitrāṇāṃ na mitrāṇām udāsīnajanasya ca
aham ārtatayā kaṃ cid viśeṣaṃ nopalakṣaye', null, 2053011),
('ramayana-2-53-12', 12, 'Ayodhya Kanda, Sarga 53, Verse 12', 'अप्रहृष्टमनुष्या च दीननागतुरंगमा।
आर्तस्वरपरिम्लाना विनिःश्वसितनिःस्वना॥', 'aprahṛṣṭamanuṣyā ca dīnanāgaturaṃgamā
ārtasvaraparimlānā viniḥśvasitaniḥsvanā', null, 2053012),
('ramayana-2-53-13', 13, 'Ayodhya Kanda, Sarga 53, Verse 13', 'निरानन्दा महाराज रामप्रव्राजनातुला।
कौसल्या पुत्र हीनेव अयोध्या प्रतिभाति मा॥', 'nirānandā mahārāja rāmapravrājanātulā
kausalyā putra hīneva ayodhyā pratibhāti mā', null, 2053013),
('ramayana-2-53-14', 14, 'Ayodhya Kanda, Sarga 53, Verse 14', 'सूतस्य वचनं श्रुत्वा वाचा परमदीनया।
बाष्पोपहतया राजा तं सूतमिदमब्रवीत्॥', 'sūtasya vacanaṃ śrutvā vācā paramadīnayā
bāṣpopahatayā rājā taṃ sūtam idam abravīt', null, 2053014),
('ramayana-2-53-15', 15, 'Ayodhya Kanda, Sarga 53, Verse 15', 'कैकेय्या विनियुक्तेन पापाभिजनभावया।
मया न मन्त्रकुशलैर्वृद्धैः सह समर्थितम्॥', 'kaikeyyā viniyuktena pāpābhijanabhāvayā
mayā na mantrakuśalair vṛddhaiḥ saha samarthitam', null, 2053015),
('ramayana-2-53-16', 16, 'Ayodhya Kanda, Sarga 53, Verse 16', 'न सुहृद्भिर्न चामात्यैर्मन्त्रयित्वा न नैगमैः।
मयायमर्थः संमोहात्स्त्रीहेतोः सहसा कृतः॥', 'na suhṛdbhir na cāmātyair mantrayitvā na naigamaiḥ
mayāyam arthaḥ saṃmohāt strīhetoḥ sahasā kṛtaḥ', null, 2053016),
('ramayana-2-53-17', 17, 'Ayodhya Kanda, Sarga 53, Verse 17', 'भवितव्यतया नूनमिदं वा व्यसनं महत्।
कुलस्यास्य विनाशाय प्राप्तं सूत यदृच्छया॥', 'bhavitavyatayā nūnam idaṃ vā vyasanaṃ mahat
kulasyāsya vināśāya prāptaṃ sūta yadṛcchayā', null, 2053017),
('ramayana-2-53-18', 18, 'Ayodhya Kanda, Sarga 53, Verse 18', 'सूत यद्यस्ति ते किं चिन्मयापि सुकृतं कृतम्।
त्वं प्रापयाशु मां रामं प्राणाः संत्वरयन्ति माम्॥', 'sūta yady asti te kiṃ cin mayāpi sukṛtaṃ kṛtam
tvaṃ prāpayāśu māṃ rāmaṃ prāṇāḥ saṃtvarayanti mām', null, 2053018),
('ramayana-2-53-19', 19, 'Ayodhya Kanda, Sarga 53, Verse 19', 'यद्यद्यापि ममैवाज्ञा निवर्तयतु राघवम्।
न शक्ष्यामि विना राम मुहूर्तमपि जीवितुम्॥', 'yad yad yāpi mamaivājñā nivartayatu rāghavam
na śakṣyāmi vinā rāma muhūrtam api jīvitum', null, 2053019),
('ramayana-2-53-20', 20, 'Ayodhya Kanda, Sarga 53, Verse 20', 'अथ वापि महाबाहुर्गतो दूरं भविष्यति।
मामेव रथमारोप्य शीघ्रं रामाय दर्शय॥', 'atha vāpi mahābāhur gato dūraṃ bhaviṣyati
mām eva ratham āropya śīghraṃ rāmāya darśaya', null, 2053020),
('ramayana-2-53-21', 21, 'Ayodhya Kanda, Sarga 53, Verse 21', 'वृत्तदंष्ट्रो महेष्वासः क्वासौ लक्ष्मणपूर्वजः।
यदि जीवामि साध्वेनं पश्येयं सह सीतया॥', 'vṛttadaṃṣṭro maheṣvāsaḥ kvāsau lakṣmaṇapūrvajaḥ
yadi jīvāmi sādhv enaṃ paśyeyaṃ saha sītayā', null, 2053021),
('ramayana-2-53-22', 22, 'Ayodhya Kanda, Sarga 53, Verse 22', 'लोहिताक्षं महाबाहुमामुक्तमणिकुण्डलम्।
रामं यदि न पश्यामि गमिष्यामि यमक्षयम्॥', 'lohitākṣaṃ mahābāhum āmuktamaṇikuṇḍalam
rāmaṃ yadi na paśyāmi gamiṣyāmi yamakṣayam', null, 2053022),
('ramayana-2-53-23', 23, 'Ayodhya Kanda, Sarga 53, Verse 23', 'अतो नु किं दुःखतरं योऽहमिक्ष्वाकुनन्दनम्।
इमामवस्थामापन्नो नेह पश्यामि राघवम्॥', 'ato nu kiṃ duḥkhataraṃ yo ''ham ikṣvākunandanam
imām avasthām āpanno neha paśyāmi rāghavam', null, 2053023),
('ramayana-2-53-24', 24, 'Ayodhya Kanda, Sarga 53, Verse 24', 'हा राम रामानुज हा हा वैदेहि तपस्विनी।
न मां जानीत दुःखेन म्रियमाणमनाथवत्।
दुस्तरो जीवता देवि मयायं शोकसागरः॥', 'hā rāma rāmānuja hā hā vaidehi tapasvinī
na māṃ jānīta duḥkhena mriyamāṇam anāthavat
dustaro jīvatā devi mayāyaṃ śokasāgaraḥ', null, 2053024),
('ramayana-2-53-25', 25, 'Ayodhya Kanda, Sarga 53, Verse 25', 'अशोभनं योऽहमिहाद्य राघवं दिदृक्षमाणो न लभे सलक्ष्मणम्।
इतीव राजा विलपन्महायशाः पपात तूर्णं शयने स मूर्छितः॥', 'aśobhanaṃ yo ''ham ihādya rāghavaṃ didṛkṣamāṇo na labhe salakṣmaṇam
itīva rājā vilapan mahāyaśāḥ papāta tūrṇaṃ śayane sa mūrchitaḥ', null, 2053025),
('ramayana-2-53-26', 26, 'Ayodhya Kanda, Sarga 53, Verse 26', 'इति विलपति पार्थिवे प्रनष्टे करुणतरं द्विगुणं च रामहेतोः।
वचनमनुनिशम्य तस्य देवी भयमगमत्पुनरेव राममाता॥', 'iti vilapati pārthive pranaṣṭe karuṇataraṃ dviguṇaṃ ca rāmahetoḥ
vacanam anuniśamya tasya devī bhayam agamat punar eva rāmamātā', null, 2053026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 54 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-54-1', 1, 'Ayodhya Kanda, Sarga 54, Verse 1', 'ततो भूतोपसृष्टेव वेपमाना पुनः पुनः।
धरण्यां गतसत्त्वेव कौसल्या सूतमब्रवीत्॥', 'tato bhūtopasṛṣṭeva vepamānā punaḥ punaḥ
dharaṇyāṃ gatasattveva kausalyā sūtam abravīt', null, 2054001),
('ramayana-2-54-2', 2, 'Ayodhya Kanda, Sarga 54, Verse 2', 'नय मां यत्र काकुत्स्थः सीता यत्र च लक्ष्मणः।
तान्विना क्षणमप्यत्र जीवितुं नोत्सहे ह्यहम्॥', 'naya māṃ yatra kākutsthaḥ sītā yatra ca lakṣmaṇaḥ
tān vinā kṣaṇam apy atra jīvituṃ notsahe hy aham', null, 2054002),
('ramayana-2-54-3', 3, 'Ayodhya Kanda, Sarga 54, Verse 3', 'निवर्तय रथं शीघ्रं दण्डकान्नय मामपि।
अथ तान्नानुगच्छामि गमिष्यामि यमक्षयम्॥', 'nivartaya rathaṃ śīghraṃ daṇḍakān naya mām api
atha tān nānugacchāmi gamiṣyāmi yamakṣayam', null, 2054003),
('ramayana-2-54-4', 4, 'Ayodhya Kanda, Sarga 54, Verse 4', 'बाष्पवेगौपहतया स वाचा सज्जमानया।
इदमाश्वासयन्देवीं सूतः प्राञ्जलिरब्रवीत्॥', 'bāṣpavegaupahatayā sa vācā sajjamānayā
idam āśvāsayan devīṃ sūtaḥ prāñjalir abravīt', null, 2054004),
('ramayana-2-54-5', 5, 'Ayodhya Kanda, Sarga 54, Verse 5', 'त्यज शोकं च मोहं च संभ्रमं दुःखजं तथा।
व्यवधूय च संतापं वने वत्स्यति राघवः॥', 'tyaja śokaṃ ca mohaṃ ca saṃbhramaṃ duḥkhajaṃ tathā
vyavadhūya ca saṃtāpaṃ vane vatsyati rāghavaḥ', null, 2054005),
('ramayana-2-54-6', 6, 'Ayodhya Kanda, Sarga 54, Verse 6', 'लक्ष्मणश्चापि रामस्य पादौ परिचरन्वने।
आराधयति धर्मज्ञः परलोकं जितेन्द्रियः॥', 'lakṣmaṇaś cāpi rāmasya pādau paricaran vane
ārādhayati dharmajñaḥ paralokaṃ jitendriyaḥ', null, 2054006),
('ramayana-2-54-7', 7, 'Ayodhya Kanda, Sarga 54, Verse 7', 'विजनेऽपि वने सीता वासं प्राप्य गृहेष्विव।
विस्रम्भं लभतेऽभीता रामे संन्यस्त मानसा॥', 'vijane ''pi vane sītā vāsaṃ prāpya gṛheṣv iva
visrambhaṃ labhate ''bhītā rāme saṃnyasta mānasā', null, 2054007),
('ramayana-2-54-8', 8, 'Ayodhya Kanda, Sarga 54, Verse 8', 'नास्या दैन्यं कृतं किं चित्सुसूक्ष्ममपि लक्षये।
उचितेव प्रवासानां वैदेही प्रतिभाति मा॥', 'nāsyā dainyaṃ kṛtaṃ kiṃ cit susūkṣmam api lakṣaye
uciteva pravāsānāṃ vaidehī pratibhāti mā', null, 2054008),
('ramayana-2-54-9', 9, 'Ayodhya Kanda, Sarga 54, Verse 9', 'नगरोपवनं गत्वा यथा स्म रमते पुरा।
तथैव रमते सीता निर्जनेषु वनेष्वपि॥', 'nagaropavanaṃ gatvā yathā sma ramate purā
tathaiva ramate sītā nirjaneṣu vaneṣv api', null, 2054009),
('ramayana-2-54-10', 10, 'Ayodhya Kanda, Sarga 54, Verse 10', 'बालेव रमते सीता बालचन्द्रनिभानना।
रामा रामे ह्यदीनात्मा विजनेऽपि वने सती॥', 'bāleva ramate sītā bālacandranibhānanā
rāmā rāme hy adīnātmā vijane ''pi vane satī', null, 2054010),
('ramayana-2-54-11', 11, 'Ayodhya Kanda, Sarga 54, Verse 11', 'तद्गतं हृदयं ह्यस्यास्तदधीनं च जीवितम्।
अयोध्यापि भवेत्तस्या राम हीना तथा वनम्॥', 'tadgataṃ hṛdayaṃ hy asyās tad adhīnaṃ ca jīvitam
ayodhyāpi bhavet tasyā rāma hīnā tathā vanam', null, 2054011),
('ramayana-2-54-12', 12, 'Ayodhya Kanda, Sarga 54, Verse 12', 'पथि पृच्छति वैदेही ग्रामांश्च नगराणि च।
गतिं दृष्ट्वा नदीनां च पादपान्विविधानपि॥', 'pathi pṛcchati vaidehī grāmāṃś ca nagarāṇi ca
gatiṃ dṛṣṭvā nadīnāṃ ca pādapān vividhān api', null, 2054012),
('ramayana-2-54-13', 13, 'Ayodhya Kanda, Sarga 54, Verse 13', 'अध्वना वात वेगेन संभ्रमेणातपेन च।
न हि गच्छति वैदेह्याश्चन्द्रांशुसदृशी प्रभा॥', 'adhvanā vāta vegena saṃbhrameṇātapena ca
na hi gacchati vaidehyāś candrāṃśusadṛśī prabhā', null, 2054013),
('ramayana-2-54-14', 14, 'Ayodhya Kanda, Sarga 54, Verse 14', 'सदृशं शतपत्रस्य पूर्णचन्द्रोपमप्रभम्।
वदनं तद्वदान्याया वैदेह्या न विकम्पते॥', 'sadṛśaṃ śatapatrasya pūrṇacandropamaprabham
vadanaṃ tadvadānyāyā vaidehyā na vikampate', null, 2054014),
('ramayana-2-54-15', 15, 'Ayodhya Kanda, Sarga 54, Verse 15', 'अलक्तरसरक्ताभावलक्तरसवर्जितौ।
अद्यापि चरणौ तस्याः पद्मकोशसमप्रभौ॥', 'alaktarasaraktābhāv alaktarasavarjitau
adyāpi caraṇau tasyāḥ padmakośasamaprabhau', null, 2054015),
('ramayana-2-54-16', 16, 'Ayodhya Kanda, Sarga 54, Verse 16', 'नूपुरोद्घुष्टहेलेव खेलं गच्छति भामिनी।
इदानीमपि वैदेही तद्रागा न्यस्तभूषणा॥', 'nūpurodghuṣṭaheleva khelaṃ gacchati bhāminī
idānīm api vaidehī tadrāgā nyastabhūṣaṇā', null, 2054016),
('ramayana-2-54-17', 17, 'Ayodhya Kanda, Sarga 54, Verse 17', 'गजं वा वीक्ष्य सिंहं वा व्याघ्रं वा वनमाश्रिता।
नाहारयति संत्रासं बाहू रामस्य संश्रिता॥', 'gajaṃ vā vīkṣya siṃhaṃ vā vyāghraṃ vā vanam āśritā
nāhārayati saṃtrāsaṃ bāhū rāmasya saṃśritā', null, 2054017),
('ramayana-2-54-18', 18, 'Ayodhya Kanda, Sarga 54, Verse 18', 'न शोच्यास्ते न चात्मा ते शोच्यो नापि जनाधिपः।
इदं हि चरितं लोके प्रतिष्ठास्यति शाश्वतम्॥', 'na śocyās te na cātmā te śocyo nāpi janādhipaḥ
idaṃ hi caritaṃ loke pratiṣṭhāsyati śāśvatam', null, 2054018),
('ramayana-2-54-19', 19, 'Ayodhya Kanda, Sarga 54, Verse 19', 'विधूय शोकं परिहृष्टमानसा महर्षियाते पथि सुव्यवस्थिताः।
वने रता वन्यफलाशनाः पितुः शुभां प्रतिज्ञां परिपालयन्ति ते॥', 'vidhūya śokaṃ parihṛṣṭamānasā maharṣiyāte pathi suvyavasthitāḥ
vane ratā vanyaphalāśanāḥ pituḥ śubhāṃ pratijñāṃ paripālayanti te', null, 2054019),
('ramayana-2-54-20', 20, 'Ayodhya Kanda, Sarga 54, Verse 20', 'तथापि सूतेन सुयुक्तवादिना निवार्यमाणा सुतशोककर्शिता।
न चैव देवी विरराम कूजितात्प्रियेति पुत्रेति च राघवेति च॥', 'tathāpi sūtena suyuktavādinā nivāryamāṇā sutaśokakarśitā
na caiva devī virarāma kūjitāt priyeti putreti ca rāghaveti ca', null, 2054020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 55 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-55-1', 1, 'Ayodhya Kanda, Sarga 55, Verse 1', 'वनं गते धर्मपरे रामे रमयतां वरे।
कौसल्या रुदती स्वार्ता भर्तारमिदमब्रवीत्॥', 'vanaṃ gate dharmapare rāme ramayatāṃ vare
kausalyā rudatī svārtā bhartāram idam abravīt', null, 2055001),
('ramayana-2-55-2', 2, 'Ayodhya Kanda, Sarga 55, Verse 2', 'यद्यपित्रिषु लोकेषु प्रथितं ते मयद्यशः।
सानुक्रोशो वदान्यश्च प्रियवादी च राघवः॥', 'yady apitriṣu lokeṣu prathitaṃ te mayad yaśaḥ
sānukrośo vadānyaś ca priyavādī ca rāghavaḥ', null, 2055002),
('ramayana-2-55-3', 3, 'Ayodhya Kanda, Sarga 55, Verse 3', 'कथं नरवरश्रेष्ठ पुत्रौ तौ सह सीतया।
दुःखितौ सुखसंवृद्धौ वने दुःखं सहिष्यतः॥', 'kathaṃ naravaraśreṣṭha putrau tau saha sītayā
duḥkhitau sukhasaṃvṛddhau vane duḥkhaṃ sahiṣyataḥ', null, 2055003),
('ramayana-2-55-4', 4, 'Ayodhya Kanda, Sarga 55, Verse 4', 'सा नूनं तरुणी श्यामा सुकुमारी सुखोचिता।
कथमुष्णं च शीतं च मैथिली प्रसहिष्यते॥', 'sā nūnaṃ taruṇī śyāmā sukumārī sukhocitā
katham uṣṇaṃ ca śītaṃ ca maithilī prasahiṣyate', null, 2055004),
('ramayana-2-55-5', 5, 'Ayodhya Kanda, Sarga 55, Verse 5', 'भुक्त्वाशनं विशालाक्षी सूपदंशान्वितं शुभम्।
वन्यं नैवारमाहारं कथं सीतोपभोक्ष्यते॥', 'bhuktvāśanaṃ viśālākṣī sūpadaṃśānvitaṃ śubham
vanyaṃ naivāram āhāraṃ kathaṃ sītopabhokṣyate', null, 2055005),
('ramayana-2-55-6', 6, 'Ayodhya Kanda, Sarga 55, Verse 6', 'गीतवादित्रनिर्घोषं श्रुत्वा शुभमनिन्दिता।
कथं क्रव्यादसिंहानां शब्दं श्रोष्यत्यशोभनम्॥', 'gītavāditranirghoṣaṃ śrutvā śubham aninditā
kathaṃ kravyādasiṃhānāṃ śabdaṃ śroṣyaty aśobhanam', null, 2055006),
('ramayana-2-55-7', 7, 'Ayodhya Kanda, Sarga 55, Verse 7', 'महेन्द्रध्वजसंकाशः क्व नु शेते महाभुजः।
भुजं परिघसंकाशमुपधाय महाबलः॥', 'mahendradhvajasaṃkāśaḥ kva nu śete mahābhujaḥ
bhujaṃ parighasaṃkāśam upadhāya mahābalaḥ', null, 2055007),
('ramayana-2-55-8', 8, 'Ayodhya Kanda, Sarga 55, Verse 8', 'पद्मवर्णं सुकेशान्तं पद्मनिःश्वासमुत्तमम्।
कदा द्रक्ष्यामि रामस्य वदनं पुष्करेक्षणम्॥', 'padmavarṇaṃ sukeśāntaṃ padmaniḥśvāsam uttamam
kadā drakṣyāmi rāmasya vadanaṃ puṣkarekṣaṇam', null, 2055008),
('ramayana-2-55-9', 9, 'Ayodhya Kanda, Sarga 55, Verse 9', 'वज्रसारमयं नूनं हृदयं मे न संशयः।
अपश्यन्त्या न तं यद्वै फलतीदं सहस्रधा॥', 'vajrasāramayaṃ nūnaṃ hṛdayaṃ me na saṃśayaḥ
apaśyantyā na taṃ yad vai phalatīdaṃ sahasradhā', null, 2055009),
('ramayana-2-55-10', 10, 'Ayodhya Kanda, Sarga 55, Verse 10', 'यदि पञ्चदशे वर्षे राघवः पुनरेष्यति।
जह्याद्राज्यं च कोशं च भरतेनोपभोक्ष्यते॥', 'yadi pañcadaśe varṣe rāghavaḥ punar eṣyati
jahyād rājyaṃ ca kośaṃ ca bharatenopabhokṣyate', null, 2055010),
('ramayana-2-55-11', 11, 'Ayodhya Kanda, Sarga 55, Verse 11', 'एवं कनीयसा भ्रात्रा भुक्तं राज्यं विशां पते।
भ्राता ज्येष्ठा वरिष्ठाश्च किमर्थं नावमंस्यते॥', 'evaṃ kanīyasā bhrātrā bhuktaṃ rājyaṃ viśāṃ pate
bhrātā jyeṣṭhā variṣṭhāś ca kimarthaṃ nāvamaṃsyate', null, 2055011),
('ramayana-2-55-12', 12, 'Ayodhya Kanda, Sarga 55, Verse 12', 'न परेणाहृतं भक्ष्यं व्याघ्रः खादितुमिच्छति।
एवमेव नरव्याघ्रः परलीढं न मंस्यते॥', 'na pareṇāhṛtaṃ bhakṣyaṃ vyāghraḥ khāditum icchati
evam eva naravyāghraḥ paralīḍhaṃ na maṃsyate', null, 2055012),
('ramayana-2-55-13', 13, 'Ayodhya Kanda, Sarga 55, Verse 13', 'हविराज्यं पुरोडाशाः कुशा यूपाश्च खादिराः।
नैतानि यातयामानि कुर्वन्ति पुनरध्वरे॥', 'havir ājyaṃ puroḍāśāḥ kuśā yūpāś ca khādirāḥ
naitāni yātayāmāni kurvanti punar adhvare', null, 2055013),
('ramayana-2-55-14', 14, 'Ayodhya Kanda, Sarga 55, Verse 14', 'तथा ह्यात्तमिदं राज्यं हृतसारां सुरामिव।
नाभिमन्तुमलं रामो नष्टसोममिवाध्वरम्॥', 'tathā hy āttam idaṃ rājyaṃ hṛtasārāṃ surām iva
nābhimantum alaṃ rāmo naṣṭasomam ivādhvaram', null, 2055014),
('ramayana-2-55-15', 15, 'Ayodhya Kanda, Sarga 55, Verse 15', 'नैवंविधमसत्कारं राघवो मर्षयिष्यति।
बलवानिव शार्दूलो बालधेरभिमर्शनम्॥', 'naivaṃvidham asatkāraṃ rāghavo marṣayiṣyati
balavān iva śārdūlo bāladher abhimarśanam', null, 2055015),
('ramayana-2-55-16', 16, 'Ayodhya Kanda, Sarga 55, Verse 16', 'स तादृशः सिंहबलो वृषभाक्षो नरर्षभः।
स्वयमेव हतः पित्रा जलजेनात्मजो यथा॥', 'sa tādṛśaḥ siṃhabalo vṛṣabhākṣo nararṣabhaḥ
svayam eva hataḥ pitrā jalajenātmajo yathā', null, 2055016),
('ramayana-2-55-17', 17, 'Ayodhya Kanda, Sarga 55, Verse 17', 'द्विजाति चरितो धर्मः शास्त्रदृष्टः सनातनः।
यदि ते धर्मनिरते त्वया पुत्रे विवासिते॥', 'dvijāti carito dharmaḥ śāstradṛṣṭaḥ sanātanaḥ
yadi te dharmanirate tvayā putre vivāsite', null, 2055017),
('ramayana-2-55-18', 18, 'Ayodhya Kanda, Sarga 55, Verse 18', 'गतिरेवाक्पतिर्नार्या द्वितीया गतिरात्मजः।
तृतीया ज्ञातयो राजंश्चतुर्थी नेह विद्यते॥', 'gatir evāk patir nāryā dvitīyā gatir ātmajaḥ
tṛtīyā jñātayo rājaṃś caturthī neha vidyate', null, 2055018),
('ramayana-2-55-19', 19, 'Ayodhya Kanda, Sarga 55, Verse 19', 'तत्र त्वं चैव मे नास्ति रामश्च वनमाश्रितः।
न वनं गन्तुमिच्छामि सर्वथा हि हता त्वया॥', 'tatra tvaṃ caiva me nāsti rāmaś ca vanam āśritaḥ
na vanaṃ gantum icchāmi sarvathā hi hatā tvayā', null, 2055019),
('ramayana-2-55-20', 20, 'Ayodhya Kanda, Sarga 55, Verse 20', 'हतं त्वया राज्यमिदं सराष्ट्रं हतस्तथात्मा सह मन्त्रिभिश्च।
हता सपुत्रास्मि हताश्च पौराः सुतश्च भार्या च तव प्रहृष्टौ॥', 'hataṃ tvayā rājyam idaṃ sarāṣṭraṃ hatas tathātmā saha mantribhiś ca
hatā saputrāsmi hatāś ca paurāḥ sutaś ca bhāryā ca tava prahṛṣṭau', null, 2055020),
('ramayana-2-55-21', 21, 'Ayodhya Kanda, Sarga 55, Verse 21', 'इमां गिरं दारुणशब्दसंश्रितां निशम्य राजापि मुमोह दुःखितः।
ततः स शोकं प्रविवेश पार्थिवः स्वदुष्कृतं चापि पुनस्तदास्मरत्॥', 'imāṃ giraṃ dāruṇaśabdasaṃśritāṃ niśamya rājāpi mumoha duḥkhitaḥ
tataḥ sa śokaṃ praviveśa pārthivaḥ svaduṣkṛtaṃ cāpi punas tadāsmarat', null, 2055021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 56 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-56-1', 1, 'Ayodhya Kanda, Sarga 56, Verse 1', 'एवं तु क्रुद्धया राजा राममात्रा सशोकया।
श्रावितः परुषं वाक्यं चिन्तयामास दुःखितः॥', 'evaṃ tu kruddhayā rājā rāmamātrā saśokayā
śrāvitaḥ paruṣaṃ vākyaṃ cintayām āsa duḥkhitaḥ', null, 2056001),
('ramayana-2-56-2', 2, 'Ayodhya Kanda, Sarga 56, Verse 2', 'तस्य चिन्तयमानस्य प्रत्यभात्कर्म दुष्कृतम्।
यदनेन कृतं पूर्वमज्ञानाच्छब्दवेधिना॥', 'tasya cintayamānasya pratyabhāt karma duṣkṛtam
yad anena kṛtaṃ pūrvam ajñānāc chabdavedhinā', null, 2056002),
('ramayana-2-56-3', 3, 'Ayodhya Kanda, Sarga 56, Verse 3', 'अमनास्तेन शोकेन रामशोकेन च प्रभुः।
दह्यमानस्तु शोकाभ्यां कौसल्यामाह भूपतिः॥', 'amanās tena śokena rāmaśokena ca prabhuḥ
dahyamānas tu śokābhyāṃ kausalyām āha bhūpatiḥ', null, 2056003),
('ramayana-2-56-4', 4, 'Ayodhya Kanda, Sarga 56, Verse 4', 'प्रसादये त्वां कौसल्ये रचितोऽयं मयाञ्जलिः।
वत्सला चानृशंसा च त्वं हि नित्यं परेष्वपि॥', 'prasādaye tvāṃ kausalye racito ''yaṃ mayāñjaliḥ
vatsalā cānṛśaṃsā ca tvaṃ hi nityaṃ pareṣv api', null, 2056004),
('ramayana-2-56-5', 5, 'Ayodhya Kanda, Sarga 56, Verse 5', 'भर्ता तु खलु नारीणां गुणवान्निर्गुणोऽपि वा।
धर्मं विमृशमानानां प्रत्यक्षं देवि दैवतम्॥', 'bhartā tu khalu nārīṇāṃ guṇavān nirguṇo ''pi vā
dharmaṃ vimṛśamānānāṃ pratyakṣaṃ devi daivatam', null, 2056005),
('ramayana-2-56-6', 6, 'Ayodhya Kanda, Sarga 56, Verse 6', 'सा त्वं धर्मपरा नित्यं दृष्टलोकपरावर।
नार्हसे विप्रियं वक्तुं दुःखितापि सुदुःखितम्॥', 'sā tvaṃ dharmaparā nityaṃ dṛṣṭalokaparāvara
nārhase vipriyaṃ vaktuṃ duḥkhitāpi suduḥkhitam', null, 2056006),
('ramayana-2-56-7', 7, 'Ayodhya Kanda, Sarga 56, Verse 7', 'तद्वाक्यं करुणं राज्ञः श्रुत्वा दीनस्य भाषितम्।
कौसल्या व्यसृजद्बाष्पं प्रणालीव नवोदकम्॥', 'tad vākyaṃ karuṇaṃ rājñaḥ śrutvā dīnasya bhāṣitam
kausalyā vyasṛjad bāṣpaṃ praṇālīva navodakam', null, 2056007),
('ramayana-2-56-8', 8, 'Ayodhya Kanda, Sarga 56, Verse 8', 'स मूद्र्ह्णि बद्ध्वा रुदती राज्ञः पद्ममिवाञ्जलिम्।
संभ्रमादब्रवीत्त्रस्ता त्वरमाणाक्षरं वचः॥', 'sa mūdrhṇi baddhvā rudatī rājñaḥ padmam ivāñjalim
saṃbhramād abravīt trastā tvaramāṇākṣaraṃ vacaḥ', null, 2056008),
('ramayana-2-56-9', 9, 'Ayodhya Kanda, Sarga 56, Verse 9', 'प्रसीद शिरसा याचे भूमौ निततितास्मि ते।
याचितास्मि हता देव हन्तव्याहं न हि त्वया॥', 'prasīda śirasā yāce bhūmau nitatitāsmi te
yācitāsmi hatā deva hantavyāhaṃ na hi tvayā', null, 2056009),
('ramayana-2-56-10', 10, 'Ayodhya Kanda, Sarga 56, Verse 10', 'नैषा हि सा स्त्री भवति श्लाघनीयेन धीमता।
उभयोर्लोकयोर्वीर पत्या या संप्रसाद्यते॥', 'naiṣā hi sā strī bhavati ślāghanīyena dhīmatā
ubhayor lokayor vīra patyā yā saṃprasādyate', null, 2056010),
('ramayana-2-56-11', 11, 'Ayodhya Kanda, Sarga 56, Verse 11', 'जानामि धर्मं धर्मज्ञ त्वां जाने सत्यवादिनम्।
पुत्रशोकार्तया तत्तु मया किमपि भाषितम्॥', 'jānāmi dharmaṃ dharmajña tvāṃ jāne satyavādinam
putraśokārtayā tat tu mayā kim api bhāṣitam', null, 2056011),
('ramayana-2-56-12', 12, 'Ayodhya Kanda, Sarga 56, Verse 12', 'शोको नाशयते धैर्यं शोको नाशयते श्रुतम्।
शोको नाशयते सर्वं नास्ति शोकसमो रिपुः॥', 'śoko nāśayate dhairyaṃ śoko nāśayate śrutam
śoko nāśayate sarvaṃ nāsti śokasamo ripuḥ', null, 2056012),
('ramayana-2-56-13', 13, 'Ayodhya Kanda, Sarga 56, Verse 13', 'शयमापतितः सोढुं प्रहरो रिपुहस्ततः।
सोढुमापतितः शोकः सुसूक्ष्मोऽपि न शक्यते॥', 'śayam āpatitaḥ soḍhuṃ praharo ripuhastataḥ
soḍhum āpatitaḥ śokaḥ susūkṣmo ''pi na śakyate', null, 2056013),
('ramayana-2-56-14', 14, 'Ayodhya Kanda, Sarga 56, Verse 14', 'वनवासाय रामस्य पञ्चरात्रोऽद्य गण्यते।
यः शोकहतहर्षायाः पञ्चवर्षोपमो मम॥', 'vanavāsāya rāmasya pañcarātro ''dya gaṇyate
yaḥ śokahataharṣāyāḥ pañcavarṣopamo mama', null, 2056014),
('ramayana-2-56-15', 15, 'Ayodhya Kanda, Sarga 56, Verse 15', 'तं हि चिन्तयमानायाः शोकोऽयं हृदि वर्धते।
अदीनामिव वेगेन समुद्रसलिलं महत्॥', 'taṃ hi cintayamānāyāḥ śoko ''yaṃ hṛdi vardhate
adīnām iva vegena samudrasalilaṃ mahat', null, 2056015),
('ramayana-2-56-16', 16, 'Ayodhya Kanda, Sarga 56, Verse 16', 'एवं हि कथयन्त्यास्तु कौसल्यायाः शुभं वचः।
मन्दरश्मिरभूत्सुर्यो रजनी चाभ्यवर्तत॥', 'evaṃ hi kathayantyās tu kausalyāyāḥ śubhaṃ vacaḥ
mandaraśmir abhūt suryo rajanī cābhyavartata', null, 2056016),
('ramayana-2-56-17', 17, 'Ayodhya Kanda, Sarga 56, Verse 17', 'अथ प्रह्लादितो वाक्यैर्देव्या कौसल्यया नृपः।
शोकेन च समाक्रान्तो निद्राया वशमेयिवान्॥', 'atha prahlādito vākyair devyā kausalyayā nṛpaḥ
śokena ca samākrānto nidrāyā vaśam eyivān', null, 2056017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 57 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-57-1', 1, 'Ayodhya Kanda, Sarga 57, Verse 1', 'प्रतिबुद्धो मुहुर्तेन शोकोपहतचेतनः।
अथ राजा दशरथः स चिन्तामभ्यपद्यत॥', 'pratibuddho muhur tena śokopahatacetanaḥ
atha rājā daśarathaḥ sa cintām abhyapadyata', null, 2057001),
('ramayana-2-57-2', 2, 'Ayodhya Kanda, Sarga 57, Verse 2', 'रामलक्ष्मणयोश्चैव विवासाद्वासवोपमम्।
आविवेशोपसर्गस्तं तमः सूर्यमिवासुरम्॥', 'rāmalakṣmaṇayoś caiva vivāsād vāsavopamam
āviveśopasargas taṃ tamaḥ sūryam ivāsuram', null, 2057002),
('ramayana-2-57-3', 3, 'Ayodhya Kanda, Sarga 57, Verse 3', 'स राजा रजनीं षष्ठीं रामे प्रव्रजिते वनम्।
अर्धरात्रे दशरथः संस्मरन्दुष्कृतं कृतम्।
कौसल्यां पुत्रशोकार्तामिदं वचनमब्रवीत्॥', 'sa rājā rajanīṃ ṣaṣṭhīṃ rāme pravrajite vanam
ardharātre daśarathaḥ saṃsmaran duṣkṛtaṃ kṛtam
kausalyāṃ putraśokārtām idaṃ vacanam abravīt', null, 2057003),
('ramayana-2-57-4', 4, 'Ayodhya Kanda, Sarga 57, Verse 4', 'यदाचरति कल्याणि शुभं वा यदि वाशुभम्।
तदेव लभते भद्रे कर्ता कर्मजमात्मनः॥', 'yad ācarati kalyāṇi śubhaṃ vā yadi vāśubham
tad eva labhate bhadre kartā karmajam ātmanaḥ', null, 2057004),
('ramayana-2-57-5', 5, 'Ayodhya Kanda, Sarga 57, Verse 5', 'गुरु लाघवमर्थानामारम्भे कर्मणां फलम्।
दोषं वा यो न जानाति स बाल इति होच्यते॥', 'guru lāghavam arthānām ārambhe karmaṇāṃ phalam
doṣaṃ vā yo na jānāti sa bāla iti hocyate', null, 2057005),
('ramayana-2-57-6', 6, 'Ayodhya Kanda, Sarga 57, Verse 6', 'कश्चिदाम्रवणं छित्त्वा पलाशांश्च निषिञ्चति।
पुष्पं दृष्ट्वा फले गृध्नुः स शोचति फलागमे॥', 'kaś cid āmravaṇaṃ chittvā palāśāṃś ca niṣiñcati
puṣpaṃ dṛṣṭvā phale gṛdhnuḥ sa śocati phalāgame', null, 2057006),
('ramayana-2-57-7', 7, 'Ayodhya Kanda, Sarga 57, Verse 7', 'सोऽहमाम्रवणं छित्त्वा पलाशांश्च न्यषेचयम्।
रामं फलागमे त्यक्त्वा पश्चाच्छोचामि दुर्मतिः॥', 'so ''ham āmravaṇaṃ chittvā palāśāṃś ca nyaṣecayam
rāmaṃ phalāgame tyaktvā paścāc chocāmi durmatiḥ', null, 2057007),
('ramayana-2-57-8', 8, 'Ayodhya Kanda, Sarga 57, Verse 8', 'लब्धशब्देन कौसल्ये कुमारेण धनुष्मता।
कुमारः शब्दवेधीति मया पापमिदं कृतम्।
तदिदं मेऽनुसंप्राप्तं देवि दुःखं स्वयं कृतम्॥', 'labdhaśabdena kausalye kumāreṇa dhanuṣmatā
kumāraḥ śabdavedhīti mayā pāpam idaṃ kṛtam
tad idaṃ me ''nusaṃprāptaṃ devi duḥkhaṃ svayaṃ kṛtam', null, 2057008),
('ramayana-2-57-9', 9, 'Ayodhya Kanda, Sarga 57, Verse 9', 'संमोहादिह बालेन यथा स्याद्भक्षितं विषम्।
एवं ममाप्यविज्ञातं शब्दवेध्यमयं फलम्॥', 'saṃmohād iha bālena yathā syād bhakṣitaṃ viṣam
evaṃ mamāpy avijñātaṃ śabdavedhyamayaṃ phalam', null, 2057009),
('ramayana-2-57-10', 10, 'Ayodhya Kanda, Sarga 57, Verse 10', 'देव्यनूढा त्वमभवो युवराजो भवाम्यहम्।
ततः प्रावृडनुप्राप्ता मदकामविवर्धिनी॥', 'devy anūḍhā tvam abhavo yuvarājo bhavāmy aham
tataḥ prāvṛḍ anuprāptā madakāmavivardhinī', null, 2057010),
('ramayana-2-57-11', 11, 'Ayodhya Kanda, Sarga 57, Verse 11', 'उपास्यहि रसान्भौमांस्तप्त्वा च जगदंशुभिः।
परेताचरितां भीमां रविराविशते दिशम्॥', 'upāsyahi rasān bhaumāṃs taptvā ca jagad aṃśubhiḥ
paretācaritāṃ bhīmāṃ ravir āviśate diśam', null, 2057011),
('ramayana-2-57-12', 12, 'Ayodhya Kanda, Sarga 57, Verse 12', 'उष्णमन्तर्दधे सद्यः स्निग्धा ददृशिरे घनाः।
ततो जहृषिरे सर्वे भेकसारङ्गबर्हिणः॥', 'uṣṇam antardadhe sadyaḥ snigdhā dadṛśire ghanāḥ
tato jahṛṣire sarve bhekasāraṅgabarhiṇaḥ', null, 2057012),
('ramayana-2-57-13', 13, 'Ayodhya Kanda, Sarga 57, Verse 13', 'पतितेनाम्भसा छन्नः पतमानेन चासकृत्।
आबभौ मत्तसारङ्गस्तोयराशिरिवाचलः॥', 'patitenāmbhasā channaḥ patamānena cāsakṛt
ābabhau mattasāraṅgas toyarāśir ivācalaḥ', null, 2057013),
('ramayana-2-57-14', 14, 'Ayodhya Kanda, Sarga 57, Verse 14', 'तस्मिन्नतिसुखे काले धनुष्मानिषुमान्रथी।
व्यायाम कृतसंकल्पः सरयूमन्वगां नदीम्॥', 'tasminn atisukhe kāle dhanuṣmān iṣumān rathī
vyāyāma kṛtasaṃkalpaḥ sarayūm anvagāṃ nadīm', null, 2057014),
('ramayana-2-57-15', 15, 'Ayodhya Kanda, Sarga 57, Verse 15', 'निपाने महिषं रात्रौ गजं वाभ्यागतं नदीम्।
अन्यं वा श्वापदं कं चिज्जिघांसुरजितेन्द्रियः॥', 'nipāne mahiṣaṃ rātrau gajaṃ vābhyāgataṃ nadīm
anyaṃ vā śvāpadaṃ kaṃ cij jighāṃsur ajitendriyaḥ', null, 2057015),
('ramayana-2-57-16', 16, 'Ayodhya Kanda, Sarga 57, Verse 16', 'अथान्धकारे त्वश्रौषं जले कुम्भस्य पर्यतः।
अचक्षुर्विषये घोषं वारणस्येव नर्दतः॥', 'athāndhakāre tv aśrauṣaṃ jale kumbhasya paryataḥ
acakṣur viṣaye ghoṣaṃ vāraṇasyeva nardataḥ', null, 2057016),
('ramayana-2-57-17', 17, 'Ayodhya Kanda, Sarga 57, Verse 17', 'ततोऽहं शरमुद्धृत्य दीप्तमाशीविषोपमम्।
अमुञ्चं निशितं बाणमहमाशीविषोपमम्॥', 'tato ''haṃ śaram uddhṛtya dīptam āśīviṣopamam
amuñcaṃ niśitaṃ bāṇam aham āśīviṣopamam', null, 2057017),
('ramayana-2-57-18', 18, 'Ayodhya Kanda, Sarga 57, Verse 18', 'तत्र वागुषसि व्यक्ता प्रादुरासीद्वनौकसः।
हा हेति पततस्तोये वागभूत्तत्र मानुषी।
कथमस्मद्विधे शस्त्रं निपतेत्तु तपस्विनि॥', 'tatra vāg uṣasi vyaktā prādurāsīd vanaukasaḥ
hā heti patatas toye vāg abhūt tatra mānuṣī
katham asmadvidhe śastraṃ nipatet tu tapasvini', null, 2057018),
('ramayana-2-57-19', 19, 'Ayodhya Kanda, Sarga 57, Verse 19', 'प्रविविक्तां नदीं रात्रावुदाहारोऽहमागतः।
इषुणाभिहतः केन कस्य वा किं कृतं मया॥', 'praviviktāṃ nadīṃ rātrāv udāhāro ''ham āgataḥ
iṣuṇābhihataḥ kena kasya vā kiṃ kṛtaṃ mayā', null, 2057019),
('ramayana-2-57-20', 20, 'Ayodhya Kanda, Sarga 57, Verse 20', 'ऋषेर्हि न्यस्त दण्डस्य वने वन्येन जीवतः।
कथं नु शस्त्रेण वधो मद्विधस्य विधीयते॥', 'ṛṣer hi nyasta daṇḍasya vane vanyena jīvataḥ
kathaṃ nu śastreṇa vadho madvidhasya vidhīyate', null, 2057020),
('ramayana-2-57-21', 21, 'Ayodhya Kanda, Sarga 57, Verse 21', 'जटाभारधरस्यैव वल्कलाजिनवाससः।
को वधेन ममार्थी स्यात्किं वास्यापकृतं मया॥', 'jaṭābhāradharasyaiva valkalājinavāsasaḥ
ko vadhena mamārthī syāt kiṃ vāsyāpakṛtaṃ mayā', null, 2057021),
('ramayana-2-57-22', 22, 'Ayodhya Kanda, Sarga 57, Verse 22', 'एवं निष्फलमारब्धं केवलानर्थसंहितम्।
न कश्चित्साधु मन्येत यथैव गुरुतल्पगम्॥', 'evaṃ niṣphalam ārabdhaṃ kevalānarthasaṃhitam
na kaś cit sādhu manyeta yathaiva gurutalpagam', null, 2057022),
('ramayana-2-57-23', 23, 'Ayodhya Kanda, Sarga 57, Verse 23', 'नेमं तथानुशोचामि जीवितक्षयमात्मनः।
मातरं पितरं चोभावनुशोचामि मद्विधे॥', 'nemaṃ tathānuśocāmi jīvitakṣayam ātmanaḥ
mātaraṃ pitaraṃ cobhāv anuśocāmi madvidhe', null, 2057023),
('ramayana-2-57-24', 24, 'Ayodhya Kanda, Sarga 57, Verse 24', 'तदेतान्मिथुनं वृद्धं चिरकालभृतं मया।
मयि पञ्चत्वमापन्ने कां वृत्तिं वर्तयिष्यति॥', 'tad etān mithunaṃ vṛddhaṃ cirakālabhṛtaṃ mayā
mayi pañcatvam āpanne kāṃ vṛttiṃ vartayiṣyati', null, 2057024),
('ramayana-2-57-25', 25, 'Ayodhya Kanda, Sarga 57, Verse 25', 'वृद्धौ च मातापितरावहं चैकेषुणा हतः।
केन स्म निहताः सर्वे सुबालेनाकृतात्मना॥', 'vṛddhau ca mātāpitarāv ahaṃ caikeṣuṇā hataḥ
kena sma nihatāḥ sarve subālenākṛtātmanā', null, 2057025),
('ramayana-2-57-26', 26, 'Ayodhya Kanda, Sarga 57, Verse 26', 'तं गिरं करुणां श्रुत्वा मम धर्मानुकाङ्क्षिणः।
कराभ्यां सशरं चापं व्यथितस्यापतद्भुवि॥', 'taṃ giraṃ karuṇāṃ śrutvā mama dharmānukāṅkṣiṇaḥ
karābhyāṃ saśaraṃ cāpaṃ vyathitasyāpatad bhuvi', null, 2057026),
('ramayana-2-57-27', 27, 'Ayodhya Kanda, Sarga 57, Verse 27', 'तं देशमहमागम्य दीनसत्त्वः सुदुर्मनाः।
अपश्यमिषुणा तीरे सरय्वास्तापसं हतम्॥', 'taṃ deśam aham āgamya dīnasattvaḥ sudurmanāḥ
apaśyam iṣuṇā tīre sarayvās tāpasaṃ hatam', null, 2057027),
('ramayana-2-57-28', 28, 'Ayodhya Kanda, Sarga 57, Verse 28', 'स मामुद्वीक्ष्य नेत्राभ्यां त्रस्तमस्वस्थचेतसं।
इत्युवाच वचः क्रूरं दिधक्षन्निव तेजसा॥', 'sa mām udvīkṣya netrābhyāṃ trastam asvasthacetasaṃ
ity uvāca vacaḥ krūraṃ didhakṣann iva tejasā', null, 2057028),
('ramayana-2-57-29', 29, 'Ayodhya Kanda, Sarga 57, Verse 29', 'किं तवापकृतं राजन्वने निवसता मया।
जिहीर्षुरम्भो गुर्वर्थं यदहं ताडितस्त्वया॥', 'kiṃ tavāpakṛtaṃ rājan vane nivasatā mayā
jihīrṣur ambho gurvarthaṃ yad ahaṃ tāḍitas tvayā', null, 2057029),
('ramayana-2-57-30', 30, 'Ayodhya Kanda, Sarga 57, Verse 30', 'एकेन खलु बाणेन मर्मण्यभिहते मयि।
द्वावन्धौ निहतौ वृद्धौ माता जनयिता च मे॥', 'ekena khalu bāṇena marmaṇy abhihate mayi
dvāv andhau nihatau vṛddhau mātā janayitā ca me', null, 2057030),
('ramayana-2-57-31', 31, 'Ayodhya Kanda, Sarga 57, Verse 31', 'तौ नूनं दुर्बलावन्धौ मत्प्रतीक्षौ पिपासितौ।
चिरमाशाकृतां तृष्णां कष्टां संधारयिष्यतः॥', 'tau nūnaṃ durbalāv andhau matpratīkṣau pipāsitau
ciram āśākṛtāṃ tṛṣṇāṃ kaṣṭāṃ saṃdhārayiṣyataḥ', null, 2057031),
('ramayana-2-57-32', 32, 'Ayodhya Kanda, Sarga 57, Verse 32', 'न नूनं तपसो वास्ति फलयोगः श्रुतस्य वा।
पिता यन्मां न जानाति शयानं पतितं भुवि॥', 'na nūnaṃ tapaso vāsti phalayogaḥ śrutasya vā
pitā yan māṃ na jānāti śayānaṃ patitaṃ bhuvi', null, 2057032),
('ramayana-2-57-33', 33, 'Ayodhya Kanda, Sarga 57, Verse 33', 'जानन्नपि च किं कुर्यादशक्तिरपरिक्रमः।
भिद्यमानमिवाशक्तस्त्रातुमन्यो नगो नगम्॥', 'jānann api ca kiṃ kuryād aśaktir aparikramaḥ
bhidyamānam ivāśaktas trātum anyo nago nagam', null, 2057033),
('ramayana-2-57-34', 34, 'Ayodhya Kanda, Sarga 57, Verse 34', 'पितुस्त्वमेव मे गत्वा शीघ्रमाचक्ष्व राघव।
न त्वामनुदहेत्क्रुद्धो वनं वह्निरिवैधितः॥', 'pitus tvam eva me gatvā śīghram ācakṣva rāghava
na tvām anudahet kruddho vanaṃ vahnir ivaidhitaḥ', null, 2057034),
('ramayana-2-57-35', 35, 'Ayodhya Kanda, Sarga 57, Verse 35', 'इयमेकपदी राजन्यतो मे पितुराश्रमः।
तं प्रसादय गत्वा त्वं न त्वां स कुपितः शपेत्॥', 'iyam ekapadī rājan yato me pitur āśramaḥ
taṃ prasādaya gatvā tvaṃ na tvāṃ sa kupitaḥ śapet', null, 2057035),
('ramayana-2-57-36', 36, 'Ayodhya Kanda, Sarga 57, Verse 36', 'विशल्यं कुरु मां राजन्मर्म मे निशितः शरः।
रुणद्धि मृदु सोत्सेधं तीरमम्बुरयो यथा॥', 'viśalyaṃ kuru māṃ rājan marma me niśitaḥ śaraḥ
ruṇaddhi mṛdu sotsedhaṃ tīram amburayo yathā', null, 2057036),
('ramayana-2-57-37', 37, 'Ayodhya Kanda, Sarga 57, Verse 37', 'न द्विजातिरहं राजन्मा भूत्ते मनसो व्यथा।
शूद्रायामस्मि वैश्येन जातो जनपदाधिप॥', 'na dvijātir ahaṃ rājan mā bhūt te manaso vyathā
śūdrāyām asmi vaiśyena jāto janapadādhipa', null, 2057037),
('ramayana-2-57-38', 38, 'Ayodhya Kanda, Sarga 57, Verse 38', 'इतीव वदतः कृच्छ्राद्बाणाभिहतमर्मणः।
तस्य त्वानम्यमानस्य तं बाणमहमुद्धरम्॥', 'itīva vadataḥ kṛcchrād bāṇābhihatamarmaṇaḥ
tasya tv ānamyamānasya taṃ bāṇam aham uddharam', null, 2057038),
('ramayana-2-57-39', 39, 'Ayodhya Kanda, Sarga 57, Verse 39', 'जलार्द्रगात्रं तु विलप्य कृच्छान्मर्मव्रणं संततमुच्छसन्तम्।
ततः सरय्वां तमहं शयानं समीक्ष्य भद्रे सुभृशं विषण्णः॥', 'jalārdragātraṃ tu vilapya kṛcchān marmavraṇaṃ saṃtatam ucchasantam
tataḥ sarayvāṃ tam ahaṃ śayānaṃ samīkṣya bhadre subhṛśaṃ viṣaṇṇaḥ', null, 2057039)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 58 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-58-1', 1, 'Ayodhya Kanda, Sarga 58, Verse 1', 'तदज्ञानान्महत्पापं कृत्वा संकुलितेन्द्रियः।
एकस्त्वचिन्तयं बुद्ध्या कथं नु सुकृतं भवेत्॥', 'tad ajñānān mahat pāpaṃ kṛtvā saṃkulitendriyaḥ
ekas tv acintayaṃ buddhyā kathaṃ nu sukṛtaṃ bhavet', null, 2058001),
('ramayana-2-58-2', 2, 'Ayodhya Kanda, Sarga 58, Verse 2', 'ततस्तं घटमादय पूर्णं परमवारिणा।
आश्रमं तमहं प्राप्य यथाख्यातपथं गतः॥', 'tatas taṃ ghaṭam ādaya pūrṇaṃ paramavāriṇā
āśramaṃ tam ahaṃ prāpya yathākhyātapathaṃ gataḥ', null, 2058002),
('ramayana-2-58-3', 3, 'Ayodhya Kanda, Sarga 58, Verse 3', 'तत्राहं दुर्बलावन्धौ वृद्धावपरिणायकौ।
अपश्यं तस्य पितरौ लूनपक्षाविव द्विजौ॥', 'tatrāhaṃ durbalāv andhau vṛddhāv apariṇāyakau
apaśyaṃ tasya pitarau lūnapakṣāv iva dvijau', null, 2058003),
('ramayana-2-58-4', 4, 'Ayodhya Kanda, Sarga 58, Verse 4', 'तन्निमित्ताभिरासीनौ कथाभिरपरिक्रमौ।
तामाशां मत्कृते हीनावुदासीनावनाथवत्॥', 'tannimittābhir āsīnau kathābhir aparikramau
tām āśāṃ matkṛte hīnāv udāsīnāv anāthavat', null, 2058004),
('ramayana-2-58-5', 5, 'Ayodhya Kanda, Sarga 58, Verse 5', 'पदशब्दं तु मे श्रुत्वा मुनिर्वाक्यमभाषत।
किं चिरायसि मे पुत्र पानीयं क्षिप्रमानय॥', 'padaśabdaṃ tu me śrutvā munir vākyam abhāṣata
kiṃ cirāyasi me putra pānīyaṃ kṣipram ānaya', null, 2058005),
('ramayana-2-58-6', 6, 'Ayodhya Kanda, Sarga 58, Verse 6', 'यन्निमित्तमिदं तात सलिले क्रीडितं त्वया।
उत्कण्ठिता ते मातेयं प्रविश क्षिप्रमाश्रमम्॥', 'yannimittam idaṃ tāta salile krīḍitaṃ tvayā
utkaṇṭhitā te māteyaṃ praviśa kṣipram āśramam', null, 2058006),
('ramayana-2-58-7', 7, 'Ayodhya Kanda, Sarga 58, Verse 7', 'यद्व्यलीकं कृतं पुत्र मात्रा ते यदि वा मया।
न तन्मनसि कर्तव्यं त्वया तात तपस्विना॥', 'yad vyalīkaṃ kṛtaṃ putra mātrā te yadi vā mayā
na tan manasi kartavyaṃ tvayā tāta tapasvinā', null, 2058007),
('ramayana-2-58-8', 8, 'Ayodhya Kanda, Sarga 58, Verse 8', 'त्वं गतिस्त्वगतीनां च चक्षुस्त्वं हीनचक्षुषाम्।
समासक्तास्त्वयि प्राणाः किं चिन्नौ नाभिभाषसे॥', 'tvaṃ gatis tv agatīnāṃ ca cakṣus tvaṃ hīnacakṣuṣām
samāsaktās tvayi prāṇāḥ kiṃ cin nau nābhibhāṣase', null, 2058008),
('ramayana-2-58-9', 9, 'Ayodhya Kanda, Sarga 58, Verse 9', 'मुनिमव्यक्तया वाचा तमहं सज्जमानया।
हीनव्यञ्जनया प्रेक्ष्य भीतो भीत इवाब्रुवम्॥', 'munim avyaktayā vācā tam ahaṃ sajjamānayā
hīnavyañjanayā prekṣya bhīto bhīta ivābruvam', null, 2058009),
('ramayana-2-58-10', 10, 'Ayodhya Kanda, Sarga 58, Verse 10', 'मनसः कर्म चेष्टाभिरभिसंस्तभ्य वाग्बलम्।
आचचक्षे त्वहं तस्मै पुत्रव्यसनजं भयम्॥', 'manasaḥ karma ceṣṭābhir abhisaṃstabhya vāgbalam
ācacakṣe tv ahaṃ tasmai putravyasanajaṃ bhayam', null, 2058010),
('ramayana-2-58-11', 11, 'Ayodhya Kanda, Sarga 58, Verse 11', 'क्षत्रियोऽहं दशरथो नाहं पुत्रो महात्मनः।
सज्जनावमतं दुःखमिदं प्राप्तं स्वकर्मजम्॥', 'kṣatriyo ''haṃ daśaratho nāhaṃ putro mahātmanaḥ
sajjanāvamataṃ duḥkham idaṃ prāptaṃ svakarmajam', null, 2058011),
('ramayana-2-58-12', 12, 'Ayodhya Kanda, Sarga 58, Verse 12', 'भगवंश्चापहस्तोऽहं सरयूतीरमागतः।
जिघांसुः श्वापदं किं चिन्निपाने वागतं गजम्॥', 'bhagavaṃś cāpahasto ''haṃ sarayūtīram āgataḥ
jighāṃsuḥ śvāpadaṃ kiṃ cin nipāne vāgataṃ gajam', null, 2058012),
('ramayana-2-58-13', 13, 'Ayodhya Kanda, Sarga 58, Verse 13', 'तत्र श्रुतो मया शब्दो जले कुम्भस्य पूर्यतः।
द्विपोऽयमिति मत्वा हि बाणेनाभिहतो मया॥', 'tatra śruto mayā śabdo jale kumbhasya pūryataḥ
dvipo ''yam iti matvā hi bāṇenābhihato mayā', null, 2058013),
('ramayana-2-58-14', 14, 'Ayodhya Kanda, Sarga 58, Verse 14', 'गत्वा नद्यास्ततस्तीरमपश्यमिषुणा हृदि।
विनिर्भिन्नं गतप्राणं शयानं भुवि तापसं॥', 'gatvā nadyās tatas tīram apaśyam iṣuṇā hṛdi
vinirbhinnaṃ gataprāṇaṃ śayānaṃ bhuvi tāpasaṃ', null, 2058014),
('ramayana-2-58-15', 15, 'Ayodhya Kanda, Sarga 58, Verse 15', 'भगवञ्शब्दमालक्ष्य मया गजजिघांसुना।
विसृष्टोऽम्भसि नाराचस्तेन ते निहतः सुतः॥', 'bhagavañ śabdam ālakṣya mayā gajajighāṃsunā
visṛṣṭo ''mbhasi nārācas tena te nihataḥ sutaḥ', null, 2058015),
('ramayana-2-58-16', 16, 'Ayodhya Kanda, Sarga 58, Verse 16', 'स चोद्धृतेन बाणेन तत्रैव स्वर्गमास्थितः।
भगवन्तावुभौ शोचन्नन्धाविति विलप्य च॥', 'sa coddhṛtena bāṇena tatraiva svargam āsthitaḥ
bhagavantāv ubhau śocann andhāv iti vilapya ca', null, 2058016),
('ramayana-2-58-17', 17, 'Ayodhya Kanda, Sarga 58, Verse 17', 'अज्ञानाद्भवतः पुत्रः सहसाभिहतो मया।
शेषमेवंगते यत्स्यात्तत्प्रसीदतु मे मुनिः॥', 'ajñānād bhavataḥ putraḥ sahasābhihato mayā
śeṣam evaṃgate yat syāt tat prasīdatu me muniḥ', null, 2058017),
('ramayana-2-58-18', 18, 'Ayodhya Kanda, Sarga 58, Verse 18', 'स तच्छ्रुत्वा वचः क्रूरं निःश्वसञ्शोककर्शितः।
मामुवाच महातेजाः कृताञ्जलिमुपस्थितम्॥', 'sa tac chrutvā vacaḥ krūraṃ niḥśvasañ śokakarśitaḥ
mām uvāca mahātejāḥ kṛtāñjalim upasthitam', null, 2058018),
('ramayana-2-58-19', 19, 'Ayodhya Kanda, Sarga 58, Verse 19', 'यद्येतदशुभं कर्म न स्म मे कथयेः स्वयम्।
फलेन्मूर्धा स्म ते राजन्सद्यः शतसहस्रधा॥', 'yady etad aśubhaṃ karma na sma me kathayeḥ svayam
phalen mūrdhā sma te rājan sadyaḥ śatasahasradhā', null, 2058019),
('ramayana-2-58-20', 20, 'Ayodhya Kanda, Sarga 58, Verse 20', 'क्षत्रियेण वधो राजन्वानप्रस्थे विशेषतः।
ज्ञानपूर्वं कृतः स्थानाच्च्यावयेदपि वज्रिणम्॥', 'kṣatriyeṇa vadho rājan vānaprasthe viśeṣataḥ
jñānapūrvaṃ kṛtaḥ sthānāc cyāvayed api vajriṇam', null, 2058020),
('ramayana-2-58-21', 21, 'Ayodhya Kanda, Sarga 58, Verse 21', 'अज्ञानाद्धि कृतं यस्मादिदं तेनैव जीवसि।
अपि ह्यद्य कुलं नस्याद्राघवाणां कुतो भवान्॥', 'ajñānād dhi kṛtaṃ yasmād idaṃ tenaiva jīvasi
api hy adya kulaṃ nasyād rāghavāṇāṃ kuto bhavān', null, 2058021),
('ramayana-2-58-22', 22, 'Ayodhya Kanda, Sarga 58, Verse 22', 'नय नौ नृप तं देशमिति मां चाभ्यभाषत।
अद्य तं द्रष्टुमिच्छावः पुत्रं पश्चिमदर्शनम्॥', 'naya nau nṛpa taṃ deśam iti māṃ cābhyabhāṣata
adya taṃ draṣṭum icchāvaḥ putraṃ paścimadarśanam', null, 2058022),
('ramayana-2-58-23', 23, 'Ayodhya Kanda, Sarga 58, Verse 23', 'रुधिरेणावसिताङ्गं प्रकीर्णाजिनवाससं।
शयानं भुवि निःसंज्ञं धर्मराजवशं गतम्॥', 'rudhireṇāvasitāṅgaṃ prakīrṇājinavāsasaṃ
śayānaṃ bhuvi niḥsaṃjñaṃ dharmarājavaśaṃ gatam', null, 2058023),
('ramayana-2-58-24', 24, 'Ayodhya Kanda, Sarga 58, Verse 24', 'अथाहमेकस्तं देशं नीत्वा तौ भृशदुःखितौ।
अस्पर्शयमहं पुत्रं तं मुनिं सह भार्यया॥', 'athāham ekas taṃ deśaṃ nītvā tau bhṛśaduḥkhitau
asparśayam ahaṃ putraṃ taṃ muniṃ saha bhāryayā', null, 2058024),
('ramayana-2-58-25', 25, 'Ayodhya Kanda, Sarga 58, Verse 25', 'तौ पुत्रमात्मनः स्पृष्ट्वा तमासाद्य तपस्विनौ।
निपेततुः शरीरेऽस्य पिता चास्येदमब्रवीत्॥', 'tau putram ātmanaḥ spṛṣṭvā tam āsādya tapasvinau
nipetatuḥ śarīre ''sya pitā cāsyedam abravīt', null, 2058025),
('ramayana-2-58-26', 26, 'Ayodhya Kanda, Sarga 58, Verse 26', 'न न्वहं ते प्रियः पुत्र मातरं पश्य धार्मिक।
किं नु नालिङ्गसे पुत्र सुकुमार वचो वद॥', 'na nv ahaṃ te priyaḥ putra mātaraṃ paśya dhārmika
kiṃ nu nāliṅgase putra sukumāra vaco vada', null, 2058026),
('ramayana-2-58-27', 27, 'Ayodhya Kanda, Sarga 58, Verse 27', 'कस्य वापररात्रेऽहं श्रोष्यामि हृदयंगमम्।
अधीयानस्य मधुरं शास्त्रं वान्यद्विशेषतः॥', 'kasya vāpararātre ''haṃ śroṣyāmi hṛdayaṃgamam
adhīyānasya madhuraṃ śāstraṃ vānyad viśeṣataḥ', null, 2058027),
('ramayana-2-58-28', 28, 'Ayodhya Kanda, Sarga 58, Verse 28', 'को मां संध्यामुपास्यैव स्नात्वा हुतहुताशनः।
श्लाघयिष्यत्युपासीनः पुत्रशोकभयार्दितम्॥', 'ko māṃ saṃdhyām upāsyaiva snātvā hutahutāśanaḥ
ślāghayiṣyaty upāsīnaḥ putraśokabhayārditam', null, 2058028),
('ramayana-2-58-29', 29, 'Ayodhya Kanda, Sarga 58, Verse 29', 'कन्दमूलफलं हृत्वा को मां प्रियमिवातिथिम्।
भोजयिष्यत्यकर्मण्यमप्रग्रहमनायकम्॥', 'kandamūlaphalaṃ hṛtvā ko māṃ priyam ivātithim
bhojayiṣyaty akarmaṇyam apragraham anāyakam', null, 2058029),
('ramayana-2-58-30', 30, 'Ayodhya Kanda, Sarga 58, Verse 30', 'इमामन्धां च वृद्धां च मातरं ते तपस्विनीम्।
कथं पुत्र भरिष्यामि कृपणां पुत्रगर्धिनीम्॥', 'imām andhāṃ ca vṛddhāṃ ca mātaraṃ te tapasvinīm
kathaṃ putra bhariṣyāmi kṛpaṇāṃ putragardhinīm', null, 2058030),
('ramayana-2-58-31', 31, 'Ayodhya Kanda, Sarga 58, Verse 31', 'तिष्ठ मा मा गमः पुत्र यमस्य सदनं प्रति।
श्वो मया सह गन्तासि जनन्या च समेधितः॥', 'tiṣṭha mā mā gamaḥ putra yamasya sadanaṃ prati
śvo mayā saha gantāsi jananyā ca samedhitaḥ', null, 2058031),
('ramayana-2-58-32', 32, 'Ayodhya Kanda, Sarga 58, Verse 32', 'उभावपि च शोकार्तावनाथौ कृपणौ वने।
क्षिप्रमेव गमिष्यावस्त्वया हीनौ यमक्षयम्॥', 'ubhāv api ca śokārtāv anāthau kṛpaṇau vane
kṣipram eva gamiṣyāvas tvayā hīnau yamakṣayam', null, 2058032),
('ramayana-2-58-33', 33, 'Ayodhya Kanda, Sarga 58, Verse 33', 'ततो वैवस्वतं दृष्ट्वा तं प्रवक्ष्यामि भारतीम्।
क्षमतां धर्मराजो मे बिभृयात्पितरावयम्॥', 'tato vaivasvataṃ dṛṣṭvā taṃ pravakṣyāmi bhāratīm
kṣamatāṃ dharmarājo me bibhṛyāt pitarāv ayam', null, 2058033),
('ramayana-2-58-34', 34, 'Ayodhya Kanda, Sarga 58, Verse 34', 'अपापोऽसि यथा पुत्र निहतः पापकर्मणा।
तेन सत्येन गच्छाशु ये लोकाः शस्त्रयोधिनाम्॥', 'apāpo ''si yathā putra nihataḥ pāpakarmaṇā
tena satyena gacchāśu ye lokāḥ śastrayodhinām', null, 2058034),
('ramayana-2-58-35', 35, 'Ayodhya Kanda, Sarga 58, Verse 35', 'यान्ति शूरा गतिं यां च संग्रामेष्वनिवर्तिनः।
हतास्त्वभिमुखाः पुत्र गतिं तां परमां व्रज॥', 'yānti śūrā gatiṃ yāṃ ca saṃgrāmeṣv anivartinaḥ
hatās tv abhimukhāḥ putra gatiṃ tāṃ paramāṃ vraja', null, 2058035),
('ramayana-2-58-36', 36, 'Ayodhya Kanda, Sarga 58, Verse 36', 'यां गतिं सगरः शैब्यो दिलीपो जनमेजयः।
नहुषो धुन्धुमारश्च प्राप्तास्तां गच्छ पुत्रक॥', 'yāṃ gatiṃ sagaraḥ śaibyo dilīpo janamejayaḥ
nahuṣo dhundhumāraś ca prāptās tāṃ gaccha putraka', null, 2058036),
('ramayana-2-58-37', 37, 'Ayodhya Kanda, Sarga 58, Verse 37', 'या गतिः सर्वसाधूनां स्वाध्यायात्पतसश्च या।
भूमिदस्याहिताग्नेश्च एकपत्नीव्रतस्य च॥', 'yā gatiḥ sarvasādhūnāṃ svādhyāyāt patasaś ca yā
bhūmidasyāhitāgneś ca ekapatnīvratasya ca', null, 2058037),
('ramayana-2-58-38', 38, 'Ayodhya Kanda, Sarga 58, Verse 38', 'गोसहस्रप्रदातॄणां या या गुरुभृतामपि।
देहन्यासकृतां या च तां गतिं गच्छ पुत्रक।
न हि त्वस्मिन्कुले जातो गच्छत्यकुशलां गतिम्॥', 'gosahasrapradātṝṇāṃ yā yā gurubhṛtām api
dehanyāsakṛtāṃ yā ca tāṃ gatiṃ gaccha putraka
na hi tv asmin kule jāto gacchaty akuśalāṃ gatim', null, 2058038),
('ramayana-2-58-39', 39, 'Ayodhya Kanda, Sarga 58, Verse 39', 'एवं स कृपणं तत्र पर्यदेवयतासकृत्।
ततोऽस्मै कर्तुमुदकं प्रवृत्तः सह भार्यया॥', 'evaṃ sa kṛpaṇaṃ tatra paryadevayatāsakṛt
tato ''smai kartum udakaṃ pravṛttaḥ saha bhāryayā', null, 2058039),
('ramayana-2-58-40', 40, 'Ayodhya Kanda, Sarga 58, Verse 40', 'स तु दिव्येन रूपेण मुनिपुत्रः स्वकर्मभिः।
आश्वास्य च मुहूर्तं तु पितरौ वाक्यमब्रवीत्॥', 'sa tu divyena rūpeṇa muniputraḥ svakarmabhiḥ
āśvāsya ca muhūrtaṃ tu pitarau vākyam abravīt', null, 2058040),
('ramayana-2-58-41', 41, 'Ayodhya Kanda, Sarga 58, Verse 41', 'स्थानमस्मि महत्प्राप्तो भवतोः परिचारणात्।
भवन्तावपि च क्षिप्रं मम मूलमुपैष्यतः॥', 'sthānam asmi mahat prāpto bhavatoḥ paricāraṇāt
bhavantāv api ca kṣipraṃ mama mūlam upaiṣyataḥ', null, 2058041),
('ramayana-2-58-42', 42, 'Ayodhya Kanda, Sarga 58, Verse 42', 'एवमुक्त्वा तु दिव्येन विमानेन वपुष्मता।
आरुरोह दिवं क्षिप्रं मुनिपुत्रो जितेन्द्रियः॥', 'evam uktvā tu divyena vimānena vapuṣmatā
āruroha divaṃ kṣipraṃ muniputro jitendriyaḥ', null, 2058042),
('ramayana-2-58-43', 43, 'Ayodhya Kanda, Sarga 58, Verse 43', 'स कृत्वा तूदकं तूर्णं तापसः सह भार्यया।
मामुवाच महातेजाः कृताञ्जलिमुपस्थितम्॥', 'sa kṛtvā tūdakaṃ tūrṇaṃ tāpasaḥ saha bhāryayā
mām uvāca mahātejāḥ kṛtāñjalim upasthitam', null, 2058043),
('ramayana-2-58-44', 44, 'Ayodhya Kanda, Sarga 58, Verse 44', 'अद्यैव जहि मां राजन्मरणे नास्ति मे व्यथा।
यच्छरेणैकपुत्रं मां त्वमकार्षीरपुत्रकम्॥', 'adyaiva jahi māṃ rājan maraṇe nāsti me vyathā
yac chareṇaikaputraṃ māṃ tvam akārṣīr aputrakam', null, 2058044),
('ramayana-2-58-45', 45, 'Ayodhya Kanda, Sarga 58, Verse 45', 'त्वया तु यदविज्ञानान्निहतो मे सुतः शुचिः।
तेन त्वामभिशप्स्यामि सुदुःखमतिदारुणम्॥', 'tvayā tu yad avijñānān nihato me sutaḥ śuciḥ
tena tvām abhiśapsyāmi suduḥkham atidāruṇam', null, 2058045),
('ramayana-2-58-46', 46, 'Ayodhya Kanda, Sarga 58, Verse 46', 'पुत्रव्यसनजं दुःखं यदेतन्मम साम्प्रतम्।
एवं त्वं पुत्रशोकेन राजन्कालं करिष्यसि॥', 'putravyasanajaṃ duḥkhaṃ yad etan mama sāmpratam
evaṃ tvaṃ putraśokena rājan kālaṃ kariṣyasi', null, 2058046),
('ramayana-2-58-47', 47, 'Ayodhya Kanda, Sarga 58, Verse 47', 'तस्मान्मामागतं भद्रे तस्योदारस्य तद्वचः।
यदहं पुत्रशोकेन संत्यक्ष्याम्यद्य जीवितम्॥', 'tasmān mām āgataṃ bhadre tasyodārasya tad vacaḥ
yad ahaṃ putraśokena saṃtyakṣyāmy adya jīvitam', null, 2058047),
('ramayana-2-58-48', 48, 'Ayodhya Kanda, Sarga 58, Verse 48', 'यदि मां संस्पृशेद्रामः सकृदद्यालभेत वा।
न तन्मे सदृशं देवि यन्मया राघवे कृतम्॥', 'yadi māṃ saṃspṛśed rāmaḥ sakṛd adyālabheta vā
na tan me sadṛśaṃ devi yan mayā rāghave kṛtam', null, 2058048),
('ramayana-2-58-49', 49, 'Ayodhya Kanda, Sarga 58, Verse 49', 'चक्षुषा त्वां न पश्यामि स्मृतिर्मम विलुप्यते।
दूता वैवस्वतस्यैते कौसल्ये त्वरयन्ति माम्॥', 'cakṣuṣā tvāṃ na paśyāmi smṛtir mama vilupyate
dūtā vaivasvatasyaite kausalye tvarayanti mām', null, 2058049),
('ramayana-2-58-50', 50, 'Ayodhya Kanda, Sarga 58, Verse 50', 'अतस्तु किं दुःखतरं यदहं जीवितक्षये।
न हि पश्यामि धर्मज्ञं रामं सत्यपराक्यमम्॥', 'atas tu kiṃ duḥkhataraṃ yad ahaṃ jīvitakṣaye
na hi paśyāmi dharmajñaṃ rāmaṃ satyaparākyamam', null, 2058050),
('ramayana-2-58-51', 51, 'Ayodhya Kanda, Sarga 58, Verse 51', 'न ते मनुष्या देवास्ते ये चारुशुभकुण्डलम्।
मुखं द्रक्ष्यन्ति रामस्य वर्षे पञ्चदशे पुनः॥', 'na te manuṣyā devās te ye cāruśubhakuṇḍalam
mukhaṃ drakṣyanti rāmasya varṣe pañcadaśe punaḥ', null, 2058051),
('ramayana-2-58-52', 52, 'Ayodhya Kanda, Sarga 58, Verse 52', 'पद्मपत्रेक्षणं सुभ्रु सुदंष्ट्रं चारुनासिकम्।
धन्या द्रक्ष्यन्ति रामस्य ताराधिपनिभं मुखम्॥', 'padmapatrekṣaṇaṃ subhru sudaṃṣṭraṃ cārunāsikam
dhanyā drakṣyanti rāmasya tārādhipanibhaṃ mukham', null, 2058052),
('ramayana-2-58-53', 53, 'Ayodhya Kanda, Sarga 58, Verse 53', 'सदृशं शारदस्येन्दोः फुल्लस्य कमलस्य च।
सुगन्धि मम नाथस्य धन्या द्रक्ष्यन्ति तन्मुखम्॥', 'sadṛśaṃ śāradasyendoḥ phullasya kamalasya ca
sugandhi mama nāthasya dhanyā drakṣyanti tanmukham', null, 2058053),
('ramayana-2-58-54', 54, 'Ayodhya Kanda, Sarga 58, Verse 54', 'निवृत्तवनवासं तमयोध्यां पुनरागतम्।
द्रक्ष्यन्ति सुखिनो रामं शुक्रं मार्गगतं यथा॥', 'nivṛttavanavāsaṃ tam ayodhyāṃ punar āgatam
drakṣyanti sukhino rāmaṃ śukraṃ mārgagataṃ yathā', null, 2058054),
('ramayana-2-58-55', 55, 'Ayodhya Kanda, Sarga 58, Verse 55', 'अयमात्मभवः शोको मामनाथमचेतनम्।
संसादयति वेगेन यथा कूलं नदीरयः॥', 'ayam ātmabhavaḥ śoko mām anātham acetanam
saṃsādayati vegena yathā kūlaṃ nadīrayaḥ', null, 2058055),
('ramayana-2-58-56', 56, 'Ayodhya Kanda, Sarga 58, Verse 56', 'हा राघव महाबाहो हा ममायास नाशन।
राजा दशरथः शोचञ्जीवितान्तमुपागमत्॥', 'hā rāghava mahābāho hā mamāyāsa nāśana
rājā daśarathaḥ śocañ jīvitāntam upāgamat', null, 2058056),
('ramayana-2-58-57', 57, 'Ayodhya Kanda, Sarga 58, Verse 57', 'तथा तु दीनं कथयन्नराधिपः प्रियस्य पुत्रस्य विवासनातुरः।
गतेऽर्धरात्रे भृशदुःखपीडितस्तदा जहौ प्राणमुदारदर्शनः॥', 'tathā tu dīnaṃ kathayan narādhipaḥ priyasya putrasya vivāsanāturaḥ
gate ''rdharātre bhṛśaduḥkhapīḍitas tadā jahau prāṇam udāradarśanaḥ', null, 2058057)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 59 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-59-1', 1, 'Ayodhya Kanda, Sarga 59, Verse 1', 'अथ रात्र्यां व्यतीतायां प्रातरेवापरेऽहनि।
बन्दिनः पर्युपातिष्ठंस्तत्पार्थिवनिवेशनम्॥', 'atha rātryāṃ vyatītāyāṃ prātar evāpare ''hani
bandinaḥ paryupātiṣṭhaṃs tat pārthivaniveśanam', null, 2059001),
('ramayana-2-59-2', 2, 'Ayodhya Kanda, Sarga 59, Verse 2', 'ततः शुचिसमाचाराः पर्युपस्थान कोविदः।
स्त्रीवर्षवरभूयिष्ठा उपतस्थुर्यथापुरम्॥', 'tataḥ śucisamācārāḥ paryupasthāna kovidaḥ
strīvarṣavarabhūyiṣṭhā upatasthur yathāpuram', null, 2059002),
('ramayana-2-59-3', 3, 'Ayodhya Kanda, Sarga 59, Verse 3', 'हरिचन्दनसंपृक्तमुदकं काञ्चनैर्घटैः।
आनिन्युः स्नानशिक्षाज्ञा यथाकालं यथाविधि॥', 'haricandanasaṃpṛktam udakaṃ kāñcanair ghaṭaiḥ
āninyuḥ snānaśikṣājñā yathākālaṃ yathāvidhi', null, 2059003),
('ramayana-2-59-4', 4, 'Ayodhya Kanda, Sarga 59, Verse 4', 'मङ्गलालम्भनीयानि प्राशनीयानुपस्करान्।
उपनिन्युस्तथाप्यन्याः कुमारी बहुलाः स्त्रियः॥', 'maṅgalālambhanīyāni prāśanīyān upaskarān
upaninyus tathāpy anyāḥ kumārī bahulāḥ striyaḥ', null, 2059004),
('ramayana-2-59-5', 5, 'Ayodhya Kanda, Sarga 59, Verse 5', 'अथ याः कोसलेन्द्रस्य शयनं प्रत्यनन्तराः।
ताः स्त्रियस्तु समागम्य भर्तारं प्रत्यबोधयन्॥', 'atha yāḥ kosalendrasya śayanaṃ pratyanantarāḥ
tāḥ striyas tu samāgamya bhartāraṃ pratyabodhayan', null, 2059005),
('ramayana-2-59-6', 6, 'Ayodhya Kanda, Sarga 59, Verse 6', 'ता वेपथुपरीताश्च राज्ञः प्राणेषु शङ्किताः।
प्रतिस्रोतस्तृणाग्राणां सदृशं संचकम्पिरे॥', 'tā vepathuparītāś ca rājñaḥ prāṇeṣu śaṅkitāḥ
pratisrotas tṛṇāgrāṇāṃ sadṛśaṃ saṃcakampire', null, 2059006),
('ramayana-2-59-7', 7, 'Ayodhya Kanda, Sarga 59, Verse 7', 'अथ संवेपमनानां स्त्रीणां दृष्ट्वा च पार्थिवम्।
यत्तदाशङ्कितं पापं तस्य जज्ञे विनिश्चयः॥', 'atha saṃvepamanānāṃ strīṇāṃ dṛṣṭvā ca pārthivam
yat tad āśaṅkitaṃ pāpaṃ tasya jajñe viniścayaḥ', null, 2059007),
('ramayana-2-59-8', 8, 'Ayodhya Kanda, Sarga 59, Verse 8', 'ततः प्रचुक्रुशुर्दीनाः सस्वरं ता वराङ्गनाः।
करेणव इवारण्ये स्थानप्रच्युतयूथपाः॥', 'tataḥ pracukruśur dīnāḥ sasvaraṃ tā varāṅganāḥ
kareṇava ivāraṇye sthānapracyutayūthapāḥ', null, 2059008),
('ramayana-2-59-9', 9, 'Ayodhya Kanda, Sarga 59, Verse 9', 'तासामाक्रन्द शब्देन सहसोद्गतचेतने।
कौसल्या च सुमित्राच त्यक्तनिद्रे बभूवतुः॥', 'tāsām ākranda śabdena sahasodgatacetane
kausalyā ca sumitrāca tyaktanidre babhūvatuḥ', null, 2059009),
('ramayana-2-59-10', 10, 'Ayodhya Kanda, Sarga 59, Verse 10', 'कौसल्या च सुमित्रा च दृष्ट्वा स्पृष्ट्वा च पार्थिवम्।
हा नाथेति परिक्रुश्य पेततुर्धरणीतले॥', 'kausalyā ca sumitrā ca dṛṣṭvā spṛṣṭvā ca pārthivam
hā nātheti parikruśya petatur dharaṇītale', null, 2059010),
('ramayana-2-59-11', 11, 'Ayodhya Kanda, Sarga 59, Verse 11', 'सा कोसलेन्द्रदुहिता वेष्टमाना महीतले।
न बभ्राज रजोध्वस्ता तारेव गगनच्युता॥', 'sā kosalendraduhitā veṣṭamānā mahītale
na babhrāja rajodhvastā tāreva gaganacyutā', null, 2059011),
('ramayana-2-59-12', 12, 'Ayodhya Kanda, Sarga 59, Verse 12', 'तत्समुत्त्रस्तसंभ्रान्तं पर्युत्सुकजनाकुलम्।
सर्वतस्तुमुलाक्रन्दं परितापार्तबान्धवम्॥', 'tat samuttrastasaṃbhrāntaṃ paryutsukajanākulam
sarvatas tumulākrandaṃ paritāpārtabāndhavam', null, 2059012),
('ramayana-2-59-13', 13, 'Ayodhya Kanda, Sarga 59, Verse 13', 'सद्यो निपतितानन्दं दीनविक्लवदर्शनम्।
बभूव नरदेवस्य सद्म दिष्टान्तमीयुषः॥', 'sadyo nipatitānandaṃ dīnaviklavadarśanam
babhūva naradevasya sadma diṣṭāntam īyuṣaḥ', null, 2059013),
('ramayana-2-59-14', 14, 'Ayodhya Kanda, Sarga 59, Verse 14', 'अतीतमाज्ञाय तु पार्थिवर्षभं यशस्विनं संपरिवार्य पत्नयः।
भृशं रुदन्त्यः करुणं सुदुःखिताः प्रगृह्य बाहू व्यलपन्ननाथवत्॥', 'atītam ājñāya tu pārthivarṣabhaṃ yaśasvinaṃ saṃparivārya patnayaḥ
bhṛśaṃ rudantyaḥ karuṇaṃ suduḥkhitāḥ pragṛhya bāhū vyalapann anāthavat', null, 2059014)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 60 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-60-1', 1, 'Ayodhya Kanda, Sarga 60, Verse 1', 'तमग्निमिव संशान्तमम्बुहीनमिवार्णवम्।
हतप्रभमिवादित्यं स्वर्गथं प्रेक्ष्य भूमिपम्॥', 'tam agnim iva saṃśāntam ambuhīnam ivārṇavam
hataprabham ivādityaṃ svargathaṃ prekṣya bhūmipam', null, 2060001),
('ramayana-2-60-2', 2, 'Ayodhya Kanda, Sarga 60, Verse 2', 'कौसल्या बाष्पपूर्णाक्षी विविधं शोककर्शिता।
उपगृह्य शिरो राज्ञः कैकेयीं प्रत्यभाषत॥', 'kausalyā bāṣpapūrṇākṣī vividhaṃ śokakarśitā
upagṛhya śiro rājñaḥ kaikeyīṃ pratyabhāṣata', null, 2060002),
('ramayana-2-60-3', 3, 'Ayodhya Kanda, Sarga 60, Verse 3', 'सकामा भव कैकेयि भुङ्क्ष्व राज्यमकण्टकम्।
त्यक्त्वा राजानमेकाग्रा नृशंसे दुष्टचारिणि॥', 'sakāmā bhava kaikeyi bhuṅkṣva rājyam akaṇṭakam
tyaktvā rājānam ekāgrā nṛśaṃse duṣṭacāriṇi', null, 2060003),
('ramayana-2-60-4', 4, 'Ayodhya Kanda, Sarga 60, Verse 4', 'विहाय मां गतो रामो भर्ता च स्वर्गतो मम।
विपथे सार्थहीनेव नाहं जीवितुमुत्सहे॥', 'vihāya māṃ gato rāmo bhartā ca svargato mama
vipathe sārthahīneva nāhaṃ jīvitum utsahe', null, 2060004),
('ramayana-2-60-5', 5, 'Ayodhya Kanda, Sarga 60, Verse 5', 'भर्तारं तं परित्यज्य का स्त्री दैवतमात्मनः।
इच्छेज्जीवितुमन्यत्र कैकेय्यास्त्यक्तधर्मणः॥', 'bhartāraṃ taṃ parityajya kā strī daivatam ātmanaḥ
icchej jīvitum anyatra kaikeyyās tyaktadharmaṇaḥ', null, 2060005),
('ramayana-2-60-6', 6, 'Ayodhya Kanda, Sarga 60, Verse 6', 'न लुब्धो बुध्यते दोषान्किं पाकमिव भक्षयन्।
कुब्जानिमित्तं कैकेय्या राघवाणान्कुलं हतम्॥', 'na lubdho budhyate doṣān kiṃ pākam iva bhakṣayan
kubjānimittaṃ kaikeyyā rāghavāṇān kulaṃ hatam', null, 2060006),
('ramayana-2-60-7', 7, 'Ayodhya Kanda, Sarga 60, Verse 7', 'अनियोगे नियुक्तेन राज्ञा रामं विवासितम्।
सभार्यं जनकः श्रुत्वा परितप्स्यत्यहं यथा॥', 'aniyoge niyuktena rājñā rāmaṃ vivāsitam
sabhāryaṃ janakaḥ śrutvā paritapsyaty ahaṃ yathā', null, 2060007),
('ramayana-2-60-8', 8, 'Ayodhya Kanda, Sarga 60, Verse 8', 'रामः कमलपत्राक्षो जीवनाशमितो गतः।
विदेहराजस्य सुता तहा सीता तपस्विनी।
दुःखस्यानुचिता दुःखं वने पर्युद्विजिष्यति॥', 'rāmaḥ kamalapatrākṣo jīvanāśam ito gataḥ
videharājasya sutā tahā sītā tapasvinī
duḥkhasyānucitā duḥkhaṃ vane paryudvijiṣyati', null, 2060008),
('ramayana-2-60-9', 9, 'Ayodhya Kanda, Sarga 60, Verse 9', 'नदतां भीमघोषाणां निशासु मृगपक्षिणाम्।
निशम्य नूनं संस्त्रस्ता राघवं संश्रयिष्यति॥', 'nadatāṃ bhīmaghoṣāṇāṃ niśāsu mṛgapakṣiṇām
niśamya nūnaṃ saṃstrastā rāghavaṃ saṃśrayiṣyati', null, 2060009),
('ramayana-2-60-10', 10, 'Ayodhya Kanda, Sarga 60, Verse 10', 'वृद्धश्चैवाल्पपुत्रश्च वैदेहीमनिचिन्तयन्।
सोऽपि शोकसमाविष्टो ननु त्यक्ष्यति जीवितम्॥', 'vṛddhaś caivālpaputraś ca vaidehīm anicintayan
so ''pi śokasamāviṣṭo nanu tyakṣyati jīvitam', null, 2060010),
('ramayana-2-60-11', 11, 'Ayodhya Kanda, Sarga 60, Verse 11', 'तां ततः संपरिष्वज्य विलपन्तीं तपस्विनीम्।
व्यपनिन्युः सुदुःखार्तां कौसल्यां व्यावहारिकाः॥', 'tāṃ tataḥ saṃpariṣvajya vilapantīṃ tapasvinīm
vyapaninyuḥ suduḥkhārtāṃ kausalyāṃ vyāvahārikāḥ', null, 2060011),
('ramayana-2-60-12', 12, 'Ayodhya Kanda, Sarga 60, Verse 12', 'तैलद्रोण्यामथामात्याः संवेश्य जगतीपतिम्।
राज्ञः सर्वाण्यथादिष्टाश्चक्रुः कर्माण्यनन्तरम्॥', 'tailadroṇyām athāmātyāḥ saṃveśya jagatīpatim
rājñaḥ sarvāṇy athādiṣṭāś cakruḥ karmāṇy anantaram', null, 2060012),
('ramayana-2-60-13', 13, 'Ayodhya Kanda, Sarga 60, Verse 13', 'न तु संकलनं राज्ञो विना पुत्रेण मन्त्रिणः।
सर्वज्ञाः कर्तुमीषुस्ते ततो रक्षन्ति भूमिपम्॥', 'na tu saṃkalanaṃ rājño vinā putreṇa mantriṇaḥ
sarvajñāḥ kartum īṣus te tato rakṣanti bhūmipam', null, 2060013),
('ramayana-2-60-14', 14, 'Ayodhya Kanda, Sarga 60, Verse 14', 'तैलद्रोण्यां तु सचिवैः शायितं तं नराधिपम्।
हा मृतोऽयमिति ज्ञात्वा स्त्रियस्ताः पर्यदेवयन्॥', 'tailadroṇyāṃ tu sacivaiḥ śāyitaṃ taṃ narādhipam
hā mṛto ''yam iti jñātvā striyas tāḥ paryadevayan', null, 2060014),
('ramayana-2-60-15', 15, 'Ayodhya Kanda, Sarga 60, Verse 15', 'बाहूनुद्यम्य कृपणा नेत्रप्रस्रवणैर्मुखैः।
रुदन्त्यः शोकसंतप्ताः कृपणं पर्यदेवयन्॥', 'bāhūn udyamya kṛpaṇā netraprasravaṇair mukhaiḥ
rudantyaḥ śokasaṃtaptāḥ kṛpaṇaṃ paryadevayan', null, 2060015),
('ramayana-2-60-16', 16, 'Ayodhya Kanda, Sarga 60, Verse 16', 'निशानक्षत्रहीनेव स्त्रीव भर्तृविवर्जिता।
पुरी नाराजतायोध्या हीना राज्ञा महात्मना॥', 'niśānakṣatrahīneva strīva bhartṛvivarjitā
purī nārājatāyodhyā hīnā rājñā mahātmanā', null, 2060016),
('ramayana-2-60-17', 17, 'Ayodhya Kanda, Sarga 60, Verse 17', 'बाष्पपर्याकुलजना हाहाभूतकुलाङ्गना।
शून्यचत्वरवेश्मान्ता न बभ्राज यथापुरम्॥', 'bāṣpaparyākulajanā hāhābhūtakulāṅganā
śūnyacatvaraveśmāntā na babhrāja yathāpuram', null, 2060017),
('ramayana-2-60-18', 18, 'Ayodhya Kanda, Sarga 60, Verse 18', 'गतप्रभा द्यौरिव भास्करं विना व्यपेतनक्षत्रगणेव शर्वरी।
पुरी बभासे रहिता महात्मना न चास्रकण्ठाकुलमार्गचत्वरा॥', 'gataprabhā dyaur iva bhāskaraṃ vinā vyapetanakṣatragaṇeva śarvarī
purī babhāse rahitā mahātmanā na cāsrakaṇṭhākulamārgacatvarā', null, 2060018),
('ramayana-2-60-19', 19, 'Ayodhya Kanda, Sarga 60, Verse 19', 'नराश्च नार्यश्च समेत्य संघशो विगर्हमाणा भरतस्य मातरम्।
तदा नगर्यां नरदेवसंक्षये बभूवुरार्ता न च शर्म लेभिरे॥', 'narāś ca nāryaś ca sametya saṃghaśo vigarhamāṇā bharatasya mātaram
tadā nagaryāṃ naradevasaṃkṣaye babhūvur ārtā na ca śarma lebhire', null, 2060019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 61 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-61-1', 1, 'Ayodhya Kanda, Sarga 61, Verse 1', 'व्यतीतायां तु शर्वर्यामादित्यस्योदये ततः।
समेत्य राजकर्तारः सभामीयुर्द्विजातयः॥', 'vyatītāyāṃ tu śarvaryām ādityasyodaye tataḥ
sametya rājakartāraḥ sabhām īyur dvijātayaḥ', null, 2061001),
('ramayana-2-61-2', 2, 'Ayodhya Kanda, Sarga 61, Verse 2', 'मार्कण्डेयोऽथ मौद्गल्यो वामदेवश्च काश्यपः।
कात्ययनो गौतमश्च जाबालिश्च महायशाः॥', 'mārkaṇḍeyo ''tha maudgalyo vāmadevaś ca kāśyapaḥ
kātyayano gautamaś ca jābāliś ca mahāyaśāḥ', null, 2061002),
('ramayana-2-61-3', 3, 'Ayodhya Kanda, Sarga 61, Verse 3', 'एते द्विजाः सहामात्यैः पृथग्वाचमुदीरयन्।
वसिष्ठमेवाभिमुखाः श्रेष्ठो राजपुरोहितम्॥', 'ete dvijāḥ sahāmātyaiḥ pṛthag vācam udīrayan
vasiṣṭham evābhimukhāḥ śreṣṭho rājapurohitam', null, 2061003),
('ramayana-2-61-4', 4, 'Ayodhya Kanda, Sarga 61, Verse 4', 'अतीता शर्वरी दुःखं या नो वर्षशतोपमा।
अस्मिन्पञ्चत्वमापन्ने पुत्रशोकेन पार्थिवे॥', 'atītā śarvarī duḥkhaṃ yā no varṣaśatopamā
asmin pañcatvam āpanne putraśokena pārthive', null, 2061004),
('ramayana-2-61-5', 5, 'Ayodhya Kanda, Sarga 61, Verse 5', 'स्वर्गतश्च महाराजो रामश्चारण्यमाश्रितः।
लक्ष्मणश्चापि तेजस्वी रामेणैव गतः सह॥', 'svargataś ca mahārājo rāmaś cāraṇyam āśritaḥ
lakṣmaṇaś cāpi tejasvī rāmeṇaiva gataḥ saha', null, 2061005),
('ramayana-2-61-6', 6, 'Ayodhya Kanda, Sarga 61, Verse 6', 'उभौ भरतशत्रुघ्नौ क्केकयेषु परंतपौ।
पुरे राजगृहे रम्ये मातामहनिवेशने॥', 'ubhau bharataśatrughnau kkekayeṣu paraṃtapau
pure rājagṛhe ramye mātāmahaniveśane', null, 2061006),
('ramayana-2-61-7', 7, 'Ayodhya Kanda, Sarga 61, Verse 7', 'इक्ष्वाकूणामिहाद्यैव कश्चिद्राजा विधीयताम्।
अराजकं हि नो राष्ट्रं न विनाशमवाप्नुयात्॥', 'ikṣvākūṇām ihādyaiva kaś cid rājā vidhīyatām
arājakaṃ hi no rāṣṭraṃ na vināśam avāpnuyāt', null, 2061007),
('ramayana-2-61-8', 8, 'Ayodhya Kanda, Sarga 61, Verse 8', 'नाराजले जनपदे विद्युन्माली महास्वनः।
अभिवर्षति पर्जन्यो महीं दिव्येन वारिणा॥', 'nārājale janapade vidyunmālī mahāsvanaḥ
abhivarṣati parjanyo mahīṃ divyena vāriṇā', null, 2061008),
('ramayana-2-61-9', 9, 'Ayodhya Kanda, Sarga 61, Verse 9', 'नाराजके जनपदे बीजमुष्टिः प्रकीर्यते।
नाराकके पितुः पुत्रो भार्या वा वर्तते वशे॥', 'nārājake janapade bījamuṣṭiḥ prakīryate
nārākake pituḥ putro bhāryā vā vartate vaśe', null, 2061009),
('ramayana-2-61-10', 10, 'Ayodhya Kanda, Sarga 61, Verse 10', 'अराजके धनं नास्ति नास्ति भार्याप्यराजके।
इदमत्याहितं चान्यत्कुतः सत्यमराजके॥', 'arājake dhanaṃ nāsti nāsti bhāryāpy arājake
idam atyāhitaṃ cānyat kutaḥ satyam arājake', null, 2061010),
('ramayana-2-61-11', 11, 'Ayodhya Kanda, Sarga 61, Verse 11', 'नाराजके जनपदे कारयन्ति सभां नराः।
उद्यानानि च रम्याणि हृष्टाः पुण्यगृहाणि च॥', 'nārājake janapade kārayanti sabhāṃ narāḥ
udyānāni ca ramyāṇi hṛṣṭāḥ puṇyagṛhāṇi ca', null, 2061011),
('ramayana-2-61-12', 12, 'Ayodhya Kanda, Sarga 61, Verse 12', 'नाराजके जनपदे यज्ञशीला द्विजातयः।
सत्राण्यन्वासते दान्ता ब्राह्मणाः संशितव्रताः॥', 'nārājake janapade yajñaśīlā dvijātayaḥ
satrāṇy anvāsate dāntā brāhmaṇāḥ saṃśitavratāḥ', null, 2061012),
('ramayana-2-61-13', 13, 'Ayodhya Kanda, Sarga 61, Verse 13', 'नाराजके जनपदे प्रभूतनटनर्तकाः।
उत्सवाश्च समाजाश्च वर्धन्ते राष्ट्रवर्धनाः॥', 'nārājake janapade prabhūtanaṭanartakāḥ
utsavāś ca samājāś ca vardhante rāṣṭravardhanāḥ', null, 2061013),
('ramayana-2-61-14', 14, 'Ayodhya Kanda, Sarga 61, Verse 14', 'नारजके जनपदे सिद्धार्था व्यवहारिणः।
कथाभिरनुरज्यन्ते कथाशीलाः कथाप्रियैः॥', 'nārajake janapade siddhārthā vyavahāriṇaḥ
kathābhir anurajyante kathāśīlāḥ kathāpriyaiḥ', null, 2061014),
('ramayana-2-61-15', 15, 'Ayodhya Kanda, Sarga 61, Verse 15', 'नाराजके जनपदे वाहनैः शीघ्रगामिभिः।
नरा निर्यान्त्यरण्यानि नारीभिः सह कामिनः॥', 'nārājake janapade vāhanaiḥ śīghragāmibhiḥ
narā niryānty araṇyāni nārībhiḥ saha kāminaḥ', null, 2061015),
('ramayana-2-61-16', 16, 'Ayodhya Kanda, Sarga 61, Verse 16', 'नाराकजे जनपदे धनवन्तः सुरक्षिताः।
शेरते विवृत द्वाराः कृषिगोरक्षजीविनः॥', 'nārākaje janapade dhanavantaḥ surakṣitāḥ
śerate vivṛta dvārāḥ kṛṣigorakṣajīvinaḥ', null, 2061016),
('ramayana-2-61-17', 17, 'Ayodhya Kanda, Sarga 61, Verse 17', 'नाराजके जनपदे वणिजो दूरगामिनः।
गच्छन्ति क्षेममध्वानं बहुपुण्यसमाचिताः॥', 'nārājake janapade vaṇijo dūragāminaḥ
gacchanti kṣemam adhvānaṃ bahupuṇyasamācitāḥ', null, 2061017),
('ramayana-2-61-18', 18, 'Ayodhya Kanda, Sarga 61, Verse 18', 'नाराजके जनपदे चरत्येकचरो वशी।
भावयन्नात्मनात्मानं यत्रसायंगृहो मुनिः॥', 'nārājake janapade caraty ekacaro vaśī
bhāvayann ātmanātmānaṃ yatrasāyaṃgṛho muniḥ', null, 2061018),
('ramayana-2-61-19', 19, 'Ayodhya Kanda, Sarga 61, Verse 19', 'नाराजके जनपदे योगक्षेमं प्रवर्तते।
न चाप्यराजके सेना शत्रून्विषहते युधि॥', 'nārājake janapade yogakṣemaṃ pravartate
na cāpy arājake senā śatrūn viṣahate yudhi', null, 2061019),
('ramayana-2-61-20', 20, 'Ayodhya Kanda, Sarga 61, Verse 20', 'यथा ह्यनुदका नद्यो यथा वाप्यतृणं वनम्।
अगोपाला यथा गावस्तथा राष्ट्रमराजकम्॥', 'yathā hy anudakā nadyo yathā vāpy atṛṇaṃ vanam
agopālā yathā gāvas tathā rāṣṭram arājakam', null, 2061020),
('ramayana-2-61-21', 21, 'Ayodhya Kanda, Sarga 61, Verse 21', 'नाराजके जनपदे स्वकं भवति कस्य चित्।
मत्स्या इव नरा नित्यं भक्षयन्ति परस्परम्॥', 'nārājake janapade svakaṃ bhavati kasya cit
matsyā iva narā nityaṃ bhakṣayanti parasparam', null, 2061021),
('ramayana-2-61-22', 22, 'Ayodhya Kanda, Sarga 61, Verse 22', 'येहि संभिन्नमर्यादा नास्तिकाश्छिन्नसंशयाः।
तेऽपि भावाय कल्पन्ते राजदण्डनिपीडिताः॥', 'yehi saṃbhinnamaryādā nāstikāś chinnasaṃśayāḥ
te ''pi bhāvāya kalpante rājadaṇḍanipīḍitāḥ', null, 2061022),
('ramayana-2-61-23', 23, 'Ayodhya Kanda, Sarga 61, Verse 23', 'अहो तम इवेदं स्यान्न प्रज्ञायेत किं चन।
राजा चेन्न भवेंल्लोके विभजन्साध्वसाधुनी॥', 'aho tama ivedaṃ syān na prajñāyeta kiṃ cana
rājā cen na bhaveṃl loke vibhajan sādhvasādhunī', null, 2061023),
('ramayana-2-61-24', 24, 'Ayodhya Kanda, Sarga 61, Verse 24', 'जीवत्यपि महाराजे तवैव वचनं वयम्।
नातिक्रमामहे सर्वे वेलां प्राप्येव सागरः॥', 'jīvaty api mahārāje tavaiva vacanaṃ vayam
nātikramāmahe sarve velāṃ prāpyeva sāgaraḥ', null, 2061024),
('ramayana-2-61-25', 25, 'Ayodhya Kanda, Sarga 61, Verse 25', 'स नः समीक्ष्य द्विजवर्यवृत्तं नृपं विना राज्यमरण्यभूतम्।
कुमारमिक्ष्वाकुसुतं वदान्यं त्वमेव राजानमिहाभिषिञ्चय॥', 'sa naḥ samīkṣya dvijavaryavṛttaṃ nṛpaṃ vinā rājyam araṇyabhūtam
kumāram ikṣvākusutaṃ vadānyaṃ tvam eva rājānam ihābhiṣiñcaya', null, 2061025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 62 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-62-1', 1, 'Ayodhya Kanda, Sarga 62, Verse 1', 'तेषां तद्वचनं श्रुत्वा वसिष्ठः प्रत्युवाच ह।
मित्रामात्यगणान्सर्वान्ब्राह्मणांस्तानिदं वचः॥', 'teṣāṃ tad vacanaṃ śrutvā vasiṣṭhaḥ pratyuvāca ha
mitrāmātyagaṇān sarvān brāhmaṇāṃs tān idaṃ vacaḥ', null, 2062001),
('ramayana-2-62-2', 2, 'Ayodhya Kanda, Sarga 62, Verse 2', 'यदसौ मातुलकुले पुरे राजगृहे सुखी।
भरतो वसति भ्रात्रा शत्रुघ्नेन समन्वितः॥', 'yad asau mātulakule pure rājagṛhe sukhī
bharato vasati bhrātrā śatrughnena samanvitaḥ', null, 2062002),
('ramayana-2-62-3', 3, 'Ayodhya Kanda, Sarga 62, Verse 3', 'तच्छीघ्रं जवना दूता गच्छन्तु त्वरितैर्हयैः।
आनेतुं भ्रातरौ वीरौ किं समीक्षामहे वयम्॥', 'tac chīghraṃ javanā dūtā gacchantu tvaritair hayaiḥ
ānetuṃ bhrātarau vīrau kiṃ samīkṣāmahe vayam', null, 2062003),
('ramayana-2-62-4', 4, 'Ayodhya Kanda, Sarga 62, Verse 4', 'गच्छन्त्विति ततः सर्वे वसिष्ठं वाक्यमब्रुवन्।
तेषां तद्वचनं श्रुत्वा वसिष्ठो वाक्यमब्रवीत्॥', 'gacchantv iti tataḥ sarve vasiṣṭhaṃ vākyam abruvan
teṣāṃ tad vacanaṃ śrutvā vasiṣṭho vākyam abravīt', null, 2062004),
('ramayana-2-62-5', 5, 'Ayodhya Kanda, Sarga 62, Verse 5', 'एहि सिद्धार्थ विजय जयन्ताशोकनन्दन।
श्रूयतामितिकर्तव्यं सर्वानेव ब्रवीमि वः॥', 'ehi siddhārtha vijaya jayantāśokanandana
śrūyatām itikartavyaṃ sarvān eva bravīmi vaḥ', null, 2062005),
('ramayana-2-62-6', 6, 'Ayodhya Kanda, Sarga 62, Verse 6', 'पुरं राजगृहं गत्वा शीघ्रं शीघ्रजवैर्हयैः।
त्यक्तशोकैरिदं वाच्यः शासनाद्भरतो मम॥', 'puraṃ rājagṛhaṃ gatvā śīghraṃ śīghrajavair hayaiḥ
tyaktaśokair idaṃ vācyaḥ śāsanād bharato mama', null, 2062006),
('ramayana-2-62-7', 7, 'Ayodhya Kanda, Sarga 62, Verse 7', 'पुरोहितस्त्वां कुशलं प्राह सर्वे च मन्त्रिणः।
त्वरमाणश्च निर्याहि कृत्यमात्ययिकं त्वया॥', 'purohitas tvāṃ kuśalaṃ prāha sarve ca mantriṇaḥ
tvaramāṇaś ca niryāhi kṛtyam ātyayikaṃ tvayā', null, 2062007),
('ramayana-2-62-8', 8, 'Ayodhya Kanda, Sarga 62, Verse 8', 'मा चास्मै प्रोषितं रामं मा चास्मै पितरं मृतम्।
भवन्तः शंसिषुर्गत्वा राघवाणामिमं क्षयम्॥', 'mā cāsmai proṣitaṃ rāmaṃ mā cāsmai pitaraṃ mṛtam
bhavantaḥ śaṃsiṣur gatvā rāghavāṇām imaṃ kṣayam', null, 2062008),
('ramayana-2-62-9', 9, 'Ayodhya Kanda, Sarga 62, Verse 9', 'कौशेयानि च वस्त्राणि भूषणानि वराणि च।
क्षिप्रमादाय राज्ञश्च भरतस्य च गच्छत।
वसिष्ठेनाभ्यनुज्ञाता दूताः संत्वरिता ययुः॥', 'kauśeyāni ca vastrāṇi bhūṣaṇāni varāṇi ca
kṣipram ādāya rājñaś ca bharatasya ca gacchata
vasiṣṭhenābhyanujñātā dūtāḥ saṃtvaritā yayuḥ', null, 2062009),
('ramayana-2-62-10', 10, 'Ayodhya Kanda, Sarga 62, Verse 10', 'ते हस्तिन पुरे गङ्गां तीर्त्वा प्रत्यङ्मुखा ययुः।
पाञ्चालदेशमासाद्य मध्येन कुरुजाङ्गलम्॥', 'te hastina pure gaṅgāṃ tīrtvā pratyaṅmukhā yayuḥ
pāñcāladeśam āsādya madhyena kurujāṅgalam', null, 2062010),
('ramayana-2-62-11', 11, 'Ayodhya Kanda, Sarga 62, Verse 11', 'ते प्रसन्नोदकां दिव्यां नानाविहगसेविताम्।
उपातिजग्मुर्वेगेन शरदण्डां जनाकुलाम्॥', 'te prasannodakāṃ divyāṃ nānāvihagasevitām
upātijagmur vegena śaradaṇḍāṃ janākulām', null, 2062011),
('ramayana-2-62-12', 12, 'Ayodhya Kanda, Sarga 62, Verse 12', 'निकूलवृक्षमासाद्य दिव्यं सत्योपयाचनम्।
अभिगम्याभिवाद्यं तं कुलिङ्गां प्राविशन्पुरीम्॥', 'nikūlavṛkṣam āsādya divyaṃ satyopayācanam
abhigamyābhivādyaṃ taṃ kuliṅgāṃ prāviśan purīm', null, 2062012),
('ramayana-2-62-13', 13, 'Ayodhya Kanda, Sarga 62, Verse 13', 'अभिकालं ततः प्राप्य तेजोऽभिभवनाच्च्युताः।
ययुर्मध्येन बाह्लीकान्सुदामानं च पर्वतम्।
विष्णोः पदं प्रेक्षमाणा विपाशां चापि शाल्मलीम्॥', 'abhikālaṃ tataḥ prāpya tejo''bhibhavanāc cyutāḥ
yayur madhyena bāhlīkān sudāmānaṃ ca parvatam
viṣṇoḥ padaṃ prekṣamāṇā vipāśāṃ cāpi śālmalīm', null, 2062013),
('ramayana-2-62-14', 14, 'Ayodhya Kanda, Sarga 62, Verse 14', 'ते श्रान्तवाहना दूता विकृष्टेन सता पथा।
गिरि व्रजं पुर वरं शीघ्रमासेदुरञ्जसा॥', 'te śrāntavāhanā dūtā vikṛṣṭena satā pathā
giri vrajaṃ pura varaṃ śīghram āsedur añjasā', null, 2062014),
('ramayana-2-62-15', 15, 'Ayodhya Kanda, Sarga 62, Verse 15', 'भर्तुः प्रियार्थं कुलरक्षणार्थं भर्तुश्च वंशस्य परिग्रहार्थम्।
अहेडमानास्त्वरया स्म दूता रात्र्यां तु ते तत्पुरमेव याताः॥', 'bhartuḥ priyārthaṃ kularakṣaṇārthaṃ bhartuś ca vaṃśasya parigrahārtham
aheḍamānās tvarayā sma dūtā rātryāṃ tu te tat puram eva yātāḥ', null, 2062015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 63 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-63-1', 1, 'Ayodhya Kanda, Sarga 63, Verse 1', 'यामेव रात्रिं ते दूताः प्रविशन्ति स्म तां पुरीम्।
भरतेनापि तां रात्रिं स्वप्नो दृष्टोऽयमप्रियः॥', 'yām eva rātriṃ te dūtāḥ praviśanti sma tāṃ purīm
bharatenāpi tāṃ rātriṃ svapno dṛṣṭo ''yam apriyaḥ', null, 2063001),
('ramayana-2-63-2', 2, 'Ayodhya Kanda, Sarga 63, Verse 2', 'व्युष्टामेव तु तां रात्रिं दृष्ट्वा तं स्वप्नमप्रियम्।
पुत्रो राजाधिराजस्य सुभृशं पर्यतप्यत॥', 'vyuṣṭām eva tu tāṃ rātriṃ dṛṣṭvā taṃ svapnam apriyam
putro rājādhirājasya subhṛśaṃ paryatapyata', null, 2063002),
('ramayana-2-63-3', 3, 'Ayodhya Kanda, Sarga 63, Verse 3', 'तप्यमानं समाज्ञाय वयस्याः प्रियवादिनः।
आयासं हि विनेष्यन्तः सभायां चक्रिरे कथाः॥', 'tapyamānaṃ samājñāya vayasyāḥ priyavādinaḥ
āyāsaṃ hi vineṣyantaḥ sabhāyāṃ cakrire kathāḥ', null, 2063003),
('ramayana-2-63-4', 4, 'Ayodhya Kanda, Sarga 63, Verse 4', 'वादयन्ति तथा शान्तिं लासयन्त्यपि चापरे।
नाटकान्यपरे प्राहुर्हास्यानि विविधानि च॥', 'vādayanti tathā śāntiṃ lāsayanty api cāpare
nāṭakāny apare prāhur hāsyāni vividhāni ca', null, 2063004),
('ramayana-2-63-5', 5, 'Ayodhya Kanda, Sarga 63, Verse 5', 'स तैर्महात्मा भरतः सखिभिः प्रिय वादिभिः।
गोष्ठीहास्यानि कुर्वद्भिर्न प्राहृष्यत राघवः॥', 'sa tair mahātmā bharataḥ sakhibhiḥ priya vādibhiḥ
goṣṭhīhāsyāni kurvadbhir na prāhṛṣyata rāghavaḥ', null, 2063005),
('ramayana-2-63-6', 6, 'Ayodhya Kanda, Sarga 63, Verse 6', 'तमब्रवीत्प्रियसखो भरतं सखिभिर्वृतम्।
सुहृद्भिः पर्युपासीनः किं सखे नानुमोदसे॥', 'tam abravīt priyasakho bharataṃ sakhibhir vṛtam
suhṛdbhiḥ paryupāsīnaḥ kiṃ sakhe nānumodase', null, 2063006),
('ramayana-2-63-7', 7, 'Ayodhya Kanda, Sarga 63, Verse 7', 'एवं ब्रुवाणं सुहृदं भरतः प्रत्युवाच ह।
शृणु त्वं यन्निमित्तंमे दैन्यमेतदुपागतम्॥', 'evaṃ bruvāṇaṃ suhṛdaṃ bharataḥ pratyuvāca ha
śṛṇu tvaṃ yan nimittaṃme dainyam etad upāgatam', null, 2063007),
('ramayana-2-63-8', 8, 'Ayodhya Kanda, Sarga 63, Verse 8', 'स्वप्ने पितरमद्राक्षं मलिनं मुक्तमूर्धजम्।
पतन्तमद्रिशिखरात्कलुषे गोमये ह्रदे॥', 'svapne pitaram adrākṣaṃ malinaṃ muktamūrdhajam
patantam adriśikharāt kaluṣe gomaye hrade', null, 2063008),
('ramayana-2-63-9', 9, 'Ayodhya Kanda, Sarga 63, Verse 9', 'प्लवमानश्च मे दृष्टः स तस्मिन्गोमयह्रदे।
पिबन्नञ्जलिना तैलं हसन्निव मुहुर्मुहुः॥', 'plavamānaś ca me dṛṣṭaḥ sa tasmin gomayahrade
pibann añjalinā tailaṃ hasann iva muhur muhuḥ', null, 2063009),
('ramayana-2-63-10', 10, 'Ayodhya Kanda, Sarga 63, Verse 10', 'ततस्तिलोदनं भुक्त्वा पुनः पुनरधःशिराः।
तैलेनाभ्यक्तसर्वाङ्गस्तैलमेवावगाहत॥', 'tatas tilodanaṃ bhuktvā punaḥ punar adhaḥśirāḥ
tailenābhyaktasarvāṅgas tailam evāvagāhata', null, 2063010),
('ramayana-2-63-11', 11, 'Ayodhya Kanda, Sarga 63, Verse 11', 'स्वप्नेऽपि सागरं शुष्कं चन्द्रं च पतितं भुवि।
सहसा चापि संशन्तं ज्वलितं जातवेदसं॥', 'svapne ''pi sāgaraṃ śuṣkaṃ candraṃ ca patitaṃ bhuvi
sahasā cāpi saṃśantaṃ jvalitaṃ jātavedasaṃ', null, 2063011),
('ramayana-2-63-12', 12, 'Ayodhya Kanda, Sarga 63, Verse 12', 'अवदीर्णां च पृथिवीं शुष्कांश्च विविधान्द्रुमान्।
अहं पश्यामि विध्वस्तान्सधूमांश्चैव पार्वतान्॥', 'avadīrṇāṃ ca pṛthivīṃ śuṣkāṃś ca vividhān drumān
ahaṃ paśyāmi vidhvastān sadhūmāṃś caiva pārvatān', null, 2063012),
('ramayana-2-63-13', 13, 'Ayodhya Kanda, Sarga 63, Verse 13', 'पीठे कार्ष्णायसे चैनं निषण्णं कृष्णवाससं।
प्रहसन्ति स्म राजानं प्रमदाः कृष्णपिङ्गलाः॥', 'pīṭhe kārṣṇāyase cainaṃ niṣaṇṇaṃ kṛṣṇavāsasaṃ
prahasanti sma rājānaṃ pramadāḥ kṛṣṇapiṅgalāḥ', null, 2063013),
('ramayana-2-63-14', 14, 'Ayodhya Kanda, Sarga 63, Verse 14', 'त्वरमाणश्च धर्मात्मा रक्तमाल्यानुलेपनः।
रथेन खरयुक्तेन प्रयातो दक्षिणामुखः॥', 'tvaramāṇaś ca dharmātmā raktamālyānulepanaḥ
rathena kharayuktena prayāto dakṣiṇāmukhaḥ', null, 2063014),
('ramayana-2-63-15', 15, 'Ayodhya Kanda, Sarga 63, Verse 15', 'एवमेतन्मया दृष्टमिमां रात्रिं भयावहाम्।
अहं रामोऽथ वा राजा लक्ष्मणो वा मरिष्यति॥', 'evam etan mayā dṛṣṭam imāṃ rātriṃ bhayāvahām
ahaṃ rāmo ''tha vā rājā lakṣmaṇo vā mariṣyati', null, 2063015),
('ramayana-2-63-16', 16, 'Ayodhya Kanda, Sarga 63, Verse 16', 'नरो यानेन यः स्वप्ने खरयुक्तेन याति हि।
अचिरात्तस्य धूमाग्रं चितायां संप्रदृश्यते।
एतन्निमित्तं दीनोऽहं तन्न वः प्रतिपूजये॥', 'naro yānena yaḥ svapne kharayuktena yāti hi
acirāt tasya dhūmāgraṃ citāyāṃ saṃpradṛśyate
etannimittaṃ dīno ''haṃ tan na vaḥ pratipūjaye', null, 2063016),
('ramayana-2-63-17', 17, 'Ayodhya Kanda, Sarga 63, Verse 17', 'शुष्यतीव च मे कण्ठो न स्वस्थमिव मे मनः।
जुगुप्सन्निव चात्मानं न च पश्यामि कारणम्॥', 'śuṣyatīva ca me kaṇṭho na svastham iva me manaḥ
jugupsann iva cātmānaṃ na ca paśyāmi kāraṇam', null, 2063017),
('ramayana-2-63-18', 18, 'Ayodhya Kanda, Sarga 63, Verse 18', 'इमां हि दुःस्वप्नगतिं निशाम्य तामनेकरूपामवितर्कितां पुरा।
भयं महत्तद्धृदयान्न याति मे विचिन्त्य राजानमचिन्त्यदर्शनम्॥', 'imāṃ hi duḥsvapnagatiṃ niśāmya tām anekarūpām avitarkitāṃ purā
bhayaṃ mahat tad dhṛdayān na yāti me vicintya rājānam acintyadarśanam', null, 2063018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 64 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-64-1', 1, 'Ayodhya Kanda, Sarga 64, Verse 1', 'भरते ब्रुवति स्वप्नं दूतास्ते क्लान्तवाहनाः।
प्रविश्यासह्यपरिखं रम्यं राजगृहं पुरम्॥', 'bharate bruvati svapnaṃ dūtās te klāntavāhanāḥ
praviśyāsahyaparikhaṃ ramyaṃ rājagṛhaṃ puram', null, 2064001),
('ramayana-2-64-2', 2, 'Ayodhya Kanda, Sarga 64, Verse 2', 'समागम्य तु राज्ञा च राजपुत्रेण चार्चिताः।
राज्ञः पादौ गृहीत्वा तु तमूचुर्भरतं वचः॥', 'samāgamya tu rājñā ca rājaputreṇa cārcitāḥ
rājñaḥ pādau gṛhītvā tu tam ūcur bharataṃ vacaḥ', null, 2064002),
('ramayana-2-64-3', 3, 'Ayodhya Kanda, Sarga 64, Verse 3', 'पुरोहितस्त्वा कुशलं प्राह सर्वे च मन्त्रिणः।
त्वरमाणश्च निर्याहि कृत्यमात्ययिकं त्वया॥', 'purohitas tvā kuśalaṃ prāha sarve ca mantriṇaḥ
tvaramāṇaś ca niryāhi kṛtyam ātyayikaṃ tvayā', null, 2064003),
('ramayana-2-64-4', 4, 'Ayodhya Kanda, Sarga 64, Verse 4', 'अत्र विंशतिकोट्यस्तु नृपतेर्मातुलस्य ते।
दशकोट्यस्तु संपूर्णास्तथैव च नृपात्मज॥', 'atra viṃśatikoṭyas tu nṛpater mātulasya te
daśakoṭyas tu saṃpūrṇās tathaiva ca nṛpātmaja', null, 2064004),
('ramayana-2-64-5', 5, 'Ayodhya Kanda, Sarga 64, Verse 5', 'प्रतिगृह्य च तत्सर्वं स्वनुरक्तः सुहृज्जने।
दूतानुवाच भरतः कामैः संप्रतिपूज्य तान्॥', 'pratigṛhya ca tat sarvaṃ svanuraktaḥ suhṛjjane
dūtān uvāca bharataḥ kāmaiḥ saṃpratipūjya tān', null, 2064005),
('ramayana-2-64-6', 6, 'Ayodhya Kanda, Sarga 64, Verse 6', 'कच्चित्सुकुशली राजा पिता दशरथो मम।
कच्चिच्चारागता रामे लक्ष्मणे वा महात्मनि॥', 'kaccit sukuśalī rājā pitā daśaratho mama
kaccic cārāgatā rāme lakṣmaṇe vā mahātmani', null, 2064006),
('ramayana-2-64-7', 7, 'Ayodhya Kanda, Sarga 64, Verse 7', 'आर्या च धर्मनिरता धर्मज्ञा धर्मदर्शिनी।
अरोगा चापि कौसल्या माता रामस्य धीमतः॥', 'āryā ca dharmaniratā dharmajñā dharmadarśinī
arogā cāpi kausalyā mātā rāmasya dhīmataḥ', null, 2064007),
('ramayana-2-64-8', 8, 'Ayodhya Kanda, Sarga 64, Verse 8', 'कच्चित्सुमित्रा धर्मज्ञा जननी लक्ष्मणस्य या।
शत्रुघ्नस्य च वीरस्य सारोगा चापि मध्यमा॥', 'kaccit sumitrā dharmajñā jananī lakṣmaṇasya yā
śatrughnasya ca vīrasya sārogā cāpi madhyamā', null, 2064008),
('ramayana-2-64-9', 9, 'Ayodhya Kanda, Sarga 64, Verse 9', 'आत्मकामा सदा चण्डी क्रोधना प्राज्ञमानिनी।
अरोगा चापि कैकेयी माता मे किमुवाच ह॥', 'ātmakāmā sadā caṇḍī krodhanā prājñamāninī
arogā cāpi kaikeyī mātā me kim uvāca ha', null, 2064009),
('ramayana-2-64-10', 10, 'Ayodhya Kanda, Sarga 64, Verse 10', 'एवमुक्तास्तु ते दूता भरतेन महात्मना।
ऊचुः संप्रश्रितं वाक्यमिदं तं भरतं तदा।
कुशलास्ते नरव्याघ्र येषां कुशलमिच्छसि॥', 'evam uktās tu te dūtā bharatena mahātmanā
ūcuḥ saṃpraśritaṃ vākyam idaṃ taṃ bharataṃ tadā
kuśalās te naravyāghra yeṣāṃ kuśalam icchasi', null, 2064010),
('ramayana-2-64-11', 11, 'Ayodhya Kanda, Sarga 64, Verse 11', 'भरतश्चापि तान्दूतानेवमुक्तोऽभ्यभाषत।
आपृच्छेऽहं महाराजं दूताः संत्वरयन्ति माम्॥', 'bharataś cāpi tān dūtān evam ukto ''bhyabhāṣata
āpṛcche ''haṃ mahārājaṃ dūtāḥ saṃtvarayanti mām', null, 2064011),
('ramayana-2-64-12', 12, 'Ayodhya Kanda, Sarga 64, Verse 12', 'एवमुक्त्वा तु तान्दूतान्भरतः पार्थिवात्मजः।
दूतैः संचोदितो वाक्यं मातामहमुवाच ह॥', 'evam uktvā tu tān dūtān bharataḥ pārthivātmajaḥ
dūtaiḥ saṃcodito vākyaṃ mātāmaham uvāca ha', null, 2064012),
('ramayana-2-64-13', 13, 'Ayodhya Kanda, Sarga 64, Verse 13', 'राजन्पितुर्गमिष्यामि सकाशं दूतचोदितः।
पुनरप्यहमेष्यामि यदा मे त्वं स्मरिष्यसि॥', 'rājan pitur gamiṣyāmi sakāśaṃ dūtacoditaḥ
punar apy aham eṣyāmi yadā me tvaṃ smariṣyasi', null, 2064013),
('ramayana-2-64-14', 14, 'Ayodhya Kanda, Sarga 64, Verse 14', 'भरतेनैवमुक्तस्तु नृपो मातामहस्तदा।
तमुवाच शुभं वाक्यं शिरस्याघ्राय राघवम्॥', 'bharatenaivam uktas tu nṛpo mātāmahas tadā
tam uvāca śubhaṃ vākyaṃ śirasy āghrāya rāghavam', null, 2064014),
('ramayana-2-64-15', 15, 'Ayodhya Kanda, Sarga 64, Verse 15', 'गच्छ तातानुजाने त्वां कैकेयी सुप्रजास्त्वया।
मातरं कुशलं ब्रूयाः पितरं च परंतप॥', 'gaccha tātānujāne tvāṃ kaikeyī suprajās tvayā
mātaraṃ kuśalaṃ brūyāḥ pitaraṃ ca paraṃtapa', null, 2064015),
('ramayana-2-64-16', 16, 'Ayodhya Kanda, Sarga 64, Verse 16', 'पुरोहितं च कुशलं ये चान्ये द्विजसत्तमाः।
तौ च तात महेष्वासौ भ्रातरु रामलक्ष्मणौ॥', 'purohitaṃ ca kuśalaṃ ye cānye dvijasattamāḥ
tau ca tāta maheṣvāsau bhrātaru rāmalakṣmaṇau', null, 2064016),
('ramayana-2-64-17', 17, 'Ayodhya Kanda, Sarga 64, Verse 17', 'तस्मै हस्त्युत्तमांश्चित्रान्कम्बलानजिनानि च।
अभिसत्कृत्य कैकेयो भरताय धनं ददौ॥', 'tasmai hastyuttamāṃś citrān kambalān ajināni ca
abhisatkṛtya kaikeyo bharatāya dhanaṃ dadau', null, 2064017),
('ramayana-2-64-18', 18, 'Ayodhya Kanda, Sarga 64, Verse 18', 'रुक्म निष्कसहस्रे द्वे षोडशाश्वशतानि च।
सत्कृत्य कैकेयी पुत्रं केकयो धनमादिशत्॥', 'rukma niṣkasahasre dve ṣoḍaśāśvaśatāni ca
satkṛtya kaikeyī putraṃ kekayo dhanam ādiśat', null, 2064018),
('ramayana-2-64-19', 19, 'Ayodhya Kanda, Sarga 64, Verse 19', 'तथामात्यानभिप्रेतान्विश्वास्यांश्च गुणान्वितान्।
ददावश्वपतिः शीघ्रं भरतायानुयायिनः॥', 'tathāmātyān abhipretān viśvāsyāṃś ca guṇānvitān
dadāv aśvapatiḥ śīghraṃ bharatāyānuyāyinaḥ', null, 2064019),
('ramayana-2-64-20', 20, 'Ayodhya Kanda, Sarga 64, Verse 20', 'ऐरावतानैन्द्रशिरान्नागान्वै प्रियदर्शनान्।
खराञ्शीघ्रान्सुसंयुक्तान्मातुलोऽस्मै धनं ददौ॥', 'airāvatān aindraśirān nāgān vai priyadarśanān
kharāñ śīghrān susaṃyuktān mātulo ''smai dhanaṃ dadau', null, 2064020),
('ramayana-2-64-21', 21, 'Ayodhya Kanda, Sarga 64, Verse 21', 'अन्तःपुरेऽतिसंवृद्धान्व्याघ्रवीर्यबलान्वितान्।
दंष्ट्रायुधान्महाकायाञ्शुनश्चोपायनं ददौ॥', 'antaḥpure ''tisaṃvṛddhān vyāghravīryabalānvitān
daṃṣṭrāyudhān mahākāyāñ śunaś copāyanaṃ dadau', null, 2064021),
('ramayana-2-64-22', 22, 'Ayodhya Kanda, Sarga 64, Verse 22', 'स मातामहमापृच्छ्य मातुलं च युधाजितम्।
रथमारुह्य भरतः शत्रुघ्नसहितो ययौ॥', 'sa mātāmaham āpṛcchya mātulaṃ ca yudhājitam
ratham āruhya bharataḥ śatrughnasahito yayau', null, 2064022),
('ramayana-2-64-23', 23, 'Ayodhya Kanda, Sarga 64, Verse 23', 'रथान्मण्डलचक्रांश्च योजयित्वा परःशतम्।
उष्ट्रगोऽश्वखरैर्भृत्या भरतं यान्तमन्वयुः॥', 'rathān maṇḍalacakrāṃś ca yojayitvā paraḥśatam
uṣṭrago''śvakharair bhṛtyā bharataṃ yāntam anvayuḥ', null, 2064023),
('ramayana-2-64-24', 24, 'Ayodhya Kanda, Sarga 64, Verse 24', 'बलेन गुप्तो भरतो महात्मा सहार्यकस्यात्मसमैरमात्यैः।
आदाय शत्रुघ्नमपेतशत्रुर्गृहाद्ययौ सिद्ध इवेन्द्रलोकात्॥', 'balena gupto bharato mahātmā sahāryakasyātmasamair amātyaiḥ
ādāya śatrughnam apetaśatrur gṛhād yayau siddha ivendralokāt', null, 2064024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 65 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-65-1', 1, 'Ayodhya Kanda, Sarga 65, Verse 1', 'स प्राङ्मुखो राजगृहादभिनिर्याय वीर्यवान्।
ह्रादिनीं दूरपारां च प्रत्यक्स्रोतस्तरङ्गिणीम्।
शतद्रूमतरच्छ्रीमान्नदीमिक्ष्वाकुनन्दनः॥', 'sa prāṅmukho rājagṛhād abhiniryāya vīryavān
hrādinīṃ dūrapārāṃ ca pratyaksrotas taraṅgiṇīm
śatadrūm atarac chrīmān nadīm ikṣvākunandanaḥ', null, 2065001),
('ramayana-2-65-2', 2, 'Ayodhya Kanda, Sarga 65, Verse 2', 'एलधाने नदीं तीर्त्वा प्राप्य चापरपर्पटान्।
शिलामाकुर्वतीं तीर्त्वा आग्नेयं शल्यकर्तनम्॥', 'eladhāne nadīṃ tīrtvā prāpya cāparaparpaṭān
śilām ākurvatīṃ tīrtvā āgneyaṃ śalyakartanam', null, 2065002),
('ramayana-2-65-3', 3, 'Ayodhya Kanda, Sarga 65, Verse 3', 'सत्यसंधः शुचिः श्रीमान्प्रेक्षमाणः शिलावहाम्।
अत्ययात्स महाशैलान्वनं चैत्ररथं प्रति॥', 'satyasaṃdhaḥ śuciḥ śrīmān prekṣamāṇaḥ śilāvahām
atyayāt sa mahāśailān vanaṃ caitrarathaṃ prati', null, 2065003),
('ramayana-2-65-4', 4, 'Ayodhya Kanda, Sarga 65, Verse 4', 'वेगिनीं च कुलिङ्गाख्यां ह्रादिनीं पर्वतावृताम्।
यमुनां प्राप्य संतीर्णो बलमाश्वासयत्तदा॥', 'veginīṃ ca kuliṅgākhyāṃ hrādinīṃ parvatāvṛtām
yamunāṃ prāpya saṃtīrṇo balam āśvāsayat tadā', null, 2065004),
('ramayana-2-65-5', 5, 'Ayodhya Kanda, Sarga 65, Verse 5', 'शीतीकृत्य तु गात्राणि क्लान्तानाश्वास्य वाजिनः।
तत्र स्नात्वा च पीत्वा च प्रायादादाय चोदकम्॥', 'śītīkṛtya tu gātrāṇi klāntān āśvāsya vājinaḥ
tatra snātvā ca pītvā ca prāyād ādāya codakam', null, 2065005),
('ramayana-2-65-6', 6, 'Ayodhya Kanda, Sarga 65, Verse 6', 'राजपुत्रो महारण्यमनभीक्ष्णोपसेवितम्।
भद्रो भद्रेण यानेन मारुतः खमिवात्ययात्॥', 'rājaputro mahāraṇyam anabhīkṣṇopasevitam
bhadro bhadreṇa yānena mārutaḥ kham ivātyayāt', null, 2065006),
('ramayana-2-65-7', 7, 'Ayodhya Kanda, Sarga 65, Verse 7', 'तोरणं दक्षिणार्धेन जम्बूप्रस्थमुपागमत्।
वरूथं च ययौ रम्यं ग्रामं दशरथात्मजः॥', 'toraṇaṃ dakṣiṇārdhena jambūprastham upāgamat
varūthaṃ ca yayau ramyaṃ grāmaṃ daśarathātmajaḥ', null, 2065007),
('ramayana-2-65-8', 8, 'Ayodhya Kanda, Sarga 65, Verse 8', 'तत्र रम्ये वने वासं कृत्वासौ प्राङ्मुखो ययौ।
उद्यानमुज्जिहानायाः प्रियका यत्र पादपाः॥', 'tatra ramye vane vāsaṃ kṛtvāsau prāṅmukho yayau
udyānam ujjihānāyāḥ priyakā yatra pādapāḥ', null, 2065008),
('ramayana-2-65-9', 9, 'Ayodhya Kanda, Sarga 65, Verse 9', 'सालांस्तु प्रियकान्प्राप्य शीघ्रानास्थाय वाजिनः।
अनुज्ञाप्याथ भरतो वाहिनीं त्वरितो ययौ॥', 'sālāṃs tu priyakān prāpya śīghrān āsthāya vājinaḥ
anujñāpyātha bharato vāhinīṃ tvarito yayau', null, 2065009),
('ramayana-2-65-10', 10, 'Ayodhya Kanda, Sarga 65, Verse 10', 'वासं कृत्वा सर्वतीर्थे तीर्त्वा चोत्तानकां नदीम्।
अन्या नदीश्च विविधाः पार्वतीयैस्तुरंगमैः॥', 'vāsaṃ kṛtvā sarvatīrthe tīrtvā cottānakāṃ nadīm
anyā nadīś ca vividhāḥ pārvatīyais turaṃgamaiḥ', null, 2065010),
('ramayana-2-65-11', 11, 'Ayodhya Kanda, Sarga 65, Verse 11', 'हस्तिपृष्ठकमासाद्य कुटिकामत्यवर्तत।
ततार च नरव्याघ्रो लौहित्ये स कपीवतीम्।
एकसाले स्थाणुमतीं विनते गोमतीं नदीम्॥', 'hastipṛṣṭhakam āsādya kuṭikām atyavartata
tatāra ca naravyāghro lauhitye sa kapīvatīm
ekasāle sthāṇumatīṃ vinate gomatīṃ nadīm', null, 2065011),
('ramayana-2-65-12', 12, 'Ayodhya Kanda, Sarga 65, Verse 12', 'कलिङ्ग नगरे चापि प्राप्य सालवनं तदा।
भरतः क्षिप्रमागच्छत्सुपरिश्रान्तवाहनः॥', 'kaliṅga nagare cāpi prāpya sālavanaṃ tadā
bharataḥ kṣipram āgacchat supariśrāntavāhanaḥ', null, 2065012),
('ramayana-2-65-13', 13, 'Ayodhya Kanda, Sarga 65, Verse 13', 'वनं च समतीत्याशु शर्वर्यामरुणोदये।
अयोध्यां मनुना राज्ञा निर्मितां स ददर्श ह॥', 'vanaṃ ca samatītyāśu śarvaryām aruṇodaye
ayodhyāṃ manunā rājñā nirmitāṃ sa dadarśa ha', null, 2065013),
('ramayana-2-65-14', 14, 'Ayodhya Kanda, Sarga 65, Verse 14', 'तां पुरीं पुरुषव्याघ्रः सप्तरात्रोषिटः पथि।
अयोध्यामग्रतो दृष्ट्वा रथे सारथिमब्रवीत्॥', 'tāṃ purīṃ puruṣavyāghraḥ saptarātroṣiṭaḥ pathi
ayodhyām agrato dṛṣṭvā rathe sārathim abravīt', null, 2065014),
('ramayana-2-65-15', 15, 'Ayodhya Kanda, Sarga 65, Verse 15', 'एषा नातिप्रतीता मे पुण्योद्याना यशस्विनी।
अयोध्या दृश्यते दूरात्सारथे पाण्डुमृत्तिका॥', 'eṣā nātipratītā me puṇyodyānā yaśasvinī
ayodhyā dṛśyate dūrāt sārathe pāṇḍumṛttikā', null, 2065015),
('ramayana-2-65-16', 16, 'Ayodhya Kanda, Sarga 65, Verse 16', 'यज्वभिर्गुणसंपन्नैर्ब्राह्मणैर्वेदपारगैः।
भूयिष्ठमृद्धैराकीर्णा राजर्षिवरपालिता॥', 'yajvabhir guṇasaṃpannair brāhmaṇair vedapāragaiḥ
bhūyiṣṭham ṛddhair ākīrṇā rājarṣivarapālitā', null, 2065016),
('ramayana-2-65-17', 17, 'Ayodhya Kanda, Sarga 65, Verse 17', 'अयोध्यायां पुराशब्दः श्रूयते तुमुलो महान्।
समन्तान्नरनारीणां तमद्य न शृणोम्यहम्॥', 'ayodhyāyāṃ purāśabdaḥ śrūyate tumulo mahān
samantān naranārīṇāṃ tam adya na śṛṇomy aham', null, 2065017),
('ramayana-2-65-18', 18, 'Ayodhya Kanda, Sarga 65, Verse 18', 'उद्यानानि हि सायाह्ने क्रीडित्वोपरतैर्नरैः।
समन्ताद्विप्रधावद्भिः प्रकाशन्ते ममान्यदा॥', 'udyānāni hi sāyāhne krīḍitvoparatair naraiḥ
samantād vipradhāvadbhiḥ prakāśante mamānyadā', null, 2065018),
('ramayana-2-65-19', 19, 'Ayodhya Kanda, Sarga 65, Verse 19', 'तान्यद्यानुरुदन्तीव परित्यक्तानि कामिभिः।
अरण्यभूतेव पुरी सारथे प्रतिभाति मे॥', 'tāny adyānurudantīva parityaktāni kāmibhiḥ
araṇyabhūteva purī sārathe pratibhāti me', null, 2065019),
('ramayana-2-65-20', 20, 'Ayodhya Kanda, Sarga 65, Verse 20', 'न ह्यत्र यानैर्दृश्यन्ते न गजैर्न च वाजिभिः।
निर्यान्तो वाभियान्तो वा नरमुख्या यथापुरम्॥', 'na hy atra yānair dṛśyante na gajair na ca vājibhiḥ
niryānto vābhiyānto vā naramukhyā yathāpuram', null, 2065020),
('ramayana-2-65-21', 21, 'Ayodhya Kanda, Sarga 65, Verse 21', 'अनिष्टानि च पापानि पश्यामि विविधानि च।
निमित्तान्यमनोज्ञानि तेन सीदति ते मनः॥', 'aniṣṭāni ca pāpāni paśyāmi vividhāni ca
nimittāny amanojñāni tena sīdati te manaḥ', null, 2065021),
('ramayana-2-65-22', 22, 'Ayodhya Kanda, Sarga 65, Verse 22', 'द्वारेण वैजयन्तेन प्राविशच्छ्रान्तवाहनः।
द्वाःस्थैरुत्थाय विजयं पृष्टस्तैः सहितो ययौ॥', 'dvāreṇa vaijayantena prāviśac chrāntavāhanaḥ
dvāḥsthair utthāya vijayaṃ pṛṣṭas taiḥ sahito yayau', null, 2065022),
('ramayana-2-65-23', 23, 'Ayodhya Kanda, Sarga 65, Verse 23', 'स त्वनेकाग्रहृदयो द्वाःस्थं प्रत्यर्च्य तं जनम्।
सूतमश्वपतेः क्लान्तमब्रवीत्तत्र राघवः॥', 'sa tv anekāgrahṛdayo dvāḥsthaṃ pratyarcya taṃ janam
sūtam aśvapateḥ klāntam abravīt tatra rāghavaḥ', null, 2065023),
('ramayana-2-65-24', 24, 'Ayodhya Kanda, Sarga 65, Verse 24', 'श्रुता नो यादृशाः पूर्वं नृपतीनां विनाशने।
आकारास्तानहं सर्वानिह पश्यामि सारथे॥', 'śrutā no yādṛśāḥ pūrvaṃ nṛpatīnāṃ vināśane
ākārās tān ahaṃ sarvān iha paśyāmi sārathe', null, 2065024),
('ramayana-2-65-25', 25, 'Ayodhya Kanda, Sarga 65, Verse 25', 'मलिनं चाश्रुपूर्णाक्षं दीनं ध्यानपरं कृशम्।
सस्त्री पुंसं च पश्यामि जनमुत्कण्ठितं पुरे॥', 'malinaṃ cāśrupūrṇākṣaṃ dīnaṃ dhyānaparaṃ kṛśam
sastrī puṃsaṃ ca paśyāmi janam utkaṇṭhitaṃ pure', null, 2065025),
('ramayana-2-65-26', 26, 'Ayodhya Kanda, Sarga 65, Verse 26', 'इत्येवमुक्त्वा भरतः सूतं तं दीनमानसः।
तान्यनिष्टान्ययोध्यायां प्रेक्ष्य राजगृहं ययौ॥', 'ity evam uktvā bharataḥ sūtaṃ taṃ dīnamānasaḥ
tāny aniṣṭāny ayodhyāyāṃ prekṣya rājagṛhaṃ yayau', null, 2065026),
('ramayana-2-65-27', 27, 'Ayodhya Kanda, Sarga 65, Verse 27', 'तां शून्यशृङ्गाटकवेश्मरथ्यां रजोऽरुणद्वारकपाटयन्त्राम्।
दृष्ट्वा पुरीमिन्द्रपुरी प्रकाशां दुःखेन संपूर्णतरो बभूव॥', 'tāṃ śūnyaśṛṅgāṭakaveśmarathyāṃ rajo''ruṇadvārakapāṭayantrām
dṛṣṭvā purīm indrapurī prakāśāṃ duḥkhena saṃpūrṇataro babhūva', null, 2065027),
('ramayana-2-65-28', 28, 'Ayodhya Kanda, Sarga 65, Verse 28', 'बहूनि पश्यन्मनसोऽप्रियाणि यान्यन्न्यदा नास्य पुरे बभूवुः।
अवाक्शिरा दीनमना नहृष्टः पितुर्महात्मा प्रविवेश वेश्म॥', 'bahūni paśyan manaso ''priyāṇi yāny annyadā nāsya pure babhūvuḥ
avākśirā dīnamanā nahṛṣṭaḥ pitur mahātmā praviveśa veśma', null, 2065028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 66 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-66-1', 1, 'Ayodhya Kanda, Sarga 66, Verse 1', 'अपश्यंस्तु ततस्तत्र पितरं पितुरालये।
जगाम भरतो द्रष्टुं मातरं मातुरालये॥', 'apaśyaṃs tu tatas tatra pitaraṃ pitur ālaye
jagāma bharato draṣṭuṃ mātaraṃ mātur ālaye', null, 2066001),
('ramayana-2-66-2', 2, 'Ayodhya Kanda, Sarga 66, Verse 2', 'अनुप्राप्तं तु तं दृष्ट्वा कैकेयी प्रोषितं सुतम्।
उत्पपात तदा हृष्टा त्यक्त्वा सौवर्णमानसं॥', 'anuprāptaṃ tu taṃ dṛṣṭvā kaikeyī proṣitaṃ sutam
utpapāta tadā hṛṣṭā tyaktvā sauvarṇamānasaṃ', null, 2066002),
('ramayana-2-66-3', 3, 'Ayodhya Kanda, Sarga 66, Verse 3', 'स प्रविश्यैव धर्मात्मा स्वगृहं श्रीविवर्जितम्।
भरतः प्रेक्ष्य जग्राह जनन्याश्चरणौ शुभौ॥', 'sa praviśyaiva dharmātmā svagṛhaṃ śrīvivarjitam
bharataḥ prekṣya jagrāha jananyāś caraṇau śubhau', null, 2066003),
('ramayana-2-66-4', 4, 'Ayodhya Kanda, Sarga 66, Verse 4', 'तं मूर्ध्नि समुपाघ्राय परिष्वज्य यशस्विनम्।
अङ्के भरतमारोप्य प्रष्टुं समुपचक्रमे॥', 'taṃ mūrdhni samupāghrāya pariṣvajya yaśasvinam
aṅke bharatam āropya praṣṭuṃ samupacakrame', null, 2066004),
('ramayana-2-66-5', 5, 'Ayodhya Kanda, Sarga 66, Verse 5', 'अद्य ते कति चिद्रात्र्यश्च्युतस्यार्यकवेश्मनः।
अपि नाध्वश्रमः शीघ्रं रथेनापततस्तव॥', 'adya te kati cid rātryaś cyutasyāryakaveśmanaḥ
api nādhvaśramaḥ śīghraṃ rathenāpatatas tava', null, 2066005),
('ramayana-2-66-6', 6, 'Ayodhya Kanda, Sarga 66, Verse 6', 'आर्यकस्ते सुकुशलो युधाजिन्मातुलस्तव।
प्रवासाच्च सुखं पुत्र सर्वं मे वक्तुमर्हसि॥', 'āryakas te sukuśalo yudhājin mātulas tava
pravāsāc ca sukhaṃ putra sarvaṃ me vaktum arhasi', null, 2066006),
('ramayana-2-66-7', 7, 'Ayodhya Kanda, Sarga 66, Verse 7', 'एवं पृष्ठस्तु कैकेय्या प्रियं पार्थिवनन्दनः।
आचष्ट भरतः सर्वं मात्रे राजीवलोचनः॥', 'evaṃ pṛṣṭhas tu kaikeyyā priyaṃ pārthivanandanaḥ
ācaṣṭa bharataḥ sarvaṃ mātre rājīvalocanaḥ', null, 2066007),
('ramayana-2-66-8', 8, 'Ayodhya Kanda, Sarga 66, Verse 8', 'अद्य मे सप्तमी रात्रिश्च्युतस्यार्यकवेश्मनः।
अम्बायाः कुशली तातो युधाजिन्मातुलश्च मे॥', 'adya me saptamī rātriś cyutasyāryakaveśmanaḥ
ambāyāḥ kuśalī tāto yudhājin mātulaś ca me', null, 2066008),
('ramayana-2-66-9', 9, 'Ayodhya Kanda, Sarga 66, Verse 9', 'यन्मे धनं च रत्नं च ददौ राजा परंतपः।
परिश्रान्तं पथ्यभवत्ततोऽहं पूर्वमागतः॥', 'yan me dhanaṃ ca ratnaṃ ca dadau rājā paraṃtapaḥ
pariśrāntaṃ pathy abhavat tato ''haṃ pūrvam āgataḥ', null, 2066009),
('ramayana-2-66-10', 10, 'Ayodhya Kanda, Sarga 66, Verse 10', 'राजवाक्यहरैर्दूतैस्त्वर्यमाणोऽहमागतः।
यदहं प्रष्टुमिच्छामि तदम्बा वक्तुमर्हसि॥', 'rājavākyaharair dūtais tvaryamāṇo ''ham āgataḥ
yad ahaṃ praṣṭum icchāmi tad ambā vaktum arhasi', null, 2066010),
('ramayana-2-66-11', 11, 'Ayodhya Kanda, Sarga 66, Verse 11', 'शून्योऽयं शयनीयस्ते पर्यङ्को हेमभूषितः।
न चायमिक्ष्वाकुजनः प्रहृष्टः प्रतिभाति मे॥', 'śūnyo ''yaṃ śayanīyas te paryaṅko hemabhūṣitaḥ
na cāyam ikṣvākujanaḥ prahṛṣṭaḥ pratibhāti me', null, 2066011),
('ramayana-2-66-12', 12, 'Ayodhya Kanda, Sarga 66, Verse 12', 'राजा भवति भूयिष्ठमिहाम्बाया निवेशने।
तमहं नाद्य पश्यामि द्रष्टुमिच्छन्निहागतः॥', 'rājā bhavati bhūyiṣṭham ihāmbāyā niveśane
tam ahaṃ nādya paśyāmi draṣṭum icchann ihāgataḥ', null, 2066012),
('ramayana-2-66-13', 13, 'Ayodhya Kanda, Sarga 66, Verse 13', 'पितुर्ग्रहीष्ये चरणौ तं ममाख्याहि पृच्छतः।
आहोस्विदम्ब ज्येष्ठायाः कौसल्याया निवेशने॥', 'pitur grahīṣye caraṇau taṃ mamākhyāhi pṛcchataḥ
āhosvid amba jyeṣṭhāyāḥ kausalyāyā niveśane', null, 2066013),
('ramayana-2-66-14', 14, 'Ayodhya Kanda, Sarga 66, Verse 14', 'तं प्रत्युवाच कैकेयी प्रियवद्घोरमप्रियम्।
अजानन्तं प्रजानन्ती राज्यलोभेन मोहिता।
या गतिः सर्वभूतानां तां गतिं ते पिता गतः॥', 'taṃ pratyuvāca kaikeyī priyavad ghoram apriyam
ajānantaṃ prajānantī rājyalobhena mohitā
yā gatiḥ sarvabhūtānāṃ tāṃ gatiṃ te pitā gataḥ', null, 2066014),
('ramayana-2-66-15', 15, 'Ayodhya Kanda, Sarga 66, Verse 15', 'तच्छ्रुत्वा भरतो वाक्यं धर्माभिजनवाञ्शुचिः।
पपात सहसा भूमौ पितृशोकबलार्दितः॥', 'tac chrutvā bharato vākyaṃ dharmābhijanavāñ śuciḥ
papāta sahasā bhūmau pitṛśokabalārditaḥ', null, 2066015),
('ramayana-2-66-16', 16, 'Ayodhya Kanda, Sarga 66, Verse 16', 'ततः शोकेन संवीतः पितुर्मरणदुःखितः।
विललाप महातेजा भ्रान्ताकुलितचेतनः॥', 'tataḥ śokena saṃvītaḥ pitur maraṇaduḥkhitaḥ
vilalāpa mahātejā bhrāntākulitacetanaḥ', null, 2066016),
('ramayana-2-66-17', 17, 'Ayodhya Kanda, Sarga 66, Verse 17', 'एतत्सुरुचिरं भाति पितुर्मे शयनं पुरा।
तदिदं न विभात्यद्य विहीनं तेन धीमता॥', 'etat suruciraṃ bhāti pitur me śayanaṃ purā
tad idaṃ na vibhāty adya vihīnaṃ tena dhīmatā', null, 2066017),
('ramayana-2-66-18', 18, 'Ayodhya Kanda, Sarga 66, Verse 18', 'तमार्तं देवसंकाशं समीक्ष्य पतितं भुवि।
उत्थापयित्वा शोकार्तं वचनं चेदमब्रवीत्॥', 'tam ārtaṃ devasaṃkāśaṃ samīkṣya patitaṃ bhuvi
utthāpayitvā śokārtaṃ vacanaṃ cedam abravīt', null, 2066018),
('ramayana-2-66-19', 19, 'Ayodhya Kanda, Sarga 66, Verse 19', 'उत्तिष्ठोत्तिष्ठ किं शेषे राजपुत्र महायशः।
त्वद्विधा न हि शोचन्ति सन्तः सदसि संमताः॥', 'uttiṣṭhottiṣṭha kiṃ śeṣe rājaputra mahāyaśaḥ
tvadvidhā na hi śocanti santaḥ sadasi saṃmatāḥ', null, 2066019),
('ramayana-2-66-20', 20, 'Ayodhya Kanda, Sarga 66, Verse 20', 'स रुदत्या चिरं कालं भूमौ विपरिवृत्य च।
जननीं प्रत्युवाचेदं शोकैर्बहुभिरावृतः॥', 'sa rudatyā ciraṃ kālaṃ bhūmau viparivṛtya ca
jananīṃ pratyuvācedaṃ śokair bahubhir āvṛtaḥ', null, 2066020),
('ramayana-2-66-21', 21, 'Ayodhya Kanda, Sarga 66, Verse 21', 'अभिषेक्ष्यति रामं तु राजा यज्ञं नु यक्ष्यति।
इत्यहं कृतसंकल्पो हृष्टो यात्रामयासिषम्॥', 'abhiṣekṣyati rāmaṃ tu rājā yajñaṃ nu yakṣyati
ity ahaṃ kṛtasaṃkalpo hṛṣṭo yātrām ayāsiṣam', null, 2066021),
('ramayana-2-66-22', 22, 'Ayodhya Kanda, Sarga 66, Verse 22', 'तदिदं ह्यन्यथा भूतं व्यवदीर्णं मनो मम।
पितरं यो न पश्यामि नित्यं प्रियहिते रतम्॥', 'tad idaṃ hy anyathā bhūtaṃ vyavadīrṇaṃ mano mama
pitaraṃ yo na paśyāmi nityaṃ priyahite ratam', null, 2066022),
('ramayana-2-66-23', 23, 'Ayodhya Kanda, Sarga 66, Verse 23', 'अम्ब केनात्यगाद्राजा व्याधिना मय्यनागते।
धन्या रामादयः सर्वे यैः पिता संस्कृतः स्वयम्॥', 'amba kenātyagād rājā vyādhinā mayy anāgate
dhanyā rāmādayaḥ sarve yaiḥ pitā saṃskṛtaḥ svayam', null, 2066023),
('ramayana-2-66-24', 24, 'Ayodhya Kanda, Sarga 66, Verse 24', 'न नूनं मां महाराजः प्राप्तं जानाति कीर्तिमान्।
उपजिघ्रेद्धि मां मूर्ध्नि तातः संनम्य सत्वरम्॥', 'na nūnaṃ māṃ mahārājaḥ prāptaṃ jānāti kīrtimān
upajighred dhi māṃ mūrdhni tātaḥ saṃnamya satvaram', null, 2066024),
('ramayana-2-66-25', 25, 'Ayodhya Kanda, Sarga 66, Verse 25', 'क्व स पाणिः सुखस्पर्शस्तातस्याक्लिष्टकर्मणः।
येन मां रजसा ध्वस्तमभीक्ष्णं परिमार्जति॥', 'kva sa pāṇiḥ sukhasparśas tātasyākliṣṭakarmaṇaḥ
yena māṃ rajasā dhvastam abhīkṣṇaṃ parimārjati', null, 2066025),
('ramayana-2-66-26', 26, 'Ayodhya Kanda, Sarga 66, Verse 26', 'यो मे भ्राता पिता बन्धुर्यस्य दासोऽस्मि धीमतः।
तस्य मां शीघ्रमाख्याहि रामस्याक्लिष्ट कर्मणः॥', 'yo me bhrātā pitā bandhur yasya dāso ''smi dhīmataḥ
tasya māṃ śīghram ākhyāhi rāmasyākliṣṭa karmaṇaḥ', null, 2066026),
('ramayana-2-66-27', 27, 'Ayodhya Kanda, Sarga 66, Verse 27', 'पिता हि भवति ज्येष्ठो धर्ममार्यस्य जानतः।
तस्य पादौ ग्रहीष्यामि स हीदानीं गतिर्मम॥', 'pitā hi bhavati jyeṣṭho dharmam āryasya jānataḥ
tasya pādau grahīṣyāmi sa hīdānīṃ gatir mama', null, 2066027),
('ramayana-2-66-28', 28, 'Ayodhya Kanda, Sarga 66, Verse 28', 'आर्ये किमब्रवीद्राजा पिता मे सत्यविक्रमः।
पश्चिमं साधु संदेशमिच्छामि श्रोतुमात्मनः॥', 'ārye kim abravīd rājā pitā me satyavikramaḥ
paścimaṃ sādhu saṃdeśam icchāmi śrotum ātmanaḥ', null, 2066028),
('ramayana-2-66-29', 29, 'Ayodhya Kanda, Sarga 66, Verse 29', 'इति पृष्टा यथातत्त्वं कैकेयी वाक्यमब्रवीत्।
रामेति राजा विलपन्हा सीते लक्ष्मणेति च।
स महात्मा परं लोकं गतो गतिमतां वरः॥', 'iti pṛṣṭā yathātattvaṃ kaikeyī vākyam abravīt
rāmeti rājā vilapan hā sīte lakṣmaṇeti ca
sa mahātmā paraṃ lokaṃ gato gatimatāṃ varaḥ', null, 2066029),
('ramayana-2-66-30', 30, 'Ayodhya Kanda, Sarga 66, Verse 30', 'इमां तु पश्चिमां वाचं व्याजहार पिता तव।
काल धर्मपरिक्षिप्तः पाशैरिव महागजः॥', 'imāṃ tu paścimāṃ vācaṃ vyājahāra pitā tava
kāla dharmaparikṣiptaḥ pāśair iva mahāgajaḥ', null, 2066030),
('ramayana-2-66-31', 31, 'Ayodhya Kanda, Sarga 66, Verse 31', 'सिद्धार्थास्तु नरा राममागतं सीतया सह।
लक्ष्मणं च महाबाहुं द्रक्ष्यन्ति पुनरागतम्॥', 'siddhārthās tu narā rāmam āgataṃ sītayā saha
lakṣmaṇaṃ ca mahābāhuṃ drakṣyanti punar āgatam', null, 2066031),
('ramayana-2-66-32', 32, 'Ayodhya Kanda, Sarga 66, Verse 32', 'तच्छ्रुत्वा विषसादैव द्वितीया प्रियशंसनात्।
विषण्णवदनो भूत्वा भूयः पप्रच्छ मातरम्॥', 'tac chrutvā viṣasādaiva dvitīyā priyaśaṃsanāt
viṣaṇṇavadano bhūtvā bhūyaḥ papraccha mātaram', null, 2066032),
('ramayana-2-66-33', 33, 'Ayodhya Kanda, Sarga 66, Verse 33', 'क्व चेदानीं स धर्मात्मा कौसल्यानन्दवर्धनः।
लक्ष्मणेन सह भ्रात्रा सीतया च समं गतः॥', 'kva cedānīṃ sa dharmātmā kausalyānandavardhanaḥ
lakṣmaṇena saha bhrātrā sītayā ca samaṃ gataḥ', null, 2066033),
('ramayana-2-66-34', 34, 'Ayodhya Kanda, Sarga 66, Verse 34', 'तथा पृष्टा यथातत्त्वमाख्यातुमुपचक्रमे।
मातास्य युगपद्वाक्यं विप्रियं प्रियशङ्कया॥', 'tathā pṛṣṭā yathātattvam ākhyātum upacakrame
mātāsya yugapad vākyaṃ vipriyaṃ priyaśaṅkayā', null, 2066034),
('ramayana-2-66-35', 35, 'Ayodhya Kanda, Sarga 66, Verse 35', 'स हि राजसुतः पुत्र चीरवासा महावनम्।
दण्डकान्सह वैदेह्या लक्ष्मणानुचरो गतः॥', 'sa hi rājasutaḥ putra cīravāsā mahāvanam
daṇḍakān saha vaidehyā lakṣmaṇānucaro gataḥ', null, 2066035),
('ramayana-2-66-36', 36, 'Ayodhya Kanda, Sarga 66, Verse 36', 'तच्छ्रुत्वा भरतस्त्रस्तो भ्रातुश्चारित्रशङ्कया।
स्वस्य वंशस्य माहात्म्यात्प्रष्टुं समुपचक्रमे॥', 'tac chrutvā bharatas trasto bhrātuś cāritraśaṅkayā
svasya vaṃśasya māhātmyāt praṣṭuṃ samupacakrame', null, 2066036),
('ramayana-2-66-37', 37, 'Ayodhya Kanda, Sarga 66, Verse 37', 'कच्चिन्न ब्राह्मणवधं हृतं रामेण कस्य चित्।
कच्चिन्नाढ्यो दरिद्रो वा तेनापापो विहिंसितः॥', 'kaccin na brāhmaṇavadhaṃ hṛtaṃ rāmeṇa kasya cit
kaccin nāḍhyo daridro vā tenāpāpo vihiṃsitaḥ', null, 2066037),
('ramayana-2-66-38', 38, 'Ayodhya Kanda, Sarga 66, Verse 38', 'कच्चिन्न परदारान्वा राजपुत्रोऽभिमन्यते।
कस्मात्स दण्डकारण्ये भ्रूणहेव विवासितः॥', 'kaccin na paradārān vā rājaputro ''bhimanyate
kasmāt sa daṇḍakāraṇye bhrūṇaheva vivāsitaḥ', null, 2066038),
('ramayana-2-66-39', 39, 'Ayodhya Kanda, Sarga 66, Verse 39', 'अथास्य चपला माता तत्स्वकर्म यथातथम्।
तेनैव स्त्रीस्वभावेन व्याहर्तुमुपचक्रमे॥', 'athāsya capalā mātā tat svakarma yathātatham
tenaiva strīsvabhāvena vyāhartum upacakrame', null, 2066039),
('ramayana-2-66-40', 40, 'Ayodhya Kanda, Sarga 66, Verse 40', 'न ब्राह्मणधनं किं चिद्धृतं रामेण कस्य चित्।
कश्चिन्नाढ्यो दरिद्रो वा तेनापापो विहिंसितः।
न रामः परदारांश्च चक्षुर्भ्यामपि पश्यति॥', 'na brāhmaṇadhanaṃ kiṃ cid dhṛtaṃ rāmeṇa kasya cit
kaś cin nāḍhyo daridro vā tenāpāpo vihiṃsitaḥ
na rāmaḥ paradārāṃś ca cakṣurbhyām api paśyati', null, 2066040),
('ramayana-2-66-41', 41, 'Ayodhya Kanda, Sarga 66, Verse 41', 'मया तु पुत्र श्रुत्वैव रामस्यैवाभिषेचनम्।
याचितस्ते पिता राज्यं रामस्य च विवासनम्॥', 'mayā tu putra śrutvaiva rāmasyaivābhiṣecanam
yācitas te pitā rājyaṃ rāmasya ca vivāsanam', null, 2066041),
('ramayana-2-66-42', 42, 'Ayodhya Kanda, Sarga 66, Verse 42', 'स स्ववृत्तिं समास्थाय पिता ते तत्तथाकरोत्।
रामश्च सहसौमित्रिः प्रेषितः सह सीतया॥', 'sa svavṛttiṃ samāsthāya pitā te tat tathākarot
rāmaś ca sahasaumitriḥ preṣitaḥ saha sītayā', null, 2066042),
('ramayana-2-66-43', 43, 'Ayodhya Kanda, Sarga 66, Verse 43', 'तमपश्यन्प्रियं पुत्रं महीपालो महायशाः।
पुत्रशोकपरिद्यूनः पञ्चत्वमुपपेदिवान्॥', 'tam apaśyan priyaṃ putraṃ mahīpālo mahāyaśāḥ
putraśokaparidyūnaḥ pañcatvam upapedivān', null, 2066043),
('ramayana-2-66-44', 44, 'Ayodhya Kanda, Sarga 66, Verse 44', 'त्वया त्विदानीं धर्मज्ञ राजत्वमवलम्ब्यताम्।
त्वत्कृते हि मया सर्वमिदमेवंविधं कृतम्॥', 'tvayā tv idānīṃ dharmajña rājatvam avalambyatām
tvatkṛte hi mayā sarvam idam evaṃvidhaṃ kṛtam', null, 2066044),
('ramayana-2-66-45', 45, 'Ayodhya Kanda, Sarga 66, Verse 45', 'तत्पुत्र शीघ्रं विधिना विधिज्ञैर्वसिष्ठमुख्यैः सहितो द्विजेन्द्रैः।
संकाल्य राजानमदीनसत्त्वमात्मानमुर्व्यामभिषेचयस्व॥', 'tat putra śīghraṃ vidhinā vidhijñair vasiṣṭhamukhyaiḥ sahito dvijendraiḥ
saṃkālya rājānam adīnasattvam ātmānam urvyām abhiṣecayasva', null, 2066045)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 67 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-67-1', 1, 'Ayodhya Kanda, Sarga 67, Verse 1', 'श्रुत्वा तु पितरं वृत्तं भ्रातरु च विवासितौ।
भरतो दुःखसंतप्त इदं वचनमब्रवीत्॥', 'śrutvā tu pitaraṃ vṛttaṃ bhrātaru ca vivāsitau
bharato duḥkhasaṃtapta idaṃ vacanam abravīt', null, 2067001),
('ramayana-2-67-2', 2, 'Ayodhya Kanda, Sarga 67, Verse 2', 'किं नुण्कार्यं हतस्येह मम राज्येन शोचतः।
विहीनस्याथ पित्रा च भ्रात्रा पितृसमेन च॥', 'kiṃ nuṇkāryaṃ hatasyeha mama rājyena śocataḥ
vihīnasyātha pitrā ca bhrātrā pitṛsamena ca', null, 2067002),
('ramayana-2-67-3', 3, 'Ayodhya Kanda, Sarga 67, Verse 3', 'दुःखे मे दुःखमकरोर्व्रणे क्षारमिवादधाः।
राजानं प्रेतभावस्थं कृत्वा रामं च तापसं॥', 'duḥkhe me duḥkham akaror vraṇe kṣāram ivādadhāḥ
rājānaṃ pretabhāvasthaṃ kṛtvā rāmaṃ ca tāpasaṃ', null, 2067003),
('ramayana-2-67-4', 4, 'Ayodhya Kanda, Sarga 67, Verse 4', 'कुलस्य त्वमभावाय कालरात्रिरिवागता।
अङ्गारमुपगूह्य स्म पिता मे नावबुद्धवान्॥', 'kulasya tvam abhāvāya kālarātrir ivāgatā
aṅgāram upagūhya sma pitā me nāvabuddhavān', null, 2067004),
('ramayana-2-67-5', 5, 'Ayodhya Kanda, Sarga 67, Verse 5', 'कौसल्या च सुमित्रा च पुत्रशोकाभिपीडिते।
दुष्करं यदि जीवेतां प्राप्य त्वां जननीं मम॥', 'kausalyā ca sumitrā ca putraśokābhipīḍite
duṣkaraṃ yadi jīvetāṃ prāpya tvāṃ jananīṃ mama', null, 2067005),
('ramayana-2-67-6', 6, 'Ayodhya Kanda, Sarga 67, Verse 6', 'ननु त्वार्योऽपि धर्मात्मा त्वयि वृत्तिमनुत्तमाम्।
वर्तते गुरुवृत्तिज्ञो यथा मातरि वर्तते॥', 'nanu tv āryo ''pi dharmātmā tvayi vṛttim anuttamām
vartate guruvṛttijño yathā mātari vartate', null, 2067006),
('ramayana-2-67-7', 7, 'Ayodhya Kanda, Sarga 67, Verse 7', 'तथा ज्येष्ठा हि मे माता कौसल्या दीर्घदर्शिनी।
त्वयि धर्मं समास्थाय भगिन्यामिव वर्तते॥', 'tathā jyeṣṭhā hi me mātā kausalyā dīrghadarśinī
tvayi dharmaṃ samāsthāya bhaginyām iva vartate', null, 2067007),
('ramayana-2-67-8', 8, 'Ayodhya Kanda, Sarga 67, Verse 8', 'तस्याः पुत्रं कृतात्मानं चीरवल्कलवाससं।
प्रस्थाप्य वनवासाय कथं पापे न शोचसि॥', 'tasyāḥ putraṃ kṛtātmānaṃ cīravalkalavāsasaṃ
prasthāpya vanavāsāya kathaṃ pāpe na śocasi', null, 2067008),
('ramayana-2-67-9', 9, 'Ayodhya Kanda, Sarga 67, Verse 9', 'अपापदर्शिनं शूरं कृतात्मानं यशस्विनम्।
प्रव्राज्य चीरवसनं किं नु पश्यसि कारणम्॥', 'apāpadarśinaṃ śūraṃ kṛtātmānaṃ yaśasvinam
pravrājya cīravasanaṃ kiṃ nu paśyasi kāraṇam', null, 2067009),
('ramayana-2-67-10', 10, 'Ayodhya Kanda, Sarga 67, Verse 10', 'लुब्धाया विदितो मन्ये न तेऽहं राघवं प्रति।
तथा ह्यनर्थो राज्यार्थं त्वया नीतो महानयम्॥', 'lubdhāyā vidito manye na te ''haṃ rāghavaṃ prati
tathā hy anartho rājyārthaṃ tvayā nīto mahān ayam', null, 2067010),
('ramayana-2-67-11', 11, 'Ayodhya Kanda, Sarga 67, Verse 11', 'अहं हि पुरुषव्याघ्रावपश्यन्रामलक्ष्मणौ।
केन शक्तिप्रभावेन राज्यं रक्षितुमुत्सहे॥', 'ahaṃ hi puruṣavyāghrāv apaśyan rāmalakṣmaṇau
kena śaktiprabhāvena rājyaṃ rakṣitum utsahe', null, 2067011),
('ramayana-2-67-12', 12, 'Ayodhya Kanda, Sarga 67, Verse 12', 'तं हि नित्यं महाराजो बलवन्तं महाबलः।
अपाश्रितोऽभूद्धर्मात्मा मेरुर्मेरुवनं यथा॥', 'taṃ hi nityaṃ mahārājo balavantaṃ mahābalaḥ
apāśrito ''bhūd dharmātmā merur meruvanaṃ yathā', null, 2067012),
('ramayana-2-67-13', 13, 'Ayodhya Kanda, Sarga 67, Verse 13', 'सोऽहं कथमिमं भारं महाधुर्यसमुद्यतम्।
दम्यो धुरमिवासाद्य सहेयं केन चौजसा॥', 'so ''haṃ katham imaṃ bhāraṃ mahādhuryasamudyatam
damyo dhuram ivāsādya saheyaṃ kena caujasā', null, 2067013),
('ramayana-2-67-14', 14, 'Ayodhya Kanda, Sarga 67, Verse 14', 'अथ वा मे भवेच्छक्तिर्योगैर्बुद्धिबलेन वा।
सकामां न करिष्यामि त्वामहं पुत्रगर्धिनीम्।
निवर्तयिष्यामि वनाद्भ्रातरं स्वजनप्रियम्॥', 'atha vā me bhavec chaktir yogair buddhibalena vā
sakāmāṃ na kariṣyāmi tvām ahaṃ putragardhinīm
nivartayiṣyāmi vanād bhrātaraṃ svajanapriyam', null, 2067014),
('ramayana-2-67-15', 15, 'Ayodhya Kanda, Sarga 67, Verse 15', 'इत्येवमुक्त्वा भरतो महात्मा प्रियेतरैर्वाक्यगणैस्तुदंस्ताम्।
शोकातुरश्चापि ननाद भूयः सिंहो यथा पर्वतगह्वरस्थः॥', 'ity evam uktvā bharato mahātmā priyetarair vākyagaṇais tudaṃs tām
śokāturaś cāpi nanāda bhūyaḥ siṃho yathā parvatagahvarasthaḥ', null, 2067015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 68 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-68-1', 1, 'Ayodhya Kanda, Sarga 68, Verse 1', 'तां तथा गर्हयित्वा तु मातरं भरतस्तदा।
रोषेण महताविष्टः पुनरेवाब्रवीद्वचः॥', 'tāṃ tathā garhayitvā tu mātaraṃ bharatas tadā
roṣeṇa mahatāviṣṭaḥ punar evābravīd vacaḥ', null, 2068001),
('ramayana-2-68-2', 2, 'Ayodhya Kanda, Sarga 68, Verse 2', 'राज्याद्भ्रंशस्व कैकेयि नृशंसे दुष्टचारिणि।
परित्यक्ता च धर्मेण मा मृतं रुदती भव॥', 'rājyād bhraṃśasva kaikeyi nṛśaṃse duṣṭacāriṇi
parityaktā ca dharmeṇa mā mṛtaṃ rudatī bhava', null, 2068002),
('ramayana-2-68-3', 3, 'Ayodhya Kanda, Sarga 68, Verse 3', 'किं नु तेऽदूषयद्राजा रामो वा भृशधार्मिकः।
ययोर्मृत्युर्विवासश्च त्वत्कृते तुल्यमागतौ॥', 'kiṃ nu te ''dūṣayad rājā rāmo vā bhṛśadhārmikaḥ
yayor mṛtyur vivāsaś ca tvatkṛte tulyam āgatau', null, 2068003),
('ramayana-2-68-4', 4, 'Ayodhya Kanda, Sarga 68, Verse 4', 'भ्रूणहत्यामसि प्राप्ता कुलस्यास्य विनाशनात्।
कैकेयि नरकं गच्छ मा च भर्तुः सलोकताम्॥', 'bhrūṇahatyām asi prāptā kulasyāsya vināśanāt
kaikeyi narakaṃ gaccha mā ca bhartuḥ salokatām', null, 2068004),
('ramayana-2-68-5', 5, 'Ayodhya Kanda, Sarga 68, Verse 5', 'यत्त्वया हीदृशं पापं कृतं घोरेण कर्मणा।
सर्वलोकप्रियं हित्वा ममाप्यापादितं भयम्॥', 'yat tvayā hīdṛśaṃ pāpaṃ kṛtaṃ ghoreṇa karmaṇā
sarvalokapriyaṃ hitvā mamāpy āpāditaṃ bhayam', null, 2068005),
('ramayana-2-68-6', 6, 'Ayodhya Kanda, Sarga 68, Verse 6', 'त्वत्कृते मे पिता वृत्तो रामश्चारण्यमाश्रितः।
अयशो जीवलोके च त्वयाहं प्रतिपादितः॥', 'tvatkṛte me pitā vṛtto rāmaś cāraṇyam āśritaḥ
ayaśo jīvaloke ca tvayāhaṃ pratipāditaḥ', null, 2068006),
('ramayana-2-68-7', 7, 'Ayodhya Kanda, Sarga 68, Verse 7', 'मातृरूपे ममामित्रे नृशंसे राज्यकामुके।
न तेऽहमभिभाष्योऽस्मि दुर्वृत्ते पतिघातिनि॥', 'mātṛrūpe mamāmitre nṛśaṃse rājyakāmuke
na te ''ham abhibhāṣyo ''smi durvṛtte patighātini', null, 2068007),
('ramayana-2-68-8', 8, 'Ayodhya Kanda, Sarga 68, Verse 8', 'कौसल्या च सुमित्रा च याश्चान्या मम मातरः।
दुःखेन महताविष्टास्त्वां प्राप्य कुलदूषिणीम्॥', 'kausalyā ca sumitrā ca yāś cānyā mama mātaraḥ
duḥkhena mahatāviṣṭās tvāṃ prāpya kuladūṣiṇīm', null, 2068008),
('ramayana-2-68-9', 9, 'Ayodhya Kanda, Sarga 68, Verse 9', 'न त्वमश्वपतेः कन्या धर्मराजस्य धीमतः।
राक्षसी तत्र जातासि कुलप्रध्वंसिनी पितुः॥', 'na tvam aśvapateḥ kanyā dharmarājasya dhīmataḥ
rākṣasī tatra jātāsi kulapradhvaṃsinī pituḥ', null, 2068009),
('ramayana-2-68-10', 10, 'Ayodhya Kanda, Sarga 68, Verse 10', 'यत्त्वया धार्मिको रामो नित्यं सत्यपरायणः।
वनं प्रस्थापितो दुःखात्पिता च त्रिदिवं गतः॥', 'yat tvayā dhārmiko rāmo nityaṃ satyaparāyaṇaḥ
vanaṃ prasthāpito duḥkhāt pitā ca tridivaṃ gataḥ', null, 2068010),
('ramayana-2-68-11', 11, 'Ayodhya Kanda, Sarga 68, Verse 11', 'यत्प्रधानासि तत्पापं मयि पित्रा विनाकृते।
भ्रातृभ्यां च परित्यक्ते सर्वलोकस्य चाप्रिये॥', 'yat pradhānāsi tat pāpaṃ mayi pitrā vinākṛte
bhrātṛbhyāṃ ca parityakte sarvalokasya cāpriye', null, 2068011),
('ramayana-2-68-12', 12, 'Ayodhya Kanda, Sarga 68, Verse 12', 'कौसल्यां धर्मसंयुक्तां वियुक्तां पापनिश्चये।
कृत्वा कं प्राप्स्यसे त्वद्य लोकं निरयगामिनी॥', 'kausalyāṃ dharmasaṃyuktāṃ viyuktāṃ pāpaniścaye
kṛtvā kaṃ prāpsyase tv adya lokaṃ nirayagāminī', null, 2068012),
('ramayana-2-68-13', 13, 'Ayodhya Kanda, Sarga 68, Verse 13', 'किं नावबुध्यसे क्रूरे नियतं बन्धुसंश्रयम्।
ज्येष्ठं पितृसमं रामं कौसल्यायात्मसंभवम्॥', 'kiṃ nāvabudhyase krūre niyataṃ bandhusaṃśrayam
jyeṣṭhaṃ pitṛsamaṃ rāmaṃ kausalyāyātmasaṃbhavam', null, 2068013),
('ramayana-2-68-14', 14, 'Ayodhya Kanda, Sarga 68, Verse 14', 'अङ्गप्रत्यङ्गजः पुत्रो हृदयाच्चापि जायते।
तस्मात्प्रियतरो मातुः प्रियत्वान्न तु बान्धवः॥', 'aṅgapratyaṅgajaḥ putro hṛdayāc cāpi jāyate
tasmāt priyataro mātuḥ priyatvān na tu bāndhavaḥ', null, 2068014),
('ramayana-2-68-15', 15, 'Ayodhya Kanda, Sarga 68, Verse 15', 'अन्यदा किल धर्मज्ञा सुरभिः सुरसंमता।
वहमानौ ददर्शोर्व्यां पुत्रौ विगतचेतसौ॥', 'anyadā kila dharmajñā surabhiḥ surasaṃmatā
vahamānau dadarśorvyāṃ putrau vigatacetasau', null, 2068015),
('ramayana-2-68-16', 16, 'Ayodhya Kanda, Sarga 68, Verse 16', 'तावर्धदिवसे श्रान्तौ दृष्ट्वा पुत्रौ महीतले।
रुरोद पुत्र शोकेन बाष्पपर्याकुलेक्षणा॥', 'tāv ardhadivase śrāntau dṛṣṭvā putrau mahītale
ruroda putra śokena bāṣpaparyākulekṣaṇā', null, 2068016),
('ramayana-2-68-17', 17, 'Ayodhya Kanda, Sarga 68, Verse 17', 'अधस्ताद्व्रजतस्तस्याः सुरराज्ञो महात्मनः।
बिन्दवः पतिता गात्रे सूक्ष्माः सुरभिगन्धिनः॥', 'adhastād vrajatas tasyāḥ surarājño mahātmanaḥ
bindavaḥ patitā gātre sūkṣmāḥ surabhigandhinaḥ', null, 2068017),
('ramayana-2-68-18', 18, 'Ayodhya Kanda, Sarga 68, Verse 18', 'तां दृष्ट्वा शोकसंतप्तां वज्रपाणिर्यशस्विनीम्।
इन्द्रः प्राञ्जलिरुद्विग्नः सुरराजोऽब्रवीद्वचः॥', 'tāṃ dṛṣṭvā śokasaṃtaptāṃ vajrapāṇir yaśasvinīm
indraḥ prāñjalir udvignaḥ surarājo ''bravīd vacaḥ', null, 2068018),
('ramayana-2-68-19', 19, 'Ayodhya Kanda, Sarga 68, Verse 19', 'भयं कच्चिन्न चास्मासु कुतश्चिद्विद्यते महत्।
कुतो निमित्तः शोकस्ते ब्रूहि सर्वहितैषिणि॥', 'bhayaṃ kaccin na cāsmāsu kutaś cid vidyate mahat
kuto nimittaḥ śokas te brūhi sarvahitaiṣiṇi', null, 2068019),
('ramayana-2-68-20', 20, 'Ayodhya Kanda, Sarga 68, Verse 20', 'एवमुक्ता तु सुरभिः सुरराजेन धीमता।
पत्युवाच ततो धीरा वाक्यं वाक्यविशारदा॥', 'evam uktā tu surabhiḥ surarājena dhīmatā
patyuvāca tato dhīrā vākyaṃ vākyaviśāradā', null, 2068020),
('ramayana-2-68-21', 21, 'Ayodhya Kanda, Sarga 68, Verse 21', 'शान्तं पातं न वः किं चित्कुतश्चिदमराधिप।
अहं तु मग्नौ शोचामि स्वपुत्रौ विषमे स्थितौ॥', 'śāntaṃ pātaṃ na vaḥ kiṃ cit kutaś cid amarādhipa
ahaṃ tu magnau śocāmi svaputrau viṣame sthitau', null, 2068021),
('ramayana-2-68-22', 22, 'Ayodhya Kanda, Sarga 68, Verse 22', 'एतौ दृष्ट्वा कृषौ दीनौ सूर्यरश्मिप्रतापिनौ।
वध्यमानौ बलीवर्दौ कर्षकेण सुराधिप॥', 'etau dṛṣṭvā kṛṣau dīnau sūryaraśmipratāpinau
vadhyamānau balīvardau karṣakeṇa surādhipa', null, 2068022),
('ramayana-2-68-23', 23, 'Ayodhya Kanda, Sarga 68, Verse 23', 'मम कायात्प्रसूतौ हि दुःखितौ भार पीडितौ।
यौ दृष्ट्वा परितप्येऽहं नास्ति पुत्रसमः प्रियः॥', 'mama kāyāt prasūtau hi duḥkhitau bhāra pīḍitau
yau dṛṣṭvā paritapye ''haṃ nāsti putrasamaḥ priyaḥ', null, 2068023),
('ramayana-2-68-24', 24, 'Ayodhya Kanda, Sarga 68, Verse 24', 'यस्याः पुत्र सहस्राणि सापि शोचति कामधुक्।
किं पुनर्या विना रामं कौसल्या वर्तयिष्यति॥', 'yasyāḥ putra sahasrāṇi sāpi śocati kāmadhuk
kiṃ punar yā vinā rāmaṃ kausalyā vartayiṣyati', null, 2068024),
('ramayana-2-68-25', 25, 'Ayodhya Kanda, Sarga 68, Verse 25', 'एकपुत्रा च साध्वी च विवत्सेयं त्वया कृता।
तस्मात्त्वं सततं दुःखं प्रेत्य चेह च लप्स्यसे॥', 'ekaputrā ca sādhvī ca vivatseyaṃ tvayā kṛtā
tasmāt tvaṃ satataṃ duḥkhaṃ pretya ceha ca lapsyase', null, 2068025),
('ramayana-2-68-26', 26, 'Ayodhya Kanda, Sarga 68, Verse 26', 'अहं ह्यपचितिं भ्रातुः पितुश्च सकलामिमाम्।
वर्धनं यशसश्चापि करिष्यामि न संशयः॥', 'ahaṃ hy apacitiṃ bhrātuḥ pituś ca sakalām imām
vardhanaṃ yaśasaś cāpi kariṣyāmi na saṃśayaḥ', null, 2068026),
('ramayana-2-68-27', 27, 'Ayodhya Kanda, Sarga 68, Verse 27', 'आनाययित्वा तनयं कौसल्याया महाद्युतिम्।
स्वयमेव प्रवेक्ष्यामि वनं मुनिनिषेवितम्॥', 'ānāyayitvā tanayaṃ kausalyāyā mahādyutim
svayam eva pravekṣyāmi vanaṃ muniniṣevitam', null, 2068027),
('ramayana-2-68-28', 28, 'Ayodhya Kanda, Sarga 68, Verse 28', 'इति नाग इवारण्ये तोमराङ्कुशचोदितः।
पपात भुवि संक्रुद्धो निःश्वसन्निव पन्नगः॥', 'iti nāga ivāraṇye tomarāṅkuśacoditaḥ
papāta bhuvi saṃkruddho niḥśvasann iva pannagaḥ', null, 2068028),
('ramayana-2-68-29', 29, 'Ayodhya Kanda, Sarga 68, Verse 29', 'संरक्तनेत्रः शिथिलाम्बरस्तदा विधूतसर्वाभरणः परंतपः।
बभूव भूमौ पतितो नृपात्मजः शचीपतेः केतुरिवोत्सवक्षये॥', 'saṃraktanetraḥ śithilāmbaras tadā vidhūtasarvābharaṇaḥ paraṃtapaḥ
babhūva bhūmau patito nṛpātmajaḥ śacīpateḥ ketur ivotsavakṣaye', null, 2068029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 69 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-69-1', 1, 'Ayodhya Kanda, Sarga 69, Verse 1', 'तथैव क्रोशतस्तस्य भरतस्य महात्मनः।
कौसल्या शब्दमाज्ञाय सुमित्रामिदमब्रवीत्॥', 'tathaiva krośatas tasya bharatasya mahātmanaḥ
kausalyā śabdam ājñāya sumitrām idam abravīt', null, 2069001),
('ramayana-2-69-2', 2, 'Ayodhya Kanda, Sarga 69, Verse 2', 'आगतः क्रूरकार्यायाः कैकेय्या भरतः सुतः।
तमहं द्रष्टुमिच्छामि भरतं दीर्घदर्शिनम्॥', 'āgataḥ krūrakāryāyāḥ kaikeyyā bharataḥ sutaḥ
tam ahaṃ draṣṭum icchāmi bharataṃ dīrghadarśinam', null, 2069002),
('ramayana-2-69-3', 3, 'Ayodhya Kanda, Sarga 69, Verse 3', 'एवमुक्त्वा सुमित्रां सा विवर्णा मलिनाम्बरा।
प्रतस्थे भरतो यत्र वेपमाना विचेतना॥', 'evam uktvā sumitrāṃ sā vivarṇā malināmbarā
pratasthe bharato yatra vepamānā vicetanā', null, 2069003),
('ramayana-2-69-4', 4, 'Ayodhya Kanda, Sarga 69, Verse 4', 'स तु रामानुजश्चापि शत्रुघ्नसहितस्तदा।
प्रतस्थे भरतो यत्र कौसल्याया निवेशनम्॥', 'sa tu rāmānujaś cāpi śatrughnasahitas tadā
pratasthe bharato yatra kausalyāyā niveśanam', null, 2069004),
('ramayana-2-69-5', 5, 'Ayodhya Kanda, Sarga 69, Verse 5', 'ततः शत्रुघ्नभरतौ कौसल्यां प्रेक्ष्य दुःखितौ।
पर्यष्वजेतां दुःखार्तां पतितां नष्टचेतनाम्॥', 'tataḥ śatrughnabharatau kausalyāṃ prekṣya duḥkhitau
paryaṣvajetāṃ duḥkhārtāṃ patitāṃ naṣṭacetanām', null, 2069005),
('ramayana-2-69-6', 6, 'Ayodhya Kanda, Sarga 69, Verse 6', 'भरतं प्रत्युवाचेदं कौसल्या भृशदुःखिता।
इदं ते राज्यकामस्य राज्यं प्राप्तमकण्टकम्।
संप्राप्तं बत कैकेय्या शीघ्रं क्रूरेण कर्मणा॥', 'bharataṃ pratyuvācedaṃ kausalyā bhṛśaduḥkhitā
idaṃ te rājyakāmasya rājyaṃ prāptam akaṇṭakam
saṃprāptaṃ bata kaikeyyā śīghraṃ krūreṇa karmaṇā', null, 2069006),
('ramayana-2-69-7', 7, 'Ayodhya Kanda, Sarga 69, Verse 7', 'प्रस्थाप्य चीरवसनं पुत्रं मे वनवासिनम्।
कैकेयी कं गुणं तत्र पश्यति क्रूरदर्शिनी॥', 'prasthāpya cīravasanaṃ putraṃ me vanavāsinam
kaikeyī kaṃ guṇaṃ tatra paśyati krūradarśinī', null, 2069007),
('ramayana-2-69-8', 8, 'Ayodhya Kanda, Sarga 69, Verse 8', 'क्षिप्रं मामपि कैकेयी प्रस्थापयितुमर्हति।
हिरण्यनाभो यत्रास्ते सुतो मे सुमहायशाः॥', 'kṣipraṃ mām api kaikeyī prasthāpayitum arhati
hiraṇyanābho yatrāste suto me sumahāyaśāḥ', null, 2069008),
('ramayana-2-69-9', 9, 'Ayodhya Kanda, Sarga 69, Verse 9', 'अथ वा स्वयमेवाहं सुमित्रानुचरा सुखम्।
अग्निहोत्रं पुरस्कृत्य प्रस्थास्ये यत्र राघवः॥', 'atha vā svayam evāhaṃ sumitrānucarā sukham
agnihotraṃ puraskṛtya prasthāsye yatra rāghavaḥ', null, 2069009),
('ramayana-2-69-10', 10, 'Ayodhya Kanda, Sarga 69, Verse 10', 'कामं वा स्वयमेवाद्य तत्र मां नेतुमर्हसि।
यत्रासौ पुरुषव्याघ्रस्तप्यते मे तपः सुतः॥', 'kāmaṃ vā svayam evādya tatra māṃ netum arhasi
yatrāsau puruṣavyāghras tapyate me tapaḥ sutaḥ', null, 2069010),
('ramayana-2-69-11', 11, 'Ayodhya Kanda, Sarga 69, Verse 11', 'इदं हि तव विस्तीर्णं धनधान्यसमाचितम्।
हस्त्यश्वरथसंपूर्णं राज्यं निर्यातितं तया॥', 'idaṃ hi tava vistīrṇaṃ dhanadhānyasamācitam
hastyaśvarathasaṃpūrṇaṃ rājyaṃ niryātitaṃ tayā', null, 2069011),
('ramayana-2-69-12', 12, 'Ayodhya Kanda, Sarga 69, Verse 12', 'एवं विलपमानां तां भरतः प्राञ्जलिस्तदा।
कौसल्यां प्रत्युवाचेदं शोकैर्बहुभिरावृताम्॥', 'evaṃ vilapamānāṃ tāṃ bharataḥ prāñjalis tadā
kausalyāṃ pratyuvācedaṃ śokair bahubhir āvṛtām', null, 2069012),
('ramayana-2-69-13', 13, 'Ayodhya Kanda, Sarga 69, Verse 13', 'आर्ये कस्मादजानन्तं गर्हसे मामकिल्बिषम्।
विपुलां च मम प्रीतिं स्थिरां जानासि राघवे॥', 'ārye kasmād ajānantaṃ garhase mām akilbiṣam
vipulāṃ ca mama prītiṃ sthirāṃ jānāsi rāghave', null, 2069013),
('ramayana-2-69-14', 14, 'Ayodhya Kanda, Sarga 69, Verse 14', 'कृता शास्त्रानुगा बुद्धिर्मा भूत्तस्य कदा चन।
सत्यसंधः सतां श्रेष्ठो यस्यार्योऽनुमते गतः॥', 'kṛtā śāstrānugā buddhir mā bhūt tasya kadā cana
satyasaṃdhaḥ satāṃ śreṣṭho yasyāryo ''numate gataḥ', null, 2069014),
('ramayana-2-69-15', 15, 'Ayodhya Kanda, Sarga 69, Verse 15', 'प्रैष्यं पापीयसां यातु सूर्यं च प्रति मेहतु।
हन्तु पादेन गां सुप्तां यस्यार्योऽनुमते गतः॥', 'praiṣyaṃ pāpīyasāṃ yātu sūryaṃ ca prati mehatu
hantu pādena gāṃ suptāṃ yasyāryo ''numate gataḥ', null, 2069015),
('ramayana-2-69-16', 16, 'Ayodhya Kanda, Sarga 69, Verse 16', 'कारयित्वा महत्कर्म भर्ता भृत्यमनर्थकम्।
अधर्मो योऽस्य सोऽस्यास्तु यस्यार्योऽनुमते गतः॥', 'kārayitvā mahat karma bhartā bhṛtyam anarthakam
adharmo yo ''sya so ''syās tu yasyāryo ''numate gataḥ', null, 2069016),
('ramayana-2-69-17', 17, 'Ayodhya Kanda, Sarga 69, Verse 17', 'परिपालयमानस्य राज्ञो भूतानि पुत्रवत्।
ततस्तु द्रुह्यतां पापं यस्यार्योऽनुमते गतः॥', 'paripālayamānasya rājño bhūtāni putravat
tatas tu druhyatāṃ pāpaṃ yasyāryo ''numate gataḥ', null, 2069017),
('ramayana-2-69-18', 18, 'Ayodhya Kanda, Sarga 69, Verse 18', 'बलिषड्भागमुद्धृत्य नृपस्यारक्षतः प्रजाः।
अधर्मो योऽस्य सोऽस्यास्तु यस्यार्योऽनुमते गतः॥', 'baliṣaḍbhāgam uddhṛtya nṛpasyārakṣataḥ prajāḥ
adharmo yo ''sya so ''syāstu yasyāryo ''numate gataḥ', null, 2069018),
('ramayana-2-69-19', 19, 'Ayodhya Kanda, Sarga 69, Verse 19', 'संश्रुत्य च तपस्विभ्यः सत्रे वै यज्ञदक्षिणाम्।
तां विप्रलपतां पापं यस्यार्योऽनुमते गतः॥', 'saṃśrutya ca tapasvibhyaḥ satre vai yajñadakṣiṇām
tāṃ vipralapatāṃ pāpaṃ yasyāryo ''numate gataḥ', null, 2069019),
('ramayana-2-69-20', 20, 'Ayodhya Kanda, Sarga 69, Verse 20', 'हस्त्यश्वरथसंबाधे युद्धे शस्त्रसमाकुले।
मा स्म कार्षीत्सतां धर्मं यस्यार्योऽनुमते गतः॥', 'hastyaśvarathasaṃbādhe yuddhe śastrasamākule
mā sma kārṣīt satāṃ dharmaṃ yasyāryo ''numate gataḥ', null, 2069020),
('ramayana-2-69-21', 21, 'Ayodhya Kanda, Sarga 69, Verse 21', 'उपदिष्टं सुसूक्ष्मार्थं शास्त्रं यत्नेन धीमता।
स नाशयतु दुष्टात्मा यस्यार्योऽनुमते गतः॥', 'upadiṣṭaṃ susūkṣmārthaṃ śāstraṃ yatnena dhīmatā
sa nāśayatu duṣṭātmā yasyāryo ''numate gataḥ', null, 2069021),
('ramayana-2-69-22', 22, 'Ayodhya Kanda, Sarga 69, Verse 22', 'पायसं कृसरं छागं वृथा सोऽश्नातु निर्घृणः।
गुरूंश्चाप्यवजानातु यस्यार्योऽनुमते गतः॥', 'pāyasaṃ kṛsaraṃ chāgaṃ vṛthā so ''śnātu nirghṛṇaḥ
gurūṃś cāpy avajānātu yasyāryo ''numate gataḥ', null, 2069022),
('ramayana-2-69-23', 23, 'Ayodhya Kanda, Sarga 69, Verse 23', 'पुत्रैर्दारैश्च भृत्यैश्च स्वगृहे परिवारितः।
स एको मृष्टमश्नातु यस्यार्योऽनुमते गतः॥', 'putrair dāraiś ca bhṛtyaiś ca svagṛhe parivāritaḥ
sa eko mṛṣṭam aśnātu yasyāryo ''numate gataḥ', null, 2069023),
('ramayana-2-69-24', 24, 'Ayodhya Kanda, Sarga 69, Verse 24', 'राजस्त्रीबालवृद्धानां वधे यत्पापमुच्यते।
भृत्यत्यागे च यत्पापं तत्पापं प्रतिपद्यताम्॥', 'rājastrībālavṛddhānāṃ vadhe yat pāpam ucyate
bhṛtyatyāge ca yat pāpaṃ tat pāpaṃ pratipadyatām', null, 2069024),
('ramayana-2-69-25', 25, 'Ayodhya Kanda, Sarga 69, Verse 25', 'उभे संध्ये शयानस्य यत्पापं परिकल्प्यते।
तच्च पापं भवेत्तस्य यस्यार्योऽनुमते गतः॥', 'ubhe saṃdhye śayānasya yat pāpaṃ parikalpyate
tac ca pāpaṃ bhavet tasya yasyāryo ''numate gataḥ', null, 2069025),
('ramayana-2-69-26', 26, 'Ayodhya Kanda, Sarga 69, Verse 26', 'यदग्निदायके पापं यत्पापं गुरुतल्पगे।
मित्रद्रोहे च यत्पापं तत्पापं प्रतिपद्यताम्॥', 'yad agnidāyake pāpaṃ yat pāpaṃ gurutalpage
mitradrohe ca yat pāpaṃ tat pāpaṃ pratipadyatām', null, 2069026),
('ramayana-2-69-27', 27, 'Ayodhya Kanda, Sarga 69, Verse 27', 'देवतानां पितॄणां च माता पित्रोस्तथैव च।
मा स्म कार्षीत्स शुश्रूषां यस्यार्योऽनुमते गतः॥', 'devatānāṃ pitṝṇāṃ ca mātā pitros tathaiva ca
mā sma kārṣīt sa śuśrūṣāṃ yasyāryo ''numate gataḥ', null, 2069027),
('ramayana-2-69-28', 28, 'Ayodhya Kanda, Sarga 69, Verse 28', 'सतां लोकात्सतां कीर्त्याः सज्जुष्टात्कर्मणस्तथा।
भ्रश्यतु क्षिप्रमद्यैव यस्यार्योऽनुमते गतः॥', 'satāṃ lokāt satāṃ kīrtyāḥ sajjuṣṭāt karmaṇas tathā
bhraśyatu kṣipram adyaiva yasyāryo ''numate gataḥ', null, 2069028),
('ramayana-2-69-29', 29, 'Ayodhya Kanda, Sarga 69, Verse 29', 'विहीनां पतिपुत्राभ्यां कौसल्यां पार्थिवात्मजः।
एवमाश्वसयन्नेव दुःखार्तो निपपात ह॥', 'vihīnāṃ patiputrābhyāṃ kausalyāṃ pārthivātmajaḥ
evam āśvasayann eva duḥkhārto nipapāta ha', null, 2069029),
('ramayana-2-69-30', 30, 'Ayodhya Kanda, Sarga 69, Verse 30', 'तथा तु शपथैः कष्टैः शपमानमचेतनम्।
भरतं शोकसंतप्तं कौसल्या वाक्यमब्रवीत्॥', 'tathā tu śapathaiḥ kaṣṭaiḥ śapamānam acetanam
bharataṃ śokasaṃtaptaṃ kausalyā vākyam abravīt', null, 2069030),
('ramayana-2-69-31', 31, 'Ayodhya Kanda, Sarga 69, Verse 31', 'मम दुःखमिदं पुत्र भूयः समुपजायते।
शपथैः शपमानो हि प्राणानुपरुणत्सि मे॥', 'mama duḥkham idaṃ putra bhūyaḥ samupajāyate
śapathaiḥ śapamāno hi prāṇān uparuṇatsi me', null, 2069031),
('ramayana-2-69-32', 32, 'Ayodhya Kanda, Sarga 69, Verse 32', 'दिष्ट्या न चलितो धर्मादात्मा ते सहलक्ष्मणः।
वत्स सत्यप्रतिज्ञो मे सतां लोकानवाप्स्यसि॥', 'diṣṭyā na calito dharmād ātmā te sahalakṣmaṇaḥ
vatsa satyapratijño me satāṃ lokān avāpsyasi', null, 2069032),
('ramayana-2-69-33', 33, 'Ayodhya Kanda, Sarga 69, Verse 33', 'एवं विलपमानस्य दुःखार्तस्य महात्मनः।
मोहाच्च शोकसंरोधाद्बभूव लुलितं मनः॥', 'evaṃ vilapamānasya duḥkhārtasya mahātmanaḥ
mohāc ca śokasaṃrodhād babhūva lulitaṃ manaḥ', null, 2069033),
('ramayana-2-69-34', 34, 'Ayodhya Kanda, Sarga 69, Verse 34', 'लालप्यमानस्य विचेतनस्य प्रनष्टबुद्धेः पतितस्य भूमौ।
मुहुर्मुहुर्निःश्वसतश्च दीर्घं सा तस्य शोकेन जगाम रात्रिः॥', 'lālapyamānasya vicetanasya pranaṣṭabuddheḥ patitasya bhūmau
muhur muhur niḥśvasataś ca dīrghaṃ sā tasya śokena jagāma rātriḥ', null, 2069034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 70 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-70-1', 1, 'Ayodhya Kanda, Sarga 70, Verse 1', 'तमेवं शोकसंतप्तं भरतं केकयीसुतम्।
उवाच वदतां श्रेष्ठो वसिष्ठः श्रेष्ठवागृषिः॥', 'tam evaṃ śokasaṃtaptaṃ bharataṃ kekayīsutam
uvāca vadatāṃ śreṣṭho vasiṣṭhaḥ śreṣṭhavāg ṛṣiḥ', null, 2070001),
('ramayana-2-70-2', 2, 'Ayodhya Kanda, Sarga 70, Verse 2', 'अलं शोकेन भद्रं ते राजपुत्र महायशः।
प्राप्तकालं नरपतेः कुरु संयानमुत्तरम्॥', 'alaṃ śokena bhadraṃ te rājaputra mahāyaśaḥ
prāptakālaṃ narapateḥ kuru saṃyānam uttaram', null, 2070002),
('ramayana-2-70-3', 3, 'Ayodhya Kanda, Sarga 70, Verse 3', 'वसिष्ठस्य वचः श्रुत्वा भरतो धारणां गतः।
प्रेतकार्याणि सर्वाणि कारयामास धर्मवित्॥', 'vasiṣṭhasya vacaḥ śrutvā bharato dhāraṇāṃ gataḥ
pretakāryāṇi sarvāṇi kārayām āsa dharmavit', null, 2070003),
('ramayana-2-70-4', 4, 'Ayodhya Kanda, Sarga 70, Verse 4', 'उद्धृतं तैलसंक्लेदात्स तु भूमौ निवेशितम्।
आपीतवर्णवदनं प्रसुप्तमिव भूमिपम्॥', 'uddhṛtaṃ tailasaṃkledāt sa tu bhūmau niveśitam
āpītavarṇavadanaṃ prasuptam iva bhūmipam', null, 2070004),
('ramayana-2-70-5', 5, 'Ayodhya Kanda, Sarga 70, Verse 5', 'निवेश्य शयने चाग्र्ये नानारत्नपरिष्कृते।
ततो दशरथं पुत्रो विललाप सुदुःखितः॥', 'niveśya śayane cāgrye nānāratnapariṣkṛte
tato daśarathaṃ putro vilalāpa suduḥkhitaḥ', null, 2070005),
('ramayana-2-70-6', 6, 'Ayodhya Kanda, Sarga 70, Verse 6', 'किं ते व्यवसितं राजन्प्रोषिते मय्यनागते।
विवास्य रामं धर्मज्ञं लक्ष्मणं च महाबलम्॥', 'kiṃ te vyavasitaṃ rājan proṣite mayy anāgate
vivāsya rāmaṃ dharmajñaṃ lakṣmaṇaṃ ca mahābalam', null, 2070006),
('ramayana-2-70-7', 7, 'Ayodhya Kanda, Sarga 70, Verse 7', 'क्व यास्यसि महाराज हित्वेमं दुःखितं जनम्।
हीनं पुरुषसिंहेन रामेणाक्लिष्टकर्मणा॥', 'kva yāsyasi mahārāja hitvemaṃ duḥkhitaṃ janam
hīnaṃ puruṣasiṃhena rāmeṇākliṣṭakarmaṇā', null, 2070007),
('ramayana-2-70-8', 8, 'Ayodhya Kanda, Sarga 70, Verse 8', 'योगक्षेमं तु ते राजन्कोऽस्मिन्कल्पयिता पुरे।
त्वयि प्रयाते स्वस्तात रामे च वनमाश्रिते॥', 'yogakṣemaṃ tu te rājan ko ''smin kalpayitā pure
tvayi prayāte svas tāta rāme ca vanam āśrite', null, 2070008),
('ramayana-2-70-9', 9, 'Ayodhya Kanda, Sarga 70, Verse 9', 'विधवा पृथिवी राजंस्त्वया हीना न राजते।
हीनचन्द्रेव रजनी नगरी प्रतिभाति माम्॥', 'vidhavā pṛthivī rājaṃs tvayā hīnā na rājate
hīnacandreva rajanī nagarī pratibhāti mām', null, 2070009),
('ramayana-2-70-10', 10, 'Ayodhya Kanda, Sarga 70, Verse 10', 'एवं विलपमानं तं भरतं दीनमानसं।
अब्रवीद्वचनं भूयो वसिष्ठस्तु महानृषिः॥', 'evaṃ vilapamānaṃ taṃ bharataṃ dīnamānasaṃ
abravīd vacanaṃ bhūyo vasiṣṭhas tu mahān ṛṣiḥ', null, 2070010),
('ramayana-2-70-11', 11, 'Ayodhya Kanda, Sarga 70, Verse 11', 'प्रेतकार्याणि यान्यस्य कर्तव्यानि विशाम्पतेः।
तान्यव्यग्रं महाबाहो क्रियतामविचारितम्॥', 'pretakāryāṇi yāny asya kartavyāni viśāmpateḥ
tāny avyagraṃ mahābāho kriyatām avicāritam', null, 2070011),
('ramayana-2-70-12', 12, 'Ayodhya Kanda, Sarga 70, Verse 12', 'तथेति भरतो वाक्यं वसिष्ठस्याभिपूज्य तत्।
ऋत्विक्पुरोहिताचार्यांस्त्वरयामास सर्वशः॥', 'tatheti bharato vākyaṃ vasiṣṭhasyābhipūjya tat
ṛtvikpurohitācāryāṃs tvarayām āsa sarvaśaḥ', null, 2070012),
('ramayana-2-70-13', 13, 'Ayodhya Kanda, Sarga 70, Verse 13', 'ये त्वग्रतो नरेन्द्रस्य अग्न्यगाराद्बहिष्कृताः।
ऋत्विग्भिर्याजकैश्चैव ते ह्रियन्ते यथाविधि॥', 'ye tv agrato narendrasya agny agārād bahiṣkṛtāḥ
ṛtvigbhir yājakaiś caiva te hriyante yathāvidhi', null, 2070013),
('ramayana-2-70-14', 14, 'Ayodhya Kanda, Sarga 70, Verse 14', 'शिबिलायामथारोप्य राजानं गतचेतनम्।
बाष्पकण्ठा विमनसस्तमूहुः परिचारकाः॥', 'śibilāyām athāropya rājānaṃ gatacetanam
bāṣpakaṇṭhā vimanasas tam ūhuḥ paricārakāḥ', null, 2070014),
('ramayana-2-70-15', 15, 'Ayodhya Kanda, Sarga 70, Verse 15', 'हिरण्यं च सुवर्णं च वासांसि विविधानि च।
प्रकिरन्तो जना मार्गं नृपतेरग्रतो ययुः॥', 'hiraṇyaṃ ca suvarṇaṃ ca vāsāṃsi vividhāni ca
prakiranto janā mārgaṃ nṛpater agrato yayuḥ', null, 2070015),
('ramayana-2-70-16', 16, 'Ayodhya Kanda, Sarga 70, Verse 16', 'चन्दनागुरुनिर्यासान्सरलं पद्मकं तथा।
देवदारूणि चाहृत्य चितां चक्रुस्तथापरे॥', 'candanāguruniryāsān saralaṃ padmakaṃ tathā
devadārūṇi cāhṛtya citāṃ cakrus tathāpare', null, 2070016),
('ramayana-2-70-17', 17, 'Ayodhya Kanda, Sarga 70, Verse 17', 'गन्धानुच्चावचांश्चान्यांस्तत्र दत्त्वाथ भूमिपम्।
ततः संवेशयामासुश्चितामध्ये तमृत्विजः॥', 'gandhān uccāvacāṃś cānyāṃs tatra dattvātha bhūmipam
tataḥ saṃveśayām āsuś citāmadhye tam ṛtvijaḥ', null, 2070017),
('ramayana-2-70-18', 18, 'Ayodhya Kanda, Sarga 70, Verse 18', 'तथा हुताशनं हुत्वा जेपुस्तस्य तदर्त्विजः।
जगुश्च ते यथाशास्त्रं तत्र सामानि सामगाः॥', 'tathā hutāśanaṃ hutvā jepus tasya tadartvijaḥ
jaguś ca te yathāśāstraṃ tatra sāmāni sāmagāḥ', null, 2070018),
('ramayana-2-70-19', 19, 'Ayodhya Kanda, Sarga 70, Verse 19', 'शिबिकाभिश्च यानैश्च यथार्हं तस्य योषितः।
नगरान्निर्ययुस्तत्र वृद्धैः परिवृतास्तदा॥', 'śibikābhiś ca yānaiś ca yathārhaṃ tasya yoṣitaḥ
nagarān niryayus tatra vṛddhaiḥ parivṛtās tadā', null, 2070019),
('ramayana-2-70-20', 20, 'Ayodhya Kanda, Sarga 70, Verse 20', 'प्रसव्यं चापि तं चक्रुरृत्विजोऽग्निचितं नृपम्।
स्त्रियश्च शोकसंतप्ताः कौसल्या प्रमुखास्तदा॥', 'prasavyaṃ cāpi taṃ cakrur ṛtvijo ''gnicitaṃ nṛpam
striyaś ca śokasaṃtaptāḥ kausalyā pramukhās tadā', null, 2070020),
('ramayana-2-70-21', 21, 'Ayodhya Kanda, Sarga 70, Verse 21', 'क्रौञ्चीनामिव नारीणां निनादस्तत्र शुश्रुवे।
आर्तानां करुणं काले क्रोशन्तीनां सहस्रशः॥', 'krauñcīnām iva nārīṇāṃ ninādas tatra śuśruve
ārtānāṃ karuṇaṃ kāle krośantīnāṃ sahasraśaḥ', null, 2070021),
('ramayana-2-70-22', 22, 'Ayodhya Kanda, Sarga 70, Verse 22', 'ततो रुदन्त्यो विवशा विलप्य च पुनः पुनः।
यानेभ्यः सरयूतीरमवतेरुर्वराङ्गनाः॥', 'tato rudantyo vivaśā vilapya ca punaḥ punaḥ
yānebhyaḥ sarayūtīram avaterur varāṅganāḥ', null, 2070022),
('ramayana-2-70-23', 23, 'Ayodhya Kanda, Sarga 70, Verse 23', 'कृतोदकं ते भरतेन सार्धं नृपाङ्गना मन्त्रिपुरोहिताश्च।
पुरं प्रविश्याश्रुपरीतनेत्रा भूमौ दशाहं व्यनयन्त दुःखम्॥', 'kṛtodakaṃ te bharatena sārdhaṃ nṛpāṅganā mantripurohitāś ca
puraṃ praviśyāśruparītanetrā bhūmau daśāhaṃ vyanayanta duḥkham', null, 2070023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 71 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-71-1', 1, 'Ayodhya Kanda, Sarga 71, Verse 1', 'ततो दशाहेऽतिगते कृतशौचो नृपात्मजः।
द्वादशेऽहनि संप्राप्ते श्राद्धकर्माण्यकारयत्॥', 'tato daśāhe ''tigate kṛtaśauco nṛpātmajaḥ
dvādaśe ''hani saṃprāpte śrāddhakarmāṇy akārayat', null, 2071001),
('ramayana-2-71-2', 2, 'Ayodhya Kanda, Sarga 71, Verse 2', 'ब्राह्मणेभ्यो ददौ रत्नं धनमन्नं च पुष्कलम्।
बास्तिकं बहुशुक्लं च गाश्चापि शतशस्तथा॥', 'brāhmaṇebhyo dadau ratnaṃ dhanam annaṃ ca puṣkalam
bāstikaṃ bahuśuklaṃ ca gāś cāpi śataśas tathā', null, 2071002),
('ramayana-2-71-3', 3, 'Ayodhya Kanda, Sarga 71, Verse 3', 'दासीदासं च यानं च वेश्मानि सुमहान्ति च।
ब्राह्मणेभ्यो ददौ पुत्रो राज्ञस्तस्यौर्ध्वदैहिकम्॥', 'dāsīdāsaṃ ca yānaṃ ca veśmāni sumahānti ca
brāhmaṇebhyo dadau putro rājñas tasyaurdhvadaihikam', null, 2071003),
('ramayana-2-71-4', 4, 'Ayodhya Kanda, Sarga 71, Verse 4', 'ततः प्रभातसमये दिवसेऽथ त्रयोदशे।
विललाप महाबाहुर्भरतः शोकमूर्छितः॥', 'tataḥ prabhātasamaye divase ''tha trayodaśe
vilalāpa mahābāhur bharataḥ śokamūrchitaḥ', null, 2071004),
('ramayana-2-71-5', 5, 'Ayodhya Kanda, Sarga 71, Verse 5', 'शब्दापिहितकण्ठश्च शोधनार्थमुपागतः।
चितामूले पितुर्वाक्यमिदमाह सुदुःखितः॥', 'śabdāpihitakaṇṭhaś ca śodhanārtham upāgataḥ
citāmūle pitur vākyam idam āha suduḥkhitaḥ', null, 2071005),
('ramayana-2-71-6', 6, 'Ayodhya Kanda, Sarga 71, Verse 6', 'तात यस्मिन्निषृष्टोऽहं त्वया भ्रातरि राघवे।
तस्मिन्वनं प्रव्रजिते शून्ये त्यक्तोऽस्म्यहं त्वया॥', 'tāta yasmin niṣṛṣṭo ''haṃ tvayā bhrātari rāghave
tasmin vanaṃ pravrajite śūnye tyakto ''smy ahaṃ tvayā', null, 2071006),
('ramayana-2-71-7', 7, 'Ayodhya Kanda, Sarga 71, Verse 7', 'यथागतिरनाथायाः पुत्रः प्रव्राजितो वनम्।
तामम्बां तात कौसल्यां त्यक्त्वा त्वं क्व गतो नृप॥', 'yathāgatir anāthāyāḥ putraḥ pravrājito vanam
tām ambāṃ tāta kausalyāṃ tyaktvā tvaṃ kva gato nṛpa', null, 2071007),
('ramayana-2-71-8', 8, 'Ayodhya Kanda, Sarga 71, Verse 8', 'दृष्ट्वा भस्मारुणं तच्च दग्धास्थिस्थानमण्डलम्।
पितुः शरीर निर्वाणं निष्टनन्विषसाद ह॥', 'dṛṣṭvā bhasmāruṇaṃ tac ca dagdhāsthisthānamaṇḍalam
pituḥ śarīra nirvāṇaṃ niṣṭanan viṣasāda ha', null, 2071008),
('ramayana-2-71-9', 9, 'Ayodhya Kanda, Sarga 71, Verse 9', 'स तु दृष्ट्वा रुदन्दीनः पपात धरणीतले।
उत्थाप्यमानः शक्रस्य यन्त्र ध्वज इव च्युतः॥', 'sa tu dṛṣṭvā rudan dīnaḥ papāta dharaṇītale
utthāpyamānaḥ śakrasya yantra dhvaja iva cyutaḥ', null, 2071009),
('ramayana-2-71-10', 10, 'Ayodhya Kanda, Sarga 71, Verse 10', 'अभिपेतुस्ततः सर्वे तस्यामात्याः शुचिव्रतम्।
अन्तकाले निपतितं ययातिमृषयो यथा॥', 'abhipetus tataḥ sarve tasyāmātyāḥ śucivratam
antakāle nipatitaṃ yayātim ṛṣayo yathā', null, 2071010),
('ramayana-2-71-11', 11, 'Ayodhya Kanda, Sarga 71, Verse 11', 'शत्रुघ्नश्चापि भरतं दृष्ट्वा शोकपरिप्लुतम्।
विसंज्ञो न्यपतद्भूमौ भूमिपालमनुस्मरन्॥', 'śatrughnaś cāpi bharataṃ dṛṣṭvā śokapariplutam
visaṃjño nyapatad bhūmau bhūmipālam anusmaran', null, 2071011),
('ramayana-2-71-12', 12, 'Ayodhya Kanda, Sarga 71, Verse 12', 'उन्मत्त इव निश्चेता विललाप सुदुःखितः।
स्मृत्वा पितुर्गुणाङ्गानि तानि तानि तदा तदा॥', 'unmatta iva niścetā vilalāpa suduḥkhitaḥ
smṛtvā pitur guṇāṅgāni tāni tāni tadā tadā', null, 2071012),
('ramayana-2-71-13', 13, 'Ayodhya Kanda, Sarga 71, Verse 13', 'मन्थरा प्रभवस्तीव्रः कैकेयीग्राहसंकुलः।
वरदानमयोऽक्षोभ्योऽमज्जयच्छोकसागरः॥', 'mantharā prabhavas tīvraḥ kaikeyīgrāhasaṃkulaḥ
varadānamayo ''kṣobhyo ''majjayac chokasāgaraḥ', null, 2071013),
('ramayana-2-71-14', 14, 'Ayodhya Kanda, Sarga 71, Verse 14', 'सुकुमारं च बालं च सततं लालितं त्वया।
क्व तात भरतं हित्वा विलपन्तं गतो भवान्॥', 'sukumāraṃ ca bālaṃ ca satataṃ lālitaṃ tvayā
kva tāta bharataṃ hitvā vilapantaṃ gato bhavān', null, 2071014),
('ramayana-2-71-15', 15, 'Ayodhya Kanda, Sarga 71, Verse 15', 'ननु भोज्येषु पानेषु वस्त्रेष्वाभरणेषु च।
प्रवारयसि नः सर्वांस्तन्नः कोऽद्य करिष्यति॥', 'nanu bhojyeṣu pāneṣu vastreṣv ābharaṇeṣu ca
pravārayasi naḥ sarvāṃs tan naḥ ko ''dya kariṣyati', null, 2071015),
('ramayana-2-71-16', 16, 'Ayodhya Kanda, Sarga 71, Verse 16', 'अवदारण काले तु पृथिवी नावदीर्यते।
विहीना या त्वया राज्ञा धर्मज्ञेन महात्मना॥', 'avadāraṇa kāle tu pṛthivī nāvadīryate
vihīnā yā tvayā rājñā dharmajñena mahātmanā', null, 2071016),
('ramayana-2-71-17', 17, 'Ayodhya Kanda, Sarga 71, Verse 17', 'पितरि स्वर्गमापन्ने रामे चारण्यमाश्रिते।
किं मे जीवित सामर्थ्यं प्रवेक्ष्यामि हुताशनम्॥', 'pitari svargam āpanne rāme cāraṇyam āśrite
kiṃ me jīvita sāmarthyaṃ pravekṣyāmi hutāśanam', null, 2071017),
('ramayana-2-71-18', 18, 'Ayodhya Kanda, Sarga 71, Verse 18', 'हीनो भ्रात्रा च पित्रा च शून्यामिक्ष्वाकुपालिताम्।
अयोध्यां न प्रवेक्ष्यामि प्रवेक्ष्यामि तपोवनम्॥', 'hīno bhrātrā ca pitrā ca śūnyām ikṣvākupālitām
ayodhyāṃ na pravekṣyāmi pravekṣyāmi tapovanam', null, 2071018),
('ramayana-2-71-19', 19, 'Ayodhya Kanda, Sarga 71, Verse 19', 'तयोर्विलपितं श्रुत्वा व्यसनं चान्ववेक्ष्य तत्।
भृशमार्ततरा भूयः सर्व एवानुगामिनः॥', 'tayor vilapitaṃ śrutvā vyasanaṃ cānvavekṣya tat
bhṛśam ārtatarā bhūyaḥ sarva evānugāminaḥ', null, 2071019),
('ramayana-2-71-20', 20, 'Ayodhya Kanda, Sarga 71, Verse 20', 'ततो विषण्णौ श्रान्तौ च शत्रुघ्नभरतावुभौ।
धरण्यां संव्यचेष्टेतां भग्नशृङ्गाविवर्षभौ॥', 'tato viṣaṇṇau śrāntau ca śatrughnabharatāv ubhau
dharaṇyāṃ saṃvyaceṣṭetāṃ bhagnaśṛṅgāv ivarṣabhau', null, 2071020),
('ramayana-2-71-21', 21, 'Ayodhya Kanda, Sarga 71, Verse 21', 'ततः प्रकृतिमान्वैद्यः पितुरेषां पुरोहितः।
वसिष्ठो भरतं वाक्यमुत्थाप्य तमुवाच ह॥', 'tataḥ prakṛtimān vaidyaḥ pitur eṣāṃ purohitaḥ
vasiṣṭho bharataṃ vākyam utthāpya tam uvāca ha', null, 2071021),
('ramayana-2-71-22', 22, 'Ayodhya Kanda, Sarga 71, Verse 22', 'त्रीणि द्वन्द्वानि भूतेषु प्रवृत्तान्यविशेषतः।
तेषु चापरिहार्येषु नैवं भवितुमर्हति॥', 'trīṇi dvandvāni bhūteṣu pravṛttāny aviśeṣataḥ
teṣu cāparihāryeṣu naivaṃ bhavitum arhati', null, 2071022),
('ramayana-2-71-23', 23, 'Ayodhya Kanda, Sarga 71, Verse 23', 'सुमन्त्रश्चापि शत्रुघ्नमुत्थाप्याभिप्रसाद्य च।
श्रावयामास तत्त्वज्ञः सर्वभूतभवाभवौ॥', 'sumantraś cāpi śatrughnam utthāpyābhiprasādya ca
śrāvayām āsa tattvajñaḥ sarvabhūtabhavābhavau', null, 2071023),
('ramayana-2-71-24', 24, 'Ayodhya Kanda, Sarga 71, Verse 24', 'उत्थितौ तौ नरव्याघ्रौ प्रकाशेते यशस्विनौ।
वर्षातपपरिक्लिन्नौ पृथगिन्द्रध्वजाविव॥', 'utthitau tau naravyāghrau prakāśete yaśasvinau
varṣātapapariklinnau pṛthag indradhvajāv iva', null, 2071024),
('ramayana-2-71-25', 25, 'Ayodhya Kanda, Sarga 71, Verse 25', 'अश्रूणि परिमृद्नन्तौ रक्ताक्षौ दीनभाषिणौ।
अमात्यास्त्वरयन्ति स्म तनयौ चापराः क्रियाः॥', 'aśrūṇi parimṛdnantau raktākṣau dīnabhāṣiṇau
amātyās tvarayanti sma tanayau cāparāḥ kriyāḥ', null, 2071025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 72 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-72-1', 1, 'Ayodhya Kanda, Sarga 72, Verse 1', 'अत्र यात्रां समीहन्तं शत्रुघ्नो लक्ष्मणानुजः।
भरतं शोकसंतप्तमिदं वचनमब्रवीत्॥', 'atra yātrāṃ samīhantaṃ śatrughno lakṣmaṇānujaḥ
bharataṃ śokasaṃtaptam idaṃ vacanam abravīt', null, 2072001),
('ramayana-2-72-2', 2, 'Ayodhya Kanda, Sarga 72, Verse 2', 'गतिर्यः सर्वभूतानां दुःखे किं पुनरात्मनः।
स रामः सत्त्व संपन्नः स्त्रिया प्रव्राजितो वनम्॥', 'gatir yaḥ sarvabhūtānāṃ duḥkhe kiṃ punar ātmanaḥ
sa rāmaḥ sattva saṃpannaḥ striyā pravrājito vanam', null, 2072002),
('ramayana-2-72-3', 3, 'Ayodhya Kanda, Sarga 72, Verse 3', 'बलवान्वीर्य संपन्नो लक्ष्मणो नाम योऽप्यसौ।
किं न मोचयते रामं कृत्वापि पितृनिग्रहम्॥', 'balavān vīrya saṃpanno lakṣmaṇo nāma yo ''py asau
kiṃ na mocayate rāmaṃ kṛtvāpi pitṛnigraham', null, 2072003),
('ramayana-2-72-4', 4, 'Ayodhya Kanda, Sarga 72, Verse 4', 'पूर्वमेव तु निग्राह्यः समवेक्ष्य नयानयौ।
उत्पथं यः समारूढो नार्या राजा वशं गतः॥', 'pūrvam eva tu nigrāhyaḥ samavekṣya nayānayau
utpathaṃ yaḥ samārūḍho nāryā rājā vaśaṃ gataḥ', null, 2072004),
('ramayana-2-72-5', 5, 'Ayodhya Kanda, Sarga 72, Verse 5', 'इति संभाषमाणे तु शत्रुघ्ने लक्ष्मणानुजे।
प्राग्द्वारेऽभूत्तदा कुब्जा सर्वाभरणभूषिता॥', 'iti saṃbhāṣamāṇe tu śatrughne lakṣmaṇānuje
prāgdvāre ''bhūt tadā kubjā sarvābharaṇabhūṣitā', null, 2072005),
('ramayana-2-72-6', 6, 'Ayodhya Kanda, Sarga 72, Verse 6', 'लिप्ता चन्दनसारेण राजवस्त्राणि बिभ्रती।
मेखला दामभिश्चित्रै रज्जुबद्धेव वानरी॥', 'liptā candanasāreṇa rājavastrāṇi bibhratī
mekhalā dāmabhiś citrai rajjubaddheva vānarī', null, 2072006),
('ramayana-2-72-7', 7, 'Ayodhya Kanda, Sarga 72, Verse 7', 'तां समीक्ष्य तदा द्वाःस्थो भृशं पापस्य कारिणीम्।
गृहीत्वाकरुणं कुब्जां शत्रुघ्नाय न्यवेदयत्॥', 'tāṃ samīkṣya tadā dvāḥstho bhṛśaṃ pāpasya kāriṇīm
gṛhītvākaruṇaṃ kubjāṃ śatrughnāya nyavedayat', null, 2072007),
('ramayana-2-72-8', 8, 'Ayodhya Kanda, Sarga 72, Verse 8', 'यस्याः कृते वने रामो न्यस्तदेहश्च वः पिता।
सेयं पापा नृशंसा च तस्याः कुरु यथामति॥', 'yasyāḥ kṛte vane rāmo nyastadehaś ca vaḥ pitā
seyaṃ pāpā nṛśaṃsā ca tasyāḥ kuru yathāmati', null, 2072008),
('ramayana-2-72-9', 9, 'Ayodhya Kanda, Sarga 72, Verse 9', 'शत्रुघ्नश्च तदाज्ञाय वचनं भृशदुःखितः।
अन्तःपुरचरान्सर्वानित्युवाच धृतव्रतः॥', 'śatrughnaś ca tad ājñāya vacanaṃ bhṛśaduḥkhitaḥ
antaḥpuracarān sarvān ity uvāca dhṛtavrataḥ', null, 2072009),
('ramayana-2-72-10', 10, 'Ayodhya Kanda, Sarga 72, Verse 10', 'तीव्रमुत्पादितं दुःखं भ्रातॄणां मे तथा पितुः।
यया सेयं नृशंसस्य कर्मणः फलमश्नुताम्॥', 'tīvram utpāditaṃ duḥkhaṃ bhrātṝṇāṃ me tathā pituḥ
yayā seyaṃ nṛśaṃsasya karmaṇaḥ phalam aśnutām', null, 2072010),
('ramayana-2-72-11', 11, 'Ayodhya Kanda, Sarga 72, Verse 11', 'एवमुक्ता च तेनाशु सखी जनसमावृता।
गृहीता बलवत्कुब्जा सा तद्गृहमनादयत्॥', 'evam uktā ca tenāśu sakhī janasamāvṛtā
gṛhītā balavat kubjā sā tadgṛham anādayat', null, 2072011),
('ramayana-2-72-12', 12, 'Ayodhya Kanda, Sarga 72, Verse 12', 'ततः सुभृश संतप्तस्तस्याः सर्वः सखीजनः।
क्रुद्धमाज्ञाय शत्रुघ्नं व्यपलायत सर्वशः॥', 'tataḥ subhṛśa saṃtaptas tasyāḥ sarvaḥ sakhījanaḥ
kruddham ājñāya śatrughnaṃ vyapalāyata sarvaśaḥ', null, 2072012),
('ramayana-2-72-13', 13, 'Ayodhya Kanda, Sarga 72, Verse 13', 'अमन्त्रयत कृत्स्नश्च तस्याः सर्वसखीजनः।
यथायं समुपक्रान्तो निःशेषं नः करिष्यति॥', 'amantrayata kṛtsnaś ca tasyāḥ sarvasakhījanaḥ
yathāyaṃ samupakrānto niḥśeṣaṃ naḥ kariṣyati', null, 2072013),
('ramayana-2-72-14', 14, 'Ayodhya Kanda, Sarga 72, Verse 14', 'सानुक्रोशां वदान्यां च धर्मज्ञां च यशस्विनीम्।
कौसल्यां शरणं यामः सा हि नोऽस्तु ध्रुवा गतिः॥', 'sānukrośāṃ vadānyāṃ ca dharmajñāṃ ca yaśasvinīm
kausalyāṃ śaraṇaṃ yāmaḥ sā hi no ''stu dhruvā gatiḥ', null, 2072014),
('ramayana-2-72-15', 15, 'Ayodhya Kanda, Sarga 72, Verse 15', 'स च रोषेण ताम्राक्षः शत्रुघ्नः शत्रुतापनः।
विचकर्ष तदा कुब्जां क्रोशन्तीं पृथिवीतले॥', 'sa ca roṣeṇa tāmrākṣaḥ śatrughnaḥ śatrutāpanaḥ
vicakarṣa tadā kubjāṃ krośantīṃ pṛthivītale', null, 2072015),
('ramayana-2-72-16', 16, 'Ayodhya Kanda, Sarga 72, Verse 16', 'तस्या ह्याकृष्यमाणाया मन्थरायास्ततस्ततः।
चित्रं बहुविधं भाण्डं पृथिव्यां तद्व्यशीर्यत॥', 'tasyā hy ākṛṣyamāṇāyā mantharāyās tatas tataḥ
citraṃ bahuvidhaṃ bhāṇḍaṃ pṛthivyāṃ tad vyaśīryata', null, 2072016),
('ramayana-2-72-17', 17, 'Ayodhya Kanda, Sarga 72, Verse 17', 'तेन भाण्डेन संकीर्णं श्रीमद्राजनिवेशनम्।
अशोभत तदा भूयः शारदं गगनं यथा॥', 'tena bhāṇḍena saṃkīrṇaṃ śrīmadrājaniveśanam
aśobhata tadā bhūyaḥ śāradaṃ gaganaṃ yathā', null, 2072017),
('ramayana-2-72-18', 18, 'Ayodhya Kanda, Sarga 72, Verse 18', 'स बली बलवत्क्रोधाद्गृहीत्वा पुरुषर्षभः।
कैकेयीमभिनिर्भर्त्स्य बभाषे परुषं वचः॥', 'sa balī balavat krodhād gṛhītvā puruṣarṣabhaḥ
kaikeyīm abhinirbhartsya babhāṣe paruṣaṃ vacaḥ', null, 2072018),
('ramayana-2-72-19', 19, 'Ayodhya Kanda, Sarga 72, Verse 19', 'तैर्वाक्यैः परुषैर्दुःखैः कैकेयी भृशदुःखिता।
शत्रुघ्न भयसंत्रस्ता पुत्रं शरणमागता॥', 'tair vākyaiḥ paruṣair duḥkhaiḥ kaikeyī bhṛśaduḥkhitā
śatrughna bhayasaṃtrastā putraṃ śaraṇam āgatā', null, 2072019),
('ramayana-2-72-20', 20, 'Ayodhya Kanda, Sarga 72, Verse 20', 'तां प्रेक्ष्य भरतः क्रुद्धं शत्रुघ्नमिदमब्रवीत्।
अवध्याः सर्वभूतानां प्रमदाः क्षम्यतामिति॥', 'tāṃ prekṣya bharataḥ kruddhaṃ śatrughnam idam abravīt
avadhyāḥ sarvabhūtānāṃ pramadāḥ kṣamyatām iti', null, 2072020),
('ramayana-2-72-21', 21, 'Ayodhya Kanda, Sarga 72, Verse 21', 'हन्यामहमिमां पापां कैकेयीं दुष्टचारिणीम्।
यदि मां धार्मिको रामो नासूयेन्मातृघातकम्॥', 'hanyām aham imāṃ pāpāṃ kaikeyīṃ duṣṭacāriṇīm
yadi māṃ dhārmiko rāmo nāsūyen mātṛghātakam', null, 2072021),
('ramayana-2-72-22', 22, 'Ayodhya Kanda, Sarga 72, Verse 22', 'इमामपि हतां कुब्जां यदि जानाति राघवः।
त्वां च मां चैव धर्मात्मा नाभिभाषिष्यते ध्रुवम्॥', 'imām api hatāṃ kubjāṃ yadi jānāti rāghavaḥ
tvāṃ ca māṃ caiva dharmātmā nābhibhāṣiṣyate dhruvam', null, 2072022),
('ramayana-2-72-23', 23, 'Ayodhya Kanda, Sarga 72, Verse 23', 'भरतस्य वचः श्रुत्वा शत्रुघ्नो लक्ष्मणानुजः।
न्यवर्तत ततो रोषात्तां मुमोच च मन्थराम्॥', 'bharatasya vacaḥ śrutvā śatrughno lakṣmaṇānujaḥ
nyavartata tato roṣāt tāṃ mumoca ca mantharām', null, 2072023),
('ramayana-2-72-24', 24, 'Ayodhya Kanda, Sarga 72, Verse 24', 'सा पादमूले कैकेय्या मन्थरा निपपात ह।
निःश्वसन्ती सुदुःखार्ता कृपणं विललाप च॥', 'sā pādamūle kaikeyyā mantharā nipapāta ha
niḥśvasantī suduḥkhārtā kṛpaṇaṃ vilalāpa ca', null, 2072024),
('ramayana-2-72-25', 25, 'Ayodhya Kanda, Sarga 72, Verse 25', 'शत्रुघ्नविक्षेपविमूढसंज्ञां समीक्ष्य कुब्जां भरतस्य माता।
शनैः समाश्वासयदार्तरूपां क्रौञ्चीं विलग्नामिव वीक्षमाणाम्॥', 'śatrughnavikṣepavimūḍhasaṃjñāṃ samīkṣya kubjāṃ bharatasya mātā
śanaiḥ samāśvāsayad ārtarūpāṃ krauñcīṃ vilagnām iva vīkṣamāṇām', null, 2072025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 73 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-73-1', 1, 'Ayodhya Kanda, Sarga 73, Verse 1', 'ततः प्रभातसमये दिवसेऽथ चतुर्दशे।
समेत्य राजकर्तारो भरतं वाक्यमब्रुवन्॥', 'tataḥ prabhātasamaye divase ''tha caturdaśe
sametya rājakartāro bharataṃ vākyam abruvan', null, 2073001),
('ramayana-2-73-2', 2, 'Ayodhya Kanda, Sarga 73, Verse 2', 'गतो दशरथः स्वर्गं यो नो गुरुतरो गुरुः।
रामं प्रव्राज्य वै ज्येष्ठं लक्ष्मणं च महाबलम्॥', 'gato daśarathaḥ svargaṃ yo no gurutaro guruḥ
rāmaṃ pravrājya vai jyeṣṭhaṃ lakṣmaṇaṃ ca mahābalam', null, 2073002),
('ramayana-2-73-3', 3, 'Ayodhya Kanda, Sarga 73, Verse 3', 'त्वमद्य भव नो राजा राजपुत्र महायशः।
संगत्या नापराध्नोति राज्यमेतदनायकम्॥', 'tvam adya bhava no rājā rājaputra mahāyaśaḥ
saṃgatyā nāparādhnoti rājyam etad anāyakam', null, 2073003),
('ramayana-2-73-4', 4, 'Ayodhya Kanda, Sarga 73, Verse 4', 'आभिषेचनिकं सर्वमिदमादाय राघव।
प्रतीक्षते त्वां स्वजनः श्रेणयश्च नृपात्मज॥', 'ābhiṣecanikaṃ sarvam idam ādāya rāghava
pratīkṣate tvāṃ svajanaḥ śreṇayaś ca nṛpātmaja', null, 2073004),
('ramayana-2-73-5', 5, 'Ayodhya Kanda, Sarga 73, Verse 5', 'राज्यं गृहाण भरत पितृपैतामहं महत्।
अभिषेचय चात्मानं पाहि चास्मान्नरर्षभ॥', 'rājyaṃ gṛhāṇa bharata pitṛpaitāmahaṃ mahat
abhiṣecaya cātmānaṃ pāhi cāsmān nararṣabha', null, 2073005),
('ramayana-2-73-6', 6, 'Ayodhya Kanda, Sarga 73, Verse 6', 'आभिषेचनिकं भाण्डं कृत्वा सर्वं प्रदक्षिणम्।
भरतस्तं जनं सर्वं प्रत्युवाच धृतव्रतः॥', 'ābhiṣecanikaṃ bhāṇḍaṃ kṛtvā sarvaṃ pradakṣiṇam
bharatas taṃ janaṃ sarvaṃ pratyuvāca dhṛtavrataḥ', null, 2073006),
('ramayana-2-73-7', 7, 'Ayodhya Kanda, Sarga 73, Verse 7', 'ज्येष्ठस्य राजता नित्यमुचिता हि कुलस्य नः।
नैवं भवन्तो मां वक्तुमर्हन्ति कुशला जनाः॥', 'jyeṣṭhasya rājatā nityam ucitā hi kulasya naḥ
naivaṃ bhavanto māṃ vaktum arhanti kuśalā janāḥ', null, 2073007),
('ramayana-2-73-8', 8, 'Ayodhya Kanda, Sarga 73, Verse 8', 'रामः पूर्वो हि नो भ्राता भविष्यति महीपतिः।
अहं त्वरण्ये वत्स्यामि वर्षाणि नव पञ्च च॥', 'rāmaḥ pūrvo hi no bhrātā bhaviṣyati mahīpatiḥ
ahaṃ tv araṇye vatsyāmi varṣāṇi nava pañca ca', null, 2073008),
('ramayana-2-73-9', 9, 'Ayodhya Kanda, Sarga 73, Verse 9', 'युज्यतां महती सेना चतुरङ्गमहाबला।
आनयिष्याम्यहं ज्येष्ठं भ्रातरं राघवं वनात्॥', 'yujyatāṃ mahatī senā caturaṅgamahābalā
ānayiṣyāmy ahaṃ jyeṣṭhaṃ bhrātaraṃ rāghavaṃ vanāt', null, 2073009),
('ramayana-2-73-10', 10, 'Ayodhya Kanda, Sarga 73, Verse 10', 'आभिषेचनिकं चैव सर्वमेतदुपस्कृतम्।
पुरस्कृत्य गमिष्यामि रामहेतोर्वनं प्रति॥', 'ābhiṣecanikaṃ caiva sarvam etad upaskṛtam
puraskṛtya gamiṣyāmi rāmahetor vanaṃ prati', null, 2073010),
('ramayana-2-73-11', 11, 'Ayodhya Kanda, Sarga 73, Verse 11', 'तत्रैव तं नरव्याघ्रमभिषिच्य पुरस्कृतम्।
आनेष्यामि तु वै रामं हव्यवाहमिवाध्वरात्॥', 'tatraiva taṃ naravyāghram abhiṣicya puraskṛtam
āneṣyāmi tu vai rāmaṃ havyavāham ivādhvarāt', null, 2073011),
('ramayana-2-73-12', 12, 'Ayodhya Kanda, Sarga 73, Verse 12', 'न सकामा करिष्यामि स्वमिमां मातृगन्धिनीम्।
वने वत्स्याम्यहं दुर्गे रामो राजा भविष्यति॥', 'na sakāmā kariṣyāmi svam imāṃ mātṛgandhinīm
vane vatsyāmy ahaṃ durge rāmo rājā bhaviṣyati', null, 2073012),
('ramayana-2-73-13', 13, 'Ayodhya Kanda, Sarga 73, Verse 13', 'क्रियतां शिल्पिभिः पन्थाः समानि विषमाणि च।
रक्षिणश्चानुसंयान्तु पथि दुर्गविचारकाः॥', 'kriyatāṃ śilpibhiḥ panthāḥ samāni viṣamāṇi ca
rakṣiṇaś cānusaṃyāntu pathi durgavicārakāḥ', null, 2073013),
('ramayana-2-73-14', 14, 'Ayodhya Kanda, Sarga 73, Verse 14', 'एवं संभाषमाणं तं रामहेतोर्नृपात्मजम्।
प्रत्युवाच जनः सर्वः श्रीमद्वाक्यमनुत्तमम्॥', 'evaṃ saṃbhāṣamāṇaṃ taṃ rāmahetor nṛpātmajam
pratyuvāca janaḥ sarvaḥ śrīmadvākyam anuttamam', null, 2073014),
('ramayana-2-73-15', 15, 'Ayodhya Kanda, Sarga 73, Verse 15', 'एवं ते भाषमाणस्य पद्मा श्रीरुपतिष्ठताम्।
यस्त्वं ज्येष्ठे नृपसुते पृथिवीं दातुमिच्छसि॥', 'evaṃ te bhāṣamāṇasya padmā śrīr upatiṣṭhatām
yas tvaṃ jyeṣṭhe nṛpasute pṛthivīṃ dātum icchasi', null, 2073015),
('ramayana-2-73-16', 16, 'Ayodhya Kanda, Sarga 73, Verse 16', 'अनुत्तमं तद्वचनं नृपात्मज प्रभाषितं संश्रवणे निशम्य च।
प्रहर्षजास्तं प्रति बाष्पबिन्दवो निपेतुरार्यानननेत्रसंभवाः॥', 'anuttamaṃ tad vacanaṃ nṛpātmaja prabhāṣitaṃ saṃśravaṇe niśamya ca
praharṣajās taṃ prati bāṣpabindavo nipetur āryānananetrasaṃbhavāḥ', null, 2073016),
('ramayana-2-73-17', 17, 'Ayodhya Kanda, Sarga 73, Verse 17', 'ऊचुस्ते वचनमिदं निशम्य हृष्टाः सामात्याः सपरिषदो वियातशोकाः।
पन्थानं नरवरभक्तिमाञ्जनश्च व्यादिष्टस्तव वचनाच्च शिल्पिवर्गः॥', 'ūcus te vacanam idaṃ niśamya hṛṣṭāḥ sāmātyāḥ sapariṣado viyātaśokāḥ
panthānaṃ naravarabhaktimāñ janaś ca vyādiṣṭas tava vacanāc ca śilpivargaḥ', null, 2073017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 74 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-74-1', 1, 'Ayodhya Kanda, Sarga 74, Verse 1', 'अथ भूमिप्रदेशज्ञाः सूत्रकर्मविशारदाः।
स्वकर्माभिरताः शूराः खनका यन्त्रकास्तथा॥', 'atha bhūmipradeśajñāḥ sūtrakarmaviśāradāḥ
svakarmābhiratāḥ śūrāḥ khanakā yantrakās tathā', null, 2074001),
('ramayana-2-74-2', 2, 'Ayodhya Kanda, Sarga 74, Verse 2', 'कर्मान्तिकाः स्थपतयः पुरुषा यन्त्रकोविदाः।
तथा वर्धकयश्चैव मार्गिणो वृक्षतक्षकाः॥', 'karmāntikāḥ sthapatayaḥ puruṣā yantrakovidāḥ
tathā vardhakayaś caiva mārgiṇo vṛkṣatakṣakāḥ', null, 2074002),
('ramayana-2-74-3', 3, 'Ayodhya Kanda, Sarga 74, Verse 3', 'कूपकाराः सुधाकारा वंशकर्मकृतस्तथा।
समर्था ये च द्रष्टारः पुरतस्ते प्रतस्थिरे॥', 'kūpakārāḥ sudhākārā vaṃśakarmakṛtas tathā
samarthā ye ca draṣṭāraḥ puratas te pratasthire', null, 2074003),
('ramayana-2-74-4', 4, 'Ayodhya Kanda, Sarga 74, Verse 4', 'स तु हर्षात्तमुद्देशं जनौघो विपुलः प्रयान्।
अशोभत महावेगः सागरस्येव पर्वणि॥', 'sa tu harṣāt tam uddeśaṃ janaugho vipulaḥ prayān
aśobhata mahāvegaḥ sāgarasyeva parvaṇi', null, 2074004),
('ramayana-2-74-5', 5, 'Ayodhya Kanda, Sarga 74, Verse 5', 'ते स्ववारं समास्थाय वर्त्मकर्माणि कोविदाः।
करणैर्विविधोपेतैः पुरस्तात्संप्रतस्थिरे॥', 'te svavāraṃ samāsthāya vartmakarmāṇi kovidāḥ
karaṇair vividhopetaiḥ purastāt saṃpratasthire', null, 2074005),
('ramayana-2-74-6', 6, 'Ayodhya Kanda, Sarga 74, Verse 6', 'लतावल्लीश्च गुल्मांश्च स्थाणूनश्मन एव च।
जनास्ते चक्रिरे मार्गं छिन्दन्तो विविधान्द्रुमान्॥', 'latāvallīś ca gulmāṃś ca sthāṇūn aśmana eva ca
janās te cakrire mārgaṃ chindanto vividhān drumān', null, 2074006),
('ramayana-2-74-7', 7, 'Ayodhya Kanda, Sarga 74, Verse 7', 'अवृक्षेषु च देशेषु के चिद्वृक्षानरोपयन्।
के चित्कुठारैष्टङ्कैश्च दात्रैश्छिन्दन्क्व चित्क्व चित्॥', 'avṛkṣeṣu ca deśeṣu ke cid vṛkṣān aropayan
ke cit kuṭhāraiṣ ṭaṅkaiś ca dātraiś chindan kva cit kva cit', null, 2074007),
('ramayana-2-74-8', 8, 'Ayodhya Kanda, Sarga 74, Verse 8', 'अपरे वीरणस्तम्बान्बलिनो बलवत्तराः।
विधमन्ति स्म दुर्गाणि स्थलानि च ततस्ततः॥', 'apare vīraṇastambān balino balavattarāḥ
vidhamanti sma durgāṇi sthalāni ca tatas tataḥ', null, 2074008),
('ramayana-2-74-9', 9, 'Ayodhya Kanda, Sarga 74, Verse 9', 'अपरेऽपूरयन्कूपान्पांसुभिः श्वभ्रमायतम्।
निम्नभागांस्तथा के चित्समांश्चक्रुः समन्ततः॥', 'apare ''pūrayan kūpān pāṃsubhiḥ śvabhram āyatam
nimnabhāgāṃs tathā ke cit samāṃś cakruḥ samantataḥ', null, 2074009),
('ramayana-2-74-10', 10, 'Ayodhya Kanda, Sarga 74, Verse 10', 'बबन्धुर्बन्धनीयांश्च क्षोद्यान्संचुक्षुदुस्तदा।
बिभिदुर्भेदनीयांश्च तांस्तान्देशान्नरास्तदा॥', 'babandhur bandhanīyāṃś ca kṣodyān saṃcukṣudus tadā
bibhidur bhedanīyāṃś ca tāṃs tān deśān narās tadā', null, 2074010),
('ramayana-2-74-11', 11, 'Ayodhya Kanda, Sarga 74, Verse 11', 'अचिरेणैव कालेन परिवाहान्बहूदकान्।
चक्रुर्बहुविधाकारान्सागरप्रतिमान्बहून्।
उदपानान्बहुविधान्वेदिका परिमण्डितान्॥', 'acireṇaiva kālena parivāhān bahūdakān
cakrur bahuvidhākārān sāgarapratimān bahūn
udapānān bahuvidhān vedikā parimaṇḍitān', null, 2074011),
('ramayana-2-74-12', 12, 'Ayodhya Kanda, Sarga 74, Verse 12', 'ससुधाकुट्टिमतलः प्रपुष्पितमहीरुहः।
मत्तोद्घुष्टद्विजगणः पताकाभिरलंकृतः॥', 'sasudhākuṭṭimatalaḥ prapuṣpitamahīruhaḥ
mattodghuṣṭadvijagaṇaḥ patākābhir alaṃkṛtaḥ', null, 2074012),
('ramayana-2-74-13', 13, 'Ayodhya Kanda, Sarga 74, Verse 13', 'चन्दनोदकसंसिक्तो नानाकुसुमभूषितः।
बह्वशोभत सेनायाः पन्थाः स्वर्गपथोपमः॥', 'candanodakasaṃsikto nānākusumabhūṣitaḥ
bahv aśobhata senāyāḥ panthāḥ svargapathopamaḥ', null, 2074013),
('ramayana-2-74-14', 14, 'Ayodhya Kanda, Sarga 74, Verse 14', 'आज्ञाप्याथ यथाज्ञप्ति युक्तास्तेऽधिकृता नराः।
रमणीयेषु देशेषु बहुस्वादुफलेषु च॥', 'ājñāpyātha yathājñapti yuktās te ''dhikṛtā narāḥ
ramaṇīyeṣu deśeṣu bahusvāduphaleṣu ca', null, 2074014),
('ramayana-2-74-15', 15, 'Ayodhya Kanda, Sarga 74, Verse 15', 'यो निवेशस्त्वभिप्रेतो भरतस्य महात्मनः।
भूयस्तं शोभयामासुर्भूषाभिर्भूषणोपमम्॥', 'yo niveśas tv abhipreto bharatasya mahātmanaḥ
bhūyas taṃ śobhayām āsur bhūṣābhir bhūṣaṇopamam', null, 2074015),
('ramayana-2-74-16', 16, 'Ayodhya Kanda, Sarga 74, Verse 16', 'नक्षत्रेषु प्रशस्तेषु मुहूर्तेषु च तद्विदः।
निवेशं स्थापयामासुर्भरतस्य महात्मनः॥', 'nakṣatreṣu praśasteṣu muhūrteṣu ca tadvidaḥ
niveśaṃ sthāpayām āsur bharatasya mahātmanaḥ', null, 2074016),
('ramayana-2-74-17', 17, 'Ayodhya Kanda, Sarga 74, Verse 17', 'बहुपांसुचयाश्चापि परिखापरिवारिताः।
तत्रेन्द्रकीलप्रतिमाः प्रतोलीवरशोभिताः॥', 'bahupāṃsucayāś cāpi parikhāparivāritāḥ
tatrendrakīlapratimāḥ pratolīvaraśobhitāḥ', null, 2074017),
('ramayana-2-74-18', 18, 'Ayodhya Kanda, Sarga 74, Verse 18', 'प्रासादमालासंयुक्ताः सौधप्राकारसंवृताः।
पताका शोभिताः सर्वे सुनिर्मितमहापथाः॥', 'prāsādamālāsaṃyuktāḥ saudhaprākārasaṃvṛtāḥ
patākā śobhitāḥ sarve sunirmitamahāpathāḥ', null, 2074018),
('ramayana-2-74-19', 19, 'Ayodhya Kanda, Sarga 74, Verse 19', 'विसर्पद्भिरिवाकाशे विटङ्काग्रविमानकैः।
समुच्छ्रितैर्निवेशास्ते बभुः शक्रपुरोपमाः॥', 'visarpadbhir ivākāśe viṭaṅkāgravimānakaiḥ
samucchritair niveśās te babhuḥ śakrapuropamāḥ', null, 2074019),
('ramayana-2-74-20', 20, 'Ayodhya Kanda, Sarga 74, Verse 20', 'जाह्नवीं तु समासाद्य विविधद्रुम काननाम्।
शीतलामलपानीयां महामीनसमाकुलाम्॥', 'jāhnavīṃ tu samāsādya vividhadruma kānanām
śītalāmalapānīyāṃ mahāmīnasamākulām', null, 2074020),
('ramayana-2-74-21', 21, 'Ayodhya Kanda, Sarga 74, Verse 21', 'सचन्द्रतारागणमण्डितं यथा नभःक्षपायाममलं विराजते।
नरेन्द्रमार्गः स तथा व्यराजत क्रमेण रम्यः शुभशिल्पिनिर्मितः॥', 'sacandratārāgaṇamaṇḍitaṃ yathā nabhaḥkṣapāyām amalaṃ virājate
narendramārgaḥ sa tathā vyarājata krameṇa ramyaḥ śubhaśilpinirmitaḥ', null, 2074021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 75 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-75-1', 1, 'Ayodhya Kanda, Sarga 75, Verse 1', 'ततो नान्दीमुखीं रात्रिं भरतं सूतमागधाः।
तुष्टुवुर्वाग्विशेषज्ञाः स्तवैर्मङ्गलसंहितैः॥', 'tato nāndīmukhīṃ rātriṃ bharataṃ sūtamāgadhāḥ
tuṣṭuvur vāgviśeṣajñāḥ stavair maṅgalasaṃhitaiḥ', null, 2075001),
('ramayana-2-75-2', 2, 'Ayodhya Kanda, Sarga 75, Verse 2', 'सुवर्णकोणाभिहतः प्राणदद्यामदुन्दुभिः।
दध्मुः शङ्खांश्च शतशो वाद्यांश्चोच्चावचस्वरान्॥', 'suvarṇakoṇābhihataḥ prāṇadad yāmadundubhiḥ
dadhmuḥ śaṅkhāṃś ca śataśo vādyāṃś coccāvacasvarān', null, 2075002),
('ramayana-2-75-3', 3, 'Ayodhya Kanda, Sarga 75, Verse 3', 'स तूर्य घोषः सुमहान्दिवमापूरयन्निव।
भरतं शोकसंतप्तं भूयः शोकैररन्ध्रयत्॥', 'sa tūrya ghoṣaḥ sumahān divam āpūrayann iva
bharataṃ śokasaṃtaptaṃ bhūyaḥ śokair arandhrayat', null, 2075003),
('ramayana-2-75-4', 4, 'Ayodhya Kanda, Sarga 75, Verse 4', 'ततो प्रबुद्धो भरतस्तं घोषं संनिवर्त्य च।
नाहं राजेति चाप्युक्त्वा शत्रुघ्नमिदमब्रवीत्॥', 'tato prabuddho bharatas taṃ ghoṣaṃ saṃnivartya ca
nāhaṃ rājeti cāpy uktvā śatrughnam idam abravīt', null, 2075004),
('ramayana-2-75-5', 5, 'Ayodhya Kanda, Sarga 75, Verse 5', 'पश्य शत्रुघ्न कैकेय्या लोकस्यापकृतं महत्।
विसृज्य मयि दुःखानि राजा दशरथो गतः॥', 'paśya śatrughna kaikeyyā lokasyāpakṛtaṃ mahat
visṛjya mayi duḥkhāni rājā daśaratho gataḥ', null, 2075005),
('ramayana-2-75-6', 6, 'Ayodhya Kanda, Sarga 75, Verse 6', 'तस्यैषा धर्मराजस्य धर्ममूला महात्मनः।
परिभ्रमति राजश्रीर्नौरिवाकर्णिका जले॥', 'tasyaiṣā dharmarājasya dharmamūlā mahātmanaḥ
paribhramati rājaśrīr naur ivākarṇikā jale', null, 2075006),
('ramayana-2-75-7', 7, 'Ayodhya Kanda, Sarga 75, Verse 7', 'इत्येवं भरतं प्रेक्ष्य विलपन्तं विचेतनम्।
कृपणं रुरुदुः सर्वाः सस्वरं योषितस्तदा॥', 'ity evaṃ bharataṃ prekṣya vilapantaṃ vicetanam
kṛpaṇaṃ ruruduḥ sarvāḥ sasvaraṃ yoṣitas tadā', null, 2075007),
('ramayana-2-75-8', 8, 'Ayodhya Kanda, Sarga 75, Verse 8', 'तथा तस्मिन्विलपति वसिष्ठो राजधर्मवित्।
सभामिक्ष्वाकुनाथस्य प्रविवेश महायशाः॥', 'tathā tasmin vilapati vasiṣṭho rājadharmavit
sabhām ikṣvākunāthasya praviveśa mahāyaśāḥ', null, 2075008),
('ramayana-2-75-9', 9, 'Ayodhya Kanda, Sarga 75, Verse 9', 'शात कुम्भमयीं रम्यां मणिरत्नसमाकुलाम्।
सुधर्मामिव धर्मात्मा सगणः प्रत्यपद्यत॥', 'śāta kumbhamayīṃ ramyāṃ maṇiratnasamākulām
sudharmām iva dharmātmā sagaṇaḥ pratyapadyata', null, 2075009),
('ramayana-2-75-10', 10, 'Ayodhya Kanda, Sarga 75, Verse 10', 'स काञ्चनमयं पीठं परार्ध्यास्तरणावृतम्।
अध्यास्त सर्ववेदज्ञो दूताननुशशास च॥', 'sa kāñcanamayaṃ pīṭhaṃ parārdhyāstaraṇāvṛtam
adhyāsta sarvavedajño dūtān anuśaśāsa ca', null, 2075010),
('ramayana-2-75-11', 11, 'Ayodhya Kanda, Sarga 75, Verse 11', 'ब्राह्मणान्क्षत्रियान्योधानमात्यान्गणबल्लभान्।
क्षिप्रमानयताव्यग्राः कृत्यमात्ययिकं हि नः॥', 'brāhmaṇān kṣatriyān yodhān amātyān gaṇaballabhān
kṣipram ānayatāvyagrāḥ kṛtyam ātyayikaṃ hi naḥ', null, 2075011),
('ramayana-2-75-12', 12, 'Ayodhya Kanda, Sarga 75, Verse 12', 'ततो हलहलाशब्दो महान्समुदपद्यत।
रथैरश्वैर्गजैश्चापि जनानामुपगच्छताम्॥', 'tato halahalāśabdo mahān samudapadyata
rathair aśvair gajaiś cāpi janānām upagacchatām', null, 2075012),
('ramayana-2-75-13', 13, 'Ayodhya Kanda, Sarga 75, Verse 13', 'ततो भरतमायान्तं शतक्रतुमिवामराः।
प्रत्यनन्दन्प्रकृतयो यथा दशरथं तथा॥', 'tato bharatam āyāntaṃ śatakratum ivāmarāḥ
pratyanandan prakṛtayo yathā daśarathaṃ tathā', null, 2075013),
('ramayana-2-75-14', 14, 'Ayodhya Kanda, Sarga 75, Verse 14', 'ह्रद इव तिमिनागसंवृतः स्तिमितजलो मणिशङ्खशर्करः।
दशरथसुतशोभिता सभा सदशरथेव बभौ यथा पुरा॥', 'hrada iva timināgasaṃvṛtaḥ stimitajalo maṇiśaṅkhaśarkaraḥ
daśarathasutaśobhitā sabhā sadaśaratheva babhau yathā purā', null, 2075014)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 76 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-76-1', 1, 'Ayodhya Kanda, Sarga 76, Verse 1', 'तामार्यगणसंपूर्णां भरतः प्रग्रहां सभाम्।
ददर्श बुद्धिसंपन्नः पूर्णचन्द्रां निशामिव॥', 'tām āryagaṇasaṃpūrṇāṃ bharataḥ pragrahāṃ sabhām
dadarśa buddhisaṃpannaḥ pūrṇacandrāṃ niśām iva', null, 2076001),
('ramayana-2-76-2', 2, 'Ayodhya Kanda, Sarga 76, Verse 2', 'आसनानि यथान्यायमार्याणां विशतां तदा।
अदृश्यत घनापाये पूर्णचन्द्रेव शर्वरी॥', 'āsanāni yathānyāyam āryāṇāṃ viśatāṃ tadā
adṛśyata ghanāpāye pūrṇacandreva śarvarī', null, 2076002),
('ramayana-2-76-3', 3, 'Ayodhya Kanda, Sarga 76, Verse 3', 'राज्ञस्तु प्रकृतीः सर्वाः समग्राः प्रेक्ष्य धर्मवित्।
इदं पुरोहितो वाक्यं भरतं मृदु चाब्रवीत्॥', 'rājñas tu prakṛtīḥ sarvāḥ samagrāḥ prekṣya dharmavit
idaṃ purohito vākyaṃ bharataṃ mṛdu cābravīt', null, 2076003),
('ramayana-2-76-4', 4, 'Ayodhya Kanda, Sarga 76, Verse 4', 'तात राजा दशरथः स्वर्गतो धर्ममाचरन्।
धन धान्यवतीं स्फीतां प्रदाय पृथिवीं तव॥', 'tāta rājā daśarathaḥ svargato dharmam ācaran
dhana dhānyavatīṃ sphītāṃ pradāya pṛthivīṃ tava', null, 2076004),
('ramayana-2-76-5', 5, 'Ayodhya Kanda, Sarga 76, Verse 5', 'रामस्तथा सत्यधृतिः सतां धर्ममनुस्मरन्।
नाजहात्पितुरादेशं शशी ज्योत्स्नामिवोदितः॥', 'rāmas tathā satyadhṛtiḥ satāṃ dharmam anusmaran
nājahāt pitur ādeśaṃ śaśī jyotsnām ivoditaḥ', null, 2076005),
('ramayana-2-76-6', 6, 'Ayodhya Kanda, Sarga 76, Verse 6', 'पित्रा भ्रात्रा च ते दत्तं राज्यं निहतकण्टकम्।
तद्भुङ्क्ष्व मुदितामात्यः क्षिप्रमेवाभिषेचय॥', 'pitrā bhrātrā ca te dattaṃ rājyaṃ nihatakaṇṭakam
tad bhuṅkṣva muditāmātyaḥ kṣipram evābhiṣecaya', null, 2076006),
('ramayana-2-76-7', 7, 'Ayodhya Kanda, Sarga 76, Verse 7', 'उदीच्याश्च प्रतीच्याश्च दाक्षिणात्याश्च केवलाः।
कोट्यापरान्ताः सामुद्रा रत्नान्यभिहरन्तु ते॥', 'udīcyāś ca pratīcyāś ca dākṣiṇātyāś ca kevalāḥ
koṭyāparāntāḥ sāmudrā ratnāny abhiharantu te', null, 2076007),
('ramayana-2-76-8', 8, 'Ayodhya Kanda, Sarga 76, Verse 8', 'तच्छ्रुत्वा भरतो वाक्यं शोकेनाभिपरिप्लुतः।
जगाम मनसा रामं धर्मज्ञो धर्मकाङ्क्षया॥', 'tac chrutvā bharato vākyaṃ śokenābhipariplutaḥ
jagāma manasā rāmaṃ dharmajño dharmakāṅkṣayā', null, 2076008),
('ramayana-2-76-9', 9, 'Ayodhya Kanda, Sarga 76, Verse 9', 'स बाष्पकलया वाचा कलहंसस्वरो युवा।
विललाप सभामध्ये जगर्हे च पुरोहितम्॥', 'sa bāṣpakalayā vācā kalahaṃsasvaro yuvā
vilalāpa sabhāmadhye jagarhe ca purohitam', null, 2076009),
('ramayana-2-76-10', 10, 'Ayodhya Kanda, Sarga 76, Verse 10', 'चरितब्रह्मचर्यस्य विद्या स्नातस्य धीमतः।
धर्मे प्रयतमानस्य को राज्यं मद्विधो हरेत्॥', 'caritabrahmacaryasya vidyā snātasya dhīmataḥ
dharme prayatamānasya ko rājyaṃ madvidho haret', null, 2076010),
('ramayana-2-76-11', 11, 'Ayodhya Kanda, Sarga 76, Verse 11', 'कथं दशरथाज्जातो भवेद्राज्यापहारकः।
राज्यं चाहं च रामस्य धर्मं वक्तुमिहार्हसि॥', 'kathaṃ daśarathāj jāto bhaved rājyāpahārakaḥ
rājyaṃ cāhaṃ ca rāmasya dharmaṃ vaktum ihārhasi', null, 2076011),
('ramayana-2-76-12', 12, 'Ayodhya Kanda, Sarga 76, Verse 12', 'ज्येष्ठः श्रेष्ठश्च धर्मात्मा दिलीपनहुषोपमः।
लब्धुमर्हति काकुत्स्थो राज्यं दशरथो यथा॥', 'jyeṣṭhaḥ śreṣṭhaś ca dharmātmā dilīpanahuṣopamaḥ
labdhum arhati kākutstho rājyaṃ daśaratho yathā', null, 2076012),
('ramayana-2-76-13', 13, 'Ayodhya Kanda, Sarga 76, Verse 13', 'अनार्यजुष्टमस्वर्ग्यं कुर्यां पापमहं यदि।
इक्ष्वाकूणामहं लोके भवेयं कुलपांसनः॥', 'anāryajuṣṭam asvargyaṃ kuryāṃ pāpam ahaṃ yadi
ikṣvākūṇām ahaṃ loke bhaveyaṃ kulapāṃsanaḥ', null, 2076013),
('ramayana-2-76-14', 14, 'Ayodhya Kanda, Sarga 76, Verse 14', 'यद्धि मात्रा कृतं पापं नाहं तदभिरोचये।
इहस्थो वनदुर्गस्थं नमस्यामि कृताञ्जलिः॥', 'yad dhi mātrā kṛtaṃ pāpaṃ nāhaṃ tad abhirocaye
ihastho vanadurgasthaṃ namasyāmi kṛtāñjaliḥ', null, 2076014),
('ramayana-2-76-15', 15, 'Ayodhya Kanda, Sarga 76, Verse 15', 'राममेवानुगच्छामि स राजा द्विपदां वरः।
त्रयाणामपि लोकानां राघवो राज्यमर्हति॥', 'rāmam evānugacchāmi sa rājā dvipadāṃ varaḥ
trayāṇām api lokānāṃ rāghavo rājyam arhati', null, 2076015),
('ramayana-2-76-16', 16, 'Ayodhya Kanda, Sarga 76, Verse 16', 'तद्वाक्यं धर्मसंयुक्तं श्रुत्वा सर्वे सभासदः।
हर्षान्मुमुचुरश्रूणि रामे निहितचेतसः॥', 'tad vākyaṃ dharmasaṃyuktaṃ śrutvā sarve sabhāsadaḥ
harṣān mumucur aśrūṇi rāme nihitacetasaḥ', null, 2076016),
('ramayana-2-76-17', 17, 'Ayodhya Kanda, Sarga 76, Verse 17', 'यदि त्वार्यं न शक्ष्यामि विनिवर्तयितुं वनात्।
वने तत्रैव वत्स्यामि यथार्यो लक्ष्मणस्तथा॥', 'yadi tv āryaṃ na śakṣyāmi vinivartayituṃ vanāt
vane tatraiva vatsyāmi yathāryo lakṣmaṇas tathā', null, 2076017),
('ramayana-2-76-18', 18, 'Ayodhya Kanda, Sarga 76, Verse 18', 'सर्वोपायं तु वर्तिष्ये विनिवर्तयितुं बलात्।
समक्षमार्य मिश्राणां साधूनां गुणवर्तिनाम्॥', 'sarvopāyaṃ tu vartiṣye vinivartayituṃ balāt
samakṣam ārya miśrāṇāṃ sādhūnāṃ guṇavartinām', null, 2076018),
('ramayana-2-76-19', 19, 'Ayodhya Kanda, Sarga 76, Verse 19', 'एवमुक्त्वा तु धर्मात्मा भरतो भ्रातृवत्सलः।
समीपस्थमुवाचेदं सुमन्त्रं मन्त्रकोविदम्॥', 'evam uktvā tu dharmātmā bharato bhrātṛvatsalaḥ
samīpastham uvācedaṃ sumantraṃ mantrakovidam', null, 2076019),
('ramayana-2-76-20', 20, 'Ayodhya Kanda, Sarga 76, Verse 20', 'तूर्णमुत्थाय गच्छ त्वं सुमन्त्र मम शासनात्।
यात्रामाज्ञापय क्षिप्रं बलं चैव समानय॥', 'tūrṇam utthāya gaccha tvaṃ sumantra mama śāsanāt
yātrām ājñāpaya kṣipraṃ balaṃ caiva samānaya', null, 2076020),
('ramayana-2-76-21', 21, 'Ayodhya Kanda, Sarga 76, Verse 21', 'एवमुक्तः सुमन्त्रस्तु भरतेन महात्मना।
प्रहृष्टः सोऽदिशत्सर्वं यथा संदिष्टमिष्टवत्॥', 'evam uktaḥ sumantras tu bharatena mahātmanā
prahṛṣṭaḥ so ''diśat sarvaṃ yathā saṃdiṣṭam iṣṭavat', null, 2076021),
('ramayana-2-76-22', 22, 'Ayodhya Kanda, Sarga 76, Verse 22', 'ताः प्रहृष्टाः प्रकृतयो बलाध्यक्षा बलस्य च।
श्रुत्वा यात्रां समाज्ञप्तां राघवस्य निवर्तने॥', 'tāḥ prahṛṣṭāḥ prakṛtayo balādhyakṣā balasya ca
śrutvā yātrāṃ samājñaptāṃ rāghavasya nivartane', null, 2076022),
('ramayana-2-76-23', 23, 'Ayodhya Kanda, Sarga 76, Verse 23', 'ततो योधाङ्गनाः सर्वा भर्तॄन्सर्वान्गृहेगृहे।
यात्रा गमनमाज्ञाय त्वरयन्ति स्म हर्षिताः॥', 'tato yodhāṅganāḥ sarvā bhartṝn sarvān gṛhegṛhe
yātrā gamanam ājñāya tvarayanti sma harṣitāḥ', null, 2076023),
('ramayana-2-76-24', 24, 'Ayodhya Kanda, Sarga 76, Verse 24', 'ते हयैर्गोरथैः शीघ्रैः स्यन्दनैश्च मनोजवैः।
सह योधैर्बलाध्यक्षा बलं सर्वमचोदयन्॥', 'te hayair gorathaiḥ śīghraiḥ syandanaiś ca manojavaiḥ
saha yodhair balādhyakṣā balaṃ sarvam acodayan', null, 2076024),
('ramayana-2-76-25', 25, 'Ayodhya Kanda, Sarga 76, Verse 25', 'सज्जं तु तद्बलं दृष्ट्वा भरतो गुरुसंनिधौ।
रथं मे त्वरयस्वेति सुमन्त्रं पार्श्वतोऽब्रवीत्॥', 'sajjaṃ tu tad balaṃ dṛṣṭvā bharato gurusaṃnidhau
rathaṃ me tvarayasveti sumantraṃ pārśvato ''bravīt', null, 2076025),
('ramayana-2-76-26', 26, 'Ayodhya Kanda, Sarga 76, Verse 26', 'भरतस्य तु तस्याज्ञां प्रतिगृह्य प्रहर्षितः।
रथं गृहीत्वा प्रययौ युक्तं परमवाजिभिः॥', 'bharatasya tu tasyājñāṃ pratigṛhya praharṣitaḥ
rathaṃ gṛhītvā prayayau yuktaṃ paramavājibhiḥ', null, 2076026),
('ramayana-2-76-27', 27, 'Ayodhya Kanda, Sarga 76, Verse 27', 'स राघवः सत्यधृतिः प्रतापवान्ब्रुवन्सुयुक्तं दृढसत्यविक्रमः।
गुरुं महारण्यगतं यशस्विनं प्रसादयिष्यन्भरतोऽब्रवीत्तदा॥', 'sa rāghavaḥ satyadhṛtiḥ pratāpavān bruvan suyuktaṃ dṛḍhasatyavikramaḥ
guruṃ mahāraṇyagataṃ yaśasvinaṃ prasādayiṣyan bharato ''bravīt tadā', null, 2076027),
('ramayana-2-76-28', 28, 'Ayodhya Kanda, Sarga 76, Verse 28', 'तूर्णं समुत्थाय सुमन्त्र गच्छ बलस्य योगाय बलप्रधानान्।
आनेतुमिच्छामि हि तं वनस्थं प्रसाद्य रामं जगतो हिताय॥', 'tūrṇaṃ samutthāya sumantra gaccha balasya yogāya balapradhānān
ānetum icchāmi hi taṃ vanasthaṃ prasādya rāmaṃ jagato hitāya', null, 2076028),
('ramayana-2-76-29', 29, 'Ayodhya Kanda, Sarga 76, Verse 29', 'स सूतपुत्रो भरतेन सम्यगाज्ञापितः संपरिपूर्णकामः।
शशास सर्वान्प्रकृतिप्रधानान्बलस्य मुख्यांश्च सुहृज्जनं च॥', 'sa sūtaputro bharatena samyag ājñāpitaḥ saṃparipūrṇakāmaḥ
śaśāsa sarvān prakṛtipradhānān balasya mukhyāṃś ca suhṛjjanaṃ ca', null, 2076029),
('ramayana-2-76-30', 30, 'Ayodhya Kanda, Sarga 76, Verse 30', 'ततः समुत्थाय कुले कुले ते राजन्यवैश्या वृषलाश्च विप्राः।
अयूयुजन्नुष्ट्ररथान्खरांश्च नागान्हयांश्चैव कुलप्रसूतान्॥', 'tataḥ samutthāya kule kule te rājanyavaiśyā vṛṣalāś ca viprāḥ
ayūyujann uṣṭrarathān kharāṃś ca nāgān hayāṃś caiva kulaprasūtān', null, 2076030)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 77 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-77-1', 1, 'Ayodhya Kanda, Sarga 77, Verse 1', 'ततः समुत्थितः काल्यमास्थाय स्यन्दनोत्तमम्।
प्रययौ भरतः शीघ्रं रामदर्शनकाङ्क्षया॥', 'tataḥ samutthitaḥ kālyam āsthāya syandanottamam
prayayau bharataḥ śīghraṃ rāmadarśanakāṅkṣayā', null, 2077001),
('ramayana-2-77-2', 2, 'Ayodhya Kanda, Sarga 77, Verse 2', 'अग्रतः प्रययुस्तस्य सर्वे मन्त्रिपुरोधसः।
अधिरुह्य हयैर्युक्तान्रथान्सूर्यरथोपमान्॥', 'agrataḥ prayayus tasya sarve mantripurodhasaḥ
adhiruhya hayair yuktān rathān sūryarathopamān', null, 2077002),
('ramayana-2-77-3', 3, 'Ayodhya Kanda, Sarga 77, Verse 3', 'नवनागसहस्राणि कल्पितानि यथाविधि।
अन्वयुर्भरतं यान्तमिक्ष्वाकु कुलनन्दनम्॥', 'navanāgasahasrāṇi kalpitāni yathāvidhi
anvayur bharataṃ yāntam ikṣvāku kulanandanam', null, 2077003),
('ramayana-2-77-4', 4, 'Ayodhya Kanda, Sarga 77, Verse 4', 'षष्ठी रथसहस्राणि धन्विनो विविधायुधाः।
अन्वयुर्भरतं यान्तं राजपुत्रं यशस्विनम्॥', 'ṣaṣṭhī rathasahasrāṇi dhanvino vividhāyudhāḥ
anvayur bharataṃ yāntaṃ rājaputraṃ yaśasvinam', null, 2077004),
('ramayana-2-77-5', 5, 'Ayodhya Kanda, Sarga 77, Verse 5', 'शतं सहस्राण्यश्वानां समारूढानि राघवम्।
अन्वयुर्भरतं यान्तं राजपुत्रं यशस्विनम्॥', 'śataṃ sahasrāṇy aśvānāṃ samārūḍhāni rāghavam
anvayur bharataṃ yāntaṃ rājaputraṃ yaśasvinam', null, 2077005),
('ramayana-2-77-6', 6, 'Ayodhya Kanda, Sarga 77, Verse 6', 'कैकेयी च सुमित्रा च कौसल्या च यशस्विनी।
रामानयनसंहृष्टा ययुर्यानेन भास्वता॥', 'kaikeyī ca sumitrā ca kausalyā ca yaśasvinī
rāmānayanasaṃhṛṣṭā yayur yānena bhāsvatā', null, 2077006),
('ramayana-2-77-7', 7, 'Ayodhya Kanda, Sarga 77, Verse 7', 'प्रयाताश्चार्यसंघाता रामं द्रष्टुं सलक्ष्मणम्।
तस्यैव च कथाश्चित्राः कुर्वाणा हृष्टमानसाः॥', 'prayātāś cāryasaṃghātā rāmaṃ draṣṭuṃ salakṣmaṇam
tasyaiva ca kathāś citrāḥ kurvāṇā hṛṣṭamānasāḥ', null, 2077007),
('ramayana-2-77-8', 8, 'Ayodhya Kanda, Sarga 77, Verse 8', 'मेघश्यामं महाबाहुं स्थिरसत्त्वं दृढव्रतम्।
कदा द्रक्ष्यामहे रामं जगतः शोकनाशनम्॥', 'meghaśyāmaṃ mahābāhuṃ sthirasattvaṃ dṛḍhavratam
kadā drakṣyāmahe rāmaṃ jagataḥ śokanāśanam', null, 2077008),
('ramayana-2-77-9', 9, 'Ayodhya Kanda, Sarga 77, Verse 9', 'दृष्ट एव हि नः शोकमपनेष्यति राघवः।
तमः सर्वस्य लोकस्य समुद्यन्निव भास्करः॥', 'dṛṣṭa eva hi naḥ śokam apaneṣyati rāghavaḥ
tamaḥ sarvasya lokasya samudyann iva bhāskaraḥ', null, 2077009),
('ramayana-2-77-10', 10, 'Ayodhya Kanda, Sarga 77, Verse 10', 'इत्येवं कथयन्तस्ते संप्रहृष्टाः कथाः शुभाः।
परिष्वजानाश्चान्योन्यं ययुर्नागरिकास्तदा॥', 'ity evaṃ kathayantas te saṃprahṛṣṭāḥ kathāḥ śubhāḥ
pariṣvajānāś cānyonyaṃ yayur nāgarikās tadā', null, 2077010),
('ramayana-2-77-11', 11, 'Ayodhya Kanda, Sarga 77, Verse 11', 'ये च तत्रापरे सर्वे संमता ये च नैगमाः।
रामं प्रति ययुर्हृष्टाः सर्वाः प्रकृतयस्तदा॥', 'ye ca tatrāpare sarve saṃmatā ye ca naigamāḥ
rāmaṃ prati yayur hṛṣṭāḥ sarvāḥ prakṛtayas tadā', null, 2077011),
('ramayana-2-77-12', 12, 'Ayodhya Kanda, Sarga 77, Verse 12', 'मणि काराश्च ये के चित्कुम्भकाराश्च शोभनाः।
सूत्रकर्मकृतश्चैव ये च शस्त्रोपजीविनः॥', 'maṇi kārāś ca ye ke cit kumbhakārāś ca śobhanāḥ
sūtrakarmakṛtaś caiva ye ca śastropajīvinaḥ', null, 2077012),
('ramayana-2-77-13', 13, 'Ayodhya Kanda, Sarga 77, Verse 13', 'मायूरकाः क्राकचिका रोचका वेधकास्तथा।
दन्तकाराः सुधाकारास्तथा गन्धोपजीविनः॥', 'māyūrakāḥ krākacikā rocakā vedhakās tathā
dantakārāḥ sudhākārās tathā gandhopajīvinaḥ', null, 2077013),
('ramayana-2-77-14', 14, 'Ayodhya Kanda, Sarga 77, Verse 14', 'सुवर्णकाराः प्रख्यातास्तथा कम्बलधावकाः।
स्नापकाच्छादका वैद्या धूपकाः शौण्डिकास्तथा॥', 'suvarṇakārāḥ prakhyātās tathā kambaladhāvakāḥ
snāpakācchādakā vaidyā dhūpakāḥ śauṇḍikās tathā', null, 2077014),
('ramayana-2-77-15', 15, 'Ayodhya Kanda, Sarga 77, Verse 15', 'रजकास्तुन्नवायाश्च ग्रामघोषमहत्तराः।
शैलूषाश्च सह स्त्रीभिर्यान्ति कैवर्तकास्तथा॥', 'rajakās tunnavāyāś ca grāmaghoṣamahattarāḥ
śailūṣāś ca saha strībhir yānti kaivartakās tathā', null, 2077015),
('ramayana-2-77-16', 16, 'Ayodhya Kanda, Sarga 77, Verse 16', 'समाहिता वेदविदो ब्राह्मणा वृत्तसंमताः।
गोरथैर्भरतं यान्तमनुजग्मुः सहस्रशः॥', 'samāhitā vedavido brāhmaṇā vṛttasaṃmatāḥ
gorathair bharataṃ yāntam anujagmuḥ sahasraśaḥ', null, 2077016),
('ramayana-2-77-17', 17, 'Ayodhya Kanda, Sarga 77, Verse 17', 'सुवेषाः शुद्धवसनास्ताम्रमृष्टानुलेपनाः।
सर्वे ते विविधैर्यानैः शनैर्भरतमन्वयुः॥', 'suveṣāḥ śuddhavasanās tāmramṛṣṭānulepanāḥ
sarve te vividhair yānaiḥ śanair bharatam anvayuḥ', null, 2077017),
('ramayana-2-77-18', 18, 'Ayodhya Kanda, Sarga 77, Verse 18', 'प्रहृष्टमुदिता सेना सान्वयात्कैकयीसुतम्।
व्यवतिष्ठत सा सेना भरतस्यानुयायिनी॥', 'prahṛṣṭamuditā senā sānvayāt kaikayīsutam
vyavatiṣṭhata sā senā bharatasyānuyāyinī', null, 2077018),
('ramayana-2-77-19', 19, 'Ayodhya Kanda, Sarga 77, Verse 19', 'निरीक्ष्यानुगतां सेनां तां च गङ्गां शिवोदकाम्।
भरतः सचिवान्सर्वानब्रवीद्वाक्यकोविदः॥', 'nirīkṣyānugatāṃ senāṃ tāṃ ca gaṅgāṃ śivodakām
bharataḥ sacivān sarvān abravīd vākyakovidaḥ', null, 2077019),
('ramayana-2-77-20', 20, 'Ayodhya Kanda, Sarga 77, Verse 20', 'निवेशयत मे सैन्यमभिप्रायेण सर्वशः।
विश्रान्तः प्रतरिष्यामः श्व इदानीं महानदीम्॥', 'niveśayata me sainyam abhiprāyeṇa sarvaśaḥ
viśrāntaḥ pratariṣyāmaḥ śva idānīṃ mahānadīm', null, 2077020),
('ramayana-2-77-21', 21, 'Ayodhya Kanda, Sarga 77, Verse 21', 'दातुं च तावदिच्छामि स्वर्गतस्य महीपतेः।
और्ध्वदेह निमित्तार्थमवतीर्योदकं नदीम्॥', 'dātuṃ ca tāvad icchāmi svar gatasya mahīpateḥ
aurdhvadeha nimittārtham avatīryodakaṃ nadīm', null, 2077021),
('ramayana-2-77-22', 22, 'Ayodhya Kanda, Sarga 77, Verse 22', 'तस्यैवं ब्रुवतोऽमात्यास्तथेत्युक्त्वा समाहिताः।
न्यवेशयंस्तांश्छन्देन स्वेन स्वेन पृथक्पृथक्॥', 'tasyaivaṃ bruvato ''mātyās tathety uktvā samāhitāḥ
nyaveśayaṃs tāṃś chandena svena svena pṛthakpṛthak', null, 2077022),
('ramayana-2-77-23', 23, 'Ayodhya Kanda, Sarga 77, Verse 23', 'निवेश्य गङ्गामनु तां महानदीं चमूं विधानैः परिबर्ह शोभिनीम्।
उवास रामस्य तदा महात्मनो विचिन्तयानो भरतो निवर्तनम्॥', 'niveśya gaṅgām anu tāṃ mahānadīṃ camūṃ vidhānaiḥ paribarha śobhinīm
uvāsa rāmasya tadā mahātmano vicintayāno bharato nivartanam', null, 2077023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 78 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-78-1', 1, 'Ayodhya Kanda, Sarga 78, Verse 1', 'ततो निविष्टां ध्वजिनीं गङ्गामन्वाश्रितां नदीम्।
निषादराजो दृष्ट्वैव ज्ञातीन्संत्वरितोऽब्रवीत्॥', 'tato niviṣṭāṃ dhvajinīṃ gaṅgām anvāśritāṃ nadīm
niṣādarājo dṛṣṭvaiva jñātīn saṃtvarito ''bravīt', null, 2078001),
('ramayana-2-78-2', 2, 'Ayodhya Kanda, Sarga 78, Verse 2', 'महतीयमतः सेना सागराभा प्रदृश्यते।
नास्यान्तमवगच्छामि मनसापि विचिन्तयन्॥', 'mahatīyam ataḥ senā sāgarābhā pradṛśyate
nāsyāntam avagacchāmi manasāpi vicintayan', null, 2078002),
('ramayana-2-78-3', 3, 'Ayodhya Kanda, Sarga 78, Verse 3', 'स एष हि महाकायः कोविदारध्वजो रथे।
बन्धयिष्यति वा दाशानथ वास्मान्वधिष्यति॥', 'sa eṣa hi mahākāyaḥ kovidāradhvajo rathe
bandhayiṣyati vā dāśān atha vāsmān vadhiṣyati', null, 2078003),
('ramayana-2-78-4', 4, 'Ayodhya Kanda, Sarga 78, Verse 4', 'अथ दाशरथिं रामं पित्रा राज्याद्विवासितम्।
भरतः कैकेयीपुत्रो हन्तुं समधिगच्छति॥', 'atha dāśarathiṃ rāmaṃ pitrā rājyād vivāsitam
bharataḥ kaikeyīputro hantuṃ samadhigacchati', null, 2078004),
('ramayana-2-78-5', 5, 'Ayodhya Kanda, Sarga 78, Verse 5', 'भर्ता चैव सखा चैव रामो दाशरथिर्मम।
तस्यार्थकामाः संनद्धा गङ्गानूपेऽत्र तिष्ठत॥', 'bhartā caiva sakhā caiva rāmo dāśarathir mama
tasyārthakāmāḥ saṃnaddhā gaṅgānūpe ''tra tiṣṭhata', null, 2078005),
('ramayana-2-78-6', 6, 'Ayodhya Kanda, Sarga 78, Verse 6', 'तिष्ठन्तु सर्वदाशाश्च गङ्गामन्वाश्रिता नदीम्।
बलयुक्ता नदीरक्षा मांसमूलफलाशनाः॥', 'tiṣṭhantu sarvadāśāś ca gaṅgām anvāśritā nadīm
balayuktā nadīrakṣā māṃsamūlaphalāśanāḥ', null, 2078006),
('ramayana-2-78-7', 7, 'Ayodhya Kanda, Sarga 78, Verse 7', 'नावां शतानां पञ्चानां कैवर्तानां शतं शतम्।
संनद्धानां तथा यूनां तिष्ठन्त्वत्यभ्यचोदयत्॥', 'nāvāṃ śatānāṃ pañcānāṃ kaivartānāṃ śataṃ śatam
saṃnaddhānāṃ tathā yūnāṃ tiṣṭhantv atyabhyacodayat', null, 2078007),
('ramayana-2-78-8', 8, 'Ayodhya Kanda, Sarga 78, Verse 8', 'यदा तुष्टस्तु भरतो रामस्येह भविष्यति।
सेयं स्वस्तिमयी सेना गङ्गामद्य तरिष्यति॥', 'yadā tuṣṭas tu bharato rāmasyeha bhaviṣyati
seyaṃ svastimayī senā gaṅgām adya tariṣyati', null, 2078008),
('ramayana-2-78-9', 9, 'Ayodhya Kanda, Sarga 78, Verse 9', 'इत्युक्त्वोपायनं गृह्य मत्स्यमांसमधूनि च।
अभिचक्राम भरतं निषादाधिपतिर्गुहः॥', 'ity uktvopāyanaṃ gṛhya matsyamāṃsamadhūni ca
abhicakrāma bharataṃ niṣādādhipatir guhaḥ', null, 2078009),
('ramayana-2-78-10', 10, 'Ayodhya Kanda, Sarga 78, Verse 10', 'तमायान्तं तु संप्रेक्ष्य सूतपुत्रः प्रतापवान्।
भरतायाचचक्षेऽथ विनयज्ञो विनीतवत्॥', 'tam āyāntaṃ tu saṃprekṣya sūtaputraḥ pratāpavān
bharatāyācacakṣe ''tha vinayajño vinītavat', null, 2078010),
('ramayana-2-78-11', 11, 'Ayodhya Kanda, Sarga 78, Verse 11', 'एष ज्ञातिसहस्रेण स्थपतिः परिवारितः।
कुशलो दण्डकारण्ये वृद्धो भ्रातुश्च ते सखा॥', 'eṣa jñātisahasreṇa sthapatiḥ parivāritaḥ
kuśalo daṇḍakāraṇye vṛddho bhrātuś ca te sakhā', null, 2078011),
('ramayana-2-78-12', 12, 'Ayodhya Kanda, Sarga 78, Verse 12', 'तस्मात्पश्यतु काकुत्स्थ त्वां निषादाधिपो गुहः।
असंशयं विजानीते यत्र तौ रामलक्ष्मणौ॥', 'tasmāt paśyatu kākutstha tvāṃ niṣādādhipo guhaḥ
asaṃśayaṃ vijānīte yatra tau rāmalakṣmaṇau', null, 2078012),
('ramayana-2-78-13', 13, 'Ayodhya Kanda, Sarga 78, Verse 13', 'एतत्तु वचनं श्रुत्वा सुमन्त्राद्भरतः शुभम्।
उवाच वचनं शीघ्रं गुहः पश्यतु मामिति॥', 'etat tu vacanaṃ śrutvā sumantrād bharataḥ śubham
uvāca vacanaṃ śīghraṃ guhaḥ paśyatu mām iti', null, 2078013),
('ramayana-2-78-14', 14, 'Ayodhya Kanda, Sarga 78, Verse 14', 'लब्ध्वाभ्यनुज्ञां संहृष्टो ज्ञातिभिः परिवारितः।
आगम्य भरतं प्रह्वो गुहो वचनमब्रवीत्॥', 'labdhvābhyanujñāṃ saṃhṛṣṭo jñātibhiḥ parivāritaḥ
āgamya bharataṃ prahvo guho vacanam abravīt', null, 2078014),
('ramayana-2-78-15', 15, 'Ayodhya Kanda, Sarga 78, Verse 15', 'निष्कुटश्चैव देशोऽयं वञ्चिताश्चापि ते वयम्।
निवेदयामस्ते सर्वे स्वके दाशकुले वस॥', 'niṣkuṭaś caiva deśo ''yaṃ vañcitāś cāpi te vayam
nivedayāmas te sarve svake dāśakule vasa', null, 2078015),
('ramayana-2-78-16', 16, 'Ayodhya Kanda, Sarga 78, Verse 16', 'अस्ति मूलं फलं चैव निषादैः समुपाहृतम्।
आर्द्रं च मांसं शुष्कं च वन्यं चोच्चावचं महत्॥', 'asti mūlaṃ phalaṃ caiva niṣādaiḥ samupāhṛtam
ārdraṃ ca māṃsaṃ śuṣkaṃ ca vanyaṃ coccāvacaṃ mahat', null, 2078016),
('ramayana-2-78-17', 17, 'Ayodhya Kanda, Sarga 78, Verse 17', 'आशंसे स्वाशिता सेना वत्स्यतीमां विभावरीम्।
अर्चितो विविधैः कामैः श्वः ससैन्यो गमिष्यसि॥', 'āśaṃse svāśitā senā vatsyatīmāṃ vibhāvarīm
arcito vividhaiḥ kāmaiḥ śvaḥ sasainyo gamiṣyasi', null, 2078017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 79 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-79-1', 1, 'Ayodhya Kanda, Sarga 79, Verse 1', 'एवमुक्तस्तु भरतो निषादाधिपतिं गुहम्।
प्रत्युवाच महाप्राज्ञो वाक्यं हेत्वर्थसंहितम्॥', 'evam uktas tu bharato niṣādādhipatiṃ guham
pratyuvāca mahāprājño vākyaṃ hetvarthasaṃhitam', null, 2079001),
('ramayana-2-79-2', 2, 'Ayodhya Kanda, Sarga 79, Verse 2', 'ऊर्जितः खलु ते कामः कृतो मम गुरोः सखे।
यो मे त्वमीदृशीं सेनामेकोऽभ्यर्चितुमिच्छसि॥', 'ūrjitaḥ khalu te kāmaḥ kṛto mama guroḥ sakhe
yo me tvam īdṛśīṃ senām eko ''bhyarcitum icchasi', null, 2079002),
('ramayana-2-79-3', 3, 'Ayodhya Kanda, Sarga 79, Verse 3', 'इत्युक्त्वा तु महातेजा गुहं वचनमुत्तमम्।
अब्रवीद्भरतः श्रीमान्निषादाधिपतिं पुनः॥', 'ity uktvā tu mahātejā guhaṃ vacanam uttamam
abravīd bharataḥ śrīmān niṣādādhipatiṃ punaḥ', null, 2079003),
('ramayana-2-79-4', 4, 'Ayodhya Kanda, Sarga 79, Verse 4', 'कतरेण गमिष्यामि भरद्वाजाश्रमं गुह।
गहनोऽयं भृशं देशो गङ्गानूपो दुरत्ययः॥', 'katareṇa gamiṣyāmi bharadvājāśramaṃ guha
gahano ''yaṃ bhṛśaṃ deśo gaṅgānūpo duratyayaḥ', null, 2079004),
('ramayana-2-79-5', 5, 'Ayodhya Kanda, Sarga 79, Verse 5', 'तस्य तद्वचनं श्रुत्वा राजपुत्रस्य धीमतः।
अब्रवीत्प्राञ्जलिर्वाक्यं गुहो गहनगोचरः॥', 'tasya tad vacanaṃ śrutvā rājaputrasya dhīmataḥ
abravīt prāñjalir vākyaṃ guho gahanagocaraḥ', null, 2079005),
('ramayana-2-79-6', 6, 'Ayodhya Kanda, Sarga 79, Verse 6', 'दाशास्त्वनुगमिष्यन्ति धन्विनः सुसमाहिताः।
अहं चानुगमिष्यामि राजपुत्र महायशः॥', 'dāśās tv anugamiṣyanti dhanvinaḥ susamāhitāḥ
ahaṃ cānugamiṣyāmi rājaputra mahāyaśaḥ', null, 2079006),
('ramayana-2-79-7', 7, 'Ayodhya Kanda, Sarga 79, Verse 7', 'कच्चिन्न दुष्टो व्रजसि रामस्याक्लिष्टकर्मणः।
इयं ते महती सेना शङ्कां जनयतीव मे॥', 'kaccin na duṣṭo vrajasi rāmasyākliṣṭakarmaṇaḥ
iyaṃ te mahatī senā śaṅkāṃ janayatīva me', null, 2079007),
('ramayana-2-79-8', 8, 'Ayodhya Kanda, Sarga 79, Verse 8', 'तमेवमभिभाषन्तमाकाश इव निर्मलः।
भरतः श्लक्ष्णया वाचा गुहं वचनमब्रवीत्॥', 'tam evam abhibhāṣantam ākāśa iva nirmalaḥ
bharataḥ ślakṣṇayā vācā guhaṃ vacanam abravīt', null, 2079008),
('ramayana-2-79-9', 9, 'Ayodhya Kanda, Sarga 79, Verse 9', 'मा भूत्स कालो यत्कष्टं न मां शङ्कितुमर्हसि।
राघवः स हि मे भ्राता ज्येष्ठः पितृसमो मम॥', 'mā bhūt sa kālo yat kaṣṭaṃ na māṃ śaṅkitum arhasi
rāghavaḥ sa hi me bhrātā jyeṣṭhaḥ pitṛsamo mama', null, 2079009),
('ramayana-2-79-10', 10, 'Ayodhya Kanda, Sarga 79, Verse 10', 'तं निवर्तयितुं यामि काकुत्स्थं वनवासिनम्।
बुद्धिरन्या न ते कार्या गुह सत्यं ब्रवीमि ते॥', 'taṃ nivartayituṃ yāmi kākutsthaṃ vanavāsinam
buddhir anyā na te kāryā guha satyaṃ bravīmi te', null, 2079010),
('ramayana-2-79-11', 11, 'Ayodhya Kanda, Sarga 79, Verse 11', 'स तु संहृष्टवदनः श्रुत्वा भरतभाषितम्।
पुनरेवाब्रवीद्वाक्यं भरतं प्रति हर्षितः॥', 'sa tu saṃhṛṣṭavadanaḥ śrutvā bharatabhāṣitam
punar evābravīd vākyaṃ bharataṃ prati harṣitaḥ', null, 2079011),
('ramayana-2-79-12', 12, 'Ayodhya Kanda, Sarga 79, Verse 12', 'धन्यस्त्वं न त्वया तुल्यं पश्यामि जगतीतले।
अयत्नादागतं राज्यं यस्त्वं त्यक्तुमिहेच्छसि॥', 'dhanyas tvaṃ na tvayā tulyaṃ paśyāmi jagatītale
ayatnād āgataṃ rājyaṃ yas tvaṃ tyaktum ihecchasi', null, 2079012),
('ramayana-2-79-13', 13, 'Ayodhya Kanda, Sarga 79, Verse 13', 'शाश्वती खलु ते कीर्तिर्लोकाननुचरिष्यति।
यस्त्वं कृच्छ्रगतं रामं प्रत्यानयितुमिच्छसि॥', 'śāśvatī khalu te kīrtir lokān anucariṣyati
yas tvaṃ kṛcchragataṃ rāmaṃ pratyānayitum icchasi', null, 2079013),
('ramayana-2-79-14', 14, 'Ayodhya Kanda, Sarga 79, Verse 14', 'एवं संभाषमाणस्य गुहस्य भरतं तदा।
बभौ नष्टप्रभः सूर्यो रजनी चाभ्यवर्तत॥', 'evaṃ saṃbhāṣamāṇasya guhasya bharataṃ tadā
babhau naṣṭaprabhaḥ sūryo rajanī cābhyavartata', null, 2079014),
('ramayana-2-79-15', 15, 'Ayodhya Kanda, Sarga 79, Verse 15', 'संनिवेश्य स तां सेनां गुहेन परितोषितः।
शत्रुघ्नेन सह श्रीमाञ्शयनं पुनरागमत्॥', 'saṃniveśya sa tāṃ senāṃ guhena paritoṣitaḥ
śatrughnena saha śrīmāñ śayanaṃ punar āgamat', null, 2079015),
('ramayana-2-79-16', 16, 'Ayodhya Kanda, Sarga 79, Verse 16', 'रामचिन्तामयः शोको भरतस्य महात्मनः।
उपस्थितो ह्यनर्हस्य धर्मप्रेक्षस्य तादृशः॥', 'rāmacintāmayaḥ śoko bharatasya mahātmanaḥ
upasthito hy anarhasya dharmaprekṣasya tādṛśaḥ', null, 2079016),
('ramayana-2-79-17', 17, 'Ayodhya Kanda, Sarga 79, Verse 17', 'अन्तर्दाहेन दहनः संतापयति राघवम्।
वनदाहाभिसंतप्तं गूढोऽग्निरिव पादपम्॥', 'antardāhena dahanaḥ saṃtāpayati rāghavam
vanadāhābhisaṃtaptaṃ gūḍho ''gnir iva pādapam', null, 2079017),
('ramayana-2-79-18', 18, 'Ayodhya Kanda, Sarga 79, Verse 18', 'प्रस्रुतः सर्वगात्रेभ्यः स्वेदः शोकाग्निसंभवः।
यथा सूर्यांशुसंतप्तो हिमवान्प्रस्रुतो हिमम्॥', 'prasrutaḥ sarvagātrebhyaḥ svedaḥ śokāgnisaṃbhavaḥ
yathā sūryāṃśusaṃtapto himavān prasruto himam', null, 2079018),
('ramayana-2-79-19', 19, 'Ayodhya Kanda, Sarga 79, Verse 19', 'ध्याननिर्दरशैलेन विनिःश्वसितधातुना।
दैन्यपादपसंघेन शोकायासाधिशृङ्गिणा॥', 'dhyānanirdaraśailena viniḥśvasitadhātunā
dainyapādapasaṃghena śokāyāsādhiśṛṅgiṇā', null, 2079019),
('ramayana-2-79-20', 20, 'Ayodhya Kanda, Sarga 79, Verse 20', 'प्रमोहानन्तसत्त्वेन संतापौषधिवेणुना।
आक्रान्तो दुःखशैलेन महता कैकयीसुतः॥', 'pramohānantasattvena saṃtāpauṣadhiveṇunā
ākrānto duḥkhaśailena mahatā kaikayīsutaḥ', null, 2079020),
('ramayana-2-79-21', 21, 'Ayodhya Kanda, Sarga 79, Verse 21', 'गुहेन सार्धं भरतः समागतो महानुभावः सजनः समाहितः।
सुदुर्मनास्तं भरतं तदा पुनर्गुहः समाश्वासयदग्रजं प्रति॥', 'guhena sārdhaṃ bharataḥ samāgato mahānubhāvaḥ sajanaḥ samāhitaḥ
sudurmanās taṃ bharataṃ tadā punar guhaḥ samāśvāsayad agrajaṃ prati', null, 2079021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 80 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-80-1', 1, 'Ayodhya Kanda, Sarga 80, Verse 1', 'आचचक्षेऽथ सद्भावं लक्ष्मणस्य महात्मनः।
भरतायाप्रमेयाय गुहो गहनगोचरः॥', 'ācacakṣe ''tha sadbhāvaṃ lakṣmaṇasya mahātmanaḥ
bharatāyāprameyāya guho gahanagocaraḥ', null, 2080001),
('ramayana-2-80-2', 2, 'Ayodhya Kanda, Sarga 80, Verse 2', 'तं जाग्रतं गुणैर्युक्तं वरचापेषुधारिणम्।
भ्रातृ गुप्त्यर्थमत्यन्तमहं लक्ष्मणमब्रवम्॥', 'taṃ jāgrataṃ guṇair yuktaṃ varacāpeṣudhāriṇam
bhrātṛ guptyartham atyantam ahaṃ lakṣmaṇam abravam', null, 2080002),
('ramayana-2-80-3', 3, 'Ayodhya Kanda, Sarga 80, Verse 3', 'इयं तात सुखा शय्या त्वदर्थमुपकल्पिता।
प्रत्याश्वसिहि शेष्वास्यां सुखं राघवनन्दन॥', 'iyaṃ tāta sukhā śayyā tvadartham upakalpitā
pratyāśvasihi śeṣvāsyāṃ sukhaṃ rāghavanandana', null, 2080003),
('ramayana-2-80-4', 4, 'Ayodhya Kanda, Sarga 80, Verse 4', 'उचितोऽयं जनः सर्वे दुःखानां त्वं सुखोचितः।
धर्मात्मंस्तस्य गुप्त्यर्थं जागरिष्यामहे वयम्॥', 'ucito ''yaṃ janaḥ sarve duḥkhānāṃ tvaṃ sukhocitaḥ
dharmātmaṃs tasya guptyarthaṃ jāgariṣyāmahe vayam', null, 2080004),
('ramayana-2-80-5', 5, 'Ayodhya Kanda, Sarga 80, Verse 5', 'न हि रामात्प्रियतरो ममास्ति भुवि कश्चन।
मोत्सुको भूर्ब्रवीम्येतदप्यसत्यं तवाग्रतः॥', 'na hi rāmāt priyataro mamāsti bhuvi kaś cana
motsuko bhūr bravīmy etad apy asatyaṃ tavāgrataḥ', null, 2080005),
('ramayana-2-80-6', 6, 'Ayodhya Kanda, Sarga 80, Verse 6', 'अस्य प्रसादादाशंसे लोकेऽस्मिन्सुमहद्यशः।
धर्मावाप्तिं च विपुलामर्थावाप्तिं च केवलाम्॥', 'asya prasādād āśaṃse loke ''smin sumahad yaśaḥ
dharmāvāptiṃ ca vipulām arthāvāptiṃ ca kevalām', null, 2080006),
('ramayana-2-80-7', 7, 'Ayodhya Kanda, Sarga 80, Verse 7', 'सोऽहं प्रियसखं रामं शयानं सह सीतया।
रक्षिष्यामि धनुष्पाणिः सर्वैः स्वैर्ज्ञातिभिः सह॥', 'so ''haṃ priyasakhaṃ rāmaṃ śayānaṃ saha sītayā
rakṣiṣyāmi dhanuṣpāṇiḥ sarvaiḥ svair jñātibhiḥ saha', null, 2080007),
('ramayana-2-80-8', 8, 'Ayodhya Kanda, Sarga 80, Verse 8', 'न हि मेऽविदितं किं चिद्वनेऽस्मिंश्चरतः सदा।
चतुरङ्गं ह्यपि बलं प्रसहेम वयं युधि॥', 'na hi me ''viditaṃ kiṃ cid vane ''smiṃś carataḥ sadā
caturaṅgaṃ hy api balaṃ prasahema vayaṃ yudhi', null, 2080008),
('ramayana-2-80-9', 9, 'Ayodhya Kanda, Sarga 80, Verse 9', 'एवमस्माभिरुक्तेन लक्ष्मणेन महात्मना।
अनुनीता वयं सर्वे धर्ममेवानुपश्यता॥', 'evam asmābhir uktena lakṣmaṇena mahātmanā
anunītā vayaṃ sarve dharmam evānupaśyatā', null, 2080009),
('ramayana-2-80-10', 10, 'Ayodhya Kanda, Sarga 80, Verse 10', 'कथं दाशरथौ भूमौ शयाने सह सीतया।
शक्या निद्रामया लब्धुं जीवितं वा सुखानि वा॥', 'kathaṃ dāśarathau bhūmau śayāne saha sītayā
śakyā nidrāmayā labdhuṃ jīvitaṃ vā sukhāni vā', null, 2080010),
('ramayana-2-80-11', 11, 'Ayodhya Kanda, Sarga 80, Verse 11', 'यो न देवासुरैः सर्वैः शक्यः प्रसहितुं युधि।
तं पश्य गुह संविष्टं तृणेषु सह सीतया॥', 'yo na devāsuraiḥ sarvaiḥ śakyaḥ prasahituṃ yudhi
taṃ paśya guha saṃviṣṭaṃ tṛṇeṣu saha sītayā', null, 2080011),
('ramayana-2-80-12', 12, 'Ayodhya Kanda, Sarga 80, Verse 12', 'महता तपसा लब्धो विविधैश्च परिश्रमैः।
एको दशरथस्यैष पुत्रः सदृशलक्षणः॥', 'mahatā tapasā labdho vividhaiś ca pariśramaiḥ
eko daśarathasyaiṣa putraḥ sadṛśalakṣaṇaḥ', null, 2080012),
('ramayana-2-80-13', 13, 'Ayodhya Kanda, Sarga 80, Verse 13', 'अस्मिन्प्रव्राजिते राजा न चिरं वर्तयिष्यति।
विधवा मेदिनी नूनं क्षिप्रमेव भविष्यति॥', 'asmin pravrājite rājā na ciraṃ vartayiṣyati
vidhavā medinī nūnaṃ kṣipram eva bhaviṣyati', null, 2080013),
('ramayana-2-80-14', 14, 'Ayodhya Kanda, Sarga 80, Verse 14', 'विनद्य सुमहानादं श्रमेणोपरताः स्त्रियः।
निर्घोषोपरतं नूनमद्य राजनिवेशनम्॥', 'vinadya sumahānādaṃ śrameṇoparatāḥ striyaḥ
nirghoṣoparataṃ nūnam adya rājaniveśanam', null, 2080014),
('ramayana-2-80-15', 15, 'Ayodhya Kanda, Sarga 80, Verse 15', 'कौसल्या चैव राजा च तथैव जननी मम।
नाशंसे यदि ते सर्वे जीवेयुः शर्वरीमिमाम्॥', 'kausalyā caiva rājā ca tathaiva jananī mama
nāśaṃse yadi te sarve jīveyuḥ śarvarīm imām', null, 2080015),
('ramayana-2-80-16', 16, 'Ayodhya Kanda, Sarga 80, Verse 16', 'जीवेदपि हि मे माता शत्रुघ्नस्यान्ववेक्षया।
दुःखिता या तु कौसल्या वीरसूर्विनशिष्यति॥', 'jīved api hi me mātā śatrughnasyānvavekṣayā
duḥkhitā yā tu kausalyā vīrasūr vinaśiṣyati', null, 2080016),
('ramayana-2-80-17', 17, 'Ayodhya Kanda, Sarga 80, Verse 17', 'अतिक्रान्तमतिक्रान्तमनवाप्य मनोरथम्।
राज्ये राममनिक्षिप्य पिता मे विनशिष्यति॥', 'atikrāntam atikrāntam anavāpya manoratham
rājye rāmam anikṣipya pitā me vinaśiṣyati', null, 2080017),
('ramayana-2-80-18', 18, 'Ayodhya Kanda, Sarga 80, Verse 18', 'सिद्धार्थाः पितरं वृत्तं तस्मिन्काले ह्युपस्थिते।
प्रेतकार्येषु सर्वेषु संस्करिष्यन्ति भूमिपम्॥', 'siddhārthāḥ pitaraṃ vṛttaṃ tasmin kāle hy upasthite
pretakāryeṣu sarveṣu saṃskariṣyanti bhūmipam', null, 2080018),
('ramayana-2-80-19', 19, 'Ayodhya Kanda, Sarga 80, Verse 19', 'रम्यचत्वरसंस्थानां सुविभक्तमहापथाम्।
हर्म्यप्रासादसंपन्नां सर्वरत्नविभूषिताम्॥', 'ramyacatvarasaṃsthānāṃ suvibhaktamahāpathām
harmyaprāsādasaṃpannāṃ sarvaratnavibhūṣitām', null, 2080019),
('ramayana-2-80-20', 20, 'Ayodhya Kanda, Sarga 80, Verse 20', 'गजाश्वरथसंबाधां तूर्यनादविनादिताम्।
सर्वकल्याणसंपूर्णां हृष्टपुष्टजनाकुलाम्॥', 'gajāśvarathasaṃbādhāṃ tūryanādavināditām
sarvakalyāṇasaṃpūrṇāṃ hṛṣṭapuṣṭajanākulām', null, 2080020),
('ramayana-2-80-21', 21, 'Ayodhya Kanda, Sarga 80, Verse 21', 'आरामोद्यानसंपूर्णां समाजोत्सवशालिनीम्।
सुखिता विचरिष्यन्ति राजधानीं पितुर्मम॥', 'ārāmodyānasaṃpūrṇāṃ samājotsavaśālinīm
sukhitā vicariṣyanti rājadhānīṃ pitur mama', null, 2080021),
('ramayana-2-80-22', 22, 'Ayodhya Kanda, Sarga 80, Verse 22', 'अपि सत्यप्रतिज्ञेन सार्धं कुशलिना वयम्।
निवृत्ते समये ह्यस्मिन्सुखिताः प्रविशेमहि॥', 'api satyapratijñena sārdhaṃ kuśalinā vayam
nivṛtte samaye hy asmin sukhitāḥ praviśemahi', null, 2080022),
('ramayana-2-80-23', 23, 'Ayodhya Kanda, Sarga 80, Verse 23', 'परिदेवयमानस्य तस्यैवं सुमहात्मनः।
तिष्ठतो राजपुत्रस्य शर्वरी सात्यवर्तत॥', 'paridevayamānasya tasyaivaṃ sumahātmanaḥ
tiṣṭhato rājaputrasya śarvarī sātyavartata', null, 2080023),
('ramayana-2-80-24', 24, 'Ayodhya Kanda, Sarga 80, Verse 24', 'प्रभाते विमले सूर्ये कारयित्वा जटा उभौ।
अस्मिन्भागीरथीतीरे सुखं संतारितौ मया॥', 'prabhāte vimale sūrye kārayitvā jaṭā ubhau
asmin bhāgīrathītīre sukhaṃ saṃtāritau mayā', null, 2080024),
('ramayana-2-80-25', 25, 'Ayodhya Kanda, Sarga 80, Verse 25', 'जटाधरौ तौ द्रुमचीरवाससौ महाबलौ कुञ्जरयूथपोपमौ।
वरेषुचापासिधरौ परंतपौ व्यवेक्षमाणौ सह सीतया गतौ॥', 'jaṭādharau tau drumacīravāsasau mahābalau kuñjarayūthapopamau
vareṣucāpāsidharau paraṃtapau vyavekṣamāṇau saha sītayā gatau', null, 2080025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 81 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-81-1', 1, 'Ayodhya Kanda, Sarga 81, Verse 1', 'गुहस्य वचनं श्रुत्वा भरतो भृशमप्रियम्।
ध्यानं जगाम तत्रैव यत्र तच्छ्रुतमप्रियम्॥', 'guhasya vacanaṃ śrutvā bharato bhṛśam apriyam
dhyānaṃ jagāma tatraiva yatra tac chrutam apriyam', null, 2081001),
('ramayana-2-81-2', 2, 'Ayodhya Kanda, Sarga 81, Verse 2', 'सुकुमारो महासत्त्वः सिंहस्कन्धो महाभुजः।
पुण्डरीक विशालाक्षस्तरुणः प्रियदर्शनः॥', 'sukumāro mahāsattvaḥ siṃhaskandho mahābhujaḥ
puṇḍarīka viśālākṣas taruṇaḥ priyadarśanaḥ', null, 2081002),
('ramayana-2-81-3', 3, 'Ayodhya Kanda, Sarga 81, Verse 3', 'प्रत्याश्वस्य मुहूर्तं तु कालं परमदुर्मनाः।
पपात सहसा तोत्रैर्हृदि विद्ध इव द्विपः॥', 'pratyāśvasya muhūrtaṃ tu kālaṃ paramadurmanāḥ
papāta sahasā totrair hṛdi viddha iva dvipaḥ', null, 2081003),
('ramayana-2-81-4', 4, 'Ayodhya Kanda, Sarga 81, Verse 4', 'तदवस्थं तु भरतं शत्रुघ्नोऽनन्तर स्थितः।
परिष्वज्य रुरोदोच्चैर्विसंज्ञः शोककर्शितः॥', 'tadavasthaṃ tu bharataṃ śatrughno ''nantara sthitaḥ
pariṣvajya rurodoccair visaṃjñaḥ śokakarśitaḥ', null, 2081004),
('ramayana-2-81-5', 5, 'Ayodhya Kanda, Sarga 81, Verse 5', 'ततः सर्वाः समापेतुर्मातरो भरतस्य ताः।
उपवास कृशा दीना भर्तृव्यसनकर्शिताः॥', 'tataḥ sarvāḥ samāpetur mātaro bharatasya tāḥ
upavāsa kṛśā dīnā bhartṛvyasanakarśitāḥ', null, 2081005),
('ramayana-2-81-6', 6, 'Ayodhya Kanda, Sarga 81, Verse 6', 'ताश्च तं पतितं भूमौ रुदन्त्यः पर्यवारयन्।
कौसल्या त्वनुसृत्यैनं दुर्मनाः परिषस्वजे॥', 'tāś ca taṃ patitaṃ bhūmau rudantyaḥ paryavārayan
kausalyā tv anusṛtyainaṃ durmanāḥ pariṣasvaje', null, 2081006),
('ramayana-2-81-7', 7, 'Ayodhya Kanda, Sarga 81, Verse 7', 'वत्सला स्वं यथा वत्समुपगूह्य तपस्विनी।
परिपप्रच्छ भरतं रुदन्ती शोकलालसा॥', 'vatsalā svaṃ yathā vatsam upagūhya tapasvinī
paripapraccha bharataṃ rudantī śokalālasā', null, 2081007),
('ramayana-2-81-8', 8, 'Ayodhya Kanda, Sarga 81, Verse 8', 'पुत्रव्याधिर्न ते कच्चिच्छरीरं परिबाधते।
अद्य राजकुलस्यास्य त्वदधीनं हि जीवितम्॥', 'putravyādhir na te kaccic charīraṃ paribādhate
adya rājakulasyāsya tvadadhīnaṃ hi jīvitam', null, 2081008),
('ramayana-2-81-9', 9, 'Ayodhya Kanda, Sarga 81, Verse 9', 'त्वां दृष्ट्वा पुत्र जीवामि रामे सभ्रातृके गते।
वृत्ते दशरथे राज्ञि नाथ एकस्त्वमद्य नः॥', 'tvāṃ dṛṣṭvā putra jīvāmi rāme sabhrātṛke gate
vṛtte daśarathe rājñi nātha ekas tvam adya naḥ', null, 2081009),
('ramayana-2-81-10', 10, 'Ayodhya Kanda, Sarga 81, Verse 10', 'कच्चिन्न लक्ष्मणे पुत्र श्रुतं ते किं चिदप्रियम्।
पुत्र वा ह्येकपुत्रायाः सहभार्ये वनं गते॥', 'kaccin na lakṣmaṇe putra śrutaṃ te kiṃ cid apriyam
putra vā hy ekaputrāyāḥ sahabhārye vanaṃ gate', null, 2081010),
('ramayana-2-81-11', 11, 'Ayodhya Kanda, Sarga 81, Verse 11', 'स मुहूर्तं समाश्वस्य रुदन्नेव महायशाः।
कौसल्यां परिसान्त्व्येदं गुहं वचनमब्रवीत्॥', 'sa muhūrtaṃ samāśvasya rudann eva mahāyaśāḥ
kausalyāṃ parisāntvyedaṃ guhaṃ vacanam abravīt', null, 2081011),
('ramayana-2-81-12', 12, 'Ayodhya Kanda, Sarga 81, Verse 12', 'भ्राता मे क्वावसद्रात्रिं क्व सीता क्व च लक्ष्मणः।
अस्वपच्छयने कस्मिन्किं भुक्त्वा गुह शंस मे॥', 'bhrātā me kvāvasad rātriṃ kva sītā kva ca lakṣmaṇaḥ
asvapac chayane kasmin kiṃ bhuktvā guha śaṃsa me', null, 2081012),
('ramayana-2-81-13', 13, 'Ayodhya Kanda, Sarga 81, Verse 13', 'सोऽब्रवीद्भरतं पृष्टो निषादाधिपतिर्गुहः।
यद्विधं प्रतिपेदे च रामे प्रियहितेऽतिथौ॥', 'so ''bravīd bharataṃ pṛṣṭo niṣādādhipatir guhaḥ
yad vidhaṃ pratipede ca rāme priyahite ''tithau', null, 2081013),
('ramayana-2-81-14', 14, 'Ayodhya Kanda, Sarga 81, Verse 14', 'अन्नमुच्चावचं भक्ष्याः फलानि विविधानि च।
रामायाभ्यवहारार्थं बहुचोपहृतं मया॥', 'annam uccāvacaṃ bhakṣyāḥ phalāni vividhāni ca
rāmāyābhyavahārārthaṃ bahucopahṛtaṃ mayā', null, 2081014),
('ramayana-2-81-15', 15, 'Ayodhya Kanda, Sarga 81, Verse 15', 'तत्सर्वं प्रत्यनुज्ञासीद्रामः सत्यपराक्रमः।
न हि तत्प्रत्यगृह्णात्स क्षत्रधर्ममनुस्मरन्॥', 'tat sarvaṃ pratyanujñāsīd rāmaḥ satyaparākramaḥ
na hi tat pratyagṛhṇāt sa kṣatradharmam anusmaran', null, 2081015),
('ramayana-2-81-16', 16, 'Ayodhya Kanda, Sarga 81, Verse 16', 'न ह्यस्माभिः प्रतिग्राह्यं सखे देयं तु सर्वदा।
इति तेन वयं राजन्ननुनीता महात्मना॥', 'na hy asmābhiḥ pratigrāhyaṃ sakhe deyaṃ tu sarvadā
iti tena vayaṃ rājann anunītā mahātmanā', null, 2081016),
('ramayana-2-81-17', 17, 'Ayodhya Kanda, Sarga 81, Verse 17', 'लक्ष्मणेन समानीतं पीत्वा वारि महायशाः।
औपवास्यं तदाकार्षीद्राघवः सह सीतया॥', 'lakṣmaṇena samānītaṃ pītvā vāri mahāyaśāḥ
aupavāsyaṃ tadākārṣīd rāghavaḥ saha sītayā', null, 2081017),
('ramayana-2-81-18', 18, 'Ayodhya Kanda, Sarga 81, Verse 18', 'ततस्तु जलशेषेण लक्ष्मणोऽप्यकरोत्तदा।
वाग्यतास्ते त्रयः संध्यामुपासत समाहिताः॥', 'tatas tu jalaśeṣeṇa lakṣmaṇo ''py akarot tadā
vāg yatās te trayaḥ saṃdhyām upāsata samāhitāḥ', null, 2081018),
('ramayana-2-81-19', 19, 'Ayodhya Kanda, Sarga 81, Verse 19', 'सौमित्रिस्तु ततः पश्चादकरोत्स्वास्तरं शुभम्।
स्वयमानीय बर्हींषि क्षिप्रं राघव कारणात्॥', 'saumitris tu tataḥ paścād akarot svāstaraṃ śubham
svayam ānīya barhīṃṣi kṣipraṃ rāghava kāraṇāt', null, 2081019),
('ramayana-2-81-20', 20, 'Ayodhya Kanda, Sarga 81, Verse 20', 'तस्मिन्समाविशद्रामः स्वास्तरे सह सीतया।
प्रक्षाल्य च तयोः पादावपचक्राम लक्ष्मणः॥', 'tasmin samāviśad rāmaḥ svāstare saha sītayā
prakṣālya ca tayoḥ pādāv apacakrāma lakṣmaṇaḥ', null, 2081020),
('ramayana-2-81-21', 21, 'Ayodhya Kanda, Sarga 81, Verse 21', 'एतत्तदिङ्गुदीमूलमिदमेव च तत्तृणम्।
यस्मिन्रामश्च सीता च रात्रिं तां शयितावुभौ॥', 'etat tad iṅgudīmūlam idam eva ca tat tṛṇam
yasmin rāmaś ca sītā ca rātriṃ tāṃ śayitāv ubhau', null, 2081021),
('ramayana-2-81-22', 22, 'Ayodhya Kanda, Sarga 81, Verse 22', 'नियम्य पृष्ठे तु तलाङ्गुलित्रवाञ्शरैः सुपूर्णाविषुधी परंतपः।
महद्धनुः सज्यमुपोह्य लक्ष्मणो निशामतिष्ठत्परितोऽस्य केवलम्॥', 'niyamya pṛṣṭhe tu talāṅgulitravāñ śaraiḥ supūrṇāv iṣudhī paraṃtapaḥ
mahad dhanuḥ sajyam upohya lakṣmaṇo niśām atiṣṭhat parito ''sya kevalam', null, 2081022),
('ramayana-2-81-23', 23, 'Ayodhya Kanda, Sarga 81, Verse 23', 'ततस्त्वहं चोत्तमबाणचापधृक्स्थितोऽभवं तत्र स यत्र लक्ष्मणः।
अतन्द्रिभिर्ज्ञातिभिरात्तकार्मुकैर्महेन्द्रकल्पं परिपालयंस्तदा॥', 'tatas tv ahaṃ cottamabāṇacāpadhṛk sthito ''bhavaṃ tatra sa yatra lakṣmaṇaḥ
atandribhir jñātibhir āttakārmukair mahendrakalpaṃ paripālayaṃs tadā', null, 2081023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 82 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-82-1', 1, 'Ayodhya Kanda, Sarga 82, Verse 1', 'तच्छ्रुत्वा निपुणं सर्वं भरतः सह मन्त्रिभिः।
इङ्गुदीमूलमागम्य रामशय्यामवेक्ष्य ताम्॥', 'tac chrutvā nipuṇaṃ sarvaṃ bharataḥ saha mantribhiḥ
iṅgudīmūlam āgamya rāmaśayyām avekṣya tām', null, 2082001),
('ramayana-2-82-2', 2, 'Ayodhya Kanda, Sarga 82, Verse 2', 'अब्रवीज्जननीः सर्वा इह तेन महात्मना।
शर्वरी शयिता भूमाविदमस्य विमर्दितम्॥', 'abravīj jananīḥ sarvā iha tena mahātmanā
śarvarī śayitā bhūmāv idam asya vimarditam', null, 2082002),
('ramayana-2-82-3', 3, 'Ayodhya Kanda, Sarga 82, Verse 3', 'महाभागकुलीनेन महाभागेन धीमता।
जातो दशरथेनोर्व्यां न रामः स्वप्तुमर्हति॥', 'mahābhāgakulīnena mahābhāgena dhīmatā
jāto daśarathenorvyāṃ na rāmaḥ svaptum arhati', null, 2082003),
('ramayana-2-82-4', 4, 'Ayodhya Kanda, Sarga 82, Verse 4', 'अजिनोत्तरसंस्तीर्णे वरास्तरणसंचये।
शयित्वा पुरुषव्याघ्रः कथं शेते महीतले॥', 'ajinottarasaṃstīrṇe varāstaraṇasaṃcaye
śayitvā puruṣavyāghraḥ kathaṃ śete mahītale', null, 2082004),
('ramayana-2-82-5', 5, 'Ayodhya Kanda, Sarga 82, Verse 5', 'प्रासादाग्र विमानेषु वलभीषु च सर्वदा।
हैमराजतभौमेषु वरास्तरणशालिषु॥', 'prāsādāgra vimāneṣu valabhīṣu ca sarvadā
haimarājatabhaumeṣu varāstaraṇaśāliṣu', null, 2082005),
('ramayana-2-82-6', 6, 'Ayodhya Kanda, Sarga 82, Verse 6', 'पुष्पसंचयचित्रेषु चन्दनागरुगन्धिषु।
पाण्डुराभ्रप्रकाशेषु शुकसंघरुतेषु च॥', 'puṣpasaṃcayacitreṣu candanāgarugandhiṣu
pāṇḍurābhraprakāśeṣu śukasaṃgharuteṣu ca', null, 2082006),
('ramayana-2-82-7', 7, 'Ayodhya Kanda, Sarga 82, Verse 7', 'गीतवादित्रनिर्घोषैर्वराभरणनिःस्वनैः।
मृदङ्गवरशब्दैश्च सततं प्रतिबोधितः॥', 'gītavāditranirghoṣair varābharaṇaniḥsvanaiḥ
mṛdaṅgavaraśabdaiś ca satataṃ pratibodhitaḥ', null, 2082007),
('ramayana-2-82-8', 8, 'Ayodhya Kanda, Sarga 82, Verse 8', 'बन्दिभिर्वन्दितः काले बहुभिः सूतमागधैः।
गाथाभिरनुरूपाभिः स्तुतिभिश्च परंतपः॥', 'bandibhir vanditaḥ kāle bahubhiḥ sūtamāgadhaiḥ
gāthābhir anurūpābhiḥ stutibhiś ca paraṃtapaḥ', null, 2082008),
('ramayana-2-82-9', 9, 'Ayodhya Kanda, Sarga 82, Verse 9', 'अश्रद्धेयमिदं लोके न सत्यं प्रतिभाति मा।
मुह्यते खलु मे भावः स्वप्नोऽयमिति मे मतिः॥', 'aśraddheyam idaṃ loke na satyaṃ pratibhāti mā
muhyate khalu me bhāvaḥ svapno ''yam iti me matiḥ', null, 2082009),
('ramayana-2-82-10', 10, 'Ayodhya Kanda, Sarga 82, Verse 10', 'न नूनं दैवतं किं चित्कालेन बलवत्तरम्।
यत्र दाशरथी रामो भूमावेवं शयीत सः॥', 'na nūnaṃ daivataṃ kiṃ cit kālena balavattaram
yatra dāśarathī rāmo bhūmāv evaṃ śayīta saḥ', null, 2082010),
('ramayana-2-82-11', 11, 'Ayodhya Kanda, Sarga 82, Verse 11', 'विदेहराजस्य सुता सीता च प्रियदर्शना।
दयिता शयिता भूमौ स्नुषा दशरथस्य च॥', 'videharājasya sutā sītā ca priyadarśanā
dayitā śayitā bhūmau snuṣā daśarathasya ca', null, 2082011),
('ramayana-2-82-12', 12, 'Ayodhya Kanda, Sarga 82, Verse 12', 'इयं शय्या मम भ्रातुरिदं हि परिवर्तितम्।
स्थण्डिले कठिने सर्वं गात्रैर्विमृदितं तृणम्॥', 'iyaṃ śayyā mama bhrātur idaṃ hi parivartitam
sthaṇḍile kaṭhine sarvaṃ gātrair vimṛditaṃ tṛṇam', null, 2082012),
('ramayana-2-82-13', 13, 'Ayodhya Kanda, Sarga 82, Verse 13', 'मन्ये साभरणा सुप्ता सीतास्मिञ्शयने तदा।
तत्र तत्र हि दृश्यन्ते सक्ताः कनकबिन्दवः॥', 'manye sābharaṇā suptā sītāsmiñ śayane tadā
tatra tatra hi dṛśyante saktāḥ kanakabindavaḥ', null, 2082013),
('ramayana-2-82-14', 14, 'Ayodhya Kanda, Sarga 82, Verse 14', 'उत्तरीयमिहासक्तं सुव्यक्तं सीतया तदा।
तथा ह्येते प्रकाशन्ते सक्ताः कौशेयतन्तवः॥', 'uttarīyam ihāsaktaṃ suvyaktaṃ sītayā tadā
tathā hy ete prakāśante saktāḥ kauśeyatantavaḥ', null, 2082014),
('ramayana-2-82-15', 15, 'Ayodhya Kanda, Sarga 82, Verse 15', 'मन्ये भर्तुः सुखा शय्या येन बाला तपस्विनी।
सुकुमारी सती दुःखं न विजानाति मैथिली॥', 'manye bhartuḥ sukhā śayyā yena bālā tapasvinī
sukumārī satī duḥkhaṃ na vijānāti maithilī', null, 2082015),
('ramayana-2-82-16', 16, 'Ayodhya Kanda, Sarga 82, Verse 16', 'सार्वभौम कुले जातः सर्वलोकसुखावहः।
सर्वलोकप्रियस्त्यक्त्वा राज्यं प्रियमनुत्तमम्॥', 'sārvabhauma kule jātaḥ sarvalokasukhāvahaḥ
sarvalokapriyas tyaktvā rājyaṃ priyam anuttamam', null, 2082016),
('ramayana-2-82-17', 17, 'Ayodhya Kanda, Sarga 82, Verse 17', 'कथमिन्दीवरश्यामो रक्ताक्षः प्रियदर्शनः।
सुखभागी च दुःखार्हः शयितो भुवि राघवः॥', 'katham indīvaraśyāmo raktākṣaḥ priyadarśanaḥ
sukhabhāgī ca duḥkhārhaḥ śayito bhuvi rāghavaḥ', null, 2082017),
('ramayana-2-82-18', 18, 'Ayodhya Kanda, Sarga 82, Verse 18', 'सिद्धार्था खलु वैदेही पतिं यानुगता वनम्।
वयं संशयिताः सर्वे हीनास्तेन महात्मना॥', 'siddhārthā khalu vaidehī patiṃ yānugatā vanam
vayaṃ saṃśayitāḥ sarve hīnās tena mahātmanā', null, 2082018),
('ramayana-2-82-19', 19, 'Ayodhya Kanda, Sarga 82, Verse 19', 'अकर्णधारा पृथिवी शून्येव प्रतिभाति मा।
गते दशरथे स्वर्गे रामे चारण्यमाश्रिते॥', 'akarṇadhārā pṛthivī śūnyeva pratibhāti mā
gate daśarathe svarge rāme cāraṇyam āśrite', null, 2082019),
('ramayana-2-82-20', 20, 'Ayodhya Kanda, Sarga 82, Verse 20', 'न च प्रार्थयते कश्चिन्मनसापि वसुंधराम्।
वनेऽपि वसतस्तस्य बाहुवीर्याभिरक्षिताम्॥', 'na ca prārthayate kaś cin manasāpi vasuṃdharām
vane ''pi vasatas tasya bāhuvīryābhirakṣitām', null, 2082020),
('ramayana-2-82-21', 21, 'Ayodhya Kanda, Sarga 82, Verse 21', 'शून्यसंवरणारक्षामयन्त्रितहयद्विपाम्।
अपावृतपुरद्वारां राजधानीमरक्षिताम्॥', 'śūnyasaṃvaraṇārakṣām ayantritahayadvipām
apāvṛtapuradvārāṃ rājadhānīm arakṣitām', null, 2082021),
('ramayana-2-82-22', 22, 'Ayodhya Kanda, Sarga 82, Verse 22', 'अप्रहृष्टबलां न्यूनां विषमस्थामनावृताम्।
शत्रवो नाभिमन्यन्ते भक्ष्यान्विषकृतानिव॥', 'aprahṛṣṭabalāṃ nyūnāṃ viṣamasthām anāvṛtām
śatravo nābhimanyante bhakṣyān viṣakṛtān iva', null, 2082022),
('ramayana-2-82-23', 23, 'Ayodhya Kanda, Sarga 82, Verse 23', 'अद्य प्रभृति भूमौ तु शयिष्येऽहं तृणेषु वा।
फलमूलाशनो नित्यं जटाचीराणि धारयन्॥', 'adya prabhṛti bhūmau tu śayiṣye ''haṃ tṛṇeṣu vā
phalamūlāśano nityaṃ jaṭācīrāṇi dhārayan', null, 2082023),
('ramayana-2-82-24', 24, 'Ayodhya Kanda, Sarga 82, Verse 24', 'तस्यार्थमुत्तरं कालं निवत्स्यामि सुखं वने।
तं प्रतिश्रवमामुच्य नास्य मिथ्या भविष्यति॥', 'tasyārtham uttaraṃ kālaṃ nivatsyāmi sukhaṃ vane
taṃ pratiśravam āmucya nāsya mithyā bhaviṣyati', null, 2082024),
('ramayana-2-82-25', 25, 'Ayodhya Kanda, Sarga 82, Verse 25', 'वसन्तं भ्रातुरर्थाय शत्रुघ्नो मानुवत्स्यति।
लक्ष्मणेन सह त्वार्यो अयोध्यां पालयिष्यति॥', 'vasantaṃ bhrātur arthāya śatrughno mānuvatsyati
lakṣmaṇena saha tv āryo ayodhyāṃ pālayiṣyati', null, 2082025),
('ramayana-2-82-26', 26, 'Ayodhya Kanda, Sarga 82, Verse 26', 'अभिषेक्ष्यन्ति काकुत्स्थमयोध्यायां द्विजातयः।
अपि मे देवताः कुर्युरिमं सत्यं मनोरथम्॥', 'abhiṣekṣyanti kākutstham ayodhyāyāṃ dvijātayaḥ
api me devatāḥ kuryur imaṃ satyaṃ manoratham', null, 2082026),
('ramayana-2-82-27', 27, 'Ayodhya Kanda, Sarga 82, Verse 27', 'प्रसाद्यमानः शिरसा मया स्वयं बहुप्रकारं यदि न प्रपत्स्यते।
ततोऽनुवत्स्यामि चिराय राघवं वने वसन्नार्हति मामुपेक्षितुम्॥', 'prasādyamānaḥ śirasā mayā svayaṃ bahuprakāraṃ yadi na prapatsyate
tato ''nuvatsyāmi cirāya rāghavaṃ vane vasan nārhati mām upekṣitum', null, 2082027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 83 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-83-1', 1, 'Ayodhya Kanda, Sarga 83, Verse 1', 'व्युष्य रात्रिं तु तत्रैव गङ्गाकूले स राघवः।
भरतः काल्यमुत्थाय शत्रुघ्नमिदमब्रवीत्॥', 'vyuṣya rātriṃ tu tatraiva gaṅgākūle sa rāghavaḥ
bharataḥ kālyam utthāya śatrughnam idam abravīt', null, 2083001),
('ramayana-2-83-2', 2, 'Ayodhya Kanda, Sarga 83, Verse 2', 'शत्रुघोत्तिष्ठ किं शेषे निषादाधिपतिं गुहम्।
शीघ्रमानय भद्रं ते तारयिष्यति वाहिनीम्॥', 'śatrughottiṣṭha kiṃ śeṣe niṣādādhipatiṃ guham
śīghram ānaya bhadraṃ te tārayiṣyati vāhinīm', null, 2083002),
('ramayana-2-83-3', 3, 'Ayodhya Kanda, Sarga 83, Verse 3', 'जागर्मि नाहं स्वपिमि तथैवार्यं विचिन्तयन्।
इत्येवमब्रवीद्भ्रात्रा शत्रुघ्नोऽपि प्रचोदितः॥', 'jāgarmi nāhaṃ svapimi tathaivāryaṃ vicintayan
ity evam abravīd bhrātrā śatrughno ''pi pracoditaḥ', null, 2083003),
('ramayana-2-83-4', 4, 'Ayodhya Kanda, Sarga 83, Verse 4', 'इति संवदतोरेवमन्योन्यं नरसिंहयोः।
आगम्य प्राञ्जलिः काले गुहो भरतमब्रवीत्॥', 'iti saṃvadator evam anyonyaṃ narasiṃhayoḥ
āgamya prāñjaliḥ kāle guho bharatam abravīt', null, 2083004),
('ramayana-2-83-5', 5, 'Ayodhya Kanda, Sarga 83, Verse 5', 'कच्चित्सुखं नदीतीरेऽवात्सीः काकुत्स्थ शर्वरीम्।
कच्चिच्च सह सैन्यस्य तव सर्वमनामयम्॥', 'kaccit sukhaṃ nadītīre ''vātsīḥ kākutstha śarvarīm
kaccic ca saha sainyasya tava sarvam anāmayam', null, 2083005),
('ramayana-2-83-6', 6, 'Ayodhya Kanda, Sarga 83, Verse 6', 'गुहस्य तत्तु वचनं श्रुत्वा स्नेहादुदीरितम्।
रामस्यानुवशो वाक्यं भरतोऽपीदमब्रवीत्॥', 'guhasya tat tu vacanaṃ śrutvā snehād udīritam
rāmasyānuvaśo vākyaṃ bharato ''pīdam abravīt', null, 2083006),
('ramayana-2-83-7', 7, 'Ayodhya Kanda, Sarga 83, Verse 7', 'सुखा नः शर्वरी राजन्पूजिताश्चापि ते वयम्।
गङ्गां तु नौभिर्बह्वीभिर्दाशाः संतारयन्तु नः॥', 'sukhā naḥ śarvarī rājan pūjitāś cāpi te vayam
gaṅgāṃ tu naubhir bahvībhir dāśāḥ saṃtārayantu naḥ', null, 2083007),
('ramayana-2-83-8', 8, 'Ayodhya Kanda, Sarga 83, Verse 8', 'ततो गुहः संत्वरितः श्रुत्वा भरतशासनम्।
प्रतिप्रविश्य नगरं तं ज्ञातिजनमब्रवीत्॥', 'tato guhaḥ saṃtvaritaḥ śrutvā bharataśāsanam
pratipraviśya nagaraṃ taṃ jñātijanam abravīt', null, 2083008),
('ramayana-2-83-9', 9, 'Ayodhya Kanda, Sarga 83, Verse 9', 'उत्तिष्ठत प्रबुध्यध्वं भद्रमस्तु हि वः सदा।
नावः समनुकर्षध्वं तारयिष्याम वाहिनीम्॥', 'uttiṣṭhata prabudhyadhvaṃ bhadram astu hi vaḥ sadā
nāvaḥ samanukarṣadhvaṃ tārayiṣyāma vāhinīm', null, 2083009),
('ramayana-2-83-10', 10, 'Ayodhya Kanda, Sarga 83, Verse 10', 'ते तथोक्ताः समुत्थाय त्वरिता राजशासनात्।
पञ्च नावां शतान्येव समानिन्युः समन्ततः॥', 'te tathoktāḥ samutthāya tvaritā rājaśāsanāt
pañca nāvāṃ śatāny eva samāninyuḥ samantataḥ', null, 2083010),
('ramayana-2-83-11', 11, 'Ayodhya Kanda, Sarga 83, Verse 11', 'अन्याः स्वस्तिकविज्ञेया महाघण्डा धरा वराः।
शोभमानाः पताकिन्यो युक्तवाताः सुसंहताः॥', 'anyāḥ svastikavijñeyā mahāghaṇḍā dharā varāḥ
śobhamānāḥ patākinyo yuktavātāḥ susaṃhatāḥ', null, 2083011),
('ramayana-2-83-12', 12, 'Ayodhya Kanda, Sarga 83, Verse 12', 'ततः स्वस्तिकविज्ञेयां पाण्डुकम्बलसंवृताम्।
सनन्दिघोषां कल्याणीं गुहो नावमुपाहरत्॥', 'tataḥ svastikavijñeyāṃ pāṇḍukambalasaṃvṛtām
sanandighoṣāṃ kalyāṇīṃ guho nāvam upāharat', null, 2083012),
('ramayana-2-83-13', 13, 'Ayodhya Kanda, Sarga 83, Verse 13', 'तामारुरोह भरतः शत्रुघ्नश्च महाबलः।
कौसल्या च सुमित्रा च याश्चान्या राजयोषितः॥', 'tām āruroha bharataḥ śatrughnaś ca mahābalaḥ
kausalyā ca sumitrā ca yāś cānyā rājayoṣitaḥ', null, 2083013),
('ramayana-2-83-14', 14, 'Ayodhya Kanda, Sarga 83, Verse 14', 'पुरोहितश्च तत्पूर्वं गुरवे ब्राह्मणाश्च ये।
अनन्तरं राजदारास्तथैव शकटापणाः॥', 'purohitaś ca tat pūrvaṃ gurave brāhmaṇāś ca ye
anantaraṃ rājadārās tathaiva śakaṭāpaṇāḥ', null, 2083014),
('ramayana-2-83-15', 15, 'Ayodhya Kanda, Sarga 83, Verse 15', 'आवासमादीपयतां तीर्थं चाप्यवगाहताम्।
भाण्डानि चाददानानां घोषस्त्रिदिवमस्पृशत्॥', 'āvāsam ādīpayatāṃ tīrthaṃ cāpy avagāhatām
bhāṇḍāni cādadānānāṃ ghoṣas tridivam aspṛśat', null, 2083015),
('ramayana-2-83-16', 16, 'Ayodhya Kanda, Sarga 83, Verse 16', 'पताकिन्यस्तु ता नावः स्वयं दाशैरधिष्ठिताः।
वहन्त्यो जनमारूढं तदा संपेतुराशुगाः॥', 'patākinyas tu tā nāvaḥ svayaṃ dāśair adhiṣṭhitāḥ
vahantyo janam ārūḍhaṃ tadā saṃpetur āśugāḥ', null, 2083016),
('ramayana-2-83-17', 17, 'Ayodhya Kanda, Sarga 83, Verse 17', 'नारीणामभिपूर्णास्तु काश्चित्काश्चित्तु वाजिनाम्।
कश्चित्तत्र वहन्ति स्म यानयुग्यं महाधनम्॥', 'nārīṇām abhipūrṇās tu kāś cit kāś cit tu vājinām
kaś cit tatra vahanti sma yānayugyaṃ mahādhanam', null, 2083017),
('ramayana-2-83-18', 18, 'Ayodhya Kanda, Sarga 83, Verse 18', 'ताः स्म गत्वा परं तीरमवरोप्य च तं जनम्।
निवृत्ताः काण्डचित्राणि क्रियन्ते दाशबन्धुभिः॥', 'tāḥ sma gatvā paraṃ tīram avaropya ca taṃ janam
nivṛttāḥ kāṇḍacitrāṇi kriyante dāśabandhubhiḥ', null, 2083018),
('ramayana-2-83-19', 19, 'Ayodhya Kanda, Sarga 83, Verse 19', 'सवैजयन्तास्तु गजा गजारोहैः प्रचोदिताः।
तरन्तः स्म प्रकाशन्ते सध्वजा इव पर्वताः॥', 'savaijayantās tu gajā gajārohaiḥ pracoditāḥ
tarantaḥ sma prakāśante sadhvajā iva parvatāḥ', null, 2083019),
('ramayana-2-83-20', 20, 'Ayodhya Kanda, Sarga 83, Verse 20', 'नावश्चारुरुहुस्त्वन्ये प्लवैस्तेरुस्तथापरे।
अन्ये कुम्भघटैस्तेरुरन्ये तेरुश्च बाहुभिः॥', 'nāvaś cāruruhus tv anye plavais terus tathāpare
anye kumbhaghaṭais terur anye teruś ca bāhubhiḥ', null, 2083020),
('ramayana-2-83-21', 21, 'Ayodhya Kanda, Sarga 83, Verse 21', 'सा पुण्या ध्वजिनी गङ्गां दाशैः संतारिता स्वयम्।
मैत्रे मुहूर्ते प्रययौ प्रयागवनमुत्तमम्॥', 'sā puṇyā dhvajinī gaṅgāṃ dāśaiḥ saṃtāritā svayam
maitre muhūrte prayayau prayāgavanam uttamam', null, 2083021),
('ramayana-2-83-22', 22, 'Ayodhya Kanda, Sarga 83, Verse 22', 'आश्वासयित्वा च चमूं महात्मा निवेशयित्वा च यथोपजोषम्।
द्रष्टुं भरद्वाजमृषिप्रवर्यमृत्विग्वृतः सन्भरतः प्रतस्थे॥', 'āśvāsayitvā ca camūṃ mahātmā niveśayitvā ca yathopajoṣam
draṣṭuṃ bharadvājam ṛṣipravaryam ṛtvig vṛtaḥ san bharataḥ pratasthe', null, 2083022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 84 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-84-1', 1, 'Ayodhya Kanda, Sarga 84, Verse 1', 'भरद्वाजाश्रमं दृष्ट्वा क्रोशादेव नरर्षभः।
बलं सर्वमवस्थाप्य जगाम सह मन्त्रिभिः॥', 'bharadvājāśramaṃ dṛṣṭvā krośād eva nararṣabhaḥ
balaṃ sarvam avasthāpya jagāma saha mantribhiḥ', null, 2084001),
('ramayana-2-84-2', 2, 'Ayodhya Kanda, Sarga 84, Verse 2', 'पद्भ्यामेव हि धर्मज्ञो न्यस्तशस्त्रपरिच्छदः।
वसानो वाससी क्षौमे पुरोधाय पुरोहितम्॥', 'padbhyām eva hi dharmajño nyastaśastraparicchadaḥ
vasāno vāsasī kṣaume purodhāya purohitam', null, 2084002),
('ramayana-2-84-3', 3, 'Ayodhya Kanda, Sarga 84, Verse 3', 'ततः संदर्शने तस्य भरद्वाजस्य राघवः।
मन्त्रिणस्तानवस्थाप्य जगामानु पुरोहितम्॥', 'tataḥ saṃdarśane tasya bharadvājasya rāghavaḥ
mantriṇas tān avasthāpya jagāmānu purohitam', null, 2084003),
('ramayana-2-84-4', 4, 'Ayodhya Kanda, Sarga 84, Verse 4', 'वसिष्ठमथ दृष्ट्वैव भरद्वाजो महातपाः।
संचचालासनात्तूर्णं शिष्यानर्घ्यमिति ब्रुवन्॥', 'vasiṣṭham atha dṛṣṭvaiva bharadvājo mahātapāḥ
saṃcacālāsanāt tūrṇaṃ śiṣyān arghyam iti bruvan', null, 2084004),
('ramayana-2-84-5', 5, 'Ayodhya Kanda, Sarga 84, Verse 5', 'समागम्य वसिष्ठेन भरतेनाभिवादितः।
अबुध्यत महातेजाः सुतं दशरथस्य तम्॥', 'samāgamya vasiṣṭhena bharatenābhivāditaḥ
abudhyata mahātejāḥ sutaṃ daśarathasya tam', null, 2084005),
('ramayana-2-84-6', 6, 'Ayodhya Kanda, Sarga 84, Verse 6', 'ताभ्यामर्घ्यं च पाद्यं च दत्त्वा पश्चात्फलानि च।
आनुपूर्व्याच्च धर्मज्ञः पप्रच्छ कुशलं कुले॥', 'tābhyām arghyaṃ ca pādyaṃ ca dattvā paścāt phalāni ca
ānupūrvyāc ca dharmajñaḥ papraccha kuśalaṃ kule', null, 2084006),
('ramayana-2-84-7', 7, 'Ayodhya Kanda, Sarga 84, Verse 7', 'अयोध्यायां बले कोशे मित्रेष्वपि च मन्त्रिषु।
जानन्दशरथं वृत्तं न राजानमुदाहरत्॥', 'ayodhyāyāṃ bale kośe mitreṣv api ca mantriṣu
jānan daśarathaṃ vṛttaṃ na rājānam udāharat', null, 2084007),
('ramayana-2-84-8', 8, 'Ayodhya Kanda, Sarga 84, Verse 8', 'वसिष्ठो भरतश्चैनं पप्रच्छतुरनामयम्।
शरीरेऽग्निषु वृक्षेषु शिष्येषु मृगपक्षिषु॥', 'vasiṣṭho bharataś cainaṃ papracchatur anāmayam
śarīre ''gniṣu vṛkṣeṣu śiṣyeṣu mṛgapakṣiṣu', null, 2084008),
('ramayana-2-84-9', 9, 'Ayodhya Kanda, Sarga 84, Verse 9', 'तथेति च प्रतिज्ञाय भरद्वाजो महातपाः।
भरतं प्रत्युवाचेदं राघवस्नेहबन्धनात्॥', 'tatheti ca pratijñāya bharadvājo mahātapāḥ
bharataṃ pratyuvācedaṃ rāghavasnehabandhanāt', null, 2084009),
('ramayana-2-84-10', 10, 'Ayodhya Kanda, Sarga 84, Verse 10', 'किमिहागमने कार्यं तव राज्यं प्रशासतः।
एतदाचक्ष्व मे सर्वं न हि मे शुध्यते मनः॥', 'kim ihāgamane kāryaṃ tava rājyaṃ praśāsataḥ
etad ācakṣva me sarvaṃ na hi me śudhyate manaḥ', null, 2084010),
('ramayana-2-84-11', 11, 'Ayodhya Kanda, Sarga 84, Verse 11', 'सुषुवे यम मित्रघ्नं कौसल्यानन्दवर्धनम्।
भ्रात्रा सह सभार्यो यश्चिरं प्रव्राजितो वनम्॥', 'suṣuve yama mitraghnaṃ kausalyānandavardhanam
bhrātrā saha sabhāryo yaś ciraṃ pravrājito vanam', null, 2084011),
('ramayana-2-84-12', 12, 'Ayodhya Kanda, Sarga 84, Verse 12', 'नियुक्तः स्त्रीनियुक्तेन पित्रा योऽसौ महायशाः।
वनवासी भवेतीह समाः किल चतुर्दश॥', 'niyuktaḥ strīniyuktena pitrā yo ''sau mahāyaśāḥ
vanavāsī bhavetīha samāḥ kila caturdaśa', null, 2084012),
('ramayana-2-84-13', 13, 'Ayodhya Kanda, Sarga 84, Verse 13', 'कच्चिन्न तस्यापापस्य पापं कर्तुमिहेच्छसि।
अकण्टकं भोक्तुमना राज्यं तस्यानुजस्य च॥', 'kaccin na tasyāpāpasya pāpaṃ kartum ihecchasi
akaṇṭakaṃ bhoktumanā rājyaṃ tasyānujasya ca', null, 2084013),
('ramayana-2-84-14', 14, 'Ayodhya Kanda, Sarga 84, Verse 14', 'एवमुक्तो भरद्वाजं भरतः प्रत्युवाच ह।
पर्यश्रु नयनो दुःखाद्वाचा संसज्जमानया॥', 'evam ukto bharadvājaṃ bharataḥ pratyuvāca ha
paryaśru nayano duḥkhād vācā saṃsajjamānayā', null, 2084014),
('ramayana-2-84-15', 15, 'Ayodhya Kanda, Sarga 84, Verse 15', 'हतोऽस्मि यदि मामेवं भगवानपि मन्यते।
मत्तो न दोषमाशङ्केर्नैवं मामनुशाधि हि॥', 'hato ''smi yadi mām evaṃ bhagavān api manyate
matto na doṣam āśaṅker naivaṃ mām anuśādhi hi', null, 2084015),
('ramayana-2-84-16', 16, 'Ayodhya Kanda, Sarga 84, Verse 16', 'न चैतदिष्टं माता मे यदवोचन्मदन्तरे।
नाहमेतेन तुष्टश्च न तद्वचनमाददे॥', 'na caitad iṣṭaṃ mātā me yad avocan madantare
nāham etena tuṣṭaś ca na tad vacanam ādade', null, 2084016),
('ramayana-2-84-17', 17, 'Ayodhya Kanda, Sarga 84, Verse 17', 'अहं तु तं नरव्याघ्रमुपयातः प्रसादकः।
प्रतिनेतुमयोध्यां च पादौ तस्याभिवन्दितुम्॥', 'ahaṃ tu taṃ naravyāghram upayātaḥ prasādakaḥ
pratinetum ayodhyāṃ ca pādau tasyābhivanditum', null, 2084017),
('ramayana-2-84-18', 18, 'Ayodhya Kanda, Sarga 84, Verse 18', 'त्वं मामेवंगतं मत्वा प्रसादं कर्तुमर्हसि।
शंस मे भगवन्रामः क्व संप्रति महीपतिः॥', 'tvaṃ mām evaṃgataṃ matvā prasādaṃ kartum arhasi
śaṃsa me bhagavan rāmaḥ kva saṃprati mahīpatiḥ', null, 2084018),
('ramayana-2-84-19', 19, 'Ayodhya Kanda, Sarga 84, Verse 19', 'उवाच तं भरद्वाजः प्रसादाद्भरतं वचः।
त्वय्येतत्पुरुषव्याघ्र युक्तं राघववंशजे।
गुरुवृत्तिर्दमश्चैव साधूनां चानुयायिता॥', 'uvāca taṃ bharadvājaḥ prasādād bharataṃ vacaḥ
tvayy etat puruṣavyāghra yuktaṃ rāghavavaṃśaje
guruvṛttir damaś caiva sādhūnāṃ cānuyāyitā', null, 2084019),
('ramayana-2-84-20', 20, 'Ayodhya Kanda, Sarga 84, Verse 20', 'जाने चैतन्मनःस्थं ते दृढीकरणमस्त्विति।
अपृच्छं त्वां तवात्यर्थं कीर्तिं समभिवर्धयन्॥', 'jāne caitan manaḥsthaṃ te dṛḍhīkaraṇam astv iti
apṛcchaṃ tvāṃ tavātyarthaṃ kīrtiṃ samabhivardhayan', null, 2084020),
('ramayana-2-84-21', 21, 'Ayodhya Kanda, Sarga 84, Verse 21', 'असौ वसति ते भ्राता चित्रकूटे महागिरौ।
श्वस्तु गन्तासि तं देशं वसाद्य सह मन्त्रिभिः।
एतं मे कुरु सुप्राज्ञ कामं कामार्थकोविद॥', 'asau vasati te bhrātā citrakūṭe mahāgirau
śvas tu gantāsi taṃ deśaṃ vasādya saha mantribhiḥ
etaṃ me kuru suprājña kāmaṃ kāmārthakovida', null, 2084021),
('ramayana-2-84-22', 22, 'Ayodhya Kanda, Sarga 84, Verse 22', 'ततस्तथेत्येवमुदारदर्शनः प्रतीतरूपो भरतोऽब्रवीद्वचः।
चकार बुद्धिं च तदा महाश्रमे निशानिवासाय नराधिपात्मजः॥', 'tatas tathety evam udāradarśanaḥ pratītarūpo bharato ''bravīd vacaḥ
cakāra buddhiṃ ca tadā mahāśrame niśānivāsāya narādhipātmajaḥ', null, 2084022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 85 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-85-1', 1, 'Ayodhya Kanda, Sarga 85, Verse 1', 'कृतबुद्धिं निवासाय तथैव स मुनिस्तदा।
भरतं कैकयी पुत्रमातिथ्येन न्यमन्त्रयत्॥', 'kṛtabuddhiṃ nivāsāya tathaiva sa munis tadā
bharataṃ kaikayī putram ātithyena nyamantrayat', null, 2085001),
('ramayana-2-85-2', 2, 'Ayodhya Kanda, Sarga 85, Verse 2', 'अब्रवीद्भरतस्त्वेनं नन्विदं भवता कृतम्।
पाद्यमर्घ्यं तथातिथ्यं वने यदूपपद्यते॥', 'abravīd bharatas tv enaṃ nanv idaṃ bhavatā kṛtam
pādyam arghyaṃ tathātithyaṃ vane yad ūpapadyate', null, 2085002),
('ramayana-2-85-3', 3, 'Ayodhya Kanda, Sarga 85, Verse 3', 'अथोवाच भरद्वाजो भरतं प्रहसन्निव।
जाने त्वां प्रीति संयुक्तं तुष्येस्त्वं येन केन चित्॥', 'athovāca bharadvājo bharataṃ prahasann iva
jāne tvāṃ prīti saṃyuktaṃ tuṣyes tvaṃ yena kena cit', null, 2085003),
('ramayana-2-85-4', 4, 'Ayodhya Kanda, Sarga 85, Verse 4', 'सेनायास्तु तवैतस्याः कर्तुमिच्छामि भोजनम्।
मम प्रितिर्यथा रूपा त्वमर्हो मनुजर्षभ॥', 'senāyās tu tavaitasyāḥ kartum icchāmi bhojanam
mama pritir yathā rūpā tvam arho manujarṣabha', null, 2085004),
('ramayana-2-85-5', 5, 'Ayodhya Kanda, Sarga 85, Verse 5', 'किमर्थं चापि निक्षिप्य दूरे बलमिहागतः।
कस्मान्नेहोपयातोऽसि सबलः पुरुषर्षभ॥', 'kimarthaṃ cāpi nikṣipya dūre balam ihāgataḥ
kasmān nehopayāto ''si sabalaḥ puruṣarṣabha', null, 2085005),
('ramayana-2-85-6', 6, 'Ayodhya Kanda, Sarga 85, Verse 6', 'भरतः प्रत्युवाचेदं प्राञ्जलिस्तं तपोधनम्।
ससैन्यो नोपयातोऽस्मि भगवन्भगवद्भयात्॥', 'bharataḥ pratyuvācedaṃ prāñjalis taṃ tapodhanam
sasainyo nopayāto ''smi bhagavan bhagavad bhayāt', null, 2085006),
('ramayana-2-85-7', 7, 'Ayodhya Kanda, Sarga 85, Verse 7', 'वाजि मुख्या मनुष्याश्च मत्ताश्च वर वारणाः।
प्रच्छाद्य महतीं भूमिं भगवन्ननुयान्ति माम्॥', 'vāji mukhyā manuṣyāś ca mattāś ca vara vāraṇāḥ
pracchādya mahatīṃ bhūmiṃ bhagavann anuyānti mām', null, 2085007),
('ramayana-2-85-8', 8, 'Ayodhya Kanda, Sarga 85, Verse 8', 'ते वृक्षानुदकं भूमिमाश्रमेषूटजांस्तथा।
न हिंस्युरिति तेनाहमेक एवागतस्ततः॥', 'te vṛkṣān udakaṃ bhūmim āśrameṣūṭajāṃs tathā
na hiṃsyur iti tenāham eka evāgatas tataḥ', null, 2085008),
('ramayana-2-85-9', 9, 'Ayodhya Kanda, Sarga 85, Verse 9', 'आनीयतामितः सेनेत्याज्ञप्तः परमर्षिणा।
तथा तु चक्रे भरतः सेनायाः समुपागमम्॥', 'ānīyatām itaḥ senety ājñaptaḥ paramarṣiṇā
tathā tu cakre bharataḥ senāyāḥ samupāgamam', null, 2085009),
('ramayana-2-85-10', 10, 'Ayodhya Kanda, Sarga 85, Verse 10', 'अग्निशालां प्रविश्याथ पीत्वापः परिमृज्य च।
आतिथ्यस्य क्रियाहेतोर्विश्वकर्माणमाह्वयत्॥', 'agniśālāṃ praviśyātha pītvāpaḥ parimṛjya ca
ātithyasya kriyāhetor viśvakarmāṇam āhvayat', null, 2085010),
('ramayana-2-85-11', 11, 'Ayodhya Kanda, Sarga 85, Verse 11', 'आह्वये विश्वकर्माणमहं त्वष्टारमेव च।
आतिथ्यं कर्तुमिच्छामि तत्र मे संविधीयताम्॥', 'āhvaye viśvakarmāṇam ahaṃ tvaṣṭāram eva ca
ātithyaṃ kartum icchāmi tatra me saṃvidhīyatām', null, 2085011),
('ramayana-2-85-12', 12, 'Ayodhya Kanda, Sarga 85, Verse 12', 'प्राक्स्रोतसश्च या नद्यः प्रत्यक्स्रोतस एव च।
पृथिव्यामन्तरिक्षे च समायान्त्वद्य सर्वशः॥', 'prāk srotasaś ca yā nadyaḥ pratyak srotasa eva ca
pṛthivyām antarikṣe ca samāyāntv adya sarvaśaḥ', null, 2085012),
('ramayana-2-85-13', 13, 'Ayodhya Kanda, Sarga 85, Verse 13', 'अन्याः स्रवन्तु मैरेयं सुरामन्याः सुनिष्ठिताम्।
अपराश्चोदकं शीतमिक्षुकाण्डरसोपमम्॥', 'anyāḥ sravantu maireyaṃ surām anyāḥ suniṣṭhitām
aparāś codakaṃ śītam ikṣukāṇḍarasopamam', null, 2085013),
('ramayana-2-85-14', 14, 'Ayodhya Kanda, Sarga 85, Verse 14', 'आह्वये देवगन्धर्वान्विश्वावसुहहाहुहून्।
तथैवाप्सरसो देवीर्गन्धर्वीश्चापि सर्वशः॥', 'āhvaye devagandharvān viśvāvasuhahāhuhūn
tathaivāpsaraso devīr gandharvīś cāpi sarvaśaḥ', null, 2085014),
('ramayana-2-85-15', 15, 'Ayodhya Kanda, Sarga 85, Verse 15', 'घृताचीमथ विश्वाचीं मिश्रकेशीमलम्बुसाम्।
शक्रं याश्चोपतिष्ठन्ति ब्रह्माणं याश्च भामिनीः।
सर्वास्तुम्बुरुणा सार्धमाह्वये सपरिच्छदाः॥', 'ghṛtācīm atha viśvācīṃ miśrakeśīm alambusām
śakraṃ yāś copatiṣṭhanti brahmāṇaṃ yāś ca bhāminīḥ
sarvās tumburuṇā sārdham āhvaye saparicchadāḥ', null, 2085015),
('ramayana-2-85-16', 16, 'Ayodhya Kanda, Sarga 85, Verse 16', 'वनं कुरुषु यद्दिव्यं वासो भूषणपत्रवत्।
दिव्यनारीफलं शश्वत्तत्कौबेरमिहैव तु॥', 'vanaṃ kuruṣu yad divyaṃ vāso bhūṣaṇapatravat
divyanārīphalaṃ śaśvat tat kauberam ihaiva tu', null, 2085016),
('ramayana-2-85-17', 17, 'Ayodhya Kanda, Sarga 85, Verse 17', 'इह मे भगवान्सोमो विधत्तामन्नमुत्तमम्।
भक्ष्यं भोज्यं च चोष्यं च लेह्यं च विविधं बहु॥', 'iha me bhagavān somo vidhattām annam uttamam
bhakṣyaṃ bhojyaṃ ca coṣyaṃ ca lehyaṃ ca vividhaṃ bahu', null, 2085017),
('ramayana-2-85-18', 18, 'Ayodhya Kanda, Sarga 85, Verse 18', 'विचित्राणि च माल्यानि पादपप्रच्युतानि च।
सुरादीनि च पेयानि मांसानि विविधानि च॥', 'vicitrāṇi ca mālyāni pādapapracyutāni ca
surādīni ca peyāni māṃsāni vividhāni ca', null, 2085018),
('ramayana-2-85-19', 19, 'Ayodhya Kanda, Sarga 85, Verse 19', 'एवं समाधिना युक्तस्तेजसाप्रतिमेन च।
शिक्षास्वरसमायुक्तं तपसा चाब्रवीन्मुनिः॥', 'evaṃ samādhinā yuktas tejasāpratimena ca
śikṣāsvarasamāyuktaṃ tapasā cābravīn muniḥ', null, 2085019),
('ramayana-2-85-20', 20, 'Ayodhya Kanda, Sarga 85, Verse 20', 'मनसा ध्यायतस्तस्य प्राङ्मुखस्य कृताञ्जलेः।
आजग्मुस्तानि सर्वाणि दैवतानि पृथक्पृथक्॥', 'manasā dhyāyatas tasya prāṅmukhasya kṛtāñjaleḥ
ājagmus tāni sarvāṇi daivatāni pṛthakpṛthak', null, 2085020),
('ramayana-2-85-21', 21, 'Ayodhya Kanda, Sarga 85, Verse 21', 'मलयं दुर्दुरं चैव ततः स्वेदनुदोऽनिलः।
उपस्पृश्य ववौ युक्त्या सुप्रियात्मा सुखः शिवः॥', 'malayaṃ durduraṃ caiva tataḥ svedanudo ''nilaḥ
upaspṛśya vavau yuktyā supriyātmā sukhaḥ śivaḥ', null, 2085021),
('ramayana-2-85-22', 22, 'Ayodhya Kanda, Sarga 85, Verse 22', 'ततोऽभ्यवर्तन्त घना दिव्याः कुसुमवृष्टयः।
देवदुन्दुभिघोषश्च दिक्षु सर्वासु शुश्रुवे॥', 'tato ''bhyavartanta ghanā divyāḥ kusumavṛṣṭayaḥ
devadundubhighoṣaś ca dikṣu sarvāsu śuśruve', null, 2085022),
('ramayana-2-85-23', 23, 'Ayodhya Kanda, Sarga 85, Verse 23', 'प्रववुश्चोत्तमा वाता ननृतुश्चाप्सरोगणाः।
प्रजगुर्देवगन्धर्वा वीणा प्रमुमुचुः स्वरान्॥', 'pravavuś cottamā vātā nanṛtuś cāpsarogaṇāḥ
prajagur devagandharvā vīṇā pramumucuḥ svarān', null, 2085023),
('ramayana-2-85-24', 24, 'Ayodhya Kanda, Sarga 85, Verse 24', 'स शब्दो द्यां च भूमिं च प्राणिनां श्रवणानि च।
विवेशोच्चारितः श्लक्ष्णः समो लयगुणान्वितः॥', 'sa śabdo dyāṃ ca bhūmiṃ ca prāṇināṃ śravaṇāni ca
viveśoccāritaḥ ślakṣṇaḥ samo layaguṇānvitaḥ', null, 2085024),
('ramayana-2-85-25', 25, 'Ayodhya Kanda, Sarga 85, Verse 25', 'तस्मिन्नुपरते शब्दे दिव्ये श्रोत्रसुखे नृणाम्।
ददर्श भारतं सैन्यं विधानं विश्वकर्मणः॥', 'tasminn uparate śabde divye śrotrasukhe nṛṇām
dadarśa bhārataṃ sainyaṃ vidhānaṃ viśvakarmaṇaḥ', null, 2085025),
('ramayana-2-85-26', 26, 'Ayodhya Kanda, Sarga 85, Verse 26', 'बभूव हि समा भूमिः समन्तात्पञ्चयोजनम्।
शाद्वलैर्बहुभिश्छन्ना नीलवैदूर्यसंनिभैः॥', 'babhūva hi samā bhūmiḥ samantāt pañcayojanam
śādvalair bahubhiś channā nīlavaidūryasaṃnibhaiḥ', null, 2085026),
('ramayana-2-85-27', 27, 'Ayodhya Kanda, Sarga 85, Verse 27', 'तस्मिन्बिल्वाः कपित्थाश्च पनसा बीजपूरकाः।
आमलक्यो बभूवुश्च चूताश्च फलभूषणाः॥', 'tasmin bilvāḥ kapitthāś ca panasā bījapūrakāḥ
āmalakyo babhūvuś ca cūtāś ca phalabhūṣaṇāḥ', null, 2085027),
('ramayana-2-85-28', 28, 'Ayodhya Kanda, Sarga 85, Verse 28', 'उत्तरेभ्यः कुरुभ्यश्च वनं दिव्योपभोगवत्।
आजगाम नदी दिव्या तीरजैर्बहुभिर्वृता॥', 'uttarebhyaḥ kurubhyaś ca vanaṃ divyopabhogavat
ājagāma nadī divyā tīrajair bahubhir vṛtā', null, 2085028),
('ramayana-2-85-29', 29, 'Ayodhya Kanda, Sarga 85, Verse 29', 'चतुःशालानि शुभ्राणि शालाश्च गजवाजिनाम्।
हर्म्यप्रासादसंघातास्तोरणानि शुभानि च॥', 'catuḥśālāni śubhrāṇi śālāś ca gajavājinām
harmyaprāsādasaṃghātās toraṇāni śubhāni ca', null, 2085029),
('ramayana-2-85-30', 30, 'Ayodhya Kanda, Sarga 85, Verse 30', 'सितमेघनिभं चापि राजवेश्म सुतोरणम्।
शुक्लमाल्यकृताकारं दिव्यगन्धसमुक्षितम्॥', 'sitameghanibhaṃ cāpi rājaveśma sutoraṇam
śuklamālyakṛtākāraṃ divyagandhasamukṣitam', null, 2085030),
('ramayana-2-85-31', 31, 'Ayodhya Kanda, Sarga 85, Verse 31', 'चतुरस्रमसंबाधं शयनासनयानवत्।
दिव्यैः सर्वरसैर्युक्तं दिव्यभोजनवस्त्रवत्॥', 'caturasram asaṃbādhaṃ śayanāsanayānavat
divyaiḥ sarvarasair yuktaṃ divyabhojanavastravat', null, 2085031),
('ramayana-2-85-32', 32, 'Ayodhya Kanda, Sarga 85, Verse 32', 'उपकल्पित सर्वान्नं धौतनिर्मलभाजनम्।
कॢप्तसर्वासनं श्रीमत्स्वास्तीर्णशयनोत्तमम्॥', 'upakalpita sarvānnaṃ dhautanirmalabhājanam
kḷptasarvāsanaṃ śrīmat svāstīrṇaśayanottamam', null, 2085032),
('ramayana-2-85-33', 33, 'Ayodhya Kanda, Sarga 85, Verse 33', 'प्रविवेश महाबाहुरनुज्ञातो महर्षिणा।
वेश्म तद्रत्नसंपूर्णं भरतः कैकयीसुतः॥', 'praviveśa mahābāhur anujñāto maharṣiṇā
veśma tad ratnasaṃpūrṇaṃ bharataḥ kaikayīsutaḥ', null, 2085033),
('ramayana-2-85-34', 34, 'Ayodhya Kanda, Sarga 85, Verse 34', 'अनुजग्मुश्च तं सर्वे मन्त्रिणः सपुरोहिताः।
बभूवुश्च मुदा युक्ता तं दृष्ट्वा वेश्म संविधिम्॥', 'anujagmuś ca taṃ sarve mantriṇaḥ sapurohitāḥ
babhūvuś ca mudā yuktā taṃ dṛṣṭvā veśma saṃvidhim', null, 2085034),
('ramayana-2-85-35', 35, 'Ayodhya Kanda, Sarga 85, Verse 35', 'तत्र राजासनं दिव्यं व्यजनं छत्रमेव च।
भरतो मन्त्रिभिः सार्धमभ्यवर्तत राजवत्॥', 'tatra rājāsanaṃ divyaṃ vyajanaṃ chatram eva ca
bharato mantribhiḥ sārdham abhyavartata rājavat', null, 2085035),
('ramayana-2-85-36', 36, 'Ayodhya Kanda, Sarga 85, Verse 36', 'आसनं पूजयामास रामायाभिप्रणम्य च।
वालव्यजनमादाय न्यषीदत्सचिवासने॥', 'āsanaṃ pūjayām āsa rāmāyābhipraṇamya ca
vālavyajanam ādāya nyaṣīdat sacivāsane', null, 2085036),
('ramayana-2-85-37', 37, 'Ayodhya Kanda, Sarga 85, Verse 37', 'आनुपूर्व्यान्निषेदुश्च सर्वे मन्त्रपुरोहिताः।
ततः सेनापतिः पश्चात्प्रशास्ता च निषेदतुः॥', 'ānupūrvyān niṣeduś ca sarve mantrapurohitāḥ
tataḥ senāpatiḥ paścāt praśāstā ca niṣedatuḥ', null, 2085037),
('ramayana-2-85-38', 38, 'Ayodhya Kanda, Sarga 85, Verse 38', 'ततस्तत्र मुहूर्तेन नद्यः पायसकर्दमाः।
उपातिष्ठन्त भरतं भरद्वाजस्य शासनत्॥', 'tatas tatra muhūrtena nadyaḥ pāyasakardamāḥ
upātiṣṭhanta bharataṃ bharadvājasya śāsanat', null, 2085038),
('ramayana-2-85-39', 39, 'Ayodhya Kanda, Sarga 85, Verse 39', 'तासामुभयतः कूलं पाण्डुमृत्तिकलेपनाः।
रम्याश्चावसथा दिव्या ब्रह्मणस्तु प्रसादजाः॥', 'tāsām ubhayataḥ kūlaṃ pāṇḍumṛttikalepanāḥ
ramyāś cāvasathā divyā brahmaṇas tu prasādajāḥ', null, 2085039),
('ramayana-2-85-40', 40, 'Ayodhya Kanda, Sarga 85, Verse 40', 'तेनैव च मुहूर्तेन दिव्याभरणभूषिताः।
आगुर्विंशतिसाहस्रा ब्रह्मणा प्रहिताः स्त्रियः॥', 'tenaiva ca muhūrtena divyābharaṇabhūṣitāḥ
āgur viṃśatisāhasrā brahmaṇā prahitāḥ striyaḥ', null, 2085040),
('ramayana-2-85-41', 41, 'Ayodhya Kanda, Sarga 85, Verse 41', 'सुवर्णमणिमुक्तेन प्रवालेन च शोभिताः।
आगुर्विंशतिसाहस्राः कुबेरप्रहिताः स्त्रियः॥', 'suvarṇamaṇimuktena pravālena ca śobhitāḥ
āgur viṃśatisāhasrāḥ kuberaprahitāḥ striyaḥ', null, 2085041),
('ramayana-2-85-42', 42, 'Ayodhya Kanda, Sarga 85, Verse 42', 'याभिर्गृहीतः पुरुषः सोन्माद इव लक्ष्यते।
आगुर्विंशतिसाहस्रा नन्दनादप्सरोगणाः॥', 'yābhir gṛhītaḥ puruṣaḥ sonmāda iva lakṣyate
āgur viṃśatisāhasrā nandanād apsarogaṇāḥ', null, 2085042),
('ramayana-2-85-43', 43, 'Ayodhya Kanda, Sarga 85, Verse 43', 'नारदस्तुम्बुरुर्गोपः पर्वतः सूर्यवर्चसः।
एते गन्धर्वराजानो भरतस्याग्रतो जगुः॥', 'nāradas tumburur gopaḥ parvataḥ sūryavarcasaḥ
ete gandharvarājāno bharatasyāgrato jaguḥ', null, 2085043),
('ramayana-2-85-44', 44, 'Ayodhya Kanda, Sarga 85, Verse 44', 'अलम्बुसा मिश्रकेशी पुण्डरीकाथ वामना।
उपानृत्यंस्तु भरतं भरद्वाजस्य शासनात्॥', 'alambusā miśrakeśī puṇḍarīkātha vāmanā
upānṛtyaṃs tu bharataṃ bharadvājasya śāsanāt', null, 2085044),
('ramayana-2-85-45', 45, 'Ayodhya Kanda, Sarga 85, Verse 45', 'यानि माल्यानि देवेषु यानि चैत्ररथे वने।
प्रयागे तान्यदृश्यन्त भरद्वाजस्य शासनात्॥', 'yāni mālyāni deveṣu yāni caitrarathe vane
prayāge tāny adṛśyanta bharadvājasya śāsanāt', null, 2085045),
('ramayana-2-85-46', 46, 'Ayodhya Kanda, Sarga 85, Verse 46', 'बिल्वा मार्दङ्गिका आसञ्शम्या ग्राहा बिभीतकाः।
अश्वत्था नर्तकाश्चासन्भरद्वाजस्य तेजसा॥', 'bilvā mārdaṅgikā āsañ śamyā grāhā bibhītakāḥ
aśvatthā nartakāś cāsan bharadvājasya tejasā', null, 2085046),
('ramayana-2-85-47', 47, 'Ayodhya Kanda, Sarga 85, Verse 47', 'ततः सरलतालाश्च तिलका नक्तमालकाः।
प्रहृष्टास्तत्र संपेतुः कुब्जाभूताथ वामनाः॥', 'tataḥ saralatālāś ca tilakā naktamālakāḥ
prahṛṣṭās tatra saṃpetuḥ kubjābhūtātha vāmanāḥ', null, 2085047),
('ramayana-2-85-48', 48, 'Ayodhya Kanda, Sarga 85, Verse 48', 'शिंशपामलकी जम्बूर्याश्चान्याः कानने लताः।
प्रमदा विग्रहं कृत्वा भरद्वाजाश्रमेऽवसन्॥', 'śiṃśapāmalakī jambūr yāś cānyāḥ kānane latāḥ
pramadā vigrahaṃ kṛtvā bharadvājāśrame ''vasan', null, 2085048),
('ramayana-2-85-49', 49, 'Ayodhya Kanda, Sarga 85, Verse 49', 'सुरां सुरापाः पिबत पायसं च बुभुक्शिताः।
मांसनि च सुमेध्यानि भक्ष्यन्तां यावदिच्छथ॥', 'surāṃ surāpāḥ pibata pāyasaṃ ca bubhukśitāḥ
māṃsani ca sumedhyāni bhakṣyantāṃ yāvad icchatha', null, 2085049),
('ramayana-2-85-50', 50, 'Ayodhya Kanda, Sarga 85, Verse 50', 'उत्साद्य स्नापयन्ति स्म नदीतीरेषु वल्गुषु।
अप्येकमेकं पुरुषं प्रमदाः सत्प चाष्ट च॥', 'utsādya snāpayanti sma nadītīreṣu valguṣu
apy ekam ekaṃ puruṣaṃ pramadāḥ satpa cāṣṭa ca', null, 2085050),
('ramayana-2-85-51', 51, 'Ayodhya Kanda, Sarga 85, Verse 51', 'संवहन्त्यः समापेतुर्नार्यो रुचिरलोचनाः।
परिमृज्य तथान्योन्यं पाययन्ति वराङ्गनाः॥', 'saṃvahantyaḥ samāpetur nāryo ruciralocanāḥ
parimṛjya tathānyonyaṃ pāyayanti varāṅganāḥ', null, 2085051),
('ramayana-2-85-52', 52, 'Ayodhya Kanda, Sarga 85, Verse 52', 'हयान्गजान्खरानुष्ट्रांस्तथैव सुरभेः सुतान्।
इक्षूंश्च मधुजालांश्च भोजयन्ति स्म वाहनान्।
इक्ष्वाकुवरयोधानां चोदयन्तो महाबलाः॥', 'hayān gajān kharān uṣṭrāṃs tathaiva surabheḥ sutān
ikṣūṃś ca madhujālāṃś ca bhojayanti sma vāhanān
ikṣvākuvarayodhānāṃ codayanto mahābalāḥ', null, 2085052),
('ramayana-2-85-53', 53, 'Ayodhya Kanda, Sarga 85, Verse 53', 'नाश्वबन्धोऽश्वमाजानान्न गजं कुञ्जरग्रहः।
मत्तप्रमत्तमुदिता चमूः सा तत्र संबभौ॥', 'nāśvabandho ''śvam ājānān na gajaṃ kuñjaragrahaḥ
mattapramattamuditā camūḥ sā tatra saṃbabhau', null, 2085053),
('ramayana-2-85-54', 54, 'Ayodhya Kanda, Sarga 85, Verse 54', 'तर्पिता सर्वकामैस्ते रक्तचन्दनरूषिताः।
अप्सरोगणसंयुक्ताः सैन्या वाचमुदैरयन्॥', 'tarpitā sarvakāmais te raktacandanarūṣitāḥ
apsarogaṇasaṃyuktāḥ sainyā vācam udairayan', null, 2085054),
('ramayana-2-85-55', 55, 'Ayodhya Kanda, Sarga 85, Verse 55', 'नैवायोध्यां गमिष्यामो न गमिष्याम दण्डकान्।
कुशलं भरतस्यास्तु रामस्यास्तु तथा सुखम्॥', 'naivāyodhyāṃ gamiṣyāmo na gamiṣyāma daṇḍakān
kuśalaṃ bharatasyāstu rāmasyāstu tathā sukham', null, 2085055),
('ramayana-2-85-56', 56, 'Ayodhya Kanda, Sarga 85, Verse 56', 'इति पादातयोधाश्च हस्त्यश्वारोहबन्धकाः।
अनाथास्तं विधिं लब्ध्वा वाचमेतामुदैरयन्॥', 'iti pādātayodhāś ca hastyaśvārohabandhakāḥ
anāthās taṃ vidhiṃ labdhvā vācam etām udairayan', null, 2085056),
('ramayana-2-85-57', 57, 'Ayodhya Kanda, Sarga 85, Verse 57', 'संप्रहृष्टा विनेदुस्ते नरास्तत्र सहस्रशः।
भरतस्यानुयातारः स्वर्गेऽयमिति चाब्रुवन्॥', 'saṃprahṛṣṭā vinedus te narās tatra sahasraśaḥ
bharatasyānuyātāraḥ svarge ''yam iti cābruvan', null, 2085057),
('ramayana-2-85-58', 58, 'Ayodhya Kanda, Sarga 85, Verse 58', 'ततो भुक्तवतां तेषां तदन्नममृतोपमम्।
दिव्यानुद्वीक्ष्य भक्ष्यांस्तानभवद्भक्षणे मतिः॥', 'tato bhuktavatāṃ teṣāṃ tad annam amṛtopamam
divyān udvīkṣya bhakṣyāṃs tān abhavad bhakṣaṇe matiḥ', null, 2085058),
('ramayana-2-85-59', 59, 'Ayodhya Kanda, Sarga 85, Verse 59', 'प्रेष्याश्चेट्यश्च वध्वश्च बलस्थाश्चापि सर्वशः।
बभूवुस्ते भृशं तृप्ताः सर्वे चाहतवाससः॥', 'preṣyāś ceṭyaś ca vadhvaś ca balasthāś cāpi sarvaśaḥ
babhūvus te bhṛśaṃ tṛptāḥ sarve cāhatavāsasaḥ', null, 2085059),
('ramayana-2-85-60', 60, 'Ayodhya Kanda, Sarga 85, Verse 60', 'कुञ्जराश्च खरोष्ट्रश्च गोऽश्वाश्च मृगपक्षिणः।
बभूवुः सुभृतास्तत्र नान्यो ह्यन्यमकल्पयत्॥', 'kuñjarāś ca kharoṣṭraś ca go''śvāś ca mṛgapakṣiṇaḥ
babhūvuḥ subhṛtās tatra nānyo hy anyam akalpayat', null, 2085060),
('ramayana-2-85-61', 61, 'Ayodhya Kanda, Sarga 85, Verse 61', 'नाशुक्लवासास्तत्रासीत्क्षुधितो मलिनोऽपि वा।
रजसा ध्वस्तकेशो वा नरः कश्चिददृश्यत॥', 'nāśuklavāsās tatrāsīt kṣudhito malino ''pi vā
rajasā dhvastakeśo vā naraḥ kaś cid adṛśyata', null, 2085061),
('ramayana-2-85-62', 62, 'Ayodhya Kanda, Sarga 85, Verse 62', 'आजैश्चापि च वाराहैर्निष्ठानवरसंचयैः।
फलनिर्यूहसंसिद्धैः सूपैर्गन्धरसान्वितैः॥', 'ājaiś cāpi ca vārāhair niṣṭhānavarasaṃcayaiḥ
phalaniryūhasaṃsiddhaiḥ sūpair gandharasānvitaiḥ', null, 2085062),
('ramayana-2-85-63', 63, 'Ayodhya Kanda, Sarga 85, Verse 63', 'पुष्पध्वजवतीः पूर्णाः शुक्लस्यान्नस्य चाभितः।
ददृशुर्विस्मितास्तत्र नरा लौहीः सहस्रशः॥', 'puṣpadhvajavatīḥ pūrṇāḥ śuklasyānnasya cābhitaḥ
dadṛśur vismitās tatra narā lauhīḥ sahasraśaḥ', null, 2085063),
('ramayana-2-85-64', 64, 'Ayodhya Kanda, Sarga 85, Verse 64', 'बभूवुर्वनपार्श्वेषु कूपाः पायसकर्दमाः।
ताश्च कामदुघा गावो द्रुमाश्चासन्मधुश्च्युतः॥', 'babhūvur vanapārśveṣu kūpāḥ pāyasakardamāḥ
tāś ca kāmadughā gāvo drumāś cāsan madhuścyutaḥ', null, 2085064),
('ramayana-2-85-65', 65, 'Ayodhya Kanda, Sarga 85, Verse 65', 'वाप्यो मैरेयपूर्णाश्च मृष्टमांसचयैर्वृताः।
प्रतप्तपिठरैश्चापि मार्गमायूरकौक्कुटैः॥', 'vāpyo maireyapūrṇāś ca mṛṣṭamāṃsacayair vṛtāḥ
prataptapiṭharaiś cāpi mārgamāyūrakaukkuṭaiḥ', null, 2085065),
('ramayana-2-85-66', 66, 'Ayodhya Kanda, Sarga 85, Verse 66', 'पात्रीणां च सहस्राणि शातकुम्भमयानि च।
स्थाल्यः कुम्भ्यः करम्भ्यश्च दधिपूर्णाः सुसंस्कृताः।
यौवनस्थस्य गौरस्य कपित्थस्य सुगन्धिनः॥', 'pātrīṇāṃ ca sahasrāṇi śātakumbhamayāni ca
sthālyaḥ kumbhyaḥ karambhyaś ca dadhipūrṇāḥ susaṃskṛtāḥ
yauvanasthasya gaurasya kapitthasya sugandhinaḥ', null, 2085066),
('ramayana-2-85-67', 67, 'Ayodhya Kanda, Sarga 85, Verse 67', 'ह्रदाः पूर्णा रसालस्य दध्नः श्वेतस्य चापरे।
बभूवुः पायसस्यान्ते शर्करायाश्च संचयाः॥', 'hradāḥ pūrṇā rasālasya dadhnaḥ śvetasya cāpare
babhūvuḥ pāyasasyānte śarkarāyāś ca saṃcayāḥ', null, 2085067),
('ramayana-2-85-68', 68, 'Ayodhya Kanda, Sarga 85, Verse 68', 'कल्कांश्चूर्णकषायांश्च स्नानानि विविधानि च।
ददृशुर्भाजनस्थानि तीर्थेषु सरितां नराः॥', 'kalkāṃś cūrṇakaṣāyāṃś ca snānāni vividhāni ca
dadṛśur bhājanasthāni tīrtheṣu saritāṃ narāḥ', null, 2085068),
('ramayana-2-85-69', 69, 'Ayodhya Kanda, Sarga 85, Verse 69', 'शुक्लानंशुमतश्चापि दन्तधावनसंचयान्।
शुक्लांश्चन्दनकल्कांश्च समुद्गेष्ववतिष्ठतः॥', 'śuklān aṃśumataś cāpi dantadhāvanasaṃcayān
śuklāṃś candanakalkāṃś ca samudgeṣv avatiṣṭhataḥ', null, 2085069),
('ramayana-2-85-70', 70, 'Ayodhya Kanda, Sarga 85, Verse 70', 'दर्पणान्परिमृष्टांश्च वाससां चापि संचयान्।
पादुकोपानहां चैव युग्मान्यत्र सहस्रशः॥', 'darpaṇān parimṛṣṭāṃś ca vāsasāṃ cāpi saṃcayān
pādukopānahāṃ caiva yugmān yatra sahasraśaḥ', null, 2085070),
('ramayana-2-85-71', 71, 'Ayodhya Kanda, Sarga 85, Verse 71', 'आञ्जनीः कङ्कतान्कूर्चांश्छत्राणि च धनूंषि च।
मर्मत्राणानि चित्राणि शयनान्यासनानि च॥', 'āñjanīḥ kaṅkatān kūrcāṃś chatrāṇi ca dhanūṃṣi ca
marmatrāṇāni citrāṇi śayanāny āsanāni ca', null, 2085071),
('ramayana-2-85-72', 72, 'Ayodhya Kanda, Sarga 85, Verse 72', 'प्रतिपानह्रदान्पूर्णान्खरोष्ट्रगजवाजिनाम्।
अवगाह्य सुतीर्थांश्च ह्रदान्सोत्पल पुष्करान्॥', 'pratipānahradān pūrṇān kharoṣṭragajavājinām
avagāhya sutīrthāṃś ca hradān sotpala puṣkarān', null, 2085072),
('ramayana-2-85-73', 73, 'Ayodhya Kanda, Sarga 85, Verse 73', 'नीलवैदूर्यवर्णांश्च मृदून्यवससंचयान्।
निर्वापार्थं पशूनां ते ददृशुस्तत्र सर्वशः॥', 'nīlavaidūryavarṇāṃś ca mṛdūn yavasasaṃcayān
nirvāpārthaṃ paśūnāṃ te dadṛśus tatra sarvaśaḥ', null, 2085073),
('ramayana-2-85-74', 74, 'Ayodhya Kanda, Sarga 85, Verse 74', 'व्यस्मयन्त मनुष्यास्ते स्वप्नकल्पं तदद्भुतम्।
दृष्ट्वातिथ्यं कृतं तादृग्भरतस्य महर्षिणा॥', 'vyasmayanta manuṣyās te svapnakalpaṃ tad adbhutam
dṛṣṭvātithyaṃ kṛtaṃ tādṛg bharatasya maharṣiṇā', null, 2085074),
('ramayana-2-85-75', 75, 'Ayodhya Kanda, Sarga 85, Verse 75', 'इत्येवं रममाणानां देवानामिव नन्दने।
भरद्वाजाश्रमे रम्ये सा रात्रिर्व्यत्यवर्तत॥', 'ity evaṃ ramamāṇānāṃ devānām iva nandane
bharadvājāśrame ramye sā rātrir vyatyavartata', null, 2085075),
('ramayana-2-85-76', 76, 'Ayodhya Kanda, Sarga 85, Verse 76', 'प्रतिजग्मुश्च ता नद्यो गन्धर्वाश्च यथागतम्।
भरद्वाजमनुज्ञाप्य ताश्च सर्वा वराङ्गनाः॥', 'pratijagmuś ca tā nadyo gandharvāś ca yathāgatam
bharadvājam anujñāpya tāś ca sarvā varāṅganāḥ', null, 2085076),
('ramayana-2-85-77', 77, 'Ayodhya Kanda, Sarga 85, Verse 77', 'तथैव मत्ता मदिरोत्कटा नरास्तथैव दिव्यागुरुचन्दनोक्षिताः।
तथैव दिव्या विविधाः स्रगुत्तमाः पृथक्प्रकीर्णा मनुजैः प्रमर्दिताः॥', 'tathaiva mattā madirotkaṭā narās tathaiva divyāgurucandanokṣitāḥ
tathaiva divyā vividhāḥ sraguttamāḥ pṛthakprakīrṇā manujaiḥ pramarditāḥ', null, 2085077)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 86 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-86-1', 1, 'Ayodhya Kanda, Sarga 86, Verse 1', 'ततस्तां रजनीमुष्य भरतः सपरिच्छदः।
कृतातिथ्यो भरद्वाजं कामादभिजगाम ह॥', 'tatas tāṃ rajanīm uṣya bharataḥ saparicchadaḥ
kṛtātithyo bharadvājaṃ kāmād abhijagāma ha', null, 2086001),
('ramayana-2-86-2', 2, 'Ayodhya Kanda, Sarga 86, Verse 2', 'तमृषिः पुरुषव्याघ्रं प्रेक्ष्य प्राञ्जलिमागतम्।
हुताग्निहोत्रो भरतं भरद्वाजोऽभ्यभाषत॥', 'tam ṛṣiḥ puruṣavyāghraṃ prekṣya prāñjalim āgatam
hutāgnihotro bharataṃ bharadvājo ''bhyabhāṣata', null, 2086002),
('ramayana-2-86-3', 3, 'Ayodhya Kanda, Sarga 86, Verse 3', 'कच्चिदत्र सुखा रात्रिस्तवास्मद्विषये गता।
समग्रस्ते जनः कच्चिदातिथ्ये शंस मेऽनघ॥', 'kaccid atra sukhā rātris tavāsmadviṣaye gatā
samagras te janaḥ kaccid ātithye śaṃsa me ''nagha', null, 2086003),
('ramayana-2-86-4', 4, 'Ayodhya Kanda, Sarga 86, Verse 4', 'तमुवाचाञ्जलिं कृत्वा भरतोऽभिप्रणम्य च।
आश्रमादभिनिष्क्रन्तमृषिमुत्तम तेजसं॥', 'tam uvācāñjaliṃ kṛtvā bharato ''bhipraṇamya ca
āśramād abhiniṣkrantam ṛṣim uttama tejasaṃ', null, 2086004),
('ramayana-2-86-5', 5, 'Ayodhya Kanda, Sarga 86, Verse 5', 'सुखोषितोऽस्मि भगवन्समग्रबलवाहनः।
तर्पितः सर्वकामैश्च सामात्यो बलवत्त्वया॥', 'sukhoṣito ''smi bhagavan samagrabalavāhanaḥ
tarpitaḥ sarvakāmaiś ca sāmātyo balavat tvayā', null, 2086005),
('ramayana-2-86-6', 6, 'Ayodhya Kanda, Sarga 86, Verse 6', 'अपेतक्लमसंतापाः सुभक्ष्याः सुप्रतिश्रयाः।
अपि प्रेष्यानुपादाय सर्वे स्म सुसुखोषिताः॥', 'apetaklamasaṃtāpāḥ subhakṣyāḥ supratiśrayāḥ
api preṣyān upādāya sarve sma susukhoṣitāḥ', null, 2086006),
('ramayana-2-86-7', 7, 'Ayodhya Kanda, Sarga 86, Verse 7', 'आमन्त्रयेऽहं भगवन्कामं त्वामृषिसत्तम।
समीपं प्रस्थितं भ्रातुर्मैरेणेक्षस्व चक्षुषा॥', 'āmantraye ''haṃ bhagavan kāmaṃ tvām ṛṣisattama
samīpaṃ prasthitaṃ bhrātur maireṇekṣasva cakṣuṣā', null, 2086007),
('ramayana-2-86-8', 8, 'Ayodhya Kanda, Sarga 86, Verse 8', 'आश्रमं तस्य धर्मज्ञ धार्मिकस्य महात्मनः।
आचक्ष्व कतमो मार्गः कियानिति च शंस मे॥', 'āśramaṃ tasya dharmajña dhārmikasya mahātmanaḥ
ācakṣva katamo mārgaḥ kiyān iti ca śaṃsa me', null, 2086008),
('ramayana-2-86-9', 9, 'Ayodhya Kanda, Sarga 86, Verse 9', 'इति पृष्टस्तु भरतं भ्रातृदर्शनलालसं।
प्रत्युवाच महातेजा भरद्वाजो महातपाः॥', 'iti pṛṣṭas tu bharataṃ bhrātṛdarśanalālasaṃ
pratyuvāca mahātejā bharadvājo mahātapāḥ', null, 2086009),
('ramayana-2-86-10', 10, 'Ayodhya Kanda, Sarga 86, Verse 10', 'भरतार्धतृतीयेषु योजनेष्वजने वने।
चित्रकूटो गिरिस्तत्र रम्यनिर्दरकाननः॥', 'bharatārdhatṛtīyeṣu yojaneṣv ajane vane
citrakūṭo giris tatra ramyanirdarakānanaḥ', null, 2086010),
('ramayana-2-86-11', 11, 'Ayodhya Kanda, Sarga 86, Verse 11', 'उत्तरं पार्श्वमासाद्य तस्य मन्दाकिनी नदी।
पुष्पितद्रुमसंछन्ना रम्यपुष्पितकानना॥', 'uttaraṃ pārśvam āsādya tasya mandākinī nadī
puṣpitadrumasaṃchannā ramyapuṣpitakānanā', null, 2086011),
('ramayana-2-86-12', 12, 'Ayodhya Kanda, Sarga 86, Verse 12', 'अनन्तरं तत्सरितश्चित्रकूटश्च पर्वतः।
ततो पर्णकुटी तात तत्र तौ वसतो ध्रुवम्॥', 'anantaraṃ tat saritaś citrakūṭaś ca parvataḥ
tato parṇakuṭī tāta tatra tau vasato dhruvam', null, 2086012),
('ramayana-2-86-13', 13, 'Ayodhya Kanda, Sarga 86, Verse 13', 'दक्षिणेनैव मार्गेण सव्यदक्षिणमेव च।
गजवाजिरथाकीर्णां वाहिनीं वाहिनीपते।
वाहयस्व महाभाग ततो द्रक्ष्यसि राघवम्॥', 'dakṣiṇenaiva mārgeṇa savyadakṣiṇam eva ca
gajavājirathākīrṇāṃ vāhinīṃ vāhinīpate
vāhayasva mahābhāga tato drakṣyasi rāghavam', null, 2086013),
('ramayana-2-86-14', 14, 'Ayodhya Kanda, Sarga 86, Verse 14', 'प्रयाणमिति च श्रुत्वा राजराजस्य योषितः।
हित्वा यानानि यानार्हा ब्राह्मणं पर्यवारयन्॥', 'prayāṇam iti ca śrutvā rājarājasya yoṣitaḥ
hitvā yānāni yānārhā brāhmaṇaṃ paryavārayan', null, 2086014),
('ramayana-2-86-15', 15, 'Ayodhya Kanda, Sarga 86, Verse 15', 'वेपमाना कृशा दीना सह देव्या सुमन्त्रिया।
कौसल्या तत्र जग्राह कराभ्यां चरणौ मुनेः॥', 'vepamānā kṛśā dīnā saha devyā sumantriyā
kausalyā tatra jagrāha karābhyāṃ caraṇau muneḥ', null, 2086015),
('ramayana-2-86-16', 16, 'Ayodhya Kanda, Sarga 86, Verse 16', 'असमृद्धेन कामेन सर्वलोकस्य गर्हिता।
कैकेयी तस्य जग्राह चरणौ सव्यपत्रपा॥', 'asamṛddhena kāmena sarvalokasya garhitā
kaikeyī tasya jagrāha caraṇau savyapatrapā', null, 2086016),
('ramayana-2-86-17', 17, 'Ayodhya Kanda, Sarga 86, Verse 17', 'तं प्रदक्षिणमागम्य भगवन्तं महामुनिम्।
अदूराद्भरतस्यैव तस्थौ दीनमनास्तदा॥', 'taṃ pradakṣiṇam āgamya bhagavantaṃ mahāmunim
adūrād bharatasyaiva tasthau dīnamanās tadā', null, 2086017),
('ramayana-2-86-18', 18, 'Ayodhya Kanda, Sarga 86, Verse 18', 'ततः पप्रच्छ भरतं भरद्वाजो दृढव्रतः।
विशेषं ज्ञातुमिच्छामि मातॄणां तव राघव॥', 'tataḥ papraccha bharataṃ bharadvājo dṛḍhavrataḥ
viśeṣaṃ jñātum icchāmi mātṝṇāṃ tava rāghava', null, 2086018),
('ramayana-2-86-19', 19, 'Ayodhya Kanda, Sarga 86, Verse 19', 'एवमुक्तस्तु भरतो भरद्वाजेन धार्मिकः।
उवाच प्राञ्जलिर्भूत्वा वाक्यं वचनकोविदः॥', 'evam uktas tu bharato bharadvājena dhārmikaḥ
uvāca prāñjalir bhūtvā vākyaṃ vacanakovidaḥ', null, 2086019),
('ramayana-2-86-20', 20, 'Ayodhya Kanda, Sarga 86, Verse 20', 'यामिमां भगवन्दीनां शोकानशनकर्शिताम्।
पितुर्हि महिषीं देवीं देवतामिव पश्यसि॥', 'yām imāṃ bhagavan dīnāṃ śokān aśanakarśitām
pitur hi mahiṣīṃ devīṃ devatām iva paśyasi', null, 2086020),
('ramayana-2-86-21', 21, 'Ayodhya Kanda, Sarga 86, Verse 21', 'एषा तं पुरुषव्याघ्रं सिंहविक्रान्तगामिनम्।
कौसल्या सुषुवे रामं धातारमदितिर्यथा॥', 'eṣā taṃ puruṣavyāghraṃ siṃhavikrāntagāminam
kausalyā suṣuve rāmaṃ dhātāram aditir yathā', null, 2086021),
('ramayana-2-86-22', 22, 'Ayodhya Kanda, Sarga 86, Verse 22', 'अस्या वामभुजं श्लिष्टा यैषा तिष्ठति दुर्मनाः।
कर्णिकारस्य शाखेव शीर्णपुष्पा वनान्तरे॥', 'asyā vāmabhujaṃ śliṣṭā yaiṣā tiṣṭhati durmanāḥ
karṇikārasya śākheva śīrṇapuṣpā vanāntare', null, 2086022),
('ramayana-2-86-23', 23, 'Ayodhya Kanda, Sarga 86, Verse 23', 'एतस्यास्तौ सुतौ देव्याः कुमारौ देववर्णिनौ।
उभौ लक्ष्मणशत्रुघ्नौ वीरौ सत्यपराक्रमौ॥', 'etasyās tau sutau devyāḥ kumārau devavarṇinau
ubhau lakṣmaṇaśatrughnau vīrau satyaparākramau', null, 2086023),
('ramayana-2-86-24', 24, 'Ayodhya Kanda, Sarga 86, Verse 24', 'यस्याः कृते नरव्याघ्रौ जीवनाशमितो गतौ।
राजा पुत्रविहीनश्च स्वर्गं दशरथो गतः॥', 'yasyāḥ kṛte naravyāghrau jīvanāśam ito gatau
rājā putravihīnaś ca svargaṃ daśaratho gataḥ', null, 2086024),
('ramayana-2-86-25', 25, 'Ayodhya Kanda, Sarga 86, Verse 25', 'ऐश्वर्यकामां कैकेयीमनार्यामार्यरूपिणीम्।
ममैतां मातरं विद्धि नृशंसां पापनिश्चयाम्।
यतोमूलं हि पश्यामि व्यसनं महदात्मनः॥', 'aiśvaryakāmāṃ kaikeyīm anāryām āryarūpiṇīm
mamaitāṃ mātaraṃ viddhi nṛśaṃsāṃ pāpaniścayām
yatomūlaṃ hi paśyāmi vyasanaṃ mahad ātmanaḥ', null, 2086025),
('ramayana-2-86-26', 26, 'Ayodhya Kanda, Sarga 86, Verse 26', 'इत्युक्त्वा नरशार्दूलो बाष्पगद्गदया गिरा।
स निशश्वास ताम्राक्षो क्रुद्धो नाग इवासकृत्॥', 'ity uktvā naraśārdūlo bāṣpagadgadayā girā
sa niśaśvāsa tāmrākṣo kruddho nāga ivāsakṛt', null, 2086026),
('ramayana-2-86-27', 27, 'Ayodhya Kanda, Sarga 86, Verse 27', 'भरद्वाजो महर्षिस्तं ब्रुवन्तं भरतं तदा।
प्रत्युवाच महाबुद्धिरिदं वचनमर्थवत्॥', 'bharadvājo maharṣis taṃ bruvantaṃ bharataṃ tadā
pratyuvāca mahābuddhir idaṃ vacanam arthavat', null, 2086027),
('ramayana-2-86-28', 28, 'Ayodhya Kanda, Sarga 86, Verse 28', 'न दोषेणावगन्तव्या कैकेयी भरत त्वया।
रामप्रव्राजनं ह्येतत्सुखोदर्कं भविष्यति॥', 'na doṣeṇāvagantavyā kaikeyī bharata tvayā
rāmapravrājanaṃ hy etat sukhodarkaṃ bhaviṣyati', null, 2086028),
('ramayana-2-86-29', 29, 'Ayodhya Kanda, Sarga 86, Verse 29', 'अभिवाद्य तु संसिद्धः कृत्वा चैनं प्रदक्षिणम्।
आमन्त्र्य भरतः सैन्यं युज्यतामित्यचोदयत्॥', 'abhivādya tu saṃsiddhaḥ kṛtvā cainaṃ pradakṣiṇam
āmantrya bharataḥ sainyaṃ yujyatām ity acodayat', null, 2086029),
('ramayana-2-86-30', 30, 'Ayodhya Kanda, Sarga 86, Verse 30', 'ततो वाजिरथान्युक्त्वा दिव्यान्हेमपरिष्क्रितान्।
अध्यारोहत्प्रयाणार्थी बहून्बहुविधो जनः॥', 'tato vājirathān yuktvā divyān hemapariṣkritān
adhyārohat prayāṇārthī bahūn bahuvidho janaḥ', null, 2086030),
('ramayana-2-86-31', 31, 'Ayodhya Kanda, Sarga 86, Verse 31', 'गजकन्यागजाश्चैव हेमकक्ष्याः पताकिनः।
जीमूता इव घर्मान्ते सघोषाः संप्रतस्थिरे॥', 'gajakanyāgajāś caiva hemakakṣyāḥ patākinaḥ
jīmūtā iva gharmānte saghoṣāḥ saṃpratasthire', null, 2086031),
('ramayana-2-86-32', 32, 'Ayodhya Kanda, Sarga 86, Verse 32', 'विविधान्यपि यानानि महानि च लघूनि च।
प्रययुः सुमहार्हाणि पादैरेव पदातयः॥', 'vividhāny api yānāni mahāni ca laghūni ca
prayayuḥ sumahārhāṇi pādair eva padātayaḥ', null, 2086032),
('ramayana-2-86-33', 33, 'Ayodhya Kanda, Sarga 86, Verse 33', 'अथ यानप्रवेकैस्तु कौसल्याप्रमुखाः स्त्रियः।
रामदर्शनकाङ्क्षिण्यः प्रययुर्मुदितास्तदा॥', 'atha yānapravekais tu kausalyāpramukhāḥ striyaḥ
rāmadarśanakāṅkṣiṇyaḥ prayayur muditās tadā', null, 2086033),
('ramayana-2-86-34', 34, 'Ayodhya Kanda, Sarga 86, Verse 34', 'स चार्कतरुणाभासां नियुक्तां शिबिकां शुभाम्।
आस्थाय प्रययौ श्रीमान्भरतः सपरिच्छदः॥', 'sa cārkataruṇābhāsāṃ niyuktāṃ śibikāṃ śubhām
āsthāya prayayau śrīmān bharataḥ saparicchadaḥ', null, 2086034),
('ramayana-2-86-35', 35, 'Ayodhya Kanda, Sarga 86, Verse 35', 'सा प्रयाता महासेना गजवाजिरथाकुला।
दक्षिणां दिशमावृत्य महामेघ इवोत्थितः।
वनानि तु व्यतिक्रम्य जुष्टानि मृगपक्षिभिः॥', 'sā prayātā mahāsenā gajavājirathākulā
dakṣiṇāṃ diśam āvṛtya mahāmegha ivotthitaḥ
vanāni tu vyatikramya juṣṭāni mṛgapakṣibhiḥ', null, 2086035),
('ramayana-2-86-36', 36, 'Ayodhya Kanda, Sarga 86, Verse 36', 'सा संप्रहृष्टद्विपवाजियोधा वित्रासयन्ती मृगपक्षिसंघान्।
महद्वनं तत्प्रविगाहमाना रराज सेना भरतस्य तत्र॥', 'sā saṃprahṛṣṭadvipavājiyodhā vitrāsayantī mṛgapakṣisaṃghān
mahad vanaṃ tat pravigāhamānā rarāja senā bharatasya tatra', null, 2086036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 87 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-87-1', 1, 'Ayodhya Kanda, Sarga 87, Verse 1', 'तया महत्या यायिन्या ध्वजिन्या वनवासिनः।
अर्दिता यूथपा मत्ताः सयूथाः संप्रदुद्रुवुः॥', 'tayā mahatyā yāyinyā dhvajinyā vanavāsinaḥ
arditā yūthapā mattāḥ sayūthāḥ saṃpradudruvuḥ', null, 2087001),
('ramayana-2-87-2', 2, 'Ayodhya Kanda, Sarga 87, Verse 2', 'ऋक्षाः पृषतसंघाश्च रुरवश्च समन्ततः।
दृश्यन्ते वनराजीषु गिरिष्वपि नदीषु च॥', 'ṛkṣāḥ pṛṣatasaṃghāś ca ruravaś ca samantataḥ
dṛśyante vanarājīṣu giriṣv api nadīṣu ca', null, 2087002),
('ramayana-2-87-3', 3, 'Ayodhya Kanda, Sarga 87, Verse 3', 'स संप्रतस्थे धर्मात्मा प्रीतो दशरथात्मजः।
वृतो महत्या नादिन्या सेनया चतुरङ्गया॥', 'sa saṃpratasthe dharmātmā prīto daśarathātmajaḥ
vṛto mahatyā nādinyā senayā caturaṅgayā', null, 2087003),
('ramayana-2-87-4', 4, 'Ayodhya Kanda, Sarga 87, Verse 4', 'सागरौघनिभा सेना भरतस्य महात्मनः।
महीं संछादयामास प्रावृषि द्यामिवाम्बुदः॥', 'sāgaraughanibhā senā bharatasya mahātmanaḥ
mahīṃ saṃchādayām āsa prāvṛṣi dyām ivāmbudaḥ', null, 2087004),
('ramayana-2-87-5', 5, 'Ayodhya Kanda, Sarga 87, Verse 5', 'तुरंगौघैरवतता वारणैश्च महाजवैः।
अनालक्ष्या चिरं कालं तस्मिन्काले बभूव भूः॥', 'turaṃgaughair avatatā vāraṇaiś ca mahājavaiḥ
anālakṣyā ciraṃ kālaṃ tasmin kāle babhūva bhūḥ', null, 2087005),
('ramayana-2-87-6', 6, 'Ayodhya Kanda, Sarga 87, Verse 6', 'स यात्वा दूरमध्वानं सुपरिश्रान्त वाहनः।
उवाच भरतः श्रीमान्वसिष्ठं मन्त्रिणां वरम्॥', 'sa yātvā dūram adhvānaṃ supariśrānta vāhanaḥ
uvāca bharataḥ śrīmān vasiṣṭhaṃ mantriṇāṃ varam', null, 2087006),
('ramayana-2-87-7', 7, 'Ayodhya Kanda, Sarga 87, Verse 7', 'यादृशं लक्ष्यते रूपं यथा चैव श्रुतं मया।
व्यक्तं प्राप्ताः स्म तं देशं भरद्वाजो यमब्रवीत्॥', 'yādṛśaṃ lakṣyate rūpaṃ yathā caiva śrutaṃ mayā
vyaktaṃ prāptāḥ sma taṃ deśaṃ bharadvājo yam abravīt', null, 2087007),
('ramayana-2-87-8', 8, 'Ayodhya Kanda, Sarga 87, Verse 8', 'अयं गिरिश्चित्रकूटस्तथा मन्दाकिनी नदी।
एतत्प्रकाशते दूरान्नीलमेघनिभं वनम्॥', 'ayaṃ giriś citrakūṭas tathā mandākinī nadī
etat prakāśate dūrān nīlameghanibhaṃ vanam', null, 2087008),
('ramayana-2-87-9', 9, 'Ayodhya Kanda, Sarga 87, Verse 9', 'गिरेः सानूनि रम्याणि चित्रकूटस्य संप्रति।
वारणैरवमृद्यन्ते मामकैः पर्वतोपमैः॥', 'gireḥ sānūni ramyāṇi citrakūṭasya saṃprati
vāraṇair avamṛdyante māmakaiḥ parvatopamaiḥ', null, 2087009),
('ramayana-2-87-10', 10, 'Ayodhya Kanda, Sarga 87, Verse 10', 'मुञ्चन्ति कुसुमान्येते नगाः पर्वतसानुषु।
नीला इवातपापाये तोयं तोयधरा घनाः॥', 'muñcanti kusumāny ete nagāḥ parvatasānuṣu
nīlā ivātapāpāye toyaṃ toyadharā ghanāḥ', null, 2087010),
('ramayana-2-87-11', 11, 'Ayodhya Kanda, Sarga 87, Verse 11', 'किन्नराचरितोद्देशं पश्य शत्रुघ्न पर्वतम्।
हयैः समन्तादाकीर्णं मकरैरिव सागरम्॥', 'kinnarācaritoddeśaṃ paśya śatrughna parvatam
hayaiḥ samantād ākīrṇaṃ makarair iva sāgaram', null, 2087011),
('ramayana-2-87-12', 12, 'Ayodhya Kanda, Sarga 87, Verse 12', 'एते मृगगणा भान्ति शीघ्रवेगाः प्रचोदिताः।
वायुप्रविद्धाः शरदि मेघराज्य इवाम्बरे॥', 'ete mṛgagaṇā bhānti śīghravegāḥ pracoditāḥ
vāyupraviddhāḥ śaradi megharājya ivāmbare', null, 2087012),
('ramayana-2-87-13', 13, 'Ayodhya Kanda, Sarga 87, Verse 13', 'कुर्वन्ति कुसुमापीडाञ्शिरःसु सुरभीनमी।
मेघप्रकाशैः फलकैर्दाक्षिणात्या यथा नराः॥', 'kurvanti kusumāpīḍāñ śiraḥsu surabhīn amī
meghaprakāśaiḥ phalakair dākṣiṇātyā yathā narāḥ', null, 2087013),
('ramayana-2-87-14', 14, 'Ayodhya Kanda, Sarga 87, Verse 14', 'निष्कूजमिव भूत्वेदं वनं घोरप्रदर्शनम्।
अयोध्येव जनाकीर्णा संप्रति प्रतिभाति मा॥', 'niṣkūjam iva bhūtvedaṃ vanaṃ ghorapradarśanam
ayodhyeva janākīrṇā saṃprati pratibhāti mā', null, 2087014),
('ramayana-2-87-15', 15, 'Ayodhya Kanda, Sarga 87, Verse 15', 'खुरैरुदीरितो रेणुर्दिवं प्रच्छाद्य तिष्ठति।
तं वहत्यनिलः शीघ्रं कुर्वन्निव मम प्रियम्॥', 'khurair udīrito reṇur divaṃ pracchādya tiṣṭhati
taṃ vahaty anilaḥ śīghraṃ kurvann iva mama priyam', null, 2087015),
('ramayana-2-87-16', 16, 'Ayodhya Kanda, Sarga 87, Verse 16', 'स्यन्दनांस्तुरगोपेतान्सूतमुख्यैरधिष्ठितान्।
एतान्संपततः शीघ्रं पश्य शत्रुघ्न कानने॥', 'syandanāṃs turagopetān sūtamukhyair adhiṣṭhitān
etān saṃpatataḥ śīghraṃ paśya śatrughna kānane', null, 2087016),
('ramayana-2-87-17', 17, 'Ayodhya Kanda, Sarga 87, Verse 17', 'एतान्वित्रासितान्पश्य बर्हिणः प्रियदर्शनान्।
एतमाविशतः शैलमधिवासं पतत्रिणाम्॥', 'etān vitrāsitān paśya barhiṇaḥ priyadarśanān
etam āviśataḥ śailam adhivāsaṃ patatriṇām', null, 2087017),
('ramayana-2-87-18', 18, 'Ayodhya Kanda, Sarga 87, Verse 18', 'अतिमात्रमयं देशो मनोज्ञः प्रतिभाति मा।
तापसानां निवासोऽयं व्यक्तं स्वर्गपथो यथा॥', 'atimātram ayaṃ deśo manojñaḥ pratibhāti mā
tāpasānāṃ nivāso ''yaṃ vyaktaṃ svargapatho yathā', null, 2087018),
('ramayana-2-87-19', 19, 'Ayodhya Kanda, Sarga 87, Verse 19', 'मृगा मृगीभिः सहिता बहवः पृषता वने।
मनोज्ञ रूपा लक्ष्यन्ते कुसुमैरिव चित्रितः॥', 'mṛgā mṛgībhiḥ sahitā bahavaḥ pṛṣatā vane
manojña rūpā lakṣyante kusumair iva citritaḥ', null, 2087019),
('ramayana-2-87-20', 20, 'Ayodhya Kanda, Sarga 87, Verse 20', 'साधु सैन्याः प्रतिष्ठन्तां विचिन्वन्तु च काननम्।
यथा तौ पुरुषव्याघ्रौ दृश्येते रामलक्ष्मणौ॥', 'sādhu sainyāḥ pratiṣṭhantāṃ vicinvantu ca kānanam
yathā tau puruṣavyāghrau dṛśyete rāmalakṣmaṇau', null, 2087020),
('ramayana-2-87-21', 21, 'Ayodhya Kanda, Sarga 87, Verse 21', 'भरतस्य वचः श्रुत्वा पुरुषाः शस्त्रपाणयः।
विविशुस्तद्वनं शूरा धूमं च ददृशुस्ततः॥', 'bharatasya vacaḥ śrutvā puruṣāḥ śastrapāṇayaḥ
viviśus tad vanaṃ śūrā dhūmaṃ ca dadṛśus tataḥ', null, 2087021),
('ramayana-2-87-22', 22, 'Ayodhya Kanda, Sarga 87, Verse 22', 'ते समालोक्य धूमाग्रमूचुर्भरतमागताः।
नामनुष्ये भवत्यग्निर्व्यक्तमत्रैव राघवौ॥', 'te samālokya dhūmāgram ūcur bharatam āgatāḥ
nāmanuṣye bhavaty agnir vyaktam atraiva rāghavau', null, 2087022),
('ramayana-2-87-23', 23, 'Ayodhya Kanda, Sarga 87, Verse 23', 'अथ नात्र नरव्याघ्रौ राजपुत्रौ परंतपौ।
अन्ये रामोपमाः सन्ति व्यक्तमत्र तपस्विनः॥', 'atha nātra naravyāghrau rājaputrau paraṃtapau
anye rāmopamāḥ santi vyaktam atra tapasvinaḥ', null, 2087023),
('ramayana-2-87-24', 24, 'Ayodhya Kanda, Sarga 87, Verse 24', 'तच्छ्रुत्वा भरतस्तेषां वचनं साधु संमतम्।
सैन्यानुवाच सर्वांस्तानमित्रबलमर्दनः॥', 'tac chrutvā bharatas teṣāṃ vacanaṃ sādhu saṃmatam
sainyān uvāca sarvāṃs tān amitrabalamardanaḥ', null, 2087024),
('ramayana-2-87-25', 25, 'Ayodhya Kanda, Sarga 87, Verse 25', 'यत्ता भवन्तस्तिष्ठन्तु नेतो गन्तव्यमग्रतः।
अहमेव गमिष्यामि सुमन्त्रो गुरुरेव च॥', 'yat tā bhavantas tiṣṭhantu neto gantavyam agrataḥ
aham eva gamiṣyāmi sumantro gurur eva ca', null, 2087025),
('ramayana-2-87-26', 26, 'Ayodhya Kanda, Sarga 87, Verse 26', 'एवमुक्तास्ततः सर्वे तत्र तस्थुः समन्ततः।
भरतो यत्र धूमाग्रं तत्र दृष्टिं समादधत्॥', 'evam uktās tataḥ sarve tatra tasthuḥ samantataḥ
bharato yatra dhūmāgraṃ tatra dṛṣṭiṃ samādadhat', null, 2087026),
('ramayana-2-87-27', 27, 'Ayodhya Kanda, Sarga 87, Verse 27', 'व्यवस्थिता या भरतेन सा चमूर्निरीक्षमाणापि च धूममग्रतः।
बभूव हृष्टा नचिरेण जानती प्रियस्य रामस्य समागमं तदा॥', 'vyavasthitā yā bharatena sā camūr nirīkṣamāṇāpi ca dhūmam agrataḥ
babhūva hṛṣṭā nacireṇa jānatī priyasya rāmasya samāgamaṃ tadā', null, 2087027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 88 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-88-1', 1, 'Ayodhya Kanda, Sarga 88, Verse 1', 'दीर्घकालोषितस्तस्मिन्गिरौ गिरिवनप्रियः।
विदेह्याः प्रियमाकाङ्क्षन्स्वं च चित्तं विलोभयन्॥', 'dīrghakāloṣitas tasmin girau girivanapriyaḥ
videhyāḥ priyamākāṅkṣan svaṃ ca cittaṃ vilobhayan', null, 2088001),
('ramayana-2-88-2', 2, 'Ayodhya Kanda, Sarga 88, Verse 2', 'अथ दाशरथिश्चित्रं चित्रकूटमदर्शयत्।
भार्याममरसंकाशः शचीमिव पुरंदरः॥', 'atha dāśarathiś citraṃ citrakūṭam adarśayat
bhāryām amarasaṃkāśaḥ śacīm iva puraṃdaraḥ', null, 2088002),
('ramayana-2-88-3', 3, 'Ayodhya Kanda, Sarga 88, Verse 3', 'न राज्याद्भ्रंशनं भद्रे न सुहृद्भिर्विनाभवः।
मनो मे बाधते दृष्ट्वा रमणीयमिमं गिरिम्॥', 'na rājyād bhraṃśanaṃ bhadre na suhṛdbhir vinābhavaḥ
mano me bādhate dṛṣṭvā ramaṇīyam imaṃ girim', null, 2088003),
('ramayana-2-88-4', 4, 'Ayodhya Kanda, Sarga 88, Verse 4', 'पश्येममचलं भद्रे नानाद्विजगणायुतम्।
शिखरैः खमिवोद्विद्धैर्धातुमद्भिर्विभूषितम्॥', 'paśyemam acalaṃ bhadre nānādvijagaṇāyutam
śikharaiḥ kham ivodviddhair dhātumadbhir vibhūṣitam', null, 2088004),
('ramayana-2-88-5', 5, 'Ayodhya Kanda, Sarga 88, Verse 5', 'के चिद्रजतसंकाशाः के चित्क्षतजसंनिभाः।
पीतमाञ्जिष्ठवर्णाश्च के चिन्मणिवरप्रभाः॥', 'ke cid rajatasaṃkāśāḥ ke cit kṣatajasaṃnibhāḥ
pītamāñjiṣṭhavarṇāś ca ke cin maṇivaraprabhāḥ', null, 2088005),
('ramayana-2-88-6', 6, 'Ayodhya Kanda, Sarga 88, Verse 6', 'पुष्यार्ककेतुकाभाश्च के चिज्ज्योती रसप्रभाः।
विराजन्तेऽचलेन्द्रस्य देशा धातुविभूषिताः॥', 'puṣyārkaketukābhāś ca ke cij jyotī rasaprabhāḥ
virājante ''calendrasya deśā dhātuvibhūṣitāḥ', null, 2088006),
('ramayana-2-88-7', 7, 'Ayodhya Kanda, Sarga 88, Verse 7', 'नानामृगगणद्वीपितरक्ष्वृक्षगणैर्वृतः।
अदुष्टैर्भात्ययं शैलो बहुपक्षिसमाकुलः॥', 'nānāmṛgagaṇadvīpitarakṣvṛkṣagaṇair vṛtaḥ
aduṣṭair bhāty ayaṃ śailo bahupakṣisamākulaḥ', null, 2088007),
('ramayana-2-88-8', 8, 'Ayodhya Kanda, Sarga 88, Verse 8', 'आम्रजम्ब्वसनैर्लोध्रैः प्रियालैः पनसैर्धवैः।
अङ्कोलैर्भव्यतिनिशैर्बिल्वतिन्दुकवेणुभिः॥', 'āmrajambvasanair lodhraiḥ priyālaiḥ panasair dhavaiḥ
aṅkolair bhavyatiniśair bilvatindukaveṇubhiḥ', null, 2088008),
('ramayana-2-88-9', 9, 'Ayodhya Kanda, Sarga 88, Verse 9', 'काश्मर्यरिष्टवरणैर्मधूकैस्तिलकैस्तथा।
बदर्यामलकैर्नीपैर्वेत्रधन्वनबीजकैः॥', 'kāśmaryariṣṭavaraṇair madhūkais tilakais tathā
badaryāmalakair nīpair vetradhanvanabījakaiḥ', null, 2088009),
('ramayana-2-88-10', 10, 'Ayodhya Kanda, Sarga 88, Verse 10', 'पुष्पवद्भिः फलोपेतैश्छायावद्भिर्मनोरमैः।
एवमादिभिराकीर्णः श्रियं पुष्यत्ययं गिरिः॥', 'puṣpavadbhiḥ phalopetaiś chāyāvadbhir manoramaiḥ
evamādibhir ākīrṇaḥ śriyaṃ puṣyaty ayaṃ giriḥ', null, 2088010),
('ramayana-2-88-11', 11, 'Ayodhya Kanda, Sarga 88, Verse 11', 'शैलप्रस्थेषु रम्येषु पश्येमान्कामहर्षणान्।
किन्नरान्द्वंद्वशो भद्रे रममाणान्मनस्विनः॥', 'śailaprastheṣu ramyeṣu paśyemān kāmaharṣaṇān
kinnarān dvaṃdvaśo bhadre ramamāṇān manasvinaḥ', null, 2088011),
('ramayana-2-88-12', 12, 'Ayodhya Kanda, Sarga 88, Verse 12', 'शाखावसक्तान्खड्गांश्च प्रवराण्यम्बराणि च।
पश्य विद्याधरस्त्रीणां क्रीडेद्देशान्मनोरमान्॥', 'śākhāvasaktān khaḍgāṃś ca pravarāṇy ambarāṇi ca
paśya vidyādharastrīṇāṃ krīḍed deśān manoramān', null, 2088012),
('ramayana-2-88-13', 13, 'Ayodhya Kanda, Sarga 88, Verse 13', 'जलप्रपातैरुद्भेदैर्निष्यन्दैश्च क्व चित्क्व चित्।
स्रवद्भिर्भात्ययं शैलः स्रवन्मद इव द्विपः॥', 'jalaprapātair udbhedair niṣyandaiś ca kva cit kva cit
sravadbhir bhāty ayaṃ śailaḥ sravan mada iva dvipaḥ', null, 2088013),
('ramayana-2-88-14', 14, 'Ayodhya Kanda, Sarga 88, Verse 14', 'गुहासमीरणो गन्धान्नानापुष्पभवान्वहन्।
घ्राणतर्पणमभ्येत्य कं नरं न प्रहर्षयेत्॥', 'guhāsamīraṇo gandhān nānāpuṣpabhavān vahan
ghrāṇatarpaṇam abhyetya kaṃ naraṃ na praharṣayet', null, 2088014),
('ramayana-2-88-15', 15, 'Ayodhya Kanda, Sarga 88, Verse 15', 'यदीह शरदोऽनेकास्त्वया सार्धमनिन्दिते।
लक्ष्मणेन च वत्स्यामि न मां शोकः प्रधक्ष्यति॥', 'yadīha śarado ''nekās tvayā sārdham anindite
lakṣmaṇena ca vatsyāmi na māṃ śokaḥ pradhakṣyati', null, 2088015),
('ramayana-2-88-16', 16, 'Ayodhya Kanda, Sarga 88, Verse 16', 'बहुपुष्पफले रम्ये नानाद्विजगणायुते।
विचित्रशिखरे ह्यस्मिन्रतवानस्मि भामिनि॥', 'bahupuṣpaphale ramye nānādvijagaṇāyute
vicitraśikhare hy asmin ratavān asmi bhāmini', null, 2088016),
('ramayana-2-88-17', 17, 'Ayodhya Kanda, Sarga 88, Verse 17', 'अनेन वनवासेन मया प्राप्तं फलद्वयम्।
पितुश्चानृणता धर्मे भरतस्य प्रियं तथा॥', 'anena vanavāsena mayā prāptaṃ phaladvayam
pituś cānṛṇatā dharme bharatasya priyaṃ tathā', null, 2088017),
('ramayana-2-88-18', 18, 'Ayodhya Kanda, Sarga 88, Verse 18', 'वैदेहि रमसे कच्चिच्चित्रकूटे मया सह।
पश्यन्ती विविधान्भावान्मनोवाक्कायसंयतान्॥', 'vaidehi ramase kaccic citrakūṭe mayā saha
paśyantī vividhān bhāvān manovākkāyasaṃyatān', null, 2088018),
('ramayana-2-88-19', 19, 'Ayodhya Kanda, Sarga 88, Verse 19', 'इदमेवामृतं प्राहू राज्ञां राजर्षयः परे।
वनवासं भवार्थाय प्रेत्य मे प्रपितामहाः॥', 'idam evāmṛtaṃ prāhū rājñāṃ rājarṣayaḥ pare
vanavāsaṃ bhavārthāya pretya me prapitāmahāḥ', null, 2088019),
('ramayana-2-88-20', 20, 'Ayodhya Kanda, Sarga 88, Verse 20', 'शिलाः शैलस्य शोभन्ते विशालाः शतशोऽभितः।
बहुला बहुलैर्वर्णैर्नीलपीतसितारुणैः॥', 'śilāḥ śailasya śobhante viśālāḥ śataśo ''bhitaḥ
bahulā bahulair varṇair nīlapītasitāruṇaiḥ', null, 2088020),
('ramayana-2-88-21', 21, 'Ayodhya Kanda, Sarga 88, Verse 21', 'निशि भान्त्यचलेन्द्रस्य हुताशनशिखा इव।
ओषध्यः स्वप्रभा लक्ष्म्या भ्राजमानाः सहस्रशः॥', 'niśi bhānty acalendrasya hutāśanaśikhā iva
oṣadhyaḥ svaprabhā lakṣmyā bhrājamānāḥ sahasraśaḥ', null, 2088021),
('ramayana-2-88-22', 22, 'Ayodhya Kanda, Sarga 88, Verse 22', 'के चित्क्षयनिभा देशाः के चिदुद्यानसंनिभाः।
के चिदेकशिला भान्ति पर्वतस्यास्य भामिनि॥', 'ke cit kṣayanibhā deśāḥ ke cid udyānasaṃnibhāḥ
ke cid ekaśilā bhānti parvatasyāsya bhāmini', null, 2088022),
('ramayana-2-88-23', 23, 'Ayodhya Kanda, Sarga 88, Verse 23', 'भित्त्वेव वसुधां भाति चित्रकूटः समुत्थितः।
चित्रकूटस्य कूटोऽसौ दृश्यते सर्वतः शिवः॥', 'bhittveva vasudhāṃ bhāti citrakūṭaḥ samutthitaḥ
citrakūṭasya kūṭo ''sau dṛśyate sarvataḥ śivaḥ', null, 2088023),
('ramayana-2-88-24', 24, 'Ayodhya Kanda, Sarga 88, Verse 24', 'कुष्ठपुंनागतगरभूर्जपत्रोत्तरच्छदान्।
कामिनां स्वास्तरान्पश्य कुशेशयदलायुतान्॥', 'kuṣṭhapuṃnāgatagarabhūrjapatrottaracchadān
kāmināṃ svāstarān paśya kuśeśayadalāyutān', null, 2088024),
('ramayana-2-88-25', 25, 'Ayodhya Kanda, Sarga 88, Verse 25', 'मृदिताश्चापविद्धाश्च दृश्यन्ते कमलस्रजः।
कामिभिर्वनिते पश्य फलानि विविधानि च॥', 'mṛditāś cāpaviddhāś ca dṛśyante kamalasrajaḥ
kāmibhir vanite paśya phalāni vividhāni ca', null, 2088025),
('ramayana-2-88-26', 26, 'Ayodhya Kanda, Sarga 88, Verse 26', 'वस्वौकसारां नलिनीमत्येतीवोत्तरान्कुरून्।
पर्वतश्चित्रकूटोऽसौ बहुमूलफलोदकः॥', 'vasvaukasārāṃ nalinīm atyetīvottarān kurūn
parvataś citrakūṭo ''sau bahumūlaphalodakaḥ', null, 2088026),
('ramayana-2-88-27', 27, 'Ayodhya Kanda, Sarga 88, Verse 27', 'इमं तु कालं वनिते विजह्रिवांस्त्वया च सीते सह लक्ष्मणेन च।
रतिं प्रपत्स्ये कुलधर्मवर्धिनीं सतां पथि स्वैर्नियमैः परैः स्थितः॥', 'imaṃ tu kālaṃ vanite vijahrivāṃs tvayā ca sīte saha lakṣmaṇena ca
ratiṃ prapatsye kuladharmavardhinīṃ satāṃ pathi svair niyamaiḥ paraiḥ sthitaḥ', null, 2088027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 89 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-89-1', 1, 'Ayodhya Kanda, Sarga 89, Verse 1', 'अथ शैलाद्विनिष्क्रम्य मैथिलीं कोसलेश्वरः।
अदर्शयच्छुभजलां रम्यां मन्दाकिनीं नदीम्॥', 'atha śailād viniṣkramya maithilīṃ kosaleśvaraḥ
adarśayac chubhajalāṃ ramyāṃ mandākinīṃ nadīm', null, 2089001),
('ramayana-2-89-2', 2, 'Ayodhya Kanda, Sarga 89, Verse 2', 'अब्रवीच्च वरारोहां चारुचन्द्रनिभाननाम्।
विदेहराजस्य सुतां रामो राजीवलोचनः॥', 'abravīc ca varārohāṃ cārucandranibhānanām
videharājasya sutāṃ rāmo rājīvalocanaḥ', null, 2089002),
('ramayana-2-89-3', 3, 'Ayodhya Kanda, Sarga 89, Verse 3', 'विचित्रपुलिनां रम्यां हंससारससेविताम्।
कुसुमैरुपसंपन्नां पश्य मन्दाकिनीं नदीम्॥', 'vicitrapulināṃ ramyāṃ haṃsasārasasevitām
kusumair upasaṃpannāṃ paśya mandākinīṃ nadīm', null, 2089003),
('ramayana-2-89-4', 4, 'Ayodhya Kanda, Sarga 89, Verse 4', 'नानाविधैस्तीररुहैर्वृतां पुष्पफलद्रुमैः।
राजन्तीं राजराजस्य नलिनीमिव सर्वतः॥', 'nānāvidhais tīraruhair vṛtāṃ puṣpaphaladrumaiḥ
rājantīṃ rājarājasya nalinīm iva sarvataḥ', null, 2089004),
('ramayana-2-89-5', 5, 'Ayodhya Kanda, Sarga 89, Verse 5', 'मृगयूथनिपीतानि कलुषाम्भांसि साम्प्रतम्।
तीर्थानि रमणीयानि रतिं संजनयन्ति मे॥', 'mṛgayūthanipītāni kaluṣāmbhāṃsi sāmpratam
tīrthāni ramaṇīyāni ratiṃ saṃjanayanti me', null, 2089005),
('ramayana-2-89-6', 6, 'Ayodhya Kanda, Sarga 89, Verse 6', 'जटाजिनधराः काले वल्कलोत्तरवाससः।
ऋषयस्त्ववगाहन्ते नदीं मन्दाकिनीं प्रिये॥', 'jaṭājinadharāḥ kāle valkalottaravāsasaḥ
ṛṣayas tv avagāhante nadīṃ mandākinīṃ priye', null, 2089006),
('ramayana-2-89-7', 7, 'Ayodhya Kanda, Sarga 89, Verse 7', 'आदित्यमुपतिष्ठन्ते नियमादूर्ध्वबाहवः।
एतेऽपरे विशालाक्षि मुनयः संशितव्रताः॥', 'ādityam upatiṣṭhante niyamād ūrdhvabāhavaḥ
ete ''pare viśālākṣi munayaḥ saṃśitavratāḥ', null, 2089007),
('ramayana-2-89-8', 8, 'Ayodhya Kanda, Sarga 89, Verse 8', 'मारुतोद्धूत शिखरैः प्रनृत्त इव पर्वतः।
पादपैः पत्रपुष्पाणि सृजद्भिरभितो नदीम्॥', 'mārutoddhūta śikharaiḥ pranṛtta iva parvataḥ
pādapaiḥ patrapuṣpāṇi sṛjadbhir abhito nadīm', null, 2089008),
('ramayana-2-89-9', 9, 'Ayodhya Kanda, Sarga 89, Verse 9', 'कच्चिन्मणिनिकाशोदां कच्चित्पुलिनशालिनीम्।
कच्चित्सिद्धजनाकीर्णां पश्य मन्दाकिनीं नदीम्॥', 'kaccin maṇinikāśodāṃ kaccit pulinaśālinīm
kaccit siddhajanākīrṇāṃ paśya mandākinīṃ nadīm', null, 2089009),
('ramayana-2-89-10', 10, 'Ayodhya Kanda, Sarga 89, Verse 10', 'निर्धूतान्वायुना पश्य विततान्पुष्पसंचयान्।
पोप्लूयमानानपरान्पश्य त्वं जलमध्यगान्॥', 'nirdhūtān vāyunā paśya vitatān puṣpasaṃcayān
poplūyamānān aparān paśya tvaṃ jalamadhyagān', null, 2089010),
('ramayana-2-89-11', 11, 'Ayodhya Kanda, Sarga 89, Verse 11', 'तांश्चातिवल्गु वचसो रथाङ्गाह्वयना द्विजाः।
अधिरोहन्ति कल्याणि निष्कूजन्तः शुभा गिरः॥', 'tāṃś cātivalgu vacaso rathāṅgāhvayanā dvijāḥ
adhirohanti kalyāṇi niṣkūjantaḥ śubhā giraḥ', null, 2089011),
('ramayana-2-89-12', 12, 'Ayodhya Kanda, Sarga 89, Verse 12', 'दर्शनं चित्रकूटस्य मन्दाकिन्याश्च शोभने।
अधिकं पुरवासाच्च मन्ये च तव दर्शनात्॥', 'darśanaṃ citrakūṭasya mandākinyāś ca śobhane
adhikaṃ puravāsāc ca manye ca tava darśanāt', null, 2089012),
('ramayana-2-89-13', 13, 'Ayodhya Kanda, Sarga 89, Verse 13', 'विधूतकलुषैः सिद्धैस्तपोदमशमान्वितैः।
नित्यविक्षोभित जलां विहाहस्व मया सह॥', 'vidhūtakaluṣaiḥ siddhais tapodamaśamānvitaiḥ
nityavikṣobhita jalāṃ vihāhasva mayā saha', null, 2089013),
('ramayana-2-89-14', 14, 'Ayodhya Kanda, Sarga 89, Verse 14', 'सखीवच्च विगाहस्व सीते मन्दकिनीमिमाम्।
कमलान्यवमज्जन्ती पुष्कराणि च भामिनि॥', 'sakhīvac ca vigāhasva sīte mandakinīm imām
kamalāny avamajjantī puṣkarāṇi ca bhāmini', null, 2089014),
('ramayana-2-89-15', 15, 'Ayodhya Kanda, Sarga 89, Verse 15', 'त्वं पौरजनवद्व्यालानयोध्यामिव पर्वतम्।
मन्यस्व वनिते नित्यं सरयूवदिमां नदीम्॥', 'tvaṃ paurajanavad vyālān ayodhyām iva parvatam
manyasva vanite nityaṃ sarayūvad imāṃ nadīm', null, 2089015),
('ramayana-2-89-16', 16, 'Ayodhya Kanda, Sarga 89, Verse 16', 'लक्ष्मणश्चैव धर्मात्मा मन्निदेशे व्यवस्थितः।
त्वं चानुकूला वैदेहि प्रीतिं जनयथो मम॥', 'lakṣmaṇaś caiva dharmātmā mannideśe vyavasthitaḥ
tvaṃ cānukūlā vaidehi prītiṃ janayatho mama', null, 2089016),
('ramayana-2-89-17', 17, 'Ayodhya Kanda, Sarga 89, Verse 17', 'उपस्पृशंस्त्रिषवणं मधुमूलफलाशनः।
नायोध्यायै न राज्याय स्पृहयेऽद्य त्वया सह॥', 'upaspṛśaṃs triṣavaṇaṃ madhumūlaphalāśanaḥ
nāyodhyāyai na rājyāya spṛhaye ''dya tvayā saha', null, 2089017),
('ramayana-2-89-18', 18, 'Ayodhya Kanda, Sarga 89, Verse 18', 'इमां हि रम्यां गजयूथलोलितां निपीततोयां गजसिंहवानरैः।
सुपुष्पितैः पुष्पधरैरलंकृतां न सोऽस्ति यः स्यान्न गतक्रमः सुखी॥', 'imāṃ hi ramyāṃ gajayūthalolitāṃ nipītatoyāṃ gajasiṃhavānaraiḥ
supuṣpitaiḥ puṣpadharair alaṃkṛtāṃ na so ''sti yaḥ syān na gatakramaḥ sukhī', null, 2089018),
('ramayana-2-89-19', 19, 'Ayodhya Kanda, Sarga 89, Verse 19', 'इतीव रामो बहुसंगतं वचः प्रिया सहायः सरितं प्रति ब्रुवन्।
चचार रम्यं नयनाञ्जनप्रभं स चित्रकूटं रघुवंशवर्धनः॥', 'itīva rāmo bahusaṃgataṃ vacaḥ priyā sahāyaḥ saritaṃ prati bruvan
cacāra ramyaṃ nayanāñjanaprabhaṃ sa citrakūṭaṃ raghuvaṃśavardhanaḥ', null, 2089019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 90 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-90-1', 1, 'Ayodhya Kanda, Sarga 90, Verse 1', 'तथा तत्रासतस्तस्य भरतस्योपयायिनः।
सैन्य रेणुश्च शब्दश्च प्रादुरास्तां नभः स्पृशौ॥', 'tathā tatrāsatas tasya bharatasyopayāyinaḥ
sainya reṇuś ca śabdaś ca prādurāstāṃ nabhaḥ spṛśau', null, 2090001),
('ramayana-2-90-2', 2, 'Ayodhya Kanda, Sarga 90, Verse 2', 'एतस्मिन्नन्तरे त्रस्ताः शब्देन महता ततः।
अर्दिता यूथपा मत्ताः सयूथा दुद्रुवुर्दिशः॥', 'etasminn antare trastāḥ śabdena mahatā tataḥ
arditā yūthapā mattāḥ sayūthā dudruvur diśaḥ', null, 2090002),
('ramayana-2-90-3', 3, 'Ayodhya Kanda, Sarga 90, Verse 3', 'स तं सैन्यसमुद्भूतं शब्दं शुश्रव राघवः।
तांश्च विप्रद्रुतान्सर्वान्यूथपानन्ववैक्षत॥', 'sa taṃ sainyasamudbhūtaṃ śabdaṃ śuśrava rāghavaḥ
tāṃś ca vipradrutān sarvān yūthapān anvavaikṣata', null, 2090003),
('ramayana-2-90-4', 4, 'Ayodhya Kanda, Sarga 90, Verse 4', 'तांश्च विद्रवतो दृष्ट्वा तं च श्रुत्वा स निःस्वनम्।
उवाच रामः सौमित्रिं लक्ष्मणं दीप्ततेजसं॥', 'tāṃś ca vidravato dṛṣṭvā taṃ ca śrutvā sa niḥsvanam
uvāca rāmaḥ saumitriṃ lakṣmaṇaṃ dīptatejasaṃ', null, 2090004),
('ramayana-2-90-5', 5, 'Ayodhya Kanda, Sarga 90, Verse 5', 'हन्त लक्ष्मण पश्येह सुमित्रा सुप्रजास्त्वया।
भीमस्तनितगम्भीरस्तुमुलः श्रूयते स्वनः॥', 'hanta lakṣmaṇa paśyeha sumitrā suprajās tvayā
bhīmastanitagambhīras tumulaḥ śrūyate svanaḥ', null, 2090005),
('ramayana-2-90-6', 6, 'Ayodhya Kanda, Sarga 90, Verse 6', 'राजा वा राजमात्रो वा मृगयामटते वने।
अन्यद्वा श्वापदं किं चित्सौमित्रे ज्ञातुमर्हसि।
सर्वमेतद्यथातत्त्वमचिराज्ज्ञातुमर्हसि॥', 'rājā vā rājamātro vā mṛgayām aṭate vane
anyad vā śvāpadaṃ kiṃ cit saumitre jñātum arhasi
sarvam etad yathātattvam acirāj jñātum arhasi', null, 2090006),
('ramayana-2-90-7', 7, 'Ayodhya Kanda, Sarga 90, Verse 7', 'स लक्ष्मणः संत्वरितः सालमारुह्य पुष्पितम्।
प्रेक्षमाणो दिशः सर्वाः पूर्वां दिशमवैक्षत॥', 'sa lakṣmaṇaḥ saṃtvaritaḥ sālam āruhya puṣpitam
prekṣamāṇo diśaḥ sarvāḥ pūrvāṃ diśam avaikṣata', null, 2090007),
('ramayana-2-90-8', 8, 'Ayodhya Kanda, Sarga 90, Verse 8', 'उदङ्मुखः प्रेक्षमाणो ददर्श महतीं चमूम्।
रथाश्वगजसंबाधां यत्तैर्युक्तां पदातिभिः॥', 'udaṅmukhaḥ prekṣamāṇo dadarśa mahatīṃ camūm
rathāśvagajasaṃbādhāṃ yattair yuktāṃ padātibhiḥ', null, 2090008),
('ramayana-2-90-9', 9, 'Ayodhya Kanda, Sarga 90, Verse 9', 'तामश्वगजसंपूर्णां रथध्वजविभूषिताम्।
शशंस सेनां रामाय वचनं चेदमब्रवीत्॥', 'tām aśvagajasaṃpūrṇāṃ rathadhvajavibhūṣitām
śaśaṃsa senāṃ rāmāya vacanaṃ cedam abravīt', null, 2090009),
('ramayana-2-90-10', 10, 'Ayodhya Kanda, Sarga 90, Verse 10', 'अग्निं संशमयत्वार्यः सीता च भजतां गुहाम्।
सज्यं कुरुष्व चापं च शरांश्च कवचं तथा॥', 'agniṃ saṃśamayatv āryaḥ sītā ca bhajatāṃ guhām
sajyaṃ kuruṣva cāpaṃ ca śarāṃś ca kavacaṃ tathā', null, 2090010),
('ramayana-2-90-11', 11, 'Ayodhya Kanda, Sarga 90, Verse 11', 'तं रामः पुरुषव्याघ्रो लक्ष्मणं प्रत्युवाच ह।
अङ्गावेक्षस्व सौमित्रे कस्यैतां मन्यसे चमूम्॥', 'taṃ rāmaḥ puruṣavyāghro lakṣmaṇaṃ pratyuvāca ha
aṅgāvekṣasva saumitre kasyaitāṃ manyase camūm', null, 2090011),
('ramayana-2-90-12', 12, 'Ayodhya Kanda, Sarga 90, Verse 12', 'एवमुक्क्तस्तु रामेण लक्ष्माणो वाक्यमब्रवीत्।
दिधक्षन्निव तां सेनां रुषितः पावको यथा॥', 'evam ukktas tu rāmeṇa lakṣmāṇo vākyam abravīt
didhakṣann iva tāṃ senāṃ ruṣitaḥ pāvako yathā', null, 2090012),
('ramayana-2-90-13', 13, 'Ayodhya Kanda, Sarga 90, Verse 13', 'संपन्नं राज्यमिच्छंस्तु व्यक्तं प्राप्याभिषेचनम्।
आवां हन्तुं समभ्येति कैकेय्या भरतः सुतः॥', 'saṃpannaṃ rājyam icchaṃs tu vyaktaṃ prāpyābhiṣecanam
āvāṃ hantuṃ samabhyeti kaikeyyā bharataḥ sutaḥ', null, 2090013),
('ramayana-2-90-14', 14, 'Ayodhya Kanda, Sarga 90, Verse 14', 'एष वै सुमहाञ्श्रीमान्विटपी संप्रकाशते।
विराजत्युद्गतस्कन्धः कोविदार ध्वजो रथे॥', 'eṣa vai sumahāñ śrīmān viṭapī saṃprakāśate
virājaty udgataskandhaḥ kovidāra dhvajo rathe', null, 2090014),
('ramayana-2-90-15', 15, 'Ayodhya Kanda, Sarga 90, Verse 15', 'भजन्त्येते यथाकाममश्वानारुह्य शीघ्रगान्।
एते भ्राजन्ति संहृष्टा गजानारुह्य सादिनः॥', 'bhajanty ete yathākāmam aśvān āruhya śīghragān
ete bhrājanti saṃhṛṣṭā gajān āruhya sādinaḥ', null, 2090015),
('ramayana-2-90-16', 16, 'Ayodhya Kanda, Sarga 90, Verse 16', 'गृहीतधनुषौ चावां गिरिं वीर श्रयावहे।
अथ वेहैव तिष्ठावः संनद्धावुद्यतायुधौ।
अपि नौ वशमागच्छेत्कोविदारध्वजो रणे॥', 'gṛhītadhanuṣau cāvāṃ giriṃ vīra śrayāvahe
atha vehaiva tiṣṭhāvaḥ saṃnaddhāv udyatāyudhau
api nau vaśam āgacchet kovidāradhvajo raṇe', null, 2090016),
('ramayana-2-90-17', 17, 'Ayodhya Kanda, Sarga 90, Verse 17', 'अपि द्रक्ष्यामि भरतं यत्कृते व्यसनं महत्।
त्वया राघव संप्राप्तं सीतया च मया तथा॥', 'api drakṣyāmi bharataṃ yatkṛte vyasanaṃ mahat
tvayā rāghava saṃprāptaṃ sītayā ca mayā tathā', null, 2090017),
('ramayana-2-90-18', 18, 'Ayodhya Kanda, Sarga 90, Verse 18', 'यन्निमित्तं भवान्राज्याच्च्युतो राघव शाश्वतीम्।
संप्राप्तोऽयमरिर्वीर भरतो वध्य एव मे॥', 'yannimittaṃ bhavān rājyāc cyuto rāghava śāśvatīm
saṃprāpto ''yam arir vīra bharato vadhya eva me', null, 2090018),
('ramayana-2-90-19', 19, 'Ayodhya Kanda, Sarga 90, Verse 19', 'भरतस्य वधे दोषं नाहं पश्यामि राघव।
पूर्वापकारिणां त्यागे न ह्यधर्मो विधीयते।
एतस्मिन्निहते कृत्स्नामनुशाधि वसुंधराम्॥', 'bharatasya vadhe doṣaṃ nāhaṃ paśyāmi rāghava
pūrvāpakāriṇāṃ tyāge na hy adharmo vidhīyate
etasmin nihate kṛtsnām anuśādhi vasuṃdharām', null, 2090019),
('ramayana-2-90-20', 20, 'Ayodhya Kanda, Sarga 90, Verse 20', 'अद्य पुत्रं हतं संख्ये कैकेयी राज्यकामुका।
मया पश्येत्सुदुःखार्ता हस्तिभग्नमिव द्रुमम्॥', 'adya putraṃ hataṃ saṃkhye kaikeyī rājyakāmukā
mayā paśyet suduḥkhārtā hastibhagnam iva drumam', null, 2090020),
('ramayana-2-90-21', 21, 'Ayodhya Kanda, Sarga 90, Verse 21', 'कैकेयीं च वधिष्यामि सानुबन्धां सबान्धवाम्।
कलुषेणाद्य महता मेदिनी परिमुच्यताम्॥', 'kaikeyīṃ ca vadhiṣyāmi sānubandhāṃ sabāndhavām
kaluṣeṇādya mahatā medinī parimucyatām', null, 2090021),
('ramayana-2-90-22', 22, 'Ayodhya Kanda, Sarga 90, Verse 22', 'अद्येमं संयतं क्रोधमसत्कारं च मानद।
मोक्ष्यामि शत्रुसैन्येषु कक्षेष्विव हुताशनम्॥', 'adyemaṃ saṃyataṃ krodham asatkāraṃ ca mānada
mokṣyāmi śatrusainyeṣu kakṣeṣv iva hutāśanam', null, 2090022),
('ramayana-2-90-23', 23, 'Ayodhya Kanda, Sarga 90, Verse 23', 'अद्यैतच्चित्रकूटस्य काननं निशितैः शरैः।
भिन्दञ्शत्रुशरीराणि करिष्ये शोणितोक्षितम्॥', 'adyaitac citrakūṭasya kānanaṃ niśitaiḥ śaraiḥ
bhindañ śatruśarīrāṇi kariṣye śoṇitokṣitam', null, 2090023),
('ramayana-2-90-24', 24, 'Ayodhya Kanda, Sarga 90, Verse 24', 'शरैर्निर्भिन्नहृदयान्कुञ्जरांस्तुरगांस्तथा।
श्वापदाः परिकर्षन्तु नराश्च निहतान्मया॥', 'śarair nirbhinnahṛdayān kuñjarāṃs turagāṃs tathā
śvāpadāḥ parikarṣantu narāś ca nihatān mayā', null, 2090024),
('ramayana-2-90-25', 25, 'Ayodhya Kanda, Sarga 90, Verse 25', 'शराणां धनुषश्चाहमनृणोऽस्मि महावने।
ससैन्यं भरतं हत्वा भविष्यामि न संशयः॥', 'śarāṇāṃ dhanuṣaś cāham anṛṇo ''smi mahāvane
sasainyaṃ bharataṃ hatvā bhaviṣyāmi na saṃśayaḥ', null, 2090025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 91 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-91-1', 1, 'Ayodhya Kanda, Sarga 91, Verse 1', 'सुसंरब्धं तु सौमित्रिं लक्ष्मणं क्रोधमूर्छितम्।
रामस्तु परिसान्त्व्याथ वचनं चेदमब्रवीत्॥', 'susaṃrabdhaṃ tu saumitriṃ lakṣmaṇaṃ krodhamūrchitam
rāmas tu parisāntvyātha vacanaṃ cedam abravīt', null, 2091001),
('ramayana-2-91-2', 2, 'Ayodhya Kanda, Sarga 91, Verse 2', 'किमत्र धनुषा कार्यमसिना वा सचर्मणा।
महेष्वासे महाप्राज्ञे भरते स्वयमागते॥', 'kim atra dhanuṣā kāryam asinā vā sacarmaṇā
maheṣvāse mahāprājñe bharate svayam āgate', null, 2091002),
('ramayana-2-91-3', 3, 'Ayodhya Kanda, Sarga 91, Verse 3', 'प्राप्तकालं यदेषोऽस्मान्भरतो द्रष्टुमिच्छति।
अस्मासु मनसाप्येष नाहितं किं चिदाचरेत्॥', 'prāptakālaṃ yad eṣo ''smān bharato draṣṭum icchati
asmāsu manasāpy eṣa nāhitaṃ kiṃ cid ācaret', null, 2091003),
('ramayana-2-91-4', 4, 'Ayodhya Kanda, Sarga 91, Verse 4', 'विप्रियं कृतपूर्वं ते भरतेन कदा न किम्।
ईदृशं वा भयं तेऽद्य भरतं योऽत्र शङ्कसे॥', 'vipriyaṃ kṛtapūrvaṃ te bharatena kadā na kim
īdṛśaṃ vā bhayaṃ te ''dya bharataṃ yo ''tra śaṅkase', null, 2091004),
('ramayana-2-91-5', 5, 'Ayodhya Kanda, Sarga 91, Verse 5', 'न हि ते निष्ठुरं वाच्यो भरतो नाप्रियं वचः।
अहं ह्यप्रियमुक्तः स्यां भरतस्याप्रिये कृते॥', 'na hi te niṣṭhuraṃ vācyo bharato nāpriyaṃ vacaḥ
ahaṃ hy apriyam uktaḥ syāṃ bharatasyāpriye kṛte', null, 2091005),
('ramayana-2-91-6', 6, 'Ayodhya Kanda, Sarga 91, Verse 6', 'कथं नु पुत्राः पितरं हन्युः कस्यां चिदापदि।
भ्राता वा भ्रातरं हन्यात्सौमित्रे प्राणमात्मनः॥', 'kathaṃ nu putrāḥ pitaraṃ hanyuḥ kasyāṃ cid āpadi
bhrātā vā bhrātaraṃ hanyāt saumitre prāṇam ātmanaḥ', null, 2091006),
('ramayana-2-91-7', 7, 'Ayodhya Kanda, Sarga 91, Verse 7', 'यदि राज्यस्य हेतोस्त्वमिमां वाचं प्रभाषसे।
वक्ष्यामि भरतं दृष्ट्वा राज्यमस्मै प्रदीयताम्॥', 'yadi rājyasya hetos tvam imāṃ vācaṃ prabhāṣase
vakṣyāmi bharataṃ dṛṣṭvā rājyam asmai pradīyatām', null, 2091007),
('ramayana-2-91-8', 8, 'Ayodhya Kanda, Sarga 91, Verse 8', 'उच्यमानो हि भरतो मया लक्ष्मण तत्त्वतः।
राज्यमस्मै प्रयच्छेति बाढमित्येव वक्ष्यति॥', 'ucyamāno hi bharato mayā lakṣmaṇa tattvataḥ
rājyam asmai prayaccheti bāḍham ity eva vakṣyati', null, 2091008),
('ramayana-2-91-9', 9, 'Ayodhya Kanda, Sarga 91, Verse 9', 'तथोक्तो धर्मशीलेन भ्रात्रा तस्य हिते रतः।
लक्ष्मणः प्रविवेशेव स्वानि गात्राणि लज्जया॥', 'tathokto dharmaśīlena bhrātrā tasya hite rataḥ
lakṣmaṇaḥ praviveśeva svāni gātrāṇi lajjayā', null, 2091009),
('ramayana-2-91-10', 10, 'Ayodhya Kanda, Sarga 91, Verse 10', 'व्रीडितं लक्ष्मणं दृष्ट्वा राघवः प्रत्युवाच ह।
एष मन्ये महाबाहुरिहास्मान्द्रष्टुमागतः॥', 'vrīḍitaṃ lakṣmaṇaṃ dṛṣṭvā rāghavaḥ pratyuvāca ha
eṣa manye mahābāhur ihāsmān draṣṭum āgataḥ', null, 2091010),
('ramayana-2-91-11', 11, 'Ayodhya Kanda, Sarga 91, Verse 11', 'वनवासमनुध्याय गृहाय प्रतिनेष्यति।
इमां वाप्येश वैदेहीमत्यन्तसुखसेविनीम्॥', 'vanavāsam anudhyāya gṛhāya pratineṣyati
imāṃ vāpy eśa vaidehīm atyantasukhasevinīm', null, 2091011),
('ramayana-2-91-12', 12, 'Ayodhya Kanda, Sarga 91, Verse 12', 'एतौ तौ संप्रकाशेते गोत्रवन्तौ मनोरमौ।
वायुवेगसमौ वीर जवनौ तुरगोत्तमौ॥', 'etau tau saṃprakāśete gotravantau manoramau
vāyuvegasamau vīra javanau turagottamau', null, 2091012),
('ramayana-2-91-13', 13, 'Ayodhya Kanda, Sarga 91, Verse 13', 'स एष सुमहाकायः कम्पते वाहिनीमुखे।
नागः शत्रुंजयो नाम वृद्धस्तातस्य धीमतः॥', 'sa eṣa sumahākāyaḥ kampate vāhinīmukhe
nāgaḥ śatruṃjayo nāma vṛddhas tātasya dhīmataḥ', null, 2091013),
('ramayana-2-91-14', 14, 'Ayodhya Kanda, Sarga 91, Verse 14', 'अवतीर्य तु सालाग्रात्तस्मात्स समितिंजयः।
लक्ष्मणः प्राञ्जलिर्भूत्वा तस्थौ रामस्य पार्श्वतः॥', 'avatīrya tu sālāgrāt tasmāt sa samitiṃjayaḥ
lakṣmaṇaḥ prāñjalir bhūtvā tasthau rāmasya pārśvataḥ', null, 2091014),
('ramayana-2-91-15', 15, 'Ayodhya Kanda, Sarga 91, Verse 15', 'भरतेनाथ संदिष्टा संमर्दो न भवेदिति।
समन्तात्तस्य शैलस्य सेनावासमकल्पयत्॥', 'bharatenātha saṃdiṣṭā saṃmardo na bhaved iti
samantāt tasya śailasya senāvāsam akalpayat', null, 2091015),
('ramayana-2-91-16', 16, 'Ayodhya Kanda, Sarga 91, Verse 16', 'अध्यर्धमिक्ष्वाकुचमूर्योजनं पर्वतस्य सा।
पार्श्वे न्यविशदावृत्य गजवाजिरथाकुला॥', 'adhyardham ikṣvākucamūr yojanaṃ parvatasya sā
pārśve nyaviśad āvṛtya gajavājirathākulā', null, 2091016),
('ramayana-2-91-17', 17, 'Ayodhya Kanda, Sarga 91, Verse 17', 'सा चित्रकूटे भरतेन सेना धर्मं पुरस्कृत्य विधूय दर्पम्।
प्रसादनार्थं रघुनन्दनस्य विरोचते नीतिमता प्रणीता॥', 'sā citrakūṭe bharatena senā dharmaṃ puraskṛtya vidhūya darpam
prasādanārthaṃ raghunandanasya virocate nītimatā praṇītā', null, 2091017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 92 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-92-1', 1, 'Ayodhya Kanda, Sarga 92, Verse 1', 'निवेश्य सेनां तु विभुः पद्भ्यां पादवतां वरः।
अभिगन्तुं स काकुत्स्थमियेष गुरुवर्तकम्॥', 'niveśya senāṃ tu vibhuḥ padbhyāṃ pādavatāṃ varaḥ
abhigantuṃ sa kākutstham iyeṣa guruvartakam', null, 2092001),
('ramayana-2-92-2', 2, 'Ayodhya Kanda, Sarga 92, Verse 2', 'निविष्ट मात्रे सैन्ये तु यथोद्देशं विनीतवत्।
भरतो भ्रातरं वाक्यं शत्रुघ्नमिदमब्रवीत्॥', 'niviṣṭa mātre sainye tu yathoddeśaṃ vinītavat
bharato bhrātaraṃ vākyaṃ śatrughnam idam abravīt', null, 2092002),
('ramayana-2-92-3', 3, 'Ayodhya Kanda, Sarga 92, Verse 3', 'क्षिप्रं वनमिदं सौम्य नरसंघैः समन्ततः।
लुब्धैश्च सहितैरेभिस्त्वमन्वेषितुमर्हसि॥', 'kṣipraṃ vanam idaṃ saumya narasaṃghaiḥ samantataḥ
lubdhaiś ca sahitair ebhis tvam anveṣitum arhasi', null, 2092003),
('ramayana-2-92-4', 4, 'Ayodhya Kanda, Sarga 92, Verse 4', 'यावन्न रामं द्रक्ष्यामि लक्ष्मणं वा महाबलम्।
वैदेहीं वा महाभागां न मे शान्तिर्भविष्यति॥', 'yāvan na rāmaṃ drakṣyāmi lakṣmaṇaṃ vā mahābalam
vaidehīṃ vā mahābhāgāṃ na me śāntir bhaviṣyati', null, 2092004),
('ramayana-2-92-5', 5, 'Ayodhya Kanda, Sarga 92, Verse 5', 'यावन्न चन्द्रसंकाशं द्रक्ष्यामि शुभमाननम्।
भ्रातुः पद्मपलाशाक्षं न मे शान्तिर्भविष्यति॥', 'yāvan na candrasaṃkāśaṃ drakṣyāmi śubham ānanam
bhrātuḥ padmapalāśākṣaṃ na me śāntir bhaviṣyati', null, 2092005),
('ramayana-2-92-6', 6, 'Ayodhya Kanda, Sarga 92, Verse 6', 'यावन्न चरणौ भ्रातुः पार्थिव व्यञ्जनान्वितौ।
शिरसा धारयिष्यामि न मे शान्तिर्भविष्यति॥', 'yāvan na caraṇau bhrātuḥ pārthiva vyañjanānvitau
śirasā dhārayiṣyāmi na me śāntir bhaviṣyati', null, 2092006),
('ramayana-2-92-7', 7, 'Ayodhya Kanda, Sarga 92, Verse 7', 'यावन्न राज्ये राज्यार्हः पितृपैतामहे स्थितः।
अभिषेकजलक्लिन्नो न मे शान्तिर्भविष्यति॥', 'yāvan na rājye rājyārhaḥ pitṛpaitāmahe sthitaḥ
abhiṣekajalaklinno na me śāntir bhaviṣyati', null, 2092007),
('ramayana-2-92-8', 8, 'Ayodhya Kanda, Sarga 92, Verse 8', 'कृतकृत्या महाभागा वैदेही जनकात्मजा।
भर्तारं सागरान्तायाः पृथिव्या यानुगच्छति॥', 'kṛtakṛtyā mahābhāgā vaidehī janakātmajā
bhartāraṃ sāgarāntāyāḥ pṛthivyā yānugacchati', null, 2092008),
('ramayana-2-92-9', 9, 'Ayodhya Kanda, Sarga 92, Verse 9', 'सुभगश्चित्रकूटोऽसौ गिरिराजोपमो गिरिः।
यस्मिन्वसति काकुत्स्थः कुबेर इवनन्दने॥', 'subhagaś citrakūṭo ''sau girirājopamo giriḥ
yasmin vasati kākutsthaḥ kubera ivanandane', null, 2092009),
('ramayana-2-92-10', 10, 'Ayodhya Kanda, Sarga 92, Verse 10', 'कृतकार्यमिदं दुर्गं वनं व्यालनिषेवितम्।
यदध्यास्ते महातेजा रामः शस्त्रभृतां वरः॥', 'kṛtakāryam idaṃ durgaṃ vanaṃ vyālaniṣevitam
yad adhyāste mahātejā rāmaḥ śastrabhṛtāṃ varaḥ', null, 2092010),
('ramayana-2-92-11', 11, 'Ayodhya Kanda, Sarga 92, Verse 11', 'एवमुक्त्वा महातेजा भरतः पुरुषर्षभः।
पद्भ्यामेव महातेजाः प्रविवेश महद्वनम्॥', 'evam uktvā mahātejā bharataḥ puruṣarṣabhaḥ
padbhyām eva mahātejāḥ praviveśa mahad vanam', null, 2092011),
('ramayana-2-92-12', 12, 'Ayodhya Kanda, Sarga 92, Verse 12', 'स तानि द्रुमजालानि जातानि गिरिसानुषु।
पुष्पिताग्राणि मध्येन जगाम वदतां वरः॥', 'sa tāni drumajālāni jātāni girisānuṣu
puṣpitāgrāṇi madhyena jagāma vadatāṃ varaḥ', null, 2092012),
('ramayana-2-92-13', 13, 'Ayodhya Kanda, Sarga 92, Verse 13', 'स गिरेश्चित्रकूटस्य सालमासाद्य पुष्पितम्।
रामाश्रमगतस्याग्नेर्ददर्श ध्वजमुच्छ्रितम्॥', 'sa gireś citrakūṭasya sālam āsādya puṣpitam
rāmāśramagatasyāgner dadarśa dhvajam ucchritam', null, 2092013),
('ramayana-2-92-14', 14, 'Ayodhya Kanda, Sarga 92, Verse 14', 'तं दृष्ट्वा भरतः श्रीमान्मुमोद सहबान्धवः।
अत्र राम इति ज्ञात्वा गतः पारमिवाम्भसः॥', 'taṃ dṛṣṭvā bharataḥ śrīmān mumoda sahabāndhavaḥ
atra rāma iti jñātvā gataḥ pāram ivāmbhasaḥ', null, 2092014),
('ramayana-2-92-15', 15, 'Ayodhya Kanda, Sarga 92, Verse 15', 'स चित्रकूटे तु गिरौ निशाम्य रामाश्रमं पुण्यजनोपपन्नम्।
गुहेन सार्धं त्वरितो जगाम पुनर्निवेश्यैव चमूं महात्मा॥', 'sa citrakūṭe tu girau niśāmya rāmāśramaṃ puṇyajanopapannam
guhena sārdhaṃ tvarito jagāma punar niveśyaiva camūṃ mahātmā', null, 2092015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 93 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-93-1', 1, 'Ayodhya Kanda, Sarga 93, Verse 1', 'निविष्टायां तु सेनायामुत्सुको भरतस्तदा।
जगाम भ्रातरं द्रष्टुं शत्रुघ्नमनुदर्शयन्॥', 'niviṣṭāyāṃ tu senāyām utsuko bharatas tadā
jagāma bhrātaraṃ draṣṭuṃ śatrughnam anudarśayan', null, 2093001),
('ramayana-2-93-2', 2, 'Ayodhya Kanda, Sarga 93, Verse 2', 'ऋषिं वसिष्ठं संदिश्य मातॄर्मे शीघ्रमानय।
इति तरितमग्रे स जागम गुरुवत्सलः॥', 'ṛṣiṃ vasiṣṭhaṃ saṃdiśya mātṝr me śīghram ānaya
iti taritam agre sa jāgama guruvatsalaḥ', null, 2093002),
('ramayana-2-93-3', 3, 'Ayodhya Kanda, Sarga 93, Verse 3', 'सुमन्त्रस्त्वपि शतुघ्नमदूरादन्वपद्यत।
रामदार्शनजस्तर्षो भरतस्येव तस्य च॥', 'sumantras tv api śatughnam adūrād anvapadyata
rāmadārśanajas tarṣo bharatasyeva tasya ca', null, 2093003),
('ramayana-2-93-4', 4, 'Ayodhya Kanda, Sarga 93, Verse 4', 'गच्छन्नेवाथ भरतस्तापसालयसंस्थिताम्।
भ्रातुः पर्णकुटीं श्रीमानुटजं च ददर्श ह॥', 'gacchann evātha bharatas tāpasālayasaṃsthitām
bhrātuḥ parṇakuṭīṃ śrīmān uṭajaṃ ca dadarśa ha', null, 2093004),
('ramayana-2-93-5', 5, 'Ayodhya Kanda, Sarga 93, Verse 5', 'शालायास्त्वग्रतस्तस्या ददर्श भरतस्तदा।
काष्टानि चावभग्नानि पुष्पाण्यवचितानि च॥', 'śālāyās tv agratas tasyā dadarśa bharatas tadā
kāṣṭāni cāvabhagnāni puṣpāṇy avacitāni ca', null, 2093005),
('ramayana-2-93-6', 6, 'Ayodhya Kanda, Sarga 93, Verse 6', 'ददर्श च वने तस्मिन्महतः संचयान्कृतान्।
मृगाणां महिषाणां च करीषैः शीतकारणात्॥', 'dadarśa ca vane tasmin mahataḥ saṃcayān kṛtān
mṛgāṇāṃ mahiṣāṇāṃ ca karīṣaiḥ śītakāraṇāt', null, 2093006),
('ramayana-2-93-7', 7, 'Ayodhya Kanda, Sarga 93, Verse 7', 'गच्छनेव महाबाहुर्द्युतिमान्भरतस्तदा।
शत्रुघ्नं चाब्रवीद्धृष्टस्तानमात्यांश्च सर्वशः॥', 'gacchan eva mahābāhur dyutimān bharatas tadā
śatrughnaṃ cābravīd dhṛṣṭas tān amātyāṃś ca sarvaśaḥ', null, 2093007),
('ramayana-2-93-8', 8, 'Ayodhya Kanda, Sarga 93, Verse 8', 'मन्ये प्राप्ताः स्म तं देशं भरद्वाजो यमब्रवीत्।
नातिदूरे हि मन्येऽहं नदीं मन्दाकिनीमितः॥', 'manye prāptāḥ sma taṃ deśaṃ bharadvājo yam abravīt
nātidūre hi manye ''haṃ nadīṃ mandākinīm itaḥ', null, 2093008),
('ramayana-2-93-9', 9, 'Ayodhya Kanda, Sarga 93, Verse 9', 'उच्चैर्बद्धानि चीराणि लक्ष्मणेन भवेदयम्।
अभिज्ञानकृतः पन्था विकाले गन्तुमिच्छता॥', 'uccair baddhāni cīrāṇi lakṣmaṇena bhaved ayam
abhijñānakṛtaḥ panthā vikāle gantum icchatā', null, 2093009),
('ramayana-2-93-10', 10, 'Ayodhya Kanda, Sarga 93, Verse 10', 'इदं चोदात्तदन्तानां कुञ्जराणां तरस्विनाम्।
शैलपार्श्वे परिक्रान्तमन्योन्यमभिगर्जताम्॥', 'idaṃ codāttadantānāṃ kuñjarāṇāṃ tarasvinām
śailapārśve parikrāntam anyonyam abhigarjatām', null, 2093010),
('ramayana-2-93-11', 11, 'Ayodhya Kanda, Sarga 93, Verse 11', 'यमेवाधातुमिच्छन्ति तापसाः सततं वने।
तस्यासौ दृश्यते धूमः संकुलः कृष्टवर्त्मनः॥', 'yam evādhātum icchanti tāpasāḥ satataṃ vane
tasyāsau dṛśyate dhūmaḥ saṃkulaḥ kṛṣṭavartmanaḥ', null, 2093011),
('ramayana-2-93-12', 12, 'Ayodhya Kanda, Sarga 93, Verse 12', 'अत्राहं पुरुषव्याघ्रं गुरुसत्कारकारिणम्।
आर्यं द्रक्ष्यामि संहृष्टो महर्षिमिव राघवम्॥', 'atrāhaṃ puruṣavyāghraṃ gurusatkārakāriṇam
āryaṃ drakṣyāmi saṃhṛṣṭo maharṣim iva rāghavam', null, 2093012),
('ramayana-2-93-13', 13, 'Ayodhya Kanda, Sarga 93, Verse 13', 'अथ गत्वा मुहूर्तं तु चित्रकूटं स राघवः।
मन्दाकिनीमनुप्राप्तस्तं जनं चेदमब्रवीत्॥', 'atha gatvā muhūrtaṃ tu citrakūṭaṃ sa rāghavaḥ
mandākinīm anuprāptas taṃ janaṃ cedam abravīt', null, 2093013),
('ramayana-2-93-14', 14, 'Ayodhya Kanda, Sarga 93, Verse 14', 'जगत्यां पुरुषव्याघ्र आस्ते वीरासने रतः।
जनेन्द्रो निर्जनं प्राप्य धिन्मे जन्म सजीवितम्॥', 'jagatyāṃ puruṣavyāghra āste vīrāsane rataḥ
janendro nirjanaṃ prāpya dhin me janma sajīvitam', null, 2093014),
('ramayana-2-93-15', 15, 'Ayodhya Kanda, Sarga 93, Verse 15', 'मत्कृते व्यसनं प्राप्तो लोकनाथो महाद्युतिः।
सरान्कामान्परित्यज्य वने वसति राघवः॥', 'matkṛte vyasanaṃ prāpto lokanātho mahādyutiḥ
sarān kāmān parityajya vane vasati rāghavaḥ', null, 2093015),
('ramayana-2-93-16', 16, 'Ayodhya Kanda, Sarga 93, Verse 16', 'इति लोकसमाक्रुष्टः पादेष्वद्य प्रसादयन्।
रामस्य निपतिष्यामि सीतायाश्च पुनः पुनः॥', 'iti lokasamākruṣṭaḥ pādeṣv adya prasādayan
rāmasya nipatiṣyāmi sītāyāś ca punaḥ punaḥ', null, 2093016),
('ramayana-2-93-17', 17, 'Ayodhya Kanda, Sarga 93, Verse 17', 'एवं स विलपंस्तस्मिन्वने दशरथात्मजः।
ददर्श महतीं पुण्यां पर्णशालां मनोरमाम्॥', 'evaṃ sa vilapaṃs tasmin vane daśarathātmajaḥ
dadarśa mahatīṃ puṇyāṃ parṇaśālāṃ manoramām', null, 2093017),
('ramayana-2-93-18', 18, 'Ayodhya Kanda, Sarga 93, Verse 18', 'सालतालाश्वकर्णानां पर्णैर्बहुभिरावृताम्।
विशालां मृदुभिस्तीर्णां कुशैर्वेदिमिवाध्वरे॥', 'sālatālāśvakarṇānāṃ parṇair bahubhir āvṛtām
viśālāṃ mṛdubhis tīrṇāṃ kuśair vedim ivādhvare', null, 2093018),
('ramayana-2-93-19', 19, 'Ayodhya Kanda, Sarga 93, Verse 19', 'शक्रायुध निकाशैश्च कार्मुकैर्भारसाधनैः।
रुक्मपृष्ठैर्महासारैः शोभितां शत्रुबाधकैः॥', 'śakrāyudha nikāśaiś ca kārmukair bhārasādhanaiḥ
rukmapṛṣṭhair mahāsāraiḥ śobhitāṃ śatrubādhakaiḥ', null, 2093019),
('ramayana-2-93-20', 20, 'Ayodhya Kanda, Sarga 93, Verse 20', 'अर्करश्मिप्रतीकाशैर्घोरैस्तूणीगतैः शरैः।
शोभितां दीप्तवदनैः सर्पैर्भोगवतीमिव॥', 'arkaraśmipratīkāśair ghorais tūṇīgataiḥ śaraiḥ
śobhitāṃ dīptavadanaiḥ sarpair bhogavatīm iva', null, 2093020),
('ramayana-2-93-21', 21, 'Ayodhya Kanda, Sarga 93, Verse 21', 'महारजतवासोभ्यामसिभ्यां च विराजिताम्।
रुक्मबिन्दुविचित्राभ्यां चर्मभ्यां चापि शोभिताम्॥', 'mahārajatavāsobhyām asibhyāṃ ca virājitām
rukmabinduvicitrābhyāṃ carmabhyāṃ cāpi śobhitām', null, 2093021),
('ramayana-2-93-22', 22, 'Ayodhya Kanda, Sarga 93, Verse 22', 'गोधाङ्गुलित्रैरासाक्तैश्चित्रैः काञ्चनभूषितैः।
अरिसंघैरनाधृष्यां मृगैः सिंहगुहामिव॥', 'godhāṅgulitrair āsāktaiś citraiḥ kāñcanabhūṣitaiḥ
arisaṃghair anādhṛṣyāṃ mṛgaiḥ siṃhaguhām iva', null, 2093022),
('ramayana-2-93-23', 23, 'Ayodhya Kanda, Sarga 93, Verse 23', 'प्रागुदक्स्रवणां वेदिं विशालां दीप्तपावकाम्।
ददर्श भरतस्तत्र पुण्यां रामनिवेशने॥', 'prāgudaksravaṇāṃ vediṃ viśālāṃ dīptapāvakām
dadarśa bharatas tatra puṇyāṃ rāmaniveśane', null, 2093023),
('ramayana-2-93-24', 24, 'Ayodhya Kanda, Sarga 93, Verse 24', 'निरीक्ष्य स मुहूर्तं तु ददर्श भरतो गुरुम्।
उटजे राममासीनां जटामण्डलधारिणम्॥', 'nirīkṣya sa muhūrtaṃ tu dadarśa bharato gurum
uṭaje rāmam āsīnāṃ jaṭāmaṇḍaladhāriṇam', null, 2093024),
('ramayana-2-93-25', 25, 'Ayodhya Kanda, Sarga 93, Verse 25', 'तं तु कृष्णाजिनधरं चीरवल्कलवाससं।
ददर्श राममासीनमभितः पावकोपमम्॥', 'taṃ tu kṛṣṇājinadharaṃ cīravalkalavāsasaṃ
dadarśa rāmam āsīnam abhitaḥ pāvakopamam', null, 2093025),
('ramayana-2-93-26', 26, 'Ayodhya Kanda, Sarga 93, Verse 26', 'सिंहस्कन्धं महाबाहुं पुण्डरीकनिभेक्षणम्।
पृथिव्याः सगरान्ताया भर्तारं धर्मचारिणम्॥', 'siṃhaskandhaṃ mahābāhuṃ puṇḍarīkanibhekṣaṇam
pṛthivyāḥ sagarāntāyā bhartāraṃ dharmacāriṇam', null, 2093026),
('ramayana-2-93-27', 27, 'Ayodhya Kanda, Sarga 93, Verse 27', 'उपविष्टं महाबाहुं ब्रह्माणमिव शाश्वतम्।
स्थण्डिले दर्भसस्म्तीर्णे सीतया लक्ष्मणेन च॥', 'upaviṣṭaṃ mahābāhuṃ brahmāṇam iva śāśvatam
sthaṇḍile darbhasasmtīrṇe sītayā lakṣmaṇena ca', null, 2093027),
('ramayana-2-93-28', 28, 'Ayodhya Kanda, Sarga 93, Verse 28', 'तं दृष्ट्वा भरतः श्रीमान्दुःखमोहपरिप्लुतः।
अभ्यधावत धर्मात्मा भरतः कैकयीसुतः॥', 'taṃ dṛṣṭvā bharataḥ śrīmān duḥkhamohapariplutaḥ
abhyadhāvata dharmātmā bharataḥ kaikayīsutaḥ', null, 2093028),
('ramayana-2-93-29', 29, 'Ayodhya Kanda, Sarga 93, Verse 29', 'दृष्ट्वा च विललापार्तो बाष्पसंदिग्धया गिरा।
अशक्नुवन्धारयितुं धैर्याद्वचनमब्रवीत्॥', 'dṛṣṭvā ca vilalāpārto bāṣpasaṃdigdhayā girā
aśaknuvan dhārayituṃ dhairyād vacanam abravīt', null, 2093029),
('ramayana-2-93-30', 30, 'Ayodhya Kanda, Sarga 93, Verse 30', 'यः संसदि प्रकृतिभिर्भवेद्युक्त उपासितुम्।
वन्यैर्मृगैरुपासीनः सोऽयमास्ते ममाग्रजः॥', 'yaḥ saṃsadi prakṛtibhir bhaved yukta upāsitum
vanyair mṛgair upāsīnaḥ so ''yam āste mamāgrajaḥ', null, 2093030),
('ramayana-2-93-31', 31, 'Ayodhya Kanda, Sarga 93, Verse 31', 'वासोभिर्बहुसाहस्रैर्यो महात्मा पुरोचितः।
मृगाजिने सोऽयमिह प्रवस्ते धर्ममाचरन्॥', 'vāsobhir bahusāhasrair yo mahātmā purocitaḥ
mṛgājine so ''yam iha pravaste dharmam ācaran', null, 2093031),
('ramayana-2-93-32', 32, 'Ayodhya Kanda, Sarga 93, Verse 32', 'अधारयद्यो विविधाश्चित्राः सुमनसस्तदा।
सोऽयं जटाभारमिमं सहते राघवः कथम्॥', 'adhārayad yo vividhāś citrāḥ sumanasas tadā
so ''yaṃ jaṭābhāram imaṃ sahate rāghavaḥ katham', null, 2093032),
('ramayana-2-93-33', 33, 'Ayodhya Kanda, Sarga 93, Verse 33', 'यस्य यज्ञैर्यथादिष्टैर्युक्तो धर्मस्य संचयः।
शरीर क्लेशसंभूतं स धर्मं परिमार्गते॥', 'yasya yajñair yathādiṣṭair yukto dharmasya saṃcayaḥ
śarīra kleśasaṃbhūtaṃ sa dharmaṃ parimārgate', null, 2093033),
('ramayana-2-93-34', 34, 'Ayodhya Kanda, Sarga 93, Verse 34', 'चन्दनेन महार्हेण यस्याङ्गमुपसेवितम्।
मलेन तस्याङ्गमिदं कथमार्यस्य सेव्यते॥', 'candanena mahārheṇa yasyāṅgam upasevitam
malena tasyāṅgam idaṃ katham āryasya sevyate', null, 2093034),
('ramayana-2-93-35', 35, 'Ayodhya Kanda, Sarga 93, Verse 35', 'मन्निमित्तमिदं दुःखं प्राप्तो रामः सुखोचितः।
धिग्जीवितं नृशंसस्य मम लोकविगर्हितम्॥', 'mannimittam idaṃ duḥkhaṃ prāpto rāmaḥ sukhocitaḥ
dhig jīvitaṃ nṛśaṃsasya mama lokavigarhitam', null, 2093035),
('ramayana-2-93-36', 36, 'Ayodhya Kanda, Sarga 93, Verse 36', 'इत्येवं विलपन्दीनः प्रस्विन्नमुखपङ्कजः।
पादावप्राप्य रामस्य पपात भरतो रुदन्॥', 'ity evaṃ vilapan dīnaḥ prasvinnamukhapaṅkajaḥ
pādāv aprāpya rāmasya papāta bharato rudan', null, 2093036),
('ramayana-2-93-37', 37, 'Ayodhya Kanda, Sarga 93, Verse 37', 'दुःखाभितप्तो भरतो राजपुत्रो महाबलः।
उक्त्वार्येति सकृद्दीनं पुनर्नोवाच किं चन॥', 'duḥkhābhitapto bharato rājaputro mahābalaḥ
uktvāryeti sakṛd dīnaṃ punar novāca kiṃ cana', null, 2093037),
('ramayana-2-93-38', 38, 'Ayodhya Kanda, Sarga 93, Verse 38', 'बाष्पापिहित कण्ठश्च प्रेक्ष्य रामं यशस्विनम्।
आर्येत्येवाभिसंक्रुश्य व्याहर्तुं नाशकत्ततः॥', 'bāṣpāpihita kaṇṭhaś ca prekṣya rāmaṃ yaśasvinam
āryety evābhisaṃkruśya vyāhartuṃ nāśakat tataḥ', null, 2093038),
('ramayana-2-93-39', 39, 'Ayodhya Kanda, Sarga 93, Verse 39', 'शत्रुघ्नश्चापि रामस्य ववन्दे चरणौ रुदन्।
तावुभौ स समालिङ्ग्य रामोऽप्यश्रूण्यवर्तयत्॥', 'śatrughnaś cāpi rāmasya vavande caraṇau rudan
tāv ubhau sa samāliṅgya rāmo ''py aśrūṇy avartayat', null, 2093039),
('ramayana-2-93-40', 40, 'Ayodhya Kanda, Sarga 93, Verse 40', 'ततः सुमन्त्रेण गुहेन चैव समीयतू राजसुतावरण्ये।
दिवाकरश्चैव निशाकरश्च यथाम्बरे शुक्रबृहस्पतिभ्याम्॥', 'tataḥ sumantreṇa guhena caiva samīyatū rājasutāv araṇye
divākaraś caiva niśākaraś ca yathāmbare śukrabṛhaspatibhyām', null, 2093040),
('ramayana-2-93-41', 41, 'Ayodhya Kanda, Sarga 93, Verse 41', 'तान्पार्थिवान्वारणयूथपाभान्समागतांस्तत्र महत्यरण्ये।
वनौकसस्तेऽपि समीक्ष्य सर्वेऽप्यश्रूण्यमुञ्चन्प्रविहाय हर्षम्॥', 'tān pārthivān vāraṇayūthapābhān samāgatāṃs tatra mahaty araṇye
vanaukasas te ''pi samīkṣya sarve ''py aśrūṇy amuñcan pravihāya harṣam', null, 2093041)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 94 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-94-1', 1, 'Ayodhya Kanda, Sarga 94, Verse 1', 'आघ्राय रामस्तं मूर्ध्नि परिष्वज्य च राघवः।
अङ्के भरतमारोप्य पर्यपृच्छत्समाहितः॥', 'āghrāya rāmas taṃ mūrdhni pariṣvajya ca rāghavaḥ
aṅke bharatam āropya paryapṛcchat samāhitaḥ', null, 2094001),
('ramayana-2-94-2', 2, 'Ayodhya Kanda, Sarga 94, Verse 2', 'क्व नु तेऽभूत्पिता तात यदरण्यं त्वमागतः।
न हि त्वं जीवतस्तस्य वनमागन्तुमर्हसि॥', 'kva nu te ''bhūt pitā tāta yad araṇyaṃ tvam āgataḥ
na hi tvaṃ jīvatas tasya vanam āgantum arhasi', null, 2094002),
('ramayana-2-94-3', 3, 'Ayodhya Kanda, Sarga 94, Verse 3', 'चिरस्य बत पश्यामि दूराद्भरतमागतम्।
दुष्प्रतीकमरण्येऽस्मिन्किं तात वनमागतः॥', 'cirasya bata paśyāmi dūrād bharatam āgatam
duṣpratīkam araṇye ''smin kiṃ tāta vanam āgataḥ', null, 2094003),
('ramayana-2-94-4', 4, 'Ayodhya Kanda, Sarga 94, Verse 4', 'कच्चिद्दशरथो राजा कुशली सत्यसंगरः।
राजसूयाश्वमेधानामाहर्ता धर्मनिश्चयः॥', 'kaccid daśaratho rājā kuśalī satyasaṃgaraḥ
rājasūyāśvamedhānām āhartā dharmaniścayaḥ', null, 2094004),
('ramayana-2-94-5', 5, 'Ayodhya Kanda, Sarga 94, Verse 5', 'स कच्चिद्ब्राह्मणो विद्वान्धर्मनित्यो महाद्युतिः।
इक्ष्वाकूणामुपाध्यायो यथावत्तात पूज्यते॥', 'sa kaccid brāhmaṇo vidvān dharmanityo mahādyutiḥ
ikṣvākūṇām upādhyāyo yathāvat tāta pūjyate', null, 2094005),
('ramayana-2-94-6', 6, 'Ayodhya Kanda, Sarga 94, Verse 6', 'तात कच्चिच्च कौसल्या सुमित्रा च प्रजावती।
सुखिनी कच्चिदार्या च देवी नन्दति कैकयी॥', 'tāta kaccic ca kausalyā sumitrā ca prajāvatī
sukhinī kaccid āryā ca devī nandati kaikayī', null, 2094006),
('ramayana-2-94-7', 7, 'Ayodhya Kanda, Sarga 94, Verse 7', 'कच्चिद्विनय संपन्नः कुलपुत्रो बहुश्रुतः।
अनसूयुरनुद्रष्टा सत्कृतस्ते पुरोहितः॥', 'kaccid vinaya saṃpannaḥ kulaputro bahuśrutaḥ
anasūyur anudraṣṭā satkṛtas te purohitaḥ', null, 2094007),
('ramayana-2-94-8', 8, 'Ayodhya Kanda, Sarga 94, Verse 8', 'कच्चिदग्निषु ते युक्तो विधिज्ञो मतिमानृजुः।
हुतं च होष्यमाणं च काले वेदयते सदा॥', 'kaccid agniṣu te yukto vidhijño matimān ṛjuḥ
hutaṃ ca hoṣyamāṇaṃ ca kāle vedayate sadā', null, 2094008),
('ramayana-2-94-9', 9, 'Ayodhya Kanda, Sarga 94, Verse 9', 'इष्वस्त्रवरसंपन्नमर्थशास्त्रविशारदम्।
सुधन्वानमुपाध्यायं कच्चित्त्वं तात मन्यसे॥', 'iṣvastravarasaṃpannam arthaśāstraviśāradam
sudhanvānam upādhyāyaṃ kaccit tvaṃ tāta manyase', null, 2094009),
('ramayana-2-94-10', 10, 'Ayodhya Kanda, Sarga 94, Verse 10', 'कच्चिदात्म समाः शूराः श्रुतवन्तो जितेन्द्रियाः।
कुलीनाश्चेङ्गितज्ञाश्च कृतास्ते तात मन्त्रिणः॥', 'kaccid ātma samāḥ śūrāḥ śrutavanto jitendriyāḥ
kulīnāś ceṅgitajñāś ca kṛtās te tāta mantriṇaḥ', null, 2094010),
('ramayana-2-94-11', 11, 'Ayodhya Kanda, Sarga 94, Verse 11', 'मन्त्रो विजयमूलं हि राज्ञां भवति राघव।
सुसंवृतो मन्त्रधरैरमात्यैः शास्त्रकोविदैः॥', 'mantro vijayamūlaṃ hi rājñāṃ bhavati rāghava
susaṃvṛto mantradharair amātyaiḥ śāstrakovidaiḥ', null, 2094011),
('ramayana-2-94-12', 12, 'Ayodhya Kanda, Sarga 94, Verse 12', 'कच्चिन्निद्रावशं नैषि कच्चित्काले विबुध्यसे।
कच्चिंश्चापररात्रिषु चिन्तयस्यर्थनैपुणम्॥', 'kaccin nidrāvaśaṃ naiṣi kaccit kāle vibudhyase
kac ciṃś cāpararātriṣu cintayasy arthanaipuṇam', null, 2094012),
('ramayana-2-94-13', 13, 'Ayodhya Kanda, Sarga 94, Verse 13', 'कच्चिन्मन्त्रयसे नैकः कच्चिन्न बहुभिः सह।
कच्चित्ते मन्त्रितो मन्त्रो राष्ट्रं न परिधावति॥', 'kaccin mantrayase naikaḥ kaccin na bahubhiḥ saha
kaccit te mantrito mantro rāṣṭraṃ na paridhāvati', null, 2094013),
('ramayana-2-94-14', 14, 'Ayodhya Kanda, Sarga 94, Verse 14', 'कच्चिदर्थं विनिश्चित्य लघुमूलं महोदयम्।
क्षिप्रमारभसे कर्तुं न दीर्घयसि राघव॥', 'kaccid arthaṃ viniścitya laghumūlaṃ mahodayam
kṣipram ārabhase kartuṃ na dīrghayasi rāghava', null, 2094014),
('ramayana-2-94-15', 15, 'Ayodhya Kanda, Sarga 94, Verse 15', 'कच्चित्तु सुकृतान्येव कृतरूपाणि वा पुनः।
विदुस्ते सर्वकार्याणि न कर्तव्यानि पार्थिवाः॥', 'kaccit tu sukṛtāny eva kṛtarūpāṇi vā punaḥ
vidus te sarvakāryāṇi na kartavyāni pārthivāḥ', null, 2094015),
('ramayana-2-94-16', 16, 'Ayodhya Kanda, Sarga 94, Verse 16', 'कच्चिन्न तर्कैर्युक्त्वा वा ये चाप्यपरिकीर्तिताः।
त्वया वा तव वामात्यैर्बुध्यते तात मन्त्रितम्॥', 'kaccin na tarkair yuktvā vā ye cāpy aparikīrtitāḥ
tvayā vā tava vāmātyair budhyate tāta mantritam', null, 2094016),
('ramayana-2-94-17', 17, 'Ayodhya Kanda, Sarga 94, Verse 17', 'कच्चित्सहस्रान्मूर्खाणामेकमिच्छसि पण्डितम्।
पण्डितो ह्यर्थकृच्छ्रेषु कुर्यान्निःश्रेयसं महत्॥', 'kaccit sahasrān mūrkhāṇām ekam icchasi paṇḍitam
paṇḍito hy arthakṛcchreṣu kuryān niḥśreyasaṃ mahat', null, 2094017),
('ramayana-2-94-18', 18, 'Ayodhya Kanda, Sarga 94, Verse 18', 'सहस्राण्यपि मूर्खाणां यद्युपास्ते महीपतिः।
अथ वाप्ययुतान्येव नास्ति तेषु सहायता॥', 'sahasrāṇy api mūrkhāṇāṃ yady upāste mahīpatiḥ
atha vāpy ayutāny eva nāsti teṣu sahāyatā', null, 2094018),
('ramayana-2-94-19', 19, 'Ayodhya Kanda, Sarga 94, Verse 19', 'एकोऽप्यमात्यो मेधावी शूरो दक्षो विचक्षणः।
राजानं राजमात्रं वा प्रापयेन्महतीं श्रियम्॥', 'eko ''py amātyo medhāvī śūro dakṣo vicakṣaṇaḥ
rājānaṃ rājamātraṃ vā prāpayen mahatīṃ śriyam', null, 2094019),
('ramayana-2-94-20', 20, 'Ayodhya Kanda, Sarga 94, Verse 20', 'कच्चिन्मुख्या महत्स्वेव मध्यमेषु च मध्यमाः।
जघन्याश्च जघन्येषु भृत्याः कर्मसु योजिताः॥', 'kaccin mukhyā mahatsv eva madhyameṣu ca madhyamāḥ
jaghanyāś ca jaghanyeṣu bhṛtyāḥ karmasu yojitāḥ', null, 2094020),
('ramayana-2-94-21', 21, 'Ayodhya Kanda, Sarga 94, Verse 21', 'अमात्यानुपधातीतान्पितृपैतामहाञ्शुचीन्।
श्रेष्ठाञ्श्रेष्ठेषु कच्चित्त्वं नियोजयसि कर्मसु॥', 'amātyān upadhātītān pitṛpaitāmahāñ śucīn
śreṣṭhāñ śreṣṭheṣu kaccit tvaṃ niyojayasi karmasu', null, 2094021),
('ramayana-2-94-22', 22, 'Ayodhya Kanda, Sarga 94, Verse 22', 'कच्चित्त्वां नावजानन्ति याजकाः पतितं यथा।
उग्रप्रतिग्रहीतारं कामयानमिव स्त्रियः॥', 'kaccit tvāṃ nāvajānanti yājakāḥ patitaṃ yathā
ugrapratigrahītāraṃ kāmayānam iva striyaḥ', null, 2094022),
('ramayana-2-94-23', 23, 'Ayodhya Kanda, Sarga 94, Verse 23', 'उपायकुशलं वैद्यं भृत्यसंदूषणे रतम्।
शूरमैश्वर्यकामं च यो न हन्ति स वध्यते॥', 'upāyakuśalaṃ vaidyaṃ bhṛtyasaṃdūṣaṇe ratam
śūram aiśvaryakāmaṃ ca yo na hanti sa vadhyate', null, 2094023),
('ramayana-2-94-24', 24, 'Ayodhya Kanda, Sarga 94, Verse 24', 'कच्चिद्धृष्टश्च शूरश्च धृतिमान्मतिमाञ्शुचिः।
कुलीनश्चानुरक्तश्च दक्षः सेनापतिः कृतः॥', 'kaccid dhṛṣṭaś ca śūraś ca dhṛtimān matimāñ śuciḥ
kulīnaś cānuraktaś ca dakṣaḥ senāpatiḥ kṛtaḥ', null, 2094024),
('ramayana-2-94-25', 25, 'Ayodhya Kanda, Sarga 94, Verse 25', 'बलवन्तश्च कच्चित्ते मुख्या युद्धविशारदाः।
दृष्टापदाना विक्रान्तास्त्वया सत्कृत्य मानिताः॥', 'balavantaś ca kaccit te mukhyā yuddhaviśāradāḥ
dṛṣṭāpadānā vikrāntās tvayā satkṛtya mānitāḥ', null, 2094025),
('ramayana-2-94-26', 26, 'Ayodhya Kanda, Sarga 94, Verse 26', 'क चिद्बलस्य भक्तं च वेतनं च यथोचितम्।
संप्राप्तकालं दातव्यं ददासि न विलम्बसे॥', 'ka cid balasya bhaktaṃ ca vetanaṃ ca yathocitam
saṃprāptakālaṃ dātavyaṃ dadāsi na vilambase', null, 2094026),
('ramayana-2-94-27', 27, 'Ayodhya Kanda, Sarga 94, Verse 27', 'कालातिक्रमणे ह्येव भक्त वेतनयोर्भृताः।
भर्तुः कुप्यन्ति दुष्यन्ति सोऽनर्थः सुमहान्स्मृतः॥', 'kālātikramaṇe hy eva bhakta vetanayor bhṛtāḥ
bhartuḥ kupyanti duṣyanti so ''narthaḥ sumahān smṛtaḥ', null, 2094027),
('ramayana-2-94-28', 28, 'Ayodhya Kanda, Sarga 94, Verse 28', 'कच्चित्सर्वेऽनुरक्तास्त्वां कुलपुत्राः प्रधानतः।
कच्चित्प्राणांस्तवार्थेषु संत्यजन्ति समाहिताः॥', 'kaccit sarve ''nuraktās tvāṃ kulaputrāḥ pradhānataḥ
kaccit prāṇāṃs tavārtheṣu saṃtyajanti samāhitāḥ', null, 2094028),
('ramayana-2-94-29', 29, 'Ayodhya Kanda, Sarga 94, Verse 29', 'कच्चिज्जानपदो विद्वान्दक्षिणः प्रतिभानवान्।
यथोक्तवादी दूतस्ते कृतो भरत पण्डितः॥', 'kaccij jānapado vidvān dakṣiṇaḥ pratibhānavān
yathoktavādī dūtas te kṛto bharata paṇḍitaḥ', null, 2094029),
('ramayana-2-94-30', 30, 'Ayodhya Kanda, Sarga 94, Verse 30', 'कच्चिदष्टादशान्येषु स्वपक्षे दश पञ्च च।
त्रिभिस्त्रिभिरविज्ञातैर्वेत्सि तीर्थानि चारकैः॥', 'kaccid aṣṭādaśāny eṣu svapakṣe daśa pañca ca
tribhis tribhir avijñātair vetsi tīrthāni cārakaiḥ', null, 2094030),
('ramayana-2-94-31', 31, 'Ayodhya Kanda, Sarga 94, Verse 31', 'कच्चिद्व्यपास्तानहितान्प्रतियातांश्च सर्वदा।
दुर्बलाननवज्ञाय वर्तसे रिपुसूदन॥', 'kaccid vyapāstān ahitān pratiyātāṃś ca sarvadā
durbalān anavajñāya vartase ripusūdana', null, 2094031),
('ramayana-2-94-32', 32, 'Ayodhya Kanda, Sarga 94, Verse 32', 'कच्चिन्न लोकायतिकान्ब्राह्मणांस्तात सेवसे।
अनर्थ कुशला ह्येते बालाः पण्डितमानिनः॥', 'kaccin na lokāyatikān brāhmaṇāṃs tāta sevase
anartha kuśalā hy ete bālāḥ paṇḍitamāninaḥ', null, 2094032),
('ramayana-2-94-33', 33, 'Ayodhya Kanda, Sarga 94, Verse 33', 'धर्मशास्त्रेषु मुख्येषु विद्यमानेषु दुर्बुधाः।
बुद्धिमान्वीक्षिकीं प्राप्य निरर्थं प्रवदन्ति ते॥', 'dharmaśāstreṣu mukhyeṣu vidyamāneṣu durbudhāḥ
buddhimān vīkṣikīṃ prāpya nirarthaṃ pravadanti te', null, 2094033),
('ramayana-2-94-34', 34, 'Ayodhya Kanda, Sarga 94, Verse 34', 'वीरैरध्युषितां पूर्वमस्माकं तात पूर्वकैः।
सत्यनामां दृढद्वारां हस्त्यश्वरथसंकुलाम्॥', 'vīrair adhyuṣitāṃ pūrvam asmākaṃ tāta pūrvakaiḥ
satyanāmāṃ dṛḍhadvārāṃ hastyaśvarathasaṃkulām', null, 2094034),
('ramayana-2-94-35', 35, 'Ayodhya Kanda, Sarga 94, Verse 35', 'ब्राह्मणैः क्षत्रियैर्वैश्यैः स्वकर्मनिरतैः सदा।
जितेन्द्रियैर्महोत्साहैर्वृतामात्यैः सहस्रशः॥', 'brāhmaṇaiḥ kṣatriyair vaiśyaiḥ svakarmanirataiḥ sadā
jitendriyair mahotsāhair vṛtāmātyaiḥ sahasraśaḥ', null, 2094035),
('ramayana-2-94-36', 36, 'Ayodhya Kanda, Sarga 94, Verse 36', 'प्रासादैर्विविधाकारैर्वृतां वैद्यजनाकुलाम्।
कच्चित्समुदितां स्फीतामयोध्यां परिरक्षसि॥', 'prāsādair vividhākārair vṛtāṃ vaidyajanākulām
kaccit samuditāṃ sphītām ayodhyāṃ parirakṣasi', null, 2094036),
('ramayana-2-94-37', 37, 'Ayodhya Kanda, Sarga 94, Verse 37', 'कच्चिच्चैत्यशतैर्जुष्टः सुनिविष्टजनाकुलः।
देवस्थानैः प्रपाभिश्च तडागैश्चोपशोभितः॥', 'kaccic caityaśatair juṣṭaḥ suniviṣṭajanākulaḥ
devasthānaiḥ prapābhiś ca taḍāgaiś copaśobhitaḥ', null, 2094037),
('ramayana-2-94-38', 38, 'Ayodhya Kanda, Sarga 94, Verse 38', 'प्रहृष्टनरनारीकः समाजोत्सवशोभितः।
सुकृष्टसीमा पशुमान्हिंसाभिरभिवर्जितः॥', 'prahṛṣṭanaranārīkaḥ samājotsavaśobhitaḥ
sukṛṣṭasīmā paśumān hiṃsābhir abhivarjitaḥ', null, 2094038),
('ramayana-2-94-39', 39, 'Ayodhya Kanda, Sarga 94, Verse 39', 'अदेवमातृको रम्यः श्वापदैः परिवर्जितः।
कच्चिज्जनपदः स्फीतः सुखं वसति राघव॥', 'adevamātṛko ramyaḥ śvāpadaiḥ parivarjitaḥ
kaccij janapadaḥ sphītaḥ sukhaṃ vasati rāghava', null, 2094039),
('ramayana-2-94-40', 40, 'Ayodhya Kanda, Sarga 94, Verse 40', 'कच्चित्ते दयिताः सर्वे कृषिगोरक्षजीविनः।
वार्तायां संश्रितस्तात लोको हि सुखमेधते॥', 'kaccit te dayitāḥ sarve kṛṣigorakṣajīvinaḥ
vārtāyāṃ saṃśritas tāta loko hi sukham edhate', null, 2094040),
('ramayana-2-94-41', 41, 'Ayodhya Kanda, Sarga 94, Verse 41', 'तेषां गुप्तिपरीहारैः कच्चित्ते भरणं कृतम्।
रक्ष्या हि राज्ञा धर्मेण सर्वे विषयवासिनः॥', 'teṣāṃ guptiparīhāraiḥ kaccit te bharaṇaṃ kṛtam
rakṣyā hi rājñā dharmeṇa sarve viṣayavāsinaḥ', null, 2094041),
('ramayana-2-94-42', 42, 'Ayodhya Kanda, Sarga 94, Verse 42', 'कच्चित्स्त्रियः सान्त्वयसि कच्चित्ताश्च सुरक्षिताः।
कच्चिन्न श्रद्दधास्यासां कच्चिद्गुह्यं न भाषसे॥', 'kaccit striyaḥ sāntvayasi kaccit tāś ca surakṣitāḥ
kaccin na śraddadhāsyāsāṃ kaccid guhyaṃ na bhāṣase', null, 2094042),
('ramayana-2-94-43', 43, 'Ayodhya Kanda, Sarga 94, Verse 43', 'कच्चिन्नागवनं गुप्तं कुञ्जराणां च तृप्यसि।
कच्चिद्दर्शयसे नित्यं मनुष्याणां विभूषितम्।
उत्थायोत्थाय पूर्वाह्णे राजपुत्रो महापथे॥', 'kaccin nāgavanaṃ guptaṃ kuñjarāṇāṃ ca tṛpyasi
kaccid darśayase nityaṃ manuṣyāṇāṃ vibhūṣitam
utthāyotthāya pūrvāhṇe rājaputro mahāpathe', null, 2094043),
('ramayana-2-94-44', 44, 'Ayodhya Kanda, Sarga 94, Verse 44', 'कच्चित्सर्वाणि दुर्गाणि धनधान्यायुधोदकैः।
यन्त्रैश्च परिपूर्णानि तथा शिल्पिधनुर्धरैः॥', 'kaccit sarvāṇi durgāṇi dhanadhānyāyudhodakaiḥ
yantraiś ca paripūrṇāni tathā śilpidhanurdharaiḥ', null, 2094044),
('ramayana-2-94-45', 45, 'Ayodhya Kanda, Sarga 94, Verse 45', 'आयस्ते विपुलः कच्चित्कच्चिदल्पतरो व्ययः।
अपात्रेषु न ते कच्चित्कोशो गच्छति राघव॥', 'āyas te vipulaḥ kaccit kaccid alpataro vyayaḥ
apātreṣu na te kaccit kośo gacchati rāghava', null, 2094045),
('ramayana-2-94-46', 46, 'Ayodhya Kanda, Sarga 94, Verse 46', 'देवतार्थे च पित्रर्थे ब्राह्मणाभ्यागतेषु च।
योधेषु मित्रवर्गेषु कच्चिद्गच्छति ते व्ययः॥', 'devatārthe ca pitrarthe brāhmaṇābhyāgateṣu ca
yodheṣu mitravargeṣu kaccid gacchati te vyayaḥ', null, 2094046),
('ramayana-2-94-47', 47, 'Ayodhya Kanda, Sarga 94, Verse 47', 'कच्चिदार्यो विशुद्धात्मा क्षारितश्चोरकर्मणा।
अपृष्टः शास्त्रकुशलैर्न लोभाद्बध्यते शुचिः॥', 'kaccid āryo viśuddhātmā kṣāritaś corakarmaṇā
apṛṣṭaḥ śāstrakuśalair na lobhād badhyate śuciḥ', null, 2094047),
('ramayana-2-94-48', 48, 'Ayodhya Kanda, Sarga 94, Verse 48', 'गृहीतश्चैव पृष्टश्च काले दृष्टः सकारणः।
कच्चिन्न मुच्यते चोरो धनलोभान्नरर्षभ॥', 'gṛhītaś caiva pṛṣṭaś ca kāle dṛṣṭaḥ sakāraṇaḥ
kaccin na mucyate coro dhanalobhān nararṣabha', null, 2094048),
('ramayana-2-94-49', 49, 'Ayodhya Kanda, Sarga 94, Verse 49', 'व्यसने कच्चिदाढ्यस्य दुगतस्य च राघव।
अर्थं विरागाः पश्यन्ति तवामात्या बहुश्रुताः॥', 'vyasane kaccid āḍhyasya dugatasya ca rāghava
arthaṃ virāgāḥ paśyanti tavāmātyā bahuśrutāḥ', null, 2094049),
('ramayana-2-94-50', 50, 'Ayodhya Kanda, Sarga 94, Verse 50', 'यानि मिथ्याभिशस्तानां पतन्त्यस्राणि राघव।
तानि पुत्रपशून्घ्नन्ति प्रीत्यर्थमनुशासतः॥', 'yāni mithyābhiśastānāṃ patanty asrāṇi rāghava
tāni putrapaśūn ghnanti prītyartham anuśāsataḥ', null, 2094050),
('ramayana-2-94-51', 51, 'Ayodhya Kanda, Sarga 94, Verse 51', 'कच्चिद्वृधांश्च बालांश्च वैद्यमुख्यांश्च राघव।
दानेन मनसा वाचा त्रिभिरेतैर्बुभूषसे॥', 'kaccid vṛdhāṃś ca bālāṃś ca vaidyamukhyāṃś ca rāghava
dānena manasā vācā tribhir etair bubhūṣase', null, 2094051),
('ramayana-2-94-52', 52, 'Ayodhya Kanda, Sarga 94, Verse 52', 'कच्चिद्गुरूंश्च वृद्धांश्च तापसान्देवतातिथीन्।
चैत्यांश्च सर्वान्सिद्धार्थान्ब्राह्मणांश्च नमस्यसि॥', 'kaccid gurūṃś ca vṛddhāṃś ca tāpasān devatātithīn
caityāṃś ca sarvān siddhārthān brāhmaṇāṃś ca namasyasi', null, 2094052),
('ramayana-2-94-53', 53, 'Ayodhya Kanda, Sarga 94, Verse 53', 'कच्चिदर्थेन वा धर्मं धर्मं धर्मेण वा पुनः।
उभौ वा प्रीतिलोभेन कामेन न विबाधसे॥', 'kaccid arthena vā dharmaṃ dharmaṃ dharmeṇa vā punaḥ
ubhau vā prītilobhena kāmena na vibādhase', null, 2094053),
('ramayana-2-94-54', 54, 'Ayodhya Kanda, Sarga 94, Verse 54', 'कच्चिदर्थं च धर्मं च कामं च जयतां वर।
विभज्य काले कालज्ञ सर्वान्भरत सेवसे॥', 'kaccid arthaṃ ca dharmaṃ ca kāmaṃ ca jayatāṃ vara
vibhajya kāle kālajña sarvān bharata sevase', null, 2094054),
('ramayana-2-94-55', 55, 'Ayodhya Kanda, Sarga 94, Verse 55', 'कच्चित्ते ब्राह्मणाः शर्म सर्वशास्त्रार्थकोविदः।
आशंसन्ते महाप्राज्ञ पौरजानपदैः सह॥', 'kaccit te brāhmaṇāḥ śarma sarvaśāstrārthakovidaḥ
āśaṃsante mahāprājña paurajānapadaiḥ saha', null, 2094055),
('ramayana-2-94-56', 56, 'Ayodhya Kanda, Sarga 94, Verse 56', 'नास्तिक्यमनृतं क्रोधं प्रमादं दीर्घसूत्रताम्।
अदर्शनं ज्ञानवतामालस्यं पञ्चवृत्तिताम्॥', 'nāstikyam anṛtaṃ krodhaṃ pramādaṃ dīrghasūtratām
adarśanaṃ jñānavatām ālasyaṃ pañcavṛttitām', null, 2094056),
('ramayana-2-94-57', 57, 'Ayodhya Kanda, Sarga 94, Verse 57', 'एकचिन्तनमर्थानामनर्थज्ञैश्च मन्त्रणम्।
निश्चितानामनारम्भं मन्त्रस्यापरिलक्षणम्॥', 'ekacintanam arthānām anarthajñaiś ca mantraṇam
niścitānām anārambhaṃ mantrasyāparilakṣaṇam', null, 2094057),
('ramayana-2-94-58', 58, 'Ayodhya Kanda, Sarga 94, Verse 58', 'मङ्गलस्याप्रयोगं च प्रत्युत्थानं च सर्वशः।
कच्चित्त्वं वर्जयस्येतान्राजदोषांश्चतुर्दश॥', 'maṅgalasyāprayogaṃ ca pratyutthānaṃ ca sarvaśaḥ
kaccit tvaṃ varjayasy etān rājadoṣāṃś caturdaśa', null, 2094058),
('ramayana-2-94-59', 59, 'Ayodhya Kanda, Sarga 94, Verse 59', 'कच्चित्स्वादुकृतं भोज्यमेको नाश्नासि राघव।
कच्चिदाशंसमानेभ्यो मित्रेभ्यः संप्रयच्छसि॥', 'kaccit svādukṛtaṃ bhojyam eko nāśnāsi rāghava
kaccid āśaṃsamānebhyo mitrebhyaḥ saṃprayacchasi', null, 2094059)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 95 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-95-1', 1, 'Ayodhya Kanda, Sarga 95, Verse 1', 'रामस्य वचनं श्रुत्वा भरतः प्रत्युवाच ह।
किं मे धर्माद्विहीनस्य राजधर्मः करिष्यति॥', 'rāmasya vacanaṃ śrutvā bharataḥ pratyuvāca ha
kiṃ me dharmād vihīnasya rājadharmaḥ kariṣyati', null, 2095001),
('ramayana-2-95-2', 2, 'Ayodhya Kanda, Sarga 95, Verse 2', 'शाश्वतोऽयं सदा धर्मः स्थितोऽस्मासु नरर्षभ।
ज्येष्ठ पुत्रे स्थिते राजन्न कनीयान्भवेन्नृपः॥', 'śāśvato ''yaṃ sadā dharmaḥ sthito ''smāsu nararṣabha
jyeṣṭha putre sthite rājan na kanīyān bhaven nṛpaḥ', null, 2095002),
('ramayana-2-95-3', 3, 'Ayodhya Kanda, Sarga 95, Verse 3', 'स समृद्धां मया सार्धमयोध्यां गच्छ राघव।
अभिषेचय चात्मानं कुलस्यास्य भवाय नः॥', 'sa samṛddhāṃ mayā sārdham ayodhyāṃ gaccha rāghava
abhiṣecaya cātmānaṃ kulasyāsya bhavāya naḥ', null, 2095003),
('ramayana-2-95-4', 4, 'Ayodhya Kanda, Sarga 95, Verse 4', 'राजानं मानुषं प्राहुर्देवत्वे संमतो मम।
यस्य धर्मार्थसहितं वृत्तमाहुरमानुषम्॥', 'rājānaṃ mānuṣaṃ prāhur devatve saṃmato mama
yasya dharmārthasahitaṃ vṛttam āhur amānuṣam', null, 2095004),
('ramayana-2-95-5', 5, 'Ayodhya Kanda, Sarga 95, Verse 5', 'केकयस्थे च मयि तु त्वयि चारण्यमाश्रिते।
दिवमार्य गतो राजा यायजूकः सतां मतः॥', 'kekayasthe ca mayi tu tvayi cāraṇyam āśrite
divam ārya gato rājā yāyajūkaḥ satāṃ mataḥ', null, 2095005),
('ramayana-2-95-6', 6, 'Ayodhya Kanda, Sarga 95, Verse 6', 'उत्तिष्ठ पुरुषव्याघ्र क्रियतामुदकं पितुः।
अहं चायं च शत्रुघ्नः पूर्वमेव कृतोदकौ॥', 'uttiṣṭha puruṣavyāghra kriyatām udakaṃ pituḥ
ahaṃ cāyaṃ ca śatrughnaḥ pūrvam eva kṛtodakau', null, 2095006),
('ramayana-2-95-7', 7, 'Ayodhya Kanda, Sarga 95, Verse 7', 'प्रियेण किल दत्तं हि पितृलोकेषु राघव।
अक्षय्यं भवतीत्याहुर्भवांश्चैव पितुः प्रियः॥', 'priyeṇa kila dattaṃ hi pitṛlokeṣu rāghava
akṣayyaṃ bhavatīty āhur bhavāṃś caiva pituḥ priyaḥ', null, 2095007),
('ramayana-2-95-8', 8, 'Ayodhya Kanda, Sarga 95, Verse 8', 'तां श्रुत्वा करुणां वाचं पितुर्मरणसंहिताम्।
राघवो भरतेनोक्तां बभूव गतचेतनः॥', 'tāṃ śrutvā karuṇāṃ vācaṃ pitur maraṇasaṃhitām
rāghavo bharatenoktāṃ babhūva gatacetanaḥ', null, 2095008),
('ramayana-2-95-9', 9, 'Ayodhya Kanda, Sarga 95, Verse 9', 'वाग्वज्रं भरतेनोक्तममनोज्ञं परंतपः।
प्रगृह्य बाहू रामो वै पुष्पिताग्रो यथा द्रुमः।
वने परशुना कृत्तस्तथा भुवि पपात ह॥', 'vāgvajraṃ bharatenoktam amanojñaṃ paraṃtapaḥ
pragṛhya bāhū rāmo vai puṣpitāgro yathā drumaḥ
vane paraśunā kṛttas tathā bhuvi papāta ha', null, 2095009),
('ramayana-2-95-10', 10, 'Ayodhya Kanda, Sarga 95, Verse 10', 'तथा हि पतितं रामं जगत्यां जगतीपतिम्।
कूलघातपरिश्रान्तं प्रसुप्तमिव कुञ्जरम्॥', 'tathā hi patitaṃ rāmaṃ jagatyāṃ jagatīpatim
kūlaghātapariśrāntaṃ prasuptam iva kuñjaram', null, 2095010),
('ramayana-2-95-11', 11, 'Ayodhya Kanda, Sarga 95, Verse 11', 'भ्रातरस्ते महेष्वासं सर्वतः शोककर्शितम्।
रुदन्तः सह वैदेह्या सिषिचुः सलिलेन वै॥', 'bhrātaras te maheṣvāsaṃ sarvataḥ śokakarśitam
rudantaḥ saha vaidehyā siṣicuḥ salilena vai', null, 2095011),
('ramayana-2-95-12', 12, 'Ayodhya Kanda, Sarga 95, Verse 12', 'स तु संज्ञां पुनर्लब्ध्वा नेत्राभ्यामास्रमुत्सृजन्।
उपाक्रामत काकुत्स्थः कृपणं बहुभाषितुम्॥', 'sa tu saṃjñāṃ punar labdhvā netrābhyām āsram utsṛjan
upākrāmata kākutsthaḥ kṛpaṇaṃ bahubhāṣitum', null, 2095012),
('ramayana-2-95-13', 13, 'Ayodhya Kanda, Sarga 95, Verse 13', 'किं नु तस्य मया कार्यं दुर्जातेन महात्मना।
यो मृतो मम शोकेन न मया चापि संस्कृतः॥', 'kiṃ nu tasya mayā kāryaṃ durjātena mahātmanā
yo mṛto mama śokena na mayā cāpi saṃskṛtaḥ', null, 2095013),
('ramayana-2-95-14', 14, 'Ayodhya Kanda, Sarga 95, Verse 14', 'अहो भरत सिद्धार्थो येन राजा त्वयानघ।
शत्रुघेण च सर्वेषु प्रेतकृत्येषु सत्कृतः॥', 'aho bharata siddhārtho yena rājā tvayānagha
śatrugheṇa ca sarveṣu pretakṛtyeṣu satkṛtaḥ', null, 2095014),
('ramayana-2-95-15', 15, 'Ayodhya Kanda, Sarga 95, Verse 15', 'निष्प्रधानामनेकाग्रं नरेन्द्रेण विनाकृताम्।
निवृत्तवनवासोऽपि नायोध्यां गन्तुमुत्सहे॥', 'niṣpradhānām anekāgraṃ narendreṇa vinākṛtām
nivṛttavanavāso ''pi nāyodhyāṃ gantum utsahe', null, 2095015),
('ramayana-2-95-16', 16, 'Ayodhya Kanda, Sarga 95, Verse 16', 'समाप्तवनवासं मामयोध्यायां परंतप।
को नु शासिष्यति पुनस्ताते लोकान्तरं गते॥', 'samāptavanavāsaṃ mām ayodhyāyāṃ paraṃtapa
ko nu śāsiṣyati punas tāte lokāntaraṃ gate', null, 2095016),
('ramayana-2-95-17', 17, 'Ayodhya Kanda, Sarga 95, Verse 17', 'पुरा प्रेक्ष्य सुवृत्तं मां पिता यान्याह सान्त्वयन्।
वाक्यानि तानि श्रोष्यामि कुतः कर्णसुखान्यहम्॥', 'purā prekṣya suvṛttaṃ māṃ pitā yāny āha sāntvayan
vākyāni tāni śroṣyāmi kutaḥ karṇasukhāny aham', null, 2095017),
('ramayana-2-95-18', 18, 'Ayodhya Kanda, Sarga 95, Verse 18', 'एवमुक्त्वा स भरतं भार्यामभ्येत्य राघवः।
उवाच शोकसंतप्तः पूर्णचन्द्रनिभाननाम्॥', 'evam uktvā sa bharataṃ bhāryām abhyetya rāghavaḥ
uvāca śokasaṃtaptaḥ pūrṇacandranibhānanām', null, 2095018),
('ramayana-2-95-19', 19, 'Ayodhya Kanda, Sarga 95, Verse 19', 'सीते मृतस्ते श्वशुरः पित्रा हीनोऽसि लक्ष्मण।
भरतो दुःखमाचष्टे स्वर्गतं पृथिवीपतिम्॥', 'sīte mṛtas te śvaśuraḥ pitrā hīno ''si lakṣmaṇa
bharato duḥkham ācaṣṭe svargataṃ pṛthivīpatim', null, 2095019),
('ramayana-2-95-20', 20, 'Ayodhya Kanda, Sarga 95, Verse 20', 'सान्त्वयित्वा तु तां रामो रुदन्तीं जनकात्मजाम्।
उवाच लक्ष्मणं तत्र दुःखितो दुःखितं वचः॥', 'sāntvayitvā tu tāṃ rāmo rudantīṃ janakātmajām
uvāca lakṣmaṇaṃ tatra duḥkhito duḥkhitaṃ vacaḥ', null, 2095020),
('ramayana-2-95-21', 21, 'Ayodhya Kanda, Sarga 95, Verse 21', 'आनयेङ्गुदिपिण्याकं चीरमाहर चोत्तरम्।
जलक्रियार्थं तातस्य गमिष्यामि महात्मनः॥', 'ānayeṅgudipiṇyākaṃ cīram āhara cottaram
jalakriyārthaṃ tātasya gamiṣyāmi mahātmanaḥ', null, 2095021),
('ramayana-2-95-22', 22, 'Ayodhya Kanda, Sarga 95, Verse 22', 'सीता पुरस्ताद्व्रजतु त्वमेनामभितो व्रज।
अहं पश्चाद्गमिष्यामि गतिर्ह्येषा सुदारुणा॥', 'sītā purastād vrajatu tvam enām abhito vraja
ahaṃ paścād gamiṣyāmi gatir hy eṣā sudāruṇā', null, 2095022),
('ramayana-2-95-23', 23, 'Ayodhya Kanda, Sarga 95, Verse 23', 'ततो नित्यानुगस्तेषां विदितात्मा महामतिः।
मृदुर्दान्तश्च शान्तश्च रामे च दृढ भक्तिमान्॥', 'tato nityānugas teṣāṃ viditātmā mahāmatiḥ
mṛdur dāntaś ca śāntaś ca rāme ca dṛḍha bhaktimān', null, 2095023),
('ramayana-2-95-24', 24, 'Ayodhya Kanda, Sarga 95, Verse 24', 'सुमन्त्रस्तैर्नृपसुतैः सार्धमाश्वास्य राघवम्।
अवातारयदालम्ब्य नदीं मन्दाकिनीं शिवाम्॥', 'sumantras tair nṛpasutaiḥ sārdham āśvāsya rāghavam
avātārayad ālambya nadīṃ mandākinīṃ śivām', null, 2095024),
('ramayana-2-95-25', 25, 'Ayodhya Kanda, Sarga 95, Verse 25', 'ते सुतीर्थां ततः कृच्छ्रादुपागम्य यशस्विनः।
नदीं मन्दाकिनीं रम्यां सदा पुष्पितकाननाम्॥', 'te sutīrthāṃ tataḥ kṛcchrād upāgamya yaśasvinaḥ
nadīṃ mandākinīṃ ramyāṃ sadā puṣpitakānanām', null, 2095025),
('ramayana-2-95-26', 26, 'Ayodhya Kanda, Sarga 95, Verse 26', 'शीघ्रस्रोतसमासाद्य तीर्थं शिवमकर्दमम्।
सिषिचुस्तूदकं राज्ञे तत एतद्भवत्विति॥', 'śīghrasrotasam āsādya tīrthaṃ śivam akardamam
siṣicus tūdakaṃ rājñe tata etad bhavatv iti', null, 2095026),
('ramayana-2-95-27', 27, 'Ayodhya Kanda, Sarga 95, Verse 27', 'प्रगृह्य च महीपालो जलपूरितमञ्जलिम्।
दिशं याम्यामभिमुखो रुदन्वचनमब्रवीत्॥', 'pragṛhya ca mahīpālo jalapūritam añjalim
diśaṃ yāmyām abhimukho rudan vacanam abravīt', null, 2095027),
('ramayana-2-95-28', 28, 'Ayodhya Kanda, Sarga 95, Verse 28', 'एतत्ते राजशार्दूल विमलं तोयमक्षयम्।
पितृलोकगतस्याद्य मद्दत्तमुपतिष्ठतु॥', 'etat te rājaśārdūla vimalaṃ toyam akṣayam
pitṛlokagatasyādya maddattam upatiṣṭhatu', null, 2095028),
('ramayana-2-95-29', 29, 'Ayodhya Kanda, Sarga 95, Verse 29', 'ततो मन्दाकिनी तीरात्प्रत्युत्तीर्य स राघवः।
पितुश्चकार तेजस्वी निवापं भ्रातृभिः सह॥', 'tato mandākinī tīrāt pratyuttīrya sa rāghavaḥ
pituś cakāra tejasvī nivāpaṃ bhrātṛbhiḥ saha', null, 2095029),
('ramayana-2-95-30', 30, 'Ayodhya Kanda, Sarga 95, Verse 30', 'ऐङ्गुदं बदरीमिश्रं पिण्याकं दर्भसंस्तरे।
न्यस्य रामः सुदुःखार्तो रुदन्वचनमब्रवीत्॥', 'aiṅgudaṃ badarīmiśraṃ piṇyākaṃ darbhasaṃstare
nyasya rāmaḥ suduḥkhārto rudan vacanam abravīt', null, 2095030),
('ramayana-2-95-31', 31, 'Ayodhya Kanda, Sarga 95, Verse 31', 'इदं भुङ्क्ष्व महाराजप्रीतो यदशना वयम्।
यदन्नः पुरुषो भवति तदन्नास्तस्य देवताः॥', 'idaṃ bhuṅkṣva mahārājaprīto yad aśanā vayam
yadannaḥ puruṣo bhavati tadannās tasya devatāḥ', null, 2095031),
('ramayana-2-95-32', 32, 'Ayodhya Kanda, Sarga 95, Verse 32', 'ततस्तेनैव मार्गेण प्रत्युत्तीर्य नदीतटात्।
आरुरोह नरव्याघ्रो रम्यसानुं महीधरम्॥', 'tatas tenaiva mārgeṇa pratyuttīrya nadītaṭāt
āruroha naravyāghro ramyasānuṃ mahīdharam', null, 2095032),
('ramayana-2-95-33', 33, 'Ayodhya Kanda, Sarga 95, Verse 33', 'ततः पर्णकुटीद्वारमासाद्य जगतीपतिः।
परिजग्राह पाणिभ्यामुभौ भरतलक्ष्मणौ॥', 'tataḥ parṇakuṭīdvāram āsādya jagatīpatiḥ
parijagrāha pāṇibhyām ubhau bharatalakṣmaṇau', null, 2095033),
('ramayana-2-95-34', 34, 'Ayodhya Kanda, Sarga 95, Verse 34', 'तेषां तु रुदतां शब्दात्प्रतिश्रुत्काभवद्गिरौ।
भ्रातॄणां सह वैदेह्या सिंहानां नर्दतामिव॥', 'teṣāṃ tu rudatāṃ śabdāt pratiśrutkābhavad girau
bhrātṝṇāṃ saha vaidehyā siṃhānāṃ nardatām iva', null, 2095034),
('ramayana-2-95-35', 35, 'Ayodhya Kanda, Sarga 95, Verse 35', 'विज्ञाय तुमुलं शब्दं त्रस्ता भरतसैनिकाः।
अब्रुवंश्चापि रामेण भरतः संगतो ध्रुवम्।
तेषामेव महाञ्शब्दः शोचतां पितरं मृतम्॥', 'vijñāya tumulaṃ śabdaṃ trastā bharatasainikāḥ
abruvaṃś cāpi rāmeṇa bharataḥ saṃgato dhruvam
teṣām eva mahāñ śabdaḥ śocatāṃ pitaraṃ mṛtam', null, 2095035),
('ramayana-2-95-36', 36, 'Ayodhya Kanda, Sarga 95, Verse 36', 'अथ वासान्परित्यज्य तं सर्वेऽभिमुखाः स्वनम्।
अप्येक मनसो जग्मुर्यथास्थानं प्रधाविताः॥', 'atha vāsān parityajya taṃ sarve ''bhimukhāḥ svanam
apy eka manaso jagmur yathāsthānaṃ pradhāvitāḥ', null, 2095036),
('ramayana-2-95-37', 37, 'Ayodhya Kanda, Sarga 95, Verse 37', 'हयैरन्ये गजैरन्ये रथैरन्ये स्वलंकृतैः।
सुकुमारास्तथैवान्ये पद्भिरेव नरा ययुः॥', 'hayair anye gajair anye rathair anye svalaṃkṛtaiḥ
sukumārās tathaivānye padbhir eva narā yayuḥ', null, 2095037),
('ramayana-2-95-38', 38, 'Ayodhya Kanda, Sarga 95, Verse 38', 'अचिरप्रोषितं रामं चिरविप्रोषितं यथा।
द्रष्टुकामो जनः सर्वो जगाम सहसाश्रमम्॥', 'aciraproṣitaṃ rāmaṃ ciraviproṣitaṃ yathā
draṣṭukāmo janaḥ sarvo jagāma sahasāśramam', null, 2095038),
('ramayana-2-95-39', 39, 'Ayodhya Kanda, Sarga 95, Verse 39', 'भ्रातॄणां त्वरितास्ते तु द्रष्टुकामाः समागमम्।
ययुर्बहुविधैर्यानैः खुरनेमिसमाकुलैः॥', 'bhrātṝṇāṃ tvaritās te tu draṣṭukāmāḥ samāgamam
yayur bahuvidhair yānaiḥ khuranemisamākulaiḥ', null, 2095039),
('ramayana-2-95-40', 40, 'Ayodhya Kanda, Sarga 95, Verse 40', 'सा भूमिर्बहुभिर्यानैः खुरनेमिसमाहता।
मुमोच तुमुलं शब्दं द्यौरिवाभ्रसमागमे॥', 'sā bhūmir bahubhir yānaiḥ khuranemisamāhatā
mumoca tumulaṃ śabdaṃ dyaur ivābhrasamāgame', null, 2095040),
('ramayana-2-95-41', 41, 'Ayodhya Kanda, Sarga 95, Verse 41', 'तेन वित्रासिता नागाः करेणुपरिवारिताः।
आवासयन्तो गन्धेन जग्मुरन्यद्वनं ततः॥', 'tena vitrāsitā nāgāḥ kareṇuparivāritāḥ
āvāsayanto gandhena jagmur anyad vanaṃ tataḥ', null, 2095041),
('ramayana-2-95-42', 42, 'Ayodhya Kanda, Sarga 95, Verse 42', 'वराहमृगसिंहाश्च महिषाः सर्क्षवानराः।
व्याघ्र गोकर्णगवया वित्रेषुः पृषतैः सह॥', 'varāhamṛgasiṃhāś ca mahiṣāḥ sarkṣavānarāḥ
vyāghra gokarṇagavayā vitreṣuḥ pṛṣataiḥ saha', null, 2095042),
('ramayana-2-95-43', 43, 'Ayodhya Kanda, Sarga 95, Verse 43', 'रथाङ्गसाह्वा नत्यूहा हंसाः कारण्डवाः प्लवाः।
तथा पुंस्कोकिलाः क्रौञ्चा विसंज्ञा भेजिरे दिशः॥', 'rathāṅgasāhvā natyūhā haṃsāḥ kāraṇḍavāḥ plavāḥ
tathā puṃskokilāḥ krauñcā visaṃjñā bhejire diśaḥ', null, 2095043),
('ramayana-2-95-44', 44, 'Ayodhya Kanda, Sarga 95, Verse 44', 'तेन शब्देन वित्रस्तैराकाशं पक्षिभिर्वृतम्।
मनुष्यैरावृता भूमिरुभयं प्रबभौ तदा॥', 'tena śabdena vitrastair ākāśaṃ pakṣibhir vṛtam
manuṣyair āvṛtā bhūmir ubhayaṃ prababhau tadā', null, 2095044),
('ramayana-2-95-45', 45, 'Ayodhya Kanda, Sarga 95, Verse 45', 'तान्नरान्बाष्पपूर्णाक्षान्समीक्ष्याथ सुदुःखितान्।
पर्यष्वजत धर्मज्ञः पितृवन्मातृवच्च सः॥', 'tān narān bāṣpapūrṇākṣān samīkṣyātha suduḥkhitān
paryaṣvajata dharmajñaḥ pitṛvan mātṛvac ca saḥ', null, 2095045),
('ramayana-2-95-46', 46, 'Ayodhya Kanda, Sarga 95, Verse 46', 'स तत्र कांश्चित्परिषस्वजे नरान्नराश्च के चित्तु तमभ्यवादयन्।
चकार सर्वान्सवयस्यबान्धवान्यथार्हमासाद्य तदा नृपात्मजः॥', 'sa tatra kāṃś cit pariṣasvaje narān narāś ca ke cit tu tam abhyavādayan
cakāra sarvān savayasyabāndhavān yathārham āsādya tadā nṛpātmajaḥ', null, 2095046),
('ramayana-2-95-47', 47, 'Ayodhya Kanda, Sarga 95, Verse 47', 'ततः स तेषां रुदतां महात्मनां भुवं च खं चानुविनादयन्स्वनः।
गुहा गिरीणां च दिशश्च संततं मृदङ्गघोषप्रतिमो विशुश्रुवे॥', 'tataḥ sa teṣāṃ rudatāṃ mahātmanāṃ bhuvaṃ ca khaṃ cānuvinādayan svanaḥ
guhā girīṇāṃ ca diśaś ca saṃtataṃ mṛdaṅgaghoṣapratimo viśuśruve', null, 2095047)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 96 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-96-1', 1, 'Ayodhya Kanda, Sarga 96, Verse 1', 'वसिष्ठः पुरतः कृत्वा दारान्दशरथस्य च।
अभिचक्राम तं देशं रामदर्शनतर्षितः॥', 'vasiṣṭhaḥ purataḥ kṛtvā dārān daśarathasya ca
abhicakrāma taṃ deśaṃ rāmadarśanatarṣitaḥ', null, 2096001),
('ramayana-2-96-2', 2, 'Ayodhya Kanda, Sarga 96, Verse 2', 'राजपत्न्यश्च गच्छन्त्यो मन्दं मन्दाकिनीं प्रति।
ददृशुस्तत्र तत्तीर्थं रामलक्ष्मणसेवितम्॥', 'rājapatnyaś ca gacchantyo mandaṃ mandākinīṃ prati
dadṛśus tatra tat tīrthaṃ rāmalakṣmaṇasevitam', null, 2096002),
('ramayana-2-96-3', 3, 'Ayodhya Kanda, Sarga 96, Verse 3', 'कौसल्या बाष्पपूर्णेन मुखेन परिशुष्यता।
सुमित्रामब्रवीद्दीना याश्चान्या राजयोषितः॥', 'kausalyā bāṣpapūrṇena mukhena pariśuṣyatā
sumitrām abravīd dīnā yāś cānyā rājayoṣitaḥ', null, 2096003),
('ramayana-2-96-4', 4, 'Ayodhya Kanda, Sarga 96, Verse 4', 'इदं तेषामनाथानां क्लिष्टमक्लिष्ट कर्मणाम्।
वने प्राक्केवलं तीर्थं ये ते निर्विषयी कृताः॥', 'idaṃ teṣām anāthānāṃ kliṣṭam akliṣṭa karmaṇām
vane prāk kevalaṃ tīrthaṃ ye te nirviṣayī kṛtāḥ', null, 2096004),
('ramayana-2-96-5', 5, 'Ayodhya Kanda, Sarga 96, Verse 5', 'इतः सुमित्रे पुत्रस्ते सदा जलमतन्द्रितः।
स्वयं हरति सौमित्रिर्मम पुत्रस्य कारणात्॥', 'itaḥ sumitre putras te sadā jalam atandritaḥ
svayaṃ harati saumitrir mama putrasya kāraṇāt', null, 2096005),
('ramayana-2-96-6', 6, 'Ayodhya Kanda, Sarga 96, Verse 6', 'दक्षिणाग्रेषु दर्भेषु सा ददर्श महीतले।
पितुरिङ्गुदिपिण्याकं न्यस्तमायतलोचना॥', 'dakṣiṇāgreṣu darbheṣu sā dadarśa mahītale
pitur iṅgudipiṇyākaṃ nyastam āyatalocanā', null, 2096006),
('ramayana-2-96-7', 7, 'Ayodhya Kanda, Sarga 96, Verse 7', 'तं भूमौ पितुरार्तेन न्यस्तं रामेण वीक्ष्य सा।
उवाच देवी कौसल्या सर्वा दशरथस्त्रियः॥', 'taṃ bhūmau pitur ārtena nyastaṃ rāmeṇa vīkṣya sā
uvāca devī kausalyā sarvā daśarathastriyaḥ', null, 2096007),
('ramayana-2-96-8', 8, 'Ayodhya Kanda, Sarga 96, Verse 8', 'इदमिक्ष्वाकुनाथस्य राघवस्य महात्मनः।
राघवेण पितुर्दत्तं पश्यतैतद्यथाविधि॥', 'idam ikṣvākunāthasya rāghavasya mahātmanaḥ
rāghaveṇa pitur dattaṃ paśyataitad yathāvidhi', null, 2096008),
('ramayana-2-96-9', 9, 'Ayodhya Kanda, Sarga 96, Verse 9', 'तस्य देवसमानस्य पार्थिवस्य महात्मनः।
नैतदौपयिकं मन्ये भुक्तभोगस्य भोजनम्॥', 'tasya devasamānasya pārthivasya mahātmanaḥ
naitad aupayikaṃ manye bhuktabhogasya bhojanam', null, 2096009),
('ramayana-2-96-10', 10, 'Ayodhya Kanda, Sarga 96, Verse 10', 'चतुरन्तां महीं भुक्त्वा महेन्द्र सदृशो भुवि।
कथमिङ्गुदिपिण्याकं स भुङ्क्ते वसुधाधिपः॥', 'caturantāṃ mahīṃ bhuktvā mahendra sadṛśo bhuvi
katham iṅgudipiṇyākaṃ sa bhuṅkte vasudhādhipaḥ', null, 2096010),
('ramayana-2-96-11', 11, 'Ayodhya Kanda, Sarga 96, Verse 11', 'अतो दुःखतरं लोके न किं चित्प्रतिभाति मा।
यत्र रामः पितुर्दद्यादिङ्गुदीक्षोदमृद्धिमान्॥', 'ato duḥkhataraṃ loke na kiṃ cit pratibhāti mā
yatra rāmaḥ pitur dadyād iṅgudīkṣodam ṛddhimān', null, 2096011),
('ramayana-2-96-12', 12, 'Ayodhya Kanda, Sarga 96, Verse 12', 'रामेणेङ्गुदिपिण्याकं पितुर्दत्तं समीक्ष्य मे।
कथं दुःखेन हृदयं न स्फोटति सहस्रधा॥', 'rāmeṇeṅgudipiṇyākaṃ pitur dattaṃ samīkṣya me
kathaṃ duḥkhena hṛdayaṃ na sphoṭati sahasradhā', null, 2096012),
('ramayana-2-96-13', 13, 'Ayodhya Kanda, Sarga 96, Verse 13', 'एवमार्तां सपत्न्यस्ता जग्मुराश्वास्य तां तदा।
ददृशुश्चाश्रमे रामं स्वर्गाच्च्युतमिवामरम्॥', 'evam ārtāṃ sapatnyas tā jagmur āśvāsya tāṃ tadā
dadṛśuś cāśrame rāmaṃ svargāc cyutam ivāmaram', null, 2096013),
('ramayana-2-96-14', 14, 'Ayodhya Kanda, Sarga 96, Verse 14', 'सर्वभोगैः परित्यक्तं राम संप्रेक्ष्य मातरः।
आर्ता मुमुचुरश्रूणि सस्वरं शोककर्शिताः॥', 'sarvabhogaiḥ parityaktaṃ rāma saṃprekṣya mātaraḥ
ārtā mumucur aśrūṇi sasvaraṃ śokakarśitāḥ', null, 2096014),
('ramayana-2-96-15', 15, 'Ayodhya Kanda, Sarga 96, Verse 15', 'तासां रामः समुत्थाय जग्राह चरणाञ्शुभान्।
मातॄणां मनुजव्याघ्रः सर्वासां सत्यसंगरः॥', 'tāsāṃ rāmaḥ samutthāya jagrāha caraṇāñ śubhān
mātṝṇāṃ manujavyāghraḥ sarvāsāṃ satyasaṃgaraḥ', null, 2096015),
('ramayana-2-96-16', 16, 'Ayodhya Kanda, Sarga 96, Verse 16', 'ताः पाणिभिः सुखस्पर्शैर्मृद्वङ्गुलितलैः शुभैः।
प्रममार्जू रजः पृष्ठाद्रामस्यायतलोचनाः॥', 'tāḥ pāṇibhiḥ sukhasparśair mṛdvaṅgulitalaiḥ śubhaiḥ
pramamārjū rajaḥ pṛṣṭhād rāmasyāyatalocanāḥ', null, 2096016),
('ramayana-2-96-17', 17, 'Ayodhya Kanda, Sarga 96, Verse 17', 'सौमित्रिरपि ताः सर्वा मातॄः संप्रेक्ष्य दुःखितः।
अभ्यवादयतासक्तं शनै रामादनन्तरम्॥', 'saumitrir api tāḥ sarvā mātṝḥ saṃprekṣya duḥkhitaḥ
abhyavādayatāsaktaṃ śanai rāmād anantaram', null, 2096017),
('ramayana-2-96-18', 18, 'Ayodhya Kanda, Sarga 96, Verse 18', 'यथा रामे तथा तस्मिन्सर्वा ववृतिरे स्त्रियः।
वृत्तिं दशरथाज्जाते लक्ष्मणे शुभलक्षणे॥', 'yathā rāme tathā tasmin sarvā vavṛtire striyaḥ
vṛttiṃ daśarathāj jāte lakṣmaṇe śubhalakṣaṇe', null, 2096018),
('ramayana-2-96-19', 19, 'Ayodhya Kanda, Sarga 96, Verse 19', 'सीतापि चरणांस्तासामुपसंगृह्य दुःखिता।
श्वश्रूणामश्रुपूर्णाक्षी सा बभूवाग्रतः स्थिता॥', 'sītāpi caraṇāṃs tāsām upasaṃgṛhya duḥkhitā
śvaśrūṇām aśrupūrṇākṣī sā babhūvāgrataḥ sthitā', null, 2096019),
('ramayana-2-96-20', 20, 'Ayodhya Kanda, Sarga 96, Verse 20', 'तां परिष्वज्य दुःखार्तां माता दुहितरं यथा।
वनवासकृशां दीनां कौसल्या वाक्यमब्रवीत्॥', 'tāṃ pariṣvajya duḥkhārtāṃ mātā duhitaraṃ yathā
vanavāsakṛśāṃ dīnāṃ kausalyā vākyam abravīt', null, 2096020),
('ramayana-2-96-21', 21, 'Ayodhya Kanda, Sarga 96, Verse 21', 'विदेहराजस्य सुता स्नुषा दशरथस्य च।
रामपत्नी कथं दुःखं संप्राप्ता निर्जने वने॥', 'videharājasya sutā snuṣā daśarathasya ca
rāmapatnī kathaṃ duḥkhaṃ saṃprāptā nirjane vane', null, 2096021),
('ramayana-2-96-22', 22, 'Ayodhya Kanda, Sarga 96, Verse 22', 'पद्ममातपसंतप्तं परिक्लिष्टमिवोत्पलम्।
काञ्चनं रजसा ध्वस्तं क्लिष्टं चन्द्रमिवाम्बुदैः॥', 'padmam ātapasaṃtaptaṃ parikliṣṭam ivotpalam
kāñcanaṃ rajasā dhvastaṃ kliṣṭaṃ candram ivāmbudaiḥ', null, 2096022),
('ramayana-2-96-23', 23, 'Ayodhya Kanda, Sarga 96, Verse 23', 'मुखं ते प्रेक्ष्य मां शोको दहत्यग्निरिवाश्रयम्।
भृशं मनसि वैदेहि व्यसनारणिसंभवः॥', 'mukhaṃ te prekṣya māṃ śoko dahaty agnir ivāśrayam
bhṛśaṃ manasi vaidehi vyasanāraṇisaṃbhavaḥ', null, 2096023),
('ramayana-2-96-24', 24, 'Ayodhya Kanda, Sarga 96, Verse 24', 'ब्रुवन्त्यामेवमार्तायां जनन्यां भरताग्रजः।
पादावासाद्य जग्राह वसिष्ठस्य स राघवः॥', 'bruvantyām evam ārtāyāṃ jananyāṃ bharatāgrajaḥ
pādāv āsādya jagrāha vasiṣṭhasya sa rāghavaḥ', null, 2096024),
('ramayana-2-96-25', 25, 'Ayodhya Kanda, Sarga 96, Verse 25', 'पुरोहितस्याग्निसमस्य तस्य वै बृहस्पतेरिन्द्र इवामराधिपः।
प्रगृह्य पादौ सुसमृद्धतेजसः सहैव तेनोपविवेश राघवः॥', 'purohitasyāgnisamasya tasya vai bṛhaspater indra ivāmarādhipaḥ
pragṛhya pādau susamṛddhatejasaḥ sahaiva tenopaviveśa rāghavaḥ', null, 2096025),
('ramayana-2-96-26', 26, 'Ayodhya Kanda, Sarga 96, Verse 26', 'ततो जघन्यं सहितैः स मन्त्रिभिः पुरप्रधानैश्च सहैव सैनिकैः।
जनेन धर्मज्ञतमेन धर्मवानुपोपविष्टो भरतस्तदाग्रजम्॥', 'tato jaghanyaṃ sahitaiḥ sa mantribhiḥ purapradhānaiś ca sahaiva sainikaiḥ
janena dharmajñatamena dharmavān upopaviṣṭo bharatas tadāgrajam', null, 2096026),
('ramayana-2-96-27', 27, 'Ayodhya Kanda, Sarga 96, Verse 27', 'उपोपविष्टस्तु तदा स वीर्यवांस्तपस्विवेषेण समीक्ष्य राघवम्।
श्रिया ज्वलन्तं भरतः कृताञ्जलिर्यथा महेन्द्रः प्रयतः प्रजापतिम्॥', 'upopaviṣṭas tu tadā sa vīryavāṃs tapasviveṣeṇa samīkṣya rāghavam
śriyā jvalantaṃ bharataḥ kṛtāñjalir yathā mahendraḥ prayataḥ prajāpatim', null, 2096027),
('ramayana-2-96-28', 28, 'Ayodhya Kanda, Sarga 96, Verse 28', 'किमेष वाक्यं भरतोऽद्य राघवं प्रणम्य सत्कृत्य च साधु वक्ष्यति।
इतीव तस्यार्यजनस्य तत्त्वतो बभूव कौतूहलमुत्तमं तदा॥', 'kim eṣa vākyaṃ bharato ''dya rāghavaṃ praṇamya satkṛtya ca sādhu vakṣyati
itīva tasyāryajanasya tattvato babhūva kautūhalam uttamaṃ tadā', null, 2096028),
('ramayana-2-96-29', 29, 'Ayodhya Kanda, Sarga 96, Verse 29', 'स राघवः सत्यधृतिश्च लक्ष्मणो महानुभावो भरतश्च धार्मिकः।
वृताः सुहृद्भिश्च विरेजुरध्वरे यथा सदस्यैः सहितास्त्रयोऽग्नयः॥', 'sa rāghavaḥ satyadhṛtiś ca lakṣmaṇo mahānubhāvo bharataś ca dhārmikaḥ
vṛtāḥ suhṛdbhiś ca virejur adhvare yathā sadasyaiḥ sahitās trayo ''gnayaḥ', null, 2096029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 97 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-97-1', 1, 'Ayodhya Kanda, Sarga 97, Verse 1', 'तं तु रामः समाश्वास्य भ्रातरं गुरुवत्सलम्।
लक्ष्मणेन सह भ्रात्रा प्रष्टुं समुपचक्रमे॥', 'taṃ tu rāmaḥ samāśvāsya bhrātaraṃ guruvatsalam
lakṣmaṇena saha bhrātrā praṣṭuṃ samupacakrame', null, 2097001),
('ramayana-2-97-2', 2, 'Ayodhya Kanda, Sarga 97, Verse 2', 'किमेतदिच्छेयमहं श्रोतुं प्रव्याहृतं त्वया।
यस्मात्त्वमागतो देशमिमं चीरजटाजिनी॥', 'kim etad iccheyam ahaṃ śrotuṃ pravyāhṛtaṃ tvayā
yasmāt tvam āgato deśam imaṃ cīrajaṭājinī', null, 2097002),
('ramayana-2-97-3', 3, 'Ayodhya Kanda, Sarga 97, Verse 3', 'यन्निमित्तमिमं देशं कृष्णाजिनजटाधरः।
हित्वा राज्यं प्रविष्टस्त्वं तत्सर्वं वक्तुमर्हसि॥', 'yannimittam imaṃ deśaṃ kṛṣṇājinajaṭādharaḥ
hitvā rājyaṃ praviṣṭas tvaṃ tat sarvaṃ vaktum arhasi', null, 2097003),
('ramayana-2-97-4', 4, 'Ayodhya Kanda, Sarga 97, Verse 4', 'इत्युक्तः केकयीपुत्रः काकुत्स्थेन महात्मना।
प्रगृह्य बलवद्भूयः प्राञ्जलिर्वाक्यमब्रवीत्॥', 'ity uktaḥ kekayīputraḥ kākutsthena mahātmanā
pragṛhya balavad bhūyaḥ prāñjalir vākyam abravīt', null, 2097004),
('ramayana-2-97-5', 5, 'Ayodhya Kanda, Sarga 97, Verse 5', 'आर्यं तातः परित्यज्य कृत्वा कर्म सुदुष्करम्।
गतः स्वर्गं महाबाहुः पुत्रशोकाभिपीडितः॥', 'āryaṃ tātaḥ parityajya kṛtvā karma suduṣkaram
gataḥ svargaṃ mahābāhuḥ putraśokābhipīḍitaḥ', null, 2097005),
('ramayana-2-97-6', 6, 'Ayodhya Kanda, Sarga 97, Verse 6', 'स्त्रिया नियुक्तः कैकेय्या मम मात्रा परंतप।
चकार सुमहत्पापमिदमात्मयशोहरम्॥', 'striyā niyuktaḥ kaikeyyā mama mātrā paraṃtapa
cakāra sumahat pāpam idam ātmayaśoharam', null, 2097006),
('ramayana-2-97-7', 7, 'Ayodhya Kanda, Sarga 97, Verse 7', 'सा राज्यफलमप्राप्य विधवा शोककर्शिता।
पतिष्यति महाघोरे निरये जननी मम॥', 'sā rājyaphalam aprāpya vidhavā śokakarśitā
patiṣyati mahāghore niraye jananī mama', null, 2097007),
('ramayana-2-97-8', 8, 'Ayodhya Kanda, Sarga 97, Verse 8', 'तस्य मे दासभूतस्य प्रसादं कर्तुमर्हसि।
अभिषिञ्चस्व चाद्यैव राज्येन मघवानिव॥', 'tasya me dāsabhūtasya prasādaṃ kartum arhasi
abhiṣiñcasva cādyaiva rājyena maghavān iva', null, 2097008),
('ramayana-2-97-9', 9, 'Ayodhya Kanda, Sarga 97, Verse 9', 'इमाः प्रकृतयः सर्वा विधवा मातुरश्च याः।
त्वत्सकाशमनुप्राप्ताः प्रसादं कर्तुमर्हसि॥', 'imāḥ prakṛtayaḥ sarvā vidhavā māturaś ca yāḥ
tvat sakāśam anuprāptāḥ prasādaṃ kartum arhasi', null, 2097009),
('ramayana-2-97-10', 10, 'Ayodhya Kanda, Sarga 97, Verse 10', 'तदानुपूर्व्या युक्तं च युक्तं चात्मनि मानद।
राज्यं प्राप्नुहि धर्मेण सकामान्सुहृदः कुरु॥', 'tadānupūrvyā yuktaṃ ca yuktaṃ cātmani mānada
rājyaṃ prāpnuhi dharmeṇa sakāmān suhṛdaḥ kuru', null, 2097010),
('ramayana-2-97-11', 11, 'Ayodhya Kanda, Sarga 97, Verse 11', 'भवत्वविधवा भूमिः समग्रा पतिना त्वया।
शशिना विमलेनेव शारदी रजनी यथा॥', 'bhavatv avidhavā bhūmiḥ samagrā patinā tvayā
śaśinā vimaleneva śāradī rajanī yathā', null, 2097011),
('ramayana-2-97-12', 12, 'Ayodhya Kanda, Sarga 97, Verse 12', 'एभिश्च सचिवैः सार्धं शिरसा याचितो मया।
भ्रातुः शिष्यस्य दासस्य प्रसादं कर्तुमर्हसि॥', 'ebhiś ca sacivaiḥ sārdhaṃ śirasā yācito mayā
bhrātuḥ śiṣyasya dāsasya prasādaṃ kartum arhasi', null, 2097012),
('ramayana-2-97-13', 13, 'Ayodhya Kanda, Sarga 97, Verse 13', 'तदिदं शाश्वतं पित्र्यं सर्वं सचिवमण्डलम्।
पूजितं पुरुषव्याघ्र नातिक्रमितुमुत्सहे॥', 'tad idaṃ śāśvataṃ pitryaṃ sarvaṃ sacivamaṇḍalam
pūjitaṃ puruṣavyāghra nātikramitum utsahe', null, 2097013),
('ramayana-2-97-14', 14, 'Ayodhya Kanda, Sarga 97, Verse 14', 'एवमुक्त्वा महाबाहुः सबाष्पः केकयीसुतः।
रामस्य शिरसा पादौ जग्राह भरतः पुनः॥', 'evam uktvā mahābāhuḥ sabāṣpaḥ kekayīsutaḥ
rāmasya śirasā pādau jagrāha bharataḥ punaḥ', null, 2097014),
('ramayana-2-97-15', 15, 'Ayodhya Kanda, Sarga 97, Verse 15', 'तं मत्तमिव मातङ्गं निःश्वसन्तं पुनः पुनः।
भ्रातरं भरतं रामः परिष्वज्येदमब्रवीत्॥', 'taṃ mattam iva mātaṅgaṃ niḥśvasantaṃ punaḥ punaḥ
bhrātaraṃ bharataṃ rāmaḥ pariṣvajyedam abravīt', null, 2097015),
('ramayana-2-97-16', 16, 'Ayodhya Kanda, Sarga 97, Verse 16', 'कुलीनः सत्त्वसंपन्नस्तेजस्वी चरितव्रतः।
राज्यहेतोः कथं पापमाचरेत्त्वद्विधो जनः॥', 'kulīnaḥ sattvasaṃpannas tejasvī caritavrataḥ
rājyahetoḥ kathaṃ pāpam ācaret tvadvidho janaḥ', null, 2097016),
('ramayana-2-97-17', 17, 'Ayodhya Kanda, Sarga 97, Verse 17', 'न दोषं त्वयि पश्यामि सूक्ष्ममप्यरि सूदन।
न चापि जननीं बाल्यात्त्वं विगर्हितुमर्हसि॥', 'na doṣaṃ tvayi paśyāmi sūkṣmam apy ari sūdana
na cāpi jananīṃ bālyāt tvaṃ vigarhitum arhasi', null, 2097017),
('ramayana-2-97-18', 18, 'Ayodhya Kanda, Sarga 97, Verse 18', 'यावत्पितरि धर्मज्ञ गौरवं लोकसत्कृते।
तावद्धर्मभृतां श्रेष्ठ जनन्यामपि गौरवम्॥', 'yāvat pitari dharmajña gauravaṃ lokasatkṛte
tāvad dharmabhṛtāṃ śreṣṭha jananyām api gauravam', null, 2097018),
('ramayana-2-97-19', 19, 'Ayodhya Kanda, Sarga 97, Verse 19', 'एताभ्यां धर्मशीलाभ्यां वनं गच्छेति राघव।
माता पितृभ्यामुक्तोऽहं कथमन्यत्समाचरे॥', 'etābhyāṃ dharmaśīlābhyāṃ vanaṃ gaccheti rāghava
mātā pitṛbhyām ukto ''haṃ katham anyat samācare', null, 2097019),
('ramayana-2-97-20', 20, 'Ayodhya Kanda, Sarga 97, Verse 20', 'त्वया राज्यमयोध्यायां प्राप्तव्यं लोकसत्कृतम्।
वस्तव्यं दण्डकारण्ये मया वल्कलवाससा॥', 'tvayā rājyam ayodhyāyāṃ prāptavyaṃ lokasatkṛtam
vastavyaṃ daṇḍakāraṇye mayā valkalavāsasā', null, 2097020),
('ramayana-2-97-21', 21, 'Ayodhya Kanda, Sarga 97, Verse 21', 'एवं कृत्वा महाराजो विभागं लोकसंनिधौ।
व्यादिश्य च महातेजा दिवं दशरथो गतः॥', 'evaṃ kṛtvā mahārājo vibhāgaṃ lokasaṃnidhau
vyādiśya ca mahātejā divaṃ daśaratho gataḥ', null, 2097021),
('ramayana-2-97-22', 22, 'Ayodhya Kanda, Sarga 97, Verse 22', 'स च प्रमाणं धर्मात्मा राजा लोकगुरुस्तव।
पित्रा दत्तं यथाभागमुपभोक्तुं त्वमर्हसि॥', 'sa ca pramāṇaṃ dharmātmā rājā lokagurus tava
pitrā dattaṃ yathābhāgam upabhoktuṃ tvam arhasi', null, 2097022),
('ramayana-2-97-23', 23, 'Ayodhya Kanda, Sarga 97, Verse 23', 'चतुर्दश समाः सौम्य दण्डकारण्यमाश्रितः।
उपभोक्ष्ये त्वहं दत्तं भागं पित्रा महात्मना॥', 'caturdaśa samāḥ saumya daṇḍakāraṇyam āśritaḥ
upabhokṣye tv ahaṃ dattaṃ bhāgaṃ pitrā mahātmanā', null, 2097023),
('ramayana-2-97-24', 24, 'Ayodhya Kanda, Sarga 97, Verse 24', 'यदब्रवीन्मां नरलोकसत्कृतः पिता महात्मा विबुधाधिपोपमः।
तदेव मन्ये परमात्मनो हितं न सर्वलोकेश्वरभावमव्ययम्॥', 'yad abravīn māṃ naralokasatkṛtaḥ pitā mahātmā vibudhādhipopamaḥ
tad eva manye paramātmano hitaṃ na sarvalokeśvarabhāvam avyayam', null, 2097024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 98 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-98-1', 1, 'Ayodhya Kanda, Sarga 98, Verse 1', 'ततः पुरुषसिंहानां वृतानां तैः सुहृद्गणैः।
शोचतामेव रजनी दुःखेन व्यत्यवर्तत॥', 'tataḥ puruṣasiṃhānāṃ vṛtānāṃ taiḥ suhṛdgaṇaiḥ
śocatām eva rajanī duḥkhena vyatyavartata', null, 2098001),
('ramayana-2-98-2', 2, 'Ayodhya Kanda, Sarga 98, Verse 2', 'रजन्यां सुप्रभातायां भ्रातरस्ते सुहृद्वृताः।
मन्दाकिन्यां हुतं जप्यं कृत्वा राममुपागमन्॥', 'rajanyāṃ suprabhātāyāṃ bhrātaras te suhṛdvṛtāḥ
mandākinyāṃ hutaṃ japyaṃ kṛtvā rāmam upāgaman', null, 2098002),
('ramayana-2-98-3', 3, 'Ayodhya Kanda, Sarga 98, Verse 3', 'तूष्णीं ते समुपासीना न कश्चित्किं चिदब्रवीत्।
भरतस्तु सुहृन्मध्ये रामवचनमब्रवीत्॥', 'tūṣṇīṃ te samupāsīnā na kaś cit kiṃ cid abravīt
bharatas tu suhṛnmadhye rāmavacanam abravīt', null, 2098003),
('ramayana-2-98-4', 4, 'Ayodhya Kanda, Sarga 98, Verse 4', 'सान्त्विता मामिका माता दत्तं राज्यमिदं मम।
तद्ददामि तवैवाहं भुङ्क्ष्व राज्यमकण्टकम्॥', 'sāntvitā māmikā mātā dattaṃ rājyam idaṃ mama
tad dadāmi tavaivāhaṃ bhuṅkṣva rājyam akaṇṭakam', null, 2098004),
('ramayana-2-98-5', 5, 'Ayodhya Kanda, Sarga 98, Verse 5', 'महतेवाम्बुवेगेन भिन्नः सेतुर्जलागमे।
दुरावारं त्वदन्येन राज्यखण्डमिदं महत्॥', 'mahatevāmbuvegena bhinnaḥ setur jalāgame
durāvāraṃ tvadanyena rājyakhaṇḍam idaṃ mahat', null, 2098005),
('ramayana-2-98-6', 6, 'Ayodhya Kanda, Sarga 98, Verse 6', 'गतिं खर इवाश्वस्य तार्क्ष्यस्येव पतत्रिणः।
अनुगन्तुं न शक्तिर्मे गतिं तव महीपते॥', 'gatiṃ khara ivāśvasya tārkṣyasyeva patatriṇaḥ
anugantuṃ na śaktir me gatiṃ tava mahīpate', null, 2098006),
('ramayana-2-98-7', 7, 'Ayodhya Kanda, Sarga 98, Verse 7', 'सुजीवं नित्यशस्तस्य यः परैरुपजीव्यते।
राम तेन तु दुर्जीवं यः परानुपजीवति॥', 'sujīvaṃ nityaśas tasya yaḥ parair upajīvyate
rāma tena tu durjīvaṃ yaḥ parān upajīvati', null, 2098007),
('ramayana-2-98-8', 8, 'Ayodhya Kanda, Sarga 98, Verse 8', 'यथा तु रोपितो वृक्षः पुरुषेण विवर्धितः।
ह्रस्वकेन दुरारोहो रूढस्कन्धो महाद्रुमः॥', 'yathā tu ropito vṛkṣaḥ puruṣeṇa vivardhitaḥ
hrasvakena durāroho rūḍhaskandho mahādrumaḥ', null, 2098008),
('ramayana-2-98-9', 9, 'Ayodhya Kanda, Sarga 98, Verse 9', 'स यदा पुष्पितो भूत्वा फलानि न विदर्शयेत्।
स तां नानुभवेत्प्रीतिं यस्य हेतोः प्रभावितः॥', 'sa yadā puṣpito bhūtvā phalāni na vidarśayet
sa tāṃ nānubhavet prītiṃ yasya hetoḥ prabhāvitaḥ', null, 2098009),
('ramayana-2-98-10', 10, 'Ayodhya Kanda, Sarga 98, Verse 10', 'एषोपमा महाबाहो त्वमर्थं वेत्तुमर्हसि।
यदि त्वमस्मानृषभो भर्ता भृत्यान्न शाधि हि॥', 'eṣopamā mahābāho tvam arthaṃ vettum arhasi
yadi tvam asmān ṛṣabho bhartā bhṛtyān na śādhi hi', null, 2098010),
('ramayana-2-98-11', 11, 'Ayodhya Kanda, Sarga 98, Verse 11', 'श्रेणयस्त्वां महाराज पश्यन्त्वग्र्याश्च सर्वशः।
प्रतपन्तमिवादित्यं राज्ये स्थितमरिंदमम्॥', 'śreṇayas tvāṃ mahārāja paśyantv agryāś ca sarvaśaḥ
pratapantam ivādityaṃ rājye sthitam ariṃdamam', null, 2098011),
('ramayana-2-98-12', 12, 'Ayodhya Kanda, Sarga 98, Verse 12', 'तवानुयाने काकुत्ष्ठ मत्ता नर्दन्तु कुञ्जराः।
अन्तःपुर गता नार्यो नन्दन्तु सुसमाहिताः॥', 'tavānuyāne kākutṣṭha mattā nardantu kuñjarāḥ
antaḥpura gatā nāryo nandantu susamāhitāḥ', null, 2098012),
('ramayana-2-98-13', 13, 'Ayodhya Kanda, Sarga 98, Verse 13', 'तस्य साध्वित्यमन्यन्त नागरा विविधा जनाः।
भरतस्य वचः श्रुत्वा रामं प्रत्यनुयाचतः॥', 'tasya sādhv ity amanyanta nāgarā vividhā janāḥ
bharatasya vacaḥ śrutvā rāmaṃ pratyanuyācataḥ', null, 2098013),
('ramayana-2-98-14', 14, 'Ayodhya Kanda, Sarga 98, Verse 14', 'तमेवं दुःखितं प्रेक्ष्य विलपन्तं यशस्विनम्।
रामः कृतात्मा भरतं समाश्वासयदात्मवान्॥', 'tam evaṃ duḥkhitaṃ prekṣya vilapantaṃ yaśasvinam
rāmaḥ kṛtātmā bharataṃ samāśvāsayad ātmavān', null, 2098014),
('ramayana-2-98-15', 15, 'Ayodhya Kanda, Sarga 98, Verse 15', 'नात्मनः कामकारोऽस्ति पुरुषोऽयमनीश्वरः।
इतश्चेतरतश्चैनं कृतान्तः परिकर्षति॥', 'nātmanaḥ kāmakāro ''sti puruṣo ''yam anīśvaraḥ
itaś cetarataś cainaṃ kṛtāntaḥ parikarṣati', null, 2098015),
('ramayana-2-98-16', 16, 'Ayodhya Kanda, Sarga 98, Verse 16', 'सर्वे क्षयान्ता निचयाः पतनान्ताः समुच्छ्रयाः।
संयोगा विप्रयोगान्ता मरणान्तं च जीवितम्॥', 'sarve kṣayāntā nicayāḥ patanāntāḥ samucchrayāḥ
saṃyogā viprayogāntā maraṇāntaṃ ca jīvitam', null, 2098016),
('ramayana-2-98-17', 17, 'Ayodhya Kanda, Sarga 98, Verse 17', 'यथा फलानं पक्वानां नान्यत्र पतनाद्भयम्।
एवं नरस्य जातस्य नान्यत्र मरणाद्भयम्॥', 'yathā phalānaṃ pakvānāṃ nānyatra patanād bhayam
evaṃ narasya jātasya nānyatra maraṇād bhayam', null, 2098017),
('ramayana-2-98-18', 18, 'Ayodhya Kanda, Sarga 98, Verse 18', 'यथागारं दृढस्थूणं जीर्णं भूत्वावसीदति।
तथावसीदन्ति नरा जरामृत्युवशं गताः॥', 'yathāgāraṃ dṛḍhasthūṇaṃ jīrṇaṃ bhūtvāvasīdati
tathāvasīdanti narā jarāmṛtyuvaśaṃ gatāḥ', null, 2098018),
('ramayana-2-98-19', 19, 'Ayodhya Kanda, Sarga 98, Verse 19', 'अहोरात्राणि गच्छन्ति सर्वेषां प्राणिनामिह।
आयूंषि क्षपयन्त्याशु ग्रीष्मे जलमिवांशवः॥', 'ahorātrāṇi gacchanti sarveṣāṃ prāṇinām iha
āyūṃṣi kṣapayanty āśu grīṣme jalam ivāṃśavaḥ', null, 2098019),
('ramayana-2-98-20', 20, 'Ayodhya Kanda, Sarga 98, Verse 20', 'आत्मानमनुशोच त्वं किमन्यमनुशोचसि।
आयुस्ते हीयते यस्य स्थितस्य च गतस्य च॥', 'ātmānam anuśoca tvaṃ kim anyam anuśocasi
āyus te hīyate yasya sthitasya ca gatasya ca', null, 2098020),
('ramayana-2-98-21', 21, 'Ayodhya Kanda, Sarga 98, Verse 21', 'सहैव मृत्युर्व्रजति सह मृत्युर्निषीदति।
गत्वा सुदीर्घमध्वानं सह मृत्युर्निवर्तते॥', 'sahaiva mṛtyur vrajati saha mṛtyur niṣīdati
gatvā sudīrgham adhvānaṃ saha mṛtyur nivartate', null, 2098021),
('ramayana-2-98-22', 22, 'Ayodhya Kanda, Sarga 98, Verse 22', 'गात्रेषु वलयः प्राप्ताः श्वेताश्चैव शिरोरुहाः।
जरया पुरुषो जीर्णः किं हि कृत्वा प्रभावयेत्॥', 'gātreṣu valayaḥ prāptāḥ śvetāś caiva śiroruhāḥ
jarayā puruṣo jīrṇaḥ kiṃ hi kṛtvā prabhāvayet', null, 2098022),
('ramayana-2-98-23', 23, 'Ayodhya Kanda, Sarga 98, Verse 23', 'नन्दन्त्युदित आदित्ये नन्दन्त्यस्तमिते रवौ।
आत्मनो नावबुध्यन्ते मनुष्या जीवितक्षयम्॥', 'nandanty udita āditye nandanty astam ite ravau
ātmano nāvabudhyante manuṣyā jīvitakṣayam', null, 2098023),
('ramayana-2-98-24', 24, 'Ayodhya Kanda, Sarga 98, Verse 24', 'हृष्यन्त्यृतुमुखं दृष्ट्वा नवं नवमिहागतम्।
ऋतूनां परिवर्तेन प्राणिनां प्राणसंक्षयः॥', 'hṛṣyanty ṛtumukhaṃ dṛṣṭvā navaṃ navam ihāgatam
ṛtūnāṃ parivartena prāṇināṃ prāṇasaṃkṣayaḥ', null, 2098024),
('ramayana-2-98-25', 25, 'Ayodhya Kanda, Sarga 98, Verse 25', 'यथा काष्ठं च काष्ठं च समेयातां महार्णवे।
समेत्य च व्यपेयातां कालमासाद्य कं चन॥', 'yathā kāṣṭhaṃ ca kāṣṭhaṃ ca sameyātāṃ mahārṇave
sametya ca vyapeyātāṃ kālam āsādya kaṃ cana', null, 2098025),
('ramayana-2-98-26', 26, 'Ayodhya Kanda, Sarga 98, Verse 26', 'एवं भार्याश्च पुत्राश्च ज्ञातयश्च वसूनि च।
समेत्य व्यवधावन्ति ध्रुवो ह्येषां विनाभवः॥', 'evaṃ bhāryāś ca putrāś ca jñātayaś ca vasūni ca
sametya vyavadhāvanti dhruvo hy eṣāṃ vinābhavaḥ', null, 2098026),
('ramayana-2-98-27', 27, 'Ayodhya Kanda, Sarga 98, Verse 27', 'नात्र कश्चिद्यथा भावं प्राणी समभिवर्तते।
तेन तस्मिन्न सामर्थ्यं प्रेतस्यास्त्यनुशोचतः॥', 'nātra kaś cid yathā bhāvaṃ prāṇī samabhivartate
tena tasmin na sāmarthyaṃ pretasyāsty anuśocataḥ', null, 2098027),
('ramayana-2-98-28', 28, 'Ayodhya Kanda, Sarga 98, Verse 28', 'यथा हि सार्थं गच्छन्तं ब्रूयात्कश्चित्पथि स्थितः।
अहमप्यागमिष्यामि पृष्ठतो भवतामिति॥', 'yathā hi sārthaṃ gacchantaṃ brūyāt kaś cit pathi sthitaḥ
aham apy āgamiṣyāmi pṛṣṭhato bhavatām iti', null, 2098028),
('ramayana-2-98-29', 29, 'Ayodhya Kanda, Sarga 98, Verse 29', 'एवं पूर्वैर्गतो मार्गः पितृपैतामहो ध्रुवः।
तमापन्नः कथं शोचेद्यस्य नास्ति व्यतिक्रमः॥', 'evaṃ pūrvair gato mārgaḥ pitṛpaitāmaho dhruvaḥ
tam āpannaḥ kathaṃ śoced yasya nāsti vyatikramaḥ', null, 2098029),
('ramayana-2-98-30', 30, 'Ayodhya Kanda, Sarga 98, Verse 30', 'वयसः पतमानस्य स्रोतसो वानिवर्तिनः।
आत्मा सुखे नियोक्तव्यः सुखभाजः प्रजाः स्मृताः॥', 'vayasaḥ patamānasya srotaso vānivartinaḥ
ātmā sukhe niyoktavyaḥ sukhabhājaḥ prajāḥ smṛtāḥ', null, 2098030),
('ramayana-2-98-31', 31, 'Ayodhya Kanda, Sarga 98, Verse 31', 'धर्मात्मा स शुभैः कृत्स्नैः क्रतुभिश्चाप्तदक्षिणैः।
धूतपापो गतः स्वर्गं पिता नः पृथिवीपतिः॥', 'dharmātmā sa śubhaiḥ kṛtsnaiḥ kratubhiś cāptadakṣiṇaiḥ
dhūtapāpo gataḥ svargaṃ pitā naḥ pṛthivīpatiḥ', null, 2098031),
('ramayana-2-98-32', 32, 'Ayodhya Kanda, Sarga 98, Verse 32', 'भृत्यानां भरणात्सम्यक्प्रजानां परिपालनात्।
अर्थादानाच्च धार्मेण पिता नस्त्रिदिवं गतः॥', 'bhṛtyānāṃ bharaṇāt samyak prajānāṃ paripālanāt
arthādānāc ca dhārmeṇa pitā nas tridivaṃ gataḥ', null, 2098032),
('ramayana-2-98-33', 33, 'Ayodhya Kanda, Sarga 98, Verse 33', 'इष्ट्वा बहुविधैर्यज्ञैर्भोगांश्चावाप्य पुष्कलान्।
उत्तमं चायुरासाद्य स्वर्गतः पृथिवीपतिः॥', 'iṣṭvā bahuvidhair yajñair bhogāṃś cāvāpya puṣkalān
uttamaṃ cāyur āsādya svar gataḥ pṛthivīpatiḥ', null, 2098033),
('ramayana-2-98-34', 34, 'Ayodhya Kanda, Sarga 98, Verse 34', 'स जीर्णं मानुषं देहं परित्यज्य पिता हि नः।
दैवीमृद्धिमनुप्राप्तो ब्रह्मलोकविहारिणीम्॥', 'sa jīrṇaṃ mānuṣaṃ dehaṃ parityajya pitā hi naḥ
daivīm ṛddhim anuprāpto brahmalokavihāriṇīm', null, 2098034),
('ramayana-2-98-35', 35, 'Ayodhya Kanda, Sarga 98, Verse 35', 'तं तु नैवं विधः कश्चित्प्राज्ञः शोचितुमर्हति।
त्वद्विधो यद्विधश्चापि श्रुतवान्बुद्धिमत्तरः॥', 'taṃ tu naivaṃ vidhaḥ kaś cit prājñaḥ śocitum arhati
tvadvidho yadvidhaś cāpi śrutavān buddhimattaraḥ', null, 2098035),
('ramayana-2-98-36', 36, 'Ayodhya Kanda, Sarga 98, Verse 36', 'एते बहुविधाः शोका विलाप रुदिते तथा।
वर्जनीया हि धीरेण सर्वावस्थासु धीमता॥', 'ete bahuvidhāḥ śokā vilāpa rudite tathā
varjanīyā hi dhīreṇa sarvāvasthāsu dhīmatā', null, 2098036),
('ramayana-2-98-37', 37, 'Ayodhya Kanda, Sarga 98, Verse 37', 'स स्वस्थो भव मा शोचो यात्वा चावस तां पुरीम्।
तथा पित्रा नियुक्तोऽसि वशिना वदताम्व्वर॥', 'sa svastho bhava mā śoco yātvā cāvasa tāṃ purīm
tathā pitrā niyukto ''si vaśinā vadatāmv vara', null, 2098037),
('ramayana-2-98-38', 38, 'Ayodhya Kanda, Sarga 98, Verse 38', 'यत्राहमपि तेनैव नियुक्तः पुण्यकर्मणा।
तत्रैवाहं करिष्यामि पितुरार्यस्य शासनम्॥', 'yatrāham api tenaiva niyuktaḥ puṇyakarmaṇā
tatraivāhaṃ kariṣyāmi pitur āryasya śāsanam', null, 2098038),
('ramayana-2-98-39', 39, 'Ayodhya Kanda, Sarga 98, Verse 39', 'न मया शासनं तस्य त्यक्तुं न्याय्यमरिंदम।
तत्त्वयापि सदा मान्यं स वै बन्धुः स नः पिता॥', 'na mayā śāsanaṃ tasya tyaktuṃ nyāyyam ariṃdama
tat tvayāpi sadā mānyaṃ sa vai bandhuḥ sa naḥ pitā', null, 2098039),
('ramayana-2-98-40', 40, 'Ayodhya Kanda, Sarga 98, Verse 40', 'एवमुक्त्वा तु विरते रामे वचनमर्थवत्।
उवाच भरतश्चित्रं धार्मिको धार्मिकं वचः॥', 'evam uktvā tu virate rāme vacanam arthavat
uvāca bharataś citraṃ dhārmiko dhārmikaṃ vacaḥ', null, 2098040),
('ramayana-2-98-41', 41, 'Ayodhya Kanda, Sarga 98, Verse 41', 'को हि स्यादीदृशो लोके यादृशस्त्वमरिंदम।
न त्वां प्रव्यथयेद्दुःखं प्रीतिर्वा न प्रहर्षयेत्॥', 'ko hi syād īdṛśo loke yādṛśas tvam ariṃdama
na tvāṃ pravyathayed duḥkhaṃ prītir vā na praharṣayet', null, 2098041),
('ramayana-2-98-42', 42, 'Ayodhya Kanda, Sarga 98, Verse 42', 'संमतश्चासि वृद्धानां तांश्च पृच्छसि संशयान्।
यथा मृतस्तथा जीवन्यथासति तथा सति॥', 'saṃmataś cāsi vṛddhānāṃ tāṃś ca pṛcchasi saṃśayān
yathā mṛtas tathā jīvan yathāsati tathā sati', null, 2098042),
('ramayana-2-98-43', 43, 'Ayodhya Kanda, Sarga 98, Verse 43', 'यस्यैष बुद्धिलाभः स्यात्परितप्येत केन सः।
स एवं व्यसनं प्राप्य न विषीदितुमर्हति॥', 'yasyaiṣa buddhilābhaḥ syāt paritapyeta kena saḥ
sa evaṃ vyasanaṃ prāpya na viṣīditum arhati', null, 2098043),
('ramayana-2-98-44', 44, 'Ayodhya Kanda, Sarga 98, Verse 44', 'अमरोपमसत्त्वस्त्वं महात्मा सत्यसंगरः।
सर्वज्ञः सर्वदर्शी च बुद्धिमांश्चासि राघव॥', 'amaropamasattvas tvaṃ mahātmā satyasaṃgaraḥ
sarvajñaḥ sarvadarśī ca buddhimāṃś cāsi rāghava', null, 2098044),
('ramayana-2-98-45', 45, 'Ayodhya Kanda, Sarga 98, Verse 45', 'न त्वामेवं गुणैर्युक्तं प्रभवाभवकोविदम्।
अविषह्यतमं दुःखमासादयितुमर्हति॥', 'na tvām evaṃ guṇair yuktaṃ prabhavābhavakovidam
aviṣahyatamaṃ duḥkham āsādayitum arhati', null, 2098045),
('ramayana-2-98-46', 46, 'Ayodhya Kanda, Sarga 98, Verse 46', 'प्रोषिते मयि यत्पापं मात्रा मत्कारणात्कृतम्।
क्षुद्रया तदनिष्टं मे प्रसीदतु भवान्मम॥', 'proṣite mayi yat pāpaṃ mātrā matkāraṇāt kṛtam
kṣudrayā tad aniṣṭaṃ me prasīdatu bhavān mama', null, 2098046),
('ramayana-2-98-47', 47, 'Ayodhya Kanda, Sarga 98, Verse 47', 'धर्मबन्धेन बद्धोऽस्मि तेनेमां नेह मातरम्।
हन्मि तीव्रेण दण्डेन दण्डार्हां पापकारिणीम्॥', 'dharmabandhena baddho ''smi tenemāṃ neha mātaram
hanmi tīvreṇa daṇḍena daṇḍārhāṃ pāpakāriṇīm', null, 2098047),
('ramayana-2-98-48', 48, 'Ayodhya Kanda, Sarga 98, Verse 48', 'कथं दशरथाज्जातः शुद्धाभिजनकर्मणः।
जानन्धर्ममधर्मिष्ठं कुर्यां कर्म जुगुप्सितम्॥', 'kathaṃ daśarathāj jātaḥ śuddhābhijanakarmaṇaḥ
jānan dharmam adharmiṣṭhaṃ kuryāṃ karma jugupsitam', null, 2098048),
('ramayana-2-98-49', 49, 'Ayodhya Kanda, Sarga 98, Verse 49', 'गुरुः क्रियावान्वृद्धश्च राजा प्रेतः पितेति च।
तातं न परिगर्हेयं दैवतं चेति संसदि॥', 'guruḥ kriyāvān vṛddhaś ca rājā pretaḥ piteti ca
tātaṃ na parigarheyaṃ daivataṃ ceti saṃsadi', null, 2098049),
('ramayana-2-98-50', 50, 'Ayodhya Kanda, Sarga 98, Verse 50', 'को हि धर्मार्थयोर्हीनमीदृशं कर्म किल्बिषम्।
स्त्रियाः प्रियचिकीर्षुः सन्कुर्याद्धर्मज्ञ धर्मवित्॥', 'ko hi dharmārthayor hīnam īdṛśaṃ karma kilbiṣam
striyāḥ priyacikīrṣuḥ san kuryād dharmajña dharmavit', null, 2098050),
('ramayana-2-98-51', 51, 'Ayodhya Kanda, Sarga 98, Verse 51', 'अन्तकाले हि भूतानि मुह्यन्तीति पुराश्रुतिः।
राज्ञैवं कुर्वता लोके प्रत्यक्षा सा श्रुतिः कृता॥', 'antakāle hi bhūtāni muhyantīti purāśrutiḥ
rājñaivaṃ kurvatā loke pratyakṣā sā śrutiḥ kṛtā', null, 2098051),
('ramayana-2-98-52', 52, 'Ayodhya Kanda, Sarga 98, Verse 52', 'साध्वर्थमभिसंधाय क्रोधान्मोहाच्च साहसात्।
तातस्य यदतिक्रान्तं प्रत्याहरतु तद्भवान्॥', 'sādhv artham abhisaṃdhāya krodhān mohāc ca sāhasāt
tātasya yad atikrāntaṃ pratyāharatu tad bhavān', null, 2098052),
('ramayana-2-98-53', 53, 'Ayodhya Kanda, Sarga 98, Verse 53', 'पितुर्हि समतिक्रान्तं पुत्रो यः साधु मन्यते।
तदपत्यं मतं लोके विपरीतमतोऽन्यथा॥', 'pitur hi samatikrāntaṃ putro yaḥ sādhu manyate
tad apatyaṃ mataṃ loke viparītam ato ''nyathā', null, 2098053),
('ramayana-2-98-54', 54, 'Ayodhya Kanda, Sarga 98, Verse 54', 'तदपत्यं भवानस्तु मा भवान्दुष्कृतं पितुः।
अभिपत्तत्कृतं कर्म लोके धीरविगर्हितम्॥', 'tad apatyaṃ bhavān astu mā bhavān duṣkṛtaṃ pituḥ
abhipat tat kṛtaṃ karma loke dhīravigarhitam', null, 2098054),
('ramayana-2-98-55', 55, 'Ayodhya Kanda, Sarga 98, Verse 55', 'कैकेयीं मां च तातं च सुहृदो बान्धवांश्च नः।
पौरजानपदान्सर्वांस्त्रातु सर्वमिदं भवान्॥', 'kaikeyīṃ māṃ ca tātaṃ ca suhṛdo bāndhavāṃś ca naḥ
paurajānapadān sarvāṃs trātu sarvam idaṃ bhavān', null, 2098055),
('ramayana-2-98-56', 56, 'Ayodhya Kanda, Sarga 98, Verse 56', 'क्व चारण्यं क्व च क्षात्रं क्व जटाः क्व च पालनम्।
ईदृशं व्याहतं कर्म न भवान्कर्तुमर्हति॥', 'kva cāraṇyaṃ kva ca kṣātraṃ kva jaṭāḥ kva ca pālanam
īdṛśaṃ vyāhataṃ karma na bhavān kartum arhati', null, 2098056),
('ramayana-2-98-57', 57, 'Ayodhya Kanda, Sarga 98, Verse 57', 'अथ क्लेशजमेव त्वं धर्मं चरितुमिच्छसि।
धर्मेण चतुरो वर्णान्पालयन्क्लेशमाप्नुहि॥', 'atha kleśajam eva tvaṃ dharmaṃ caritum icchasi
dharmeṇa caturo varṇān pālayan kleśam āpnuhi', null, 2098057),
('ramayana-2-98-58', 58, 'Ayodhya Kanda, Sarga 98, Verse 58', 'चतुर्णामाश्रमाणां हि गार्हस्थ्यं श्रेष्ठमाश्रमम्।
आहुर्धर्मज्ञ धर्मज्ञास्तं कथं त्यक्तुमर्हसि॥', 'caturṇām āśramāṇāṃ hi gārhasthyaṃ śreṣṭham āśramam
āhur dharmajña dharmajñās taṃ kathaṃ tyaktum arhasi', null, 2098058),
('ramayana-2-98-59', 59, 'Ayodhya Kanda, Sarga 98, Verse 59', 'श्रुतेन बालः स्थानेन जन्मना भवतो ह्यहम्।
स कथं पालयिष्यामि भूमिं भवति तिष्ठति॥', 'śrutena bālaḥ sthānena janmanā bhavato hy aham
sa kathaṃ pālayiṣyāmi bhūmiṃ bhavati tiṣṭhati', null, 2098059),
('ramayana-2-98-60', 60, 'Ayodhya Kanda, Sarga 98, Verse 60', 'हीनबुद्धिगुणो बालो हीनः स्थानेन चाप्यहम्।
भवता च विना भूतो न वर्तयितुमुत्सहे॥', 'hīnabuddhiguṇo bālo hīnaḥ sthānena cāpy aham
bhavatā ca vinā bhūto na vartayitum utsahe', null, 2098060),
('ramayana-2-98-61', 61, 'Ayodhya Kanda, Sarga 98, Verse 61', 'इदं निखिलमव्यग्रं पित्र्यं राज्यमकण्टकम्।
अनुशाधि स्वधर्मेण धर्मज्ञ सह बान्धवैः॥', 'idaṃ nikhilam avyagraṃ pitryaṃ rājyam akaṇṭakam
anuśādhi svadharmeṇa dharmajña saha bāndhavaiḥ', null, 2098061),
('ramayana-2-98-62', 62, 'Ayodhya Kanda, Sarga 98, Verse 62', 'इहैव त्वाभिषिञ्चन्तु धर्मज्ञ सह बान्धवैः।
ऋत्विजः सवसिष्ठाश्च मन्त्रवन्मन्त्रकोविदाः॥', 'ihaiva tvābhiṣiñcantu dharmajña saha bāndhavaiḥ
ṛtvijaḥ savasiṣṭhāś ca mantravan mantrakovidāḥ', null, 2098062),
('ramayana-2-98-63', 63, 'Ayodhya Kanda, Sarga 98, Verse 63', 'अभिषिक्तस्त्वमस्माभिरयोध्यां पालने व्रज।
विजित्य तरसा लोकान्मरुद्भिरिव वासवः॥', 'abhiṣiktas tvam asmābhir ayodhyāṃ pālane vraja
vijitya tarasā lokān marudbhir iva vāsavaḥ', null, 2098063),
('ramayana-2-98-64', 64, 'Ayodhya Kanda, Sarga 98, Verse 64', 'ऋणानि त्रीण्यपाकुर्वन्दुर्हृदः साधु निर्दहन्।
सुहृदस्तर्पयन्कामैस्त्वमेवात्रानुशाधि माम्॥', 'ṛṇāni trīṇy apākurvan durhṛdaḥ sādhu nirdahan
suhṛdas tarpayan kāmais tvam evātrānuśādhi mām', null, 2098064),
('ramayana-2-98-65', 65, 'Ayodhya Kanda, Sarga 98, Verse 65', 'अद्यार्य मुदिताः सन्तु सुहृदस्तेऽभिषेचने।
अद्य भीताः पालयन्तां दुर्हृदस्ते दिशो दश॥', 'adyārya muditāḥ santu suhṛdas te ''bhiṣecane
adya bhītāḥ pālayantāṃ durhṛdas te diśo daśa', null, 2098065),
('ramayana-2-98-66', 66, 'Ayodhya Kanda, Sarga 98, Verse 66', 'आक्रोशं मम मातुश्च प्रमृज्य पुरुषर्षभ।
अद्य तत्र भवन्तं च पितरं रक्ष किल्बिषात्॥', 'ākrośaṃ mama mātuś ca pramṛjya puruṣarṣabha
adya tatra bhavantaṃ ca pitaraṃ rakṣa kilbiṣāt', null, 2098066),
('ramayana-2-98-67', 67, 'Ayodhya Kanda, Sarga 98, Verse 67', 'शिरसा त्वाभियाचेऽहं कुरुष्व करुणां मयि।
बान्धवेषु च सर्वेषु भूतेष्विव महेश्वरः॥', 'śirasā tvābhiyāce ''haṃ kuruṣva karuṇāṃ mayi
bāndhaveṣu ca sarveṣu bhūteṣv iva maheśvaraḥ', null, 2098067),
('ramayana-2-98-68', 68, 'Ayodhya Kanda, Sarga 98, Verse 68', 'अथ वा पृष्ठतः कृत्वा वनमेव भवानितः।
गमिष्यति गमिष्यामि भवता सार्धमप्यहम्॥', 'atha vā pṛṣṭhataḥ kṛtvā vanam eva bhavān itaḥ
gamiṣyati gamiṣyāmi bhavatā sārdham apy aham', null, 2098068),
('ramayana-2-98-69', 69, 'Ayodhya Kanda, Sarga 98, Verse 69', 'तथापि रामो भरतेन ताम्यत प्रसाद्यमानः शिरसा महीपतिः।
न चैव चक्रे गमनाय सत्त्ववान्मतिं पितुस्तद्वचने प्रतिष्ठितः॥', 'tathāpi rāmo bharatena tāmyata prasādyamānaḥ śirasā mahīpatiḥ
na caiva cakre gamanāya sattvavān matiṃ pitus tadvacane pratiṣṭhitaḥ', null, 2098069),
('ramayana-2-98-70', 70, 'Ayodhya Kanda, Sarga 98, Verse 70', 'तदद्भुतं स्थैर्यमवेक्ष्य राघवे समं जनो हर्षमवाप दुःखितः।
न यात्ययोध्यामिति दुःखितोऽभवत्स्थिरप्रतिज्ञत्वमवेक्ष्य हर्षितः॥', 'tad adbhutaṃ sthairyam avekṣya rāghave samaṃ jano harṣam avāpa duḥkhitaḥ
na yāty ayodhyām iti duḥkhito ''bhavat sthirapratijñatvam avekṣya harṣitaḥ', null, 2098070),
('ramayana-2-98-71', 71, 'Ayodhya Kanda, Sarga 98, Verse 71', 'तमृत्विजो नैगमयूथवल्लभास्तथा विसंज्ञाश्रुकलाश्च मातरः।
तथा ब्रुवाणं भरतं प्रतुष्टुवुः प्रणम्य रामं च ययाचिरे सह॥', 'tam ṛtvijo naigamayūthavallabhās tathā visaṃjñāśrukalāś ca mātaraḥ
tathā bruvāṇaṃ bharataṃ pratuṣṭuvuḥ praṇamya rāmaṃ ca yayācire saha', null, 2098071)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 99 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-99-1', 1, 'Ayodhya Kanda, Sarga 99, Verse 1', 'पुनरेवं ब्रुवाणं तु भरतं लक्ष्मणाग्रजः।
प्रत्युवच ततः श्रीमाञ्ज्ञातिमध्येऽतिसत्कृतः॥', 'punar evaṃ bruvāṇaṃ tu bharataṃ lakṣmaṇāgrajaḥ
pratyuvaca tataḥ śrīmāñ jñātimadhye ''tisatkṛtaḥ', null, 2099001),
('ramayana-2-99-2', 2, 'Ayodhya Kanda, Sarga 99, Verse 2', 'उपपन्नमिदं वाक्यं यत्त्वमेवमभाषथाः।
जातः पुत्रो दशरथात्कैकेय्यां राजसत्तमात्॥', 'upapannam idaṃ vākyaṃ yat tvam evam abhāṣathāḥ
jātaḥ putro daśarathāt kaikeyyāṃ rājasattamāt', null, 2099002),
('ramayana-2-99-3', 3, 'Ayodhya Kanda, Sarga 99, Verse 3', 'पुरा भ्रातः पिता नः स मातरं ते समुद्वहन्।
मातामहे समाश्रौषीद्राज्यशुल्कमनुत्तमम्॥', 'purā bhrātaḥ pitā naḥ sa mātaraṃ te samudvahan
mātāmahe samāśrauṣīd rājyaśulkam anuttamam', null, 2099003),
('ramayana-2-99-4', 4, 'Ayodhya Kanda, Sarga 99, Verse 4', 'देवासुरे च संग्रामे जनन्यै तव पार्थिवः।
संप्रहृष्टो ददौ राजा वरमाराधितः प्रभुः॥', 'devāsure ca saṃgrāme jananyai tava pārthivaḥ
saṃprahṛṣṭo dadau rājā varam ārādhitaḥ prabhuḥ', null, 2099004),
('ramayana-2-99-5', 5, 'Ayodhya Kanda, Sarga 99, Verse 5', 'ततः सा संप्रतिश्राव्य तव माता यशस्विनी।
अयाचत नरश्रेष्ठं द्वौ वरौ वरवर्णिनी॥', 'tataḥ sā saṃpratiśrāvya tava mātā yaśasvinī
ayācata naraśreṣṭhaṃ dvau varau varavarṇinī', null, 2099005),
('ramayana-2-99-6', 6, 'Ayodhya Kanda, Sarga 99, Verse 6', 'तव राज्यं नरव्याघ्र मम प्रव्राजनं तथा।
तच्च राजा तथा तस्यै नियुक्तः प्रददौ वरम्॥', 'tava rājyaṃ naravyāghra mama pravrājanaṃ tathā
tac ca rājā tathā tasyai niyuktaḥ pradadau varam', null, 2099006),
('ramayana-2-99-7', 7, 'Ayodhya Kanda, Sarga 99, Verse 7', 'तेन पित्राहमप्यत्र नियुक्तः पुरुषर्षभ।
चतुर्दश वने वासं वर्षाणि वरदानिकम्॥', 'tena pitrāham apy atra niyuktaḥ puruṣarṣabha
caturdaśa vane vāsaṃ varṣāṇi varadānikam', null, 2099007),
('ramayana-2-99-8', 8, 'Ayodhya Kanda, Sarga 99, Verse 8', 'सोऽहं वनमिदं प्राप्तो निर्जनं लक्ष्मणान्वितः।
शीतया चाप्रतिद्वन्द्वः सत्यवादे स्थितः पितुः॥', 'so ''haṃ vanam idaṃ prāpto nirjanaṃ lakṣmaṇānvitaḥ
śītayā cāpratidvandvaḥ satyavāde sthitaḥ pituḥ', null, 2099008),
('ramayana-2-99-9', 9, 'Ayodhya Kanda, Sarga 99, Verse 9', 'भवानपि तथेत्येव पितरं सत्यवादिनम्।
कर्तुमर्हति राजेन्द्रं क्षिप्रमेवाभिषेचनात्॥', 'bhavān api tathety eva pitaraṃ satyavādinam
kartum arhati rājendraṃ kṣipram evābhiṣecanāt', null, 2099009),
('ramayana-2-99-10', 10, 'Ayodhya Kanda, Sarga 99, Verse 10', 'ऋणान्मोचय राजानं मत्कृते भरत प्रभुम्।
पितरं त्राहि धर्मज्ञ मातरं चाभिनन्दय॥', 'ṛṇān mocaya rājānaṃ matkṛte bharata prabhum
pitaraṃ trāhi dharmajña mātaraṃ cābhinandaya', null, 2099010),
('ramayana-2-99-11', 11, 'Ayodhya Kanda, Sarga 99, Verse 11', 'श्रूयते हि पुरा तात श्रुतिर्गीता यशस्विनी।
गयेन यजमानेन गयेष्वेव पितॄन्प्रति॥', 'śrūyate hi purā tāta śrutir gītā yaśasvinī
gayena yajamānena gayeṣv eva pitṝn prati', null, 2099011),
('ramayana-2-99-12', 12, 'Ayodhya Kanda, Sarga 99, Verse 12', 'पुं नाम्ना नरकाद्यस्मात्पितरं त्रायते सुतः।
तस्मात्पुत्र इति प्रोक्तः पितॄन्यत्पाति वा सुतः॥', 'puṃ nāmnā narakād yasmāt pitaraṃ trāyate sutaḥ
tasmāt putra iti proktaḥ pitṝn yat pāti vā sutaḥ', null, 2099012),
('ramayana-2-99-13', 13, 'Ayodhya Kanda, Sarga 99, Verse 13', 'एष्टव्या बहवः पुत्रा गुणवन्तो बहुश्रुताः।
तेषां वै समवेतानामपि कश्चिद्गयां व्रजेत्॥', 'eṣṭavyā bahavaḥ putrā guṇavanto bahuśrutāḥ
teṣāṃ vai samavetānām api kaś cid gayāṃ vrajet', null, 2099013),
('ramayana-2-99-14', 14, 'Ayodhya Kanda, Sarga 99, Verse 14', 'एवं राजर्षयः सर्वे प्रतीता राजनन्दन।
तस्मात्त्राहि नरश्रेष्ठ पितरं नरकात्प्रभो॥', 'evaṃ rājarṣayaḥ sarve pratītā rājanandana
tasmāt trāhi naraśreṣṭha pitaraṃ narakāt prabho', null, 2099014),
('ramayana-2-99-15', 15, 'Ayodhya Kanda, Sarga 99, Verse 15', 'अयोध्यां गच्छ भरत प्रकृतीरनुरञ्जय।
शत्रुघ्न सहितो वीर सह सर्वैर्द्विजातिभिः॥', 'ayodhyāṃ gaccha bharata prakṛtīr anurañjaya
śatrughna sahito vīra saha sarvair dvijātibhiḥ', null, 2099015),
('ramayana-2-99-16', 16, 'Ayodhya Kanda, Sarga 99, Verse 16', 'प्रवेक्ष्ये दण्डकारण्यमहमप्यविलम्बयन्।
आभ्यां तु सहितो राजन्वैदेह्या लक्ष्मणेन च॥', 'pravekṣye daṇḍakāraṇyam aham apy avilambayan
ābhyāṃ tu sahito rājan vaidehyā lakṣmaṇena ca', null, 2099016),
('ramayana-2-99-17', 17, 'Ayodhya Kanda, Sarga 99, Verse 17', 'त्वं राजा भव भरत स्वयं नराणां वन्यानामहमपि राजराण्मृगाणाम्।
गच्छ त्वं पुरवरमद्य संप्रहृष्टः संहृष्टस्त्वहमपि दण्डकान्प्रवेक्ष्ये॥', 'tvaṃ rājā bhava bharata svayaṃ narāṇāṃ vanyānām aham api rājarāṇ mṛgāṇām
gaccha tvaṃ puravaram adya saṃprahṛṣṭaḥ saṃhṛṣṭas tv aham api daṇḍakān pravekṣye', null, 2099017),
('ramayana-2-99-18', 18, 'Ayodhya Kanda, Sarga 99, Verse 18', 'छायां ते दिनकरभाः प्रबाधमानं वर्षत्रं भरत करोतु मूर्ध्नि शीताम्।
एतेषामहमपि काननद्रुमाणां छायां तामतिशयिनीं सुखं श्रयिष्ये॥', 'chāyāṃ te dinakarabhāḥ prabādhamānaṃ varṣatraṃ bharata karotu mūrdhni śītām
eteṣām aham api kānanadrumāṇāṃ chāyāṃ tām atiśayinīṃ sukhaṃ śrayiṣye', null, 2099018),
('ramayana-2-99-19', 19, 'Ayodhya Kanda, Sarga 99, Verse 19', 'शत्रुघ्नः कुशलमतिस्तु ते सहायः सौमित्रिर्मम विदितः प्रधानमित्रम्।
चत्वारस्तनयवरा वयं नरेन्द्रं सत्यस्थं भरत चराम मा विषादम्॥', 'śatrughnaḥ kuśalamatis tu te sahāyaḥ saumitrir mama viditaḥ pradhānamitram
catvāras tanayavarā vayaṃ narendraṃ satyasthaṃ bharata carāma mā viṣādam', null, 2099019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 100 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-100-1', 1, 'Ayodhya Kanda, Sarga 100, Verse 1', 'आश्वासयन्तं भरतं जाबालिर्ब्राह्मणोत्तमः।
उवाच रामं धर्मज्ञं धर्मापेतमिदं वचः॥', 'āśvāsayantaṃ bharataṃ jābālir brāhmaṇottamaḥ
uvāca rāmaṃ dharmajñaṃ dharmāpetam idaṃ vacaḥ', null, 2100001),
('ramayana-2-100-2', 2, 'Ayodhya Kanda, Sarga 100, Verse 2', 'साधु राघव मा भूत्ते बुद्धिरेवं निरर्थका।
प्राकृतस्य नरस्येव आर्य बुद्धेस्तपस्विनः॥', 'sādhu rāghava mā bhūt te buddhir evaṃ nirarthakā
prākṛtasya narasyeva ārya buddhes tapasvinaḥ', null, 2100002),
('ramayana-2-100-3', 3, 'Ayodhya Kanda, Sarga 100, Verse 3', 'कः कस्य पुरुषो बन्धुः किमाप्यं कस्य केन चित्।
यदेको जायते जन्तुरेक एव विनश्यति॥', 'kaḥ kasya puruṣo bandhuḥ kim āpyaṃ kasya kena cit
yad eko jāyate jantur eka eva vinaśyati', null, 2100003),
('ramayana-2-100-4', 4, 'Ayodhya Kanda, Sarga 100, Verse 4', 'तस्मान्माता पिता चेति राम सज्जेत यो नरः।
उन्मत्त इव स ज्ञेयो नास्ति का चिद्धि कस्य चित्॥', 'tasmān mātā pitā ceti rāma sajjeta yo naraḥ
unmatta iva sa jñeyo nāsti kā cid dhi kasya cit', null, 2100004),
('ramayana-2-100-5', 5, 'Ayodhya Kanda, Sarga 100, Verse 5', 'यथा ग्रामान्तरं गच्छन्नरः कश्चित्क्व चिद्वसेत्।
उत्सृज्य च तमावासं प्रतिष्ठेतापरेऽहनि॥', 'yathā grāmāntaraṃ gacchan naraḥ kaś cit kva cid vaset
utsṛjya ca tam āvāsaṃ pratiṣṭhetāpare ''hani', null, 2100005),
('ramayana-2-100-6', 6, 'Ayodhya Kanda, Sarga 100, Verse 6', 'एवमेव मनुष्याणां पिता माता गृहं वसु।
आवासमात्रं काकुत्स्थ सज्जन्ते नात्र सज्जनाः॥', 'evam eva manuṣyāṇāṃ pitā mātā gṛhaṃ vasu
āvāsamātraṃ kākutstha sajjante nātra sajjanāḥ', null, 2100006),
('ramayana-2-100-7', 7, 'Ayodhya Kanda, Sarga 100, Verse 7', 'पित्र्यं राज्यं समुत्सृज्य स नार्हति नरोत्तम।
आस्थातुं कापथं दुःखं विषमं बहुकण्टकम्॥', 'pitryaṃ rājyaṃ samutsṛjya sa nārhati narottama
āsthātuṃ kāpathaṃ duḥkhaṃ viṣamaṃ bahukaṇṭakam', null, 2100007),
('ramayana-2-100-8', 8, 'Ayodhya Kanda, Sarga 100, Verse 8', 'समृद्धायामयोध्यायामात्मानमभिषेचय।
एकवेणीधरा हि त्वां नगरी संप्रतीक्षते॥', 'samṛddhāyām ayodhyāyām ātmānam abhiṣecaya
ekaveṇīdharā hi tvāṃ nagarī saṃpratīkṣate', null, 2100008),
('ramayana-2-100-9', 9, 'Ayodhya Kanda, Sarga 100, Verse 9', 'राजभोगाननुभवन्महार्हान्पार्थिवात्मज।
विहर त्वमयोध्यायां यथा शक्रस्त्रिविष्टपे॥', 'rājabhogān anubhavan mahārhān pārthivātmaja
vihara tvam ayodhyāyāṃ yathā śakras triviṣṭape', null, 2100009),
('ramayana-2-100-10', 10, 'Ayodhya Kanda, Sarga 100, Verse 10', 'न ते कश्चिद्दशरतःस्त्वं च तस्य न कश्चन।
अन्यो राजा त्वमन्यश्च तस्मात्कुरु यदुच्यते॥', 'na te kaś cid daśarataḥs tvaṃ ca tasya na kaś cana
anyo rājā tvam anyaś ca tasmāt kuru yad ucyate', null, 2100010),
('ramayana-2-100-11', 11, 'Ayodhya Kanda, Sarga 100, Verse 11', 'गतः स नृपतिस्तत्र गन्तव्यं यत्र तेन वै।
प्रवृत्तिरेषा मर्त्यानां त्वं तु मिथ्या विहन्यसे॥', 'gataḥ sa nṛpatis tatra gantavyaṃ yatra tena vai
pravṛttir eṣā martyānāṃ tvaṃ tu mithyā vihanyase', null, 2100011),
('ramayana-2-100-12', 12, 'Ayodhya Kanda, Sarga 100, Verse 12', 'अर्थधर्मपरा ये ये तांस्ताञ्शोचामि नेतरान्।
ते हि दुःखमिह प्राप्य विनाशं प्रेत्य भेजिरे॥', 'arthadharmaparā ye ye tāṃs tāñ śocāmi netarān
te hi duḥkham iha prāpya vināśaṃ pretya bhejire', null, 2100012),
('ramayana-2-100-13', 13, 'Ayodhya Kanda, Sarga 100, Verse 13', 'अष्टका पितृदैवत्यमित्ययं प्रसृतो जनः।
अन्नस्योपद्रवं पश्य मृतो हि किमशिष्यति॥', 'aṣṭakā pitṛdaivatyam ity ayaṃ prasṛto janaḥ
annasyopadravaṃ paśya mṛto hi kim aśiṣyati', null, 2100013),
('ramayana-2-100-14', 14, 'Ayodhya Kanda, Sarga 100, Verse 14', 'यदि भुक्तमिहान्येन देहमन्यस्य गच्छति।
दद्यात्प्रवसतः श्राद्धं न तत्पथ्यशनं भवेत्॥', 'yadi bhuktam ihānyena deham anyasya gacchati
dadyāt pravasataḥ śrāddhaṃ na tat pathy aśanaṃ bhavet', null, 2100014),
('ramayana-2-100-15', 15, 'Ayodhya Kanda, Sarga 100, Verse 15', 'दानसंवनना ह्येते ग्रन्था मेधाविभिः कृताः।
यजस्व देहि दीक्षस्व तपस्तप्यस्व संत्यज॥', 'dānasaṃvananā hy ete granthā medhāvibhiḥ kṛtāḥ
yajasva dehi dīkṣasva tapas tapyasva saṃtyaja', null, 2100015),
('ramayana-2-100-16', 16, 'Ayodhya Kanda, Sarga 100, Verse 16', 'स नास्ति परमित्येव कुरु बुद्धिं महामते।
प्रत्यक्षं यत्तदातिष्ठ परोक्षं पृष्ठतः कुरु॥', 'sa nāsti param ity eva kuru buddhiṃ mahāmate
pratyakṣaṃ yat tad ātiṣṭha parokṣaṃ pṛṣṭhataḥ kuru', null, 2100016),
('ramayana-2-100-17', 17, 'Ayodhya Kanda, Sarga 100, Verse 17', 'सतां बुद्धिं पुरस्कृत्य सर्वलोकनिदर्शिनीम्।
राज्यं त्वं प्रतिगृह्णीष्व भरतेन प्रसादितः॥', 'satāṃ buddhiṃ puraskṛtya sarvalokanidarśinīm
rājyaṃ tvaṃ pratigṛhṇīṣva bharatena prasāditaḥ', null, 2100017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 101 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-101-1', 1, 'Ayodhya Kanda, Sarga 101, Verse 1', 'जाबालेस्तु वचः श्रुत्वा रामः सत्यात्मनां वरः।
उवाच परया युक्त्या स्वबुद्ध्या चाविपन्नया॥', 'jābāles tu vacaḥ śrutvā rāmaḥ satyātmanāṃ varaḥ
uvāca parayā yuktyā svabuddhyā cāvipannayā', null, 2101001),
('ramayana-2-101-2', 2, 'Ayodhya Kanda, Sarga 101, Verse 2', 'भवान्मे प्रियकामार्थं वचनं यदिहोक्तवान्।
अकार्यं कार्यसंकाशमपथ्यं पथ्यसंमितम्॥', 'bhavān me priyakāmārthaṃ vacanaṃ yad ihoktavān
akāryaṃ kāryasaṃkāśam apathyaṃ pathyasaṃmitam', null, 2101002),
('ramayana-2-101-3', 3, 'Ayodhya Kanda, Sarga 101, Verse 3', 'निर्मर्यादस्तु पुरुषः पापाचारसमन्वितः।
मानं न लभते सत्सु भिन्नचारित्रदर्शनः॥', 'nirmaryādas tu puruṣaḥ pāpācārasamanvitaḥ
mānaṃ na labhate satsu bhinnacāritradarśanaḥ', null, 2101003),
('ramayana-2-101-4', 4, 'Ayodhya Kanda, Sarga 101, Verse 4', 'कुलीनमकुलीनं वा वीरं पुरुषमानिनम्।
चारित्रमेव व्याख्याति शुचिं वा यदि वाशुचिम्॥', 'kulīnam akulīnaṃ vā vīraṃ puruṣamāninam
cāritram eva vyākhyāti śuciṃ vā yadi vāśucim', null, 2101004),
('ramayana-2-101-5', 5, 'Ayodhya Kanda, Sarga 101, Verse 5', 'अनार्यस्त्वार्यसंकाशः शौचाद्धीनस्तथा शुचिः।
लक्षण्यवदलक्षण्यो दुःशीलः शीलवानिव॥', 'anāryas tv āryasaṃkāśaḥ śaucād dhīnas tathā śuciḥ
lakṣaṇyavad alakṣaṇyo duḥśīlaḥ śīlavān iva', null, 2101005),
('ramayana-2-101-6', 6, 'Ayodhya Kanda, Sarga 101, Verse 6', 'अधर्मं धर्मवेषेण यदीमं लोकसंकरम्।
अभिपत्स्ये शुभं हित्वा क्रियाविधिविवर्जितम्॥', 'adharmaṃ dharmaveṣeṇa yadīmaṃ lokasaṃkaram
abhipatsye śubhaṃ hitvā kriyāvidhivivarjitam', null, 2101006),
('ramayana-2-101-7', 7, 'Ayodhya Kanda, Sarga 101, Verse 7', 'कश्चेतयानः पुरुषः कार्याकार्यविचक्षणः।
बहु मंस्यति मां लोके दुर्वृत्तं लोकदूषणम्॥', 'kaś cetayānaḥ puruṣaḥ kāryākāryavicakṣaṇaḥ
bahu maṃsyati māṃ loke durvṛttaṃ lokadūṣaṇam', null, 2101007),
('ramayana-2-101-8', 8, 'Ayodhya Kanda, Sarga 101, Verse 8', 'कस्य यास्याम्यहं वृत्तं केन वा स्वर्गमाप्नुयाम्।
अनया वर्तमानोऽहं वृत्त्या हीनप्रतिज्ञया॥', 'kasya yāsyāmy ahaṃ vṛttaṃ kena vā svargam āpnuyām
anayā vartamāno ''haṃ vṛttyā hīnapratijñayā', null, 2101008),
('ramayana-2-101-9', 9, 'Ayodhya Kanda, Sarga 101, Verse 9', 'कामवृत्तस्त्वयं लोकः कृत्स्नः समुपवर्तते।
यद्वृत्ताः सन्ति राजानस्तद्वृत्ताः सन्ति हि प्रजाः॥', 'kāmavṛttas tv ayaṃ lokaḥ kṛtsnaḥ samupavartate
yadvṛttāḥ santi rājānas tadvṛttāḥ santi hi prajāḥ', null, 2101009),
('ramayana-2-101-10', 10, 'Ayodhya Kanda, Sarga 101, Verse 10', 'सत्यमेवानृशंस्यं च राजवृत्तं सनातनम्।
तस्मात्सत्यात्मकं राज्यं सत्ये लोकः प्रतिष्ठितः॥', 'satyam evānṛśaṃsyaṃ ca rājavṛttaṃ sanātanam
tasmāt satyātmakaṃ rājyaṃ satye lokaḥ pratiṣṭhitaḥ', null, 2101010),
('ramayana-2-101-11', 11, 'Ayodhya Kanda, Sarga 101, Verse 11', 'ऋषयश्चैव देवाश्च सत्यमेव हि मेनिरे।
सत्यवादी हि लोकेऽस्मिन्परमं गच्छति क्षयम्॥', 'ṛṣayaś caiva devāś ca satyam eva hi menire
satyavādī hi loke ''smin paramaṃ gacchati kṣayam', null, 2101011),
('ramayana-2-101-12', 12, 'Ayodhya Kanda, Sarga 101, Verse 12', 'उद्विजन्ते यथा सर्पान्नरादनृतवादिनः।
धर्मः सत्यं परो लोके मूलं स्वर्गस्य चोच्यते॥', 'udvijante yathā sarpān narād anṛtavādinaḥ
dharmaḥ satyaṃ paro loke mūlaṃ svargasya cocyate', null, 2101012),
('ramayana-2-101-13', 13, 'Ayodhya Kanda, Sarga 101, Verse 13', 'सत्यमेवेश्वरो लोके सत्यं पद्मा समाश्रिता।
सत्यमूलानि सर्वाणि सत्यान्नास्ति परं पदम्॥', 'satyam eveśvaro loke satyaṃ padmā samāśritā
satyamūlāni sarvāṇi satyān nāsti paraṃ padam', null, 2101013),
('ramayana-2-101-14', 14, 'Ayodhya Kanda, Sarga 101, Verse 14', 'दत्तमिष्टं हुतं चैव तप्तानि च तपांसि च।
वेदाः सत्यप्रतिष्ठानास्तस्मात्सत्यपरो भवेत्॥', 'dattam iṣṭaṃ hutaṃ caiva taptāni ca tapāṃsi ca
vedāḥ satyapratiṣṭhānās tasmāt satyaparo bhavet', null, 2101014),
('ramayana-2-101-15', 15, 'Ayodhya Kanda, Sarga 101, Verse 15', 'एकः पालयते लोकमेकः पालयते कुलम्।
मज्जत्येको हि निरय एकः स्वर्गे महीयते॥', 'ekaḥ pālayate lokam ekaḥ pālayate kulam
majjaty eko hi niraya ekaḥ svarge mahīyate', null, 2101015),
('ramayana-2-101-16', 16, 'Ayodhya Kanda, Sarga 101, Verse 16', 'सोऽहं पितुर्निदेशं तु किमर्थं नानुपालये।
सत्यप्रतिश्रवः सत्यं सत्येन समयीकृतः॥', 'so ''haṃ pitur nideśaṃ tu kimarthaṃ nānupālaye
satyapratiśravaḥ satyaṃ satyena samayīkṛtaḥ', null, 2101016),
('ramayana-2-101-17', 17, 'Ayodhya Kanda, Sarga 101, Verse 17', 'नैव लोभान्न मोहाद्वा न चाज्ञानात्तमोऽन्वितः।
सेतुं सत्यस्य भेत्स्यामि गुरोः सत्यप्रतिश्रवः॥', 'naiva lobhān na mohād vā na cājñānāt tamo''nvitaḥ
setuṃ satyasya bhetsyāmi guroḥ satyapratiśravaḥ', null, 2101017),
('ramayana-2-101-18', 18, 'Ayodhya Kanda, Sarga 101, Verse 18', 'असत्यसंधस्य सतश्चलस्यास्थिरचेतसः।
नैव देवा न पितरः प्रतीच्छन्तीति नः श्रुतम्॥', 'asatyasaṃdhasya sataś calasyāsthiracetasaḥ
naiva devā na pitaraḥ pratīcchantīti naḥ śrutam', null, 2101018),
('ramayana-2-101-19', 19, 'Ayodhya Kanda, Sarga 101, Verse 19', 'प्रत्यगात्ममिमं धर्मं सत्यं पश्याम्यहं स्वयम्।
भारः सत्पुरुषाचीर्णस्तदर्थमभिनन्द्यते॥', 'pratyagātmam imaṃ dharmaṃ satyaṃ paśyāmy ahaṃ svayam
bhāraḥ satpuruṣācīrṇas tad artham abhinandyate', null, 2101019),
('ramayana-2-101-20', 20, 'Ayodhya Kanda, Sarga 101, Verse 20', 'क्षात्रं धर्ममहं त्यक्ष्ये ह्यधर्मं धर्मसंहितम्।
क्षुद्रौर्नृशंसैर्लुब्धैश्च सेवितं पापकर्मभिः॥', 'kṣātraṃ dharmam ahaṃ tyakṣye hy adharmaṃ dharmasaṃhitam
kṣudraur nṛśaṃsair lubdhaiś ca sevitaṃ pāpakarmabhiḥ', null, 2101020),
('ramayana-2-101-21', 21, 'Ayodhya Kanda, Sarga 101, Verse 21', 'कायेन कुरुते पापं मनसा संप्रधार्य च।
अनृतं जिह्वया चाह त्रिविधं कर्म पातकम्॥', 'kāyena kurute pāpaṃ manasā saṃpradhārya ca
anṛtaṃ jihvayā cāha trividhaṃ karma pātakam', null, 2101021),
('ramayana-2-101-22', 22, 'Ayodhya Kanda, Sarga 101, Verse 22', 'भूमिः कीर्तिर्यशो लक्ष्मीः पुरुषं प्रार्थयन्ति हि।
स्वर्गस्थं चानुबध्नन्ति सत्यमेव भजेत तत्॥', 'bhūmiḥ kīrtir yaśo lakṣmīḥ puruṣaṃ prārthayanti hi
svargasthaṃ cānubadhnanti satyam eva bhajeta tat', null, 2101022),
('ramayana-2-101-23', 23, 'Ayodhya Kanda, Sarga 101, Verse 23', 'श्रेष्ठं ह्यनार्यमेव स्याद्यद्भवानवधार्य माम्।
आह युक्तिकरैर्वाक्यैरिदं भद्रं कुरुष्व ह॥', 'śreṣṭhaṃ hy anāryam eva syād yad bhavān avadhārya mām
āha yuktikarair vākyair idaṃ bhadraṃ kuruṣva ha', null, 2101023),
('ramayana-2-101-24', 24, 'Ayodhya Kanda, Sarga 101, Verse 24', 'कथं ह्यहं प्रतिज्ञाय वनवासमिमं गुरोः।
भरतस्य करिष्यामि वचो हित्वा गुरोर्वचः॥', 'kathaṃ hy ahaṃ pratijñāya vanavāsam imaṃ guroḥ
bharatasya kariṣyāmi vaco hitvā guror vacaḥ', null, 2101024),
('ramayana-2-101-25', 25, 'Ayodhya Kanda, Sarga 101, Verse 25', 'स्थिरा मया प्रतिज्ञाता प्रतिज्ञा गुरुसंनिधौ।
प्रहृष्टमानसा देवी कैकेयी चाभवत्तदा॥', 'sthirā mayā pratijñātā pratijñā gurusaṃnidhau
prahṛṣṭamānasā devī kaikeyī cābhavat tadā', null, 2101025),
('ramayana-2-101-26', 26, 'Ayodhya Kanda, Sarga 101, Verse 26', 'वनवासं वसन्नेवं शुचिर्नियतभोजनः।
मूलैः पुष्पैः फलैः पुण्यैः पितॄन्देवांश्च तर्पयन्॥', 'vanavāsaṃ vasann evaṃ śucir niyatabhojanaḥ
mūlaiḥ puṣpaiḥ phalaiḥ puṇyaiḥ pitṝn devāṃś ca tarpayan', null, 2101026),
('ramayana-2-101-27', 27, 'Ayodhya Kanda, Sarga 101, Verse 27', 'संतुष्टपञ्चवर्गोऽहं लोकयात्रां प्रवर्तये।
अकुहः श्रद्दधानः सन्कार्याकार्यविचक्षणः॥', 'saṃtuṣṭapañcavargo ''haṃ lokayātrāṃ pravartaye
akuhaḥ śraddadhānaḥ san kāryākāryavicakṣaṇaḥ', null, 2101027),
('ramayana-2-101-28', 28, 'Ayodhya Kanda, Sarga 101, Verse 28', 'कर्मभूमिमिमां प्राप्य कर्तव्यं कर्म यच्छुभम्।
अग्निर्वायुश्च सोमश्च कर्मणां फलभागिनः॥', 'karmabhūmim imāṃ prāpya kartavyaṃ karma yac chubham
agnir vāyuś ca somaś ca karmaṇāṃ phalabhāginaḥ', null, 2101028),
('ramayana-2-101-29', 29, 'Ayodhya Kanda, Sarga 101, Verse 29', 'शतं क्रतूनामाहृत्य देवराट्त्रिदिवं गतः।
तपांस्युग्राणि चास्थाय दिवं याता महर्षयः॥', 'śataṃ kratūnām āhṛtya devarāṭ tridivaṃ gataḥ
tapāṃsy ugrāṇi cāsthāya divaṃ yātā maharṣayaḥ', null, 2101029),
('ramayana-2-101-30', 30, 'Ayodhya Kanda, Sarga 101, Verse 30', 'सत्यं च धर्मं च पराक्रमं च भूतानुकम्पां प्रियवादितां च।
द्विजातिदेवातिथिपूजनं च पन्थानमाहुस्त्रिदिवस्य सन्तः॥', 'satyaṃ ca dharmaṃ ca parākramaṃ ca bhūtānukampāṃ priyavāditāṃ ca
dvijātidevātithipūjanaṃ ca panthānam āhus tridivasya santaḥ', null, 2101030),
('ramayana-2-101-31', 31, 'Ayodhya Kanda, Sarga 101, Verse 31', 'धर्मे रताः सत्पुरुषैः समेतास्तेजस्विनो दानगुणप्रधानाः।
अहिंसका वीतमलाश्च लोके भवन्ति पूज्या मुनयः प्रधानाः॥', 'dharme ratāḥ satpuruṣaiḥ sametās tejasvino dānaguṇapradhānāḥ
ahiṃsakā vītamalāś ca loke bhavanti pūjyā munayaḥ pradhānāḥ', null, 2101031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 102 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-102-1', 1, 'Ayodhya Kanda, Sarga 102, Verse 1', 'क्रुद्धमाज्ञाय रामं तु वसिष्ठः प्रत्युवाच ह।
जाबालिरपि जानीते लोकस्यास्य गतागतिम्।
निवर्तयितुकामस्तु त्वामेतद्वाक्यमब्रवीत्॥', 'kruddham ājñāya rāmaṃ tu vasiṣṭhaḥ pratyuvāca ha
jābālir api jānīte lokasyāsya gatāgatim
nivartayitukāmas tu tvām etad vākyam abravīt', null, 2102001),
('ramayana-2-102-2', 2, 'Ayodhya Kanda, Sarga 102, Verse 2', 'इमां लोकसमुत्पत्तिं लोकनाथ निबोध मे।
सर्वं सलिलमेवासीत्पृथिवी यत्र निर्मिता।
ततः समभवद्ब्रह्मा स्वयम्भूर्दैवतैः सह॥', 'imāṃ lokasamutpattiṃ lokanātha nibodha me
sarvaṃ salilam evāsīt pṛthivī yatra nirmitā
tataḥ samabhavad brahmā svayambhūr daivataiḥ saha', null, 2102002),
('ramayana-2-102-3', 3, 'Ayodhya Kanda, Sarga 102, Verse 3', 'स वराहस्ततो भूत्वा प्रोज्जहार वसुंधराम्।
असृजच्च जगत्सर्वं सह पुत्रैः कृतात्मभिः॥', 'sa varāhas tato bhūtvā projjahāra vasuṃdharām
asṛjac ca jagat sarvaṃ saha putraiḥ kṛtātmabhiḥ', null, 2102003),
('ramayana-2-102-4', 4, 'Ayodhya Kanda, Sarga 102, Verse 4', 'आकाशप्रभवो ब्रह्मा शाश्वतो नित्य अव्ययः।
तस्मान्मरीचिः संजज्ञे मरीचेः कश्यपः सुतः॥', 'ākāśaprabhavo brahmā śāśvato nitya avyayaḥ
tasmān marīciḥ saṃjajñe marīceḥ kaśyapaḥ sutaḥ', null, 2102004),
('ramayana-2-102-5', 5, 'Ayodhya Kanda, Sarga 102, Verse 5', 'विवस्वान्कश्यपाज्जज्ञे मनुर्वैवस्वतः स्मृतः।
स तु प्रजापतिः पूर्वमिक्ष्वाकुस्तु मनोः सुतः॥', 'vivasvān kaśyapāj jajñe manur vaivasvataḥ smṛtaḥ
sa tu prajāpatiḥ pūrvam ikṣvākus tu manoḥ sutaḥ', null, 2102005),
('ramayana-2-102-6', 6, 'Ayodhya Kanda, Sarga 102, Verse 6', 'यस्येयं प्रथमं दत्ता समृद्धा मनुना मही।
तमिक्ष्वाकुमयोध्यायां राजानं विद्धि पूर्वकम्॥', 'yasyeyaṃ prathamaṃ dattā samṛddhā manunā mahī
tam ikṣvākum ayodhyāyāṃ rājānaṃ viddhi pūrvakam', null, 2102006),
('ramayana-2-102-7', 7, 'Ayodhya Kanda, Sarga 102, Verse 7', 'इक्ष्वाकोस्तु सुतः श्रीमान्कुक्षिरेवेति विश्रुतः।
कुक्षेरथात्मजो वीरो विकुक्षिरुदपद्यत॥', 'ikṣvākos tu sutaḥ śrīmān kukṣir eveti viśrutaḥ
kukṣer athātmajo vīro vikukṣir udapadyata', null, 2102007),
('ramayana-2-102-8', 8, 'Ayodhya Kanda, Sarga 102, Verse 8', 'विकुक्षेस्तु महातेजा बाणः पुत्रः प्रतापवान्।
बाणस्य तु महाबाहुरनरण्यो महायशाः॥', 'vikukṣes tu mahātejā bāṇaḥ putraḥ pratāpavān
bāṇasya tu mahābāhur anaraṇyo mahāyaśāḥ', null, 2102008),
('ramayana-2-102-9', 9, 'Ayodhya Kanda, Sarga 102, Verse 9', 'नानावृष्टिर्बभूवास्मिन्न दुर्भिक्षं सतां वरे।
अनरण्ये महाराजे तस्करो वापि कश्चन॥', 'nānāvṛṣṭir babhūvāsmin na durbhikṣaṃ satāṃ vare
anaraṇye mahārāje taskaro vāpi kaś cana', null, 2102009),
('ramayana-2-102-10', 10, 'Ayodhya Kanda, Sarga 102, Verse 10', 'अनरण्यान्महाबाहुः पृथू राजा बभूव ह।
तस्मात्पृथोर्महाराजस्त्रिशङ्कुरुदपद्यत।
स सत्यवचनाद्वीरः सशरीरो दिवं गतः॥', 'anaraṇyān mahābāhuḥ pṛthū rājā babhūva ha
tasmāt pṛthor mahārājas triśaṅkur udapadyata
sa satyavacanād vīraḥ saśarīro divaṃ gataḥ', null, 2102010),
('ramayana-2-102-11', 11, 'Ayodhya Kanda, Sarga 102, Verse 11', 'त्रिशङ्कोरभवत्सूनुर्धुन्धुमारो महायशाः।
धुन्धुमारान्महातेजा युवनाश्वो व्यजायत॥', 'triśaṅkor abhavat sūnur dhundhumāro mahāyaśāḥ
dhundhumārān mahātejā yuvanāśvo vyajāyata', null, 2102011),
('ramayana-2-102-12', 12, 'Ayodhya Kanda, Sarga 102, Verse 12', 'युवनाश्व सुतः श्रीमान्मान्धाता समपद्यत।
मान्धातुस्तु महातेजाः सुसंधिरुदपद्यत॥', 'yuvanāśva sutaḥ śrīmān māndhātā samapadyata
māndhātus tu mahātejāḥ susaṃdhir udapadyata', null, 2102012),
('ramayana-2-102-13', 13, 'Ayodhya Kanda, Sarga 102, Verse 13', 'सुसंधेरपि पुत्रौ द्वौ ध्रुवसंधिः प्रसेनजित्।
यशस्वी ध्रुवसंधेस्तु भरतो रिपुसूदनः॥', 'susaṃdher api putrau dvau dhruvasaṃdhiḥ prasenajit
yaśasvī dhruvasaṃdhes tu bharato ripusūdanaḥ', null, 2102013),
('ramayana-2-102-14', 14, 'Ayodhya Kanda, Sarga 102, Verse 14', 'भरतात्तु महाबाहोरसितो नाम जायत।
यस्यैते प्रतिराजान उदपद्यन्त शत्रवः।
हैहयास्तालजङ्घाश्च शूराश्च शशबिन्दवः॥', 'bharatāt tu mahābāhor asito nāma jāyata
yasyaite pratirājāna udapadyanta śatravaḥ
haihayās tālajaṅghāś ca śūrāś ca śaśabindavaḥ', null, 2102014),
('ramayana-2-102-15', 15, 'Ayodhya Kanda, Sarga 102, Verse 15', 'तांस्तु सर्वान्प्रतिव्यूह्य युद्धे राजा प्रवासितः।
स च शैलवरे रम्ये बभूवाभिरतो मुनिः।
द्वे चास्य भार्ये गर्भिण्यौ बभूवतुरिति श्रुतिः॥', 'tāṃs tu sarvān prativyūhya yuddhe rājā pravāsitaḥ
sa ca śailavare ramye babhūvābhirato muniḥ
dve cāsya bhārye garbhiṇyau babhūvatur iti śrutiḥ', null, 2102015),
('ramayana-2-102-16', 16, 'Ayodhya Kanda, Sarga 102, Verse 16', 'भार्गवश्च्यवनो नाम हिमवन्तमुपाश्रितः।
तमृषिं समुपागम्य कालिन्दी त्वभ्यवादयत्॥', 'bhārgavaś cyavano nāma himavantam upāśritaḥ
tam ṛṣiṃ samupāgamya kālindī tv abhyavādayat', null, 2102016),
('ramayana-2-102-17', 17, 'Ayodhya Kanda, Sarga 102, Verse 17', 'स तामभ्यवदद्विप्रो वरेप्सुं पुत्रजन्मनि।
ततः सा गृहमागम्य देवी पुत्रं व्यजायत॥', 'sa tām abhyavadad vipro varepsuṃ putrajanmani
tataḥ sā gṛham āgamya devī putraṃ vyajāyata', null, 2102017),
('ramayana-2-102-18', 18, 'Ayodhya Kanda, Sarga 102, Verse 18', 'सपत्न्या तु गरस्तस्यै दत्तो गर्भजिघांसया।
गरेण सह तेनैव जातः स सगरोऽभवत्॥', 'sapatnyā tu garas tasyai datto garbhajighāṃsayā
gareṇa saha tenaiva jātaḥ sa sagaro ''bhavat', null, 2102018),
('ramayana-2-102-19', 19, 'Ayodhya Kanda, Sarga 102, Verse 19', 'स राजा सगरो नाम यः समुद्रमखानयत्।
इष्ट्वा पर्वणि वेगेन त्रासयन्तमिमाः प्रजाः॥', 'sa rājā sagaro nāma yaḥ samudram akhānayat
iṣṭvā parvaṇi vegena trāsayantam imāḥ prajāḥ', null, 2102019),
('ramayana-2-102-20', 20, 'Ayodhya Kanda, Sarga 102, Verse 20', 'असमञ्जस्तु पुत्रोऽभूत्सगरस्येति नः श्रुतम्।
जीवन्नेव स पित्रा तु निरस्तः पापकर्मकृत्॥', 'asamañjas tu putro ''bhūt sagarasyeti naḥ śrutam
jīvann eva sa pitrā tu nirastaḥ pāpakarmakṛt', null, 2102020),
('ramayana-2-102-21', 21, 'Ayodhya Kanda, Sarga 102, Verse 21', 'अंशुमानिति पुत्रोऽभूदसमञ्जस्य वीर्यवान्।
दिलीपोऽंशुमतः पुत्रो दिलीपस्य भगीरथः॥', 'aṃśumān iti putro ''bhūd asamañjasya vīryavān
dilīpo ''ṃśumataḥ putro dilīpasya bhagīrathaḥ', null, 2102021),
('ramayana-2-102-22', 22, 'Ayodhya Kanda, Sarga 102, Verse 22', 'भगीरथात्ककुत्स्थस्तु काकुत्स्था येन तु स्मृताः।
ककुत्स्थस्य तु पुत्रोऽभूद्रघुर्येन तु राघवः॥', 'bhagīrathāt kakutsthas tu kākutsthā yena tu smṛtāḥ
kakutsthasya tu putro ''bhūd raghur yena tu rāghavaḥ', null, 2102022),
('ramayana-2-102-23', 23, 'Ayodhya Kanda, Sarga 102, Verse 23', 'रघोस्तु पुत्रस्तेजस्वी प्रवृद्धः पुरुषादकः।
कल्माषपादः सौदास इत्येवं प्रथितो भुवि॥', 'raghos tu putras tejasvī pravṛddhaḥ puruṣādakaḥ
kalmāṣapādaḥ saudāsa ity evaṃ prathito bhuvi', null, 2102023),
('ramayana-2-102-24', 24, 'Ayodhya Kanda, Sarga 102, Verse 24', 'कल्माषपादपुत्रोऽभूच्छङ्खणस्त्विति विश्रुतः।
यस्तु तद्वीर्यमासाद्य सहसेनो व्यनीनशत्॥', 'kalmāṣapādaputro ''bhūc chaṅkhaṇas tv iti viśrutaḥ
yas tu tad vīryam āsādya sahaseno vyanīnaśat', null, 2102024),
('ramayana-2-102-25', 25, 'Ayodhya Kanda, Sarga 102, Verse 25', 'शङ्खणस्य तु पुत्रोऽभूच्छूरः श्रीमान्सुदर्शनः।
सुदर्शनस्याग्निवर्ण अग्निवर्षस्य शीघ्रगः॥', 'śaṅkhaṇasya tu putro ''bhūc chūraḥ śrīmān sudarśanaḥ
sudarśanasyāgnivarṇa agnivarṣasya śīghragaḥ', null, 2102025),
('ramayana-2-102-26', 26, 'Ayodhya Kanda, Sarga 102, Verse 26', 'शीघ्रगस्य मरुः पुत्रो मरोः पुत्रः प्रशुश्रुकः।
प्रशुश्रुकस्य पुत्रोऽभूदम्बरीषो महाद्युतिः॥', 'śīghragasya maruḥ putro maroḥ putraḥ praśuśrukaḥ
praśuśrukasya putro ''bhūd ambarīṣo mahādyutiḥ', null, 2102026),
('ramayana-2-102-27', 27, 'Ayodhya Kanda, Sarga 102, Verse 27', 'अम्बरीषस्य पुत्रोऽभून्नहुषः सत्यविक्रमः।
नहुषस्य च नाभागः पुत्रः परमधार्मिकः॥', 'ambarīṣasya putro ''bhūn nahuṣaḥ satyavikramaḥ
nahuṣasya ca nābhāgaḥ putraḥ paramadhārmikaḥ', null, 2102027),
('ramayana-2-102-28', 28, 'Ayodhya Kanda, Sarga 102, Verse 28', 'अजश्च सुव्रतश्चैव नाभागस्य सुतावुभौ।
अजस्य चैव धर्मात्मा राजा दशरथः सुतः॥', 'ajaś ca suvrataś caiva nābhāgasya sutāv ubhau
ajasya caiva dharmātmā rājā daśarathaḥ sutaḥ', null, 2102028),
('ramayana-2-102-29', 29, 'Ayodhya Kanda, Sarga 102, Verse 29', 'तस्य ज्येष्ठोऽसि दायादो राम इत्यभिविश्रुतः।
तद्गृहाण स्वकं राज्यमवेक्षस्व जगन्नृप॥', 'tasya jyeṣṭho ''si dāyādo rāma ity abhiviśrutaḥ
tad gṛhāṇa svakaṃ rājyam avekṣasva jagan nṛpa', null, 2102029),
('ramayana-2-102-30', 30, 'Ayodhya Kanda, Sarga 102, Verse 30', 'इक्ष्वाकूणां हि सर्वेषां राजा भवति पूर्वजः।
पूर्वजे नावरः पुत्रो ज्येष्ठो राज्येऽभिषिच्यते॥', 'ikṣvākūṇāṃ hi sarveṣāṃ rājā bhavati pūrvajaḥ
pūrvaje nāvaraḥ putro jyeṣṭho rājye ''bhiṣicyate', null, 2102030),
('ramayana-2-102-31', 31, 'Ayodhya Kanda, Sarga 102, Verse 31', 'स राघवाणां कुलधर्ममात्मनः सनातनं नाद्य विहातुमर्हसि।
प्रभूतरत्नामनुशाधि मेदिनीं प्रभूतराष्ट्रां पितृवन्महायशाः॥', 'sa rāghavāṇāṃ kuladharmam ātmanaḥ sanātanaṃ nādya vihātum arhasi
prabhūtaratnām anuśādhi medinīṃ prabhūtarāṣṭrāṃ pitṛvan mahāyaśāḥ', null, 2102031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 103 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-103-1', 1, 'Ayodhya Kanda, Sarga 103, Verse 1', 'वसिष्ठस्तु तदा राममुक्त्वा राजपुरोहितः।
अब्रवीद्धर्मसंयुक्तं पुनरेवापरं वचः॥', 'vasiṣṭhas tu tadā rāmam uktvā rājapurohitaḥ
abravīd dharmasaṃyuktaṃ punar evāparaṃ vacaḥ', null, 2103001),
('ramayana-2-103-2', 2, 'Ayodhya Kanda, Sarga 103, Verse 2', 'पुरुषस्येह जातस्य भवन्ति गुरवस्त्रयः।
आचार्यश्चैव काकुत्स्थ पिता माता च राघव॥', 'puruṣasyeha jātasya bhavanti guravas trayaḥ
ācāryaś caiva kākutstha pitā mātā ca rāghava', null, 2103002),
('ramayana-2-103-3', 3, 'Ayodhya Kanda, Sarga 103, Verse 3', 'पिता ह्येनं जनयति पुरुषं पुरुषर्षभ।
प्रज्ञां ददाति चाचार्यस्तस्मात्स गुरुरुच्यते॥', 'pitā hy enaṃ janayati puruṣaṃ puruṣarṣabha
prajñāṃ dadāti cācāryas tasmāt sa gurur ucyate', null, 2103003),
('ramayana-2-103-4', 4, 'Ayodhya Kanda, Sarga 103, Verse 4', 'स तेऽहं पितुराचार्यस्तव चैव परंतप।
मम त्वं वचनं कुर्वन्नातिवर्तेः सतां गतिम्॥', 'sa te ''haṃ pitur ācāryas tava caiva paraṃtapa
mama tvaṃ vacanaṃ kurvan nātivarteḥ satāṃ gatim', null, 2103004),
('ramayana-2-103-5', 5, 'Ayodhya Kanda, Sarga 103, Verse 5', 'इमा हि ते परिषदः श्रेणयश्च समागताः।
एषु तात चरन्धर्मं नातिवर्तेः सतां गतिम्॥', 'imā hi te pariṣadaḥ śreṇayaś ca samāgatāḥ
eṣu tāta caran dharmaṃ nātivarteḥ satāṃ gatim', null, 2103005),
('ramayana-2-103-6', 6, 'Ayodhya Kanda, Sarga 103, Verse 6', 'वृद्धाया धर्मशीलाया मातुर्नार्हस्यवर्तितुम्।
अस्यास्तु वचनं कुर्वन्नातिवर्तेः सतां गतिम्॥', 'vṛddhāyā dharmaśīlāyā mātur nārhasy avartitum
asyās tu vacanaṃ kurvan nātivarteḥ satāṃ gatim', null, 2103006),
('ramayana-2-103-7', 7, 'Ayodhya Kanda, Sarga 103, Verse 7', 'भरतस्य वचः कुर्वन्याचमानस्य राघव।
आत्मानं नातिवर्तेस्त्वं सत्यधर्मपराक्रम॥', 'bharatasya vacaḥ kurvan yācamānasya rāghava
ātmānaṃ nātivartes tvaṃ satyadharmaparākrama', null, 2103007),
('ramayana-2-103-8', 8, 'Ayodhya Kanda, Sarga 103, Verse 8', 'एवं मधुरमुक्तस्तु गुरुणा राघवः स्वयम्।
प्रत्युवाच समासीनं वसिष्ठं पुरुषर्षभः॥', 'evaṃ madhuram uktas tu guruṇā rāghavaḥ svayam
pratyuvāca samāsīnaṃ vasiṣṭhaṃ puruṣarṣabhaḥ', null, 2103008),
('ramayana-2-103-9', 9, 'Ayodhya Kanda, Sarga 103, Verse 9', 'यन्मातापितरौ वृत्तं तनये कुरुतः सदा।
न सुप्रतिकरं तत्तु मात्रा पित्रा च यत्कृतम्॥', 'yan mātāpitarau vṛttaṃ tanaye kurutaḥ sadā
na supratikaraṃ tat tu mātrā pitrā ca yat kṛtam', null, 2103009),
('ramayana-2-103-10', 10, 'Ayodhya Kanda, Sarga 103, Verse 10', 'यथाशक्ति प्रदानेन स्नापनाच्छादनेन च।
नित्यं च प्रियवादेन तथा संवर्धनेन च॥', 'yathāśakti pradānena snāpanāc chādanena ca
nityaṃ ca priyavādena tathā saṃvardhanena ca', null, 2103010),
('ramayana-2-103-11', 11, 'Ayodhya Kanda, Sarga 103, Verse 11', 'स हि राजा जनयिता पिता दशरथो मम।
आज्ञातं यन्मया तस्य न तन्मिथ्या भविष्यति॥', 'sa hi rājā janayitā pitā daśaratho mama
ājñātaṃ yan mayā tasya na tan mithyā bhaviṣyati', null, 2103011),
('ramayana-2-103-12', 12, 'Ayodhya Kanda, Sarga 103, Verse 12', 'एवमुक्तस्तु रामेण भरतः प्रत्यनन्तरम्।
उवाच परमोदारः सूतं परमदुर्मनाः॥', 'evam uktas tu rāmeṇa bharataḥ pratyanantaram
uvāca paramodāraḥ sūtaṃ paramadurmanāḥ', null, 2103012),
('ramayana-2-103-13', 13, 'Ayodhya Kanda, Sarga 103, Verse 13', 'इह मे स्थण्डिले शीघ्रं कुशानास्तर सारथे।
आर्यं प्रत्युपवेक्ष्यामि यावन्मे न प्रसीदति॥', 'iha me sthaṇḍile śīghraṃ kuśān āstara sārathe
āryaṃ pratyupavekṣyāmi yāvan me na prasīdati', null, 2103013),
('ramayana-2-103-14', 14, 'Ayodhya Kanda, Sarga 103, Verse 14', 'अनाहारो निरालोको धनहीनो यथा द्विजः।
शेष्ये पुरस्ताच्छालाया यावन्न प्रतियास्यति॥', 'anāhāro nirāloko dhanahīno yathā dvijaḥ
śeṣye purastāc chālāyā yāvan na pratiyāsyati', null, 2103014),
('ramayana-2-103-15', 15, 'Ayodhya Kanda, Sarga 103, Verse 15', 'स तु राममवेक्षन्तं सुमन्त्रं प्रेक्ष्य दुर्मनाः।
कुशोत्तरमुपस्थाप्य भूमावेवास्तरत्स्वयम्॥', 'sa tu rāmam avekṣantaṃ sumantraṃ prekṣya durmanāḥ
kuśottaram upasthāpya bhūmāv evāstarat svayam', null, 2103015),
('ramayana-2-103-16', 16, 'Ayodhya Kanda, Sarga 103, Verse 16', 'तमुवाच महातेजा रामो राजर्षिसत्तमाः।
किं मां भरत कुर्वाणं तात प्रत्युपवेक्ष्यसि॥', 'tam uvāca mahātejā rāmo rājarṣisattamāḥ
kiṃ māṃ bharata kurvāṇaṃ tāta pratyupavekṣyasi', null, 2103016),
('ramayana-2-103-17', 17, 'Ayodhya Kanda, Sarga 103, Verse 17', 'ब्राह्मणो ह्येकपार्श्वेन नरान्रोद्धुमिहार्हति।
न तु मूर्धावसिक्तानां विधिः प्रत्युपवेशने॥', 'brāhmaṇo hy ekapārśvena narān roddhum ihārhati
na tu mūrdhāvasiktānāṃ vidhiḥ pratyupaveśane', null, 2103017),
('ramayana-2-103-18', 18, 'Ayodhya Kanda, Sarga 103, Verse 18', 'उत्तिष्ठ नरशार्दूल हित्वैतद्दारुणं व्रतम्।
पुरवर्यामितः क्षिप्रमयोध्यां याहि राघव॥', 'uttiṣṭha naraśārdūla hitvaitad dāruṇaṃ vratam
puravaryām itaḥ kṣipram ayodhyāṃ yāhi rāghava', null, 2103018),
('ramayana-2-103-19', 19, 'Ayodhya Kanda, Sarga 103, Verse 19', 'आसीनस्त्वेव भरतः पौरजानपदं जनम्।
उवाच सर्वतः प्रेक्ष्य किमार्यं नानुशासथ॥', 'āsīnas tv eva bharataḥ paurajānapadaṃ janam
uvāca sarvataḥ prekṣya kim āryaṃ nānuśāsatha', null, 2103019),
('ramayana-2-103-20', 20, 'Ayodhya Kanda, Sarga 103, Verse 20', 'ते तमूचुर्महात्मानं पौरजानपदा जनाः।
काकुत्स्थमभिजानीमः सम्यग्वदति राघवः॥', 'te tam ūcur mahātmānaṃ paurajānapadā janāḥ
kākutstham abhijānīmaḥ samyag vadati rāghavaḥ', null, 2103020),
('ramayana-2-103-21', 21, 'Ayodhya Kanda, Sarga 103, Verse 21', 'एषोऽपि हि महाभागः पितुर्वचसि तिष्ठति।
अत एव न शक्ताः स्मो व्यावर्तयितुमञ्जसा॥', 'eṣo ''pi hi mahābhāgaḥ pitur vacasi tiṣṭhati
ata eva na śaktāḥ smo vyāvartayitum añjasā', null, 2103021),
('ramayana-2-103-22', 22, 'Ayodhya Kanda, Sarga 103, Verse 22', 'तेषामाज्ञाय वचनं रामो वचनमब्रवीत्।
एवं निबोध वचनं सुहृदां धर्मचक्षुषाम्॥', 'teṣām ājñāya vacanaṃ rāmo vacanam abravīt
evaṃ nibodha vacanaṃ suhṛdāṃ dharmacakṣuṣām', null, 2103022),
('ramayana-2-103-23', 23, 'Ayodhya Kanda, Sarga 103, Verse 23', 'एतच्चैवोभयं श्रुत्वा सम्यक्संपश्य राघव।
उत्तिष्ठ त्वं महाबाहो मां च स्पृश तथोदकम्॥', 'etac caivobhayaṃ śrutvā samyak saṃpaśya rāghava
uttiṣṭha tvaṃ mahābāho māṃ ca spṛśa tathodakam', null, 2103023),
('ramayana-2-103-24', 24, 'Ayodhya Kanda, Sarga 103, Verse 24', 'अथोत्थाय जलं स्पृष्ट्वा भरतो वाक्यमब्रवीत्।
शृण्वन्तु मे परिषदो मन्त्रिणः श्रेणयस्तथा॥', 'athotthāya jalaṃ spṛṣṭvā bharato vākyam abravīt
śṛṇvantu me pariṣado mantriṇaḥ śreṇayas tathā', null, 2103024),
('ramayana-2-103-25', 25, 'Ayodhya Kanda, Sarga 103, Verse 25', 'न याचे पितरं राज्यं नानुशासामि मातरम्।
आर्यं परमधर्मज्ञमभिजानामि राघवम्॥', 'na yāce pitaraṃ rājyaṃ nānuśāsāmi mātaram
āryaṃ paramadharmajñam abhijānāmi rāghavam', null, 2103025),
('ramayana-2-103-26', 26, 'Ayodhya Kanda, Sarga 103, Verse 26', 'यदि त्ववश्यं वस्तव्यं कर्तव्यं च पितुर्वचः।
अहमेव निवत्स्यामि चतुर्दश वने समाः॥', 'yadi tv avaśyaṃ vastavyaṃ kartavyaṃ ca pitur vacaḥ
aham eva nivatsyāmi caturdaśa vane samāḥ', null, 2103026),
('ramayana-2-103-27', 27, 'Ayodhya Kanda, Sarga 103, Verse 27', 'धर्मात्मा तस्य तथ्येन भ्रातुर्वाक्येन विस्मितः।
उवाच रामः संप्रेक्ष्य पौरजानपदं जनम्॥', 'dharmātmā tasya tathyena bhrātur vākyena vismitaḥ
uvāca rāmaḥ saṃprekṣya paurajānapadaṃ janam', null, 2103027),
('ramayana-2-103-28', 28, 'Ayodhya Kanda, Sarga 103, Verse 28', 'विक्रीतमाहितं क्रीतं यत्पित्रा जीवता मम।
न तल्लोपयितुं शक्यं मया वा भरतेन वा॥', 'vikrītam āhitaṃ krītaṃ yat pitrā jīvatā mama
na tal lopayituṃ śakyaṃ mayā vā bharatena vā', null, 2103028),
('ramayana-2-103-29', 29, 'Ayodhya Kanda, Sarga 103, Verse 29', 'उपधिर्न मया कार्यो वनवासे जुगुप्सितः।
युक्तमुक्तं च कैकेय्या पित्रा मे सुकृतं कृतम्॥', 'upadhir na mayā kāryo vanavāse jugupsitaḥ
yuktam uktaṃ ca kaikeyyā pitrā me sukṛtaṃ kṛtam', null, 2103029),
('ramayana-2-103-30', 30, 'Ayodhya Kanda, Sarga 103, Verse 30', 'जानामि भरतं क्षान्तं गुरुसत्कारकारिणम्।
सर्वमेवात्र कल्याणं सत्यसंधे महात्मनि॥', 'jānāmi bharataṃ kṣāntaṃ gurusatkārakāriṇam
sarvam evātra kalyāṇaṃ satyasaṃdhe mahātmani', null, 2103030),
('ramayana-2-103-31', 31, 'Ayodhya Kanda, Sarga 103, Verse 31', 'अनेन धर्मशीलेन वनात्प्रत्यागतः पुनः।
भ्रात्रा सह भविष्यामि पृथिव्याः पतिरुत्तमः॥', 'anena dharmaśīlena vanāt pratyāgataḥ punaḥ
bhrātrā saha bhaviṣyāmi pṛthivyāḥ patir uttamaḥ', null, 2103031),
('ramayana-2-103-32', 32, 'Ayodhya Kanda, Sarga 103, Verse 32', 'वृतो राजा हि कैकेय्या मया तद्वचनं कृतम्।
अनृतान्मोचयानेन पितरं तं महीपतिम्॥', 'vṛto rājā hi kaikeyyā mayā tad vacanaṃ kṛtam
anṛtān mocayānena pitaraṃ taṃ mahīpatim', null, 2103032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 104 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-104-1', 1, 'Ayodhya Kanda, Sarga 104, Verse 1', 'तमप्रतिमतेजोभ्यां भ्रातृभ्यां रोमहर्षणम्।
विस्मिताः संगमं प्रेक्ष्य समवेता महर्षयः॥', 'tam apratimatejobhyāṃ bhrātṛbhyāṃ romaharṣaṇam
vismitāḥ saṃgamaṃ prekṣya samavetā maharṣayaḥ', null, 2104001),
('ramayana-2-104-2', 2, 'Ayodhya Kanda, Sarga 104, Verse 2', 'अन्तर्हितास्त्वृषिगणाः सिद्धाश्च परमर्षयः।
तौ भ्रातरौ महात्मानौ काकुत्स्थौ प्रशशंसिरे॥', 'antarhitās tv ṛṣigaṇāḥ siddhāś ca paramarṣayaḥ
tau bhrātarau mahātmānau kākutsthau praśaśaṃsire', null, 2104002),
('ramayana-2-104-3', 3, 'Ayodhya Kanda, Sarga 104, Verse 3', 'स धन्यो यस्य पुत्रौ द्वौ धर्मज्ञौ धर्मविक्रमौ।
श्रुत्वा वयं हि संभाषामुभयोः स्पृहयामहे॥', 'sa dhanyo yasya putrau dvau dharmajñau dharmavikramau
śrutvā vayaṃ hi saṃbhāṣām ubhayoḥ spṛhayāmahe', null, 2104003),
('ramayana-2-104-4', 4, 'Ayodhya Kanda, Sarga 104, Verse 4', 'ततस्त्वृषिगणाः क्षिप्रं दशग्रीववधैषिणः।
भरतं राजशार्दूलमित्यूचुः संगता वचः॥', 'tatas tv ṛṣigaṇāḥ kṣipraṃ daśagrīvavadhaiṣiṇaḥ
bharataṃ rājaśārdūlam ity ūcuḥ saṃgatā vacaḥ', null, 2104004),
('ramayana-2-104-5', 5, 'Ayodhya Kanda, Sarga 104, Verse 5', 'कुले जात महाप्राज्ञ महावृत्त महायशः।
ग्राह्यं रामस्य वाक्यं ते पितरं यद्यवेक्षसे॥', 'kule jāta mahāprājña mahāvṛtta mahāyaśaḥ
grāhyaṃ rāmasya vākyaṃ te pitaraṃ yady avekṣase', null, 2104005),
('ramayana-2-104-6', 6, 'Ayodhya Kanda, Sarga 104, Verse 6', 'सदानृणमिमं रामं वयमिच्छामहे पितुः।
अनृणत्वाच्च कैकेय्याः स्वर्गं दशरथो गतः॥', 'sadānṛṇam imaṃ rāmaṃ vayam icchāmahe pituḥ
anṛṇatvāc ca kaikeyyāḥ svargaṃ daśaratho gataḥ', null, 2104006),
('ramayana-2-104-7', 7, 'Ayodhya Kanda, Sarga 104, Verse 7', 'एतावदुक्त्वा वचनं गन्धर्वाः समहर्षयः।
राजर्षयश्चैव तथा सर्वे स्वां स्वां गतिं गताः॥', 'etāvad uktvā vacanaṃ gandharvāḥ samaharṣayaḥ
rājarṣayaś caiva tathā sarve svāṃ svāṃ gatiṃ gatāḥ', null, 2104007),
('ramayana-2-104-8', 8, 'Ayodhya Kanda, Sarga 104, Verse 8', 'ह्लादितस्तेन वाक्येन शुभेन शुभदर्शनः।
रामः संहृष्टवदनस्तानृषीनभ्यपूजयत्॥', 'hlāditas tena vākyena śubhena śubhadarśanaḥ
rāmaḥ saṃhṛṣṭavadanas tān ṛṣīn abhyapūjayat', null, 2104008),
('ramayana-2-104-9', 9, 'Ayodhya Kanda, Sarga 104, Verse 9', 'स्रस्तगात्रस्तु भरतः स वाचा सज्जमानया।
कृताञ्जलिरिदं वाक्यं राघवं पुनरब्रवीत्॥', 'srastagātras tu bharataḥ sa vācā sajjamānayā
kṛtāñjalir idaṃ vākyaṃ rāghavaṃ punar abravīt', null, 2104009),
('ramayana-2-104-10', 10, 'Ayodhya Kanda, Sarga 104, Verse 10', 'राजधर्ममनुप्रेक्ष्य कुलधर्मानुसंततिम्।
कर्तुमर्हसि काकुत्स्थ मम मातुश्च याचनाम्॥', 'rājadharmam anuprekṣya kuladharmānusaṃtatim
kartum arhasi kākutstha mama mātuś ca yācanām', null, 2104010),
('ramayana-2-104-11', 11, 'Ayodhya Kanda, Sarga 104, Verse 11', 'रक्षितुं सुमहद्राज्यमहमेकस्तु नोत्सहे।
पौरजानपदांश्चापि रक्तान्रञ्जयितुं तथा॥', 'rakṣituṃ sumahad rājyam aham ekas tu notsahe
paurajānapadāṃś cāpi raktān rañjayituṃ tathā', null, 2104011),
('ramayana-2-104-12', 12, 'Ayodhya Kanda, Sarga 104, Verse 12', 'ज्ञातयश्च हि योधाश्च मित्राणि सुहृदश्च नः।
त्वामेव प्रतिकाङ्क्षन्ते पर्जन्यमिव कर्षकाः॥', 'jñātayaś ca hi yodhāś ca mitrāṇi suhṛdaś ca naḥ
tvām eva pratikāṅkṣante parjanyam iva karṣakāḥ', null, 2104012),
('ramayana-2-104-13', 13, 'Ayodhya Kanda, Sarga 104, Verse 13', 'इदं राज्यं महाप्राज्ञ स्थापय प्रतिपद्य हि।
शक्तिमानसि काकुत्स्थ लोकस्य परिपालने॥', 'idaṃ rājyaṃ mahāprājña sthāpaya pratipadya hi
śaktimān asi kākutstha lokasya paripālane', null, 2104013),
('ramayana-2-104-14', 14, 'Ayodhya Kanda, Sarga 104, Verse 14', 'इत्युक्त्वा न्यपतद्भ्रातुः पादयोर्भरतस्तदा।
भृशं संप्रार्थयामास राममेवं प्रियं वदः॥', 'ity uktvā nyapatad bhrātuḥ pādayor bharatas tadā
bhṛśaṃ saṃprārthayām āsa rāmam evaṃ priyaṃ vadaḥ', null, 2104014),
('ramayana-2-104-15', 15, 'Ayodhya Kanda, Sarga 104, Verse 15', 'तमङ्के भ्रातरं कृत्वा रामो वचनमब्रवीत्।
श्यामं नलिनपत्राक्षं मत्तहंसस्वरः स्वयम्॥', 'tam aṅke bhrātaraṃ kṛtvā rāmo vacanam abravīt
śyāmaṃ nalinapatrākṣaṃ mattahaṃsasvaraḥ svayam', null, 2104015),
('ramayana-2-104-16', 16, 'Ayodhya Kanda, Sarga 104, Verse 16', 'आगता त्वामियं बुद्धिः स्वजा वैनयिकी च या।
भृशमुत्सहसे तात रक्षितुं पृथिवीमपि॥', 'āgatā tvām iyaṃ buddhiḥ svajā vainayikī ca yā
bhṛśam utsahase tāta rakṣituṃ pṛthivīm api', null, 2104016),
('ramayana-2-104-17', 17, 'Ayodhya Kanda, Sarga 104, Verse 17', 'अमात्यैश्च सुहृद्भिश्च बुद्धिमद्भिश्च मन्त्रिभिः।
सर्वकार्याणि संमन्त्र्य सुमहान्त्यपि कारय॥', 'amātyaiś ca suhṛdbhiś ca buddhimadbhiś ca mantribhiḥ
sarvakāryāṇi saṃmantrya sumahānty api kāraya', null, 2104017),
('ramayana-2-104-18', 18, 'Ayodhya Kanda, Sarga 104, Verse 18', 'लक्ष्मीश्चन्द्रादपेयाद्वा हिमवान्वा हिमं त्यजेत्।
अतीयात्सागरो वेलां न प्रतिज्ञामहं पितुः॥', 'lakṣmīś candrād apeyād vā himavān vā himaṃ tyajet
atīyāt sāgaro velāṃ na pratijñām ahaṃ pituḥ', null, 2104018),
('ramayana-2-104-19', 19, 'Ayodhya Kanda, Sarga 104, Verse 19', 'कामाद्वा तात लोभाद्वा मात्रा तुभ्यमिदं कृतम्।
न तन्मनसि कर्तव्यं वर्तितव्यं च मातृवत्॥', 'kāmād vā tāta lobhād vā mātrā tubhyam idaṃ kṛtam
na tan manasi kartavyaṃ vartitavyaṃ ca mātṛvat', null, 2104019),
('ramayana-2-104-20', 20, 'Ayodhya Kanda, Sarga 104, Verse 20', 'एवं ब्रुवाणं भरतः कौसल्यासुतमब्रवीत्।
तेजसादित्यसंकाशं प्रतिपच्चन्द्रदर्शनम्॥', 'evaṃ bruvāṇaṃ bharataḥ kausalyāsutam abravīt
tejasādityasaṃkāśaṃ pratipaccandradarśanam', null, 2104020),
('ramayana-2-104-21', 21, 'Ayodhya Kanda, Sarga 104, Verse 21', 'अधिरोहार्य पादाभ्यां पादुके हेमभूषिते।
एते हि सर्वलोकस्य योगक्षेमं विधास्यतः॥', 'adhirohārya pādābhyāṃ pāduke hemabhūṣite
ete hi sarvalokasya yogakṣemaṃ vidhāsyataḥ', null, 2104021),
('ramayana-2-104-22', 22, 'Ayodhya Kanda, Sarga 104, Verse 22', 'सोऽधिरुह्य नरव्याघ्रः पादुके ह्यवरुह्य च।
प्रायच्छत्सुमहातेजा भरताय महात्मने॥', 'so ''dhiruhya naravyāghraḥ pāduke hy avaruhya ca
prāyacchat sumahātejā bharatāya mahātmane', null, 2104022),
('ramayana-2-104-23', 23, 'Ayodhya Kanda, Sarga 104, Verse 23', 'स पादुके ते भरतः प्रतापवान्स्वलंकृते संपरिगृह्य धर्मवित्।
प्रदक्षिणं चैव चकार राघवं चकार चैवोत्तमनागमूर्धनि॥', 'sa pāduke te bharataḥ pratāpavān svalaṃkṛte saṃparigṛhya dharmavit
pradakṣiṇaṃ caiva cakāra rāghavaṃ cakāra caivottamanāgamūrdhani', null, 2104023),
('ramayana-2-104-24', 24, 'Ayodhya Kanda, Sarga 104, Verse 24', 'अथानुपूर्व्यात्प्रतिपूज्य तं जनं गुरूंश्च मन्त्रिप्रकृतीस्तथानुजौ।
व्यसर्जयद्राघववंशवर्धनः स्थितः स्वधर्मे हिमवानिवाचलः॥', 'athānupūrvyāt pratipūjya taṃ janaṃ gurūṃś ca mantriprakṛtīs tathānujau
vyasarjayad rāghavavaṃśavardhanaḥ sthitaḥ svadharme himavān ivācalaḥ', null, 2104024),
('ramayana-2-104-25', 25, 'Ayodhya Kanda, Sarga 104, Verse 25', 'तं मातरो बाष्पगृहीतकण्ठो दुःखेन नामन्त्रयितुं हि शेकुः।
स त्वेव मातॄरभिवाद्य सर्वा रुदन्कुटीं स्वां प्रविवेश रामः॥', 'taṃ mātaro bāṣpagṛhītakaṇṭho duḥkhena nāmantrayituṃ hi śekuḥ
sa tv eva mātṝr abhivādya sarvā rudan kuṭīṃ svāṃ praviveśa rāmaḥ', null, 2104025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 105 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-105-1', 1, 'Ayodhya Kanda, Sarga 105, Verse 1', 'ततः शिरसि कृत्वा तु पादुके भरतस्तदा।
आरुरोह रथं हृष्टः शत्रुघ्नेन समन्वितः॥', 'tataḥ śirasi kṛtvā tu pāduke bharatas tadā
āruroha rathaṃ hṛṣṭaḥ śatrughnena samanvitaḥ', null, 2105001),
('ramayana-2-105-2', 2, 'Ayodhya Kanda, Sarga 105, Verse 2', 'वसिष्ठो वामदेवश्च जाबालिश्च दृढव्रतः।
अग्रतः प्रययुः सर्वे मन्त्रिणो मन्त्रपूजिताः॥', 'vasiṣṭho vāmadevaś ca jābāliś ca dṛḍhavrataḥ
agrataḥ prayayuḥ sarve mantriṇo mantrapūjitāḥ', null, 2105002),
('ramayana-2-105-3', 3, 'Ayodhya Kanda, Sarga 105, Verse 3', 'मन्दाकिनीं नदीं रम्यां प्राङ्मुखास्ते ययुस्तदा।
प्रदक्षिणं च कुर्वाणाश्चित्रकूटं महागिरिम्॥', 'mandākinīṃ nadīṃ ramyāṃ prāṅmukhās te yayus tadā
pradakṣiṇaṃ ca kurvāṇāś citrakūṭaṃ mahāgirim', null, 2105003),
('ramayana-2-105-4', 4, 'Ayodhya Kanda, Sarga 105, Verse 4', 'पश्यन्धातुसहस्राणि रम्याणि विविधानि च।
प्रययौ तस्य पार्श्वेन ससैन्यो भरतस्तदा॥', 'paśyan dhātusahasrāṇi ramyāṇi vividhāni ca
prayayau tasya pārśvena sasainyo bharatas tadā', null, 2105004),
('ramayana-2-105-5', 5, 'Ayodhya Kanda, Sarga 105, Verse 5', 'अदूराच्चित्रकूटस्य ददर्श भरतस्तदा।
आश्रमं यत्र स मुनिर्भरद्वाजः कृतालयः॥', 'adūrāc citrakūṭasya dadarśa bharatas tadā
āśramaṃ yatra sa munir bharadvājaḥ kṛtālayaḥ', null, 2105005),
('ramayana-2-105-6', 6, 'Ayodhya Kanda, Sarga 105, Verse 6', 'स तमाश्रममागम्य भरद्वाजस्य बुद्धिमान्।
अवतीर्य रथात्पादौ ववन्दे कुलनन्दनः॥', 'sa tam āśramam āgamya bharadvājasya buddhimān
avatīrya rathāt pādau vavande kulanandanaḥ', null, 2105006),
('ramayana-2-105-7', 7, 'Ayodhya Kanda, Sarga 105, Verse 7', 'ततो हृष्टो भरद्वाजो भरतं वाक्यमब्रवीत्।
अपि कृत्यं कृतं तात रामेण च समागतम्॥', 'tato hṛṣṭo bharadvājo bharataṃ vākyam abravīt
api kṛtyaṃ kṛtaṃ tāta rāmeṇa ca samāgatam', null, 2105007),
('ramayana-2-105-8', 8, 'Ayodhya Kanda, Sarga 105, Verse 8', 'एवमुक्तस्तु भरतो भरद्वाजेन धीमता।
प्रत्युवाच भरद्वाजं भरतो धर्मवत्सलः॥', 'evam uktas tu bharato bharadvājena dhīmatā
pratyuvāca bharadvājaṃ bharato dharmavatsalaḥ', null, 2105008),
('ramayana-2-105-9', 9, 'Ayodhya Kanda, Sarga 105, Verse 9', 'स याच्यमानो गुरुणा मया च दृढविक्रमः।
राघवः परमप्रीतो वसिष्ठं वाक्यमब्रवीत्॥', 'sa yācyamāno guruṇā mayā ca dṛḍhavikramaḥ
rāghavaḥ paramaprīto vasiṣṭhaṃ vākyam abravīt', null, 2105009),
('ramayana-2-105-10', 10, 'Ayodhya Kanda, Sarga 105, Verse 10', 'पितुः प्रतिज्ञां तामेव पालयिष्यामि तत्त्वतः।
चतुर्दश हि वर्षाणि य प्रतिज्ञा पितुर्मम॥', 'pituḥ pratijñāṃ tām eva pālayiṣyāmi tattvataḥ
caturdaśa hi varṣāṇi ya pratijñā pitur mama', null, 2105010),
('ramayana-2-105-11', 11, 'Ayodhya Kanda, Sarga 105, Verse 11', 'एवमुक्तो महाप्राज्ञो वसिष्ठः प्रत्युवाच ह।
वाक्यज्ञो वाक्यकुशलं राघवं वचनं महत्॥', 'evam ukto mahāprājño vasiṣṭhaḥ pratyuvāca ha
vākyajño vākyakuśalaṃ rāghavaṃ vacanaṃ mahat', null, 2105011),
('ramayana-2-105-12', 12, 'Ayodhya Kanda, Sarga 105, Verse 12', 'एते प्रयच्छ संहृष्टः पादुके हेमभूषिते।
अयोध्यायां महाप्राज्ञ योगक्षेमकरे तव॥', 'ete prayaccha saṃhṛṣṭaḥ pāduke hemabhūṣite
ayodhyāyāṃ mahāprājña yogakṣemakare tava', null, 2105012),
('ramayana-2-105-13', 13, 'Ayodhya Kanda, Sarga 105, Verse 13', 'एवमुक्तो वसिष्ठेन राघवः प्राङ्मुखः स्थितः।
पादुके हेमविकृते मम राज्याय ते ददौ॥', 'evam ukto vasiṣṭhena rāghavaḥ prāṅmukhaḥ sthitaḥ
pāduke hemavikṛte mama rājyāya te dadau', null, 2105013),
('ramayana-2-105-14', 14, 'Ayodhya Kanda, Sarga 105, Verse 14', 'निवृत्तोऽहमनुज्ञातो रामेण सुमहात्मना।
अयोध्यामेव गच्छामि गृहीत्वा पादुके शुभे॥', 'nivṛtto ''ham anujñāto rāmeṇa sumahātmanā
ayodhyām eva gacchāmi gṛhītvā pāduke śubhe', null, 2105014),
('ramayana-2-105-15', 15, 'Ayodhya Kanda, Sarga 105, Verse 15', 'एतच्छ्रुत्वा शुभं वाक्यं भरतस्य महात्मनः।
भरद्वाजः शुभतरं मुनिर्वाक्यमुदाहरत्॥', 'etac chrutvā śubhaṃ vākyaṃ bharatasya mahātmanaḥ
bharadvājaḥ śubhataraṃ munir vākyam udāharat', null, 2105015),
('ramayana-2-105-16', 16, 'Ayodhya Kanda, Sarga 105, Verse 16', 'नैतच्चित्रं नरव्याघ्र शीलवृत्तवतां वर।
यदार्यं त्वयि तिष्ठेत्तु निम्ने वृष्टिमिवोदकम्॥', 'naitac citraṃ naravyāghra śīlavṛttavatāṃ vara
yad āryaṃ tvayi tiṣṭhet tu nimne vṛṣṭim ivodakam', null, 2105016),
('ramayana-2-105-17', 17, 'Ayodhya Kanda, Sarga 105, Verse 17', 'अमृतः स महाबाहुः पिता दशरथस्तव।
यस्य त्वमीदृशः पुत्रो धर्मात्मा धर्मवत्सलः॥', 'amṛtaḥ sa mahābāhuḥ pitā daśarathas tava
yasya tvam īdṛśaḥ putro dharmātmā dharmavatsalaḥ', null, 2105017),
('ramayana-2-105-18', 18, 'Ayodhya Kanda, Sarga 105, Verse 18', 'तमृषिं तु महात्मानमुक्तवाक्यं कृताञ्जलिः।
आमन्त्रयितुमारेभे चरणावुपगृह्य च॥', 'tam ṛṣiṃ tu mahātmānam uktavākyaṃ kṛtāñjaliḥ
āmantrayitum ārebhe caraṇāv upagṛhya ca', null, 2105018),
('ramayana-2-105-19', 19, 'Ayodhya Kanda, Sarga 105, Verse 19', 'ततः प्रदक्षिणं कृत्वा भरद्वाजं पुनः पुनः।
भरतस्तु ययौ श्रीमानयोध्यां सह मन्त्रिभिः॥', 'tataḥ pradakṣiṇaṃ kṛtvā bharadvājaṃ punaḥ punaḥ
bharatas tu yayau śrīmān ayodhyāṃ saha mantribhiḥ', null, 2105019),
('ramayana-2-105-20', 20, 'Ayodhya Kanda, Sarga 105, Verse 20', 'यानैश्च शकटैश्चैव हयैश्नागैश्च सा चमूः।
पुनर्निवृत्ता विस्तीर्णा भरतस्यानुयायिनी॥', 'yānaiś ca śakaṭaiś caiva hayaiś nāgaiś ca sā camūḥ
punar nivṛttā vistīrṇā bharatasyānuyāyinī', null, 2105020),
('ramayana-2-105-21', 21, 'Ayodhya Kanda, Sarga 105, Verse 21', 'ततस्ते यमुनां दिव्यां नदीं तीर्त्वोर्मिमालिनीम्।
ददृशुस्तां पुनः सर्वे गङ्गां शिवजलां नदीम्॥', 'tatas te yamunāṃ divyāṃ nadīṃ tīrtvormimālinīm
dadṛśus tāṃ punaḥ sarve gaṅgāṃ śivajalāṃ nadīm', null, 2105021),
('ramayana-2-105-22', 22, 'Ayodhya Kanda, Sarga 105, Verse 22', 'तां रम्यजलसंपूर्णां संतीर्य सह बान्धवः।
शृङ्गवेरपुरं रम्यं प्रविवेश ससैनिकः॥', 'tāṃ ramyajalasaṃpūrṇāṃ saṃtīrya saha bāndhavaḥ
śṛṅgaverapuraṃ ramyaṃ praviveśa sasainikaḥ', null, 2105022),
('ramayana-2-105-23', 23, 'Ayodhya Kanda, Sarga 105, Verse 23', 'शृङ्गवेरपुराद्भूय अयोध्यां संददर्श ह।
भरतो दुःखसंतप्तः सारथिं चेदमब्रवीत्॥', 'śṛṅgaverapurād bhūya ayodhyāṃ saṃdadarśa ha
bharato duḥkhasaṃtaptaḥ sārathiṃ cedam abravīt', null, 2105023),
('ramayana-2-105-24', 24, 'Ayodhya Kanda, Sarga 105, Verse 24', 'सारथे पश्य विध्वस्ता अयोध्या न प्रकाशते।
निराकारा निरानन्दा दीना प्रतिहतस्वना॥', 'sārathe paśya vidhvastā ayodhyā na prakāśate
nirākārā nirānandā dīnā pratihatasvanā', null, 2105024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 106 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-106-1', 1, 'Ayodhya Kanda, Sarga 106, Verse 1', 'स्निग्धगम्भीरघोषेण स्यन्दनेनोपयान्प्रभुः।
अयोध्यां भरतः क्षिप्रं प्रविवेश महायशाः॥', 'snigdhagambhīraghoṣeṇa syandanenopayān prabhuḥ
ayodhyāṃ bharataḥ kṣipraṃ praviveśa mahāyaśāḥ', null, 2106001),
('ramayana-2-106-2', 2, 'Ayodhya Kanda, Sarga 106, Verse 2', 'बिडालोलूकचरितामालीननरवारणाम्।
तिमिराभ्याहतां कालीमप्रकाशां निशामिव॥', 'biḍālolūkacaritām ālīnanaravāraṇām
timirābhyāhatāṃ kālīm aprakāśāṃ niśām iva', null, 2106002),
('ramayana-2-106-3', 3, 'Ayodhya Kanda, Sarga 106, Verse 3', 'राहुशत्रोः प्रियां पत्नीं श्रिया प्रज्वलितप्रभाम्।
ग्रहेणाभ्युत्थितेनैकां रोहिणीमिव पीडिताम्॥', 'rāhuśatroḥ priyāṃ patnīṃ śriyā prajvalitaprabhām
graheṇābhyutthitenaikāṃ rohiṇīm iva pīḍitām', null, 2106003),
('ramayana-2-106-4', 4, 'Ayodhya Kanda, Sarga 106, Verse 4', 'अल्पोष्णक्षुब्धसलिलां घर्मोत्तप्तविहंगमाम्।
लीनमीनझषग्राहां कृशां गिरिनदीमिव॥', 'alpoṣṇakṣubdhasalilāṃ gharmottaptavihaṃgamām
līnamīnajhaṣagrāhāṃ kṛśāṃ girinadīm iva', null, 2106004),
('ramayana-2-106-5', 5, 'Ayodhya Kanda, Sarga 106, Verse 5', 'विधूमामिव हेमाभामध्वराग्निसमुत्थिताम्।
हविरभ्युक्षितां पश्चाच्छिखां विप्रलयं गताम्॥', 'vidhūmām iva hemābhām adhvarāgnisamutthitām
havirabhyukṣitāṃ paścāc chikhāṃ vipralayaṃ gatām', null, 2106005),
('ramayana-2-106-6', 6, 'Ayodhya Kanda, Sarga 106, Verse 6', 'विध्वस्तकवचां रुग्णगजवाजिरथध्वजाम्।
हतप्रवीरामापन्नां चमूमिव महाहवे॥', 'vidhvastakavacāṃ rugṇagajavājirathadhvajām
hatapravīrām āpannāṃ camūm iva mahāhave', null, 2106006),
('ramayana-2-106-7', 7, 'Ayodhya Kanda, Sarga 106, Verse 7', 'सफेनां सस्वनां भूत्वा सागरस्य समुत्थिताम्।
प्रशान्तमारुतोद्धूतां जलोर्मिमिव निःस्वनाम्॥', 'saphenāṃ sasvanāṃ bhūtvā sāgarasya samutthitām
praśāntamārutoddhūtāṃ jalormim iva niḥsvanām', null, 2106007),
('ramayana-2-106-8', 8, 'Ayodhya Kanda, Sarga 106, Verse 8', 'त्यक्तां यज्ञायुधैः सर्वैरभिरूपैश्च याजकैः।
सुत्याकाले विनिर्वृत्ते वेदिं गतरवामिव॥', 'tyaktāṃ yajñāyudhaiḥ sarvair abhirūpaiś ca yājakaiḥ
sutyākāle vinirvṛtte vediṃ gataravām iva', null, 2106008),
('ramayana-2-106-9', 9, 'Ayodhya Kanda, Sarga 106, Verse 9', 'गोष्ठमध्ये स्थितामार्तामचरन्तीं नवं तृणम्।
गोवृषेण परित्यक्तां गवां पत्नीमिवोत्सुकाम्॥', 'goṣṭhamadhye sthitām ārtām acarantīṃ navaṃ tṛṇam
govṛṣeṇa parityaktāṃ gavāṃ patnīm ivotsukām', null, 2106009),
('ramayana-2-106-10', 10, 'Ayodhya Kanda, Sarga 106, Verse 10', 'प्रभाकरालैः सुस्निग्धैः प्रज्वलद्भिरिवोत्तमैः।
वियुक्तां मणिभिर्जात्यैर्नवां मुक्तावलीमिव॥', 'prabhākarālaiḥ susnigdhaiḥ prajvaladbhir ivottamaiḥ
viyuktāṃ maṇibhir jātyair navāṃ muktāvalīm iva', null, 2106010),
('ramayana-2-106-11', 11, 'Ayodhya Kanda, Sarga 106, Verse 11', 'सहसा चलितां स्थानान्महीं पुण्यक्षयाद्गताम्।
संहृतद्युतिविस्तारां तारामिव दिवश्च्युताम्॥', 'sahasā calitāṃ sthānān mahīṃ puṇyakṣayād gatām
saṃhṛtadyutivistārāṃ tārām iva divaś cyutām', null, 2106011),
('ramayana-2-106-12', 12, 'Ayodhya Kanda, Sarga 106, Verse 12', 'पुष्पनद्धां वसन्तान्ते मत्तभ्रमरशालिनीम्।
द्रुतदावाग्निविप्लुष्टां क्लान्तां वनलतामिव॥', 'puṣpanaddhāṃ vasantānte mattabhramaraśālinīm
drutadāvāgnivipluṣṭāṃ klāntāṃ vanalatām iva', null, 2106012),
('ramayana-2-106-13', 13, 'Ayodhya Kanda, Sarga 106, Verse 13', 'संमूढनिगमां सर्वां संक्षिप्तविपणापणाम्।
प्रच्छन्नशशिनक्षत्रां द्यामिवाम्बुधरैर्वृताम्॥', 'saṃmūḍhanigamāṃ sarvāṃ saṃkṣiptavipaṇāpaṇām
pracchannaśaśinakṣatrāṃ dyām ivāmbudharair vṛtām', null, 2106013),
('ramayana-2-106-14', 14, 'Ayodhya Kanda, Sarga 106, Verse 14', 'क्षीणपानोत्तमैर्भिन्नैः शरावैरभिसंवृताम्।
हतशौण्डामिवाकाशे पानभूमिमसंस्कृताम्॥', 'kṣīṇapānottamair bhinnaiḥ śarāvair abhisaṃvṛtām
hataśauṇḍām ivākāśe pānabhūmim asaṃskṛtām', null, 2106014),
('ramayana-2-106-15', 15, 'Ayodhya Kanda, Sarga 106, Verse 15', 'वृक्णभूमितलां निम्नां वृक्णपात्रैः समावृताम्।
उपयुक्तोदकां भग्नां प्रपां निपतितामिव॥', 'vṛkṇabhūmitalāṃ nimnāṃ vṛkṇapātraiḥ samāvṛtām
upayuktodakāṃ bhagnāṃ prapāṃ nipatitām iva', null, 2106015),
('ramayana-2-106-16', 16, 'Ayodhya Kanda, Sarga 106, Verse 16', 'विपुलां विततां चैव युक्तपाशां तरस्विनाम्।
भूमौ बाणैर्विनिष्कृत्तां पतितां ज्यामिवायुधात्॥', 'vipulāṃ vitatāṃ caiva yuktapāśāṃ tarasvinām
bhūmau bāṇair viniṣkṛttāṃ patitāṃ jyām ivāyudhāt', null, 2106016),
('ramayana-2-106-17', 17, 'Ayodhya Kanda, Sarga 106, Verse 17', 'सहसा युद्धशौण्डेन हयारोहेण वाहिताम्।
निक्षिप्तभाण्डामुत्सृष्टां किशोरीमिव दुर्बलाम्॥', 'sahasā yuddhaśauṇḍena hayāroheṇa vāhitām
nikṣiptabhāṇḍām utsṛṣṭāṃ kiśorīm iva durbalām', null, 2106017),
('ramayana-2-106-18', 18, 'Ayodhya Kanda, Sarga 106, Verse 18', 'प्रावृषि प्रविगाढायां प्रविष्टस्याभ्र मण्डलम्।
प्रच्छन्नां नीलजीमूतैर्भास्करस्य प्रभामिव॥', 'prāvṛṣi pravigāḍhāyāṃ praviṣṭasyābhra maṇḍalam
pracchannāṃ nīlajīmūtair bhāskarasya prabhām iva', null, 2106018),
('ramayana-2-106-19', 19, 'Ayodhya Kanda, Sarga 106, Verse 19', 'भरतस्तु रथस्थः सञ्श्रीमान्दशरथात्मजः।
वाहयन्तं रथश्रेष्ठं सारथिं वाक्यमब्रवीत्॥', 'bharatas tu rathasthaḥ sañ śrīmān daśarathātmajaḥ
vāhayantaṃ rathaśreṣṭhaṃ sārathiṃ vākyam abravīt', null, 2106019),
('ramayana-2-106-20', 20, 'Ayodhya Kanda, Sarga 106, Verse 20', 'किं नु खल्वद्य गम्भीरो मूर्छितो न निशम्यते।
यथापुरमयोध्यायां गीतवादित्रनिःस्वनः॥', 'kiṃ nu khalv adya gambhīro mūrchito na niśamyate
yathāpuram ayodhyāyāṃ gītavāditraniḥsvanaḥ', null, 2106020),
('ramayana-2-106-21', 21, 'Ayodhya Kanda, Sarga 106, Verse 21', 'वारुणीमदगन्धाश्च माल्यगन्धश्च मूर्छितः।
धूपितागरुगन्धश्च न प्रवाति समन्ततः॥', 'vāruṇīmadagandhāś ca mālyagandhaś ca mūrchitaḥ
dhūpitāgarugandhaś ca na pravāti samantataḥ', null, 2106021),
('ramayana-2-106-22', 22, 'Ayodhya Kanda, Sarga 106, Verse 22', 'यानप्रवरघोषश्च स्निग्धश्च हयनिःस्वनः।
प्रमत्तगजनादश्च महांश्च रथनिःस्वनः।
नेदानीं श्रूयते पुर्यामस्यां रामे विवासिते॥', 'yānapravaraghoṣaś ca snigdhaś ca hayaniḥsvanaḥ
pramattagajanādaś ca mahāṃś ca rathaniḥsvanaḥ
nedānīṃ śrūyate puryām asyāṃ rāme vivāsite', null, 2106022),
('ramayana-2-106-23', 23, 'Ayodhya Kanda, Sarga 106, Verse 23', 'तरुणैश्चारु वेषैश्च नरैरुन्नतगामिभिः।
संपतद्भिरयोध्यायां न विभान्ति महापथाः॥', 'taruṇaiś cāru veṣaiś ca narair unnatagāmibhiḥ
saṃpatadbhir ayodhyāyāṃ na vibhānti mahāpathāḥ', null, 2106023),
('ramayana-2-106-24', 24, 'Ayodhya Kanda, Sarga 106, Verse 24', 'एवं बहुविधं जल्पन्विवेश वसतिं पितुः।
तेन हीनां नरेन्द्रेण सिंहहीनां गुहामिव॥', 'evaṃ bahuvidhaṃ jalpan viveśa vasatiṃ pituḥ
tena hīnāṃ narendreṇa siṃhahīnāṃ guhām iva', null, 2106024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 107 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-107-1', 1, 'Ayodhya Kanda, Sarga 107, Verse 1', 'ततो निक्षिप्य मातॄः स अयोध्यायां दृढव्रतः।
भरतः शोकसंतप्तो गुरूनिदमथाब्रवीत्॥', 'tato nikṣipya mātṝḥ sa ayodhyāyāṃ dṛḍhavrataḥ
bharataḥ śokasaṃtapto gurūn idam athābravīt', null, 2107001),
('ramayana-2-107-2', 2, 'Ayodhya Kanda, Sarga 107, Verse 2', 'नन्दिग्रामं गमिष्यामि सर्वानामन्त्रयेऽद्य वः।
तत्र दुःखमिदं सर्वं सहिष्ये राघवं विना॥', 'nandigrāmaṃ gamiṣyāmi sarvān āmantraye ''dya vaḥ
tatra duḥkham idaṃ sarvaṃ sahiṣye rāghavaṃ vinā', null, 2107002),
('ramayana-2-107-3', 3, 'Ayodhya Kanda, Sarga 107, Verse 3', 'गतश्च हि दिवं राजा वनस्थश्च गुरुर्मम।
रामं प्रतीक्षे राज्याय स हि राजा महायशाः॥', 'gataś ca hi divaṃ rājā vanasthaś ca gurur mama
rāmaṃ pratīkṣe rājyāya sa hi rājā mahāyaśāḥ', null, 2107003),
('ramayana-2-107-4', 4, 'Ayodhya Kanda, Sarga 107, Verse 4', 'एतच्छ्रुत्वा शुभं वाक्यं भरतस्य महात्मनः।
अब्रुवन्मन्त्रिणः सर्वे वसिष्ठश्च पुरोहितः॥', 'etac chrutvā śubhaṃ vākyaṃ bharatasya mahātmanaḥ
abruvan mantriṇaḥ sarve vasiṣṭhaś ca purohitaḥ', null, 2107004),
('ramayana-2-107-5', 5, 'Ayodhya Kanda, Sarga 107, Verse 5', 'सदृशं श्लाघनीयं च यदुक्तं भरत त्वया।
वचनं भ्रातृवात्सल्यादनुरूपं तवैव तत्॥', 'sadṛśaṃ ślāghanīyaṃ ca yad uktaṃ bharata tvayā
vacanaṃ bhrātṛvātsalyād anurūpaṃ tavaiva tat', null, 2107005),
('ramayana-2-107-6', 6, 'Ayodhya Kanda, Sarga 107, Verse 6', 'नित्यं ते बन्धुलुब्धस्य तिष्ठतो भ्रातृसौहृदे।
आर्यमार्गं प्रपन्नस्य नानुमन्येत कः पुमान्॥', 'nityaṃ te bandhulubdhasya tiṣṭhato bhrātṛsauhṛde
āryamārgaṃ prapannasya nānumanyeta kaḥ pumān', null, 2107006),
('ramayana-2-107-7', 7, 'Ayodhya Kanda, Sarga 107, Verse 7', 'मन्त्रिणां वचनं श्रुत्वा यथाभिलषितं प्रियम्।
अब्रवीत्सारथिं वाक्यं रथो मे युज्यतामिति॥', 'mantriṇāṃ vacanaṃ śrutvā yathābhilaṣitaṃ priyam
abravīt sārathiṃ vākyaṃ ratho me yujyatām iti', null, 2107007),
('ramayana-2-107-8', 8, 'Ayodhya Kanda, Sarga 107, Verse 8', 'प्रहृष्टवदनः सर्वा मातॄः समभिवाद्य सः।
आरुरोह रथं श्रीमाञ्शत्रुघ्नेन समन्वितः॥', 'prahṛṣṭavadanaḥ sarvā mātṝḥ samabhivādya saḥ
āruroha rathaṃ śrīmāñ śatrughnena samanvitaḥ', null, 2107008),
('ramayana-2-107-9', 9, 'Ayodhya Kanda, Sarga 107, Verse 9', 'आरुह्य तु रथं शीघ्रं शत्रुघ्नभरतावुभौ।
ययतुः परमप्रीतौ वृतौ मन्त्रिपुरोहितैः॥', 'āruhya tu rathaṃ śīghraṃ śatrughnabharatāv ubhau
yayatuḥ paramaprītau vṛtau mantripurohitaiḥ', null, 2107009),
('ramayana-2-107-10', 10, 'Ayodhya Kanda, Sarga 107, Verse 10', 'अग्रतो पुरवस्तत्र वसिष्ठ प्रमुखा द्विजाः।
प्रययुः प्राङ्मुखाः सर्वे नन्दिग्रामो यतोऽभवत्॥', 'agrato puravas tatra vasiṣṭha pramukhā dvijāḥ
prayayuḥ prāṅmukhāḥ sarve nandigrāmo yato ''bhavat', null, 2107010),
('ramayana-2-107-11', 11, 'Ayodhya Kanda, Sarga 107, Verse 11', 'बलं च तदनाहूतं गजाश्वरथसंकुलम्।
प्रययौ भरते याते सर्वे च पुरवासिनः॥', 'balaṃ ca tad anāhūtaṃ gajāśvarathasaṃkulam
prayayau bharate yāte sarve ca puravāsinaḥ', null, 2107011),
('ramayana-2-107-12', 12, 'Ayodhya Kanda, Sarga 107, Verse 12', 'रथस्थः स तु धर्मात्मा भरतो भ्रातृवत्सलः।
नन्दिग्रामं ययौ तूर्णं शिरस्याधाय पादुके॥', 'rathasthaḥ sa tu dharmātmā bharato bhrātṛvatsalaḥ
nandigrāmaṃ yayau tūrṇaṃ śirasy ādhāya pāduke', null, 2107012),
('ramayana-2-107-13', 13, 'Ayodhya Kanda, Sarga 107, Verse 13', 'ततस्तु भरतः क्षिप्रं नन्दिग्रामं प्रविश्य सः।
अवतीर्य रथात्तूर्णं गुरूनिदमुवाच ह॥', 'tatas tu bharataḥ kṣipraṃ nandigrāmaṃ praviśya saḥ
avatīrya rathāt tūrṇaṃ gurūn idam uvāca ha', null, 2107013),
('ramayana-2-107-14', 14, 'Ayodhya Kanda, Sarga 107, Verse 14', 'एतद्राज्यं मम भ्रात्रा दत्तं संन्यासवत्स्वयम्।
योगक्षेमवहे चेमे पादुके हेमभूषिते।
तमिमं पालयिष्यामि राघवागमनं प्रति॥', 'etad rājyaṃ mama bhrātrā dattaṃ saṃnyāsavat svayam
yogakṣemavahe ceme pāduke hemabhūṣite
tam imaṃ pālayiṣyāmi rāghavāgamanaṃ prati', null, 2107014),
('ramayana-2-107-15', 15, 'Ayodhya Kanda, Sarga 107, Verse 15', 'क्षिप्रं संयोजयित्वा तु राघवस्य पुनः स्वयम्।
चरणौ तौ तु रामस्य द्रक्ष्यामि सहपादुकौ॥', 'kṣipraṃ saṃyojayitvā tu rāghavasya punaḥ svayam
caraṇau tau tu rāmasya drakṣyāmi sahapādukau', null, 2107015),
('ramayana-2-107-16', 16, 'Ayodhya Kanda, Sarga 107, Verse 16', 'ततो निक्षिप्तभारोऽहं राघवेण समागतः।
निवेद्य गुरवे राज्यं भजिष्ये गुरुवृत्तिताम्॥', 'tato nikṣiptabhāro ''haṃ rāghaveṇa samāgataḥ
nivedya gurave rājyaṃ bhajiṣye guruvṛttitām', null, 2107016),
('ramayana-2-107-17', 17, 'Ayodhya Kanda, Sarga 107, Verse 17', 'राघवाय च संन्यासं दत्त्वेमे वरपादुके।
राज्यं चेदमयोध्यां च धूतपापो भवामि च॥', 'rāghavāya ca saṃnyāsaṃ dattveme varapāduke
rājyaṃ cedam ayodhyāṃ ca dhūtapāpo bhavāmi ca', null, 2107017),
('ramayana-2-107-18', 18, 'Ayodhya Kanda, Sarga 107, Verse 18', 'अभिषिक्ते तु काकुत्स्थे प्रहृष्टमुदिते जने।
प्रीतिर्मम यशश्चैव भवेद्राज्याच्चतुर्गुणम्॥', 'abhiṣikte tu kākutsthe prahṛṣṭamudite jane
prītir mama yaśaś caiva bhaved rājyāc caturguṇam', null, 2107018),
('ramayana-2-107-19', 19, 'Ayodhya Kanda, Sarga 107, Verse 19', 'एवं तु विलपन्दीनो भरतः स महायशाः।
नन्दिग्रामेऽकरोद्राज्यं दुःखितो मन्त्रिभिः सह॥', 'evaṃ tu vilapan dīno bharataḥ sa mahāyaśāḥ
nandigrāme ''karod rājyaṃ duḥkhito mantribhiḥ saha', null, 2107019),
('ramayana-2-107-20', 20, 'Ayodhya Kanda, Sarga 107, Verse 20', 'स वल्कलजटाधारी मुनिवेषधरः प्रभुः।
नन्दिग्रामेऽवसद्वीरः ससैन्यो भरतस्तदा॥', 'sa valkalajaṭādhārī muniveṣadharaḥ prabhuḥ
nandigrāme ''vasad vīraḥ sasainyo bharatas tadā', null, 2107020),
('ramayana-2-107-21', 21, 'Ayodhya Kanda, Sarga 107, Verse 21', 'रामागमनमाकाङ्क्षन्भरतो भ्रातृवत्सलः।
भ्रातुर्वचनकारी च प्रतिज्ञापारगस्तदा॥', 'rāmāgamanam ākāṅkṣan bharato bhrātṛvatsalaḥ
bhrātur vacanakārī ca pratijñāpāragas tadā', null, 2107021),
('ramayana-2-107-22', 22, 'Ayodhya Kanda, Sarga 107, Verse 22', 'पादुके त्वभिषिच्याथ नन्दिग्रामेऽवसत्तदा।
भरतः शासनं सर्वं पादुकाभ्यां न्यवेदयत्॥', 'pāduke tv abhiṣicyātha nandigrāme ''vasat tadā
bharataḥ śāsanaṃ sarvaṃ pādukābhyāṃ nyavedayat', null, 2107022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 108 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-108-1', 1, 'Ayodhya Kanda, Sarga 108, Verse 1', 'प्रतिप्रयाते भरते वसन्रामस्तपोवने।
लक्षयामास सोद्वेगमथौत्सुक्यं तपस्विनाम्॥', 'pratiprayāte bharate vasan rāmas tapovane
lakṣayām āsa sodvegam athautsukyaṃ tapasvinām', null, 2108001),
('ramayana-2-108-2', 2, 'Ayodhya Kanda, Sarga 108, Verse 2', 'ये तत्र चित्रकूटस्य पुरस्तात्तापसाश्रमे।
राममाश्रित्य निरतास्तानलक्षयदुत्सुकान्॥', 'ye tatra citrakūṭasya purastāt tāpasāśrame
rāmam āśritya niratās tān alakṣayad utsukān', null, 2108002),
('ramayana-2-108-3', 3, 'Ayodhya Kanda, Sarga 108, Verse 3', 'नयनैर्भृकुटीभिश्च रामं निर्दिश्य शङ्किताः।
अन्योन्यमुपजल्पन्तः शनैश्चक्रुर्मिथः कथाः॥', 'nayanair bhṛkuṭībhiś ca rāmaṃ nirdiśya śaṅkitāḥ
anyonyam upajalpantaḥ śanaiś cakrur mithaḥ kathāḥ', null, 2108003),
('ramayana-2-108-4', 4, 'Ayodhya Kanda, Sarga 108, Verse 4', 'तेषामौत्सुक्यमालक्ष्य रामस्त्वात्मनि शङ्कितः।
कृताञ्जलिरुवाचेदमृषिं कुलपतिं ततः॥', 'teṣām autsukyam ālakṣya rāmas tv ātmani śaṅkitaḥ
kṛtāñjalir uvācedam ṛṣiṃ kulapatiṃ tataḥ', null, 2108004),
('ramayana-2-108-5', 5, 'Ayodhya Kanda, Sarga 108, Verse 5', 'न कच्चिद्भगवन्किं चित्पूर्ववृत्तमिदं मयि।
दृश्यते विकृतं येन विक्रियन्ते तपस्विनः॥', 'na kaccid bhagavan kiṃ cit pūrvavṛttam idaṃ mayi
dṛśyate vikṛtaṃ yena vikriyante tapasvinaḥ', null, 2108005),
('ramayana-2-108-6', 6, 'Ayodhya Kanda, Sarga 108, Verse 6', 'प्रमादाच्चरितं कच्चित्किं चिन्नावरजस्य मे।
लक्ष्मणस्यर्षिभिर्दृष्टं नानुरूपमिवात्मनः॥', 'pramādāc caritaṃ kaccit kiṃ cin nāvarajasya me
lakṣmaṇasyarṣibhir dṛṣṭaṃ nānurūpam ivātmanaḥ', null, 2108006),
('ramayana-2-108-7', 7, 'Ayodhya Kanda, Sarga 108, Verse 7', 'कच्चिच्छुश्रूषमाणा वः शुश्रूषणपरा मयि।
प्रमदाभ्युचितां वृत्तिं सीता युक्तं न वर्तते॥', 'kaccic chuśrūṣamāṇā vaḥ śuśrūṣaṇaparā mayi
pramadābhyucitāṃ vṛttiṃ sītā yuktaṃ na vartate', null, 2108007),
('ramayana-2-108-8', 8, 'Ayodhya Kanda, Sarga 108, Verse 8', 'अथर्षिर्जरया वृद्धस्तपसा च जरां गतः।
वेपमान इवोवाच रामं भूतदयापरम्॥', 'atharṣir jarayā vṛddhas tapasā ca jarāṃ gataḥ
vepamāna ivovāca rāmaṃ bhūtadayāparam', null, 2108008),
('ramayana-2-108-9', 9, 'Ayodhya Kanda, Sarga 108, Verse 9', 'कुतः कल्याणसत्त्वायाः कल्याणाभिरतेस्तथा।
चलनं तात वैदेह्यास्तपस्विषु विशेषतः॥', 'kutaḥ kalyāṇasattvāyāḥ kalyāṇābhirates tathā
calanaṃ tāta vaidehyās tapasviṣu viśeṣataḥ', null, 2108009),
('ramayana-2-108-10', 10, 'Ayodhya Kanda, Sarga 108, Verse 10', 'त्वन्निमित्तमिदं तावत्तापसान्प्रति वर्तते।
रक्षोभ्यस्तेन संविग्नाः कथयन्ति मिथः कथाः॥', 'tvannimittam idaṃ tāvat tāpasān prati vartate
rakṣobhyas tena saṃvignāḥ kathayanti mithaḥ kathāḥ', null, 2108010),
('ramayana-2-108-11', 11, 'Ayodhya Kanda, Sarga 108, Verse 11', 'रावणावरजः कश्चित्खरो नामेह राक्षसः।
उत्पाट्य तापसान्सर्वाञ्जनस्थाननिकेतनान्॥', 'rāvaṇāvarajaḥ kaś cit kharo nāmeha rākṣasaḥ
utpāṭya tāpasān sarvāñ janasthānaniketanān', null, 2108011),
('ramayana-2-108-12', 12, 'Ayodhya Kanda, Sarga 108, Verse 12', 'धृष्टश्च जितकाशी च नृशंसः पुरुषादकः।
अवलिप्तश्च पापश्च त्वां च तात न मृष्यते॥', 'dhṛṣṭaś ca jitakāśī ca nṛśaṃsaḥ puruṣādakaḥ
avaliptaś ca pāpaś ca tvāṃ ca tāta na mṛṣyate', null, 2108012),
('ramayana-2-108-13', 13, 'Ayodhya Kanda, Sarga 108, Verse 13', 'त्वं यदा प्रभृति ह्यस्मिन्नाश्रमे तात वर्तसे।
तदा प्रभृति रक्षांसि विप्रकुर्वन्ति तापसान्॥', 'tvaṃ yadā prabhṛti hy asminn āśrame tāta vartase
tadā prabhṛti rakṣāṃsi viprakurvanti tāpasān', null, 2108013),
('ramayana-2-108-14', 14, 'Ayodhya Kanda, Sarga 108, Verse 14', 'दर्शयन्ति हि बीभत्सैः क्रूरैर्भीषणकैरपि।
नाना रूपैर्विरूपैश्च रूपैरसुखदर्शनैः॥', 'darśayanti hi bībhatsaiḥ krūrair bhīṣaṇakair api
nānā rūpair virūpaiś ca rūpair asukhadarśanaiḥ', null, 2108014),
('ramayana-2-108-15', 15, 'Ayodhya Kanda, Sarga 108, Verse 15', 'अप्रशस्तैरशुचिभिः संप्रयोज्य च तापसान्।
प्रतिघ्नन्त्यपरान्क्षिप्रमनार्याः पुरतः स्थितः॥', 'apraśastair aśucibhiḥ saṃprayojya ca tāpasān
pratighnanty aparān kṣipram anāryāḥ purataḥ sthitaḥ', null, 2108015),
('ramayana-2-108-16', 16, 'Ayodhya Kanda, Sarga 108, Verse 16', 'तेषु तेष्वाश्रमस्थानेष्वबुद्धमवलीय च।
रमन्ते तापसांस्तत्र नाशयन्तोऽल्पचेतसः॥', 'teṣu teṣv āśramasthāneṣv abuddham avalīya ca
ramante tāpasāṃs tatra nāśayanto ''lpacetasaḥ', null, 2108016),
('ramayana-2-108-17', 17, 'Ayodhya Kanda, Sarga 108, Verse 17', 'अपक्षिपन्ति स्रुग्भाण्डानग्नीन्सिञ्चन्ति वारिणा।
कलशांश्च प्रमृद्नन्ति हवने समुपस्थिते॥', 'apakṣipanti srugbhāṇḍān agnīn siñcanti vāriṇā
kalaśāṃś ca pramṛdnanti havane samupasthite', null, 2108017),
('ramayana-2-108-18', 18, 'Ayodhya Kanda, Sarga 108, Verse 18', 'तैर्दुरात्मभिराविष्टानाश्रमान्प्रजिहासवः।
गमनायान्यदेशस्य चोदयन्त्यृषयोऽद्य माम्॥', 'tair durātmabhir āviṣṭān āśramān prajihāsavaḥ
gamanāyānyadeśasya codayanty ṛṣayo ''dya mām', null, 2108018),
('ramayana-2-108-19', 19, 'Ayodhya Kanda, Sarga 108, Verse 19', 'तत्पुरा राम शारीरामुपहिंसां तपस्विषु।
दर्शयति हि दुष्टास्ते त्यक्ष्याम इममाश्रमम्॥', 'tat purā rāma śārīrām upahiṃsāṃ tapasviṣu
darśayati hi duṣṭās te tyakṣyāma imam āśramam', null, 2108019),
('ramayana-2-108-20', 20, 'Ayodhya Kanda, Sarga 108, Verse 20', 'बहुमूलफलं चित्रमविदूरादितो वनम्।
पुराणाश्रममेवाहं श्रयिष्ये सगणः पुनः॥', 'bahumūlaphalaṃ citram avidūrād ito vanam
purāṇāśramam evāhaṃ śrayiṣye sagaṇaḥ punaḥ', null, 2108020),
('ramayana-2-108-21', 21, 'Ayodhya Kanda, Sarga 108, Verse 21', 'खरस्त्वय्यपि चायुक्तं पुरा तात प्रवर्तते।
सहास्माभिरितो गच्छ यदि बुद्धिः प्रवर्तते॥', 'kharas tvayy api cāyuktaṃ purā tāta pravartate
sahāsmābhir ito gaccha yadi buddhiḥ pravartate', null, 2108021),
('ramayana-2-108-22', 22, 'Ayodhya Kanda, Sarga 108, Verse 22', 'सकलत्रस्य संदेहो नित्यं यत्तस्य राघव।
समर्थस्यापि हि सतो वासो दुःख इहाद्य ते॥', 'sakalatrasya saṃdeho nityaṃ yat tasya rāghava
samarthasyāpi hi sato vāso duḥkha ihādya te', null, 2108022),
('ramayana-2-108-23', 23, 'Ayodhya Kanda, Sarga 108, Verse 23', 'इत्युक्तवन्तं रामस्तं राजपुत्रस्तपस्विनम्।
न शशाकोत्तरैर्वाक्यैरवरोद्धुं समुत्सुकम्॥', 'ity uktavantaṃ rāmas taṃ rājaputras tapasvinam
na śaśākottarair vākyair avaroddhuṃ samutsukam', null, 2108023),
('ramayana-2-108-24', 24, 'Ayodhya Kanda, Sarga 108, Verse 24', 'अभिनन्द्य समापृच्छ्य समाधाय च राघवम्।
स जगामाश्रमं त्यक्त्वा कुलैः कुलपतिः सह॥', 'abhinandya samāpṛcchya samādhāya ca rāghavam
sa jagāmāśramaṃ tyaktvā kulaiḥ kulapatiḥ saha', null, 2108024),
('ramayana-2-108-25', 25, 'Ayodhya Kanda, Sarga 108, Verse 25', 'रामः संसाध्य त्वृषिगणमनुगमनाद्देशात्तस्माच्चित्कुलपतिमभिवाद्यर्षिम्।
सम्यक्प्रीतैस्तैरनुमत उपदिष्टार्थः पुण्यं वासाय स्वनिलयमुपसंपेदे॥', 'rāmaḥ saṃsādhya tv ṛṣigaṇam anugamanād deśāt tasmāccit kulapatim abhivādyarṣim
samyakprītais tair anumata upadiṣṭārthaḥ puṇyaṃ vāsāya svanilayam upasaṃpede', null, 2108025),
('ramayana-2-108-26', 26, 'Ayodhya Kanda, Sarga 108, Verse 26', 'आश्रमं त्वृषिविरहितं प्रभुः क्षणमपि न जहौ स राघवः।
राघवं हि सततमनुगतास्तापसाश्चर्षिचरितधृतगुणाः॥', 'āśramaṃ tv ṛṣivirahitaṃ prabhuḥ kṣaṇam api na jahau sa rāghavaḥ
rāghavaṃ hi satatam anugatās tāpasāś carṣicaritadhṛtaguṇāḥ', null, 2108026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 109 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-109-1', 1, 'Ayodhya Kanda, Sarga 109, Verse 1', 'राघवस्त्वपयातेषु तपस्विषु विचिन्तयन्।
न तत्रारोचयद्वासं कारणैर्बहुभिस्तदा॥', 'rāghavas tv apayāteṣu tapasviṣu vicintayan
na tatrārocayad vāsaṃ kāraṇair bahubhis tadā', null, 2109001),
('ramayana-2-109-2', 2, 'Ayodhya Kanda, Sarga 109, Verse 2', 'इह मे भरतो दृष्टो मातरश्च सनागराः।
सा च मे स्मृतिरन्वेति तान्नित्यमनुशोचतः॥', 'iha me bharato dṛṣṭo mātaraś ca sanāgarāḥ
sā ca me smṛtir anveti tān nityam anuśocataḥ', null, 2109002),
('ramayana-2-109-3', 3, 'Ayodhya Kanda, Sarga 109, Verse 3', 'स्कन्धावारनिवेशेन तेन तस्य महात्मनः।
हयहस्तिकरीषैश्च उपमर्दः कृतो भृशम्॥', 'skandhāvāraniveśena tena tasya mahātmanaḥ
hayahastikarīṣaiś ca upamardaḥ kṛto bhṛśam', null, 2109003),
('ramayana-2-109-4', 4, 'Ayodhya Kanda, Sarga 109, Verse 4', 'तस्मादन्यत्र गच्छाम इति संचिन्त्य राघवः।
प्रातिष्ठत स वैदेह्या लक्ष्मणेन च संगतः॥', 'tasmād anyatra gacchāma iti saṃcintya rāghavaḥ
prātiṣṭhata sa vaidehyā lakṣmaṇena ca saṃgataḥ', null, 2109004),
('ramayana-2-109-5', 5, 'Ayodhya Kanda, Sarga 109, Verse 5', 'सोऽत्रेराश्रममासाद्य तं ववन्दे महायशाः।
तं चापि भगवानत्रिः पुत्रवत्प्रत्यपद्यत॥', 'so ''trer āśramam āsādya taṃ vavande mahāyaśāḥ
taṃ cāpi bhagavān atriḥ putravat pratyapadyata', null, 2109005),
('ramayana-2-109-6', 6, 'Ayodhya Kanda, Sarga 109, Verse 6', 'स्वयमातिथ्यमादिश्य सर्वमस्य सुसत्कृतम्।
सौमित्रिं च महाभागां सीतां च समसान्त्वयत्॥', 'svayam ātithyam ādiśya sarvam asya susatkṛtam
saumitriṃ ca mahābhāgāṃ sītāṃ ca samasāntvayat', null, 2109006),
('ramayana-2-109-7', 7, 'Ayodhya Kanda, Sarga 109, Verse 7', 'पत्नीं च तमनुप्राप्तां वृद्धामामन्त्र्य सत्कृताम्।
सान्त्वयामास धर्मज्ञः सर्वभूतहिते रतः॥', 'patnīṃ ca tam anuprāptāṃ vṛddhām āmantrya satkṛtām
sāntvayām āsa dharmajñaḥ sarvabhūtahite rataḥ', null, 2109007),
('ramayana-2-109-8', 8, 'Ayodhya Kanda, Sarga 109, Verse 8', 'अनसूयां महाभागां तापसीं धर्मचारिणीम्।
प्रतिगृह्णीष्व वैदेहीमब्रवीदृषिसत्तमः॥', 'anasūyāṃ mahābhāgāṃ tāpasīṃ dharmacāriṇīm
pratigṛhṇīṣva vaidehīm abravīd ṛṣisattamaḥ', null, 2109008),
('ramayana-2-109-9', 9, 'Ayodhya Kanda, Sarga 109, Verse 9', 'रामाय चाचचक्षे तां तापसीं धर्मचारिणीम्।
दश वर्षाण्यनावृष्ट्या दग्धे लोके निरन्तरम्॥', 'rāmāya cācacakṣe tāṃ tāpasīṃ dharmacāriṇīm
daśa varṣāṇy anāvṛṣṭyā dagdhe loke nirantaram', null, 2109009),
('ramayana-2-109-10', 10, 'Ayodhya Kanda, Sarga 109, Verse 10', 'यया मूलफले सृष्टे जाह्नवी च प्रवर्तिता।
उग्रेण तपसा युक्ता नियमैश्चाप्यलंकृता॥', 'yayā mūlaphale sṛṣṭe jāhnavī ca pravartitā
ugreṇa tapasā yuktā niyamaiś cāpy alaṃkṛtā', null, 2109010),
('ramayana-2-109-11', 11, 'Ayodhya Kanda, Sarga 109, Verse 11', 'दशवर्षसहस्राणि यया तप्तं महत्तपः।
अनसूयाव्रतैस्तात प्रत्यूहाश्च निबर्हिताः॥', 'daśavarṣasahasrāṇi yayā taptaṃ mahat tapaḥ
anasūyāvratais tāta pratyūhāś ca nibarhitāḥ', null, 2109011),
('ramayana-2-109-12', 12, 'Ayodhya Kanda, Sarga 109, Verse 12', 'देवकार्यनिमित्तं च यया संत्वरमाणया।
दशरात्रं कृत्वा रात्रिः सेयं मातेव तेऽनघ॥', 'devakāryanimittaṃ ca yayā saṃtvaramāṇayā
daśarātraṃ kṛtvā rātriḥ seyaṃ māteva te ''nagha', null, 2109012),
('ramayana-2-109-13', 13, 'Ayodhya Kanda, Sarga 109, Verse 13', 'तामिमां सर्वभूतानां नमस्कार्यां यशस्विनीम्।
अभिगच्छतु वैदेही वृद्धामक्रोधनां सदा॥', 'tām imāṃ sarvabhūtānāṃ namaskāryāṃ yaśasvinīm
abhigacchatu vaidehī vṛddhām akrodhanāṃ sadā', null, 2109013),
('ramayana-2-109-14', 14, 'Ayodhya Kanda, Sarga 109, Verse 14', 'एवं ब्रुवाणं तमृषिं तथेत्युक्त्वा स राघवः।
सीतामुवाच धर्मज्ञामिदं वचनमुत्तमम्॥', 'evaṃ bruvāṇaṃ tam ṛṣiṃ tathety uktvā sa rāghavaḥ
sītām uvāca dharmajñām idaṃ vacanam uttamam', null, 2109014),
('ramayana-2-109-15', 15, 'Ayodhya Kanda, Sarga 109, Verse 15', 'राजपुत्रि श्रुतं त्वेतन्मुनेरस्य समीरितम्।
श्रेयोऽर्थमात्मनः शीघ्रमभिगच्छ तपस्विनीम्॥', 'rājaputri śrutaṃ tv etan muner asya samīritam
śreyo ''rtham ātmanaḥ śīghram abhigaccha tapasvinīm', null, 2109015),
('ramayana-2-109-16', 16, 'Ayodhya Kanda, Sarga 109, Verse 16', 'अनसूयेति या लोके कर्मभिः क्यातिमागता।
तां शीघ्रमभिगच्छ त्वमभिगम्यां तपस्विनीम्॥', 'anasūyeti yā loke karmabhiḥ kyātim āgatā
tāṃ śīghram abhigaccha tvam abhigamyāṃ tapasvinīm', null, 2109016),
('ramayana-2-109-17', 17, 'Ayodhya Kanda, Sarga 109, Verse 17', 'सीता त्वेतद्वचः श्रुत्वा राघवस्य हितैषिणी।
तामत्रिपत्नीं धर्मज्ञामभिचक्राम मैथिली॥', 'sītā tv etad vacaḥ śrutvā rāghavasya hitaiṣiṇī
tām atripatnīṃ dharmajñām abhicakrāma maithilī', null, 2109017),
('ramayana-2-109-18', 18, 'Ayodhya Kanda, Sarga 109, Verse 18', 'शिथिलां वलितां वृद्धां जरापाण्डुरमूर्धजाम्।
सततं वेपमानाङ्गीं प्रवाते कदली यथा॥', 'śithilāṃ valitāṃ vṛddhāṃ jarāpāṇḍuramūrdhajām
satataṃ vepamānāṅgīṃ pravāte kadalī yathā', null, 2109018),
('ramayana-2-109-19', 19, 'Ayodhya Kanda, Sarga 109, Verse 19', 'तां तु सीता महाभागामनसूयां पतिव्रताम्।
अभ्यवादयदव्यग्रा स्वं नाम समुदाहरत्॥', 'tāṃ tu sītā mahābhāgām anasūyāṃ pativratām
abhyavādayad avyagrā svaṃ nāma samudāharat', null, 2109019),
('ramayana-2-109-20', 20, 'Ayodhya Kanda, Sarga 109, Verse 20', 'अभिवाद्य च वैदेही तापसीं तामनिन्दिताम्।
बद्धाञ्जलिपुटा हृष्टा पर्यपृच्छदनामयम्॥', 'abhivādya ca vaidehī tāpasīṃ tām aninditām
baddhāñjalipuṭā hṛṣṭā paryapṛcchad anāmayam', null, 2109020),
('ramayana-2-109-21', 21, 'Ayodhya Kanda, Sarga 109, Verse 21', 'ततः सीतां महाभागां दृष्ट्वा तां धर्मचारिणीम्।
सान्त्वयन्त्यब्रवीद्धृष्टा दिष्ट्या धर्ममवेक्षसे॥', 'tataḥ sītāṃ mahābhāgāṃ dṛṣṭvā tāṃ dharmacāriṇīm
sāntvayanty abravīd dhṛṣṭā diṣṭyā dharmam avekṣase', null, 2109021),
('ramayana-2-109-22', 22, 'Ayodhya Kanda, Sarga 109, Verse 22', 'त्यक्त्वा ज्ञातिजनं सीते मानमृद्धिं च मानिनि।
अवरुद्धं वने रामं दिष्ट्या त्वमनुगच्छसि॥', 'tyaktvā jñātijanaṃ sīte mānam ṛddhiṃ ca mānini
avaruddhaṃ vane rāmaṃ diṣṭyā tvam anugacchasi', null, 2109022),
('ramayana-2-109-23', 23, 'Ayodhya Kanda, Sarga 109, Verse 23', 'नगरस्थो वनस्थो वा पापो वा यदि वाशुभः।
यासां स्त्रीणां प्रियो भर्ता तासां लोका महोदयाः॥', 'nagarastho vanastho vā pāpo vā yadi vāśubhaḥ
yāsāṃ strīṇāṃ priyo bhartā tāsāṃ lokā mahodayāḥ', null, 2109023),
('ramayana-2-109-24', 24, 'Ayodhya Kanda, Sarga 109, Verse 24', 'दुःशीलः कामवृत्तो वा धनैर्वा परिवर्जितः।
स्त्रीणामार्य स्वभावानां परमं दैवतं पतिः॥', 'duḥśīlaḥ kāmavṛtto vā dhanair vā parivarjitaḥ
strīṇām ārya svabhāvānāṃ paramaṃ daivataṃ patiḥ', null, 2109024),
('ramayana-2-109-25', 25, 'Ayodhya Kanda, Sarga 109, Verse 25', 'नातो विशिष्टं पश्यामि बान्धवं विमृशन्त्यहम्।
सर्वत्र योग्यं वैदेहि तपः कृतमिवाव्ययम्॥', 'nāto viśiṣṭaṃ paśyāmi bāndhavaṃ vimṛśanty aham
sarvatra yogyaṃ vaidehi tapaḥ kṛtam ivāvyayam', null, 2109025),
('ramayana-2-109-26', 26, 'Ayodhya Kanda, Sarga 109, Verse 26', 'न त्वेवमवगच्छन्ति गुण दोषमसत्स्त्रियः।
कामवक्तव्यहृदया भर्तृनाथाश्चरन्ति याः॥', 'na tv evam avagacchanti guṇa doṣam asat striyaḥ
kāmavaktavyahṛdayā bhartṛnāthāś caranti yāḥ', null, 2109026),
('ramayana-2-109-27', 27, 'Ayodhya Kanda, Sarga 109, Verse 27', 'प्राप्नुवन्त्ययशश्चैव धर्मभ्रंशं च मैथिलि।
अकार्य वशमापन्नाः स्त्रियो याः खलु तद्विधाः॥', 'prāpnuvanty ayaśaś caiva dharmabhraṃśaṃ ca maithili
akārya vaśam āpannāḥ striyo yāḥ khalu tad vidhāḥ', null, 2109027),
('ramayana-2-109-28', 28, 'Ayodhya Kanda, Sarga 109, Verse 28', 'त्वद्विधास्तु गुणैर्युक्ता दृष्टलोकपरावराः।
स्त्रियः स्वर्गे चरिष्यन्ति यथा पुण्यकृतस्तथा॥', 'tvadvidhās tu guṇair yuktā dṛṣṭalokaparāvarāḥ
striyaḥ svarge cariṣyanti yathā puṇyakṛtas tathā', null, 2109028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 110 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-110-1', 1, 'Ayodhya Kanda, Sarga 110, Verse 1', 'सा त्वेवमुक्ता वैदेही अनसूयानसूयया।
प्रतिपूज्य वचो मन्दं प्रवक्तुमुपचक्रमे॥', 'sā tv evam uktā vaidehī anasūyān asūyayā
pratipūjya vaco mandaṃ pravaktum upacakrame', null, 2110001),
('ramayana-2-110-2', 2, 'Ayodhya Kanda, Sarga 110, Verse 2', 'नैतदाश्चर्यमार्याया यन्मां त्वमनुभाषसे।
विदितं तु ममाप्येतद्यथा नार्याः पतिर्गुरुः॥', 'naitad āścaryam āryāyā yan māṃ tvam anubhāṣase
viditaṃ tu mamāpy etad yathā nāryāḥ patir guruḥ', null, 2110002),
('ramayana-2-110-3', 3, 'Ayodhya Kanda, Sarga 110, Verse 3', 'यद्यप्येष भवेद्भर्ता ममार्ये वृत्तवर्जितः।
अद्वैधमुपवर्तव्यस्तथाप्येष मया भवेत्॥', 'yady apy eṣa bhaved bhartā mamārye vṛttavarjitaḥ
advaidham upavartavyas tathāpy eṣa mayā bhavet', null, 2110003),
('ramayana-2-110-4', 4, 'Ayodhya Kanda, Sarga 110, Verse 4', 'किं पुनर्यो गुणश्लाघ्यः सानुक्रोशो जितेन्द्रियः।
स्थिरानुरागो धर्मात्मा मातृवर्ती पितृ प्रियः॥', 'kiṃ punar yo guṇaślāghyaḥ sānukrośo jitendriyaḥ
sthirānurāgo dharmātmā mātṛvartī pitṛ priyaḥ', null, 2110004),
('ramayana-2-110-5', 5, 'Ayodhya Kanda, Sarga 110, Verse 5', 'यां वृत्तिं वर्तते रामः कौसल्यायां महाबलः।
तामेव नृपनारीणामन्यासामपि वर्तते॥', 'yāṃ vṛttiṃ vartate rāmaḥ kausalyāyāṃ mahābalaḥ
tām eva nṛpanārīṇām anyāsām api vartate', null, 2110005),
('ramayana-2-110-6', 6, 'Ayodhya Kanda, Sarga 110, Verse 6', 'सकृद्दृष्टास्वपि स्त्रीषु नृपेण नृपवत्सलः।
मातृवद्वर्तते वीरो मानमुत्सृज्य धर्मवित्॥', 'sakṛd dṛṣṭāsv api strīṣu nṛpeṇa nṛpavatsalaḥ
mātṛvad vartate vīro mānam utsṛjya dharmavit', null, 2110006),
('ramayana-2-110-7', 7, 'Ayodhya Kanda, Sarga 110, Verse 7', 'आगच्छन्त्याश्च विजनं वनमेवं भयावहम्।
समाहितं हि मे श्वश्र्वा हृदये यत्स्थितं मम॥', 'āgacchantyāś ca vijanaṃ vanam evaṃ bhayāvaham
samāhitaṃ hi me śvaśrvā hṛdaye yat sthitaṃ mama', null, 2110007),
('ramayana-2-110-8', 8, 'Ayodhya Kanda, Sarga 110, Verse 8', 'प्राणिप्रदानकाले च यत्पुरा त्वग्निसंनिधौ।
अनुशिष्टा जनन्यास्मि वाक्यं तदपि मे धृतम्॥', 'prāṇipradānakāle ca yat purā tv agnisaṃnidhau
anuśiṣṭā jananyāsmi vākyaṃ tad api me dhṛtam', null, 2110008),
('ramayana-2-110-9', 9, 'Ayodhya Kanda, Sarga 110, Verse 9', 'नवीकृतं तु तत्सर्वं वाक्यैस्ते धर्मचारिणि।
पतिशुश्रूषणान्नार्यास्तपो नान्यद्विधीयते॥', 'navīkṛtaṃ tu tat sarvaṃ vākyais te dharmacāriṇi
patiśuśrūṣaṇān nāryās tapo nānyad vidhīyate', null, 2110009),
('ramayana-2-110-10', 10, 'Ayodhya Kanda, Sarga 110, Verse 10', 'सावित्री पतिशुश्रूषां कृत्वा स्वर्गे महीयते।
तथा वृत्तिश्च याता त्वं पतिशुश्रूषया दिवम्॥', 'sāvitrī patiśuśrūṣāṃ kṛtvā svarge mahīyate
tathā vṛttiś ca yātā tvaṃ patiśuśrūṣayā divam', null, 2110010),
('ramayana-2-110-11', 11, 'Ayodhya Kanda, Sarga 110, Verse 11', 'वरिष्ठा सर्वनारीणामेषा च दिवि देवता।
रोहिणी च विना चन्द्रं मुहूर्तमपि दृश्यते॥', 'variṣṭhā sarvanārīṇām eṣā ca divi devatā
rohiṇī ca vinā candraṃ muhūrtam api dṛśyate', null, 2110011),
('ramayana-2-110-12', 12, 'Ayodhya Kanda, Sarga 110, Verse 12', 'एवंविधाश्च प्रवराः स्त्रियो भर्तृदृढव्रताः।
देवलोके महीयन्ते पुण्येन स्वेन कर्मणा॥', 'evaṃvidhāś ca pravarāḥ striyo bhartṛdṛḍhavratāḥ
devaloke mahīyante puṇyena svena karmaṇā', null, 2110012),
('ramayana-2-110-13', 13, 'Ayodhya Kanda, Sarga 110, Verse 13', 'ततोऽनसूया संहृष्टा श्रुत्वोक्तं सीतया वचः।
शिरस्याघ्राय चोवाच मैथिलीं हर्षयन्त्युत॥', 'tato ''nasūyā saṃhṛṣṭā śrutvoktaṃ sītayā vacaḥ
śirasy āghrāya covāca maithilīṃ harṣayanty uta', null, 2110013),
('ramayana-2-110-14', 14, 'Ayodhya Kanda, Sarga 110, Verse 14', 'नियमैर्विविधैराप्तं तपो हि महदस्ति मे।
तत्संश्रित्य बलं सीते छन्दये त्वां शुचिव्रते॥', 'niyamair vividhair āptaṃ tapo hi mahad asti me
tat saṃśritya balaṃ sīte chandaye tvāṃ śucivrate', null, 2110014),
('ramayana-2-110-15', 15, 'Ayodhya Kanda, Sarga 110, Verse 15', 'उपपन्नं च युक्तं च वचनं तव मैथिलि।
प्रीता चास्म्युचितं किं ते करवाणि ब्रवीहि मे।
कृतमित्यब्रवीत्सीता तपोबलसमन्विताम्॥', 'upapannaṃ ca yuktaṃ ca vacanaṃ tava maithili
prītā cāsmy ucitaṃ kiṃ te karavāṇi bravīhi me
kṛtam ity abravīt sītā tapobalasamanvitām', null, 2110015),
('ramayana-2-110-16', 16, 'Ayodhya Kanda, Sarga 110, Verse 16', 'सा त्वेवमुक्ता धर्मज्ञा तया प्रीततराभवत्।
सफलं च प्रहर्षं ते हन्त सीते करोम्यहम्॥', 'sā tv evam uktā dharmajñā tayā prītatarābhavat
saphalaṃ ca praharṣaṃ te hanta sīte karomy aham', null, 2110016),
('ramayana-2-110-17', 17, 'Ayodhya Kanda, Sarga 110, Verse 17', 'इदं दिव्यं वरं माल्यं वस्त्रमाभरणानि च।
अङ्गरागं च वैदेहि महार्हमनुलेपनम्॥', 'idaṃ divyaṃ varaṃ mālyaṃ vastram ābharaṇāni ca
aṅgarāgaṃ ca vaidehi mahārham anulepanam', null, 2110017),
('ramayana-2-110-18', 18, 'Ayodhya Kanda, Sarga 110, Verse 18', 'मया दत्तमिदं सीते तव गात्राणि शोभयेत्।
अनुरूपमसंक्लिष्टं नित्यमेव भविष्यति॥', 'mayā dattam idaṃ sīte tava gātrāṇi śobhayet
anurūpam asaṃkliṣṭaṃ nityam eva bhaviṣyati', null, 2110018),
('ramayana-2-110-19', 19, 'Ayodhya Kanda, Sarga 110, Verse 19', 'अङ्गरागेण दिव्येन लिप्ताङ्गी जनकात्मजे।
शोभयिष्यामि भर्तारं यथा श्रीर्विष्णुमव्ययम्॥', 'aṅgarāgeṇa divyena liptāṅgī janakātmaje
śobhayiṣyāmi bhartāraṃ yathā śrīr viṣṇum avyayam', null, 2110019),
('ramayana-2-110-20', 20, 'Ayodhya Kanda, Sarga 110, Verse 20', 'सा वस्त्रमङ्गरागं च भूषणानि स्रजस्तथा।
मैथिली प्रतिजग्राह प्रीतिदानमनुत्तमम्॥', 'sā vastram aṅgarāgaṃ ca bhūṣaṇāni srajas tathā
maithilī pratijagrāha prītidānam anuttamam', null, 2110020),
('ramayana-2-110-21', 21, 'Ayodhya Kanda, Sarga 110, Verse 21', 'प्रतिगृह्य च तत्सीता प्रीतिदानं यशस्विनी।
श्लिष्टाञ्जलिपुटा धीरा समुपास्त तपोधनाम्॥', 'pratigṛhya ca tat sītā prītidānaṃ yaśasvinī
śliṣṭāñjalipuṭā dhīrā samupāsta tapodhanām', null, 2110021),
('ramayana-2-110-22', 22, 'Ayodhya Kanda, Sarga 110, Verse 22', 'तथा सीतामुपासीनामनसूया दृढव्रता।
वचनं प्रष्टुमारेभे कथां कां चिदनुप्रियाम्॥', 'tathā sītām upāsīnām anasūyā dṛḍhavratā
vacanaṃ praṣṭum ārebhe kathāṃ kāṃ cid anupriyām', null, 2110022),
('ramayana-2-110-23', 23, 'Ayodhya Kanda, Sarga 110, Verse 23', 'स्वयंवरे किल प्राप्ता त्वमनेन यशस्विना।
राघवेणेति मे सीते कथा श्रुतिमुपागता॥', 'svayaṃvare kila prāptā tvam anena yaśasvinā
rāghaveṇeti me sīte kathā śrutim upāgatā', null, 2110023),
('ramayana-2-110-24', 24, 'Ayodhya Kanda, Sarga 110, Verse 24', 'तां कथां श्रोतुमिच्छामि विस्तरेण च मैथिलि।
यथानुभूतं कार्त्स्न्येन तन्मे त्वं वक्तुमर्हसि॥', 'tāṃ kathāṃ śrotum icchāmi vistareṇa ca maithili
yathānubhūtaṃ kārtsnyena tan me tvaṃ vaktum arhasi', null, 2110024),
('ramayana-2-110-25', 25, 'Ayodhya Kanda, Sarga 110, Verse 25', 'एवमुक्ता तु सा सीता तां ततो धर्मचारिणीम्।
श्रूयतामिति चोक्त्वा वै कथयामास तां कथाम्॥', 'evam uktā tu sā sītā tāṃ tato dharmacāriṇīm
śrūyatām iti coktvā vai kathayām āsa tāṃ kathām', null, 2110025),
('ramayana-2-110-26', 26, 'Ayodhya Kanda, Sarga 110, Verse 26', 'मिथिलाधिपतिर्वीरो जनको नाम धर्मवित्।
क्षत्रधर्मण्यभिरतो न्यायतः शास्ति मेदिनीम्॥', 'mithilādhipatir vīro janako nāma dharmavit
kṣatradharmaṇy abhirato nyāyataḥ śāsti medinīm', null, 2110026),
('ramayana-2-110-27', 27, 'Ayodhya Kanda, Sarga 110, Verse 27', 'तस्य लाङ्गलहस्तस्य कर्षतः क्षेत्रमण्डलम्।
अहं किलोत्थिता भित्त्वा जगतीं नृपतेः सुता॥', 'tasya lāṅgalahastasya karṣataḥ kṣetramaṇḍalam
ahaṃ kilotthitā bhittvā jagatīṃ nṛpateḥ sutā', null, 2110027),
('ramayana-2-110-28', 28, 'Ayodhya Kanda, Sarga 110, Verse 28', 'स मां दृष्ट्वा नरपतिर्मुष्टिविक्षेपतत्परः।
पांशु गुण्ठित सर्वाङ्गीं विस्मितो जनकोऽभवत्॥', 'sa māṃ dṛṣṭvā narapatir muṣṭivikṣepatatparaḥ
pāṃśu guṇṭhita sarvāṅgīṃ vismito janako ''bhavat', null, 2110028),
('ramayana-2-110-29', 29, 'Ayodhya Kanda, Sarga 110, Verse 29', 'अनपत्येन च स्नेहादङ्कमारोप्य च स्वयम्।
ममेयं तनयेत्युक्त्वा स्नेहो मयि निपातितः॥', 'anapatyena ca snehād aṅkam āropya ca svayam
mameyaṃ tanayety uktvā sneho mayi nipātitaḥ', null, 2110029),
('ramayana-2-110-30', 30, 'Ayodhya Kanda, Sarga 110, Verse 30', 'अन्तरिक्षे च वागुक्ताप्रतिमा मानुषी किल।
एवमेतन्नरपते धर्मेण तनया तव॥', 'antarikṣe ca vāg uktāpratimā mānuṣī kila
evam etan narapate dharmeṇa tanayā tava', null, 2110030),
('ramayana-2-110-31', 31, 'Ayodhya Kanda, Sarga 110, Verse 31', 'ततः प्रहृष्टो धर्मात्मा पिता मे मिथिलाधिपः।
अवाप्तो विपुलामृद्धिं मामवाप्य नराधिपः॥', 'tataḥ prahṛṣṭo dharmātmā pitā me mithilādhipaḥ
avāpto vipulām ṛddhiṃ mām avāpya narādhipaḥ', null, 2110031),
('ramayana-2-110-32', 32, 'Ayodhya Kanda, Sarga 110, Verse 32', 'दत्त्वा चास्मीष्टवद्देव्यै ज्येष्ठायै पुण्यकर्मणा।
तया संभाविता चास्मि स्निग्धया मातृसौहृदात्॥', 'dattvā cāsmīṣṭavad devyai jyeṣṭhāyai puṇyakarmaṇā
tayā saṃbhāvitā cāsmi snigdhayā mātṛsauhṛdāt', null, 2110032),
('ramayana-2-110-33', 33, 'Ayodhya Kanda, Sarga 110, Verse 33', 'पतिसंयोगसुलभं वयो दृष्ट्वा तु मे पिता।
चिन्तामभ्यगमद्दीनो वित्तनाशादिवाधनः॥', 'patisaṃyogasulabhaṃ vayo dṛṣṭvā tu me pitā
cintām abhyagamad dīno vittanāśād ivādhanaḥ', null, 2110033),
('ramayana-2-110-34', 34, 'Ayodhya Kanda, Sarga 110, Verse 34', 'सदृशाच्चापकृष्टाच्च लोके कन्यापिता जनात्।
प्रधर्षणामवाप्नोति शक्रेणापि समो भुवि॥', 'sadṛśāc cāpakṛṣṭāc ca loke kanyāpitā janāt
pradharṣaṇām avāpnoti śakreṇāpi samo bhuvi', null, 2110034),
('ramayana-2-110-35', 35, 'Ayodhya Kanda, Sarga 110, Verse 35', 'तां धर्षणामदूरस्थां संदृश्यात्मनि पार्थिवः।
चिन्न्तार्णवगतः पारं नाससादाप्लवो यथ॥', 'tāṃ dharṣaṇām adūrasthāṃ saṃdṛśyātmani pārthivaḥ
cinntārṇavagataḥ pāraṃ nāsasādāplavo yatha', null, 2110035),
('ramayana-2-110-36', 36, 'Ayodhya Kanda, Sarga 110, Verse 36', 'अयोनिजां हि मां ज्ञात्वा नाध्यगच्छत्स चिन्तयन्।
सदृशं चानुरूपं च महीपालः पतिं मम॥', 'ayonijāṃ hi māṃ jñātvā nādhyagacchat sa cintayan
sadṛśaṃ cānurūpaṃ ca mahīpālaḥ patiṃ mama', null, 2110036),
('ramayana-2-110-37', 37, 'Ayodhya Kanda, Sarga 110, Verse 37', 'तस्य बुद्धिरियं जाता चिन्तयानस्य संततम्।
स्वयं वरं तनूजायाः करिष्यामीति धीमतः॥', 'tasya buddhir iyaṃ jātā cintayānasya saṃtatam
svayaṃ varaṃ tanūjāyāḥ kariṣyāmīti dhīmataḥ', null, 2110037),
('ramayana-2-110-38', 38, 'Ayodhya Kanda, Sarga 110, Verse 38', 'महायज्ञे तदा तस्य वरुणेन महात्मना।
दत्तं धनुर्वरं प्रीत्या तूणी चाक्षय्य सायकौ॥', 'mahāyajñe tadā tasya varuṇena mahātmanā
dattaṃ dhanurvaraṃ prītyā tūṇī cākṣayya sāyakau', null, 2110038),
('ramayana-2-110-39', 39, 'Ayodhya Kanda, Sarga 110, Verse 39', 'असंचाल्यं मनुष्यैश्च यत्नेनापि च गौरवात्।
तन्न शक्ता नमयितुं स्वप्नेष्वपि नराधिपाः॥', 'asaṃcālyaṃ manuṣyaiś ca yatnenāpi ca gauravāt
tan na śaktā namayituṃ svapneṣv api narādhipāḥ', null, 2110039),
('ramayana-2-110-40', 40, 'Ayodhya Kanda, Sarga 110, Verse 40', 'तद्धनुः प्राप्य मे पित्रा व्याहृतं सत्यवादिना।
समवाये नरेन्द्राणां पूर्वमामन्त्र्य पार्थिवान्॥', 'tad dhanuḥ prāpya me pitrā vyāhṛtaṃ satyavādinā
samavāye narendrāṇāṃ pūrvam āmantrya pārthivān', null, 2110040),
('ramayana-2-110-41', 41, 'Ayodhya Kanda, Sarga 110, Verse 41', 'इदं च धनुरुद्यम्य सज्यं यः कुरुते नरः।
तस्य मे दुहिता भार्या भविष्यति न संशयः॥', 'idaṃ ca dhanur udyamya sajyaṃ yaḥ kurute naraḥ
tasya me duhitā bhāryā bhaviṣyati na saṃśayaḥ', null, 2110041),
('ramayana-2-110-42', 42, 'Ayodhya Kanda, Sarga 110, Verse 42', 'तच्च दृष्ट्वा धनुःश्रेष्ठं गौरवाद्गिरिसंनिभम्।
अभिवाद्य नृपा जग्मुरशक्तास्तस्य तोलने॥', 'tac ca dṛṣṭvā dhanuḥśreṣṭhaṃ gauravād girisaṃnibham
abhivādya nṛpā jagmur aśaktās tasya tolane', null, 2110042),
('ramayana-2-110-43', 43, 'Ayodhya Kanda, Sarga 110, Verse 43', 'सुदीर्घस्य तु कालस्य राघवोऽयं महाद्युतिः।
विश्वामित्रेण सहितो यज्ञं द्रष्टुं समागतः॥', 'sudīrghasya tu kālasya rāghavo ''yaṃ mahādyutiḥ
viśvāmitreṇa sahito yajñaṃ draṣṭuṃ samāgataḥ', null, 2110043),
('ramayana-2-110-44', 44, 'Ayodhya Kanda, Sarga 110, Verse 44', 'लक्ष्मणेन सह भ्रात्रा रामः सत्यपराक्रमः।
विश्वामित्रस्तु धर्मात्मा मम पित्रा सुपूजितः॥', 'lakṣmaṇena saha bhrātrā rāmaḥ satyaparākramaḥ
viśvāmitras tu dharmātmā mama pitrā supūjitaḥ', null, 2110044),
('ramayana-2-110-45', 45, 'Ayodhya Kanda, Sarga 110, Verse 45', 'प्रोवाच पितरं तत्र राघवो रामलक्ष्मणौ।
सुतौ दशरथस्येमौ धनुर्दर्शनकाङ्क्षिणौ।
इत्युक्तस्तेन विप्रेण तद्धनुः समुपानयत्॥', 'provāca pitaraṃ tatra rāghavo rāmalakṣmaṇau
sutau daśarathasyemau dhanurdarśanakāṅkṣiṇau
ity uktas tena vipreṇa tad dhanuḥ samupānayat', null, 2110045),
('ramayana-2-110-46', 46, 'Ayodhya Kanda, Sarga 110, Verse 46', 'निमेषान्तरमात्रेण तदानम्य स वीर्यवान्।
ज्यां समारोप्य झटिति पूरयामास वीर्यवान्॥', 'nimeṣāntaramātreṇa tad ānamya sa vīryavān
jyāṃ samāropya jhaṭiti pūrayām āsa vīryavān', null, 2110046),
('ramayana-2-110-47', 47, 'Ayodhya Kanda, Sarga 110, Verse 47', 'तेन पूरयता वेगान्मध्ये भग्नं द्विधा धनुः।
तस्य शब्दोऽभवद्भीमः पतितस्याशनेरिव॥', 'tena pūrayatā vegān madhye bhagnaṃ dvidhā dhanuḥ
tasya śabdo ''bhavad bhīmaḥ patitasyāśaner iva', null, 2110047),
('ramayana-2-110-48', 48, 'Ayodhya Kanda, Sarga 110, Verse 48', 'ततोऽहं तत्र रामाय पित्रा सत्याभिसंधिना।
उद्यता दातुमुद्यम्य जलभाजनमुत्तमम्॥', 'tato ''haṃ tatra rāmāya pitrā satyābhisaṃdhinā
udyatā dātum udyamya jalabhājanam uttamam', null, 2110048),
('ramayana-2-110-49', 49, 'Ayodhya Kanda, Sarga 110, Verse 49', 'दीयमानां न तु तदा प्रतिजग्राह राघवः।
अविज्ञाय पितुश्छन्दमयोध्याधिपतेः प्रभोः॥', 'dīyamānāṃ na tu tadā pratijagrāha rāghavaḥ
avijñāya pituś chandam ayodhyādhipateḥ prabhoḥ', null, 2110049),
('ramayana-2-110-50', 50, 'Ayodhya Kanda, Sarga 110, Verse 50', 'ततः श्वशुरमामन्त्र्य वृद्धं दशरथं नृपम्।
मम पित्रा अहं दत्ता रामाय विदितात्मने॥', 'tataḥ śvaśuram āmantrya vṛddhaṃ daśarathaṃ nṛpam
mama pitrā ahaṃ dattā rāmāya viditātmane', null, 2110050),
('ramayana-2-110-51', 51, 'Ayodhya Kanda, Sarga 110, Verse 51', 'मम चैवानुजा साध्वी ऊर्मिला प्रियदर्शना।
भार्यार्थे लक्ष्मणस्यापि दत्ता पित्रा मम स्वयम्॥', 'mama caivānujā sādhvī ūrmilā priyadarśanā
bhāryārthe lakṣmaṇasyāpi dattā pitrā mama svayam', null, 2110051),
('ramayana-2-110-52', 52, 'Ayodhya Kanda, Sarga 110, Verse 52', 'एवं दत्तास्मि रामाय तदा तस्मिन्स्वयं वरे।
अनुरक्ता च धर्मेण पतिं वीर्यवतां वरम्॥', 'evaṃ dattāsmi rāmāya tadā tasmin svayaṃ vare
anuraktā ca dharmeṇa patiṃ vīryavatāṃ varam', null, 2110052)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 111 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 2 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-2-111-1', 1, 'Ayodhya Kanda, Sarga 111, Verse 1', 'अनसूया तु धर्मज्ञा श्रुत्वा तां महतीं कथाम्।
पर्यष्वजत बाहुभ्यां शिरस्याघ्राय मैथिलीम्॥', 'anasūyā tu dharmajñā śrutvā tāṃ mahatīṃ kathām
paryaṣvajata bāhubhyāṃ śirasy āghrāya maithilīm', null, 2111001),
('ramayana-2-111-2', 2, 'Ayodhya Kanda, Sarga 111, Verse 2', 'व्यक्ताक्षरपदं चित्रं भाषितं मधुरं त्वया।
यथा स्वयंवरं वृत्तं तत्सर्वं हि श्रुतं मया॥', 'vyaktākṣarapadaṃ citraṃ bhāṣitaṃ madhuraṃ tvayā
yathā svayaṃvaraṃ vṛttaṃ tat sarvaṃ hi śrutaṃ mayā', null, 2111002),
('ramayana-2-111-3', 3, 'Ayodhya Kanda, Sarga 111, Verse 3', 'रमेऽहं कथया ते तु दृढं मधुरभाषिणि।
रविरस्तं गतः श्रीमानुपोह्य रजनीं शिवाम्॥', 'rame ''haṃ kathayā te tu dṛḍhaṃ madhurabhāṣiṇi
ravir astaṃ gataḥ śrīmān upohya rajanīṃ śivām', null, 2111003),
('ramayana-2-111-4', 4, 'Ayodhya Kanda, Sarga 111, Verse 4', 'दिवसं प्रति कीर्णानामाहारार्थं पतत्रिणाम्।
संध्याकाले निलीनानां निद्रार्थं श्रूयते ध्वनिः॥', 'divasaṃ prati kīrṇānām āhārārthaṃ patatriṇām
saṃdhyākāle nilīnānāṃ nidrārthaṃ śrūyate dhvaniḥ', null, 2111004),
('ramayana-2-111-5', 5, 'Ayodhya Kanda, Sarga 111, Verse 5', 'एते चाप्यभिषेकार्द्रा मुनयः फलशोधनाः।
सहिता उपवर्तन्ते सलिलाप्लुतवल्कलाः॥', 'ete cāpy abhiṣekārdrā munayaḥ phalaśodhanāḥ
sahitā upavartante salilāplutavalkalāḥ', null, 2111005),
('ramayana-2-111-6', 6, 'Ayodhya Kanda, Sarga 111, Verse 6', 'ऋषीणामग्निहोत्रेषु हुतेषु विधिपुर्वकम्।
कपोताङ्गारुणो धूमो दृश्यते पवनोद्धतः॥', 'ṛṣīṇām agnihotreṣu huteṣu vidhipurvakam
kapotāṅgāruṇo dhūmo dṛśyate pavanoddhataḥ', null, 2111006),
('ramayana-2-111-7', 7, 'Ayodhya Kanda, Sarga 111, Verse 7', 'अल्पपर्णा हि तरवो घनीभूताः समन्ततः।
विप्रकृष्टेऽपि ये देशे न प्रकाशन्ति वै दिशः॥', 'alpaparṇā hi taravo ghanībhūtāḥ samantataḥ
viprakṛṣṭe ''pi ye deśe na prakāśanti vai diśaḥ', null, 2111007),
('ramayana-2-111-8', 8, 'Ayodhya Kanda, Sarga 111, Verse 8', 'रजनी रससत्त्वानि प्रचरन्ति समन्ततः।
तपोवनमृगा ह्येते वेदितीर्थेषु शेरते॥', 'rajanī rasasattvāni pracaranti samantataḥ
tapovanamṛgā hy ete veditīrtheṣu śerate', null, 2111008),
('ramayana-2-111-9', 9, 'Ayodhya Kanda, Sarga 111, Verse 9', 'संप्रवृत्ता निशा सीते नक्षत्रसमलंकृता।
ज्योत्स्ना प्रावरणश्चन्द्रो दृश्यतेऽभ्युदितोऽम्बरे॥', 'saṃpravṛttā niśā sīte nakṣatrasamalaṃkṛtā
jyotsnā prāvaraṇaś candro dṛśyate ''bhyudito ''mbare', null, 2111009),
('ramayana-2-111-10', 10, 'Ayodhya Kanda, Sarga 111, Verse 10', 'गम्यतामनुजानामि रामस्यानुचरी भव।
कथयन्त्या हि मधुरं त्वयाहं परितोषिता॥', 'gamyatām anujānāmi rāmasyānucarī bhava
kathayantyā hi madhuraṃ tvayāhaṃ paritoṣitā', null, 2111010),
('ramayana-2-111-11', 11, 'Ayodhya Kanda, Sarga 111, Verse 11', 'अलंकुरु च तावत्त्वं प्रत्यक्षं मम मैथिलि।
प्रीतिं जनय मे वत्स दिव्यालंकारशोभिनी॥', 'alaṃkuru ca tāvat tvaṃ pratyakṣaṃ mama maithili
prītiṃ janaya me vatsa divyālaṃkāraśobhinī', null, 2111011),
('ramayana-2-111-12', 12, 'Ayodhya Kanda, Sarga 111, Verse 12', 'सा तदा समलंकृत्य सीता सुरसुतोपमा।
प्रणम्य शिरसा तस्यै रामं त्वभिमुखी ययौ॥', 'sā tadā samalaṃkṛtya sītā surasutopamā
praṇamya śirasā tasyai rāmaṃ tv abhimukhī yayau', null, 2111012),
('ramayana-2-111-13', 13, 'Ayodhya Kanda, Sarga 111, Verse 13', 'तथा तु भूषितां सीतां ददर्श वदतां वरः।
राघवः प्रीतिदानेन तपस्विन्या जहर्ष च॥', 'tathā tu bhūṣitāṃ sītāṃ dadarśa vadatāṃ varaḥ
rāghavaḥ prītidānena tapasvinyā jaharṣa ca', null, 2111013),
('ramayana-2-111-14', 14, 'Ayodhya Kanda, Sarga 111, Verse 14', 'न्यवेदयत्ततः सर्वं सीता रामाय मैथिली।
प्रीतिदानं तपस्विन्या वसनाभरणस्रजाम्॥', 'nyavedayat tataḥ sarvaṃ sītā rāmāya maithilī
prītidānaṃ tapasvinyā vasanābharaṇasrajām', null, 2111014),
('ramayana-2-111-15', 15, 'Ayodhya Kanda, Sarga 111, Verse 15', 'प्रहृष्टस्त्वभवद्रामो लक्ष्मणश्च महारथः।
मैथिल्याः सत्क्रियां दृष्ट्वा मानुषेषु सुदुर्लभाम्॥', 'prahṛṣṭas tv abhavad rāmo lakṣmaṇaś ca mahārathaḥ
maithilyāḥ satkriyāṃ dṛṣṭvā mānuṣeṣu sudurlabhām', null, 2111015),
('ramayana-2-111-16', 16, 'Ayodhya Kanda, Sarga 111, Verse 16', 'ततस्तां सर्वरीं प्रीतः पुण्यां शशिनिभाननः।
अर्चितस्तापसैः सिद्धैरुवास रघुनन्दनः॥', 'tatas tāṃ sarvarīṃ prītaḥ puṇyāṃ śaśinibhānanaḥ
arcitas tāpasaiḥ siddhair uvāsa raghunandanaḥ', null, 2111016),
('ramayana-2-111-17', 17, 'Ayodhya Kanda, Sarga 111, Verse 17', 'तस्यां रात्र्यां व्यतीतायामभिषिच्य हुताग्निकान्।
आपृच्छेतां नरव्याघ्रौ तापसान्वनगोचरान्॥', 'tasyāṃ rātryāṃ vyatītāyām abhiṣicya hutāgnikān
āpṛcchetāṃ naravyāghrau tāpasān vanagocarān', null, 2111017),
('ramayana-2-111-18', 18, 'Ayodhya Kanda, Sarga 111, Verse 18', 'तावूचुस्ते वनचरास्तापसा धर्मचारिणः।
वनस्य तस्य संचारं राक्षसैः समभिप्लुतम्॥', 'tāv ūcus te vanacarās tāpasā dharmacāriṇaḥ
vanasya tasya saṃcāraṃ rākṣasaiḥ samabhiplutam', null, 2111018),
('ramayana-2-111-19', 19, 'Ayodhya Kanda, Sarga 111, Verse 19', 'एष पन्था महर्षीणां फलान्याहरतां वने।
अनेन तु वनं दुर्गं गन्तुं राघव ते क्षमम्॥', 'eṣa panthā maharṣīṇāṃ phalāny āharatāṃ vane
anena tu vanaṃ durgaṃ gantuṃ rāghava te kṣamam', null, 2111019),
('ramayana-2-111-20', 20, 'Ayodhya Kanda, Sarga 111, Verse 20', 'इतीव तैः प्राञ्जलिभिस्तपस्विभिर्द्विजैः कृतस्वस्त्ययनः परंतपः।
वनं सभार्यः प्रविवेश राघवः सलक्ष्मणः सूर्य इवाभ्रमण्डलम्॥', 'itīva taiḥ prāñjalibhis tapasvibhir dvijaiḥ kṛtasvastyayanaḥ paraṃtapaḥ
vanaṃ sabhāryaḥ praviveśa rāghavaḥ salakṣmaṇaḥ sūrya ivābhramaṇḍalam', null, 2111020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into translations (verse_id, language, text, source_id, is_primary) values
('ramayana-2-1-1', 'en', 'After some time, King Dasharatha, joy of the Raghus, spoke to his son Bharata, son of Kaikeyi.', 'veda-app-ai-draft', true),
('ramayana-2-1-2', 'en', 'This son of the Kekaya king, your uncle Yudhajit, is staying here, my son; he has come to take you with him, hero.', 'veda-app-ai-draft', true),
('ramayana-2-1-3', 'en', 'Hearing this from Dasharatha, Bharata son of Kaikeyi prepared to go, together with Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-1-4', 'en', 'Taking leave of his father, of Rama who acted without strain, and of his mothers, the best of men went with Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-1-5', 'en', 'Yudhajit, delighted to have Bharata and Shatrughna, entered his own city, and his father was pleased.', 'veda-app-ai-draft', true),
('ramayana-2-1-6', 'en', 'Bharata lived there with his brother, honoured with hospitality and cherished by his uncle Ashvapati with a father''s love.', 'veda-app-ai-draft', true),
('ramayana-2-1-7', 'en', 'Though living there, satisfied in every wish, the two heroic brothers remembered their old father, King Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-2-1-8', 'en', 'The mighty king too remembered his two absent sons, Bharata and Shatrughna, like great Indra and Varuna.', 'veda-app-ai-draft', true),
('ramayana-2-1-9', 'en', 'All four bulls among men were dear to him, like four arms grown from his own body.', 'veda-app-ai-draft', true),
('ramayana-2-1-10', 'en', 'Of them, mighty Rama gave his father the most joy; like Brahma among beings, he was the most virtuous.', 'veda-app-ai-draft', true),
('ramayana-2-1-11', 'en', 'With Bharata gone, Rama and mighty Lakshmana honoured their god-like father.', 'veda-app-ai-draft', true),
('ramayana-2-1-12', 'en', 'Placing his father''s command first, righteous Rama carried out all the city''s affairs, pleasing and beneficial.', 'veda-app-ai-draft', true),
('ramayana-2-1-13', 'en', 'Taking great care, he did what was due to his mothers and attended to his elders'' needs at the proper times.', 'veda-app-ai-draft', true),
('ramayana-2-1-14', 'en', 'So Dasharatha was pleased, and so were the brahmins, the merchants and all who lived in the land, by Rama''s conduct and character.', 'veda-app-ai-draft', true),
('ramayana-2-1-15', 'en', 'He was always calm and spoke gently first; even when spoken to harshly he did not answer back.', 'veda-app-ai-draft', true),
('ramayana-2-1-16', 'en', 'He was pleased by even a single kindness done to him, and, being self-possessed, did not remember even a hundred wrongs.', 'veda-app-ai-draft', true),
('ramayana-2-1-17', 'en', 'Even between his weapons practice he always sat talking with good people, elders in character, wisdom and age.', 'veda-app-ai-draft', true),
('ramayana-2-1-18', 'en', 'He was of noble birth, good, never downcast, truthful and straightforward, trained by elders and by brahmins who saw dharma and purpose.', 'veda-app-ai-draft', true),
('ramayana-2-1-19', 'en', 'He knew the truth of dharma, wealth and pleasure; he had a sharp memory and quick insight, and was skilled and practised in worldly custom.', 'veda-app-ai-draft', true),
('ramayana-2-1-20', 'en', 'He knew the scriptures, was grateful, understood people, and was wise in when to restrain and when to favour, as was just.', 'veda-app-ai-draft', true),
('ramayana-2-1-21', 'en', 'He knew the means of raising revenue and understood spending; he excelled in all the branches of learning, even the mixed ones.', 'veda-app-ai-draft', true),
('ramayana-2-1-22', 'en', 'Balancing wealth and dharma, he enjoyed pleasure but was never lazy; he understood the arts of recreation and how to divide resources.', 'veda-app-ai-draft', true),
('ramayana-2-1-23', 'en', 'He was skilled in riding and training elephants and horses, the best of those who knew archery, honoured in the world as a master chariot-warrior.', 'veda-app-ai-draft', true),
('ramayana-2-1-24', 'en', 'He could lead an attack and strike, was skilled in leading armies, and could not be overcome in battle even by angry gods and demons.', 'veda-app-ai-draft', true),
('ramayana-2-1-25', 'en', 'He was free of envy, had conquered anger, was neither proud nor jealous, despised no living being, and was not ruled by time.', 'veda-app-ai-draft', true),
('ramayana-2-1-26', 'en', 'Thus endowed with the best qualities, the prince was loved by his people and honoured in the three worlds; like the earth in patience, like Brihaspati in wisdom, like Indra in valour.', 'veda-app-ai-draft', true),
('ramayana-2-1-27', 'en', 'With these qualities, loved by all the people and bringing his father joy, Rama shone like the blazing sun with its rays.', 'veda-app-ai-draft', true),
('ramayana-2-1-28', 'en', 'The earth itself longed for him as its lord, so perfect in conduct, of irresistible valour, like a guardian of the world.', 'veda-app-ai-draft', true),
('ramayana-2-1-29', 'en', 'Seeing his son endowed with so many matchless qualities, King Dasharatha, scorcher of foes, began to think.', 'veda-app-ai-draft', true),
('ramayana-2-1-30', 'en', 'This was the dearest wish turning in his heart: When will I see my dear son crowned?', 'veda-app-ai-draft', true),
('ramayana-2-1-31', 'en', 'He wishes the world to prosper and has compassion for all beings; he is dearer to the people than I am, like a rain cloud.', 'veda-app-ai-draft', true),
('ramayana-2-1-32', 'en', 'He is equal to Yama and Indra in valour, to Brihaspati in judgment, to a mountain in steadiness, and more virtuous than I.', 'veda-app-ai-draft', true),
('ramayana-2-1-33', 'en', 'May I, at this age, see my son ruling this whole earth, and so attain heaven.', 'veda-app-ai-draft', true),
('ramayana-2-1-34', 'en', 'Seeing him endowed with every rising virtue, the great king decided with his ministers to make him crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-1-35', 'en', 'The lord of the earth summoned the leading men of the land, from many cities and from the countryside.', 'veda-app-ai-draft', true),
('ramayana-2-1-36', 'en', 'Seated on the various seats the king had given them, the kings sat facing him, composed.', 'veda-app-ai-draft', true),
('ramayana-2-1-37', 'en', 'Surrounded by honoured, courteous kings and people of town and country seated around him, the king shone like thousand-eyed Indra among the gods.', 'veda-app-ai-draft', true),
('ramayana-2-2-1', 'en', 'Then, addressing the whole assembly, the lord of the earth spoke these matchless words, beneficial and uplifting.', 'veda-app-ai-draft', true),
('ramayana-2-2-2', 'en', 'In a great deep, echoing voice like the sound of a drum, the king spoke, thundering like a cloud.', 'veda-app-ai-draft', true),
('ramayana-2-2-3', 'en', 'I wish to bring good fortune to this whole world, protected by my ancestors, the Ikshvaku kings, and worthy of happiness.', 'veda-app-ai-draft', true),
('ramayana-2-2-4', 'en', 'I too have followed the path of my forebears, always tirelessly protecting the people as best I could.', 'veda-app-ai-draft', true),
('ramayana-2-2-5', 'en', 'Working for the good of the whole world, I have grown old in this body under the shade of the white royal umbrella.', 'veda-app-ai-draft', true),
('ramayana-2-2-6', 'en', 'Having lived a long life of many thousands of years, I wish to rest this worn-out body.', 'veda-app-ai-draft', true),
('ramayana-2-2-7', 'en', 'I am worn out carrying the heavy burden of dharma for the world, which comes with royal power and is hard to bear for those who have not mastered their senses.', 'veda-app-ai-draft', true),
('ramayana-2-2-8', 'en', 'I wish to rest by placing my son in charge of the people''s welfare, with the consent of all these brahmins gathered here.', 'veda-app-ai-draft', true),
('ramayana-2-2-9', 'en', 'My eldest son Rama, conqueror of enemy cities, equal to Indra in valour, has inherited all my virtues.', 'veda-app-ai-draft', true),
('ramayana-2-2-10', 'en', 'Gladly I will install that bull among men, best of upholders of dharma, as crown prince, as the moon is joined with the star Pushya.', 'veda-app-ai-draft', true),
('ramayana-2-2-11', 'en', 'Lakshmana''s elder brother, blessed with fortune, will be a fitting lord for you; with him as lord even the three worlds would be well protected.', 'veda-app-ai-draft', true),
('ramayana-2-2-12', 'en', 'Joining this land with this good fortune, and placing it in my son''s care, I will be free of strain.', 'veda-app-ai-draft', true),
('ramayana-2-2-13', 'en', 'As he spoke, the kings joyfully welcomed the king, like peacocks greeting a great, thundering rain cloud.', 'veda-app-ai-draft', true),
('ramayana-2-2-14', 'en', 'Understanding fully the intent of the king who knew dharma and purpose, they considered it in their minds and spoke to old King Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-2-2-15', 'en', 'You are old, O king, of many thousands of years. Crown Rama as crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-2-16', 'en', 'Hearing these words so pleasing to him, the king, as if he did not know, said this, wanting to test them:', 'veda-app-ai-draft', true),
('ramayana-2-2-17', 'en', 'Why, while I rule the earth with dharma, do you want to see my son as crown prince?', 'veda-app-ai-draft', true),
('ramayana-2-2-18', 'en', 'They and the people of town and country said to the great king: Your son has many fine qualities, O king.', 'veda-app-ai-draft', true),
('ramayana-2-2-19', 'en', 'With divine virtues, Rama, true in valour, equal to Indra, surpasses all the Ikshvakus, lord of people.', 'veda-app-ai-draft', true),
('ramayana-2-2-20', 'en', 'Rama is a good man in the world, devoted to truth and dharma, knowing dharma, true to his word, of good character, free of envy.', 'veda-app-ai-draft', true),
('ramayana-2-2-21', 'en', 'He is patient, comforting, gentle, grateful, master of his senses, soft-spoken and steady-minded, always kind and without envy.', 'veda-app-ai-draft', true),
('ramayana-2-2-22', 'en', 'Raghava speaks kindly and truthfully to all beings, and attends upon learned, elderly brahmins.', 'veda-app-ai-draft', true),
('ramayana-2-2-23', 'en', 'So his matchless fame, glory and power grow here; he is skilled in all the weapons of gods, demons and men.', 'veda-app-ai-draft', true),
('ramayana-2-2-24', 'en', 'When he goes to battle for a village or city with Saumitri, he never returns without victory.', 'veda-app-ai-draft', true),
('ramayana-2-2-25', 'en', 'Returning from battle on elephant or chariot, he always asks the citizens about their welfare as if they were his own family.', 'veda-app-ai-draft', true),
('ramayana-2-2-26', 'en', 'About their sons, sacred fires, wives, servants and pupils, fully and in order, as a father asks about his own sons,', 'veda-app-ai-draft', true),
('ramayana-2-2-27', 'en', 'Do your pupils serve you, and are they diligent in their work? This is what that tiger among men, Rama, always asks us.', 'veda-app-ai-draft', true),
('ramayana-2-2-28', 'en', 'He is deeply grieved at people''s troubles and rejoices like a father in all their festivals.', 'veda-app-ai-draft', true),
('ramayana-2-2-29', 'en', 'Truthful, a great archer, serving his elders, master of his senses: this child has been born for your good fortune; happily he is your Raghava, endowed with a son''s virtues, as Kashyapa was to Marichi.', 'veda-app-ai-draft', true),
('ramayana-2-2-30', 'en', 'All the people in the kingdom and in the capital wish strength, health and long life to self-knowing Rama.', 'veda-app-ai-draft', true),
('ramayana-2-2-31', 'en', 'People inside and outside the city, of town and country, women old and young, morning and evening with focused minds,', 'veda-app-ai-draft', true),
('ramayana-2-2-32', 'en', 'bow to all the gods for the sake of famous Rama. May their prayers be fulfilled by your grace, lord.', 'veda-app-ai-draft', true),
('ramayana-2-2-33', 'en', 'We wish to see Rama, dark as a blue lotus, destroyer of all enemies, your son, best of kings, established as crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-2-34', 'en', 'Your god-like son, devoted to the good of the whole world, you should quickly and joyfully crown for our good, giver of boons.', 'veda-app-ai-draft', true),
('ramayana-2-3-1', 'en', 'Accepting their lotus-like folded hands raised on all sides, the king spoke to them pleasing and beneficial words.', 'veda-app-ai-draft', true),
('ramayana-2-3-2', 'en', 'Ah, I am delighted, and my influence is boundless, since you want my dear eldest son as crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-3-3', 'en', 'Having honoured them, the king said this to the brahmins Vasishtha and Vamadeva as the others listened:', 'veda-app-ai-draft', true),
('ramayana-2-3-4', 'en', 'This glorious month of Chaitra is holy, its forests in flower. Let everything be prepared for Rama''s installation as crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-3-5', 'en', 'The two best of brahmins came to the lord of the world and, glad and joyful, said: It is done as you say.', 'veda-app-ai-draft', true),
('ramayana-2-3-6', 'en', 'Then the radiant king said to Sumantra: Bring self-possessed Rama here quickly.', 'veda-app-ai-draft', true),
('ramayana-2-3-7', 'en', 'Sumantra agreed and, at the king''s command, brought Rama, best of chariot-warriors, there by chariot.', 'veda-app-ai-draft', true),
('ramayana-2-3-8', 'en', 'Then the kings seated there around King Dasharatha, from the east, north, west and south,', 'veda-app-ai-draft', true),
('ramayana-2-3-9', 'en', 'mlecchas and aryas and others who lived in the forests and mountains, all attended him like the gods around Indra.', 'veda-app-ai-draft', true),
('ramayana-2-3-10', 'en', 'Among them the royal sage, like Indra among the Maruts, from his palace saw his son coming in a chariot.', 'veda-app-ai-draft', true),
('ramayana-2-3-11', 'en', 'Like a king of the gandharvas, famed for his manliness, long-armed, great-hearted, walking like a proud elephant,', 'veda-app-ai-draft', true),
('ramayana-2-3-12', 'en', 'with a face lovely as the moon, most pleasing to see, stealing the eyes and hearts of men with his beauty, generosity and virtues,', 'veda-app-ai-draft', true),
('ramayana-2-3-13', 'en', 'like a rain cloud cheering people scorched by summer heat: the king could not have enough of watching him approach.', 'veda-app-ai-draft', true),
('ramayana-2-3-14', 'en', 'Sumantra helped Raghava down from the fine chariot and followed behind with folded hands as he went to his father.', 'veda-app-ai-draft', true),
('ramayana-2-3-15', 'en', 'The best of men, Raghava, climbed the palace, shining like a peak of Kailasa, with the charioteer, to see the king.', 'veda-app-ai-draft', true),
('ramayana-2-3-16', 'en', 'Approaching with folded hands and bowing near his father, Rama announced his name and touched his father''s feet.', 'veda-app-ai-draft', true),
('ramayana-2-3-17', 'en', 'Seeing him bowed at his side with folded hands, the king took his hands, drew him close and embraced his dear son.', 'veda-app-ai-draft', true),
('ramayana-2-3-18', 'en', 'The glorious king pointed Rama to a splendid seat set ready for him, adorned with gems and gold.', 'veda-app-ai-draft', true),
('ramayana-2-3-19', 'en', 'Taking that fine seat, Raghava lit it up with his own radiance, like the clear rising sun lighting Mount Meru.', 'veda-app-ai-draft', true),
('ramayana-2-3-20', 'en', 'Lit up by him, the hall shone like the clear autumn sky with its planets and stars lit by the moon.', 'veda-app-ai-draft', true),
('ramayana-2-3-21', 'en', 'Looking at his dear son, the king was delighted, as if seeing himself adorned in a mirror.', 'veda-app-ai-draft', true),
('ramayana-2-3-22', 'en', 'Smiling, the best of fathers spoke to his son, as Kashyapa spoke to Indra:', 'veda-app-ai-draft', true),
('ramayana-2-3-23', 'en', 'You are my worthy son, born of my worthy eldest queen, best in virtues, my dear son Rama.', 'veda-app-ai-draft', true),
('ramayana-2-3-24', 'en', 'Since the people are devoted to you through your virtues, become crown prince under the star Pushya.', 'veda-app-ai-draft', true),
('ramayana-2-3-25', 'en', 'By nature you are disciplined and virtuous; yet out of love, son, I will tell you what is good for you, though you are virtuous.', 'veda-app-ai-draft', true),
('ramayana-2-3-26', 'en', 'Be even more humble and always master your senses. Give up the vices that come from desire and anger.', 'veda-app-ai-draft', true),
('ramayana-2-3-27', 'en', 'Through what you do both openly and unseen, keep your ministers and all your subjects content.', 'veda-app-ai-draft', true),
('ramayana-2-3-28', 'en', 'When a king protects the earth with contented, loyal subjects, his friends rejoice like the gods on gaining nectar. So, son, act always with self-restraint.', 'veda-app-ai-draft', true),
('ramayana-2-3-29', 'en', 'Hearing this, Rama''s friends, eager to please him, hurried to tell Kausalya.', 'veda-app-ai-draft', true),
('ramayana-2-3-30', 'en', 'Kausalya, finest of women, ordered gold, cows and many jewels to be given to those who brought the good news.', 'veda-app-ai-draft', true),
('ramayana-2-3-31', 'en', 'Then, bowing to the king, Raghava mounted his chariot and went to his own bright palace, honoured by crowds.', 'veda-app-ai-draft', true),
('ramayana-2-3-32', 'en', 'And the citizens, hearing the king''s words as if they had gained a cherished wish, took leave of the king, went home and joyfully worshipped the gods.', 'veda-app-ai-draft', true),
('ramayana-2-4-1', 'en', 'When the citizens had gone, the king again took counsel with his ministers and, knowing how to decide, made his decision.', 'veda-app-ai-draft', true),
('ramayana-2-4-2', 'en', 'Tomorrow will be Pushya; tomorrow let my son Rama, with eyes like red lotuses, be crowned crown prince, the lord decided.', 'veda-app-ai-draft', true),
('ramayana-2-4-3', 'en', 'Then, entering the inner palace, King Dasharatha ordered the charioteer: Bring Rama here again.', 'veda-app-ai-draft', true),
('ramayana-2-4-4', 'en', 'Accepting the order, the charioteer quickly went again to Rama''s house to bring him.', 'veda-app-ai-draft', true),
('ramayana-2-4-5', 'en', 'Hearing from the doorkeepers that he had come again, Rama grew uneasy.', 'veda-app-ai-draft', true),
('ramayana-2-4-6', 'en', 'Admitting him quickly, Rama said: Tell me fully why you have come again.', 'veda-app-ai-draft', true),
('ramayana-2-4-7', 'en', 'The charioteer said: The king wishes to see you. Having heard, decide whether to go or not.', 'veda-app-ai-draft', true),
('ramayana-2-4-8', 'en', 'Hearing the charioteer, Rama hurried to the royal palace to see the king again.', 'veda-app-ai-draft', true),
('ramayana-2-4-9', 'en', 'Hearing Rama had arrived, King Dasharatha had him brought in, wishing to tell him dear news.', 'veda-app-ai-draft', true),
('ramayana-2-4-10', 'en', 'As soon as glorious Raghava entered his father''s palace, he saw his father from afar and bowed down with folded hands.', 'veda-app-ai-draft', true),
('ramayana-2-4-11', 'en', 'Raising him up as he bowed and embracing him, the king showed him a fine seat and spoke again.', 'veda-app-ai-draft', true),
('ramayana-2-4-12', 'en', 'Rama, I am old and long-lived; I have enjoyed the pleasures I wanted and performed hundreds of sacrifices rich in food and gifts.', 'veda-app-ai-draft', true),
('ramayana-2-4-13', 'en', 'The child I longed for was born, you, matchless on earth today. I have given, sacrificed and studied, best of men.', 'veda-app-ai-draft', true),
('ramayana-2-4-14', 'en', 'I have known the joys I wanted, hero; I am free of debt to gods, sages, ancestors, brahmins and myself.', 'veda-app-ai-draft', true),
('ramayana-2-4-15', 'en', 'Nothing remains for me to do except your coronation. So you should do what I tell you.', 'veda-app-ai-draft', true),
('ramayana-2-4-16', 'en', 'Today all the people want you as their ruler. So I will crown you crown prince, my son.', 'veda-app-ai-draft', true),
('ramayana-2-4-17', 'en', 'Also, Rama, I am seeing terrible, ill-omened dreams; great meteors are falling here with thunder and roaring.', 'veda-app-ai-draft', true),
('ramayana-2-4-18', 'en', 'Astrologers tell me, Rama, that my birth star is beset by fierce planets: the sun, Mars and Rahu.', 'veda-app-ai-draft', true),
('ramayana-2-4-19', 'en', 'When such omens appear, usually a king dies or meets terrible misfortune.', 'veda-app-ai-draft', true),
('ramayana-2-4-20', 'en', 'So, while my mind is still clear, Raghava, be crowned, for people''s minds are fickle.', 'veda-app-ai-draft', true),
('ramayana-2-4-21', 'en', 'Today the moon has entered Punarvasu, before Pushya; tomorrow, the astrologers say, it will surely be in Pushya.', 'veda-app-ai-draft', true),
('ramayana-2-4-22', 'en', 'Be crowned at Pushya; my mind urges me on. Tomorrow I will crown you crown prince, scorcher of foes.', 'veda-app-ai-draft', true),
('ramayana-2-4-23', 'en', 'So tonight you and your wife must keep a vow, self-controlled, fasting and sleeping on a bed of darbha grass.', 'veda-app-ai-draft', true),
('ramayana-2-4-24', 'en', 'Let your friends guard you carefully on every side today, for such undertakings meet many obstacles.', 'veda-app-ai-draft', true),
('ramayana-2-4-25', 'en', 'While Bharata is away from the city, I think this is the right time for your coronation.', 'veda-app-ai-draft', true),
('ramayana-2-4-26', 'en', 'Certainly your brother Bharata keeps to the conduct of the good, follows his elder, is righteous, compassionate and self-controlled.', 'veda-app-ai-draft', true),
('ramayana-2-4-27', 'en', 'But I believe the minds of men are changeable, Raghava, even of the good who are devoted to dharma.', 'veda-app-ai-draft', true),
('ramayana-2-4-28', 'en', 'Thus told and dismissed for the coronation set for tomorrow, Rama bowed to his father and went home.', 'veda-app-ai-draft', true),
('ramayana-2-4-29', 'en', 'Entering his house after the king had announced the coronation, he at once went out again to his mother''s quarters.', 'veda-app-ai-draft', true),
('ramayana-2-4-30', 'en', 'There he saw his mother, devout, in linen, silent in the shrine, praying for his fortune.', 'veda-app-ai-draft', true),
('ramayana-2-4-31', 'en', 'Sumitra and Lakshmana had already come there, and Sita had been brought, hearing the welcome news of Rama''s coronation.', 'veda-app-ai-draft', true),
('ramayana-2-4-32', 'en', 'Kausalya stood there with eyes closed, attended by Sumitra, Sita and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-4-33', 'en', 'Having heard of her son''s coronation under Pushya, she was meditating on Lord Janardana with breath control.', 'veda-app-ai-draft', true),
('ramayana-2-4-34', 'en', 'Approaching her as she kept her vow, Rama greeted her and, to delight her, said:', 'veda-app-ai-draft', true),
('ramayana-2-4-35', 'en', 'Mother, father has appointed me to protect the people. Tomorrow will be my coronation, as father commands.', 'veda-app-ai-draft', true),
('ramayana-2-4-36', 'en', 'Sita too must fast with me tonight; so father told me, with the priests and teachers.', 'veda-app-ai-draft', true),
('ramayana-2-4-37', 'en', 'Have whatever blessings are fitting for tomorrow''s coronation performed today for me and for Vaidehi.', 'veda-app-ai-draft', true),
('ramayana-2-4-38', 'en', 'Hearing what she had long desired, Kausalya spoke to Rama, her voice choked with tears of joy:', 'veda-app-ai-draft', true),
('ramayana-2-4-39', 'en', 'Rama, my child, live long; may your foes be destroyed. Gaining royal fortune, bring joy to my kin and Sumitra''s.', 'veda-app-ai-draft', true),
('ramayana-2-4-40', 'en', 'Surely, my son, you were born to me under a lucky star, since you have won your father Dasharatha by your virtues.', 'veda-app-ai-draft', true),
('ramayana-2-4-41', 'en', 'Surely my devotion to the lotus-eyed Lord was not in vain, since this royal fortune of the Ikshvakus will come to you, my son.', 'veda-app-ai-draft', true),
('ramayana-2-4-42', 'en', 'Thus addressed by his mother, Rama, looking at his brother seated humbly with folded hands, said with a smile:', 'veda-app-ai-draft', true),
('ramayana-2-4-43', 'en', 'Lakshmana, rule this earth with me. You are my second self; this fortune has come to you too.', 'veda-app-ai-draft', true),
('ramayana-2-4-44', 'en', 'Saumitri, enjoy the pleasures you wish and the fruits of kingship. I desire life and kingdom for your sake.', 'veda-app-ai-draft', true),
('ramayana-2-4-45', 'en', 'Having said this to Lakshmana, Rama bowed to his two mothers, took leave with Sita, and went to his own house.', 'veda-app-ai-draft', true),
('ramayana-2-5-1', 'en', 'Having instructed Rama about tomorrow''s coronation, the king summoned his priest Vasishtha and said:', 'veda-app-ai-draft', true),
('ramayana-2-5-2', 'en', 'Go, ascetic, and have Kakutstha and his wife keep the fast today, observing the vow, for fortune, glory and the kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-5-3', 'en', 'Saying So be it, blessed Vasishtha, best of Veda knowers, went himself to Rama''s house.', 'veda-app-ai-draft', true),
('ramayana-2-5-4', 'en', 'Reaching Rama''s house, bright as a mass of white cloud, the best of sages drove his chariot through three courtyards.', 'veda-app-ai-draft', true),
('ramayana-2-5-5', 'en', 'Seeing the sage arrive, Rama hurried out of the house eagerly to honour him who deserved honour.', 'veda-app-ai-draft', true),
('ramayana-2-5-6', 'en', 'Hurrying to the wise man''s chariot, he himself helped him down, holding him.', 'veda-app-ai-draft', true),
('ramayana-2-5-7', 'en', 'Seeing him so humble, the priest spoke with him kindly and, delighting Rama who deserved kindness, said:', 'veda-app-ai-draft', true),
('ramayana-2-5-8', 'en', 'Your father is pleased, Rama; you will become crown prince. Today keep the fast with Sita.', 'veda-app-ai-draft', true),
('ramayana-2-5-9', 'en', 'At dawn your father, King Dasharatha, will lovingly crown you, as Nahusha crowned Yayati.', 'veda-app-ai-draft', true),
('ramayana-2-5-10', 'en', 'Having said this, the sage had Rama, steadfast in his vow, keep the fast with Vaidehi, with proper mantras.', 'veda-app-ai-draft', true),
('ramayana-2-5-11', 'en', 'Then, duly honoured by Rama, the king''s teacher took leave of Kakutstha and left Rama''s house.', 'veda-app-ai-draft', true),
('ramayana-2-5-12', 'en', 'Rama too, saying goodbye to his friends there and honoured by them, went inside.', 'veda-app-ai-draft', true),
('ramayana-2-5-13', 'en', 'Rama''s house, full of joyful men and women, shone like a lake of blooming lotuses with flocks of excited birds.', 'veda-app-ai-draft', true),
('ramayana-2-5-14', 'en', 'Coming out of Rama''s palace, which rivalled the king''s, Vasishtha saw the road crowded with people.', 'veda-app-ai-draft', true),
('ramayana-2-5-15', 'en', 'On every side in Ayodhya the royal roads were jammed with throngs of curious people.', 'veda-app-ai-draft', true),
('ramayana-2-5-16', 'en', 'The royal road, with waves of crowds jostling and joyful noise, sounded like the ocean.', 'veda-app-ai-draft', true),
('ramayana-2-5-17', 'en', 'That day the city of Ayodhya, its streets sprinkled and swept, was garlanded with trees, and flags flew high on its houses.', 'veda-app-ai-draft', true),
('ramayana-2-5-18', 'en', 'All the people of Ayodhya, with women, children and the old, longed for Rama''s coronation, longing for the sun to rise.', 'veda-app-ai-draft', true),
('ramayana-2-5-19', 'en', 'The people were eager to see that great festival of Ayodhya, the jewel of its people that would increase their joy.', 'veda-app-ai-draft', true),
('ramayana-2-5-20', 'en', 'The priest, as if parting the crowds on the jammed royal road, slowly made his way to the royal palace.', 'veda-app-ai-draft', true),
('ramayana-2-5-21', 'en', 'Climbing the palace, like a white cloud-peak, he met the king as Brihaspati meets Indra.', 'veda-app-ai-draft', true),
('ramayana-2-5-22', 'en', 'Seeing him come, the king rose from his throne and asked; and he told him it was done.', 'veda-app-ai-draft', true),
('ramayana-2-5-23', 'en', 'With his guru''s leave, the king dismissed the crowd and entered the inner palace like a lion entering a mountain cave.', 'veda-app-ai-draft', true),
('ramayana-2-5-24', 'en', 'The king entered that residence like great Indra''s, crowded with finely dressed women, lighting it up, as the moon enters a sky full of stars.', 'veda-app-ai-draft', true),
('ramayana-2-6-1', 'en', 'When the priest had gone, Rama bathed and, with focused mind, approached Narayana with his wide-eyed wife.', 'veda-app-ai-draft', true),
('ramayana-2-6-2', 'en', 'Taking the vessel of offering on his head as prescribed, he offered ghee into the blazing fire to the great deity.', 'veda-app-ai-draft', true),
('ramayana-2-6-3', 'en', 'Eating the rest of the offering and praying for what was dear to him, meditating on Lord Narayana, on a well-spread bed of kusha grass,', 'veda-app-ai-draft', true),
('ramayana-2-6-4', 'en', 'silent with Vaidehi, his mind controlled, the prince slept in the splendid shrine of Vishnu.', 'veda-app-ai-draft', true),
('ramayana-2-6-5', 'en', 'Waking when one watch of the night remained, he had the whole house decorated.', 'veda-app-ai-draft', true),
('ramayana-2-6-6', 'en', 'There, hearing the pleasant voices of bards and heralds, he performed the dawn worship and prayed with a controlled mind.', 'veda-app-ai-draft', true),
('ramayana-2-6-7', 'en', 'Bowing his head, he praised Madhusudana and, dressed in clean linen, had brahmins recite blessings.', 'veda-app-ai-draft', true),
('ramayana-2-6-8', 'en', 'Their deep, sweet cries of blessing for a holy day, echoing with music, filled Ayodhya.', 'veda-app-ai-draft', true),
('ramayana-2-6-9', 'en', 'Hearing that Raghava had begun his fast with Vaidehi, all the people of Ayodhya rejoiced.', 'veda-app-ai-draft', true),
('ramayana-2-6-10', 'en', 'Then all the citizens, hearing of Rama''s coronation and seeing the night turn to dawn, decorated the city splendidly again.', 'veda-app-ai-draft', true),
('ramayana-2-6-11', 'en', 'On temples like white cloud-peaks, at crossroads and in streets, on sacred trees and watchtowers,', 'veda-app-ai-draft', true),
('ramayana-2-6-12', 'en', 'in merchants'' shops full of goods, in the rich, splendid homes of householders,', 'veda-app-ai-draft', true),
('ramayana-2-6-13', 'en', 'in all the halls and on prominent trees, colourful flags and banners were raised.', 'veda-app-ai-draft', true),
('ramayana-2-6-14', 'en', 'Everywhere one heard the voices of actors, dancers and singers, pleasing to mind and ear.', 'veda-app-ai-draft', true),
('ramayana-2-6-15', 'en', 'With the coronation at hand, people talked together about Rama''s coronation in squares and homes.', 'veda-app-ai-draft', true),
('ramayana-2-6-16', 'en', 'Even children playing in groups at their doors talked to each other about Rama''s coronation.', 'veda-app-ai-draft', true),
('ramayana-2-6-17', 'en', 'For Rama''s coronation the citizens made the royal road splendid with offerings of flowers and scented with incense.', 'veda-app-ai-draft', true),
('ramayana-2-6-18', 'en', 'Fearing nightfall, they set up lamp-trees all along the streets to light them.', 'veda-app-ai-draft', true),
('ramayana-2-6-19', 'en', 'Having decorated the city, the citizens, longing for Rama''s coronation as crown prince,', 'veda-app-ai-draft', true),
('ramayana-2-6-20', 'en', 'gathered in groups in squares and halls and, talking together, praised the king.', 'veda-app-ai-draft', true),
('ramayana-2-6-21', 'en', 'Ah, this king, joy of the Ikshvakus, is great-souled: knowing himself to be old, he will crown Rama.', 'veda-app-ai-draft', true),
('ramayana-2-6-22', 'en', 'We are all blessed that Rama, who has seen the world''s high and low, will long be our king and protector.', 'veda-app-ai-draft', true),
('ramayana-2-6-23', 'en', 'Humble, learned, righteous and loving to his brothers: as Raghava is affectionate to his brothers, so is he to us.', 'veda-app-ai-draft', true),
('ramayana-2-6-24', 'en', 'Long live the righteous, sinless King Dasharatha, by whose grace we will see Rama crowned.', 'veda-app-ai-draft', true),
('ramayana-2-6-25', 'en', 'The country people, who had heard the news from every direction, listened to the citizens talking like this.', 'veda-app-ai-draft', true),
('ramayana-2-6-26', 'en', 'Arriving from all directions to see Rama''s coronation, the country people filled Rama''s city.', 'veda-app-ai-draft', true),
('ramayana-2-6-27', 'en', 'The sound of those surging crowds was heard like the roar of the ocean when its tides rise at the full moon.', 'veda-app-ai-draft', true),
('ramayana-2-6-28', 'en', 'That city, like Indra''s home, crowded on all sides with country people come to see, shone loud and teeming like ocean water full of sea creatures.', 'veda-app-ai-draft', true),
('ramayana-2-7-1', 'en', 'Kaikeyi''s maid, born in her family and brought up with her, happened to climb up to the moon-bright terrace.', 'veda-app-ai-draft', true),
('ramayana-2-7-2', 'en', 'From that terrace Manthara looked out over all Ayodhya, its royal road sprinkled and strewn with lotuses.', 'veda-app-ai-draft', true),
('ramayana-2-7-3', 'en', 'Adorned with fine banners and flags, sprinkled with sandal-water, full of people freshly bathed,', 'veda-app-ai-draft', true),
('ramayana-2-7-4', 'en', 'Seeing a nurse standing nearby, Manthara asked her, the nurse wearing her finest and full of joy:', 'veda-app-ai-draft', true),
('ramayana-2-7-5', 'en', 'Why is Rama''s mother giving wealth to people? Tell me why everyone is so overjoyed. What is the delighted king going to do?', 'veda-app-ai-draft', true),
('ramayana-2-7-6', 'en', 'The nurse, bursting with joy, told the hunchbacked maid of Raghava''s great fortune:', 'veda-app-ai-draft', true),
('ramayana-2-7-7', 'en', 'Tomorrow under Pushya King Dasharatha will crown sinless Rama, who has conquered anger, as crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-7-8', 'en', 'Hearing the nurse, the maid, instantly resentful, came down from the palace shaped like a Kailasa peak.', 'veda-app-ai-draft', true),
('ramayana-2-7-9', 'en', 'Burning with anger, evil-minded Manthara went to Kaikeyi as she lay resting and said:', 'veda-app-ai-draft', true),
('ramayana-2-7-10', 'en', 'Get up, foolish woman! How can you lie there when danger threatens you? Don''t you see you are swamped by a great flood?', 'veda-app-ai-draft', true),
('ramayana-2-7-11', 'en', 'Unlucky one with the look of a lucky one, you boast of your good fortune; but your fortune is fleeting, like a river''s flow in summer.', 'veda-app-ai-draft', true),
('ramayana-2-7-12', 'en', 'Told these harsh words by the angry, evil-minded maid, Kaikeyi was deeply troubled.', 'veda-app-ai-draft', true),
('ramayana-2-7-13', 'en', 'Kaikeyi said to her: Is something wrong, Manthara? I see your face is sad and you are very upset.', 'veda-app-ai-draft', true),
('ramayana-2-7-14', 'en', 'Hearing Kaikeyi''s sweet words, Manthara, clever with words, answered angrily.', 'veda-app-ai-draft', true),
('ramayana-2-7-15', 'en', 'More dejected still, the maid, appearing to seek her good, spoke to dismay her and to turn her against Raghava:', 'veda-app-ai-draft', true),
('ramayana-2-7-16', 'en', 'A great disaster has begun, queen, that will ruin you: King Dasharatha will crown Rama as crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-7-17', 'en', 'I am sunk in bottomless fear, full of grief, burning as if in fire; I have come here for your sake.', 'veda-app-ai-draft', true),
('ramayana-2-7-18', 'en', 'Your sorrow would be my great sorrow, Kaikeyi, and your rise my rise; of this there is no doubt.', 'veda-app-ai-draft', true),
('ramayana-2-7-19', 'en', 'You were born in a royal family and are the king''s queen; how can you not understand how harsh royal politics is?', 'veda-app-ai-draft', true),
('ramayana-2-7-20', 'en', 'Your husband talks of dharma but is deceitful; he speaks softly but is cruel. Pure-hearted, you do not see it, so you have been tricked.', 'veda-app-ai-draft', true),
('ramayana-2-7-21', 'en', 'Your husband offers you empty comfort, while he will give real benefit to Kausalya today.', 'veda-app-ai-draft', true),
('ramayana-2-7-22', 'en', 'Having sent Bharata away to your relatives, the wicked man will establish Rama tomorrow in a kingdom cleared of rivals.', 'veda-app-ai-draft', true),
('ramayana-2-7-23', 'en', 'You have held an enemy called husband close like a mother, foolish girl, as one holds a poisonous snake in one''s lap.', 'veda-app-ai-draft', true),
('ramayana-2-7-24', 'en', 'As a snake or a neglected enemy would do, so King Dasharatha has today done to you and your son.', 'veda-app-ai-draft', true),
('ramayana-2-7-25', 'en', 'By that wicked man with his false comfort, you who are used to happiness are ruined with all your kin, as he sets Rama on the throne.', 'veda-app-ai-draft', true),
('ramayana-2-7-26', 'en', 'So, Kaikeyi, quickly do what serves you while there is time. Save your son, yourself and me, lovely one.', 'veda-app-ai-draft', true),
('ramayana-2-7-27', 'en', 'Hearing Manthara, the fair-faced queen rose from her bed and gave the maid a beautiful ornament.', 'veda-app-ai-draft', true),
('ramayana-2-7-28', 'en', 'Having given the ornament, Kaikeyi, finest of women, delighted, spoke again to Manthara:', 'veda-app-ai-draft', true),
('ramayana-2-7-29', 'en', 'Manthara, this is the most welcome news you tell me. What more can I do for you for this good news?', 'veda-app-ai-draft', true),
('ramayana-2-7-30', 'en', 'I see no difference between Rama and Bharata. So I am happy that the king will crown Rama.', 'veda-app-ai-draft', true),
('ramayana-2-7-31', 'en', 'No news could be dearer to me than this, dear one. Since you have told me such happy news, I will give you a further boon; choose it.', 'veda-app-ai-draft', true),
('ramayana-2-8-1', 'en', 'But Manthara, resenting her, threw away the ornament and, full of anger and grief, said:', 'veda-app-ai-draft', true),
('ramayana-2-8-2', 'en', 'Why this misplaced joy, foolish girl? You do not see that you are in the middle of an ocean of sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-8-3', 'en', 'Fortunate indeed is Kausalya, whose son will be installed tomorrow as crown prince under Pushya by the best of brahmins.', 'veda-app-ai-draft', true),
('ramayana-2-8-4', 'en', 'You will wait on Kausalya with folded hands like a servant, when she has gained great joy and is rid of her rivals.', 'veda-app-ai-draft', true),
('ramayana-2-8-5', 'en', 'Rama''s wives will be overjoyed, and your daughters-in-law will be miserable at Bharata''s ruin.', 'veda-app-ai-draft', true),
('ramayana-2-8-6', 'en', 'Seeing Manthara speak so, deeply upset, Queen Kaikeyi simply praised Rama''s virtues.', 'veda-app-ai-draft', true),
('ramayana-2-8-7', 'en', 'Rama knows dharma, is trained by his elders, grateful, truthful and pure. He is the king''s eldest son and so deserves to be crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-8-8', 'en', 'Long-lived, he will protect his brothers and servants like a father. Why are you upset, maid, hearing of Rama''s coronation?', 'veda-app-ai-draft', true),
('ramayana-2-8-9', 'en', 'And surely after a hundred years Bharata too, bull among men, will gain the kingdom of his fathers after Rama.', 'veda-app-ai-draft', true),
('ramayana-2-8-10', 'en', 'Now that good fortune has come, and is present, and more will come, why do you grieve, Manthara? Rama serves me even more than Kausalya.', 'veda-app-ai-draft', true),
('ramayana-2-8-11', 'en', 'Hearing Kaikeyi, Manthara, very upset, sighed long and hot and said to Kaikeyi:', 'veda-app-ai-draft', true),
('ramayana-2-8-12', 'en', 'Seeing only harm through folly, you do not understand yourself, sinking in an ocean of sorrow wide with grief and misfortune.', 'veda-app-ai-draft', true),
('ramayana-2-8-13', 'en', 'Raghava will be king, and then Raghava''s son; Bharata will be cut out of the royal line, Kaikeyi.', 'veda-app-ai-draft', true),
('ramayana-2-8-14', 'en', 'Not all a king''s sons stay in the kingdom, lovely one; if all were installed there would be great disorder.', 'veda-app-ai-draft', true),
('ramayana-2-8-15', 'en', 'So kings place the reins of state with the eldest, flawless one, even when the others are virtuous.', 'veda-app-ai-draft', true),
('ramayana-2-8-16', 'en', 'Your son will be utterly broken, cut off from pleasures and from the royal line, like an orphan, loving mother.', 'veda-app-ai-draft', true),
('ramayana-2-8-17', 'en', 'I have come for your sake, but you do not understand me, and want to give me a reward for your co-wife''s rise.', 'veda-app-ai-draft', true),
('ramayana-2-8-18', 'en', 'Surely Rama, once he has the kingdom unchallenged, will send Bharata to another land, or even to the other world.', 'veda-app-ai-draft', true),
('ramayana-2-8-19', 'en', 'You sent Bharata, while still a child, to his uncle''s; but closeness breeds affection even among plants.', 'veda-app-ai-draft', true),
('ramayana-2-8-20', 'en', 'Saumitri protects Rama, and Raghava protects Lakshmana; their brotherhood is famous in the worlds, like the Ashvins''.', 'veda-app-ai-draft', true),
('ramayana-2-8-21', 'en', 'So Rama will do no harm to Lakshmana, but no doubt Rama would harm Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-8-22', 'en', 'So let your son go straight from the royal palace to the forest. That pleases me and is very much for your good.', 'veda-app-ai-draft', true),
('ramayana-2-8-23', 'en', 'That will be good for your side of the family, if Bharata by dharma gains his father''s kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-8-24', 'en', 'How will that child, used to comfort, Rama''s natural rival, live in his power, having lost everything while Rama prospers?', 'veda-app-ai-draft', true),
('ramayana-2-8-25', 'en', 'You must save Bharata, overshadowed by Rama, like an elephant-leader chased by a lion in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-8-26', 'en', 'Rama''s mother, your co-wife, whom you once slighted in your pride as the favourite, how would she not take revenge?', 'veda-app-ai-draft', true),
('ramayana-2-8-27', 'en', 'When Rama gains the earth, Bharata will surely be lost. So think today about the kingdom for your son and a reason to banish the other.', 'veda-app-ai-draft', true),
('ramayana-2-9-1', 'en', 'Thus addressed, Kaikeyi, her face flaming with anger, sighed long and hot and said to Manthara:', 'veda-app-ai-draft', true),
('ramayana-2-9-2', 'en', 'Today I will quickly send Rama from here to the forest, and quickly have Bharata installed as crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-9-3', 'en', 'Now, Manthara, see by what means Bharata may get the kingdom and Rama by no means.', 'veda-app-ai-draft', true),
('ramayana-2-9-4', 'en', 'Thus addressed by the queen, evil-minded Manthara, seeking to harm Rama, said to Kaikeyi:', 'veda-app-ai-draft', true),
('ramayana-2-9-5', 'en', 'Listen, Kaikeyi, I will tell you how your son Bharata alone will gain the kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-9-6', 'en', 'Hearing Manthara''s words, Kaikeyi rose a little from her well-made bed and said:', 'veda-app-ai-draft', true),
('ramayana-2-9-7', 'en', 'Tell me the plan, Manthara, by which Bharata may gain the kingdom and Rama never.', 'veda-app-ai-draft', true),
('ramayana-2-9-8', 'en', 'Thus addressed by the queen, the evil-minded maid, seeking to harm Rama, spoke:', 'veda-app-ai-draft', true),
('ramayana-2-9-9', 'en', 'In the war between gods and demons, your husband went with the royal sages, taking you with him, to help the king of the gods.', 'veda-app-ai-draft', true),
('ramayana-2-9-10', 'en', 'He went south towards the Dandakas, Kaikeyi, to the city called Vaijayanta, where Timidhvaja lived,', 'veda-app-ai-draft', true),
('ramayana-2-9-11', 'en', 'the great demon called Shambara, master of a hundred illusions, who fought Indra and was unconquered by the hosts of gods.', 'veda-app-ai-draft', true),
('ramayana-2-9-12', 'en', 'In that great battle, queen, you carried King Dasharatha, unconscious, away from the fighting.', 'veda-app-ai-draft', true),
('ramayana-2-9-13', 'en', 'Even there, when your husband was wounded by weapons, you protected him; and he, pleased, gave you two boons, lovely one.', 'veda-app-ai-draft', true),
('ramayana-2-9-14', 'en', 'You told your husband, queen, I will claim the two boons when I wish, and the great one said, So be it. I did not know this; you told me yourself long ago.', 'veda-app-ai-draft', true),
('ramayana-2-9-15', 'en', 'Ask your husband for those two boons: Bharata''s coronation, and Rama''s banishment for fourteen years.', 'veda-app-ai-draft', true),
('ramayana-2-9-16', 'en', 'Go today into the chamber of anger as if enraged, daughter of Ashvapati. Lie on the bare ground in soiled clothes. Do not look at him or speak to him.', 'veda-app-ai-draft', true),
('ramayana-2-9-17', 'en', 'You are always your husband''s beloved, I have no doubt. For your sake the great king would even enter fire.', 'veda-app-ai-draft', true),
('ramayana-2-9-18', 'en', 'He cannot bear to anger you, nor look at you when angry. To please you, the king would even give up his life.', 'veda-app-ai-draft', true),
('ramayana-2-9-19', 'en', 'The king cannot go against your word. Simple-hearted one, recognise the power of your fortune.', 'veda-app-ai-draft', true),
('ramayana-2-9-20', 'en', 'King Dasharatha may offer gems, pearls, gold and all kinds of jewels; do not set your mind on them.', 'veda-app-ai-draft', true),
('ramayana-2-9-21', 'en', 'Remind him of the two boons he gave in the war of gods and demons, fortunate one; do not let that purpose slip past you.', 'veda-app-ai-draft', true),
('ramayana-2-9-22', 'en', 'When Raghava himself raises you up and offers a boon, bind the great king to it and choose this boon:', 'veda-app-ai-draft', true),
('ramayana-2-9-23', 'en', 'Banish Rama to the forest for nine and five years, and let Bharata, bull among kings, be made king of the earth.', 'veda-app-ai-draft', true),
('ramayana-2-9-24', 'en', 'Banished like this, Rama will lose his joy, and Bharata, rid of his rival, will be your king.', 'veda-app-ai-draft', true),
('ramayana-2-9-25', 'en', 'By the time Rama returns from the forest, your son will be firmly rooted, with the people won over and friends at his side.', 'veda-app-ai-draft', true),
('ramayana-2-9-26', 'en', 'I think the time has come. Without fear, restrain the king and turn him from his plan for Rama''s coronation.', 'veda-app-ai-draft', true),
('ramayana-2-9-27', 'en', 'Made to accept harm disguised as good, Kaikeyi, delighted and confident, said to Manthara:', 'veda-app-ai-draft', true),
('ramayana-2-9-28', 'en', 'Maid, I did not know you were so excellent and gave such excellent advice. Of all such women on earth, you are the best at judgment.', 'veda-app-ai-draft', true),
('ramayana-2-9-29', 'en', 'You are always devoted to my interests and wish me well. I would not have understood what the king was planning.', 'veda-app-ai-draft', true),
('ramayana-2-9-30', 'en', 'Some bent women are ill-formed and wicked, but you are lovely, bending like a lotus in the wind.', 'veda-app-ai-draft', true),
('ramayana-2-9-31', 'en', 'Your breast is high up to your shoulders, and below, your waist is slender, as if shy of its lovely navel.', 'veda-app-ai-draft', true),
('ramayana-2-9-32', 'en', 'Your hips are fine, adorned with a girdle; your legs are shapely and both your feet long.', 'veda-app-ai-draft', true),
('ramayana-2-9-33', 'en', 'With your long thighs, Manthara, dressed in linen, walking before me you shine like a royal swan.', 'veda-app-ai-draft', true),
('ramayana-2-9-34', 'en', 'This long hump of yours, broad as a chariot''s prow, is where your cleverness, statecraft and wiles must live.', 'veda-app-ai-draft', true),
('ramayana-2-9-35', 'en', 'When Bharata is crowned and Raghava has gone to the forest, I will hang a garland of gold on it, maid.', 'veda-app-ai-draft', true),
('ramayana-2-9-36', 'en', 'With refined, pure gold, lovely one, I will coat your hump when I have succeeded and am content.', 'veda-app-ai-draft', true),
('ramayana-2-9-37', 'en', 'I will have a fine golden mark painted on your forehead, maid, and give you lovely ornaments.', 'veda-app-ai-draft', true),
('ramayana-2-9-38', 'en', 'Wearing fine clothes you will walk like a goddess, your matchless face rivalling the moon, and walk proudly before your enemies.', 'veda-app-ai-draft', true),
('ramayana-2-9-39', 'en', 'Other bent women, adorned with ornaments, will serve at your feet as you always serve me.', 'veda-app-ai-draft', true),
('ramayana-2-9-40', 'en', 'Praised like this, Manthara said to Kaikeyi, lying on her white bed like a flame on an altar:', 'veda-app-ai-draft', true),
('ramayana-2-9-41', 'en', 'No one builds a dam when the water has gone, good lady. Get up, do what is good for you, and make the king see.', 'veda-app-ai-draft', true),
('ramayana-2-9-42', 'en', 'Thus urged, the wide-eyed queen, proud and intoxicated by her favour, went with Manthara to the chamber of anger.', 'veda-app-ai-draft', true),
('ramayana-2-9-43', 'en', 'The lovely woman took off her pearl necklace worth many hundreds of thousands, and her fine, costly ornaments.', 'veda-app-ai-draft', true),
('ramayana-2-9-44', 'en', 'Then, golden-skinned Kaikeyi, under the maid''s influence, lay on the ground and said to Manthara:', 'veda-app-ai-draft', true),
('ramayana-2-9-45', 'en', 'Either you will report to the king that I have died here, maid, or Raghava will go to the forest and Bharata will gain the earth.', 'veda-app-ai-draft', true),
('ramayana-2-9-46', 'en', 'Saying these terrible words and putting aside all her ornaments, the lady lay on the bare ground like a fallen kinnari.', 'veda-app-ai-draft', true),
('ramayana-2-9-47', 'en', 'Her face clouded with rising rage, stripped of her fine garlands and jewels, the king''s wife lay distraught, like a dark sky with its stars drowned.', 'veda-app-ai-draft', true),
('ramayana-2-10-1', 'en', 'Having ordered Raghava''s coronation, the self-controlled great king entered the inner palace to tell his beloved the good news.', 'veda-app-ai-draft', true),
('ramayana-2-10-2', 'en', 'There the lord of the earth, as if burned by sorrow, saw her fallen and lying on the ground, which did not befit her.', 'veda-app-ai-draft', true),
('ramayana-2-10-3', 'en', 'The old, sinless king saw his young wife, dearer to him than life, lying on the ground with a sinful purpose.', 'veda-app-ai-draft', true),
('ramayana-2-10-4', 'en', 'Like a great elephant in the forest caressing a female wounded by a hunter''s poisoned arrow, he stroked her lovingly.', 'veda-app-ai-draft', true),
('ramayana-2-10-5', 'en', 'Stroking her with his hands, his mind alarmed, the loving king said to the lotus-eyed woman:', 'veda-app-ai-draft', true),
('ramayana-2-10-6', 'en', 'I do not know why you are angry. Queen, who has wronged you, who has insulted you?', 'veda-app-ai-draft', true),
('ramayana-2-10-7', 'en', 'Why do you lie in the dust, good lady, causing me sorrow? Why lie on the ground when I am devoted to you? You torment my mind as if possessed.', 'veda-app-ai-draft', true),
('ramayana-2-10-8', 'en', 'I have skilled physicians, all well rewarded; they will make you well. Tell me your illness, lovely one.', 'veda-app-ai-draft', true),
('ramayana-2-10-9', 'en', 'Who should be favoured for your sake, or who has displeased you? Who should gain favour today, or suffer great displeasure?', 'veda-app-ai-draft', true),
('ramayana-2-10-10', 'en', 'Who that deserves death should be spared, or who should be put to death? Which poor man should become rich, or which rich man poor?', 'veda-app-ai-draft', true),
('ramayana-2-10-11', 'en', 'I and all mine are at your command. I could not oppose any wish of yours.', 'veda-app-ai-draft', true),
('ramayana-2-10-12', 'en', 'Even at the cost of my own life, tell me what you desire. As far as the wheel of my rule turns, so far the earth is mine.', 'veda-app-ai-draft', true),
('ramayana-2-10-13', 'en', 'Thus addressed and reassured, wanting to speak her cruel wish, she began to torment her husband further.', 'veda-app-ai-draft', true),
('ramayana-2-10-14', 'en', 'I have not been wronged by anyone, lord, nor insulted. But I have a wish, and I want you to fulfil it.', 'veda-app-ai-draft', true),
('ramayana-2-10-15', 'en', 'Make a promise, if you are willing to do it. Then I will tell you what I want.', 'veda-app-ai-draft', true),
('ramayana-2-10-16', 'en', 'Thus addressed by his beloved, the mighty king, ruled by love for her, smiled slightly and said to Kaikeyi:', 'veda-app-ai-draft', true),
('ramayana-2-10-17', 'en', 'Proud woman, do you not know that no one is dearer to me than you, except Rama, tiger among men?', 'veda-app-ai-draft', true),
('ramayana-2-10-18', 'en', 'Good lady, you could even tear out my heart and take it. Considering this, Kaikeyi, say what you think is right.', 'veda-app-ai-draft', true),
('ramayana-2-10-19', 'en', 'Seeing your power over me, you should not doubt me. I will do what pleases you; I swear by my good deeds.', 'veda-app-ai-draft', true),
('ramayana-2-10-20', 'en', 'Delighted by this, she spoke her terrible wish, like death itself arriving.', 'veda-app-ai-draft', true),
('ramayana-2-10-21', 'en', 'As you swear in order and grant me a boon, let the thirty-three gods led by Indra hear it.', 'veda-app-ai-draft', true),
('ramayana-2-10-22', 'en', 'Let the moon and sun, the sky, the planets, night and day, the directions, the world and the earth, with gandharvas and rakshasas,', 'veda-app-ai-draft', true),
('ramayana-2-10-23', 'en', 'the night-wandering beings, the household gods in homes, and all other beings know what you have said.', 'veda-app-ai-draft', true),
('ramayana-2-10-24', 'en', 'He is true to his word, mighty, knowing dharma, composed; he grants me a boon. Let the gods hear it.', 'veda-app-ai-draft', true),
('ramayana-2-10-25', 'en', 'So the queen, having bound and praised the great archer, said this to the boon-giver, deluded by love:', 'veda-app-ai-draft', true),
('ramayana-2-10-26', 'en', 'The two boons you gave me then, lord, I will now name; hear my words.', 'veda-app-ai-draft', true),
('ramayana-2-10-27', 'en', 'The preparations made for Raghava''s coronation: with this very coronation let my Bharata be crowned.', 'veda-app-ai-draft', true),
('ramayana-2-10-28', 'en', 'For nine and five years, living in the Dandaka forest, wearing bark, deerskin and matted hair, let Rama be an ascetic.', 'veda-app-ai-draft', true),
('ramayana-2-10-29', 'en', 'Let Bharata enjoy the crown princeship today without rival, and let me see Raghava leave for the forest today.', 'veda-app-ai-draft', true),
('ramayana-2-10-30', 'en', 'Hearing Kaikeyi''s cruel words, the great king was shaken and terrified, like a deer seeing a tigress.', 'veda-app-ai-draft', true),
('ramayana-2-10-31', 'en', 'Sitting on the bare ground, sighing deeply, the king cried in anger, Ah, shame! and fainted again, stricken with grief.', 'veda-app-ai-draft', true),
('ramayana-2-10-32', 'en', 'After a long time, regaining consciousness, deeply grieved, the king spoke angrily to Kaikeyi, as if burning her with his eyes:', 'veda-app-ai-draft', true),
('ramayana-2-10-33', 'en', 'Cruel, wicked woman, destroyer of this family! What wrong has Rama done you, sinful one, or I?', 'veda-app-ai-draft', true),
('ramayana-2-10-34', 'en', 'Raghava always treats you just as he treats his own mother. Why are you set on harming him of all people?', 'veda-app-ai-draft', true),
('ramayana-2-10-35', 'en', 'Not knowing it, I brought you into my house to destroy myself, a princess like a sharp-fanged snake.', 'veda-app-ai-draft', true),
('ramayana-2-10-36', 'en', 'When the whole world praises Rama''s virtues, for what fault can I abandon my beloved son?', 'veda-app-ai-draft', true),
('ramayana-2-10-37', 'en', 'I could give up Kausalya or Sumitra, or my royal fortune, or my own life, but never Rama, who loves his father.', 'veda-app-ai-draft', true),
('ramayana-2-10-38', 'en', 'I feel the highest joy seeing my eldest son; when I do not see Rama, my mind fails.', 'veda-app-ai-draft', true),
('ramayana-2-10-39', 'en', 'The world may survive without the sun, or crops without water, but my life could not stay in my body without Rama.', 'veda-app-ai-draft', true),
('ramayana-2-10-40', 'en', 'Enough! Give up this resolve, you who are bent on sin. Look, I touch your feet with my head; have mercy on me.', 'veda-app-ai-draft', true),
('ramayana-2-10-41', 'en', 'The lord of the earth, lamenting like one without protector, seized by the woman and overwhelmed, fell towards the queen''s outstretched feet but could not reach them, like a sick man.', 'veda-app-ai-draft', true),
('ramayana-2-11-1', 'en', 'The great king lay there, as undeserving of it as Yayati fallen from heaven when his merit ran out.', 'veda-app-ai-draft', true),
('ramayana-2-11-2', 'en', 'The woman, harm in human form, her purpose won, fearless and fearsome, pressed him again about the boon.', 'veda-app-ai-draft', true),
('ramayana-2-11-3', 'en', 'You boast, great king, that you are truthful and firm in your vows. Why then do you want to withhold this boon of mine?', 'veda-app-ai-draft', true),
('ramayana-2-11-4', 'en', 'Thus addressed by Kaikeyi, King Dasharatha, angry and reeling for a moment, replied:', 'veda-app-ai-draft', true),
('ramayana-2-11-5', 'en', 'When I am dead and Rama, best of men, has gone to the forest, then rejoice, ignoble woman, my enemy, that Rama is banished.', 'veda-app-ai-draft', true),
('ramayana-2-11-6', 'en', 'If I say this is true, it will be false; matchless infamy and certainly contempt will be mine in the world.', 'veda-app-ai-draft', true),
('ramayana-2-11-7', 'en', 'As he lamented, his mind reeling, the sun set and night came on.', 'veda-app-ai-draft', true),
('ramayana-2-11-8', 'en', 'For the king lamenting in pain, that night of three watches, adorned with the moon''s disc, did not shine.', 'veda-app-ai-draft', true),
('ramayana-2-11-9', 'en', 'Sighing hot breaths, old King Dasharatha lamented his sorrow like one in agony, gazing at the sky.', 'veda-app-ai-draft', true),
('ramayana-2-11-10', 'en', 'Night, I do not want you to turn to dawn; see, I join my hands to you. Or pass quickly, for I do not want to see pitiless, cruel Kaikeyi, who has caused this great disaster.', 'veda-app-ai-draft', true),
('ramayana-2-11-11', 'en', 'Having said this, the king, hands joined, again tried to win Kaikeyi over and said:', 'veda-app-ai-draft', true),
('ramayana-2-11-12', 'en', 'Show mercy, queen, good lady, to a king of good conduct, wretched, devoted to you, whose life is over.', 'veda-app-ai-draft', true),
('ramayana-2-11-13', 'en', 'Surely I said this without thinking, lovely one. Show me grace, child, for you have a heart.', 'veda-app-ai-draft', true),
('ramayana-2-11-14', 'en', 'Hearing the strange, pitiful lament of her pure-hearted husband, his eyes red and full of tears, the cruel, ill-intentioned woman did not do as he asked.', 'veda-app-ai-draft', true),
('ramayana-2-11-15', 'en', 'Then the king, seeing his beloved unappeased and speaking against him about his son''s exile, fainted again and fell senseless to the ground in grief.', 'veda-app-ai-draft', true),
('ramayana-2-12-1', 'en', 'Seeing the Ikshvaku king fallen senseless on the ground, tormented by grief for his son and writhing, the wicked woman said:', 'veda-app-ai-draft', true),
('ramayana-2-12-2', 'en', 'Having made me a promise, why do you lie on the ground as if you had done wrong? You should keep to your word.', 'veda-app-ai-draft', true),
('ramayana-2-12-3', 'en', 'Those who know dharma say truth is the highest dharma. Relying on truth, I am urging you towards dharma.', 'veda-app-ai-draft', true),
('ramayana-2-12-4', 'en', 'King Shaibya, having promised, gave his own body to a hawk to save a bird, O king, and reached the highest state.', 'veda-app-ai-draft', true),
('ramayana-2-12-5', 'en', 'So too radiant Alarka, when a brahmin learned in the Vedas asked, tore out his own eyes and gave them without regret.', 'veda-app-ai-draft', true),
('ramayana-2-12-6', 'en', 'The ocean, lord of rivers, keeping to truth, does not cross its small boundary, its shore, at the appointed time.', 'veda-app-ai-draft', true),
('ramayana-2-12-7', 'en', 'If you do not keep this agreement with me, noble one, I will give up my life before your eyes, abandoned by you.', 'veda-app-ai-draft', true),
('ramayana-2-12-8', 'en', 'Thus urged by fearless Kaikeyi, the king could not loosen the noose, as Bali could not escape the noose made by Indra.', 'veda-app-ai-draft', true),
('ramayana-2-12-9', 'en', 'His heart reeling, his face pale, he was like a draught ox struggling between the yoke and the wheel.', 'veda-app-ai-draft', true),
('ramayana-2-12-10', 'en', 'With dazed eyes, as if blind, the king, steadying himself with difficulty, said to Kaikeyi:', 'veda-app-ai-draft', true),
('ramayana-2-12-11', 'en', 'Your hand that I took before the fire with mantras, wicked woman, I renounce, and with it your son born of me.', 'veda-app-ai-draft', true),
('ramayana-2-12-12', 'en', 'Then Kaikeyi, of evil conduct, clever with words and blinded by anger, spoke harshly to the king again:', 'veda-app-ai-draft', true),
('ramayana-2-12-13', 'en', 'What is this, king, speaking words like poison? You should have your son Rama brought here without fuss.', 'veda-app-ai-draft', true),
('ramayana-2-12-14', 'en', 'Once you have set my son on the throne, made Rama a forest-dweller and freed me of rivals, you will have done your duty.', 'veda-app-ai-draft', true),
('ramayana-2-12-15', 'en', 'Like a fine horse goaded by a sharp spur, the king, urged again and again, said to Kaikeyi:', 'veda-app-ai-draft', true),
('ramayana-2-12-16', 'en', 'I am bound by the bond of dharma and my mind is lost. I want to see my dear, righteous eldest son Rama.', 'veda-app-ai-draft', true),
('ramayana-2-12-17', 'en', 'Hearing the king''s words, Kaikeyi herself immediately told the charioteer: Go and bring Rama.', 'veda-app-ai-draft', true),
('ramayana-2-12-18', 'en', 'Then the glorious, righteous king, his joy in his son gone, his eyes red with grief, looked up at the charioteer and spoke.', 'veda-app-ai-draft', true),
('ramayana-2-12-19', 'en', 'Sumantra, hearing the pitiful words and seeing the wretched king, moved a little away with folded hands.', 'veda-app-ai-draft', true),
('ramayana-2-12-20', 'en', 'When the king, in his misery, could not speak himself, Kaikeyi, skilled in scheming, answered Sumantra:', 'veda-app-ai-draft', true),
('ramayana-2-12-21', 'en', 'Sumantra, I want to see Rama; quickly bring the handsome one. He, thinking it good news, was glad at heart.', 'veda-app-ai-draft', true),
('ramayana-2-12-22', 'en', 'Sumantra thought, urged on by her: Clearly righteous Rama will come here for the coronation.', 'veda-app-ai-draft', true),
('ramayana-2-12-23', 'en', 'Thinking so, the mighty charioteer went out again with great joy, eager to see Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-12-24', 'en', 'Going out suddenly in front, looking at the kings gathered at the gate, he saw various wealthy citizens who had come and were standing at the door.', 'veda-app-ai-draft', true),
('ramayana-2-13-1', 'en', 'Having spent that night, the brahmins learned in the Vedas came to the court with the royal priests.', 'veda-app-ai-draft', true),
('ramayana-2-13-2', 'en', 'The ministers, army chiefs and leading merchants gathered gladly for Raghava''s coronation.', 'veda-app-ai-draft', true),
('ramayana-2-13-3', 'en', 'When the clear sun had risen and the day of Pushya had come, the best of brahmins had prepared for Rama''s coronation:', 'veda-app-ai-draft', true),
('ramayana-2-13-4', 'en', 'golden water jars, a richly adorned auspicious throne, and a chariot well spread with a shining tiger skin;', 'veda-app-ai-draft', true),
('ramayana-2-13-5', 'en', 'water brought from the holy meeting of the Ganga and Yamuna, and from other holy rivers, pools, wells and lakes;', 'veda-app-ai-draft', true),
('ramayana-2-13-6', 'en', 'from rivers flowing east, flowing upward and flowing sideways, and from all the oceans;', 'veda-app-ai-draft', true),
('ramayana-2-13-7', 'en', 'honey, curd, ghee, parched grain, darbha grass, flowers and milk; gold and silver jars covered with milky leaves, shining with lotuses and full of the finest water;', 'veda-app-ai-draft', true),
('ramayana-2-13-8', 'en', 'a fine white yak-tail fan studded with gems, like a spray of moonbeams, stood ready for Rama;', 'veda-app-ai-draft', true),
('ramayana-2-13-9', 'en', 'and a white umbrella like the moon''s disc, ready, radiant and splendid, set out for the coronation;', 'veda-app-ai-draft', true),
('ramayana-2-13-10', 'en', 'a white bull and a white horse stood ready, and a splendid elephant for riding waited.', 'veda-app-ai-draft', true),
('ramayana-2-13-11', 'en', 'Eight auspicious maidens adorned with jewels, all kinds of instruments, and bards,', 'veda-app-ai-draft', true),
('ramayana-2-13-12', 'en', 'all the things gathered for a coronation in the Ikshvaku kingdom, they brought for the prince''s coronation.', 'veda-app-ai-draft', true),
('ramayana-2-13-13', 'en', 'Gathered there at the king''s command, not seeing the king, they said: Who will announce us to the king?', 'veda-app-ai-draft', true),
('ramayana-2-13-14', 'en', 'We do not see the king, yet the sun has risen and wise Rama''s coronation is ready.', 'veda-app-ai-draft', true),
('ramayana-2-13-15', 'en', 'As they spoke, Sumantra, honoured by the king, said to all those great kings:', 'veda-app-ai-draft', true),
('ramayana-2-13-16', 'en', 'At your word I will ask the king, now awake, about his welfare and why he has not come.', 'veda-app-ai-draft', true),
('ramayana-2-13-17', 'en', 'Saying this, the one versed in old lore went to the door of the inner palace and praised Raghava with blessings full of virtue.', 'veda-app-ai-draft', true),
('ramayana-2-13-18', 'en', 'The blessed night has gone and an auspicious day has come. Wake, tiger among kings, and do what is next.', 'veda-app-ai-draft', true),
('ramayana-2-13-19', 'en', 'Brahmins, army chiefs and merchants have come, O king, and long to see you. Wake, Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-13-20', 'en', 'Waking, the king said to Sumantra, the counsellor praising him:', 'veda-app-ai-draft', true),
('ramayana-2-13-21', 'en', 'I am not asleep. Bring Raghava quickly. So King Dasharatha again instructed the charioteer.', 'veda-app-ai-draft', true),
('ramayana-2-13-22', 'en', 'Hearing the king''s word and honouring it with bowed head, he left the king''s quarters thinking it great good news.', 'veda-app-ai-draft', true),
('ramayana-2-13-23', 'en', 'Reaching the royal road adorned with banners and flags, the charioteer heard people talking about Rama.', 'veda-app-ai-draft', true),
('ramayana-2-13-24', 'en', 'Then Sumantra saw Rama''s lovely palace, bright as Kailasa, shining like Indra''s home,', 'veda-app-ai-draft', true),
('ramayana-2-13-25', 'en', 'closed with great doors, adorned with a hundred terraces, its top crowned with golden images, its arches of gems and coral,', 'veda-app-ai-draft', true),
('ramayana-2-13-26', 'en', 'like a mass of autumn cloud, blazing like a cave of Meru, adorned with great strands of fine garlands.', 'veda-app-ai-draft', true),
('ramayana-2-13-27', 'en', 'Driving his horse-drawn chariot and seeing the royal household crowded with people, the charioteer reached the great, rich palace, and his hair stood on end with joy.', 'veda-app-ai-draft', true),
('ramayana-2-13-28', 'en', 'Unhindered, the charioteer entered that palace, like a mountain-peak cloud, like a great mansion full of the finest rooms, rich in jewels, as a sea monster enters the ocean.', 'veda-app-ai-draft', true),
('ramayana-2-14-1', 'en', 'Passing the crowded gate of the inner apartments, the one versed in old lore reached a secluded courtyard,', 'veda-app-ai-draft', true),
('ramayana-2-14-2', 'en', 'guarded by young men with spears and bows and polished earrings, alert, focused and devoted,', 'veda-app-ai-draft', true),
('ramayana-2-14-3', 'en', 'There at the door he saw old men in ochre robes, well dressed, with canes in hand, attentive guardians of the women''s quarters.', 'veda-app-ai-draft', true),
('ramayana-2-14-4', 'en', 'Seeing him coming and eager to please Rama, they quickly told Rama and his wife.', 'veda-app-ai-draft', true),
('ramayana-2-14-5', 'en', 'Learning the charioteer close to his father had been announced, Raghava, wishing to please, had him brought in.', 'veda-app-ai-draft', true),
('ramayana-2-14-6', 'en', 'The charioteer saw him seated, richly adorned, like Kubera, on a golden couch with a fine cover,', 'veda-app-ai-draft', true),
('ramayana-2-14-7', 'en', 'anointed with pure, fragrant, costly sandal paste the colour of boar''s blood,', 'veda-app-ai-draft', true),
('ramayana-2-14-8', 'en', 'with Sita standing at his side holding a yak-tail fan, like the moon with the star Chitra.', 'veda-app-ai-draft', true),
('ramayana-2-14-9', 'en', 'The bard, knowing the proper forms, bowed humbly to that giver of boons, blazing like the sun with his own radiance.', 'veda-app-ai-draft', true),
('ramayana-2-14-10', 'en', 'With folded hands, having asked after his comfort in leisure, bed and seat, Sumantra, honoured by the king, said to the prince:', 'veda-app-ai-draft', true),
('ramayana-2-14-11', 'en', 'Kausalya is blessed in you. Your father wishes to see you. Go there quickly, where he is with Queen Kaikeyi.', 'veda-app-ai-draft', true),
('ramayana-2-14-12', 'en', 'Thus addressed, the radiant lion among men was delighted, and honouring Sita, said to her:', 'veda-app-ai-draft', true),
('ramayana-2-14-13', 'en', 'Queen, surely the king and queen have met to discuss something about my coronation.', 'veda-app-ai-draft', true),
('ramayana-2-14-14', 'en', 'Seeing his wish, the generous, dark-eyed queen, wanting to please, is surely urging the king on my behalf.', 'veda-app-ai-draft', true),
('ramayana-2-14-15', 'en', 'As the assembly is, so is the messenger who has come. Surely the king will crown me crown prince today.', 'veda-app-ai-draft', true),
('ramayana-2-14-16', 'en', 'I will go quickly and see the king. You stay here at ease with your attendants and enjoy yourself.', 'veda-app-ai-draft', true),
('ramayana-2-14-17', 'en', 'Honoured by her husband, dark-eyed Sita followed him to the door, praying for blessings.', 'veda-app-ai-draft', true),
('ramayana-2-14-18', 'en', 'Seeing all the petitioners, meeting and greeting them, he mounted the fine chariot, bright as fire,', 'veda-app-ai-draft', true),
('ramayana-2-14-19', 'en', 'dazzling the eyes with its golden glow, yoked to the finest horses, like young elephants.', 'veda-app-ai-draft', true),
('ramayana-2-14-20', 'en', 'Like Indra on his swift chariot yoked with bay horses, Raghava, blazing with splendour, set off quickly.', 'veda-app-ai-draft', true),
('ramayana-2-14-21', 'en', 'Making it resound like a thundering cloud in the sky, the glorious one came out of his house like the moon from a great cloud.', 'veda-app-ai-draft', true),
('ramayana-2-14-22', 'en', 'Lakshmana, Raghava''s younger brother, holding umbrella and fan, rode in the chariot behind and guarded his brother.', 'veda-app-ai-draft', true),
('ramayana-2-14-23', 'en', 'Then a tumultuous roar arose from the crowds on every side as he came out.', 'veda-app-ai-draft', true),
('ramayana-2-14-24', 'en', 'Raghava heard the talk of the assembled people and the many joyful things the city''s people said about him.', 'veda-app-ai-draft', true),
('ramayana-2-14-25', 'en', 'Raghava goes today to gain vast fortune by the king''s grace. We will have every wish fulfilled with him to rule us. It is the people''s gain that he will hold this whole kingdom for a long time.', 'veda-app-ai-draft', true),
('ramayana-2-14-26', 'en', 'With neighing horses and elephants, preceded by heralds and bards, honoured by the best musicians and praised, he went like Kubera.', 'veda-app-ai-draft', true),
('ramayana-2-14-27', 'en', 'Rama saw the lovely great road crowded with elephants, chariots and horses, its squares full of people, rich in jewels and stocked with goods.', 'veda-app-ai-draft', true),
('ramayana-2-15-1', 'en', 'Rama in his chariot, his friends delighted, saw the glorious city crowded with all kinds of people.', 'veda-app-ai-draft', true),
('ramayana-2-15-2', 'en', 'Rama went along the royal road, fragrant with aloe incense, lined with white cloud-like houses.', 'veda-app-ai-draft', true),
('ramayana-2-15-3', 'en', 'That fine royal road was splendid and uncrowded, full of all kinds of goods and food, high and low.', 'veda-app-ai-draft', true),
('ramayana-2-15-4', 'en', 'Hearing the many blessings his friends spoke, and honouring all the people as they deserved, he went on.', 'veda-app-ai-draft', true),
('ramayana-2-15-5', 'en', 'Crowned today, follow the path walked by your grandfathers and great-grandfathers and protect it.', 'veda-app-ai-draft', true),
('ramayana-2-15-6', 'en', 'As we were cherished by your father and your forefathers, so we will all live even more happily with Rama as king.', 'veda-app-ai-draft', true),
('ramayana-2-15-7', 'en', 'Enough of food today, enough of anything else, if we can see Rama come out established in the kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-15-8', 'en', 'Nothing will be dearer than this, the coronation of boundlessly radiant Rama to the kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-15-9', 'en', 'Hearing these and other kind words of his friends, honouring him, Rama went along the great road, unmoved.', 'veda-app-ai-draft', true),
('ramayana-2-15-10', 'en', 'No one could draw his mind or eyes away from that best of men, even after Raghava had passed.', 'veda-app-ai-draft', true),
('ramayana-2-15-11', 'en', 'For that righteous one showed compassion to all four classes and to people of every age, so they were all devoted to him.', 'veda-app-ai-draft', true),
('ramayana-2-15-12', 'en', 'Reaching the royal residence, like great Indra''s palace, the prince, blazing with splendour, entered his father''s house.', 'veda-app-ai-draft', true),
('ramayana-2-15-13', 'en', 'Passing through all the courtyards, Dasharatha''s son sent all the people back and entered the private inner apartments.', 'veda-app-ai-draft', true),
('ramayana-2-15-14', 'en', 'When the prince had gone in to his father, all the joyful people waited for him to come out again, as the ocean waits for the moonrise.', 'veda-app-ai-draft', true),
('ramayana-2-16-1', 'en', 'Rama saw his father seated on a fine seat with Kaikeyi, wretched, his mouth dried up.', 'veda-app-ai-draft', true),
('ramayana-2-16-2', 'en', 'He humbly bowed first at his father''s feet, then, very attentively, at Kaikeyi''s feet.', 'veda-app-ai-draft', true),
('ramayana-2-16-3', 'en', 'Saying only Rama, his eyes filled with tears, the miserable king could neither look at him nor speak.', 'veda-app-ai-draft', true),
('ramayana-2-16-4', 'en', 'Seeing the king''s strange and frightening look, Rama too grew afraid, as if he had stepped on a snake.', 'veda-app-ai-draft', true),
('ramayana-2-16-5', 'en', 'The great king, his senses joyless, worn by grief and pain, sighing, his mind troubled and confused,', 'veda-app-ai-draft', true),
('ramayana-2-16-6', 'en', 'like the unshakable wave-garlanded ocean in turmoil, like the sun in eclipse, like a sage who has told a lie,', 'veda-app-ai-draft', true),
('ramayana-2-16-7', 'en', 'Seeing his father''s unthinkable grief, Rama grew more agitated, like the sea at the full moon.', 'veda-app-ai-draft', true),
('ramayana-2-16-8', 'en', 'Rama, devoted to his father''s good, thought: Why does the king not welcome me today?', 'veda-app-ai-draft', true),
('ramayana-2-16-9', 'en', 'Other times, even when angry, father softens on seeing me. Why is he distressed today when he sees me?', 'veda-app-ai-draft', true),
('ramayana-2-16-10', 'en', 'Downcast and pained with grief, his face pale, Rama bowed to Kaikeyi and said:', 'veda-app-ai-draft', true),
('ramayana-2-16-11', 'en', 'Have I unknowingly offended, so that my father is angry? Tell me, and please calm him.', 'veda-app-ai-draft', true),
('ramayana-2-16-12', 'en', 'Pale and wretched, he does not speak to me. Is some bodily or mental pain troubling him? Happiness is always hard to keep.', 'veda-app-ai-draft', true),
('ramayana-2-16-13', 'en', 'Has anything bad happened to handsome Prince Bharata, or mighty Shatrughna, or my mothers?', 'veda-app-ai-draft', true),
('ramayana-2-16-14', 'en', 'If I displease the great king or fail to do my father''s word, I would not wish to live a moment with the king angry.', 'veda-app-ai-draft', true),
('ramayana-2-16-15', 'en', 'How could a man not serve the visible god who is the very root of his birth in this world?', 'veda-app-ai-draft', true),
('ramayana-2-16-16', 'en', 'Did you in pride speak harshly to my father in anger, so that his mind is disturbed?', 'veda-app-ai-draft', true),
('ramayana-2-16-17', 'en', 'Tell me truthfully, queen, as I ask: what has caused this strange change in the king?', 'veda-app-ai-draft', true),
('ramayana-2-16-18', 'en', 'At the king''s word I would fall into fire, drink deadly poison or sink in the ocean, when commanded by my teacher, father, king and well-wisher.', 'veda-app-ai-draft', true),
('ramayana-2-16-19', 'en', 'So tell me, queen, what the king wants. I will do it, I promise. Rama does not speak twice.', 'veda-app-ai-draft', true),
('ramayana-2-16-20', 'en', 'To straightforward, truthful Rama, ignoble Kaikeyi spoke very cruel words:', 'veda-app-ai-draft', true),
('ramayana-2-16-21', 'en', 'Long ago in the war of gods and demons, Raghava, your father gave me two boons when I protected him, wounded with an arrow, in the great battle.', 'veda-app-ai-draft', true),
('ramayana-2-16-22', 'en', 'Now I have asked the king for Bharata''s coronation and for your departure today to the Dandaka forest, Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-16-23', 'en', 'If you want to make your father and yourself true to your promises, best of men, hear what I say.', 'veda-app-ai-draft', true),
('ramayana-2-16-24', 'en', 'Obey your father''s command as he promised: you must go to the forest for nine and five years.', 'veda-app-ai-draft', true),
('ramayana-2-16-25', 'en', 'For seven and seven years, living in the Dandaka forest, give up this coronation and live wearing matted hair and bark.', 'veda-app-ai-draft', true),
('ramayana-2-16-26', 'en', 'Let Bharata rule this earth from the Kosala capital, full of all kinds of jewels, with horses, chariots and elephants.', 'veda-app-ai-draft', true),
('ramayana-2-16-27', 'en', 'Hearing those unwelcome words, like death, the slayer of enemies was not shaken, and said to Kaikeyi:', 'veda-app-ai-draft', true),
('ramayana-2-16-28', 'en', 'So be it. I will go from here to live in the forest, wearing matted hair and bark, keeping the king''s promise.', 'veda-app-ai-draft', true),
('ramayana-2-16-29', 'en', 'But I want to know why the invincible king, tamer of foes, does not welcome me as before.', 'veda-app-ai-draft', true),
('ramayana-2-16-30', 'en', 'Do not be angry, queen; I say it to your face: I will go to the forest in bark and matted hair. Be happy.', 'veda-app-ai-draft', true),
('ramayana-2-16-31', 'en', 'Commanded by my well-wisher, teacher, father, grateful king, what dear thing would I not do with confidence?', 'veda-app-ai-draft', true),
('ramayana-2-16-32', 'en', 'Only one thing burns my heart: that the king did not himself tell me of Bharata''s coronation.', 'veda-app-ai-draft', true),
('ramayana-2-16-33', 'en', 'I would gladly give Sita, the kingdom, my life, what I love and my wealth to my brother Bharata myself, unasked.', 'veda-app-ai-draft', true),
('ramayana-2-16-34', 'en', 'How much more when urged by my father the king himself, keeping his promise and to please you.', 'veda-app-ai-draft', true),
('ramayana-2-16-35', 'en', 'So comfort him. Why does the king shed tears slowly, his eyes fixed on the ground?', 'veda-app-ai-draft', true),
('ramayana-2-16-36', 'en', 'Let messengers go on swift horses by the king''s order to bring Bharata from his uncle''s house today.', 'veda-app-ai-draft', true),
('ramayana-2-16-37', 'en', 'I will go quickly from here to the Dandaka forest, without questioning my father''s word, to live there fourteen years.', 'veda-app-ai-draft', true),
('ramayana-2-16-38', 'en', 'Kaikeyi, delighted at Rama''s words and trusting he would leave, hurried Raghava on.', 'veda-app-ai-draft', true),
('ramayana-2-16-39', 'en', 'So be it; men will go on swift horses to bring Bharata back from his uncle''s house.', 'veda-app-ai-draft', true),
('ramayana-2-16-40', 'en', 'But I do not think delay is right for you, eager as you are. So, Rama, you should go quickly from here to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-16-41', 'en', 'The king does not speak to you himself out of shame; it is nothing more, best of men; let your hurt go.', 'veda-app-ai-draft', true),
('ramayana-2-16-42', 'en', 'Until you leave this city in haste for the forest, Rama, your father will neither bathe nor eat.', 'veda-app-ai-draft', true),
('ramayana-2-16-43', 'en', 'Sighing Ah, shame, how cruel! the king, overwhelmed with grief, fainted on the gold-adorned couch.', 'veda-app-ai-draft', true),
('ramayana-2-16-44', 'en', 'Rama raised the king and, urged on by Kaikeyi like a horse struck with a whip, hurried to leave for the forest.', 'veda-app-ai-draft', true),
('ramayana-2-16-45', 'en', 'Hearing the ignoble woman''s unwelcome, cruel words, Rama, free of distress, said to Kaikeyi:', 'veda-app-ai-draft', true),
('ramayana-2-16-46', 'en', 'I do not wish to live in the world devoted to gain, queen. Know me to be like the sages, devoted only to dharma.', 'veda-app-ai-draft', true),
('ramayana-2-16-47', 'en', 'Whatever I can do to please my revered father, I will do in every way, even giving up my life.', 'veda-app-ai-draft', true),
('ramayana-2-16-48', 'en', 'There is no greater act of dharma than serving one''s father or doing as he says.', 'veda-app-ai-draft', true),
('ramayana-2-16-49', 'en', 'Even without my father telling me, I will live fourteen years in the lonely forest at your word.', 'veda-app-ai-draft', true),
('ramayana-2-16-50', 'en', 'Surely, Kaikeyi, you think I have no virtue, since you spoke to the king, though you have more authority over me.', 'veda-app-ai-draft', true),
('ramayana-2-16-51', 'en', 'As soon as I take leave of my mother and console Sita, I will go today to the great Dandaka forest.', 'veda-app-ai-draft', true),
('ramayana-2-16-52', 'en', 'See that Bharata rules the kingdom and serves our father; that is the eternal dharma.', 'veda-app-ai-draft', true),
('ramayana-2-16-53', 'en', 'Hearing Rama, his father, crushed with sorrow, unable to hold back his tears, wept aloud.', 'veda-app-ai-draft', true),
('ramayana-2-16-54', 'en', 'Bowing at the feet of his unconscious father and of ignoble Kaikeyi, radiant Rama went out.', 'veda-app-ai-draft', true),
('ramayana-2-16-55', 'en', 'Walking respectfully round his father and Kaikeyi and leaving the inner palace, Rama saw his friends.', 'veda-app-ai-draft', true),
('ramayana-2-16-56', 'en', 'Lakshmana, the joy of Sumitra, his eyes full of tears and furious, followed behind him.', 'veda-app-ai-draft', true),
('ramayana-2-16-57', 'en', 'Walking respectfully round the coronation vessels, Rama went slowly, without turning his gaze to them.', 'veda-app-ai-draft', true),
('ramayana-2-16-58', 'en', 'The loss of the kingdom did not diminish his great splendour, as night does not diminish the loveliness of the moon.', 'veda-app-ai-draft', true),
('ramayana-2-16-59', 'en', 'As he set out for the forest and gave up the earth, no change of mind was seen in him, as in one beyond all worlds.', 'veda-app-ai-draft', true),
('ramayana-2-16-60', 'en', 'Holding his sorrow in his mind and restraining his senses, the self-possessed one entered his mother''s house, bearer of bad news.', 'veda-app-ai-draft', true),
('ramayana-2-16-61', 'en', 'Entering the house full of joy and seeing her about to face disaster, Rama showed no change, fearing for his loved ones'' distress.', 'veda-app-ai-draft', true),
('ramayana-2-17-1', 'en', 'Rama, deeply weary, sighing like an elephant, self-controlled, went with his brother to his mother''s apartments.', 'veda-app-ai-draft', true),
('ramayana-2-17-2', 'en', 'There he saw an old, highly honoured man sitting at the house door and many others standing.', 'veda-app-ai-draft', true),
('ramayana-2-17-3', 'en', 'Entering the first courtyard, in the second he saw old brahmins learned in the Vedas, honoured by the king.', 'veda-app-ai-draft', true),
('ramayana-2-17-4', 'en', 'Bowing to those elders, in the third he saw women old and young intent on guarding the door.', 'veda-app-ai-draft', true),
('ramayana-2-17-5', 'en', 'Greeting him gladly, the women went in and quickly told Rama''s mother the good news.', 'veda-app-ai-draft', true),
('ramayana-2-17-6', 'en', 'Queen Kausalya had spent the night in devotion, and at dawn was worshipping Vishnu for her son''s good.', 'veda-app-ai-draft', true),
('ramayana-2-17-7', 'en', 'Dressed in linen, joyful, ever devoted to vows, having done the blessings, she was offering into the fire with mantras.', 'veda-app-ai-draft', true),
('ramayana-2-17-8', 'en', 'Entering his mother''s lovely apartments, Rama saw her making offerings into the fire.', 'veda-app-ai-draft', true),
('ramayana-2-17-9', 'en', 'Seeing after a long while her son, his mother''s joy, she ran to him delighted, like a mare to her foal.', 'veda-app-ai-draft', true),
('ramayana-2-17-10', 'en', 'Out of love for her son, Kausalya spoke these loving words to invincible Raghava, her own son:', 'veda-app-ai-draft', true),
('ramayana-2-17-11', 'en', 'May you gain the long life, fame and dharma of the old, righteous royal sages of our family.', 'veda-app-ai-draft', true),
('ramayana-2-17-12', 'en', 'See your father the king, true to his word, Raghava; today the righteous one will crown you crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-17-13', 'en', 'Raghava, stretching out his joined hands a little, spoke to his mother, humble by nature and bowing in respect.', 'veda-app-ai-draft', true),
('ramayana-2-17-14', 'en', 'Queen, surely you do not know a great danger has come, which will grieve you, Vaidehi and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-17-15', 'en', 'I will live fourteen years in the lonely forest, living on honey, roots and fruits, giving up meat like a sage.', 'veda-app-ai-draft', true),
('ramayana-2-17-16', 'en', 'The great king is giving the crown princeship to Bharata and banishing me to the Dandaka forest as an ascetic.', 'veda-app-ai-draft', true),
('ramayana-2-17-17', 'en', 'Seeing his mother, unused to sorrow, fall senseless like a felled plantain tree, Rama lifted her up.', 'veda-app-ai-draft', true),
('ramayana-2-17-18', 'en', 'He stroked with his hand his miserable mother, her whole body covered in dust, risen like a weary mare.', 'veda-app-ai-draft', true),
('ramayana-2-17-19', 'en', 'Used to happiness and now stricken with sorrow, she spoke to the tiger among men seated beside her, with Lakshmana listening:', 'veda-app-ai-draft', true),
('ramayana-2-17-20', 'en', 'If you had not been born, son, to cause me grief, Raghava, I would not, childless, see sorrow greater than this.', 'veda-app-ai-draft', true),
('ramayana-2-17-21', 'en', 'A childless woman has only one sorrow, the grief of being childless; there is no other, son.', 'veda-app-ai-draft', true),
('ramayana-2-17-22', 'en', 'I have never known good fortune or happiness through my husband''s power; I hoped I would see it through my son, Rama.', 'veda-app-ai-draft', true),
('ramayana-2-17-23', 'en', 'I, the senior, will hear many unkind, heart-breaking words from my junior co-wives. What could be more painful for a woman?', 'veda-app-ai-draft', true),
('ramayana-2-17-24', 'en', 'Even with you near, I was slighted like this. How much more when you are gone, dear; surely death is all that awaits me.', 'veda-app-ai-draft', true),
('ramayana-2-17-25', 'en', 'Anyone who served or followed me, seeing Kaikeyi''s son, will no longer speak to me.', 'veda-app-ai-draft', true),
('ramayana-2-17-26', 'en', 'Seventeen years have passed since you were born, Raghava, while I waited for my sorrows to end.', 'veda-app-ai-draft', true),
('ramayana-2-17-27', 'en', 'With fasts, devotions and many hardships I raised you, wretched as I am, and all in vain, to sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-17-28', 'en', 'I think my heart must be hard, since it does not break, like a riverbank in the rains when struck by new floods.', 'veda-app-ai-draft', true),
('ramayana-2-17-29', 'en', 'Surely there is no death for me, no room for me in Yama''s realm, since Death does not seize me today, as a lion seizes a weeping doe.', 'veda-app-ai-draft', true),
('ramayana-2-17-30', 'en', 'Surely my heart is of iron, since it does not split or break on the ground; surely there is no untimely death, though my body is given over to this grief.', 'veda-app-ai-draft', true),
('ramayana-2-17-31', 'en', 'This is the pain: my vows, gifts and self-restraint, and the austerity I practised for a child, have all been fruitless, like seed sown in barren soil.', 'veda-app-ai-draft', true),
('ramayana-2-17-32', 'en', 'If one crushed by heavy sorrow could die at will before one''s time, I would go today to the assembly of the dead without you, like a cow without her calf.', 'veda-app-ai-draft', true),
('ramayana-2-17-33', 'en', 'Seeing Raghava and foreseeing the great disaster, she lamented long in deep distress, like a kinnari seeing her son bound.', 'veda-app-ai-draft', true),
('ramayana-2-18-1', 'en', 'As Kausalya, Rama''s mother, lamented, downcast Lakshmana spoke words fitting the moment:', 'veda-app-ai-draft', true),
('ramayana-2-18-2', 'en', 'I too do not like this, noble lady, that Raghava should give up royal fortune and go to the forest because of a woman''s words.', 'veda-app-ai-draft', true),
('ramayana-2-18-3', 'en', 'The king is perverse, old and overcome by the senses; urged on and ruled by desire, what would he not say?', 'veda-app-ai-draft', true),
('ramayana-2-18-4', 'en', 'I see no offence or fault in Rama for which he should be banished from the kingdom to live in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-18-5', 'en', 'I see no man in the world, even behind his back, not even an enemy or one he has punished, who could name a fault in him.', 'veda-app-ai-draft', true),
('ramayana-2-18-6', 'en', 'Who that respects dharma would cast off without cause a god-like son, honest, self-controlled and kind even to enemies?', 'veda-app-ai-draft', true),
('ramayana-2-18-7', 'en', 'What son, remembering how kings should act, would take to heart these words of a king fallen back into childishness?', 'veda-app-ai-draft', true),
('ramayana-2-18-8', 'en', 'Before anyone knows of this, take power into your own hands with me.', 'veda-app-ai-draft', true),
('ramayana-2-18-9', 'en', 'With me at your side, bow in hand, guarding you, Raghava, who could prevail against you, standing like death itself?', 'veda-app-ai-draft', true),
('ramayana-2-18-10', 'en', 'I will empty all Ayodhya of people with my sharp arrows, bull among men, if it stands against you.', 'veda-app-ai-draft', true),
('ramayana-2-18-11', 'en', 'Bharata''s partisans or anyone who wishes him well, I will kill them all, for the gentle are trampled on.', 'veda-app-ai-draft', true),
('ramayana-2-18-12', 'en', 'When you and I have made the greatest enmity, who would have the power to give the kingdom to Bharata, tamer of foes?', 'veda-app-ai-draft', true),
('ramayana-2-18-13', 'en', 'I am devoted to my brother with all my heart, queen, truly; I swear by truth, my bow, my gifts and sacrifices.', 'veda-app-ai-draft', true),
('ramayana-2-18-14', 'en', 'If Rama enters blazing fire or the forest, know, queen, that I will have entered it before him.', 'veda-app-ai-draft', true),
('ramayana-2-18-15', 'en', 'With my strength I will take away your sorrow, as the rising sun removes darkness. Let the queen see my strength, and let Raghava see it.', 'veda-app-ai-draft', true),
('ramayana-2-18-16', 'en', 'Hearing great Lakshmana, Kausalya, weeping and absorbed in grief, said to Rama:', 'veda-app-ai-draft', true),
('ramayana-2-18-17', 'en', 'You have heard what your brother Lakshmana said, son. Do what follows, if you agree.', 'veda-app-ai-draft', true),
('ramayana-2-18-18', 'en', 'Having heard my co-wife''s unjust words, you should not leave me here burning with grief.', 'veda-app-ai-draft', true),
('ramayana-2-18-19', 'en', 'Knower of dharma, if you wish to practise dharma, stay here and serve me; practise the highest dharma.', 'veda-app-ai-draft', true),
('ramayana-2-18-20', 'en', 'Kashyapa, living self-controlled at home serving his mother, with the highest austerity, went to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-18-21', 'en', 'As the king is to be honoured by you, so am I. I do not permit you; you must not go from here to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-18-22', 'en', 'Separated from you, I want neither life nor happiness. With you, even eating grass is good for me.', 'veda-app-ai-draft', true),
('ramayana-2-18-23', 'en', 'If you go to the forest leaving me grieving, I will fast to death here, for I cannot live.', 'veda-app-ai-draft', true),
('ramayana-2-18-24', 'en', 'Then, son, you will go to a hell known to the world, like the ocean, lord of rivers, for the sin of killing a brahmin.', 'veda-app-ai-draft', true),
('ramayana-2-18-25', 'en', 'To his mother Kausalya, lamenting so wretchedly, righteous Rama spoke words full of dharma:', 'veda-app-ai-draft', true),
('ramayana-2-18-26', 'en', 'I have no power to go against my father''s word. I bow my head to you; I wish to go to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-18-27', 'en', 'The wise sage Kandu, keeping a vow and knowing dharma, killed a cow doing his father''s word.', 'veda-app-ai-draft', true),
('ramayana-2-18-28', 'en', 'And in our own family long ago, the sons of Sagara, digging the earth at their father''s command, met great destruction.', 'veda-app-ai-draft', true),
('ramayana-2-18-29', 'en', 'Rama son of Jamadagni himself cut down his mother Renuka with an axe in the forest, doing his father''s word.', 'veda-app-ai-draft', true),
('ramayana-2-18-30', 'en', 'I am not the only one to follow a father''s command; I follow the path desired and walked by those before.', 'veda-app-ai-draft', true),
('ramayana-2-18-31', 'en', 'This must be done by me on earth, not otherwise. No one is lessened by doing his father''s word.', 'veda-app-ai-draft', true),
('ramayana-2-18-32', 'en', 'Having said this to his mother, he spoke again to Lakshmana: Lakshmana, I know your matchless love for me, but you do not understand the meaning of truth and calm.', 'veda-app-ai-draft', true),
('ramayana-2-18-33', 'en', 'Dharma is supreme in the world, and truth rests on dharma. Our father''s word, the highest, rests on dharma.', 'veda-app-ai-draft', true),
('ramayana-2-18-34', 'en', 'Having heard the word of a father, mother or brahmin, one who stands in dharma must not make it vain, hero.', 'veda-app-ai-draft', true),
('ramayana-2-18-35', 'en', 'So I cannot go against my father''s command; it is by my father''s word that Kaikeyi urged me.', 'veda-app-ai-draft', true),
('ramayana-2-18-36', 'en', 'So give up this ignoble thought based on warrior force. Hold to dharma, not harshness; follow my way of thinking.', 'veda-app-ai-draft', true),
('ramayana-2-18-37', 'en', 'Having spoken so lovingly to his brother, Lakshmana''s elder spoke again to Kausalya, folding his hands and bowing his head.', 'veda-app-ai-draft', true),
('ramayana-2-18-38', 'en', 'Give me leave, queen, as I go from here to the forest. I beg you by my life, perform blessings for my journey. Having fulfilled my promise, I will return from the forest to the city.', 'veda-app-ai-draft', true),
('ramayana-2-18-39', 'en', 'I cannot set aside great glory merely for a kingdom. Life is short, queen; I will not choose this paltry earth today through adharma.', 'veda-app-ai-draft', true),
('ramayana-2-18-40', 'en', 'So the bull among men, set on going to Dandaka, sought to win his mother over, firmly instructed his younger brother, and in his heart walked respectfully round his mother.', 'veda-app-ai-draft', true),
('ramayana-2-19-1', 'en', 'Then, approaching Saumitri, distressed and especially resentful, sighing like a great serpent, his eyes wide with anger,', 'veda-app-ai-draft', true),
('ramayana-2-19-2', 'en', 'Rama spoke to his dear brother and friend, holding his own strength steady with courage:', 'veda-app-ai-draft', true),
('ramayana-2-19-3', 'en', 'Saumitri, let the energy spent on preparing for my coronation now go into stopping it.', 'veda-app-ai-draft', true),
('ramayana-2-19-4', 'en', 'Make sure that our mother, whose mind is troubled about my coronation, is not left anxious.', 'veda-app-ai-draft', true),
('ramayana-2-19-5', 'en', 'I cannot ignore for even a moment the pain of doubt that has arisen in her mind, Saumitri.', 'veda-app-ai-draft', true),
('ramayana-2-19-6', 'en', 'I do not remember ever doing even the smallest unkindness, knowingly or not, to my mothers or my father.', 'veda-app-ai-draft', true),
('ramayana-2-19-7', 'en', 'Let my father, true, true to his word and always truly valiant, who fears the next world, be free of fear.', 'veda-app-ai-draft', true),
('ramayana-2-19-8', 'en', 'If this work is not stopped, he would grieve that truth was broken, and his grief would grieve me.', 'veda-app-ai-draft', true),
('ramayana-2-19-9', 'en', 'So, Lakshmana, stop the coronation; I wish to go to the forest from here right after.', 'veda-app-ai-draft', true),
('ramayana-2-19-10', 'en', 'With my departure today, the princess will be satisfied and will then crown her son Bharata without worry.', 'veda-app-ai-draft', true),
('ramayana-2-19-11', 'en', 'When I have gone to the forest in bark and deerskin with matted hair, Kaikeyi will be content.', 'veda-app-ai-draft', true),
('ramayana-2-19-12', 'en', 'I should not trouble the one by whom this plan was devised and the mind made firm. I will leave without delay.', 'veda-app-ai-draft', true),
('ramayana-2-19-13', 'en', 'Fate alone must be seen in my exile, Saumitri, and in the return of the kingdom once given.', 'veda-app-ai-draft', true),
('ramayana-2-19-14', 'en', 'How else could Kaikeyi decide to hurt me, if this were not fate''s doing?', 'veda-app-ai-draft', true),
('ramayana-2-19-15', 'en', 'You know, gentle one, that I never made a difference between my mothers, nor did she between me and her son.', 'veda-app-ai-draft', true),
('ramayana-2-19-16', 'en', 'I can see nothing but fate in her harsh words about stopping the coronation and banishing me.', 'veda-app-ai-draft', true),
('ramayana-2-19-17', 'en', 'How could a princess of such nature and virtue speak like a common woman to hurt me before her husband?', 'veda-app-ai-draft', true),
('ramayana-2-19-18', 'en', 'What is beyond thought is fate, which even beings cannot escape; clearly a reversal has fallen on me and on her.', 'veda-app-ai-draft', true),
('ramayana-2-19-19', 'en', 'What man can fight fate, Saumitri, whose grip is seen only through its results?', 'veda-app-ai-draft', true),
('ramayana-2-19-20', 'en', 'Pleasure and pain, fear and anger, gain and loss, birth and death: whatever happens so is surely fate''s work.', 'veda-app-ai-draft', true),
('ramayana-2-19-21', 'en', 'Though my coronation is stopped, I feel no distress. So you too, free of distress, following me, quickly stop the coronation rites.', 'veda-app-ai-draft', true),
('ramayana-2-19-22', 'en', 'Lakshmana, do not blame our younger mother for this obstacle to my kingship. People driven by fate say unwelcome things; you know how powerful fate is.', 'veda-app-ai-draft', true),
('ramayana-2-20-1', 'en', 'As Rama spoke, Lakshmana, with head bowed, listening, seemed to stand between sorrow and joy.', 'veda-app-ai-draft', true),
('ramayana-2-20-2', 'en', 'Then, knitting his brows, the bull among men hissed like an angry great snake in its hole.', 'veda-app-ai-draft', true),
('ramayana-2-20-3', 'en', 'His frowning face, hard to look at, was like the face of an angry lion.', 'veda-app-ai-draft', true),
('ramayana-2-20-4', 'en', 'Swinging his arm as an elephant swings its trunk, and tossing his neck this way and that,', 'veda-app-ai-draft', true),
('ramayana-2-20-5', 'en', 'looking sideways at his brother from the corner of his eye, he said: This great agitation of yours is misplaced.', 'veda-app-ai-draft', true),
('ramayana-2-20-6', 'en', 'Out of fear of breaking dharma and of the people''s blame, how can one like you say this so calmly?', 'veda-app-ai-draft', true),
('ramayana-2-20-7', 'en', 'You, a bold bull among warriors, how can you praise weak, powerless fate?', 'veda-app-ai-draft', true),
('ramayana-2-20-8', 'en', 'How can you not suspect those two wicked ones? There are smooth deceptions dressed as dharma; righteous one, do you not see?', 'veda-app-ai-draft', true),
('ramayana-2-20-9', 'en', 'Crowning someone other than you is hateful to the world; that dharma by which your mind is divided and confused, I hate.', 'veda-app-ai-draft', true),
('ramayana-2-20-10', 'en', 'Even if this is their plan and fate''s doing, you should not accept it; I do not like it.', 'veda-app-ai-draft', true),
('ramayana-2-20-11', 'en', 'The weak and timid follow fate; heroes who respect themselves do not bow to fate.', 'veda-app-ai-draft', true),
('ramayana-2-20-12', 'en', 'The man who can push back fate by human effort does not sink when fate harms his purpose.', 'veda-app-ai-draft', true),
('ramayana-2-20-13', 'en', 'Today they will see the power of fate and the power of man; today the difference between fate and man will be clear.', 'veda-app-ai-draft', true),
('ramayana-2-20-14', 'en', 'Today people will see fate struck down by my effort, just as they saw your coronation struck down by fate.', 'veda-app-ai-draft', true),
('ramayana-2-20-15', 'en', 'Like a rampaging elephant in rut, ignoring the goad, I will turn back charging fate by my effort.', 'veda-app-ai-draft', true),
('ramayana-2-20-16', 'en', 'Not all the world''s guardians, nor all three worlds, could stop Rama''s coronation today, let alone our father.', 'veda-app-ai-draft', true),
('ramayana-2-20-17', 'en', 'Those who agreed between them on your exile, O king, will themselves live in the forest for fourteen years.', 'veda-app-ai-draft', true),
('ramayana-2-20-18', 'en', 'I will cut off the hope of our father and of her who works against your coronation for her son''s kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-20-19', 'en', 'The power of fate will not stand against my strength as much as my fierce effort will bring them grief.', 'veda-app-ai-draft', true),
('ramayana-2-20-20', 'en', 'After a thousand years, when you have gone to the forest, your noble sons will rule the people in turn.', 'veda-app-ai-draft', true),
('ramayana-2-20-21', 'en', 'Living in the forest is ordained by the custom of the old royal sages, after handing the people over to their sons to protect like children.', 'veda-app-ai-draft', true),
('ramayana-2-20-22', 'en', 'If, righteous Rama, you do not want the kingdom for yourself, fearing the king is confused and the kingdom unsettled,', 'veda-app-ai-draft', true),
('ramayana-2-20-23', 'en', 'I promise you, hero, or may I not reach the heroes'' world: I will guard your kingdom as the shore guards the sea.', 'veda-app-ai-draft', true),
('ramayana-2-20-24', 'en', 'Be crowned with blessings and busy yourself with that. I alone am enough to hold back the kings by force.', 'veda-app-ai-draft', true),
('ramayana-2-20-25', 'en', 'These arms are not for show, nor my bow for decoration; my sword is not for wearing, nor my arrows for idle holding.', 'veda-app-ai-draft', true),
('ramayana-2-20-26', 'en', 'All four are for subduing enemies. I do not much want for whoever I count as an enemy.', 'veda-app-ai-draft', true),
('ramayana-2-20-27', 'en', 'With a sharp-edged sword flashing like lightning in my hand, I would not count an enemy, even Indra with his thunderbolt.', 'veda-app-ai-draft', true),
('ramayana-2-20-28', 'en', 'The earth will be thick and hard to cross with elephants, horses, men, hands, thighs and heads crushed by my sword.', 'veda-app-ai-draft', true),
('ramayana-2-20-29', 'en', 'Struck by my sword''s edge today, elephants will fall to the ground like blazing mountains, like clouds with lightning.', 'veda-app-ai-draft', true),
('ramayana-2-20-30', 'en', 'With my lizard-skin finger guard on and my bow in hand, how could any man think himself a man with me standing here?', 'veda-app-ai-draft', true),
('ramayana-2-20-31', 'en', 'Shooting many arrows at one and one at many, I will send my arrows into the vital points of men, horses and elephants.', 'veda-app-ai-draft', true),
('ramayana-2-20-32', 'en', 'Today the power of my weapons will prevail, to make the king powerless and make you lord, my lord.', 'veda-app-ai-draft', true),
('ramayana-2-20-33', 'en', 'Today these arms, fit for sandal paste, armlets, giving wealth and protecting friends,', 'veda-app-ai-draft', true),
('ramayana-2-20-34', 'en', 'will do their work, Rama, in stopping those who are blocking your coronation.', 'veda-app-ai-draft', true),
('ramayana-2-20-35', 'en', 'Tell me which enemy of yours I should part today from life, fame and friends. Command me how this earth may be in your power; I am your servant.', 'veda-app-ai-draft', true),
('ramayana-2-20-36', 'en', 'Wiping away his tears and comforting Lakshmana again and again, the one who prospered the Raghu line, firm in his father''s word, said: Understand me, gentle one; this is the good path.', 'veda-app-ai-draft', true),
('ramayana-2-21-1', 'en', 'Seeing him intent on keeping his father''s command, Kausalya, choked with tears, spoke words full of dharma:', 'veda-app-ai-draft', true),
('ramayana-2-21-2', 'en', 'How will he, righteous, who has never known sorrow, kind-spoken to all, born of me and Dasharatha, live by gleaning?', 'veda-app-ai-draft', true),
('ramayana-2-21-3', 'en', 'How will he, whose servants and slaves eat fine food, eat roots and fruits in the forest?', 'veda-app-ai-draft', true),
('ramayana-2-21-4', 'en', 'Who would believe this, hearing it, or who would not be afraid, that virtuous Raghava, dear to the king, is banished?', 'veda-app-ai-draft', true),
('ramayana-2-21-5', 'en', 'Without you here, a great, matchless fire of grief will burn me as fire burns dry brush at the end of winter.', 'veda-app-ai-draft', true),
('ramayana-2-21-6', 'en', 'How could a cow not follow her calf as it goes? I will follow you wherever you go, son.', 'veda-app-ai-draft', true),
('ramayana-2-21-7', 'en', 'Hearing his mother speak so, Rama, bull among men, said to his deeply grieving mother:', 'veda-app-ai-draft', true),
('ramayana-2-21-8', 'en', 'The king has been deceived by Kaikeyi; with me gone to the forest and abandoned by you too, he surely will not survive.', 'veda-app-ai-draft', true),
('ramayana-2-21-9', 'en', 'A woman abandoning her husband is simply cruel; you should not do it, nor even think of it, for it is condemned.', 'veda-app-ai-draft', true),
('ramayana-2-21-10', 'en', 'As long as my father, the Kakutstha lord of the earth, lives, serve him, for that is eternal dharma.', 'veda-app-ai-draft', true),
('ramayana-2-21-11', 'en', 'Thus told by Rama, lovely Kausalya, well pleased, said to Rama, who acted without strain, So be it.', 'veda-app-ai-draft', true),
('ramayana-2-21-12', 'en', 'Thus answered, Rama, best of upholders of dharma, spoke again to his deeply grieving mother:', 'veda-app-ai-draft', true),
('ramayana-2-21-13', 'en', 'You and I must both do father''s word: the king is husband, teacher, best, lord and master of all.', 'veda-app-ai-draft', true),
('ramayana-2-21-14', 'en', 'After roaming the great forest for nine and five years, I will gladly stand by your word.', 'veda-app-ai-draft', true),
('ramayana-2-21-15', 'en', 'Thus addressed, Kausalya, loving her son, her face streaming with tears, said in deep pain to her dear son:', 'veda-app-ai-draft', true),
('ramayana-2-21-16', 'en', 'Rama, I cannot live among these co-wives. Take me too, Kakutstha, to the forest like a forest doe, if you have decided to go out of regard for your father.', 'veda-app-ai-draft', true),
('ramayana-2-21-17', 'en', 'Weeping himself, Rama said to her as she wept: For a living woman her husband is her god and lord; today the king is lord over you and me.', 'veda-app-ai-draft', true),
('ramayana-2-21-18', 'en', 'And righteous Bharata, kind-spoken to all beings, will respect you, for he always delights in dharma.', 'veda-app-ai-draft', true),
('ramayana-2-21-19', 'en', 'See to it carefully that when I have left, the king does not suffer from grief for his son.', 'veda-app-ai-draft', true),
('ramayana-2-21-20', 'en', 'Even the best woman, devoted to vows and fasts, who does not follow her husband, goes the way of the sinful.', 'veda-app-ai-draft', true),
('ramayana-2-21-21', 'en', 'She should serve her husband, devoted to his good. This dharma was seen of old, heard in the Vedas and remembered in tradition.', 'veda-app-ai-draft', true),
('ramayana-2-21-22', 'en', 'For my sake honour the brahmins of good vows, queen. So wait for the time, longing for my return.', 'veda-app-ai-draft', true),
('ramayana-2-21-23', 'en', 'You will gain your highest wish when I return, if the best of upholders of dharma stays alive.', 'veda-app-ai-draft', true),
('ramayana-2-21-24', 'en', 'Thus addressed by Rama, her eyes filled with tears, Kausalya, afflicted by grief for her son, said to Rama: Go, son, with a focused mind; may good fortune always be with you, lord.', 'veda-app-ai-draft', true),
('ramayana-2-21-25', 'en', 'Seeing Rama resolved on living in the forest, the queen, with deep feeling, spoke auspicious words to Rama and wished to perform a blessing for his journey.', 'veda-app-ai-draft', true),
('ramayana-2-22-1', 'en', 'Putting aside her distress and touching pure water, Rama''s high-minded mother performed blessings for him.', 'veda-app-ai-draft', true),
('ramayana-2-22-2', 'en', 'May the Sadhyas, the Vishvedevas, the Maruts and the great sages keep you safe; may Dhatri and Vidhatri, Pushan, Bhaga and Aryaman keep you safe.', 'veda-app-ai-draft', true),
('ramayana-2-22-3', 'en', 'May the seasons, fortnights, months, years, nights, days and moments always keep you safe.', 'veda-app-ai-draft', true),
('ramayana-2-22-4', 'en', 'May memory, steadfastness and dharma guard you on all sides, son; and blessed Skanda, Soma and Brihaspati,', 'veda-app-ai-draft', true),
('ramayana-2-22-5', 'en', 'the Seven Sages and Narada protect you everywhere; and all the stars and planets with their gods, as you, wise one, wander the great forests in a sage''s dress.', 'veda-app-ai-draft', true),
('ramayana-2-22-6', 'en', 'May monkeys, scorpions, gadflies and mosquitoes in the forest, and reptiles and insects, not trouble you in the thickets.', 'veda-app-ai-draft', true),
('ramayana-2-22-7', 'en', 'May great elephants, lions, tigers, fanged bears and fierce horned buffaloes not harm you, my child.', 'veda-app-ai-draft', true),
('ramayana-2-22-8', 'en', 'May fierce man-eaters and other kinds of creatures not hurt you, son, since I have honoured them here.', 'veda-app-ai-draft', true),
('ramayana-2-22-9', 'en', 'May your journeys be safe and your efforts succeed. May all good things be yours, Rama; go safely, my son.', 'veda-app-ai-draft', true),
('ramayana-2-22-10', 'en', 'May you be safe again and again from beings of the sky and the earth, and from all gods and those who oppose you.', 'veda-app-ai-draft', true),
('ramayana-2-22-11', 'en', 'May Brahma, lord of all worlds, the sustainer of beings, the sages and the other gods protect you as you live in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-22-12', 'en', 'So the famous, wide-eyed queen worshipped the hosts of gods with garlands, perfumes and fitting hymns.', 'veda-app-ai-draft', true),
('ramayana-2-22-13', 'en', 'The blessing that came to thousand-eyed Indra, worshipped by all gods, at the slaying of Vritra, may that blessing be yours.', 'veda-app-ai-draft', true),
('ramayana-2-22-14', 'en', 'The blessing Vinata once made for Suparna as he sought the nectar, may that blessing be yours.', 'veda-app-ai-draft', true),
('ramayana-2-22-15', 'en', 'Kausalya made a protective amulet of a potent herb that heals wounds, and recited mantras over it.', 'veda-app-ai-draft', true),
('ramayana-2-22-16', 'en', 'Bending, smelling his head and embracing him, the famous queen said: Go, Rama, as you please, your purpose achieved.', 'veda-app-ai-draft', true),
('ramayana-2-22-17', 'en', 'May I see you return to Ayodhya, healthy and with every purpose achieved, happy and settled in the royal palace, my child.', 'veda-app-ai-draft', true),
('ramayana-2-22-18', 'en', 'The hosts of gods led by Shiva, the great sages, spirits, great asuras and serpents, whom I have worshipped, and the directions, may they wish you well as you go to the forest for so long, Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-22-19', 'en', 'Her eyes full of tears, having completed the blessing as prescribed, she walked respectfully round Raghava and embraced him tightly again and again.', 'veda-app-ai-draft', true),
('ramayana-2-22-20', 'en', 'When the queen had walked round him, he pressed his mother''s feet again and again and, blazing with his own splendour, the famous Raghava went to Sita''s house.', 'veda-app-ai-draft', true),
('ramayana-2-23-1', 'en', 'Bowing to Kausalya, with his mother''s blessing, Rama set out for the forest, standing on the path of dharma.', 'veda-app-ai-draft', true),
('ramayana-2-23-2', 'en', 'The prince lit up the royal road crowded with people, as if churning their hearts with his goodness.', 'veda-app-ai-draft', true),
('ramayana-2-23-3', 'en', 'Devoted Vaidehi had heard none of this; in her heart was only the coronation as crown prince.', 'veda-app-ai-draft', true),
('ramayana-2-23-4', 'en', 'Having worshipped the gods, grateful and glad, knowing the duties of royalty, she waited for the prince.', 'veda-app-ai-draft', true),
('ramayana-2-23-5', 'en', 'Rama entered his own well-decorated house, full of joyful people, his face lowered a little in embarrassment.', 'veda-app-ai-draft', true),
('ramayana-2-23-6', 'en', 'Sita sprang up, trembling, and saw her husband burning with grief, his senses disturbed with worry.', 'veda-app-ai-draft', true),
('ramayana-2-23-7', 'en', 'Seeing his pale, sweating, troubled face, she, tormented by sorrow, said: What is this now, lord?', 'veda-app-ai-draft', true),
('ramayana-2-23-8', 'en', 'Today the glorious Pushya, ruled by Brihaspati, is in conjunction, the wise brahmins say. Why are you troubled, Raghava?', 'veda-app-ai-draft', true),
('ramayana-2-23-9', 'en', 'Your lovely face is not shaded by the hundred-ribbed umbrella, white as water-foam.', 'veda-app-ai-draft', true),
('ramayana-2-23-10', 'en', 'Your lotus-eyed face is not being fanned by the two fine whisks, bright as the moon and swans.', 'veda-app-ai-draft', true),
('ramayana-2-23-11', 'en', 'The eloquent bards and heralds are not seen joyfully praising you today with blessings, bull among men.', 'veda-app-ai-draft', true),
('ramayana-2-23-12', 'en', 'Brahmins learned in the Vedas are not pouring honey and curd on your head as prescribed for one being anointed.', 'veda-app-ai-draft', true),
('ramayana-2-23-13', 'en', 'The ministers, the heads of guilds in their finery, and the people of town and country do not want to follow you.', 'veda-app-ai-draft', true),
('ramayana-2-23-14', 'en', 'Why does the fine Pushya chariot, yoked to four swift horses adorned with gold, not go before you?', 'veda-app-ai-draft', true),
('ramayana-2-23-15', 'en', 'No splendid elephant with auspicious marks, like a dark cloud-mountain, is seen going before you, hero.', 'veda-app-ai-draft', true),
('ramayana-2-23-16', 'en', 'Nor do I see the gold-patterned throne carried before you as you go, handsome one, with heroes in front.', 'veda-app-ai-draft', true),
('ramayana-2-23-17', 'en', 'When the coronation was ready, what is this now? Your face has a colour I have never seen, and no joy shows.', 'veda-app-ai-draft', true),
('ramayana-2-23-18', 'en', 'To her lamenting like this, the joy of the Raghus said: Sita, my revered father is banishing me to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-23-19', 'en', 'Born in a great family, knowing and practising dharma, hear, Janaki, how this has come to me step by step.', 'veda-app-ai-draft', true),
('ramayana-2-23-20', 'en', 'My father, King Dasharatha, true to his word, long ago gladly gave Kaikeyi two great boons.', 'veda-app-ai-draft', true),
('ramayana-2-23-21', 'en', 'Today, when the coronation was ready and the king had prepared it, she claimed that agreement, and he was overcome by dharma.', 'veda-app-ai-draft', true),
('ramayana-2-23-22', 'en', 'I must live fourteen years in Dandaka, and father has appointed Bharata crown prince. So I have come to see you as I leave for the lonely forest.', 'veda-app-ai-draft', true),
('ramayana-2-23-23', 'en', 'Never praise me near Bharata; prosperous men cannot bear praise of others. So do not speak of my virtues before Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-23-24', 'en', 'Do not expect special treatment from him; you can live near him by being agreeable.', 'veda-app-ai-draft', true),
('ramayana-2-23-25', 'en', 'Keeping my father''s promise, I will go to the forest today. Be steadfast, wise one.', 'veda-app-ai-draft', true),
('ramayana-2-23-26', 'en', 'When I have gone to the forest where sages live, blessed and sinless one, you should devote yourself to vows and fasts.', 'veda-app-ai-draft', true),
('ramayana-2-23-27', 'en', 'Rising early and worshipping the gods properly, you should honour my father, King Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-2-23-28', 'en', 'My mother Kausalya, old and worn with sorrow, deserves respect from you, with dharma first.', 'veda-app-ai-draft', true),
('ramayana-2-23-29', 'en', 'You should always honour my other mothers too; in love, affection and care they are all equal to me as mothers.', 'veda-app-ai-draft', true),
('ramayana-2-23-30', 'en', 'You should look on Lakshmana and Shatrughna especially as brothers and sons; they are dearer to me than life.', 'veda-app-ai-draft', true),
('ramayana-2-23-31', 'en', 'Never do anything to displease Bharata; he is now king and lord of the land and the family.', 'veda-app-ai-draft', true),
('ramayana-2-23-32', 'en', 'Kings are pleased when served with good conduct and effort, and angered by the opposite.', 'veda-app-ai-draft', true),
('ramayana-2-23-33', 'en', 'Kings cast off even their own sons who act against them, and embrace capable people even if strangers.', 'veda-app-ai-draft', true),
('ramayana-2-23-34', 'en', 'I will go to the great forest, beloved; you must live right here, lovely one. Do as I say, and give no one cause for offence.', 'veda-app-ai-draft', true),
('ramayana-2-24-1', 'en', 'Thus addressed, Vaidehi, who deserved kindness and spoke kindly, grew angry out of love and said to her husband:', 'veda-app-ai-draft', true),
('ramayana-2-24-2', 'en', 'Noble son, father, mother, brother, son and daughter-in-law each enjoy their own merit and meet their own fortune.', 'veda-app-ai-draft', true),
('ramayana-2-24-3', 'en', 'But a wife alone shares her husband''s fortune, bull among men. So I too am ordered to live in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-24-4', 'en', 'Not father, nor son, nor self, nor mother, nor friends; for women, here and hereafter, the husband alone is always the refuge.', 'veda-app-ai-draft', true),
('ramayana-2-24-5', 'en', 'If you are setting out today for the hard forest, Raghava, I will walk ahead of you, crushing the kusha grass and thorns.', 'veda-app-ai-draft', true),
('ramayana-2-24-6', 'en', 'Casting off jealousy and anger like leftover water, take me with you confidently, hero; there is no sin in me.', 'veda-app-ai-draft', true),
('ramayana-2-24-7', 'en', 'Better than palace tops, flying chariots or travelling through the sky, in every condition, is the shade of a husband''s feet.', 'veda-app-ai-draft', true),
('ramayana-2-24-8', 'en', 'My mother and father have taught me in many ways; I need not be told now how to behave.', 'veda-app-ai-draft', true),
('ramayana-2-24-9', 'en', 'I will live happily in the forest just as in my father''s house, thinking not of the three worlds but of my vow to my husband.', 'veda-app-ai-draft', true),
('ramayana-2-24-10', 'en', 'Always serving you, disciplined and chaste, I will delight with you, hero, in the honey-scented forests.', 'veda-app-ai-draft', true),
('ramayana-2-24-11', 'en', 'You can protect others in the forest, Rama; how much more me, giver of honour.', 'veda-app-ai-draft', true),
('ramayana-2-24-12', 'en', 'I will live on fruits and roots, no doubt; I will cause you no trouble living with you.', 'veda-app-ai-draft', true),
('ramayana-2-24-13', 'en', 'I want to see rivers, mountains, ponds and forests everywhere without fear, with you, my wise protector.', 'veda-app-ai-draft', true),
('ramayana-2-24-14', 'en', 'I would happily see lotus ponds in full bloom, crowded with swans and ducks, together with you, my hero.', 'veda-app-ai-draft', true),
('ramayana-2-24-15', 'en', 'With you I will delight in great joy, wide-eyed one, even for a hundred thousand years with you.', 'veda-app-ai-draft', true),
('ramayana-2-24-16', 'en', 'Even living in heaven, if it were without you, Raghava, tiger among men, I would not want it.', 'veda-app-ai-draft', true),
('ramayana-2-24-17', 'en', 'I will go to the impassable forest full of deer, monkeys and elephants; I will live there as in my father''s house, holding your feet, honoured.', 'veda-app-ai-draft', true),
('ramayana-2-24-18', 'en', 'Devoted to no one else, my heart attached to you, resolved to die if parted from you, take me, grant my request; I will not be a burden to you.', 'veda-app-ai-draft', true),
('ramayana-2-24-19', 'en', 'Though she spoke so, the best of men, devoted to dharma, did not wish to take Sita, and spoke at length to turn her back, grieved at the thought of her living in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-25-1', 'en', 'To Sita speaking like this, righteous Rama, knowing dharma, said this to turn her back:', 'veda-app-ai-draft', true),
('ramayana-2-25-2', 'en', 'Sita, you come of a great family and are always devoted to dharma. Practise your own dharma here; do not follow your heart''s pleasure.', 'veda-app-ai-draft', true),
('ramayana-2-25-3', 'en', 'Sita, do as I tell you, my gentle one; the forest has many dangers. Hear them as I tell them.', 'veda-app-ai-draft', true),
('ramayana-2-25-4', 'en', 'Sita, give up this idea of living in the forest. The wilderness is said to be full of dangers.', 'veda-app-ai-draft', true),
('ramayana-2-25-5', 'en', 'I say this for your good. I know no happiness in the forest; the forest is always sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-25-6', 'en', 'The roars of lions living in mountain caves, echoing from mountain waterfalls, are painful to hear; so the forest is sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-25-7', 'en', 'One sleeps at night on beds of leaves broken by oneself on the ground, worn out with toil; so the forest is more sorrowful.', 'veda-app-ai-draft', true),
('ramayana-2-25-8', 'en', 'One must fast as much as life allows, Maithili, wear a mass of matted hair and dress in bark.', 'veda-app-ai-draft', true),
('ramayana-2-25-9', 'en', 'Fierce wind, darkness and constant hunger, and great dangers: so the forest is more sorrowful.', 'veda-app-ai-draft', true),
('ramayana-2-25-10', 'en', 'Many reptiles of many forms roam the earth boldly, lovely one; so the forest is more sorrowful.', 'veda-app-ai-draft', true),
('ramayana-2-25-11', 'en', 'Snakes living in rivers, moving crookedly like rivers, lie across the path; so the forest is more sorrowful.', 'veda-app-ai-draft', true),
('ramayana-2-25-12', 'en', 'Moths, scorpions, insects, gadflies and mosquitoes always torment one, gentle woman; so the forest is all sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-25-13', 'en', 'Thorny trees, kusha and kasha grasses, and tangled branches fill the forest, lovely one; so the forest is more sorrowful.', 'veda-app-ai-draft', true),
('ramayana-2-25-14', 'en', 'So enough of going to the forest; the forest is not right for you. Thinking it over, I see the forest has many more dangers.', 'veda-app-ai-draft', true),
('ramayana-2-25-15', 'en', 'Great Rama had not resolved to take her to the forest; Sita did not accept his words, and in great sorrow said this to Rama:', 'veda-app-ai-draft', true),
('ramayana-2-26-1', 'en', 'Hearing Rama''s words, Sita, grieved, her face streaming with tears, spoke softly:', 'veda-app-ai-draft', true),
('ramayana-2-26-2', 'en', 'The dangers you named of living in the forest, know them to be blessings, when love comes first.', 'veda-app-ai-draft', true),
('ramayana-2-26-3', 'en', 'I must go with you, by the command of my elders; separated from you, Rama, I must give up my life here.', 'veda-app-ai-draft', true),
('ramayana-2-26-4', 'en', 'With me near you, Raghava, not even Indra, lord of the gods, could overpower me by force.', 'veda-app-ai-draft', true),
('ramayana-2-26-5', 'en', 'A woman without her husband cannot live; you yourself have shown me this, Rama.', 'veda-app-ai-draft', true),
('ramayana-2-26-6', 'en', 'And, wise one, I heard from brahmins long ago in my father''s house that I would truly have to live in a forest.', 'veda-app-ai-draft', true),
('ramayana-2-26-7', 'en', 'Hearing those words at home from brahmins who read signs, I have always been eager to live in the forest, mighty one.', 'veda-app-ai-draft', true),
('ramayana-2-26-8', 'en', 'That command to live in the forest must come to me; so I will go there with you, dear, and not otherwise.', 'veda-app-ai-draft', true),
('ramayana-2-26-9', 'en', 'I will have fulfilled the prophecy; I will go with you. The time has come; let the brahmin''s word be true.', 'veda-app-ai-draft', true),
('ramayana-2-26-10', 'en', 'I know there are many sorrows in forest life, but they surely fall on men whose minds are not disciplined, hero.', 'veda-app-ai-draft', true),
('ramayana-2-26-11', 'en', 'As a girl in my father''s house I heard of forest life from a good-living woman mendicant, before my mother.', 'veda-app-ai-draft', true),
('ramayana-2-26-12', 'en', 'And earlier I begged you many times, lord, wishing to go to live in the forest with you.', 'veda-app-ai-draft', true),
('ramayana-2-26-13', 'en', 'I have been waiting for this chance, Raghava, bless you. The life of a hero''s forest dwelling pleases me.', 'veda-app-ai-draft', true),
('ramayana-2-26-14', 'en', 'Pure-souled one, through love I will be free of sin, following my husband, for my husband is my god.', 'veda-app-ai-draft', true),
('ramayana-2-26-15', 'en', 'Even after death my union with you will be blessed; this holy teaching is heard from famous brahmins.', 'veda-app-ai-draft', true),
('ramayana-2-26-16', 'en', 'A woman given to a man in this world by her parents with water, by their own dharma, is his even after death.', 'veda-app-ai-draft', true),
('ramayana-2-26-17', 'en', 'So why do you not wish to take me, your own wife, of good conduct and devoted to her husband?', 'veda-app-ai-draft', true),
('ramayana-2-26-18', 'en', 'Devoted, faithful, wretched, the same in joy and sorrow, you should take me, Kakutstha, sharing your joys and sorrows.', 'veda-app-ai-draft', true),
('ramayana-2-26-19', 'en', 'If you do not wish to take me, grieving like this, to the forest, I will take poison, fire or water to die.', 'veda-app-ai-draft', true),
('ramayana-2-26-20', 'en', 'So she begged him in many ways to go, but the mighty-armed one did not agree to take her to the lonely forest.', 'veda-app-ai-draft', true),
('ramayana-2-26-21', 'en', 'Thus answered, Maithili fell into deep thought, as if bathing the ground with the hot tears falling from her eyes.', 'veda-app-ai-draft', true),
('ramayana-2-26-22', 'en', 'Self-possessed Kakutstha comforted Vaidehi much, seeing her thoughtful and angry, to turn her back.', 'veda-app-ai-draft', true),
('ramayana-2-27-1', 'en', 'Being comforted by Rama, Maithili, Janaka''s daughter, said this to her husband about going to the forest:', 'veda-app-ai-draft', true),
('ramayana-2-27-2', 'en', 'Deeply agitated, out of love and pride, Sita rebuked broad-chested Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-27-3', 'en', 'What did my father, the Videha lord of Mithila, think, Rama, gaining you as son-in-law, a woman in a man''s form?', 'veda-app-ai-draft', true),
('ramayana-2-27-4', 'en', 'It would be a lie, which ignorant people would tell, that there is no greater power than Rama''s, blazing like the sun.', 'veda-app-ai-draft', true),
('ramayana-2-27-5', 'en', 'What have you done that you are so downcast, and what do you fear, that you want to abandon me, who has no other refuge?', 'veda-app-ai-draft', true),
('ramayana-2-27-6', 'en', 'Know me to be like Savitri, devoted to Satyavan son of Dyumatsena, one who follows you alone.', 'veda-app-ai-draft', true),
('ramayana-2-27-7', 'en', 'I would not even in my mind look at another man but you, sinless one. I would go with you, Raghava, not like some woman who disgraces her family.', 'veda-app-ai-draft', true),
('ramayana-2-27-8', 'en', 'You yourself want to hand me over to others like an actor, your wife married young and long living with you, chaste.', 'veda-app-ai-draft', true),
('ramayana-2-27-9', 'en', 'You should not set out for the forest without taking me. Austerity, forest or heaven, let it be with you.', 'veda-app-ai-draft', true),
('ramayana-2-27-10', 'en', 'I will feel no weariness on the road, walking behind you, nor in resting or sleeping.', 'veda-app-ai-draft', true),
('ramayana-2-27-11', 'en', 'Kusha and kasha grass, reeds and thorny trees will feel to me like cotton and deerskin on the road with you.', 'veda-app-ai-draft', true),
('ramayana-2-27-12', 'en', 'The dust stirred by great winds that covers me, beloved, I will think of as precious sandalwood.', 'veda-app-ai-draft', true),
('ramayana-2-27-13', 'en', 'When I sit on grassy meadows at the forest''s edge, roaming the forest, what could be happier than beds with fine covers?', 'veda-app-ai-draft', true),
('ramayana-2-27-14', 'en', 'Leaf, root or fruit, little or much, that you yourself bring and give me, will taste like nectar.', 'veda-app-ai-draft', true),
('ramayana-2-27-15', 'en', 'There I will not remember mother, father or home, enjoying the flowers and fruits of each season.', 'veda-app-ai-draft', true),
('ramayana-2-27-16', 'en', 'You will see nothing unpleasant there; you will not grieve because of me, and I will not be hard to look after.', 'veda-app-ai-draft', true),
('ramayana-2-27-17', 'en', 'Where you are is heaven; where you are not is hell. Knowing this, Rama, go with me in the highest joy.', 'veda-app-ai-draft', true),
('ramayana-2-27-18', 'en', 'If you will not take me, untroubled as I am, to the forest, I will drink poison today rather than fall into enemies'' power.', 'veda-app-ai-draft', true),
('ramayana-2-27-19', 'en', 'Afterwards, through grief, I would not live anyway; abandoned by you, lord, death then would be better.', 'veda-app-ai-draft', true),
('ramayana-2-27-20', 'en', 'I cannot bear this grief for even a moment; how much less for ten, three and one years in sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-27-21', 'en', 'So, burning with grief, after lamenting pitifully, she cried out loud, clinging tightly to her husband.', 'veda-app-ai-draft', true),
('ramayana-2-27-22', 'en', 'Wounded by many words as an elephant cow by poisoned arrows, she released her long-held tears as a fire-stick releases fire.', 'veda-app-ai-draft', true),
('ramayana-2-27-23', 'en', 'Crystal-clear water born of distress flowed from her eyes like water from lotuses.', 'veda-app-ai-draft', true),
('ramayana-2-27-24', 'en', 'Embracing her with his arms as she seemed to faint with grief, Rama, reassuring her, said:', 'veda-app-ai-draft', true),
('ramayana-2-27-25', 'en', 'Queen, I would not want even heaven at the cost of your grief. I have no fear of anything, like Brahma himself.', 'veda-app-ai-draft', true),
('ramayana-2-27-26', 'en', 'Not knowing your full intent, lovely one, I did not want you to live in the forest, though I am able to protect you.', 'veda-app-ai-draft', true),
('ramayana-2-27-27', 'en', 'Since you were made to live in the forest with me, Maithili, I cannot leave you, as a self-possessed man cannot abandon his good name.', 'veda-app-ai-draft', true),
('ramayana-2-27-28', 'en', 'Dharma was practised by the good of old, elephant-thighed one, and I follow it today as Suvarchala follows the sun.', 'veda-app-ai-draft', true),
('ramayana-2-27-29', 'en', 'This dharma, lovely one, is obedience to father and mother; so I cannot live if I break their command.', 'veda-app-ai-draft', true),
('ramayana-2-27-30', 'en', 'As my father, standing on the path of truth and dharma, commands me, so I wish to act; that is eternal dharma. Follow me, timid one, and be my partner in dharma.', 'veda-app-ai-draft', true),
('ramayana-2-27-31', 'en', 'Give jewels to brahmins and food to mendicants and to those who ask; hurry, without delay.', 'veda-app-ai-draft', true),
('ramayana-2-27-32', 'en', 'Knowing her husband agreed to her going, the queen, delighted, quickly began to give.', 'veda-app-ai-draft', true),
('ramayana-2-27-33', 'en', 'Then, delighted and fulfilled, the famous, high-minded lady, seeing her husband''s words, began to give away wealth and jewels to the righteous.', 'veda-app-ai-draft', true),
('ramayana-2-28-1', 'en', 'Then mighty Rama spoke to Lakshmana, who stood before him with folded hands, ready to go first, begging:', 'veda-app-ai-draft', true),
('ramayana-2-28-2', 'en', 'If you go to the forest with me today, Saumitri, who will look after Kausalya or famous Sumitra?', 'veda-app-ai-draft', true),
('ramayana-2-28-3', 'en', 'The mighty king, who showered the earth with gifts like a rain cloud, is caught in the noose of desire.', 'veda-app-ai-draft', true),
('ramayana-2-28-4', 'en', 'When the daughter of King Ashvapati gains this kingdom, she will not treat her grieving co-wives well.', 'veda-app-ai-draft', true),
('ramayana-2-28-5', 'en', 'Thus addressed gently by Rama, Lakshmana, skilled in speech, replied to eloquent Rama:', 'veda-app-ai-draft', true),
('ramayana-2-28-6', 'en', 'By your power alone, hero, Bharata will carefully honour Kausalya and Sumitra; there is no doubt.', 'veda-app-ai-draft', true),
('ramayana-2-28-7', 'en', 'Noble Kausalya could support a thousand like me; she has a thousand villages for her living.', 'veda-app-ai-draft', true),
('ramayana-2-28-8', 'en', 'Taking my bow and arrows, carrying spade and basket, I will go ahead of you showing the way.', 'veda-app-ai-draft', true),
('ramayana-2-28-9', 'en', 'I will always bring you roots and fruits and whatever other forest food is fit for ascetics.', 'veda-app-ai-draft', true),
('ramayana-2-28-10', 'en', 'You will enjoy yourself with Vaidehi on the mountain slopes; I will do everything, while you wake and while you sleep.', 'veda-app-ai-draft', true),
('ramayana-2-28-11', 'en', 'Well pleased by these words, Rama replied: Go, Saumitri, take leave of all your friends.', 'veda-app-ai-draft', true),
('ramayana-2-28-12', 'en', 'The two divine, fearsome bows that great Varuna himself gave the king at Janaka''s great sacrifice,', 'veda-app-ai-draft', true),
('ramayana-2-28-13', 'en', 'the divine impenetrable armour, the two quivers of inexhaustible arrows, and the two gold-adorned swords bright as the sun,', 'veda-app-ai-draft', true),
('ramayana-2-28-14', 'en', 'all kept with honour in our teacher''s house: take these weapons and come back quickly, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-28-15', 'en', 'Resolved on forest life, he took leave of his friends, took leave of the Ikshvaku teacher and took the fine weapons.', 'veda-app-ai-draft', true),
('ramayana-2-28-16', 'en', 'Saumitri showed Rama all the divine weapons, honoured and adorned with garlands.', 'veda-app-ai-draft', true),
('ramayana-2-28-17', 'en', 'Self-possessed Rama lovingly said to Lakshmana: You have come at the time I wished, gentle Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-28-18', 'en', 'I want to give away this wealth of mine to brahmins and ascetics with you, tamer of foes.', 'veda-app-ai-draft', true),
('ramayana-2-28-19', 'en', 'The best of brahmins who live here with firm devotion to our elders, and all my dependants too,', 'veda-app-ai-draft', true),
('ramayana-2-28-20', 'en', 'bring quickly noble Suyajna, son of Vasishtha, best of brahmins. I will go to the forest after honouring him and all the other learned brahmins.', 'veda-app-ai-draft', true),
('ramayana-2-29-1', 'en', 'Understanding his brother''s kind and welcome command, he went and quickly entered Suyajna''s house.', 'veda-app-ai-draft', true),
('ramayana-2-29-2', 'en', 'Bowing to the brahmin in his fire-room, Lakshmana said: Friend, come and see the house of one doing a hard thing.', 'veda-app-ai-draft', true),
('ramayana-2-29-3', 'en', 'After the evening prayer he quickly went with Saumitri and entered Rama''s lovely, splendid house.', 'veda-app-ai-draft', true),
('ramayana-2-29-4', 'en', 'Raghava with Sita came forward with folded hands to the learned Suyajna, as to a worshipped fire.', 'veda-app-ai-draft', true),
('ramayana-2-29-5', 'en', 'With fine gold armlets, lovely earrings, gold threads with gems, bracelets and bangles,', 'veda-app-ai-draft', true),
('ramayana-2-29-6', 'en', 'and many other jewels Kakutstha honoured him, and Rama, urged by Sita, said to Suyajna:', 'veda-app-ai-draft', true),
('ramayana-2-29-7', 'en', 'Take this necklace and gold chain for your wife, gentle one; and Sita wants to give you her girdle now, friend.', 'veda-app-ai-draft', true),
('ramayana-2-29-8', 'en', 'Vaidehi also wants to give you this couch with a fine cover, adorned with many jewels.', 'veda-app-ai-draft', true),
('ramayana-2-29-9', 'en', 'The elephant named Shatrunjaya that my uncle gave me, I give you with a thousand elephants, best of brahmins.', 'veda-app-ai-draft', true),
('ramayana-2-29-10', 'en', 'Thus addressed by Rama, Suyajna accepted it and gave auspicious blessings to Rama, Lakshmana and Sita.', 'veda-app-ai-draft', true),
('ramayana-2-29-11', 'en', 'Then kind-spoken Rama said to his calm, dear brother Saumitri, as Brahma speaks to Indra:', 'veda-app-ai-draft', true),
('ramayana-2-29-12', 'en', 'Invite and honour with jewels the two best of brahmins, Agastya and Kaushika, as crops are refreshed with rain.', 'veda-app-ai-draft', true),
('ramayana-2-29-13', 'en', 'The devoted teacher of the Taittiriya school, handsome and learned, who serves Kausalya with blessings,', 'veda-app-ai-draft', true),
('ramayana-2-29-14', 'en', 'give him a carriage, servant women and silk clothes until that brahmin is satisfied, Saumitri.', 'veda-app-ai-draft', true),
('ramayana-2-29-15', 'en', 'And noble Chitraratha, the charioteer and long-serving counsellor, please him with costly jewels, clothes and wealth.', 'veda-app-ai-draft', true),
('ramayana-2-29-16', 'en', 'And a thousand loads of rice, two hundred oxen and, for dairy, a thousand cows, Saumitri.', 'veda-app-ai-draft', true),
('ramayana-2-29-17', 'en', 'Then Lakshmana, tiger among men, himself gave that wealth to the best brahmins as instructed, like Kubera.', 'veda-app-ai-draft', true),
('ramayana-2-29-18', 'en', 'Then he spoke to the dependants standing there, choked with tears, having given much to each one:', 'veda-app-ai-draft', true),
('ramayana-2-29-19', 'en', 'Keep Lakshmana''s house and this home of mine each occupied until I return.', 'veda-app-ai-draft', true),
('ramayana-2-29-20', 'en', 'Having said this to all those grieving dependants, he told the treasurer: Bring the wealth. And the dependants brought all his wealth.', 'veda-app-ai-draft', true),
('ramayana-2-29-21', 'en', 'Then the tiger among men with Lakshmana had it given to brahmins, children, the old and the poor.', 'veda-app-ai-draft', true),
('ramayana-2-29-22', 'en', 'There was a brahmin there named Trijata of the Garga clan, tawny-haired; no one stopped him up to the fifth courtyard.', 'veda-app-ai-draft', true),
('ramayana-2-29-23', 'en', 'Reaching the prince, Trijata said: I am poor with many sons, famous prince. I live by gleaning in the forest; look after me.', 'veda-app-ai-draft', true),
('ramayana-2-29-24', 'en', 'Rama, in a playful mood, said to him: I have not yet given away even one thousand cows. As far as you can throw your staff, you will get that many.', 'veda-app-ai-draft', true),
('ramayana-2-29-25', 'en', 'He quickly, eagerly tied his cloth round his waist, whirled his staff and threw it with all his strength.', 'veda-app-ai-draft', true),
('ramayana-2-29-26', 'en', 'Then Rama, comforting that Garga, said: Do not be offended; this was just my joke.', 'veda-app-ai-draft', true),
('ramayana-2-29-27', 'en', 'Then the great sage Trijata with his wife, receiving a herd of cows, delighted, gave great Rama blessings that increase fame, strength, love and happiness.', 'veda-app-ai-draft', true),
('ramayana-2-30-1', 'en', 'Having given much wealth to brahmins with Vaidehi, the two Raghavas went with Sita to see their father.', 'veda-app-ai-draft', true),
('ramayana-2-30-2', 'en', 'The weapons they carried, hard to look at, shone, hung with garlands and adorned by Sita.', 'veda-app-ai-draft', true),
('ramayana-2-30-3', 'en', 'Then the people climbed palaces, mansions and towers and watched sorrowfully.', 'veda-app-ai-draft', true),
('ramayana-2-30-4', 'en', 'The streets were too crowded to walk, so they climbed the palaces and gazed sadly at Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-30-5', 'en', 'Seeing Rama on foot, without his umbrella, the people, stricken with grief, said many things.', 'veda-app-ai-draft', true),
('ramayana-2-30-6', 'en', 'He whom a great four-part army used to follow is followed now only by Lakshmana with Sita.', 'veda-app-ai-draft', true),
('ramayana-2-30-7', 'en', 'Though he knows the taste of power and grants desires, he will not make his father a liar, out of reverence for dharma.', 'veda-app-ai-draft', true),
('ramayana-2-30-8', 'en', 'Sita, whom even beings in the sky could not see before, the people on the royal road see today.', 'veda-app-ai-draft', true),
('ramayana-2-30-9', 'en', 'Sita, used to cosmetics and red sandal paste, will soon be darkened by rain, heat and cold.', 'veda-app-ai-draft', true),
('ramayana-2-30-10', 'en', 'Surely Dasharatha speaks today possessed by some spirit; no king would banish his dear son.', 'veda-app-ai-draft', true),
('ramayana-2-30-11', 'en', 'How could even a worthless son be banished? How much more one who has won this world by his conduct alone?', 'veda-app-ai-draft', true),
('ramayana-2-30-12', 'en', 'Kindness, compassion, learning, character, self-control and calm: these six virtues adorn Raghava, best of men.', 'veda-app-ai-draft', true),
('ramayana-2-30-13', 'en', 'So the people are deeply pained by his injury, like water creatures when the water dries up in summer.', 'veda-app-ai-draft', true),
('ramayana-2-30-14', 'en', 'The whole world is pained by the pain of this lord of the world, as a flowering, fruiting tree is when its root is cut.', 'veda-app-ai-draft', true),
('ramayana-2-30-15', 'en', 'Like Lakshmana, let us quickly follow where Raghava goes, with our wives and kin.', 'veda-app-ai-draft', true),
('ramayana-2-30-16', 'en', 'Leaving gardens, fields and homes, sharing one sorrow and joy, let us follow righteous Rama.', 'veda-app-ai-draft', true),
('ramayana-2-30-17', 'en', 'Let Kaikeyi take our abandoned houses, their treasure dug up, courtyards ruined, grain and wealth removed, stripped of all value,', 'veda-app-ai-draft', true),
('ramayana-2-30-18', 'en', 'covered in dust, deserted by the household gods, abandoned by us.', 'veda-app-ai-draft', true),
('ramayana-2-30-19', 'en', 'Let the forest where Raghava goes become a city, and let the city we abandon become a forest.', 'veda-app-ai-draft', true),
('ramayana-2-30-20', 'en', 'Let fanged beasts leave their dens, and deer and birds their slopes, and come to live in what we abandon.', 'veda-app-ai-draft', true),
('ramayana-2-30-21', 'en', 'Rama heard these many things said by all kinds of people, and hearing them, his mind did not change.', 'veda-app-ai-draft', true),
('ramayana-2-30-22', 'en', 'Looking at the distressed people, himself showing no distress, almost smiling, Rama went to see his father, wishing to do his command properly.', 'veda-app-ai-draft', true),
('ramayana-2-30-23', 'en', 'Before going, great Rama, Ikshvaku''s son, about to leave for the forest, stood seeing Sumantra stricken, waiting to be announced to his father.', 'veda-app-ai-draft', true),
('ramayana-2-30-24', 'en', 'Devoted to dharma, resolved to enter the forest by his father''s command, Raghava, seeing Sumantra, said: Announce my coming to the king.', 'veda-app-ai-draft', true),
('ramayana-2-31-1', 'en', 'Sent by Rama, the charioteer, his senses clouded by grief, went in quickly and saw the king sighing.', 'veda-app-ai-draft', true),
('ramayana-2-31-2', 'en', 'Seeing the king deeply troubled, grieving for Rama, the wise charioteer approached him with folded hands.', 'veda-app-ai-draft', true),
('ramayana-2-31-3', 'en', 'Here is your son at the door, tiger among men, having given all his wealth to brahmins and dependants.', 'veda-app-ai-draft', true),
('ramayana-2-31-4', 'en', 'Let Rama, true in valour, see you, bless you. Having taken leave of all his friends, he wishes to see you now.', 'veda-app-ai-draft', true),
('ramayana-2-31-5', 'en', 'He will go to the great forest; see him, lord of the earth, endowed with every kingly virtue like the sun with its rays.', 'veda-app-ai-draft', true),
('ramayana-2-31-6', 'en', 'The truthful, righteous king, deep as the ocean and clear as the sky, replied:', 'veda-app-ai-draft', true),
('ramayana-2-31-7', 'en', 'Sumantra, bring all my wives who are here; I want to see Raghava surrounded by all my wives.', 'veda-app-ai-draft', true),
('ramayana-2-31-8', 'en', 'Going into the inner palace he said to the women: The noble king calls you; go there without delay.', 'veda-app-ai-draft', true),
('ramayana-2-31-9', 'en', 'Thus told by Sumantra at the king''s command, all the women went to that hall, knowing their husband''s order.', 'veda-app-ai-draft', true),
('ramayana-2-31-10', 'en', 'Three hundred and fifty women with red-rimmed eyes, keeping their vows, slowly came surrounding Kausalya.', 'veda-app-ai-draft', true),
('ramayana-2-31-11', 'en', 'When the wives had come, the lord of the earth, seeing them, said to the charioteer: Sumantra, bring my son.', 'veda-app-ai-draft', true),
('ramayana-2-31-12', 'en', 'The charioteer, bringing Rama, Lakshmana and Maithili, went quickly towards the lord of the earth.', 'veda-app-ai-draft', true),
('ramayana-2-31-13', 'en', 'The king, seeing his son coming from afar with folded hands, sprang up from his seat, distressed, surrounded by the women.', 'veda-app-ai-draft', true),
('ramayana-2-31-14', 'en', 'The lord of people ran fast towards Rama, but before reaching him, stricken with grief, fell fainting to the ground.', 'veda-app-ai-draft', true),
('ramayana-2-31-15', 'en', 'Rama and the great warrior Lakshmana quickly rushed to the king, unconscious with grief and sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-31-16', 'en', 'A cry of a thousand women rose in the palace, Alas, Rama! mixed with the sound of their ornaments.', 'veda-app-ai-draft', true),
('ramayana-2-31-17', 'en', 'Embracing him with their arms, Rama and Lakshmana with Sita, weeping, laid him on the couch.', 'veda-app-ai-draft', true),
('ramayana-2-31-18', 'en', 'After a while, when the king regained consciousness, Rama, with folded hands, spoke to him, drowning in an ocean of grief:', 'veda-app-ai-draft', true),
('ramayana-2-31-19', 'en', 'I take leave of you, great king; you are lord of us all. See me safely off to the Dandaka forest.', 'veda-app-ai-draft', true),
('ramayana-2-31-20', 'en', 'Give Lakshmana leave too, and Sita follows me to the forest; though held back with many true reasons, they will not stay.', 'veda-app-ai-draft', true),
('ramayana-2-31-21', 'en', 'Give us all leave, giver of honour, setting grief aside, Lakshmana, me and Sita, as the Creator does his creatures.', 'veda-app-ai-draft', true),
('ramayana-2-31-22', 'en', 'Seeing Raghava calmly waiting for his permission to live in the forest, the king said:', 'veda-app-ai-draft', true),
('ramayana-2-31-23', 'en', 'Raghava, I am deluded by the boon I gave Kaikeyi. Restrain me and become king of Ayodhya yourself today.', 'veda-app-ai-draft', true),
('ramayana-2-31-24', 'en', 'Thus addressed by the king, Rama, best of upholders of dharma, skilled in speech, folded his hands and replied:', 'veda-app-ai-draft', true),
('ramayana-2-31-25', 'en', 'May you be lord of the earth for a thousand years, O king. I will live in the forest; I must not make you a liar.', 'veda-app-ai-draft', true),
('ramayana-2-31-26', 'en', 'Go, my son, for good fortune, growth and return, on a safe path, untroubled and free of fear from any side.', 'veda-app-ai-draft', true),
('ramayana-2-31-27', 'en', 'But do not go now tonight, son, in any case. Seeing your mother and me, stay this one night; satisfied with all you want, you can set out tomorrow.', 'veda-app-ai-draft', true),
('ramayana-2-31-28', 'en', 'Hearing the words of his grieving father, Rama, sad, with his brother Lakshmana, said:', 'veda-app-ai-draft', true),
('ramayana-2-31-29', 'en', 'Who will give me tomorrow the good things I would get today? So I choose leaving over all desires.', 'veda-app-ai-draft', true),
('ramayana-2-31-30', 'en', 'Let this earth, with its kingdom and people, full of wealth and grain, which I give up, be given to Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-31-31', 'en', 'Let your sorrow go; do not be drowned in tears. The invincible ocean, lord of rivers, is not shaken.', 'veda-app-ai-draft', true),
('ramayana-2-31-32', 'en', 'I want neither kingdom, nor happiness, nor even Maithili; I want you to be truthful, not false, bull among men.', 'veda-app-ai-draft', true),
('ramayana-2-31-33', 'en', 'Let the city, the kingdom and the whole earth I give up be given to Bharata. Keeping your command, I will go to the forest to live there a long time.', 'veda-app-ai-draft', true),
('ramayana-2-31-34', 'en', 'Let Bharata alone rule this earth I give up, with its mountains, cities and forests, auspicious and well bounded; let what you said be so, O king.', 'veda-app-ai-draft', true),
('ramayana-2-31-35', 'en', 'My mind is not set so much on great pleasures or on what is dear to me as on your command approved by the good. Let your sorrow on my account pass, sinless one.', 'veda-app-ai-draft', true),
('ramayana-2-31-36', 'en', 'So today, sinless one, I would not choose the lasting kingdom, nor all pleasures, nor happiness, nor Maithili, nor life, by making you false. Let your vow be true.', 'veda-app-ai-draft', true),
('ramayana-2-31-37', 'en', 'Eating fruits and roots in the forest, seeing mountains, rivers and lakes, entering the forest of many trees, I will be happy. Be at peace.', 'veda-app-ai-draft', true),
('ramayana-2-32-1', 'en', 'Then the Ikshvaku king, tormented by his promise, sighing deeply with tears, said to Sumantra again and again:', 'veda-app-ai-draft', true),
('ramayana-2-32-2', 'en', 'Charioteer, quickly prepare a four-part army full of treasure to follow Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-32-3', 'en', 'Let courtesans, skilled women and wealthy merchants adorn the prince''s train, spread out widely.', 'veda-app-ai-draft', true),
('ramayana-2-32-4', 'en', 'Those who live by him and those whose prowess he enjoys, give them many things and assign them here too.', 'veda-app-ai-draft', true),
('ramayana-2-32-5', 'en', 'Killing deer and elephants, drinking forest honey, seeing many rivers, he will not remember the kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-32-6', 'en', 'Let whatever granary and treasury of mine follow Rama as he lives in the lonely forest.', 'veda-app-ai-draft', true),
('ramayana-2-32-7', 'en', 'Sacrificing in holy places and giving generous fees, meeting with sages, he will live happily in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-32-8', 'en', 'Mighty Bharata will protect Ayodhya; let glorious Rama be provided with every desire.', 'veda-app-ai-draft', true),
('ramayana-2-32-9', 'en', 'As Kakutstha spoke, fear came over Kaikeyi; her mouth went dry and her voice was choked.', 'veda-app-ai-draft', true),
('ramayana-2-32-10', 'en', 'Dismayed and frightened, Kaikeyi said: Good sir, Bharata will not accept a kingdom emptied of people, like wine with its essence drunk, utterly tasteless and void.', 'veda-app-ai-draft', true),
('ramayana-2-32-11', 'en', 'As Kaikeyi, shameless, spoke so very cruelly, King Dasharatha said to the wide-eyed woman: Why do you goad me when I carry the burden you placed on me?', 'veda-app-ai-draft', true),
('ramayana-2-32-12', 'en', 'Kaikeyi, twice as angry, said to the king: In your own line Sagara banished his eldest son, known as Asamanja; so this one should go.', 'veda-app-ai-draft', true),
('ramayana-2-32-13', 'en', 'Thus addressed, King Dasharatha said only, Shame! All the people were ashamed, but she did not understand.', 'veda-app-ai-draft', true),
('ramayana-2-32-14', 'en', 'There an old chief minister named Siddhartha, honest and esteemed by the king, said to Kaikeyi:', 'veda-app-ai-draft', true),
('ramayana-2-32-15', 'en', 'Asamanja used to seize children on the road in play and throw them into the waters of the Sarayu; the wicked one enjoyed it.', 'veda-app-ai-draft', true),
('ramayana-2-32-16', 'en', 'Seeing that, all the citizens angrily told the king: Choose Asamanja alone, or us, you who prosper the kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-32-17', 'en', 'The king asked them: Why this fear? Asked by the king, the people said:', 'veda-app-ai-draft', true),
('ramayana-2-32-18', 'en', 'He, out of his mind, seizes our little sons in play and throws them into the Sarayu, and in his folly takes great delight in it.', 'veda-app-ai-draft', true),
('ramayana-2-32-19', 'en', 'Hearing the people, O king, he cast off that harmful son to please them.', 'veda-app-ai-draft', true),
('ramayana-2-32-20', 'en', 'So righteous King Sagara cast him off. What wrong has Rama done to be banished like this?', 'veda-app-ai-draft', true),
('ramayana-2-32-21', 'en', 'Hearing Siddhartha, the king, his voice weaker still, said to Kaikeyi in a grief-stricken voice:', 'veda-app-ai-draft', true),
('ramayana-2-32-22', 'en', 'I will follow Rama today, giving up kingdom, comfort and wealth. You, with King Bharata, enjoy the kingdom as you please for a long time.', 'veda-app-ai-draft', true),
('ramayana-2-33-1', 'en', 'Hearing the chief minister, Rama, knowing humility, humbly spoke to Dasharatha:', 'veda-app-ai-draft', true),
('ramayana-2-33-2', 'en', 'I have given up pleasures and will live on forest food, O king. What use is a following to me, who have given up all attachments?', 'veda-app-ai-draft', true),
('ramayana-2-33-3', 'en', 'Who, having given away the best elephant, sets his heart on the girth rope? What is the rope to one giving up the elephant?', 'veda-app-ai-draft', true),
('ramayana-2-33-4', 'en', 'So, best of the good, what use is an army to me, lord of the world? I give up everything. Let them bring me just bark garments.', 'veda-app-ai-draft', true),
('ramayana-2-33-5', 'en', 'Bring me a spade and a basket as I go, to live fourteen years in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-33-6', 'en', 'Then Kaikeyi herself brought bark garments to Raghava and said shamelessly before the crowd, Put them on.', 'veda-app-ai-draft', true),
('ramayana-2-33-7', 'en', 'Taking the bark garments from Kaikeyi, the tiger among men threw off his fine clothes and put on a sage''s dress.', 'veda-app-ai-draft', true),
('ramayana-2-33-8', 'en', 'Lakshmana too, right there before his father, left his fine clothes and took the ascetic''s dress.', 'veda-app-ai-draft', true),
('ramayana-2-33-9', 'en', 'Then Sita, dressed in silk, seeing the bark garment meant for her, shrank like a doe from a net.', 'veda-app-ai-draft', true),
('ramayana-2-33-10', 'en', 'Taking it, ashamed and unhappy, she said to her husband, handsome as a gandharva king: How do forest sages tie their bark garments?', 'veda-app-ai-draft', true),
('ramayana-2-33-11', 'en', 'Putting one around her neck and holding one in her hand, Janaka''s daughter stood there, clumsy and embarrassed.', 'veda-app-ai-draft', true),
('ramayana-2-33-12', 'en', 'Rama, best of upholders of dharma, came quickly and himself tied the bark garment over her silk.', 'veda-app-ai-draft', true),
('ramayana-2-33-13', 'en', 'Seeing her, who had a protector, wearing bark as if she had none, all the people cried out: Shame on you, Dasharatha!', 'veda-app-ai-draft', true),
('ramayana-2-33-14', 'en', 'Sighing hot, the Ikshvaku said to his wife: Kaikeyi, Sita should not go in a bark garment.', 'veda-app-ai-draft', true),
('ramayana-2-33-15', 'en', 'Surely Rama''s banishment is enough for you, wicked one. Why add these mean sins?', 'veda-app-ai-draft', true),
('ramayana-2-33-16', 'en', 'To his father speaking so, sitting with bowed head, Rama, setting out for the forest, said:', 'veda-app-ai-draft', true),
('ramayana-2-33-17', 'en', 'Righteous one, this Kausalya is my famous mother, old and of noble character; she does not blame you, lord of gods.', 'veda-app-ai-draft', true),
('ramayana-2-33-18', 'en', 'Without me, giver of boons, sunk in an ocean of grief, never having known misfortune, she deserves your greater respect.', 'veda-app-ai-draft', true),
('ramayana-2-33-19', 'en', 'Treat my mother, who bore a son like great Indra, so that, worn by grief while I am in the forest, she does not give up her life and go to Yama''s realm.', 'veda-app-ai-draft', true),
('ramayana-2-34-1', 'en', 'Hearing Rama''s words and seeing him in a sage''s dress, the king with his wives lost consciousness.', 'veda-app-ai-draft', true),
('ramayana-2-34-2', 'en', 'Burning with sorrow, he could not look at Raghava, nor, seeing him, speak to him in his misery.', 'veda-app-ai-draft', true),
('ramayana-2-34-3', 'en', 'For a while the king lay unconscious and grieving; then the mighty-armed one lamented, thinking only of Rama.', 'veda-app-ai-draft', true),
('ramayana-2-34-4', 'en', 'I think I must have separated many cows from their calves before, or harmed living things; that is why this has come.', 'veda-app-ai-draft', true),
('ramayana-2-34-5', 'en', 'Life does not leave the body before its time; though tormented by Kaikeyi, I do not die.', 'veda-app-ai-draft', true),
('ramayana-2-34-6', 'en', 'I see before me my son, bright as fire, having put off fine clothes for an ascetic''s covering.', 'veda-app-ai-draft', true),
('ramayana-2-34-7', 'en', 'Because of one woman, Kaikeyi, these people suffer; she strives for her own ends, relying on this deceit.', 'veda-app-ai-draft', true),
('ramayana-2-34-8', 'en', 'Saying this, his eyes veiled with tears, he said Rama only once and could speak no more.', 'veda-app-ai-draft', true),
('ramayana-2-34-9', 'en', 'Regaining consciousness after a while, the king, his eyes full of tears, said to Sumantra:', 'veda-app-ai-draft', true),
('ramayana-2-34-10', 'en', 'Yoke the riding chariot with the best horses and come; take this fortunate one beyond this country.', 'veda-app-ai-draft', true),
('ramayana-2-34-11', 'en', 'This, I think, is called the fruit of virtue in the virtuous: that a good and heroic son is banished to the forest by his father and mother.', 'veda-app-ai-draft', true),
('ramayana-2-34-12', 'en', 'Understanding the king''s command, swift Sumantra yoked and brought the chariot with decorated horses.', 'veda-app-ai-draft', true),
('ramayana-2-34-13', 'en', 'With folded hands the charioteer told the prince the gold-adorned chariot was yoked to the finest horses.', 'veda-app-ai-draft', true),
('ramayana-2-34-14', 'en', 'The king quickly called the treasurer, who knew place and time, was resolute and honest in every way, and said:', 'veda-app-ai-draft', true),
('ramayana-2-34-15', 'en', 'Counting these years, quickly bring costly clothes and fine ornaments for Vaidehi.', 'veda-app-ai-draft', true),
('ramayana-2-34-16', 'en', 'Thus told by the king, he went to the treasury and quickly brought everything and gave it to Sita.', 'veda-app-ai-draft', true),
('ramayana-2-34-17', 'en', 'Noble Vaidehi, setting out for the forest, adorned her limbs with those lovely, varied ornaments.', 'veda-app-ai-draft', true),
('ramayana-2-34-18', 'en', 'Well adorned, Vaidehi lit up the palace, as the radiance of the rising sun lights the sky.', 'veda-app-ai-draft', true),
('ramayana-2-34-19', 'en', 'Her mother-in-law embraced her with both arms, kissed Maithili on the head, who never acted meanly, and said:', 'veda-app-ai-draft', true),
('ramayana-2-34-20', 'en', 'In this whole world, unfaithful women, though always honoured by loved ones, do not respect a husband fallen on misfortune.', 'veda-app-ai-draft', true),
('ramayana-2-34-21', 'en', 'Do not slight my banished son. Let him be your god, poor or rich.', 'veda-app-ai-draft', true),
('ramayana-2-34-22', 'en', 'Understanding her words full of dharma and purpose, Sita stood before her mother-in-law with folded hands and said:', 'veda-app-ai-draft', true),
('ramayana-2-34-23', 'en', 'I will do everything the noble lady teaches me. I know how to behave towards my husband; I have heard it.', 'veda-app-ai-draft', true),
('ramayana-2-34-24', 'en', 'The noble lady should not compare me with bad women; I cannot swerve from dharma, as light cannot leave the moon.', 'veda-app-ai-draft', true),
('ramayana-2-34-25', 'en', 'A vina does not play without strings, a chariot does not run without wheels; a woman without her husband does not thrive in happiness, even with a hundred sons.', 'veda-app-ai-draft', true),
('ramayana-2-34-26', 'en', 'Father gives in measure, mother gives in measure, son gives in measure; what woman would not honour her husband, giver of what cannot be measured?', 'veda-app-ai-draft', true),
('ramayana-2-34-27', 'en', 'Being such, and having heard what is higher and lower in dharma, noble lady, how could I slight him? For women, the husband is a god.', 'veda-app-ai-draft', true),
('ramayana-2-34-28', 'en', 'Hearing Sita''s heartfelt words, pure-hearted Kausalya suddenly shed tears born of both sorrow and joy.', 'veda-app-ai-draft', true),
('ramayana-2-34-29', 'en', 'Approaching with folded hands his mother, highly honoured among the mothers, Rama, who knew dharma well, said:', 'veda-app-ai-draft', true),
('ramayana-2-34-30', 'en', 'Mother, do not grieve; look after my father. The end of the forest exile will come quickly.', 'veda-app-ai-draft', true),
('ramayana-2-34-31', 'en', 'Nine and five years will pass as if you slept. You will see me back here whole, surrounded by friends.', 'veda-app-ai-draft', true),
('ramayana-2-34-32', 'en', 'Having said these meaningful words to his mother, he looked round and saw the three hundred and fifty mothers.', 'veda-app-ai-draft', true),
('ramayana-2-34-33', 'en', 'To those mothers, equally grieved, Dasharatha''s son spoke these words full of dharma with folded hands:', 'veda-app-ai-draft', true),
('ramayana-2-34-34', 'en', 'Whatever harshness I may have done through living together or unknowingly, forgive me; I take leave of you all.', 'veda-app-ai-draft', true),
('ramayana-2-34-35', 'en', 'As Raghava spoke, the wives of the lord of men cried out like curlews.', 'veda-app-ai-draft', true),
('ramayana-2-34-36', 'en', 'Dasharatha''s palace, once resounding like drums and thunder, was now filled with laments and cries, stricken with disaster.', 'veda-app-ai-draft', true),
('ramayana-2-35-1', 'en', 'Then Rama, Sita and Lakshmana, with folded hands, touched the king''s feet and sadly walked round him.', 'veda-app-ai-draft', true),
('ramayana-2-35-2', 'en', 'Taking leave of him, righteous Raghava with Sita, bewildered with grief, saluted his mother.', 'veda-app-ai-draft', true),
('ramayana-2-35-3', 'en', 'Right after his brother, Lakshmana saluted Kausalya, and then clasped the feet of his own mother Sumitra.', 'veda-app-ai-draft', true),
('ramayana-2-35-4', 'en', 'As he bowed, his weeping mother, wishing him well, kissed mighty-armed Lakshmana on the head and said:', 'veda-app-ai-draft', true),
('ramayana-2-35-5', 'en', 'You are sent to live in the forest, devoted to your loved one. Do not be careless about Rama, son, as your brother goes.', 'veda-app-ai-draft', true),
('ramayana-2-35-6', 'en', 'In misfortune or prosperity he is your refuge, sinless one. This is the dharma of the good in the world, to obey the eldest.', 'veda-app-ai-draft', true),
('ramayana-2-35-7', 'en', 'This is the eternal, fitting conduct of this family: giving, consecration in sacrifices, and giving one''s body in battle.', 'veda-app-ai-draft', true),
('ramayana-2-35-8', 'en', 'Know Rama as Dasharatha, know Janaka''s daughter as me, know the forest as Ayodhya. Go, my son, happily.', 'veda-app-ai-draft', true),
('ramayana-2-35-9', 'en', 'Then Sumantra, humble and knowing courtesy, spoke to Kakutstha with folded hands, as Matali speaks to Indra:', 'veda-app-ai-draft', true),
('ramayana-2-35-10', 'en', 'Mount the chariot, bless you, famous prince. I will quickly take you wherever you tell me, Rama.', 'veda-app-ai-draft', true),
('ramayana-2-35-11', 'en', 'You must live fourteen years in the forest; they must begin, as the queen has urged.', 'veda-app-ai-draft', true),
('ramayana-2-35-12', 'en', 'Lovely Sita, having adorned herself, mounted that sun-bright chariot with a glad heart.', 'veda-app-ai-draft', true),
('ramayana-2-35-13', 'en', 'Placing the brothers'' weapons and armour in the chariot, along with the leather-covered basket,', 'veda-app-ai-draft', true),
('ramayana-2-35-14', 'en', 'seeing the three mounted with Sita, Sumantra boldly urged on the fine horses, swift as the wind.', 'veda-app-ai-draft', true),
('ramayana-2-35-15', 'en', 'As Raghava left for the great forest for so long, the city fainted, and the army and people fainted too.', 'veda-app-ai-draft', true),
('ramayana-2-35-16', 'en', 'The city was in uproar and confusion, with maddened, angry elephants and the neighing and jingling of horses.', 'veda-app-ai-draft', true),
('ramayana-2-35-17', 'en', 'Then the whole city, children and old, deeply pained, ran after Rama like the heat-struck to water.', 'veda-app-ai-draft', true),
('ramayana-2-35-18', 'en', 'Hanging on at the sides and behind, looking up at him, their faces full of tears, all said in deep sorrow:', 'veda-app-ai-draft', true),
('ramayana-2-35-19', 'en', 'Hold the horses'' reins, charioteer; go slowly, slowly. We want to see Rama''s face; soon it will be hard to see.', 'veda-app-ai-draft', true),
('ramayana-2-35-20', 'en', 'Surely Rama''s mother has a heart of iron, since it does not break as her god-like son goes to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-35-21', 'en', 'Vaidehi has done her duty, following her husband like a shadow; devoted to dharma, she does not leave him, as sunlight does not leave Meru.', 'veda-app-ai-draft', true),
('ramayana-2-35-22', 'en', 'Ah, Lakshmana, you have succeeded, for you will serve your god-like, ever kind-spoken brother.', 'veda-app-ai-draft', true),
('ramayana-2-35-23', 'en', 'This is a great achievement for you, a great rise, the road to heaven, that you follow him. Saying this, they could not hold back their tears.', 'veda-app-ai-draft', true),
('ramayana-2-35-24', 'en', 'Then the king, surrounded by his grieving wives, came out of the palace saying, I will see my dear son.', 'veda-app-ai-draft', true),
('ramayana-2-35-25', 'en', 'Ahead was heard a great cry of weeping women, like the cries of cow-elephants when a great bull elephant is bound.', 'veda-app-ai-draft', true),
('ramayana-2-35-26', 'en', 'Glorious King Kakutstha, the father, looked sunk, like the full moon eclipsed.', 'veda-app-ai-draft', true),
('ramayana-2-35-27', 'en', 'Then a tumult rose behind Rama, as the men saw the king sinking in deep sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-35-28', 'en', 'Some cried, Ah Rama! others, Ah Rama''s mother! and they mourned the wailing inner palace.', 'veda-app-ai-draft', true),
('ramayana-2-35-29', 'en', 'Looking back, Rama saw the king and his mother, dejected and confused, following on the road; bound by the noose of dharma, he did not look at them openly.', 'veda-app-ai-draft', true),
('ramayana-2-35-30', 'en', 'Seeing them on foot, who deserved carriages, unused to sorrow and used to comfort, he urged the charioteer, Go quickly.', 'veda-app-ai-draft', true),
('ramayana-2-35-31', 'en', 'The tiger among men could not bear the painful sight of his father and mother, like an elephant goaded by a spike.', 'veda-app-ai-draft', true),
('ramayana-2-35-32', 'en', 'He looked again and again at Kausalya running after the chariot, weeping, crying Rama, Rama! Ah Sita, Lakshmana! as if she were dancing.', 'veda-app-ai-draft', true),
('ramayana-2-35-33', 'en', 'Stop! cried the king. Go, go! said Raghava. Sumantra''s mind was as if caught between two wheels.', 'veda-app-ai-draft', true),
('ramayana-2-35-34', 'en', 'Even if reproached by the king, you can say, I did not hear. Long grief is worst of all, Rama told him.', 'veda-app-ai-draft', true),
('ramayana-2-35-35', 'en', 'Doing Rama''s word and taking leave of the people, the charioteer urged the already moving horses faster.', 'veda-app-ai-draft', true),
('ramayana-2-35-36', 'en', 'The king''s people walked round Rama and turned back, but in mind and tears they did not turn back.', 'veda-app-ai-draft', true),
('ramayana-2-35-37', 'en', 'One should not follow far someone one wishes to return, the ministers told great King Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-2-35-38', 'en', 'Hearing their wise words, the wretched king with his wives, sweating and dejected, stood looking at his son.', 'veda-app-ai-draft', true),
('ramayana-2-36-1', 'en', 'As that tiger among men left with folded hands, a great cry of distress rose among the women of the palace.', 'veda-app-ai-draft', true),
('ramayana-2-36-2', 'en', 'Where is he going, the protector who was the refuge and shelter of these helpless, weak, suffering people?', 'veda-app-ai-draft', true),
('ramayana-2-36-3', 'en', 'He did not get angry even when insulted, avoided what causes anger, soothed all who were angry and shared their sorrow; where is he going?', 'veda-app-ai-draft', true),
('ramayana-2-36-4', 'en', 'He treated us as he treated his own mother Kausalya; where is that great soul going?', 'veda-app-ai-draft', true),
('ramayana-2-36-5', 'en', 'Driven to the forest by the king, tormented by Kaikeyi, where is the saviour of these people and of the world going?', 'veda-app-ai-draft', true),
('ramayana-2-36-6', 'en', 'Ah, the king is senseless: Rama, beloved of the living world, righteous and true to his vows, will live in the forest!', 'veda-app-ai-draft', true),
('ramayana-2-36-7', 'en', 'So all those queens wept like cows bereft of their calves and cried aloud in sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-36-8', 'en', 'Hearing that terrible cry of grief in the inner palace, the king, burning with grief for his son, was deeply pained.', 'veda-app-ai-draft', true),
('ramayana-2-36-9', 'en', 'The fire offerings were not made, the sun disappeared, elephants dropped their food and cows did not suckle their calves.', 'veda-app-ai-draft', true),
('ramayana-2-36-10', 'en', 'Trishanku, Mars, Jupiter and Mercury, fierce planets, all stood near the moon.', 'veda-app-ai-draft', true),
('ramayana-2-36-11', 'en', 'The stars lost their light and the planets their brightness; the Vishakha stars shone in the sky as if in smoke.', 'veda-app-ai-draft', true),
('ramayana-2-36-12', 'en', 'Suddenly all the townspeople fell into misery; no one set his mind on eating or pleasure.', 'veda-app-ai-draft', true),
('ramayana-2-36-13', 'en', 'People on the royal road had tear-stained faces; no one looked happy; all were sunk in grief.', 'veda-app-ai-draft', true),
('ramayana-2-36-14', 'en', 'No cool wind blew, the moon looked unkind, the sun did not warm the world; the whole world was in turmoil.', 'veda-app-ai-draft', true),
('ramayana-2-36-15', 'en', 'Sons, women, husbands and brothers lost interest in each other; leaving everything, they thought only of Rama.', 'veda-app-ai-draft', true),
('ramayana-2-36-16', 'en', 'All Rama''s friends, their minds bewildered and crushed by grief, did not leave their beds.', 'veda-app-ai-draft', true),
('ramayana-2-36-17', 'en', 'Then Ayodhya, without that great soul, shook terribly under the weight of fear, like the earth with its mountains without Indra, and its elephants, warriors and horses cried out.', 'veda-app-ai-draft', true),
('ramayana-2-37-1', 'en', 'As long as the dust of his departure could be seen, the best of the Ikshvakus did not take his eyes away.', 'veda-app-ai-draft', true),
('ramayana-2-37-2', 'en', 'As long as the king could see his dear, righteous son, he seemed to grow taller on the earth to see him.', 'veda-app-ai-draft', true),
('ramayana-2-37-3', 'en', 'When the king could no longer see even the dust of Rama, he fell to the ground in pain and despair.', 'veda-app-ai-draft', true),
('ramayana-2-37-4', 'en', 'Kausalya went to his right arm, and Kaikeyi, who loved Bharata, to his left side.', 'veda-app-ai-draft', true),
('ramayana-2-37-5', 'en', 'The king, endowed with policy, dharma and discipline, looking at Kaikeyi with pained senses, said:', 'veda-app-ai-draft', true),
('ramayana-2-37-6', 'en', 'Kaikeyi, do not touch my body, evil woman. I do not want to see you; you are neither my wife nor my kin.', 'veda-app-ai-draft', true),
('ramayana-2-37-7', 'en', 'Those who live by you are not mine, nor I theirs. You care only for gain and have abandoned dharma; I abandon you.', 'veda-app-ai-draft', true),
('ramayana-2-37-8', 'en', 'That I took your hand and led you round the fire, I renounce it all, in this world and the next.', 'veda-app-ai-draft', true),
('ramayana-2-37-9', 'en', 'If Bharata is pleased at gaining this lasting kingdom, let whatever he offers for his father''s rites not reach me.', 'veda-app-ai-draft', true),
('ramayana-2-37-10', 'en', 'Then Queen Kausalya, worn with grief, raised the dust-covered king and turned back.', 'veda-app-ai-draft', true),
('ramayana-2-37-11', 'en', 'Like one who had killed a brahmin out of desire or touched fire with his hand, the righteous king burned with remorse thinking of his son as an ascetic.', 'veda-app-ai-draft', true),
('ramayana-2-37-12', 'en', 'Turning back again and again, sinking in the chariot tracks, the king did not shine, like the eclipsed sun.', 'veda-app-ai-draft', true),
('ramayana-2-37-13', 'en', 'Remembering his dear son, he lamented in sorrow; knowing his son had reached the city''s edge, he said:', 'veda-app-ai-draft', true),
('ramayana-2-37-14', 'en', 'The hoofprints of the fine horses that carry my son are seen on the road, but that great soul is not seen.', 'veda-app-ai-draft', true),
('ramayana-2-37-15', 'en', 'Surely today he will rest at the foot of some tree and sleep with a log or a stone for a pillow.', 'veda-app-ai-draft', true),
('ramayana-2-37-16', 'en', 'He will rise from the ground, wretched and covered in dust, sighing like a bull elephant leaving a spring of cow-elephants.', 'veda-app-ai-draft', true),
('ramayana-2-37-17', 'en', 'Surely forest dwellers will see long-armed Rama, lord of the world, rising and going on like one without a protector.', 'veda-app-ai-draft', true),
('ramayana-2-37-18', 'en', 'Have your wish, Kaikeyi; widowed, live in the kingdom. I cannot live without that tiger among men.', 'veda-app-ai-draft', true),
('ramayana-2-37-19', 'en', 'Lamenting like this, surrounded by crowds, the king entered the fine city like one entering a place of mourning.', 'veda-app-ai-draft', true),
('ramayana-2-37-20', 'en', 'Its squares and houses empty, its shops and shrines closed, its people weary, weak and grieving, its great roads not crowded,', 'veda-app-ai-draft', true),
('ramayana-2-37-21', 'en', 'looking at the whole city and thinking only of Rama, the king entered his house lamenting, like the sun entering a cloud.', 'veda-app-ai-draft', true),
('ramayana-2-37-22', 'en', 'The house without Rama, Vaidehi and Lakshmana was like a great still lake whose serpents Garuda has carried off.', 'veda-app-ai-draft', true),
('ramayana-2-37-23', 'en', 'Take me quickly to Kausalya''s house, Rama''s mother, the king said, and the doorkeepers took him.', 'veda-app-ai-draft', true),
('ramayana-2-37-24', 'en', 'Entering Kausalya''s quarters and lying on the bed, his mind was in turmoil.', 'veda-app-ai-draft', true),
('ramayana-2-37-25', 'en', 'Seeing that, the mighty great king raised his arm and cried loudly, Ah Raghava, you are leaving me!', 'veda-app-ai-draft', true),
('ramayana-2-37-26', 'en', 'Happy indeed will be the best of men who live to that time and embrace Rama when they see him return.', 'veda-app-ai-draft', true),
('ramayana-2-37-27', 'en', 'I cannot see you, Kausalya; touch me gently with your hand. My sight followed Rama and has not yet come back.', 'veda-app-ai-draft', true),
('ramayana-2-37-28', 'en', 'Seeing the king on the bed thinking only of Rama, the queen sat close beside him, more distressed still, sighing and lamenting painfully.', 'veda-app-ai-draft', true),
('ramayana-2-38-1', 'en', 'Then, seeing the king sunk with grief on the bed, Kausalya, tormented by grief for her son, said to him:', 'veda-app-ai-draft', true),
('ramayana-2-38-2', 'en', 'Having shed her poison on Raghava like a forked-tongued snake, Kaikeyi will roam free like a she-snake that has shed its skin.', 'veda-app-ai-draft', true),
('ramayana-2-38-3', 'en', 'Having banished Rama, lucky and satisfied, she will frighten me again like a wicked snake in the house.', 'veda-app-ai-draft', true),
('ramayana-2-38-4', 'en', 'Better if Rama had stayed in the city living by begging, or even been given as a servant, with her free to choose.', 'veda-app-ai-draft', true),
('ramayana-2-38-5', 'en', 'By letting Kaikeyi push Rama out of his place as she wished, you have thrown the rakshasas their share, like a fire-keeper on a holy day.', 'veda-app-ai-draft', true),
('ramayana-2-38-6', 'en', 'Surely the hero, walking like a king elephant, long-armed, carrying a bow, is entering the forest with his wife and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-38-7', 'en', 'Abandoned to the forest by you with Kaikeyi''s consent, they who have never known sorrow, what will become of them?', 'veda-app-ai-draft', true),
('ramayana-2-38-8', 'en', 'Young, stripped of their jewels, banished at the time of enjoying life''s fruits, how will those poor ones live, eating fruits and roots?', 'veda-app-ai-draft', true),
('ramayana-2-38-9', 'en', 'Will that blessed time come now, the end of my sorrow, when I see Raghava here with his wife and brother?', 'veda-app-ai-draft', true),
('ramayana-2-38-10', 'en', 'When will Ayodhya, hearing that the two heroes are here, be glorious and full of joyful people, garlanded with raised flags?', 'veda-app-ai-draft', true),
('ramayana-2-38-11', 'en', 'When will the city, seeing the two tigers among men back from the forest, rejoice like the sea at full moon?', 'veda-app-ai-draft', true),
('ramayana-2-38-12', 'en', 'When will the mighty-armed hero enter Ayodhya with Sita before him in the chariot, like a bull with his cow?', 'veda-app-ai-draft', true),
('ramayana-2-38-13', 'en', 'When will thousands of people scatter parched rice on my two sons, the tamers of foes, as they enter on the royal road?', 'veda-app-ai-draft', true),
('ramayana-2-38-14', 'en', 'When will brahmin girls, giving flowers and fruits, joyfully walk round the city?', 'veda-app-ai-draft', true),
('ramayana-2-38-15', 'en', 'When will he, mature in mind and age, god-like and knowing dharma, come to me playfully like a three-year-old?', 'veda-app-ai-draft', true),
('ramayana-2-38-16', 'en', 'No doubt, hero, I must once, being cruel, have cut off mothers'' teats when their calves wanted to drink.', 'veda-app-ai-draft', true),
('ramayana-2-38-17', 'en', 'I, loving, have been made calfless by Kaikeyi, like a cow by a lion, a cow with a young calf taken by force.', 'veda-app-ai-draft', true),
('ramayana-2-38-18', 'en', 'With only one son, I cannot live without that son, endowed with virtues and skilled in every science.', 'veda-app-ai-draft', true),
('ramayana-2-38-19', 'en', 'I have no strength left to live, not seeing my dear, mighty-armed, powerful son.', 'veda-app-ai-draft', true),
('ramayana-2-38-20', 'en', 'This fire born of grief for my son burns me, as the blazing sun burns the earth with its rays in summer.', 'veda-app-ai-draft', true),
('ramayana-2-39-1', 'en', 'To Kausalya, finest of women, lamenting like this, Sumitra, steady in dharma, spoke righteous words:', 'veda-app-ai-draft', true),
('ramayana-2-39-2', 'en', 'Noble lady, your son, the best of men, has true virtues. Why lament and weep so pitifully?', 'veda-app-ai-draft', true),
('ramayana-2-39-3', 'en', 'Your mighty son who has gone, giving up the kingdom, does right by making his great father true to his word.', 'veda-app-ai-draft', true),
('ramayana-2-39-4', 'en', 'Rama stands in dharma, practised by the good, whose fruit always comes hereafter; that best one is never to be grieved for.', 'veda-app-ai-draft', true),
('ramayana-2-39-5', 'en', 'And sinless Lakshmana always serves him in the best way, compassionate to all beings; that is a gain for that great soul.', 'veda-app-ai-draft', true),
('ramayana-2-39-6', 'en', 'Vaidehi, used to comfort and knowing the hardship of forest life, follows your righteous son.', 'veda-app-ai-draft', true),
('ramayana-2-39-7', 'en', 'What has your son not gained, the lord who waves the banner of fame through the world, devoted to self-control, truth and vows?', 'veda-app-ai-draft', true),
('ramayana-2-39-8', 'en', 'Surely the sun, knowing Rama''s purity and greatness, will not burn his body with its rays.', 'veda-app-ai-draft', true),
('ramayana-2-39-9', 'en', 'A pleasant, gentle wind, cool or warm as needed, will come from the forests and attend Raghava at all times.', 'veda-app-ai-draft', true),
('ramayana-2-39-10', 'en', 'As the sinless one sleeps at night, the moon will embrace him like a father and delight him with its cool rays.', 'veda-app-ai-draft', true),
('ramayana-2-39-11', 'en', 'Brahma gave divine weapons to that mighty one after seeing him kill the demon lord, son of Timidhvaja, in battle.', 'veda-app-ai-draft', true),
('ramayana-2-39-12', 'en', 'The bull among men will soon be crowned with these three: the earth, Vaidehi and Fortune.', 'veda-app-ai-draft', true),
('ramayana-2-39-13', 'en', 'You who shed tears of sorrow seeing him leave will soon shed tears of joy.', 'veda-app-ai-draft', true),
('ramayana-2-39-14', 'en', 'Seeing your son bow to you with his friends, you will soon shed tears of joy like a rain cloud.', 'veda-app-ai-draft', true),
('ramayana-2-39-15', 'en', 'Your boon-giving son, returned soon to Ayodhya, will press your feet with his soft, strong hands.', 'veda-app-ai-draft', true),
('ramayana-2-39-16', 'en', 'Hearing these words of Lakshmana''s mother, the grief in the body of Rama''s mother, the king''s wife, vanished at once, like a small autumn cloud.', 'veda-app-ai-draft', true),
('ramayana-2-40-1', 'en', 'Devoted to great Rama, true in valour, people followed him as he left to live in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-40-2', 'en', 'Even when the king and his friends were made to turn back, those following Rama''s chariot did not turn back.', 'veda-app-ai-draft', true),
('ramayana-2-40-3', 'en', 'For the people of Ayodhya, the famous, virtuous one was dear like the full moon.', 'veda-app-ai-draft', true),
('ramayana-2-40-4', 'en', 'Begged by his own people, Kakutstha, making his father truthful, went on to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-40-5', 'en', 'Looking at them lovingly, as if drinking them in with his eyes, Rama spoke affectionately to his people as if they were his children.', 'veda-app-ai-draft', true),
('ramayana-2-40-6', 'en', 'The love and respect the people of Ayodhya have for me, for my sake give it especially to Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-40-7', 'en', 'He is of good character, the joy of Kaikeyi; he will do what pleases and benefits you properly.', 'veda-app-ai-draft', true),
('ramayana-2-40-8', 'en', 'Old in wisdom though young in years, gentle yet strong and valiant, he will be a fitting master who removes your fear.', 'veda-app-ai-draft', true),
('ramayana-2-40-9', 'en', 'He has the qualities of a king and has been chosen crown prince; and you must do as your master commands, as I tell you.', 'veda-app-ai-draft', true),
('ramayana-2-40-10', 'en', 'And for my sake, make sure the great king does not grieve when I have gone to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-40-11', 'en', 'The more Dasharatha''s son stood by dharma, the more the people wanted Rama as their lord.', 'veda-app-ai-draft', true),
('ramayana-2-40-12', 'en', 'Rama with Saumitri seemed to bind the tearful, wretched people with cords of virtue and pull them along.', 'veda-app-ai-draft', true),
('ramayana-2-40-13', 'en', 'Those brahmins, old in three ways, in knowledge, age and power, their heads shaking with age, called from afar:', 'veda-app-ai-draft', true),
('ramayana-2-40-14', 'en', 'Swift thoroughbred horses carrying Rama, turn back, do not go; be good to your master. Your master should be carried towards the city, not away from it to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-40-15', 'en', 'Seeing those old brahmins lamenting so, Rama suddenly got down from the chariot.', 'veda-app-ai-draft', true),
('ramayana-2-40-16', 'en', 'Rama went on foot with Sita and Lakshmana, taking short steps, set on the forest.', 'veda-app-ai-draft', true),
('ramayana-2-40-17', 'en', 'Rama, who loved good conduct, his eyes full of compassion, could not leave the brahmins on foot behind by riding.', 'veda-app-ai-draft', true),
('ramayana-2-40-18', 'en', 'Seeing Rama still going, the brahmins, deeply troubled and pained, said:', 'veda-app-ai-draft', true),
('ramayana-2-40-19', 'en', 'All the brahmin class follows you, friend of brahmins; even our sacred fires follow you, carried on our shoulders.', 'veda-app-ai-draft', true),
('ramayana-2-40-20', 'en', 'See our parasols from the Vajapeya sacrifice following behind, like swans after the rains.', 'veda-app-ai-draft', true),
('ramayana-2-40-21', 'en', 'You have no royal umbrella and are scorched by the sun; we will make shade for you with our own Vajapeya parasols.', 'veda-app-ai-draft', true),
('ramayana-2-40-22', 'en', 'Our minds, always following the Vedic mantras, for your sake now follow your forest life, dear child.', 'veda-app-ai-draft', true),
('ramayana-2-40-23', 'en', 'The Vedas, our highest wealth, live in our hearts; our wives, guarded by their conduct, will stay at home.', 'veda-app-ai-draft', true),
('ramayana-2-40-24', 'en', 'We will not change our resolve; our mind is set on going with you. But if you care for dharma, what better dharma is there to consider?', 'veda-app-ai-draft', true),
('ramayana-2-40-25', 'en', 'We beg you with our swan-white heads dusty from bowing to the ground: turn back, you of good conduct.', 'veda-app-ai-draft', true),
('ramayana-2-40-26', 'en', 'Many brahmins who have come here have begun sacrifices; their completion depends on your return, child.', 'veda-app-ai-draft', true),
('ramayana-2-40-27', 'en', 'All beings, moving and unmoving, are devoted to you; show devotion to your devotees as they beg.', 'veda-app-ai-draft', true),
('ramayana-2-40-28', 'en', 'Unable to follow you, held by their roots, the trees, swaying in the wind, seem to cry out.', 'veda-app-ai-draft', true),
('ramayana-2-40-29', 'en', 'Even the birds, motionless, not eating or moving, perched in one place on the trees, beg you, compassionate to all beings.', 'veda-app-ai-draft', true),
('ramayana-2-40-30', 'en', 'As the brahmins cried out for him to return, the river Tamasa appeared, as if to stop Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-41-1', 'en', 'Reaching the lovely bank of the Tamasa, Raghava looked at Sita and said to Saumitri:', 'veda-app-ai-draft', true),
('ramayana-2-41-2', 'en', 'This is the first night since we set out for the forest, Saumitri. Bless you, do not feel homesick for forest life.', 'veda-app-ai-draft', true),
('ramayana-2-41-3', 'en', 'See the empty forests all around, seeming to weep, the deer and birds settling into their homes.', 'veda-app-ai-draft', true),
('ramayana-2-41-4', 'en', 'Today Ayodhya, my father''s capital, will grieve for us who have gone, men and women alike, no doubt.', 'veda-app-ai-draft', true),
('ramayana-2-41-5', 'en', 'Surely righteous Bharata will comfort my father and mother with words full of dharma, purpose and love.', 'veda-app-ai-draft', true),
('ramayana-2-41-6', 'en', 'Thinking again and again of Bharata''s kindness, I do not grieve for my father and mother, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-41-7', 'en', 'By following me, tiger among men, you have done what needed doing; help must be found to protect Vaidehi.', 'veda-app-ai-draft', true),
('ramayana-2-41-8', 'en', 'Tonight I will live on water alone, Saumitri; that pleases me, though there are many forest foods.', 'veda-app-ai-draft', true),
('ramayana-2-41-9', 'en', 'Having said this to Saumitri, Raghava said to Sumantra: Take care of the horses, gentle one.', 'veda-app-ai-draft', true),
('ramayana-2-41-10', 'en', 'When the sun had set, Sumantra tethered the horses, gave them plenty of fodder and waited nearby.', 'veda-app-ai-draft', true),
('ramayana-2-41-11', 'en', 'Having performed the evening prayer and seeing night had come, the charioteer with Saumitri made a bed for Rama.', 'veda-app-ai-draft', true),
('ramayana-2-41-12', 'en', 'Seeing that bed of leaves on the Tamasa bank, Rama lay down with his wife, with Saumitri nearby.', 'veda-app-ai-draft', true),
('ramayana-2-41-13', 'en', 'Seeing his brother asleep with his wife, Lakshmana told the charioteer of Rama''s many virtues.', 'veda-app-ai-draft', true),
('ramayana-2-41-14', 'en', 'The sun rose while Saumitri was still awake, telling the charioteer of Rama''s virtues on the Tamasa bank.', 'veda-app-ai-draft', true),
('ramayana-2-41-15', 'en', 'Not far from the Tamasa, its banks crowded with herds of cattle, Rama spent that night with the people.', 'veda-app-ai-draft', true),
('ramayana-2-41-16', 'en', 'Rising, mighty Rama, seeing those people, said to his brother Lakshmana of auspicious marks:', 'veda-app-ai-draft', true),
('ramayana-2-41-17', 'en', 'Saumitri, see these who care for us and not even for their homes, sleeping now at the roots of trees, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-41-18', 'en', 'Just as these citizens are determined to bring us back, they will give up their lives sooner than their resolve.', 'veda-app-ai-draft', true),
('ramayana-2-41-19', 'en', 'While they are still asleep, let us quickly mount the chariot and go on a path free from fear.', 'veda-app-ai-draft', true),
('ramayana-2-41-20', 'en', 'Then the loyal people of the Ikshvaku city will not again sleep at the roots of trees because of me.', 'veda-app-ai-draft', true),
('ramayana-2-41-21', 'en', 'Princes should free the citizens from the sorrows they bring on themselves, not tie them to their own sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-41-22', 'en', 'Lakshmana said to Rama, who stood like dharma itself: I agree, wise one; let us mount quickly.', 'veda-app-ai-draft', true),
('ramayana-2-41-23', 'en', 'The charioteer quickly yoked the chariot with those fine horses and, with folded hands, told Rama.', 'veda-app-ai-draft', true),
('ramayana-2-41-24', 'en', 'To mislead the citizens, Rama told the charioteer: Mount the chariot and drive north, charioteer.', 'veda-app-ai-draft', true),
('ramayana-2-41-25', 'en', 'Go quickly for a while, then bring the chariot back; do it carefully so the citizens do not know where I am.', 'veda-app-ai-draft', true),
('ramayana-2-41-26', 'en', 'Hearing Rama, the charioteer did so, and returning, presented the chariot to Rama.', 'veda-app-ai-draft', true),
('ramayana-2-41-27', 'en', 'Mounting the chariot with his companions, Raghava crossed the swift, eddying river Tamasa.', 'veda-app-ai-draft', true),
('ramayana-2-41-28', 'en', 'Having crossed, the glorious mighty-armed one reached the great road, safe and free of thorns, fearless even for those who fear.', 'veda-app-ai-draft', true),
('ramayana-2-41-29', 'en', 'When night turned to dawn, the citizens, without Raghava, stunned with grief, became motionless and lost heart.', 'veda-app-ai-draft', true),
('ramayana-2-41-30', 'en', 'Worn with tears of grief, looking here and there, the grieving people could not see even a trace of Rama.', 'veda-app-ai-draft', true),
('ramayana-2-41-31', 'en', 'Following the track for a while and losing it, they were overwhelmed with deep despair.', 'veda-app-ai-draft', true),
('ramayana-2-41-32', 'en', 'When the chariot tracks were lost, the high-minded people turned back: What is this? What shall we do? We are struck by fate.', 'veda-app-ai-draft', true),
('ramayana-2-41-33', 'en', 'Then all of them, weary at heart, went back the way they had come to Ayodhya, a city of grieving good people.', 'veda-app-ai-draft', true),
('ramayana-2-42-1', 'en', 'The townspeople who followed Rama and returned were downcast, as if their life had left them.', 'veda-app-ai-draft', true),
('ramayana-2-42-2', 'en', 'Reaching their homes, surrounded by sons and wives, all wept, their faces covered with tears.', 'veda-app-ai-draft', true),
('ramayana-2-42-3', 'en', 'Merchants did not rejoice or celebrate or spread their wares; goods did not shine and householders did not cook.', 'veda-app-ai-draft', true),
('ramayana-2-42-4', 'en', 'Seeing something lost found, or great wealth gained, no one rejoiced; a mother did not rejoice at the birth of her first son.', 'veda-app-ai-draft', true),
('ramayana-2-42-5', 'en', 'In every house, women weeping in sorrow reproached their husbands who had come home, with words like goads to elephants.', 'veda-app-ai-draft', true),
('ramayana-2-42-6', 'en', 'What use are houses, wives, wealth, sons or pleasures to those who do not see Raghava?', 'veda-app-ai-draft', true),
('ramayana-2-42-7', 'en', 'Lakshmana with Sita is the one good man in the world, who follows Kakutstha Rama and serves him in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-42-8', 'en', 'Blessed are the rivers, lotus ponds and lakes where Kakutstha will bathe, plunging into their pure water.', 'veda-app-ai-draft', true),
('ramayana-2-42-9', 'en', 'The lovely woods, great river marshes and peaked mountains will adorn Kakutstha.', 'veda-app-ai-draft', true),
('ramayana-2-42-10', 'en', 'Whatever forest or mountain Rama goes to will not be able to fail to honour him, like a dear guest arriving.', 'veda-app-ai-draft', true),
('ramayana-2-42-11', 'en', 'Wearing crowns of colourful flowers and many blossoms, the mountains out of compassion will show Rama the best flowers and fruits, even out of season.', 'veda-app-ai-draft', true),
('ramayana-2-42-12', 'en', 'Showing many colourful waterfalls again and again, the trees on mountain tops will delight Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-42-13', 'en', 'Where Rama is, there is no fear and no defeat, for he is a hero, mighty-armed, the son of Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-2-42-14', 'en', 'Before he gets too far, let us follow Raghava. The shade of the feet of such a great master is sweet; he is the people''s protector, refuge and final goal.', 'veda-app-ai-draft', true),
('ramayana-2-42-15', 'en', 'We will serve Sita and you will serve Raghava, the city''s women told their husbands in their grief.', 'veda-app-ai-draft', true),
('ramayana-2-42-16', 'en', 'Raghava will provide for your welfare in the forest, and Sita will provide for the welfare of the women.', 'veda-app-ai-draft', true),
('ramayana-2-42-17', 'en', 'Who could enjoy this unwelcome dwelling, joyless, its people yearning, its heart stolen?', 'veda-app-ai-draft', true),
('ramayana-2-42-18', 'en', 'If the kingdom is Kaikeyi''s, unjust and without a protector, we have no use for life, let alone sons or wealth.', 'veda-app-ai-draft', true),
('ramayana-2-42-19', 'en', 'Kaikeyi, disgrace of her family, who abandoned son and husband for power, whom else would she spare?', 'veda-app-ai-draft', true),
('ramayana-2-42-20', 'en', 'We will not live as servants in Kaikeyi''s kingdom while she lives; we swear it by our sons.', 'veda-app-ai-draft', true),
('ramayana-2-42-21', 'en', 'Who could live happily under that pitiless, unrighteous, wicked woman who banishes the king''s son?', 'veda-app-ai-draft', true),
('ramayana-2-42-22', 'en', 'With Rama gone, the king will not live; when Dasharatha dies, ruin will clearly follow.', 'veda-app-ai-draft', true),
('ramayana-2-42-23', 'en', 'You whose merit is spent, drink poison mixed in water, or follow Raghava, or go where no one hears of you.', 'veda-app-ai-draft', true),
('ramayana-2-42-24', 'en', 'Rama has been banished on a false pretext with his wife and Lakshmana; we have been handed to Bharata like animals to a butcher.', 'veda-app-ai-draft', true),
('ramayana-2-42-25', 'en', 'So the women of the city lamented, crying out in deep pain as if death were coming.', 'veda-app-ai-draft', true),
('ramayana-2-42-26', 'en', 'The women, distressed for Rama as if their own son or brother were exiled, lamented and wept wretchedly, out of their senses, for he was dearer to them than their sons.', 'veda-app-ai-draft', true),
('ramayana-2-43-1', 'en', 'Rama too, tiger among men, travelled a great distance in the rest of that night, remembering his father''s command.', 'veda-app-ai-draft', true),
('ramayana-2-43-2', 'en', 'As he went, the blessed night passed; having performed the auspicious dawn prayer, he reached the edge of the country.', 'veda-app-ai-draft', true),
('ramayana-2-43-3', 'en', 'Seeing villages with wide-ploughed fields and flowering forests, he went swiftly on with fine horses like arrows.', 'veda-app-ai-draft', true),
('ramayana-2-43-4', 'en', 'He heard the words of people living in the villages: Shame on King Dasharatha, ruled by desire!', 'veda-app-ai-draft', true),
('ramayana-2-43-5', 'en', 'Ah, cruel, wicked Kaikeyi, bound to evil, harsh, breaking all bounds, is engaged in a cruel deed,', 'veda-app-ai-draft', true),
('ramayana-2-43-6', 'en', 'banishing to forest life such a righteous son of the king, wise, compassionate and tireless.', 'veda-app-ai-draft', true),
('ramayana-2-43-7', 'en', 'Hearing these words of the villagers, the heroic lord of Kosala passed through Kosala.', 'veda-app-ai-draft', true),
('ramayana-2-43-8', 'en', 'Then crossing the Vedashruti river with its auspicious water, he went on towards the direction where Agastya lived.', 'veda-app-ai-draft', true),
('ramayana-2-43-9', 'en', 'After going a long time, he crossed the cool Gomati river flowing to the sea, its marshes full of cattle.', 'veda-app-ai-draft', true),
('ramayana-2-43-10', 'en', 'Crossing the Gomati with swift horses, Raghava crossed the Syandika river, echoing with peacocks and swans.', 'veda-app-ai-draft', true),
('ramayana-2-43-11', 'en', 'Rama showed Vaidehi the rich land, full of kingdoms, that King Manu once gave to Ikshvaku.', 'veda-app-ai-draft', true),
('ramayana-2-43-12', 'en', 'Calling the charioteer again and again, Charioteer!, the glorious best of men, his voice like an excited swan''s, said:', 'veda-app-ai-draft', true),
('ramayana-2-43-13', 'en', 'When will I return and hunt again in the flowering woods of the Sarayu, together with my mother and father?', 'veda-app-ai-draft', true),
('ramayana-2-43-14', 'en', 'I do not greatly long for hunting in the Sarayu woods; it is a matchless pleasure in the world, approved by the royal sages.', 'veda-app-ai-draft', true),
('ramayana-2-43-15', 'en', 'Speaking sweetly to the charioteer about one thing after another, the Ikshvaku went along that road.', 'veda-app-ai-draft', true),
('ramayana-2-44-1', 'en', 'Having passed through broad, lovely Kosala, Lakshmana''s elder, mighty-armed, reached Shringaverapura.', 'veda-app-ai-draft', true),
('ramayana-2-44-2', 'en', 'There Raghava saw the divine Ganga, flowing through three worlds, with clear, weedless water, holy and visited by sages.', 'veda-app-ai-draft', true),
('ramayana-2-44-3', 'en', 'Echoing with swans and cranes, ringing with ruddy geese, inhabited by dolphins, crocodiles and serpents,', 'veda-app-ai-draft', true),
('ramayana-2-44-4', 'en', 'Seeing her with her waves and whirlpools, the great warrior said to the charioteer Sumantra: We will stay right here today.', 'veda-app-ai-draft', true),
('ramayana-2-44-5', 'en', 'Not far from the river is a great ingudi tree full of flowers and shoots; let us stay right here, charioteer.', 'veda-app-ai-draft', true),
('ramayana-2-44-6', 'en', 'Lakshmana and Sumantra said Very well to Raghava and drove the horses to that ingudi tree.', 'veda-app-ai-draft', true),
('ramayana-2-44-7', 'en', 'Reaching that lovely tree, Rama, joy of the Ikshvakus, got down from the chariot with his wife and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-44-8', 'en', 'Sumantra too got down, unyoked the fine horses and stood with folded hands before Rama at the tree''s foot.', 'veda-app-ai-draft', true),
('ramayana-2-44-9', 'en', 'There was a king there named Guha, Rama''s friend dear as his own self, of the Nishada people, strong, and known as a chieftain.', 'veda-app-ai-draft', true),
('ramayana-2-44-10', 'en', 'Hearing that Rama, tiger among men, had come to his land, he came surrounded by elders, ministers and kin.', 'veda-app-ai-draft', true),
('ramayana-2-44-11', 'en', 'Seeing the lord of the Nishadas standing at a distance, Rama with Saumitri went to meet Guha.', 'veda-app-ai-draft', true),
('ramayana-2-44-12', 'en', 'Distressed, Guha embraced Raghava and said: This land is yours as Ayodhya is, Rama. What can I do for you?', 'veda-app-ai-draft', true),
('ramayana-2-44-13', 'en', 'Then he quickly brought fine food of many kinds and water of welcome and said:', 'veda-app-ai-draft', true),
('ramayana-2-44-14', 'en', 'Welcome, mighty-armed one; this whole land is yours. We are your servants and you our master; rule our kingdom well.', 'veda-app-ai-draft', true),
('ramayana-2-44-15', 'en', 'Here are things to eat, chew, drink and lick, fine beds, and fodder for your horses.', 'veda-app-ai-draft', true),
('ramayana-2-44-16', 'en', 'Raghava replied to Guha as he spoke: We are honoured and delighted by you in every way.', 'veda-app-ai-draft', true),
('ramayana-2-44-17', 'en', 'Pressing him with his strong, noble arms, for coming on foot and showing his love, he said:', 'veda-app-ai-draft', true),
('ramayana-2-44-18', 'en', 'Happily I see you well with your kin, Guha. Is all well in your kingdom, with your friends and wealth?', 'veda-app-ai-draft', true),
('ramayana-2-44-19', 'en', 'Whatever you have lovingly prepared, I accept it all in spirit, but I do not take gifts now.', 'veda-app-ai-draft', true),
('ramayana-2-44-20', 'en', 'Know me as an ascetic living in the forest, wearing kusha, bark and deerskin, eating fruits and roots, devoted to dharma.', 'veda-app-ai-draft', true),
('ramayana-2-44-21', 'en', 'I need only fodder for the horses, nothing else. With this alone I will be well honoured by you.', 'veda-app-ai-draft', true),
('ramayana-2-44-22', 'en', 'These horses are dear to my father, King Dasharatha; if they are well cared for, I will feel honoured.', 'veda-app-ai-draft', true),
('ramayana-2-44-23', 'en', 'Guha at once ordered his men to give water and fodder to the horses quickly.', 'veda-app-ai-draft', true),
('ramayana-2-44-24', 'en', 'Then, wearing his bark upper garment, having performed the evening prayer, he took only water, brought by Lakshmana himself, as his food.', 'veda-app-ai-draft', true),
('ramayana-2-44-25', 'en', 'Lakshmana washed the feet of Rama and his wife as they lay on the ground, then went and stood leaning against a tree.', 'veda-app-ai-draft', true),
('ramayana-2-44-26', 'en', 'Guha too, with the charioteer, talking with Saumitri, kept awake beside Rama, alert, bow in hand.', 'veda-app-ai-draft', true),
('ramayana-2-44-27', 'en', 'So the night passed slowly for the wise, famous, great-souled son of Dasharatha, lying there, who had never known sorrow and was used to comfort.', 'veda-app-ai-draft', true),
('ramayana-2-45-1', 'en', 'Seeing Lakshmana awake without pretence for his brother''s sake, Guha, pained, said to Raghava''s brother:', 'veda-app-ai-draft', true),
('ramayana-2-45-2', 'en', 'This comfortable bed has been made for you, dear one; rest well on it, prince, as you like.', 'veda-app-ai-draft', true),
('ramayana-2-45-3', 'en', 'All these people are used to hardship, but you are used to comfort. We will stay awake tonight to guard Kakutstha.', 'veda-app-ai-draft', true),
('ramayana-2-45-4', 'en', 'No one on earth is dearer to me than Rama; I say this truly and swear it by truth.', 'veda-app-ai-draft', true),
('ramayana-2-45-5', 'en', 'By his grace I hope for great fame in this world, abundant dharma and wealth.', 'veda-app-ai-draft', true),
('ramayana-2-45-6', 'en', 'So I will guard my dear friend Rama as he sleeps with Sita, bow in hand, on every side with my kin.', 'veda-app-ai-draft', true),
('ramayana-2-45-7', 'en', 'There is nothing in this forest I do not know, as I always roam it; we could withstand even a great four-part army.', 'veda-app-ai-draft', true),
('ramayana-2-45-8', 'en', 'Lakshmana said to him: Protected by you, sinless one, none of us fears here, watching only over dharma.', 'veda-app-ai-draft', true),
('ramayana-2-45-9', 'en', 'How can I sleep, or care for life or pleasure, while Dasharatha''s son lies on the ground with Sita?', 'veda-app-ai-draft', true),
('ramayana-2-45-10', 'en', 'See him, whom all the gods and demons together could not overcome in battle, lying comfortably on grass with Sita.', 'veda-app-ai-draft', true),
('ramayana-2-45-11', 'en', 'He, won by mantras, austerity and many efforts, is Dasharatha''s one son with the same marks as his father.', 'veda-app-ai-draft', true),
('ramayana-2-45-12', 'en', 'With him banished, the king will not live long; surely the earth will soon be widowed.', 'veda-app-ai-draft', true),
('ramayana-2-45-13', 'en', 'The women, having cried aloud, have surely fallen silent from exhaustion; I think the royal palace is now hushed.', 'veda-app-ai-draft', true),
('ramayana-2-45-14', 'en', 'Kausalya, the king and my own mother: I do not expect they will all live through this night.', 'veda-app-ai-draft', true),
('ramayana-2-45-15', 'en', 'My mother may live, watching over Shatrughna; but it is a sorrow that Kausalya, mother of a hero, will perish.', 'veda-app-ai-draft', true),
('ramayana-2-45-16', 'en', 'That city, full of loving people, a joy to see, struck by the king''s misfortune, will be ruined.', 'veda-app-ai-draft', true),
('ramayana-2-45-17', 'en', 'Not having achieved his wish as time passed, not having placed Rama on the throne, my father will die.', 'veda-app-ai-draft', true),
('ramayana-2-45-18', 'en', 'Those who are there at that time will be fortunate and will perform all the funeral rites for the king.', 'veda-app-ai-draft', true),
('ramayana-2-45-19', 'en', 'Its lovely squares, well-laid great roads, mansions and palaces, adorned with fine courtesans,', 'veda-app-ai-draft', true),
('ramayana-2-45-20', 'en', 'crowded with chariots, horses and elephants, ringing with music, full of every good thing and happy, well-fed people,', 'veda-app-ai-draft', true),
('ramayana-2-45-21', 'en', 'rich in parks and gardens, splendid with gatherings and festivals: happy are those who will walk in my father''s capital.', 'veda-app-ai-draft', true),
('ramayana-2-45-22', 'en', 'May we, with the one true to his promise, safely enter Ayodhya again when this forest exile is over.', 'veda-app-ai-draft', true),
('ramayana-2-45-23', 'en', 'As the great-souled prince stood lamenting in sorrow, that night passed.', 'veda-app-ai-draft', true),
('ramayana-2-45-24', 'en', 'As the king''s son spoke truthfully for the good of the people, Guha, out of love for his elder, shed tears, struck by grief, like an elephant in fever.', 'veda-app-ai-draft', true),
('ramayana-2-46-1', 'en', 'When night turned to dawn, famous, broad-chested Rama spoke to Saumitri Lakshmana of auspicious marks:', 'veda-app-ai-draft', true),
('ramayana-2-46-2', 'en', 'This is the time of sunrise; the blessed night has gone. That jet-black bird, the cuckoo, is calling, dear.', 'veda-app-ai-draft', true),
('ramayana-2-46-3', 'en', 'The cries of peacocks calling in the forest are heard. Let us cross the swift Jahnavi flowing to the sea, gentle one.', 'veda-app-ai-draft', true),
('ramayana-2-46-4', 'en', 'Understanding Rama, Saumitri, joy of his friends, called Guha and the charioteer and stood before his brother.', 'veda-app-ai-draft', true),
('ramayana-2-46-5', 'en', 'Then the two Raghava archers, putting on their quivers and girding their swords, went with Sita towards the Ganga.', 'veda-app-ai-draft', true),
('ramayana-2-46-6', 'en', 'The charioteer, humbly approaching righteous Rama, said with folded hands: What shall I do?', 'veda-app-ai-draft', true),
('ramayana-2-46-7', 'en', 'Go back, he said; this is all you need to do. Leaving the chariot, we will go on foot into the great forest.', 'veda-app-ai-draft', true),
('ramayana-2-46-8', 'en', 'Seeing himself dismissed, the distressed charioteer Sumantra said to the Ikshvaku tiger among men:', 'veda-app-ai-draft', true),
('ramayana-2-46-9', 'en', 'No man in this world has ever had to endure this: that you live in the forest like a common man with your brother and wife.', 'veda-app-ai-draft', true),
('ramayana-2-46-10', 'en', 'I do not think there is any fruit in chastity, study, gentleness or honesty, if misfortune has come to you.', 'veda-app-ai-draft', true),
('ramayana-2-46-11', 'en', 'Living in the forest with Vaidehi and your brother, Raghava, you will reach the highest goal, as if conquering the three worlds.', 'veda-app-ai-draft', true),
('ramayana-2-46-12', 'en', 'We are the ones destroyed, Rama, deceived by her too; we will fall into the power of wicked Kaikeyi and share in sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-46-13', 'en', 'Saying this to one like himself, the charioteer Sumantra, seeing Rama about to go far, wept long in sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-46-14', 'en', 'When his tears had stopped and he had touched water and was pure, Rama spoke to the charioteer sweetly again and again:', 'veda-app-ai-draft', true),
('ramayana-2-46-15', 'en', 'I see no friend of the Ikshvakus equal to you. Act so that King Dasharatha does not grieve for me.', 'veda-app-ai-draft', true),
('ramayana-2-46-16', 'en', 'The lord of the earth is old, his mind struck by grief and weighed down by desire; that is why I tell you this.', 'veda-app-ai-draft', true),
('ramayana-2-46-17', 'en', 'Whatever the great king commands to please Kaikeyi, do it without hesitation.', 'veda-app-ai-draft', true),
('ramayana-2-46-18', 'en', 'For this is why kings rule kingdoms: that their will is not thwarted in any task.', 'veda-app-ai-draft', true),
('ramayana-2-46-19', 'en', 'So, Sumantra, act so that the great king does not meet with falsehood or suffer from sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-46-20', 'en', 'Bowing to the king, old, noble, self-controlled, who has never known sorrow, tell him this from me:', 'veda-app-ai-draft', true),
('ramayana-2-46-21', 'en', 'Neither I, nor Lakshmana, nor Maithili grieve at having left Ayodhya or at having to live in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-46-22', 'en', 'When the fourteen years are over, you will soon see Lakshmana, me and Sita come back again.', 'veda-app-ai-draft', true),
('ramayana-2-46-23', 'en', 'Having said this to the king and my mother, Sumantra, and to the other queens together, and to Kaikeyi again and again,', 'veda-app-ai-draft', true),
('ramayana-2-46-24', 'en', 'tell Kausalya we are well and touch her feet for Sita, for me and for noble Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-46-25', 'en', 'And tell the great king: Bring Bharata quickly, and when Bharata comes, set him in the place the king intends.', 'veda-app-ai-draft', true),
('ramayana-2-46-26', 'en', 'Embrace Bharata and crown him crown prince; then the sorrow born of our suffering will not overwhelm you.', 'veda-app-ai-draft', true),
('ramayana-2-46-27', 'en', 'And tell Bharata: As you treat the king, so treat all the mothers without distinction.', 'veda-app-ai-draft', true),
('ramayana-2-46-28', 'en', 'As Kaikeyi is to you, so are Sumitra and, especially, Queen Kausalya, my mother.', 'veda-app-ai-draft', true),
('ramayana-2-46-29', 'en', 'Sent back by Rama, Sumantra, worn with grief, hearing all this, said lovingly to Kakutstha:', 'veda-app-ai-draft', true),
('ramayana-2-46-30', 'en', 'If I speak not formally but out of love, without fear, forgive what I say as from one devoted.', 'veda-app-ai-draft', true),
('ramayana-2-46-31', 'en', 'How can I return to that city without you, dear one, a city grieving at parting from you as for a son?', 'veda-app-ai-draft', true),
('ramayana-2-46-32', 'en', 'The people saw my chariot with Rama; seeing it without Rama, the city might break apart.', 'veda-app-ai-draft', true),
('ramayana-2-46-33', 'en', 'The city would fall into despair seeing this empty chariot, like an army with only its charioteer left, its hero killed in battle.', 'veda-app-ai-draft', true),
('ramayana-2-46-34', 'en', 'Though you live far away, they keep you before them in their minds; surely the people have gone without food today thinking of you.', 'veda-app-ai-draft', true),
('ramayana-2-46-35', 'en', 'The cry of grief the citizens raised at your exile, they would make a hundred times louder seeing me in the chariot.', 'veda-app-ai-draft', true),
('ramayana-2-46-36', 'en', 'What shall I say to the queen: I have taken your son to his uncle''s; do not grieve?', 'veda-app-ai-draft', true),
('ramayana-2-46-37', 'en', 'I could never say such an untruth. How can I tell her this unwelcome truth?', 'veda-app-ai-draft', true),
('ramayana-2-46-38', 'en', 'These fine horses under my command, which carried your kin, how will they draw a chariot without you?', 'veda-app-ai-draft', true),
('ramayana-2-46-39', 'en', 'If you abandon me though I beg, I will enter fire with the chariot the moment you leave me here.', 'veda-app-ai-draft', true),
('ramayana-2-46-40', 'en', 'Whatever creatures in the forest disturb your austerities, Raghava, I will drive them off with the chariot.', 'veda-app-ai-draft', true),
('ramayana-2-46-41', 'en', 'Through you I have known the pleasure of driving the chariot; through you I hope to know the pleasure of forest life.', 'veda-app-ai-draft', true),
('ramayana-2-46-42', 'en', 'Be gracious; I want to be near you in the forest. I want you to say lovingly: Stay with me.', 'veda-app-ai-draft', true),
('ramayana-2-46-43', 'en', 'Living in the forest, I will serve you with my head bowed; I give up Ayodhya and even the world of the gods.', 'veda-app-ai-draft', true),
('ramayana-2-46-44', 'en', 'I cannot enter Ayodhya without you, as an evildoer cannot enter great Indra''s capital.', 'veda-app-ai-draft', true),
('ramayana-2-46-45', 'en', 'And these horses, hero, if they serve you living in the forest, will reach the highest state.', 'veda-app-ai-draft', true),
('ramayana-2-46-46', 'en', 'This is my wish: when the forest exile ends, to carry you back to the city in this very chariot.', 'veda-app-ai-draft', true),
('ramayana-2-46-47', 'en', 'Fourteen years with you in the forest would pass like moments; otherwise they would be a hundredfold longer.', 'veda-app-ai-draft', true),
('ramayana-2-46-48', 'en', 'You who love your servants, do not abandon me, your devoted servant, standing on the path your father''s son walks, steady in my duty.', 'veda-app-ai-draft', true),
('ramayana-2-46-49', 'en', 'To Sumantra, begging so pitifully again and again, Rama, kind to his servants, said:', 'veda-app-ai-draft', true),
('ramayana-2-46-50', 'en', 'I know your great devotion to me, you who love your master. Hear why I am sending you back to the city.', 'veda-app-ai-draft', true),
('ramayana-2-46-51', 'en', 'Seeing you return to the city, my younger mother Kaikeyi will be convinced that Rama has gone to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-46-52', 'en', 'Satisfied that I have gone to the forest, the queen will not suspect the righteous king of being a liar.', 'veda-app-ai-draft', true),
('ramayana-2-46-53', 'en', 'This is my first concern: that my younger mother should gain her son''s kingdom, prosperous and protected by Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-46-54', 'en', 'For my sake and the king''s, go to the city with the chariot, and tell everything as I have instructed.', 'veda-app-ai-draft', true),
('ramayana-2-46-55', 'en', 'Having said this to the charioteer and comforting him again and again, Rama said firmly and with reason to Guha: I will make my hair matted and go; bring banyan sap.', 'veda-app-ai-draft', true),
('ramayana-2-46-56', 'en', 'Guha quickly brought that sap for the prince, and Rama with it made matted locks for Lakshmana and himself.', 'veda-app-ai-draft', true),
('ramayana-2-46-57', 'en', 'Then, in bark garments and with crowns of matted hair, the brothers Rama and Lakshmana shone like sages.', 'veda-app-ai-draft', true),
('ramayana-2-46-58', 'en', 'Then, taking up the path of forest hermits with Lakshmana and the vow it requires, Rama spoke to his helper Guha:', 'veda-app-ai-draft', true),
('ramayana-2-46-59', 'en', 'Be watchful over your army, treasury, fort and country, Guha, for a kingdom is held to be hardest to protect.', 'veda-app-ai-draft', true),
('ramayana-2-46-60', 'en', 'Then, taking leave of Guha, the joy of the Ikshvakus went quickly and calmly with his wife and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-46-61', 'en', 'Seeing a boat on the riverbank, the joy of the Ikshvakus, wishing to cross the swift Ganga, said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-2-46-62', 'en', 'Get into this boat slowly, tiger among men, and help the high-minded Sita in, holding her.', 'veda-app-ai-draft', true),
('ramayana-2-46-63', 'en', 'Hearing his brother''s command and not opposing anything, he first helped Maithili in, then the self-possessed one boarded.', 'veda-app-ai-draft', true),
('ramayana-2-46-64', 'en', 'Then radiant Lakshmana''s elder boarded himself, and Guha, lord of the Nishadas, urged on his kinsmen.', 'veda-app-ai-draft', true),
('ramayana-2-46-65', 'en', 'Taking leave of Sumantra and of Guha with his men, Rama sat in the boat and urged on the boatmen.', 'veda-app-ai-draft', true),
('ramayana-2-46-66', 'en', 'Urged by them and steered by the helmsman, the boat, driven by strong oars, quickly crossed the water.', 'veda-app-ai-draft', true),
('ramayana-2-46-67', 'en', 'Reaching the middle of the Bhagirathi, blameless Vaidehi folded her hands and said to the river:', 'veda-app-ai-draft', true),
('ramayana-2-46-68', 'en', 'This son of the wise great King Dasharatha, protected by you, Ganga, may he fulfil this command.', 'veda-app-ai-draft', true),
('ramayana-2-46-69', 'en', 'Having lived the full fourteen years in the forest, he will return again with his brother and me.', 'veda-app-ai-draft', true),
('ramayana-2-46-70', 'en', 'Then, blessed goddess, returning safely, I will joyfully worship you, Ganga, for the fulfilment of every wish.', 'veda-app-ai-draft', true),
('ramayana-2-46-71', 'en', 'Goddess, flowing in three paths, you look upon Brahma''s world, and in this world you are seen as the wife of the ocean king.', 'veda-app-ai-draft', true),
('ramayana-2-46-72', 'en', 'I bow to you, goddess, and praise you, lovely one. When the tiger among men returns safely and gains the kingdom,', 'veda-app-ai-draft', true),
('ramayana-2-46-73', 'en', 'I will give brahmins hundreds of thousands of cows, clothes and fine food, to please you.', 'veda-app-ai-draft', true),
('ramayana-2-46-74', 'en', 'Speaking so to the Ganga, blameless, capable Sita quickly reached the southern bank.', 'veda-app-ai-draft', true),
('ramayana-2-46-75', 'en', 'Reaching the bank and leaving the boat, the bull among men set out with his brother and Vaidehi.', 'veda-app-ai-draft', true),
('ramayana-2-46-76', 'en', 'Then the mighty-armed one said to Sumitra''s joy: Go ahead, Saumitri; let Sita follow you.', 'veda-app-ai-draft', true),
('ramayana-2-46-77', 'en', 'I will go behind, protecting you and Sita. Today Vaidehi will learn the hardship of forest life.', 'veda-app-ai-draft', true),
('ramayana-2-46-78', 'en', 'Watching Rama go quickly to the far bank of the Ganga, Sumantra gazed until the distance turned his sight away, and the pained, faithful man wept.', 'veda-app-ai-draft', true),
('ramayana-2-46-79', 'en', 'There the two, hungry, killed four large animals, a boar, an antelope, a spotted deer and a great ruru deer, took the pure meat and at evening went to a great tree to stay.', 'veda-app-ai-draft', true),
('ramayana-2-47-1', 'en', 'Reaching that tree and performing the evening prayer, Rama, best of those who give delight, said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-2-47-2', 'en', 'This is the first night we have spent outside the inhabited land, without Sumantra; you should not feel homesick.', 'veda-app-ai-draft', true),
('ramayana-2-47-3', 'en', 'From today we two must stay awake by turns at night, tirelessly, for Sita''s welfare depends on us, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-47-4', 'en', 'Let us pass this night somehow, Saumitri; we will lie on the ground on leaves we gather ourselves.', 'veda-app-ai-draft', true),
('ramayana-2-47-5', 'en', 'Lying on the earth, he who was used to costly beds spoke these fine words to Saumitri:', 'veda-app-ai-draft', true),
('ramayana-2-47-6', 'en', 'Surely the great king sleeps in sorrow tonight, Lakshmana, while Kaikeyi, her wish fulfilled, must be content.', 'veda-app-ai-draft', true),
('ramayana-2-47-7', 'en', 'Might Queen Kaikeyi, for the sake of the kingdom, even take the great king''s life once she sees Bharata arrive?', 'veda-app-ai-draft', true),
('ramayana-2-47-8', 'en', 'Old and without protector, parted from me, under Kaikeyi''s power and ruled by desire, what will he do?', 'veda-app-ai-draft', true),
('ramayana-2-47-9', 'en', 'Seeing this disaster and the king''s confusion, I think desire weighs more than wealth and dharma.', 'veda-app-ai-draft', true),
('ramayana-2-47-10', 'en', 'What man, however foolish, would give up for a woman an obedient son as father has given me up, Lakshmana?', 'veda-app-ai-draft', true),
('ramayana-2-47-11', 'en', 'Happy indeed is Bharata, Kaikeyi''s son, with his wife, who alone will enjoy the joyful Kosalas like an emperor.', 'veda-app-ai-draft', true),
('ramayana-2-47-12', 'en', 'He will be the one head of the whole kingdom, with father past his age and me gone to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-47-13', 'en', 'Whoever gives up wealth and dharma to follow desire quickly meets the fate King Dasharatha has.', 'veda-app-ai-draft', true),
('ramayana-2-47-14', 'en', 'I think Kaikeyi came, gentle one, to bring about Dasharatha''s end, my banishment and the kingdom for Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-47-15', 'en', 'Might not Kaikeyi, intoxicated by her good fortune, now harass Kausalya and Sumitra because of me?', 'veda-app-ai-draft', true),
('ramayana-2-47-16', 'en', 'Let not Queen Sumitra suffer on my account. Go back to Ayodhya from here in good time, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-47-17', 'en', 'I alone will go with Sita to the Dandakas; you will be protector of helpless Kausalya.', 'veda-app-ai-draft', true),
('ramayana-2-47-18', 'en', 'Kaikeyi is mean in her actions and out of hatred might act unjustly. Entrust my mother to righteous Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-47-19', 'en', 'Surely in some former life women were parted from their sons by my mother, Saumitri; now that has come back to her.', 'veda-app-ai-draft', true),
('ramayana-2-47-20', 'en', 'Kausalya raised me long, with much sorrow, and is parted from me just when she should enjoy the fruit. Shame on me!', 'veda-app-ai-draft', true),
('ramayana-2-47-21', 'en', 'May no woman ever bear a son like me, Saumitri, who gives his mother endless grief.', 'veda-app-ai-draft', true),
('ramayana-2-47-22', 'en', 'I think her pet myna bird gives her more love than I, for she hears it say: Parrot, bite the enemy''s foot!', 'veda-app-ai-draft', true),
('ramayana-2-47-23', 'en', 'What use am I, a son who does nothing for my grieving, unlucky mother, as if she were childless?', 'veda-app-ai-draft', true),
('ramayana-2-47-24', 'en', 'My unlucky mother Kausalya, without me, lies in deep pain, fallen into an ocean of grief.', 'veda-app-ai-draft', true),
('ramayana-2-47-25', 'en', 'Alone, Lakshmana, I could conquer Ayodhya and the whole earth with my arrows if angry; but strength without just cause is nothing.', 'veda-app-ai-draft', true),
('ramayana-2-47-26', 'en', 'I fear adharma and the next world, sinless one; so I do not crown myself today, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-47-27', 'en', 'Having lamented this and much else in the lonely place, Rama, his face full of tears, sat silent in the night.', 'veda-app-ai-draft', true),
('ramayana-2-47-28', 'en', 'Lakshmana comforted Rama, who had stopped lamenting like a fire without flame or a sea without waves.', 'veda-app-ai-draft', true),
('ramayana-2-47-29', 'en', 'Surely today, Rama, best of warriors, the city of Ayodhya is without light now that you have left, like night without the moon.', 'veda-app-ai-draft', true),
('ramayana-2-47-30', 'en', 'It is not right, Rama, that you torment yourself like this; you are making Sita and me despondent, bull among men.', 'veda-app-ai-draft', true),
('ramayana-2-47-31', 'en', 'Neither Sita nor I could live a moment without you, Raghava, like fish taken out of water.', 'veda-app-ai-draft', true),
('ramayana-2-47-32', 'en', 'I would not want to see father, Shatrughna, Sumitra, or even heaven today without you, tamer of foes.', 'veda-app-ai-draft', true),
('ramayana-2-47-33', 'en', 'Hearing Lakshmana''s excellent, full words, the tamer of foes, Raghava, respectfully accepted forest life for all those years, embracing dharma for a long time.', 'veda-app-ai-draft', true),
('ramayana-2-48-1', 'en', 'Having spent that auspicious night under the great tree, they set out from there when the clear sun had risen.', 'veda-app-ai-draft', true),
('ramayana-2-48-2', 'en', 'They went towards the place where the Bhagirathi Ganga meets the Yamuna, plunging into a vast forest.', 'veda-app-ai-draft', true),
('ramayana-2-48-3', 'en', 'The famous ones saw lands of many kinds and lovely regions they had never seen before.', 'veda-app-ai-draft', true),
('ramayana-2-48-4', 'en', 'Going safely and seeing many trees, as the day was ending, Rama said to Saumitri:', 'veda-app-ai-draft', true),
('ramayana-2-48-5', 'en', 'See the smoke rising near Prayaga, Saumitri, the banner of blessed Agni; I think a sage is near.', 'veda-app-ai-draft', true),
('ramayana-2-48-6', 'en', 'Surely we have reached the meeting of the Ganga and Yamuna, for we hear the sound of water striking water.', 'veda-app-ai-draft', true),
('ramayana-2-48-7', 'en', 'Here is firewood split by forest dwellers who live by it, and these many trees are in Bharadvaja''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-2-48-8', 'en', 'The two archers, going easily, reached the sage''s dwelling at the meeting of the Ganga and Yamuna as the sun was sinking.', 'veda-app-ai-draft', true),
('ramayana-2-48-9', 'en', 'Reaching the hermitage, startling the deer and birds, Rama went a short way and approached Bharadvaja.', 'veda-app-ai-draft', true),
('ramayana-2-48-10', 'en', 'At the hermitage, the two heroes, followed by Sita and wishing to see the sage, stood at a distance.', 'veda-app-ai-draft', true),
('ramayana-2-48-11', 'en', 'Seeing the fortunate sage who had made his fire offering, Rama with folded hands, with Saumitri and Sita, saluted him.', 'veda-app-ai-draft', true),
('ramayana-2-48-12', 'en', 'Lakshmana''s elder introduced himself: We are the two sons of Dasharatha, lord, Rama and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-48-13', 'en', 'This is my wife Vaidehi, the auspicious daughter of Janaka; blameless, she has followed me to this lonely ascetics'' forest.', 'veda-app-ai-draft', true),
('ramayana-2-48-14', 'en', 'When my father banished me, my dear younger brother Saumitri, firm in his vow, followed me to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-48-15', 'en', 'Ordered by our father, lord, we will enter the ascetics'' forest; there we will practise dharma, living on roots and fruits.', 'veda-app-ai-draft', true),
('ramayana-2-48-16', 'en', 'Hearing the wise prince, the righteous sage brought a cow, water of welcome and water.', 'veda-app-ai-draft', true),
('ramayana-2-48-17', 'en', 'Seated, surrounded by deer, birds and sages, the sage honoured Rama on his arrival and welcomed him.', 'veda-app-ai-draft', true),
('ramayana-2-48-18', 'en', 'When Rama had accepted the honour and sat down, Bharadvaja spoke these righteous words:', 'veda-app-ai-draft', true),
('ramayana-2-48-19', 'en', 'At last I see you come here, Kakutstha. I have heard of your causeless banishment.', 'veda-app-ai-draft', true),
('ramayana-2-48-20', 'en', 'This place at the meeting of the two great rivers is secluded, holy and lovely; let your lordship live here happily.', 'veda-app-ai-draft', true),
('ramayana-2-48-21', 'en', 'Thus addressed by Bharadvaja, Raghava, devoted to the good of all, replied in fine words:', 'veda-app-ai-draft', true),
('ramayana-2-48-22', 'en', 'Lord, the people of the city and country are near here; they will come to see Vaidehi and me. For that reason I do not want to stay here.', 'veda-app-ai-draft', true),
('ramayana-2-48-23', 'en', 'Lord, find a fine site for a hermitage in a secluded place, where Vaidehi, Janaka''s daughter, who deserves comfort, will be happy.', 'veda-app-ai-draft', true),
('ramayana-2-48-24', 'en', 'Hearing these good words, the great sage Bharadvaja said meaningfully to Raghava:', 'veda-app-ai-draft', true),
('ramayana-2-48-25', 'en', 'Ten krosha from here, dear one, is a mountain where you can live, holy, visited by great sages, lovely to look at everywhere.', 'veda-app-ai-draft', true),
('ramayana-2-48-26', 'en', 'Roamed by langurs, frequented by monkeys and bears, it is called Chitrakuta, like Mount Gandhamadana.', 'veda-app-ai-draft', true),
('ramayana-2-48-27', 'en', 'As long as a man looks on Chitrakuta''s peaks, he turns his mind to good and not to evil.', 'veda-app-ai-draft', true),
('ramayana-2-48-28', 'en', 'Many sages have lived there a hundred autumns and risen to heaven through austerity.', 'veda-app-ai-draft', true),
('ramayana-2-48-29', 'en', 'I think that dwelling, secluded, will be pleasant for you; or live here with me for your forest exile, Rama.', 'veda-app-ai-draft', true),
('ramayana-2-48-30', 'en', 'Righteous Bharadvaja received his dear guest Rama, with his wife and brother, with everything they could wish.', 'veda-app-ai-draft', true),
('ramayana-2-48-31', 'en', 'At Prayaga, as Rama sat with the great sage telling wonderful stories, the holy night came.', 'veda-app-ai-draft', true),
('ramayana-2-48-32', 'en', 'When the night had turned to dawn, the tiger among men went to Bharadvaja, blazing with radiance, and said:', 'veda-app-ai-draft', true),
('ramayana-2-48-33', 'en', 'We have spent the night in your hermitage, truthful one; please give us leave to go to our dwelling.', 'veda-app-ai-draft', true),
('ramayana-2-48-34', 'en', 'When that night had passed, Bharadvaja said: Go to Chitrakuta, rich in honey, roots and fruits.', 'veda-app-ai-draft', true),
('ramayana-2-48-35', 'en', 'There herds of elephants and deer roam the forest edges on all sides; you will see them, Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-48-36', 'en', 'Reach that auspicious mountain, ringing with the cries of delighted birds and cuckoos, lovely with many deer and elephants in rut, and make your hermitage there.', 'veda-app-ai-draft', true),
('ramayana-2-49-1', 'en', 'Having spent the night there, the two princes bowed to the great sage and set out for that mountain.', 'veda-app-ai-draft', true),
('ramayana-2-49-2', 'en', 'Seeing them set out, the great sage followed them like a father his sons and began to speak:', 'veda-app-ai-draft', true),
('ramayana-2-49-3', 'en', 'Reach the Kalindi, the swift-flowing river, make a raft there and cross the Amshumati river.', 'veda-app-ai-draft', true),
('ramayana-2-49-4', 'en', 'Then reach a great green-leaved banyan tree, grown big among many trees, dark and visited by siddhas.', 'veda-app-ai-draft', true),
('ramayana-2-49-5', 'en', 'Going a krosha from there, you will see a dark forest mixed with palasha and jujube trees and Yamuna bamboos, Rama.', 'veda-app-ai-draft', true),
('ramayana-2-49-6', 'en', 'That path to Chitrakuta I have walked many times; it is lovely, soft and free of forest fires. Having told them the way, the great sage turned back.', 'veda-app-ai-draft', true),
('ramayana-2-49-7', 'en', 'When the sage had turned back, Rama said to Lakshmana: We have earned merit, Saumitri, that the sage is kind to us.', 'veda-app-ai-draft', true),
('ramayana-2-49-8', 'en', 'So the two high-minded tigers among men talked and, putting Sita in front, went to the Kalindi river.', 'veda-app-ai-draft', true),
('ramayana-2-49-9', 'en', 'They made a large raft of logs; Lakshmana cut wood and made a comfortable seat for Sita.', 'veda-app-ai-draft', true),
('ramayana-2-49-10', 'en', 'There Rama, son of Dasharatha, helped his beloved, like unimaginable Shri, a little shy, onto the raft.', 'veda-app-ai-draft', true),
('ramayana-2-49-11', 'en', 'Then on the raft they crossed the swift, wave-garlanded Amshumati, the Yamuna, with many trees on its banks.', 'veda-app-ai-draft', true),
('ramayana-2-49-12', 'en', 'Having crossed, they left the raft, set out from the Yamuna woods and reached the dark, cool, green-leaved banyan.', 'veda-app-ai-draft', true),
('ramayana-2-49-13', 'en', 'May I see Kausalya and famous Sumitra again, prayed Sita with folded hands, and walked round the tree.', 'veda-app-ai-draft', true),
('ramayana-2-49-14', 'en', 'Going a krosha from there, the brothers Rama and Lakshmana killed many deer fit for offering and roamed the Yamuna forest.', 'veda-app-ai-draft', true),
('ramayana-2-49-15', 'en', 'Having roamed the lovely forest, echoing with flocks of peacocks and full of elephants and monkeys, they reached a level riverbank and made their camp, with cheerful faces.', 'veda-app-ai-draft', true),
('ramayana-2-50-1', 'en', 'When the night had passed, the joy of the Raghus gently woke Lakshmana, who had just fallen asleep.', 'veda-app-ai-draft', true),
('ramayana-2-50-2', 'en', 'Saumitri, hear the sweet sound of the forest creatures calling. Let us set out; it is time to go, tamer of foes.', 'veda-app-ai-draft', true),
('ramayana-2-50-3', 'en', 'Woken by his brother at the right time, Lakshmana shook off sleep, drowsiness and the weariness of the road.', 'veda-app-ai-draft', true),
('ramayana-2-50-4', 'en', 'Then they all rose, touched the river''s auspicious water and set off on the path to Chitrakuta the sage had pointed out.', 'veda-app-ai-draft', true),
('ramayana-2-50-5', 'en', 'Then, setting out at the right time with Saumitri, Rama said to lotus-eyed Sita:', 'veda-app-ai-draft', true),
('ramayana-2-50-6', 'en', 'Vaidehi, see the kimshuka trees in full bloom on every side, as if ablaze, garlanded with their own flowers at the end of winter.', 'veda-app-ai-draft', true),
('ramayana-2-50-7', 'en', 'See the bhallataka trees in bloom, untouched by people, bent with fruit and leaves; surely I can live here.', 'veda-app-ai-draft', true),
('ramayana-2-50-8', 'en', 'See, Lakshmana, honeycombs as big as buckets hanging on every tree, gathered by the bees.', 'veda-app-ai-draft', true),
('ramayana-2-50-9', 'en', 'Here a natyuha bird calls and a peacock answers it, in this lovely spot carpeted with flowers.', 'veda-app-ai-draft', true),
('ramayana-2-50-10', 'en', 'See this Chitrakuta mountain with its high peaks, roamed by herds of elephants and echoing with flocks of birds.', 'veda-app-ai-draft', true),
('ramayana-2-50-11', 'en', 'Walking on foot with Sita, the two reached the lovely, delightful mountain Chitrakuta.', 'veda-app-ai-draft', true),
('ramayana-2-50-12', 'en', 'Reaching that mountain full of many kinds of birds: This will be our home for now; let us enjoy ourselves here, gentle one.', 'veda-app-ai-draft', true),
('ramayana-2-50-13', 'en', 'Lakshmana, bring strong, good timber and build a dwelling, gentle one; my heart is set on living here.', 'veda-app-ai-draft', true),
('ramayana-2-50-14', 'en', 'Hearing him, Saumitri brought various trees and built a leaf hut, tamer of foes.', 'veda-app-ai-draft', true),
('ramayana-2-50-15', 'en', 'To Lakshmana, attentive and serving him, Rama said: Bring antelope meat; we will consecrate the hut.', 'veda-app-ai-draft', true),
('ramayana-2-50-16', 'en', 'Mighty Lakshmana killed a black antelope fit for offering and placed it in the kindled fire.', 'veda-app-ai-draft', true),
('ramayana-2-50-17', 'en', 'Knowing it was cooked, well roasted and free of blood, Lakshmana said to Raghava, tiger among men:', 'veda-app-ai-draft', true),
('ramayana-2-50-18', 'en', 'This black antelope is cooked whole, god-like one; worship the deities, for you are skilled.', 'veda-app-ai-draft', true),
('ramayana-2-50-19', 'en', 'Rama, having bathed, controlled, virtuous and skilled in prayer, made the excellent offering that removes sin.', 'veda-app-ai-draft', true),
('ramayana-2-50-20', 'en', 'They all entered together to live in that charming leaf-roofed hut, well built in a fit place and sheltered from wind, as the gods enter their hall Sudharma.', 'veda-app-ai-draft', true),
('ramayana-2-50-21', 'en', 'In that finest of forests, full of many deer and birds, with trees bearing colourful clusters of flowers and echoing with wild animals, they lived very happily, self-controlled.', 'veda-app-ai-draft', true),
('ramayana-2-50-22', 'en', 'Reaching lovely Chitrakuta and the river Malyavati with its good bathing places, full of deer and birds, he rejoiced and let go of the sorrow of exile from the city.', 'veda-app-ai-draft', true),
('ramayana-2-51-1', 'en', 'After talking long with Sumantra, deeply grieved, Guha went home when Rama was on the southern bank.', 'veda-app-ai-draft', true),
('ramayana-2-51-2', 'en', 'Dismissed, Sumantra yoked the fine horses and set out for the city of Ayodhya, deeply downcast.', 'veda-app-ai-draft', true),
('ramayana-2-51-3', 'en', 'Seeing fragrant forests, rivers, lakes, villages and towns, he passed quickly by.', 'veda-app-ai-draft', true),
('ramayana-2-51-4', 'en', 'Then on the evening of the third day, reaching Ayodhya, the charioteer saw it joyless.', 'veda-app-ai-draft', true),
('ramayana-2-51-5', 'en', 'Seeing it empty and silent, Sumantra, deeply downcast and struck by grief, thought:', 'veda-app-ai-draft', true),
('ramayana-2-51-6', 'en', 'Has the city, with its elephants, horses, people and king, been burned by the fire of grief for Rama? Thinking so, the charioteer hurried in.', 'veda-app-ai-draft', true),
('ramayana-2-51-7', 'en', 'As Sumantra came, men ran to him by the hundreds and thousands, asking, Where is Rama?', 'veda-app-ai-draft', true),
('ramayana-2-51-8', 'en', 'He told them: I took leave of Raghava at the Ganga; dismissed by the righteous great soul, I returned.', 'veda-app-ai-draft', true),
('ramayana-2-51-9', 'en', 'Knowing they had crossed, the people, their faces full of tears, sighed, Alas, shame! and cried, Ah Rama!', 'veda-app-ai-draft', true),
('ramayana-2-51-10', 'en', 'He heard them speaking in groups: We are ruined, since we do not see Raghava here.', 'veda-app-ai-draft', true),
('ramayana-2-51-11', 'en', 'At gifts, sacrifices, weddings and great gatherings we will never again see righteous Rama among us.', 'veda-app-ai-draft', true),
('ramayana-2-51-12', 'en', 'What is fitting, dear and pleasing for these people: so Rama looked after the city like a father.', 'veda-app-ai-draft', true),
('ramayana-2-51-13', 'en', 'Through the shops he heard the laments of women at their windows, burning with grief for Rama.', 'veda-app-ai-draft', true),
('ramayana-2-51-14', 'en', 'Sumantra, covering his face, went along the royal road to the house where King Dasharatha was.', 'veda-app-ai-draft', true),
('ramayana-2-51-15', 'en', 'Quickly getting down from the chariot and entering the palace, he passed through seven courtyards crowded with people.', 'veda-app-ai-draft', true),
('ramayana-2-51-16', 'en', 'Then he heard the soft talk of Dasharatha''s wives, burning with grief for Rama, from palaces here and there.', 'veda-app-ai-draft', true),
('ramayana-2-51-17', 'en', 'The charioteer left with Rama and has come back without Rama; what will he say to grieving Kausalya?', 'veda-app-ai-draft', true),
('ramayana-2-51-18', 'en', 'As I think, life is surely hard for her; how does Kausalya live, her son torn away and gone?', 'veda-app-ai-draft', true),
('ramayana-2-51-19', 'en', 'Hearing these true words of the king''s women, he entered the house quickly, as if burning with grief.', 'veda-app-ai-draft', true),
('ramayana-2-51-20', 'en', 'Entering the eighth courtyard, he saw the king wretched and pale, worn out with grief for his son, in the white house.', 'veda-app-ai-draft', true),
('ramayana-2-51-21', 'en', 'Approaching the seated king and saluting him, Sumantra reported Rama''s words as spoken.', 'veda-app-ai-draft', true),
('ramayana-2-51-22', 'en', 'Hearing it in silence, the king, his mind reeling, fainted and fell to the ground, crushed by grief for Rama.', 'veda-app-ai-draft', true),
('ramayana-2-51-23', 'en', 'Then the inner palace, stricken when the lord of the earth fainted, raised their arms and cried out as the king fell.', 'veda-app-ai-draft', true),
('ramayana-2-51-24', 'en', 'Kausalya, with Sumitra, raised her fallen husband and said:', 'veda-app-ai-draft', true),
('ramayana-2-51-25', 'en', 'Fortunate one, here is the messenger of him who did a hard thing, come back from the forest; why do you not speak to him?', 'veda-app-ai-draft', true),
('ramayana-2-51-26', 'en', 'Having done this wrong today, you are ashamed, Raghava. Get up; may your good deeds help you; there is no help in grief.', 'veda-app-ai-draft', true),
('ramayana-2-51-27', 'en', 'Lord, Kaikeyi, for fear of whom you do not ask the charioteer about Rama, is not here; speak freely.', 'veda-app-ai-draft', true),
('ramayana-2-51-28', 'en', 'Having said this to the great king, Kausalya, overcome by grief, fell to the ground, her words broken by tears.', 'veda-app-ai-draft', true),
('ramayana-2-51-29', 'en', 'Seeing Kausalya lamenting and fallen on the ground, and looking at their husband, all the women wept aloud.', 'veda-app-ai-draft', true),
('ramayana-2-51-30', 'en', 'Hearing the cry rising from the inner palace, old and young men and all the women wept on every side, and the city was again in turmoil.', 'veda-app-ai-draft', true),
('ramayana-2-52-1', 'en', 'When the king recovered and came back to his senses, he called the charioteer to hear about Rama.', 'veda-app-ai-draft', true),
('ramayana-2-52-2', 'en', 'Old, deeply pained, like a newly captured elephant, sighing and brooding like an unwell elephant,', 'veda-app-ai-draft', true),
('ramayana-2-52-3', 'en', 'the king said in deep distress to the charioteer, who stood dust-covered, tear-faced and wretched:', 'veda-app-ai-draft', true),
('ramayana-2-52-4', 'en', 'Where will the righteous one live, sheltering at a tree''s foot? What will Raghava, used to great comfort, eat, charioteer? How does the king''s son lie on the ground like one without a protector?', 'veda-app-ai-draft', true),
('ramayana-2-52-5', 'en', 'He whom foot soldiers, chariots and elephants followed, how will Rama live in the lonely forest?', 'veda-app-ai-draft', true),
('ramayana-2-52-6', 'en', 'How did the two princes with Vaidehi reach the forest, roamed by wild beasts and black snakes?', 'veda-app-ai-draft', true),
('ramayana-2-52-7', 'en', 'With delicate, devoted Sita, Sumantra, how did the princes get down from the chariot and go on foot?', 'veda-app-ai-draft', true),
('ramayana-2-52-8', 'en', 'You have succeeded, charioteer, for you saw my sons entering the forest like the Ashvins entering Mount Mandara.', 'veda-app-ai-draft', true),
('ramayana-2-52-9', 'en', 'What did Rama say, what did Lakshmana say, Sumantra, on reaching the forest, and what did Maithili say? Tell me how Rama sat, slept and ate.', 'veda-app-ai-draft', true),
('ramayana-2-52-10', 'en', 'Urged by the king, the charioteer spoke to him in a halting voice choked with tears:', 'veda-app-ai-draft', true),
('ramayana-2-52-11', 'en', 'Great king, keeping to dharma, Raghava folded his hands, bowed his head and said to me:', 'veda-app-ai-draft', true),
('ramayana-2-52-12', 'en', 'Charioteer, on my behalf bow at the feet of my wise, great-souled father, who is to be honoured with bowed head.', 'veda-app-ai-draft', true),
('ramayana-2-52-13', 'en', 'Give all the inner palace my greeting, wish them health without distinction and salute them fittingly.', 'veda-app-ai-draft', true),
('ramayana-2-52-14', 'en', 'Tell my mother Kausalya I am well and salute her: Queen, care for the king''s feet as you would a god''s.', 'veda-app-ai-draft', true),
('ramayana-2-52-15', 'en', 'Give Bharata my good wishes and tell him on my behalf: Treat all the mothers as is just.', 'veda-app-ai-draft', true),
('ramayana-2-52-16', 'en', 'And tell the mighty-armed joy of the Ikshvaku line: As crown prince, look after our father who is king.', 'veda-app-ai-draft', true),
('ramayana-2-52-17', 'en', 'Saying this to me, great king, famous Rama, his eyes red as lotuses, shed many tears.', 'veda-app-ai-draft', true),
('ramayana-2-52-18', 'en', 'But Lakshmana, very angry, sighing, said: For what offence has this prince been banished?', 'veda-app-ai-draft', true),
('ramayana-2-52-19', 'en', 'Whether Rama was banished out of greed or because of a boon, it was a wrong deed in every way; I see no reason for abandoning Rama.', 'veda-app-ai-draft', true),
('ramayana-2-52-20', 'en', 'Begun without thought, contrary to reason through shallow judgment, Raghava''s banishment will cause an outcry.', 'veda-app-ai-draft', true),
('ramayana-2-52-21', 'en', 'For my part I see no fatherhood in the great king; my brother, master, kin and father is Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-52-22', 'en', 'Having cast off the one loved by all, devoted to the good of all, how will the whole world love you after this deed?', 'veda-app-ai-draft', true),
('ramayana-2-52-23', 'en', 'But Janaki, great king, sighing, devoted, stood as if possessed, lost in thought.', 'veda-app-ai-draft', true),
('ramayana-2-52-24', 'en', 'The famous princess, who had never known misfortune, weeping with that grief, said nothing to me.', 'veda-app-ai-draft', true),
('ramayana-2-52-25', 'en', 'Looking at her husband with a dried-up face, she suddenly shed tears as she watched me leave.', 'veda-app-ai-draft', true),
('ramayana-2-52-26', 'en', 'So too Rama stood with tear-stained face and folded hands, guarded by Lakshmana''s arm; and so too devoted Sita, weeping, watched the royal chariot and me.', 'veda-app-ai-draft', true),
('ramayana-2-53-1', 'en', 'As I turned back, the horses would not move on the road, shedding hot tears as Rama set out for the forest.', 'veda-app-ai-draft', true),
('ramayana-2-53-2', 'en', 'Folding my hands to both princes, I set out in the chariot, bearing that sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-53-3', 'en', 'I stayed there with Guha for many days, hoping Rama might call me back again.', 'veda-app-ai-draft', true),
('ramayana-2-53-4', 'en', 'In your kingdom, great king, even the trees, worn by Rama''s misfortune, have withered, with their flowers, shoots and buds.', 'veda-app-ai-draft', true),
('ramayana-2-53-5', 'en', 'Creatures do not move, beasts of prey do not roam; the forest, overcome by grief for Rama, has gone silent.', 'veda-app-ai-draft', true),
('ramayana-2-53-6', 'en', 'The lotus ponds, lord of men, have their lotus leaves drooping, their water muddy, their lotuses scorched, their fish and birds hidden.', 'veda-app-ai-draft', true),
('ramayana-2-53-7', 'en', 'Water flowers, land flowers and garlands do not shine today, nor do fruits smell as before.', 'veda-app-ai-draft', true),
('ramayana-2-53-8', 'en', 'As I entered Ayodhya no one welcomed me; people, not seeing Rama, sighed again and again.', 'veda-app-ai-draft', true),
('ramayana-2-53-9', 'en', 'From mansions, towers and palaces, women seeing the chariot return cried out, wasted by not seeing Rama.', 'veda-app-ai-draft', true),
('ramayana-2-53-10', 'en', 'With wide, clear eyes flooded with tears, the women looked at one another, plainly more pained.', 'veda-app-ai-draft', true),
('ramayana-2-53-11', 'en', 'In this distress I see no difference among enemies, friends or neutral people.', 'veda-app-ai-draft', true),
('ramayana-2-53-12', 'en', 'Its people joyless, its elephants and horses wretched, withered with cries of pain and filled with sighs,', 'veda-app-ai-draft', true),
('ramayana-2-53-13', 'en', 'joyless, great king, stricken by Rama''s banishment, Ayodhya looks to me like Kausalya without her son.', 'veda-app-ai-draft', true),
('ramayana-2-53-14', 'en', 'Hearing the charioteer, the king said to him in a very wretched voice choked with tears:', 'veda-app-ai-draft', true),
('ramayana-2-53-15', 'en', 'Urged by Kaikeyi, of wicked birth and nature, I did not consult the old men skilled in counsel.', 'veda-app-ai-draft', true),
('ramayana-2-53-16', 'en', 'Without consulting friends, ministers or merchants, I did this rashly, deluded, for a woman''s sake.', 'veda-app-ai-draft', true),
('ramayana-2-53-17', 'en', 'Surely, charioteer, by fate this great disaster has come upon us by chance, to destroy this family.', 'veda-app-ai-draft', true),
('ramayana-2-53-18', 'en', 'Charioteer, if I have ever done you any good, take me quickly to Rama, for my life is hurrying to leave me.', 'veda-app-ai-draft', true),
('ramayana-2-53-19', 'en', 'Let my own command bring Raghava back. I cannot live without Rama even for a moment.', 'veda-app-ai-draft', true),
('ramayana-2-53-20', 'en', 'Or, if the mighty-armed one has gone far away, put me in the chariot and show me Rama quickly.', 'veda-app-ai-draft', true),
('ramayana-2-53-21', 'en', 'Where is Lakshmana''s elder brother, the great archer with fine teeth? If I live, may I see him with Sita.', 'veda-app-ai-draft', true),
('ramayana-2-53-22', 'en', 'If I do not see Rama, with his reddish eyes, mighty arms and jewelled earrings, I will go to the abode of Yama.', 'veda-app-ai-draft', true),
('ramayana-2-53-23', 'en', 'What could be more painful than this, that I have come to such a state and cannot see Rama, the joy of the Ikshvakus, here?', 'veda-app-ai-draft', true),
('ramayana-2-53-24', 'en', 'Alas Rama! Alas Lakshmana! Alas, poor Vaidehi! You do not know that I am dying of grief like one with no protector. O queen, this ocean of sorrow is hard for me to cross while I live.', 'veda-app-ai-draft', true),
('ramayana-2-53-25', 'en', '''It is wretched that today I long to see Raghava with Lakshmana and cannot.'' Lamenting thus, the famous king fell senseless on his bed.', 'veda-app-ai-draft', true),
('ramayana-2-53-26', 'en', 'As the king lamented, lost and twice as pitiful for Rama''s sake, Rama''s mother heard his words and was seized by fear again.', 'veda-app-ai-draft', true),
('ramayana-2-54-1', 'en', 'Then Kausalya, trembling again and again as if possessed, lying on the ground as if lifeless, spoke to the charioteer.', 'veda-app-ai-draft', true),
('ramayana-2-54-2', 'en', 'Take me where Kakutstha is, where Sita and Lakshmana are. Without them I cannot bear to live here even a moment.', 'veda-app-ai-draft', true),
('ramayana-2-54-3', 'en', 'Turn the chariot back quickly and take me too to the Dandaka forest. If I do not follow them, I will go to the abode of death.', 'veda-app-ai-draft', true),
('ramayana-2-54-4', 'en', 'With a voice choked by a rush of tears, the charioteer folded his hands and said this to comfort the queen.', 'veda-app-ai-draft', true),
('ramayana-2-54-5', 'en', 'Give up grief, confusion and the distress born of sorrow. Raghava will live in the forest having shaken off all pain.', 'veda-app-ai-draft', true),
('ramayana-2-54-6', 'en', 'And Lakshmana, who knows dharma and has mastered his senses, serves Rama''s feet in the forest and so wins the world beyond.', 'veda-app-ai-draft', true),
('ramayana-2-54-7', 'en', 'Even in the lonely forest Sita lives as if at home, fearless and trusting, her heart given to Rama.', 'veda-app-ai-draft', true),
('ramayana-2-54-8', 'en', 'I did not see the slightest sign of misery in her. Vaidehi seems to me as if used to living away from home.', 'veda-app-ai-draft', true),
('ramayana-2-54-9', 'en', 'Just as she used to enjoy going to the city gardens, Sita enjoys herself in the empty forests too.', 'veda-app-ai-draft', true),
('ramayana-2-54-10', 'en', 'Sita, with a face like the new moon, plays like a young girl. Devoted to Rama, with an untroubled heart, the good lady is happy even in the lonely forest.', 'veda-app-ai-draft', true),
('ramayana-2-54-11', 'en', 'Her heart is set on him and her life depends on him. Without Rama, even Ayodhya would be a forest to her.', 'veda-app-ai-draft', true),
('ramayana-2-54-12', 'en', 'On the way Vaidehi asks about the villages and towns, and about the flow of the rivers and the many kinds of trees she sees.', 'veda-app-ai-draft', true),
('ramayana-2-54-13', 'en', 'The road, the force of the wind, the hurry and the heat have not dimmed Vaidehi''s moonlike radiance.', 'veda-app-ai-draft', true),
('ramayana-2-54-14', 'en', 'The generous lady''s face, like a lotus and shining like the full moon, does not falter.', 'veda-app-ai-draft', true),
('ramayana-2-54-15', 'en', 'Her feet, once red with lac dye and now without it, still glow like lotus buds.', 'veda-app-ai-draft', true),
('ramayana-2-54-16', 'en', 'Even now, having put aside her ornaments, the lovely Vaidehi walks playfully, as if her anklets were still ringing, out of love for him.', 'veda-app-ai-draft', true),
('ramayana-2-54-17', 'en', 'Whether she sees an elephant, a lion or a tiger, living in the forest she feels no fear, relying on Rama''s arms.', 'veda-app-ai-draft', true),
('ramayana-2-54-18', 'en', 'They are not to be grieved for, nor are you, nor the king. This conduct of theirs will stand in the world forever.', 'veda-app-ai-draft', true),
('ramayana-2-54-19', 'en', 'Shaking off grief, with joyful minds, steady on the path the great sages walked, delighting in the forest and living on wild fruit, they are keeping their father''s noble promise.', 'veda-app-ai-draft', true),
('ramayana-2-54-20', 'en', 'Yet though the charioteer spoke so well and tried to stop her, the queen, worn down by grief for her son, did not stop crying ''My dear! My son! Raghava!''', 'veda-app-ai-draft', true),
('ramayana-2-55-1', 'en', 'With Rama, devoted to dharma and the best of those who give joy, gone to the forest, Kausalya, weeping and stricken, said this to her husband.', 'veda-app-ai-draft', true),
('ramayana-2-55-2', 'en', 'Great is your fame in the three worlds, that Raghava is compassionate, generous and kind in speech.', 'veda-app-ai-draft', true),
('ramayana-2-55-3', 'en', 'Best of men, how will your two sons and Sita, raised in comfort, bear hardship in the forest?', 'veda-app-ai-draft', true),
('ramayana-2-55-4', 'en', 'How will that young, delicate Maithili, used to comfort, bear the heat and the cold?', 'veda-app-ai-draft', true),
('ramayana-2-55-5', 'en', 'Having eaten fine food with sauces and relishes, how will wide-eyed Sita eat wild rice from the forest?', 'veda-app-ai-draft', true),
('ramayana-2-55-6', 'en', 'Having heard the lovely sound of songs and music, how will the blameless one hear the frightening roars of flesh-eating lions?', 'veda-app-ai-draft', true),
('ramayana-2-55-7', 'en', 'Where does the mighty-armed one, like Indra''s banner, sleep now, resting his head on his strong, bar-like arm?', 'veda-app-ai-draft', true),
('ramayana-2-55-8', 'en', 'When will I see Rama''s face again, lotus-coloured, framed by fine hair, with lotus eyes and fragrant breath?', 'veda-app-ai-draft', true),
('ramayana-2-55-9', 'en', 'Surely my heart is made of diamond, without doubt, since it does not burst into a thousand pieces now that I cannot see him.', 'veda-app-ai-draft', true),
('ramayana-2-55-10', 'en', 'Even if Raghava returns in the fifteenth year, Bharata will have enjoyed the kingdom and treasury; he may give them up.', 'veda-app-ai-draft', true),
('ramayana-2-55-11', 'en', 'Lord of the people, when the kingdom has thus been enjoyed by a younger brother, why would the eldest and best not scorn it?', 'veda-app-ai-draft', true),
('ramayana-2-55-12', 'en', 'A tiger does not want to eat prey another has brought down. In the same way the tiger among men will not accept what others have tasted.', 'veda-app-ai-draft', true),
('ramayana-2-55-13', 'en', 'Oblations, ghee, sacrificial cakes, kusha grass and khadira posts, once used, are not used again in a sacrifice.', 'veda-app-ai-draft', true),
('ramayana-2-55-14', 'en', 'So Rama will not accept this kingdom once it has been used, like wine with its strength gone, or a sacrifice whose soma is lost.', 'veda-app-ai-draft', true),
('ramayana-2-55-15', 'en', 'Raghava will not put up with such an insult, just as a mighty tiger would not bear someone touching its tail.', 'veda-app-ai-draft', true),
('ramayana-2-55-16', 'en', 'Such a man, strong as a lion, bull-eyed, a bull among men, has been destroyed by his own father, as a fish might eat its own young.', 'veda-app-ai-draft', true),
('ramayana-2-55-17', 'en', 'Is this the eternal dharma practised by the twice-born and seen in the scriptures, if you, devoted to dharma, banish your son?', 'veda-app-ai-draft', true),
('ramayana-2-55-18', 'en', 'O king, a woman''s first refuge is her husband, the second her son, the third her relatives. There is no fourth here.', 'veda-app-ai-draft', true),
('ramayana-2-55-19', 'en', 'Of these, you are not mine, and Rama has gone to the forest. I do not want to go to the forest; I am utterly ruined by you.', 'veda-app-ai-draft', true),
('ramayana-2-55-20', 'en', 'You have destroyed this kingdom with its land; you have destroyed yourself and your ministers. I am destroyed with my son, and the citizens too. Only your son and your wife are delighted.', 'veda-app-ai-draft', true),
('ramayana-2-55-21', 'en', 'Hearing these harsh words, the king, already in pain, fainted. Then he sank into grief and again remembered a wrong he had once done.', 'veda-app-ai-draft', true),
('ramayana-2-56-1', 'en', 'The king, having been spoken to so harshly by Rama''s angry and grieving mother, became thoughtful in his pain.', 'veda-app-ai-draft', true),
('ramayana-2-56-2', 'en', 'As he thought, the wrong he had done long ago in ignorance, as one who shoots at sound, came back to him.', 'veda-app-ai-draft', true),
('ramayana-2-56-3', 'en', 'Downcast with that grief and with grief for Rama, burned by both sorrows, the lord of the earth spoke to Kausalya.', 'veda-app-ai-draft', true),
('ramayana-2-56-4', 'en', 'Kausalya, I fold my hands to win your favour. You have always been loving and gentle, even to strangers.', 'veda-app-ai-draft', true),
('ramayana-2-56-5', 'en', 'For women who reflect on dharma, a husband, whether good or without virtues, is a visible god, O queen.', 'veda-app-ai-draft', true),
('ramayana-2-56-6', 'en', 'You, always devoted to dharma and knowing what is near and far in the world, should not speak unkind words to one who is deeply pained, even though you are pained yourself.', 'veda-app-ai-draft', true),
('ramayana-2-56-7', 'en', 'Hearing the pitiful words of the wretched king, Kausalya shed tears like a channel pouring new rainwater.', 'veda-app-ai-draft', true),
('ramayana-2-56-8', 'en', 'Weeping, she placed the king''s lotus-like folded hands on her head, and in alarm spoke hurried words.', 'veda-app-ai-draft', true),
('ramayana-2-56-9', 'en', 'Be gracious; I beg you with bowed head, falling to the ground before you. Being begged by you, lord, I am ruined; I do not deserve to be pleaded with by you.', 'veda-app-ai-draft', true),
('ramayana-2-56-10', 'en', 'She is not a worthy woman in either world whose wise and praiseworthy husband has to win her over.', 'veda-app-ai-draft', true),
('ramayana-2-56-11', 'en', 'I know dharma, knower of dharma, and I know you speak the truth. It was grief for my son that made me say whatever I said.', 'veda-app-ai-draft', true),
('ramayana-2-56-12', 'en', 'Grief destroys courage, grief destroys learning, grief destroys everything. There is no enemy like grief.', 'veda-app-ai-draft', true),
('ramayana-2-56-13', 'en', 'A blow from an enemy''s hand can be endured when it falls, but grief, even the slightest, cannot be endured when it comes.', 'veda-app-ai-draft', true),
('ramayana-2-56-14', 'en', 'Today is counted as the fifth night of Rama''s forest exile, yet for me, whose joy grief has killed, it seems like five years.', 'veda-app-ai-draft', true),
('ramayana-2-56-15', 'en', 'As I think of him, this grief swells in my heart, like the great ocean swelling with the force of rivers.', 'veda-app-ai-draft', true),
('ramayana-2-56-16', 'en', 'While Kausalya was speaking these kind words, the sun''s rays grew dim and night came on.', 'veda-app-ai-draft', true),
('ramayana-2-56-17', 'en', 'Then the king, comforted by queen Kausalya''s words but still overcome by grief, fell asleep.', 'veda-app-ai-draft', true),
('ramayana-2-57-1', 'en', 'Awakening shortly after, his mind struck by grief, King Dasharatha fell into deep thought.', 'veda-app-ai-draft', true),
('ramayana-2-57-2', 'en', 'Because Rama and Lakshmana had been exiled, distress entered the Indra-like king, as the demon of darkness covers the sun.', 'veda-app-ai-draft', true),
('ramayana-2-57-3', 'en', 'On the sixth night after Rama went to the forest, at midnight, King Dasharatha, remembering the wrong he had done, said this to Kausalya, who was tormented by grief for her son.', 'veda-app-ai-draft', true),
('ramayana-2-57-4', 'en', 'Whatever a person does, good or bad, gracious lady, the doer receives that same fruit born of his own action.', 'veda-app-ai-draft', true),
('ramayana-2-57-5', 'en', 'One who, when starting a task, does not know whether its matters are heavy or light, nor its result or its fault, is called a child.', 'veda-app-ai-draft', true),
('ramayana-2-57-6', 'en', 'Someone cuts down a mango grove and waters palasha trees; greedy for fruit after seeing the flowers, he grieves when the fruiting season comes.', 'veda-app-ai-draft', true),
('ramayana-2-57-7', 'en', 'I am that fool who cut down the mango grove and watered the palasha trees. Having cast off Rama when it was time for fruit, I grieve afterwards.', 'veda-app-ai-draft', true),
('ramayana-2-57-8', 'en', 'Kausalya, when I was a young prince with a bow, proud of being called one who shoots by sound, I committed this sin. Now this sorrow I brought on myself has come to me, O queen.', 'veda-app-ai-draft', true),
('ramayana-2-57-9', 'en', 'Just as a child might eat poison in ignorance, so I did not know the fruit of shooting by sound.', 'veda-app-ai-draft', true),
('ramayana-2-57-10', 'en', 'O queen, you were not yet married and I was crown prince. Then the rainy season came, which increases desire and passion.', 'veda-app-ai-draft', true),
('ramayana-2-57-11', 'en', 'Having drawn up the earth''s moisture and heated the world with its rays, the sun entered the dreadful southern quarter, travelled by the dead.', 'veda-app-ai-draft', true),
('ramayana-2-57-12', 'en', 'The heat vanished at once, dark rain clouds appeared, and all the frogs, deer and peacocks rejoiced.', 'veda-app-ai-draft', true),
('ramayana-2-57-13', 'en', 'Drenched with rain that fell and kept falling, the hill, full of excited deer, looked like a mass of water.', 'veda-app-ai-draft', true),
('ramayana-2-57-14', 'en', 'In that very pleasant season, armed with bow and arrows, in my chariot, intent on exercise, I went along the Sarayu river.', 'veda-app-ai-draft', true),
('ramayana-2-57-15', 'en', 'Not master of my senses, I wanted to kill a buffalo, or an elephant come to the river at night to drink, or some other wild beast.', 'veda-app-ai-draft', true),
('ramayana-2-57-16', 'en', 'Then in the darkness, beyond the range of sight, I heard the sound of a pot being filled in the water, like an elephant''s trumpeting.', 'veda-app-ai-draft', true),
('ramayana-2-57-17', 'en', 'Then I drew out an arrow, blazing and like a venomous snake, and released that sharp, snake-like arrow.', 'veda-app-ai-draft', true),
('ramayana-2-57-18', 'en', 'There, as the arrow fell, a clear human voice of a forest dweller arose: ''Alas! Alas!'' And it said, ''How could a weapon fall on an ascetic like me?''', 'veda-app-ai-draft', true),
('ramayana-2-57-19', 'en', '''I came to the lonely river at night to fetch water. Who has struck me with an arrow? Whom have I wronged?''', 'veda-app-ai-draft', true),
('ramayana-2-57-20', 'en', '''How can death by weapon come to someone like me, a sage who has laid down the rod of violence and lives in the forest on forest food?''', 'veda-app-ai-draft', true),
('ramayana-2-57-21', 'en', '''Who could want to kill me, wearing matted hair and clothes of bark and deerskin? What harm have I done him?''', 'veda-app-ai-draft', true),
('ramayana-2-57-22', 'en', '''Such a deed, undertaken for nothing and bringing only harm, no one would think good, just as no one approves of one who violates his teacher''s bed.''', 'veda-app-ai-draft', true),
('ramayana-2-57-23', 'en', '''I do not grieve so much for the end of my own life. I grieve for my mother and father, both, now that this has happened to me.''', 'veda-app-ai-draft', true),
('ramayana-2-57-24', 'en', '''I have long supported this aged couple. When I am dead, how will they live?''', 'veda-app-ai-draft', true),
('ramayana-2-57-25', 'en', '''My old mother and father and I have all been struck by one arrow. By what foolish, undisciplined person have we all been slain?''', 'veda-app-ai-draft', true),
('ramayana-2-57-26', 'en', 'Hearing those pitiful words, I, who cared for dharma, was shaken, and my bow and arrow fell from my hands to the ground.', 'veda-app-ai-draft', true),
('ramayana-2-57-27', 'en', 'I went to that place, wretched and sick at heart, and saw on the Sarayu''s bank the ascetic struck down by my arrow.', 'veda-app-ai-draft', true),
('ramayana-2-57-28', 'en', 'Looking at me, frightened and confused, he spoke these harsh words, as if to burn me with his spiritual power.', 'veda-app-ai-draft', true),
('ramayana-2-57-29', 'en', '''King, what wrong have I done you, living in the forest? I only wanted to fetch water for my elders, and you struck me.''', 'veda-app-ai-draft', true),
('ramayana-2-57-30', 'en', '''With one arrow piercing my vital spot, two blind old people are killed as well, my mother and my father.''', 'veda-app-ai-draft', true),
('ramayana-2-57-31', 'en', '''Weak, blind and thirsty, they must be waiting for me, holding on long to their painful thirst in hope.''', 'veda-app-ai-draft', true),
('ramayana-2-57-32', 'en', '''Surely there is no fruit of austerity or learning, since my father does not know that I am lying fallen on the ground.''', 'veda-app-ai-draft', true),
('ramayana-2-57-33', 'en', '''And even if he knew, what could he do, powerless and unable to move, like one tree unable to save another being cut down?''', 'veda-app-ai-draft', true),
('ramayana-2-57-34', 'en', '''Raghava, go yourself quickly and tell my father, so that his anger does not burn you as a blazing fire burns a forest.''', 'veda-app-ai-draft', true),
('ramayana-2-57-35', 'en', '''King, this footpath leads to my father''s hermitage. Go and win his favour, so that he does not curse you in anger.''', 'veda-app-ai-draft', true),
('ramayana-2-57-36', 'en', '''King, take the arrow out of me. This sharp arrow presses on my vital spot, as a river''s flow presses on a soft, high bank.''', 'veda-app-ai-draft', true),
('ramayana-2-57-37', 'en', '''King, I am not a Brahmin; let there be no anguish in your mind. Lord of the land, I was born of a Vaishya father and a Shudra mother.''', 'veda-app-ai-draft', true),
('ramayana-2-57-38', 'en', 'As he spoke with difficulty, his vital spot pierced, and as he bent down, I drew out that arrow.', 'veda-app-ai-draft', true),
('ramayana-2-57-39', 'en', 'Seeing him lying in the Sarayu, his body wet, lamenting in pain and breathing hard from the wound, I was utterly dejected, good lady.', 'veda-app-ai-draft', true),
('ramayana-2-58-1', 'en', 'Having committed that great sin through ignorance, my senses confused, I thought alone with my mind how I could set things right.', 'veda-app-ai-draft', true),
('ramayana-2-58-2', 'en', 'Then I took the pot filled with good water and went by the path he had described to the hermitage.', 'veda-app-ai-draft', true),
('ramayana-2-58-3', 'en', 'There I saw his parents, weak, blind, old and without a guide, like two birds with clipped wings.', 'veda-app-ai-draft', true),
('ramayana-2-58-4', 'en', 'They sat talking about him, unable to move, their hope cut off because of me, helpless as if without a protector.', 'veda-app-ai-draft', true),
('ramayana-2-58-5', 'en', 'Hearing my footsteps, the sage said, ''Why are you so late, my son? Bring the water quickly.''', 'veda-app-ai-draft', true),
('ramayana-2-58-6', 'en', '''Dear one, because you played in the water so long, your mother here is anxious. Come quickly into the hermitage.''', 'veda-app-ai-draft', true),
('ramayana-2-58-7', 'en', '''Son, if your mother or I have done anything to hurt you, do not keep it in your mind, dear ascetic.''', 'veda-app-ai-draft', true),
('ramayana-2-58-8', 'en', '''You are the refuge of us who have no refuge, the eyes of us who have no eyes. Our lives depend on you. Why do you not speak to us?''', 'veda-app-ai-draft', true),
('ramayana-2-58-9', 'en', 'Seeing the sage, frightened, I spoke to him in an unclear, faltering voice, the words broken.', 'veda-app-ai-draft', true),
('ramayana-2-58-10', 'en', 'Steadying the strength of my voice with effort of mind, I told him of the fear born of disaster to his son.', 'veda-app-ai-draft', true),
('ramayana-2-58-11', 'en', '''I am Dasharatha, a Kshatriya, not your great-souled son. This sorrow, despised by good people, has come from my own deed.''', 'veda-app-ai-draft', true),
('ramayana-2-58-12', 'en', '''Holy one, bow in hand I came to the Sarayu''s bank, wishing to kill some wild beast or an elephant come to the watering place.''', 'veda-app-ai-draft', true),
('ramayana-2-58-13', 'en', '''There I heard the sound of a pot filling in the water. Thinking it was an elephant, I struck with an arrow.''', 'veda-app-ai-draft', true),
('ramayana-2-58-14', 'en', '''Then going to the river bank I saw an ascetic lying on the ground, his heart pierced by the arrow, near death.''', 'veda-app-ai-draft', true),
('ramayana-2-58-15', 'en', '''Holy one, aiming at a sound, wanting to kill an elephant, I loosed an iron arrow into the water, and by it your son was slain.''', 'veda-app-ai-draft', true),
('ramayana-2-58-16', 'en', '''When the arrow was drawn out, he went to heaven right there, grieving for you both, lamenting that you are blind.''', 'veda-app-ai-draft', true),
('ramayana-2-58-17', 'en', '''Through ignorance I suddenly struck your son. Whatever remains to be done now, may the sage be gracious to me.''', 'veda-app-ai-draft', true),
('ramayana-2-58-18', 'en', 'Hearing those cruel words, sighing and wasted by grief, the sage of great power spoke to me as I stood with folded hands.', 'veda-app-ai-draft', true),
('ramayana-2-58-19', 'en', '''King, if you had not told me of this evil deed yourself, your head would at once have burst into a hundred thousand pieces.''', 'veda-app-ai-draft', true),
('ramayana-2-58-20', 'en', '''King, the killing of a forest-dwelling ascetic by a Kshatriya, done knowingly, would cast down even Indra from his place.''', 'veda-app-ai-draft', true),
('ramayana-2-58-21', 'en', '''Because this was done in ignorance, you live. Otherwise today the whole family of the Raghavas would perish, let alone you.''', 'veda-app-ai-draft', true),
('ramayana-2-58-22', 'en', 'He said to me, ''King, take us to that place. Today we wish to see our son for the last time.''', 'veda-app-ai-draft', true),
('ramayana-2-58-23', 'en', '''...his body covered in blood, his deerskin garment scattered, lying senseless on the ground, gone into the power of the king of dharma.''', 'veda-app-ai-draft', true),
('ramayana-2-58-24', 'en', 'Then I alone led the deeply grieving pair to that place and let the sage and his wife touch their son.', 'veda-app-ai-draft', true),
('ramayana-2-58-25', 'en', 'The two ascetics, touching their son and reaching him, fell upon his body, and his father said this.', 'veda-app-ai-draft', true),
('ramayana-2-58-26', 'en', '''Am I not dear to you, son? Look at your mother, righteous one. Why do you not embrace me, son? Speak, gentle one.''', 'veda-app-ai-draft', true),
('ramayana-2-58-27', 'en', '''From whom will I now hear, in the last part of the night, the sweet, heart-touching recitation of scripture?''', 'veda-app-ai-draft', true),
('ramayana-2-58-28', 'en', '''Who, after bathing, performing the twilight worship and offering to the fire, will sit by me and comfort me, tormented by grief and fear for my son?''', 'veda-app-ai-draft', true),
('ramayana-2-58-29', 'en', '''Who will bring roots, bulbs and fruit and feed me like a dear guest, helpless, without support and without a leader?''', 'veda-app-ai-draft', true),
('ramayana-2-58-30', 'en', '''Son, how will I support your blind, aged mother, an ascetic, miserable and longing for her son?''', 'veda-app-ai-draft', true),
('ramayana-2-58-31', 'en', '''Stay, son, do not go toward Yama''s house. Tomorrow you will go with me and your mother.''', 'veda-app-ai-draft', true),
('ramayana-2-58-32', 'en', '''We two, stricken with grief, helpless and wretched in the forest, will soon go to Yama''s realm without you.''', 'veda-app-ai-draft', true),
('ramayana-2-58-33', 'en', '''Then, seeing Vaivasvata, I will say to him: may the king of dharma forgive me, and may this son support his parents.''', 'veda-app-ai-draft', true),
('ramayana-2-58-34', 'en', '''Son, since you are sinless and were killed by one who did a sinful deed, by that truth go quickly to the worlds of those who fight with weapons.''', 'veda-app-ai-draft', true),
('ramayana-2-58-35', 'en', '''Son, go to that highest state that heroes reach who never turn back in battle and die facing the enemy.''', 'veda-app-ai-draft', true),
('ramayana-2-58-36', 'en', '''Little son, go to the state reached by Sagara, Shaibya, Dilipa, Janamejaya, Nahusha and Dhundhumara.''', 'veda-app-ai-draft', true),
('ramayana-2-58-37', 'en', '''...the state of all good people, of those who study and do austerities, of the giver of land, of one who keeps the sacred fire, and of one faithful to a single wife...''', 'veda-app-ai-draft', true),
('ramayana-2-58-38', 'en', '''...the state of givers of a thousand cows, of those who serve their teachers, of those who give up the body; go to that state, little son. No one born in this family goes to an unhappy end.''', 'veda-app-ai-draft', true),
('ramayana-2-58-39', 'en', 'So he lamented there pitifully again and again. Then he began, with his wife, to offer water for him.', 'veda-app-ai-draft', true),
('ramayana-2-58-40', 'en', 'Then the sage''s son, in a divine form gained by his own deeds, comforted his parents for a moment and spoke.', 'veda-app-ai-draft', true),
('ramayana-2-58-41', 'en', '''I have reached a great place through serving you both. You too will soon come to me.''', 'veda-app-ai-draft', true),
('ramayana-2-58-42', 'en', 'Having said this, the self-controlled sage''s son quickly rose to heaven in a beautiful divine chariot.', 'veda-app-ai-draft', true),
('ramayana-2-58-43', 'en', 'The ascetic, with his wife, having quickly made the water offering, spoke to me, the powerful one, as I stood with folded hands.', 'veda-app-ai-draft', true),
('ramayana-2-58-44', 'en', '''Kill me today, king; I have no fear of death, since with one arrow you have made me, who had one son, sonless.''', 'veda-app-ai-draft', true),
('ramayana-2-58-45', 'en', '''Because you killed my pure son through ignorance, I will lay on you a curse of very painful and terrible sorrow.''', 'veda-app-ai-draft', true),
('ramayana-2-58-46', 'en', '''Just as I now feel this pain born of losing my son, so, king, you too will die of grief for a son.''', 'veda-app-ai-draft', true),
('ramayana-2-58-47', 'en', 'Good lady, the words of that noble one have now come true for me, since today I will give up my life from grief for my son.', 'veda-app-ai-draft', true),
('ramayana-2-58-48', 'en', 'If Rama touched me even once today or held me, that would not match what I have done to Raghava, O queen.', 'veda-app-ai-draft', true),
('ramayana-2-58-49', 'en', 'I cannot see you with my eyes, my memory is fading. Kausalya, Yama''s messengers are hurrying me.', 'veda-app-ai-draft', true),
('ramayana-2-58-50', 'en', 'What could be more painful than this, that at the end of my life I cannot see Rama, who knows dharma and is true in valour?', 'veda-app-ai-draft', true),
('ramayana-2-58-51', 'en', 'They are not men but gods who will see Rama''s face with its lovely bright earrings again in the fifteenth year.', 'veda-app-ai-draft', true),
('ramayana-2-58-52', 'en', 'Fortunate are those who will see Rama''s face, with lotus-petal eyes, fine brows, fine teeth and lovely nose, shining like the moon.', 'veda-app-ai-draft', true),
('ramayana-2-58-53', 'en', 'Fortunate are those who will see my lord''s fragrant face, like the autumn moon and a blooming lotus.', 'veda-app-ai-draft', true),
('ramayana-2-58-54', 'en', 'Happy are those who will see Rama, his forest exile over, come back to Ayodhya, like the planet Venus back on its course.', 'veda-app-ai-draft', true),
('ramayana-2-58-55', 'en', 'This grief, born of my own deeds, wears me down, helpless and senseless, as a river''s current wears away its bank.', 'veda-app-ai-draft', true),
('ramayana-2-58-56', 'en', '''Alas Raghava, mighty-armed! Alas, destroyer of my troubles!'' So grieving, King Dasharatha came to the end of his life.', 'veda-app-ai-draft', true),
('ramayana-2-58-57', 'en', 'Speaking so pitifully, distressed by the exile of his beloved son, the noble-looking king, crushed by deep grief, gave up his life after midnight.', 'veda-app-ai-draft', true),
('ramayana-2-59-1', 'en', 'When the night had passed, early the next morning, the bards came to attend at the king''s palace.', 'veda-app-ai-draft', true),
('ramayana-2-59-2', 'en', 'Then the attendants, pure in conduct and skilled in service, mostly women and eunuchs, came as before.', 'veda-app-ai-draft', true),
('ramayana-2-59-3', 'en', 'Those who knew the rites of bathing brought water mixed with yellow sandal in golden pots, at the right time and in the proper way.', 'veda-app-ai-draft', true),
('ramayana-2-59-4', 'en', 'Other women, many of them young girls, brought auspicious things to touch, food and utensils.', 'veda-app-ai-draft', true),
('ramayana-2-59-5', 'en', 'Then the women closest to the king''s bed came together and tried to wake their lord.', 'veda-app-ai-draft', true),
('ramayana-2-59-6', 'en', 'Trembling and fearing for the king''s life, they shook like grass tips against a stream.', 'veda-app-ai-draft', true),
('ramayana-2-59-7', 'en', 'Then, seeing the trembling women and the king, their fear that something terrible had happened became certain.', 'veda-app-ai-draft', true),
('ramayana-2-59-8', 'en', 'Then the fine ladies cried out aloud in misery, like female elephants in the forest whose herd leader has fallen.', 'veda-app-ai-draft', true),
('ramayana-2-59-9', 'en', 'At the sound of their wailing, Kausalya and Sumitra woke suddenly from sleep.', 'veda-app-ai-draft', true),
('ramayana-2-59-10', 'en', 'Kausalya and Sumitra, seeing and touching the king, cried ''Alas, my lord!'' and fell to the ground.', 'veda-app-ai-draft', true),
('ramayana-2-59-11', 'en', 'The daughter of the Kosala king, rolling on the ground, covered in dust, lost her lustre like a star fallen from the sky.', 'veda-app-ai-draft', true),
('ramayana-2-59-12', 'en', '...full of terrified, bewildered and anxious people, everywhere loud lamentation, kinsmen tormented with grief...', 'veda-app-ai-draft', true),
('ramayana-2-59-13', 'en', '...all joy suddenly gone, a sight of misery and confusion: so became the palace of the king who had met his end.', 'veda-app-ai-draft', true),
('ramayana-2-59-14', 'en', 'Knowing that the famous bull among kings had passed away, his wives gathered round him, weeping bitterly and pitifully, and holding his arms lamented like orphans.', 'veda-app-ai-draft', true),
('ramayana-2-60-1', 'en', 'Seeing the king gone to heaven, like a fire gone out, like an ocean without water, like a sun without light...', 'veda-app-ai-draft', true),
('ramayana-2-60-2', 'en', '...Kausalya, her eyes full of tears, worn down by grief in many ways, took the king''s head in her lap and spoke to Kaikeyi.', 'veda-app-ai-draft', true),
('ramayana-2-60-3', 'en', 'Have your wish, Kaikeyi. Enjoy the kingdom without a rival, having cast off the king, single-minded, cruel woman of wicked conduct.', 'veda-app-ai-draft', true),
('ramayana-2-60-4', 'en', 'Rama has left me and gone, and my husband has gone to heaven. Like a traveller who has lost her caravan on a bad road, I cannot bear to live.', 'veda-app-ai-draft', true),
('ramayana-2-60-5', 'en', 'What woman, having abandoned her husband, her god, would wish to live elsewhere, except Kaikeyi who has abandoned dharma?', 'veda-app-ai-draft', true),
('ramayana-2-60-6', 'en', 'A greedy person does not see the faults, like one eating poisonous fruit. Because of the hunchbacked woman, Kaikeyi has destroyed the family of the Raghavas.', 'veda-app-ai-draft', true),
('ramayana-2-60-7', 'en', 'When Janaka hears that Rama and his wife were exiled by the king under an improper command, he will grieve as I do.', 'veda-app-ai-draft', true),
('ramayana-2-60-8', 'en', 'Lotus-eyed Rama has gone from here as if to his death. And Sita, the poor daughter of the king of Videha, who never knew sorrow, will be distressed by hardship in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-60-9', 'en', 'Hearing at night the terrible cries of beasts and birds, she will surely be frightened and cling to Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-60-10', 'en', 'Old, with only one child, thinking constantly of Vaidehi, he too, overcome by grief, will surely give up his life.', 'veda-app-ai-draft', true),
('ramayana-2-60-11', 'en', 'Then the attendants embraced the weeping, wretched Kausalya, deeply stricken with sorrow, and led her away.', 'veda-app-ai-draft', true),
('ramayana-2-60-12', 'en', 'Then the ministers laid the lord of the earth in a vessel of oil and, as instructed, did all the necessary things for the king.', 'veda-app-ai-draft', true),
('ramayana-2-60-13', 'en', 'The all-knowing ministers did not wish to perform the king''s funeral without a son, so they kept the king''s body safe.', 'veda-app-ai-draft', true),
('ramayana-2-60-14', 'en', 'When the women learned that the king, laid in the oil vessel by the ministers, was truly dead, they lamented.', 'veda-app-ai-draft', true),
('ramayana-2-60-15', 'en', 'Raising their arms, wretched, faces streaming with tears, burning with grief, they wept and lamented pitifully.', 'veda-app-ai-draft', true),
('ramayana-2-60-16', 'en', 'Without its great-souled king, the city of Ayodhya did not shine, like a night without stars or a woman without her husband.', 'veda-app-ai-draft', true),
('ramayana-2-60-17', 'en', 'With people choked by tears, the noble women crying ''Alas!'', its squares and houses empty, it did not shine as before.', 'veda-app-ai-draft', true),
('ramayana-2-60-18', 'en', 'Bereft of the great one, the city looked like the sky without the sun, or a night with its hosts of stars gone, its roads and squares filled with tear-choked people.', 'veda-app-ai-draft', true),
('ramayana-2-60-19', 'en', 'Then in the city, at the king''s death, men and women gathered in groups condemning Bharata''s mother; they were in distress and found no peace.', 'veda-app-ai-draft', true),
('ramayana-2-61-1', 'en', 'When the night had passed and the sun rose, the twice-born who were the king-makers gathered and went to the assembly hall.', 'veda-app-ai-draft', true),
('ramayana-2-61-2', 'en', 'Markandeya, Maudgalya, Vamadeva, Kashyapa, Katyayana, Gautama and the famous Jabali...', 'veda-app-ai-draft', true),
('ramayana-2-61-3', 'en', 'These Brahmins, with the ministers, each spoke out, facing Vasishtha, the best of royal priests.', 'veda-app-ai-draft', true),
('ramayana-2-61-4', 'en', 'This night has passed in sorrow, like a hundred years for us, now that the king has died of grief for his son.', 'veda-app-ai-draft', true),
('ramayana-2-61-5', 'en', 'The great king has gone to heaven, Rama has gone to the forest, and splendid Lakshmana has gone with him.', 'veda-app-ai-draft', true),
('ramayana-2-61-6', 'en', 'Both Bharata and Shatrughna, scorchers of foes, are in Kekaya, in the lovely city of Rajagriha, in their grandfather''s home.', 'veda-app-ai-draft', true),
('ramayana-2-61-7', 'en', 'Let some Ikshvaku prince be made king here this very day, so that our kingless land does not fall to ruin.', 'veda-app-ai-draft', true),
('ramayana-2-61-8', 'en', 'In a kingless land the thundering rain-cloud, garlanded with lightning, does not pour heavenly water on the earth.', 'veda-app-ai-draft', true),
('ramayana-2-61-9', 'en', 'In a kingless land no handful of seed is sown. In a kingless land a son does not obey his father, nor a wife her husband.', 'veda-app-ai-draft', true),
('ramayana-2-61-10', 'en', 'In a kingless land there is no wealth, no wife is safe; and here is a further great danger: how can there be truth in a kingless land?', 'veda-app-ai-draft', true),
('ramayana-2-61-11', 'en', 'In a kingless land people do not build assembly halls, lovely gardens or holy shrines with joy.', 'veda-app-ai-draft', true),
('ramayana-2-61-12', 'en', 'In a kingless land the twice-born devoted to sacrifice, the self-controlled Brahmins of strict vows, do not hold long sacrificial sessions.', 'veda-app-ai-draft', true),
('ramayana-2-61-13', 'en', 'In a kingless land there are no crowds of actors and dancers, and festivals and gatherings that enrich the realm do not flourish.', 'veda-app-ai-draft', true),
('ramayana-2-61-14', 'en', 'In a kingless land successful litigants find no joy, and storytellers are not delighted by those who love stories.', 'veda-app-ai-draft', true),
('ramayana-2-61-15', 'en', 'In a kingless land men do not ride out to the woods on swift vehicles with their women for pleasure.', 'veda-app-ai-draft', true),
('ramayana-2-61-16', 'en', 'In a kingless land the wealthy are not protected, and farmers and herdsmen do not sleep with their doors open.', 'veda-app-ai-draft', true),
('ramayana-2-61-17', 'en', 'In a kingless land merchants who travel far, carrying many goods, do not take the road in safety.', 'veda-app-ai-draft', true),
('ramayana-2-61-18', 'en', 'In a kingless land the self-controlled sage who wanders alone, contemplating the self by the self and making his home wherever evening finds him, does not roam.', 'veda-app-ai-draft', true),
('ramayana-2-61-19', 'en', 'In a kingless land welfare and security do not continue, and without a king an army cannot withstand enemies in battle.', 'veda-app-ai-draft', true),
('ramayana-2-61-20', 'en', 'Like rivers without water, like a forest without grass, like cows without a herdsman, so is a kingdom without a king.', 'veda-app-ai-draft', true),
('ramayana-2-61-21', 'en', 'In a kingless land nothing belongs to anyone. People always devour each other like fish.', 'veda-app-ai-draft', true),
('ramayana-2-61-22', 'en', 'Even those who break all bounds, unbelievers whose doubts have been cut off, come to good behaviour when restrained by the king''s rod of justice.', 'veda-app-ai-draft', true),
('ramayana-2-61-23', 'en', 'Ah, if there were no king in the world to separate good from bad, all would be like darkness and nothing would be clear.', 'veda-app-ai-draft', true),
('ramayana-2-61-24', 'en', 'Even while the great king lived, we all never overstepped your word, just as the ocean does not pass its shore.', 'veda-app-ai-draft', true),
('ramayana-2-61-25', 'en', 'Best of Brahmins, seeing how the kingdom without a king has become like a wilderness, you yourself consecrate as king here a generous Ikshvaku prince.', 'veda-app-ai-draft', true),
('ramayana-2-62-1', 'en', 'Hearing their words, Vasishtha replied to all the friends, ministers and Brahmins.', 'veda-app-ai-draft', true),
('ramayana-2-62-2', 'en', 'Since Bharata lives happily in his uncle''s house in the city of Rajagriha, together with his brother Shatrughna...', 'veda-app-ai-draft', true),
('ramayana-2-62-3', 'en', '...let swift messengers go quickly on fast horses to bring the two heroic brothers. What else should we consider?', 'veda-app-ai-draft', true),
('ramayana-2-62-4', 'en', '''Let them go,'' they all said to Vasishtha. Hearing their words, Vasishtha spoke.', 'veda-app-ai-draft', true),
('ramayana-2-62-5', 'en', 'Come, Siddhartha, Vijaya, Jayanta, Ashoka and Nandana. Listen to what must be done; I tell all of you.', 'veda-app-ai-draft', true),
('ramayana-2-62-6', 'en', 'Go quickly to the city of Rajagriha on swift horses, put aside your grief, and say this to Bharata at my command.', 'veda-app-ai-draft', true),
('ramayana-2-62-7', 'en', '''The royal priest and all the ministers wish you well. Set out quickly; there is urgent business for you.''', 'veda-app-ai-draft', true),
('ramayana-2-62-8', 'en', 'Do not tell him that Rama has been exiled or that his father is dead, this ruin of the Raghavas.', 'veda-app-ai-draft', true),
('ramayana-2-62-9', 'en', 'Take silk garments and fine ornaments quickly for the king and for Bharata, and go.'' Permitted by Vasishtha, the messengers left in haste.', 'veda-app-ai-draft', true),
('ramayana-2-62-10', 'en', 'They crossed the Ganga at Hastinapura and went west, reaching the Panchala country and passing through the middle of Kurujangala.', 'veda-app-ai-draft', true),
('ramayana-2-62-11', 'en', 'They swiftly passed the Sharadanda river, with its clear water, divine and frequented by many birds, crowded with people.', 'veda-app-ai-draft', true),
('ramayana-2-62-12', 'en', 'Reaching the divine tree on the riverbank called Satyopayachana, they approached and saluted it, and entered the city of Kulinga.', 'veda-app-ai-draft', true),
('ramayana-2-62-13', 'en', 'Then reaching Abhikala, they went through the Bahlika country and Mount Sudaman, looking at Vishnu''s footprint, the Vipasha river and the Shalmali.', 'veda-app-ai-draft', true),
('ramayana-2-62-14', 'en', 'Their horses tired, the messengers reached the fine city of Girivraja quickly and directly by a long, good road.', 'veda-app-ai-draft', true),
('ramayana-2-62-15', 'en', 'To please their master, to protect the family and secure the royal line, the messengers, never slackening, hurried and reached that city at night.', 'veda-app-ai-draft', true),
('ramayana-2-63-1', 'en', 'On the very night the messengers entered the city, Bharata had an unpleasant dream.', 'veda-app-ai-draft', true),
('ramayana-2-63-2', 'en', 'When that night ended, having seen that unpleasant dream, the son of the king of kings was deeply troubled.', 'veda-app-ai-draft', true),
('ramayana-2-63-3', 'en', 'Seeing him troubled, his friends, pleasant in speech, told stories in the hall to ease his distress.', 'veda-app-ai-draft', true),
('ramayana-2-63-4', 'en', 'Some played calming music, others had dancers perform, others told plays and many kinds of jokes.', 'veda-app-ai-draft', true),
('ramayana-2-63-5', 'en', 'But great-souled Bharata, of the Raghu line, did not cheer up with those kind friends who joked in company.', 'veda-app-ai-draft', true),
('ramayana-2-63-6', 'en', 'His dear friend, sitting among the companions, asked Bharata, ''Why, friend, do you not enjoy yourself?''', 'veda-app-ai-draft', true),
('ramayana-2-63-7', 'en', 'Bharata replied to his friend: ''Listen to why this gloom has come upon me.''', 'veda-app-ai-draft', true),
('ramayana-2-63-8', 'en', 'In a dream I saw my father, dirty, his hair loose, falling from a mountain peak into a foul pool of cow dung.', 'veda-app-ai-draft', true),
('ramayana-2-63-9', 'en', 'I saw him floating in that pool of dung, drinking oil from his cupped hands and laughing again and again.', 'veda-app-ai-draft', true),
('ramayana-2-63-10', 'en', 'Then eating rice with sesame, again and again head down, his whole body smeared with oil, he plunged into oil.', 'veda-app-ai-draft', true),
('ramayana-2-63-11', 'en', 'In the dream I also saw the ocean dried up, the moon fallen to the earth, and the blazing fire suddenly gone out.', 'veda-app-ai-draft', true),
('ramayana-2-63-12', 'en', 'I see the earth split open, many kinds of trees withered, and mountains shattered and smoking.', 'veda-app-ai-draft', true),
('ramayana-2-63-13', 'en', 'Dark and tawny women laughed at the king as he sat on an iron seat wearing black clothes.', 'veda-app-ai-draft', true),
('ramayana-2-63-14', 'en', 'And the righteous king, wearing red garlands and red paste, went off hastily southward in a chariot drawn by donkeys.', 'veda-app-ai-draft', true),
('ramayana-2-63-15', 'en', 'This is what I saw this frightening night. I, Rama, the king or Lakshmana will die.', 'veda-app-ai-draft', true),
('ramayana-2-63-16', 'en', 'A man who in a dream rides a chariot drawn by donkeys soon has the smoke of his pyre seen. This is why I am gloomy and do not respond to you.', 'veda-app-ai-draft', true),
('ramayana-2-63-17', 'en', 'My throat seems dry, my mind is not at ease. I feel as if I loathe myself, yet I see no reason.', 'veda-app-ai-draft', true),
('ramayana-2-63-18', 'en', 'Hearing this many-sided course of a bad dream, never imagined before, and thinking of the king whose face I cannot picture, a great fear will not leave my heart.', 'veda-app-ai-draft', true),
('ramayana-2-64-1', 'en', 'While Bharata was telling his dream, the messengers with their tired horses entered the lovely city of Rajagriha with its impassable moat.', 'veda-app-ai-draft', true),
('ramayana-2-64-2', 'en', 'Meeting the king and the prince and being honoured by them, they clasped the king''s feet and spoke to Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-64-3', 'en', '''The royal priest and all the ministers wish you well. Set out quickly; there is urgent business for you.''', 'veda-app-ai-draft', true),
('ramayana-2-64-4', 'en', '''Here are two hundred million for the king, your uncle, and a full hundred million for you, prince.''', 'veda-app-ai-draft', true),
('ramayana-2-64-5', 'en', 'Accepting it all, Bharata, devoted to his friends, honoured the messengers with what they wished and spoke to them.', 'veda-app-ai-draft', true),
('ramayana-2-64-6', 'en', 'Is my father, King Dasharatha, well? Is there good health for Rama and for great-souled Lakshmana?', 'veda-app-ai-draft', true),
('ramayana-2-64-7', 'en', 'Is noble Kausalya, devoted to dharma, knowing and seeing dharma, the mother of wise Rama, in good health?', 'veda-app-ai-draft', true),
('ramayana-2-64-8', 'en', 'Is Sumitra, who knows dharma, the mother of Lakshmana and heroic Shatrughna, the middle queen, well?', 'veda-app-ai-draft', true),
('ramayana-2-64-9', 'en', 'And my mother Kaikeyi, always selfish, fierce, quick to anger, proud of her cleverness, is she well? What did she say?', 'veda-app-ai-draft', true),
('ramayana-2-64-10', 'en', 'Addressed so by great-souled Bharata, the messengers then said politely to him: ''Those whose welfare you wish for are well, tiger among men.''', 'veda-app-ai-draft', true),
('ramayana-2-64-11', 'en', 'Told this, Bharata said to the messengers, ''I will take leave of the great king; the messengers are hurrying me.''', 'veda-app-ai-draft', true),
('ramayana-2-64-12', 'en', 'Having spoken thus to the messengers, Prince Bharata, urged by them, spoke to his maternal grandfather.', 'veda-app-ai-draft', true),
('ramayana-2-64-13', 'en', 'King, urged by the messengers I will go to my father. I will come again whenever you think of me.', 'veda-app-ai-draft', true),
('ramayana-2-64-14', 'en', 'Addressed thus by Bharata, his grandfather the king kissed Raghava on the head and spoke kind words.', 'veda-app-ai-draft', true),
('ramayana-2-64-15', 'en', 'Go, dear one, I permit you. Kaikeyi is blessed with a good son in you. Give my greetings to your mother and father, scorcher of foes.', 'veda-app-ai-draft', true),
('ramayana-2-64-16', 'en', '''...and to the royal priest and the other excellent Brahmins, and, dear one, to your brothers Rama and Lakshmana, the great archers.''', 'veda-app-ai-draft', true),
('ramayana-2-64-17', 'en', 'The Kekaya king honoured Bharata and gave him wealth: fine elephants, colourful blankets and deerskins.', 'veda-app-ai-draft', true),
('ramayana-2-64-18', 'en', 'The Kekaya king honoured Kaikeyi''s son and ordered wealth for him: two thousand gold coins and sixteen hundred horses.', 'veda-app-ai-draft', true),
('ramayana-2-64-19', 'en', 'Ashvapati also quickly gave Bharata trusted, capable and virtuous ministers to accompany him.', 'veda-app-ai-draft', true),
('ramayana-2-64-20', 'en', 'His uncle gave him as wealth handsome elephants of the Airavata and Indrashira breeds, and swift, well-trained mules.', 'veda-app-ai-draft', true),
('ramayana-2-64-21', 'en', 'He also gave as a present huge dogs raised in the inner palace, armed with fangs, with the strength and courage of tigers.', 'veda-app-ai-draft', true),
('ramayana-2-64-22', 'en', 'Taking leave of his grandfather and his uncle Yudhajit, Bharata mounted his chariot and left with Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-64-23', 'en', 'Servants yoked over a hundred chariots with round wheels and followed Bharata with camels, oxen, horses and mules.', 'veda-app-ai-draft', true),
('ramayana-2-64-24', 'en', 'Protected by an army, with ministers as dear as himself from his grandfather, great-souled Bharata, free of enemies, took Shatrughna and left the house like a perfected being leaving Indra''s world.', 'veda-app-ai-draft', true),
('ramayana-2-65-1', 'en', 'Setting out eastward from Rajagriha, the mighty and glorious joy of the Ikshvakus crossed the river Hradini, with far banks, and the Shatadru, its waves flowing westward.', 'veda-app-ai-draft', true),
('ramayana-2-65-2', 'en', 'Crossing the river at Eladhana and reaching Aparaparpata, he crossed the Shila and Akurvati and came to Agneya and Shalyakartana.', 'veda-app-ai-draft', true),
('ramayana-2-65-3', 'en', 'True to his word, pure and glorious, gazing at the Shilavaha, he passed great mountains towards the Chaitraratha forest.', 'veda-app-ai-draft', true),
('ramayana-2-65-4', 'en', 'Reaching the swift Kulinga, roaring and hemmed in by hills, and the Yamuna, he crossed and then rested his army.', 'veda-app-ai-draft', true),
('ramayana-2-65-5', 'en', 'Cooling their limbs and refreshing the tired horses, bathing and drinking there, he went on carrying water.', 'veda-app-ai-draft', true),
('ramayana-2-65-6', 'en', 'The noble prince crossed the great, seldom-visited forest in his fine chariot as the wind crosses the sky.', 'veda-app-ai-draft', true),
('ramayana-2-65-7', 'en', 'By the southern side of Torana he reached Jambuprastha, and the son of Dasharatha went on to the lovely village of Varutha.', 'veda-app-ai-draft', true),
('ramayana-2-65-8', 'en', 'Staying there in a lovely forest, he went east to the garden of Ujjihana, where there are priyaka trees.', 'veda-app-ai-draft', true),
('ramayana-2-65-9', 'en', 'Reaching the sala and priyaka trees, Bharata took swift horses, left instructions for the army, and went on quickly.', 'veda-app-ai-draft', true),
('ramayana-2-65-10', 'en', 'Staying at Sarvatirtha and crossing the Uttanaka river and many other rivers with mountain horses...', 'veda-app-ai-draft', true),
('ramayana-2-65-11', 'en', 'Reaching Hastiprishthaka, he passed Kutika. The tiger among men crossed the Kapivati at Lauhitya, the Sthanumati at Ekasala and the Gomati at Vinata.', 'veda-app-ai-draft', true),
('ramayana-2-65-12', 'en', 'Reaching the sala forest at the town of Kalinga, Bharata came quickly, his horses utterly exhausted.', 'veda-app-ai-draft', true),
('ramayana-2-65-13', 'en', 'Quickly crossing the forest, at dawn after the night, he saw Ayodhya, built by King Manu.', 'veda-app-ai-draft', true),
('ramayana-2-65-14', 'en', 'Having spent seven nights on the road, the tiger among men saw the city of Ayodhya ahead and spoke to the charioteer in the chariot.', 'veda-app-ai-draft', true),
('ramayana-2-65-15', 'en', 'Charioteer, this glorious Ayodhya with its holy gardens and pale soil, seen from afar, does not look quite itself to me.', 'veda-app-ai-draft', true),
('ramayana-2-65-16', 'en', '...the city full of worshippers, virtuous Brahmins learned in the Vedas, and wealthy people, protected by the best of royal sages.', 'veda-app-ai-draft', true),
('ramayana-2-65-17', 'en', 'In Ayodhya, a great, loud noise of men and women used to be heard all around. Today I do not hear it.', 'veda-app-ai-draft', true),
('ramayana-2-65-18', 'en', 'At other times the gardens shone in the evening with people running about everywhere after playing.', 'veda-app-ai-draft', true),
('ramayana-2-65-19', 'en', 'Today, abandoned by pleasure-seekers, they seem to weep. Charioteer, the city seems to me like a wilderness.', 'veda-app-ai-draft', true),
('ramayana-2-65-20', 'en', 'Leading men are not seen going out or coming in on carriages, elephants or horses as before.', 'veda-app-ai-draft', true),
('ramayana-2-65-21', 'en', 'I see many kinds of unwelcome, evil and unpleasant omens; that is why my mind sinks.', 'veda-app-ai-draft', true),
('ramayana-2-65-22', 'en', 'With his horses tired he entered by the Vaijayanta gate. The gatekeepers rose, wished him victory, and went with him.', 'veda-app-ai-draft', true),
('ramayana-2-65-23', 'en', 'His mind unsettled, Raghava returned the greeting of the gatekeepers and spoke there to Ashvapati''s weary charioteer.', 'veda-app-ai-draft', true),
('ramayana-2-65-24', 'en', 'Charioteer, all the signs we have heard of before that come at the death of kings, I see here.', 'veda-app-ai-draft', true),
('ramayana-2-65-25', 'en', 'I see the people in the city, men and women, dirty, eyes full of tears, wretched, lost in thought, thin and anxious.', 'veda-app-ai-draft', true),
('ramayana-2-65-26', 'en', 'Having said this to the charioteer, Bharata, sad at heart, seeing these unwelcome signs in Ayodhya, went to the royal palace.', 'veda-app-ai-draft', true),
('ramayana-2-65-27', 'en', 'Seeing the city, once bright as Indra''s city, its crossroads, houses and streets empty, its doors, panels and bolts reddened with dust, he was filled even more with sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-65-28', 'en', 'Seeing many things unpleasant to the mind, which had never been in the city before, great-souled Bharata, head bowed, sad and joyless, entered his father''s house.', 'veda-app-ai-draft', true),
('ramayana-2-66-1', 'en', 'Not seeing his father there in his father''s residence, Bharata went to see his mother in his mother''s residence.', 'veda-app-ai-draft', true),
('ramayana-2-66-2', 'en', 'Seeing her son, who had been away, arrive, Kaikeyi jumped up joyfully, leaving her golden seat.', 'veda-app-ai-draft', true),
('ramayana-2-66-3', 'en', 'Entering his own home, which had lost its splendour, righteous Bharata saw his mother and clasped her lovely feet.', 'veda-app-ai-draft', true),
('ramayana-2-66-4', 'en', 'She kissed the famous Bharata on the head, embraced him, took him on her lap and began to ask questions.', 'veda-app-ai-draft', true),
('ramayana-2-66-5', 'en', 'How many nights is it since you left your grandfather''s house? Are you not tired from the road, coming so fast by chariot?', 'veda-app-ai-draft', true),
('ramayana-2-66-6', 'en', 'Is your grandfather well, and your uncle Yudhajit? Tell me everything, son, about how happy your stay was.', 'veda-app-ai-draft', true),
('ramayana-2-66-7', 'en', 'Questioned thus kindly by Kaikeyi, lotus-eyed Bharata, joy of the king, told his mother everything.', 'veda-app-ai-draft', true),
('ramayana-2-66-8', 'en', 'This is the seventh night since I left grandfather''s house. Your father is well, mother, and so is my uncle Yudhajit.', 'veda-app-ai-draft', true),
('ramayana-2-66-9', 'en', 'The wealth and jewels the king, scorcher of foes, gave me became tired on the road, so I came ahead.', 'veda-app-ai-draft', true),
('ramayana-2-66-10', 'en', 'I have come hurried by messengers bringing the king''s message. Mother, please tell me what I want to ask.', 'veda-app-ai-draft', true),
('ramayana-2-66-11', 'en', 'Your gold-adorned bed is empty, and these Ikshvaku people do not seem happy to me.', 'veda-app-ai-draft', true),
('ramayana-2-66-12', 'en', 'The king is usually here in mother''s residence. I do not see him today, though I came here wanting to see him.', 'veda-app-ai-draft', true),
('ramayana-2-66-13', 'en', 'I will clasp my father''s feet. Tell me, as I ask: or is he, mother, in the residence of the eldest, Kausalya?', 'veda-app-ai-draft', true),
('ramayana-2-66-14', 'en', 'Kaikeyi, deluded by greed for the kingdom, knowing what he did not know, told him the terrible, unwelcome news as if it were pleasant: ''Your father has gone the way all beings go.''', 'veda-app-ai-draft', true),
('ramayana-2-66-15', 'en', 'Hearing that, pure Bharata, of righteous birth, struck by the force of grief for his father, fell suddenly to the ground.', 'veda-app-ai-draft', true),
('ramayana-2-66-16', 'en', 'Then, wrapped in grief, pained by his father''s death, the splendid one lamented, his mind confused and agitated.', 'veda-app-ai-draft', true),
('ramayana-2-66-17', 'en', 'This bed of my father used to look so beautiful before; today it does not shine, without that wise man.', 'veda-app-ai-draft', true),
('ramayana-2-66-18', 'en', 'Seeing him, godlike and stricken, fallen on the ground, she lifted him up, grieving, and said this.', 'veda-app-ai-draft', true),
('ramayana-2-66-19', 'en', 'Get up, get up! Why do you lie there, famous prince? Good people like you, respected in assemblies, do not grieve.', 'veda-app-ai-draft', true),
('ramayana-2-66-20', 'en', 'After weeping a long time and rolling on the ground, covered by many sorrows, he replied to his mother.', 'veda-app-ai-draft', true),
('ramayana-2-66-21', 'en', 'I set out happily, thinking, ''The king will consecrate Rama, or will perform a sacrifice.''', 'veda-app-ai-draft', true),
('ramayana-2-66-22', 'en', 'But it has turned out otherwise, and my heart is broken, for I cannot see my father, who was always devoted to my welfare.', 'veda-app-ai-draft', true),
('ramayana-2-66-23', 'en', 'Mother, of what illness did the king die while I was away? Blessed are Rama and the others, who performed father''s last rites themselves.', 'veda-app-ai-draft', true),
('ramayana-2-66-24', 'en', 'Surely the famous great king does not know I have arrived, or my father would quickly bend down and kiss my head.', 'veda-app-ai-draft', true),
('ramayana-2-66-25', 'en', 'Where is that pleasant-touching hand of my father, tireless in deeds, with which he used to wipe me clean when I was covered in dust?', 'veda-app-ai-draft', true),
('ramayana-2-66-26', 'en', 'Tell me quickly about Rama, tireless in deeds, who is my brother, father and kinsman, whose servant I am.', 'veda-app-ai-draft', true),
('ramayana-2-66-27', 'en', 'For a noble person who knows dharma, the eldest brother becomes a father. I will clasp his feet; he is now my refuge.', 'veda-app-ai-draft', true),
('ramayana-2-66-28', 'en', 'Noble lady, what did the king, my father, true in valour, say? I want to hear his last good message for me.', 'veda-app-ai-draft', true),
('ramayana-2-66-29', 'en', 'Asked this, Kaikeyi told the truth: ''Lamenting "Rama! Alas Sita! Lakshmana!", that great soul, best of those who travel, went to the next world.''', 'veda-app-ai-draft', true),
('ramayana-2-66-30', 'en', 'This was your father''s last speech, caught by the law of time like a great elephant by nooses:', 'veda-app-ai-draft', true),
('ramayana-2-66-31', 'en', '''Fulfilled are the people who will see Rama come back with Sita, and mighty-armed Lakshmana returned.''', 'veda-app-ai-draft', true),
('ramayana-2-66-32', 'en', 'Hearing that second piece of unwelcome news, he was dejected, and with a downcast face he asked his mother again.', 'veda-app-ai-draft', true),
('ramayana-2-66-33', 'en', 'And where now is that righteous one, who increases Kausalya''s joy, gone with his brother Lakshmana and with Sita?', 'veda-app-ai-draft', true),
('ramayana-2-66-34', 'en', 'Asked thus, his mother began to tell the truth, the unwelcome news, all at once, thinking it would please him.', 'veda-app-ai-draft', true),
('ramayana-2-66-35', 'en', 'Son, that prince has gone to the great Dandaka forest, wearing bark clothes, with Vaidehi, followed by Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-66-36', 'en', 'Hearing that, Bharata was alarmed, fearing for his brother''s conduct, and because of the greatness of his family began to ask.', 'veda-app-ai-draft', true),
('ramayana-2-66-37', 'en', 'Has Rama perhaps taken some Brahmin''s wealth? Has he harmed some innocent person, rich or poor?', 'veda-app-ai-draft', true),
('ramayana-2-66-38', 'en', 'Has the prince desired another man''s wife? Why has he been exiled to the Dandaka forest like a murderer?', 'veda-app-ai-draft', true),
('ramayana-2-66-39', 'en', 'Then his fickle mother began to describe her own deed exactly as it was, with that same nature.', 'veda-app-ai-draft', true),
('ramayana-2-66-40', 'en', 'Rama took no Brahmin''s wealth, harmed no innocent person rich or poor, and Rama does not even look at other men''s wives.', 'veda-app-ai-draft', true),
('ramayana-2-66-41', 'en', 'But son, as soon as I heard of Rama''s consecration, I asked your father for the kingdom for you and for Rama''s exile.', 'veda-app-ai-draft', true),
('ramayana-2-66-42', 'en', 'Your father, keeping to his word, did just that, and Rama was sent away with Lakshmana and Sita.', 'veda-app-ai-draft', true),
('ramayana-2-66-43', 'en', 'Not seeing his beloved son, the famous king, worn out by grief for his son, died.', 'veda-app-ai-draft', true),
('ramayana-2-66-44', 'en', 'Now, knower of dharma, take up the kingship, for I have done all this for your sake.', 'veda-app-ai-draft', true),
('ramayana-2-66-45', 'en', 'So, son, quickly, with Vasishtha and the chief Brahmins who know the rites, perform the king''s funeral and have yourself, of undaunted spirit, consecrated over the earth.', 'veda-app-ai-draft', true),
('ramayana-2-67-1', 'en', 'Hearing that his father had died and his two brothers had been exiled, Bharata, burning with sorrow, spoke these words.', 'veda-app-ai-draft', true),
('ramayana-2-67-2', 'en', 'What use is a kingdom to me, struck down and grieving, deprived of my father and of my brother who was like a father?', 'veda-app-ai-draft', true),
('ramayana-2-67-3', 'en', 'You have added sorrow to my sorrow, like rubbing salt into a wound, by sending the king to his death and making Rama an ascetic.', 'veda-app-ai-draft', true),
('ramayana-2-67-4', 'en', 'You have come like the night of doom to destroy this family. My father embraced a burning coal and did not know it.', 'veda-app-ai-draft', true),
('ramayana-2-67-5', 'en', 'Kausalya and Sumitra, crushed by grief for their sons, will hardly be able to live now that they have you as my mother.', 'veda-app-ai-draft', true),
('ramayana-2-67-6', 'en', 'Even the noble, righteous Rama, who knows how to treat elders, behaved towards you with the highest regard, as he would towards his own mother.', 'veda-app-ai-draft', true),
('ramayana-2-67-7', 'en', 'And my eldest mother, far-sighted Kausalya, following dharma, treated you like a sister.', 'veda-app-ai-draft', true),
('ramayana-2-67-8', 'en', 'Having sent her self-disciplined son into forest exile wearing bark clothes, how do you not grieve, wicked one?', 'veda-app-ai-draft', true),
('ramayana-2-67-9', 'en', 'Having banished the brave, glorious, self-disciplined hero, who sees no evil, in bark clothes, what reason do you see in it?', 'veda-app-ai-draft', true),
('ramayana-2-67-10', 'en', 'I think, greedy as you are, you did not know how I feel towards Raghava, and so for the sake of the kingdom you brought about this great disaster.', 'veda-app-ai-draft', true),
('ramayana-2-67-11', 'en', 'Without seeing those two tigers among men, Rama and Lakshmana, by what strength could I dare protect the kingdom?', 'veda-app-ai-draft', true),
('ramayana-2-67-12', 'en', 'The mighty, righteous great king always relied on that strong one, as Mount Meru relies on its forest.', 'veda-app-ai-draft', true),
('ramayana-2-67-13', 'en', 'How can I, like an untrained bullock put to a yoke meant for a great ox, bear this burden? With what strength?', 'veda-app-ai-draft', true),
('ramayana-2-67-14', 'en', 'Or even if I had the strength, by means or by intelligence, I will not fulfil your wish, greedy for your son. I will bring my brother, dear to his people, back from the forest.', 'veda-app-ai-draft', true),
('ramayana-2-67-15', 'en', 'Having said this, great-souled Bharata, wounding her with many unkind words, roared again in grief like a lion in a mountain cave.', 'veda-app-ai-draft', true),
('ramayana-2-68-1', 'en', 'Having reproached his mother so, Bharata, filled with great anger, spoke again.', 'veda-app-ai-draft', true),
('ramayana-2-68-2', 'en', 'Fall from the kingdom, Kaikeyi, cruel, wicked woman! Abandoned by dharma, do not weep for the dead.', 'veda-app-ai-draft', true),
('ramayana-2-68-3', 'en', 'What wrong did the king or the deeply righteous Rama do you, that death and exile came to them equally because of you?', 'veda-app-ai-draft', true),
('ramayana-2-68-4', 'en', 'By destroying this family you have incurred the sin of killing the innocent. Kaikeyi, go to hell, and not to your husband''s world.', 'veda-app-ai-draft', true),
('ramayana-2-68-5', 'en', 'By the sin you have committed through this terrible deed, abandoning him whom all the world loves, you have brought fear on me too.', 'veda-app-ai-draft', true),
('ramayana-2-68-6', 'en', 'Because of you my father is dead and Rama has gone to the forest, and you have brought me dishonour in the world of the living.', 'veda-app-ai-draft', true),
('ramayana-2-68-7', 'en', 'Enemy in the shape of a mother, cruel, greedy for the kingdom, wicked, killer of your husband, I will not speak to you.', 'veda-app-ai-draft', true),
('ramayana-2-68-8', 'en', 'Kausalya, Sumitra and my other mothers are filled with great sorrow, having you, who defile the family.', 'veda-app-ai-draft', true),
('ramayana-2-68-9', 'en', 'You are not the daughter of wise Ashvapati, king of dharma. You were born there a rakshasi, destroyer of your father''s family.', 'veda-app-ai-draft', true),
('ramayana-2-68-10', 'en', '...since by you righteous Rama, always devoted to truth, was sent to the forest, and in grief my father went to heaven...', 'veda-app-ai-draft', true),
('ramayana-2-68-11', 'en', '...you are the chief cause of that sin, putting it upon me, deprived of my father, abandoned by my brothers and hateful to the whole world.', 'veda-app-ai-draft', true),
('ramayana-2-68-12', 'en', 'Having separated righteous Kausalya from her son, set on evil, what world will you reach now, bound for hell?', 'veda-app-ai-draft', true),
('ramayana-2-68-13', 'en', 'Cruel one, do you not understand that Rama, Kausalya''s own son, the eldest, like a father, is the steady refuge of his kin?', 'veda-app-ai-draft', true),
('ramayana-2-68-14', 'en', 'A son is born from every limb and from the heart. So he is dearer to his mother; through love, no kinsman is so dear.', 'veda-app-ai-draft', true),
('ramayana-2-68-15', 'en', 'Once, they say, Surabhi, who knows dharma and is honoured by the gods, saw on the earth her two sons, bullocks, exhausted while hauling.', 'veda-app-ai-draft', true),
('ramayana-2-68-16', 'en', 'Seeing her two sons tired on the ground at midday, she wept with grief for her sons, her eyes full of tears.', 'veda-app-ai-draft', true),
('ramayana-2-68-17', 'en', 'Fine, fragrant drops fell on the body of great-souled Indra, king of the gods, who was passing beneath her.', 'veda-app-ai-draft', true),
('ramayana-2-68-18', 'en', 'Seeing the glorious one burning with grief, Indra, the wielder of the thunderbolt, king of the gods, alarmed, folded his hands and spoke.', 'veda-app-ai-draft', true),
('ramayana-2-68-19', 'en', 'Is there some great danger to us from anywhere? Why are you grieving? Tell me, you who wish all beings well.', 'veda-app-ai-draft', true),
('ramayana-2-68-20', 'en', 'Addressed thus by the wise king of the gods, Surabhi, steady and skilled in speech, replied.', 'veda-app-ai-draft', true),
('ramayana-2-68-21', 'en', 'Lord of immortals, may no harm come to you from anywhere. I grieve for my two sons who have sunk into hardship.', 'veda-app-ai-draft', true),
('ramayana-2-68-22', 'en', 'Lord of gods, I see these two oxen, thin and miserable, burned by the sun''s rays, being beaten by the ploughman.', 'veda-app-ai-draft', true),
('ramayana-2-68-23', 'en', 'Born from my body, suffering and crushed by burdens, seeing them I am tormented. Nothing is as dear as a son.', 'veda-app-ai-draft', true),
('ramayana-2-68-24', 'en', 'If she who grants all wishes and has thousands of sons still grieves, how will Kausalya live without Rama?', 'veda-app-ai-draft', true),
('ramayana-2-68-25', 'en', 'This good woman with only one son has been made childless by you. So you will always find sorrow, here and after death.', 'veda-app-ai-draft', true),
('ramayana-2-68-26', 'en', 'I will without doubt make full amends to my brother and my father and increase their honour.', 'veda-app-ai-draft', true),
('ramayana-2-68-27', 'en', 'I will bring back Kausalya''s radiant son, and I myself will enter the forest frequented by sages.', 'veda-app-ai-draft', true),
('ramayana-2-68-28', 'en', 'Then, like an elephant in the forest goaded by lance and hook, he fell to the ground in fury, hissing like a snake.', 'veda-app-ai-draft', true),
('ramayana-2-68-29', 'en', 'His eyes red, his clothes loose, all his ornaments thrown off, the prince, scorcher of foes, lay fallen on the ground like Indra''s banner at the end of a festival.', 'veda-app-ai-draft', true),
('ramayana-2-69-1', 'en', 'Hearing great-souled Bharata crying out like this, Kausalya said this to Sumitra.', 'veda-app-ai-draft', true),
('ramayana-2-69-2', 'en', 'Bharata, the son of cruel Kaikeyi, has come. I want to see far-sighted Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-69-3', 'en', 'Having said this to Sumitra, pale and in soiled clothes, trembling and dazed, she set out to where Bharata was.', 'veda-app-ai-draft', true),
('ramayana-2-69-4', 'en', 'And Bharata, Rama''s younger brother, with Shatrughna, set out at the same time towards Kausalya''s residence.', 'veda-app-ai-draft', true),
('ramayana-2-69-5', 'en', 'Then Shatrughna and Bharata, seeing Kausalya fallen and senseless with grief, sorrowfully embraced her.', 'veda-app-ai-draft', true),
('ramayana-2-69-6', 'en', 'Deeply grieved, Kausalya said this to Bharata: ''Here is the kingdom you wanted, free of rivals. Alas, Kaikeyi has quickly won it by a cruel deed.''', 'veda-app-ai-draft', true),
('ramayana-2-69-7', 'en', 'Having sent my son to live in the forest in bark clothes, what good does cruel-eyed Kaikeyi see in it?', 'veda-app-ai-draft', true),
('ramayana-2-69-8', 'en', 'Kaikeyi should quickly send me too to where my very famous son with the golden navel is.', 'veda-app-ai-draft', true),
('ramayana-2-69-9', 'en', 'Or I will go myself, happily, with Sumitra following, carrying the sacred fire before me, to where Raghava is.', 'veda-app-ai-draft', true),
('ramayana-2-69-10', 'en', 'Or you yourself should take me today to where that tiger among men, my son, is practising austerities.', 'veda-app-ai-draft', true),
('ramayana-2-69-11', 'en', 'For this wide kingdom, full of wealth and grain, filled with elephants, horses and chariots, has been handed to you by her.', 'veda-app-ai-draft', true),
('ramayana-2-69-12', 'en', 'As she lamented thus, Bharata folded his hands and spoke to Kausalya, who was overwhelmed by many sorrows.', 'veda-app-ai-draft', true),
('ramayana-2-69-13', 'en', 'Noble lady, why do you blame me, innocent and unaware? You know my great and steady love for Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-69-14', 'en', 'May the person by whose consent the noble one, true to his word and best of the good, went away, never have a mind that follows the scriptures.', 'veda-app-ai-draft', true),
('ramayana-2-69-15', 'en', 'May he become a servant of the most wicked, may he urinate facing the sun, may he kick a sleeping cow, he by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-16', 'en', 'Whatever sin a master incurs who makes a servant do great work and then gives him nothing, may that be his, by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-17', 'en', 'May the sin of those who betray a king who protects all beings like his children fall on him by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-18', 'en', 'Whatever wrong a king commits who takes a sixth of the produce as tax yet does not protect his people, may that be his, by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-19', 'en', 'May the sin of those who promise sacrificial fees to ascetics at a ceremony and then deny them fall on him by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-20', 'en', 'In battle crowded with elephants, horses and chariots and full of weapons, may he not follow the code of the good, he by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-21', 'en', 'May that wicked one destroy the subtle teaching carefully taught by a wise teacher, he by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-22', 'en', 'May he, heartless, eat rice pudding, sesame rice and goat''s meat for no sacred purpose, and may he insult his elders, he by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-23', 'en', 'Surrounded by sons, wives and servants in his own house, may he eat fine food alone, he by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-24', 'en', 'May he incur the sin said to belong to killing a king, a woman, a child or an old person, and the sin of abandoning dependants.', 'veda-app-ai-draft', true),
('ramayana-2-69-25', 'en', 'Whatever sin is held to fall on one who sleeps at both twilights, may that sin be his, by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-26', 'en', 'May he incur the sin of an arsonist, the sin of one who violates his teacher''s bed, and the sin of betraying a friend.', 'veda-app-ai-draft', true),
('ramayana-2-69-27', 'en', 'May he never serve the gods, the ancestors, or his mother and father, he by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-28', 'en', 'May he quickly, this very day, fall from the world of the good, from the fame of the good, and from deeds the good practise, he by whose consent the noble one went.', 'veda-app-ai-draft', true),
('ramayana-2-69-29', 'en', 'Comforting Kausalya, bereft of husband and son, in this way, the prince, overcome by sorrow, fell down.', 'veda-app-ai-draft', true),
('ramayana-2-69-30', 'en', 'As Bharata, burning with grief, lay senseless, swearing such grievous oaths, Kausalya spoke to him.', 'veda-app-ai-draft', true),
('ramayana-2-69-31', 'en', 'Son, this sorrow of mine grows even more, for by swearing these oaths you choke my very breath.', 'veda-app-ai-draft', true),
('ramayana-2-69-32', 'en', 'Thank goodness your heart, like Lakshmana''s, has not swerved from dharma. Child, true to your word, you will reach the worlds of the good.', 'veda-app-ai-draft', true),
('ramayana-2-69-33', 'en', 'As the great-souled one lamented, stricken with sorrow, his mind was shaken by confusion and the weight of grief.', 'veda-app-ai-draft', true),
('ramayana-2-69-34', 'en', 'As he lay on the ground, lamenting over and over, senseless, his mind lost, sighing long and often, that night passed in grief.', 'veda-app-ai-draft', true),
('ramayana-2-70-1', 'en', 'To Bharata, Kaikeyi''s son, burning with grief, Vasishtha, best of speakers, the sage of fine words, spoke.', 'veda-app-ai-draft', true),
('ramayana-2-70-2', 'en', 'Enough of grief, may you be well, famous prince. Perform the king''s final journey, which is now due.', 'veda-app-ai-draft', true),
('ramayana-2-70-3', 'en', 'Hearing Vasishtha''s words, Bharata steadied himself and, knowing dharma, had all the funeral rites performed.', 'veda-app-ai-draft', true),
('ramayana-2-70-4', 'en', 'The king was taken out of the oil and laid on the ground, his face yellowish, as though asleep.', 'veda-app-ai-draft', true),
('ramayana-2-70-5', 'en', 'Laying him on a fine bed adorned with many jewels, his son, deeply grieved, lamented over Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-2-70-6', 'en', 'King, what did you decide while I was away and had not returned, having exiled righteous Rama and mighty Lakshmana?', 'veda-app-ai-draft', true),
('ramayana-2-70-7', 'en', 'Where will you go, great king, leaving these grieving people, without Rama, the lion among men, tireless in deeds?', 'veda-app-ai-draft', true),
('ramayana-2-70-8', 'en', 'King, father, who will provide for the welfare and safety of this city now that you have gone to heaven and Rama has gone to the forest?', 'veda-app-ai-draft', true),
('ramayana-2-70-9', 'en', 'King, the earth, widowed without you, does not shine. The city seems to me like a night without the moon.', 'veda-app-ai-draft', true),
('ramayana-2-70-10', 'en', 'As Bharata lamented thus, sad at heart, the great sage Vasishtha spoke to him again.', 'veda-app-ai-draft', true),
('ramayana-2-70-11', 'en', 'Mighty-armed one, let the funeral rites due to this lord of the people be done calmly and without hesitation.', 'veda-app-ai-draft', true),
('ramayana-2-70-12', 'en', 'Saying ''So be it'' and honouring Vasishtha''s words, Bharata hurried all the officiating priests, royal priests and teachers.', 'veda-app-ai-draft', true),
('ramayana-2-70-13', 'en', 'The king''s sacred fires, brought out of the fire-house, were carried ahead by the priests and sacrificers according to the rules.', 'veda-app-ai-draft', true),
('ramayana-2-70-14', 'en', 'Then the attendants, choked with tears and heavy-hearted, placed the lifeless king on a palanquin and carried him.', 'veda-app-ai-draft', true),
('ramayana-2-70-15', 'en', 'People went ahead of the king, scattering silver, gold and many kinds of cloth along the road.', 'veda-app-ai-draft', true),
('ramayana-2-70-16', 'en', 'Others brought sandalwood, aloe resin, sarala, padmaka and deodar wood and built the pyre.', 'veda-app-ai-draft', true),
('ramayana-2-70-17', 'en', 'After placing many kinds of fragrant substances there, the priests laid the king in the middle of the pyre.', 'veda-app-ai-draft', true),
('ramayana-2-70-18', 'en', 'Offering into the fire, his priests murmured prayers, and the Sama chanters sang Sama hymns there as the scriptures direct.', 'veda-app-ai-draft', true),
('ramayana-2-70-19', 'en', 'The king''s wives, in palanquins and carriages as befitted them, left the city then, surrounded by elders.', 'veda-app-ai-draft', true),
('ramayana-2-70-20', 'en', 'The priests and the grieving women, led by Kausalya, walked around the king on the pyre, keeping it to their left.', 'veda-app-ai-draft', true),
('ramayana-2-70-21', 'en', 'There the cry of the women was heard, like that of krauncha birds, thousands of them crying out pitifully in their distress.', 'veda-app-ai-draft', true),
('ramayana-2-70-22', 'en', 'Then the noble women, weeping helplessly and lamenting again and again, came down from their carriages to the bank of the Sarayu.', 'veda-app-ai-draft', true),
('ramayana-2-70-23', 'en', 'Having offered water with Bharata, the royal women, ministers and priests entered the city, their eyes filled with tears, and spent ten days in grief, sleeping on the ground.', 'veda-app-ai-draft', true),
('ramayana-2-71-1', 'en', 'When the ten days had passed and he had been purified, on the twelfth day the prince had the shraddha rites performed.', 'veda-app-ai-draft', true),
('ramayana-2-71-2', 'en', 'He gave the Brahmins jewels, wealth and plenty of food, white goats in great number, and hundreds of cows.', 'veda-app-ai-draft', true),
('ramayana-2-71-3', 'en', 'The king''s son gave the Brahmins servants, carriages and very large houses for the king''s welfare after death.', 'veda-app-ai-draft', true),
('ramayana-2-71-4', 'en', 'Then at dawn on the thirteenth day, mighty-armed Bharata, overcome by grief, lamented.', 'veda-app-ai-draft', true),
('ramayana-2-71-5', 'en', 'His throat choked so he could hardly speak, he came to gather the remains, and at the foot of his father''s pyre he said in deep sorrow:', 'veda-app-ai-draft', true),
('ramayana-2-71-6', 'en', 'Father, my brother Raghava, to whom you entrusted me, has gone to the forest, and I am left alone and abandoned by you.', 'veda-app-ai-draft', true),
('ramayana-2-71-7', 'en', 'Her son, the refuge of the helpless, has been banished to the forest. Where have you gone, king, leaving mother Kausalya?', 'veda-app-ai-draft', true),
('ramayana-2-71-8', 'en', 'Seeing the ash-red circle of burnt bones where his father''s body had been consumed, he groaned and sank down.', 'veda-app-ai-draft', true),
('ramayana-2-71-9', 'en', 'Seeing it, weeping and wretched, he fell to the ground like Indra''s banner falling while being raised.', 'veda-app-ai-draft', true),
('ramayana-2-71-10', 'en', 'Then all his ministers ran to him, pure in his vows, as the sages ran to Yayati when he fell at the end of his merit.', 'veda-app-ai-draft', true),
('ramayana-2-71-11', 'en', 'Shatrughna too, seeing Bharata flooded with grief, fell senseless to the ground, remembering the king.', 'veda-app-ai-draft', true),
('ramayana-2-71-12', 'en', 'As if mad and senseless, he lamented in deep sorrow, remembering his father''s many virtues one by one.', 'veda-app-ai-draft', true),
('ramayana-2-71-13', 'en', 'This fierce ocean of sorrow, rising from Manthara, full of the crocodile Kaikeyi, made of the granting of boons and impossible to stir, has drowned us.', 'veda-app-ai-draft', true),
('ramayana-2-71-14', 'en', 'Father, where have you gone, leaving lamenting Bharata, tender and young, whom you always pampered?', 'veda-app-ai-draft', true),
('ramayana-2-71-15', 'en', 'Did you not offer all of us food, drink, clothes and ornaments? Who will do that for us now?', 'veda-app-ai-draft', true),
('ramayana-2-71-16', 'en', 'At this time when it should break apart, the earth does not split, though it has lost you, the great-souled king who knew dharma.', 'veda-app-ai-draft', true),
('ramayana-2-71-17', 'en', 'With my father gone to heaven and Rama in the forest, what power do I have to live? I will enter the fire.', 'veda-app-ai-draft', true),
('ramayana-2-71-18', 'en', 'Bereft of my brother and father, I will not enter empty Ayodhya, ruled by the Ikshvakus; I will enter a forest of austerity.', 'veda-app-ai-draft', true),
('ramayana-2-71-19', 'en', 'Hearing their lament and seeing the disaster, all the followers were even more stricken.', 'veda-app-ai-draft', true),
('ramayana-2-71-20', 'en', 'Then Shatrughna and Bharata, both dejected and exhausted, writhed on the ground like two bulls with broken horns.', 'veda-app-ai-draft', true),
('ramayana-2-71-21', 'en', 'Then Vasishtha, their father''s priest, steady in nature and wise, raised Bharata and spoke to him.', 'veda-app-ai-draft', true),
('ramayana-2-71-22', 'en', 'Three pairs of opposites act on all beings without distinction. Since they cannot be avoided, you should not behave like this.', 'veda-app-ai-draft', true),
('ramayana-2-71-23', 'en', 'Sumantra, who knew the truth, raised and calmed Shatrughna and told him about the arising and passing away of all beings.', 'veda-app-ai-draft', true),
('ramayana-2-71-24', 'en', 'Raised up, those two famous tigers among men shone like two of Indra''s banners soaked by rain and sun.', 'veda-app-ai-draft', true),
('ramayana-2-71-25', 'en', 'As they wiped their tears, red-eyed and speaking sadly, the ministers urged the two sons to perform the remaining rites.', 'veda-app-ai-draft', true),
('ramayana-2-72-1', 'en', 'As Bharata, burning with grief, was planning to set out, Shatrughna, Lakshmana''s younger brother, said this to him.', 'veda-app-ai-draft', true),
('ramayana-2-72-2', 'en', 'Rama, full of goodness, who is the refuge of all beings in sorrow, let alone his own family, has been sent to the forest by a woman.', 'veda-app-ai-draft', true),
('ramayana-2-72-3', 'en', 'And that strong, brave one called Lakshmana, why did he not free Rama, even by restraining our father?', 'veda-app-ai-draft', true),
('ramayana-2-72-4', 'en', 'The king should have been restrained from the start, considering right and wrong policy, when he took the wrong path and fell under a woman''s control.', 'veda-app-ai-draft', true),
('ramayana-2-72-5', 'en', 'As Shatrughna was speaking, the hunchbacked woman appeared at the eastern gate, adorned with all her ornaments.', 'veda-app-ai-draft', true),
('ramayana-2-72-6', 'en', 'She was smeared with fine sandal paste and wore royal clothes, decorated with colourful girdles and strings.', 'veda-app-ai-draft', true),
('ramayana-2-72-7', 'en', 'Seeing her who had done such great wrong, the gatekeeper seized the hunchbacked woman roughly and handed her over to Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-72-8', 'en', '''Here is the wicked, cruel woman because of whom Rama is in the forest and your father has given up his body. Do with her as you think fit.''', 'veda-app-ai-draft', true),
('ramayana-2-72-9', 'en', 'Hearing those words, Shatrughna, deeply grieved and firm in his vows, said this to all the palace attendants.', 'veda-app-ai-draft', true),
('ramayana-2-72-10', 'en', 'Let her who caused such sharp pain to my brothers and my father taste the fruit of her cruel deed.', 'veda-app-ai-draft', true),
('ramayana-2-72-11', 'en', 'Having said this, he quickly seized the hunchbacked woman by force among her companions, and she made the house ring with her cries.', 'veda-app-ai-draft', true),
('ramayana-2-72-12', 'en', 'Then all her companions, greatly distressed, seeing Shatrughna''s anger, fled in every direction.', 'veda-app-ai-draft', true),
('ramayana-2-72-13', 'en', 'All her companions conferred together: ''The way he has started, he will destroy us completely.''', 'veda-app-ai-draft', true),
('ramayana-2-72-14', 'en', '''Let us take refuge with Kausalya, who is compassionate, generous, righteous and famous. She will surely be our refuge.''', 'veda-app-ai-draft', true),
('ramayana-2-72-15', 'en', 'Shatrughna, scorcher of foes, his eyes red with fury, then dragged the screaming hunchbacked woman along the ground.', 'veda-app-ai-draft', true),
('ramayana-2-72-16', 'en', 'As Manthara was dragged here and there, her many colourful ornaments scattered on the ground.', 'veda-app-ai-draft', true),
('ramayana-2-72-17', 'en', 'Strewn with those ornaments, the splendid royal palace shone like the autumn sky.', 'veda-app-ai-draft', true),
('ramayana-2-72-18', 'en', 'That strong bull among men, holding her firmly in his anger, rebuked Kaikeyi and spoke harsh words to her.', 'veda-app-ai-draft', true),
('ramayana-2-72-19', 'en', 'Deeply pained by those harsh and hurtful words, Kaikeyi, terrified of Shatrughna, ran to her son for refuge.', 'veda-app-ai-draft', true),
('ramayana-2-72-20', 'en', 'Seeing her, Bharata said to the angry Shatrughna: ''Women are not to be killed by any being. Let her be forgiven.''', 'veda-app-ai-draft', true),
('ramayana-2-72-21', 'en', 'I would kill this wicked, ill-behaved Kaikeyi myself, if righteous Rama would not despise me as a matricide.', 'veda-app-ai-draft', true),
('ramayana-2-72-22', 'en', 'If Raghava knew that even this hunchbacked woman had been killed, the righteous one would surely never speak to you or me again.', 'veda-app-ai-draft', true),
('ramayana-2-72-23', 'en', 'Hearing Bharata''s words, Shatrughna, Lakshmana''s younger brother, turned away from his anger and released Manthara.', 'veda-app-ai-draft', true),
('ramayana-2-72-24', 'en', 'Manthara fell at Kaikeyi''s feet, sighing, in great distress, and lamented pitifully.', 'veda-app-ai-draft', true),
('ramayana-2-72-25', 'en', 'Seeing the hunchbacked woman, dazed from Shatrughna''s rough handling and in distress, Bharata''s mother gently comforted her, looking at her like a trapped krauncha bird.', 'veda-app-ai-draft', true),
('ramayana-2-73-1', 'en', 'Then at dawn on the fourteenth day the king-makers gathered and spoke to Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-73-2', 'en', 'Dasharatha, our most revered elder, has gone to heaven, having exiled the eldest, Rama, and mighty Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-73-3', 'en', 'Famous prince, be our king today. Then this leaderless kingdom will come to no harm.', 'veda-app-ai-draft', true),
('ramayana-2-73-4', 'en', 'Raghava, your kinsmen and the guilds are waiting for you, prince, with everything ready for the consecration.', 'veda-app-ai-draft', true),
('ramayana-2-73-5', 'en', 'Bharata, take the great kingdom of your fathers and grandfathers. Have yourself consecrated and protect us, bull among men.', 'veda-app-ai-draft', true),
('ramayana-2-73-6', 'en', 'Walking reverently around all the consecration items, Bharata, firm in his vows, replied to all the people.', 'veda-app-ai-draft', true),
('ramayana-2-73-7', 'en', 'In our family the kingship has always belonged to the eldest. You good people should not speak to me like this.', 'veda-app-ai-draft', true),
('ramayana-2-73-8', 'en', 'Rama, our elder brother, will be lord of the earth. I will live in the forest for fourteen years.', 'veda-app-ai-draft', true),
('ramayana-2-73-9', 'en', 'Let a great army with its four divisions be readied. I will bring my eldest brother Raghava back from the forest.', 'veda-app-ai-draft', true),
('ramayana-2-73-10', 'en', 'Taking all these prepared consecration items ahead, I will go to the forest for Rama''s sake.', 'veda-app-ai-draft', true),
('ramayana-2-73-11', 'en', 'There I will consecrate that tiger among men and bring Rama back, honoured before all, as the sacred fire is brought from the sacrifice.', 'veda-app-ai-draft', true),
('ramayana-2-73-12', 'en', 'I will not fulfil the wish of this woman who is my mother only in name. I will live in the hard forest; Rama will be king.', 'veda-app-ai-draft', true),
('ramayana-2-73-13', 'en', 'Let craftsmen make a road, levelling the uneven places, and let guards who scout difficult terrain go along the road.', 'veda-app-ai-draft', true),
('ramayana-2-73-14', 'en', 'As the prince spoke thus for Rama''s sake, all the people replied with these excellent, auspicious words.', 'veda-app-ai-draft', true),
('ramayana-2-73-15', 'en', 'Since you, speaking so, wish to give the earth to the eldest prince, may lotus-dwelling Lakshmi, goddess of fortune, wait upon you.', 'veda-app-ai-draft', true),
('ramayana-2-73-16', 'en', 'Hearing those excellent words of the prince, tears of joy fell from the noble people''s eyes.', 'veda-app-ai-draft', true),
('ramayana-2-73-17', 'en', 'Hearing this, the ministers and the assembly, their grief gone, said joyfully: ''At your command the people, devoted to the best of men, and the craftsmen have been ordered to build the road.''', 'veda-app-ai-draft', true),
('ramayana-2-74-1', 'en', 'Then those who knew the land, experts in measuring with cords, devoted to their work, brave diggers and engineers...', 'veda-app-ai-draft', true),
('ramayana-2-74-2', 'en', '...overseers, architects, men skilled with machines, carpenters, road-makers and woodcutters...', 'veda-app-ai-draft', true),
('ramayana-2-74-3', 'en', '...well-diggers, plasterers, bamboo-workers and capable supervisors went on ahead.', 'veda-app-ai-draft', true),
('ramayana-2-74-4', 'en', 'That vast crowd of people moving joyfully towards that place looked like the great surge of the ocean at the full moon.', 'veda-app-ai-draft', true),
('ramayana-2-74-5', 'en', 'Those experts in road-building, each in his group, set out ahead with all kinds of tools.', 'veda-app-ai-draft', true),
('ramayana-2-74-6', 'en', 'Clearing creepers, vines, bushes, stumps and stones, and cutting many kinds of trees, the people made the road.', 'veda-app-ai-draft', true),
('ramayana-2-74-7', 'en', 'Where there were no trees, some planted trees; others cut here and there with axes, chisels and sickles.', 'veda-app-ai-draft', true),
('ramayana-2-74-8', 'en', 'Other very strong men cleared clumps of virana grass and levelled rough places and mounds here and there.', 'veda-app-ai-draft', true),
('ramayana-2-74-9', 'en', 'Others filled wells and long pits with earth, and some levelled the low places all around.', 'veda-app-ai-draft', true),
('ramayana-2-74-10', 'en', 'Then the men bridged what needed bridging, crushed what needed crushing and broke through what needed breaking, in various places.', 'veda-app-ai-draft', true),
('ramayana-2-74-11', 'en', 'In a short time they made many channels full of water, of many shapes, like seas, and many kinds of wells adorned with platforms.', 'veda-app-ai-draft', true),
('ramayana-2-74-12', 'en', 'With floors paved with plaster, flowering trees, flocks of excited birds singing, and decorated with banners...', 'veda-app-ai-draft', true),
('ramayana-2-74-13', 'en', '...sprinkled with sandal water and adorned with many flowers, the army''s road shone greatly, like the road to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-74-14', 'en', 'Then the officers in charge, as ordered, in pleasant places with many sweet fruits...', 'veda-app-ai-draft', true),
('ramayana-2-74-15', 'en', '...decorated even more with ornaments the camp intended for great-souled Bharata, already like an ornament itself.', 'veda-app-ai-draft', true),
('ramayana-2-74-16', 'en', 'Experts set up great-souled Bharata''s camp under favourable stars and at auspicious moments.', 'veda-app-ai-draft', true),
('ramayana-2-74-17', 'en', 'With many earth ramparts, surrounded by moats, like Indra''s pillar, adorned with fine gateways...', 'veda-app-ai-draft', true),
('ramayana-2-74-18', 'en', '...with rows of mansions, enclosed by white walls, all decorated with banners, with well-made main roads...', 'veda-app-ai-draft', true),
('ramayana-2-74-19', 'en', '...with tall towers rising as if spreading into the sky, those camps shone like Indra''s city.', 'veda-app-ai-draft', true),
('ramayana-2-74-20', 'en', 'Reaching the Ganga, with forests of many trees, cool and clear water, and full of great fish...', 'veda-app-ai-draft', true),
('ramayana-2-74-21', 'en', 'As the clear night sky shines adorned with the moon and hosts of stars, so the lovely royal road, built by fine craftsmen, shone more and more.', 'veda-app-ai-draft', true),
('ramayana-2-75-1', 'en', 'Then, on the night before the auspicious ceremony, bards and heralds skilled in fine speech praised Bharata with auspicious hymns.', 'veda-app-ai-draft', true),
('ramayana-2-75-2', 'en', 'The watch drum, struck with golden sticks, sounded; they blew hundreds of conches and instruments of high and low pitch.', 'veda-app-ai-draft', true),
('ramayana-2-75-3', 'en', 'That great sound of instruments, filling the sky as it were, pierced grief-stricken Bharata with sorrow again.', 'veda-app-ai-draft', true),
('ramayana-2-75-4', 'en', 'Then, waking, Bharata stopped the sound, saying ''I am not the king,'' and spoke to Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-75-5', 'en', 'See, Shatrughna, the great harm Kaikeyi has done the world. King Dasharatha has gone, leaving his sorrows to me.', 'veda-app-ai-draft', true),
('ramayana-2-75-6', 'en', 'The royal fortune of that great-souled king of dharma, rooted in dharma, drifts about like a boat without a helmsman on the water.', 'veda-app-ai-draft', true),
('ramayana-2-75-7', 'en', 'Seeing Bharata lamenting senselessly, all the women wept aloud pitifully.', 'veda-app-ai-draft', true),
('ramayana-2-75-8', 'en', 'While he was lamenting, famous Vasishtha, who knew the duties of kings, entered the assembly hall of the Ikshvaku lord.', 'veda-app-ai-draft', true),
('ramayana-2-75-9', 'en', 'The righteous one with his followers came to the lovely golden hall, full of gems and jewels, like Sudharma, the hall of the gods.', 'veda-app-ai-draft', true),
('ramayana-2-75-10', 'en', 'He, who knew all the Vedas, sat on a golden seat covered with a costly cloth and instructed the messengers.', 'veda-app-ai-draft', true),
('ramayana-2-75-11', 'en', 'Calmly and quickly bring the Brahmins, warriors, soldiers, ministers and leaders of groups, for we have urgent business.', 'veda-app-ai-draft', true),
('ramayana-2-75-12', 'en', 'Then a great tumult arose as people came by chariots, horses and elephants.', 'veda-app-ai-draft', true),
('ramayana-2-75-13', 'en', 'Then the people welcomed Bharata as he came, as the gods welcome Indra, just as they had welcomed Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-2-75-14', 'en', 'Like a lake full of great fish and serpents, with still water and gems, shells and sand, the hall graced by Dasharatha''s son shone as it did before with Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-2-76-1', 'en', 'Wise Bharata saw the assembly, full of nobles and well ordered, like a night with a full moon.', 'veda-app-ai-draft', true),
('ramayana-2-76-2', 'en', 'As the nobles took their seats in proper order, it looked like a night with a full moon after the clouds have gone.', 'veda-app-ai-draft', true),
('ramayana-2-76-3', 'en', 'Seeing all the king''s subjects assembled, the royal priest, who knew dharma, spoke gently to Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-76-4', 'en', 'Dear one, King Dasharatha has gone to heaven after living by dharma, having given you the prosperous earth rich in wealth and grain.', 'veda-app-ai-draft', true),
('ramayana-2-76-5', 'en', 'Rama too, firm in truth, remembering the dharma of the good, did not abandon his father''s command, as the rising moon does not give up its light.', 'veda-app-ai-draft', true),
('ramayana-2-76-6', 'en', 'The kingdom given to you by your father and brother is free of enemies. Enjoy it with your ministers glad, and have yourself consecrated quickly.', 'veda-app-ai-draft', true),
('ramayana-2-76-7', 'en', 'Let the kings of the north, west and south, and of the far frontier and the coasts, bring you jewels.', 'veda-app-ai-draft', true),
('ramayana-2-76-8', 'en', 'Hearing this, Bharata, flooded with grief, his mind went to Rama, knowing dharma and wishing to follow it.', 'veda-app-ai-draft', true),
('ramayana-2-76-9', 'en', 'The young man, with a voice like a swan''s but choked with tears, lamented in the middle of the assembly and rebuked the priest.', 'veda-app-ai-draft', true),
('ramayana-2-76-10', 'en', 'Who like me would take the kingdom of one who has lived the student''s life, completed his learning, is wise and strives in dharma?', 'veda-app-ai-draft', true),
('ramayana-2-76-11', 'en', 'How could one born of Dasharatha steal a kingdom? The kingdom and I both belong to Rama. You should speak of dharma here.', 'veda-app-ai-draft', true),
('ramayana-2-76-12', 'en', 'The eldest and best, righteous, like Dilipa and Nahusha, Kakutstha deserves to have the kingdom as Dasharatha did.', 'veda-app-ai-draft', true),
('ramayana-2-76-13', 'en', 'If I did this sinful thing, practised by the ignoble and not leading to heaven, I would be the disgrace of the Ikshvaku family in the world.', 'veda-app-ai-draft', true),
('ramayana-2-76-14', 'en', 'I do not approve of the sin my mother committed. Standing here, I bow with folded hands to him who lives in the hard forest.', 'veda-app-ai-draft', true),
('ramayana-2-76-15', 'en', 'I will follow Rama. He is the king, the best of men. Raghava deserves the kingdom of all three worlds.', 'veda-app-ai-draft', true),
('ramayana-2-76-16', 'en', 'Hearing those words full of dharma, all the members of the assembly, their hearts set on Rama, shed tears of joy.', 'veda-app-ai-draft', true),
('ramayana-2-76-17', 'en', 'If I cannot bring my noble brother back from the forest, I will live there in the forest, as noble Lakshmana does.', 'veda-app-ai-draft', true),
('ramayana-2-76-18', 'en', 'I will use every means to bring him back by force of persuasion, in the presence of the noble, the good and the virtuous.', 'veda-app-ai-draft', true),
('ramayana-2-76-19', 'en', 'Having said this, righteous Bharata, loving towards his brother, spoke to Sumantra, skilled in counsel, who stood near.', 'veda-app-ai-draft', true),
('ramayana-2-76-20', 'en', 'Rise quickly, Sumantra, and go at my command. Order the march at once and gather the army.', 'veda-app-ai-draft', true),
('ramayana-2-76-21', 'en', 'Told this by great-souled Bharata, Sumantra, delighted, ordered everything as instructed, as he wished.', 'veda-app-ai-draft', true),
('ramayana-2-76-22', 'en', 'The people and the army commanders were delighted to hear that the march to bring Raghava back had been ordered.', 'veda-app-ai-draft', true),
('ramayana-2-76-23', 'en', 'Then in every house the soldiers'' wives, hearing of the march, joyfully hurried their husbands.', 'veda-app-ai-draft', true),
('ramayana-2-76-24', 'en', 'The army commanders with the soldiers urged on the whole army, with horses, swift ox-carts and chariots fast as thought.', 'veda-app-ai-draft', true),
('ramayana-2-76-25', 'en', 'Seeing the army ready, Bharata, in the presence of his elders, said to Sumantra at his side, ''Hurry my chariot.''', 'veda-app-ai-draft', true),
('ramayana-2-76-26', 'en', 'Accepting Bharata''s command with delight, he took the chariot yoked with the finest horses and set out.', 'veda-app-ai-draft', true),
('ramayana-2-76-27', 'en', 'Then Bharata, of the Raghu line, steadfast in truth, powerful, firm and true in valour, intending to win the favour of his famous elder gone to the great forest, spoke.', 'veda-app-ai-draft', true),
('ramayana-2-76-28', 'en', 'Rise quickly, Sumantra, and go to the army chiefs to assemble the army. I wish to win over Rama in the forest and bring him back for the good of the world.', 'veda-app-ai-draft', true),
('ramayana-2-76-29', 'en', 'The charioteer''s son, properly commanded by Bharata and with his wish fulfilled, instructed all the leaders of the people, the army chiefs and the friends.', 'veda-app-ai-draft', true),
('ramayana-2-76-30', 'en', 'Then in every family, Kshatriyas, Vaishyas, Shudras and Brahmins rose and yoked camel-carts, mules, elephants and well-bred horses.', 'veda-app-ai-draft', true),
('ramayana-2-77-1', 'en', 'Then rising early and mounting the finest chariot, Bharata set out quickly, longing to see Rama.', 'veda-app-ai-draft', true),
('ramayana-2-77-2', 'en', 'Ahead of him went all the ministers and priests, riding chariots drawn by horses, like the sun''s chariot.', 'veda-app-ai-draft', true),
('ramayana-2-77-3', 'en', 'Nine thousand elephants, properly equipped, followed Bharata, the joy of the Ikshvaku family, as he went.', 'veda-app-ai-draft', true),
('ramayana-2-77-4', 'en', 'Sixty thousand chariots with archers bearing various weapons followed the famous prince Bharata as he went.', 'veda-app-ai-draft', true),
('ramayana-2-77-5', 'en', 'A hundred thousand horses with riders followed the famous prince Bharata, of the Raghu line, as he went.', 'veda-app-ai-draft', true),
('ramayana-2-77-6', 'en', 'Kaikeyi, Sumitra and famous Kausalya went in a shining carriage, delighted at the prospect of bringing Rama back.', 'veda-app-ai-draft', true),
('ramayana-2-77-7', 'en', 'Groups of nobles set out to see Rama with Lakshmana, telling delightful stories about him, their hearts glad.', 'veda-app-ai-draft', true),
('ramayana-2-77-8', 'en', 'When will we see Rama, dark as a rain cloud, mighty-armed, steady in nature, firm in his vows, who drives away the world''s sorrow?', 'veda-app-ai-draft', true),
('ramayana-2-77-9', 'en', 'As soon as he is seen, Raghava will take away our grief, as the rising sun dispels the darkness of the whole world.', 'veda-app-ai-draft', true),
('ramayana-2-77-10', 'en', 'Telling such happy, auspicious stories and embracing one another, the citizens went on.', 'veda-app-ai-draft', true),
('ramayana-2-77-11', 'en', 'All the other respected people there and the merchants, all the people, went joyfully towards Rama.', 'veda-app-ai-draft', true),
('ramayana-2-77-12', 'en', 'Some jewellers, fine potters, weavers and those who live by weapons...', 'veda-app-ai-draft', true),
('ramayana-2-77-13', 'en', '...makers of peacock-feather goods, sawyers, decorators, borers, ivory-workers, plasterers and perfumers...', 'veda-app-ai-draft', true),
('ramayana-2-77-14', 'en', '...famous goldsmiths, blanket-washers, bath attendants, physicians, incense-makers and brewers...', 'veda-app-ai-draft', true),
('ramayana-2-77-15', 'en', '...washermen, tailors, village and cowherd headmen, and actors with their women, and fishermen too went.', 'veda-app-ai-draft', true),
('ramayana-2-77-16', 'en', 'Thousands of composed, Veda-knowing Brahmins of respected conduct followed Bharata in ox-carts.', 'veda-app-ai-draft', true),
('ramayana-2-77-17', 'en', 'All of them, well dressed in clean clothes and anointed with copper-coloured paste, followed Bharata slowly in various vehicles.', 'veda-app-ai-draft', true),
('ramayana-2-77-18', 'en', 'The joyful, delighted army followed Kaikeyi''s son, and that army following Bharata halted.', 'veda-app-ai-draft', true),
('ramayana-2-77-19', 'en', 'Looking at the army following him and at the Ganga with its auspicious water, Bharata, skilled in speech, spoke to all his ministers.', 'veda-app-ai-draft', true),
('ramayana-2-77-20', 'en', 'Settle my army as you see fit. After resting, we will cross the great river tomorrow.', 'veda-app-ai-draft', true),
('ramayana-2-77-21', 'en', 'Meanwhile I wish to go down to the river and offer water for the welfare of the king who has gone to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-77-22', 'en', 'As he said this, the ministers attentively said ''So be it'' and settled the troops, each where they wished.', 'veda-app-ai-draft', true),
('ramayana-2-77-23', 'en', 'Having camped the army, splendid with its equipment, along the great Ganga, Bharata stayed there, thinking about how to bring back great-souled Rama.', 'veda-app-ai-draft', true),
('ramayana-2-78-1', 'en', 'Then the king of the Nishadas, seeing the army camped along the Ganga, quickly spoke to his kinsmen.', 'veda-app-ai-draft', true),
('ramayana-2-78-2', 'en', 'This army looks huge, like an ocean. Even thinking hard, I cannot see its end.', 'veda-app-ai-draft', true),
('ramayana-2-78-3', 'en', 'That great one with the kovidara banner on his chariot will either have us boatmen bound or kill us.', 'veda-app-ai-draft', true),
('ramayana-2-78-4', 'en', 'Or Bharata, Kaikeyi''s son, is coming to kill Rama, son of Dasharatha, exiled from the kingdom by his father.', 'veda-app-ai-draft', true),
('ramayana-2-78-5', 'en', 'Rama, son of Dasharatha, is my lord and my friend. For his sake stand ready here in armour on the banks of the Ganga.', 'veda-app-ai-draft', true),
('ramayana-2-78-6', 'en', 'Let all the boatmen stand along the Ganga, guarding the river with forces, living on meat, roots and fruit.', 'veda-app-ai-draft', true),
('ramayana-2-78-7', 'en', 'He ordered five hundred boats, each with a hundred young armed fishermen, to stand ready.', 'veda-app-ai-draft', true),
('ramayana-2-78-8', 'en', 'If Bharata is well disposed towards Rama here, this army will cross the Ganga safely today.', 'veda-app-ai-draft', true),
('ramayana-2-78-9', 'en', 'Saying this, Guha, lord of the Nishadas, took gifts of fish, meat and honey and approached Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-78-10', 'en', 'Seeing him coming, the mighty charioteer''s son, who knew courtesy, humbly told Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-78-11', 'en', 'This chief, surrounded by a thousand kinsmen, knows the Dandaka forest well; he is elderly and your brother''s friend.', 'veda-app-ai-draft', true),
('ramayana-2-78-12', 'en', 'So, Kakutstha, let Guha, lord of the Nishadas, see you. He certainly knows where Rama and Lakshmana are.', 'veda-app-ai-draft', true),
('ramayana-2-78-13', 'en', 'Hearing these good words from Sumantra, Bharata quickly said, ''Let Guha see me.''', 'veda-app-ai-draft', true),
('ramayana-2-78-14', 'en', 'Given permission, Guha, delighted and surrounded by kinsmen, came humbly to Bharata and spoke.', 'veda-app-ai-draft', true),
('ramayana-2-78-15', 'en', 'This land is your garden; you have caught us by surprise. We offer you everything; stay in your own boatmen''s house.', 'veda-app-ai-draft', true),
('ramayana-2-78-16', 'en', 'There are roots and fruit gathered by the Nishadas, fresh and dried meat, and a great variety of forest food.', 'veda-app-ai-draft', true),
('ramayana-2-78-17', 'en', 'I hope the army will stay this night well fed. Honoured with all you wish, you will go with your troops tomorrow.', 'veda-app-ai-draft', true),
('ramayana-2-79-1', 'en', 'Addressed thus, the very wise Bharata replied to Guha, lord of the Nishadas, with reasonable words.', 'veda-app-ai-draft', true),
('ramayana-2-79-2', 'en', 'Friend of my elder brother, your wish is generous indeed, that you alone want to honour such a large army.', 'veda-app-ai-draft', true),
('ramayana-2-79-3', 'en', 'Having said these excellent words to Guha, the splendid and glorious Bharata spoke again to the lord of the Nishadas.', 'veda-app-ai-draft', true),
('ramayana-2-79-4', 'en', 'Guha, by which way shall I go to Bharadvaja''s hermitage? This region along the Ganga is very dense and hard to cross.', 'veda-app-ai-draft', true),
('ramayana-2-79-5', 'en', 'Hearing the words of the wise prince, Guha, who roamed the deep forest, folded his hands and spoke.', 'veda-app-ai-draft', true),
('ramayana-2-79-6', 'en', 'The boatmen will go with you, armed and alert, and I will go with you too, famous prince.', 'veda-app-ai-draft', true),
('ramayana-2-79-7', 'en', 'I hope you are not going with ill intent toward Rama, tireless in deeds? This great army of yours makes me uneasy.', 'veda-app-ai-draft', true),
('ramayana-2-79-8', 'en', 'As he spoke thus, Bharata, clear as the sky, answered Guha with gentle words.', 'veda-app-ai-draft', true),
('ramayana-2-79-9', 'en', 'May such a terrible time never come! You should not suspect me. Raghava is my eldest brother, like a father to me.', 'veda-app-ai-draft', true),
('ramayana-2-79-10', 'en', 'I am going to bring back Kakutstha, who lives in the forest. Do not think otherwise, Guha; I am telling you the truth.', 'veda-app-ai-draft', true),
('ramayana-2-79-11', 'en', 'Hearing Bharata''s words, Guha, his face glowing with joy, spoke again to Bharata, delighted.', 'veda-app-ai-draft', true),
('ramayana-2-79-12', 'en', 'You are blessed. I see no one equal to you on earth, since you wish to give up a kingdom that came to you without effort.', 'veda-app-ai-draft', true),
('ramayana-2-79-13', 'en', 'Surely your fame will travel the worlds forever, since you want to bring back Rama, who is in difficulty.', 'veda-app-ai-draft', true),
('ramayana-2-79-14', 'en', 'As Guha was speaking to Bharata, the sun lost its light and night came on.', 'veda-app-ai-draft', true),
('ramayana-2-79-15', 'en', 'Having settled the army and been made welcome by Guha, glorious Bharata went to bed with Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-79-16', 'en', 'Grief full of thoughts of Rama came upon great-souled Bharata, who did not deserve it and always looked to dharma.', 'veda-app-ai-draft', true),
('ramayana-2-79-17', 'en', 'Burning within, it tormented Raghava, as a hidden fire torments a tree scorched by a forest blaze.', 'veda-app-ai-draft', true),
('ramayana-2-79-18', 'en', 'Sweat born of the fire of grief poured from all his limbs, as the Himalaya, heated by the sun''s rays, pours out its snow.', 'veda-app-ai-draft', true),
('ramayana-2-79-19', 'en', '...a mountain of sorrow whose caves were brooding, whose minerals were sighs, whose trees were misery, whose peaks were grief and exhaustion...', 'veda-app-ai-draft', true),
('ramayana-2-79-20', 'en', '...whose beasts were confusion, whose herbs and bamboo were torment: Kaikeyi''s son was overwhelmed by that great mountain of sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-79-21', 'en', 'Then Guha, deeply troubled, comforted great-hearted Bharata, who had come with his people, about his elder brother.', 'veda-app-ai-draft', true),
('ramayana-2-80-1', 'en', 'Then Guha, who roamed the deep forest, told immeasurable Bharata about the noble devotion of great-souled Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-80-2', 'en', 'To Lakshmana, who was awake, virtuous, holding a fine bow and arrows to guard his brother, I said:', 'veda-app-ai-draft', true),
('ramayana-2-80-3', 'en', '''Dear one, this comfortable bed has been prepared for you. Rest on it comfortably, joy of Raghava.''', 'veda-app-ai-draft', true),
('ramayana-2-80-4', 'en', '''All these people are used to hardship; you are used to comfort. Righteous one, we will keep watch to protect him.''', 'veda-app-ai-draft', true),
('ramayana-2-80-5', 'en', '''There is no one on earth dearer to me than Rama. Do not be anxious; I tell you this truly before you.''', 'veda-app-ai-draft', true),
('ramayana-2-80-6', 'en', '''Through his grace I hope for great fame in this world, abundant merit and true wealth.''', 'veda-app-ai-draft', true),
('ramayana-2-80-7', 'en', '''I will guard my dear friend Rama as he sleeps with Sita, bow in hand, together with all my kinsmen.''', 'veda-app-ai-draft', true),
('ramayana-2-80-8', 'en', '''There is nothing in this forest unknown to me, as I always roam here. We could withstand even a fourfold army in battle.''', 'veda-app-ai-draft', true),
('ramayana-2-80-9', 'en', 'When we said this, great-souled Lakshmana, looking only to dharma, answered all of us.', 'veda-app-ai-draft', true),
('ramayana-2-80-10', 'en', '''How, when Dasharatha''s son lies on the ground with Sita, can I take sleep, or care about life or comforts?''', 'veda-app-ai-draft', true),
('ramayana-2-80-11', 'en', '''Look, Guha, he whom all the gods and demons together cannot overcome in battle lies on grass with Sita.''', 'veda-app-ai-draft', true),
('ramayana-2-80-12', 'en', '''Won by great austerity and many efforts, he is Dasharatha''s only son with qualities like his own.''', 'veda-app-ai-draft', true),
('ramayana-2-80-13', 'en', '''With him exiled, the king will not live long. Surely the earth will soon be widowed.''', 'veda-app-ai-draft', true),
('ramayana-2-80-14', 'en', '''The women, having cried out loudly, must have fallen silent from exhaustion. Surely the palace is silent today.''', 'veda-app-ai-draft', true),
('ramayana-2-80-15', 'en', '''Kausalya, the king and my mother: I do not expect that all of them will live through this night.''', 'veda-app-ai-draft', true),
('ramayana-2-80-16', 'en', '''My mother may live, looking to Shatrughna, but grieving Kausalya, mother of a hero, will perish.''', 'veda-app-ai-draft', true),
('ramayana-2-80-17', 'en', '''Without fulfilling his wish, which keeps passing him by, without placing Rama on the throne, my father will perish.''', 'veda-app-ai-draft', true),
('ramayana-2-80-18', 'en', '''Fortunate are those who, when that time comes, will perform all the funeral rites for the dead king.''', 'veda-app-ai-draft', true),
('ramayana-2-80-19', 'en', '''...the capital with lovely squares, well-laid-out main roads, mansions and palaces, adorned with every jewel...''', 'veda-app-ai-draft', true),
('ramayana-2-80-20', 'en', '''...crowded with elephants, horses and chariots, ringing with music, full of every blessing, crowded with happy, well-fed people...''', 'veda-app-ai-draft', true),
('ramayana-2-80-21', 'en', '''...full of parks and gardens, splendid with gatherings and festivals: happy people will walk about my father''s capital.''', 'veda-app-ai-draft', true),
('ramayana-2-80-22', 'en', '''May we, with the one true to his promise, return well when this period is over and enter it happily.''', 'veda-app-ai-draft', true),
('ramayana-2-80-23', 'en', 'As the great-souled prince stood lamenting like this, that night passed.', 'veda-app-ai-draft', true),
('ramayana-2-80-24', 'en', 'At dawn, when the sun was clear, I had both of them, having matted their hair, ferried comfortably across on this bank of the Bhagirathi.', 'veda-app-ai-draft', true),
('ramayana-2-80-25', 'en', 'With matted hair and wearing bark clothes, mighty like leaders of elephant herds, carrying fine arrows, bows and swords, the scorchers of foes went, looking about them, with Sita.', 'veda-app-ai-draft', true),
('ramayana-2-81-1', 'en', 'Hearing Guha''s very painful words, Bharata fell into deep thought right there where he heard them.', 'veda-app-ai-draft', true),
('ramayana-2-81-2', 'en', 'Delicate, of great strength, lion-shouldered, mighty-armed, with large lotus eyes, young and handsome...', 'veda-app-ai-draft', true),
('ramayana-2-81-3', 'en', '...after recovering for a moment, deeply dejected, he suddenly fell like an elephant pierced in the heart by goads.', 'veda-app-ai-draft', true),
('ramayana-2-81-4', 'en', 'Seeing Bharata in that state, Shatrughna, standing beside him, embraced him and wept aloud, senseless and wasted with grief.', 'veda-app-ai-draft', true),
('ramayana-2-81-5', 'en', 'Then all of Bharata''s mothers rushed up, thin from fasting, miserable and wasted by grief for their husband.', 'veda-app-ai-draft', true),
('ramayana-2-81-6', 'en', 'Weeping, they surrounded him fallen on the ground, and Kausalya, sick at heart, went to him and embraced him.', 'veda-app-ai-draft', true),
('ramayana-2-81-7', 'en', 'As a loving cow embraces her calf, the ascetic queen, weeping and full of grief, embraced Bharata and questioned him.', 'veda-app-ai-draft', true),
('ramayana-2-81-8', 'en', 'Son, I hope no illness afflicts your body? Today the life of this royal family depends on you.', 'veda-app-ai-draft', true),
('ramayana-2-81-9', 'en', 'Son, seeing you, I live. With Rama gone with his brother and King Dasharatha dead, you alone are our protector now.', 'veda-app-ai-draft', true),
('ramayana-2-81-10', 'en', 'Son, I hope you have not heard anything bad about Lakshmana, or about my only son, gone to the forest with his wife?', 'veda-app-ai-draft', true),
('ramayana-2-81-11', 'en', 'Recovering for a moment, the famous one, still weeping, comforted Kausalya and said this to Guha.', 'veda-app-ai-draft', true),
('ramayana-2-81-12', 'en', 'Guha, tell me where my brother spent the night, where Sita and Lakshmana were, what bed he slept on and what he ate.', 'veda-app-ai-draft', true),
('ramayana-2-81-13', 'en', 'Asked thus, Guha, lord of the Nishadas, told Bharata how he had treated Rama, his dear and welcome guest.', 'veda-app-ai-draft', true),
('ramayana-2-81-14', 'en', 'I brought much food of every kind, delicacies and various fruits for Rama to eat.', 'veda-app-ai-draft', true),
('ramayana-2-81-15', 'en', 'Rama, true in valour, declined it all; remembering the duty of a Kshatriya, he did not accept it.', 'veda-app-ai-draft', true),
('ramayana-2-81-16', 'en', '''Friend, we must not accept; we must always give.'' So, king, that great soul persuaded us.', 'veda-app-ai-draft', true),
('ramayana-2-81-17', 'en', 'The famous Raghava, with Sita, drank only the water Lakshmana brought and so kept a fast.', 'veda-app-ai-draft', true),
('ramayana-2-81-18', 'en', 'Then Lakshmana too drank the remaining water. The three, silent and composed, performed the evening prayer.', 'veda-app-ai-draft', true),
('ramayana-2-81-19', 'en', 'Then Sumitra''s son quickly made a fine bed, bringing kusha grass himself for Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-81-20', 'en', 'Rama lay on that bed with Sita, and Lakshmana, having washed their feet, stepped away.', 'veda-app-ai-draft', true),
('ramayana-2-81-21', 'en', 'This is the root of the ingudi tree, and this is the grass on which Rama and Sita both slept that night.', 'veda-app-ai-draft', true),
('ramayana-2-81-22', 'en', 'Fastening on his back two quivers full of arrows, with finger guards, and holding his great strung bow, Lakshmana, scorcher of foes, stood all night around him.', 'veda-app-ai-draft', true),
('ramayana-2-81-23', 'en', 'Then I too, holding a fine bow and arrows, stood where Lakshmana was, guarding the Indra-like one with my tireless kinsmen, bows in hand.', 'veda-app-ai-draft', true),
('ramayana-2-82-1', 'en', 'Hearing all this carefully with his ministers, Bharata went to the root of the ingudi tree and looked at Rama''s bed.', 'veda-app-ai-draft', true),
('ramayana-2-82-2', 'en', 'He said to all his mothers: ''Here the great soul slept the night on the ground; this is where it is pressed down.''', 'veda-app-ai-draft', true),
('ramayana-2-82-3', 'en', 'Rama, born on earth to wise and fortunate Dasharatha of a noble family, should not have to sleep like this.', 'veda-app-ai-draft', true),
('ramayana-2-82-4', 'en', 'Having slept on heaps of fine coverings spread with deerskin, how does the tiger among men lie on the ground?', 'veda-app-ai-draft', true),
('ramayana-2-82-5', 'en', '...always in rooftop chambers of palaces and in turrets, on floors of gold and silver, with fine coverings...', 'veda-app-ai-draft', true),
('ramayana-2-82-6', 'en', '...bright with heaps of flowers, fragrant with sandal and aloe, shining like white clouds, ringing with the calls of parrots...', 'veda-app-ai-draft', true),
('ramayana-2-82-7', 'en', '...always woken by the sound of songs and music, the jingling of fine ornaments and the sound of fine drums...', 'veda-app-ai-draft', true),
('ramayana-2-82-8', 'en', '...praised at the right time by many bards and heralds with fitting songs and hymns, that scorcher of foes...', 'veda-app-ai-draft', true),
('ramayana-2-82-9', 'en', 'This is unbelievable in the world; it does not seem true to me. My mind is confused; I think this is a dream.', 'veda-app-ai-draft', true),
('ramayana-2-82-10', 'en', 'Surely no deity is stronger than Time, if Rama, son of Dasharatha, must sleep on the ground like this.', 'veda-app-ai-draft', true),
('ramayana-2-82-11', 'en', 'And Sita, the lovely daughter of the king of Videha, the beloved daughter-in-law of Dasharatha, slept on the ground.', 'veda-app-ai-draft', true),
('ramayana-2-82-12', 'en', 'This is my brother''s bed; here he turned over. All the grass on the hard ground has been crushed by his limbs.', 'veda-app-ai-draft', true),
('ramayana-2-82-13', 'en', 'I think Sita slept on this bed with her ornaments on, for specks of gold are seen stuck here and there.', 'veda-app-ai-draft', true),
('ramayana-2-82-14', 'en', 'Sita''s upper garment was clearly caught here, for these silk threads can be seen stuck there.', 'veda-app-ai-draft', true),
('ramayana-2-82-15', 'en', 'I think the young ascetic finds her husband''s bed comfortable, since the delicate, faithful Maithili does not feel hardship.', 'veda-app-ai-draft', true),
('ramayana-2-82-16', 'en', 'Born in a family of world rulers, bringing happiness to all, dear to all, having given up the dear and matchless kingdom...', 'veda-app-ai-draft', true),
('ramayana-2-82-17', 'en', '...how can Raghava, dark as a blue lotus, red-eyed and handsome, who deserves happiness and not sorrow, lie on the ground?', 'veda-app-ai-draft', true),
('ramayana-2-82-18', 'en', 'Vaidehi is fortunate indeed, having followed her husband to the forest. All of us, deprived of that great soul, are in doubt.', 'veda-app-ai-draft', true),
('ramayana-2-82-19', 'en', 'With Dasharatha gone to heaven and Rama in the forest, the earth seems to me empty, like a ship without a helmsman.', 'veda-app-ai-draft', true),
('ramayana-2-82-20', 'en', 'Yet no one even in thought covets the earth, protected by the strength of his arms even while he lives in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-82-21', 'en', '...the capital unguarded, its walls unmanned, its horses and elephants untethered, its city gates open, unprotected...', 'veda-app-ai-draft', true),
('ramayana-2-82-22', 'en', '...its army dispirited, weakened, in distress and exposed, enemies do not desire it, as one avoids poisoned food.', 'veda-app-ai-draft', true),
('ramayana-2-82-23', 'en', 'From today I will sleep on the ground or on grass, always eating fruit and roots and wearing matted hair and bark clothes.', 'veda-app-ai-draft', true),
('ramayana-2-82-24', 'en', 'For his sake I will live happily in the forest for the remaining time. Thus releasing him from his promise, it will not become false.', 'veda-app-ai-draft', true),
('ramayana-2-82-25', 'en', 'Shatrughna will live with me for my brother''s sake, and the noble one with Lakshmana will rule Ayodhya.', 'veda-app-ai-draft', true),
('ramayana-2-82-26', 'en', 'The Brahmins will consecrate Kakutstha in Ayodhya. May the gods make this wish of mine come true.', 'veda-app-ai-draft', true),
('ramayana-2-82-27', 'en', 'If he will not agree, though I beg him myself in many ways with my head bowed, then I will follow Raghava and live in the forest for a long time. He should not ignore me.', 'veda-app-ai-draft', true),
('ramayana-2-83-1', 'en', 'Having spent the night right there on the bank of the Ganga, Bharata, of the Raghu line, rose early and said this to Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-83-2', 'en', 'Shatrughna, get up, why are you lying there? Quickly bring Guha, lord of the Nishadas. Bless you, he will take the army across.', 'veda-app-ai-draft', true),
('ramayana-2-83-3', 'en', '''I am awake, I am not asleep, thinking of our noble brother,'' said Shatrughna when urged by his brother.', 'veda-app-ai-draft', true),
('ramayana-2-83-4', 'en', 'As the two lions among men were talking together, Guha came at the right time with folded hands and spoke to Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-83-5', 'en', 'Did you spend the night comfortably on the riverbank, Kakutstha? Is everything well with you and your army?', 'veda-app-ai-draft', true),
('ramayana-2-83-6', 'en', 'Hearing Guha''s words spoken with affection, Bharata, devoted to Rama, replied.', 'veda-app-ai-draft', true),
('ramayana-2-83-7', 'en', 'King, our night was pleasant and we have been honoured by you. Let the boatmen take us across the Ganga in many boats.', 'veda-app-ai-draft', true),
('ramayana-2-83-8', 'en', 'Hearing Bharata''s command, Guha quickly went back into the town and said to his kinsmen:', 'veda-app-ai-draft', true),
('ramayana-2-83-9', 'en', 'Get up, wake up, good fortune be with you always. Drag the boats out; we will take the army across.', 'veda-app-ai-draft', true),
('ramayana-2-83-10', 'en', 'Told this, they got up quickly at the king''s command and brought five hundred boats from all around.', 'veda-app-ai-draft', true),
('ramayana-2-83-11', 'en', 'Other fine boats, marked with the svastika, with great bells, decorated with banners, fitted with sails and sturdily built...', 'veda-app-ai-draft', true),
('ramayana-2-83-12', 'en', 'Then Guha brought a fine auspicious boat marked with the svastika, covered with pale blankets, with joyful music sounding.', 'veda-app-ai-draft', true),
('ramayana-2-83-13', 'en', 'Bharata boarded it, with mighty Shatrughna, Kausalya, Sumitra and the other royal women.', 'veda-app-ai-draft', true),
('ramayana-2-83-14', 'en', 'Before that went the royal priest, the elders and the Brahmins, then the royal wives, and also the carts and goods.', 'veda-app-ai-draft', true),
('ramayana-2-83-15', 'en', 'The noise of those burning the camp, plunging into the ford and picking up their goods reached the heavens.', 'veda-app-ai-draft', true),
('ramayana-2-83-16', 'en', 'Those bannered boats, steered by the boatmen themselves, carrying the people on board, sped swiftly across.', 'veda-app-ai-draft', true),
('ramayana-2-83-17', 'en', 'Some were full of women, some of horses, and some carried carriages, draught animals and great wealth.', 'veda-app-ai-draft', true),
('ramayana-2-83-18', 'en', 'Having gone to the far shore and set down the people, the boats returned, the boatmen making them perform playful manoeuvres.', 'veda-app-ai-draft', true),
('ramayana-2-83-19', 'en', 'Elephants with pennants, urged on by their riders, swimming across, looked like mountains with flags.', 'veda-app-ai-draft', true),
('ramayana-2-83-20', 'en', 'Some boarded boats, others crossed on rafts, others with pots and jars, and others swam with their arms.', 'veda-app-ai-draft', true),
('ramayana-2-83-21', 'en', 'That holy army, ferried across the Ganga by the boatmen themselves, went at the auspicious hour called Maitra to the fine forest of Prayaga.', 'veda-app-ai-draft', true),
('ramayana-2-83-22', 'en', 'Having rested the army and camped it comfortably, great-souled Bharata set out, surrounded by priests, to see Bharadvaja, best of sages.', 'veda-app-ai-draft', true),
('ramayana-2-84-1', 'en', 'Seeing Bharadvaja''s hermitage from a krosha away, the bull among men halted the whole army and went on with his ministers.', 'veda-app-ai-draft', true),
('ramayana-2-84-2', 'en', 'Knowing dharma, he went on foot, laying aside his weapons and royal trappings, wearing two linen garments, with the royal priest in front.', 'veda-app-ai-draft', true),
('ramayana-2-84-3', 'en', 'Then, within sight of Bharadvaja, Raghava stopped the ministers and followed behind the priest.', 'veda-app-ai-draft', true),
('ramayana-2-84-4', 'en', 'As soon as he saw Vasishtha, the great ascetic Bharadvaja rose quickly from his seat, telling his disciples, ''Bring water for guests.''', 'veda-app-ai-draft', true),
('ramayana-2-84-5', 'en', 'Meeting Vasishtha and greeted by Bharata, the radiant sage recognised him as Dasharatha''s son.', 'veda-app-ai-draft', true),
('ramayana-2-84-6', 'en', 'After giving the two of them water for guests and for their feet, and then fruits, the sage who knew dharma asked in proper order about the family''s welfare.', 'veda-app-ai-draft', true),
('ramayana-2-84-7', 'en', 'He asked about Ayodhya, the army, the treasury, friends and ministers; knowing Dasharatha was dead, he did not mention the king.', 'veda-app-ai-draft', true),
('ramayana-2-84-8', 'en', 'Vasishtha and Bharata asked after his health, his fires, trees, disciples, beasts and birds.', 'veda-app-ai-draft', true),
('ramayana-2-84-9', 'en', 'Saying ''All is well'', the great ascetic Bharadvaja spoke to Bharata, bound by affection for Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-84-10', 'en', 'What brings you here while you rule the kingdom? Tell me everything, for my mind is not at ease.', 'veda-app-ai-draft', true),
('ramayana-2-84-11', 'en', '...the slayer of enemies whom Kausalya bore, who increases her joy, who has been banished to the forest for a long time with his brother and wife...', 'veda-app-ai-draft', true),
('ramayana-2-84-12', 'en', '...that famous one, ordered by his father, who was himself directed by a woman, to live in the forest here for fourteen years...', 'veda-app-ai-draft', true),
('ramayana-2-84-13', 'en', 'I hope you do not wish to harm that innocent one, wanting to enjoy the kingdom without rivals, along with his younger brother?', 'veda-app-ai-draft', true),
('ramayana-2-84-14', 'en', 'Addressed thus, Bharata replied to Bharadvaja, his eyes full of tears from sorrow, his voice faltering.', 'veda-app-ai-draft', true),
('ramayana-2-84-15', 'en', 'I am ruined if even your holiness thinks of me like this. Do not suspect any fault from me; do not speak to me like this.', 'veda-app-ai-draft', true),
('ramayana-2-84-16', 'en', 'What my mother said in my absence was not my wish. I am not pleased by it, nor do I accept those words.', 'veda-app-ai-draft', true),
('ramayana-2-84-17', 'en', 'I have come to that tiger among men to seek his favour, to bring him back to Ayodhya and to bow at his feet.', 'veda-app-ai-draft', true),
('ramayana-2-84-18', 'en', 'Seeing me in this state, please be gracious. Tell me, holy one, where is Rama, lord of the earth, now?', 'veda-app-ai-draft', true),
('ramayana-2-84-19', 'en', 'Bharadvaja, gracious, said to Bharata: ''Tiger among men, born in the Raghu line, this befits you: respect for elders, self-control and following the good.''', 'veda-app-ai-draft', true),
('ramayana-2-84-20', 'en', 'I know what is in your mind. I asked only to make it firm and to increase your fame greatly.', 'veda-app-ai-draft', true),
('ramayana-2-84-21', 'en', 'Your brother lives on the great mountain Chitrakuta. You will go there tomorrow. Stay here today with your ministers; grant me this wish, wise one who knows what is fitting.', 'veda-app-ai-draft', true),
('ramayana-2-84-22', 'en', 'Then noble-looking Bharata, trusting, said ''So be it'', and the prince decided to spend the night at the great hermitage.', 'veda-app-ai-draft', true),
('ramayana-2-85-1', 'en', 'When he had decided to stay, the sage invited Bharata, Kaikeyi''s son, to receive his hospitality.', 'veda-app-ai-draft', true),
('ramayana-2-85-2', 'en', 'But Bharata said to him, ''Surely you have already done this: water for the feet, welcome water and hospitality such as the forest allows.''', 'veda-app-ai-draft', true),
('ramayana-2-85-3', 'en', 'Then Bharadvaja said to Bharata, almost smiling: ''I know you are full of goodwill and would be content with anything.''', 'veda-app-ai-draft', true),
('ramayana-2-85-4', 'en', 'But I wish to feed this army of yours. You deserve that I show my affection fittingly, bull among men.', 'veda-app-ai-draft', true),
('ramayana-2-85-5', 'en', 'Why did you leave the army far away and come here? Why did you not come with your army, bull among men?', 'veda-app-ai-draft', true),
('ramayana-2-85-6', 'en', 'Bharata, with folded hands, replied to the sage rich in austerity: ''Holy one, I did not come with my army out of respect for you.''', 'veda-app-ai-draft', true),
('ramayana-2-85-7', 'en', 'Holy one, the finest horses, men and great rutting elephants follow me, covering a vast area.', 'veda-app-ai-draft', true),
('ramayana-2-85-8', 'en', 'So that they would not harm the trees, water, land and huts in the hermitages, I came here alone.', 'veda-app-ai-draft', true),
('ramayana-2-85-9', 'en', 'Ordered by the great sage, ''Let the army be brought here'', Bharata had the army come.', 'veda-app-ai-draft', true),
('ramayana-2-85-10', 'en', 'Then, entering the fire-hall, sipping water and wiping his lips, he called on Vishvakarman to provide hospitality.', 'veda-app-ai-draft', true),
('ramayana-2-85-11', 'en', 'I call on Vishvakarman and on Tvashtri. I wish to give hospitality; let it be arranged for me.', 'veda-app-ai-draft', true),
('ramayana-2-85-12', 'en', 'Let all the rivers that flow east and west, on earth and in the sky, come here today from everywhere.', 'veda-app-ai-draft', true),
('ramayana-2-85-13', 'en', 'Let some flow with maireya, others with well-made sura, and others with cool water like sugarcane juice.', 'veda-app-ai-draft', true),
('ramayana-2-85-14', 'en', 'I call the gods and gandharvas, Vishvavasu, Haha and Huhu, and likewise the apsaras goddesses and all the gandharva women.', 'veda-app-ai-draft', true),
('ramayana-2-85-15', 'en', 'Ghritachi, Vishvachi, Mishrakeshi, Alambusa, the beauties who wait on Indra and on Brahma, all of them I call with Tumburu and their attendants.', 'veda-app-ai-draft', true),
('ramayana-2-85-16', 'en', 'Let Kubera''s divine forest among the Kurus, with leaves that are clothes and ornaments and fruit that are divine women, be here.', 'veda-app-ai-draft', true),
('ramayana-2-85-17', 'en', 'Here let holy Soma provide the finest food, many kinds to chew, eat, suck and lick.', 'veda-app-ai-draft', true),
('ramayana-2-85-18', 'en', '...and many kinds of garlands fallen from trees, drinks such as wine, and various meats.', 'veda-app-ai-draft', true),
('ramayana-2-85-19', 'en', 'So the sage spoke, absorbed in meditation, with matchless spiritual power, with correct pronunciation and tone, through his austerity.', 'veda-app-ai-draft', true),
('ramayana-2-85-20', 'en', 'As he meditated facing east with folded hands, all those deities came, one by one.', 'veda-app-ai-draft', true),
('ramayana-2-85-21', 'en', 'A pleasant, kind and auspicious breeze, touching the Malaya and Dardura mountains, blew gently, taking away sweat.', 'veda-app-ai-draft', true),
('ramayana-2-85-22', 'en', 'Then clouds came pouring down divine flowers, and the sound of divine drums was heard in all directions.', 'veda-app-ai-draft', true),
('ramayana-2-85-23', 'en', 'Fine winds blew, troops of apsaras danced, the gods and gandharvas sang, and vinas poured out their notes.', 'veda-app-ai-draft', true),
('ramayana-2-85-24', 'en', 'That sound, smooth, even and full of rhythm, entered heaven and earth and the ears of all beings.', 'veda-app-ai-draft', true),
('ramayana-2-85-25', 'en', 'When that divine sound, pleasing to people''s ears, ceased, Bharata''s army saw what Vishvakarman had arranged.', 'veda-app-ai-draft', true),
('ramayana-2-85-26', 'en', 'The ground became level for five yojanas all around, covered with much grass like blue beryl.', 'veda-app-ai-draft', true),
('ramayana-2-85-27', 'en', 'There were bilva, wood-apple, jackfruit, citron, amalaka and mango trees, adorned with fruit.', 'veda-app-ai-draft', true),
('ramayana-2-85-28', 'en', 'A forest with divine delights came from Uttarakuru, and a divine river lined with many trees on its banks.', 'veda-app-ai-draft', true),
('ramayana-2-85-29', 'en', 'There were bright four-sided halls, stables for elephants and horses, clusters of mansions and palaces, and fine gateways.', 'veda-app-ai-draft', true),
('ramayana-2-85-30', 'en', 'And a royal palace like a white cloud with a fine gateway, decorated with white garlands and sprinkled with divine fragrance...', 'veda-app-ai-draft', true),
('ramayana-2-85-31', 'en', '...square, spacious, with beds, seats and carriages, with every divine taste, and divine food and clothing...', 'veda-app-ai-draft', true),
('ramayana-2-85-32', 'en', '...with all kinds of food prepared, clean washed dishes, all seats arranged, splendid, with fine well-spread beds.', 'veda-app-ai-draft', true),
('ramayana-2-85-33', 'en', 'With the great sage''s permission, mighty-armed Bharata, Kaikeyi''s son, entered that palace full of jewels.', 'veda-app-ai-draft', true),
('ramayana-2-85-34', 'en', 'All the ministers and the priest followed him, and they were filled with joy at seeing the palace''s arrangements.', 'veda-app-ai-draft', true),
('ramayana-2-85-35', 'en', 'There was a divine royal throne, a fan and a parasol. Bharata, with his ministers, walked around them as one would around a king.', 'veda-app-ai-draft', true),
('ramayana-2-85-36', 'en', 'Bowing to the throne as if to Rama, he honoured it, then took the yak-tail fan and sat on a minister''s seat.', 'veda-app-ai-draft', true),
('ramayana-2-85-37', 'en', 'All the ministers and priests sat down in order, and after them the army commander and the camp marshal.', 'veda-app-ai-draft', true),
('ramayana-2-85-38', 'en', 'Then within a moment, at Bharadvaja''s command, rivers thick with rice pudding came up to Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-85-39', 'en', 'On both banks there were lovely divine dwellings plastered with white clay, created by Brahma''s grace.', 'veda-app-ai-draft', true),
('ramayana-2-85-40', 'en', 'At that same moment twenty thousand women adorned with divine ornaments arrived, sent by Brahma.', 'veda-app-ai-draft', true),
('ramayana-2-85-41', 'en', 'Twenty thousand women sent by Kubera came, shining with gold, gems, pearls and coral.', 'veda-app-ai-draft', true),
('ramayana-2-85-42', 'en', 'Twenty thousand troops of apsaras came from Nandana, at whose touch a man seems almost intoxicated.', 'veda-app-ai-draft', true),
('ramayana-2-85-43', 'en', 'Narada, Tumburu, Gopa and Parvata, bright as the sun, these kings of the gandharvas sang before Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-85-44', 'en', 'Alambusa, Mishrakeshi, Pundarika and Vamana danced before Bharata at Bharadvaja''s command.', 'veda-app-ai-draft', true),
('ramayana-2-85-45', 'en', 'The garlands found among the gods and in the Chaitraratha forest appeared at Prayaga by Bharadvaja''s command.', 'veda-app-ai-draft', true),
('ramayana-2-85-46', 'en', 'By Bharadvaja''s power, bilva trees became drummers, shamya and bibhitaka trees became cymbal players, and ashvattha trees became dancers.', 'veda-app-ai-draft', true),
('ramayana-2-85-47', 'en', 'Then sarala, tala, tilaka and naktamala trees, delighted, came there, changed into hunchbacks and dwarfs.', 'veda-app-ai-draft', true),
('ramayana-2-85-48', 'en', 'Shimshapa, amalaki, jambu and the other creepers of the forest took the form of women and stayed in Bharadvaja''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-2-85-49', 'en', '''Drink wine, you who drink wine; eat rice pudding, you who are hungry; eat the choicest meats as much as you like.''', 'veda-app-ai-draft', true),
('ramayana-2-85-50', 'en', 'On the lovely riverbanks, seven or eight women together would rub and bathe each man.', 'veda-app-ai-draft', true),
('ramayana-2-85-51', 'en', 'Women with lovely eyes came to massage them, and the fine ladies, wiping one another, served them drinks.', 'veda-app-ai-draft', true),
('ramayana-2-85-52', 'en', 'The mighty attendants fed the horses, elephants, mules, camels and oxen, the mounts of the Ikshvaku warriors, with sugarcane and honey.', 'veda-app-ai-draft', true),
('ramayana-2-85-53', 'en', 'The horse-keeper did not recognise his horse, nor the elephant-keeper his elephant; the army there seemed drunk, carefree and happy.', 'veda-app-ai-draft', true),
('ramayana-2-85-54', 'en', 'Satisfied with every desire, smeared with red sandal, joined by troops of apsaras, the soldiers spoke out:', 'veda-app-ai-draft', true),
('ramayana-2-85-55', 'en', '''We will not go to Ayodhya, nor will we go to the Dandaka forest. May Bharata be well, and may Rama be happy.''', 'veda-app-ai-draft', true),
('ramayana-2-85-56', 'en', 'So the foot soldiers and the elephant and horse riders and keepers, without masters there, said these words on receiving such treatment.', 'veda-app-ai-draft', true),
('ramayana-2-85-57', 'en', 'Thousands of Bharata''s followers shouted for joy there and said, ''This is heaven!''', 'veda-app-ai-draft', true),
('ramayana-2-85-58', 'en', 'Then, though they had eaten that nectar-like food, when they saw the divine delicacies they wanted to eat again.', 'veda-app-ai-draft', true),
('ramayana-2-85-59', 'en', 'The servants, maids, young wives and all those in the army were completely satisfied, and all wore new clothes.', 'veda-app-ai-draft', true),
('ramayana-2-85-60', 'en', 'Elephants, mules, camels, cattle, horses, beasts and birds were well fed there; no one had to provide for another.', 'veda-app-ai-draft', true),
('ramayana-2-85-61', 'en', 'No one there was seen in unwashed clothes, hungry or dirty, or with hair covered in dust.', 'veda-app-ai-draft', true),
('ramayana-2-85-62', 'en', '...with goat and boar meat, heaps of fine sauces, soups made with fruit juices, full of fragrance and flavour...', 'veda-app-ai-draft', true),
('ramayana-2-85-63', 'en', 'The amazed people saw thousands of iron vessels full of white rice, decorated with flower flags, all around.', 'veda-app-ai-draft', true),
('ramayana-2-85-64', 'en', 'At the forest''s edge there were wells thick with rice pudding, wish-granting cows, and trees dripping with honey.', 'veda-app-ai-draft', true),
('ramayana-2-85-65', 'en', 'There were pools full of maireya, surrounded by heaps of fine meat, and by hot pots of venison, peacock and fowl.', 'veda-app-ai-draft', true),
('ramayana-2-85-66', 'en', 'There were thousands of golden plates, and pans, pots and bowls full of well-prepared curd, fragrant with young yellow wood-apple.', 'veda-app-ai-draft', true),
('ramayana-2-85-67', 'en', 'There were lakes full of spiced curd drink and of white curd, and at the edge of the rice pudding, heaps of sugar.', 'veda-app-ai-draft', true),
('ramayana-2-85-68', 'en', 'At the bathing places of the rivers the people saw pastes, powders, astringents and all kinds of bathing items in vessels.', 'veda-app-ai-draft', true),
('ramayana-2-85-69', 'en', '...heaps of white, bristled tooth-sticks and white sandal paste kept in boxes...', 'veda-app-ai-draft', true),
('ramayana-2-85-70', 'en', '...polished mirrors, piles of clothes, and thousands of pairs of sandals and shoes...', 'veda-app-ai-draft', true),
('ramayana-2-85-71', 'en', '...collyrium boxes, combs, brushes, parasols, bows, colourful armour, beds and seats...', 'veda-app-ai-draft', true),
('ramayana-2-85-72', 'en', '...full drinking ponds for mules, camels, elephants and horses, and lakes with good fords and lotuses to bathe in...', 'veda-app-ai-draft', true),
('ramayana-2-85-73', 'en', '...and they saw everywhere heaps of soft fodder, coloured like blue beryl, to feed the animals.', 'veda-app-ai-draft', true),
('ramayana-2-85-74', 'en', 'The people were amazed at that wonder, like a dream, seeing such hospitality given to Bharata by the great sage.', 'veda-app-ai-draft', true),
('ramayana-2-85-75', 'en', 'While they enjoyed themselves like gods in the Nandana garden, that night passed in Bharadvaja''s lovely hermitage.', 'veda-app-ai-draft', true),
('ramayana-2-85-76', 'en', 'Then the rivers, the gandharvas and all those lovely women took leave of Bharadvaja and returned as they had come.', 'veda-app-ai-draft', true),
('ramayana-2-85-77', 'en', 'Yet the men were still intoxicated, still sprinkled with divine aloe and sandal, and the many fine divine garlands lay scattered, crushed by the people.', 'veda-app-ai-draft', true),
('ramayana-2-86-1', 'en', 'Having spent that night there and enjoyed hospitality, Bharata with his retinue willingly went to Bharadvaja.', 'veda-app-ai-draft', true),
('ramayana-2-86-2', 'en', 'The sage Bharadvaja, having made his fire offering, saw the tiger among men approach with folded hands and spoke to Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-86-3', 'en', 'Did you pass a pleasant night here in our land? Were all your people satisfied with the hospitality? Tell me, sinless one.', 'veda-app-ai-draft', true),
('ramayana-2-86-4', 'en', 'Bharata folded his hands, bowed and spoke to the sage of supreme splendour, who had come out of the hermitage.', 'veda-app-ai-draft', true),
('ramayana-2-86-5', 'en', 'Holy one, I have stayed happily with my whole army and mounts, and with my ministers I have been fully satisfied in every wish by you.', 'veda-app-ai-draft', true),
('ramayana-2-86-6', 'en', 'All of us, even the servants, stayed very happily, free of fatigue and distress, well fed and well housed.', 'veda-app-ai-draft', true),
('ramayana-2-86-7', 'en', 'Holy one, best of sages, I take leave of you. Look kindly on me as I set out to my brother.', 'veda-app-ai-draft', true),
('ramayana-2-86-8', 'en', 'Knower of dharma, tell me where the hermitage of that righteous great soul is, which road leads there and how far it is.', 'veda-app-ai-draft', true),
('ramayana-2-86-9', 'en', 'Asked thus by Bharata, who longed to see his brother, the radiant great ascetic Bharadvaja replied.', 'veda-app-ai-draft', true),
('ramayana-2-86-10', 'en', 'Bharata, two and a half yojanas away, in an uninhabited forest, is the mountain Chitrakuta, with lovely caves and woods.', 'veda-app-ai-draft', true),
('ramayana-2-86-11', 'en', 'On its northern side is the river Mandakini, covered with flowering trees, with lovely blossoming woods.', 'veda-app-ai-draft', true),
('ramayana-2-86-12', 'en', 'Beyond that river is Mount Chitrakuta. There, dear one, is a leaf hut where the two surely live.', 'veda-app-ai-draft', true),
('ramayana-2-86-13', 'en', 'Lead your army, full of elephants, horses and chariots, by the southern road, keeping to the left and right, commander, and you will see Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-86-14', 'en', 'Hearing of the departure, the wives of the king of kings left their carriages, though worthy of them, and surrounded the Brahmin.', 'veda-app-ai-draft', true),
('ramayana-2-86-15', 'en', 'Trembling, thin and miserable, Kausalya, with queen Sumitra, clasped the sage''s feet with her hands.', 'veda-app-ai-draft', true),
('ramayana-2-86-16', 'en', 'Kaikeyi, condemned by the whole world because her wish had not been fulfilled, clasped his feet in shame.', 'veda-app-ai-draft', true),
('ramayana-2-86-17', 'en', 'Having walked around the holy great sage, she stood not far from Bharata, sad at heart.', 'veda-app-ai-draft', true),
('ramayana-2-86-18', 'en', 'Then Bharadvaja, firm in his vows, asked Bharata: ''Raghava, I wish to know about each of your mothers.''', 'veda-app-ai-draft', true),
('ramayana-2-86-19', 'en', 'Asked thus by Bharadvaja, righteous Bharata, skilled in speech, folded his hands and spoke.', 'veda-app-ai-draft', true),
('ramayana-2-86-20', 'en', 'Holy one, this miserable queen you see, wasted by grief and fasting, the chief queen of my father, like a goddess...', 'veda-app-ai-draft', true),
('ramayana-2-86-21', 'en', '...this is Kausalya, who bore Rama, the tiger among men who walks with a lion''s gait, as Aditi bore Dhatri.', 'veda-app-ai-draft', true),
('ramayana-2-86-22', 'en', 'She who stands clinging to her left arm, sad at heart, like a karnikara branch in the forest with its flowers fallen...', 'veda-app-ai-draft', true),
('ramayana-2-86-23', 'en', '...her two sons are the godlike princes, the heroes Lakshmana and Shatrughna, true in valour.', 'veda-app-ai-draft', true),
('ramayana-2-86-24', 'en', '...and she because of whom the two tigers among men have gone from here as if to death, and King Dasharatha, deprived of his son, has gone to heaven...', 'veda-app-ai-draft', true),
('ramayana-2-86-25', 'en', '...know her as my mother, Kaikeyi, hungry for power, ignoble though she looks noble, cruel and set on evil, in whom I see the root of my great misfortune.', 'veda-app-ai-draft', true),
('ramayana-2-86-26', 'en', 'Having said this in a voice choked with tears, the tiger among men, red-eyed, sighed again and again like an angry snake.', 'veda-app-ai-draft', true),
('ramayana-2-86-27', 'en', 'Then the great sage Bharadvaja, of great wisdom, replied to Bharata with these meaningful words.', 'veda-app-ai-draft', true),
('ramayana-2-86-28', 'en', 'Bharata, you should not think of Kaikeyi as at fault. This exile of Rama will turn out to bring happiness.', 'veda-app-ai-draft', true),
('ramayana-2-86-29', 'en', 'Having saluted him and walked around him, Bharata, his purpose achieved, took leave and ordered, ''Let the army be yoked.''', 'veda-app-ai-draft', true),
('ramayana-2-86-30', 'en', 'Then many people of many kinds, eager to set out, yoked horses and divine chariots adorned with gold, and mounted them.', 'veda-app-ai-draft', true),
('ramayana-2-86-31', 'en', 'Female and male elephants with golden girths and banners set out roaring, like thunderclouds at the end of summer.', 'veda-app-ai-draft', true),
('ramayana-2-86-32', 'en', 'Many kinds of costly carriages, large and small, went along, and the foot soldiers went on foot.', 'veda-app-ai-draft', true),
('ramayana-2-86-33', 'en', 'Then the women, led by Kausalya, longing to see Rama, set out joyfully in the finest carriages.', 'veda-app-ai-draft', true),
('ramayana-2-86-34', 'en', 'Glorious Bharata, with his retinue, set out in a fine palanquin that shone like the rising sun.', 'veda-app-ai-draft', true),
('ramayana-2-86-35', 'en', 'That great army, full of elephants, horses and chariots, set out towards the south like a great rising cloud, passing forests full of beasts and birds.', 'veda-app-ai-draft', true),
('ramayana-2-86-36', 'en', 'Bharata''s army, with its joyful elephants, horses and warriors, frightening the flocks of beasts and birds as it plunged into the great forest, looked splendid there.', 'veda-app-ai-draft', true),
('ramayana-2-87-1', 'en', 'Disturbed by that great marching army, the rutting herd leaders of the forest fled with their herds.', 'veda-app-ai-draft', true),
('ramayana-2-87-2', 'en', 'Bears, herds of spotted deer and ruru deer were seen all around in the forest groves, on the hills and by the rivers.', 'veda-app-ai-draft', true),
('ramayana-2-87-3', 'en', 'The righteous son of Dasharatha set out gladly, surrounded by the great, noisy army with its four divisions.', 'veda-app-ai-draft', true),
('ramayana-2-87-4', 'en', 'Great-souled Bharata''s army, like the surge of the ocean, covered the earth as clouds cover the sky in the rains.', 'veda-app-ai-draft', true),
('ramayana-2-87-5', 'en', 'Spread over with masses of horses and swift elephants, the ground could not be seen for a long time then.', 'veda-app-ai-draft', true),
('ramayana-2-87-6', 'en', 'Having travelled far, his horses very tired, glorious Bharata spoke to Vasishtha, best of counsellors.', 'veda-app-ai-draft', true),
('ramayana-2-87-7', 'en', 'From the look of it and from what I have heard, we have clearly reached the place Bharadvaja described.', 'veda-app-ai-draft', true),
('ramayana-2-87-8', 'en', 'This is Mount Chitrakuta and that is the Mandakini river. That forest, like a dark cloud, can be seen from afar.', 'veda-app-ai-draft', true),
('ramayana-2-87-9', 'en', 'The lovely slopes of Mount Chitrakuta are now being trampled by my mountain-like elephants.', 'veda-app-ai-draft', true),
('ramayana-2-87-10', 'en', 'These trees on the mountain slopes shed their flowers, as dark rain clouds pour water at the end of summer.', 'veda-app-ai-draft', true),
('ramayana-2-87-11', 'en', 'Look, Shatrughna, at the mountain, frequented by kinnaras, crowded all around with horses like the sea with sea creatures.', 'veda-app-ai-draft', true),
('ramayana-2-87-12', 'en', 'These herds of deer, driven on swiftly, look like lines of clouds in the autumn sky scattered by the wind.', 'veda-app-ai-draft', true),
('ramayana-2-87-13', 'en', 'These men wear fragrant flower crowns on their heads, like southerners with shields bright as clouds.', 'veda-app-ai-draft', true),
('ramayana-2-87-14', 'en', 'This forest, which was silent and frightening to look at, now seems to me crowded with people like Ayodhya.', 'veda-app-ai-draft', true),
('ramayana-2-87-15', 'en', 'The dust raised by the hooves covers the sky and stays there; the wind quickly carries it away, as if doing me a favour.', 'veda-app-ai-draft', true),
('ramayana-2-87-16', 'en', 'Look, Shatrughna, at these chariots with horses, driven by the best charioteers, speeding through the forest.', 'veda-app-ai-draft', true),
('ramayana-2-87-17', 'en', 'Look at these lovely peacocks, frightened, entering the mountain, the home of birds.', 'veda-app-ai-draft', true),
('ramayana-2-87-18', 'en', 'This place seems to me exceedingly lovely. It is clearly the dwelling of ascetics, like the road to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-87-19', 'en', 'Many spotted deer with their does are seen in the forest, beautiful, as if painted with flowers.', 'veda-app-ai-draft', true),
('ramayana-2-87-20', 'en', 'Let the soldiers go forward and search the forest so that those two tigers among men, Rama and Lakshmana, may be found.', 'veda-app-ai-draft', true),
('ramayana-2-87-21', 'en', 'Hearing Bharata''s words, brave men with weapons in hand entered the forest and then saw smoke.', 'veda-app-ai-draft', true),
('ramayana-2-87-22', 'en', 'Seeing the top of the smoke, they came back and told Bharata: ''There is no fire where there are no people. Clearly the two Raghavas are right here.''', 'veda-app-ai-draft', true),
('ramayana-2-87-23', 'en', '''Or if the two princes, tigers among men and scorchers of foes, are not here, then clearly there are other ascetics here like Rama.''', 'veda-app-ai-draft', true),
('ramayana-2-87-24', 'en', 'Hearing their sensible words, approved by the good, Bharata, crusher of enemy forces, spoke to all the soldiers.', 'veda-app-ai-draft', true),
('ramayana-2-87-25', 'en', 'Stay here, all of you; no one should go ahead from here. I alone will go, with Sumantra and our teacher.', 'veda-app-ai-draft', true),
('ramayana-2-87-26', 'en', 'Told this, all of them stood there on every side, and Bharata fixed his gaze where the top of the smoke was.', 'veda-app-ai-draft', true),
('ramayana-2-87-27', 'en', 'The army halted by Bharata, looking at the smoke ahead, soon became joyful, knowing they would meet their beloved Rama.', 'veda-app-ai-draft', true),
('ramayana-2-88-1', 'en', 'Having lived long on that mountain, loving its hills and woods, wishing to please Vaidehi and to delight his own heart...', 'veda-app-ai-draft', true),
('ramayana-2-88-2', 'en', '...the godlike son of Dasharatha showed his wife the many-coloured Chitrakuta, as Indra shows Shachi.', 'veda-app-ai-draft', true),
('ramayana-2-88-3', 'en', 'Dear one, neither the loss of the kingdom nor being apart from friends troubles my mind, when I see this lovely mountain.', 'veda-app-ai-draft', true),
('ramayana-2-88-4', 'en', 'Look at this mountain, dear, full of many kinds of birds, adorned with peaks rich in minerals that seem to pierce the sky.', 'veda-app-ai-draft', true),
('ramayana-2-88-5', 'en', 'Some areas look like silver, some like blood, some yellow or madder-red, some shine like fine gems.', 'veda-app-ai-draft', true),
('ramayana-2-88-6', 'en', 'Some shine like topaz, crystal or ketaka flowers, some like stars or mercury: the regions of this king of mountains glow with minerals.', 'veda-app-ai-draft', true),
('ramayana-2-88-7', 'en', 'Filled with herds of deer, leopards, hyenas and bears, all harmless, and full of many birds, this mountain shines.', 'veda-app-ai-draft', true),
('ramayana-2-88-8', 'en', '...with mango, jambu, asana, lodhra, priyala, jackfruit, dhava, ankola, bhavya, tinisha, bilva, tinduka and bamboo...', 'veda-app-ai-draft', true),
('ramayana-2-88-9', 'en', '...with kashmari, arishta, varana, madhuka, tilaka, badari, amalaka, nipa, vetra, dhanvana and bijaka trees...', 'veda-app-ai-draft', true),
('ramayana-2-88-10', 'en', '...flowering, bearing fruit, shady and lovely: filled with these and others, this mountain flourishes in beauty.', 'veda-app-ai-draft', true),
('ramayana-2-88-11', 'en', 'Look, dear, at these high-spirited kinnaras in pairs, delighting in love on the lovely mountain plateaus.', 'veda-app-ai-draft', true),
('ramayana-2-88-12', 'en', 'See the swords and fine clothes hanging on the branches, and the lovely playgrounds of the vidyadhara women.', 'veda-app-ai-draft', true),
('ramayana-2-88-13', 'en', 'With waterfalls, springs and trickles here and there, this mountain shines like an elephant in rut.', 'veda-app-ai-draft', true),
('ramayana-2-88-14', 'en', 'What man would not be delighted by the breeze from the caves, carrying the scent of many flowers and pleasing the nose?', 'veda-app-ai-draft', true),
('ramayana-2-88-15', 'en', 'Blameless one, if I live here many autumns with you and Lakshmana, grief will not burn me.', 'veda-app-ai-draft', true),
('ramayana-2-88-16', 'en', 'Lovely one, I am delighted with this beautiful, many-peaked mountain, full of flowers and fruit and many kinds of birds.', 'veda-app-ai-draft', true),
('ramayana-2-88-17', 'en', 'Through this forest life I have gained two fruits: my father freed from his debt of dharma, and Bharata''s happiness.', 'veda-app-ai-draft', true),
('ramayana-2-88-18', 'en', 'Vaidehi, do you enjoy Chitrakuta with me, seeing its many sights that delight mind, speech and body?', 'veda-app-ai-draft', true),
('ramayana-2-88-19', 'en', 'My ancestors, the great royal sages, called this forest life the nectar of kings, for welfare after death.', 'veda-app-ai-draft', true),
('ramayana-2-88-20', 'en', 'Hundreds of wide rocks on the mountain shine all around in many colours: blue, yellow, white and red.', 'veda-app-ai-draft', true),
('ramayana-2-88-21', 'en', 'At night thousands of herbs on this king of mountains shine with their own light, like flames of fire.', 'veda-app-ai-draft', true),
('ramayana-2-88-22', 'en', 'Some places of this mountain look like houses, some like gardens, and some, lovely one, are a single great rock.', 'veda-app-ai-draft', true),
('ramayana-2-88-23', 'en', 'Chitrakuta seems to rise splitting the earth, and its auspicious peak can be seen from everywhere.', 'veda-app-ai-draft', true),
('ramayana-2-88-24', 'en', 'Look at the comfortable beds of lovers, made of kushtha, punnaga, tagara and birch leaves, strewn with lotus petals.', 'veda-app-ai-draft', true),
('ramayana-2-88-25', 'en', 'Look, dear, at the lotus garlands crushed and thrown aside by lovers, and the many kinds of fruit.', 'veda-app-ai-draft', true),
('ramayana-2-88-26', 'en', 'With its many roots, fruits and waters, Chitrakuta surpasses even Kubera''s lotus pool and the land of the northern Kurus.', 'veda-app-ai-draft', true),
('ramayana-2-88-27', 'en', 'Spending this time pleasantly with you, Sita, and with Lakshmana, I will find joy that increases the dharma of my family, staying on the path of the good with my own strict rules.', 'veda-app-ai-draft', true),
('ramayana-2-89-1', 'en', 'Then, coming down from the mountain, the lord of Kosala showed Maithili the lovely Mandakini river with its pure water.', 'veda-app-ai-draft', true),
('ramayana-2-89-2', 'en', 'And lotus-eyed Rama spoke to the daughter of the king of Videha, with her fine hips and face lovely as the moon.', 'veda-app-ai-draft', true),
('ramayana-2-89-3', 'en', 'Look at the lovely Mandakini river, with its colourful sandbanks, frequented by swans and cranes, full of flowers.', 'veda-app-ai-draft', true),
('ramayana-2-89-4', 'en', 'Surrounded by many kinds of flowering and fruiting trees on its banks, it shines on every side like the lotus pool of Kubera, king of kings.', 'veda-app-ai-draft', true),
('ramayana-2-89-5', 'en', 'The lovely bathing places, their water muddied now by herds of deer drinking, give me joy.', 'veda-app-ai-draft', true),
('ramayana-2-89-6', 'en', 'Beloved, sages wearing matted hair and deerskins, with bark upper garments, bathe in the Mandakini at the proper times.', 'veda-app-ai-draft', true),
('ramayana-2-89-7', 'en', 'These other sages, wide-eyed one, strict in their vows, stand with arms raised, worshipping the sun as their discipline.', 'veda-app-ai-draft', true),
('ramayana-2-89-8', 'en', 'With its peaks shaken by the wind and its trees scattering leaves and flowers around the river, the mountain seems to dance.', 'veda-app-ai-draft', true),
('ramayana-2-89-9', 'en', 'Look at the Mandakini river: here its water is clear as crystal, there it has fine sandbanks, elsewhere it is crowded with perfected beings.', 'veda-app-ai-draft', true),
('ramayana-2-89-10', 'en', 'See the masses of flowers scattered by the wind, and others floating in the middle of the water.', 'veda-app-ai-draft', true),
('ramayana-2-89-11', 'en', 'And see, gracious one, the chakravaka birds with their sweet voices climbing onto them, calling out lovely notes.', 'veda-app-ai-draft', true),
('ramayana-2-89-12', 'en', 'Lovely one, seeing Chitrakuta and the Mandakini, and seeing you, I think better than living in the city.', 'veda-app-ai-draft', true),
('ramayana-2-89-13', 'en', 'Bathe with me in this river, its water always stirred by perfected beings free of impurity, rich in austerity, self-control and calm.', 'veda-app-ai-draft', true),
('ramayana-2-89-14', 'en', 'Sita, bathe in this Mandakini as you would with a friend, dipping down among the red and white lotuses, lovely one.', 'veda-app-ai-draft', true),
('ramayana-2-89-15', 'en', 'Dear one, always think of the wild animals as townspeople, the mountain as Ayodhya and this river as the Sarayu.', 'veda-app-ai-draft', true),
('ramayana-2-89-16', 'en', 'Righteous Lakshmana stands by my command, and you, Vaidehi, are in harmony with me; you both give me joy.', 'veda-app-ai-draft', true),
('ramayana-2-89-17', 'en', 'Bathing three times a day, eating honey, roots and fruit, with you I do not long today for Ayodhya or the kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-89-18', 'en', 'There is no one who would not be happy and free of fatigue at this lovely river, stirred by herds of elephants, drunk from by elephants, lions and monkeys, and adorned with flowering trees.', 'veda-app-ai-draft', true),
('ramayana-2-89-19', 'en', 'Speaking such fitting words about the river, with his beloved companion, Rama, who increases the Raghu line, wandered over lovely Chitrakuta, dark as collyrium.', 'veda-app-ai-draft', true),
('ramayana-2-90-1', 'en', 'While he was living there, the dust and noise of the approaching Bharata''s army rose up, touching the sky.', 'veda-app-ai-draft', true),
('ramayana-2-90-2', 'en', 'Meanwhile, frightened by the great noise, the troubled rutting herd leaders fled with their herds in all directions.', 'veda-app-ai-draft', true),
('ramayana-2-90-3', 'en', 'Raghava heard the noise made by the army and saw all the herd leaders fleeing.', 'veda-app-ai-draft', true),
('ramayana-2-90-4', 'en', 'Seeing them fleeing and hearing that noise, Rama spoke to Lakshmana, Sumitra''s son, of blazing energy.', 'veda-app-ai-draft', true),
('ramayana-2-90-5', 'en', 'Look, Lakshmana, Sumitra is blessed with a good son in you. A tumultuous sound, deep as terrible thunder, is heard.', 'veda-app-ai-draft', true),
('ramayana-2-90-6', 'en', 'A king or a prince may be hunting in the forest, or there may be some wild beast. Son of Sumitra, find out quickly what it truly is.', 'veda-app-ai-draft', true),
('ramayana-2-90-7', 'en', 'Lakshmana quickly climbed a flowering sala tree and, looking in all directions, looked east.', 'veda-app-ai-draft', true),
('ramayana-2-90-8', 'en', 'Looking north, he saw a great army crowded with chariots, horses and elephants, with ready foot soldiers.', 'veda-app-ai-draft', true),
('ramayana-2-90-9', 'en', 'He told Rama of that army, full of horses and elephants and decorated with chariot banners, and said this:', 'veda-app-ai-draft', true),
('ramayana-2-90-10', 'en', 'Let my noble brother put out the fire and let Sita go into a cave. String your bow and take your arrows and armour.', 'veda-app-ai-draft', true),
('ramayana-2-90-11', 'en', 'Rama, tiger among men, replied to Lakshmana: ''Look carefully, son of Sumitra. Whose army do you think it is?''', 'veda-app-ai-draft', true),
('ramayana-2-90-12', 'en', 'Told this by Rama, Lakshmana spoke, angry as a fire about to burn up that army.', 'veda-app-ai-draft', true),
('ramayana-2-90-13', 'en', 'Clearly Bharata, Kaikeyi''s son, having been consecrated and wanting the kingdom secured, is coming to kill us both.', 'veda-app-ai-draft', true),
('ramayana-2-90-14', 'en', 'That great, splendid tree is clearly visible: the kovidara banner on the chariot, with its tall trunk, shines there.', 'veda-app-ai-draft', true),
('ramayana-2-90-15', 'en', 'They ride swift horses as they please; these riders shine, delighted, mounted on elephants.', 'veda-app-ai-draft', true),
('ramayana-2-90-16', 'en', 'Hero, let us take our bows and retreat to the mountain, or stay right here armed and ready. Perhaps the kovidara banner will come into our power in battle.', 'veda-app-ai-draft', true),
('ramayana-2-90-17', 'en', 'Perhaps I will see Bharata, because of whom you, Raghava, Sita and I have met with this great misfortune.', 'veda-app-ai-draft', true),
('ramayana-2-90-18', 'en', 'This enemy Bharata, because of whom you, Raghava, lost the eternal kingdom, has come, hero; he must be killed by me.', 'veda-app-ai-draft', true),
('ramayana-2-90-19', 'en', 'I see no wrong in killing Bharata, Raghava. There is no sin in casting off one who has harmed us before. When he is dead, rule the whole earth.', 'veda-app-ai-draft', true),
('ramayana-2-90-20', 'en', 'Today let Kaikeyi, greedy for the kingdom, see her son killed by me in battle, deeply grieved, like a tree broken by an elephant.', 'veda-app-ai-draft', true),
('ramayana-2-90-21', 'en', 'I will kill Kaikeyi with her followers and kin. Let the earth be freed today from a great stain.', 'veda-app-ai-draft', true),
('ramayana-2-90-22', 'en', 'Today, giver of honour, I will release this restrained anger and insult on the enemy forces like fire on dry brush.', 'veda-app-ai-draft', true),
('ramayana-2-90-23', 'en', 'Today with sharp arrows, piercing enemy bodies, I will drench this forest of Chitrakuta with blood.', 'veda-app-ai-draft', true),
('ramayana-2-90-24', 'en', 'Let wild beasts drag away the elephants and horses whose hearts are pierced by my arrows, and the men I kill.', 'veda-app-ai-draft', true),
('ramayana-2-90-25', 'en', 'Having killed Bharata and his army in this great forest, I will without doubt be free of my debt to my arrows and bow.', 'veda-app-ai-draft', true),
('ramayana-2-91-1', 'en', 'Rama calmed Lakshmana, Sumitra''s son, who was furious and overcome with anger, and said this.', 'veda-app-ai-draft', true),
('ramayana-2-91-2', 'en', 'What need is there here for a bow, or a sword and shield, when the great archer, the very wise Bharata, has come himself?', 'veda-app-ai-draft', true),
('ramayana-2-91-3', 'en', 'It is natural that Bharata wants to see us now. He would never even think of doing us harm.', 'veda-app-ai-draft', true),
('ramayana-2-91-4', 'en', 'When has Bharata ever done you any wrong? What fear is this that makes you suspect Bharata here today?', 'veda-app-ai-draft', true),
('ramayana-2-91-5', 'en', 'You must not speak harshly or unkindly of Bharata. If you wrong Bharata, it is I who am wronged.', 'veda-app-ai-draft', true),
('ramayana-2-91-6', 'en', 'How could sons kill their father in any crisis, or a brother kill his brother, who is his own life, son of Sumitra?', 'veda-app-ai-draft', true),
('ramayana-2-91-7', 'en', 'If you are saying this for the sake of the kingdom, when I see Bharata I will tell him, ''Give the kingdom to him.''', 'veda-app-ai-draft', true),
('ramayana-2-91-8', 'en', 'Lakshmana, if I tell Bharata truly, ''Give him the kingdom'', he will say ''Certainly.''', 'veda-app-ai-draft', true),
('ramayana-2-91-9', 'en', 'Told this by his righteous brother, Lakshmana, devoted to his welfare, shrank into his own limbs with shame.', 'veda-app-ai-draft', true),
('ramayana-2-91-10', 'en', 'Seeing Lakshmana ashamed, Raghava replied: ''I think this mighty-armed one has come here to see us.''', 'veda-app-ai-draft', true),
('ramayana-2-91-11', 'en', 'Thinking of our forest life, he will take us home; or he may take Vaidehi, who is used to great comfort.', 'veda-app-ai-draft', true),
('ramayana-2-91-12', 'en', 'Those two fine horses of good breed shine there, hero, swift and as fast as the wind.', 'veda-app-ai-draft', true),
('ramayana-2-91-13', 'en', 'That huge elephant swaying at the front of the army is Shatrunjaya, the old elephant of our wise father.', 'veda-app-ai-draft', true),
('ramayana-2-91-14', 'en', 'Then Lakshmana, conqueror in battle, came down from the top of the sala tree and stood by Rama''s side with folded hands.', 'veda-app-ai-draft', true),
('ramayana-2-91-15', 'en', 'Then, as Bharata had ordered that there be no crowding, the army camp was set up all around that mountain.', 'veda-app-ai-draft', true),
('ramayana-2-91-16', 'en', 'The Ikshvaku army, full of elephants, horses and chariots, camped surrounding the side of the mountain for a yojana and a half.', 'veda-app-ai-draft', true),
('ramayana-2-91-17', 'en', 'That army, led to Chitrakuta by the wise Bharata, putting dharma first and casting off pride, to win the favour of the joy of the Raghus, shone splendidly.', 'veda-app-ai-draft', true),
('ramayana-2-92-1', 'en', 'Having camped the army, the lord, best of those who walk, wished to go on foot to Kakutstha, who honours his elders.', 'veda-app-ai-draft', true),
('ramayana-2-92-2', 'en', 'As soon as the army had camped in good order, Bharata said this to his brother Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-92-3', 'en', 'Gentle one, you should quickly search this forest all around with groups of men and these hunters.', 'veda-app-ai-draft', true),
('ramayana-2-92-4', 'en', 'Until I see Rama, or mighty Lakshmana, or fortunate Vaidehi, I will have no peace.', 'veda-app-ai-draft', true),
('ramayana-2-92-5', 'en', 'Until I see my brother''s lovely moonlike face with eyes like lotus petals, I will have no peace.', 'veda-app-ai-draft', true),
('ramayana-2-92-6', 'en', 'Until I place on my head my brother''s feet, bearing the marks of a king, I will have no peace.', 'veda-app-ai-draft', true),
('ramayana-2-92-7', 'en', 'Until he who deserves the kingdom is established in our ancestral kingdom, wet with the water of consecration, I will have no peace.', 'veda-app-ai-draft', true),
('ramayana-2-92-8', 'en', 'Fortunate Vaidehi, Janaka''s daughter, has fulfilled her purpose, she who follows her husband, the lord of the sea-bounded earth.', 'veda-app-ai-draft', true),
('ramayana-2-92-9', 'en', 'Blessed is that mountain Chitrakuta, like the king of mountains, where Kakutstha lives like Kubera in the Nandana garden.', 'veda-app-ai-draft', true),
('ramayana-2-92-10', 'en', 'This hard forest, full of wild beasts, has fulfilled its purpose, since radiant Rama, best of warriors, lives in it.', 'veda-app-ai-draft', true),
('ramayana-2-92-11', 'en', 'Having said this, radiant Bharata, bull among men, entered the great forest on foot.', 'veda-app-ai-draft', true),
('ramayana-2-92-12', 'en', 'The best of speakers went through the middle of the thickets of trees with flowering tops growing on the mountain slopes.', 'veda-app-ai-draft', true),
('ramayana-2-92-13', 'en', 'Reaching a flowering sala tree on Mount Chitrakuta, he saw the raised banner of smoke from the fire at Rama''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-2-92-14', 'en', 'Seeing it, glorious Bharata rejoiced with his kin, knowing ''Rama is here'', like one who has reached the far shore of the water.', 'veda-app-ai-draft', true),
('ramayana-2-92-15', 'en', 'Seeing Rama''s hermitage on Mount Chitrakuta, inhabited by holy people, great-souled Bharata settled the army again and hurried on with Guha.', 'veda-app-ai-draft', true),
('ramayana-2-93-1', 'en', 'With the army camped, eager Bharata went to see his brother, showing the way to Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-93-2', 'en', 'Instructing the sage Vasishtha, ''Bring my mothers quickly,'' he who loved his elders went on ahead quickly.', 'veda-app-ai-draft', true),
('ramayana-2-93-3', 'en', 'Sumantra followed Shatrughna not far behind; his longing to see Rama was as great as Bharata''s.', 'veda-app-ai-draft', true),
('ramayana-2-93-4', 'en', 'As he went, glorious Bharata saw his brother''s leaf hut and cottage standing among the dwellings of ascetics.', 'veda-app-ai-draft', true),
('ramayana-2-93-5', 'en', 'In front of that hut Bharata saw broken firewood and gathered flowers.', 'veda-app-ai-draft', true),
('ramayana-2-93-6', 'en', 'And in that forest he saw large heaps made of the dung of deer and buffalo, kept against the cold.', 'veda-app-ai-draft', true),
('ramayana-2-93-7', 'en', 'As he went, radiant, mighty-armed Bharata joyfully said to Shatrughna and to all the ministers:', 'veda-app-ai-draft', true),
('ramayana-2-93-8', 'en', 'I think we have reached the place Bharadvaja told us of; I think the Mandakini river is not far from here.', 'veda-app-ai-draft', true),
('ramayana-2-93-9', 'en', 'These bark strips tied up high must be Lakshmana''s, a path marked for recognition by one wanting to go out at odd hours.', 'veda-app-ai-draft', true),
('ramayana-2-93-10', 'en', 'And this is the trail of strong elephants with lofty tusks that roared at one another on the mountain side.', 'veda-app-ai-draft', true),
('ramayana-2-93-11', 'en', 'That thick smoke is seen from the fire that ascetics always wish to keep in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-93-12', 'en', 'Here I will joyfully see my noble brother, tiger among men, who honours his elders, Raghava, like a great sage.', 'veda-app-ai-draft', true),
('ramayana-2-93-13', 'en', 'Going on for a moment, Raghava reached the Mandakini at Chitrakuta and said this to those people:', 'veda-app-ai-draft', true),
('ramayana-2-93-14', 'en', 'The tiger among men, lord of the people, sits on the bare ground in the hero''s posture, having come to a lonely place. Shame on my birth and my life!', 'veda-app-ai-draft', true),
('ramayana-2-93-15', 'en', 'Because of me the radiant lord of the world has met misfortune; giving up all pleasures, Raghava lives in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-93-16', 'en', 'Condemned by the world, I will fall at Rama''s feet and Sita''s again and again today, begging their forgiveness.', 'veda-app-ai-draft', true),
('ramayana-2-93-17', 'en', 'Lamenting thus in that forest, the son of Dasharatha saw a large, holy and lovely leaf hut.', 'veda-app-ai-draft', true),
('ramayana-2-93-18', 'en', 'It was covered with many leaves of sala, tala and ashvakarna trees, spacious, and strewn with soft kusha grass like an altar at a sacrifice.', 'veda-app-ai-draft', true),
('ramayana-2-93-19', 'en', 'It was adorned with bows like Indra''s rainbow, able to bear great strain, gold-backed, very strong and able to harass enemies.', 'veda-app-ai-draft', true),
('ramayana-2-93-20', 'en', 'It was adorned with fearsome arrows in quivers, bright as sunbeams, like Bhogavati adorned with snakes with blazing mouths.', 'veda-app-ai-draft', true),
('ramayana-2-93-21', 'en', 'It shone with two swords in sheaths of fine silver and was adorned with two shields decorated with gold spots.', 'veda-app-ai-draft', true),
('ramayana-2-93-22', 'en', 'With colourful gold-adorned lizard-skin finger guards hung there, it was unassailable by hosts of enemies, as a lion''s cave is by deer.', 'veda-app-ai-draft', true),
('ramayana-2-93-23', 'en', 'There in Rama''s dwelling Bharata saw a large, holy altar sloping to the northeast, with a blazing fire.', 'veda-app-ai-draft', true),
('ramayana-2-93-24', 'en', 'Looking for a moment, Bharata saw his elder, Rama, seated in the cottage, wearing a coil of matted hair.', 'veda-app-ai-draft', true),
('ramayana-2-93-25', 'en', 'He saw Rama sitting there wearing a black deerskin and bark clothes, like a fire all around.', 'veda-app-ai-draft', true),
('ramayana-2-93-26', 'en', '...lion-shouldered, mighty-armed, with eyes like white lotuses, the righteous lord of the sea-bounded earth...', 'veda-app-ai-draft', true),
('ramayana-2-93-27', 'en', '...the mighty-armed one seated like eternal Brahma on the bare ground strewn with darbha grass, with Sita and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-93-28', 'en', 'Seeing him, glorious, righteous Bharata, Kaikeyi''s son, flooded with grief and confusion, ran towards him.', 'veda-app-ai-draft', true),
('ramayana-2-93-29', 'en', 'Seeing him, he lamented in distress, his voice thick with tears, and unable to hold steady, he spoke.', 'veda-app-ai-draft', true),
('ramayana-2-93-30', 'en', 'He who should be served by his subjects in the assembly sits here served by wild animals: this is my elder brother.', 'veda-app-ai-draft', true),
('ramayana-2-93-31', 'en', 'The great soul who was used to thousands of garments now wears a deerskin here, practising dharma.', 'veda-app-ai-draft', true),
('ramayana-2-93-32', 'en', 'How does Raghava, who once wore many lovely flowers, now bear this load of matted hair?', 'veda-app-ai-draft', true),
('ramayana-2-93-33', 'en', 'He whose store of merit came from sacrifices duly performed now seeks merit born of bodily hardship.', 'veda-app-ai-draft', true),
('ramayana-2-93-34', 'en', 'How is the body of my noble brother, once anointed with costly sandal, now covered with dirt?', 'veda-app-ai-draft', true),
('ramayana-2-93-35', 'en', 'Because of me Rama, used to comfort, has met this sorrow. Shame on my cruel life, condemned by the world!', 'veda-app-ai-draft', true),
('ramayana-2-93-36', 'en', 'Lamenting thus in misery, his lotus face covered in sweat, Bharata fell weeping before he could reach Rama''s feet.', 'veda-app-ai-draft', true),
('ramayana-2-93-37', 'en', 'Burning with sorrow, mighty Prince Bharata said ''Noble one!'' once, pitifully, and could say nothing more.', 'veda-app-ai-draft', true),
('ramayana-2-93-38', 'en', 'His throat choked with tears, looking at famous Rama, he cried out only ''Noble one!'' and could speak no further.', 'veda-app-ai-draft', true),
('ramayana-2-93-39', 'en', 'Shatrughna too, weeping, bowed at Rama''s feet. Rama embraced them both and shed tears as well.', 'veda-app-ai-draft', true),
('ramayana-2-93-40', 'en', 'Then the two princes met Sumantra and Guha in the forest, like the sun and moon in the sky meeting Venus and Jupiter.', 'veda-app-ai-draft', true),
('ramayana-2-93-41', 'en', 'Seeing those princes, like leaders of elephant herds, gathered in the great forest, all the forest dwellers too set aside their joy and wept.', 'veda-app-ai-draft', true),
('ramayana-2-94-1', 'en', 'Raghava kissed him on the head, embraced him, took Bharata on his lap and attentively asked him:', 'veda-app-ai-draft', true),
('ramayana-2-94-2', 'en', 'Where was your father, dear one, that you have come to the forest? You should not come to the forest while he lives.', 'veda-app-ai-draft', true),
('ramayana-2-94-3', 'en', 'After a long time I see Bharata, come from afar, hard to recognise in this forest. Why have you come to the forest, dear one?', 'veda-app-ai-draft', true),
('ramayana-2-94-4', 'en', 'I hope King Dasharatha is well, true to his promise, performer of the Rajasuya and Ashvamedha sacrifices, firm in dharma?', 'veda-app-ai-draft', true),
('ramayana-2-94-5', 'en', 'I hope that learned Brahmin, always devoted to dharma and radiant, the preceptor of the Ikshvakus, is honoured properly, dear one?', 'veda-app-ai-draft', true),
('ramayana-2-94-6', 'en', 'Dear one, I hope Kausalya and Sumitra, mother of good sons, are happy, and that the noble queen Kaikeyi is content?', 'veda-app-ai-draft', true),
('ramayana-2-94-7', 'en', 'I hope your royal priest, disciplined, of good family, learned, free of envy and watchful, is honoured by you?', 'veda-app-ai-draft', true),
('ramayana-2-94-8', 'en', 'I hope the one in charge of your fires, who knows the rites, is wise and honest, always tells you on time what has been offered and what is to be offered?', 'veda-app-ai-draft', true),
('ramayana-2-94-9', 'en', 'Dear one, I hope you respect your teacher Sudhanvan, master of the best arrows and weapons and expert in statecraft?', 'veda-app-ai-draft', true),
('ramayana-2-94-10', 'en', 'Dear one, I hope you have made ministers who are like yourself: brave, learned, self-controlled, of good family and able to read gestures?', 'veda-app-ai-draft', true),
('ramayana-2-94-11', 'en', 'Raghava, good counsel, well guarded by ministers who keep secrets and know the texts, is the root of a king''s success.', 'veda-app-ai-draft', true),
('ramayana-2-94-12', 'en', 'I hope you do not fall under the power of sleep, that you wake at the proper time, and that in the last part of the night you think about how to act wisely?', 'veda-app-ai-draft', true),
('ramayana-2-94-13', 'en', 'I hope you do not deliberate alone, nor with too many? I hope your decisions do not leak out across the kingdom?', 'veda-app-ai-draft', true),
('ramayana-2-94-14', 'en', 'Raghava, having decided on an undertaking that costs little and yields much, I hope you begin it quickly and do not delay?', 'veda-app-ai-draft', true),
('ramayana-2-94-15', 'en', 'I hope other kings know only your tasks that are completed or nearly done, not those still to be done?', 'veda-app-ai-draft', true),
('ramayana-2-94-16', 'en', 'Dear one, I hope your deliberations are not discovered by others through guesswork or by any means, either from you or from your ministers?', 'veda-app-ai-draft', true),
('ramayana-2-94-17', 'en', 'I hope you prefer one wise man to a thousand fools? For in a crisis a wise man can bring about great good.', 'veda-app-ai-draft', true),
('ramayana-2-94-18', 'en', 'Even if a king keeps thousands or tens of thousands of fools around him, they are no help.', 'veda-app-ai-draft', true),
('ramayana-2-94-19', 'en', 'A single minister who is intelligent, brave, capable and discerning can bring a king or a prince great prosperity.', 'veda-app-ai-draft', true),
('ramayana-2-94-20', 'en', 'I hope you assign the best servants to great tasks, the middling to middling tasks and the lowest to minor tasks?', 'veda-app-ai-draft', true),
('ramayana-2-94-21', 'en', 'I hope you employ in the highest tasks the best ministers, honest, tested, who served your father and grandfather?', 'veda-app-ai-draft', true),
('ramayana-2-94-22', 'en', 'I hope priests do not despise you as they would an outcaste, or as women despise a lustful man who takes things by force?', 'veda-app-ai-draft', true),
('ramayana-2-94-23', 'en', 'A king who does not stop a scheming physician, a servant bent on corrupting others, or a brave man hungry for power, will himself be destroyed.', 'veda-app-ai-draft', true),
('ramayana-2-94-24', 'en', 'I hope you have appointed an army commander who is bold, brave, steady, wise, honest, of good family, loyal and skilled?', 'veda-app-ai-draft', true),
('ramayana-2-94-25', 'en', 'I hope your chief warriors, strong, skilled in war, of proven deeds and valiant, are honoured and respected by you?', 'veda-app-ai-draft', true),
('ramayana-2-94-26', 'en', 'I hope you give the army its rations and wages properly and on time, without delay?', 'veda-app-ai-draft', true),
('ramayana-2-94-27', 'en', 'When rations and wages are delayed, those who serve grow angry with their master and turn against him; that is said to be a great disaster.', 'veda-app-ai-draft', true),
('ramayana-2-94-28', 'en', 'I hope all the leading men of good families are devoted to you, and ready to give their lives for your cause?', 'veda-app-ai-draft', true),
('ramayana-2-94-29', 'en', 'Bharata, I hope your envoy is a native of the land, learned, skilful, quick-witted, wise and one who says exactly what he is told?', 'veda-app-ai-draft', true),
('ramayana-2-94-30', 'en', 'I hope you know, through three spies each unknown to the others, about the eighteen officials of the enemy and fifteen of your own side?', 'veda-app-ai-draft', true),
('ramayana-2-94-31', 'en', 'Slayer of foes, I hope you do not ignore enemies who have been driven out and have returned, thinking them weak?', 'veda-app-ai-draft', true),
('ramayana-2-94-32', 'en', 'Dear one, I hope you do not keep company with materialist Brahmins? They are skilled only in harm, childish, thinking themselves wise.', 'veda-app-ai-draft', true),
('ramayana-2-94-33', 'en', 'Though the main books of dharma exist, these foolish men, having gained logical skill, speak about meaningless things.', 'veda-app-ai-draft', true),
('ramayana-2-94-34', 'en', '...Ayodhya, dear one, once inhabited by our heroic ancestors, true to its name, with strong gates, crowded with elephants, horses and chariots...', 'veda-app-ai-draft', true),
('ramayana-2-94-35', 'en', '...surrounded by thousands of Brahmins, Kshatriyas and Vaishyas, always devoted to their own work, self-controlled and energetic...', 'veda-app-ai-draft', true),
('ramayana-2-94-36', 'en', '...surrounded by palaces of many shapes, full of learned people: I hope you protect prosperous, flourishing Ayodhya?', 'veda-app-ai-draft', true),
('ramayana-2-94-37', 'en', 'I hope the countryside is full of hundreds of shrines, crowded with well-settled people, adorned with temples, water stations and tanks...', 'veda-app-ai-draft', true),
('ramayana-2-94-38', 'en', '...with happy men and women, bright with gatherings and festivals, with well-ploughed fields, rich in cattle, free of violence...', 'veda-app-ai-draft', true),
('ramayana-2-94-39', 'en', '...not dependent on rain alone, lovely, free of dangerous beasts: Raghava, I hope the countryside is prosperous and lives happily?', 'veda-app-ai-draft', true),
('ramayana-2-94-40', 'en', 'Dear one, I hope all who live by farming and cattle-keeping are dear to you? For the world thrives happily when it relies on agriculture and trade.', 'veda-app-ai-draft', true),
('ramayana-2-94-41', 'en', 'I hope you support them by protecting them and relieving their burdens? For a king must protect all who live in his realm according to dharma.', 'veda-app-ai-draft', true),
('ramayana-2-94-42', 'en', 'I hope you console the women and keep them well protected? I hope you do not put too much trust in them or tell them secrets?', 'veda-app-ai-draft', true),
('ramayana-2-94-43', 'en', 'I hope the elephant forest is guarded and you are pleased with the elephants? I hope that, rising early each morning, you show yourself, well dressed, to the people on the main road?', 'veda-app-ai-draft', true),
('ramayana-2-94-44', 'en', 'I hope all your forts are full of wealth, grain, weapons, water and machines, and of craftsmen and archers?', 'veda-app-ai-draft', true),
('ramayana-2-94-45', 'en', 'I hope your income is large and your spending smaller? Raghava, I hope your treasury does not go to the unworthy?', 'veda-app-ai-draft', true),
('ramayana-2-94-46', 'en', 'I hope your spending goes to the gods and ancestors, to Brahmins and guests, to soldiers and to friends?', 'veda-app-ai-draft', true),
('ramayana-2-94-47', 'en', 'I hope that a noble, pure-hearted person, falsely accused of theft, is not punished out of greed without being questioned by those skilled in law?', 'veda-app-ai-draft', true),
('ramayana-2-94-48', 'en', 'Bull among men, I hope a thief who has been caught, questioned and seen in the act with clear cause is not let go out of greed for money?', 'veda-app-ai-draft', true),
('ramayana-2-94-49', 'en', 'Raghava, I hope your learned ministers, free of bias, judge disputes between rich and poor fairly?', 'veda-app-ai-draft', true),
('ramayana-2-94-50', 'en', 'Raghava, the tears shed by those falsely accused destroy the sons and cattle of a ruler who governs for his own pleasure.', 'veda-app-ai-draft', true),
('ramayana-2-94-51', 'en', 'Raghava, I hope you seek to win over the old, the young and the chief physicians by these three: gifts, kind thoughts and kind words?', 'veda-app-ai-draft', true),
('ramayana-2-94-52', 'en', 'I hope you bow to teachers, elders, ascetics, gods, guests, sacred shrines, accomplished people and Brahmins?', 'veda-app-ai-draft', true),
('ramayana-2-94-53', 'en', 'I hope you do not harm dharma for the sake of wealth, or wealth for dharma, or both through love of pleasure and desire?', 'veda-app-ai-draft', true),
('ramayana-2-94-54', 'en', 'Bharata, best of victors, knower of right times, I hope you pursue wealth, dharma and pleasure, dividing your time among them properly?', 'veda-app-ai-draft', true),
('ramayana-2-94-55', 'en', 'Very wise one, I hope the Brahmins learned in all the scriptures, with the townspeople and villagers, wish you well?', 'veda-app-ai-draft', true),
('ramayana-2-94-56', 'en', '...unbelief, falsehood, anger, carelessness, procrastination, not meeting the wise, laziness, being ruled by the five senses...', 'veda-app-ai-draft', true),
('ramayana-2-94-57', 'en', '...deciding matters alone, consulting those who do not understand affairs, not starting what has been decided, failing to keep counsel secret...', 'veda-app-ai-draft', true),
('ramayana-2-94-58', 'en', '...not performing auspicious rites, and rising to greet everyone: I hope you avoid these fourteen faults of kings?', 'veda-app-ai-draft', true),
('ramayana-2-94-59', 'en', 'Raghava, I hope you do not eat tasty food alone? I hope you share it with friends who hope for it?', 'veda-app-ai-draft', true),
('ramayana-2-95-1', 'en', 'Hearing Rama''s words, Bharata replied: ''What use is the duty of kings to me, who am cut off from dharma?''', 'veda-app-ai-draft', true),
('ramayana-2-95-2', 'en', 'Bull among men, this eternal dharma has always held among us: while the eldest son lives, king, the younger should not be king.', 'veda-app-ai-draft', true),
('ramayana-2-95-3', 'en', 'So come with me to prosperous Ayodhya, Raghava, and have yourself consecrated for the good of our family.', 'veda-app-ai-draft', true),
('ramayana-2-95-4', 'en', 'They call a king a mortal, but to me he is a god, whose conduct, joined with dharma and wealth, is called superhuman.', 'veda-app-ai-draft', true),
('ramayana-2-95-5', 'en', 'While I was in Kekaya and you had gone to the forest, the king, honoured by the good and devoted to sacrifice, went to heaven, noble one.', 'veda-app-ai-draft', true),
('ramayana-2-95-6', 'en', 'Rise, tiger among men, and offer water to our father. Shatrughna and I have already made the water offering.', 'veda-app-ai-draft', true),
('ramayana-2-95-7', 'en', 'They say, Raghava, that what a beloved one gives in the world of ancestors becomes everlasting, and you were our father''s beloved.', 'veda-app-ai-draft', true),
('ramayana-2-95-8', 'en', 'Hearing those pitiful words about his father''s death spoken by Bharata, Raghava lost consciousness.', 'veda-app-ai-draft', true),
('ramayana-2-95-9', 'en', 'At Bharata''s unwelcome thunderbolt of words, Rama, scorcher of foes, threw up his arms and fell to the ground, like a flowering tree in the forest cut by an axe.', 'veda-app-ai-draft', true),
('ramayana-2-95-10', 'en', 'The lord of the earth fallen on the ground looked like an elephant asleep, worn out from battering a riverbank.', 'veda-app-ai-draft', true),
('ramayana-2-95-11', 'en', 'His brothers and Vaidehi, weeping, sprinkled the great archer, wasted by grief, with water from all sides.', 'veda-app-ai-draft', true),
('ramayana-2-95-12', 'en', 'Regaining consciousness, shedding tears from his eyes, Kakutstha began to lament pitifully at length.', 'veda-app-ai-draft', true),
('ramayana-2-95-13', 'en', 'What can I, an ill-born son, do now for that great soul, who died of grief for me and whose last rites I did not perform?', 'veda-app-ai-draft', true),
('ramayana-2-95-14', 'en', 'Ah, Bharata, you are fortunate, sinless one, since you and Shatrughna honoured the king in all the funeral rites.', 'veda-app-ai-draft', true),
('ramayana-2-95-15', 'en', 'Even when my forest life is over, I cannot bear to go to Ayodhya, leaderless, distracted and deprived of its king.', 'veda-app-ai-draft', true),
('ramayana-2-95-16', 'en', 'Scorcher of foes, when my forest life is complete, who will guide me again in Ayodhya, now that father has gone to another world?', 'veda-app-ai-draft', true),
('ramayana-2-95-17', 'en', 'Where will I hear those words, pleasing to the ear, that my father spoke to comfort me when he saw me behaving well?', 'veda-app-ai-draft', true),
('ramayana-2-95-18', 'en', 'Having said this to Bharata, Raghava went to his wife and, burning with grief, spoke to her whose face was like the full moon.', 'veda-app-ai-draft', true),
('ramayana-2-95-19', 'en', 'Sita, your father-in-law is dead. Lakshmana, you have lost your father. Bharata tells of the sorrow that the lord of the earth has gone to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-95-20', 'en', 'Having comforted Janaka''s weeping daughter, Rama, grieving, spoke sad words to grieving Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-95-21', 'en', 'Bring ingudi paste and fetch a bark upper cloth. I will go to make the water offering for our great-souled father.', 'veda-app-ai-draft', true),
('ramayana-2-95-22', 'en', 'Let Sita go first, you go beside her, and I will go behind. This is the most painful of journeys.', 'veda-app-ai-draft', true),
('ramayana-2-95-23', 'en', 'Then Sumantra, their constant follower, self-aware, wise, gentle, self-controlled, calm and firmly devoted to Rama...', 'veda-app-ai-draft', true),
('ramayana-2-95-24', 'en', '...comforted Raghava with the princes and, holding him, helped him down to the auspicious Mandakini river.', 'veda-app-ai-draft', true),
('ramayana-2-95-25', 'en', 'Those famous ones reached with difficulty the good bathing place of the lovely Mandakini, its banks always in flower.', 'veda-app-ai-draft', true),
('ramayana-2-95-26', 'en', 'Reaching a swift-flowing, auspicious, mud-free bathing place, they poured water for the king, saying, ''May this be yours.''', 'veda-app-ai-draft', true),
('ramayana-2-95-27', 'en', 'Taking a handful of water, the lord of the earth faced the southern direction and, weeping, said:', 'veda-app-ai-draft', true),
('ramayana-2-95-28', 'en', 'Tiger among kings, may this pure, everlasting water given by me reach you today in the world of the ancestors.', 'veda-app-ai-draft', true),
('ramayana-2-95-29', 'en', 'Then, coming up from the bank of the Mandakini, splendid Raghava, with his brothers, made the food offering for his father.', 'veda-app-ai-draft', true),
('ramayana-2-95-30', 'en', 'Placing ingudi paste mixed with jujube on darbha grass, Rama, deeply grieved, weeping, said:', 'veda-app-ai-draft', true),
('ramayana-2-95-31', 'en', 'Great king, eat this gladly, which is what we eat. For whatever food a person eats, that is the food of his gods.', 'veda-app-ai-draft', true),
('ramayana-2-95-32', 'en', 'Then, coming up from the riverbank by the same path, the tiger among men climbed the mountain with its lovely slopes.', 'veda-app-ai-draft', true),
('ramayana-2-95-33', 'en', 'Reaching the door of the leaf hut, the lord of the earth took both Bharata and Lakshmana by the hands.', 'veda-app-ai-draft', true),
('ramayana-2-95-34', 'en', 'From the sound of the brothers weeping with Vaidehi, there was an echo on the mountain, like lions roaring.', 'veda-app-ai-draft', true),
('ramayana-2-95-35', 'en', 'Hearing the loud sound, Bharata''s soldiers were alarmed and said, ''Surely Bharata has met Rama. This great sound is theirs, grieving for their dead father.''', 'veda-app-ai-draft', true),
('ramayana-2-95-36', 'en', 'Then all of them left their quarters and, with one mind, ran towards the sound, each from where he was.', 'veda-app-ai-draft', true),
('ramayana-2-95-37', 'en', 'Some went on horses, some on elephants, some in decorated chariots, and other tender people went on foot.', 'veda-app-ai-draft', true),
('ramayana-2-95-38', 'en', 'Wanting to see Rama, who had been away only a short time but seemed gone for a long time, all the people went at once to the hermitage.', 'veda-app-ai-draft', true),
('ramayana-2-95-39', 'en', 'Eager to see the brothers'' meeting, they went quickly in many vehicles, noisy with hooves and wheels.', 'veda-app-ai-draft', true),
('ramayana-2-95-40', 'en', 'The ground, struck by the hooves and wheels of many vehicles, gave out a tumultuous sound like the sky when clouds gather.', 'veda-app-ai-draft', true),
('ramayana-2-95-41', 'en', 'Frightened by it, the elephants surrounded by their cows went off to another forest, perfuming the air with their scent.', 'veda-app-ai-draft', true),
('ramayana-2-95-42', 'en', 'Boars, deer, lions, buffalo, bears, monkeys, tigers, gokarnas and gavayas trembled along with the spotted deer.', 'veda-app-ai-draft', true),
('ramayana-2-95-43', 'en', 'Chakravakas, natyuhas, swans, karandavas, plavas, male cuckoos and cranes fled bewildered in every direction.', 'veda-app-ai-draft', true),
('ramayana-2-95-44', 'en', 'The sky was filled with birds frightened by that sound, and the earth was covered with people; both looked splendid then.', 'veda-app-ai-draft', true),
('ramayana-2-95-45', 'en', 'Seeing those people, their eyes full of tears and in deep sorrow, Rama, who knew dharma, embraced them like a father and a mother.', 'veda-app-ai-draft', true),
('ramayana-2-95-46', 'en', 'There the prince embraced some men, and some bowed to him; he greeted all, with their friends and kin, as each deserved.', 'veda-app-ai-draft', true),
('ramayana-2-95-47', 'en', 'Then the sound of those great souls weeping, filling earth and sky, was heard continually in the mountain caves and in every direction, like the sound of drums.', 'veda-app-ai-draft', true),
('ramayana-2-96-1', 'en', 'Vasishtha, putting Dasharatha''s wives in front, approached that place, longing to see Rama.', 'veda-app-ai-draft', true),
('ramayana-2-96-2', 'en', 'As the royal wives walked slowly towards the Mandakini, they saw the bathing place used by Rama and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-96-3', 'en', 'Kausalya, her face tear-stained and parched, said sadly to Sumitra and the other royal women:', 'veda-app-ai-draft', true),
('ramayana-2-96-4', 'en', 'This is the only bathing place in the forest of those helpless ones of untiring deeds, who now suffer, driven from their land.', 'veda-app-ai-draft', true),
('ramayana-2-96-5', 'en', 'Sumitra, from here your son, Sumitra''s son, tirelessly fetches water himself for my son''s sake.', 'veda-app-ai-draft', true),
('ramayana-2-96-6', 'en', 'On darbha grass with tips pointing south, the long-eyed queen saw on the ground the ingudi paste placed for the father.', 'veda-app-ai-draft', true),
('ramayana-2-96-7', 'en', 'Seeing it placed on the ground for his father by grieving Rama, queen Kausalya spoke to all Dasharatha''s wives.', 'veda-app-ai-draft', true),
('ramayana-2-96-8', 'en', 'See this, given properly by Raghava to his father, the great-souled Raghava, lord of the Ikshvakus.', 'veda-app-ai-draft', true),
('ramayana-2-96-9', 'en', 'I do not think this is fitting food for that godlike, great-souled king, who enjoyed every pleasure.', 'veda-app-ai-draft', true),
('ramayana-2-96-10', 'en', 'How does the lord of the earth, like great Indra on earth, who enjoyed the four-cornered earth, eat ingudi paste?', 'veda-app-ai-draft', true),
('ramayana-2-96-11', 'en', 'Nothing in the world seems to me more painful than this, that prosperous Rama must give his father crushed ingudi.', 'veda-app-ai-draft', true),
('ramayana-2-96-12', 'en', 'Seeing the ingudi paste Rama gave his father, how does my heart not break into a thousand pieces from sorrow?', 'veda-app-ai-draft', true),
('ramayana-2-96-13', 'en', 'Her co-wives comforted her in her distress and went on, and in the hermitage they saw Rama, like a god fallen from heaven.', 'veda-app-ai-draft', true),
('ramayana-2-96-14', 'en', 'Seeing Rama deprived of all comforts, the mothers, grieving and worn with sorrow, shed tears aloud.', 'veda-app-ai-draft', true),
('ramayana-2-96-15', 'en', 'Rama, tiger among men, true to his promise, rose and clasped the lovely feet of all his mothers.', 'veda-app-ai-draft', true),
('ramayana-2-96-16', 'en', 'With their soft, pleasant-touching hands and gentle fingers, the long-eyed mothers wiped the dust from Rama''s back.', 'veda-app-ai-draft', true),
('ramayana-2-96-17', 'en', 'Sumitra''s son too, seeing all the mothers, sadly bowed to them slowly and lovingly, right after Rama.', 'veda-app-ai-draft', true),
('ramayana-2-96-18', 'en', 'All the women treated Lakshmana, Dasharatha''s son of auspicious marks, just as they treated Rama.', 'veda-app-ai-draft', true),
('ramayana-2-96-19', 'en', 'Sita too, sorrowful, clasped the feet of her mothers-in-law and stood before them, her eyes full of tears.', 'veda-app-ai-draft', true),
('ramayana-2-96-20', 'en', 'Kausalya embraced her, stricken with sorrow, thin and pale from forest life, as a mother embraces her daughter, and said:', 'veda-app-ai-draft', true),
('ramayana-2-96-21', 'en', 'How has the daughter of the king of Videha, daughter-in-law of Dasharatha and wife of Rama, come to suffer in this lonely forest?', 'veda-app-ai-draft', true),
('ramayana-2-96-22', 'en', '...like a lotus scorched by the sun, a faded water lily, gold covered in dust, or the moon dimmed by clouds...', 'veda-app-ai-draft', true),
('ramayana-2-96-23', 'en', 'Seeing your face, Vaidehi, grief born of the fire-stick of misfortune burns my heart as fire burns its fuel.', 'veda-app-ai-draft', true),
('ramayana-2-96-24', 'en', 'As his mother spoke thus in distress, Raghava, Bharata''s elder brother, went to Vasishtha and clasped his feet.', 'veda-app-ai-draft', true),
('ramayana-2-96-25', 'en', 'Clasping the feet of the fire-like royal priest, rich in splendour, as Indra, lord of gods, clasps Brihaspati''s, Raghava sat down with him.', 'veda-app-ai-draft', true),
('ramayana-2-96-26', 'en', 'Then righteous Bharata, with the ministers, the city''s leaders and the soldiers, and with the people most versed in dharma, sat down below his elder brother.', 'veda-app-ai-draft', true),
('ramayana-2-96-27', 'en', 'Seated there, mighty Bharata, folding his hands, looked at Raghava, blazing with glory though in ascetic''s dress, as great Indra, composed, looks at Prajapati.', 'veda-app-ai-draft', true),
('ramayana-2-96-28', 'en', '''What fine words will Bharata speak to Raghava today, after bowing and honouring him?'' Such keen curiosity arose then among those noble people.', 'veda-app-ai-draft', true),
('ramayana-2-96-29', 'en', 'Raghava, steadfast in truth, great Lakshmana and righteous Bharata, surrounded by friends, shone like the three sacred fires at a sacrifice surrounded by its priests.', 'veda-app-ai-draft', true),
('ramayana-2-97-1', 'en', 'Having comforted his brother who loved his elders, Rama, with his brother Lakshmana, began to question him.', 'veda-app-ai-draft', true),
('ramayana-2-97-2', 'en', 'I want to hear from you why you have come to this place wearing bark, matted hair and deerskin.', 'veda-app-ai-draft', true),
('ramayana-2-97-3', 'en', 'You should tell me everything: why you have left the kingdom and entered this place wearing black deerskin and matted hair.', 'veda-app-ai-draft', true),
('ramayana-2-97-4', 'en', 'Asked this by great Kakutstha, Kaikeyi''s son, holding back his feelings firmly, folded his hands and spoke again.', 'veda-app-ai-draft', true),
('ramayana-2-97-5', 'en', 'Noble one, our father, having done a very hard thing and abandoned you, went to heaven, mighty-armed one, crushed by grief for his son.', 'veda-app-ai-draft', true),
('ramayana-2-97-6', 'en', 'Driven by a woman, my mother Kaikeyi, scorcher of foes, he did this great wrong that destroyed his own good name.', 'veda-app-ai-draft', true),
('ramayana-2-97-7', 'en', 'My mother, not getting the fruit of the kingdom, widowed and wasted by grief, will fall into a terrible hell.', 'veda-app-ai-draft', true),
('ramayana-2-97-8', 'en', 'Be gracious to me, your servant, and be consecrated with the kingdom today, like Indra.', 'veda-app-ai-draft', true),
('ramayana-2-97-9', 'en', 'All these subjects and the widowed mothers have come to you; be gracious to them.', 'veda-app-ai-draft', true),
('ramayana-2-97-10', 'en', 'Giver of honour, take the kingdom by dharma, as is proper by succession and as befits you, and fulfil the wishes of your friends.', 'veda-app-ai-draft', true),
('ramayana-2-97-11', 'en', 'Let the whole earth be no longer widowed, with you as its lord, like an autumn night with the clear moon.', 'veda-app-ai-draft', true),
('ramayana-2-97-12', 'en', 'Begged by me with bowed head along with these ministers, please be gracious to your brother, pupil and servant.', 'veda-app-ai-draft', true),
('ramayana-2-97-13', 'en', 'Tiger among men, you cannot overrule this whole honoured circle of ministers, ancient and inherited from our father.', 'veda-app-ai-draft', true),
('ramayana-2-97-14', 'en', 'Having said this, mighty-armed Bharata, Kaikeyi''s son, in tears, again clasped Rama''s feet with his head.', 'veda-app-ai-draft', true),
('ramayana-2-97-15', 'en', 'Rama embraced his brother Bharata, who was sighing again and again like a rutting elephant, and said this:', 'veda-app-ai-draft', true),
('ramayana-2-97-16', 'en', 'How could someone like you, of good family, full of goodness, radiant and keeping his vows, do wrong for the sake of a kingdom?', 'veda-app-ai-draft', true),
('ramayana-2-97-17', 'en', 'Slayer of foes, I see not even the slightest fault in you. And you should not, out of youthfulness, blame your mother.', 'veda-app-ai-draft', true),
('ramayana-2-97-18', 'en', 'Knower of dharma, best of upholders of dharma, the respect due to a father honoured by the world is due equally to a mother.', 'veda-app-ai-draft', true),
('ramayana-2-97-19', 'en', 'Raghava, told ''Go to the forest'' by these two righteous ones, my mother and father, how could I do otherwise?', 'veda-app-ai-draft', true),
('ramayana-2-97-20', 'en', 'You are to receive the kingdom in Ayodhya, honoured by the world; I am to live in the Dandaka forest wearing bark.', 'veda-app-ai-draft', true),
('ramayana-2-97-21', 'en', 'Having made this division before the world and given his commands, the radiant great king Dasharatha went to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-97-22', 'en', 'That righteous king, teacher of the world, is your authority. You should enjoy the share given you by our father.', 'veda-app-ai-draft', true),
('ramayana-2-97-23', 'en', 'Gentle one, I will live fourteen years in the Dandaka forest and enjoy the share given me by our great-souled father.', 'veda-app-ai-draft', true),
('ramayana-2-97-24', 'en', 'What my great father, honoured by mankind and like the lord of the gods, told me, I consider my highest good, not even endless lordship of all worlds.', 'veda-app-ai-draft', true),
('ramayana-2-98-1', 'en', 'Then the night passed in sorrow for those lions among men, surrounded by their friends, as they grieved.', 'veda-app-ai-draft', true),
('ramayana-2-98-2', 'en', 'When the night had turned to bright morning, the brothers with their friends made offerings and prayers at the Mandakini and came to Rama.', 'veda-app-ai-draft', true),
('ramayana-2-98-3', 'en', 'They sat in silence; no one said anything. Then Bharata, among his friends, spoke to Rama.', 'veda-app-ai-draft', true),
('ramayana-2-98-4', 'en', 'My mother has been satisfied and this kingdom given to me. I give it to you alone; enjoy the kingdom free of rivals.', 'veda-app-ai-draft', true),
('ramayana-2-98-5', 'en', 'Like a dam broken by a great rush of water in the rains, this great piece of a kingdom is hard for anyone but you to hold.', 'veda-app-ai-draft', true),
('ramayana-2-98-6', 'en', 'Lord of the earth, I cannot follow your path, as a donkey cannot follow a horse''s pace, or another bird the flight of Garuda.', 'veda-app-ai-draft', true),
('ramayana-2-98-7', 'en', 'Rama, life is always easy for one on whom others depend, but life is hard for one who depends on others.', 'veda-app-ai-draft', true),
('ramayana-2-98-8', 'en', 'As a tree planted and grown by a man becomes a great tree with a thick trunk, hard for a short man to climb...', 'veda-app-ai-draft', true),
('ramayana-2-98-9', 'en', '...if, when it has flowered, it shows no fruit, he does not enjoy the pleasure for which he raised it.', 'veda-app-ai-draft', true),
('ramayana-2-98-10', 'en', 'Mighty-armed one, this is the parable; you should understand its meaning, if you, our master and best, do not rule us, your servants.', 'veda-app-ai-draft', true),
('ramayana-2-98-11', 'en', 'Great king, let the guilds and all the leaders see you established in the kingdom, subduer of foes, blazing like the sun.', 'veda-app-ai-draft', true),
('ramayana-2-98-12', 'en', 'Kakutstha, let rutting elephants trumpet as they follow you, and let the women of the palace rejoice with calm minds.', 'veda-app-ai-draft', true),
('ramayana-2-98-13', 'en', 'Hearing Bharata''s words as he pleaded with Rama, the various people of the city thought, ''Well said.''', 'veda-app-ai-draft', true),
('ramayana-2-98-14', 'en', 'Seeing famous Bharata so sorrowful and lamenting, self-possessed, disciplined Rama comforted him.', 'veda-app-ai-draft', true),
('ramayana-2-98-15', 'en', 'A person cannot do as he likes; man is not the master. Fate drags him this way and that.', 'veda-app-ai-draft', true),
('ramayana-2-98-16', 'en', 'All gathering ends in scattering, all rising ends in falling, every union ends in separation, and life ends in death.', 'veda-app-ai-draft', true),
('ramayana-2-98-17', 'en', 'As ripe fruit has no fear except of falling, so a person who is born has no fear except of death.', 'veda-app-ai-draft', true),
('ramayana-2-98-18', 'en', 'As a house with strong pillars grows old and collapses, so people sink down, fallen under the power of old age and death.', 'veda-app-ai-draft', true),
('ramayana-2-98-19', 'en', 'The days and nights pass for all living beings here, quickly wearing away their lifespans, as the sun''s rays dry up water in summer.', 'veda-app-ai-draft', true),
('ramayana-2-98-20', 'en', 'Grieve for yourself; why grieve for another? Your life is shrinking whether you stay or go.', 'veda-app-ai-draft', true),
('ramayana-2-98-21', 'en', 'Death walks with us, death sits with us, and having gone a very long way, death returns with us.', 'veda-app-ai-draft', true),
('ramayana-2-98-22', 'en', 'Wrinkles appear on the limbs and the hair turns white; worn by old age, what can a person do?', 'veda-app-ai-draft', true),
('ramayana-2-98-23', 'en', 'People rejoice when the sun rises and rejoice when it sets, but they do not notice their own life wasting away.', 'veda-app-ai-draft', true),
('ramayana-2-98-24', 'en', 'They are glad to see the start of each new season, yet with the turning of the seasons, living beings'' lives are used up.', 'veda-app-ai-draft', true),
('ramayana-2-98-25', 'en', 'As two pieces of wood meet in the great ocean and, having met, drift apart after some time...', 'veda-app-ai-draft', true),
('ramayana-2-98-26', 'en', '...so wives, sons, kin and wealth come together and then run apart; their separation is certain.', 'veda-app-ai-draft', true),
('ramayana-2-98-27', 'en', 'No living being here can escape its nature, so one who grieves for the dead has no power over it.', 'veda-app-ai-draft', true),
('ramayana-2-98-28', 'en', 'As someone standing on the road might say to a passing caravan, ''I too will come along behind you''...', 'veda-app-ai-draft', true),
('ramayana-2-98-29', 'en', '...so, on the sure path taken by our fathers and grandfathers, why should one grieve on reaching it, since there is no way to avoid it?', 'veda-app-ai-draft', true),
('ramayana-2-98-30', 'en', 'As age slips away like a river that does not return, the self should be set on true happiness, for living beings are meant to share in happiness.', 'veda-app-ai-draft', true),
('ramayana-2-98-31', 'en', 'Our righteous father, lord of the earth, cleansed of sin by all the good sacrifices with gifts given, has gone to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-98-32', 'en', 'By supporting his dependants well, by protecting his people, and by gaining wealth through dharma, our father has gone to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-98-33', 'en', 'Having performed many kinds of sacrifices, enjoyed abundant pleasures and reached a great age, the lord of the earth has gone to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-98-34', 'en', 'Our father, having cast off his old human body, has reached divine glory and roams in Brahma''s world.', 'veda-app-ai-draft', true),
('ramayana-2-98-35', 'en', 'No wise person, learned and very intelligent, like you or me, should grieve for him.', 'veda-app-ai-draft', true),
('ramayana-2-98-36', 'en', 'These many kinds of grief, lament and weeping should be avoided by a steady and wise person in every situation.', 'veda-app-ai-draft', true),
('ramayana-2-98-37', 'en', 'Be calm, do not grieve; go and live in that city, best of speakers, as our self-controlled father appointed you.', 'veda-app-ai-draft', true),
('ramayana-2-98-38', 'en', 'I too will carry out my noble father''s command where that doer of good deeds has appointed me.', 'veda-app-ai-draft', true),
('ramayana-2-98-39', 'en', 'Subduer of foes, it is not right for me to abandon his command. You too must always respect it; he was our kinsman and our father.', 'veda-app-ai-draft', true),
('ramayana-2-98-40', 'en', 'When Rama had finished these meaningful words, righteous Bharata spoke wonderful, righteous words to righteous Rama.', 'veda-app-ai-draft', true),
('ramayana-2-98-41', 'en', 'Subduer of foes, who in the world is like you? Sorrow does not trouble you, nor does pleasure excite you.', 'veda-app-ai-draft', true),
('ramayana-2-98-42', 'en', 'You are respected by elders and you ask them about your doubts. To you the living and the dead, what exists and what does not, are the same.', 'veda-app-ai-draft', true),
('ramayana-2-98-43', 'en', 'One who has gained such understanding, how could he be troubled by anything? Having met such misfortune, he should not despair.', 'veda-app-ai-draft', true),
('ramayana-2-98-44', 'en', 'Raghava, you are godlike in strength, great-souled, true to your promise, all-knowing, all-seeing and wise.', 'veda-app-ai-draft', true),
('ramayana-2-98-45', 'en', 'Unbearable sorrow should not overcome you, endowed with such virtues and knowing birth and death.', 'veda-app-ai-draft', true),
('ramayana-2-98-46', 'en', 'The wrong my petty mother did for my sake while I was away is not what I wanted. Be gracious to me.', 'veda-app-ai-draft', true),
('ramayana-2-98-47', 'en', 'I am bound by the bond of dharma; that is why I do not punish my mother here severely, though she deserves punishment for her wrong.', 'veda-app-ai-draft', true),
('ramayana-2-98-48', 'en', 'How could I, born of Dasharatha of pure family and deeds, knowing dharma, do a most unrighteous, despicable deed?', 'veda-app-ai-draft', true),
('ramayana-2-98-49', 'en', 'Because he was my teacher, a performer of rites, elderly, king, departed and my father, I will not blame my father before the assembly, for he is like a god.', 'veda-app-ai-draft', true),
('ramayana-2-98-50', 'en', 'Knower of dharma, who that knows dharma would do such a sinful deed, lacking both dharma and wealth, wishing to please a woman?', 'veda-app-ai-draft', true),
('ramayana-2-98-51', 'en', 'There is an old saying that beings become confused at the time of their end; by acting thus, the king made that saying visible in the world.', 'veda-app-ai-draft', true),
('ramayana-2-98-52', 'en', 'With good purpose, please undo the wrong our father did from anger, confusion and rashness.', 'veda-app-ai-draft', true),
('ramayana-2-98-53', 'en', 'A son who rightly considers his father''s mistakes is held in the world to be a true child; otherwise he is the opposite.', 'veda-app-ai-draft', true),
('ramayana-2-98-54', 'en', 'So be a true son; do not approve of our father''s wrong deed, condemned in the world by the wise.', 'veda-app-ai-draft', true),
('ramayana-2-98-55', 'en', 'Save Kaikeyi, me, our father, our friends and kin, and all the townspeople and villagers: save all of this.', 'veda-app-ai-draft', true),
('ramayana-2-98-56', 'en', 'Where is the forest and where the warrior''s duty? Where matted hair and where ruling? You should not do such contradictory things.', 'veda-app-ai-draft', true),
('ramayana-2-98-57', 'en', 'If you want to practise the dharma that comes from hardship, then bear hardship by protecting the four classes with dharma.', 'veda-app-ai-draft', true),
('ramayana-2-98-58', 'en', 'Knower of dharma, the wise say that of the four stages of life, the householder''s stage is the best. How can you give it up?', 'veda-app-ai-draft', true),
('ramayana-2-98-59', 'en', 'In learning, in rank and in birth I am a child compared to you. How can I protect the earth while you are here?', 'veda-app-ai-draft', true),
('ramayana-2-98-60', 'en', 'I am a child, lacking intelligence and virtue and lower in rank. Without you I cannot carry on.', 'veda-app-ai-draft', true),
('ramayana-2-98-61', 'en', 'Knower of dharma, rule this whole ancestral kingdom, calm and free of enemies, by your own dharma, with your kin.', 'veda-app-ai-draft', true),
('ramayana-2-98-62', 'en', 'Knower of dharma, let the priests with Vasishtha, skilled in mantras, consecrate you right here with your kin.', 'veda-app-ai-draft', true),
('ramayana-2-98-63', 'en', 'Consecrated by us, go to Ayodhya to protect it, having conquered the worlds by your strength like Indra with the Maruts.', 'veda-app-ai-draft', true),
('ramayana-2-98-64', 'en', 'Paying off the three debts, burning up your enemies, satisfying your friends with their wishes, rule me here yourself.', 'veda-app-ai-draft', true),
('ramayana-2-98-65', 'en', 'Noble one, let your friends rejoice today at your consecration, and let your enemies flee in fear to the ten directions.', 'veda-app-ai-draft', true),
('ramayana-2-98-66', 'en', 'Bull among men, wipe away the curses on my mother, and protect our revered father from sin today.', 'veda-app-ai-draft', true),
('ramayana-2-98-67', 'en', 'I beg you with my head bowed: have compassion on me and on all your kin, as the great Lord does on all beings.', 'veda-app-ai-draft', true),
('ramayana-2-98-68', 'en', 'Or if you turn your back on this and go from here to the forest, I will go with you too.', 'veda-app-ai-draft', true),
('ramayana-2-98-69', 'en', 'Yet Rama, lord of the earth, though entreated with bowed head by the anguished Bharata, steadfast and firm in his father''s word, did not decide to go back.', 'veda-app-ai-draft', true),
('ramayana-2-98-70', 'en', 'Seeing that wonderful steadiness in Raghava, the people felt sorrow and joy together: sad that he would not go to Ayodhya, glad to see him so firm in his promise.', 'veda-app-ai-draft', true),
('ramayana-2-98-71', 'en', 'The priests, the leaders of merchant guilds, and the mothers, faint and tearful, praised Bharata for speaking so, and bowing to Rama, joined him in pleading.', 'veda-app-ai-draft', true),
('ramayana-2-99-1', 'en', 'When Bharata spoke like this again, glorious Rama, Lakshmana''s elder brother, highly honoured among his kin, replied.', 'veda-app-ai-draft', true),
('ramayana-2-99-2', 'en', 'These words of yours are fitting for a son born of Dasharatha, best of kings, and of Kaikeyi.', 'veda-app-ai-draft', true),
('ramayana-2-99-3', 'en', 'Long ago, brother, when our father married your mother, he promised your grandfather the kingdom as her bride-price.', 'veda-app-ai-draft', true),
('ramayana-2-99-4', 'en', 'And in the war between gods and demons, the king, pleased and won over, gave your mother a boon.', 'veda-app-ai-draft', true),
('ramayana-2-99-5', 'en', 'Then your famous mother, holding him to his word, asked the best of men for two boons.', 'veda-app-ai-draft', true),
('ramayana-2-99-6', 'en', 'The kingdom for you, tiger among men, and my exile. Bound by his word, the king granted her those boons.', 'veda-app-ai-draft', true),
('ramayana-2-99-7', 'en', 'So I too, bull among men, have been appointed by our father to live fourteen years in the forest as part of the boon.', 'veda-app-ai-draft', true),
('ramayana-2-99-8', 'en', 'So I have come to this lonely forest with Lakshmana and Sita, without complaint, keeping our father''s word true.', 'veda-app-ai-draft', true),
('ramayana-2-99-9', 'en', 'You too should quickly make our father, the king of kings, true to his word by accepting consecration.', 'veda-app-ai-draft', true),
('ramayana-2-99-10', 'en', 'Bharata, free our lord the king from his debt for my sake; save our father, knower of dharma, and make your mother happy.', 'veda-app-ai-draft', true),
('ramayana-2-99-11', 'en', 'Dear one, we hear of a famous verse sung long ago by Gaya, while sacrificing at Gaya for his ancestors:', 'veda-app-ai-draft', true),
('ramayana-2-99-12', 'en', 'Because a son saves his father from the hell called Put, or because he protects his ancestors, he is called putra, son.', 'veda-app-ai-draft', true),
('ramayana-2-99-13', 'en', 'One should wish for many virtuous, learned sons, so that of all of them, at least one may go to Gaya.', 'veda-app-ai-draft', true),
('ramayana-2-99-14', 'en', 'All the royal sages were convinced of this, joy of kings. So, best of men, lord, save our father from hell.', 'veda-app-ai-draft', true),
('ramayana-2-99-15', 'en', 'Go to Ayodhya, Bharata, hero, and win the hearts of the people, with Shatrughna and all the Brahmins.', 'veda-app-ai-draft', true),
('ramayana-2-99-16', 'en', 'I too will enter the Dandaka forest without delay, king, together with these two, Vaidehi and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-99-17', 'en', 'Bharata, be king of men yourself; I will be emperor of the forest beasts. Go joyfully to the fine city today, and I too will joyfully enter the Dandaka forest.', 'veda-app-ai-draft', true),
('ramayana-2-99-18', 'en', 'Let a parasol cast cool shade on your head, Bharata, keeping off the sun''s light. I too will happily take refuge in the even finer shade of these forest trees.', 'veda-app-ai-draft', true),
('ramayana-2-99-19', 'en', 'Shatrughna, of fine mind, is your helper; Sumitra''s son is known as my chief friend. We four fine sons will keep our father true; do not despair, Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-100-1', 'en', 'As Rama was comforting Bharata, Jabali, a learned Brahmin, spoke these words, contrary to dharma, to Rama who knew dharma.', 'veda-app-ai-draft', true),
('ramayana-2-100-2', 'en', 'Well, Raghava, let your mind not be so pointless, like an ordinary man''s, noble-minded ascetic.', 'veda-app-ai-draft', true),
('ramayana-2-100-3', 'en', 'Who is anyone''s kinsman? What is anyone to gain from another? A creature is born alone and dies alone.', 'veda-app-ai-draft', true),
('ramayana-2-100-4', 'en', 'So, Rama, a man who clings to ''mother'' and ''father'' should be thought mad, for no one belongs to anyone.', 'veda-app-ai-draft', true),
('ramayana-2-100-5', 'en', 'Just as a man going to another village stays somewhere and, leaving that lodging, sets out the next day...', 'veda-app-ai-draft', true),
('ramayana-2-100-6', 'en', '...so for people, father, mother, home and wealth are only lodgings, Kakutstha. The good do not cling to them.', 'veda-app-ai-draft', true),
('ramayana-2-100-7', 'en', 'Best of men, you should not give up your ancestral kingdom to take a hard, uneven, thorny wrong road.', 'veda-app-ai-draft', true),
('ramayana-2-100-8', 'en', 'Have yourself crowned in prosperous Ayodhya. The city awaits you, wearing a single braid like a woman in mourning.', 'veda-app-ai-draft', true),
('ramayana-2-100-9', 'en', 'Prince, enjoy precious royal pleasures and amuse yourself in Ayodhya as Indra does in heaven.', 'veda-app-ai-draft', true),
('ramayana-2-100-10', 'en', 'Dasharatha is nothing to you, and you are nothing to him. He was one king and you are another; so do as you are told.', 'veda-app-ai-draft', true),
('ramayana-2-100-11', 'en', 'That king has gone where he had to go. This is the way of mortals; you are troubling yourself for nothing.', 'veda-app-ai-draft', true),
('ramayana-2-100-12', 'en', 'I pity those who are devoted to duty and wealth, not the others. They suffer here and perish after death.', 'veda-app-ai-draft', true),
('ramayana-2-100-13', 'en', 'People busy themselves with rites for the ancestors and gods. See the waste of food! What will a dead man eat?', 'veda-app-ai-draft', true),
('ramayana-2-100-14', 'en', 'If what one person eats here went into another''s body, one could give a shraddha for a traveller, and he would need no food on the road.', 'veda-app-ai-draft', true),
('ramayana-2-100-15', 'en', 'These texts that say ''sacrifice, give, be consecrated, practise austerity, renounce'' were made by clever people to get gifts.', 'veda-app-ai-draft', true),
('ramayana-2-100-16', 'en', 'Very wise one, make up your mind that there is nothing beyond. Stand by what is before your eyes and put what is unseen behind you.', 'veda-app-ai-draft', true),
('ramayana-2-100-17', 'en', 'Following the view of the wise, which shows the way for all, accept the kingdom, being won over by Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-101-1', 'en', 'Hearing Jabali''s words, Rama, best of the truthful, replied with sound reasoning and his own unshaken understanding.', 'veda-app-ai-draft', true),
('ramayana-2-101-2', 'en', 'What you have said here, wishing to please me, is wrong though it looks right, harmful though it seems wholesome.', 'veda-app-ai-draft', true),
('ramayana-2-101-3', 'en', 'A man without limits, given to wicked conduct, whose character is seen to be broken, wins no respect among the good.', 'veda-app-ai-draft', true),
('ramayana-2-101-4', 'en', 'Whether a man is of good family or not, brave or merely boastful, pure or impure, it is his conduct alone that shows it.', 'veda-app-ai-draft', true),
('ramayana-2-101-5', 'en', 'The ignoble can look noble, the impure look pure, the unworthy look worthy, and the ill-behaved look well-behaved.', 'veda-app-ai-draft', true),
('ramayana-2-101-6', 'en', 'If I were to take up this unrighteousness dressed as righteousness, which confuses the world, abandoning what is good and free of proper rites...', 'veda-app-ai-draft', true),
('ramayana-2-101-7', 'en', '...what thinking person who can tell right from wrong would respect me in the world, a man of bad conduct who corrupts the world?', 'veda-app-ai-draft', true),
('ramayana-2-101-8', 'en', 'Whose conduct would I follow, and how would I reach heaven, living this way, having broken my promise?', 'veda-app-ai-draft', true),
('ramayana-2-101-9', 'en', 'This whole world would follow its desires, for as kings behave, so behave their people.', 'veda-app-ai-draft', true),
('ramayana-2-101-10', 'en', 'Truth and kindness are the eternal conduct of kings. So the kingdom is founded on truth; the world rests on truth.', 'veda-app-ai-draft', true),
('ramayana-2-101-11', 'en', 'Sages and gods alike have honoured truth above all. One who speaks the truth reaches the highest state in this world.', 'veda-app-ai-draft', true),
('ramayana-2-101-12', 'en', 'People shrink from a liar as from a snake. Truth is the highest dharma in the world and is called the root of heaven.', 'veda-app-ai-draft', true),
('ramayana-2-101-13', 'en', 'Truth is the lord of the world; prosperity rests on truth. All things are rooted in truth; there is nothing higher than truth.', 'veda-app-ai-draft', true),
('ramayana-2-101-14', 'en', 'Giving, sacrifice, offerings, austerities performed, and the Vedas themselves are founded on truth; so one should be devoted to truth.', 'veda-app-ai-draft', true),
('ramayana-2-101-15', 'en', 'One person protects the world, one protects a family; one sinks into hell, one is honoured in heaven.', 'veda-app-ai-draft', true),
('ramayana-2-101-16', 'en', 'So why should I not follow my father''s command? I am true to my promise, bound by truth to truth.', 'veda-app-ai-draft', true),
('ramayana-2-101-17', 'en', 'Neither from greed nor confusion nor ignorance, darkened in mind, will I break the dam of truth, true to my promise to my elder.', 'veda-app-ai-draft', true),
('ramayana-2-101-18', 'en', 'We have heard that neither gods nor ancestors accept offerings from one who is untrue to his word, fickle and unsteady.', 'veda-app-ai-draft', true),
('ramayana-2-101-19', 'en', 'I myself see truth as this inner dharma. This burden borne by the good is honoured for that reason.', 'veda-app-ai-draft', true),
('ramayana-2-101-20', 'en', 'I will give up the ''warrior''s dharma'' you describe, which is unrighteousness dressed as dharma, followed by petty, cruel, greedy evildoers.', 'veda-app-ai-draft', true),
('ramayana-2-101-21', 'en', 'A person does wrong with the body after deciding it in the mind, and speaks falsehood with the tongue: sinful action is of three kinds.', 'veda-app-ai-draft', true),
('ramayana-2-101-22', 'en', 'Land, fame, glory and fortune seek out a person and follow him even to heaven; so one should hold to truth alone.', 'veda-app-ai-draft', true),
('ramayana-2-101-23', 'en', 'What you, having thought it over, told me with persuasive words, ''Do this good thing'', would be most ignoble.', 'veda-app-ai-draft', true),
('ramayana-2-101-24', 'en', 'How, having promised my elder to live in the forest, could I follow Bharata''s words and abandon my elder''s?', 'veda-app-ai-draft', true),
('ramayana-2-101-25', 'en', 'I made a firm promise in the presence of my elder, and queen Kaikeyi was then delighted.', 'veda-app-ai-draft', true),
('ramayana-2-101-26', 'en', 'Living in the forest like this, pure and restrained in diet, satisfying ancestors and gods with holy roots, flowers and fruit...', 'veda-app-ai-draft', true),
('ramayana-2-101-27', 'en', '...with my five senses content, I will live my life, sincere, full of faith, and able to tell right from wrong.', 'veda-app-ai-draft', true),
('ramayana-2-101-28', 'en', 'Having come to this world of action, one should do good deeds. Agni, Vayu and Soma share in the fruits of actions.', 'veda-app-ai-draft', true),
('ramayana-2-101-29', 'en', 'Having performed a hundred sacrifices, the king of gods went to heaven; by practising fierce austerities the great sages went to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-101-30', 'en', 'Truth, dharma, courage, compassion for all beings, kind speech, and honouring Brahmins, gods and guests: the good call this the path to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-101-31', 'en', 'Devoted to dharma, keeping company with the good, radiant, chiefly given to generosity, harmless and free of impurity, the foremost sages are worshipped in the world.', 'veda-app-ai-draft', true),
('ramayana-2-102-1', 'en', 'Seeing Rama angry, Vasishtha replied: ''Jabali too knows the coming and going of this world. He spoke these words only because he wanted to bring you back.''', 'veda-app-ai-draft', true),
('ramayana-2-102-2', 'en', 'Lord of the world, hear from me how this world came to be. All was water, in which the earth was formed. Then self-born Brahma arose, with the gods.', 'veda-app-ai-draft', true),
('ramayana-2-102-3', 'en', 'Then, becoming a boar, he raised up the earth and created the whole world with his self-disciplined sons.', 'veda-app-ai-draft', true),
('ramayana-2-102-4', 'en', 'Brahma, arising from space, eternal, everlasting and imperishable: from him was born Marichi, and Kashyapa was Marichi''s son.', 'veda-app-ai-draft', true),
('ramayana-2-102-5', 'en', 'Vivasvat was born of Kashyapa, and Manu is known as Vivasvat''s son. He was the first Prajapati, and Ikshvaku was Manu''s son.', 'veda-app-ai-draft', true),
('ramayana-2-102-6', 'en', 'Know that Ikshvaku, to whom Manu first gave this prosperous earth, was the first king in Ayodhya.', 'veda-app-ai-draft', true),
('ramayana-2-102-7', 'en', 'Ikshvaku''s glorious son was known as Kukshi, and from Kukshi was born the hero Vikukshi.', 'veda-app-ai-draft', true),
('ramayana-2-102-8', 'en', 'Vikukshi''s son was radiant, mighty Bana, and Bana''s son was mighty-armed, famous Anaranya.', 'veda-app-ai-draft', true),
('ramayana-2-102-9', 'en', 'Best of the good, while great king Anaranya ruled there was no drought, no famine and no thief.', 'veda-app-ai-draft', true),
('ramayana-2-102-10', 'en', 'From Anaranya came the mighty king Prithu, and from Prithu the great king Trishanku, a hero who went to heaven in his body because of his truthful words.', 'veda-app-ai-draft', true),
('ramayana-2-102-11', 'en', 'Trishanku''s son was famous Dhundhumara, and from Dhundhumara was born radiant Yuvanashva.', 'veda-app-ai-draft', true),
('ramayana-2-102-12', 'en', 'Yuvanashva''s son was glorious Mandhata, and from Mandhata came radiant Susandhi.', 'veda-app-ai-draft', true),
('ramayana-2-102-13', 'en', 'Susandhi had two sons, Dhruvasandhi and Prasenajit. From Dhruvasandhi came famous Bharata, slayer of foes.', 'veda-app-ai-draft', true),
('ramayana-2-102-14', 'en', 'From mighty-armed Bharata was born Asita, whose enemies were rival kings: the Haihayas, the Talajanghas and the brave Shashabindus.', 'veda-app-ai-draft', true),
('ramayana-2-102-15', 'en', 'Facing them all in battle, the king was driven out. He became a sage, happy on a lovely mountain, and it is said his two wives were pregnant.', 'veda-app-ai-draft', true),
('ramayana-2-102-16', 'en', 'Chyavana of the Bhrigu line lived on the Himalaya. Kalindi went to that sage and bowed to him.', 'veda-app-ai-draft', true),
('ramayana-2-102-17', 'en', 'The Brahmin blessed her, who wished for a boon at her son''s birth. Then the queen went home and gave birth to a son.', 'veda-app-ai-draft', true),
('ramayana-2-102-18', 'en', 'Her co-wife had given her poison to kill the unborn child; born together with that poison (gara), he became Sagara.', 'veda-app-ai-draft', true),
('ramayana-2-102-19', 'en', 'That king named Sagara had the ocean dug out; having sacrificed at the festival, he terrified these people with his force.', 'veda-app-ai-draft', true),
('ramayana-2-102-20', 'en', 'We have heard that Asamanja was Sagara''s son; because he did evil deeds, his father banished him while he was still alive.', 'veda-app-ai-draft', true),
('ramayana-2-102-21', 'en', 'Asamanja''s son was mighty Amshuman; Dilipa was Amshuman''s son, and Bhagiratha was Dilipa''s.', 'veda-app-ai-draft', true),
('ramayana-2-102-22', 'en', 'From Bhagiratha came Kakutstha, after whom the Kakutsthas are named; Kakutstha''s son was Raghu, from whom comes the name Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-102-23', 'en', 'Raghu''s radiant son, grown great, became a man-eater, known on earth as Kalmashapada Saudasa.', 'veda-app-ai-draft', true),
('ramayana-2-102-24', 'en', 'Kalmashapada''s son was the famous Shankhana, who met that power and perished with his army.', 'veda-app-ai-draft', true),
('ramayana-2-102-25', 'en', 'Shankhana''s son was brave, glorious Sudarshana; Sudarshana''s was Agnivarna, and Agnivarna''s was Shighraga.', 'veda-app-ai-draft', true),
('ramayana-2-102-26', 'en', 'Shighraga''s son was Maru, Maru''s son Prashushruka, and Prashushruka''s son was radiant Ambarisha.', 'veda-app-ai-draft', true),
('ramayana-2-102-27', 'en', 'Ambarisha''s son was Nahusha, true in valour; Nahusha''s son was the supremely righteous Nabhaga.', 'veda-app-ai-draft', true),
('ramayana-2-102-28', 'en', 'Nabhaga had two sons, Aja and Suvrata. Aja''s son was the righteous King Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-2-102-29', 'en', 'You are his eldest heir, renowned as Rama. So take your own kingdom and look after the world, king.', 'veda-app-ai-draft', true),
('ramayana-2-102-30', 'en', 'Among all the Ikshvakus the firstborn becomes king. While the firstborn lives, a younger son is not consecrated; the eldest is.', 'veda-app-ai-draft', true),
('ramayana-2-102-31', 'en', 'You should not today abandon your own eternal family dharma of the Raghavas. Famous one, rule the earth, rich in jewels and many realms, as your father did.', 'veda-app-ai-draft', true),
('ramayana-2-103-1', 'en', 'Having said this to Rama, Vasishtha, the royal priest, spoke further words full of dharma.', 'veda-app-ai-draft', true),
('ramayana-2-103-2', 'en', 'Kakutstha, a person born here has three gurus: the teacher, the father and the mother.', 'veda-app-ai-draft', true),
('ramayana-2-103-3', 'en', 'The father gives birth to a person, bull among men, and the teacher gives wisdom; so the teacher is called a guru.', 'veda-app-ai-draft', true),
('ramayana-2-103-4', 'en', 'I am your father''s teacher and yours too, scorcher of foes. By doing as I say you will not stray from the path of the good.', 'veda-app-ai-draft', true),
('ramayana-2-103-5', 'en', 'These assemblies and guilds have come; by practising dharma toward them, dear one, you will not stray from the path of the good.', 'veda-app-ai-draft', true),
('ramayana-2-103-6', 'en', 'You should not disobey your aged, righteous mother. By doing as she asks, you will not stray from the path of the good.', 'veda-app-ai-draft', true),
('ramayana-2-103-7', 'en', 'Raghava, valiant in truth and dharma, by doing as Bharata begs, you will not go against yourself.', 'veda-app-ai-draft', true),
('ramayana-2-103-8', 'en', 'Addressed so sweetly by his teacher, Raghava, bull among men, replied to Vasishtha, who was seated.', 'veda-app-ai-draft', true),
('ramayana-2-103-9', 'en', 'What mother and father always do for their child cannot easily be repaid, all that a mother and father have done...', 'veda-app-ai-draft', true),
('ramayana-2-103-10', 'en', '...giving what they can, bathing and clothing us, always speaking kindly and raising us.', 'veda-app-ai-draft', true),
('ramayana-2-103-11', 'en', 'King Dasharatha, who begot me, is my father. What I promised him will not be made false.', 'veda-app-ai-draft', true),
('ramayana-2-103-12', 'en', 'When Rama said this, generous Bharata, deeply troubled, immediately spoke to the charioteer.', 'veda-app-ai-draft', true),
('ramayana-2-103-13', 'en', 'Charioteer, quickly spread kusha grass for me here on the ground. I will sit facing my noble brother until he is gracious to me.', 'veda-app-ai-draft', true),
('ramayana-2-103-14', 'en', 'Without food and without light, like a Brahmin robbed of his wealth, I will lie before the hut until he returns.', 'veda-app-ai-draft', true),
('ramayana-2-103-15', 'en', 'Seeing Sumantra look towards Rama, he, troubled, brought kusha grass himself and spread it on the ground.', 'veda-app-ai-draft', true),
('ramayana-2-103-16', 'en', 'Radiant Rama, best of royal sages, said to him: ''Dear Bharata, what am I doing that you would sit fasting against me?''', 'veda-app-ai-draft', true),
('ramayana-2-103-17', 'en', 'A Brahmin may sit on one side to restrain people here, but the rule of sitting in protest does not apply to consecrated Kshatriyas.', 'veda-app-ai-draft', true),
('ramayana-2-103-18', 'en', 'Rise, tiger among men, give up this harsh vow, and go quickly from here to Ayodhya, the best of cities, Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-103-19', 'en', 'Still seated, Bharata looked all around at the townspeople and villagers and said, ''Why do you not instruct my noble brother?''', 'veda-app-ai-draft', true),
('ramayana-2-103-20', 'en', 'The townspeople and villagers said to the great soul: ''We know Kakutstha; Raghava speaks rightly.''', 'veda-app-ai-draft', true),
('ramayana-2-103-21', 'en', 'He too, the fortunate one, stands by his father''s word. That is why we cannot easily turn him back.', 'veda-app-ai-draft', true),
('ramayana-2-103-22', 'en', 'Hearing their words, Rama said: ''Understand these words of your friends who see by dharma.''', 'veda-app-ai-draft', true),
('ramayana-2-103-23', 'en', 'Having heard both sides and considered them well, Raghava, rise, mighty-armed one, and touch me and touch water.', 'veda-app-ai-draft', true),
('ramayana-2-103-24', 'en', 'Then, rising and touching water, Bharata said: ''Let the assemblies, ministers and guilds hear me.''', 'veda-app-ai-draft', true),
('ramayana-2-103-25', 'en', 'I did not ask my father for the kingdom, nor did I direct my mother. I know my noble brother Raghava as supremely knowing dharma.', 'veda-app-ai-draft', true),
('ramayana-2-103-26', 'en', 'If someone must live in the forest and our father''s word be carried out, I myself will live fourteen years in the forest.', 'veda-app-ai-draft', true),
('ramayana-2-103-27', 'en', 'Amazed at his brother''s sincere words, righteous Rama looked at the townspeople and villagers and said:', 'veda-app-ai-draft', true),
('ramayana-2-103-28', 'en', 'What my father sold, pledged or bought while he lived cannot be undone by me or by Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-103-29', 'en', 'I must not use a substitute in the forest exile; that would be shameful. What Kaikeyi asked was proper, and my father did right.', 'veda-app-ai-draft', true),
('ramayana-2-103-30', 'en', 'I know Bharata is patient and honours his elders. Everything good is in this great soul, true to his promise.', 'veda-app-ai-draft', true),
('ramayana-2-103-31', 'en', 'When I return from the forest, with this righteous brother I will be the best lord of the earth.', 'veda-app-ai-draft', true),
('ramayana-2-103-32', 'en', 'The king was asked by Kaikeyi, and I have fulfilled that word. Free our father, the lord of the earth, from untruth.', 'veda-app-ai-draft', true),
('ramayana-2-104-1', 'en', 'Seeing that thrilling meeting of the two brothers of matchless splendour, the great sages gathered there were amazed.', 'veda-app-ai-draft', true),
('ramayana-2-104-2', 'en', 'The hosts of sages, invisible, the perfected ones and the great seers praised the two great-souled brothers, the Kakutsthas.', 'veda-app-ai-draft', true),
('ramayana-2-104-3', 'en', 'Blessed is he whose two sons know dharma and are valiant in dharma. Hearing their conversation, we are filled with longing.', 'veda-app-ai-draft', true),
('ramayana-2-104-4', 'en', 'Then the hosts of sages, wishing for the death of ten-headed Ravana, gathered and quickly said to Bharata, tiger among kings:', 'veda-app-ai-draft', true),
('ramayana-2-104-5', 'en', 'You who are well born, very wise, of great conduct and great fame: if you care for your father, you should accept Rama''s word.', 'veda-app-ai-draft', true),
('ramayana-2-104-6', 'en', 'We wish Rama always to be free of debt to his father. Because he was free of debt to Kaikeyi, Dasharatha went to heaven.', 'veda-app-ai-draft', true),
('ramayana-2-104-7', 'en', 'Having said this, the gandharvas, great sages and royal sages all went to their own places.', 'veda-app-ai-draft', true),
('ramayana-2-104-8', 'en', 'Delighted by those auspicious words, handsome Rama, his face glowing with joy, honoured those sages.', 'veda-app-ai-draft', true),
('ramayana-2-104-9', 'en', 'His limbs trembling, with a faltering voice, Bharata folded his hands and spoke to Raghava again.', 'veda-app-ai-draft', true),
('ramayana-2-104-10', 'en', 'Kakutstha, considering the duty of kings and the continuity of the family dharma, you should grant my request and my mother''s.', 'veda-app-ai-draft', true),
('ramayana-2-104-11', 'en', 'I alone cannot protect this great kingdom, nor please the devoted townspeople and villagers.', 'veda-app-ai-draft', true),
('ramayana-2-104-12', 'en', 'Our kin, warriors, friends and allies all long for you, as farmers long for rain.', 'veda-app-ai-draft', true),
('ramayana-2-104-13', 'en', 'Very wise one, accept this kingdom and set it in order. Kakutstha, you are able to protect the world.', 'veda-app-ai-draft', true),
('ramayana-2-104-14', 'en', 'Having said this, Bharata fell at his brother''s feet and earnestly begged Rama, speaking lovingly.', 'veda-app-ai-draft', true),
('ramayana-2-104-15', 'en', 'Taking his dark, lotus-eyed brother on his lap, Rama, with a voice like an excited swan, said:', 'veda-app-ai-draft', true),
('ramayana-2-104-16', 'en', 'Dear one, this understanding, both natural and learned, has come to you; you are well able to protect even the whole earth.', 'veda-app-ai-draft', true),
('ramayana-2-104-17', 'en', 'Consult with your ministers, friends and wise counsellors, and have all tasks done, even very great ones.', 'veda-app-ai-draft', true),
('ramayana-2-104-18', 'en', 'The moon may lose its light, the Himalaya its snow, the ocean may cross its shore, but I will not break my father''s promise.', 'veda-app-ai-draft', true),
('ramayana-2-104-19', 'en', 'Dear one, whether your mother did this out of desire or greed, do not hold it in your mind; treat her as a mother.', 'veda-app-ai-draft', true),
('ramayana-2-104-20', 'en', 'As he said this, Bharata spoke to Kausalya''s son, who shone like the sun and looked lovely as the new moon:', 'veda-app-ai-draft', true),
('ramayana-2-104-21', 'en', 'Noble one, step onto these gold-decorated sandals. They will secure the welfare of the whole world.', 'veda-app-ai-draft', true),
('ramayana-2-104-22', 'en', 'The radiant tiger among men stepped onto the sandals, stepped off again, and gave them to great-souled Bharata.', 'veda-app-ai-draft', true),
('ramayana-2-104-23', 'en', 'Mighty Bharata, knowing dharma, took those fine sandals, walked reverently around Raghava and placed them on the head of the finest elephant.', 'veda-app-ai-draft', true),
('ramayana-2-104-24', 'en', 'Then Rama, who increases the Raghu line, steady in his duty like the immovable Himalaya, honoured the people, elders, ministers and his two younger brothers in order, and sent them away.', 'veda-app-ai-draft', true),
('ramayana-2-104-25', 'en', 'The mothers, their throats choked with tears, could not bid him farewell in their sorrow. Rama bowed to all his mothers and went weeping into his hut.', 'veda-app-ai-draft', true),
('ramayana-2-105-1', 'en', 'Then Bharata, placing the sandals on his head, joyfully mounted his chariot with Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-105-2', 'en', 'Vasishtha, Vamadeva, the steadfast Jabali and all the ministers honoured for their counsel went ahead.', 'veda-app-ai-draft', true),
('ramayana-2-105-3', 'en', 'They went east towards the lovely Mandakini river, circling the great mountain Chitrakuta reverently.', 'veda-app-ai-draft', true),
('ramayana-2-105-4', 'en', 'Looking at thousands of lovely minerals of many kinds, Bharata went along its side with his army.', 'veda-app-ai-draft', true),
('ramayana-2-105-5', 'en', 'Not far from Chitrakuta, Bharata saw the hermitage where the sage Bharadvaja made his home.', 'veda-app-ai-draft', true),
('ramayana-2-105-6', 'en', 'Coming to Bharadvaja''s hermitage, the wise joy of his family got down from his chariot and bowed at the sage''s feet.', 'veda-app-ai-draft', true),
('ramayana-2-105-7', 'en', 'Then Bharadvaja, delighted, said to Bharata: ''Dear one, have you done what you came for and met Rama?''', 'veda-app-ai-draft', true),
('ramayana-2-105-8', 'en', 'Asked this by wise Bharadvaja, Bharata, devoted to dharma, replied to him.', 'veda-app-ai-draft', true),
('ramayana-2-105-9', 'en', 'Begged by our teacher and by me, Raghava, firm in valour and well pleased, said to Vasishtha:', 'veda-app-ai-draft', true),
('ramayana-2-105-10', 'en', '''I will keep my father''s promise faithfully: the promise of fourteen years that my father made.''', 'veda-app-ai-draft', true),
('ramayana-2-105-11', 'en', 'Told this, the very wise Vasishtha, who knew how to speak, replied to Raghava, skilled in speech, with great words:', 'veda-app-ai-draft', true),
('ramayana-2-105-12', 'en', '''Gladly give these gold-adorned sandals, very wise one, to secure welfare in Ayodhya on your behalf.''', 'veda-app-ai-draft', true),
('ramayana-2-105-13', 'en', 'Told this by Vasishtha, Raghava, standing facing east, gave me these gold-worked sandals for the kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-105-14', 'en', 'Permitted by great-souled Rama, I have turned back, and I go to Ayodhya carrying these auspicious sandals.', 'veda-app-ai-draft', true),
('ramayana-2-105-15', 'en', 'Hearing these good words of great-souled Bharata, the sage Bharadvaja spoke even better words.', 'veda-app-ai-draft', true),
('ramayana-2-105-16', 'en', 'Tiger among men, best of the virtuous, it is no wonder that nobility rests in you, as rainwater settles in a hollow.', 'veda-app-ai-draft', true),
('ramayana-2-105-17', 'en', 'Your mighty-armed father Dasharatha is immortal, since he has a son like you, righteous and devoted to dharma.', 'veda-app-ai-draft', true),
('ramayana-2-105-18', 'en', 'When the great sage had spoken, Bharata, with folded hands, clasped his feet and began to take leave.', 'veda-app-ai-draft', true),
('ramayana-2-105-19', 'en', 'Then, having walked around Bharadvaja again and again, glorious Bharata went to Ayodhya with his ministers.', 'veda-app-ai-draft', true),
('ramayana-2-105-20', 'en', 'The vast army following Bharata turned back again, with carriages, carts, horses and elephants.', 'veda-app-ai-draft', true),
('ramayana-2-105-21', 'en', 'Then, crossing the divine Yamuna with its garland of waves, they all saw again the Ganga with its auspicious water.', 'veda-app-ai-draft', true),
('ramayana-2-105-22', 'en', 'Crossing it, full of lovely water, with his kin, he entered lovely Shringaverapura with his soldiers.', 'veda-app-ai-draft', true),
('ramayana-2-105-23', 'en', 'From Shringaverapura he saw Ayodhya again, and Bharata, burning with sorrow, said this to the charioteer:', 'veda-app-ai-draft', true),
('ramayana-2-105-24', 'en', 'Charioteer, look, Ayodhya seems ruined and does not shine; it is shapeless, joyless, wretched and silent.', 'veda-app-ai-draft', true),
('ramayana-2-106-1', 'en', 'The lord, famous Bharata, quickly entered Ayodhya in his chariot with its deep, pleasing rumble.', 'veda-app-ai-draft', true),
('ramayana-2-106-2', 'en', '...a city haunted by cats and owls, its men and elephants hidden away, like a dark, black, lightless night...', 'veda-app-ai-draft', true),
('ramayana-2-106-3', 'en', '...like Rohini, the moon''s dear wife, once blazing with splendour, now alone and afflicted by the rising eclipse planet...', 'veda-app-ai-draft', true),
('ramayana-2-106-4', 'en', '...like a thin mountain stream, its scant water warm and troubled, its birds scorched by heat, its fish and crocodiles hidden...', 'veda-app-ai-draft', true),
('ramayana-2-106-5', 'en', '...like a sacrificial flame, smokeless and golden, that rose from the fire and then, sprinkled with oblation, died away...', 'veda-app-ai-draft', true),
('ramayana-2-106-6', 'en', '...like an army in a great battle, its armour shattered, its elephants, horses, chariots and banners broken, its heroes slain...', 'veda-app-ai-draft', true),
('ramayana-2-106-7', 'en', '...like an ocean wave that rose foaming and roaring and then fell silent when the wind died down...', 'veda-app-ai-draft', true),
('ramayana-2-106-8', 'en', '...like an altar, silent after the soma pressing is over, abandoned by all the sacrificial tools and handsome priests...', 'veda-app-ai-draft', true),
('ramayana-2-106-9', 'en', '...like a cow standing in the middle of the pen, distressed, not eating fresh grass, abandoned by the bull and longing...', 'veda-app-ai-draft', true),
('ramayana-2-106-10', 'en', '...like a new pearl necklace stripped of its fine, bright, glowing jewels...', 'veda-app-ai-draft', true),
('ramayana-2-106-11', 'en', '...like a star fallen from the sky when its merit is spent, its spreading radiance withdrawn...', 'veda-app-ai-draft', true),
('ramayana-2-106-12', 'en', '...like a forest creeper at the end of spring, once covered in flowers and humming bees, now scorched by a forest fire and withered...', 'veda-app-ai-draft', true),
('ramayana-2-106-13', 'en', '...with all its merchants bewildered and its shops and markets closed, like the sky covered by clouds, hiding moon and stars...', 'veda-app-ai-draft', true),
('ramayana-2-106-14', 'en', '...like an untended drinking hall with its drinkers gone, strewn with broken cups whose fine drink is spent...', 'veda-app-ai-draft', true),
('ramayana-2-106-15', 'en', '...like a broken, collapsed water stand, its floor torn up, sunken, strewn with broken pots, its water used up...', 'veda-app-ai-draft', true),
('ramayana-2-106-16', 'en', '...like a long, taut bowstring, fitted with loops, cut by arrows and fallen from a warrior''s bow to the ground...', 'veda-app-ai-draft', true),
('ramayana-2-106-17', 'en', '...like a weak young mare, ridden hard by a battle-loving horseman and then abandoned with her gear thrown down...', 'veda-app-ai-draft', true),
('ramayana-2-106-18', 'en', '...like the sun''s light hidden by dark rain clouds when the rainy season has set in and it has entered the cloud bank.', 'veda-app-ai-draft', true),
('ramayana-2-106-19', 'en', 'Glorious Bharata, son of Dasharatha, standing in his chariot, spoke to the charioteer driving the fine chariot:', 'veda-app-ai-draft', true),
('ramayana-2-106-20', 'en', 'Why today is the deep, rich sound of songs and music not heard in Ayodhya as before?', 'veda-app-ai-draft', true),
('ramayana-2-106-21', 'en', 'The heady scent of wine, the scent of garlands and the scent of burnt aloe incense no longer drift around.', 'veda-app-ai-draft', true),
('ramayana-2-106-22', 'en', 'The sound of fine carriages, the pleasant neighing of horses, the trumpeting of rutting elephants and the great rumble of chariots are not heard in this city now that Rama is exiled.', 'veda-app-ai-draft', true),
('ramayana-2-106-23', 'en', 'The main roads of Ayodhya do not shine with young, well-dressed men walking proudly about.', 'veda-app-ai-draft', true),
('ramayana-2-106-24', 'en', 'Speaking of many such things, he entered his father''s home, bereft of that king like a cave without its lion.', 'veda-app-ai-draft', true),
('ramayana-2-107-1', 'en', 'Then, having settled his mothers in Ayodhya, Bharata, firm in his vows and burning with sorrow, said this to his elders:', 'veda-app-ai-draft', true),
('ramayana-2-107-2', 'en', 'I will go to Nandigrama; I take leave of you all today. There I will bear all this sorrow without Raghava.', 'veda-app-ai-draft', true),
('ramayana-2-107-3', 'en', 'The king has gone to heaven and my elder lives in the forest. I will wait for Rama to take the kingdom, for he is the famous king.', 'veda-app-ai-draft', true),
('ramayana-2-107-4', 'en', 'Hearing these good words of great-souled Bharata, all the ministers and the royal priest Vasishtha said:', 'veda-app-ai-draft', true),
('ramayana-2-107-5', 'en', 'Bharata, what you have said is fitting and praiseworthy; these words from love for your brother are worthy of you alone.', 'veda-app-ai-draft', true),
('ramayana-2-107-6', 'en', 'Who would not approve of you, always loving your kin, firm in friendship to your brother, following the noble path?', 'veda-app-ai-draft', true),
('ramayana-2-107-7', 'en', 'Hearing the ministers'' words, which matched his wish, he said to the charioteer, ''Let my chariot be yoked.''', 'veda-app-ai-draft', true),
('ramayana-2-107-8', 'en', 'With a joyful face, he bowed to all his mothers and mounted the chariot with Shatrughna.', 'veda-app-ai-draft', true),
('ramayana-2-107-9', 'en', 'Mounting the chariot quickly, Shatrughna and Bharata, very glad, went on, surrounded by ministers and priests.', 'veda-app-ai-draft', true),
('ramayana-2-107-10', 'en', 'Ahead went the Brahmins led by Vasishtha, all facing east, toward where Nandigrama was.', 'veda-app-ai-draft', true),
('ramayana-2-107-11', 'en', 'When Bharata went, the army, full of elephants, horses and chariots, went too unbidden, as did all the citizens.', 'veda-app-ai-draft', true),
('ramayana-2-107-12', 'en', 'Righteous Bharata, loving his brother, standing in his chariot, went quickly to Nandigrama, carrying the sandals on his head.', 'veda-app-ai-draft', true),
('ramayana-2-107-13', 'en', 'Then Bharata, quickly entering Nandigrama, got down from his chariot and said this to his elders:', 'veda-app-ai-draft', true),
('ramayana-2-107-14', 'en', 'My brother himself gave me this kingdom as a trust, and these gold-adorned sandals will secure its welfare. I will guard it until Raghava returns.', 'veda-app-ai-draft', true),
('ramayana-2-107-15', 'en', 'Quickly fitting them back myself, I will see Rama''s feet together with these sandals.', 'veda-app-ai-draft', true),
('ramayana-2-107-16', 'en', 'Then, my burden laid down, reunited with Raghava, I will hand the kingdom to my elder and serve him as an elder.', 'veda-app-ai-draft', true),
('ramayana-2-107-17', 'en', 'Giving back to Raghava these fine sandals held in trust, and this kingdom and Ayodhya, I will be cleansed of sin.', 'veda-app-ai-draft', true),
('ramayana-2-107-18', 'en', 'When Kakutstha is consecrated and the people are joyful, my happiness and fame will be four times greater than from the kingdom.', 'veda-app-ai-draft', true),
('ramayana-2-107-19', 'en', 'Lamenting thus, sad and famous Bharata ruled the kingdom from Nandigrama with his ministers, in sorrow.', 'veda-app-ai-draft', true),
('ramayana-2-107-20', 'en', 'The heroic lord Bharata, wearing bark and matted hair in the dress of a sage, lived in Nandigrama with his army.', 'veda-app-ai-draft', true),
('ramayana-2-107-21', 'en', 'Bharata, loving his brother, longed for Rama''s return, doing his brother''s bidding and keeping his promise to the end.', 'veda-app-ai-draft', true),
('ramayana-2-107-22', 'en', 'Having consecrated the sandals, Bharata lived in Nandigrama and reported all affairs of government to the sandals.', 'veda-app-ai-draft', true),
('ramayana-2-108-1', 'en', 'After Bharata had left, Rama, living in the ascetics'' forest, noticed that the ascetics were anxious and uneasy.', 'veda-app-ai-draft', true),
('ramayana-2-108-2', 'en', 'He saw that the ascetics in the hermitage in front of Chitrakuta, who lived there relying on Rama, were uneasy.', 'veda-app-ai-draft', true),
('ramayana-2-108-3', 'en', 'Pointing at Rama with their eyes and brows, suspicious, they whispered to one another and talked quietly among themselves.', 'veda-app-ai-draft', true),
('ramayana-2-108-4', 'en', 'Seeing their unease, Rama, doubting himself, folded his hands and spoke to the chief sage of the community.', 'veda-app-ai-draft', true),
('ramayana-2-108-5', 'en', 'Holy one, is there anything in my past conduct that seems wrong, causing the ascetics to change toward me?', 'veda-app-ai-draft', true),
('ramayana-2-108-6', 'en', 'Has my younger brother Lakshmana, through carelessness, done something seen by the sages as unworthy of himself?', 'veda-app-ai-draft', true),
('ramayana-2-108-7', 'en', 'Has Sita, who serves you and is devoted to serving me, failed to behave as befits a woman?', 'veda-app-ai-draft', true),
('ramayana-2-108-8', 'en', 'Then the sage, aged by years and worn by austerity, spoke trembling to Rama, who was devoted to compassion for all beings.', 'veda-app-ai-draft', true),
('ramayana-2-108-9', 'en', 'Dear one, how could Vaidehi, so good by nature and delighting in goodness, ever falter, especially toward ascetics?', 'veda-app-ai-draft', true),
('ramayana-2-108-10', 'en', 'This trouble for the ascetics arises because of you. That is why, frightened of the rakshasas, they talk among themselves.', 'veda-app-ai-draft', true),
('ramayana-2-108-11', 'en', 'There is a rakshasa here named Khara, Ravana''s younger brother, who has uprooted all the ascetics living in Janasthana.', 'veda-app-ai-draft', true),
('ramayana-2-108-12', 'en', 'He is bold, arrogant from victory, cruel, a man-eater, proud and wicked, and he cannot tolerate you, dear one.', 'veda-app-ai-draft', true),
('ramayana-2-108-13', 'en', 'Ever since you came to this hermitage, dear one, the rakshasas have been harassing the ascetics.', 'veda-app-ai-draft', true),
('ramayana-2-108-14', 'en', 'They show themselves in hideous, cruel, terrifying, many and misshapen forms, unpleasant to see.', 'veda-app-ai-draft', true),
('ramayana-2-108-15', 'en', 'Defiling the ascetics with impure, unclean things, these ignoble ones quickly strike down others who stand before them.', 'veda-app-ai-draft', true),
('ramayana-2-108-16', 'en', 'Hiding unseen in those hermitage grounds, these small-minded ones delight in destroying the ascetics there.', 'veda-app-ai-draft', true),
('ramayana-2-108-17', 'en', 'They throw away the ladles and vessels, pour water on the fires and smash the pots when the offering is about to be made.', 'veda-app-ai-draft', true),
('ramayana-2-108-18', 'en', 'Wishing to leave the hermitages invaded by those wicked ones, the sages are now urging me to go to another region.', 'veda-app-ai-draft', true),
('ramayana-2-108-19', 'en', 'So, Rama, before those wicked ones show bodily violence to the ascetics, we will leave this hermitage.', 'veda-app-ai-draft', true),
('ramayana-2-108-20', 'en', 'Not far from here is a lovely forest with plenty of roots and fruit. I will go back to the old hermitage with my followers.', 'veda-app-ai-draft', true),
('ramayana-2-108-21', 'en', 'Khara may act wrongly against you too, dear one. If you are so minded, come with us from here.', 'veda-app-ai-draft', true),
('ramayana-2-108-22', 'en', 'Raghava, living here now is dangerous for you with your wife, as there is always risk, even though you are capable.', 'veda-app-ai-draft', true),
('ramayana-2-108-23', 'en', 'Prince Rama could not hold back that eager ascetic with words of reply.', 'veda-app-ai-draft', true),
('ramayana-2-108-24', 'en', 'Having greeted Raghava, taken leave and reassured him, the head of the community left the hermitage with his people.', 'veda-app-ai-draft', true),
('ramayana-2-108-25', 'en', 'Rama, having followed the sages for a distance from that place and bowed to the chief sage, given advice by those well-pleased sages and with their approval, returned to his holy dwelling.', 'veda-app-ai-draft', true),
('ramayana-2-108-26', 'en', 'The lord Raghava did not leave the hermitage, empty of sages, for even a moment; some ascetics with the virtues of sages always stayed with him.', 'veda-app-ai-draft', true),
('ramayana-2-109-1', 'en', 'After the ascetics had left, Raghava, reflecting, no longer liked living there, for many reasons.', 'veda-app-ai-draft', true),
('ramayana-2-109-2', 'en', 'Here I saw Bharata, and my mothers with the citizens; that memory follows me as I keep grieving for them.', 'veda-app-ai-draft', true),
('ramayana-2-109-3', 'en', 'The great soul''s army camp has badly trampled the place with the dung of horses and elephants.', 'veda-app-ai-draft', true),
('ramayana-2-109-4', 'en', 'Thinking, ''Let us go elsewhere,'' Raghava set out with Vaidehi and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-2-109-5', 'en', 'Reaching Atri''s hermitage, the famous one bowed to him, and the holy Atri received him like a son.', 'veda-app-ai-draft', true),
('ramayana-2-109-6', 'en', 'He himself ordered all hospitality to be well given to him, and comforted Sumitra''s son and fortunate Sita.', 'veda-app-ai-draft', true),
('ramayana-2-109-7', 'en', 'Calling and honouring his aged wife who came, the sage who knew dharma and loved all beings spoke kindly to her.', 'veda-app-ai-draft', true),
('ramayana-2-109-8', 'en', 'The best of sages said to fortunate Anasuya, the righteous ascetic woman: ''Receive Vaidehi.''', 'veda-app-ai-draft', true),
('ramayana-2-109-9', 'en', 'He told Rama about that righteous ascetic woman: when the world was burned by ten years of drought without a break...', 'veda-app-ai-draft', true),
('ramayana-2-109-10', 'en', '...she created roots and fruit and made the Ganga flow, endowed with fierce austerity and adorned with disciplines.', 'veda-app-ai-draft', true),
('ramayana-2-109-11', 'en', 'Dear one, she practised great austerity for ten thousand years, and by her vows all obstacles were removed.', 'veda-app-ai-draft', true),
('ramayana-2-109-12', 'en', 'Hurrying for the gods'' purpose, she turned ten nights into one night. Sinless one, she is like a mother to you.', 'veda-app-ai-draft', true),
('ramayana-2-109-13', 'en', 'Let Vaidehi go to her, the famous elder, worthy of all beings'' reverence, never angry.', 'veda-app-ai-draft', true),
('ramayana-2-109-14', 'en', 'When the sage said this, Raghava agreed and spoke these excellent words to Sita, who knew dharma.', 'veda-app-ai-draft', true),
('ramayana-2-109-15', 'en', 'Princess, you have heard what this sage said. For your own good, go quickly to the ascetic woman.', 'veda-app-ai-draft', true),
('ramayana-2-109-16', 'en', 'Go quickly to the ascetic woman worthy of approach, known in the world as Anasuya for her deeds.', 'veda-app-ai-draft', true),
('ramayana-2-109-17', 'en', 'Hearing these words, Maithili, wishing Raghava well, approached Atri''s wife, who knew dharma.', 'veda-app-ai-draft', true),
('ramayana-2-109-18', 'en', '...weak and wrinkled, aged, her hair white with age, her body always trembling like a plantain tree in the wind.', 'veda-app-ai-draft', true),
('ramayana-2-109-19', 'en', 'Calmly Sita bowed to fortunate Anasuya, devoted to her husband, and told her name.', 'veda-app-ai-draft', true),
('ramayana-2-109-20', 'en', 'Having bowed to the blameless ascetic, Vaidehi, with joined palms and joy, asked after her health.', 'veda-app-ai-draft', true),
('ramayana-2-109-21', 'en', 'Then, seeing fortunate Sita, who followed dharma, Anasuya comforted her and said joyfully, ''Fortunately you look to dharma.''', 'veda-app-ai-draft', true),
('ramayana-2-109-22', 'en', 'Proud Sita, fortunately you have left your kin, honour and wealth and followed Rama, confined to the forest.', 'veda-app-ai-draft', true),
('ramayana-2-109-23', 'en', 'Whether in the city or the forest, whether good or bad, women whose husbands are dear to them reach worlds of great fortune.', 'veda-app-ai-draft', true),
('ramayana-2-109-24', 'en', 'Even if of bad character, driven by desire or without wealth, a husband is the highest god for women of noble nature.', 'veda-app-ai-draft', true),
('ramayana-2-109-25', 'en', 'Thinking it over, I see no better kinsman than this, Vaidehi; fitting everywhere, like austerity that never fades.', 'veda-app-ai-draft', true),
('ramayana-2-109-26', 'en', 'But bad women do not understand virtue and fault in this way; their hearts ruled by desire, they behave as if they owned their husbands.', 'veda-app-ai-draft', true),
('ramayana-2-109-27', 'en', 'Such women, falling under the power of wrong deeds, earn disgrace and fall from dharma, Maithili.', 'veda-app-ai-draft', true),
('ramayana-2-109-28', 'en', 'But women like you, endowed with virtues and knowing what is high and low in the world, will move in heaven like those who have done good.', 'veda-app-ai-draft', true),
('ramayana-2-110-1', 'en', 'Addressed thus by Anasuya, free of envy, Vaidehi honoured her words and began to speak softly.', 'veda-app-ai-draft', true),
('ramayana-2-110-2', 'en', 'It is no wonder, noble lady, that you speak to me like this. I too know that a husband is a woman''s guide.', 'veda-app-ai-draft', true),
('ramayana-2-110-3', 'en', 'Even if my husband were without good conduct, noble lady, I would serve him without hesitation.', 'veda-app-ai-draft', true),
('ramayana-2-110-4', 'en', 'How much more one praised for his virtues, compassionate, self-controlled, steadfast in love, righteous, devoted to his mother and dear to his father?', 'veda-app-ai-draft', true),
('ramayana-2-110-5', 'en', 'Mighty Rama treats the king''s other wives exactly as he treats Kausalya.', 'veda-app-ai-draft', true),
('ramayana-2-110-6', 'en', 'Even women the king saw only once, the heroic Rama, who loves his father and knows dharma, treats like a mother, setting aside pride.', 'veda-app-ai-draft', true),
('ramayana-2-110-7', 'en', 'As I was coming into this frightening, lonely forest, my mother-in-law fixed firmly in my heart what is there now.', 'veda-app-ai-draft', true),
('ramayana-2-110-8', 'en', 'And at the time of my marriage, before the fire, my mother taught me words that I have kept too.', 'veda-app-ai-draft', true),
('ramayana-2-110-9', 'en', 'All that has been renewed by your words, righteous lady: for a woman no austerity is ordained other than serving her husband.', 'veda-app-ai-draft', true),
('ramayana-2-110-10', 'en', 'Savitri, having served her husband, is honoured in heaven; and you too, by the same conduct, have reached heaven through serving your husband.', 'veda-app-ai-draft', true),
('ramayana-2-110-11', 'en', 'This best of all women is a goddess in heaven: Rohini, who is never seen without the moon even for a moment.', 'veda-app-ai-draft', true),
('ramayana-2-110-12', 'en', 'Such excellent women, firm in vows to their husbands, are honoured in the world of the gods by their own good deeds.', 'veda-app-ai-draft', true),
('ramayana-2-110-13', 'en', 'Then Anasuya, delighted on hearing Sita''s words, kissed Maithili on the head and said, to please her:', 'veda-app-ai-draft', true),
('ramayana-2-110-14', 'en', 'Through many disciplines I have gained great power of austerity. Relying on that power, Sita of pure vows, I offer you a gift.', 'veda-app-ai-draft', true),
('ramayana-2-110-15', 'en', 'Your words are fitting and proper, Maithili, and I am pleased. Tell me what fitting thing I may do for you.'' Sita said to her, rich in austerity: ''It is already done.''', 'veda-app-ai-draft', true),
('ramayana-2-110-16', 'en', 'Addressed thus, the righteous one was even more pleased with her. ''Then, Sita, I will make your joy fruitful.''', 'veda-app-ai-draft', true),
('ramayana-2-110-17', 'en', 'This divine, fine garland, clothing, ornaments and precious body ointment, Vaidehi...', 'veda-app-ai-draft', true),
('ramayana-2-110-18', 'en', '...given by me, Sita, will adorn your limbs. It will always be fitting and never fade.', 'veda-app-ai-draft', true),
('ramayana-2-110-19', 'en', 'Anointed with this divine ointment, daughter of Janaka, you will adorn your husband as Lakshmi adorns the imperishable Vishnu.', 'veda-app-ai-draft', true),
('ramayana-2-110-20', 'en', 'Maithili accepted the clothing, ointment, ornaments and garlands, a matchless gift of love.', 'veda-app-ai-draft', true),
('ramayana-2-110-21', 'en', 'Having accepted that loving gift, famous Sita, steady, with joined palms, sat by the ascetic woman rich in austerity.', 'veda-app-ai-draft', true),
('ramayana-2-110-22', 'en', 'As Sita sat thus, Anasuya, firm in her vows, began to ask about some pleasant story.', 'veda-app-ai-draft', true),
('ramayana-2-110-23', 'en', 'Sita, I have heard the story that you were won by famous Raghava at a svayamvara.', 'veda-app-ai-draft', true),
('ramayana-2-110-24', 'en', 'I want to hear that story in detail, Maithili. Please tell me all of it as you experienced it.', 'veda-app-ai-draft', true),
('ramayana-2-110-25', 'en', 'Addressed thus, Sita said to the righteous woman, ''Listen,'' and told her the story.', 'veda-app-ai-draft', true),
('ramayana-2-110-26', 'en', 'The heroic lord of Mithila, named Janaka, who knows dharma, devoted to a Kshatriya''s duty, rules the earth justly.', 'veda-app-ai-draft', true),
('ramayana-2-110-27', 'en', 'As he was ploughing a field with a plough in his hand, I, they say, rose up, splitting the earth, and became the king''s daughter.', 'veda-app-ai-draft', true),
('ramayana-2-110-28', 'en', 'Seeing me, my whole body covered in dust, the king, who was scattering handfuls of earth, was amazed.', 'veda-app-ai-draft', true),
('ramayana-2-110-29', 'en', 'Being childless, he lovingly took me on his lap himself, saying ''This is my daughter,'' and poured his love on me.', 'veda-app-ai-draft', true),
('ramayana-2-110-30', 'en', 'And a voice in the sky, they say, spoke in human tones: ''So it is, king; she is rightfully your daughter.''', 'veda-app-ai-draft', true),
('ramayana-2-110-31', 'en', 'Then my righteous father, the lord of Mithila, was delighted; having gained me, the king gained great prosperity.', 'veda-app-ai-draft', true),
('ramayana-2-110-32', 'en', 'The doer of good deeds gave me lovingly to his eldest queen, and she cherished me with a mother''s tender affection.', 'veda-app-ai-draft', true),
('ramayana-2-110-33', 'en', 'Seeing that I had reached the age for marriage, my father grew anxious, like a poor man who has lost his wealth.', 'veda-app-ai-draft', true),
('ramayana-2-110-34', 'en', 'In the world the father of a daughter, even one equal to Indra on earth, faces humiliation from people both equal and lower.', 'veda-app-ai-draft', true),
('ramayana-2-110-35', 'en', 'Seeing that humiliation close at hand, the king, sunk in an ocean of worry, could not reach the shore, like one without a boat.', 'veda-app-ai-draft', true),
('ramayana-2-110-36', 'en', 'Knowing I was not born from a womb, the king, thinking about it, could not find a fitting, suitable husband for me.', 'veda-app-ai-draft', true),
('ramayana-2-110-37', 'en', 'As the wise king kept thinking, this idea came to him: ''I will hold a svayamvara for my daughter.''', 'veda-app-ai-draft', true),
('ramayana-2-110-38', 'en', 'At a great sacrifice, great-souled Varuna had lovingly given him a fine bow and two quivers with inexhaustible arrows.', 'veda-app-ai-draft', true),
('ramayana-2-110-39', 'en', 'It could not be moved by men even with effort, because of its weight; kings could not bend it even in their dreams.', 'veda-app-ai-draft', true),
('ramayana-2-110-40', 'en', 'Having obtained that bow, my truthful father first invited the kings and said in an assembly of rulers:', 'veda-app-ai-draft', true),
('ramayana-2-110-41', 'en', '''The man who lifts this bow and strings it, my daughter will be his wife, without doubt.''', 'veda-app-ai-draft', true),
('ramayana-2-110-42', 'en', 'Seeing that best of bows, heavy as a mountain, the kings bowed to it and left, unable to lift it.', 'veda-app-ai-draft', true),
('ramayana-2-110-43', 'en', 'After a very long time this radiant Raghava came with Vishvamitra to see the sacrifice.', 'veda-app-ai-draft', true),
('ramayana-2-110-44', 'en', 'Rama, true in valour, came with his brother Lakshmana, and righteous Vishvamitra was well honoured by my father.', 'veda-app-ai-draft', true),
('ramayana-2-110-45', 'en', 'There the Brahmin said to my father, ''These are Rama and Lakshmana, sons of Dasharatha, who wish to see the bow.'' Told this, he had the bow brought.', 'veda-app-ai-draft', true),
('ramayana-2-110-46', 'en', 'In the twinkling of an eye the mighty one bent it, quickly fitted the string and drew it full.', 'veda-app-ai-draft', true),
('ramayana-2-110-47', 'en', 'As he drew it with force, the bow broke in two in the middle, and its sound was terrible, like a falling thunderbolt.', 'veda-app-ai-draft', true),
('ramayana-2-110-48', 'en', 'Then my truthful father, raising a fine water vessel, was ready to give me to Rama there.', 'veda-app-ai-draft', true),
('ramayana-2-110-49', 'en', 'But Raghava did not accept me then, without knowing the wish of his father, the lord of Ayodhya.', 'veda-app-ai-draft', true),
('ramayana-2-110-50', 'en', 'Then, after inviting my aged father-in-law King Dasharatha, my father gave me to Rama, who knew himself.', 'veda-app-ai-draft', true),
('ramayana-2-110-51', 'en', 'And my father himself gave my younger sister, good and lovely Urmila, to Lakshmana as his wife.', 'veda-app-ai-draft', true),
('ramayana-2-110-52', 'en', 'So I was given to Rama at that svayamvara, and by dharma I am devoted to my husband, the best of the mighty.', 'veda-app-ai-draft', true),
('ramayana-2-111-1', 'en', 'Anasuya, who knew dharma, hearing that great story, embraced Maithili with both arms and kissed her head.', 'veda-app-ai-draft', true),
('ramayana-2-111-2', 'en', 'You have told it sweetly and vividly, with clear words; I have heard all about how the svayamvara took place.', 'veda-app-ai-draft', true),
('ramayana-2-111-3', 'en', 'I am delighted by your story, sweet-spoken one. The glorious sun has set, bringing on the auspicious night.', 'veda-app-ai-draft', true),
('ramayana-2-111-4', 'en', 'The sound is heard of birds that were scattered all day for food, nestling at twilight to sleep.', 'veda-app-ai-draft', true),
('ramayana-2-111-5', 'en', 'These sages too, wet from bathing, bringing fruit, are coming together, their bark garments soaked with water.', 'veda-app-ai-draft', true),
('ramayana-2-111-6', 'en', 'When the sages have made their fire offerings properly, smoke red as a dove''s neck is seen, stirred by the wind.', 'veda-app-ai-draft', true),
('ramayana-2-111-7', 'en', 'The trees, though their leaves are few, seem dense all around, and even at a distance the directions cannot be seen.', 'veda-app-ai-draft', true),
('ramayana-2-111-8', 'en', 'Night-roaming creatures wander everywhere, and these deer of the hermitage forest sleep at the altars and bathing places.', 'veda-app-ai-draft', true),
('ramayana-2-111-9', 'en', 'Sita, night has come, adorned with stars; the moon, clothed in moonlight, is seen risen in the sky.', 'veda-app-ai-draft', true),
('ramayana-2-111-10', 'en', 'Go; I give you leave. Attend Rama. I have been delighted by your sweet storytelling.', 'veda-app-ai-draft', true),
('ramayana-2-111-11', 'en', 'But first adorn yourself before my eyes, Maithili. Give me joy, dear child, shining with divine ornaments.', 'veda-app-ai-draft', true),
('ramayana-2-111-12', 'en', 'Then Sita, like a daughter of the gods, adorned herself, bowed her head to her, and went toward Rama.', 'veda-app-ai-draft', true),
('ramayana-2-111-13', 'en', 'Raghava, best of speakers, saw Sita adorned like that and was delighted at the ascetic woman''s loving gift.', 'veda-app-ai-draft', true),
('ramayana-2-111-14', 'en', 'Then Maithili told Rama all about the ascetic woman''s loving gift of clothes, ornaments and garlands.', 'veda-app-ai-draft', true),
('ramayana-2-111-15', 'en', 'Rama and the great chariot-warrior Lakshmana were delighted to see such honour paid to Maithili, very rare among humans.', 'veda-app-ai-draft', true),
('ramayana-2-111-16', 'en', 'Then, pleased, the moon-faced joy of the Raghus spent that holy night there, honoured by ascetics and perfected beings.', 'veda-app-ai-draft', true),
('ramayana-2-111-17', 'en', 'When that night had passed and the ascetics had bathed and made their fire offerings, the two tigers among men took leave of the forest-dwelling ascetics.', 'veda-app-ai-draft', true),
('ramayana-2-111-18', 'en', 'Those righteous forest-dwelling ascetics told them that the paths of that forest were overrun by rakshasas.', 'veda-app-ai-draft', true),
('ramayana-2-111-19', 'en', 'This is the path the great sages take when gathering fruit in the forest. By it, Raghava, you can enter the hard forest.', 'veda-app-ai-draft', true),
('ramayana-2-111-20', 'en', 'Blessed thus by the Brahmin ascetics with folded hands, Raghava, scorcher of foes, entered the forest with his wife and Lakshmana, like the sun entering a bank of clouds.', 'veda-app-ai-draft', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values
('ramayana-2-1-1', 'en', 'The second book opens with Dasharatha speaking to Bharata.', 'Ayodhya Kanda, chapter 1: Bharata leaves to visit his uncle in Kekaya. Rama''s goodness, skill and gentle character are described at length, and Dasharatha, growing old, decides to make him crown prince.', '[{"word":"Kaikeyi","meaning":"Bharata''s mother"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
