select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 1 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-1-1', 1, 'Aranya Kanda, Sarga 1, Verse 1', 'प्रविश्य तु महारण्यं दण्डकारण्यमात्मवान्।
ददर्श रामो दुर्धर्षस्तापसाश्रममण्डलम्॥', 'praviśya tu mahāraṇyaṃ daṇḍakāraṇyam ātmavān
dadarśa rāmo durdharṣas tāpasāśramamaṇḍalam', null, 3001001),
('ramayana-3-1-2', 2, 'Aranya Kanda, Sarga 1, Verse 2', 'कुशचीरपरिक्षिप्तं ब्राह्म्या लक्ष्म्या समावृतम्।
यथा प्रदीप्तं दुर्धर्शं गगने सूर्यमण्डलम्॥', 'kuśacīraparikṣiptaṃ brāhmyā lakṣmyā samāvṛtam
yathā pradīptaṃ durdharśaṃ gagane sūryamaṇḍalam', null, 3001002),
('ramayana-3-1-3', 3, 'Aranya Kanda, Sarga 1, Verse 3', 'शरण्यं सर्वभूतानां सुसमृष्टाजिरं सदा।
पूजितं चोपनृत्तं च नित्यमप्सरसां गणैः॥', 'śaraṇyaṃ sarvabhūtānāṃ susamṛṣṭājiraṃ sadā
pūjitaṃ copanṛttaṃ ca nityam apsarasāṃ gaṇaiḥ', null, 3001003),
('ramayana-3-1-4', 4, 'Aranya Kanda, Sarga 1, Verse 4', 'विशालैरग्निशरणैः स्रुग्भाण्डैरजिनैः कुशैः।
समिद्भिस्तोयकलशैः फलमूलैश्च शोभितम्॥', 'viśālair agniśaraṇaiḥ srugbhāṇḍair ajinaiḥ kuśaiḥ
samidbhis toyakalaśaiḥ phalamūlaiś ca śobhitam', null, 3001004),
('ramayana-3-1-5', 5, 'Aranya Kanda, Sarga 1, Verse 5', 'आरण्यैश्च महावृक्षैः पुण्यैः स्वादुफलैर्वृतम्।
बलिहोमार्चितं पुण्यं ब्रह्मघोषनिनादितम्॥', 'āraṇyaiś ca mahāvṛkṣaiḥ puṇyaiḥ svāduphalair vṛtam
balihomārcitaṃ puṇyaṃ brahmaghoṣanināditam', null, 3001005),
('ramayana-3-1-6', 6, 'Aranya Kanda, Sarga 1, Verse 6', 'पुष्पैर्वन्यैः परिक्षिप्तं पद्मिन्या च सपद्मया।
फलमूलाशनैर्दान्तैश्चीरकृष्णाजिनाम्बरैः॥', 'puṣpair vanyaiḥ parikṣiptaṃ padminyā ca sapadmayā
phalamūlāśanair dāntaiś cīrakṛṣṇājināmbaraiḥ', null, 3001006),
('ramayana-3-1-7', 7, 'Aranya Kanda, Sarga 1, Verse 7', 'सूर्यवैश्वानराभैश्च पुराणैर्मुनिभिर्वृतम्।
पुण्यैश नियताहारैः शोभितं परमर्षिभिः॥', 'sūryavaiśvānarābhaiś ca purāṇair munibhir vṛtam
puṇyaiś a niyatāhāraiḥ śobhitaṃ paramarṣibhiḥ', null, 3001007),
('ramayana-3-1-8', 8, 'Aranya Kanda, Sarga 1, Verse 8', 'तद्ब्रह्मभवनप्रख्यं ब्रह्मघोषनिनादितम्।
ब्रह्मविद्भिर्महाभागैर्ब्राह्मणैरुपशोभितम्॥', 'tad brahmabhavanaprakhyaṃ brahmaghoṣanināditam
brahmavidbhir mahābhāgair brāhmaṇair upaśobhitam', null, 3001008),
('ramayana-3-1-9', 9, 'Aranya Kanda, Sarga 1, Verse 9', 'तद्दृष्ट्वा राघवः श्रीमांस्तापसाश्रममण्डलम्।
अभ्यगच्छन्महातेजा विज्यं कृत्वा महद्धनुः॥', 'tad dṛṣṭvā rāghavaḥ śrīmāṃs tāpasāśramamaṇḍalam
abhyagacchan mahātejā vijyaṃ kṛtvā mahad dhanuḥ', null, 3001009),
('ramayana-3-1-10', 10, 'Aranya Kanda, Sarga 1, Verse 10', 'दिव्यज्ञानोपपन्नास्ते रामं दृष्ट्वा महर्षयः।
अभ्यगच्छंस्तदा प्रीता वैदेहीं च यशस्विनीम्॥', 'divyajñānopapannās te rāmaṃ dṛṣṭvā maharṣayaḥ
abhyagacchaṃs tadā prītā vaidehīṃ ca yaśasvinīm', null, 3001010),
('ramayana-3-1-11', 11, 'Aranya Kanda, Sarga 1, Verse 11', 'ते तं सोममिवोद्यन्तं दृष्ट्वा वै धर्मचारिणः।
मङ्गलानि प्रयुञ्जानाः प्रत्यगृह्णन्दृढव्रताः॥', 'te taṃ somam ivodyantaṃ dṛṣṭvā vai dharmacāriṇaḥ
maṅgalāni prayuñjānāḥ pratyagṛhṇan dṛḍhavratāḥ', null, 3001011),
('ramayana-3-1-12', 12, 'Aranya Kanda, Sarga 1, Verse 12', 'रूपसंहननं लक्ष्मीं सौकुमार्यं सुवेषताम्।
ददृशुर्विस्मिताकारा रामस्य वनवासिनः॥', 'rūpasaṃhananaṃ lakṣmīṃ saukumāryaṃ suveṣatām
dadṛśur vismitākārā rāmasya vanavāsinaḥ', null, 3001012),
('ramayana-3-1-13', 13, 'Aranya Kanda, Sarga 1, Verse 13', 'वैदेहीं लक्ष्मणं रामं नेत्रैरनिमिषैरिव।
आश्चर्यभूतान्ददृशुः सर्वे ते वनचारिणः॥', 'vaidehīṃ lakṣmaṇaṃ rāmaṃ netrair animiṣair iva
āścaryabhūtān dadṛśuḥ sarve te vanacāriṇaḥ', null, 3001013),
('ramayana-3-1-14', 14, 'Aranya Kanda, Sarga 1, Verse 14', 'अत्रैनं हि महाभागाः सर्वभूतहिते रताः।
अतिथिं पर्णशालायां राघवं संन्यवेशयन्॥', 'atrainaṃ hi mahābhāgāḥ sarvabhūtahite ratāḥ
atithiṃ parṇaśālāyāṃ rāghavaṃ saṃnyaveśayan', null, 3001014),
('ramayana-3-1-15', 15, 'Aranya Kanda, Sarga 1, Verse 15', 'ततो रामस्य सत्कृत्य विधिना पावकोपमाः।
आजह्रुस्ते महाभागाः सलिलं धर्मचारिणः॥', 'tato rāmasya satkṛtya vidhinā pāvakopamāḥ
ājahrus te mahābhāgāḥ salilaṃ dharmacāriṇaḥ', null, 3001015),
('ramayana-3-1-16', 16, 'Aranya Kanda, Sarga 1, Verse 16', 'मूलं पुष्पं फलं वन्यमाश्रमं च महात्मनः।
निवेदयीत्वा धर्मज्ञास्ततः प्राञ्जलयोऽब्रुवन्॥', 'mūlaṃ puṣpaṃ phalaṃ vanyam āśramaṃ ca mahātmanaḥ
nivedayītvā dharmajñās tataḥ prāñjalayo ''bruvan', null, 3001016),
('ramayana-3-1-17', 17, 'Aranya Kanda, Sarga 1, Verse 17', 'धर्मपालो जनस्यास्य शरण्यश्च महायशाः।
पूजनीयश्च मान्यश्च राजा दण्डधरो गुरुः॥', 'dharmapālo janasyāsya śaraṇyaś ca mahāyaśāḥ
pūjanīyaś ca mānyaś ca rājā daṇḍadharo guruḥ', null, 3001017),
('ramayana-3-1-18', 18, 'Aranya Kanda, Sarga 1, Verse 18', 'इन्द्रस्यैव चतुर्भागः प्रजा रक्षति राघव।
राजा तस्माद्वनान्भोगान्भुङ्क्ते लोकनमस्कृतः॥', 'indrasyaiva caturbhāgaḥ prajā rakṣati rāghava
rājā tasmād vanān bhogān bhuṅkte lokanamaskṛtaḥ', null, 3001018),
('ramayana-3-1-19', 19, 'Aranya Kanda, Sarga 1, Verse 19', 'ते वयं भवता रक्ष्या भवद्विषयवासिनः।
नगरस्थो वनस्थो वा त्वं नो राजा जनेश्वरः॥', 'te vayaṃ bhavatā rakṣyā bhavadviṣayavāsinaḥ
nagarastho vanastho vā tvaṃ no rājā janeśvaraḥ', null, 3001019),
('ramayana-3-1-20', 20, 'Aranya Kanda, Sarga 1, Verse 20', 'न्यस्तदण्डा वयं राजञ्जितक्रोधा जितेन्द्रियाः।
रक्षितव्यास्त्वया शश्वद्गर्भभूतास्तपोधनाः॥', 'nyastadaṇḍā vayaṃ rājañ jitakrodhā jitendriyāḥ
rakṣitavyās tvayā śaśvad garbhabhūtās tapodhanāḥ', null, 3001020),
('ramayana-3-1-21', 21, 'Aranya Kanda, Sarga 1, Verse 21', 'एवमुक्त्वा फलैर्मूलैः पुष्पैर्वन्यैश्च राघवम्।
अन्यैश्च विविधाहारैः सलक्ष्मणमपूजयन्॥', 'evam uktvā phalair mūlaiḥ puṣpair vanyaiś ca rāghavam
anyaiś ca vividhāhāraiḥ salakṣmaṇam apūjayan', null, 3001021),
('ramayana-3-1-22', 22, 'Aranya Kanda, Sarga 1, Verse 22', 'तथान्ये तापसाः सिद्धा रामं वैश्वानरोपमाः।
न्यायवृत्ता यथान्यायं तर्पयामासुरीश्वरम्॥', 'tathānye tāpasāḥ siddhā rāmaṃ vaiśvānaropamāḥ
nyāyavṛttā yathānyāyaṃ tarpayām āsur īśvaram', null, 3001022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 2 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-2-1', 1, 'Aranya Kanda, Sarga 2, Verse 1', 'कृतातिथ्योऽथ रामस्तु सूर्यस्योदयनं प्रति।
आमन्त्र्य स मुनीन्सर्वान्वनमेवान्वगाहत॥', 'kṛtātithyo ''tha rāmas tu sūryasyodayanaṃ prati
āmantrya sa munīn sarvān vanam evānvagāhata', null, 3002001),
('ramayana-3-2-2', 2, 'Aranya Kanda, Sarga 2, Verse 2', 'नानामृगगणाकीर्णं शार्दूलवृकसेवितम्।
ध्वस्तवृक्षलतागुल्मं दुर्दर्श सलिलाशयम्॥', 'nānāmṛgagaṇākīrṇaṃ śārdūlavṛkasevitam
dhvastavṛkṣalatāgulmaṃ durdarśa salilāśayam', null, 3002002),
('ramayana-3-2-3', 3, 'Aranya Kanda, Sarga 2, Verse 3', 'निष्कूजनानाशकुनि झिल्लिका गणनादितम्।
लक्ष्मणानुगतो रामो वनमध्यं ददर्श ह॥', 'niṣkūjanānāśakuni jhillikā gaṇanāditam
lakṣmaṇānugato rāmo vanamadhyaṃ dadarśa ha', null, 3002003),
('ramayana-3-2-4', 4, 'Aranya Kanda, Sarga 2, Verse 4', 'वनमध्ये तु काकुत्स्थस्तस्मिन्घोरमृगायुते।
ददर्श गिरिशृङ्गाभं पुरुषादं महास्वनम्॥', 'vanamadhye tu kākutsthas tasmin ghoramṛgāyute
dadarśa giriśṛṅgābhaṃ puruṣādaṃ mahāsvanam', null, 3002004),
('ramayana-3-2-5', 5, 'Aranya Kanda, Sarga 2, Verse 5', 'गभीराक्षं महावक्त्रं विकटं विषमोदरम्।
बीभत्सं विषमं दीर्घं विकृतं घोरदर्शनम्॥', 'gabhīrākṣaṃ mahāvaktraṃ vikaṭaṃ viṣamodaram
bībhatsaṃ viṣamaṃ dīrghaṃ vikṛtaṃ ghoradarśanam', null, 3002005),
('ramayana-3-2-6', 6, 'Aranya Kanda, Sarga 2, Verse 6', 'वसानं चर्मवैयाघ्रं वसार्द्रं रुधिरोक्षितम्।
त्रासनं सर्वभूतानां व्यादितास्यमिवान्तकम्॥', 'vasānaṃ carmavaiyāghraṃ vasārdraṃ rudhirokṣitam
trāsanaṃ sarvabhūtānāṃ vyāditāsyam ivāntakam', null, 3002006),
('ramayana-3-2-7', 7, 'Aranya Kanda, Sarga 2, Verse 7', 'त्रीन्सिंहांश्चतुरो व्याघ्रान्द्वौ वृकौ पृषतान्दश।
सविषाणं वसादिग्धं गजस्य च शिरो महत्॥', 'trīn siṃhāṃś caturo vyāghrān dvau vṛkau pṛṣatān daśa
saviṣāṇaṃ vasādigdhaṃ gajasya ca śiro mahat', null, 3002007),
('ramayana-3-2-8', 8, 'Aranya Kanda, Sarga 2, Verse 8', 'अवसज्यायसे शूले विनदन्तं महास्वनम्।
स रामं लक्ष्मणं चैव सीतां दृष्ट्वा च मैथिलीम्॥', 'avasajyāyase śūle vinadantaṃ mahāsvanam
sa rāmaṃ lakṣmaṇaṃ caiva sītāṃ dṛṣṭvā ca maithilīm', null, 3002008),
('ramayana-3-2-9', 9, 'Aranya Kanda, Sarga 2, Verse 9', 'अभ्यधावत्सुसंक्रुद्धः प्रजाः काल इवान्तकः।
स कृत्वा भैरवं नादं चालयन्निव मेदिनीम्॥', 'abhyadhāvat susaṃkruddhaḥ prajāḥ kāla ivāntakaḥ
sa kṛtvā bhairavaṃ nādaṃ cālayann iva medinīm', null, 3002009),
('ramayana-3-2-10', 10, 'Aranya Kanda, Sarga 2, Verse 10', 'अङ्गेनादाय वैदेहीमपक्रम्य ततोऽब्रवीत्।
युवां जटाचीरधरौ सभार्यौ क्षीणजीवितौ॥', 'aṅgenādāya vaidehīm apakramya tato ''bravīt
yuvāṃ jaṭācīradharau sabhāryau kṣīṇajīvitau', null, 3002010),
('ramayana-3-2-11', 11, 'Aranya Kanda, Sarga 2, Verse 11', 'प्रविष्टौ दण्डकारण्यं शरचापासिधारिणौ।
कथं तापसयोर्वां च वासः प्रमदया सह॥', 'praviṣṭau daṇḍakāraṇyaṃ śaracāpāsidhāriṇau
kathaṃ tāpasayor vāṃ ca vāsaḥ pramadayā saha', null, 3002011),
('ramayana-3-2-12', 12, 'Aranya Kanda, Sarga 2, Verse 12', 'अधर्मचारिणौ पापौ कौ युवां मुनिदूषकौ।
अहं वनमिदं दुर्गं विराघो नाम राक्षसः॥', 'adharmacāriṇau pāpau kau yuvāṃ munidūṣakau
ahaṃ vanam idaṃ durgaṃ virāgho nāma rākṣasaḥ', null, 3002012),
('ramayana-3-2-13', 13, 'Aranya Kanda, Sarga 2, Verse 13', 'चरामि सायुधो नित्यमृषिमांसानि भक्षयन्।
इयं नारी वरारोहा मम भर्या भविष्यति।
युवयोः पापयोश्चाहं पास्यामि रुधिरं मृधे॥', 'carāmi sāyudho nityam ṛṣimāṃsāni bhakṣayan
iyaṃ nārī varārohā mama bharyā bhaviṣyati
yuvayoḥ pāpayoś cāhaṃ pāsyāmi rudhiraṃ mṛdhe', null, 3002013),
('ramayana-3-2-14', 14, 'Aranya Kanda, Sarga 2, Verse 14', 'तस्यैवं ब्रुवतो धृष्टं विराधस्य दुरात्मनः।
श्रुत्वा सगर्वितं वाक्यं संभ्रान्ता जनकात्मजा।
सीता प्रावेपतोद्वेगात्प्रवाते कदली यथा॥', 'tasyaivaṃ bruvato dhṛṣṭaṃ virādhasya durātmanaḥ
śrutvā sagarvitaṃ vākyaṃ saṃbhrāntā janakātmajā
sītā prāvepatodvegāt pravāte kadalī yathā', null, 3002014),
('ramayana-3-2-15', 15, 'Aranya Kanda, Sarga 2, Verse 15', 'तां दृष्ट्वा राघवः सीतां विराधाङ्कगतां शुभाम्।
अब्रवील्लक्ष्मणं वाक्यं मुखेन परिशुष्यता॥', 'tāṃ dṛṣṭvā rāghavaḥ sītāṃ virādhāṅkagatāṃ śubhām
abravīl lakṣmaṇaṃ vākyaṃ mukhena pariśuṣyatā', null, 3002015),
('ramayana-3-2-16', 16, 'Aranya Kanda, Sarga 2, Verse 16', 'पश्य सौम्य नरेन्द्रस्य जनकस्यात्मसंभवाम्।
मम भार्यां शुभाचारां विराधाङ्के प्रवेशिताम्।
अत्यन्त सुखसंवृद्धां राजपुत्रीं यशस्विनीम्॥', 'paśya saumya narendrasya janakasyātmasaṃbhavām
mama bhāryāṃ śubhācārāṃ virādhāṅke praveśitām
atyanta sukhasaṃvṛddhāṃ rājaputrīṃ yaśasvinīm', null, 3002016),
('ramayana-3-2-17', 17, 'Aranya Kanda, Sarga 2, Verse 17', 'यदभिप्रेतमस्मासु प्रियं वर वृतं च यत्।
कैकेय्यास्तु सुसंवृत्तं क्षिप्रमद्यैव लक्ष्मण॥', 'yad abhipretam asmāsu priyaṃ vara vṛtaṃ ca yat
kaikeyyās tu susaṃvṛttaṃ kṣipram adyaiva lakṣmaṇa', null, 3002017),
('ramayana-3-2-18', 18, 'Aranya Kanda, Sarga 2, Verse 18', 'या न तुष्यति राज्येन पुत्रार्थे दीर्घदर्शिनी।
ययाहं सर्वभूतानां हितः प्रस्थापितो वनम्।
अद्येदानीं सकामा सा या माता मम मध्यमा॥', 'yā na tuṣyati rājyena putrārthe dīrghadarśinī
yayāhaṃ sarvabhūtānāṃ hitaḥ prasthāpito vanam
adyedānīṃ sakāmā sā yā mātā mama madhyamā', null, 3002018),
('ramayana-3-2-19', 19, 'Aranya Kanda, Sarga 2, Verse 19', 'परस्पर्शात्तु वैदेह्या न दुःखतरमस्ति मे।
पितुर्विनाशात्सौमित्रे स्वराज्यहरणात्तथा॥', 'parasparśāt tu vaidehyā na duḥkhataram asti me
pitur vināśāt saumitre svarājyaharaṇāt tathā', null, 3002019),
('ramayana-3-2-20', 20, 'Aranya Kanda, Sarga 2, Verse 20', 'इति ब्रुवति काकुत्स्थे बाष्पशोकपरिप्लुते।
अब्रवील्लक्ष्मणः क्रुद्धो रुद्धो नाग इव श्वसन्॥', 'iti bruvati kākutsthe bāṣpaśokapariplute
abravīl lakṣmaṇaḥ kruddho ruddho nāga iva śvasan', null, 3002020),
('ramayana-3-2-21', 21, 'Aranya Kanda, Sarga 2, Verse 21', 'अनाथ इव भूतानां नाथस्त्वं वासवोपमः।
मया प्रेष्येण काकुत्स्थ किमर्थं परितप्स्यसे॥', 'anātha iva bhūtānāṃ nāthas tvaṃ vāsavopamaḥ
mayā preṣyeṇa kākutstha kimarthaṃ paritapsyase', null, 3002021),
('ramayana-3-2-22', 22, 'Aranya Kanda, Sarga 2, Verse 22', 'शरेण निहतस्याद्य मया क्रुद्धेन रक्षसः।
विराधस्य गतासोर्हि मही पास्यति शोणितम्॥', 'śareṇa nihatasyādya mayā kruddhena rakṣasaḥ
virādhasya gatāsor hi mahī pāsyati śoṇitam', null, 3002022),
('ramayana-3-2-23', 23, 'Aranya Kanda, Sarga 2, Verse 23', 'राज्यकामे मम क्रोधो भरते यो बभूव ह।
तं विराधे विमोक्ष्यामि वज्री वज्रमिवाचले॥', 'rājyakāme mama krodho bharate yo babhūva ha
taṃ virādhe vimokṣyāmi vajrī vajram ivācale', null, 3002023),
('ramayana-3-2-24', 24, 'Aranya Kanda, Sarga 2, Verse 24', 'मम भुजबलवेगवेगितः पततु शरोऽस्य महान्महोरसि।
व्यपनयतु तनोश्च जीवितं पततु ततश्च महीं विघूर्णितः॥', 'mama bhujabalavegavegitaḥ patatu śaro ''sya mahān mahorasi
vyapanayatu tanoś ca jīvitaṃ patatu tataś ca mahīṃ vighūrṇitaḥ', null, 3002024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 3 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-3-1', 1, 'Aranya Kanda, Sarga 3, Verse 1', 'अथोवाच पुनर्वाक्यं विराधः पूरयन्वनम्।
आत्मानं पृच्छते ब्रूतं कौ युवां क्व गमिष्यथः॥', 'athovāca punar vākyaṃ virādhaḥ pūrayan vanam
ātmānaṃ pṛcchate brūtaṃ kau yuvāṃ kva gamiṣyathaḥ', null, 3003001),
('ramayana-3-3-2', 2, 'Aranya Kanda, Sarga 3, Verse 2', 'तमुवाच ततो रामो राक्षसं ज्वलिताननम्।
पृच्छन्तं सुमहातेजा इक्ष्वाकुकुलमात्मनः॥', 'tam uvāca tato rāmo rākṣasaṃ jvalitānanam
pṛcchantaṃ sumahātejā ikṣvākukulam ātmanaḥ', null, 3003002),
('ramayana-3-3-3', 3, 'Aranya Kanda, Sarga 3, Verse 3', 'क्षत्रियो वृत्तसंपन्नौ विद्धि नौ वनगोचरौ।
त्वां तु वेदितुमिच्छावः कस्त्वं चरसि दण्डकान्॥', 'kṣatriyo vṛttasaṃpannau viddhi nau vanagocarau
tvāṃ tu veditum icchāvaḥ kas tvaṃ carasi daṇḍakān', null, 3003003),
('ramayana-3-3-4', 4, 'Aranya Kanda, Sarga 3, Verse 4', 'तमुवाच विराधस्तु रामं सत्यपराक्रमम्।
हन्त वक्ष्यामि ते राजन्निबोध मम राघव॥', 'tam uvāca virādhas tu rāmaṃ satyaparākramam
hanta vakṣyāmi te rājan nibodha mama rāghava', null, 3003004),
('ramayana-3-3-5', 5, 'Aranya Kanda, Sarga 3, Verse 5', 'पुत्रः किल जयस्याहं माता मम शतह्रदा।
विराध इति मामाहुः पृथिव्यां सर्वराक्षसाः॥', 'putraḥ kila jayasyāhaṃ mātā mama śatahradā
virādha iti mām āhuḥ pṛthivyāṃ sarvarākṣasāḥ', null, 3003005),
('ramayana-3-3-6', 6, 'Aranya Kanda, Sarga 3, Verse 6', 'तपसा चापि मे प्राप्ता ब्रह्मणो हि प्रसादजा।
शस्त्रेणावध्यता लोकेऽच्छेद्याभेद्यत्वमेव च॥', 'tapasā cāpi me prāptā brahmaṇo hi prasādajā
śastreṇāvadhyatā loke ''cchedyābhedyatvam eva ca', null, 3003006),
('ramayana-3-3-7', 7, 'Aranya Kanda, Sarga 3, Verse 7', 'उत्सृज्य प्रमदामेनामनपेक्षौ यथागतम्।
त्वरमाणौ पालयेथां न वां जीवितमाददे॥', 'utsṛjya pramadām enām anapekṣau yathāgatam
tvaramāṇau pālayethāṃ na vāṃ jīvitam ādade', null, 3003007),
('ramayana-3-3-8', 8, 'Aranya Kanda, Sarga 3, Verse 8', 'तं रामः प्रत्युवाचेदं कोपसंरक्तलोचनः।
राक्षसं विकृताकारं विराधं पापचेतसं॥', 'taṃ rāmaḥ pratyuvācedaṃ kopasaṃraktalocanaḥ
rākṣasaṃ vikṛtākāraṃ virādhaṃ pāpacetasaṃ', null, 3003008),
('ramayana-3-3-9', 9, 'Aranya Kanda, Sarga 3, Verse 9', 'क्षुद्र धिक्त्वां तु हीनार्थं मृत्युमन्वेषसे ध्रुवम्।
रणे संप्राप्स्यसे तिष्ठ न मे जीवन्गमिष्यसि॥', 'kṣudra dhik tvāṃ tu hīnārthaṃ mṛtyum anveṣase dhruvam
raṇe saṃprāpsyase tiṣṭha na me jīvan gamiṣyasi', null, 3003009),
('ramayana-3-3-10', 10, 'Aranya Kanda, Sarga 3, Verse 10', 'ततः सज्यं धनुः कृत्वा रामः सुनिशिताञ्शरान्।
सुशीघ्रमभिसंधाय राक्षसं निजघान ह॥', 'tataḥ sajyaṃ dhanuḥ kṛtvā rāmaḥ suniśitāñ śarān
suśīghram abhisaṃdhāya rākṣasaṃ nijaghāna ha', null, 3003010),
('ramayana-3-3-11', 11, 'Aranya Kanda, Sarga 3, Verse 11', 'धनुषा ज्यागुणवता सप्तबाणान्मुमोच ह।
रुक्मपुङ्खान्महावेगान्सुपर्णानिलतुल्यगान्॥', 'dhanuṣā jyāguṇavatā saptabāṇān mumoca ha
rukmapuṅkhān mahāvegān suparṇānilatulyagān', null, 3003011),
('ramayana-3-3-12', 12, 'Aranya Kanda, Sarga 3, Verse 12', 'ते शरीरं विराधस्य भित्त्वा बर्हिणवाससः।
निपेतुः शोणितादिग्धा धरण्यां पावकोपमाः॥', 'te śarīraṃ virādhasya bhittvā barhiṇavāsasaḥ
nipetuḥ śoṇitādigdhā dharaṇyāṃ pāvakopamāḥ', null, 3003012),
('ramayana-3-3-13', 13, 'Aranya Kanda, Sarga 3, Verse 13', 'स विनद्य महानादं शूलं शक्रध्वजोपमम्।
प्रगृह्याशोभत तदा व्यात्तानन इवान्तकः॥', 'sa vinadya mahānādaṃ śūlaṃ śakradhvajopamam
pragṛhyāśobhata tadā vyāttānana ivāntakaḥ', null, 3003013),
('ramayana-3-3-14', 14, 'Aranya Kanda, Sarga 3, Verse 14', 'तच्छूलं वज्रसंकाशं गगने ज्वलनोपमम्।
द्वाभ्यां शराभ्यां चिच्छेद रामः शस्त्रभृतां वरः॥', 'tac chūlaṃ vajrasaṃkāśaṃ gagane jvalanopamam
dvābhyāṃ śarābhyāṃ ciccheda rāmaḥ śastrabhṛtāṃ varaḥ', null, 3003014),
('ramayana-3-3-15', 15, 'Aranya Kanda, Sarga 3, Verse 15', 'तस्य रौद्रस्य सौमित्रिर्बाहुं सव्यं बभञ्ज ह।
रामस्तु दक्षिणं बाहुं तरसा तस्य रक्षसः॥', 'tasya raudrasya saumitrir bāhuṃ savyaṃ babhañja ha
rāmas tu dakṣiṇaṃ bāhuṃ tarasā tasya rakṣasaḥ', null, 3003015),
('ramayana-3-3-16', 16, 'Aranya Kanda, Sarga 3, Verse 16', 'स भग्नबाहुः संविग्नो निपपाताशु राक्षसः।
धरण्यां मेघसंकाशो वज्रभिन्न इवाचलः।
इदं प्रोवाच काकुत्स्थं विराधः पुरुषर्षभम्॥', 'sa bhagnabāhuḥ saṃvigno nipapātāśu rākṣasaḥ
dharaṇyāṃ meghasaṃkāśo vajrabhinna ivācalaḥ
idaṃ provāca kākutsthaṃ virādhaḥ puruṣarṣabham', null, 3003016),
('ramayana-3-3-17', 17, 'Aranya Kanda, Sarga 3, Verse 17', 'कौसल्या सुप्रजास्तात रामस्त्वं विदितो मया।
वैदेही च महाभागा लक्ष्मणश्च महायशाः॥', 'kausalyā suprajās tāta rāmas tvaṃ vidito mayā
vaidehī ca mahābhāgā lakṣmaṇaś ca mahāyaśāḥ', null, 3003017),
('ramayana-3-3-18', 18, 'Aranya Kanda, Sarga 3, Verse 18', 'अभिशापादहं घोरां प्रविष्टो राक्षसीं तनुम्।
तुम्बुरुर्नाम गन्धर्वः शप्तो वैश्वरणेन हि॥', 'abhiśāpād ahaṃ ghorāṃ praviṣṭo rākṣasīṃ tanum
tumburur nāma gandharvaḥ śapto vaiśvaraṇena hi', null, 3003018),
('ramayana-3-3-19', 19, 'Aranya Kanda, Sarga 3, Verse 19', 'प्रसाद्यमानश्च मया सोऽब्रवीन्मां महायशाः।
यदा दाशरथी रामस्त्वां वधिष्यति संयुगे॥', 'prasādyamānaś ca mayā so ''bravīn māṃ mahāyaśāḥ
yadā dāśarathī rāmas tvāṃ vadhiṣyati saṃyuge', null, 3003019),
('ramayana-3-3-20', 20, 'Aranya Kanda, Sarga 3, Verse 20', 'तदा प्रकृतिमापन्नो भवान्स्वर्गं गमिष्यति।
इति वैश्रवणो राजा रम्भासक्तमुवाच ह॥', 'tadā prakṛtim āpanno bhavān svargaṃ gamiṣyati
iti vaiśravaṇo rājā rambhāsaktam uvāca ha', null, 3003020),
('ramayana-3-3-21', 21, 'Aranya Kanda, Sarga 3, Verse 21', 'अनुपस्थीयमानो मां संक्रुद्धो व्यजहार ह।
तव प्रसादान्मुक्तोऽहमभिशापात्सुदारुणात्।
भवनं स्वं गमिष्यामि स्वस्ति वोऽस्तु परंतप॥', 'anupasthīyamāno māṃ saṃkruddho vyajahāra ha
tava prasādān mukto ''ham abhiśāpāt sudāruṇāt
bhavanaṃ svaṃ gamiṣyāmi svasti vo ''stu paraṃtapa', null, 3003021),
('ramayana-3-3-22', 22, 'Aranya Kanda, Sarga 3, Verse 22', 'इतो वसति धर्मात्मा शरभङ्गः प्रतापवान्।
अध्यर्धयोजने तात महर्षिः सूर्यसंनिभः॥', 'ito vasati dharmātmā śarabhaṅgaḥ pratāpavān
adhyardhayojane tāta maharṣiḥ sūryasaṃnibhaḥ', null, 3003022),
('ramayana-3-3-23', 23, 'Aranya Kanda, Sarga 3, Verse 23', 'तं क्षिप्रमभिगच्छ त्वं स ते श्रेयो विधास्यति।
अवटे चापि मां राम निक्षिप्य कुशली व्रज॥', 'taṃ kṣipram abhigaccha tvaṃ sa te śreyo vidhāsyati
avaṭe cāpi māṃ rāma nikṣipya kuśalī vraja', null, 3003023),
('ramayana-3-3-24', 24, 'Aranya Kanda, Sarga 3, Verse 24', 'रक्षसां गतसत्त्वानामेष धर्मः सनातनः।
अवटे ये निधीयन्ते तेषां लोकाः सनातनाः॥', 'rakṣasāṃ gatasattvānām eṣa dharmaḥ sanātanaḥ
avaṭe ye nidhīyante teṣāṃ lokāḥ sanātanāḥ', null, 3003024),
('ramayana-3-3-25', 25, 'Aranya Kanda, Sarga 3, Verse 25', 'एवमुक्त्वा तु काकुत्स्थं विराधः शरपीडितः।
बभूव स्वर्गसंप्राप्तो न्यस्तदेहो महाबलः॥', 'evam uktvā tu kākutsthaṃ virādhaḥ śarapīḍitaḥ
babhūva svargasaṃprāpto nyastadeho mahābalaḥ', null, 3003025),
('ramayana-3-3-26', 26, 'Aranya Kanda, Sarga 3, Verse 26', 'तं मुक्तकण्ठमुत्क्षिप्य शङ्कुकर्णं महास्वनम्।
विराधं प्राक्षिपच्छ्वभ्रे नदन्तं भैरवस्वनम्॥', 'taṃ muktakaṇṭham utkṣipya śaṅkukarṇaṃ mahāsvanam
virādhaṃ prākṣipac chvabhre nadantaṃ bhairavasvanam', null, 3003026),
('ramayana-3-3-27', 27, 'Aranya Kanda, Sarga 3, Verse 27', 'ततस्तु तौ काञ्चनचित्रकार्मुकौ निहत्य रक्षः परिगृह्य मैथिलीम्।
विजह्रतुस्तौ मुदितौ महावने दिवि स्थितौ चन्द्रदिवाकराविव॥', 'tatas tu tau kāñcanacitrakārmukau nihatya rakṣaḥ parigṛhya maithilīm
vijahratus tau muditau mahāvane divi sthitau candradivākarāv iva', null, 3003027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 4 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-4-1', 1, 'Aranya Kanda, Sarga 4, Verse 1', 'हत्वा तु तं भीमबलं विराधं राक्षसं वने।
ततः सीतां परिष्वज्य समाश्वास्य च वीर्यवान्।
अब्रवील्लक्ष्मणां रामो भ्रातरं दीप्ततेजसं॥', 'hatvā tu taṃ bhīmabalaṃ virādhaṃ rākṣasaṃ vane
tataḥ sītāṃ pariṣvajya samāśvāsya ca vīryavān
abravīl lakṣmaṇāṃ rāmo bhrātaraṃ dīptatejasaṃ', null, 3004001),
('ramayana-3-4-2', 2, 'Aranya Kanda, Sarga 4, Verse 2', 'कष्टं वनमिदं दुर्गं न च स्मो वनगोचराः।
अभिगच्छामहे शीघ्रं शरभङ्गं तपोधनम्॥', 'kaṣṭaṃ vanam idaṃ durgaṃ na ca smo vanagocarāḥ
abhigacchāmahe śīghraṃ śarabhaṅgaṃ tapodhanam', null, 3004002),
('ramayana-3-4-3', 3, 'Aranya Kanda, Sarga 4, Verse 3', 'आश्रमं शरभङ्गस्य राघवोऽभिजगाम ह॥', 'āśramaṃ śarabhaṅgasya rāghavo ''bhijagāma ha', null, 3004003),
('ramayana-3-4-4', 4, 'Aranya Kanda, Sarga 4, Verse 4', 'तस्य देवप्रभावस्य तपसा भावितात्मनः।
समीपे शरभङ्गस्य ददर्श महदद्भुतम्॥', 'tasya devaprabhāvasya tapasā bhāvitātmanaḥ
samīpe śarabhaṅgasya dadarśa mahad adbhutam', null, 3004004),
('ramayana-3-4-5', 5, 'Aranya Kanda, Sarga 4, Verse 5', 'विभ्राजमानं वपुषा सूर्यवैश्वानरोपमम्।
असंस्पृशन्तं वसुधां ददर्श विबुधेश्वरम्॥', 'vibhrājamānaṃ vapuṣā sūryavaiśvānaropamam
asaṃspṛśantaṃ vasudhāṃ dadarśa vibudheśvaram', null, 3004005),
('ramayana-3-4-6', 6, 'Aranya Kanda, Sarga 4, Verse 6', 'सुप्रभाभरणं देवं विरजोऽम्बरधारिणम्।
तद्विधैरेव बहुभिः पूज्यमानं महात्मभिः॥', 'suprabhābharaṇaṃ devaṃ virajo ''mbaradhāriṇam
tadvidhair eva bahubhiḥ pūjyamānaṃ mahātmabhiḥ', null, 3004006),
('ramayana-3-4-7', 7, 'Aranya Kanda, Sarga 4, Verse 7', 'हरिभिर्वाजिभिर्युक्तमन्तरिक्षगतं रथम्।
ददर्शादूरतस्तस्य तरुणादित्यसंनिभम्॥', 'haribhir vājibhir yuktam antarikṣagataṃ ratham
dadarśādūratas tasya taruṇādityasaṃnibham', null, 3004007),
('ramayana-3-4-8', 8, 'Aranya Kanda, Sarga 4, Verse 8', 'पाण्डुराभ्रघनप्रख्यं चन्द्रमण्डलसंनिभम्।
अपश्यद्विमलं छत्रं चित्रमाल्योपशोभितम्॥', 'pāṇḍurābhraghanaprakhyaṃ candramaṇḍalasaṃnibham
apaśyad vimalaṃ chatraṃ citramālyopaśobhitam', null, 3004008),
('ramayana-3-4-9', 9, 'Aranya Kanda, Sarga 4, Verse 9', 'चामरव्यजने चाग्र्ये रुक्मदण्डे महाधने।
गृहीते वननारीभ्यां धूयमाने च मूर्धनि॥', 'cāmaravyajane cāgrye rukmadaṇḍe mahādhane
gṛhīte vananārībhyāṃ dhūyamāne ca mūrdhani', null, 3004009),
('ramayana-3-4-10', 10, 'Aranya Kanda, Sarga 4, Verse 10', 'गन्धर्वामरसिद्धाश्च बहवः परमर्षयः।
अन्तरिक्षगतं देवं वाग्भिरग्र्याभिरीडिरे॥', 'gandharvāmarasiddhāś ca bahavaḥ paramarṣayaḥ
antarikṣagataṃ devaṃ vāgbhir agryābhir īḍire', null, 3004010),
('ramayana-3-4-11', 11, 'Aranya Kanda, Sarga 4, Verse 11', 'दृष्ट्वा शतक्रतुं तत्र रामो लक्ष्मणमब्रवीत्।
ये हयाः पुरुहूतस्य पुरा शक्रस्य नः श्रुताः।
अन्तरिक्षगता दिव्यास्त इमे हरयो ध्रुवम्॥', 'dṛṣṭvā śatakratuṃ tatra rāmo lakṣmaṇam abravīt
ye hayāḥ puruhūtasya purā śakrasya naḥ śrutāḥ
antarikṣagatā divyās ta ime harayo dhruvam', null, 3004011),
('ramayana-3-4-12', 12, 'Aranya Kanda, Sarga 4, Verse 12', 'इमे च पुरुषव्याघ्र ये तिष्ठन्त्यभितो रथम्।
शतं शतं कुण्डलिनो युवानः खड्गपाणयः॥', 'ime ca puruṣavyāghra ye tiṣṭhanty abhito ratham
śataṃ śataṃ kuṇḍalino yuvānaḥ khaḍgapāṇayaḥ', null, 3004012),
('ramayana-3-4-13', 13, 'Aranya Kanda, Sarga 4, Verse 13', 'उरोदेशेषु सर्वेषां हारा ज्वलनसंनिभाः।
रूपं बिभ्रति सौमित्रे पञ्चविंशतिवार्षिकम्॥', 'urodeśeṣu sarveṣāṃ hārā jvalanasaṃnibhāḥ
rūpaṃ bibhrati saumitre pañcaviṃśativārṣikam', null, 3004013),
('ramayana-3-4-14', 14, 'Aranya Kanda, Sarga 4, Verse 14', 'एतद्धि किल देवानां वयो भवति नित्यदा।
यथेमे पुरुषव्याघ्रा दृश्यन्ते प्रियदर्शनाः॥', 'etad dhi kila devānāṃ vayo bhavati nityadā
yatheme puruṣavyāghrā dṛśyante priyadarśanāḥ', null, 3004014),
('ramayana-3-4-15', 15, 'Aranya Kanda, Sarga 4, Verse 15', 'इहैव सह वैदेह्या मुहूर्तं तिष्ठ लक्ष्मण।
यावज्जनाम्यहं व्यक्तं क एष द्युतिमान्रथे॥', 'ihaiva saha vaidehyā muhūrtaṃ tiṣṭha lakṣmaṇa
yāvaj janāmy ahaṃ vyaktaṃ ka eṣa dyutimān rathe', null, 3004015),
('ramayana-3-4-16', 16, 'Aranya Kanda, Sarga 4, Verse 16', 'तमेवमुक्त्वा सौमित्रिमिहैव स्थीयतामिति।
अभिचक्राम काकुत्स्थः शरभङ्गाश्रमं प्रति॥', 'tam evam uktvā saumitrim ihaiva sthīyatām iti
abhicakrāma kākutsthaḥ śarabhaṅgāśramaṃ prati', null, 3004016),
('ramayana-3-4-17', 17, 'Aranya Kanda, Sarga 4, Verse 17', 'ततः समभिगच्छन्तं प्रेक्ष्य रामं शचीपतिः।
शरभङ्गमनुज्ञाप्य विबुधानिदमब्रवीत्॥', 'tataḥ samabhigacchantaṃ prekṣya rāmaṃ śacīpatiḥ
śarabhaṅgam anujñāpya vibudhān idam abravīt', null, 3004017),
('ramayana-3-4-18', 18, 'Aranya Kanda, Sarga 4, Verse 18', 'इहोपयात्यसौ रामो यावन्मां नाभिभाषते।
निष्ठां नयत तावत्तु ततो मां द्रष्टुमर्हति॥', 'ihopayāty asau rāmo yāvan māṃ nābhibhāṣate
niṣṭhāṃ nayata tāvat tu tato māṃ draṣṭum arhati', null, 3004018),
('ramayana-3-4-19', 19, 'Aranya Kanda, Sarga 4, Verse 19', 'जितवन्तं कृतार्थं च द्रष्टाहमचिरादिमम्।
कर्म ह्यनेन कर्तव्यं महदन्यैः सुदुष्करम्॥', 'jitavantaṃ kṛtārthaṃ ca draṣṭāham acirād imam
karma hy anena kartavyaṃ mahad anyaiḥ suduṣkaram', null, 3004019),
('ramayana-3-4-20', 20, 'Aranya Kanda, Sarga 4, Verse 20', 'इति वज्री तमामन्त्र्य मानयित्वा च तापसं।
रथेन हरियुक्तेन ययौ दिवमरिंदमः॥', 'iti vajrī tam āmantrya mānayitvā ca tāpasaṃ
rathena hariyuktena yayau divam ariṃdamaḥ', null, 3004020),
('ramayana-3-4-21', 21, 'Aranya Kanda, Sarga 4, Verse 21', 'प्रयाते तु सहस्राक्षे राघवः सपरिच्छदः।
अग्निहोत्रमुपासीनं शरभङ्गमुपागमत्॥', 'prayāte tu sahasrākṣe rāghavaḥ saparicchadaḥ
agnihotram upāsīnaṃ śarabhaṅgam upāgamat', null, 3004021),
('ramayana-3-4-22', 22, 'Aranya Kanda, Sarga 4, Verse 22', 'तस्य पादौ च संगृह्य रामः सीता च लक्ष्मणः।
निषेदुस्तदनुज्ञाता लब्धवासा निमन्त्रिताः॥', 'tasya pādau ca saṃgṛhya rāmaḥ sītā ca lakṣmaṇaḥ
niṣedus tadanujñātā labdhavāsā nimantritāḥ', null, 3004022),
('ramayana-3-4-23', 23, 'Aranya Kanda, Sarga 4, Verse 23', 'ततः शक्रोपयानं तु पर्यपृच्छत्स राघवः।
शरभङ्गश्च तत्सर्वं राघवाय न्यवेदयत्॥', 'tataḥ śakropayānaṃ tu paryapṛcchat sa rāghavaḥ
śarabhaṅgaś ca tat sarvaṃ rāghavāya nyavedayat', null, 3004023),
('ramayana-3-4-24', 24, 'Aranya Kanda, Sarga 4, Verse 24', 'मामेष वरदो राम ब्रह्मलोकं निनीषति।
जितमुग्रेण तपसा दुष्प्रापमकृतात्मभिः॥', 'mām eṣa varado rāma brahmalokaṃ ninīṣati
jitam ugreṇa tapasā duṣprāpam akṛtātmabhiḥ', null, 3004024),
('ramayana-3-4-25', 25, 'Aranya Kanda, Sarga 4, Verse 25', 'अहं ज्ञात्वा नरव्याघ्र वर्तमानमदूरतः।
ब्रह्मलोकं न गच्छामि त्वामदृष्ट्वा प्रियातिथिम्॥', 'ahaṃ jñātvā naravyāghra vartamānam adūrataḥ
brahmalokaṃ na gacchāmi tvām adṛṣṭvā priyātithim', null, 3004025),
('ramayana-3-4-26', 26, 'Aranya Kanda, Sarga 4, Verse 26', 'समागम्य गमिष्यामि त्रिदिवं देवसेवितम्।
अक्षया नरशार्दूल जिता लोका मया शुभाः।
ब्राह्म्याश्च नाकपृष्ठ्याश्च प्रतिगृह्णीष्व मामकान्॥', 'samāgamya gamiṣyāmi tridivaṃ devasevitam
akṣayā naraśārdūla jitā lokā mayā śubhāḥ
brāhmyāś ca nākapṛṣṭhyāś ca pratigṛhṇīṣva māmakān', null, 3004026),
('ramayana-3-4-27', 27, 'Aranya Kanda, Sarga 4, Verse 27', 'एवमुक्तो नरव्याघ्रः सर्वशास्त्रविशारदः।
ऋषिणा शरभङ्गेन राघवो वाक्यमब्रवीत्॥', 'evam ukto naravyāghraḥ sarvaśāstraviśāradaḥ
ṛṣiṇā śarabhaṅgena rāghavo vākyam abravīt', null, 3004027),
('ramayana-3-4-28', 28, 'Aranya Kanda, Sarga 4, Verse 28', 'अहमेवाहरिष्यामि सर्वांल्लोकान्महामुने।
आवासं त्वहमिच्छामि प्रदिष्टमिह कानने॥', 'aham evāhariṣyāmi sarvāṃl lokān mahāmune
āvāsaṃ tv aham icchāmi pradiṣṭam iha kānane', null, 3004028),
('ramayana-3-4-29', 29, 'Aranya Kanda, Sarga 4, Verse 29', 'राघवेणैवमुक्तस्तु शक्रतुल्यबलेन वै।
शरभङ्गो महाप्राज्ञः पुनरेवाब्रवीद्वचः॥', 'rāghaveṇaivam uktas tu śakratulyabalena vai
śarabhaṅgo mahāprājñaḥ punar evābravīd vacaḥ', null, 3004029),
('ramayana-3-4-30', 30, 'Aranya Kanda, Sarga 4, Verse 30', 'सुतीक्ष्णमभिगच्छ त्वं शुचौ देशे तपस्विनम्।
रमणीये वनोद्देशे स ते वासं विधास्यति॥', 'sutīkṣṇam abhigaccha tvaṃ śucau deśe tapasvinam
ramaṇīye vanoddeśe sa te vāsaṃ vidhāsyati', null, 3004030),
('ramayana-3-4-31', 31, 'Aranya Kanda, Sarga 4, Verse 31', 'एष पन्था नरव्याघ्र मुहूर्तं पश्य तात माम्।
यावज्जहामि गात्राणि जीर्णं त्वचमिवोरगः॥', 'eṣa panthā naravyāghra muhūrtaṃ paśya tāta mām
yāvaj jahāmi gātrāṇi jīrṇaṃ tvacam ivoragaḥ', null, 3004031),
('ramayana-3-4-32', 32, 'Aranya Kanda, Sarga 4, Verse 32', 'ततोऽग्निं स समाधाय हुत्वा चाज्येन मन्त्रवित्।
शरभङ्गो महातेजाः प्रविवेश हुताशनम्॥', 'tato ''gniṃ sa samādhāya hutvā cājyena mantravit
śarabhaṅgo mahātejāḥ praviveśa hutāśanam', null, 3004032),
('ramayana-3-4-33', 33, 'Aranya Kanda, Sarga 4, Verse 33', 'तस्य रोमाणि केशांश्च ददाहाग्निर्महात्मनः।
जीर्णं त्वचं तथास्थीनि यच्च मांसं च शोणितम्॥', 'tasya romāṇi keśāṃś ca dadāhāgnir mahātmanaḥ
jīrṇaṃ tvacaṃ tathāsthīni yac ca māṃsaṃ ca śoṇitam', null, 3004033),
('ramayana-3-4-34', 34, 'Aranya Kanda, Sarga 4, Verse 34', 'स च पावकसंकाशः कुमारः समपद्यत।
उत्थायाग्निचयात्तस्माच्छरभङ्गो व्यरोचत॥', 'sa ca pāvakasaṃkāśaḥ kumāraḥ samapadyata
utthāyāgnicayāt tasmāc charabhaṅgo vyarocata', null, 3004034),
('ramayana-3-4-35', 35, 'Aranya Kanda, Sarga 4, Verse 35', 'स लोकानाहिताग्नीनामृषीणां च महात्मनाम्।
देवानां च व्यतिक्रम्य ब्रह्मलोकं व्यरोहत॥', 'sa lokān āhitāgnīnām ṛṣīṇāṃ ca mahātmanām
devānāṃ ca vyatikramya brahmalokaṃ vyarohata', null, 3004035),
('ramayana-3-4-36', 36, 'Aranya Kanda, Sarga 4, Verse 36', 'स पुण्यकर्मा भुवने द्विजर्षभः पितामहं सानुचरं ददर्श ह।
पितामहश्चापि समीक्ष्य तं द्विजं ननन्द सुस्वागतमित्युवाच ह॥', 'sa puṇyakarmā bhuvane dvijarṣabhaḥ pitāmahaṃ sānucaraṃ dadarśa ha
pitāmahaś cāpi samīkṣya taṃ dvijaṃ nananda susvāgatam ity uvāca ha', null, 3004036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 5 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-5-1', 1, 'Aranya Kanda, Sarga 5, Verse 1', 'शरभङ्गे दिवं प्राप्ते मुनिसंघाः समागताः।
अभ्यगच्छन्त काकुत्स्थं रामं ज्वलिततेजसं॥', 'śarabhaṅge divaṃ prāpte munisaṃghāḥ samāgatāḥ
abhyagacchanta kākutsthaṃ rāmaṃ jvalitatejasaṃ', null, 3005001),
('ramayana-3-5-2', 2, 'Aranya Kanda, Sarga 5, Verse 2', 'वैखानसा वालखिल्याः संप्रक्षाला मरीचिपाः।
अश्मकुट्टाश्च बहवः पत्राहाराश्च तापसाः॥', 'vaikhānasā vālakhilyāḥ saṃprakṣālā marīcipāḥ
aśmakuṭṭāś ca bahavaḥ patrāhārāś ca tāpasāḥ', null, 3005002),
('ramayana-3-5-3', 3, 'Aranya Kanda, Sarga 5, Verse 3', 'दन्तोलूखलिनश्चैव तथैवोन्मज्जकाः परे।
मुनयः सलिलाहारा वायुभक्षास्तथापरे॥', 'dantolūkhalinaś caiva tathaivonmajjakāḥ pare
munayaḥ salilāhārā vāyubhakṣās tathāpare', null, 3005003),
('ramayana-3-5-4', 4, 'Aranya Kanda, Sarga 5, Verse 4', 'आकाशनिलयाश्चैव तथा स्थण्डिलशायिनः।
तथोर्ध्ववासिनो दान्तास्तथार्द्रपटवाससः॥', 'ākāśanilayāś caiva tathā sthaṇḍilaśāyinaḥ
tathordhvavāsino dāntās tathārdrapaṭavāsasaḥ', null, 3005004),
('ramayana-3-5-5', 5, 'Aranya Kanda, Sarga 5, Verse 5', 'सजपाश्च तपोनित्यास्तथा पञ्चतपोऽन्विताः।
सर्वे ब्राह्म्या श्रिया जुष्टा दृढयोगसमाहिताः।
शरभङ्गाश्रमे राममभिजग्मुश्च तापसाः॥', 'sajapāś ca taponityās tathā pañcatapo''nvitāḥ
sarve brāhmyā śriyā juṣṭā dṛḍhayogasamāhitāḥ
śarabhaṅgāśrame rāmam abhijagmuś ca tāpasāḥ', null, 3005005),
('ramayana-3-5-6', 6, 'Aranya Kanda, Sarga 5, Verse 6', 'अभिगम्य च धर्मज्ञा रामं धर्मभृतां वरम्।
ऊचुः परमधर्मज्ञमृषिसंघाः समाहिताः॥', 'abhigamya ca dharmajñā rāmaṃ dharmabhṛtāṃ varam
ūcuḥ paramadharmajñam ṛṣisaṃghāḥ samāhitāḥ', null, 3005006),
('ramayana-3-5-7', 7, 'Aranya Kanda, Sarga 5, Verse 7', 'त्वमिक्ष्वाकुकुलस्यास्य पृथिव्याश्च महारथः।
प्रधानश्चासि नाथश्च देवानां मघवानिव॥', 'tvam ikṣvākukulasyāsya pṛthivyāś ca mahārathaḥ
pradhānaś cāsi nāthaś ca devānāṃ maghavān iva', null, 3005007),
('ramayana-3-5-8', 8, 'Aranya Kanda, Sarga 5, Verse 8', 'विश्रुतस्त्रिषु लोकेषु यशसा विक्रमेण च।
पितृव्रतत्वं सत्यं च त्वयि धर्मश्च पुष्कलः॥', 'viśrutas triṣu lokeṣu yaśasā vikrameṇa ca
pitṛvratatvaṃ satyaṃ ca tvayi dharmaś ca puṣkalaḥ', null, 3005008),
('ramayana-3-5-9', 9, 'Aranya Kanda, Sarga 5, Verse 9', 'त्वामासाद्य महात्मानं धर्मज्ञं धर्मवत्सलम्।
अर्थित्वान्नाथ वक्ष्यामस्तच्च नः क्षन्तुमर्हसि॥', 'tvām āsādya mahātmānaṃ dharmajñaṃ dharmavatsalam
arthitvān nātha vakṣyāmas tac ca naḥ kṣantum arhasi', null, 3005009),
('ramayana-3-5-10', 10, 'Aranya Kanda, Sarga 5, Verse 10', 'अधार्मस्तु महांस्तात भवेत्तस्य महीपतेः।
यो हरेद्बलिषड्भागं न च रक्षति पुत्रवत्॥', 'adhārmas tu mahāṃs tāta bhavet tasya mahīpateḥ
yo hared baliṣaḍbhāgaṃ na ca rakṣati putravat', null, 3005010),
('ramayana-3-5-11', 11, 'Aranya Kanda, Sarga 5, Verse 11', 'युञ्जानः स्वानिव प्राणान्प्राणैरिष्टान्सुतानिव।
नित्ययुक्तः सदा रक्षन्सर्वान्विषयवासिनः॥', 'yuñjānaḥ svān iva prāṇān prāṇair iṣṭān sutān iva
nityayuktaḥ sadā rakṣan sarvān viṣayavāsinaḥ', null, 3005011),
('ramayana-3-5-12', 12, 'Aranya Kanda, Sarga 5, Verse 12', 'प्राप्नोति शाश्वतीं राम कीर्तिं स बहुवार्षिकीम्।
ब्रह्मणः स्थानमासाद्य तत्र चापि महीयते॥', 'prāpnoti śāśvatīṃ rāma kīrtiṃ sa bahuvārṣikīm
brahmaṇaḥ sthānam āsādya tatra cāpi mahīyate', null, 3005012),
('ramayana-3-5-13', 13, 'Aranya Kanda, Sarga 5, Verse 13', 'यत्करोति परं धर्मं मुनिर्मूलफलाशनः।
तत्र राज्ञश्चतुर्भागः प्रजा धर्मेण रक्षतः॥', 'yat karoti paraṃ dharmaṃ munir mūlaphalāśanaḥ
tatra rājñaś caturbhāgaḥ prajā dharmeṇa rakṣataḥ', null, 3005013),
('ramayana-3-5-14', 14, 'Aranya Kanda, Sarga 5, Verse 14', 'सोऽयं ब्राह्मणभूयिष्ठो वानप्रस्थगणो महान्।
त्वन्नाथोऽनाथवद्राम राक्षसैर्वध्यते भृशम्॥', 'so ''yaṃ brāhmaṇabhūyiṣṭho vānaprasthagaṇo mahān
tvan nātho ''nāthavad rāma rākṣasair vadhyate bhṛśam', null, 3005014),
('ramayana-3-5-15', 15, 'Aranya Kanda, Sarga 5, Verse 15', 'एहि पश्य शरीराणि मुनीनां भावितात्मनाम्।
हतानां राक्षसैर्घोरैर्बहूनां बहुधा वने॥', 'ehi paśya śarīrāṇi munīnāṃ bhāvitātmanām
hatānāṃ rākṣasair ghorair bahūnāṃ bahudhā vane', null, 3005015),
('ramayana-3-5-16', 16, 'Aranya Kanda, Sarga 5, Verse 16', 'पम्पानदीनिवासानामनुमन्दाकिनीमपि।
चित्रकूटालयानां च क्रियते कदनं महत्॥', 'pampānadīnivāsānām anumandākinīm api
citrakūṭālayānāṃ ca kriyate kadanaṃ mahat', null, 3005016),
('ramayana-3-5-17', 17, 'Aranya Kanda, Sarga 5, Verse 17', 'एवं वयं न मृष्यामो विप्रकारं तपस्विनम्।
क्रियमाणं वने घोरं रक्षोभिर्भीमकर्मभिः॥', 'evaṃ vayaṃ na mṛṣyāmo viprakāraṃ tapasvinam
kriyamāṇaṃ vane ghoraṃ rakṣobhir bhīmakarmabhiḥ', null, 3005017),
('ramayana-3-5-18', 18, 'Aranya Kanda, Sarga 5, Verse 18', 'ततस्त्वां शरणार्थं च शरण्यं समुपस्थिताः।
परिपालय नो राम वध्यमानान्निशाचरैः॥', 'tatas tvāṃ śaraṇārthaṃ ca śaraṇyaṃ samupasthitāḥ
paripālaya no rāma vadhyamānān niśācaraiḥ', null, 3005018),
('ramayana-3-5-19', 19, 'Aranya Kanda, Sarga 5, Verse 19', 'एतच्छ्रुत्वा तु काकुत्स्थस्तापसानां तपस्विनाम्।
इदं प्रोवाच धर्मात्मा सर्वानेव तपस्विनः।
नैवमर्हथ मां वक्तुमाज्ञाप्योऽहं तपस्विनम्॥', 'etac chrutvā tu kākutsthas tāpasānāṃ tapasvinām
idaṃ provāca dharmātmā sarvān eva tapasvinaḥ
naivam arhatha māṃ vaktum ājñāpyo ''haṃ tapasvinam', null, 3005019),
('ramayana-3-5-20', 20, 'Aranya Kanda, Sarga 5, Verse 20', 'भवतामर्थसिद्ध्यर्थमागतोऽहं यदृच्छया।
तस्य मेऽयं वने वासो भविष्यति महाफलः।
तपस्विनां रणे शत्रून्हन्तुमिच्छामि राक्षसान्॥', 'bhavatām arthasiddhyartham āgato ''haṃ yadṛcchayā
tasya me ''yaṃ vane vāso bhaviṣyati mahāphalaḥ
tapasvināṃ raṇe śatrūn hantum icchāmi rākṣasān', null, 3005020),
('ramayana-3-5-21', 21, 'Aranya Kanda, Sarga 5, Verse 21', 'दत्त्वा वरं चापि तपोधनानां धर्मे धृतात्मा सहलक्ष्मणेन।
तपोधनैश्चापि सहार्य वृत्तः सुतीष्क्णमेवाभिजगाम वीरः॥', 'dattvā varaṃ cāpi tapodhanānāṃ dharme dhṛtātmā sahalakṣmaṇena
tapodhanaiś cāpi sahārya vṛttaḥ sutīṣkṇam evābhijagāma vīraḥ', null, 3005021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 6 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-6-1', 1, 'Aranya Kanda, Sarga 6, Verse 1', 'रामस्तु सहितो भ्रात्रा सीतया च परंतपः।
सुतीक्ष्णस्याश्रमपदं जगाम सह तैर्द्विजैः॥', 'rāmas tu sahito bhrātrā sītayā ca paraṃtapaḥ
sutīkṣṇasyāśramapadaṃ jagāma saha tair dvijaiḥ', null, 3006001),
('ramayana-3-6-2', 2, 'Aranya Kanda, Sarga 6, Verse 2', 'स गत्वा दूरमध्वानं नदीस्तीर्त्व बहूदकाः।
ददर्श विपुलं शैलं महामेघमिवोन्नतम्॥', 'sa gatvā dūram adhvānaṃ nadīs tīrtva bahūdakāḥ
dadarśa vipulaṃ śailaṃ mahāmegham ivonnatam', null, 3006002),
('ramayana-3-6-3', 3, 'Aranya Kanda, Sarga 6, Verse 3', 'ततस्तदिक्ष्वाकुवरौ सततं विविधैर्द्रुमैः।
काननं तौ विविशतुः सीतया सह राघवौ॥', 'tatas tad ikṣvākuvarau satataṃ vividhair drumaiḥ
kānanaṃ tau viviśatuḥ sītayā saha rāghavau', null, 3006003),
('ramayana-3-6-4', 4, 'Aranya Kanda, Sarga 6, Verse 4', 'प्रविष्टस्तु वनं घोरं बहुपुष्पफलद्रुमम्।
ददर्शाश्रममेकान्ते चीरमालापरिष्कृतम्॥', 'praviṣṭas tu vanaṃ ghoraṃ bahupuṣpaphaladrumam
dadarśāśramam ekānte cīramālāpariṣkṛtam', null, 3006004),
('ramayana-3-6-5', 5, 'Aranya Kanda, Sarga 6, Verse 5', 'तत्र तापसमासीनं मलपङ्कजटाधरम्।
रामः सुतीक्ष्णं विधिवत्तपोवृद्धमभाषत॥', 'tatra tāpasam āsīnaṃ malapaṅkajaṭādharam
rāmaḥ sutīkṣṇaṃ vidhivat tapovṛddham abhāṣata', null, 3006005),
('ramayana-3-6-6', 6, 'Aranya Kanda, Sarga 6, Verse 6', 'रामोऽहमस्मि भगवन्भवन्तं द्रष्टुमागतः।
तन्माभिवद धर्मज्ञ महर्षे सत्यविक्रम॥', 'rāmo ''ham asmi bhagavan bhavantaṃ draṣṭum āgataḥ
tan mābhivada dharmajña maharṣe satyavikrama', null, 3006006),
('ramayana-3-6-7', 7, 'Aranya Kanda, Sarga 6, Verse 7', 'स निरीक्ष्य ततो वीरं रामं धर्मभृतां वरम्।
समाश्लिष्य च बाहुभ्यामिदं वचनमब्रवीत्॥', 'sa nirīkṣya tato vīraṃ rāmaṃ dharmabhṛtāṃ varam
samāśliṣya ca bāhubhyām idaṃ vacanam abravīt', null, 3006007),
('ramayana-3-6-8', 8, 'Aranya Kanda, Sarga 6, Verse 8', 'स्वागतं खलु ते वीर राम धर्मभृतां वर।
आश्रमोऽयं त्वयाक्रान्तः सनाथ इव साम्प्रतम्॥', 'svāgataṃ khalu te vīra rāma dharmabhṛtāṃ vara
āśramo ''yaṃ tvayākrāntaḥ sanātha iva sāmpratam', null, 3006008),
('ramayana-3-6-9', 9, 'Aranya Kanda, Sarga 6, Verse 9', 'प्रतीक्षमाणस्त्वामेव नारोहेऽहं महायशः।
देवलोकमितो वीर देहं त्यक्त्वा महीतले॥', 'pratīkṣamāṇas tvām eva nārohe ''haṃ mahāyaśaḥ
devalokam ito vīra dehaṃ tyaktvā mahītale', null, 3006009),
('ramayana-3-6-10', 10, 'Aranya Kanda, Sarga 6, Verse 10', 'चित्रकूटमुपादाय राज्यभ्रष्टोऽसि मे श्रुतः।
इहोपयातः काकुत्स्थो देवराजः शतक्रतुः।
सर्वांल्लोकाञ्जितानाह मम पुण्येन कर्मणा॥', 'citrakūṭam upādāya rājyabhraṣṭo ''si me śrutaḥ
ihopayātaḥ kākutstho devarājaḥ śatakratuḥ
sarvāṃl lokāñ jitān āha mama puṇyena karmaṇā', null, 3006010),
('ramayana-3-6-11', 11, 'Aranya Kanda, Sarga 6, Verse 11', 'तेषु देवर्षिजुष्टेषु जितेषु तपसा मया।
मत्प्रसादात्सभार्यस्त्वं विहरस्व सलक्ष्मणः॥', 'teṣu devarṣijuṣṭeṣu jiteṣu tapasā mayā
matprasādāt sabhāryas tvaṃ viharasva salakṣmaṇaḥ', null, 3006011),
('ramayana-3-6-12', 12, 'Aranya Kanda, Sarga 6, Verse 12', 'तमुग्रतपसं दीप्तं महर्षिं सत्यवादिनम्।
प्रत्युवाचात्मवान्रामो ब्रह्माणमिव वासवः॥', 'tam ugratapasaṃ dīptaṃ maharṣiṃ satyavādinam
pratyuvācātmavān rāmo brahmāṇam iva vāsavaḥ', null, 3006012),
('ramayana-3-6-13', 13, 'Aranya Kanda, Sarga 6, Verse 13', 'अहमेवाहरिष्यामि स्वयं लोकान्महामुने।
आवासं त्वहमिच्छामि प्रदिष्टमिह कानने॥', 'aham evāhariṣyāmi svayaṃ lokān mahāmune
āvāsaṃ tv aham icchāmi pradiṣṭam iha kānane', null, 3006013),
('ramayana-3-6-14', 14, 'Aranya Kanda, Sarga 6, Verse 14', 'भवान्सर्वत्र कुशलः सर्वभूतहिते रतः।
आख्यातः शरभङ्गेन गौतमेन महात्मना॥', 'bhavān sarvatra kuśalaḥ sarvabhūtahite rataḥ
ākhyātaḥ śarabhaṅgena gautamena mahātmanā', null, 3006014),
('ramayana-3-6-15', 15, 'Aranya Kanda, Sarga 6, Verse 15', 'एवमुक्तस्तु रामेण महर्षिर्लोकविश्रुतः।
अब्रवीन्मधुरं वाक्यं हर्षेण महताप्लुतः॥', 'evam uktas tu rāmeṇa maharṣir lokaviśrutaḥ
abravīn madhuraṃ vākyaṃ harṣeṇa mahatāplutaḥ', null, 3006015),
('ramayana-3-6-16', 16, 'Aranya Kanda, Sarga 6, Verse 16', 'अयमेवाश्रमो राम गुणवान्रम्यतामिह।
ऋषिसंघानुचरितः सदा मूलफलैर्युतः॥', 'ayam evāśramo rāma guṇavān ramyatām iha
ṛṣisaṃghānucaritaḥ sadā mūlaphalair yutaḥ', null, 3006016),
('ramayana-3-6-17', 17, 'Aranya Kanda, Sarga 6, Verse 17', 'इममाश्रममागम्य मृगसंघा महायशाः।
अटित्वा प्रतिगच्छन्ति लोभयित्वाकुतोभयाः॥', 'imam āśramam āgamya mṛgasaṃghā mahāyaśāḥ
aṭitvā pratigacchanti lobhayitvākutobhayāḥ', null, 3006017),
('ramayana-3-6-18', 18, 'Aranya Kanda, Sarga 6, Verse 18', 'तच्छ्रुत्वा वचनं तस्य महर्षेर्लक्ष्मणाग्रजः।
उवाच वचनं धीरो विकृष्य सशरं धनुः॥', 'tac chrutvā vacanaṃ tasya maharṣer lakṣmaṇāgrajaḥ
uvāca vacanaṃ dhīro vikṛṣya saśaraṃ dhanuḥ', null, 3006018),
('ramayana-3-6-19', 19, 'Aranya Kanda, Sarga 6, Verse 19', 'तानहं सुमहाभाग मृगसंघान्समागतान्।
हन्यां निशितधारेण शरेणाशनिवर्चसा॥', 'tān ahaṃ sumahābhāga mṛgasaṃghān samāgatān
hanyāṃ niśitadhāreṇa śareṇāśanivarcasā', null, 3006019),
('ramayana-3-6-20', 20, 'Aranya Kanda, Sarga 6, Verse 20', 'भवांस्तत्राभिषज्येत किं स्यात्कृच्छ्रतरं ततः।
एतस्मिन्नाश्रमे वासं चिरं तु न समर्थये॥', 'bhavāṃs tatrābhiṣajyeta kiṃ syāt kṛcchrataraṃ tataḥ
etasminn āśrame vāsaṃ ciraṃ tu na samarthaye', null, 3006020),
('ramayana-3-6-21', 21, 'Aranya Kanda, Sarga 6, Verse 21', 'तमेवमुक्त्वा वरदं रामः संध्यामुपागमत्।
अन्वास्य पश्चिमां संध्यां तत्र वासमकल्पयत्॥', 'tam evam uktvā varadaṃ rāmaḥ saṃdhyām upāgamat
anvāsya paścimāṃ saṃdhyāṃ tatra vāsam akalpayat', null, 3006021),
('ramayana-3-6-22', 22, 'Aranya Kanda, Sarga 6, Verse 22', 'ततः शुभं तापसभोज्यमन्नं स्वयं सुतीक्ष्णः पुरुषर्षभाभ्याम्।
ताभ्यां सुसत्कृत्य ददौ महात्मा संध्यानिवृत्तौ रजनीं समीक्ष्य॥', 'tataḥ śubhaṃ tāpasabhojyam annaṃ svayaṃ sutīkṣṇaḥ puruṣarṣabhābhyām
tābhyāṃ susatkṛtya dadau mahātmā saṃdhyānivṛttau rajanīṃ samīkṣya', null, 3006022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 7 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-7-1', 1, 'Aranya Kanda, Sarga 7, Verse 1', 'रामस्तु सहसौमित्रिः सुतीक्ष्णेनाभिपूजितः।
परिणम्य निशां तत्र प्रभाते प्रत्यबुध्यत॥', 'rāmas tu sahasaumitriḥ sutīkṣṇenābhipūjitaḥ
pariṇamya niśāṃ tatra prabhāte pratyabudhyata', null, 3007001),
('ramayana-3-7-2', 2, 'Aranya Kanda, Sarga 7, Verse 2', 'उत्थाय तु यथाकालं राघवः सह सीतया।
उपास्पृशत्सुशीतेन जलेनोत्पलगन्धिना॥', 'utthāya tu yathākālaṃ rāghavaḥ saha sītayā
upāspṛśat suśītena jalenotpalagandhinā', null, 3007002),
('ramayana-3-7-3', 3, 'Aranya Kanda, Sarga 7, Verse 3', 'अथ तेऽग्निं सुरांश्चैव वैदेही रामलक्ष्मणौ।
काल्यं विधिवदभ्यर्च्य तपस्विशरणे वने॥', 'atha te ''gniṃ surāṃś caiva vaidehī rāmalakṣmaṇau
kālyaṃ vidhivad abhyarcya tapasviśaraṇe vane', null, 3007003),
('ramayana-3-7-4', 4, 'Aranya Kanda, Sarga 7, Verse 4', 'उदयन्न्तं दिनकरं दृष्ट्वा विगतकल्मषाः।
सुतीक्ष्णमभिगम्येदं श्लक्ष्णं वचनमब्रुवन्॥', 'udayanntaṃ dinakaraṃ dṛṣṭvā vigatakalmaṣāḥ
sutīkṣṇam abhigamyedaṃ ślakṣṇaṃ vacanam abruvan', null, 3007004),
('ramayana-3-7-5', 5, 'Aranya Kanda, Sarga 7, Verse 5', 'सुखोषिताः स्म भगवंस्त्वया पूज्येन पूजिताः।
आपृच्छामः प्रयास्यामो मुनयस्त्वरयन्ति नः॥', 'sukhoṣitāḥ sma bhagavaṃs tvayā pūjyena pūjitāḥ
āpṛcchāmaḥ prayāsyāmo munayas tvarayanti naḥ', null, 3007005),
('ramayana-3-7-6', 6, 'Aranya Kanda, Sarga 7, Verse 6', 'त्वरामहे वयं द्रष्टुं कृत्स्नमाश्रममण्डलम्।
ऋषीणां पुण्यशीलानां दण्डकारण्यवासिनाम्॥', 'tvarāmahe vayaṃ draṣṭuṃ kṛtsnam āśramamaṇḍalam
ṛṣīṇāṃ puṇyaśīlānāṃ daṇḍakāraṇyavāsinām', null, 3007006),
('ramayana-3-7-7', 7, 'Aranya Kanda, Sarga 7, Verse 7', 'अभ्यनुज्ञातुमिच्छामः सहैभिर्मुनिपुङ्गवैः।
धर्मनित्यैस्तपोदान्तैर्विशिखैरिव पावकैः॥', 'abhyanujñātum icchāmaḥ sahaibhir munipuṅgavaiḥ
dharmanityais tapodāntair viśikhair iva pāvakaiḥ', null, 3007007),
('ramayana-3-7-8', 8, 'Aranya Kanda, Sarga 7, Verse 8', 'अविषह्यातपो यावत्सूर्यो नातिविराजिते।
अमार्गेणागतां लक्ष्मीं प्राप्येवान्वयवर्जितः॥', 'aviṣahyātapo yāvat sūryo nātivirājite
amārgeṇāgatāṃ lakṣmīṃ prāpyevānvayavarjitaḥ', null, 3007008),
('ramayana-3-7-9', 9, 'Aranya Kanda, Sarga 7, Verse 9', 'तावदिच्छामहे गन्तुमित्युक्त्वा चरणौ मुनेः।
ववन्दे सहसौमित्रिः सीतया सह राघवः॥', 'tāvad icchāmahe gantum ity uktvā caraṇau muneḥ
vavande sahasaumitriḥ sītayā saha rāghavaḥ', null, 3007009),
('ramayana-3-7-10', 10, 'Aranya Kanda, Sarga 7, Verse 10', 'तौ संस्पृशन्तौ चरणावुत्थाप्य मुनिपुंगवः।
गाढमालिङ्ग्य सस्नेहमिदं वचनमब्रवीत्॥', 'tau saṃspṛśantau caraṇāv utthāpya munipuṃgavaḥ
gāḍham āliṅgya sasneham idaṃ vacanam abravīt', null, 3007010),
('ramayana-3-7-11', 11, 'Aranya Kanda, Sarga 7, Verse 11', 'अरिष्टं गच्छ पन्थानं राम सौमित्रिणा सह।
सीतया चानया सार्धं छाययेवानुवृत्तया॥', 'ariṣṭaṃ gaccha panthānaṃ rāma saumitriṇā saha
sītayā cānayā sārdhaṃ chāyayevānuvṛttayā', null, 3007011),
('ramayana-3-7-12', 12, 'Aranya Kanda, Sarga 7, Verse 12', 'पश्याश्रमपदं रम्यं दण्डकारण्यवासिनाम्।
एषां तपस्विनां वीर तपसा भावितात्मनाम्॥', 'paśyāśramapadaṃ ramyaṃ daṇḍakāraṇyavāsinām
eṣāṃ tapasvināṃ vīra tapasā bhāvitātmanām', null, 3007012),
('ramayana-3-7-13', 13, 'Aranya Kanda, Sarga 7, Verse 13', 'सुप्राज्यफलमूलानि पुष्पितानि वनानि च।
प्रशान्तमृगयूथानि शान्तपक्षिगणानि च॥', 'suprājyaphalamūlāni puṣpitāni vanāni ca
praśāntamṛgayūthāni śāntapakṣigaṇāni ca', null, 3007013),
('ramayana-3-7-14', 14, 'Aranya Kanda, Sarga 7, Verse 14', 'फुल्लपङ्कजषडानि प्रसन्नसलिलानि च।
कारण्डवविकीर्णानि तटाकानि सरांसि च॥', 'phullapaṅkajaṣaḍāni prasannasalilāni ca
kāraṇḍavavikīrṇāni taṭākāni sarāṃsi ca', null, 3007014),
('ramayana-3-7-15', 15, 'Aranya Kanda, Sarga 7, Verse 15', 'द्रक्ष्यसे दृष्टिरम्याणि गिरिप्रस्रवणानि च।
रमणीयान्यरण्यानि मयूराभिरुतानि च॥', 'drakṣyase dṛṣṭiramyāṇi giriprasravaṇāni ca
ramaṇīyāny araṇyāni mayūrābhirutāni ca', null, 3007015),
('ramayana-3-7-16', 16, 'Aranya Kanda, Sarga 7, Verse 16', 'गम्यतां वत्स सौमित्रे भवानपि च गच्छतु।
आगन्तव्यं च ते दृष्ट्वा पुनरेवाश्रमं मम॥', 'gamyatāṃ vatsa saumitre bhavān api ca gacchatu
āgantavyaṃ ca te dṛṣṭvā punar evāśramaṃ mama', null, 3007016),
('ramayana-3-7-17', 17, 'Aranya Kanda, Sarga 7, Verse 17', 'एवमुक्तस्तथेत्युक्त्वा काकुत्स्थः सहलक्ष्मणः।
प्रदक्षिणं मुनिं कृता प्रस्थातुमुपचक्रमे॥', 'evam uktas tathety uktvā kākutsthaḥ sahalakṣmaṇaḥ
pradakṣiṇaṃ muniṃ kṛtā prasthātum upacakrame', null, 3007017),
('ramayana-3-7-18', 18, 'Aranya Kanda, Sarga 7, Verse 18', 'ततः शुभतरे तूणी धनुषी चायतेक्षणा।
ददौ सीता तयोर्भ्रात्रोः खड्गौ च विमलौ ततः॥', 'tataḥ śubhatare tūṇī dhanuṣī cāyatekṣaṇā
dadau sītā tayor bhrātroḥ khaḍgau ca vimalau tataḥ', null, 3007018),
('ramayana-3-7-19', 19, 'Aranya Kanda, Sarga 7, Verse 19', 'आबध्य च शुभे तूणी चापे चादाय सस्वने।
निष्क्रान्तावाश्रमाद्गन्तुमुभौ तौ रामलक्ष्मणौ॥', 'ābadhya ca śubhe tūṇī cāpe cādāya sasvane
niṣkrāntāv āśramād gantum ubhau tau rāmalakṣmaṇau', null, 3007019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 8 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-8-1', 1, 'Aranya Kanda, Sarga 8, Verse 1', 'सुतीक्ष्णेनाभ्यनुज्ञातं प्रस्थितं रघुनन्दनम्।
वैदेही स्निग्धया वाचा भर्तारमिदमब्रवीत्॥', 'sutīkṣṇenābhyanujñātaṃ prasthitaṃ raghunandanam
vaidehī snigdhayā vācā bhartāram idam abravīt', null, 3008001),
('ramayana-3-8-2', 2, 'Aranya Kanda, Sarga 8, Verse 2', 'अयं धर्मः सुसूक्ष्मेण विधिना प्राप्यते महान्।
निवृत्तेन च शक्योऽयं व्यसनात्कामजादिह॥', 'ayaṃ dharmaḥ susūkṣmeṇa vidhinā prāpyate mahān
nivṛttena ca śakyo ''yaṃ vyasanāt kāmajād iha', null, 3008002),
('ramayana-3-8-3', 3, 'Aranya Kanda, Sarga 8, Verse 3', 'त्रीण्येव व्यसनान्यत्र कामजानि भवन्त्युत।
मिथ्या वाक्यं परमकं तस्माद्गुरुतरावुभौ।
परदाराभिगमनं विना वैरं च रौद्रता॥', 'trīṇy eva vyasanāny atra kāmajāni bhavanty uta
mithyā vākyaṃ paramakaṃ tasmād gurutarāv ubhau
paradārābhigamanaṃ vinā vairaṃ ca raudratā', null, 3008003),
('ramayana-3-8-4', 4, 'Aranya Kanda, Sarga 8, Verse 4', 'मिथ्यावाक्यं न ते भूतं न भविष्यति राघव।
कुतोऽभिलषणं स्त्रीणां परेषां धर्मनाशनम्॥', 'mithyāvākyaṃ na te bhūtaṃ na bhaviṣyati rāghava
kuto ''bhilaṣaṇaṃ strīṇāṃ pareṣāṃ dharmanāśanam', null, 3008004),
('ramayana-3-8-5', 5, 'Aranya Kanda, Sarga 8, Verse 5', 'तच्च सर्वं महाबाहो शक्यं वोढुं जितेन्द्रियैः।
तव वश्येन्द्रियत्वं च जानामि शुभदर्शन॥', 'tac ca sarvaṃ mahābāho śakyaṃ voḍhuṃ jitendriyaiḥ
tava vaśyendriyatvaṃ ca jānāmi śubhadarśana', null, 3008005),
('ramayana-3-8-6', 6, 'Aranya Kanda, Sarga 8, Verse 6', 'तृतीयं यदिदं रौद्रं परप्राणाभिहिंसनम्।
निर्वैरं क्रियते मोहात्तच्च ते समुपस्थितम्॥', 'tṛtīyaṃ yad idaṃ raudraṃ paraprāṇābhihiṃsanam
nirvairaṃ kriyate mohāt tac ca te samupasthitam', null, 3008006),
('ramayana-3-8-7', 7, 'Aranya Kanda, Sarga 8, Verse 7', 'प्रतिज्ञातस्त्वया वीर दण्डकारण्यवासिनाम्।
ऋषीणां रक्षणार्थाय वधः संयति रक्षसाम्॥', 'pratijñātas tvayā vīra daṇḍakāraṇyavāsinām
ṛṣīṇāṃ rakṣaṇārthāya vadhaḥ saṃyati rakṣasām', null, 3008007),
('ramayana-3-8-8', 8, 'Aranya Kanda, Sarga 8, Verse 8', 'एतन्निमित्तं च वनं दण्डका इति विश्रुतम्।
प्रस्थितस्त्वं सह भ्रात्रा धृतबाणशरासनः॥', 'etannimittaṃ ca vanaṃ daṇḍakā iti viśrutam
prasthitas tvaṃ saha bhrātrā dhṛtabāṇaśarāsanaḥ', null, 3008008),
('ramayana-3-8-9', 9, 'Aranya Kanda, Sarga 8, Verse 9', 'ततस्त्वां प्रस्थितं दृष्ट्वा मम चिन्ताकुलं मनः।
त्वद्वृत्तं चिन्तयन्त्या वै भवेन्निःश्रेयसं हितम्॥', 'tatas tvāṃ prasthitaṃ dṛṣṭvā mama cintākulaṃ manaḥ
tvad vṛttaṃ cintayantyā vai bhaven niḥśreyasaṃ hitam', null, 3008009),
('ramayana-3-8-10', 10, 'Aranya Kanda, Sarga 8, Verse 10', 'न हि मे रोचते वीर गमनं दण्डकान्प्रति।
कारणं तत्र वक्ष्यामि वदन्त्याः श्रूयतां मम॥', 'na hi me rocate vīra gamanaṃ daṇḍakān prati
kāraṇaṃ tatra vakṣyāmi vadantyāḥ śrūyatāṃ mama', null, 3008010),
('ramayana-3-8-11', 11, 'Aranya Kanda, Sarga 8, Verse 11', 'त्वं हि बाणधनुष्पाणिर्भ्रात्रा सह वनं गतः।
दृष्ट्वा वनचरान्सर्वान्कच्चित्कुर्याः शरव्ययम्॥', 'tvaṃ hi bāṇadhanuṣpāṇir bhrātrā saha vanaṃ gataḥ
dṛṣṭvā vanacarān sarvān kaccit kuryāḥ śaravyayam', null, 3008011),
('ramayana-3-8-12', 12, 'Aranya Kanda, Sarga 8, Verse 12', 'क्षत्रियाणामिह धनुर्हुताशस्येन्धनानि च।
समीपतः स्थितं तेजोबलमुच्छ्रयते भृशम्॥', 'kṣatriyāṇām iha dhanur hutāśasyendhanāni ca
samīpataḥ sthitaṃ tejobalam ucchrayate bhṛśam', null, 3008012),
('ramayana-3-8-13', 13, 'Aranya Kanda, Sarga 8, Verse 13', 'पुरा किल महाबाहो तपस्वी सत्यवाक्शुचिः।
कस्मिंश्चिदभवत्पुण्ये वने रतमृगद्विजे॥', 'purā kila mahābāho tapasvī satyavāk śuciḥ
kasmiṃś cid abhavat puṇye vane ratamṛgadvije', null, 3008013),
('ramayana-3-8-14', 14, 'Aranya Kanda, Sarga 8, Verse 14', 'तस्यैव तपसो विघ्नं कर्तुमिन्द्रः शचीपतिः।
खड्गपाणिरथागच्छदाश्रमं भट रूपधृक्॥', 'tasyaiva tapaso vighnaṃ kartum indraḥ śacīpatiḥ
khaḍgapāṇir athāgacchad āśramaṃ bhaṭa rūpadhṛk', null, 3008014),
('ramayana-3-8-15', 15, 'Aranya Kanda, Sarga 8, Verse 15', 'तस्मिंस्तदाश्रमपदे निहितः खड्ग उत्तमः।
स न्यासविधिना दत्तः पुण्ये तपसि तिष्ठतः॥', 'tasmiṃs tad āśramapade nihitaḥ khaḍga uttamaḥ
sa nyāsavidhinā dattaḥ puṇye tapasi tiṣṭhataḥ', null, 3008015),
('ramayana-3-8-16', 16, 'Aranya Kanda, Sarga 8, Verse 16', 'स तच्छस्त्रमनुप्राप्य न्यासरक्षणतत्परः।
वने तु विचरत्येव रक्षन्प्रत्ययमात्मनः॥', 'sa tac chastram anuprāpya nyāsarakṣaṇatatparaḥ
vane tu vicaraty eva rakṣan pratyayam ātmanaḥ', null, 3008016),
('ramayana-3-8-17', 17, 'Aranya Kanda, Sarga 8, Verse 17', 'यत्र गच्छत्युपादातुं मूलानि च फलानि च।
न विना याति तं खड्गं न्यासरक्षणतत्परः॥', 'yatra gacchaty upādātuṃ mūlāni ca phalāni ca
na vinā yāti taṃ khaḍgaṃ nyāsarakṣaṇatatparaḥ', null, 3008017),
('ramayana-3-8-18', 18, 'Aranya Kanda, Sarga 8, Verse 18', 'नित्यं शस्त्रं परिवहन्क्रमेण स तपोधनः।
चकार रौद्रीं स्वां बुद्धिं त्यक्त्वा तपसि निश्चयम्॥', 'nityaṃ śastraṃ parivahan krameṇa sa tapodhanaḥ
cakāra raudrīṃ svāṃ buddhiṃ tyaktvā tapasi niścayam', null, 3008018),
('ramayana-3-8-19', 19, 'Aranya Kanda, Sarga 8, Verse 19', 'ततः स रौद्राभिरतः प्रमत्तोऽधर्मकर्षितः।
तस्य शस्त्रस्य संवासाज्जगाम नरकं मुनिः॥', 'tataḥ sa raudrābhirataḥ pramatto ''dharmakarṣitaḥ
tasya śastrasya saṃvāsāj jagāma narakaṃ muniḥ', null, 3008019),
('ramayana-3-8-20', 20, 'Aranya Kanda, Sarga 8, Verse 20', 'स्नेहाच्च बहुमानाच्च स्मारये त्वां न शिक्षये।
न कथं चन सा कार्या हृहीतधनुषा त्वया॥', 'snehāc ca bahumānāc ca smāraye tvāṃ na śikṣaye
na kathaṃ cana sā kāryā hṛhītadhanuṣā tvayā', null, 3008020),
('ramayana-3-8-21', 21, 'Aranya Kanda, Sarga 8, Verse 21', 'बुद्धिर्वैरं विना हन्तुं राक्षसान्दण्डकाश्रितान्।
अपराधं विना हन्तुं लोकान्वीर न कामये॥', 'buddhir vairaṃ vinā hantuṃ rākṣasān daṇḍakāśritān
aparādhaṃ vinā hantuṃ lokān vīra na kāmaye', null, 3008021),
('ramayana-3-8-22', 22, 'Aranya Kanda, Sarga 8, Verse 22', 'क्षत्रियाणां तु वीराणां वनेषु नियतात्मनाम्।
धनुषा कार्यमेतावदार्तानामभिरक्षणम्॥', 'kṣatriyāṇāṃ tu vīrāṇāṃ vaneṣu niyatātmanām
dhanuṣā kāryam etāvad ārtānām abhirakṣaṇam', null, 3008022),
('ramayana-3-8-23', 23, 'Aranya Kanda, Sarga 8, Verse 23', 'क्व च शस्त्रं क्व च वनं क्व च क्षात्रं तपः क्व च।
व्याविद्धमिदमस्माभिर्देशधर्मस्तु पूज्यताम्॥', 'kva ca śastraṃ kva ca vanaṃ kva ca kṣātraṃ tapaḥ kva ca
vyāviddham idam asmābhir deśadharmas tu pūjyatām', null, 3008023),
('ramayana-3-8-24', 24, 'Aranya Kanda, Sarga 8, Verse 24', 'तदार्यकलुषा बुद्धिर्जायते शस्त्रसेवनात्।
पुनर्गत्वा त्वयोध्यायां क्षत्रधर्मं चरिष्यसि॥', 'tad āryakaluṣā buddhir jāyate śastrasevanāt
punar gatvā tv ayodhyāyāṃ kṣatradharmaṃ cariṣyasi', null, 3008024),
('ramayana-3-8-25', 25, 'Aranya Kanda, Sarga 8, Verse 25', 'अक्षया तु भवेत्प्रीतिः श्वश्रू श्वशुरयोर्मम।
यदि राज्यं हि संन्यस्य भवेस्त्वं निरतो मुनिः॥', 'akṣayā tu bhavet prītiḥ śvaśrū śvaśurayor mama
yadi rājyaṃ hi saṃnyasya bhaves tvaṃ nirato muniḥ', null, 3008025),
('ramayana-3-8-26', 26, 'Aranya Kanda, Sarga 8, Verse 26', 'धर्मादर्थः प्रभवति धर्मात्प्रभवते सुखम्।
धर्मेण लभते सर्वं धर्मसारमिदं जगत्॥', 'dharmād arthaḥ prabhavati dharmāt prabhavate sukham
dharmeṇa labhate sarvaṃ dharmasāram idaṃ jagat', null, 3008026),
('ramayana-3-8-27', 27, 'Aranya Kanda, Sarga 8, Verse 27', 'आत्मानं नियमैस्तैस्तैः कर्षयित्वा प्रयत्नतः।
प्राप्यते निपुणैर्धर्मो न सुखाल्लभ्यते सुखम्॥', 'ātmānaṃ niyamais tais taiḥ karṣayitvā prayatnataḥ
prāpyate nipuṇair dharmo na sukhāl labhyate sukham', null, 3008027),
('ramayana-3-8-28', 28, 'Aranya Kanda, Sarga 8, Verse 28', 'नित्यं शुचिमतिः सौम्य चर धर्मं तपोवने।
सर्वं हि विदितं तुभ्यं त्रैलोक्यमपि तत्त्वतः॥', 'nityaṃ śucimatiḥ saumya cara dharmaṃ tapovane
sarvaṃ hi viditaṃ tubhyaṃ trailokyam api tattvataḥ', null, 3008028),
('ramayana-3-8-29', 29, 'Aranya Kanda, Sarga 8, Verse 29', 'स्त्रीचापलादेतदुदाहृतं मे धर्मं च वक्तुं तव कः समर्थः।
विचार्य बुद्ध्या तु सहानुजेन यद्रोचते तत्कुरु माचिरेण॥', 'strīcāpalād etad udāhṛtaṃ me dharmaṃ ca vaktuṃ tava kaḥ samarthaḥ
vicārya buddhyā tu sahānujena yad rocate tat kuru mācireṇa', null, 3008029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 9 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-9-1', 1, 'Aranya Kanda, Sarga 9, Verse 1', 'वाक्यमेतत्तु वैदेह्या व्याहृतं भर्तृभक्तया।
श्रुत्वा धर्मे स्थितो रामः प्रत्युवाचाथ मैथिलीम्॥', 'vākyam etat tu vaidehyā vyāhṛtaṃ bhartṛbhaktayā
śrutvā dharme sthito rāmaḥ pratyuvācātha maithilīm', null, 3009001),
('ramayana-3-9-2', 2, 'Aranya Kanda, Sarga 9, Verse 2', 'हितमुक्तं त्वया देवि स्निग्धया सदृशं वचः।
कुलं व्यपदिशन्त्या च धर्मज्ञे जनकात्मजे॥', 'hitam uktaṃ tvayā devi snigdhayā sadṛśaṃ vacaḥ
kulaṃ vyapadiśantyā ca dharmajñe janakātmaje', null, 3009002),
('ramayana-3-9-3', 3, 'Aranya Kanda, Sarga 9, Verse 3', 'किं तु वक्ष्याम्यहं देवि त्वयैवोक्तमिदं वचः।
क्षत्रियैर्धार्यते चापो नार्तशब्दो भवेदिति॥', 'kiṃ tu vakṣyāmy ahaṃ devi tvayaivoktam idaṃ vacaḥ
kṣatriyair dhāryate cāpo nārtaśabdo bhaved iti', null, 3009003),
('ramayana-3-9-4', 4, 'Aranya Kanda, Sarga 9, Verse 4', 'ते चार्ता दण्डकारण्ये मुनयः संशितव्रताः।
मां सीते स्वयमागम्य शरण्याः शरणं गताः॥', 'te cārtā daṇḍakāraṇye munayaḥ saṃśitavratāḥ
māṃ sīte svayam āgamya śaraṇyāḥ śaraṇaṃ gatāḥ', null, 3009004),
('ramayana-3-9-5', 5, 'Aranya Kanda, Sarga 9, Verse 5', 'वसन्तो धर्मनिरता वने मूलफलाशनाः।
न लभन्ते सुखं भीता राक्षसैः क्रूरकर्मभिः॥', 'vasanto dharmaniratā vane mūlaphalāśanāḥ
na labhante sukhaṃ bhītā rākṣasaiḥ krūrakarmabhiḥ', null, 3009005),
('ramayana-3-9-6', 6, 'Aranya Kanda, Sarga 9, Verse 6', 'काले काले च निरता नियमैर्विविधैर्वने।
भक्ष्यन्ते राक्षसैर्भीमैर्नरमांसोपजीविभिः॥', 'kāle kāle ca niratā niyamair vividhair vane
bhakṣyante rākṣasair bhīmair naramāṃsopajīvibhiḥ', null, 3009006),
('ramayana-3-9-7', 7, 'Aranya Kanda, Sarga 9, Verse 7', 'ते भक्ष्यमाणा मुनयो दण्डकारण्यवासिनः।
अस्मानभ्यवपद्येति मामूचुर्द्विजसत्तमाः॥', 'te bhakṣyamāṇā munayo daṇḍakāraṇyavāsinaḥ
asmān abhyavapadyeti mām ūcur dvijasattamāḥ', null, 3009007),
('ramayana-3-9-8', 8, 'Aranya Kanda, Sarga 9, Verse 8', 'मया तु वचनं श्रुत्वा तेषामेवं मुखाच्च्युतम्।
कृत्वा चरणशुश्रूषां वाक्यमेतदुदाहृतम्॥', 'mayā tu vacanaṃ śrutvā teṣām evaṃ mukhāc cyutam
kṛtvā caraṇaśuśrūṣāṃ vākyam etad udāhṛtam', null, 3009008),
('ramayana-3-9-9', 9, 'Aranya Kanda, Sarga 9, Verse 9', 'प्रसीदन्तु भवन्तो मे ह्रीरेषा हि ममातुला।
यदीदृशैरहं विप्रैरुपस्थेयैरुपस्थितः।
किं करोमीति च मया व्याहृतं द्विजसंनिधौ॥', 'prasīdantu bhavanto me hrīr eṣā hi mamātulā
yadīdṛśair ahaṃ viprair upastheyair upasthitaḥ
kiṃ karomīti ca mayā vyāhṛtaṃ dvijasaṃnidhau', null, 3009009),
('ramayana-3-9-10', 10, 'Aranya Kanda, Sarga 9, Verse 10', 'सर्वैरेव समागम्य वागियं समुदाहृता।
राक्षसैर्दण्डकारण्ये बहुभिः कामरूपिभिः।
अर्दिताः स्म भृशं राम भवान्नस्त्रातुमर्हति॥', 'sarvair eva samāgamya vāg iyaṃ samudāhṛtā
rākṣasair daṇḍakāraṇye bahubhiḥ kāmarūpibhiḥ
arditāḥ sma bhṛśaṃ rāma bhavān nas trātum arhati', null, 3009010),
('ramayana-3-9-11', 11, 'Aranya Kanda, Sarga 9, Verse 11', 'होमकाले तु संप्राप्ते पर्वकालेषु चानघ।
धर्षयन्ति स्म दुर्धर्षा राक्षसाः पिशिताशनाः॥', 'homakāle tu saṃprāpte parvakāleṣu cānagha
dharṣayanti sma durdharṣā rākṣasāḥ piśitāśanāḥ', null, 3009011),
('ramayana-3-9-12', 12, 'Aranya Kanda, Sarga 9, Verse 12', 'राक्षसैर्धर्षितानां च तापसानां तपस्विनाम्।
गतिं मृगयमाणानां भवान्नः परमा गतिः॥', 'rākṣasair dharṣitānāṃ ca tāpasānāṃ tapasvinām
gatiṃ mṛgayamāṇānāṃ bhavān naḥ paramā gatiḥ', null, 3009012),
('ramayana-3-9-13', 13, 'Aranya Kanda, Sarga 9, Verse 13', 'कामं तपः प्रभावेन शक्ता हन्तुं निशाचरान्।
चिरार्जितं तु नेच्छामस्तपः खण्डयितुं वयम्॥', 'kāmaṃ tapaḥ prabhāvena śaktā hantuṃ niśācarān
cirārjitaṃ tu necchāmas tapaḥ khaṇḍayituṃ vayam', null, 3009013),
('ramayana-3-9-14', 14, 'Aranya Kanda, Sarga 9, Verse 14', 'बहुविघ्नं तपोनित्यं दुश्चरं चैव राघव।
तेन शापं न मुञ्चामो भक्ष्यमाणाश्च राक्षसैः॥', 'bahuvighnaṃ taponityaṃ duścaraṃ caiva rāghava
tena śāpaṃ na muñcāmo bhakṣyamāṇāś ca rākṣasaiḥ', null, 3009014),
('ramayana-3-9-15', 15, 'Aranya Kanda, Sarga 9, Verse 15', 'तदर्द्यमानान्रक्षोभिर्दण्डकारण्यवासिभिः।
रक्षनस्त्वं सह भ्रात्रा त्वन्नाथा हि वयं वने॥', 'tad ardyamānān rakṣobhir daṇḍakāraṇyavāsibhiḥ
rakṣanas tvaṃ saha bhrātrā tvannāthā hi vayaṃ vane', null, 3009015),
('ramayana-3-9-16', 16, 'Aranya Kanda, Sarga 9, Verse 16', 'मया चैतद्वचः श्रुत्वा कार्त्स्न्येन परिपालनम्।
ऋषीणां दण्डकारण्ये संश्रुतं जनकात्मजे॥', 'mayā caitad vacaḥ śrutvā kārtsnyena paripālanam
ṛṣīṇāṃ daṇḍakāraṇye saṃśrutaṃ janakātmaje', null, 3009016),
('ramayana-3-9-17', 17, 'Aranya Kanda, Sarga 9, Verse 17', 'संश्रुत्य च न शक्ष्यामि जीवमानः प्रतिश्रवम्।
मुनीनामन्यथा कर्तुं सत्यमिष्टं हि मे सदा॥', 'saṃśrutya ca na śakṣyāmi jīvamānaḥ pratiśravam
munīnām anyathā kartuṃ satyam iṣṭaṃ hi me sadā', null, 3009017),
('ramayana-3-9-18', 18, 'Aranya Kanda, Sarga 9, Verse 18', 'अप्यहं जीवितं जह्यां त्वां वा सीते सलक्ष्मणाम्।
न तु प्रतिज्ञां संश्रुत्य ब्राह्मणेभ्यो विशेषतः॥', 'apy ahaṃ jīvitaṃ jahyāṃ tvāṃ vā sīte salakṣmaṇām
na tu pratijñāṃ saṃśrutya brāhmaṇebhyo viśeṣataḥ', null, 3009018),
('ramayana-3-9-19', 19, 'Aranya Kanda, Sarga 9, Verse 19', 'तदवश्यं मया कार्यमृषीणां परिपालनम्।
अनुक्तेनापि वैदेहि प्रतिज्ञाय तु किं पुनः॥', 'tad avaśyaṃ mayā kāryam ṛṣīṇāṃ paripālanam
anuktenāpi vaidehi pratijñāya tu kiṃ punaḥ', null, 3009019),
('ramayana-3-9-20', 20, 'Aranya Kanda, Sarga 9, Verse 20', 'मम स्नेहाच्च सौहार्दादिदमुक्तं त्वया वचः।
परितुष्टोऽस्म्यहं सीते न ह्यनिष्टोऽनुशिष्यते।
सदृशं चानुरूपं च कुलस्य तव शोभने॥', 'mama snehāc ca sauhārdād idam uktaṃ tvayā vacaḥ
parituṣṭo ''smy ahaṃ sīte na hy aniṣṭo ''nuśiṣyate
sadṛśaṃ cānurūpaṃ ca kulasya tava śobhane', null, 3009020),
('ramayana-3-9-21', 21, 'Aranya Kanda, Sarga 9, Verse 21', 'इत्येवमुक्त्वा वचनं महात्मा सीतां प्रियां मैथिल राजपुत्रीम्।
रामो धनुष्मान्सहलक्ष्मणेन जगाम रम्याणि तपोवनानि॥', 'ity evam uktvā vacanaṃ mahātmā sītāṃ priyāṃ maithila rājaputrīm
rāmo dhanuṣmān sahalakṣmaṇena jagāma ramyāṇi tapovanāni', null, 3009021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 10 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-10-1', 1, 'Aranya Kanda, Sarga 10, Verse 1', 'अग्रतः प्रययौ रामः सीता मध्ये सुमध्यमा।
पृष्ठतस्तु धनुष्पाणिर्लक्ष्मणोऽनुजगाम ह॥', 'agrataḥ prayayau rāmaḥ sītā madhye sumadhyamā
pṛṣṭhatas tu dhanuṣpāṇir lakṣmaṇo ''nujagāma ha', null, 3010001),
('ramayana-3-10-2', 2, 'Aranya Kanda, Sarga 10, Verse 2', 'तौ पश्यमानौ विविधाञ्शैलप्रस्थान्वनानि च।
नदीश्च विविधा रम्या जग्मतुः सह सीतया॥', 'tau paśyamānau vividhāñ śailaprasthān vanāni ca
nadīś ca vividhā ramyā jagmatuḥ saha sītayā', null, 3010002),
('ramayana-3-10-3', 3, 'Aranya Kanda, Sarga 10, Verse 3', 'सारसांश्चक्रवाकांश्च नदीपुलिनचारिणः।
सरांसि च सपद्मानि युतानि जलजैः खगैः॥', 'sārasāṃś cakravākāṃś ca nadīpulinacāriṇaḥ
sarāṃsi ca sapadmāni yutāni jalajaiḥ khagaiḥ', null, 3010003),
('ramayana-3-10-4', 4, 'Aranya Kanda, Sarga 10, Verse 4', 'यूथबद्धांश्च पृषतान्मदोन्मत्तान्विषाणिनः।
महिषांश्च वराहांश्च गजांश्च द्रुमवैरिणः॥', 'yūthabaddhāṃś ca pṛṣatān madonmattān viṣāṇinaḥ
mahiṣāṃś ca varāhāṃś ca gajāṃś ca drumavairiṇaḥ', null, 3010004),
('ramayana-3-10-5', 5, 'Aranya Kanda, Sarga 10, Verse 5', 'ते गत्वा दूरमध्वानं लम्बमाने दिवाकरे।
ददृशुः सहिता रम्यं तटाकं योजनायतम्॥', 'te gatvā dūram adhvānaṃ lambamāne divākare
dadṛśuḥ sahitā ramyaṃ taṭākaṃ yojanāyatam', null, 3010005),
('ramayana-3-10-6', 6, 'Aranya Kanda, Sarga 10, Verse 6', 'पद्मपुष्करसंबाधं गजयूथैरलंकृतम्।
सारसैर्हंसकादम्बैः संकुलं जलचारिभिः॥', 'padmapuṣkarasaṃbādhaṃ gajayūthair alaṃkṛtam
sārasair haṃsakādambaiḥ saṃkulaṃ jalacāribhiḥ', null, 3010006),
('ramayana-3-10-7', 7, 'Aranya Kanda, Sarga 10, Verse 7', 'प्रसन्नसलिले रम्यतस्मिन्सरसि शुश्रुवे।
गीतवादित्रनिर्घोषो न तु कश्चन दृश्यते॥', 'prasannasalile ramyatasmin sarasi śuśruve
gītavāditranirghoṣo na tu kaś cana dṛśyate', null, 3010007),
('ramayana-3-10-8', 8, 'Aranya Kanda, Sarga 10, Verse 8', 'ततः कौतूहलाद्रामो लक्ष्मणश्च महारथः।
मुनिं धर्मभृतं नाम प्रष्टुं समुपचक्रमे॥', 'tataḥ kautūhalād rāmo lakṣmaṇaś ca mahārathaḥ
muniṃ dharmabhṛtaṃ nāma praṣṭuṃ samupacakrame', null, 3010008),
('ramayana-3-10-9', 9, 'Aranya Kanda, Sarga 10, Verse 9', 'इदमत्यद्भुतं श्रुत्वा सर्वेषां नो महामुने।
कौतूहलं महज्जातं किमिदं साधु कथ्यताम्॥', 'idam atyadbhutaṃ śrutvā sarveṣāṃ no mahāmune
kautūhalaṃ mahaj jātaṃ kim idaṃ sādhu kathyatām', null, 3010009),
('ramayana-3-10-10', 10, 'Aranya Kanda, Sarga 10, Verse 10', 'तेनैवमुक्तो धर्मात्मा राघवेण मुनिस्तदा।
प्रभावं सरसः कृत्स्नमाख्यातुमुपचक्रमे॥', 'tenaivam ukto dharmātmā rāghaveṇa munis tadā
prabhāvaṃ sarasaḥ kṛtsnam ākhyātum upacakrame', null, 3010010),
('ramayana-3-10-11', 11, 'Aranya Kanda, Sarga 10, Verse 11', 'इदं पञ्चाप्सरो नाम तटाकं सार्वकालिकम्।
निर्मितं तपसा राम मुनिना माण्डकर्णिना॥', 'idaṃ pañcāpsaro nāma taṭākaṃ sārvakālikam
nirmitaṃ tapasā rāma muninā māṇḍakarṇinā', null, 3010011),
('ramayana-3-10-12', 12, 'Aranya Kanda, Sarga 10, Verse 12', 'स हि तेपे तपस्तीव्रं माण्डकर्णिर्महामुनिः।
दशवर्षसहस्राणि वायुभक्षो जलाश्रय॥', 'sa hi tepe tapas tīvraṃ māṇḍakarṇir mahāmuniḥ
daśavarṣasahasrāṇi vāyubhakṣo jalāśraya', null, 3010012),
('ramayana-3-10-13', 13, 'Aranya Kanda, Sarga 10, Verse 13', 'ततः प्रव्यथिताः सर्वे देवाः साग्निपुरोगमाः।
अब्रुवन्वचनं सर्वे परस्पर समागताः।
अस्मकं कस्य चित्स्थानमेष प्रार्थयते मुनिः॥', 'tataḥ pravyathitāḥ sarve devāḥ sāgnipurogamāḥ
abruvan vacanaṃ sarve paraspara samāgatāḥ
asmakaṃ kasya cit sthānam eṣa prārthayate muniḥ', null, 3010013),
('ramayana-3-10-14', 14, 'Aranya Kanda, Sarga 10, Verse 14', 'ततः कर्तुं तपोविघ्नं सर्वैर्देवैर्नियोजिताः।
प्रधानाप्सरसः पञ्चविद्युच्चलितवर्चसः॥', 'tataḥ kartuṃ tapovighnaṃ sarvair devair niyojitāḥ
pradhānāpsarasaḥ pañcavidyuccalitavarcasaḥ', null, 3010014),
('ramayana-3-10-15', 15, 'Aranya Kanda, Sarga 10, Verse 15', 'अप्सरोभिस्ततस्ताभिर्मुनिर्दृष्टपरावरः।
नीतो मदनवश्यत्वं सुराणां कार्यसिद्धये॥', 'apsarobhis tatas tābhir munir dṛṣṭaparāvaraḥ
nīto madanavaśyatvaṃ surāṇāṃ kāryasiddhaye', null, 3010015),
('ramayana-3-10-16', 16, 'Aranya Kanda, Sarga 10, Verse 16', 'ताश्चैवाप्सरसः पञ्चमुनेः पत्नीत्वमागताः।
तटाके निर्मितं तासामस्मिन्नन्तर्हितं गृहम्॥', 'tāś caivāpsarasaḥ pañcamuneḥ patnītvam āgatāḥ
taṭāke nirmitaṃ tāsām asminn antarhitaṃ gṛham', null, 3010016),
('ramayana-3-10-17', 17, 'Aranya Kanda, Sarga 10, Verse 17', 'तत्रैवाप्सरसः पञ्चनिवसन्त्यो यथासुखम्।
रमयन्ति तपोयोगान्मुनिं यौवनमास्थितम्॥', 'tatraivāpsarasaḥ pañcanivasantyo yathāsukham
ramayanti tapoyogān muniṃ yauvanam āsthitam', null, 3010017),
('ramayana-3-10-18', 18, 'Aranya Kanda, Sarga 10, Verse 18', 'तासां संक्रीडमानानामेष वादित्रनिःस्वनः।
श्रूयते भूषणोन्मिश्रो गीतशब्दो मनोहरः॥', 'tāsāṃ saṃkrīḍamānānām eṣa vāditraniḥsvanaḥ
śrūyate bhūṣaṇonmiśro gītaśabdo manoharaḥ', null, 3010018),
('ramayana-3-10-19', 19, 'Aranya Kanda, Sarga 10, Verse 19', 'आश्चर्यमिति तस्यैतद्वचनं भावितात्मनः।
राघवः प्रतिजग्राह सह भ्रात्रा महायशाः॥', 'āścaryam iti tasyaitad vacanaṃ bhāvitātmanaḥ
rāghavaḥ pratijagrāha saha bhrātrā mahāyaśāḥ', null, 3010019),
('ramayana-3-10-20', 20, 'Aranya Kanda, Sarga 10, Verse 20', 'एवं कथयमानस्य ददर्शाश्रममण्डलम्।
कुशचीरपरिक्षिप्तं नानावृक्षसमावृतम्॥', 'evaṃ kathayamānasya dadarśāśramamaṇḍalam
kuśacīraparikṣiptaṃ nānāvṛkṣasamāvṛtam', null, 3010020),
('ramayana-3-10-21', 21, 'Aranya Kanda, Sarga 10, Verse 21', 'प्रविश्य सह वैदेह्या लक्ष्मणेन च राघवः।
तदा तस्मिन्स काकुत्स्थः श्रीमत्याश्रममण्डले॥', 'praviśya saha vaidehyā lakṣmaṇena ca rāghavaḥ
tadā tasmin sa kākutsthaḥ śrīmaty āśramamaṇḍale', null, 3010021),
('ramayana-3-10-22', 22, 'Aranya Kanda, Sarga 10, Verse 22', 'उषित्वा सुसुखं तत्र पूर्ज्यमानो महर्षिभिः।
जगाम चाश्रमांस्तेषां पर्यायेण तपस्विनाम्॥', 'uṣitvā susukhaṃ tatra pūrjyamāno maharṣibhiḥ
jagāma cāśramāṃs teṣāṃ paryāyeṇa tapasvinām', null, 3010022),
('ramayana-3-10-23', 23, 'Aranya Kanda, Sarga 10, Verse 23', 'येषामुषितवान्पूर्वं सकाशे स महास्त्रवित्।
क्व चित्परिदशान्मासानेकं संवत्सरं क्व चित्॥', 'yeṣām uṣitavān pūrvaṃ sakāśe sa mahāstravit
kva cit paridaśān māsān ekaṃ saṃvatsaraṃ kva cit', null, 3010023),
('ramayana-3-10-24', 24, 'Aranya Kanda, Sarga 10, Verse 24', 'क्व चिच्च चतुरो मासान्पञ्चषट्चापरान्क्व चित्।
अपरत्राधिकान्मासानध्यर्धमधिकं क्व चित्॥', 'kva cic ca caturo māsān pañcaṣaṭ cāparān kva cit
aparatrādhikān māsān adhyardham adhikaṃ kva cit', null, 3010024),
('ramayana-3-10-25', 25, 'Aranya Kanda, Sarga 10, Verse 25', 'त्रीन्मासानष्टमासांश्च राघवो न्यवसत्सुखम्।
तथा संवसतस्तस्य मुनीनामाश्रमेषु वै।
रमतश्चानुकुल्येन ययुः संवत्सरा दश॥', 'trīn māsān aṣṭamāsāṃś ca rāghavo nyavasat sukham
tathā saṃvasatas tasya munīnām āśrameṣu vai
ramataś cānukulyena yayuḥ saṃvatsarā daśa', null, 3010025),
('ramayana-3-10-26', 26, 'Aranya Kanda, Sarga 10, Verse 26', 'परिसृत्य च धर्मज्ञो राघवः सह सीतया।
सुतीक्ष्णस्याश्रमं श्रीमान्पुनरेवाजगाम ह॥', 'parisṛtya ca dharmajño rāghavaḥ saha sītayā
sutīkṣṇasyāśramaṃ śrīmān punar evājagāma ha', null, 3010026),
('ramayana-3-10-27', 27, 'Aranya Kanda, Sarga 10, Verse 27', 'स तमाश्रममागम्य मुनिभिः प्रतिपूजितः।
तत्रापि न्यवसद्रामः कं चित्कालमरिंदमः॥', 'sa tam āśramam āgamya munibhiḥ pratipūjitaḥ
tatrāpi nyavasad rāmaḥ kaṃ cit kālam ariṃdamaḥ', null, 3010027),
('ramayana-3-10-28', 28, 'Aranya Kanda, Sarga 10, Verse 28', 'अथाश्रमस्थो विनयात्कदा चित्तं महामुनिम्।
उपासीनः स काकुत्स्थः सुतीक्ष्णमिदमब्रवीत्॥', 'athāśramastho vinayāt kadā cit taṃ mahāmunim
upāsīnaḥ sa kākutsthaḥ sutīkṣṇam idam abravīt', null, 3010028),
('ramayana-3-10-29', 29, 'Aranya Kanda, Sarga 10, Verse 29', 'अस्मिन्नरण्ये भगवन्नगस्त्यो मुनिसत्तमः।
वसतीति मया नित्यं कथाः कथयतां श्रुतम्॥', 'asminn araṇye bhagavann agastyo munisattamaḥ
vasatīti mayā nityaṃ kathāḥ kathayatāṃ śrutam', null, 3010029),
('ramayana-3-10-30', 30, 'Aranya Kanda, Sarga 10, Verse 30', 'न तु जानामि तं देशं वनस्यास्य महत्तया।
कुत्राश्रमपदं पुण्यं महर्षेस्तस्य धीमतः॥', 'na tu jānāmi taṃ deśaṃ vanasyāsya mahattayā
kutrāśramapadaṃ puṇyaṃ maharṣes tasya dhīmataḥ', null, 3010030),
('ramayana-3-10-31', 31, 'Aranya Kanda, Sarga 10, Verse 31', 'प्रसादात्तत्र भवतः सानुजः सह सीतया।
अगस्त्यमभिगच्छेयमभिवादयितुं मुनिम्॥', 'prasādāt tatra bhavataḥ sānujaḥ saha sītayā
agastyam abhigaccheyam abhivādayituṃ munim', null, 3010031),
('ramayana-3-10-32', 32, 'Aranya Kanda, Sarga 10, Verse 32', 'मनोरथो महानेष हृदि संपरिवर्तते।
यदहं तं मुनिवरं शुश्रूषेयमपि स्वयम्॥', 'manoratho mahān eṣa hṛdi saṃparivartate
yad ahaṃ taṃ munivaraṃ śuśrūṣeyam api svayam', null, 3010032),
('ramayana-3-10-33', 33, 'Aranya Kanda, Sarga 10, Verse 33', 'इति रामस्य स मुनिः श्रुत्वा धर्मात्मनो वचः।
सुतीक्ष्णः प्रत्युवाचेदं प्रीतो दशरथात्मजम्॥', 'iti rāmasya sa muniḥ śrutvā dharmātmano vacaḥ
sutīkṣṇaḥ pratyuvācedaṃ prīto daśarathātmajam', null, 3010033),
('ramayana-3-10-34', 34, 'Aranya Kanda, Sarga 10, Verse 34', 'अहमप्येतदेव त्वां वक्तुकामः सलक्ष्मणम्।
अगस्त्यमभिगच्छेति सीतया सह राघव॥', 'aham apy etad eva tvāṃ vaktukāmaḥ salakṣmaṇam
agastyam abhigaccheti sītayā saha rāghava', null, 3010034),
('ramayana-3-10-35', 35, 'Aranya Kanda, Sarga 10, Verse 35', 'दिष्ट्या त्विदानीमर्थेऽस्मिन्स्वयमेव ब्रवीषि माम्।
अहमाख्यामि ते वत्स यत्रागस्त्यो महामुनिः॥', 'diṣṭyā tv idānīm arthe ''smin svayam eva bravīṣi mām
aham ākhyāmi te vatsa yatrāgastyo mahāmuniḥ', null, 3010035),
('ramayana-3-10-36', 36, 'Aranya Kanda, Sarga 10, Verse 36', 'योजनान्याश्रमात्तात याहि चत्वारि वै ततः।
दक्षिणेन महाञ्श्रीमानगस्त्यभ्रातुराश्रमः॥', 'yojanāny āśramāt tāta yāhi catvāri vai tataḥ
dakṣiṇena mahāñ śrīmān agastyabhrātur āśramaḥ', null, 3010036),
('ramayana-3-10-37', 37, 'Aranya Kanda, Sarga 10, Verse 37', 'स्थलप्राये वनोद्देशे पिप्पलीवनशोभिते।
बहुपुष्पफले रम्ये नानाशकुनिनादिते॥', 'sthalaprāye vanoddeśe pippalīvanaśobhite
bahupuṣpaphale ramye nānāśakuninādite', null, 3010037),
('ramayana-3-10-38', 38, 'Aranya Kanda, Sarga 10, Verse 38', 'पद्मिन्यो विविधास्तत्र प्रसन्नसलिलाः शिवाः।
हंसकारण्डवाकीर्णाश्चक्रवाकोपशोभिताः॥', 'padminyo vividhās tatra prasannasalilāḥ śivāḥ
haṃsakāraṇḍavākīrṇāś cakravākopaśobhitāḥ', null, 3010038),
('ramayana-3-10-39', 39, 'Aranya Kanda, Sarga 10, Verse 39', 'तत्रैकां रजनीमुष्य प्रभाते राम गम्यताम्।
दक्षिणां दिशमास्थाय वनखण्डस्य पार्श्वतः॥', 'tatraikāṃ rajanīm uṣya prabhāte rāma gamyatām
dakṣiṇāṃ diśam āsthāya vanakhaṇḍasya pārśvataḥ', null, 3010039),
('ramayana-3-10-40', 40, 'Aranya Kanda, Sarga 10, Verse 40', 'तत्रागस्त्याश्रमपदं गत्वा योजनमन्तरम्।
रमणीये वनोद्देशे बहुपादप संवृते।
रंस्यते तत्र वैदेही लक्ष्मणश्च त्वया सह॥', 'tatrāgastyāśramapadaṃ gatvā yojanam antaram
ramaṇīye vanoddeśe bahupādapa saṃvṛte
raṃsyate tatra vaidehī lakṣmaṇaś ca tvayā saha', null, 3010040),
('ramayana-3-10-41', 41, 'Aranya Kanda, Sarga 10, Verse 41', 'स हि रम्यो वनोद्देशो बहुपादपसंकुलः।
यदि बुद्धिः कृता द्रष्टुमगस्त्यं तं महामुनिम्।
अद्यैव गमने बुद्धिं रोचयस्व महायशः॥', 'sa hi ramyo vanoddeśo bahupādapasaṃkulaḥ
yadi buddhiḥ kṛtā draṣṭum agastyaṃ taṃ mahāmunim
adyaiva gamane buddhiṃ rocayasva mahāyaśaḥ', null, 3010041),
('ramayana-3-10-42', 42, 'Aranya Kanda, Sarga 10, Verse 42', 'इति रामो मुनेः श्रुत्वा सह भ्रात्राभिवाद्य च।
प्रतस्थेऽगस्त्यमुद्दिश्य सानुजः सह सीतया॥', 'iti rāmo muneḥ śrutvā saha bhrātrābhivādya ca
pratasthe ''gastyam uddiśya sānujaḥ saha sītayā', null, 3010042),
('ramayana-3-10-43', 43, 'Aranya Kanda, Sarga 10, Verse 43', 'पश्यन्वनानि चित्राणि पर्वपांश्चाभ्रसंनिभान्।
सरांसि सरितश्चैव पथि मार्गवशानुगाः॥', 'paśyan vanāni citrāṇi parvapāṃś cābhrasaṃnibhān
sarāṃsi saritaś caiva pathi mārgavaśānugāḥ', null, 3010043),
('ramayana-3-10-44', 44, 'Aranya Kanda, Sarga 10, Verse 44', 'सुतीक्ष्णेनोपदिष्टेन गत्वा तेन पथा सुखम्।
इदं परमसंहृष्टो वाक्यं लक्ष्मणमब्रवीत्॥', 'sutīkṣṇenopadiṣṭena gatvā tena pathā sukham
idaṃ paramasaṃhṛṣṭo vākyaṃ lakṣmaṇam abravīt', null, 3010044),
('ramayana-3-10-45', 45, 'Aranya Kanda, Sarga 10, Verse 45', 'एतदेवाश्रमपदं नूनं तस्य महात्मनः।
अगस्त्यस्य मुनेर्भ्रातुर्दृश्यते पुण्यकर्मणः॥', 'etad evāśramapadaṃ nūnaṃ tasya mahātmanaḥ
agastyasya muner bhrātur dṛśyate puṇyakarmaṇaḥ', null, 3010045),
('ramayana-3-10-46', 46, 'Aranya Kanda, Sarga 10, Verse 46', 'यथा हीमे वनस्यास्य ज्ञाताः पथि सहस्रशः।
संनताः फलभरेण पुष्पभारेण च द्रुमाः॥', 'yathā hīme vanasyāsya jñātāḥ pathi sahasraśaḥ
saṃnatāḥ phalabhareṇa puṣpabhāreṇa ca drumāḥ', null, 3010046),
('ramayana-3-10-47', 47, 'Aranya Kanda, Sarga 10, Verse 47', 'पिप्पलीनां च पक्वानां वनादस्मादुपागतः।
गन्धोऽयं पवनोत्क्षिप्तः सहसा कटुकोदयः॥', 'pippalīnāṃ ca pakvānāṃ vanād asmād upāgataḥ
gandho ''yaṃ pavanotkṣiptaḥ sahasā kaṭukodayaḥ', null, 3010047),
('ramayana-3-10-48', 48, 'Aranya Kanda, Sarga 10, Verse 48', 'तत्र तत्र च दृश्यन्ते संक्षिप्ताः काष्ठसंचयाः।
लूनाश्च पथि दृश्यन्ते दर्भा वैदूर्यवर्चसः॥', 'tatra tatra ca dṛśyante saṃkṣiptāḥ kāṣṭhasaṃcayāḥ
lūnāś ca pathi dṛśyante darbhā vaidūryavarcasaḥ', null, 3010048),
('ramayana-3-10-49', 49, 'Aranya Kanda, Sarga 10, Verse 49', 'एतच्च वनमध्यस्थं कृष्णाभ्रशिखरोपमम्।
पावकस्याश्रमस्थस्य धूमाग्रं संप्रदृश्यते॥', 'etac ca vanamadhyasthaṃ kṛṣṇābhraśikharopamam
pāvakasyāśramasthasya dhūmāgraṃ saṃpradṛśyate', null, 3010049),
('ramayana-3-10-50', 50, 'Aranya Kanda, Sarga 10, Verse 50', 'विविक्तेषु च तीर्थेषु कृतस्नाना द्विजातयः।
पुष्पोपहारं कुर्वन्ति कुसुमैः स्वयमार्जितैः॥', 'vivikteṣu ca tīrtheṣu kṛtasnānā dvijātayaḥ
puṣpopahāraṃ kurvanti kusumaiḥ svayam ārjitaiḥ', null, 3010050),
('ramayana-3-10-51', 51, 'Aranya Kanda, Sarga 10, Verse 51', 'तत्सुतीक्ष्णस्य वचनं यथा सौम्य मया श्रुतम्।
अगस्त्यस्याश्रमो भ्रातुर्नूनमेष भविष्यति॥', 'tat sutīkṣṇasya vacanaṃ yathā saumya mayā śrutam
agastyasyāśramo bhrātur nūnam eṣa bhaviṣyati', null, 3010051),
('ramayana-3-10-52', 52, 'Aranya Kanda, Sarga 10, Verse 52', 'निगृह्य तरसा मृत्युं लोकानां हितकाम्यया।
यस्य भ्रात्रा कृतेयं दिक्शरण्या पुण्यकर्मणा॥', 'nigṛhya tarasā mṛtyuṃ lokānāṃ hitakāmyayā
yasya bhrātrā kṛteyaṃ dik śaraṇyā puṇyakarmaṇā', null, 3010052),
('ramayana-3-10-53', 53, 'Aranya Kanda, Sarga 10, Verse 53', 'इहैकदा किल क्रूरो वातापिरपि चेल्वलः।
भ्रातरौ सहितावास्तां ब्राह्मणघ्नौ महासुरौ॥', 'ihaikadā kila krūro vātāpir api celvalaḥ
bhrātarau sahitāv āstāṃ brāhmaṇaghnau mahāsurau', null, 3010053),
('ramayana-3-10-54', 54, 'Aranya Kanda, Sarga 10, Verse 54', 'धारयन्ब्राह्मणं रूपमिल्वलः संस्कृतं वदन्।
आमन्त्रयति विप्रान्स श्राद्धमुद्दिश्य निर्घृणः॥', 'dhārayan brāhmaṇaṃ rūpam ilvalaḥ saṃskṛtaṃ vadan
āmantrayati viprān sa śrāddham uddiśya nirghṛṇaḥ', null, 3010054),
('ramayana-3-10-55', 55, 'Aranya Kanda, Sarga 10, Verse 55', 'भ्रातरं संस्कृतं भ्राता ततस्तं मेषरूपिणम्।
तान्द्विजान्भोजयामास श्राद्धदृष्टेन कर्मणा॥', 'bhrātaraṃ saṃskṛtaṃ bhrātā tatas taṃ meṣarūpiṇam
tān dvijān bhojayām āsa śrāddhadṛṣṭena karmaṇā', null, 3010055),
('ramayana-3-10-56', 56, 'Aranya Kanda, Sarga 10, Verse 56', 'ततो भुक्तवतां तेषां विप्राणामिल्वलोऽब्रवीत्।
वातापे निष्क्रमस्वेति स्वरेण महता वदन्॥', 'tato bhuktavatāṃ teṣāṃ viprāṇām ilvalo ''bravīt
vātāpe niṣkramasveti svareṇa mahatā vadan', null, 3010056),
('ramayana-3-10-57', 57, 'Aranya Kanda, Sarga 10, Verse 57', 'ततो भ्रातुर्वचः श्रुत्वा वातापिर्मेषवन्नदन्।
भित्त्वा भित्वा शरीराणि ब्राह्मणानां विनिष्पतत्॥', 'tato bhrātur vacaḥ śrutvā vātāpir meṣavan nadan
bhittvā bhitvā śarīrāṇi brāhmaṇānāṃ viniṣpatat', null, 3010057),
('ramayana-3-10-58', 58, 'Aranya Kanda, Sarga 10, Verse 58', 'ब्राह्मणानां सहस्राणि तैरेवं कामरूपिभिः।
विनाशितानि संहत्य नित्यशः पिशिताशनैः॥', 'brāhmaṇānāṃ sahasrāṇi tair evaṃ kāmarūpibhiḥ
vināśitāni saṃhatya nityaśaḥ piśitāśanaiḥ', null, 3010058),
('ramayana-3-10-59', 59, 'Aranya Kanda, Sarga 10, Verse 59', 'अगस्त्येन तदा देवैः प्रार्थितेन महर्षिणा।
अनुभूय किल श्राद्धे भक्षितः स महासुरः॥', 'agastyena tadā devaiḥ prārthitena maharṣiṇā
anubhūya kila śrāddhe bhakṣitaḥ sa mahāsuraḥ', null, 3010059),
('ramayana-3-10-60', 60, 'Aranya Kanda, Sarga 10, Verse 60', 'ततः संपन्नमित्युक्त्वा दत्त्वा हस्तावसेचनम्।
भ्रातरं निष्क्रमस्वेति इल्वलः सोऽभ्यभाषत॥', 'tataḥ saṃpannam ity uktvā dattvā hastāvasecanam
bhrātaraṃ niṣkramasveti ilvalaḥ so ''bhyabhāṣata', null, 3010060),
('ramayana-3-10-61', 61, 'Aranya Kanda, Sarga 10, Verse 61', 'तं तथा भाषमाणं तु भ्रातरं विप्रघातिनम्।
अब्रवीत्प्रहसन्धीमानगस्त्यो मुनिसत्तमः॥', 'taṃ tathā bhāṣamāṇaṃ tu bhrātaraṃ vipraghātinam
abravīt prahasan dhīmān agastyo munisattamaḥ', null, 3010061),
('ramayana-3-10-62', 62, 'Aranya Kanda, Sarga 10, Verse 62', 'कुतो निष्क्रमितुं शक्तिर्मया जीर्णस्य रक्षसः।
भ्रातुस्ते मेष रूपस्य गतस्य यमसादनम्॥', 'kuto niṣkramituṃ śaktir mayā jīrṇasya rakṣasaḥ
bhrātus te meṣa rūpasya gatasya yamasādanam', null, 3010062),
('ramayana-3-10-63', 63, 'Aranya Kanda, Sarga 10, Verse 63', 'अथ तस्य वचः श्रुत्वा भ्रातुर्निधनसंश्रितम्।
प्रधर्षयितुमारेभे मुनिं क्रोधान्निशाचरः॥', 'atha tasya vacaḥ śrutvā bhrātur nidhanasaṃśritam
pradharṣayitum ārebhe muniṃ krodhān niśācaraḥ', null, 3010063),
('ramayana-3-10-64', 64, 'Aranya Kanda, Sarga 10, Verse 64', 'सोऽभ्यद्रवद्द्विजेन्द्रं तं मुनिना दीप्ततेजसा।
चक्षुषानलकल्पेन निर्दग्धो निधनं गतः॥', 'so ''bhyadravad dvijendraṃ taṃ muninā dīptatejasā
cakṣuṣānalakalpena nirdagdho nidhanaṃ gataḥ', null, 3010064),
('ramayana-3-10-65', 65, 'Aranya Kanda, Sarga 10, Verse 65', 'तस्यायमाश्रमो भ्रातुस्तटाकवनशोभितः।
विप्रानुकम्पया येन कर्मेदं दुष्करं कृतम्॥', 'tasyāyam āśramo bhrātus taṭākavanaśobhitaḥ
viprānukampayā yena karmedaṃ duṣkaraṃ kṛtam', null, 3010065),
('ramayana-3-10-66', 66, 'Aranya Kanda, Sarga 10, Verse 66', 'एवं कथयमानस्य तस्य सौमित्रिणा सह।
रामस्यास्तं गतः सूर्यः संध्याकालोऽभ्यवर्तत॥', 'evaṃ kathayamānasya tasya saumitriṇā saha
rāmasyāstaṃ gataḥ sūryaḥ saṃdhyākālo ''bhyavartata', null, 3010066),
('ramayana-3-10-67', 67, 'Aranya Kanda, Sarga 10, Verse 67', 'उपास्य पश्चिमां संध्यां सह भ्रात्रा यथाविधि।
प्रविवेशाश्रमपदं तमृषिं चाभ्यवादयन्॥', 'upāsya paścimāṃ saṃdhyāṃ saha bhrātrā yathāvidhi
praviveśāśramapadaṃ tam ṛṣiṃ cābhyavādayan', null, 3010067),
('ramayana-3-10-68', 68, 'Aranya Kanda, Sarga 10, Verse 68', 'सम्यक्प्रतिगृहीतस्तु मुनिना तेन राघवः।
न्यवसत्तां निशामेकां प्राश्य मूलफलानि च॥', 'samyak pratigṛhītas tu muninā tena rāghavaḥ
nyavasat tāṃ niśām ekāṃ prāśya mūlaphalāni ca', null, 3010068),
('ramayana-3-10-69', 69, 'Aranya Kanda, Sarga 10, Verse 69', 'तस्यां रात्र्यां व्यतीतायां विमले सूर्यमण्डले।
भ्रातरं तमगस्त्यस्य आमन्त्रयत राघवः॥', 'tasyāṃ rātryāṃ vyatītāyāṃ vimale sūryamaṇḍale
bhrātaraṃ tam agastyasya āmantrayata rāghavaḥ', null, 3010069),
('ramayana-3-10-70', 70, 'Aranya Kanda, Sarga 10, Verse 70', 'अभिवादये त्वा भगवन्सुखमध्युषितो निशाम्।
आमन्त्रये त्वां गच्छामि गुरुं ते द्रष्टुमग्रजम्॥', 'abhivādaye tvā bhagavan sukham adhyuṣito niśām
āmantraye tvāṃ gacchāmi guruṃ te draṣṭum agrajam', null, 3010070),
('ramayana-3-10-71', 71, 'Aranya Kanda, Sarga 10, Verse 71', 'गम्यतामिति तेनोक्तो जगाम रघुनन्दनः।
यथोद्दिष्टेन मार्गेण वनं तच्चावलोकयन्॥', 'gamyatām iti tenokto jagāma raghunandanaḥ
yathoddiṣṭena mārgeṇa vanaṃ tac cāvalokayan', null, 3010071),
('ramayana-3-10-72', 72, 'Aranya Kanda, Sarga 10, Verse 72', 'नीवारान्पनसांस्तालांस्तिमिशान्वञ्जुलान्धवान्।
चिरिबिल्वान्मधूकांश्च बिल्वानपि च तिन्दुकान्॥', 'nīvārān panasāṃs tālāṃs timiśān vañjulān dhavān
ciribilvān madhūkāṃś ca bilvān api ca tindukān', null, 3010072),
('ramayana-3-10-73', 73, 'Aranya Kanda, Sarga 10, Verse 73', 'पुष्पितान्पुष्पिताग्राभिर्लताभिरनुवेष्टितान्।
ददर्श रामः शतशस्तत्र कान्तारपादपान्॥', 'puṣpitān puṣpitāgrābhir latābhir anuveṣṭitān
dadarśa rāmaḥ śataśas tatra kāntārapādapān', null, 3010073),
('ramayana-3-10-74', 74, 'Aranya Kanda, Sarga 10, Verse 74', 'हस्तिहस्तैर्विमृदितान्वानरैरुपशोभितान्।
मत्तैः शकुनिसंघैश्च शतशः प्रतिनादितान्॥', 'hastihastair vimṛditān vānarair upaśobhitān
mattaiḥ śakunisaṃghaiś ca śataśaḥ pratināditān', null, 3010074),
('ramayana-3-10-75', 75, 'Aranya Kanda, Sarga 10, Verse 75', 'ततोऽब्रवीत्समीपस्थं रामो राजीवलोचनः।
पृष्ठतोऽनुगतं वीरं लक्ष्मणं लक्ष्मिवर्धनम्॥', 'tato ''bravīt samīpasthaṃ rāmo rājīvalocanaḥ
pṛṣṭhato ''nugataṃ vīraṃ lakṣmaṇaṃ lakṣmivardhanam', null, 3010075),
('ramayana-3-10-76', 76, 'Aranya Kanda, Sarga 10, Verse 76', 'स्निग्धपत्रा यथा वृक्षा यथा क्षान्ता मृगद्विजाः।
आश्रमो नातिदूरस्थो महर्षेर्भावितात्मनः॥', 'snigdhapatrā yathā vṛkṣā yathā kṣāntā mṛgadvijāḥ
āśramo nātidūrastho maharṣer bhāvitātmanaḥ', null, 3010076),
('ramayana-3-10-77', 77, 'Aranya Kanda, Sarga 10, Verse 77', 'अगस्त्य इति विख्यातो लोके स्वेनैव कर्मणा।
आश्रमो दृश्यते तस्य परिश्रान्त श्रमापहः॥', 'agastya iti vikhyāto loke svenaiva karmaṇā
āśramo dṛśyate tasya pariśrānta śramāpahaḥ', null, 3010077),
('ramayana-3-10-78', 78, 'Aranya Kanda, Sarga 10, Verse 78', 'प्राज्यधूमाकुलवनश्चीरमालापरिष्कृतः।
प्रशान्तमृगयूथश्च नानाशकुनिनादितः॥', 'prājyadhūmākulavanaś cīramālāpariṣkṛtaḥ
praśāntamṛgayūthaś ca nānāśakunināditaḥ', null, 3010078),
('ramayana-3-10-79', 79, 'Aranya Kanda, Sarga 10, Verse 79', 'निगृह्य तरसा मृत्युं लोकानां हितकाम्यया।
दक्षिणा दिक्कृता येन शरण्या पुण्यकर्मणा॥', 'nigṛhya tarasā mṛtyuṃ lokānāṃ hitakāmyayā
dakṣiṇā dik kṛtā yena śaraṇyā puṇyakarmaṇā', null, 3010079),
('ramayana-3-10-80', 80, 'Aranya Kanda, Sarga 10, Verse 80', 'तस्येदमाश्रमपदं प्रभावाद्यस्य राक्षसैः।
दिगियं दक्षिणा त्रासाद्दृश्यते नोपभुज्यते॥', 'tasyedam āśramapadaṃ prabhāvād yasya rākṣasaiḥ
dig iyaṃ dakṣiṇā trāsād dṛśyate nopabhujyate', null, 3010080),
('ramayana-3-10-81', 81, 'Aranya Kanda, Sarga 10, Verse 81', 'यदा प्रभृति चाक्रान्ता दिगियं पुण्यकर्मणा।
तदा प्रभृति निर्वैराः प्रशान्ता रजनीचराः॥', 'yadā prabhṛti cākrāntā dig iyaṃ puṇyakarmaṇā
tadā prabhṛti nirvairāḥ praśāntā rajanīcarāḥ', null, 3010081),
('ramayana-3-10-82', 82, 'Aranya Kanda, Sarga 10, Verse 82', 'नाम्ना चेयं भगवतो दक्षिणा दिक्प्रदक्षिणा।
प्रथिता त्रिषु लोकेषु दुर्धर्षा क्रूरकर्मभिः॥', 'nāmnā ceyaṃ bhagavato dakṣiṇā dik pradakṣiṇā
prathitā triṣu lokeṣu durdharṣā krūrakarmabhiḥ', null, 3010082),
('ramayana-3-10-83', 83, 'Aranya Kanda, Sarga 10, Verse 83', 'मार्गं निरोद्धुं सततं भास्करस्याचलोत्तमः।
संदेशं पालयंस्तस्य विन्ध्यशौलो न वर्धते॥', 'mārgaṃ niroddhuṃ satataṃ bhāskarasyācalottamaḥ
saṃdeśaṃ pālayaṃs tasya vindhyaśaulo na vardhate', null, 3010083),
('ramayana-3-10-84', 84, 'Aranya Kanda, Sarga 10, Verse 84', 'अयं दीर्घायुषस्तस्य लोके विश्रुतकर्मणः।
अगस्त्यस्याश्रमः श्रीमान्विनीतमृगसेवितः॥', 'ayaṃ dīrghāyuṣas tasya loke viśrutakarmaṇaḥ
agastyasyāśramaḥ śrīmān vinītamṛgasevitaḥ', null, 3010084),
('ramayana-3-10-85', 85, 'Aranya Kanda, Sarga 10, Verse 85', 'एष लोकार्चितः साधुर्हिते नित्यं रतः सताम्।
अस्मानधिगतानेष श्रेयसा योजयिष्यति॥', 'eṣa lokārcitaḥ sādhur hite nityaṃ rataḥ satām
asmān adhigatān eṣa śreyasā yojayiṣyati', null, 3010085),
('ramayana-3-10-86', 86, 'Aranya Kanda, Sarga 10, Verse 86', 'आराधयिष्याम्यत्राहमगस्त्यं तं महामुनिम्।
शेषं च वनवासस्य सौम्य वत्स्याम्यहं प्रभो॥', 'ārādhayiṣyāmy atrāham agastyaṃ taṃ mahāmunim
śeṣaṃ ca vanavāsasya saumya vatsyāmy ahaṃ prabho', null, 3010086),
('ramayana-3-10-87', 87, 'Aranya Kanda, Sarga 10, Verse 87', 'अत्र देवाः सगन्धर्वाः सिद्धाश्च परमर्षयः।
अगस्त्यं नियताहारं सततं पर्युपासते॥', 'atra devāḥ sagandharvāḥ siddhāś ca paramarṣayaḥ
agastyaṃ niyatāhāraṃ satataṃ paryupāsate', null, 3010087),
('ramayana-3-10-88', 88, 'Aranya Kanda, Sarga 10, Verse 88', 'नात्र जीवेन्मृषावादी क्रूरो वा यदि वा शठः।
नृशंसः कामवृत्तो वा मुनिरेष तथाविधः॥', 'nātra jīven mṛṣāvādī krūro vā yadi vā śaṭhaḥ
nṛśaṃsaḥ kāmavṛtto vā munir eṣa tathāvidhaḥ', null, 3010088),
('ramayana-3-10-89', 89, 'Aranya Kanda, Sarga 10, Verse 89', 'अत्र देवाश्च यक्षाश्च नागाश्च पतगैः सह।
वसन्ति नियताहारा धर्ममाराधयिष्णवः॥', 'atra devāś ca yakṣāś ca nāgāś ca patagaiḥ saha
vasanti niyatāhārā dharmam ārādhayiṣṇavaḥ', null, 3010089),
('ramayana-3-10-90', 90, 'Aranya Kanda, Sarga 10, Verse 90', 'अत्र सिद्धा महात्मानो विमानैः सूर्यसंनिभैः।
त्यक्त्वा देहान्नवैर्देहैः स्वर्याताः परमर्षयः॥', 'atra siddhā mahātmāno vimānaiḥ sūryasaṃnibhaiḥ
tyaktvā dehān navair dehaiḥ svaryātāḥ paramarṣayaḥ', null, 3010090),
('ramayana-3-10-91', 91, 'Aranya Kanda, Sarga 10, Verse 91', 'यक्षत्वममरत्वं च राज्यानि विविधानि च।
अत्र देवाः प्रयच्छन्ति भूतैराराधिताः शुभैः॥', 'yakṣatvam amaratvaṃ ca rājyāni vividhāni ca
atra devāḥ prayacchanti bhūtair ārādhitāḥ śubhaiḥ', null, 3010091),
('ramayana-3-10-92', 92, 'Aranya Kanda, Sarga 10, Verse 92', 'आगताः स्माश्रमपदं सौमित्रे प्रविशाग्रतः।
निवेदयेह मां प्राप्तमृषये सह सीतया॥', 'āgatāḥ smāśramapadaṃ saumitre praviśāgrataḥ
nivedayeha māṃ prāptam ṛṣaye saha sītayā', null, 3010092)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 11 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-11-1', 1, 'Aranya Kanda, Sarga 11, Verse 1', 'स प्रविश्याश्रमपदं लक्ष्मणो राघवानुजः।
अगस्त्यशिष्यमासाद्य वाक्यमेतदुवाच ह॥', 'sa praviśyāśramapadaṃ lakṣmaṇo rāghavānujaḥ
agastyaśiṣyam āsādya vākyam etad uvāca ha', null, 3011001),
('ramayana-3-11-2', 2, 'Aranya Kanda, Sarga 11, Verse 2', 'राजा दशरथो नाम ज्येष्ठस्तस्य सुतो बली।
रामः प्राप्तो मुनिं द्रष्टुं भार्यया सह सीतया॥', 'rājā daśaratho nāma jyeṣṭhas tasya suto balī
rāmaḥ prāpto muniṃ draṣṭuṃ bhāryayā saha sītayā', null, 3011002),
('ramayana-3-11-3', 3, 'Aranya Kanda, Sarga 11, Verse 3', 'लक्ष्मणो नाम तस्याहं भ्राता त्ववरजो हितः।
अनुकूलश्च भक्तश्च यदि ते श्रोत्रमागतः॥', 'lakṣmaṇo nāma tasyāhaṃ bhrātā tv avarajo hitaḥ
anukūlaś ca bhaktaś ca yadi te śrotram āgataḥ', null, 3011003),
('ramayana-3-11-4', 4, 'Aranya Kanda, Sarga 11, Verse 4', 'ते वयं वनमत्युग्रं प्रविष्टाः पितृशासनात्।
द्रष्टुमिच्छामहे सर्वे भगवन्तं निवेद्यताम्॥', 'te vayaṃ vanam atyugraṃ praviṣṭāḥ pitṛśāsanāt
draṣṭum icchāmahe sarve bhagavantaṃ nivedyatām', null, 3011004),
('ramayana-3-11-5', 5, 'Aranya Kanda, Sarga 11, Verse 5', 'तस्य तद्वचनं श्रुत्वा लक्ष्मणस्य तपोधनः।
तथेत्युक्त्वाग्निशरणं प्रविवेश निवेदितुम्॥', 'tasya tad vacanaṃ śrutvā lakṣmaṇasya tapodhanaḥ
tathety uktvāgniśaraṇaṃ praviveśa niveditum', null, 3011005),
('ramayana-3-11-6', 6, 'Aranya Kanda, Sarga 11, Verse 6', 'स प्रविश्य मुनिश्रेष्ठं तपसा दुष्प्रधर्षणम्।
कृताञ्जलिरुवाचेदं रामागमनमञ्जसा॥', 'sa praviśya muniśreṣṭhaṃ tapasā duṣpradharṣaṇam
kṛtāñjalir uvācedaṃ rāmāgamanam añjasā', null, 3011006),
('ramayana-3-11-7', 7, 'Aranya Kanda, Sarga 11, Verse 7', 'पुत्रौ दशरथस्येमौ रामो लक्ष्मण एव च।
प्रविष्टावाश्रमपदं सीतया सह भार्यया॥', 'putrau daśarathasyemau rāmo lakṣmaṇa eva ca
praviṣṭāv āśramapadaṃ sītayā saha bhāryayā', null, 3011007),
('ramayana-3-11-8', 8, 'Aranya Kanda, Sarga 11, Verse 8', 'द्रष्टुं भवन्तमायातौ शुश्रूषार्थमरिंदमौ।
यदत्रानन्तरं तत्त्वमाज्ञापयितुमर्हसि॥', 'draṣṭuṃ bhavantam āyātau śuśrūṣārtham ariṃdamau
yad atrānantaraṃ tattvam ājñāpayitum arhasi', null, 3011008),
('ramayana-3-11-9', 9, 'Aranya Kanda, Sarga 11, Verse 9', 'ततः शिष्यादुपश्रुत्य प्राप्तं रामं सलक्ष्मणम्।
वैदेहीं च महाभागामिदं वचनमब्रवीत्॥', 'tataḥ śiṣyād upaśrutya prāptaṃ rāmaṃ salakṣmaṇam
vaidehīṃ ca mahābhāgām idaṃ vacanam abravīt', null, 3011009),
('ramayana-3-11-10', 10, 'Aranya Kanda, Sarga 11, Verse 10', 'दिष्ट्या रामश्चिरस्याद्य द्रष्टुं मां समुपागतः।
मनसा काङ्क्षितं ह्यस्य मयाप्यागमनं प्रति॥', 'diṣṭyā rāmaś cirasyādya draṣṭuṃ māṃ samupāgataḥ
manasā kāṅkṣitaṃ hy asya mayāpy āgamanaṃ prati', null, 3011010),
('ramayana-3-11-11', 11, 'Aranya Kanda, Sarga 11, Verse 11', 'गम्यतां सत्कृतो रामः सभार्यः सहलक्ष्मणः।
प्रवेश्यतां समीपं मे किं चासौ न प्रवेशितः॥', 'gamyatāṃ satkṛto rāmaḥ sabhāryaḥ sahalakṣmaṇaḥ
praveśyatāṃ samīpaṃ me kiṃ cāsau na praveśitaḥ', null, 3011011),
('ramayana-3-11-12', 12, 'Aranya Kanda, Sarga 11, Verse 12', 'एवमुक्तस्तु मुनिना धर्मज्ञेन महात्मना।
अभिवाद्याब्रवीच्छिष्यस्तथेति नियताञ्जलिः॥', 'evam uktas tu muninā dharmajñena mahātmanā
abhivādyābravīc chiṣyas tatheti niyatāñjaliḥ', null, 3011012),
('ramayana-3-11-13', 13, 'Aranya Kanda, Sarga 11, Verse 13', 'ततो निष्क्रम्य संभ्रान्तः शिष्यो लक्ष्मणमब्रवीत्।
क्वासौ रामो मुनिं द्रष्टुमेतु प्रविशतु स्वयम्॥', 'tato niṣkramya saṃbhrāntaḥ śiṣyo lakṣmaṇam abravīt
kvāsau rāmo muniṃ draṣṭum etu praviśatu svayam', null, 3011013),
('ramayana-3-11-14', 14, 'Aranya Kanda, Sarga 11, Verse 14', 'ततो गत्वाश्रमपदं शिष्येण सह लक्ष्मणः।
दर्शयामास काकुत्स्थं सीतां च जनकात्मजाम्॥', 'tato gatvāśramapadaṃ śiṣyeṇa saha lakṣmaṇaḥ
darśayām āsa kākutsthaṃ sītāṃ ca janakātmajām', null, 3011014),
('ramayana-3-11-15', 15, 'Aranya Kanda, Sarga 11, Verse 15', 'तं शिष्यः प्रश्रितं वाक्यमगस्त्यवचनं ब्रुवन्।
प्रावेशयद्यथान्यायं सत्कारार्थं सुसत्कृतम्॥', 'taṃ śiṣyaḥ praśritaṃ vākyam agastyavacanaṃ bruvan
prāveśayad yathānyāyaṃ satkārārthaṃ susatkṛtam', null, 3011015),
('ramayana-3-11-16', 16, 'Aranya Kanda, Sarga 11, Verse 16', 'प्रविवेश ततो रामः सीतया सहलक्ष्मणः।
प्रशान्तहरिणाकीर्णमाश्रमं ह्यवलोकयन्॥', 'praviveśa tato rāmaḥ sītayā sahalakṣmaṇaḥ
praśāntahariṇākīrṇam āśramaṃ hy avalokayan', null, 3011016),
('ramayana-3-11-17', 17, 'Aranya Kanda, Sarga 11, Verse 17', 'स तत्र ब्रह्मणः स्थानमग्नेः स्थानं तथैव च।
विष्णोः स्थानं महेन्द्रस्य स्थानं चैव विवस्वतः॥', 'sa tatra brahmaṇaḥ sthānam agneḥ sthānaṃ tathaiva ca
viṣṇoḥ sthānaṃ mahendrasya sthānaṃ caiva vivasvataḥ', null, 3011017),
('ramayana-3-11-18', 18, 'Aranya Kanda, Sarga 11, Verse 18', 'सोमस्थानं भगस्थानं स्थानं कौबेरमेव च।
धातुर्विधातुः स्थानं च वायोः स्थानं तथैव च॥', 'somasthānaṃ bhagasthānaṃ sthānaṃ kauberam eva ca
dhātur vidhātuḥ sthānaṃ ca vāyoḥ sthānaṃ tathaiva ca', null, 3011018),
('ramayana-3-11-19', 19, 'Aranya Kanda, Sarga 11, Verse 19', 'ततः शिष्यैः परिवृतो मुनिरप्यभिनिष्पतत्।
तं ददर्शाग्रतो रामो मुनीनां दीप्ततेजसं।
अब्रवीद्वचनं वीरो लक्ष्मणं लक्ष्मिवर्धनम्॥', 'tataḥ śiṣyaiḥ parivṛto munir apy abhiniṣpatat
taṃ dadarśāgrato rāmo munīnāṃ dīptatejasaṃ
abravīd vacanaṃ vīro lakṣmaṇaṃ lakṣmivardhanam', null, 3011019),
('ramayana-3-11-20', 20, 'Aranya Kanda, Sarga 11, Verse 20', 'एष लक्ष्मण निष्क्रामत्यगस्त्यो भगवानृषिः।
औदार्येणावगच्छामि निधानं तपसामिमम्॥', 'eṣa lakṣmaṇa niṣkrāmaty agastyo bhagavān ṛṣiḥ
audāryeṇāvagacchāmi nidhānaṃ tapasām imam', null, 3011020),
('ramayana-3-11-21', 21, 'Aranya Kanda, Sarga 11, Verse 21', 'एवमुक्त्वा महाबाहुरगस्त्यं सूर्यवर्चसं।
जग्राह परमप्रीतस्तस्य पादौ परंतपः॥', 'evam uktvā mahābāhur agastyaṃ sūryavarcasaṃ
jagrāha paramaprītas tasya pādau paraṃtapaḥ', null, 3011021),
('ramayana-3-11-22', 22, 'Aranya Kanda, Sarga 11, Verse 22', 'अभिवाद्य तु धर्मात्मा तस्थौ रामः कृताञ्जलिः।
सीतया सह वैदेह्या तदा राम सलक्ष्मणः॥', 'abhivādya tu dharmātmā tasthau rāmaḥ kṛtāñjaliḥ
sītayā saha vaidehyā tadā rāma salakṣmaṇaḥ', null, 3011022),
('ramayana-3-11-23', 23, 'Aranya Kanda, Sarga 11, Verse 23', 'प्रतिगृह्य च काकुत्स्थमर्चयित्वासनोदकैः।
कुशलप्रश्नमुक्त्वा च आस्यतामिति सोऽब्रवीत्॥', 'pratigṛhya ca kākutstham arcayitvāsanodakaiḥ
kuśalapraśnam uktvā ca āsyatām iti so ''bravīt', null, 3011023),
('ramayana-3-11-24', 24, 'Aranya Kanda, Sarga 11, Verse 24', 'अग्निं हुत्वा प्रदायार्घ्यमतिथिं प्रतिपूज्य च।
वानप्रस्थेन धर्मेण स तेषां भोजनं ददौ॥', 'agniṃ hutvā pradāyārghyam atithiṃ pratipūjya ca
vānaprasthena dharmeṇa sa teṣāṃ bhojanaṃ dadau', null, 3011024),
('ramayana-3-11-25', 25, 'Aranya Kanda, Sarga 11, Verse 25', 'प्रथमं चोपविश्याथ धर्मज्ञो मुनिपुंगवः।
उवाच राममासीनं प्राञ्जलिं धर्मकोविदम्॥', 'prathamaṃ copaviśyātha dharmajño munipuṃgavaḥ
uvāca rāmam āsīnaṃ prāñjaliṃ dharmakovidam', null, 3011025),
('ramayana-3-11-26', 26, 'Aranya Kanda, Sarga 11, Verse 26', 'अन्यथा खलु काकुत्स्थ तपस्वी समुदाचरन्।
दुःसाक्षीव परे लोके स्वानि मांसानि भक्षयेत्॥', 'anyathā khalu kākutstha tapasvī samudācaran
duḥsākṣīva pare loke svāni māṃsāni bhakṣayet', null, 3011026),
('ramayana-3-11-27', 27, 'Aranya Kanda, Sarga 11, Verse 27', 'राजा सर्वस्य लोकस्य धर्मचारी महारथः।
पूजनीयश्च मान्यश्च भवान्प्राप्तः प्रियातिथिः॥', 'rājā sarvasya lokasya dharmacārī mahārathaḥ
pūjanīyaś ca mānyaś ca bhavān prāptaḥ priyātithiḥ', null, 3011027),
('ramayana-3-11-28', 28, 'Aranya Kanda, Sarga 11, Verse 28', 'एवमुक्त्वा फलैर्मूलैः पुष्पैश्चान्यैश्च राघवम्।
पूजयित्वा यथाकामं पुनरेव ततोऽब्रवीत्॥', 'evam uktvā phalair mūlaiḥ puṣpaiś cānyaiś ca rāghavam
pūjayitvā yathākāmaṃ punar eva tato ''bravīt', null, 3011028),
('ramayana-3-11-29', 29, 'Aranya Kanda, Sarga 11, Verse 29', 'इदं दिव्यं महच्चापं हेमवज्रविभूषितम्।
वैष्णवं पुरुषव्याघ्र निर्मितं विश्वकर्मणा॥', 'idaṃ divyaṃ mahac cāpaṃ hemavajravibhūṣitam
vaiṣṇavaṃ puruṣavyāghra nirmitaṃ viśvakarmaṇā', null, 3011029),
('ramayana-3-11-30', 30, 'Aranya Kanda, Sarga 11, Verse 30', 'अमोघः सूर्यसंकाशो ब्रह्मदत्तः शरोत्तमः।
दत्तो मम महेन्द्रेण तूणी चाक्षयसायकौ॥', 'amoghaḥ sūryasaṃkāśo brahmadattaḥ śarottamaḥ
datto mama mahendreṇa tūṇī cākṣayasāyakau', null, 3011030),
('ramayana-3-11-31', 31, 'Aranya Kanda, Sarga 11, Verse 31', 'संपूर्णौ निशितैर्बाणैर्ज्वलद्भिरिव पावकैः।
महाराजत कोशोऽयमसिर्हेमविभूषितः॥', 'saṃpūrṇau niśitair bāṇair jvaladbhir iva pāvakaiḥ
mahārājata kośo ''yam asir hemavibhūṣitaḥ', null, 3011031),
('ramayana-3-11-32', 32, 'Aranya Kanda, Sarga 11, Verse 32', 'अनेन धनुषा राम हत्वा संख्ये महासुरान्।
आजहार श्रियं दीप्तां पुरा विष्णुर्दिवौकसाम्॥', 'anena dhanuṣā rāma hatvā saṃkhye mahāsurān
ājahāra śriyaṃ dīptāṃ purā viṣṇur divaukasām', null, 3011032),
('ramayana-3-11-33', 33, 'Aranya Kanda, Sarga 11, Verse 33', 'तद्धनुस्तौ च तूणीरौ शरं खड्गं च मानद।
जयाय प्रतिगृह्णीष्व वज्रं वज्रधरो यथा॥', 'tad dhanus tau ca tūṇīrau śaraṃ khaḍgaṃ ca mānada
jayāya pratigṛhṇīṣva vajraṃ vajradharo yathā', null, 3011033),
('ramayana-3-11-34', 34, 'Aranya Kanda, Sarga 11, Verse 34', 'एवमुक्त्वा महातेजाः समस्तं तद्वरायुधम्।
दत्त्वा रामाय भगवानगस्त्यः पुनरब्रवीत्॥', 'evam uktvā mahātejāḥ samastaṃ tad varāyudham
dattvā rāmāya bhagavān agastyaḥ punar abravīt', null, 3011034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 12 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-12-1', 1, 'Aranya Kanda, Sarga 12, Verse 1', 'राम प्रीतोऽस्मि भद्रं ते परितुष्टोऽस्मि लक्ष्मण।
अभिवादयितुं यन्मां प्राप्तौ स्थः सह सीतया॥', 'rāma prīto ''smi bhadraṃ te parituṣṭo ''smi lakṣmaṇa
abhivādayituṃ yan māṃ prāptau sthaḥ saha sītayā', null, 3012001),
('ramayana-3-12-2', 2, 'Aranya Kanda, Sarga 12, Verse 2', 'अध्वश्रमेण वां खेदो बाधते प्रचुरश्रमः।
व्यक्तमुत्कण्ठते चापि मैथिली जनकात्मजा॥', 'adhvaśrameṇa vāṃ khedo bādhate pracuraśramaḥ
vyaktam utkaṇṭhate cāpi maithilī janakātmajā', null, 3012002),
('ramayana-3-12-3', 3, 'Aranya Kanda, Sarga 12, Verse 3', 'एषा हि सुकुमारी च दुःखैश्च न विमानिता।
प्राज्यदोषं वनं प्रप्ता भर्तृस्नेहप्रचोदिता॥', 'eṣā hi sukumārī ca duḥkhaiś ca na vimānitā
prājyadoṣaṃ vanaṃ praptā bhartṛsnehapracoditā', null, 3012003),
('ramayana-3-12-4', 4, 'Aranya Kanda, Sarga 12, Verse 4', 'यथैषा रमते राम इह सीता तथा कुरु।
दुष्करं कृतवत्येषा वने त्वामनुगच्छती॥', 'yathaiṣā ramate rāma iha sītā tathā kuru
duṣkaraṃ kṛtavaty eṣā vane tvām anugacchatī', null, 3012004),
('ramayana-3-12-5', 5, 'Aranya Kanda, Sarga 12, Verse 5', 'एषा हि प्रकृतिः स्त्रीणामासृष्टे रघुनन्दन।
समस्थमनुरज्यन्ते विषमस्थं त्यजन्ति च॥', 'eṣā hi prakṛtiḥ strīṇām āsṛṣṭe raghunandana
samastham anurajyante viṣamasthaṃ tyajanti ca', null, 3012005),
('ramayana-3-12-6', 6, 'Aranya Kanda, Sarga 12, Verse 6', 'शतह्रदानां लोलत्वं शस्त्राणां तीक्ष्णतां तथा।
गरुडानिलयोः शैघ्र्यमनुगच्छन्ति योषितः॥', 'śatahradānāṃ lolatvaṃ śastrāṇāṃ tīkṣṇatāṃ tathā
garuḍānilayoḥ śaighryam anugacchanti yoṣitaḥ', null, 3012006),
('ramayana-3-12-7', 7, 'Aranya Kanda, Sarga 12, Verse 7', 'इयं तु भवतो भार्या दोषैरेतैर्विवर्जिताः।
श्लाघ्या च व्यपदेश्या च यथा देवी ह्यरुन्धती॥', 'iyaṃ tu bhavato bhāryā doṣair etair vivarjitāḥ
ślāghyā ca vyapadeśyā ca yathā devī hy arundhatī', null, 3012007),
('ramayana-3-12-8', 8, 'Aranya Kanda, Sarga 12, Verse 8', 'अलंकृतोऽयं देशश्च यत्र सौमित्रिणा सह।
वैदेह्या चानया राम वत्स्यसि त्वमरिंदम॥', 'alaṃkṛto ''yaṃ deśaś ca yatra saumitriṇā saha
vaidehyā cānayā rāma vatsyasi tvam ariṃdama', null, 3012008),
('ramayana-3-12-9', 9, 'Aranya Kanda, Sarga 12, Verse 9', 'एवमुक्तस्तु मुनिना राघवः संयताञ्जलिः।
उवाच प्रश्रितं वाक्यमृषिं दीप्तमिवानलम्॥', 'evam uktas tu muninā rāghavaḥ saṃyatāñjaliḥ
uvāca praśritaṃ vākyam ṛṣiṃ dīptam ivānalam', null, 3012009),
('ramayana-3-12-10', 10, 'Aranya Kanda, Sarga 12, Verse 10', 'धन्योऽस्म्यनुगृहीतोऽस्मि यस्य मे मुनिपुंगवः।
गुणैः सभ्रातृभार्यस्य वरदः परितुष्यति॥', 'dhanyo ''smy anugṛhīto ''smi yasya me munipuṃgavaḥ
guṇaiḥ sabhrātṛbhāryasya varadaḥ parituṣyati', null, 3012010),
('ramayana-3-12-11', 11, 'Aranya Kanda, Sarga 12, Verse 11', 'किं तु व्यादिश मे देशं सोदकं बहुकाननम्।
यत्राश्रमपदं कृत्वा वसेयं निरतः सुखम्॥', 'kiṃ tu vyādiśa me deśaṃ sodakaṃ bahukānanam
yatrāśramapadaṃ kṛtvā vaseyaṃ nirataḥ sukham', null, 3012011),
('ramayana-3-12-12', 12, 'Aranya Kanda, Sarga 12, Verse 12', 'ततोऽब्रवीन्मुनि श्रेष्ठः श्रुत्वा रामस्य भाषितम्।
ध्यात्वा मुहूर्तं धर्मात्मा धीरो धीरतरं वचः॥', 'tato ''bravīn muni śreṣṭhaḥ śrutvā rāmasya bhāṣitam
dhyātvā muhūrtaṃ dharmātmā dhīro dhīrataraṃ vacaḥ', null, 3012012),
('ramayana-3-12-13', 13, 'Aranya Kanda, Sarga 12, Verse 13', 'इतो द्वियोजने तात बहुमूलफलोदकः।
देशो बहुमृगः श्रीमान्पञ्चवट्यभिविश्रुतः॥', 'ito dviyojane tāta bahumūlaphalodakaḥ
deśo bahumṛgaḥ śrīmān pañcavaṭy abhiviśrutaḥ', null, 3012013),
('ramayana-3-12-14', 14, 'Aranya Kanda, Sarga 12, Verse 14', 'तत्र गत्वाश्रमपदं कृत्वा सौमित्रिणा सह।
रमस्व त्वं पितुर्वाक्यं यथोक्तमनुपालयन्॥', 'tatra gatvāśramapadaṃ kṛtvā saumitriṇā saha
ramasva tvaṃ pitur vākyaṃ yathoktam anupālayan', null, 3012014),
('ramayana-3-12-15', 15, 'Aranya Kanda, Sarga 12, Verse 15', 'विदितो ह्येष वृत्तान्तो मम सर्वस्तवानघ।
तपसश्च प्रभावेन स्नेहाद्दशरथस्य च॥', 'vidito hy eṣa vṛttānto mama sarvas tavānagha
tapasaś ca prabhāvena snehād daśarathasya ca', null, 3012015),
('ramayana-3-12-16', 16, 'Aranya Kanda, Sarga 12, Verse 16', 'हृदयस्थश्च ते छन्दो विज्ञातस्तपसा मया।
इह वासं प्रतिज्ञाय मया सह तपोवने॥', 'hṛdayasthaś ca te chando vijñātas tapasā mayā
iha vāsaṃ pratijñāya mayā saha tapovane', null, 3012016),
('ramayana-3-12-17', 17, 'Aranya Kanda, Sarga 12, Verse 17', 'अतश्च त्वामहं ब्रूमि गच्छ पञ्चवटीमिति।
स हि रम्यो वनोद्देशो मैथिली तत्र रंस्यते॥', 'ataś ca tvām ahaṃ brūmi gaccha pañcavaṭīm iti
sa hi ramyo vanoddeśo maithilī tatra raṃsyate', null, 3012017),
('ramayana-3-12-18', 18, 'Aranya Kanda, Sarga 12, Verse 18', 'स देशः श्लाघनीयश्च नातिदूरे च राघव।
गोदावर्याः समीपे च मैथिली तत्र रंस्यते॥', 'sa deśaḥ ślāghanīyaś ca nātidūre ca rāghava
godāvaryāḥ samīpe ca maithilī tatra raṃsyate', null, 3012018),
('ramayana-3-12-19', 19, 'Aranya Kanda, Sarga 12, Verse 19', 'प्राज्यमूलफलैश्चैव नानाद्विज गणैर्युतः।
विविक्तश्च महाबाहो पुण्यो रम्यस्तथैव च॥', 'prājyamūlaphalaiś caiva nānādvija gaṇair yutaḥ
viviktaś ca mahābāho puṇyo ramyas tathaiva ca', null, 3012019),
('ramayana-3-12-20', 20, 'Aranya Kanda, Sarga 12, Verse 20', 'भवानपि सदारश्च शक्तश्च परिरक्षणे।
अपि चात्र वसन्रामस्तापसान्पालयिष्यसि॥', 'bhavān api sadāraś ca śaktaś ca parirakṣaṇe
api cātra vasan rāmas tāpasān pālayiṣyasi', null, 3012020),
('ramayana-3-12-21', 21, 'Aranya Kanda, Sarga 12, Verse 21', 'एतदालक्ष्यते वीर मधुकानां महद्वनम्।
उत्तरेणास्य गन्तव्यं न्यग्रोधमभिगच्छता॥', 'etad ālakṣyate vīra madhukānāṃ mahad vanam
uttareṇāsya gantavyaṃ nyagrodham abhigacchatā', null, 3012021),
('ramayana-3-12-22', 22, 'Aranya Kanda, Sarga 12, Verse 22', 'ततः स्थलमुपारुह्य पर्वतस्याविदूरतः।
ख्यातः पञ्चवटीत्येव नित्यपुष्पितकाननः॥', 'tataḥ sthalam upāruhya parvatasyāvidūrataḥ
khyātaḥ pañcavaṭīty eva nityapuṣpitakānanaḥ', null, 3012022),
('ramayana-3-12-23', 23, 'Aranya Kanda, Sarga 12, Verse 23', 'अगस्त्येनैवमुक्तस्तु रामः सौमित्रिणा सह।
सात्कृत्यामन्त्रयामास तमृषिं सत्यवादिनम्॥', 'agastyenaivam uktas tu rāmaḥ saumitriṇā saha
sātkṛtyāmantrayām āsa tam ṛṣiṃ satyavādinam', null, 3012023),
('ramayana-3-12-24', 24, 'Aranya Kanda, Sarga 12, Verse 24', 'तौ तु तेनाभ्यनुज्ञातौ कृतपादाभिवन्दनौ।
तदाश्रमात्पञ्चवटीं जग्मतुः सह सीतया॥', 'tau tu tenābhyanujñātau kṛtapādābhivandanau
tadāśramāt pañcavaṭīṃ jagmatuḥ saha sītayā', null, 3012024),
('ramayana-3-12-25', 25, 'Aranya Kanda, Sarga 12, Verse 25', 'गृहीतचापौ तु नराधिपात्मजौ विषक्ततूणी समरेष्वकातरौ।
यथोपदिष्टेन पथा महर्षिणा प्रजग्मतुः पञ्चवटीं समाहितौ॥', 'gṛhītacāpau tu narādhipātmajau viṣaktatūṇī samareṣv akātarau
yathopadiṣṭena pathā maharṣiṇā prajagmatuḥ pañcavaṭīṃ samāhitau', null, 3012025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 13 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-13-1', 1, 'Aranya Kanda, Sarga 13, Verse 1', 'अथ पञ्चवटीं गच्छन्नन्तरा रघुनन्दनः।
आससाद महाकायं गृध्रं भीमपराक्रमम्॥', 'atha pañcavaṭīṃ gacchann antarā raghunandanaḥ
āsasāda mahākāyaṃ gṛdhraṃ bhīmaparākramam', null, 3013001),
('ramayana-3-13-2', 2, 'Aranya Kanda, Sarga 13, Verse 2', 'तं दृष्ट्वा तौ महाभागौ वनस्थं रामलक्ष्मणौ।
मेनाते राक्षसं पक्षिं ब्रुवाणौ को भवानिति॥', 'taṃ dṛṣṭvā tau mahābhāgau vanasthaṃ rāmalakṣmaṇau
menāte rākṣasaṃ pakṣiṃ bruvāṇau ko bhavān iti', null, 3013002),
('ramayana-3-13-3', 3, 'Aranya Kanda, Sarga 13, Verse 3', 'स तौ मधुरया वाचा सौम्यया प्रीणयन्निव।
उवाच वत्स मां विद्धि वयस्यं पितुरात्मनः॥', 'sa tau madhurayā vācā saumyayā prīṇayann iva
uvāca vatsa māṃ viddhi vayasyaṃ pitur ātmanaḥ', null, 3013003),
('ramayana-3-13-4', 4, 'Aranya Kanda, Sarga 13, Verse 4', 'स तं पितृसखं बुद्ध्वा पूजयामास राघवः।
स तस्य कुलमव्यग्रमथ पप्रच्छ नाम च॥', 'sa taṃ pitṛsakhaṃ buddhvā pūjayām āsa rāghavaḥ
sa tasya kulam avyagram atha papraccha nāma ca', null, 3013004),
('ramayana-3-13-5', 5, 'Aranya Kanda, Sarga 13, Verse 5', 'रामस्य वचनं श्रुत्वा कुलमात्मानमेव च।
आचचक्षे द्विजस्तस्मै सर्वभूतसमुद्भवम्॥', 'rāmasya vacanaṃ śrutvā kulam ātmānam eva ca
ācacakṣe dvijas tasmai sarvabhūtasamudbhavam', null, 3013005),
('ramayana-3-13-6', 6, 'Aranya Kanda, Sarga 13, Verse 6', 'पूर्वकाले महाबाहो ये प्रजापतयोऽभवन्।
तान्मे निगदतः सर्वानादितः शृणु राघव॥', 'pūrvakāle mahābāho ye prajāpatayo ''bhavan
tān me nigadataḥ sarvān āditaḥ śṛṇu rāghava', null, 3013006),
('ramayana-3-13-7', 7, 'Aranya Kanda, Sarga 13, Verse 7', 'कर्दमः प्रथमस्तेषां विकृतस्तदनन्तरम्।
शेषश्च संश्रयश्चैव बहुपुत्रश्च वीर्यवान्॥', 'kardamaḥ prathamas teṣāṃ vikṛtas tadanantaram
śeṣaś ca saṃśrayaś caiva bahuputraś ca vīryavān', null, 3013007),
('ramayana-3-13-8', 8, 'Aranya Kanda, Sarga 13, Verse 8', 'स्थाणुर्मरीचिरत्रिश्च क्रतुश्चैव महाबलः।
पुलस्त्यश्चाङ्गिराश्चैव प्रचेताः पुलहस्तथा॥', 'sthāṇur marīcir atriś ca kratuś caiva mahābalaḥ
pulastyaś cāṅgirāś caiva pracetāḥ pulahas tathā', null, 3013008),
('ramayana-3-13-9', 9, 'Aranya Kanda, Sarga 13, Verse 9', 'दक्षो विवस्वानपरोऽरिष्टनेमिश्च राघव।
कश्यपश्च महातेजास्तेषामासीच्च पश्चिमः॥', 'dakṣo vivasvān aparo ''riṣṭanemiś ca rāghava
kaśyapaś ca mahātejās teṣām āsīc ca paścimaḥ', null, 3013009),
('ramayana-3-13-10', 10, 'Aranya Kanda, Sarga 13, Verse 10', 'प्रजापतेस्तु दक्षस्य बभूवुरिति नः श्रुतम्।
षष्टिर्दुहितरो राम यशस्विन्यो महायशः॥', 'prajāpates tu dakṣasya babhūvur iti naḥ śrutam
ṣaṣṭir duhitaro rāma yaśasvinyo mahāyaśaḥ', null, 3013010),
('ramayana-3-13-11', 11, 'Aranya Kanda, Sarga 13, Verse 11', 'कश्यपः प्रतिजग्राह तासामष्टौ सुमध्यमाः।
अदितिं च दितिं चैव दनूमपि च कालकाम्॥', 'kaśyapaḥ pratijagrāha tāsām aṣṭau sumadhyamāḥ
aditiṃ ca ditiṃ caiva danūm api ca kālakām', null, 3013011),
('ramayana-3-13-12', 12, 'Aranya Kanda, Sarga 13, Verse 12', 'ताम्रां क्रोधवशां चैव मनुं चाप्यनलामपि।
तास्तु कन्यास्ततः प्रीतः कश्यपः पुनरब्रवीत्॥', 'tāmrāṃ krodhavaśāṃ caiva manuṃ cāpy analām api
tās tu kanyās tataḥ prītaḥ kaśyapaḥ punar abravīt', null, 3013012),
('ramayana-3-13-13', 13, 'Aranya Kanda, Sarga 13, Verse 13', 'पुत्रांस्त्रैलोक्यभर्तॄन्वै जनयिष्यथ मत्समान्।
अदितिस्तन्मना राम दितिश्च दनुरेव च॥', 'putrāṃs trailokyabhartṝn vai janayiṣyatha mat samān
aditis tan manā rāma ditiś ca danur eva ca', null, 3013013),
('ramayana-3-13-14', 14, 'Aranya Kanda, Sarga 13, Verse 14', 'कालका च महाबाहो शेषास्त्वमनसोऽभवन्।
अदित्यां जज्ञिरे देवास्त्रयस्त्रिंशदरिंदम॥', 'kālakā ca mahābāho śeṣās tv amanaso ''bhavan
adityāṃ jajñire devās trayastriṃśad ariṃdama', null, 3013014),
('ramayana-3-13-15', 15, 'Aranya Kanda, Sarga 13, Verse 15', 'आदित्या वसवो रुद्रा अश्विनौ च परंतप।
दितिस्त्वजनयत्पुत्रान्दैत्यांस्तात यशस्विनः॥', 'ādityā vasavo rudrā aśvinau ca paraṃtapa
ditis tv ajanayat putrān daityāṃs tāta yaśasvinaḥ', null, 3013015),
('ramayana-3-13-16', 16, 'Aranya Kanda, Sarga 13, Verse 16', 'तेषामियं वसुमती पुरासीत्सवनार्णवा।
दनुस्त्वजनयत्पुत्रमश्वग्रीवमरिंदम॥', 'teṣām iyaṃ vasumatī purāsīt savanārṇavā
danus tv ajanayat putram aśvagrīvam ariṃdama', null, 3013016),
('ramayana-3-13-17', 17, 'Aranya Kanda, Sarga 13, Verse 17', 'नरकं कालकं चैव कालकापि व्यजायत।
क्रौञ्चीं भासीं तथा श्येनीं धृतराष्ट्रीं तथा शुकीम्॥', 'narakaṃ kālakaṃ caiva kālakāpi vyajāyata
krauñcīṃ bhāsīṃ tathā śyenīṃ dhṛtarāṣṭrīṃ tathā śukīm', null, 3013017),
('ramayana-3-13-18', 18, 'Aranya Kanda, Sarga 13, Verse 18', 'ताम्रापि सुषुवे कन्याः पञ्चैता लोकविश्रुताः।
उलूकाञ्जनयत्क्रौञ्ची भासी भासान्व्यजायत॥', 'tāmrāpi suṣuve kanyāḥ pañcaitā lokaviśrutāḥ
ulūkāñ janayat krauñcī bhāsī bhāsān vyajāyata', null, 3013018),
('ramayana-3-13-19', 19, 'Aranya Kanda, Sarga 13, Verse 19', 'श्येनी श्येनांश्च गृध्रांश्च व्यजायत सुतेजसः।
धृतराष्ट्री तु हंसांश्च कलहंसांश्च सर्वशः॥', 'śyenī śyenāṃś ca gṛdhrāṃś ca vyajāyata sutejasaḥ
dhṛtarāṣṭrī tu haṃsāṃś ca kalahaṃsāṃś ca sarvaśaḥ', null, 3013019),
('ramayana-3-13-20', 20, 'Aranya Kanda, Sarga 13, Verse 20', 'चक्रवाकांश्च भद्रं ते विजज्ञे सापि भामिनी।
शुकी नतां विजज्ञे तु नताया विनता सुता॥', 'cakravākāṃś ca bhadraṃ te vijajñe sāpi bhāminī
śukī natāṃ vijajñe tu natāyā vinatā sutā', null, 3013020),
('ramayana-3-13-21', 21, 'Aranya Kanda, Sarga 13, Verse 21', 'दशक्रोधवशा राम विजज्ञेऽप्यात्मसंभवाः।
मृगीं च मृगमन्दां च हरीं भद्रमदामपि॥', 'daśakrodhavaśā rāma vijajñe ''py ātmasaṃbhavāḥ
mṛgīṃ ca mṛgamandāṃ ca harīṃ bhadramadām api', null, 3013021),
('ramayana-3-13-22', 22, 'Aranya Kanda, Sarga 13, Verse 22', 'मातङ्गीमथ शार्दूलीं श्वेतां च सुरभीं तथा।
सर्वलक्षणसंपन्नां सुरसां कद्रुकामपि॥', 'mātaṅgīm atha śārdūlīṃ śvetāṃ ca surabhīṃ tathā
sarvalakṣaṇasaṃpannāṃ surasāṃ kadrukām api', null, 3013022),
('ramayana-3-13-23', 23, 'Aranya Kanda, Sarga 13, Verse 23', 'अपत्यं तु मृगाः सर्वे मृग्या नरवरोत्तम।
ऋष्काश्च मृगमन्दायाः सृमराश्चमरास्तथा॥', 'apatyaṃ tu mṛgāḥ sarve mṛgyā naravarottama
ṛṣkāś ca mṛgamandāyāḥ sṛmarāś camarās tathā', null, 3013023),
('ramayana-3-13-24', 24, 'Aranya Kanda, Sarga 13, Verse 24', 'ततस्त्विरावतीं नाम जज्ञे भद्रमदा सुताम्।
तस्यास्त्वैरावतः पुत्रो लोकनाथो महागजः॥', 'tatas tv irāvatīṃ nāma jajñe bhadramadā sutām
tasyās tv airāvataḥ putro lokanātho mahāgajaḥ', null, 3013024),
('ramayana-3-13-25', 25, 'Aranya Kanda, Sarga 13, Verse 25', 'हर्याश्च हरयोऽपत्यं वानराश्च तपस्विनः।
गोलाङ्गूलांश्च शार्दूली व्याघ्रांश्चाजनयत्सुतान्॥', 'haryāś ca harayo ''patyaṃ vānarāś ca tapasvinaḥ
golāṅgūlāṃś ca śārdūlī vyāghrāṃś cājanayat sutān', null, 3013025),
('ramayana-3-13-26', 26, 'Aranya Kanda, Sarga 13, Verse 26', 'मातङ्ग्यास्त्वथ मातङ्गा अपत्यं मनुजर्षभ।
दिशागजं तु श्वेताक्षं श्वेता व्यजनयत्सुतम्॥', 'mātaṅgyās tv atha mātaṅgā apatyaṃ manujarṣabha
diśāgajaṃ tu śvetākṣaṃ śvetā vyajanayat sutam', null, 3013026),
('ramayana-3-13-27', 27, 'Aranya Kanda, Sarga 13, Verse 27', 'ततो दुहितरौ राम सुरभिर्देव्यजायत।
रोहिणीं नाम भद्रं ते गन्धर्वीं च यशस्विनीम्॥', 'tato duhitarau rāma surabhir devy ajāyata
rohiṇīṃ nāma bhadraṃ te gandharvīṃ ca yaśasvinīm', null, 3013027),
('ramayana-3-13-28', 28, 'Aranya Kanda, Sarga 13, Verse 28', 'रोहिण्यजनयद्गा वै गन्धर्वी वाजिनः सुतान्।
सुरसाजनयन्नागान्राम कद्रूश्च पन्नगान्॥', 'rohiṇy ajanayad gā vai gandharvī vājinaḥ sutān
surasājanayan nāgān rāma kadrūś ca pannagān', null, 3013028),
('ramayana-3-13-29', 29, 'Aranya Kanda, Sarga 13, Verse 29', 'मनुर्मनुष्याञ्जनयत्कश्यपस्य महात्मनः।
ब्राह्मणान्क्षत्रियान्वैश्याञ्शूद्रांश्च मनुजर्षभ॥', 'manur manuṣyāñ janayat kaśyapasya mahātmanaḥ
brāhmaṇān kṣatriyān vaiśyāñ śūdrāṃś ca manujarṣabha', null, 3013029),
('ramayana-3-13-30', 30, 'Aranya Kanda, Sarga 13, Verse 30', 'मुखतो ब्राह्मणा जाता उरसः क्षत्रियास्तथा।
ऊरुभ्यां जज्ञिरे वैश्याः पद्भ्यां शूद्रा इति श्रुतिः॥', 'mukhato brāhmaṇā jātā urasaḥ kṣatriyās tathā
ūrubhyāṃ jajñire vaiśyāḥ padbhyāṃ śūdrā iti śrutiḥ', null, 3013030),
('ramayana-3-13-31', 31, 'Aranya Kanda, Sarga 13, Verse 31', 'सर्वान्पुण्यफलान्वृक्षाननलापि व्यजायत।
विनता च शुकी पौत्री कद्रूश्च सुरसा स्वसा॥', 'sarvān puṇyaphalān vṛkṣān analāpi vyajāyata
vinatā ca śukī pautrī kadrūś ca surasā svasā', null, 3013031),
('ramayana-3-13-32', 32, 'Aranya Kanda, Sarga 13, Verse 32', 'कद्रूर्नागसहस्क्रं तु विजज्ञे धरणीधरम्।
द्वौ पुत्रौ विनतायास्तु गरुडोऽरुण एव च॥', 'kadrūr nāgasahaskraṃ tu vijajñe dharaṇīdharam
dvau putrau vinatāyās tu garuḍo ''ruṇa eva ca', null, 3013032),
('ramayana-3-13-33', 33, 'Aranya Kanda, Sarga 13, Verse 33', 'तस्माज्जातोऽहमरुणात्संपातिश्च ममाग्रजः।
जटायुरिति मां विद्धि श्येनीपुत्रमरिंदम॥', 'tasmāj jāto ''ham aruṇāt saṃpātiś ca mamāgrajaḥ
jaṭāyur iti māṃ viddhi śyenīputram ariṃdama', null, 3013033),
('ramayana-3-13-34', 34, 'Aranya Kanda, Sarga 13, Verse 34', 'सोऽहं वाससहायस्ते भविष्यामि यदीच्छसि।
सीतां च तात रक्षिष्ये त्वयि याते सलक्ष्मणे॥', 'so ''haṃ vāsasahāyas te bhaviṣyāmi yadīcchasi
sītāṃ ca tāta rakṣiṣye tvayi yāte salakṣmaṇe', null, 3013034),
('ramayana-3-13-35', 35, 'Aranya Kanda, Sarga 13, Verse 35', 'जटायुषं तु प्रतिपूज्य राघवो मुदा परिष्वज्य च संनतोऽभवत्।
पितुर्हि शुश्राव सखित्वमात्मवाञ्जटायुषा संकथितं पुनः पुनः॥', 'jaṭāyuṣaṃ tu pratipūjya rāghavo mudā pariṣvajya ca saṃnato ''bhavat
pitur hi śuśrāva sakhitvam ātmavāñ jaṭāyuṣā saṃkathitaṃ punaḥ punaḥ', null, 3013035),
('ramayana-3-13-36', 36, 'Aranya Kanda, Sarga 13, Verse 36', 'स तत्र सीतां परिदाय मैथिलीं सहैव तेनातिबलेन पक्षिणा।
जगाम तां पञ्चवटीं सलक्ष्मणो रिपून्दिधक्षञ्शलभानिवानलः॥', 'sa tatra sītāṃ paridāya maithilīṃ sahaiva tenātibalena pakṣiṇā
jagāma tāṃ pañcavaṭīṃ salakṣmaṇo ripūn didhakṣañ śalabhān ivānalaḥ', null, 3013036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 14 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-14-1', 1, 'Aranya Kanda, Sarga 14, Verse 1', 'ततः पञ्चवटीं गत्वा नानाव्यालमृगायुताम्।
उवाच भ्रातरं रामो लक्ष्मणं दीप्ततेजसं॥', 'tataḥ pañcavaṭīṃ gatvā nānāvyālamṛgāyutām
uvāca bhrātaraṃ rāmo lakṣmaṇaṃ dīptatejasaṃ', null, 3014001),
('ramayana-3-14-2', 2, 'Aranya Kanda, Sarga 14, Verse 2', 'आगताः स्म यथोद्दिष्टममुं देशं महर्षिणा।
अयं पञ्चवटी देशः सौम्य पुष्पितकाननः॥', 'āgatāḥ sma yathoddiṣṭam amuṃ deśaṃ maharṣiṇā
ayaṃ pañcavaṭī deśaḥ saumya puṣpitakānanaḥ', null, 3014002),
('ramayana-3-14-3', 3, 'Aranya Kanda, Sarga 14, Verse 3', 'सर्वतश्चार्यतां दृष्टिः कानने निपुणो ह्यसि।
आश्रमः कतरस्मिन्नो देशे भवति संमतः॥', 'sarvataś cāryatāṃ dṛṣṭiḥ kānane nipuṇo hy asi
āśramaḥ katarasmin no deśe bhavati saṃmataḥ', null, 3014003),
('ramayana-3-14-4', 4, 'Aranya Kanda, Sarga 14, Verse 4', 'रमते यत्र वैदेही त्वमहं चैव लक्ष्मण।
तादृशो दृश्यतां देशः संनिकृष्टजलाशयः॥', 'ramate yatra vaidehī tvam ahaṃ caiva lakṣmaṇa
tādṛśo dṛśyatāṃ deśaḥ saṃnikṛṣṭajalāśayaḥ', null, 3014004),
('ramayana-3-14-5', 5, 'Aranya Kanda, Sarga 14, Verse 5', 'वनरामण्यकं यत्र जलरामण्यकं तथा।
संनिकृष्टं च यत्र स्यात्समित्पुष्पकुशोदकम्॥', 'vanarāmaṇyakaṃ yatra jalarāmaṇyakaṃ tathā
saṃnikṛṣṭaṃ ca yatra syāt samitpuṣpakuśodakam', null, 3014005),
('ramayana-3-14-6', 6, 'Aranya Kanda, Sarga 14, Verse 6', 'एवमुक्तस्तु रामेण लक्मणः संयताञ्जलिः।
सीता समक्षं काकुत्स्थमिदं वचनमब्रवीत्॥', 'evam uktas tu rāmeṇa lakmaṇaḥ saṃyatāñjaliḥ
sītā samakṣaṃ kākutstham idaṃ vacanam abravīt', null, 3014006),
('ramayana-3-14-7', 7, 'Aranya Kanda, Sarga 14, Verse 7', 'परवानस्मि काकुत्स्थ त्वयि वर्षशतं स्थिते।
स्वयं तु रुचिरे देशे क्रियतामिति मां वद॥', 'paravān asmi kākutstha tvayi varṣaśataṃ sthite
svayaṃ tu rucire deśe kriyatām iti māṃ vada', null, 3014007),
('ramayana-3-14-8', 8, 'Aranya Kanda, Sarga 14, Verse 8', 'सुप्रीतस्तेन वाक्येन लक्ष्मणस्य महाद्युतिः।
विमृशन्रोचयामास देशं सर्वगुणान्वितम्॥', 'suprītas tena vākyena lakṣmaṇasya mahādyutiḥ
vimṛśan rocayām āsa deśaṃ sarvaguṇānvitam', null, 3014008),
('ramayana-3-14-9', 9, 'Aranya Kanda, Sarga 14, Verse 9', 'स तं रुचिरमाक्रम्य देशमाश्रमकर्मणि।
हस्ते गृहीत्वा हस्तेन रामः सौमित्रिमब्रवीत्॥', 'sa taṃ ruciram ākramya deśam āśramakarmaṇi
haste gṛhītvā hastena rāmaḥ saumitrim abravīt', null, 3014009),
('ramayana-3-14-10', 10, 'Aranya Kanda, Sarga 14, Verse 10', 'अयं देशः समः श्रीमान्पुष्पितैर्तरुभिर्वृतः।
इहाश्रमपदं सौम्य यथावत्कर्तुमर्हसि॥', 'ayaṃ deśaḥ samaḥ śrīmān puṣpitair tarubhir vṛtaḥ
ihāśramapadaṃ saumya yathāvat kartum arhasi', null, 3014010),
('ramayana-3-14-11', 11, 'Aranya Kanda, Sarga 14, Verse 11', 'इयमादित्यसंकाशैः पद्मैः सुरभिगन्धिभिः।
अदूरे दृश्यते रम्या पद्मिनी पद्मशोभिता॥', 'iyam ādityasaṃkāśaiḥ padmaiḥ surabhigandhibhiḥ
adūre dṛśyate ramyā padminī padmaśobhitā', null, 3014011),
('ramayana-3-14-12', 12, 'Aranya Kanda, Sarga 14, Verse 12', 'यथाख्यातमगस्त्येन मुनिना भावितात्मना।
इयं गोदावरी रम्या पुष्पितैस्तरुभिर्वृता॥', 'yathākhyātam agastyena muninā bhāvitātmanā
iyaṃ godāvarī ramyā puṣpitais tarubhir vṛtā', null, 3014012),
('ramayana-3-14-13', 13, 'Aranya Kanda, Sarga 14, Verse 13', 'हंसकारण्डवाकीर्णा चक्रवाकोपशोभिता।
नातिदूरे न चासन्ने मृगयूथनिपीडिता॥', 'haṃsakāraṇḍavākīrṇā cakravākopaśobhitā
nātidūre na cāsanne mṛgayūthanipīḍitā', null, 3014013),
('ramayana-3-14-14', 14, 'Aranya Kanda, Sarga 14, Verse 14', 'मयूरनादिता रम्याः प्रांशवो बहुकन्दराः।
दृश्यन्ते गिरयः सौम्य फुल्लैस्तरुभिरावृताः॥', 'mayūranāditā ramyāḥ prāṃśavo bahukandarāḥ
dṛśyante girayaḥ saumya phullais tarubhir āvṛtāḥ', null, 3014014),
('ramayana-3-14-15', 15, 'Aranya Kanda, Sarga 14, Verse 15', 'सौवर्णे राजतैस्ताम्रैर्देशे देशे च धातुभिः।
गवाक्षिता इवाभान्ति गजाः परमभक्तिभिः॥', 'sauvarṇe rājatais tāmrair deśe deśe ca dhātubhiḥ
gavākṣitā ivābhānti gajāḥ paramabhaktibhiḥ', null, 3014015),
('ramayana-3-14-16', 16, 'Aranya Kanda, Sarga 14, Verse 16', 'सालैस्तालैस्तमालैश्च खर्जूरैः पनसाम्रकैः।
नीवारैस्तिमिशैश्चैव पुंनागैश्चोपशोभिताः॥', 'sālais tālais tamālaiś ca kharjūraiḥ panasāmrakaiḥ
nīvārais timiśaiś caiva puṃnāgaiś copaśobhitāḥ', null, 3014016),
('ramayana-3-14-17', 17, 'Aranya Kanda, Sarga 14, Verse 17', 'चूतैरशोकैस्तिलकैश्चम्पकैः केतकैरपि।
पुष्पगुल्मलतोपेतैस्तैस्तैस्तरुभिरावृताः॥', 'cūtair aśokais tilakaiś campakaiḥ ketakair api
puṣpagulmalatopetais tais tais tarubhir āvṛtāḥ', null, 3014017),
('ramayana-3-14-18', 18, 'Aranya Kanda, Sarga 14, Verse 18', 'चन्दनैः स्यन्दनैर्नीपैः पनसैर्लकुचैरपि।
धवाश्वकर्णखदिरैः शमीकिंशुकपाटलैः॥', 'candanaiḥ syandanair nīpaiḥ panasair lakucair api
dhavāśvakarṇakhadiraiḥ śamīkiṃśukapāṭalaiḥ', null, 3014018),
('ramayana-3-14-19', 19, 'Aranya Kanda, Sarga 14, Verse 19', 'इदं पुण्यमिदं मेध्यमिदं बहुमृगद्विजम्।
इह वत्स्याम सौमित्रे सार्धमेतेन पक्षिणा॥', 'idaṃ puṇyam idaṃ medhyam idaṃ bahumṛgadvijam
iha vatsyāma saumitre sārdham etena pakṣiṇā', null, 3014019),
('ramayana-3-14-20', 20, 'Aranya Kanda, Sarga 14, Verse 20', 'एवमुक्तस्तु रामेण लक्ष्मणः परवीरहा।
अचिरेणाश्रमं भ्रातुश्चकार सुमहाबलः॥', 'evam uktas tu rāmeṇa lakṣmaṇaḥ paravīrahā
acireṇāśramaṃ bhrātuś cakāra sumahābalaḥ', null, 3014020),
('ramayana-3-14-21', 21, 'Aranya Kanda, Sarga 14, Verse 21', 'पर्णशालां सुविपुलां तत्र संघातमृत्तिकाम्।
सुस्तम्भां मस्करैर्दीर्घैः कृतवंशां सुशोभनाम्॥', 'parṇaśālāṃ suvipulāṃ tatra saṃghātamṛttikām
sustambhāṃ maskarair dīrghaiḥ kṛtavaṃśāṃ suśobhanām', null, 3014021),
('ramayana-3-14-22', 22, 'Aranya Kanda, Sarga 14, Verse 22', 'स गत्वा लक्ष्मणः श्रीमान्नदीं गोदावरीं तदा।
स्नात्वा पद्मानि चादाय सफलः पुनरागतः॥', 'sa gatvā lakṣmaṇaḥ śrīmān nadīṃ godāvarīṃ tadā
snātvā padmāni cādāya saphalaḥ punar āgataḥ', null, 3014022),
('ramayana-3-14-23', 23, 'Aranya Kanda, Sarga 14, Verse 23', 'ततः पुष्पबलिं कृत्वा शान्तिं च स यथाविधि।
दर्शयामास रामाय तदाश्रमपदं कृतम्॥', 'tataḥ puṣpabaliṃ kṛtvā śāntiṃ ca sa yathāvidhi
darśayām āsa rāmāya tad āśramapadaṃ kṛtam', null, 3014023),
('ramayana-3-14-24', 24, 'Aranya Kanda, Sarga 14, Verse 24', 'स तं दृष्ट्वा कृतं सौम्यमाश्रमं सह सीतया।
राघवः पर्णशालायां हर्षमाहारयत्परम्॥', 'sa taṃ dṛṣṭvā kṛtaṃ saumyam āśramaṃ saha sītayā
rāghavaḥ parṇaśālāyāṃ harṣam āhārayat param', null, 3014024),
('ramayana-3-14-25', 25, 'Aranya Kanda, Sarga 14, Verse 25', 'सुसंहृष्टः परिष्वज्य बाहुभ्यां लक्ष्मणं तदा।
अतिस्निग्धं च गाढं च वचनं चेदमब्रवीत्॥', 'susaṃhṛṣṭaḥ pariṣvajya bāhubhyāṃ lakṣmaṇaṃ tadā
atisnigdhaṃ ca gāḍhaṃ ca vacanaṃ cedam abravīt', null, 3014025),
('ramayana-3-14-26', 26, 'Aranya Kanda, Sarga 14, Verse 26', 'प्रीतोऽस्मि ते महत्कर्म त्वया कृतमिदं प्रभो।
प्रदेयो यन्निमित्तं ते परिष्वङ्गो मया कृतः॥', 'prīto ''smi te mahat karma tvayā kṛtam idaṃ prabho
pradeyo yannimittaṃ te pariṣvaṅgo mayā kṛtaḥ', null, 3014026),
('ramayana-3-14-27', 27, 'Aranya Kanda, Sarga 14, Verse 27', 'भावज्ञेन कृतज्ञेन धर्मज्ञेन च लक्ष्मण।
त्वया पुत्रेण धर्मात्मा न संवृत्तः पिता मम॥', 'bhāvajñena kṛtajñena dharmajñena ca lakṣmaṇa
tvayā putreṇa dharmātmā na saṃvṛttaḥ pitā mama', null, 3014027),
('ramayana-3-14-28', 28, 'Aranya Kanda, Sarga 14, Verse 28', 'एवं लक्ष्मणमुक्त्वा तु राघवो लक्ष्मिवर्धनः।
तस्मिन्देशे बहुफले न्यवसत्स सुखं वशी॥', 'evaṃ lakṣmaṇam uktvā tu rāghavo lakṣmivardhanaḥ
tasmin deśe bahuphale nyavasat sa sukhaṃ vaśī', null, 3014028),
('ramayana-3-14-29', 29, 'Aranya Kanda, Sarga 14, Verse 29', 'कं चित्कालं स धर्मात्मा सीतया लक्ष्मणेन च।
अन्वास्यमानो न्यवसत्स्वर्गलोके यथामरः॥', 'kaṃ cit kālaṃ sa dharmātmā sītayā lakṣmaṇena ca
anvāsyamāno nyavasat svargaloke yathāmaraḥ', null, 3014029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 15 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-15-1', 1, 'Aranya Kanda, Sarga 15, Verse 1', 'वसतस्तस्य तु सुखं राघवस्य महात्मनः।
शरद्व्यपाये हेमन्त ऋतुरिष्टः प्रवर्तते॥', 'vasatas tasya tu sukhaṃ rāghavasya mahātmanaḥ
śaradvyapāye hemanta ṛtur iṣṭaḥ pravartate', null, 3015001),
('ramayana-3-15-2', 2, 'Aranya Kanda, Sarga 15, Verse 2', 'स कदा चित्प्रभातायां शर्वर्यां रघुनन्दनः।
प्रययावभिषेकार्थं रम्यां गोदावरीं नदीम्॥', 'sa kadā cit prabhātāyāṃ śarvaryāṃ raghunandanaḥ
prayayāv abhiṣekārthaṃ ramyāṃ godāvarīṃ nadīm', null, 3015002),
('ramayana-3-15-3', 3, 'Aranya Kanda, Sarga 15, Verse 3', 'प्रह्वः कलशहस्तस्तं सीतया सह वीर्यवान्।
पृष्ठतोऽनुव्रजन्भ्राता सौमित्रिरिदमब्रवीत्॥', 'prahvaḥ kalaśahastas taṃ sītayā saha vīryavān
pṛṣṭhato ''nuvrajan bhrātā saumitrir idam abravīt', null, 3015003),
('ramayana-3-15-4', 4, 'Aranya Kanda, Sarga 15, Verse 4', 'अयं स कालः संप्राप्तः प्रियो यस्ते प्रियंवद।
अलंकृत इवाभाति येन संवत्सरः शुभः॥', 'ayaṃ sa kālaḥ saṃprāptaḥ priyo yas te priyaṃvada
alaṃkṛta ivābhāti yena saṃvatsaraḥ śubhaḥ', null, 3015004),
('ramayana-3-15-5', 5, 'Aranya Kanda, Sarga 15, Verse 5', 'नीहारपरुषो लोकः पृथिवी सस्यमालिनी।
जलान्यनुपभोग्यानि सुभगो हव्यवाहनः॥', 'nīhāraparuṣo lokaḥ pṛthivī sasyamālinī
jalāny anupabhogyāni subhago havyavāhanaḥ', null, 3015005),
('ramayana-3-15-6', 6, 'Aranya Kanda, Sarga 15, Verse 6', 'नवाग्रयणपूजाभिरभ्यर्च्य पितृदेवताः।
कृताग्रयणकाः काले सन्तो विगतकल्मषाः॥', 'navāgrayaṇapūjābhir abhyarcya pitṛdevatāḥ
kṛtāgrayaṇakāḥ kāle santo vigatakalmaṣāḥ', null, 3015006),
('ramayana-3-15-7', 7, 'Aranya Kanda, Sarga 15, Verse 7', 'प्राज्यकामा जनपदाः संपन्नतरगोरसाः।
विचरन्ति महीपाला यात्रार्थं विजिगीषवः॥', 'prājyakāmā janapadāḥ saṃpannataragorasāḥ
vicaranti mahīpālā yātrārthaṃ vijigīṣavaḥ', null, 3015007),
('ramayana-3-15-8', 8, 'Aranya Kanda, Sarga 15, Verse 8', 'सेवमाने दृढं सूर्ये दिशमन्तकसेविताम्।
विहीनतिलकेव स्त्री नोत्तरा दिक्प्रकाशते॥', 'sevamāne dṛḍhaṃ sūrye diśam antakasevitām
vihīnatilakeva strī nottarā dik prakāśate', null, 3015008),
('ramayana-3-15-9', 9, 'Aranya Kanda, Sarga 15, Verse 9', 'प्रकृत्या हिमकोशाढ्यो दूरसूर्यश्च साम्प्रतम्।
यथार्थनामा सुव्यक्तं हिमवान्हिमवान्गिरिः॥', 'prakṛtyā himakośāḍhyo dūrasūryaś ca sāmpratam
yathārthanāmā suvyaktaṃ himavān himavān giriḥ', null, 3015009),
('ramayana-3-15-10', 10, 'Aranya Kanda, Sarga 15, Verse 10', 'अत्यन्तसुखसंचारा मध्याह्ने स्पर्शतः सुखाः।
दिवसाः सुभगादित्याश्छायासलिलदुर्भगाः॥', 'atyantasukhasaṃcārā madhyāhne sparśataḥ sukhāḥ
divasāḥ subhagādityāś chāyāsaliladurbhagāḥ', null, 3015010),
('ramayana-3-15-11', 11, 'Aranya Kanda, Sarga 15, Verse 11', 'मृदुसूर्याः सनीहाराः पटुशीताः समारुताः।
शून्यारण्या हिमध्वस्ता दिवसा भान्ति साम्प्रतम्॥', 'mṛdusūryāḥ sanīhārāḥ paṭuśītāḥ samārutāḥ
śūnyāraṇyā himadhvastā divasā bhānti sāmpratam', null, 3015011),
('ramayana-3-15-12', 12, 'Aranya Kanda, Sarga 15, Verse 12', 'निवृत्ताकाशशयनाः पुष्यनीता हिमारुणाः।
शीता वृद्धतरायामास्त्रियामा यान्ति साम्प्रतम्॥', 'nivṛttākāśaśayanāḥ puṣyanītā himāruṇāḥ
śītā vṛddhatarāyāmās triyāmā yānti sāmpratam', null, 3015012),
('ramayana-3-15-13', 13, 'Aranya Kanda, Sarga 15, Verse 13', 'रविसंक्रान्तसौभाग्यस्तुषारारुणमण्डलः।
निःश्वासान्ध इवादर्शश्चन्द्रमा न प्रकाशते॥', 'ravisaṃkrāntasaubhāgyas tuṣārāruṇamaṇḍalaḥ
niḥśvāsāndha ivādarśaś candramā na prakāśate', null, 3015013),
('ramayana-3-15-14', 14, 'Aranya Kanda, Sarga 15, Verse 14', 'ज्योत्स्ना तुषारमलिना पौर्णमास्यां न राजते।
सीतेव चातपश्यामा लक्ष्यते न तु शोभते॥', 'jyotsnā tuṣāramalinā paurṇamāsyāṃ na rājate
sīteva cātapaśyāmā lakṣyate na tu śobhate', null, 3015014),
('ramayana-3-15-15', 15, 'Aranya Kanda, Sarga 15, Verse 15', 'प्रकृत्या शीतलस्पर्शो हिमविद्धश्च साम्प्रतम्।
प्रवाति पश्चिमो वायुः काले द्विगुणशीतलः॥', 'prakṛtyā śītalasparśo himaviddhaś ca sāmpratam
pravāti paścimo vāyuḥ kāle dviguṇaśītalaḥ', null, 3015015),
('ramayana-3-15-16', 16, 'Aranya Kanda, Sarga 15, Verse 16', 'बाष्पच्छन्नान्यरण्यानि यवगोधूमवन्ति च।
शोभन्तेऽभ्युदिते सूर्ये नदद्भिः क्रौञ्चसारसैः॥', 'bāṣpacchannāny araṇyāni yavagodhūmavanti ca
śobhante ''bhyudite sūrye nadadbhiḥ krauñcasārasaiḥ', null, 3015016),
('ramayana-3-15-17', 17, 'Aranya Kanda, Sarga 15, Verse 17', 'खर्जूरपुष्पाकृतिभिः शिरोभिः पूर्णतण्डुलैः।
शोभन्ते किं चिदालम्बाः शालयः कनकप्रभाः॥', 'kharjūrapuṣpākṛtibhiḥ śirobhiḥ pūrṇataṇḍulaiḥ
śobhante kiṃ cidālambāḥ śālayaḥ kanakaprabhāḥ', null, 3015017),
('ramayana-3-15-18', 18, 'Aranya Kanda, Sarga 15, Verse 18', 'मयूखैरुपसर्पद्भिर्हिमनीहारसंवृतैः।
दूरमभ्युदितः सूर्यः शशाङ्क इव लक्ष्यते॥', 'mayūkhair upasarpadbhir himanīhārasaṃvṛtaiḥ
dūram abhyuditaḥ sūryaḥ śaśāṅka iva lakṣyate', null, 3015018),
('ramayana-3-15-19', 19, 'Aranya Kanda, Sarga 15, Verse 19', 'अग्राह्यवीर्यः पूर्वाह्णे मध्याह्ने स्पर्शतः सुखः।
संरक्तः किं चिदापाण्डुरातपः शोभते क्षितौ॥', 'agrāhyavīryaḥ pūrvāhṇe madhyāhne sparśataḥ sukhaḥ
saṃraktaḥ kiṃ cid āpāṇḍur ātapaḥ śobhate kṣitau', null, 3015019),
('ramayana-3-15-20', 20, 'Aranya Kanda, Sarga 15, Verse 20', 'अवश्यायनिपातेन किं चित्प्रक्लिन्नशाद्वला।
वनानां शोभते भूमिर्निविष्टतरुणातपा॥', 'avaśyāyanipātena kiṃ cit praklinnaśādvalā
vanānāṃ śobhate bhūmir niviṣṭataruṇātapā', null, 3015020),
('ramayana-3-15-21', 21, 'Aranya Kanda, Sarga 15, Verse 21', 'अवश्यायतमोनद्धा नीहारतमसावृताः।
प्रसुप्ता इव लक्ष्यन्ते विपुष्पा वनराजयः॥', 'avaśyāyatamonaddhā nīhāratamasāvṛtāḥ
prasuptā iva lakṣyante vipuṣpā vanarājayaḥ', null, 3015021),
('ramayana-3-15-22', 22, 'Aranya Kanda, Sarga 15, Verse 22', 'बाष्पसंछन्नसलिला रुतविज्ञेयसारसाः।
हिमार्द्रवालुकैस्तीरैः सरितो भान्ति साम्प्रतम्॥', 'bāṣpasaṃchannasalilā rutavijñeyasārasāḥ
himārdravālukais tīraiḥ sarito bhānti sāmpratam', null, 3015022),
('ramayana-3-15-23', 23, 'Aranya Kanda, Sarga 15, Verse 23', 'तुषारपतनाच्चैव मृदुत्वाद्भास्करस्य च।
शैत्यादगाग्रस्थमपि प्रायेण रसवज्जलम्॥', 'tuṣārapatanāc caiva mṛdutvād bhāskarasya ca
śaityād agāgrastham api prāyeṇa rasavaj jalam', null, 3015023),
('ramayana-3-15-24', 24, 'Aranya Kanda, Sarga 15, Verse 24', 'जराजर्जरितैः पर्णैः शीर्णकेसरकर्णिकैः।
नालशेषा हिमध्वस्ता न भान्ति कमलाकराः॥', 'jarājarjaritaiḥ parṇaiḥ śīrṇakesarakarṇikaiḥ
nālaśeṣā himadhvastā na bhānti kamalākarāḥ', null, 3015024),
('ramayana-3-15-25', 25, 'Aranya Kanda, Sarga 15, Verse 25', 'अस्मिंस्तु पुरुषव्याघ्र काले दुःखसमन्वितः।
तपश्चरति धर्मात्मा त्वद्भक्त्या भरतः पुरे॥', 'asmiṃs tu puruṣavyāghra kāle duḥkhasamanvitaḥ
tapaś carati dharmātmā tvadbhaktyā bharataḥ pure', null, 3015025),
('ramayana-3-15-26', 26, 'Aranya Kanda, Sarga 15, Verse 26', 'त्यक्त्वा राज्यं च मानं च भोगांश्च विविधान्बहून्।
तपस्वी नियताहारः शेते शीते महीतले॥', 'tyaktvā rājyaṃ ca mānaṃ ca bhogāṃś ca vividhān bahūn
tapasvī niyatāhāraḥ śete śīte mahītale', null, 3015026),
('ramayana-3-15-27', 27, 'Aranya Kanda, Sarga 15, Verse 27', 'सोऽपि वेलामिमां नूनमभिषेकार्थमुद्यतः।
वृतः प्रकृतिभिर्नित्यं प्रयाति सरयूं नदीम्॥', 'so ''pi velām imāṃ nūnam abhiṣekārtham udyataḥ
vṛtaḥ prakṛtibhir nityaṃ prayāti sarayūṃ nadīm', null, 3015027),
('ramayana-3-15-28', 28, 'Aranya Kanda, Sarga 15, Verse 28', 'अत्यन्तसुखसंवृद्धः सुकुमारो हिमार्दितः।
कथं त्वपररात्रेषु सरयूमवगाहते॥', 'atyantasukhasaṃvṛddhaḥ sukumāro himārditaḥ
kathaṃ tv apararātreṣu sarayūm avagāhate', null, 3015028),
('ramayana-3-15-29', 29, 'Aranya Kanda, Sarga 15, Verse 29', 'पद्मपत्रेक्षणः श्यामः श्रीमान्निरुदरो महान्।
धर्मज्ञः सत्यवादी च ह्रीनिषेधो जितेन्द्रियः॥', 'padmapatrekṣaṇaḥ śyāmaḥ śrīmān nirudaro mahān
dharmajñaḥ satyavādī ca hrīniṣedho jitendriyaḥ', null, 3015029),
('ramayana-3-15-30', 30, 'Aranya Kanda, Sarga 15, Verse 30', 'प्रियाभिभाषी मधुरो दीर्घबाहुररिंदमः।
संत्यज्य विविधान्सौख्यानार्यं सर्वात्मनाश्रितः॥', 'priyābhibhāṣī madhuro dīrghabāhur ariṃdamaḥ
saṃtyajya vividhān saukhyān āryaṃ sarvātmanāśritaḥ', null, 3015030),
('ramayana-3-15-31', 31, 'Aranya Kanda, Sarga 15, Verse 31', 'जितः स्वर्गस्तव भ्रात्रा भरतेन महात्मना।
वनस्थमपि तापस्ये यस्त्वामनुविधीयते॥', 'jitaḥ svargas tava bhrātrā bharatena mahātmanā
vanastham api tāpasye yas tvām anuvidhīyate', null, 3015031),
('ramayana-3-15-32', 32, 'Aranya Kanda, Sarga 15, Verse 32', 'न पित्र्यमनुवर्न्तन्ते मातृकं द्विपदा इति।
ख्यातो लोकप्रवादोऽयं भरतेनान्यथाकृतः॥', 'na pitryam anuvarntante mātṛkaṃ dvipadā iti
khyāto lokapravādo ''yaṃ bharatenānyathākṛtaḥ', null, 3015032),
('ramayana-3-15-33', 33, 'Aranya Kanda, Sarga 15, Verse 33', 'भर्ता दशरथो यस्याः साधुश्च भरतः सुतः।
कथं नु साम्बा कैकेयी तादृशी क्रूरदर्शिनी॥', 'bhartā daśaratho yasyāḥ sādhuś ca bharataḥ sutaḥ
kathaṃ nu sāmbā kaikeyī tādṛśī krūradarśinī', null, 3015033),
('ramayana-3-15-34', 34, 'Aranya Kanda, Sarga 15, Verse 34', 'इत्येवं लक्ष्मणे वाक्यं स्नेहाद्ब्रुवति धार्मिके।
परिवादं जनन्यास्तमसहन्राघवोऽब्रवीत्॥', 'ity evaṃ lakṣmaṇe vākyaṃ snehād bruvati dhārmike
parivādaṃ jananyās tam asahan rāghavo ''bravīt', null, 3015034),
('ramayana-3-15-35', 35, 'Aranya Kanda, Sarga 15, Verse 35', 'न तेऽम्बा मध्यमा तात गर्हितव्या कथं चन।
तामेवेक्ष्वाकुनाथस्य भरतस्य कथां कुरु॥', 'na te ''mbā madhyamā tāta garhitavyā kathaṃ cana
tām evekṣvākunāthasya bharatasya kathāṃ kuru', null, 3015035),
('ramayana-3-15-36', 36, 'Aranya Kanda, Sarga 15, Verse 36', 'निश्चितापि हि मे बुद्धिर्वनवासे दृढव्रता।
भरतस्नेहसंतप्ता बालिशीक्रियते पुनः॥', 'niścitāpi hi me buddhir vanavāse dṛḍhavratā
bharatasnehasaṃtaptā bāliśīkriyate punaḥ', null, 3015036),
('ramayana-3-15-37', 37, 'Aranya Kanda, Sarga 15, Verse 37', 'इत्येवं विलपंस्तत्र प्राप्य गोदावरीं नदीम्।
चक्रेऽभिषेकं काकुत्स्थः सानुजः सह सीतया॥', 'ity evaṃ vilapaṃs tatra prāpya godāvarīṃ nadīm
cakre ''bhiṣekaṃ kākutsthaḥ sānujaḥ saha sītayā', null, 3015037),
('ramayana-3-15-38', 38, 'Aranya Kanda, Sarga 15, Verse 38', 'तर्पयित्वाथ सलिलैस्ते पितॄन्दैवतानि च।
स्तुवन्ति स्मोदितं सूर्यं देवताश्च समाहिताः॥', 'tarpayitvātha salilais te pitṝn daivatāni ca
stuvanti smoditaṃ sūryaṃ devatāś ca samāhitāḥ', null, 3015038),
('ramayana-3-15-39', 39, 'Aranya Kanda, Sarga 15, Verse 39', 'कृताभिषेकः स रराज रामः सीताद्वितीयः सह लक्ष्मणेन।
कृताभिषेकस्त्वगराजपुत्र्या रुद्रः सनन्दिर्भगवानिवेशः॥', 'kṛtābhiṣekaḥ sa rarāja rāmaḥ sītādvitīyaḥ saha lakṣmaṇena
kṛtābhiṣekas tv agarājaputryā rudraḥ sanandir bhagavān iveśaḥ', null, 3015039)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 16 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-16-1', 1, 'Aranya Kanda, Sarga 16, Verse 1', 'कृताभिषेको रामस्तु सीता सौमित्रिरेव च।
तस्माद्गोदावरीतीरात्ततो जग्मुः स्वमाश्रमम्॥', 'kṛtābhiṣeko rāmas tu sītā saumitrir eva ca
tasmād godāvarītīrāt tato jagmuḥ svam āśramam', null, 3016001),
('ramayana-3-16-2', 2, 'Aranya Kanda, Sarga 16, Verse 2', 'आश्रमं तमुपागम्य राघवः सहलक्ष्मणः।
कृत्वा पौर्वाह्णिकं कर्म पर्णशालामुपागमत्॥', 'āśramaṃ tam upāgamya rāghavaḥ sahalakṣmaṇaḥ
kṛtvā paurvāhṇikaṃ karma parṇaśālām upāgamat', null, 3016002),
('ramayana-3-16-3', 3, 'Aranya Kanda, Sarga 16, Verse 3', 'स रामः पर्णशालायामासीनः सह सीतया।
विरराज महाबाहुश्चित्रया चन्द्रमा इव।
लक्ष्मणेन सह भ्रात्रा चकार विविधाः कथाः॥', 'sa rāmaḥ parṇaśālāyām āsīnaḥ saha sītayā
virarāja mahābāhuś citrayā candramā iva
lakṣmaṇena saha bhrātrā cakāra vividhāḥ kathāḥ', null, 3016003),
('ramayana-3-16-4', 4, 'Aranya Kanda, Sarga 16, Verse 4', 'तदासीनस्य रामस्य कथासंसक्तचेतसः।
तं देशं राक्षसी का चिदाजगाम यदृच्छया॥', 'tadāsīnasya rāmasya kathāsaṃsaktacetasaḥ
taṃ deśaṃ rākṣasī kā cid ājagāma yadṛcchayā', null, 3016004),
('ramayana-3-16-5', 5, 'Aranya Kanda, Sarga 16, Verse 5', 'सा तु शूर्पणखा नाम दशग्रीवस्य रक्षसः।
भगिनी राममासाद्य ददर्श त्रिदशोपमम्॥', 'sā tu śūrpaṇakhā nāma daśagrīvasya rakṣasaḥ
bhaginī rāmam āsādya dadarśa tridaśopamam', null, 3016005),
('ramayana-3-16-6', 6, 'Aranya Kanda, Sarga 16, Verse 6', 'सिंहोरस्कं महाबाहुं पद्मपत्रनिभेक्षणम्।
सुकुमारं महासत्त्वं पार्थिवव्यञ्जनान्वितम्॥', 'siṃhoraskaṃ mahābāhuṃ padmapatranibhekṣaṇam
sukumāraṃ mahāsattvaṃ pārthivavyañjanānvitam', null, 3016006),
('ramayana-3-16-7', 7, 'Aranya Kanda, Sarga 16, Verse 7', 'राममिन्दीवरश्यामं कन्दर्पसदृशप्रभम्।
बभूवेन्द्रोपमं दृष्ट्वा राक्षसी काममोहिता॥', 'rāmam indīvaraśyāmaṃ kandarpasadṛśaprabham
babhūvendropamaṃ dṛṣṭvā rākṣasī kāmamohitā', null, 3016007),
('ramayana-3-16-8', 8, 'Aranya Kanda, Sarga 16, Verse 8', 'सुमुखं दुर्मुखी रामं वृत्तमध्यं महोदरी।
विशालाक्षं विरूपाक्षी सुकेशं ताम्रमूर्धजा॥', 'sumukhaṃ durmukhī rāmaṃ vṛttamadhyaṃ mahodarī
viśālākṣaṃ virūpākṣī sukeśaṃ tāmramūrdhajā', null, 3016008),
('ramayana-3-16-9', 9, 'Aranya Kanda, Sarga 16, Verse 9', 'प्रियरूपं विरूपा सा सुस्वरं भैरवस्वना।
तरुणं दारुणा वृद्धा दक्षिणं वामभाषिणी॥', 'priyarūpaṃ virūpā sā susvaraṃ bhairavasvanā
taruṇaṃ dāruṇā vṛddhā dakṣiṇaṃ vāmabhāṣiṇī', null, 3016009),
('ramayana-3-16-10', 10, 'Aranya Kanda, Sarga 16, Verse 10', 'न्यायवृत्तं सुदुर्वृत्ता प्रियमप्रियदर्शना।
शरीरजसमाविष्टा राक्षसी राममब्रवीत्॥', 'nyāyavṛttaṃ sudurvṛttā priyam apriyadarśanā
śarīrajasamāviṣṭā rākṣasī rāmam abravīt', null, 3016010),
('ramayana-3-16-11', 11, 'Aranya Kanda, Sarga 16, Verse 11', 'जटी तापसरूपेण सभार्यः शरचापधृक्।
आगतस्त्वमिमं देशं कथं राक्षससेवितम्॥', 'jaṭī tāpasarūpeṇa sabhāryaḥ śaracāpadhṛk
āgatas tvam imaṃ deśaṃ kathaṃ rākṣasasevitam', null, 3016011),
('ramayana-3-16-12', 12, 'Aranya Kanda, Sarga 16, Verse 12', 'एवमुक्तस्तु राक्षस्या शूर्पणख्या परंतपः।
ऋजुबुद्धितया सर्वमाख्यातुमुपचक्रमे॥', 'evam uktas tu rākṣasyā śūrpaṇakhyā paraṃtapaḥ
ṛjubuddhitayā sarvam ākhyātum upacakrame', null, 3016012),
('ramayana-3-16-13', 13, 'Aranya Kanda, Sarga 16, Verse 13', 'आसीद्दशरथो नाम राजा त्रिदशविक्रमः।
तस्याहमग्रजः पुत्रो रामो नाम जनैः श्रुतः॥', 'āsīd daśaratho nāma rājā tridaśavikramaḥ
tasyāham agrajaḥ putro rāmo nāma janaiḥ śrutaḥ', null, 3016013),
('ramayana-3-16-14', 14, 'Aranya Kanda, Sarga 16, Verse 14', 'भ्रातायं लक्ष्मणो नाम यवीयान्मामनुव्रतः।
इयं भार्या च वैदेही मम सीतेति विश्रुता॥', 'bhrātāyaṃ lakṣmaṇo nāma yavīyān mām anuvrataḥ
iyaṃ bhāryā ca vaidehī mama sīteti viśrutā', null, 3016014),
('ramayana-3-16-15', 15, 'Aranya Kanda, Sarga 16, Verse 15', 'नियोगात्तु नरेन्द्रस्य पितुर्मातुश्च यन्त्रितः।
धर्मार्थं धर्मकाङ्क्षी च वनं वस्तुमिहागतः॥', 'niyogāt tu narendrasya pitur mātuś ca yantritaḥ
dharmārthaṃ dharmakāṅkṣī ca vanaṃ vastum ihāgataḥ', null, 3016015),
('ramayana-3-16-16', 16, 'Aranya Kanda, Sarga 16, Verse 16', 'त्वां तु वेदितुमिच्छामि कथ्यतां कासि कस्य वा।
इह वा किंनिमित्तं त्वमागता ब्रूहि तत्त्वतः॥', 'tvāṃ tu veditum icchāmi kathyatāṃ kāsi kasya vā
iha vā kiṃnimittaṃ tvam āgatā brūhi tattvataḥ', null, 3016016),
('ramayana-3-16-17', 17, 'Aranya Kanda, Sarga 16, Verse 17', 'साब्रवीद्वचनं श्रुत्वा राक्षसी मदनार्दिता।
श्रूयतां राम वक्ष्यामि तत्त्वार्थं वचनं मम॥', 'sābravīd vacanaṃ śrutvā rākṣasī madanārditā
śrūyatāṃ rāma vakṣyāmi tattvārthaṃ vacanaṃ mama', null, 3016017),
('ramayana-3-16-18', 18, 'Aranya Kanda, Sarga 16, Verse 18', 'अहं शूर्पणखा नाम राक्षसी कामरूपिणी।
अरण्यं विचरामीदमेका सर्वभयंकरा॥', 'ahaṃ śūrpaṇakhā nāma rākṣasī kāmarūpiṇī
araṇyaṃ vicarāmīdam ekā sarvabhayaṃkarā', null, 3016018),
('ramayana-3-16-19', 19, 'Aranya Kanda, Sarga 16, Verse 19', 'रावणो नाम मे भ्राता राक्षसो राक्षसेश्वरः।
प्रवृद्धनिद्रश्च सदा कुम्भकर्णो महाबलः॥', 'rāvaṇo nāma me bhrātā rākṣaso rākṣaseśvaraḥ
pravṛddhanidraś ca sadā kumbhakarṇo mahābalaḥ', null, 3016019),
('ramayana-3-16-20', 20, 'Aranya Kanda, Sarga 16, Verse 20', 'विभीषणस्तु धर्मात्मा न तु राक्षसचेष्टितः।
प्रख्यातवीर्यौ च रणे भ्रातरौ खरदूषणौ॥', 'vibhīṣaṇas tu dharmātmā na tu rākṣasaceṣṭitaḥ
prakhyātavīryau ca raṇe bhrātarau kharadūṣaṇau', null, 3016020),
('ramayana-3-16-21', 21, 'Aranya Kanda, Sarga 16, Verse 21', 'तानहं समतिक्रान्ता राम त्वापूर्वदर्शनात्।
समुपेतास्मि भावेन भर्तारं पुरुषोत्तमम्।
चिराय भव भर्ता मे सीतया किं करिष्यसि॥', 'tān ahaṃ samatikrāntā rāma tvāpūrvadarśanāt
samupetāsmi bhāvena bhartāraṃ puruṣottamam
cirāya bhava bhartā me sītayā kiṃ kariṣyasi', null, 3016021),
('ramayana-3-16-22', 22, 'Aranya Kanda, Sarga 16, Verse 22', 'विकृता च विरूपा च न सेयं सदृशी तव।
अहमेवानुरूपा ते भार्यारूपेण पश्य माम्॥', 'vikṛtā ca virūpā ca na seyaṃ sadṛśī tava
aham evānurūpā te bhāryārūpeṇa paśya mām', null, 3016022),
('ramayana-3-16-23', 23, 'Aranya Kanda, Sarga 16, Verse 23', 'इमां विरूपामसतीं करालां निर्णतोदरीम्।
अनेन सह ते भ्रात्रा भक्षयिष्यामि मानुषीम्॥', 'imāṃ virūpām asatīṃ karālāṃ nirṇatodarīm
anena saha te bhrātrā bhakṣayiṣyāmi mānuṣīm', null, 3016023),
('ramayana-3-16-24', 24, 'Aranya Kanda, Sarga 16, Verse 24', 'ततः पर्वतशृङ्गाणि वनानि विविधानि च।
पश्यन्सह मया कान्त दण्डकान्विचरिष्यसि॥', 'tataḥ parvataśṛṅgāṇi vanāni vividhāni ca
paśyan saha mayā kānta daṇḍakān vicariṣyasi', null, 3016024),
('ramayana-3-16-25', 25, 'Aranya Kanda, Sarga 16, Verse 25', 'इत्येवमुक्तः काकुत्स्थः प्रहस्य मदिरेक्षणाम्।
इदं वचनमारेभे वक्तुं वाक्यविशारदः॥', 'ity evam uktaḥ kākutsthaḥ prahasya madirekṣaṇām
idaṃ vacanam ārebhe vaktuṃ vākyaviśāradaḥ', null, 3016025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 17 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-17-1', 1, 'Aranya Kanda, Sarga 17, Verse 1', 'तां तु शूर्पणखां रामः कामपाशावपाशिताम्।
स्वेच्छया श्लक्ष्णया वाचा स्मितपूर्वमथाब्रवीत्॥', 'tāṃ tu śūrpaṇakhāṃ rāmaḥ kāmapāśāvapāśitām
svecchayā ślakṣṇayā vācā smitapūrvam athābravīt', null, 3017001),
('ramayana-3-17-2', 2, 'Aranya Kanda, Sarga 17, Verse 2', 'कृतदारोऽस्मि भवति भार्येयं दयिता मम।
त्वद्विधानां तु नारीणां सुदुःखा ससपत्नता॥', 'kṛtadāro ''smi bhavati bhāryeyaṃ dayitā mama
tvadvidhānāṃ tu nārīṇāṃ suduḥkhā sasapatnatā', null, 3017002),
('ramayana-3-17-3', 3, 'Aranya Kanda, Sarga 17, Verse 3', 'अनुजस्त्वेष मे भ्राता शीलवान्प्रियदर्शनः।
श्रीमानकृतदारश्च लक्ष्मणो नाम वीर्यवान्॥', 'anujas tv eṣa me bhrātā śīlavān priyadarśanaḥ
śrīmān akṛtadāraś ca lakṣmaṇo nāma vīryavān', null, 3017003),
('ramayana-3-17-4', 4, 'Aranya Kanda, Sarga 17, Verse 4', 'अपूर्वी भार्यया चार्थी तरुणः प्रियदर्शनः।
अनुरूपश्च ते भर्ता रूपस्यास्य भविष्यति॥', 'apūrvī bhāryayā cārthī taruṇaḥ priyadarśanaḥ
anurūpaś ca te bhartā rūpasyāsya bhaviṣyati', null, 3017004),
('ramayana-3-17-5', 5, 'Aranya Kanda, Sarga 17, Verse 5', 'एनं भज विशालाक्षि भर्तारं भ्रातरं मम।
असपत्ना वरारोहे मेरुमर्कप्रभा यथा॥', 'enaṃ bhaja viśālākṣi bhartāraṃ bhrātaraṃ mama
asapatnā varārohe merum arkaprabhā yathā', null, 3017005),
('ramayana-3-17-6', 6, 'Aranya Kanda, Sarga 17, Verse 6', 'इति रामेण सा प्रोक्ता राक्षसी काममोहिता।
विसृज्य रामं सहसा ततो लक्ष्मणमब्रवीत्॥', 'iti rāmeṇa sā proktā rākṣasī kāmamohitā
visṛjya rāmaṃ sahasā tato lakṣmaṇam abravīt', null, 3017006),
('ramayana-3-17-7', 7, 'Aranya Kanda, Sarga 17, Verse 7', 'अस्य रूपस्य ते युक्ता भार्याहं वरवर्णिनी।
मया सह सुखं सर्वान्दण्डकान्विचरिष्यसि॥', 'asya rūpasya te yuktā bhāryāhaṃ varavarṇinī
mayā saha sukhaṃ sarvān daṇḍakān vicariṣyasi', null, 3017007),
('ramayana-3-17-8', 8, 'Aranya Kanda, Sarga 17, Verse 8', 'एवमुक्तस्तु सौमित्री राक्षस्या वाक्यकोविदः।
ततः शूर्पणखीं स्मित्वा लक्ष्मणो युक्तमब्रवीत्॥', 'evam uktas tu saumitrī rākṣasyā vākyakovidaḥ
tataḥ śūrpaṇakhīṃ smitvā lakṣmaṇo yuktam abravīt', null, 3017008),
('ramayana-3-17-9', 9, 'Aranya Kanda, Sarga 17, Verse 9', 'कथं दासस्य मे दासी भार्या भवितुमिच्छसि।
सोऽहमार्येण परवान्भ्रात्रा कमलवर्णिनी॥', 'kathaṃ dāsasya me dāsī bhāryā bhavitum icchasi
so ''ham āryeṇa paravān bhrātrā kamalavarṇinī', null, 3017009),
('ramayana-3-17-10', 10, 'Aranya Kanda, Sarga 17, Verse 10', 'समृद्धार्थस्य सिद्धार्था मुदितामलवर्णिनी।
आर्यस्य त्वं विशालाक्षि भार्या भव यवीयसी॥', 'samṛddhārthasya siddhārthā muditāmalavarṇinī
āryasya tvaṃ viśālākṣi bhāryā bhava yavīyasī', null, 3017010),
('ramayana-3-17-11', 11, 'Aranya Kanda, Sarga 17, Verse 11', 'एतां विरूपामसतीं करालां निर्णतोदरीम्।
भार्यां वृद्धां परित्यज्य त्वामेवैष भजिष्यति॥', 'etāṃ virūpām asatīṃ karālāṃ nirṇatodarīm
bhāryāṃ vṛddhāṃ parityajya tvām evaiṣa bhajiṣyati', null, 3017011),
('ramayana-3-17-12', 12, 'Aranya Kanda, Sarga 17, Verse 12', 'को हि रूपमिदं श्रेष्ठं संत्यज्य वरवर्णिनि।
मानुषेषु वरारोहे कुर्याद्भावं विचक्षणः॥', 'ko hi rūpam idaṃ śreṣṭhaṃ saṃtyajya varavarṇini
mānuṣeṣu varārohe kuryād bhāvaṃ vicakṣaṇaḥ', null, 3017012),
('ramayana-3-17-13', 13, 'Aranya Kanda, Sarga 17, Verse 13', 'इति सा लक्ष्मणेनोक्ता कराला निर्णतोदरी।
मन्यते तद्वचः सत्यं परिहासाविचक्षणा॥', 'iti sā lakṣmaṇenoktā karālā nirṇatodarī
manyate tad vacaḥ satyaṃ parihāsāvicakṣaṇā', null, 3017013),
('ramayana-3-17-14', 14, 'Aranya Kanda, Sarga 17, Verse 14', 'सा रामं पर्णशालायामुपविष्टं परंतपम्।
सीतया सह दुर्धर्षमब्रवीत्काममोहिता॥', 'sā rāmaṃ parṇaśālāyām upaviṣṭaṃ paraṃtapam
sītayā saha durdharṣam abravīt kāmamohitā', null, 3017014),
('ramayana-3-17-15', 15, 'Aranya Kanda, Sarga 17, Verse 15', 'इमां विरूपामसतीं करालां निर्णतोदरीम्।
वृद्धां भार्यामवष्टभ्य न मां त्वं बहु मन्यसे॥', 'imāṃ virūpām asatīṃ karālāṃ nirṇatodarīm
vṛddhāṃ bhāryām avaṣṭabhya na māṃ tvaṃ bahu manyase', null, 3017015),
('ramayana-3-17-16', 16, 'Aranya Kanda, Sarga 17, Verse 16', 'अद्येमां भक्षयिष्यामि पश्यतस्तव मानुषीम्।
त्वया सह चरिष्यामि निःसपत्ना यथासुखम्॥', 'adyemāṃ bhakṣayiṣyāmi paśyatas tava mānuṣīm
tvayā saha cariṣyāmi niḥsapatnā yathāsukham', null, 3017016),
('ramayana-3-17-17', 17, 'Aranya Kanda, Sarga 17, Verse 17', 'इत्युक्त्वा मृगशावाक्षीमलातसदृशेक्षणा।
अभ्यधावत्सुसंक्रुद्धा महोल्का रोहिणीमिव॥', 'ity uktvā mṛgaśāvākṣīm alātasadṛśekṣaṇā
abhyadhāvat susaṃkruddhā maholkā rohiṇīm iva', null, 3017017),
('ramayana-3-17-18', 18, 'Aranya Kanda, Sarga 17, Verse 18', 'तां मृत्युपाशप्रतिमामापतन्तीं महाबलः।
निगृह्य रामः कुपितस्ततो लक्ष्मणमब्रवीत्॥', 'tāṃ mṛtyupāśapratimām āpatantīṃ mahābalaḥ
nigṛhya rāmaḥ kupitas tato lakṣmaṇam abravīt', null, 3017018),
('ramayana-3-17-19', 19, 'Aranya Kanda, Sarga 17, Verse 19', 'क्रूरैरनार्यैः सौमित्रे परिहासः कथं चन।
न कार्यः पश्य वैदेहीं कथं चित्सौम्य जीवतीम्॥', 'krūrair anāryaiḥ saumitre parihāsaḥ kathaṃ cana
na kāryaḥ paśya vaidehīṃ kathaṃ cit saumya jīvatīm', null, 3017019),
('ramayana-3-17-20', 20, 'Aranya Kanda, Sarga 17, Verse 20', 'इमां विरूपामसतीमतिमत्तां महोदरीम्।
राक्षसीं पुरुषव्याघ्र विरूपयितुमर्हसि॥', 'imāṃ virūpām asatīm atimattāṃ mahodarīm
rākṣasīṃ puruṣavyāghra virūpayitum arhasi', null, 3017020),
('ramayana-3-17-21', 21, 'Aranya Kanda, Sarga 17, Verse 21', 'इत्युक्तो लक्ष्मणस्तस्याः क्रुद्धो रामस्य पश्यतः।
उद्धृत्य खड्गं चिच्छेद कर्णनासं महाबलः॥', 'ity ukto lakṣmaṇas tasyāḥ kruddho rāmasya paśyataḥ
uddhṛtya khaḍgaṃ ciccheda karṇanāsaṃ mahābalaḥ', null, 3017021),
('ramayana-3-17-22', 22, 'Aranya Kanda, Sarga 17, Verse 22', 'निकृत्तकर्णनासा तु विस्वरं सा विनद्य च।
यथागतं प्रदुद्राव घोरा शूर्पणखा वनम्॥', 'nikṛttakarṇanāsā tu visvaraṃ sā vinadya ca
yathāgataṃ pradudrāva ghorā śūrpaṇakhā vanam', null, 3017022),
('ramayana-3-17-23', 23, 'Aranya Kanda, Sarga 17, Verse 23', 'सा विरूपा महाघोरा राक्षसी शोणितोक्षिता।
ननाद विविधान्नादान्यथा प्रावृषि तोयदः॥', 'sā virūpā mahāghorā rākṣasī śoṇitokṣitā
nanāda vividhān nādān yathā prāvṛṣi toyadaḥ', null, 3017023),
('ramayana-3-17-24', 24, 'Aranya Kanda, Sarga 17, Verse 24', 'सा विक्षरन्ती रुधिरं बहुधा घोरदर्शना।
प्रगृह्य बाहू गर्जन्ती प्रविवेश महावनम्॥', 'sā vikṣarantī rudhiraṃ bahudhā ghoradarśanā
pragṛhya bāhū garjantī praviveśa mahāvanam', null, 3017024),
('ramayana-3-17-25', 25, 'Aranya Kanda, Sarga 17, Verse 25', 'ततस्तु सा राक्षससंघसंवृतं खरं जनस्थानगतं विरूपिता।
उपेत्य तं भ्रातरमुग्रतेजसं पपात भूमौ गगनाद्यथाशनिः॥', 'tatas tu sā rākṣasasaṃghasaṃvṛtaṃ kharaṃ janasthānagataṃ virūpitā
upetya taṃ bhrātaram ugratejasaṃ papāta bhūmau gaganād yathāśaniḥ', null, 3017025),
('ramayana-3-17-26', 26, 'Aranya Kanda, Sarga 17, Verse 26', 'ततः सभार्यं भयमोहमूर्छिता सलक्ष्मणं राघवमागतं वनम्।
विरूपणं चात्मनि शोणितोक्षिता शशंस सर्वं भगिनी खरस्य सा॥', 'tataḥ sabhāryaṃ bhayamohamūrchitā salakṣmaṇaṃ rāghavam āgataṃ vanam
virūpaṇaṃ cātmani śoṇitokṣitā śaśaṃsa sarvaṃ bhaginī kharasya sā', null, 3017026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 18 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-18-1', 1, 'Aranya Kanda, Sarga 18, Verse 1', 'तां तथा पतितां दृष्ट्वा विरूपां शोणितोक्षिताम्।
भगिनीं क्रोधसंतप्तः खरः पप्रच्छ राक्षसः॥', 'tāṃ tathā patitāṃ dṛṣṭvā virūpāṃ śoṇitokṣitām
bhaginīṃ krodhasaṃtaptaḥ kharaḥ papraccha rākṣasaḥ', null, 3018001),
('ramayana-3-18-2', 2, 'Aranya Kanda, Sarga 18, Verse 2', 'बलविक्रमसंपन्ना कामगा कामरूपिणी।
इमामवस्थां नीता त्वं केनान्तकसमा गता॥', 'balavikramasaṃpannā kāmagā kāmarūpiṇī
imām avasthāṃ nītā tvaṃ kenāntakasamā gatā', null, 3018002),
('ramayana-3-18-3', 3, 'Aranya Kanda, Sarga 18, Verse 3', 'देवगन्धर्वभूतानामृषीणां च महात्मनाम्।
कोऽयमेवं महावीर्यस्त्वां विरूपां चकार ह॥', 'devagandharvabhūtānām ṛṣīṇāṃ ca mahātmanām
ko ''yam evaṃ mahāvīryas tvāṃ virūpāṃ cakāra ha', null, 3018003),
('ramayana-3-18-4', 4, 'Aranya Kanda, Sarga 18, Verse 4', 'न हि पश्याम्यहं लोके यः कुर्यान्मम विप्रियम्।
अन्तरेन सहस्राक्षं महेन्द्रं पाकशासनम्॥', 'na hi paśyāmy ahaṃ loke yaḥ kuryān mama vipriyam
antarena sahasrākṣaṃ mahendraṃ pākaśāsanam', null, 3018004),
('ramayana-3-18-5', 5, 'Aranya Kanda, Sarga 18, Verse 5', 'अद्याहं मार्गणैः प्राणानादास्ये जीवितान्तकैः।
सलिले क्षीरमासक्तं निष्पिबन्निव सारसः॥', 'adyāhaṃ mārgaṇaiḥ prāṇān ādāsye jīvitāntakaiḥ
salile kṣīram āsaktaṃ niṣpibann iva sārasaḥ', null, 3018005),
('ramayana-3-18-6', 6, 'Aranya Kanda, Sarga 18, Verse 6', 'निहतस्य मया संख्ये शरसंकृत्तमर्मणः।
सफेनं रुधिरं रक्तं मेदिनी कस्य पास्यति॥', 'nihatasya mayā saṃkhye śarasaṃkṛttamarmaṇaḥ
saphenaṃ rudhiraṃ raktaṃ medinī kasya pāsyati', null, 3018006),
('ramayana-3-18-7', 7, 'Aranya Kanda, Sarga 18, Verse 7', 'कस्य पत्ररथाः कायान्मांसमुत्कृत्य संगताः।
प्रहृष्टा भक्षयिष्यन्ति निहतस्य मया रणे॥', 'kasya patrarathāḥ kāyān māṃsam utkṛtya saṃgatāḥ
prahṛṣṭā bhakṣayiṣyanti nihatasya mayā raṇe', null, 3018007),
('ramayana-3-18-8', 8, 'Aranya Kanda, Sarga 18, Verse 8', 'तं न देवा न गन्धर्वा न पिशाचा न राक्षसाः।
मयापकृष्टं कृपणं शक्तास्त्रातुं महाहवे॥', 'taṃ na devā na gandharvā na piśācā na rākṣasāḥ
mayāpakṛṣṭaṃ kṛpaṇaṃ śaktās trātuṃ mahāhave', null, 3018008),
('ramayana-3-18-9', 9, 'Aranya Kanda, Sarga 18, Verse 9', 'उपलभ्य शनैः संज्ञां तं मे शंसितुमर्हसि।
येन त्वं दुर्विनीतेन वने विक्रम्य निर्जिता॥', 'upalabhya śanaiḥ saṃjñāṃ taṃ me śaṃsitum arhasi
yena tvaṃ durvinītena vane vikramya nirjitā', null, 3018009),
('ramayana-3-18-10', 10, 'Aranya Kanda, Sarga 18, Verse 10', 'इति भ्रातुर्वचः श्रुत्वा क्रुद्धस्य च विशेषतः।
ततः शूर्पणखा वाक्यं सबाष्पमिदमब्रवीत्॥', 'iti bhrātur vacaḥ śrutvā kruddhasya ca viśeṣataḥ
tataḥ śūrpaṇakhā vākyaṃ sabāṣpam idam abravīt', null, 3018010),
('ramayana-3-18-11', 11, 'Aranya Kanda, Sarga 18, Verse 11', 'तरुणौ रूपसंपन्नौ सुकूमारौ महाबलौ।
पुण्डरीकविशालाक्षौ चीरकृष्णाजिनाम्बरौ॥', 'taruṇau rūpasaṃpannau sukūmārau mahābalau
puṇḍarīkaviśālākṣau cīrakṛṣṇājināmbarau', null, 3018011),
('ramayana-3-18-12', 12, 'Aranya Kanda, Sarga 18, Verse 12', 'गन्धर्वराजप्रतिमौ पार्थिवव्यञ्जनान्वितौ।
देवौ वा मानुषौ वा तौ न तर्कयितुमुत्सहे॥', 'gandharvarājapratimau pārthivavyañjanānvitau
devau vā mānuṣau vā tau na tarkayitum utsahe', null, 3018012),
('ramayana-3-18-13', 13, 'Aranya Kanda, Sarga 18, Verse 13', 'तरुणी रूपसंपन्ना सर्वाभरणभूषिता।
दृष्टा तत्र मया नारी तयोर्मध्ये सुमध्यमा॥', 'taruṇī rūpasaṃpannā sarvābharaṇabhūṣitā
dṛṣṭā tatra mayā nārī tayor madhye sumadhyamā', null, 3018013),
('ramayana-3-18-14', 14, 'Aranya Kanda, Sarga 18, Verse 14', 'ताभ्यामुभाभ्यां संभूय प्रमदामधिकृत्य ताम्।
इमामवस्थां नीताहं यथानाथासती तथा॥', 'tābhyām ubhābhyāṃ saṃbhūya pramadām adhikṛtya tām
imām avasthāṃ nītāhaṃ yathānāthāsatī tathā', null, 3018014),
('ramayana-3-18-15', 15, 'Aranya Kanda, Sarga 18, Verse 15', 'तस्याश्चानृजुवृत्तायास्तयोश्च हतयोरहम्।
सफेनं पातुमिच्छामि रुधिरं रणमूर्धनि॥', 'tasyāś cānṛjuvṛttāyās tayoś ca hatayor aham
saphenaṃ pātum icchāmi rudhiraṃ raṇamūrdhani', null, 3018015),
('ramayana-3-18-16', 16, 'Aranya Kanda, Sarga 18, Verse 16', 'एष मे प्रथमः कामः कृतस्तात त्वया भवेत्।
तस्यास्तयोश्च रुधिरं पिबेयमहमाहवे॥', 'eṣa me prathamaḥ kāmaḥ kṛtas tāta tvayā bhavet
tasyās tayoś ca rudhiraṃ pibeyam aham āhave', null, 3018016),
('ramayana-3-18-17', 17, 'Aranya Kanda, Sarga 18, Verse 17', 'इति तस्यां ब्रुवाणायां चतुर्दश महाबलान्।
व्यादिदेश खरः क्रुद्धो राक्षसानन्तकोपमान्॥', 'iti tasyāṃ bruvāṇāyāṃ caturdaśa mahābalān
vyādideśa kharaḥ kruddho rākṣasān antakopamān', null, 3018017),
('ramayana-3-18-18', 18, 'Aranya Kanda, Sarga 18, Verse 18', 'मानुषौ शस्त्रसंपन्नौ चीरकृष्णाजिनाम्बरौ।
प्रविष्टौ दण्डकारण्यं घोरं प्रमदया सह॥', 'mānuṣau śastrasaṃpannau cīrakṛṣṇājināmbarau
praviṣṭau daṇḍakāraṇyaṃ ghoraṃ pramadayā saha', null, 3018018),
('ramayana-3-18-19', 19, 'Aranya Kanda, Sarga 18, Verse 19', 'तौ हत्वा तां च दुर्वृत्तामुपावर्तितुमर्हथ।
इयं च रुधिरं तेषां भगिनी मम पास्यति॥', 'tau hatvā tāṃ ca durvṛttām upāvartitum arhatha
iyaṃ ca rudhiraṃ teṣāṃ bhaginī mama pāsyati', null, 3018019),
('ramayana-3-18-20', 20, 'Aranya Kanda, Sarga 18, Verse 20', 'मनोरथोऽयमिष्टोऽस्या भगिन्या मम राक्षसाः।
शीघ्रं संपद्यतां गत्वा तौ प्रमथ्य स्वतेजसा॥', 'manoratho ''yam iṣṭo ''syā bhaginyā mama rākṣasāḥ
śīghraṃ saṃpadyatāṃ gatvā tau pramathya svatejasā', null, 3018020),
('ramayana-3-18-21', 21, 'Aranya Kanda, Sarga 18, Verse 21', 'इति प्रतिसमादिष्टा राक्षसास्ते चतुर्दश।
तत्र जग्मुस्तया सार्धं घना वातेरिता यथा॥', 'iti pratisamādiṣṭā rākṣasās te caturdaśa
tatra jagmus tayā sārdhaṃ ghanā vāteritā yathā', null, 3018021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 19 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-19-1', 1, 'Aranya Kanda, Sarga 19, Verse 1', 'ततः शूर्पणखा घोरा राघवाश्रममागता।
रक्षसामाचचक्षे तौ भ्रातरौ सह सीतया॥', 'tataḥ śūrpaṇakhā ghorā rāghavāśramam āgatā
rakṣasām ācacakṣe tau bhrātarau saha sītayā', null, 3019001),
('ramayana-3-19-2', 2, 'Aranya Kanda, Sarga 19, Verse 2', 'ते रामं पर्णशालायामुपविष्टं महाबलम्।
ददृशुः सीतया सार्धं वैदेह्या लक्ष्मणेन च॥', 'te rāmaṃ parṇaśālāyām upaviṣṭaṃ mahābalam
dadṛśuḥ sītayā sārdhaṃ vaidehyā lakṣmaṇena ca', null, 3019002),
('ramayana-3-19-3', 3, 'Aranya Kanda, Sarga 19, Verse 3', 'तान्दृष्ट्वा राघवः श्रीमानागतां तां च राक्षसीम्।
अब्रवीद्भ्रातरं रामो लक्ष्मणं दीप्ततेजसं॥', 'tān dṛṣṭvā rāghavaḥ śrīmān āgatāṃ tāṃ ca rākṣasīm
abravīd bhrātaraṃ rāmo lakṣmaṇaṃ dīptatejasaṃ', null, 3019003),
('ramayana-3-19-4', 4, 'Aranya Kanda, Sarga 19, Verse 4', 'मुहूर्तं भव सौमित्रे सीतायाः प्रत्यनन्तरः।
इमानस्या वधिष्यामि पदवीमागतानिह॥', 'muhūrtaṃ bhava saumitre sītāyāḥ pratyanantaraḥ
imān asyā vadhiṣyāmi padavīm āgatān iha', null, 3019004),
('ramayana-3-19-5', 5, 'Aranya Kanda, Sarga 19, Verse 5', 'वाक्यमेतत्ततः श्रुत्वा रामस्य विदितात्मनः।
तथेति लक्ष्मणो वाक्यं रामस्य प्रत्यपूजयत्॥', 'vākyam etat tataḥ śrutvā rāmasya viditātmanaḥ
tatheti lakṣmaṇo vākyaṃ rāmasya pratyapūjayat', null, 3019005),
('ramayana-3-19-6', 6, 'Aranya Kanda, Sarga 19, Verse 6', 'राघवोऽपि महच्चापं चामीकरविभूषितम्।
चकार सज्यं धर्मात्मा तानि रक्षांसि चाब्रवीत्॥', 'rāghavo ''pi mahac cāpaṃ cāmīkaravibhūṣitam
cakāra sajyaṃ dharmātmā tāni rakṣāṃsi cābravīt', null, 3019006),
('ramayana-3-19-7', 7, 'Aranya Kanda, Sarga 19, Verse 7', 'पुत्रौ दशरथस्यावां भ्रातरौ रामलक्ष्मणौ।
प्रविष्टौ सीतया सार्धं दुश्चरं दण्डकावनम्॥', 'putrau daśarathasyāvāṃ bhrātarau rāmalakṣmaṇau
praviṣṭau sītayā sārdhaṃ duścaraṃ daṇḍakāvanam', null, 3019007),
('ramayana-3-19-8', 8, 'Aranya Kanda, Sarga 19, Verse 8', 'फलमूलाशनौ दान्तौ तापसौ धर्मचारिणौ।
वसन्तौ दण्डकारण्ये किमर्थमुपहिंसथ॥', 'phalamūlāśanau dāntau tāpasau dharmacāriṇau
vasantau daṇḍakāraṇye kimartham upahiṃsatha', null, 3019008),
('ramayana-3-19-9', 9, 'Aranya Kanda, Sarga 19, Verse 9', 'युष्मान्पापात्मकान्हन्तुं विप्रकारान्महावने।
ऋषीणां तु नियोगेन प्राप्तोऽहं सशरासनः॥', 'yuṣmān pāpātmakān hantuṃ viprakārān mahāvane
ṛṣīṇāṃ tu niyogena prāpto ''haṃ saśarāsanaḥ', null, 3019009),
('ramayana-3-19-10', 10, 'Aranya Kanda, Sarga 19, Verse 10', 'तिष्ठतैवात्र संतुष्टा नोपसर्पितुमर्हथ।
यदि प्राणैरिहार्थो वो निवर्तध्वं निशाचराः॥', 'tiṣṭhataivātra saṃtuṣṭā nopasarpitum arhatha
yadi prāṇair ihārtho vo nivartadhvaṃ niśācarāḥ', null, 3019010),
('ramayana-3-19-11', 11, 'Aranya Kanda, Sarga 19, Verse 11', 'तस्य तद्वचनं श्रुत्वा राक्षसास्ते चतुर्दश।
ऊचुर्वाचं सुसंक्रुद्धा ब्रह्मघ्नः शूलपाणयः॥', 'tasya tad vacanaṃ śrutvā rākṣasās te caturdaśa
ūcur vācaṃ susaṃkruddhā brahmaghnaḥ śūlapāṇayaḥ', null, 3019011),
('ramayana-3-19-12', 12, 'Aranya Kanda, Sarga 19, Verse 12', 'संरक्तनयना घोरा रामं रक्तान्तलोचनम्।
परुषा मधुराभाषं हृष्टादृष्टपराक्रमम्॥', 'saṃraktanayanā ghorā rāmaṃ raktāntalocanam
paruṣā madhurābhāṣaṃ hṛṣṭādṛṣṭaparākramam', null, 3019012),
('ramayana-3-19-13', 13, 'Aranya Kanda, Sarga 19, Verse 13', 'क्रोधमुत्पाद्य नो भर्तुः खरस्य सुमहात्मनः।
त्वमेव हास्यसे प्राणानद्यास्माभिर्हतो युधि॥', 'krodham utpādya no bhartuḥ kharasya sumahātmanaḥ
tvam eva hāsyase prāṇān adyāsmābhir hato yudhi', null, 3019013),
('ramayana-3-19-14', 14, 'Aranya Kanda, Sarga 19, Verse 14', 'का हि ते शक्तिरेकस्य बहूनां रणमूर्धनि।
अस्माकमग्रतः स्थातुं किं पुनर्योद्धुमाहवे॥', 'kā hi te śaktir ekasya bahūnāṃ raṇamūrdhani
asmākam agrataḥ sthātuṃ kiṃ punar yoddhum āhave', null, 3019014),
('ramayana-3-19-15', 15, 'Aranya Kanda, Sarga 19, Verse 15', 'एभिर्बाहुप्रयुक्तैर्नः परिघैः शूलपट्टिशैः।
प्राणांस्त्यक्ष्यसि वीर्यं च धनुश्च करपीडितम्॥', 'ebhir bāhuprayuktair naḥ parighaiḥ śūlapaṭṭiśaiḥ
prāṇāṃs tyakṣyasi vīryaṃ ca dhanuś ca karapīḍitam', null, 3019015),
('ramayana-3-19-16', 16, 'Aranya Kanda, Sarga 19, Verse 16', 'इत्येवमुक्त्वा संरब्धा राक्षसास्ते चतुर्दश।
उद्यतायुधनिस्त्रिंशा राममेवाभिदुद्रुवुः।
चिक्षिपुस्तानि शूलानि राघवं प्रति दुर्जयम्॥', 'ity evam uktvā saṃrabdhā rākṣasās te caturdaśa
udyatāyudhanistriṃśā rāmam evābhidudruvuḥ
cikṣipus tāni śūlāni rāghavaṃ prati durjayam', null, 3019016),
('ramayana-3-19-17', 17, 'Aranya Kanda, Sarga 19, Verse 17', 'तानि शूलानि काकुत्स्थः समस्तानि चतुर्दश।
तावद्भिरेव चिच्छेद शरैः काञ्चनभूषणैः॥', 'tāni śūlāni kākutsthaḥ samastāni caturdaśa
tāvadbhir eva ciccheda śaraiḥ kāñcanabhūṣaṇaiḥ', null, 3019017),
('ramayana-3-19-18', 18, 'Aranya Kanda, Sarga 19, Verse 18', 'ततः पश्चान्महातेजा नाराचान्सूर्यसंनिभान्।
जग्राह परमक्रुद्धश्चतुर्दश शिलाशितान्॥', 'tataḥ paścān mahātejā nārācān sūryasaṃnibhān
jagrāha paramakruddhaś caturdaśa śilāśitān', null, 3019018),
('ramayana-3-19-19', 19, 'Aranya Kanda, Sarga 19, Verse 19', 'गृहीत्वा धनुरायम्य लक्ष्यानुद्दिश्य राक्षसान्।
मुमोच राघवो बाणान्वज्रानिव शतक्रतुः॥', 'gṛhītvā dhanur āyamya lakṣyān uddiśya rākṣasān
mumoca rāghavo bāṇān vajrān iva śatakratuḥ', null, 3019019),
('ramayana-3-19-20', 20, 'Aranya Kanda, Sarga 19, Verse 20', 'रुक्मपुङ्खाश्च विशिखाः प्रदीप्ता हेमभूषणाः।
अन्तरिक्षे महोल्कानां बभूवुस्तुल्यवर्चसः॥', 'rukmapuṅkhāś ca viśikhāḥ pradīptā hemabhūṣaṇāḥ
antarikṣe maholkānāṃ babhūvus tulyavarcasaḥ', null, 3019020),
('ramayana-3-19-21', 21, 'Aranya Kanda, Sarga 19, Verse 21', 'ते भित्त्वा रक्षसां वेगाद्वक्षांसि रुधिराप्लुताः।
विनिष्पेतुस्तदा भूमौ न्यमज्जन्ताशनिस्वनाः॥', 'te bhittvā rakṣasāṃ vegād vakṣāṃsi rudhirāplutāḥ
viniṣpetus tadā bhūmau nyamajjantāśanisvanāḥ', null, 3019021),
('ramayana-3-19-22', 22, 'Aranya Kanda, Sarga 19, Verse 22', 'ते भिन्नहृदया भूमौ छिन्नमूला इव द्रुमाः।
निपेतुः शोणितार्द्राङ्गा विकृता विगतासवः॥', 'te bhinnahṛdayā bhūmau chinnamūlā iva drumāḥ
nipetuḥ śoṇitārdrāṅgā vikṛtā vigatāsavaḥ', null, 3019022),
('ramayana-3-19-23', 23, 'Aranya Kanda, Sarga 19, Verse 23', 'तान्भूमौ पतितान्दृष्ट्वा राक्षसी क्रोधमूर्छिता।
परित्रस्ता पुनस्तत्र व्यसृजद्भैरवं रवम्॥', 'tān bhūmau patitān dṛṣṭvā rākṣasī krodhamūrchitā
paritrastā punas tatra vyasṛjad bhairavaṃ ravam', null, 3019023),
('ramayana-3-19-24', 24, 'Aranya Kanda, Sarga 19, Verse 24', 'सा नदन्ती महानादं जवाच्छूर्पणखा पुनः।
उपगम्य खरं सा तु किं चित्संशुष्क शोणिता।
पपात पुनरेवार्ता सनिर्यासेव वल्लरी॥', 'sā nadantī mahānādaṃ javāc chūrpaṇakhā punaḥ
upagamya kharaṃ sā tu kiṃ cit saṃśuṣka śoṇitā
papāta punar evārtā saniryāseva vallarī', null, 3019024),
('ramayana-3-19-25', 25, 'Aranya Kanda, Sarga 19, Verse 25', 'निपातितान्प्रेक्ष्य रणे तु राक्षसान्प्रधाविता शूर्पणखा पुनस्ततः।
वधं च तेषां निखिलेन रक्षसां शशंस सर्वं भगिनी खरस्य सा॥', 'nipātitān prekṣya raṇe tu rākṣasān pradhāvitā śūrpaṇakhā punas tataḥ
vadhaṃ ca teṣāṃ nikhilena rakṣasāṃ śaśaṃsa sarvaṃ bhaginī kharasya sā', null, 3019025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 20 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-20-1', 1, 'Aranya Kanda, Sarga 20, Verse 1', 'स पुनः पतितां दृष्ट्वा क्रोधाच्छूर्पणखां खरः।
उवाच व्यक्तता वाचा तामनर्थार्थमागताम्॥', 'sa punaḥ patitāṃ dṛṣṭvā krodhāc chūrpaṇakhāṃ kharaḥ
uvāca vyaktatā vācā tām anarthārtham āgatām', null, 3020001),
('ramayana-3-20-2', 2, 'Aranya Kanda, Sarga 20, Verse 2', 'मया त्विदानीं शूरास्ते राक्षसा रुधिराशनाः।
त्वत्प्रियार्थं विनिर्दिष्टाः किमर्थं रुद्यते पुनः॥', 'mayā tv idānīṃ śūrās te rākṣasā rudhirāśanāḥ
tvatpriyārthaṃ vinirdiṣṭāḥ kimarthaṃ rudyate punaḥ', null, 3020002),
('ramayana-3-20-3', 3, 'Aranya Kanda, Sarga 20, Verse 3', 'भक्ताश्चैवानुरक्ताश्च हिताश्च मम नित्यशः।
घ्नन्तोऽपि न निहन्तव्या न न कुर्युर्वचो मम॥', 'bhaktāś caivānuraktāś ca hitāś ca mama nityaśaḥ
ghnanto ''pi na nihantavyā na na kuryur vaco mama', null, 3020003),
('ramayana-3-20-4', 4, 'Aranya Kanda, Sarga 20, Verse 4', 'किमेतच्छ्रोतुमिच्छामि कारणं यत्कृते पुनः।
हा नाथेति विनर्दन्ती सर्पवद्वेष्टसे क्षितौ॥', 'kim etac chrotum icchāmi kāraṇaṃ yatkṛte punaḥ
hā nātheti vinardantī sarpavad veṣṭase kṣitau', null, 3020004),
('ramayana-3-20-5', 5, 'Aranya Kanda, Sarga 20, Verse 5', 'अनाथवद्विलपसि किं नु नाथे मयि स्थिते।
उत्तिष्ठोत्तिष्ठ मा भैषीर्वैक्लव्यं त्यज्यतामिह॥', 'anāthavad vilapasi kiṃ nu nāthe mayi sthite
uttiṣṭhottiṣṭha mā bhaiṣīr vaiklavyaṃ tyajyatām iha', null, 3020005),
('ramayana-3-20-6', 6, 'Aranya Kanda, Sarga 20, Verse 6', 'इत्येवमुक्ता दुर्धर्षा खरेण परिसान्त्विता।
विमृज्य नयने सास्रे खरं भ्रातरमब्रवीत्॥', 'ity evam uktā durdharṣā khareṇa parisāntvitā
vimṛjya nayane sāsre kharaṃ bhrātaram abravīt', null, 3020006),
('ramayana-3-20-7', 7, 'Aranya Kanda, Sarga 20, Verse 7', 'प्रेषिताश्च त्वया शूरा राक्षसास्ते चतुर्दश।
निहन्तुं राघवं घोरा मत्प्रियार्थं सलक्ष्मणम्॥', 'preṣitāś ca tvayā śūrā rākṣasās te caturdaśa
nihantuṃ rāghavaṃ ghorā matpriyārthaṃ salakṣmaṇam', null, 3020007),
('ramayana-3-20-8', 8, 'Aranya Kanda, Sarga 20, Verse 8', 'ते तु रामेण सामर्षाः शूलपट्टिशपाणयः।
समरे निहताः सर्वे सायकैर्मर्मभेदिभिः॥', 'te tu rāmeṇa sāmarṣāḥ śūlapaṭṭiśapāṇayaḥ
samare nihatāḥ sarve sāyakair marmabhedibhiḥ', null, 3020008),
('ramayana-3-20-9', 9, 'Aranya Kanda, Sarga 20, Verse 9', 'तान्भूमौ पतितान्दृष्ट्वा क्षणेनैव महाबलान्।
रामस्य च महत्कर्म महांस्त्रासोऽभवन्मम॥', 'tān bhūmau patitān dṛṣṭvā kṣaṇenaiva mahābalān
rāmasya ca mahat karma mahāṃs trāso ''bhavan mama', null, 3020009),
('ramayana-3-20-10', 10, 'Aranya Kanda, Sarga 20, Verse 10', 'सास्मि भीता समुद्विग्ना विषण्णा च निशाचर।
शरणं त्वां पुनः प्राप्ता सर्वतो भयदर्शिनी॥', 'sāsmi bhītā samudvignā viṣaṇṇā ca niśācara
śaraṇaṃ tvāṃ punaḥ prāptā sarvato bhayadarśinī', null, 3020010),
('ramayana-3-20-11', 11, 'Aranya Kanda, Sarga 20, Verse 11', 'विषादनक्राध्युषिते परित्रासोर्मिमालिनि।
किं मां न त्रायसे मग्नां विपुले शोकसागरे॥', 'viṣādanakrādhyuṣite paritrāsormimālini
kiṃ māṃ na trāyase magnāṃ vipule śokasāgare', null, 3020011),
('ramayana-3-20-12', 12, 'Aranya Kanda, Sarga 20, Verse 12', 'एते च निहता भूमौ रामेण निशितैः शरैः।
ये च मे पदवीं प्राप्ता राक्षसाः पिशिताशनाः॥', 'ete ca nihatā bhūmau rāmeṇa niśitaiḥ śaraiḥ
ye ca me padavīṃ prāptā rākṣasāḥ piśitāśanāḥ', null, 3020012),
('ramayana-3-20-13', 13, 'Aranya Kanda, Sarga 20, Verse 13', 'मयि ते यद्यनुक्रोशो यदि रक्षःसु तेषु च।
रामेण यदि शक्तिस्ते तेजो वास्ति निशाचर।
दण्डकारण्यनिलयं जहि राक्षसकण्टकम्॥', 'mayi te yady anukrośo yadi rakṣaḥsu teṣu ca
rāmeṇa yadi śaktis te tejo vāsti niśācara
daṇḍakāraṇyanilayaṃ jahi rākṣasakaṇṭakam', null, 3020013),
('ramayana-3-20-14', 14, 'Aranya Kanda, Sarga 20, Verse 14', 'यदि रामं ममामित्रमद्य त्वं न वधिष्यसि।
तव चैवाग्रतः प्राणांस्त्यक्ष्यामि निरपत्रपा॥', 'yadi rāmaṃ mamāmitram adya tvaṃ na vadhiṣyasi
tava caivāgrataḥ prāṇāṃs tyakṣyāmi nirapatrapā', null, 3020014),
('ramayana-3-20-15', 15, 'Aranya Kanda, Sarga 20, Verse 15', 'बुद्ध्याहमनुपश्यामि न त्वं रामस्य संयुगे।
स्थातुं प्रतिमुखे शक्तः सचापस्य महारणे॥', 'buddhyāham anupaśyāmi na tvaṃ rāmasya saṃyuge
sthātuṃ pratimukhe śaktaḥ sacāpasya mahāraṇe', null, 3020015),
('ramayana-3-20-16', 16, 'Aranya Kanda, Sarga 20, Verse 16', 'शूरमानी न शूरस्त्वं मिथ्यारोपितविक्रमः।
मानुषौ यन्न शक्नोषि हन्तुं तौ रामलक्ष्मणौ॥', 'śūramānī na śūras tvaṃ mithyāropitavikramaḥ
mānuṣau yan na śaknoṣi hantuṃ tau rāmalakṣmaṇau', null, 3020016),
('ramayana-3-20-17', 17, 'Aranya Kanda, Sarga 20, Verse 17', 'अपयाहि जनस्थानात्त्वरितः सहबान्धवः।
निःसत्त्वस्याल्पवीर्यस्य वासस्ते कीदृशस्त्विह॥', 'apayāhi janasthānāt tvaritaḥ sahabāndhavaḥ
niḥsattvasyālpavīryasya vāsas te kīdṛśas tv iha', null, 3020017),
('ramayana-3-20-18', 18, 'Aranya Kanda, Sarga 20, Verse 18', 'रामतेजोऽभिभूतो हि त्वं क्षिप्रं विनशिष्यसि।
स हि तेजःसमायुक्तो रामो दशरथात्मजः।
भ्राता चास्य महावीर्यो येन चास्मि विरूपिता॥', 'rāmatejo''bhibhūto hi tvaṃ kṣipraṃ vinaśiṣyasi
sa hi tejaḥsamāyukto rāmo daśarathātmajaḥ
bhrātā cāsya mahāvīryo yena cāsmi virūpitā', null, 3020018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 21 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-21-1', 1, 'Aranya Kanda, Sarga 21, Verse 1', 'एवमाधर्षितः शूरः शूर्पणख्या खरस्तदा।
उवाच रक्षसां मध्ये खरः खरतरं वचः॥', 'evam ādharṣitaḥ śūraḥ śūrpaṇakhyā kharas tadā
uvāca rakṣasāṃ madhye kharaḥ kharataraṃ vacaḥ', null, 3021001),
('ramayana-3-21-2', 2, 'Aranya Kanda, Sarga 21, Verse 2', 'तवापमानप्रभवः क्रोधोऽयमतुलो मम।
न शक्यते धारयितुं लवणाम्भ इवोत्थितम्॥', 'tavāpamānaprabhavaḥ krodho ''yam atulo mama
na śakyate dhārayituṃ lavaṇāmbha ivotthitam', null, 3021002),
('ramayana-3-21-3', 3, 'Aranya Kanda, Sarga 21, Verse 3', 'न रामं गणये वीर्यान्मानुषं क्षीणजीवितम्।
आत्मा दुश्चरितैः प्राणान्हतो योऽद्य विमोक्ष्यति॥', 'na rāmaṃ gaṇaye vīryān mānuṣaṃ kṣīṇajīvitam
ātmā duścaritaiḥ prāṇān hato yo ''dya vimokṣyati', null, 3021003),
('ramayana-3-21-4', 4, 'Aranya Kanda, Sarga 21, Verse 4', 'बाष्पः संह्रियतामेष संभ्रमश्च विमुच्यताम्।
अहं रामः सह भ्रात्रा नयामि यमसादनम्॥', 'bāṣpaḥ saṃhriyatām eṣa saṃbhramaś ca vimucyatām
ahaṃ rāmaḥ saha bhrātrā nayāmi yamasādanam', null, 3021004),
('ramayana-3-21-5', 5, 'Aranya Kanda, Sarga 21, Verse 5', 'परश्वधहतस्याद्य मन्दप्राणस्य भूतले।
रामस्य रुधिरं रक्तमुष्णं पास्यसि राक्षसि॥', 'paraśvadhahatasyādya mandaprāṇasya bhūtale
rāmasya rudhiraṃ raktam uṣṇaṃ pāsyasi rākṣasi', null, 3021005),
('ramayana-3-21-6', 6, 'Aranya Kanda, Sarga 21, Verse 6', 'सा प्रहृष्ट्वा वचः श्रुत्वा खरस्य वदनाच्च्युतम्।
प्रशशंस पुनर्मौर्ख्याद्भ्रातरं रक्षसां वरम्॥', 'sā prahṛṣṭvā vacaḥ śrutvā kharasya vadanāc cyutam
praśaśaṃsa punar maurkhyād bhrātaraṃ rakṣasāṃ varam', null, 3021006),
('ramayana-3-21-7', 7, 'Aranya Kanda, Sarga 21, Verse 7', 'तया परुषितः पूर्वं पुनरेव प्रशंसितः।
अब्रवीद्दूषणं नाम खरः सेनापतिं तदा॥', 'tayā paruṣitaḥ pūrvaṃ punar eva praśaṃsitaḥ
abravīd dūṣaṇaṃ nāma kharaḥ senāpatiṃ tadā', null, 3021007),
('ramayana-3-21-8', 8, 'Aranya Kanda, Sarga 21, Verse 8', 'चतुर्दश सहस्राणि मम चित्तानुवर्तिनाम्।
रक्षसीं भीमवेगानां समरेष्वनिवर्तिनाम्॥', 'caturdaśa sahasrāṇi mama cittānuvartinām
rakṣasīṃ bhīmavegānāṃ samareṣv anivartinām', null, 3021008),
('ramayana-3-21-9', 9, 'Aranya Kanda, Sarga 21, Verse 9', 'नीलजीमूतवर्णानां घोराणां क्रूरकर्मणाम्।
लोकसिंहाविहाराणां बलिनामुग्रतेजसाम्॥', 'nīlajīmūtavarṇānāṃ ghorāṇāṃ krūrakarmaṇām
lokasiṃhāvihārāṇāṃ balinām ugratejasām', null, 3021009),
('ramayana-3-21-10', 10, 'Aranya Kanda, Sarga 21, Verse 10', 'तेषां शार्दूलदर्पाणां महास्यानां महौजसाम्।
सर्वोद्योगमुदीर्णानां रक्षसां सौम्य कारय॥', 'teṣāṃ śārdūladarpāṇāṃ mahāsyānāṃ mahaujasām
sarvodyogam udīrṇānāṃ rakṣasāṃ saumya kāraya', null, 3021010),
('ramayana-3-21-11', 11, 'Aranya Kanda, Sarga 21, Verse 11', 'उपस्थापय मे क्षिप्रं रथं सौम्य धनूंषि च।
शरांश्च चित्रान्खड्गांश्च शक्तीश्च विविधाः शिताः॥', 'upasthāpaya me kṣipraṃ rathaṃ saumya dhanūṃṣi ca
śarāṃś ca citrān khaḍgāṃś ca śaktīś ca vividhāḥ śitāḥ', null, 3021011),
('ramayana-3-21-12', 12, 'Aranya Kanda, Sarga 21, Verse 12', 'अग्रे निर्यातुमिच्छामि पौलस्त्यानां महात्मनाम्।
वधार्थं दुर्विनीतस्य रामस्य रणकोविदः॥', 'agre niryātum icchāmi paulastyānāṃ mahātmanām
vadhārthaṃ durvinītasya rāmasya raṇakovidaḥ', null, 3021012),
('ramayana-3-21-13', 13, 'Aranya Kanda, Sarga 21, Verse 13', 'इति तस्य ब्रुवाणस्य सूर्यवर्णं महारथम्।
सदश्वैः शबलैर्युक्तमाचचक्षेऽथ दूषणः॥', 'iti tasya bruvāṇasya sūryavarṇaṃ mahāratham
sadaśvaiḥ śabalair yuktam ācacakṣe ''tha dūṣaṇaḥ', null, 3021013),
('ramayana-3-21-14', 14, 'Aranya Kanda, Sarga 21, Verse 14', 'तं मेरुशिखराकारं तप्तकाञ्चनभूषणम्।
हेमचक्रमसंबाधं वैदूर्यमय कूबरम्॥', 'taṃ meruśikharākāraṃ taptakāñcanabhūṣaṇam
hemacakram asaṃbādhaṃ vaidūryamaya kūbaram', null, 3021014),
('ramayana-3-21-15', 15, 'Aranya Kanda, Sarga 21, Verse 15', 'मत्स्यैः पुष्पैर्द्रुमैः शैलैश्चन्द्रसूर्यैश्च काञ्चनैः।
माङ्गल्यैः पक्षिसंघैश्च ताराभिश्च समावृतम्॥', 'matsyaiḥ puṣpair drumaiḥ śailaiś candrasūryaiś ca kāñcanaiḥ
māṅgalyaiḥ pakṣisaṃghaiś ca tārābhiś ca samāvṛtam', null, 3021015),
('ramayana-3-21-16', 16, 'Aranya Kanda, Sarga 21, Verse 16', 'ध्वजनिस्त्रिंशसंपन्नं किङ्किणीकविभूषितम्।
सदश्वयुक्तं सोऽमर्षादारुरोह रथं खरः॥', 'dhvajanistriṃśasaṃpannaṃ kiṅkiṇīkavibhūṣitam
sadaśvayuktaṃ so ''marṣād āruroha rathaṃ kharaḥ', null, 3021016),
('ramayana-3-21-17', 17, 'Aranya Kanda, Sarga 21, Verse 17', 'निशाम्य तं रथगतं राक्षसा भीमविक्रमाः।
तस्थुः संपरिवार्यैनं दूषणं च महाबलम्॥', 'niśāmya taṃ rathagataṃ rākṣasā bhīmavikramāḥ
tasthuḥ saṃparivāryainaṃ dūṣaṇaṃ ca mahābalam', null, 3021017),
('ramayana-3-21-18', 18, 'Aranya Kanda, Sarga 21, Verse 18', 'खरस्तु तान्महेष्वासान्घोरचर्मायुधध्वजान्।
निर्यातेत्यब्रवीद्दृष्ट्वा रथस्थः सर्वराक्षसान्॥', 'kharas tu tān maheṣvāsān ghoracarmāyudhadhvajān
niryātety abravīd dṛṣṭvā rathasthaḥ sarvarākṣasān', null, 3021018),
('ramayana-3-21-19', 19, 'Aranya Kanda, Sarga 21, Verse 19', 'ततस्तद्राक्षसं सैन्यं घोरचर्मायुधध्वजम्।
निर्जगाम जनस्थानान्महानादं महाजवम्॥', 'tatas tad rākṣasaṃ sainyaṃ ghoracarmāyudhadhvajam
nirjagāma janasthānān mahānādaṃ mahājavam', null, 3021019),
('ramayana-3-21-20', 20, 'Aranya Kanda, Sarga 21, Verse 20', 'मुद्गरैः पट्टिशैः शूलैः सुतीक्ष्णैश्च परश्वधैः।
खड्गैश्चक्रैश्च हस्तस्थैर्भ्राजमानैश्च तोमरैः॥', 'mudgaraiḥ paṭṭiśaiḥ śūlaiḥ sutīkṣṇaiś ca paraśvadhaiḥ
khaḍgaiś cakraiś ca hastasthair bhrājamānaiś ca tomaraiḥ', null, 3021020),
('ramayana-3-21-21', 21, 'Aranya Kanda, Sarga 21, Verse 21', 'शक्तिभिः पतिघैर्घोरैरतिमात्रैश्च कार्मुकैः।
गदासिमुसलैर्वज्रैर्गृहीतैर्भीमदर्शनैः॥', 'śaktibhiḥ patighair ghorair atimātraiś ca kārmukaiḥ
gadāsimusalair vajrair gṛhītair bhīmadarśanaiḥ', null, 3021021),
('ramayana-3-21-22', 22, 'Aranya Kanda, Sarga 21, Verse 22', 'राक्षसानां सुघोराणां सहस्राणि चतुर्दश।
निर्यातानि जनस्थानात्खरचित्तानुवर्तिनाम्॥', 'rākṣasānāṃ sughorāṇāṃ sahasrāṇi caturdaśa
niryātāni janasthānāt kharacittānuvartinām', null, 3021022),
('ramayana-3-21-23', 23, 'Aranya Kanda, Sarga 21, Verse 23', 'तांस्त्वभिद्रवतो दृष्ट्वा राक्षसान्भीमविक्रमान्।
खरस्यापि रथः किं चिज्जगाम तदनन्तरम्॥', 'tāṃs tv abhidravato dṛṣṭvā rākṣasān bhīmavikramān
kharasyāpi rathaḥ kiṃ cij jagāma tadanantaram', null, 3021023),
('ramayana-3-21-24', 24, 'Aranya Kanda, Sarga 21, Verse 24', 'ततस्ताञ्शबलानश्वांस्तप्तकाञ्चनभूषितान्।
खरस्य मतमाज्ञाय सारथिः समचोदयत्॥', 'tatas tāñ śabalān aśvāṃs taptakāñcanabhūṣitān
kharasya matam ājñāya sārathiḥ samacodayat', null, 3021024),
('ramayana-3-21-25', 25, 'Aranya Kanda, Sarga 21, Verse 25', 'स चोदितो रथः शीघ्रं खरस्य रिपुघातिनः।
शब्देनापूरयामास दिशश्च प्रतिशस्तथा॥', 'sa codito rathaḥ śīghraṃ kharasya ripughātinaḥ
śabdenāpūrayām āsa diśaś ca pratiśas tathā', null, 3021025),
('ramayana-3-21-26', 26, 'Aranya Kanda, Sarga 21, Verse 26', 'प्रवृद्धमन्युस्तु खरः खरस्वनो रिपोर्वधार्थं त्वरितो यथान्तकः।
अचूचुदत्सारथिमुन्नदन्पुनर्महाबलो मेघ इवाश्मवर्षवान्॥', 'pravṛddhamanyus tu kharaḥ kharasvano ripor vadhārthaṃ tvarito yathāntakaḥ
acūcudat sārathim unnadan punar mahābalo megha ivāśmavarṣavān', null, 3021026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 22 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-22-1', 1, 'Aranya Kanda, Sarga 22, Verse 1', 'तत्प्रयातं बलं घोरमशिवं शोणितोदकम्।
अभ्यवर्षन्महामेघस्तुमुलो गर्दभारुणः॥', 'tat prayātaṃ balaṃ ghoram aśivaṃ śoṇitodakam
abhyavarṣan mahāmeghas tumulo gardabhāruṇaḥ', null, 3022001),
('ramayana-3-22-2', 2, 'Aranya Kanda, Sarga 22, Verse 2', 'निपेतुस्तुरगास्तस्य रथयुक्ता महाजवाः।
समे पुष्पचिते देशे राजमार्गे यदृच्छया॥', 'nipetus turagās tasya rathayuktā mahājavāḥ
same puṣpacite deśe rājamārge yadṛcchayā', null, 3022002),
('ramayana-3-22-3', 3, 'Aranya Kanda, Sarga 22, Verse 3', 'श्यामं रुधिरपर्यन्तं बभूव परिवेषणम्।
अलातचक्रप्रतिमं प्रतिगृह्य दिवाकरम्॥', 'śyāmaṃ rudhiraparyantaṃ babhūva pariveṣaṇam
alātacakrapratimaṃ pratigṛhya divākaram', null, 3022003),
('ramayana-3-22-4', 4, 'Aranya Kanda, Sarga 22, Verse 4', 'ततो ध्वजमुपागम्य हेमदण्डं समुच्छ्रितम्।
समाक्रम्य महाकायस्तस्थौ गृध्रः सुदारुणः॥', 'tato dhvajam upāgamya hemadaṇḍaṃ samucchritam
samākramya mahākāyas tasthau gṛdhraḥ sudāruṇaḥ', null, 3022004),
('ramayana-3-22-5', 5, 'Aranya Kanda, Sarga 22, Verse 5', 'जनस्थानसमीपे च समाक्रम्य खरस्वनाः।
विस्वरान्विविधांश्चक्रुर्मांसादा मृगपक्षिणः॥', 'janasthānasamīpe ca samākramya kharasvanāḥ
visvarān vividhāṃś cakrur māṃsādā mṛgapakṣiṇaḥ', null, 3022005),
('ramayana-3-22-6', 6, 'Aranya Kanda, Sarga 22, Verse 6', 'व्याजह्रुश्च पदीप्तायां दिशि वै भैरवस्वनम्।
अशिवा यातु दाहानां शिवा घोरा महास्वनाः॥', 'vyājahruś ca padīptāyāṃ diśi vai bhairavasvanam
aśivā yātu dāhānāṃ śivā ghorā mahāsvanāḥ', null, 3022006),
('ramayana-3-22-7', 7, 'Aranya Kanda, Sarga 22, Verse 7', 'प्रभिन्नगिरिसंकाशास्तोयशोषितधारिणः।
आकाशं तदनाकाशं चक्रुर्भीमा बलाहकाः॥', 'prabhinnagirisaṃkāśās toyaśoṣitadhāriṇaḥ
ākāśaṃ tad anākāśaṃ cakrur bhīmā balāhakāḥ', null, 3022007),
('ramayana-3-22-8', 8, 'Aranya Kanda, Sarga 22, Verse 8', 'बभूव तिमिरं घोरमुद्धतं रोमहर्षणम्।
दिशो वा विदिशो वापि सुव्यक्तं न चकाशिरे॥', 'babhūva timiraṃ ghoram uddhataṃ romaharṣaṇam
diśo vā vidiśo vāpi suvyaktaṃ na cakāśire', null, 3022008),
('ramayana-3-22-9', 9, 'Aranya Kanda, Sarga 22, Verse 9', 'क्षतजार्द्रसवर्णाभा संध्याकालं विना बभौ।
खरस्याभिमुखं नेदुस्तदा घोरा मृगाः खगाः॥', 'kṣatajārdrasavarṇābhā saṃdhyākālaṃ vinā babhau
kharasyābhimukhaṃ nedus tadā ghorā mṛgāḥ khagāḥ', null, 3022009),
('ramayana-3-22-10', 10, 'Aranya Kanda, Sarga 22, Verse 10', 'नित्याशिवकरा युद्धे शिवा घोरनिदर्शनाः।
नेदुर्बलस्याभिमुखं ज्वालोद्गारिभिराननैः॥', 'nityāśivakarā yuddhe śivā ghoranidarśanāḥ
nedur balasyābhimukhaṃ jvālodgāribhir ānanaiḥ', null, 3022010),
('ramayana-3-22-11', 11, 'Aranya Kanda, Sarga 22, Verse 11', 'कबन्धः परिघाभासो दृश्यते भास्करान्तिके।
जग्राह सूर्यं स्वर्भानुरपर्वणि महाग्रहः॥', 'kabandhaḥ parighābhāso dṛśyate bhāskarāntike
jagrāha sūryaṃ svarbhānur aparvaṇi mahāgrahaḥ', null, 3022011),
('ramayana-3-22-12', 12, 'Aranya Kanda, Sarga 22, Verse 12', 'प्रवाति मारुतः शीघ्रं निष्प्रभोऽभूद्दिवाकरः।
उत्पेतुश्च विना रात्रिं ताराः खद्योतसप्रभाः॥', 'pravāti mārutaḥ śīghraṃ niṣprabho ''bhūd divākaraḥ
utpetuś ca vinā rātriṃ tārāḥ khadyotasaprabhāḥ', null, 3022012),
('ramayana-3-22-13', 13, 'Aranya Kanda, Sarga 22, Verse 13', 'संलीनमीनविहगा नलिन्यः पुष्पपङ्कजाः।
तस्मिन्क्षणे बभूवुश्च विना पुष्पफलैर्द्रुमाः॥', 'saṃlīnamīnavihagā nalinyaḥ puṣpapaṅkajāḥ
tasmin kṣaṇe babhūvuś ca vinā puṣpaphalair drumāḥ', null, 3022013),
('ramayana-3-22-14', 14, 'Aranya Kanda, Sarga 22, Verse 14', 'उद्धूतश्च विना वातं रेणुर्जलधरारुणः।
वीचीकूचीति वाश्यन्तो बभूवुस्तत्र सारिकाः॥', 'uddhūtaś ca vinā vātaṃ reṇur jaladharāruṇaḥ
vīcīkūcīti vāśyanto babhūvus tatra sārikāḥ', null, 3022014),
('ramayana-3-22-15', 15, 'Aranya Kanda, Sarga 22, Verse 15', 'उल्काश्चापि सनिर्घोषा निपेतुर्घोरदर्शनाः।
प्रचचाल मही चापि सशैलवनकानना॥', 'ulkāś cāpi sanirghoṣā nipetur ghoradarśanāḥ
pracacāla mahī cāpi saśailavanakānanā', null, 3022015),
('ramayana-3-22-16', 16, 'Aranya Kanda, Sarga 22, Verse 16', 'खरस्य च रथस्थस्य नर्दमानस्य धीमतः।
प्राकम्पत भुजः सव्यः खरश्चास्यावसज्जत॥', 'kharasya ca rathasthasya nardamānasya dhīmataḥ
prākampata bhujaḥ savyaḥ kharaś cāsyāvasajjata', null, 3022016),
('ramayana-3-22-17', 17, 'Aranya Kanda, Sarga 22, Verse 17', 'सास्रा संपद्यते दृष्टिः पश्यमानस्य सर्वतः।
ललाटे च रुजा जाता न च मोहान्न्यवर्तत॥', 'sāsrā saṃpadyate dṛṣṭiḥ paśyamānasya sarvataḥ
lalāṭe ca rujā jātā na ca mohān nyavartata', null, 3022017),
('ramayana-3-22-18', 18, 'Aranya Kanda, Sarga 22, Verse 18', 'तान्समीक्ष्य महोत्पातानुत्थितान्रोमहर्षणान्।
अब्रवीद्राक्षसान्सर्वान्प्रहसन्स खरस्तदा॥', 'tān samīkṣya mahotpātān utthitān romaharṣaṇān
abravīd rākṣasān sarvān prahasan sa kharas tadā', null, 3022018),
('ramayana-3-22-19', 19, 'Aranya Kanda, Sarga 22, Verse 19', 'महोत्पातानिमान्सर्वानुत्थितान्घोरदर्शनान्।
न चिन्तयाम्यहं वीर्याद्बलवान्दुर्बलानिव॥', 'mahotpātān imān sarvān utthitān ghoradarśanān
na cintayāmy ahaṃ vīryād balavān durbalān iva', null, 3022019),
('ramayana-3-22-20', 20, 'Aranya Kanda, Sarga 22, Verse 20', 'तारा अपि शरैस्तीक्ष्णैः पातयेयं नभस्तलात्।
मृत्युं मरणधर्मेण संक्रुद्धो योजयाम्यहम्॥', 'tārā api śarais tīkṣṇaiḥ pātayeyaṃ nabhastalāt
mṛtyuṃ maraṇadharmeṇa saṃkruddho yojayāmy aham', null, 3022020),
('ramayana-3-22-21', 21, 'Aranya Kanda, Sarga 22, Verse 21', 'राघवं तं बलोत्सिक्तं भ्रातरं चापि लक्ष्मणम्।
अहत्वा सायकैस्तीक्ष्णैर्नोपावर्तितुमुत्सहे॥', 'rāghavaṃ taṃ balotsiktaṃ bhrātaraṃ cāpi lakṣmaṇam
ahatvā sāyakais tīkṣṇair nopāvartitum utsahe', null, 3022021),
('ramayana-3-22-22', 22, 'Aranya Kanda, Sarga 22, Verse 22', 'सकामा भगिनी मेऽस्तु पीत्वा तु रुधिरं तयोः।
यन्निमित्तं तु रामस्य लक्ष्मणस्य विपर्ययः॥', 'sakāmā bhaginī me ''stu pītvā tu rudhiraṃ tayoḥ
yannimittaṃ tu rāmasya lakṣmaṇasya viparyayaḥ', null, 3022022),
('ramayana-3-22-23', 23, 'Aranya Kanda, Sarga 22, Verse 23', 'न क्व चित्प्राप्तपूर्वो मे संयुगेषु पराजयः।
युष्माकमेतत्प्रत्यक्षं नानृतं कथयाम्यहम्॥', 'na kva cit prāptapūrvo me saṃyugeṣu parājayaḥ
yuṣmākam etat pratyakṣaṃ nānṛtaṃ kathayāmy aham', null, 3022023),
('ramayana-3-22-24', 24, 'Aranya Kanda, Sarga 22, Verse 24', 'देवराजमपि क्रुद्धो मत्तैरावतयायिनम्।
वज्रहस्तं रणे हन्यां किं पुनस्तौ च मानुषौ॥', 'devarājam api kruddho mattairāvatayāyinam
vajrahastaṃ raṇe hanyāṃ kiṃ punas tau ca mānuṣau', null, 3022024),
('ramayana-3-22-25', 25, 'Aranya Kanda, Sarga 22, Verse 25', 'सा तस्य गर्जितं श्रुत्वा राक्षसस्य महाचमूः।
प्रहर्षमतुलं लेभे मृत्युपाशावपाशिता॥', 'sā tasya garjitaṃ śrutvā rākṣasasya mahācamūḥ
praharṣam atulaṃ lebhe mṛtyupāśāvapāśitā', null, 3022025),
('ramayana-3-22-26', 26, 'Aranya Kanda, Sarga 22, Verse 26', 'समेयुश्च महात्मानो युद्धदर्शनकाङ्क्षिणः।
ऋषयो देवगन्धर्वाः सिद्धाश्च सह चारणैः॥', 'sameyuś ca mahātmāno yuddhadarśanakāṅkṣiṇaḥ
ṛṣayo devagandharvāḥ siddhāś ca saha cāraṇaiḥ', null, 3022026),
('ramayana-3-22-27', 27, 'Aranya Kanda, Sarga 22, Verse 27', 'समेत्य चोरुः सहितास्तेऽन्यायं पुण्यकर्मणः।
स्वस्ति गोब्राह्मणेभ्योऽस्तु लोकानां ये च संमताः॥', 'sametya coruḥ sahitās te ''nyāyaṃ puṇyakarmaṇaḥ
svasti gobrāhmaṇebhyo ''stu lokānāṃ ye ca saṃmatāḥ', null, 3022027),
('ramayana-3-22-28', 28, 'Aranya Kanda, Sarga 22, Verse 28', 'जयतां राघवो युद्धे पौलस्त्यान्रजनीचरान्।
चक्रा हस्तो यथा युद्धे सर्वानसुरपुंगवान्॥', 'jayatāṃ rāghavo yuddhe paulastyān rajanīcarān
cakrā hasto yathā yuddhe sarvān asurapuṃgavān', null, 3022028),
('ramayana-3-22-29', 29, 'Aranya Kanda, Sarga 22, Verse 29', 'एतच्चान्यच्च बहुशो ब्रुवाणाः परमर्षयः।
ददृशुर्वाहिनीं तेषां राक्षसानां गतायुषाम्॥', 'etac cānyac ca bahuśo bruvāṇāḥ paramarṣayaḥ
dadṛśur vāhinīṃ teṣāṃ rākṣasānāṃ gatāyuṣām', null, 3022029),
('ramayana-3-22-30', 30, 'Aranya Kanda, Sarga 22, Verse 30', 'रथेन तु खरो वेगात्सैन्यस्याग्राद्विनिःसृतः।
तं दृष्ट्वा राक्षसं भूयो राक्षसाश्च विनिःसृताः॥', 'rathena tu kharo vegāt sainyasyāgrād viniḥsṛtaḥ
taṃ dṛṣṭvā rākṣasaṃ bhūyo rākṣasāś ca viniḥsṛtāḥ', null, 3022030),
('ramayana-3-22-31', 31, 'Aranya Kanda, Sarga 22, Verse 31', 'श्येन गामी पृथुग्रीवो यज्ञशत्रुर्विहंगमः।
दुर्जयः करवीराक्षः परुषः कालकार्मुकः॥', 'śyena gāmī pṛthugrīvo yajñaśatrur vihaṃgamaḥ
durjayaḥ karavīrākṣaḥ paruṣaḥ kālakārmukaḥ', null, 3022031),
('ramayana-3-22-32', 32, 'Aranya Kanda, Sarga 22, Verse 32', 'मेघमाली महामाली सर्पास्यो रुधिराशनः।
द्वादशैते महावीर्याः प्रतस्थुरभितः खरम्॥', 'meghamālī mahāmālī sarpāsyo rudhirāśanaḥ
dvādaśaite mahāvīryāḥ pratasthur abhitaḥ kharam', null, 3022032),
('ramayana-3-22-33', 33, 'Aranya Kanda, Sarga 22, Verse 33', 'महाकपालः स्थूलाक्षः प्रमाथी त्रिशिरास्तथा।
चत्वार एते सेनाग्र्या दूषणं पृष्ठतोऽन्वयुः॥', 'mahākapālaḥ sthūlākṣaḥ pramāthī triśirās tathā
catvāra ete senāgryā dūṣaṇaṃ pṛṣṭhato ''nvayuḥ', null, 3022033),
('ramayana-3-22-34', 34, 'Aranya Kanda, Sarga 22, Verse 34', 'सा भीमवेगा समराभिकामा सुदारुणा राक्षसवीर सेना।
तौ राजपुत्रौ सहसाभ्युपेता मालाग्रहाणामिव चन्द्रसूर्यौ॥', 'sā bhīmavegā samarābhikāmā sudāruṇā rākṣasavīra senā
tau rājaputrau sahasābhyupetā mālāgrahāṇām iva candrasūryau', null, 3022034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 23 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-23-1', 1, 'Aranya Kanda, Sarga 23, Verse 1', 'आश्रमं प्रति याते तु खरे खरपराक्रमे।
तानेवौत्पातिकान्रामः सह भ्रात्रा ददर्श ह॥', 'āśramaṃ prati yāte tu khare kharaparākrame
tān evautpātikān rāmaḥ saha bhrātrā dadarśa ha', null, 3023001),
('ramayana-3-23-2', 2, 'Aranya Kanda, Sarga 23, Verse 2', 'तानुत्पातान्महाघोरानुत्थितान्रोमहर्षणान्।
प्रजानामहितान्दृष्ट्वा वाक्यं लक्ष्मणमब्रवीत्॥', 'tān utpātān mahāghorān utthitān romaharṣaṇān
prajānām ahitān dṛṣṭvā vākyaṃ lakṣmaṇam abravīt', null, 3023002),
('ramayana-3-23-3', 3, 'Aranya Kanda, Sarga 23, Verse 3', 'इमान्पश्य महाबाहो सर्वभूतापहारिणः।
समुत्थितान्महोत्पातान्संहर्तुं सर्वराक्षसान्॥', 'imān paśya mahābāho sarvabhūtāpahāriṇaḥ
samutthitān mahotpātān saṃhartuṃ sarvarākṣasān', null, 3023003),
('ramayana-3-23-4', 4, 'Aranya Kanda, Sarga 23, Verse 4', 'अमी रुधिरधारास्तु विसृजन्तः खरस्वनान्।
व्योम्नि मेघा विवर्तन्ते परुषा गर्दभारुणाः॥', 'amī rudhiradhārās tu visṛjantaḥ kharasvanān
vyomni meghā vivartante paruṣā gardabhāruṇāḥ', null, 3023004),
('ramayana-3-23-5', 5, 'Aranya Kanda, Sarga 23, Verse 5', 'सधूमाश्च शराः सर्वे मम युद्धाभिनन्दिनः।
रुक्मपृष्ठानि चापानि विवेष्टन्ते च लक्ष्मण॥', 'sadhūmāś ca śarāḥ sarve mama yuddhābhinandinaḥ
rukmapṛṣṭhāni cāpāni viveṣṭante ca lakṣmaṇa', null, 3023005),
('ramayana-3-23-6', 6, 'Aranya Kanda, Sarga 23, Verse 6', 'यादृशा इह कूजन्ति पक्षिणो वनचारिणः।
अग्रतो नो भयं प्राप्तं संशयो जीवितस्य च॥', 'yādṛśā iha kūjanti pakṣiṇo vanacāriṇaḥ
agrato no bhayaṃ prāptaṃ saṃśayo jīvitasya ca', null, 3023006),
('ramayana-3-23-7', 7, 'Aranya Kanda, Sarga 23, Verse 7', 'संप्रहारस्तु सुमहान्भविष्यति न संशयः।
अयमाख्याति मे बाहुः स्फुरमाणो मुहुर्मुहुः॥', 'saṃprahāras tu sumahān bhaviṣyati na saṃśayaḥ
ayam ākhyāti me bāhuḥ sphuramāṇo muhur muhuḥ', null, 3023007),
('ramayana-3-23-8', 8, 'Aranya Kanda, Sarga 23, Verse 8', 'संनिकर्षे तु नः शूर जयं शत्रोः पराजयम्।
सुप्रभं च प्रसन्नं च तव वक्त्रं हि लक्ष्यते॥', 'saṃnikarṣe tu naḥ śūra jayaṃ śatroḥ parājayam
suprabhaṃ ca prasannaṃ ca tava vaktraṃ hi lakṣyate', null, 3023008),
('ramayana-3-23-9', 9, 'Aranya Kanda, Sarga 23, Verse 9', 'उद्यतानां हि युद्धार्थं येषां भवति लक्ष्मणः।
निष्प्रभं वदनं तेषां भवत्यायुः परिक्षयः॥', 'udyatānāṃ hi yuddhārthaṃ yeṣāṃ bhavati lakṣmaṇaḥ
niṣprabhaṃ vadanaṃ teṣāṃ bhavaty āyuḥ parikṣayaḥ', null, 3023009),
('ramayana-3-23-10', 10, 'Aranya Kanda, Sarga 23, Verse 10', 'अनागतविधानं तु कर्तव्यं शुभमिच्छता।
आपदं शङ्कमानेन पुरुषेण विपश्चिता॥', 'anāgatavidhānaṃ tu kartavyaṃ śubham icchatā
āpadaṃ śaṅkamānena puruṣeṇa vipaścitā', null, 3023010),
('ramayana-3-23-11', 11, 'Aranya Kanda, Sarga 23, Verse 11', 'तस्माद्गृहीत्वा वैदेहीं शरपाणिर्धनुर्धरः।
गुहामाश्रयशैलस्य दुर्गां पादपसंकुलाम्॥', 'tasmād gṛhītvā vaidehīṃ śarapāṇir dhanurdharaḥ
guhām āśrayaśailasya durgāṃ pādapasaṃkulām', null, 3023011),
('ramayana-3-23-12', 12, 'Aranya Kanda, Sarga 23, Verse 12', 'प्रतिकूलितुमिच्छामि न हि वाक्यमिदं त्वया।
शापितो मम पादाभ्यां गम्यतां वत्स माचिरम्॥', 'pratikūlitum icchāmi na hi vākyam idaṃ tvayā
śāpito mama pādābhyāṃ gamyatāṃ vatsa māciram', null, 3023012),
('ramayana-3-23-13', 13, 'Aranya Kanda, Sarga 23, Verse 13', 'एवमुक्तस्तु रामेण लक्ष्मणः सह सीतया।
शरानादाय चापं च गुहां दुर्गां समाश्रयत्॥', 'evam uktas tu rāmeṇa lakṣmaṇaḥ saha sītayā
śarān ādāya cāpaṃ ca guhāṃ durgāṃ samāśrayat', null, 3023013),
('ramayana-3-23-14', 14, 'Aranya Kanda, Sarga 23, Verse 14', 'तस्मिन्प्रविष्टे तु गुहां लक्ष्मणे सह सीतया।
हन्त निर्युक्तमित्युक्त्वा रामः कवचमाविशत्॥', 'tasmin praviṣṭe tu guhāṃ lakṣmaṇe saha sītayā
hanta niryuktam ity uktvā rāmaḥ kavacam āviśat', null, 3023014),
('ramayana-3-23-15', 15, 'Aranya Kanda, Sarga 23, Verse 15', 'सा तेनाग्निनिकाशेन कवचेन विभूषितः।
बभूव रामस्तिमिरे विधूमोऽग्निरिवोत्थितः॥', 'sā tenāgninikāśena kavacena vibhūṣitaḥ
babhūva rāmas timire vidhūmo ''gnir ivotthitaḥ', null, 3023015),
('ramayana-3-23-16', 16, 'Aranya Kanda, Sarga 23, Verse 16', 'स चापमुद्यम्य महच्छरानादाय वीर्यवान्।
बभूवावस्थितस्तत्र ज्यास्वनैः पूरयन्दिशः॥', 'sa cāpam udyamya mahac charān ādāya vīryavān
babhūvāvasthitas tatra jyāsvanaiḥ pūrayan diśaḥ', null, 3023016),
('ramayana-3-23-17', 17, 'Aranya Kanda, Sarga 23, Verse 17', 'ततो देवाः सगन्धर्वाः सिद्धाश्च सह चारणैः।
ऊचुः परमसंत्रस्ता गुह्यकाश्च परस्परम्॥', 'tato devāḥ sagandharvāḥ siddhāś ca saha cāraṇaiḥ
ūcuḥ paramasaṃtrastā guhyakāś ca parasparam', null, 3023017),
('ramayana-3-23-18', 18, 'Aranya Kanda, Sarga 23, Verse 18', 'चतुर्दश सहस्राणि रक्षसां भीमकर्मणाम्।
एकश्च रामो धर्मात्मा कथं युद्धं भविष्यति॥', 'caturdaśa sahasrāṇi rakṣasāṃ bhīmakarmaṇām
ekaś ca rāmo dharmātmā kathaṃ yuddhaṃ bhaviṣyati', null, 3023018),
('ramayana-3-23-19', 19, 'Aranya Kanda, Sarga 23, Verse 19', 'ततो गम्भीरनिर्ह्रादं घोरवर्मायुधध्वजम्।
अनीकं यातुधानानां समन्तात्प्रत्यदृश्यत॥', 'tato gambhīranirhrādaṃ ghoravarmāyudhadhvajam
anīkaṃ yātudhānānāṃ samantāt pratyadṛśyata', null, 3023019),
('ramayana-3-23-20', 20, 'Aranya Kanda, Sarga 23, Verse 20', 'सिंहनादं विसृजतामन्योन्यमभिगर्जताम्।
चापानि विस्फरयतां जृम्भतां चाप्यभीक्ष्णशः॥', 'siṃhanādaṃ visṛjatām anyonyam abhigarjatām
cāpāni vispharayatāṃ jṛmbhatāṃ cāpy abhīkṣṇaśaḥ', null, 3023020),
('ramayana-3-23-21', 21, 'Aranya Kanda, Sarga 23, Verse 21', 'विप्रघुष्टस्वनानां च दुन्दुभींश्चापि निघ्नताम्।
तेषां सुतुमुलः शब्दः पूरयामास तद्वनम्॥', 'vipraghuṣṭasvanānāṃ ca dundubhīṃś cāpi nighnatām
teṣāṃ sutumulaḥ śabdaḥ pūrayām āsa tad vanam', null, 3023021),
('ramayana-3-23-22', 22, 'Aranya Kanda, Sarga 23, Verse 22', 'तेन शब्देन वित्रस्ताः श्वापदा वनचारिणः।
दुद्रुवुर्यत्र निःशब्दं पृष्ठतो नावलोकयन्॥', 'tena śabdena vitrastāḥ śvāpadā vanacāriṇaḥ
dudruvur yatra niḥśabdaṃ pṛṣṭhato nāvalokayan', null, 3023022),
('ramayana-3-23-23', 23, 'Aranya Kanda, Sarga 23, Verse 23', 'तत्त्वनीकं महावेगं रामं समुपसर्पत।
घृतनानाप्रहरणं गम्भीरं सागरोपमम्॥', 'tat tv anīkaṃ mahāvegaṃ rāmaṃ samupasarpata
ghṛtanānāpraharaṇaṃ gambhīraṃ sāgaropamam', null, 3023023),
('ramayana-3-23-24', 24, 'Aranya Kanda, Sarga 23, Verse 24', 'रामोऽपि चारयंश्चक्षुः सर्वतो रणपण्डितः।
ददर्श खरसैन्यं तद्युद्धाभिमुखमुद्यतम्॥', 'rāmo ''pi cārayaṃś cakṣuḥ sarvato raṇapaṇḍitaḥ
dadarśa kharasainyaṃ tad yuddhābhimukham udyatam', null, 3023024),
('ramayana-3-23-25', 25, 'Aranya Kanda, Sarga 23, Verse 25', 'वितत्य च धनुर्भीमं तूण्याश्चोद्धृत्य सायकान्।
क्रोधमाहारयत्तीव्रं वधार्थं सर्वरक्षसाम्॥', 'vitatya ca dhanur bhīmaṃ tūṇyāś coddhṛtya sāyakān
krodham āhārayat tīvraṃ vadhārthaṃ sarvarakṣasām', null, 3023025),
('ramayana-3-23-26', 26, 'Aranya Kanda, Sarga 23, Verse 26', 'दुष्प्रेक्ष्यः सोऽभवत्क्रुद्धो युगान्ताग्निरिव ज्वलन्।
तं दृष्ट्वा तेजसाविष्टं प्राव्यथन्वनदेवताः॥', 'duṣprekṣyaḥ so ''bhavat kruddho yugāntāgnir iva jvalan
taṃ dṛṣṭvā tejasāviṣṭaṃ prāvyathan vanadevatāḥ', null, 3023026),
('ramayana-3-23-27', 27, 'Aranya Kanda, Sarga 23, Verse 27', 'तस्य क्रुद्धस्य रूपं तु रामस्य ददृशे तदा।
दक्षस्येव क्रतुं हन्तुमुद्यतस्य पिनाकिनः॥', 'tasya kruddhasya rūpaṃ tu rāmasya dadṛśe tadā
dakṣasyeva kratuṃ hantum udyatasya pinākinaḥ', null, 3023027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 24 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-24-1', 1, 'Aranya Kanda, Sarga 24, Verse 1', 'अवष्टब्धधनुं रामं क्रुद्धं च रिपुघातिनम्।
ददर्शाश्रममागम्य खरः सह पुरःसरैः॥', 'avaṣṭabdhadhanuṃ rāmaṃ kruddhaṃ ca ripughātinam
dadarśāśramam āgamya kharaḥ saha puraḥsaraiḥ', null, 3024001),
('ramayana-3-24-2', 2, 'Aranya Kanda, Sarga 24, Verse 2', 'तं दृष्ट्वा सगुणं चापमुद्यम्य खरनिःस्वनम्।
रामस्याभिमुखं सूतं चोद्यतामित्यचोदयत्॥', 'taṃ dṛṣṭvā saguṇaṃ cāpam udyamya kharaniḥsvanam
rāmasyābhimukhaṃ sūtaṃ codyatām ity acodayat', null, 3024002),
('ramayana-3-24-3', 3, 'Aranya Kanda, Sarga 24, Verse 3', 'स खरस्याज्ञया सूतस्तुरगान्समचोदयत्।
यत्र रामो महाबाहुरेको धुन्वन्धनुः स्थितः॥', 'sa kharasyājñayā sūtas turagān samacodayat
yatra rāmo mahābāhur eko dhunvan dhanuḥ sthitaḥ', null, 3024003),
('ramayana-3-24-4', 4, 'Aranya Kanda, Sarga 24, Verse 4', 'तं तु निष्पतितं दृष्ट्वा सर्वे ते रजनीचराः।
नर्दमाना महानादं सचिवाः पर्यवारयन्॥', 'taṃ tu niṣpatitaṃ dṛṣṭvā sarve te rajanīcarāḥ
nardamānā mahānādaṃ sacivāḥ paryavārayan', null, 3024004),
('ramayana-3-24-5', 5, 'Aranya Kanda, Sarga 24, Verse 5', 'स तेषां यातुधानानां मध्ये रतो गतः खरः।
बभूव मध्ये ताराणां लोहिताङ्ग इवोदितः॥', 'sa teṣāṃ yātudhānānāṃ madhye rato gataḥ kharaḥ
babhūva madhye tārāṇāṃ lohitāṅga ivoditaḥ', null, 3024005),
('ramayana-3-24-6', 6, 'Aranya Kanda, Sarga 24, Verse 6', 'ततस्तं भीमधन्वानं क्रुद्धाः सर्वे निशाचराः।
रामं नानाविधैः शस्त्रैरभ्यवर्षन्त दुर्जयम्॥', 'tatas taṃ bhīmadhanvānaṃ kruddhāḥ sarve niśācarāḥ
rāmaṃ nānāvidhaiḥ śastrair abhyavarṣanta durjayam', null, 3024006),
('ramayana-3-24-7', 7, 'Aranya Kanda, Sarga 24, Verse 7', 'मुद्गरैरायसैः शूलैः प्रासैः खड्गैः परश्वधैः।
राक्षसाः समरे रामं निजघ्नू रोषतत्पराः॥', 'mudgarair āyasaiḥ śūlaiḥ prāsaiḥ khaḍgaiḥ paraśvadhaiḥ
rākṣasāḥ samare rāmaṃ nijaghnū roṣatatparāḥ', null, 3024007),
('ramayana-3-24-8', 8, 'Aranya Kanda, Sarga 24, Verse 8', 'ते बलाहकसंकाशा महानादा महाबलाः।
अभ्यधावन्त काकुत्स्थं रामं युद्धे जिघांसवः॥', 'te balāhakasaṃkāśā mahānādā mahābalāḥ
abhyadhāvanta kākutsthaṃ rāmaṃ yuddhe jighāṃsavaḥ', null, 3024008),
('ramayana-3-24-9', 9, 'Aranya Kanda, Sarga 24, Verse 9', 'ते रामे शरवर्षाणि व्यसृजन्रक्षसां गुणाः।
शैलेन्द्रमिव धाराभिर्वर्षमाणा महाधनाः॥', 'te rāme śaravarṣāṇi vyasṛjan rakṣasāṃ guṇāḥ
śailendram iva dhārābhir varṣamāṇā mahādhanāḥ', null, 3024009),
('ramayana-3-24-10', 10, 'Aranya Kanda, Sarga 24, Verse 10', 'स तैः परिवृतो घोरै राघवो रक्षसां गणैः।
तिथिष्विव महादेवो वृतः पारिषदां गणैः॥', 'sa taiḥ parivṛto ghorai rāghavo rakṣasāṃ gaṇaiḥ
tithiṣv iva mahādevo vṛtaḥ pāriṣadāṃ gaṇaiḥ', null, 3024010),
('ramayana-3-24-11', 11, 'Aranya Kanda, Sarga 24, Verse 11', 'तानि मुक्तानि शस्त्राणि यातुधानैः स राघवः।
प्रतिजग्राह विशिखैर्नद्योघानिव सागरः॥', 'tāni muktāni śastrāṇi yātudhānaiḥ sa rāghavaḥ
pratijagrāha viśikhair nadyoghān iva sāgaraḥ', null, 3024011),
('ramayana-3-24-12', 12, 'Aranya Kanda, Sarga 24, Verse 12', 'स तैः प्रहरणैर्घोरैर्भिन्नगात्रो न विव्यथे।
रामः प्रदीप्तैर्बहुभिर्वज्रैरिव महाचलः॥', 'sa taiḥ praharaṇair ghorair bhinnagātro na vivyathe
rāmaḥ pradīptair bahubhir vajrair iva mahācalaḥ', null, 3024012),
('ramayana-3-24-13', 13, 'Aranya Kanda, Sarga 24, Verse 13', 'स विद्धः क्षतजादिग्धः सर्वगात्रेषु राघवः।
बभूव रामः संध्याभ्रैर्दिवाकर इवावृतः॥', 'sa viddhaḥ kṣatajādigdhaḥ sarvagātreṣu rāghavaḥ
babhūva rāmaḥ saṃdhyābhrair divākara ivāvṛtaḥ', null, 3024013),
('ramayana-3-24-14', 14, 'Aranya Kanda, Sarga 24, Verse 14', 'विषेदुर्देवगन्धर्वाः सिद्धाश्च परमर्षयः।
एकं सहस्त्रैर्बहुभिस्तदा दृष्ट्वा समावृतम्॥', 'viṣedur devagandharvāḥ siddhāś ca paramarṣayaḥ
ekaṃ sahastrair bahubhis tadā dṛṣṭvā samāvṛtam', null, 3024014),
('ramayana-3-24-15', 15, 'Aranya Kanda, Sarga 24, Verse 15', 'ततो रामः सुसंक्रुद्धो मण्डलीकृतकार्मुकः।
ससर्ज निशितान्बाणाञ्शतशोऽथ सहस्रशः॥', 'tato rāmaḥ susaṃkruddho maṇḍalīkṛtakārmukaḥ
sasarja niśitān bāṇāñ śataśo ''tha sahasraśaḥ', null, 3024015),
('ramayana-3-24-16', 16, 'Aranya Kanda, Sarga 24, Verse 16', 'दुरावारान्दुर्विषहान्कालपाशोपमान्रणे।
मुमोच लीलया रामः कङ्कपत्रानजिह्मगान्॥', 'durāvārān durviṣahān kālapāśopamān raṇe
mumoca līlayā rāmaḥ kaṅkapatrān ajihmagān', null, 3024016),
('ramayana-3-24-17', 17, 'Aranya Kanda, Sarga 24, Verse 17', 'ते शराः शत्रुसैन्येषु मुक्ता रामेण लीलया।
आददू रक्षसां प्राणान्पाशाः कालकृता इव॥', 'te śarāḥ śatrusainyeṣu muktā rāmeṇa līlayā
ādadū rakṣasāṃ prāṇān pāśāḥ kālakṛtā iva', null, 3024017),
('ramayana-3-24-18', 18, 'Aranya Kanda, Sarga 24, Verse 18', 'भित्त्वा राक्षसदेहांस्तांस्ते शरा रुधिराप्लुताः।
अन्तरिक्षगता रेजुर्दीप्ताग्निसमतेजसः॥', 'bhittvā rākṣasadehāṃs tāṃs te śarā rudhirāplutāḥ
antarikṣagatā rejur dīptāgnisamatejasaḥ', null, 3024018),
('ramayana-3-24-19', 19, 'Aranya Kanda, Sarga 24, Verse 19', 'असंख्येयास्तु रामस्य सायकाश्चापमण्डलात्।
विनिष्पेतुरतीवोग्रा रक्षः प्राणापहारिणः॥', 'asaṃkhyeyās tu rāmasya sāyakāś cāpamaṇḍalāt
viniṣpetur atīvogrā rakṣaḥ prāṇāpahāriṇaḥ', null, 3024019),
('ramayana-3-24-20', 20, 'Aranya Kanda, Sarga 24, Verse 20', 'तैर्धनूंषि ध्वजाग्राणि वर्माणि च शिरांसि च।
बहून्सहस्ताभरणानूरून्करिकरोपमान्॥', 'tair dhanūṃṣi dhvajāgrāṇi varmāṇi ca śirāṃsi ca
bahūn sahastābharaṇān ūrūn karikaropamān', null, 3024020),
('ramayana-3-24-21', 21, 'Aranya Kanda, Sarga 24, Verse 21', 'ततो नालीकनाराचैस्तीक्ष्णाग्रैश्च विकर्णिभिः।
भीममार्तस्वरं चक्रुर्भिद्यमाना निशाचराः॥', 'tato nālīkanārācais tīkṣṇāgraiś ca vikarṇibhiḥ
bhīmam ārtasvaraṃ cakrur bhidyamānā niśācarāḥ', null, 3024021),
('ramayana-3-24-22', 22, 'Aranya Kanda, Sarga 24, Verse 22', 'तत्सैन्यं निशितैर्बाणैरर्दितं मर्मभेदिभिः।
रामेण न सुखं लेभे शुष्कं वनमिवाग्निना॥', 'tat sainyaṃ niśitair bāṇair arditaṃ marmabhedibhiḥ
rāmeṇa na sukhaṃ lebhe śuṣkaṃ vanam ivāgninā', null, 3024022),
('ramayana-3-24-23', 23, 'Aranya Kanda, Sarga 24, Verse 23', 'के चिद्भीमबलाः शूराः शूलान्खड्गान्परश्वधान्।
चिक्षिपुः परमक्रुद्धा रामाय रजनीचराः॥', 'ke cid bhīmabalāḥ śūrāḥ śūlān khaḍgān paraśvadhān
cikṣipuḥ paramakruddhā rāmāya rajanīcarāḥ', null, 3024023),
('ramayana-3-24-24', 24, 'Aranya Kanda, Sarga 24, Verse 24', 'तानि बाणैर्महाबाहुः शस्त्राण्यावार्य राघवः।
जहार समरे प्राणांश्चिच्छेद च शिरोधरान्॥', 'tāni bāṇair mahābāhuḥ śastrāṇy āvārya rāghavaḥ
jahāra samare prāṇāṃś ciccheda ca śirodharān', null, 3024024),
('ramayana-3-24-25', 25, 'Aranya Kanda, Sarga 24, Verse 25', 'अवशिष्टाश्च ये तत्र विषण्णाश्च निशाचराः।
खरमेवाभ्यधावन्त शरणार्थं शरार्दिताः॥', 'avaśiṣṭāś ca ye tatra viṣaṇṇāś ca niśācarāḥ
kharam evābhyadhāvanta śaraṇārthaṃ śarārditāḥ', null, 3024025),
('ramayana-3-24-26', 26, 'Aranya Kanda, Sarga 24, Verse 26', 'तान्सर्वान्पुनरादाय समाश्वास्य च दूषणः।
अभ्यधावत काकुत्स्थं क्रुद्धो रुद्रमिवान्तकः॥', 'tān sarvān punar ādāya samāśvāsya ca dūṣaṇaḥ
abhyadhāvata kākutsthaṃ kruddho rudram ivāntakaḥ', null, 3024026),
('ramayana-3-24-27', 27, 'Aranya Kanda, Sarga 24, Verse 27', 'निवृत्तास्तु पुनः सर्वे दूषणाश्रयनिर्भयाः।
राममेवाभ्यधावन्त सालतालशिलायुधाः॥', 'nivṛttās tu punaḥ sarve dūṣaṇāśrayanirbhayāḥ
rāmam evābhyadhāvanta sālatālaśilāyudhāḥ', null, 3024027),
('ramayana-3-24-28', 28, 'Aranya Kanda, Sarga 24, Verse 28', 'तद्बभूवाद्भुतं युद्धं तुमुलं रोमहर्षणम्।
रामस्यास्य महाघोरं पुनस्तेषां च रक्षसाम्॥', 'tad babhūvādbhutaṃ yuddhaṃ tumulaṃ romaharṣaṇam
rāmasyāsya mahāghoraṃ punas teṣāṃ ca rakṣasām', null, 3024028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 25 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-25-1', 1, 'Aranya Kanda, Sarga 25, Verse 1', 'तद्द्रुमाणां शिलानां च वर्षं प्राणहरं महत्।
प्रतिजग्राह धर्मात्मा राघवस्तीक्ष्णसायकैः॥', 'tad drumāṇāṃ śilānāṃ ca varṣaṃ prāṇaharaṃ mahat
pratijagrāha dharmātmā rāghavas tīkṣṇasāyakaiḥ', null, 3025001),
('ramayana-3-25-2', 2, 'Aranya Kanda, Sarga 25, Verse 2', 'प्रतिगृह्य च तद्वरं निमीलित इवर्षभः।
रामः क्रोधं परं भेजे वधार्थं सर्वरक्षसाम्॥', 'pratigṛhya ca tad varaṃ nimīlita ivarṣabhaḥ
rāmaḥ krodhaṃ paraṃ bheje vadhārthaṃ sarvarakṣasām', null, 3025002),
('ramayana-3-25-3', 3, 'Aranya Kanda, Sarga 25, Verse 3', 'ततः क्रोधसमाविष्टः प्रदीप्त इव तेजसा।
शरैरभ्यकिरत्सैन्यं सर्वतः सहदूषणम्॥', 'tataḥ krodhasamāviṣṭaḥ pradīpta iva tejasā
śarair abhyakirat sainyaṃ sarvataḥ sahadūṣaṇam', null, 3025003),
('ramayana-3-25-4', 4, 'Aranya Kanda, Sarga 25, Verse 4', 'ततः सेनापतिः क्रुद्धो दूषणः शत्रुदूषणः।
जग्राह गिरिशृङ्गाभं परिघं रोमहर्षणम्॥', 'tataḥ senāpatiḥ kruddho dūṣaṇaḥ śatrudūṣaṇaḥ
jagrāha giriśṛṅgābhaṃ parighaṃ romaharṣaṇam', null, 3025004),
('ramayana-3-25-5', 5, 'Aranya Kanda, Sarga 25, Verse 5', 'वेष्टितं काञ्चनैः पट्टैर्देवसैन्याभिमर्दनम्।
आयसैः शङ्कुभिस्तीक्ष्णैः कीर्णं परवसोक्षिताम्॥', 'veṣṭitaṃ kāñcanaiḥ paṭṭair devasainyābhimardanam
āyasaiḥ śaṅkubhis tīkṣṇaiḥ kīrṇaṃ paravasokṣitām', null, 3025005),
('ramayana-3-25-6', 6, 'Aranya Kanda, Sarga 25, Verse 6', 'वज्राशनिसमस्पर्शं परगोपुरदारणम्।
तं महोरगसंकाशं प्रगृह्य परिघं रणे।
दूषणोऽभ्यपतद्रामं क्रूरकर्मा निशाचरः॥', 'vajrāśanisamasparśaṃ paragopuradāraṇam
taṃ mahoragasaṃkāśaṃ pragṛhya parighaṃ raṇe
dūṣaṇo ''bhyapatad rāmaṃ krūrakarmā niśācaraḥ', null, 3025006),
('ramayana-3-25-7', 7, 'Aranya Kanda, Sarga 25, Verse 7', 'तस्याभिपतमानस्य दूषणस्य स राघवः।
द्वाभ्यां शराभ्यां चिच्छेद सहस्ताभरणौ भुजौ॥', 'tasyābhipatamānasya dūṣaṇasya sa rāghavaḥ
dvābhyāṃ śarābhyāṃ ciccheda sahastābharaṇau bhujau', null, 3025007),
('ramayana-3-25-8', 8, 'Aranya Kanda, Sarga 25, Verse 8', 'भ्रष्टस्तस्य महाकायः पपात रणमूर्धनि।
परिघश्छिन्नहस्तस्य शक्रध्वज इवाग्रतः॥', 'bhraṣṭas tasya mahākāyaḥ papāta raṇamūrdhani
parighaś chinnahastasya śakradhvaja ivāgrataḥ', null, 3025008),
('ramayana-3-25-9', 9, 'Aranya Kanda, Sarga 25, Verse 9', 'स कराभ्यां विकीर्णाभ्यां पपात भुवि दूषणः।
विषाणाभ्यां विशीर्णाभ्यां मनस्वीव महागजः॥', 'sa karābhyāṃ vikīrṇābhyāṃ papāta bhuvi dūṣaṇaḥ
viṣāṇābhyāṃ viśīrṇābhyāṃ manasvīva mahāgajaḥ', null, 3025009),
('ramayana-3-25-10', 10, 'Aranya Kanda, Sarga 25, Verse 10', 'दृष्ट्वा तं पतितं भूमौ दूषणं निहतं रणे।
साधु साध्विति काकुत्स्थं सर्वभूतान्यपूजयन्॥', 'dṛṣṭvā taṃ patitaṃ bhūmau dūṣaṇaṃ nihataṃ raṇe
sādhu sādhv iti kākutsthaṃ sarvabhūtāny apūjayan', null, 3025010),
('ramayana-3-25-11', 11, 'Aranya Kanda, Sarga 25, Verse 11', 'एतस्मिन्नन्तरे क्रुद्धास्त्रयः सेनाग्रयायिनः।
संहत्याभ्यद्रवन्रामं मृत्युपाशावपाशिताः।
महाकपालः स्थूलाक्षः प्रमाथी च महाबलः॥', 'etasminn antare kruddhās trayaḥ senāgrayāyinaḥ
saṃhatyābhyadravan rāmaṃ mṛtyupāśāvapāśitāḥ
mahākapālaḥ sthūlākṣaḥ pramāthī ca mahābalaḥ', null, 3025011),
('ramayana-3-25-12', 12, 'Aranya Kanda, Sarga 25, Verse 12', 'महाकपालो विपुलं शूलमुद्यम्य राक्षसः।
स्थूलाक्षः पट्टिशं गृह्य प्रमाथी च परश्वधम्॥', 'mahākapālo vipulaṃ śūlam udyamya rākṣasaḥ
sthūlākṣaḥ paṭṭiśaṃ gṛhya pramāthī ca paraśvadham', null, 3025012),
('ramayana-3-25-13', 13, 'Aranya Kanda, Sarga 25, Verse 13', 'दृष्ट्वैवापततस्तांस्तु राघवः सायकैः शितैः।
तीक्ष्णाग्रैः प्रतिजग्राह संप्राप्तानतिथीनिव॥', 'dṛṣṭvaivāpatatas tāṃs tu rāghavaḥ sāyakaiḥ śitaiḥ
tīkṣṇāgraiḥ pratijagrāha saṃprāptān atithīn iva', null, 3025013),
('ramayana-3-25-14', 14, 'Aranya Kanda, Sarga 25, Verse 14', 'महाकपालस्य शिरश्चिच्छेद रघुनङ्गनः।
असंख्येयैस्तु बाणौघैः प्रममाथ प्रमाथिनम्॥', 'mahākapālasya śiraś ciccheda raghunaṅganaḥ
asaṃkhyeyais tu bāṇaughaiḥ pramamātha pramāthinam', null, 3025014),
('ramayana-3-25-15', 15, 'Aranya Kanda, Sarga 25, Verse 15', 'स्थूलाक्षस्याक्षिणी तीक्ष्णैः पूरयामास सायकैः।
स पपात हतो भूमौ विटपीव महाद्रुमः॥', 'sthūlākṣasyākṣiṇī tīkṣṇaiḥ pūrayām āsa sāyakaiḥ
sa papāta hato bhūmau viṭapīva mahādrumaḥ', null, 3025015),
('ramayana-3-25-16', 16, 'Aranya Kanda, Sarga 25, Verse 16', 'ततः पावकसंकाशैर्हेमवज्रविभूषितैः।
जघनशेषं तेजस्वी तस्य सैन्यस्य सायकैः॥', 'tataḥ pāvakasaṃkāśair hemavajravibhūṣitaiḥ
jaghanaśeṣaṃ tejasvī tasya sainyasya sāyakaiḥ', null, 3025016),
('ramayana-3-25-17', 17, 'Aranya Kanda, Sarga 25, Verse 17', 'ते रुक्मपुङ्खा विशिखाः सधूमा इव पावकाः।
निजघ्नुस्तानि रक्षांसि वज्रा इव महाद्रुमान्॥', 'te rukmapuṅkhā viśikhāḥ sadhūmā iva pāvakāḥ
nijaghnus tāni rakṣāṃsi vajrā iva mahādrumān', null, 3025017),
('ramayana-3-25-18', 18, 'Aranya Kanda, Sarga 25, Verse 18', 'रक्षसां तु शतं रामः शतेनैकेन कर्णिना।
सहस्रं च सहस्रेण जघान रणमूर्धनि॥', 'rakṣasāṃ tu śataṃ rāmaḥ śatenaikena karṇinā
sahasraṃ ca sahasreṇa jaghāna raṇamūrdhani', null, 3025018),
('ramayana-3-25-19', 19, 'Aranya Kanda, Sarga 25, Verse 19', 'तैर्भिन्नवर्माभरणाश्छिन्नभिन्नशरासनाः।
निपेतुः शोणितादिग्धा धरण्यां रजनीचराः॥', 'tair bhinnavarmābharaṇāś chinnabhinnaśarāsanāḥ
nipetuḥ śoṇitādigdhā dharaṇyāṃ rajanīcarāḥ', null, 3025019),
('ramayana-3-25-20', 20, 'Aranya Kanda, Sarga 25, Verse 20', 'तैर्मुक्तकेशैः समरे पतितैः शोणितोक्षितैः।
आस्तीर्णा वसुधा कृत्स्ना महावेदिः कुशैरिव॥', 'tair muktakeśaiḥ samare patitaiḥ śoṇitokṣitaiḥ
āstīrṇā vasudhā kṛtsnā mahāvediḥ kuśair iva', null, 3025020),
('ramayana-3-25-21', 21, 'Aranya Kanda, Sarga 25, Verse 21', 'क्षणेन तु महाघोरं वनं निहतराक्षसं।
बभूव निरय प्रख्यं मांसशोणितकर्दमम्॥', 'kṣaṇena tu mahāghoraṃ vanaṃ nihatarākṣasaṃ
babhūva niraya prakhyaṃ māṃsaśoṇitakardamam', null, 3025021),
('ramayana-3-25-22', 22, 'Aranya Kanda, Sarga 25, Verse 22', 'चतुर्दश सहस्राणि रक्षसां भीमकर्मणाम्।
हतान्येकेन रामेण मानुषेण पदातिना॥', 'caturdaśa sahasrāṇi rakṣasāṃ bhīmakarmaṇām
hatāny ekena rāmeṇa mānuṣeṇa padātinā', null, 3025022),
('ramayana-3-25-23', 23, 'Aranya Kanda, Sarga 25, Verse 23', 'तस्य सैन्यस्य सर्वस्य खरः शेषो महारथः।
राक्षसस्त्रिशिराश्चैव रामश्च रिपुसूदनः॥', 'tasya sainyasya sarvasya kharaḥ śeṣo mahārathaḥ
rākṣasas triśirāś caiva rāmaś ca ripusūdanaḥ', null, 3025023),
('ramayana-3-25-24', 24, 'Aranya Kanda, Sarga 25, Verse 24', 'ततस्तु तद्भीमबलं महाहवे समीक्ष्य रामेण हतं बलीयसा।
रथेन रामं महता खरस्ततः समाससादेन्द्र इवोद्यताशनिः॥', 'tatas tu tad bhīmabalaṃ mahāhave samīkṣya rāmeṇa hataṃ balīyasā
rathena rāmaṃ mahatā kharas tataḥ samāsasādendra ivodyatāśaniḥ', null, 3025024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 26 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-26-1', 1, 'Aranya Kanda, Sarga 26, Verse 1', 'खरं तु रामाभिमुखं प्रयान्तं वाहिनीपतिः।
राक्षसस्त्रिशिरा नाम संनिपत्येदमब्रवीत्॥', 'kharaṃ tu rāmābhimukhaṃ prayāntaṃ vāhinīpatiḥ
rākṣasas triśirā nāma saṃnipatyedam abravīt', null, 3026001),
('ramayana-3-26-2', 2, 'Aranya Kanda, Sarga 26, Verse 2', 'मां नियोजय विक्रान्त संनिवर्तस्व साहसात्।
पश्य रामं महाबाहुं संयुगे विनिपातितम्॥', 'māṃ niyojaya vikrānta saṃnivartasva sāhasāt
paśya rāmaṃ mahābāhuṃ saṃyuge vinipātitam', null, 3026002),
('ramayana-3-26-3', 3, 'Aranya Kanda, Sarga 26, Verse 3', 'प्रतिजानामि ते सत्यमायुधं चाहमालभे।
यथा रामं वधिष्यामि वधार्हं सर्वरक्षसाम्॥', 'pratijānāmi te satyam āyudhaṃ cāham ālabhe
yathā rāmaṃ vadhiṣyāmi vadhārhaṃ sarvarakṣasām', null, 3026003),
('ramayana-3-26-4', 4, 'Aranya Kanda, Sarga 26, Verse 4', 'अहं वास्य रणे मृत्युरेष वा समरे मम।
विनिवर्त्य रणोत्साहं मुहूर्तं प्राश्निको भव॥', 'ahaṃ vāsya raṇe mṛtyur eṣa vā samare mama
vinivartya raṇotsāhaṃ muhūrtaṃ prāśniko bhava', null, 3026004),
('ramayana-3-26-5', 5, 'Aranya Kanda, Sarga 26, Verse 5', 'प्रहृष्टो वा हते रामे जनस्थानं प्रयास्यसि।
मयि वा निहते रामं संयुगायोपयास्यसि॥', 'prahṛṣṭo vā hate rāme janasthānaṃ prayāsyasi
mayi vā nihate rāmaṃ saṃyugāyopayāsyasi', null, 3026005),
('ramayana-3-26-6', 6, 'Aranya Kanda, Sarga 26, Verse 6', 'खरस्त्रिशिरसा तेन मृत्युलोभात्प्रसादितः।
गच्छ युध्येत्यनुज्ञातो राघवाभिमुखो ययौ॥', 'kharas triśirasā tena mṛtyulobhāt prasāditaḥ
gaccha yudhyety anujñāto rāghavābhimukho yayau', null, 3026006),
('ramayana-3-26-7', 7, 'Aranya Kanda, Sarga 26, Verse 7', 'त्रिशिराश्च रथेनैव वाजियुक्तेन भास्वता।
अभ्यद्रवद्रणे रामं त्रिशृङ्ग इव पर्वतः॥', 'triśirāś ca rathenaiva vājiyuktena bhāsvatā
abhyadravad raṇe rāmaṃ triśṛṅga iva parvataḥ', null, 3026007),
('ramayana-3-26-8', 8, 'Aranya Kanda, Sarga 26, Verse 8', 'शरधारा समूहान्स महामेघ इवोत्सृजन्।
व्यसृजत्सदृशं नादं जलार्द्रस्येव दुन्दुभेः॥', 'śaradhārā samūhān sa mahāmegha ivotsṛjan
vyasṛjat sadṛśaṃ nādaṃ jalārdrasyeva dundubheḥ', null, 3026008),
('ramayana-3-26-9', 9, 'Aranya Kanda, Sarga 26, Verse 9', 'आगच्छन्तं त्रिशिरसं राक्षसं प्रेक्ष्य राघवः।
धनुषा प्रतिजग्राह विधुन्वन्सायकाञ्शितान्॥', 'āgacchantaṃ triśirasaṃ rākṣasaṃ prekṣya rāghavaḥ
dhanuṣā pratijagrāha vidhunvan sāyakāñ śitān', null, 3026009),
('ramayana-3-26-10', 10, 'Aranya Kanda, Sarga 26, Verse 10', 'स संप्रहारस्तुमुलो राम त्रिशिरसोर्महान्।
बभूवातीव बलिनोः सिंहकुञ्जरयोरिव॥', 'sa saṃprahāras tumulo rāma triśirasor mahān
babhūvātīva balinoḥ siṃhakuñjarayor iva', null, 3026010),
('ramayana-3-26-11', 11, 'Aranya Kanda, Sarga 26, Verse 11', 'ततस्त्रिशिरसा बाणैर्ललाटे ताडितस्त्रिभिः।
अमर्षी कुपितो रामः संरब्धमिदमब्रवीत्॥', 'tatas triśirasā bāṇair lalāṭe tāḍitas tribhiḥ
amarṣī kupito rāmaḥ saṃrabdham idam abravīt', null, 3026011),
('ramayana-3-26-12', 12, 'Aranya Kanda, Sarga 26, Verse 12', 'अहो विक्रमशूरस्य राक्षसस्येदृशं बलम्।
पुष्पैरिव शरैर्यस्य ललाटेऽस्मि परिक्षतः।
ममापि प्रतिगृह्णीष्व शरांश्चापगुणच्युतान्॥', 'aho vikramaśūrasya rākṣasasyedṛśaṃ balam
puṣpair iva śarair yasya lalāṭe ''smi parikṣataḥ
mamāpi pratigṛhṇīṣva śarāṃś cāpaguṇacyutān', null, 3026012),
('ramayana-3-26-13', 13, 'Aranya Kanda, Sarga 26, Verse 13', 'एवमुक्त्वा तु संरब्धः शरानाशीविषोपमान्।
त्रिशिरो वक्षसि क्रुद्धो निजघान चतुर्दश॥', 'evam uktvā tu saṃrabdhaḥ śarān āśīviṣopamān
triśiro vakṣasi kruddho nijaghāna caturdaśa', null, 3026013),
('ramayana-3-26-14', 14, 'Aranya Kanda, Sarga 26, Verse 14', 'चतुर्भिस्तुरगानस्य शरैः संनतपर्वभिः।
न्यपातयत तेजस्वी चतुरस्तस्य वाजिनः॥', 'caturbhis turagān asya śaraiḥ saṃnataparvabhiḥ
nyapātayata tejasvī caturas tasya vājinaḥ', null, 3026014),
('ramayana-3-26-15', 15, 'Aranya Kanda, Sarga 26, Verse 15', 'अष्टभिः सायकैः सूतं रथोपस्थे न्यपातयत्।
रामश्चिच्छेद बाणेन ध्वजं चास्य समुच्छ्रितम्॥', 'aṣṭabhiḥ sāyakaiḥ sūtaṃ rathopasthe nyapātayat
rāmaś ciccheda bāṇena dhvajaṃ cāsya samucchritam', null, 3026015),
('ramayana-3-26-16', 16, 'Aranya Kanda, Sarga 26, Verse 16', 'ततो हतरथात्तस्मादुत्पतन्तं निशाचरम्।
बिभेद रामस्तं बाणैर्हृदये सोऽभवज्जडः॥', 'tato hatarathāt tasmād utpatantaṃ niśācaram
bibheda rāmas taṃ bāṇair hṛdaye so ''bhavaj jaḍaḥ', null, 3026016),
('ramayana-3-26-17', 17, 'Aranya Kanda, Sarga 26, Verse 17', 'सायकैश्चाप्रमेयात्मा सामर्षस्तस्य रक्षसः।
शिरांस्यपातयत्त्रीणि वेगवद्भिस्त्रिभिः शतैः॥', 'sāyakaiś cāprameyātmā sāmarṣas tasya rakṣasaḥ
śirāṃsy apātayat trīṇi vegavadbhis tribhiḥ śataiḥ', null, 3026017),
('ramayana-3-26-18', 18, 'Aranya Kanda, Sarga 26, Verse 18', 'स भूमौ शोणितोद्गारी रामबाणाभिपीडितः।
न्यपतत्पतितैः पूर्वं स्वशिरोभिर्निशाचरः॥', 'sa bhūmau śoṇitodgārī rāmabāṇābhipīḍitaḥ
nyapatat patitaiḥ pūrvaṃ svaśirobhir niśācaraḥ', null, 3026018),
('ramayana-3-26-19', 19, 'Aranya Kanda, Sarga 26, Verse 19', 'हतशेषास्ततो भग्ना राक्षसाः खरसंश्रयाः।
द्रवन्ति स्म न तिष्ठन्ति व्याघ्रत्रस्ता मृगा इव॥', 'hataśeṣās tato bhagnā rākṣasāḥ kharasaṃśrayāḥ
dravanti sma na tiṣṭhanti vyāghratrastā mṛgā iva', null, 3026019),
('ramayana-3-26-20', 20, 'Aranya Kanda, Sarga 26, Verse 20', 'तान्खरो द्रवतो दृष्ट्वा निवर्त्य रुषितः स्वयम्।
राममेवाभिदुद्राव राहुश्चन्द्रमसं यथा॥', 'tān kharo dravato dṛṣṭvā nivartya ruṣitaḥ svayam
rāmam evābhidudrāva rāhuś candramasaṃ yathā', null, 3026020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 27 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-27-1', 1, 'Aranya Kanda, Sarga 27, Verse 1', 'निहतं दूषणं दृष्ट्वा रणे त्रिशिरसा सह।
खरस्याप्यभवत्त्रासो दृष्ट्वा रामस्य विक्रमम्॥', 'nihataṃ dūṣaṇaṃ dṛṣṭvā raṇe triśirasā saha
kharasyāpy abhavat trāso dṛṣṭvā rāmasya vikramam', null, 3027001),
('ramayana-3-27-2', 2, 'Aranya Kanda, Sarga 27, Verse 2', 'स दृष्ट्वा राक्षसं सैन्यमविषह्यं महाबलम्।
हतमेकेन रामेण दूषणस्त्रिशिरा अपि॥', 'sa dṛṣṭvā rākṣasaṃ sainyam aviṣahyaṃ mahābalam
hatam ekena rāmeṇa dūṣaṇas triśirā api', null, 3027002),
('ramayana-3-27-3', 3, 'Aranya Kanda, Sarga 27, Verse 3', 'तद्बलं हतभूयिष्ठं विमनाः प्रेक्ष्य राक्षसः।
आससाद खरो रामं नमुचिर्वासवं यथा॥', 'tad balaṃ hatabhūyiṣṭhaṃ vimanāḥ prekṣya rākṣasaḥ
āsasāda kharo rāmaṃ namucir vāsavaṃ yathā', null, 3027003),
('ramayana-3-27-4', 4, 'Aranya Kanda, Sarga 27, Verse 4', 'विकृष्य बलवच्चापं नाराचान्रक्तभोजनान्।
खरश्चिक्षेप रामाय क्रुद्धानाशीविषानिव॥', 'vikṛṣya balavac cāpaṃ nārācān raktabhojanān
kharaś cikṣepa rāmāya kruddhān āśīviṣān iva', null, 3027004),
('ramayana-3-27-5', 5, 'Aranya Kanda, Sarga 27, Verse 5', 'ज्यां विधुन्वन्सुबहुशः शिक्षयास्त्राणि दर्शयन्।
चचार समरे मार्गाञ्शरै रथगतः खरः॥', 'jyāṃ vidhunvan subahuśaḥ śikṣayāstrāṇi darśayan
cacāra samare mārgāñ śarai rathagataḥ kharaḥ', null, 3027005),
('ramayana-3-27-6', 6, 'Aranya Kanda, Sarga 27, Verse 6', 'स सर्वाश्च दिशो बाणैः प्रदिशश्च महारथः।
पूरयामास तं दृष्ट्वा रामोऽपि सुमहद्धनुः॥', 'sa sarvāś ca diśo bāṇaiḥ pradiśaś ca mahārathaḥ
pūrayām āsa taṃ dṛṣṭvā rāmo ''pi sumahad dhanuḥ', null, 3027006),
('ramayana-3-27-7', 7, 'Aranya Kanda, Sarga 27, Verse 7', 'स सायकैर्दुर्विषहैः सस्फुलिङ्गैरिवाग्निभिः।
नभश्चकाराविवरं पर्जन्य इव वृष्टिभिः॥', 'sa sāyakair durviṣahaiḥ sasphuliṅgair ivāgnibhiḥ
nabhaś cakārāvivaraṃ parjanya iva vṛṣṭibhiḥ', null, 3027007),
('ramayana-3-27-8', 8, 'Aranya Kanda, Sarga 27, Verse 8', 'तद्बभूव शितैर्बाणैः खररामविसर्जितैः।
पर्याकाशमनाकाशं सर्वतः शरसंकुलम्॥', 'tad babhūva śitair bāṇaiḥ khararāmavisarjitaiḥ
paryākāśam anākāśaṃ sarvataḥ śarasaṃkulam', null, 3027008),
('ramayana-3-27-9', 9, 'Aranya Kanda, Sarga 27, Verse 9', 'शरजालावृतः सूर्यो न तदा स्म प्रकाशते।
अन्योन्यवधसंरम्भादुभयोः संप्रयुध्यतोः॥', 'śarajālāvṛtaḥ sūryo na tadā sma prakāśate
anyonyavadhasaṃrambhād ubhayoḥ saṃprayudhyatoḥ', null, 3027009),
('ramayana-3-27-10', 10, 'Aranya Kanda, Sarga 27, Verse 10', 'ततो नालीकनाराचैस्तीक्ष्णाग्रैश्च विकर्णिभिः।
आजघान रणे रामं तोत्रैरिव महाद्विपम्॥', 'tato nālīkanārācais tīkṣṇāgraiś ca vikarṇibhiḥ
ājaghāna raṇe rāmaṃ totrair iva mahādvipam', null, 3027010),
('ramayana-3-27-11', 11, 'Aranya Kanda, Sarga 27, Verse 11', 'तं रथस्थं धनुष्पाणिं राक्षसं पर्यवस्थितम्।
ददृशुः सर्वभूतानि पाशहस्तमिवान्तकम्॥', 'taṃ rathasthaṃ dhanuṣpāṇiṃ rākṣasaṃ paryavasthitam
dadṛśuḥ sarvabhūtāni pāśahastam ivāntakam', null, 3027011),
('ramayana-3-27-12', 12, 'Aranya Kanda, Sarga 27, Verse 12', 'तं सिंहमिव विक्रान्तं सिंहविक्रान्तगामिनम्।
दृष्ट्वा नोद्विजते रामः सिंहः क्षुद्रमृगं यथा॥', 'taṃ siṃham iva vikrāntaṃ siṃhavikrāntagāminam
dṛṣṭvā nodvijate rāmaḥ siṃhaḥ kṣudramṛgaṃ yathā', null, 3027012),
('ramayana-3-27-13', 13, 'Aranya Kanda, Sarga 27, Verse 13', 'ततः सूर्यनिकाशेन रथेन महता खरः।
आससाद रणे रामं पतङ्ग इव पावकम्॥', 'tataḥ sūryanikāśena rathena mahatā kharaḥ
āsasāda raṇe rāmaṃ pataṅga iva pāvakam', null, 3027013),
('ramayana-3-27-14', 14, 'Aranya Kanda, Sarga 27, Verse 14', 'ततोऽस्य सशरं चापं मुष्टिदेशे महात्मनः।
खरश्चिच्छेद रामस्य दर्शयन्पाणिलाघवम्॥', 'tato ''sya saśaraṃ cāpaṃ muṣṭideśe mahātmanaḥ
kharaś ciccheda rāmasya darśayan pāṇilāghavam', null, 3027014),
('ramayana-3-27-15', 15, 'Aranya Kanda, Sarga 27, Verse 15', 'स पुनस्त्वपरान्सप्त शरानादाय वर्मणि।
निजघान रणे क्रुद्धः शक्राशनिसमप्रभान्॥', 'sa punas tv aparān sapta śarān ādāya varmaṇi
nijaghāna raṇe kruddhaḥ śakrāśanisamaprabhān', null, 3027015),
('ramayana-3-27-16', 16, 'Aranya Kanda, Sarga 27, Verse 16', 'ततस्तत्प्रहतं बाणैः खरमुक्तैः सुपर्वभिः।
पपात कवचं भूमौ रामस्यादित्यवर्चसः॥', 'tatas tat prahataṃ bāṇaiḥ kharamuktaiḥ suparvabhiḥ
papāta kavacaṃ bhūmau rāmasyādityavarcasaḥ', null, 3027016),
('ramayana-3-27-17', 17, 'Aranya Kanda, Sarga 27, Verse 17', 'स शरैरर्पितः क्रुद्धः सर्वगात्रेषु राघवः।
रराज समरे रामो विधूमोऽग्निरिव ज्वलन्॥', 'sa śarair arpitaḥ kruddhaḥ sarvagātreṣu rāghavaḥ
rarāja samare rāmo vidhūmo ''gnir iva jvalan', null, 3027017),
('ramayana-3-27-18', 18, 'Aranya Kanda, Sarga 27, Verse 18', 'ततो गम्भीरनिर्ह्रादं रामः शत्रुनिबर्हणः।
चकारान्ताय स रिपोः सज्यमन्यन्महद्धनुः॥', 'tato gambhīranirhrādaṃ rāmaḥ śatrunibarhaṇaḥ
cakārāntāya sa ripoḥ sajyam anyan mahad dhanuḥ', null, 3027018),
('ramayana-3-27-19', 19, 'Aranya Kanda, Sarga 27, Verse 19', 'सुमहद्वैष्णवं यत्तदतिसृष्टं महर्षिणा।
वरं तद्धनुरुद्यम्य खरं समभिधावत॥', 'sumahad vaiṣṇavaṃ yat tad atisṛṣṭaṃ maharṣiṇā
varaṃ tad dhanur udyamya kharaṃ samabhidhāvata', null, 3027019),
('ramayana-3-27-20', 20, 'Aranya Kanda, Sarga 27, Verse 20', 'ततः कनकपुङ्खैस्तु शरैः संनतपर्वभिः।
चिच्छेद रामः संक्रुद्धः खरस्य समरे ध्वजम्॥', 'tataḥ kanakapuṅkhais tu śaraiḥ saṃnataparvabhiḥ
ciccheda rāmaḥ saṃkruddhaḥ kharasya samare dhvajam', null, 3027020),
('ramayana-3-27-21', 21, 'Aranya Kanda, Sarga 27, Verse 21', 'स दर्शनीयो बहुधा विच्छिन्नः काञ्चनो ध्वजः।
जगाम धरणीं सूर्यो देवतानामिवाज्ञया॥', 'sa darśanīyo bahudhā vicchinnaḥ kāñcano dhvajaḥ
jagāma dharaṇīṃ sūryo devatānām ivājñayā', null, 3027021),
('ramayana-3-27-22', 22, 'Aranya Kanda, Sarga 27, Verse 22', 'तं चतुर्भिः खरः क्रुद्धो रामं गात्रेषु मार्गणैः।
विव्याध हृदि मर्मज्ञो मातङ्गमिव तोमरैः॥', 'taṃ caturbhiḥ kharaḥ kruddho rāmaṃ gātreṣu mārgaṇaiḥ
vivyādha hṛdi marmajño mātaṅgam iva tomaraiḥ', null, 3027022),
('ramayana-3-27-23', 23, 'Aranya Kanda, Sarga 27, Verse 23', 'स रामो बहुभिर्बाणैः खरकार्मुकनिःसृतैः।
विद्धो रुधिरसिक्ताङ्गो बभूव रुषितो भृशम्॥', 'sa rāmo bahubhir bāṇaiḥ kharakārmukaniḥsṛtaiḥ
viddho rudhirasiktāṅgo babhūva ruṣito bhṛśam', null, 3027023),
('ramayana-3-27-24', 24, 'Aranya Kanda, Sarga 27, Verse 24', 'स धनुर्धन्विनां श्रेष्ठः प्रगृह्य परमाहवे।
मुमोच परमेष्वासः षट्शरानभिलक्षितान्॥', 'sa dhanur dhanvināṃ śreṣṭhaḥ pragṛhya paramāhave
mumoca parameṣvāsaḥ ṣaṭ śarān abhilakṣitān', null, 3027024),
('ramayana-3-27-25', 25, 'Aranya Kanda, Sarga 27, Verse 25', 'शिरस्येकेन बाणेन द्वाभ्यां बाह्वोरथार्पयत्।
त्रिभिश्चन्द्रार्धवक्त्रैश्च वक्षस्यभिजघान ह॥', 'śirasy ekena bāṇena dvābhyāṃ bāhvor athārpayat
tribhiś candrārdhavaktraiś ca vakṣasy abhijaghāna ha', null, 3027025),
('ramayana-3-27-26', 26, 'Aranya Kanda, Sarga 27, Verse 26', 'ततः पश्चान्महातेजा नाराचान्भास्करोपमान्।
जिघांसू राक्षसं क्रुद्धस्त्रयोदश शिलाशितान्॥', 'tataḥ paścān mahātejā nārācān bhāskaropamān
jighāṃsū rākṣasaṃ kruddhas trayodaśa śilāśitān', null, 3027026),
('ramayana-3-27-27', 27, 'Aranya Kanda, Sarga 27, Verse 27', 'ततोऽस्य युगमेकेन चतुर्भिश्चतुरो हयान्।
षष्ठेन च शिरः संख्ये चिच्छेद खरसारथेः॥', 'tato ''sya yugam ekena caturbhiś caturo hayān
ṣaṣṭhena ca śiraḥ saṃkhye ciccheda kharasāratheḥ', null, 3027027),
('ramayana-3-27-28', 28, 'Aranya Kanda, Sarga 27, Verse 28', 'त्रिभिस्त्रिवेणुं बलवान्द्वाभ्यामक्षं महाबलः।
द्वादशेन तु बाणेन खरस्य सशरं धनुः।
छित्त्वा वज्रनिकाशेन राघवः प्रहसन्निव।
त्रयोदशेनेन्द्रसमो बिभेद समरे खरम्॥', 'tribhis triveṇuṃ balavān dvābhyām akṣaṃ mahābalaḥ
dvādaśena tu bāṇena kharasya saśaraṃ dhanuḥ
chittvā vajranikāśena rāghavaḥ prahasann iva
trayodaśenendrasamo bibheda samare kharam', null, 3027028),
('ramayana-3-27-29', 29, 'Aranya Kanda, Sarga 27, Verse 29', 'प्रभग्नधन्वा विरथो हताश्वो हतसारथिः।
गदापाणिरवप्लुत्य तस्थौ भूमौ खरस्तदा॥', 'prabhagnadhanvā viratho hatāśvo hatasārathiḥ
gadāpāṇir avaplutya tasthau bhūmau kharas tadā', null, 3027029),
('ramayana-3-27-30', 30, 'Aranya Kanda, Sarga 27, Verse 30', 'तत्कर्म रामस्य महारथस्य समेत्य देवाश्च महर्षयश्च।
अपूजयन्प्राञ्जलयः प्रहृष्टास्तदा विमानाग्रगताः समेताः॥', 'tat karma rāmasya mahārathasya sametya devāś ca maharṣayaś ca
apūjayan prāñjalayaḥ prahṛṣṭās tadā vimānāgragatāḥ sametāḥ', null, 3027030)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 28 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-28-1', 1, 'Aranya Kanda, Sarga 28, Verse 1', 'खरं तु विरथं रामो गदापाणिमवस्थितम्।
मृदुपूर्वं महातेजाः परुषं वाक्यमब्रवीत्॥', 'kharaṃ tu virathaṃ rāmo gadāpāṇim avasthitam
mṛdupūrvaṃ mahātejāḥ paruṣaṃ vākyam abravīt', null, 3028001),
('ramayana-3-28-2', 2, 'Aranya Kanda, Sarga 28, Verse 2', 'गजाश्वरथसंबाधे बले महति तिष्ठता।
कृतं सुदारुणं कर्म सर्वलोकजुगुप्सितम्॥', 'gajāśvarathasaṃbādhe bale mahati tiṣṭhatā
kṛtaṃ sudāruṇaṃ karma sarvalokajugupsitam', null, 3028002),
('ramayana-3-28-3', 3, 'Aranya Kanda, Sarga 28, Verse 3', 'उद्वेजनीयो भूतानां नृशंसः पापकर्मकृत्।
त्रयाणामपि लोकानामीश्वरोऽपि न तिष्ठति॥', 'udvejanīyo bhūtānāṃ nṛśaṃsaḥ pāpakarmakṛt
trayāṇām api lokānām īśvaro ''pi na tiṣṭhati', null, 3028003),
('ramayana-3-28-4', 4, 'Aranya Kanda, Sarga 28, Verse 4', 'कर्म लोकविरुद्धं तु कुर्वाणं क्षणदाचर।
तीक्ष्णं सर्वजनो हन्ति सर्पं दुष्टमिवागतम्॥', 'karma lokaviruddhaṃ tu kurvāṇaṃ kṣaṇadācara
tīkṣṇaṃ sarvajano hanti sarpaṃ duṣṭam ivāgatam', null, 3028004),
('ramayana-3-28-5', 5, 'Aranya Kanda, Sarga 28, Verse 5', 'लोभात्पापानि कुर्वाणः कामाद्वा यो न बुध्यते।
भ्रष्टः पश्यति तस्यान्तं ब्राह्मणी करकादिव॥', 'lobhāt pāpāni kurvāṇaḥ kāmād vā yo na budhyate
bhraṣṭaḥ paśyati tasyāntaṃ brāhmaṇī karakād iva', null, 3028005),
('ramayana-3-28-6', 6, 'Aranya Kanda, Sarga 28, Verse 6', 'वसतो दण्डकारण्ये तापसान्धर्मचारिणः।
किं नु हत्वा महाभागान्फलं प्राप्स्यसि राक्षस॥', 'vasato daṇḍakāraṇye tāpasān dharmacāriṇaḥ
kiṃ nu hatvā mahābhāgān phalaṃ prāpsyasi rākṣasa', null, 3028006),
('ramayana-3-28-7', 7, 'Aranya Kanda, Sarga 28, Verse 7', 'न चिरं पापकर्माणः क्रूरा लोकजुगुप्सिताः।
ऐश्वर्यं प्राप्य तिष्ठन्ति शीर्णमूला इव द्रुमाः॥', 'na ciraṃ pāpakarmāṇaḥ krūrā lokajugupsitāḥ
aiśvaryaṃ prāpya tiṣṭhanti śīrṇamūlā iva drumāḥ', null, 3028007),
('ramayana-3-28-8', 8, 'Aranya Kanda, Sarga 28, Verse 8', 'अवश्यं लभते कर्ता फलं पापस्य कर्मणः।
घोरं पर्यागते काले द्रुमः पुष्पमिवार्तवम्॥', 'avaśyaṃ labhate kartā phalaṃ pāpasya karmaṇaḥ
ghoraṃ paryāgate kāle drumaḥ puṣpam ivārtavam', null, 3028008),
('ramayana-3-28-9', 9, 'Aranya Kanda, Sarga 28, Verse 9', 'नचिरात्प्राप्यते लोके पापानां कर्मणां फलम्।
सविषाणामिवान्नानां भुक्तानां क्षणदाचर॥', 'nacirāt prāpyate loke pāpānāṃ karmaṇāṃ phalam
saviṣāṇām ivānnānāṃ bhuktānāṃ kṣaṇadācara', null, 3028009),
('ramayana-3-28-10', 10, 'Aranya Kanda, Sarga 28, Verse 10', 'पापमाच्चरतां घोरं लोकस्याप्रियमिच्छताम्।
अहमासादितो राजा प्राणान्हन्तुं निशाचर॥', 'pāpam āccaratāṃ ghoraṃ lokasyāpriyam icchatām
aham āsādito rājā prāṇān hantuṃ niśācara', null, 3028010),
('ramayana-3-28-11', 11, 'Aranya Kanda, Sarga 28, Verse 11', 'अद्य हि त्वां मया मुक्ताः शराः काञ्चनभूषणाः।
विदार्य निपतिष्यन्ति वल्मीकमिव पन्नगाः॥', 'adya hi tvāṃ mayā muktāḥ śarāḥ kāñcanabhūṣaṇāḥ
vidārya nipatiṣyanti valmīkam iva pannagāḥ', null, 3028011),
('ramayana-3-28-12', 12, 'Aranya Kanda, Sarga 28, Verse 12', 'ये त्वया दण्डकारण्ये भक्षिता धर्मचारिणः।
तानद्य निहतः संख्ये ससैन्योऽनुगमिष्यसि॥', 'ye tvayā daṇḍakāraṇye bhakṣitā dharmacāriṇaḥ
tān adya nihataḥ saṃkhye sasainyo ''nugamiṣyasi', null, 3028012),
('ramayana-3-28-13', 13, 'Aranya Kanda, Sarga 28, Verse 13', 'अद्य त्वां निहतं बाणैः पश्यन्तु परमर्षयः।
निरयस्थं विमानस्था ये त्वया हिंसिताः पुरा॥', 'adya tvāṃ nihataṃ bāṇaiḥ paśyantu paramarṣayaḥ
nirayasthaṃ vimānasthā ye tvayā hiṃsitāḥ purā', null, 3028013),
('ramayana-3-28-14', 14, 'Aranya Kanda, Sarga 28, Verse 14', 'प्रहर त्वं यथाकामं कुरु यत्नं कुलाधम।
अद्य ते पातयिष्यामि शिरस्तालफलं यथा॥', 'prahara tvaṃ yathākāmaṃ kuru yatnaṃ kulādhama
adya te pātayiṣyāmi śiras tālaphalaṃ yathā', null, 3028014),
('ramayana-3-28-15', 15, 'Aranya Kanda, Sarga 28, Verse 15', 'एवमुक्तस्तु रामेण क्रुद्धः संरक्तलोचनः।
प्रत्युवाच ततो रामं प्रहसन्क्रोधमूर्छितः॥', 'evam uktas tu rāmeṇa kruddhaḥ saṃraktalocanaḥ
pratyuvāca tato rāmaṃ prahasan krodhamūrchitaḥ', null, 3028015),
('ramayana-3-28-16', 16, 'Aranya Kanda, Sarga 28, Verse 16', 'प्राकृतान्राक्षसान्हत्वा युद्धे दशरथात्मज।
आत्मना कथमात्मानमप्रशस्यं प्रशंससि॥', 'prākṛtān rākṣasān hatvā yuddhe daśarathātmaja
ātmanā katham ātmānam apraśasyaṃ praśaṃsasi', null, 3028016),
('ramayana-3-28-17', 17, 'Aranya Kanda, Sarga 28, Verse 17', 'विक्रान्ता बलवन्तो वा ये भवन्ति नरर्षभाः।
कथयन्ति न ते किं चित्तेजसा स्वेन गर्विताः॥', 'vikrāntā balavanto vā ye bhavanti nararṣabhāḥ
kathayanti na te kiṃ cit tejasā svena garvitāḥ', null, 3028017),
('ramayana-3-28-18', 18, 'Aranya Kanda, Sarga 28, Verse 18', 'प्राकृतास्त्वकृतात्मानो लोके क्षत्रियपांसनाः।
निरर्थकं विकत्थन्ते यथा राम विकत्थसे॥', 'prākṛtās tv akṛtātmāno loke kṣatriyapāṃsanāḥ
nirarthakaṃ vikatthante yathā rāma vikatthase', null, 3028018),
('ramayana-3-28-19', 19, 'Aranya Kanda, Sarga 28, Verse 19', 'कुलं व्यपदिशन्वीरः समरे कोऽभिधास्यति।
मृत्युकाले हि संप्राप्ते स्वयमप्रस्तवे स्तवम्॥', 'kulaṃ vyapadiśan vīraḥ samare ko ''bhidhāsyati
mṛtyukāle hi saṃprāpte svayam aprastave stavam', null, 3028019),
('ramayana-3-28-20', 20, 'Aranya Kanda, Sarga 28, Verse 20', 'सर्वथा तु लघुत्वं ते कत्थनेन विदर्शितम्।
सुवर्णप्रतिरूपेण तप्तेनेव कुशाग्निना॥', 'sarvathā tu laghutvaṃ te katthanena vidarśitam
suvarṇapratirūpeṇa tapteneva kuśāgninā', null, 3028020),
('ramayana-3-28-21', 21, 'Aranya Kanda, Sarga 28, Verse 21', 'न तु मामिह तिष्ठन्तं पश्यसि त्वं गदाधरम्।
धराधरमिवाकम्प्यं पर्वतं धातुभिश्चितम्॥', 'na tu mām iha tiṣṭhantaṃ paśyasi tvaṃ gadādharam
dharādharam ivākampyaṃ parvataṃ dhātubhiś citam', null, 3028021),
('ramayana-3-28-22', 22, 'Aranya Kanda, Sarga 28, Verse 22', 'पर्याप्तोऽहं गदापाणिर्हन्तुं प्राणान्रणे तव।
त्रयाणामपि लोकानां पाशहस्त इवान्तकः॥', 'paryāpto ''haṃ gadāpāṇir hantuṃ prāṇān raṇe tava
trayāṇām api lokānāṃ pāśahasta ivāntakaḥ', null, 3028022),
('ramayana-3-28-23', 23, 'Aranya Kanda, Sarga 28, Verse 23', 'कामं बह्वपि वक्तव्यं त्वयि वक्ष्यामि न त्वहम्।
अस्तं गच्छेद्धि सविता युद्धविघ्रस्ततो भवेत्॥', 'kāmaṃ bahv api vaktavyaṃ tvayi vakṣyāmi na tv aham
astaṃ gacched dhi savitā yuddhavighras tato bhavet', null, 3028023),
('ramayana-3-28-24', 24, 'Aranya Kanda, Sarga 28, Verse 24', 'चतुर्दश सहस्राणि राक्षसानां हतानि ते।
त्वद्विनाशात्करोम्यद्य तेषामश्रुप्रमार्जनम्॥', 'caturdaśa sahasrāṇi rākṣasānāṃ hatāni te
tvadvināśāt karomy adya teṣām aśrupramārjanam', null, 3028024),
('ramayana-3-28-25', 25, 'Aranya Kanda, Sarga 28, Verse 25', 'इत्युक्त्वा परमक्रुद्धस्तां गदां परमाङ्गदाम्।
खरश्चिक्षेप रामाय प्रदीप्तामशनिं यथा॥', 'ity uktvā paramakruddhas tāṃ gadāṃ paramāṅgadām
kharaś cikṣepa rāmāya pradīptām aśaniṃ yathā', null, 3028025),
('ramayana-3-28-26', 26, 'Aranya Kanda, Sarga 28, Verse 26', 'खरबाहुप्रमुक्ता सा प्रदीप्ता महती गदा।
भस्मवृक्षांश्च गुल्मांश्च कृत्वागात्तत्समीपतः॥', 'kharabāhupramuktā sā pradīptā mahatī gadā
bhasmavṛkṣāṃś ca gulmāṃś ca kṛtvāgāt tatsamīpataḥ', null, 3028026),
('ramayana-3-28-27', 27, 'Aranya Kanda, Sarga 28, Verse 27', 'तामापतन्तीं ज्वलितां मृत्युपाशोपमां गदा।
अन्तरिक्षगतां रामश्चिच्छेद बहुधा शरैः॥', 'tām āpatantīṃ jvalitāṃ mṛtyupāśopamāṃ gadā
antarikṣagatāṃ rāmaś ciccheda bahudhā śaraiḥ', null, 3028027),
('ramayana-3-28-28', 28, 'Aranya Kanda, Sarga 28, Verse 28', 'सा विशीर्णा शरैर्भिन्ना पपात धरणीतले।
गदामन्त्रौषधिबलैर्व्यालीव विनिपातिता॥', 'sā viśīrṇā śarair bhinnā papāta dharaṇītale
gadāmantrauṣadhibalair vyālīva vinipātitā', null, 3028028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 29 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-29-1', 1, 'Aranya Kanda, Sarga 29, Verse 1', 'भित्त्वा तु तां गदां बाणै राघवो धर्मवत्सलः।
स्मयमानः खरं वाक्यं संरब्धमिदमब्रवीत्॥', 'bhittvā tu tāṃ gadāṃ bāṇai rāghavo dharmavatsalaḥ
smayamānaḥ kharaṃ vākyaṃ saṃrabdham idam abravīt', null, 3029001),
('ramayana-3-29-2', 2, 'Aranya Kanda, Sarga 29, Verse 2', 'एतत्ते बलसर्वस्वं दर्शितं राक्षसाधम।
शक्तिहीनतरो मत्तो वृथा त्वमुपगर्जितम्॥', 'etat te balasarvasvaṃ darśitaṃ rākṣasādhama
śaktihīnataro matto vṛthā tvam upagarjitam', null, 3029002),
('ramayana-3-29-3', 3, 'Aranya Kanda, Sarga 29, Verse 3', 'एषा बाणविनिर्भिन्ना गदा भूमितलं गता।
अभिधानप्रगल्भस्य तव प्रत्ययघातिनी॥', 'eṣā bāṇavinirbhinnā gadā bhūmitalaṃ gatā
abhidhānapragalbhasya tava pratyayaghātinī', null, 3029003),
('ramayana-3-29-4', 4, 'Aranya Kanda, Sarga 29, Verse 4', 'यत्त्वयोक्तं विनष्टानामिदमश्रुप्रमार्जनम्।
राक्षसानां करोमीति मिथ्या तदपि ते वचः॥', 'yat tvayoktaṃ vinaṣṭānām idam aśrupramārjanam
rākṣasānāṃ karomīti mithyā tad api te vacaḥ', null, 3029004),
('ramayana-3-29-5', 5, 'Aranya Kanda, Sarga 29, Verse 5', 'नीचस्य क्षुद्रशीलस्य मिथ्यावृत्तस्य रक्षसः।
प्राणानपहरिष्यामि गरुत्मानमृतं यथा॥', 'nīcasya kṣudraśīlasya mithyāvṛttasya rakṣasaḥ
prāṇān apahariṣyāmi garutmān amṛtaṃ yathā', null, 3029005),
('ramayana-3-29-6', 6, 'Aranya Kanda, Sarga 29, Verse 6', 'अद्य ते भिन्नकण्ठस्य फेनबुद्बुदभूषितम्।
विदारितस्य मद्बाणैर्मही पास्यति शोणितम्॥', 'adya te bhinnakaṇṭhasya phenabudbudabhūṣitam
vidāritasya madbāṇair mahī pāsyati śoṇitam', null, 3029006),
('ramayana-3-29-7', 7, 'Aranya Kanda, Sarga 29, Verse 7', 'पांसुरूषितसर्वाङ्गः स्रस्तन्यस्तभुजद्वयः।
स्वप्स्यसे गां समाश्लिष्य दुर्लभां प्रमदामिव॥', 'pāṃsurūṣitasarvāṅgaḥ srastanyastabhujadvayaḥ
svapsyase gāṃ samāśliṣya durlabhāṃ pramadām iva', null, 3029007),
('ramayana-3-29-8', 8, 'Aranya Kanda, Sarga 29, Verse 8', 'प्रवृद्धनिद्रे शयिते त्वयि राक्षसपांसने।
भविष्यन्त्यशरण्यानां शरण्या दण्डका इमे॥', 'pravṛddhanidre śayite tvayi rākṣasapāṃsane
bhaviṣyanty aśaraṇyānāṃ śaraṇyā daṇḍakā ime', null, 3029008),
('ramayana-3-29-9', 9, 'Aranya Kanda, Sarga 29, Verse 9', 'जनस्थाने हतस्थाने तव राक्षसमच्छरैः।
निर्भया विचरिष्यन्ति सर्वतो मुनयो वने॥', 'janasthāne hatasthāne tava rākṣasamaccharaiḥ
nirbhayā vicariṣyanti sarvato munayo vane', null, 3029009),
('ramayana-3-29-10', 10, 'Aranya Kanda, Sarga 29, Verse 10', 'अद्य विप्रसरिष्यन्ति राक्षस्यो हतबान्धवाः।
बाष्पार्द्रवदना दीना भयादन्यभयावहाः॥', 'adya viprasariṣyanti rākṣasyo hatabāndhavāḥ
bāṣpārdravadanā dīnā bhayād anyabhayāvahāḥ', null, 3029010),
('ramayana-3-29-11', 11, 'Aranya Kanda, Sarga 29, Verse 11', 'अद्य शोकरसज्ञास्ता भविष्यन्ति निशाचर।
अनुरूपकुलाः पत्न्यो यासां त्वं पतिरीदृशः॥', 'adya śokarasajñās tā bhaviṣyanti niśācara
anurūpakulāḥ patnyo yāsāṃ tvaṃ patir īdṛśaḥ', null, 3029011),
('ramayana-3-29-12', 12, 'Aranya Kanda, Sarga 29, Verse 12', 'नृशंसशील क्षुद्रात्मन्नित्यं ब्राह्मणकण्टक।
त्वत्कृते शङ्कितैरग्नौ मुनिभिः पात्यते हविः॥', 'nṛśaṃsaśīla kṣudrātman nityaṃ brāhmaṇakaṇṭaka
tvatkṛte śaṅkitair agnau munibhiḥ pātyate haviḥ', null, 3029012),
('ramayana-3-29-13', 13, 'Aranya Kanda, Sarga 29, Verse 13', 'तमेवमभिसंरब्धं ब्रुवाणं राघवं रणे।
खरो निर्भर्त्सयामास रोषात्खरतर स्वनः॥', 'tam evam abhisaṃrabdhaṃ bruvāṇaṃ rāghavaṃ raṇe
kharo nirbhartsayām āsa roṣāt kharatara svanaḥ', null, 3029013),
('ramayana-3-29-14', 14, 'Aranya Kanda, Sarga 29, Verse 14', 'दृढं खल्ववलिप्तोऽसि भयेष्वपि च निर्भयः।
वाच्यावाच्यं ततो हि त्वं मृत्युवश्यो न बुध्यसे॥', 'dṛḍhaṃ khalv avalipto ''si bhayeṣv api ca nirbhayaḥ
vācyāvācyaṃ tato hi tvaṃ mṛtyuvaśyo na budhyase', null, 3029014),
('ramayana-3-29-15', 15, 'Aranya Kanda, Sarga 29, Verse 15', 'कालपाशपरिक्षिप्ता भवन्ति पुरुषा हि ये।
कार्याकार्यं न जानन्ति ते निरस्तषडिन्द्रियाः॥', 'kālapāśaparikṣiptā bhavanti puruṣā hi ye
kāryākāryaṃ na jānanti te nirastaṣaḍindriyāḥ', null, 3029015),
('ramayana-3-29-16', 16, 'Aranya Kanda, Sarga 29, Verse 16', 'एवमुक्त्वा ततो रामं संरुध्य भृकुटिं ततः।
स ददर्श महासालमविदूरे निशाचरः॥', 'evam uktvā tato rāmaṃ saṃrudhya bhṛkuṭiṃ tataḥ
sa dadarśa mahāsālam avidūre niśācaraḥ', null, 3029016),
('ramayana-3-29-17', 17, 'Aranya Kanda, Sarga 29, Verse 17', 'रणे प्रहरणस्यार्थे सर्वतो ह्यवलोकयन्।
स तमुत्पाटयामास संदृश्य दशनच्छदम्॥', 'raṇe praharaṇasyārthe sarvato hy avalokayan
sa tam utpāṭayām āsa saṃdṛśya daśanacchadam', null, 3029017),
('ramayana-3-29-18', 18, 'Aranya Kanda, Sarga 29, Verse 18', 'तं समुत्क्षिप्य बाहुभ्यां विनर्दित्वा महाबलः।
राममुद्दिश्य चिक्षेप हतस्त्वमिति चाब्रवीत्॥', 'taṃ samutkṣipya bāhubhyāṃ vinarditvā mahābalaḥ
rāmam uddiśya cikṣepa hatas tvam iti cābravīt', null, 3029018),
('ramayana-3-29-19', 19, 'Aranya Kanda, Sarga 29, Verse 19', 'तमापतन्तं बाणौघैश्छित्त्वा रामः प्रतापवान्।
रोषमाहारयत्तीव्रं निहन्तुं समरे खरम्॥', 'tam āpatantaṃ bāṇaughaiś chittvā rāmaḥ pratāpavān
roṣam āhārayat tīvraṃ nihantuṃ samare kharam', null, 3029019),
('ramayana-3-29-20', 20, 'Aranya Kanda, Sarga 29, Verse 20', 'जातस्वेदस्ततो रामो रोषाद्रक्तान्तलोचनः।
निर्बिभेद सहस्रेण बाणानां समरे खरम्॥', 'jātasvedas tato rāmo roṣād raktāntalocanaḥ
nirbibheda sahasreṇa bāṇānāṃ samare kharam', null, 3029020),
('ramayana-3-29-21', 21, 'Aranya Kanda, Sarga 29, Verse 21', 'तस्य बाणान्तराद्रक्तं बहु सुस्राव फेनिलम्।
गिरेः प्रस्रवणस्येव तोयधारापरिस्रवः॥', 'tasya bāṇāntarād raktaṃ bahu susrāva phenilam
gireḥ prasravaṇasyeva toyadhārāparisravaḥ', null, 3029021),
('ramayana-3-29-22', 22, 'Aranya Kanda, Sarga 29, Verse 22', 'विह्वलः स कृतो बाणैः खरो रामेण संयुगे।
मत्तो रुधिरगन्धेन तमेवाभ्यद्रवद्द्रुतम्॥', 'vihvalaḥ sa kṛto bāṇaiḥ kharo rāmeṇa saṃyuge
matto rudhiragandhena tam evābhyadravad drutam', null, 3029022),
('ramayana-3-29-23', 23, 'Aranya Kanda, Sarga 29, Verse 23', 'तमापतन्तं संरब्धं कृतास्त्रो रुधिराप्लुतम्।
अपसर्पत्प्रतिपदं किं चित्त्वरितविक्रमः॥', 'tam āpatantaṃ saṃrabdhaṃ kṛtāstro rudhirāplutam
apasarpat pratipadaṃ kiṃ cit tvaritavikramaḥ', null, 3029023),
('ramayana-3-29-24', 24, 'Aranya Kanda, Sarga 29, Verse 24', 'ततः पावकसंकाशं बधाय समरे शरम्।
खरस्य रामो जग्राह ब्रह्मदण्डमिवापरम्॥', 'tataḥ pāvakasaṃkāśaṃ badhāya samare śaram
kharasya rāmo jagrāha brahmadaṇḍam ivāparam', null, 3029024),
('ramayana-3-29-25', 25, 'Aranya Kanda, Sarga 29, Verse 25', 'स तद्दत्तं मघवता सुरराजेन धीमता।
संदधे च स धर्मात्मा मुमोच च खरं प्रति॥', 'sa tad dattaṃ maghavatā surarājena dhīmatā
saṃdadhe ca sa dharmātmā mumoca ca kharaṃ prati', null, 3029025),
('ramayana-3-29-26', 26, 'Aranya Kanda, Sarga 29, Verse 26', 'स विमुक्तो महाबाणो निर्घातसमनिःस्वनः।
रामेण धनुरुद्यम्य खरस्योरसि चापतत्॥', 'sa vimukto mahābāṇo nirghātasamaniḥsvanaḥ
rāmeṇa dhanur udyamya kharasyorasi cāpatat', null, 3029026),
('ramayana-3-29-27', 27, 'Aranya Kanda, Sarga 29, Verse 27', 'स पपात खरो भूमौ दह्यमानः शराग्निना।
रुद्रेणैव विनिर्दग्धः श्वेतारण्ये यथान्धकः॥', 'sa papāta kharo bhūmau dahyamānaḥ śarāgninā
rudreṇaiva vinirdagdhaḥ śvetāraṇye yathāndhakaḥ', null, 3029027),
('ramayana-3-29-28', 28, 'Aranya Kanda, Sarga 29, Verse 28', 'स वृत्र इव वज्रेण फेनेन नमुचिर्यथा।
बलो वेन्द्राशनिहतो निपपात हतः खरः॥', 'sa vṛtra iva vajreṇa phenena namucir yathā
balo vendrāśanihato nipapāta hataḥ kharaḥ', null, 3029028),
('ramayana-3-29-29', 29, 'Aranya Kanda, Sarga 29, Verse 29', 'ततो राजर्षयः सर्वे संगताः परमर्षयः।
सभाज्य मुदिता राममिदं वचनमब्रुवन्॥', 'tato rājarṣayaḥ sarve saṃgatāḥ paramarṣayaḥ
sabhājya muditā rāmam idaṃ vacanam abruvan', null, 3029029),
('ramayana-3-29-30', 30, 'Aranya Kanda, Sarga 29, Verse 30', 'एतदर्थं महातेजा महेन्द्रः पाकशासनः।
शरभङ्गाश्रमं पुण्यमाजगाम पुरंदरः॥', 'etadarthaṃ mahātejā mahendraḥ pākaśāsanaḥ
śarabhaṅgāśramaṃ puṇyam ājagāma puraṃdaraḥ', null, 3029030),
('ramayana-3-29-31', 31, 'Aranya Kanda, Sarga 29, Verse 31', 'आनीतस्त्वमिमं देशमुपायेन महर्षिभिः।
एषां वधार्थं क्रूराणां रक्षसां पापकर्मणाम्॥', 'ānītas tvam imaṃ deśam upāyena maharṣibhiḥ
eṣāṃ vadhārthaṃ krūrāṇāṃ rakṣasāṃ pāpakarmaṇām', null, 3029031),
('ramayana-3-29-32', 32, 'Aranya Kanda, Sarga 29, Verse 32', 'तदिदं नः कृतं कार्यं त्वया दशरथात्मज।
सुखं धर्मं चरिष्यन्ति दण्डकेषु महर्षयः॥', 'tad idaṃ naḥ kṛtaṃ kāryaṃ tvayā daśarathātmaja
sukhaṃ dharmaṃ cariṣyanti daṇḍakeṣu maharṣayaḥ', null, 3029032),
('ramayana-3-29-33', 33, 'Aranya Kanda, Sarga 29, Verse 33', 'एतस्मिन्नन्तरे वीरो लक्ष्मणः सह सीतया।
गिरिदुर्गाद्विनिष्क्रम्य संविवेशाश्रमं सुखी॥', 'etasminn antare vīro lakṣmaṇaḥ saha sītayā
giridurgād viniṣkramya saṃviveśāśramaṃ sukhī', null, 3029033),
('ramayana-3-29-34', 34, 'Aranya Kanda, Sarga 29, Verse 34', 'ततो रामस्तु विजयी पूज्यमानो महर्षिभिः।
प्रविवेशाश्रमं वीरो लक्ष्मणेनाभिवादितः॥', 'tato rāmas tu vijayī pūjyamāno maharṣibhiḥ
praviveśāśramaṃ vīro lakṣmaṇenābhivāditaḥ', null, 3029034),
('ramayana-3-29-35', 35, 'Aranya Kanda, Sarga 29, Verse 35', 'तं दृष्ट्वा शत्रुहन्तारं महर्षीणां सुखावहम्।
बभूव हृष्टा वैदेही भर्तारं परिषस्वजे॥', 'taṃ dṛṣṭvā śatruhantāraṃ maharṣīṇāṃ sukhāvaham
babhūva hṛṣṭā vaidehī bhartāraṃ pariṣasvaje', null, 3029035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 30 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-30-1', 1, 'Aranya Kanda, Sarga 30, Verse 1', 'ततः शूर्पणखा दृष्ट्वा सहस्राणि चतुर्दश।
हतान्येकेन रामेण रक्षसां भीमकर्मणाम्॥', 'tataḥ śūrpaṇakhā dṛṣṭvā sahasrāṇi caturdaśa
hatāny ekena rāmeṇa rakṣasāṃ bhīmakarmaṇām', null, 3030001),
('ramayana-3-30-2', 2, 'Aranya Kanda, Sarga 30, Verse 2', 'दूषणं च खरं चैव हतं त्रिशिरसं रणे।
दृष्ट्वा पुनर्महानादं ननाद जलदोपमा॥', 'dūṣaṇaṃ ca kharaṃ caiva hataṃ triśirasaṃ raṇe
dṛṣṭvā punar mahānādaṃ nanāda jaladopamā', null, 3030002),
('ramayana-3-30-3', 3, 'Aranya Kanda, Sarga 30, Verse 3', 'सा दृष्ट्वा कर्म रामस्य कृतमन्यैः सुदुष्करम्।
जगाम परमौद्विग्ना लङ्कां रावणपालिताम्॥', 'sā dṛṣṭvā karma rāmasya kṛtam anyaiḥ suduṣkaram
jagāma paramaudvignā laṅkāṃ rāvaṇapālitām', null, 3030003),
('ramayana-3-30-4', 4, 'Aranya Kanda, Sarga 30, Verse 4', 'स ददर्श विमानाग्रे रावणं दीप्ततेजसं।
उपोपविष्टं सचिवैर्मरुद्भिरिव वासवम्॥', 'sa dadarśa vimānāgre rāvaṇaṃ dīptatejasaṃ
upopaviṣṭaṃ sacivair marudbhir iva vāsavam', null, 3030004),
('ramayana-3-30-5', 5, 'Aranya Kanda, Sarga 30, Verse 5', 'आसीनं सूर्यसंकाशे काञ्चने परमासने।
रुक्मवेदिगतं प्राज्यं ज्वलन्तमिव पावकम्॥', 'āsīnaṃ sūryasaṃkāśe kāñcane paramāsane
rukmavedigataṃ prājyaṃ jvalantam iva pāvakam', null, 3030005),
('ramayana-3-30-6', 6, 'Aranya Kanda, Sarga 30, Verse 6', 'देवगन्धर्वभूतानामृषीणां च महात्मनाम्।
अजेयं समरे शूरं व्यात्ताननमिवान्तकम्॥', 'devagandharvabhūtānām ṛṣīṇāṃ ca mahātmanām
ajeyaṃ samare śūraṃ vyāttānanam ivāntakam', null, 3030006),
('ramayana-3-30-7', 7, 'Aranya Kanda, Sarga 30, Verse 7', 'देवासुरविमर्देषु वज्राशनिकृतव्रणम्।
ऐरावतविषाणाग्रैरुत्कृष्टकिणवक्षसं॥', 'devāsuravimardeṣu vajrāśanikṛtavraṇam
airāvataviṣāṇāgrair utkṛṣṭakiṇavakṣasaṃ', null, 3030007),
('ramayana-3-30-8', 8, 'Aranya Kanda, Sarga 30, Verse 8', 'विंशद्भुजं दशग्रीवं दर्शनीयपरिच्छदम्।
विशालवक्षसं वीरं राजलक्ष्मणलक्षितम्॥', 'viṃśadbhujaṃ daśagrīvaṃ darśanīyaparicchadam
viśālavakṣasaṃ vīraṃ rājalakṣmaṇalakṣitam', null, 3030008),
('ramayana-3-30-9', 9, 'Aranya Kanda, Sarga 30, Verse 9', 'स्निग्धवैदूर्यसंकाशं तप्तकाञ्चनकुण्डलम्।
सुभुजं शुक्लदशनं महास्यं पर्वतोपमम्॥', 'snigdhavaidūryasaṃkāśaṃ taptakāñcanakuṇḍalam
subhujaṃ śukladaśanaṃ mahāsyaṃ parvatopamam', null, 3030009),
('ramayana-3-30-10', 10, 'Aranya Kanda, Sarga 30, Verse 10', 'विष्णुचक्रनिपातैश्च शतशो देवसंयुगे।
आहताङ्गं समस्तैश्च देवप्रहरणैस्तथा॥', 'viṣṇucakranipātaiś ca śataśo devasaṃyuge
āhatāṅgaṃ samastaiś ca devapraharaṇais tathā', null, 3030010),
('ramayana-3-30-11', 11, 'Aranya Kanda, Sarga 30, Verse 11', 'अक्षोभ्याणां समुद्राणां क्षोभणं क्षिप्रकारिणम्।
क्षेप्तारं पर्वताग्राणां सुराणां च प्रमर्दनम्॥', 'akṣobhyāṇāṃ samudrāṇāṃ kṣobhaṇaṃ kṣiprakāriṇam
kṣeptāraṃ parvatāgrāṇāṃ surāṇāṃ ca pramardanam', null, 3030011),
('ramayana-3-30-12', 12, 'Aranya Kanda, Sarga 30, Verse 12', 'उच्छेत्तारं च धर्माणां परदाराभिमर्शनम्।
सर्वदिव्यास्त्रयोक्तारं यज्ञविघ्नकरं सदा॥', 'ucchettāraṃ ca dharmāṇāṃ paradārābhimarśanam
sarvadivyāstrayoktāraṃ yajñavighnakaraṃ sadā', null, 3030012),
('ramayana-3-30-13', 13, 'Aranya Kanda, Sarga 30, Verse 13', 'पुरीं भोगवतीं गत्वा पराजित्य च वासुकिम्।
तक्षकस्य प्रियां भार्यां पराजित्य जहार यः॥', 'purīṃ bhogavatīṃ gatvā parājitya ca vāsukim
takṣakasya priyāṃ bhāryāṃ parājitya jahāra yaḥ', null, 3030013),
('ramayana-3-30-14', 14, 'Aranya Kanda, Sarga 30, Verse 14', 'कैलासं पर्वतं गत्वा विजित्य नरवाहनम्।
विमानं पुष्पकं तस्य कामगं वै जहार यः॥', 'kailāsaṃ parvataṃ gatvā vijitya naravāhanam
vimānaṃ puṣpakaṃ tasya kāmagaṃ vai jahāra yaḥ', null, 3030014),
('ramayana-3-30-15', 15, 'Aranya Kanda, Sarga 30, Verse 15', 'वनं चैत्ररथं दिव्यं नलिनीं नन्दनं वनम्।
विनाशयति यः क्रोधाद्देवोद्यानानि वीर्यवान्॥', 'vanaṃ caitrarathaṃ divyaṃ nalinīṃ nandanaṃ vanam
vināśayati yaḥ krodhād devodyānāni vīryavān', null, 3030015),
('ramayana-3-30-16', 16, 'Aranya Kanda, Sarga 30, Verse 16', 'चन्द्रसूर्यौ महाभागावुत्तिष्ठन्तौ परंतपौ।
निवारयति बाहुभ्यां यः शैलशिखरोपमः॥', 'candrasūryau mahābhāgāv uttiṣṭhantau paraṃtapau
nivārayati bāhubhyāṃ yaḥ śailaśikharopamaḥ', null, 3030016),
('ramayana-3-30-17', 17, 'Aranya Kanda, Sarga 30, Verse 17', 'दशवर्षसहस्राणि तपस्तप्त्वा महावने।
पुरा स्वयम्भुवे धीरः शिरांस्युपजहार यः॥', 'daśavarṣasahasrāṇi tapas taptvā mahāvane
purā svayambhuve dhīraḥ śirāṃsy upajahāra yaḥ', null, 3030017),
('ramayana-3-30-18', 18, 'Aranya Kanda, Sarga 30, Verse 18', 'देवदानवगन्धर्वपिशाचपतगोरगैः।
अभयं यस्य संग्रामे मृत्युतो मानुषादृते॥', 'devadānavagandharvapiśācapatagoragaiḥ
abhayaṃ yasya saṃgrāme mṛtyuto mānuṣād ṛte', null, 3030018),
('ramayana-3-30-19', 19, 'Aranya Kanda, Sarga 30, Verse 19', 'मन्त्ररभितुष्टं पुण्यमध्वरेषु द्विजातिभिः।
हविर्धानेषु यः सोममुपहन्ति महाबलः॥', 'mantrar abhituṣṭaṃ puṇyam adhvareṣu dvijātibhiḥ
havirdhāneṣu yaḥ somam upahanti mahābalaḥ', null, 3030019),
('ramayana-3-30-20', 20, 'Aranya Kanda, Sarga 30, Verse 20', 'आप्तयज्ञहरं क्रूरं ब्रह्मघ्नं दुष्टचारिणम्।
कर्कशं निरनुक्रोशं प्रजानामहिते रतम्।
रावणं सर्वभूतानां सर्वलोकभयावहम्॥', 'āptayajñaharaṃ krūraṃ brahmaghnaṃ duṣṭacāriṇam
karkaśaṃ niranukrośaṃ prajānām ahite ratam
rāvaṇaṃ sarvabhūtānāṃ sarvalokabhayāvaham', null, 3030020),
('ramayana-3-30-21', 21, 'Aranya Kanda, Sarga 30, Verse 21', 'राक्षसी भ्रातरं क्रूरं सा ददर्श महाबलम्।
तं दिव्यवस्त्राभरणं दिव्यमाल्योपशोभितम्।
राक्षसेन्द्रं महाभागं पौलस्त्य कुलनन्दनम्॥', 'rākṣasī bhrātaraṃ krūraṃ sā dadarśa mahābalam
taṃ divyavastrābharaṇaṃ divyamālyopaśobhitam
rākṣasendraṃ mahābhāgaṃ paulastya kulanandanam', null, 3030021),
('ramayana-3-30-22', 22, 'Aranya Kanda, Sarga 30, Verse 22', 'तमब्रवीद्दीप्तविशाललोचनं प्रदर्शयित्वा भयमोहमूर्छिता।
सुदारुणं वाक्यमभीतचारिणी महात्मना शूर्पणखा विरूपिता॥', 'tam abravīd dīptaviśālalocanaṃ pradarśayitvā bhayamohamūrchitā
sudāruṇaṃ vākyam abhītacāriṇī mahātmanā śūrpaṇakhā virūpitā', null, 3030022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 31 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-31-1', 1, 'Aranya Kanda, Sarga 31, Verse 1', 'ततः शूर्पणखा दीना रावणं लोकरावणम्।
अमात्यमध्ये संक्रुद्धा परुषं वाक्यमब्रवीत्॥', 'tataḥ śūrpaṇakhā dīnā rāvaṇaṃ lokarāvaṇam
amātyamadhye saṃkruddhā paruṣaṃ vākyam abravīt', null, 3031001),
('ramayana-3-31-2', 2, 'Aranya Kanda, Sarga 31, Verse 2', 'प्रमत्तः कामभोगेषु स्वैरवृत्तो निरङ्कुशः।
समुत्पन्नं भयं घोरं बोद्धव्यं नावबुध्यसे॥', 'pramattaḥ kāmabhogeṣu svairavṛtto niraṅkuśaḥ
samutpannaṃ bhayaṃ ghoraṃ boddhavyaṃ nāvabudhyase', null, 3031002),
('ramayana-3-31-3', 3, 'Aranya Kanda, Sarga 31, Verse 3', 'सक्तं ग्राम्येषु भोगेषु कामवृत्तं महीपतिम्।
लुब्धं न बहु मन्यन्ते श्मशानाग्निमिव प्रजाः॥', 'saktaṃ grāmyeṣu bhogeṣu kāmavṛttaṃ mahīpatim
lubdhaṃ na bahu manyante śmaśānāgnim iva prajāḥ', null, 3031003),
('ramayana-3-31-4', 4, 'Aranya Kanda, Sarga 31, Verse 4', 'स्वयं कार्याणि यः काले नानुतिष्ठति पार्थिवः।
स तु वै सह राज्येन तैश्च कार्यैर्विनश्यति॥', 'svayaṃ kāryāṇi yaḥ kāle nānutiṣṭhati pārthivaḥ
sa tu vai saha rājyena taiś ca kāryair vinaśyati', null, 3031004),
('ramayana-3-31-5', 5, 'Aranya Kanda, Sarga 31, Verse 5', 'अयुक्तचारं दुर्दर्शमस्वाधीनं नराधिपम्।
वर्जयन्ति नरा दूरान्नदीपङ्कमिव द्विपाः॥', 'ayuktacāraṃ durdarśam asvādhīnaṃ narādhipam
varjayanti narā dūrān nadīpaṅkam iva dvipāḥ', null, 3031005),
('ramayana-3-31-6', 6, 'Aranya Kanda, Sarga 31, Verse 6', 'ये न रक्षन्ति विषयमस्वाधीना नराधिपः।
ते न वृद्ध्या प्रकाशन्ते गिरयः सागरे यथा॥', 'ye na rakṣanti viṣayam asvādhīnā narādhipaḥ
te na vṛddhyā prakāśante girayaḥ sāgare yathā', null, 3031006),
('ramayana-3-31-7', 7, 'Aranya Kanda, Sarga 31, Verse 7', 'आत्मवद्भिर्विगृह्य त्वं देवगन्धर्वदानवैः।
अयुक्तचारश्चपलः कथं राजा भविष्यसि॥', 'ātmavadbhir vigṛhya tvaṃ devagandharvadānavaiḥ
ayuktacāraś capalaḥ kathaṃ rājā bhaviṣyasi', null, 3031007),
('ramayana-3-31-8', 8, 'Aranya Kanda, Sarga 31, Verse 8', 'येषां चारश्च कोशश्च नयश्च जयतां वर।
अस्वाधीना नरेन्द्राणां प्राकृतैस्ते जनैः समाः॥', 'yeṣāṃ cāraś ca kośaś ca nayaś ca jayatāṃ vara
asvādhīnā narendrāṇāṃ prākṛtais te janaiḥ samāḥ', null, 3031008),
('ramayana-3-31-9', 9, 'Aranya Kanda, Sarga 31, Verse 9', 'यस्मात्पश्यन्ति दूरस्थान्सर्वानर्थान्नराधिपाः।
चारेण तस्मादुच्यन्ते राजानो दीर्घचक्षुषः॥', 'yasmāt paśyanti dūrasthān sarvān arthān narādhipāḥ
cāreṇa tasmād ucyante rājāno dīrghacakṣuṣaḥ', null, 3031009),
('ramayana-3-31-10', 10, 'Aranya Kanda, Sarga 31, Verse 10', 'अयुक्तचारं मन्ये त्वां प्राकृतैः सचिवैर्वृतम्।
स्वजनं च जनस्थानं हतं यो नावबुध्यसे॥', 'ayuktacāraṃ manye tvāṃ prākṛtaiḥ sacivair vṛtam
svajanaṃ ca janasthānaṃ hataṃ yo nāvabudhyase', null, 3031010),
('ramayana-3-31-11', 11, 'Aranya Kanda, Sarga 31, Verse 11', 'चतुर्दश सहस्राणि रक्षसां भीमकर्मणाम्।
हतान्येकेन रामेण खरश्च सहदूषणः॥', 'caturdaśa sahasrāṇi rakṣasāṃ bhīmakarmaṇām
hatāny ekena rāmeṇa kharaś ca sahadūṣaṇaḥ', null, 3031011),
('ramayana-3-31-12', 12, 'Aranya Kanda, Sarga 31, Verse 12', 'ऋषीणामभयं दत्तं कृतक्षेमाश्च दण्डकाः।
धर्षितं च जनस्थानं रामेणाक्लिष्टकर्मणा॥', 'ṛṣīṇām abhayaṃ dattaṃ kṛtakṣemāś ca daṇḍakāḥ
dharṣitaṃ ca janasthānaṃ rāmeṇākliṣṭakarmaṇā', null, 3031012),
('ramayana-3-31-13', 13, 'Aranya Kanda, Sarga 31, Verse 13', 'त्वं तु लुब्धः प्रमत्तश्च पराधीनश्च रावण।
विषये स्वे समुत्पन्नं भयं यो नावबुध्यसे॥', 'tvaṃ tu lubdhaḥ pramattaś ca parādhīnaś ca rāvaṇa
viṣaye sve samutpannaṃ bhayaṃ yo nāvabudhyase', null, 3031013),
('ramayana-3-31-14', 14, 'Aranya Kanda, Sarga 31, Verse 14', 'तीक्ष्णमल्पप्रदातारं प्रमत्तं गर्वितं शठम्।
व्यसने सर्वभूतानि नाभिधावन्ति पार्थिवम्॥', 'tīkṣṇam alpapradātāraṃ pramattaṃ garvitaṃ śaṭham
vyasane sarvabhūtāni nābhidhāvanti pārthivam', null, 3031014),
('ramayana-3-31-15', 15, 'Aranya Kanda, Sarga 31, Verse 15', 'अतिमानिनमग्राह्यमात्मसंभावितं नरम्।
क्रोधनं व्यसने हन्ति स्वजनोऽपि नराधिपम्॥', 'atimāninam agrāhyam ātmasaṃbhāvitaṃ naram
krodhanaṃ vyasane hanti svajano ''pi narādhipam', null, 3031015),
('ramayana-3-31-16', 16, 'Aranya Kanda, Sarga 31, Verse 16', 'नानुतिष्ठति कार्याणि भयेषु न बिभेति च।
क्षिप्रं राज्याच्च्युतो दीनस्तृणैस्तुल्यो भविष्यति॥', 'nānutiṣṭhati kāryāṇi bhayeṣu na bibheti ca
kṣipraṃ rājyāc cyuto dīnas tṛṇais tulyo bhaviṣyati', null, 3031016),
('ramayana-3-31-17', 17, 'Aranya Kanda, Sarga 31, Verse 17', 'शुष्ककाष्ठैर्भवेत्कार्यं लोष्टैरपि च पांसुभिः।
न तु स्थानात्परिभ्रष्टैः कार्यं स्याद्वसुधाधिपैः॥', 'śuṣkakāṣṭhair bhavet kāryaṃ loṣṭair api ca pāṃsubhiḥ
na tu sthānāt paribhraṣṭaiḥ kāryaṃ syād vasudhādhipaiḥ', null, 3031017),
('ramayana-3-31-18', 18, 'Aranya Kanda, Sarga 31, Verse 18', 'उपभुक्तं यथा वासः स्रजो वा मृदिता यथा।
एवं राज्यात्परिभ्रष्टः समर्थोऽपि निरर्थकः॥', 'upabhuktaṃ yathā vāsaḥ srajo vā mṛditā yathā
evaṃ rājyāt paribhraṣṭaḥ samartho ''pi nirarthakaḥ', null, 3031018),
('ramayana-3-31-19', 19, 'Aranya Kanda, Sarga 31, Verse 19', 'अप्रमत्तश्च यो राजा सर्वज्ञो विजितेन्द्रियः।
कृतज्ञो धर्मशीलश्च स राजा तिष्ठते चिरम्॥', 'apramattaś ca yo rājā sarvajño vijitendriyaḥ
kṛtajño dharmaśīlaś ca sa rājā tiṣṭhate ciram', null, 3031019),
('ramayana-3-31-20', 20, 'Aranya Kanda, Sarga 31, Verse 20', 'नयनाभ्यां प्रसुप्तोऽपि जागर्ति नयचक्षुषा।
व्यक्तक्रोधप्रसादश्च स राजा पूज्यते जनैः॥', 'nayanābhyāṃ prasupto ''pi jāgarti nayacakṣuṣā
vyaktakrodhaprasādaś ca sa rājā pūjyate janaiḥ', null, 3031020),
('ramayana-3-31-21', 21, 'Aranya Kanda, Sarga 31, Verse 21', 'त्वं तु रावणदुर्बुद्धिर्गुणैरेतैर्विवर्जितः।
यस्य तेऽविदितश्चारै रक्षसां सुमहान्वधः॥', 'tvaṃ tu rāvaṇadurbuddhir guṇair etair vivarjitaḥ
yasya te ''viditaś cārai rakṣasāṃ sumahān vadhaḥ', null, 3031021),
('ramayana-3-31-22', 22, 'Aranya Kanda, Sarga 31, Verse 22', 'परावमन्ता विषयेषु संगतो नदेश कालप्रविभाग तत्त्ववित्।
अयुक्तबुद्धिर्गुणदोषनिश्चये विपन्नराज्यो न चिराद्विपत्स्यते॥', 'parāvamantā viṣayeṣu saṃgato nadeśa kālapravibhāga tattvavit
ayuktabuddhir guṇadoṣaniścaye vipannarājyo na cirād vipatsyate', null, 3031022),
('ramayana-3-31-23', 23, 'Aranya Kanda, Sarga 31, Verse 23', 'इति स्वदोषान्परिकीर्तितांस्तया समीक्ष्य बुद्ध्या क्षणदाचरेश्वरः।
धनेन दर्पेण बलेन चान्वितो विचिन्तयामास चिरं स रावणः॥', 'iti svadoṣān parikīrtitāṃs tayā samīkṣya buddhyā kṣaṇadācareśvaraḥ
dhanena darpeṇa balena cānvito vicintayām āsa ciraṃ sa rāvaṇaḥ', null, 3031023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 32 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-32-1', 1, 'Aranya Kanda, Sarga 32, Verse 1', 'ततः शूर्पणखां क्रुद्धां ब्रुवतीं परुषं वचः।
अमात्यमध्ये संक्रुद्धः परिपप्रच्छ रावणः॥', 'tataḥ śūrpaṇakhāṃ kruddhāṃ bruvatīṃ paruṣaṃ vacaḥ
amātyamadhye saṃkruddhaḥ paripapraccha rāvaṇaḥ', null, 3032001),
('ramayana-3-32-2', 2, 'Aranya Kanda, Sarga 32, Verse 2', 'कश्च रामः कथं वीर्यः किं रूपः किं पराक्रमः।
किमर्थं दण्डकारण्यं प्रविष्टश्च सुदुश्चरम्॥', 'kaś ca rāmaḥ kathaṃ vīryaḥ kiṃ rūpaḥ kiṃ parākramaḥ
kimarthaṃ daṇḍakāraṇyaṃ praviṣṭaś ca suduścaram', null, 3032002),
('ramayana-3-32-3', 3, 'Aranya Kanda, Sarga 32, Verse 3', 'आयुधं किं च रामस्य निहता येन राक्षसाः।
खरश्च निहतं संख्ये दूषणस्त्रिशिरास्तथा॥', 'āyudhaṃ kiṃ ca rāmasya nihatā yena rākṣasāḥ
kharaś ca nihataṃ saṃkhye dūṣaṇas triśirās tathā', null, 3032003),
('ramayana-3-32-4', 4, 'Aranya Kanda, Sarga 32, Verse 4', 'इत्युक्ता राक्षसेन्द्रेण राक्षसी क्रोधमूर्छिता।
ततो रामं यथान्यायमाख्यातुमुपचक्रमे॥', 'ity uktā rākṣasendreṇa rākṣasī krodhamūrchitā
tato rāmaṃ yathānyāyam ākhyātum upacakrame', null, 3032004),
('ramayana-3-32-5', 5, 'Aranya Kanda, Sarga 32, Verse 5', 'दीर्घबाहुर्विशालाक्षश्चीरकृष्णाजिनाम्बरः।
कन्दर्पसमरूपश्च रामो दशरथात्मजः॥', 'dīrghabāhur viśālākṣaś cīrakṛṣṇājināmbaraḥ
kandarpasamarūpaś ca rāmo daśarathātmajaḥ', null, 3032005),
('ramayana-3-32-6', 6, 'Aranya Kanda, Sarga 32, Verse 6', 'शक्रचापनिभं चापं विकृष्य कनकाङ्गदम्।
दीप्तान्क्षिपति नाराचान्सर्पानिव महाविषान्॥', 'śakracāpanibhaṃ cāpaṃ vikṛṣya kanakāṅgadam
dīptān kṣipati nārācān sarpān iva mahāviṣān', null, 3032006),
('ramayana-3-32-7', 7, 'Aranya Kanda, Sarga 32, Verse 7', 'नाददानं शरान्घोरान्न मुञ्चन्तं महाबलम्।
न कार्मुकं विकर्षन्तं रामं पश्यामि संयुगे॥', 'nādadānaṃ śarān ghorān na muñcantaṃ mahābalam
na kārmukaṃ vikarṣantaṃ rāmaṃ paśyāmi saṃyuge', null, 3032007),
('ramayana-3-32-8', 8, 'Aranya Kanda, Sarga 32, Verse 8', 'हन्यमानं तु तत्सैन्यं पश्यामि शरवृष्टिभिः।
इन्द्रेणैवोत्तमं सस्यमाहतं त्वश्मवृष्टिभिः॥', 'hanyamānaṃ tu tat sainyaṃ paśyāmi śaravṛṣṭibhiḥ
indreṇaivottamaṃ sasyam āhataṃ tv aśmavṛṣṭibhiḥ', null, 3032008),
('ramayana-3-32-9', 9, 'Aranya Kanda, Sarga 32, Verse 9', 'रक्षसां भीमवीर्याणां सहस्राणि चतुर्दश।
निहतानि शरैस्तीक्ष्णैस्तेनैकेन पदातिना॥', 'rakṣasāṃ bhīmavīryāṇāṃ sahasrāṇi caturdaśa
nihatāni śarais tīkṣṇais tenaikena padātinā', null, 3032009),
('ramayana-3-32-10', 10, 'Aranya Kanda, Sarga 32, Verse 10', 'अर्धाधिकमुहूर्तेन खरश्च सहदूषणः।
ऋषीणामभयं दत्तं कृतक्षेमाश्च दण्डकाः॥', 'ardhādhikamuhūrtena kharaś ca sahadūṣaṇaḥ
ṛṣīṇām abhayaṃ dattaṃ kṛtakṣemāś ca daṇḍakāḥ', null, 3032010),
('ramayana-3-32-11', 11, 'Aranya Kanda, Sarga 32, Verse 11', 'एका कथं चिन्मुक्ताहं परिभूय महात्मना।
स्त्रीवधं शङ्कमानेन रामेण विदितात्मना॥', 'ekā kathaṃ cin muktāhaṃ paribhūya mahātmanā
strīvadhaṃ śaṅkamānena rāmeṇa viditātmanā', null, 3032011),
('ramayana-3-32-12', 12, 'Aranya Kanda, Sarga 32, Verse 12', 'भ्राता चास्य महातेजा गुणतस्तुल्यविक्रमः।
अनुरक्तश्च भक्तश्च लक्ष्मणो नाम वीर्यवान्॥', 'bhrātā cāsya mahātejā guṇatas tulyavikramaḥ
anuraktaś ca bhaktaś ca lakṣmaṇo nāma vīryavān', null, 3032012),
('ramayana-3-32-13', 13, 'Aranya Kanda, Sarga 32, Verse 13', 'अमर्षी दुर्जयो जेता विक्रान्तो बुद्धिमान्बली।
रामस्य दक्षिणे बाहुर्नित्यं प्राणो बहिष्चरः॥', 'amarṣī durjayo jetā vikrānto buddhimān balī
rāmasya dakṣiṇe bāhur nityaṃ prāṇo bahiṣcaraḥ', null, 3032013),
('ramayana-3-32-14', 14, 'Aranya Kanda, Sarga 32, Verse 14', 'रामस्य तु विशालाक्षी धर्मपत्नी यशस्विनी।
सीता नाम वरारोहा वैदेही तनुमध्यमा॥', 'rāmasya tu viśālākṣī dharmapatnī yaśasvinī
sītā nāma varārohā vaidehī tanumadhyamā', null, 3032014),
('ramayana-3-32-15', 15, 'Aranya Kanda, Sarga 32, Verse 15', 'नैव देवी न गन्धर्वा न यक्षी न च किंनरी।
तथारूपा मया नारी दृष्टपूर्वा महीतले॥', 'naiva devī na gandharvā na yakṣī na ca kiṃnarī
tathārūpā mayā nārī dṛṣṭapūrvā mahītale', null, 3032015),
('ramayana-3-32-16', 16, 'Aranya Kanda, Sarga 32, Verse 16', 'यस्य सीता भवेद्भार्या यं च हृष्टा परिष्वजेत्।
अतिजीवेत्स सर्वेषु लोकेष्वपि पुरंदरात्॥', 'yasya sītā bhaved bhāryā yaṃ ca hṛṣṭā pariṣvajet
atijīvet sa sarveṣu lokeṣv api puraṃdarāt', null, 3032016),
('ramayana-3-32-17', 17, 'Aranya Kanda, Sarga 32, Verse 17', 'सा सुशीला वपुःश्लाघ्या रूपेणाप्रतिमा भुवि।
तवानुरूपा भार्या सा त्वं च तस्यास्तथा पतिः॥', 'sā suśīlā vapuḥślāghyā rūpeṇāpratimā bhuvi
tavānurūpā bhāryā sā tvaṃ ca tasyās tathā patiḥ', null, 3032017),
('ramayana-3-32-18', 18, 'Aranya Kanda, Sarga 32, Verse 18', 'तां तु विस्तीर्णजघनां पीनोत्तुङ्गपयोधराम्।
भार्यार्थे तु तवानेतुमुद्यताहं वराननाम्॥', 'tāṃ tu vistīrṇajaghanāṃ pīnottuṅgapayodharām
bhāryārthe tu tavānetum udyatāhaṃ varānanām', null, 3032018),
('ramayana-3-32-19', 19, 'Aranya Kanda, Sarga 32, Verse 19', 'तां तु दृष्ट्वाद्य वैदेहीं पूर्णचन्द्रनिभाननाम्।
मन्मथस्य शराणां च त्वं विधेयो भविष्यसि॥', 'tāṃ tu dṛṣṭvādya vaidehīṃ pūrṇacandranibhānanām
manmathasya śarāṇāṃ ca tvaṃ vidheyo bhaviṣyasi', null, 3032019),
('ramayana-3-32-20', 20, 'Aranya Kanda, Sarga 32, Verse 20', 'यदि तस्यामभिप्रायो भार्यार्थे तव जायते।
शीघ्रमुद्ध्रियतां पादो जयार्थमिह दक्षिणः॥', 'yadi tasyām abhiprāyo bhāryārthe tava jāyate
śīghram uddhriyatāṃ pādo jayārtham iha dakṣiṇaḥ', null, 3032020),
('ramayana-3-32-21', 21, 'Aranya Kanda, Sarga 32, Verse 21', 'कुरु प्रियं तथा तेषां रक्षसां राक्षसेश्वर।
वधात्तस्य नृशंसस्य रामस्याश्रमवासिनः॥', 'kuru priyaṃ tathā teṣāṃ rakṣasāṃ rākṣaseśvara
vadhāt tasya nṛśaṃsasya rāmasyāśramavāsinaḥ', null, 3032021),
('ramayana-3-32-22', 22, 'Aranya Kanda, Sarga 32, Verse 22', 'तं शरैर्निशितैर्हत्वा लक्ष्मणं च महारथम्।
हतनाथां सुखं सीतां यथावदुपभोक्ष्यसे॥', 'taṃ śarair niśitair hatvā lakṣmaṇaṃ ca mahāratham
hatanāthāṃ sukhaṃ sītāṃ yathāvad upabhokṣyase', null, 3032022),
('ramayana-3-32-23', 23, 'Aranya Kanda, Sarga 32, Verse 23', 'रोचते यदि ते वाक्यं ममैतद्राक्षसेश्वर।
क्रियतां निर्विशङ्केन वचनं मम राघव॥', 'rocate yadi te vākyaṃ mamaitad rākṣaseśvara
kriyatāṃ nirviśaṅkena vacanaṃ mama rāghava', null, 3032023),
('ramayana-3-32-24', 24, 'Aranya Kanda, Sarga 32, Verse 24', 'निशम्य रामेण शरैरजिह्मगैर्हताञ्जनस्थानगतान्निशाचरान्।
खरं च बुद्ध्वा निहतं च दूषणं त्वमद्य कृत्यं प्रतिपत्तुमर्हसि॥', 'niśamya rāmeṇa śarair ajihmagair hatāñ janasthānagatān niśācarān
kharaṃ ca buddhvā nihataṃ ca dūṣaṇaṃ tvam adya kṛtyaṃ pratipattum arhasi', null, 3032024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 33 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-33-1', 1, 'Aranya Kanda, Sarga 33, Verse 1', 'ततः शूर्पणखा वाक्यं तच्छ्रुत्वा रोमहर्षणम्।
सचिवानभ्यनुज्ञाय कार्यं बुद्ध्वा जगाम ह॥', 'tataḥ śūrpaṇakhā vākyaṃ tac chrutvā romaharṣaṇam
sacivān abhyanujñāya kāryaṃ buddhvā jagāma ha', null, 3033001),
('ramayana-3-33-2', 2, 'Aranya Kanda, Sarga 33, Verse 2', 'तत्कार्यमनुगम्याथ यथावदुपलभ्य च।
दोषाणां च गुणानां च संप्रधार्य बलाबलम्॥', 'tat kāryam anugamyātha yathāvad upalabhya ca
doṣāṇāṃ ca guṇānāṃ ca saṃpradhārya balābalam', null, 3033002),
('ramayana-3-33-3', 3, 'Aranya Kanda, Sarga 33, Verse 3', 'इति कर्तव्यमित्येव कृत्वा निश्चयमात्मनः।
स्थिरबुद्धिस्ततो रम्यां यानशालां जगाम ह॥', 'iti kartavyam ity eva kṛtvā niścayam ātmanaḥ
sthirabuddhis tato ramyāṃ yānaśālāṃ jagāma ha', null, 3033003),
('ramayana-3-33-4', 4, 'Aranya Kanda, Sarga 33, Verse 4', 'यानशालां ततो गत्वा प्रच्छन्नं राक्षसाधिपः।
सूतं संचोदयामास रथः संयुज्यतामिति॥', 'yānaśālāṃ tato gatvā pracchannaṃ rākṣasādhipaḥ
sūtaṃ saṃcodayām āsa rathaḥ saṃyujyatām iti', null, 3033004),
('ramayana-3-33-5', 5, 'Aranya Kanda, Sarga 33, Verse 5', 'एवमुक्तः क्षणेनैव सारथिर्लघुविक्रमः।
रथं संयोजयामास तस्याभिमतमुत्तमम्॥', 'evam uktaḥ kṣaṇenaiva sārathir laghuvikramaḥ
rathaṃ saṃyojayām āsa tasyābhimatam uttamam', null, 3033005),
('ramayana-3-33-6', 6, 'Aranya Kanda, Sarga 33, Verse 6', 'काञ्चनं रथमास्थाय कामगं रत्नभूषितम्।
पिशाचवदनैर्युक्तं खरैः कनकभूषणैः॥', 'kāñcanaṃ ratham āsthāya kāmagaṃ ratnabhūṣitam
piśācavadanair yuktaṃ kharaiḥ kanakabhūṣaṇaiḥ', null, 3033006),
('ramayana-3-33-7', 7, 'Aranya Kanda, Sarga 33, Verse 7', 'मेघप्रतिमनादेन स तेन धनदानुजः।
राक्षसाधिपतिः श्रीमान्ययौ नदनदीपतिम्॥', 'meghapratimanādena sa tena dhanadānujaḥ
rākṣasādhipatiḥ śrīmān yayau nadanadīpatim', null, 3033007),
('ramayana-3-33-8', 8, 'Aranya Kanda, Sarga 33, Verse 8', 'स श्वेतबालव्यसनः श्वेतच्छत्रो दशाननः।
स्निग्धवैदूर्यसंकाशस्तप्तकाञ्चनभूषणः॥', 'sa śvetabālavyasanaḥ śvetacchatro daśānanaḥ
snigdhavaidūryasaṃkāśas taptakāñcanabhūṣaṇaḥ', null, 3033008),
('ramayana-3-33-9', 9, 'Aranya Kanda, Sarga 33, Verse 9', 'दशास्यो विंशतिभुजो दर्शनीय परिच्छदः।
त्रिदशारिर्मुनीन्द्रघ्नो दशशीर्ष इवाद्रिराट्॥', 'daśāsyo viṃśatibhujo darśanīya paricchadaḥ
tridaśārir munīndraghno daśaśīrṣa ivādrirāṭ', null, 3033009),
('ramayana-3-33-10', 10, 'Aranya Kanda, Sarga 33, Verse 10', 'कामगं रथमास्थाय शुशुभे राक्षसाधिपः।
विद्युन्मण्डलवान्मेघः सबलाक इवाम्बरे॥', 'kāmagaṃ ratham āsthāya śuśubhe rākṣasādhipaḥ
vidyunmaṇḍalavān meghaḥ sabalāka ivāmbare', null, 3033010),
('ramayana-3-33-11', 11, 'Aranya Kanda, Sarga 33, Verse 11', 'सशैलं सागरानूपं वीर्यवानवलोकयन्।
नानापुष्पफलैर्वृक्षैरनुकीर्णं सहस्रशः॥', 'saśailaṃ sāgarānūpaṃ vīryavān avalokayan
nānāpuṣpaphalair vṛkṣair anukīrṇaṃ sahasraśaḥ', null, 3033011),
('ramayana-3-33-12', 12, 'Aranya Kanda, Sarga 33, Verse 12', 'शीतमङ्गलतोयाभिः पद्मिनीभिः समन्ततः।
विशालैराश्रमपदैर्वेदिमद्भिः समावृतम्॥', 'śītamaṅgalatoyābhiḥ padminībhiḥ samantataḥ
viśālair āśramapadair vedimadbhiḥ samāvṛtam', null, 3033012),
('ramayana-3-33-13', 13, 'Aranya Kanda, Sarga 33, Verse 13', 'कदल्याढकिसंबाधं नालिकेरोपशोभितम्।
सालैस्तालैस्तमालैश्च तरुभिश्च सुपुष्पितैः॥', 'kadaly āḍhakisaṃbādhaṃ nālikeropaśobhitam
sālais tālais tamālaiś ca tarubhiś ca supuṣpitaiḥ', null, 3033013),
('ramayana-3-33-14', 14, 'Aranya Kanda, Sarga 33, Verse 14', 'अत्यन्तनियताहारैः शोभितं परमर्षिभिः।
नागैः सुपर्णैर्गन्धर्वैः किंनरैश्च सहस्रशः॥', 'atyantaniyatāhāraiḥ śobhitaṃ paramarṣibhiḥ
nāgaiḥ suparṇair gandharvaiḥ kiṃnaraiś ca sahasraśaḥ', null, 3033014),
('ramayana-3-33-15', 15, 'Aranya Kanda, Sarga 33, Verse 15', 'जितकामैश्च सिद्धैश्च चामणैश्चोपशोभितम्।
आजैर्वैखानसैर्माषैर्वालखिल्यैर्मरीचिपैः॥', 'jitakāmaiś ca siddhaiś ca cāmaṇaiś copaśobhitam
ājair vaikhānasair māṣair vālakhilyair marīcipaiḥ', null, 3033015),
('ramayana-3-33-16', 16, 'Aranya Kanda, Sarga 33, Verse 16', 'दिव्याभरणमाल्याभिर्दिव्यरूपाभिरावृतम्।
क्रीडा रतिविधिज्ञाभिरप्सरोभिः सहस्रशः॥', 'divyābharaṇamālyābhir divyarūpābhir āvṛtam
krīḍā ratividhijñābhir apsarobhiḥ sahasraśaḥ', null, 3033016),
('ramayana-3-33-17', 17, 'Aranya Kanda, Sarga 33, Verse 17', 'सेवितं देवपत्नीभिः श्रीमतीभिः श्रिया वृतम्।
देवदानवसंघैश्च चरितं त्वमृताशिभिः॥', 'sevitaṃ devapatnībhiḥ śrīmatībhiḥ śriyā vṛtam
devadānavasaṃghaiś ca caritaṃ tv amṛtāśibhiḥ', null, 3033017),
('ramayana-3-33-18', 18, 'Aranya Kanda, Sarga 33, Verse 18', 'हंसक्रौञ्चप्लवाकीर्णं सारसैः संप्रणादितम्।
वैदूर्यप्रस्तरं रम्यं स्निग्धं सागरतेजसा॥', 'haṃsakrauñcaplavākīrṇaṃ sārasaiḥ saṃpraṇāditam
vaidūryaprastaraṃ ramyaṃ snigdhaṃ sāgaratejasā', null, 3033018),
('ramayana-3-33-19', 19, 'Aranya Kanda, Sarga 33, Verse 19', 'पाण्डुराणि विशालानि दिव्यमाल्ययुतानि च।
तूर्यगीताभिजुष्टानि विमानानि समन्ततः॥', 'pāṇḍurāṇi viśālāni divyamālyayutāni ca
tūryagītābhijuṣṭāni vimānāni samantataḥ', null, 3033019),
('ramayana-3-33-20', 20, 'Aranya Kanda, Sarga 33, Verse 20', 'तपसा जितलोकानां कामगान्यभिसंपतन्।
गन्धर्वाप्सरसश्चैव ददर्श धनदानुजः॥', 'tapasā jitalokānāṃ kāmagāny abhisaṃpatan
gandharvāpsarasaś caiva dadarśa dhanadānujaḥ', null, 3033020),
('ramayana-3-33-21', 21, 'Aranya Kanda, Sarga 33, Verse 21', 'निर्यासरसमूलानां चन्दनानां सहस्रशः।
वनानि पश्यन्सौम्यानि घ्राणतृप्तिकराणि च॥', 'niryāsarasamūlānāṃ candanānāṃ sahasraśaḥ
vanāni paśyan saumyāni ghrāṇatṛptikarāṇi ca', null, 3033021),
('ramayana-3-33-22', 22, 'Aranya Kanda, Sarga 33, Verse 22', 'अगरूणां च मुख्यानां वनान्युपवनानि च।
तक्कोलानां च जात्यानां फलानां च सुगन्धिनाम्॥', 'agarūṇāṃ ca mukhyānāṃ vanāny upavanāni ca
takkolānāṃ ca jātyānāṃ phalānāṃ ca sugandhinām', null, 3033022),
('ramayana-3-33-23', 23, 'Aranya Kanda, Sarga 33, Verse 23', 'पुष्पाणि च तमालस्य गुल्मानि मरिचस्य च।
मुक्तानां च समूहानि शुष्यमाणानि तीरतः॥', 'puṣpāṇi ca tamālasya gulmāni maricasya ca
muktānāṃ ca samūhāni śuṣyamāṇāni tīrataḥ', null, 3033023),
('ramayana-3-33-24', 24, 'Aranya Kanda, Sarga 33, Verse 24', 'शङ्खानां प्रस्तरं चैव प्रवालनिचयं तथा।
काञ्चनानि च शैलानि राजतानि च सर्वशः॥', 'śaṅkhānāṃ prastaraṃ caiva pravālanicayaṃ tathā
kāñcanāni ca śailāni rājatāni ca sarvaśaḥ', null, 3033024),
('ramayana-3-33-25', 25, 'Aranya Kanda, Sarga 33, Verse 25', 'प्रस्रवाणि मनोज्ञानि प्रसन्नानि ह्रदानि च।
धनधान्योपपन्नानि स्त्रीरत्नैरावृतानि च॥', 'prasravāṇi manojñāni prasannāni hradāni ca
dhanadhānyopapannāni strīratnair āvṛtāni ca', null, 3033025),
('ramayana-3-33-26', 26, 'Aranya Kanda, Sarga 33, Verse 26', 'हस्त्यश्वरथगाढानि नगराण्यवलोकयन्।
तं समं सर्वतः स्निग्धं मृदुसंस्पर्शमारुतम्॥', 'hastyaśvarathagāḍhāni nagarāṇy avalokayan
taṃ samaṃ sarvataḥ snigdhaṃ mṛdusaṃsparśamārutam', null, 3033026),
('ramayana-3-33-27', 27, 'Aranya Kanda, Sarga 33, Verse 27', 'अनूपं सिन्धुराजस्य ददर्श त्रिदिवोपमम्।
तत्रापश्यत्स मेघाभं न्यग्रोधमृषिभिर्वृतम्॥', 'anūpaṃ sindhurājasya dadarśa tridivopamam
tatrāpaśyat sa meghābhaṃ nyagrodham ṛṣibhir vṛtam', null, 3033027),
('ramayana-3-33-28', 28, 'Aranya Kanda, Sarga 33, Verse 28', 'समन्ताद्यस्य ताः शाखाः शतयोजनमायताः।
यस्य हस्तिनमादाय महाकायं च कच्चपम्।
भक्षार्थं गरुडः शाखामाजगाम महाबलः॥', 'samantād yasya tāḥ śākhāḥ śatayojanam āyatāḥ
yasya hastinam ādāya mahākāyaṃ ca kaccapam
bhakṣārthaṃ garuḍaḥ śākhām ājagāma mahābalaḥ', null, 3033028),
('ramayana-3-33-29', 29, 'Aranya Kanda, Sarga 33, Verse 29', 'तस्य तां सहसा शाखां भारेण पतगोत्तमः।
सुपर्णः पर्णबहुलां बभञ्जाथ महाबलः॥', 'tasya tāṃ sahasā śākhāṃ bhāreṇa patagottamaḥ
suparṇaḥ parṇabahulāṃ babhañjātha mahābalaḥ', null, 3033029),
('ramayana-3-33-30', 30, 'Aranya Kanda, Sarga 33, Verse 30', 'तत्र वैखानसा माषा वालखिल्या मरीचिपाः।
अजा बभूवुर्धूम्राश्च संगताः परमर्षयः॥', 'tatra vaikhānasā māṣā vālakhilyā marīcipāḥ
ajā babhūvur dhūmrāś ca saṃgatāḥ paramarṣayaḥ', null, 3033030),
('ramayana-3-33-31', 31, 'Aranya Kanda, Sarga 33, Verse 31', 'तेषां दयार्थं गरुडस्तां शाखां शतयोजनाम्।
जगामादाय वेगेन तौ चोभौ गजकच्छपौ॥', 'teṣāṃ dayārthaṃ garuḍas tāṃ śākhāṃ śatayojanām
jagāmādāya vegena tau cobhau gajakacchapau', null, 3033031),
('ramayana-3-33-32', 32, 'Aranya Kanda, Sarga 33, Verse 32', 'एकपादेन धर्मात्मा भक्षयित्वा तदामिषम्।
निषादविषयं हत्वा शाखया पतगोत्तमः।
प्रहर्षमतुलं लेभे मोक्षयित्वा महामुनीन्॥', 'ekapādena dharmātmā bhakṣayitvā tad āmiṣam
niṣādaviṣayaṃ hatvā śākhayā patagottamaḥ
praharṣam atulaṃ lebhe mokṣayitvā mahāmunīn', null, 3033032),
('ramayana-3-33-33', 33, 'Aranya Kanda, Sarga 33, Verse 33', 'स तेनैव प्रहर्षेण द्विगुणीकृतविक्रमः।
अमृतानयनार्थं वै चकार मतिमान्मतिम्॥', 'sa tenaiva praharṣeṇa dviguṇīkṛtavikramaḥ
amṛtānayanārthaṃ vai cakāra matimān matim', null, 3033033),
('ramayana-3-33-34', 34, 'Aranya Kanda, Sarga 33, Verse 34', 'अयोजालानि निर्मथ्य भित्त्वा रत्नगृहं वरम्।
महेन्द्रभवनाद्गुप्तमाजहारामृतं ततः॥', 'ayojālāni nirmathya bhittvā ratnagṛhaṃ varam
mahendrabhavanād guptam ājahārāmṛtaṃ tataḥ', null, 3033034),
('ramayana-3-33-35', 35, 'Aranya Kanda, Sarga 33, Verse 35', 'तं महर्षिगणैर्जुष्टं सुपर्णकृतलक्षणम्।
नाम्ना सुभद्रं न्यग्रोधं ददर्श धनदानुजः॥', 'taṃ maharṣigaṇair juṣṭaṃ suparṇakṛtalakṣaṇam
nāmnā subhadraṃ nyagrodhaṃ dadarśa dhanadānujaḥ', null, 3033035),
('ramayana-3-33-36', 36, 'Aranya Kanda, Sarga 33, Verse 36', 'तं तु गत्वा परं पारं समुद्रस्य नदीपतेः।
ददर्शाश्रममेकान्ते पुण्ये रम्ये वनान्तरे॥', 'taṃ tu gatvā paraṃ pāraṃ samudrasya nadīpateḥ
dadarśāśramam ekānte puṇye ramye vanāntare', null, 3033036),
('ramayana-3-33-37', 37, 'Aranya Kanda, Sarga 33, Verse 37', 'तत्र कृष्णाजिनधरं जटावल्कलधारिणम्।
ददर्श नियताहारं मारीचं नाम राक्षसं॥', 'tatra kṛṣṇājinadharaṃ jaṭāvalkaladhāriṇam
dadarśa niyatāhāraṃ mārīcaṃ nāma rākṣasaṃ', null, 3033037),
('ramayana-3-33-38', 38, 'Aranya Kanda, Sarga 33, Verse 38', 'स रावणः समागम्य विधिवत्तेन रक्षसा।
ततः पश्चादिदं वाक्यमब्रवीद्वाक्यकोविदः॥', 'sa rāvaṇaḥ samāgamya vidhivat tena rakṣasā
tataḥ paścād idaṃ vākyam abravīd vākyakovidaḥ', null, 3033038)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 34 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-34-1', 1, 'Aranya Kanda, Sarga 34, Verse 1', 'मारीच श्रूयतां तात वचनं मम भाषतः।
आर्तोऽस्मि मम चार्तस्य भवान्हि परमा गतिः॥', 'mārīca śrūyatāṃ tāta vacanaṃ mama bhāṣataḥ
ārto ''smi mama cārtasya bhavān hi paramā gatiḥ', null, 3034001),
('ramayana-3-34-2', 2, 'Aranya Kanda, Sarga 34, Verse 2', 'जानीषे त्वं जनस्थानं भ्राता यत्र खरो मम।
दूषणश्च महाबाहुः स्वसा शूर्पणखा च मे॥', 'jānīṣe tvaṃ janasthānaṃ bhrātā yatra kharo mama
dūṣaṇaś ca mahābāhuḥ svasā śūrpaṇakhā ca me', null, 3034002),
('ramayana-3-34-3', 3, 'Aranya Kanda, Sarga 34, Verse 3', 'त्रिशिराश्च महातेजा राक्षसः पिशिताशनः।
अन्ये च बहवः शूरा लब्धलक्षा निशाचराः॥', 'triśirāś ca mahātejā rākṣasaḥ piśitāśanaḥ
anye ca bahavaḥ śūrā labdhalakṣā niśācarāḥ', null, 3034003),
('ramayana-3-34-4', 4, 'Aranya Kanda, Sarga 34, Verse 4', 'वसन्ति मन्नियोगेन अधिवासं च राक्षसः।
बाधमाना महारण्ये मुनीन्ये धर्मचारिणः॥', 'vasanti manniyogena adhivāsaṃ ca rākṣasaḥ
bādhamānā mahāraṇye munīn ye dharmacāriṇaḥ', null, 3034004),
('ramayana-3-34-5', 5, 'Aranya Kanda, Sarga 34, Verse 5', 'चतुर्दश सहस्राणि रक्षसां भीमकर्मणाम्।
शूराणां लब्धलक्षाणां खरचित्तानुवर्तिनाम्॥', 'caturdaśa sahasrāṇi rakṣasāṃ bhīmakarmaṇām
śūrāṇāṃ labdhalakṣāṇāṃ kharacittānuvartinām', null, 3034005),
('ramayana-3-34-6', 6, 'Aranya Kanda, Sarga 34, Verse 6', 'ते त्विदानीं जनस्थाने वसमाना महाबलाः।
संगताः परमायत्ता रामेण सह संयुगे॥', 'te tv idānīṃ janasthāne vasamānā mahābalāḥ
saṃgatāḥ param āyattā rāmeṇa saha saṃyuge', null, 3034006),
('ramayana-3-34-7', 7, 'Aranya Kanda, Sarga 34, Verse 7', 'तेन संजातरोषेण रामेण रणमूर्धनि।
अनुक्त्वा परुषं किं चिच्छरैर्व्यापारितं धनुः॥', 'tena saṃjātaroṣeṇa rāmeṇa raṇamūrdhani
anuktvā paruṣaṃ kiṃ cic charair vyāpāritaṃ dhanuḥ', null, 3034007),
('ramayana-3-34-8', 8, 'Aranya Kanda, Sarga 34, Verse 8', 'चतुर्दश सहस्राणि रक्षसां भीमकर्मणाम्।
निहतानि शरैस्तीक्ष्णैर्मानुषेण पदातिना॥', 'caturdaśa sahasrāṇi rakṣasāṃ bhīmakarmaṇām
nihatāni śarais tīkṣṇair mānuṣeṇa padātinā', null, 3034008),
('ramayana-3-34-9', 9, 'Aranya Kanda, Sarga 34, Verse 9', 'खरश्च निहतः संख्ये दूषणश्च निपातितः।
हत्वा त्रिशिरसं चापि निर्भया दण्डकाः कृताः॥', 'kharaś ca nihataḥ saṃkhye dūṣaṇaś ca nipātitaḥ
hatvā triśirasaṃ cāpi nirbhayā daṇḍakāḥ kṛtāḥ', null, 3034009),
('ramayana-3-34-10', 10, 'Aranya Kanda, Sarga 34, Verse 10', 'पित्रा निरस्तः क्रुद्धेन सभार्यः क्षीणजीवितः।
स हन्ता तस्य सैन्यस्य रामः क्षत्रियपांसनः॥', 'pitrā nirastaḥ kruddhena sabhāryaḥ kṣīṇajīvitaḥ
sa hantā tasya sainyasya rāmaḥ kṣatriyapāṃsanaḥ', null, 3034010),
('ramayana-3-34-11', 11, 'Aranya Kanda, Sarga 34, Verse 11', 'अशीलः कर्कशस्तीक्ष्णो मूर्खो लुब्धोऽजितेन्द्रियः।
त्यक्तधर्मस्त्वधर्मात्मा भूतानामहिते रतः॥', 'aśīlaḥ karkaśas tīkṣṇo mūrkho lubdho ''jitendriyaḥ
tyaktadharmas tv adharmātmā bhūtānām ahite rataḥ', null, 3034011),
('ramayana-3-34-12', 12, 'Aranya Kanda, Sarga 34, Verse 12', 'येन वैरं विनारण्ये सत्त्वमाश्रित्य केवलम्।
कर्णनासापहारेण भगिनी मे विरूपिता॥', 'yena vairaṃ vināraṇye sattvam āśritya kevalam
karṇanāsāpahāreṇa bhaginī me virūpitā', null, 3034012),
('ramayana-3-34-13', 13, 'Aranya Kanda, Sarga 34, Verse 13', 'तस्य भार्यां जनस्थानात्सीतां सुरसुतोपमाम्।
आनयिष्यामि विक्रम्य सहायस्तत्र मे भव॥', 'tasya bhāryāṃ janasthānāt sītāṃ surasutopamām
ānayiṣyāmi vikramya sahāyas tatra me bhava', null, 3034013),
('ramayana-3-34-14', 14, 'Aranya Kanda, Sarga 34, Verse 14', 'त्वया ह्यहं सहायेन पार्श्वस्थेन महाबल।
भ्रातृभिश्च सुरान्युद्धे समग्रान्नाभिचिन्तये॥', 'tvayā hy ahaṃ sahāyena pārśvasthena mahābala
bhrātṛbhiś ca surān yuddhe samagrān nābhicintaye', null, 3034014),
('ramayana-3-34-15', 15, 'Aranya Kanda, Sarga 34, Verse 15', 'तत्सहायो भव त्वं मे समर्थो ह्यसि राक्षस।
वीर्ये युद्धे च दर्पे च न ह्यस्ति सदृशस्तव॥', 'tat sahāyo bhava tvaṃ me samartho hy asi rākṣasa
vīrye yuddhe ca darpe ca na hy asti sadṛśas tava', null, 3034015),
('ramayana-3-34-16', 16, 'Aranya Kanda, Sarga 34, Verse 16', 'एतदर्थमहं प्राप्तस्त्वत्समीपं निशाचर।
शृणु तत्कर्म साहाय्ये यत्कार्यं वचनान्मम॥', 'etadartham ahaṃ prāptas tvatsamīpaṃ niśācara
śṛṇu tat karma sāhāyye yat kāryaṃ vacanān mama', null, 3034016),
('ramayana-3-34-17', 17, 'Aranya Kanda, Sarga 34, Verse 17', 'सौवर्णस्त्वं मृगो भूत्वा चित्रो रजतबिन्दुभिः।
आश्रमे तस्य रामस्य सीतायाः प्रमुखे चर॥', 'sauvarṇas tvaṃ mṛgo bhūtvā citro rajatabindubhiḥ
āśrame tasya rāmasya sītāyāḥ pramukhe cara', null, 3034017),
('ramayana-3-34-18', 18, 'Aranya Kanda, Sarga 34, Verse 18', 'त्वां तु निःसंशयं सीता दृष्ट्वा तु मृगरूपिणम्।
गृह्यतामिति भर्तारं लक्ष्मणं चाभिधास्यति॥', 'tvāṃ tu niḥsaṃśayaṃ sītā dṛṣṭvā tu mṛgarūpiṇam
gṛhyatām iti bhartāraṃ lakṣmaṇaṃ cābhidhāsyati', null, 3034018),
('ramayana-3-34-19', 19, 'Aranya Kanda, Sarga 34, Verse 19', 'ततस्तयोरपाये तु शून्ये सीतां यथासुखम्।
निराबाधो हरिष्यामि राहुश्चन्द्रप्रभामिव॥', 'tatas tayor apāye tu śūnye sītāṃ yathāsukham
nirābādho hariṣyāmi rāhuś candraprabhām iva', null, 3034019),
('ramayana-3-34-20', 20, 'Aranya Kanda, Sarga 34, Verse 20', 'ततः पश्चात्सुखं रामे भार्याहरणकर्शिते।
विस्रब्धं प्रहरिष्यामि कृतार्थेनान्तरात्मना॥', 'tataḥ paścāt sukhaṃ rāme bhāryāharaṇakarśite
visrabdhaṃ prahariṣyāmi kṛtārthenāntarātmanā', null, 3034020),
('ramayana-3-34-21', 21, 'Aranya Kanda, Sarga 34, Verse 21', 'तस्य रामकथां श्रुत्वा मारीचस्य महात्मनः।
शुष्कं समभवद्वक्त्रं परित्रस्तो बभूव च॥', 'tasya rāmakathāṃ śrutvā mārīcasya mahātmanaḥ
śuṣkaṃ samabhavad vaktraṃ paritrasto babhūva ca', null, 3034021),
('ramayana-3-34-22', 22, 'Aranya Kanda, Sarga 34, Verse 22', 'स रावणं त्रस्तविषण्णचेता महावने रामपराक्रमज्ञः।
कृताञ्जलिस्तत्त्वमुवाच वाक्यं हितं च तस्मै हितमात्मनश्च॥', 'sa rāvaṇaṃ trastaviṣaṇṇacetā mahāvane rāmaparākramajñaḥ
kṛtāñjalis tattvam uvāca vākyaṃ hitaṃ ca tasmai hitam ātmanaś ca', null, 3034022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 35 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-35-1', 1, 'Aranya Kanda, Sarga 35, Verse 1', 'तच्छ्रुत्वा राक्षसेन्द्रस्य वाक्यं वाक्यविशारदः।
प्रत्युवाच महाप्राज्ञो मारीचो राक्षसेश्वरम्॥', 'tac chrutvā rākṣasendrasya vākyaṃ vākyaviśāradaḥ
pratyuvāca mahāprājño mārīco rākṣaseśvaram', null, 3035001),
('ramayana-3-35-2', 2, 'Aranya Kanda, Sarga 35, Verse 2', 'सुलभाः पुरुषा राजन्सततं प्रियवादिनः।
अप्रियस्य च पथ्यस्य वक्ता श्रोता च दुर्लभः॥', 'sulabhāḥ puruṣā rājan satataṃ priyavādinaḥ
apriyasya ca pathyasya vaktā śrotā ca durlabhaḥ', null, 3035002),
('ramayana-3-35-3', 3, 'Aranya Kanda, Sarga 35, Verse 3', 'न नूनं बुध्यसे रामं महावीर्यं गुणोन्नतम्।
अयुक्तचारश्चपलो महेन्द्रवरुणोपमम्॥', 'na nūnaṃ budhyase rāmaṃ mahāvīryaṃ guṇonnatam
ayuktacāraś capalo mahendravaruṇopamam', null, 3035003),
('ramayana-3-35-4', 4, 'Aranya Kanda, Sarga 35, Verse 4', 'अपि स्वस्ति भवेत्तात सर्वेषां भुवि रक्षसाम्।
अपि रामो न संक्रुद्धः कुर्याल्लोकमराक्षसं॥', 'api svasti bhavet tāta sarveṣāṃ bhuvi rakṣasām
api rāmo na saṃkruddhaḥ kuryāl lokam arākṣasaṃ', null, 3035004),
('ramayana-3-35-5', 5, 'Aranya Kanda, Sarga 35, Verse 5', 'अपि ते जीवितान्ताय नोत्पन्ना जनकात्मजा।
अपि सीता निमित्तं च न भवेद्व्यसनं महत्॥', 'api te jīvitāntāya notpannā janakātmajā
api sītā nimittaṃ ca na bhaved vyasanaṃ mahat', null, 3035005),
('ramayana-3-35-6', 6, 'Aranya Kanda, Sarga 35, Verse 6', 'अपि त्वामीश्वरं प्राप्य कामवृत्तं निरङ्कुशम्।
न विनश्येत्पुरी लङ्का त्वया सह सराक्षसा॥', 'api tvām īśvaraṃ prāpya kāmavṛttaṃ niraṅkuśam
na vinaśyet purī laṅkā tvayā saha sarākṣasā', null, 3035006),
('ramayana-3-35-7', 7, 'Aranya Kanda, Sarga 35, Verse 7', 'त्वद्विधः कामवृत्तो हि दुःशीलः पापमन्त्रितः।
आत्मानं स्वजनं राष्ट्रं स राजा हन्ति दुर्मतिः॥', 'tvadvidhaḥ kāmavṛtto hi duḥśīlaḥ pāpamantritaḥ
ātmānaṃ svajanaṃ rāṣṭraṃ sa rājā hanti durmatiḥ', null, 3035007),
('ramayana-3-35-8', 8, 'Aranya Kanda, Sarga 35, Verse 8', 'न च पित्रा परित्यक्तो नामर्यादः कथं चन।
न लुब्धो न च दुःशीलो न च क्षत्रियपांसनः॥', 'na ca pitrā parityakto nāmaryādaḥ kathaṃ cana
na lubdho na ca duḥśīlo na ca kṣatriyapāṃsanaḥ', null, 3035008),
('ramayana-3-35-9', 9, 'Aranya Kanda, Sarga 35, Verse 9', 'न च धर्मगुणैर्हीनैः कौसल्यानन्दवर्धनः।
न च तीक्ष्णो हि भूतानां सर्वेषां च हिते रतः॥', 'na ca dharmaguṇair hīnaiḥ kausalyānandavardhanaḥ
na ca tīkṣṇo hi bhūtānāṃ sarveṣāṃ ca hite rataḥ', null, 3035009),
('ramayana-3-35-10', 10, 'Aranya Kanda, Sarga 35, Verse 10', 'वञ्चितं पितरं दृष्ट्वा कैकेय्या सत्यवादिनम्।
करिष्यामीति धर्मात्मा ततः प्रव्रजितो वनम्॥', 'vañcitaṃ pitaraṃ dṛṣṭvā kaikeyyā satyavādinam
kariṣyāmīti dharmātmā tataḥ pravrajito vanam', null, 3035010),
('ramayana-3-35-11', 11, 'Aranya Kanda, Sarga 35, Verse 11', 'कैकेय्याः प्रियकामार्थं पितुर्दशरथस्य च।
हित्वा राज्यं च भोगांश्च प्रविष्टो दण्डकावनम्॥', 'kaikeyyāḥ priyakāmārthaṃ pitur daśarathasya ca
hitvā rājyaṃ ca bhogāṃś ca praviṣṭo daṇḍakāvanam', null, 3035011),
('ramayana-3-35-12', 12, 'Aranya Kanda, Sarga 35, Verse 12', 'न रामः कर्कशस्तात नाविद्वान्नाजितेन्द्रियः।
अनृतं न श्रुतं चैव नैव त्वं वक्तुमर्हसि॥', 'na rāmaḥ karkaśas tāta nāvidvān nājitendriyaḥ
anṛtaṃ na śrutaṃ caiva naiva tvaṃ vaktum arhasi', null, 3035012),
('ramayana-3-35-13', 13, 'Aranya Kanda, Sarga 35, Verse 13', 'रामो विग्रहवान्धर्मः साधुः सत्यपराक्रमः।
राजा सर्वस्य लोकस्य देवानामिव वासवः॥', 'rāmo vigrahavān dharmaḥ sādhuḥ satyaparākramaḥ
rājā sarvasya lokasya devānām iva vāsavaḥ', null, 3035013),
('ramayana-3-35-14', 14, 'Aranya Kanda, Sarga 35, Verse 14', 'कथं त्वं तस्य वैदेहीं रक्षितां स्वेन तेजसा।
इच्छसि प्रसभं हर्तुं प्रभामिव विवस्वतः॥', 'kathaṃ tvaṃ tasya vaidehīṃ rakṣitāṃ svena tejasā
icchasi prasabhaṃ hartuṃ prabhām iva vivasvataḥ', null, 3035014),
('ramayana-3-35-15', 15, 'Aranya Kanda, Sarga 35, Verse 15', 'शरार्चिषमनाधृष्यं चापखड्गेन्धनं रणे।
रामाग्निं सहसा दीप्तं न प्रवेष्टुं त्वमर्हसि॥', 'śarārciṣam anādhṛṣyaṃ cāpakhaḍgendhanaṃ raṇe
rāmāgniṃ sahasā dīptaṃ na praveṣṭuṃ tvam arhasi', null, 3035015),
('ramayana-3-35-16', 16, 'Aranya Kanda, Sarga 35, Verse 16', 'धनुर्व्यादितदीप्तास्यं शरार्चिषममर्षणम्।
चापबाणधरं वीरं शत्रुसेनापहारिणम्॥', 'dhanurvyāditadīptāsyaṃ śarārciṣam amarṣaṇam
cāpabāṇadharaṃ vīraṃ śatrusenāpahāriṇam', null, 3035016),
('ramayana-3-35-17', 17, 'Aranya Kanda, Sarga 35, Verse 17', 'राज्यं सुखं च संत्यज्य जीवितं चेष्टमात्मनः।
नात्यासादयितुं तात रामान्तकमिहार्हसि॥', 'rājyaṃ sukhaṃ ca saṃtyajya jīvitaṃ ceṣṭam ātmanaḥ
nātyāsādayituṃ tāta rāmāntakam ihārhasi', null, 3035017),
('ramayana-3-35-18', 18, 'Aranya Kanda, Sarga 35, Verse 18', 'अप्रमेयं हि तत्तेजो यस्य सा जनकात्मजा।
न त्वं समर्थस्तां हर्तुं रामचापाश्रयां वने॥', 'aprameyaṃ hi tat tejo yasya sā janakātmajā
na tvaṃ samarthas tāṃ hartuṃ rāmacāpāśrayāṃ vane', null, 3035018),
('ramayana-3-35-19', 19, 'Aranya Kanda, Sarga 35, Verse 19', 'प्राणेभ्योऽपि प्रियतरा भार्या नित्यमनुव्रता।
दीप्तस्येव हुताशस्य शिखा सीता सुमध्यमा॥', 'prāṇebhyo ''pi priyatarā bhāryā nityam anuvratā
dīptasyeva hutāśasya śikhā sītā sumadhyamā', null, 3035019),
('ramayana-3-35-20', 20, 'Aranya Kanda, Sarga 35, Verse 20', 'किमुद्यमं व्यर्थमिमं कृत्वा ते राक्षसाधिप।
दृष्टश्चेत्त्वं रणे तेन तदन्तं तव जीवितम्।
जीवितं च सुखं चैव राज्यं चैव सुदुर्लभम्॥', 'kim udyamaṃ vyartham imaṃ kṛtvā te rākṣasādhipa
dṛṣṭaś cet tvaṃ raṇe tena tad antaṃ tava jīvitam
jīvitaṃ ca sukhaṃ caiva rājyaṃ caiva sudurlabham', null, 3035020),
('ramayana-3-35-21', 21, 'Aranya Kanda, Sarga 35, Verse 21', 'स सर्वैः सचिवैः सार्धं विभीषणपुरस्कृतैः।
मन्त्रयित्वा तु धर्मिष्ठैः कृत्वा निश्चयमात्मनः॥', 'sa sarvaiḥ sacivaiḥ sārdhaṃ vibhīṣaṇapuraskṛtaiḥ
mantrayitvā tu dharmiṣṭhaiḥ kṛtvā niścayam ātmanaḥ', null, 3035021),
('ramayana-3-35-22', 22, 'Aranya Kanda, Sarga 35, Verse 22', 'दोषाणां च गुणानां च संप्रधार्य बलाबलम्।
आत्मनश्च बलं ज्ञात्वा राघवस्य च तत्त्वतः।
हितं हि तव निश्चित्य क्षमं त्वं कर्तुमर्हसि॥', 'doṣāṇāṃ ca guṇānāṃ ca saṃpradhārya balābalam
ātmanaś ca balaṃ jñātvā rāghavasya ca tattvataḥ
hitaṃ hi tava niścitya kṣamaṃ tvaṃ kartum arhasi', null, 3035022),
('ramayana-3-35-23', 23, 'Aranya Kanda, Sarga 35, Verse 23', 'अहं तु मन्ये तव न क्षमं रणे समागमं कोसलराजसूनुना।
इदं हि भूयः शृणु वाक्यमुत्तमं क्षमं च युक्तं च निशाचराधिप॥', 'ahaṃ tu manye tava na kṣamaṃ raṇe samāgamaṃ kosalarājasūnunā
idaṃ hi bhūyaḥ śṛṇu vākyam uttamaṃ kṣamaṃ ca yuktaṃ ca niśācarādhipa', null, 3035023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 36 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-36-1', 1, 'Aranya Kanda, Sarga 36, Verse 1', 'कदा चिदप्यहं वीर्यात्पर्यटन्पृथिवीमिमाम्।
बलं नागसहस्रस्य धारयन्पर्वतोपमः॥', 'kadā cid apy ahaṃ vīryāt paryaṭan pṛthivīm imām
balaṃ nāgasahasrasya dhārayan parvatopamaḥ', null, 3036001),
('ramayana-3-36-2', 2, 'Aranya Kanda, Sarga 36, Verse 2', 'नीलजीमूतसंकाशस्तप्तकाञ्चनकुण्डलः।
भयं लोकस्य जनयन्किरीटी परिघायुधः।
व्यचरं दण्डकारण्यमृषिमांसानि भक्षयन्॥', 'nīlajīmūtasaṃkāśas taptakāñcanakuṇḍalaḥ
bhayaṃ lokasya janayan kirīṭī parighāyudhaḥ
vyacaraṃ daṇḍakāraṇyam ṛṣimāṃsāni bhakṣayan', null, 3036002),
('ramayana-3-36-3', 3, 'Aranya Kanda, Sarga 36, Verse 3', 'विश्वामित्रोऽथ धर्मात्मा मद्वित्रस्तो महामुनिः।
स्वयं गत्वा दशरथं नरेन्द्रमिदमब्रवीत्॥', 'viśvāmitro ''tha dharmātmā madvitrasto mahāmuniḥ
svayaṃ gatvā daśarathaṃ narendram idam abravīt', null, 3036003),
('ramayana-3-36-4', 4, 'Aranya Kanda, Sarga 36, Verse 4', 'अयं रक्षतु मां रामः पर्वकाले समाहितः।
मारीचान्मे भयं घोरं समुत्पन्नं नरेश्वर॥', 'ayaṃ rakṣatu māṃ rāmaḥ parvakāle samāhitaḥ
mārīcān me bhayaṃ ghoraṃ samutpannaṃ nareśvara', null, 3036004),
('ramayana-3-36-5', 5, 'Aranya Kanda, Sarga 36, Verse 5', 'इत्येवमुक्तो धर्मात्मा राजा दशरथस्तदा।
प्रत्युवाच महाभागं विश्वामित्रं महामुनिम्॥', 'ity evam ukto dharmātmā rājā daśarathas tadā
pratyuvāca mahābhāgaṃ viśvāmitraṃ mahāmunim', null, 3036005),
('ramayana-3-36-6', 6, 'Aranya Kanda, Sarga 36, Verse 6', 'ऊन षोडश वर्षोऽयमकृतास्त्रश्च राघवः।
कामं तु मम यत्सैन्यं मया सह गमिष्यति।
बधिष्यामि मुनिश्रेष्ठ शत्रुं तव यथेप्सितम्॥', 'ūna ṣoḍaśa varṣo ''yam akṛtāstraś ca rāghavaḥ
kāmaṃ tu mama yat sainyaṃ mayā saha gamiṣyati
badhiṣyāmi muniśreṣṭha śatruṃ tava yathepsitam', null, 3036006),
('ramayana-3-36-7', 7, 'Aranya Kanda, Sarga 36, Verse 7', 'इत्येवमुक्तः स मुनी राजानं पुनरब्रवीत्।
रामान्नान्यद्बलं लोके पर्याप्तं तस्य रक्षसः॥', 'ity evam uktaḥ sa munī rājānaṃ punar abravīt
rāmān nānyad balaṃ loke paryāptaṃ tasya rakṣasaḥ', null, 3036007),
('ramayana-3-36-8', 8, 'Aranya Kanda, Sarga 36, Verse 8', 'बालोऽप्येष महातेजाः समर्थस्तस्य निग्रहे।
गमिष्ये राममादाय स्वस्ति तेऽस्तु परंतपः॥', 'bālo ''py eṣa mahātejāḥ samarthas tasya nigrahe
gamiṣye rāmam ādāya svasti te ''stu paraṃtapaḥ', null, 3036008),
('ramayana-3-36-9', 9, 'Aranya Kanda, Sarga 36, Verse 9', 'इत्येवमुक्त्वा स मुनिस्तमादाय नृपात्मजम्।
जगाम परमप्रीतो विश्वामित्रः स्वमाश्रमम्॥', 'ity evam uktvā sa munis tam ādāya nṛpātmajam
jagāma paramaprīto viśvāmitraḥ svam āśramam', null, 3036009),
('ramayana-3-36-10', 10, 'Aranya Kanda, Sarga 36, Verse 10', 'तं तदा दण्डकारण्ये यज्ञमुद्दिश्य दीक्षितम्।
बभूवावस्थितो रामश्चित्रं विस्फारयन्धनुः॥', 'taṃ tadā daṇḍakāraṇye yajñam uddiśya dīkṣitam
babhūvāvasthito rāmaś citraṃ visphārayan dhanuḥ', null, 3036010),
('ramayana-3-36-11', 11, 'Aranya Kanda, Sarga 36, Verse 11', 'अजातव्यञ्जनः श्रीमान्बालः श्यामः शुभेक्षणः।
एकवस्त्रधरो धन्वी शिखी कनकमालया॥', 'ajātavyañjanaḥ śrīmān bālaḥ śyāmaḥ śubhekṣaṇaḥ
ekavastradharo dhanvī śikhī kanakamālayā', null, 3036011),
('ramayana-3-36-12', 12, 'Aranya Kanda, Sarga 36, Verse 12', 'शोभयन्दण्डकारण्यं दीप्तेन स्वेन तेजसा।
अदृश्यत तदा रामो बालचन्द्र इवोदितः॥', 'śobhayan daṇḍakāraṇyaṃ dīptena svena tejasā
adṛśyata tadā rāmo bālacandra ivoditaḥ', null, 3036012),
('ramayana-3-36-13', 13, 'Aranya Kanda, Sarga 36, Verse 13', 'ततोऽहं मेघसंकाशस्तप्तकाञ्चनकुण्डलः।
बली दत्तवरो दर्पादाजगाम तदाश्रमम्॥', 'tato ''haṃ meghasaṃkāśas taptakāñcanakuṇḍalaḥ
balī dattavaro darpād ājagāma tadāśramam', null, 3036013),
('ramayana-3-36-14', 14, 'Aranya Kanda, Sarga 36, Verse 14', 'तेन दृष्टः प्रविष्टोऽहं सहसैवोद्यतायुधः।
मां तु दृष्ट्वा धनुः सज्यमसंभ्रान्तश्चकार ह॥', 'tena dṛṣṭaḥ praviṣṭo ''haṃ sahasaivodyatāyudhaḥ
māṃ tu dṛṣṭvā dhanuḥ sajyam asaṃbhrāntaś cakāra ha', null, 3036014),
('ramayana-3-36-15', 15, 'Aranya Kanda, Sarga 36, Verse 15', 'अवजानन्नहं मोहाद्बालोऽयमिति राघवम्।
विश्वामित्रस्य तां वेदिमध्यधावं कृतत्वरः॥', 'avajānann ahaṃ mohād bālo ''yam iti rāghavam
viśvāmitrasya tāṃ vedim adhyadhāvaṃ kṛtatvaraḥ', null, 3036015),
('ramayana-3-36-16', 16, 'Aranya Kanda, Sarga 36, Verse 16', 'तेन मुक्तस्ततो बाणः शितः शत्रुनिबर्हणः।
तेनाहं ताडितः क्षिप्तः समुद्रे शतयोजने॥', 'tena muktas tato bāṇaḥ śitaḥ śatrunibarhaṇaḥ
tenāhaṃ tāḍitaḥ kṣiptaḥ samudre śatayojane', null, 3036016),
('ramayana-3-36-17', 17, 'Aranya Kanda, Sarga 36, Verse 17', 'रामस्य शरवेगेन निरस्तो भ्रान्तचेतनः।
पातितोऽहं तदा तेन गम्भीरे सागराम्भसि।
प्राप्य संज्ञां चिरात्तात लङ्कां प्रति गतः पुरीम्॥', 'rāmasya śaravegena nirasto bhrāntacetanaḥ
pātito ''haṃ tadā tena gambhīre sāgarāmbhasi
prāpya saṃjñāṃ cirāt tāta laṅkāṃ prati gataḥ purīm', null, 3036017),
('ramayana-3-36-18', 18, 'Aranya Kanda, Sarga 36, Verse 18', 'एवमस्मि तदा मुक्तः सहायास्ते निपातिताः।
अकृतास्त्रेण रामेण बालेनाक्लिष्टकर्मणा॥', 'evam asmi tadā muktaḥ sahāyās te nipātitāḥ
akṛtāstreṇa rāmeṇa bālenākliṣṭakarmaṇā', null, 3036018),
('ramayana-3-36-19', 19, 'Aranya Kanda, Sarga 36, Verse 19', 'तन्मया वार्यमाणस्त्वं यदि रामेण विग्रहम्।
करिष्यस्यापदं घोरां क्षिप्रं प्राप्य नशिष्यसि॥', 'tan mayā vāryamāṇas tvaṃ yadi rāmeṇa vigraham
kariṣyasy āpadaṃ ghorāṃ kṣipraṃ prāpya naśiṣyasi', null, 3036019),
('ramayana-3-36-20', 20, 'Aranya Kanda, Sarga 36, Verse 20', 'क्रीडा रतिविधिज्ञानां समाजोत्सवशालिनाम्।
रक्षसां चैव संतापमनर्थं चाहरिष्यसि॥', 'krīḍā ratividhijñānāṃ samājotsavaśālinām
rakṣasāṃ caiva saṃtāpam anarthaṃ cāhariṣyasi', null, 3036020),
('ramayana-3-36-21', 21, 'Aranya Kanda, Sarga 36, Verse 21', 'हर्म्यप्रासादसंबाधां नानारत्नविभूषिताम्।
द्रक्ष्यसि त्वं पुरीं लङ्कां विनष्टां मैथिलीकृते॥', 'harmyaprāsādasaṃbādhāṃ nānāratnavibhūṣitām
drakṣyasi tvaṃ purīṃ laṅkāṃ vinaṣṭāṃ maithilīkṛte', null, 3036021),
('ramayana-3-36-22', 22, 'Aranya Kanda, Sarga 36, Verse 22', 'अकुर्वन्तोऽपि पापानि शुचयः पापसंश्रयात्।
परपापैर्विनश्यन्ति मत्स्या नागह्रदे यथा॥', 'akurvanto ''pi pāpāni śucayaḥ pāpasaṃśrayāt
parapāpair vinaśyanti matsyā nāgahrade yathā', null, 3036022),
('ramayana-3-36-23', 23, 'Aranya Kanda, Sarga 36, Verse 23', 'दिव्यचन्दनदिग्धाङ्गान्दिव्याभरणभूषितान्।
द्रक्ष्यस्यभिहतान्भूमौ तव दोषात्तु राक्षसान्॥', 'divyacandanadigdhāṅgān divyābharaṇabhūṣitān
drakṣyasy abhihatān bhūmau tava doṣāt tu rākṣasān', null, 3036023),
('ramayana-3-36-24', 24, 'Aranya Kanda, Sarga 36, Verse 24', 'हृतदारान्सदारांश्च दशविद्रवतो दिशः।
हतशेषानशरणान्द्रक्ष्यसि त्वं निशाचरान्॥', 'hṛtadārān sadārāṃś ca daśavidravato diśaḥ
hataśeṣān aśaraṇān drakṣyasi tvaṃ niśācarān', null, 3036024),
('ramayana-3-36-25', 25, 'Aranya Kanda, Sarga 36, Verse 25', 'शरजालपरिक्षिप्तामग्निज्वालासमावृताम्।
प्रदग्धभवनां लङ्कां द्रक्ष्यसि त्वमसंशयम्॥', 'śarajālaparikṣiptām agnijvālāsamāvṛtām
pradagdhabhavanāṃ laṅkāṃ drakṣyasi tvam asaṃśayam', null, 3036025),
('ramayana-3-36-26', 26, 'Aranya Kanda, Sarga 36, Verse 26', 'प्रमदानां सहस्राणि तव राजन्परिग्रहः।
भव स्वदारनिरतः स्वकुलं रक्षराक्षस॥', 'pramadānāṃ sahasrāṇi tava rājan parigrahaḥ
bhava svadāranirataḥ svakulaṃ rakṣarākṣasa', null, 3036026),
('ramayana-3-36-27', 27, 'Aranya Kanda, Sarga 36, Verse 27', 'मानं वृद्धिं च राज्यं च जीवितं चेष्टमात्मनः।
यदीच्छसि चिरं भोक्तुं मा कृथा राम विप्रियम्॥', 'mānaṃ vṛddhiṃ ca rājyaṃ ca jīvitaṃ ceṣṭam ātmanaḥ
yadīcchasi ciraṃ bhoktuṃ mā kṛthā rāma vipriyam', null, 3036027),
('ramayana-3-36-28', 28, 'Aranya Kanda, Sarga 36, Verse 28', 'निवार्यमाणः सुहृदा मया भृशं प्रसह्य सीतां यदि धर्षयिष्यसि।
गमिष्यसि क्षीणबलः सबान्धवो यमक्षयं रामशरात्तजीवितः॥', 'nivāryamāṇaḥ suhṛdā mayā bhṛśaṃ prasahya sītāṃ yadi dharṣayiṣyasi
gamiṣyasi kṣīṇabalaḥ sabāndhavo yamakṣayaṃ rāmaśarāttajīvitaḥ', null, 3036028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 37 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-37-1', 1, 'Aranya Kanda, Sarga 37, Verse 1', 'एवमस्मि तदा मुक्तः कथं चित्तेन संयुगे।
इदानीमपि यद्वृत्तं तच्छृणुष्व यदुत्तरम्॥', 'evam asmi tadā muktaḥ kathaṃ cit tena saṃyuge
idānīm api yad vṛttaṃ tac chṛṇuṣva yad uttaram', null, 3037001),
('ramayana-3-37-2', 2, 'Aranya Kanda, Sarga 37, Verse 2', 'राक्षसाभ्यामहं द्वाभ्यामनिर्विण्णस्तथा कृतः।
सहितो मृगरूपाभ्यां प्रविष्टो दण्डकावनम्॥', 'rākṣasābhyām ahaṃ dvābhyām anirviṇṇas tathā kṛtaḥ
sahito mṛgarūpābhyāṃ praviṣṭo daṇḍakāvanam', null, 3037002),
('ramayana-3-37-3', 3, 'Aranya Kanda, Sarga 37, Verse 3', 'दीप्तजिह्वो महाकायस्तीक्ष्णशृण्गो महाबलः।
व्यचरन्दण्डकारण्यं मांसभक्षो महामृगः॥', 'dīptajihvo mahākāyas tīkṣṇaśṛṇgo mahābalaḥ
vyacaran daṇḍakāraṇyaṃ māṃsabhakṣo mahāmṛgaḥ', null, 3037003),
('ramayana-3-37-4', 4, 'Aranya Kanda, Sarga 37, Verse 4', 'अग्निहोत्रेषु तीर्थेषु चैत्यवृक्षेषु रावण।
अत्यन्तघोरो व्यचरंस्तापसांस्तान्प्रधर्षयन्॥', 'agnihotreṣu tīrtheṣu caityavṛkṣeṣu rāvaṇa
atyantaghoro vyacaraṃs tāpasāṃs tān pradharṣayan', null, 3037004),
('ramayana-3-37-5', 5, 'Aranya Kanda, Sarga 37, Verse 5', 'निहत्य दण्डकारण्ये तापसान्धर्मचारिणः।
रुधिराणि पिबंस्तेषां तथा मांसानि भक्षयन्॥', 'nihatya daṇḍakāraṇye tāpasān dharmacāriṇaḥ
rudhirāṇi pibaṃs teṣāṃ tathā māṃsāni bhakṣayan', null, 3037005),
('ramayana-3-37-6', 6, 'Aranya Kanda, Sarga 37, Verse 6', 'ऋषिमांसाशनः क्रूरस्त्रासयन्वनगोचरान्।
तदा रुधिरमत्तोऽहं व्यचरं दण्डकावनम्॥', 'ṛṣimāṃsāśanaḥ krūras trāsayan vanagocarān
tadā rudhiramatto ''haṃ vyacaraṃ daṇḍakāvanam', null, 3037006),
('ramayana-3-37-7', 7, 'Aranya Kanda, Sarga 37, Verse 7', 'तदाहं दण्डकारण्ये विचरन्धर्मदूषकः।
आसादयं तदा रामं तापसं धर्ममाश्रितम्॥', 'tadāhaṃ daṇḍakāraṇye vicaran dharmadūṣakaḥ
āsādayaṃ tadā rāmaṃ tāpasaṃ dharmam āśritam', null, 3037007),
('ramayana-3-37-8', 8, 'Aranya Kanda, Sarga 37, Verse 8', 'वैदेहीं च महाभागां लक्ष्मणं च महारथम्।
तापसं नियताहारं सर्वभूतहिते रतम्॥', 'vaidehīṃ ca mahābhāgāṃ lakṣmaṇaṃ ca mahāratham
tāpasaṃ niyatāhāraṃ sarvabhūtahite ratam', null, 3037008),
('ramayana-3-37-9', 9, 'Aranya Kanda, Sarga 37, Verse 9', 'सोऽहं वनगतं रामं परिभूय महाबलम्।
तापसोऽयमिति ज्ञात्वा पूर्ववैरमनुस्मरन्॥', 'so ''haṃ vanagataṃ rāmaṃ paribhūya mahābalam
tāpaso ''yam iti jñātvā pūrvavairam anusmaran', null, 3037009),
('ramayana-3-37-10', 10, 'Aranya Kanda, Sarga 37, Verse 10', 'अभ्यधावं सुसंक्रुद्धस्तीक्ष्णशृङ्गो मृगाकृतिः।
जिघांसुरकृतप्रज्ञस्तं प्रहारमनुस्मरन्॥', 'abhyadhāvaṃ susaṃkruddhas tīkṣṇaśṛṅgo mṛgākṛtiḥ
jighāṃsur akṛtaprajñas taṃ prahāram anusmaran', null, 3037010),
('ramayana-3-37-11', 11, 'Aranya Kanda, Sarga 37, Verse 11', 'तेन मुक्तास्त्रयो बाणाः शिताः शत्रुनिबर्हणाः।
विकृष्य बलवच्चापं सुपर्णानिलतुल्यगाः॥', 'tena muktās trayo bāṇāḥ śitāḥ śatrunibarhaṇāḥ
vikṛṣya balavac cāpaṃ suparṇānilatulyagāḥ', null, 3037011),
('ramayana-3-37-12', 12, 'Aranya Kanda, Sarga 37, Verse 12', 'ते बाणा वज्रसंकाशाः सुघोरा रक्तभोजनाः।
आजग्मुः सहिताः सर्वे त्रयः संनतपर्वणः॥', 'te bāṇā vajrasaṃkāśāḥ sughorā raktabhojanāḥ
ājagmuḥ sahitāḥ sarve trayaḥ saṃnataparvaṇaḥ', null, 3037012),
('ramayana-3-37-13', 13, 'Aranya Kanda, Sarga 37, Verse 13', 'पराक्रमज्ञो रामस्य शठो दृष्टभयः पुरा।
समुत्क्रान्तस्ततो मुक्तस्तावुभौ राक्षसौ हतौ॥', 'parākramajño rāmasya śaṭho dṛṣṭabhayaḥ purā
samutkrāntas tato muktas tāv ubhau rākṣasau hatau', null, 3037013),
('ramayana-3-37-14', 14, 'Aranya Kanda, Sarga 37, Verse 14', 'शरेण मुक्तो रामस्य कथं चित्प्राप्य जीवितम्।
इह प्रव्राजितो युक्तस्तापसोऽहं समाहितः॥', 'śareṇa mukto rāmasya kathaṃ cit prāpya jīvitam
iha pravrājito yuktas tāpaso ''haṃ samāhitaḥ', null, 3037014),
('ramayana-3-37-15', 15, 'Aranya Kanda, Sarga 37, Verse 15', 'वृक्षे वृक्षे हि पश्यामि चीरकृष्णाजिनाम्बरम्।
गृहीतधनुषं रामं पाशहस्तमिवान्तकम्॥', 'vṛkṣe vṛkṣe hi paśyāmi cīrakṛṣṇājināmbaram
gṛhītadhanuṣaṃ rāmaṃ pāśahastam ivāntakam', null, 3037015),
('ramayana-3-37-16', 16, 'Aranya Kanda, Sarga 37, Verse 16', 'अपि रामसहस्राणि भीतः पश्यामि रावण।
रामभूतमिदं सर्वमरण्यं प्रतिभाति मे॥', 'api rāmasahasrāṇi bhītaḥ paśyāmi rāvaṇa
rāmabhūtam idaṃ sarvam araṇyaṃ pratibhāti me', null, 3037016),
('ramayana-3-37-17', 17, 'Aranya Kanda, Sarga 37, Verse 17', 'राममेव हि पश्यामि रहिते राक्षसेश्वर।
दृष्ट्वा स्वप्नगतं राममुद्भ्रमामि विचेतनः॥', 'rāmam eva hi paśyāmi rahite rākṣaseśvara
dṛṣṭvā svapnagataṃ rāmam udbhramāmi vicetanaḥ', null, 3037017),
('ramayana-3-37-18', 18, 'Aranya Kanda, Sarga 37, Verse 18', 'रकारादीनि नामानि रामत्रस्तस्य रावण।
रत्नानि च रथाश्चैव त्रासं संजनयन्ति मे॥', 'rakārādīni nāmāni rāmatrastasya rāvaṇa
ratnāni ca rathāś caiva trāsaṃ saṃjanayanti me', null, 3037018),
('ramayana-3-37-19', 19, 'Aranya Kanda, Sarga 37, Verse 19', 'अहं तस्य प्रभावज्ञो न युद्धं तेन ते क्षमम्।
रणे रामेण युध्यस्व क्षमां वा कुरु राक्षस।
न ते रामकथा कार्या यदि मां द्रष्टुमिच्छसि॥', 'ahaṃ tasya prabhāvajño na yuddhaṃ tena te kṣamam
raṇe rāmeṇa yudhyasva kṣamāṃ vā kuru rākṣasa
na te rāmakathā kāryā yadi māṃ draṣṭum icchasi', null, 3037019),
('ramayana-3-37-20', 20, 'Aranya Kanda, Sarga 37, Verse 20', 'इदं वचो बन्धुहितार्थिना मया यथोच्यमानं यदि नाभिपत्स्यसे।
सबान्धवस्त्यक्ष्यसि जीवितं रणे हतोऽद्य रामेण शरैरजिह्मगैः॥', 'idaṃ vaco bandhuhitārthinā mayā yathocyamānaṃ yadi nābhipatsyase
sabāndhavas tyakṣyasi jīvitaṃ raṇe hato ''dya rāmeṇa śarair ajihmagaiḥ', null, 3037020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 38 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-38-1', 1, 'Aranya Kanda, Sarga 38, Verse 1', 'मारीचेन तु तद्वाक्यं क्षमं युक्तं च रावणः।
उक्तो न प्रतिजग्राह मर्तुकाम इवौषधम्॥', 'mārīcena tu tad vākyaṃ kṣamaṃ yuktaṃ ca rāvaṇaḥ
ukto na pratijagrāha martukāma ivauṣadham', null, 3038001),
('ramayana-3-38-2', 2, 'Aranya Kanda, Sarga 38, Verse 2', 'तं पथ्यहितवक्तारं मारीचं राक्षसाधिपः।
अब्रवीत्परुषं वाक्यमयुक्तं कालचोदितः॥', 'taṃ pathyahitavaktāraṃ mārīcaṃ rākṣasādhipaḥ
abravīt paruṣaṃ vākyam ayuktaṃ kālacoditaḥ', null, 3038002),
('ramayana-3-38-3', 3, 'Aranya Kanda, Sarga 38, Verse 3', 'यत्किलैतदयुक्तार्थं मारीच मयि कथ्यते।
वाक्यं निष्फलमत्यर्थं बीजमुप्तमिवोषरे॥', 'yat kilaitad ayuktārthaṃ mārīca mayi kathyate
vākyaṃ niṣphalam atyarthaṃ bījam uptam ivoṣare', null, 3038003),
('ramayana-3-38-4', 4, 'Aranya Kanda, Sarga 38, Verse 4', 'त्वद्वाक्यैर्न तु मां शक्यं भेत्तुं रामस्य संयुगे।
पापशीलस्य मूर्खस्य मानुषस्य विशेषतः॥', 'tvadvākyair na tu māṃ śakyaṃ bhettuṃ rāmasya saṃyuge
pāpaśīlasya mūrkhasya mānuṣasya viśeṣataḥ', null, 3038004),
('ramayana-3-38-5', 5, 'Aranya Kanda, Sarga 38, Verse 5', 'यस्त्यक्त्वा सुहृदो राज्यं मातरं पितरं तथा।
स्त्रीवाक्यं प्राकृतं श्रुत्वा वनमेकपदे गतः॥', 'yas tyaktvā suhṛdo rājyaṃ mātaraṃ pitaraṃ tathā
strīvākyaṃ prākṛtaṃ śrutvā vanam ekapade gataḥ', null, 3038005),
('ramayana-3-38-6', 6, 'Aranya Kanda, Sarga 38, Verse 6', 'अवश्यं तु मया तस्य संयुगे खरघातिनः।
प्राणैः प्रियतरा सीता हर्तव्या तव संनिधौ॥', 'avaśyaṃ tu mayā tasya saṃyuge kharaghātinaḥ
prāṇaiḥ priyatarā sītā hartavyā tava saṃnidhau', null, 3038006),
('ramayana-3-38-7', 7, 'Aranya Kanda, Sarga 38, Verse 7', 'एवं मे निश्चिता बुद्धिर्हृदि मारीच वर्तते।
न व्यावर्तयितुं शक्या सेन्द्रैरपि सुरासुरैः॥', 'evaṃ me niścitā buddhir hṛdi mārīca vartate
na vyāvartayituṃ śakyā sendrair api surāsuraiḥ', null, 3038007),
('ramayana-3-38-8', 8, 'Aranya Kanda, Sarga 38, Verse 8', 'दोषं गुणं वा संपृष्टस्त्वमेवं वक्तुमर्हसि।
अपायं वाप्युपायं वा कार्यस्यास्य विनिश्चये॥', 'doṣaṃ guṇaṃ vā saṃpṛṣṭas tvam evaṃ vaktum arhasi
apāyaṃ vāpy upāyaṃ vā kāryasyāsya viniścaye', null, 3038008),
('ramayana-3-38-9', 9, 'Aranya Kanda, Sarga 38, Verse 9', 'संपृष्टेन तु वक्तव्यं सचिवेन विपश्चिता।
उद्यताञ्जलिना राज्ञो य इच्छेद्भूतिमात्मनः॥', 'saṃpṛṣṭena tu vaktavyaṃ sacivena vipaścitā
udyatāñjalinā rājño ya icched bhūtim ātmanaḥ', null, 3038009),
('ramayana-3-38-10', 10, 'Aranya Kanda, Sarga 38, Verse 10', 'वाक्यमप्रतिकूलं तु मृदुपूर्वं शुभं हितम्।
उपचारेण युक्तं च वक्तव्यो वसुधाधिपः॥', 'vākyam apratikūlaṃ tu mṛdupūrvaṃ śubhaṃ hitam
upacāreṇa yuktaṃ ca vaktavyo vasudhādhipaḥ', null, 3038010),
('ramayana-3-38-11', 11, 'Aranya Kanda, Sarga 38, Verse 11', 'सावमर्दं तु यद्वाक्यं मारीच हितमुच्यते।
नाभिनन्दति तद्राजा मानार्हो मानवर्जितम्॥', 'sāvamardaṃ tu yad vākyaṃ mārīca hitam ucyate
nābhinandati tad rājā mānārho mānavarjitam', null, 3038011),
('ramayana-3-38-12', 12, 'Aranya Kanda, Sarga 38, Verse 12', 'पञ्चरूपाणि राजानो धारयन्त्यमितौजसः।
अग्नेरिन्द्रस्य सोमस्य यमस्य वरुणस्य च।
औष्ण्यं तथा विक्रमं च सौम्यं दण्डं प्रसन्नताम्॥', 'pañcarūpāṇi rājāno dhārayanty amitaujasaḥ
agner indrasya somasya yamasya varuṇasya ca
auṣṇyaṃ tathā vikramaṃ ca saumyaṃ daṇḍaṃ prasannatām', null, 3038012),
('ramayana-3-38-13', 13, 'Aranya Kanda, Sarga 38, Verse 13', 'तस्मात्सर्वास्ववस्थासु मान्याः पूज्याश्च पार्थिवाः।
त्वं तु धर्ममविज्ञाय केवलं मोहमास्थितः॥', 'tasmāt sarvāsv avasthāsu mānyāḥ pūjyāś ca pārthivāḥ
tvaṃ tu dharmam avijñāya kevalaṃ moham āsthitaḥ', null, 3038013),
('ramayana-3-38-14', 14, 'Aranya Kanda, Sarga 38, Verse 14', 'अभ्यागतं मां दौरात्म्यात्परुषं वदसीदृशम्।
गुणदोषौ न पृच्छामि क्षमं चात्मनि राक्षस।
अस्मिंस्तु स भवान्कृत्ये साहाय्यं कर्तुमर्हति॥', 'abhyāgataṃ māṃ daurātmyāt paruṣaṃ vadasīdṛśam
guṇadoṣau na pṛcchāmi kṣamaṃ cātmani rākṣasa
asmiṃs tu sa bhavān kṛtye sāhāyyaṃ kartum arhati', null, 3038014),
('ramayana-3-38-15', 15, 'Aranya Kanda, Sarga 38, Verse 15', 'सौवर्णस्त्वं मृगो भूत्वा चित्रो रजतबिन्दुभिः।
प्रलोभयित्वा वैदेहीं यथेष्टं गन्तुमर्हसि॥', 'sauvarṇas tvaṃ mṛgo bhūtvā citro rajatabindubhiḥ
pralobhayitvā vaidehīṃ yatheṣṭaṃ gantum arhasi', null, 3038015),
('ramayana-3-38-16', 16, 'Aranya Kanda, Sarga 38, Verse 16', 'त्वां तु मायामृगं दृष्ट्वा काञ्चनं जातविस्मया।
आनयैनमिति क्षिप्रं रामं वक्ष्यति मैथिली॥', 'tvāṃ tu māyāmṛgaṃ dṛṣṭvā kāñcanaṃ jātavismayā
ānayainam iti kṣipraṃ rāmaṃ vakṣyati maithilī', null, 3038016),
('ramayana-3-38-17', 17, 'Aranya Kanda, Sarga 38, Verse 17', 'अपक्रान्ते च काकुत्स्थे लक्ष्मणे च यथासुखम्।
आनयिष्यामि वैदेहीं सहस्राक्षः शचीमिव॥', 'apakrānte ca kākutsthe lakṣmaṇe ca yathāsukham
ānayiṣyāmi vaidehīṃ sahasrākṣaḥ śacīm iva', null, 3038017),
('ramayana-3-38-18', 18, 'Aranya Kanda, Sarga 38, Verse 18', 'एवं कृत्वा त्विदं कार्यं यथेष्टं गच्छ राक्षस।
राज्यस्यार्धं प्रदास्यामि मारीच तव सुव्रत॥', 'evaṃ kṛtvā tv idaṃ kāryaṃ yatheṣṭaṃ gaccha rākṣasa
rājyasyārdhaṃ pradāsyāmi mārīca tava suvrata', null, 3038018),
('ramayana-3-38-19', 19, 'Aranya Kanda, Sarga 38, Verse 19', 'गच्छ सौम्य शिवं मार्गं कार्यस्यास्य विवृद्धये।
प्राप्य सीतामयुद्धेन वञ्चयित्वा तु राघवम्।
लङ्कां प्रति गमिष्यामि कृतकार्यः सह त्वया॥', 'gaccha saumya śivaṃ mārgaṃ kāryasyāsya vivṛddhaye
prāpya sītām ayuddhena vañcayitvā tu rāghavam
laṅkāṃ prati gamiṣyāmi kṛtakāryaḥ saha tvayā', null, 3038019),
('ramayana-3-38-20', 20, 'Aranya Kanda, Sarga 38, Verse 20', 'एतत्कार्यमवश्यं मे बलादपि करिष्यसि।
राज्ञो हि प्रतिकूलस्थो न जातु सुखमेधते॥', 'etat kāryam avaśyaṃ me balād api kariṣyasi
rājño hi pratikūlastho na jātu sukham edhate', null, 3038020),
('ramayana-3-38-21', 21, 'Aranya Kanda, Sarga 38, Verse 21', 'आसाद्य तं जीवितसंशयस्ते मृत्युर्ध्रुवो ह्यद्य मया विरुध्य।
एतद्यथावत्परिगृह्य बुद्ध्या यदत्र पथ्यं कुरु तत्तथा त्वम्॥', 'āsādya taṃ jīvitasaṃśayas te mṛtyur dhruvo hy adya mayā virudhya
etad yathāvat parigṛhya buddhyā yad atra pathyaṃ kuru tat tathā tvam', null, 3038021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 39 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-39-1', 1, 'Aranya Kanda, Sarga 39, Verse 1', 'आज्ञप्तो राजवद्वाक्यं प्रतिकूलं निशाचरः।
अब्रवीत्परुषं वाक्यं मारीचो राक्षसाधिपम्॥', 'ājñapto rājavad vākyaṃ pratikūlaṃ niśācaraḥ
abravīt paruṣaṃ vākyaṃ mārīco rākṣasādhipam', null, 3039001),
('ramayana-3-39-2', 2, 'Aranya Kanda, Sarga 39, Verse 2', 'केनायमुपदिष्टस्ते विनाशः पापकर्मणा।
सपुत्रस्य सराष्ट्रस्य सामात्यस्य निशाचर॥', 'kenāyam upadiṣṭas te vināśaḥ pāpakarmaṇā
saputrasya sarāṣṭrasya sāmātyasya niśācara', null, 3039002),
('ramayana-3-39-3', 3, 'Aranya Kanda, Sarga 39, Verse 3', 'कस्त्वया सुखिना राजन्नाभिनन्दति पापकृत्।
केनेदमुपदिष्टं ते मृत्युद्वारमुपायतः॥', 'kas tvayā sukhinā rājan nābhinandati pāpakṛt
kenedam upadiṣṭaṃ te mṛtyudvāram upāyataḥ', null, 3039003),
('ramayana-3-39-4', 4, 'Aranya Kanda, Sarga 39, Verse 4', 'शत्रवस्तव सुव्यक्तं हीनवीर्या निशाचर।
इच्छन्ति त्वां विनश्यन्तमुपरुद्धं बलीयसा॥', 'śatravas tava suvyaktaṃ hīnavīryā niśācara
icchanti tvāṃ vinaśyantam uparuddhaṃ balīyasā', null, 3039004),
('ramayana-3-39-5', 5, 'Aranya Kanda, Sarga 39, Verse 5', 'केनेदमुपदिष्टं ते क्षुद्रेणाहितवादिना।
यस्त्वामिच्छति नश्यन्तं स्वकृतेन निशाचर॥', 'kenedam upadiṣṭaṃ te kṣudreṇāhitavādinā
yas tvām icchati naśyantaṃ svakṛtena niśācara', null, 3039005),
('ramayana-3-39-6', 6, 'Aranya Kanda, Sarga 39, Verse 6', 'वध्याः खलु न हन्यन्ते सचिवास्तव रावण।
ये त्वामुत्पथमारूढं न निगृह्णन्ति सर्वशः॥', 'vadhyāḥ khalu na hanyante sacivās tava rāvaṇa
ye tvām utpatham ārūḍhaṃ na nigṛhṇanti sarvaśaḥ', null, 3039006),
('ramayana-3-39-7', 7, 'Aranya Kanda, Sarga 39, Verse 7', 'अमात्यैः कामवृत्तो हि राजा कापथमाश्रितः।
निग्राह्यः सर्वथा सद्भिर्न निग्राह्यो निगृह्यसे॥', 'amātyaiḥ kāmavṛtto hi rājā kāpatham āśritaḥ
nigrāhyaḥ sarvathā sadbhir na nigrāhyo nigṛhyase', null, 3039007),
('ramayana-3-39-8', 8, 'Aranya Kanda, Sarga 39, Verse 8', 'धर्ममर्थं च कामं च यशश्च जयतां वर।
स्वामिप्रसादात्सचिवाः प्राप्नुवन्ति निशाचर॥', 'dharmam arthaṃ ca kāmaṃ ca yaśaś ca jayatāṃ vara
svāmiprasādāt sacivāḥ prāpnuvanti niśācara', null, 3039008),
('ramayana-3-39-9', 9, 'Aranya Kanda, Sarga 39, Verse 9', 'विपर्यये तु तत्सर्वं व्यर्थं भवति रावण।
व्यसनं स्वामिवैगुण्यात्प्राप्नुवन्तीतरे जनाः॥', 'viparyaye tu tat sarvaṃ vyarthaṃ bhavati rāvaṇa
vyasanaṃ svāmivaiguṇyāt prāpnuvantītare janāḥ', null, 3039009),
('ramayana-3-39-10', 10, 'Aranya Kanda, Sarga 39, Verse 10', 'राजमूलो हि धर्मश्च जयश्च जयतां वर।
तस्मात्सर्वास्ववस्थासु रक्षितव्यो नराधिपः॥', 'rājamūlo hi dharmaś ca jayaś ca jayatāṃ vara
tasmāt sarvāsv avasthāsu rakṣitavyo narādhipaḥ', null, 3039010),
('ramayana-3-39-11', 11, 'Aranya Kanda, Sarga 39, Verse 11', 'राज्यं पालयितुं शक्यं न तीक्ष्णेन निशाचर।
न चापि प्रतिकूलेन नाविनीतेन राक्षस॥', 'rājyaṃ pālayituṃ śakyaṃ na tīkṣṇena niśācara
na cāpi pratikūlena nāvinītena rākṣasa', null, 3039011),
('ramayana-3-39-12', 12, 'Aranya Kanda, Sarga 39, Verse 12', 'ये तीक्ष्णमन्त्राः सचिवा भज्यन्ते सह तेन वै।
विषमेषु रथाः शीघ्रं मन्दसारथयो यथा॥', 'ye tīkṣṇamantrāḥ sacivā bhajyante saha tena vai
viṣameṣu rathāḥ śīghraṃ mandasārathayo yathā', null, 3039012),
('ramayana-3-39-13', 13, 'Aranya Kanda, Sarga 39, Verse 13', 'बहवः साधवो लोके युक्तधर्ममनुष्ठिताः।
परेषामपराधेन विनष्टाः सपरिच्छदाः॥', 'bahavaḥ sādhavo loke yuktadharmam anuṣṭhitāḥ
pareṣām aparādhena vinaṣṭāḥ saparicchadāḥ', null, 3039013),
('ramayana-3-39-14', 14, 'Aranya Kanda, Sarga 39, Verse 14', 'स्वामिना प्रतिकूलेन प्रजास्तीक्ष्णेन रावण।
रक्ष्यमाणा न वर्धन्ते मेषा गोमायुना यथा॥', 'svāminā pratikūlena prajās tīkṣṇena rāvaṇa
rakṣyamāṇā na vardhante meṣā gomāyunā yathā', null, 3039014),
('ramayana-3-39-15', 15, 'Aranya Kanda, Sarga 39, Verse 15', 'अवश्यं विनशिष्यन्ति सर्वे रावण राक्षसाः।
येषां त्वं कर्कशो राजा दुर्बुद्धिरजितेन्द्रियः॥', 'avaśyaṃ vinaśiṣyanti sarve rāvaṇa rākṣasāḥ
yeṣāṃ tvaṃ karkaśo rājā durbuddhir ajitendriyaḥ', null, 3039015),
('ramayana-3-39-16', 16, 'Aranya Kanda, Sarga 39, Verse 16', 'तदिदं काकतालीयं घोरमासादितं त्वया।
अत्र किं शोभनं यत्त्वं ससैन्यो विनशिष्यसि॥', 'tad idaṃ kākatālīyaṃ ghoram āsāditaṃ tvayā
atra kiṃ śobhanaṃ yat tvaṃ sasainyo vinaśiṣyasi', null, 3039016),
('ramayana-3-39-17', 17, 'Aranya Kanda, Sarga 39, Verse 17', 'मां निहत्य तु रामोऽसौ नचिरात्त्वां वधिष्यति।
अनेन कृतकृत्योऽस्मि म्रिये यदरिणा हतः॥', 'māṃ nihatya tu rāmo ''sau nacirāt tvāṃ vadhiṣyati
anena kṛtakṛtyo ''smi mriye yad ariṇā hataḥ', null, 3039017),
('ramayana-3-39-18', 18, 'Aranya Kanda, Sarga 39, Verse 18', 'दर्शनादेव रामस्य हतं मामुपधारय।
आत्मानं च हतं विद्धि हृत्वा सीतां सबान्धवम्॥', 'darśanād eva rāmasya hataṃ mām upadhāraya
ātmānaṃ ca hataṃ viddhi hṛtvā sītāṃ sabāndhavam', null, 3039018),
('ramayana-3-39-19', 19, 'Aranya Kanda, Sarga 39, Verse 19', 'आनयिष्यसि चेत्सीतामाश्रमात्सहितो मया।
नैव त्वमसि नैवाहं नैव लङ्का न राक्षसाः॥', 'ānayiṣyasi cet sītām āśramāt sahito mayā
naiva tvam asi naivāhaṃ naiva laṅkā na rākṣasāḥ', null, 3039019),
('ramayana-3-39-20', 20, 'Aranya Kanda, Sarga 39, Verse 20', 'निवार्यमाणस्तु मया हितैषिणा न मृष्यसे वाक्यमिदं निशाचर।
परेतकल्पा हि गतायुषो नरा हितं न गृह्णन्ति सुहृद्भिरीरितम्॥', 'nivāryamāṇas tu mayā hitaiṣiṇā na mṛṣyase vākyam idaṃ niśācara
paretakalpā hi gatāyuṣo narā hitaṃ na gṛhṇanti suhṛdbhir īritam', null, 3039020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 40 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-40-1', 1, 'Aranya Kanda, Sarga 40, Verse 1', 'एवमुक्त्वा तु परुषं मारीचो रावणं ततः।
गच्छावेत्यब्रवीद्दीनो भयाद्रात्रिंचरप्रभोः॥', 'evam uktvā tu paruṣaṃ mārīco rāvaṇaṃ tataḥ
gacchāvety abravīd dīno bhayād rātriṃcaraprabhoḥ', null, 3040001),
('ramayana-3-40-2', 2, 'Aranya Kanda, Sarga 40, Verse 2', 'दृष्टश्चाहं पुनस्तेन शरचापासिधारिणा।
मद्वधोद्यतशस्त्रेण विनष्टं जीवितं च मे॥', 'dṛṣṭaś cāhaṃ punas tena śaracāpāsidhāriṇā
madvadhodyataśastreṇa vinaṣṭaṃ jīvitaṃ ca me', null, 3040002),
('ramayana-3-40-3', 3, 'Aranya Kanda, Sarga 40, Verse 3', 'किं तु कर्तुं मया शक्यमेवं त्वयि दुरात्मनि।
एष गच्छाम्यहं तात स्वस्ति तेऽस्तु निशाचर॥', 'kiṃ tu kartuṃ mayā śakyam evaṃ tvayi durātmani
eṣa gacchāmy ahaṃ tāta svasti te ''stu niśācara', null, 3040003),
('ramayana-3-40-4', 4, 'Aranya Kanda, Sarga 40, Verse 4', 'प्रहृष्टस्त्वभवत्तेन वचनेन स राक्षसः।
परिष्वज्य सुसंश्लिष्टमिदं वचनमब्रवीत्॥', 'prahṛṣṭas tv abhavat tena vacanena sa rākṣasaḥ
pariṣvajya susaṃśliṣṭam idaṃ vacanam abravīt', null, 3040004),
('ramayana-3-40-5', 5, 'Aranya Kanda, Sarga 40, Verse 5', 'एतच्छौण्डीर्ययुक्तं ते मच्छन्दादिव भाषितम्।
इदानीमसि मारीचः पूर्वमन्यो निशाचरः॥', 'etac chauṇḍīryayuktaṃ te macchandād iva bhāṣitam
idānīm asi mārīcaḥ pūrvam anyo niśācaraḥ', null, 3040005),
('ramayana-3-40-6', 6, 'Aranya Kanda, Sarga 40, Verse 6', 'आरुह्यतामयं शीघ्रं खगो रत्नविभूषितः।
मया सह रथो युक्तः पिशाचवदनैः खरैः॥', 'āruhyatām ayaṃ śīghraṃ khago ratnavibhūṣitaḥ
mayā saha ratho yuktaḥ piśācavadanaiḥ kharaiḥ', null, 3040006),
('ramayana-3-40-7', 7, 'Aranya Kanda, Sarga 40, Verse 7', 'ततो रावणमारीचौ विमानमिव तं रथम्।
आरुह्य ययतुः शीघ्रं तस्मादाश्रममण्डलात्॥', 'tato rāvaṇamārīcau vimānam iva taṃ ratham
āruhya yayatuḥ śīghraṃ tasmād āśramamaṇḍalāt', null, 3040007),
('ramayana-3-40-8', 8, 'Aranya Kanda, Sarga 40, Verse 8', 'तथैव तत्र पश्यन्तौ पत्तनानि वनानि च।
गिरींश्च सरितः सर्वा राष्ट्राणि नगराणि च॥', 'tathaiva tatra paśyantau pattanāni vanāni ca
girīṃś ca saritaḥ sarvā rāṣṭrāṇi nagarāṇi ca', null, 3040008),
('ramayana-3-40-9', 9, 'Aranya Kanda, Sarga 40, Verse 9', 'समेत्य दण्डकारण्यं राघवस्याश्रमं ततः।
ददर्श सहमरीचो रावणो राक्षसाधिपः॥', 'sametya daṇḍakāraṇyaṃ rāghavasyāśramaṃ tataḥ
dadarśa sahamarīco rāvaṇo rākṣasādhipaḥ', null, 3040009),
('ramayana-3-40-10', 10, 'Aranya Kanda, Sarga 40, Verse 10', 'अवतीर्य रथात्तस्मात्ततः काञ्चनभूषणात्।
हस्ते गृहीत्वा मारीचं रावणो वाक्यमब्रवीत्॥', 'avatīrya rathāt tasmāt tataḥ kāñcanabhūṣaṇāt
haste gṛhītvā mārīcaṃ rāvaṇo vākyam abravīt', null, 3040010),
('ramayana-3-40-11', 11, 'Aranya Kanda, Sarga 40, Verse 11', 'एतद्रामाश्रमपदं दृश्यते कदलीवृतम्।
क्रियतां तत्सखे शीघ्रं यदर्थं वयमागताः॥', 'etad rāmāśramapadaṃ dṛśyate kadalīvṛtam
kriyatāṃ tat sakhe śīghraṃ yadarthaṃ vayam āgatāḥ', null, 3040011),
('ramayana-3-40-12', 12, 'Aranya Kanda, Sarga 40, Verse 12', 'स रावणवचः श्रुत्वा मारीचो राक्षसस्तदा।
मृगो भूत्वाश्रमद्वारि रामस्य विचचार ह॥', 'sa rāvaṇavacaḥ śrutvā mārīco rākṣasas tadā
mṛgo bhūtvāśramadvāri rāmasya vicacāra ha', null, 3040012),
('ramayana-3-40-13', 13, 'Aranya Kanda, Sarga 40, Verse 13', 'मणिप्रवरशृङ्गाग्रः सितासितमुखाकृतिः।
रक्तपद्मोत्पलमुख इन्द्रनीलोत्पलश्रवाः॥', 'maṇipravaraśṛṅgāgraḥ sitāsitamukhākṛtiḥ
raktapadmotpalamukha indranīlotpalaśravāḥ', null, 3040013),
('ramayana-3-40-14', 14, 'Aranya Kanda, Sarga 40, Verse 14', 'किं चिदभ्युन्नत ग्रीव इन्द्रनीलनिभोदरः।
मधूकनिभपार्श्वश्च कञ्जकिञ्जल्कसंनिभः॥', 'kiṃ cid abhyunnata grīva indranīlanibhodaraḥ
madhūkanibhapārśvaś ca kañjakiñjalkasaṃnibhaḥ', null, 3040014),
('ramayana-3-40-15', 15, 'Aranya Kanda, Sarga 40, Verse 15', 'वैदूर्यसंकाशखुरस्तनुजङ्घः सुसंहतः।
इन्द्रायुधसवर्णेन पुच्छेनोर्ध्वं विराजितः॥', 'vaidūryasaṃkāśakhuras tanujaṅghaḥ susaṃhataḥ
indrāyudhasavarṇena pucchenordhvaṃ virājitaḥ', null, 3040015),
('ramayana-3-40-16', 16, 'Aranya Kanda, Sarga 40, Verse 16', 'मनोहरस्निग्धवर्णो रत्नैर्नानाविधैर्वृतः।
क्षणेन राक्षसो जातो मृगः परमशोभनः॥', 'manoharasnigdhavarṇo ratnair nānāvidhair vṛtaḥ
kṣaṇena rākṣaso jāto mṛgaḥ paramaśobhanaḥ', null, 3040016),
('ramayana-3-40-17', 17, 'Aranya Kanda, Sarga 40, Verse 17', 'वनं प्रज्वलयन्रम्यं रामाश्रमपदं च तत्।
मनोहरं दर्शनीयं रूपं कृत्वा स राक्षसः॥', 'vanaṃ prajvalayan ramyaṃ rāmāśramapadaṃ ca tat
manoharaṃ darśanīyaṃ rūpaṃ kṛtvā sa rākṣasaḥ', null, 3040017),
('ramayana-3-40-18', 18, 'Aranya Kanda, Sarga 40, Verse 18', 'प्रलोभनार्थं वैदेह्या नानाधातुविचित्रितम्।
विचरन्गच्छते सम्यक्शाद्वलानि समन्ततः॥', 'pralobhanārthaṃ vaidehyā nānādhātuvicitritam
vicaran gacchate samyak śādvalāni samantataḥ', null, 3040018),
('ramayana-3-40-19', 19, 'Aranya Kanda, Sarga 40, Verse 19', 'रूप्यबिन्दुशतैश्चित्रो भूत्वा च प्रियदर्शनः।
विटपीनां किसलयान्भङ्क्त्वादन्विचचार ह॥', 'rūpyabinduśataiś citro bhūtvā ca priyadarśanaḥ
viṭapīnāṃ kisalayān bhaṅktvādan vicacāra ha', null, 3040019),
('ramayana-3-40-20', 20, 'Aranya Kanda, Sarga 40, Verse 20', 'कदलीगृहकं गत्वा कर्णिकारानितस्ततः।
समाश्रयन्मन्दगतिः सीतासंदर्शनं तदा॥', 'kadalīgṛhakaṃ gatvā karṇikārān itas tataḥ
samāśrayan mandagatiḥ sītāsaṃdarśanaṃ tadā', null, 3040020),
('ramayana-3-40-21', 21, 'Aranya Kanda, Sarga 40, Verse 21', 'राजीवचित्रपृष्ठः स विरराज महामृगः।
रामाश्रमपदाभ्याशे विचचार यथासुखम्॥', 'rājīvacitrapṛṣṭhaḥ sa virarāja mahāmṛgaḥ
rāmāśramapadābhyāśe vicacāra yathāsukham', null, 3040021),
('ramayana-3-40-22', 22, 'Aranya Kanda, Sarga 40, Verse 22', 'पुनर्गत्वा निवृत्तश्च विचचार मृगोत्तमः।
गत्वा मुहूर्तं त्वरया पुनः प्रतिनिवर्तते॥', 'punar gatvā nivṛttaś ca vicacāra mṛgottamaḥ
gatvā muhūrtaṃ tvarayā punaḥ pratinivartate', null, 3040022),
('ramayana-3-40-23', 23, 'Aranya Kanda, Sarga 40, Verse 23', 'विक्रीडंश्च पुनर्भूमौ पुनरेव निषीदति।
आश्रमद्वारमागम्य मृगयूथानि गच्छति॥', 'vikrīḍaṃś ca punar bhūmau punar eva niṣīdati
āśramadvāram āgamya mṛgayūthāni gacchati', null, 3040023),
('ramayana-3-40-24', 24, 'Aranya Kanda, Sarga 40, Verse 24', 'मृगयूथैरनुगतः पुनरेव निवर्तते।
सीतादर्शनमाकाङ्क्षन्राक्षसो मृगतां गतः॥', 'mṛgayūthair anugataḥ punar eva nivartate
sītādarśanam ākāṅkṣan rākṣaso mṛgatāṃ gataḥ', null, 3040024),
('ramayana-3-40-25', 25, 'Aranya Kanda, Sarga 40, Verse 25', 'परिभ्रमति चित्राणि मण्डलानि विनिष्पतन्।
समुद्वीक्ष्य च सर्वे तं मृगा येऽन्ये वनेचराः॥', 'paribhramati citrāṇi maṇḍalāni viniṣpatan
samudvīkṣya ca sarve taṃ mṛgā ye ''nye vanecarāḥ', null, 3040025),
('ramayana-3-40-26', 26, 'Aranya Kanda, Sarga 40, Verse 26', 'उपगम्य समाघ्राय विद्रवन्ति दिशो दश।
राक्षसः सोऽपि तान्वन्यान्मृगान्मृगवधे रतः॥', 'upagamya samāghrāya vidravanti diśo daśa
rākṣasaḥ so ''pi tān vanyān mṛgān mṛgavadhe rataḥ', null, 3040026),
('ramayana-3-40-27', 27, 'Aranya Kanda, Sarga 40, Verse 27', 'प्रच्छादनार्थं भावस्य न भक्षयति संस्पृशन्।
तस्मिन्नेव ततः काले वैदेही शुभलोचना॥', 'pracchādanārthaṃ bhāvasya na bhakṣayati saṃspṛśan
tasminn eva tataḥ kāle vaidehī śubhalocanā', null, 3040027),
('ramayana-3-40-28', 28, 'Aranya Kanda, Sarga 40, Verse 28', 'कुसुमापचये व्यग्रा पादपानत्यवर्तत।
कर्णिकारानशोकांश्च चूटांश्च मदिरेक्षणा॥', 'kusumāpacaye vyagrā pādapān atyavartata
karṇikārān aśokāṃś ca cūṭāṃś ca madirekṣaṇā', null, 3040028),
('ramayana-3-40-29', 29, 'Aranya Kanda, Sarga 40, Verse 29', 'कुसुमान्यपचिन्वन्ती चचार रुचिरानना।
अनर्हारण्यवासस्य सा तं रत्नमयं मृगम्।
मुक्तामणिविचित्राङ्गं ददर्श परमाङ्गना॥', 'kusumāny apacinvantī cacāra rucirānanā
anarhāraṇyavāsasya sā taṃ ratnamayaṃ mṛgam
muktāmaṇivicitrāṅgaṃ dadarśa paramāṅganā', null, 3040029),
('ramayana-3-40-30', 30, 'Aranya Kanda, Sarga 40, Verse 30', 'तं वै रुचिरदण्तौष्ठं रूप्यधातुतनूरुहम्।
विस्मयोत्फुल्लनयना सस्नेहं समुदैक्षत॥', 'taṃ vai ruciradaṇtauṣṭhaṃ rūpyadhātutanūruham
vismayotphullanayanā sasnehaṃ samudaikṣata', null, 3040030),
('ramayana-3-40-31', 31, 'Aranya Kanda, Sarga 40, Verse 31', 'स च तां रामदयितां पश्यन्मायामयो मृगः।
विचचार ततस्तत्र दीपयन्निव तद्वनम्॥', 'sa ca tāṃ rāmadayitāṃ paśyan māyāmayo mṛgaḥ
vicacāra tatas tatra dīpayann iva tad vanam', null, 3040031),
('ramayana-3-40-32', 32, 'Aranya Kanda, Sarga 40, Verse 32', 'अदृष्टपूर्वं दृष्ट्वा तं नानारत्नमयं मृगम्।
विस्मयं परमं सीता जगाम जनकात्मजा॥', 'adṛṣṭapūrvaṃ dṛṣṭvā taṃ nānāratnamayaṃ mṛgam
vismayaṃ paramaṃ sītā jagāma janakātmajā', null, 3040032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 41 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-41-1', 1, 'Aranya Kanda, Sarga 41, Verse 1', 'सा तं संप्रेक्ष्य सुश्रोणी कुसुमानि विचिन्वती।
हेमराजतवर्णाभ्यां पार्श्वाभ्यामुपशोभितम्॥', 'sā taṃ saṃprekṣya suśroṇī kusumāni vicinvatī
hemarājatavarṇābhyāṃ pārśvābhyām upaśobhitam', null, 3041001),
('ramayana-3-41-2', 2, 'Aranya Kanda, Sarga 41, Verse 2', 'प्रहृष्टा चानवद्याङ्गी मृष्टहाटकवर्णिनी।
भर्तारमपि चाक्रन्दल्लक्ष्मणं चैव सायुधम्॥', 'prahṛṣṭā cānavadyāṅgī mṛṣṭahāṭakavarṇinī
bhartāram api cākrandal lakṣmaṇaṃ caiva sāyudham', null, 3041002),
('ramayana-3-41-3', 3, 'Aranya Kanda, Sarga 41, Verse 3', 'तयाहूतौ नरव्याघ्रौ वैदेह्या रामलक्ष्मणौ।
वीक्षमाणौ तु तं देशं तदा ददृशतुर्मृगम्॥', 'tayāhūtau naravyāghrau vaidehyā rāmalakṣmaṇau
vīkṣamāṇau tu taṃ deśaṃ tadā dadṛśatur mṛgam', null, 3041003),
('ramayana-3-41-4', 4, 'Aranya Kanda, Sarga 41, Verse 4', 'शङ्कमानस्तु तं दृष्ट्वा लक्ष्मणो राममब्रवीत्।
तमेवैनमहं मन्ये मारीचं राक्षसं मृगम्॥', 'śaṅkamānas tu taṃ dṛṣṭvā lakṣmaṇo rāmam abravīt
tam evainam ahaṃ manye mārīcaṃ rākṣasaṃ mṛgam', null, 3041004),
('ramayana-3-41-5', 5, 'Aranya Kanda, Sarga 41, Verse 5', 'चरन्तो मृगयां हृष्टाः पापेनोपाधिना वने।
अनेन निहता राम राजानः कामरूपिणा॥', 'caranto mṛgayāṃ hṛṣṭāḥ pāpenopādhinā vane
anena nihatā rāma rājānaḥ kāmarūpiṇā', null, 3041005),
('ramayana-3-41-6', 6, 'Aranya Kanda, Sarga 41, Verse 6', 'अस्य मायाविदो मायामृगरूपमिदं कृतम्।
भानुमत्पुरुषव्याघ्र गन्धर्वपुरसंनिभम्॥', 'asya māyāvido māyāmṛgarūpam idaṃ kṛtam
bhānumatpuruṣavyāghra gandharvapurasaṃnibham', null, 3041006),
('ramayana-3-41-7', 7, 'Aranya Kanda, Sarga 41, Verse 7', 'मृगो ह्येवंविधो रत्नविचित्रो नास्ति राघव।
जगत्यां जगतीनाथ मायैषा हि न संशयः॥', 'mṛgo hy evaṃvidho ratnavicitro nāsti rāghava
jagatyāṃ jagatīnātha māyaiṣā hi na saṃśayaḥ', null, 3041007),
('ramayana-3-41-8', 8, 'Aranya Kanda, Sarga 41, Verse 8', 'एवं ब्रुवाणं काकुत्स्थं प्रतिवार्य शुचिस्मिता।
उवाच सीता संहृष्टा छद्मना हृतचेतना॥', 'evaṃ bruvāṇaṃ kākutsthaṃ prativārya śucismitā
uvāca sītā saṃhṛṣṭā chadmanā hṛtacetanā', null, 3041008),
('ramayana-3-41-9', 9, 'Aranya Kanda, Sarga 41, Verse 9', 'आर्यपुत्राभिरामोऽसौ मृगो हरति मे मनः।
आनयैनं महाबाहो क्रीडार्थं नो भविष्यति॥', 'āryaputrābhirāmo ''sau mṛgo harati me manaḥ
ānayainaṃ mahābāho krīḍārthaṃ no bhaviṣyati', null, 3041009),
('ramayana-3-41-10', 10, 'Aranya Kanda, Sarga 41, Verse 10', 'इहाश्रमपदेऽस्माकं बहवः पुण्यदर्शनाः।
मृगाश्चरन्ति सहिताश्चमराः सृमरास्तथा॥', 'ihāśramapade ''smākaṃ bahavaḥ puṇyadarśanāḥ
mṛgāś caranti sahitāś camarāḥ sṛmarās tathā', null, 3041010),
('ramayana-3-41-11', 11, 'Aranya Kanda, Sarga 41, Verse 11', 'ऋक्षाः पृषतसंघाश्च वानराः किंनरास्तथा।
विचरन्ति महाबाहो रूपश्रेष्ठा महाबलाः॥', 'ṛkṣāḥ pṛṣatasaṃghāś ca vānarāḥ kiṃnarās tathā
vicaranti mahābāho rūpaśreṣṭhā mahābalāḥ', null, 3041011),
('ramayana-3-41-12', 12, 'Aranya Kanda, Sarga 41, Verse 12', 'न चास्य सदृशो राजन्दृष्टपूर्वो मृगः पुरा।
तेजसा क्षमया दीप्त्या यथायं मृगसत्तमः॥', 'na cāsya sadṛśo rājan dṛṣṭapūrvo mṛgaḥ purā
tejasā kṣamayā dīptyā yathāyaṃ mṛgasattamaḥ', null, 3041012),
('ramayana-3-41-13', 13, 'Aranya Kanda, Sarga 41, Verse 13', 'नानावर्णविचित्राङ्गो रत्नबिन्दुसमाचितः।
द्योतयन्वनमव्यग्रं शोभते शशिसंनिभः॥', 'nānāvarṇavicitrāṅgo ratnabindusamācitaḥ
dyotayan vanam avyagraṃ śobhate śaśisaṃnibhaḥ', null, 3041013),
('ramayana-3-41-14', 14, 'Aranya Kanda, Sarga 41, Verse 14', 'अहो रूपमहो लक्ष्मीः स्वरसंपच्च शोभना।
मृगोऽद्भुतो विचित्रोऽसौ हृदयं हरतीव मे॥', 'aho rūpam aho lakṣmīḥ svarasaṃpac ca śobhanā
mṛgo ''dbhuto vicitro ''sau hṛdayaṃ haratīva me', null, 3041014),
('ramayana-3-41-15', 15, 'Aranya Kanda, Sarga 41, Verse 15', 'यदि ग्रहणमभ्येति जीवन्नेव मृगस्तव।
आश्चर्यभूतं भवति विस्मयं जनयिष्यति॥', 'yadi grahaṇam abhyeti jīvann eva mṛgas tava
āścaryabhūtaṃ bhavati vismayaṃ janayiṣyati', null, 3041015),
('ramayana-3-41-16', 16, 'Aranya Kanda, Sarga 41, Verse 16', 'समाप्तवनवासानां राज्यस्थानां च नः पुनः।
अन्तःपुरविभूषार्थो मृग एष भविष्यति॥', 'samāptavanavāsānāṃ rājyasthānāṃ ca naḥ punaḥ
antaḥpuravibhūṣārtho mṛga eṣa bhaviṣyati', null, 3041016),
('ramayana-3-41-17', 17, 'Aranya Kanda, Sarga 41, Verse 17', 'भरतस्यार्यपुत्रस्य श्वश्रूणां मम च प्रभो।
मृगरूपमिदं दिव्यं विस्मयं जनयिष्यति॥', 'bharatasyāryaputrasya śvaśrūṇāṃ mama ca prabho
mṛgarūpam idaṃ divyaṃ vismayaṃ janayiṣyati', null, 3041017),
('ramayana-3-41-18', 18, 'Aranya Kanda, Sarga 41, Verse 18', 'जीवन्न यदि तेऽभ्येति ग्रहणं मृगसत्तमः।
अजिनं नरशार्दूल रुचिरं मे भविष्यति॥', 'jīvan na yadi te ''bhyeti grahaṇaṃ mṛgasattamaḥ
ajinaṃ naraśārdūla ruciraṃ me bhaviṣyati', null, 3041018),
('ramayana-3-41-19', 19, 'Aranya Kanda, Sarga 41, Verse 19', 'निहतस्यास्य सत्त्वस्य जाम्बूनदमयत्वचि।
शष्पबृस्यां विनीतायामिच्छाम्यहमुपासितुम्॥', 'nihatasyāsya sattvasya jāmbūnadamayatvaci
śaṣpabṛsyāṃ vinītāyām icchāmy aham upāsitum', null, 3041019),
('ramayana-3-41-20', 20, 'Aranya Kanda, Sarga 41, Verse 20', 'कामवृत्तमिदं रौद्रं स्त्रीणामसदृशं मतम्।
वपुषा त्वस्य सत्त्वस्य विस्मयो जनितो मम॥', 'kāmavṛttam idaṃ raudraṃ strīṇām asadṛśaṃ matam
vapuṣā tv asya sattvasya vismayo janito mama', null, 3041020),
('ramayana-3-41-21', 21, 'Aranya Kanda, Sarga 41, Verse 21', 'तेन काञ्चनरोम्णा तु मणिप्रवरशृङ्गिणा।
तरुणादित्यवर्णेन नक्षत्रपथवर्चसा।
बभूव राघवस्यापि मनो विस्मयमागतम्॥', 'tena kāñcanaromṇā tu maṇipravaraśṛṅgiṇā
taruṇādityavarṇena nakṣatrapathavarcasā
babhūva rāghavasyāpi mano vismayam āgatam', null, 3041021),
('ramayana-3-41-22', 22, 'Aranya Kanda, Sarga 41, Verse 22', 'एवं सीतावचः श्रुत्वा दृष्ट्वा च मृगमद्भुतम्।
उवाच राघवो हृष्टो भ्रातरं लक्ष्मणं वचः॥', 'evaṃ sītāvacaḥ śrutvā dṛṣṭvā ca mṛgam adbhutam
uvāca rāghavo hṛṣṭo bhrātaraṃ lakṣmaṇaṃ vacaḥ', null, 3041022),
('ramayana-3-41-23', 23, 'Aranya Kanda, Sarga 41, Verse 23', 'पश्य लक्ष्मण वैदेह्याः स्पृहां मृगगतामिमाम्।
रूपश्रेष्ठतया ह्येष मृगोऽद्य न भविष्यति॥', 'paśya lakṣmaṇa vaidehyāḥ spṛhāṃ mṛgagatām imām
rūpaśreṣṭhatayā hy eṣa mṛgo ''dya na bhaviṣyati', null, 3041023),
('ramayana-3-41-24', 24, 'Aranya Kanda, Sarga 41, Verse 24', 'न वने नन्दनोद्देशे न चैत्ररथसंश्रये।
कुतः पृथिव्यां सौमित्रे योऽस्य कश्चित्समो मृगः॥', 'na vane nandanoddeśe na caitrarathasaṃśraye
kutaḥ pṛthivyāṃ saumitre yo ''sya kaś cit samo mṛgaḥ', null, 3041024),
('ramayana-3-41-25', 25, 'Aranya Kanda, Sarga 41, Verse 25', 'प्रतिलोमानुलोमाश्च रुचिरा रोमराजयः।
शोभन्ते मृगमाश्रित्य चित्राः कनकबिन्दुभिः॥', 'pratilomānulomāś ca rucirā romarājayaḥ
śobhante mṛgam āśritya citrāḥ kanakabindubhiḥ', null, 3041025),
('ramayana-3-41-26', 26, 'Aranya Kanda, Sarga 41, Verse 26', 'पश्यास्य जृम्भमाणस्य दीप्तामग्निशिखोपमाम्।
जिह्वां मुखान्निःसरन्तीं मेघादिव शतह्रदाम्॥', 'paśyāsya jṛmbhamāṇasya dīptām agniśikhopamām
jihvāṃ mukhān niḥsarantīṃ meghād iva śatahradām', null, 3041026),
('ramayana-3-41-27', 27, 'Aranya Kanda, Sarga 41, Verse 27', 'मसारगल्वर्कमुखः शङ्खमुक्तानिभोदरः।
कस्य नामानिरूप्योऽसौ न मनो लोभयेन्मृगः॥', 'masāragalvarkamukhaḥ śaṅkhamuktānibhodaraḥ
kasya nāmānirūpyo ''sau na mano lobhayen mṛgaḥ', null, 3041027),
('ramayana-3-41-28', 28, 'Aranya Kanda, Sarga 41, Verse 28', 'कस्य रूपमिदं दृष्ट्वा जाम्बूनदमयप्रभम्।
नानारत्नमयं दिव्यं न मनो विस्मयं व्रजेत्॥', 'kasya rūpam idaṃ dṛṣṭvā jāmbūnadamayaprabham
nānāratnamayaṃ divyaṃ na mano vismayaṃ vrajet', null, 3041028),
('ramayana-3-41-29', 29, 'Aranya Kanda, Sarga 41, Verse 29', 'मांसहेतोरपि मृगान्विहारार्थं च धन्विनः।
घ्नन्ति लक्ष्मण राजानो मृगयायां महावने॥', 'māṃsahetor api mṛgān vihārārthaṃ ca dhanvinaḥ
ghnanti lakṣmaṇa rājāno mṛgayāyāṃ mahāvane', null, 3041029),
('ramayana-3-41-30', 30, 'Aranya Kanda, Sarga 41, Verse 30', 'धनानि व्यवसायेन विचीयन्ते महावने।
धातवो विविधाश्चापि मणिरत्नसुवर्णिनः॥', 'dhanāni vyavasāyena vicīyante mahāvane
dhātavo vividhāś cāpi maṇiratnasuvarṇinaḥ', null, 3041030),
('ramayana-3-41-31', 31, 'Aranya Kanda, Sarga 41, Verse 31', 'तत्सारमखिलं नॄणां धनं निचयवर्धनम्।
मनसा चिन्तितं सर्वं यथा शुक्रस्य लक्ष्मण॥', 'tat sāram akhilaṃ nṝṇāṃ dhanaṃ nicayavardhanam
manasā cintitaṃ sarvaṃ yathā śukrasya lakṣmaṇa', null, 3041031),
('ramayana-3-41-32', 32, 'Aranya Kanda, Sarga 41, Verse 32', 'अर्थी येनार्थकृत्येन संव्रजत्यविचारयन्।
तमर्थमर्थशास्त्रज्ञः प्राहुरर्थ्याश्च लक्ष्मण॥', 'arthī yenārthakṛtyena saṃvrajaty avicārayan
tam artham arthaśāstrajñaḥ prāhur arthyāś ca lakṣmaṇa', null, 3041032),
('ramayana-3-41-33', 33, 'Aranya Kanda, Sarga 41, Verse 33', 'एतस्य मृगरत्नस्य परार्ध्ये काञ्चनत्वचि।
उपवेक्ष्यति वैदेही मया सह सुमध्यमा॥', 'etasya mṛgaratnasya parārdhye kāñcanatvaci
upavekṣyati vaidehī mayā saha sumadhyamā', null, 3041033),
('ramayana-3-41-34', 34, 'Aranya Kanda, Sarga 41, Verse 34', 'न कादली न प्रियकी न प्रवेणी न चाविकी।
भवेदेतस्य सदृशी स्पर्शनेनेति मे मतिः॥', 'na kādalī na priyakī na praveṇī na cāvikī
bhaved etasya sadṛśī sparśaneneti me matiḥ', null, 3041034),
('ramayana-3-41-35', 35, 'Aranya Kanda, Sarga 41, Verse 35', 'एष चैव मृगः श्रीमान्यश्च दिव्यो नभश्चरः।
उभावेतौ मृगौ दिव्यौ तारामृगमहीमृगौ॥', 'eṣa caiva mṛgaḥ śrīmān yaś ca divyo nabhaścaraḥ
ubhāv etau mṛgau divyau tārāmṛgamahīmṛgau', null, 3041035),
('ramayana-3-41-36', 36, 'Aranya Kanda, Sarga 41, Verse 36', 'यदि वायं तथा यन्मां भवेद्वदसि लक्ष्मण।
मायैषा राक्षसस्येति कर्तव्योऽस्य वधो मया॥', 'yadi vāyaṃ tathā yan māṃ bhaved vadasi lakṣmaṇa
māyaiṣā rākṣasasyeti kartavyo ''sya vadho mayā', null, 3041036),
('ramayana-3-41-37', 37, 'Aranya Kanda, Sarga 41, Verse 37', 'एतेन हि नृशंसेन मारीचेनाकृतात्मना।
वने विचरता पूर्वं हिंसिता मुनिपुंगवाः॥', 'etena hi nṛśaṃsena mārīcenākṛtātmanā
vane vicaratā pūrvaṃ hiṃsitā munipuṃgavāḥ', null, 3041037),
('ramayana-3-41-38', 38, 'Aranya Kanda, Sarga 41, Verse 38', 'उत्थाय बहवो येन मृगयायां जनाधिपाः।
निहताः परमेष्वासास्तस्माद्वध्यस्त्वयं मृगः॥', 'utthāya bahavo yena mṛgayāyāṃ janādhipāḥ
nihatāḥ parameṣvāsās tasmād vadhyas tv ayaṃ mṛgaḥ', null, 3041038),
('ramayana-3-41-39', 39, 'Aranya Kanda, Sarga 41, Verse 39', 'पुरस्तादिह वातापिः परिभूय तपस्विनः।
उदरस्थो द्विजान्हन्ति स्वगर्भोऽश्वतरीमिव॥', 'purastād iha vātāpiḥ paribhūya tapasvinaḥ
udarastho dvijān hanti svagarbho ''śvatarīm iva', null, 3041039),
('ramayana-3-41-40', 40, 'Aranya Kanda, Sarga 41, Verse 40', 'स कदा चिच्चिराल्लोके आससाद महामुनिम्।
अगस्त्यं तेजसा युक्तं भक्ष्यस्तस्य बभूव ह॥', 'sa kadā cic cirāl loke āsasāda mahāmunim
agastyaṃ tejasā yuktaṃ bhakṣyas tasya babhūva ha', null, 3041040),
('ramayana-3-41-41', 41, 'Aranya Kanda, Sarga 41, Verse 41', 'समुत्थाने च तद्रूपं कर्तुकामं समीक्ष्य तम्।
उत्स्मयित्वा तु भगवान्वातापिमिदमब्रवीत्॥', 'samutthāne ca tad rūpaṃ kartukāmaṃ samīkṣya tam
utsmayitvā tu bhagavān vātāpim idam abravīt', null, 3041041),
('ramayana-3-41-42', 42, 'Aranya Kanda, Sarga 41, Verse 42', 'त्वयाविगण्य वातापे परिभूताश्च तेजसा।
जीवलोके द्विजश्रेष्ठास्तस्मादसि जरां गतः॥', 'tvayāvigaṇya vātāpe paribhūtāś ca tejasā
jīvaloke dvijaśreṣṭhās tasmād asi jarāṃ gataḥ', null, 3041042),
('ramayana-3-41-43', 43, 'Aranya Kanda, Sarga 41, Verse 43', 'एवं तन्न भवेद्रक्षो वातापिरिव लक्ष्मण।
मद्विधं योऽतिमन्येत धर्मनित्यं जितेन्द्रियम्॥', 'evaṃ tan na bhaved rakṣo vātāpir iva lakṣmaṇa
madvidhaṃ yo ''timanyeta dharmanityaṃ jitendriyam', null, 3041043),
('ramayana-3-41-44', 44, 'Aranya Kanda, Sarga 41, Verse 44', 'भवेद्धतोऽयं वातापिरगस्त्येनेव मा गतिः।
इह त्वं भव संनद्धो यन्त्रितो रक्ष मैथिलीम्॥', 'bhaved dhato ''yaṃ vātāpir agastyeneva mā gatiḥ
iha tvaṃ bhava saṃnaddho yantrito rakṣa maithilīm', null, 3041044),
('ramayana-3-41-45', 45, 'Aranya Kanda, Sarga 41, Verse 45', 'अस्यामायत्तमस्माकं यत्कृत्यं रघुनन्दन।
अहमेनं वधिष्यामि ग्रहीष्याम्यथ वा मृगम्॥', 'asyām āyattam asmākaṃ yat kṛtyaṃ raghunandana
aham enaṃ vadhiṣyāmi grahīṣyāmy atha vā mṛgam', null, 3041045),
('ramayana-3-41-46', 46, 'Aranya Kanda, Sarga 41, Verse 46', 'यावद्गच्छामि सौमित्रे मृगमानयितुं द्रुतम्।
पश्य लक्ष्मण वैदेहीं मृगत्वचि गतस्पृहाम्॥', 'yāvad gacchāmi saumitre mṛgam ānayituṃ drutam
paśya lakṣmaṇa vaidehīṃ mṛgatvaci gataspṛhām', null, 3041046),
('ramayana-3-41-47', 47, 'Aranya Kanda, Sarga 41, Verse 47', 'त्वचा प्रधानया ह्येष मृगोऽद्य न भविष्यति।
अप्रमत्तेन ते भाव्यमाश्रमस्थेन सीतया॥', 'tvacā pradhānayā hy eṣa mṛgo ''dya na bhaviṣyati
apramattena te bhāvyam āśramasthena sītayā', null, 3041047),
('ramayana-3-41-48', 48, 'Aranya Kanda, Sarga 41, Verse 48', 'यावत्पृषतमेकेन सायकेन निहन्म्यहम्।
हत्वैतच्चर्म आदाय शीघ्रमेष्यामि लक्ष्मण॥', 'yāvat pṛṣatam ekena sāyakena nihanmy aham
hatvaitac carma ādāya śīghram eṣyāmi lakṣmaṇa', null, 3041048),
('ramayana-3-41-49', 49, 'Aranya Kanda, Sarga 41, Verse 49', 'प्रदक्षिणेनातिबलेन पक्षिणा जटायुषा बुद्धिमता च लक्ष्मण।
भवाप्रमत्तः प्रतिगृह्य मैथिलीं प्रतिक्षणं सर्वत एव शङ्कितः॥', 'pradakṣiṇenātibalena pakṣiṇā jaṭāyuṣā buddhimatā ca lakṣmaṇa
bhavāpramattaḥ pratigṛhya maithilīṃ pratikṣaṇaṃ sarvata eva śaṅkitaḥ', null, 3041049)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 42 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-42-1', 1, 'Aranya Kanda, Sarga 42, Verse 1', 'तथा तु तं समादिश्य भ्रातरं रघुनन्दनः।
बबन्धासिं महातेजा जाम्बूनदमयत्सरुम्॥', 'tathā tu taṃ samādiśya bhrātaraṃ raghunandanaḥ
babandhāsiṃ mahātejā jāmbūnadamayatsarum', null, 3042001),
('ramayana-3-42-2', 2, 'Aranya Kanda, Sarga 42, Verse 2', 'ततस्त्रिविणतं चापमादायात्मविभूषणम्।
आबध्य च कलापौ द्वौ जगामोदग्रविक्रमः॥', 'tatas triviṇataṃ cāpam ādāyātmavibhūṣaṇam
ābadhya ca kalāpau dvau jagāmodagravikramaḥ', null, 3042002),
('ramayana-3-42-3', 3, 'Aranya Kanda, Sarga 42, Verse 3', 'तं वञ्चयानो राजेन्द्रमापतन्तं निरीक्ष्य वै।
बभूवान्तर्हितस्त्रासात्पुनः संदर्शनेऽभवत्॥', 'taṃ vañcayāno rājendram āpatantaṃ nirīkṣya vai
babhūvāntarhitas trāsāt punaḥ saṃdarśane ''bhavat', null, 3042003),
('ramayana-3-42-4', 4, 'Aranya Kanda, Sarga 42, Verse 4', 'बद्धासिर्धनुरादाय प्रदुद्राव यतो मृगः।
तं स पश्यति रूपेण द्योतमानमिवाग्रतः॥', 'baddhāsir dhanur ādāya pradudrāva yato mṛgaḥ
taṃ sa paśyati rūpeṇa dyotamānam ivāgrataḥ', null, 3042004),
('ramayana-3-42-5', 5, 'Aranya Kanda, Sarga 42, Verse 5', 'अवेक्ष्यावेक्ष्य धावन्तं धनुष्पाणिर्महावने।
अतिवृत्तमिषोः पाताल्लोभयानं कदा चन॥', 'avekṣyāvekṣya dhāvantaṃ dhanuṣpāṇir mahāvane
ativṛttam iṣoḥ pātāl lobhayānaṃ kadā cana', null, 3042005),
('ramayana-3-42-6', 6, 'Aranya Kanda, Sarga 42, Verse 6', 'शङ्कितं तु समुद्भ्रान्तमुत्पतन्तमिवाम्बरे।
दश्यमानमदृश्यं च नवोद्देशेषु केषु चित्॥', 'śaṅkitaṃ tu samudbhrāntam utpatantam ivāmbare
daśyamānam adṛśyaṃ ca navoddeśeṣu keṣu cit', null, 3042006),
('ramayana-3-42-7', 7, 'Aranya Kanda, Sarga 42, Verse 7', 'छिन्नाभ्रैरिव संवीतं शारदं चन्द्रमण्डलम्।
मुहूर्तादेव ददृशे मुहुर्दूरात्प्रकाशते॥', 'chinnābhrair iva saṃvītaṃ śāradaṃ candramaṇḍalam
muhūrtād eva dadṛśe muhur dūrāt prakāśate', null, 3042007),
('ramayana-3-42-8', 8, 'Aranya Kanda, Sarga 42, Verse 8', 'दर्शनादर्शनेनैव सोऽपाकर्षत राघवम्।
आसीत्क्रुद्धस्तु काकुत्स्थो विवशस्तेन मोहितः॥', 'darśanādarśanenaiva so ''pākarṣata rāghavam
āsīt kruddhas tu kākutstho vivaśas tena mohitaḥ', null, 3042008),
('ramayana-3-42-9', 9, 'Aranya Kanda, Sarga 42, Verse 9', 'अथावतस्थे सुश्रान्तश्छायामाश्रित्य शाद्वले।
मृगैः परिवृतो वन्यैरदूरात्प्रत्यदृश्यत॥', 'athāvatasthe suśrāntaś chāyām āśritya śādvale
mṛgaiḥ parivṛto vanyair adūrāt pratyadṛśyata', null, 3042009),
('ramayana-3-42-10', 10, 'Aranya Kanda, Sarga 42, Verse 10', 'दृष्ट्वा रामो महातेजास्तं हन्तुं कृतनिश्चयः।
संधाय सुदृढे चापे विकृष्य बलवद्बली॥', 'dṛṣṭvā rāmo mahātejās taṃ hantuṃ kṛtaniścayaḥ
saṃdhāya sudṛḍhe cāpe vikṛṣya balavad balī', null, 3042010),
('ramayana-3-42-11', 11, 'Aranya Kanda, Sarga 42, Verse 11', 'तमेव मृगमुद्दिश्य ज्वलन्तमिव पन्नगम्।
मुमोच ज्वलितं दीप्तमस्त्रब्रह्मविनिर्मितम्॥', 'tam eva mṛgam uddiśya jvalantam iva pannagam
mumoca jvalitaṃ dīptam astrabrahmavinirmitam', null, 3042011),
('ramayana-3-42-12', 12, 'Aranya Kanda, Sarga 42, Verse 12', 'स भृशं मृगरूपस्य विनिर्भिद्य शरोत्तमः।
मारीचस्यैव हृदयं विभेदाशनिसंनिभः॥', 'sa bhṛśaṃ mṛgarūpasya vinirbhidya śarottamaḥ
mārīcasyaiva hṛdayaṃ vibhedāśanisaṃnibhaḥ', null, 3042012),
('ramayana-3-42-13', 13, 'Aranya Kanda, Sarga 42, Verse 13', 'तालमात्रमथोत्पत्य न्यपतत्स शरातुरः।
व्यनदद्भैरवं नादं धरण्यामल्पजीवितः।
म्रियमाणस्तु मारीचो जहौ तां कृत्रिमां तनुम्॥', 'tālamātram athotpatya nyapatat sa śarāturaḥ
vyanadad bhairavaṃ nādaṃ dharaṇyām alpajīvitaḥ
mriyamāṇas tu mārīco jahau tāṃ kṛtrimāṃ tanum', null, 3042013),
('ramayana-3-42-14', 14, 'Aranya Kanda, Sarga 42, Verse 14', 'संप्राप्तकालमाज्ञाय चकार च ततः स्वरम्।
सदृशं राघवस्यैव हा सीते लक्ष्मणेति च॥', 'saṃprāptakālam ājñāya cakāra ca tataḥ svaram
sadṛśaṃ rāghavasyaiva hā sīte lakṣmaṇeti ca', null, 3042014),
('ramayana-3-42-15', 15, 'Aranya Kanda, Sarga 42, Verse 15', 'तेन मर्मणि निर्विद्धः शरेणानुपमेन हि।
मृगरूपं तु तत्त्यक्त्वा राक्षसं रूपमात्मनः।
चक्रे स सुमहाकायो मारीचो जीवितं त्यजन्॥', 'tena marmaṇi nirviddhaḥ śareṇānupamena hi
mṛgarūpaṃ tu tat tyaktvā rākṣasaṃ rūpam ātmanaḥ
cakre sa sumahākāyo mārīco jīvitaṃ tyajan', null, 3042015),
('ramayana-3-42-16', 16, 'Aranya Kanda, Sarga 42, Verse 16', 'ततो विचित्रकेयूरः सर्वाभरणभूषितः।
हेममाली महादंष्ट्रो राक्षसोऽभूच्छराहतः॥', 'tato vicitrakeyūraḥ sarvābharaṇabhūṣitaḥ
hemamālī mahādaṃṣṭro rākṣaso ''bhūc charāhataḥ', null, 3042016),
('ramayana-3-42-17', 17, 'Aranya Kanda, Sarga 42, Verse 17', 'तं दृष्ट्वा पतितं भूमौ राक्षसं घोरदर्शनम्।
जगाम मनसा सीतां लक्ष्मणस्य वचः स्मरन्॥', 'taṃ dṛṣṭvā patitaṃ bhūmau rākṣasaṃ ghoradarśanam
jagāma manasā sītāṃ lakṣmaṇasya vacaḥ smaran', null, 3042017),
('ramayana-3-42-18', 18, 'Aranya Kanda, Sarga 42, Verse 18', 'हा सीते लक्ष्मणेत्येवमाक्रुश्य तु महास्वरम्।
ममार राक्षसः सोऽयं श्रुत्वा सीता कथं भवेत्॥', 'hā sīte lakṣmaṇety evam ākruśya tu mahāsvaram
mamāra rākṣasaḥ so ''yaṃ śrutvā sītā kathaṃ bhavet', null, 3042018),
('ramayana-3-42-19', 19, 'Aranya Kanda, Sarga 42, Verse 19', 'लक्ष्मणश्च महाबाहुः कामवस्थां गमिष्यति।
इति संचिन्त्य धर्मात्मा रामो हृष्टतनूरुहः॥', 'lakṣmaṇaś ca mahābāhuḥ kām avasthāṃ gamiṣyati
iti saṃcintya dharmātmā rāmo hṛṣṭatanūruhaḥ', null, 3042019),
('ramayana-3-42-20', 20, 'Aranya Kanda, Sarga 42, Verse 20', 'तत्र रामं भयं तीव्रमाविवेश विषादजम्।
राक्षसं मृगरूपं तं हत्वा श्रुत्वा च तत्स्वरम्॥', 'tatra rāmaṃ bhayaṃ tīvram āviveśa viṣādajam
rākṣasaṃ mṛgarūpaṃ taṃ hatvā śrutvā ca tat svaram', null, 3042020),
('ramayana-3-42-21', 21, 'Aranya Kanda, Sarga 42, Verse 21', 'निहत्य पृषतं चान्यं मांसमादाय राघवः।
त्वरमाणो जनस्थानं ससाराभिमुखस्तदा॥', 'nihatya pṛṣataṃ cānyaṃ māṃsam ādāya rāghavaḥ
tvaramāṇo janasthānaṃ sasārābhimukhas tadā', null, 3042021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 43 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-43-1', 1, 'Aranya Kanda, Sarga 43, Verse 1', 'आर्तस्वरं तु तं भर्तुर्विज्ञाय सदृशं वने।
उवाच लक्ष्मणं सीता गच्छ जानीहि राघवम्॥', 'ārtasvaraṃ tu taṃ bhartur vijñāya sadṛśaṃ vane
uvāca lakṣmaṇaṃ sītā gaccha jānīhi rāghavam', null, 3043001),
('ramayana-3-43-2', 2, 'Aranya Kanda, Sarga 43, Verse 2', 'न हि मे जीवितं स्थाने हृदयं वावतिष्ठते।
क्रोशतः परमार्तस्य श्रुतः शब्दो मया भृशम्॥', 'na hi me jīvitaṃ sthāne hṛdayaṃ vāvatiṣṭhate
krośataḥ paramārtasya śrutaḥ śabdo mayā bhṛśam', null, 3043002),
('ramayana-3-43-3', 3, 'Aranya Kanda, Sarga 43, Verse 3', 'आक्रन्दमानं तु वने भ्रातरं त्रातुमर्हसि।
तं क्षिप्रमभिधाव त्वं भ्रातरं शरणैषिणम्॥', 'ākrandamānaṃ tu vane bhrātaraṃ trātum arhasi
taṃ kṣipram abhidhāva tvaṃ bhrātaraṃ śaraṇaiṣiṇam', null, 3043003),
('ramayana-3-43-4', 4, 'Aranya Kanda, Sarga 43, Verse 4', 'रक्षसां वशमापन्नं सिंहानामिव गोवृषम्।
न जगाम तथोक्तस्तु भ्रातुराज्ञाय शासनम्॥', 'rakṣasāṃ vaśam āpannaṃ siṃhānām iva govṛṣam
na jagāma tathoktas tu bhrātur ājñāya śāsanam', null, 3043004),
('ramayana-3-43-5', 5, 'Aranya Kanda, Sarga 43, Verse 5', 'तमुवाच ततस्तत्र कुपिता जनकात्मजा।
सौमित्रे मित्ररूपेण भ्रातुस्त्वमसि शत्रुवत्॥', 'tam uvāca tatas tatra kupitā janakātmajā
saumitre mitrarūpeṇa bhrātus tvam asi śatruvat', null, 3043005),
('ramayana-3-43-6', 6, 'Aranya Kanda, Sarga 43, Verse 6', 'यस्त्वमस्यामवस्थायां भ्रातरं नाभिपद्यसे।
इच्छसि त्वं विनश्यन्तं रामं लक्ष्मण मत्कृते॥', 'yas tvam asyām avasthāyāṃ bhrātaraṃ nābhipadyase
icchasi tvaṃ vinaśyantaṃ rāmaṃ lakṣmaṇa matkṛte', null, 3043006),
('ramayana-3-43-7', 7, 'Aranya Kanda, Sarga 43, Verse 7', 'व्यसनं ते प्रियं मन्ये स्नेहो भ्रातरि नास्ति ते।
तेन तिष्ठसि विस्रब्धस्तमपश्यन्महाद्युतिम्॥', 'vyasanaṃ te priyaṃ manye sneho bhrātari nāsti te
tena tiṣṭhasi visrabdhas tam apaśyan mahādyutim', null, 3043007),
('ramayana-3-43-8', 8, 'Aranya Kanda, Sarga 43, Verse 8', 'किं हि संशयमापन्ने तस्मिन्निह मया भवेत्।
कर्तव्यमिह तिष्ठन्त्या यत्प्रधानस्त्वमागतः॥', 'kiṃ hi saṃśayam āpanne tasminn iha mayā bhavet
kartavyam iha tiṣṭhantyā yat pradhānas tvam āgataḥ', null, 3043008),
('ramayana-3-43-9', 9, 'Aranya Kanda, Sarga 43, Verse 9', 'इति ब्रुवाणं वैदेहीं बाष्पशोकपरिप्लुताम्।
अब्रवील्लक्ष्मणस्त्रस्तां सीतां मृगवधूमिव॥', 'iti bruvāṇaṃ vaidehīṃ bāṣpaśokapariplutām
abravīl lakṣmaṇas trastāṃ sītāṃ mṛgavadhūm iva', null, 3043009),
('ramayana-3-43-10', 10, 'Aranya Kanda, Sarga 43, Verse 10', 'देवि देवमनुष्येषु गन्धर्वेषु पतत्रिषु।
राक्षसेषु पिशाचेषु किंनरेषु मृगेषु च॥', 'devi devamanuṣyeṣu gandharveṣu patatriṣu
rākṣaseṣu piśāceṣu kiṃnareṣu mṛgeṣu ca', null, 3043010),
('ramayana-3-43-11', 11, 'Aranya Kanda, Sarga 43, Verse 11', 'दानवेषु च घोरेषु न स विद्येत शोभने।
यो रामं प्रतियुध्येत समरे वासवोपमम्॥', 'dānaveṣu ca ghoreṣu na sa vidyeta śobhane
yo rāmaṃ pratiyudhyeta samare vāsavopamam', null, 3043011),
('ramayana-3-43-12', 12, 'Aranya Kanda, Sarga 43, Verse 12', 'अवध्यः समरे रामो नैवं त्वं वक्तुमर्हसि।
न त्वामस्मिन्वने हातुमुत्सहे राघवं विना॥', 'avadhyaḥ samare rāmo naivaṃ tvaṃ vaktum arhasi
na tvām asmin vane hātum utsahe rāghavaṃ vinā', null, 3043012),
('ramayana-3-43-13', 13, 'Aranya Kanda, Sarga 43, Verse 13', 'अनिवार्यं बलं तस्य बलैर्बलवतामपि।
त्रिभिर्लोकैः समुद्युक्तैः सेश्वरैः सामरैरपि॥', 'anivāryaṃ balaṃ tasya balair balavatām api
tribhir lokaiḥ samudyuktaiḥ seśvaraiḥ sāmarair api', null, 3043013),
('ramayana-3-43-14', 14, 'Aranya Kanda, Sarga 43, Verse 14', 'हृदयं निर्वृतं तेऽस्तु संतापस्त्यज्यतामयम्।
आगमिष्यति ते भर्ता शीघ्रं हत्वा मृगोत्तमम्॥', 'hṛdayaṃ nirvṛtaṃ te ''stu saṃtāpas tyajyatām ayam
āgamiṣyati te bhartā śīghraṃ hatvā mṛgottamam', null, 3043014),
('ramayana-3-43-15', 15, 'Aranya Kanda, Sarga 43, Verse 15', 'न स तस्य स्वरो व्यक्तं न कश्चिदपि दैवतः।
गन्धर्वनगरप्रख्या माया सा तस्य रक्षसः॥', 'na sa tasya svaro vyaktaṃ na kaś cid api daivataḥ
gandharvanagaraprakhyā māyā sā tasya rakṣasaḥ', null, 3043015),
('ramayana-3-43-16', 16, 'Aranya Kanda, Sarga 43, Verse 16', 'न्यासभूतासि वैदेहि न्यस्ता मयि महात्मना।
रामेण त्वं वरारोहे न त्वां त्यक्तुमिहोत्सहे॥', 'nyāsabhūtāsi vaidehi nyastā mayi mahātmanā
rāmeṇa tvaṃ varārohe na tvāṃ tyaktum ihotsahe', null, 3043016),
('ramayana-3-43-17', 17, 'Aranya Kanda, Sarga 43, Verse 17', 'कृतवैराश्च कल्याणि वयमेतैर्निशाचरैः।
खरस्य निधने देवि जनस्थानवधं प्रति॥', 'kṛtavairāś ca kalyāṇi vayam etair niśācaraiḥ
kharasya nidhane devi janasthānavadhaṃ prati', null, 3043017),
('ramayana-3-43-18', 18, 'Aranya Kanda, Sarga 43, Verse 18', 'राक्षसा विधिना वाचो विसृजन्ति महावने।
हिंसाविहारा वैदेहि न चिन्तयितुमर्हसि॥', 'rākṣasā vidhinā vāco visṛjanti mahāvane
hiṃsāvihārā vaidehi na cintayitum arhasi', null, 3043018),
('ramayana-3-43-19', 19, 'Aranya Kanda, Sarga 43, Verse 19', 'लक्ष्मणेनैवमुक्ता तु क्रुद्धा संरक्तलोचना।
अब्रवीत्परुषं वाक्यं लक्ष्मणं सत्यवादिनम्॥', 'lakṣmaṇenaivam uktā tu kruddhā saṃraktalocanā
abravīt paruṣaṃ vākyaṃ lakṣmaṇaṃ satyavādinam', null, 3043019),
('ramayana-3-43-20', 20, 'Aranya Kanda, Sarga 43, Verse 20', 'अनार्य करुणारम्भ नृशंस कुलपांसन।
अहं तव प्रियं मन्ये तेनैतानि प्रभाषसे॥', 'anārya karuṇārambha nṛśaṃsa kulapāṃsana
ahaṃ tava priyaṃ manye tenaitāni prabhāṣase', null, 3043020),
('ramayana-3-43-21', 21, 'Aranya Kanda, Sarga 43, Verse 21', 'नैतच्चित्रं सपत्नेषु पापं लक्ष्मण यद्भवेत्।
त्वद्विधेषु नृशंसेषु नित्यं प्रच्छन्नचारिषु॥', 'naitac citraṃ sapatneṣu pāpaṃ lakṣmaṇa yad bhavet
tvadvidheṣu nṛśaṃseṣu nityaṃ pracchannacāriṣu', null, 3043021),
('ramayana-3-43-22', 22, 'Aranya Kanda, Sarga 43, Verse 22', 'सुदुष्टस्त्वं वने राममेकमेकोऽनुगच्छसि।
मम हेतोः प्रतिच्छन्नः प्रयुक्तो भरतेन वा॥', 'suduṣṭas tvaṃ vane rāmam ekam eko ''nugacchasi
mama hetoḥ praticchannaḥ prayukto bharatena vā', null, 3043022),
('ramayana-3-43-23', 23, 'Aranya Kanda, Sarga 43, Verse 23', 'कथमिन्दीवरश्यामं रामं पद्मनिभेक्षणम्।
उपसंश्रित्य भर्तारं कामयेयं पृथग्जनम्॥', 'katham indīvaraśyāmaṃ rāmaṃ padmanibhekṣaṇam
upasaṃśritya bhartāraṃ kāmayeyaṃ pṛthag janam', null, 3043023),
('ramayana-3-43-24', 24, 'Aranya Kanda, Sarga 43, Verse 24', 'समक्षं तव सौमित्रे प्राणांस्त्यक्ष्ये न संशयः।
रामं विना क्षणमपि न हि जीवामि भूतले॥', 'samakṣaṃ tava saumitre prāṇāṃs tyakṣye na saṃśayaḥ
rāmaṃ vinā kṣaṇam api na hi jīvāmi bhūtale', null, 3043024),
('ramayana-3-43-25', 25, 'Aranya Kanda, Sarga 43, Verse 25', 'इत्युक्तः परुषं वाक्यं सीतया सोमहर्षणम्।
अब्रवील्लक्ष्मणः सीतां प्राञ्जलिर्विजितेन्द्रियः॥', 'ity uktaḥ paruṣaṃ vākyaṃ sītayā somaharṣaṇam
abravīl lakṣmaṇaḥ sītāṃ prāñjalir vijitendriyaḥ', null, 3043025),
('ramayana-3-43-26', 26, 'Aranya Kanda, Sarga 43, Verse 26', 'उत्तरं नोत्सहे वक्तुं दैवतं भवती मम।
वाक्यमप्रतिरूपं तु न चित्रं स्त्रीषु मैथिलि॥', 'uttaraṃ notsahe vaktuṃ daivataṃ bhavatī mama
vākyam apratirūpaṃ tu na citraṃ strīṣu maithili', null, 3043026),
('ramayana-3-43-27', 27, 'Aranya Kanda, Sarga 43, Verse 27', 'स्वभावस्त्वेष नारीणामेषु लोकेषु दृश्यते।
विमुक्तधर्माश्चपलास्तीक्ष्णा भेदकराः स्त्रियः॥', 'svabhāvas tv eṣa nārīṇām eṣu lokeṣu dṛśyate
vimuktadharmāś capalās tīkṣṇā bhedakarāḥ striyaḥ', null, 3043027),
('ramayana-3-43-28', 28, 'Aranya Kanda, Sarga 43, Verse 28', 'उपशृण्वन्तु मे सर्वे साक्षिभूता वनेचराः।
न्यायवादी यथा वाक्यमुक्तोऽहं परुषं त्वया॥', 'upaśṛṇvantu me sarve sākṣibhūtā vanecarāḥ
nyāyavādī yathā vākyam ukto ''haṃ paruṣaṃ tvayā', null, 3043028),
('ramayana-3-43-29', 29, 'Aranya Kanda, Sarga 43, Verse 29', 'धिक्त्वामद्य प्रणश्य त्वं यन्मामेवं विशङ्कसे।
स्त्रीत्वाद्दुष्टस्वभावेन गुरुवाक्ये व्यवस्थितम्॥', 'dhik tvām adya praṇaśya tvaṃ yan mām evaṃ viśaṅkase
strītvād duṣṭasvabhāvena guruvākye vyavasthitam', null, 3043029),
('ramayana-3-43-30', 30, 'Aranya Kanda, Sarga 43, Verse 30', 'गमिष्ये यत्र काकुत्स्थः स्वस्ति तेऽस्तु वरानने।
रक्षन्तु त्वां विशालाक्षि समग्रा वनदेवताः॥', 'gamiṣye yatra kākutsthaḥ svasti te ''stu varānane
rakṣantu tvāṃ viśālākṣi samagrā vanadevatāḥ', null, 3043030),
('ramayana-3-43-31', 31, 'Aranya Kanda, Sarga 43, Verse 31', 'निमित्तानि हि घोराणि यानि प्रादुर्भवन्ति मे।
अपि त्वां सह रामेण पश्येयं पुनरागतः॥', 'nimittāni hi ghorāṇi yāni prādurbhavanti me
api tvāṃ saha rāmeṇa paśyeyaṃ punar āgataḥ', null, 3043031),
('ramayana-3-43-32', 32, 'Aranya Kanda, Sarga 43, Verse 32', 'लक्ष्मणेनैवमुक्ता तु रुदती जनकात्मजा।
प्रत्युवाच ततो वाक्यं तीव्रं बाष्पपरिप्लुता॥', 'lakṣmaṇenaivam uktā tu rudatī janakātmajā
pratyuvāca tato vākyaṃ tīvraṃ bāṣpapariplutā', null, 3043032),
('ramayana-3-43-33', 33, 'Aranya Kanda, Sarga 43, Verse 33', 'गोदावरीं प्रवेक्ष्यामि विना रामेण लक्ष्मण।
आबन्धिष्येऽथ वा त्यक्ष्ये विषमे देहमात्मनः॥', 'godāvarīṃ pravekṣyāmi vinā rāmeṇa lakṣmaṇa
ābandhiṣye ''tha vā tyakṣye viṣame deham ātmanaḥ', null, 3043033),
('ramayana-3-43-34', 34, 'Aranya Kanda, Sarga 43, Verse 34', 'पिबामि वा विषं तीक्ष्णं प्रवेक्ष्यामि हुताशनम्।
न त्वहं राघवादन्यं पदापि पुरुषं स्पृशे॥', 'pibāmi vā viṣaṃ tīkṣṇaṃ pravekṣyāmi hutāśanam
na tv ahaṃ rāghavād anyaṃ padāpi puruṣaṃ spṛśe', null, 3043034),
('ramayana-3-43-35', 35, 'Aranya Kanda, Sarga 43, Verse 35', 'इति लक्ष्मणमाक्रुश्य सीता दुःखसमन्विता।
पाणिभ्यां रुदती दुःखादुदरं प्रजघान ह॥', 'iti lakṣmaṇam ākruśya sītā duḥkhasamanvitā
pāṇibhyāṃ rudatī duḥkhād udaraṃ prajaghāna ha', null, 3043035),
('ramayana-3-43-36', 36, 'Aranya Kanda, Sarga 43, Verse 36', 'तामार्तरूपां विमना रुदन्तीं सौमित्रिरालोक्य विशालनेत्राम्।
आश्वासयामास न चैव भर्तुस्तं भ्रातरं किं चिदुवाच सीता॥', 'tām ārtarūpāṃ vimanā rudantīṃ saumitrir ālokya viśālanetrām
āśvāsayām āsa na caiva bhartus taṃ bhrātaraṃ kiṃ cid uvāca sītā', null, 3043036),
('ramayana-3-43-37', 37, 'Aranya Kanda, Sarga 43, Verse 37', 'ततस्तु सीतामभिवाद्य लक्ष्मणः कृताञ्जलिः किं चिदभिप्रणम्य।
अवेक्षमाणो बहुशश्च मैथिलीं जगाम रामस्य समीपमात्मवान्॥', 'tatas tu sītām abhivādya lakṣmaṇaḥ kṛtāñjaliḥ kiṃ cid abhipraṇamya
avekṣamāṇo bahuśaś ca maithilīṃ jagāma rāmasya samīpam ātmavān', null, 3043037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 44 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-44-1', 1, 'Aranya Kanda, Sarga 44, Verse 1', 'तया परुषमुक्तस्तु कुपितो राघवानुजः।
स विकाङ्क्षन्भृशं रामं प्रतस्थे नचिरादिव॥', 'tayā paruṣam uktas tu kupito rāghavānujaḥ
sa vikāṅkṣan bhṛśaṃ rāmaṃ pratasthe nacirād iva', null, 3044001),
('ramayana-3-44-2', 2, 'Aranya Kanda, Sarga 44, Verse 2', 'तदासाद्य दशग्रीवः क्षिप्रमन्तरमास्थितः।
अभिचक्राम वैदेहीं परिव्राजकरूपधृक्॥', 'tadāsādya daśagrīvaḥ kṣipram antaram āsthitaḥ
abhicakrāma vaidehīṃ parivrājakarūpadhṛk', null, 3044002),
('ramayana-3-44-3', 3, 'Aranya Kanda, Sarga 44, Verse 3', 'श्लक्ष्णकाषायसंवीतः शिखी छत्री उपानही।
वामे चांसेऽवसज्याथ शुभे यष्टिकमण्डलू।
परिव्राजकरूपेण वैदेहीं समुपागमत्॥', 'ślakṣṇakāṣāyasaṃvītaḥ śikhī chatrī upānahī
vāme cāṃse ''vasajyātha śubhe yaṣṭikamaṇḍalū
parivrājakarūpeṇa vaidehīṃ samupāgamat', null, 3044003),
('ramayana-3-44-4', 4, 'Aranya Kanda, Sarga 44, Verse 4', 'तामाससादातिबलो भ्रातृभ्यां रहितां वने।
रहितां सूर्यचन्द्राभ्यां संध्यामिव महत्तमः॥', 'tām āsasādātibalo bhrātṛbhyāṃ rahitāṃ vane
rahitāṃ sūryacandrābhyāṃ saṃdhyām iva mahattamaḥ', null, 3044004),
('ramayana-3-44-5', 5, 'Aranya Kanda, Sarga 44, Verse 5', 'तामपश्यत्ततो बालां राजपुत्रीं यशस्विनीम्।
रोहिणीं शशिना हीनां ग्रहवद्भृशदारुणः॥', 'tām apaśyat tato bālāṃ rājaputrīṃ yaśasvinīm
rohiṇīṃ śaśinā hīnāṃ grahavad bhṛśadāruṇaḥ', null, 3044005),
('ramayana-3-44-6', 6, 'Aranya Kanda, Sarga 44, Verse 6', 'तमुग्रं पापकर्माणं जनस्थानरुहा द्रुमाः।
समीक्ष्य न प्रकम्पन्ते न प्रवाति च मारुतः॥', 'tam ugraṃ pāpakarmāṇaṃ janasthānaruhā drumāḥ
samīkṣya na prakampante na pravāti ca mārutaḥ', null, 3044006),
('ramayana-3-44-7', 7, 'Aranya Kanda, Sarga 44, Verse 7', 'शीघ्रस्रोताश्च तं दृष्ट्वा वीक्षन्तं रक्तलोचनम्।
स्तिमितं गन्तुमारेभे भयाद्गोदावरी नदी॥', 'śīghrasrotāś ca taṃ dṛṣṭvā vīkṣantaṃ raktalocanam
stimitaṃ gantum ārebhe bhayād godāvarī nadī', null, 3044007),
('ramayana-3-44-8', 8, 'Aranya Kanda, Sarga 44, Verse 8', 'रामस्य त्वन्तरं प्रेप्सुर्दशग्रीवस्तदन्तरे।
उपतस्थे च वैदेहीं भिक्षुरूपेण रावणः॥', 'rāmasya tv antaraṃ prepsur daśagrīvas tadantare
upatasthe ca vaidehīṃ bhikṣurūpeṇa rāvaṇaḥ', null, 3044008),
('ramayana-3-44-9', 9, 'Aranya Kanda, Sarga 44, Verse 9', 'अभव्यो भव्यरूपेण भर्तारमनुशोचतीम्।
अभ्यवर्तत वैदेहीं चित्रामिव शनैश्चरः॥', 'abhavyo bhavyarūpeṇa bhartāram anuśocatīm
abhyavartata vaidehīṃ citrām iva śanaiścaraḥ', null, 3044009),
('ramayana-3-44-10', 10, 'Aranya Kanda, Sarga 44, Verse 10', 'स पापो भव्यरूपेण तृणैः कूप इवावृतः।
अतिष्ठत्प्रेक्ष्य वैदेहीं रामपत्नीं यशस्विनीम्॥', 'sa pāpo bhavyarūpeṇa tṛṇaiḥ kūpa ivāvṛtaḥ
atiṣṭhat prekṣya vaidehīṃ rāmapatnīṃ yaśasvinīm', null, 3044010),
('ramayana-3-44-11', 11, 'Aranya Kanda, Sarga 44, Verse 11', 'शुभां रुचिरदन्तौष्ठीं पूर्णचन्द्रनिभाननाम्।
आसीनां पर्णशालायां बाष्पशोकाभिपीडिताम्॥', 'śubhāṃ ruciradantauṣṭhīṃ pūrṇacandranibhānanām
āsīnāṃ parṇaśālāyāṃ bāṣpaśokābhipīḍitām', null, 3044011),
('ramayana-3-44-12', 12, 'Aranya Kanda, Sarga 44, Verse 12', 'स तां पद्मपलाशाक्षीं पीतकौशेयवासिनीम्।
अभ्यगच्छत वैदेहीं दुष्टचेता निशाचरः॥', 'sa tāṃ padmapalāśākṣīṃ pītakauśeyavāsinīm
abhyagacchata vaidehīṃ duṣṭacetā niśācaraḥ', null, 3044012),
('ramayana-3-44-13', 13, 'Aranya Kanda, Sarga 44, Verse 13', 'स मन्मथशराविष्टो ब्रह्मघोषमुदीरयन्।
अब्रवीत्प्रश्रितं वाक्यं रहिते राक्षसाधिपः॥', 'sa manmathaśarāviṣṭo brahmaghoṣam udīrayan
abravīt praśritaṃ vākyaṃ rahite rākṣasādhipaḥ', null, 3044013),
('ramayana-3-44-14', 14, 'Aranya Kanda, Sarga 44, Verse 14', 'तामुत्तमां त्रिलोकानां पद्महीनामिव श्रियम्।
विभ्राजमानां वपुषा रावणः प्रशशंस ह॥', 'tām uttamāṃ trilokānāṃ padmahīnām iva śriyam
vibhrājamānāṃ vapuṣā rāvaṇaḥ praśaśaṃsa ha', null, 3044014),
('ramayana-3-44-15', 15, 'Aranya Kanda, Sarga 44, Verse 15', 'का त्वं काञ्चनवर्णाभे पीतकौशेयवासिनि।
कमलानां शुभां मालां पद्मिनीव च बिभ्रती॥', 'kā tvaṃ kāñcanavarṇābhe pītakauśeyavāsini
kamalānāṃ śubhāṃ mālāṃ padminīva ca bibhratī', null, 3044015),
('ramayana-3-44-16', 16, 'Aranya Kanda, Sarga 44, Verse 16', 'ह्रीः श्रीः कीर्तिः शुभा लक्ष्मीरप्सरा वा शुभानने।
भूतिर्वा त्वं वरारोहे रतिर्वा स्वैरचारिणी॥', 'hrīḥ śrīḥ kīrtiḥ śubhā lakṣmīr apsarā vā śubhānane
bhūtir vā tvaṃ varārohe ratir vā svairacāriṇī', null, 3044016),
('ramayana-3-44-17', 17, 'Aranya Kanda, Sarga 44, Verse 17', 'समाः शिखरिणः स्निग्धाः पाण्डुरा दशनास्तव।
विशाले विमले नेत्रे रक्तान्ते कृष्णतारके॥', 'samāḥ śikhariṇaḥ snigdhāḥ pāṇḍurā daśanās tava
viśāle vimale netre raktānte kṛṣṇatārake', null, 3044017),
('ramayana-3-44-18', 18, 'Aranya Kanda, Sarga 44, Verse 18', 'विशालं जघनं पीनमूरू करिकरोपमौ।
एतावुपचितौ वृत्तौ सहितौ संप्रगल्भितौ॥', 'viśālaṃ jaghanaṃ pīnam ūrū karikaropamau
etāv upacitau vṛttau sahitau saṃpragalbhitau', null, 3044018),
('ramayana-3-44-19', 19, 'Aranya Kanda, Sarga 44, Verse 19', 'पीनोन्नतमुखौ कान्तौ स्निग्धतालफलोपमौ।
मणिप्रवेकाभरणौ रुचिरौ ते पयोधरौ॥', 'pīnonnatamukhau kāntau snigdhatālaphalopamau
maṇipravekābharaṇau rucirau te payodharau', null, 3044019),
('ramayana-3-44-20', 20, 'Aranya Kanda, Sarga 44, Verse 20', 'चारुस्मिते चारुदति चारुनेत्रे विलासिनि।
मनो हरसि मे रामे नदीकूलमिवाम्भसा॥', 'cārusmite cārudati cārunetre vilāsini
mano harasi me rāme nadīkūlam ivāmbhasā', null, 3044020),
('ramayana-3-44-21', 21, 'Aranya Kanda, Sarga 44, Verse 21', 'करान्तमितमध्यासि सुकेशी संहतस्तनी।
नैव देवी न गन्धर्वी न यक्षी न च किंनरी॥', 'karāntamitamadhyāsi sukeśī saṃhatastanī
naiva devī na gandharvī na yakṣī na ca kiṃnarī', null, 3044021),
('ramayana-3-44-22', 22, 'Aranya Kanda, Sarga 44, Verse 22', 'नैवंरूपा मया नारी दृष्टपूर्वा महीतले।
इह वासश्च कान्तारे चित्तमुन्माथयन्ति मे॥', 'naivaṃrūpā mayā nārī dṛṣṭapūrvā mahītale
iha vāsaś ca kāntāre cittam unmāthayanti me', null, 3044022),
('ramayana-3-44-23', 23, 'Aranya Kanda, Sarga 44, Verse 23', 'सा प्रतिक्राम भद्रं ते न त्वं वस्तुमिहार्हसि।
राक्षसानामयं वासो घोराणां कामरूपिणाम्॥', 'sā pratikrāma bhadraṃ te na tvaṃ vastum ihārhasi
rākṣasānām ayaṃ vāso ghorāṇāṃ kāmarūpiṇām', null, 3044023),
('ramayana-3-44-24', 24, 'Aranya Kanda, Sarga 44, Verse 24', 'प्रासादाग्र्याणि रम्याणि नगरोपवनानि च।
संपन्नानि सुगन्धीनि युक्तान्याचरितुं त्वया॥', 'prāsādāgryāṇi ramyāṇi nagaropavanāni ca
saṃpannāni sugandhīni yuktāny ācarituṃ tvayā', null, 3044024),
('ramayana-3-44-25', 25, 'Aranya Kanda, Sarga 44, Verse 25', 'वरं माल्यं वरं पानं वरं वस्त्रं च शोभने।
भर्तारं च वरं मन्ये त्वद्युक्तमसितेक्षणे॥', 'varaṃ mālyaṃ varaṃ pānaṃ varaṃ vastraṃ ca śobhane
bhartāraṃ ca varaṃ manye tvadyuktam asitekṣaṇe', null, 3044025),
('ramayana-3-44-26', 26, 'Aranya Kanda, Sarga 44, Verse 26', 'का त्वं भवसि रुद्राणां मरुतां वा शुचिस्मिते।
वसूनां वा वरारोहे देवता प्रतिभासि मे॥', 'kā tvaṃ bhavasi rudrāṇāṃ marutāṃ vā śucismite
vasūnāṃ vā varārohe devatā pratibhāsi me', null, 3044026),
('ramayana-3-44-27', 27, 'Aranya Kanda, Sarga 44, Verse 27', 'नेह गच्छन्ती गन्धर्वा न देवा न च किंनराः।
राक्षसानामयं वासः कथं नु त्वमिहागता॥', 'neha gacchantī gandharvā na devā na ca kiṃnarāḥ
rākṣasānām ayaṃ vāsaḥ kathaṃ nu tvam ihāgatā', null, 3044027),
('ramayana-3-44-28', 28, 'Aranya Kanda, Sarga 44, Verse 28', 'इह शाखामृगाः सिंहा द्वीपिव्याघ्रमृगास्तथा।
ऋक्षास्तरक्षवः कङ्काः कथं तेभ्यो न बिभ्यसे॥', 'iha śākhāmṛgāḥ siṃhā dvīpivyāghramṛgās tathā
ṛkṣās tarakṣavaḥ kaṅkāḥ kathaṃ tebhyo na bibhyase', null, 3044028),
('ramayana-3-44-29', 29, 'Aranya Kanda, Sarga 44, Verse 29', 'मदान्वितानां घोराणां कुञ्जराणां तरस्विनाम्।
कथमेका महारण्ये न बिभेषि वनानने॥', 'madānvitānāṃ ghorāṇāṃ kuñjarāṇāṃ tarasvinām
katham ekā mahāraṇye na bibheṣi vanānane', null, 3044029),
('ramayana-3-44-30', 30, 'Aranya Kanda, Sarga 44, Verse 30', 'कासि कस्य कुतश्च त्वं किंनिमित्तं च दण्डकान्।
एका चरसि कल्याणि घोरान्राक्षससेवितान्॥', 'kāsi kasya kutaś ca tvaṃ kiṃnimittaṃ ca daṇḍakān
ekā carasi kalyāṇi ghorān rākṣasasevitān', null, 3044030),
('ramayana-3-44-31', 31, 'Aranya Kanda, Sarga 44, Verse 31', 'इति प्रशस्ता वैदेही रावणेन दुरात्मना।
द्विजातिवेषेण हि तं दृष्ट्वा रावणमागतम्।
सर्वैरतिथिसत्कारैः पूजयामास मैथिली॥', 'iti praśastā vaidehī rāvaṇena durātmanā
dvijātiveṣeṇa hi taṃ dṛṣṭvā rāvaṇam āgatam
sarvair atithisatkāraiḥ pūjayām āsa maithilī', null, 3044031),
('ramayana-3-44-32', 32, 'Aranya Kanda, Sarga 44, Verse 32', 'उपानीयासनं पूर्वं पाद्येनाभिनिमन्त्र्य च।
अब्रवीत्सिद्धमित्येव तदा तं सौम्यदर्शनम्॥', 'upānīyāsanaṃ pūrvaṃ pādyenābhinimantrya ca
abravīt siddham ity eva tadā taṃ saumyadarśanam', null, 3044032),
('ramayana-3-44-33', 33, 'Aranya Kanda, Sarga 44, Verse 33', 'द्विजातिवेषेण समीक्ष्य मैथिली तमागतं पात्रकुसुम्भधारिणम्।
अशक्यमुद्द्वेष्टुमुपायदर्शनान्न्यमन्त्रयद्ब्राह्मणवद्यथागतम्॥', 'dvijātiveṣeṇa samīkṣya maithilī tam āgataṃ pātrakusumbhadhāriṇam
aśakyam uddveṣṭum upāyadarśanān nyamantrayad brāhmaṇavad yathāgatam', null, 3044033),
('ramayana-3-44-34', 34, 'Aranya Kanda, Sarga 44, Verse 34', 'इयं बृसी ब्राह्मण काममास्यतामिदं च पाद्यं प्रतिगृह्यतामिति।
इदं च सिद्धं वनजातमुत्तमं त्वदर्थमव्यग्रमिहोपभुज्यताम्॥', 'iyaṃ bṛsī brāhmaṇa kāmam āsyatām idaṃ ca pādyaṃ pratigṛhyatām iti
idaṃ ca siddhaṃ vanajātam uttamaṃ tvadartham avyagram ihopabhujyatām', null, 3044034),
('ramayana-3-44-35', 35, 'Aranya Kanda, Sarga 44, Verse 35', 'निमन्त्र्यमाणः प्रतिपूर्णभाषिणीं नरेन्द्रपत्नीं प्रसमीक्ष्य मैथिलीम्।
प्रहस्य तस्या हरणे धृतं मनः समर्पयामास वधाय रावणः॥', 'nimantryamāṇaḥ pratipūrṇabhāṣiṇīṃ narendrapatnīṃ prasamīkṣya maithilīm
prahasya tasyā haraṇe dhṛtaṃ manaḥ samarpayām āsa vadhāya rāvaṇaḥ', null, 3044035),
('ramayana-3-44-36', 36, 'Aranya Kanda, Sarga 44, Verse 36', 'ततः सुवेषं मृगया गतं पतिं प्रतीक्षमाणा सहलक्ष्मणं तदा।
निरीक्षमाणा हरितं ददर्श तन्महद्वनं नैव तु रामलक्ष्मणौ॥', 'tataḥ suveṣaṃ mṛgayā gataṃ patiṃ pratīkṣamāṇā sahalakṣmaṇaṃ tadā
nirīkṣamāṇā haritaṃ dadarśa tan mahad vanaṃ naiva tu rāmalakṣmaṇau', null, 3044036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 45 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-45-1', 1, 'Aranya Kanda, Sarga 45, Verse 1', 'रावणेन तु वैदेही तदा पृष्टा जिहीर्षुणा।
परिव्राजकरूपेण शशंसात्मानमात्मना॥', 'rāvaṇena tu vaidehī tadā pṛṣṭā jihīrṣuṇā
parivrājakarūpeṇa śaśaṃsātmānam ātmanā', null, 3045001),
('ramayana-3-45-2', 2, 'Aranya Kanda, Sarga 45, Verse 2', 'ब्राह्मणश्चातिथिश्चैष अनुक्तो हि शपेत माम्।
इति ध्यात्वा मुहूर्तं तु सीता वचनमब्रवीत्॥', 'brāhmaṇaś cātithiś caiṣa anukto hi śapeta mām
iti dhyātvā muhūrtaṃ tu sītā vacanam abravīt', null, 3045002),
('ramayana-3-45-3', 3, 'Aranya Kanda, Sarga 45, Verse 3', 'दुहिता जनकस्याहं मैथिलस्य महात्मनः।
सीता नाम्नास्मि भद्रं ते रामभार्या द्विजोत्तम॥', 'duhitā janakasyāhaṃ maithilasya mahātmanaḥ
sītā nāmnāsmi bhadraṃ te rāmabhāryā dvijottama', null, 3045003),
('ramayana-3-45-4', 4, 'Aranya Kanda, Sarga 45, Verse 4', 'संवत्सरं चाध्युषिता राघवस्य निवेशने।
भुञ्जाना मानुषान्भोगान्सर्वकामसमृद्धिनी॥', 'saṃvatsaraṃ cādhyuṣitā rāghavasya niveśane
bhuñjānā mānuṣān bhogān sarvakāmasamṛddhinī', null, 3045004),
('ramayana-3-45-5', 5, 'Aranya Kanda, Sarga 45, Verse 5', 'ततः संवत्सरादूर्ध्वं सममन्यत मे पतिम्।
अभिषेचयितुं रामं समेतो राजमन्त्रिभिः॥', 'tataḥ saṃvatsarād ūrdhvaṃ samamanyata me patim
abhiṣecayituṃ rāmaṃ sameto rājamantribhiḥ', null, 3045005),
('ramayana-3-45-6', 6, 'Aranya Kanda, Sarga 45, Verse 6', 'तस्मिन्संभ्रियमाणे तु राघवस्याभिषेचने।
कैकेयी नाम भर्तारं ममार्या याचते वरम्॥', 'tasmin saṃbhriyamāṇe tu rāghavasyābhiṣecane
kaikeyī nāma bhartāraṃ mamāryā yācate varam', null, 3045006),
('ramayana-3-45-7', 7, 'Aranya Kanda, Sarga 45, Verse 7', 'प्रतिगृह्य तु कैकेयी श्वशुरं सुकृतेन मे।
मम प्रव्राजनं भर्तुर्भरतस्याभिषेचनम्।
द्वावयाचत भर्तारं सत्यसंधं नृपोत्तमम्॥', 'pratigṛhya tu kaikeyī śvaśuraṃ sukṛtena me
mama pravrājanaṃ bhartur bharatasyābhiṣecanam
dvāv ayācata bhartāraṃ satyasaṃdhaṃ nṛpottamam', null, 3045007),
('ramayana-3-45-8', 8, 'Aranya Kanda, Sarga 45, Verse 8', 'नाद्य भोक्ष्ये न च स्वप्स्ये न पास्येऽहं कदा चन।
एष मे जीवितस्यान्तो रामो यद्यभिषिच्यते॥', 'nādya bhokṣye na ca svapsye na pāsye ''haṃ kadā cana
eṣa me jīvitasyānto rāmo yady abhiṣicyate', null, 3045008),
('ramayana-3-45-9', 9, 'Aranya Kanda, Sarga 45, Verse 9', 'इति ब्रुवाणां कैकेयीं श्वशुरो मे स मानदः।
अयाचतार्थैरन्वर्थैर्न च याच्ञां चकार सा॥', 'iti bruvāṇāṃ kaikeyīṃ śvaśuro me sa mānadaḥ
ayācatārthair anvarthair na ca yācñāṃ cakāra sā', null, 3045009),
('ramayana-3-45-10', 10, 'Aranya Kanda, Sarga 45, Verse 10', 'मम भर्ता महातेजा वयसा पञ्चविंशकः।
रामेति प्रथितो लोके गुणवान्सत्यवाक्शुचिः।
विशालाक्षो महाबाहुः सर्वभूतहिते रतः॥', 'mama bhartā mahātejā vayasā pañcaviṃśakaḥ
rāmeti prathito loke guṇavān satyavāk śuciḥ
viśālākṣo mahābāhuḥ sarvabhūtahite rataḥ', null, 3045010),
('ramayana-3-45-11', 11, 'Aranya Kanda, Sarga 45, Verse 11', 'अभिषेकाय तु पितुः समीपं राममागतम्।
कैकेयी मम भर्तारमित्युवाच द्रुतं वचः॥', 'abhiṣekāya tu pituḥ samīpaṃ rāmam āgatam
kaikeyī mama bhartāram ity uvāca drutaṃ vacaḥ', null, 3045011),
('ramayana-3-45-12', 12, 'Aranya Kanda, Sarga 45, Verse 12', 'तव पित्रा समाज्ञप्तं ममेदं शृणु राघव।
भरताय प्रदातव्यमिदं राज्यमकण्टकम्॥', 'tava pitrā samājñaptaṃ mamedaṃ śṛṇu rāghava
bharatāya pradātavyam idaṃ rājyam akaṇṭakam', null, 3045012),
('ramayana-3-45-13', 13, 'Aranya Kanda, Sarga 45, Verse 13', 'त्वया तु खलु वस्तव्यं नव वर्षाणि पञ्च च।
वने प्रव्रज काकुत्स्थ पितरं मोचयानृतात्॥', 'tvayā tu khalu vastavyaṃ nava varṣāṇi pañca ca
vane pravraja kākutstha pitaraṃ mocayānṛtāt', null, 3045013),
('ramayana-3-45-14', 14, 'Aranya Kanda, Sarga 45, Verse 14', 'तथेत्युवाच तां रामः कैकेयीमकुतोभयः।
चकार तद्वचस्तस्या मम भर्ता दृढव्रतः॥', 'tathety uvāca tāṃ rāmaḥ kaikeyīm akutobhayaḥ
cakāra tad vacas tasyā mama bhartā dṛḍhavrataḥ', null, 3045014),
('ramayana-3-45-15', 15, 'Aranya Kanda, Sarga 45, Verse 15', 'दद्यान्न प्रतिगृह्णीयात्सत्यब्रूयान्न चानृतम्।
एतद्ब्राह्मण रामस्य व्रतं ध्रुवमनुत्तमम्॥', 'dadyān na pratigṛhṇīyāt satyabrūyān na cānṛtam
etad brāhmaṇa rāmasya vrataṃ dhruvam anuttamam', null, 3045015),
('ramayana-3-45-16', 16, 'Aranya Kanda, Sarga 45, Verse 16', 'तस्य भ्राता तु वैमात्रो लक्ष्मणो नाम वीर्यवान्।
रामस्य पुरुषव्याघ्रः सहायः समरेऽरिहा॥', 'tasya bhrātā tu vaimātro lakṣmaṇo nāma vīryavān
rāmasya puruṣavyāghraḥ sahāyaḥ samare ''rihā', null, 3045016),
('ramayana-3-45-17', 17, 'Aranya Kanda, Sarga 45, Verse 17', 'स भ्राता लक्ष्मणो नाम धर्मचारी दृढव्रतः।
अन्वगच्छद्धनुष्पाणिः प्रव्रजन्तं मया सह॥', 'sa bhrātā lakṣmaṇo nāma dharmacārī dṛḍhavrataḥ
anvagacchad dhanuṣpāṇiḥ pravrajantaṃ mayā saha', null, 3045017),
('ramayana-3-45-18', 18, 'Aranya Kanda, Sarga 45, Verse 18', 'ते वयं प्रच्युता राज्यात्कैलेय्यास्तु कृते त्रयः।
विचराम द्विजश्रेष्ठ वनं गम्भीरमोजसा॥', 'te vayaṃ pracyutā rājyāt kaileyyās tu kṛte trayaḥ
vicarāma dvijaśreṣṭha vanaṃ gambhīram ojasā', null, 3045018),
('ramayana-3-45-19', 19, 'Aranya Kanda, Sarga 45, Verse 19', 'समाश्वस मुहूर्तं तु शक्यं वस्तुमिह त्वया।
आगमिष्यति मे भर्ता वन्यमादाय पुष्कलम्॥', 'samāśvasa muhūrtaṃ tu śakyaṃ vastum iha tvayā
āgamiṣyati me bhartā vanyam ādāya puṣkalam', null, 3045019),
('ramayana-3-45-20', 20, 'Aranya Kanda, Sarga 45, Verse 20', 'स त्वं नाम च गोत्रं च कुलमाचक्ष्व तत्त्वतः।
एकश्च दण्डकारण्ये किमर्थं चरसि द्विज॥', 'sa tvaṃ nāma ca gotraṃ ca kulam ācakṣva tattvataḥ
ekaś ca daṇḍakāraṇye kimarthaṃ carasi dvija', null, 3045020),
('ramayana-3-45-21', 21, 'Aranya Kanda, Sarga 45, Verse 21', 'एवं ब्रुवत्यां सीतायां रामपत्न्यां महाबलः।
प्रत्युवाचोत्तरं तीव्रं रावणो राक्षसाधिपः॥', 'evaṃ bruvatyāṃ sītāyāṃ rāmapatnyāṃ mahābalaḥ
pratyuvācottaraṃ tīvraṃ rāvaṇo rākṣasādhipaḥ', null, 3045021),
('ramayana-3-45-22', 22, 'Aranya Kanda, Sarga 45, Verse 22', 'येन वित्रासिता लोकाः सदेवासुरपन्नगाः।
अहं स रावणो नाम सीते रक्षोगणेश्वरः॥', 'yena vitrāsitā lokāḥ sadevāsurapannagāḥ
ahaṃ sa rāvaṇo nāma sīte rakṣogaṇeśvaraḥ', null, 3045022),
('ramayana-3-45-23', 23, 'Aranya Kanda, Sarga 45, Verse 23', 'त्वां तु काञ्चनवर्णाभां दृष्ट्वा कौशेयवासिनीम्।
रतिं स्वकेषु दारेषु नाधिगच्छाम्यनिन्दिते॥', 'tvāṃ tu kāñcanavarṇābhāṃ dṛṣṭvā kauśeyavāsinīm
ratiṃ svakeṣu dāreṣu nādhigacchāmy anindite', null, 3045023),
('ramayana-3-45-24', 24, 'Aranya Kanda, Sarga 45, Verse 24', 'बह्वीनामुत्तमस्त्रीणामाहृतानामितस्ततः।
सर्वासामेव भद्रं ते ममाग्रमहिषी भव॥', 'bahvīnām uttamastrīṇām āhṛtānām itas tataḥ
sarvāsām eva bhadraṃ te mamāgramahiṣī bhava', null, 3045024),
('ramayana-3-45-25', 25, 'Aranya Kanda, Sarga 45, Verse 25', 'लङ्का नाम समुद्रस्य मध्ये मम महापुरी।
सागरेण परिक्षिप्ता निविष्टा गिरिमूर्धनि॥', 'laṅkā nāma samudrasya madhye mama mahāpurī
sāgareṇa parikṣiptā niviṣṭā girimūrdhani', null, 3045025),
('ramayana-3-45-26', 26, 'Aranya Kanda, Sarga 45, Verse 26', 'तत्र सीते मया सार्धं वनेषु विचरिष्यसि।
न चास्यारण्यवासस्य स्पृहयिष्यसि भामिनि॥', 'tatra sīte mayā sārdhaṃ vaneṣu vicariṣyasi
na cāsyāraṇyavāsasya spṛhayiṣyasi bhāmini', null, 3045026),
('ramayana-3-45-27', 27, 'Aranya Kanda, Sarga 45, Verse 27', 'पञ्चदास्यः सहस्राणि सर्वाभरणभूषिताः।
सीते परिचरिष्यन्ति भार्या भवसि मे यदि॥', 'pañcadāsyaḥ sahasrāṇi sarvābharaṇabhūṣitāḥ
sīte paricariṣyanti bhāryā bhavasi me yadi', null, 3045027),
('ramayana-3-45-28', 28, 'Aranya Kanda, Sarga 45, Verse 28', 'रावणेनैवमुक्ता तु कुपिता जनकात्मजा।
प्रत्युवाचानवद्याङ्गी तमनादृत्य राक्षसं॥', 'rāvaṇenaivam uktā tu kupitā janakātmajā
pratyuvācānavadyāṅgī tam anādṛtya rākṣasaṃ', null, 3045028),
('ramayana-3-45-29', 29, 'Aranya Kanda, Sarga 45, Verse 29', 'महागिरिमिवाकम्प्यं महेन्द्रसदृशं पतिम्।
महोदधिमिवाक्षोभ्यमहं राममनुव्रता॥', 'mahāgirim ivākampyaṃ mahendrasadṛśaṃ patim
mahodadhim ivākṣobhyam ahaṃ rāmam anuvratā', null, 3045029),
('ramayana-3-45-30', 30, 'Aranya Kanda, Sarga 45, Verse 30', 'महाबाहुं महोरस्कं सिंहविक्रान्तगामिनम्।
नृसिंहं सिंहसंकाशमहं राममनुव्रता॥', 'mahābāhuṃ mahoraskaṃ siṃhavikrāntagāminam
nṛsiṃhaṃ siṃhasaṃkāśam ahaṃ rāmam anuvratā', null, 3045030),
('ramayana-3-45-31', 31, 'Aranya Kanda, Sarga 45, Verse 31', 'पूर्णचन्द्राननं वीरं राजवत्सं जितेन्द्रियम्।
पृथुकीर्तिं महाबाहुमहं राममनुव्रता॥', 'pūrṇacandrānanaṃ vīraṃ rājavatsaṃ jitendriyam
pṛthukīrtiṃ mahābāhum ahaṃ rāmam anuvratā', null, 3045031),
('ramayana-3-45-32', 32, 'Aranya Kanda, Sarga 45, Verse 32', 'त्वं पुनर्जम्बुकः सिंहीं मामिहेच्छसि दुर्लभाम्।
नाहं शक्या त्वया स्प्रष्टुमादित्यस्य प्रभा यथा॥', 'tvaṃ punar jambukaḥ siṃhīṃ mām ihecchasi durlabhām
nāhaṃ śakyā tvayā spraṣṭum ādityasya prabhā yathā', null, 3045032),
('ramayana-3-45-33', 33, 'Aranya Kanda, Sarga 45, Verse 33', 'पादपान्काञ्चनान्नूनं बहून्पश्यसि मन्दभाक्।
राघवस्य प्रियां भार्यां यस्त्वमिच्छसि रावण॥', 'pādapān kāñcanān nūnaṃ bahūn paśyasi mandabhāk
rāghavasya priyāṃ bhāryāṃ yas tvam icchasi rāvaṇa', null, 3045033),
('ramayana-3-45-34', 34, 'Aranya Kanda, Sarga 45, Verse 34', 'क्षुधितस्य च सिंहस्य मृगशत्रोस्तरस्विनः।
आशीविषस्य वदनाद्दंष्ट्रामादातुमिच्छसि॥', 'kṣudhitasya ca siṃhasya mṛgaśatros tarasvinaḥ
āśīviṣasya vadanād daṃṣṭrām ādātum icchasi', null, 3045034),
('ramayana-3-45-35', 35, 'Aranya Kanda, Sarga 45, Verse 35', 'मन्दरं पर्वतश्रेष्ठं पाणिना हर्तुमिच्छसि।
कालकूटं विषं पीत्वा स्वस्तिमान्गन्तुमिच्छसि॥', 'mandaraṃ parvataśreṣṭhaṃ pāṇinā hartum icchasi
kālakūṭaṃ viṣaṃ pītvā svastimān gantum icchasi', null, 3045035),
('ramayana-3-45-36', 36, 'Aranya Kanda, Sarga 45, Verse 36', 'अक्षिसूच्या प्रमृजसि जिह्वया लेढि च क्षुरम्।
राघवस्य प्रियां भार्यामधिगन्तुं त्वमिच्छसि॥', 'akṣisūcyā pramṛjasi jihvayā leḍhi ca kṣuram
rāghavasya priyāṃ bhāryām adhigantuṃ tvam icchasi', null, 3045036),
('ramayana-3-45-37', 37, 'Aranya Kanda, Sarga 45, Verse 37', 'अवसज्य शिलां कण्ठे समुद्रं तर्तुमिच्छसि।
सूर्या चन्द्रमसौ चोभौ प्राणिभ्यां हर्तुमिच्छसि।
यो रामस्य प्रियां भार्यां प्रधर्षयितुमिच्छसि॥', 'avasajya śilāṃ kaṇṭhe samudraṃ tartum icchasi
sūryā candramasau cobhau prāṇibhyāṃ hartum icchasi
yo rāmasya priyāṃ bhāryāṃ pradharṣayitum icchasi', null, 3045037),
('ramayana-3-45-38', 38, 'Aranya Kanda, Sarga 45, Verse 38', 'अग्निं प्रज्वलितं दृष्ट्वा वस्त्रेणाहर्तुमिच्छसि।
कल्याण वृत्तां रामस्य यो भार्यां हर्तुमिच्छसि॥', 'agniṃ prajvalitaṃ dṛṣṭvā vastreṇāhartum icchasi
kalyāṇa vṛttāṃ rāmasya yo bhāryāṃ hartum icchasi', null, 3045038),
('ramayana-3-45-39', 39, 'Aranya Kanda, Sarga 45, Verse 39', 'अयोमुखानां शूलानामग्रे चरितुमिच्छसि।
रामस्य सदृशीं भार्यां योऽधिगन्तुं त्वमिच्छसि॥', 'ayomukhānāṃ śūlānām agre caritum icchasi
rāmasya sadṛśīṃ bhāryāṃ yo ''dhigantuṃ tvam icchasi', null, 3045039),
('ramayana-3-45-40', 40, 'Aranya Kanda, Sarga 45, Verse 40', 'यदन्तरं सिंहशृगालयोर्वने यदन्तरं स्यन्दनिकासमुद्रयोः।
सुराग्र्यसौवीरकयोर्यदन्तरं तदन्तरं दाशरथेस्तवैव च॥', 'yad antaraṃ siṃhaśṛgālayor vane yad antaraṃ syandanikāsamudrayoḥ
surāgryasauvīrakayor yad antaraṃ tad antaraṃ dāśarathes tavaiva ca', null, 3045040),
('ramayana-3-45-41', 41, 'Aranya Kanda, Sarga 45, Verse 41', 'यदन्तरं काञ्चनसीसलोहयोर्यदन्तरं चन्दनवारिपङ्कयोः।
यदन्तरं हस्तिबिडालयोर्वने तदन्तरं दशरथेस्तवैव च॥', 'yad antaraṃ kāñcanasīsalohayor yad antaraṃ candanavāripaṅkayoḥ
yad antaraṃ hastibiḍālayor vane tad antaraṃ daśarathes tavaiva ca', null, 3045041),
('ramayana-3-45-42', 42, 'Aranya Kanda, Sarga 45, Verse 42', 'यदन्तरं वायसवैनतेययोर्यदन्तरं मद्गुमयूरयोरपि।
यदन्तरं सारसगृध्रयोर्वने तदन्तरं दाशरथेस्तवैव च॥', 'yad antaraṃ vāyasavainateyayor yad antaraṃ madgumayūrayor api
yad antaraṃ sārasagṛdhrayor vane tad antaraṃ dāśarathes tavaiva ca', null, 3045042),
('ramayana-3-45-43', 43, 'Aranya Kanda, Sarga 45, Verse 43', 'तस्मिन्सहस्राक्षसमप्रभावे रामे स्थिते कार्मुकबाणपाणौ।
हृतापि तेऽहं न जरां गमिष्ये वज्रं यथा मक्षिकयावगीर्णम्॥', 'tasmin sahasrākṣasamaprabhāve rāme sthite kārmukabāṇapāṇau
hṛtāpi te ''haṃ na jarāṃ gamiṣye vajraṃ yathā makṣikayāvagīrṇam', null, 3045043),
('ramayana-3-45-44', 44, 'Aranya Kanda, Sarga 45, Verse 44', 'इतीव तद्वाक्यमदुष्टभावा सुदृष्टमुक्त्वा रजनीचरं तम्।
गात्रप्रकम्पाद्व्यथिता बभूव वातोद्धता सा कदलीव तन्वी॥', 'itīva tad vākyam aduṣṭabhāvā sudṛṣṭam uktvā rajanīcaraṃ tam
gātraprakampād vyathitā babhūva vātoddhatā sā kadalīva tanvī', null, 3045044),
('ramayana-3-45-45', 45, 'Aranya Kanda, Sarga 45, Verse 45', 'तां वेपमानामुपलक्ष्य सीतां स रावणो मृत्युसमप्रभावः।
कुलं बलं नाम च कर्म चात्मनः समाचचक्षे भयकारणार्थम्॥', 'tāṃ vepamānām upalakṣya sītāṃ sa rāvaṇo mṛtyusamaprabhāvaḥ
kulaṃ balaṃ nāma ca karma cātmanaḥ samācacakṣe bhayakāraṇārtham', null, 3045045)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 46 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-46-1', 1, 'Aranya Kanda, Sarga 46, Verse 1', 'एवं ब्रुवत्यां सीतायां संरब्धः परुषाक्षरम्।
ललाटे भ्रुकुटीं कृत्वा रावणः प्रत्युवाच ह॥', 'evaṃ bruvatyāṃ sītāyāṃ saṃrabdhaḥ paruṣākṣaram
lalāṭe bhrukuṭīṃ kṛtvā rāvaṇaḥ pratyuvāca ha', null, 3046001),
('ramayana-3-46-2', 2, 'Aranya Kanda, Sarga 46, Verse 2', 'भ्राता वैश्रवणस्याहं सापत्न्यो वरवर्णिनि।
रावणो नाम भद्रं ते दशग्रीवः प्रतापवान्॥', 'bhrātā vaiśravaṇasyāhaṃ sāpatnyo varavarṇini
rāvaṇo nāma bhadraṃ te daśagrīvaḥ pratāpavān', null, 3046002),
('ramayana-3-46-3', 3, 'Aranya Kanda, Sarga 46, Verse 3', 'यस्य देवाः सगन्धर्वाः पिशाचपतगोरगाः।
विद्रवन्ति भयाद्भीता मृत्योरिव सदा प्रजाः॥', 'yasya devāḥ sagandharvāḥ piśācapatagoragāḥ
vidravanti bhayād bhītā mṛtyor iva sadā prajāḥ', null, 3046003),
('ramayana-3-46-4', 4, 'Aranya Kanda, Sarga 46, Verse 4', 'येन वैश्रवणो भ्राता वैमात्रः कारणान्तरे।
द्वन्द्वमासादितः क्रोधाद्रणे विक्रम्य निर्जितः॥', 'yena vaiśravaṇo bhrātā vaimātraḥ kāraṇāntare
dvandvam āsāditaḥ krodhād raṇe vikramya nirjitaḥ', null, 3046004),
('ramayana-3-46-5', 5, 'Aranya Kanda, Sarga 46, Verse 5', 'मद्भयार्तः परित्यज्य स्वमधिष्ठानमृद्धिमत्।
कैलासं पर्वतश्रेष्ठमध्यास्ते नरवाहनः॥', 'madbhayārtaḥ parityajya svam adhiṣṭhānam ṛddhimat
kailāsaṃ parvataśreṣṭham adhyāste naravāhanaḥ', null, 3046005),
('ramayana-3-46-6', 6, 'Aranya Kanda, Sarga 46, Verse 6', 'यस्य तत्पुष्पकं नाम विमानं कामगं शुभम्।
वीर्यादावर्जितं भद्रे येन यामि विहायसं॥', 'yasya tat puṣpakaṃ nāma vimānaṃ kāmagaṃ śubham
vīryād āvarjitaṃ bhadre yena yāmi vihāyasaṃ', null, 3046006),
('ramayana-3-46-7', 7, 'Aranya Kanda, Sarga 46, Verse 7', 'मम संजातरोषस्य मुखं दृष्ट्वैव मैथिलि।
विद्रवन्ति परित्रस्ताः सुराः शक्रपुरोगमाः॥', 'mama saṃjātaroṣasya mukhaṃ dṛṣṭvaiva maithili
vidravanti paritrastāḥ surāḥ śakrapurogamāḥ', null, 3046007),
('ramayana-3-46-8', 8, 'Aranya Kanda, Sarga 46, Verse 8', 'यत्र तिष्ठाम्यहं तत्र मारुतो वाति शङ्कितः।
तीव्रांशुः शिशिरांशुश्च भयात्संपद्यते रविः॥', 'yatra tiṣṭhāmy ahaṃ tatra māruto vāti śaṅkitaḥ
tīvrāṃśuḥ śiśirāṃśuś ca bhayāt saṃpadyate raviḥ', null, 3046008),
('ramayana-3-46-9', 9, 'Aranya Kanda, Sarga 46, Verse 9', 'निष्कम्पपत्रास्तरवो नद्यश्च स्तिमितोदकाः।
भवन्ति यत्र यत्राहं तिष्ठामि च चरामि च॥', 'niṣkampapatrās taravo nadyaś ca stimitodakāḥ
bhavanti yatra yatrāhaṃ tiṣṭhāmi ca carāmi ca', null, 3046009),
('ramayana-3-46-10', 10, 'Aranya Kanda, Sarga 46, Verse 10', 'मम पारे समुद्रस्य लङ्का नाम पुरी शुभा।
संपूर्णा राक्षसैर्घोरैर्यथेन्द्रस्यामरावती॥', 'mama pāre samudrasya laṅkā nāma purī śubhā
saṃpūrṇā rākṣasair ghorair yathendrasyāmarāvatī', null, 3046010),
('ramayana-3-46-11', 11, 'Aranya Kanda, Sarga 46, Verse 11', 'प्राकारेण परिक्षिप्ता पाण्डुरेण विराजिता।
हेमकक्ष्या पुरी रम्या वैदूर्यमय तोरणा॥', 'prākāreṇa parikṣiptā pāṇḍureṇa virājitā
hemakakṣyā purī ramyā vaidūryamaya toraṇā', null, 3046011),
('ramayana-3-46-12', 12, 'Aranya Kanda, Sarga 46, Verse 12', 'हस्त्यश्वरथसंभाधा तूर्यनादविनादिता।
सर्वकामफलैर्वृक्षैः संकुलोद्यानशोभिता॥', 'hastyaśvarathasaṃbhādhā tūryanādavināditā
sarvakāmaphalair vṛkṣaiḥ saṃkulodyānaśobhitā', null, 3046012),
('ramayana-3-46-13', 13, 'Aranya Kanda, Sarga 46, Verse 13', 'तत्र त्वं वसती सीते राजपुत्रि मया सह।
न स्रमिष्यसि नारीणां मानुषीणां मनस्विनि॥', 'tatra tvaṃ vasatī sīte rājaputri mayā saha
na sramiṣyasi nārīṇāṃ mānuṣīṇāṃ manasvini', null, 3046013),
('ramayana-3-46-14', 14, 'Aranya Kanda, Sarga 46, Verse 14', 'भुञ्जाना मानुषान्भोगान्दिव्यांश्च वरवर्णिनि।
न स्मरिष्यसि रामस्य मानुषस्य गतायुषः॥', 'bhuñjānā mānuṣān bhogān divyāṃś ca varavarṇini
na smariṣyasi rāmasya mānuṣasya gatāyuṣaḥ', null, 3046014),
('ramayana-3-46-15', 15, 'Aranya Kanda, Sarga 46, Verse 15', 'स्थापयित्वा प्रियं पुत्रं राज्ञा दशरथेन यः।
मन्दवीर्यः सुतो ज्येष्ठस्ततः प्रस्थापितो वनम्॥', 'sthāpayitvā priyaṃ putraṃ rājñā daśarathena yaḥ
mandavīryaḥ suto jyeṣṭhas tataḥ prasthāpito vanam', null, 3046015),
('ramayana-3-46-16', 16, 'Aranya Kanda, Sarga 46, Verse 16', 'तेन किं भ्रष्टराज्येन रामेण गतचेतसा।
करिष्यसि विशालाक्षि तापसेन तपस्विना॥', 'tena kiṃ bhraṣṭarājyena rāmeṇa gatacetasā
kariṣyasi viśālākṣi tāpasena tapasvinā', null, 3046016),
('ramayana-3-46-17', 17, 'Aranya Kanda, Sarga 46, Verse 17', 'सर्वराक्षसभर्तारं कामात्स्वयमिहागतम्।
न मन्मथशराविष्टं प्रत्याख्यातुं त्वमर्हसि॥', 'sarvarākṣasabhartāraṃ kāmāt svayam ihāgatam
na manmathaśarāviṣṭaṃ pratyākhyātuṃ tvam arhasi', null, 3046017),
('ramayana-3-46-18', 18, 'Aranya Kanda, Sarga 46, Verse 18', 'प्रत्याख्याय हि मां भीरु परितापं गमिष्यसि।
चरणेनाभिहत्येव पुरूरवसमुर्वशी॥', 'pratyākhyāya hi māṃ bhīru paritāpaṃ gamiṣyasi
caraṇenābhihatyeva purūravasam urvaśī', null, 3046018),
('ramayana-3-46-19', 19, 'Aranya Kanda, Sarga 46, Verse 19', 'एवमुक्ता तु वैदेही क्रुद्धा संरक्तलोचना।
अब्रवीत्परुषं वाक्यं रहिते राक्षसाधिपम्॥', 'evam uktā tu vaidehī kruddhā saṃraktalocanā
abravīt paruṣaṃ vākyaṃ rahite rākṣasādhipam', null, 3046019),
('ramayana-3-46-20', 20, 'Aranya Kanda, Sarga 46, Verse 20', 'कथं वैश्रवणं देवं सर्वभूतनमस्कृतम्।
भ्रातरं व्यपदिश्य त्वमशुभं कर्तुमिच्छसि॥', 'kathaṃ vaiśravaṇaṃ devaṃ sarvabhūtanamaskṛtam
bhrātaraṃ vyapadiśya tvam aśubhaṃ kartum icchasi', null, 3046020),
('ramayana-3-46-21', 21, 'Aranya Kanda, Sarga 46, Verse 21', 'अवश्यं विनशिष्यन्ति सर्वे रावण राक्षसाः।
येषां त्वं कर्कशो राजा दुर्बुद्धिरजितेन्द्रियः॥', 'avaśyaṃ vinaśiṣyanti sarve rāvaṇa rākṣasāḥ
yeṣāṃ tvaṃ karkaśo rājā durbuddhir ajitendriyaḥ', null, 3046021),
('ramayana-3-46-22', 22, 'Aranya Kanda, Sarga 46, Verse 22', 'अपहृत्य शचीं भार्यां शक्यमिन्द्रस्य जीवितुम्।
न तु रामस्य भार्यां मामपनीयास्ति जीवितम्॥', 'apahṛtya śacīṃ bhāryāṃ śakyam indrasya jīvitum
na tu rāmasya bhāryāṃ mām apanīyāsti jīvitam', null, 3046022),
('ramayana-3-46-23', 23, 'Aranya Kanda, Sarga 46, Verse 23', 'जीवेच्चिरं वज्रधरस्य हस्ताच्छचीं प्रधृष्याप्रतिरूपरूपाम्।
न मादृशीं राक्षसधर्षयित्वा पीतामृतस्यापि तवास्ति मोक्षः॥', 'jīvec ciraṃ vajradharasya hastāc chacīṃ pradhṛṣyāpratirūparūpām
na mādṛśīṃ rākṣasadharṣayitvā pītāmṛtasyāpi tavāsti mokṣaḥ', null, 3046023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 47 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-47-1', 1, 'Aranya Kanda, Sarga 47, Verse 1', 'सीताया वचनं श्रुत्वा दशग्रीवः प्रतापवान्।
हस्ते हस्तं समाहत्य चकार सुमहद्वपुः॥', 'sītāyā vacanaṃ śrutvā daśagrīvaḥ pratāpavān
haste hastaṃ samāhatya cakāra sumahad vapuḥ', null, 3047001),
('ramayana-3-47-2', 2, 'Aranya Kanda, Sarga 47, Verse 2', 'स मैथिलीं पुनर्वाक्यं बभाषे च ततो भृशम्।
नोन्मत्तया श्रुतौ मन्ये मम वीर्यपराक्रमौ॥', 'sa maithilīṃ punar vākyaṃ babhāṣe ca tato bhṛśam
nonmattayā śrutau manye mama vīryaparākramau', null, 3047002),
('ramayana-3-47-3', 3, 'Aranya Kanda, Sarga 47, Verse 3', 'उद्वहेयं भुजाभ्यां तु मेदिनीमम्बरे स्थितः।
आपिबेयं समुद्रं च मृत्युं हन्यां रणे स्थितः॥', 'udvaheyaṃ bhujābhyāṃ tu medinīm ambare sthitaḥ
āpibeyaṃ samudraṃ ca mṛtyuṃ hanyāṃ raṇe sthitaḥ', null, 3047003),
('ramayana-3-47-4', 4, 'Aranya Kanda, Sarga 47, Verse 4', 'अर्कं रुन्ध्यां शरैस्तीक्ष्णैर्विभिन्द्यां हि महीतलम्।
कामरूपिणमुन्मत्ते पश्य मां कामदं पतिम्॥', 'arkaṃ rundhyāṃ śarais tīkṣṇair vibhindyāṃ hi mahītalam
kāmarūpiṇam unmatte paśya māṃ kāmadaṃ patim', null, 3047004),
('ramayana-3-47-5', 5, 'Aranya Kanda, Sarga 47, Verse 5', 'एवमुक्तवतस्तस्य रावणस्य शिखिप्रभे।
क्रुद्धस्य हरिपर्यन्ते रक्ते नेत्रे बभूवतुः॥', 'evam uktavatas tasya rāvaṇasya śikhiprabhe
kruddhasya hariparyante rakte netre babhūvatuḥ', null, 3047005),
('ramayana-3-47-6', 6, 'Aranya Kanda, Sarga 47, Verse 6', 'सद्यः सौम्यं परित्यज्य भिक्षुरूपं स रावणः।
स्वं रूपं कालरूपाभं भेजे वैश्रवणानुजः॥', 'sadyaḥ saumyaṃ parityajya bhikṣurūpaṃ sa rāvaṇaḥ
svaṃ rūpaṃ kālarūpābhaṃ bheje vaiśravaṇānujaḥ', null, 3047006),
('ramayana-3-47-7', 7, 'Aranya Kanda, Sarga 47, Verse 7', 'संरक्तनयनः श्रीमांस्तप्तकाञ्चनकुण्डलः।
दशास्यः कार्मुकी बाणी बभूव क्षणदाचरः॥', 'saṃraktanayanaḥ śrīmāṃs taptakāñcanakuṇḍalaḥ
daśāsyaḥ kārmukī bāṇī babhūva kṣaṇadācaraḥ', null, 3047007),
('ramayana-3-47-8', 8, 'Aranya Kanda, Sarga 47, Verse 8', 'स परिव्राजकच्छद्म महाकायो विहाय तत्।
प्रतिपेदे स्वकं रूपं रावणो राक्षसाधिपः॥', 'sa parivrājakacchadma mahākāyo vihāya tat
pratipede svakaṃ rūpaṃ rāvaṇo rākṣasādhipaḥ', null, 3047008),
('ramayana-3-47-9', 9, 'Aranya Kanda, Sarga 47, Verse 9', 'संरक्तनयनः क्रोधाज्जीमूतनिचयप्रभः।
रक्ताम्बरधरस्तस्थौ स्त्रीरत्नं प्रेक्ष्य मैथिलीम्॥', 'saṃraktanayanaḥ krodhāj jīmūtanicayaprabhaḥ
raktāmbaradharas tasthau strīratnaṃ prekṣya maithilīm', null, 3047009),
('ramayana-3-47-10', 10, 'Aranya Kanda, Sarga 47, Verse 10', 'स तामसितकेशान्तां भास्करस्य प्रभामिव।
वसनाभरणोपेतां मैथिलीं रावणोऽब्रवीत्॥', 'sa tām asitakeśāntāṃ bhāskarasya prabhām iva
vasanābharaṇopetāṃ maithilīṃ rāvaṇo ''bravīt', null, 3047010),
('ramayana-3-47-11', 11, 'Aranya Kanda, Sarga 47, Verse 11', 'त्रिषु लोकेषु विख्यातं यदि भर्तारमिच्छसि।
मामाश्रय वरारोहे तवाहं सदृशः पतिः॥', 'triṣu lokeṣu vikhyātaṃ yadi bhartāram icchasi
mām āśraya varārohe tavāhaṃ sadṛśaḥ patiḥ', null, 3047011),
('ramayana-3-47-12', 12, 'Aranya Kanda, Sarga 47, Verse 12', 'मां भजस्व चिराय त्वमहं श्लाघ्यस्तव प्रियः।
नैव चाहं क्व चिद्भद्रे करिष्ये तव विप्रियम्।
त्यज्यतां मानुषो भावो मयि भावः प्रणीयताम्॥', 'māṃ bhajasva cirāya tvam ahaṃ ślāghyas tava priyaḥ
naiva cāhaṃ kva cid bhadre kariṣye tava vipriyam
tyajyatāṃ mānuṣo bhāvo mayi bhāvaḥ praṇīyatām', null, 3047012),
('ramayana-3-47-13', 13, 'Aranya Kanda, Sarga 47, Verse 13', 'राज्याच्च्युतमसिद्धार्थं रामं परिमितायुषम्।
कैर्गुणैरनुरक्तासि मूढे पण्डितमानिनि॥', 'rājyāc cyutam asiddhārthaṃ rāmaṃ parimitāyuṣam
kair guṇair anuraktāsi mūḍhe paṇḍitamānini', null, 3047013),
('ramayana-3-47-14', 14, 'Aranya Kanda, Sarga 47, Verse 14', 'यः स्त्रिया वचनाद्राज्यं विहाय ससुहृज्जनम्।
अस्मिन्व्यालानुचरिते वने वसति दुर्मतिः॥', 'yaḥ striyā vacanād rājyaṃ vihāya sasuhṛjjanam
asmin vyālānucarite vane vasati durmatiḥ', null, 3047014),
('ramayana-3-47-15', 15, 'Aranya Kanda, Sarga 47, Verse 15', 'इत्युक्त्वा मैथिलीं वाक्यं प्रियार्हां प्रियवादिनीम्।
जग्राह रावणः सीतां बुधः खे रोहिणीमिव॥', 'ity uktvā maithilīṃ vākyaṃ priyārhāṃ priyavādinīm
jagrāha rāvaṇaḥ sītāṃ budhaḥ khe rohiṇīm iva', null, 3047015),
('ramayana-3-47-16', 16, 'Aranya Kanda, Sarga 47, Verse 16', 'वामेन सीतां पद्माक्षीं मूर्धजेषु करेण सः।
ऊर्वोस्तु दक्षिणेनैव परिजग्राह पाणिना॥', 'vāmena sītāṃ padmākṣīṃ mūrdhajeṣu kareṇa saḥ
ūrvos tu dakṣiṇenaiva parijagrāha pāṇinā', null, 3047016),
('ramayana-3-47-17', 17, 'Aranya Kanda, Sarga 47, Verse 17', 'तं दृष्ट्वा गिरिशृङ्गाभं तीक्ष्णदंष्ट्रं महाभुजम्।
प्राद्रवन्मृत्युसंकाशं भयार्ता वनदेवताः॥', 'taṃ dṛṣṭvā giriśṛṅgābhaṃ tīkṣṇadaṃṣṭraṃ mahābhujam
prādravan mṛtyusaṃkāśaṃ bhayārtā vanadevatāḥ', null, 3047017),
('ramayana-3-47-18', 18, 'Aranya Kanda, Sarga 47, Verse 18', 'स च मायामयो दिव्यः खरयुक्तः खरस्वनः।
प्रत्यदृश्यत हेमाङ्गो रावणस्य महारथः॥', 'sa ca māyāmayo divyaḥ kharayuktaḥ kharasvanaḥ
pratyadṛśyata hemāṅgo rāvaṇasya mahārathaḥ', null, 3047018),
('ramayana-3-47-19', 19, 'Aranya Kanda, Sarga 47, Verse 19', 'ततस्तां परुषैर्वाक्यैरभितर्ज्य महास्वनः।
अङ्केनादाय वैदेहीं रथमारोपयत्तदा॥', 'tatas tāṃ paruṣair vākyair abhitarjya mahāsvanaḥ
aṅkenādāya vaidehīṃ ratham āropayat tadā', null, 3047019),
('ramayana-3-47-20', 20, 'Aranya Kanda, Sarga 47, Verse 20', 'सा गृहीतातिचुक्रोश रावणेन यशस्विनी।
रामेति सीता दुःखार्ता रामं दूरगतं वने॥', 'sā gṛhītāticukrośa rāvaṇena yaśasvinī
rāmeti sītā duḥkhārtā rāmaṃ dūragataṃ vane', null, 3047020),
('ramayana-3-47-21', 21, 'Aranya Kanda, Sarga 47, Verse 21', 'तामकामां स कामार्तः पन्नगेन्द्रवधूमिव।
विवेष्टमानामादाय उत्पपाथाथ रावणः॥', 'tām akāmāṃ sa kāmārtaḥ pannagendravadhūm iva
viveṣṭamānām ādāya utpapāthātha rāvaṇaḥ', null, 3047021),
('ramayana-3-47-22', 22, 'Aranya Kanda, Sarga 47, Verse 22', 'ततः सा राक्षसेन्द्रेण ह्रियमाणा विहायसा।
भृशं चुक्रोश मत्तेव भ्रान्तचित्ता यथातुरा॥', 'tataḥ sā rākṣasendreṇa hriyamāṇā vihāyasā
bhṛśaṃ cukrośa matteva bhrāntacittā yathāturā', null, 3047022),
('ramayana-3-47-23', 23, 'Aranya Kanda, Sarga 47, Verse 23', 'हा लक्ष्मण महाबाहो गुरुचित्तप्रसादक।
ह्रियमाणां न जानीषे रक्षसा कामरूपिणा॥', 'hā lakṣmaṇa mahābāho gurucittaprasādaka
hriyamāṇāṃ na jānīṣe rakṣasā kāmarūpiṇā', null, 3047023),
('ramayana-3-47-24', 24, 'Aranya Kanda, Sarga 47, Verse 24', 'जीवितं सुखमर्थांश्च धर्महेतोः परित्यजन्।
ह्रियमाणामधर्मेण मां राघव न पश्यसि॥', 'jīvitaṃ sukham arthāṃś ca dharmahetoḥ parityajan
hriyamāṇām adharmeṇa māṃ rāghava na paśyasi', null, 3047024),
('ramayana-3-47-25', 25, 'Aranya Kanda, Sarga 47, Verse 25', 'ननु नामाविनीतानां विनेतासि परंतप।
कथमेवंविधं पापं न त्वं शाधि हि रावणम्॥', 'nanu nāmāvinītānāṃ vinetāsi paraṃtapa
katham evaṃvidhaṃ pāpaṃ na tvaṃ śādhi hi rāvaṇam', null, 3047025),
('ramayana-3-47-26', 26, 'Aranya Kanda, Sarga 47, Verse 26', 'ननु सद्योऽविनीतस्य दृश्यते कर्मणः फलम्।
कालोऽप्यङ्गी भवत्यत्र सस्यानामिव पक्तये॥', 'nanu sadyo ''vinītasya dṛśyate karmaṇaḥ phalam
kālo ''py aṅgī bhavaty atra sasyānām iva paktaye', null, 3047026),
('ramayana-3-47-27', 27, 'Aranya Kanda, Sarga 47, Verse 27', 'स कर्म कृतवानेतत्कालोपहतचेतनः।
जीवितान्तकरं घोरं रामाद्व्यसनमाप्नुहि॥', 'sa karma kṛtavān etat kālopahatacetanaḥ
jīvitāntakaraṃ ghoraṃ rāmād vyasanam āpnuhi', null, 3047027),
('ramayana-3-47-28', 28, 'Aranya Kanda, Sarga 47, Verse 28', 'हन्तेदानीं सकामा तु कैकेयी बान्धवैः सह।
ह्रियेयं धर्मकामस्य धर्मपत्नी यशस्विनः॥', 'hantedānīṃ sakāmā tu kaikeyī bāndhavaiḥ saha
hriyeyaṃ dharmakāmasya dharmapatnī yaśasvinaḥ', null, 3047028),
('ramayana-3-47-29', 29, 'Aranya Kanda, Sarga 47, Verse 29', 'आमन्त्रये जनस्थानं कर्णिकारांश्च पुष्पितान्।
क्षिप्रं रामाय शंसध्वं सीतां हरति रावणः॥', 'āmantraye janasthānaṃ karṇikārāṃś ca puṣpitān
kṣipraṃ rāmāya śaṃsadhvaṃ sītāṃ harati rāvaṇaḥ', null, 3047029),
('ramayana-3-47-30', 30, 'Aranya Kanda, Sarga 47, Verse 30', 'माल्यवन्तं शिखरिणं वन्दे प्रस्रवणं गिरिम्।
क्षिप्रं रामाय शंसध्वं सीतां हरति रावणः॥', 'mālyavantaṃ śikhariṇaṃ vande prasravaṇaṃ girim
kṣipraṃ rāmāya śaṃsadhvaṃ sītāṃ harati rāvaṇaḥ', null, 3047030),
('ramayana-3-47-31', 31, 'Aranya Kanda, Sarga 47, Verse 31', 'हंससारससंघुष्टां वन्दे गोदावरीं नदीम्।
क्षिप्रं रामाय शंसध्वं सीतां हरति रावणः॥', 'haṃsasārasasaṃghuṣṭāṃ vande godāvarīṃ nadīm
kṣipraṃ rāmāya śaṃsadhvaṃ sītāṃ harati rāvaṇaḥ', null, 3047031),
('ramayana-3-47-32', 32, 'Aranya Kanda, Sarga 47, Verse 32', 'दैवतानि च यान्त्यस्मिन्वने विविधपादपे।
नमस्करोम्यहं तेभ्यो भर्तुः शंसत मां हृताम्॥', 'daivatāni ca yānty asmin vane vividhapādape
namaskaromy ahaṃ tebhyo bhartuḥ śaṃsata māṃ hṛtām', null, 3047032),
('ramayana-3-47-33', 33, 'Aranya Kanda, Sarga 47, Verse 33', 'यानि कानि चिदप्यत्र सत्त्वानि निवसन्त्युत।
सर्वाणि शरणं यामि मृगपक्षिगणानपि॥', 'yāni kāni cid apy atra sattvāni nivasanty uta
sarvāṇi śaraṇaṃ yāmi mṛgapakṣigaṇān api', null, 3047033),
('ramayana-3-47-34', 34, 'Aranya Kanda, Sarga 47, Verse 34', 'ह्रियमाणां प्रियां भर्तुः प्राणेभ्योऽपि गरीयसीम्।
विवशापहृता सीता रावणेनेति शंसत॥', 'hriyamāṇāṃ priyāṃ bhartuḥ prāṇebhyo ''pi garīyasīm
vivaśāpahṛtā sītā rāvaṇeneti śaṃsata', null, 3047034),
('ramayana-3-47-35', 35, 'Aranya Kanda, Sarga 47, Verse 35', 'विदित्वा मां महाबाहुरमुत्रापि महाबलः।
आनेष्यति पराक्रम्य वैवस्वतहृतामपि॥', 'viditvā māṃ mahābāhur amutrāpi mahābalaḥ
āneṣyati parākramya vaivasvatahṛtām api', null, 3047035),
('ramayana-3-47-36', 36, 'Aranya Kanda, Sarga 47, Verse 36', 'रामाय तु यथातत्त्वं जटायो हरणं मम।
लक्ष्मणाय च तत्सर्वमाख्यातव्यमशेषतः॥', 'rāmāya tu yathātattvaṃ jaṭāyo haraṇaṃ mama
lakṣmaṇāya ca tat sarvam ākhyātavyam aśeṣataḥ', null, 3047036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 48 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-48-1', 1, 'Aranya Kanda, Sarga 48, Verse 1', 'तं शब्दमवसुप्तस्य जटायुरथ शुश्रुवे।
निरैक्षद्रावणं क्षिप्रं वैदेहीं च ददर्श सः॥', 'taṃ śabdam avasuptasya jaṭāyur atha śuśruve
niraikṣad rāvaṇaṃ kṣipraṃ vaidehīṃ ca dadarśa saḥ', null, 3048001),
('ramayana-3-48-2', 2, 'Aranya Kanda, Sarga 48, Verse 2', 'ततः पर्वतकूटाभस्तीक्ष्णतुण्डः खगोत्तमः।
वनस्पतिगतः श्रीमान्व्याजहार शुभां गिरम्॥', 'tataḥ parvatakūṭābhas tīkṣṇatuṇḍaḥ khagottamaḥ
vanaspatigataḥ śrīmān vyājahāra śubhāṃ giram', null, 3048002),
('ramayana-3-48-3', 3, 'Aranya Kanda, Sarga 48, Verse 3', 'दशग्रीवस्थितो धर्मे पुराणे सत्यसंश्रयः।
जटायुर्नाम नाम्नाहं गृध्रराजो महाबलः॥', 'daśagrīvasthito dharme purāṇe satyasaṃśrayaḥ
jaṭāyur nāma nāmnāhaṃ gṛdhrarājo mahābalaḥ', null, 3048003),
('ramayana-3-48-4', 4, 'Aranya Kanda, Sarga 48, Verse 4', 'राजा सर्वस्य लोकस्य महेन्द्रवरुणोपमः।
लोकानां च हिते युक्तो रामो दशरथात्मजः॥', 'rājā sarvasya lokasya mahendravaruṇopamaḥ
lokānāṃ ca hite yukto rāmo daśarathātmajaḥ', null, 3048004),
('ramayana-3-48-5', 5, 'Aranya Kanda, Sarga 48, Verse 5', 'तस्यैषा लोकनाथस्य धर्मपत्नी यशस्विनी।
सीता नाम वरारोहा यां त्वं हर्तुमिहेच्छसि॥', 'tasyaiṣā lokanāthasya dharmapatnī yaśasvinī
sītā nāma varārohā yāṃ tvaṃ hartum ihecchasi', null, 3048005),
('ramayana-3-48-6', 6, 'Aranya Kanda, Sarga 48, Verse 6', 'कथं राजा स्थितो धर्मे परदारान्परामृशेत्।
रक्षणीया विशेषेण राजदारा महाबलः।
निवर्तय मतिं नीचां परदाराभिमर्शनम्॥', 'kathaṃ rājā sthito dharme paradārān parāmṛśet
rakṣaṇīyā viśeṣeṇa rājadārā mahābalaḥ
nivartaya matiṃ nīcāṃ paradārābhimarśanam', null, 3048006),
('ramayana-3-48-7', 7, 'Aranya Kanda, Sarga 48, Verse 7', 'न तत्समाचरेद्धीरो यत्परोऽस्य विगर्हयेत्।
यथात्मनस्तथान्येषां दारा रक्ष्या विमर्शनात्॥', 'na tat samācared dhīro yat paro ''sya vigarhayet
yathātmanas tathānyeṣāṃ dārā rakṣyā vimarśanāt', null, 3048007),
('ramayana-3-48-8', 8, 'Aranya Kanda, Sarga 48, Verse 8', 'अर्थं वा यदि वा कामं शिष्टाः शास्त्रेष्वनागतम्।
व्यवस्यन्त्यनु राजानं धर्मं पौरस्त्यनन्दन॥', 'arthaṃ vā yadi vā kāmaṃ śiṣṭāḥ śāstreṣv anāgatam
vyavasyanty anu rājānaṃ dharmaṃ paurastyanandana', null, 3048008),
('ramayana-3-48-9', 9, 'Aranya Kanda, Sarga 48, Verse 9', 'राजा धर्मश्च कामश्च द्रव्याणां चोत्तमो निधिः।
धर्मः शुभं वा पापं वा राजमूलं प्रवर्तते॥', 'rājā dharmaś ca kāmaś ca dravyāṇāṃ cottamo nidhiḥ
dharmaḥ śubhaṃ vā pāpaṃ vā rājamūlaṃ pravartate', null, 3048009),
('ramayana-3-48-10', 10, 'Aranya Kanda, Sarga 48, Verse 10', 'पापस्वभावश्चपलः कथं त्वं रक्षसां वर।
ऐश्वर्यमभिसंप्राप्तो विमानमिव दुष्कृती॥', 'pāpasvabhāvaś capalaḥ kathaṃ tvaṃ rakṣasāṃ vara
aiśvaryam abhisaṃprāpto vimānam iva duṣkṛtī', null, 3048010),
('ramayana-3-48-11', 11, 'Aranya Kanda, Sarga 48, Verse 11', 'कामस्वभावो यो यस्य न स शक्यः प्रमार्जितुम्।
न हि दुष्टात्मनामार्य मा वसत्यालये चिरम्॥', 'kāmasvabhāvo yo yasya na sa śakyaḥ pramārjitum
na hi duṣṭātmanām ārya mā vasaty ālaye ciram', null, 3048011),
('ramayana-3-48-12', 12, 'Aranya Kanda, Sarga 48, Verse 12', 'विषये वा पुरे वा ते यदा रामो महाबलः।
नापराध्यति धर्मात्मा कथं तस्यापराध्यसि॥', 'viṣaye vā pure vā te yadā rāmo mahābalaḥ
nāparādhyati dharmātmā kathaṃ tasyāparādhyasi', null, 3048012),
('ramayana-3-48-13', 13, 'Aranya Kanda, Sarga 48, Verse 13', 'यदि शूर्पणखाहेतोर्जनस्थानगतः खरः।
अतिवृत्तो हतः पूर्वं रामेणाक्लिष्टकर्मणा॥', 'yadi śūrpaṇakhāhetor janasthānagataḥ kharaḥ
ativṛtto hataḥ pūrvaṃ rāmeṇākliṣṭakarmaṇā', null, 3048013),
('ramayana-3-48-14', 14, 'Aranya Kanda, Sarga 48, Verse 14', 'अत्र ब्रूहि यथासत्यं को रामस्य व्यतिक्रमः।
यस्य त्वं लोकनाथस्य हृत्वा भार्यां गमिष्यसि॥', 'atra brūhi yathāsatyaṃ ko rāmasya vyatikramaḥ
yasya tvaṃ lokanāthasya hṛtvā bhāryāṃ gamiṣyasi', null, 3048014),
('ramayana-3-48-15', 15, 'Aranya Kanda, Sarga 48, Verse 15', 'क्षिप्रं विसृज वैदेहीं मा त्वा घोरेण चक्षुषा।
दहेद्दहन भूतेन वृत्रमिन्द्राशनिर्यथा॥', 'kṣipraṃ visṛja vaidehīṃ mā tvā ghoreṇa cakṣuṣā
dahed dahana bhūtena vṛtram indrāśanir yathā', null, 3048015),
('ramayana-3-48-16', 16, 'Aranya Kanda, Sarga 48, Verse 16', 'सर्पमाशीविषं बद्ध्वा वस्त्रान्ते नावबुध्यसे।
ग्रीवायां प्रतिमुक्तं च कालपाशं न पश्यसि॥', 'sarpam āśīviṣaṃ baddhvā vastrānte nāvabudhyase
grīvāyāṃ pratimuktaṃ ca kālapāśaṃ na paśyasi', null, 3048016),
('ramayana-3-48-17', 17, 'Aranya Kanda, Sarga 48, Verse 17', 'स भारः सौम्य भर्तव्यो यो नरं नावसादयेत्।
तदन्नमुपभोक्तव्यं जीर्यते यदनामयम्॥', 'sa bhāraḥ saumya bhartavyo yo naraṃ nāvasādayet
tad annam upabhoktavyaṃ jīryate yad anāmayam', null, 3048017),
('ramayana-3-48-18', 18, 'Aranya Kanda, Sarga 48, Verse 18', 'यत्कृत्वा न भवेद्धर्मो न कीर्तिर्न यशो भुवि।
शरीरस्य भवेत्खेदः कस्तत्कर्म समाचरेत्॥', 'yat kṛtvā na bhaved dharmo na kīrtir na yaśo bhuvi
śarīrasya bhavet khedaḥ kas tat karma samācaret', null, 3048018),
('ramayana-3-48-19', 19, 'Aranya Kanda, Sarga 48, Verse 19', 'षष्टिवर्षसहस्राणि मम जातस्य रावण।
पितृपैतामहं राज्यं यथावदनुतिष्ठतः॥', 'ṣaṣṭivarṣasahasrāṇi mama jātasya rāvaṇa
pitṛpaitāmahaṃ rājyaṃ yathāvad anutiṣṭhataḥ', null, 3048019),
('ramayana-3-48-20', 20, 'Aranya Kanda, Sarga 48, Verse 20', 'वृद्धोऽहं त्वं युवा धन्वी सरथः कवची शरी।
तथाप्यादाय वैदेहीं कुशली न गमिष्यसि॥', 'vṛddho ''haṃ tvaṃ yuvā dhanvī sarathaḥ kavacī śarī
tathāpy ādāya vaidehīṃ kuśalī na gamiṣyasi', null, 3048020),
('ramayana-3-48-21', 21, 'Aranya Kanda, Sarga 48, Verse 21', 'न शक्तस्त्वं बलाद्धर्तुं वैदेहीं मम पश्यतः।
हेतुभिर्न्यायसंयुक्तैर्ध्रुवां वेदश्रुतीमिव॥', 'na śaktas tvaṃ balād dhartuṃ vaidehīṃ mama paśyataḥ
hetubhir nyāyasaṃyuktair dhruvāṃ vedaśrutīm iva', null, 3048021),
('ramayana-3-48-22', 22, 'Aranya Kanda, Sarga 48, Verse 22', 'युध्यस्व यदि शूरोऽसि मुहूर्तं तिष्ठ रावण।
शयिष्यसे हतो भूमौ यथापूर्वं खरस्तथा॥', 'yudhyasva yadi śūro ''si muhūrtaṃ tiṣṭha rāvaṇa
śayiṣyase hato bhūmau yathāpūrvaṃ kharas tathā', null, 3048022),
('ramayana-3-48-23', 23, 'Aranya Kanda, Sarga 48, Verse 23', 'असकृत्संयुगे येन निहता दैत्यदानवाः।
नचिराच्चीरवासास्त्वां रामो युधि वधिष्यति॥', 'asakṛt saṃyuge yena nihatā daityadānavāḥ
nacirāc cīravāsās tvāṃ rāmo yudhi vadhiṣyati', null, 3048023),
('ramayana-3-48-24', 24, 'Aranya Kanda, Sarga 48, Verse 24', 'किं नु शक्यं मया कर्तुं गतौ दूरं नृपात्मजौ।
क्षिप्रं त्वं नश्यसे नीच तयोर्भीतो न संशयः॥', 'kiṃ nu śakyaṃ mayā kartuṃ gatau dūraṃ nṛpātmajau
kṣipraṃ tvaṃ naśyase nīca tayor bhīto na saṃśayaḥ', null, 3048024),
('ramayana-3-48-25', 25, 'Aranya Kanda, Sarga 48, Verse 25', 'न हि मे जीवमानस्य नयिष्यसि शुभामिमाम्।
सीतां कमलपत्राक्षीं रामस्य महषीं प्रियाम्॥', 'na hi me jīvamānasya nayiṣyasi śubhām imām
sītāṃ kamalapatrākṣīṃ rāmasya mahaṣīṃ priyām', null, 3048025),
('ramayana-3-48-26', 26, 'Aranya Kanda, Sarga 48, Verse 26', 'अवश्यं तु मया कार्यं प्रियं तस्य महात्मनः।
जीवितेनापि रामस्य तथा दशरथस्य च॥', 'avaśyaṃ tu mayā kāryaṃ priyaṃ tasya mahātmanaḥ
jīvitenāpi rāmasya tathā daśarathasya ca', null, 3048026),
('ramayana-3-48-27', 27, 'Aranya Kanda, Sarga 48, Verse 27', 'तिष्ठ तिष्ठ दशग्रीव मुहूर्तं पश्य रावण।
युद्धातिथ्यं प्रदास्यामि यथाप्राणं निशाचर।
वृन्तादिव फलं त्वां तु पातयेयं रथोत्तमात्॥', 'tiṣṭha tiṣṭha daśagrīva muhūrtaṃ paśya rāvaṇa
yuddhātithyaṃ pradāsyāmi yathāprāṇaṃ niśācara
vṛntād iva phalaṃ tvāṃ tu pātayeyaṃ rathottamāt', null, 3048027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 49 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-49-1', 1, 'Aranya Kanda, Sarga 49, Verse 1', 'इत्युक्तस्य यथान्यायं रावणस्य जटायुषा।
क्रुद्धस्याग्निनिभाः सर्वा रेजुर्विंशतिदृष्टयः॥', 'ity uktasya yathānyāyaṃ rāvaṇasya jaṭāyuṣā
kruddhasyāgninibhāḥ sarvā rejur viṃśatidṛṣṭayaḥ', null, 3049001),
('ramayana-3-49-2', 2, 'Aranya Kanda, Sarga 49, Verse 2', 'संरक्तनयनः कोपात्तप्तकाञ्चनकुण्डलः।
राक्षसेन्द्रोऽभिदुद्राव पतगेन्द्रममर्षणः॥', 'saṃraktanayanaḥ kopāt taptakāñcanakuṇḍalaḥ
rākṣasendro ''bhidudrāva patagendram amarṣaṇaḥ', null, 3049002),
('ramayana-3-49-3', 3, 'Aranya Kanda, Sarga 49, Verse 3', 'स संप्रहारस्तुमुलस्तयोस्तस्मिन्महावने।
बभूव वातोद्धतयोर्मेघयोर्गगने यथा॥', 'sa saṃprahāras tumulas tayos tasmin mahāvane
babhūva vātoddhatayor meghayor gagane yathā', null, 3049003),
('ramayana-3-49-4', 4, 'Aranya Kanda, Sarga 49, Verse 4', 'तद्बभूवाद्भुतं युद्धं गृध्रराक्षसयोस्तदा।
सपक्षयोर्माल्यवतोर्महापर्वतयोरिव॥', 'tad babhūvādbhutaṃ yuddhaṃ gṛdhrarākṣasayos tadā
sapakṣayor mālyavator mahāparvatayor iva', null, 3049004),
('ramayana-3-49-5', 5, 'Aranya Kanda, Sarga 49, Verse 5', 'ततो नालीकनाराचैस्तीक्ष्णाग्रैश्च विकर्णिभिः।
अभ्यवर्षन्महाघोरैर्गृध्रराजं महाबलः॥', 'tato nālīkanārācais tīkṣṇāgraiś ca vikarṇibhiḥ
abhyavarṣan mahāghorair gṛdhrarājaṃ mahābalaḥ', null, 3049005),
('ramayana-3-49-6', 6, 'Aranya Kanda, Sarga 49, Verse 6', 'स तानि शरजालानि गृध्रः पत्ररथेश्वरः।
जटायुः प्रतिजग्राह रावणास्त्राणि संयुगे॥', 'sa tāni śarajālāni gṛdhraḥ patraratheśvaraḥ
jaṭāyuḥ pratijagrāha rāvaṇāstrāṇi saṃyuge', null, 3049006),
('ramayana-3-49-7', 7, 'Aranya Kanda, Sarga 49, Verse 7', 'तस्य तीक्ष्णनखाभ्यां तु चरणाभ्यां महाबलः।
चकार बहुधा गात्रे व्रणान्पतगसत्तमः॥', 'tasya tīkṣṇanakhābhyāṃ tu caraṇābhyāṃ mahābalaḥ
cakāra bahudhā gātre vraṇān patagasattamaḥ', null, 3049007),
('ramayana-3-49-8', 8, 'Aranya Kanda, Sarga 49, Verse 8', 'अथ क्रोधाद्दशग्रीवो जग्राह दशमार्गणान्।
मृत्युदण्डनिभान्घोराञ्शत्रुमर्दनकाङ्क्षया॥', 'atha krodhād daśagrīvo jagrāha daśamārgaṇān
mṛtyudaṇḍanibhān ghorāñ śatrumardanakāṅkṣayā', null, 3049008),
('ramayana-3-49-9', 9, 'Aranya Kanda, Sarga 49, Verse 9', 'स तैर्बाणैर्महावीर्यः पूर्णमुक्तैरजिह्मगैः।
बिभेद निशितैस्तीक्ष्णैर्गृध्रं घोरैः शिलीमुखैः॥', 'sa tair bāṇair mahāvīryaḥ pūrṇamuktair ajihmagaiḥ
bibheda niśitais tīkṣṇair gṛdhraṃ ghoraiḥ śilīmukhaiḥ', null, 3049009),
('ramayana-3-49-10', 10, 'Aranya Kanda, Sarga 49, Verse 10', 'स राक्षसरथे पश्यञ्जानकीं बाष्पलोचनाम्।
अचिन्तयित्वा बाणांस्तान्राक्षसं समभिद्रवत्॥', 'sa rākṣasarathe paśyañ jānakīṃ bāṣpalocanām
acintayitvā bāṇāṃs tān rākṣasaṃ samabhidravat', null, 3049010),
('ramayana-3-49-11', 11, 'Aranya Kanda, Sarga 49, Verse 11', 'ततोऽस्य सशरं चापं मुक्तामणिविभूषितम्।
चरणाभ्यां महातेजा बभञ्ज पतगेश्वरः॥', 'tato ''sya saśaraṃ cāpaṃ muktāmaṇivibhūṣitam
caraṇābhyāṃ mahātejā babhañja patageśvaraḥ', null, 3049011),
('ramayana-3-49-12', 12, 'Aranya Kanda, Sarga 49, Verse 12', 'तच्चाग्निसदृशं दीप्तं रावणस्य शरावरम्।
पक्षाभ्यां च महातेजा व्यधुनोत्पतगेश्वरः॥', 'tac cāgnisadṛśaṃ dīptaṃ rāvaṇasya śarāvaram
pakṣābhyāṃ ca mahātejā vyadhunot patageśvaraḥ', null, 3049012),
('ramayana-3-49-13', 13, 'Aranya Kanda, Sarga 49, Verse 13', 'काञ्चनोरश्छदान्दिव्यान्पिशाचवदनान्खरान्।
तांश्चास्य जवसंपन्नाञ्जघान समरे बली॥', 'kāñcanoraśchadān divyān piśācavadanān kharān
tāṃś cāsya javasaṃpannāñ jaghāna samare balī', null, 3049013),
('ramayana-3-49-14', 14, 'Aranya Kanda, Sarga 49, Verse 14', 'वरं त्रिवेणुसंपन्नं कामगं पावकार्चिषम्।
मणिहेमविचित्राङ्गं बभञ्ज च महारथम्।
पूर्णचन्द्रप्रतीकाशं छत्रं च व्यजनैः सह॥', 'varaṃ triveṇusaṃpannaṃ kāmagaṃ pāvakārciṣam
maṇihemavicitrāṅgaṃ babhañja ca mahāratham
pūrṇacandrapratīkāśaṃ chatraṃ ca vyajanaiḥ saha', null, 3049014),
('ramayana-3-49-15', 15, 'Aranya Kanda, Sarga 49, Verse 15', 'स भग्नधन्वा विरथो हताश्वो हतसारथिः।
अङ्केनादाय वैदेहीं पपात भुवि रावणः॥', 'sa bhagnadhanvā viratho hatāśvo hatasārathiḥ
aṅkenādāya vaidehīṃ papāta bhuvi rāvaṇaḥ', null, 3049015),
('ramayana-3-49-16', 16, 'Aranya Kanda, Sarga 49, Verse 16', 'दृष्ट्वा निपतितं भूमौ रावणं भग्नवाहनम्।
साधु साध्विति भूतानि गृध्रराजमपूजयन्॥', 'dṛṣṭvā nipatitaṃ bhūmau rāvaṇaṃ bhagnavāhanam
sādhu sādhv iti bhūtāni gṛdhrarājam apūjayan', null, 3049016),
('ramayana-3-49-17', 17, 'Aranya Kanda, Sarga 49, Verse 17', 'परिश्रान्तं तु तं दृष्ट्वा जरया पक्षियूथपम्।
उत्पपात पुनर्हृष्टो मैथिलीं गृह्य रावणः॥', 'pariśrāntaṃ tu taṃ dṛṣṭvā jarayā pakṣiyūthapam
utpapāta punar hṛṣṭo maithilīṃ gṛhya rāvaṇaḥ', null, 3049017),
('ramayana-3-49-18', 18, 'Aranya Kanda, Sarga 49, Verse 18', 'तं प्रहृष्टं निधायाङ्के गच्छन्तं जनकात्मजाम्।
गृध्रराजः समुत्पत्य जटायुरिदमब्रवीत्॥', 'taṃ prahṛṣṭaṃ nidhāyāṅke gacchantaṃ janakātmajām
gṛdhrarājaḥ samutpatya jaṭāyur idam abravīt', null, 3049018),
('ramayana-3-49-19', 19, 'Aranya Kanda, Sarga 49, Verse 19', 'वज्रसंस्पर्शबाणस्य भार्यां रामस्य रावण।
अल्पबुद्धे हरस्येनां वधाय खलु रक्षसाम्॥', 'vajrasaṃsparśabāṇasya bhāryāṃ rāmasya rāvaṇa
alpabuddhe harasy enāṃ vadhāya khalu rakṣasām', null, 3049019),
('ramayana-3-49-20', 20, 'Aranya Kanda, Sarga 49, Verse 20', 'समित्रबन्धुः सामात्यः सबलः सपरिच्छदः।
विषपानं पिबस्येतत्पिपासित इवोदकम्॥', 'samitrabandhuḥ sāmātyaḥ sabalaḥ saparicchadaḥ
viṣapānaṃ pibasy etat pipāsita ivodakam', null, 3049020),
('ramayana-3-49-21', 21, 'Aranya Kanda, Sarga 49, Verse 21', 'अनुबन्धमजानन्तः कर्मणामविचक्षणाः।
शीघ्रमेव विनश्यन्ति यथा त्वं विनशिष्यसि॥', 'anubandham ajānantaḥ karmaṇām avicakṣaṇāḥ
śīghram eva vinaśyanti yathā tvaṃ vinaśiṣyasi', null, 3049021),
('ramayana-3-49-22', 22, 'Aranya Kanda, Sarga 49, Verse 22', 'बद्धस्त्वं कालपाशेन क्व गतस्तस्य मोक्ष्यसे।
वधाय बडिशं गृह्य सामिषं जलजो यथा॥', 'baddhas tvaṃ kālapāśena kva gatas tasya mokṣyase
vadhāya baḍiśaṃ gṛhya sāmiṣaṃ jalajo yathā', null, 3049022),
('ramayana-3-49-23', 23, 'Aranya Kanda, Sarga 49, Verse 23', 'न हि जातु दुराधर्षौ काकुत्स्थौ तव रावण।
धर्षणं चाश्रमस्यास्य क्षमिष्येते तु राघवौ॥', 'na hi jātu durādharṣau kākutsthau tava rāvaṇa
dharṣaṇaṃ cāśramasyāsya kṣamiṣyete tu rāghavau', null, 3049023),
('ramayana-3-49-24', 24, 'Aranya Kanda, Sarga 49, Verse 24', 'यथा त्वया कृतं कर्म भीरुणा लोकगर्हितम्।
तस्कराचरितो मार्गो नैष वीरनिषेवितः॥', 'yathā tvayā kṛtaṃ karma bhīruṇā lokagarhitam
taskarācarito mārgo naiṣa vīraniṣevitaḥ', null, 3049024),
('ramayana-3-49-25', 25, 'Aranya Kanda, Sarga 49, Verse 25', 'युध्यस्व यदि शूरोऽसि मुहूर्तं तिष्ठ रावण।
शयिष्यसे हतो भूमौ यथा भ्राता खरस्तथा॥', 'yudhyasva yadi śūro ''si muhūrtaṃ tiṣṭha rāvaṇa
śayiṣyase hato bhūmau yathā bhrātā kharas tathā', null, 3049025),
('ramayana-3-49-26', 26, 'Aranya Kanda, Sarga 49, Verse 26', 'परेतकाले पुरुषो यत्कर्म प्रतिपद्यते।
विनाशायात्मनोऽधर्म्यं प्रतिपन्नोऽसि कर्म तत्॥', 'paretakāle puruṣo yat karma pratipadyate
vināśāyātmano ''dharmyaṃ pratipanno ''si karma tat', null, 3049026),
('ramayana-3-49-27', 27, 'Aranya Kanda, Sarga 49, Verse 27', 'पापानुबन्धो वै यस्य कर्मणः को नु तत्पुमान्।
कुर्वीत लोकाधिपतिः स्वयम्भूर्भगवानपि॥', 'pāpānubandho vai yasya karmaṇaḥ ko nu tat pumān
kurvīta lokādhipatiḥ svayambhūr bhagavān api', null, 3049027),
('ramayana-3-49-28', 28, 'Aranya Kanda, Sarga 49, Verse 28', 'एवमुक्त्वा शुभं वाक्यं जटायुस्तस्य रक्षसः।
निपपात भृशं पृष्ठे दशग्रीवस्य वीर्यवान्॥', 'evam uktvā śubhaṃ vākyaṃ jaṭāyus tasya rakṣasaḥ
nipapāta bhṛśaṃ pṛṣṭhe daśagrīvasya vīryavān', null, 3049028),
('ramayana-3-49-29', 29, 'Aranya Kanda, Sarga 49, Verse 29', 'तं गृहीत्वा नखैस्तीक्ष्णैर्विरराद समन्ततः।
अधिरूढो गजारोहि यथा स्याद्दुष्टवारणम्॥', 'taṃ gṛhītvā nakhais tīkṣṇair virarāda samantataḥ
adhirūḍho gajārohi yathā syād duṣṭavāraṇam', null, 3049029),
('ramayana-3-49-30', 30, 'Aranya Kanda, Sarga 49, Verse 30', 'विरराद नखैरस्य तुण्डं पृष्ठे समर्पयन्।
केशांश्चोत्पाटयामास नखपक्षमुखायुधः॥', 'virarāda nakhair asya tuṇḍaṃ pṛṣṭhe samarpayan
keśāṃś cotpāṭayām āsa nakhapakṣamukhāyudhaḥ', null, 3049030),
('ramayana-3-49-31', 31, 'Aranya Kanda, Sarga 49, Verse 31', 'स तथा गृध्रराजेन क्लिश्यमानो मुहुर्मुहुः।
अमर्षस्फुरितौष्ठः सन्प्राकम्पत स राक्षसः॥', 'sa tathā gṛdhrarājena kliśyamāno muhur muhuḥ
amarṣasphuritauṣṭhaḥ san prākampata sa rākṣasaḥ', null, 3049031),
('ramayana-3-49-32', 32, 'Aranya Kanda, Sarga 49, Verse 32', 'संपरिष्वज्य वैदेहीं वामेनाङ्केन रावणः।
तलेनाभिजघानार्तो जटायुं क्रोधमूर्छितः॥', 'saṃpariṣvajya vaidehīṃ vāmenāṅkena rāvaṇaḥ
talenābhijaghānārto jaṭāyuṃ krodhamūrchitaḥ', null, 3049032),
('ramayana-3-49-33', 33, 'Aranya Kanda, Sarga 49, Verse 33', 'जटायुस्तमतिक्रम्य तुण्डेनास्य खराधिपः।
वामबाहून्दश तदा व्यपाहरदरिंदमः॥', 'jaṭāyus tam atikramya tuṇḍenāsya kharādhipaḥ
vāmabāhūn daśa tadā vyapāharad ariṃdamaḥ', null, 3049033),
('ramayana-3-49-34', 34, 'Aranya Kanda, Sarga 49, Verse 34', 'ततः क्रुद्धो दशक्रीवः सीतामुत्सृज्य वीर्यवान्।
मुष्टिभ्यां चरणाभ्यां च गृध्रराजमपोथयत्॥', 'tataḥ kruddho daśakrīvaḥ sītām utsṛjya vīryavān
muṣṭibhyāṃ caraṇābhyāṃ ca gṛdhrarājam apothayat', null, 3049034),
('ramayana-3-49-35', 35, 'Aranya Kanda, Sarga 49, Verse 35', 'ततो मुहूर्तं संग्रामो बभूवातुलवीर्ययोः।
राक्षसानां च मुख्यस्य पक्षिणां प्रवरस्य च॥', 'tato muhūrtaṃ saṃgrāmo babhūvātulavīryayoḥ
rākṣasānāṃ ca mukhyasya pakṣiṇāṃ pravarasya ca', null, 3049035),
('ramayana-3-49-36', 36, 'Aranya Kanda, Sarga 49, Verse 36', 'तस्य व्यायच्छमानस्य रामस्यार्थेऽथ रावणः।
पक्षौ पादौ च पार्श्वौ च खड्गमुद्धृत्य सोऽच्छिनत्॥', 'tasya vyāyacchamānasya rāmasyārthe ''tha rāvaṇaḥ
pakṣau pādau ca pārśvau ca khaḍgam uddhṛtya so ''cchinat', null, 3049036),
('ramayana-3-49-37', 37, 'Aranya Kanda, Sarga 49, Verse 37', 'स छिन्नपक्षः सहसा रक्षसा रौद्रकर्मणा।
निपपात हतो गृध्रो धरण्यामल्पजीवितः॥', 'sa chinnapakṣaḥ sahasā rakṣasā raudrakarmaṇā
nipapāta hato gṛdhro dharaṇyām alpajīvitaḥ', null, 3049037),
('ramayana-3-49-38', 38, 'Aranya Kanda, Sarga 49, Verse 38', 'तं दृष्ट्वा पतितं भूमौ क्षतजार्द्रं जटायुषम्।
अभ्यधावत वैदेही स्वबन्धुमिव दुःखिता॥', 'taṃ dṛṣṭvā patitaṃ bhūmau kṣatajārdraṃ jaṭāyuṣam
abhyadhāvata vaidehī svabandhum iva duḥkhitā', null, 3049038),
('ramayana-3-49-39', 39, 'Aranya Kanda, Sarga 49, Verse 39', 'तं नीलजीमूतनिकाशकल्पं सुपाण्डुरोरस्कमुदारवीर्यम्।
ददर्श लङ्काधिपतिः पृथिव्यां जटायुषं शान्तमिवाग्निदावम्॥', 'taṃ nīlajīmūtanikāśakalpaṃ supāṇḍuroraskam udāravīryam
dadarśa laṅkādhipatiḥ pṛthivyāṃ jaṭāyuṣaṃ śāntam ivāgnidāvam', null, 3049039),
('ramayana-3-49-40', 40, 'Aranya Kanda, Sarga 49, Verse 40', 'ततस्तु तं पत्ररथं महीतले निपातितं रावणवेगमर्दितम्।
पुनः परिष्वज्य शशिप्रभानना रुरोद सीता जनकात्मजा तदा॥', 'tatas tu taṃ patrarathaṃ mahītale nipātitaṃ rāvaṇavegamarditam
punaḥ pariṣvajya śaśiprabhānanā ruroda sītā janakātmajā tadā', null, 3049040)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 50 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-50-1', 1, 'Aranya Kanda, Sarga 50, Verse 1', 'तमल्पजीवितं भूमौ स्फुरन्तं राक्षसाधिपः।
ददर्श गृध्रं पतितं समीपे राघवाश्रमात्॥', 'tam alpajīvitaṃ bhūmau sphurantaṃ rākṣasādhipaḥ
dadarśa gṛdhraṃ patitaṃ samīpe rāghavāśramāt', null, 3050001),
('ramayana-3-50-2', 2, 'Aranya Kanda, Sarga 50, Verse 2', 'सा तु ताराधिपमुखी रावणेन समीक्ष्य तम्।
गृध्रराजं विनिहतं विललाप सुदुःखिता॥', 'sā tu tārādhipamukhī rāvaṇena samīkṣya tam
gṛdhrarājaṃ vinihataṃ vilalāpa suduḥkhitā', null, 3050002),
('ramayana-3-50-3', 3, 'Aranya Kanda, Sarga 50, Verse 3', 'निमित्तं लक्षणज्ञानं शकुनिस्वरदर्शनम्।
अवश्यं सुखदुःखेषु नराणां प्रतिदृश्यते॥', 'nimittaṃ lakṣaṇajñānaṃ śakunisvaradarśanam
avaśyaṃ sukhaduḥkheṣu narāṇāṃ pratidṛśyate', null, 3050003),
('ramayana-3-50-4', 4, 'Aranya Kanda, Sarga 50, Verse 4', 'न नूनं राम जानासि महद्व्यसनमात्मजः।
धावन्ति नूनं काकुत्स्थ मदर्थं मृगपक्षिणः॥', 'na nūnaṃ rāma jānāsi mahad vyasanam ātmajaḥ
dhāvanti nūnaṃ kākutstha madarthaṃ mṛgapakṣiṇaḥ', null, 3050004),
('ramayana-3-50-5', 5, 'Aranya Kanda, Sarga 50, Verse 5', 'त्राहि मामद्य काकुत्स्थ लक्ष्मणेति वराङ्गना।
सुसंत्रस्ता समाक्रन्दच्छृण्वतां तु यथान्तिके॥', 'trāhi mām adya kākutstha lakṣmaṇeti varāṅganā
susaṃtrastā samākrandac chṛṇvatāṃ tu yathāntike', null, 3050005),
('ramayana-3-50-6', 6, 'Aranya Kanda, Sarga 50, Verse 6', 'तां क्लिष्टमाल्याभरणां विलपन्तीमनाथवत्।
अभ्यधावत वैदेहीं रावणो राक्षसाधिपः॥', 'tāṃ kliṣṭamālyābharaṇāṃ vilapantīm anāthavat
abhyadhāvata vaidehīṃ rāvaṇo rākṣasādhipaḥ', null, 3050006),
('ramayana-3-50-7', 7, 'Aranya Kanda, Sarga 50, Verse 7', 'तां लतामिव वेष्टन्तीमालिङ्गन्तीं महाद्रुमान्।
मुञ्च मुञ्चेति बहुशः प्रवदन्राक्षसाधिपः॥', 'tāṃ latām iva veṣṭantīm āliṅgantīṃ mahādrumān
muñca muñceti bahuśaḥ pravadan rākṣasādhipaḥ', null, 3050007),
('ramayana-3-50-8', 8, 'Aranya Kanda, Sarga 50, Verse 8', 'क्रोशन्तीं राम रामेति रामेण रहितां वने।
जीवितान्ताय केशेषु जग्राहान्तकसंनिभः॥', 'krośantīṃ rāma rāmeti rāmeṇa rahitāṃ vane
jīvitāntāya keśeṣu jagrāhāntakasaṃnibhaḥ', null, 3050008),
('ramayana-3-50-9', 9, 'Aranya Kanda, Sarga 50, Verse 9', 'प्रधर्षितायां वैदेह्यां बभूव सचराचरम्।
जगत्सर्वममर्यादं तमसान्धेन संवृतम्॥', 'pradharṣitāyāṃ vaidehyāṃ babhūva sacarācaram
jagat sarvam amaryādaṃ tamasāndhena saṃvṛtam', null, 3050009),
('ramayana-3-50-10', 10, 'Aranya Kanda, Sarga 50, Verse 10', 'दृष्ट्वा सीतां परामृष्टां दीनां दिव्येन चक्षुषा।
कृतं कार्यमिति श्रीमान्व्याजहार पितामहः॥', 'dṛṣṭvā sītāṃ parāmṛṣṭāṃ dīnāṃ divyena cakṣuṣā
kṛtaṃ kāryam iti śrīmān vyājahāra pitāmahaḥ', null, 3050010),
('ramayana-3-50-11', 11, 'Aranya Kanda, Sarga 50, Verse 11', 'प्रहृष्टा व्यथिताश्चासन्सर्वे ते परमर्षयः।
दृष्ट्वा सीतां परामृष्टां दण्डकारण्यवासिनः॥', 'prahṛṣṭā vyathitāś cāsan sarve te paramarṣayaḥ
dṛṣṭvā sītāṃ parāmṛṣṭāṃ daṇḍakāraṇyavāsinaḥ', null, 3050011),
('ramayana-3-50-12', 12, 'Aranya Kanda, Sarga 50, Verse 12', 'स तु तां राम रामेति रुदन्तीं लक्ष्मणेति च।
जगामाकाशमादाय रावणो राक्षसाधिपः॥', 'sa tu tāṃ rāma rāmeti rudantīṃ lakṣmaṇeti ca
jagāmākāśam ādāya rāvaṇo rākṣasādhipaḥ', null, 3050012),
('ramayana-3-50-13', 13, 'Aranya Kanda, Sarga 50, Verse 13', 'तप्ताभरणसर्वाङ्गी पीतकौशेयवासनी।
रराज राजपुत्री तु विद्युत्सौदामनी यथा॥', 'taptābharaṇasarvāṅgī pītakauśeyavāsanī
rarāja rājaputrī tu vidyut saudāmanī yathā', null, 3050013),
('ramayana-3-50-14', 14, 'Aranya Kanda, Sarga 50, Verse 14', 'उद्धूतेन च वस्त्रेण तस्याः पीतेन रावणः।
अधिकं परिबभ्राज गिरिर्दीप इवाग्निना॥', 'uddhūtena ca vastreṇa tasyāḥ pītena rāvaṇaḥ
adhikaṃ paribabhrāja girir dīpa ivāgninā', null, 3050014),
('ramayana-3-50-15', 15, 'Aranya Kanda, Sarga 50, Verse 15', 'तस्याः परमकल्याण्यास्ताम्राणि सुरभीणि च।
पद्मपत्राणि वैदेह्या अभ्यकीर्यन्त रावणम्॥', 'tasyāḥ paramakalyāṇyās tāmrāṇi surabhīṇi ca
padmapatrāṇi vaidehyā abhyakīryanta rāvaṇam', null, 3050015),
('ramayana-3-50-16', 16, 'Aranya Kanda, Sarga 50, Verse 16', 'तस्याः कौशेयमुद्धूतमाकाशे कनकप्रभम्।
बभौ चादित्यरागेण ताम्रमभ्रमिवातपे॥', 'tasyāḥ kauśeyam uddhūtam ākāśe kanakaprabham
babhau cādityarāgeṇa tāmram abhram ivātape', null, 3050016),
('ramayana-3-50-17', 17, 'Aranya Kanda, Sarga 50, Verse 17', 'तस्यास्तद्विमलं वक्त्रमाकाशे रावणाङ्कगम्।
न रराज विना रामं विनालमिव पङ्कजम्॥', 'tasyās tad vimalaṃ vaktram ākāśe rāvaṇāṅkagam
na rarāja vinā rāmaṃ vinālam iva paṅkajam', null, 3050017),
('ramayana-3-50-18', 18, 'Aranya Kanda, Sarga 50, Verse 18', 'बभूव जलदं नीलं भित्त्वा चन्द्र इवोदितः।
सुललाटं सुकेशान्तं पद्मगर्भाभमव्रणम्।
शुक्लैः सुविमलैर्दन्तैः प्रभावद्भिरलंकृतम्॥', 'babhūva jaladaṃ nīlaṃ bhittvā candra ivoditaḥ
sulalāṭaṃ sukeśāntaṃ padmagarbhābham avraṇam
śuklaiḥ suvimalair dantaiḥ prabhāvadbhir alaṃkṛtam', null, 3050018),
('ramayana-3-50-19', 19, 'Aranya Kanda, Sarga 50, Verse 19', 'रुदितं व्यपमृष्टास्त्रं चन्द्रवत्प्रियदर्शनम्।
सुनासं चारुताम्रौष्ठमाकाषे हाटकप्रभम्॥', 'ruditaṃ vyapamṛṣṭāstraṃ candravat priyadarśanam
sunāsaṃ cārutāmrauṣṭham ākāṣe hāṭakaprabham', null, 3050019),
('ramayana-3-50-20', 20, 'Aranya Kanda, Sarga 50, Verse 20', 'राक्षसेन्द्रसमाधूतं तस्यास्तद्वचनं शुभम्।
शुशुभे न विना रामं दिवा चन्द्र इवोदितः॥', 'rākṣasendrasamādhūtaṃ tasyās tad vacanaṃ śubham
śuśubhe na vinā rāmaṃ divā candra ivoditaḥ', null, 3050020),
('ramayana-3-50-21', 21, 'Aranya Kanda, Sarga 50, Verse 21', 'सा हेमवर्णा नीलाङ्गं मैथिली राक्षसाधिपम्।
शुशुभे काञ्चनी काञ्ची नीलं मणिमिवाश्रिता॥', 'sā hemavarṇā nīlāṅgaṃ maithilī rākṣasādhipam
śuśubhe kāñcanī kāñcī nīlaṃ maṇim ivāśritā', null, 3050021),
('ramayana-3-50-22', 22, 'Aranya Kanda, Sarga 50, Verse 22', 'सा पद्मगौरी हेमाभा रावणं जनकात्मजा।
विद्युद्घनमिवाविश्य शुशुभे तप्तभूषणा॥', 'sā padmagaurī hemābhā rāvaṇaṃ janakātmajā
vidyudghanam ivāviśya śuśubhe taptabhūṣaṇā', null, 3050022),
('ramayana-3-50-23', 23, 'Aranya Kanda, Sarga 50, Verse 23', 'तस्या भूषणघोषेण वैदेह्या राक्षसाधिपः।
बभूव विमलो नीलः सघोष इव तोयदः॥', 'tasyā bhūṣaṇaghoṣeṇa vaidehyā rākṣasādhipaḥ
babhūva vimalo nīlaḥ saghoṣa iva toyadaḥ', null, 3050023),
('ramayana-3-50-24', 24, 'Aranya Kanda, Sarga 50, Verse 24', 'उत्तमाङ्गच्युता तस्याः पुष्पवृष्टिः समन्ततः।
सीताया ह्रियमाणायाः पपात धरणीतले॥', 'uttamāṅgacyutā tasyāḥ puṣpavṛṣṭiḥ samantataḥ
sītāyā hriyamāṇāyāḥ papāta dharaṇītale', null, 3050024),
('ramayana-3-50-25', 25, 'Aranya Kanda, Sarga 50, Verse 25', 'सा तु रावणवेगेन पुष्पवृष्टिः समन्ततः।
समाधूता दशग्रीवं पुनरेवाभ्यवर्तत॥', 'sā tu rāvaṇavegena puṣpavṛṣṭiḥ samantataḥ
samādhūtā daśagrīvaṃ punar evābhyavartata', null, 3050025),
('ramayana-3-50-26', 26, 'Aranya Kanda, Sarga 50, Verse 26', 'अभ्यवर्तत पुष्पाणां धारा वैश्रवणानुजम्।
नक्षत्रमालाविमला मेरुं नगमिवोत्तमम्॥', 'abhyavartata puṣpāṇāṃ dhārā vaiśravaṇānujam
nakṣatramālāvimalā meruṃ nagam ivottamam', null, 3050026),
('ramayana-3-50-27', 27, 'Aranya Kanda, Sarga 50, Verse 27', 'चरणान्नूपुरं भ्रष्टं वैदेह्या रत्नभूषितम्।
विद्युन्मण्डलसंकाशं पपात मधुरस्वनम्॥', 'caraṇān nūpuraṃ bhraṣṭaṃ vaidehyā ratnabhūṣitam
vidyunmaṇḍalasaṃkāśaṃ papāta madhurasvanam', null, 3050027),
('ramayana-3-50-28', 28, 'Aranya Kanda, Sarga 50, Verse 28', 'तरुप्रवालरक्ता सा नीलाङ्गं राक्षसेश्वरम्।
प्राशोभयत वैदेही गजं कष्येव काञ्चनी॥', 'tarupravālaraktā sā nīlāṅgaṃ rākṣaseśvaram
prāśobhayata vaidehī gajaṃ kaṣyeva kāñcanī', null, 3050028),
('ramayana-3-50-29', 29, 'Aranya Kanda, Sarga 50, Verse 29', 'तां महोल्कामिवाकाशे दीप्यमानां स्वतेजसा।
जहाराकाशमाविश्य सीतां वैश्रवणानुजः॥', 'tāṃ maholkām ivākāśe dīpyamānāṃ svatejasā
jahārākāśam āviśya sītāṃ vaiśravaṇānujaḥ', null, 3050029),
('ramayana-3-50-30', 30, 'Aranya Kanda, Sarga 50, Verse 30', 'तस्यास्तान्यग्निवर्णानि भूषणानि महीतले।
सघोषाण्यवकीर्यन्त क्षीणास्तारा इवाम्बरात्॥', 'tasyās tāny agnivarṇāni bhūṣaṇāni mahītale
saghoṣāṇy avakīryanta kṣīṇās tārā ivāmbarāt', null, 3050030),
('ramayana-3-50-31', 31, 'Aranya Kanda, Sarga 50, Verse 31', 'तस्याः स्तनान्तराद्भ्रष्टो हारस्ताराधिपद्युतिः।
वैदेह्या निपतन्भाति गङ्गेव गगनाच्च्युता॥', 'tasyāḥ stanāntarād bhraṣṭo hāras tārādhipadyutiḥ
vaidehyā nipatan bhāti gaṅgeva gaganāc cyutā', null, 3050031),
('ramayana-3-50-32', 32, 'Aranya Kanda, Sarga 50, Verse 32', 'उत्पात वाताभिहता नानाद्विज गणायुताः।
मा भैरिति विधूताग्रा व्याजह्रुरिव पादपाः॥', 'utpāta vātābhihatā nānādvija gaṇāyutāḥ
mā bhair iti vidhūtāgrā vyājahrur iva pādapāḥ', null, 3050032),
('ramayana-3-50-33', 33, 'Aranya Kanda, Sarga 50, Verse 33', 'नलिन्यो ध्वस्तकमलास्त्रस्तमीनजले चराः।
सखीमिव गतोत्साहां शोचन्तीव स्म मैथिलीम्॥', 'nalinyo dhvastakamalās trastamīnajale carāḥ
sakhīm iva gatotsāhāṃ śocantīva sma maithilīm', null, 3050033),
('ramayana-3-50-34', 34, 'Aranya Kanda, Sarga 50, Verse 34', 'समन्तादभिसंपत्य सिंहव्याघ्रमृगद्विजाः।
अन्वधावंस्तदा रोषात्सीताच्छायानुगामिनः॥', 'samantād abhisaṃpatya siṃhavyāghramṛgadvijāḥ
anvadhāvaṃs tadā roṣāt sītācchāyānugāminaḥ', null, 3050034),
('ramayana-3-50-35', 35, 'Aranya Kanda, Sarga 50, Verse 35', 'जलप्रपातास्रमुखाः शृङ्गैरुच्छ्रितबाहवः।
सीतायां ह्रियमाणायां विक्रोशन्तीव पर्वताः॥', 'jalaprapātāsramukhāḥ śṛṅgair ucchritabāhavaḥ
sītāyāṃ hriyamāṇāyāṃ vikrośantīva parvatāḥ', null, 3050035),
('ramayana-3-50-36', 36, 'Aranya Kanda, Sarga 50, Verse 36', 'ह्रियमाणां तु वैदेहीं दृष्ट्वा दीनो दिवाकरः।
प्रविध्वस्तप्रभः श्रीमानासीत्पाण्डुरमण्डलः॥', 'hriyamāṇāṃ tu vaidehīṃ dṛṣṭvā dīno divākaraḥ
pravidhvastaprabhaḥ śrīmān āsīt pāṇḍuramaṇḍalaḥ', null, 3050036),
('ramayana-3-50-37', 37, 'Aranya Kanda, Sarga 50, Verse 37', 'नास्ति धर्मः कुतः सत्यं नार्जवं नानृशंसता।
यत्र रामस्य वैदेहीं भार्यां हरति रावणः॥', 'nāsti dharmaḥ kutaḥ satyaṃ nārjavaṃ nānṛśaṃsatā
yatra rāmasya vaidehīṃ bhāryāṃ harati rāvaṇaḥ', null, 3050037),
('ramayana-3-50-38', 38, 'Aranya Kanda, Sarga 50, Verse 38', 'इति सर्वाणि भूतानि गणशः पर्यदेवयन्।
वित्रस्तका दीनमुखा रुरुदुर्मृगपोतकाः॥', 'iti sarvāṇi bhūtāni gaṇaśaḥ paryadevayan
vitrastakā dīnamukhā rurudur mṛgapotakāḥ', null, 3050038),
('ramayana-3-50-39', 39, 'Aranya Kanda, Sarga 50, Verse 39', 'उद्वीक्ष्योद्वीक्ष्य नयनैरास्रपाताविलेक्षणाः।
सुप्रवेपितगात्राश्च बभूवुर्वनदेवताः॥', 'udvīkṣyodvīkṣya nayanair āsrapātāvilekṣaṇāḥ
supravepitagātrāś ca babhūvur vanadevatāḥ', null, 3050039),
('ramayana-3-50-40', 40, 'Aranya Kanda, Sarga 50, Verse 40', 'विक्रोशन्तीं दृढं सीतां दृष्ट्वा दुःखं तथा गताम्।
तां तु लक्ष्मण रामेति क्रोशन्तीं मधुरस्वराम्॥', 'vikrośantīṃ dṛḍhaṃ sītāṃ dṛṣṭvā duḥkhaṃ tathā gatām
tāṃ tu lakṣmaṇa rāmeti krośantīṃ madhurasvarām', null, 3050040),
('ramayana-3-50-41', 41, 'Aranya Kanda, Sarga 50, Verse 41', 'अवेक्षमाणां बहुषो वैदेहीं धरणीतलम्।
स तामाकुलकेशान्तां विप्रमृष्टविशेषकाम्।
जहारात्मविनाशाय दशग्रीवो मनस्विनाम्॥', 'avekṣamāṇāṃ bahuṣo vaidehīṃ dharaṇītalam
sa tām ākulakeśāntāṃ vipramṛṣṭaviśeṣakām
jahārātmavināśāya daśagrīvo manasvinām', null, 3050041),
('ramayana-3-50-42', 42, 'Aranya Kanda, Sarga 50, Verse 42', 'ततस्तु सा चारुदती शुचिस्मिता विनाकृता बन्धुजनेन मैथिली।
अपश्यती राघवलक्ष्मणावुभौ विवर्णवक्त्रा भयभारपीडिता॥', 'tatas tu sā cārudatī śucismitā vinākṛtā bandhujanena maithilī
apaśyatī rāghavalakṣmaṇāv ubhau vivarṇavaktrā bhayabhārapīḍitā', null, 3050042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 51 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-51-1', 1, 'Aranya Kanda, Sarga 51, Verse 1', 'खमुत्पतन्तं तं दृष्ट्वा मैथिली जनकात्मजा।
दुःखिता परमोद्विग्ना भये महति वर्तिनी॥', 'kham utpatantaṃ taṃ dṛṣṭvā maithilī janakātmajā
duḥkhitā paramodvignā bhaye mahati vartinī', null, 3051001),
('ramayana-3-51-2', 2, 'Aranya Kanda, Sarga 51, Verse 2', 'रोषरोदनताम्राक्षी भीमाक्षं राक्षसाधिपम्।
रुदती करुणं सीता ह्रियमाणेदमब्रवीत्॥', 'roṣarodanatāmrākṣī bhīmākṣaṃ rākṣasādhipam
rudatī karuṇaṃ sītā hriyamāṇedam abravīt', null, 3051002),
('ramayana-3-51-3', 3, 'Aranya Kanda, Sarga 51, Verse 3', 'न व्यपत्रपसे नीच कर्मणानेन रावण।
ज्ञात्वा विरहितां यो मां चोरयित्वा पलायसे॥', 'na vyapatrapase nīca karmaṇānena rāvaṇa
jñātvā virahitāṃ yo māṃ corayitvā palāyase', null, 3051003),
('ramayana-3-51-4', 4, 'Aranya Kanda, Sarga 51, Verse 4', 'त्वयैव नूनं दुष्टात्मन्भीरुणा हर्तुमिच्छता।
ममापवाहितो भर्ता मृगरूपेण मायया।
यो हि मामुद्यतस्त्रातुं सोऽप्ययं विनिपातितः॥', 'tvayaiva nūnaṃ duṣṭātman bhīruṇā hartum icchatā
mamāpavāhito bhartā mṛgarūpeṇa māyayā
yo hi mām udyatas trātuṃ so ''py ayaṃ vinipātitaḥ', null, 3051004),
('ramayana-3-51-5', 5, 'Aranya Kanda, Sarga 51, Verse 5', 'परमं खलु ते वीर्यं दृश्यते राक्षसाधम।
विश्राव्य नामधेयं हि युद्धे नास्ति जिता त्वया॥', 'paramaṃ khalu te vīryaṃ dṛśyate rākṣasādhama
viśrāvya nāmadheyaṃ hi yuddhe nāsti jitā tvayā', null, 3051005),
('ramayana-3-51-6', 6, 'Aranya Kanda, Sarga 51, Verse 6', 'ईदृशं गर्हितं कर्म कथं कृत्वा न लज्जसे।
स्त्रियाश्च हरणं नीच रहिते च परस्य च॥', 'īdṛśaṃ garhitaṃ karma kathaṃ kṛtvā na lajjase
striyāś ca haraṇaṃ nīca rahite ca parasya ca', null, 3051006),
('ramayana-3-51-7', 7, 'Aranya Kanda, Sarga 51, Verse 7', 'कथयिष्यन्ति लोकेषु पुरुषाः कर्म कुत्सितम्।
सुनृशंसमधर्मिष्ठं तव शौण्डीर्यमानिनः॥', 'kathayiṣyanti lokeṣu puruṣāḥ karma kutsitam
sunṛśaṃsam adharmiṣṭhaṃ tava śauṇḍīryamāninaḥ', null, 3051007),
('ramayana-3-51-8', 8, 'Aranya Kanda, Sarga 51, Verse 8', 'धिक्ते शौर्यं च सत्त्वं च यत्त्वया कथितं तदा।
कुलाक्रोशकरं लोके धिक्ते चारित्रमीदृशम्॥', 'dhik te śauryaṃ ca sattvaṃ ca yat tvayā kathitaṃ tadā
kulākrośakaraṃ loke dhik te cāritram īdṛśam', null, 3051008),
('ramayana-3-51-9', 9, 'Aranya Kanda, Sarga 51, Verse 9', 'किं शक्यं कर्तुमेवं हि यज्जवेनैव धावसि।
मुहूर्तमपि तिष्ठस्व न जीवन्प्रतियास्यसि॥', 'kiṃ śakyaṃ kartum evaṃ hi yaj javenaiva dhāvasi
muhūrtam api tiṣṭhasva na jīvan pratiyāsyasi', null, 3051009),
('ramayana-3-51-10', 10, 'Aranya Kanda, Sarga 51, Verse 10', 'न हि चक्षुःपथं प्राप्य तयोः पार्थिवपुत्रयोः।
ससैन्योऽपि समर्तःस्त्वं मुहूर्तमपि जीवितुम्॥', 'na hi cakṣuḥpathaṃ prāpya tayoḥ pārthivaputrayoḥ
sasainyo ''pi samartaḥs tvaṃ muhūrtam api jīvitum', null, 3051010),
('ramayana-3-51-11', 11, 'Aranya Kanda, Sarga 51, Verse 11', 'न त्वं तयोः शरस्पर्शं सोढुं शक्तः कथं चन।
वने प्रज्वलितस्येव स्पर्शमग्नेर्विहंगमः॥', 'na tvaṃ tayoḥ śarasparśaṃ soḍhuṃ śaktaḥ kathaṃ cana
vane prajvalitasyeva sparśam agner vihaṃgamaḥ', null, 3051011),
('ramayana-3-51-12', 12, 'Aranya Kanda, Sarga 51, Verse 12', 'साधु कृत्वात्मनः पथ्यं साधु मां मुञ्च रावण।
मत्प्रधर्षणरुष्टो हि भ्रात्रा सह पतिर्मम।
विधास्यति विनाशाय त्वं मां यदि न मुञ्चसि॥', 'sādhu kṛtvātmanaḥ pathyaṃ sādhu māṃ muñca rāvaṇa
matpradharṣaṇaruṣṭo hi bhrātrā saha patir mama
vidhāsyati vināśāya tvaṃ māṃ yadi na muñcasi', null, 3051012),
('ramayana-3-51-13', 13, 'Aranya Kanda, Sarga 51, Verse 13', 'येन त्वं व्यवसायेन बलान्मां हर्तुमिच्छसि।
व्यवसायः स ते नीच भविष्यति निरर्थकः॥', 'yena tvaṃ vyavasāyena balān māṃ hartum icchasi
vyavasāyaḥ sa te nīca bhaviṣyati nirarthakaḥ', null, 3051013),
('ramayana-3-51-14', 14, 'Aranya Kanda, Sarga 51, Verse 14', 'न ह्यहं तमपश्यन्ती भर्तारं विबुधोपमम्।
उत्सहे शत्रुवशगा प्राणान्धारयितुं चिरम्॥', 'na hy ahaṃ tam apaśyantī bhartāraṃ vibudhopamam
utsahe śatruvaśagā prāṇān dhārayituṃ ciram', null, 3051014),
('ramayana-3-51-15', 15, 'Aranya Kanda, Sarga 51, Verse 15', 'न नूनं चात्मनः श्रेयः पथ्यं वा समवेक्षसे।
मृत्युकाले यथा मर्त्यो विपरीतानि सेवते॥', 'na nūnaṃ cātmanaḥ śreyaḥ pathyaṃ vā samavekṣase
mṛtyukāle yathā martyo viparītāni sevate', null, 3051015),
('ramayana-3-51-16', 16, 'Aranya Kanda, Sarga 51, Verse 16', 'मुमूर्षूणां हि सर्वेषां यत्पथ्यं तन्न रोचते।
पश्यामीव हि कण्ठे त्वां कालपाशावपाशितम्॥', 'mumūrṣūṇāṃ hi sarveṣāṃ yat pathyaṃ tan na rocate
paśyāmīva hi kaṇṭhe tvāṃ kālapāśāvapāśitam', null, 3051016),
('ramayana-3-51-17', 17, 'Aranya Kanda, Sarga 51, Verse 17', 'यथा चास्मिन्भयस्थाने न बिभेषे दशानन।
व्यक्तं हिरण्मयान्हि त्वं संपश्यसि महीरुहान्॥', 'yathā cāsmin bhayasthāne na bibheṣe daśānana
vyaktaṃ hiraṇmayān hi tvaṃ saṃpaśyasi mahīruhān', null, 3051017),
('ramayana-3-51-18', 18, 'Aranya Kanda, Sarga 51, Verse 18', 'नदीं वैरतणीं घोरां रुधिरौघनिवाहिनीम्।
खड्गपत्रवनं चैव भीमं पश्यसि रावण॥', 'nadīṃ vairataṇīṃ ghorāṃ rudhiraughanivāhinīm
khaḍgapatravanaṃ caiva bhīmaṃ paśyasi rāvaṇa', null, 3051018),
('ramayana-3-51-19', 19, 'Aranya Kanda, Sarga 51, Verse 19', 'तप्तकाञ्चनपुष्पां च वैदूर्यप्रवरच्छदाम्।
द्रक्ष्यसे शाल्मलीं तीक्ष्णामायसैः कण्टकैश्चिताम्॥', 'taptakāñcanapuṣpāṃ ca vaidūryapravaracchadām
drakṣyase śālmalīṃ tīkṣṇām āyasaiḥ kaṇṭakaiś citām', null, 3051019),
('ramayana-3-51-20', 20, 'Aranya Kanda, Sarga 51, Verse 20', 'न हि त्वमीदृशं कृत्वा तस्यालीकं महात्मनः।
धारितुं शक्ष्यसि चिरं विषं पीत्वेव निर्घृणः॥', 'na hi tvam īdṛśaṃ kṛtvā tasyālīkaṃ mahātmanaḥ
dhārituṃ śakṣyasi ciraṃ viṣaṃ pītveva nirghṛṇaḥ', null, 3051020),
('ramayana-3-51-21', 21, 'Aranya Kanda, Sarga 51, Verse 21', 'बद्धस्त्वं कालपाशेन दुर्निवारेण रावण।
क्व गतो लप्स्यसे शर्म भर्तुर्मम महात्मनः॥', 'baddhas tvaṃ kālapāśena durnivāreṇa rāvaṇa
kva gato lapsyase śarma bhartur mama mahātmanaḥ', null, 3051021),
('ramayana-3-51-22', 22, 'Aranya Kanda, Sarga 51, Verse 22', 'निमेषान्तरमात्रेण विना भ्रातरमाहवे।
राक्षसा निहता येन सहस्राणि चतुर्दश॥', 'nimeṣāntaramātreṇa vinā bhrātaram āhave
rākṣasā nihatā yena sahasrāṇi caturdaśa', null, 3051022),
('ramayana-3-51-23', 23, 'Aranya Kanda, Sarga 51, Verse 23', 'स कथं राघवो वीरः सर्वास्त्रकुशलो बली।
न त्वां हन्याच्छरैस्तीक्ष्णैरिष्टभार्यापहारिणम्॥', 'sa kathaṃ rāghavo vīraḥ sarvāstrakuśalo balī
na tvāṃ hanyāc charais tīkṣṇair iṣṭabhāryāpahāriṇam', null, 3051023),
('ramayana-3-51-24', 24, 'Aranya Kanda, Sarga 51, Verse 24', 'एतच्चान्यच्च परुषं वैदेही रावणाङ्कगा।
भयशोकसमाविष्टा करुणं विललाप ह॥', 'etac cānyac ca paruṣaṃ vaidehī rāvaṇāṅkagā
bhayaśokasamāviṣṭā karuṇaṃ vilalāpa ha', null, 3051024),
('ramayana-3-51-25', 25, 'Aranya Kanda, Sarga 51, Verse 25', 'तथा भृशार्तां बहु चैव भाषिणीं विललाप पूर्वं करुणं च भामिनीम्।
जहार पापस्तरुणीं विवेष्टतीं नृपात्मजामागतगात्रवेपथुम्॥', 'tathā bhṛśārtāṃ bahu caiva bhāṣiṇīṃ vilalāpa pūrvaṃ karuṇaṃ ca bhāminīm
jahāra pāpas taruṇīṃ viveṣṭatīṃ nṛpātmajām āgatagātravepathum', null, 3051025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 52 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-52-1', 1, 'Aranya Kanda, Sarga 52, Verse 1', 'ह्रियमाणा तु वैदेही कं चिन्नाथमपश्यती।
ददर्श गिरिशृङ्गस्थान्पञ्चवानरपुंगवान्॥', 'hriyamāṇā tu vaidehī kaṃ cin nātham apaśyatī
dadarśa giriśṛṅgasthān pañcavānarapuṃgavān', null, 3052001),
('ramayana-3-52-2', 2, 'Aranya Kanda, Sarga 52, Verse 2', 'तेषां मध्ये विशालाक्षी कौशेयं कनकप्रभम्।
उत्तरीयं वरारोहा शुभान्याभरणानि च।
मुमोच यदि रामाय शंसेयुरिति मैथिली॥', 'teṣāṃ madhye viśālākṣī kauśeyaṃ kanakaprabham
uttarīyaṃ varārohā śubhāny ābharaṇāni ca
mumoca yadi rāmāya śaṃseyur iti maithilī', null, 3052002),
('ramayana-3-52-3', 3, 'Aranya Kanda, Sarga 52, Verse 3', 'वस्त्रमुत्सृज्य तन्मध्ये विनिक्षिप्तं सभूषणम्।
संभ्रमात्तु दशग्रीवस्तत्कर्म न च बुद्धिवान्॥', 'vastram utsṛjya tan madhye vinikṣiptaṃ sabhūṣaṇam
saṃbhramāt tu daśagrīvas tat karma na ca buddhivān', null, 3052003),
('ramayana-3-52-4', 4, 'Aranya Kanda, Sarga 52, Verse 4', 'पिङ्गाक्षास्तां विशालाक्षीं नेत्रैरनिमिषैरिव।
विक्रोशन्तीं तदा सीतां ददृशुर्वानरर्षभाः॥', 'piṅgākṣās tāṃ viśālākṣīṃ netrair animiṣair iva
vikrośantīṃ tadā sītāṃ dadṛśur vānararṣabhāḥ', null, 3052004),
('ramayana-3-52-5', 5, 'Aranya Kanda, Sarga 52, Verse 5', 'स च पम्पामतिक्रम्य लङ्कामभिमुखः पुरीम्।
जगाम रुदतीं गृह्य मैथिलीं राक्षसेश्वरः॥', 'sa ca pampām atikramya laṅkām abhimukhaḥ purīm
jagāma rudatīṃ gṛhya maithilīṃ rākṣaseśvaraḥ', null, 3052005),
('ramayana-3-52-6', 6, 'Aranya Kanda, Sarga 52, Verse 6', 'तां जहार सुसंहृष्टो रावणो मृत्युमात्मनः।
उत्सङ्गेनैव भुजगीं तीक्ष्णदंष्ट्रां महाविषाम्॥', 'tāṃ jahāra susaṃhṛṣṭo rāvaṇo mṛtyum ātmanaḥ
utsaṅgenaiva bhujagīṃ tīkṣṇadaṃṣṭrāṃ mahāviṣām', null, 3052006),
('ramayana-3-52-7', 7, 'Aranya Kanda, Sarga 52, Verse 7', 'वनानि सरितः शैलान्सरांसि च विहायसा।
स क्षिप्रं समतीयाय शरश्चापादिव च्युतः॥', 'vanāni saritaḥ śailān sarāṃsi ca vihāyasā
sa kṣipraṃ samatīyāya śaraś cāpād iva cyutaḥ', null, 3052007),
('ramayana-3-52-8', 8, 'Aranya Kanda, Sarga 52, Verse 8', 'तिमिनक्रनिकेतं तु वरुणालयमक्षयम्।
सरितां शरणं गत्वा समतीयाय सागरम्॥', 'timinakraniketaṃ tu varuṇālayam akṣayam
saritāṃ śaraṇaṃ gatvā samatīyāya sāgaram', null, 3052008),
('ramayana-3-52-9', 9, 'Aranya Kanda, Sarga 52, Verse 9', 'संभ्रमात्परिवृत्तोर्मी रुद्धमीनमहोरगः।
वैदेह्यां ह्रियमाणायां बभूव वरुणालयः॥', 'saṃbhramāt parivṛttormī ruddhamīnamahoragaḥ
vaidehyāṃ hriyamāṇāyāṃ babhūva varuṇālayaḥ', null, 3052009),
('ramayana-3-52-10', 10, 'Aranya Kanda, Sarga 52, Verse 10', 'अन्तरिक्षगता वाचः ससृजुश्चारणास्तदा।
एतदन्तो दशग्रीव इति सिद्धास्तदाब्रुवन्॥', 'antarikṣagatā vācaḥ sasṛjuś cāraṇās tadā
etad anto daśagrīva iti siddhās tadābruvan', null, 3052010),
('ramayana-3-52-11', 11, 'Aranya Kanda, Sarga 52, Verse 11', 'स तु सीतां विवेष्टन्तीमङ्केनादाय रावणः।
प्रविवेश पुरीं लङ्कां रूपिणीं मृत्युमात्मनः॥', 'sa tu sītāṃ viveṣṭantīm aṅkenādāya rāvaṇaḥ
praviveśa purīṃ laṅkāṃ rūpiṇīṃ mṛtyum ātmanaḥ', null, 3052011),
('ramayana-3-52-12', 12, 'Aranya Kanda, Sarga 52, Verse 12', 'सोऽभिगम्य पुरीं लङ्कां सुविभक्तमहापथाम्।
संरूढकक्ष्या बहुलं स्वमन्तःपुरमाविशत्॥', 'so ''bhigamya purīṃ laṅkāṃ suvibhaktamahāpathām
saṃrūḍhakakṣyā bahulaṃ svam antaḥpuram āviśat', null, 3052012),
('ramayana-3-52-13', 13, 'Aranya Kanda, Sarga 52, Verse 13', 'तत्र तामसितापाङ्गीं शोकमोहपरायणाम्।
निदधे रावणः सीतां मयो मायामिवासुरीम्॥', 'tatra tām asitāpāṅgīṃ śokamohaparāyaṇām
nidadhe rāvaṇaḥ sītāṃ mayo māyām ivāsurīm', null, 3052013),
('ramayana-3-52-14', 14, 'Aranya Kanda, Sarga 52, Verse 14', 'अब्रवीच्च दशग्रीवः पिशाचीर्घोरदर्शनाः।
यथा नैनां पुमान्स्त्री वा सीतां पश्यत्यसंमतः॥', 'abravīc ca daśagrīvaḥ piśācīr ghoradarśanāḥ
yathā naināṃ pumān strī vā sītāṃ paśyaty asaṃmataḥ', null, 3052014),
('ramayana-3-52-15', 15, 'Aranya Kanda, Sarga 52, Verse 15', 'मुक्तामणिसुवर्णानि वस्त्राण्याभरणानि च।
यद्यदिच्छेत्तदेवास्या देयं मच्छन्दतो यथा॥', 'muktāmaṇisuvarṇāni vastrāṇy ābharaṇāni ca
yad yad icchet tad evāsyā deyaṃ macchandato yathā', null, 3052015),
('ramayana-3-52-16', 16, 'Aranya Kanda, Sarga 52, Verse 16', 'या च वक्ष्यति वैदेहीं वचनं किं चिदप्रियम्।
अज्ञानाद्यदि वा ज्ञानान्न तस्या जीवितं प्रियम्॥', 'yā ca vakṣyati vaidehīṃ vacanaṃ kiṃ cid apriyam
ajñānād yadi vā jñānān na tasyā jīvitaṃ priyam', null, 3052016),
('ramayana-3-52-17', 17, 'Aranya Kanda, Sarga 52, Verse 17', 'तथोक्त्वा राक्षसीस्तास्तु राक्षसेन्द्रः प्रतापवान्।
निष्क्रम्यान्तःपुरात्तस्मात्किं कृत्यमिति चिन्तयन्।
ददर्शाष्टौ महावीर्यान्राक्षसान्पिशिताशनान्॥', 'tathoktvā rākṣasīs tās tu rākṣasendraḥ pratāpavān
niṣkramyāntaḥpurāt tasmāt kiṃ kṛtyam iti cintayan
dadarśāṣṭau mahāvīryān rākṣasān piśitāśanān', null, 3052017),
('ramayana-3-52-18', 18, 'Aranya Kanda, Sarga 52, Verse 18', 'स तान्दृष्ट्वा महावीर्यो वरदानेन मोहितः।
उवाचैतानिदं वाक्यं प्रशस्य बलवीर्यतः॥', 'sa tān dṛṣṭvā mahāvīryo varadānena mohitaḥ
uvācaitān idaṃ vākyaṃ praśasya balavīryataḥ', null, 3052018),
('ramayana-3-52-19', 19, 'Aranya Kanda, Sarga 52, Verse 19', 'नानाप्रहरणाः क्षिप्रमितो गच्छत सत्वराः।
जनस्थानं हतस्थानं भूतपूर्वं खरालयम्॥', 'nānāpraharaṇāḥ kṣipram ito gacchata satvarāḥ
janasthānaṃ hatasthānaṃ bhūtapūrvaṃ kharālayam', null, 3052019),
('ramayana-3-52-20', 20, 'Aranya Kanda, Sarga 52, Verse 20', 'तत्रोष्यतां जनस्थाने शून्ये निहतराक्षसे।
पौरुषं बलमाश्रित्य त्रासमुत्सृज्य दूरतः॥', 'tatroṣyatāṃ janasthāne śūnye nihatarākṣase
pauruṣaṃ balam āśritya trāsam utsṛjya dūrataḥ', null, 3052020),
('ramayana-3-52-21', 21, 'Aranya Kanda, Sarga 52, Verse 21', 'बलं हि सुमहद्यन्मे जनस्थाने निवेशितम्।
सदूषणखरं युद्धे हतं तद्रामसायकैः॥', 'balaṃ hi sumahad yan me janasthāne niveśitam
sadūṣaṇakharaṃ yuddhe hataṃ tad rāmasāyakaiḥ', null, 3052021),
('ramayana-3-52-22', 22, 'Aranya Kanda, Sarga 52, Verse 22', 'ततः क्रोधो ममापूर्वो धैर्यस्योपरि वर्धते।
वैरं च सुमहज्जातं रामं प्रति सुदारुणम्॥', 'tataḥ krodho mamāpūrvo dhairyasyopari vardhate
vairaṃ ca sumahaj jātaṃ rāmaṃ prati sudāruṇam', null, 3052022),
('ramayana-3-52-23', 23, 'Aranya Kanda, Sarga 52, Verse 23', 'निर्यातयितुमिच्छामि तच्च वैरमहं रिपोः।
न हि लप्स्याम्यहं निद्रामहत्वा संयुगे रिपुम्॥', 'niryātayitum icchāmi tac ca vairam ahaṃ ripoḥ
na hi lapsyāmy ahaṃ nidrām ahatvā saṃyuge ripum', null, 3052023),
('ramayana-3-52-24', 24, 'Aranya Kanda, Sarga 52, Verse 24', 'तं त्विदानीमहं हत्वा खरदूषणघातिनम्।
रामं शर्मोपलप्स्यामि धनं लब्ध्वेव निर्धनः॥', 'taṃ tv idānīm ahaṃ hatvā kharadūṣaṇaghātinam
rāmaṃ śarmopalapsyāmi dhanaṃ labdhveva nirdhanaḥ', null, 3052024),
('ramayana-3-52-25', 25, 'Aranya Kanda, Sarga 52, Verse 25', 'जनस्थाने वसद्भिस्तु भवद्भी राममाश्रिता।
प्रवृत्तिरुपनेतव्या किं करोतीति तत्त्वतः॥', 'janasthāne vasadbhis tu bhavadbhī rāmam āśritā
pravṛttir upanetavyā kiṃ karotīti tattvataḥ', null, 3052025),
('ramayana-3-52-26', 26, 'Aranya Kanda, Sarga 52, Verse 26', 'अप्रमादाच्च गन्तव्यं सर्वैरेव निशाचरैः।
कर्तव्यश्च सदा यत्नो राघवस्य वधं प्रति॥', 'apramādāc ca gantavyaṃ sarvair eva niśācaraiḥ
kartavyaś ca sadā yatno rāghavasya vadhaṃ prati', null, 3052026),
('ramayana-3-52-27', 27, 'Aranya Kanda, Sarga 52, Verse 27', 'युष्माकं हि बलज्ञोऽहं बहुशो रणमूर्धनि।
अतश्चास्मिञ्जनस्थाने मया यूयं नियोजिताः॥', 'yuṣmākaṃ hi balajño ''haṃ bahuśo raṇamūrdhani
ataś cāsmiñ janasthāne mayā yūyaṃ niyojitāḥ', null, 3052027),
('ramayana-3-52-28', 28, 'Aranya Kanda, Sarga 52, Verse 28', 'ततः प्रियं वाक्यमुपेत्य राक्षसा महार्थमष्टावभिवाद्य रावणम्।
विहाय लङ्कां सहिताः प्रतस्थिरे यतो जनस्थानमलक्ष्यदर्शनाः॥', 'tataḥ priyaṃ vākyam upetya rākṣasā mahārtham aṣṭāv abhivādya rāvaṇam
vihāya laṅkāṃ sahitāḥ pratasthire yato janasthānam alakṣyadarśanāḥ', null, 3052028),
('ramayana-3-52-29', 29, 'Aranya Kanda, Sarga 52, Verse 29', 'ततस्तु सीतामुपलभ्य रावणः सुसंप्रहृष्टः परिगृह्य मैथिलीम्।
प्रसज्य रामेण च वैरमुत्तमं बभूव मोहान्मुदितः स राक्षसः॥', 'tatas tu sītām upalabhya rāvaṇaḥ susaṃprahṛṣṭaḥ parigṛhya maithilīm
prasajya rāmeṇa ca vairam uttamaṃ babhūva mohān muditaḥ sa rākṣasaḥ', null, 3052029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 53 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-53-1', 1, 'Aranya Kanda, Sarga 53, Verse 1', 'संदिश्य राक्षसान्घोरान्रावणोऽष्टौ महाबलान्।
आत्मानं बुद्धिवैक्लव्यात्कृतकृत्यममन्यत॥', 'saṃdiśya rākṣasān ghorān rāvaṇo ''ṣṭau mahābalān
ātmānaṃ buddhivaiklavyāt kṛtakṛtyam amanyata', null, 3053001),
('ramayana-3-53-2', 2, 'Aranya Kanda, Sarga 53, Verse 2', 'स चिन्तयानो वैदेहीं कामबाणसमर्पितः।
प्रविवेश गृहं रम्यं सीतां द्रष्टुमभित्वरन्॥', 'sa cintayāno vaidehīṃ kāmabāṇasamarpitaḥ
praviveśa gṛhaṃ ramyaṃ sītāṃ draṣṭum abhitvaran', null, 3053002),
('ramayana-3-53-3', 3, 'Aranya Kanda, Sarga 53, Verse 3', 'स प्रविश्य तु तद्वेश्म रावणो राक्षसाधिपः।
अपश्यद्राक्षसीमध्ये सीतां शोकपरायणम्॥', 'sa praviśya tu tadveśma rāvaṇo rākṣasādhipaḥ
apaśyad rākṣasīmadhye sītāṃ śokaparāyaṇam', null, 3053003),
('ramayana-3-53-4', 4, 'Aranya Kanda, Sarga 53, Verse 4', 'अश्रुपूर्णमुखीं दीनां शोकभारावपीडिताम्।
वायुवेगैरिवाक्रान्तां मज्जन्तीं नावमर्णवे॥', 'aśrupūrṇamukhīṃ dīnāṃ śokabhārāvapīḍitām
vāyuvegair ivākrāntāṃ majjantīṃ nāvam arṇave', null, 3053004),
('ramayana-3-53-5', 5, 'Aranya Kanda, Sarga 53, Verse 5', 'मृगयूथपरिभ्रष्टां मृगीं श्वभिरिवावृताम्।
अधोमुखमुखीं दीनामभ्येत्य च निशाचरः॥', 'mṛgayūthaparibhraṣṭāṃ mṛgīṃ śvabhir ivāvṛtām
adhomukhamukhīṃ dīnām abhyetya ca niśācaraḥ', null, 3053005),
('ramayana-3-53-6', 6, 'Aranya Kanda, Sarga 53, Verse 6', 'तां तु शोकवशां दीनामवशां राक्षसाधिपः।
स बलाद्दर्शयामास गृहं देवगृहोपमम्॥', 'tāṃ tu śokavaśāṃ dīnām avaśāṃ rākṣasādhipaḥ
sa balād darśayām āsa gṛhaṃ devagṛhopamam', null, 3053006),
('ramayana-3-53-7', 7, 'Aranya Kanda, Sarga 53, Verse 7', 'हर्म्यप्रासादसंबधं स्त्रीसहस्रनिषेवितम्।
नानापक्षिगणैर्जुष्टं नानारत्नसमन्वितम्॥', 'harmyaprāsādasaṃbadhaṃ strīsahasraniṣevitam
nānāpakṣigaṇair juṣṭaṃ nānāratnasamanvitam', null, 3053007),
('ramayana-3-53-8', 8, 'Aranya Kanda, Sarga 53, Verse 8', 'काञ्चनैस्तापनीयैश्च स्फाटिकै राजतैस्तथा।
वज्रवैदूर्यचित्रैश्च स्तम्भैर्दृष्टिमनोहरैः॥', 'kāñcanais tāpanīyaiś ca sphāṭikai rājatais tathā
vajravaidūryacitraiś ca stambhair dṛṣṭimanoharaiḥ', null, 3053008),
('ramayana-3-53-9', 9, 'Aranya Kanda, Sarga 53, Verse 9', 'दिव्यदुन्दुभिनिर्ह्रादं तप्तकाञ्चनतोरणम्।
सोपानं काञ्चनं चित्रमारुरोह तया सह॥', 'divyadundubhinirhrādaṃ taptakāñcanatoraṇam
sopānaṃ kāñcanaṃ citram āruroha tayā saha', null, 3053009),
('ramayana-3-53-10', 10, 'Aranya Kanda, Sarga 53, Verse 10', 'दान्तका राजताश्चैव गवाक्षाः प्रियदर्शनाः।
हेमजालावृताश्चासंस्तत्र प्रासादपङ्क्तयः॥', 'dāntakā rājatāś caiva gavākṣāḥ priyadarśanāḥ
hemajālāvṛtāś cāsaṃs tatra prāsādapaṅktayaḥ', null, 3053010),
('ramayana-3-53-11', 11, 'Aranya Kanda, Sarga 53, Verse 11', 'सुधामणिविचित्राणि भूमिभागानि सर्वशः।
दशग्रीवः स्वभवने प्रादर्शयत मैथिलीम्॥', 'sudhāmaṇivicitrāṇi bhūmibhāgāni sarvaśaḥ
daśagrīvaḥ svabhavane prādarśayata maithilīm', null, 3053011),
('ramayana-3-53-12', 12, 'Aranya Kanda, Sarga 53, Verse 12', 'दीर्घिकाः पुष्करिण्यश्च नानापुष्पसमावृताः।
रावणो दर्शयामास सीतां शोकपरायणाम्॥', 'dīrghikāḥ puṣkariṇyaś ca nānāpuṣpasamāvṛtāḥ
rāvaṇo darśayām āsa sītāṃ śokaparāyaṇām', null, 3053012),
('ramayana-3-53-13', 13, 'Aranya Kanda, Sarga 53, Verse 13', 'दर्शयित्वा तु वैदेहीं कृत्स्नं तद्भवनोत्तमम्।
उवाच वाक्यं पापात्मा रावणो जनकात्मजाम्॥', 'darśayitvā tu vaidehīṃ kṛtsnaṃ tad bhavanottamam
uvāca vākyaṃ pāpātmā rāvaṇo janakātmajām', null, 3053013),
('ramayana-3-53-14', 14, 'Aranya Kanda, Sarga 53, Verse 14', 'दशराक्षसकोट्यश्च द्वाविंशतिरथापराः।
वर्जयित्वा जरा वृद्धान्बालांश्च रजनीचरान्॥', 'daśarākṣasakoṭyaś ca dvāviṃśatir athāparāḥ
varjayitvā jarā vṛddhān bālāṃś ca rajanīcarān', null, 3053014),
('ramayana-3-53-15', 15, 'Aranya Kanda, Sarga 53, Verse 15', 'तेषां प्रभुरहं सीते सर्वेषां भीमकर्मणाम्।
सहस्रमेकमेकस्य मम कार्यपुरःसरम्॥', 'teṣāṃ prabhur ahaṃ sīte sarveṣāṃ bhīmakarmaṇām
sahasram ekam ekasya mama kāryapuraḥsaram', null, 3053015),
('ramayana-3-53-16', 16, 'Aranya Kanda, Sarga 53, Verse 16', 'यदिदं राज्यतन्त्रं मे त्वयि सर्वं प्रतिष्ठितम्।
जीवितं च विशालाक्षि त्वं मे प्राणैर्गरीयसी॥', 'yad idaṃ rājyatantraṃ me tvayi sarvaṃ pratiṣṭhitam
jīvitaṃ ca viśālākṣi tvaṃ me prāṇair garīyasī', null, 3053016),
('ramayana-3-53-17', 17, 'Aranya Kanda, Sarga 53, Verse 17', 'बहूनां स्त्रीसहस्राणां मम योऽसौ परिग्रहः।
तासां त्वमीश्वरी सीते मम भार्या भव प्रिये॥', 'bahūnāṃ strīsahasrāṇāṃ mama yo ''sau parigrahaḥ
tāsāṃ tvam īśvarī sīte mama bhāryā bhava priye', null, 3053017),
('ramayana-3-53-18', 18, 'Aranya Kanda, Sarga 53, Verse 18', 'साधु किं तेऽन्यया बुद्ध्या रोचयस्व वचो मम।
भजस्व माभितप्तस्य प्रसादं कर्तुमर्हसि॥', 'sādhu kiṃ te ''nyayā buddhyā rocayasva vaco mama
bhajasva mābhitaptasya prasādaṃ kartum arhasi', null, 3053018),
('ramayana-3-53-19', 19, 'Aranya Kanda, Sarga 53, Verse 19', 'परिक्षिप्ता समुद्रेण लङ्केयं शतयोजना।
नेयं धर्षयितुं शक्या सेन्द्रैरपि सुरासुरैः॥', 'parikṣiptā samudreṇa laṅkeyaṃ śatayojanā
neyaṃ dharṣayituṃ śakyā sendrair api surāsuraiḥ', null, 3053019),
('ramayana-3-53-20', 20, 'Aranya Kanda, Sarga 53, Verse 20', 'न देवेषु न यक्षेषु न गन्धर्वेषु नर्षिषु।
अहं पश्यामि लोकेषु यो मे वीर्यसमो भवेत्॥', 'na deveṣu na yakṣeṣu na gandharveṣu narṣiṣu
ahaṃ paśyāmi lokeṣu yo me vīryasamo bhavet', null, 3053020),
('ramayana-3-53-21', 21, 'Aranya Kanda, Sarga 53, Verse 21', 'राज्यभ्रष्टेन दीनेन तापसेन गतायुषा।
किं करिष्यसि रामेण मानुषेणाल्पतेजसा॥', 'rājyabhraṣṭena dīnena tāpasena gatāyuṣā
kiṃ kariṣyasi rāmeṇa mānuṣeṇālpatejasā', null, 3053021),
('ramayana-3-53-22', 22, 'Aranya Kanda, Sarga 53, Verse 22', 'भजस्व सीते मामेव भर्ताहं सदृशस्तव।
यौवनं ह्यध्रुवं भीरु रमस्वेह मया सह॥', 'bhajasva sīte mām eva bhartāhaṃ sadṛśas tava
yauvanaṃ hy adhruvaṃ bhīru ramasveha mayā saha', null, 3053022),
('ramayana-3-53-23', 23, 'Aranya Kanda, Sarga 53, Verse 23', 'दर्शने मा कृथा बुद्धिं राघवस्य वरानने।
कास्य शक्तिरिहागन्तुमपि सीते मनोरथैः॥', 'darśane mā kṛthā buddhiṃ rāghavasya varānane
kāsya śaktir ihāgantum api sīte manorathaiḥ', null, 3053023),
('ramayana-3-53-24', 24, 'Aranya Kanda, Sarga 53, Verse 24', 'न शक्यो वायुराकाशे पाशैर्बद्धं महाजवः।
दीप्यमानस्य वाप्यग्नेर्ग्रहीतुं विमलां शिखाम्॥', 'na śakyo vāyur ākāśe pāśair baddhaṃ mahājavaḥ
dīpyamānasya vāpy agner grahītuṃ vimalāṃ śikhām', null, 3053024),
('ramayana-3-53-25', 25, 'Aranya Kanda, Sarga 53, Verse 25', 'त्रयाणामपि लोकानां न तं पश्यामि शोभने।
विक्रमेण नयेद्यस्त्वां मद्बाहुपरिपालिताम्॥', 'trayāṇām api lokānāṃ na taṃ paśyāmi śobhane
vikrameṇa nayed yas tvāṃ madbāhuparipālitām', null, 3053025),
('ramayana-3-53-26', 26, 'Aranya Kanda, Sarga 53, Verse 26', 'लङ्कायां सुमहद्राज्यमिदं त्वमनुपालय।
अभिषेकोदकक्लिन्ना तुष्टा च रमयस्व माम्॥', 'laṅkāyāṃ sumahad rājyam idaṃ tvam anupālaya
abhiṣekodakaklinnā tuṣṭā ca ramayasva mām', null, 3053026),
('ramayana-3-53-27', 27, 'Aranya Kanda, Sarga 53, Verse 27', 'दुष्कृतं यत्पुरा कर्म वनवासेन तद्गतम्।
यश्च ते सुकृतो धर्मस्तस्येह फलमाप्नुहि॥', 'duṣkṛtaṃ yat purā karma vanavāsena tad gatam
yaś ca te sukṛto dharmas tasyeha phalam āpnuhi', null, 3053027),
('ramayana-3-53-28', 28, 'Aranya Kanda, Sarga 53, Verse 28', 'इह सर्वाणि माल्यानि दिव्यगन्धानि मैथिलि।
भूषणानि च मुख्यानि तानि सेव मया सह॥', 'iha sarvāṇi mālyāni divyagandhāni maithili
bhūṣaṇāni ca mukhyāni tāni seva mayā saha', null, 3053028),
('ramayana-3-53-29', 29, 'Aranya Kanda, Sarga 53, Verse 29', 'पुष्पकं नाम सुश्रोणि भ्रातुर्वैश्रवणस्य मे।
विमानं रमणीयं च तद्विमानं मनोजवम्॥', 'puṣpakaṃ nāma suśroṇi bhrātur vaiśravaṇasya me
vimānaṃ ramaṇīyaṃ ca tad vimānaṃ manojavam', null, 3053029),
('ramayana-3-53-30', 30, 'Aranya Kanda, Sarga 53, Verse 30', 'तत्र सीते मया सार्धं विहरस्व यथासुखम्।
वदनं पद्मसंकाशं विमलं चारुदर्शनम्॥', 'tatra sīte mayā sārdhaṃ viharasva yathāsukham
vadanaṃ padmasaṃkāśaṃ vimalaṃ cārudarśanam', null, 3053030),
('ramayana-3-53-31', 31, 'Aranya Kanda, Sarga 53, Verse 31', 'शोकार्तं तु वरारोहे न भ्राजति वरानने।
अलं व्रीडेन वैदेहि धर्मलोप कृतेन ते॥', 'śokārtaṃ tu varārohe na bhrājati varānane
alaṃ vrīḍena vaidehi dharmalopa kṛtena te', null, 3053031),
('ramayana-3-53-32', 32, 'Aranya Kanda, Sarga 53, Verse 32', 'आर्षोऽयं दैवनिष्यन्दो यस्त्वामभिगमिष्यति।
एतौ पादौ मया स्निग्धौ शिरोभिः परिपीडितौ॥', 'ārṣo ''yaṃ daivaniṣyando yas tvām abhigamiṣyati
etau pādau mayā snigdhau śirobhiḥ paripīḍitau', null, 3053032),
('ramayana-3-53-33', 33, 'Aranya Kanda, Sarga 53, Verse 33', 'प्रसादं कुरु मे क्षिप्रं वश्यो दासोऽहमस्मि ते।
नेमाः शून्या मया वाचः शुष्यमाणेन भाषिताः॥', 'prasādaṃ kuru me kṣipraṃ vaśyo dāso ''ham asmi te
nemāḥ śūnyā mayā vācaḥ śuṣyamāṇena bhāṣitāḥ', null, 3053033),
('ramayana-3-53-34', 34, 'Aranya Kanda, Sarga 53, Verse 34', 'न चापि रावणः कां चिन्मूर्ध्ना स्त्रीं प्रणमेत ह।
एवमुक्त्वा दशग्रीवो मैथिलीं जनकात्मजाम्॥', 'na cāpi rāvaṇaḥ kāṃ cin mūrdhnā strīṃ praṇameta ha
evam uktvā daśagrīvo maithilīṃ janakātmajām', null, 3053034),
('ramayana-3-53-35', 35, 'Aranya Kanda, Sarga 53, Verse 35', 'कृतान्तवशमापन्नो ममेयमिति मन्यते॥', 'kṛtāntavaśam āpanno mameyam iti manyate', null, 3053035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 54 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-54-1', 1, 'Aranya Kanda, Sarga 54, Verse 1', 'सा तथोक्ता तु वैदेही निर्भया शोककर्षिता।
तृणमन्तरतः कृत्वा रावणं प्रत्यभाषत॥', 'sā tathoktā tu vaidehī nirbhayā śokakarṣitā
tṛṇam antarataḥ kṛtvā rāvaṇaṃ pratyabhāṣata', null, 3054001),
('ramayana-3-54-2', 2, 'Aranya Kanda, Sarga 54, Verse 2', 'राजा दशरथो नाम धर्मसेतुरिवाचलः।
सत्यसन्धः परिज्ञातो यस्य पुत्रः स राघवः॥', 'rājā daśaratho nāma dharmasetur ivācalaḥ
satyasandhaḥ parijñāto yasya putraḥ sa rāghavaḥ', null, 3054002),
('ramayana-3-54-3', 3, 'Aranya Kanda, Sarga 54, Verse 3', 'रामो नाम स धर्मात्मा त्रिषु लोकेषु विश्रुतः।
दीर्घबाहुर्विशालाक्षो दैवतं स पतिर्मम॥', 'rāmo nāma sa dharmātmā triṣu lokeṣu viśrutaḥ
dīrghabāhur viśālākṣo daivataṃ sa patir mama', null, 3054003),
('ramayana-3-54-4', 4, 'Aranya Kanda, Sarga 54, Verse 4', 'इक्ष्वाकूणां कुले जातः सिंहस्कन्धो महाद्युतिः।
लक्ष्मणेन सह भ्रात्रा यस्ते प्राणां हरिष्यति॥', 'ikṣvākūṇāṃ kule jātaḥ siṃhaskandho mahādyutiḥ
lakṣmaṇena saha bhrātrā yas te prāṇāṃ hariṣyati', null, 3054004),
('ramayana-3-54-5', 5, 'Aranya Kanda, Sarga 54, Verse 5', 'प्रत्यक्षं यद्यहं तस्य त्वया स्यां धर्षिता बलात्।
शयिता त्वं हतः संख्ये जनस्थाने यथा खरः॥', 'pratyakṣaṃ yady ahaṃ tasya tvayā syāṃ dharṣitā balāt
śayitā tvaṃ hataḥ saṃkhye janasthāne yathā kharaḥ', null, 3054005),
('ramayana-3-54-6', 6, 'Aranya Kanda, Sarga 54, Verse 6', 'य एते राक्षसाः प्रोक्ता घोररूपा महाबलाः।
राघवे निर्विषाः सर्वे सुपर्णे पन्नगा यथा॥', 'ya ete rākṣasāḥ proktā ghorarūpā mahābalāḥ
rāghave nirviṣāḥ sarve suparṇe pannagā yathā', null, 3054006),
('ramayana-3-54-7', 7, 'Aranya Kanda, Sarga 54, Verse 7', 'तस्य ज्याविप्रमुक्तास्ते शराः काञ्चनभूषणाः।
शरीरं विधमिष्यन्ति गङ्गाकूलमिवोर्मयः॥', 'tasya jyāvipramuktās te śarāḥ kāñcanabhūṣaṇāḥ
śarīraṃ vidhamiṣyanti gaṅgākūlam ivormayaḥ', null, 3054007),
('ramayana-3-54-8', 8, 'Aranya Kanda, Sarga 54, Verse 8', 'असुरैर्वा सुरैर्वा त्वं यद्यवधोऽसि रावण।
उत्पाद्य सुमहद्वैरं जीवंस्तस्य न मोक्ष्यसे॥', 'asurair vā surair vā tvaṃ yady avadho ''si rāvaṇa
utpādya sumahad vairaṃ jīvaṃs tasya na mokṣyase', null, 3054008),
('ramayana-3-54-9', 9, 'Aranya Kanda, Sarga 54, Verse 9', 'स ते जीवितशेषस्य राघवोऽन्तकरो बली।
पशोर्यूपगतस्येव जीवितं तव दुर्लभम्॥', 'sa te jīvitaśeṣasya rāghavo ''ntakaro balī
paśor yūpagatasyeva jīvitaṃ tava durlabham', null, 3054009),
('ramayana-3-54-10', 10, 'Aranya Kanda, Sarga 54, Verse 10', 'यदि पश्येत्स रामस्त्वां रोषदीप्तेन चक्षुषा।
रक्षस्त्वमद्य निर्दग्धो गच्छेः सद्यः पराभवम्॥', 'yadi paśyet sa rāmas tvāṃ roṣadīptena cakṣuṣā
rakṣas tvam adya nirdagdho gaccheḥ sadyaḥ parābhavam', null, 3054010),
('ramayana-3-54-11', 11, 'Aranya Kanda, Sarga 54, Verse 11', 'यश्चन्द्रं नभसो भूमौ पातयेन्नाशयेत वा।
सागरं शोषयेद्वापि स सीतां मोचयेदिह॥', 'yaś candraṃ nabhaso bhūmau pātayen nāśayeta vā
sāgaraṃ śoṣayed vāpi sa sītāṃ mocayed iha', null, 3054011),
('ramayana-3-54-12', 12, 'Aranya Kanda, Sarga 54, Verse 12', 'गतायुस्त्वं गतश्रीको गतसत्त्वो गतेन्द्रियः।
लङ्का वैधव्यसंयुक्ता त्वत्कृतेन भविष्यति॥', 'gatāyus tvaṃ gataśrīko gatasattvo gatendriyaḥ
laṅkā vaidhavyasaṃyuktā tvatkṛtena bhaviṣyati', null, 3054012),
('ramayana-3-54-13', 13, 'Aranya Kanda, Sarga 54, Verse 13', 'न ते पापमिदं कर्म सुखोदर्कं भविष्यति।
याहं नीता विना भावं पतिपार्श्वात्त्वया वनात्॥', 'na te pāpam idaṃ karma sukhodarkaṃ bhaviṣyati
yāhaṃ nītā vinā bhāvaṃ patipārśvāt tvayā vanāt', null, 3054013),
('ramayana-3-54-14', 14, 'Aranya Kanda, Sarga 54, Verse 14', 'स हि दैवतसंयुक्तो मम भर्ता महाद्युतिः।
निर्भयो वीर्यमाश्रित्य शून्ये वसति दण्डके॥', 'sa hi daivatasaṃyukto mama bhartā mahādyutiḥ
nirbhayo vīryam āśritya śūnye vasati daṇḍake', null, 3054014),
('ramayana-3-54-15', 15, 'Aranya Kanda, Sarga 54, Verse 15', 'स ते दर्पं बलं वीर्यमुत्सेकं च तथाविधम्।
अपनेष्यति गात्रेभ्यः शरवर्षेण संयुगे॥', 'sa te darpaṃ balaṃ vīryam utsekaṃ ca tathāvidham
apaneṣyati gātrebhyaḥ śaravarṣeṇa saṃyuge', null, 3054015),
('ramayana-3-54-16', 16, 'Aranya Kanda, Sarga 54, Verse 16', 'यदा विनाशो भूतानां दृश्यते कालचोदितः।
तदा कार्ये प्रमाद्यन्ति नराः कालवशं गताः॥', 'yadā vināśo bhūtānāṃ dṛśyate kālacoditaḥ
tadā kārye pramādyanti narāḥ kālavaśaṃ gatāḥ', null, 3054016),
('ramayana-3-54-17', 17, 'Aranya Kanda, Sarga 54, Verse 17', 'मां प्रधृष्य स ते कालः प्राप्तोऽयं रक्षसाधम।
आत्मनो राक्षसानां च वधायान्तःपुरस्य च॥', 'māṃ pradhṛṣya sa te kālaḥ prāpto ''yaṃ rakṣasādhama
ātmano rākṣasānāṃ ca vadhāyāntaḥpurasya ca', null, 3054017),
('ramayana-3-54-18', 18, 'Aranya Kanda, Sarga 54, Verse 18', 'न शक्या यज्ञमध्यस्था वेदिः स्रुग्भाण्ड मण्डिता।
द्विजातिमन्त्रसंपूता चण्डालेनावमर्दितुम्॥', 'na śakyā yajñamadhyasthā vediḥ srugbhāṇḍa maṇḍitā
dvijātimantrasaṃpūtā caṇḍālenāvamarditum', null, 3054018),
('ramayana-3-54-19', 19, 'Aranya Kanda, Sarga 54, Verse 19', 'इदं शरीरं निःसंज्ञं बन्ध वा घातयस्व वा।
नेदं शरीरं रक्ष्यं मे जीवितं वापि राक्षस।
न हि शक्ष्याम्युपक्रोशं पृथिव्यां दातुमात्मनः॥', 'idaṃ śarīraṃ niḥsaṃjñaṃ bandha vā ghātayasva vā
nedaṃ śarīraṃ rakṣyaṃ me jīvitaṃ vāpi rākṣasa
na hi śakṣyāmy upakrośaṃ pṛthivyāṃ dātum ātmanaḥ', null, 3054019),
('ramayana-3-54-20', 20, 'Aranya Kanda, Sarga 54, Verse 20', 'एवमुक्त्वा तु वैदेही क्रोद्धात्सुपरुषं वचः।
रावणं मैथिली तत्र पुनर्नोवाच किं चन॥', 'evam uktvā tu vaidehī kroddhāt suparuṣaṃ vacaḥ
rāvaṇaṃ maithilī tatra punar novāca kiṃ cana', null, 3054020),
('ramayana-3-54-21', 21, 'Aranya Kanda, Sarga 54, Verse 21', 'सीताया वचनं श्रुत्वा परुषं रोमहर्षणम्।
प्रत्युवाच ततः सीतां भयसंदर्शनं वचः॥', 'sītāyā vacanaṃ śrutvā paruṣaṃ romaharṣaṇam
pratyuvāca tataḥ sītāṃ bhayasaṃdarśanaṃ vacaḥ', null, 3054021),
('ramayana-3-54-22', 22, 'Aranya Kanda, Sarga 54, Verse 22', 'शृणु मैथिलि मद्वाक्यं मासान्द्वादश भामिनि।
कालेनानेन नाभ्येषि यदि मां चारुहासिनि।
ततस्त्वां प्रातराशार्थं सूदाश्छेत्स्यन्ति लेशशः॥', 'śṛṇu maithili madvākyaṃ māsān dvādaśa bhāmini
kālenānena nābhyeṣi yadi māṃ cāruhāsini
tatas tvāṃ prātarāśārthaṃ sūdāś chetsyanti leśaśaḥ', null, 3054022),
('ramayana-3-54-23', 23, 'Aranya Kanda, Sarga 54, Verse 23', 'इत्युक्त्वा परुषं वाक्यं रावणः शत्रुरावणः।
राक्षसीश्च ततः क्रुद्ध इदं वचनमब्रवीत्॥', 'ity uktvā paruṣaṃ vākyaṃ rāvaṇaḥ śatrurāvaṇaḥ
rākṣasīś ca tataḥ kruddha idaṃ vacanam abravīt', null, 3054023),
('ramayana-3-54-24', 24, 'Aranya Kanda, Sarga 54, Verse 24', 'शीघ्रमेवं हि राक्षस्यो विकृता घोरदर्शनाः।
दर्पमस्या विनेष्यन्तु मांसशोणितभोजनाः॥', 'śīghram evaṃ hi rākṣasyo vikṛtā ghoradarśanāḥ
darpam asyā vineṣyantu māṃsaśoṇitabhojanāḥ', null, 3054024),
('ramayana-3-54-25', 25, 'Aranya Kanda, Sarga 54, Verse 25', 'वचनादेव तास्तस्य विकृता घोरदर्शनाः।
कृतप्राञ्जलयो भूत्वा मैथिलीं पर्यवारयन्॥', 'vacanād eva tās tasya vikṛtā ghoradarśanāḥ
kṛtaprāñjalayo bhūtvā maithilīṃ paryavārayan', null, 3054025),
('ramayana-3-54-26', 26, 'Aranya Kanda, Sarga 54, Verse 26', 'स ताः प्रोवाच राजा तु रावणो घोरदर्शनः।
प्रचाल्य चरणोत्कर्षैर्दारयन्निव मेदिनीम्॥', 'sa tāḥ provāca rājā tu rāvaṇo ghoradarśanaḥ
pracālya caraṇotkarṣair dārayann iva medinīm', null, 3054026),
('ramayana-3-54-27', 27, 'Aranya Kanda, Sarga 54, Verse 27', 'अशोकवनिकामध्ये मैथिली नीयतामिति।
तत्रेयं रक्ष्यतां गूढमुष्माभिः परिवारिता॥', 'aśokavanikāmadhye maithilī nīyatām iti
tatreyaṃ rakṣyatāṃ gūḍham uṣmābhiḥ parivāritā', null, 3054027),
('ramayana-3-54-28', 28, 'Aranya Kanda, Sarga 54, Verse 28', 'तत्रैनां तर्जनैर्घोरैः पुनः सान्त्वैश्च मैथिलीम्।
आनयध्वं वशं सर्वा वन्यां गजवधूमिव॥', 'tatraināṃ tarjanair ghoraiḥ punaḥ sāntvaiś ca maithilīm
ānayadhvaṃ vaśaṃ sarvā vanyāṃ gajavadhūm iva', null, 3054028),
('ramayana-3-54-29', 29, 'Aranya Kanda, Sarga 54, Verse 29', 'इति प्रतिसमादिष्टा राक्षस्यो रावणेन ताः।
अशोकवनिकां जग्मुर्मैथिलीं परिगृह्य ताम्॥', 'iti pratisamādiṣṭā rākṣasyo rāvaṇena tāḥ
aśokavanikāṃ jagmur maithilīṃ parigṛhya tām', null, 3054029),
('ramayana-3-54-30', 30, 'Aranya Kanda, Sarga 54, Verse 30', 'सर्वकामफलैर्वृक्षैर्नानापुष्पफलैर्वृताम्।
सर्वकालमदैश्चापि द्विजैः समुपसेविताम्॥', 'sarvakāmaphalair vṛkṣair nānāpuṣpaphalair vṛtām
sarvakālamadaiś cāpi dvijaiḥ samupasevitām', null, 3054030),
('ramayana-3-54-31', 31, 'Aranya Kanda, Sarga 54, Verse 31', 'सा तु शोकपरीताङ्गी मैथिली जनकात्मजा।
राक्षसी वशमापन्ना व्याघ्रीणां हरिणी यथा॥', 'sā tu śokaparītāṅgī maithilī janakātmajā
rākṣasī vaśam āpannā vyāghrīṇāṃ hariṇī yathā', null, 3054031),
('ramayana-3-54-32', 32, 'Aranya Kanda, Sarga 54, Verse 32', 'न विन्दते तत्र तु शर्म मैथिली विरूपनेत्राभिरतीव तर्जिता।
पतिं स्मरन्ती दयितं च देवरं विचेतनाभूद्भयशोकपीडिता॥', 'na vindate tatra tu śarma maithilī virūpanetrābhir atīva tarjitā
patiṃ smarantī dayitaṃ ca devaraṃ vicetanābhūd bhayaśokapīḍitā', null, 3054032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 55 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-55-1', 1, 'Aranya Kanda, Sarga 55, Verse 1', 'राक्षसं मृगरूपेण चरन्तं कामरूपिणम्।
निहत्य रामो मारीचं तूर्णं पथि न्यवर्तत॥', 'rākṣasaṃ mṛgarūpeṇa carantaṃ kāmarūpiṇam
nihatya rāmo mārīcaṃ tūrṇaṃ pathi nyavartata', null, 3055001),
('ramayana-3-55-2', 2, 'Aranya Kanda, Sarga 55, Verse 2', 'तस्य संत्वरमाणस्य द्रष्टुकामस्य मैथिलीम्।
क्रूरस्वरोऽथ गोमायुर्विननादास्य पृष्ठतः॥', 'tasya saṃtvaramāṇasya draṣṭukāmasya maithilīm
krūrasvaro ''tha gomāyur vinanādāsya pṛṣṭhataḥ', null, 3055002),
('ramayana-3-55-3', 3, 'Aranya Kanda, Sarga 55, Verse 3', 'स तस्य स्वरमाज्ञाय दारुणं रोमहर्षणम्।
चिन्तयामास गोमायोः स्वरेण परिशङ्कितः॥', 'sa tasya svaram ājñāya dāruṇaṃ romaharṣaṇam
cintayām āsa gomāyoḥ svareṇa pariśaṅkitaḥ', null, 3055003),
('ramayana-3-55-4', 4, 'Aranya Kanda, Sarga 55, Verse 4', 'अशुभं बत मन्येऽहं गोमायुर्वाश्यते यथा।
स्वस्ति स्यादपि वैदेह्या राक्षसैर्भक्षणं विना॥', 'aśubhaṃ bata manye ''haṃ gomāyur vāśyate yathā
svasti syād api vaidehyā rākṣasair bhakṣaṇaṃ vinā', null, 3055004),
('ramayana-3-55-5', 5, 'Aranya Kanda, Sarga 55, Verse 5', 'मारीचेन तु विज्ञाय स्वरमालक्ष्य मामकम्।
विक्रुष्टं मृगरूपेण लक्ष्मणः शृणुयाद्यदि॥', 'mārīcena tu vijñāya svaram ālakṣya māmakam
vikruṣṭaṃ mṛgarūpeṇa lakṣmaṇaḥ śṛṇuyād yadi', null, 3055005),
('ramayana-3-55-6', 6, 'Aranya Kanda, Sarga 55, Verse 6', 'स सौमित्रिः स्वरं श्रुत्वा तां च हित्वाथ मैथिलीम्।
तयैव प्रहितः क्षिप्रं मत्सकाशमिहैष्यति॥', 'sa saumitriḥ svaraṃ śrutvā tāṃ ca hitvātha maithilīm
tayaiva prahitaḥ kṣipraṃ matsakāśam ihaiṣyati', null, 3055006),
('ramayana-3-55-7', 7, 'Aranya Kanda, Sarga 55, Verse 7', 'राक्षसैः सहितैर्नूनं सीताया ईप्सितो वधः।
काञ्चनश्च मृगो भूत्वा व्यपनीयाश्रमात्तु माम्॥', 'rākṣasaiḥ sahitair nūnaṃ sītāyā īpsito vadhaḥ
kāñcanaś ca mṛgo bhūtvā vyapanīyāśramāt tu mām', null, 3055007),
('ramayana-3-55-8', 8, 'Aranya Kanda, Sarga 55, Verse 8', 'दूरं नीत्वा तु मारीचो राक्षसोऽभूच्छराहतः।
हा लक्ष्मण हतोऽस्मीति यद्वाक्यं व्यजहार ह॥', 'dūraṃ nītvā tu mārīco rākṣaso ''bhūc charāhataḥ
hā lakṣmaṇa hato ''smīti yad vākyaṃ vyajahāra ha', null, 3055008),
('ramayana-3-55-9', 9, 'Aranya Kanda, Sarga 55, Verse 9', 'अपि स्वस्ति भवेद्द्वाभ्यां रहिताभ्यां मया वने।
जनस्थाननिमित्तं हि कृतवैरोऽस्मि राक्षसैः।
निमित्तानि च घोराणि दृश्यन्तेऽद्य बहूनि च॥', 'api svasti bhaved dvābhyāṃ rahitābhyāṃ mayā vane
janasthānanimittaṃ hi kṛtavairo ''smi rākṣasaiḥ
nimittāni ca ghorāṇi dṛśyante ''dya bahūni ca', null, 3055009),
('ramayana-3-55-10', 10, 'Aranya Kanda, Sarga 55, Verse 10', 'इत्येवं चिन्तयन्रामः श्रुत्वा गोमायुनिःस्वनम्।
आत्मनश्चापनयनं मृगरूपेण रक्षसा।
आजगाम जनस्थानं राघवः परिशङ्कितः॥', 'ity evaṃ cintayan rāmaḥ śrutvā gomāyuniḥsvanam
ātmanaś cāpanayanaṃ mṛgarūpeṇa rakṣasā
ājagāma janasthānaṃ rāghavaḥ pariśaṅkitaḥ', null, 3055010),
('ramayana-3-55-11', 11, 'Aranya Kanda, Sarga 55, Verse 11', 'तं दीनमानसं दीनमासेदुर्मृगपक्षिणः।
सव्यं कृत्वा महात्मानं घोरांश्च ससृजुः स्वरान्॥', 'taṃ dīnamānasaṃ dīnam āsedur mṛgapakṣiṇaḥ
savyaṃ kṛtvā mahātmānaṃ ghorāṃś ca sasṛjuḥ svarān', null, 3055011),
('ramayana-3-55-12', 12, 'Aranya Kanda, Sarga 55, Verse 12', 'तानि दृष्ट्वा निमित्तानि महाघोराणि राघवः।
ततो लक्षणमायान्तं ददर्श विगतप्रभम्॥', 'tāni dṛṣṭvā nimittāni mahāghorāṇi rāghavaḥ
tato lakṣaṇam āyāntaṃ dadarśa vigataprabham', null, 3055012),
('ramayana-3-55-13', 13, 'Aranya Kanda, Sarga 55, Verse 13', 'ततोऽविदूरे रामेण समीयाय स लक्ष्मणः।
विषण्णः स विषण्णेन दुःखितो दुःखभागिना॥', 'tato ''vidūre rāmeṇa samīyāya sa lakṣmaṇaḥ
viṣaṇṇaḥ sa viṣaṇṇena duḥkhito duḥkhabhāginā', null, 3055013),
('ramayana-3-55-14', 14, 'Aranya Kanda, Sarga 55, Verse 14', 'संजगर्हेऽथ तं भ्राता जेष्ठो लक्ष्मणमागतम्।
विहाय सीतां विजने वने राक्षससेविते॥', 'saṃjagarhe ''tha taṃ bhrātā jeṣṭho lakṣmaṇam āgatam
vihāya sītāṃ vijane vane rākṣasasevite', null, 3055014),
('ramayana-3-55-15', 15, 'Aranya Kanda, Sarga 55, Verse 15', 'गृहीत्वा च करं सव्यं लक्ष्मणं रघुनन्दनः।
उवाच मधुरोदर्कमिदं परुषमार्तवत्॥', 'gṛhītvā ca karaṃ savyaṃ lakṣmaṇaṃ raghunandanaḥ
uvāca madhurodarkam idaṃ paruṣam ārtavat', null, 3055015),
('ramayana-3-55-16', 16, 'Aranya Kanda, Sarga 55, Verse 16', 'अहो लक्ष्मण गर्ह्यं ते कृतं यत्त्वं विहाय ताम्।
सीतामिहागतः सौम्य कच्चित्स्वस्ति भवेदिति॥', 'aho lakṣmaṇa garhyaṃ te kṛtaṃ yat tvaṃ vihāya tām
sītām ihāgataḥ saumya kaccit svasti bhaved iti', null, 3055016),
('ramayana-3-55-17', 17, 'Aranya Kanda, Sarga 55, Verse 17', 'न मेऽस्ति संशयो वीर सर्वथा जनकात्मजा।
विनष्टा भक्षिता वाप राक्षसैर्वनचारिभिः॥', 'na me ''sti saṃśayo vīra sarvathā janakātmajā
vinaṣṭā bhakṣitā vāpa rākṣasair vanacāribhiḥ', null, 3055017),
('ramayana-3-55-18', 18, 'Aranya Kanda, Sarga 55, Verse 18', 'अशुभान्येव भूयिष्ठं यथा प्रादुर्भवन्ति मे।
अपि लक्ष्मण सीतायाः सामग्र्यं प्राप्नुयावहे॥', 'aśubhāny eva bhūyiṣṭhaṃ yathā prādurbhavanti me
api lakṣmaṇa sītāyāḥ sāmagryaṃ prāpnuyāvahe', null, 3055018),
('ramayana-3-55-19', 19, 'Aranya Kanda, Sarga 55, Verse 19', 'इदं हि रक्षोमृगसंनिकाशं प्रलोभ्य मां दूरमनुप्रयातम्।
हतं कथं चिन्महता श्रमेण स राक्षसोऽभून्म्रियमाण एव॥', 'idaṃ hi rakṣomṛgasaṃnikāśaṃ pralobhya māṃ dūram anuprayātam
hataṃ kathaṃ cin mahatā śrameṇa sa rākṣaso ''bhūn mriyamāṇa eva', null, 3055019),
('ramayana-3-55-20', 20, 'Aranya Kanda, Sarga 55, Verse 20', 'मनश्च मे दीनमिहाप्रहृष्टं चक्षुश्च सव्यं कुरुते विकारम्।
असंशयं लक्ष्मण नास्ति सीता हृता मृता वा पथि वर्तते वा॥', 'manaś ca me dīnam ihāprahṛṣṭaṃ cakṣuś ca savyaṃ kurute vikāram
asaṃśayaṃ lakṣmaṇa nāsti sītā hṛtā mṛtā vā pathi vartate vā', null, 3055020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 56 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-56-1', 1, 'Aranya Kanda, Sarga 56, Verse 1', 'स दृष्ट्वा लक्ष्मणं दीनं शून्ये दशरथात्मजः।
पर्यपृच्छत धर्मात्मा वैदेहीमागतं विना॥', 'sa dṛṣṭvā lakṣmaṇaṃ dīnaṃ śūnye daśarathātmajaḥ
paryapṛcchata dharmātmā vaidehīm āgataṃ vinā', null, 3056001),
('ramayana-3-56-2', 2, 'Aranya Kanda, Sarga 56, Verse 2', 'प्रस्थितं दण्डकारण्यं या मामनुजगाम ह।
क्व सा लक्ष्मण वैदेही यां हित्वा त्वमिहागतः॥', 'prasthitaṃ daṇḍakāraṇyaṃ yā mām anujagāma ha
kva sā lakṣmaṇa vaidehī yāṃ hitvā tvam ihāgataḥ', null, 3056002),
('ramayana-3-56-3', 3, 'Aranya Kanda, Sarga 56, Verse 3', 'राज्यभ्रष्टस्य दीनस्य दण्डकान्परिधावतः।
क्व सा दुःखसहाया मे वैदेही तनुमध्यमा॥', 'rājyabhraṣṭasya dīnasya daṇḍakān paridhāvataḥ
kva sā duḥkhasahāyā me vaidehī tanumadhyamā', null, 3056003),
('ramayana-3-56-4', 4, 'Aranya Kanda, Sarga 56, Verse 4', 'यां विना नोत्सहे वीर मुहूर्तमपि जीवितुम्।
क्व सा प्राणसहाया मे सीता सुरसुतोपमा॥', 'yāṃ vinā notsahe vīra muhūrtam api jīvitum
kva sā prāṇasahāyā me sītā surasutopamā', null, 3056004),
('ramayana-3-56-5', 5, 'Aranya Kanda, Sarga 56, Verse 5', 'पतित्वममराणां वा पृथिव्याश्चापि लक्ष्मण।
विना तां तपनीयाभां नेच्छेयं जनकात्मजाम्॥', 'patitvam amarāṇāṃ vā pṛthivyāś cāpi lakṣmaṇa
vinā tāṃ tapanīyābhāṃ neccheyaṃ janakātmajām', null, 3056005),
('ramayana-3-56-6', 6, 'Aranya Kanda, Sarga 56, Verse 6', 'कच्चिज्जीवति वैदेही प्राणैः प्रियतरा मम।
कच्चित्प्रव्राजनं सौम्य न मे मिथ्या भविष्यति॥', 'kaccij jīvati vaidehī prāṇaiḥ priyatarā mama
kaccit pravrājanaṃ saumya na me mithyā bhaviṣyati', null, 3056006),
('ramayana-3-56-7', 7, 'Aranya Kanda, Sarga 56, Verse 7', 'सीतानिमित्तं सौमित्रे मृते मयि गते त्वयि।
कच्चित्सकामा सुखिता कैकेयी सा भविष्यति॥', 'sītānimittaṃ saumitre mṛte mayi gate tvayi
kaccit sakāmā sukhitā kaikeyī sā bhaviṣyati', null, 3056007),
('ramayana-3-56-8', 8, 'Aranya Kanda, Sarga 56, Verse 8', 'सपुत्रराज्यां सिद्धार्थां मृतपुत्रा तपस्विनी।
उपस्थास्यति कौसल्या कच्चिन्सौम्य न कैकयीम्॥', 'saputrarājyāṃ siddhārthāṃ mṛtaputrā tapasvinī
upasthāsyati kausalyā kaccin saumya na kaikayīm', null, 3056008),
('ramayana-3-56-9', 9, 'Aranya Kanda, Sarga 56, Verse 9', 'यदि जीवति वैदेही गमिष्याम्याश्रमं पुनः।
सुवृत्ता यदि वृत्ता सा प्राणांस्त्यक्ष्यामि लक्ष्मण॥', 'yadi jīvati vaidehī gamiṣyāmy āśramaṃ punaḥ
suvṛttā yadi vṛttā sā prāṇāṃs tyakṣyāmi lakṣmaṇa', null, 3056009),
('ramayana-3-56-10', 10, 'Aranya Kanda, Sarga 56, Verse 10', 'यदि मामाश्रमगतं वैदेही नाभिभाषते।
पुनः प्रहसिता सीता विनशिष्यामि लक्ष्मण॥', 'yadi mām āśramagataṃ vaidehī nābhibhāṣate
punaḥ prahasitā sītā vinaśiṣyāmi lakṣmaṇa', null, 3056010),
('ramayana-3-56-11', 11, 'Aranya Kanda, Sarga 56, Verse 11', 'ब्रूहि लक्ष्मण वैदेही यदि जीवति वा न वा।
त्वयि प्रमत्ते रक्षोभिर्भक्षिता वा तपस्विनी॥', 'brūhi lakṣmaṇa vaidehī yadi jīvati vā na vā
tvayi pramatte rakṣobhir bhakṣitā vā tapasvinī', null, 3056011),
('ramayana-3-56-12', 12, 'Aranya Kanda, Sarga 56, Verse 12', 'सुकुमारी च बाला च नित्यं चादुःखदर्शिनी।
मद्वियोगेन वैदेही व्यक्तं शोचति दुर्मनाः॥', 'sukumārī ca bālā ca nityaṃ cāduḥkhadarśinī
madviyogena vaidehī vyaktaṃ śocati durmanāḥ', null, 3056012),
('ramayana-3-56-13', 13, 'Aranya Kanda, Sarga 56, Verse 13', 'सर्वथा रक्षसा तेन जिह्मेन सुदुरात्मना।
वदता लक्ष्मणेत्युच्चैस्तवापि जनितं भयम्॥', 'sarvathā rakṣasā tena jihmena sudurātmanā
vadatā lakṣmaṇety uccais tavāpi janitaṃ bhayam', null, 3056013),
('ramayana-3-56-14', 14, 'Aranya Kanda, Sarga 56, Verse 14', 'श्रुतश्च शङ्के वैदेह्या स स्वरः सदृशो मम।
त्रस्तया प्रेषितस्त्वं च द्रष्टुं मां शीघ्रमागतः॥', 'śrutaś ca śaṅke vaidehyā sa svaraḥ sadṛśo mama
trastayā preṣitas tvaṃ ca draṣṭuṃ māṃ śīghram āgataḥ', null, 3056014),
('ramayana-3-56-15', 15, 'Aranya Kanda, Sarga 56, Verse 15', 'सर्वथा तु कृतं कष्टं सीतामुत्सृजता वने।
प्रतिकर्तुं नृशंसानां रक्षसां दत्तमन्तरम्॥', 'sarvathā tu kṛtaṃ kaṣṭaṃ sītām utsṛjatā vane
pratikartuṃ nṛśaṃsānāṃ rakṣasāṃ dattam antaram', null, 3056015),
('ramayana-3-56-16', 16, 'Aranya Kanda, Sarga 56, Verse 16', 'दुःखिताः खरघातेन राक्षसाः पिशिताशनाः।
तैः सीता निहता घोरैर्भविष्यति न संशयः॥', 'duḥkhitāḥ kharaghātena rākṣasāḥ piśitāśanāḥ
taiḥ sītā nihatā ghorair bhaviṣyati na saṃśayaḥ', null, 3056016),
('ramayana-3-56-17', 17, 'Aranya Kanda, Sarga 56, Verse 17', 'अहोऽस्मि व्यसने मग्नः सर्वथा रिपुनाशन।
किं त्विदानीं करिष्यामि शङ्के प्राप्तव्यमीदृशम्॥', 'aho ''smi vyasane magnaḥ sarvathā ripunāśana
kiṃ tv idānīṃ kariṣyāmi śaṅke prāptavyam īdṛśam', null, 3056017),
('ramayana-3-56-18', 18, 'Aranya Kanda, Sarga 56, Verse 18', 'इति सीतां वरारोहां चिन्तयन्नेव राघवः।
आजगाम जनस्थानं त्वरया सहलक्ष्मणः॥', 'iti sītāṃ varārohāṃ cintayann eva rāghavaḥ
ājagāma janasthānaṃ tvarayā sahalakṣmaṇaḥ', null, 3056018),
('ramayana-3-56-19', 19, 'Aranya Kanda, Sarga 56, Verse 19', 'विगर्हमाणोऽनुजमार्तरूपं क्षुधा श्रमाच्चैव पिपासया च।
विनिःश्वसञ्शुष्कमुखो विषण्णः प्रतिश्रयं प्राप्य समीक्ष्य शून्यम्॥', 'vigarhamāṇo ''nujam ārtarūpaṃ kṣudhā śramāc caiva pipāsayā ca
viniḥśvasañ śuṣkamukho viṣaṇṇaḥ pratiśrayaṃ prāpya samīkṣya śūnyam', null, 3056019),
('ramayana-3-56-20', 20, 'Aranya Kanda, Sarga 56, Verse 20', 'स्वमाश्रमं संप्रविगाह्य वीरो विहारदेशाननुसृत्य कांश्चित्।
एतत्तदित्येव निवासभूमौ प्रहृष्टरोमा व्यथितो बभूव॥', 'svam āśramaṃ saṃpravigāhya vīro vihāradeśān anusṛtya kāṃś cit
etat tad ity eva nivāsabhūmau prahṛṣṭaromā vyathito babhūva', null, 3056020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 57 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-57-1', 1, 'Aranya Kanda, Sarga 57, Verse 1', 'अथाश्रमादुपावृत्तमन्तरा रघुनन्दनः।
परिपप्रच्छ सौमित्रिं रामो दुःखार्दितः पुनः॥', 'athāśramād upāvṛttam antarā raghunandanaḥ
paripapraccha saumitriṃ rāmo duḥkhārditaḥ punaḥ', null, 3057001),
('ramayana-3-57-2', 2, 'Aranya Kanda, Sarga 57, Verse 2', 'तमुवाच किमर्थं त्वमागतोऽपास्य मैथिलीम्।
यदा सा तव विश्वासाद्वने विहरिता मया॥', 'tam uvāca kimarthaṃ tvam āgato ''pāsya maithilīm
yadā sā tava viśvāsād vane viharitā mayā', null, 3057002),
('ramayana-3-57-3', 3, 'Aranya Kanda, Sarga 57, Verse 3', 'दृष्ट्वैवाभ्यागतं त्वां मे मैथिलीं त्यज्य लक्ष्मण।
शङ्कमानं महत्पापं यत्सत्यं व्यथितं मनः॥', 'dṛṣṭvaivābhyāgataṃ tvāṃ me maithilīṃ tyajya lakṣmaṇa
śaṅkamānaṃ mahat pāpaṃ yat satyaṃ vyathitaṃ manaḥ', null, 3057003),
('ramayana-3-57-4', 4, 'Aranya Kanda, Sarga 57, Verse 4', 'स्फुरते नयनं सव्यं बाहुश्च हृदयं च मे।
दृष्ट्वा लक्ष्मण दूरे त्वां सीताविरहितं पथि॥', 'sphurate nayanaṃ savyaṃ bāhuś ca hṛdayaṃ ca me
dṛṣṭvā lakṣmaṇa dūre tvāṃ sītāvirahitaṃ pathi', null, 3057004),
('ramayana-3-57-5', 5, 'Aranya Kanda, Sarga 57, Verse 5', 'एवमुक्तस्तु सौमित्रिर्लक्ष्मणः शुभलक्षणः।
भूयो दुःखसमाविष्टो दुःखितं राममब्रवीत्॥', 'evam uktas tu saumitrir lakṣmaṇaḥ śubhalakṣaṇaḥ
bhūyo duḥkhasamāviṣṭo duḥkhitaṃ rāmam abravīt', null, 3057005),
('ramayana-3-57-6', 6, 'Aranya Kanda, Sarga 57, Verse 6', 'न स्वयं कामकारेण तां त्यक्त्वाहमिहागतः।
प्रचोदितस्तयैवोग्रैस्त्वत्सकाशमिहागतः॥', 'na svayaṃ kāmakāreṇa tāṃ tyaktvāham ihāgataḥ
pracoditas tayaivograis tvatsakāśam ihāgataḥ', null, 3057006),
('ramayana-3-57-7', 7, 'Aranya Kanda, Sarga 57, Verse 7', 'आर्येणेव परिक्रुष्टं हा सीते लक्ष्मणेति च।
परित्राहीति यद्वाक्यं मैथिल्यास्तच्छ्रुतिं गतम्॥', 'āryeṇeva parikruṣṭaṃ hā sīte lakṣmaṇeti ca
paritrāhīti yad vākyaṃ maithilyās tac chrutiṃ gatam', null, 3057007),
('ramayana-3-57-8', 8, 'Aranya Kanda, Sarga 57, Verse 8', 'सा तमार्तस्वरं श्रुत्वा तव स्नेहेन मैथिली।
गच्छ गच्छेति मामाह रुदन्ती भयविह्वला॥', 'sā tam ārtasvaraṃ śrutvā tava snehena maithilī
gaccha gaccheti mām āha rudantī bhayavihvalā', null, 3057008),
('ramayana-3-57-9', 9, 'Aranya Kanda, Sarga 57, Verse 9', 'प्रचोद्यमानेन मया गच्छेति बहुशस्तया।
प्रत्युक्ता मैथिली वाक्यमिदं त्वत्प्रत्ययान्वितम्॥', 'pracodyamānena mayā gaccheti bahuśas tayā
pratyuktā maithilī vākyam idaṃ tvatpratyayānvitam', null, 3057009),
('ramayana-3-57-10', 10, 'Aranya Kanda, Sarga 57, Verse 10', 'न तत्पश्याम्यहं रक्षो यदस्य भयमावहेत्।
निर्वृता भव नास्त्येतत्केनाप्येवमुदाहृतम्॥', 'na tat paśyāmy ahaṃ rakṣo yad asya bhayam āvahet
nirvṛtā bhava nāsty etat kenāpy evam udāhṛtam', null, 3057010),
('ramayana-3-57-11', 11, 'Aranya Kanda, Sarga 57, Verse 11', 'विगर्हितं च नीचं च कथमार्योऽभिधास्यति।
त्राहीति वचनं सीते यस्त्रायेत्त्रिदशानपि॥', 'vigarhitaṃ ca nīcaṃ ca katham āryo ''bhidhāsyati
trāhīti vacanaṃ sīte yas trāyet tridaśān api', null, 3057011),
('ramayana-3-57-12', 12, 'Aranya Kanda, Sarga 57, Verse 12', 'किंनिमित्तं तु केनापि भ्रातुरालम्ब्य मे स्वरम्।
विस्वरं व्याहृतं वाक्यं लक्ष्मण त्राहि मामिति।
न भवत्या व्यथा कार्या कुनारीजनसेविता॥', 'kiṃnimittaṃ tu kenāpi bhrātur ālambya me svaram
visvaraṃ vyāhṛtaṃ vākyaṃ lakṣmaṇa trāhi mām iti
na bhavatyā vyathā kāryā kunārījanasevitā', null, 3057012),
('ramayana-3-57-13', 13, 'Aranya Kanda, Sarga 57, Verse 13', 'अलं वैक्लव्यमालम्ब्य स्वस्था भव निरुत्सुका।
न चास्ति त्रिषु लोकेषु पुमान्यो राघवं रणे।
जातो वा जायमानो वा संयुगे यः पराजयेत्॥', 'alaṃ vaiklavyam ālambya svasthā bhava nirutsukā
na cāsti triṣu lokeṣu pumān yo rāghavaṃ raṇe
jāto vā jāyamāno vā saṃyuge yaḥ parājayet', null, 3057013),
('ramayana-3-57-14', 14, 'Aranya Kanda, Sarga 57, Verse 14', 'एवमुक्ता तु वैदेही परिमोहितचेतना।
उवाचाश्रूणि मुञ्चन्ती दारुणं मामिदं वचः॥', 'evam uktā tu vaidehī parimohitacetanā
uvācāśrūṇi muñcantī dāruṇaṃ mām idaṃ vacaḥ', null, 3057014),
('ramayana-3-57-15', 15, 'Aranya Kanda, Sarga 57, Verse 15', 'भावो मयि तवात्यर्थं पाप एव निवेशितः।
विनष्टे भ्रातरि प्राप्ते न च त्वं मामवाप्स्यसि॥', 'bhāvo mayi tavātyarthaṃ pāpa eva niveśitaḥ
vinaṣṭe bhrātari prāpte na ca tvaṃ mām avāpsyasi', null, 3057015),
('ramayana-3-57-16', 16, 'Aranya Kanda, Sarga 57, Verse 16', 'संकेताद्भरतेन त्वं रामं समनुगच्छसि।
क्रोशन्तं हि यथात्यर्थं नैनमभ्यवपद्यसे॥', 'saṃketād bharatena tvaṃ rāmaṃ samanugacchasi
krośantaṃ hi yathātyarthaṃ nainam abhyavapadyase', null, 3057016),
('ramayana-3-57-17', 17, 'Aranya Kanda, Sarga 57, Verse 17', 'रिपुः प्रच्छन्नचारी त्वं मदर्थमनुगच्छसि।
राघवस्यान्तरप्रेप्सुस्तथैनं नाभिपद्यसे॥', 'ripuḥ pracchannacārī tvaṃ madartham anugacchasi
rāghavasyāntaraprepsus tathainaṃ nābhipadyase', null, 3057017),
('ramayana-3-57-18', 18, 'Aranya Kanda, Sarga 57, Verse 18', 'एवमुक्तो हि वैदेह्या संरब्धो रक्तलोचनः।
क्रोधात्प्रस्फुरमाणौष्ठ आश्रमादभिनिर्गतः॥', 'evam ukto hi vaidehyā saṃrabdho raktalocanaḥ
krodhāt prasphuramāṇauṣṭha āśramād abhinirgataḥ', null, 3057018),
('ramayana-3-57-19', 19, 'Aranya Kanda, Sarga 57, Verse 19', 'एवं ब्रुवाणं सौमित्रिं रामः संतापमोहितः।
अब्रवीद्दुष्कृतं सौम्य तां विना यत्त्वमागतः॥', 'evaṃ bruvāṇaṃ saumitriṃ rāmaḥ saṃtāpamohitaḥ
abravīd duṣkṛtaṃ saumya tāṃ vinā yat tvam āgataḥ', null, 3057019),
('ramayana-3-57-20', 20, 'Aranya Kanda, Sarga 57, Verse 20', 'जानन्नपि समर्थं मां रक्षसां विनिवारणे।
अनेन क्रोधवाक्येन मैथिल्या निःसृतो भवान्॥', 'jānann api samarthaṃ māṃ rakṣasāṃ vinivāraṇe
anena krodhavākyena maithilyā niḥsṛto bhavān', null, 3057020),
('ramayana-3-57-21', 21, 'Aranya Kanda, Sarga 57, Verse 21', 'न हि ते परितुष्यामि त्यक्त्वा यद्यासि मैथिलीम्।
क्रुद्धायाः परुषं श्रुत्वा स्त्रिया यत्त्वमिहागतः॥', 'na hi te parituṣyāmi tyaktvā yad yāsi maithilīm
kruddhāyāḥ paruṣaṃ śrutvā striyā yat tvam ihāgataḥ', null, 3057021),
('ramayana-3-57-22', 22, 'Aranya Kanda, Sarga 57, Verse 22', 'सर्वथा त्वपनीतं ते सीतया यत्प्रचोदितः।
क्रोधस्य वशमागम्य नाकरोः शासनं मम॥', 'sarvathā tv apanītaṃ te sītayā yat pracoditaḥ
krodhasya vaśam āgamya nākaroḥ śāsanaṃ mama', null, 3057022),
('ramayana-3-57-23', 23, 'Aranya Kanda, Sarga 57, Verse 23', 'असौ हि राक्षसः शेते शरेणाभिहतो मया।
मृगरूपेण येनाहमाश्रमादपवादितः॥', 'asau hi rākṣasaḥ śete śareṇābhihato mayā
mṛgarūpeṇa yenāham āśramād apavāditaḥ', null, 3057023),
('ramayana-3-57-24', 24, 'Aranya Kanda, Sarga 57, Verse 24', 'विकृष्य चापं परिधाय सायकं सलील बाणेन च ताडितो मया।
मार्गीं तनुं त्यज्य च विक्लवस्वरो बभूव केयूरधरः स राक्षसः॥', 'vikṛṣya cāpaṃ paridhāya sāyakaṃ salīla bāṇena ca tāḍito mayā
mārgīṃ tanuṃ tyajya ca viklavasvaro babhūva keyūradharaḥ sa rākṣasaḥ', null, 3057024),
('ramayana-3-57-25', 25, 'Aranya Kanda, Sarga 57, Verse 25', 'शराहतेनैव तदार्तया गिरा स्वरं ममालम्ब्य सुदूरसंश्रवम्।
उदाहृतं तद्वचनं सुदारुणं त्वमागतो येन विहाय मैथिलीम्॥', 'śarāhatenaiva tadārtayā girā svaraṃ mamālambya sudūrasaṃśravam
udāhṛtaṃ tad vacanaṃ sudāruṇaṃ tvam āgato yena vihāya maithilīm', null, 3057025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 58 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-58-1', 1, 'Aranya Kanda, Sarga 58, Verse 1', 'भृशमाव्रजमानस्य तस्याधोवामलोचनम्।
प्रास्फुरच्चास्खलद्रामो वेपथुश्चास्य जायते॥', 'bhṛśam āvrajamānasya tasyādhovāmalocanam
prāsphurac cāskhalad rāmo vepathuś cāsya jāyate', null, 3058001),
('ramayana-3-58-2', 2, 'Aranya Kanda, Sarga 58, Verse 2', 'उपालक्ष्य निमित्तानि सोऽशुभानि मुहुर्मुहुः।
अपि क्षेमं तु सीताया इति वै व्याजहार ह॥', 'upālakṣya nimittāni so ''śubhāni muhur muhuḥ
api kṣemaṃ tu sītāyā iti vai vyājahāra ha', null, 3058002),
('ramayana-3-58-3', 3, 'Aranya Kanda, Sarga 58, Verse 3', 'त्वरमाणो जगामाथ सीतादर्शनलालसः।
शून्यमावसथं दृष्ट्वा बभूवोद्विग्नमानसः॥', 'tvaramāṇo jagāmātha sītādarśanalālasaḥ
śūnyam āvasathaṃ dṛṣṭvā babhūvodvignamānasaḥ', null, 3058003),
('ramayana-3-58-4', 4, 'Aranya Kanda, Sarga 58, Verse 4', 'उद्भ्रमन्निव वेगेन विक्षिपन्रघुनन्दनः।
तत्र तत्रोटजस्थानमभिवीक्ष्य समन्ततः॥', 'udbhramann iva vegena vikṣipan raghunandanaḥ
tatra tatroṭajasthānam abhivīkṣya samantataḥ', null, 3058004),
('ramayana-3-58-5', 5, 'Aranya Kanda, Sarga 58, Verse 5', 'ददर्श पर्णशालां च रहितां सीतया तदा।
श्रिया विरहितां ध्वस्तां हेमन्ते पद्मिनीमिव॥', 'dadarśa parṇaśālāṃ ca rahitāṃ sītayā tadā
śriyā virahitāṃ dhvastāṃ hemante padminīm iva', null, 3058005),
('ramayana-3-58-6', 6, 'Aranya Kanda, Sarga 58, Verse 6', 'रुदन्तमिव वृक्षैश्च म्लानपुष्पमृगद्विजम्।
श्रिया विहीनं विध्वस्तं संत्यक्तवनदैवतम्॥', 'rudantam iva vṛkṣaiś ca mlānapuṣpamṛgadvijam
śriyā vihīnaṃ vidhvastaṃ saṃtyaktavanadaivatam', null, 3058006),
('ramayana-3-58-7', 7, 'Aranya Kanda, Sarga 58, Verse 7', 'विप्रकीर्णाजिनकुशं विप्रविद्धबृसीकटम्।
दृष्ट्वा शून्योटजस्थानं विललाप पुनः पुनः॥', 'viprakīrṇājinakuśaṃ vipraviddhabṛsīkaṭam
dṛṣṭvā śūnyoṭajasthānaṃ vilalāpa punaḥ punaḥ', null, 3058007),
('ramayana-3-58-8', 8, 'Aranya Kanda, Sarga 58, Verse 8', 'हृता मृता वा नष्टा वा भक्षिता वा भविष्यति।
निलीनाप्यथ वा भीरुरथ वा वनमाश्रिता॥', 'hṛtā mṛtā vā naṣṭā vā bhakṣitā vā bhaviṣyati
nilīnāpy atha vā bhīrur atha vā vanam āśritā', null, 3058008),
('ramayana-3-58-9', 9, 'Aranya Kanda, Sarga 58, Verse 9', 'गता विचेतुं पुष्पाणि फलान्यपि च वा पुनः।
अथ वा पद्मिनीं याता जलार्थं वा नदीं गता॥', 'gatā vicetuṃ puṣpāṇi phalāny api ca vā punaḥ
atha vā padminīṃ yātā jalārthaṃ vā nadīṃ gatā', null, 3058009),
('ramayana-3-58-10', 10, 'Aranya Kanda, Sarga 58, Verse 10', 'यत्नान्मृगयमाणस्तु नाससाद वने प्रियाम्।
शोकरक्तेक्षणः शोकादुन्मत्त इव लक्ष्यते॥', 'yatnān mṛgayamāṇas tu nāsasāda vane priyām
śokaraktekṣaṇaḥ śokād unmatta iva lakṣyate', null, 3058010),
('ramayana-3-58-11', 11, 'Aranya Kanda, Sarga 58, Verse 11', 'वृक्षाद्वृक्षं प्रधावन्स गिरींश्चापि नदीन्नदीम्।
बभूव विलपन्रामः शोकपङ्कार्णवप्लुतः॥', 'vṛkṣād vṛkṣaṃ pradhāvan sa girīṃś cāpi nadīn nadīm
babhūva vilapan rāmaḥ śokapaṅkārṇavaplutaḥ', null, 3058011),
('ramayana-3-58-12', 12, 'Aranya Kanda, Sarga 58, Verse 12', 'अस्ति कच्चित्त्वया दृष्टा सा कदम्बप्रिया प्रिया।
कदम्ब यदि जानीषे शंस सीतां शुभाननाम्॥', 'asti kaccit tvayā dṛṣṭā sā kadambapriyā priyā
kadamba yadi jānīṣe śaṃsa sītāṃ śubhānanām', null, 3058012),
('ramayana-3-58-13', 13, 'Aranya Kanda, Sarga 58, Verse 13', 'स्निग्धपल्लवसंकाशां पीतकौशेयवासिनीम्।
शंसस्व यदि वा दृष्टा बिल्व बिल्वोपमस्तनी॥', 'snigdhapallavasaṃkāśāṃ pītakauśeyavāsinīm
śaṃsasva yadi vā dṛṣṭā bilva bilvopamastanī', null, 3058013),
('ramayana-3-58-14', 14, 'Aranya Kanda, Sarga 58, Verse 14', 'अथ वार्जुन शंस त्वं प्रियां तामर्जुनप्रियाम्।
जनकस्य सुता भीरुर्यदि जीवति वा न वा॥', 'atha vārjuna śaṃsa tvaṃ priyāṃ tām arjunapriyām
janakasya sutā bhīrur yadi jīvati vā na vā', null, 3058014),
('ramayana-3-58-15', 15, 'Aranya Kanda, Sarga 58, Verse 15', 'ककुभः ककुभोरुं तां व्यक्तं जानाति मैथिलीम्।
लतापल्लवपुष्पाढ्यो भाति ह्येष वनस्पतिः॥', 'kakubhaḥ kakubhoruṃ tāṃ vyaktaṃ jānāti maithilīm
latāpallavapuṣpāḍhyo bhāti hy eṣa vanaspatiḥ', null, 3058015),
('ramayana-3-58-16', 16, 'Aranya Kanda, Sarga 58, Verse 16', 'भ्रमरैरुपगीतश्च यथा द्रुमवरो ह्ययम्।
एष व्यक्तं विजानाति तिलकस्तिलकप्रियाम्॥', 'bhramarair upagītaś ca yathā drumavaro hy ayam
eṣa vyaktaṃ vijānāti tilakas tilakapriyām', null, 3058016),
('ramayana-3-58-17', 17, 'Aranya Kanda, Sarga 58, Verse 17', 'अशोकशोकापनुद शोकोपहतचेतसं।
त्वन्नामानं कुरु क्षिप्रं प्रियासंदर्शनेन माम्॥', 'aśokaśokāpanuda śokopahatacetasaṃ
tvannāmānaṃ kuru kṣipraṃ priyāsaṃdarśanena mām', null, 3058017),
('ramayana-3-58-18', 18, 'Aranya Kanda, Sarga 58, Verse 18', 'यदि ताल त्वया दृष्टा पक्वतालफलस्तनी।
कथयस्व वरारोहां कारुष्यं यदि ते मयि॥', 'yadi tāla tvayā dṛṣṭā pakvatālaphalastanī
kathayasva varārohāṃ kāruṣyaṃ yadi te mayi', null, 3058018),
('ramayana-3-58-19', 19, 'Aranya Kanda, Sarga 58, Verse 19', 'यदि दृष्टा त्वया सीता जम्बुजाम्बूनदप्रभा।
प्रियां यदि विजानीषे निःशङ्कं कथयस्व मे॥', 'yadi dṛṣṭā tvayā sītā jambujāmbūnadaprabhā
priyāṃ yadi vijānīṣe niḥśaṅkaṃ kathayasva me', null, 3058019),
('ramayana-3-58-20', 20, 'Aranya Kanda, Sarga 58, Verse 20', 'अथ वा मृगशावाक्षीं मृग जानासि मैथिलीम्।
मृगविप्रेक्षणी कान्ता मृगीभिः सहिता भवेत्॥', 'atha vā mṛgaśāvākṣīṃ mṛga jānāsi maithilīm
mṛgaviprekṣaṇī kāntā mṛgībhiḥ sahitā bhavet', null, 3058020),
('ramayana-3-58-21', 21, 'Aranya Kanda, Sarga 58, Verse 21', 'गज सा गजनासोरुर्यदि दृष्टा त्वया भवेत्।
तां मन्ये विदितां तुभ्यमाख्याहि वरवारण॥', 'gaja sā gajanāsorur yadi dṛṣṭā tvayā bhavet
tāṃ manye viditāṃ tubhyam ākhyāhi varavāraṇa', null, 3058021),
('ramayana-3-58-22', 22, 'Aranya Kanda, Sarga 58, Verse 22', 'शार्दूल यदि सा दृष्टा प्रिया चन्द्रनिभानना।
मैथिली मम विस्रब्धः कथयस्व न ते भयम्॥', 'śārdūla yadi sā dṛṣṭā priyā candranibhānanā
maithilī mama visrabdhaḥ kathayasva na te bhayam', null, 3058022),
('ramayana-3-58-23', 23, 'Aranya Kanda, Sarga 58, Verse 23', 'किं धावसि प्रिये नूनं दृष्टासि कमलेक्षणे।
वृक्षेणाच्छाद्य चात्मानं किं मां न प्रतिभाषसे॥', 'kiṃ dhāvasi priye nūnaṃ dṛṣṭāsi kamalekṣaṇe
vṛkṣeṇācchādya cātmānaṃ kiṃ māṃ na pratibhāṣase', null, 3058023),
('ramayana-3-58-24', 24, 'Aranya Kanda, Sarga 58, Verse 24', 'तिष्ठ तिष्ठ वरारोहे न तेऽस्ति करुणा मयि।
नात्यर्थं हास्यशीलासि किमर्थं मामुपेक्षसे॥', 'tiṣṭha tiṣṭha varārohe na te ''sti karuṇā mayi
nātyarthaṃ hāsyaśīlāsi kimarthaṃ mām upekṣase', null, 3058024),
('ramayana-3-58-25', 25, 'Aranya Kanda, Sarga 58, Verse 25', 'पीतकौशेयकेनासि सूचिता वरवर्णिनि।
धावन्त्यपि मया दृष्टा तिष्ठ यद्यस्ति सौहृदम्॥', 'pītakauśeyakenāsi sūcitā varavarṇini
dhāvanty api mayā dṛṣṭā tiṣṭha yady asti sauhṛdam', null, 3058025),
('ramayana-3-58-26', 26, 'Aranya Kanda, Sarga 58, Verse 26', 'नैव सा नूनमथ वा हिंसिता चारुहासिनी।
कृच्छ्रं प्राप्तं हि मां नूनं यथोपेक्षितुमर्हति॥', 'naiva sā nūnam atha vā hiṃsitā cāruhāsinī
kṛcchraṃ prāptaṃ hi māṃ nūnaṃ yathopekṣitum arhati', null, 3058026),
('ramayana-3-58-27', 27, 'Aranya Kanda, Sarga 58, Verse 27', 'व्यक्तं सा भक्षिता बाला राक्षसैः पिशिताशनैः।
विभज्याङ्गानि सर्वाणि मया विरहिता प्रिया॥', 'vyaktaṃ sā bhakṣitā bālā rākṣasaiḥ piśitāśanaiḥ
vibhajyāṅgāni sarvāṇi mayā virahitā priyā', null, 3058027),
('ramayana-3-58-28', 28, 'Aranya Kanda, Sarga 58, Verse 28', 'नूनं तच्छुभदन्तौष्ठं मुखं निष्प्रभतां गतम्।
सा हि चम्पकवर्णाभा ग्रीवा ग्रैवेय शोभिता॥', 'nūnaṃ tac chubhadantauṣṭhaṃ mukhaṃ niṣprabhatāṃ gatam
sā hi campakavarṇābhā grīvā graiveya śobhitā', null, 3058028),
('ramayana-3-58-29', 29, 'Aranya Kanda, Sarga 58, Verse 29', 'कोमला विलपन्त्यास्तु कान्ताया भक्षिता शुभा।
नूनं विक्षिप्यमाणौ तौ बाहू पल्लवकोमलौ॥', 'komalā vilapantyās tu kāntāyā bhakṣitā śubhā
nūnaṃ vikṣipyamāṇau tau bāhū pallavakomalau', null, 3058029),
('ramayana-3-58-30', 30, 'Aranya Kanda, Sarga 58, Verse 30', 'भक्षितौ वेपमानाग्रौ सहस्ताभरणाङ्गदौ।
मया विरहिता बाला रक्षसां भक्षणाय वै॥', 'bhakṣitau vepamānāgrau sahastābharaṇāṅgadau
mayā virahitā bālā rakṣasāṃ bhakṣaṇāya vai', null, 3058030),
('ramayana-3-58-31', 31, 'Aranya Kanda, Sarga 58, Verse 31', 'सार्थेनेव परित्यक्ता भक्षिता बहुबान्धवा।
हा लक्ष्मण महाबाहो पश्यसि त्वं प्रियां क्व चित्॥', 'sārtheneva parityaktā bhakṣitā bahubāndhavā
hā lakṣmaṇa mahābāho paśyasi tvaṃ priyāṃ kva cit', null, 3058031),
('ramayana-3-58-32', 32, 'Aranya Kanda, Sarga 58, Verse 32', 'हा प्रिये क्व गता भद्रे हा सीतेति पुनः पुनः।
इत्येवं विलपन्रामः परिधावन्वनाद्वनम्॥', 'hā priye kva gatā bhadre hā sīteti punaḥ punaḥ
ity evaṃ vilapan rāmaḥ paridhāvan vanād vanam', null, 3058032),
('ramayana-3-58-33', 33, 'Aranya Kanda, Sarga 58, Verse 33', 'क्व चिदुद्भ्रमते वेगात्क्व चिद्विभ्रमते बलात्।
क्व चिन्मत्त इवाभाति कान्तान्वेषणतत्परः॥', 'kva cid udbhramate vegāt kva cid vibhramate balāt
kva cin matta ivābhāti kāntān veṣaṇatatparaḥ', null, 3058033),
('ramayana-3-58-34', 34, 'Aranya Kanda, Sarga 58, Verse 34', 'स वनानि नदीः शैलान्गिरिप्रस्रवणानि च।
काननानि च वेगेन भ्रमत्यपरिसंस्थितः॥', 'sa vanāni nadīḥ śailān giriprasravaṇāni ca
kānanāni ca vegena bhramaty aparisaṃsthitaḥ', null, 3058034),
('ramayana-3-58-35', 35, 'Aranya Kanda, Sarga 58, Verse 35', 'तथा स गत्वा विपुलं महद्वनं परीत्य सर्वं त्वथ मैथिलीं प्रति।
अनिष्ठिताशः स चकार मार्गणे पुनः प्रियायाः परमं परिश्रमम्॥', 'tathā sa gatvā vipulaṃ mahad vanaṃ parītya sarvaṃ tv atha maithilīṃ prati
aniṣṭhitāśaḥ sa cakāra mārgaṇe punaḥ priyāyāḥ paramaṃ pariśramam', null, 3058035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 59 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-59-1', 1, 'Aranya Kanda, Sarga 59, Verse 1', 'दृष्टाश्रमपदं शून्यं रामो दशरथात्मजः।
रहितां पर्णशालां च विध्वस्तान्यासनानि च॥', 'dṛṣṭāśramapadaṃ śūnyaṃ rāmo daśarathātmajaḥ
rahitāṃ parṇaśālāṃ ca vidhvastāny āsanāni ca', null, 3059001),
('ramayana-3-59-2', 2, 'Aranya Kanda, Sarga 59, Verse 2', 'अदृष्ट्वा तत्र वैदेहीं संनिरीक्ष्य च सर्वशः।
उवाच रामः प्राक्रुश्य प्रगृह्य रुचिरौ भुजौ॥', 'adṛṣṭvā tatra vaidehīṃ saṃnirīkṣya ca sarvaśaḥ
uvāca rāmaḥ prākruśya pragṛhya rucirau bhujau', null, 3059002),
('ramayana-3-59-3', 3, 'Aranya Kanda, Sarga 59, Verse 3', 'क्व नु लक्ष्मण वैदेही कं वा देशमितो गता।
केनाहृता वा सौमित्रे भक्षिता केन वा प्रिया॥', 'kva nu lakṣmaṇa vaidehī kaṃ vā deśam ito gatā
kenāhṛtā vā saumitre bhakṣitā kena vā priyā', null, 3059003),
('ramayana-3-59-4', 4, 'Aranya Kanda, Sarga 59, Verse 4', 'वृष्केणावार्य यदि मां सीते हसितुमिच्छसि।
अलं ते हसितेनाद्य मां भजस्व सुदुःखितम्॥', 'vṛṣkeṇāvārya yadi māṃ sīte hasitum icchasi
alaṃ te hasitenādya māṃ bhajasva suduḥkhitam', null, 3059004),
('ramayana-3-59-5', 5, 'Aranya Kanda, Sarga 59, Verse 5', 'यैः सह क्रीडसे सीते विश्वस्तैर्मृगपोतकैः।
एते हीनास्त्वया सौम्ये ध्यायन्त्यस्राविलेक्षणाः॥', 'yaiḥ saha krīḍase sīte viśvastair mṛgapotakaiḥ
ete hīnās tvayā saumye dhyāyanty asrāvilekṣaṇāḥ', null, 3059005),
('ramayana-3-59-6', 6, 'Aranya Kanda, Sarga 59, Verse 6', 'मृतं शोकेन महता सीताहरणजेन माम्।
परलोके महाराजो नूनं द्रक्ष्यति मे पिता॥', 'mṛtaṃ śokena mahatā sītāharaṇajena mām
paraloke mahārājo nūnaṃ drakṣyati me pitā', null, 3059006),
('ramayana-3-59-7', 7, 'Aranya Kanda, Sarga 59, Verse 7', 'कथं प्रतिज्ञां संश्रुत्य मया त्वमभियोजितः।
अपूरयित्वा तं कालं मत्सकाशमिहागतः॥', 'kathaṃ pratijñāṃ saṃśrutya mayā tvam abhiyojitaḥ
apūrayitvā taṃ kālaṃ matsakāśam ihāgataḥ', null, 3059007),
('ramayana-3-59-8', 8, 'Aranya Kanda, Sarga 59, Verse 8', 'कामवृत्तमनार्यं मां मृषावादिनमेव च।
धिक्त्वामिति परे लोके व्यक्तं वक्ष्यति मे पिता॥', 'kāmavṛttam anāryaṃ māṃ mṛṣāvādinam eva ca
dhik tvām iti pare loke vyaktaṃ vakṣyati me pitā', null, 3059008),
('ramayana-3-59-9', 9, 'Aranya Kanda, Sarga 59, Verse 9', 'विवशं शोकसंतप्तं दीनं भग्नमनोरथम्।
मामिहोत्सृज्य करुणं कीर्तिर्नरमिवानृजुम्॥', 'vivaśaṃ śokasaṃtaptaṃ dīnaṃ bhagnamanoratham
mām ihotsṛjya karuṇaṃ kīrtir naram ivānṛjum', null, 3059009),
('ramayana-3-59-10', 10, 'Aranya Kanda, Sarga 59, Verse 10', 'क्व गच्छसि वरारोहे मामुत्सृज्य सुमध्यमे।
त्वया विरहितश्चाहं मोक्ष्ये जीवितमात्मनः॥', 'kva gacchasi varārohe mām utsṛjya sumadhyame
tvayā virahitaś cāhaṃ mokṣye jīvitam ātmanaḥ', null, 3059010),
('ramayana-3-59-11', 11, 'Aranya Kanda, Sarga 59, Verse 11', 'इतीव विलपन्रामः सीतादर्शनलालसः।
न ददर्श सुदुःखार्तो राघवो जनकात्मजाम्॥', 'itīva vilapan rāmaḥ sītādarśanalālasaḥ
na dadarśa suduḥkhārto rāghavo janakātmajām', null, 3059011),
('ramayana-3-59-12', 12, 'Aranya Kanda, Sarga 59, Verse 12', 'अनासादयमानं तं सीतां दशरथात्मजम्।
पङ्कमासाद्य विपुलं सीदन्तमिव कुञ्जरम्।
लक्ष्मणो राममत्यर्थमुवाच हितकाम्यया॥', 'anāsādayamānaṃ taṃ sītāṃ daśarathātmajam
paṅkam āsādya vipulaṃ sīdantam iva kuñjaram
lakṣmaṇo rāmam atyartham uvāca hitakāmyayā', null, 3059012),
('ramayana-3-59-13', 13, 'Aranya Kanda, Sarga 59, Verse 13', 'मा विषादं महाबाहो कुरु यत्नं मया सह।
इदं च हि वनं शूर बहुकन्दरशोभितम्॥', 'mā viṣādaṃ mahābāho kuru yatnaṃ mayā saha
idaṃ ca hi vanaṃ śūra bahukandaraśobhitam', null, 3059013),
('ramayana-3-59-14', 14, 'Aranya Kanda, Sarga 59, Verse 14', 'प्रियकाननसंचारा वनोन्मत्ता च मैथिली।
सा वनं वा प्रविष्टा स्यान्नलिनीं वा सुपुष्पिताम्॥', 'priyakānanasaṃcārā vanonmattā ca maithilī
sā vanaṃ vā praviṣṭā syān nalinīṃ vā supuṣpitām', null, 3059014),
('ramayana-3-59-15', 15, 'Aranya Kanda, Sarga 59, Verse 15', 'सरितं वापि संप्राप्ता मीनवञ्जुरसेविताम्।
वित्रासयितुकामा वा लीना स्यात्कानने क्व चित्।
जिज्ञासमाना वैदेही त्वां मां च पुरुषर्षभ॥', 'saritaṃ vāpi saṃprāptā mīnavañjurasevitām
vitrāsayitukāmā vā līnā syāt kānane kva cit
jijñāsamānā vaidehī tvāṃ māṃ ca puruṣarṣabha', null, 3059015),
('ramayana-3-59-16', 16, 'Aranya Kanda, Sarga 59, Verse 16', 'तस्या ह्यन्वेषणे श्रीमन्क्षिप्रमेव यतावहे।
वनं सर्वं विचिनुवो यत्र सा जनकात्मजा।
मन्यसे यदि काकुत्स्थ मा स्म शोके मनः कृथाः॥', 'tasyā hy anveṣaṇe śrīman kṣipram eva yatāvahe
vanaṃ sarvaṃ vicinuvo yatra sā janakātmajā
manyase yadi kākutstha mā sma śoke manaḥ kṛthāḥ', null, 3059016),
('ramayana-3-59-17', 17, 'Aranya Kanda, Sarga 59, Verse 17', 'एवमुक्तस्तु सौहार्दाल्लक्ष्मणेन समाहितः।
सह सौमित्रिणा रामो विचेतुमुपचक्रमे।
तौ वनानि गिरींश्चैव सरितश्च सरांसि च॥', 'evam uktas tu sauhārdāl lakṣmaṇena samāhitaḥ
saha saumitriṇā rāmo vicetum upacakrame
tau vanāni girīṃś caiva saritaś ca sarāṃsi ca', null, 3059017),
('ramayana-3-59-18', 18, 'Aranya Kanda, Sarga 59, Verse 18', 'निखिलेन विचिन्वन्तौ सीतां दशरथात्मजौ।
तस्य शैलस्य सानूनि गुहाश्च शिखराणि च॥', 'nikhilena vicinvantau sītāṃ daśarathātmajau
tasya śailasya sānūni guhāś ca śikharāṇi ca', null, 3059018),
('ramayana-3-59-19', 19, 'Aranya Kanda, Sarga 59, Verse 19', 'निखिलेन विचिन्वन्तौ नैव तामभिजग्मतुः।
विचित्य सर्वतः शैलं रामो लक्ष्मणमब्रवीत्॥', 'nikhilena vicinvantau naiva tām abhijagmatuḥ
vicitya sarvataḥ śailaṃ rāmo lakṣmaṇam abravīt', null, 3059019),
('ramayana-3-59-20', 20, 'Aranya Kanda, Sarga 59, Verse 20', 'नेह पश्यामि सौमित्रे वैदेहीं पर्वते शुभे।
ततो दुःखाभिसंतप्तो लक्ष्मणो वाक्यमब्रवीत्॥', 'neha paśyāmi saumitre vaidehīṃ parvate śubhe
tato duḥkhābhisaṃtapto lakṣmaṇo vākyam abravīt', null, 3059020),
('ramayana-3-59-21', 21, 'Aranya Kanda, Sarga 59, Verse 21', 'विचरन्दण्डकारण्यं भ्रातरं दीप्ततेजसं।
प्राप्स्यसि त्वं महाप्राज्ञ मैथिलीं जनकात्मजाम्॥', 'vicaran daṇḍakāraṇyaṃ bhrātaraṃ dīptatejasaṃ
prāpsyasi tvaṃ mahāprājña maithilīṃ janakātmajām', null, 3059021),
('ramayana-3-59-22', 22, 'Aranya Kanda, Sarga 59, Verse 22', 'यथा विष्णुर्महाबाहुर्बलिं बद्ध्वा महीमिमाम्।
एवमुक्तस्तु वीरेण लक्ष्मणेन स राघवः॥', 'yathā viṣṇur mahābāhur baliṃ baddhvā mahīm imām
evam uktas tu vīreṇa lakṣmaṇena sa rāghavaḥ', null, 3059022),
('ramayana-3-59-23', 23, 'Aranya Kanda, Sarga 59, Verse 23', 'उवाच दीनया वाचा दुःखाभिहतचेतनः।
वनं सर्वं सुविचितं पद्मिन्यः फुल्लपङ्कजाः॥', 'uvāca dīnayā vācā duḥkhābhihatacetanaḥ
vanaṃ sarvaṃ suvicitaṃ padminyaḥ phullapaṅkajāḥ', null, 3059023),
('ramayana-3-59-24', 24, 'Aranya Kanda, Sarga 59, Verse 24', 'गिरिश्चायं महाप्राज्ञ बहुकन्दरनिर्झरः।
न हि पश्यामि वैदेहीं प्राणेभ्योऽपि गरीयसीम्॥', 'giriś cāyaṃ mahāprājña bahukandaranirjharaḥ
na hi paśyāmi vaidehīṃ prāṇebhyo ''pi garīyasīm', null, 3059024),
('ramayana-3-59-25', 25, 'Aranya Kanda, Sarga 59, Verse 25', 'एवं स विलपन्रामः सीताहरणकर्शितः।
दीनः शोकसमाविष्टो मुहूर्तं विह्वलोऽभवत्॥', 'evaṃ sa vilapan rāmaḥ sītāharaṇakarśitaḥ
dīnaḥ śokasamāviṣṭo muhūrtaṃ vihvalo ''bhavat', null, 3059025),
('ramayana-3-59-26', 26, 'Aranya Kanda, Sarga 59, Verse 26', 'स विह्वलितसर्वाङ्गो गतबुद्धिर्विचेतनः।
विषसादातुरो दीनो निःश्वस्याशीतमायतम्॥', 'sa vihvalitasarvāṅgo gatabuddhir vicetanaḥ
viṣasādāturo dīno niḥśvasyāśītam āyatam', null, 3059026),
('ramayana-3-59-27', 27, 'Aranya Kanda, Sarga 59, Verse 27', 'बहुशः स तु निःश्वस्य रामो राजीवलोचनः।
हा प्रियेति विचुक्रोश बहुशो बाष्पगद्गदः॥', 'bahuśaḥ sa tu niḥśvasya rāmo rājīvalocanaḥ
hā priyeti vicukrośa bahuśo bāṣpagadgadaḥ', null, 3059027),
('ramayana-3-59-28', 28, 'Aranya Kanda, Sarga 59, Verse 28', 'तं सान्त्वयामास ततो लक्ष्मणः प्रियबान्धवः।
बहुप्रकारं धर्मज्ञः प्रश्रितः प्रश्रिताञ्जलिः॥', 'taṃ sāntvayām āsa tato lakṣmaṇaḥ priyabāndhavaḥ
bahuprakāraṃ dharmajñaḥ praśritaḥ praśritāñjaliḥ', null, 3059028),
('ramayana-3-59-29', 29, 'Aranya Kanda, Sarga 59, Verse 29', 'अनादृत्य तु तद्वाक्यं लक्ष्मणौष्ठपुटच्युतम्।
अपश्यंस्तां प्रियां सीतां प्राक्रोशत्स पुनः पुनः॥', 'anādṛtya tu tad vākyaṃ lakṣmaṇauṣṭhapuṭacyutam
apaśyaṃs tāṃ priyāṃ sītāṃ prākrośat sa punaḥ punaḥ', null, 3059029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 60 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-60-1', 1, 'Aranya Kanda, Sarga 60, Verse 1', 'स दीनो दीनया वाचा लक्ष्मणं वाक्यमब्रवीत्।
शीघ्रं लक्ष्मण जानीहि गत्वा गोदावरीं नदीम्।
अपि गोदावरीं सीता पद्मान्यानयितुं गता॥', 'sa dīno dīnayā vācā lakṣmaṇaṃ vākyam abravīt
śīghraṃ lakṣmaṇa jānīhi gatvā godāvarīṃ nadīm
api godāvarīṃ sītā padmāny ānayituṃ gatā', null, 3060001),
('ramayana-3-60-2', 2, 'Aranya Kanda, Sarga 60, Verse 2', 'एवमुक्तस्तु रामेण लक्ष्मणः पुनरेव हि।
नदीं गोदावरीं रम्यां जगाम लघुविक्रमः॥', 'evam uktas tu rāmeṇa lakṣmaṇaḥ punar eva hi
nadīṃ godāvarīṃ ramyāṃ jagāma laghuvikramaḥ', null, 3060002),
('ramayana-3-60-3', 3, 'Aranya Kanda, Sarga 60, Verse 3', 'तां लक्ष्मणस्तीर्थवतीं विचित्वा राममब्रवीत्।
नैनां पश्यामि तीर्थेषु क्रोशतो न शृणोति मे॥', 'tāṃ lakṣmaṇas tīrthavatīṃ vicitvā rāmam abravīt
naināṃ paśyāmi tīrtheṣu krośato na śṛṇoti me', null, 3060003),
('ramayana-3-60-4', 4, 'Aranya Kanda, Sarga 60, Verse 4', 'कं नु सा देशमापन्ना वैदेही क्लेशनाशिनी।
न हि तं वेद्मि वै राम यत्र सा तनुमध्यमा॥', 'kaṃ nu sā deśam āpannā vaidehī kleśanāśinī
na hi taṃ vedmi vai rāma yatra sā tanumadhyamā', null, 3060004),
('ramayana-3-60-5', 5, 'Aranya Kanda, Sarga 60, Verse 5', 'लक्ष्मणस्य वचः श्रुत्वा दीनः संताप मोहितः।
रामः समभिचक्राम स्वयं गोदावरीं नदीम्॥', 'lakṣmaṇasya vacaḥ śrutvā dīnaḥ saṃtāpa mohitaḥ
rāmaḥ samabhicakrāma svayaṃ godāvarīṃ nadīm', null, 3060005),
('ramayana-3-60-6', 6, 'Aranya Kanda, Sarga 60, Verse 6', 'स तामुपस्थितो रामः क्व सीतेत्येवमब्रवीत्॥', 'sa tām upasthito rāmaḥ kva sītety evam abravīt', null, 3060006),
('ramayana-3-60-7', 7, 'Aranya Kanda, Sarga 60, Verse 7', 'भूतानि राक्षसेन्द्रेण वधार्हेण हृतामपि।
न तां शशंसू रामाय तथा गोदावरी नदी॥', 'bhūtāni rākṣasendreṇa vadhārheṇa hṛtām api
na tāṃ śaśaṃsū rāmāya tathā godāvarī nadī', null, 3060007),
('ramayana-3-60-8', 8, 'Aranya Kanda, Sarga 60, Verse 8', 'ततः प्रचोदिता भूतैः शंसास्मै तां प्रियामिति।
न च साभ्यवदत्सीतां पृष्टा रामेण शोचिता॥', 'tataḥ pracoditā bhūtaiḥ śaṃsāsmai tāṃ priyām iti
na ca sābhyavadat sītāṃ pṛṣṭā rāmeṇa śocitā', null, 3060008),
('ramayana-3-60-9', 9, 'Aranya Kanda, Sarga 60, Verse 9', 'रावणस्य च तद्रूपं कर्माणि च दुरात्मनः।
ध्यात्वा भयात्तु वैदेहीं सा नदी न शशंस ताम्॥', 'rāvaṇasya ca tad rūpaṃ karmāṇi ca durātmanaḥ
dhyātvā bhayāt tu vaidehīṃ sā nadī na śaśaṃsa tām', null, 3060009),
('ramayana-3-60-10', 10, 'Aranya Kanda, Sarga 60, Verse 10', 'निराशस्तु तया नद्या सीताया दर्शने कृतः।
उवाच रामः सौमित्रिं सीतादर्शनकर्शितः॥', 'nirāśas tu tayā nadyā sītāyā darśane kṛtaḥ
uvāca rāmaḥ saumitriṃ sītādarśanakarśitaḥ', null, 3060010),
('ramayana-3-60-11', 11, 'Aranya Kanda, Sarga 60, Verse 11', 'किं नु लक्ष्मण वक्ष्यामि समेत्य जनकं वचः।
मातरं चैव वैदेह्या विना तामहमप्रियम्॥', 'kiṃ nu lakṣmaṇa vakṣyāmi sametya janakaṃ vacaḥ
mātaraṃ caiva vaidehyā vinā tām aham apriyam', null, 3060011),
('ramayana-3-60-12', 12, 'Aranya Kanda, Sarga 60, Verse 12', 'या मे राज्यविहीनस्य वने वन्येन जीवतः।
सर्वं व्यपनयच्छोकं वैदेही क्व नु सा गता॥', 'yā me rājyavihīnasya vane vanyena jīvataḥ
sarvaṃ vyapanayac chokaṃ vaidehī kva nu sā gatā', null, 3060012),
('ramayana-3-60-13', 13, 'Aranya Kanda, Sarga 60, Verse 13', 'ज्ञातिपक्षविहीनस्य राजपुत्रीमपश्यतः।
मन्ये दीर्घा भविष्यन्ति रात्रयो मम जाग्रतः॥', 'jñātipakṣavihīnasya rājaputrīm apaśyataḥ
manye dīrghā bhaviṣyanti rātrayo mama jāgrataḥ', null, 3060013),
('ramayana-3-60-14', 14, 'Aranya Kanda, Sarga 60, Verse 14', 'गोदावरीं जनस्थानमिमं प्रस्रवणं गिरिम्।
सर्वाण्यनुचरिष्यामि यदि सीता हि दृश्यते॥', 'godāvarīṃ janasthānam imaṃ prasravaṇaṃ girim
sarvāṇy anucariṣyāmi yadi sītā hi dṛśyate', null, 3060014),
('ramayana-3-60-15', 15, 'Aranya Kanda, Sarga 60, Verse 15', 'एवं संभाषमाणौ तावन्योन्यं भ्रातरावुभौ।
वसुंधरायां पतितं पुष्पमार्गमपश्यताम्॥', 'evaṃ saṃbhāṣamāṇau tāv anyonyaṃ bhrātarāv ubhau
vasuṃdharāyāṃ patitaṃ puṣpamārgam apaśyatām', null, 3060015),
('ramayana-3-60-16', 16, 'Aranya Kanda, Sarga 60, Verse 16', 'तां पुष्पवृष्टिं पतितां दृष्ट्वा रामो महीतले।
उवाच लक्ष्मणं वीरो दुःखितो दुःखितं वचः॥', 'tāṃ puṣpavṛṣṭiṃ patitāṃ dṛṣṭvā rāmo mahītale
uvāca lakṣmaṇaṃ vīro duḥkhito duḥkhitaṃ vacaḥ', null, 3060016),
('ramayana-3-60-17', 17, 'Aranya Kanda, Sarga 60, Verse 17', 'अभिजानामि पुष्पाणि तानीमामीह लक्ष्मण।
अपिनद्धानि वैदेह्या मया दत्तानि कानने॥', 'abhijānāmi puṣpāṇi tānīmāmīha lakṣmaṇa
apinaddhāni vaidehyā mayā dattāni kānane', null, 3060017),
('ramayana-3-60-18', 18, 'Aranya Kanda, Sarga 60, Verse 18', 'एवमुक्त्वा महाबाहुर्लक्ष्मणं पुरुषर्षभम्।
क्रुद्धोऽब्रवीद्गिरिं तत्र सिंहः क्षुद्रमृगं यथा॥', 'evam uktvā mahābāhur lakṣmaṇaṃ puruṣarṣabham
kruddho ''bravīd giriṃ tatra siṃhaḥ kṣudramṛgaṃ yathā', null, 3060018),
('ramayana-3-60-19', 19, 'Aranya Kanda, Sarga 60, Verse 19', 'तां हेमवर्णां हेमाभां सीतां दर्शय पर्वत।
यावत्सानूनि सर्वाणि न ते विध्वंसयाम्यहम्॥', 'tāṃ hemavarṇāṃ hemābhāṃ sītāṃ darśaya parvata
yāvat sānūni sarvāṇi na te vidhvaṃsayāmy aham', null, 3060019),
('ramayana-3-60-20', 20, 'Aranya Kanda, Sarga 60, Verse 20', 'मम बाणाग्निनिर्दग्धो भस्मीभूतो भविष्यसि।
असेव्यः सततं चैव निस्तृणद्रुमपल्लवः॥', 'mama bāṇāgninirdagdho bhasmībhūto bhaviṣyasi
asevyaḥ satataṃ caiva nistṛṇadrumapallavaḥ', null, 3060020),
('ramayana-3-60-21', 21, 'Aranya Kanda, Sarga 60, Verse 21', 'इमां वा सरितं चाद्य शोषयिष्यामि लक्ष्मण।
यदि नाख्याति मे सीतामद्य चन्द्रनिभाननाम्॥', 'imāṃ vā saritaṃ cādya śoṣayiṣyāmi lakṣmaṇa
yadi nākhyāti me sītām adya candranibhānanām', null, 3060021),
('ramayana-3-60-22', 22, 'Aranya Kanda, Sarga 60, Verse 22', 'एवं स रुषितो रामो दिधक्षन्निव चक्षुषा।
ददर्श भूमौ निष्क्रान्तं राक्षसस्य पदं महत्॥', 'evaṃ sa ruṣito rāmo didhakṣann iva cakṣuṣā
dadarśa bhūmau niṣkrāntaṃ rākṣasasya padaṃ mahat', null, 3060022),
('ramayana-3-60-23', 23, 'Aranya Kanda, Sarga 60, Verse 23', 'स समीक्ष्य परिक्रान्तं सीताया राक्षसस्य च।
संभ्रान्तहृदयो रामः शशंस भ्रातरं प्रियम्॥', 'sa samīkṣya parikrāntaṃ sītāyā rākṣasasya ca
saṃbhrāntahṛdayo rāmaḥ śaśaṃsa bhrātaraṃ priyam', null, 3060023),
('ramayana-3-60-24', 24, 'Aranya Kanda, Sarga 60, Verse 24', 'पश्य लक्ष्मण वैदेह्याः शीर्णाः कनकबिन्दवः।
भूषणानां हि सौमित्रे माल्यानि विविधानि च॥', 'paśya lakṣmaṇa vaidehyāḥ śīrṇāḥ kanakabindavaḥ
bhūṣaṇānāṃ hi saumitre mālyāni vividhāni ca', null, 3060024),
('ramayana-3-60-25', 25, 'Aranya Kanda, Sarga 60, Verse 25', 'तप्तबिन्दुनिकाशैश्च चित्रैः क्षतजबिन्दुभिः।
आवृतं पश्य सौमित्रे सर्वतो धरणीतलम्॥', 'taptabindunikāśaiś ca citraiḥ kṣatajabindubhiḥ
āvṛtaṃ paśya saumitre sarvato dharaṇītalam', null, 3060025),
('ramayana-3-60-26', 26, 'Aranya Kanda, Sarga 60, Verse 26', 'मन्ये लक्ष्मण वैदेही राक्षसैः कामरूपिभिः।
भित्त्वा भित्त्वा विभक्ता वा भक्षिता वा भविष्यति॥', 'manye lakṣmaṇa vaidehī rākṣasaiḥ kāmarūpibhiḥ
bhittvā bhittvā vibhaktā vā bhakṣitā vā bhaviṣyati', null, 3060026),
('ramayana-3-60-27', 27, 'Aranya Kanda, Sarga 60, Verse 27', 'तस्य निमित्तं वैदेह्या द्वयोर्विवदमानयोः।
बभूव युद्धं सौमित्रे घोरं राक्षसयोरिह॥', 'tasya nimittaṃ vaidehyā dvayor vivadamānayoḥ
babhūva yuddhaṃ saumitre ghoraṃ rākṣasayor iha', null, 3060027),
('ramayana-3-60-28', 28, 'Aranya Kanda, Sarga 60, Verse 28', 'मुक्तामणिचितं चेदं तपनीयविभूषितम्।
धरण्यां पतितं सौम्य कस्य भग्नं महद्धनुः॥', 'muktāmaṇicitaṃ cedaṃ tapanīyavibhūṣitam
dharaṇyāṃ patitaṃ saumya kasya bhagnaṃ mahad dhanuḥ', null, 3060028),
('ramayana-3-60-29', 29, 'Aranya Kanda, Sarga 60, Verse 29', 'तरुणादित्यसंकाशं वैदूर्यगुलिकाचितम्।
विशीर्णं पतितं भूमौ कवचं कस्य काञ्चनम्॥', 'taruṇādityasaṃkāśaṃ vaidūryagulikācitam
viśīrṇaṃ patitaṃ bhūmau kavacaṃ kasya kāñcanam', null, 3060029),
('ramayana-3-60-30', 30, 'Aranya Kanda, Sarga 60, Verse 30', 'छत्रं शतशलाकं च दिव्यमाल्योपशोभितम्।
भग्नदण्डमिदं कस्य भूमौ सौम्य निपातितम्॥', 'chatraṃ śataśalākaṃ ca divyamālyopaśobhitam
bhagnadaṇḍam idaṃ kasya bhūmau saumya nipātitam', null, 3060030),
('ramayana-3-60-31', 31, 'Aranya Kanda, Sarga 60, Verse 31', 'काञ्चनोरश्छदाश्चेमे पिशाचवदनाः खराः।
भीमरूपा महाकायाः कस्य वा निहता रणे॥', 'kāñcanoraśchadāś ceme piśācavadanāḥ kharāḥ
bhīmarūpā mahākāyāḥ kasya vā nihatā raṇe', null, 3060031),
('ramayana-3-60-32', 32, 'Aranya Kanda, Sarga 60, Verse 32', 'दीप्तपावकसंकाशो द्युतिमान्समरध्वजः।
अपविद्धश्च भग्नश्च कस्य सांग्रामिको रथः॥', 'dīptapāvakasaṃkāśo dyutimān samaradhvajaḥ
apaviddhaś ca bhagnaś ca kasya sāṃgrāmiko rathaḥ', null, 3060032),
('ramayana-3-60-33', 33, 'Aranya Kanda, Sarga 60, Verse 33', 'रथाक्षमात्रा विशिखास्तपनीयविभूषणाः।
कस्येमेऽभिहता बाणाः प्रकीर्णा घोरकर्मणः॥', 'rathākṣamātrā viśikhās tapanīyavibhūṣaṇāḥ
kasyeme ''bhihatā bāṇāḥ prakīrṇā ghorakarmaṇaḥ', null, 3060033),
('ramayana-3-60-34', 34, 'Aranya Kanda, Sarga 60, Verse 34', 'वैरं शतगुणं पश्य ममेदं जीवितान्तकम्।
सुघोरहृदयैः सौम्य राक्षसैः कामरूपिभिः॥', 'vairaṃ śataguṇaṃ paśya mamedaṃ jīvitāntakam
sughorahṛdayaiḥ saumya rākṣasaiḥ kāmarūpibhiḥ', null, 3060034),
('ramayana-3-60-35', 35, 'Aranya Kanda, Sarga 60, Verse 35', 'हृता मृता वा सीता हि भक्षिता वा तपस्विनी।
न धर्मस्त्रायते सीतां ह्रियमाणां महावने॥', 'hṛtā mṛtā vā sītā hi bhakṣitā vā tapasvinī
na dharmas trāyate sītāṃ hriyamāṇāṃ mahāvane', null, 3060035),
('ramayana-3-60-36', 36, 'Aranya Kanda, Sarga 60, Verse 36', 'भक्षितायां हि वैदेह्यां हृतायामपि लक्ष्मण।
के हि लोके प्रियं कर्तुं शक्ताः सौम्य ममेश्वराः॥', 'bhakṣitāyāṃ hi vaidehyāṃ hṛtāyām api lakṣmaṇa
ke hi loke priyaṃ kartuṃ śaktāḥ saumya mameśvarāḥ', null, 3060036),
('ramayana-3-60-37', 37, 'Aranya Kanda, Sarga 60, Verse 37', 'कर्तारमपि लोकानां शूरं करुणवेदिनम्।
अज्ञानादवमन्येरन्सर्वभूतानि लक्ष्मण॥', 'kartāram api lokānāṃ śūraṃ karuṇavedinam
ajñānād avamanyeran sarvabhūtāni lakṣmaṇa', null, 3060037),
('ramayana-3-60-38', 38, 'Aranya Kanda, Sarga 60, Verse 38', 'मृदुं लोकहिते युक्तं दान्तं करुणवेदिनम्।
निर्वीर्य इति मन्यन्ते नूनं मां त्रिदशेश्वराः॥', 'mṛduṃ lokahite yuktaṃ dāntaṃ karuṇavedinam
nirvīrya iti manyante nūnaṃ māṃ tridaśeśvarāḥ', null, 3060038),
('ramayana-3-60-39', 39, 'Aranya Kanda, Sarga 60, Verse 39', 'मां प्राप्य हि गुणो दोषः संवृत्तः पश्य लक्ष्मण।
अद्यैव सर्वभूतानां रक्षसामभवाय च।
संहृत्यैव शशिज्योत्स्नां महान्सूर्य इवोदितः॥', 'māṃ prāpya hi guṇo doṣaḥ saṃvṛttaḥ paśya lakṣmaṇa
adyaiva sarvabhūtānāṃ rakṣasām abhavāya ca
saṃhṛtyaiva śaśijyotsnāṃ mahān sūrya ivoditaḥ', null, 3060039),
('ramayana-3-60-40', 40, 'Aranya Kanda, Sarga 60, Verse 40', 'नैव यक्षा न गन्धर्वा न पिशाचा न राक्षसाः।
किंनरा वा मनुष्या वा सुखं प्राप्स्यन्ति लक्ष्मण॥', 'naiva yakṣā na gandharvā na piśācā na rākṣasāḥ
kiṃnarā vā manuṣyā vā sukhaṃ prāpsyanti lakṣmaṇa', null, 3060040),
('ramayana-3-60-41', 41, 'Aranya Kanda, Sarga 60, Verse 41', 'ममास्त्रबाणसंपूर्णमाकाशं पश्य लक्ष्मण।
निःसंपातं करिष्यामि ह्यद्य त्रैलोक्यचारिणाम्॥', 'mamāstrabāṇasaṃpūrṇam ākāśaṃ paśya lakṣmaṇa
niḥsaṃpātaṃ kariṣyāmi hy adya trailokyacāriṇām', null, 3060041),
('ramayana-3-60-42', 42, 'Aranya Kanda, Sarga 60, Verse 42', 'संनिरुद्धग्रहगणमावारितनिशाकरम्।
विप्रनष्टानलमरुद्भास्करद्युतिसंवृतम्॥', 'saṃniruddhagrahagaṇam āvāritaniśākaram
vipranaṣṭānalamarudbhāskaradyutisaṃvṛtam', null, 3060042),
('ramayana-3-60-43', 43, 'Aranya Kanda, Sarga 60, Verse 43', 'विनिर्मथितशैलाग्रं शुष्यमाणजलाशयम्।
ध्वस्तद्रुमलतागुल्मं विप्रणाशितसागरम्॥', 'vinirmathitaśailāgraṃ śuṣyamāṇajalāśayam
dhvastadrumalatāgulmaṃ vipraṇāśitasāgaram', null, 3060043),
('ramayana-3-60-44', 44, 'Aranya Kanda, Sarga 60, Verse 44', 'न तां कुशलिनीं सीतां प्रदास्यन्ति ममेश्वराः।
अस्मिन्मुहूर्ते सौमित्रे मम द्रक्ष्यन्ति विक्रमम्॥', 'na tāṃ kuśalinīṃ sītāṃ pradāsyanti mameśvarāḥ
asmin muhūrte saumitre mama drakṣyanti vikramam', null, 3060044),
('ramayana-3-60-45', 45, 'Aranya Kanda, Sarga 60, Verse 45', 'नाकाशमुत्पतिष्यन्ति सर्वभूतानि लक्ष्मण।
मम चापगुणान्मुक्तैर्बाणजालैर्निरन्तरम्॥', 'nākāśam utpatiṣyanti sarvabhūtāni lakṣmaṇa
mama cāpaguṇān muktair bāṇajālair nirantaram', null, 3060045),
('ramayana-3-60-46', 46, 'Aranya Kanda, Sarga 60, Verse 46', 'अर्दितं मम नाराचैर्ध्वस्तभ्रान्तमृगद्विजम्।
समाकुलममर्यादं जगत्पश्याद्य लक्ष्मण॥', 'arditaṃ mama nārācair dhvastabhrāntamṛgadvijam
samākulam amaryādaṃ jagat paśyādya lakṣmaṇa', null, 3060046),
('ramayana-3-60-47', 47, 'Aranya Kanda, Sarga 60, Verse 47', 'आकर्णपूर्णैरिषुभिर्जीवलोकं दुरावरैः।
करिष्ये मैथिलीहेतोरपिशाचमराक्षसं॥', 'ākarṇapūrṇair iṣubhir jīvalokaṃ durāvaraiḥ
kariṣye maithilīhetor apiśācam arākṣasaṃ', null, 3060047),
('ramayana-3-60-48', 48, 'Aranya Kanda, Sarga 60, Verse 48', 'मम रोषप्रयुक्तानां सायकानां बलं सुराः।
द्रक्ष्यन्त्यद्य विमुक्तानाममर्षाद्दूरगामिनाम्॥', 'mama roṣaprayuktānāṃ sāyakānāṃ balaṃ surāḥ
drakṣyanty adya vimuktānām amarṣād dūragāminām', null, 3060048),
('ramayana-3-60-49', 49, 'Aranya Kanda, Sarga 60, Verse 49', 'नैव देवा न दैतेया न पिशाचा न राक्षसाः।
भविष्यन्ति मम क्रोधात्त्रैलोक्ये विप्रणाशिते॥', 'naiva devā na daiteyā na piśācā na rākṣasāḥ
bhaviṣyanti mama krodhāt trailokye vipraṇāśite', null, 3060049),
('ramayana-3-60-50', 50, 'Aranya Kanda, Sarga 60, Verse 50', 'देवदानवयक्षाणां लोका ये रक्षसामपि।
बहुधा निपतिष्यन्ति बाणौघैः शकुलीकृताः।
निर्मर्यादानिमांल्लोकान्करिष्याम्यद्य सायकैः॥', 'devadānavayakṣāṇāṃ lokā ye rakṣasām api
bahudhā nipatiṣyanti bāṇaughaiḥ śakulīkṛtāḥ
nirmaryādān imāṃl lokān kariṣyāmy adya sāyakaiḥ', null, 3060050),
('ramayana-3-60-51', 51, 'Aranya Kanda, Sarga 60, Verse 51', 'यथा जरा यथा मृत्युर्यथाकालो यथाविधिः।
नित्यं न प्रतिहन्यन्ते सर्वभूतेषु लक्ष्मण।
तथाहं क्रोधसंयुक्तो न निवार्योऽस्म्यसंशयम्॥', 'yathā jarā yathā mṛtyur yathākālo yathāvidhiḥ
nityaṃ na pratihanyante sarvabhūteṣu lakṣmaṇa
tathāhaṃ krodhasaṃyukto na nivāryo ''smy asaṃśayam', null, 3060051),
('ramayana-3-60-52', 52, 'Aranya Kanda, Sarga 60, Verse 52', 'पुरेव मे चारुदतीमनिन्दितां दिशन्ति सीतां यदि नाद्य मैथिलीम्।
सदेवगन्धर्वमनुष्य पन्नगं जगत्सशैलं परिवर्तयाम्यहम्॥', 'pureva me cārudatīm aninditāṃ diśanti sītāṃ yadi nādya maithilīm
sadevagandharvamanuṣya pannagaṃ jagat saśailaṃ parivartayāmy aham', null, 3060052)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 61 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-61-1', 1, 'Aranya Kanda, Sarga 61, Verse 1', 'तप्यमानं तथा रामं सीताहरणकर्शितम्।
लोकानामभवे युक्तं साम्वर्तकमिवानलम्॥', 'tapyamānaṃ tathā rāmaṃ sītāharaṇakarśitam
lokānām abhave yuktaṃ sāmvartakam ivānalam', null, 3061001),
('ramayana-3-61-2', 2, 'Aranya Kanda, Sarga 61, Verse 2', 'वीक्षमाणं धनुः सज्यं निःश्वसन्तं मुहुर्मुहुः।
हन्तुकामं पशुं रुद्रं क्रुद्धं दक्षक्रतौ यथा॥', 'vīkṣamāṇaṃ dhanuḥ sajyaṃ niḥśvasantaṃ muhur muhuḥ
hantukāmaṃ paśuṃ rudraṃ kruddhaṃ dakṣakratau yathā', null, 3061002),
('ramayana-3-61-3', 3, 'Aranya Kanda, Sarga 61, Verse 3', 'अदृष्टपूर्वं संक्रुद्धं दृष्ट्वा रामं स लक्ष्मणः।
अब्रवीत्प्राञ्जलिर्वाक्यं मुखेन परिशुष्यता॥', 'adṛṣṭapūrvaṃ saṃkruddhaṃ dṛṣṭvā rāmaṃ sa lakṣmaṇaḥ
abravīt prāñjalir vākyaṃ mukhena pariśuṣyatā', null, 3061003),
('ramayana-3-61-4', 4, 'Aranya Kanda, Sarga 61, Verse 4', 'पुरा भूत्वा मृदुर्दान्तः सर्वभूतहिते रतः।
न क्रोधवशमापन्नः प्रकृतिं हातुमर्हसि॥', 'purā bhūtvā mṛdur dāntaḥ sarvabhūtahite rataḥ
na krodhavaśam āpannaḥ prakṛtiṃ hātum arhasi', null, 3061004),
('ramayana-3-61-5', 5, 'Aranya Kanda, Sarga 61, Verse 5', 'चन्द्रे लक्ष्णीः प्रभा सूर्ये गतिर्वायौ भुवि क्षमा।
एतच्च नियतं सर्वं त्वयि चानुत्तमं यशः॥', 'candre lakṣṇīḥ prabhā sūrye gatir vāyau bhuvi kṣamā
etac ca niyataṃ sarvaṃ tvayi cānuttamaṃ yaśaḥ', null, 3061005),
('ramayana-3-61-6', 6, 'Aranya Kanda, Sarga 61, Verse 6', 'न तु जानामि कस्यायं भग्नः सांग्रामिको रथः।
केन वा कस्य वा हेतोः सायुधः सपरिच्छदः॥', 'na tu jānāmi kasyāyaṃ bhagnaḥ sāṃgrāmiko rathaḥ
kena vā kasya vā hetoḥ sāyudhaḥ saparicchadaḥ', null, 3061006),
('ramayana-3-61-7', 7, 'Aranya Kanda, Sarga 61, Verse 7', 'खुरनेमिक्षतश्चायं सिक्तो रुधिरबिन्दुभिः।
देशो निवृत्तसंग्रामः सुघोरः पार्थिवात्मज॥', 'khuranemikṣataś cāyaṃ sikto rudhirabindubhiḥ
deśo nivṛttasaṃgrāmaḥ sughoraḥ pārthivātmaja', null, 3061007),
('ramayana-3-61-8', 8, 'Aranya Kanda, Sarga 61, Verse 8', 'एकस्य तु विमर्दोऽयं न द्वयोर्वदतां वर।
न हि वृत्तं हि पश्यामि बलस्य महतः पदम्॥', 'ekasya tu vimardo ''yaṃ na dvayor vadatāṃ vara
na hi vṛttaṃ hi paśyāmi balasya mahataḥ padam', null, 3061008),
('ramayana-3-61-9', 9, 'Aranya Kanda, Sarga 61, Verse 9', 'नैकस्य तु कृते लोकान्विनाशयितुमर्हसि।
युक्तदण्डा हि मृदवः प्रशान्ता वसुधाधिपाः॥', 'naikasya tu kṛte lokān vināśayitum arhasi
yuktadaṇḍā hi mṛdavaḥ praśāntā vasudhādhipāḥ', null, 3061009),
('ramayana-3-61-10', 10, 'Aranya Kanda, Sarga 61, Verse 10', 'सदा त्वं सर्वभूतानां शरण्यः परमा गतिः।
को नु दारप्रणाशं ते साधु मन्येत राघव॥', 'sadā tvaṃ sarvabhūtānāṃ śaraṇyaḥ paramā gatiḥ
ko nu dārapraṇāśaṃ te sādhu manyeta rāghava', null, 3061010),
('ramayana-3-61-11', 11, 'Aranya Kanda, Sarga 61, Verse 11', 'सरितः सागराः शैला देवगन्धर्वदानवाः।
नालं ते विप्रियं कर्तुं दीक्षितस्येव साधवः॥', 'saritaḥ sāgarāḥ śailā devagandharvadānavāḥ
nālaṃ te vipriyaṃ kartuṃ dīkṣitasyeva sādhavaḥ', null, 3061011),
('ramayana-3-61-12', 12, 'Aranya Kanda, Sarga 61, Verse 12', 'येन राजन्हृता सीता तमन्वेषितुमर्हसि।
मद्द्वितीयो धनुष्पाणिः सहायैः परमर्षिभिः॥', 'yena rājan hṛtā sītā tam anveṣitum arhasi
maddvitīyo dhanuṣpāṇiḥ sahāyaiḥ paramarṣibhiḥ', null, 3061012),
('ramayana-3-61-13', 13, 'Aranya Kanda, Sarga 61, Verse 13', 'समुद्रं च विचेष्यामः पर्वतांश्च वनानि च।
गुहाश्च विविधा घोरा नलिनीः पार्वतीश्च ह॥', 'samudraṃ ca viceṣyāmaḥ parvatāṃś ca vanāni ca
guhāś ca vividhā ghorā nalinīḥ pārvatīś ca ha', null, 3061013),
('ramayana-3-61-14', 14, 'Aranya Kanda, Sarga 61, Verse 14', 'देवगन्धर्वलोकांश्च विचेष्यामः समाहिताः।
यावन्नाधिगमिष्यामस्तव भार्यापहारिणम्॥', 'devagandharvalokāṃś ca viceṣyāmaḥ samāhitāḥ
yāvan nādhigamiṣyāmas tava bhāryāpahāriṇam', null, 3061014),
('ramayana-3-61-15', 15, 'Aranya Kanda, Sarga 61, Verse 15', 'न चेत्साम्ना प्रदास्यन्ति पत्नीं ते त्रिदशेश्वराः।
कोसलेन्द्र ततः पश्चात्प्राप्तकालं करिष्यसि॥', 'na cet sāmnā pradāsyanti patnīṃ te tridaśeśvarāḥ
kosalendra tataḥ paścāt prāptakālaṃ kariṣyasi', null, 3061015),
('ramayana-3-61-16', 16, 'Aranya Kanda, Sarga 61, Verse 16', 'शीलेन साम्ना विनयेन सीतां नयेन न प्राप्स्यसि चेन्नरेन्द्र।
ततः समुत्सादय हेमपुङ्खैर्महेन्द्रवज्रप्रतिमैः शरौघैः॥', 'śīlena sāmnā vinayena sītāṃ nayena na prāpsyasi cen narendra
tataḥ samutsādaya hemapuṅkhair mahendravajrapratimaiḥ śaraughaiḥ', null, 3061016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 62 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-62-1', 1, 'Aranya Kanda, Sarga 62, Verse 1', 'तं तथा शोकसंतप्तं विलपन्तमनाथवत्।
मोहेन महताविष्टं परिद्यूनमचेतनम्॥', 'taṃ tathā śokasaṃtaptaṃ vilapantam anāthavat
mohena mahatāviṣṭaṃ paridyūnam acetanam', null, 3062001),
('ramayana-3-62-2', 2, 'Aranya Kanda, Sarga 62, Verse 2', 'ततः सौमित्रिराश्वास्य मुहूर्तादिव लक्ष्मणः।
रामं संबोधयामास चरणौ चाभिपीडयन्॥', 'tataḥ saumitrir āśvāsya muhūrtād iva lakṣmaṇaḥ
rāmaṃ saṃbodhayām āsa caraṇau cābhipīḍayan', null, 3062002),
('ramayana-3-62-3', 3, 'Aranya Kanda, Sarga 62, Verse 3', 'महता तपसा राम महता चापि कर्मणा।
राज्ञा दशरथेनासील्लब्धोऽमृतमिवामरैः॥', 'mahatā tapasā rāma mahatā cāpi karmaṇā
rājñā daśarathenāsīl labdho ''mṛtam ivāmaraiḥ', null, 3062003),
('ramayana-3-62-4', 4, 'Aranya Kanda, Sarga 62, Verse 4', 'तव चैव गुणैर्बद्धस्त्वद्वियोगान्महीपतिः।
राजा देवत्वमापन्नो भरतस्य यथा श्रुतम्॥', 'tava caiva guṇair baddhas tvadviyogān mahīpatiḥ
rājā devatvam āpanno bharatasya yathā śrutam', null, 3062004),
('ramayana-3-62-5', 5, 'Aranya Kanda, Sarga 62, Verse 5', 'यदि दुःखमिदं प्राप्तं काकुत्स्थ न सहिष्यसे।
प्राकृतश्चाल्पसत्त्वश्च इतरः कः सहिष्यति॥', 'yadi duḥkham idaṃ prāptaṃ kākutstha na sahiṣyase
prākṛtaś cālpasattvaś ca itaraḥ kaḥ sahiṣyati', null, 3062005),
('ramayana-3-62-6', 6, 'Aranya Kanda, Sarga 62, Verse 6', 'दुःखितो हि भवांल्लोकांस्तेजसा यदि धक्ष्यते।
आर्ताः प्रजा नरव्याघ्र क्व नु यास्यन्ति निर्वृतिम्॥', 'duḥkhito hi bhavāṃl lokāṃs tejasā yadi dhakṣyate
ārtāḥ prajā naravyāghra kva nu yāsyanti nirvṛtim', null, 3062006),
('ramayana-3-62-7', 7, 'Aranya Kanda, Sarga 62, Verse 7', 'लोकस्वभाव एवैष ययातिर्नहुषात्मजः।
गतः शक्रेण सालोक्यमनयस्तं समस्पृशत्॥', 'lokasvabhāva evaiṣa yayātir nahuṣātmajaḥ
gataḥ śakreṇa sālokyam anayas taṃ samaspṛśat', null, 3062007),
('ramayana-3-62-8', 8, 'Aranya Kanda, Sarga 62, Verse 8', 'महर्षयो वसिष्ठस्तु यः पितुर्नः पुरोहितः।
अह्ना पुत्रशतं जज्ञे तथैवास्य पुनर्हतम्॥', 'maharṣayo vasiṣṭhas tu yaḥ pitur naḥ purohitaḥ
ahnā putraśataṃ jajñe tathaivāsya punar hatam', null, 3062008),
('ramayana-3-62-9', 9, 'Aranya Kanda, Sarga 62, Verse 9', 'या चेयं जगतो माता देवी लोकनमस्कृता।
अस्याश्च चलनं भूमेर्दृश्यते सत्यसंश्रव॥', 'yā ceyaṃ jagato mātā devī lokanamaskṛtā
asyāś ca calanaṃ bhūmer dṛśyate satyasaṃśrava', null, 3062009),
('ramayana-3-62-10', 10, 'Aranya Kanda, Sarga 62, Verse 10', 'यौ चेमौ जगतां नेत्रे यत्र सर्वं प्रतिष्ठितम्।
आदित्यचन्द्रौ ग्रहणमभ्युपेतौ महाबलौ॥', 'yau cemau jagatāṃ netre yatra sarvaṃ pratiṣṭhitam
ādityacandrau grahaṇam abhyupetau mahābalau', null, 3062010),
('ramayana-3-62-11', 11, 'Aranya Kanda, Sarga 62, Verse 11', 'सुमहान्त्यपि भूतानि देवाश्च पुरुषर्षभ।
न दैवस्य प्रमुञ्चन्ति सर्वभूतानि देहिनः॥', 'sumahānty api bhūtāni devāś ca puruṣarṣabha
na daivasya pramuñcanti sarvabhūtāni dehinaḥ', null, 3062011),
('ramayana-3-62-12', 12, 'Aranya Kanda, Sarga 62, Verse 12', 'शक्रादिष्वपि देवेषु वर्तमानौ नयानयौ।
श्रूयेते नरशार्दूल न त्वं व्यथितुमर्हसि॥', 'śakrādiṣv api deveṣu vartamānau nayānayau
śrūyete naraśārdūla na tvaṃ vyathitum arhasi', null, 3062012),
('ramayana-3-62-13', 13, 'Aranya Kanda, Sarga 62, Verse 13', 'नष्टायामपि वैदेह्यां हृतायामपि चानघ।
शोचितुं नार्हसे वीर यथान्यः प्राकृतस्तथा॥', 'naṣṭāyām api vaidehyāṃ hṛtāyām api cānagha
śocituṃ nārhase vīra yathānyaḥ prākṛtas tathā', null, 3062013),
('ramayana-3-62-14', 14, 'Aranya Kanda, Sarga 62, Verse 14', 'त्वद्विधा हि न शोचन्ति सततं सत्यदर्शिनः।
सुमहत्स्वपि कृच्छ्रेषु रामानिर्विण्णदर्शणाः॥', 'tvadvidhā hi na śocanti satataṃ satyadarśinaḥ
sumahatsv api kṛcchreṣu rāmānirviṇṇadarśaṇāḥ', null, 3062014),
('ramayana-3-62-15', 15, 'Aranya Kanda, Sarga 62, Verse 15', 'तत्त्वतो हि नरश्रेष्ठ बुद्ध्या समनुचिन्तय।
बुद्ध्या युक्ता महाप्राज्ञा विजानन्ति शुभाशुभे॥', 'tattvato hi naraśreṣṭha buddhyā samanucintaya
buddhyā yuktā mahāprājñā vijānanti śubhāśubhe', null, 3062015),
('ramayana-3-62-16', 16, 'Aranya Kanda, Sarga 62, Verse 16', 'अदृष्टगुणदोषाणामधृतानां च कर्मणाम्।
नान्तरेण क्रियां तेषां फलमिष्टं प्रवर्तते॥', 'adṛṣṭaguṇadoṣāṇām adhṛtānāṃ ca karmaṇām
nāntareṇa kriyāṃ teṣāṃ phalam iṣṭaṃ pravartate', null, 3062016),
('ramayana-3-62-17', 17, 'Aranya Kanda, Sarga 62, Verse 17', 'मामेव हि पुरा वीर त्वमेव बहुषोऽन्वशाः।
अनुशिष्याद्धि को नु त्वामपि साक्षाद्बृहस्पतिः॥', 'mām eva hi purā vīra tvam eva bahuṣo ''nvaśāḥ
anuśiṣyād dhi ko nu tvām api sākṣād bṛhaspatiḥ', null, 3062017),
('ramayana-3-62-18', 18, 'Aranya Kanda, Sarga 62, Verse 18', 'बुद्धिश्च ते महाप्राज्ञ देवैरपि दुरन्वया।
शोकेनाभिप्रसुप्तं ते ज्ञानं संबोधयाम्यहम्॥', 'buddhiś ca te mahāprājña devair api duranvayā
śokenābhiprasuptaṃ te jñānaṃ saṃbodhayāmy aham', null, 3062018),
('ramayana-3-62-19', 19, 'Aranya Kanda, Sarga 62, Verse 19', 'दिव्यं च मानुषं चैवमात्मनश्च पराक्रमम्।
इक्ष्वाकुवृषभावेक्ष्य यतस्व द्विषतां बधे॥', 'divyaṃ ca mānuṣaṃ caivam ātmanaś ca parākramam
ikṣvākuvṛṣabhāvekṣya yatasva dviṣatāṃ badhe', null, 3062019),
('ramayana-3-62-20', 20, 'Aranya Kanda, Sarga 62, Verse 20', 'किं ते सर्वविनाशेन कृतेन पुरुषर्षभ।
तमेव तु रिपुं पापं विज्ञायोद्धर्तुमर्हसि॥', 'kiṃ te sarvavināśena kṛtena puruṣarṣabha
tam eva tu ripuṃ pāpaṃ vijñāyoddhartum arhasi', null, 3062020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 63 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-63-1', 1, 'Aranya Kanda, Sarga 63, Verse 1', 'पूर्वजोऽप्युक्तमात्रस्तु लक्ष्मणेन सुभाषितम्।
सारग्राही महासारं प्रतिजग्राह राघवः॥', 'pūrvajo ''py uktamātras tu lakṣmaṇena subhāṣitam
sāragrāhī mahāsāraṃ pratijagrāha rāghavaḥ', null, 3063001),
('ramayana-3-63-2', 2, 'Aranya Kanda, Sarga 63, Verse 2', 'संनिगृह्य महाबाहुः प्रवृद्धं कोपमात्मनः।
अवष्टभ्य धनुश्चित्रं रामो लक्ष्मणमब्रवीत्॥', 'saṃnigṛhya mahābāhuḥ pravṛddhaṃ kopam ātmanaḥ
avaṣṭabhya dhanuś citraṃ rāmo lakṣmaṇam abravīt', null, 3063002),
('ramayana-3-63-3', 3, 'Aranya Kanda, Sarga 63, Verse 3', 'किं करिष्यावहे वत्स क्व वा गच्छाव लक्ष्मण।
केनोपायेन पश्येयं सीतामिति विचिन्तय॥', 'kiṃ kariṣyāvahe vatsa kva vā gacchāva lakṣmaṇa
kenopāyena paśyeyaṃ sītām iti vicintaya', null, 3063003),
('ramayana-3-63-4', 4, 'Aranya Kanda, Sarga 63, Verse 4', 'तं तथा परितापार्तं लक्ष्मणो राममब्रवीत्।
इदमेव जनस्थानं त्वमन्वेषितुमर्हसि॥', 'taṃ tathā paritāpārtaṃ lakṣmaṇo rāmam abravīt
idam eva janasthānaṃ tvam anveṣitum arhasi', null, 3063004),
('ramayana-3-63-5', 5, 'Aranya Kanda, Sarga 63, Verse 5', 'राक्षसैर्बहुभिः कीर्णं नानाद्रुमलतायुतम्।
सन्तीह गिरिदुर्गाणि निर्दराः कन्दराणि च॥', 'rākṣasair bahubhiḥ kīrṇaṃ nānādrumalatāyutam
santīha giridurgāṇi nirdarāḥ kandarāṇi ca', null, 3063005),
('ramayana-3-63-6', 6, 'Aranya Kanda, Sarga 63, Verse 6', 'गुहाश्च विविधा घोरा नानामृगगणाकुलाः।
आवासाः किंनराणां च गन्धर्वभवनानि च॥', 'guhāś ca vividhā ghorā nānāmṛgagaṇākulāḥ
āvāsāḥ kiṃnarāṇāṃ ca gandharvabhavanāni ca', null, 3063006),
('ramayana-3-63-7', 7, 'Aranya Kanda, Sarga 63, Verse 7', 'तानि युक्तो मया सार्धं त्वमन्वेषितुमर्हसि।
त्वद्विधो बुद्धिसंपन्ना माहात्मानो नरर्षभ॥', 'tāni yukto mayā sārdhaṃ tvam anveṣitum arhasi
tvadvidho buddhisaṃpannā māhātmāno nararṣabha', null, 3063007),
('ramayana-3-63-8', 8, 'Aranya Kanda, Sarga 63, Verse 8', 'आपत्सु न प्रकम्पन्ते वायुवेगैरिवाचलाः।
इत्युक्तस्तद्वनं सर्वं विचचार सलक्ष्मणः॥', 'āpatsu na prakampante vāyuvegair ivācalāḥ
ity uktas tad vanaṃ sarvaṃ vicacāra salakṣmaṇaḥ', null, 3063008),
('ramayana-3-63-9', 9, 'Aranya Kanda, Sarga 63, Verse 9', 'क्रुद्धो रामः शरं घोरं संधाय धनुषि क्षुरम्।
ततः पर्वतकूटाभं महाभागं द्विजोत्तमम्॥', 'kruddho rāmaḥ śaraṃ ghoraṃ saṃdhāya dhanuṣi kṣuram
tataḥ parvatakūṭābhaṃ mahābhāgaṃ dvijottamam', null, 3063009),
('ramayana-3-63-10', 10, 'Aranya Kanda, Sarga 63, Verse 10', 'ददर्श पतितं भूमौ क्षतजार्द्रं जटायुषम्।
तं दृष्ट्वा गिरिशृङ्गाभं रामो लक्ष्मणमब्रवीत्।
अनेन सीता वैदेही भक्षिता नात्र संशयः॥', 'dadarśa patitaṃ bhūmau kṣatajārdraṃ jaṭāyuṣam
taṃ dṛṣṭvā giriśṛṅgābhaṃ rāmo lakṣmaṇam abravīt
anena sītā vaidehī bhakṣitā nātra saṃśayaḥ', null, 3063010),
('ramayana-3-63-11', 11, 'Aranya Kanda, Sarga 63, Verse 11', 'गृध्ररूपमिदं व्यक्तं रक्षो भ्रमति काननम्।
भक्षयित्वा विशालाक्षीमास्ते सीतां यथासुखम्।
एनं वधिष्ये दीप्ताग्रैर्घोरैर्बाणैरजिह्मगैः॥', 'gṛdhrarūpam idaṃ vyaktaṃ rakṣo bhramati kānanam
bhakṣayitvā viśālākṣīm āste sītāṃ yathāsukham
enaṃ vadhiṣye dīptāgrair ghorair bāṇair ajihmagaiḥ', null, 3063011),
('ramayana-3-63-12', 12, 'Aranya Kanda, Sarga 63, Verse 12', 'इत्युक्त्वाभ्यपतद्गृध्रं संधाय धनुषि क्षुरम्।
क्रुद्धो रामः समुद्रान्तां चालयन्निव मेदिनीम्॥', 'ity uktvābhyapatad gṛdhraṃ saṃdhāya dhanuṣi kṣuram
kruddho rāmaḥ samudrāntāṃ cālayann iva medinīm', null, 3063012),
('ramayana-3-63-13', 13, 'Aranya Kanda, Sarga 63, Verse 13', 'तं दीनदीनया वाचा सफेनं रुधिरं वमन्।
अभ्यभाषत पक्षी तु रामं दशरथात्मजम्॥', 'taṃ dīnadīnayā vācā saphenaṃ rudhiraṃ vaman
abhyabhāṣata pakṣī tu rāmaṃ daśarathātmajam', null, 3063013),
('ramayana-3-63-14', 14, 'Aranya Kanda, Sarga 63, Verse 14', 'यामोषधिमिवायुष्मन्नन्वेषसि महावने।
सा देवी मम च प्राणा रावणेनोभयं हृतम्॥', 'yām oṣadhim ivāyuṣmann anveṣasi mahāvane
sā devī mama ca prāṇā rāvaṇenobhayaṃ hṛtam', null, 3063014),
('ramayana-3-63-15', 15, 'Aranya Kanda, Sarga 63, Verse 15', 'त्वया विरहिता देवी लक्ष्मणेन च राघव।
ह्रियमाणा मया दृष्टा रावणेन बलीयसा॥', 'tvayā virahitā devī lakṣmaṇena ca rāghava
hriyamāṇā mayā dṛṣṭā rāvaṇena balīyasā', null, 3063015),
('ramayana-3-63-16', 16, 'Aranya Kanda, Sarga 63, Verse 16', 'सीतामभ्यवपन्नोऽहं रावणश्च रणे मया।
विध्वंसितरथच्छत्रः पातितो धरणीतले॥', 'sītām abhyavapan no ''haṃ rāvaṇaś ca raṇe mayā
vidhvaṃsitarathacchatraḥ pātito dharaṇītale', null, 3063016),
('ramayana-3-63-17', 17, 'Aranya Kanda, Sarga 63, Verse 17', 'एतदस्य धनुर्भग्नमेतदस्य शरावरम्।
अयमस्य रणे राम भग्नः सांग्रामिको रथः॥', 'etad asya dhanur bhagnam etad asya śarāvaram
ayam asya raṇe rāma bhagnaḥ sāṃgrāmiko rathaḥ', null, 3063017),
('ramayana-3-63-18', 18, 'Aranya Kanda, Sarga 63, Verse 18', 'परिश्रान्तस्य मे पक्षौ छित्त्वा खड्गेन रावणः।
सीतामादाय वैदेहीमुत्पपात विहायसं।
रक्षसा निहतं पूर्व्म न मां हन्तुं त्वमर्हसि॥', 'pariśrāntasya me pakṣau chittvā khaḍgena rāvaṇaḥ
sītām ādāya vaidehīm utpapāta vihāyasaṃ
rakṣasā nihataṃ pūrvma na māṃ hantuṃ tvam arhasi', null, 3063018),
('ramayana-3-63-19', 19, 'Aranya Kanda, Sarga 63, Verse 19', 'रामस्तस्य तु विज्ञाय सीतासक्तां प्रियां कथाम्।
गृध्रराजं परिष्वज्य रुरोद सहलक्ष्मणः॥', 'rāmas tasya tu vijñāya sītāsaktāṃ priyāṃ kathām
gṛdhrarājaṃ pariṣvajya ruroda sahalakṣmaṇaḥ', null, 3063019),
('ramayana-3-63-20', 20, 'Aranya Kanda, Sarga 63, Verse 20', 'एकमेकायने दुर्गे निःश्वसन्तं कथं चन।
समीक्ष्य दुःखितो रामः सौमित्रिमिदमब्रवीत्॥', 'ekam ekāyane durge niḥśvasantaṃ kathaṃ cana
samīkṣya duḥkhito rāmaḥ saumitrim idam abravīt', null, 3063020),
('ramayana-3-63-21', 21, 'Aranya Kanda, Sarga 63, Verse 21', 'राज्याद्भ्रंशो वने वासः सीता नष्टा हतो द्विजः।
ईदृशीयं ममालक्ष्मीर्निर्दहेदपि पावकम्॥', 'rājyād bhraṃśo vane vāsaḥ sītā naṣṭā hato dvijaḥ
īdṛśīyaṃ mamālakṣmīr nirdahed api pāvakam', null, 3063021),
('ramayana-3-63-22', 22, 'Aranya Kanda, Sarga 63, Verse 22', 'संपूर्णमपि चेदद्य प्रतरेयं महोदधिम्।
सोऽपि नूनं ममालक्ष्म्या विशुष्येत्सरितां पतिः॥', 'saṃpūrṇam api ced adya pratareyaṃ mahodadhim
so ''pi nūnaṃ mamālakṣmyā viśuṣyet saritāṃ patiḥ', null, 3063022),
('ramayana-3-63-23', 23, 'Aranya Kanda, Sarga 63, Verse 23', 'नास्त्यभाग्यतरो लोके मत्तोऽस्मिन्सचराचरे।
येनेयं महती प्राप्ता मया व्यसनवागुरा॥', 'nāsty abhāgyataro loke matto ''smin sacarācare
yeneyaṃ mahatī prāptā mayā vyasanavāgurā', null, 3063023),
('ramayana-3-63-24', 24, 'Aranya Kanda, Sarga 63, Verse 24', 'अयं पितृवयस्यो मे गृध्रराजो जरान्वितः।
शेते विनिहतो भूमौ मम भाग्यविपर्ययात्॥', 'ayaṃ pitṛvayasyo me gṛdhrarājo jarānvitaḥ
śete vinihato bhūmau mama bhāgyaviparyayāt', null, 3063024),
('ramayana-3-63-25', 25, 'Aranya Kanda, Sarga 63, Verse 25', 'इत्येवमुक्त्वा बहुशो राघवः सहलक्ष्मणः।
जटायुषं च पस्पर्श पितृस्नेहं निदर्शयन्॥', 'ity evam uktvā bahuśo rāghavaḥ sahalakṣmaṇaḥ
jaṭāyuṣaṃ ca pasparśa pitṛsnehaṃ nidarśayan', null, 3063025),
('ramayana-3-63-26', 26, 'Aranya Kanda, Sarga 63, Verse 26', 'निकृत्तपक्षं रुधिरावसिक्तं तं गृध्रराजं परिरभ्य रामः।
क्व मैथिलि प्राणसमा ममेति विमुच्य वाचं निपपात भूमौ॥', 'nikṛttapakṣaṃ rudhirāvasiktaṃ taṃ gṛdhrarājaṃ parirabhya rāmaḥ
kva maithili prāṇasamā mameti vimucya vācaṃ nipapāta bhūmau', null, 3063026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 64 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-64-1', 1, 'Aranya Kanda, Sarga 64, Verse 1', 'रामः प्रेक्ष्य तु तं गृध्रं भुवि रौद्रेण पातितम्।
सौमित्रिं मित्रसंपन्नमिदं वचनमब्रवीत्॥', 'rāmaḥ prekṣya tu taṃ gṛdhraṃ bhuvi raudreṇa pātitam
saumitriṃ mitrasaṃpannam idaṃ vacanam abravīt', null, 3064001),
('ramayana-3-64-2', 2, 'Aranya Kanda, Sarga 64, Verse 2', 'ममायं नूनमर्थेषु यतमानो विहंगमः।
राक्षसेन हतः संख्ये प्राणांस्त्यजति दुस्त्यजान्॥', 'mamāyaṃ nūnam artheṣu yatamāno vihaṃgamaḥ
rākṣasena hataḥ saṃkhye prāṇāṃs tyajati dustyajān', null, 3064002),
('ramayana-3-64-3', 3, 'Aranya Kanda, Sarga 64, Verse 3', 'अयमस्य शरीरेऽस्मिन्प्राणो लक्ष्मण विद्यते।
तथा स्वरविहीनोऽयं विक्लवं समुदीक्षते॥', 'ayam asya śarīre ''smin prāṇo lakṣmaṇa vidyate
tathā svaravihīno ''yaṃ viklavaṃ samudīkṣate', null, 3064003),
('ramayana-3-64-4', 4, 'Aranya Kanda, Sarga 64, Verse 4', 'जटायो यदि शक्नोषि वाक्यं व्याहरितुं पुनः।
सीतामाख्याहि भद्रं ते वधमाख्याहि चात्मनः॥', 'jaṭāyo yadi śaknoṣi vākyaṃ vyāharituṃ punaḥ
sītām ākhyāhi bhadraṃ te vadham ākhyāhi cātmanaḥ', null, 3064004),
('ramayana-3-64-5', 5, 'Aranya Kanda, Sarga 64, Verse 5', 'किंनिमित्तोऽहरत्सीतां रावणस्तस्य किं मया।
अपराद्धं तु यं दृष्ट्वा रावणेन हृता प्रिया॥', 'kiṃnimitto ''harat sītāṃ rāvaṇas tasya kiṃ mayā
aparāddhaṃ tu yaṃ dṛṣṭvā rāvaṇena hṛtā priyā', null, 3064005),
('ramayana-3-64-6', 6, 'Aranya Kanda, Sarga 64, Verse 6', 'कथं तच्चन्द्रसंकाशं मुखमासीन्मनोहरम्।
सीतया कानि चोक्तानि तस्मिन्काले द्विजोत्तम॥', 'kathaṃ tac candrasaṃkāśaṃ mukham āsīn manoharam
sītayā kāni coktāni tasmin kāle dvijottama', null, 3064006),
('ramayana-3-64-7', 7, 'Aranya Kanda, Sarga 64, Verse 7', 'कथंवीर्यः कथंरूपः किंकर्मा स च राक्षसः।
क्व चास्य भवनं तात ब्रूहि मे परिपृच्छतः॥', 'kathaṃvīryaḥ kathaṃrūpaḥ kiṃkarmā sa ca rākṣasaḥ
kva cāsya bhavanaṃ tāta brūhi me paripṛcchataḥ', null, 3064007),
('ramayana-3-64-8', 8, 'Aranya Kanda, Sarga 64, Verse 8', 'तमुद्वीक्ष्याथ दीनात्मा विलपन्तमनन्तरम्।
वाचातिसन्नया रामं जटायुरिदमब्रवीत्॥', 'tam udvīkṣyātha dīnātmā vilapantam anantaram
vācātisannayā rāmaṃ jaṭāyur idam abravīt', null, 3064008),
('ramayana-3-64-9', 9, 'Aranya Kanda, Sarga 64, Verse 9', 'सा हृता राक्षसेन्द्रेण रावणेन विहायसा।
मायामास्थाय विपुलां वातदुर्दिनसंकुलाम्॥', 'sā hṛtā rākṣasendreṇa rāvaṇena vihāyasā
māyām āsthāya vipulāṃ vātadurdinasaṃkulām', null, 3064009),
('ramayana-3-64-10', 10, 'Aranya Kanda, Sarga 64, Verse 10', 'परिश्रान्तस्य मे तात पक्षौ छित्त्वा निशाचरः।
सीतामादाय वैदेहीं प्रयातो दक्षिणा मुखः॥', 'pariśrāntasya me tāta pakṣau chittvā niśācaraḥ
sītām ādāya vaidehīṃ prayāto dakṣiṇā mukhaḥ', null, 3064010),
('ramayana-3-64-11', 11, 'Aranya Kanda, Sarga 64, Verse 11', 'उपरुध्यन्ति मे प्राणा दृष्टिर्भ्रमति राघव।
पश्यामि वृक्षान्सौवर्णानुशीरकृतमूर्धजान्॥', 'uparudhyanti me prāṇā dṛṣṭir bhramati rāghava
paśyāmi vṛkṣān sauvarṇān uśīrakṛtamūrdhajān', null, 3064011),
('ramayana-3-64-12', 12, 'Aranya Kanda, Sarga 64, Verse 12', 'येन याति मुहूर्तेन सीतामादाय रावणः।
विप्रनष्टं धनं क्षिप्रं तत्स्वामिप्रतिपद्यते॥', 'yena yāti muhūrtena sītām ādāya rāvaṇaḥ
vipranaṣṭaṃ dhanaṃ kṣipraṃ tat svāmipratipadyate', null, 3064012),
('ramayana-3-64-13', 13, 'Aranya Kanda, Sarga 64, Verse 13', 'विन्दो नाम मुहूर्तोऽसौ स च काकुत्स्थ नाबुधत्।
झषवद्बडिशं गृह्य क्षिप्रमेव विनश्यति॥', 'vindo nāma muhūrto ''sau sa ca kākutstha nābudhat
jhaṣavad baḍiśaṃ gṛhya kṣipram eva vinaśyati', null, 3064013),
('ramayana-3-64-14', 14, 'Aranya Kanda, Sarga 64, Verse 14', 'न च त्वया व्यथा कार्या जनकस्य सुतां प्रति।
वैदेह्या रंस्यसे क्षिप्रं हत्वा तं राक्षसं रणे॥', 'na ca tvayā vyathā kāryā janakasya sutāṃ prati
vaidehyā raṃsyase kṣipraṃ hatvā taṃ rākṣasaṃ raṇe', null, 3064014),
('ramayana-3-64-15', 15, 'Aranya Kanda, Sarga 64, Verse 15', 'असंमूढस्य गृध्रस्य रामं प्रत्यनुभाषतः।
आस्यात्सुस्राव रुधिरं म्रियमाणस्य सामिषम्॥', 'asaṃmūḍhasya gṛdhrasya rāmaṃ pratyanubhāṣataḥ
āsyāt susrāva rudhiraṃ mriyamāṇasya sāmiṣam', null, 3064015),
('ramayana-3-64-16', 16, 'Aranya Kanda, Sarga 64, Verse 16', 'पुत्रो विश्रवसः साक्षाद्भ्राता वैश्रवणस्य च।
इत्युक्त्वा दुर्लभान्प्राणान्मुमोच पतगेश्वरः॥', 'putro viśravasaḥ sākṣād bhrātā vaiśravaṇasya ca
ity uktvā durlabhān prāṇān mumoca patageśvaraḥ', null, 3064016),
('ramayana-3-64-17', 17, 'Aranya Kanda, Sarga 64, Verse 17', 'ब्रूहि ब्रूहीति रामस्य ब्रुवाणस्य कृताञ्जलेः।
त्यक्त्वा शरीरं गृध्रस्य जग्मुः प्राणा विहायसं॥', 'brūhi brūhīti rāmasya bruvāṇasya kṛtāñjaleḥ
tyaktvā śarīraṃ gṛdhrasya jagmuḥ prāṇā vihāyasaṃ', null, 3064017),
('ramayana-3-64-18', 18, 'Aranya Kanda, Sarga 64, Verse 18', 'स निक्षिप्य शिरो भूमौ प्रसार्य चरणौ तदा।
विक्षिप्य च शरीरं स्वं पपात धरणीतले॥', 'sa nikṣipya śiro bhūmau prasārya caraṇau tadā
vikṣipya ca śarīraṃ svaṃ papāta dharaṇītale', null, 3064018),
('ramayana-3-64-19', 19, 'Aranya Kanda, Sarga 64, Verse 19', 'तं गृध्रं प्रेक्ष्य ताम्राक्षं गतासुमचलोपमम्।
रामः सुबहुभिर्दुःखैर्दीनः सौमित्रिमब्रवीत्॥', 'taṃ gṛdhraṃ prekṣya tāmrākṣaṃ gatāsum acalopamam
rāmaḥ subahubhir duḥkhair dīnaḥ saumitrim abravīt', null, 3064019),
('ramayana-3-64-20', 20, 'Aranya Kanda, Sarga 64, Verse 20', 'बहूनि रक्षसां वासे वर्षाणि वसता सुखम्।
अनेन दण्डकारण्ये विचीर्णमिह पक्षिणा॥', 'bahūni rakṣasāṃ vāse varṣāṇi vasatā sukham
anena daṇḍakāraṇye vicīrṇam iha pakṣiṇā', null, 3064020),
('ramayana-3-64-21', 21, 'Aranya Kanda, Sarga 64, Verse 21', 'अनेकवार्षिको यस्तु चिरकालं समुत्थितः।
सोऽयमद्य हतः शेते कालो हि दुरतिक्रमः॥', 'anekavārṣiko yas tu cirakālaṃ samutthitaḥ
so ''yam adya hataḥ śete kālo hi duratikramaḥ', null, 3064021),
('ramayana-3-64-22', 22, 'Aranya Kanda, Sarga 64, Verse 22', 'पश्य लक्ष्मण गृध्रोऽयमुपकारी हतश्च मे।
सीतामभ्यवपन्नो वै रावणेन बलीयसा॥', 'paśya lakṣmaṇa gṛdhro ''yam upakārī hataś ca me
sītām abhyavapan no vai rāvaṇena balīyasā', null, 3064022),
('ramayana-3-64-23', 23, 'Aranya Kanda, Sarga 64, Verse 23', 'गृध्रराज्यं परित्यज्य पितृपैतामहं महत्।
मम हेतोरयं प्राणान्मुमोच पतगेश्वरः॥', 'gṛdhrarājyaṃ parityajya pitṛpaitāmahaṃ mahat
mama hetor ayaṃ prāṇān mumoca patageśvaraḥ', null, 3064023),
('ramayana-3-64-24', 24, 'Aranya Kanda, Sarga 64, Verse 24', 'सर्वत्र खलु दृश्यन्ते साधवो धर्मचारिणः।
शूराः शरण्याः सौमित्रे तिर्यग्योनिगतेष्वपि॥', 'sarvatra khalu dṛśyante sādhavo dharmacāriṇaḥ
śūrāḥ śaraṇyāḥ saumitre tiryagyonigateṣv api', null, 3064024),
('ramayana-3-64-25', 25, 'Aranya Kanda, Sarga 64, Verse 25', 'सीताहरणजं दुःखं न मे सौम्य तथागतम्।
यथा विनाशो गृध्रस्य मत्कृते च परंतप॥', 'sītāharaṇajaṃ duḥkhaṃ na me saumya tathāgatam
yathā vināśo gṛdhrasya matkṛte ca paraṃtapa', null, 3064025),
('ramayana-3-64-26', 26, 'Aranya Kanda, Sarga 64, Verse 26', 'राजा दशरथः श्रीमान्यथा मम मया यशाः।
पूजनीयश्च मान्यश्च तथायं पतगेश्वरः॥', 'rājā daśarathaḥ śrīmān yathā mama mayā yaśāḥ
pūjanīyaś ca mānyaś ca tathāyaṃ patageśvaraḥ', null, 3064026),
('ramayana-3-64-27', 27, 'Aranya Kanda, Sarga 64, Verse 27', 'सौमित्रे हर काष्ठानि निर्मथिष्यामि पावकम्।
गृध्रराजं दिधक्षामि मत्कृते निधनं गतम्॥', 'saumitre hara kāṣṭhāni nirmathiṣyāmi pāvakam
gṛdhrarājaṃ didhakṣāmi matkṛte nidhanaṃ gatam', null, 3064027),
('ramayana-3-64-28', 28, 'Aranya Kanda, Sarga 64, Verse 28', 'नाथं पतगलोकस्य चितामारोपयाम्यहम्।
इमं धक्ष्यामि सौमित्रे हतं रौद्रेण रक्षसा॥', 'nāthaṃ patagalokasya citām āropayāmy aham
imaṃ dhakṣyāmi saumitre hataṃ raudreṇa rakṣasā', null, 3064028),
('ramayana-3-64-29', 29, 'Aranya Kanda, Sarga 64, Verse 29', 'या गतिर्यज्ञशीलानामाहिताग्नेश्च या गतिः।
अपरावर्तिनां या च या च भूमिप्रदायिनाम्॥', 'yā gatir yajñaśīlānām āhitāgneś ca yā gatiḥ
aparāvartināṃ yā ca yā ca bhūmipradāyinām', null, 3064029),
('ramayana-3-64-30', 30, 'Aranya Kanda, Sarga 64, Verse 30', 'मया त्वं समनुज्ञातो गच्छ लोकाननुत्तमान्।
गृध्रराज महासत्त्व संस्कृतश्च मया व्रज॥', 'mayā tvaṃ samanujñāto gaccha lokān anuttamān
gṛdhrarāja mahāsattva saṃskṛtaś ca mayā vraja', null, 3064030),
('ramayana-3-64-31', 31, 'Aranya Kanda, Sarga 64, Verse 31', 'एवमुक्त्वा चितां दीप्तामारोप्य पतगेश्वरम्।
ददाह रामो धर्मात्मा स्वबन्धुमिव दुःखितः॥', 'evam uktvā citāṃ dīptām āropya patageśvaram
dadāha rāmo dharmātmā svabandhum iva duḥkhitaḥ', null, 3064031),
('ramayana-3-64-32', 32, 'Aranya Kanda, Sarga 64, Verse 32', 'रामोऽथ सहसौमित्रिर्वनं यात्वा स वीर्यवान्।
स्थूलान्हत्वा महारोहीननु तस्तार तं द्विजम्॥', 'rāmo ''tha sahasaumitrir vanaṃ yātvā sa vīryavān
sthūlān hatvā mahārohīn anu tastāra taṃ dvijam', null, 3064032),
('ramayana-3-64-33', 33, 'Aranya Kanda, Sarga 64, Verse 33', 'रोहिमांसानि चोद्धृत्य पेशीकृत्वा महायशाः।
शकुनाय ददौ रामो रम्ये हरितशाद्वले॥', 'rohimāṃsāni coddhṛtya peśīkṛtvā mahāyaśāḥ
śakunāya dadau rāmo ramye haritaśādvale', null, 3064033),
('ramayana-3-64-34', 34, 'Aranya Kanda, Sarga 64, Verse 34', 'यत्तत्प्रेतस्य मर्त्यस्य कथयन्ति द्विजातयः।
तत्स्वर्गगमनं तस्य क्षिप्रं रामो जजाप ह॥', 'yat tat pretasya martyasya kathayanti dvijātayaḥ
tat svargagamanaṃ tasya kṣipraṃ rāmo jajāpa ha', null, 3064034),
('ramayana-3-64-35', 35, 'Aranya Kanda, Sarga 64, Verse 35', 'ततो गोदावरीं गत्वा नदीं नरवरात्मजौ।
उदकं चक्रतुस्तस्मै गृध्रराजाय तावुभौ॥', 'tato godāvarīṃ gatvā nadīṃ naravarātmajau
udakaṃ cakratus tasmai gṛdhrarājāya tāv ubhau', null, 3064035),
('ramayana-3-64-36', 36, 'Aranya Kanda, Sarga 64, Verse 36', 'स गृध्रराजः कृतवान्यशस्करं सुदुष्करं कर्म रणे निपातितः।
महर्षिकल्पेन च संस्कृतस्तदा जगाम पुण्यां गतिमात्मनः शुभाम्॥', 'sa gṛdhrarājaḥ kṛtavān yaśaskaraṃ suduṣkaraṃ karma raṇe nipātitaḥ
maharṣikalpena ca saṃskṛtas tadā jagāma puṇyāṃ gatim ātmanaḥ śubhām', null, 3064036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 65 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-65-1', 1, 'Aranya Kanda, Sarga 65, Verse 1', 'कृत्वैवमुदकं तस्मै प्रस्थितौ राघवौ तदा।
अवेक्षन्तौ वने सीतां पश्चिमां जग्मतुर्दिशम्॥', 'kṛtvaivam udakaṃ tasmai prasthitau rāghavau tadā
avekṣantau vane sītāṃ paścimāṃ jagmatur diśam', null, 3065001),
('ramayana-3-65-2', 2, 'Aranya Kanda, Sarga 65, Verse 2', 'तां दिशं दक्षिणां गत्वा शरचापासिधारिणौ।
अविप्रहतमैक्ष्वाकौ पन्थानं प्रतिपेदतुः॥', 'tāṃ diśaṃ dakṣiṇāṃ gatvā śaracāpāsidhāriṇau
aviprahatam aikṣvākau panthānaṃ pratipedatuḥ', null, 3065002),
('ramayana-3-65-3', 3, 'Aranya Kanda, Sarga 65, Verse 3', 'गुल्मैर्वृक्षैश्च बहुभिर्लताभिश्च प्रवेष्टितम्।
आवृतं सर्वतो दुर्गं गहनं घोरदर्शनम्॥', 'gulmair vṛkṣaiś ca bahubhir latābhiś ca praveṣṭitam
āvṛtaṃ sarvato durgaṃ gahanaṃ ghoradarśanam', null, 3065003),
('ramayana-3-65-4', 4, 'Aranya Kanda, Sarga 65, Verse 4', 'व्यतिक्रम्य तु वेगेन गृहीत्वा दक्षिणां दिशम्।
सुभीमं तन्महारण्यं व्यतियातौ महाबलौ॥', 'vyatikramya tu vegena gṛhītvā dakṣiṇāṃ diśam
subhīmaṃ tan mahāraṇyaṃ vyatiyātau mahābalau', null, 3065004),
('ramayana-3-65-5', 5, 'Aranya Kanda, Sarga 65, Verse 5', 'ततः परं जनस्थानात्त्रिक्रोशं गम्य राघवौ।
क्रौञ्चारण्यं विविशतुर्गहनं तौ महौजसौ॥', 'tataḥ paraṃ janasthānāt trikrośaṃ gamya rāghavau
krauñcāraṇyaṃ viviśatur gahanaṃ tau mahaujasau', null, 3065005),
('ramayana-3-65-6', 6, 'Aranya Kanda, Sarga 65, Verse 6', 'नानामेघघनप्रख्यं प्रहृष्टमिव सर्वतः।
नानावर्णैः शुभैः पुष्पैर्मृगपक्षिगणैर्युतम्॥', 'nānāmeghaghanaprakhyaṃ prahṛṣṭam iva sarvataḥ
nānāvarṇaiḥ śubhaiḥ puṣpair mṛgapakṣigaṇair yutam', null, 3065006),
('ramayana-3-65-7', 7, 'Aranya Kanda, Sarga 65, Verse 7', 'दिदृक्षमाणौ वैदेहीं तद्वनं तौ विचिक्यतुः।
तत्र तत्रावतिष्ठन्तौ सीताहरणकर्शितौ॥', 'didṛkṣamāṇau vaidehīṃ tad vanaṃ tau vicikyatuḥ
tatra tatrāvatiṣṭhantau sītāharaṇakarśitau', null, 3065007),
('ramayana-3-65-8', 8, 'Aranya Kanda, Sarga 65, Verse 8', 'लक्ष्मणस्तु महातेजाः सत्त्ववाञ्शीलवाञ्शुचिः।
अब्रवीत्प्राञ्जलिर्वाक्यं भ्रातरं दीप्ततेजसं॥', 'lakṣmaṇas tu mahātejāḥ sattvavāñ śīlavāñ śuciḥ
abravīt prāñjalir vākyaṃ bhrātaraṃ dīptatejasaṃ', null, 3065008),
('ramayana-3-65-9', 9, 'Aranya Kanda, Sarga 65, Verse 9', 'स्पन्दते मे दृढं बाहुरुद्विग्नमिव मे मनः।
प्रायशश्चाप्यनिष्टानि निमित्तान्युपलक्षये॥', 'spandate me dṛḍhaṃ bāhur udvignam iva me manaḥ
prāyaśaś cāpy aniṣṭāni nimittāny upalakṣaye', null, 3065009),
('ramayana-3-65-10', 10, 'Aranya Kanda, Sarga 65, Verse 10', 'तस्मात्सज्जीभवार्य त्वं कुरुष्व वचनं हितम्।
ममैव हि निमित्तानि सद्यः शंसन्ति संभ्रमम्॥', 'tasmāt sajjībhavārya tvaṃ kuruṣva vacanaṃ hitam
mamaiva hi nimittāni sadyaḥ śaṃsanti saṃbhramam', null, 3065010),
('ramayana-3-65-11', 11, 'Aranya Kanda, Sarga 65, Verse 11', 'एष वञ्चुलको नाम पक्षी परमदारुणः।
आवयोर्विजयं युद्धे शंसन्निव विनर्दति॥', 'eṣa vañculako nāma pakṣī paramadāruṇaḥ
āvayor vijayaṃ yuddhe śaṃsann iva vinardati', null, 3065011),
('ramayana-3-65-12', 12, 'Aranya Kanda, Sarga 65, Verse 12', 'तयोरन्वेषतोरेवं सर्वं तद्वनमोजसा।
संजज्ञे विपुलः शब्दः प्रभञ्जन्निव तद्वनम्॥', 'tayor anveṣator evaṃ sarvaṃ tad vanam ojasā
saṃjajñe vipulaḥ śabdaḥ prabhañjann iva tad vanam', null, 3065012),
('ramayana-3-65-13', 13, 'Aranya Kanda, Sarga 65, Verse 13', 'संवेष्टितमिवात्यर्थं गहनं मातरिश्वना।
वनस्य तस्य शब्दोऽभूद्दिवमापूरयन्निव॥', 'saṃveṣṭitam ivātyarthaṃ gahanaṃ mātariśvanā
vanasya tasya śabdo ''bhūd divam āpūrayann iva', null, 3065013),
('ramayana-3-65-14', 14, 'Aranya Kanda, Sarga 65, Verse 14', 'तं शब्दं काङ्क्षमाणस्तु रामः कक्षे सहानुजः।
ददर्श सुमहाकायं राक्षसं विपुलोरसं॥', 'taṃ śabdaṃ kāṅkṣamāṇas tu rāmaḥ kakṣe sahānujaḥ
dadarśa sumahākāyaṃ rākṣasaṃ vipulorasaṃ', null, 3065014),
('ramayana-3-65-15', 15, 'Aranya Kanda, Sarga 65, Verse 15', 'आसेदतुस्ततस्तत्र तावुभौ प्रमुखे स्थितम्।
विवृद्धमशिरोग्रीवं कबन्धमुदरे मुखम्॥', 'āsedatus tatas tatra tāv ubhau pramukhe sthitam
vivṛddham aśirogrīvaṃ kabandham udare mukham', null, 3065015),
('ramayana-3-65-16', 16, 'Aranya Kanda, Sarga 65, Verse 16', 'रोमभिर्निचितैस्तीक्ष्णैर्महागिरिमिवोच्छ्रितम्।
नीलमेघनिभं रौद्रं मेघस्तनितनिःस्वनम्॥', 'romabhir nicitais tīkṣṇair mahāgirim ivocchritam
nīlameghanibhaṃ raudraṃ meghastanitaniḥsvanam', null, 3065016),
('ramayana-3-65-17', 17, 'Aranya Kanda, Sarga 65, Verse 17', 'महापक्ष्मेण पिङ्गेन विपुलेनायतेन च।
एकेनोरसि घोरेण नयनेनाशुदर्शिना॥', 'mahāpakṣmeṇa piṅgena vipulenāyatena ca
ekenorasi ghoreṇa nayanenāśudarśinā', null, 3065017),
('ramayana-3-65-18', 18, 'Aranya Kanda, Sarga 65, Verse 18', 'महादंष्ट्रोपपन्नं तं लेलिहानं महामुखम्।
भक्षयन्तं महाघोरानृक्षसिंहमृगद्विपान्॥', 'mahādaṃṣṭropapannaṃ taṃ lelihānaṃ mahāmukham
bhakṣayantaṃ mahāghorān ṛkṣasiṃhamṛgadvipān', null, 3065018),
('ramayana-3-65-19', 19, 'Aranya Kanda, Sarga 65, Verse 19', 'घोरौ भुजौ विकुर्वाणमुभौ योजनमायतौ।
कराभ्यां विविधान्गृह्य ऋष्कान्पक्षिगणान्मृगान्॥', 'ghorau bhujau vikurvāṇam ubhau yojanam āyatau
karābhyāṃ vividhān gṛhya ṛṣkān pakṣigaṇān mṛgān', null, 3065019),
('ramayana-3-65-20', 20, 'Aranya Kanda, Sarga 65, Verse 20', 'आकर्षन्तं विकर्षन्तमनेकान्मृगयूथपान्।
स्थितमावृत्य पन्थानं तयोर्भ्रात्रोः प्रपन्नयोः॥', 'ākarṣantaṃ vikarṣantam anekān mṛgayūthapān
sthitam āvṛtya panthānaṃ tayor bhrātroḥ prapannayoḥ', null, 3065020),
('ramayana-3-65-21', 21, 'Aranya Kanda, Sarga 65, Verse 21', 'अथ तौ समतिक्रम्य क्रोशमात्रे ददर्शतुः।
महान्तं दारुणं भीमं कबन्धं भुजसंवृतम्॥', 'atha tau samatikramya krośamātre dadarśatuḥ
mahāntaṃ dāruṇaṃ bhīmaṃ kabandhaṃ bhujasaṃvṛtam', null, 3065021),
('ramayana-3-65-22', 22, 'Aranya Kanda, Sarga 65, Verse 22', 'स महाबाहुरत्यर्थं प्रसार्य विपुलौ भुजौ।
जग्राह सहितावेव राघवौ पीडयन्बलात्॥', 'sa mahābāhur atyarthaṃ prasārya vipulau bhujau
jagrāha sahitāv eva rāghavau pīḍayan balāt', null, 3065022),
('ramayana-3-65-23', 23, 'Aranya Kanda, Sarga 65, Verse 23', 'खड्गिनौ दृढधन्वानौ तिग्मतेजौ महाभुजौ।
भ्रातरौ विवशं प्राप्तौ कृष्यमाणौ महाबलौ॥', 'khaḍginau dṛḍhadhanvānau tigmatejau mahābhujau
bhrātarau vivaśaṃ prāptau kṛṣyamāṇau mahābalau', null, 3065023),
('ramayana-3-65-24', 24, 'Aranya Kanda, Sarga 65, Verse 24', 'तावुवाच महाबाहुः कबन्धो दानवोत्तमः।
कौ युवां वृषभस्कन्धौ महाखड्गधनुर्धरौ॥', 'tāv uvāca mahābāhuḥ kabandho dānavottamaḥ
kau yuvāṃ vṛṣabhaskandhau mahākhaḍgadhanurdharau', null, 3065024),
('ramayana-3-65-25', 25, 'Aranya Kanda, Sarga 65, Verse 25', 'घोरं देशमिमं प्राप्तौ मम भक्षावुपस्थितौ।
वदतं कार्यमिह वां किमर्थं चागतौ युवाम्॥', 'ghoraṃ deśam imaṃ prāptau mama bhakṣāv upasthitau
vadataṃ kāryam iha vāṃ kimarthaṃ cāgatau yuvām', null, 3065025),
('ramayana-3-65-26', 26, 'Aranya Kanda, Sarga 65, Verse 26', 'इमं देशमनुप्राप्तौ क्षुधार्तस्येह तिष्ठतः।
सबाणचापखड्गौ च तीक्ष्णशृङ्गाविवर्षभौ।
ममास्यमनुसंप्राप्तौ दुर्लभं जीवितं पुनः॥', 'imaṃ deśam anuprāptau kṣudhārtasyeha tiṣṭhataḥ
sabāṇacāpakhaḍgau ca tīkṣṇaśṛṅgāv ivarṣabhau
mamāsyam anusaṃprāptau durlabhaṃ jīvitaṃ punaḥ', null, 3065026),
('ramayana-3-65-27', 27, 'Aranya Kanda, Sarga 65, Verse 27', 'तस्य तद्वचनं श्रुत्वा कबन्धस्य दुरात्मनः।
उवाच लक्ष्मणं रामो मुखेन परिशुष्यता॥', 'tasya tad vacanaṃ śrutvā kabandhasya durātmanaḥ
uvāca lakṣmaṇaṃ rāmo mukhena pariśuṣyatā', null, 3065027),
('ramayana-3-65-28', 28, 'Aranya Kanda, Sarga 65, Verse 28', 'कृच्छ्रात्कृच्छ्रतरं प्राप्य दारुणं सत्यविक्रम।
व्यसनं जीवितान्ताय प्राप्तमप्राप्य तां प्रियाम्॥', 'kṛcchrāt kṛcchrataraṃ prāpya dāruṇaṃ satyavikrama
vyasanaṃ jīvitāntāya prāptam aprāpya tāṃ priyām', null, 3065028),
('ramayana-3-65-29', 29, 'Aranya Kanda, Sarga 65, Verse 29', 'कालस्य सुमहद्वीर्यं सर्वभूतेषु लक्ष्मण।
त्वां च मां च नरव्याघ्र व्यसनैः पश्य मोहितौ।
नातिभारोऽस्ति दैवस्य सर्वभुतेषु लक्ष्मण॥', 'kālasya sumahad vīryaṃ sarvabhūteṣu lakṣmaṇa
tvāṃ ca māṃ ca naravyāghra vyasanaiḥ paśya mohitau
nātibhāro ''sti daivasya sarvabhuteṣu lakṣmaṇa', null, 3065029),
('ramayana-3-65-30', 30, 'Aranya Kanda, Sarga 65, Verse 30', 'शूराश्च बलवन्तश्च कृतास्त्राश्च रणाजिरे।
कालाभिपन्नाः सीदन्ति यथा वालुकसेतवः॥', 'śūrāś ca balavantaś ca kṛtāstrāś ca raṇājire
kālābhipannāḥ sīdanti yathā vālukasetavaḥ', null, 3065030),
('ramayana-3-65-31', 31, 'Aranya Kanda, Sarga 65, Verse 31', 'इति ब्रुवाणो दृढसत्यविक्रमो महायशा दाशरथिः प्रतापवान्।
अवेक्ष्य सौमित्रिमुदग्रविक्रमं स्थिरां तदा स्वां मतिमात्मनाकरोत्॥', 'iti bruvāṇo dṛḍhasatyavikramo mahāyaśā dāśarathiḥ pratāpavān
avekṣya saumitrim udagravikramaṃ sthirāṃ tadā svāṃ matim ātmanākarot', null, 3065031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 66 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-66-1', 1, 'Aranya Kanda, Sarga 66, Verse 1', 'तौ तु तत्र स्थितौ दृष्ट्वा भ्रातरौ रामलक्ष्मणौ।
बाहुपाशपरिक्षिप्तौ कबन्धो वाक्यमब्रवीत्॥', 'tau tu tatra sthitau dṛṣṭvā bhrātarau rāmalakṣmaṇau
bāhupāśaparikṣiptau kabandho vākyam abravīt', null, 3066001),
('ramayana-3-66-2', 2, 'Aranya Kanda, Sarga 66, Verse 2', 'तिष्ठतः किं नु मां दृष्ट्वा क्षुधार्तं क्षत्रियर्षभौ।
आहारार्थं तु संदिष्टौ दैवेन गतचेतसौ॥', 'tiṣṭhataḥ kiṃ nu māṃ dṛṣṭvā kṣudhārtaṃ kṣatriyarṣabhau
āhārārthaṃ tu saṃdiṣṭau daivena gatacetasau', null, 3066002),
('ramayana-3-66-3', 3, 'Aranya Kanda, Sarga 66, Verse 3', 'तच्छ्रुत्वा लक्ष्मणो वाक्यं प्राप्तकालं हितं तदा।
उवाचार्तिसमापन्नो विक्रमे कृतनिश्चयः॥', 'tac chrutvā lakṣmaṇo vākyaṃ prāptakālaṃ hitaṃ tadā
uvācārtisamāpanno vikrame kṛtaniścayaḥ', null, 3066003),
('ramayana-3-66-4', 4, 'Aranya Kanda, Sarga 66, Verse 4', 'त्वां च मां च पुरा तूर्णमादत्ते राक्षसाधमः।
तस्मादसिभ्यामस्याशु बाहू छिन्दावहे गुरू॥', 'tvāṃ ca māṃ ca purā tūrṇam ādatte rākṣasādhamaḥ
tasmād asibhyām asyāśu bāhū chindāvahe gurū', null, 3066004),
('ramayana-3-66-5', 5, 'Aranya Kanda, Sarga 66, Verse 5', 'ततस्तौ देशकालज्ञौ खड्गाभ्यामेव राघवौ।
अच्छिन्दतां सुसंहृष्टौ बाहू तस्यांसदेशयोः॥', 'tatas tau deśakālajñau khaḍgābhyām eva rāghavau
acchindatāṃ susaṃhṛṣṭau bāhū tasyāṃsadeśayoḥ', null, 3066005),
('ramayana-3-66-6', 6, 'Aranya Kanda, Sarga 66, Verse 6', 'दक्षिणो दक्षिणं बाहुमसक्तमसिना ततः।
चिच्छेद रामो वेगेन सव्यं वीरस्तु लक्ष्मणः॥', 'dakṣiṇo dakṣiṇaṃ bāhum asaktam asinā tataḥ
ciccheda rāmo vegena savyaṃ vīras tu lakṣmaṇaḥ', null, 3066006),
('ramayana-3-66-7', 7, 'Aranya Kanda, Sarga 66, Verse 7', 'स पपात महाबाहुश्छिन्नबाहुर्महास्वनः।
खं च गां च दिशश्चैव नादयञ्जलदो यथा॥', 'sa papāta mahābāhuś chinnabāhur mahāsvanaḥ
khaṃ ca gāṃ ca diśaś caiva nādayañ jalado yathā', null, 3066007),
('ramayana-3-66-8', 8, 'Aranya Kanda, Sarga 66, Verse 8', 'स निकृत्तौ भुजौ दृष्ट्वा शोणितौघपरिप्लुतः।
दीनः पप्रच्छ तौ वीरौ कौ युवामिति दानवः॥', 'sa nikṛttau bhujau dṛṣṭvā śoṇitaughapariplutaḥ
dīnaḥ papraccha tau vīrau kau yuvām iti dānavaḥ', null, 3066008),
('ramayana-3-66-9', 9, 'Aranya Kanda, Sarga 66, Verse 9', 'इति तस्य ब्रुवाणस्य लक्ष्मणः शुभलक्षणः।
शशंस तस्य काकुत्स्थं कबन्धस्य महाबलः॥', 'iti tasya bruvāṇasya lakṣmaṇaḥ śubhalakṣaṇaḥ
śaśaṃsa tasya kākutsthaṃ kabandhasya mahābalaḥ', null, 3066009),
('ramayana-3-66-10', 10, 'Aranya Kanda, Sarga 66, Verse 10', 'अयमिक्ष्वाकुदायादो रामो नाम जनैः श्रुतः।
अस्यैवावरजं विद्धि भ्रातरं मां च लक्ष्मणम्॥', 'ayam ikṣvākudāyādo rāmo nāma janaiḥ śrutaḥ
asyaivāvarajaṃ viddhi bhrātaraṃ māṃ ca lakṣmaṇam', null, 3066010),
('ramayana-3-66-11', 11, 'Aranya Kanda, Sarga 66, Verse 11', 'अस्य देवप्रभावस्य वसतो विजने वने।
रक्षसापहृता भार्या यामिच्छन्ताविहागतौ॥', 'asya devaprabhāvasya vasato vijane vane
rakṣasāpahṛtā bhāryā yām icchantāv ihāgatau', null, 3066011),
('ramayana-3-66-12', 12, 'Aranya Kanda, Sarga 66, Verse 12', 'त्वं तु को वा किमर्थं वा कबन्ध सदृशो वने।
आस्येनोरसि दीप्तेन भग्नजङ्घो विचेष्टसे॥', 'tvaṃ tu ko vā kimarthaṃ vā kabandha sadṛśo vane
āsyenorasi dīptena bhagnajaṅgho viceṣṭase', null, 3066012),
('ramayana-3-66-13', 13, 'Aranya Kanda, Sarga 66, Verse 13', 'एवमुक्तः कबन्धस्तु लक्ष्मणेनोत्तरं वचः।
उवाच परमप्रीतस्तदिन्द्रवचनं स्मरन्॥', 'evam uktaḥ kabandhas tu lakṣmaṇenottaraṃ vacaḥ
uvāca paramaprītas tad indravacanaṃ smaran', null, 3066013),
('ramayana-3-66-14', 14, 'Aranya Kanda, Sarga 66, Verse 14', 'स्वागतं वां नरव्याघ्रौ दिष्ट्या पश्यामि चाप्यहम्।
दिष्ट्या चेमौ निकृत्तौ मे युवाभ्यां बाहुबन्धनौ॥', 'svāgataṃ vāṃ naravyāghrau diṣṭyā paśyāmi cāpy aham
diṣṭyā cemau nikṛttau me yuvābhyāṃ bāhubandhanau', null, 3066014),
('ramayana-3-66-15', 15, 'Aranya Kanda, Sarga 66, Verse 15', 'विरूपं यच्च मे रूपं प्राप्तं ह्यविनयाद्यथा।
तन्मे शृणु नरव्याघ्र तत्त्वतः शंसतस्तव॥', 'virūpaṃ yac ca me rūpaṃ prāptaṃ hy avinayād yathā
tan me śṛṇu naravyāghra tattvataḥ śaṃsatas tava', null, 3066015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 67 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-67-1', 1, 'Aranya Kanda, Sarga 67, Verse 1', 'पुरा राम महाबाहो महाबलपराक्रम।
रूपमासीन्ममाचिन्त्यं त्रिषु लोकेषु विश्रुतम्।
यथा सोमस्य शक्रस्य सूर्यस्य च यथा वपुः॥', 'purā rāma mahābāho mahābalaparākrama
rūpam āsīn mamācintyaṃ triṣu lokeṣu viśrutam
yathā somasya śakrasya sūryasya ca yathā vapuḥ', null, 3067001),
('ramayana-3-67-2', 2, 'Aranya Kanda, Sarga 67, Verse 2', 'सोऽहं रूपमिदं कृत्वा लोकवित्रासनं महत्।
ऋषीन्वनगतान्राम त्रासयामि ततस्ततः॥', 'so ''haṃ rūpam idaṃ kṛtvā lokavitrāsanaṃ mahat
ṛṣīn vanagatān rāma trāsayāmi tatas tataḥ', null, 3067002),
('ramayana-3-67-3', 3, 'Aranya Kanda, Sarga 67, Verse 3', 'ततः स्थूलशिरा नाम महर्षिः कोपितो मया।
संचिन्वन्विविधं वन्यं रूपेणानेन धर्षितः॥', 'tataḥ sthūlaśirā nāma maharṣiḥ kopito mayā
saṃcinvan vividhaṃ vanyaṃ rūpeṇānena dharṣitaḥ', null, 3067003),
('ramayana-3-67-4', 4, 'Aranya Kanda, Sarga 67, Verse 4', 'तेनाहमुक्तः प्रेक्ष्यैवं घोरशापाभिधायिना।
एतदेव नृशंसं ते रूपमस्तु विगर्हितम्॥', 'tenāham uktaḥ prekṣyaivaṃ ghoraśāpābhidhāyinā
etad eva nṛśaṃsaṃ te rūpam astu vigarhitam', null, 3067004),
('ramayana-3-67-5', 5, 'Aranya Kanda, Sarga 67, Verse 5', 'स मया याचितः क्रुद्धः शापस्यान्तो भवेदिति।
अभिशापकृतस्येति तेनेदं भाषितं वचः॥', 'sa mayā yācitaḥ kruddhaḥ śāpasyānto bhaved iti
abhiśāpakṛtasyeti tenedaṃ bhāṣitaṃ vacaḥ', null, 3067005),
('ramayana-3-67-6', 6, 'Aranya Kanda, Sarga 67, Verse 6', 'यदा छित्त्वा भुजौ रामस्त्वां दहेद्विजने वने।
तदा त्वं प्राप्स्यसे रूपं स्वमेव विपुलं शुभम्॥', 'yadā chittvā bhujau rāmas tvāṃ dahed vijane vane
tadā tvaṃ prāpsyase rūpaṃ svam eva vipulaṃ śubham', null, 3067006),
('ramayana-3-67-7', 7, 'Aranya Kanda, Sarga 67, Verse 7', 'श्रिया विराजितं पुत्रं दनोस्त्वं विद्धि लक्ष्मण।
इन्द्रकोपादिदं रूपं प्राप्तमेवं रणाजिरे॥', 'śriyā virājitaṃ putraṃ danos tvaṃ viddhi lakṣmaṇa
indrakopād idaṃ rūpaṃ prāptam evaṃ raṇājire', null, 3067007),
('ramayana-3-67-8', 8, 'Aranya Kanda, Sarga 67, Verse 8', 'अहं हि तपसोग्रेण पितामहमतोषयम्।
दीर्घमायुः स मे प्रादात्ततो मां विभ्रमोऽस्पृशत्॥', 'ahaṃ hi tapasogreṇa pitāmaham atoṣayam
dīrgham āyuḥ sa me prādāt tato māṃ vibhramo ''spṛśat', null, 3067008),
('ramayana-3-67-9', 9, 'Aranya Kanda, Sarga 67, Verse 9', 'दीर्घमायुर्मया प्राप्तं किं मे शक्रः करिष्यति।
इत्येवं बुद्धिमास्थाय रणे शक्रमधर्षयम्॥', 'dīrgham āyur mayā prāptaṃ kiṃ me śakraḥ kariṣyati
ity evaṃ buddhim āsthāya raṇe śakram adharṣayam', null, 3067009),
('ramayana-3-67-10', 10, 'Aranya Kanda, Sarga 67, Verse 10', 'तस्य बाहुप्रमुक्तेन वज्रेण शतपर्वणा।
सक्थिनी च शिरश्चैव शरीरे संप्रवेशितम्॥', 'tasya bāhupramuktena vajreṇa śataparvaṇā
sakthinī ca śiraś caiva śarīre saṃpraveśitam', null, 3067010),
('ramayana-3-67-11', 11, 'Aranya Kanda, Sarga 67, Verse 11', 'स मया याच्यमानः सन्नानयद्यमसादनम्।
पितामहवचः सत्यं तदस्त्विति ममाब्रवीत्॥', 'sa mayā yācyamānaḥ sann ānayad yamasādanam
pitāmahavacaḥ satyaṃ tad astv iti mamābravīt', null, 3067011),
('ramayana-3-67-12', 12, 'Aranya Kanda, Sarga 67, Verse 12', 'अनाहारः कथं शक्तो भग्नसक्थिशिरोमुखः।
वज्रेणाभिहतः कालं सुदीर्घमपि जीवितुम्॥', 'anāhāraḥ kathaṃ śakto bhagnasakthiśiromukhaḥ
vajreṇābhihataḥ kālaṃ sudīrgham api jīvitum', null, 3067012),
('ramayana-3-67-13', 13, 'Aranya Kanda, Sarga 67, Verse 13', 'एवमुक्तस्तु मे शक्रो बाहू योजनमायतौ।
प्रादादास्यं च मे कुक्षौ तीक्ष्णदंष्ट्रमकल्पयत्॥', 'evam uktas tu me śakro bāhū yojanam āyatau
prādād āsyaṃ ca me kukṣau tīkṣṇadaṃṣṭram akalpayat', null, 3067013),
('ramayana-3-67-14', 14, 'Aranya Kanda, Sarga 67, Verse 14', 'सोऽहं भुजाभ्यां दीर्घाभ्यां समाकृष्य वनेचरान्।
सिंहद्विपमृगव्याघ्रान्भक्षयामि समन्ततः॥', 'so ''haṃ bhujābhyāṃ dīrghābhyāṃ samākṛṣya vanecarān
siṃhadvipamṛgavyāghrān bhakṣayāmi samantataḥ', null, 3067014),
('ramayana-3-67-15', 15, 'Aranya Kanda, Sarga 67, Verse 15', 'स तु मामब्रवीदिन्द्रो यदा रामः सलक्ष्मणः।
छेत्स्यते समरे बाहू तदा स्वर्गं गमिष्यसि॥', 'sa tu mām abravīd indro yadā rāmaḥ salakṣmaṇaḥ
chetsyate samare bāhū tadā svargaṃ gamiṣyasi', null, 3067015),
('ramayana-3-67-16', 16, 'Aranya Kanda, Sarga 67, Verse 16', 'स त्वं रामोऽसि भद्रं ते नाहमन्येन राघव।
शक्यो हन्तुं यथातत्त्वमेवमुक्तं महर्षिणा॥', 'sa tvaṃ rāmo ''si bhadraṃ te nāham anyena rāghava
śakyo hantuṃ yathātattvam evam uktaṃ maharṣiṇā', null, 3067016),
('ramayana-3-67-17', 17, 'Aranya Kanda, Sarga 67, Verse 17', 'अहं हि मतिसाचिव्यं करिष्यामि नरर्षभ।
मित्रं चैवोपदेक्ष्यामि युवाभ्यां संस्कृतोऽग्निना॥', 'ahaṃ hi matisācivyaṃ kariṣyāmi nararṣabha
mitraṃ caivopadekṣyāmi yuvābhyāṃ saṃskṛto ''gninā', null, 3067017),
('ramayana-3-67-18', 18, 'Aranya Kanda, Sarga 67, Verse 18', 'एवमुक्तस्तु धर्मात्मा दनुना तेन राघवः।
इदं जगाद वचनं लक्ष्मणस्योपशृण्वतः॥', 'evam uktas tu dharmātmā danunā tena rāghavaḥ
idaṃ jagāda vacanaṃ lakṣmaṇasyopaśṛṇvataḥ', null, 3067018),
('ramayana-3-67-19', 19, 'Aranya Kanda, Sarga 67, Verse 19', 'रावणेन हृता सीता मम भार्या यशस्विनी।
निष्क्रान्तस्य जनस्थानात्सह भ्रात्रा यथासुखम्॥', 'rāvaṇena hṛtā sītā mama bhāryā yaśasvinī
niṣkrāntasya janasthānāt saha bhrātrā yathāsukham', null, 3067019),
('ramayana-3-67-20', 20, 'Aranya Kanda, Sarga 67, Verse 20', 'नाममात्रं तु जानामि न रूपं तस्य रक्षसः।
निवासं वा प्रभावं वा वयं तस्य न विद्महे॥', 'nāmamātraṃ tu jānāmi na rūpaṃ tasya rakṣasaḥ
nivāsaṃ vā prabhāvaṃ vā vayaṃ tasya na vidmahe', null, 3067020),
('ramayana-3-67-21', 21, 'Aranya Kanda, Sarga 67, Verse 21', 'शोकार्तानामनाथानामेवं विपरिधावताम्।
कारुण्यं सदृशं कर्तुमुपकारे च वर्तताम्॥', 'śokārtānām anāthānām evaṃ viparidhāvatām
kāruṇyaṃ sadṛśaṃ kartum upakāre ca vartatām', null, 3067021),
('ramayana-3-67-22', 22, 'Aranya Kanda, Sarga 67, Verse 22', 'काष्ठान्यानीय शुष्काणि काले भग्नानि कुञ्जरैः।
भक्ष्यामस्त्वां वयं वीर श्वभ्रे महति कल्पिते॥', 'kāṣṭhāny ānīya śuṣkāṇi kāle bhagnāni kuñjaraiḥ
bhakṣyāmas tvāṃ vayaṃ vīra śvabhre mahati kalpite', null, 3067022),
('ramayana-3-67-23', 23, 'Aranya Kanda, Sarga 67, Verse 23', 'स त्वं सीतां समाचक्ष्व येन वा यत्र वा हृता।
कुरु कल्याणमत्यर्थं यदि जानासि तत्त्वतः॥', 'sa tvaṃ sītāṃ samācakṣva yena vā yatra vā hṛtā
kuru kalyāṇam atyarthaṃ yadi jānāsi tattvataḥ', null, 3067023),
('ramayana-3-67-24', 24, 'Aranya Kanda, Sarga 67, Verse 24', 'एवमुक्तस्तु रामेण वाक्यं दनुरनुत्तमम्।
प्रोवाच कुशलो वक्तुं वक्तारमपि राघवम्॥', 'evam uktas tu rāmeṇa vākyaṃ danur anuttamam
provāca kuśalo vaktuṃ vaktāram api rāghavam', null, 3067024),
('ramayana-3-67-25', 25, 'Aranya Kanda, Sarga 67, Verse 25', 'दिव्यमस्ति न मे ज्ञानं नाभिजानामि मैथिलीम्।
यस्तां ज्ञास्यति तं वक्ष्ये दग्धः स्वं रूपमास्थितः॥', 'divyam asti na me jñānaṃ nābhijānāmi maithilīm
yas tāṃ jñāsyati taṃ vakṣye dagdhaḥ svaṃ rūpam āsthitaḥ', null, 3067025),
('ramayana-3-67-26', 26, 'Aranya Kanda, Sarga 67, Verse 26', 'अदग्धस्य हि विज्ञातुं शक्तिरस्ति न मे प्रभो।
राक्षसं तं महावीर्यं सीता येन हृता तव॥', 'adagdhasya hi vijñātuṃ śaktir asti na me prabho
rākṣasaṃ taṃ mahāvīryaṃ sītā yena hṛtā tava', null, 3067026),
('ramayana-3-67-27', 27, 'Aranya Kanda, Sarga 67, Verse 27', 'विज्ञानं हि महद्भ्रष्टं शापदोषेण राघव।
स्वकृतेन मया प्राप्तं रूपं लोकविगर्हितम्॥', 'vijñānaṃ hi mahad bhraṣṭaṃ śāpadoṣeṇa rāghava
svakṛtena mayā prāptaṃ rūpaṃ lokavigarhitam', null, 3067027),
('ramayana-3-67-28', 28, 'Aranya Kanda, Sarga 67, Verse 28', 'किं तु यावन्न यात्यस्तं सविता श्रान्तवाहनः।
तावन्मामवटे क्षिप्त्वा दह राम यथाविधि॥', 'kiṃ tu yāvan na yāty astaṃ savitā śrāntavāhanaḥ
tāvan mām avaṭe kṣiptvā daha rāma yathāvidhi', null, 3067028),
('ramayana-3-67-29', 29, 'Aranya Kanda, Sarga 67, Verse 29', 'दग्धस्त्वयाहमवटे न्यायेन रघुनन्दन।
वक्ष्यामि तमहं वीर यस्तं ज्ञास्यति राक्षसं॥', 'dagdhas tvayāham avaṭe nyāyena raghunandana
vakṣyāmi tam ahaṃ vīra yas taṃ jñāsyati rākṣasaṃ', null, 3067029),
('ramayana-3-67-30', 30, 'Aranya Kanda, Sarga 67, Verse 30', 'तेन सख्यं च कर्तव्यं न्याय्यवृत्तेन राघव।
कल्पयिष्यति ते प्रीतः साहाय्यं लघुविक्रमः॥', 'tena sakhyaṃ ca kartavyaṃ nyāyyavṛttena rāghava
kalpayiṣyati te prītaḥ sāhāyyaṃ laghuvikramaḥ', null, 3067030),
('ramayana-3-67-31', 31, 'Aranya Kanda, Sarga 67, Verse 31', 'न हि तस्यास्त्यविज्ञातं त्रिषु लोकेषु राघव।
सर्वान्परिसृतो लोकान्पुरा वै कारणान्तरे॥', 'na hi tasyāsty avijñātaṃ triṣu lokeṣu rāghava
sarvān parisṛto lokān purā vai kāraṇāntare', null, 3067031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 68 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-68-1', 1, 'Aranya Kanda, Sarga 68, Verse 1', 'एवमुक्तौ तु तौ वीरौ कबन्धेन नरेश्वरौ।
गिरिप्रदरमासाद्य पावकं विससर्जतुः॥', 'evam uktau tu tau vīrau kabandhena nareśvarau
giripradaram āsādya pāvakaṃ visasarjatuḥ', null, 3068001),
('ramayana-3-68-2', 2, 'Aranya Kanda, Sarga 68, Verse 2', 'लक्ष्मणस्तु महोल्काभिर्ज्वलिताभिः समन्ततः।
चितामादीपयामास सा प्रजज्वाल सर्वतः॥', 'lakṣmaṇas tu maholkābhir jvalitābhiḥ samantataḥ
citām ādīpayām āsa sā prajajvāla sarvataḥ', null, 3068002),
('ramayana-3-68-3', 3, 'Aranya Kanda, Sarga 68, Verse 3', 'तच्छरीरं कबन्धस्य घृतपिण्डोपमं महत्।
मेदसा पच्यमानस्य मन्दं दहति पावक॥', 'tac charīraṃ kabandhasya ghṛtapiṇḍopamaṃ mahat
medasā pacyamānasya mandaṃ dahati pāvaka', null, 3068003),
('ramayana-3-68-4', 4, 'Aranya Kanda, Sarga 68, Verse 4', 'स विधूय चितामाशु विधूमोऽग्निरिवोत्थितः।
अरजे वाससी विभ्रन्मालां दिव्यां महाबलः॥', 'sa vidhūya citām āśu vidhūmo ''gnir ivotthitaḥ
araje vāsasī vibhran mālāṃ divyāṃ mahābalaḥ', null, 3068004),
('ramayana-3-68-5', 5, 'Aranya Kanda, Sarga 68, Verse 5', 'ततश्चिताया वेगेन भास्वरो विरजाम्बरः।
उत्पपाताशु संहृष्टः सर्वप्रत्यङ्गभूषणः॥', 'tataś citāyā vegena bhāsvaro virajāmbaraḥ
utpapātāśu saṃhṛṣṭaḥ sarvapratyaṅgabhūṣaṇaḥ', null, 3068005),
('ramayana-3-68-6', 6, 'Aranya Kanda, Sarga 68, Verse 6', 'विमाने भास्वरे तिष्ठन्हंसयुक्ते यशस्करे।
प्रभया च महातेजा दिशो दश विराजयन्॥', 'vimāne bhāsvare tiṣṭhan haṃsayukte yaśaskare
prabhayā ca mahātejā diśo daśa virājayan', null, 3068006),
('ramayana-3-68-7', 7, 'Aranya Kanda, Sarga 68, Verse 7', 'सोऽन्तरिक्षगतो रामं कबन्धो वाक्यमब्रवीत्।
शृणु राघव तत्त्वेन यथा सीमामवाप्स्यसि॥', 'so ''ntarikṣagato rāmaṃ kabandho vākyam abravīt
śṛṇu rāghava tattvena yathā sīmām avāpsyasi', null, 3068007),
('ramayana-3-68-8', 8, 'Aranya Kanda, Sarga 68, Verse 8', 'राम षड्युक्तयो लोके याभिः सर्वं विमृश्यते।
परिमृष्टो दशान्तेन दशाभागेन सेव्यते॥', 'rāma ṣaḍ yuktayo loke yābhiḥ sarvaṃ vimṛśyate
parimṛṣṭo daśāntena daśābhāgena sevyate', null, 3068008),
('ramayana-3-68-9', 9, 'Aranya Kanda, Sarga 68, Verse 9', 'दशाभागगतो हीनस्त्वं राम सहलक्ष्मणः।
यत्कृते व्यसनं प्राप्तं त्वया दारप्रधर्षणम्॥', 'daśābhāgagato hīnas tvaṃ rāma sahalakṣmaṇaḥ
yat kṛte vyasanaṃ prāptaṃ tvayā dārapradharṣaṇam', null, 3068009),
('ramayana-3-68-10', 10, 'Aranya Kanda, Sarga 68, Verse 10', 'तदवश्यं त्वया कार्यः स सुहृत्सुहृदां वर।
अकृत्वा न हि ते सिद्धिमहं पश्यामि चिन्तयन्॥', 'tad avaśyaṃ tvayā kāryaḥ sa suhṛt suhṛdāṃ vara
akṛtvā na hi te siddhim ahaṃ paśyāmi cintayan', null, 3068010),
('ramayana-3-68-11', 11, 'Aranya Kanda, Sarga 68, Verse 11', 'श्रूयतां राम वक्ष्यामि सुग्रीवो नाम वानरः।
भ्रात्रा निरस्तः क्रुद्धेन वालिना शक्रसूनुना॥', 'śrūyatāṃ rāma vakṣyāmi sugrīvo nāma vānaraḥ
bhrātrā nirastaḥ kruddhena vālinā śakrasūnunā', null, 3068011),
('ramayana-3-68-12', 12, 'Aranya Kanda, Sarga 68, Verse 12', 'ऋष्यमूके गिरिवरे पम्पापर्यन्तशोभिते।
निवसत्यात्मवान्वीरश्चतुर्भिः सह वानरैः॥', 'ṛṣyamūke girivare pampāparyantaśobhite
nivasaty ātmavān vīraś caturbhiḥ saha vānaraiḥ', null, 3068012),
('ramayana-3-68-13', 13, 'Aranya Kanda, Sarga 68, Verse 13', 'वयस्यं तं कुरु क्षिप्रमितो गत्वाद्य राघव।
अद्रोहाय समागम्य दीप्यमाने विभावसौ॥', 'vayasyaṃ taṃ kuru kṣipram ito gatvādya rāghava
adrohāya samāgamya dīpyamāne vibhāvasau', null, 3068013),
('ramayana-3-68-14', 14, 'Aranya Kanda, Sarga 68, Verse 14', 'न च ते सोऽवमन्तव्यः सुग्रीवो वानराधिपः।
कृतज्ञः कामरूपी च सहायार्थी च वीर्यवान्॥', 'na ca te so ''vamantavyaḥ sugrīvo vānarādhipaḥ
kṛtajñaḥ kāmarūpī ca sahāyārthī ca vīryavān', null, 3068014),
('ramayana-3-68-15', 15, 'Aranya Kanda, Sarga 68, Verse 15', 'शक्तौ ह्यद्य युवां कर्तुं कार्यं तस्य चिकीर्षितम्।
कृतार्थो वाकृतार्थो वा कृत्यं तव करिष्यति॥', 'śaktau hy adya yuvāṃ kartuṃ kāryaṃ tasya cikīrṣitam
kṛtārtho vākṛtārtho vā kṛtyaṃ tava kariṣyati', null, 3068015),
('ramayana-3-68-16', 16, 'Aranya Kanda, Sarga 68, Verse 16', 'स ऋक्षरजसः पुत्रः पम्पामटति शङ्कितः।
भास्करस्यौरसः पुत्रो वालिना कृतकिल्बिषः॥', 'sa ṛkṣarajasaḥ putraḥ pampām aṭati śaṅkitaḥ
bhāskarasyaurasaḥ putro vālinā kṛtakilbiṣaḥ', null, 3068016),
('ramayana-3-68-17', 17, 'Aranya Kanda, Sarga 68, Verse 17', 'संनिधायायुधं क्षिप्रमृष्यमूकालयं कपिम्।
कुरु राघव सत्येन वयस्यं वनचारिणम्॥', 'saṃnidhāyāyudhaṃ kṣipram ṛṣyamūkālayaṃ kapim
kuru rāghava satyena vayasyaṃ vanacāriṇam', null, 3068017),
('ramayana-3-68-18', 18, 'Aranya Kanda, Sarga 68, Verse 18', 'स हि स्थानानि सर्वाणि कार्त्स्न्येन कपिकुञ्जरः।
नरमांसाशिनां लोके नैपुण्यादधिगच्छति॥', 'sa hi sthānāni sarvāṇi kārtsnyena kapikuñjaraḥ
naramāṃsāśināṃ loke naipuṇyād adhigacchati', null, 3068018),
('ramayana-3-68-19', 19, 'Aranya Kanda, Sarga 68, Verse 19', 'न तस्याविदितं लोके किं चिदस्ति हि राघव।
यावत्सूर्यः प्रतपति सहस्रांशुररिंदम॥', 'na tasyāviditaṃ loke kiṃ cid asti hi rāghava
yāvat sūryaḥ pratapati sahasrāṃśur ariṃdama', null, 3068019),
('ramayana-3-68-20', 20, 'Aranya Kanda, Sarga 68, Verse 20', 'स नदीर्विपुलाञ्शैलान्गिरिदुर्गाणि कन्दरान्।
अन्विष्य वानरैः सार्धं पत्नीं तेऽधिगमिष्यति॥', 'sa nadīr vipulāñ śailān giridurgāṇi kandarān
anviṣya vānaraiḥ sārdhaṃ patnīṃ te ''dhigamiṣyati', null, 3068020),
('ramayana-3-68-21', 21, 'Aranya Kanda, Sarga 68, Verse 21', 'वानरांश्च महाकायान्प्रेषयिष्यति राघव।
दिशो विचेतुं तां सीतां त्वद्वियोगेन शोचतीम्॥', 'vānarāṃś ca mahākāyān preṣayiṣyati rāghava
diśo vicetuṃ tāṃ sītāṃ tvadviyogena śocatīm', null, 3068021),
('ramayana-3-68-22', 22, 'Aranya Kanda, Sarga 68, Verse 22', 'स मेरुशृङ्गाग्रगतामनिन्दितां प्रविश्य पातालतलेऽपि वाश्रिताम्।
प्लवंगमानां प्रवरस्तव प्रियां निहत्य रक्षांसि पुनः प्रदास्यति॥', 'sa meruśṛṅgāgragatām aninditāṃ praviśya pātālatale ''pi vāśritām
plavaṃgamānāṃ pravaras tava priyāṃ nihatya rakṣāṃsi punaḥ pradāsyati', null, 3068022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 69 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-69-1', 1, 'Aranya Kanda, Sarga 69, Verse 1', 'निदर्शयित्वा रामाय सीतायाः प्रतिपादने।
वाक्यमन्वर्थमर्थज्ञः कबन्धः पुनरब्रवीत्॥', 'nidarśayitvā rāmāya sītāyāḥ pratipādane
vākyam anvartham arthajñaḥ kabandhaḥ punar abravīt', null, 3069001),
('ramayana-3-69-2', 2, 'Aranya Kanda, Sarga 69, Verse 2', 'एष राम शिवः पन्था यत्रैते पुष्पिता द्रुमाः।
प्रतीचीं दिशमाश्रित्य प्रकाशन्ते मनोरमाः॥', 'eṣa rāma śivaḥ panthā yatraite puṣpitā drumāḥ
pratīcīṃ diśam āśritya prakāśante manoramāḥ', null, 3069002),
('ramayana-3-69-3', 3, 'Aranya Kanda, Sarga 69, Verse 3', 'जम्बूप्रियालपनसाः प्लक्षन्यग्रोधतिन्दुकाः।
अश्वत्थाः कर्णिकाराश्च चूताश्चान्ये च पादपाः॥', 'jambūpriyālapanasāḥ plakṣanyagrodhatindukāḥ
aśvatthāḥ karṇikārāś ca cūtāś cānye ca pādapāḥ', null, 3069003),
('ramayana-3-69-4', 4, 'Aranya Kanda, Sarga 69, Verse 4', 'तानारुह्याथ वा भूमौ पातयित्वा च तान्बलात्।
फलान्यमृतकल्पानि भक्षयन्तौ गमिष्यथः॥', 'tān āruhyātha vā bhūmau pātayitvā ca tān balāt
phalāny amṛtakalpāni bhakṣayantau gamiṣyathaḥ', null, 3069004),
('ramayana-3-69-5', 5, 'Aranya Kanda, Sarga 69, Verse 5', 'चङ्क्रमन्तौ वरान्देशाञ्शैलाच्छैलं वनाद्वनम्।
ततः पुष्करिणीं वीरौ पम्पां नाम गमिष्यथः॥', 'caṅkramantau varān deśāñ śailāc chailaṃ vanād vanam
tataḥ puṣkariṇīṃ vīrau pampāṃ nāma gamiṣyathaḥ', null, 3069005),
('ramayana-3-69-6', 6, 'Aranya Kanda, Sarga 69, Verse 6', 'अशर्करामविभ्रंशां समतीर्थमशैवलाम्।
राम संजातवालूकां कमलोत्पलशोभिताम्॥', 'aśarkarām avibhraṃśāṃ samatīrtham aśaivalām
rāma saṃjātavālūkāṃ kamalotpalaśobhitām', null, 3069006),
('ramayana-3-69-7', 7, 'Aranya Kanda, Sarga 69, Verse 7', 'तत्र हंसाः प्लवाः क्रौञ्चाः कुरराश्चैव राघव।
वल्गुस्वरा निकूजन्ति पम्पासलिलगोचराः॥', 'tatra haṃsāḥ plavāḥ krauñcāḥ kurarāś caiva rāghava
valgusvarā nikūjanti pampāsalilagocarāḥ', null, 3069007),
('ramayana-3-69-8', 8, 'Aranya Kanda, Sarga 69, Verse 8', 'नोद्विजन्ते नरान्दृष्ट्वा वधस्याकोविदाः शुभाः।
घृतपिण्डोपमान्स्थूलांस्तान्द्विजान्भक्षयिष्यथः॥', 'nodvijante narān dṛṣṭvā vadhasyākovidāḥ śubhāḥ
ghṛtapiṇḍopamān sthūlāṃs tān dvijān bhakṣayiṣyathaḥ', null, 3069008),
('ramayana-3-69-9', 9, 'Aranya Kanda, Sarga 69, Verse 9', 'रोहितान्वक्रतुण्डांश्च नलमीनांश्च राघव।
पम्पायामिषुभिर्मत्स्यांस्तत्र राम वरान्हतान्॥', 'rohitān vakratuṇḍāṃś ca nalamīnāṃś ca rāghava
pampāyām iṣubhir matsyāṃs tatra rāma varān hatān', null, 3069009),
('ramayana-3-69-10', 10, 'Aranya Kanda, Sarga 69, Verse 10', 'निस्त्वक्पक्षानयस्तप्तानकृशानेककण्टकान्।
तव भक्त्या समायुक्तो लक्ष्मणः संप्रदास्यति॥', 'nistvakpakṣān ayastaptān akṛśān ekakaṇṭakān
tava bhaktyā samāyukto lakṣmaṇaḥ saṃpradāsyati', null, 3069010),
('ramayana-3-69-11', 11, 'Aranya Kanda, Sarga 69, Verse 11', 'भृशं ते खादतो मत्स्यान्पम्पायाः पुष्पसंचये।
पद्मगन्धि शिवं वारि सुखशीतमनामयम्॥', 'bhṛśaṃ te khādato matsyān pampāyāḥ puṣpasaṃcaye
padmagandhi śivaṃ vāri sukhaśītam anāmayam', null, 3069011),
('ramayana-3-69-12', 12, 'Aranya Kanda, Sarga 69, Verse 12', 'उद्धृत्य स तदाक्लिष्टं रूप्यस्फटिकसंनिभम्।
अथ पुष्करपर्णेन लक्ष्मणः पाययिष्यति॥', 'uddhṛtya sa tadākliṣṭaṃ rūpyasphaṭikasaṃnibham
atha puṣkaraparṇena lakṣmaṇaḥ pāyayiṣyati', null, 3069012),
('ramayana-3-69-13', 13, 'Aranya Kanda, Sarga 69, Verse 13', 'स्थूलान्गिरिगुहाशय्यान्वराहान्वनचारिणः।
अपां लोभादुपावृत्तान्वृषभानिव नर्दतः।
रूपान्वितांश्च पम्पायां द्रक्ष्यसि त्वं नरोत्तम॥', 'sthūlān giriguhāśayyān varāhān vanacāriṇaḥ
apāṃ lobhād upāvṛttān vṛṣabhān iva nardataḥ
rūpānvitāṃś ca pampāyāṃ drakṣyasi tvaṃ narottama', null, 3069013),
('ramayana-3-69-14', 14, 'Aranya Kanda, Sarga 69, Verse 14', 'सायाह्ने विचरन्राम विटपी माल्यधारिणः।
शीतोदकं च पम्पायां दृष्ट्वा शोकं विहास्यसि॥', 'sāyāhne vicaran rāma viṭapī mālyadhāriṇaḥ
śītodakaṃ ca pampāyāṃ dṛṣṭvā śokaṃ vihāsyasi', null, 3069014),
('ramayana-3-69-15', 15, 'Aranya Kanda, Sarga 69, Verse 15', 'सुमनोभिश्चितांस्तत्र तिलकान्नक्तमालकान्।
उत्पलानि च फुल्लानि पङ्कजानि च राघव॥', 'sumanobhiś citāṃs tatra tilakān naktamālakān
utpalāni ca phullāni paṅkajāni ca rāghava', null, 3069015),
('ramayana-3-69-16', 16, 'Aranya Kanda, Sarga 69, Verse 16', 'न तानि कश्चिन्माल्यानि तत्रारोपयिता नरः।
मतङ्गशिष्यास्तत्रासन्नृषयः सुसमाहितः॥', 'na tāni kaś cin mālyāni tatrāropayitā naraḥ
mataṅgaśiṣyās tatrāsann ṛṣayaḥ susamāhitaḥ', null, 3069016),
('ramayana-3-69-17', 17, 'Aranya Kanda, Sarga 69, Verse 17', 'तेषां भाराभितप्तानां वन्यमाहरतां गुरोः।
ये प्रपेतुर्महीं तूर्णं शरीरात्स्वेदबिन्दवः॥', 'teṣāṃ bhārābhitaptānāṃ vanyam āharatāṃ guroḥ
ye prapetur mahīṃ tūrṇaṃ śarīrāt svedabindavaḥ', null, 3069017),
('ramayana-3-69-18', 18, 'Aranya Kanda, Sarga 69, Verse 18', 'तानि माल्यानि जातानि मुनीनां तपसा तदा।
स्वेदबिन्दुसमुत्थानि न विनश्यन्ति राघव॥', 'tāni mālyāni jātāni munīnāṃ tapasā tadā
svedabindusamutthāni na vinaśyanti rāghava', null, 3069018),
('ramayana-3-69-19', 19, 'Aranya Kanda, Sarga 69, Verse 19', 'तेषामद्यापि तत्रैव दृश्यते परिचारिणी।
श्रमणी शबरी नाम काकुत्स्थ चिरजीविनी॥', 'teṣām adyāpi tatraiva dṛśyate paricāriṇī
śramaṇī śabarī nāma kākutstha cirajīvinī', null, 3069019),
('ramayana-3-69-20', 20, 'Aranya Kanda, Sarga 69, Verse 20', 'त्वां तु धर्मे स्थिता नित्यं सर्वभूतनमस्कृतम्।
दृष्ट्वा देवोपमं राम स्वर्गलोकं गमिष्यति॥', 'tvāṃ tu dharme sthitā nityaṃ sarvabhūtanamaskṛtam
dṛṣṭvā devopamaṃ rāma svargalokaṃ gamiṣyati', null, 3069020),
('ramayana-3-69-21', 21, 'Aranya Kanda, Sarga 69, Verse 21', 'ततस्तद्राम पम्पायास्तीरमाश्रित्य पश्चिमम्।
आश्रमस्थानमतुलं गुह्यं काकुत्स्थ पश्यसि॥', 'tatas tad rāma pampāyās tīram āśritya paścimam
āśramasthānam atulaṃ guhyaṃ kākutstha paśyasi', null, 3069021),
('ramayana-3-69-22', 22, 'Aranya Kanda, Sarga 69, Verse 22', 'न तत्राक्रमितुं नागाः शक्नुवन्ति तमाश्रमम्।
ऋषेस्तस्य मतङ्गस्य विधानात्तच्च काननम्॥', 'na tatrākramituṃ nāgāḥ śaknuvanti tam āśramam
ṛṣes tasya mataṅgasya vidhānāt tac ca kānanam', null, 3069022),
('ramayana-3-69-23', 23, 'Aranya Kanda, Sarga 69, Verse 23', 'तस्मिन्नन्दनसंकाशे देवारण्योपमे वने।
नानाविहगसंकीर्णे रंस्यसे राम निर्वृतः॥', 'tasmin nandanasaṃkāśe devāraṇyopame vane
nānāvihagasaṃkīrṇe raṃsyase rāma nirvṛtaḥ', null, 3069023),
('ramayana-3-69-24', 24, 'Aranya Kanda, Sarga 69, Verse 24', 'ऋष्यमूकस्तु पम्पायाः पुरस्तात्पुष्पितद्रुमः।
सुदुःखारोहणो नाम शिशुनागाभिरक्षितः।
उदारो ब्रह्मणा चैव पूर्वकाले विनिर्मितः॥', 'ṛṣyamūkas tu pampāyāḥ purastāt puṣpitadrumaḥ
suduḥkhārohaṇo nāma śiśunāgābhirakṣitaḥ
udāro brahmaṇā caiva pūrvakāle vinirmitaḥ', null, 3069024),
('ramayana-3-69-25', 25, 'Aranya Kanda, Sarga 69, Verse 25', 'शयानः पुरुषो राम तस्य शैलस्य मूर्धनि।
यत्स्वप्ने लभते वित्तं तत्प्रबुद्धोऽधिगच्छति॥', 'śayānaḥ puruṣo rāma tasya śailasya mūrdhani
yat svapne labhate vittaṃ tat prabuddho ''dhigacchati', null, 3069025),
('ramayana-3-69-26', 26, 'Aranya Kanda, Sarga 69, Verse 26', 'न त्वेनं विषमाचारः पापकर्माधिरोहति।
तत्रैव प्रहरन्त्येनं सुप्तमादाय राक्षसाः॥', 'na tv enaṃ viṣamācāraḥ pāpakarmādhirohati
tatraiva praharanty enaṃ suptam ādāya rākṣasāḥ', null, 3069026),
('ramayana-3-69-27', 27, 'Aranya Kanda, Sarga 69, Verse 27', 'ततोऽपि शिशुनागानामाक्रन्दः श्रूयते महान्।
क्रीडतां राम पम्पायां मतङ्गारण्यवासिनाम्॥', 'tato ''pi śiśunāgānām ākrandaḥ śrūyate mahān
krīḍatāṃ rāma pampāyāṃ mataṅgāraṇyavāsinām', null, 3069027),
('ramayana-3-69-28', 28, 'Aranya Kanda, Sarga 69, Verse 28', 'सिक्ता रुधिरधाराभिः संहत्य परमद्विपाः।
प्रचरन्ति पृथक्कीर्णा मेघवर्णास्तरस्विनः॥', 'siktā rudhiradhārābhiḥ saṃhatya paramadvipāḥ
pracaranti pṛthak kīrṇā meghavarṇās tarasvinaḥ', null, 3069028),
('ramayana-3-69-29', 29, 'Aranya Kanda, Sarga 69, Verse 29', 'ते तत्र पीत्वा पानीयं विमलं शीतमव्ययम्।
निवृत्ताः संविगाहन्ते वनानि वनगोचराः॥', 'te tatra pītvā pānīyaṃ vimalaṃ śītam avyayam
nivṛttāḥ saṃvigāhante vanāni vanagocarāḥ', null, 3069029),
('ramayana-3-69-30', 30, 'Aranya Kanda, Sarga 69, Verse 30', 'राम तस्य तु शैलस्य महती शोभते गुहा।
शिलापिधाना काकुत्स्थ दुःखं चास्याः प्रवेशनम्॥', 'rāma tasya tu śailasya mahatī śobhate guhā
śilāpidhānā kākutstha duḥkhaṃ cāsyāḥ praveśanam', null, 3069030),
('ramayana-3-69-31', 31, 'Aranya Kanda, Sarga 69, Verse 31', 'तस्या गुहायाः प्राग्द्वारे महाञ्शीतोदको ह्रदः।
बहुमूलफलो रम्यो नानानगसमावृतः॥', 'tasyā guhāyāḥ prāgdvāre mahāñ śītodako hradaḥ
bahumūlaphalo ramyo nānānagasamāvṛtaḥ', null, 3069031),
('ramayana-3-69-32', 32, 'Aranya Kanda, Sarga 69, Verse 32', 'तस्यां वसति सुग्रीवश्चतुर्भिः सह वानरैः।
कदा चिच्छिखरे तस्य पर्वतस्यावतिष्ठते॥', 'tasyāṃ vasati sugrīvaś caturbhiḥ saha vānaraiḥ
kadā cic chikhare tasya parvatasyāvatiṣṭhate', null, 3069032),
('ramayana-3-69-33', 33, 'Aranya Kanda, Sarga 69, Verse 33', 'कबन्धस्त्वनुशास्यैवं तावुभौ रामलक्ष्मणौ।
स्रग्वी भास्करवर्णाभः खे व्यरोचत वीर्यवान्॥', 'kabandhas tv anuśāsyaivaṃ tāv ubhau rāmalakṣmaṇau
sragvī bhāskaravarṇābhaḥ khe vyarocata vīryavān', null, 3069033),
('ramayana-3-69-34', 34, 'Aranya Kanda, Sarga 69, Verse 34', 'तं तु खस्थं महाभागं कबन्धं रामलक्ष्मणौ।
प्रस्थितौ त्वं व्रजस्वेति वाक्यमूचतुरन्तिकात्॥', 'taṃ tu khasthaṃ mahābhāgaṃ kabandhaṃ rāmalakṣmaṇau
prasthitau tvaṃ vrajasveti vākyam ūcatur antikāt', null, 3069034),
('ramayana-3-69-35', 35, 'Aranya Kanda, Sarga 69, Verse 35', 'गम्यतां कार्यसिद्ध्यर्थमिति तावब्रवीच्च सः।
सुप्रीतौ तावनुज्ञाप्य कबन्धः प्रस्थितस्तदा॥', 'gamyatāṃ kāryasiddhyartham iti tāv abravīc ca saḥ
suprītau tāv anujñāpya kabandhaḥ prasthitas tadā', null, 3069035),
('ramayana-3-69-36', 36, 'Aranya Kanda, Sarga 69, Verse 36', 'स तत्कबन्धः प्रतिपद्य रूपं वृतः श्रिया भास्करतुल्यदेहः।
निदर्शयन्राममवेक्ष्य खस्थः सख्यं कुरुष्वेति तदाभ्युवाच॥', 'sa tat kabandhaḥ pratipadya rūpaṃ vṛtaḥ śriyā bhāskaratulyadehaḥ
nidarśayan rāmam avekṣya khasthaḥ sakhyaṃ kuruṣveti tadābhyuvāca', null, 3069036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 70 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-70-1', 1, 'Aranya Kanda, Sarga 70, Verse 1', 'तौ कबन्धेन तं मार्गं पम्पाया दर्शितं वने।
आतस्थतुर्दिशं गृह्य प्रतीचीं नृवरात्मजौ॥', 'tau kabandhena taṃ mārgaṃ pampāyā darśitaṃ vane
ātasthatur diśaṃ gṛhya pratīcīṃ nṛvarātmajau', null, 3070001),
('ramayana-3-70-2', 2, 'Aranya Kanda, Sarga 70, Verse 2', 'तौ शैलेष्वाचितानेकान्क्षौद्रकल्पफलद्रुमान्।
वीक्षन्तौ जग्मतुर्द्रष्टुं सुग्रीवं रामलक्ष्मणौ॥', 'tau śaileṣv ācitānekān kṣaudrakalpaphaladrumān
vīkṣantau jagmatur draṣṭuṃ sugrīvaṃ rāmalakṣmaṇau', null, 3070002),
('ramayana-3-70-3', 3, 'Aranya Kanda, Sarga 70, Verse 3', 'कृत्वा च शैलपृष्ठे तु तौ वासं रघुनन्दनौ।
पम्पायाः पश्चिमं तीरं राघवावुपतस्थतुः॥', 'kṛtvā ca śailapṛṣṭhe tu tau vāsaṃ raghunandanau
pampāyāḥ paścimaṃ tīraṃ rāghavāv upatasthatuḥ', null, 3070003),
('ramayana-3-70-4', 4, 'Aranya Kanda, Sarga 70, Verse 4', 'तौ पुष्करिण्याः पम्पायास्तीरमासाद्य पश्चिमम्।
अपश्यतां ततस्तत्र शबर्या रम्यमाश्रमम्॥', 'tau puṣkariṇyāḥ pampāyās tīram āsādya paścimam
apaśyatāṃ tatas tatra śabaryā ramyam āśramam', null, 3070004),
('ramayana-3-70-5', 5, 'Aranya Kanda, Sarga 70, Verse 5', 'तौ तमाश्रममासाद्य द्रुमैर्बहुभिरावृतम्।
सुरम्यमभिवीक्षन्तौ शबरीमभ्युपेयतुः॥', 'tau tam āśramam āsādya drumair bahubhir āvṛtam
suramyam abhivīkṣantau śabarīm abhyupeyatuḥ', null, 3070005),
('ramayana-3-70-6', 6, 'Aranya Kanda, Sarga 70, Verse 6', 'तौ तु दृष्ट्वा तदा सिद्धा समुत्थाय कृताञ्जलिः।
पादौ जग्राह रामस्य लक्ष्मणस्य च धीमतः॥', 'tau tu dṛṣṭvā tadā siddhā samutthāya kṛtāñjaliḥ
pādau jagrāha rāmasya lakṣmaṇasya ca dhīmataḥ', null, 3070006),
('ramayana-3-70-7', 7, 'Aranya Kanda, Sarga 70, Verse 7', 'तामुवाच ततो रामः श्रमणीं संशितव्रताम्।
कच्चित्ते निर्जिता विघ्नाः कच्चित्ते वर्धते तपः॥', 'tām uvāca tato rāmaḥ śramaṇīṃ saṃśitavratām
kaccit te nirjitā vighnāḥ kaccit te vardhate tapaḥ', null, 3070007),
('ramayana-3-70-8', 8, 'Aranya Kanda, Sarga 70, Verse 8', 'कच्चित्ते नियतः कोप आहारश्च तपोधने।
कच्चित्ते नियमाः प्राप्ताः कच्चित्ते मनसः सुखम्।
कच्चित्ते गुरुशुश्रूषा सफला चारुभाषिणि॥', 'kaccit te niyataḥ kopa āhāraś ca tapodhane
kaccit te niyamāḥ prāptāḥ kaccit te manasaḥ sukham
kaccit te guruśuśrūṣā saphalā cārubhāṣiṇi', null, 3070008),
('ramayana-3-70-9', 9, 'Aranya Kanda, Sarga 70, Verse 9', 'रामेण तापसी पृष्ठा सा सिद्धा सिद्धसंमता।
शशंस शबरी वृद्धा रामाय प्रत्युपस्थिता॥', 'rāmeṇa tāpasī pṛṣṭhā sā siddhā siddhasaṃmatā
śaśaṃsa śabarī vṛddhā rāmāya pratyupasthitā', null, 3070009),
('ramayana-3-70-10', 10, 'Aranya Kanda, Sarga 70, Verse 10', 'चित्रकूटं त्वयि प्राप्ते विमानैरतुलप्रभैः।
इतस्ते दिवमारूढा यानहं पर्यचारिषम्॥', 'citrakūṭaṃ tvayi prāpte vimānair atulaprabhaiḥ
itas te divam ārūḍhā yān ahaṃ paryacāriṣam', null, 3070010),
('ramayana-3-70-11', 11, 'Aranya Kanda, Sarga 70, Verse 11', 'तैश्चाहमुक्ता धर्मज्ञैर्महाभागैर्महर्षिभिः।
आगमिष्यति ते रामः सुपुण्यमिममाश्रमम्॥', 'taiś cāham uktā dharmajñair mahābhāgair maharṣibhiḥ
āgamiṣyati te rāmaḥ supuṇyam imam āśramam', null, 3070011),
('ramayana-3-70-12', 12, 'Aranya Kanda, Sarga 70, Verse 12', 'स ते प्रतिग्रहीतव्यः सौमित्रिसहितोऽतिथिः।
तं च दृष्ट्वा वरांल्लोकानक्षयांस्त्वं गमिष्यसि॥', 'sa te pratigrahītavyaḥ saumitrisahito ''tithiḥ
taṃ ca dṛṣṭvā varāṃl lokān akṣayāṃs tvaṃ gamiṣyasi', null, 3070012),
('ramayana-3-70-13', 13, 'Aranya Kanda, Sarga 70, Verse 13', 'मया तु विविधं वन्यं संचितं पुरुषर्षभ।
तवार्थे पुरुषव्याघ्र पम्पायास्तीरसंभवम्॥', 'mayā tu vividhaṃ vanyaṃ saṃcitaṃ puruṣarṣabha
tavārthe puruṣavyāghra pampāyās tīrasaṃbhavam', null, 3070013),
('ramayana-3-70-14', 14, 'Aranya Kanda, Sarga 70, Verse 14', 'एवमुक्तः स धर्मात्मा शबर्या शबरीमिदम्।
राघवः प्राह विज्ञाने तां नित्यमबहिष्कृताम्॥', 'evam uktaḥ sa dharmātmā śabaryā śabarīm idam
rāghavaḥ prāha vijñāne tāṃ nityam abahiṣkṛtām', null, 3070014),
('ramayana-3-70-15', 15, 'Aranya Kanda, Sarga 70, Verse 15', 'दनोः सकाशात्तत्त्वेन प्रभावं ते महात्मनः।
श्रुतं प्रत्यक्षमिच्छामि संद्रष्टुं यदि मन्यसे॥', 'danoḥ sakāśāt tattvena prabhāvaṃ te mahātmanaḥ
śrutaṃ pratyakṣam icchāmi saṃdraṣṭuṃ yadi manyase', null, 3070015),
('ramayana-3-70-16', 16, 'Aranya Kanda, Sarga 70, Verse 16', 'एतत्तु वचनं श्रुत्वा रामवक्त्राद्विनिःसृतम्।
शबरी दर्शयामास तावुभौ तद्वनं महत्॥', 'etat tu vacanaṃ śrutvā rāmavaktrād viniḥsṛtam
śabarī darśayām āsa tāv ubhau tad vanaṃ mahat', null, 3070016),
('ramayana-3-70-17', 17, 'Aranya Kanda, Sarga 70, Verse 17', 'पश्य मेघघनप्रख्यं मृगपक्षिसमाकुलम्।
मतङ्गवनमित्येव विश्रुतं रघुनन्दन॥', 'paśya meghaghanaprakhyaṃ mṛgapakṣisamākulam
mataṅgavanam ity eva viśrutaṃ raghunandana', null, 3070017),
('ramayana-3-70-18', 18, 'Aranya Kanda, Sarga 70, Verse 18', 'इह ते भावितात्मानो गुरवो मे महाद्युते।
जुहवांश्चक्रिरे तीर्थं मन्त्रवन्मन्त्रपूजितम्॥', 'iha te bhāvitātmāno guravo me mahādyute
juhavāṃś cakrire tīrthaṃ mantravan mantrapūjitam', null, 3070018),
('ramayana-3-70-19', 19, 'Aranya Kanda, Sarga 70, Verse 19', 'इयं प्रत्यक्स्थली वेदी यत्र ते मे सुसत्कृताः।
पुष्पोपहारं कुर्वन्ति श्रमादुद्वेपिभिः करैः॥', 'iyaṃ pratyak sthalī vedī yatra te me susatkṛtāḥ
puṣpopahāraṃ kurvanti śramād udvepibhiḥ karaiḥ', null, 3070019),
('ramayana-3-70-20', 20, 'Aranya Kanda, Sarga 70, Verse 20', 'तेषां तपः प्रभावेन पश्याद्यापि रघूत्तम।
द्योतयन्ति दिशः सर्वाः श्रिया वेद्योऽतुलप्रभाः॥', 'teṣāṃ tapaḥ prabhāvena paśyādyāpi raghūttama
dyotayanti diśaḥ sarvāḥ śriyā vedyo ''tulaprabhāḥ', null, 3070020),
('ramayana-3-70-21', 21, 'Aranya Kanda, Sarga 70, Verse 21', 'अशक्नुवद्भिस्तैर्गन्तुमुपवासश्रमालसैः।
चिन्तितेऽभ्यागतान्पश्य समेतान्सप्त सागरान्॥', 'aśaknuvadbhis tair gantum upavāsaśramālasaiḥ
cintite ''bhyāgatān paśya sametān sapta sāgarān', null, 3070021),
('ramayana-3-70-22', 22, 'Aranya Kanda, Sarga 70, Verse 22', 'कृताभिषेकैस्तैर्न्यस्ता वल्कलाः पादपेष्विह।
अद्यापि न विशुष्यन्ति प्रदेशे रघुनन्दन॥', 'kṛtābhiṣekais tair nyastā valkalāḥ pādapeṣv iha
adyāpi na viśuṣyanti pradeśe raghunandana', null, 3070022),
('ramayana-3-70-23', 23, 'Aranya Kanda, Sarga 70, Verse 23', 'कृत्स्नं वनमिदं दृष्टं श्रोतव्यं च श्रुतं त्वया।
तदिच्छाम्यभ्यनुज्ञाता त्यक्तुमेतत्कलेवरम्॥', 'kṛtsnaṃ vanam idaṃ dṛṣṭaṃ śrotavyaṃ ca śrutaṃ tvayā
tad icchāmy abhyanujñātā tyaktum etat kalevaram', null, 3070023),
('ramayana-3-70-24', 24, 'Aranya Kanda, Sarga 70, Verse 24', 'तेषामिच्छाम्यहं गन्तुं समीपं भावितात्मनाम्।
मुनीनामाश्रंमो येषामहं च परिचारिणी॥', 'teṣām icchāmy ahaṃ gantuṃ samīpaṃ bhāvitātmanām
munīnām āśraṃmo yeṣām ahaṃ ca paricāriṇī', null, 3070024),
('ramayana-3-70-25', 25, 'Aranya Kanda, Sarga 70, Verse 25', 'धर्मिष्ठं तु वचः श्रुत्वा राघवः सहलक्ष्मणः।
अनुजानामि गच्छेति प्रहृष्टवदनोऽब्रवीत्॥', 'dharmiṣṭhaṃ tu vacaḥ śrutvā rāghavaḥ sahalakṣmaṇaḥ
anujānāmi gaccheti prahṛṣṭavadano ''bravīt', null, 3070025),
('ramayana-3-70-26', 26, 'Aranya Kanda, Sarga 70, Verse 26', 'अनुज्ञाता तु रामेण हुत्वात्मानं हुताशने।
ज्वलत्पावकसंकाशा स्वर्गमेव जगाम सा॥', 'anujñātā tu rāmeṇa hutvātmānaṃ hutāśane
jvalatpāvakasaṃkāśā svargam eva jagāma sā', null, 3070026),
('ramayana-3-70-27', 27, 'Aranya Kanda, Sarga 70, Verse 27', 'यत्र ते सुकृतात्मानो विहरन्ति महर्षयः।
तत्पुण्यं शबरीस्थानं जगामात्मसमाधिना॥', 'yatra te sukṛtātmāno viharanti maharṣayaḥ
tat puṇyaṃ śabarīsthānaṃ jagāmātmasamādhinā', null, 3070027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 71 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 3 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-3-71-1', 1, 'Aranya Kanda, Sarga 71, Verse 1', 'दिवं तु तस्यां यातायां शबर्यां स्वेन कर्मणा।
लक्ष्मणेन सह भ्रात्रा चिन्तयामास राघवः॥', 'divaṃ tu tasyāṃ yātāyāṃ śabaryāṃ svena karmaṇā
lakṣmaṇena saha bhrātrā cintayām āsa rāghavaḥ', null, 3071001),
('ramayana-3-71-2', 2, 'Aranya Kanda, Sarga 71, Verse 2', 'चिन्तयित्वा तु धर्मात्मा प्रभावं तं महात्मनाम्।
हितकारिणमेकाग्रं लक्ष्मणं राघवोऽब्रवीत्॥', 'cintayitvā tu dharmātmā prabhāvaṃ taṃ mahātmanām
hitakāriṇam ekāgraṃ lakṣmaṇaṃ rāghavo ''bravīt', null, 3071002),
('ramayana-3-71-3', 3, 'Aranya Kanda, Sarga 71, Verse 3', 'दृष्टोऽयमाश्रमः सौम्य बह्वाश्चर्यः कृतात्मनाम्।
विश्वस्तमृगशार्दूलो नानाविहगसेवितः॥', 'dṛṣṭo ''yam āśramaḥ saumya bahvāścaryaḥ kṛtātmanām
viśvastamṛgaśārdūlo nānāvihagasevitaḥ', null, 3071003),
('ramayana-3-71-4', 4, 'Aranya Kanda, Sarga 71, Verse 4', 'सप्तानां च समुद्राणामेषु तीर्थेषु लक्ष्मण।
उपस्पृष्टं च विधिवत्पितरश्चापि तर्पिताः॥', 'saptānāṃ ca samudrāṇām eṣu tīrtheṣu lakṣmaṇa
upaspṛṣṭaṃ ca vidhivat pitaraś cāpi tarpitāḥ', null, 3071004),
('ramayana-3-71-5', 5, 'Aranya Kanda, Sarga 71, Verse 5', 'प्रनष्टमशुभं यत्तत्कल्याणं समुपस्थितम्।
तेन त्वेतत्प्रहृष्टं मे मनो लक्ष्मण संप्रति॥', 'pranaṣṭam aśubhaṃ yat tat kalyāṇaṃ samupasthitam
tena tv etat prahṛṣṭaṃ me mano lakṣmaṇa saṃprati', null, 3071005),
('ramayana-3-71-6', 6, 'Aranya Kanda, Sarga 71, Verse 6', 'हृदये हि नरव्याघ्र शुभमाविर्भविष्यति।
तदागच्छ गमिष्यावः पम्पां तां प्रियदर्शनाम्॥', 'hṛdaye hi naravyāghra śubham āvirbhaviṣyati
tad āgaccha gamiṣyāvaḥ pampāṃ tāṃ priyadarśanām', null, 3071006),
('ramayana-3-71-7', 7, 'Aranya Kanda, Sarga 71, Verse 7', 'ऋश्यमूको गिरिर्यत्र नातिदूरे प्रकाशते।
यस्मिन्वसति धर्मात्मा सुग्रीवोऽंशुमतः सुतः।
नित्यं वालिभयात्त्रस्तश्चतुर्भिः सह वानरैः॥', 'ṛśyamūko girir yatra nātidūre prakāśate
yasmin vasati dharmātmā sugrīvo ''ṃśumataḥ sutaḥ
nityaṃ vālibhayāt trastaś caturbhiḥ saha vānaraiḥ', null, 3071007),
('ramayana-3-71-8', 8, 'Aranya Kanda, Sarga 71, Verse 8', 'अभित्वरे च तं द्रष्टुं सुग्रीवं वानरर्षभम्।
तदधीनं हि मे सौम्य सीतायाः परिमार्गणम्॥', 'abhitvare ca taṃ draṣṭuṃ sugrīvaṃ vānararṣabham
tadadhīnaṃ hi me saumya sītāyāḥ parimārgaṇam', null, 3071008),
('ramayana-3-71-9', 9, 'Aranya Kanda, Sarga 71, Verse 9', 'इति ब्रुवाणं तं रामं सौमित्रिरिदमब्रवीत्।
गच्छावस्त्वरितं तत्र ममापि त्वरते मनः॥', 'iti bruvāṇaṃ taṃ rāmaṃ saumitrir idam abravīt
gacchāvas tvaritaṃ tatra mamāpi tvarate manaḥ', null, 3071009),
('ramayana-3-71-10', 10, 'Aranya Kanda, Sarga 71, Verse 10', 'आश्रमात्तु ततस्तस्मान्निष्क्रम्य स विशां पतिः।
आजगाम ततः पम्पां लक्ष्मणेन सहाभिभूः॥', 'āśramāt tu tatas tasmān niṣkramya sa viśāṃ patiḥ
ājagāma tataḥ pampāṃ lakṣmaṇena sahābhibhūḥ', null, 3071010),
('ramayana-3-71-11', 11, 'Aranya Kanda, Sarga 71, Verse 11', 'समीक्षमाणः पुष्पाढ्यं सर्वतो विपुलद्रुमम्।
कोयष्टिभिश्चार्जुनकैः शतपत्रैश्च कीचकैः।
एतैश्चान्यैश्च विविधैर्नादितं तद्वनं महत्॥', 'samīkṣamāṇaḥ puṣpāḍhyaṃ sarvato vipuladrumam
koyaṣṭibhiś cārjunakaiḥ śatapatraiś ca kīcakaiḥ
etaiś cānyaiś ca vividhair nāditaṃ tad vanaṃ mahat', null, 3071011),
('ramayana-3-71-12', 12, 'Aranya Kanda, Sarga 71, Verse 12', 'स रामो विधिवान्वृक्षान्सरांसि विविधानि च।
पश्यन्कामाभिसंतप्तो जगाम परमं ह्रदम्॥', 'sa rāmo vidhivān vṛkṣān sarāṃsi vividhāni ca
paśyan kāmābhisaṃtapto jagāma paramaṃ hradam', null, 3071012),
('ramayana-3-71-13', 13, 'Aranya Kanda, Sarga 71, Verse 13', 'स तामासाद्य वै रामो दूरादुदकवाहिनीम्।
मतङ्गसरसं नाम ह्रदं समवगाहत॥', 'sa tām āsādya vai rāmo dūrād udakavāhinīm
mataṅgasarasaṃ nāma hradaṃ samavagāhata', null, 3071013),
('ramayana-3-71-14', 14, 'Aranya Kanda, Sarga 71, Verse 14', 'स तु शोकसमाविष्टो रामो दशरथात्मजः।
विवेश नलिनीं पम्पां पङ्कजैश्च समावृताम्॥', 'sa tu śokasamāviṣṭo rāmo daśarathātmajaḥ
viveśa nalinīṃ pampāṃ paṅkajaiś ca samāvṛtām', null, 3071014),
('ramayana-3-71-15', 15, 'Aranya Kanda, Sarga 71, Verse 15', 'तिलकाशोकपुंनागबकुलोद्दाल काशिनीम्।
रम्योपवनसंबाधां पद्मसंपीडितोदकाम्॥', 'tilakāśokapuṃnāgabakuloddāla kāśinīm
ramyopavanasaṃbādhāṃ padmasaṃpīḍitodakām', null, 3071015),
('ramayana-3-71-16', 16, 'Aranya Kanda, Sarga 71, Verse 16', 'स्फटिकोपमतोयाढ्यां श्लक्ष्णवालुकसंतताम्।
मत्स्यकच्छपसंबाधां तीरस्थद्रुमशोभिताम्॥', 'sphaṭikopamatoyāḍhyāṃ ślakṣṇavālukasaṃtatām
matsyakacchapasaṃbādhāṃ tīrasthadrumaśobhitām', null, 3071016),
('ramayana-3-71-17', 17, 'Aranya Kanda, Sarga 71, Verse 17', 'सखीभिरिव युक्ताभिर्लताभिरनुवेष्टिताम्।
किंनरोरगगन्धर्वयक्षराक्षससेविताम्।
नानाद्रुमलताकीर्णां शीतवारिनिधिं शुभाम्॥', 'sakhībhir iva yuktābhir latābhir anuveṣṭitām
kiṃnaroragagandharvayakṣarākṣasasevitām
nānādrumalatākīrṇāṃ śītavārinidhiṃ śubhām', null, 3071017),
('ramayana-3-71-18', 18, 'Aranya Kanda, Sarga 71, Verse 18', 'पद्मैः सौगन्धिकैस्ताम्रां शुक्लां कुमुदमण्डलैः।
नीलां कुवलयोद्धातैर्बहुवर्णां कुथामिव॥', 'padmaiḥ saugandhikais tāmrāṃ śuklāṃ kumudamaṇḍalaiḥ
nīlāṃ kuvalayoddhātair bahuvarṇāṃ kuthām iva', null, 3071018),
('ramayana-3-71-19', 19, 'Aranya Kanda, Sarga 71, Verse 19', 'अरविन्दोत्पलवतीं पद्मसौगन्धिकायुताम्।
पुष्पिताम्रवणोपेतां बर्हिणोद्घुष्टनादिताम्॥', 'aravindotpalavatīṃ padmasaugandhikāyutām
puṣpitāmravaṇopetāṃ barhiṇodghuṣṭanāditām', null, 3071019),
('ramayana-3-71-20', 20, 'Aranya Kanda, Sarga 71, Verse 20', 'स तां दृष्ट्वा ततः पम्पां रामः सौमित्रिणा सह।
विललाप च तेजस्वी कामाद्दशरथात्मजः॥', 'sa tāṃ dṛṣṭvā tataḥ pampāṃ rāmaḥ saumitriṇā saha
vilalāpa ca tejasvī kāmād daśarathātmajaḥ', null, 3071020),
('ramayana-3-71-21', 21, 'Aranya Kanda, Sarga 71, Verse 21', 'तिलकैर्बीजपूरैश्च वटैः शुक्लद्रुमैस्तथा।
पुष्पितैः करवीरैश्च पुंनागैश्च सुपुष्पितैः॥', 'tilakair bījapūraiś ca vaṭaiḥ śukladrumais tathā
puṣpitaiḥ karavīraiś ca puṃnāgaiś ca supuṣpitaiḥ', null, 3071021),
('ramayana-3-71-22', 22, 'Aranya Kanda, Sarga 71, Verse 22', 'मालतीकुन्दगुल्मैश्च भण्डीरैर्निचुलैस्तथा।
अशोकैः सप्तपर्णैश्च केतकैरतिमुक्तकैः।
अन्यैश्च विविधैर्वृक्षैः प्रमदेवोपशोभिताम्॥', 'mālatīkundagulmaiś ca bhaṇḍīrair niculais tathā
aśokaiḥ saptaparṇaiś ca ketakair atimuktakaiḥ
anyaiś ca vividhair vṛkṣaiḥ pramadevopaśobhitām', null, 3071022),
('ramayana-3-71-23', 23, 'Aranya Kanda, Sarga 71, Verse 23', 'अस्यास्तीरे तु पूर्वोक्तः पर्वतो धातुमण्डितः।
ऋश्यमूक इति ख्यातश्चित्रपुष्पितकाननः॥', 'asyās tīre tu pūrvoktaḥ parvato dhātumaṇḍitaḥ
ṛśyamūka iti khyātaś citrapuṣpitakānanaḥ', null, 3071023),
('ramayana-3-71-24', 24, 'Aranya Kanda, Sarga 71, Verse 24', 'हरिरृक्षरजो नाम्नः पुत्रस्तस्य महात्मनः।
अध्यास्ते तं महावीर्यः सुग्रीव इति विश्रुतः॥', 'harir ṛkṣarajo nāmnaḥ putras tasya mahātmanaḥ
adhyāste taṃ mahāvīryaḥ sugrīva iti viśrutaḥ', null, 3071024),
('ramayana-3-71-25', 25, 'Aranya Kanda, Sarga 71, Verse 25', 'सुग्रीवमभिगच्छ त्वं वानरेन्द्रं नरर्षभ।
इत्युवाच पुनर्वाक्यं लक्ष्मणं सत्यविक्रमम्॥', 'sugrīvam abhigaccha tvaṃ vānarendraṃ nararṣabha
ity uvāca punar vākyaṃ lakṣmaṇaṃ satyavikramam', null, 3071025),
('ramayana-3-71-26', 26, 'Aranya Kanda, Sarga 71, Verse 26', 'ततो महद्वर्त्म च दूरसंक्रमं क्रमेण गत्वा प्रविलोकयन्वनम्।
ददर्श पम्पां शुभदर्श काननामनेकनानाविधपक्षिसंकुलाम्॥', 'tato mahad vartma ca dūrasaṃkramaṃ krameṇa gatvā pravilokayan vanam
dadarśa pampāṃ śubhadarśa kānanām anekanānāvidhapakṣisaṃkulām', null, 3071026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into translations (verse_id, language, text, source_id, is_primary) values
('ramayana-3-1-1', 'en', 'Entering the vast Dandaka forest, the self-possessed and unconquerable Rama saw a circle of hermitages of ascetics.', 'veda-app-ai-draft', true),
('ramayana-3-1-2', 'en', 'It was strewn with kusha grass and bark garments and filled with spiritual radiance, as hard to look at as the blazing disc of the sun in the sky.', 'veda-app-ai-draft', true),
('ramayana-3-1-3', 'en', 'It was a refuge for all creatures, its courtyards always swept clean, honoured and danced in by troupes of apsaras.', 'veda-app-ai-draft', true),
('ramayana-3-1-4', 'en', 'It was adorned with large fire-sanctuaries, ladles and vessels, deerskins, kusha grass, firewood, water pots, fruits and roots.', 'veda-app-ai-draft', true),
('ramayana-3-1-5', 'en', 'It was surrounded by great sacred forest trees bearing sweet fruit, worshipped with offerings and oblations, and resounding with Vedic chanting.', 'veda-app-ai-draft', true),
('ramayana-3-1-6', 'en', 'It was strewn with wild flowers and had a lotus pond; and the sages there lived on fruits and roots, were self-controlled, and wore bark and black deerskin.', 'veda-app-ai-draft', true),
('ramayana-3-1-7', 'en', 'It was surrounded by ancient sages bright as the sun and fire, and adorned with great seers of holy, restrained diet.', 'veda-app-ai-draft', true),
('ramayana-3-1-8', 'en', 'Resounding with Vedic chanting, like the abode of Brahma itself, it was graced by noble brahmins who knew the Absolute.', 'veda-app-ai-draft', true),
('ramayana-3-1-9', 'en', 'Seeing that circle of hermitages, the glorious and mighty Rama unstrung his great bow and approached.', 'veda-app-ai-draft', true),
('ramayana-3-1-10', 'en', 'The great seers, endowed with divine insight, saw Rama and the renowned Sita and came forward joyfully to meet them.', 'veda-app-ai-draft', true),
('ramayana-3-1-11', 'en', 'Seeing him like the rising moon, those righteous sages firm in their vows received him, speaking words of blessing.', 'veda-app-ai-draft', true),
('ramayana-3-1-12', 'en', 'Amazed, they gazed at the form, build, grace, gentleness and fine dress of Rama the forest-dweller.', 'veda-app-ai-draft', true),
('ramayana-3-1-13', 'en', 'All the forest-dwellers gazed at Sita, Lakshmana and Rama with unblinking eyes, as at a wonder.', 'veda-app-ai-draft', true),
('ramayana-3-1-14', 'en', 'Those noble sages, devoted to the welfare of all beings, lodged Rama as their guest in a leaf hut.', 'veda-app-ai-draft', true),
('ramayana-3-1-15', 'en', 'Then the noble, righteous sages, bright as fire, honoured Rama by due rite and brought him water.', 'veda-app-ai-draft', true),
('ramayana-3-1-16', 'en', 'Offering him roots, flowers, forest fruits and the hermitage itself, those who knew dharma spoke with joined palms.', 'veda-app-ai-draft', true),
('ramayana-3-1-17', 'en', 'The king is the protector of dharma for his people, their famous refuge, worthy of worship and honour, the bearer of the rod of justice, and their elder.', 'veda-app-ai-draft', true),
('ramayana-3-1-18', 'en', 'O Rama, the king protects his subjects as a fourth part of Indra; therefore the king, honoured by the world, enjoys fine things.', 'veda-app-ai-draft', true),
('ramayana-3-1-19', 'en', 'We who live in your realm must be protected by you; whether you live in the city or in the forest, you are our king, lord of the people.', 'veda-app-ai-draft', true),
('ramayana-3-1-20', 'en', 'O king, we have laid down the rod of force, conquered anger and mastered our senses; we ascetics must always be protected by you, like a child in the womb.', 'veda-app-ai-draft', true),
('ramayana-3-1-21', 'en', 'Having said this, they honoured Rama and Lakshmana with fruits, roots, wild flowers and many other foods.', 'veda-app-ai-draft', true),
('ramayana-3-1-22', 'en', 'Likewise other ascetics, perfected and bright as fire, upright in conduct, properly gratified the lord Rama.', 'veda-app-ai-draft', true),
('ramayana-3-2-1', 'en', 'Having received hospitality, Rama took leave of all the sages at sunrise and plunged deeper into the forest.', 'veda-app-ai-draft', true),
('ramayana-3-2-2', 'en', 'It was crowded with many kinds of deer, haunted by tigers and wolves, its trees, creepers and shrubs broken, its pools hard to see.', 'veda-app-ai-draft', true),
('ramayana-3-2-3', 'en', 'Followed by Lakshmana, Rama saw the heart of the forest, loud with crickets and many kinds of birds.', 'veda-app-ai-draft', true),
('ramayana-3-2-4', 'en', 'There, in the middle of that forest full of fierce beasts, Rama saw a man-eater as large as a mountain peak, with a mighty roar.', 'veda-app-ai-draft', true),
('ramayana-3-2-5', 'en', 'He had deep-set eyes, a huge mouth, a monstrous shape and a misshapen belly; he was loathsome, crooked, tall, deformed and frightful to see.', 'veda-app-ai-draft', true),
('ramayana-3-2-6', 'en', 'He wore a tiger skin wet with fat and splashed with blood, terrifying to all beings, his mouth gaping like Death.', 'veda-app-ai-draft', true),
('ramayana-3-2-7', 'en', 'He had three lions, four tigers, two wolves, ten spotted deer and a great elephant''s head with its tusks, smeared with fat,', 'veda-app-ai-draft', true),
('ramayana-3-2-8', 'en', 'impaled on an iron spear, roaring loudly. Seeing Rama, Lakshmana and Sita of Mithila,', 'veda-app-ai-draft', true),
('ramayana-3-2-9', 'en', 'he rushed at them in fury like Death at living creatures, and let out a terrible roar as if shaking the earth.', 'veda-app-ai-draft', true),
('ramayana-3-2-10', 'en', 'Snatching up Sita, he moved off and said: ''You two wear matted hair and bark, yet have a wife with you; your lives are nearly over,', 'veda-app-ai-draft', true),
('ramayana-3-2-11', 'en', 'you have entered the Dandaka forest carrying arrows, bows and swords. How is it that two ascetics live with a woman?', 'veda-app-ai-draft', true),
('ramayana-3-2-12', 'en', 'Who are you, wicked ones doing wrong and disgracing the sages? I am the demon named Viradha, roaming this impassable forest,', 'veda-app-ai-draft', true),
('ramayana-3-2-13', 'en', 'always armed and eating the flesh of seers. This lovely woman will be my wife, and I will drink the blood of you two sinners in battle.''', 'veda-app-ai-draft', true),
('ramayana-3-2-14', 'en', 'Hearing the bold and arrogant words of the wicked Viradha, Sita, daughter of Janaka, was alarmed and trembled with fear like a plantain tree in a gale.', 'veda-app-ai-draft', true),
('ramayana-3-2-15', 'en', 'Seeing the lovely Sita in Viradha''s grip, Rama spoke to Lakshmana with his mouth gone dry:', 'veda-app-ai-draft', true),
('ramayana-3-2-16', 'en', '''Look, gentle one, at the daughter of King Janaka, my virtuous wife, raised in great comfort, a famous princess, now in Viradha''s grip.', 'veda-app-ai-draft', true),
('ramayana-3-2-17', 'en', 'What Kaikeyi wanted for us, the boon she chose, has quickly come true this very day, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-2-18', 'en', 'She who, far-sighted for her son, was not satisfied with the kingdom, and by whom I, a friend of all beings, was sent to the forest, my middle mother has now got her wish.', 'veda-app-ai-draft', true),
('ramayana-3-2-19', 'en', 'Nothing gives me greater pain, Lakshmana, than another''s touch on Sita, not even my father''s death or the loss of my kingdom.', 'veda-app-ai-draft', true),
('ramayana-3-2-20', 'en', 'As Rama spoke, flooded with tears and grief, Lakshmana, angry, said, hissing like a trapped serpent:', 'veda-app-ai-draft', true),
('ramayana-3-2-21', 'en', '''You are the protector of all beings, like Indra; why do you grieve like one without protection, when I am your servant?', 'veda-app-ai-draft', true),
('ramayana-3-2-22', 'en', 'Today the earth will drink the blood of the demon Viradha, slain by my arrow in anger.', 'veda-app-ai-draft', true),
('ramayana-3-2-23', 'en', 'The anger I felt toward Bharata, who wanted the kingdom, I will release on Viradha, as Indra hurls his thunderbolt at a mountain.', 'veda-app-ai-draft', true),
('ramayana-3-2-24', 'en', 'Driven by the force of my arms, let my great arrow fall on his broad chest, take away his life, and let him fall reeling to the ground.''', 'veda-app-ai-draft', true),
('ramayana-3-3-1', 'en', 'Then Viradha spoke again, filling the forest with his voice: ''I am asking you: tell me, who are you and where will you go?''', 'veda-app-ai-draft', true),
('ramayana-3-3-2', 'en', 'The mighty Rama answered the demon with the blazing face, who was asking about his family line, the Ikshvakus:', 'veda-app-ai-draft', true),
('ramayana-3-3-3', 'en', '''Know us to be two kshatriyas of good conduct, wandering the forest. But we want to know you: who are you, roaming the Dandaka?''', 'veda-app-ai-draft', true),
('ramayana-3-3-4', 'en', 'Viradha said to Rama, whose valour was true: ''Listen, king, I will tell you; learn about me, Rama.', 'veda-app-ai-draft', true),
('ramayana-3-3-5', 'en', 'I am the son of Java, and my mother is Shatahrada; all the demons on earth call me Viradha.', 'veda-app-ai-draft', true),
('ramayana-3-3-6', 'en', 'By my austerity I have gained, by Brahma''s grace, the power not to be killed by weapons, and to be uncut and unpierced.', 'veda-app-ai-draft', true),
('ramayana-3-3-7', 'en', 'Leave this woman, go back the way you came and save yourselves quickly; I will not take your lives.''', 'veda-app-ai-draft', true),
('ramayana-3-3-8', 'en', 'Rama, his eyes red with anger, answered the misshapen, evil-minded demon Viradha:', 'veda-app-ai-draft', true),
('ramayana-3-3-9', 'en', '''Shame on you, low one, with your vile purpose; you are surely seeking death. Stand and fight; you will not leave me alive.''', 'veda-app-ai-draft', true),
('ramayana-3-3-10', 'en', 'Then Rama strung his bow, quickly fitted very sharp arrows and struck the demon.', 'veda-app-ai-draft', true),
('ramayana-3-3-11', 'en', 'From his bow with its taut string he released seven arrows with golden feathers, very swift, as fast as Garuda or the wind.', 'veda-app-ai-draft', true),
('ramayana-3-3-12', 'en', 'Piercing the body of Viradha, who wore peacock feathers, the fiery arrows fell to the ground smeared with blood.', 'veda-app-ai-draft', true),
('ramayana-3-3-13', 'en', 'Roaring loudly, he seized his spear, like Indra''s banner, and looked like Death with open jaws.', 'veda-app-ai-draft', true),
('ramayana-3-3-14', 'en', 'That spear, like a thunderbolt and blazing like fire in the sky, Rama, best of warriors, cut apart with two arrows.', 'veda-app-ai-draft', true),
('ramayana-3-3-15', 'en', 'Lakshmana broke the fierce demon''s left arm, and Rama forcefully broke his right arm.', 'veda-app-ai-draft', true),
('ramayana-3-3-16', 'en', 'With his arms broken, the alarmed demon fell quickly to the ground like a cloud, like a mountain split by a thunderbolt, and said to Rama, the best of men:', 'veda-app-ai-draft', true),
('ramayana-3-3-17', 'en', '''Dear one, I recognise you as Rama, Kausalya''s noble son; and the blessed Sita, and the renowned Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-3-18', 'en', 'Through a curse I entered this terrible demon body. I am the gandharva Tumburu, cursed by Kubera.', 'veda-app-ai-draft', true),
('ramayana-3-3-19', 'en', 'When I begged him for mercy, the famous one told me: "When Rama, son of Dasharatha, kills you in battle,', 'veda-app-ai-draft', true),
('ramayana-3-3-20', 'en', 'then you will regain your true nature and go to heaven." So said King Kubera to me, who was attached to Rambha,', 'veda-app-ai-draft', true),
('ramayana-3-3-21', 'en', 'angry because I had not attended on him. By your grace I am freed from that terrible curse. I will go to my own home; may all be well with you, scorcher of foes.', 'veda-app-ai-draft', true),
('ramayana-3-3-22', 'en', 'Not far from here, a yojana and a half away, lives the righteous and powerful sage Sharabhanga, radiant like the sun.', 'veda-app-ai-draft', true),
('ramayana-3-3-23', 'en', 'Go to him quickly; he will do you good. And, Rama, put me in a pit and go on safely.', 'veda-app-ai-draft', true),
('ramayana-3-3-24', 'en', 'This is the ancient custom for demons whose life has gone: those who are placed in a pit gain everlasting worlds.''', 'veda-app-ai-draft', true),
('ramayana-3-3-25', 'en', 'Having said this to Rama, the mighty Viradha, wounded by arrows, left his body and reached heaven.', 'veda-app-ai-draft', true),
('ramayana-3-3-26', 'en', 'Lifting him up, still loudly roaring, with ears like spikes, they threw Viradha into the pit.', 'veda-app-ai-draft', true),
('ramayana-3-3-27', 'en', 'Having slain the demon and recovered Sita, the two with their gold-adorned bows roamed joyfully in the great forest, like the moon and sun in the sky.', 'veda-app-ai-draft', true),
('ramayana-3-4-1', 'en', 'Having killed the demon Viradha of terrible strength, the valiant Rama embraced and comforted Sita, then spoke to his radiant brother Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-4-2', 'en', '''This forest is hard and dangerous, and we are not used to forest life; let us go quickly to Sharabhanga, rich in austerity.''', 'veda-app-ai-draft', true),
('ramayana-3-4-3', 'en', 'Rama went to Sharabhanga''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-4-4', 'en', 'Near Sharabhanga, who had godlike power and a soul purified by austerity, he saw a great wonder.', 'veda-app-ai-draft', true),
('ramayana-3-4-5', 'en', 'He saw the lord of the gods, shining in body like the sun and fire, not touching the earth.', 'veda-app-ai-draft', true),
('ramayana-3-4-6', 'en', 'The god wore bright ornaments and spotless clothes, and was worshipped by many great souls like himself.', 'veda-app-ai-draft', true),
('ramayana-3-4-7', 'en', 'Not far away Rama saw his chariot standing in the sky, yoked to green horses, shining like the young sun.', 'veda-app-ai-draft', true),
('ramayana-3-4-8', 'en', 'He saw a spotless parasol, like a mass of white cloud or the moon''s disc, adorned with bright garlands.', 'veda-app-ai-draft', true),
('ramayana-3-4-9', 'en', 'Two excellent whisks with golden handles, very precious, were held by two women and waved over his head.', 'veda-app-ai-draft', true),
('ramayana-3-4-10', 'en', 'Many gandharvas, gods, perfected beings and great seers praised the god in the sky with fine words.', 'veda-app-ai-draft', true),
('ramayana-3-4-11', 'en', 'Seeing Indra there, Rama said to Lakshmana: ''The heavenly horses of Indra we heard of long ago, travelling through the sky, these must be they.', 'veda-app-ai-draft', true),
('ramayana-3-4-12', 'en', 'And these young men standing around the chariot, tiger among men, a hundred and a hundred, wearing earrings and holding swords,', 'veda-app-ai-draft', true),
('ramayana-3-4-13', 'en', 'all with necklaces bright as fire on their chests, look twenty-five years old, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-4-14', 'en', 'For that, they say, is the age the gods always have, just as these handsome tigers among men appear.', 'veda-app-ai-draft', true),
('ramayana-3-4-15', 'en', 'Stay here with Sita for a moment, Lakshmana, until I find out clearly who this shining one in the chariot is.''', 'veda-app-ai-draft', true),
('ramayana-3-4-16', 'en', 'Having told Lakshmana ''Wait here'', Rama walked toward Sharabhanga''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-4-17', 'en', 'Then Indra, husband of Shachi, seeing Rama approach, took leave of Sharabhanga and said to the gods:', 'veda-app-ai-draft', true),
('ramayana-3-4-18', 'en', '''Rama is coming here. Until he speaks to me, take me to my destination; only afterwards may he see me.', 'veda-app-ai-draft', true),
('ramayana-3-4-19', 'en', 'I will soon see him victorious and his purpose fulfilled; for he has a great deed to do that others could hardly do.''', 'veda-app-ai-draft', true),
('ramayana-3-4-20', 'en', 'So saying, the wielder of the thunderbolt took leave of the ascetic, honoured him, and went to heaven in his chariot drawn by green horses.', 'veda-app-ai-draft', true),
('ramayana-3-4-21', 'en', 'When the thousand-eyed god had gone, Rama with his companions approached Sharabhanga, who was attending to his fire offering.', 'veda-app-ai-draft', true),
('ramayana-3-4-22', 'en', 'Rama, Sita and Lakshmana touched his feet; given permission, invited and offered lodging, they sat down.', 'veda-app-ai-draft', true),
('ramayana-3-4-23', 'en', 'Then Rama asked about Indra''s visit, and Sharabhanga told him everything.', 'veda-app-ai-draft', true),
('ramayana-3-4-24', 'en', '''Rama, this giver of boons wants to take me to Brahma''s world, which I have won by fierce austerity and which is hard for the undisciplined to reach.', 'veda-app-ai-draft', true),
('ramayana-3-4-25', 'en', 'But knowing you were near, tiger among men, I will not go to Brahma''s world without seeing you, my dear guest.', 'veda-app-ai-draft', true),
('ramayana-3-4-26', 'en', 'Having met you, I will go to the heaven the gods dwell in. I have won imperishable, auspicious worlds, those of Brahma and of highest heaven; accept them from me.''', 'veda-app-ai-draft', true),
('ramayana-3-4-27', 'en', 'Thus addressed by the sage Sharabhanga, Rama, tiger among men and learned in all scriptures, replied:', 'veda-app-ai-draft', true),
('ramayana-3-4-28', 'en', '''Great sage, I will win all those worlds myself. But I would like a dwelling place pointed out to me here in the forest.''', 'veda-app-ai-draft', true),
('ramayana-3-4-29', 'en', 'Thus addressed by Rama, whose strength equalled Indra''s, the wise Sharabhanga spoke again:', 'veda-app-ai-draft', true),
('ramayana-3-4-30', 'en', '''Go to the ascetic Sutikshna, in a pure place in a lovely part of the forest; he will arrange a dwelling for you.', 'veda-app-ai-draft', true),
('ramayana-3-4-31', 'en', 'This is the path, tiger among men. Watch me for a moment, dear one, while I leave my limbs as a snake sheds its old skin.''', 'veda-app-ai-draft', true),
('ramayana-3-4-32', 'en', 'Then the mighty Sharabhanga, who knew the mantras, kindled the fire, made an offering of ghee and entered the fire.', 'veda-app-ai-draft', true),
('ramayana-3-4-33', 'en', 'The fire burned the great soul''s body hair, his hair, his old skin, bones, flesh and blood.', 'veda-app-ai-draft', true),
('ramayana-3-4-34', 'en', 'And Sharabhanga became a youth bright as fire, and rising from the pyre he shone.', 'veda-app-ai-draft', true),
('ramayana-3-4-35', 'en', 'Passing beyond the worlds of those who keep sacred fires, of great sages and of the gods, he ascended to Brahma''s world.', 'veda-app-ai-draft', true),
('ramayana-3-4-36', 'en', 'That best of brahmins, of holy deeds, saw the Grandfather Brahma with his attendants in that world; and Brahma, seeing him, rejoiced and said, ''Welcome!''', 'veda-app-ai-draft', true),
('ramayana-3-5-1', 'en', 'When Sharabhanga had gone to heaven, groups of sages gathered and came to Rama, who was blazing with energy.', 'veda-app-ai-draft', true),
('ramayana-3-5-2', 'en', 'There were Vaikhanasas, Valakhilyas, Samprakshalas, Marichipas, many Ashmakuttas and ascetics who lived on leaves,', 'veda-app-ai-draft', true),
('ramayana-3-5-3', 'en', 'others who used their teeth as mortars, others who stood immersed in water, sages who lived on water and others who lived on air,', 'veda-app-ai-draft', true),
('ramayana-3-5-4', 'en', 'those who lived in the open sky, those who slept on bare ground, those who stood upright, the self-controlled, and those who wore wet clothes,', 'veda-app-ai-draft', true),
('ramayana-3-5-5', 'en', 'those devoted to chanting and constant austerity, and those who practised the five fires; all endowed with spiritual splendour and firm in yoga, these ascetics came to Rama at Sharabhanga''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-5-6', 'en', 'Approaching Rama, best of those who uphold dharma, the groups of sages who knew dharma spoke with composure:', 'veda-app-ai-draft', true),
('ramayana-3-5-7', 'en', '''You are the great warrior of the Ikshvaku line and of the earth, its chief and protector, as Indra is of the gods.', 'veda-app-ai-draft', true),
('ramayana-3-5-8', 'en', 'You are famed in the three worlds for glory and valour; in you are devotion to your father, truth and abundant dharma.', 'veda-app-ai-draft', true),
('ramayana-3-5-9', 'en', 'Having come to you, great soul who knows and loves dharma, we will speak as petitioners, lord; please forgive us.', 'veda-app-ai-draft', true),
('ramayana-3-5-10', 'en', 'Great is the wrong of a king who takes a sixth of the produce as tax and does not protect his people like his own sons.', 'veda-app-ai-draft', true),
('ramayana-3-5-11', 'en', 'But one who cares for all who live in his realm as for his own life, or for his beloved sons, always attentive and protecting,', 'veda-app-ai-draft', true),
('ramayana-3-5-12', 'en', 'such a king wins lasting fame for many years, Rama, reaches the realm of Brahma and is honoured there.', 'veda-app-ai-draft', true),
('ramayana-3-5-13', 'en', 'Of the high dharma that a sage living on roots and fruits performs, a fourth part goes to the king who protects his people rightly.', 'veda-app-ai-draft', true),
('ramayana-3-5-14', 'en', 'This great company of forest hermits, mostly brahmins, has you as protector, yet is being killed by demons as if it had none.', 'veda-app-ai-draft', true),
('ramayana-3-5-15', 'en', 'Come and see the bodies of many sages of purified soul, killed in many ways by terrible demons in the forest.', 'veda-app-ai-draft', true),
('ramayana-3-5-16', 'en', 'Great slaughter is being done to those who live by the Pampa river, along the Mandakini, and on Chitrakuta.', 'veda-app-ai-draft', true),
('ramayana-3-5-17', 'en', 'We cannot bear the terrible harm being done to ascetics in the forest by demons of dreadful deeds.', 'veda-app-ai-draft', true),
('ramayana-3-5-18', 'en', 'So we have come to you, our refuge, seeking shelter. Protect us, Rama, who are being killed by night-roamers.''', 'veda-app-ai-draft', true),
('ramayana-3-5-19', 'en', 'Hearing this from the ascetics, the righteous Rama said to them all: ''You should not speak to me like this; I am to be commanded by ascetics.', 'veda-app-ai-draft', true),
('ramayana-3-5-20', 'en', 'I have come by chance to fulfil your purpose; this stay of mine in the forest will bear great fruit. I wish to kill in battle the demons who are enemies of ascetics.''', 'veda-app-ai-draft', true),
('ramayana-3-5-21', 'en', 'Having given his promise to the ascetics, the hero, steadfast in dharma, went with Lakshmana and the ascetics to Sutikshna.', 'veda-app-ai-draft', true),
('ramayana-3-6-1', 'en', 'Rama, scorcher of foes, with his brother and Sita, went to Sutikshna''s hermitage with those brahmins.', 'veda-app-ai-draft', true),
('ramayana-3-6-2', 'en', 'After travelling a long way and crossing rivers full of water, he saw a vast mountain rising like a great cloud.', 'veda-app-ai-draft', true),
('ramayana-3-6-3', 'en', 'Then the two best of the Ikshvakus, with Sita, entered a forest always full of many kinds of trees.', 'veda-app-ai-draft', true),
('ramayana-3-6-4', 'en', 'Entering the deep forest full of flowering and fruiting trees, he saw a secluded hermitage hung with strings of bark garments.', 'veda-app-ai-draft', true),
('ramayana-3-6-5', 'en', 'There Rama formally addressed the ascetic Sutikshna, seated, bearing matted hair caked with dirt, grown great in austerity.', 'veda-app-ai-draft', true),
('ramayana-3-6-6', 'en', '''I am Rama, holy one; I have come to see you. Speak to me, knower of dharma, great seer of true valour.''', 'veda-app-ai-draft', true),
('ramayana-3-6-7', 'en', 'Looking at the hero Rama, best of upholders of dharma, he embraced him with both arms and said:', 'veda-app-ai-draft', true),
('ramayana-3-6-8', 'en', '''Welcome, hero Rama, best of upholders of dharma; now that you have come, this hermitage has found its protector.', 'veda-app-ai-draft', true),
('ramayana-3-6-9', 'en', 'Waiting for you, glorious one, I did not leave my body on earth to rise to the world of the gods.', 'veda-app-ai-draft', true),
('ramayana-3-6-10', 'en', 'I heard you had lost your kingdom and gone to Chitrakuta. Indra, king of the gods, came here and said I had won all worlds by my holy deeds.', 'veda-app-ai-draft', true),
('ramayana-3-6-11', 'en', 'By my grace, enjoy with your wife and Lakshmana those worlds frequented by divine seers that I have won by austerity.''', 'veda-app-ai-draft', true),
('ramayana-3-6-12', 'en', 'Self-possessed Rama answered that fierce, radiant, truthful sage, as Indra answers Brahma:', 'veda-app-ai-draft', true),
('ramayana-3-6-13', 'en', '''Great sage, I will win the worlds myself. But I would like a dwelling place pointed out to me here in the forest.', 'veda-app-ai-draft', true),
('ramayana-3-6-14', 'en', 'You are skilled in everything and devoted to the good of all beings, as the great Sharabhanga Gautama told me.''', 'veda-app-ai-draft', true),
('ramayana-3-6-15', 'en', 'Thus addressed by Rama, the world-famous great seer, flooded with joy, spoke sweet words:', 'veda-app-ai-draft', true),
('ramayana-3-6-16', 'en', '''This very hermitage is good, Rama; enjoy yourself here. It is frequented by groups of sages and always has roots and fruits.', 'veda-app-ai-draft', true),
('ramayana-3-6-17', 'en', 'Herds of deer come to this hermitage, glorious one, roam about fearless and go away again, tempting us.', 'veda-app-ai-draft', true),
('ramayana-3-6-18', 'en', 'Hearing these words of the great seer, Rama, Lakshmana''s elder brother, drew his bow with its arrow and said firmly:', 'veda-app-ai-draft', true),
('ramayana-3-6-19', 'en', '''If I were to kill those herds of deer that come here with my sharp-edged arrow bright as lightning,', 'veda-app-ai-draft', true),
('ramayana-3-6-20', 'en', 'you would be distressed; what could be worse than that? So I do not think I should stay long in this hermitage.''', 'veda-app-ai-draft', true),
('ramayana-3-6-21', 'en', 'Having said this to the giver of boons, Rama went to his evening prayers; after the western twilight rite he prepared to stay there.', 'veda-app-ai-draft', true),
('ramayana-3-6-22', 'en', 'Then, seeing night had come after the twilight rites, the great-souled Sutikshna himself gave the two best of men fine ascetics'' food, with great honour.', 'veda-app-ai-draft', true),
('ramayana-3-7-1', 'en', 'Rama and Lakshmana, honoured by Sutikshna, spent the night there and woke at dawn.', 'veda-app-ai-draft', true),
('ramayana-3-7-2', 'en', 'Rising at the proper time, Rama with Sita bathed in cool water fragrant with lotuses.', 'veda-app-ai-draft', true),
('ramayana-3-7-3', 'en', 'Then Sita, Rama and Lakshmana duly worshipped the fire and the gods at dawn in the forest, the refuge of ascetics,', 'veda-app-ai-draft', true),
('ramayana-3-7-4', 'en', 'and seeing the rising sun, freed from impurity, they approached Sutikshna and spoke gently:', 'veda-app-ai-draft', true),
('ramayana-3-7-5', 'en', '''We have lived happily, holy one, honoured by you who are worthy of honour. We take our leave and will go; the sages are urging us on.', 'veda-app-ai-draft', true),
('ramayana-3-7-6', 'en', 'We are eager to see the whole circle of hermitages of the virtuous sages who live in the Dandaka forest.', 'veda-app-ai-draft', true),
('ramayana-3-7-7', 'en', 'We wish your leave to go with these best of sages, devoted to dharma, restrained by austerity, like fires without smoke.', 'veda-app-ai-draft', true),
('ramayana-3-7-8', 'en', 'before the sun grows too fierce with unbearable heat, like a low-born man who has gained wealth by wrong means,', 'veda-app-ai-draft', true),
('ramayana-3-7-9', 'en', 'we wish to go.'' Saying this, Rama with Lakshmana and Sita bowed at the sage''s feet.', 'veda-app-ai-draft', true),
('ramayana-3-7-10', 'en', 'The best of sages raised the two who were touching his feet, embraced them tightly and lovingly, and said:', 'veda-app-ai-draft', true),
('ramayana-3-7-11', 'en', '''Go safely on your way, Rama, with Lakshmana and this Sita who follows you like a shadow.', 'veda-app-ai-draft', true),
('ramayana-3-7-12', 'en', 'See the lovely hermitages of the ascetics of the Dandaka forest, hero, whose souls are purified by austerity.', 'veda-app-ai-draft', true),
('ramayana-3-7-13', 'en', 'forests rich in fruits and roots and full of flowers, with calm herds of deer and peaceful flocks of birds,', 'veda-app-ai-draft', true),
('ramayana-3-7-14', 'en', 'lakes and ponds with clear water, full of blooming lotuses and scattered with karandava ducks,', 'veda-app-ai-draft', true),
('ramayana-3-7-15', 'en', 'You will see mountain springs lovely to look at, and charming forests filled with the cries of peacocks.', 'veda-app-ai-draft', true),
('ramayana-3-7-16', 'en', 'Go, dear child; and you too, Lakshmana. Having seen them, come back to my hermitage again.''', 'veda-app-ai-draft', true),
('ramayana-3-7-17', 'en', 'Saying ''So be it'', Rama with Lakshmana walked around the sage respectfully and prepared to set out.', 'veda-app-ai-draft', true),
('ramayana-3-7-18', 'en', 'Then the large-eyed Sita handed the two brothers their fine quivers, their bows and their bright swords.', 'veda-app-ai-draft', true),
('ramayana-3-7-19', 'en', 'Binding on their fine quivers and taking up their twanging bows, Rama and Lakshmana left the hermitage to go.', 'veda-app-ai-draft', true),
('ramayana-3-8-1', 'en', 'As Rama set out with Sutikshna''s leave, Sita spoke to her husband in an affectionate voice:', 'veda-app-ai-draft', true),
('ramayana-3-8-2', 'en', '''This great dharma is reached by very subtle means; and here one can keep it only by turning away from the vices born of desire.', 'veda-app-ai-draft', true),
('ramayana-3-8-3', 'en', 'There are three vices born of desire: lying is the first, and two are heavier still, going to another''s wife, and cruelty without enmity.', 'veda-app-ai-draft', true),
('ramayana-3-8-4', 'en', 'Falsehood you have never spoken and never will, Rama; how then could you desire other men''s wives, which destroys dharma?', 'veda-app-ai-draft', true),
('ramayana-3-8-5', 'en', 'All this can be borne by those who master their senses, mighty-armed one; and I know your senses are under your control, handsome one.', 'veda-app-ai-draft', true),
('ramayana-3-8-6', 'en', 'The third, this cruelty of taking others'' lives without enmity, done through delusion, is now before you.', 'veda-app-ai-draft', true),
('ramayana-3-8-7', 'en', 'You have promised, hero, to kill demons in battle to protect the sages of the Dandaka forest.', 'veda-app-ai-draft', true),
('ramayana-3-8-8', 'en', 'For this purpose you have set out with your brother, carrying bow and arrows, for the forest known as Dandaka.', 'veda-app-ai-draft', true),
('ramayana-3-8-9', 'en', 'Seeing you set out, my mind is troubled with worry, thinking about your conduct and what will truly be for your highest good.', 'veda-app-ai-draft', true),
('ramayana-3-8-10', 'en', 'I do not like this going to the Dandaka forest, hero. I will tell you the reason; listen as I speak.', 'veda-app-ai-draft', true),
('ramayana-3-8-11', 'en', 'You have gone into the forest with your brother, bow and arrows in hand; seeing all the forest creatures, might you not spend your arrows on them?', 'veda-app-ai-draft', true),
('ramayana-3-8-12', 'en', 'Here a kshatriya''s bow is like fuel for fire: when kept close, it greatly increases one''s fierce energy.', 'veda-app-ai-draft', true),
('ramayana-3-8-13', 'en', 'Long ago, mighty-armed one, there was a truthful and pure ascetic in a holy forest where deer and birds were happy.', 'veda-app-ai-draft', true),
('ramayana-3-8-14', 'en', 'To obstruct his austerity, Indra, husband of Shachi, came to the hermitage disguised as a soldier, sword in hand.', 'veda-app-ai-draft', true),
('ramayana-3-8-15', 'en', 'He left that fine sword in the hermitage, given as a deposit in trust to the sage who was engaged in holy austerity.', 'veda-app-ai-draft', true),
('ramayana-3-8-16', 'en', 'Having received that weapon and intent on guarding the deposit, he carried it around the forest, keeping faith.', 'veda-app-ai-draft', true),
('ramayana-3-8-17', 'en', 'Wherever he went to gather roots and fruits, he never went without that sword, intent on guarding the trust.', 'veda-app-ai-draft', true),
('ramayana-3-8-18', 'en', 'Always carrying the weapon, the ascetic gradually turned his mind to cruelty, giving up his resolve in austerity.', 'veda-app-ai-draft', true),
('ramayana-3-8-19', 'en', 'Then, delighting in cruelty, careless and dragged down by wrongdoing, the sage went to hell through his association with the weapon.', 'veda-app-ai-draft', true),
('ramayana-3-8-20', 'en', 'I remind you out of love and great respect, not to teach you; never make up your mind, bow in hand,', 'veda-app-ai-draft', true),
('ramayana-3-8-21', 'en', 'to kill demons living in Dandaka without enmity. I do not want you to kill beings who have done no wrong, hero.', 'veda-app-ai-draft', true),
('ramayana-3-8-22', 'en', 'For heroic kshatriyas living with restraint in the forest, this is all the bow is for: protecting the suffering.', 'veda-app-ai-draft', true),
('ramayana-3-8-23', 'en', 'Where is the weapon and where the forest, where the warrior''s way and where austerity? These do not go together; let us honour the dharma of the place we are in.', 'veda-app-ai-draft', true),
('ramayana-3-8-24', 'en', 'Handling weapons makes the mind of a noble person turbid. When you return to Ayodhya, then you can follow the warrior''s duty.', 'veda-app-ai-draft', true),
('ramayana-3-8-25', 'en', 'My mother-in-law and father-in-law would have unending joy if, having set aside the kingdom, you lived here devoted as a sage.', 'veda-app-ai-draft', true),
('ramayana-3-8-26', 'en', 'From dharma comes wealth, from dharma comes happiness; by dharma one gains everything; dharma is the essence of this world.', 'veda-app-ai-draft', true),
('ramayana-3-8-27', 'en', 'The wise reach dharma by carefully disciplining themselves with various restraints; happiness is not gained through comfort.', 'veda-app-ai-draft', true),
('ramayana-3-8-28', 'en', 'Gentle one, practise dharma in the ascetics'' forest always with a pure mind; for you truly know everything, even the three worlds.', 'veda-app-ai-draft', true),
('ramayana-3-8-29', 'en', 'I have said this out of a woman''s restlessness; who could teach you dharma? Think it over with your brother and do quickly what seems right.', 'veda-app-ai-draft', true),
('ramayana-3-9-1', 'en', 'Hearing these words spoken by Sita, devoted to her husband, Rama, steadfast in dharma, answered her:', 'veda-app-ai-draft', true),
('ramayana-3-9-2', 'en', '''Queen, you have spoken good, affectionate words worthy of you and of your family, knower of dharma, daughter of Janaka.', 'veda-app-ai-draft', true),
('ramayana-3-9-3', 'en', 'But what shall I say, queen? You yourself said it: kshatriyas carry the bow so that no cry of distress is heard.', 'veda-app-ai-draft', true),
('ramayana-3-9-4', 'en', 'And those sages in the Dandaka, firm in their vows, are in distress; they came to me themselves, Sita, the refuges seeking refuge.', 'veda-app-ai-draft', true),
('ramayana-3-9-5', 'en', 'Living in the forest devoted to dharma, eating roots and fruits, they find no happiness, afraid of cruel demons.', 'veda-app-ai-draft', true),
('ramayana-3-9-6', 'en', 'Time and again, those devoted to many disciplines in the forest are eaten by dreadful demons who live on human flesh.', 'veda-app-ai-draft', true),
('ramayana-3-9-7', 'en', 'Being devoured, those best of brahmins living in the Dandaka said to me, ''Help us.''', 'veda-app-ai-draft', true),
('ramayana-3-9-8', 'en', 'Hearing these words from their mouths, I served at their feet and said this:', 'veda-app-ai-draft', true),
('ramayana-3-9-9', 'en', '''Be gracious to me; I feel boundless shame that such brahmins, whom I should approach, have approached me. What shall I do?'' I said before the brahmins.', 'veda-app-ai-draft', true),
('ramayana-3-9-10', 'en', 'Gathering together, they all said: ''We are sorely oppressed by many shape-shifting demons in the Dandaka forest, Rama; you must save us.', 'veda-app-ai-draft', true),
('ramayana-3-9-11', 'en', 'When the time for offerings comes, and on holy days, sinless one, the invincible flesh-eating demons attack us.', 'veda-app-ai-draft', true),
('ramayana-3-9-12', 'en', 'For us ascetics attacked by demons and seeking a way out, you are our highest refuge.', 'veda-app-ai-draft', true),
('ramayana-3-9-13', 'en', 'We could indeed kill the night-roamers by the power of our austerity, but we do not wish to spend the austerity we have gathered over long years.', 'veda-app-ai-draft', true),
('ramayana-3-9-14', 'en', 'Austerity is always full of obstacles and hard to practise, Rama; so we do not utter curses, even while being eaten by demons.', 'veda-app-ai-draft', true),
('ramayana-3-9-15', 'en', 'So protect us, with your brother, who are tormented by the demons of Dandaka; in the forest you are our protector.''', 'veda-app-ai-draft', true),
('ramayana-3-9-16', 'en', 'Hearing these words, daughter of Janaka, I promised the sages of Dandaka full protection.', 'veda-app-ai-draft', true),
('ramayana-3-9-17', 'en', 'Having promised, I cannot, while I live, go back on my word to the sages; truth is always dear to me.', 'veda-app-ai-draft', true),
('ramayana-3-9-18', 'en', 'I would give up my life, or even you, Sita, and Lakshmana, but I would not break a promise once made, especially one made to brahmins.', 'veda-app-ai-draft', true),
('ramayana-3-9-19', 'en', 'So I must protect the sages; even unasked I would do it, Sita, how much more having promised.', 'veda-app-ai-draft', true),
('ramayana-3-9-20', 'en', 'You said this out of love and friendship for me; I am pleased, Sita, for no one advises someone they do not care for. It is fitting and worthy of your family, lovely one.''', 'veda-app-ai-draft', true),
('ramayana-3-9-21', 'en', 'Having spoken thus to his beloved Sita, princess of Mithila, the great-souled Rama, bow in hand, went with Lakshmana to the lovely hermitage-forests.', 'veda-app-ai-draft', true),
('ramayana-3-10-1', 'en', 'Rama went in front, slender-waisted Sita in the middle, and behind them Lakshmana, bow in hand, followed.', 'veda-app-ai-draft', true),
('ramayana-3-10-2', 'en', 'Looking at many mountain slopes, forests and lovely rivers, the two went on with Sita.', 'veda-app-ai-draft', true),
('ramayana-3-10-3', 'en', 'cranes and chakravaka birds roaming the riverbanks, lakes full of lotuses and water birds,', 'veda-app-ai-draft', true),
('ramayana-3-10-4', 'en', 'herds of spotted deer, horned animals wild with rut, buffaloes, boars, and elephants that break trees.', 'veda-app-ai-draft', true),
('ramayana-3-10-5', 'en', 'Having travelled a long way, as the sun was sinking, they saw together a lovely lake a yojana long.', 'veda-app-ai-draft', true),
('ramayana-3-10-6', 'en', 'It was crowded with lotuses, adorned with herds of elephants, and full of cranes, swans, geese and other water creatures.', 'veda-app-ai-draft', true),
('ramayana-3-10-7', 'en', 'From that lovely lake of clear water came the sound of song and music, yet no one could be seen.', 'veda-app-ai-draft', true),
('ramayana-3-10-8', 'en', 'Then, out of curiosity, Rama and the great warrior Lakshmana began to question a sage named Dharmabhrit.', 'veda-app-ai-draft', true),
('ramayana-3-10-9', 'en', '''Hearing this wonder, great sage, we are all very curious. What is it? Please tell us.''', 'veda-app-ai-draft', true),
('ramayana-3-10-10', 'en', 'Thus addressed by Rama, the righteous sage began to tell the whole story of the lake''s power.', 'veda-app-ai-draft', true),
('ramayana-3-10-11', 'en', '''This lake, Rama, called Panchapsaras, lasts for ever; it was made by the sage Mandakarni through austerity.', 'veda-app-ai-draft', true),
('ramayana-3-10-12', 'en', 'For the great sage Mandakarni practised fierce austerity for ten thousand years, living on air and dwelling in water.', 'veda-app-ai-draft', true),
('ramayana-3-10-13', 'en', 'Then all the gods, led by Agni, became alarmed and said to one another, ''This sage is seeking the place of one of us.''', 'veda-app-ai-draft', true),
('ramayana-3-10-14', 'en', 'So, to obstruct his austerity, all the gods engaged five chief apsaras, bright as flashing lightning.', 'veda-app-ai-draft', true),
('ramayana-3-10-15', 'en', 'By those apsaras the sage, who knew the high and the low, was brought under the power of love, to serve the gods'' purpose.', 'veda-app-ai-draft', true),
('ramayana-3-10-16', 'en', 'Those five apsaras became the sage''s wives; a hidden home was made for them in this lake.', 'veda-app-ai-draft', true),
('ramayana-3-10-17', 'en', 'There the five apsaras live happily, delighting the sage, who through the power of his austerity has taken on youth.', 'veda-app-ai-draft', true),
('ramayana-3-10-18', 'en', 'As they play, this sound of music is heard, the lovely sound of song mingled with the jingle of ornaments.''', 'veda-app-ai-draft', true),
('ramayana-3-10-19', 'en', '''A wonder!'' said Rama with his brother, and accepted these words of the pure-souled sage.', 'veda-app-ai-draft', true),
('ramayana-3-10-20', 'en', 'As he was speaking, Rama saw a circle of hermitages, strewn with kusha grass and bark, surrounded by many trees.', 'veda-app-ai-draft', true),
('ramayana-3-10-21', 'en', 'Rama entered that splendid circle of hermitages with Sita and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-10-22', 'en', 'He lived happily there, honoured by great seers, and then went in turn to the hermitages of those ascetics', 'veda-app-ai-draft', true),
('ramayana-3-10-23', 'en', 'with whom the great master of weapons had stayed before: in some for ten months, in some for a year,', 'veda-app-ai-draft', true),
('ramayana-3-10-24', 'en', 'in some for four months, in others five or six, elsewhere for more months, in some for a month and a half more,', 'veda-app-ai-draft', true),
('ramayana-3-10-25', 'en', 'three months and eight months Rama lived happily; living thus in the hermitages of the sages and enjoying himself, ten years passed.', 'veda-app-ai-draft', true),
('ramayana-3-10-26', 'en', 'Having wandered around, Rama, who knew dharma, came back with Sita to Sutikshna''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-10-27', 'en', 'Coming to that hermitage, honoured by the sages, Rama, subduer of foes, stayed there for some time.', 'veda-app-ai-draft', true),
('ramayana-3-10-28', 'en', 'One day, staying at the hermitage and sitting humbly by the great sage Sutikshna, Rama said:', 'veda-app-ai-draft', true),
('ramayana-3-10-29', 'en', '''Holy one, I have always heard people say in their stories that Agastya, best of sages, lives in this forest.', 'veda-app-ai-draft', true),
('ramayana-3-10-30', 'en', 'But because the forest is so vast I do not know where the holy hermitage of that wise great seer is.', 'veda-app-ai-draft', true),
('ramayana-3-10-31', 'en', 'By your grace, I would go with my brother and Sita to Agastya to pay my respects to the sage.', 'veda-app-ai-draft', true),
('ramayana-3-10-32', 'en', 'This great wish turns in my heart: that I might myself serve that best of sages.''', 'veda-app-ai-draft', true),
('ramayana-3-10-33', 'en', 'Hearing the righteous Rama''s words, the sage Sutikshna, pleased, answered Dasharatha''s son:', 'veda-app-ai-draft', true),
('ramayana-3-10-34', 'en', '''I too wanted to tell you this, Rama: go to Agastya with Lakshmana and Sita.', 'veda-app-ai-draft', true),
('ramayana-3-10-35', 'en', 'Happily, you yourself have now spoken of it. I will tell you, child, where the great sage Agastya is.', 'veda-app-ai-draft', true),
('ramayana-3-10-36', 'en', 'Go four yojanas south from this hermitage, dear one; there is the great and splendid hermitage of Agastya''s brother,', 'veda-app-ai-draft', true),
('ramayana-3-10-37', 'en', 'in a part of the forest on dry ground, adorned with groves of pippali, lovely, full of flowers and fruit, echoing with many birds.', 'veda-app-ai-draft', true),
('ramayana-3-10-38', 'en', 'There are various lotus ponds there with clear, pleasant water, scattered with swans and ducks and graced by chakravakas.', 'veda-app-ai-draft', true),
('ramayana-3-10-39', 'en', 'Spend one night there, Rama, and go on in the morning, heading south along the edge of the forest.', 'veda-app-ai-draft', true),
('ramayana-3-10-40', 'en', 'Going a yojana further, you will come to Agastya''s hermitage in a charming part of the forest full of trees; Sita and Lakshmana will be happy there with you.', 'veda-app-ai-draft', true),
('ramayana-3-10-41', 'en', 'That lovely area is full of trees. If you have decided to see the great sage Agastya, set your mind on going today, glorious one.''', 'veda-app-ai-draft', true),
('ramayana-3-10-42', 'en', 'Hearing the sage, Rama bowed to him with his brother and set out for Agastya with Lakshmana and Sita.', 'veda-app-ai-draft', true),
('ramayana-3-10-43', 'en', 'He saw colourful forests, mountains like clouds, lakes and rivers along the way.', 'veda-app-ai-draft', true),
('ramayana-3-10-44', 'en', 'Travelling happily by the path Sutikshna had shown, he said to Lakshmana in great joy:', 'veda-app-ai-draft', true),
('ramayana-3-10-45', 'en', '''This must surely be the hermitage of the great-souled brother of the sage Agastya, of holy deeds.', 'veda-app-ai-draft', true),
('ramayana-3-10-46', 'en', 'For thousands of trees in this forest along the path, bent with loads of fruit and flowers, are as described.', 'veda-app-ai-draft', true),
('ramayana-3-10-47', 'en', 'And this sharp scent of ripe pippali, carried suddenly on the wind, comes from this forest.', 'veda-app-ai-draft', true),
('ramayana-3-10-48', 'en', 'Here and there piles of wood are seen stacked, and cut darbha grass gleaming like beryl lies on the path.', 'veda-app-ai-draft', true),
('ramayana-3-10-49', 'en', 'And in the middle of the forest one sees the top of the smoke from the hermitage fire, like the peak of a dark cloud.', 'veda-app-ai-draft', true),
('ramayana-3-10-50', 'en', 'Twice-born men who have bathed at secluded fords make offerings of flowers they have gathered themselves.', 'veda-app-ai-draft', true),
('ramayana-3-10-51', 'en', 'As I heard from Sutikshna, gentle one, this must surely be the hermitage of Agastya''s brother.', 'veda-app-ai-draft', true),
('ramayana-3-10-52', 'en', 'His brother, of holy deeds, for the good of the worlds, forcefully restrained death and made this southern region a place of refuge.', 'veda-app-ai-draft', true),
('ramayana-3-10-53', 'en', 'Here once, they say, lived two cruel brothers together, Vatapi and Ilvala, great demons who killed brahmins.', 'veda-app-ai-draft', true),
('ramayana-3-10-54', 'en', 'Taking the form of a brahmin and speaking refined Sanskrit, the pitiless Ilvala would invite brahmins to a memorial feast.', 'veda-app-ai-draft', true),
('ramayana-3-10-55', 'en', 'Then he would cook his brother, who had taken the form of a ram, and feed him to the brahmins in the manner of the memorial rite.', 'veda-app-ai-draft', true),
('ramayana-3-10-56', 'en', 'When the brahmins had eaten, Ilvala would call in a loud voice, ''Vatapi, come out!''', 'veda-app-ai-draft', true),
('ramayana-3-10-57', 'en', 'Hearing his brother''s call, Vatapi, bleating like a ram, burst out tearing apart the bodies of the brahmins.', 'veda-app-ai-draft', true),
('ramayana-3-10-58', 'en', 'In this way thousands of brahmins were destroyed by those shape-shifting flesh-eaters together, again and again.', 'veda-app-ai-draft', true),
('ramayana-3-10-59', 'en', 'Then the great seer Agastya, asked by the gods, ate that great demon at a memorial feast.', 'veda-app-ai-draft', true),
('ramayana-3-10-60', 'en', 'Then, saying ''It is done'' and giving water to wash his hands, Ilvala called to his brother, ''Come out!''', 'veda-app-ai-draft', true),
('ramayana-3-10-61', 'en', 'As he spoke so to his brahmin-killing brother, wise Agastya, best of sages, said with a laugh:', 'veda-app-ai-draft', true),
('ramayana-3-10-62', 'en', '''How can the demon come out? I have digested your brother in the form of a ram; he has gone to the abode of Yama.''', 'veda-app-ai-draft', true),
('ramayana-3-10-63', 'en', 'Hearing of his brother''s death, the night-roamer angrily began to attack the sage.', 'veda-app-ai-draft', true),
('ramayana-3-10-64', 'en', 'He rushed at that lord of brahmins, and was burned to death by the sage''s eye, blazing like fire.', 'veda-app-ai-draft', true),
('ramayana-3-10-65', 'en', 'This is the hermitage of his brother, adorned with ponds and woods, who did this hard deed out of compassion for brahmins.', 'veda-app-ai-draft', true),
('ramayana-3-10-66', 'en', 'While Rama was speaking thus with Lakshmana, the sun set and twilight came.', 'veda-app-ai-draft', true),
('ramayana-3-10-67', 'en', 'Having performed the evening twilight rite with his brother as prescribed, he entered the hermitage and they greeted the sage.', 'veda-app-ai-draft', true),
('ramayana-3-10-68', 'en', 'Well received by that sage, Rama stayed there one night, eating roots and fruits.', 'veda-app-ai-draft', true),
('ramayana-3-10-69', 'en', 'When that night had passed and the sun''s disc was clear, Rama took leave of Agastya''s brother.', 'veda-app-ai-draft', true),
('ramayana-3-10-70', 'en', '''I salute you, holy one; I spent the night happily. I take my leave; I go to see your elder brother, your guru.''', 'veda-app-ai-draft', true),
('ramayana-3-10-71', 'en', 'Told ''Go'', Rama went by the path described, looking at the forest.', 'veda-app-ai-draft', true),
('ramayana-3-10-72', 'en', 'He saw wild rice, jackfruit, palms, timisha, vanjula, dhava, ciribilva, madhuka, bilva and tinduka trees,', 'veda-app-ai-draft', true),
('ramayana-3-10-73', 'en', 'hundreds of forest trees in flower, wrapped in creepers with blossoming tips,', 'veda-app-ai-draft', true),
('ramayana-3-10-74', 'en', 'rubbed by elephants'' trunks, adorned with monkeys and echoing with hundreds of excited birds.', 'veda-app-ai-draft', true),
('ramayana-3-10-75', 'en', 'Then lotus-eyed Rama said to the hero Lakshmana, who was following close behind and increased his good fortune:', 'veda-app-ai-draft', true),
('ramayana-3-10-76', 'en', '''Since the trees have glossy leaves and the deer and birds are tame, the hermitage of the great seer of purified soul is not far.', 'veda-app-ai-draft', true),
('ramayana-3-10-77', 'en', 'The hermitage of the one known in the world as Agastya by his own deeds is seen, which takes away the fatigue of the weary.', 'veda-app-ai-draft', true),
('ramayana-3-10-78', 'en', 'Its forest is filled with much smoke, it is hung with strings of bark cloth, its herds of deer are calm and it echoes with many birds.', 'veda-app-ai-draft', true),
('ramayana-3-10-79', 'en', 'He of holy deeds, for the good of the worlds, forcefully restrained death and made the southern direction a place of refuge.', 'veda-app-ai-draft', true),
('ramayana-3-10-80', 'en', 'This is the hermitage of him by whose power the demons only look at this southern region in fear and do not enjoy it.', 'veda-app-ai-draft', true),
('ramayana-3-10-81', 'en', 'Ever since this holy one occupied this region, the night-roamers have been at peace and without hostility.', 'veda-app-ai-draft', true),
('ramayana-3-10-82', 'en', 'By the holy one''s name this southern region is famed in the three worlds as auspicious and unassailable by cruel beings.', 'veda-app-ai-draft', true),
('ramayana-3-10-83', 'en', 'The Vindhya, best of mountains, which kept trying to block the sun''s path, obeys his command and no longer grows.', 'veda-app-ai-draft', true),
('ramayana-3-10-84', 'en', 'This is the splendid hermitage of the long-lived Agastya, famous in the world for his deeds, frequented by tame deer.', 'veda-app-ai-draft', true),
('ramayana-3-10-85', 'en', 'This good man, honoured by the world, ever devoted to the welfare of the good, will bestow good fortune on us who have come.', 'veda-app-ai-draft', true),
('ramayana-3-10-86', 'en', 'Here I will serve the great sage Agastya and live out the rest of my forest exile, gentle one.', 'veda-app-ai-draft', true),
('ramayana-3-10-87', 'en', 'Here gods, gandharvas, perfected beings and great seers constantly attend on Agastya, who is restrained in diet.', 'veda-app-ai-draft', true),
('ramayana-3-10-88', 'en', 'No liar, cruel person, cheat, wicked person or one ruled by lust can live here; such is this sage.', 'veda-app-ai-draft', true),
('ramayana-3-10-89', 'en', 'Here gods, yakshas and serpents, with birds, live restrained in diet, wishing to worship dharma.', 'veda-app-ai-draft', true),
('ramayana-3-10-90', 'en', 'Here great perfected souls, the highest seers, left their bodies and went to heaven in new bodies, in sun-bright celestial chariots.', 'veda-app-ai-draft', true),
('ramayana-3-10-91', 'en', 'Here the gods, worshipped by good beings, grant the state of yakshas, immortality and various kingdoms.', 'veda-app-ai-draft', true),
('ramayana-3-10-92', 'en', 'We have reached the hermitage, Lakshmana; go in first and tell the sage that I have come with Sita.''', 'veda-app-ai-draft', true),
('ramayana-3-11-1', 'en', 'Lakshmana, Rama''s younger brother, entered the hermitage, approached a disciple of Agastya and said:', 'veda-app-ai-draft', true),
('ramayana-3-11-2', 'en', '''There is a king named Dasharatha; his eldest son, the mighty Rama, has come to see the sage with his wife Sita.', 'veda-app-ai-draft', true),
('ramayana-3-11-3', 'en', 'I am his younger brother named Lakshmana, devoted and loyal to him, if you have heard of me.', 'veda-app-ai-draft', true),
('ramayana-3-11-4', 'en', 'By our father''s command we have entered this very fierce forest. We all wish to see the holy one; please announce us.''', 'veda-app-ai-draft', true),
('ramayana-3-11-5', 'en', 'Hearing Lakshmana''s words, the ascetic said ''So be it'' and entered the fire sanctuary to announce him.', 'veda-app-ai-draft', true),
('ramayana-3-11-6', 'en', 'Entering, with joined palms he told the best of sages, unassailable by austerity, of Rama''s arrival:', 'veda-app-ai-draft', true),
('ramayana-3-11-7', 'en', '''These two sons of Dasharatha, Rama and Lakshmana, have entered the hermitage with Sita, Rama''s wife.', 'veda-app-ai-draft', true),
('ramayana-3-11-8', 'en', 'The two subduers of foes have come to see you and serve you. Please command what should be done next.''', 'veda-app-ai-draft', true),
('ramayana-3-11-9', 'en', 'Hearing from the disciple that Rama had come with Lakshmana and the noble Sita, he said:', 'veda-app-ai-draft', true),
('ramayana-3-11-10', 'en', '''Happily, Rama has at last come to see me today; I too have long wished in my heart for his coming.', 'veda-app-ai-draft', true),
('ramayana-3-11-11', 'en', 'Go, let Rama with his wife and Lakshmana be honoured and brought to me. Why has he not been brought in already?''', 'veda-app-ai-draft', true),
('ramayana-3-11-12', 'en', 'Thus addressed by the great-souled sage who knew dharma, the disciple saluted and said ''So be it'' with joined palms.', 'veda-app-ai-draft', true),
('ramayana-3-11-13', 'en', 'Then the disciple went out in haste and said to Lakshmana, ''Where is Rama? Let him come and enter himself to see the sage.''', 'veda-app-ai-draft', true),
('ramayana-3-11-14', 'en', 'Then Lakshmana went with the disciple to the hermitage gate and showed him Rama and Sita, daughter of Janaka.', 'veda-app-ai-draft', true),
('ramayana-3-11-15', 'en', 'The disciple, speaking Agastya''s courteous words, brought him in properly, honouring him well.', 'veda-app-ai-draft', true),
('ramayana-3-11-16', 'en', 'Then Rama entered with Sita and Lakshmana, looking around the hermitage full of calm deer.', 'veda-app-ai-draft', true),
('ramayana-3-11-17', 'en', 'There he saw the places of Brahma and of Agni, of Vishnu, of great Indra and of Vivasvat the sun,', 'veda-app-ai-draft', true),
('ramayana-3-11-18', 'en', 'the places of Soma, of Bhaga, of Kubera, of Dhatri and Vidhatri, and of Vayu.', 'veda-app-ai-draft', true),
('ramayana-3-11-19', 'en', 'Then the sage came out surrounded by disciples. Rama saw him in front of the sages, blazing with energy, and the hero said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-11-20', 'en', '''Lakshmana, the holy seer Agastya is coming out. From his nobility I know him to be a treasure of austerities.''', 'veda-app-ai-draft', true),
('ramayana-3-11-21', 'en', 'Saying this, mighty-armed Rama, delighted, took the feet of Agastya, bright as the sun.', 'veda-app-ai-draft', true),
('ramayana-3-11-22', 'en', 'Having saluted, the righteous Rama stood with joined palms, together with Sita and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-11-23', 'en', 'Receiving Rama and honouring him with a seat and water, he asked after his welfare and said, ''Be seated.''', 'veda-app-ai-draft', true),
('ramayana-3-11-24', 'en', 'Having offered into the fire, given the guest-water and honoured his guest, he gave them food according to forest-dweller''s dharma.', 'veda-app-ai-draft', true),
('ramayana-3-11-25', 'en', 'Then the best of sages, who knew dharma, sat down first and said to Rama, who was seated with joined palms and learned in dharma:', 'veda-app-ai-draft', true),
('ramayana-3-11-26', 'en', '''An ascetic who behaves otherwise, Rama, like a false witness, would eat his own flesh in the next world.', 'veda-app-ai-draft', true),
('ramayana-3-11-27', 'en', 'You are the king of the whole world, a great warrior who follows dharma, worthy of worship and honour; you have come as a dear guest.', 'veda-app-ai-draft', true),
('ramayana-3-11-28', 'en', 'Having said this and honoured Rama as he wished with fruits, roots, flowers and other things, he spoke again:', 'veda-app-ai-draft', true),
('ramayana-3-11-29', 'en', '''This is a great divine bow, adorned with gold and diamonds, belonging to Vishnu, tiger among men, made by Vishvakarma.', 'veda-app-ai-draft', true),
('ramayana-3-11-30', 'en', 'This unfailing best of arrows, bright as the sun, was given by Brahma; and these two quivers with inexhaustible arrows were given me by great Indra,', 'veda-app-ai-draft', true),
('ramayana-3-11-31', 'en', 'full of sharp arrows blazing like fire; and this sword adorned with gold in a silver scabbard.', 'veda-app-ai-draft', true),
('ramayana-3-11-32', 'en', 'With this bow, Rama, Vishnu once killed great demons in battle and brought back shining glory to the gods.', 'veda-app-ai-draft', true),
('ramayana-3-11-33', 'en', 'Accept the bow, the two quivers, the arrow and the sword for victory, giver of honour, as the thunderbolt-bearer accepts the thunderbolt.''', 'veda-app-ai-draft', true),
('ramayana-3-11-34', 'en', 'Having said this and given all those fine weapons to Rama, the mighty holy Agastya spoke again:', 'veda-app-ai-draft', true),
('ramayana-3-12-1', 'en', '''Rama, I am pleased, bless you; I am delighted, Lakshmana, that you have come with Sita to pay your respects to me.', 'veda-app-ai-draft', true),
('ramayana-3-12-2', 'en', 'The fatigue of the road troubles you, the great weariness; clearly Sita, Janaka''s daughter, is also tired.', 'veda-app-ai-draft', true),
('ramayana-3-12-3', 'en', 'She is delicate and was never touched by hardship; driven by love for her husband, she has come to a forest full of dangers.', 'veda-app-ai-draft', true),
('ramayana-3-12-4', 'en', 'Do whatever makes Sita happy here, Rama; she has done a hard thing in following you to the forest.', 'veda-app-ai-draft', true),
('ramayana-3-12-5', 'en', 'For this, Rama, has been the way of women since creation: they love a man in good times and leave him in bad.', 'veda-app-ai-draft', true),
('ramayana-3-12-6', 'en', 'Women share the fickleness of lightning, the sharpness of weapons, and the swiftness of Garuda and the wind.', 'veda-app-ai-draft', true),
('ramayana-3-12-7', 'en', 'But your wife is free of these faults; she is praiseworthy and an example, like the goddess Arundhati.', 'veda-app-ai-draft', true),
('ramayana-3-12-8', 'en', 'This place is graced wherever you live, Rama, with Lakshmana and Sita, subduer of foes.''', 'veda-app-ai-draft', true),
('ramayana-3-12-9', 'en', 'Thus addressed by the sage, Rama, with joined palms, spoke humbly to the seer, who blazed like fire:', 'veda-app-ai-draft', true),
('ramayana-3-12-10', 'en', '''I am blessed and favoured, since the best of sages, the giver of boons, is pleased with the qualities of me, my brother and my wife.', 'veda-app-ai-draft', true),
('ramayana-3-12-11', 'en', 'But show me a place with water and plenty of forest, where I may build a hermitage and live happily, devoted.''', 'veda-app-ai-draft', true),
('ramayana-3-12-12', 'en', 'Hearing Rama''s words, the best of sages, righteous and wise, thought for a moment and then spoke steady words:', 'veda-app-ai-draft', true),
('ramayana-3-12-13', 'en', '''Two yojanas from here, dear one, there is a splendid place famous as Panchavati, with plenty of roots, fruits and water, and many deer.', 'veda-app-ai-draft', true),
('ramayana-3-12-14', 'en', 'Go there, build a hermitage with Lakshmana, and live happily, keeping your father''s word as it was spoken.', 'veda-app-ai-draft', true),
('ramayana-3-12-15', 'en', 'For I know your whole story, sinless one, through the power of austerity and through my affection for Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-3-12-16', 'en', 'Through austerity I have also learned the wish in your heart, though you promised to live here with me in the hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-12-17', 'en', 'So I tell you: go to Panchavati. It is a lovely part of the forest, and Sita will be happy there.', 'veda-app-ai-draft', true),
('ramayana-3-12-18', 'en', 'That place is praiseworthy and not far, Rama, near the Godavari; Sita will enjoy it there.', 'veda-app-ai-draft', true),
('ramayana-3-12-19', 'en', 'It has plenty of roots and fruits and many kinds of birds; it is secluded, holy and lovely, mighty-armed one.', 'veda-app-ai-draft', true),
('ramayana-3-12-20', 'en', 'You with your wife are able to protect it; and living there, Rama, you will protect the ascetics.', 'veda-app-ai-draft', true),
('ramayana-3-12-21', 'en', 'That great madhuka forest can be seen, hero; go north of it, heading for a banyan tree.', 'veda-app-ai-draft', true),
('ramayana-3-12-22', 'en', 'Then, climbing to higher ground not far from a mountain, you will find the place known as Panchavati, whose woods are always in flower.''', 'veda-app-ai-draft', true),
('ramayana-3-12-23', 'en', 'Thus told by Agastya, Rama with Lakshmana honoured and took leave of the truthful seer.', 'veda-app-ai-draft', true),
('ramayana-3-12-24', 'en', 'With his permission and having bowed at his feet, the two went from that hermitage to Panchavati with Sita.', 'veda-app-ai-draft', true),
('ramayana-3-12-25', 'en', 'The two princes, bows in hand, quivers bound on, never fearful in battle, went with composure to Panchavati by the path the great seer had shown.', 'veda-app-ai-draft', true),
('ramayana-3-13-1', 'en', 'On the way to Panchavati, Rama came upon a huge vulture of terrible strength.', 'veda-app-ai-draft', true),
('ramayana-3-13-2', 'en', 'Seeing him in the forest, the noble Rama and Lakshmana thought the bird was a demon and asked, ''Who are you?''', 'veda-app-ai-draft', true),
('ramayana-3-13-3', 'en', 'Pleasing them, as it were, with a sweet, gentle voice, he said, ''Child, know me as a friend of your father.''', 'veda-app-ai-draft', true),
('ramayana-3-13-4', 'en', 'Realising he was his father''s friend, Rama honoured him and calmly asked his family and name.', 'veda-app-ai-draft', true),
('ramayana-3-13-5', 'en', 'Hearing Rama''s question, the bird told him of his family and himself, and of the origin of all creatures.', 'veda-app-ai-draft', true),
('ramayana-3-13-6', 'en', '''Listen, Rama, as I tell you from the beginning about all the Prajapatis, the lords of creatures, who lived in former times.', 'veda-app-ai-draft', true),
('ramayana-3-13-7', 'en', 'Kardama was the first of them, then Vikrita, Shesha, Samshraya and the mighty Bahuputra,', 'veda-app-ai-draft', true),
('ramayana-3-13-8', 'en', 'Sthanu, Marichi, Atri, the very strong Kratu, Pulastya, Angiras, Prachetas and Pulaha,', 'veda-app-ai-draft', true),
('ramayana-3-13-9', 'en', 'Daksha, Vivasvat, Arishtanemi, and the mighty Kashyapa, the last of them.', 'veda-app-ai-draft', true),
('ramayana-3-13-10', 'en', 'We have heard that the Prajapati Daksha had sixty famous daughters, Rama.', 'veda-app-ai-draft', true),
('ramayana-3-13-11', 'en', 'Kashyapa took eight of them as wives: Aditi, Diti, Danu, Kalaka,', 'veda-app-ai-draft', true),
('ramayana-3-13-12', 'en', 'Tamra, Krodhavasha, Manu and Anala. Pleased, Kashyapa then said to the maidens:', 'veda-app-ai-draft', true),
('ramayana-3-13-13', 'en', '"You will bear sons like me, rulers of the three worlds." Aditi, Diti, Danu', 'veda-app-ai-draft', true),
('ramayana-3-13-14', 'en', 'and Kalaka took this to heart, but the others were inattentive. From Aditi were born the thirty-three gods,', 'veda-app-ai-draft', true),
('ramayana-3-13-15', 'en', 'the Adityas, Vasus, Rudras and the two Ashvins. Diti bore famous sons, the Daityas.', 'veda-app-ai-draft', true),
('ramayana-3-13-16', 'en', 'This earth with its forests and oceans once belonged to them. Danu bore a son, Ashvagriva,', 'veda-app-ai-draft', true),
('ramayana-3-13-17', 'en', 'and Kalaka bore Naraka and Kalaka. Tamra bore Krauñchi, Bhasi, Shyeni, Dhritarashtri and Shuki,', 'veda-app-ai-draft', true),
('ramayana-3-13-18', 'en', 'these five world-famous daughters. Krauñchi bore owls; Bhasi bore bhasa birds;', 'veda-app-ai-draft', true),
('ramayana-3-13-19', 'en', 'Shyeni bore hawks and bright vultures; Dhritarashtri bore swans and geese of every kind,', 'veda-app-ai-draft', true),
('ramayana-3-13-20', 'en', 'and that lady also bore chakravakas, bless you. Shuki bore Nata, and Nata''s daughter was Vinata.', 'veda-app-ai-draft', true),
('ramayana-3-13-21', 'en', 'Krodhavasha bore ten daughters: Mrigi, Mrigamanda, Hari, Bhadramada,', 'veda-app-ai-draft', true),
('ramayana-3-13-22', 'en', 'Matangi, Shardulī, Shveta, Surabhi, Surasa endowed with all marks, and Kadru.', 'veda-app-ai-draft', true),
('ramayana-3-13-23', 'en', 'All deer are Mrigi''s offspring; bears, srimaras and yaks are Mrigamanda''s.', 'veda-app-ai-draft', true),
('ramayana-3-13-24', 'en', 'Bhadramada bore a daughter, Iravati, whose son is Airavata, the great elephant, guardian of the world.', 'veda-app-ai-draft', true),
('ramayana-3-13-25', 'en', 'Hari''s offspring are lions and monkeys; Shardulī bore golangula apes and tigers.', 'veda-app-ai-draft', true),
('ramayana-3-13-26', 'en', 'Matangi''s offspring are elephants; Shveta bore a son, the elephant of the quarters, Shvetaksha.', 'veda-app-ai-draft', true),
('ramayana-3-13-27', 'en', 'Then the goddess Surabhi bore two daughters, Rohini and the famous Gandharvi.', 'veda-app-ai-draft', true),
('ramayana-3-13-28', 'en', 'Rohini bore cows, Gandharvi bore horses; Surasa bore nagas and Kadru serpents.', 'veda-app-ai-draft', true),
('ramayana-3-13-29', 'en', 'Manu, wife of the great Kashyapa, bore human beings: brahmins, kshatriyas, vaishyas and shudras.', 'veda-app-ai-draft', true),
('ramayana-3-13-30', 'en', 'Brahmins were born from the mouth, kshatriyas from the chest, vaishyas from the thighs and shudras from the feet; so says the scripture.', 'veda-app-ai-draft', true),
('ramayana-3-13-31', 'en', 'Anala bore all trees with holy fruits. Vinata was Shuki''s granddaughter, and Kadru the sister of Surasa.', 'veda-app-ai-draft', true),
('ramayana-3-13-32', 'en', 'Kadru bore the thousand-headed serpent who holds up the earth; Vinata had two sons, Garuda and Aruna.', 'veda-app-ai-draft', true),
('ramayana-3-13-33', 'en', 'From Aruna I was born, and Sampati is my elder brother. Know me as Jatayu, son of Shyeni, subduer of foes.', 'veda-app-ai-draft', true),
('ramayana-3-13-34', 'en', 'If you wish, I will be your companion here, and I will guard Sita, dear one, when you and Lakshmana are away.''', 'veda-app-ai-draft', true),
('ramayana-3-13-35', 'en', 'Rama honoured Jatayu, embraced him joyfully and bowed, for he had heard many times of his father''s friendship with Jatayu.', 'veda-app-ai-draft', true),
('ramayana-3-13-36', 'en', 'Entrusting Sita to that very strong bird, he went with Lakshmana to Panchavati, eager to burn his enemies like fire burns moths.', 'veda-app-ai-draft', true),
('ramayana-3-14-1', 'en', 'Reaching Panchavati, full of many beasts and deer, Rama said to his radiant brother Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-14-2', 'en', '''We have come to the place the great seer described. This is Panchavati, gentle one, its woods in flower.', 'veda-app-ai-draft', true),
('ramayana-3-14-3', 'en', 'Look around in every direction, for you are skilled in the forest. In which spot would our hermitage be best?', 'veda-app-ai-draft', true),
('ramayana-3-14-4', 'en', 'Find a place where Sita, you and I will be happy, Lakshmana, with water close by,', 'veda-app-ai-draft', true),
('ramayana-3-14-5', 'en', 'where the forest and water are lovely, and firewood, flowers, kusha grass and water are near.''', 'veda-app-ai-draft', true),
('ramayana-3-14-6', 'en', 'Thus told by Rama, Lakshmana, with joined palms, said to him in Sita''s presence:', 'veda-app-ai-draft', true),
('ramayana-3-14-7', 'en', '''I am dependent on you, Rama, even if you live a hundred years. You choose a pleasing place yourself and tell me, "Build it here."''', 'veda-app-ai-draft', true),
('ramayana-3-14-8', 'en', 'Very pleased with Lakshmana''s words, the radiant one considered and chose a place with every good quality.', 'veda-app-ai-draft', true),
('ramayana-3-14-9', 'en', 'Stepping onto that lovely spot for the hermitage, Rama took Lakshmana''s hand in his and said:', 'veda-app-ai-draft', true),
('ramayana-3-14-10', 'en', '''This place is level and lovely, surrounded by flowering trees; build the hermitage here properly, gentle one.', 'veda-app-ai-draft', true),
('ramayana-3-14-11', 'en', 'Not far away you can see a lovely lotus pond, adorned with sun-bright, fragrant lotuses.', 'veda-app-ai-draft', true),
('ramayana-3-14-12', 'en', 'As the pure-souled sage Agastya described, here is the lovely Godavari, surrounded by flowering trees,', 'veda-app-ai-draft', true),
('ramayana-3-14-13', 'en', 'scattered with swans and ducks, graced by chakravakas, neither too near nor too far, and visited by herds of deer.', 'veda-app-ai-draft', true),
('ramayana-3-14-14', 'en', 'Lovely high hills with many caves are seen, gentle one, echoing with peacocks and covered in flowering trees.', 'veda-app-ai-draft', true),
('ramayana-3-14-15', 'en', 'Here and there they shine with gold, silver and copper ores, like elephants with fine painted decorations.', 'veda-app-ai-draft', true),
('ramayana-3-14-16', 'en', 'They are adorned with sala, palm, tamala, date, jackfruit, mango, wild rice, timisha and punnaga trees,', 'veda-app-ai-draft', true),
('ramayana-3-14-17', 'en', 'covered with mango, ashoka, tilaka, champaka and ketaka trees, with flowering shrubs and creepers,', 'veda-app-ai-draft', true),
('ramayana-3-14-18', 'en', 'with sandal, syandana, nipa, jackfruit, lakucha, dhava, ashvakarna, khadira, shami, kimshuka and patala.', 'veda-app-ai-draft', true),
('ramayana-3-14-19', 'en', 'This place is holy, pure and full of deer and birds. Here we will live, Lakshmana, together with this bird.''', 'veda-app-ai-draft', true),
('ramayana-3-14-20', 'en', 'Thus told by Rama, mighty Lakshmana, slayer of hostile heroes, quickly built a hermitage for his brother:', 'veda-app-ai-draft', true),
('ramayana-3-14-21', 'en', 'a spacious leaf hut of packed earth, with strong pillars, long bamboo poles for a ridge, very beautiful.', 'veda-app-ai-draft', true),
('ramayana-3-14-22', 'en', 'Then the glorious Lakshmana went to the Godavari, bathed, gathered lotuses and fruits and came back.', 'veda-app-ai-draft', true),
('ramayana-3-14-23', 'en', 'Then he made a flower offering and a rite of peace as prescribed, and showed Rama the finished hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-14-24', 'en', 'Seeing the lovely hermitage built, Rama with Sita felt great joy in the leaf hut.', 'veda-app-ai-draft', true),
('ramayana-3-14-25', 'en', 'Overjoyed, he embraced Lakshmana with both arms and spoke very tender and heartfelt words:', 'veda-app-ai-draft', true),
('ramayana-3-14-26', 'en', '''I am pleased with you; you have done a great deed, lord. For this I have given you this embrace as a gift.', 'veda-app-ai-draft', true),
('ramayana-3-14-27', 'en', 'With you, Lakshmana, a son who understands feelings, is grateful and knows dharma, my righteous father is not gone.''', 'veda-app-ai-draft', true),
('ramayana-3-14-28', 'en', 'Having spoken so to Lakshmana, Rama, increaser of fortune, lived happily in that fruitful place, self-controlled.', 'veda-app-ai-draft', true),
('ramayana-3-14-29', 'en', 'The righteous one lived there for some time, attended by Sita and Lakshmana, like an immortal in heaven.', 'veda-app-ai-draft', true),
('ramayana-3-15-1', 'en', 'While the great-souled Rama lived there happily, autumn ended and the pleasant winter season began.', 'veda-app-ai-draft', true),
('ramayana-3-15-2', 'en', 'One day, as night turned to dawn, Rama went to the lovely Godavari river to bathe.', 'veda-app-ai-draft', true),
('ramayana-3-15-3', 'en', 'Humbly carrying a water pot and following behind with Sita, his valiant brother Lakshmana said:', 'veda-app-ai-draft', true),
('ramayana-3-15-4', 'en', '''This is the season dear to you, sweet-spoken one, which adorns the auspicious year.', 'veda-app-ai-draft', true),
('ramayana-3-15-5', 'en', 'The world is harsh with frost, the earth garlanded with crops; the waters are unfit to enjoy, and fire is welcome.', 'veda-app-ai-draft', true),
('ramayana-3-15-6', 'en', 'Having worshipped the ancestors and gods with offerings of the new harvest, good people who have made the harvest offering in time are free of fault.', 'veda-app-ai-draft', true),
('ramayana-3-15-7', 'en', 'The countryside has all it wants and plenty of milk; kings eager for conquest travel on campaigns.', 'veda-app-ai-draft', true),
('ramayana-3-15-8', 'en', 'As the sun keeps firmly to the southern quarter, the northern quarter, like a woman without her forehead mark, does not shine.', 'veda-app-ai-draft', true),
('ramayana-3-15-9', 'en', 'Rich by nature in stores of snow and with the sun now far away, the Himalaya is clearly true to its name, the snowy mountain.', 'veda-app-ai-draft', true),
('ramayana-3-15-10', 'en', 'The days are very pleasant for walking and pleasant to the touch at midday; the sun is welcome, while shade and water are not.', 'veda-app-ai-draft', true),
('ramayana-3-15-11', 'en', 'The days now shine with a mild sun, mist, sharp cold and wind; the forests are empty and blasted by frost.', 'veda-app-ai-draft', true),
('ramayana-3-15-12', 'en', 'No one sleeps in the open now; the nights, ruled by the Pushya star, reddish with frost, cold and long, are passing.', 'veda-app-ai-draft', true),
('ramayana-3-15-13', 'en', 'The moon, its loveliness passed to the sun, its disc reddened by frost, does not shine, like a mirror clouded by breath.', 'veda-app-ai-draft', true),
('ramayana-3-15-14', 'en', 'Moonlight, dimmed by frost, does not shine even at full moon, like Sita darkened by the sun: seen, but not radiant.', 'veda-app-ai-draft', true),
('ramayana-3-15-15', 'en', 'The west wind, cool to the touch by nature and now pierced with snow, blows twice as cold at this time.', 'veda-app-ai-draft', true),
('ramayana-3-15-16', 'en', 'Forests of barley and wheat, covered with mist, shine at sunrise with calling cranes.', 'veda-app-ai-draft', true),
('ramayana-3-15-17', 'en', 'Rice plants shine like gold, slightly drooping, their heads full of grain and shaped like date flowers.', 'veda-app-ai-draft', true),
('ramayana-3-15-18', 'en', 'With its rays spreading through snow and mist, the sun, though high, looks like the moon.', 'veda-app-ai-draft', true),
('ramayana-3-15-19', 'en', 'In the forenoon its strength is not felt, at midday it is pleasant to the touch; the sunlight, slightly red and pale, shines on the earth.', 'veda-app-ai-draft', true),
('ramayana-3-15-20', 'en', 'With dew falling, the forest ground, its grass a little wet, shines in the early sunshine.', 'veda-app-ai-draft', true),
('ramayana-3-15-21', 'en', 'Bound in darkness of dew and wrapped in the gloom of mist, the rows of flowerless forest seem asleep.', 'veda-app-ai-draft', true),
('ramayana-3-15-22', 'en', 'The rivers now shine with water hidden by mist, cranes known only by their calls, and banks of frost-wet sand.', 'veda-app-ai-draft', true),
('ramayana-3-15-23', 'en', 'Because of the frost, the weak sun and the cold, even water on a mountain top usually tastes good.', 'veda-app-ai-draft', true),
('ramayana-3-15-24', 'en', 'The lotus ponds, blasted by frost, their leaves withered with age and their filaments and seed pods fallen, with only stalks left, do not shine.', 'veda-app-ai-draft', true),
('ramayana-3-15-25', 'en', 'In this season, tiger among men, the righteous Bharata, full of sorrow, practises austerity in the city out of devotion to you.', 'veda-app-ai-draft', true),
('ramayana-3-15-26', 'en', 'Giving up the kingdom, honour and many pleasures, he lives as an ascetic, eats sparingly and sleeps on the cold ground.', 'veda-app-ai-draft', true),
('ramayana-3-15-27', 'en', 'He too, surely, at this hour, ready for his bath, goes to the Sarayu river, always surrounded by his people.', 'veda-app-ai-draft', true),
('ramayana-3-15-28', 'en', 'Raised in great comfort, delicate and pained by the cold, how does he plunge into the Sarayu in the last hours of the night?', 'veda-app-ai-draft', true),
('ramayana-3-15-29', 'en', 'Lotus-eyed, dark, glorious, slim-waisted, great, knowing dharma, truthful, restrained by modesty, master of his senses,', 'veda-app-ai-draft', true),
('ramayana-3-15-30', 'en', 'sweet-spoken, gentle, long-armed, subduer of foes, he has given up every comfort and taken refuge wholly in his noble brother.', 'veda-app-ai-draft', true),
('ramayana-3-15-31', 'en', 'Your great-souled brother Bharata has won heaven, for he follows you in austerity even while you live in the forest.', 'veda-app-ai-draft', true),
('ramayana-3-15-32', 'en', 'The saying goes that men take after their mother, not their father; Bharata has proved it wrong.', 'veda-app-ai-draft', true),
('ramayana-3-15-33', 'en', 'How could Kaikeyi, whose husband is Dasharatha and whose son is the good Bharata, be so cruel-minded?''', 'veda-app-ai-draft', true),
('ramayana-3-15-34', 'en', 'As righteous Lakshmana spoke these words out of love, Rama, not bearing that blame of their mother, said:', 'veda-app-ai-draft', true),
('ramayana-3-15-35', 'en', '''Dear one, you must never speak ill of our middle mother. Speak only of Bharata, lord of the Ikshvakus.', 'veda-app-ai-draft', true),
('ramayana-3-15-36', 'en', 'Though my mind is set firm on forest life, burning with love for Bharata it becomes weak again.''', 'veda-app-ai-draft', true),
('ramayana-3-15-37', 'en', 'Lamenting thus, Rama reached the Godavari and bathed with Lakshmana and Sita.', 'veda-app-ai-draft', true),
('ramayana-3-15-38', 'en', 'Then they offered water to the ancestors and gods and, composed, praised the rising sun and the deities.', 'veda-app-ai-draft', true),
('ramayana-3-15-39', 'en', 'Having bathed, Rama shone with Sita and Lakshmana, like the lord Rudra with Parvati, daughter of the mountain, and Nandi after bathing.', 'veda-app-ai-draft', true),
('ramayana-3-16-1', 'en', 'Having bathed, Rama, Sita and Lakshmana went from the bank of the Godavari to their hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-16-2', 'en', 'Reaching the hermitage, Rama with Lakshmana performed the morning rites and went to the leaf hut.', 'veda-app-ai-draft', true),
('ramayana-3-16-3', 'en', 'Seated in the leaf hut with Sita, the mighty-armed Rama shone like the moon with the star Chitra, and talked of many things with his brother Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-16-4', 'en', 'As Rama sat absorbed in conversation, a demoness happened to come to that place.', 'veda-app-ai-draft', true),
('ramayana-3-16-5', 'en', 'She was Shurpanakha, sister of the ten-headed demon Ravana; approaching Rama, she saw that he was like a god.', 'veda-app-ai-draft', true),
('ramayana-3-16-6', 'en', 'lion-chested, mighty-armed, with eyes like lotus petals, gentle, of great spirit, bearing the marks of a king,', 'veda-app-ai-draft', true),
('ramayana-3-16-7', 'en', 'Seeing Rama, dark as a blue lotus, shining like the god of love, like Indra, the demoness was overcome by desire.', 'veda-app-ai-draft', true),
('ramayana-3-16-8', 'en', 'He was fair-faced, she ugly-faced; he slim-waisted, she pot-bellied; he large-eyed, she with deformed eyes; he with lovely hair, she with copper-coloured hair;', 'veda-app-ai-draft', true),
('ramayana-3-16-9', 'en', 'he pleasing, she misshapen; he sweet-voiced, she harsh-voiced; he young, she old and fearsome; he courteous, she crooked in speech;', 'veda-app-ai-draft', true),
('ramayana-3-16-10', 'en', 'he upright in conduct, she very ill-behaved; he lovely, she unpleasant to look at. Possessed by desire, the demoness said to Rama:', 'veda-app-ai-draft', true),
('ramayana-3-16-11', 'en', '''With matted hair, in ascetic''s form, with a wife and carrying bow and arrows, how have you come to this region haunted by demons?''', 'veda-app-ai-draft', true),
('ramayana-3-16-12', 'en', 'Thus questioned by the demoness Shurpanakha, Rama, in his straightforward way, began to tell her everything.', 'veda-app-ai-draft', true),
('ramayana-3-16-13', 'en', '''There was a king named Dasharatha, as valiant as the gods; I am his eldest son, known to people as Rama.', 'veda-app-ai-draft', true),
('ramayana-3-16-14', 'en', 'This is my younger brother Lakshmana, devoted to me, and this is my wife, known as Sita of Videha.', 'veda-app-ai-draft', true),
('ramayana-3-16-15', 'en', 'Bound by the command of my father the king and my mother, wanting dharma and for the sake of dharma, I have come to live here in the forest.', 'veda-app-ai-draft', true),
('ramayana-3-16-16', 'en', 'But I would like to know you. Tell me, who are you, whose are you, and why have you come here? Tell me truly.''', 'veda-app-ai-draft', true),
('ramayana-3-16-17', 'en', 'Hearing this, the demoness, tormented by desire, said: ''Listen, Rama, I will tell you the truth.', 'veda-app-ai-draft', true),
('ramayana-3-16-18', 'en', 'I am the demoness named Shurpanakha, able to take any form. I roam this forest alone, terrifying everyone.', 'veda-app-ai-draft', true),
('ramayana-3-16-19', 'en', 'My brother is the demon Ravana, lord of demons, and the mighty Kumbhakarna, who is always deep in sleep.', 'veda-app-ai-draft', true),
('ramayana-3-16-20', 'en', 'Vibhishana is righteous and does not act like a demon; and my brothers Khara and Dushana are famed for valour in battle.', 'veda-app-ai-draft', true),
('ramayana-3-16-21', 'en', 'I surpass them, Rama, and since first seeing you I have come to you with love as my husband, best of men. Be my husband for ever; what will you do with Sita?', 'veda-app-ai-draft', true),
('ramayana-3-16-22', 'en', 'She is misshapen and ugly, not fit for you. I alone am suited to you; look on me as your wife.', 'veda-app-ai-draft', true),
('ramayana-3-16-23', 'en', 'I will eat this ugly, unchaste, hideous, hollow-bellied human woman, together with your brother.', 'veda-app-ai-draft', true),
('ramayana-3-16-24', 'en', 'Then, beloved, you will roam the Dandaka with me, seeing mountain peaks and many forests.''', 'veda-app-ai-draft', true),
('ramayana-3-16-25', 'en', 'Thus addressed, Rama, skilled in speech, laughed at the woman with intoxicated eyes and began to say:', 'veda-app-ai-draft', true),
('ramayana-3-17-1', 'en', 'Rama, smiling, spoke at his pleasure in a smooth voice to Shurpanakha, caught in the noose of desire:', 'veda-app-ai-draft', true),
('ramayana-3-17-2', 'en', '''I am married, lady; this is my beloved wife. For women like you, having a co-wife would be very painful.', 'veda-app-ai-draft', true),
('ramayana-3-17-3', 'en', 'But this younger brother of mine is of good character, handsome, glorious, unmarried and valiant; his name is Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-17-4', 'en', 'He is young, handsome and wants a wife, never having had one; he will be a fitting husband for your beauty.', 'veda-app-ai-draft', true),
('ramayana-3-17-5', 'en', 'Take my brother as your husband, large-eyed one, without a rival wife, like sunlight on Mount Meru.''', 'veda-app-ai-draft', true),
('ramayana-3-17-6', 'en', 'Thus addressed by Rama, the demoness, blinded by desire, abruptly left Rama and said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-17-7', 'en', '''I, fair-skinned, am the wife suited to your beauty; with me you will roam all the Dandaka happily.''', 'veda-app-ai-draft', true),
('ramayana-3-17-8', 'en', 'Thus addressed by the demoness, Lakshmana, skilled in speech, smiled and said to Shurpanakha:', 'veda-app-ai-draft', true),
('ramayana-3-17-9', 'en', '''How can you want to be the slave-wife of a slave like me? I am dependent on my noble brother, lotus-coloured one.', 'veda-app-ai-draft', true),
('ramayana-3-17-10', 'en', 'Be the younger wife of my noble brother, large-eyed one, whose fortune is great; you will have your wish, joyful and fair.', 'veda-app-ai-draft', true),
('ramayana-3-17-11', 'en', 'He will leave this ugly, unchaste, hideous, hollow-bellied, old wife and turn to you alone.', 'veda-app-ai-draft', true),
('ramayana-3-17-12', 'en', 'For what wise man would give up this excellent beauty and set his heart on human women, lovely one?''', 'veda-app-ai-draft', true),
('ramayana-3-17-13', 'en', 'Told this by Lakshmana, the hideous, hollow-bellied demoness, not understanding jokes, took his words as true.', 'veda-app-ai-draft', true),
('ramayana-3-17-14', 'en', 'Blinded by desire, she said to Rama, the unassailable subduer of foes, seated with Sita in the leaf hut:', 'veda-app-ai-draft', true),
('ramayana-3-17-15', 'en', '''Clinging to this ugly, unchaste, hideous, hollow-bellied, old wife, you do not value me.', 'veda-app-ai-draft', true),
('ramayana-3-17-16', 'en', 'Today, while you watch, I will eat this human woman and live happily with you without a rival.''', 'veda-app-ai-draft', true),
('ramayana-3-17-17', 'en', 'Saying this, her eyes like burning torches, she rushed in fury at fawn-eyed Sita, like a great meteor at the star Rohini.', 'veda-app-ai-draft', true),
('ramayana-3-17-18', 'en', 'As she fell upon them like the noose of death, mighty Rama, angry, held her back and said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-17-19', 'en', '''One should never joke with cruel, ignoble beings, Lakshmana. Look at Sita, barely alive, gentle one.', 'veda-app-ai-draft', true),
('ramayana-3-17-20', 'en', 'You should disfigure this ugly, unchaste, wildly drunk, pot-bellied demoness, tiger among men.''', 'veda-app-ai-draft', true),
('ramayana-3-17-21', 'en', 'Thus told, angry Lakshmana drew his sword in front of Rama and cut off her ears and nose.', 'veda-app-ai-draft', true),
('ramayana-3-17-22', 'en', 'With ears and nose cut off, the terrible Shurpanakha screamed in a broken voice and ran back into the forest the way she had come.', 'veda-app-ai-draft', true),
('ramayana-3-17-23', 'en', 'Disfigured, terrible, drenched in blood, the demoness roared many kinds of roars, like a rain cloud in the monsoon.', 'veda-app-ai-draft', true),
('ramayana-3-17-24', 'en', 'Dripping blood, dreadful to see, she raised her arms and roared as she entered the great forest.', 'veda-app-ai-draft', true),
('ramayana-3-17-25', 'en', 'Then, disfigured, she went to Khara in Janasthana, surrounded by hosts of demons, her brother of fierce energy, and fell to the ground before him like a thunderbolt from the sky.', 'veda-app-ai-draft', true),
('ramayana-3-17-26', 'en', 'Then, faint with fear and confusion, bloodied, Khara''s sister told him everything: that Rama had come to the forest with his wife and Lakshmana, and how she was disfigured.', 'veda-app-ai-draft', true),
('ramayana-3-18-1', 'en', 'Seeing his sister fallen, disfigured and bloodied, the demon Khara, burning with anger, asked:', 'veda-app-ai-draft', true),
('ramayana-3-18-2', 'en', '''You are strong and brave, go where you will and take any form; who has brought you, who are like Death, to this state?', 'veda-app-ai-draft', true),
('ramayana-3-18-3', 'en', 'Among gods, gandharvas, beings and great seers, who is so mighty as to have disfigured you?', 'veda-app-ai-draft', true),
('ramayana-3-18-4', 'en', 'For I see no one in the world who would do me harm, except the thousand-eyed great Indra, chastiser of Paka.', 'veda-app-ai-draft', true),
('ramayana-3-18-5', 'en', 'Today with my life-ending arrows I will take his life, as a crane drinks milk mixed with water.', 'veda-app-ai-draft', true),
('ramayana-3-18-6', 'en', 'Whose foaming red blood will the earth drink, when I have killed him in battle, his vital parts cut by my arrows?', 'veda-app-ai-draft', true),
('ramayana-3-18-7', 'en', 'Whose body will the birds gather to tear and joyfully eat the flesh of, when I have killed him in battle?', 'veda-app-ai-draft', true),
('ramayana-3-18-8', 'en', 'Neither gods nor gandharvas nor pishachas nor demons will be able to save that wretch once I drag him into great battle.', 'veda-app-ai-draft', true),
('ramayana-3-18-9', 'en', 'Recover your senses slowly and tell me who that insolent one is who overpowered you in the forest.''', 'veda-app-ai-draft', true),
('ramayana-3-18-10', 'en', 'Hearing her brother''s words, especially as he was so angry, Shurpanakha said in tears:', 'veda-app-ai-draft', true),
('ramayana-3-18-11', 'en', '''Two young men, handsome, delicate, very strong, with large lotus eyes, wearing bark and black deerskin,', 'veda-app-ai-draft', true),
('ramayana-3-18-12', 'en', 'like kings of the gandharvas, bearing royal marks; whether gods or men, I cannot guess.', 'veda-app-ai-draft', true),
('ramayana-3-18-13', 'en', 'And between them I saw a young woman, beautiful, slender-waisted, adorned with every ornament.', 'veda-app-ai-draft', true),
('ramayana-3-18-14', 'en', 'Because of that woman, the two of them together brought me to this state, like a helpless and wicked woman.', 'veda-app-ai-draft', true),
('ramayana-3-18-15', 'en', 'When she, crooked in conduct, and those two are killed, I want to drink their foaming blood at the head of the battle.', 'veda-app-ai-draft', true),
('ramayana-3-18-16', 'en', 'This is my first wish, brother; fulfil it for me: let me drink her blood and theirs in battle.''', 'veda-app-ai-draft', true),
('ramayana-3-18-17', 'en', 'As she spoke, Khara in anger ordered fourteen mighty demons, like Death itself:', 'veda-app-ai-draft', true),
('ramayana-3-18-18', 'en', '''Two men, armed, wearing bark and black deerskin, have entered the dreadful Dandaka forest with a woman.', 'veda-app-ai-draft', true),
('ramayana-3-18-19', 'en', 'Kill the two and that wicked woman and come back; my sister will drink their blood.', 'veda-app-ai-draft', true),
('ramayana-3-18-20', 'en', 'This is my sister''s cherished wish, demons; go quickly and crush those two with your strength.''', 'veda-app-ai-draft', true),
('ramayana-3-18-21', 'en', 'So commanded, the fourteen demons went there with her like clouds driven by the wind.', 'veda-app-ai-draft', true),
('ramayana-3-19-1', 'en', 'Then terrible Shurpanakha came to Rama''s hermitage and pointed out to the demons the two brothers and Sita.', 'veda-app-ai-draft', true),
('ramayana-3-19-2', 'en', 'They saw mighty Rama sitting in the leaf hut with Sita and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-19-3', 'en', 'Seeing them and the demoness who had come, glorious Rama said to his radiant brother Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-19-4', 'en', '''Stay close to Sita for a moment, Lakshmana. I will kill these who have followed her here.''', 'veda-app-ai-draft', true),
('ramayana-3-19-5', 'en', 'Hearing these words of self-aware Rama, Lakshmana said ''So be it'' and honoured them.', 'veda-app-ai-draft', true),
('ramayana-3-19-6', 'en', 'The righteous Rama strung his great gold-adorned bow and said to the demons:', 'veda-app-ai-draft', true),
('ramayana-3-19-7', 'en', '''We are Rama and Lakshmana, brothers, sons of Dasharatha, who have entered the hard Dandaka forest with Sita.', 'veda-app-ai-draft', true),
('ramayana-3-19-8', 'en', 'We live on fruits and roots, self-controlled, ascetics following dharma, living in the Dandaka forest. Why do you attack us?', 'veda-app-ai-draft', true),
('ramayana-3-19-9', 'en', 'At the request of the sages I have come with my bow to kill you wicked ones who harm them in the great forest.', 'veda-app-ai-draft', true),
('ramayana-3-19-10', 'en', 'Stay where you are and be content; do not come closer. If you value your lives, turn back, night-roamers.''', 'veda-app-ai-draft', true),
('ramayana-3-19-11', 'en', 'Hearing his words, the fourteen brahmin-killing demons, spears in hand, spoke in great anger,', 'veda-app-ai-draft', true),
('ramayana-3-19-12', 'en', 'the dreadful ones with blood-red eyes, harsh in speech, to Rama, red-cornered of eye, sweet of speech, whose valour they had not seen:', 'veda-app-ai-draft', true),
('ramayana-3-19-13', 'en', '''Having roused the anger of our lord, the great Khara, you will lose your life today, killed by us in battle.', 'veda-app-ai-draft', true),
('ramayana-3-19-14', 'en', 'What power have you, one man against many at the head of battle, even to stand before us, let alone fight?', 'veda-app-ai-draft', true),
('ramayana-3-19-15', 'en', 'Struck by the clubs, spears and axes flung from our arms, you will lose your life, your strength and the bow gripped in your hand.''', 'veda-app-ai-draft', true),
('ramayana-3-19-16', 'en', 'Saying this, the fourteen furious demons rushed at Rama, swords and weapons raised, and hurled their spears at the invincible Rama.', 'veda-app-ai-draft', true),
('ramayana-3-19-17', 'en', 'Rama cut all fourteen spears apart with as many gold-adorned arrows.', 'veda-app-ai-draft', true),
('ramayana-3-19-18', 'en', 'Then the mighty one, enraged, took up fourteen iron arrows, sharpened on stone, bright as the sun.', 'veda-app-ai-draft', true),
('ramayana-3-19-19', 'en', 'Taking them, drawing his bow and aiming at the demons, Rama released the arrows like Indra hurling thunderbolts.', 'veda-app-ai-draft', true),
('ramayana-3-19-20', 'en', 'The gold-feathered, blazing arrows, adorned with gold, were as bright in the sky as great meteors.', 'veda-app-ai-draft', true),
('ramayana-3-19-21', 'en', 'Piercing the demons'' chests with force, bathed in blood, they fell to earth and sank into it with a sound like thunder.', 'veda-app-ai-draft', true),
('ramayana-3-19-22', 'en', 'Their hearts pierced, they fell to the ground like trees cut at the root, their bodies wet with blood, disfigured and lifeless.', 'veda-app-ai-draft', true),
('ramayana-3-19-23', 'en', 'Seeing them fallen, the demoness, faint with anger and terrified, let out a dreadful cry again.', 'veda-app-ai-draft', true),
('ramayana-3-19-24', 'en', 'Roaring loudly, Shurpanakha rushed back to Khara, her blood partly dried, and fell down again in distress, like a creeper oozing sap.', 'veda-app-ai-draft', true),
('ramayana-3-19-25', 'en', 'Having seen the demons felled in battle, Shurpanakha ran and told Khara, her brother, all about their slaughter.', 'veda-app-ai-draft', true),
('ramayana-3-20-1', 'en', 'Seeing Shurpanakha fallen again, Khara in anger spoke clearly to her, who had come for disaster:', 'veda-app-ai-draft', true),
('ramayana-3-20-2', 'en', '''I have just sent those brave, blood-drinking demons to do what you want; why are you crying again?', 'veda-app-ai-draft', true),
('ramayana-3-20-3', 'en', 'They are devoted, loyal and always good to me; they cannot be killed even when struck, and would never fail to obey me.', 'veda-app-ai-draft', true),
('ramayana-3-20-4', 'en', 'What is this? I want to hear why you writhe on the ground like a snake, crying "O protector!"', 'veda-app-ai-draft', true),
('ramayana-3-20-5', 'en', 'Why do you lament as if helpless when I, your protector, am here? Get up, get up, do not fear; give up this distress.''', 'veda-app-ai-draft', true),
('ramayana-3-20-6', 'en', 'Thus addressed and comforted by Khara, the unassailable one wiped her tearful eyes and said to her brother:', 'veda-app-ai-draft', true),
('ramayana-3-20-7', 'en', '''You sent those fourteen brave, fearsome demons to kill Rama and Lakshmana for my sake.', 'veda-app-ai-draft', true),
('ramayana-3-20-8', 'en', 'But, furious, with spears and axes in hand, they were all killed in battle by Rama with arrows that pierce the vitals.', 'veda-app-ai-draft', true),
('ramayana-3-20-9', 'en', 'Seeing those mighty ones fall to the ground in an instant, and Rama''s great feat, great terror came over me.', 'veda-app-ai-draft', true),
('ramayana-3-20-10', 'en', 'Frightened, alarmed and despondent, seeing danger everywhere, I have come to you again for refuge, night-roamer.', 'veda-app-ai-draft', true),
('ramayana-3-20-11', 'en', 'Why do you not save me, drowning in a vast ocean of grief infested with the crocodiles of despair and garlanded with waves of terror?', 'veda-app-ai-draft', true),
('ramayana-3-20-12', 'en', 'These flesh-eating demons who followed me have been killed on the ground by Rama''s sharp arrows.', 'veda-app-ai-draft', true),
('ramayana-3-20-13', 'en', 'If you have any pity for me and for those demons, if you have the power and spirit to face Rama, kill that thorn in the side of the demons who live in the Dandaka forest.', 'veda-app-ai-draft', true),
('ramayana-3-20-14', 'en', 'If you do not kill Rama, my enemy, today, I will shamelessly give up my life right in front of you.', 'veda-app-ai-draft', true),
('ramayana-3-20-15', 'en', 'I see clearly that you cannot stand face to face with Rama in battle when he holds his bow.', 'veda-app-ai-draft', true),
('ramayana-3-20-16', 'en', 'You think yourself a hero but you are not; your valour is falsely claimed, since you cannot kill two men, Rama and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-20-17', 'en', 'Leave Janasthana quickly with your kin. What place is there here for one without courage and of little strength?', 'veda-app-ai-draft', true),
('ramayana-3-20-18', 'en', 'Overpowered by Rama''s might, you will soon perish. For Rama, son of Dasharatha, is full of power, and so is his very valiant brother, who disfigured me.''', 'veda-app-ai-draft', true),
('ramayana-3-21-1', 'en', 'Thus provoked by Shurpanakha, brave Khara spoke still harsher words among the demons:', 'veda-app-ai-draft', true),
('ramayana-3-21-2', 'en', '''This boundless anger of mine, born of your humiliation, cannot be held back, like the rising salt sea.', 'veda-app-ai-draft', true),
('ramayana-3-21-3', 'en', 'I do not count Rama, a mere man whose life is spent, as valiant; by his own misdeeds he will lose his life today.', 'veda-app-ai-draft', true),
('ramayana-3-21-4', 'en', 'Stop these tears and give up this panic; I will send Rama and his brother to Yama''s abode.', 'veda-app-ai-draft', true),
('ramayana-3-21-5', 'en', 'Today, demoness, you will drink the hot red blood of Rama, struck down by my axe and dying on the ground.''', 'veda-app-ai-draft', true),
('ramayana-3-21-6', 'en', 'Delighted at the words from Khara''s mouth, she foolishly praised her brother, the best of demons, once more.', 'veda-app-ai-draft', true),
('ramayana-3-21-7', 'en', 'First insulted by her, then praised, Khara said to his general named Dushana:', 'veda-app-ai-draft', true),
('ramayana-3-21-8', 'en', '''Fourteen thousand demons who follow my will, of terrible speed, who never retreat in battle,', 'veda-app-ai-draft', true),
('ramayana-3-21-9', 'en', 'dark as blue clouds, dreadful, cruel in deeds, roaming the world like lions, strong and fierce,', 'veda-app-ai-draft', true),
('ramayana-3-21-10', 'en', 'proud as tigers, huge-mouthed and powerful, eager for battle; get them all ready, gentle one.', 'veda-app-ai-draft', true),
('ramayana-3-21-11', 'en', 'Bring my chariot quickly, gentle one, and bows, arrows of many colours, swords and many kinds of sharp spears.', 'veda-app-ai-draft', true),
('ramayana-3-21-12', 'en', 'I, skilled in war, wish to go out in front of the great descendants of Pulastya to kill the insolent Rama.''', 'veda-app-ai-draft', true),
('ramayana-3-21-13', 'en', 'As he spoke, Dushana reported that the great sun-coloured chariot was ready, yoked to fine dappled horses.', 'veda-app-ai-draft', true),
('ramayana-3-21-14', 'en', 'It was like a peak of Meru, adorned with refined gold, with golden wheels, roomy, its pole of beryl,', 'veda-app-ai-draft', true),
('ramayana-3-21-15', 'en', 'covered with golden fish, flowers, trees, mountains, moons and suns, auspicious flocks of birds and stars,', 'veda-app-ai-draft', true),
('ramayana-3-21-16', 'en', 'fitted with banners and swords, adorned with little bells and yoked to fine horses; Khara mounted it in his rage.', 'veda-app-ai-draft', true),
('ramayana-3-21-17', 'en', 'Seeing him in his chariot, the demons of terrible valour stood around him and mighty Dushana.', 'veda-app-ai-draft', true),
('ramayana-3-21-18', 'en', 'Seeing all the demons, great archers with dreadful shields, weapons and banners, Khara in his chariot said, ''March!''', 'veda-app-ai-draft', true),
('ramayana-3-21-19', 'en', 'Then that demon army, with dreadful shields, weapons and banners, went out of Janasthana with a great roar and great speed.', 'veda-app-ai-draft', true),
('ramayana-3-21-20', 'en', 'with hammers, axes, spears, sharp hatchets, swords, discuses and gleaming javelins in hand,', 'veda-app-ai-draft', true),
('ramayana-3-21-21', 'en', 'with lances, dreadful clubs, huge bows, maces, swords, pestles and thunderbolts, terrible to see,', 'veda-app-ai-draft', true),
('ramayana-3-21-22', 'en', 'fourteen thousand very dreadful demons who followed Khara''s will marched out of Janasthana.', 'veda-app-ai-draft', true),
('ramayana-3-21-23', 'en', 'Seeing the demons of terrible valour rushing forward, Khara''s chariot went a little after them.', 'veda-app-ai-draft', true),
('ramayana-3-21-24', 'en', 'Then, knowing Khara''s wish, the charioteer urged on the dappled horses adorned with refined gold.', 'veda-app-ai-draft', true),
('ramayana-3-21-25', 'en', 'Driven fast, the chariot of Khara, killer of foes, filled every direction with its sound.', 'veda-app-ai-draft', true),
('ramayana-3-21-26', 'en', 'Khara, his fury growing, harsh-voiced, hurrying like Death to kill his enemy, roared and urged on his charioteer again, like a mighty cloud raining stones.', 'veda-app-ai-draft', true),
('ramayana-3-22-1', 'en', 'As that dreadful army set out, a huge, roaring, donkey-grey cloud rained down inauspicious, blood-coloured water.', 'veda-app-ai-draft', true),
('ramayana-3-22-2', 'en', 'His very swift horses, yoked to the chariot, fell by chance on a level, flower-strewn royal road.', 'veda-app-ai-draft', true),
('ramayana-3-22-3', 'en', 'A dark halo edged with blood, like a wheel of fire, encircled the sun.', 'veda-app-ai-draft', true),
('ramayana-3-22-4', 'en', 'Then a huge, very dreadful vulture came and perched on the tall gold-staffed banner.', 'veda-app-ai-draft', true),
('ramayana-3-22-5', 'en', 'Near Janasthana, flesh-eating beasts and birds with harsh voices gathered and made many discordant sounds.', 'veda-app-ai-draft', true),
('ramayana-3-22-6', 'en', 'Inauspicious jackals, ill-omened for those who set out, howled terribly with great cries toward the blazing quarter.', 'veda-app-ai-draft', true),
('ramayana-3-22-7', 'en', 'Dreadful clouds like broken mountains, carrying blood for water, made the sky no sky.', 'veda-app-ai-draft', true),
('ramayana-3-22-8', 'en', 'A dreadful, hair-raising darkness arose; neither the main nor the intermediate directions could be clearly seen.', 'veda-app-ai-draft', true),
('ramayana-3-22-9', 'en', 'The sky shone the colour of fresh blood though it was not twilight; dreadful beasts and birds cried out facing Khara.', 'veda-app-ai-draft', true),
('ramayana-3-22-10', 'en', 'Jackals, always bringing ill in battle, dreadful to see, howled facing the army with flame-spitting mouths.', 'veda-app-ai-draft', true),
('ramayana-3-22-11', 'en', 'A headless trunk like an iron bar was seen near the sun, and the great planet Rahu seized the sun out of season.', 'veda-app-ai-draft', true),
('ramayana-3-22-12', 'en', 'The wind blew fiercely, the sun lost its light, and stars bright as fireflies rose though it was not night.', 'veda-app-ai-draft', true),
('ramayana-3-22-13', 'en', 'At that moment, the lotus ponds, their fish and birds hidden, lost their flowers, and the trees were left without flowers or fruit.', 'veda-app-ai-draft', true),
('ramayana-3-22-14', 'en', 'Dust as red as clouds rose without wind, and myna birds cried ''vichi kuchi'' there.', 'veda-app-ai-draft', true),
('ramayana-3-22-15', 'en', 'Meteors fell with a roar, dreadful to see, and the earth shook with its mountains and forests.', 'veda-app-ai-draft', true),
('ramayana-3-22-16', 'en', 'As wise Khara roared in his chariot, his left arm trembled and his voice faltered.', 'veda-app-ai-draft', true),
('ramayana-3-22-17', 'en', 'His eyes filled with tears as he looked about, and pain arose in his forehead; yet in his delusion he did not turn back.', 'veda-app-ai-draft', true),
('ramayana-3-22-18', 'en', 'Seeing these great, hair-raising portents arise, Khara laughed and said to all the demons:', 'veda-app-ai-draft', true),
('ramayana-3-22-19', 'en', '''I do not care about all these dreadful portents, by my strength, as a strong man does not care about the weak.', 'veda-app-ai-draft', true),
('ramayana-3-22-20', 'en', 'I could bring down even the stars from the sky with sharp arrows; in my anger I could make Death himself die.', 'veda-app-ai-draft', true),
('ramayana-3-22-21', 'en', 'I will not return without killing Rama, proud of his strength, and his brother Lakshmana with sharp arrows.', 'veda-app-ai-draft', true),
('ramayana-3-22-22', 'en', 'Let my sister have her wish and drink their blood, she for whose sake this reversal has come to Rama and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-22-23', 'en', 'I have never before met defeat in battle; you have seen this yourselves, I do not lie.', 'veda-app-ai-draft', true),
('ramayana-3-22-24', 'en', 'In my anger I could kill even the king of gods riding his rutting Airavata, thunderbolt in hand; how much more two men.''', 'veda-app-ai-draft', true),
('ramayana-3-22-25', 'en', 'Hearing the demon''s roar, the great army, bound in the noose of death, felt boundless joy.', 'veda-app-ai-draft', true),
('ramayana-3-22-26', 'en', 'Great souls gathered, eager to watch the battle: sages, gods, gandharvas, perfected beings and celestial singers.', 'veda-app-ai-draft', true),
('ramayana-3-22-27', 'en', 'Gathered together, those of holy deeds said to one another: ''May there be welfare for cows and brahmins and those honoured in the worlds.', 'veda-app-ai-draft', true),
('ramayana-3-22-28', 'en', 'May Rama defeat the night-roaming descendants of Pulastya in battle, as the discus-holder Vishnu defeated all the chief asuras.''', 'veda-app-ai-draft', true),
('ramayana-3-22-29', 'en', 'Saying this and much else, the great seers watched the army of those demons whose lives were spent.', 'veda-app-ai-draft', true),
('ramayana-3-22-30', 'en', 'Khara rushed out ahead of the army in his chariot; seeing him, the demons rushed out again too.', 'veda-app-ai-draft', true),
('ramayana-3-22-31', 'en', 'Shyenagamin, Prithugriva, Yajnashatru, Vihangama, Durjaya, Karaviraksha, Parusha, Kalakarmuka,', 'veda-app-ai-draft', true),
('ramayana-3-22-32', 'en', 'Meghamali, Mahamali, Sarpasya and Rudhirashana: these twelve mighty ones went on around Khara.', 'veda-app-ai-draft', true),
('ramayana-3-22-33', 'en', 'Mahakapala, Sthulaksha, Pramathin and Trishiras, these four army leaders, followed behind Dushana.', 'veda-app-ai-draft', true),
('ramayana-3-22-34', 'en', 'That dreadful army of demon heroes, of terrible speed and eager for battle, suddenly fell upon the two princes, like planets upon the moon and sun.', 'veda-app-ai-draft', true),
('ramayana-3-23-1', 'en', 'As Khara of fierce valour went toward the hermitage, Rama with his brother saw those same portents.', 'veda-app-ai-draft', true),
('ramayana-3-23-2', 'en', 'Seeing those very dreadful, hair-raising portents, harmful to creatures, he said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-23-3', 'en', '''See, mighty-armed one, these great portents that destroy all beings have arisen to destroy all the demons.', 'veda-app-ai-draft', true),
('ramayana-3-23-4', 'en', 'These harsh, donkey-grey clouds move about the sky, pouring streams of blood with harsh sounds.', 'veda-app-ai-draft', true),
('ramayana-3-23-5', 'en', 'All my arrows, eager for battle, are smoking, and my gold-backed bows are quivering, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-23-6', 'en', 'From the way the forest birds are crying, danger lies ahead of us and our lives are at stake.', 'veda-app-ai-draft', true),
('ramayana-3-23-7', 'en', 'There will be a very great battle, no doubt; my arm, throbbing again and again, tells me so.', 'veda-app-ai-draft', true),
('ramayana-3-23-8', 'en', 'But close at hand, hero, victory for us and defeat for the enemy are shown, for your face looks bright and clear.', 'veda-app-ai-draft', true),
('ramayana-3-23-9', 'en', 'For those ready for battle whose face is dull, Lakshmana, life is coming to its end.', 'veda-app-ai-draft', true),
('ramayana-3-23-10', 'en', 'A wise man who wants good and suspects danger should make provision for what has not yet come.', 'veda-app-ai-draft', true),
('ramayana-3-23-11', 'en', 'So take Sita and, with bow and arrows in hand, go to the cave in the mountain, hard to reach and thick with trees.', 'veda-app-ai-draft', true),
('ramayana-3-23-12', 'en', 'I do not want you to oppose these words. I bind you by my feet: go quickly, child.''', 'veda-app-ai-draft', true),
('ramayana-3-23-13', 'en', 'Thus told by Rama, Lakshmana took his bow and arrows and went with Sita to the hard-to-reach cave.', 'veda-app-ai-draft', true),
('ramayana-3-23-14', 'en', 'When Lakshmana had entered the cave with Sita, Rama said, ''Good, it is done,'' and put on his armour.', 'veda-app-ai-draft', true),
('ramayana-3-23-15', 'en', 'Adorned with that fire-bright armour, Rama looked like a smokeless fire risen in darkness.', 'veda-app-ai-draft', true),
('ramayana-3-23-16', 'en', 'Raising his great bow and taking his arrows, the valiant one stood there, filling the directions with the twang of his bowstring.', 'veda-app-ai-draft', true),
('ramayana-3-23-17', 'en', 'Then the gods, gandharvas, perfected beings, celestial singers and guhyakas, greatly alarmed, said to one another:', 'veda-app-ai-draft', true),
('ramayana-3-23-18', 'en', '''Fourteen thousand demons of terrible deeds, and the righteous Rama alone; how will this battle go?''', 'veda-app-ai-draft', true),
('ramayana-3-23-19', 'en', 'Then the army of demons, with deep roars and dreadful armour, weapons and banners, appeared on every side.', 'veda-app-ai-draft', true),
('ramayana-3-23-20', 'en', 'They roared like lions, bellowed at one another, twanged their bows and yawned again and again.', 'veda-app-ai-draft', true),
('ramayana-3-23-21', 'en', 'The tumultuous sound of their shouting and beating of drums filled that forest.', 'veda-app-ai-draft', true),
('ramayana-3-23-22', 'en', 'Frightened by that sound, the wild animals of the forest fled to where it was silent and did not look back.', 'veda-app-ai-draft', true),
('ramayana-3-23-23', 'en', 'That army, of great speed, armed with many weapons, deep as the ocean, approached Rama.', 'veda-app-ai-draft', true),
('ramayana-3-23-24', 'en', 'Rama too, skilled in battle, looking everywhere, saw Khara''s army ready for battle.', 'veda-app-ai-draft', true),
('ramayana-3-23-25', 'en', 'Drawing his dreadful bow and taking arrows from his quiver, he summoned fierce anger to kill all the demons.', 'veda-app-ai-draft', true),
('ramayana-3-23-26', 'en', 'Enraged, blazing like the fire at the end of an age, he became hard to look at; seeing him filled with power, the forest deities trembled.', 'veda-app-ai-draft', true),
('ramayana-3-23-27', 'en', 'The form of angry Rama then looked like that of Shiva, bearer of Pinaka, ready to destroy Daksha''s sacrifice.', 'veda-app-ai-draft', true),
('ramayana-3-24-1', 'en', 'Arriving at the hermitage with his vanguard, Khara saw Rama, angry, killer of foes, gripping his bow.', 'veda-app-ai-draft', true),
('ramayana-3-24-2', 'en', 'Seeing him, Khara raised his strung bow with its harsh twang and told his charioteer, ''Drive toward Rama.''', 'veda-app-ai-draft', true),
('ramayana-3-24-3', 'en', 'At Khara''s command the charioteer urged the horses toward where mighty-armed Rama stood alone, shaking his bow.', 'veda-app-ai-draft', true),
('ramayana-3-24-4', 'en', 'Seeing him rush out, all the night-roamers, his ministers, surrounded him with great roars.', 'veda-app-ai-draft', true),
('ramayana-3-24-5', 'en', 'Khara, in his chariot among those demons, looked like Mars risen among the stars.', 'veda-app-ai-draft', true),
('ramayana-3-24-6', 'en', 'Then all the angry night-roamers showered the invincible Rama, of terrible bow, with many kinds of weapons.', 'veda-app-ai-draft', true),
('ramayana-3-24-7', 'en', 'With iron hammers, spears, lances, swords and axes, the furious demons struck at Rama in battle.', 'veda-app-ai-draft', true),
('ramayana-3-24-8', 'en', 'Those huge, loud, mighty ones, like clouds, rushed at Rama in battle, eager to kill him.', 'veda-app-ai-draft', true),
('ramayana-3-24-9', 'en', 'Those hordes of demons rained showers of arrows on Rama, as great clouds pour streams on the king of mountains.', 'veda-app-ai-draft', true),
('ramayana-3-24-10', 'en', 'Surrounded by those dreadful hosts of demons, Rama was like Mahadeva surrounded by his attendants on holy days.', 'veda-app-ai-draft', true),
('ramayana-3-24-11', 'en', 'Rama received the weapons the demons released with his arrows, as the ocean receives the floods of rivers.', 'veda-app-ai-draft', true),
('ramayana-3-24-12', 'en', 'Though his body was wounded by those dreadful weapons, Rama did not waver, like a great mountain struck by many blazing thunderbolts.', 'veda-app-ai-draft', true),
('ramayana-3-24-13', 'en', 'Pierced and smeared with blood all over his body, Rama looked like the sun covered by evening clouds.', 'veda-app-ai-draft', true),
('ramayana-3-24-14', 'en', 'Gods, gandharvas, perfected beings and great seers grieved, seeing him alone surrounded by many thousands.', 'veda-app-ai-draft', true),
('ramayana-3-24-15', 'en', 'Then Rama, enraged, bent his bow into a circle and released sharp arrows by the hundred and thousand.', 'veda-app-ai-draft', true),
('ramayana-3-24-16', 'en', 'Hard to ward off, hard to bear, like the nooses of Death in battle, the heron-feathered, straight-flying arrows Rama released with ease.', 'veda-app-ai-draft', true),
('ramayana-3-24-17', 'en', 'Released by Rama with ease into the enemy army, those arrows took the demons'' lives like nooses made by Time.', 'veda-app-ai-draft', true),
('ramayana-3-24-18', 'en', 'Piercing the demons'' bodies, bathed in blood, those arrows shone in the sky with the brilliance of blazing fire.', 'veda-app-ai-draft', true),
('ramayana-3-24-19', 'en', 'Countless, very fierce arrows that took the demons'' lives flew from the circle of Rama''s bow.', 'veda-app-ai-draft', true),
('ramayana-3-24-20', 'en', 'With them he cut bows, banner tops, armour and heads, many arms with their ornaments, and thighs like elephants'' trunks.', 'veda-app-ai-draft', true),
('ramayana-3-24-21', 'en', 'Then, pierced by tubular arrows, iron arrows, sharp-pointed and barbed arrows, the night-roamers let out terrible cries of pain.', 'veda-app-ai-draft', true),
('ramayana-3-24-22', 'en', 'That army, struck by Rama''s sharp, vital-piercing arrows, found no relief, like a dry forest in a fire.', 'veda-app-ai-draft', true),
('ramayana-3-24-23', 'en', 'Some brave night-roamers of terrible strength, in great anger, hurled spears, swords and axes at Rama.', 'veda-app-ai-draft', true),
('ramayana-3-24-24', 'en', 'Warding off those weapons with arrows, mighty-armed Rama took their lives in battle and cut off their heads.', 'veda-app-ai-draft', true),
('ramayana-3-24-25', 'en', 'Those night-roamers who were left, despondent and wounded by arrows, ran to Khara for refuge.', 'veda-app-ai-draft', true),
('ramayana-3-24-26', 'en', 'Gathering them all again and encouraging them, Dushana rushed at Rama in anger, like Death at Rudra.', 'veda-app-ai-draft', true),
('ramayana-3-24-27', 'en', 'Turning back, all of them, fearless with Dushana''s support, rushed at Rama again, armed with sala trees, palms and rocks.', 'veda-app-ai-draft', true),
('ramayana-3-24-28', 'en', 'Then there was a wondrous, tumultuous, hair-raising and very dreadful battle between Rama and those demons.', 'veda-app-ai-draft', true),
('ramayana-3-25-1', 'en', 'The righteous Rama received that great, deadly shower of trees and rocks with his sharp arrows.', 'veda-app-ai-draft', true),
('ramayana-3-25-2', 'en', 'Receiving that shower like a bull with eyes closed, Rama summoned the greatest anger to kill all the demons.', 'veda-app-ai-draft', true),
('ramayana-3-25-3', 'en', 'Then, filled with anger and blazing as if with power, he covered the army and Dushana on every side with arrows.', 'veda-app-ai-draft', true),
('ramayana-3-25-4', 'en', 'Then the general Dushana, destroyer of foes, in anger seized a hair-raising iron club like a mountain peak,', 'veda-app-ai-draft', true),
('ramayana-3-25-5', 'en', 'bound with gold bands, crusher of the armies of the gods, studded with sharp iron spikes and smeared with the fat of enemies,', 'veda-app-ai-draft', true),
('ramayana-3-25-6', 'en', 'as hard as a thunderbolt, able to break the gates of enemy cities, like a great serpent; seizing that club, the cruel night-roamer Dushana fell upon Rama.', 'veda-app-ai-draft', true),
('ramayana-3-25-7', 'en', 'As Dushana fell upon him, Rama cut off both his arms, with their ornaments, with two arrows.', 'veda-app-ai-draft', true),
('ramayana-3-25-8', 'en', 'His huge club fell from his severed hands at the front of the battle, like Indra''s banner.', 'veda-app-ai-draft', true),
('ramayana-3-25-9', 'en', 'With his arms cut away, Dushana fell to the ground, like a proud great elephant whose tusks are broken.', 'veda-app-ai-draft', true),
('ramayana-3-25-10', 'en', 'Seeing Dushana fallen and slain in battle, all beings honoured Rama, crying ''Well done, well done!''', 'veda-app-ai-draft', true),
('ramayana-3-25-11', 'en', 'Meanwhile three angry army leaders, bound by the noose of death, rushed at Rama together: Mahakapala, Sthulaksha and mighty Pramathin.', 'veda-app-ai-draft', true),
('ramayana-3-25-12', 'en', 'The demon Mahakapala raised a huge spear, Sthulaksha seized a battle axe, and Pramathin an axe.', 'veda-app-ai-draft', true),
('ramayana-3-25-13', 'en', 'Seeing them rush at him, Rama received them with sharp-pointed arrows as if receiving guests who had arrived.', 'veda-app-ai-draft', true),
('ramayana-3-25-14', 'en', 'Rama cut off Mahakapala''s head and crushed Pramathin with countless floods of arrows.', 'veda-app-ai-draft', true),
('ramayana-3-25-15', 'en', 'He filled Sthulaksha''s eyes with sharp arrows; slain, he fell to the ground like a great tree with its branches.', 'veda-app-ai-draft', true),
('ramayana-3-25-16', 'en', 'Then the radiant one, with fire-bright arrows adorned with gold and diamonds, attacked what was left of the army.', 'veda-app-ai-draft', true),
('ramayana-3-25-17', 'en', 'Those gold-feathered arrows, like smoking fires, killed the demons as thunderbolts strike great trees.', 'veda-app-ai-draft', true),
('ramayana-3-25-18', 'en', 'At the head of the battle Rama killed a hundred demons with a hundred barbed arrows, and a thousand with a thousand.', 'veda-app-ai-draft', true),
('ramayana-3-25-19', 'en', 'Their armour and ornaments broken, their bows cut and shattered, the night-roamers fell to the ground smeared with blood.', 'veda-app-ai-draft', true),
('ramayana-3-25-20', 'en', 'The whole earth was strewn with them, fallen in battle with loosened hair and bathed in blood, like a great altar strewn with kusha grass.', 'veda-app-ai-draft', true),
('ramayana-3-25-21', 'en', 'In a moment the very dreadful forest, full of slain demons, looked like hell, a mire of flesh and blood.', 'veda-app-ai-draft', true),
('ramayana-3-25-22', 'en', 'Fourteen thousand demons of terrible deeds were killed by Rama alone, a man on foot.', 'veda-app-ai-draft', true),
('ramayana-3-25-23', 'en', 'Of that whole army only the great warrior Khara and the demon Trishiras were left, facing Rama, slayer of foes.', 'veda-app-ai-draft', true),
('ramayana-3-25-24', 'en', 'Seeing that army of terrible strength killed in the great battle by the mightier Rama, Khara drove at him in his great chariot, like Indra with thunderbolt raised.', 'veda-app-ai-draft', true),
('ramayana-3-26-1', 'en', 'As Khara went toward Rama, the army commander, the demon named Trishiras, came up and said:', 'veda-app-ai-draft', true),
('ramayana-3-26-2', 'en', '''Send me, valiant one, and turn back from this rashness. See mighty-armed Rama brought down in battle.', 'veda-app-ai-draft', true),
('ramayana-3-26-3', 'en', 'I promise you truly, and touch my weapon in oath, that I will kill Rama, who deserves death from all demons.', 'veda-app-ai-draft', true),
('ramayana-3-26-4', 'en', 'Either I will be his death in battle or he mine. Hold back your eagerness for a moment and be a witness.', 'veda-app-ai-draft', true),
('ramayana-3-26-5', 'en', 'Either you will go joyfully to Janasthana when Rama is dead, or, if I am killed, you will go to fight Rama.''', 'veda-app-ai-draft', true),
('ramayana-3-26-6', 'en', 'Persuaded by Trishiras out of desire for death, Khara gave him leave: ''Go and fight.'' He went toward Rama.', 'veda-app-ai-draft', true),
('ramayana-3-26-7', 'en', 'Trishiras, in his shining chariot drawn by horses, rushed at Rama in battle like a three-peaked mountain.', 'veda-app-ai-draft', true),
('ramayana-3-26-8', 'en', 'Releasing streams of arrows like a great cloud, he let out a roar like a drum wet with water.', 'veda-app-ai-draft', true),
('ramayana-3-26-9', 'en', 'Seeing the demon Trishiras coming, Rama received him with his bow, shaking sharp arrows.', 'veda-app-ai-draft', true),
('ramayana-3-26-10', 'en', 'That tumultuous battle between Rama and Trishiras, both very strong, was like one between a lion and an elephant.', 'veda-app-ai-draft', true),
('ramayana-3-26-11', 'en', 'Then, struck on the forehead by Trishiras with three arrows, Rama, angry and impatient, said fiercely:', 'veda-app-ai-draft', true),
('ramayana-3-26-12', 'en', '''Oh, such is the strength of this demon hero, by whose arrows I am wounded on the forehead as if by flowers! Now receive my arrows released from the bowstring.''', 'veda-app-ai-draft', true),
('ramayana-3-26-13', 'en', 'Saying this, he angrily struck Trishiras in the chest with fourteen arrows like venomous snakes.', 'veda-app-ai-draft', true),
('ramayana-3-26-14', 'en', 'With four smooth-jointed arrows the radiant one brought down his four horses.', 'veda-app-ai-draft', true),
('ramayana-3-26-15', 'en', 'With eight arrows he brought down the charioteer in the chariot, and with one arrow Rama cut down his tall banner.', 'veda-app-ai-draft', true),
('ramayana-3-26-16', 'en', 'As the night-roamer leapt from his ruined chariot, Rama pierced him in the heart with arrows and he went numb.', 'veda-app-ai-draft', true),
('ramayana-3-26-17', 'en', 'Then, with three swift arrows, Rama of boundless spirit, angry, brought down the demon''s three heads.', 'veda-app-ai-draft', true),
('ramayana-3-26-18', 'en', 'Spitting blood, crushed by Rama''s arrows, the night-roamer fell to the ground after his own fallen heads.', 'veda-app-ai-draft', true),
('ramayana-3-26-19', 'en', 'Then the remaining demons who depended on Khara broke and ran, not standing their ground, like deer frightened by a tiger.', 'veda-app-ai-draft', true),
('ramayana-3-26-20', 'en', 'Seeing them run, Khara, enraged, turned them back himself and rushed at Rama, as Rahu at the moon.', 'veda-app-ai-draft', true),
('ramayana-3-27-1', 'en', 'Seeing Dushana and Trishiras slain in battle, and seeing Rama''s valour, even Khara felt fear.', 'veda-app-ai-draft', true),
('ramayana-3-27-2', 'en', 'He saw the mighty, irresistible demon army, and Dushana and Trishiras too, killed by Rama alone.', 'veda-app-ai-draft', true),
('ramayana-3-27-3', 'en', 'Seeing that army mostly destroyed, the demon Khara, dejected, approached Rama as Namuchi approached Indra.', 'veda-app-ai-draft', true),
('ramayana-3-27-4', 'en', 'Drawing his strong bow, Khara shot blood-drinking iron arrows at Rama like angry venomous snakes.', 'veda-app-ai-draft', true),
('ramayana-3-27-5', 'en', 'Twanging his bowstring again and again and showing his skill in weapons, Khara moved about the battlefield in his chariot, shooting arrows.', 'veda-app-ai-draft', true),
('ramayana-3-27-6', 'en', 'The great warrior filled all the directions and intermediate directions with arrows; seeing this, Rama too took up his great bow.', 'veda-app-ai-draft', true),
('ramayana-3-27-7', 'en', 'With unbearable arrows like sparking fires, he left no gap in the sky, like the rain god with his showers.', 'veda-app-ai-draft', true),
('ramayana-3-27-8', 'en', 'With sharp arrows released by Khara and Rama, the whole sky became no sky, filled with arrows on every side.', 'veda-app-ai-draft', true),
('ramayana-3-27-9', 'en', 'Covered by a net of arrows, the sun did not shine, as the two fought, each eager to kill the other.', 'veda-app-ai-draft', true),
('ramayana-3-27-10', 'en', 'Then he struck Rama in battle with tubular, iron, sharp-pointed and barbed arrows, like goads on a great elephant.', 'veda-app-ai-draft', true),
('ramayana-3-27-11', 'en', 'All beings saw the demon standing in his chariot, bow in hand, like Death with a noose in his hand.', 'veda-app-ai-draft', true),
('ramayana-3-27-12', 'en', 'Seeing him, valiant as a lion and moving like a lion, Rama was not alarmed, as a lion is not alarmed by a small deer.', 'veda-app-ai-draft', true),
('ramayana-3-27-13', 'en', 'Then Khara in his great sun-bright chariot came at Rama in battle, like a moth to fire.', 'veda-app-ai-draft', true),
('ramayana-3-27-14', 'en', 'Then Khara, showing his speed of hand, cut great Rama''s bow, with its arrow, at the grip.', 'veda-app-ai-draft', true),
('ramayana-3-27-15', 'en', 'Then, angry, he took seven more arrows bright as Indra''s thunderbolt and struck Rama''s armour in battle.', 'veda-app-ai-draft', true),
('ramayana-3-27-16', 'en', 'Struck by Khara''s well-jointed arrows, the armour of sun-bright Rama fell to the ground.', 'veda-app-ai-draft', true),
('ramayana-3-27-17', 'en', 'Pierced by arrows all over his body, angry Rama shone in battle like a smokeless blazing fire.', 'veda-app-ai-draft', true),
('ramayana-3-27-18', 'en', 'Then Rama, destroyer of enemies, strung another great bow with a deep roar, to put an end to his foe.', 'veda-app-ai-draft', true),
('ramayana-3-27-19', 'en', 'Raising that excellent, very great bow of Vishnu, given to him by the great seer, he rushed at Khara.', 'veda-app-ai-draft', true),
('ramayana-3-27-20', 'en', 'Then, enraged, Rama cut down Khara''s banner in battle with gold-feathered, smooth-jointed arrows.', 'veda-app-ai-draft', true),
('ramayana-3-27-21', 'en', 'That handsome golden banner, cut into many pieces, fell to the earth like the sun at the gods'' command.', 'veda-app-ai-draft', true),
('ramayana-3-27-22', 'en', 'Angry Khara, who knew the vital points, struck Rama in the body and heart with four arrows, as one strikes an elephant with javelins.', 'veda-app-ai-draft', true),
('ramayana-3-27-23', 'en', 'Pierced by many arrows from Khara''s bow, his limbs drenched with blood, Rama became very angry.', 'veda-app-ai-draft', true),
('ramayana-3-27-24', 'en', 'The best of bowmen, the great archer, took his bow in that great battle and shot six well-aimed arrows.', 'veda-app-ai-draft', true),
('ramayana-3-27-25', 'en', 'He struck him with one arrow in the head, two in the arms, and three crescent-headed ones in the chest.', 'veda-app-ai-draft', true),
('ramayana-3-27-26', 'en', 'Then the mighty one, angry and eager to kill the demon, took thirteen sun-bright iron arrows sharpened on stone.', 'veda-app-ai-draft', true),
('ramayana-3-27-27', 'en', 'With one he broke the yoke, with four the four horses, and with the sixth he cut off the head of Khara''s charioteer in battle.', 'veda-app-ai-draft', true),
('ramayana-3-27-28', 'en', 'With three the mighty one broke the triple bamboo pole, with two the axle; with the twelfth arrow Rama, as if laughing, cut Khara''s bow and arrow, and with the thirteenth, like a thunderbolt, Indra-like Rama pierced Khara in battle.', 'veda-app-ai-draft', true),
('ramayana-3-27-29', 'en', 'With his bow broken, chariotless, his horses and charioteer killed, Khara leapt down and stood on the ground, mace in hand.', 'veda-app-ai-draft', true),
('ramayana-3-27-30', 'en', 'Gathered together, the gods and great seers, standing in their celestial chariots, joyfully honoured that feat of the great warrior Rama with joined palms.', 'veda-app-ai-draft', true),
('ramayana-3-28-1', 'en', 'To Khara, standing chariotless with mace in hand, mighty Rama spoke harsh words, gently at first:', 'veda-app-ai-draft', true),
('ramayana-3-28-2', 'en', '''Standing in your great army crowded with elephants, horses and chariots, you have done very cruel deeds, hated by all the world.', 'veda-app-ai-draft', true),
('ramayana-3-28-3', 'en', 'One who frightens beings, who is cruel and does evil deeds, does not last, even if he is lord of the three worlds.', 'veda-app-ai-draft', true),
('ramayana-3-28-4', 'en', 'Everyone kills one who does deeds against the world, night-roamer, as they kill a vicious snake that comes near.', 'veda-app-ai-draft', true),
('ramayana-3-28-5', 'en', 'He who does evil out of greed or desire without realising it sees his end when he falls, like the brahmani lizard from hail.', 'veda-app-ai-draft', true),
('ramayana-3-28-6', 'en', 'What fruit will you gain, demon, by killing the noble ascetics who follow dharma living in the Dandaka forest?', 'veda-app-ai-draft', true),
('ramayana-3-28-7', 'en', 'Cruel doers of evil, hated by the world, do not last long even when they gain power, like trees with rotten roots.', 'veda-app-ai-draft', true),
('ramayana-3-28-8', 'en', 'The doer surely reaps the dreadful fruit of his evil deed when the time comes, as a tree bears its seasonal flower.', 'veda-app-ai-draft', true),
('ramayana-3-28-9', 'en', 'Before long in this world the fruit of evil deeds is reaped, night-roamer, as with poisoned food that has been eaten.', 'veda-app-ai-draft', true),
('ramayana-3-28-10', 'en', 'I, a king, have come to take the lives of those who do dreadful evil and wish harm on the world, night-roamer.', 'veda-app-ai-draft', true),
('ramayana-3-28-11', 'en', 'Today my gold-adorned arrows will tear through you and fall, as snakes into an anthill.', 'veda-app-ai-draft', true),
('ramayana-3-28-12', 'en', 'Today, killed in battle with your army, you will follow those followers of dharma whom you devoured in the Dandaka forest.', 'veda-app-ai-draft', true),
('ramayana-3-28-13', 'en', 'Today let the great seers whom you harmed before, standing in their celestial chariots, see you killed by arrows and in hell.', 'veda-app-ai-draft', true),
('ramayana-3-28-14', 'en', 'Strike as you please, make your effort, lowest of your clan; today I will bring down your head like a palm fruit.''', 'veda-app-ai-draft', true),
('ramayana-3-28-15', 'en', 'Thus addressed by Rama, Khara, angry, his eyes red, laughed and answered Rama, faint with anger:', 'veda-app-ai-draft', true),
('ramayana-3-28-16', 'en', '''Having killed ordinary demons in battle, son of Dasharatha, how can you praise yourself, who deserve no praise?', 'veda-app-ai-draft', true),
('ramayana-3-28-17', 'en', 'Truly valiant and strong men, bulls among men, say nothing, proud in their own power.', 'veda-app-ai-draft', true),
('ramayana-3-28-18', 'en', 'It is common, undisciplined men, disgraces to the warrior class, who boast pointlessly, Rama, as you do.', 'veda-app-ai-draft', true),
('ramayana-3-28-19', 'en', 'What hero in battle, naming his family, praises himself unprompted when the time of death has come?', 'veda-app-ai-draft', true),
('ramayana-3-28-20', 'en', 'Your boasting has shown your lightness completely, like a kusha fire made to look like gold.', 'veda-app-ai-draft', true),
('ramayana-3-28-21', 'en', 'Do you not see me standing here with my mace, unshakeable like a mountain studded with minerals?', 'veda-app-ai-draft', true),
('ramayana-3-28-22', 'en', 'With mace in hand I am enough to take your life in battle, like Death with noose in hand for the three worlds.', 'veda-app-ai-draft', true),
('ramayana-3-28-23', 'en', 'Much could be said to you, but I will not say it; the sun may set and then there would be a break in the fight.', 'veda-app-ai-draft', true),
('ramayana-3-28-24', 'en', 'You have killed fourteen thousand demons; by your death today I will wipe away their tears.''', 'veda-app-ai-draft', true),
('ramayana-3-28-25', 'en', 'Saying this, in great anger Khara hurled at Rama that mace with its fine bands, blazing like lightning.', 'veda-app-ai-draft', true),
('ramayana-3-28-26', 'en', 'Released from Khara''s arm, that huge blazing mace reduced trees and shrubs to ashes as it came near.', 'veda-app-ai-draft', true),
('ramayana-3-28-27', 'en', 'As that blazing mace, like the noose of death, came through the air, Rama cut it into many pieces with arrows.', 'veda-app-ai-draft', true),
('ramayana-3-28-28', 'en', 'Broken and shattered by arrows, it fell to the ground like a she-serpent brought down by spells and herbs.', 'veda-app-ai-draft', true),
('ramayana-3-29-1', 'en', 'Having broken the mace with arrows, Rama, lover of dharma, smiling, spoke these angry words to Khara:', 'veda-app-ai-draft', true),
('ramayana-3-29-2', 'en', '''You have shown the whole of your strength, lowest of demons; you are weaker than I, and your roaring was in vain.', 'veda-app-ai-draft', true),
('ramayana-3-29-3', 'en', 'This mace, shattered by my arrows and fallen to the ground, has destroyed the confidence of you who are bold only in words.', 'veda-app-ai-draft', true),
('ramayana-3-29-4', 'en', 'What you said, that you would wipe away the tears of the slain demons, that too is a false statement.', 'veda-app-ai-draft', true),
('ramayana-3-29-5', 'en', 'I will take the life of this low, mean-natured, false demon, as Garuda took the nectar of immortality.', 'veda-app-ai-draft', true),
('ramayana-3-29-6', 'en', 'Today the earth will drink your blood, adorned with froth and bubbles, when your throat is split and you are torn by my arrows.', 'veda-app-ai-draft', true),
('ramayana-3-29-7', 'en', 'With every limb covered in dust and both arms flung out, you will sleep embracing the earth like a rare woman.', 'veda-app-ai-draft', true),
('ramayana-3-29-8', 'en', 'When you, disgrace of the demons, lie in your long sleep, this Dandaka forest will be a refuge for those without refuge.', 'veda-app-ai-draft', true),
('ramayana-3-29-9', 'en', 'When Janasthana, your stronghold, is destroyed by my arrows, the sages will roam the forest everywhere without fear.', 'veda-app-ai-draft', true),
('ramayana-3-29-10', 'en', 'Today the demonesses, who brought fear to others, will flee in fear, their kin slain, their faces wet with tears, wretched.', 'veda-app-ai-draft', true),
('ramayana-3-29-11', 'en', 'Today your wives, of fitting family, whose husband is such as you, will know the taste of grief, night-roamer.', 'veda-app-ai-draft', true),
('ramayana-3-29-12', 'en', 'Cruel-natured, mean-souled, ever a thorn to brahmins, because of you the sages pour their offerings into the fire in fear.''', 'veda-app-ai-draft', true),
('ramayana-3-29-13', 'en', 'As Rama spoke so angrily in battle, Khara, in fury, scolded him in an even harsher voice:', 'veda-app-ai-draft', true),
('ramayana-3-29-14', 'en', '''You are truly very arrogant, and fearless even amid danger; in the power of death, you do not know what should and should not be said.', 'veda-app-ai-draft', true),
('ramayana-3-29-15', 'en', 'For men caught in the noose of Time do not know what should and should not be done, their six senses gone.''', 'veda-app-ai-draft', true),
('ramayana-3-29-16', 'en', 'Having said this to Rama and knitting his brows, the night-roamer saw a great sala tree not far off.', 'veda-app-ai-draft', true),
('ramayana-3-29-17', 'en', 'Looking all around for a weapon in battle, he uprooted it, biting his lip.', 'veda-app-ai-draft', true),
('ramayana-3-29-18', 'en', 'Lifting it in both arms and roaring, the mighty one hurled it at Rama, saying, ''You are dead!''', 'veda-app-ai-draft', true),
('ramayana-3-29-19', 'en', 'Cutting it down with floods of arrows as it came, mighty Rama summoned fierce anger to kill Khara in battle.', 'veda-app-ai-draft', true),
('ramayana-3-29-20', 'en', 'Then Rama, sweating, his eye-corners red with anger, pierced Khara in battle with a thousand arrows.', 'veda-app-ai-draft', true),
('ramayana-3-29-21', 'en', 'From the gaps between the arrows much frothy blood flowed, like streams of water from a mountain spring.', 'veda-app-ai-draft', true),
('ramayana-3-29-22', 'en', 'Made unsteady by Rama''s arrows in battle, Khara, maddened by the smell of blood, rushed at him quickly.', 'veda-app-ai-draft', true),
('ramayana-3-29-23', 'en', 'As he rushed furiously, bathed in blood, the skilled warrior Rama stepped back a little, step by step, quick in his moves.', 'veda-app-ai-draft', true),
('ramayana-3-29-24', 'en', 'Then, to kill Khara in battle, Rama took a fire-like arrow, like a second rod of Brahma.', 'veda-app-ai-draft', true),
('ramayana-3-29-25', 'en', 'The righteous one fitted that arrow, given by wise Indra, king of the gods, and released it at Khara.', 'veda-app-ai-draft', true),
('ramayana-3-29-26', 'en', 'That great arrow, released by Rama as he raised his bow, with a sound like a thunderclap, struck Khara in the chest.', 'veda-app-ai-draft', true),
('ramayana-3-29-27', 'en', 'Khara fell to the ground, burning in the fire of the arrow, like Andhaka burned up by Rudra in the White Forest.', 'veda-app-ai-draft', true),
('ramayana-3-29-28', 'en', 'Slain, Khara fell, like Vritra by the thunderbolt, Namuchi by foam, or Bala struck by Indra''s lightning.', 'veda-app-ai-draft', true),
('ramayana-3-29-29', 'en', 'Then all the royal sages and great seers gathered and, honouring Rama joyfully, said:', 'veda-app-ai-draft', true),
('ramayana-3-29-30', 'en', '''For this purpose mighty Indra, chastiser of Paka, destroyer of cities, came to Sharabhanga''s holy hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-29-31', 'en', 'You were brought to this region by the great seers through a plan, to kill these cruel demons of evil deeds.', 'veda-app-ai-draft', true),
('ramayana-3-29-32', 'en', 'You have done this work for us, son of Dasharatha; the great seers will practise dharma happily in the Dandaka.''', 'veda-app-ai-draft', true),
('ramayana-3-29-33', 'en', 'Meanwhile the hero Lakshmana came out with Sita from the mountain stronghold and happily entered the hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-29-34', 'en', 'Then victorious Rama, honoured by the great seers, entered the hermitage, saluted by Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-29-35', 'en', 'Seeing her husband, slayer of enemies, bringer of happiness to the great seers, Sita was overjoyed and embraced him.', 'veda-app-ai-draft', true),
('ramayana-3-30-1', 'en', 'Then Shurpanakha, seeing the fourteen thousand demons of terrible deeds killed by Rama alone,', 'veda-app-ai-draft', true),
('ramayana-3-30-2', 'en', 'and seeing Dushana, Khara and Trishiras slain in battle, roared again a great roar like a thundercloud.', 'veda-app-ai-draft', true),
('ramayana-3-30-3', 'en', 'Seeing the deed done by Rama, very hard for others to do, she went, greatly alarmed, to Lanka, ruled by Ravana.', 'veda-app-ai-draft', true),
('ramayana-3-30-4', 'en', 'She saw Ravana, blazing with energy, on top of his palace, surrounded by ministers like Indra by the Maruts.', 'veda-app-ai-draft', true),
('ramayana-3-30-5', 'en', 'He sat on a golden, sun-bright high throne, like a great fire blazing on a golden altar,', 'veda-app-ai-draft', true),
('ramayana-3-30-6', 'en', 'invincible in battle by gods, gandharvas, beings and great seers, brave, like Death with open jaws,', 'veda-app-ai-draft', true),
('ramayana-3-30-7', 'en', 'bearing wounds from thunderbolts in the wars of gods and demons, his chest scarred by the tusks of Airavata,', 'veda-app-ai-draft', true),
('ramayana-3-30-8', 'en', 'with twenty arms and ten heads, splendid in his attire, broad-chested, heroic, marked with the signs of royalty,', 'veda-app-ai-draft', true),
('ramayana-3-30-9', 'en', 'shining like smooth beryl, with earrings of refined gold, fine arms, white teeth, a huge mouth, like a mountain,', 'veda-app-ai-draft', true),
('ramayana-3-30-10', 'en', 'his body struck hundreds of times by blows of Vishnu''s discus in wars with the gods, and by all the gods'' weapons,', 'veda-app-ai-draft', true),
('ramayana-3-30-11', 'en', 'one who stirs the unshakeable oceans, swift in action, hurler of mountain peaks and crusher of gods,', 'veda-app-ai-draft', true),
('ramayana-3-30-12', 'en', 'destroyer of dharma, violator of others'' wives, user of all divine weapons, always obstructing sacrifices.', 'veda-app-ai-draft', true),
('ramayana-3-30-13', 'en', 'He had gone to the city of Bhogavati, defeated Vasuki and carried off Takshaka''s beloved wife.', 'veda-app-ai-draft', true),
('ramayana-3-30-14', 'en', 'He had gone to Mount Kailasa, defeated Kubera and taken his chariot Pushpaka, which goes wherever one wishes.', 'veda-app-ai-draft', true),
('ramayana-3-30-15', 'en', 'In anger the mighty one destroyed the divine Chaitraratha forest, the lotus lake and the Nandana garden, the gardens of the gods.', 'veda-app-ai-draft', true),
('ramayana-3-30-16', 'en', 'Like a mountain peak, he blocked with his arms the noble moon and sun as they rose.', 'veda-app-ai-draft', true),
('ramayana-3-30-17', 'en', 'Steadfast, he once practised austerity in the great forest for ten thousand years and offered his heads to Brahma, the self-born.', 'veda-app-ai-draft', true),
('ramayana-3-30-18', 'en', 'He had no fear in battle of death from gods, danavas, gandharvas, pishachas, birds or serpents, except from a human.', 'veda-app-ai-draft', true),
('ramayana-3-30-19', 'en', 'The mighty one destroys the holy soma, praised with mantras by brahmins at sacrifices, in the vessels for offerings.', 'veda-app-ai-draft', true),
('ramayana-3-30-20', 'en', 'Ravana, destroyer of completed sacrifices, cruel, brahmin-killer, wicked in conduct, harsh, pitiless, intent on harming creatures, terror of all beings and all worlds:', 'veda-app-ai-draft', true),
('ramayana-3-30-21', 'en', 'the demoness saw her cruel, mighty brother, in divine clothes and ornaments, adorned with divine garlands, the lord of demons, delight of the line of Pulastya.', 'veda-app-ai-draft', true),
('ramayana-3-30-22', 'en', 'Faint with fear and confusion, showing herself disfigured by the great Rama, Shurpanakha, who used to move without fear, spoke very harsh words to him with his large blazing eyes.', 'veda-app-ai-draft', true),
('ramayana-3-31-1', 'en', 'Then wretched and angry Shurpanakha spoke harsh words in the midst of the ministers to Ravana, who made the world cry:', 'veda-app-ai-draft', true),
('ramayana-3-31-2', 'en', '''Careless in pleasures, doing as you please, unrestrained, you do not notice the terrible danger that has arisen and must be noticed.', 'veda-app-ai-draft', true),
('ramayana-3-31-3', 'en', 'People do not respect a king attached to vulgar pleasures, ruled by desire and greedy, any more than the fire of a cremation ground.', 'veda-app-ai-draft', true),
('ramayana-3-31-4', 'en', 'A king who does not himself attend to his duties at the right time perishes along with his kingdom and those duties.', 'veda-app-ai-draft', true),
('ramayana-3-31-5', 'en', 'People avoid from afar a king who has no spies, is hard to see and is not his own master, as elephants avoid river mud.', 'veda-app-ai-draft', true),
('ramayana-3-31-6', 'en', 'Kings who do not protect their realm and are not their own masters do not shine with prosperity, like mountains sunk in the sea.', 'veda-app-ai-draft', true),
('ramayana-3-31-7', 'en', 'Having made enemies of self-possessed gods, gandharvas and danavas, how will you remain king, fickle and without spies?', 'veda-app-ai-draft', true),
('ramayana-3-31-8', 'en', 'Kings whose spies, treasury and policy are not under their control are equal to common people, best of victors.', 'veda-app-ai-draft', true),
('ramayana-3-31-9', 'en', 'Because kings see all distant matters through spies, they are called ''long-sighted''.', 'veda-app-ai-draft', true),
('ramayana-3-31-10', 'en', 'I think you have no spies and are surrounded by common ministers, since you do not know your own people in Janasthana have been killed.', 'veda-app-ai-draft', true),
('ramayana-3-31-11', 'en', 'Fourteen thousand demons of terrible deeds have been killed by Rama alone, and Khara with Dushana.', 'veda-app-ai-draft', true),
('ramayana-3-31-12', 'en', 'Rama, tireless in deeds, has given the sages freedom from fear, made the Dandaka safe and attacked Janasthana.', 'veda-app-ai-draft', true),
('ramayana-3-31-13', 'en', 'But you, Ravana, are greedy, careless and dependent on others, since you do not notice the danger that has arisen in your own realm.', 'veda-app-ai-draft', true),
('ramayana-3-31-14', 'en', 'When a king is harsh, gives little, is careless, proud and deceitful, no creature runs to help him in disaster.', 'veda-app-ai-draft', true),
('ramayana-3-31-15', 'en', 'Even his own people destroy, in disaster, a king who is too proud, unapproachable, self-important and angry.', 'veda-app-ai-draft', true),
('ramayana-3-31-16', 'en', 'He who does not do his duties and does not fear what should be feared will soon fall from his kingdom, wretched, worth no more than grass.', 'veda-app-ai-draft', true),
('ramayana-3-31-17', 'en', 'Dry wood, clods of earth and even dust have their use, but kings fallen from their place have none.', 'veda-app-ai-draft', true),
('ramayana-3-31-18', 'en', 'Like a worn garment or a crushed garland, a king fallen from his kingdom, however able, is of no use.', 'veda-app-ai-draft', true),
('ramayana-3-31-19', 'en', 'But the king who is watchful, all-knowing, master of his senses, grateful and righteous lasts long.', 'veda-app-ai-draft', true),
('ramayana-3-31-20', 'en', 'Though asleep with his eyes, he is awake with the eye of policy; and whose anger and favour are open is honoured by people.', 'veda-app-ai-draft', true),
('ramayana-3-31-21', 'en', 'But you, Ravana, foolish-minded, lack these qualities, since your spies did not tell you of the great slaughter of the demons.', 'veda-app-ai-draft', true),
('ramayana-3-31-22', 'en', 'Despising others, attached to pleasures, not understanding the proper divisions of place and time, with a mind unfit to judge good and bad, your kingdom ruined, you will soon perish.''', 'veda-app-ai-draft', true),
('ramayana-3-31-23', 'en', 'Thus Ravana, lord of night-roamers, filled with wealth, pride and strength, considered with his mind the faults she had listed, and thought for a long time.', 'veda-app-ai-draft', true),
('ramayana-3-32-1', 'en', 'Then Ravana, angry, questioned angry Shurpanakha, who had spoken harsh words, in the midst of his ministers:', 'veda-app-ai-draft', true),
('ramayana-3-32-2', 'en', '''Who is Rama? What is his strength, his form, his valour? Why has he entered the very hard Dandaka forest?', 'veda-app-ai-draft', true),
('ramayana-3-32-3', 'en', 'What is Rama''s weapon, by which the demons were killed, and Khara slain in battle, and Dushana and Trishiras?''', 'veda-app-ai-draft', true),
('ramayana-3-32-4', 'en', 'Thus addressed by the lord of demons, the demoness, faint with anger, began to describe Rama properly.', 'veda-app-ai-draft', true),
('ramayana-3-32-5', 'en', '''Long-armed, large-eyed, wearing bark and black deerskin, handsome as the god of love, is Rama, son of Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-3-32-6', 'en', 'Drawing his gold-adorned bow, like Indra''s rainbow, he shoots blazing iron arrows like very venomous snakes.', 'veda-app-ai-draft', true),
('ramayana-3-32-7', 'en', 'I did not see mighty Rama taking his terrible arrows, releasing them or drawing his bow in battle;', 'veda-app-ai-draft', true),
('ramayana-3-32-8', 'en', 'I only saw that army being destroyed by showers of arrows, like the best crop destroyed by Indra with showers of hail.', 'veda-app-ai-draft', true),
('ramayana-3-32-9', 'en', 'Fourteen thousand demons of terrible valour were killed by sharp arrows by him alone, on foot,', 'veda-app-ai-draft', true),
('ramayana-3-32-10', 'en', 'and in an hour and a half Khara with Dushana; he gave the sages freedom from fear and made the Dandaka safe.', 'veda-app-ai-draft', true),
('ramayana-3-32-11', 'en', 'I alone was somehow let go, humiliated by the great-souled Rama, self-aware, who shrank from killing a woman.', 'veda-app-ai-draft', true),
('ramayana-3-32-12', 'en', 'His brother, of great energy, equal in qualities and valour, devoted and loyal, is the valiant one named Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-32-13', 'en', 'Impatient of wrong, invincible, victorious, valiant, wise and strong, he is Rama''s right arm, his very life walking outside him.', 'veda-app-ai-draft', true),
('ramayana-3-32-14', 'en', 'And Rama''s lawful wife is the large-eyed, famous, lovely, slender-waisted Sita of Videha.', 'veda-app-ai-draft', true),
('ramayana-3-32-15', 'en', 'Neither goddess, gandharvi, yakshi nor kinnari, nor any such woman, have I seen on earth before.', 'veda-app-ai-draft', true),
('ramayana-3-32-16', 'en', 'He whose wife Sita would be, and whom she would joyfully embrace, would live more happily in all the worlds than even Indra.', 'veda-app-ai-draft', true),
('ramayana-3-32-17', 'en', 'She is of fine character, praised for her form, beyond compare in beauty on earth; she is a fitting wife for you, and you a fitting husband for her.', 'veda-app-ai-draft', true),
('ramayana-3-32-18', 'en', 'I was trying to bring that lovely-faced woman of beautiful form to you as your wife.', 'veda-app-ai-draft', true),
('ramayana-3-32-19', 'en', 'Seeing Sita today, with her face like the full moon, you will fall under the arrows of the god of love.', 'veda-app-ai-draft', true),
('ramayana-3-32-20', 'en', 'If you wish her as your wife, quickly set forth your right foot here for victory.', 'veda-app-ai-draft', true),
('ramayana-3-32-21', 'en', 'And do a kindness to those demons, lord of demons, by killing that cruel Rama who lives in the hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-32-22', 'en', 'Having killed him and the great warrior Lakshmana with sharp arrows, you will enjoy Sita happily, her protector slain.', 'veda-app-ai-draft', true),
('ramayana-3-32-23', 'en', 'If my words please you, lord of demons, act on them without hesitation.', 'veda-app-ai-draft', true),
('ramayana-3-32-24', 'en', 'Having heard that the night-roamers of Janasthana were killed by Rama with straight-flying arrows, and knowing Khara and Dushana slain, you should act today.''', 'veda-app-ai-draft', true),
('ramayana-3-33-1', 'en', 'Hearing Shurpanakha''s hair-raising words, Ravana dismissed his ministers and, having decided what to do, departed.', 'veda-app-ai-draft', true),
('ramayana-3-33-2', 'en', 'Considering the matter, understanding it properly and weighing the strengths and weaknesses of its faults and merits,', 'veda-app-ai-draft', true),
('ramayana-3-33-3', 'en', 'having resolved ''This must be done'', firm of mind, he went to the lovely chariot house.', 'veda-app-ai-draft', true),
('ramayana-3-33-4', 'en', 'Going to the chariot house secretly, the lord of demons ordered his charioteer: ''Yoke the chariot.''', 'veda-app-ai-draft', true),
('ramayana-3-33-5', 'en', 'Thus told, the quick charioteer at once yoked his favourite, excellent chariot.', 'veda-app-ai-draft', true),
('ramayana-3-33-6', 'en', 'Mounting the golden chariot that went where he wished, adorned with jewels and drawn by goblin-faced donkeys decked with gold,', 'veda-app-ai-draft', true),
('ramayana-3-33-7', 'en', 'the glorious lord of demons, younger brother of Kubera, went with a sound like a thundercloud toward the ocean, lord of rivers.', 'veda-app-ai-draft', true),
('ramayana-3-33-8', 'en', 'Ten-faced, with white yak-tail fans and a white parasol, shining like smooth beryl, adorned with refined gold,', 'veda-app-ai-draft', true),
('ramayana-3-33-9', 'en', 'ten-faced, twenty-armed, splendidly dressed, enemy of the gods and killer of great sages, like a ten-peaked king of mountains,', 'veda-app-ai-draft', true),
('ramayana-3-33-10', 'en', 'the lord of demons shone in his wish-going chariot like a cloud in the sky with lightning flashes and cranes.', 'veda-app-ai-draft', true),
('ramayana-3-33-11', 'en', 'The mighty one looked down on the seacoast with its mountains, strewn with thousands of trees bearing many flowers and fruits,', 'veda-app-ai-draft', true),
('ramayana-3-33-12', 'en', 'surrounded on all sides by lotus ponds with cool, auspicious water and by large hermitages with altars,', 'veda-app-ai-draft', true),
('ramayana-3-33-13', 'en', 'crowded with plantain and adhaki, adorned with coconut palms, with sala, palm, tamala and flowering trees,', 'veda-app-ai-draft', true),
('ramayana-3-33-14', 'en', 'graced by great seers of very restrained diet, and by thousands of nagas, suparnas, gandharvas and kinnaras,', 'veda-app-ai-draft', true),
('ramayana-3-33-15', 'en', 'adorned with perfected beings who had conquered desire, celestial singers, and Aja, Vaikhanasa, Masha, Valakhilya and Marichipa sages,', 'veda-app-ai-draft', true),
('ramayana-3-33-16', 'en', 'filled with thousands of apsaras of divine form, wearing divine ornaments and garlands, skilled in play and love,', 'veda-app-ai-draft', true),
('ramayana-3-33-17', 'en', 'frequented by the glorious wives of the gods and visited by hosts of gods and danavas who feed on nectar,', 'veda-app-ai-draft', true),
('ramayana-3-33-18', 'en', 'scattered with swans, herons and frogs, echoing with cranes, lovely, with beryl stones, glossy with the ocean''s brilliance.', 'veda-app-ai-draft', true),
('ramayana-3-33-19', 'en', 'All around were large white celestial chariots adorned with divine garlands, filled with music and song.', 'veda-app-ai-draft', true),
('ramayana-3-33-20', 'en', 'Kubera''s younger brother saw the wish-going chariots of those who had won worlds by austerity, and gandharvas and apsaras.', 'veda-app-ai-draft', true),
('ramayana-3-33-21', 'en', 'He saw thousands of gentle sandal forests, with resin-rich roots, delightful to the nose,', 'veda-app-ai-draft', true),
('ramayana-3-33-22', 'en', 'forests and groves of the finest aloe wood, and of takkola trees with fragrant fruits,', 'veda-app-ai-draft', true),
('ramayana-3-33-23', 'en', 'flowers of tamala, shrubs of pepper, and heaps of pearls drying on the shore,', 'veda-app-ai-draft', true),
('ramayana-3-33-24', 'en', 'beds of conch shells, heaps of coral, and mountains of gold and silver everywhere,', 'veda-app-ai-draft', true),
('ramayana-3-33-25', 'en', 'charming waterfalls and clear lakes, cities full of wealth and grain and filled with jewels among women,', 'veda-app-ai-draft', true),
('ramayana-3-33-26', 'en', 'crowded with elephants, horses and chariots. He saw the shore of the king of rivers, level everywhere, smooth, with soft breezes,', 'veda-app-ai-draft', true),
('ramayana-3-33-27', 'en', 'like heaven. There he saw a banyan like a cloud, surrounded by sages,', 'veda-app-ai-draft', true),
('ramayana-3-33-28', 'en', 'whose branches spread a hundred yojanas all around; to whose branch mighty Garuda once came, carrying an elephant and a huge tortoise to eat.', 'veda-app-ai-draft', true),
('ramayana-3-33-29', 'en', 'Suddenly the mighty Suparna, best of birds, broke that leafy branch with his weight.', 'veda-app-ai-draft', true),
('ramayana-3-33-30', 'en', 'On it were gathered great seers: Vaikhanasas, Mashas, Valakhilyas, Marichipas, Ajas and Dhumras.', 'veda-app-ai-draft', true),
('ramayana-3-33-31', 'en', 'Out of compassion for them, Garuda quickly carried away that hundred-yojana branch, along with the elephant and the tortoise.', 'veda-app-ai-draft', true),
('ramayana-3-33-32', 'en', 'The righteous best of birds ate that flesh with one foot, destroyed the land of the Nishadas with the branch, and felt boundless joy at freeing the great sages.', 'veda-app-ai-draft', true),
('ramayana-3-33-33', 'en', 'With that very joy his strength doubled, and the wise one resolved to bring back the nectar of immortality.', 'veda-app-ai-draft', true),
('ramayana-3-33-34', 'en', 'Breaking the iron nets and splitting the excellent jewelled house, he carried off the guarded nectar from great Indra''s palace.', 'veda-app-ai-draft', true),
('ramayana-3-33-35', 'en', 'Kubera''s younger brother saw that banyan named Subhadra, frequented by hosts of great seers and bearing the marks Garuda made.', 'veda-app-ai-draft', true),
('ramayana-3-33-36', 'en', 'Going to the far shore of the ocean, lord of rivers, he saw a hermitage in a secluded, holy, lovely part of the forest.', 'veda-app-ai-draft', true),
('ramayana-3-33-37', 'en', 'There he saw the demon named Maricha, wearing black deerskin, matted hair and bark, restrained in diet.', 'veda-app-ai-draft', true),
('ramayana-3-33-38', 'en', 'Ravana met that demon in the proper way, and then the skilled speaker said these words:', 'veda-app-ai-draft', true),
('ramayana-3-34-1', 'en', '''Maricha, dear one, listen to what I say. I am in distress, and you are my highest refuge in distress.', 'veda-app-ai-draft', true),
('ramayana-3-34-2', 'en', 'You know Janasthana, where my brother Khara, mighty-armed Dushana and my sister Shurpanakha lived,', 'veda-app-ai-draft', true),
('ramayana-3-34-3', 'en', 'and the mighty flesh-eating demon Trishiras, and many other brave night-roamers who never miss their mark.', 'veda-app-ai-draft', true),
('ramayana-3-34-4', 'en', 'They lived there by my order, troubling the sages who follow dharma in the great forest.', 'veda-app-ai-draft', true),
('ramayana-3-34-5', 'en', 'Fourteen thousand demons of terrible deeds, brave, sure of aim, following Khara''s will,', 'veda-app-ai-draft', true),
('ramayana-3-34-6', 'en', 'these mighty ones living in Janasthana, gathered and fully prepared, met Rama in battle.', 'veda-app-ai-draft', true),
('ramayana-3-34-7', 'en', 'Rama, enraged at the head of battle, without saying anything harsh, put his bow to work with arrows,', 'veda-app-ai-draft', true),
('ramayana-3-34-8', 'en', 'and fourteen thousand demons of terrible deeds were killed with sharp arrows by a man on foot.', 'veda-app-ai-draft', true),
('ramayana-3-34-9', 'en', 'Khara was killed in battle and Dushana brought down; having killed Trishiras too, he made the Dandaka free of fear.', 'veda-app-ai-draft', true),
('ramayana-3-34-10', 'en', 'Driven out by his angry father with his wife, his life nearly spent, that Rama, disgrace to the warrior class, has destroyed that army.', 'veda-app-ai-draft', true),
('ramayana-3-34-11', 'en', 'He is without virtue, harsh, fierce, foolish, greedy, without self-control; he has abandoned dharma, is unrighteous and bent on harming creatures.', 'veda-app-ai-draft', true),
('ramayana-3-34-12', 'en', 'Without any enmity, relying only on his strength, he disfigured my sister in the forest by cutting off her ears and nose.', 'veda-app-ai-draft', true),
('ramayana-3-34-13', 'en', 'I will bravely carry off his wife Sita, like a daughter of the gods, from Janasthana; be my helper in this.', 'veda-app-ai-draft', true),
('ramayana-3-34-14', 'en', 'With you as my helper at my side, mighty one, and my brothers, I do not think about all the gods in battle.', 'veda-app-ai-draft', true),
('ramayana-3-34-15', 'en', 'So be my helper, for you are able, demon; there is none equal to you in valour, war and pride.', 'veda-app-ai-draft', true),
('ramayana-3-34-16', 'en', 'For this I have come to you, night-roamer. Hear what you must do to help, at my word.', 'veda-app-ai-draft', true),
('ramayana-3-34-17', 'en', 'Become a golden deer, spotted with silver drops, and roam in front of Sita in Rama''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-34-18', 'en', 'Seeing you in the form of a deer, Sita will without doubt tell her husband and Lakshmana, "Catch it!"', 'veda-app-ai-draft', true),
('ramayana-3-34-19', 'en', 'Then, when the two are gone and the place is empty, I will carry off Sita at my ease, unhindered, as Rahu takes the moonlight.', 'veda-app-ai-draft', true),
('ramayana-3-34-20', 'en', 'Then afterwards I will strike Rama easily, wasted by the loss of his wife, with a confident heart, my purpose fulfilled.''', 'veda-app-ai-draft', true),
('ramayana-3-34-21', 'en', 'Hearing talk of Rama, the great Maricha''s mouth went dry and he was terrified.', 'veda-app-ai-draft', true),
('ramayana-3-34-22', 'en', 'His heart frightened and dejected, knowing Rama''s valour in the great forest, Maricha with joined palms spoke the truth to Ravana, good for him and good for himself.', 'veda-app-ai-draft', true),
('ramayana-3-35-1', 'en', 'Hearing the lord of demons'' words, wise Maricha, skilled in speech, replied to the lord of demons:', 'veda-app-ai-draft', true),
('ramayana-3-35-2', 'en', '''People who always speak pleasantly are easy to find, king; but one who speaks unpleasant but beneficial truth, and one who listens to it, are rare.', 'veda-app-ai-draft', true),
('ramayana-3-35-3', 'en', 'Surely you do not understand Rama, mighty and great in virtue, like great Indra and Varuna, since you have no spies and are fickle.', 'veda-app-ai-draft', true),
('ramayana-3-35-4', 'en', 'Will there be well-being for all demons on earth, dear one? Will Rama, enraged, not rid the world of demons?', 'veda-app-ai-draft', true),
('ramayana-3-35-5', 'en', 'Was Janaka''s daughter not born to end your life? Will Sita not become the cause of great disaster?', 'veda-app-ai-draft', true),
('ramayana-3-35-6', 'en', 'Having you as lord, desire-driven and unrestrained, will Lanka not be destroyed with you and its demons?', 'veda-app-ai-draft', true),
('ramayana-3-35-7', 'en', 'For a king like you, driven by desire, of bad character and evil counsel, the foolish king destroys himself, his people and his kingdom.', 'veda-app-ai-draft', true),
('ramayana-3-35-8', 'en', 'He was not cast out by his father, he has never gone beyond bounds, he is not greedy, nor ill-natured, nor a disgrace to warriors.', 'veda-app-ai-draft', true),
('ramayana-3-35-9', 'en', 'Kausalya''s son is not lacking in the virtues of dharma; nor is he harsh, but devoted to the good of all beings.', 'veda-app-ai-draft', true),
('ramayana-3-35-10', 'en', 'Seeing his truthful father deceived by Kaikeyi, the righteous one said ''I will do it'' and went to the forest.', 'veda-app-ai-draft', true),
('ramayana-3-35-11', 'en', 'To please Kaikeyi and his father Dasharatha, he gave up the kingdom and pleasures and entered the Dandaka forest.', 'veda-app-ai-draft', true),
('ramayana-3-35-12', 'en', 'Rama is not harsh, dear one, nor ignorant, nor uncontrolled. You must not speak such untruths that are not even heard of.', 'veda-app-ai-draft', true),
('ramayana-3-35-13', 'en', 'Rama is dharma in bodily form, a good man of true valour, king of the whole world, as Indra is of the gods.', 'veda-app-ai-draft', true),
('ramayana-3-35-14', 'en', 'How can you wish to carry off by force Sita, protected by his own power, like the light of the sun?', 'veda-app-ai-draft', true),
('ramayana-3-35-15', 'en', 'You should not suddenly enter the blazing fire of Rama, unassailable in battle, whose flames are arrows and whose fuel is bow and sword.', 'veda-app-ai-draft', true),
('ramayana-3-35-16', 'en', 'With his bow like a gaping blazing mouth, his arrows like flames, intolerant, the hero holding bow and arrows, destroyer of enemy armies,', 'veda-app-ai-draft', true),
('ramayana-3-35-17', 'en', 'you should not approach Rama, like Death, giving up kingdom, happiness and your own dear life, dear one.', 'veda-app-ai-draft', true),
('ramayana-3-35-18', 'en', 'Immeasurable is the power of him whose wife is Janaka''s daughter; you cannot carry her off in the forest, sheltered by Rama''s bow.', 'veda-app-ai-draft', true),
('ramayana-3-35-19', 'en', 'Dearer to him than life, always devoted, slender-waisted Sita is like the flame of a blazing fire.', 'veda-app-ai-draft', true),
('ramayana-3-35-20', 'en', 'What use is this pointless effort, lord of demons? If he sees you in battle, that is the end of your life, and of your happiness and your kingdom, so hard to win.', 'veda-app-ai-draft', true),
('ramayana-3-35-21', 'en', 'Consult with all your ministers, led by the righteous Vibhishana, and then make up your own mind.', 'veda-app-ai-draft', true),
('ramayana-3-35-22', 'en', 'Weigh the strength of the faults and merits, know truly your own strength and Rama''s, decide what is good for you, and then do what is fitting.', 'veda-app-ai-draft', true),
('ramayana-3-35-23', 'en', 'I think a battle with the son of the king of Kosala is not right for you. Listen further to my words, which are best, fitting and proper, lord of night-roamers.', 'veda-app-ai-draft', true),
('ramayana-3-36-1', 'en', 'Once, proud of my strength, I roamed this earth, mountain-like, with the strength of a thousand elephants,', 'veda-app-ai-draft', true),
('ramayana-3-36-2', 'en', 'dark as a blue cloud, with earrings of refined gold, frightening the world, crowned and armed with an iron club, roaming the Dandaka forest eating the flesh of sages.', 'veda-app-ai-draft', true),
('ramayana-3-36-3', 'en', 'Then the righteous great sage Vishvamitra, frightened of me, went himself to King Dasharatha and said:', 'veda-app-ai-draft', true),
('ramayana-3-36-4', 'en', '''Let Rama guard me attentively at the time of the holy rite; a terrible fear has arisen for me from Maricha, lord of men.''', 'veda-app-ai-draft', true),
('ramayana-3-36-5', 'en', 'Thus addressed, the righteous King Dasharatha replied to the noble great sage Vishvamitra:', 'veda-app-ai-draft', true),
('ramayana-3-36-6', 'en', '''Rama is not yet sixteen and untrained in weapons. My whole army will go with me if you wish; I will kill your enemy as you desire, best of sages.''', 'veda-app-ai-draft', true),
('ramayana-3-36-7', 'en', 'Thus addressed, the sage said to the king again: ''No strength in the world but Rama''s is enough for that demon.', 'veda-app-ai-draft', true),
('ramayana-3-36-8', 'en', 'Though a boy, this mighty one can subdue him. I will go, taking Rama; may all be well with you, scorcher of foes.''', 'veda-app-ai-draft', true),
('ramayana-3-36-9', 'en', 'Having said this, the sage Vishvamitra, very pleased, took the prince and went to his own hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-36-10', 'en', 'Then in the Dandaka forest Rama stood guard over the one consecrated for the sacrifice, twanging his bright bow.', 'veda-app-ai-draft', true),
('ramayana-3-36-11', 'en', 'Beardless yet, glorious, a dark boy with lovely eyes, wearing a single cloth, bow in hand, with a topknot and a golden garland,', 'veda-app-ai-draft', true),
('ramayana-3-36-12', 'en', 'lighting up the Dandaka forest with his own blazing power, Rama looked like the young moon risen.', 'veda-app-ai-draft', true),
('ramayana-3-36-13', 'en', 'Then I, like a cloud, with earrings of refined gold, strong and proud of my boon, came to that hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-36-14', 'en', 'He saw me enter suddenly with weapon raised; seeing me, he calmly strung his bow.', 'veda-app-ai-draft', true),
('ramayana-3-36-15', 'en', 'Despising Rama in my delusion, thinking ''He is a boy'', I rushed in haste at Vishvamitra''s altar.', 'veda-app-ai-draft', true),
('ramayana-3-36-16', 'en', 'Then he released a sharp, foe-destroying arrow; struck by it, I was flung a hundred yojanas into the sea.', 'veda-app-ai-draft', true),
('ramayana-3-36-17', 'en', 'Thrown off by the force of Rama''s arrow, my senses reeling, I was cast into the deep waters of the ocean; regaining consciousness after a long time, I went to the city of Lanka.', 'veda-app-ai-draft', true),
('ramayana-3-36-18', 'en', 'So I was spared then, but my companions were killed by Rama, a boy untrained in weapons, tireless in his deeds.', 'veda-app-ai-draft', true),
('ramayana-3-36-19', 'en', 'So if, though I warn you, you make war on Rama, you will soon meet terrible disaster and perish.', 'veda-app-ai-draft', true),
('ramayana-3-36-20', 'en', 'You will bring suffering and ruin on the demons, who know play and love and delight in gatherings and festivals.', 'veda-app-ai-draft', true),
('ramayana-3-36-21', 'en', 'You will see the city of Lanka, crowded with mansions and palaces and adorned with many jewels, destroyed for the sake of Sita.', 'veda-app-ai-draft', true),
('ramayana-3-36-22', 'en', 'Even the pure who do no evil perish through the sins of others because they shelter with the wicked, as fish in a serpent''s pool.', 'veda-app-ai-draft', true),
('ramayana-3-36-23', 'en', 'You will see demons, their limbs anointed with divine sandal and adorned with divine ornaments, struck down on the ground through your fault.', 'veda-app-ai-draft', true),
('ramayana-3-36-24', 'en', 'You will see night-roamers, with wives seized or still with them, the survivors, fleeing in ten directions without refuge.', 'veda-app-ai-draft', true),
('ramayana-3-36-25', 'en', 'You will surely see Lanka covered with a net of arrows, wrapped in flames, its houses burned.', 'veda-app-ai-draft', true),
('ramayana-3-36-26', 'en', 'You have thousands of women, king; be devoted to your own wives and save your own clan, demon.', 'veda-app-ai-draft', true),
('ramayana-3-36-27', 'en', 'If you wish to enjoy honour, prosperity, kingdom and your own dear life for long, do nothing to displease Rama.', 'veda-app-ai-draft', true),
('ramayana-3-36-28', 'en', 'If, though strongly restrained by me, your friend, you seize Sita by force, you will go to Yama''s realm with your strength spent and your kin, your life taken by Rama''s arrows.''', 'veda-app-ai-draft', true),
('ramayana-3-37-1', 'en', '''So I escaped then from him in battle somehow. Now hear what happened afterwards.', 'veda-app-ai-draft', true),
('ramayana-3-37-2', 'en', 'Still not humbled, I entered the Dandaka forest with two demons, all of us in the form of deer.', 'veda-app-ai-draft', true),
('ramayana-3-37-3', 'en', 'With blazing tongue, huge body, sharp horns and great strength, I roamed the Dandaka forest as a great flesh-eating beast.', 'veda-app-ai-draft', true),
('ramayana-3-37-4', 'en', 'At fire offerings, bathing places and sacred trees, I roamed very fiercely, Ravana, attacking those ascetics.', 'veda-app-ai-draft', true),
('ramayana-3-37-5', 'en', 'Killing the ascetics who followed dharma in the Dandaka forest, I drank their blood and ate their flesh.', 'veda-app-ai-draft', true),
('ramayana-3-37-6', 'en', 'Eating the flesh of sages, cruel, terrifying the forest-dwellers, drunk with blood, I roamed the Dandaka forest.', 'veda-app-ai-draft', true),
('ramayana-3-37-7', 'en', 'Then, roaming the Dandaka forest as a corrupter of dharma, I came upon Rama, an ascetic devoted to dharma,', 'veda-app-ai-draft', true),
('ramayana-3-37-8', 'en', 'with the noble Sita and the great warrior Lakshmana, an ascetic restrained in diet, devoted to the good of all beings.', 'veda-app-ai-draft', true),
('ramayana-3-37-9', 'en', 'Despising mighty Rama living in the forest, thinking ''He is an ascetic'', and remembering the old enmity,', 'veda-app-ai-draft', true),
('ramayana-3-37-10', 'en', 'I rushed at him in fury in deer form with sharp horns, wanting to kill him, foolishly, remembering that blow.', 'veda-app-ai-draft', true),
('ramayana-3-37-11', 'en', 'He released three sharp, foe-destroying arrows, drawing his strong bow, swift as Garuda or the wind.', 'veda-app-ai-draft', true),
('ramayana-3-37-12', 'en', 'Those three very dreadful, blood-drinking, smooth-jointed arrows, like thunderbolts, came together.', 'veda-app-ai-draft', true),
('ramayana-3-37-13', 'en', 'Knowing Rama''s valour and having seen the danger before, I cunningly leapt away and escaped; the other two demons were killed.', 'veda-app-ai-draft', true),
('ramayana-3-37-14', 'en', 'Freed somehow from Rama''s arrow, keeping my life, I have renounced the world here and become an ascetic, disciplined and composed.', 'veda-app-ai-draft', true),
('ramayana-3-37-15', 'en', 'In every tree I see Rama, wearing bark and black deerskin, bow in hand, like Death with a noose in his hand.', 'veda-app-ai-draft', true),
('ramayana-3-37-16', 'en', 'In fear I see thousands of Ramas, Ravana; this whole forest seems to me to be made of Rama.', 'veda-app-ai-draft', true),
('ramayana-3-37-17', 'en', 'I see Rama even when alone, lord of demons; seeing Rama in my dreams, I wake up distraught.', 'veda-app-ai-draft', true),
('ramayana-3-37-18', 'en', 'For me, terrified of Rama, Ravana, names that begin with ''ra'', even ratna (jewel) and ratha (chariot), cause fear.', 'veda-app-ai-draft', true),
('ramayana-3-37-19', 'en', 'I know his power; a battle with him is not right for you. Fight Rama in battle or forgive him, demon; but do not speak of Rama to me if you want to see me.', 'veda-app-ai-draft', true),
('ramayana-3-37-20', 'en', 'If you do not accept these words spoken by me, who wishes my kin well, you will lose your life in battle today with your kin, killed by Rama with straight arrows.''', 'veda-app-ai-draft', true),
('ramayana-3-38-1', 'en', 'Ravana did not accept Maricha''s fitting and proper words, like a man who wants to die refusing medicine.', 'veda-app-ai-draft', true),
('ramayana-3-38-2', 'en', 'Driven by fate, the lord of demons spoke harsh, improper words to Maricha, who had spoken what was wholesome and good:', 'veda-app-ai-draft', true),
('ramayana-3-38-3', 'en', '''These improper words you speak to me, Maricha, are utterly fruitless, like seed sown in salty ground.', 'veda-app-ai-draft', true),
('ramayana-3-38-4', 'en', 'Your words cannot break my resolve to fight Rama, especially as he is an evil-natured, foolish man,', 'veda-app-ai-draft', true),
('ramayana-3-38-5', 'en', 'who, leaving friends, kingdom, mother and father, went to the forest at a single word from a common woman.', 'veda-app-ai-draft', true),
('ramayana-3-38-6', 'en', 'I must certainly carry off Sita, dearer to him than life, from that killer of Khara, in your presence.', 'veda-app-ai-draft', true),
('ramayana-3-38-7', 'en', 'This resolve is firm in my heart, Maricha; it cannot be turned back even by gods and demons with Indra.', 'veda-app-ai-draft', true),
('ramayana-3-38-8', 'en', 'You should speak of fault or merit only when asked, or of the danger or means in deciding this matter.', 'veda-app-ai-draft', true),
('ramayana-3-38-9', 'en', 'A wise minister who wants his own prosperity should speak to the king only when asked, with joined palms.', 'veda-app-ai-draft', true),
('ramayana-3-38-10', 'en', 'A king should be spoken to with words that do not oppose him, gently, auspiciously, beneficially and with courtesy.', 'veda-app-ai-draft', true),
('ramayana-3-38-11', 'en', 'A king worthy of honour does not welcome words, however beneficial, spoken with contempt and lacking respect.', 'veda-app-ai-draft', true),
('ramayana-3-38-12', 'en', 'Kings of boundless might bear five forms: of Agni, Indra, Soma, Yama and Varuna, namely heat, valour, gentleness, punishment and graciousness.', 'veda-app-ai-draft', true),
('ramayana-3-38-13', 'en', 'So kings are to be honoured and respected in every situation; but you, not knowing dharma, rely only on delusion.', 'veda-app-ai-draft', true),
('ramayana-3-38-14', 'en', 'Out of wickedness you speak harshly to me, your guest. I am not asking about merits and faults, or what is right for me, demon; you must give help in this task.', 'veda-app-ai-draft', true),
('ramayana-3-38-15', 'en', 'Become a golden deer spotted with silver, tempt Sita, and then go where you like.', 'veda-app-ai-draft', true),
('ramayana-3-38-16', 'en', 'Seeing you, a magical golden deer, Sita, filled with wonder, will quickly say to Rama, "Bring it!"', 'veda-app-ai-draft', true),
('ramayana-3-38-17', 'en', 'When Rama and Lakshmana have gone, I will carry off Sita at my ease, as Indra carried off Shachi.', 'veda-app-ai-draft', true),
('ramayana-3-38-18', 'en', 'Having done this, go where you like, demon. I will give you half my kingdom, Maricha of good vows.', 'veda-app-ai-draft', true),
('ramayana-3-38-19', 'en', 'Go on an auspicious path, gentle one, for the success of this work. Having won Sita without a fight, by deceiving Rama, I will go to Lanka with you, my purpose done.', 'veda-app-ai-draft', true),
('ramayana-3-38-20', 'en', 'You will do this for me even by force; one who opposes a king never prospers.', 'veda-app-ai-draft', true),
('ramayana-3-38-21', 'en', 'Going to him your life is in doubt, but opposing me your death is certain today. Consider this properly and do what is best.''', 'veda-app-ai-draft', true),
('ramayana-3-39-1', 'en', 'Ordered like a king with hostile words, the night-roamer Maricha spoke harshly to the lord of demons:', 'veda-app-ai-draft', true),
('ramayana-3-39-2', 'en', '''What evil-doer has advised you to this ruin, of yourself, your sons, your kingdom and your ministers, night-roamer?', 'veda-app-ai-draft', true),
('ramayana-3-39-3', 'en', 'What sinner does not rejoice in your happiness, king? Who has cleverly shown you this door to death?', 'veda-app-ai-draft', true),
('ramayana-3-39-4', 'en', 'Clearly your enemies, weak in strength, wish to see you perish, caught by one stronger.', 'veda-app-ai-draft', true),
('ramayana-3-39-5', 'en', 'What mean, ill-speaking person has advised you so, wishing you to perish by your own deed, night-roamer?', 'veda-app-ai-draft', true),
('ramayana-3-39-6', 'en', 'Surely your ministers deserve death and are not being killed, Ravana, since they do not restrain you at all when you have taken the wrong road.', 'veda-app-ai-draft', true),
('ramayana-3-39-7', 'en', 'A king driven by desire who has taken a wrong path must always be restrained by good ministers; you who should be restrained are not.', 'veda-app-ai-draft', true),
('ramayana-3-39-8', 'en', 'By their master''s favour, ministers gain dharma, wealth, pleasure and fame, best of victors.', 'veda-app-ai-draft', true),
('ramayana-3-39-9', 'en', 'But when it is otherwise, all that is in vain, Ravana; other people meet disaster through their master''s faults.', 'veda-app-ai-draft', true),
('ramayana-3-39-10', 'en', 'For dharma and victory are rooted in the king, best of victors; so the king must be protected in every situation.', 'veda-app-ai-draft', true),
('ramayana-3-39-11', 'en', 'A kingdom cannot be protected by one who is harsh, night-roamer, nor by one who is perverse or undisciplined.', 'veda-app-ai-draft', true),
('ramayana-3-39-12', 'en', 'Ministers who give harsh counsel are broken along with the king, like chariots with poor drivers on rough ground.', 'veda-app-ai-draft', true),
('ramayana-3-39-13', 'en', 'Many good people in the world who practise dharma properly have perished with their families through the fault of others.', 'veda-app-ai-draft', true),
('ramayana-3-39-14', 'en', 'Subjects protected by a harsh, perverse master do not prosper, Ravana, any more than sheep guarded by a jackal.', 'veda-app-ai-draft', true),
('ramayana-3-39-15', 'en', 'All the demons will surely perish, Ravana, whose king is you, harsh, foolish and without self-control.', 'veda-app-ai-draft', true),
('ramayana-3-39-16', 'en', 'This terrible disaster has come on you by chance, like the crow and the palm fruit; what good is it that you will perish with your army?', 'veda-app-ai-draft', true),
('ramayana-3-39-17', 'en', 'Having killed me, Rama will soon kill you. By this I have done my part: I will die killed by an enemy.', 'veda-app-ai-draft', true),
('ramayana-3-39-18', 'en', 'Consider me dead at the very sight of Rama, and know yourself dead with your kin once you carry off Sita.', 'veda-app-ai-draft', true),
('ramayana-3-39-19', 'en', 'If you bring Sita from the hermitage with me, neither you nor I nor Lanka nor the demons will survive.', 'veda-app-ai-draft', true),
('ramayana-3-39-20', 'en', 'Though warned by me, who wish you well, you will not bear these words, night-roamer; for men whose life is over, as good as dead, do not accept the good advice of friends.''', 'veda-app-ai-draft', true),
('ramayana-3-40-1', 'en', 'Having spoken so harshly to Ravana, Maricha, wretched and afraid of the lord of night-roamers, said, ''Let us go.''', 'veda-app-ai-draft', true),
('ramayana-3-40-2', 'en', '''Once he sees me again, with bow, arrows and sword, weapon raised to kill me, my life is gone.', 'veda-app-ai-draft', true),
('ramayana-3-40-3', 'en', 'But what can I do with you being so wicked? Here I go, dear one; may you fare well, night-roamer.''', 'veda-app-ai-draft', true),
('ramayana-3-40-4', 'en', 'The demon was delighted by those words, embraced him tightly and said:', 'veda-app-ai-draft', true),
('ramayana-3-40-5', 'en', '''These are brave words, as if spoken by my own wish. Now you are Maricha; before, you were some other night-roamer.', 'veda-app-ai-draft', true),
('ramayana-3-40-6', 'en', 'Quickly mount this jewelled, sky-going chariot with me, yoked to goblin-faced donkeys.''', 'veda-app-ai-draft', true),
('ramayana-3-40-7', 'en', 'Then Ravana and Maricha mounted that chariot like a celestial car and quickly left that circle of hermitages.', 'veda-app-ai-draft', true),
('ramayana-3-40-8', 'en', 'Looking at towns, forests, mountains, all rivers, kingdoms and cities as they went,', 'veda-app-ai-draft', true),
('ramayana-3-40-9', 'en', 'reaching the Dandaka forest, Ravana, lord of demons, with Maricha saw Rama''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-40-10', 'en', 'Getting down from that gold-adorned chariot, Ravana took Maricha by the hand and said:', 'veda-app-ai-draft', true),
('ramayana-3-40-11', 'en', '''There is Rama''s hermitage, surrounded by plantains. Do quickly, friend, what we came for.''', 'veda-app-ai-draft', true),
('ramayana-3-40-12', 'en', 'Hearing Ravana''s words, the demon Maricha became a deer and wandered by the door of Rama''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-40-13', 'en', 'The tips of his horns were the finest gems, his face white and dark, his mouth like a red lotus, his ears like blue sapphire lotuses,', 'veda-app-ai-draft', true),
('ramayana-3-40-14', 'en', 'his neck slightly raised, his belly like sapphire, his flanks like madhuka flowers, the colour of lotus filaments,', 'veda-app-ai-draft', true),
('ramayana-3-40-15', 'en', 'hooves like beryl, slender legs, well-knit, shining with its tail raised up, coloured like the rainbow,', 'veda-app-ai-draft', true),
('ramayana-3-40-16', 'en', 'of lovely glossy colour, covered with many kinds of jewels: in a moment the demon became a most beautiful deer.', 'veda-app-ai-draft', true),
('ramayana-3-40-17', 'en', 'Lighting up the lovely forest and Rama''s hermitage, the demon took on a charming, beautiful form.', 'veda-app-ai-draft', true),
('ramayana-3-40-18', 'en', 'To tempt Sita, coloured with many minerals, he wandered gracefully over the grassy places all around.', 'veda-app-ai-draft', true),
('ramayana-3-40-19', 'en', 'Spotted with hundreds of silver drops and lovely to see, he wandered about breaking and eating the young shoots of trees.', 'veda-app-ai-draft', true),
('ramayana-3-40-20', 'en', 'Going to the plantain bower and here and there among the karnikara trees, he moved slowly into Sita''s sight.', 'veda-app-ai-draft', true),
('ramayana-3-40-21', 'en', 'With its back patterned like lotuses, the great deer shone, wandering freely near Rama''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-3-40-22', 'en', 'The finest of deer would go away and come back, run off for a moment and quickly return again.', 'veda-app-ai-draft', true),
('ramayana-3-40-23', 'en', 'Playing, it would sit on the ground again; coming to the hermitage door, it would go off to the herds of deer.', 'veda-app-ai-draft', true),
('ramayana-3-40-24', 'en', 'Followed by herds of deer, it would turn back again; the demon in deer form longed to be seen by Sita.', 'veda-app-ai-draft', true),
('ramayana-3-40-25', 'en', 'It wandered, leaping in lovely circles. All the other forest deer looked at it,', 'veda-app-ai-draft', true),
('ramayana-3-40-26', 'en', 'came near, sniffed it, and fled in ten directions. The demon, though given to killing deer, did not eat those wild deer,', 'veda-app-ai-draft', true),
('ramayana-3-40-27', 'en', 'touching them but not eating, to hide his true nature. At that very time lovely-eyed Sita', 'veda-app-ai-draft', true),
('ramayana-3-40-28', 'en', 'was busy gathering flowers among the trees. The bright-eyed one passed karnikara, ashoka and mango trees', 'veda-app-ai-draft', true),
('ramayana-3-40-29', 'en', 'picking flowers, lovely-faced. That noble lady, who did not deserve forest life, saw the jewelled deer, its body patterned with pearls and gems.', 'veda-app-ai-draft', true),
('ramayana-3-40-30', 'en', 'With lovely teeth and lips, its hair like silver, she gazed at it fondly, her eyes wide with wonder.', 'veda-app-ai-draft', true),
('ramayana-3-40-31', 'en', 'And the magical deer, looking at Rama''s beloved, wandered there as if setting the forest alight.', 'veda-app-ai-draft', true),
('ramayana-3-40-32', 'en', 'Seeing that deer made of many jewels, such as she had never seen before, Sita, daughter of Janaka, was filled with great wonder.', 'veda-app-ai-draft', true),
('ramayana-3-41-1', 'en', 'Gathering flowers, the lovely one looked at it, adorned with flanks of gold and silver.', 'veda-app-ai-draft', true),
('ramayana-3-41-2', 'en', 'Delighted, the flawless one, bright as polished gold, called out to her husband and to Lakshmana with his weapons.', 'veda-app-ai-draft', true),
('ramayana-3-41-3', 'en', 'Called by Sita, Rama and Lakshmana, tigers among men, looked around the place and saw the deer.', 'veda-app-ai-draft', true),
('ramayana-3-41-4', 'en', 'Seeing it, Lakshmana was suspicious and said to Rama: ''I think this deer is the demon Maricha himself.', 'veda-app-ai-draft', true),
('ramayana-3-41-5', 'en', 'Kings happily hunting in the forest have been killed by this wicked shape-shifter through just such a disguise, Rama.', 'veda-app-ai-draft', true),
('ramayana-3-41-6', 'en', 'This magical deer form has been made by this master of illusion, tiger among men, shining like a mirage city of the gandharvas.', 'veda-app-ai-draft', true),
('ramayana-3-41-7', 'en', 'No such jewel-patterned deer exists in the world, Rama, lord of the world; this is illusion, no doubt.''', 'veda-app-ai-draft', true),
('ramayana-3-41-8', 'en', 'As he spoke, bright-smiling Sita, her mind captured by the deception, stopped him and said joyfully:', 'veda-app-ai-draft', true),
('ramayana-3-41-9', 'en', '''My noble husband, this lovely deer steals my heart. Bring it, mighty-armed one; it will be our plaything.', 'veda-app-ai-draft', true),
('ramayana-3-41-10', 'en', 'Many holy-looking deer roam together here at our hermitage, yaks and srimaras,', 'veda-app-ai-draft', true),
('ramayana-3-41-11', 'en', 'bears, herds of spotted deer, monkeys and kinnaras roam, mighty-armed one, finest in form and very strong,', 'veda-app-ai-draft', true),
('ramayana-3-41-12', 'en', 'but never before, king, have I seen a deer like this best of deer, in radiance, gentleness and brilliance.', 'veda-app-ai-draft', true),
('ramayana-3-41-13', 'en', 'Its body patterned with many colours, studded with drops of jewels, lighting up the forest calmly, it shines like the moon.', 'veda-app-ai-draft', true),
('ramayana-3-41-14', 'en', 'Ah, what form, what beauty, and what lovely voice! This wonderful, colourful deer seems to steal my heart.', 'veda-app-ai-draft', true),
('ramayana-3-41-15', 'en', 'If the deer can be caught alive by you, it will be a marvel and will cause wonder.', 'veda-app-ai-draft', true),
('ramayana-3-41-16', 'en', 'When our forest life is over and we are back in the kingdom, this deer will adorn the inner palace.', 'veda-app-ai-draft', true),
('ramayana-3-41-17', 'en', 'This divine deer will cause wonder for Bharata, for you, for my mothers-in-law and for me, lord.', 'veda-app-ai-draft', true),
('ramayana-3-41-18', 'en', 'If this finest of deer cannot be caught alive, its skin will be lovely for me, tiger among men.', 'veda-app-ai-draft', true),
('ramayana-3-41-19', 'en', 'I would like to sit on its golden skin spread on a bed of grass when the creature is killed.', 'veda-app-ai-draft', true),
('ramayana-3-41-20', 'en', 'This wilful wish is harsh and thought unbecoming for women; but this creature''s body has filled me with wonder.''', 'veda-app-ai-draft', true),
('ramayana-3-41-21', 'en', 'By that deer with golden hair, horns of the finest gems, the colour of the young sun and the brilliance of the starry path, even Rama''s mind was filled with wonder.', 'veda-app-ai-draft', true),
('ramayana-3-41-22', 'en', 'Hearing Sita''s words and seeing the wonderful deer, Rama, delighted, said to his brother Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-41-23', 'en', '''See, Lakshmana, Sita''s longing for this deer. Because of its surpassing beauty this deer will not live today.', 'veda-app-ai-draft', true),
('ramayana-3-41-24', 'en', 'Not in the Nandana grove nor in Chaitraratha, much less on earth, Lakshmana, is there any deer equal to this one.', 'veda-app-ai-draft', true),
('ramayana-3-41-25', 'en', 'Its lovely rows of hair, lying against and with the grain, shine on the deer, patterned with drops of gold.', 'veda-app-ai-draft', true),
('ramayana-3-41-26', 'en', 'See, as it yawns, its blazing tongue like a flame comes out of its mouth, like lightning from a cloud.', 'veda-app-ai-draft', true),
('ramayana-3-41-27', 'en', 'Its mouth of emerald and crystal, its belly like conch and pearl, whose mind would this indescribable deer not tempt?', 'veda-app-ai-draft', true),
('ramayana-3-41-28', 'en', 'Whose mind would not be filled with wonder, seeing this divine form, made of many jewels and shining like gold?', 'veda-app-ai-draft', true),
('ramayana-3-41-29', 'en', 'Kings who are archers kill deer while hunting in the great forest, for meat and for sport, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-41-30', 'en', 'By effort, riches are gathered in the great forest, and many kinds of minerals with gems, jewels and gold.', 'veda-app-ai-draft', true),
('ramayana-3-41-31', 'en', 'All that is the whole essence of men''s wealth, increasing their store, like all that Shukra thinks of in his mind, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-41-32', 'en', 'The object for which a seeker goes without hesitation, experts in the science of wealth call that wealth, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-41-33', 'en', 'Slender-waisted Sita will sit with me on the precious golden skin of this jewel among deer.', 'veda-app-ai-draft', true),
('ramayana-3-41-34', 'en', 'Neither kadali, priyaki, praveni nor aviki hide would equal it in softness, I think.', 'veda-app-ai-draft', true),
('ramayana-3-41-35', 'en', 'This splendid deer and the divine one that moves in the sky, both are divine deer: the star-deer and the earth-deer.', 'veda-app-ai-draft', true),
('ramayana-3-41-36', 'en', 'Or if it is as you say, Lakshmana, an illusion of the demon, then I must kill it.', 'veda-app-ai-draft', true),
('ramayana-3-41-37', 'en', 'For this cruel Maricha, of unformed soul, roaming the forest before, has harmed the best of sages.', 'veda-app-ai-draft', true),
('ramayana-3-41-38', 'en', 'He has risen up and killed many kings, great archers, while they hunted; so this deer must be killed.', 'veda-app-ai-draft', true),
('ramayana-3-41-39', 'en', 'Here before, Vatapi, despising ascetics, killed brahmins from inside their bellies, as its own foetus kills a mule.', 'veda-app-ai-draft', true),
('ramayana-3-41-40', 'en', 'After a long time he came upon the mighty great sage Agastya in the world and became his food.', 'veda-app-ai-draft', true),
('ramayana-3-41-41', 'en', 'Seeing him wanting to resume his form as he rose, the holy one smiled and said to Vatapi:', 'veda-app-ai-draft', true),
('ramayana-3-41-42', 'en', '"Vatapi, because you heedlessly overpowered the best of brahmins in the world with your power, you are now digested."', 'veda-app-ai-draft', true),
('ramayana-3-41-43', 'en', 'So, Lakshmana, that demon would not survive, like Vatapi, who despises one like me, always devoted to dharma and master of his senses.', 'veda-app-ai-draft', true),
('ramayana-3-41-44', 'en', 'He will be killed, as Vatapi by Agastya. You stay here armed and alert, and guard Sita.', 'veda-app-ai-draft', true),
('ramayana-3-41-45', 'en', 'All that we have to do depends on her, Lakshmana. I will kill this deer or catch it.', 'veda-app-ai-draft', true),
('ramayana-3-41-46', 'en', 'While I go quickly to bring the deer, Lakshmana, see how Sita longs for its skin.', 'veda-app-ai-draft', true),
('ramayana-3-41-47', 'en', 'Because of its superb skin, this deer will not live today. You must stay watchful at the hermitage with Sita', 'veda-app-ai-draft', true),
('ramayana-3-41-48', 'en', 'until I kill the spotted deer with a single arrow. Having killed it, I will take the skin and come back quickly, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-41-49', 'en', 'With the wise, very strong bird Jatayu, Lakshmana, be watchful; take charge of Sita, suspicious every moment on every side.''', 'veda-app-ai-draft', true),
('ramayana-3-42-1', 'en', 'Having instructed his brother thus, mighty Rama, delight of the Raghus, bound on his sword with its gold hilt.', 'veda-app-ai-draft', true),
('ramayana-3-42-2', 'en', 'Then, taking his bow, bent in three places, his own ornament, and binding on two quivers, he went with lofty stride.', 'veda-app-ai-draft', true),
('ramayana-3-42-3', 'en', 'Seeing the king of kings rushing at him, the deer, deceiving him, vanished in fear and then appeared again.', 'veda-app-ai-draft', true),
('ramayana-3-42-4', 'en', 'With his sword bound on, he took his bow and ran to where the deer was; he saw it ahead, as if shining with its beauty.', 'veda-app-ai-draft', true),
('ramayana-3-42-5', 'en', 'Looking again and again at it running in the great forest, bow in hand, he saw it sometimes beyond arrow''s range, tempting him.', 'veda-app-ai-draft', true),
('ramayana-3-42-6', 'en', 'Wary and darting, as if leaping into the sky, it was seen and then unseen in various new places.', 'veda-app-ai-draft', true),
('ramayana-3-42-7', 'en', 'Like the autumn moon veiled by scattered clouds, it was seen for a moment and then shone again from far off.', 'veda-app-ai-draft', true),
('ramayana-3-42-8', 'en', 'By appearing and disappearing it drew Rama away; Rama grew angry, helpless and bewildered by it.', 'veda-app-ai-draft', true),
('ramayana-3-42-9', 'en', 'Then it stood still, as if very tired, in the shade on a grassy spot, surrounded by wild deer, seen not far off.', 'veda-app-ai-draft', true),
('ramayana-3-42-10', 'en', 'Seeing it, mighty Rama, resolved to kill it, fitted an arrow to his strong bow and drew it powerfully,', 'veda-app-ai-draft', true),
('ramayana-3-42-11', 'en', 'and aiming at that deer, he released a blazing, bright arrow made with Brahma''s weapon, like a flaming serpent.', 'veda-app-ai-draft', true),
('ramayana-3-42-12', 'en', 'That excellent arrow, like a thunderbolt, tore through the deer form and pierced the heart of Maricha himself.', 'veda-app-ai-draft', true),
('ramayana-3-42-13', 'en', 'Leaping up a palm tree''s height, struck by the arrow, he fell; nearly dead on the ground he let out a terrible cry, and dying, Maricha gave up that false body.', 'veda-app-ai-draft', true),
('ramayana-3-42-14', 'en', 'Knowing his time had come, he cried out in a voice just like Rama''s: ''Ah Sita! Ah Lakshmana!''', 'veda-app-ai-draft', true),
('ramayana-3-42-15', 'en', 'Pierced in a vital spot by that peerless arrow, Maricha left the deer form, took his own huge demon form and gave up his life.', 'veda-app-ai-draft', true),
('ramayana-3-42-16', 'en', 'Struck by the arrow, he became a demon with colourful armlets and every ornament, a golden garland and great fangs.', 'veda-app-ai-draft', true),
('ramayana-3-42-17', 'en', 'Seeing the terrible demon fallen on the ground, Rama''s mind went to Sita, remembering Lakshmana''s words.', 'veda-app-ai-draft', true),
('ramayana-3-42-18', 'en', '''This demon died crying out loudly "Ah Sita! Ah Lakshmana!"; how will Sita be when she hears it?', 'veda-app-ai-draft', true),
('ramayana-3-42-19', 'en', 'And what state will mighty-armed Lakshmana be in?'' Thinking thus, the righteous Rama''s hair stood on end.', 'veda-app-ai-draft', true),
('ramayana-3-42-20', 'en', 'Then a sharp fear born of despair entered Rama, having killed the demon in deer form and heard that cry.', 'veda-app-ai-draft', true),
('ramayana-3-42-21', 'en', 'Killing another spotted deer and taking the meat, Rama hurried back toward Janasthana.', 'veda-app-ai-draft', true),
('ramayana-3-43-1', 'en', 'Recognising in the forest the cry of distress like her husband''s, Sita said to Lakshmana, ''Go and find out about Rama.', 'veda-app-ai-draft', true),
('ramayana-3-43-2', 'en', 'My life and heart are not steady, for I heard loudly the cry of one in great distress calling out.', 'veda-app-ai-draft', true),
('ramayana-3-43-3', 'en', 'You must save your brother crying out in the forest. Run to him quickly; he is seeking help,', 'veda-app-ai-draft', true),
('ramayana-3-43-4', 'en', 'fallen into the power of demons, like a bull among lions.'' Though told this, he did not go, remembering his brother''s command.', 'veda-app-ai-draft', true),
('ramayana-3-43-5', 'en', 'Then Janaka''s daughter, angry, said to him: ''Lakshmana, in the guise of a friend you are like an enemy to your brother,', 'veda-app-ai-draft', true),
('ramayana-3-43-6', 'en', 'since in this state you do not go to your brother. You want Rama to perish for my sake, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-43-7', 'en', 'I think his misfortune pleases you; you have no love for your brother. That is why you stand here at ease without seeing that radiant one.', 'veda-app-ai-draft', true),
('ramayana-3-43-8', 'en', 'What use is it for me to be here, when he whom you came to serve is in danger?''', 'veda-app-ai-draft', true),
('ramayana-3-43-9', 'en', 'As Sita spoke, flooded with tears and grief, frightened like a doe, Lakshmana said to her:', 'veda-app-ai-draft', true),
('ramayana-3-43-10', 'en', '''Queen, among gods and men, gandharvas and birds, demons, pishachas, kinnaras and beasts,', 'veda-app-ai-draft', true),
('ramayana-3-43-11', 'en', 'and terrible danavas, there is none, lovely one, who could fight Rama, equal of Indra, in battle.', 'veda-app-ai-draft', true),
('ramayana-3-43-12', 'en', 'Rama cannot be killed in battle; you should not speak like this. I dare not leave you in this forest without Rama.', 'veda-app-ai-draft', true),
('ramayana-3-43-13', 'en', 'His strength cannot be resisted even by the mightiest, even by the three worlds united with their lords and the gods.', 'veda-app-ai-draft', true),
('ramayana-3-43-14', 'en', 'Let your heart be at peace and give up this anguish; your husband will come back soon having killed that fine deer.', 'veda-app-ai-draft', true),
('ramayana-3-43-15', 'en', 'That was clearly not his voice, nor any god''s; it is that demon''s illusion, like a mirage city.', 'veda-app-ai-draft', true),
('ramayana-3-43-16', 'en', 'You were entrusted to me as a deposit by great Rama, lovely one; I dare not leave you here.', 'veda-app-ai-draft', true),
('ramayana-3-43-17', 'en', 'And we have made enemies of these night-roamers, gracious one, because of Khara''s death and the slaughter at Janasthana.', 'veda-app-ai-draft', true),
('ramayana-3-43-18', 'en', 'Demons in the great forest make many kinds of sounds; they delight in violence. Do not worry about it, Sita.''', 'veda-app-ai-draft', true),
('ramayana-3-43-19', 'en', 'Thus addressed by Lakshmana, angry, her eyes red, she spoke harsh words to truthful Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-43-20', 'en', '''Ignoble, cruel, merciless, disgrace to your family! I think you speak like this because you want me.', 'veda-app-ai-draft', true),
('ramayana-3-43-21', 'en', 'It is no wonder, Lakshmana, that such evil exists in rivals like you, cruel and always acting in secret.', 'veda-app-ai-draft', true),
('ramayana-3-43-22', 'en', 'Very wicked, you alone have followed Rama alone into the forest, secretly for my sake, or sent by Bharata.', 'veda-app-ai-draft', true),
('ramayana-3-43-23', 'en', 'How could I, having taken refuge with my husband Rama, dark as a blue lotus and lotus-eyed, desire some other man?', 'veda-app-ai-draft', true),
('ramayana-3-43-24', 'en', 'Without doubt I will give up my life before your eyes, Lakshmana; I cannot live a moment on earth without Rama.''', 'veda-app-ai-draft', true),
('ramayana-3-43-25', 'en', 'Thus addressed with harsh, hair-raising words by Sita, Lakshmana, master of his senses, with joined palms, said to Sita:', 'veda-app-ai-draft', true),
('ramayana-3-43-26', 'en', '''I dare not answer; you are a deity to me. Unfitting words are not surprising in women, Sita.', 'veda-app-ai-draft', true),
('ramayana-3-43-27', 'en', 'This is the nature of women seen in the worlds: women abandon dharma, are fickle, sharp and cause division.', 'veda-app-ai-draft', true),
('ramayana-3-43-28', 'en', 'Let all the forest-dwellers hear me as witnesses, how harsh words were spoken to me, who spoke what is right.', 'veda-app-ai-draft', true),
('ramayana-3-43-29', 'en', 'Shame on you; may you perish, since you suspect me so, who stand by my elder''s command, because of a woman''s bad nature.', 'veda-app-ai-draft', true),
('ramayana-3-43-30', 'en', 'I will go where Rama is. May all be well with you, lovely one; may all the forest deities protect you, large-eyed one.', 'veda-app-ai-draft', true),
('ramayana-3-43-31', 'en', 'For terrible omens are appearing to me; may I see you again with Rama when I return.''', 'veda-app-ai-draft', true),
('ramayana-3-43-32', 'en', 'Thus addressed by Lakshmana, Janaka''s daughter, weeping, flooded with tears, replied sharply:', 'veda-app-ai-draft', true),
('ramayana-3-43-33', 'en', '''Without Rama, Lakshmana, I will enter the Godavari, or hang myself, or throw my body off a cliff,', 'veda-app-ai-draft', true),
('ramayana-3-43-34', 'en', 'or drink sharp poison, or enter fire; but I will never touch any man but Rama, even with my foot.''', 'veda-app-ai-draft', true),
('ramayana-3-43-35', 'en', 'Having cried out at Lakshmana, Sita, full of grief, weeping, struck her belly with her hands in sorrow.', 'veda-app-ai-draft', true),
('ramayana-3-43-36', 'en', 'Seeing her in distress, weeping, large-eyed, Lakshmana, troubled, tried to comfort her; but Sita said nothing to her husband''s brother.', 'veda-app-ai-draft', true),
('ramayana-3-43-37', 'en', 'Then Lakshmana, with joined palms, bowed a little to Sita and, looking back at her many times, went toward Rama, self-controlled.', 'veda-app-ai-draft', true),
('ramayana-3-44-1', 'en', 'Spoken to harshly by her and angry, Rama''s younger brother, longing to see Rama, set out at once.', 'veda-app-ai-draft', true),
('ramayana-3-44-2', 'en', 'Ten-necked Ravana, seizing the opportunity, quickly came near Sita in the form of a wandering ascetic.', 'veda-app-ai-draft', true),
('ramayana-3-44-3', 'en', 'Wearing smooth ochre robes, with topknot, parasol and sandals, a staff and water pot hung on his left shoulder, in the guise of a wandering ascetic he approached Sita.', 'veda-app-ai-draft', true),
('ramayana-3-44-4', 'en', 'The very mighty one came upon her alone in the forest without the brothers, like great darkness upon twilight without sun and moon.', 'veda-app-ai-draft', true),
('ramayana-3-44-5', 'en', 'He saw the young, famous princess like Rohini without the moon, like a very dreadful planet.', 'veda-app-ai-draft', true),
('ramayana-3-44-6', 'en', 'Seeing that fierce evil-doer, the trees of Janasthana did not stir and the wind did not blow.', 'veda-app-ai-draft', true),
('ramayana-3-44-7', 'en', 'Seeing him look with red eyes, the swift-flowing Godavari began to flow sluggishly out of fear.', 'veda-app-ai-draft', true),
('ramayana-3-44-8', 'en', 'Seeking his chance in Rama''s absence, Ravana approached Sita in the form of a mendicant.', 'veda-app-ai-draft', true),
('ramayana-3-44-9', 'en', 'The unworthy one in a worthy form approached Sita as she grieved for her husband, as Saturn approaches the star Chitra.', 'veda-app-ai-draft', true),
('ramayana-3-44-10', 'en', 'That sinner in a good form, like a well covered with grass, stood looking at Sita, Rama''s famous wife,', 'veda-app-ai-draft', true),
('ramayana-3-44-11', 'en', 'lovely, with fine teeth and lips, face like the full moon, sitting in the leaf hut oppressed by tears and grief.', 'veda-app-ai-draft', true),
('ramayana-3-44-12', 'en', 'The wicked-minded night-roamer approached Sita, lotus-eyed, dressed in yellow silk.', 'veda-app-ai-draft', true),
('ramayana-3-44-13', 'en', 'Pierced by love''s arrows, chanting Vedic recitation, the lord of demons spoke courteously to her in that lonely place.', 'veda-app-ai-draft', true),
('ramayana-3-44-14', 'en', 'Ravana praised her, the best in the three worlds, like Shri without her lotus, shining with her beauty.', 'veda-app-ai-draft', true),
('ramayana-3-44-15', 'en', '''Who are you, golden one in yellow silk, wearing a lovely lotus garland like a lotus pond?', 'veda-app-ai-draft', true),
('ramayana-3-44-16', 'en', 'Are you Modesty, Fortune, Fame, auspicious Lakshmi, or an apsara, lovely-faced one? Are you Prosperity, or Rati wandering at will?', 'veda-app-ai-draft', true),
('ramayana-3-44-17', 'en', 'Your teeth are even, pointed, glossy and white; your eyes are large and clear, red-cornered with dark pupils.', 'veda-app-ai-draft', true),
('ramayana-3-44-18', 'en', 'Your form is full and graceful.', 'veda-app-ai-draft', true),
('ramayana-3-44-19', 'en', 'You are adorned with fine jewels and lovely.', 'veda-app-ai-draft', true),
('ramayana-3-44-20', 'en', 'Lovely-smiling, lovely-toothed, lovely-eyed, graceful lady, you steal my heart as a river''s water steals its bank.', 'veda-app-ai-draft', true),
('ramayana-3-44-21', 'en', 'Slender-waisted, lovely-haired, neither goddess, gandharvi, yakshi nor kinnari', 'veda-app-ai-draft', true),
('ramayana-3-44-22', 'en', 'have I seen on earth such a woman before. Your living here in the wilderness unsettles my mind.', 'veda-app-ai-draft', true),
('ramayana-3-44-23', 'en', 'Turn back, bless you; you should not live here. This is the home of terrible shape-shifting demons.', 'veda-app-ai-draft', true),
('ramayana-3-44-24', 'en', 'Fine palaces, lovely city gardens, rich and fragrant, are fit for you to roam.', 'veda-app-ai-draft', true),
('ramayana-3-44-25', 'en', 'The best garland, the best drink, the best clothes, lovely one, and the best husband, I think, are fit for you, dark-eyed one.', 'veda-app-ai-draft', true),
('ramayana-3-44-26', 'en', 'Who are you, bright-smiling one, of the Rudras, Maruts or Vasus? You seem to me a goddess.', 'veda-app-ai-draft', true),
('ramayana-3-44-27', 'en', 'Neither gandharvas, gods nor kinnaras come here; this is the home of demons. How have you come here?', 'veda-app-ai-draft', true),
('ramayana-3-44-28', 'en', 'Here are monkeys, lions, leopards, tigers, bears, hyenas and herons; how are you not afraid of them?', 'veda-app-ai-draft', true),
('ramayana-3-44-29', 'en', 'How do you not fear, alone in the great forest, the terrible, strong, rutting elephants, lovely one?', 'veda-app-ai-draft', true),
('ramayana-3-44-30', 'en', 'Who are you, whose are you, where are you from, and why do you roam alone in the Dandaka, haunted by terrible demons, gracious one?''', 'veda-app-ai-draft', true),
('ramayana-3-44-31', 'en', 'Praised thus by wicked Ravana, Sita, seeing Ravana come in the dress of a brahmin, honoured him with all the courtesies due to a guest.', 'veda-app-ai-draft', true),
('ramayana-3-44-32', 'en', 'First bringing a seat and inviting him with water for his feet, she said to the gentle-looking one, ''Food is ready.''', 'veda-app-ai-draft', true),
('ramayana-3-44-33', 'en', 'Seeing him come in a brahmin''s dress with bowl and ochre cloth, Sita, seeing no way to refuse, invited him as one would a brahmin.', 'veda-app-ai-draft', true),
('ramayana-3-44-34', 'en', '''Here is a mat, brahmin, sit as you wish; take this water for your feet; and here is fine forest food prepared for you; enjoy it at ease.''', 'veda-app-ai-draft', true),
('ramayana-3-44-35', 'en', 'Invited by the king''s wife, who spoke so courteously, Ravana looked at Sita, laughed, and set his mind on carrying her off, which would bring his own death.', 'veda-app-ai-draft', true),
('ramayana-3-44-36', 'en', 'Then, waiting for her well-dressed husband gone hunting, and for Lakshmana, she looked out and saw the great green forest, but not Rama and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-45-1', 'en', 'Questioned by Ravana in the form of a wandering ascetic, who wished to carry her off, Sita told him about herself.', 'veda-app-ai-draft', true),
('ramayana-3-45-2', 'en', '''He is a brahmin and a guest; if I do not answer he might curse me.'' Thinking this for a moment, Sita spoke:', 'veda-app-ai-draft', true),
('ramayana-3-45-3', 'en', '''I am the daughter of the great Janaka of Mithila; my name is Sita, bless you, and I am Rama''s wife, best of brahmins.', 'veda-app-ai-draft', true),
('ramayana-3-45-4', 'en', 'For a year I lived in Rama''s home, enjoying human comforts and having all I wished.', 'veda-app-ai-draft', true),
('ramayana-3-45-5', 'en', 'After that year, my husband''s father, with the royal ministers, decided to consecrate Rama as king.', 'veda-app-ai-draft', true),
('ramayana-3-45-6', 'en', 'While Rama''s consecration was being prepared, a queen named Kaikeyi asked her husband for a boon.', 'veda-app-ai-draft', true),
('ramayana-3-45-7', 'en', 'Having bound my father-in-law by an earlier good deed, Kaikeyi asked the truthful best of kings for two things: my husband''s exile and Bharata''s consecration.', 'veda-app-ai-draft', true),
('ramayana-3-45-8', 'en', '"I will not eat, sleep or drink ever again; this will be the end of my life if Rama is consecrated."', 'veda-app-ai-draft', true),
('ramayana-3-45-9', 'en', 'As Kaikeyi spoke, my father-in-law, giver of honour, begged her with fitting offers, but she would not grant his plea.', 'veda-app-ai-draft', true),
('ramayana-3-45-10', 'en', 'My husband, mighty, twenty-five years old, famed in the world as Rama, virtuous, truthful, pure, large-eyed, mighty-armed, devoted to the good of all beings,', 'veda-app-ai-draft', true),
('ramayana-3-45-11', 'en', 'came to his father for the consecration, and Kaikeyi quickly said to my husband:', 'veda-app-ai-draft', true),
('ramayana-3-45-12', 'en', '"Hear from me, Rama, what your father has commanded: this kingdom must be given to Bharata without obstacle.', 'veda-app-ai-draft', true),
('ramayana-3-45-13', 'en', 'And you must live in the forest for fourteen years. Go into the forest, Rama, and free your father from untruth."', 'veda-app-ai-draft', true),
('ramayana-3-45-14', 'en', 'Rama, fearless, said ''So be it'' to Kaikeyi, and my husband, firm in his vow, did as she said.', 'veda-app-ai-draft', true),
('ramayana-3-45-15', 'en', 'He would give but not take; he would speak truth and never falsehood: this, brahmin, is Rama''s firm and supreme vow.', 'veda-app-ai-draft', true),
('ramayana-3-45-16', 'en', 'His half-brother is the valiant Lakshmana, tiger among men, Rama''s companion in battle and slayer of foes.', 'veda-app-ai-draft', true),
('ramayana-3-45-17', 'en', 'That brother named Lakshmana, following dharma and firm in his vow, followed him bow in hand as he went into exile with me.', 'veda-app-ai-draft', true),
('ramayana-3-45-18', 'en', 'So we three, cast out of the kingdom because of Kaikeyi, wander the deep forest by our own strength, best of brahmins.', 'veda-app-ai-draft', true),
('ramayana-3-45-19', 'en', 'Rest a moment; you can stay here. My husband will come bringing plenty of forest food.', 'veda-app-ai-draft', true),
('ramayana-3-45-20', 'en', 'Now tell me truly your name, your lineage and your family, and why you wander alone in the Dandaka forest, brahmin.''', 'veda-app-ai-draft', true),
('ramayana-3-45-21', 'en', 'As Sita, Rama''s wife, spoke thus, mighty Ravana, lord of demons, gave a harsh reply:', 'veda-app-ai-draft', true),
('ramayana-3-45-22', 'en', '''I am he by whom the worlds, with gods, demons and serpents, are terrified: I am Ravana, Sita, lord of the hosts of demons.', 'veda-app-ai-draft', true),
('ramayana-3-45-23', 'en', 'Seeing you, golden-skinned, in silk, I no longer find delight in my own wives, faultless one.', 'veda-app-ai-draft', true),
('ramayana-3-45-24', 'en', 'Of the many fine women brought from here and there, be the chief queen of them all, bless you.', 'veda-app-ai-draft', true),
('ramayana-3-45-25', 'en', 'My great city named Lanka is in the middle of the sea, surrounded by ocean and built on a mountain top.', 'veda-app-ai-draft', true),
('ramayana-3-45-26', 'en', 'There, Sita, you will roam its gardens with me, and you will not long for this forest life, lovely one.', 'veda-app-ai-draft', true),
('ramayana-3-45-27', 'en', 'Five thousand maidservants adorned with every ornament will serve you, Sita, if you become my wife.''', 'veda-app-ai-draft', true),
('ramayana-3-45-28', 'en', 'Thus addressed by Ravana, flawless Sita, angry, answered the demon with contempt:', 'veda-app-ai-draft', true),
('ramayana-3-45-29', 'en', '''I am devoted to Rama, unshakeable like a great mountain, like great Indra, imperturbable like the great ocean.', 'veda-app-ai-draft', true),
('ramayana-3-45-30', 'en', 'I am devoted to Rama, mighty-armed, broad-chested, walking with a lion''s stride, a lion among men, like a lion.', 'veda-app-ai-draft', true),
('ramayana-3-45-31', 'en', 'I am devoted to Rama, moon-faced, heroic, beloved prince, master of his senses, of wide fame, mighty-armed.', 'veda-app-ai-draft', true),
('ramayana-3-45-32', 'en', 'And you, a jackal, want me, a lioness, hard to win. You cannot touch me, as one cannot touch the light of the sun.', 'veda-app-ai-draft', true),
('ramayana-3-45-33', 'en', 'Unlucky one, you must surely be seeing many golden trees, since you desire Rama''s beloved wife, Ravana.', 'veda-app-ai-draft', true),
('ramayana-3-45-34', 'en', 'You want to take a fang from the mouth of a hungry, swift lion, enemy of deer, or of a venomous snake.', 'veda-app-ai-draft', true),
('ramayana-3-45-35', 'en', 'You want to carry off Mandara, best of mountains, with your hand, or drink kalakuta poison and go away safe.', 'veda-app-ai-draft', true),
('ramayana-3-45-36', 'en', 'You rub your eye with a needle and lick a razor with your tongue, you who want to take Rama''s beloved wife.', 'veda-app-ai-draft', true),
('ramayana-3-45-37', 'en', 'You want to cross the ocean with a stone tied round your neck, and seize both sun and moon with your hands, you who want to assault Rama''s beloved wife.', 'veda-app-ai-draft', true),
('ramayana-3-45-38', 'en', 'Seeing a blazing fire, you want to carry it in a cloth, you who want to carry off Rama''s virtuous wife.', 'veda-app-ai-draft', true),
('ramayana-3-45-39', 'en', 'You want to walk on the tips of iron spears, you who want to take a wife worthy of Rama.', 'veda-app-ai-draft', true),
('ramayana-3-45-40', 'en', 'The difference between a lion and a jackal in the forest, between a stream and the ocean, between fine wine and sour gruel: that is the difference between Rama and you.', 'veda-app-ai-draft', true),
('ramayana-3-45-41', 'en', 'The difference between gold and lead, between sandal water and mud, between an elephant and a cat in the forest: that is the difference between Rama and you.', 'veda-app-ai-draft', true),
('ramayana-3-45-42', 'en', 'The difference between a crow and Garuda, between a cormorant and a peacock, between a crane and a vulture in the forest: that is the difference between Rama and you.', 'veda-app-ai-draft', true),
('ramayana-3-45-43', 'en', 'While Rama, equal in might to thousand-eyed Indra, stands with bow and arrows in hand, even if you carry me off you will not digest me, as a fly cannot digest a diamond it swallows.', 'veda-app-ai-draft', true),
('ramayana-3-45-44', 'en', 'Having spoken these well-considered words to the night-roamer, pure-hearted Sita trembled in body and was distressed, like a slender plantain shaken by wind.', 'veda-app-ai-draft', true),
('ramayana-3-45-45', 'en', 'Seeing Sita trembling, Ravana, like Death in power, told of his own family, strength, name and deeds to make her afraid.', 'veda-app-ai-draft', true),
('ramayana-3-46-1', 'en', 'As Sita spoke thus, Ravana, enraged, knitting his brows, replied with harsh words:', 'veda-app-ai-draft', true),
('ramayana-3-46-2', 'en', '''I am the half-brother of Kubera, lovely one; I am Ravana, the mighty ten-necked one, bless you,', 'veda-app-ai-draft', true),
('ramayana-3-46-3', 'en', 'from whom gods, gandharvas, pishachas, birds and serpents flee in fear, as creatures always flee from death,', 'veda-app-ai-draft', true),
('ramayana-3-46-4', 'en', 'by whom my half-brother Kubera, for some cause, was challenged to a duel in anger and defeated in battle.', 'veda-app-ai-draft', true),
('ramayana-3-46-5', 'en', 'Afflicted by fear of me, Kubera left his rich capital and now lives on Kailasa, best of mountains.', 'veda-app-ai-draft', true),
('ramayana-3-46-6', 'en', 'His lovely wish-going chariot named Pushpaka I won by valour, lady, and in it I travel through the sky.', 'veda-app-ai-draft', true),
('ramayana-3-46-7', 'en', 'Seeing my face when I am angry, Sita, the gods led by Indra flee in terror.', 'veda-app-ai-draft', true),
('ramayana-3-46-8', 'en', 'Where I stand, the wind blows nervously, and the sun''s fierce rays turn cool out of fear.', 'veda-app-ai-draft', true),
('ramayana-3-46-9', 'en', 'Wherever I stand or walk, the leaves of trees do not stir and the waters of rivers grow still.', 'veda-app-ai-draft', true),
('ramayana-3-46-10', 'en', 'Across the sea is my lovely city named Lanka, full of terrible demons, like Indra''s Amaravati.', 'veda-app-ai-draft', true),
('ramayana-3-46-11', 'en', 'It is surrounded by a gleaming white wall, a lovely city with golden chambers and gateways of beryl,', 'veda-app-ai-draft', true),
('ramayana-3-46-12', 'en', 'crowded with elephants, horses and chariots, echoing with music, adorned with gardens full of trees that grant every wish.', 'veda-app-ai-draft', true),
('ramayana-3-46-13', 'en', 'Living there with me, princess Sita, proud one, you will not remember human women.', 'veda-app-ai-draft', true),
('ramayana-3-46-14', 'en', 'Enjoying human and divine pleasures, lovely one, you will not remember Rama, a mortal whose life is over.', 'veda-app-ai-draft', true),
('ramayana-3-46-15', 'en', 'He is the weak eldest son whom King Dasharatha sent away to the forest after installing his beloved son.', 'veda-app-ai-draft', true),
('ramayana-3-46-16', 'en', 'What will you do with that Rama, fallen from the kingdom, out of his mind, a wretched ascetic, large-eyed one?', 'veda-app-ai-draft', true),
('ramayana-3-46-17', 'en', 'You should not refuse the lord of all demons, who has come here himself out of desire, pierced by love''s arrows.', 'veda-app-ai-draft', true),
('ramayana-3-46-18', 'en', 'For if you refuse me, timid one, you will suffer remorse, as Urvashi did after kicking Pururavas.''', 'veda-app-ai-draft', true),
('ramayana-3-46-19', 'en', 'Thus addressed, Sita, angry, her eyes red, spoke harsh words to the lord of demons in that lonely place:', 'veda-app-ai-draft', true),
('ramayana-3-46-20', 'en', '''How, naming as your brother the god Kubera, honoured by all beings, can you wish to do evil?', 'veda-app-ai-draft', true),
('ramayana-3-46-21', 'en', 'All the demons will surely perish, Ravana, whose king is you, harsh, foolish and without self-control.', 'veda-app-ai-draft', true),
('ramayana-3-46-22', 'en', 'One might carry off Indra''s wife Shachi and live, but having carried me, Rama''s wife, away there is no living.', 'veda-app-ai-draft', true),
('ramayana-3-46-23', 'en', 'One might live long after violating peerless Shachi from the hand of the thunderbolt-bearer, but having violated one like me, demon, there is no escape for you even if you have drunk nectar.''', 'veda-app-ai-draft', true),
('ramayana-3-47-1', 'en', 'Hearing Sita''s words, mighty ten-necked Ravana struck hand against hand and took on a huge form.', 'veda-app-ai-draft', true),
('ramayana-3-47-2', 'en', 'He spoke again forcefully to Sita: ''I think you are mad, not to have heard of my valour and might.', 'veda-app-ai-draft', true),
('ramayana-3-47-3', 'en', 'Standing in the sky I could lift the earth with my arms; I could drink the ocean and kill Death standing in battle.', 'veda-app-ai-draft', true),
('ramayana-3-47-4', 'en', 'I could block the sun with sharp arrows and split the earth. See me, mad one, who takes any form, a husband who grants every wish.''', 'veda-app-ai-draft', true),
('ramayana-3-47-5', 'en', 'As Ravana spoke thus in anger, his eyes, bright as flame, became red with tawny edges.', 'veda-app-ai-draft', true),
('ramayana-3-47-6', 'en', 'At once giving up the gentle mendicant form, Kubera''s younger brother took his own form, like Death.', 'veda-app-ai-draft', true),
('ramayana-3-47-7', 'en', 'Red-eyed, glorious, with earrings of refined gold, ten-faced, with bow and arrows, the night-roamer appeared.', 'veda-app-ai-draft', true),
('ramayana-3-47-8', 'en', 'Throwing off the disguise of a wandering ascetic, the huge Ravana, lord of demons, took his own form.', 'veda-app-ai-draft', true),
('ramayana-3-47-9', 'en', 'Red-eyed with anger, dark as a mass of clouds, wearing red clothes, he stood looking at Sita, a jewel among women.', 'veda-app-ai-draft', true),
('ramayana-3-47-10', 'en', 'Ravana said to Sita, black-haired, like sunlight, with her clothes and ornaments:', 'veda-app-ai-draft', true),
('ramayana-3-47-11', 'en', '''If you want a husband famed in the three worlds, take refuge in me, lovely one; I am a husband fit for you.', 'veda-app-ai-draft', true),
('ramayana-3-47-12', 'en', 'Love me for ever; I am your praiseworthy beloved. I will never do anything to displease you, gracious one. Give up your feeling for a human and set your heart on me.', 'veda-app-ai-draft', true),
('ramayana-3-47-13', 'en', 'What virtues make you devoted to Rama, fallen from the kingdom, his aims unfulfilled, his life limited, foolish one who thinks herself wise?', 'veda-app-ai-draft', true),
('ramayana-3-47-14', 'en', 'The fool who at a woman''s word left his kingdom and friends and lives in this forest haunted by beasts?''', 'veda-app-ai-draft', true),
('ramayana-3-47-15', 'en', 'Having said this to Sita, who deserved kindness and spoke kindly, Ravana seized her, like Budha seizing Rohini in the sky.', 'veda-app-ai-draft', true),
('ramayana-3-47-16', 'en', 'With his left hand he grabbed lotus-eyed Sita by her hair, and with his right he caught her by the legs.', 'veda-app-ai-draft', true),
('ramayana-3-47-17', 'en', 'Seeing him like a mountain peak, sharp-fanged, mighty-armed, like Death, the forest deities fled in fear.', 'veda-app-ai-draft', true),
('ramayana-3-47-18', 'en', 'Then Ravana''s great golden chariot, magical and divine, yoked to donkeys and with a harsh rattle, appeared.', 'veda-app-ai-draft', true),
('ramayana-3-47-19', 'en', 'Then, threatening her with harsh words, loud-voiced, he took Sita in his arms and put her in the chariot.', 'veda-app-ai-draft', true),
('ramayana-3-47-20', 'en', 'Seized by Ravana, the famous Sita, in anguish, cried out loudly ''Rama!'' to Rama, who was far away in the forest.', 'veda-app-ai-draft', true),
('ramayana-3-47-21', 'en', 'Holding her, unwilling and writhing like a serpent king''s wife, Ravana, tormented by desire, flew up.', 'veda-app-ai-draft', true),
('ramayana-3-47-22', 'en', 'Carried through the sky by the lord of demons, she cried out loudly, as if mad, distraught and in pain:', 'veda-app-ai-draft', true),
('ramayana-3-47-23', 'en', '''Ah Lakshmana, mighty-armed, who please your elder''s heart, you do not know I am being carried off by a shape-shifting demon!', 'veda-app-ai-draft', true),
('ramayana-3-47-24', 'en', 'Rama, you who gave up life, happiness and wealth for dharma, do not see me being carried off unrighteously.', 'veda-app-ai-draft', true),
('ramayana-3-47-25', 'en', 'You are the punisher of the unruly, scorcher of foes; why do you not punish such an evil one as Ravana?', 'veda-app-ai-draft', true),
('ramayana-3-47-26', 'en', 'Surely the fruit of an unruly deed is seen at once; yet time too plays its part here, as in ripening crops.', 'veda-app-ai-draft', true),
('ramayana-3-47-27', 'en', 'You have done this deed with your mind struck by fate; you will meet a terrible, life-ending disaster from Rama.', 'veda-app-ai-draft', true),
('ramayana-3-47-28', 'en', 'Now Kaikeyi and her kin have their wish, since I, the lawful wife of the famous lover of dharma, am being carried off.', 'veda-app-ai-draft', true),
('ramayana-3-47-29', 'en', 'I call on Janasthana and the flowering karnikara trees: tell Rama quickly that Ravana is carrying off Sita.', 'veda-app-ai-draft', true),
('ramayana-3-47-30', 'en', 'I salute the peaked Malyavan and Mount Prasravana: tell Rama quickly that Ravana is carrying off Sita.', 'veda-app-ai-draft', true),
('ramayana-3-47-31', 'en', 'I salute the Godavari river, echoing with swans and cranes: tell Rama quickly that Ravana is carrying off Sita.', 'veda-app-ai-draft', true),
('ramayana-3-47-32', 'en', 'And to the deities who live in this forest of many trees I bow: tell my husband I have been carried off.', 'veda-app-ai-draft', true),
('ramayana-3-47-33', 'en', 'Whatever creatures live here, I take refuge in all of them, the herds of beasts and birds too.', 'veda-app-ai-draft', true),
('ramayana-3-47-34', 'en', 'Tell my husband that his beloved, dearer to him than life, has been carried off helpless by Ravana.', 'veda-app-ai-draft', true),
('ramayana-3-47-35', 'en', 'Knowing it, the mighty-armed, very strong one will bring me back by his valour, even from the other world, even if Yama himself had taken me.', 'veda-app-ai-draft', true),
('ramayana-3-47-36', 'en', 'Jatayu, you must tell Rama and Lakshmana exactly how I was carried off, all of it.''', 'veda-app-ai-draft', true),
('ramayana-3-48-1', 'en', 'Jatayu, who had been sleeping, heard that cry; he quickly looked at Ravana and saw Sita.', 'veda-app-ai-draft', true),
('ramayana-3-48-2', 'en', 'Then the glorious best of birds, like a mountain peak, sharp-beaked, perched on a tree, spoke auspicious words:', 'veda-app-ai-draft', true),
('ramayana-3-48-3', 'en', '''Ten-necked one, I stand in ancient dharma and rely on truth; I am Jatayu, the mighty king of vultures.', 'veda-app-ai-draft', true),
('ramayana-3-48-4', 'en', 'Rama, son of Dasharatha, is king of the whole world, like great Indra and Varuna, devoted to the good of the worlds.', 'veda-app-ai-draft', true),
('ramayana-3-48-5', 'en', 'This is the lawful, famous wife of that lord of the world, lovely Sita, whom you want to carry off.', 'veda-app-ai-draft', true),
('ramayana-3-48-6', 'en', 'How can a king who stands in dharma touch another''s wife? A king''s wife above all must be protected, mighty one. Turn back your low intent of violating another''s wife.', 'veda-app-ai-draft', true),
('ramayana-3-48-7', 'en', 'A wise man should not do what others would condemn in him; others'' wives must be protected from violation just like one''s own.', 'veda-app-ai-draft', true),
('ramayana-3-48-8', 'en', 'In matters of wealth or pleasure not covered by the scriptures, the cultured follow the king''s dharma, delight of the Paulastyas.', 'veda-app-ai-draft', true),
('ramayana-3-48-9', 'en', 'The king is dharma, desire and the best treasury of riches; dharma, good or evil, flows from the king.', 'veda-app-ai-draft', true),
('ramayana-3-48-10', 'en', 'How, being evil-natured and fickle, best of demons, have you gained power, like a sinner gaining a celestial chariot?', 'veda-app-ai-draft', true),
('ramayana-3-48-11', 'en', 'One''s nature cannot be wiped away; and good fortune does not dwell long in the house of the wicked.', 'veda-app-ai-draft', true),
('ramayana-3-48-12', 'en', 'When righteous, mighty Rama does no wrong in your realm or city, how can you wrong him?', 'veda-app-ai-draft', true),
('ramayana-3-48-13', 'en', 'If Khara, who went to Janasthana because of Shurpanakha, overstepped and was killed by Rama, tireless in deeds,', 'veda-app-ai-draft', true),
('ramayana-3-48-14', 'en', 'tell me truly, what is Rama''s offence, that you will go away having carried off the wife of the lord of the world?', 'veda-app-ai-draft', true),
('ramayana-3-48-15', 'en', 'Release Sita quickly, so that he does not burn you with his terrible fiery gaze, as Indra''s thunderbolt burned Vritra.', 'veda-app-ai-draft', true),
('ramayana-3-48-16', 'en', 'You do not realise you have tied a venomous snake in the hem of your cloth, nor see the noose of Death around your neck.', 'veda-app-ai-draft', true),
('ramayana-3-48-17', 'en', 'One should carry a load that does not crush one, gentle one, and eat food that digests without harm.', 'veda-app-ai-draft', true),
('ramayana-3-48-18', 'en', 'Who would do a deed that brings neither dharma, nor honour, nor fame on earth, but only weariness to the body?', 'veda-app-ai-draft', true),
('ramayana-3-48-19', 'en', 'Sixty thousand years have passed since I was born, Ravana, ruling properly my ancestral kingdom.', 'veda-app-ai-draft', true),
('ramayana-3-48-20', 'en', 'I am old, and you are young, an archer with chariot, armour and arrows; still, you will not go away safely taking Sita.', 'veda-app-ai-draft', true),
('ramayana-3-48-21', 'en', 'You cannot carry Sita off by force while I watch, any more than one can overturn eternal Vedic truth with reasons.', 'veda-app-ai-draft', true),
('ramayana-3-48-22', 'en', 'Fight if you are brave; stand a moment, Ravana. You will lie slain on the ground, as Khara did before.', 'veda-app-ai-draft', true),
('ramayana-3-48-23', 'en', 'Rama in bark clothes, who has often killed daityas and danavas in battle, will soon kill you in battle.', 'veda-app-ai-draft', true),
('ramayana-3-48-24', 'en', 'What can I do, with the princes gone far away? You will soon perish, low one; you are afraid of them, no doubt.', 'veda-app-ai-draft', true),
('ramayana-3-48-25', 'en', 'While I live you will not take this lovely, lotus-eyed Sita, Rama''s beloved queen.', 'veda-app-ai-draft', true),
('ramayana-3-48-26', 'en', 'I must do what pleases great Rama, and Dasharatha, even at the cost of my life.', 'veda-app-ai-draft', true),
('ramayana-3-48-27', 'en', 'Stop, stop, ten-necked one; wait a moment, Ravana. I will give you the hospitality of battle as far as my strength allows, night-roamer, and bring you down from your fine chariot like a fruit from its stalk.''', 'veda-app-ai-draft', true),
('ramayana-3-49-1', 'en', 'Thus properly addressed by Jatayu, all twenty eyes of angry Ravana blazed like fire.', 'veda-app-ai-draft', true),
('ramayana-3-49-2', 'en', 'Red-eyed with rage, with earrings of refined gold, the impatient lord of demons rushed at the king of birds.', 'veda-app-ai-draft', true),
('ramayana-3-49-3', 'en', 'That tumultuous fight between the two in the great forest was like two clouds driven by wind in the sky.', 'veda-app-ai-draft', true),
('ramayana-3-49-4', 'en', 'That fight between the vulture and the demon was wondrous, like two great winged mountains with garlands.', 'veda-app-ai-draft', true),
('ramayana-3-49-5', 'en', 'Then the mighty one showered the king of vultures with very dreadful tubular, iron, sharp-pointed and barbed arrows.', 'veda-app-ai-draft', true),
('ramayana-3-49-6', 'en', 'Jatayu, lord of birds, received those nets of arrows, Ravana''s weapons, in battle.', 'veda-app-ai-draft', true),
('ramayana-3-49-7', 'en', 'With his feet and sharp claws the mighty best of birds made many wounds on Ravana''s body.', 'veda-app-ai-draft', true),
('ramayana-3-49-8', 'en', 'Then in anger ten-necked Ravana took ten terrible arrows like Death''s rod, wanting to crush his enemy.', 'veda-app-ai-draft', true),
('ramayana-3-49-9', 'en', 'The mighty one pierced the vulture with those sharp, terrible, straight-flying arrows shot at full draw.', 'veda-app-ai-draft', true),
('ramayana-3-49-10', 'en', 'Seeing Sita in the demon''s chariot with tearful eyes, he ignored those arrows and rushed at the demon.', 'veda-app-ai-draft', true),
('ramayana-3-49-11', 'en', 'Then the mighty lord of birds broke with his feet Ravana''s bow, with its arrow, adorned with pearls and gems.', 'veda-app-ai-draft', true),
('ramayana-3-49-12', 'en', 'And with his wings the mighty lord of birds shook off Ravana''s blazing, fire-like armour.', 'veda-app-ai-draft', true),
('ramayana-3-49-13', 'en', 'The strong one killed in battle his swift goblin-faced donkeys with their golden breastplates.', 'veda-app-ai-draft', true),
('ramayana-3-49-14', 'en', 'He broke the great chariot, with its triple pole, wish-going, fire-bright, patterned with gems and gold, and the parasol like the full moon, with the fans.', 'veda-app-ai-draft', true),
('ramayana-3-49-15', 'en', 'With his bow broken, chariotless, his donkeys and charioteer killed, Ravana fell to the ground holding Sita in his arms.', 'veda-app-ai-draft', true),
('ramayana-3-49-16', 'en', 'Seeing Ravana fallen to the ground, his vehicle broken, all beings honoured the king of vultures, crying ''Well done!''', 'veda-app-ai-draft', true),
('ramayana-3-49-17', 'en', 'But seeing the leader of birds exhausted by old age, Ravana, delighted, rose up again holding Sita.', 'veda-app-ai-draft', true),
('ramayana-3-49-18', 'en', 'As he went off joyfully with Sita on his lap, Jatayu, king of vultures, flew up and said:', 'veda-app-ai-draft', true),
('ramayana-3-49-19', 'en', '''Foolish Ravana, you are carrying off the wife of Rama, whose arrows strike like thunderbolts, surely for the death of the demons.', 'veda-app-ai-draft', true),
('ramayana-3-49-20', 'en', 'With friends, kin, ministers, army and attendants, you are drinking this poison like a thirsty man drinks water.', 'veda-app-ai-draft', true),
('ramayana-3-49-21', 'en', 'The unwise, who do not know the consequences of their deeds, quickly perish, as you will perish.', 'veda-app-ai-draft', true),
('ramayana-3-49-22', 'en', 'You are bound by the noose of Time; where can you go to escape it? Like a fish taking a baited hook to its death.', 'veda-app-ai-draft', true),
('ramayana-3-49-23', 'en', 'The two invincible Raghus will never forgive you this violation of their hermitage, Ravana.', 'veda-app-ai-draft', true),
('ramayana-3-49-24', 'en', 'The deed you have done, coward, is condemned by the world; this is the way of thieves, not of heroes.', 'veda-app-ai-draft', true),
('ramayana-3-49-25', 'en', 'Fight if you are brave; stand a moment, Ravana. You will lie slain on the ground like your brother Khara.', 'veda-app-ai-draft', true),
('ramayana-3-49-26', 'en', 'A man at the time of his death takes up an unrighteous deed; you have taken up this deed for your own ruin.', 'veda-app-ai-draft', true),
('ramayana-3-49-27', 'en', 'What man would do a deed bound up with sin, even if he were lord of the world or the self-born Brahma himself?''', 'veda-app-ai-draft', true),
('ramayana-3-49-28', 'en', 'Having spoken these good words, the valiant Jatayu fell hard upon ten-necked Ravana''s back.', 'veda-app-ai-draft', true),
('ramayana-3-49-29', 'en', 'Seizing him, he tore at him all over with sharp claws, like an elephant rider mounting a wild elephant.', 'veda-app-ai-draft', true),
('ramayana-3-49-30', 'en', 'He tore with his claws, struck his beak into his back and pulled out his hair, using claws, wings and beak as weapons.', 'veda-app-ai-draft', true),
('ramayana-3-49-31', 'en', 'Tormented again and again by the king of vultures, the demon trembled, his lips quivering with rage.', 'veda-app-ai-draft', true),
('ramayana-3-49-32', 'en', 'Holding Sita with his left side, Ravana, in pain and faint with anger, struck Jatayu with his palm.', 'veda-app-ai-draft', true),
('ramayana-3-49-33', 'en', 'Jatayu, the lord of birds, subduer of foes, evaded him and tore off his ten left arms with his beak.', 'veda-app-ai-draft', true),
('ramayana-3-49-34', 'en', 'Then angry ten-necked Ravana let Sita go and pounded the king of vultures with fists and feet.', 'veda-app-ai-draft', true),
('ramayana-3-49-35', 'en', 'Then for a moment there was a battle between the two of matchless might, the chief of demons and the best of birds.', 'veda-app-ai-draft', true),
('ramayana-3-49-36', 'en', 'As he struggled for Rama''s sake, Ravana drew his sword and cut off his wings, feet and sides.', 'veda-app-ai-draft', true),
('ramayana-3-49-37', 'en', 'His wings cut off suddenly by the demon of cruel deeds, the vulture fell to the ground, struck down, with little life left.', 'veda-app-ai-draft', true),
('ramayana-3-49-38', 'en', 'Seeing Jatayu fallen on the ground wet with blood, Sita ran to him in grief, as to her own kin.', 'veda-app-ai-draft', true),
('ramayana-3-49-39', 'en', 'The lord of Lanka saw Jatayu on the earth, like a blue-black cloud, with a white chest, of noble valour, like a forest fire put out.', 'veda-app-ai-draft', true),
('ramayana-3-49-40', 'en', 'Then moon-faced Sita, daughter of Janaka, embraced the bird felled to the ground, crushed by Ravana''s force, and wept.', 'veda-app-ai-draft', true),
('ramayana-3-50-1', 'en', 'The lord of demons saw the vulture fallen on the ground near Rama''s hermitage, quivering, with little life left.', 'veda-app-ai-draft', true),
('ramayana-3-50-2', 'en', 'Moon-faced Sita, seeing the king of vultures slain by Ravana, lamented in great sorrow:', 'veda-app-ai-draft', true),
('ramayana-3-50-3', 'en', '''Omens, knowledge of signs, and seeing and hearing birds surely show men their joys and sorrows.', 'veda-app-ai-draft', true),
('ramayana-3-50-4', 'en', 'Surely, Rama, you do not know of this great disaster; surely beasts and birds are running to you for my sake.', 'veda-app-ai-draft', true),
('ramayana-3-50-5', 'en', 'Save me today, Rama! Lakshmana!'' the noble lady cried, terrified, as if they could hear her close by.', 'veda-app-ai-draft', true),
('ramayana-3-50-6', 'en', 'As she lamented as if helpless, her garlands and ornaments crushed, Ravana, lord of demons, rushed at Sita.', 'veda-app-ai-draft', true),
('ramayana-3-50-7', 'en', 'As she clung like a creeper, embracing great trees, the lord of demons said again and again, ''Let go, let go!''', 'veda-app-ai-draft', true),
('ramayana-3-50-8', 'en', 'As she cried ''Rama, Rama!'' without Rama in the forest, he, like Death, seized her by the hair, to his own life''s end.', 'veda-app-ai-draft', true),
('ramayana-3-50-9', 'en', 'When Sita was violated, the whole world, moving and unmoving, went beyond its bounds and was covered in blind darkness.', 'veda-app-ai-draft', true),
('ramayana-3-50-10', 'en', 'Seeing Sita seized and wretched, glorious Brahma, the Grandfather, said with divine sight, ''The purpose is accomplished.''', 'veda-app-ai-draft', true),
('ramayana-3-50-11', 'en', 'All the great seers living in the Dandaka forest, seeing Sita seized, were both glad and grieved.', 'veda-app-ai-draft', true),
('ramayana-3-50-12', 'en', 'Ravana, lord of demons, went into the sky carrying her as she wept, ''Rama, Rama!'' and ''Lakshmana!''', 'veda-app-ai-draft', true),
('ramayana-3-50-13', 'en', 'Every limb adorned with gold, wearing yellow silk, the princess shone like a flash of lightning.', 'veda-app-ai-draft', true),
('ramayana-3-50-14', 'en', 'With her yellow garment fluttering, Ravana shone all the more, like a mountain lit by fire.', 'veda-app-ai-draft', true),
('ramayana-3-50-15', 'en', 'Fragrant coppery lotus petals from the most gracious Sita scattered over Ravana.', 'veda-app-ai-draft', true),
('ramayana-3-50-16', 'en', 'Her silk, fluttering in the sky with a golden glow, looked like a copper cloud lit by the sun.', 'veda-app-ai-draft', true),
('ramayana-3-50-17', 'en', 'Her clear face in Ravana''s lap in the sky did not shine without Rama, like a lotus without its stalk.', 'veda-app-ai-draft', true),
('ramayana-3-50-18', 'en', 'It was like the moon risen after splitting a dark cloud: lovely forehead and hairline, like the heart of a lotus, flawless, adorned with bright white teeth,', 'veda-app-ai-draft', true),
('ramayana-3-50-19', 'en', 'weeping, tears wiped away, lovely as the moon, with fine nose and lovely red lips, shining like gold in the sky.', 'veda-app-ai-draft', true),
('ramayana-3-50-20', 'en', 'Her lovely face, shaken by the demon king, did not shine without Rama, like the moon risen by day.', 'veda-app-ai-draft', true),
('ramayana-3-50-21', 'en', 'Golden Sita against the dark-limbed demon king shone like a golden girdle around a sapphire.', 'veda-app-ai-draft', true),
('ramayana-3-50-22', 'en', 'Fair as a lotus, golden, with burning ornaments, Sita shone against Ravana like lightning entering a cloud.', 'veda-app-ai-draft', true),
('ramayana-3-50-23', 'en', 'With the jingle of Sita''s ornaments, the demon king looked like a dark, clear cloud with thunder.', 'veda-app-ai-draft', true),
('ramayana-3-50-24', 'en', 'A shower of flowers fell from her head all around to the ground as Sita was carried off.', 'veda-app-ai-draft', true),
('ramayana-3-50-25', 'en', 'Shaken by Ravana''s speed, that shower of flowers swirled back around the ten-necked one.', 'veda-app-ai-draft', true),
('ramayana-3-50-26', 'en', 'The stream of flowers circled Kubera''s younger brother like a clear garland of stars around Mount Meru.', 'veda-app-ai-draft', true),
('ramayana-3-50-27', 'en', 'Her jewelled anklet slipped from her foot and fell with a sweet sound, like a ring of lightning.', 'veda-app-ai-draft', true),
('ramayana-3-50-28', 'en', 'Red as a young shoot, Sita adorned the dark demon king like a golden girth on an elephant.', 'veda-app-ai-draft', true),
('ramayana-3-50-29', 'en', 'Kubera''s younger brother carried Sita into the sky, blazing with her own radiance like a great meteor.', 'veda-app-ai-draft', true),
('ramayana-3-50-30', 'en', 'Her fire-coloured ornaments scattered on the earth with a sound, like stars fallen from the sky.', 'veda-app-ai-draft', true),
('ramayana-3-50-31', 'en', 'Her necklace, bright as the moon, slipping from her breast, shone as it fell, like the Ganga falling from the sky.', 'veda-app-ai-draft', true),
('ramayana-3-50-32', 'en', 'The trees, struck by the wind of the disaster and full of birds, their tops shaking, seemed to say ''Do not fear.''', 'veda-app-ai-draft', true),
('ramayana-3-50-33', 'en', 'The lotus ponds, their lotuses ruined and their fish frightened, seemed to grieve for Sita as for a friend who had lost heart.', 'veda-app-ai-draft', true),
('ramayana-3-50-34', 'en', 'Lions, tigers, deer and birds gathered from all sides and ran in anger after Sita''s shadow.', 'veda-app-ai-draft', true),
('ramayana-3-50-35', 'en', 'The mountains, their waterfalls like tearful faces and their peaks like raised arms, seemed to cry out as Sita was carried off.', 'veda-app-ai-draft', true),
('ramayana-3-50-36', 'en', 'Seeing Sita carried off, the glorious sun was saddened, its light lost, its disc pale.', 'veda-app-ai-draft', true),
('ramayana-3-50-37', 'en', '''There is no dharma, how then truth? No honesty, no kindness, where Ravana carries off Rama''s wife Sita.''', 'veda-app-ai-draft', true),
('ramayana-3-50-38', 'en', 'So all beings lamented in groups; the young deer, frightened and sad-faced, wept.', 'veda-app-ai-draft', true),
('ramayana-3-50-39', 'en', 'The forest deities, looking up again and again with tear-clouded eyes, trembled all over.', 'veda-app-ai-draft', true),
('ramayana-3-50-40', 'en', 'Seeing Sita crying out loudly in such sorrow, calling ''Lakshmana! Rama!'' in her sweet voice,', 'veda-app-ai-draft', true),
('ramayana-3-50-41', 'en', 'looking down again and again at the earth, her hair dishevelled, her forehead mark smeared, ten-necked Ravana carried off the proud lady to his own destruction.', 'veda-app-ai-draft', true),
('ramayana-3-50-42', 'en', 'Then Sita, lovely-toothed and bright-smiling, separated from her family, not seeing Rama or Lakshmana, her face pale, was crushed by the weight of fear.', 'veda-app-ai-draft', true),
('ramayana-3-51-1', 'en', 'Seeing him fly up into the sky, Sita, Janaka''s daughter, grieved, greatly alarmed and in great fear,', 'veda-app-ai-draft', true),
('ramayana-3-51-2', 'en', 'her eyes red with anger and weeping, weeping piteously as she was carried off, said to the fierce-eyed demon king:', 'veda-app-ai-draft', true),
('ramayana-3-51-3', 'en', '''Are you not ashamed of this deed, low Ravana, that knowing me to be alone, you steal me and flee?', 'veda-app-ai-draft', true),
('ramayana-3-51-4', 'en', 'Surely it was you, wicked coward, wanting to carry me off, who drew my husband away by magic in a deer''s form; and he who rose to save me has been struck down too.', 'veda-app-ai-draft', true),
('ramayana-3-51-5', 'en', 'Great indeed is your valour, lowest of demons! Having announced your name, you have not won me in battle.', 'veda-app-ai-draft', true),
('ramayana-3-51-6', 'en', 'How are you not ashamed, having done such a despicable deed, carrying off another''s wife when she was alone?', 'veda-app-ai-draft', true),
('ramayana-3-51-7', 'en', 'Men in the worlds will speak of your vile, cruel and most unrighteous deed, you who think yourself a hero.', 'veda-app-ai-draft', true),
('ramayana-3-51-8', 'en', 'Shame on the heroism and courage you boasted of then; shame on such conduct, which brings disgrace on your family in the world.', 'veda-app-ai-draft', true),
('ramayana-3-51-9', 'en', 'What can be done when you run off so fast? Stay a moment; you will not go back alive.', 'veda-app-ai-draft', true),
('ramayana-3-51-10', 'en', 'Once you come within sight of those two princes, even with your army you will not live a moment.', 'veda-app-ai-draft', true),
('ramayana-3-51-11', 'en', 'You cannot bear the touch of their arrows any more than a bird can bear the touch of a blazing forest fire.', 'veda-app-ai-draft', true),
('ramayana-3-51-12', 'en', 'Do yourself good and let me go, Ravana. Angry at my violation, my husband with his brother will bring about your destruction if you do not let me go.', 'veda-app-ai-draft', true),
('ramayana-3-51-13', 'en', 'The purpose with which you want to take me by force will be fruitless, low one.', 'veda-app-ai-draft', true),
('ramayana-3-51-14', 'en', 'For not seeing my godlike husband, in the power of an enemy, I cannot keep my life for long.', 'veda-app-ai-draft', true),
('ramayana-3-51-15', 'en', 'Surely you do not see what is good or wholesome for you, like a mortal at the time of death who seeks what is harmful.', 'veda-app-ai-draft', true),
('ramayana-3-51-16', 'en', 'For all who are about to die dislike what is wholesome; I seem to see the noose of Time around your neck.', 'veda-app-ai-draft', true),
('ramayana-3-51-17', 'en', 'Since you are not afraid in this place of fear, ten-faced one, clearly you see golden trees.', 'veda-app-ai-draft', true),
('ramayana-3-51-18', 'en', 'You see the terrible river Vaitarani flowing with floods of blood, and the dreadful forest of sword-leaves, Ravana.', 'veda-app-ai-draft', true),
('ramayana-3-51-19', 'en', 'You will see the sharp shalmali tree with flowers of refined gold and leaves of the finest beryl, covered with iron thorns.', 'veda-app-ai-draft', true),
('ramayana-3-51-20', 'en', 'Having done such wrong to that great soul, you will not be able to live long, like a pitiless man who has drunk poison.', 'veda-app-ai-draft', true),
('ramayana-3-51-21', 'en', 'You are bound by the irresistible noose of Time, Ravana; where can you go to find refuge from my great-souled husband?', 'veda-app-ai-draft', true),
('ramayana-3-51-22', 'en', 'He who in the blink of an eye, without his brother, killed fourteen thousand demons in battle,', 'veda-app-ai-draft', true),
('ramayana-3-51-23', 'en', 'how would that heroic Rama, skilled in all weapons and strong, not kill you with sharp arrows, you who stole his beloved wife?''', 'veda-app-ai-draft', true),
('ramayana-3-51-24', 'en', 'Sita, in Ravana''s lap, filled with fear and grief, lamented piteously with these and other harsh words.', 'veda-app-ai-draft', true),
('ramayana-3-51-25', 'en', 'The wicked one carried off the young princess, in great distress, lamenting much and piteously, writhing and trembling in every limb.', 'veda-app-ai-draft', true),
('ramayana-3-52-1', 'en', 'Being carried off and seeing no protector, Sita saw five chief monkeys on a mountain peak.', 'veda-app-ai-draft', true),
('ramayana-3-52-2', 'en', 'In their midst, large-eyed, lovely Sita dropped her golden silk upper cloth and lovely ornaments, hoping they would tell Rama.', 'veda-app-ai-draft', true),
('ramayana-3-52-3', 'en', 'She threw down the cloth with the ornaments among them; in his haste, ten-necked Ravana did not notice.', 'veda-app-ai-draft', true),
('ramayana-3-52-4', 'en', 'The tawny-eyed chief monkeys watched with unblinking eyes large-eyed Sita crying out.', 'veda-app-ai-draft', true),
('ramayana-3-52-5', 'en', 'Passing the Pampa, the lord of demons went toward the city of Lanka, holding weeping Sita.', 'veda-app-ai-draft', true),
('ramayana-3-52-6', 'en', 'Delighted, Ravana carried her off, his own death, like a sharp-fanged, deadly she-serpent in his lap.', 'veda-app-ai-draft', true),
('ramayana-3-52-7', 'en', 'Through the sky he quickly passed forests, rivers, mountains and lakes, like an arrow shot from a bow.', 'veda-app-ai-draft', true),
('ramayana-3-52-8', 'en', 'Reaching the ocean, home of whales and crocodiles, Varuna''s endless abode and refuge of rivers, he crossed it.', 'veda-app-ai-draft', true),
('ramayana-3-52-9', 'en', 'As Sita was carried off, Varuna''s abode was agitated, its waves churning, its fish and great serpents stilled.', 'veda-app-ai-draft', true),
('ramayana-3-52-10', 'en', 'Then celestial singers in the sky spoke, and perfected beings said, ''This is the end of ten-necked Ravana.''', 'veda-app-ai-draft', true),
('ramayana-3-52-11', 'en', 'Holding writhing Sita in his lap, Ravana entered the city of Lanka, bringing his own death in bodily form.', 'veda-app-ai-draft', true),
('ramayana-3-52-12', 'en', 'Reaching Lanka, with its well-laid-out highways, he entered his own inner palace with its many courts.', 'veda-app-ai-draft', true),
('ramayana-3-52-13', 'en', 'There Ravana placed dark-eyed Sita, overwhelmed with grief and confusion, as the demon Maya placed his demonic illusion.', 'veda-app-ai-draft', true),
('ramayana-3-52-14', 'en', 'Ten-necked Ravana told terrible-looking demonesses: ''See that no man or woman sees Sita without my leave.', 'veda-app-ai-draft', true),
('ramayana-3-52-15', 'en', 'Pearls, gems, gold, clothes and ornaments, whatever she wants, give it to her as if by my wish.', 'veda-app-ai-draft', true),
('ramayana-3-52-16', 'en', 'And whoever says anything unpleasant to Sita, knowingly or unknowingly, does not value her life.''', 'veda-app-ai-draft', true),
('ramayana-3-52-17', 'en', 'Having said this to the demonesses, the mighty lord of demons left the inner palace thinking what to do, and saw eight very strong flesh-eating demons.', 'veda-app-ai-draft', true),
('ramayana-3-52-18', 'en', 'Seeing them, the mighty one, deluded by his boon, praised their strength and valour and said:', 'veda-app-ai-draft', true),
('ramayana-3-52-19', 'en', '''Take many weapons and go quickly from here to Janasthana, once Khara''s home, now a ruined place.', 'veda-app-ai-draft', true),
('ramayana-3-52-20', 'en', 'Live there in Janasthana, empty now with its demons slain, relying on your manly strength and casting fear far away.', 'veda-app-ai-draft', true),
('ramayana-3-52-21', 'en', 'For the very great army I stationed in Janasthana, with Dushana and Khara, was killed in battle by Rama''s arrows.', 'veda-app-ai-draft', true),
('ramayana-3-52-22', 'en', 'So an unprecedented anger rises in me above my composure, and a very terrible enmity has arisen toward Rama.', 'veda-app-ai-draft', true),
('ramayana-3-52-23', 'en', 'I want to avenge that enmity on my enemy; I will not sleep until I have killed him in battle.', 'veda-app-ai-draft', true),
('ramayana-3-52-24', 'en', 'Having killed Rama, slayer of Khara and Dushana, I will find peace, like a poor man gaining wealth.', 'veda-app-ai-draft', true),
('ramayana-3-52-25', 'en', 'Living in Janasthana, you must bring true news of Rama and what he is doing.', 'veda-app-ai-draft', true),
('ramayana-3-52-26', 'en', 'All you night-roamers must go carefully and always strive toward Rama''s death.', 'veda-app-ai-draft', true),
('ramayana-3-52-27', 'en', 'I know your strength well from many battles; that is why I appoint you to Janasthana.''', 'veda-app-ai-draft', true),
('ramayana-3-52-28', 'en', 'Hearing these welcome, weighty words, the eight demons saluted Ravana, left Lanka together and set out invisibly for Janasthana.', 'veda-app-ai-draft', true),
('ramayana-3-52-29', 'en', 'Then Ravana, having got Sita and holding her, overjoyed, having started a mighty enmity with Rama, rejoiced in his delusion.', 'veda-app-ai-draft', true),
('ramayana-3-53-1', 'en', 'Having sent off the eight terrible, mighty demons, Ravana, in his mental confusion, thought his work was done.', 'veda-app-ai-draft', true),
('ramayana-3-53-2', 'en', 'Thinking of Sita, pierced by love''s arrows, he hurried into his lovely palace to see her.', 'veda-app-ai-draft', true),
('ramayana-3-53-3', 'en', 'Entering that palace, Ravana, lord of demons, saw Sita among the demonesses, overcome by grief,', 'veda-app-ai-draft', true),
('ramayana-3-53-4', 'en', 'her face full of tears, wretched, crushed under the weight of sorrow, like a boat sinking in the sea struck by gusts of wind,', 'veda-app-ai-draft', true),
('ramayana-3-53-5', 'en', 'like a doe separated from her herd and surrounded by dogs, her face downcast and wretched, the night-roamer approached her.', 'veda-app-ai-draft', true),
('ramayana-3-53-6', 'en', 'The lord of demons forcibly showed her, grief-stricken, wretched and helpless, his house like a palace of the gods,', 'veda-app-ai-draft', true),
('ramayana-3-53-7', 'en', 'crowded with mansions and palaces, attended by thousands of women, full of flocks of birds and many jewels,', 'veda-app-ai-draft', true),
('ramayana-3-53-8', 'en', 'with lovely pillars of gold, refined gold, crystal and silver, patterned with diamonds and beryl,', 'veda-app-ai-draft', true),
('ramayana-3-53-9', 'en', 'echoing with divine drums, with gateways of refined gold; he climbed a lovely golden stairway with her.', 'veda-app-ai-draft', true),
('ramayana-3-53-10', 'en', 'There were rows of palaces with lovely windows of ivory and silver, covered with golden lattices.', 'veda-app-ai-draft', true),
('ramayana-3-53-11', 'en', 'Ten-necked Ravana showed Sita every part of his palace, with floors patterned with plaster and gems.', 'veda-app-ai-draft', true),
('ramayana-3-53-12', 'en', 'Ravana showed grieving Sita long pools and lotus ponds covered with many flowers.', 'veda-app-ai-draft', true),
('ramayana-3-53-13', 'en', 'Having shown Sita that whole fine palace, wicked Ravana said to Janaka''s daughter:', 'veda-app-ai-draft', true),
('ramayana-3-53-14', 'en', '''There are ten crores of demons and twenty-two more, not counting the old and the children among the night-roamers.', 'veda-app-ai-draft', true),
('ramayana-3-53-15', 'en', 'I am lord of all of them, Sita, of terrible deeds; a thousand serve each one of my tasks.', 'veda-app-ai-draft', true),
('ramayana-3-53-16', 'en', 'All this government of mine depends on you, and my life too, large-eyed one; you are dearer to me than life.', 'veda-app-ai-draft', true),
('ramayana-3-53-17', 'en', 'Of the many thousands of women I possess, be their mistress, Sita; be my wife, beloved.', 'veda-app-ai-draft', true),
('ramayana-3-53-18', 'en', 'Enough of other thoughts; accept my words. Love me, who am burning for you; please show me favour.', 'veda-app-ai-draft', true),
('ramayana-3-53-19', 'en', 'This Lanka, a hundred yojanas wide, is surrounded by the sea; it cannot be attacked even by gods and demons with Indra.', 'veda-app-ai-draft', true),
('ramayana-3-53-20', 'en', 'Among gods, yakshas, gandharvas and sages, I see no one in the worlds equal to me in valour.', 'veda-app-ai-draft', true),
('ramayana-3-53-21', 'en', 'What will you do with Rama, a mortal of little power, deprived of his kingdom, wretched, an ascetic whose life is over?', 'veda-app-ai-draft', true),
('ramayana-3-53-22', 'en', 'Love me alone, Sita; I am a fitting husband for you. Youth is fleeting, timid one; enjoy yourself here with me.', 'veda-app-ai-draft', true),
('ramayana-3-53-23', 'en', 'Do not think of seeing Rama, lovely one; what power has he to come here, even in his wishes?', 'veda-app-ai-draft', true),
('ramayana-3-53-24', 'en', 'The swift wind cannot be bound with nooses in the sky, nor the pure flame of a blazing fire be grasped.', 'veda-app-ai-draft', true),
('ramayana-3-53-25', 'en', 'In all three worlds I see no one, lovely one, who could take you by force when you are protected by my arms.', 'veda-app-ai-draft', true),
('ramayana-3-53-26', 'en', 'Rule this great kingdom in Lanka; wet with the water of consecration, be content and give me joy.', 'veda-app-ai-draft', true),
('ramayana-3-53-27', 'en', 'Whatever bad deed you did before is gone through your forest life; now enjoy here the fruit of your good dharma.', 'veda-app-ai-draft', true),
('ramayana-3-53-28', 'en', 'Here are all garlands with divine scents, Sita, and the finest ornaments; enjoy them with me.', 'veda-app-ai-draft', true),
('ramayana-3-53-29', 'en', 'My brother Kubera''s lovely chariot named Pushpaka, swift as thought,', 'veda-app-ai-draft', true),
('ramayana-3-53-30', 'en', 'in it, Sita, roam with me as you please. Your lotus-like face, clear and lovely to see,', 'veda-app-ai-draft', true),
('ramayana-3-53-31', 'en', 'does not shine when stricken with grief, lovely one. Enough of shame for breaking dharma, Sita.', 'veda-app-ai-draft', true),
('ramayana-3-53-32', 'en', 'This union that will come to you is ordained by the sages and by fate. I press these soft feet of yours with my heads.', 'veda-app-ai-draft', true),
('ramayana-3-53-33', 'en', 'Be gracious to me quickly; I am your obedient slave. These words I speak, burning with longing, are not empty.', 'veda-app-ai-draft', true),
('ramayana-3-53-34', 'en', 'And Ravana has never bowed his head to any woman.'' Having said this to Sita, daughter of Janaka, ten-necked Ravana,', 'veda-app-ai-draft', true),
('ramayana-3-53-35', 'en', 'fallen into the power of Death, thought, ''She is mine.''', 'veda-app-ai-draft', true),
('ramayana-3-54-1', 'en', 'Thus addressed, Sita, fearless though worn by grief, placed a blade of grass between them and answered Ravana:', 'veda-app-ai-draft', true),
('ramayana-3-54-2', 'en', '''There is a king named Dasharatha, unshakeable as a bridge of dharma, known for his truthfulness; his son is Rama.', 'veda-app-ai-draft', true),
('ramayana-3-54-3', 'en', 'Named Rama, righteous, famous in the three worlds, long-armed, large-eyed, he is my husband and my god.', 'veda-app-ai-draft', true),
('ramayana-3-54-4', 'en', 'Born in the Ikshvaku family, lion-shouldered, radiant, he with his brother Lakshmana will take your life.', 'veda-app-ai-draft', true),
('ramayana-3-54-5', 'en', 'Had you violated me by force before his eyes, you would be lying slain in battle like Khara in Janasthana.', 'veda-app-ai-draft', true),
('ramayana-3-54-6', 'en', 'These demons of terrible form and great strength you speak of are all powerless before Rama, as serpents before Garuda.', 'veda-app-ai-draft', true),
('ramayana-3-54-7', 'en', 'His gold-adorned arrows released from the string will scatter your body as waves wear away the bank of the Ganga.', 'veda-app-ai-draft', true),
('ramayana-3-54-8', 'en', 'Even if gods and demons cannot kill you, Ravana, having made this great enmity you will not escape him alive.', 'veda-app-ai-draft', true),
('ramayana-3-54-9', 'en', 'Mighty Rama will end the rest of your life; like an animal tied to the sacrificial post, your life is hard to keep.', 'veda-app-ai-draft', true),
('ramayana-3-54-10', 'en', 'If Rama looks at you with eyes blazing with anger, demon, you would be burned and defeated at once.', 'veda-app-ai-draft', true),
('ramayana-3-54-11', 'en', 'He who could bring the moon down from the sky or destroy it, or dry up the ocean, will free Sita from here.', 'veda-app-ai-draft', true),
('ramayana-3-54-12', 'en', 'Your life, fortune, strength and senses are gone; Lanka will be widowed because of what you have done.', 'veda-app-ai-draft', true),
('ramayana-3-54-13', 'en', 'This evil deed of yours, taking me unwillingly from my husband''s side in the forest, will not end happily.', 'veda-app-ai-draft', true),
('ramayana-3-54-14', 'en', 'My radiant husband, joined with divine power, lives fearlessly in the empty Dandaka, relying on his strength.', 'veda-app-ai-draft', true),
('ramayana-3-54-15', 'en', 'In battle he will drive out of your limbs, with a rain of arrows, your pride, strength, valour and arrogance.', 'veda-app-ai-draft', true),
('ramayana-3-54-16', 'en', 'When the destruction of beings, driven by Time, is seen, men in the power of Time grow careless in what they do.', 'veda-app-ai-draft', true),
('ramayana-3-54-17', 'en', 'Having violated me, lowest of demons, that time has come for you, for your own death, the demons'' and your household''s.', 'veda-app-ai-draft', true),
('ramayana-3-54-18', 'en', 'An altar in the middle of a sacrifice, adorned with ladles and vessels and sanctified by brahmins'' mantras, cannot be trampled by an outcaste.', 'veda-app-ai-draft', true),
('ramayana-3-54-19', 'en', 'Bind this senseless body or kill it; I will not guard this body or this life, demon. I will not bring disgrace on myself on earth.''', 'veda-app-ai-draft', true),
('ramayana-3-54-20', 'en', 'Having spoken these very harsh words in anger to Ravana, Sita said nothing more.', 'veda-app-ai-draft', true),
('ramayana-3-54-21', 'en', 'Hearing Sita''s harsh, hair-raising words, he answered Sita with words meant to frighten:', 'veda-app-ai-draft', true),
('ramayana-3-54-22', 'en', '''Listen, Sita, to my words: if within twelve months you do not come to me, lovely-smiling one, then my cooks will cut you into pieces for my breakfast.''', 'veda-app-ai-draft', true),
('ramayana-3-54-23', 'en', 'Having spoken these harsh words, Ravana, who made his enemies cry, angrily said to the demonesses:', 'veda-app-ai-draft', true),
('ramayana-3-54-24', 'en', '''Quickly, you hideous, terrible demonesses who live on flesh and blood, break her pride.''', 'veda-app-ai-draft', true),
('ramayana-3-54-25', 'en', 'At his word those hideous, terrible demonesses, with joined palms, surrounded Sita.', 'veda-app-ai-draft', true),
('ramayana-3-54-26', 'en', 'King Ravana, terrible to see, said to them, shaking the earth with the stamping of his feet as if splitting it:', 'veda-app-ai-draft', true),
('ramayana-3-54-27', 'en', '''Take Sita to the middle of the Ashoka grove. Guard her there secretly, surrounding her.', 'veda-app-ai-draft', true),
('ramayana-3-54-28', 'en', 'There, with terrible threats and then soft words, bring her under control, all of you, like a wild she-elephant.''', 'veda-app-ai-draft', true),
('ramayana-3-54-29', 'en', 'So commanded by Ravana, those demonesses took Sita and went to the Ashoka grove,', 'veda-app-ai-draft', true),
('ramayana-3-54-30', 'en', 'full of trees giving every wish and bearing many flowers and fruits, and visited by birds always in season.', 'veda-app-ai-draft', true),
('ramayana-3-54-31', 'en', 'Sita, her limbs wrapped in grief, fallen into the demonesses'' power, was like a doe among tigresses.', 'veda-app-ai-draft', true),
('ramayana-3-54-32', 'en', 'Sita found no peace there, harshly threatened by those ugly-eyed women; remembering her beloved husband and her brother-in-law, she fainted, tormented by fear and grief.', 'veda-app-ai-draft', true),
('ramayana-3-55-1', 'en', 'Having killed Maricha, the shape-shifting demon who roamed in deer form, Rama quickly turned back along the path.', 'veda-app-ai-draft', true),
('ramayana-3-55-2', 'en', 'As he hurried, eager to see Sita, a jackal howled harshly behind him.', 'veda-app-ai-draft', true),
('ramayana-3-55-3', 'en', 'Recognising that dreadful, hair-raising cry, he grew anxious at the jackal''s sound and thought:', 'veda-app-ai-draft', true),
('ramayana-3-55-4', 'en', '''I think this is inauspicious, the way the jackal howls. May Sita be safe and not eaten by demons.', 'veda-app-ai-draft', true),
('ramayana-3-55-5', 'en', 'If Lakshmana heard the cry Maricha made in deer form, imitating my voice,', 'veda-app-ai-draft', true),
('ramayana-3-55-6', 'en', 'hearing that voice Lakshmana would leave Sita and, sent by her, would quickly come to me.', 'veda-app-ai-draft', true),
('ramayana-3-55-7', 'en', 'Surely the demons together want Sita killed; Maricha became a golden deer and drew me away from the hermitage,', 'veda-app-ai-draft', true),
('ramayana-3-55-8', 'en', 'took me far away and, struck by my arrow, became a demon and cried out, "Ah Lakshmana, I am killed!"', 'veda-app-ai-draft', true),
('ramayana-3-55-9', 'en', 'Can all be well with the two of them, left without me in the forest? I have made enemies of the demons over Janasthana, and many terrible omens are seen today.''', 'veda-app-ai-draft', true),
('ramayana-3-55-10', 'en', 'Thinking thus, hearing the jackal''s howl, and of how he had been led away by the demon in deer form, Rama came to Janasthana full of foreboding.', 'veda-app-ai-draft', true),
('ramayana-3-55-11', 'en', 'Beasts and birds came to him, sad and sad-minded, passing on his left and making terrible cries.', 'veda-app-ai-draft', true),
('ramayana-3-55-12', 'en', 'Seeing those very terrible omens, Rama then saw Lakshmana coming, his radiance gone.', 'veda-app-ai-draft', true),
('ramayana-3-55-13', 'en', 'Not far off, Lakshmana met Rama, dejected meeting dejected, sorrowful meeting one who shared his sorrow.', 'veda-app-ai-draft', true),
('ramayana-3-55-14', 'en', 'His elder brother reproached Lakshmana for coming, having left Sita in the lonely forest haunted by demons.', 'veda-app-ai-draft', true),
('ramayana-3-55-15', 'en', 'Taking Lakshmana''s left hand, Rama spoke these harsh words, as one in pain, but with a gentle end:', 'veda-app-ai-draft', true),
('ramayana-3-55-16', 'en', '''Ah Lakshmana, you have done a blameworthy thing in leaving Sita and coming here. Gentle one, is she safe?', 'veda-app-ai-draft', true),
('ramayana-3-55-17', 'en', 'I have no doubt, hero, that Sita is lost or eaten by the demons who roam the forest.', 'veda-app-ai-draft', true),
('ramayana-3-55-18', 'en', 'So many bad signs appear to me; Lakshmana, will we find Sita unharmed?', 'veda-app-ai-draft', true),
('ramayana-3-55-19', 'en', 'This demon like a deer lured me and led me far away; I killed him somehow with great effort, and as he died he became a demon.', 'veda-app-ai-draft', true),
('ramayana-3-55-20', 'en', 'My mind is dejected and joyless, and my left eye twitches. Without doubt, Lakshmana, Sita is not there: she has been carried off, or is dead, or is wandering on some path.''', 'veda-app-ai-draft', true),
('ramayana-3-56-1', 'en', 'Seeing Lakshmana wretched and alone, righteous Rama asked him, as he had come without Sita:', 'veda-app-ai-draft', true),
('ramayana-3-56-2', 'en', '''Where is Sita, who followed me when I set out for the Dandaka forest, whom you left to come here, Lakshmana?', 'veda-app-ai-draft', true),
('ramayana-3-56-3', 'en', 'Where is slender-waisted Sita, my companion in sorrow as I wander the Dandaka, wretched and deprived of my kingdom?', 'veda-app-ai-draft', true),
('ramayana-3-56-4', 'en', 'Where is Sita, like a daughter of the gods, the companion of my life, without whom I cannot live even a moment, hero?', 'veda-app-ai-draft', true),
('ramayana-3-56-5', 'en', 'Lakshmana, I would not want lordship over the immortals or the earth without golden Sita, daughter of Janaka.', 'veda-app-ai-draft', true),
('ramayana-3-56-6', 'en', 'Is Sita, dearer to me than life, alive? Gentle one, will my exile not be in vain?', 'veda-app-ai-draft', true),
('ramayana-3-56-7', 'en', 'Lakshmana, when I have died because of Sita and you have gone back, will Kaikeyi be happy, her wish fulfilled?', 'veda-app-ai-draft', true),
('ramayana-3-56-8', 'en', 'Will poor Kausalya, her son dead, have to wait upon Kaikeyi, whose son has the kingdom and whose aim is achieved?', 'veda-app-ai-draft', true),
('ramayana-3-56-9', 'en', 'If Sita is alive I will go back to the hermitage; if that virtuous one is dead, I will give up my life, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-56-10', 'en', 'If, when I reach the hermitage, Sita does not speak to me and smile again, I will perish, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-56-11', 'en', 'Tell me, Lakshmana, is Sita alive or not? Or was the poor one eaten by demons while you were careless?', 'veda-app-ai-draft', true),
('ramayana-3-56-12', 'en', 'Delicate and young and never knowing sorrow, Sita is surely grieving, sad at heart, at being apart from me.', 'veda-app-ai-draft', true),
('ramayana-3-56-13', 'en', 'That crooked, very wicked demon, crying out loudly ''Lakshmana!'', roused fear in you too.', 'veda-app-ai-draft', true),
('ramayana-3-56-14', 'en', 'I suspect Sita heard that voice like mine and, frightened, sent you, and you came quickly to see me.', 'veda-app-ai-draft', true),
('ramayana-3-56-15', 'en', 'In every way it was a grievous thing to leave Sita in the forest; you gave the cruel demons a chance to take revenge.', 'veda-app-ai-draft', true),
('ramayana-3-56-16', 'en', 'The flesh-eating demons, pained by Khara''s death, will surely have killed Sita, those dreadful ones.', 'veda-app-ai-draft', true),
('ramayana-3-56-17', 'en', 'Ah, I am sunk in disaster every way, destroyer of foes. What shall I do now? I fear something like this must happen.', 'veda-app-ai-draft', true),
('ramayana-3-56-18', 'en', 'Thinking thus of lovely Sita, Rama hurried with Lakshmana to Janasthana.', 'veda-app-ai-draft', true),
('ramayana-3-56-19', 'en', 'Reproaching his distressed younger brother, worn by hunger, fatigue and thirst, sighing, dry-mouthed and dejected, he reached the shelter and saw it empty.', 'veda-app-ai-draft', true),
('ramayana-3-56-20', 'en', 'Entering his hermitage, the hero went to some of the places where they used to spend time; at each spot, thinking ''This is where...'', his hair stood on end in anguish.', 'veda-app-ai-draft', true),
('ramayana-3-57-1', 'en', 'On the way back from the hermitage, Rama, tormented by grief, again questioned Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-57-2', 'en', 'He said to him: ''Why did you come, leaving Sita, when I left her in the forest trusting you?', 'veda-app-ai-draft', true),
('ramayana-3-57-3', 'en', 'As soon as I saw you coming without Sita, Lakshmana, my mind, fearing great evil, was truly troubled.', 'veda-app-ai-draft', true),
('ramayana-3-57-4', 'en', 'My left eye, arm and heart throb, Lakshmana, seeing you far off on the path without Sita.''', 'veda-app-ai-draft', true),
('ramayana-3-57-5', 'en', 'Thus addressed, Lakshmana, of auspicious marks, filled with still more grief, said to grieving Rama:', 'veda-app-ai-draft', true),
('ramayana-3-57-6', 'en', '''I did not leave her and come here of my own will; I came to you driven by her own fierce words.', 'veda-app-ai-draft', true),
('ramayana-3-57-7', 'en', 'The words ''Ah Sita! Ah Lakshmana! Save me!'', cried out as if by my noble brother, reached Sita''s ears.', 'veda-app-ai-draft', true),
('ramayana-3-57-8', 'en', 'Hearing that cry of distress, out of love for you, Sita, weeping and overcome with fear, told me, ''Go, go!''', 'veda-app-ai-draft', true),
('ramayana-3-57-9', 'en', 'Urged by her many times to go, I answered Sita with these words, full of trust in you:', 'veda-app-ai-draft', true),
('ramayana-3-57-10', 'en', '"I see no demon who could bring fear to him. Be calm; this was not said by him, it was said by someone else.', 'veda-app-ai-draft', true),
('ramayana-3-57-11', 'en', 'How could my noble brother, who could protect even the gods, say such base, contemptible words as ''Save me'', Sita?', 'veda-app-ai-draft', true),
('ramayana-3-57-12', 'en', 'For some reason someone has imitated my brother''s voice and cried out in a strange tone, ''Lakshmana, save me!'' You should not give way to the distress of a lesser woman.', 'veda-app-ai-draft', true),
('ramayana-3-57-13', 'en', 'Enough of this agitation; be calm and untroubled. There is no man in the three worlds, born or yet to be born, who could defeat Rama in battle."', 'veda-app-ai-draft', true),
('ramayana-3-57-14', 'en', 'Thus addressed, Sita, her mind bewildered, shedding tears, spoke these cruel words to me:', 'veda-app-ai-draft', true),
('ramayana-3-57-15', 'en', '"You have set a truly wicked desire on me; but even if your brother dies, you will not have me.', 'veda-app-ai-draft', true),
('ramayana-3-57-16', 'en', 'You follow Rama by arrangement with Bharata; that is why you do not go to him when he cries out so loudly.', 'veda-app-ai-draft', true),
('ramayana-3-57-17', 'en', 'You are a secret enemy who follows for my sake, seeking a weakness in Rama; that is why you do not go to him."', 'veda-app-ai-draft', true),
('ramayana-3-57-18', 'en', 'Thus addressed by Sita, angry, red-eyed, my lips trembling with rage, I left the hermitage.''', 'veda-app-ai-draft', true),
('ramayana-3-57-19', 'en', 'As Lakshmana spoke thus, Rama, bewildered by anguish, said: ''Gentle one, you did wrong in coming here without her.', 'veda-app-ai-draft', true),
('ramayana-3-57-20', 'en', 'Though you knew I am able to hold off the demons, you left at that angry word of Sita''s.', 'veda-app-ai-draft', true),
('ramayana-3-57-21', 'en', 'I am not pleased that you left Sita and came here, having heard harsh words from an angry woman.', 'veda-app-ai-draft', true),
('ramayana-3-57-22', 'en', 'You were wholly wrong to be driven by Sita, falling under anger''s power, and not carry out my command.', 'veda-app-ai-draft', true),
('ramayana-3-57-23', 'en', 'That demon who drew me from the hermitage in deer form lies there slain by my arrow.', 'veda-app-ai-draft', true),
('ramayana-3-57-24', 'en', 'Drawing my bow, fitting an arrow, I struck him easily; leaving the deer body, the demon became one wearing armlets, with a pitiful voice.', 'veda-app-ai-draft', true),
('ramayana-3-57-25', 'en', 'Struck by the arrow, with a pained voice he imitated mine, which could be heard far off, and uttered those terrible words that made you leave Sita and come.''', 'veda-app-ai-draft', true),
('ramayana-3-58-1', 'en', 'As he hurried on, Rama''s lower left eyelid throbbed; he stumbled and began to tremble.', 'veda-app-ai-draft', true),
('ramayana-3-58-2', 'en', 'Seeing inauspicious omens again and again, he said, ''Is Sita safe?''', 'veda-app-ai-draft', true),
('ramayana-3-58-3', 'en', 'Then he went quickly, longing to see Sita; seeing the dwelling empty, his mind was agitated.', 'veda-app-ai-draft', true),
('ramayana-3-58-4', 'en', 'Rushing about as if crazed, flinging his arms, Rama looked all around the hut site here and there.', 'veda-app-ai-draft', true),
('ramayana-3-58-5', 'en', 'He saw the leaf hut without Sita, without its beauty, ruined, like a lotus pond in winter.', 'veda-app-ai-draft', true),
('ramayana-3-58-6', 'en', 'It seemed to weep with its trees, its flowers, beasts and birds withered, without its beauty, ruined, abandoned by the forest deities,', 'veda-app-ai-draft', true),
('ramayana-3-58-7', 'en', 'its deerskins and kusha scattered, its mats thrown about; seeing the hut empty, he lamented again and again:', 'veda-app-ai-draft', true),
('ramayana-3-58-8', 'en', '''She has been carried off, or is dead, or lost, or eaten; or the timid one is hiding, or has gone into the forest,', 'veda-app-ai-draft', true),
('ramayana-3-58-9', 'en', 'or gone to gather flowers or fruits, or gone to the lotus pond or the river for water.''', 'veda-app-ai-draft', true),
('ramayana-3-58-10', 'en', 'Searching hard, he did not find his beloved in the forest; his eyes red with grief, he looked like a madman.', 'veda-app-ai-draft', true),
('ramayana-3-58-11', 'en', 'Running from tree to tree, from hill to hill, from river to river, Rama lamented, sunk in an ocean of the mire of grief.', 'veda-app-ai-draft', true),
('ramayana-3-58-12', 'en', '''Kadamba tree, have you seen my beloved who loves kadamba flowers? If you know, tell me of lovely-faced Sita.', 'veda-app-ai-draft', true),
('ramayana-3-58-13', 'en', 'Bilva tree, if you have seen her, tender as a glossy shoot, in yellow silk, tell me.', 'veda-app-ai-draft', true),
('ramayana-3-58-14', 'en', 'Or arjuna tree, tell me of my beloved who loves arjuna flowers: is timid Janaka''s daughter alive or not?', 'veda-app-ai-draft', true),
('ramayana-3-58-15', 'en', 'This kakubha tree surely knows Sita; this lord of the forest shines rich with creepers, shoots and flowers.', 'veda-app-ai-draft', true),
('ramayana-3-58-16', 'en', 'As this best of trees is sung to by bees, this tilaka surely knows her who loves tilaka flowers.', 'veda-app-ai-draft', true),
('ramayana-3-58-17', 'en', 'Ashoka, remover of sorrow, make me true to your name quickly by showing me my beloved, my mind struck by grief.', 'veda-app-ai-draft', true),
('ramayana-3-58-18', 'en', 'Palm tree, if you have seen her, tell me of that lovely one, if you have pity on me.', 'veda-app-ai-draft', true),
('ramayana-3-58-19', 'en', 'Jambu tree, if you have seen Sita, golden as jambu gold, if you know my beloved, tell me without fear.', 'veda-app-ai-draft', true),
('ramayana-3-58-20', 'en', 'Or deer, do you know fawn-eyed Sita? My beloved, with a deer''s glance, may be with the does.', 'veda-app-ai-draft', true),
('ramayana-3-58-21', 'en', 'Elephant, if you have seen her, tell me, best of elephants; I think she is known to you.', 'veda-app-ai-draft', true),
('ramayana-3-58-22', 'en', 'Tiger, if you have seen my moon-faced beloved Sita, tell me confidently; you have nothing to fear.', 'veda-app-ai-draft', true),
('ramayana-3-58-23', 'en', 'Why do you run, beloved? Surely I see you, lotus-eyed one; why do you hide behind a tree and not answer me?', 'veda-app-ai-draft', true),
('ramayana-3-58-24', 'en', 'Stop, stop, lovely one; have you no pity for me? You are not one for jokes; why do you ignore me?', 'veda-app-ai-draft', true),
('ramayana-3-58-25', 'en', 'Your yellow silk gives you away, lovely one; I saw you even as you ran. Stop, if you have any affection.', 'veda-app-ai-draft', true),
('ramayana-3-58-26', 'en', 'Surely it is not her, or else the lovely-smiling one has been harmed; for she would not ignore me in such distress.', 'veda-app-ai-draft', true),
('ramayana-3-58-27', 'en', 'Clearly the young one has been eaten by flesh-eating demons, who divided all her limbs while she was without me.', 'veda-app-ai-draft', true),
('ramayana-3-58-28', 'en', 'Surely that face with fine teeth and lips has lost its light; that neck, the colour of champaka, adorned with a necklace,', 'veda-app-ai-draft', true),
('ramayana-3-58-29', 'en', 'tender and lovely, of my beloved lamenting, has been eaten; surely those arms, soft as shoots, flung about,', 'veda-app-ai-draft', true),
('ramayana-3-58-30', 'en', 'trembling at the tips, with bracelets and armlets, have been eaten; the young one, without me, was left for the demons to eat,', 'veda-app-ai-draft', true),
('ramayana-3-58-31', 'en', 'eaten like one abandoned by her caravan, though she has many kin. Ah Lakshmana, mighty-armed, do you see my beloved anywhere?', 'veda-app-ai-draft', true),
('ramayana-3-58-32', 'en', 'Ah beloved, where have you gone, gracious one? Ah Sita!'' So lamenting again and again, Rama ran from forest to forest.', 'veda-app-ai-draft', true),
('ramayana-3-58-33', 'en', 'Sometimes he whirled about wildly, sometimes staggered from exhaustion; sometimes he seemed mad, intent on searching for his beloved.', 'veda-app-ai-draft', true),
('ramayana-3-58-34', 'en', 'He roamed swiftly through forests, rivers, mountains, springs and groves, without rest.', 'veda-app-ai-draft', true),
('ramayana-3-58-35', 'en', 'Having gone around that whole vast forest searching for Sita, with hope not yet exhausted, he made a supreme effort to find his beloved again.', 'veda-app-ai-draft', true),
('ramayana-3-59-1', 'en', 'Seeing the hermitage empty, the leaf hut deserted and the seats scattered,', 'veda-app-ai-draft', true),
('ramayana-3-59-2', 'en', 'not seeing Sita there after searching everywhere, Rama cried out, raising his fine arms:', 'veda-app-ai-draft', true),
('ramayana-3-59-3', 'en', '''Where is Sita, Lakshmana? To what place has she gone from here? Who has carried off my beloved, or who has eaten her?', 'veda-app-ai-draft', true),
('ramayana-3-59-4', 'en', 'If you are hiding behind a tree to laugh at me, Sita, enough of laughing today; come to me, I am in great pain.', 'veda-app-ai-draft', true),
('ramayana-3-59-5', 'en', 'The trusting fawns you used to play with, gentle Sita, are without you and brooding, their eyes clouded with tears.', 'veda-app-ai-draft', true),
('ramayana-3-59-6', 'en', 'My father the great king will surely see me in the other world, dead from the great grief of Sita''s abduction.', 'veda-app-ai-draft', true),
('ramayana-3-59-7', 'en', '"How did you come here to me without completing the time, having promised and been appointed by me?"', 'veda-app-ai-draft', true),
('ramayana-3-59-8', 'en', 'My father will surely say in the other world, "Shame on you, wilful, ignoble and a liar."', 'veda-app-ai-draft', true),
('ramayana-3-59-9', 'en', 'Helpless, burning with grief, wretched, my hopes broken, you leave me here, pitiful, as fame leaves a crooked man.', 'veda-app-ai-draft', true),
('ramayana-3-59-10', 'en', 'Where are you going, lovely one, leaving me, slender-waisted one? Without you I will give up my life.''', 'veda-app-ai-draft', true),
('ramayana-3-59-11', 'en', 'So lamenting, longing to see Sita, Rama, in deep sorrow, did not see Janaka''s daughter.', 'veda-app-ai-draft', true),
('ramayana-3-59-12', 'en', 'Seeing Rama not finding Sita, like an elephant sinking in deep mud, Lakshmana, wishing him well, said to him:', 'veda-app-ai-draft', true),
('ramayana-3-59-13', 'en', '''Do not despair, mighty-armed one; make an effort with me. This forest, hero, is full of caves.', 'veda-app-ai-draft', true),
('ramayana-3-59-14', 'en', 'Sita loves to roam the woods and is enchanted by the forest; she may have gone into the forest or to a lotus pond in bloom,', 'veda-app-ai-draft', true),
('ramayana-3-59-15', 'en', 'or to the river full of fish and reeds; or she may be hiding somewhere in the forest to frighten us, wanting to test you and me, best of men.', 'veda-app-ai-draft', true),
('ramayana-3-59-16', 'en', 'Let us quickly try to find her, glorious one; let us search the whole forest for Janaka''s daughter. If you agree, Rama, do not give your mind to grief.''', 'veda-app-ai-draft', true),
('ramayana-3-59-17', 'en', 'Thus addressed with affection by Lakshmana, Rama, composed, began to search with him through forests, mountains, rivers and lakes.', 'veda-app-ai-draft', true),
('ramayana-3-59-18', 'en', 'The two sons of Dasharatha searched thoroughly for Sita on the slopes, caves and peaks of that mountain,', 'veda-app-ai-draft', true),
('ramayana-3-59-19', 'en', 'but searching thoroughly, they did not find her. Having searched the whole mountain, Rama said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-59-20', 'en', '''I do not see Sita on this lovely mountain, Lakshmana.'' Then Lakshmana, burning with grief, said:', 'veda-app-ai-draft', true),
('ramayana-3-59-21', 'en', '''Roaming the Dandaka forest, wise one, you will find Sita, Janaka''s daughter,', 'veda-app-ai-draft', true),
('ramayana-3-59-22', 'en', 'as mighty-armed Vishnu, having bound Bali, won this earth.'' Thus addressed by heroic Lakshmana, Rama', 'veda-app-ai-draft', true),
('ramayana-3-59-23', 'en', 'said in a wretched voice, his mind struck by sorrow: ''The whole forest has been searched, and the lotus ponds in bloom,', 'veda-app-ai-draft', true),
('ramayana-3-59-24', 'en', 'and this mountain with its many caves and waterfalls, wise one, but I do not see Sita, dearer to me than life.''', 'veda-app-ai-draft', true),
('ramayana-3-59-25', 'en', 'Lamenting thus, worn by Sita''s abduction, wretched and filled with grief, Rama was overwhelmed for a moment.', 'veda-app-ai-draft', true),
('ramayana-3-59-26', 'en', 'All his limbs shaking, his mind gone, senseless, he sank down, distressed, sighing long and hot.', 'veda-app-ai-draft', true),
('ramayana-3-59-27', 'en', 'Sighing many times, lotus-eyed Rama cried out ''Ah beloved!'' again and again, choked with tears.', 'veda-app-ai-draft', true),
('ramayana-3-59-28', 'en', 'Then Lakshmana, his loving kinsman, knowing dharma, humble and with joined palms, comforted him in many ways.', 'veda-app-ai-draft', true),
('ramayana-3-59-29', 'en', 'But disregarding the words that fell from Lakshmana''s lips, not seeing his beloved Sita, he cried out again and again.', 'veda-app-ai-draft', true),
('ramayana-3-60-1', 'en', 'Wretched, in a wretched voice, he said to Lakshmana: ''Quickly, Lakshmana, go to the Godavari and find out; perhaps Sita has gone to the Godavari to bring lotuses.''', 'veda-app-ai-draft', true),
('ramayana-3-60-2', 'en', 'Thus told by Rama, quick-footed Lakshmana went again to the lovely Godavari river.', 'veda-app-ai-draft', true),
('ramayana-3-60-3', 'en', 'Having searched the river with its many fords, Lakshmana said to Rama: ''I do not see her at the fords; she does not hear me when I call.', 'veda-app-ai-draft', true),
('ramayana-3-60-4', 'en', 'To what place has Sita, who removed our troubles, gone? I do not know where the slender-waisted one is, Rama.''', 'veda-app-ai-draft', true),
('ramayana-3-60-5', 'en', 'Hearing Lakshmana''s words, wretched and bewildered by anguish, Rama himself went to the Godavari river.', 'veda-app-ai-draft', true),
('ramayana-3-60-6', 'en', 'Standing by it, Rama said, ''Where is Sita?''', 'veda-app-ai-draft', true),
('ramayana-3-60-7', 'en', 'The creatures did not tell Rama that she had been carried off by the demon king, who deserved death; nor did the Godavari river.', 'veda-app-ai-draft', true),
('ramayana-3-60-8', 'en', 'Then, though urged by the creatures to tell him of his beloved, the river, questioned by grieving Rama, did not speak of Sita.', 'veda-app-ai-draft', true),
('ramayana-3-60-9', 'en', 'Thinking of the form and deeds of wicked Ravana, the river was afraid and did not tell of Sita.', 'veda-app-ai-draft', true),
('ramayana-3-60-10', 'en', 'Made hopeless of seeing Sita by the river, Rama, worn by not seeing her, said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-60-11', 'en', '''What shall I say, Lakshmana, when I meet Janaka, and Sita''s mother, unhappy words without her?', 'veda-app-ai-draft', true),
('ramayana-3-60-12', 'en', 'Where has Sita gone, who took away all my sorrow when I lived in the forest on forest food, deprived of my kingdom?', 'veda-app-ai-draft', true),
('ramayana-3-60-13', 'en', 'Without kin and not seeing the princess, I think my sleepless nights will be long.', 'veda-app-ai-draft', true),
('ramayana-3-60-14', 'en', 'I will roam the Godavari, Janasthana and this Mount Prasravana, all of them, in case Sita is seen.''', 'veda-app-ai-draft', true),
('ramayana-3-60-15', 'en', 'As the two brothers talked together, they saw a trail of flowers fallen on the ground.', 'veda-app-ai-draft', true),
('ramayana-3-60-16', 'en', 'Seeing that shower of flowers fallen on the earth, grieving heroic Rama said to grieving Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-60-17', 'en', '''I recognise these flowers here, Lakshmana; I gave them to Sita in the forest and she wore them.''', 'veda-app-ai-draft', true),
('ramayana-3-60-18', 'en', 'Having said this to Lakshmana, best of men, mighty-armed Rama angrily spoke to the mountain, like a lion to a small deer:', 'veda-app-ai-draft', true),
('ramayana-3-60-19', 'en', '''Show me golden Sita, mountain, before I destroy all your slopes.', 'veda-app-ai-draft', true),
('ramayana-3-60-20', 'en', 'Burned by the fire of my arrows you will become ash, never again to be visited, without grass, trees or shoots.', 'veda-app-ai-draft', true),
('ramayana-3-60-21', 'en', 'And I will dry up this river today, Lakshmana, if it does not tell me of moon-faced Sita.''', 'veda-app-ai-draft', true),
('ramayana-3-60-22', 'en', 'So enraged, Rama, as if wanting to burn with his eyes, saw on the ground the great footprint of a demon.', 'veda-app-ai-draft', true),
('ramayana-3-60-23', 'en', 'Seeing the tracks of Sita and the demon, Rama, his heart agitated, told his dear brother:', 'veda-app-ai-draft', true),
('ramayana-3-60-24', 'en', '''Look, Lakshmana, at the gold drops scattered from Sita''s ornaments, and the many garlands.', 'veda-app-ai-draft', true),
('ramayana-3-60-25', 'en', 'Look, Lakshmana, the ground everywhere is covered with drops of blood bright as molten gold.', 'veda-app-ai-draft', true),
('ramayana-3-60-26', 'en', 'I think, Lakshmana, Sita has been cut up and shared or eaten by shape-shifting demons.', 'veda-app-ai-draft', true),
('ramayana-3-60-27', 'en', 'Here, Lakshmana, there was a terrible fight between two demons quarrelling over Sita.', 'veda-app-ai-draft', true),
('ramayana-3-60-28', 'en', 'Whose great bow is this, adorned with pearls, gems and gold, fallen broken on the ground, gentle one?', 'veda-app-ai-draft', true),
('ramayana-3-60-29', 'en', 'Whose is this golden armour, bright as the young sun and studded with beryl, fallen broken on the ground?', 'veda-app-ai-draft', true),
('ramayana-3-60-30', 'en', 'Whose is this hundred-ribbed parasol adorned with divine garlands, its staff broken, thrown on the ground, gentle one?', 'veda-app-ai-draft', true),
('ramayana-3-60-31', 'en', 'Whose are these terrible, huge, goblin-faced donkeys with golden breastplates, killed in battle?', 'veda-app-ai-draft', true),
('ramayana-3-60-32', 'en', 'Whose is this blazing, fire-bright war chariot with its battle banner, overturned and broken?', 'veda-app-ai-draft', true),
('ramayana-3-60-33', 'en', 'Whose are these arrows, as long as a chariot axle, adorned with gold, scattered and broken, belonging to one of terrible deeds?', 'veda-app-ai-draft', true),
('ramayana-3-60-34', 'en', 'See, gentle one, my enmity with the very cruel-hearted shape-shifting demons is now a hundredfold, deadly to them.', 'veda-app-ai-draft', true),
('ramayana-3-60-35', 'en', 'Poor Sita has been carried off, or killed, or eaten; dharma does not protect Sita carried off in the great forest.', 'veda-app-ai-draft', true),
('ramayana-3-60-36', 'en', 'When Sita is eaten or carried off, Lakshmana, which lords in the world are able to do me any kindness?', 'veda-app-ai-draft', true),
('ramayana-3-60-37', 'en', 'All beings in their ignorance would despise even the creator of the worlds if he were brave but compassionate, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-60-38', 'en', 'The lords of the gods surely think me powerless because I am gentle, devoted to the world''s good, self-controlled and compassionate.', 'veda-app-ai-draft', true),
('ramayana-3-60-39', 'en', 'See, Lakshmana, my virtue has become a fault. Today, for the destruction of all beings and demons, I will rise like the great sun that swallows the moonlight.', 'veda-app-ai-draft', true),
('ramayana-3-60-40', 'en', 'Neither yakshas, gandharvas, pishachas, demons, kinnaras nor men will find happiness, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-60-41', 'en', 'See the sky filled with my weapons and arrows, Lakshmana; today I will make it impossible for those who roam the three worlds to move.', 'veda-app-ai-draft', true),
('ramayana-3-60-42', 'en', 'with the planets stopped, the moon blocked, fire, wind and the sun''s light destroyed and covered,', 'veda-app-ai-draft', true),
('ramayana-3-60-43', 'en', 'the mountain peaks crushed, the lakes drying up, trees, creepers and shrubs destroyed, the ocean annihilated.', 'veda-app-ai-draft', true),
('ramayana-3-60-44', 'en', 'If the lords do not give me Sita back safe, at this very moment, Lakshmana, they will see my valour.', 'veda-app-ai-draft', true),
('ramayana-3-60-45', 'en', 'No being will fly up into the sky, Lakshmana, because of the unbroken nets of arrows released from my bowstring.', 'veda-app-ai-draft', true),
('ramayana-3-60-46', 'en', 'See today, Lakshmana, the world struck by my iron arrows, its beasts and birds destroyed and bewildered, thrown into confusion and without bounds.', 'veda-app-ai-draft', true),
('ramayana-3-60-47', 'en', 'With arrows drawn to the ear, irresistible, I will rid the world of living beings, of pishachas and demons, for Sita''s sake.', 'veda-app-ai-draft', true),
('ramayana-3-60-48', 'en', 'Today the gods will see the might of my arrows, released in anger and flying far.', 'veda-app-ai-draft', true),
('ramayana-3-60-49', 'en', 'Neither gods, daityas, pishachas nor demons will survive when the three worlds are destroyed by my anger.', 'veda-app-ai-draft', true),
('ramayana-3-60-50', 'en', 'The worlds of gods, danavas, yakshas and demons will fall in many pieces, shattered by floods of arrows; today I will make these worlds boundless with my arrows.', 'veda-app-ai-draft', true),
('ramayana-3-60-51', 'en', 'As old age, death, time and fate are never resisted among all beings, Lakshmana, so I, filled with anger, cannot be held back, no doubt.', 'veda-app-ai-draft', true),
('ramayana-3-60-52', 'en', 'If they do not show me lovely-toothed, faultless Sita today as before, I will overturn the world with gods, gandharvas, men, serpents and mountains.''', 'veda-app-ai-draft', true),
('ramayana-3-61-1', 'en', 'Rama, burning, worn by Sita''s abduction, intent on destroying the worlds like the fire at the end of time,', 'veda-app-ai-draft', true),
('ramayana-3-61-2', 'en', 'looking at his strung bow, sighing again and again, like angry Rudra wanting to kill the victim at Daksha''s sacrifice,', 'veda-app-ai-draft', true),
('ramayana-3-61-3', 'en', 'seeing Rama enraged as never before, Lakshmana, with joined palms and dry mouth, said:', 'veda-app-ai-draft', true),
('ramayana-3-61-4', 'en', '''You have always been gentle, self-controlled and devoted to the good of all beings; do not fall under anger''s power and give up your nature.', 'veda-app-ai-draft', true),
('ramayana-3-61-5', 'en', 'Beauty in the moon, light in the sun, motion in the wind and patience in the earth: all these are fixed, and in you supreme fame.', 'veda-app-ai-draft', true),
('ramayana-3-61-6', 'en', 'I do not know whose broken war chariot this is, or by whom or why, with weapons and equipment.', 'veda-app-ai-draft', true),
('ramayana-3-61-7', 'en', 'This ground scarred by hooves and wheel rims and sprinkled with drops of blood, prince, is where a fierce battle has ended.', 'veda-app-ai-draft', true),
('ramayana-3-61-8', 'en', 'This was the struggle of one, not two, best of speakers; I see no tracks of a great army.', 'veda-app-ai-draft', true),
('ramayana-3-61-9', 'en', 'You should not destroy the worlds for the sake of one. Kings who are gentle and calm apply punishment fittingly.', 'veda-app-ai-draft', true),
('ramayana-3-61-10', 'en', 'You have always been the refuge and highest goal of all beings; who would think the loss of your wife a good thing, Rama?', 'veda-app-ai-draft', true),
('ramayana-3-61-11', 'en', 'Rivers, oceans, mountains, gods, gandharvas and danavas would no more harm you than good people would harm one consecrated for a sacrifice.', 'veda-app-ai-draft', true),
('ramayana-3-61-12', 'en', 'You should search for the one who carried off Sita, king, with me at your side, bow in hand, and with great seers as helpers.', 'veda-app-ai-draft', true),
('ramayana-3-61-13', 'en', 'We will search the ocean, mountains and forests, the many terrible caves and the mountain lotus ponds.', 'veda-app-ai-draft', true),
('ramayana-3-61-14', 'en', 'We will search the worlds of gods and gandharvas with focus until we find the one who took your wife.', 'veda-app-ai-draft', true),
('ramayana-3-61-15', 'en', 'If the lords of the gods do not give back your wife peacefully, lord of Kosala, then you will do what the time calls for.', 'veda-app-ai-draft', true),
('ramayana-3-61-16', 'en', 'If by good conduct, conciliation, humility and policy you do not get Sita back, king, then destroy them with floods of gold-feathered arrows like great Indra''s thunderbolt.''', 'veda-app-ai-draft', true),
('ramayana-3-62-1', 'en', 'Then, seeing Rama tormented by grief, lamenting as if helpless, overwhelmed by great confusion, exhausted and senseless,', 'veda-app-ai-draft', true),
('ramayana-3-62-2', 'en', 'Lakshmana, after comforting him for a moment, roused Rama, pressing his feet:', 'veda-app-ai-draft', true),
('ramayana-3-62-3', 'en', '''Rama, King Dasharatha won you through great austerity and great deeds, as the gods won the nectar.', 'veda-app-ai-draft', true),
('ramayana-3-62-4', 'en', 'Bound by your virtues, the king died of separation from you and became a god, as we heard from Bharata.', 'veda-app-ai-draft', true),
('ramayana-3-62-5', 'en', 'If you cannot bear this sorrow that has come, who else, ordinary and weak in spirit, could bear it?', 'veda-app-ai-draft', true),
('ramayana-3-62-6', 'en', 'If in your sorrow you burn the worlds with your power, where will suffering people find peace, tiger among men?', 'veda-app-ai-draft', true),
('ramayana-3-62-7', 'en', 'This is the nature of the world: Yayati, son of Nahusha, reached Indra''s world, and misfortune touched him there.', 'veda-app-ai-draft', true),
('ramayana-3-62-8', 'en', 'The great seer Vasishtha, our father''s priest, had a hundred sons born in one day, and they were all killed again.', 'veda-app-ai-draft', true),
('ramayana-3-62-9', 'en', 'And this earth, mother of the world, honoured by the world, is seen to shake, you who are true to your word.', 'veda-app-ai-draft', true),
('ramayana-3-62-10', 'en', 'And these two eyes of the worlds, the sun and moon, in which everything rests, mighty as they are, undergo eclipse.', 'veda-app-ai-draft', true),
('ramayana-3-62-11', 'en', 'Even very great beings and gods, best of men, cannot escape fate, nor can any embodied creature.', 'veda-app-ai-draft', true),
('ramayana-3-62-12', 'en', 'Good and ill fortune are heard of even among the gods led by Indra, tiger among men; you should not be distressed.', 'veda-app-ai-draft', true),
('ramayana-3-62-13', 'en', 'Even with Sita lost and carried off, sinless hero, you should not grieve like some ordinary man.', 'veda-app-ai-draft', true),
('ramayana-3-62-14', 'en', 'Those like you, who see the truth, do not always grieve, even in great hardships, Rama, with undiscouraged vision.', 'veda-app-ai-draft', true),
('ramayana-3-62-15', 'en', 'Think it over truly with your intellect, best of men; the very wise, endowed with intellect, know good and bad.', 'veda-app-ai-draft', true),
('ramayana-3-62-16', 'en', 'For deeds whose merits and faults are unseen and not yet done, the desired fruit does not come without action.', 'veda-app-ai-draft', true),
('ramayana-3-62-17', 'en', 'You yourself, hero, have often taught me this before; who could teach you, even Brihaspati himself?', 'veda-app-ai-draft', true),
('ramayana-3-62-18', 'en', 'Your intellect, very wise one, is hard even for the gods to fathom; I am only waking your knowledge, which grief has put to sleep.', 'veda-app-ai-draft', true),
('ramayana-3-62-19', 'en', 'Considering your divine and human valour, bull of the Ikshvakus, strive to kill your enemies.', 'veda-app-ai-draft', true),
('ramayana-3-62-20', 'en', 'What use is destroying everything, best of men? Find out that one wicked enemy and you should root him out.''', 'veda-app-ai-draft', true),
('ramayana-3-63-1', 'en', 'Elder though he was, Rama, who grasps the essence, accepted at once the essential, well-spoken words of Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-63-2', 'en', 'Restraining his swelling anger, mighty-armed Rama leaned on his bright bow and said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-63-3', 'en', '''What shall we do, child? Where shall we go, Lakshmana? Think by what means I may see Sita.''', 'veda-app-ai-draft', true),
('ramayana-3-63-4', 'en', 'To Rama, afflicted with anguish, Lakshmana said: ''You should search this very Janasthana,', 'veda-app-ai-draft', true),
('ramayana-3-63-5', 'en', 'full of many demons and many trees and creepers. There are mountain strongholds here, chasms and ravines,', 'veda-app-ai-draft', true),
('ramayana-3-63-6', 'en', 'many terrible caves full of many beasts, dwellings of kinnaras and homes of gandharvas.', 'veda-app-ai-draft', true),
('ramayana-3-63-7', 'en', 'You should search them with me, focused. Wise, great-souled men like you, bull among men,', 'veda-app-ai-draft', true),
('ramayana-3-63-8', 'en', 'do not tremble in calamities, as mountains do not tremble in the wind.'' Thus addressed, Rama roamed the whole forest with Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-63-9', 'en', 'Angry Rama fitted a terrible razor-headed arrow to his bow. Then he saw, like a mountain peak, the noble best of birds,', 'veda-app-ai-draft', true),
('ramayana-3-63-10', 'en', 'Jatayu, fallen on the ground, wet with blood. Seeing him like a mountain peak, Rama said to Lakshmana, ''This one has eaten Sita, no doubt.', 'veda-app-ai-draft', true),
('ramayana-3-63-11', 'en', 'Clearly this is a demon in vulture form roaming the forest; having eaten large-eyed Sita, it rests at ease. I will kill it with terrible, straight arrows.''', 'veda-app-ai-draft', true),
('ramayana-3-63-12', 'en', 'Saying this, angry Rama rushed at the vulture with the arrow on his bow, as if shaking the sea-bounded earth.', 'veda-app-ai-draft', true),
('ramayana-3-63-13', 'en', 'The bird, vomiting frothy blood, spoke to Rama, son of Dasharatha, in a very feeble voice:', 'veda-app-ai-draft', true),
('ramayana-3-63-14', 'en', '''Long-lived one, she whom you seek in the great forest like a healing herb, the queen, and my life too, have both been taken by Ravana.', 'veda-app-ai-draft', true),
('ramayana-3-63-15', 'en', 'Without you and Lakshmana, Rama, I saw the queen being carried off by mighty Ravana.', 'veda-app-ai-draft', true),
('ramayana-3-63-16', 'en', 'I came to help Sita, and in battle I brought Ravana down to the ground, his chariot and parasol smashed.', 'veda-app-ai-draft', true),
('ramayana-3-63-17', 'en', 'This is his broken bow, this his fine arrow, this his war chariot broken in battle, Rama.', 'veda-app-ai-draft', true),
('ramayana-3-63-18', 'en', 'When I was exhausted, Ravana cut off my wings with his sword, took Sita and flew into the sky. I have already been struck down by the demon; you should not kill me.''', 'veda-app-ai-draft', true),
('ramayana-3-63-19', 'en', 'Hearing his welcome news about Sita, Rama embraced the king of vultures and wept with Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-63-20', 'en', 'Seeing him alone in that hard, lonely place, barely breathing, grieving Rama said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-63-21', 'en', '''Loss of kingdom, life in the forest, Sita lost, this bird killed: such misfortune of mine could burn even fire.', 'veda-app-ai-draft', true),
('ramayana-3-63-22', 'en', 'If I were to cross the full ocean today, surely even that lord of rivers would dry up through my ill fortune.', 'veda-app-ai-draft', true),
('ramayana-3-63-23', 'en', 'There is no one more unfortunate than me in this world of moving and unmoving things, since I have been caught in this great net of disaster.', 'veda-app-ai-draft', true),
('ramayana-3-63-24', 'en', 'This old king of vultures, my father''s friend, lies slain on the ground through my reversal of fortune.''', 'veda-app-ai-draft', true),
('ramayana-3-63-25', 'en', 'Saying this many times, Rama with Lakshmana touched Jatayu, showing a son''s love for a father.', 'veda-app-ai-draft', true),
('ramayana-3-63-26', 'en', 'Embracing the king of vultures, his wings cut off and drenched in blood, Rama cried, ''Where is Sita, dear as my life?'' and fell to the ground.', 'veda-app-ai-draft', true),
('ramayana-3-64-1', 'en', 'Looking at the vulture struck down on the ground by the fierce one, Rama said to Lakshmana, rich in friendship:', 'veda-app-ai-draft', true),
('ramayana-3-64-2', 'en', '''Surely this bird, striving for my cause, was killed in battle by the demon and is giving up the life so hard to give up.', 'veda-app-ai-draft', true),
('ramayana-3-64-3', 'en', 'There is still life in his body, Lakshmana, but he has lost his voice and looks up feebly.', 'veda-app-ai-draft', true),
('ramayana-3-64-4', 'en', 'Jatayu, if you can speak again, tell me of Sita, bless you, and tell me how you were killed.', 'veda-app-ai-draft', true),
('ramayana-3-64-5', 'en', 'Why did Ravana carry off Sita? What wrong have I done him, for which Ravana took my beloved?', 'veda-app-ai-draft', true),
('ramayana-3-64-6', 'en', 'How was her lovely moon-like face then? What did Sita say at that time, best of birds?', 'veda-app-ai-draft', true),
('ramayana-3-64-7', 'en', 'What is that demon''s strength, form and deeds? Where is his home, dear one? Tell me, I ask you.''', 'veda-app-ai-draft', true),
('ramayana-3-64-8', 'en', 'Looking up at him lamenting, wretched Jatayu said to Rama in a very faint voice:', 'veda-app-ai-draft', true),
('ramayana-3-64-9', 'en', '''She was carried off through the sky by Ravana, lord of demons, using great illusion filled with storm and wind.', 'veda-app-ai-draft', true),
('ramayana-3-64-10', 'en', 'When I was exhausted, dear one, the night-roamer cut off my wings, took Sita and went south.', 'veda-app-ai-draft', true),
('ramayana-3-64-11', 'en', 'My breath is failing, my sight wanders, Rama; I see golden trees with hair of ushira grass.', 'veda-app-ai-draft', true),
('ramayana-3-64-12', 'en', 'The hour in which Ravana carried off Sita is one in which lost wealth quickly returns to its owner.', 'veda-app-ai-draft', true),
('ramayana-3-64-13', 'en', 'That hour is called Vinda, and he did not know it, Rama; like a fish taking a hook, he will soon perish.', 'veda-app-ai-draft', true),
('ramayana-3-64-14', 'en', 'Do not grieve over Janaka''s daughter; you will soon be happy with Sita again, having killed that demon in battle.''', 'veda-app-ai-draft', true),
('ramayana-3-64-15', 'en', 'As the vulture, still clear-minded, spoke to Rama, blood with flesh flowed from his mouth as he died.', 'veda-app-ai-draft', true),
('ramayana-3-64-16', 'en', '''He is the son of Vishravas himself and brother of Kubera.'' Having said this, the lord of birds gave up his life, so hard to give up.', 'veda-app-ai-draft', true),
('ramayana-3-64-17', 'en', 'As Rama with joined palms said ''Speak, speak!'', the vulture''s life left his body and went to the sky.', 'veda-app-ai-draft', true),
('ramayana-3-64-18', 'en', 'He laid his head on the ground, stretched out his legs, and with his body flung out, fell to the earth.', 'veda-app-ai-draft', true),
('ramayana-3-64-19', 'en', 'Seeing the red-eyed vulture lifeless like a mountain, Rama, sad with many sorrows, said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-3-64-20', 'en', '''This bird lived happily for many years in the demons'' land and roamed here in the Dandaka forest.', 'veda-app-ai-draft', true),
('ramayana-3-64-21', 'en', 'He who lived many years and rose high for a long time now lies slain today; Time is hard to escape.', 'veda-app-ai-draft', true),
('ramayana-3-64-22', 'en', 'See, Lakshmana, this vulture, my helper, killed coming to rescue Sita by the stronger Ravana.', 'veda-app-ai-draft', true),
('ramayana-3-64-23', 'en', 'Leaving his great ancestral kingdom of vultures, the lord of birds gave up his life for my sake.', 'veda-app-ai-draft', true),
('ramayana-3-64-24', 'en', 'Truly the good, the righteous, the brave who give refuge are seen everywhere, Lakshmana, even among those born as animals.', 'veda-app-ai-draft', true),
('ramayana-3-64-25', 'en', 'The grief of Sita''s abduction does not affect me as much, gentle one, as the death of the vulture for my sake.', 'veda-app-ai-draft', true),
('ramayana-3-64-26', 'en', 'As glorious King Dasharatha was to me, so this lord of birds is worthy of honour and respect.', 'veda-app-ai-draft', true),
('ramayana-3-64-27', 'en', 'Lakshmana, bring wood; I will kindle fire. I want to cremate the king of vultures, who died for me.', 'veda-app-ai-draft', true),
('ramayana-3-64-28', 'en', 'I will place the lord of the bird world on the pyre; I will burn him, Lakshmana, killed by the fierce demon.', 'veda-app-ai-draft', true),
('ramayana-3-64-29', 'en', 'The path of those devoted to sacrifice, of those who keep the sacred fire, of those who never turn back in battle, and of those who give land,', 'veda-app-ai-draft', true),
('ramayana-3-64-30', 'en', 'go to those highest worlds with my leave, mighty king of vultures, and go cremated by me.''', 'veda-app-ai-draft', true),
('ramayana-3-64-31', 'en', 'Having said this, the righteous Rama placed the lord of birds on the blazing pyre and, grieving, burned him as he would his own kin.', 'veda-app-ai-draft', true),
('ramayana-3-64-32', 'en', 'Then the valiant Rama with Lakshmana went into the forest, killed large deer and spread them for the bird.', 'veda-app-ai-draft', true),
('ramayana-3-64-33', 'en', 'Taking out the flesh and making it into balls, the glorious Rama gave it to the bird on the lovely green grass.', 'veda-app-ai-draft', true),
('ramayana-3-64-34', 'en', 'Rama quickly recited what brahmins say for a dead mortal to go to heaven.', 'veda-app-ai-draft', true),
('ramayana-3-64-35', 'en', 'Then the two princes went to the Godavari river and made water offerings for the king of vultures.', 'veda-app-ai-draft', true),
('ramayana-3-64-36', 'en', 'That king of vultures, having done a glorious and very hard deed and fallen in battle, cremated as if he were a great seer, went to his own holy, auspicious destination.', 'veda-app-ai-draft', true),
('ramayana-3-65-1', 'en', 'Having made the water offering for him, the two Raghus set out, looking for Sita in the forest, and went toward the west.', 'veda-app-ai-draft', true),
('ramayana-3-65-2', 'en', 'Going that way to the south, bearing arrows, bows and swords, the two Ikshvakus took an untrodden path,', 'veda-app-ai-draft', true),
('ramayana-3-65-3', 'en', 'overgrown with many shrubs, trees and creepers, closed on all sides, hard to pass, dense and terrible to see.', 'veda-app-ai-draft', true),
('ramayana-3-65-4', 'en', 'Passing quickly through it, heading south, the two mighty ones crossed that very dreadful great forest.', 'veda-app-ai-draft', true),
('ramayana-3-65-5', 'en', 'Then, three krosas beyond Janasthana, the two mighty Raghus entered the dense Krauñcha forest.', 'veda-app-ai-draft', true),
('ramayana-3-65-6', 'en', 'It was like a mass of many clouds, as if joyful everywhere, with many lovely coloured flowers and herds of beasts and birds.', 'veda-app-ai-draft', true),
('ramayana-3-65-7', 'en', 'Wanting to see Sita, they searched that forest, stopping here and there, worn by Sita''s abduction.', 'veda-app-ai-draft', true),
('ramayana-3-65-8', 'en', 'Then radiant Lakshmana, strong, of good character and pure, said with joined palms to his blazing brother:', 'veda-app-ai-draft', true),
('ramayana-3-65-9', 'en', '''My arm throbs strongly and my mind seems agitated; I see mostly inauspicious omens.', 'veda-app-ai-draft', true),
('ramayana-3-65-10', 'en', 'So be ready, noble one, and take my advice; my omens tell of sudden danger.', 'veda-app-ai-draft', true),
('ramayana-3-65-11', 'en', 'This very dreadful bird named Vanchulaka cries out as if announcing our victory in battle.''', 'veda-app-ai-draft', true),
('ramayana-3-65-12', 'en', 'As they searched the whole forest with vigour, a great noise arose as if smashing the forest.', 'veda-app-ai-draft', true),
('ramayana-3-65-13', 'en', 'The dense forest seemed wrapped by a great wind; the sound of that forest seemed to fill the sky.', 'veda-app-ai-draft', true),
('ramayana-3-65-14', 'en', 'Seeking that sound, Rama with his brother saw in a thicket a huge demon with a broad chest.', 'veda-app-ai-draft', true),
('ramayana-3-65-15', 'en', 'The two came upon him standing before them, huge, without head or neck: Kabandha, with a mouth in his belly.', 'veda-app-ai-draft', true),
('ramayana-3-65-16', 'en', 'Covered with thick sharp hair, tall as a great mountain, like a dark cloud, fierce, with a voice like thunder,', 'veda-app-ai-draft', true),
('ramayana-3-65-17', 'en', 'with one terrible, swift-seeing eye in his chest, large, long and tawny with great lashes,', 'veda-app-ai-draft', true),
('ramayana-3-65-18', 'en', 'with great fangs, licking his huge mouth, eating very dreadful bears, lions, deer and elephants.', 'veda-app-ai-draft', true),
('ramayana-3-65-19', 'en', 'Stretching out two terrible arms, each a yojana long, he grabbed bears, flocks of birds and wild animals with his hands.', 'veda-app-ai-draft', true),
('ramayana-3-65-20', 'en', 'Dragging and tearing at many herds of deer, he stood blocking the path of the two brothers as they came.', 'veda-app-ai-draft', true),
('ramayana-3-65-21', 'en', 'Having gone on, after barely two miles they saw the huge, dreadful, frightening Kabandha, wrapped in his own arms.', 'veda-app-ai-draft', true),
('ramayana-3-65-22', 'en', 'The long-armed giant stretched out his vast arms and seized both Raghava brothers together, crushing them with force.', 'veda-app-ai-draft', true),
('ramayana-3-65-23', 'en', 'Though armed with swords and strong bows, fiery and mighty-armed, the two powerful brothers were dragged along helpless.', 'veda-app-ai-draft', true),
('ramayana-3-65-24', 'en', 'Kabandha, chief of the danavas, said to them: Who are you two, with shoulders like bulls, carrying great swords and bows?', 'veda-app-ai-draft', true),
('ramayana-3-65-25', 'en', 'You have come to this fearful place and present yourselves as my food. Tell me your business here and why you have come.', 'veda-app-ai-draft', true),
('ramayana-3-65-26', 'en', 'You have come here where I wait, tormented by hunger. Like sharp-horned bulls with your bows, arrows and swords, you have reached my mouth, and life will be hard to regain.', 'veda-app-ai-draft', true),
('ramayana-3-65-27', 'en', 'Hearing the words of the wicked Kabandha, Rama spoke to Lakshmana, his face drawn and dry.', 'veda-app-ai-draft', true),
('ramayana-3-65-28', 'en', 'Lakshmana, true in valour, we have gone from one hardship to a worse one, and now, without having found my beloved, a disaster has come that will end our lives.', 'veda-app-ai-draft', true),
('ramayana-3-65-29', 'en', 'Great is the power of Time over all beings, Lakshmana. See how you and I are bewildered by misfortunes. Nothing is too heavy a burden for fate to place on any creature.', 'veda-app-ai-draft', true),
('ramayana-3-65-30', 'en', 'Brave, strong warriors skilled in weapons, when struck by Time, sink on the battlefield like dams of sand.', 'veda-app-ai-draft', true),
('ramayana-3-65-31', 'en', 'Saying this, the famous and mighty son of Dasharatha, firm in truth and courage, looked at Lakshmana, whose strength was rising, and steadied his own mind.', 'veda-app-ai-draft', true),
('ramayana-3-66-1', 'en', 'Seeing the brothers Rama and Lakshmana standing there, caught in the noose of his arms, Kabandha spoke.', 'veda-app-ai-draft', true),
('ramayana-3-66-2', 'en', 'Why do you just stand there staring at me, best of warriors, when I am starving? Fate has sent you to me as food, and your wits are gone.', 'veda-app-ai-draft', true),
('ramayana-3-66-3', 'en', 'Hearing this, Lakshmana, troubled but resolved to fight, spoke words that were timely and helpful.', 'veda-app-ai-draft', true),
('ramayana-3-66-4', 'en', 'Before this lowest of demons quickly swallows you and me, let us at once cut off his heavy arms with our swords.', 'veda-app-ai-draft', true),
('ramayana-3-66-5', 'en', 'Then the two Raghavas, knowing the right time and place, gladly cut his arms off at the shoulders with their swords.', 'veda-app-ai-draft', true),
('ramayana-3-66-6', 'en', 'Rama, standing on the right, swiftly cut off the right arm with his sword, and heroic Lakshmana the left.', 'veda-app-ai-draft', true),
('ramayana-3-66-7', 'en', 'With his arms cut off, the mighty one fell with a great roar, filling sky, earth and the directions like a thundercloud.', 'veda-app-ai-draft', true),
('ramayana-3-66-8', 'en', 'Seeing his arms cut away and streaming with blood, the danava miserably asked the two heroes: Who are you?', 'veda-app-ai-draft', true),
('ramayana-3-66-9', 'en', 'As he said this, the mighty Lakshmana, bearing auspicious marks, told Kabandha about Rama, the descendant of Kakutstha.', 'veda-app-ai-draft', true),
('ramayana-3-66-10', 'en', 'This is the heir of the Ikshvakus, known among people as Rama. Know me as his younger brother Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-66-11', 'en', 'While this godlike man lived in the lonely forest, a demon carried off his wife, and we have come here searching for her.', 'veda-app-ai-draft', true),
('ramayana-3-66-12', 'en', 'But who are you, and why do you roll about in the forest like a headless trunk, with a blazing mouth in your chest and broken legs?', 'veda-app-ai-draft', true),
('ramayana-3-66-13', 'en', 'Addressed this way by Lakshmana, Kabandha was overjoyed, remembering the words of Indra, and replied.', 'veda-app-ai-draft', true),
('ramayana-3-66-14', 'en', 'Welcome, tigers among men! By good fortune I see you, and by good fortune you have cut off these arms that bound me.', 'veda-app-ai-draft', true),
('ramayana-3-66-15', 'en', 'Hear from me truthfully, tiger among men, how I came to have this deformed shape through my own arrogance.', 'veda-app-ai-draft', true),
('ramayana-3-67-1', 'en', 'Long ago, mighty Rama, I had a form beyond imagining, famous in the three worlds, like the beauty of the moon, Indra and the sun.', 'veda-app-ai-draft', true),
('ramayana-3-67-2', 'en', 'Taking on this terrifying shape that frightened the world, I went about scaring the sages living in the forest.', 'veda-app-ai-draft', true),
('ramayana-3-67-3', 'en', 'Then I angered a great sage named Sthulashiras, frightening him with this form while he gathered forest food.', 'veda-app-ai-draft', true),
('ramayana-3-67-4', 'en', 'Seeing me like this, he pronounced a terrible curse: Let this cruel, despised form be yours forever.', 'veda-app-ai-draft', true),
('ramayana-3-67-5', 'en', 'I begged the angry sage to set an end to the curse, and he said these words.', 'veda-app-ai-draft', true),
('ramayana-3-67-6', 'en', 'When Rama cuts off your arms and burns you in the lonely forest, you will regain your own vast and beautiful form.', 'veda-app-ai-draft', true),
('ramayana-3-67-7', 'en', 'Know me, Lakshmana, as a son of Danu, shining with glory. This shape also came upon me from Indra''s anger in battle.', 'veda-app-ai-draft', true),
('ramayana-3-67-8', 'en', 'By fierce austerity I pleased Brahma, the Grandfather. He gave me long life, and then pride took hold of me.', 'veda-app-ai-draft', true),
('ramayana-3-67-9', 'en', 'I have long life, what can Indra do to me? Thinking this, I attacked Indra in battle.', 'veda-app-ai-draft', true),
('ramayana-3-67-10', 'en', 'With the hundred-jointed thunderbolt thrown from his arm, Indra drove my thighs and head down into my body.', 'veda-app-ai-draft', true),
('ramayana-3-67-11', 'en', 'Though I begged him, he did not send me to the realm of Yama, saying: Let the Grandfather''s word stay true.', 'veda-app-ai-draft', true),
('ramayana-3-67-12', 'en', 'How can I live a long time without food, with thighs, head and mouth smashed by the thunderbolt?', 'veda-app-ai-draft', true),
('ramayana-3-67-13', 'en', 'When I said this, Indra gave me arms a yojana long and made a mouth with sharp teeth in my belly.', 'veda-app-ai-draft', true),
('ramayana-3-67-14', 'en', 'So with these long arms I drag in forest creatures, lions, elephants, deer and tigers, and eat them all around.', 'veda-app-ai-draft', true),
('ramayana-3-67-15', 'en', 'Indra told me: When Rama with Lakshmana cuts off your arms in battle, you will go to heaven.', 'veda-app-ai-draft', true),
('ramayana-3-67-16', 'en', 'You are Rama, may good fortune be with you. No one else could kill me, Raghava, just as the great sage said.', 'veda-app-ai-draft', true),
('ramayana-3-67-17', 'en', 'Once I am purified by fire, best of men, I will help you with counsel and point you to a friend.', 'veda-app-ai-draft', true),
('ramayana-3-67-18', 'en', 'Addressed this way by the son of Danu, righteous Rama said these words while Lakshmana listened.', 'veda-app-ai-draft', true),
('ramayana-3-67-19', 'en', 'Ravana has carried off my famous wife Sita, when I had left Janasthana with my brother.', 'veda-app-ai-draft', true),
('ramayana-3-67-20', 'en', 'I know only that demon''s name, not his appearance. We do not know where he lives or how powerful he is.', 'veda-app-ai-draft', true),
('ramayana-3-67-21', 'en', 'We are stricken with grief, without help, running about like this. Show us the compassion that fits, and help us.', 'veda-app-ai-draft', true),
('ramayana-3-67-22', 'en', 'Bringing dry wood broken long ago by elephants, we will burn you, hero, in a great pit we have made.', 'veda-app-ai-draft', true),
('ramayana-3-67-23', 'en', 'So tell us of Sita, who took her or where, and do us this great kindness if you truly know.', 'veda-app-ai-draft', true),
('ramayana-3-67-24', 'en', 'Spoken to this way by Rama, Danu''s son, skilled in speech, gave a fine reply to Raghava, himself an able speaker.', 'veda-app-ai-draft', true),
('ramayana-3-67-25', 'en', 'I do not have divine knowledge and do not know Maithili. Once burned and restored to my own form, I will tell you of one who will know her.', 'veda-app-ai-draft', true),
('ramayana-3-67-26', 'en', 'Until I am burned, lord, I have no power to know that mighty demon who took your Sita.', 'veda-app-ai-draft', true),
('ramayana-3-67-27', 'en', 'Through the curse my great wisdom was lost, Raghava, and by my own deeds I got this form that the world despises.', 'veda-app-ai-draft', true),
('ramayana-3-67-28', 'en', 'But before the sun, its horses weary, sets, throw me into a pit and burn me, Rama, with proper rites.', 'veda-app-ai-draft', true),
('ramayana-3-67-29', 'en', 'Once burned properly by you in the pit, I will tell you, hero, of the one who will know that demon.', 'veda-app-ai-draft', true),
('ramayana-3-67-30', 'en', 'You should make friends with him, Raghava, as he is just in conduct. Pleased, that swift hero will give you help.', 'veda-app-ai-draft', true),
('ramayana-3-67-31', 'en', 'Nothing in the three worlds is unknown to him, Raghava, for long ago he roamed all the worlds for a certain reason.', 'veda-app-ai-draft', true),
('ramayana-3-68-1', 'en', 'Told this by Kabandha, the two heroic princes went to a mountain hollow and lit a fire.', 'veda-app-ai-draft', true),
('ramayana-3-68-2', 'en', 'Lakshmana lit the pyre on all sides with great blazing torches, and it burned everywhere.', 'veda-app-ai-draft', true),
('ramayana-3-68-3', 'en', 'The fire slowly burned Kabandha''s huge body, which was like a lump of ghee as its fat melted.', 'veda-app-ai-draft', true),
('ramayana-3-68-4', 'en', 'Shaking off the pyre, the mighty one rose quickly like a smokeless flame, wearing spotless garments and a heavenly garland.', 'veda-app-ai-draft', true),
('ramayana-3-68-5', 'en', 'Then, shining, in clean robes, joyful and adorned on every limb, he sprang swiftly from the pyre.', 'veda-app-ai-draft', true),
('ramayana-3-68-6', 'en', 'Standing in a glorious bright chariot drawn by swans, the radiant one lit up the ten directions with his glow.', 'veda-app-ai-draft', true),
('ramayana-3-68-7', 'en', 'Rising into the sky, Kabandha said to Rama: Hear truly, Raghava, how you will regain Sita.', 'veda-app-ai-draft', true),
('ramayana-3-68-8', 'en', 'Rama, there are six means in the world by which everything is weighed. One struck by misfortune is served only by another in misfortune.', 'veda-app-ai-draft', true),
('ramayana-3-68-9', 'en', 'You and Lakshmana have fallen into a bad state, which is why you have met the disaster of your wife being taken.', 'veda-app-ai-draft', true),
('ramayana-3-68-10', 'en', 'So you must surely make a friend, best of friends. Thinking it over, I see no success for you without doing so.', 'veda-app-ai-draft', true),
('ramayana-3-68-11', 'en', 'Listen, Rama, I will tell you. There is a monkey named Sugriva, driven out by his angry brother Vali, son of Indra.', 'veda-app-ai-draft', true),
('ramayana-3-68-12', 'en', 'The self-controlled hero lives with four monkeys on Rishyamuka, the best of mountains, which is graced by the shores of the Pampa.', 'veda-app-ai-draft', true),
('ramayana-3-68-13', 'en', 'Go there quickly today, Raghava, and make him your companion, meeting him to pledge loyalty before a blazing fire.', 'veda-app-ai-draft', true),
('ramayana-3-68-14', 'en', 'Do not look down on Sugriva, lord of the monkeys. He is grateful, can change form at will, needs help himself, and is brave.', 'veda-app-ai-draft', true),
('ramayana-3-68-15', 'en', 'You two can now accomplish what he wants done. Whether his goal is met or not, he will do your task.', 'veda-app-ai-draft', true),
('ramayana-3-68-16', 'en', 'He, son of Rikshrajas and true son of the Sun, wanders the Pampa in fear, wronged by Vali.', 'veda-app-ai-draft', true),
('ramayana-3-68-17', 'en', 'Quickly lay down your weapons and, with truth, make that forest-dwelling monkey of Rishyamuka your friend, Raghava.', 'veda-app-ai-draft', true),
('ramayana-3-68-18', 'en', 'That great monkey knows thoroughly all the places of the man-eaters in the world.', 'veda-app-ai-draft', true),
('ramayana-3-68-19', 'en', 'Nothing in the world is unknown to him, Raghava, as far as the thousand-rayed sun shines.', 'veda-app-ai-draft', true),
('ramayana-3-68-20', 'en', 'Searching rivers, great mountains, mountain strongholds and caves with the monkeys, he will find your wife.', 'veda-app-ai-draft', true),
('ramayana-3-68-21', 'en', 'He will send huge monkeys in every direction, Raghava, to look for Sita, grieving at being parted from you.', 'veda-app-ai-draft', true),
('ramayana-3-68-22', 'en', 'Whether your blameless beloved is on the peak of Meru or hidden in the underworld, that best of monkeys will kill the demons and give her back to you.', 'veda-app-ai-draft', true),
('ramayana-3-69-1', 'en', 'Having shown Rama how Sita could be recovered, Kabandha, who understood purpose, spoke again with meaningful words.', 'veda-app-ai-draft', true),
('ramayana-3-69-2', 'en', 'This is the good road, Rama, where these flowering trees shine beautifully, heading toward the west.', 'veda-app-ai-draft', true),
('ramayana-3-69-3', 'en', 'Rose-apple, priyala, jackfruit, plaksha, banyan, tinduka, peepal, karnikara, mango and other trees.', 'veda-app-ai-draft', true),
('ramayana-3-69-4', 'en', 'Climbing them, or pulling them to the ground, you will eat fruits like nectar as you go.', 'veda-app-ai-draft', true),
('ramayana-3-69-5', 'en', 'Walking through fine country, from hill to hill and forest to forest, you heroes will reach the lake named Pampa.', 'veda-app-ai-draft', true),
('ramayana-3-69-6', 'en', 'Its bed has no gravel, its banks do not slip, its steps are even and it has no weeds. It has fine sand, Rama, and is lovely with lotuses and lilies.', 'veda-app-ai-draft', true),
('ramayana-3-69-7', 'en', 'There swans, plavas, cranes and ospreys that live on the Pampa''s water call sweetly, Raghava.', 'veda-app-ai-draft', true),
('ramayana-3-69-8', 'en', 'These gentle birds, who do not know of killing, are not afraid when they see people. You will eat those plump birds, like lumps of ghee.', 'veda-app-ai-draft', true),
('ramayana-3-69-9', 'en', 'Rohita, vakratunda and nalamina fish, Rama, the best fish, shot with arrows in the Pampa.', 'veda-app-ai-draft', true),
('ramayana-3-69-10', 'en', 'Lakshmana, full of devotion to you, will give you fish without skin or fins, roasted on iron, plump and with a single bone.', 'veda-app-ai-draft', true),
('ramayana-3-69-11', 'en', 'As you eat the fish among the heaps of flowers at Pampa, the water there is lotus-scented, pure, pleasantly cool and wholesome.', 'veda-app-ai-draft', true),
('ramayana-3-69-12', 'en', 'Lakshmana will draw up that clear water, like silver and crystal, and give it to you to drink from a lotus leaf.', 'veda-app-ai-draft', true),
('ramayana-3-69-13', 'en', 'You will see at Pampa, best of men, fat boars that sleep in mountain caves and roam the forest, coming down for water and bellowing like bulls.', 'veda-app-ai-draft', true),
('ramayana-3-69-14', 'en', 'Wandering there in the evening, Rama, seeing the trees hung with blossoms and the cool water of the Pampa, you will put aside your grief.', 'veda-app-ai-draft', true),
('ramayana-3-69-15', 'en', 'There, Raghava, are tilaka and naktamala trees covered in flowers, blooming water lilies and lotuses.', 'veda-app-ai-draft', true),
('ramayana-3-69-16', 'en', 'No one plants those garlands of flowers there. The disciples of Matanga, sages of deep concentration, once lived there.', 'veda-app-ai-draft', true),
('ramayana-3-69-17', 'en', 'As they carried forest produce for their teacher and were exhausted by the loads, drops of sweat fell quickly from their bodies to the earth.', 'veda-app-ai-draft', true),
('ramayana-3-69-18', 'en', 'Those drops became flowers through the sages'' austerity, Raghava, and arising from sweat, they never fade.', 'veda-app-ai-draft', true),
('ramayana-3-69-19', 'en', 'Even now their attendant, an ascetic woman named Shabari, is seen there, living to a great age, Kakutstha.', 'veda-app-ai-draft', true),
('ramayana-3-69-20', 'en', 'Always steady in dharma, once she sees you, Rama, honoured by all beings and like a god, she will go to heaven.', 'veda-app-ai-draft', true),
('ramayana-3-69-21', 'en', 'Then, Rama, reaching the western shore of the Pampa, you will see an incomparable, hidden hermitage, Kakutstha.', 'veda-app-ai-draft', true),
('ramayana-3-69-22', 'en', 'Elephants cannot enter that hermitage or its forest, by the decree of the sage Matanga.', 'veda-app-ai-draft', true),
('ramayana-3-69-23', 'en', 'In that forest, like Indra''s garden, like a forest of the gods and full of many birds, you will find contentment, Rama.', 'veda-app-ai-draft', true),
('ramayana-3-69-24', 'en', 'Before the Pampa stands Rishyamuka, with flowering trees, very hard to climb and guarded by young elephants. It was made long ago by Brahma himself.', 'veda-app-ai-draft', true),
('ramayana-3-69-25', 'en', 'A man who sleeps on the peak of that mountain, Rama, gains on waking the wealth he dreamed of.', 'veda-app-ai-draft', true),
('ramayana-3-69-26', 'en', 'But no one of crooked conduct and sinful deeds can climb it. Demons seize such a man while he sleeps and strike him there.', 'veda-app-ai-draft', true),
('ramayana-3-69-27', 'en', 'From there too, Rama, comes the loud trumpeting of young elephants playing at the Pampa, living in Matanga''s forest.', 'veda-app-ai-draft', true),
('ramayana-3-69-28', 'en', 'Great elephants, dark as clouds and swift, sprinkled with streams of red ichor, gather and then roam apart.', 'veda-app-ai-draft', true),
('ramayana-3-69-29', 'en', 'After drinking the clear, cool, never-failing water there, the forest creatures turn back and plunge into the woods.', 'veda-app-ai-draft', true),
('ramayana-3-69-30', 'en', 'Rama, on that mountain there is a great shining cave, closed with a stone, Kakutstha, and hard to enter.', 'veda-app-ai-draft', true),
('ramayana-3-69-31', 'en', 'At the east entrance of that cave is a large lake of cool water, lovely, rich in roots and fruits and surrounded by many trees.', 'veda-app-ai-draft', true),
('ramayana-3-69-32', 'en', 'Sugriva lives in it with four monkeys, and sometimes he stays on the summit of that mountain.', 'veda-app-ai-draft', true),
('ramayana-3-69-33', 'en', 'Having instructed Rama and Lakshmana in this way, mighty Kabandha, wearing a garland and shining like the sun, glowed in the sky.', 'veda-app-ai-draft', true),
('ramayana-3-69-34', 'en', 'As they set out, Rama and Lakshmana said to the noble Kabandha in the sky close by: Go now.', 'veda-app-ai-draft', true),
('ramayana-3-69-35', 'en', 'He said to them: Go, for the success of your task. Taking leave of the two, who were well pleased, Kabandha departed.', 'veda-app-ai-draft', true),
('ramayana-3-69-36', 'en', 'Having regained his form, glorious with a body like the sun, Kabandha looked at Rama from the sky and said once more: Make that friendship.', 'veda-app-ai-draft', true),
('ramayana-3-70-1', 'en', 'The two princes took the road to the Pampa that Kabandha had shown them in the forest, heading toward the west.', 'veda-app-ai-draft', true),
('ramayana-3-70-2', 'en', 'Rama and Lakshmana went on to see Sugriva, gazing at the many trees on the hills with fruits sweet as honey.', 'veda-app-ai-draft', true),
('ramayana-3-70-3', 'en', 'Spending the night on a mountain ridge, the two Raghavas came to the western shore of the Pampa.', 'veda-app-ai-draft', true),
('ramayana-3-70-4', 'en', 'Reaching the western shore of the lotus lake Pampa, they saw there the lovely hermitage of Shabari.', 'veda-app-ai-draft', true),
('ramayana-3-70-5', 'en', 'Coming to that hermitage, surrounded by many trees and very charming, they looked around and approached Shabari.', 'veda-app-ai-draft', true),
('ramayana-3-70-6', 'en', 'Seeing them, the accomplished ascetic rose with folded hands and touched the feet of Rama and wise Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-70-7', 'en', 'Then Rama said to the ascetic, firm in her vows: Have you overcome obstacles? Is your austerity growing?', 'veda-app-ai-draft', true),
('ramayana-3-70-8', 'en', 'Have you mastered anger and diet, rich in austerity? Are your observances kept, is your mind at peace? Has your service to your teachers borne fruit, gentle speaker?', 'veda-app-ai-draft', true),
('ramayana-3-70-9', 'en', 'Asked by Rama, the aged Shabari, an accomplished ascetic respected by the perfected ones, stood before Rama and replied.', 'veda-app-ai-draft', true),
('ramayana-3-70-10', 'en', 'When you arrived at Chitrakuta, the sages I served rose from here to heaven in chariots of matchless brilliance.', 'veda-app-ai-draft', true),
('ramayana-3-70-11', 'en', 'Those great sages who knew dharma told me: Rama will come to this holy hermitage of yours.', 'veda-app-ai-draft', true),
('ramayana-3-70-12', 'en', 'You must receive him as a guest along with Lakshmana. Seeing him, you will go to the best, undying worlds.', 'veda-app-ai-draft', true),
('ramayana-3-70-13', 'en', 'Best of men, I have gathered many kinds of forest food for you from the banks of the Pampa.', 'veda-app-ai-draft', true),
('ramayana-3-70-14', 'en', 'Hearing this from Shabari, righteous Raghava said to her, who was never outside true knowledge:', 'veda-app-ai-draft', true),
('ramayana-3-70-15', 'en', 'I have heard truly from Danu''s son of the power of your great teachers. If you think fit, I wish to see it with my own eyes.', 'veda-app-ai-draft', true),
('ramayana-3-70-16', 'en', 'Hearing these words from Rama''s mouth, Shabari showed the two of them that great forest.', 'veda-app-ai-draft', true),
('ramayana-3-70-17', 'en', 'See, joy of the Raghus, this forest dense like a mass of clouds and full of animals and birds, famous as Matanga''s forest.', 'veda-app-ai-draft', true),
('ramayana-3-70-18', 'en', 'Here, radiant one, my teachers, their souls perfected, made offerings into the fire at this sacred place honoured with mantras.', 'veda-app-ai-draft', true),
('ramayana-3-70-19', 'en', 'This is the altar to the west where those honoured ones offered flowers with hands trembling from effort.', 'veda-app-ai-draft', true),
('ramayana-3-70-20', 'en', 'By the power of their austerity, best of the Raghus, see how even today these altars light up every direction with matchless glow.', 'veda-app-ai-draft', true),
('ramayana-3-70-21', 'en', 'When they were too weak from fasting to go, the seven seas came at their mere thought. See them gathered here.', 'veda-app-ai-draft', true),
('ramayana-3-70-22', 'en', 'The bark garments they hung on the trees after bathing still have not dried, joy of the Raghus.', 'veda-app-ai-draft', true),
('ramayana-3-70-23', 'en', 'You have seen this whole forest and heard what was to be heard. With your permission I wish to leave this body.', 'veda-app-ai-draft', true),
('ramayana-3-70-24', 'en', 'I wish to go to those sages of perfected soul whose hermitage this is and whom I served.', 'veda-app-ai-draft', true),
('ramayana-3-70-25', 'en', 'Hearing her righteous words, Raghava with Lakshmana said with a joyful face: I give you leave, go.', 'veda-app-ai-draft', true),
('ramayana-3-70-26', 'en', 'Permitted by Rama, she offered herself into the fire and, shining like a blazing flame, went straight to heaven.', 'veda-app-ai-draft', true),
('ramayana-3-70-27', 'en', 'Through her self-absorption she went to that holy place where those great sages of good deeds dwell.', 'veda-app-ai-draft', true),
('ramayana-3-71-1', 'en', 'When Shabari had gone to heaven by her own deeds, Raghava reflected together with his brother Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-71-2', 'en', 'Reflecting on the power of those great souls, righteous Raghava spoke to Lakshmana, focused and devoted to his good.', 'veda-app-ai-draft', true),
('ramayana-3-71-3', 'en', 'We have seen this hermitage of the perfected ones, gentle brother, full of wonders, where deer and tigers trust each other and many birds live.', 'veda-app-ai-draft', true),
('ramayana-3-71-4', 'en', 'At these sacred places of the seven seas, Lakshmana, we have bathed by the rites and made offerings to our ancestors.', 'veda-app-ai-draft', true),
('ramayana-3-71-5', 'en', 'Whatever was inauspicious is gone and good fortune is here. So my mind is now cheerful, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-3-71-6', 'en', 'Something good will appear in my heart, tiger among men. So come, let us go to that lovely Pampa.', 'veda-app-ai-draft', true),
('ramayana-3-71-7', 'en', 'Not far off shines Mount Rishyamuka, where righteous Sugriva, son of the sun, lives with four monkeys, always afraid of Vali.', 'veda-app-ai-draft', true),
('ramayana-3-71-8', 'en', 'I am eager to see that bull among monkeys, Sugriva, for the search for Sita depends on him, gentle brother.', 'veda-app-ai-draft', true),
('ramayana-3-71-9', 'en', 'As Rama spoke, Lakshmana said: Let us go there quickly. My mind is eager too.', 'veda-app-ai-draft', true),
('ramayana-3-71-10', 'en', 'Leaving that hermitage, the lord of the people, with Lakshmana, came to the Pampa.', 'veda-app-ai-draft', true),
('ramayana-3-71-11', 'en', 'He gazed at the great forest, full of flowers and great trees everywhere, ringing with koyashti, arjunaka, shatapatra and kichaka birds and many others.', 'veda-app-ai-draft', true),
('ramayana-3-71-12', 'en', 'Seeing many trees and lakes, Rama, burning with longing, went on to the great lake.', 'veda-app-ai-draft', true),
('ramayana-3-71-13', 'en', 'Reaching from afar the water-bearing lake named Matanga''s Lake, Rama plunged into it.', 'veda-app-ai-draft', true),
('ramayana-3-71-14', 'en', 'Overcome with grief, Rama, son of Dasharatha, entered the lotus-covered Pampa.', 'veda-app-ai-draft', true),
('ramayana-3-71-15', 'en', 'It shone with tilaka, ashoka, punnaga, bakula and uddala trees, crowded with lovely gardens, its water pressed with lotuses.', 'veda-app-ai-draft', true),
('ramayana-3-71-16', 'en', 'It was full of crystal-clear water, spread with smooth sand, crowded with fish and turtles, and adorned with trees on its banks.', 'veda-app-ai-draft', true),
('ramayana-3-71-17', 'en', 'Wrapped by vines like companions, visited by kinnaras, serpents, gandharvas, yakshas and rakshasas, full of trees and creepers, a lovely store of cool water.', 'veda-app-ai-draft', true),
('ramayana-3-71-18', 'en', 'Red with fragrant lotuses, white with circles of water lilies, blue with clusters of blue lilies, it was many-coloured like a woven rug.', 'veda-app-ai-draft', true),
('ramayana-3-71-19', 'en', 'It had day lotuses and lilies, fragrant blossoms, flowering mango groves and the cries of peacocks.', 'veda-app-ai-draft', true),
('ramayana-3-71-20', 'en', 'Seeing that Pampa with Lakshmana, radiant Rama, son of Dasharatha, lamented out of longing.', 'veda-app-ai-draft', true),
('ramayana-3-71-21', 'en', 'With tilaka, citron, banyan and white trees, with flowering karavira and blossoming punnaga trees,', 'veda-app-ai-draft', true),
('ramayana-3-71-22', 'en', 'with jasmine and kunda bushes, bhandira, nichula, ashoka, saptaparna, ketaka and atimuktaka, and many other trees, it shone like a lovely woman.', 'veda-app-ai-draft', true),
('ramayana-3-71-23', 'en', 'On its shore is the mountain mentioned before, adorned with minerals, called Rishyamuka, with forests of bright flowers.', 'veda-app-ai-draft', true),
('ramayana-3-71-24', 'en', 'The son of the great monkey Rikshraja, the mighty Sugriva, lives on it.', 'veda-app-ai-draft', true),
('ramayana-3-71-25', 'en', 'Go to Sugriva, king of monkeys, best of men. So Rama said again to Lakshmana, true in valour.', 'veda-app-ai-draft', true),
('ramayana-3-71-26', 'en', 'Then, slowly travelling a great, long road and gazing at the forest, he saw the Pampa with its lovely woods, full of many kinds of birds.', 'veda-app-ai-draft', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values
('ramayana-3-1-1', 'en', 'The exile enters its next stage: the deep forest, where holy people live.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"Dandakaranya","meaning":"the Dandaka forest"},{"word":"ashrama","meaning":"hermitage"},{"word":"tapasa","meaning":"ascetic"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-2', 'en', 'The hermitage glowed with the power of holy living.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"kusha","meaning":"sacred grass"},{"word":"brahmi lakshmi","meaning":"spiritual splendour"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-3', 'en', 'It was a safe place for every living being, kept clean and holy.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"sharanya","meaning":"refuge"},{"word":"apsaras","meaning":"celestial dancers"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-4', 'en', 'The place was full of the simple tools of daily worship.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"agnisharana","meaning":"fire shrine"},{"word":"sruk","meaning":"sacrificial ladle"},{"word":"samidh","meaning":"firewood for offerings"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-5', 'en', 'Nature and prayer filled the hermitage together.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"bali","meaning":"offering"},{"word":"homa","meaning":"fire oblation"},{"word":"brahmaghosha","meaning":"sound of Vedic chanting"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-6', 'en', 'The sages lived simply and with self-discipline.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"danta","meaning":"self-controlled"},{"word":"chira","meaning":"bark garment"},{"word":"krishnajina","meaning":"black deerskin"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-7', 'en', 'Old and holy sages, shining with their practice, lived there.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"maharshi","meaning":"great sage"},{"word":"niyatahara","meaning":"restrained in eating"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-8', 'en', 'The hermitage felt like heaven on earth.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"brahmavid","meaning":"knower of Brahman"},{"word":"brahmabhavana","meaning":"abode of Brahma"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-9', 'en', 'Rama lowered his weapon out of respect before entering a holy place.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them. Unstringing the bow is a sign of peaceful intent.', '[{"word":"vijya","meaning":"unstrung"},{"word":"dhanus","meaning":"bow"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-10', 'en', 'The sages were glad to see Rama and Sita.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"divyajnana","meaning":"divine knowledge"},{"word":"maharshi","meaning":"great seer"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-11', 'en', 'The sages blessed Rama as he arrived.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"mangala","meaning":"auspicious blessing"},{"word":"dridhavrata","meaning":"firm in vows"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-12', 'en', 'Even in exile Rama''s nobility shone through.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"saukumarya","meaning":"gentleness"},{"word":"lakshmi","meaning":"grace, splendour"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-13', 'en', 'The three were a marvel to the sages.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"animisha","meaning":"unblinking"},{"word":"ashcharya","meaning":"wonder"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-14', 'en', 'The sages welcomed Rama as an honoured guest.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"atithi","meaning":"guest"},{"word":"parnashala","meaning":"leaf hut"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-15', 'en', 'They offered him the traditional welcome.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"satkritya","meaning":"having honoured"},{"word":"salila","meaning":"water"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-16', 'en', 'The sages gave all they had, then made a humble request.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"pranjali","meaning":"with joined palms"},{"word":"dharmajna","meaning":"knower of dharma"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-17', 'en', 'A true ruler protects what is right and shelters his people.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"dharmapala","meaning":"protector of dharma"},{"word":"dandadhara","meaning":"bearer of the rod of justice"},{"word":"guru","meaning":"elder, revered one"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-18', 'en', 'A ruler''s privileges come with the duty to protect.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"Indra","meaning":"king of the gods"},{"word":"praja","meaning":"subjects"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-19', 'en', 'Rama is still their king, even in exile.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"rakshya","meaning":"to be protected"},{"word":"janeshvara","meaning":"lord of people"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-20', 'en', 'Those who have given up violence rely on the just to protect them.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"nyastadanda","meaning":"having renounced force"},{"word":"jitakrodha","meaning":"anger conquered"},{"word":"tapodhana","meaning":"one whose wealth is austerity"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-21', 'en', 'The sages showed their love with simple gifts.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"apujayan","meaning":"they honoured"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-1-22', 'en', 'All the sages welcomed Rama fittingly.', 'Aranya Kanda, chapter 1: Rama, Sita and Lakshmana enter the Dandaka forest and are welcomed by the sages living there, who ask Rama to protect them.', '[{"word":"siddha","meaning":"perfected one"},{"word":"nyayavritta","meaning":"just in conduct"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-1', 'en', 'Rama moved on into the wild, dangerous forest.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"atithya","meaning":"hospitality"},{"word":"amantrya","meaning":"taking leave"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-2', 'en', 'The forest became dark and threatening.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"shardula","meaning":"tiger"},{"word":"vrika","meaning":"wolf"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-3', 'en', 'They went into the deep forest.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"jhillika","meaning":"cricket"},{"word":"vanamadhya","meaning":"heart of the forest"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-4', 'en', 'A terrifying demon appeared.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"purushada","meaning":"man-eater"},{"word":"girishringa","meaning":"mountain peak"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-5', 'en', 'The demon looked horrible.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"vikata","meaning":"monstrous"},{"word":"bibhatsa","meaning":"loathsome"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-6', 'en', 'He was like death itself.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"antaka","meaning":"Death, the ender"},{"word":"vyaditasya","meaning":"with gaping mouth"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-7', 'en', 'He carried his kills with him.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"prishata","meaning":"spotted deer"},{"word":"gaja","meaning":"elephant"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-8', 'en', 'He saw the three travellers.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"shula","meaning":"spear, pike"},{"word":"Maithili","meaning":"Sita, princess of Mithila"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-9', 'en', 'The demon charged.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"bhairava","meaning":"terrifying"},{"word":"medini","meaning":"earth"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-10', 'en', 'He seized Sita and mocked the brothers.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"jata","meaning":"matted hair"},{"word":"kshinajivita","meaning":"whose life is spent"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-11', 'en', 'He accused them of being false ascetics.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"sharachapa","meaning":"arrows and bow"},{"word":"pramada","meaning":"young woman"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-12', 'en', 'He named himself.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"Viradha","meaning":"name of the demon"},{"word":"munidushaka","meaning":"corrupter of sages"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-13', 'en', 'He threatened them with death and claimed Sita.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"rishimamsa","meaning":"flesh of sages"},{"word":"rudhira","meaning":"blood"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-14', 'en', 'Sita shook with terror.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"kadali","meaning":"plantain tree"},{"word":"udvega","meaning":"fear"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-15', 'en', 'Rama was shaken with fear for Sita.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"parishushyata","meaning":"drying up"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
('ramayana-3-2-16', 'en', 'Rama grieved to see Sita in danger.', 'Aranya Kanda, chapter 2: the demon Viradha attacks, seizes Sita, and Rama is overcome with grief while Lakshmana vows to kill the demon.', '[{"word":"atmasambhava","meaning":"daughter"},{"word":"shubhachara","meaning":"of good conduct"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
