insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 1 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-1-1', 1, 'Kishkindha Kanda, Sarga 1, Verse 1', 'स तां पुष्करिणीं गत्वा पद्मोत्पलझषाकुलाम्।
रामः सौमित्रिसहितो विललापाकुलेन्द्रियः॥', 'sa tāṃ puṣkariṇīṃ gatvā padmotpalajhaṣākulām
rāmaḥ saumitrisahito vilalāpākulendriyaḥ', null, 4001001),
('ramayana-4-1-2', 2, 'Kishkindha Kanda, Sarga 1, Verse 2', 'तस्य दृष्ट्वैव तां हर्षादिन्द्रियाणि चकम्पिरे।
स कामवशमापन्नः सौमित्रिमिदमब्रवीत्॥', 'tasya dṛṣṭvaiva tāṃ harṣād indriyāṇi cakampire
sa kāmavaśam āpannaḥ saumitrim idam abravīt', null, 4001002),
('ramayana-4-1-3', 3, 'Kishkindha Kanda, Sarga 1, Verse 3', 'सौमित्रे पश्य पम्पायाः काननं शुभदर्शनम्।
यत्र राजन्ति शैलाभा द्रुमाः सशिखरा इव॥', 'saumitre paśya pampāyāḥ kānanaṃ śubhadarśanam
yatra rājanti śailābhā drumāḥ saśikharā iva', null, 4001003),
('ramayana-4-1-4', 4, 'Kishkindha Kanda, Sarga 1, Verse 4', 'मां तु शोकाभिसंतप्तमाधयः पीडयन्ति वै।
भरतस्य च दुःखेन वैदेह्या हरणेन च॥', 'māṃ tu śokābhisaṃtaptam ādhayaḥ pīḍayanti vai
bharatasya ca duḥkhena vaidehyā haraṇena ca', null, 4001004),
('ramayana-4-1-5', 5, 'Kishkindha Kanda, Sarga 1, Verse 5', 'अधिकं प्रविभात्येतन्नीलपीतं तु शाद्वलम्।
द्रुमाणां विविधैः पुष्पैः परिस्तोमैरिवार्पितम्॥', 'adhikaṃ pravibhāty etan nīlapītaṃ tu śādvalam
drumāṇāṃ vividhaiḥ puṣpaiḥ paristomair ivārpitam', null, 4001005),
('ramayana-4-1-6', 6, 'Kishkindha Kanda, Sarga 1, Verse 6', 'सुखानिलोऽयं सौमित्रे कालः प्रचुरमन्मथः।
गन्धवान्सुरभिर्मासो जातपुष्पफलद्रुमः॥', 'sukhānilo ''yaṃ saumitre kālaḥ pracuramanmathaḥ
gandhavān surabhir māso jātapuṣpaphaladrumaḥ', null, 4001006),
('ramayana-4-1-7', 7, 'Kishkindha Kanda, Sarga 1, Verse 7', 'पश्य रूपाणि सौमित्रे वनानां पुष्पशालिनाम्।
सृजतां पुष्पवर्षाणि वर्षं तोयमुचामिव॥', 'paśya rūpāṇi saumitre vanānāṃ puṣpaśālinām
sṛjatāṃ puṣpavarṣāṇi varṣaṃ toyamucām iva', null, 4001007),
('ramayana-4-1-8', 8, 'Kishkindha Kanda, Sarga 1, Verse 8', 'प्रस्तरेषु च रम्येषु विविधाः काननद्रुमाः।
वायुवेगप्रचलिताः पुष्पैरवकिरन्ति गाम्॥', 'prastareṣu ca ramyeṣu vividhāḥ kānanadrumāḥ
vāyuvegapracalitāḥ puṣpair avakiranti gām', null, 4001008),
('ramayana-4-1-9', 9, 'Kishkindha Kanda, Sarga 1, Verse 9', 'मारुतः सुखं संस्पर्शे वाति चन्दनशीतलः।
षट्पदैरनुकूजद्भिर्वनेषु मधुगन्धिषु॥', 'mārutaḥ sukhaṃ saṃsparśe vāti candanaśītalaḥ
ṣaṭpadair anukūjadbhir vaneṣu madhugandhiṣu', null, 4001009),
('ramayana-4-1-10', 10, 'Kishkindha Kanda, Sarga 1, Verse 10', 'गिरिप्रस्थेषु रम्येषु पुष्पवद्भिर्मनोरमैः।
संसक्तशिखरा शैला विराजन्ति महाद्रुमैः॥', 'giriprastheṣu ramyeṣu puṣpavadbhir manoramaiḥ
saṃsaktaśikharā śailā virājanti mahādrumaiḥ', null, 4001010),
('ramayana-4-1-11', 11, 'Kishkindha Kanda, Sarga 1, Verse 11', 'पुष्पिताग्रांश्च पश्येमान्कर्णिकारान्समन्ततः।
हाटकप्रतिसंछन्नान्नरान्पीताम्बरानिव॥', 'puṣpitāgrāṃś ca paśyemān karṇikārān samantataḥ
hāṭakapratisaṃchannān narān pītāmbarān iva', null, 4001011),
('ramayana-4-1-12', 12, 'Kishkindha Kanda, Sarga 1, Verse 12', 'अयं वसन्तः सौमित्रे नानाविहगनादितः।
सीतया विप्रहीणस्य शोकसंदीपनो मम॥', 'ayaṃ vasantaḥ saumitre nānāvihaganāditaḥ
sītayā viprahīṇasya śokasaṃdīpano mama', null, 4001012),
('ramayana-4-1-13', 13, 'Kishkindha Kanda, Sarga 1, Verse 13', 'मां हि शोकसमाक्रान्तं संतापयति मन्मथः।
हृष्टः प्रवदमानश्च समाह्वयति कोकिलः॥', 'māṃ hi śokasamākrāntaṃ saṃtāpayati manmathaḥ
hṛṣṭaḥ pravadamānaś ca samāhvayati kokilaḥ', null, 4001013),
('ramayana-4-1-14', 14, 'Kishkindha Kanda, Sarga 1, Verse 14', 'एष दात्यूहको हृष्टो रम्ये मां वननिर्झरे।
प्रणदन्मन्मथाविष्टं शोचयिष्यति लक्ष्मण॥', 'eṣa dātyūhako hṛṣṭo ramye māṃ vananirjhare
praṇadan manmathāviṣṭaṃ śocayiṣyati lakṣmaṇa', null, 4001014),
('ramayana-4-1-15', 15, 'Kishkindha Kanda, Sarga 1, Verse 15', 'विमिश्रा विहगाः पुम्भिरात्मव्यूहाभिनन्दिताः।
भृङ्गराजप्रमुदिताः सौमित्रे मधुरस्वराः॥', 'vimiśrā vihagāḥ pumbhir ātmavyūhābhinanditāḥ
bhṛṅgarājapramuditāḥ saumitre madhurasvarāḥ', null, 4001015),
('ramayana-4-1-16', 16, 'Kishkindha Kanda, Sarga 1, Verse 16', 'मां हि सा मृगशावाक्षी चिन्ताशोकबलात्कृतम्।
संतापयति सौमित्रे क्रूरश्चैत्रवनानिलः॥', 'māṃ hi sā mṛgaśāvākṣī cintāśokabalātkṛtam
saṃtāpayati saumitre krūraś caitravanānilaḥ', null, 4001016),
('ramayana-4-1-17', 17, 'Kishkindha Kanda, Sarga 1, Verse 17', 'शिखिनीभिः परिवृता मयूरा गिरिसानुषु।
मन्मथाभिपरीतस्य मम मन्मथवर्धनाः॥', 'śikhinībhiḥ parivṛtā mayūrā girisānuṣu
manmathābhiparītasya mama manmathavardhanāḥ', null, 4001017),
('ramayana-4-1-18', 18, 'Kishkindha Kanda, Sarga 1, Verse 18', 'पश्य लक्ष्णम नृत्यन्तं मयूरमुपनृत्यति।
शिखिनी मन्मथार्तैषा भर्तारं गिरिसानुषु॥', 'paśya lakṣṇama nṛtyantaṃ mayūram upanṛtyati
śikhinī manmathārtaiṣā bhartāraṃ girisānuṣu', null, 4001018),
('ramayana-4-1-19', 19, 'Kishkindha Kanda, Sarga 1, Verse 19', 'मयूरस्य वने नूनं रक्षसा न हृता प्रिया।
मम त्वयं विना वासः पुष्पमासे सुदुःसहः॥', 'mayūrasya vane nūnaṃ rakṣasā na hṛtā priyā
mama tv ayaṃ vinā vāsaḥ puṣpamāse suduḥsahaḥ', null, 4001019),
('ramayana-4-1-20', 20, 'Kishkindha Kanda, Sarga 1, Verse 20', 'पश्य लक्ष्मण पुष्पाणि निष्फलानि भवन्ति मे।
पुष्पभारसमृद्धानां वनानां शिशिरात्यये॥', 'paśya lakṣmaṇa puṣpāṇi niṣphalāni bhavanti me
puṣpabhārasamṛddhānāṃ vanānāṃ śiśirātyaye', null, 4001020),
('ramayana-4-1-21', 21, 'Kishkindha Kanda, Sarga 1, Verse 21', 'वदन्ति रावं मुदिताः शकुनाः संघशः कलम्।
आह्वयन्त इवान्योन्यं कामोन्मादकरा मम॥', 'vadanti rāvaṃ muditāḥ śakunāḥ saṃghaśaḥ kalam
āhvayanta ivānyonyaṃ kāmonmādakarā mama', null, 4001021),
('ramayana-4-1-22', 22, 'Kishkindha Kanda, Sarga 1, Verse 22', 'नूनं परवशा सीता सापि शोचत्यहं यथा।
श्यामा पद्मपलाशाक्षी मृदुभाषा च मे प्रिया॥', 'nūnaṃ paravaśā sītā sāpi śocaty ahaṃ yathā
śyāmā padmapalāśākṣī mṛdubhāṣā ca me priyā', null, 4001022),
('ramayana-4-1-23', 23, 'Kishkindha Kanda, Sarga 1, Verse 23', 'एष पुष्पवहो वायुः सुखस्पर्शो हिमावहः।
तां विचिन्तयतः कान्तां पावकप्रतिमो मम॥', 'eṣa puṣpavaho vāyuḥ sukhasparśo himāvahaḥ
tāṃ vicintayataḥ kāntāṃ pāvakapratimo mama', null, 4001023),
('ramayana-4-1-24', 24, 'Kishkindha Kanda, Sarga 1, Verse 24', 'तां विनाथ विहंगोऽसौ पक्षी प्रणदितस्तदा।
वायसः पादपगतः प्रहृष्टमभिनर्दति॥', 'tāṃ vinātha vihaṃgo ''sau pakṣī praṇaditas tadā
vāyasaḥ pādapagataḥ prahṛṣṭam abhinardati', null, 4001024),
('ramayana-4-1-25', 25, 'Kishkindha Kanda, Sarga 1, Verse 25', 'एष वै तत्र वैदेह्या विहगः प्रतिहारकः।
पक्षी मां तु विशालाक्ष्याः समीपमुपनेष्यति॥', 'eṣa vai tatra vaidehyā vihagaḥ pratihārakaḥ
pakṣī māṃ tu viśālākṣyāḥ samīpam upaneṣyati', null, 4001025),
('ramayana-4-1-26', 26, 'Kishkindha Kanda, Sarga 1, Verse 26', 'पश्य लक्ष्मण संनादं वने मदविवर्धनम्।
पुष्पिताग्रेषु वृक्षेषु द्विजानामुपकूजताम्॥', 'paśya lakṣmaṇa saṃnādaṃ vane madavivardhanam
puṣpitāgreṣu vṛkṣeṣu dvijānām upakūjatām', null, 4001026),
('ramayana-4-1-27', 27, 'Kishkindha Kanda, Sarga 1, Verse 27', 'सौमित्रे पश्य पम्पायाश्चित्रासु वनराजिषु।
नलिनानि प्रकाशन्ते जले तरुणसूर्यवत्॥', 'saumitre paśya pampāyāś citrāsu vanarājiṣu
nalināni prakāśante jale taruṇasūryavat', null, 4001027),
('ramayana-4-1-28', 28, 'Kishkindha Kanda, Sarga 1, Verse 28', 'एषा प्रसन्नसलिला पद्मनीलोत्पलायता।
हंसकारण्डवाकीर्णा पम्पा सौगन्धिकायुता॥', 'eṣā prasannasalilā padmanīlotpalāyatā
haṃsakāraṇḍavākīrṇā pampā saugandhikāyutā', null, 4001028),
('ramayana-4-1-29', 29, 'Kishkindha Kanda, Sarga 1, Verse 29', 'चक्रवाकयुता नित्यं चित्रप्रस्थवनान्तरा।
मातङ्गमृगयूथैश्च शोभते सलिलार्थिभिः॥', 'cakravākayutā nityaṃ citraprasthavanāntarā
mātaṅgamṛgayūthaiś ca śobhate salilārthibhiḥ', null, 4001029),
('ramayana-4-1-30', 30, 'Kishkindha Kanda, Sarga 1, Verse 30', 'पद्मकोशपलाशानि द्रष्टुं दृष्टिर्हि मन्यते।
सीताया नेत्रकोशाभ्यां सदृशानीति लक्ष्मण॥', 'padmakośapalāśāni draṣṭuṃ dṛṣṭir hi manyate
sītāyā netrakośābhyāṃ sadṛśānīti lakṣmaṇa', null, 4001030),
('ramayana-4-1-31', 31, 'Kishkindha Kanda, Sarga 1, Verse 31', 'पद्मकेसरसंसृष्टो वृक्षान्तरविनिःसृतः।
निःश्वास इव सीताया वाति वायुर्मनोहरः॥', 'padmakesarasaṃsṛṣṭo vṛkṣāntaraviniḥsṛtaḥ
niḥśvāsa iva sītāyā vāti vāyur manoharaḥ', null, 4001031),
('ramayana-4-1-32', 32, 'Kishkindha Kanda, Sarga 1, Verse 32', 'सौमित्रे पश्य पम्पाया दक्षिणे गिरिसानुनि।
पुष्पितां कर्णिकारस्य यष्टिं परमशोभनाम्॥', 'saumitre paśya pampāyā dakṣiṇe girisānuni
puṣpitāṃ karṇikārasya yaṣṭiṃ paramaśobhanām', null, 4001032),
('ramayana-4-1-33', 33, 'Kishkindha Kanda, Sarga 1, Verse 33', 'अधिकं शैलराजोऽयं धातुभिस्तु विभूषितः।
विचित्रं सृजते रेणुं वायुवेगविघट्टितम्॥', 'adhikaṃ śailarājo ''yaṃ dhātubhis tu vibhūṣitaḥ
vicitraṃ sṛjate reṇuṃ vāyuvegavighaṭṭitam', null, 4001033),
('ramayana-4-1-34', 34, 'Kishkindha Kanda, Sarga 1, Verse 34', 'गिरिप्रस्थास्तु सौमित्रे सर्वतः संप्रपुष्पितैः।
निष्पत्रैः सर्वतो रम्यैः प्रदीपा इव कुंशुकैः॥', 'giriprasthās tu saumitre sarvataḥ saṃprapuṣpitaiḥ
niṣpatraiḥ sarvato ramyaiḥ pradīpā iva kuṃśukaiḥ', null, 4001034),
('ramayana-4-1-35', 35, 'Kishkindha Kanda, Sarga 1, Verse 35', 'पम्पातीररुहाश्चेमे संसक्ता मधुगन्धिनः।
मालतीमल्लिकाषण्डाः करवीराश्च पुष्पिताः॥', 'pampātīraruhāś ceme saṃsaktā madhugandhinaḥ
mālatīmallikāṣaṇḍāḥ karavīrāś ca puṣpitāḥ', null, 4001035),
('ramayana-4-1-36', 36, 'Kishkindha Kanda, Sarga 1, Verse 36', 'केतक्यः सिन्दुवाराश्च वासन्त्यश्च सुपुष्पिताः।
माधव्यो गन्धपूर्णाश्च कुन्दगुल्माश्च सर्वशः॥', 'ketakyaḥ sinduvārāś ca vāsantyaś ca supuṣpitāḥ
mādhavyo gandhapūrṇāś ca kundagulmāś ca sarvaśaḥ', null, 4001036),
('ramayana-4-1-37', 37, 'Kishkindha Kanda, Sarga 1, Verse 37', 'चिरिबिल्वा मधूकाश्च वञ्जुला बकुलास्तथा।
चम्पकास्तिलकाश्चैव नागवृक्षाश्च पुष्पिताः॥', 'ciribilvā madhūkāś ca vañjulā bakulās tathā
campakās tilakāś caiva nāgavṛkṣāś ca puṣpitāḥ', null, 4001037),
('ramayana-4-1-38', 38, 'Kishkindha Kanda, Sarga 1, Verse 38', 'नीपाश्च वरणाश्चैव खर्जूराश्च सुपुष्पिताः।
अङ्कोलाश्च कुरण्टाश्च चूर्णकाः पारिभद्रकाः॥', 'nīpāś ca varaṇāś caiva kharjūrāś ca supuṣpitāḥ
aṅkolāś ca kuraṇṭāś ca cūrṇakāḥ pāribhadrakāḥ', null, 4001038),
('ramayana-4-1-39', 39, 'Kishkindha Kanda, Sarga 1, Verse 39', 'चूताः पाटलयश्चैव कोविदाराश्च पुष्पिताः।
मुचुकुन्दार्जुनाश्चैव दृश्यन्ते गिरिसानुषु॥', 'cūtāḥ pāṭalayaś caiva kovidārāś ca puṣpitāḥ
mucukundārjunāś caiva dṛśyante girisānuṣu', null, 4001039),
('ramayana-4-1-40', 40, 'Kishkindha Kanda, Sarga 1, Verse 40', 'केतकोद्दालकाश्चैव शिरीषाः शिंशपा धवाः।
शाल्मल्यः किंशुकाश्चैव रक्ताः कुरबकास्तथा।
तिनिशा नक्त मालाश्च चन्दनाः स्यन्दनास्तथा॥', 'ketakoddālakāś caiva śirīṣāḥ śiṃśapā dhavāḥ
śālmalyaḥ kiṃśukāś caiva raktāḥ kurabakās tathā
tiniśā nakta mālāś ca candanāḥ syandanās tathā', null, 4001040),
('ramayana-4-1-41', 41, 'Kishkindha Kanda, Sarga 1, Verse 41', 'विविधा विविधैः पुष्पैस्तैरेव नगसानुषु।
विकीर्णैः पीतरक्ताभाः सौमित्रे प्रस्तराः कृताः॥', 'vividhā vividhaiḥ puṣpais tair eva nagasānuṣu
vikīrṇaiḥ pītaraktābhāḥ saumitre prastarāḥ kṛtāḥ', null, 4001041),
('ramayana-4-1-42', 42, 'Kishkindha Kanda, Sarga 1, Verse 42', 'हिमान्ते पश्य सौमित्रे वृक्षाणां पुष्पसंभवम्।
पुष्पमासे हि तरवः संघर्षादिव पुष्पिताः॥', 'himānte paśya saumitre vṛkṣāṇāṃ puṣpasaṃbhavam
puṣpamāse hi taravaḥ saṃgharṣād iva puṣpitāḥ', null, 4001042),
('ramayana-4-1-43', 43, 'Kishkindha Kanda, Sarga 1, Verse 43', 'पश्य शीतजलां चेमां सौमित्रे पुष्करायुताम्।
चक्रवाकानुचरितां कारण्डवनिषेविताम्।
प्लवैः क्रौञ्चैश्च संपूर्णां वराहमृगसेविताम्॥', 'paśya śītajalāṃ cemāṃ saumitre puṣkarāyutām
cakravākānucaritāṃ kāraṇḍavaniṣevitām
plavaiḥ krauñcaiś ca saṃpūrṇāṃ varāhamṛgasevitām', null, 4001043),
('ramayana-4-1-44', 44, 'Kishkindha Kanda, Sarga 1, Verse 44', 'अधिकं शोभते पम्पाविकूजद्भिर्विहंगमैः॥', 'adhikaṃ śobhate pampāvikūjadbhir vihaṃgamaiḥ', null, 4001044),
('ramayana-4-1-45', 45, 'Kishkindha Kanda, Sarga 1, Verse 45', 'दीपयन्तीव मे कामं विविधा मुदिता द्विजाः।
श्यामां चन्द्रमुखीं स्मृत्वा प्रियां पद्मनिभेक्षणाम्॥', 'dīpayantīva me kāmaṃ vividhā muditā dvijāḥ
śyāmāṃ candramukhīṃ smṛtvā priyāṃ padmanibhekṣaṇām', null, 4001045),
('ramayana-4-1-46', 46, 'Kishkindha Kanda, Sarga 1, Verse 46', 'पय सानुषु चित्रेषु मृगीभिः सहितान्मृगान्।
मां पुनर्मृगशावाक्ष्या वैदेह्या विरहीकृतम्॥', 'paya sānuṣu citreṣu mṛgībhiḥ sahitān mṛgān
māṃ punar mṛgaśāvākṣyā vaidehyā virahīkṛtam', null, 4001046),
('ramayana-4-1-47', 47, 'Kishkindha Kanda, Sarga 1, Verse 47', 'एवं स विलपंस्तत्र शोकोपहतचेतनः।
अवेक्षत शिवां पम्पां रम्यवारिवहां शुभाम्॥', 'evaṃ sa vilapaṃs tatra śokopahatacetanaḥ
avekṣata śivāṃ pampāṃ ramyavārivahāṃ śubhām', null, 4001047),
('ramayana-4-1-48', 48, 'Kishkindha Kanda, Sarga 1, Verse 48', 'निरीक्षमाणः सहसा महात्मा सर्वं वनं निर्झरकन्दरं च।
उद्विग्नचेताः सह लक्ष्मणेन विचार्य दुःखोपहतः प्रतस्थे॥', 'nirīkṣamāṇaḥ sahasā mahātmā sarvaṃ vanaṃ nirjharakandaraṃ ca
udvignacetāḥ saha lakṣmaṇena vicārya duḥkhopahataḥ pratasthe', null, 4001048),
('ramayana-4-1-49', 49, 'Kishkindha Kanda, Sarga 1, Verse 49', 'तावृष्यमूकं सहितौ प्रयातौ सुग्रीवशाखामृगसेवितं तम्।
त्रस्तास्तु दृष्ट्वा हरयो बभूवुर्महौजसौ राघवलक्ष्मणौ तौ॥', 'tāv ṛṣyamūkaṃ sahitau prayātau sugrīvaśākhāmṛgasevitaṃ tam
trastās tu dṛṣṭvā harayo babhūvur mahaujasau rāghavalakṣmaṇau tau', null, 4001049)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 2 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-2-1', 1, 'Kishkindha Kanda, Sarga 2, Verse 1', 'तौ तु दृष्ट्वा महात्मानौ भ्रातरौ रामलक्ष्मणौ।
वरायुधधरौ वीरौ सुग्रीवः शङ्कितोऽभवत्॥', 'tau tu dṛṣṭvā mahātmānau bhrātarau rāmalakṣmaṇau
varāyudhadharau vīrau sugrīvaḥ śaṅkito ''bhavat', null, 4002001),
('ramayana-4-2-2', 2, 'Kishkindha Kanda, Sarga 2, Verse 2', 'उद्विग्नहृदयः सर्वा दिशः समवलोकयन्।
न व्यतिष्ठत कस्मिंश्चिद्देशे वानरपुंगवः॥', 'udvignahṛdayaḥ sarvā diśaḥ samavalokayan
na vyatiṣṭhata kasmiṃś cid deśe vānarapuṃgavaḥ', null, 4002002),
('ramayana-4-2-3', 3, 'Kishkindha Kanda, Sarga 2, Verse 3', 'नैव चक्रे मनः स्थाने वीक्षमाणो महाबलौ।
कपेः परमभीतस्य चित्तं व्यवससाद ह॥', 'naiva cakre manaḥ sthāne vīkṣamāṇo mahābalau
kapeḥ paramabhītasya cittaṃ vyavasasāda ha', null, 4002003),
('ramayana-4-2-4', 4, 'Kishkindha Kanda, Sarga 2, Verse 4', 'चिन्तयित्वा स धर्मात्मा विमृश्य गुरुलाघवम्।
सुग्रीवः परमोद्विग्नः सर्वैरनुचरैः सह॥', 'cintayitvā sa dharmātmā vimṛśya gurulāghavam
sugrīvaḥ paramodvignaḥ sarvair anucaraiḥ saha', null, 4002004),
('ramayana-4-2-5', 5, 'Kishkindha Kanda, Sarga 2, Verse 5', 'ततः स सचिवेभ्यस्तु सुग्रीवः प्लवगाधिपः।
शशंस परमोद्विग्नः पश्यंस्तौ रामलक्ष्मणौ॥', 'tataḥ sa sacivebhyas tu sugrīvaḥ plavagādhipaḥ
śaśaṃsa paramodvignaḥ paśyaṃs tau rāmalakṣmaṇau', null, 4002005),
('ramayana-4-2-6', 6, 'Kishkindha Kanda, Sarga 2, Verse 6', 'एतौ वनमिदं दुर्गं वालिप्रणिहितौ ध्रुवम्।
छद्मना चीरवसनौ प्रचरन्ताविहागतौ॥', 'etau vanam idaṃ durgaṃ vālipraṇihitau dhruvam
chadmanā cīravasanau pracarantāv ihāgatau', null, 4002006),
('ramayana-4-2-7', 7, 'Kishkindha Kanda, Sarga 2, Verse 7', 'ततः सुग्रीवसचिवा दृष्ट्वा परमधन्विनौ।
जग्मुर्गिरितटात्तस्मादन्यच्छिखरमुत्तमम्॥', 'tataḥ sugrīvasacivā dṛṣṭvā paramadhanvinau
jagmur giritaṭāt tasmād anyac chikharam uttamam', null, 4002007),
('ramayana-4-2-8', 8, 'Kishkindha Kanda, Sarga 2, Verse 8', 'ते क्षिप्रमभिगम्याथ यूथपा यूथपर्षभम्।
हरयो वानरश्रेष्ठं परिवार्योपतस्थिरे॥', 'te kṣipram abhigamyātha yūthapā yūthaparṣabham
harayo vānaraśreṣṭhaṃ parivāryopatasthire', null, 4002008),
('ramayana-4-2-9', 9, 'Kishkindha Kanda, Sarga 2, Verse 9', 'एकमेकायनगताः प्लवमाना गिरेर्गिरिम्।
प्रकम्पयन्तो वेगेन गिरीणां शिखराणि च॥', 'ekam ekāyanagatāḥ plavamānā girer girim
prakampayanto vegena girīṇāṃ śikharāṇi ca', null, 4002009),
('ramayana-4-2-10', 10, 'Kishkindha Kanda, Sarga 2, Verse 10', 'ततः शाखामृगाः सर्वे प्लवमाना महाबलाः।
बभञ्जुश्च नगांस्तत्र पुष्पितान्दुर्गसंश्रितान्॥', 'tataḥ śākhāmṛgāḥ sarve plavamānā mahābalāḥ
babhañjuś ca nagāṃs tatra puṣpitān durgasaṃśritān', null, 4002010),
('ramayana-4-2-11', 11, 'Kishkindha Kanda, Sarga 2, Verse 11', 'आप्लवन्तो हरिवराः सर्वतस्तं महागिरिम्।
मृगमार्जारशार्दूलांस्त्रासयन्तो ययुस्तदा॥', 'āplavanto harivarāḥ sarvatas taṃ mahāgirim
mṛgamārjāraśārdūlāṃs trāsayanto yayus tadā', null, 4002011),
('ramayana-4-2-12', 12, 'Kishkindha Kanda, Sarga 2, Verse 12', 'ततः सुग्रीवसचिवाः पर्वतेन्द्रं समाश्रिताः।
संगम्य कपिमुख्येन सर्वे प्राञ्जलयः स्थिताः॥', 'tataḥ sugrīvasacivāḥ parvatendraṃ samāśritāḥ
saṃgamya kapimukhyena sarve prāñjalayaḥ sthitāḥ', null, 4002012),
('ramayana-4-2-13', 13, 'Kishkindha Kanda, Sarga 2, Verse 13', 'ततस्तं भयसंत्रस्तं वालिकिल्बिषशङ्कितम्।
उवाच हनुमान्वाक्यं सुग्रीवं वाक्यकोविदः॥', 'tatas taṃ bhayasaṃtrastaṃ vālikilbiṣaśaṅkitam
uvāca hanumān vākyaṃ sugrīvaṃ vākyakovidaḥ', null, 4002013),
('ramayana-4-2-14', 14, 'Kishkindha Kanda, Sarga 2, Verse 14', 'यस्मादुद्विग्नचेतास्त्वं प्रद्रुतो हरिपुंगव।
तं क्रूरदर्शनं क्रूरं नेह पश्यामि वालिनम्॥', 'yasmād udvignacetās tvaṃ pradruto haripuṃgava
taṃ krūradarśanaṃ krūraṃ neha paśyāmi vālinam', null, 4002014),
('ramayana-4-2-15', 15, 'Kishkindha Kanda, Sarga 2, Verse 15', 'यस्मात्तव भयं सौम्य पूर्वजात्पापकर्मणः।
स नेह वाली दुष्टात्मा न ते पश्याम्यहं भयम्॥', 'yasmāt tava bhayaṃ saumya pūrvajāt pāpakarmaṇaḥ
sa neha vālī duṣṭātmā na te paśyāmy ahaṃ bhayam', null, 4002015),
('ramayana-4-2-16', 16, 'Kishkindha Kanda, Sarga 2, Verse 16', 'अहो शाखामृगत्वं ते व्यक्तमेव प्लवंगम।
लघुचित्ततयात्मानं न स्थापयसि यो मतौ॥', 'aho śākhāmṛgatvaṃ te vyaktam eva plavaṃgama
laghucittatayātmānaṃ na sthāpayasi yo matau', null, 4002016),
('ramayana-4-2-17', 17, 'Kishkindha Kanda, Sarga 2, Verse 17', 'बुद्धिविज्ञानसंपन्न इङ्गितैः सर्वमाचर।
न ह्यबुद्धिं गतो राजा सर्वभूतानि शास्ति हि॥', 'buddhivijñānasaṃpanna iṅgitaiḥ sarvam ācara
na hy abuddhiṃ gato rājā sarvabhūtāni śāsti hi', null, 4002017),
('ramayana-4-2-18', 18, 'Kishkindha Kanda, Sarga 2, Verse 18', 'सुग्रीवस्तु शुभं वाक्यं श्रुत्वा सर्वं हनूमतः।
ततः शुभतरं वाक्यं हनूमन्तमुवाच ह॥', 'sugrīvas tu śubhaṃ vākyaṃ śrutvā sarvaṃ hanūmataḥ
tataḥ śubhataraṃ vākyaṃ hanūmantam uvāca ha', null, 4002018),
('ramayana-4-2-19', 19, 'Kishkindha Kanda, Sarga 2, Verse 19', 'दीर्घबाहू विशालाक्षौ शरचापासिधारिणौ।
कस्य न स्याद्भयं दृष्ट्वा एतौ सुरसुतोपमौ॥', 'dīrghabāhū viśālākṣau śaracāpāsidhāriṇau
kasya na syād bhayaṃ dṛṣṭvā etau surasutopamau', null, 4002019),
('ramayana-4-2-20', 20, 'Kishkindha Kanda, Sarga 2, Verse 20', 'वालिप्रणिहितावेतौ शङ्केऽहं पुरुषोत्तमौ।
राजानो बहुमित्राश्च विश्वासो नात्र हि क्षमः॥', 'vālipraṇihitāv etau śaṅke ''haṃ puruṣottamau
rājāno bahumitrāś ca viśvāso nātra hi kṣamaḥ', null, 4002020),
('ramayana-4-2-21', 21, 'Kishkindha Kanda, Sarga 2, Verse 21', 'अरयश्च मनुष्येण विज्ञेयाश्छन्नचारिणः।
विश्वस्तानामविश्वस्ताश्छिद्रेषु प्रहरन्ति हि॥', 'arayaś ca manuṣyeṇa vijñeyāś channacāriṇaḥ
viśvastānām aviśvastāś chidreṣu praharanti hi', null, 4002021),
('ramayana-4-2-22', 22, 'Kishkindha Kanda, Sarga 2, Verse 22', 'कृत्येषु वाली मेधावी राजानो बहुदर्शनाः।
भवन्ति परहन्तारस्ते ज्ञेयाः प्राकृतैर्नरैः॥', 'kṛtyeṣu vālī medhāvī rājāno bahudarśanāḥ
bhavanti parahantāras te jñeyāḥ prākṛtair naraiḥ', null, 4002022),
('ramayana-4-2-23', 23, 'Kishkindha Kanda, Sarga 2, Verse 23', 'तौ त्वया प्राकृतेनैव गत्वा ज्ञेयौ प्लवंगम।
शङ्कितानां प्रकारैश्च रूपव्याभाषणेन च॥', 'tau tvayā prākṛtenaiva gatvā jñeyau plavaṃgama
śaṅkitānāṃ prakāraiś ca rūpavyābhāṣaṇena ca', null, 4002023),
('ramayana-4-2-24', 24, 'Kishkindha Kanda, Sarga 2, Verse 24', 'लक्षयस्व तयोर्भावं प्रहृष्टमनसौ यदि।
विश्वासयन्प्रशंसाभिरिङ्गितैश्च पुनः पुनः॥', 'lakṣayasva tayor bhāvaṃ prahṛṣṭamanasau yadi
viśvāsayan praśaṃsābhir iṅgitaiś ca punaḥ punaḥ', null, 4002024),
('ramayana-4-2-25', 25, 'Kishkindha Kanda, Sarga 2, Verse 25', 'ममैवाभिमुखं स्थित्वा पृच्छ त्वं हरिपुंगव।
प्रयोजनं प्रवेशस्य वनस्यास्य धनुर्धरौ॥', 'mamaivābhimukhaṃ sthitvā pṛccha tvaṃ haripuṃgava
prayojanaṃ praveśasya vanasyāsya dhanurdharau', null, 4002025),
('ramayana-4-2-26', 26, 'Kishkindha Kanda, Sarga 2, Verse 26', 'शुद्धात्मानौ यदि त्वेतौ जानीहि त्वं प्लवंगम।
व्याभाषितैर्वा रूपैर्वा विज्ञेया दुष्टतानयोः॥', 'śuddhātmānau yadi tv etau jānīhi tvaṃ plavaṃgama
vyābhāṣitair vā rūpair vā vijñeyā duṣṭatānayoḥ', null, 4002026),
('ramayana-4-2-27', 27, 'Kishkindha Kanda, Sarga 2, Verse 27', 'इत्येवं कपिराजेन संदिष्टो मारुतात्मजः।
चकार गमने बुद्धिं यत्र तौ रामलक्ष्मणौ॥', 'ity evaṃ kapirājena saṃdiṣṭo mārutātmajaḥ
cakāra gamane buddhiṃ yatra tau rāmalakṣmaṇau', null, 4002027),
('ramayana-4-2-28', 28, 'Kishkindha Kanda, Sarga 2, Verse 28', 'तथेति संपूज्य वचस्तु तस्य कपेः सुभीतस्य दुरासदस्य।
महानुभावो हनुमान्ययौ तदा स यत्र रामोऽतिबलश्च लक्ष्मणः॥', 'tatheti saṃpūjya vacas tu tasya kapeḥ subhītasya durāsadasya
mahānubhāvo hanumān yayau tadā sa yatra rāmo ''tibalaś ca lakṣmaṇaḥ', null, 4002028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 3 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-3-1', 1, 'Kishkindha Kanda, Sarga 3, Verse 1', 'वचो विज्ञाय हनुमान्सुग्रीवस्य महात्मनः।
पर्वतादृश्यमूकात्तु पुप्लुवे यत्र राघवौ॥', 'vaco vijñāya hanumān sugrīvasya mahātmanaḥ
parvatād ṛśyamūkāt tu pupluve yatra rāghavau', null, 4003001),
('ramayana-4-3-2', 2, 'Kishkindha Kanda, Sarga 3, Verse 2', 'स तत्र गत्वा हनुमान्बलवान्वानरोत्तमः।
उपचक्राम तौ वाग्भिर्मृद्वीभिः सत्यविक्रमः॥', 'sa tatra gatvā hanumān balavān vānarottamaḥ
upacakrāma tau vāgbhir mṛdvībhiḥ satyavikramaḥ', null, 4003002),
('ramayana-4-3-3', 3, 'Kishkindha Kanda, Sarga 3, Verse 3', 'स्वकं रूपं परित्यज्य भिक्षुरूपेण वानरः।
आबभाषे च तौ वीरौ यथावत्प्रशशंस च॥', 'svakaṃ rūpaṃ parityajya bhikṣurūpeṇa vānaraḥ
ābabhāṣe ca tau vīrau yathāvat praśaśaṃsa ca', null, 4003003),
('ramayana-4-3-4', 4, 'Kishkindha Kanda, Sarga 3, Verse 4', 'राजर्षिदेवप्रतिमौ तापसौ संशितव्रतौ।
देशं कथमिमं प्राप्तौ भवन्तौ वरवर्णिनौ॥', 'rājarṣidevapratimau tāpasau saṃśitavratau
deśaṃ katham imaṃ prāptau bhavantau varavarṇinau', null, 4003004),
('ramayana-4-3-5', 5, 'Kishkindha Kanda, Sarga 3, Verse 5', 'त्रासयन्तौ मृगगणानन्यांश्च वनचारिणः।
पम्पातीररुहान्वृक्षान्वीक्षमाणौ समन्ततः॥', 'trāsayantau mṛgagaṇān anyāṃś ca vanacāriṇaḥ
pampātīraruhān vṛkṣān vīkṣamāṇau samantataḥ', null, 4003005),
('ramayana-4-3-6', 6, 'Kishkindha Kanda, Sarga 3, Verse 6', 'इमां नदीं शुभजलां शोभयन्तौ तरस्विनौ।
धैर्यवन्तौ सुवर्णाभौ कौ युवां चीरवाससौ॥', 'imāṃ nadīṃ śubhajalāṃ śobhayantau tarasvinau
dhairyavantau suvarṇābhau kau yuvāṃ cīravāsasau', null, 4003006),
('ramayana-4-3-7', 7, 'Kishkindha Kanda, Sarga 3, Verse 7', 'सिंहविप्रेक्षितौ वीरौ सिंहातिबलविक्रमौ।
शक्रचापनिभे चापे प्रगृह्य विपुलैर्भुजैः॥', 'siṃhaviprekṣitau vīrau siṃhātibalavikramau
śakracāpanibhe cāpe pragṛhya vipulair bhujaiḥ', null, 4003007),
('ramayana-4-3-8', 8, 'Kishkindha Kanda, Sarga 3, Verse 8', 'श्रीमन्तौ रूपसंपन्नौ वृषभश्रेष्ठविक्रमौ।
हस्तिहस्तोपमभुजौ द्युतिमन्तौ नरर्षभौ॥', 'śrīmantau rūpasaṃpannau vṛṣabhaśreṣṭhavikramau
hastihastopamabhujau dyutimantau nararṣabhau', null, 4003008),
('ramayana-4-3-9', 9, 'Kishkindha Kanda, Sarga 3, Verse 9', 'प्रभया पर्वतेन्द्रोऽयं युवयोरवभासितः।
राज्यार्हावमरप्रख्यौ कथं देशमिहागतौ॥', 'prabhayā parvatendro ''yaṃ yuvayor avabhāsitaḥ
rājyārhāv amaraprakhyau kathaṃ deśam ihāgatau', null, 4003009),
('ramayana-4-3-10', 10, 'Kishkindha Kanda, Sarga 3, Verse 10', 'पद्मपत्रेक्षणौ वीरौ जटामण्डलधारिणौ।
अन्योन्यसदृशौ वीरौ देवलोकादिवागतौ॥', 'padmapatrekṣaṇau vīrau jaṭāmaṇḍaladhāriṇau
anyonyasadṛśau vīrau devalokād ivāgatau', null, 4003010),
('ramayana-4-3-11', 11, 'Kishkindha Kanda, Sarga 3, Verse 11', 'यदृच्छयेव संप्राप्तौ चन्द्रसूर्यौ वसुंधराम्।
विशालवक्षसौ वीरौ मानुषौ देवरूपिणौ॥', 'yadṛcchayeva saṃprāptau candrasūryau vasuṃdharām
viśālavakṣasau vīrau mānuṣau devarūpiṇau', null, 4003011),
('ramayana-4-3-12', 12, 'Kishkindha Kanda, Sarga 3, Verse 12', 'सिंहस्कन्धौ महासत्त्वौ समदाविव गोवृषौ।
आयताश्च सुवृत्ताश्च बाहवः परिघोत्तमाः।
सर्वभूषणभूषार्हाः किमर्थं न विभूषितः॥', 'siṃhaskandhau mahāsattvau samadāv iva govṛṣau
āyatāś ca suvṛttāś ca bāhavaḥ parighottamāḥ
sarvabhūṣaṇabhūṣārhāḥ kim arthaṃ na vibhūṣitaḥ', null, 4003012),
('ramayana-4-3-13', 13, 'Kishkindha Kanda, Sarga 3, Verse 13', 'उभौ योग्यावहं मन्ये रक्षितुं पृथिवीमिमाम्।
ससागरवनां कृत्स्नां विन्ध्यमेरुविभूषिताम्॥', 'ubhau yogyāv ahaṃ manye rakṣituṃ pṛthivīm imām
sasāgaravanāṃ kṛtsnāṃ vindhyameruvibhūṣitām', null, 4003013),
('ramayana-4-3-14', 14, 'Kishkindha Kanda, Sarga 3, Verse 14', 'इमे च धनुषी चित्रे श्लक्ष्णे चित्रानुलेपने।
प्रकाशेते यथेन्द्रस्य वज्रे हेमविभूषिते॥', 'ime ca dhanuṣī citre ślakṣṇe citrānulepane
prakāśete yathendrasya vajre hemavibhūṣite', null, 4003014),
('ramayana-4-3-15', 15, 'Kishkindha Kanda, Sarga 3, Verse 15', 'संपूर्णा निशितैर्बाणैर्तूणाश्च शुभदर्शनाः।
जीवितान्तकरैर्घोरैर्ज्वलद्भिरिव पन्नगैः॥', 'saṃpūrṇā niśitair bāṇair tūṇāś ca śubhadarśanāḥ
jīvitāntakarair ghorair jvaladbhir iva pannagaiḥ', null, 4003015),
('ramayana-4-3-16', 16, 'Kishkindha Kanda, Sarga 3, Verse 16', 'महाप्रमाणौ विपुलौ तप्तहाटकभूषितौ।
खड्गावेतौ विराजेते निर्मुक्तभुजगाविव॥', 'mahāpramāṇau vipulau taptahāṭakabhūṣitau
khaḍgāv etau virājete nirmuktabhujagāv iva', null, 4003016),
('ramayana-4-3-17', 17, 'Kishkindha Kanda, Sarga 3, Verse 17', 'एवं मां परिभाषन्तं कस्माद्वै नाभिभाषथः॥', 'evaṃ māṃ paribhāṣantaṃ kasmād vai nābhibhāṣathaḥ', null, 4003017),
('ramayana-4-3-18', 18, 'Kishkindha Kanda, Sarga 3, Verse 18', 'सुग्रीवो नाम धर्मात्मा कश्चिद्वानरयूथपः।
वीरो विनिकृतो भ्रात्रा जगद्भ्रमति दुःखितः॥', 'sugrīvo nāma dharmātmā kaś cid vānarayūthapaḥ
vīro vinikṛto bhrātrā jagad bhramati duḥkhitaḥ', null, 4003018),
('ramayana-4-3-19', 19, 'Kishkindha Kanda, Sarga 3, Verse 19', 'प्राप्तोऽहं प्रेषितस्तेन सुग्रीवेण महात्मना।
राज्ञा वानरमुख्यानां हनुमान्नाम वानरः॥', 'prāpto ''haṃ preṣitas tena sugrīveṇa mahātmanā
rājñā vānaramukhyānāṃ hanumān nāma vānaraḥ', null, 4003019),
('ramayana-4-3-20', 20, 'Kishkindha Kanda, Sarga 3, Verse 20', 'युवाभ्यां सह धर्मात्मा सुग्रीवः सख्यमिच्छति।
तस्य मां सचिवं वित्तं वानरं पवनात्मजम्॥', 'yuvābhyāṃ saha dharmātmā sugrīvaḥ sakhyam icchati
tasya māṃ sacivaṃ vittaṃ vānaraṃ pavanātmajam', null, 4003020),
('ramayana-4-3-21', 21, 'Kishkindha Kanda, Sarga 3, Verse 21', 'भिक्षुरूपप्रतिच्छन्नं सुग्रीवप्रियकाम्यया।
ऋश्यमूकादिह प्राप्तं कामगं कामरूपिणम्॥', 'bhikṣurūpapraticchannaṃ sugrīvapriyakāmyayā
ṛśyamūkād iha prāptaṃ kāmagaṃ kāmarūpiṇam', null, 4003021),
('ramayana-4-3-22', 22, 'Kishkindha Kanda, Sarga 3, Verse 22', 'एवमुक्त्वा तु हनुमांस्तौ वीरौ रामलक्ष्मणौ।
वाक्यज्ञौ वाक्यकुशलः पुनर्नोवाच किं चन॥', 'evam uktvā tu hanumāṃs tau vīrau rāmalakṣmaṇau
vākyajñau vākyakuśalaḥ punar novāca kiṃ cana', null, 4003022),
('ramayana-4-3-23', 23, 'Kishkindha Kanda, Sarga 3, Verse 23', 'एतच्छ्रुत्वा वचस्तस्य रामो लक्ष्मणमब्रवीत्।
प्रहृष्टवदनः श्रीमान्भ्रातरं पार्श्वतः स्थितम्॥', 'etac chrutvā vacas tasya rāmo lakṣmaṇam abravīt
prahṛṣṭavadanaḥ śrīmān bhrātaraṃ pārśvataḥ sthitam', null, 4003023),
('ramayana-4-3-24', 24, 'Kishkindha Kanda, Sarga 3, Verse 24', 'सचिवोऽयं कपीन्द्रस्य सुग्रीवस्य महात्मनः।
तमेव काङ्क्षमाणस्य ममान्तिकमुपागतः॥', 'sacivo ''yaṃ kapīndrasya sugrīvasya mahātmanaḥ
tam eva kāṅkṣamāṇasya mamāntikam upāgataḥ', null, 4003024),
('ramayana-4-3-25', 25, 'Kishkindha Kanda, Sarga 3, Verse 25', 'तमभ्यभाष सौमित्रे सुग्रीवसचिवं कपिम्।
वाक्यज्ञं मधुरैर्वाक्यैः स्नेहयुक्तमरिंदमम्॥', 'tam abhyabhāṣa saumitre sugrīvasacivaṃ kapim
vākyajñaṃ madhurair vākyaiḥ snehayuktam ariṃdamam', null, 4003025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 4 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-4-1', 1, 'Kishkindha Kanda, Sarga 4, Verse 1', 'ततः प्रहृष्टो हनुमान्कृत्यवानिति तद्वचः।
श्रुत्वा मधुरसंभाषं सुग्रीवं मनसा गतः॥', 'tataḥ prahṛṣṭo hanumān kṛtyavān iti tad vacaḥ
śrutvā madhurasaṃbhāṣaṃ sugrīvaṃ manasā gataḥ', null, 4004001),
('ramayana-4-4-2', 2, 'Kishkindha Kanda, Sarga 4, Verse 2', 'भव्यो राज्यागमस्तस्य सुग्रीवस्य महात्मनः।
यदयं कृत्यवान्प्राप्तः कृत्यं चैतदुपागतम्॥', 'bhavyo rājyāgamas tasya sugrīvasya mahātmanaḥ
yad ayaṃ kṛtyavān prāptaḥ kṛtyaṃ caitad upāgatam', null, 4004002),
('ramayana-4-4-3', 3, 'Kishkindha Kanda, Sarga 4, Verse 3', 'ततः परमसंहृष्टो हनूमान्प्लवगर्षभः।
प्रत्युवाच ततो वाक्यं रामं वाक्यविशारदः॥', 'tataḥ paramasaṃhṛṣṭo hanūmān plavagarṣabhaḥ
pratyuvāca tato vākyaṃ rāmaṃ vākyaviśāradaḥ', null, 4004003),
('ramayana-4-4-4', 4, 'Kishkindha Kanda, Sarga 4, Verse 4', 'किमर्थं त्वं वनं घोरं पम्पाकाननमण्डितम्।
आगतः सानुजो दुर्गं नानाव्यालमृगायुतम्॥', 'kimarthaṃ tvaṃ vanaṃ ghoraṃ pampākānanamaṇḍitam
āgataḥ sānujo durgaṃ nānāvyālamṛgāyutam', null, 4004004),
('ramayana-4-4-5', 5, 'Kishkindha Kanda, Sarga 4, Verse 5', 'तस्य तद्वचनं श्रुत्वा लक्ष्मणो रामचोदितः।
आचचक्षे महात्मानं रामं दशरथात्मजम्॥', 'tasya tad vacanaṃ śrutvā lakṣmaṇo rāmacoditaḥ
ācacakṣe mahātmānaṃ rāmaṃ daśarathātmajam', null, 4004005),
('ramayana-4-4-6', 6, 'Kishkindha Kanda, Sarga 4, Verse 6', 'राजा दशरथो नाम द्युतिमान्धर्मवत्सलः।
तस्यायं पूर्वजः पुत्रो रामो नाम जनैः श्रुतः॥', 'rājā daśaratho nāma dyutimān dharmavatsalaḥ
tasyāyaṃ pūrvajaḥ putro rāmo nāma janaiḥ śrutaḥ', null, 4004006),
('ramayana-4-4-7', 7, 'Kishkindha Kanda, Sarga 4, Verse 7', 'शरण्यः सर्वभूतानां पितुर्निर्देशपारगः।
वीरो दशरथस्यायं पुत्राणां गुणवत्तरः॥', 'śaraṇyaḥ sarvabhūtānāṃ pitur nirdeśapāragaḥ
vīro daśarathasyāyaṃ putrāṇāṃ guṇavattaraḥ', null, 4004007),
('ramayana-4-4-8', 8, 'Kishkindha Kanda, Sarga 4, Verse 8', 'राज्याद्भ्रष्टो वने वस्तुं मया सार्धमिहागतः।
भार्यया च महातेजाः सीतयानुगतो वशी।
दिनक्षये महातेजाः प्रभयेव दिवाकरः॥', 'rājyād bhraṣṭo vane vastuṃ mayā sārdham ihāgataḥ
bhāryayā ca mahātejāḥ sītayānugato vaśī
dinakṣaye mahātejāḥ prabhayeva divākaraḥ', null, 4004008),
('ramayana-4-4-9', 9, 'Kishkindha Kanda, Sarga 4, Verse 9', 'अहमस्यावरो भ्राता गुणैर्दास्यमुपागतः।
कृतज्ञस्य बहुज्ञस्य लक्ष्मणो नाम नामतः॥', 'aham asyāvaro bhrātā guṇair dāsyam upāgataḥ
kṛtajñasya bahujñasya lakṣmaṇo nāma nāmataḥ', null, 4004009),
('ramayana-4-4-10', 10, 'Kishkindha Kanda, Sarga 4, Verse 10', 'सुखार्हस्य महार्हस्य सर्वभूतहितात्मनः।
ऐश्वर्येण विहीनस्य वनवासाश्रितस्य च॥', 'sukhārhasya mahārhasya sarvabhūtahitātmanaḥ
aiśvaryeṇa vihīnasya vanavāsāśritasya ca', null, 4004010),
('ramayana-4-4-11', 11, 'Kishkindha Kanda, Sarga 4, Verse 11', 'रक्षसापहृता भार्या रहिते कामरूपिणा।
तच्च न ज्ञायते रक्षः पत्नी येनास्य सा हृता॥', 'rakṣasāpahṛtā bhāryā rahite kāmarūpiṇā
tac ca na jñāyate rakṣaḥ patnī yenāsya sā hṛtā', null, 4004011),
('ramayana-4-4-12', 12, 'Kishkindha Kanda, Sarga 4, Verse 12', 'दनुर्नाम श्रियः पुत्रः शापाद्राक्षसतां गतः।
आख्यातस्तेन सुग्रीवः समर्थो वानराधिपः॥', 'danur nāma śriyaḥ putraḥ śāpād rākṣasatāṃ gataḥ
ākhyātas tena sugrīvaḥ samartho vānarādhipaḥ', null, 4004012),
('ramayana-4-4-13', 13, 'Kishkindha Kanda, Sarga 4, Verse 13', 'स ज्ञास्यति महावीर्यस्तव भार्यापहारिणम्।
एवमुक्त्वा दनुः स्वर्गं भ्राजमानो गतः सुखम्॥', 'sa jñāsyati mahāvīryas tava bhāryāpahāriṇam
evam uktvā danuḥ svargaṃ bhrājamāno gataḥ sukham', null, 4004013),
('ramayana-4-4-14', 14, 'Kishkindha Kanda, Sarga 4, Verse 14', 'एतत्ते सर्वमाख्यातं याथातथ्येन पृच्छतः।
अहं चैव हि रामश्च सुग्रीवं शरणं गतौ॥', 'etat te sarvam ākhyātaṃ yāthātathyena pṛcchataḥ
ahaṃ caiva hi rāmaś ca sugrīvaṃ śaraṇaṃ gatau', null, 4004014),
('ramayana-4-4-15', 15, 'Kishkindha Kanda, Sarga 4, Verse 15', 'एष दत्त्वा च वित्तानि प्राप्य चानुत्तमं यशः।
लोकनाथः पुरा भूत्वा सुग्रीवं नाथमिच्छति॥', 'eṣa dattvā ca vittāni prāpya cānuttamaṃ yaśaḥ
lokanāthaḥ purā bhūtvā sugrīvaṃ nātham icchati', null, 4004015),
('ramayana-4-4-16', 16, 'Kishkindha Kanda, Sarga 4, Verse 16', 'शोकाभिभूते रामे तु शोकार्ते शरणं गते।
कर्तुमर्हति सुग्रीवः प्रसादं सह यूथपैः॥', 'śokābhibhūte rāme tu śokārte śaraṇaṃ gate
kartum arhati sugrīvaḥ prasādaṃ saha yūthapaiḥ', null, 4004016),
('ramayana-4-4-17', 17, 'Kishkindha Kanda, Sarga 4, Verse 17', 'एवं ब्रुवाणं सौमित्रिं करुणं साश्रुपातनम्।
हनूमान्प्रत्युवाचेदं वाक्यं वाक्यविशारदः॥', 'evaṃ bruvāṇaṃ saumitriṃ karuṇaṃ sāśrupātanam
hanūmān pratyuvācedaṃ vākyaṃ vākyaviśāradaḥ', null, 4004017),
('ramayana-4-4-18', 18, 'Kishkindha Kanda, Sarga 4, Verse 18', 'ईदृशा बुद्धिसंपन्ना जितक्रोधा जितेन्द्रियाः।
द्रष्टव्या वानरेन्द्रेण दिष्ट्या दर्शनमागताः॥', 'īdṛśā buddhisaṃpannā jitakrodhā jitendriyāḥ
draṣṭavyā vānarendreṇa diṣṭyā darśanam āgatāḥ', null, 4004018),
('ramayana-4-4-19', 19, 'Kishkindha Kanda, Sarga 4, Verse 19', 'स हि राज्याच्च विभ्रष्टः कृतवैरश्च वालिना।
हृतदारो वने त्रस्तो भ्रात्रा विनिकृतो भृशम्॥', 'sa hi rājyāc ca vibhraṣṭaḥ kṛtavairaś ca vālinā
hṛtadāro vane trasto bhrātrā vinikṛto bhṛśam', null, 4004019),
('ramayana-4-4-20', 20, 'Kishkindha Kanda, Sarga 4, Verse 20', 'करिष्यति स साहाय्यं युवयोर्भास्करात्मजः।
सुग्रीवः सह चास्माभिः सीतायाः परिमार्गणे॥', 'kariṣyati sa sāhāyyaṃ yuvayor bhāskarātmajaḥ
sugrīvaḥ saha cāsmābhiḥ sītāyāḥ parimārgaṇe', null, 4004020),
('ramayana-4-4-21', 21, 'Kishkindha Kanda, Sarga 4, Verse 21', 'इत्येवमुक्त्वा हनुमाञ्श्लक्ष्णं मधुरया गिरा।
बभाषे सोऽभिगच्छामः सुग्रीवमिति राघवम्॥', 'ity evam uktvā hanumāñ ślakṣṇaṃ madhurayā girā
babhāṣe so ''bhigacchāmaḥ sugrīvam iti rāghavam', null, 4004021),
('ramayana-4-4-22', 22, 'Kishkindha Kanda, Sarga 4, Verse 22', 'एवं ब्रुवाणं धर्मात्मा हनूमन्तं स लक्ष्मणः।
प्रतिपूज्य यथान्यायमिदं प्रोवाच राघवम्॥', 'evaṃ bruvāṇaṃ dharmātmā hanūmantaṃ sa lakṣmaṇaḥ
pratipūjya yathānyāyam idaṃ provāca rāghavam', null, 4004022),
('ramayana-4-4-23', 23, 'Kishkindha Kanda, Sarga 4, Verse 23', 'कपिः कथयते हृष्टो यथायं मारुतात्मजः।
कृत्यवान्सोऽपि संप्राप्तः कृतकृत्योऽसि राघव॥', 'kapiḥ kathayate hṛṣṭo yathāyaṃ mārutātmajaḥ
kṛtyavān so ''pi saṃprāptaḥ kṛtakṛtyo ''si rāghava', null, 4004023),
('ramayana-4-4-24', 24, 'Kishkindha Kanda, Sarga 4, Verse 24', 'प्रसन्नमुखवर्णश्च व्यक्तं हृष्टश्च भाषते।
नानृतं वक्ष्यते वीरो हनूमान्मारुतात्मजः॥', 'prasannamukhavarṇaś ca vyaktaṃ hṛṣṭaś ca bhāṣate
nānṛtaṃ vakṣyate vīro hanūmān mārutātmajaḥ', null, 4004024),
('ramayana-4-4-25', 25, 'Kishkindha Kanda, Sarga 4, Verse 25', 'ततः स तु महाप्राज्ञो हनूमान्मारुतात्मजः।
जगामादाय तौ वीरौ हरिराजाय राघवौ॥', 'tataḥ sa tu mahāprājño hanūmān mārutātmajaḥ
jagāmādāya tau vīrau harirājāya rāghavau', null, 4004025),
('ramayana-4-4-26', 26, 'Kishkindha Kanda, Sarga 4, Verse 26', 'स तु विपुल यशाः कपिप्रवीरः पवनसुतः कृतकृत्यवत्प्रहृष्टः।
गिरिवरमुरुविक्रमः प्रयातः स शुभमतिः सह रामलक्ष्मणाभ्याम्॥', 'sa tu vipula yaśāḥ kapipravīraḥ pavanasutaḥ kṛtakṛtyavat prahṛṣṭaḥ
girivaram uruvikramaḥ prayātaḥ sa śubhamatiḥ saha rāmalakṣmaṇābhyām', null, 4004026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 5 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-5-1', 1, 'Kishkindha Kanda, Sarga 5, Verse 1', 'ऋश्यमूकात्तु हनुमान्गत्वा तं मलयं गिरम्।
आचचक्षे तदा वीरौ कपिराजाय राघवौ॥', 'ṛśyamūkāt tu hanumān gatvā taṃ malayaṃ giram
ācacakṣe tadā vīrau kapirājāya rāghavau', null, 4005001),
('ramayana-4-5-2', 2, 'Kishkindha Kanda, Sarga 5, Verse 2', 'अयं रामो महाप्राज्ञः संप्राप्तो दृढविक्रमः।
लक्ष्मणेन सह भ्रात्रा रामोऽयं सत्यविक्रमः॥', 'ayaṃ rāmo mahāprājñaḥ saṃprāpto dṛḍhavikramaḥ
lakṣmaṇena saha bhrātrā rāmo ''yaṃ satyavikramaḥ', null, 4005002),
('ramayana-4-5-3', 3, 'Kishkindha Kanda, Sarga 5, Verse 3', 'इक्ष्वाकूणां कुले जातो रामो दशरथात्मजः।
धर्मे निगदितश्चैव पितुर्निर्देशपालकः॥', 'ikṣvākūṇāṃ kule jāto rāmo daśarathātmajaḥ
dharme nigaditaś caiva pitur nirdeśapālakaḥ', null, 4005003),
('ramayana-4-5-4', 4, 'Kishkindha Kanda, Sarga 5, Verse 4', 'तस्यास्य वसतोऽरण्ये नियतस्य महात्मनः।
रक्षसापहृता भार्या स त्वां शरणमागतः॥', 'tasyāsya vasato ''raṇye niyatasya mahātmanaḥ
rakṣasāpahṛtā bhāryā sa tvāṃ śaraṇam āgataḥ', null, 4005004),
('ramayana-4-5-5', 5, 'Kishkindha Kanda, Sarga 5, Verse 5', 'राजसूयाश्वमेधैश्च वह्निर्येनाभितर्पितः।
दक्षिणाश्च तथोत्सृष्टा गावः शतसहस्रशः॥', 'rājasūyāśvamedhaiś ca vahnir yenābhitarpitaḥ
dakṣiṇāś ca tathotsṛṣṭā gāvaḥ śatasahasraśaḥ', null, 4005005),
('ramayana-4-5-6', 6, 'Kishkindha Kanda, Sarga 5, Verse 6', 'तपसा सत्यवाक्येन वसुधा येन पालिता।
स्त्रीहेतोस्तस्य पुत्रोऽयं रामस्त्वां शरणं गतः॥', 'tapasā satyavākyena vasudhā yena pālitā
strīhetos tasya putro ''yaṃ rāmas tvāṃ śaraṇaṃ gataḥ', null, 4005006),
('ramayana-4-5-7', 7, 'Kishkindha Kanda, Sarga 5, Verse 7', 'भवता सख्यकामौ तौ भ्रातरौ रामलक्ष्मणौ।
प्रतिगृह्यार्चयस्वेमौ पूजनीयतमावुभौ॥', 'bhavatā sakhyakāmau tau bhrātarau rāmalakṣmaṇau
pratigṛhyārcayasvemau pūjanīyatamāv ubhau', null, 4005007),
('ramayana-4-5-8', 8, 'Kishkindha Kanda, Sarga 5, Verse 8', 'श्रुत्वा हनुमतो वाक्यं सुग्रीवो हृष्टमानसः।
भयं स राघवाद्घोरं प्रजहौ विगतज्वरः॥', 'śrutvā hanumato vākyaṃ sugrīvo hṛṣṭamānasaḥ
bhayaṃ sa rāghavād ghoraṃ prajahau vigatajvaraḥ', null, 4005008),
('ramayana-4-5-9', 9, 'Kishkindha Kanda, Sarga 5, Verse 9', 'स कृत्वा मानुषं रूपं सुग्रीवः प्लवगाधिपः।
दर्शनीयतमो भूत्वा प्रीत्या प्रोवाच राघवम्॥', 'sa kṛtvā mānuṣaṃ rūpaṃ sugrīvaḥ plavagādhipaḥ
darśanīyatamo bhūtvā prītyā provāca rāghavam', null, 4005009),
('ramayana-4-5-10', 10, 'Kishkindha Kanda, Sarga 5, Verse 10', 'भवान्धर्मविनीतश्च विक्रान्तः सर्ववत्सलः।
आख्याता वायुपुत्रेण तत्त्वतो मे भवद्गुणाः॥', 'bhavān dharmavinītaś ca vikrāntaḥ sarvavatsalaḥ
ākhyātā vāyuputreṇa tattvato me bhavadguṇāḥ', null, 4005010),
('ramayana-4-5-11', 11, 'Kishkindha Kanda, Sarga 5, Verse 11', 'तन्ममैवैष सत्कारो लाभश्चैवोत्तमः प्रभो।
यत्त्वमिच्छसि सौहार्दं वानरेण मया सह॥', 'tan mamaivaiṣa satkāro lābhaś caivottamaḥ prabho
yat tvam icchasi sauhārdaṃ vānareṇa mayā saha', null, 4005011),
('ramayana-4-5-12', 12, 'Kishkindha Kanda, Sarga 5, Verse 12', 'रोचते यदि वा सख्यं बाहुरेष प्रसारितः।
गृह्यतां पाणिना पाणिर्मर्यादा वध्यतां ध्रुवा॥', 'rocate yadi vā sakhyaṃ bāhur eṣa prasāritaḥ
gṛhyatāṃ pāṇinā pāṇir maryādā vadhyatāṃ dhruvā', null, 4005012),
('ramayana-4-5-13', 13, 'Kishkindha Kanda, Sarga 5, Verse 13', 'एतत्तु वचनं श्रुत्वा सुग्रीवस्य सुभाषितम्।
संप्रहृष्टमना हस्तं पीडयामास पाणिना।
हृद्यं सौहृदमालम्ब्य पर्यष्वजत पीडितम्॥', 'etat tu vacanaṃ śrutvā sugrīvasya subhāṣitam
saṃprahṛṣṭamanā hastaṃ pīḍayām āsa pāṇinā
hṛdyaṃ sauhṛdam ālambya paryaṣvajata pīḍitam', null, 4005013),
('ramayana-4-5-14', 14, 'Kishkindha Kanda, Sarga 5, Verse 14', 'ततो हनूमान्संत्यज्य भिक्षुरूपमरिंदमः।
काष्ठयोः स्वेन रूपेण जनयामास पावकम्॥', 'tato hanūmān saṃtyajya bhikṣurūpam ariṃdamaḥ
kāṣṭhayoḥ svena rūpeṇa janayām āsa pāvakam', null, 4005014),
('ramayana-4-5-15', 15, 'Kishkindha Kanda, Sarga 5, Verse 15', 'दीप्यमानं ततो वह्निं पुष्पैरभ्यर्च्य सत्कृतम्।
तयोर्मध्ये तु सुप्रीतो निदधे सुसमाहितः॥', 'dīpyamānaṃ tato vahniṃ puṣpair abhyarcya satkṛtam
tayor madhye tu suprīto nidadhe susamāhitaḥ', null, 4005015),
('ramayana-4-5-16', 16, 'Kishkindha Kanda, Sarga 5, Verse 16', 'ततोऽग्निं दीप्यमानं तौ चक्रतुश्च प्रदक्षिणम्।
सुग्रीवो राघवश्चैव वयस्यत्वमुपागतौ॥', 'tato ''gniṃ dīpyamānaṃ tau cakratuś ca pradakṣiṇam
sugrīvo rāghavaś caiva vayasyatvam upāgatau', null, 4005016),
('ramayana-4-5-17', 17, 'Kishkindha Kanda, Sarga 5, Verse 17', 'ततः सुप्रीत मनसौ तावुभौ हरिराघवौ।
अन्योन्यमभिवीक्षन्तौ न तृप्तिमुपजग्मतुः॥', 'tataḥ suprīta manasau tāv ubhau harirāghavau
anyonyam abhivīkṣantau na tṛptim upajagmatuḥ', null, 4005017),
('ramayana-4-5-18', 18, 'Kishkindha Kanda, Sarga 5, Verse 18', 'ततः सर्वार्थविद्वांसं रामं दशरथात्मजम्।
सुग्रीवः प्राह तेजस्वी वाक्यमेकमनास्तदा॥', 'tataḥ sarvārthavidvāṃsaṃ rāmaṃ daśarathātmajam
sugrīvaḥ prāha tejasvī vākyam ekamanās tadā', null, 4005018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 6 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-6-1', 1, 'Kishkindha Kanda, Sarga 6, Verse 1', 'अयमाख्याति मे राम सचिवो मन्त्रिसत्तमः।
हनुमान्यन्निमित्तं त्वं निर्जनं वनमागतः॥', 'ayam ākhyāti me rāma sacivo mantrisattamaḥ
hanumān yannimittaṃ tvaṃ nirjanaṃ vanam āgataḥ', null, 4006001),
('ramayana-4-6-2', 2, 'Kishkindha Kanda, Sarga 6, Verse 2', 'लक्ष्मणेन सह भ्रात्रा वसतश्च वने तव।
रक्षसापहृता भार्या मैथिली जनकात्मजा॥', 'lakṣmaṇena saha bhrātrā vasataś ca vane tava
rakṣasāpahṛtā bhāryā maithilī janakātmajā', null, 4006002),
('ramayana-4-6-3', 3, 'Kishkindha Kanda, Sarga 6, Verse 3', 'त्वया वियुक्ता रुदती लक्ष्मणेन च धीमता।
अन्तरं प्रेप्सुना तेन हत्वा गृध्रं जटायुषम्॥', 'tvayā viyuktā rudatī lakṣmaṇena ca dhīmatā
antaraṃ prepsunā tena hatvā gṛdhraṃ jaṭāyuṣam', null, 4006003),
('ramayana-4-6-4', 4, 'Kishkindha Kanda, Sarga 6, Verse 4', 'भार्यावियोगजं दुःखं नचिरात्त्वं विमोक्ष्यसे।
अहं तामानयिष्यामि नष्टां वेदश्रुतिं यथा॥', 'bhāryāviyogajaṃ duḥkhaṃ nacirāt tvaṃ vimokṣyase
ahaṃ tām ānayiṣyāmi naṣṭāṃ vedaśrutiṃ yathā', null, 4006004),
('ramayana-4-6-5', 5, 'Kishkindha Kanda, Sarga 6, Verse 5', 'रसातले वा वर्तन्तीं वर्तन्तीं वा नभस्तले।
अहमानीय दास्यामि तव भार्यामरिंदम॥', 'rasātale vā vartantīṃ vartantīṃ vā nabhastale
aham ānīya dāsyāmi tava bhāryām ariṃdama', null, 4006005),
('ramayana-4-6-6', 6, 'Kishkindha Kanda, Sarga 6, Verse 6', 'इदं तथ्यं मम वचस्त्वमवेहि च राघव।
त्यज शोकं महाबाहो तां कान्तामानयामि ते॥', 'idaṃ tathyaṃ mama vacas tvam avehi ca rāghava
tyaja śokaṃ mahābāho tāṃ kāntām ānayāmi te', null, 4006006),
('ramayana-4-6-7', 7, 'Kishkindha Kanda, Sarga 6, Verse 7', 'अनुमानात्तु जानामि मैथिली सा न संशयः।
ह्रियमाणा मया दृष्टा रक्षसा क्रूरकर्मणा॥', 'anumānāt tu jānāmi maithilī sā na saṃśayaḥ
hriyamāṇā mayā dṛṣṭā rakṣasā krūrakarmaṇā', null, 4006007),
('ramayana-4-6-8', 8, 'Kishkindha Kanda, Sarga 6, Verse 8', 'क्रोशन्ती राम रामेति लक्ष्मणेति च विस्वरम्।
स्फुरन्ती रावणस्याङ्के पन्नगेन्द्रवधूर्यथा॥', 'krośantī rāma rāmeti lakṣmaṇeti ca visvaram
sphurantī rāvaṇasyāṅke pannagendravadhūr yathā', null, 4006008),
('ramayana-4-6-9', 9, 'Kishkindha Kanda, Sarga 6, Verse 9', 'आत्मना पञ्चमं मां हि दृष्ट्वा शैलतटे स्थितम्।
उत्तरीयं तया त्यक्तं शुभान्याभरणानि च॥', 'ātmanā pañcamaṃ māṃ hi dṛṣṭvā śailataṭe sthitam
uttarīyaṃ tayā tyaktaṃ śubhāny ābharaṇāni ca', null, 4006009),
('ramayana-4-6-10', 10, 'Kishkindha Kanda, Sarga 6, Verse 10', 'तान्यस्माभिर्गृहीतानि निहितानि च राघव।
आनयिष्याम्यहं तानि प्रत्यभिज्ञातुमर्हसि॥', 'tāny asmābhir gṛhītāni nihitāni ca rāghava
ānayiṣyāmy ahaṃ tāni pratyabhijñātum arhasi', null, 4006010),
('ramayana-4-6-11', 11, 'Kishkindha Kanda, Sarga 6, Verse 11', 'तमब्रवीत्ततो रामः सुग्रीवं प्रियवादिनम्।
आनयस्व सखे शीघ्रं किमर्थं प्रविलम्बसे॥', 'tam abravīt tato rāmaḥ sugrīvaṃ priyavādinam
ānayasva sakhe śīghraṃ kimarthaṃ pravilambase', null, 4006011),
('ramayana-4-6-12', 12, 'Kishkindha Kanda, Sarga 6, Verse 12', 'एवमुक्तस्तु सुग्रीवः शैलस्य गहनां गुहाम्।
प्रविवेश ततः शीघ्रं राघवप्रियकाम्यया॥', 'evam uktas tu sugrīvaḥ śailasya gahanāṃ guhām
praviveśa tataḥ śīghraṃ rāghavapriyakāmyayā', null, 4006012),
('ramayana-4-6-13', 13, 'Kishkindha Kanda, Sarga 6, Verse 13', 'उत्तरीयं गृहीत्वा तु शुभान्याभरणानि च।
इदं पश्येति रामाय दर्शयामास वानरः॥', 'uttarīyaṃ gṛhītvā tu śubhāny ābharaṇāni ca
idaṃ paśyeti rāmāya darśayām āsa vānaraḥ', null, 4006013),
('ramayana-4-6-14', 14, 'Kishkindha Kanda, Sarga 6, Verse 14', 'ततो गृहीत्वा तद्वासः शुभान्याभरणानि च।
अभवद्बाष्पसंरुद्धो नीहारेणेव चन्द्रमाः॥', 'tato gṛhītvā tadvāsaḥ śubhāny ābharaṇāni ca
abhavad bāṣpasaṃruddho nīhāreṇeva candramāḥ', null, 4006014),
('ramayana-4-6-15', 15, 'Kishkindha Kanda, Sarga 6, Verse 15', 'सीतास्नेहप्रवृत्तेन स तु बाष्पेण दूषितः।
हा प्रियेति रुदन्धैर्यमुत्सृज्य न्यपतत्क्षितौ॥', 'sītāsnehapravṛttena sa tu bāṣpeṇa dūṣitaḥ
hā priyeti rudan dhairyam utsṛjya nyapatat kṣitau', null, 4006015),
('ramayana-4-6-16', 16, 'Kishkindha Kanda, Sarga 6, Verse 16', 'हृदि कृत्वा स बहुशस्तमलंकारमुत्तमम्।
निशश्वास भृशं सर्पो बिलस्थ इव रोषितः॥', 'hṛdi kṛtvā sa bahuśas tam alaṃkāram uttamam
niśaśvāsa bhṛśaṃ sarpo bilastha iva roṣitaḥ', null, 4006016),
('ramayana-4-6-17', 17, 'Kishkindha Kanda, Sarga 6, Verse 17', 'अविच्छिन्नाश्रुवेगस्तु सौमित्रिं वीक्ष्य पार्श्वतः।
परिदेवयितुं दीनं रामः समुपचक्रमे॥', 'avicchinnāśruvegas tu saumitriṃ vīkṣya pārśvataḥ
paridevayituṃ dīnaṃ rāmaḥ samupacakrame', null, 4006017),
('ramayana-4-6-18', 18, 'Kishkindha Kanda, Sarga 6, Verse 18', 'पश्य लक्ष्मण वैदेह्या संत्यक्तं ह्रियमाणया।
उत्तरीयमिदं भूमौ शरीराद्भूषणानि च॥', 'paśya lakṣmaṇa vaidehyā saṃtyaktaṃ hriyamāṇayā
uttarīyam idaṃ bhūmau śarīrād bhūṣaṇāni ca', null, 4006018),
('ramayana-4-6-19', 19, 'Kishkindha Kanda, Sarga 6, Verse 19', 'शाद्वलिन्यां ध्रुवं भूम्यां सीतया ह्रियमाणया।
उत्सृष्टं भूषणमिदं तथारूपं हि दृश्यते॥', 'śādvalinyāṃ dhruvaṃ bhūmyāṃ sītayā hriyamāṇayā
utsṛṣṭaṃ bhūṣaṇam idaṃ tathārūpaṃ hi dṛśyate', null, 4006019),
('ramayana-4-6-20', 20, 'Kishkindha Kanda, Sarga 6, Verse 20', 'ब्रूहि सुग्रीव कं देशं ह्रियन्ती लक्षिता त्वया।
रक्षसा रौद्ररूपेण मम प्राणसमा प्रिया॥', 'brūhi sugrīva kaṃ deśaṃ hriyantī lakṣitā tvayā
rakṣasā raudrarūpeṇa mama prāṇasamā priyā', null, 4006020),
('ramayana-4-6-21', 21, 'Kishkindha Kanda, Sarga 6, Verse 21', 'क्व वा वसति तद्रक्षो महद्व्यसनदं मम।
यन्निमित्तमहं सर्वान्नाशयिष्यामि राक्षसान्॥', 'kva vā vasati tad rakṣo mahad vyasanadaṃ mama
yannimittam ahaṃ sarvān nāśayiṣyāmi rākṣasān', null, 4006021),
('ramayana-4-6-22', 22, 'Kishkindha Kanda, Sarga 6, Verse 22', 'हरता मैथिलीं येन मां च रोषयता भृशम्।
आत्मनो जीवितान्ताय मृत्युद्वारमपावृतम्॥', 'haratā maithilīṃ yena māṃ ca roṣayatā bhṛśam
ātmano jīvitāntāya mṛtyudvāram apāvṛtam', null, 4006022),
('ramayana-4-6-23', 23, 'Kishkindha Kanda, Sarga 6, Verse 23', 'मम दयिततमा हृता वनाद्रजनिचरेण विमथ्य येन सा।
कथय मम रिपुं तमद्य वै प्रवगपते यमसंनिधिं नयामि॥', 'mama dayitatamā hṛtā vanād rajanicareṇa vimathya yena sā
kathaya mama ripuṃ tam adya vai pravagapate yamasaṃnidhiṃ nayāmi', null, 4006023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 7 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-7-1', 1, 'Kishkindha Kanda, Sarga 7, Verse 1', 'एवमुक्तस्तु सुग्रीवो रामेणार्तेन वानरः।
अब्रवीत्प्राञ्जलिर्वाक्यं सबाष्पं बाष्पगद्गदः॥', 'evam uktas tu sugrīvo rāmeṇārtena vānaraḥ
abravīt prāñjalir vākyaṃ sabāṣpaṃ bāṣpagadgadaḥ', null, 4007001),
('ramayana-4-7-2', 2, 'Kishkindha Kanda, Sarga 7, Verse 2', 'न जाने निलयं तस्य सर्वथा पापरक्षसः।
सामर्थ्यं विक्रमं वापि दौष्कुलेयस्य वा कुलम्॥', 'na jāne nilayaṃ tasya sarvathā pāparakṣasaḥ
sāmarthyaṃ vikramaṃ vāpi dauṣkuleyasya vā kulam', null, 4007002),
('ramayana-4-7-3', 3, 'Kishkindha Kanda, Sarga 7, Verse 3', 'सत्यं तु प्रतिजानामि त्यज शोकमरिंदम।
करिष्यामि तथा यत्नं यथा प्राप्स्यसि मैथिलीम्॥', 'satyaṃ tu pratijānāmi tyaja śokam ariṃdama
kariṣyāmi tathā yatnaṃ yathā prāpsyasi maithilīm', null, 4007003),
('ramayana-4-7-4', 4, 'Kishkindha Kanda, Sarga 7, Verse 4', 'रावणं सगणं हत्वा परितोष्यात्मपौरुषम्।
तथास्मि कर्ता नचिराद्यथा प्रीतो भविष्यसि॥', 'rāvaṇaṃ sagaṇaṃ hatvā paritoṣyātmapauruṣam
tathāsmi kartā nacirād yathā prīto bhaviṣyasi', null, 4007004),
('ramayana-4-7-5', 5, 'Kishkindha Kanda, Sarga 7, Verse 5', 'अलं वैक्लव्यमालम्ब्य धैर्यमात्मगतं स्मर।
त्वद्विधानां न सदृशमीदृशं बुद्धिलाघवम्॥', 'alaṃ vaiklavyam ālambya dhairyam ātmagataṃ smara
tvadvidhānāṃ na sadṛśam īdṛśaṃ buddhilāghavam', null, 4007005),
('ramayana-4-7-6', 6, 'Kishkindha Kanda, Sarga 7, Verse 6', 'मयापि व्यसनं प्राप्तं भार्या हरणजं महत्।
न चाहमेवं शोचामि न च धैर्यं परित्यजे॥', 'mayāpi vyasanaṃ prāptaṃ bhāryā haraṇajaṃ mahat
na cāham evaṃ śocāmi na ca dhairyaṃ parityaje', null, 4007006),
('ramayana-4-7-7', 7, 'Kishkindha Kanda, Sarga 7, Verse 7', 'नाहं तामनुशोचामि प्राकृतो वानरोऽपि सन्।
महात्मा च विनीतश्चा किं पुनर्धृतिमान्भवान्॥', 'nāhaṃ tām anuśocāmi prākṛto vānaro ''pi san
mahātmā ca vinītaś cā kiṃ punar dhṛtimān bhavān', null, 4007007),
('ramayana-4-7-8', 8, 'Kishkindha Kanda, Sarga 7, Verse 8', 'बाष्पमापतितं धैर्यान्निग्रहीतुं त्वमर्हसि।
मर्यादां सत्त्वयुक्तानां धृतिं नोत्स्रष्टुमर्हसि॥', 'bāṣpam āpatitaṃ dhairyān nigrahītuṃ tvam arhasi
maryādāṃ sattvayuktānāṃ dhṛtiṃ notsraṣṭum arhasi', null, 4007008),
('ramayana-4-7-9', 9, 'Kishkindha Kanda, Sarga 7, Verse 9', 'व्यसने वार्थ कृच्छ्रे वा भये वा जीवितान्तगे।
विमृशन्वै स्वया बुद्ध्या धृतिमान्नावसीदति॥', 'vyasane vārtha kṛcchre vā bhaye vā jīvitāntage
vimṛśan vai svayā buddhyā dhṛtimān nāvasīdati', null, 4007009),
('ramayana-4-7-10', 10, 'Kishkindha Kanda, Sarga 7, Verse 10', 'बालिशस्तु नरो नित्यं वैक्लव्यं योऽनुवर्तते।
स मज्जत्यवशः शोके भाराक्रान्तेव नौर्जले॥', 'bāliśas tu naro nityaṃ vaiklavyaṃ yo ''nuvartate
sa majjaty avaśaḥ śoke bhārākrānteva naur jale', null, 4007010),
('ramayana-4-7-11', 11, 'Kishkindha Kanda, Sarga 7, Verse 11', 'एषोऽञ्जलिर्मया बद्धः प्रणयात्त्वां प्रसादये।
पौरुषं श्रय शोकस्य नान्तरं दातुमर्हसि॥', 'eṣo ''ñjalir mayā baddhaḥ praṇayāt tvāṃ prasādaye
pauruṣaṃ śraya śokasya nāntaraṃ dātum arhasi', null, 4007011),
('ramayana-4-7-12', 12, 'Kishkindha Kanda, Sarga 7, Verse 12', 'ये शोकमनुवर्तन्ते न तेषां विद्यते सुखम्।
तेजश्च क्षीयते तेषां न त्वं शोचितुमर्हसि॥', 'ye śokam anuvartante na teṣāṃ vidyate sukham
tejaś ca kṣīyate teṣāṃ na tvaṃ śocitum arhasi', null, 4007012),
('ramayana-4-7-13', 13, 'Kishkindha Kanda, Sarga 7, Verse 13', 'हितं वयस्य भावेन ब्रूहि नोपदिशामि ते।
वयस्यतां पूजयन्मे न त्वं शोचितुमर्हसि॥', 'hitaṃ vayasya bhāvena brūhi nopadiśāmi te
vayasyatāṃ pūjayan me na tvaṃ śocitum arhasi', null, 4007013),
('ramayana-4-7-14', 14, 'Kishkindha Kanda, Sarga 7, Verse 14', 'मधुरं सान्त्वितस्तेन सुग्रीवेण स राघवः।
मुखमश्रुपरिक्लिन्नं वस्त्रान्तेन प्रमार्जयत्॥', 'madhuraṃ sāntvitas tena sugrīveṇa sa rāghavaḥ
mukham aśrupariklinnaṃ vastrāntena pramārjayat', null, 4007014),
('ramayana-4-7-15', 15, 'Kishkindha Kanda, Sarga 7, Verse 15', 'प्रकृतिष्ठस्तु काकुत्स्थः सुग्रीववचनात्प्रभुः।
संपरिष्वज्य सुग्रीवमिदं वचनमब्रवीत्॥', 'prakṛtiṣṭhas tu kākutsthaḥ sugrīvavacanāt prabhuḥ
saṃpariṣvajya sugrīvam idaṃ vacanam abravīt', null, 4007015),
('ramayana-4-7-16', 16, 'Kishkindha Kanda, Sarga 7, Verse 16', 'कर्तव्यं यद्वयस्येन स्निग्धेन च हितेन च।
अनुरूपं च युक्तं च कृतं सुग्रीव तत्त्वया॥', 'kartavyaṃ yad vayasyena snigdhena ca hitena ca
anurūpaṃ ca yuktaṃ ca kṛtaṃ sugrīva tat tvayā', null, 4007016),
('ramayana-4-7-17', 17, 'Kishkindha Kanda, Sarga 7, Verse 17', 'एष च प्रकृतिष्ठोऽहमनुनीतस्त्वया सखे।
दुर्लभो हीदृशो बन्धुरस्मिन्काले विशेषतः॥', 'eṣa ca prakṛtiṣṭho ''ham anunītas tvayā sakhe
durlabho hīdṛśo bandhur asmin kāle viśeṣataḥ', null, 4007017),
('ramayana-4-7-18', 18, 'Kishkindha Kanda, Sarga 7, Verse 18', 'किं तु यत्नस्त्वया कार्यो मैथिल्याः परिमार्गणे।
राक्षसस्य च रौद्रस्य रावणस्य दुरात्मनः॥', 'kiṃ tu yatnas tvayā kāryo maithilyāḥ parimārgaṇe
rākṣasasya ca raudrasya rāvaṇasya durātmanaḥ', null, 4007018),
('ramayana-4-7-19', 19, 'Kishkindha Kanda, Sarga 7, Verse 19', 'मया च यदनुष्ठेयं विस्रब्धेन तदुच्यताम्।
वर्षास्विव च सुक्षेत्रे सर्वं संपद्यते तव॥', 'mayā ca yad anuṣṭheyaṃ visrabdhena tad ucyatām
varṣāsv iva ca sukṣetre sarvaṃ saṃpadyate tava', null, 4007019),
('ramayana-4-7-20', 20, 'Kishkindha Kanda, Sarga 7, Verse 20', 'मया च यदिदं वाक्यमभिमानात्समीरितम्।
तत्त्वया हरिशार्दूल तत्त्वमित्युपधार्यताम्॥', 'mayā ca yad idaṃ vākyam abhimānāt samīritam
tat tvayā hariśārdūla tattvam ity upadhāryatām', null, 4007020),
('ramayana-4-7-21', 21, 'Kishkindha Kanda, Sarga 7, Verse 21', 'अनृतं नोक्तपूर्वं मे न च वक्ष्ये कदा चन।
एतत्ते प्रतिजानामि सत्येनैव शपामि ते॥', 'anṛtaṃ noktapūrvaṃ me na ca vakṣye kadā cana
etat te pratijānāmi satyenaiva śapāmi te', null, 4007021),
('ramayana-4-7-22', 22, 'Kishkindha Kanda, Sarga 7, Verse 22', 'ततः प्रहृष्टः सुग्रीवो वानरैः सचिवैः सह।
राघवस्य वचः श्रुत्वा प्रतिज्ञातं विशेषतः॥', 'tataḥ prahṛṣṭaḥ sugrīvo vānaraiḥ sacivaiḥ saha
rāghavasya vacaḥ śrutvā pratijñātaṃ viśeṣataḥ', null, 4007022),
('ramayana-4-7-23', 23, 'Kishkindha Kanda, Sarga 7, Verse 23', 'महानुभावस्य वचो निशम्य हरिर्नराणामृषभस्य तस्य।
कृतं स मेने हरिवीर मुख्यस्तदा स्वकार्यं हृदयेन विद्वान्॥', 'mahānubhāvasya vaco niśamya harir narāṇām ṛṣabhasya tasya
kṛtaṃ sa mene harivīra mukhyas tadā svakāryaṃ hṛdayena vidvān', null, 4007023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 8 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-8-1', 1, 'Kishkindha Kanda, Sarga 8, Verse 1', 'परितुष्टस्तु सुग्रीवस्तेन वाक्येन वानरः।
लक्ष्मणस्याग्रजं राममिदं वचनमब्रवीत्॥', 'parituṣṭas tu sugrīvas tena vākyena vānaraḥ
lakṣmaṇasyāgrajaṃ rāmam idaṃ vacanam abravīt', null, 4008001),
('ramayana-4-8-2', 2, 'Kishkindha Kanda, Sarga 8, Verse 2', 'सर्वथाहमनुग्राह्यो देवतानामसंशयः।
उपपन्नगुणोपेतः सखा यस्य भवान्मम॥', 'sarvathāham anugrāhyo devatānām asaṃśayaḥ
upapannaguṇopetaḥ sakhā yasya bhavān mama', null, 4008002),
('ramayana-4-8-3', 3, 'Kishkindha Kanda, Sarga 8, Verse 3', 'शक्यं खलु भवेद्राम सहायेन त्वयानघ।
सुरराज्यमपि प्राप्तुं स्वराज्यं किं पुनः प्रभो॥', 'śakyaṃ khalu bhaved rāma sahāyena tvayānagha
surarājyam api prāptuṃ svarājyaṃ kiṃ punaḥ prabho', null, 4008003),
('ramayana-4-8-4', 4, 'Kishkindha Kanda, Sarga 8, Verse 4', 'सोऽहं सभाज्यो बन्धूनां सुहृदां चैव राघव।
यस्याग्निसाक्षिकं मित्रं लब्धं राघववंशजम्॥', 'so ''haṃ sabhājyo bandhūnāṃ suhṛdāṃ caiva rāghava
yasyāgnisākṣikaṃ mitraṃ labdhaṃ rāghavavaṃśajam', null, 4008004),
('ramayana-4-8-5', 5, 'Kishkindha Kanda, Sarga 8, Verse 5', 'अहमप्यनुरूपस्ते वयस्यो ज्ञास्यसे शनैः।
न तु वक्तुं समर्थोऽहं स्वयमात्मगतान्गुणान्॥', 'aham apy anurūpas te vayasyo jñāsyase śanaiḥ
na tu vaktuṃ samartho ''haṃ svayam ātmagatān guṇān', null, 4008005),
('ramayana-4-8-6', 6, 'Kishkindha Kanda, Sarga 8, Verse 6', 'महात्मनां तु भूयिष्ठं त्वद्विधानां कृतात्मनाम्।
निश्चला भवति प्रीतिर्धैर्यमात्मवतामिव॥', 'mahātmanāṃ tu bhūyiṣṭhaṃ tvadvidhānāṃ kṛtātmanām
niścalā bhavati prītir dhairyam ātmavatām iva', null, 4008006),
('ramayana-4-8-7', 7, 'Kishkindha Kanda, Sarga 8, Verse 7', 'रजतं वा सुवर्णं वा वस्त्राण्याभरणानि वा।
अविभक्तानि साधूनामवगच्छन्ति साधवः॥', 'rajataṃ vā suvarṇaṃ vā vastrāṇy ābharaṇāni vā
avibhaktāni sādhūnām avagacchanti sādhavaḥ', null, 4008007),
('ramayana-4-8-8', 8, 'Kishkindha Kanda, Sarga 8, Verse 8', 'आढ्यो वापि दरिद्रो वा दुःखितः सुखितोऽपि वा।
निर्दोषो वा सदोषो वा वयस्यः परमा गतिः॥', 'āḍhyo vāpi daridro vā duḥkhitaḥ sukhito ''pi vā
nirdoṣo vā sadoṣo vā vayasyaḥ paramā gatiḥ', null, 4008008),
('ramayana-4-8-9', 9, 'Kishkindha Kanda, Sarga 8, Verse 9', 'धनत्यागः सुखत्यागो देहत्यागोऽपि वा पुनः।
वयस्यार्थे प्रवर्तन्ते स्नेहं दृष्ट्वा तथाविधम्॥', 'dhanatyāgaḥ sukhatyāgo dehatyāgo ''pi vā punaḥ
vayasyārthe pravartante snehaṃ dṛṣṭvā tathāvidham', null, 4008009),
('ramayana-4-8-10', 10, 'Kishkindha Kanda, Sarga 8, Verse 10', 'तत्तथेत्यब्रवीद्रामः सुग्रीवं प्रियवादिनम्।
लक्ष्मणस्याग्रतो लक्ष्म्या वासवस्येव धीमतः॥', 'tat tathety abravīd rāmaḥ sugrīvaṃ priyavādinam
lakṣmaṇasyāgrato lakṣmyā vāsavasyeva dhīmataḥ', null, 4008010),
('ramayana-4-8-11', 11, 'Kishkindha Kanda, Sarga 8, Verse 11', 'ततो रामं स्थितं दृष्ट्वा लक्ष्मणं च महाबलम्।
सुग्रीवः सर्वतश्चक्षुर्वने लोलमपातयत्॥', 'tato rāmaṃ sthitaṃ dṛṣṭvā lakṣmaṇaṃ ca mahābalam
sugrīvaḥ sarvataś cakṣur vane lolam apātayat', null, 4008011),
('ramayana-4-8-12', 12, 'Kishkindha Kanda, Sarga 8, Verse 12', 'स ददर्श ततः सालमविदूरे हरीश्वरः।
सुपुष्पमीषत्पत्राढ्यं भ्रमरैरुपशोभितम्॥', 'sa dadarśa tataḥ sālam avidūre harīśvaraḥ
supuṣpam īṣatpatrāḍhyaṃ bhramarair upaśobhitam', null, 4008012),
('ramayana-4-8-13', 13, 'Kishkindha Kanda, Sarga 8, Verse 13', 'तस्यैकां पर्णबहुलां भङ्क्त्वा शाखां सुपुष्पिताम्।
सालस्यास्तीर्य सुग्रीवो निषसाद सराघवः॥', 'tasyaikāṃ parṇabahulāṃ bhaṅktvā śākhāṃ supuṣpitām
sālasyāstīrya sugrīvo niṣasāda sarāghavaḥ', null, 4008013),
('ramayana-4-8-14', 14, 'Kishkindha Kanda, Sarga 8, Verse 14', 'तावासीनौ ततो दृष्ट्वा हनूमानपि लक्ष्मणम्।
सालशाखां समुत्पाट्य विनीतमुपवेशयत्॥', 'tāv āsīnau tato dṛṣṭvā hanūmān api lakṣmaṇam
sālaśākhāṃ samutpāṭya vinītam upaveśayat', null, 4008014),
('ramayana-4-8-15', 15, 'Kishkindha Kanda, Sarga 8, Verse 15', 'ततः प्रहृष्टः सुग्रीवः श्लक्ष्णं मधुरया गिरा।
उवाच प्रणयाद्रामं हर्षव्याकुलिताक्षरम्॥', 'tataḥ prahṛṣṭaḥ sugrīvaḥ ślakṣṇaṃ madhurayā girā
uvāca praṇayād rāmaṃ harṣavyākulitākṣaram', null, 4008015),
('ramayana-4-8-16', 16, 'Kishkindha Kanda, Sarga 8, Verse 16', 'अहं विनिकृतो भ्रात्रा चराम्येष भयार्दितः।
ऋश्यमूकं गिरिवरं हृतभार्यः सुदुःखितः॥', 'ahaṃ vinikṛto bhrātrā carāmy eṣa bhayārditaḥ
ṛśyamūkaṃ girivaraṃ hṛtabhāryaḥ suduḥkhitaḥ', null, 4008016),
('ramayana-4-8-17', 17, 'Kishkindha Kanda, Sarga 8, Verse 17', 'सोऽहं त्रस्तो भये मग्नो वसाम्युद्भ्रान्तचेतनः।
वालिना निकृतो भ्रात्रा कृतवैरश्च राघव॥', 'so ''haṃ trasto bhaye magno vasāmy udbhrāntacetanaḥ
vālinā nikṛto bhrātrā kṛtavairaś ca rāghava', null, 4008017),
('ramayana-4-8-18', 18, 'Kishkindha Kanda, Sarga 8, Verse 18', 'वालिनो मे भयार्तस्य सर्वलोकाभयंकर।
ममापि त्वमनाथस्य प्रसादं कर्तुमर्हसि॥', 'vālino me bhayārtasya sarvalokābhayaṃkara
mamāpi tvam anāthasya prasādaṃ kartum arhasi', null, 4008018),
('ramayana-4-8-19', 19, 'Kishkindha Kanda, Sarga 8, Verse 19', 'एवमुक्तस्तु तेजस्वी धर्मज्ञो धर्मवत्सलः।
प्रत्युवाच स काकुत्स्थः सुग्रीवं प्रहसन्निव॥', 'evam uktas tu tejasvī dharmajño dharmavatsalaḥ
pratyuvāca sa kākutsthaḥ sugrīvaṃ prahasann iva', null, 4008019),
('ramayana-4-8-20', 20, 'Kishkindha Kanda, Sarga 8, Verse 20', 'उपकारफलं मित्रमपकारोऽरिलक्षणम्।
अद्यैव तं हनिष्यामि तव भार्यापहारिणम्॥', 'upakāraphalaṃ mitram apakāro ''rilakṣaṇam
adyaiva taṃ haniṣyāmi tava bhāryāpahāriṇam', null, 4008020),
('ramayana-4-8-21', 21, 'Kishkindha Kanda, Sarga 8, Verse 21', 'इमे हि मे महावेगाः पत्रिणस्तिग्मतेजसः।
कार्तिकेयवनोद्भूताः शरा हेमविभूषिताः॥', 'ime hi me mahāvegāḥ patriṇas tigmatejasaḥ
kārtikeyavanodbhūtāḥ śarā hemavibhūṣitāḥ', null, 4008021),
('ramayana-4-8-22', 22, 'Kishkindha Kanda, Sarga 8, Verse 22', 'कङ्कपत्रप्रतिच्छन्ना महेन्द्राशनिसंनिभाः।
सुपर्वाणः सुतीक्ष्णाग्रा सरोषा भुजगा इव॥', 'kaṅkapatrapraticchannā mahendrāśanisaṃnibhāḥ
suparvāṇaḥ sutīkṣṇāgrā saroṣā bhujagā iva', null, 4008022),
('ramayana-4-8-23', 23, 'Kishkindha Kanda, Sarga 8, Verse 23', 'भ्रातृसंज्ञममित्रं ते वालिनं कृतकिल्बिषम्।
शरैर्विनिहतं पश्य विकीर्णमिव पर्वतम्॥', 'bhrātṛsaṃjñam amitraṃ te vālinaṃ kṛtakilbiṣam
śarair vinihataṃ paśya vikīrṇam iva parvatam', null, 4008023),
('ramayana-4-8-24', 24, 'Kishkindha Kanda, Sarga 8, Verse 24', 'राघवस्य वचः श्रुत्वा सुग्रीवो वाहिनीपतिः।
प्रहर्षमतुलं लेभे साधु साध्विति चाब्रवीत्॥', 'rāghavasya vacaḥ śrutvā sugrīvo vāhinīpatiḥ
praharṣam atulaṃ lebhe sādhu sādhv iti cābravīt', null, 4008024),
('ramayana-4-8-25', 25, 'Kishkindha Kanda, Sarga 8, Verse 25', 'रामशोकाभिभूतोऽहं शोकार्तानां भवान्गतिः।
वयस्य इति कृत्वा हि त्वय्यहं परिदेवये॥', 'rāmaśokābhibhūto ''haṃ śokārtānāṃ bhavān gatiḥ
vayasya iti kṛtvā hi tvayy ahaṃ paridevaye', null, 4008025),
('ramayana-4-8-26', 26, 'Kishkindha Kanda, Sarga 8, Verse 26', 'त्वं हि पाणिप्रदानेन वयस्यो सोऽग्निसाक्षिकः।
कृतः प्राणैर्बहुमतः सत्येनापि शपाम्यहम्॥', 'tvaṃ hi pāṇipradānena vayasyo so ''gnisākṣikaḥ
kṛtaḥ prāṇair bahumataḥ satyenāpi śapāmy aham', null, 4008026),
('ramayana-4-8-27', 27, 'Kishkindha Kanda, Sarga 8, Verse 27', 'वयस्य इति कृत्वा च विस्रब्धं प्रवदाम्यहम्।
दुःखमन्तर्गतं यन्मे मनो दहति नित्यशः॥', 'vayasya iti kṛtvā ca visrabdhaṃ pravadāmy aham
duḥkham antargataṃ yan me mano dahati nityaśaḥ', null, 4008027),
('ramayana-4-8-28', 28, 'Kishkindha Kanda, Sarga 8, Verse 28', 'एतावदुक्त्वा वचनं बाष्पदूषितलोचनः।
बाष्पोपहतया वाचा नोच्चैः शक्नोति भाषितुम्॥', 'etāvad uktvā vacanaṃ bāṣpadūṣitalocanaḥ
bāṣpopahatayā vācā noccaiḥ śaknoti bhāṣitum', null, 4008028),
('ramayana-4-8-29', 29, 'Kishkindha Kanda, Sarga 8, Verse 29', 'बाष्पवेगं तु सहसा नदीवेगमिवागतम्।
धारयामास धैर्येण सुग्रीवो रामसंनिधौ॥', 'bāṣpavegaṃ tu sahasā nadīvegam ivāgatam
dhārayām āsa dhairyeṇa sugrīvo rāmasaṃnidhau', null, 4008029),
('ramayana-4-8-30', 30, 'Kishkindha Kanda, Sarga 8, Verse 30', 'संनिगृह्य तु तं बाष्पं प्रमृज्य नयने शुभे।
विनिःश्वस्य च तेजस्वी राघवं पुनरब्रवीत्॥', 'saṃnigṛhya tu taṃ bāṣpaṃ pramṛjya nayane śubhe
viniḥśvasya ca tejasvī rāghavaṃ punar abravīt', null, 4008030),
('ramayana-4-8-31', 31, 'Kishkindha Kanda, Sarga 8, Verse 31', 'पुराहं वलिना राम राज्यात्स्वादवरोपितः।
परुषाणि च संश्राव्य निर्धूतोऽस्मि बलीयसा॥', 'purāhaṃ valinā rāma rājyāt svād avaropitaḥ
paruṣāṇi ca saṃśrāvya nirdhūto ''smi balīyasā', null, 4008031),
('ramayana-4-8-32', 32, 'Kishkindha Kanda, Sarga 8, Verse 32', 'हृता भार्या च मे तेन प्राणेभ्योऽपि गरीयसी।
सुहृदश्च मदीया ये संयता बन्धनेषु ते॥', 'hṛtā bhāryā ca me tena prāṇebhyo ''pi garīyasī
suhṛdaś ca madīyā ye saṃyatā bandhaneṣu te', null, 4008032),
('ramayana-4-8-33', 33, 'Kishkindha Kanda, Sarga 8, Verse 33', 'यत्नवांश्च सुदुष्टात्मा मद्विनाशाय राघव।
बहुशस्तत्प्रयुक्ताश्च वानरा निहता मया॥', 'yatnavāṃś ca suduṣṭātmā mad vināśāya rāghava
bahuśas tat prayuktāś ca vānarā nihatā mayā', null, 4008033),
('ramayana-4-8-34', 34, 'Kishkindha Kanda, Sarga 8, Verse 34', 'शङ्कया त्वेतया चाहं दृष्ट्वा त्वामपि राघव।
नोपसर्पाम्यहं भीतो भये सर्वे हि बिभ्यति॥', 'śaṅkayā tv etayā cāhaṃ dṛṣṭvā tvām api rāghava
nopasarpāmy ahaṃ bhīto bhaye sarve hi bibhyati', null, 4008034),
('ramayana-4-8-35', 35, 'Kishkindha Kanda, Sarga 8, Verse 35', 'केवलं हि सहाया मे हनुमत्प्रमुखास्त्विमे।
अतोऽहं धारयाम्यद्य प्राणान्कृच्छ्र गतोऽपि सन्॥', 'kevalaṃ hi sahāyā me hanumat pramukhās tv ime
ato ''haṃ dhārayāmy adya prāṇān kṛcchra gato ''pi san', null, 4008035),
('ramayana-4-8-36', 36, 'Kishkindha Kanda, Sarga 8, Verse 36', 'एते हि कपयः स्निग्धा मां रक्षन्ति समन्ततः।
सह गच्छन्ति गन्तव्ये नित्यं तिष्ठन्ति च स्थिते॥', 'ete hi kapayaḥ snigdhā māṃ rakṣanti samantataḥ
saha gacchanti gantavye nityaṃ tiṣṭhanti ca sthite', null, 4008036),
('ramayana-4-8-37', 37, 'Kishkindha Kanda, Sarga 8, Verse 37', 'संक्षेपस्त्वेष मे राम किमुक्त्वा विस्तरं हि ते।
स मे ज्येष्ठो रिपुर्भ्राता वाली विश्रुतपौरुषः॥', 'saṃkṣepas tv eṣa me rāma kim uktvā vistaraṃ hi te
sa me jyeṣṭho ripur bhrātā vālī viśrutapauruṣaḥ', null, 4008037),
('ramayana-4-8-38', 38, 'Kishkindha Kanda, Sarga 8, Verse 38', 'तद्विनाशाद्धि मे दुःखं प्रनष्टं स्यादनन्तरम्।
सुखं मे जीवितं चैव तद्विनाशनिबन्धनम्॥', 'tadvināśād dhi me duḥkhaṃ pranaṣṭaṃ syād anantaram
sukhaṃ me jīvitaṃ caiva tadvināśanibandhanam', null, 4008038),
('ramayana-4-8-39', 39, 'Kishkindha Kanda, Sarga 8, Verse 39', 'एष मे राम शोकान्तः शोकार्तेन निवेदितः।
दुःखितोऽदुःखितो वापि सख्युर्नित्यं सखा गतिः॥', 'eṣa me rāma śokāntaḥ śokārtena niveditaḥ
duḥkhito ''duḥkhito vāpi sakhyur nityaṃ sakhā gatiḥ', null, 4008039),
('ramayana-4-8-40', 40, 'Kishkindha Kanda, Sarga 8, Verse 40', 'श्रुत्वैतच्च वचो रामः सुग्रीवमिदमब्रवीत्।
किंनिमित्तमभूद्वैरं श्रोतुमिच्छामि तत्त्वतः॥', 'śrutvaitac ca vaco rāmaḥ sugrīvam idam abravīt
kiṃnimittam abhūd vairaṃ śrotum icchāmi tattvataḥ', null, 4008040),
('ramayana-4-8-41', 41, 'Kishkindha Kanda, Sarga 8, Verse 41', 'सुखं हि कारणं श्रुत्वा वैरस्य तव वानर।
आनन्तर्यं विधास्यामि संप्रधार्य बलाबलम्॥', 'sukhaṃ hi kāraṇaṃ śrutvā vairasya tava vānara
ānantaryaṃ vidhāsyāmi saṃpradhārya balābalam', null, 4008041),
('ramayana-4-8-42', 42, 'Kishkindha Kanda, Sarga 8, Verse 42', 'बलवान्हि ममामर्षः श्रुत्वा त्वामवमानितम्।
वर्धते हृदयोत्कम्पी प्रावृड्वेग इवाम्भसः॥', 'balavān hi mamāmarṣaḥ śrutvā tvām avamānitam
vardhate hṛdayotkampī prāvṛḍvega ivāmbhasaḥ', null, 4008042),
('ramayana-4-8-43', 43, 'Kishkindha Kanda, Sarga 8, Verse 43', 'हृष्टः कथय विस्रब्धो यावदारोप्यते धनुः।
सृष्टश्च हि मया बाणो निरस्तश्च रिपुस्तव॥', 'hṛṣṭaḥ kathaya visrabdho yāvad āropyate dhanuḥ
sṛṣṭaś ca hi mayā bāṇo nirastaś ca ripus tava', null, 4008043),
('ramayana-4-8-44', 44, 'Kishkindha Kanda, Sarga 8, Verse 44', 'एवमुक्तस्तु सुग्रीवः काकुत्स्थेन महात्मना।
प्रहर्षमतुलं लेभे चतुर्भिः सह वानरैः॥', 'evam uktas tu sugrīvaḥ kākutsthena mahātmanā
praharṣam atulaṃ lebhe caturbhiḥ saha vānaraiḥ', null, 4008044),
('ramayana-4-8-45', 45, 'Kishkindha Kanda, Sarga 8, Verse 45', 'ततः प्रहृष्टवदनः सुग्रीवो लक्ष्मणाग्रजे।
वैरस्य कारणं तत्त्वमाख्यातुमुपचक्रमे॥', 'tataḥ prahṛṣṭavadanaḥ sugrīvo lakṣmaṇāgraje
vairasya kāraṇaṃ tattvam ākhyātum upacakrame', null, 4008045)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 9 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-9-1', 1, 'Kishkindha Kanda, Sarga 9, Verse 1', 'वाली नाम मम भ्राता ज्येष्ठः शत्रुनिषूदनः।
पितुर्बहुमतो नित्यं मम चापि तथा पुरा॥', 'vālī nāma mama bhrātā jyeṣṭhaḥ śatruniṣūdanaḥ
pitur bahumato nityaṃ mama cāpi tathā purā', null, 4009001),
('ramayana-4-9-2', 2, 'Kishkindha Kanda, Sarga 9, Verse 2', 'पितर्युपरतेऽस्माकं ज्येष्ठोऽयमिति मन्त्रिभिः।
कपीनामीश्वरो राज्ये कृतः परमसंमतः॥', 'pitary uparate ''smākaṃ jyeṣṭho ''yam iti mantribhiḥ
kapīnām īśvaro rājye kṛtaḥ paramasaṃmataḥ', null, 4009002),
('ramayana-4-9-3', 3, 'Kishkindha Kanda, Sarga 9, Verse 3', 'राज्यं प्रशासतस्तस्य पितृपैतामहं महत्।
अहं सर्वेषु कालेषु प्रणतः प्रेष्यवत्स्थितः॥', 'rājyaṃ praśāsatas tasya pitṛpaitāmahaṃ mahat
ahaṃ sarveṣu kāleṣu praṇataḥ preṣyavat sthitaḥ', null, 4009003),
('ramayana-4-9-4', 4, 'Kishkindha Kanda, Sarga 9, Verse 4', 'मायावी नाम तेजस्वी पूर्वजो दुन्दुभेः सुतः।
तेन तस्य महद्वैरं स्त्रीकृतं विश्रुतं पुरा॥', 'māyāvī nāma tejasvī pūrvajo dundubheḥ sutaḥ
tena tasya mahad vairaṃ strīkṛtaṃ viśrutaṃ purā', null, 4009004),
('ramayana-4-9-5', 5, 'Kishkindha Kanda, Sarga 9, Verse 5', 'स तु सुप्ते जने रात्रौ किष्किन्धाद्वारमागतः।
नर्दति स्म सुसंरब्धो वालिनं चाह्वयद्रणे॥', 'sa tu supte jane rātrau kiṣkindhād vāram āgataḥ
nardati sma susaṃrabdho vālinaṃ cāhvayad raṇe', null, 4009005),
('ramayana-4-9-6', 6, 'Kishkindha Kanda, Sarga 9, Verse 6', 'प्रसुप्तस्तु मम भ्राता नर्दितं भैरवस्वनम्।
श्रुत्वा न ममृषे वाली निष्पपात जवात्तदा॥', 'prasuptas tu mama bhrātā narditaṃ bhairavasvanam
śrutvā na mamṛṣe vālī niṣpapāta javāt tadā', null, 4009006),
('ramayana-4-9-7', 7, 'Kishkindha Kanda, Sarga 9, Verse 7', 'स तु वै निःसृतः क्रोधात्तं हन्तुमसुरोत्तमम्।
वार्यमाणस्ततः स्त्रीभिर्मया च प्रणतात्मना॥', 'sa tu vai niḥsṛtaḥ krodhāt taṃ hantum asurottamam
vāryamāṇas tataḥ strībhir mayā ca praṇatātmanā', null, 4009007),
('ramayana-4-9-8', 8, 'Kishkindha Kanda, Sarga 9, Verse 8', 'स तु निर्धूय सर्वान्नो निर्जगाम महाबलः।
ततोऽहमपि सौहार्दान्निःसृतो वालिना सह॥', 'sa tu nirdhūya sarvānno nirjagāma mahābalaḥ
tato ''ham api sauhārdān niḥsṛto vālinā saha', null, 4009008),
('ramayana-4-9-9', 9, 'Kishkindha Kanda, Sarga 9, Verse 9', 'स तु मे भ्रातरं दृष्ट्वा मां च दूरादवस्थितम्।
असुरो जातसंत्रासः प्रदुद्राव तदा भृशम्॥', 'sa tu me bhrātaraṃ dṛṣṭvā māṃ ca dūrād avasthitam
asuro jātasaṃtrāsaḥ pradudrāva tadā bhṛśam', null, 4009009),
('ramayana-4-9-10', 10, 'Kishkindha Kanda, Sarga 9, Verse 10', 'तस्मिन्द्रवति संत्रस्ते ह्यावां द्रुततरं गतौ।
प्रकाशोऽपि कृतो मार्गश्चन्द्रेणोद्गच्छता तदा॥', 'tasmin dravati saṃtraste hy āvāṃ drutataraṃ gatau
prakāśo ''pi kṛto mārgaś candreṇodgacchatā tadā', null, 4009010),
('ramayana-4-9-11', 11, 'Kishkindha Kanda, Sarga 9, Verse 11', 'स तृणैरावृतं दुर्गं धरण्या विवरं महत्।
प्रविवेशासुरो वेगादावामासाद्य विष्ठितौ॥', 'sa tṛṇair āvṛtaṃ durgaṃ dharaṇyā vivaraṃ mahat
praviveśāsuro vegād āvām āsādya viṣṭhitau', null, 4009011),
('ramayana-4-9-12', 12, 'Kishkindha Kanda, Sarga 9, Verse 12', 'तं प्रविष्टं रिपुं दृष्ट्वा बिलं रोषवशं गतः।
मामुवाच तदा वाली वचनं क्षुभितेन्द्रियः॥', 'taṃ praviṣṭaṃ ripuṃ dṛṣṭvā bilaṃ roṣavaśaṃ gataḥ
mām uvāca tadā vālī vacanaṃ kṣubhitendriyaḥ', null, 4009012),
('ramayana-4-9-13', 13, 'Kishkindha Kanda, Sarga 9, Verse 13', 'इह त्वं तिष्ठ सुग्रीव बिलद्वारि समाहितः।
यावदत्र प्रविश्याहं निहन्मि समरे रिपुम्॥', 'iha tvaṃ tiṣṭha sugrīva biladvāri samāhitaḥ
yāvad atra praviśyāhaṃ nihanmi samare ripum', null, 4009013),
('ramayana-4-9-14', 14, 'Kishkindha Kanda, Sarga 9, Verse 14', 'मया त्वेतद्वचः श्रुत्वा याचितः स परंतप।
शापयित्वा च मां पद्भ्यां प्रविवेश बिलं तदा॥', 'mayā tv etad vacaḥ śrutvā yācitaḥ sa paraṃtapa
śāpayitvā ca māṃ padbhyāṃ praviveśa bilaṃ tadā', null, 4009014),
('ramayana-4-9-15', 15, 'Kishkindha Kanda, Sarga 9, Verse 15', 'तस्य प्रविष्टस्य बिलं साग्रः संवत्सरो गतः।
स्थितस्य च मम द्वारि स कालो व्यत्यवर्तत॥', 'tasya praviṣṭasya bilaṃ sāgraḥ saṃvatsaro gataḥ
sthitasya ca mama dvāri sa kālo vyatyavartata', null, 4009015),
('ramayana-4-9-16', 16, 'Kishkindha Kanda, Sarga 9, Verse 16', 'अहं तु नष्टं तं ज्ञात्वा स्नेहादागतसंभ्रमः।
भ्रातरं न हि पश्यामि पापशङ्कि च मे मनः॥', 'ahaṃ tu naṣṭaṃ taṃ jñātvā snehād āgatasaṃbhramaḥ
bhrātaraṃ na hi paśyāmi pāpaśaṅki ca me manaḥ', null, 4009016),
('ramayana-4-9-17', 17, 'Kishkindha Kanda, Sarga 9, Verse 17', 'अथ दीर्घस्य कालस्य बिलात्तस्माद्विनिःसृतम्।
सफेनं रुधिरं रक्तमहं दृष्ट्वा सुदुःखितः॥', 'atha dīrghasya kālasya bilāt tasmād viniḥsṛtam
saphenaṃ rudhiraṃ raktam ahaṃ dṛṣṭvā suduḥkhitaḥ', null, 4009017),
('ramayana-4-9-18', 18, 'Kishkindha Kanda, Sarga 9, Verse 18', 'नर्दतामसुराणां च ध्वनिर्मे श्रोत्रमागतः।
निरस्तस्य च संग्रामे क्रोशतो निःस्वनो गुरोः॥', 'nardatām asurāṇāṃ ca dhvanir me śrotram āgataḥ
nirastasya ca saṃgrāme krośato niḥsvano guroḥ', null, 4009018),
('ramayana-4-9-19', 19, 'Kishkindha Kanda, Sarga 9, Verse 19', 'अहं त्ववगतो बुद्ध्या चिह्नैस्तैर्भ्रातरं हतम्।
पिधाय च बिलद्वारं शिलया गिरिमात्रया।
शोकार्तश्चोदकं कृत्वा किष्किन्धामागतः सखे॥', 'ahaṃ tv avagato buddhyā cihnais tair bhrātaraṃ hatam
pidhāya ca biladvāraṃ śilayā girimātrayā
śokārtaś codakaṃ kṛtvā kiṣkindhām āgataḥ sakhe', null, 4009019),
('ramayana-4-9-20', 20, 'Kishkindha Kanda, Sarga 9, Verse 20', 'गूहमानस्य मे तत्त्वं यत्नतो मन्त्रिभिः श्रुतम्।
ततोऽहं तैः समागम्य समेतैरभिषेचितः॥', 'gūhamānasya me tattvaṃ yatnato mantribhiḥ śrutam
tato ''haṃ taiḥ samāgamya sametair abhiṣecitaḥ', null, 4009020),
('ramayana-4-9-21', 21, 'Kishkindha Kanda, Sarga 9, Verse 21', 'राज्यं प्रशासतस्तस्य न्यायतो मम राघव।
आजगाम रिपुं हत्वा वाली तमसुरोत्तमम्॥', 'rājyaṃ praśāsatas tasya nyāyato mama rāghava
ājagāma ripuṃ hatvā vālī tam asurottamam', null, 4009021),
('ramayana-4-9-22', 22, 'Kishkindha Kanda, Sarga 9, Verse 22', 'अभिषिक्तं तु मां दृष्ट्वा क्रोधात्संरक्तलोचनः।
मदीयान्मन्त्रिणो बद्ध्वा परुषं वाक्यमब्रवीत्॥', 'abhiṣiktaṃ tu māṃ dṛṣṭvā krodhāt saṃraktalocanaḥ
madīyān mantriṇo baddhvā paruṣaṃ vākyam abravīt', null, 4009022),
('ramayana-4-9-23', 23, 'Kishkindha Kanda, Sarga 9, Verse 23', 'निग्रहेऽपि समर्थस्य तं पापं प्रति राघव।
न प्रावर्तत मे बुद्धिर्भ्रातृगौरवयन्त्रिता॥', 'nigrahe ''pi samarthasya taṃ pāpaṃ prati rāghava
na prāvartata me buddhir bhrātṛgauravayantritā', null, 4009023),
('ramayana-4-9-24', 24, 'Kishkindha Kanda, Sarga 9, Verse 24', 'मानयंस्तं महात्मानं यथावच्चाभ्यवादयम्।
उक्ताश्च नाशिषस्तेन संतुष्टेनान्तरात्मना॥', 'mānayaṃs taṃ mahātmānaṃ yathāvac cābhyavādayam
uktāś ca nāśiṣas tena saṃtuṣṭenāntarātmanā', null, 4009024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 10 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-10-1', 1, 'Kishkindha Kanda, Sarga 10, Verse 1', 'ततः क्रोधसमाविष्टं संरब्धं तमुपागतम्।
अहं प्रसादयां चक्रे भ्रातरं प्रियकाम्यया॥', 'tataḥ krodhasamāviṣṭaṃ saṃrabdhaṃ tam upāgatam
ahaṃ prasādayāṃ cakre bhrātaraṃ priyakāmyayā', null, 4010001),
('ramayana-4-10-2', 2, 'Kishkindha Kanda, Sarga 10, Verse 2', 'दिष्ट्यासि कुशली प्राप्तो निहतश्च त्वया रिपुः।
अनाथस्य हि मे नाथस्त्वमेकोऽनाथनन्दनः॥', 'diṣṭyāsi kuśalī prāpto nihataś ca tvayā ripuḥ
anāthasya hi me nāthas tvam eko ''nāthanandanaḥ', null, 4010002),
('ramayana-4-10-3', 3, 'Kishkindha Kanda, Sarga 10, Verse 3', 'इदं बहुशलाकं ते पूर्णचन्द्रमिवोदितम्।
छत्रं सवालव्यजनं प्रतीच्छस्व मयोद्यतम्॥', 'idaṃ bahuśalākaṃ te pūrṇacandram ivoditam
chatraṃ savālavyajanaṃ pratīcchasva mayodyatam', null, 4010003),
('ramayana-4-10-4', 4, 'Kishkindha Kanda, Sarga 10, Verse 4', 'त्वमेव राजा मानार्हः सदा चाहं यथापुरा।
न्यासभूतमिदं राज्यं तव निर्यातयाम्यहम्॥', 'tvam eva rājā mānārhaḥ sadā cāhaṃ yathāpurā
nyāsabhūtam idaṃ rājyaṃ tava niryātayāmy aham', null, 4010004),
('ramayana-4-10-5', 5, 'Kishkindha Kanda, Sarga 10, Verse 5', 'मा च रोषं कृथाः सौम्य मयि शत्रुनिबर्हण।
याचे त्वां शिरसा राजन्मया बद्धोऽयमञ्जलिः॥', 'mā ca roṣaṃ kṛthāḥ saumya mayi śatrunibarhaṇa
yāce tvāṃ śirasā rājan mayā baddho ''yam añjaliḥ', null, 4010005),
('ramayana-4-10-6', 6, 'Kishkindha Kanda, Sarga 10, Verse 6', 'बलादस्मि समागम्य मन्त्रिभिः पुरवासिभिः।
राजभावे नियुक्तोऽहं शून्यदेशजिगीषया॥', 'balād asmi samāgamya mantribhiḥ puravāsibhiḥ
rājabhāve niyukto ''haṃ śūnyadeśajigīṣayā', null, 4010006),
('ramayana-4-10-7', 7, 'Kishkindha Kanda, Sarga 10, Verse 7', 'स्निग्धमेवं ब्रुवाणं मां स तु निर्भर्त्स्य वानरः।
धिक्त्वामिति च मामुक्त्वा बहु तत्तदुवाच ह॥', 'snigdham evaṃ bruvāṇaṃ māṃ sa tu nirbhartsya vānaraḥ
dhik tvām iti ca mām uktvā bahu tat tad uvāca ha', null, 4010007),
('ramayana-4-10-8', 8, 'Kishkindha Kanda, Sarga 10, Verse 8', 'प्रकृतीश्च समानीय मन्त्रिणश्चैव संमतान्।
मामाह सुहृदां मध्ये वाक्यं परमगर्हितम्॥', 'prakṛtīś ca samānīya mantriṇaś caiva saṃmatān
mām āha suhṛdāṃ madhye vākyaṃ paramagarhitam', null, 4010008),
('ramayana-4-10-9', 9, 'Kishkindha Kanda, Sarga 10, Verse 9', 'विदितं वो यथा रात्रौ मायावी स महासुरः।
मां समाह्वयत क्रूरो युद्धाकाङ्क्षी सुदुर्मतिः॥', 'viditaṃ vo yathā rātrau māyāvī sa mahāsuraḥ
māṃ samāhvayata krūro yuddhākāṅkṣī sudurmatiḥ', null, 4010009),
('ramayana-4-10-10', 10, 'Kishkindha Kanda, Sarga 10, Verse 10', 'तस्य तद्गर्जितं श्रुत्वा निःसृतोऽहं नृपालयात्।
अनुयातश्च मां तूर्णमयं भ्राता सुदारुणः॥', 'tasya tad garjitaṃ śrutvā niḥsṛto ''haṃ nṛpālayāt
anuyātaś ca māṃ tūrṇam ayaṃ bhrātā sudāruṇaḥ', null, 4010010),
('ramayana-4-10-11', 11, 'Kishkindha Kanda, Sarga 10, Verse 11', 'स तु दृष्ट्वैव मां रात्रौ सद्वितीयं महाबलः।
प्राद्रवद्भयसंत्रस्तो वीक्ष्यावां तमनुद्रुतौ।
अनुद्रुतस्तु वेगेन प्रविवेश महाबिलम्॥', 'sa tu dṛṣṭvaiva māṃ rātrau sadvitīyaṃ mahābalaḥ
prādravad bhayasaṃtrasto vīkṣyāvāṃ tam anudrutau
anudrutas tu vegena praviveśa mahābilam', null, 4010011),
('ramayana-4-10-12', 12, 'Kishkindha Kanda, Sarga 10, Verse 12', 'तं प्रविष्टं विदित्वा तु सुघोरं सुमहद्बिलम्।
अयमुक्तोऽथ मे भ्राता मया तु क्रूरदर्शनः॥', 'taṃ praviṣṭaṃ viditvā tu sughoraṃ sumahad bilam
ayam ukto ''tha me bhrātā mayā tu krūradarśanaḥ', null, 4010012),
('ramayana-4-10-13', 13, 'Kishkindha Kanda, Sarga 10, Verse 13', 'अहत्वा नास्ति मे शक्तिः प्रतिगन्तुमितः पुरीम्।
बिलद्वारि प्रतीक्ष त्वं यावदेनं निहन्म्यहम्॥', 'ahatvā nāsti me śaktiḥ pratigantum itaḥ purīm
biladvāri pratīkṣa tvaṃ yāvad enaṃ nihanmy aham', null, 4010013),
('ramayana-4-10-14', 14, 'Kishkindha Kanda, Sarga 10, Verse 14', 'स्थितोऽयमिति मत्वा तु प्रविष्टोऽहं दुरासदम्।
तं च मे मार्गमाणस्य गतः संवत्सरस्तदा॥', 'sthito ''yam iti matvā tu praviṣṭo ''haṃ durāsadam
taṃ ca me mārgamāṇasya gataḥ saṃvatsaras tadā', null, 4010014),
('ramayana-4-10-15', 15, 'Kishkindha Kanda, Sarga 10, Verse 15', 'स तु दृष्टो मया शत्रुरनिर्वेदाद्भयावहः।
निहतश्च मया तत्र सोऽसुरो बन्धुभिः सह॥', 'sa tu dṛṣṭo mayā śatrur anirvedād bhayāvahaḥ
nihataś ca mayā tatra so ''suro bandhubhiḥ saha', null, 4010015),
('ramayana-4-10-16', 16, 'Kishkindha Kanda, Sarga 10, Verse 16', 'तस्यास्यात्तु प्रवृत्तेन रुधिरौघेण तद्बिलम्।
पूर्णमासीद्दुराक्रामं स्तनतस्तस्य भूतले॥', 'tasyāsyāt tu pravṛttena rudhiraugheṇa tad bilam
pūrṇam āsīd durākrāmaṃ stanatas tasya bhūtale', null, 4010016),
('ramayana-4-10-17', 17, 'Kishkindha Kanda, Sarga 10, Verse 17', 'सूदयित्वा तु तं शत्रुं विक्रान्तं दुन्दुभेः सुतम्।
निष्क्रामन्नेव पश्यामि बिलस्य पिहितं मुखम्॥', 'sūdayitvā tu taṃ śatruṃ vikrāntaṃ dundubheḥ sutam
niṣkrāmann eva paśyāmi bilasya pihitaṃ mukham', null, 4010017),
('ramayana-4-10-18', 18, 'Kishkindha Kanda, Sarga 10, Verse 18', 'विक्रोशमानस्य तु मे सुग्रीवेति पुनः पुनः।
यदा प्रतिवचो नास्ति ततोऽहं भृशदुःखितः॥', 'vikrośamānasya tu me sugrīveti punaḥ punaḥ
yadā prativaco nāsti tato ''haṃ bhṛśaduḥkhitaḥ', null, 4010018),
('ramayana-4-10-19', 19, 'Kishkindha Kanda, Sarga 10, Verse 19', 'पादप्रहारैस्तु मया बहुशस्तद्विदारितम्।
ततोऽहं तेन निष्क्रम्य यथा पुनरुपागतः॥', 'pādaprahārais tu mayā bahuśas tad vidāritam
tato ''haṃ tena niṣkramya yathā punar upāgataḥ', null, 4010019),
('ramayana-4-10-20', 20, 'Kishkindha Kanda, Sarga 10, Verse 20', 'तत्रानेनास्मि संरुद्धो राज्यं मार्गयतात्मनः।
सुग्रीवेण नृशंसेन विस्मृत्य भ्रातृसौहृदम्॥', 'tatrānenāsmi saṃruddho rājyaṃ mārgayatātmanaḥ
sugrīveṇa nṛśaṃsena vismṛtya bhrātṛsauhṛdam', null, 4010020),
('ramayana-4-10-21', 21, 'Kishkindha Kanda, Sarga 10, Verse 21', 'एवमुक्त्वा तु मां तत्र वस्त्रेणैकेन वानरः।
तदा निर्वासयामास वाली विगतसाध्वसः॥', 'evam uktvā tu māṃ tatra vastreṇaikena vānaraḥ
tadā nirvāsayām āsa vālī vigatasādhvasaḥ', null, 4010021),
('ramayana-4-10-22', 22, 'Kishkindha Kanda, Sarga 10, Verse 22', 'तेनाहमपविद्धश्च हृतदारश्च राघव।
तद्भयाच्च महीकृत्स्ना क्रान्तेयं सवनार्णवा॥', 'tenāham apaviddhaś ca hṛtadāraś ca rāghava
tadbhayāc ca mahīkṛtsnā krānteyaṃ savanārṇavā', null, 4010022),
('ramayana-4-10-23', 23, 'Kishkindha Kanda, Sarga 10, Verse 23', 'ऋश्यमूकं गिरिवरं भार्याहरणदुःखितः।
प्रविष्टोऽस्मि दुराधर्षं वालिनः कारणान्तरे॥', 'ṛśyamūkaṃ girivaraṃ bhāryāharaṇaduḥkhitaḥ
praviṣṭo ''smi durādharṣaṃ vālinaḥ kāraṇāntare', null, 4010023),
('ramayana-4-10-24', 24, 'Kishkindha Kanda, Sarga 10, Verse 24', 'एतत्ते सर्वमाख्यातं वैरानुकथनं महत्।
अनागसा मया प्राप्तं व्यसनं पश्य राघव॥', 'etat te sarvam ākhyātaṃ vairānukathanaṃ mahat
anāgasā mayā prāptaṃ vyasanaṃ paśya rāghava', null, 4010024),
('ramayana-4-10-25', 25, 'Kishkindha Kanda, Sarga 10, Verse 25', 'वालिनस्तु भयार्तस्य सर्वलोकाभयंकर।
कर्तुमर्हसि मे वीर प्रसादं तस्य निग्रहात्॥', 'vālinas tu bhayārtasya sarvalokābhayaṃkara
kartum arhasi me vīra prasādaṃ tasya nigrahāt', null, 4010025),
('ramayana-4-10-26', 26, 'Kishkindha Kanda, Sarga 10, Verse 26', 'एवमुक्तः स तेजस्वी धर्मज्ञो धर्मसंहितम्।
वचनं वक्तुमारेभे सुग्रीवं प्रहसन्निव॥', 'evam uktaḥ sa tejasvī dharmajño dharmasaṃhitam
vacanaṃ vaktum ārebhe sugrīvaṃ prahasann iva', null, 4010026),
('ramayana-4-10-27', 27, 'Kishkindha Kanda, Sarga 10, Verse 27', 'अमोघाः सूर्यसंकाशा ममेमे निशिताः शराः।
तस्मिन्वालिनि दुर्वृत्ते पतिष्यन्ति रुषान्विताः॥', 'amoghāḥ sūryasaṃkāśā mameme niśitāḥ śarāḥ
tasmin vālini durvṛtte patiṣyanti ruṣānvitāḥ', null, 4010027),
('ramayana-4-10-28', 28, 'Kishkindha Kanda, Sarga 10, Verse 28', 'यावत्तं न हि पश्येयं तव भार्यापहारिणम्।
तावत्स जीवेत्पापात्मा वाली चारित्रदूषकः॥', 'yāvat taṃ na hi paśyeyaṃ tava bhāryāpahāriṇam
tāvat sa jīvet pāpātmā vālī cāritradūṣakaḥ', null, 4010028),
('ramayana-4-10-29', 29, 'Kishkindha Kanda, Sarga 10, Verse 29', 'आत्मानुमानात्पश्यामि मग्नं त्वां शोकसागरे।
त्वामहं तारयिष्यामि कामं प्राप्स्यसि पुष्कलम्॥', 'ātmānumānāt paśyāmi magnaṃ tvāṃ śokasāgare
tvām ahaṃ tārayiṣyāmi kāmaṃ prāpsyasi puṣkalam', null, 4010029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 11 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-11-1', 1, 'Kishkindha Kanda, Sarga 11, Verse 1', 'रामस्य वचनं श्रुत्वा हर्षपौरुषवर्धनम्।
सुग्रीवः पूजयां चक्रे राघवं प्रशशंस च॥', 'rāmasya vacanaṃ śrutvā harṣapauruṣavardhanam
sugrīvaḥ pūjayāṃ cakre rāghavaṃ praśaśaṃsa ca', null, 4011001),
('ramayana-4-11-2', 2, 'Kishkindha Kanda, Sarga 11, Verse 2', 'असंशयं प्रज्वलितैस्तीक्ष्णैर्मर्मातिगैः शरैः।
त्वं दहेः कुपितो लोकान्युगान्त इव भास्करः॥', 'asaṃśayaṃ prajvalitais tīkṣṇair marmātigaiḥ śaraiḥ
tvaṃ daheḥ kupito lokān yugānta iva bhāskaraḥ', null, 4011002),
('ramayana-4-11-3', 3, 'Kishkindha Kanda, Sarga 11, Verse 3', 'वालिनः पौरुषं यत्तद्यच्च वीर्यं धृतिश्च या।
तन्ममैकमनाः श्रुत्वा विधत्स्व यदनन्तरम्॥', 'vālinaḥ pauruṣaṃ yat tad yac ca vīryaṃ dhṛtiś ca yā
tan mamaikamanāḥ śrutvā vidhatsva yadanantaram', null, 4011003),
('ramayana-4-11-4', 4, 'Kishkindha Kanda, Sarga 11, Verse 4', 'समुद्रात्पश्चिमात्पूर्वं दक्षिणादपि चोत्तरम्।
क्रामत्यनुदिते सूर्ये वाली व्यपगतक्लमः॥', 'samudrāt paścimāt pūrvaṃ dakṣiṇād api cottaram
krāmaty anudite sūrye vālī vyapagataklamaḥ', null, 4011004),
('ramayana-4-11-5', 5, 'Kishkindha Kanda, Sarga 11, Verse 5', 'अग्राण्यारुह्य शैलानां शिखराणि महान्त्यपि।
ऊर्ध्वमुत्क्षिप्य तरसा प्रतिगृह्णाति वीर्यवान्॥', 'agrāṇy āruhya śailānāṃ śikharāṇi mahānty api
ūrdhvam utkṣipya tarasā pratigṛhṇāti vīryavān', null, 4011005),
('ramayana-4-11-6', 6, 'Kishkindha Kanda, Sarga 11, Verse 6', 'बहवः सारवन्तश्च वनेषु विविधा द्रुमाः।
वालिना तरसा भग्ना बलं प्रथयतात्मनः॥', 'bahavaḥ sāravantaś ca vaneṣu vividhā drumāḥ
vālinā tarasā bhagnā balaṃ prathayatātmanaḥ', null, 4011006),
('ramayana-4-11-7', 7, 'Kishkindha Kanda, Sarga 11, Verse 7', 'महिषो दुन्दुभिर्नाम कैलासशिखरप्रभः।
बलं नागसहस्रस्य धारयामास वीर्यवान्॥', 'mahiṣo dundubhir nāma kailāsaśikharaprabhaḥ
balaṃ nāgasahasrasya dhārayām āsa vīryavān', null, 4011007),
('ramayana-4-11-8', 8, 'Kishkindha Kanda, Sarga 11, Verse 8', 'वीर्योत्सेकेन दुष्टात्मा वरदानाच्च मोहितः।
जगाम स महाकायः समुद्रं सरितां पतिम्॥', 'vīryotsekena duṣṭātmā varadānāc ca mohitaḥ
jagāma sa mahākāyaḥ samudraṃ saritāṃ patim', null, 4011008),
('ramayana-4-11-9', 9, 'Kishkindha Kanda, Sarga 11, Verse 9', 'ऊर्मिमन्तमतिक्रम्य सागरं रत्नसंचयम्।
मम युद्धं प्रयच्छेति तमुवाच महार्णवम्॥', 'ūrmimantam atikramya sāgaraṃ ratnasaṃcayam
mama yuddhaṃ prayaccheti tam uvāca mahārṇavam', null, 4011009),
('ramayana-4-11-10', 10, 'Kishkindha Kanda, Sarga 11, Verse 10', 'ततः समुद्रो धर्मात्मा समुत्थाय महाबलः।
अब्रवीद्वचनं राजन्नसुरं कालचोदितम्॥', 'tataḥ samudro dharmātmā samutthāya mahābalaḥ
abravīd vacanaṃ rājann asuraṃ kālacoditam', null, 4011010),
('ramayana-4-11-11', 11, 'Kishkindha Kanda, Sarga 11, Verse 11', 'समर्थो नास्मि ते दातुं युद्धं युद्धविशारद।
श्रूयतामभिधास्यामि यस्ते युद्धं प्रदास्यति॥', 'samartho nāsmi te dātuṃ yuddhaṃ yuddhaviśārada
śrūyatām abhidhāsyāmi yas te yuddhaṃ pradāsyati', null, 4011011),
('ramayana-4-11-12', 12, 'Kishkindha Kanda, Sarga 11, Verse 12', 'शैलराजो महारण्ये तपस्विशरणं परम्।
शंकरश्वशुरो नाम्ना हिमवानिति विश्रुतः॥', 'śailarājo mahāraṇye tapasviśaraṇaṃ param
śaṃkaraśvaśuro nāmnā himavān iti viśrutaḥ', null, 4011012),
('ramayana-4-11-13', 13, 'Kishkindha Kanda, Sarga 11, Verse 13', 'गुहा प्रस्रवणोपेतो बहुकन्दरनिर्झरः।
स समर्थस्तव प्रीतिमतुलां कर्तुमाहवे॥', 'guhā prasravaṇopeto bahukandaranirjharaḥ
sa samarthas tava prītim atulāṃ kartum āhave', null, 4011013),
('ramayana-4-11-14', 14, 'Kishkindha Kanda, Sarga 11, Verse 14', 'तं भीतमिति विज्ञाय समुद्रमसुरोत्तमः।
हिमवद्वनमागच्छच्छरश्चापादिव च्युतः॥', 'taṃ bhītam iti vijñāya samudram asurottamaḥ
himavadvanam āgacchac charaś cāpād iva cyutaḥ', null, 4011014),
('ramayana-4-11-15', 15, 'Kishkindha Kanda, Sarga 11, Verse 15', 'ततस्तस्य गिरेः श्वेता गजेन्द्रविपुलाः शिलाः।
चिक्षेप बहुधा भूमौ दुन्दुभिर्विननाद च॥', 'tatas tasya gireḥ śvetā gajendravipulāḥ śilāḥ
cikṣepa bahudhā bhūmau dundubhir vinanāda ca', null, 4011015),
('ramayana-4-11-16', 16, 'Kishkindha Kanda, Sarga 11, Verse 16', 'ततः श्वेताम्बुदाकारः सौम्यः प्रीतिकराकृतिः।
हिमवानब्रवीद्वाक्यं स्व एव शिखरे स्थितः॥', 'tataḥ śvetāmbudākāraḥ saumyaḥ prītikarākṛtiḥ
himavān abravīd vākyaṃ sva eva śikhare sthitaḥ', null, 4011016),
('ramayana-4-11-17', 17, 'Kishkindha Kanda, Sarga 11, Verse 17', 'क्लेष्टुमर्हसि मां न त्वं दुन्दुभे धर्मवत्सल।
रणकर्मस्वकुशलस्तपस्विशरणं ह्यहम्॥', 'kleṣṭum arhasi māṃ na tvaṃ dundubhe dharmavatsala
raṇakarmasv akuśalas tapasviśaraṇaṃ hy aham', null, 4011017),
('ramayana-4-11-18', 18, 'Kishkindha Kanda, Sarga 11, Verse 18', 'तस्य तद्वचनं श्रुत्वा गिरिराजस्य धीमतः।
उवाच दुन्दुभिर्वाक्यं क्रोधात्संरक्तलोचनः॥', 'tasya tad vacanaṃ śrutvā girirājasya dhīmataḥ
uvāca dundubhir vākyaṃ krodhāt saṃraktalocanaḥ', null, 4011018),
('ramayana-4-11-19', 19, 'Kishkindha Kanda, Sarga 11, Verse 19', 'यदि युद्धेऽसमर्थस्त्वं मद्भयाद्वा निरुद्यमः।
तमाचक्ष्व प्रदद्यान्मे योऽद्य युद्धं युयुत्सतः॥', 'yadi yuddhe ''samarthas tvaṃ madbhayād vā nirudyamaḥ
tam ācakṣva pradadyān me yo ''dya yuddhaṃ yuyutsataḥ', null, 4011019),
('ramayana-4-11-20', 20, 'Kishkindha Kanda, Sarga 11, Verse 20', 'हिमवानब्रवीद्वाक्यं श्रुत्वा वाक्यविशारदः।
अनुक्तपूर्वं धर्मात्मा क्रोधात्तमसुरोत्तमम्॥', 'himavān abravīd vākyaṃ śrutvā vākyaviśāradaḥ
anuktapūrvaṃ dharmātmā krodhāt tam asurottamam', null, 4011020),
('ramayana-4-11-21', 21, 'Kishkindha Kanda, Sarga 11, Verse 21', 'वाली नाम महाप्राज्ञः शक्रतुल्यपराक्रमः।
अध्यास्ते वानरः श्रीमान्किष्किन्धामतुलप्रभाम्॥', 'vālī nāma mahāprājñaḥ śakratulyaparākramaḥ
adhyāste vānaraḥ śrīmān kiṣkindhām atulaprabhām', null, 4011021),
('ramayana-4-11-22', 22, 'Kishkindha Kanda, Sarga 11, Verse 22', 'स समर्थो महाप्राज्ञस्तव युद्धविशारदः।
द्वन्द्वयुद्धं महद्दातुं नमुचेरिव वासवः॥', 'sa samartho mahāprājñas tava yuddhaviśāradaḥ
dvandvayuddhaṃ mahad dātuṃ namucer iva vāsavaḥ', null, 4011022),
('ramayana-4-11-23', 23, 'Kishkindha Kanda, Sarga 11, Verse 23', 'तं शीघ्रमभिगच्छ त्वं यदि युद्धमिहेच्छसि।
स हि दुर्धर्षणो नित्यं शूरः समरकर्मणि॥', 'taṃ śīghram abhigaccha tvaṃ yadi yuddham ihecchasi
sa hi durdharṣaṇo nityaṃ śūraḥ samarakarmaṇi', null, 4011023),
('ramayana-4-11-24', 24, 'Kishkindha Kanda, Sarga 11, Verse 24', 'श्रुत्वा हिमवतो वाक्यं क्रोधाविष्टः स दुन्दुभिः।
जगाम तां पुरीं तस्य किष्किन्धां वालिनस्तदा॥', 'śrutvā himavato vākyaṃ krodhāviṣṭaḥ sa dundubhiḥ
jagāma tāṃ purīṃ tasya kiṣkindhāṃ vālinas tadā', null, 4011024),
('ramayana-4-11-25', 25, 'Kishkindha Kanda, Sarga 11, Verse 25', 'धारयन्माहिषं रूपं तीक्ष्णशृङ्गो भयावहः।
प्रावृषीव महामेघस्तोयपूर्णो नभस्तले॥', 'dhārayan māhiṣaṃ rūpaṃ tīkṣṇaśṛṅgo bhayāvahaḥ
prāvṛṣīva mahāmeghas toyapūrṇo nabhastale', null, 4011025),
('ramayana-4-11-26', 26, 'Kishkindha Kanda, Sarga 11, Verse 26', 'ततस्तु द्वारमागम्य किष्किन्धाया महाबलः।
ननर्द कम्पयन्भूमिं दुन्दुभिर्दुन्दुभिर्यथा॥', 'tatas tu dvāram āgamya kiṣkindhāyā mahābalaḥ
nanarda kampayan bhūmiṃ dundubhir dundubhir yathā', null, 4011026),
('ramayana-4-11-27', 27, 'Kishkindha Kanda, Sarga 11, Verse 27', 'समीपजान्द्रुमान्भञ्जन्वसुधां दारयन्खुरैः।
विषाणेनोल्लेखन्दर्पात्तद्द्वारं द्विरदो यथा॥', 'samīpajān drumān bhañjan vasudhāṃ dārayan khuraiḥ
viṣāṇenollekhan darpāt taddvāraṃ dvirado yathā', null, 4011027),
('ramayana-4-11-28', 28, 'Kishkindha Kanda, Sarga 11, Verse 28', 'अन्तःपुरगतो वाली श्रुत्वा शब्दममर्षणः।
निष्पपात सह स्त्रीभिस्ताराभिरिव चन्द्रमाः॥', 'antaḥpuragato vālī śrutvā śabdam amarṣaṇaḥ
niṣpapāta saha strībhis tārābhir iva candramāḥ', null, 4011028),
('ramayana-4-11-29', 29, 'Kishkindha Kanda, Sarga 11, Verse 29', 'मितं व्यक्ताक्षरपदं तमुवाच स दुन्दुभिम्।
हरीणामीश्वरो वाली सर्वेषां वनचारिणाम्॥', 'mitaṃ vyaktākṣarapadaṃ tam uvāca sa dundubhim
harīṇām īśvaro vālī sarveṣāṃ vanacāriṇām', null, 4011029),
('ramayana-4-11-30', 30, 'Kishkindha Kanda, Sarga 11, Verse 30', 'किमर्थं नगरद्वारमिदं रुद्ध्वा विनर्दसि।
दुन्दुभे विदितो मेऽसि रक्ष प्राणान्महाबल॥', 'kimarthaṃ nagaradvāram idaṃ ruddhvā vinardasi
dundubhe vidito me ''si rakṣa prāṇān mahābala', null, 4011030),
('ramayana-4-11-31', 31, 'Kishkindha Kanda, Sarga 11, Verse 31', 'तस्य तद्वचनं श्रुत्वा वानरेन्द्रस्य धीमतः।
उवाच दुन्दुभिर्वाक्यं क्रोधात्संरक्तलोचनः॥', 'tasya tad vacanaṃ śrutvā vānarendrasya dhīmataḥ
uvāca dundubhir vākyaṃ krodhāt saṃraktalocanaḥ', null, 4011031),
('ramayana-4-11-32', 32, 'Kishkindha Kanda, Sarga 11, Verse 32', 'न त्वं स्त्रीसंनिधौ वीर वचनं वक्तुमर्हसि।
मम युद्धं प्रयच्छ त्वं ततो ज्ञास्यामि ते बलम्॥', 'na tvaṃ strīsaṃnidhau vīra vacanaṃ vaktum arhasi
mama yuddhaṃ prayaccha tvaṃ tato jñāsyāmi te balam', null, 4011032),
('ramayana-4-11-33', 33, 'Kishkindha Kanda, Sarga 11, Verse 33', 'अथ वा धारयिष्यामि क्रोधमद्य निशामिमाम्।
गृह्यतामुदयः स्वैरं कामभोगेषु वानर॥', 'atha vā dhārayiṣyāmi krodham adya niśām imām
gṛhyatām udayaḥ svairaṃ kāmabhogeṣu vānara', null, 4011033),
('ramayana-4-11-34', 34, 'Kishkindha Kanda, Sarga 11, Verse 34', 'यो हि मत्तं प्रमत्तं वा सुप्तं वा रहितं भृशम्।
हन्यात्स भ्रूणहा लोके त्वद्विधं मदमोहितम्॥', 'yo hi mattaṃ pramattaṃ vā suptaṃ vā rahitaṃ bhṛśam
hanyāt sa bhrūṇahā loke tvadvidhaṃ madamohitam', null, 4011034),
('ramayana-4-11-35', 35, 'Kishkindha Kanda, Sarga 11, Verse 35', 'स प्रहस्याब्रवीन्मन्दं क्रोधात्तमसुरोत्तमम्।
विसृज्य ताः स्त्रियः सर्वास्ताराप्रभृतिकास्तदा॥', 'sa prahasyābravīn mandaṃ krodhāt tam asurottamam
visṛjya tāḥ striyaḥ sarvās tārāprabhṛtikās tadā', null, 4011035),
('ramayana-4-11-36', 36, 'Kishkindha Kanda, Sarga 11, Verse 36', 'मत्तोऽयमिति मा मंस्था यद्यभीतोऽसि संयुगे।
मदोऽयं संप्रहारेऽस्मिन्वीरपानं समर्थ्यताम्॥', 'matto ''yam iti mā maṃsthā yady abhīto ''si saṃyuge
mado ''yaṃ saṃprahāre ''smin vīrapānaṃ samarthyatām', null, 4011036),
('ramayana-4-11-37', 37, 'Kishkindha Kanda, Sarga 11, Verse 37', 'तमेवमुक्त्वा संक्रुद्धो मालामुत्क्षिप्य काञ्चनीम्।
पित्रा दत्तां महेन्द्रेण युद्धाय व्यवतिष्ठत॥', 'tam evam uktvā saṃkruddho mālām utkṣipya kāñcanīm
pitrā dattāṃ mahendreṇa yuddhāya vyavatiṣṭhata', null, 4011037),
('ramayana-4-11-38', 38, 'Kishkindha Kanda, Sarga 11, Verse 38', 'विषाणयोर्गृहीत्वा तं दुन्दुभिं गिरिसंनिभम्।
वाली व्यापातयां चक्रे ननर्द च महास्वनम्॥', 'viṣāṇayor gṛhītvā taṃ dundubhiṃ girisaṃnibham
vālī vyāpātayāṃ cakre nanarda ca mahāsvanam', null, 4011038),
('ramayana-4-11-39', 39, 'Kishkindha Kanda, Sarga 11, Verse 39', 'युद्धे प्राणहरे तस्मिन्निष्पिष्टो दुन्दुभिस्तदा।
श्रोत्राभ्यामथ रक्तं तु तस्य सुस्राव पात्यतः।
पपात च महाकायः क्षितौ पञ्चत्वमागतः॥', 'yuddhe prāṇahare tasmin niṣpiṣṭo dundubhis tadā
śrotrābhyām atha raktaṃ tu tasya susrāva pātyataḥ
papāta ca mahākāyaḥ kṣitau pañcatvam āgataḥ', null, 4011039),
('ramayana-4-11-40', 40, 'Kishkindha Kanda, Sarga 11, Verse 40', 'तं तोलयित्वा बाहुभ्यां गतसत्त्वमचेतनम्।
चिक्षेप वेगवान्वाली वेगेनैकेन योजनम्॥', 'taṃ tolayitvā bāhubhyāṃ gatasattvam acetanam
cikṣepa vegavān vālī vegenaikena yojanam', null, 4011040),
('ramayana-4-11-41', 41, 'Kishkindha Kanda, Sarga 11, Verse 41', 'तस्य वेगप्रविद्धस्य वक्त्रात्क्षतजबिन्दवः।
प्रपेतुर्मारुतोत्क्षिप्ता मतङ्गस्याश्रमं प्रति॥', 'tasya vegapraviddhasya vaktrāt kṣatajabindavaḥ
prapetur mārutotkṣiptā mataṅgasyāśramaṃ prati', null, 4011041),
('ramayana-4-11-42', 42, 'Kishkindha Kanda, Sarga 11, Verse 42', 'तान्दृष्ट्वा पतितांस्तत्र मुनिः शोणितविप्रुषः।
उत्ससर्ज महाशापं क्षेप्तारं वालिनं प्रति।
इह तेनाप्रवेष्टव्यं प्रविष्टस्य बधो भवेत्॥', 'tān dṛṣṭvā patitāṃs tatra muniḥ śoṇitavipruṣaḥ
utsasarja mahāśāpaṃ kṣeptāraṃ vālinaṃ prati
iha tenāpraveṣṭavyaṃ praviṣṭasya badho bhavet', null, 4011042),
('ramayana-4-11-43', 43, 'Kishkindha Kanda, Sarga 11, Verse 43', 'स महर्षिं समासाद्य याचते स्म कृताञ्जलिः॥', 'sa maharṣiṃ samāsādya yācate sma kṛtāñjaliḥ', null, 4011043),
('ramayana-4-11-44', 44, 'Kishkindha Kanda, Sarga 11, Verse 44', 'ततः शापभयाद्भीत ऋश्यमूकं महागिरिम्।
प्रवेष्टुं नेच्छति हरिर्द्रष्टुं वापि नरेश्वर॥', 'tataḥ śāpabhayād bhīta ṛśyamūkaṃ mahāgirim
praveṣṭuṃ necchati harir draṣṭuṃ vāpi nareśvara', null, 4011044),
('ramayana-4-11-45', 45, 'Kishkindha Kanda, Sarga 11, Verse 45', 'तस्याप्रवेशं ज्ञात्वाहमिदं राम महावनम्।
विचरामि सहामात्यो विषादेन विवर्जितः॥', 'tasyāpraveśaṃ jñātvāham idaṃ rāma mahāvanam
vicarāmi sahāmātyo viṣādena vivarjitaḥ', null, 4011045),
('ramayana-4-11-46', 46, 'Kishkindha Kanda, Sarga 11, Verse 46', 'एषोऽस्थिनिचयस्तस्य दुन्दुभेः संप्रकाशते।
वीर्योत्सेकान्निरस्तस्य गिरिकूटनिभो महान्॥', 'eṣo ''sthinicayas tasya dundubheḥ saṃprakāśate
vīryotsekān nirastasya girikūṭanibho mahān', null, 4011046),
('ramayana-4-11-47', 47, 'Kishkindha Kanda, Sarga 11, Verse 47', 'इमे च विपुलाः सालाः सप्त शाखावलम्बिनः।
यत्रैकं घटते वाली निष्पत्रयितुमोजसा॥', 'ime ca vipulāḥ sālāḥ sapta śākhāvalambinaḥ
yatraikaṃ ghaṭate vālī niṣpatrayitum ojasā', null, 4011047),
('ramayana-4-11-48', 48, 'Kishkindha Kanda, Sarga 11, Verse 48', 'एतदस्यासमं वीर्यं मया राम प्रकाशितम्।
कथं तं वालिनं हन्तुं समरे शक्ष्यसे नृप॥', 'etad asyāsamaṃ vīryaṃ mayā rāma prakāśitam
kathaṃ taṃ vālinaṃ hantuṃ samare śakṣyase nṛpa', null, 4011048),
('ramayana-4-11-49', 49, 'Kishkindha Kanda, Sarga 11, Verse 49', 'यदि भिन्द्याद्भवान्सालानिमांस्त्वेकेषुणा ततः।
जानीयां त्वां महाबाहो समर्थं वालिनो वधे॥', 'yadi bhindyād bhavān sālān imāṃs tv ekeṣuṇā tataḥ
jānīyāṃ tvāṃ mahābāho samarthaṃ vālino vadhe', null, 4011049),
('ramayana-4-11-50', 50, 'Kishkindha Kanda, Sarga 11, Verse 50', 'तस्य तद्वचनं श्रुत्वा सुग्रीवस्य महात्मनः।
राघवो दुन्दुभेः कायं पादाङ्गुष्ठेन लीलया।
तोलयित्वा महाबाहुश्चिक्षेप दशयोजनम्॥', 'tasya tad vacanaṃ śrutvā sugrīvasya mahātmanaḥ
rāghavo dundubheḥ kāyaṃ pādāṅguṣṭhena līlayā
tolayitvā mahābāhuś cikṣepa daśayojanam', null, 4011050),
('ramayana-4-11-51', 51, 'Kishkindha Kanda, Sarga 11, Verse 51', 'क्षिप्तं दृष्ट्वा ततः कायं सुग्रीवः पुनरब्रवीत्।
लक्ष्मणस्याग्रतो राममिदं वचनमर्थवत्॥', 'kṣiptaṃ dṛṣṭvā tataḥ kāyaṃ sugrīvaḥ punar abravīt
lakṣmaṇasyāgrato rāmam idaṃ vacanam arthavat', null, 4011051),
('ramayana-4-11-52', 52, 'Kishkindha Kanda, Sarga 11, Verse 52', 'आर्द्रः समांसप्रत्यग्रः क्षिप्तः कायः पुरा सखे।
लघुः संप्रति निर्मांसस्तृणभूतश्च राघव।
नात्र शक्यं बलं ज्ञातुं तव वा तस्य वाधिकम्॥', 'ārdraḥ samāṃsapratyagraḥ kṣiptaḥ kāyaḥ purā sakhe
laghuḥ saṃprati nirmāṃsas tṛṇabhūtaś ca rāghava
nātra śakyaṃ balaṃ jñātuṃ tava vā tasya vādhikam', null, 4011052)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 12 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-12-1', 1, 'Kishkindha Kanda, Sarga 12, Verse 1', 'एतच्च वचनं श्रुत्वा सुग्रीवेण सुभाषितम्।
प्रत्ययार्थं महातेजा रामो जग्राह कार्मुकम्॥', 'etac ca vacanaṃ śrutvā sugrīveṇa subhāṣitam
pratyayārthaṃ mahātejā rāmo jagrāha kārmukam', null, 4012001),
('ramayana-4-12-2', 2, 'Kishkindha Kanda, Sarga 12, Verse 2', 'स गृहीत्वा धनुर्घोरं शरमेकं च मानदः।
सालानुद्दिश्य चिक्षेप ज्यास्वनैः पूरयन्दिशः॥', 'sa gṛhītvā dhanur ghoraṃ śaram ekaṃ ca mānadaḥ
sālān uddiśya cikṣepa jyāsvanaiḥ pūrayan diśaḥ', null, 4012002),
('ramayana-4-12-3', 3, 'Kishkindha Kanda, Sarga 12, Verse 3', 'स विसृष्टो बलवता बाणः स्वर्णपरिष्कृतः।
भित्त्वा सालान्गिरिप्रस्थे सप्त भूमिं विवेश ह॥', 'sa visṛṣṭo balavatā bāṇaḥ svarṇapariṣkṛtaḥ
bhittvā sālān giriprasthe sapta bhūmiṃ viveśa ha', null, 4012003),
('ramayana-4-12-4', 4, 'Kishkindha Kanda, Sarga 12, Verse 4', 'प्रविष्टस्तु मुहूर्तेन रसां भित्त्वा महाजवः।
निष्पत्य च पुनस्तूर्णं स्वतूणीं प्रविवेश ह॥', 'praviṣṭas tu muhūrtena rasāṃ bhittvā mahājavaḥ
niṣpatya ca punas tūrṇaṃ svatūṇīṃ praviveśa ha', null, 4012004),
('ramayana-4-12-5', 5, 'Kishkindha Kanda, Sarga 12, Verse 5', 'तान्दृष्ट्वा सप्त निर्भिन्नान्सालान्वानरपुंगवः।
रामस्य शरवेगेन विस्मयं परमं गतः॥', 'tān dṛṣṭvā sapta nirbhinnān sālān vānarapuṃgavaḥ
rāmasya śaravegena vismayaṃ paramaṃ gataḥ', null, 4012005),
('ramayana-4-12-6', 6, 'Kishkindha Kanda, Sarga 12, Verse 6', 'स मूर्ध्ना न्यपतद्भूमौ प्रलम्बीकृतभूषणः।
सुग्रीवः परमप्रीतो राघवाय कृताञ्जलिः॥', 'sa mūrdhnā nyapatad bhūmau pralambīkṛtabhūṣaṇaḥ
sugrīvaḥ paramaprīto rāghavāya kṛtāñjaliḥ', null, 4012006),
('ramayana-4-12-7', 7, 'Kishkindha Kanda, Sarga 12, Verse 7', 'इदं चोवाच धर्मज्ञं कर्मणा तेन हर्षितः।
रामं सर्वास्त्रविदुषां श्रेष्ठं शूरमवस्थितम्॥', 'idaṃ covāca dharmajñaṃ karmaṇā tena harṣitaḥ
rāmaṃ sarvāstraviduṣāṃ śreṣṭhaṃ śūram avasthitam', null, 4012007),
('ramayana-4-12-8', 8, 'Kishkindha Kanda, Sarga 12, Verse 8', 'सेन्द्रानपि सुरान्सर्वांस्त्वं बाणैः पुरुषर्षभ।
समर्थः समरे हन्तुं किं पुनर्वालिनं प्रभो॥', 'sendrān api surān sarvāṃs tvaṃ bāṇaiḥ puruṣarṣabha
samarthaḥ samare hantuṃ kiṃ punar vālinaṃ prabho', null, 4012008),
('ramayana-4-12-9', 9, 'Kishkindha Kanda, Sarga 12, Verse 9', 'येन सप्त महासाला गिरिर्भूमिश्च दारिताः।
बाणेनैकेन काकुत्स्थ स्थाता ते को रणाग्रतः॥', 'yena sapta mahāsālā girir bhūmiś ca dāritāḥ
bāṇenaikena kākutstha sthātā te ko raṇāgrataḥ', null, 4012009),
('ramayana-4-12-10', 10, 'Kishkindha Kanda, Sarga 12, Verse 10', 'अद्य मे विगतः शोकः प्रीतिरद्य परा मम।
सुहृदं त्वां समासाद्य महेन्द्रवरुणोपमम्॥', 'adya me vigataḥ śokaḥ prītir adya parā mama
suhṛdaṃ tvāṃ samāsādya mahendravaruṇopamam', null, 4012010),
('ramayana-4-12-11', 11, 'Kishkindha Kanda, Sarga 12, Verse 11', 'तमद्यैव प्रियार्थं मे वैरिणं भ्रातृरूपिणम्।
वालिनं जहि काकुत्स्थ मया बद्धोऽयमञ्जलिः॥', 'tam adyaiva priyārthaṃ me vairiṇaṃ bhrātṛrūpiṇam
vālinaṃ jahi kākutstha mayā baddho ''yam añjaliḥ', null, 4012011),
('ramayana-4-12-12', 12, 'Kishkindha Kanda, Sarga 12, Verse 12', 'ततो रामः परिष्वज्य सुग्रीवं प्रियदर्शनम्।
प्रत्युवाच महाप्राज्ञो लक्ष्मणानुमतं वचः॥', 'tato rāmaḥ pariṣvajya sugrīvaṃ priyadarśanam
pratyuvāca mahāprājño lakṣmaṇānumataṃ vacaḥ', null, 4012012),
('ramayana-4-12-13', 13, 'Kishkindha Kanda, Sarga 12, Verse 13', 'अस्माद्गच्छाम किष्किन्धां क्षिप्रं गच्छ त्वमग्रतः।
गत्वा चाह्वय सुग्रीव वालिनं भ्रातृगन्धिनम्॥', 'asmād gacchāma kiṣkindhāṃ kṣipraṃ gaccha tvam agrataḥ
gatvā cāhvaya sugrīva vālinaṃ bhrātṛgandhinam', null, 4012013),
('ramayana-4-12-14', 14, 'Kishkindha Kanda, Sarga 12, Verse 14', 'सर्वे ते त्वरितं गत्वा किष्किन्धां वालिनः पुरीम्।
वृक्षैरात्मानमावृत्य व्यतिष्ठन्गहने वने॥', 'sarve te tvaritaṃ gatvā kiṣkindhāṃ vālinaḥ purīm
vṛkṣair ātmānam āvṛtya vyatiṣṭhan gahane vane', null, 4012014),
('ramayana-4-12-15', 15, 'Kishkindha Kanda, Sarga 12, Verse 15', 'सुग्रीवो व्यनदद्घोरं वालिनो ह्वानकारणात्।
गाढं परिहितो वेगान्नादैर्भिन्दन्निवाम्बरम्॥', 'sugrīvo vyanadad ghoraṃ vālino hvānakāraṇāt
gāḍhaṃ parihito vegān nādair bhindann ivāmbaram', null, 4012015),
('ramayana-4-12-16', 16, 'Kishkindha Kanda, Sarga 12, Verse 16', 'तं श्रुत्वा निनदं भ्रातुः क्रुद्धो वाली महाबलः।
निष्पपात सुसंरब्धो भास्करोऽस्ततटादिव॥', 'taṃ śrutvā ninadaṃ bhrātuḥ kruddho vālī mahābalaḥ
niṣpapāta susaṃrabdho bhāskaro ''stataṭād iva', null, 4012016),
('ramayana-4-12-17', 17, 'Kishkindha Kanda, Sarga 12, Verse 17', 'ततः सुतुमुलं युद्धं वालिसुग्रीवयोरभूत्।
गगने ग्रहयोर्घोरं बुधाङ्गारकयोरिव॥', 'tataḥ sutumulaṃ yuddhaṃ vālisugrīvayor abhūt
gagane grahayor ghoraṃ budhāṅgārakayor iva', null, 4012017),
('ramayana-4-12-18', 18, 'Kishkindha Kanda, Sarga 12, Verse 18', 'तलैरशनिकल्पैश्च वज्रकल्पैश्च मुष्टिभिः।
जघ्नतुः समरेऽन्योन्यं भ्रातरौ क्रोधमूर्छितौ॥', 'talair aśanikalpaiś ca vajrakalpaiś ca muṣṭibhiḥ
jaghnatuḥ samare ''nyonyaṃ bhrātarau krodhamūrchitau', null, 4012018),
('ramayana-4-12-19', 19, 'Kishkindha Kanda, Sarga 12, Verse 19', 'ततो रामो धनुष्पाणिस्तावुभौ समुदीक्ष्य तु।
अन्योन्यसदृशौ वीरावुभौ देवाविवाश्विनौ॥', 'tato rāmo dhanuṣpāṇis tāv ubhau samudīkṣya tu
anyonyasadṛśau vīrāv ubhau devāv ivāśvinau', null, 4012019),
('ramayana-4-12-20', 20, 'Kishkindha Kanda, Sarga 12, Verse 20', 'यन्नावगच्छत्सुग्रीवं वालिनं वापि राघवः।
ततो न कृतवान्बुद्धिं मोक्तुमन्तकरं शरम्॥', 'yan nāvagacchat sugrīvaṃ vālinaṃ vāpi rāghavaḥ
tato na kṛtavān buddhiṃ moktum antakaraṃ śaram', null, 4012020),
('ramayana-4-12-21', 21, 'Kishkindha Kanda, Sarga 12, Verse 21', 'एतस्मिन्नन्तरे भग्नः सुग्रीवस्तेन वालिना।
अपश्यन्राघवं नाथमृश्यमूकं प्रदुद्रुवे॥', 'etasminn antare bhagnaḥ sugrīvas tena vālinā
apaśyan rāghavaṃ nātham ṛśyamūkaṃ pradudruve', null, 4012021),
('ramayana-4-12-22', 22, 'Kishkindha Kanda, Sarga 12, Verse 22', 'क्लान्तो रुधिरसिक्ताङ्गः प्रहारैर्जर्जरीकृतः।
वालिनाभिद्रुतः क्रोधात्प्रविवेश महावनम्॥', 'klānto rudhirasiktāṅgaḥ prahārair jarjarīkṛtaḥ
vālinābhidrutaḥ krodhāt praviveśa mahāvanam', null, 4012022),
('ramayana-4-12-23', 23, 'Kishkindha Kanda, Sarga 12, Verse 23', 'तं प्रविष्टं वनं दृष्ट्वा वाली शापभयात्ततः।
मुक्तो ह्यसि त्वमित्युक्त्वा स निवृत्तो महाबलः॥', 'taṃ praviṣṭaṃ vanaṃ dṛṣṭvā vālī śāpabhayāt tataḥ
mukto hy asi tvam ity uktvā sa nivṛtto mahābalaḥ', null, 4012023),
('ramayana-4-12-24', 24, 'Kishkindha Kanda, Sarga 12, Verse 24', 'राघवोऽपि सह भ्रात्रा सह चैव हनूमता।
तदेव वनमागच्छत्सुग्रीवो यत्र वानरः॥', 'rāghavo ''pi saha bhrātrā saha caiva hanūmatā
tad eva vanam āgacchat sugrīvo yatra vānaraḥ', null, 4012024),
('ramayana-4-12-25', 25, 'Kishkindha Kanda, Sarga 12, Verse 25', 'तं समीक्ष्यागतं रामं सुग्रीवः सहलक्ष्मणम्।
ह्रीमान्दीनमुवाचेदं वसुधामवलोकयन्॥', 'taṃ samīkṣyāgataṃ rāmaṃ sugrīvaḥ sahalakṣmaṇam
hrīmān dīnam uvācedaṃ vasudhām avalokayan', null, 4012025),
('ramayana-4-12-26', 26, 'Kishkindha Kanda, Sarga 12, Verse 26', 'आह्वयस्वेति मामुक्त्वा दर्शयित्वा च विक्रमम्।
वैरिणा घातयित्वा च किमिदानीं त्वया कृतम्॥', 'āhvayasveti mām uktvā darśayitvā ca vikramam
vairiṇā ghātayitvā ca kim idānīṃ tvayā kṛtam', null, 4012026),
('ramayana-4-12-27', 27, 'Kishkindha Kanda, Sarga 12, Verse 27', 'तामेव वेलां वक्तव्यं त्वया राघव तत्त्वतः।
वालिनं न निहन्मीति ततो नाहमितो व्रजे॥', 'tām eva velāṃ vaktavyaṃ tvayā rāghava tattvataḥ
vālinaṃ na nihanmīti tato nāham ito vraje', null, 4012027),
('ramayana-4-12-28', 28, 'Kishkindha Kanda, Sarga 12, Verse 28', 'तस्य चैवं ब्रुवाणस्य सुग्रीवस्य महात्मनः।
करुणं दीनया वाचा राघवः पुनरब्रवीत्॥', 'tasya caivaṃ bruvāṇasya sugrīvasya mahātmanaḥ
karuṇaṃ dīnayā vācā rāghavaḥ punar abravīt', null, 4012028),
('ramayana-4-12-29', 29, 'Kishkindha Kanda, Sarga 12, Verse 29', 'सुग्रीव श्रूयतां तातः क्रोधश्च व्यपनीयताम्।
कारणं येन बाणोऽयं न मया स विसर्जितः॥', 'sugrīva śrūyatāṃ tātaḥ krodhaś ca vyapanīyatām
kāraṇaṃ yena bāṇo ''yaṃ na mayā sa visarjitaḥ', null, 4012029),
('ramayana-4-12-30', 30, 'Kishkindha Kanda, Sarga 12, Verse 30', 'अलंकारेण वेषेण प्रमाणेन गतेन च।
त्वं च सुग्रीव वाली च सदृशौ स्थः परस्परम्॥', 'alaṃkāreṇa veṣeṇa pramāṇena gatena ca
tvaṃ ca sugrīva vālī ca sadṛśau sthaḥ parasparam', null, 4012030),
('ramayana-4-12-31', 31, 'Kishkindha Kanda, Sarga 12, Verse 31', 'स्वरेण वर्चसा चैव प्रेक्षितेन च वानर।
विक्रमेण च वाक्यैश्च व्यक्तिं वां नोपलक्षये॥', 'svareṇa varcasā caiva prekṣitena ca vānara
vikrameṇa ca vākyaiś ca vyaktiṃ vāṃ nopalakṣaye', null, 4012031),
('ramayana-4-12-32', 32, 'Kishkindha Kanda, Sarga 12, Verse 32', 'ततोऽहं रूपसादृश्यान्मोहितो वानरोत्तम।
नोत्सृजामि महावेगं शरं शत्रुनिबर्हणम्॥', 'tato ''haṃ rūpasādṛśyān mohito vānarottama
notsṛjāmi mahāvegaṃ śaraṃ śatrunibarhaṇam', null, 4012032),
('ramayana-4-12-33', 33, 'Kishkindha Kanda, Sarga 12, Verse 33', 'एतन्मुहूर्ते तु मया पश्य वालिनमाहवे।
निरस्तमिषुणैकेन वेष्टमानं महीतले॥', 'etanmuhūrte tu mayā paśya vālinam āhave
nirastam iṣuṇaikena veṣṭamānaṃ mahītale', null, 4012033),
('ramayana-4-12-34', 34, 'Kishkindha Kanda, Sarga 12, Verse 34', 'अभिज्ञानं कुरुष्व त्वमात्मनो वानरेश्वर।
येन त्वामभिजानीयां द्वन्द्वयुद्धमुपागतम्॥', 'abhijñānaṃ kuruṣva tvam ātmano vānareśvara
yena tvām abhijānīyāṃ dvandvayuddham upāgatam', null, 4012034),
('ramayana-4-12-35', 35, 'Kishkindha Kanda, Sarga 12, Verse 35', 'गजपुष्पीमिमां फुल्लामुत्पाट्य शुभलक्षणाम्।
कुरु लक्ष्मण कण्ठेऽस्य सुग्रीवस्य महात्मनः॥', 'gajapuṣpīm imāṃ phullām utpāṭya śubhalakṣaṇām
kuru lakṣmaṇa kaṇṭhe ''sya sugrīvasya mahātmanaḥ', null, 4012035),
('ramayana-4-12-36', 36, 'Kishkindha Kanda, Sarga 12, Verse 36', 'ततो गिरितटे जातामुत्पाट्य कुसुमायुताम्।
लक्ष्मणो गजपुष्पीं तां तस्य कण्ठे व्यसर्जयत्॥', 'tato giritaṭe jātām utpāṭya kusumāyutām
lakṣmaṇo gajapuṣpīṃ tāṃ tasya kaṇṭhe vyasarjayat', null, 4012036),
('ramayana-4-12-37', 37, 'Kishkindha Kanda, Sarga 12, Verse 37', 'स तथा शुशुभे श्रीमांल्लतया कण्ठसक्तया।
मालयेव बलाकानां ससंध्य इव तोयदः॥', 'sa tathā śuśubhe śrīmāṃl latayā kaṇṭhasaktayā
mālayeva balākānāṃ sasaṃdhya iva toyadaḥ', null, 4012037),
('ramayana-4-12-38', 38, 'Kishkindha Kanda, Sarga 12, Verse 38', 'विभ्राजमानो वपुषा रामवाक्यसमाहितः।
जगाम सह रामेण किष्किन्धां वालिपालिताम्॥', 'vibhrājamāno vapuṣā rāmavākyasamāhitaḥ
jagāma saha rāmeṇa kiṣkindhāṃ vālipālitām', null, 4012038)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 13 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-13-1', 1, 'Kishkindha Kanda, Sarga 13, Verse 1', 'ऋश्यमूकात्स धर्मात्मा किष्किन्धां लक्ष्मणाग्रजः।
जगाम सहसुग्रीवो वालिविक्रमपालिताम्॥', 'ṛśyamūkāt sa dharmātmā kiṣkindhāṃ lakṣmaṇāgrajaḥ
jagāma sahasugrīvo vālivikramapālitām', null, 4013001),
('ramayana-4-13-2', 2, 'Kishkindha Kanda, Sarga 13, Verse 2', 'समुद्यम्य महच्चापं रामः काञ्चनभूषितम्।
शरांश्चादित्य संकाशान्गृहीत्वा रणसाधकान्॥', 'samudyamya mahac cāpaṃ rāmaḥ kāñcanabhūṣitam
śarāṃś cāditya saṃkāśān gṛhītvā raṇasādhakān', null, 4013002),
('ramayana-4-13-3', 3, 'Kishkindha Kanda, Sarga 13, Verse 3', 'अग्रतस्तु ययौ तस्य राघवस्य महात्मनः।
सुग्रीवः संहतग्रीवो लक्ष्मणश्च महाबलः॥', 'agratas tu yayau tasya rāghavasya mahātmanaḥ
sugrīvaḥ saṃhatagrīvo lakṣmaṇaś ca mahābalaḥ', null, 4013003),
('ramayana-4-13-4', 4, 'Kishkindha Kanda, Sarga 13, Verse 4', 'पृष्ठतो हनुमान्वीरो नलो नीलश्च वानरः।
तारश्चैव महातेजा हरियूथप यूथपाः॥', 'pṛṣṭhato hanumān vīro nalo nīlaś ca vānaraḥ
tāraś caiva mahātejā hariyūthapa yūthapāḥ', null, 4013004),
('ramayana-4-13-5', 5, 'Kishkindha Kanda, Sarga 13, Verse 5', 'ते वीक्षमाणा वृक्षांश्च पुष्पभारावलम्बिनः।
प्रसन्नाम्बुवहाश्चैव सरितः सागरं गमाः॥', 'te vīkṣamāṇā vṛkṣāṃś ca puṣpabhārāvalambinaḥ
prasannāmbuvahāś caiva saritaḥ sāgaraṃ gamāḥ', null, 4013005),
('ramayana-4-13-6', 6, 'Kishkindha Kanda, Sarga 13, Verse 6', 'कन्दराणि च शैलांश्च निर्झराणि गुहास्तथा।
शिखराणि च मुख्यानि दरीश्च प्रियदर्शनाः॥', 'kandarāṇi ca śailāṃś ca nirjharāṇi guhās tathā
śikharāṇi ca mukhyāni darīś ca priyadarśanāḥ', null, 4013006),
('ramayana-4-13-7', 7, 'Kishkindha Kanda, Sarga 13, Verse 7', 'वैदूर्यविमलैः पर्णैः पद्मैश्चाकाशकुड्मलैः।
शोभितान्सजलान्मार्गे तटाकांश्च व्यलोकयन्॥', 'vaidūryavimalaiḥ parṇaiḥ padmaiś cākāśakuḍmalaiḥ
śobhitān sajalān mārge taṭākāṃś ca vyalokayan', null, 4013007),
('ramayana-4-13-8', 8, 'Kishkindha Kanda, Sarga 13, Verse 8', 'कारण्डैः सारसैर्हंसैर्वञ्जूलैर्जलकुक्कुटैः।
चक्रवाकैस्तथा चान्यैः शकुनैः प्रतिनादितान्॥', 'kāraṇḍaiḥ sārasair haṃsair vañjūlair jalakukkuṭaiḥ
cakravākais tathā cānyaiḥ śakunaiḥ pratināditān', null, 4013008),
('ramayana-4-13-9', 9, 'Kishkindha Kanda, Sarga 13, Verse 9', 'मृदुशष्पाङ्कुराहारान्निर्भयान्वनगोचरान्।
चरतः सर्वतोऽपश्यन्स्थलीषु हरिणान्स्थितान्॥', 'mṛduśaṣpāṅkurāhārān nirbhayān vanagocarān
carataḥ sarvato ''paśyan sthalīṣu hariṇān sthitān', null, 4013009),
('ramayana-4-13-10', 10, 'Kishkindha Kanda, Sarga 13, Verse 10', 'तटाकवैरिणश्चापि शुक्लदन्तविभूषितान्।
घोरानेकचरान्वन्यान्द्विरदान्कूलघातिनः॥', 'taṭākavairiṇaś cāpi śukladantavibhūṣitān
ghorān ekacarān vanyān dviradān kūlaghātinaḥ', null, 4013010),
('ramayana-4-13-11', 11, 'Kishkindha Kanda, Sarga 13, Verse 11', 'वने वनचरांश्चान्यान्खेचरांश्च विहंगमान्।
पश्यन्तस्त्वरिता जग्मुः सुग्रीववशवर्तिनः॥', 'vane vanacarāṃś cānyān khecarāṃś ca vihaṃgamān
paśyantas tvaritā jagmuḥ sugrīvavaśavartinaḥ', null, 4013011),
('ramayana-4-13-12', 12, 'Kishkindha Kanda, Sarga 13, Verse 12', 'तेषां तु गच्छतां तत्र त्वरितं रघुनन्दनः।
द्रुमषण्डं वनं दृष्ट्वा रामः सुग्रीवमब्रवीत्॥', 'teṣāṃ tu gacchatāṃ tatra tvaritaṃ raghunandanaḥ
drumaṣaṇḍaṃ vanaṃ dṛṣṭvā rāmaḥ sugrīvam abravīt', null, 4013012),
('ramayana-4-13-13', 13, 'Kishkindha Kanda, Sarga 13, Verse 13', 'एष मेघ इवाकाशे वृक्षषण्डः प्रकाशते।
मेघसंघातविपुलः पर्यन्तकदलीवृतः॥', 'eṣa megha ivākāśe vṛkṣaṣaṇḍaḥ prakāśate
meghasaṃghātavipulaḥ paryantakadalīvṛtaḥ', null, 4013013),
('ramayana-4-13-14', 14, 'Kishkindha Kanda, Sarga 13, Verse 14', 'किमेतज्ज्ञातुमिच्छामि सखे कौतूहलं मम।
कौतूहलापनयनं कर्तुमिच्छाम्यहं त्वया॥', 'kim etaj jñātum icchāmi sakhe kautūhalaṃ mama
kautūhalāpanayanaṃ kartum icchāmy ahaṃ tvayā', null, 4013014),
('ramayana-4-13-15', 15, 'Kishkindha Kanda, Sarga 13, Verse 15', 'तस्य तद्वचनं श्रुत्वा राघवस्य महात्मनः।
गच्छन्नेवाचचक्षेऽथ सुग्रीवस्तन्महद्वनम्॥', 'tasya tad vacanaṃ śrutvā rāghavasya mahātmanaḥ
gacchann evācacakṣe ''tha sugrīvas tan mahad vanam', null, 4013015),
('ramayana-4-13-16', 16, 'Kishkindha Kanda, Sarga 13, Verse 16', 'एतद्राघव विस्तीर्णमाश्रमं श्रमनाशनम्।
उद्यानवनसंपन्नं स्वादुमूलफलोदकम्॥', 'etad rāghava vistīrṇam āśramaṃ śramanāśanam
udyānavanasaṃpannaṃ svādumūlaphalodakam', null, 4013016),
('ramayana-4-13-17', 17, 'Kishkindha Kanda, Sarga 13, Verse 17', 'अत्र सप्तजना नाम मुनयः संशितव्रताः।
सप्तैवासन्नधःशीर्षा नियतं जलशायिनः॥', 'atra saptajanā nāma munayaḥ saṃśitavratāḥ
saptaivāsann adhaḥśīrṣā niyataṃ jalaśāyinaḥ', null, 4013017),
('ramayana-4-13-18', 18, 'Kishkindha Kanda, Sarga 13, Verse 18', 'सप्तरात्रकृताहारा वायुना वनवासिनः।
दिवं वर्षशतैर्याताः सप्तभिः सकलेवराः॥', 'saptarātrakṛtāhārā vāyunā vanavāsinaḥ
divaṃ varṣaśatair yātāḥ saptabhiḥ sakalevarāḥ', null, 4013018),
('ramayana-4-13-19', 19, 'Kishkindha Kanda, Sarga 13, Verse 19', 'तेषामेवं प्रभावेन द्रुमप्राकारसंवृतम्।
आश्रमं सुदुराधर्षमपि सेन्द्रैः सुरासुरैः॥', 'teṣām evaṃ prabhāvena drumaprākārasaṃvṛtam
āśramaṃ sudurādharṣam api sendraiḥ surāsuraiḥ', null, 4013019),
('ramayana-4-13-20', 20, 'Kishkindha Kanda, Sarga 13, Verse 20', 'पक्षिणो वर्जयन्त्येतत्तथान्ये वनचारिणः।
विशन्ति मोहाद्येऽप्यत्र निवर्तन्ते न ते पुनः॥', 'pakṣiṇo varjayanty etat tathānye vanacāriṇaḥ
viśanti mohād ye ''py atra nivartante na te punaḥ', null, 4013020),
('ramayana-4-13-21', 21, 'Kishkindha Kanda, Sarga 13, Verse 21', 'विभूषणरवाश्चात्र श्रूयन्ते सकलाक्षराः।
तूर्यगीतस्वनाश्चापि गन्धो दिव्यश्च राघव॥', 'vibhūṣaṇaravāś cātra śrūyante sakalākṣarāḥ
tūryagītasvanāś cāpi gandho divyaś ca rāghava', null, 4013021),
('ramayana-4-13-22', 22, 'Kishkindha Kanda, Sarga 13, Verse 22', 'त्रेताग्नयोऽपि दीप्यन्ते धूमो ह्येष प्रदृश्यते।
वेष्टयन्निव वृक्षाग्रान्कपोताङ्गारुणो घनः॥', 'tretāgnayo ''pi dīpyante dhūmo hy eṣa pradṛśyate
veṣṭayann iva vṛkṣāgrān kapotāṅgāruṇo ghanaḥ', null, 4013022),
('ramayana-4-13-23', 23, 'Kishkindha Kanda, Sarga 13, Verse 23', 'कुरु प्रणामं धर्मात्मंस्तान्समुद्दिश्य राघवः।
लक्ष्मणेन सह भ्रात्रा प्रयतः संयताञ्जलिः॥', 'kuru praṇāmaṃ dharmātmaṃs tān samuddiśya rāghavaḥ
lakṣmaṇena saha bhrātrā prayataḥ saṃyatāñjaliḥ', null, 4013023),
('ramayana-4-13-24', 24, 'Kishkindha Kanda, Sarga 13, Verse 24', 'प्रणमन्ति हि ये तेषामृषीणां भावितात्मनाम्।
न तेषामशुभं किं चिच्छरीरे राम दृश्यते॥', 'praṇamanti hi ye teṣām ṛṣīṇāṃ bhāvitātmanām
na teṣām aśubhaṃ kiṃ cic charīre rāma dṛśyate', null, 4013024),
('ramayana-4-13-25', 25, 'Kishkindha Kanda, Sarga 13, Verse 25', 'ततो रामः सह भ्रात्रा लक्ष्मणेन कृताञ्जलिः।
समुद्दिश्य महात्मानस्तानृषीनभ्यवादयत्॥', 'tato rāmaḥ saha bhrātrā lakṣmaṇena kṛtāñjaliḥ
samuddiśya mahātmānas tān ṛṣīn abhyavādayat', null, 4013025),
('ramayana-4-13-26', 26, 'Kishkindha Kanda, Sarga 13, Verse 26', 'अभिवाद्य च धर्मात्मा रामो भ्राता च लक्ष्मणः।
सुग्रीवो वानराश्चैव जग्मुः संहृष्टमानसाः॥', 'abhivādya ca dharmātmā rāmo bhrātā ca lakṣmaṇaḥ
sugrīvo vānarāś caiva jagmuḥ saṃhṛṣṭamānasāḥ', null, 4013026),
('ramayana-4-13-27', 27, 'Kishkindha Kanda, Sarga 13, Verse 27', 'ते गत्वा दूरमध्वानं तस्मात्सप्तजनाश्रमात्।
ददृशुस्तां दुराधर्षां किष्किन्धां वालिपालिताम्॥', 'te gatvā dūram adhvānaṃ tasmāt saptajanāśramāt
dadṛśus tāṃ durādharṣāṃ kiṣkindhāṃ vālipālitām', null, 4013027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 14 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-14-1', 1, 'Kishkindha Kanda, Sarga 14, Verse 1', 'सर्वे ते त्वरितं गत्वा किष्किन्धां वालिपालिताम्।
वृक्षैरात्मानमावृत्य व्यतिष्ठन्गहने वने॥', 'sarve te tvaritaṃ gatvā kiṣkindhāṃ vālipālitām
vṛkṣair ātmānam āvṛtya vyatiṣṭhan gahane vane', null, 4014001),
('ramayana-4-14-2', 2, 'Kishkindha Kanda, Sarga 14, Verse 2', 'विचार्य सर्वतो दृष्टिं कानने काननप्रियः।
सुग्रीवो विपुलग्रीवः क्रोधमाहारयद्भृशम्॥', 'vicārya sarvato dṛṣṭiṃ kānane kānanapriyaḥ
sugrīvo vipulagrīvaḥ krodham āhārayad bhṛśam', null, 4014002),
('ramayana-4-14-3', 3, 'Kishkindha Kanda, Sarga 14, Verse 3', 'ततः स निनदं घोरं कृत्वा युद्धाय चाह्वयत्।
परिवारैः परिवृतो नादैर्भिन्दन्निवाम्बरम्॥', 'tataḥ sa ninadaṃ ghoraṃ kṛtvā yuddhāya cāhvayat
parivāraiḥ parivṛto nādair bhindann ivāmbaram', null, 4014003),
('ramayana-4-14-4', 4, 'Kishkindha Kanda, Sarga 14, Verse 4', 'अथ बालार्कसदृशो दृप्तसिंहगतिस्तदा।
दृष्ट्वा रामं क्रियादक्षं सुग्रीवो वाक्यमब्रवीत्॥', 'atha bālārkasadṛśo dṛptasiṃhagatis tadā
dṛṣṭvā rāmaṃ kriyādakṣaṃ sugrīvo vākyam abravīt', null, 4014004),
('ramayana-4-14-5', 5, 'Kishkindha Kanda, Sarga 14, Verse 5', 'हरिवागुरया व्याप्तं तप्तकाञ्चनतोरणाम्।
प्राप्ताः स्म ध्वजयन्त्राढ्यां किष्किन्धां वालिनः पुरीम्॥', 'harivāgurayā vyāptaṃ taptakāñcanatoraṇām
prāptāḥ sma dhvajayantrāḍhyāṃ kiṣkindhāṃ vālinaḥ purīm', null, 4014005),
('ramayana-4-14-6', 6, 'Kishkindha Kanda, Sarga 14, Verse 6', 'प्रतिज्ञा या त्वया वीर कृता वालिवधे पुरा।
सफलां तां कुरु क्षिप्रं लतां काल इवागतः॥', 'pratijñā yā tvayā vīra kṛtā vālivadhe purā
saphalāṃ tāṃ kuru kṣipraṃ latāṃ kāla ivāgataḥ', null, 4014006),
('ramayana-4-14-7', 7, 'Kishkindha Kanda, Sarga 14, Verse 7', 'एवमुक्तस्तु धर्मात्मा सुग्रीवेण स राघवः।
तमथोवाच सुग्रीवं वचनं शत्रुसूदनः॥', 'evam uktas tu dharmātmā sugrīveṇa sa rāghavaḥ
tam athovāca sugrīvaṃ vacanaṃ śatrusūdanaḥ', null, 4014007),
('ramayana-4-14-8', 8, 'Kishkindha Kanda, Sarga 14, Verse 8', 'कृताभिज्ञान चिह्नस्त्वमनया गजसाह्वया।
विपरीत इवाकाशे सूर्यो नक्षत्र मालया॥', 'kṛtābhijñāna cihnas tvam anayā gajasāhvayā
viparīta ivākāśe sūryo nakṣatra mālayā', null, 4014008),
('ramayana-4-14-9', 9, 'Kishkindha Kanda, Sarga 14, Verse 9', 'अद्य वालिसमुत्थं ते भयं वैरं च वानर।
एकेनाहं प्रमोक्ष्यामि बाणमोक्षेण संयुगे॥', 'adya vālisamutthaṃ te bhayaṃ vairaṃ ca vānara
ekenāhaṃ pramokṣyāmi bāṇamokṣeṇa saṃyuge', null, 4014009),
('ramayana-4-14-10', 10, 'Kishkindha Kanda, Sarga 14, Verse 10', 'मम दर्शय सुग्रीववैरिणं भ्रातृरूपिणम्।
वाली विनिहतो यावद्वने पांसुषु वेष्टते॥', 'mama darśaya sugrīvavairiṇaṃ bhrātṛrūpiṇam
vālī vinihato yāvad vane pāṃsuṣu veṣṭate', null, 4014010),
('ramayana-4-14-11', 11, 'Kishkindha Kanda, Sarga 14, Verse 11', 'यदि दृष्टिपथं प्राप्तो जीवन्स विनिवर्तते।
ततो दोषेण मा गच्छेत्सद्यो गर्हेच्च मा भवान्॥', 'yadi dṛṣṭipathaṃ prāpto jīvan sa vinivartate
tato doṣeṇa mā gacchet sadyo garhec ca mā bhavān', null, 4014011),
('ramayana-4-14-12', 12, 'Kishkindha Kanda, Sarga 14, Verse 12', 'प्रत्यक्षं सप्त ते साला मया बाणेन दारिताः।
ततो वेत्सि बलेनाद्य बालिनं निहतं मया॥', 'pratyakṣaṃ sapta te sālā mayā bāṇena dāritāḥ
tato vetsi balenādya bālinaṃ nihataṃ mayā', null, 4014012),
('ramayana-4-14-13', 13, 'Kishkindha Kanda, Sarga 14, Verse 13', 'अनृतं नोक्तपूर्वं मे वीर कृच्छ्रेऽपि तिष्ठता।
धर्मलोभपरीतेन न च वक्ष्ये कथं चन॥', 'anṛtaṃ noktapūrvaṃ me vīra kṛcchre ''pi tiṣṭhatā
dharmalobhaparītena na ca vakṣye kathaṃ cana', null, 4014013),
('ramayana-4-14-14', 14, 'Kishkindha Kanda, Sarga 14, Verse 14', 'सफलां च करिष्यामि प्रतिज्ञां जहि संभ्रमम्।
प्रसूतं कलमं क्षेत्रे वर्षेणेव शतक्रतुः॥', 'saphalāṃ ca kariṣyāmi pratijñāṃ jahi saṃbhramam
prasūtaṃ kalamaṃ kṣetre varṣeṇeva śatakratuḥ', null, 4014014),
('ramayana-4-14-15', 15, 'Kishkindha Kanda, Sarga 14, Verse 15', 'तदाह्वाननिमित्तं त्वं वालिनो हेममालिनः।
सुग्रीव कुरु तं शब्दं निष्पतेद्येन वानरः॥', 'tadāhvānanimittaṃ tvaṃ vālino hemamālinaḥ
sugrīva kuru taṃ śabdaṃ niṣpated yena vānaraḥ', null, 4014015),
('ramayana-4-14-16', 16, 'Kishkindha Kanda, Sarga 14, Verse 16', 'जितकाशी जयश्लाघी त्वया चाधर्षितः पुरात्।
निष्पतिष्यत्यसंगेन वाली स प्रियसंयुगः॥', 'jitakāśī jayaślāghī tvayā cādharṣitaḥ purāt
niṣpatiṣyaty asaṃgena vālī sa priyasaṃyugaḥ', null, 4014016),
('ramayana-4-14-17', 17, 'Kishkindha Kanda, Sarga 14, Verse 17', 'रिपूणां धर्षणं शूरा मर्षयन्ति न संयुगे।
जानन्तस्तु स्वकं वीर्यं स्त्रीसमक्षं विशेषतः॥', 'ripūṇāṃ dharṣaṇaṃ śūrā marṣayanti na saṃyuge
jānantas tu svakaṃ vīryaṃ strīsamakṣaṃ viśeṣataḥ', null, 4014017),
('ramayana-4-14-18', 18, 'Kishkindha Kanda, Sarga 14, Verse 18', 'स तु रामवचः श्रुत्वा सुग्रीवो हेमपिङ्गलः।
ननर्द क्रूरनादेन विनिर्भिन्दन्निवाम्बरम्॥', 'sa tu rāmavacaḥ śrutvā sugrīvo hemapiṅgalaḥ
nanarda krūranādena vinirbhindann ivāmbaram', null, 4014018),
('ramayana-4-14-19', 19, 'Kishkindha Kanda, Sarga 14, Verse 19', 'तस्य शब्देन वित्रस्ता गावो यान्ति हतप्रभाः।
राजदोषपरामृष्टाः कुलस्त्रिय इवाकुलाः॥', 'tasya śabdena vitrastā gāvo yānti hataprabhāḥ
rājadoṣaparāmṛṣṭāḥ kulastriya ivākulāḥ', null, 4014019),
('ramayana-4-14-20', 20, 'Kishkindha Kanda, Sarga 14, Verse 20', 'द्रवन्ति च मृगाः शीघ्रं भग्ना इव रणे हयाः।
पतन्ति च खगा भूमौ क्षीणपुण्या इव ग्रहाः॥', 'dravanti ca mṛgāḥ śīghraṃ bhagnā iva raṇe hayāḥ
patanti ca khagā bhūmau kṣīṇapuṇyā iva grahāḥ', null, 4014020),
('ramayana-4-14-21', 21, 'Kishkindha Kanda, Sarga 14, Verse 21', 'ततः स जीमूतगणप्रणादो नादं व्यमुञ्चत्त्वरया प्रतीतः।
सूर्यात्मजः शौर्यविवृद्धतेजाः सरित्पतिर्वानिलचञ्चलोर्मिः॥', 'tataḥ sa jīmūtagaṇapraṇādo nādaṃ vyamuñcat tvarayā pratītaḥ
sūryātmajaḥ śauryavivṛddhatejāḥ saritpatir vānilacañcalormiḥ', null, 4014021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 15 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-15-1', 1, 'Kishkindha Kanda, Sarga 15, Verse 1', 'अथ तस्य निनादं तं सुग्रीवस्य महात्मनः।
शुश्रावान्तःपुरगतो वाली भ्रातुरमर्षणः॥', 'atha tasya ninādaṃ taṃ sugrīvasya mahātmanaḥ
śuśrāvāntaḥpuragato vālī bhrātur amarṣaṇaḥ', null, 4015001),
('ramayana-4-15-2', 2, 'Kishkindha Kanda, Sarga 15, Verse 2', 'श्रुत्वा तु तस्य निनदं सर्वभूतप्रकम्पनम्।
मदश्चैकपदे नष्टः क्रोधश्चापतितो महान्॥', 'śrutvā tu tasya ninadaṃ sarvabhūtaprakampanam
madaś caikapade naṣṭaḥ krodhaś cāpatito mahān', null, 4015002),
('ramayana-4-15-3', 3, 'Kishkindha Kanda, Sarga 15, Verse 3', 'स तु रोषपरीताङ्गो वाली संध्यातपप्रभः।
उपरक्त इवादित्यः सद्यो निष्प्रभतां गतः॥', 'sa tu roṣaparītāṅgo vālī saṃdhyātapaprabhaḥ
uparakta ivādityaḥ sadyo niṣprabhatāṃ gataḥ', null, 4015003),
('ramayana-4-15-4', 4, 'Kishkindha Kanda, Sarga 15, Verse 4', 'वाली दंष्ट्रा करालस्तु क्रोधाद्दीप्ताग्निसंनिभः।
भात्युत्पतितपद्माभः समृणाल इव ह्रदः॥', 'vālī daṃṣṭrā karālas tu krodhād dīptāgnisaṃnibhaḥ
bhāty utpatitapadmābhaḥ samṛṇāla iva hradaḥ', null, 4015004),
('ramayana-4-15-5', 5, 'Kishkindha Kanda, Sarga 15, Verse 5', 'शब्दं दुर्मर्षणं श्रुत्वा निष्पपात ततो हरिः।
वेगेन चरणन्यासैर्दारयन्निव मेदिनीम्॥', 'śabdaṃ durmarṣaṇaṃ śrutvā niṣpapāta tato hariḥ
vegena caraṇanyāsair dārayann iva medinīm', null, 4015005),
('ramayana-4-15-6', 6, 'Kishkindha Kanda, Sarga 15, Verse 6', 'तं तु तारा परिष्वज्य स्नेहाद्दर्शितसौहृदा।
उवाच त्रस्तसंभ्रान्ता हितोदर्कमिदं वचः॥', 'taṃ tu tārā pariṣvajya snehād darśitasauhṛdā
uvāca trastasaṃbhrāntā hitodarkam idaṃ vacaḥ', null, 4015006),
('ramayana-4-15-7', 7, 'Kishkindha Kanda, Sarga 15, Verse 7', 'साधु क्रोधमिमं वीर नदी वेगमिवागतम्।
शयनादुत्थितः काल्यं त्यज भुक्तामिव स्रजम्॥', 'sādhu krodham imaṃ vīra nadī vegam ivāgatam
śayanād utthitaḥ kālyaṃ tyaja bhuktām iva srajam', null, 4015007),
('ramayana-4-15-8', 8, 'Kishkindha Kanda, Sarga 15, Verse 8', 'सहसा तव निष्क्रामो मम तावन्न रोचते।
श्रूयतामभिधास्यामि यन्निमित्तं निवार्यसे॥', 'sahasā tava niṣkrāmo mama tāvan na rocate
śrūyatām abhidhāsyāmi yannimittaṃ nivāryase', null, 4015008),
('ramayana-4-15-9', 9, 'Kishkindha Kanda, Sarga 15, Verse 9', 'पूर्वमापतितः क्रोधात्स त्वामाह्वयते युधि।
निष्पत्य च निरस्तस्ते हन्यमानो दिशो गतः॥', 'pūrvam āpatitaḥ krodhāt sa tvām āhvayate yudhi
niṣpatya ca nirastas te hanyamāno diśo gataḥ', null, 4015009),
('ramayana-4-15-10', 10, 'Kishkindha Kanda, Sarga 15, Verse 10', 'त्वया तस्य निरस्तस्य पीडितस्य विशेषतः।
इहैत्य पुनराह्वानं शङ्कां जनयतीव मे॥', 'tvayā tasya nirastasya pīḍitasya viśeṣataḥ
ihaitya punar āhvānaṃ śaṅkāṃ janayatīva me', null, 4015010),
('ramayana-4-15-11', 11, 'Kishkindha Kanda, Sarga 15, Verse 11', 'दर्पश्च व्यवसायश्च यादृशस्तस्य नर्दतः।
निनादस्य च संरम्भो नैतदल्पं हि कारणम्॥', 'darpaś ca vyavasāyaś ca yādṛśas tasya nardataḥ
ninādasya ca saṃrambho naitad alpaṃ hi kāraṇam', null, 4015011),
('ramayana-4-15-12', 12, 'Kishkindha Kanda, Sarga 15, Verse 12', 'नासहायमहं मन्ये सुग्रीवं तमिहागतम्।
अवष्टब्धसहायश्च यमाश्रित्यैष गर्जति॥', 'nāsahāyam ahaṃ manye sugrīvaṃ tam ihāgatam
avaṣṭabdhasahāyaś ca yam āśrityaiṣa garjati', null, 4015012),
('ramayana-4-15-13', 13, 'Kishkindha Kanda, Sarga 15, Verse 13', 'प्रकृत्या निपुणश्चैव बुद्धिमांश्चैव वानरः।
अपरीक्षितवीर्येण सुग्रीवः सह नैष्यति॥', 'prakṛtyā nipuṇaś caiva buddhimāṃś caiva vānaraḥ
aparīkṣitavīryeṇa sugrīvaḥ saha naiṣyati', null, 4015013),
('ramayana-4-15-14', 14, 'Kishkindha Kanda, Sarga 15, Verse 14', 'पूर्वमेव मया वीर श्रुतं कथयतो वचः।
अङ्गदस्य कुमारस्य वक्ष्यामि त्वा हितं वचः॥', 'pūrvam eva mayā vīra śrutaṃ kathayato vacaḥ
aṅgadasya kumārasya vakṣyāmi tvā hitaṃ vacaḥ', null, 4015014),
('ramayana-4-15-15', 15, 'Kishkindha Kanda, Sarga 15, Verse 15', 'तव भ्रातुर्हि विख्यातः सहायो रणकर्कशः।
रामः परबलामर्दी युगान्ताग्निरिवोत्थितः॥', 'tava bhrātur hi vikhyātaḥ sahāyo raṇakarkaśaḥ
rāmaḥ parabalāmardī yugāntāgnir ivotthitaḥ', null, 4015015),
('ramayana-4-15-16', 16, 'Kishkindha Kanda, Sarga 15, Verse 16', 'निवासवृक्षः साधूनामापन्नानां परा गतिः।
आर्तानां संश्रयश्चैव यशसश्चैकभाजनम्॥', 'nivāsavṛkṣaḥ sādhūnām āpannānāṃ parā gatiḥ
ārtānāṃ saṃśrayaś caiva yaśasaś caikabhājanam', null, 4015016),
('ramayana-4-15-17', 17, 'Kishkindha Kanda, Sarga 15, Verse 17', 'ज्ञानविज्ञानसंपन्नो निदेशो निरतः पितुः।
धातूनामिव शैलेन्द्रो गुणानामाकरो महान्॥', 'jñānavijñānasaṃpanno nideśo nirataḥ pituḥ
dhātūnām iva śailendro guṇānām ākaro mahān', null, 4015017),
('ramayana-4-15-18', 18, 'Kishkindha Kanda, Sarga 15, Verse 18', 'तत्क्षमं न विरोधस्ते सह तेन महात्मना।
दुर्जयेनाप्रमेयेन रामेण रणकर्मसु॥', 'tatkṣamaṃ na virodhas te saha tena mahātmanā
durjayenāprameyena rāmeṇa raṇakarmasu', null, 4015018),
('ramayana-4-15-19', 19, 'Kishkindha Kanda, Sarga 15, Verse 19', 'शूर वक्ष्यामि ते किं चिन्न चेच्छाम्यभ्यसूयितुम्।
श्रूयतां क्रियतां चैव तव वक्ष्यामि यद्धितम्॥', 'śūra vakṣyāmi te kiṃ cin na cecchāmy abhyasūyitum
śrūyatāṃ kriyatāṃ caiva tava vakṣyāmi yad dhitam', null, 4015019),
('ramayana-4-15-20', 20, 'Kishkindha Kanda, Sarga 15, Verse 20', 'यौवराज्येन सुग्रीवं तूर्णं साध्वभिषेचय।
विग्रहं मा कृथा वीर भ्रात्रा राजन्बलीयसा॥', 'yauvarājyena sugrīvaṃ tūrṇaṃ sādhv abhiṣecaya
vigrahaṃ mā kṛthā vīra bhrātrā rājan balīyasā', null, 4015020),
('ramayana-4-15-21', 21, 'Kishkindha Kanda, Sarga 15, Verse 21', 'अहं हि ते क्षमं मन्ये तव रामेण सौहृदम्।
सुग्रीवेण च संप्रीतिं वैरमुत्सृज्य दूरतः॥', 'ahaṃ hi te kṣamaṃ manye tava rāmeṇa sauhṛdam
sugrīveṇa ca saṃprītiṃ vairam utsṛjya dūrataḥ', null, 4015021),
('ramayana-4-15-22', 22, 'Kishkindha Kanda, Sarga 15, Verse 22', 'लालनीयो हि ते भ्राता यवीयानेष वानरः।
तत्र वा सन्निहस्थो वा सर्वथा बन्धुरेव ते॥', 'lālanīyo hi te bhrātā yavīyān eṣa vānaraḥ
tatra vā sann ihastho vā sarvathā bandhur eva te', null, 4015022),
('ramayana-4-15-23', 23, 'Kishkindha Kanda, Sarga 15, Verse 23', 'यदि ते मत्प्रियं कार्यं यदि चावैषि मां हिताम्।
याच्यमानः प्रयत्नेन साधु वाक्यं कुरुष्व मे॥', 'yadi te matpriyaṃ kāryaṃ yadi cāvaiṣi māṃ hitām
yācyamānaḥ prayatnena sādhu vākyaṃ kuruṣva me', null, 4015023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 16 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-16-1', 1, 'Kishkindha Kanda, Sarga 16, Verse 1', 'तामेवं ब्रुवतीं तारां ताराधिपनिभाननाम्।
वाली निर्भर्त्सयामास वचनं चेदमब्रवीत्॥', 'tām evaṃ bruvatīṃ tārāṃ tārādhipanibhānanām
vālī nirbhartsayām āsa vacanaṃ cedam abravīt', null, 4016001),
('ramayana-4-16-2', 2, 'Kishkindha Kanda, Sarga 16, Verse 2', 'गर्जतोऽस्य च संरम्भं भ्रातुः शत्रोर्विशेषतः।
मर्षयिष्याम्यहं केन कारणेन वरानने॥', 'garjato ''sya ca saṃrambhaṃ bhrātuḥ śatror viśeṣataḥ
marṣayiṣyāmy ahaṃ kena kāraṇena varānane', null, 4016002),
('ramayana-4-16-3', 3, 'Kishkindha Kanda, Sarga 16, Verse 3', 'अधर्षितानां शूराणां समरेष्वनिवर्तिनाम्।
धर्षणामर्षणं भीरु मरणादतिरिच्यते॥', 'adharṣitānāṃ śūrāṇāṃ samareṣv anivartinām
dharṣaṇāmarṣaṇaṃ bhīru maraṇād atiricyate', null, 4016003),
('ramayana-4-16-4', 4, 'Kishkindha Kanda, Sarga 16, Verse 4', 'सोढुं न च समर्थोऽहं युद्धकामस्य संयुगे।
सुग्रीवस्य च संरम्भं हीनग्रीवस्य गर्जतः॥', 'soḍhuṃ na ca samartho ''haṃ yuddhakāmasya saṃyuge
sugrīvasya ca saṃrambhaṃ hīnagrīvasya garjataḥ', null, 4016004),
('ramayana-4-16-5', 5, 'Kishkindha Kanda, Sarga 16, Verse 5', 'न च कार्यो विषादस्ते राघवं प्रति मत्कृते।
धर्मज्ञश्च कृतज्ञश्च कथं पापं करिष्यति॥', 'na ca kāryo viṣādas te rāghavaṃ prati matkṛte
dharmajñaś ca kṛtajñaś ca kathaṃ pāpaṃ kariṣyati', null, 4016005),
('ramayana-4-16-6', 6, 'Kishkindha Kanda, Sarga 16, Verse 6', 'निवर्तस्व सह स्त्रीभिः कथं भूयोऽनुगच्छसि।
सौहृदं दर्शितं तारे मयि भक्तिः कृता त्वया॥', 'nivartasva saha strībhiḥ kathaṃ bhūyo ''nugacchasi
sauhṛdaṃ darśitaṃ tāre mayi bhaktiḥ kṛtā tvayā', null, 4016006),
('ramayana-4-16-7', 7, 'Kishkindha Kanda, Sarga 16, Verse 7', 'प्रतियोत्स्याम्यहं गत्वा सुग्रीवं जहि संभ्रमम्।
दर्पं चास्य विनेष्यामि न च प्राणैर्विमोक्ष्यते॥', 'pratiyotsyāmy ahaṃ gatvā sugrīvaṃ jahi saṃbhramam
darpaṃ cāsya vineṣyāmi na ca prāṇair vimokṣyate', null, 4016007),
('ramayana-4-16-8', 8, 'Kishkindha Kanda, Sarga 16, Verse 8', 'शापितासि मम प्राणैर्निवर्तस्व जयेन च।
अहं जित्वा निवर्तिष्ये तमलं भ्रातरं रणे॥', 'śāpitāsi mama prāṇair nivartasva jayena ca
ahaṃ jitvā nivartiṣye tam alaṃ bhrātaraṃ raṇe', null, 4016008),
('ramayana-4-16-9', 9, 'Kishkindha Kanda, Sarga 16, Verse 9', 'तं तु तारा परिष्वज्य वालिनं प्रियवादिनी।
चकार रुदती मन्दं दक्षिणा सा प्रदक्षिणम्॥', 'taṃ tu tārā pariṣvajya vālinaṃ priyavādinī
cakāra rudatī mandaṃ dakṣiṇā sā pradakṣiṇam', null, 4016009),
('ramayana-4-16-10', 10, 'Kishkindha Kanda, Sarga 16, Verse 10', 'ततः स्वस्त्ययनं कृत्वा मन्त्रवद्विजयैषिणी।
अन्तःपुरं सह स्त्रीभिः प्रविष्टा शोकमोहिता॥', 'tataḥ svastyayanaṃ kṛtvā mantravad vijayaiṣiṇī
antaḥpuraṃ saha strībhiḥ praviṣṭā śokamohitā', null, 4016010),
('ramayana-4-16-11', 11, 'Kishkindha Kanda, Sarga 16, Verse 11', 'प्रविष्टायां तु तारायां सह स्त्रीभिः स्वमालयम्।
नगरान्निर्ययौ क्रुद्धो महासर्प इव श्वसन्॥', 'praviṣṭāyāṃ tu tārāyāṃ saha strībhiḥ svam ālayam
nagarān niryayau kruddho mahāsarpa iva śvasan', null, 4016011),
('ramayana-4-16-12', 12, 'Kishkindha Kanda, Sarga 16, Verse 12', 'स निःश्वस्य महावेगो वाली परमरोषणः।
सर्वतश्चारयन्दृष्टिं शत्रुदर्शनकाङ्क्षया॥', 'sa niḥśvasya mahāvego vālī paramaroṣaṇaḥ
sarvataś cārayan dṛṣṭiṃ śatrudarśanakāṅkṣayā', null, 4016012),
('ramayana-4-16-13', 13, 'Kishkindha Kanda, Sarga 16, Verse 13', 'स ददर्श ततः श्रीमान्सुग्रीवं हेमपिङ्गलम्।
सुसंवीतमवष्टब्धं दीप्यमानमिवानलम्॥', 'sa dadarśa tataḥ śrīmān sugrīvaṃ hemapiṅgalam
susaṃvītam avaṣṭabdhaṃ dīpyamānam ivānalam', null, 4016013),
('ramayana-4-16-14', 14, 'Kishkindha Kanda, Sarga 16, Verse 14', 'स तं दृष्ट्वा महावीर्यं सुग्रीवं पर्यवस्थितम्।
गाढं परिदधे वासो वाली परमरोषणः॥', 'sa taṃ dṛṣṭvā mahāvīryaṃ sugrīvaṃ paryavasthitam
gāḍhaṃ paridadhe vāso vālī paramaroṣaṇaḥ', null, 4016014),
('ramayana-4-16-15', 15, 'Kishkindha Kanda, Sarga 16, Verse 15', 'स वाली गाढसंवीतो मुष्टिमुद्यम्य वीर्यवान्।
सुग्रीवमेवाभिमुखो ययौ योद्धुं कृतक्षणः॥', 'sa vālī gāḍhasaṃvīto muṣṭim udyamya vīryavān
sugrīvam evābhimukho yayau yoddhuṃ kṛtakṣaṇaḥ', null, 4016015),
('ramayana-4-16-16', 16, 'Kishkindha Kanda, Sarga 16, Verse 16', 'श्लिष्टमुष्टिं समुद्यम्य संरब्धतरमागतः।
सुग्रीवोऽपि समुद्दिश्य वालिनं हेममालिनम्॥', 'śliṣṭamuṣṭiṃ samudyamya saṃrabdhataram āgataḥ
sugrīvo ''pi samuddiśya vālinaṃ hemamālinam', null, 4016016),
('ramayana-4-16-17', 17, 'Kishkindha Kanda, Sarga 16, Verse 17', 'तं वाली क्रोधताम्राक्षः सुग्रीवं रणपण्डितम्।
आपतन्तं महावेगमिदं वचनमब्रवीत्॥', 'taṃ vālī krodhatāmrākṣaḥ sugrīvaṃ raṇapaṇḍitam
āpatantaṃ mahāvegam idaṃ vacanam abravīt', null, 4016017),
('ramayana-4-16-18', 18, 'Kishkindha Kanda, Sarga 16, Verse 18', 'एष मुष्टिर्मया बद्धो गाढः सुनिहिताङ्गुलिः।
मया वेगविमुक्तस्ते प्राणानादाय यास्यति॥', 'eṣa muṣṭir mayā baddho gāḍhaḥ sunihitāṅguliḥ
mayā vegavimuktas te prāṇān ādāya yāsyati', null, 4016018),
('ramayana-4-16-19', 19, 'Kishkindha Kanda, Sarga 16, Verse 19', 'एवमुक्तस्तु सुग्रीवः क्रुद्धो वालिनमब्रवीत्।
तवैव च हरन्प्राणान्मुष्टिः पततु मूर्धनि॥', 'evam uktas tu sugrīvaḥ kruddho vālinam abravīt
tavaiva ca haran prāṇān muṣṭiḥ patatu mūrdhani', null, 4016019),
('ramayana-4-16-20', 20, 'Kishkindha Kanda, Sarga 16, Verse 20', 'ताडितस्तेन संक्रुद्धः समभिक्रम्य वेगतः।
अभवच्छोणितोद्गारी सोत्पीड इव पर्वतः॥', 'tāḍitas tena saṃkruddhaḥ samabhikramya vegataḥ
abhavac choṇitodgārī sotpīḍa iva parvataḥ', null, 4016020),
('ramayana-4-16-21', 21, 'Kishkindha Kanda, Sarga 16, Verse 21', 'सुग्रीवेण तु निःसंगं सालमुत्पाट्य तेजसा।
गात्रेष्वभिहतो वाली वज्रेणेव महागिरिः॥', 'sugrīveṇa tu niḥsaṃgaṃ sālam utpāṭya tejasā
gātreṣv abhihato vālī vajreṇeva mahāgiriḥ', null, 4016021),
('ramayana-4-16-22', 22, 'Kishkindha Kanda, Sarga 16, Verse 22', 'स तु वाली प्रचरितः सालताडनविह्वलः।
गुरुभारसमाक्रान्ता सागरे नौरिवाभवत्॥', 'sa tu vālī pracaritaḥ sālatāḍanavihvalaḥ
gurubhārasamākrāntā sāgare naur ivābhavat', null, 4016022),
('ramayana-4-16-23', 23, 'Kishkindha Kanda, Sarga 16, Verse 23', 'तौ भीमबलविक्रान्तौ सुपर्णसमवेगिनौ।
प्रवृद्धौ घोरवपुषौ चन्द्रसूर्याविवाम्बरे॥', 'tau bhīmabalavikrāntau suparṇasamaveginau
pravṛddhau ghoravapuṣau candrasūryāv ivāmbare', null, 4016023),
('ramayana-4-16-24', 24, 'Kishkindha Kanda, Sarga 16, Verse 24', 'वालिना भग्नदर्पस्तु सुग्रीवो मन्दविक्रमः।
वालिनं प्रति सामर्षो दर्शयामास लाघवम्॥', 'vālinā bhagnadarpas tu sugrīvo mandavikramaḥ
vālinaṃ prati sāmarṣo darśayām āsa lāghavam', null, 4016024),
('ramayana-4-16-25', 25, 'Kishkindha Kanda, Sarga 16, Verse 25', 'ततो धनुषि संधाय शरमाशीविषोपमम्।
राघवेण महाबाणो वालिवक्षसि पातितः॥', 'tato dhanuṣi saṃdhāya śaram āśīviṣopamam
rāghaveṇa mahābāṇo vālivakṣasi pātitaḥ', null, 4016025),
('ramayana-4-16-26', 26, 'Kishkindha Kanda, Sarga 16, Verse 26', 'वेगेनाभिहतो वाली निपपात महीतले॥', 'vegenābhihato vālī nipapāta mahītale', null, 4016026),
('ramayana-4-16-27', 27, 'Kishkindha Kanda, Sarga 16, Verse 27', 'अथोक्षितः शोणिततोयविस्रवैः सुपुष्पिताशोक इवानिलोद्धतः।
विचेतनो वासवसूनुराहवे प्रभ्रंशितेन्द्रध्वजवत्क्षितिं गतः॥', 'athokṣitaḥ śoṇitatoyavisravaiḥ supuṣpitāśoka ivāniloddhataḥ
vicetano vāsavasūnur āhave prabhraṃśitendradhvajavat kṣitiṃ gataḥ', null, 4016027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 17 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-17-1', 1, 'Kishkindha Kanda, Sarga 17, Verse 1', 'ततः शरेणाभिहतो रामेण रणकर्कशः।
पपात सहसा वाली निकृत्त इव पादपः॥', 'tataḥ śareṇābhihato rāmeṇa raṇakarkaśaḥ
papāta sahasā vālī nikṛtta iva pādapaḥ', null, 4017001),
('ramayana-4-17-2', 2, 'Kishkindha Kanda, Sarga 17, Verse 2', 'स भूमौ न्यस्तसर्वाङ्गस्तप्तकाञ्चनभूषणः।
अपतद्देवराजस्य मुक्तरश्मिरिव ध्वजः॥', 'sa bhūmau nyastasarvāṅgas taptakāñcanabhūṣaṇaḥ
apatad devarājasya muktaraśmir iva dhvajaḥ', null, 4017002),
('ramayana-4-17-3', 3, 'Kishkindha Kanda, Sarga 17, Verse 3', 'तस्मिन्निपतिते भूमौ हर्यृषाणां गणेश्वरे।
नष्टचन्द्रमिव व्योम न व्यराजत भूतलम्॥', 'tasmin nipatite bhūmau haryṛṣāṇāṃ gaṇeśvare
naṣṭacandram iva vyoma na vyarājata bhūtalam', null, 4017003),
('ramayana-4-17-4', 4, 'Kishkindha Kanda, Sarga 17, Verse 4', 'भूमौ निपतितस्यापि तस्य देहं महात्मनः।
न श्रीर्जहाति न प्राणा न तेजो न पराक्रमः॥', 'bhūmau nipatitasyāpi tasya dehaṃ mahātmanaḥ
na śrīr jahāti na prāṇā na tejo na parākramaḥ', null, 4017004),
('ramayana-4-17-5', 5, 'Kishkindha Kanda, Sarga 17, Verse 5', 'शक्रदत्ता वरा माला काञ्चनी रत्नभूषिता।
दधार हरिमुख्यस्य प्राणांस्तेजः श्रियं च सा॥', 'śakradattā varā mālā kāñcanī ratnabhūṣitā
dadhāra harimukhyasya prāṇāṃs tejaḥ śriyaṃ ca sā', null, 4017005),
('ramayana-4-17-6', 6, 'Kishkindha Kanda, Sarga 17, Verse 6', 'स तया मालया वीरो हैमया हरियूथपः।
संध्यानुगतपर्यन्तः पयोधर इवाभवत्॥', 'sa tayā mālayā vīro haimayā hariyūthapaḥ
saṃdhyānugataparyantaḥ payodhara ivābhavat', null, 4017006),
('ramayana-4-17-7', 7, 'Kishkindha Kanda, Sarga 17, Verse 7', 'तस्य माला च देहश्च मर्मघाती च यः शरः।
त्रिधेव रचिता लक्ष्मीः पतितस्यापि शोभते॥', 'tasya mālā ca dehaś ca marmaghātī ca yaḥ śaraḥ
tridheva racitā lakṣmīḥ patitasyāpi śobhate', null, 4017007),
('ramayana-4-17-8', 8, 'Kishkindha Kanda, Sarga 17, Verse 8', 'तदस्त्रं तस्य वीरस्य स्वर्गमार्गप्रभावनम्।
रामबाणासनक्षिप्तमावहत्परमां गतिम्॥', 'tad astraṃ tasya vīrasya svargamārgaprabhāvanam
rāmabāṇāsanakṣiptam āvahat paramāṃ gatim', null, 4017008),
('ramayana-4-17-9', 9, 'Kishkindha Kanda, Sarga 17, Verse 9', 'तं तथा पतितं संख्ये गतार्चिषमिवानलम्।
ययातिमिव पुण्यान्ते देवलोकात्परिच्युतम्॥', 'taṃ tathā patitaṃ saṃkhye gatārciṣam ivānalam
yayātim iva puṇyānte devalokāt paricyutam', null, 4017009),
('ramayana-4-17-10', 10, 'Kishkindha Kanda, Sarga 17, Verse 10', 'आदित्यमिव कालेन युगान्ते भुवि पातितम्।
महेन्द्रमिव दुर्धर्षं महेन्द्रमिव दुःसहम्॥', 'ādityam iva kālena yugānte bhuvi pātitam
mahendram iva durdharṣaṃ mahendram iva duḥsaham', null, 4017010),
('ramayana-4-17-11', 11, 'Kishkindha Kanda, Sarga 17, Verse 11', 'महेन्द्रपुत्रं पतितं वालिनं हेममालिनम्।
सिंहोरस्कं महाबाहुं दीप्तास्यं हरिलोचनम्।
लक्ष्मणानुगतो रामो ददर्शोपससर्प च॥', 'mahendraputraṃ patitaṃ vālinaṃ hemamālinam
siṃhoraskaṃ mahābāhuṃ dīptāsyaṃ harilocanam
lakṣmaṇānugato rāmo dadarśopasasarpa ca', null, 4017011),
('ramayana-4-17-12', 12, 'Kishkindha Kanda, Sarga 17, Verse 12', 'स दृष्ट्वा राघवं वाली लक्ष्मणं च महाबलम्।
अब्रवीत्प्रश्रितं वाक्यं परुषं धर्मसंहितम्॥', 'sa dṛṣṭvā rāghavaṃ vālī lakṣmaṇaṃ ca mahābalam
abravīt praśritaṃ vākyaṃ paruṣaṃ dharmasaṃhitam', null, 4017012),
('ramayana-4-17-13', 13, 'Kishkindha Kanda, Sarga 17, Verse 13', 'पराङ्मुखवधं कृत्वा को नु प्राप्तस्त्वया गुणः।
यदहं युद्धसंरब्धस्त्वत्कृते निधनं गतः॥', 'parāṅmukhavadhaṃ kṛtvā ko nu prāptas tvayā guṇaḥ
yad ahaṃ yuddhasaṃrabdhas tvatkṛte nidhanaṃ gataḥ', null, 4017013),
('ramayana-4-17-14', 14, 'Kishkindha Kanda, Sarga 17, Verse 14', 'कुलीनः सत्त्वसंपन्नस्तेजस्वी चरितव्रतः।
रामः करुणवेदी च प्रजानां च हिते रतः॥', 'kulīnaḥ sattvasaṃpannas tejasvī caritavrataḥ
rāmaḥ karuṇavedī ca prajānāṃ ca hite rataḥ', null, 4017014),
('ramayana-4-17-15', 15, 'Kishkindha Kanda, Sarga 17, Verse 15', 'सानुक्रोशो महोत्साहः समयज्ञो दृढव्रतः।
इति ते सर्वभूतानि कथयन्ति यशो भुवि॥', 'sānukrośo mahotsāhaḥ samayajño dṛḍhavrataḥ
iti te sarvabhūtāni kathayanti yaśo bhuvi', null, 4017015),
('ramayana-4-17-16', 16, 'Kishkindha Kanda, Sarga 17, Verse 16', 'तान्गुणान्संप्रधार्याहमग्र्यं चाभिजनं तव।
तारया प्रतिषिद्धः सन्सुग्रीवेण समागतः॥', 'tān guṇān saṃpradhāryāham agryaṃ cābhijanaṃ tava
tārayā pratiṣiddhaḥ san sugrīveṇa samāgataḥ', null, 4017016),
('ramayana-4-17-17', 17, 'Kishkindha Kanda, Sarga 17, Verse 17', 'न मामन्येन संरब्धं प्रमत्तं वेद्धुमर्हसि।
इति मे बुद्धिरुत्पन्ना बभूवादर्शने तव॥', 'na mām anyena saṃrabdhaṃ pramattaṃ veddhum arhasi
iti me buddhir utpannā babhūvādarśane tava', null, 4017017),
('ramayana-4-17-18', 18, 'Kishkindha Kanda, Sarga 17, Verse 18', 'न त्वां विनिहतात्मानं धर्मध्वजमधार्मिकम्।
जाने पापसमाचारं तृणैः कूपमिवावृतम्॥', 'na tvāṃ vinihatātmānaṃ dharmadhvajam adhārmikam
jāne pāpasamācāraṃ tṛṇaiḥ kūpam ivāvṛtam', null, 4017018),
('ramayana-4-17-19', 19, 'Kishkindha Kanda, Sarga 17, Verse 19', 'सतां वेषधरं पापं प्रच्छन्नमिव पावकम्।
नाहं त्वामभिजानानि धर्मच्छद्माभिसंवृतम्॥', 'satāṃ veṣadharaṃ pāpaṃ pracchannam iva pāvakam
nāhaṃ tvām abhijānāni dharmacchadmābhisaṃvṛtam', null, 4017019),
('ramayana-4-17-20', 20, 'Kishkindha Kanda, Sarga 17, Verse 20', 'विषये वा पुरे वा ते यदा नापकरोम्यहम्।
न च त्वां प्रतिजानेऽहं कस्मात्त्वं हंस्यकिल्बिषम्॥', 'viṣaye vā pure vā te yadā nāpakaromy aham
na ca tvāṃ pratijāne ''haṃ kasmāt tvaṃ haṃsy akilbiṣam', null, 4017020),
('ramayana-4-17-21', 21, 'Kishkindha Kanda, Sarga 17, Verse 21', 'फलमूलाशनं नित्यं वानरं वनगोचरम्।
मामिहाप्रतियुध्यन्तमन्येन च समागतम्॥', 'phalamūlāśanaṃ nityaṃ vānaraṃ vanagocaram
mām ihāpratiyudhyantam anyena ca samāgatam', null, 4017021),
('ramayana-4-17-22', 22, 'Kishkindha Kanda, Sarga 17, Verse 22', 'त्वं नराधिपतेः पुत्रः प्रतीतः प्रियदर्शनः।
लिङ्गमप्यस्ति ते राजन्दृश्यते धर्मसंहितम्॥', 'tvaṃ narādhipateḥ putraḥ pratītaḥ priyadarśanaḥ
liṅgam apy asti te rājan dṛśyate dharmasaṃhitam', null, 4017022),
('ramayana-4-17-23', 23, 'Kishkindha Kanda, Sarga 17, Verse 23', 'कः क्षत्रियकुले जातः श्रुतवान्नष्टसंशयः।
धर्मलिङ्ग प्रतिच्छन्नः क्रूरं कर्म समाचरेत्॥', 'kaḥ kṣatriyakule jātaḥ śrutavān naṣṭasaṃśayaḥ
dharmaliṅga praticchannaḥ krūraṃ karma samācaret', null, 4017023),
('ramayana-4-17-24', 24, 'Kishkindha Kanda, Sarga 17, Verse 24', 'राम राजकुले जातो धर्मवानिति विश्रुतः।
अभव्यो भव्यरूपेण किमर्थं परिधावसि॥', 'rāma rājakule jāto dharmavān iti viśrutaḥ
abhavyo bhavyarūpeṇa kimarthaṃ paridhāvasi', null, 4017024),
('ramayana-4-17-25', 25, 'Kishkindha Kanda, Sarga 17, Verse 25', 'साम दानं क्षमा धर्मः सत्यं धृतिपराक्रमौ।
पार्थिवानां गुणा राजन्दण्डश्चाप्यपकारिषु॥', 'sāma dānaṃ kṣamā dharmaḥ satyaṃ dhṛtiparākramau
pārthivānāṃ guṇā rājan daṇḍaś cāpy apakāriṣu', null, 4017025),
('ramayana-4-17-26', 26, 'Kishkindha Kanda, Sarga 17, Verse 26', 'वयं वनचरा राम मृगा मूलफलाशनाः।
एषा प्रकृतिरस्माकं पुरुषस्त्वं नरेश्वरः॥', 'vayaṃ vanacarā rāma mṛgā mūlaphalāśanāḥ
eṣā prakṛtir asmākaṃ puruṣas tvaṃ nareśvaraḥ', null, 4017026),
('ramayana-4-17-27', 27, 'Kishkindha Kanda, Sarga 17, Verse 27', 'भूमिर्हिरण्यं रूप्यं च निग्रहे कारणानि च।
तत्र कस्ते वने लोभो मदीयेषु फलेषु वा॥', 'bhūmir hiraṇyaṃ rūpyaṃ ca nigrahe kāraṇāni ca
tatra kas te vane lobho madīyeṣu phaleṣu vā', null, 4017027),
('ramayana-4-17-28', 28, 'Kishkindha Kanda, Sarga 17, Verse 28', 'नयश्च विनयश्चोभौ निग्रहानुग्रहावपि।
राजवृत्तिरसंकीर्णा न नृपाः कामवृत्तयः॥', 'nayaś ca vinayaś cobhau nigrahānugrahāv api
rājavṛttir asaṃkīrṇā na nṛpāḥ kāmavṛttayaḥ', null, 4017028),
('ramayana-4-17-29', 29, 'Kishkindha Kanda, Sarga 17, Verse 29', 'त्वं तु कामप्रधानश्च कोपनश्चानवस्थितः।
राजवृत्तैश्च संकीर्णः शरासनपरायणः॥', 'tvaṃ tu kāmapradhānaś ca kopanaś cānavasthitaḥ
rājavṛttaiś ca saṃkīrṇaḥ śarāsanaparāyaṇaḥ', null, 4017029),
('ramayana-4-17-30', 30, 'Kishkindha Kanda, Sarga 17, Verse 30', 'न तेऽस्त्यपचितिर्धर्मे नार्थे बुद्धिरवस्थिता।
इन्द्रियैः कामवृत्तः सन्कृष्यसे मनुजेश्वर॥', 'na te ''sty apacitir dharme nārthe buddhir avasthitā
indriyaiḥ kāmavṛttaḥ san kṛṣyase manujeśvara', null, 4017030),
('ramayana-4-17-31', 31, 'Kishkindha Kanda, Sarga 17, Verse 31', 'हत्वा बाणेन काकुत्स्थ मामिहानपराधिनम्।
किं वक्ष्यसि सतां मध्ये कर्म कृत्वा जुगुप्सितम्॥', 'hatvā bāṇena kākutstha mām ihānaparādhinam
kiṃ vakṣyasi satāṃ madhye karma kṛtvā jugupsitam', null, 4017031),
('ramayana-4-17-32', 32, 'Kishkindha Kanda, Sarga 17, Verse 32', 'राजहा ब्रह्महा गोघ्नश्चोरः प्राणिवधे रतः।
नास्तिकः परिवेत्ता च सर्वे निरयगामिनः॥', 'rājahā brahmahā goghnaś coraḥ prāṇivadhe rataḥ
nāstikaḥ parivettā ca sarve nirayagāminaḥ', null, 4017032),
('ramayana-4-17-33', 33, 'Kishkindha Kanda, Sarga 17, Verse 33', 'अधार्यं चर्म मे सद्भी रोमाण्यस्थि च वर्जितम्।
अभक्ष्याणि च मांसानि त्वद्विधैर्धर्मचारिभिः॥', 'adhāryaṃ carma me sadbhī romāṇy asthi ca varjitam
abhakṣyāṇi ca māṃsāni tvadvidhair dharmacāribhiḥ', null, 4017033),
('ramayana-4-17-34', 34, 'Kishkindha Kanda, Sarga 17, Verse 34', 'पञ्च पञ्चनखा भक्ष्या ब्रह्मक्षत्रेण राघव।
शल्यकः श्वाविधो गोधा शशः कूर्मश्च पञ्चमः॥', 'pañca pañcanakhā bhakṣyā brahmakṣatreṇa rāghava
śalyakaḥ śvāvidho godhā śaśaḥ kūrmaś ca pañcamaḥ', null, 4017034),
('ramayana-4-17-35', 35, 'Kishkindha Kanda, Sarga 17, Verse 35', 'चर्म चास्थि च मे राजन्न स्पृशन्ति मनीषिणः।
अभक्ष्याणि च मांसानि सोऽहं पञ्चनखो हतः॥', 'carma cāsthi ca me rājan na spṛśanti manīṣiṇaḥ
abhakṣyāṇi ca māṃsāni so ''haṃ pañcanakho hataḥ', null, 4017035),
('ramayana-4-17-36', 36, 'Kishkindha Kanda, Sarga 17, Verse 36', 'त्वया नाथेन काकुत्स्थ न सनाथा वसुंधरा।
प्रमदा शीलसंपन्ना धूर्तेन पतिता यथा॥', 'tvayā nāthena kākutstha na sanāthā vasuṃdharā
pramadā śīlasaṃpannā dhūrtena patitā yathā', null, 4017036),
('ramayana-4-17-37', 37, 'Kishkindha Kanda, Sarga 17, Verse 37', 'शठो नैकृतिकः क्षुद्रो मिथ्या प्रश्रितमानसः।
कथं दशरथेन त्वं जातः पापो महात्मना॥', 'śaṭho naikṛtikaḥ kṣudro mithyā praśritamānasaḥ
kathaṃ daśarathena tvaṃ jātaḥ pāpo mahātmanā', null, 4017037),
('ramayana-4-17-38', 38, 'Kishkindha Kanda, Sarga 17, Verse 38', 'छिन्नचारित्र्यकक्ष्येण सतां धर्मातिवर्तिना।
त्यक्तधर्माङ्कुशेनाहं निहतो रामहस्तिना॥', 'chinnacāritryakakṣyeṇa satāṃ dharmātivartinā
tyaktadharmāṅkuśenāhaṃ nihato rāmahastinā', null, 4017038),
('ramayana-4-17-39', 39, 'Kishkindha Kanda, Sarga 17, Verse 39', 'दृश्यमानस्तु युध्येथा मया युधि नृपात्मज।
अद्य वैवस्वतं देवं पश्येस्त्वं निहतो मया॥', 'dṛśyamānas tu yudhyethā mayā yudhi nṛpātmaja
adya vaivasvataṃ devaṃ paśyes tvaṃ nihato mayā', null, 4017039),
('ramayana-4-17-40', 40, 'Kishkindha Kanda, Sarga 17, Verse 40', 'त्वयादृश्येन तु रणे निहतोऽहं दुरासदः।
प्रसुप्तः पन्नगेनेव नरः पानवशं गतः॥', 'tvayādṛśyena tu raṇe nihato ''haṃ durāsadaḥ
prasuptaḥ pannageneva naraḥ pānavaśaṃ gataḥ', null, 4017040),
('ramayana-4-17-41', 41, 'Kishkindha Kanda, Sarga 17, Verse 41', 'सुग्रीवप्रियकामेन यदहं निहतस्त्वया।
कण्ठे बद्ध्वा प्रदद्यां तेऽनिहतं रावणं रणे॥', 'sugrīvapriyakāmena yad ahaṃ nihatas tvayā
kaṇṭhe baddhvā pradadyāṃ te ''nihataṃ rāvaṇaṃ raṇe', null, 4017041),
('ramayana-4-17-42', 42, 'Kishkindha Kanda, Sarga 17, Verse 42', 'न्यस्तां सागरतोये वा पाताले वापि मैथिलीम्।
जानयेयं तवादेशाच्छ्वेतामश्वतरीमिव॥', 'nyastāṃ sāgaratoye vā pātāle vāpi maithilīm
jānayeyaṃ tavādeśāc chvetām aśvatarīm iva', null, 4017042),
('ramayana-4-17-43', 43, 'Kishkindha Kanda, Sarga 17, Verse 43', 'युक्तं यत्प्रप्नुयाद्राज्यं सुग्रीवः स्वर्गते मयि।
अयुक्तं यदधर्मेण त्वयाहं निहतो रणे॥', 'yuktaṃ yat prapnuyād rājyaṃ sugrīvaḥ svargate mayi
ayuktaṃ yad adharmeṇa tvayāhaṃ nihato raṇe', null, 4017043),
('ramayana-4-17-44', 44, 'Kishkindha Kanda, Sarga 17, Verse 44', 'काममेवंविधं लोकः कालेन विनियुज्यते।
क्षमं चेद्भवता प्राप्तमुत्तरं साधु चिन्त्यताम्॥', 'kāmam evaṃvidhaṃ lokaḥ kālena viniyujyate
kṣamaṃ ced bhavatā prāptam uttaraṃ sādhu cintyatām', null, 4017044),
('ramayana-4-17-45', 45, 'Kishkindha Kanda, Sarga 17, Verse 45', 'इत्येवमुक्त्वा परिशुष्कवक्त्रः शराभिघाताद्व्यथितो महात्मा।
समीक्ष्य रामं रविसंनिकाशं तूष्णीं बभूवामरराजसूनुः॥', 'ity evam uktvā pariśuṣkavaktraḥ śarābhighātād vyathito mahātmā
samīkṣya rāmaṃ ravisaṃnikāśaṃ tūṣṇīṃ babhūvāmararājasūnuḥ', null, 4017045)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 18 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-18-1', 1, 'Kishkindha Kanda, Sarga 18, Verse 1', 'इत्युक्तः प्रश्रितं वाक्यं धर्मार्थसहितं हितम्।
परुषं वालिना रामो निहतेन विचेतसा॥', 'ity uktaḥ praśritaṃ vākyaṃ dharmārthasahitaṃ hitam
paruṣaṃ vālinā rāmo nihatena vicetasā', null, 4018001),
('ramayana-4-18-2', 2, 'Kishkindha Kanda, Sarga 18, Verse 2', 'तं निष्प्रभमिवादित्यं मुक्ततोयमिवाम्बुदम्।
उक्तवाक्यं हरिश्रेष्ठमुपशान्तमिवानलम्॥', 'taṃ niṣprabham ivādityaṃ muktatoyam ivāmbudam
uktavākyaṃ hariśreṣṭham upaśāntam ivānalam', null, 4018002),
('ramayana-4-18-3', 3, 'Kishkindha Kanda, Sarga 18, Verse 3', 'धर्मार्थगुणसंपन्नं हरीश्वरमनुत्तमम्।
अधिक्षिप्तस्तदा रामः पश्चाद्वालिनमब्रवीत्॥', 'dharmārthaguṇasaṃpannaṃ harīśvaram anuttamam
adhikṣiptas tadā rāmaḥ paścād vālinam abravīt', null, 4018003),
('ramayana-4-18-4', 4, 'Kishkindha Kanda, Sarga 18, Verse 4', 'धर्ममर्थं च कामं च समयं चापि लौकिकम्।
अविज्ञाय कथं बाल्यान्मामिहाद्य विगर्हसे॥', 'dharmam arthaṃ ca kāmaṃ ca samayaṃ cāpi laukikam
avijñāya kathaṃ bālyān mām ihādya vigarhase', null, 4018004),
('ramayana-4-18-5', 5, 'Kishkindha Kanda, Sarga 18, Verse 5', 'अपृष्ट्वा बुद्धिसंपन्नान्वृद्धानाचार्यसंमतान्।
सौम्य वानरचापल्यात्त्वं मां वक्तुमिहेच्छसि॥', 'apṛṣṭvā buddhisaṃpannān vṛddhān ācāryasaṃmatān
saumya vānaracāpalyāt tvaṃ māṃ vaktum ihecchasi', null, 4018005),
('ramayana-4-18-6', 6, 'Kishkindha Kanda, Sarga 18, Verse 6', 'इक्ष्वाकूणामियं भूमिः सशैलवनकानना।
मृगपक्षिमनुष्याणां निग्रहानुग्रहावपि॥', 'ikṣvākūṇām iyaṃ bhūmiḥ saśailavanakānanā
mṛgapakṣimanuṣyāṇāṃ nigrahānugrahāv api', null, 4018006),
('ramayana-4-18-7', 7, 'Kishkindha Kanda, Sarga 18, Verse 7', 'तां पालयति धर्मात्मा भरतः सत्यवागृजुः।
धर्मकामार्थतत्त्वज्ञो निग्रहानुग्रहे रतः॥', 'tāṃ pālayati dharmātmā bharataḥ satyavāg ṛjuḥ
dharmakāmārthatattvajño nigrahānugrahe rataḥ', null, 4018007),
('ramayana-4-18-8', 8, 'Kishkindha Kanda, Sarga 18, Verse 8', 'नयश्च विनयश्चोभौ यस्मिन्सत्यं च सुस्थितम्।
विक्रमश्च यथा दृष्टः स राजा देशकालवित्॥', 'nayaś ca vinayaś cobhau yasmin satyaṃ ca susthitam
vikramaś ca yathā dṛṣṭaḥ sa rājā deśakālavit', null, 4018008),
('ramayana-4-18-9', 9, 'Kishkindha Kanda, Sarga 18, Verse 9', 'तस्य धर्मकृतादेशा वयमन्ये च पार्थिवः।
चरामो वसुधां कृत्स्नां धर्मसंतानमिच्छवः॥', 'tasya dharmakṛtādeśā vayam anye ca pārthivaḥ
carāmo vasudhāṃ kṛtsnāṃ dharmasaṃtānam icchavaḥ', null, 4018009),
('ramayana-4-18-10', 10, 'Kishkindha Kanda, Sarga 18, Verse 10', 'तस्मिन्नृपतिशार्दूल भरते धर्मवत्सले।
पालयत्यखिलां भूमिं कश्चरेद्धर्मनिग्रहम्॥', 'tasmin nṛpatiśārdūla bharate dharmavatsale
pālayaty akhilāṃ bhūmiṃ kaś cared dharmanigraham', null, 4018010),
('ramayana-4-18-11', 11, 'Kishkindha Kanda, Sarga 18, Verse 11', 'ते वयं मार्गविभ्रष्टं स्वधर्मे परमे स्थिताः।
भरताज्ञां पुरस्कृत्य निगृह्णीमो यथाविधि॥', 'te vayaṃ mārgavibhraṣṭaṃ svadharme parame sthitāḥ
bharatājñāṃ puraskṛtya nigṛhṇīmo yathāvidhi', null, 4018011),
('ramayana-4-18-12', 12, 'Kishkindha Kanda, Sarga 18, Verse 12', 'त्वं तु संक्लिष्टधर्मा च कर्मणा च विगर्हितः।
कामतन्त्रप्रधानश्च न स्थितो राजवर्त्मनि॥', 'tvaṃ tu saṃkliṣṭadharmā ca karmaṇā ca vigarhitaḥ
kāmatantrapradhānaś ca na sthito rājavartmani', null, 4018012),
('ramayana-4-18-13', 13, 'Kishkindha Kanda, Sarga 18, Verse 13', 'ज्येष्ठो भ्राता पिता चैव यश्च विद्यां प्रयच्छति।
त्रयस्ते पितरो ज्ञेया धर्मे च पथि वर्तिनः॥', 'jyeṣṭho bhrātā pitā caiva yaś ca vidyāṃ prayacchati
trayas te pitaro jñeyā dharme ca pathi vartinaḥ', null, 4018013),
('ramayana-4-18-14', 14, 'Kishkindha Kanda, Sarga 18, Verse 14', 'यवीयानात्मनः पुत्रः शिष्यश्चापि गुणोदितः।
पुत्रवत्ते त्रयश्चिन्त्या धर्मश्चेदत्र कारणम्॥', 'yavīyān ātmanaḥ putraḥ śiṣyaś cāpi guṇoditaḥ
putravat te trayaś cintyā dharmaś ced atra kāraṇam', null, 4018014),
('ramayana-4-18-15', 15, 'Kishkindha Kanda, Sarga 18, Verse 15', 'सूक्ष्मः परमदुर्ज्ञेयः सतां धर्मः प्लवंगम।
हृदिस्थः सर्वभूतानामात्मा वेद शुभाशुभम्॥', 'sūkṣmaḥ paramadurjñeyaḥ satāṃ dharmaḥ plavaṃgama
hṛdisthaḥ sarvabhūtānām ātmā veda śubhāśubham', null, 4018015),
('ramayana-4-18-16', 16, 'Kishkindha Kanda, Sarga 18, Verse 16', 'चपलश्चपलैः सार्धं वानरैरकृतात्मभिः।
जात्यन्ध इव जात्यन्धैर्मन्त्रयन्द्रक्ष्यसे नु किम्॥', 'capalaś capalaiḥ sārdhaṃ vānarair akṛtātmabhiḥ
jātyandha iva jātyandhair mantrayan drakṣyase nu kim', null, 4018016),
('ramayana-4-18-17', 17, 'Kishkindha Kanda, Sarga 18, Verse 17', 'अहं तु व्यक्ततामस्य वचनस्य ब्रवीमि ते।
न हि मां केवलं रोषात्त्वं विगर्हितुमर्हसि॥', 'ahaṃ tu vyaktatām asya vacanasya bravīmi te
na hi māṃ kevalaṃ roṣāt tvaṃ vigarhitum arhasi', null, 4018017),
('ramayana-4-18-18', 18, 'Kishkindha Kanda, Sarga 18, Verse 18', 'तदेतत्कारणं पश्य यदर्थं त्वं मया हतः।
भ्रातुर्वर्तसि भार्यायां त्यक्त्वा धर्मं सनातनम्॥', 'tad etat kāraṇaṃ paśya yadarthaṃ tvaṃ mayā hataḥ
bhrātur vartasi bhāryāyāṃ tyaktvā dharmaṃ sanātanam', null, 4018018),
('ramayana-4-18-19', 19, 'Kishkindha Kanda, Sarga 18, Verse 19', 'अस्य त्वं धरमाणस्य सुग्रीवस्य महात्मनः।
रुमायां वर्तसे कामात्स्नुषायां पापकर्मकृत्॥', 'asya tvaṃ dharamāṇasya sugrīvasya mahātmanaḥ
rumāyāṃ vartase kāmāt snuṣāyāṃ pāpakarmakṛt', null, 4018019),
('ramayana-4-18-20', 20, 'Kishkindha Kanda, Sarga 18, Verse 20', 'तद्व्यतीतस्य ते धर्मात्कामवृत्तस्य वानर।
भ्रातृभार्याभिमर्शेऽस्मिन्दण्डोऽयं प्रतिपादितः॥', 'tad vyatītasya te dharmāt kāmavṛttasya vānara
bhrātṛbhāryābhimarśe ''smin daṇḍo ''yaṃ pratipāditaḥ', null, 4018020),
('ramayana-4-18-21', 21, 'Kishkindha Kanda, Sarga 18, Verse 21', 'न हि धर्मविरुद्धस्य लोकवृत्तादपेयुषः।
दण्डादन्यत्र पश्यामि निग्रहं हरियूथप॥', 'na hi dharmaviruddhasya lokavṛttād apeyuṣaḥ
daṇḍād anyatra paśyāmi nigrahaṃ hariyūthapa', null, 4018021),
('ramayana-4-18-22', 22, 'Kishkindha Kanda, Sarga 18, Verse 22', 'औरसीं भगिनीं वापि भार्यां वाप्यनुजस्य यः।
प्रचरेत नरः कामात्तस्य दण्डो वधः स्मृतः॥', 'aurasīṃ bhaginīṃ vāpi bhāryāṃ vāpy anujasya yaḥ
pracareta naraḥ kāmāt tasya daṇḍo vadhaḥ smṛtaḥ', null, 4018022),
('ramayana-4-18-23', 23, 'Kishkindha Kanda, Sarga 18, Verse 23', 'भरतस्तु महीपालो वयं त्वादेशवर्तिनः।
त्वं च धर्मादतिक्रान्तः कथं शक्यमुपेक्षितुम्॥', 'bharatas tu mahīpālo vayaṃ tv ādeśavartinaḥ
tvaṃ ca dharmād atikrāntaḥ kathaṃ śakyam upekṣitum', null, 4018023),
('ramayana-4-18-24', 24, 'Kishkindha Kanda, Sarga 18, Verse 24', 'गुरुधर्मव्यतिक्रान्तं प्राज्ञो धर्मेण पालयन्।
भरतः कामवृत्तानां निग्रहे पर्यवस्थितः॥', 'gurudharmavyatikrāntaṃ prājño dharmeṇa pālayan
bharataḥ kāmavṛttānāṃ nigrahe paryavasthitaḥ', null, 4018024),
('ramayana-4-18-25', 25, 'Kishkindha Kanda, Sarga 18, Verse 25', 'वयं तु भरतादेशं विधिं कृत्वा हरीश्वर।
त्वद्विधान्भिन्नमर्यादान्नियन्तुं पर्यवस्थिताः॥', 'vayaṃ tu bharatādeśaṃ vidhiṃ kṛtvā harīśvara
tvadvidhān bhinnamaryādān niyantuṃ paryavasthitāḥ', null, 4018025),
('ramayana-4-18-26', 26, 'Kishkindha Kanda, Sarga 18, Verse 26', 'सुग्रीवेण च मे सख्यं लक्ष्मणेन यथा तथा।
दारराज्यनिमित्तं च निःश्रेयसि रतः स मे॥', 'sugrīveṇa ca me sakhyaṃ lakṣmaṇena yathā tathā
dārarājyanimittaṃ ca niḥśreyasi rataḥ sa me', null, 4018026),
('ramayana-4-18-27', 27, 'Kishkindha Kanda, Sarga 18, Verse 27', 'प्रतिज्ञा च मया दत्ता तदा वानरसंनिधौ।
प्रतिज्ञा च कथं शक्या मद्विधेनानवेक्षितुम्॥', 'pratijñā ca mayā dattā tadā vānarasaṃnidhau
pratijñā ca kathaṃ śakyā madvidhenānavekṣitum', null, 4018027),
('ramayana-4-18-28', 28, 'Kishkindha Kanda, Sarga 18, Verse 28', 'तदेभिः कारणैः सर्वैर्महद्भिर्धर्मसंहितैः।
शासनं तव यद्युक्तं तद्भवाननुमन्यताम्॥', 'tad ebhiḥ kāraṇaiḥ sarvair mahadbhir dharmasaṃhitaiḥ
śāsanaṃ tava yad yuktaṃ tad bhavān anumanyatām', null, 4018028),
('ramayana-4-18-29', 29, 'Kishkindha Kanda, Sarga 18, Verse 29', 'सर्वथा धर्म इत्येव द्रष्टव्यस्तव निग्रहः।
वयस्यस्योपकर्तव्यं धर्ममेवानुपश्यता॥', 'sarvathā dharma ity eva draṣṭavyas tava nigrahaḥ
vayasyasyopakartavyaṃ dharmam evānupaśyatā', null, 4018029),
('ramayana-4-18-30', 30, 'Kishkindha Kanda, Sarga 18, Verse 30', 'राजभिर्धृतदण्डास्तु कृत्वा पापानि मानवाः।
निर्मलाः स्वर्गमायान्ति सन्तः सुकृतिनो यथा॥', 'rājabhir dhṛtadaṇḍās tu kṛtvā pāpāni mānavāḥ
nirmalāḥ svargam āyānti santaḥ sukṛtino yathā', null, 4018030),
('ramayana-4-18-31', 31, 'Kishkindha Kanda, Sarga 18, Verse 31', 'आर्येण मम मान्धात्रा व्यसनं घोरमीप्सितम्।
श्रमणेन कृते पापे यथा पापं कृतं त्वया॥', 'āryeṇa mama māndhātrā vyasanaṃ ghoram īpsitam
śramaṇena kṛte pāpe yathā pāpaṃ kṛtaṃ tvayā', null, 4018031),
('ramayana-4-18-32', 32, 'Kishkindha Kanda, Sarga 18, Verse 32', 'अन्यैरपि कृतं पापं प्रमत्तैर्वसुधाधिपैः।
प्रायश्चित्तं च कुर्वन्ति तेन तच्छाम्यते रजः॥', 'anyair api kṛtaṃ pāpaṃ pramattair vasudhādhipaiḥ
prāyaścittaṃ ca kurvanti tena tac chāmyate rajaḥ', null, 4018032),
('ramayana-4-18-33', 33, 'Kishkindha Kanda, Sarga 18, Verse 33', 'तदलं परितापेन धर्मतः परिकल्पितः।
वधो वानरशार्दूल न वयं स्ववशे स्थिताः॥', 'tad alaṃ paritāpena dharmataḥ parikalpitaḥ
vadho vānaraśārdūla na vayaṃ svavaśe sthitāḥ', null, 4018033),
('ramayana-4-18-34', 34, 'Kishkindha Kanda, Sarga 18, Verse 34', 'वागुराभिश्च पाशैश्च कूटैश्च विविधैर्नराः।
प्रतिच्छन्नाश्च दृश्याश्च गृह्णन्ति सुबहून्मृगान्।
प्रधावितान्वा वित्रस्तान्विस्रब्धानतिविष्ठितान्॥', 'vāgurābhiś ca pāśaiś ca kūṭaiś ca vividhair narāḥ
praticchannāś ca dṛśyāś ca gṛhṇanti subahūn mṛgān
pradhāvitān vā vitrastān visrabdhān ativiṣṭhitān', null, 4018034),
('ramayana-4-18-35', 35, 'Kishkindha Kanda, Sarga 18, Verse 35', 'प्रमत्तानप्रमत्तान्वा नरा मांसार्थिनो भृशम्।
विध्यन्ति विमुखांश्चापि न च दोषोऽत्र विद्यते॥', 'pramattān apramattān vā narā māṃsārthino bhṛśam
vidhyanti vimukhāṃś cāpi na ca doṣo ''tra vidyate', null, 4018035),
('ramayana-4-18-36', 36, 'Kishkindha Kanda, Sarga 18, Verse 36', 'यान्ति राजर्षयश्चात्र मृगयां धर्मकोविदाः।
तस्मात्त्वं निहतो युद्धे मया बाणेन वानर।
अयुध्यन्प्रतियुध्यन्वा यस्माच्छाखामृगो ह्यसि॥', 'yānti rājarṣayaś cātra mṛgayāṃ dharmakovidāḥ
tasmāt tvaṃ nihato yuddhe mayā bāṇena vānara
ayudhyan pratiyudhyan vā yasmāc chākhāmṛgo hy asi', null, 4018036),
('ramayana-4-18-37', 37, 'Kishkindha Kanda, Sarga 18, Verse 37', 'दुर्लभस्य च धर्मस्य जीवितस्य शुभस्य च।
राजानो वानरश्रेष्ठ प्रदातारो न संशयः॥', 'durlabhasya ca dharmasya jīvitasya śubhasya ca
rājāno vānaraśreṣṭha pradātāro na saṃśayaḥ', null, 4018037),
('ramayana-4-18-38', 38, 'Kishkindha Kanda, Sarga 18, Verse 38', 'तान्न हिंस्यान्न चाक्रोशेन्नाक्षिपेन्नाप्रियं वदेत्।
देवा मानुषरूपेण चरन्त्येते महीतले॥', 'tān na hiṃsyān na cākrośen nākṣipen nāpriyaṃ vadet
devā mānuṣarūpeṇa caranty ete mahītale', null, 4018038),
('ramayana-4-18-39', 39, 'Kishkindha Kanda, Sarga 18, Verse 39', 'त्वं तु धर्ममविज्ञाय केवलं रोषमास्थितः।
प्रदूषयसि मां धर्मे पितृपैतामहे स्थितम्॥', 'tvaṃ tu dharmam avijñāya kevalaṃ roṣam āsthitaḥ
pradūṣayasi māṃ dharme pitṛpaitāmahe sthitam', null, 4018039),
('ramayana-4-18-40', 40, 'Kishkindha Kanda, Sarga 18, Verse 40', 'एवमुक्तस्तु रामेण वाली प्रव्यथितो भृशम्।
प्रत्युवाच ततो रामं प्राञ्जलिर्वानरेश्वरः॥', 'evam uktas tu rāmeṇa vālī pravyathito bhṛśam
pratyuvāca tato rāmaṃ prāñjalir vānareśvaraḥ', null, 4018040),
('ramayana-4-18-41', 41, 'Kishkindha Kanda, Sarga 18, Verse 41', 'यत्त्वमात्थ नरश्रेष्ठ तदेवं नात्र संशयः।
प्रतिवक्तुं प्रकृष्टे हि नापकृष्टस्तु शक्नुयात्॥', 'yat tvam āttha naraśreṣṭha tad evaṃ nātra saṃśayaḥ
prativaktuṃ prakṛṣṭe hi nāpakṛṣṭas tu śaknuyāt', null, 4018041),
('ramayana-4-18-42', 42, 'Kishkindha Kanda, Sarga 18, Verse 42', 'यदयुक्तं मया पूर्वं प्रमादाद्वाक्यमप्रियम्।
तत्रापि खलु मे दोषं कर्तुं नार्हसि राघव॥', 'yad ayuktaṃ mayā pūrvaṃ pramādād vākyam apriyam
tatrāpi khalu me doṣaṃ kartuṃ nārhasi rāghava', null, 4018042),
('ramayana-4-18-43', 43, 'Kishkindha Kanda, Sarga 18, Verse 43', 'त्वं हि दृष्टार्थतत्त्वज्ञः प्रजानां च हिते रतः।
कार्यकारणसिद्धौ ते प्रसन्ना बुद्धिरव्यया॥', 'tvaṃ hi dṛṣṭārthatattvajñaḥ prajānāṃ ca hite rataḥ
kāryakāraṇasiddhau te prasannā buddhir avyayā', null, 4018043),
('ramayana-4-18-44', 44, 'Kishkindha Kanda, Sarga 18, Verse 44', 'मामप्यवगतं धर्माद्व्यतिक्रान्तपुरस्कृतम्।
धर्मसंहितया वाचा धर्मज्ञ परिपालय॥', 'mām apy avagataṃ dharmād vyatikrāntapuraskṛtam
dharmasaṃhitayā vācā dharmajña paripālaya', null, 4018044),
('ramayana-4-18-45', 45, 'Kishkindha Kanda, Sarga 18, Verse 45', 'बाष्पसंरुद्धकण्ठस्तु वाली सार्तरवः शनैः।
उवाच रामं संप्रेक्ष्य पङ्कलग्न इव द्विपः॥', 'bāṣpasaṃruddhakaṇṭhas tu vālī sārtaravaḥ śanaiḥ
uvāca rāmaṃ saṃprekṣya paṅkalagna iva dvipaḥ', null, 4018045),
('ramayana-4-18-46', 46, 'Kishkindha Kanda, Sarga 18, Verse 46', 'न त्वात्मानमहं शोचे न तारां नापि बान्धवान्।
यथा पुत्रं गुणश्रेष्ठमङ्गदं कनकाङ्गदम्॥', 'na tv ātmānam ahaṃ śoce na tārāṃ nāpi bāndhavān
yathā putraṃ guṇaśreṣṭham aṅgadaṃ kanakāṅgadam', null, 4018046),
('ramayana-4-18-47', 47, 'Kishkindha Kanda, Sarga 18, Verse 47', 'स ममादर्शनाद्दीनो बाल्यात्प्रभृति लालितः।
तटाक इव पीताम्बुरुपशोषं गमिष्यति॥', 'sa mamādarśanād dīno bālyāt prabhṛti lālitaḥ
taṭāka iva pītāmbur upaśoṣaṃ gamiṣyati', null, 4018047),
('ramayana-4-18-48', 48, 'Kishkindha Kanda, Sarga 18, Verse 48', 'सुग्रीवे चाङ्गदे चैव विधत्स्व मतिमुत्तमाम्।
त्वं हि शास्ता च गोप्ता च कार्याकार्यविधौ स्थितः॥', 'sugrīve cāṅgade caiva vidhatsva matim uttamām
tvaṃ hi śāstā ca goptā ca kāryākāryavidhau sthitaḥ', null, 4018048),
('ramayana-4-18-49', 49, 'Kishkindha Kanda, Sarga 18, Verse 49', 'या ते नरपते वृत्तिर्भरते लक्ष्मणे च या।
सुग्रीवे चाङ्गदे राजंस्तां चिन्तयितुमर्हसि॥', 'yā te narapate vṛttir bharate lakṣmaṇe ca yā
sugrīve cāṅgade rājaṃs tāṃ cintayitum arhasi', null, 4018049),
('ramayana-4-18-50', 50, 'Kishkindha Kanda, Sarga 18, Verse 50', 'मद्दोषकृतदोषां तां यथा तारां तपस्विनीम्।
सुग्रीवो नावमन्येत तथावस्थातुमर्हसि॥', 'maddoṣakṛtadoṣāṃ tāṃ yathā tārāṃ tapasvinīm
sugrīvo nāvamanyeta tathāvasthātum arhasi', null, 4018050),
('ramayana-4-18-51', 51, 'Kishkindha Kanda, Sarga 18, Verse 51', 'त्वया ह्यनुगृहीतेन शक्यं राज्यमुपासितुम्।
त्वद्वशे वर्तमानेन तव चित्तानुवर्तिना॥', 'tvayā hy anugṛhītena śakyaṃ rājyam upāsitum
tvadvaśe vartamānena tava cittānuvartinā', null, 4018051),
('ramayana-4-18-52', 52, 'Kishkindha Kanda, Sarga 18, Verse 52', 'स तमाश्वासयद्रामो वालिनं व्यक्तदर्शनम्॥', 'sa tam āśvāsayad rāmo vālinaṃ vyaktadarśanam', null, 4018052),
('ramayana-4-18-53', 53, 'Kishkindha Kanda, Sarga 18, Verse 53', 'न वयं भवता चिन्त्या नाप्यात्मा हरिसत्तम।
वयं भवद्विशेषेण धर्मतः कृतनिश्चयाः॥', 'na vayaṃ bhavatā cintyā nāpy ātmā harisattama
vayaṃ bhavadviśeṣeṇa dharmataḥ kṛtaniścayāḥ', null, 4018053),
('ramayana-4-18-54', 54, 'Kishkindha Kanda, Sarga 18, Verse 54', 'दण्ड्ये यः पातयेद्दण्डं दण्ड्यो यश्चापि दण्ड्यते।
कार्यकारणसिद्धार्थावुभौ तौ नावसीदतः॥', 'daṇḍye yaḥ pātayed daṇḍaṃ daṇḍyo yaś cāpi daṇḍyate
kāryakāraṇasiddhārthāv ubhau tau nāvasīdataḥ', null, 4018054),
('ramayana-4-18-55', 55, 'Kishkindha Kanda, Sarga 18, Verse 55', 'तद्भवान्दण्डसंयोगादस्माद्विगतकल्मषः।
गतः स्वां प्रकृतिं धर्म्यां धर्मदृष्ट्तेन वर्त्मना॥', 'tad bhavān daṇḍasaṃyogād asmād vigatakalmaṣaḥ
gataḥ svāṃ prakṛtiṃ dharmyāṃ dharmadṛṣṭtena vartmanā', null, 4018055),
('ramayana-4-18-56', 56, 'Kishkindha Kanda, Sarga 18, Verse 56', 'स तस्य वाक्यं मधुरं महात्मनः समाहितं धर्मपथानुवर्तिनः।
निशम्य रामस्य रणावमर्दिनो वचः सुयुक्तं निजगाद वानरः॥', 'sa tasya vākyaṃ madhuraṃ mahātmanaḥ samāhitaṃ dharmapathānuvartinaḥ
niśamya rāmasya raṇāvamardino vacaḥ suyuktaṃ nijagāda vānaraḥ', null, 4018056),
('ramayana-4-18-57', 57, 'Kishkindha Kanda, Sarga 18, Verse 57', 'शराभितप्तेन विचेतसा मया प्रदूषितस्त्वं यदजानता प्रभो।
इदं महेन्द्रोपमभीमविक्रम प्रसादितस्त्वं क्षम मे महीश्वर॥', 'śarābhitaptena vicetasā mayā pradūṣitas tvaṃ yad ajānatā prabho
idaṃ mahendropamabhīmavikrama prasāditas tvaṃ kṣama me mahīśvara', null, 4018057)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 19 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-19-1', 1, 'Kishkindha Kanda, Sarga 19, Verse 1', 'स वानरमहाराजः शयानः शरविक्षतः।
प्रत्युक्तो हेतुमद्वाक्यैर्नोत्तरं प्रत्यपद्यत॥', 'sa vānaramahārājaḥ śayānaḥ śaravikṣataḥ
pratyukto hetumadvākyair nottaraṃ pratyapadyata', null, 4019001),
('ramayana-4-19-2', 2, 'Kishkindha Kanda, Sarga 19, Verse 2', 'अश्मभिः परिभिन्नाङ्गः पादपैराहतो भृशम्।
रामबाणेन चाक्रान्तो जीवितान्ते मुमोह सः॥', 'aśmabhiḥ paribhinnāṅgaḥ pādapair āhato bhṛśam
rāmabāṇena cākrānto jīvitānte mumoha saḥ', null, 4019002),
('ramayana-4-19-3', 3, 'Kishkindha Kanda, Sarga 19, Verse 3', 'तं भार्याबाणमोक्षेण रामदत्तेन संयुगे।
हतं प्लवगशार्दूलं तारा शुश्राव वालिनम्॥', 'taṃ bhāryābāṇamokṣeṇa rāmadattena saṃyuge
hataṃ plavagaśārdūlaṃ tārā śuśrāva vālinam', null, 4019003),
('ramayana-4-19-4', 4, 'Kishkindha Kanda, Sarga 19, Verse 4', 'सा सपुत्राप्रियं श्रुत्वा वधं भर्तुः सुदारुणम्।
निष्पपात भृशं त्रस्ता विविधाद्गिरिगह्वरात्॥', 'sā saputrāpriyaṃ śrutvā vadhaṃ bhartuḥ sudāruṇam
niṣpapāta bhṛśaṃ trastā vividhād girigahvarāt', null, 4019004),
('ramayana-4-19-5', 5, 'Kishkindha Kanda, Sarga 19, Verse 5', 'ये त्वङ्गदपरीवारा वानरा हि महाबलाः।
ते सकार्मुकमालोक्य रामं त्रस्ताः प्रदुद्रुवुः॥', 'ye tv aṅgadaparīvārā vānarā hi mahābalāḥ
te sakārmukam ālokya rāmaṃ trastāḥ pradudruvuḥ', null, 4019005),
('ramayana-4-19-6', 6, 'Kishkindha Kanda, Sarga 19, Verse 6', 'सा ददर्श ततस्त्रस्तान्हरीनापततो द्रुतम्।
यूथादिव परिभ्रष्टान्मृगान्निहतयूथपान्॥', 'sā dadarśa tatas trastān harīn āpatato drutam
yūthād iva paribhraṣṭān mṛgān nihatayūthapān', null, 4019006),
('ramayana-4-19-7', 7, 'Kishkindha Kanda, Sarga 19, Verse 7', 'तानुवाच समासाद्य दुःखितान्दुःखिता सती।
राम वित्रासितान्सर्वाननुबद्धानिवेषुभिः॥', 'tān uvāca samāsādya duḥkhitān duḥkhitā satī
rāma vitrāsitān sarvān anubaddhān iveṣubhiḥ', null, 4019007),
('ramayana-4-19-8', 8, 'Kishkindha Kanda, Sarga 19, Verse 8', 'वानरा राजसिंहस्य यस्य यूयं पुरःसराः।
तं विहाय सुवित्रस्ताः कस्माद्द्रवत दुर्गताः॥', 'vānarā rājasiṃhasya yasya yūyaṃ puraḥsarāḥ
taṃ vihāya suvitrastāḥ kasmād dravata durgatāḥ', null, 4019008),
('ramayana-4-19-9', 9, 'Kishkindha Kanda, Sarga 19, Verse 9', 'राज्यहेतोः स चेद्भ्राता भ्राता रौद्रेण पातितः।
रामेण प्रसृतैर्दूरान्मार्गणैर्दूर पातिभिः॥', 'rājyahetoḥ sa ced bhrātā bhrātā raudreṇa pātitaḥ
rāmeṇa prasṛtair dūrān mārgaṇair dūra pātibhiḥ', null, 4019009),
('ramayana-4-19-10', 10, 'Kishkindha Kanda, Sarga 19, Verse 10', 'कपिपत्न्या वचः श्रुत्वा कपयः कामरूपिणः।
प्राप्तकालमविश्लिष्टमूचुर्वचनमङ्गनाम्॥', 'kapipatnyā vacaḥ śrutvā kapayaḥ kāmarūpiṇaḥ
prāptakālam aviśliṣṭam ūcur vacanam aṅganām', null, 4019010),
('ramayana-4-19-11', 11, 'Kishkindha Kanda, Sarga 19, Verse 11', 'जीव पुत्रे निवर्तस्य पुत्रं रक्षस्व चान्दगम्।
अन्तको राम रूपेण हत्वा नयति वालिनम्॥', 'jīva putre nivartasya putraṃ rakṣasva cāndagam
antako rāma rūpeṇa hatvā nayati vālinam', null, 4019011),
('ramayana-4-19-12', 12, 'Kishkindha Kanda, Sarga 19, Verse 12', 'क्षिप्तान्वृक्षान्समाविध्य विपुलाश्च शिलास्तथा।
वाली वज्रसमैर्बाणैर्वज्रेणेव निपातितः॥', 'kṣiptān vṛkṣān samāvidhya vipulāś ca śilās tathā
vālī vajrasamair bāṇair vajreṇeva nipātitaḥ', null, 4019012),
('ramayana-4-19-13', 13, 'Kishkindha Kanda, Sarga 19, Verse 13', 'अभिद्रुतमिदं सर्वं विद्रुतं प्रसृतं बलम्।
अस्मिन्प्लवगशार्दूले हते शक्रसमप्रभे॥', 'abhidrutam idaṃ sarvaṃ vidrutaṃ prasṛtaṃ balam
asmin plavagaśārdūle hate śakrasamaprabhe', null, 4019013),
('ramayana-4-19-14', 14, 'Kishkindha Kanda, Sarga 19, Verse 14', 'रक्ष्यतां नगरं शूरैरङ्गदश्चाभिषिच्यताम्।
पदस्थं वालिनः पुत्रं भजिष्यन्ति प्लवंगमाः॥', 'rakṣyatāṃ nagaraṃ śūrair aṅgadaś cābhiṣicyatām
padasthaṃ vālinaḥ putraṃ bhajiṣyanti plavaṃgamāḥ', null, 4019014),
('ramayana-4-19-15', 15, 'Kishkindha Kanda, Sarga 19, Verse 15', 'अथ वा रुचिरं स्थानमिह ते रुचिरानने।
आविशन्ति हि दुर्गाणि क्षिप्रमद्यैव वानराः॥', 'atha vā ruciraṃ sthānam iha te rucirānane
āviśanti hi durgāṇi kṣipram adyaiva vānarāḥ', null, 4019015),
('ramayana-4-19-16', 16, 'Kishkindha Kanda, Sarga 19, Verse 16', 'अभार्याः सह भार्याश्च सन्त्यत्र वनचारिणः।
लुब्धेभ्यो विप्रयुक्तेभ्यः स्वेभ्यो नस्तुमुलं भयम्॥', 'abhāryāḥ saha bhāryāś ca santy atra vanacāriṇaḥ
lubdhebhyo viprayuktebhyaḥ svebhyo nas tumulaṃ bhayam', null, 4019016),
('ramayana-4-19-17', 17, 'Kishkindha Kanda, Sarga 19, Verse 17', 'अल्पान्तरगतानां तु श्रुत्वा वचनमङ्गना।
आत्मनः प्रतिरूपं सा बभाषे चारुहासिनी॥', 'alpāntaragatānāṃ tu śrutvā vacanam aṅganā
ātmanaḥ pratirūpaṃ sā babhāṣe cāruhāsinī', null, 4019017),
('ramayana-4-19-18', 18, 'Kishkindha Kanda, Sarga 19, Verse 18', 'पुत्रेण मम किं कार्यं किं राज्येन किमात्मना।
कपिसिंहे महाभागे तस्मिन्भर्तरि नश्यति॥', 'putreṇa mama kiṃ kāryaṃ kiṃ rājyena kim ātmanā
kapisiṃhe mahābhāge tasmin bhartari naśyati', null, 4019018),
('ramayana-4-19-19', 19, 'Kishkindha Kanda, Sarga 19, Verse 19', 'पादमूलं गमिष्यामि तस्यैवाहं महात्मनः।
योऽसौ रामप्रयुक्तेन शरेण विनिपातितः॥', 'pādamūlaṃ gamiṣyāmi tasyaivāhaṃ mahātmanaḥ
yo ''sau rāmaprayuktena śareṇa vinipātitaḥ', null, 4019019),
('ramayana-4-19-20', 20, 'Kishkindha Kanda, Sarga 19, Verse 20', 'एवमुक्त्वा प्रदुद्राव रुदती शोककर्शिता।
शिरश्चोरश्च बाहुभ्यां दुःखेन समभिघ्नती॥', 'evam uktvā pradudrāva rudatī śokakarśitā
śiraś coraś ca bāhubhyāṃ duḥkhena samabhighnatī', null, 4019020),
('ramayana-4-19-21', 21, 'Kishkindha Kanda, Sarga 19, Verse 21', 'आव्रजन्ती ददर्शाथ पतिं निपतितं भुवि।
हन्तारं दानवेन्द्राणां समरेष्वनिवर्तिनाम्॥', 'āvrajantī dadarśātha patiṃ nipatitaṃ bhuvi
hantāraṃ dānavendrāṇāṃ samareṣv anivartinām', null, 4019021),
('ramayana-4-19-22', 22, 'Kishkindha Kanda, Sarga 19, Verse 22', 'क्षेप्तारं पर्वतेन्द्राणां वज्राणामिव वासवम्।
महावातसमाविष्टं महामेघौघनिःस्वनम्॥', 'kṣeptāraṃ parvatendrāṇāṃ vajrāṇām iva vāsavam
mahāvātasamāviṣṭaṃ mahāmeghaughaniḥsvanam', null, 4019022),
('ramayana-4-19-23', 23, 'Kishkindha Kanda, Sarga 19, Verse 23', 'शक्रतुल्यपराक्रान्तं वृष्ट्वेवोपरतं घनम्।
नर्दन्तं नर्दतां भीमं शूरं शूरेण पातितम्॥', 'śakratulyaparākrāntaṃ vṛṣṭvevoparataṃ ghanam
nardantaṃ nardatāṃ bhīmaṃ śūraṃ śūreṇa pātitam', null, 4019023),
('ramayana-4-19-24', 24, 'Kishkindha Kanda, Sarga 19, Verse 24', 'शार्दूलेनामिषस्यार्थे मृगराजं यथा हतम्।
अर्चितं सर्वलोकस्य सपताकं सवेदिकम्॥', 'śārdūlenāmiṣasyārthe mṛgarājaṃ yathā hatam
arcitaṃ sarvalokasya sapatākaṃ savedikam', null, 4019024),
('ramayana-4-19-25', 25, 'Kishkindha Kanda, Sarga 19, Verse 25', 'नागहेतोः सुपर्णेन चैत्यमुन्मथितं यथा।
अवष्टभ्यावतिष्ठन्तं ददर्श धनुरूर्जितम्॥', 'nāgahetoḥ suparṇena caityam unmathitaṃ yathā
avaṣṭabhyāvatiṣṭhantaṃ dadarśa dhanur ūrjitam', null, 4019025),
('ramayana-4-19-26', 26, 'Kishkindha Kanda, Sarga 19, Verse 26', 'रामं रामानुजं चैव भर्तुश्चैवानुजं शुभा।
तानतीत्य समासाद्य भर्तारं निहतं रणे॥', 'rāmaṃ rāmānujaṃ caiva bhartuś caivānujaṃ śubhā
tān atītya samāsādya bhartāraṃ nihataṃ raṇe', null, 4019026),
('ramayana-4-19-27', 27, 'Kishkindha Kanda, Sarga 19, Verse 27', 'समीक्ष्य व्यथिता भूमौ संभ्रान्ता निपपात ह।
सुप्तेव पुनरुत्थाय आर्यपुत्रेति क्रोशती॥', 'samīkṣya vyathitā bhūmau saṃbhrāntā nipapāta ha
supteva punar utthāya āryaputreti krośatī', null, 4019027),
('ramayana-4-19-28', 28, 'Kishkindha Kanda, Sarga 19, Verse 28', 'रुरोद सा पतिं दृष्ट्वा संदितं मृत्युदामभिः।
तामवेक्ष्य तु सुग्रीवः क्रोशन्तीं कुररीमिव॥', 'ruroda sā patiṃ dṛṣṭvā saṃditaṃ mṛtyudāmabhiḥ
tām avekṣya tu sugrīvaḥ krośantīṃ kurarīm iva', null, 4019028),
('ramayana-4-19-29', 29, 'Kishkindha Kanda, Sarga 19, Verse 29', 'विषादमगमत्कष्टं दृष्ट्वा चाङ्गदमागतम्॥', 'viṣādam agamat kaṣṭaṃ dṛṣṭvā cāṅgadam āgatam', null, 4019029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 20 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-20-1', 1, 'Kishkindha Kanda, Sarga 20, Verse 1', 'रामचापविसृष्टेन शरेणान्तकरेण तम्।
दृष्ट्वा विनिहतं भूमौ तारा ताराधिपानना॥', 'rāmacāpavisṛṣṭena śareṇāntakareṇa tam
dṛṣṭvā vinihataṃ bhūmau tārā tārādhipānanā', null, 4020001),
('ramayana-4-20-2', 2, 'Kishkindha Kanda, Sarga 20, Verse 2', 'सा समासाद्य भर्तारं पर्यष्वजत भामिनी।
इषुणाभिहतं दृष्ट्वा वालिनं कुञ्जरोपमम्॥', 'sā samāsādya bhartāraṃ paryaṣvajata bhāminī
iṣuṇābhihataṃ dṛṣṭvā vālinaṃ kuñjaropamam', null, 4020002),
('ramayana-4-20-3', 3, 'Kishkindha Kanda, Sarga 20, Verse 3', 'वानरेन्द्रं महेन्द्राभं शोकसंतप्तमानसा।
तारा तरुमिवोन्मूलं पर्यदेवयदातुरा॥', 'vānarendraṃ mahendrābhaṃ śokasaṃtaptamānasā
tārā tarum ivonmūlaṃ paryadevayad āturā', null, 4020003),
('ramayana-4-20-4', 4, 'Kishkindha Kanda, Sarga 20, Verse 4', 'रणे दारुणविक्रान्त प्रवीर प्लवतां वर।
किं दीनामपुरोभागामद्य त्वं नाभिभाषसे॥', 'raṇe dāruṇavikrānta pravīra plavatāṃ vara
kiṃ dīnām apurobhāgām adya tvaṃ nābhibhāṣase', null, 4020004),
('ramayana-4-20-5', 5, 'Kishkindha Kanda, Sarga 20, Verse 5', 'उत्तिष्ठ हरिशार्दूल भजस्व शयनोत्तमम्।
नैवंविधाः शेरते हि भूमौ नृपतिसत्तमाः॥', 'uttiṣṭha hariśārdūla bhajasva śayanottamam
naivaṃvidhāḥ śerate hi bhūmau nṛpatisattamāḥ', null, 4020005),
('ramayana-4-20-6', 6, 'Kishkindha Kanda, Sarga 20, Verse 6', 'अतीव खलु ते कान्ता वसुधा वसुधाधिप।
गतासुरपि यां गात्रैर्मां विहाय निषेवसे॥', 'atīva khalu te kāntā vasudhā vasudhādhipa
gatāsur api yāṃ gātrair māṃ vihāya niṣevase', null, 4020006),
('ramayana-4-20-7', 7, 'Kishkindha Kanda, Sarga 20, Verse 7', 'व्यक्तमन्या त्वया वीर धर्मतः संप्रवर्तता।
किष्किन्धेव पुरी रम्या स्वर्गमार्गे विनिर्मिता॥', 'vyaktam anyā tvayā vīra dharmataḥ saṃpravartatā
kiṣkindheva purī ramyā svargamārge vinirmitā', null, 4020007),
('ramayana-4-20-8', 8, 'Kishkindha Kanda, Sarga 20, Verse 8', 'यान्यस्माभिस्त्वया सार्धं वनेषु मधुगन्धिषु।
विहृतानि त्वया काले तेषामुपरमः कृतः॥', 'yāny asmābhis tvayā sārdhaṃ vaneṣu madhugandhiṣu
vihṛtāni tvayā kāle teṣām uparamaḥ kṛtaḥ', null, 4020008),
('ramayana-4-20-9', 9, 'Kishkindha Kanda, Sarga 20, Verse 9', 'निरानन्दा निराशाहं निमग्ना शोकसागरे।
त्वयि पञ्चत्वमापन्ने महायूथपयूथपे॥', 'nirānandā nirāśāhaṃ nimagnā śokasāgare
tvayi pañcatvam āpanne mahāyūthapayūthape', null, 4020009),
('ramayana-4-20-10', 10, 'Kishkindha Kanda, Sarga 20, Verse 10', 'हृदयं सुस्थिरं मह्यं दृष्ट्वा विनिहतं भुवि।
यन्न शोकाभिसंतप्तं स्फुटतेऽद्य सहस्रधा॥', 'hṛdayaṃ susthiraṃ mahyaṃ dṛṣṭvā vinihataṃ bhuvi
yan na śokābhisaṃtaptaṃ sphuṭate ''dya sahasradhā', null, 4020010),
('ramayana-4-20-11', 11, 'Kishkindha Kanda, Sarga 20, Verse 11', 'सुग्रीवस्य त्वया भार्या हृता स च विवासितः।
यत्तत्तस्य त्वया व्युष्टिः प्राप्तेयं प्लवगाधिप॥', 'sugrīvasya tvayā bhāryā hṛtā sa ca vivāsitaḥ
yat tat tasya tvayā vyuṣṭiḥ prāpteyaṃ plavagādhipa', null, 4020011),
('ramayana-4-20-12', 12, 'Kishkindha Kanda, Sarga 20, Verse 12', 'निःश्रेयसपरा मोहात्त्वया चाहं विगर्हिता।
यैषाब्रुवं हितं वाक्यं वानरेन्द्रहितैषिणी॥', 'niḥśreyasaparā mohāt tvayā cāhaṃ vigarhitā
yaiṣābruvaṃ hitaṃ vākyaṃ vānarendrahitaiṣiṇī', null, 4020012),
('ramayana-4-20-13', 13, 'Kishkindha Kanda, Sarga 20, Verse 13', 'कालो निःसंशयो नूनं जीवितान्तकरस्तव।
बलाद्येनावपन्नोऽसि सुग्रीवस्यावशो वशम्॥', 'kālo niḥsaṃśayo nūnaṃ jīvitāntakaras tava
balād yenāvapanno ''si sugrīvasyāvaśo vaśam', null, 4020013),
('ramayana-4-20-14', 14, 'Kishkindha Kanda, Sarga 20, Verse 14', 'वैधव्यं शोकसंतापं कृपणं कृपणा सती।
अदुःखोपचिता पूर्वं वर्तयिष्याम्यनाथवत्॥', 'vaidhavyaṃ śokasaṃtāpaṃ kṛpaṇaṃ kṛpaṇā satī
aduḥkhopacitā pūrvaṃ vartayiṣyāmy anāthavat', null, 4020014),
('ramayana-4-20-15', 15, 'Kishkindha Kanda, Sarga 20, Verse 15', 'लालितश्चाङ्गदो वीरः सुकुमारः सुखोचितः।
वत्स्यते कामवस्थां मे पितृव्ये क्रोधमूर्छिते॥', 'lālitaś cāṅgado vīraḥ sukumāraḥ sukhocitaḥ
vatsyate kām avasthāṃ me pitṛvye krodhamūrchite', null, 4020015),
('ramayana-4-20-16', 16, 'Kishkindha Kanda, Sarga 20, Verse 16', 'कुरुष्व पितरं पुत्र सुदृष्टं धर्मवत्सलम्।
दुर्लभं दर्शनं त्वस्य तव वत्स भविष्यति॥', 'kuruṣva pitaraṃ putra sudṛṣṭaṃ dharmavatsalam
durlabhaṃ darśanaṃ tv asya tava vatsa bhaviṣyati', null, 4020016),
('ramayana-4-20-17', 17, 'Kishkindha Kanda, Sarga 20, Verse 17', 'समाश्वासय पुत्रं त्वं संदेशं संदिशस्व च।
मूर्ध्नि चैनं समाघ्राय प्रवासं प्रस्थितो ह्यसि॥', 'samāśvāsaya putraṃ tvaṃ saṃdeśaṃ saṃdiśasva ca
mūrdhni cainaṃ samāghrāya pravāsaṃ prasthito hy asi', null, 4020017),
('ramayana-4-20-18', 18, 'Kishkindha Kanda, Sarga 20, Verse 18', 'रामेण हि महत्कर्म कृतं त्वामभिनिघ्नता।
आनृण्यं तु गतं तस्य सुग्रीवस्य प्रतिश्रवे॥', 'rāmeṇa hi mahat karma kṛtaṃ tvām abhinighnatā
ānṛṇyaṃ tu gataṃ tasya sugrīvasya pratiśrave', null, 4020018),
('ramayana-4-20-19', 19, 'Kishkindha Kanda, Sarga 20, Verse 19', 'सकामो भव सुग्रीव रुमां त्वं प्रतिपत्स्यसे।
भुङ्क्ष्व राज्यमनुद्विग्नः शस्तो भ्राता रिपुस्तव॥', 'sakāmo bhava sugrīva rumāṃ tvaṃ pratipatsyase
bhuṅkṣva rājyam anudvignaḥ śasto bhrātā ripus tava', null, 4020019),
('ramayana-4-20-20', 20, 'Kishkindha Kanda, Sarga 20, Verse 20', 'किं मामेवं विलपतीं प्रेंणा त्वं नाभिभाषसे।
इमाः पश्य वरा बह्वीर्भार्यास्ते वानरेश्वर॥', 'kiṃ mām evaṃ vilapatīṃ preṃṇā tvaṃ nābhibhāṣase
imāḥ paśya varā bahvīr bhāryās te vānareśvara', null, 4020020),
('ramayana-4-20-21', 21, 'Kishkindha Kanda, Sarga 20, Verse 21', 'तस्या विलपितं श्रुत्वा वानर्यः सर्वतश्च ताः।
परिगृह्याङ्गदं दीनं दुःखार्ताः परिचुक्रुशुः॥', 'tasyā vilapitaṃ śrutvā vānaryaḥ sarvataś ca tāḥ
parigṛhyāṅgadaṃ dīnaṃ duḥkhārtāḥ paricukruśuḥ', null, 4020021),
('ramayana-4-20-22', 22, 'Kishkindha Kanda, Sarga 20, Verse 22', 'किमङ्गदं साङ्गद वीर बाहो विहाय यास्यद्य चिरप्रवासं।
न युक्तमेवं गुणसंनिकृष्टं विहाय पुत्रं प्रियपुत्र गन्तुम्॥', 'kim aṅgadaṃ sāṅgada vīra bāho vihāya yāsy adya cirapravāsaṃ
na yuktam evaṃ guṇasaṃnikṛṣṭaṃ vihāya putraṃ priyaputra gantum', null, 4020022),
('ramayana-4-20-23', 23, 'Kishkindha Kanda, Sarga 20, Verse 23', 'किमप्रियं ते प्रियचारुवेष कृतं मया नाथ सुतेन वा ते।
सहायिनीमद्य विहाय वीर यमक्षयं गच्छसि दुर्विनीतम्॥', 'kim apriyaṃ te priyacāruveṣa kṛtaṃ mayā nātha sutena vā te
sahāyinīm adya vihāya vīra yamakṣayaṃ gacchasi durvinītam', null, 4020023),
('ramayana-4-20-24', 24, 'Kishkindha Kanda, Sarga 20, Verse 24', 'यद्यप्रियं किं चिदसंप्रधार्य कृतं मया स्यात्तव दीर्घबाहो।
क्षमस्व मे तद्धरिवंश नाथ व्रजामि मूर्ध्ना तव वीर पादौ॥', 'yady apriyaṃ kiṃ cid asaṃpradhārya kṛtaṃ mayā syāt tava dīrghabāho
kṣamasva me tad dharivaṃśa nātha vrajāmi mūrdhnā tava vīra pādau', null, 4020024),
('ramayana-4-20-25', 25, 'Kishkindha Kanda, Sarga 20, Verse 25', 'तथा तु तारा करुणं रुदन्ती भर्तुः समीपे सह वानरीभिः।
व्यवस्यत प्रायमनिन्द्यवर्णा उपोपवेष्टुं भुवि यत्र वाली॥', 'tathā tu tārā karuṇaṃ rudantī bhartuḥ samīpe saha vānarībhiḥ
vyavasyata prāyam anindyavarṇā upopaveṣṭuṃ bhuvi yatra vālī', null, 4020025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 21 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-21-1', 1, 'Kishkindha Kanda, Sarga 21, Verse 1', 'ततो निपतितां तारां च्युतां तारामिवाम्बरात्।
शनैराश्वासयामास हनूमान्हरियूथपः॥', 'tato nipatitāṃ tārāṃ cyutāṃ tārām ivāmbarāt
śanair āśvāsayām āsa hanūmān hariyūthapaḥ', null, 4021001),
('ramayana-4-21-2', 2, 'Kishkindha Kanda, Sarga 21, Verse 2', 'गुणदोषकृतं जन्तुः स्वकर्मफलहेतुकम्।
अव्यग्रस्तदवाप्नोति सर्वं प्रेत्य शुभाशुभम्॥', 'guṇadoṣakṛtaṃ jantuḥ svakarmaphalahetukam
avyagras tad avāpnoti sarvaṃ pretya śubhāśubham', null, 4021002),
('ramayana-4-21-3', 3, 'Kishkindha Kanda, Sarga 21, Verse 3', 'शोच्या शोचसि कं शोच्यं दीनं दीनानुकम्पसे।
कश्च कस्यानुशोच्योऽस्ति देहेऽस्मिन्बुद्बुदोपमे॥', 'śocyā śocasi kaṃ śocyaṃ dīnaṃ dīnānukampase
kaś ca kasyānuśocyo ''sti dehe ''smin budbudopame', null, 4021003),
('ramayana-4-21-4', 4, 'Kishkindha Kanda, Sarga 21, Verse 4', 'अङ्गदस्तु कुमारोऽयं द्रष्टव्यो जीवपुत्रया।
आयत्या च विधेयानि समर्थान्यस्य चिन्तय॥', 'aṅgadas tu kumāro ''yaṃ draṣṭavyo jīvaputrayā
āyatyā ca vidheyāni samarthāny asya cintaya', null, 4021004),
('ramayana-4-21-5', 5, 'Kishkindha Kanda, Sarga 21, Verse 5', 'जानास्यनियतामेवं भूतानामागतिं गतिम्।
तस्माच्छुभं हि कर्तव्यं पण्डिते नैहलौकिकम्॥', 'jānāsy aniyatām evaṃ bhūtānām āgatiṃ gatim
tasmāc chubhaṃ hi kartavyaṃ paṇḍite naihalaukikam', null, 4021005),
('ramayana-4-21-6', 6, 'Kishkindha Kanda, Sarga 21, Verse 6', 'यस्मिन्हरिसहस्राणि प्रयुतान्यर्बुदानि च।
वर्तयन्ति कृतांशानि सोऽयं दिष्टान्तमागतः॥', 'yasmin harisahasrāṇi prayutāny arbudāni ca
vartayanti kṛtāṃśāni so ''yaṃ diṣṭāntam āgataḥ', null, 4021006),
('ramayana-4-21-7', 7, 'Kishkindha Kanda, Sarga 21, Verse 7', 'यदयं न्यायदृष्टार्थः सामदानक्षमापरः।
गतो धर्मजितां भूमिं नैनं शोचितुमर्हसि॥', 'yad ayaṃ nyāyadṛṣṭārthaḥ sāmadānakṣamāparaḥ
gato dharmajitāṃ bhūmiṃ nainaṃ śocitum arhasi', null, 4021007),
('ramayana-4-21-8', 8, 'Kishkindha Kanda, Sarga 21, Verse 8', 'सर्वे च हरिशार्दूल पुत्रश्चायं तवाङ्गदः।
हर्यृष्कपतिराज्यं च त्वत्सनाथमनिन्दिते॥', 'sarve ca hariśārdūla putraś cāyaṃ tavāṅgadaḥ
haryṛṣkapatirājyaṃ ca tvatsanātham anindite', null, 4021008),
('ramayana-4-21-9', 9, 'Kishkindha Kanda, Sarga 21, Verse 9', 'ताविमौ शोकसंतप्तौ शनैः प्रेरय भामिनि।
त्वया परिगृहीतोऽयमङ्गदः शास्तु मेदिनीम्॥', 'tāv imau śokasaṃtaptau śanaiḥ preraya bhāmini
tvayā parigṛhīto ''yam aṅgadaḥ śāstu medinīm', null, 4021009),
('ramayana-4-21-10', 10, 'Kishkindha Kanda, Sarga 21, Verse 10', 'संततिश्च यथादृष्टा कृत्यं यच्चापि साम्प्रतम्।
राज्ञस्तत्क्रियतां सर्वमेष कालस्य निश्चयः॥', 'saṃtatiś ca yathādṛṣṭā kṛtyaṃ yac cāpi sāmpratam
rājñas tat kriyatāṃ sarvam eṣa kālasya niścayaḥ', null, 4021010),
('ramayana-4-21-11', 11, 'Kishkindha Kanda, Sarga 21, Verse 11', 'संस्कार्यो हरिराजस्तु अङ्गदश्चाभिषिच्यताम्।
सिंहासनगतं पुत्रं पश्यन्ती शान्तिमेष्यसि॥', 'saṃskāryo harirājas tu aṅgadaś cābhiṣicyatām
siṃhāsanagataṃ putraṃ paśyantī śāntim eṣyasi', null, 4021011),
('ramayana-4-21-12', 12, 'Kishkindha Kanda, Sarga 21, Verse 12', 'सा तस्य वचनं श्रुत्वा भर्तृव्यसनपीडिता।
अब्रवीदुत्तरं तारा हनूमन्तमवस्थितम्॥', 'sā tasya vacanaṃ śrutvā bhartṛvyasanapīḍitā
abravīd uttaraṃ tārā hanūmantam avasthitam', null, 4021012),
('ramayana-4-21-13', 13, 'Kishkindha Kanda, Sarga 21, Verse 13', 'अङ्गद प्रतिरूपाणां पुत्राणामेकतः शतम्।
हतस्याप्यस्य वीरस्य गात्रसंश्लेषणं वरम्॥', 'aṅgada pratirūpāṇāṃ putrāṇām ekataḥ śatam
hatasyāpy asya vīrasya gātrasaṃśleṣaṇaṃ varam', null, 4021013),
('ramayana-4-21-14', 14, 'Kishkindha Kanda, Sarga 21, Verse 14', 'न चाहं हरिराजस्य प्रभवाम्यङ्गदस्य वा।
पितृव्यस्तस्य सुग्रीवः सर्वकार्येष्वनन्तरः॥', 'na cāhaṃ harirājasya prabhavāmy aṅgadasya vā
pitṛvyastasya sugrīvaḥ sarvakāryeṣv anantaraḥ', null, 4021014),
('ramayana-4-21-15', 15, 'Kishkindha Kanda, Sarga 21, Verse 15', 'न ह्येषा बुद्धिरास्थेया हनूमन्नङ्गदं प्रति।
पिता हि बन्धुः पुत्रस्य न माता हरिसत्तम॥', 'na hy eṣā buddhir āstheyā hanūmann aṅgadaṃ prati
pitā hi bandhuḥ putrasya na mātā harisattama', null, 4021015),
('ramayana-4-21-16', 16, 'Kishkindha Kanda, Sarga 21, Verse 16', 'न हि मम हरिराजसंश्रयात्क्षमतरमस्ति परत्र चेह वा।
अभिमुखहतवीरसेवितं शयनमिदं मम सेवितुं क्षमम्॥', 'na hi mama harirājasaṃśrayāt kṣamataram asti paratra ceha vā
abhimukhahatavīrasevitaṃ śayanam idaṃ mama sevituṃ kṣamam', null, 4021016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 22 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-22-1', 1, 'Kishkindha Kanda, Sarga 22, Verse 1', 'वीक्षमाणस्तु मन्दासुः सर्वतो मन्दमुच्छ्वसन्।
आदावेव तु सुग्रीवं ददर्श त्वात्मजाग्रतः॥', 'vīkṣamāṇas tu mandāsuḥ sarvato mandam ucchvasan
ādāv eva tu sugrīvaṃ dadarśa tv ātmajāgrataḥ', null, 4022001),
('ramayana-4-22-2', 2, 'Kishkindha Kanda, Sarga 22, Verse 2', 'तं प्राप्तविजयं वाली सुग्रीवं प्लवगेश्वरम्।
आभाष्य व्यक्तया वाचा सस्नेहमिदमब्रवीत्॥', 'taṃ prāptavijayaṃ vālī sugrīvaṃ plavageśvaram
ābhāṣya vyaktayā vācā sasneham idam abravīt', null, 4022002),
('ramayana-4-22-3', 3, 'Kishkindha Kanda, Sarga 22, Verse 3', 'सुग्रीवदोषेण न मां गन्तुमर्हसि किल्बिषात्।
कृष्यमाणं भविष्येण बुद्धिमोहेन मां बलात्॥', 'sugrīvadoṣeṇa na māṃ gantum arhasi kilbiṣāt
kṛṣyamāṇaṃ bhaviṣyeṇa buddhimohena māṃ balāt', null, 4022003),
('ramayana-4-22-4', 4, 'Kishkindha Kanda, Sarga 22, Verse 4', 'युगपद्विहितं तात न मन्ये सुखमावयोः।
सौहार्दं भ्रातृयुक्तं हि तदिदं जातमन्यथा॥', 'yugapadvihitaṃ tāta na manye sukham āvayoḥ
sauhārdaṃ bhrātṛyuktaṃ hi tad idaṃ jātam anyathā', null, 4022004),
('ramayana-4-22-5', 5, 'Kishkindha Kanda, Sarga 22, Verse 5', 'प्रतिपद्य त्वमद्यैव राज्यमेषां वनौकसाम्।
मामप्यद्यैव गच्छन्तं विद्धि वैवस्वतक्षयम्॥', 'pratipadya tvam adyaiva rājyam eṣāṃ vanaukasām
mām apy adyaiva gacchantaṃ viddhi vaivasvatakṣayam', null, 4022005),
('ramayana-4-22-6', 6, 'Kishkindha Kanda, Sarga 22, Verse 6', 'जीवितं च हि राज्यं च श्रियं च विपुलामिमाम्।
प्रजहाम्येष वै तूर्णं महच्चागर्हितं यशः॥', 'jīvitaṃ ca hi rājyaṃ ca śriyaṃ ca vipulām imām
prajahāmy eṣa vai tūrṇaṃ mahac cāgarhitaṃ yaśaḥ', null, 4022006),
('ramayana-4-22-7', 7, 'Kishkindha Kanda, Sarga 22, Verse 7', 'अस्यां त्वहमवस्थायां वीर वक्ष्यामि यद्वचः।
यद्यप्यसुकरं राजन्कर्तुमेव तदर्हसि॥', 'asyāṃ tv aham avasthāyāṃ vīra vakṣyāmi yad vacaḥ
yady apy asukaraṃ rājan kartum eva tad arhasi', null, 4022007),
('ramayana-4-22-8', 8, 'Kishkindha Kanda, Sarga 22, Verse 8', 'सुखार्हं सुखसंवृद्धं बालमेनमबालिशम्।
बाष्पपूर्णमुखं पश्य भूमौ पतितमङ्गदम्॥', 'sukhārhaṃ sukhasaṃvṛddhaṃ bālam enam abāliśam
bāṣpapūrṇamukhaṃ paśya bhūmau patitam aṅgadam', null, 4022008),
('ramayana-4-22-9', 9, 'Kishkindha Kanda, Sarga 22, Verse 9', 'मम प्राणैः प्रियतरं पुत्रं पुत्रमिवौरसं।
मया हीनमहीनार्थं सर्वतः परिपालय॥', 'mama prāṇaiḥ priyataraṃ putraṃ putram ivaurasaṃ
mayā hīnam ahīnārthaṃ sarvataḥ paripālaya', null, 4022009),
('ramayana-4-22-10', 10, 'Kishkindha Kanda, Sarga 22, Verse 10', 'त्वमप्यस्य हि दाता च परित्राता च सर्वतः।
भयेष्वभयदश्चैव यथाहं प्लवगेश्वर॥', 'tvam apy asya hi dātā ca paritrātā ca sarvataḥ
bhayeṣv abhayadaś caiva yathāhaṃ plavageśvara', null, 4022010),
('ramayana-4-22-11', 11, 'Kishkindha Kanda, Sarga 22, Verse 11', 'एष तारात्मजः श्रीमांस्त्वया तुल्यपराक्रमः।
रक्षसां तु वधे तेषामग्रतस्ते भविष्यति॥', 'eṣa tārātmajaḥ śrīmāṃs tvayā tulyaparākramaḥ
rakṣasāṃ tu vadhe teṣām agratas te bhaviṣyati', null, 4022011),
('ramayana-4-22-12', 12, 'Kishkindha Kanda, Sarga 22, Verse 12', 'अनुरूपाणि कर्माणि विक्रम्य बलवान्रणे।
करिष्यत्येष तारेयस्तरस्वी तरुणोऽङ्गदः॥', 'anurūpāṇi karmāṇi vikramya balavān raṇe
kariṣyaty eṣa tāreyas tarasvī taruṇo ''ṅgadaḥ', null, 4022012),
('ramayana-4-22-13', 13, 'Kishkindha Kanda, Sarga 22, Verse 13', 'सुषेणदुहिता चेयमर्थसूक्ष्मविनिश्चये।
औत्पातिके च विविधे सर्वतः परिनिष्ठिता॥', 'suṣeṇaduhitā ceyam arthasūkṣmaviniścaye
autpātike ca vividhe sarvataḥ pariniṣṭhitā', null, 4022013),
('ramayana-4-22-14', 14, 'Kishkindha Kanda, Sarga 22, Verse 14', 'यदेषा साध्विति ब्रूयात्कार्यं तन्मुक्तसंशयम्।
न हि तारामतं किं चिदन्यथा परिवर्तते॥', 'yad eṣā sādhv iti brūyāt kāryaṃ tan muktasaṃśayam
na hi tārāmataṃ kiṃ cid anyathā parivartate', null, 4022014),
('ramayana-4-22-15', 15, 'Kishkindha Kanda, Sarga 22, Verse 15', 'राघवस्य च ते कार्यं कर्तव्यमविशङ्कया।
स्यादधर्मो ह्यकरणे त्वां च हिंस्याद्विमानितः॥', 'rāghavasya ca te kāryaṃ kartavyam aviśaṅkayā
syād adharmo hy akaraṇe tvāṃ ca hiṃsyād vimānitaḥ', null, 4022015),
('ramayana-4-22-16', 16, 'Kishkindha Kanda, Sarga 22, Verse 16', 'इमां च मालामाधत्स्व दिव्यां सुग्रीवकाञ्चनीम्।
उदारा श्रीः स्थिता ह्यस्यां संप्रजह्यान्मृते मयि॥', 'imāṃ ca mālām ādhatsva divyāṃ sugrīvakāñcanīm
udārā śrīḥ sthitā hy asyāṃ saṃprajahyān mṛte mayi', null, 4022016),
('ramayana-4-22-17', 17, 'Kishkindha Kanda, Sarga 22, Verse 17', 'इत्येवमुक्तः सुग्रीवो वालिना भ्रातृसौहृदात्।
हर्षं त्यक्त्वा पुनर्दीनो ग्रहग्रस्त इवोडुराट्॥', 'ity evam uktaḥ sugrīvo vālinā bhrātṛsauhṛdāt
harṣaṃ tyaktvā punar dīno grahagrasta ivoḍurāṭ', null, 4022017),
('ramayana-4-22-18', 18, 'Kishkindha Kanda, Sarga 22, Verse 18', 'तद्वालिवचनाच्छान्तः कुर्वन्युक्तमतन्द्रितः।
जग्राह सोऽभ्यनुज्ञातो मालां तां चैव काञ्चनीम्॥', 'tad vālivacanāc chāntaḥ kurvan yuktam atandritaḥ
jagrāha so ''bhyanujñāto mālāṃ tāṃ caiva kāñcanīm', null, 4022018),
('ramayana-4-22-19', 19, 'Kishkindha Kanda, Sarga 22, Verse 19', 'तां मालां काञ्चनीं दत्त्वा वाली दृष्ट्वात्मजं स्थितम्।
संसिद्धः प्रेत्य भावाय स्नेहादङ्गदमब्रवीत्॥', 'tāṃ mālāṃ kāñcanīṃ dattvā vālī dṛṣṭvātmajaṃ sthitam
saṃsiddhaḥ pretya bhāvāya snehād aṅgadam abravīt', null, 4022019),
('ramayana-4-22-20', 20, 'Kishkindha Kanda, Sarga 22, Verse 20', 'देशकालौ भजस्वाद्य क्षममाणः प्रियाप्रिये।
सुखदुःखसहः काले सुग्रीववशगो भव॥', 'deśakālau bhajasvādya kṣamamāṇaḥ priyāpriye
sukhaduḥkhasahaḥ kāle sugrīvavaśago bhava', null, 4022020),
('ramayana-4-22-21', 21, 'Kishkindha Kanda, Sarga 22, Verse 21', 'यथा हि त्वं महाबाहो लालितः सततं मया।
न तथा वर्तमानं त्वां सुग्रीवो बहु मंस्यते॥', 'yathā hi tvaṃ mahābāho lālitaḥ satataṃ mayā
na tathā vartamānaṃ tvāṃ sugrīvo bahu maṃsyate', null, 4022021),
('ramayana-4-22-22', 22, 'Kishkindha Kanda, Sarga 22, Verse 22', 'मास्यामित्रैर्गतं गच्छेर्मा शत्रुभिररिंदम।
भर्तुरर्थपरो दान्तः सुग्रीववशगो भव॥', 'māsyāmitrair gataṃ gaccher mā śatrubhir ariṃdama
bhartur arthaparo dāntaḥ sugrīvavaśago bhava', null, 4022022),
('ramayana-4-22-23', 23, 'Kishkindha Kanda, Sarga 22, Verse 23', 'न चातिप्रणयः कार्यः कर्तव्योऽप्रणयश्च ते।
उभयं हि महादोषं तस्मादन्तरदृग्भव॥', 'na cātipraṇayaḥ kāryaḥ kartavyo ''praṇayaś ca te
ubhayaṃ hi mahādoṣaṃ tasmād antaradṛg bhava', null, 4022023),
('ramayana-4-22-24', 24, 'Kishkindha Kanda, Sarga 22, Verse 24', 'इत्युक्त्वाथ विवृत्ताक्षः शरसंपीडितो भृशम्।
विवृतैर्दशनैर्भीमैर्बभूवोत्क्रान्तजीवितः॥', 'ity uktvātha vivṛttākṣaḥ śarasaṃpīḍito bhṛśam
vivṛtair daśanair bhīmair babhūvotkrāntajīvitaḥ', null, 4022024),
('ramayana-4-22-25', 25, 'Kishkindha Kanda, Sarga 22, Verse 25', 'हते तु वीरे प्लवगाधिपे तदा प्लवंगमास्तत्र न शर्म लेभिरे।
वनेचराः सिंहयुते महावने यथा हि गावो निहते गवां पतौ॥', 'hate tu vīre plavagādhipe tadā plavaṃgamās tatra na śarma lebhire
vanecarāḥ siṃhayute mahāvane yathā hi gāvo nihate gavāṃ patau', null, 4022025),
('ramayana-4-22-26', 26, 'Kishkindha Kanda, Sarga 22, Verse 26', 'ततस्तु तारा व्यसनार्णव प्लुता मृतस्या भर्तुर्वदनं समीक्ष्य सा।
जगाम भूमिं परिरभ्य वालिनं महाद्रुमं छिन्नमिवाश्रिता लता॥', 'tatas tu tārā vyasanārṇava plutā mṛtasyā bhartur vadanaṃ samīkṣya sā
jagāma bhūmiṃ parirabhya vālinaṃ mahādrumaṃ chinnam ivāśritā latā', null, 4022026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 23 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-23-1', 1, 'Kishkindha Kanda, Sarga 23, Verse 1', 'ततः समुपजिघ्रन्ती कपिराजस्य तन्मुखम्।
पतिं लोकाच्च्युतं तारा मृतं वचनमब्रवीत्॥', 'tataḥ samupajighrantī kapirājasya tanmukham
patiṃ lokāc cyutaṃ tārā mṛtaṃ vacanam abravīt', null, 4023001),
('ramayana-4-23-2', 2, 'Kishkindha Kanda, Sarga 23, Verse 2', 'शेषे त्वं विषमे दुःखमकृत्वा वचनं मम।
उपलोपचिते वीर सुदुःखे वसुधातले॥', 'śeṣe tvaṃ viṣame duḥkham akṛtvā vacanaṃ mama
upalopacite vīra suduḥkhe vasudhātale', null, 4023002),
('ramayana-4-23-3', 3, 'Kishkindha Kanda, Sarga 23, Verse 3', 'मत्तः प्रियतरा नूनं वानरेन्द्र मही तव।
शेषे हि तां परिष्वज्य मां च न प्रतिभाषसे॥', 'mattaḥ priyatarā nūnaṃ vānarendra mahī tava
śeṣe hi tāṃ pariṣvajya māṃ ca na pratibhāṣase', null, 4023003),
('ramayana-4-23-4', 4, 'Kishkindha Kanda, Sarga 23, Verse 4', 'सुग्रीव एव विक्रान्तो वीर साहसिक प्रिय।
ऋक्षवानरमुख्यास्त्वां बलिनं पर्युपासते॥', 'sugrīva eva vikrānto vīra sāhasika priya
ṛkṣavānaramukhyās tvāṃ balinaṃ paryupāsate', null, 4023004),
('ramayana-4-23-5', 5, 'Kishkindha Kanda, Sarga 23, Verse 5', 'एषां विलपितं कृच्छ्रमङ्गदस्य च शोचतः।
मम चेमां गिरं श्रुत्वा किं त्वं न प्रतिबुध्यसे॥', 'eṣāṃ vilapitaṃ kṛcchram aṅgadasya ca śocataḥ
mama cemāṃ giraṃ śrutvā kiṃ tvaṃ na pratibudhyase', null, 4023005),
('ramayana-4-23-6', 6, 'Kishkindha Kanda, Sarga 23, Verse 6', 'इदं तच्छूरशयनं यत्र शेषे हतो युधि।
शायिता निहता यत्र त्वयैव रिपवः पुरा॥', 'idaṃ tac chūraśayanaṃ yatra śeṣe hato yudhi
śāyitā nihatā yatra tvayaiva ripavaḥ purā', null, 4023006),
('ramayana-4-23-7', 7, 'Kishkindha Kanda, Sarga 23, Verse 7', 'विशुद्धसत्त्वाभिजन प्रिययुद्ध मम प्रिय।
मामनाथां विहायैकां गतस्त्वमसि मानद॥', 'viśuddhasattvābhijana priyayuddha mama priya
mām anāthāṃ vihāyaikāṃ gatas tvam asi mānada', null, 4023007),
('ramayana-4-23-8', 8, 'Kishkindha Kanda, Sarga 23, Verse 8', 'शूराय न प्रदातव्या कन्या खलु विपश्चिता।
शूरभार्यां हतां पश्य सद्यो मां विधवां कृताम्॥', 'śūrāya na pradātavyā kanyā khalu vipaścitā
śūrabhāryāṃ hatāṃ paśya sadyo māṃ vidhavāṃ kṛtām', null, 4023008),
('ramayana-4-23-9', 9, 'Kishkindha Kanda, Sarga 23, Verse 9', 'अवभग्नश्च मे मानो भग्ना मे शाश्वती गतिः।
अगाधे च निमग्नास्मि विपुले शोकसागरे॥', 'avabhagnaś ca me māno bhagnā me śāśvatī gatiḥ
agādhe ca nimagnāsmi vipule śokasāgare', null, 4023009),
('ramayana-4-23-10', 10, 'Kishkindha Kanda, Sarga 23, Verse 10', 'अश्मसारमयं नूनमिदं मे हृदयं दृढम्।
भर्तारं निहतं दृष्ट्वा यन्नाद्य शतधा गतम्॥', 'aśmasāramayaṃ nūnam idaṃ me hṛdayaṃ dṛḍham
bhartāraṃ nihataṃ dṛṣṭvā yan nādya śatadhā gatam', null, 4023010),
('ramayana-4-23-11', 11, 'Kishkindha Kanda, Sarga 23, Verse 11', 'सुहृच्चैव हि भर्ता च प्रकृत्या च मम प्रियः।
आहवे च पराक्रान्तः शूरः पञ्चत्वमागतः॥', 'suhṛc caiva hi bhartā ca prakṛtyā ca mama priyaḥ
āhave ca parākrāntaḥ śūraḥ pañcatvam āgataḥ', null, 4023011),
('ramayana-4-23-12', 12, 'Kishkindha Kanda, Sarga 23, Verse 12', 'पतिहीना तु या नारी कामं भवतु पुत्रिणी।
धनधान्यैः सुपूर्णापि विधवेत्युच्यते बुधैः॥', 'patihīnā tu yā nārī kāmaṃ bhavatu putriṇī
dhanadhānyaiḥ supūrṇāpi vidhavety ucyate budhaiḥ', null, 4023012),
('ramayana-4-23-13', 13, 'Kishkindha Kanda, Sarga 23, Verse 13', 'स्वगात्रप्रभवे वीर शेषे रुधिरमण्डले।
कृमिरागपरिस्तोमे त्वमेवं शयने यथा॥', 'svagātraprabhave vīra śeṣe rudhiramaṇḍale
kṛmirāgaparistome tvam evaṃ śayane yathā', null, 4023013),
('ramayana-4-23-14', 14, 'Kishkindha Kanda, Sarga 23, Verse 14', 'रेणुशोणितसंवीतं गात्रं तव समन्ततः।
परिरब्धुं न शक्नोमि भुजाभ्यां प्लवगर्षभ॥', 'reṇuśoṇitasaṃvītaṃ gātraṃ tava samantataḥ
parirabdhuṃ na śaknomi bhujābhyāṃ plavagarṣabha', null, 4023014),
('ramayana-4-23-15', 15, 'Kishkindha Kanda, Sarga 23, Verse 15', 'कृतकृत्योऽद्य सुग्रीवो वैरेऽस्मिन्नतिदारुणे।
यस्य रामविमुक्तेन हृतमेकेषुणा भयम्॥', 'kṛtakṛtyo ''dya sugrīvo vaire ''sminn atidāruṇe
yasya rāmavimuktena hṛtam ekeṣuṇā bhayam', null, 4023015),
('ramayana-4-23-16', 16, 'Kishkindha Kanda, Sarga 23, Verse 16', 'शरेण हृदि लग्नेन गात्रसंस्पर्शने तव।
वार्यामि त्वां निरीक्षन्ती त्वयि पञ्चत्वमागते॥', 'śareṇa hṛdi lagnena gātrasaṃsparśane tava
vāryāmi tvāṃ nirīkṣantī tvayi pañcatvam āgate', null, 4023016),
('ramayana-4-23-17', 17, 'Kishkindha Kanda, Sarga 23, Verse 17', 'उद्बबर्ह शरं नीलस्तस्य गात्रगतं तदा।
गिरिगह्वरसंलीनं दीप्तमाशीविषं यथा॥', 'udbabarha śaraṃ nīlas tasya gātragataṃ tadā
girigahvarasaṃlīnaṃ dīptam āśīviṣaṃ yathā', null, 4023017),
('ramayana-4-23-18', 18, 'Kishkindha Kanda, Sarga 23, Verse 18', 'तस्य निष्कृष्यमाणस्य बाणस्य च बभौ द्युतिः।
अस्तमस्तकसंरुद्धो रश्मिर्दिनकरादिव॥', 'tasya niṣkṛṣyamāṇasya bāṇasya ca babhau dyutiḥ
astamastakasaṃruddho raśmir dinakarād iva', null, 4023018),
('ramayana-4-23-19', 19, 'Kishkindha Kanda, Sarga 23, Verse 19', 'पेतुः क्षतजधारास्तु व्रणेभ्यस्तस्य सर्वशः।
ताम्रगैरिकसंपृक्ता धारा इव धराधरात्॥', 'petuḥ kṣatajadhārās tu vraṇebhyas tasya sarvaśaḥ
tāmragairikasaṃpṛktā dhārā iva dharādharāt', null, 4023019),
('ramayana-4-23-20', 20, 'Kishkindha Kanda, Sarga 23, Verse 20', 'अवकीर्णं विमार्जन्ती भर्तारं रणरेणुना।
अस्रैर्नयनजैः शूरं सिषेचास्त्रसमाहतम्॥', 'avakīrṇaṃ vimārjantī bhartāraṃ raṇareṇunā
asrair nayanajaiḥ śūraṃ siṣecāstrasamāhatam', null, 4023020),
('ramayana-4-23-21', 21, 'Kishkindha Kanda, Sarga 23, Verse 21', 'रुधिरोक्षितसर्वाङ्गं दृष्ट्वा विनिहतं पतिम्।
उवाच तारा पिङ्गाक्षं पुत्रमङ्गदमङ्गना॥', 'rudhirokṣitasarvāṅgaṃ dṛṣṭvā vinihataṃ patim
uvāca tārā piṅgākṣaṃ putram aṅgadam aṅganā', null, 4023021),
('ramayana-4-23-22', 22, 'Kishkindha Kanda, Sarga 23, Verse 22', 'अवस्थां पश्चिमां पश्य पितुः पुत्र सुदारुणाम्।
संप्रसक्तस्य वैरस्य गतोऽन्तः पापकर्मणा॥', 'avasthāṃ paścimāṃ paśya pituḥ putra sudāruṇām
saṃprasaktasya vairasya gato ''ntaḥ pāpakarmaṇā', null, 4023022),
('ramayana-4-23-23', 23, 'Kishkindha Kanda, Sarga 23, Verse 23', 'बालसूर्योदयतनुं प्रयान्तं यमसादनम्।
अभिवादय राजानं पितरं पुत्र मानदम्॥', 'bālasūryodayatanuṃ prayāntaṃ yamasādanam
abhivādaya rājānaṃ pitaraṃ putra mānadam', null, 4023023),
('ramayana-4-23-24', 24, 'Kishkindha Kanda, Sarga 23, Verse 24', 'एवमुक्तः समुत्थाय जग्राह चरणौ पितुः।
भुजाभ्यां पीनवृताभ्यामङ्गदोऽहमिति ब्रुवन्॥', 'evam uktaḥ samutthāya jagrāha caraṇau pituḥ
bhujābhyāṃ pīnavṛtābhyām aṅgado ''ham iti bruvan', null, 4023024),
('ramayana-4-23-25', 25, 'Kishkindha Kanda, Sarga 23, Verse 25', 'अभिवादयमानं त्वामङ्गदं त्वं यथापुरा।
दीर्घायुर्भव पुत्रेति किमर्थं नाभिभाषसे॥', 'abhivādayamānaṃ tvām aṅgadaṃ tvaṃ yathāpurā
dīrghāyur bhava putreti kimarthaṃ nābhibhāṣase', null, 4023025),
('ramayana-4-23-26', 26, 'Kishkindha Kanda, Sarga 23, Verse 26', 'अहं पुत्रसहाया त्वामुपासे गतचेतनम्।
सिंहेन निहतं सद्यो गौः सवत्सेव गोवृषम्॥', 'ahaṃ putrasahāyā tvām upāse gatacetanam
siṃhena nihataṃ sadyo gauḥ savatseva govṛṣam', null, 4023026),
('ramayana-4-23-27', 27, 'Kishkindha Kanda, Sarga 23, Verse 27', 'इष्ट्वा संग्रामयज्ञेन नानाप्रहरणाम्भसा।
अस्मिन्नवभृथे स्नातः कथं पत्न्या मया विना॥', 'iṣṭvā saṃgrāmayajñena nānāpraharaṇāmbhasā
asminn avabhṛthe snātaḥ kathaṃ patnyā mayā vinā', null, 4023027),
('ramayana-4-23-28', 28, 'Kishkindha Kanda, Sarga 23, Verse 28', 'या दत्ता देवराजेन तव तुष्टेन संयुगे।
शातकुम्भमयीं मालां तां ते पश्यामि नेह किम्॥', 'yā dattā devarājena tava tuṣṭena saṃyuge
śātakumbhamayīṃ mālāṃ tāṃ te paśyāmi neha kim', null, 4023028),
('ramayana-4-23-29', 29, 'Kishkindha Kanda, Sarga 23, Verse 29', 'राजश्रीर्न जहाति त्वां गतासुमपि मानद।
सूर्यस्यावर्तमानस्य शैलराजमिव प्रभा॥', 'rājaśrīr na jahāti tvāṃ gatāsum api mānada
sūryasyāvartamānasya śailarājam iva prabhā', null, 4023029),
('ramayana-4-23-30', 30, 'Kishkindha Kanda, Sarga 23, Verse 30', 'न मे वचः पथ्यमिदं त्वया कृतं न चास्मि शक्ता हि निवारणे तव।
हता सपुत्रास्मि हतेन संयुगे सह त्वया श्रीर्विजहाति मामिह॥', 'na me vacaḥ pathyam idaṃ tvayā kṛtaṃ na cāsmi śaktā hi nivāraṇe tava
hatā saputrāsmi hatena saṃyuge saha tvayā śrīr vijahāti mām iha', null, 4023030)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 24 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-24-1', 1, 'Kishkindha Kanda, Sarga 24, Verse 1', 'गतासुं वालिनं दृष्ट्वा राघवस्तदनन्तरम्।
अब्रवीत्प्रश्रितं वाक्यं सुग्रीवं शत्रुतापनः॥', 'gatāsuṃ vālinaṃ dṛṣṭvā rāghavas tadanantaram
abravīt praśritaṃ vākyaṃ sugrīvaṃ śatrutāpanaḥ', null, 4024001),
('ramayana-4-24-2', 2, 'Kishkindha Kanda, Sarga 24, Verse 2', 'न शोकपरितापेन श्रेयसा युज्यते मृतः।
यदत्रानन्तरं कार्यं तत्समाधातुमर्हथ॥', 'na śokaparitāpena śreyasā yujyate mṛtaḥ
yad atrānantaraṃ kāryaṃ tat samādhātum arhatha', null, 4024002),
('ramayana-4-24-3', 3, 'Kishkindha Kanda, Sarga 24, Verse 3', 'लोकवृत्तमनुष्ठेयं कृतं वो बाष्पमोक्षणम्।
न कालादुत्तरं किं चित्कर्म शक्यमुपासितुम्॥', 'lokavṛttam anuṣṭheyaṃ kṛtaṃ vo bāṣpamokṣaṇam
na kālād uttaraṃ kiṃ cit karma śakyam upāsitum', null, 4024003),
('ramayana-4-24-4', 4, 'Kishkindha Kanda, Sarga 24, Verse 4', 'नियतः कारणं लोके नियतिः कर्मसाधनम्।
नियतिः सर्वभूतानां नियोगेष्विह कारणम्॥', 'niyataḥ kāraṇaṃ loke niyatiḥ karmasādhanam
niyatiḥ sarvabhūtānāṃ niyogeṣv iha kāraṇam', null, 4024004),
('ramayana-4-24-5', 5, 'Kishkindha Kanda, Sarga 24, Verse 5', 'न कर्ता कस्य चित्कश्चिन्नियोगे चापि नेश्वरः।
स्वभावे वर्तते लोकस्तस्य कालः परायणम्॥', 'na kartā kasya cit kaś cin niyoge cāpi neśvaraḥ
svabhāve vartate lokas tasya kālaḥ parāyaṇam', null, 4024005),
('ramayana-4-24-6', 6, 'Kishkindha Kanda, Sarga 24, Verse 6', 'न कालः कालमत्येति न कालः परिहीयते।
स्वभावं वा समासाद्य न कश्चिदतिवर्तते॥', 'na kālaḥ kālam atyeti na kālaḥ parihīyate
svabhāvaṃ vā samāsādya na kaś cid ativartate', null, 4024006),
('ramayana-4-24-7', 7, 'Kishkindha Kanda, Sarga 24, Verse 7', 'न कालस्यास्ति बन्धुत्वं न हेतुर्न पराक्रमः।
न मित्रज्ञातिसंबन्धः कारणं नात्मनो वशः॥', 'na kālasyāsti bandhutvaṃ na hetur na parākramaḥ
na mitrajñātisaṃbandhaḥ kāraṇaṃ nātmano vaśaḥ', null, 4024007),
('ramayana-4-24-8', 8, 'Kishkindha Kanda, Sarga 24, Verse 8', 'किं तु काल परीणामो द्रष्टव्यः साधु पश्यता।
धर्मश्चार्थश्च कामश्च कालक्रमसमाहिताः॥', 'kiṃ tu kāla parīṇāmo draṣṭavyaḥ sādhu paśyatā
dharmaś cārthaś ca kāmaś ca kālakramasamāhitāḥ', null, 4024008),
('ramayana-4-24-9', 9, 'Kishkindha Kanda, Sarga 24, Verse 9', 'इतः स्वां प्रकृतिं वाली गतः प्राप्तः क्रियाफलम्।
धर्मार्थकामसंयोगैः पवित्रं प्लवगेश्वर॥', 'itaḥ svāṃ prakṛtiṃ vālī gataḥ prāptaḥ kriyāphalam
dharmārthakāmasaṃyogaiḥ pavitraṃ plavageśvara', null, 4024009),
('ramayana-4-24-10', 10, 'Kishkindha Kanda, Sarga 24, Verse 10', 'स्वधर्मस्य च संयोगाज्जितस्तेन महात्मना।
स्वर्गः परिगृहीतश्च प्राणानपरिरक्षता॥', 'svadharmasya ca saṃyogāj jitas tena mahātmanā
svargaḥ parigṛhītaś ca prāṇān aparirakṣatā', null, 4024010),
('ramayana-4-24-11', 11, 'Kishkindha Kanda, Sarga 24, Verse 11', 'एषा वै नियतिः श्रेष्ठा यां गतो हरियूथपः।
तदलं परितापेन प्राप्तकालमुपास्यताम्॥', 'eṣā vai niyatiḥ śreṣṭhā yāṃ gato hariyūthapaḥ
tad alaṃ paritāpena prāptakālam upāsyatām', null, 4024011),
('ramayana-4-24-12', 12, 'Kishkindha Kanda, Sarga 24, Verse 12', 'वचनान्ते तु रामस्य लक्ष्मणः परवीरहा।
अवदत्प्रश्रितं वाक्यं सुग्रीवं गतचेतसं॥', 'vacanānte tu rāmasya lakṣmaṇaḥ paravīrahā
avadat praśritaṃ vākyaṃ sugrīvaṃ gatacetasaṃ', null, 4024012),
('ramayana-4-24-13', 13, 'Kishkindha Kanda, Sarga 24, Verse 13', 'कुरु त्वमस्य सुग्रीव प्रेतकार्यमनन्तरम्।
ताराङ्गदाभ्यां सहितो वालिनो दहनं प्रति॥', 'kuru tvam asya sugrīva pretakāryam anantaram
tārāṅgadābhyāṃ sahito vālino dahanaṃ prati', null, 4024013),
('ramayana-4-24-14', 14, 'Kishkindha Kanda, Sarga 24, Verse 14', 'समाज्ञापय काष्ठानि शुष्काणि च बहूनि च।
चन्दनानि च दिव्यानि वालिसंस्कारकारणात्॥', 'samājñāpaya kāṣṭhāni śuṣkāṇi ca bahūni ca
candanāni ca divyāni vālisaṃskārakāraṇāt', null, 4024014),
('ramayana-4-24-15', 15, 'Kishkindha Kanda, Sarga 24, Verse 15', 'समाश्वासय चैनं त्वमङ्गदं दीनचेतसं।
मा भूर्बालिशबुद्धिस्त्वं त्वदधीनमिदं पुरम्॥', 'samāśvāsaya cainaṃ tvam aṅgadaṃ dīnacetasaṃ
mā bhūr bāliśabuddhis tvaṃ tvadadhīnam idaṃ puram', null, 4024015),
('ramayana-4-24-16', 16, 'Kishkindha Kanda, Sarga 24, Verse 16', 'अङ्गदस्त्वानयेन्माल्यं वस्त्राणि विविधानि च।
घृतं तैलमथो गन्धान्यच्चात्र समनन्तरम्॥', 'aṅgadas tv ānayen mālyaṃ vastrāṇi vividhāni ca
ghṛtaṃ tailam atho gandhān yac cātra samanantaram', null, 4024016),
('ramayana-4-24-17', 17, 'Kishkindha Kanda, Sarga 24, Verse 17', 'त्वं तार शिबिकां शीघ्रमादायागच्छ संभ्रमात्।
त्वरा गुणवती युक्ता ह्यस्मिन्काले विशेषतः॥', 'tvaṃ tāra śibikāṃ śīghram ādāyāgaccha saṃbhramāt
tvarā guṇavatī yuktā hy asmin kāle viśeṣataḥ', null, 4024017),
('ramayana-4-24-18', 18, 'Kishkindha Kanda, Sarga 24, Verse 18', 'सज्जीभवन्तु प्लवगाः शिबिकावाहनोचिताः।
समर्था बलिनश्चैव निर्हरिष्यन्ति वालिनम्॥', 'sajjībhavantu plavagāḥ śibikāvāhanocitāḥ
samarthā balinaś caiva nirhariṣyanti vālinam', null, 4024018),
('ramayana-4-24-19', 19, 'Kishkindha Kanda, Sarga 24, Verse 19', 'एवमुक्त्वा तु सुग्रीवं सुमित्रानन्दवर्धनः।
तस्थौ भ्रातृसमीपस्थो लक्ष्मणः परवीरहा॥', 'evam uktvā tu sugrīvaṃ sumitrānandavardhanaḥ
tasthau bhrātṛsamīpastho lakṣmaṇaḥ paravīrahā', null, 4024019),
('ramayana-4-24-20', 20, 'Kishkindha Kanda, Sarga 24, Verse 20', 'लक्ष्मणस्य वचः श्रुत्वा तारः संभ्रान्तमानसः।
प्रविवेश गुहां शीघ्रं शिबिकासक्तमानसः॥', 'lakṣmaṇasya vacaḥ śrutvā tāraḥ saṃbhrāntamānasaḥ
praviveśa guhāṃ śīghraṃ śibikāsaktamānasaḥ', null, 4024020),
('ramayana-4-24-21', 21, 'Kishkindha Kanda, Sarga 24, Verse 21', 'आदाय शिबिकां तारः स तु पर्यापयत्पुनः।
वानरैरुह्यमानां तां शूरैरुद्वहनोचितैः॥', 'ādāya śibikāṃ tāraḥ sa tu paryāpayat punaḥ
vānarair uhyamānāṃ tāṃ śūrair udvahanocitaiḥ', null, 4024021),
('ramayana-4-24-22', 22, 'Kishkindha Kanda, Sarga 24, Verse 22', 'ततो वालिनमुद्यम्य सुग्रीवः शिबिकां तदा।
आरोपयत विक्रोशन्नङ्गदेन सहैव तु॥', 'tato vālinam udyamya sugrīvaḥ śibikāṃ tadā
āropayata vikrośann aṅgadena sahaiva tu', null, 4024022),
('ramayana-4-24-23', 23, 'Kishkindha Kanda, Sarga 24, Verse 23', 'आरोप्य शिबिकां चैव वालिनं गतजीवितम्।
अलंकारैश्च विविधैर्माल्यैर्वस्त्रैश्च भूषितम्॥', 'āropya śibikāṃ caiva vālinaṃ gatajīvitam
alaṃkāraiś ca vividhair mālyair vastraiś ca bhūṣitam', null, 4024023),
('ramayana-4-24-24', 24, 'Kishkindha Kanda, Sarga 24, Verse 24', 'आज्ञापयत्तदा राजा सुग्रीवः प्लवगेश्वरः।
और्ध्वदेहिकमार्यस्य क्रियतामनुरूपतः॥', 'ājñāpayat tadā rājā sugrīvaḥ plavageśvaraḥ
aurdhvadehikam āryasya kriyatām anurūpataḥ', null, 4024024),
('ramayana-4-24-25', 25, 'Kishkindha Kanda, Sarga 24, Verse 25', 'विश्राणयन्तो रत्नानि विविधानि बहूनि च।
अग्रतः प्लवगा यान्तु शिबिका तदनन्तरम्॥', 'viśrāṇayanto ratnāni vividhāni bahūni ca
agrataḥ plavagā yāntu śibikā tadanantaram', null, 4024025),
('ramayana-4-24-26', 26, 'Kishkindha Kanda, Sarga 24, Verse 26', 'राज्ञामृद्धिविशेषा हि दृश्यन्ते भुवि यादृशाः।
तादृशं वालिनः क्षिप्रं प्राकुर्वन्नौर्ध्वदेहिकम्॥', 'rājñām ṛddhiviśeṣā hi dṛśyante bhuvi yādṛśāḥ
tādṛśaṃ vālinaḥ kṣipraṃ prākurvann aurdhvadehikam', null, 4024026),
('ramayana-4-24-27', 27, 'Kishkindha Kanda, Sarga 24, Verse 27', 'अङ्गदमप्रिगृह्याशु तारप्रभृतयस्तथा।
क्रोशन्तः प्रययुः सर्वे वानरा हतबान्धवाः॥', 'aṅgadam aprigṛhyāśu tāraprabhṛtayas tathā
krośantaḥ prayayuḥ sarve vānarā hatabāndhavāḥ', null, 4024027),
('ramayana-4-24-28', 28, 'Kishkindha Kanda, Sarga 24, Verse 28', 'ताराप्रभृतयः सर्वा वानर्यो हतयूथपाः।
अनुजग्मुर्हि भर्तारं क्रोशन्त्यः करुणस्वनाः॥', 'tārāprabhṛtayaḥ sarvā vānaryo hatayūthapāḥ
anujagmur hi bhartāraṃ krośantyaḥ karuṇasvanāḥ', null, 4024028),
('ramayana-4-24-29', 29, 'Kishkindha Kanda, Sarga 24, Verse 29', 'तासां रुदितशब्देन वानरीणां वनान्तरे।
वनानि गिरयः सर्वे विक्रोशन्तीव सर्वतः॥', 'tāsāṃ ruditaśabdena vānarīṇāṃ vanāntare
vanāni girayaḥ sarve vikrośantīva sarvataḥ', null, 4024029),
('ramayana-4-24-30', 30, 'Kishkindha Kanda, Sarga 24, Verse 30', 'पुलिने गिरिनद्यास्तु विविक्ते जलसंवृते।
चितां चक्रुः सुबहवो वानरा वनचारिणः॥', 'puline girinadyās tu vivikte jalasaṃvṛte
citāṃ cakruḥ subahavo vānarā vanacāriṇaḥ', null, 4024030),
('ramayana-4-24-31', 31, 'Kishkindha Kanda, Sarga 24, Verse 31', 'अवरोप्य ततः स्कन्धाच्छिबिकां वहनोचिताः।
तस्थुरेकान्तमाश्रित्य सर्वे शोकसमन्विताः॥', 'avaropya tataḥ skandhāc chibikāṃ vahanocitāḥ
tasthur ekāntam āśritya sarve śokasamanvitāḥ', null, 4024031),
('ramayana-4-24-32', 32, 'Kishkindha Kanda, Sarga 24, Verse 32', 'ततस्तारा पतिं दृष्ट्वा शिबिकातलशायिनम्।
आरोप्याङ्के शिरस्तस्य विललाप सुदुःखिता॥', 'tatas tārā patiṃ dṛṣṭvā śibikātalaśāyinam
āropyāṅke śiras tasya vilalāpa suduḥkhitā', null, 4024032),
('ramayana-4-24-33', 33, 'Kishkindha Kanda, Sarga 24, Verse 33', 'जनं च पश्यसीमं त्वं कस्माच्छोकाभिपीडितम्।
प्रहृष्टमिव ते वक्त्रं गतासोरपि मानद।
अस्तार्कसमवर्णं च लक्ष्यते जीवतो यथा॥', 'janaṃ ca paśyasīmaṃ tvaṃ kasmāc chokābhipīḍitam
prahṛṣṭam iva te vaktraṃ gatāsor api mānada
astārkasamavarṇaṃ ca lakṣyate jīvato yathā', null, 4024033),
('ramayana-4-24-34', 34, 'Kishkindha Kanda, Sarga 24, Verse 34', 'एष त्वां रामरूपेण कालः कर्षति वानर।
येन स्म विधवाः सर्वाः कृता एकेषुणा रणे॥', 'eṣa tvāṃ rāmarūpeṇa kālaḥ karṣati vānara
yena sma vidhavāḥ sarvāḥ kṛtā ekeṣuṇā raṇe', null, 4024034),
('ramayana-4-24-35', 35, 'Kishkindha Kanda, Sarga 24, Verse 35', 'इमास्तास्तव राजेन्द्रवानर्यो वल्लभाः सदा।
पादैर्विकृष्टमध्वानमागताः किं न बुध्यसे॥', 'imās tās tava rājendravānaryo vallabhāḥ sadā
pādair vikṛṣṭam adhvānam āgatāḥ kiṃ na budhyase', null, 4024035),
('ramayana-4-24-36', 36, 'Kishkindha Kanda, Sarga 24, Verse 36', 'तवेष्टा ननु नामैता भार्याश्चन्द्रनिभाननाः।
इदानीं नेक्षसे कस्मात्सुग्रीवं प्लवगेश्वरम्॥', 'taveṣṭā nanu nāmaitā bhāryāś candranibhānanāḥ
idānīṃ nekṣase kasmāt sugrīvaṃ plavageśvaram', null, 4024036),
('ramayana-4-24-37', 37, 'Kishkindha Kanda, Sarga 24, Verse 37', 'एते हि सचिवा राजंस्तारप्रभृतयस्तव।
पुरवासिजनश्चायं परिवार्यासतेऽनघ॥', 'ete hi sacivā rājaṃs tāraprabhṛtayas tava
puravāsijanaś cāyaṃ parivāryāsate ''nagha', null, 4024037),
('ramayana-4-24-38', 38, 'Kishkindha Kanda, Sarga 24, Verse 38', 'विसर्जयैनान्प्रवलान्यथोचितमरिंदम।
ततः क्रीडामहे सर्वा वनेषु मदिरोत्कटाः॥', 'visarjayainān pravalān yathocitam ariṃdama
tataḥ krīḍāmahe sarvā vaneṣu madirotkaṭāḥ', null, 4024038),
('ramayana-4-24-39', 39, 'Kishkindha Kanda, Sarga 24, Verse 39', 'एवं विलपतीं तारां पतिशोकपरिप्लुताम्।
उत्थापयन्ति स्म तदा वानर्यः शोककर्शिताः॥', 'evaṃ vilapatīṃ tārāṃ patiśokapariplutām
utthāpayanti sma tadā vānaryaḥ śokakarśitāḥ', null, 4024039),
('ramayana-4-24-40', 40, 'Kishkindha Kanda, Sarga 24, Verse 40', 'सुग्रीवेण ततः सार्धमङ्गदः पितरं रुदन्।
चितामारोपयामास शोकेनाभिहतेन्द्रियः॥', 'sugrīveṇa tataḥ sārdham aṅgadaḥ pitaraṃ rudan
citām āropayām āsa śokenābhihatendriyaḥ', null, 4024040),
('ramayana-4-24-41', 41, 'Kishkindha Kanda, Sarga 24, Verse 41', 'ततोऽग्निं विधिवद्दत्त्वा सोऽपसव्यं चकार ह।
पितरं दीर्घमध्वानं प्रस्थितं व्याकुलेन्द्रियः॥', 'tato ''gniṃ vidhivad dattvā so ''pasavyaṃ cakāra ha
pitaraṃ dīrgham adhvānaṃ prasthitaṃ vyākulendriyaḥ', null, 4024041),
('ramayana-4-24-42', 42, 'Kishkindha Kanda, Sarga 24, Verse 42', 'संस्कृत्य वालिनं ते तु विधिपूर्वं प्लवंगमाः।
आजग्मुरुदकं कर्तुं नदीं शीतजलां शुभाम्॥', 'saṃskṛtya vālinaṃ te tu vidhipūrvaṃ plavaṃgamāḥ
ājagmur udakaṃ kartuṃ nadīṃ śītajalāṃ śubhām', null, 4024042),
('ramayana-4-24-43', 43, 'Kishkindha Kanda, Sarga 24, Verse 43', 'ततस्ते सहितास्तत्र अङ्गदं स्थाप्य चाग्रतः।
सुग्रीवतारासहिताः सिषिचुर्वालिने जलम्॥', 'tatas te sahitās tatra aṅgadaṃ sthāpya cāgrataḥ
sugrīvatārāsahitāḥ siṣicur vāline jalam', null, 4024043),
('ramayana-4-24-44', 44, 'Kishkindha Kanda, Sarga 24, Verse 44', 'सुग्रीवेणैव दीनेन दीनो भूत्वा महाबलः।
समानशोकः काकुत्स्थः प्रेतकार्याण्यकारयत्॥', 'sugrīveṇaiva dīnena dīno bhūtvā mahābalaḥ
samānaśokaḥ kākutsthaḥ pretakāryāṇy akārayat', null, 4024044)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 25 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-25-1', 1, 'Kishkindha Kanda, Sarga 25, Verse 1', 'ततः शोकाभिसंतप्तं सुग्रीवं क्लिन्नवासनम्।
शाखामृगमहामात्राः परिवार्योपतस्थिरे॥', 'tataḥ śokābhisaṃtaptaṃ sugrīvaṃ klinnavāsanam
śākhāmṛgamahāmātrāḥ parivāryopatasthire', null, 4025001),
('ramayana-4-25-2', 2, 'Kishkindha Kanda, Sarga 25, Verse 2', 'अभिगम्य महाबाहुं राममक्लिष्टकारिणम्।
स्थिताः प्राञ्जलयः सर्वे पितामहमिवर्षयः॥', 'abhigamya mahābāhuṃ rāmam akliṣṭakāriṇam
sthitāḥ prāñjalayaḥ sarve pitāmaham ivarṣayaḥ', null, 4025002),
('ramayana-4-25-3', 3, 'Kishkindha Kanda, Sarga 25, Verse 3', 'ततः काञ्चनशैलाभस्तरुणार्कनिभाननः।
अब्रवीत्प्राञ्जलिर्वाक्यं हनुमान्मारुतात्मजः॥', 'tataḥ kāñcanaśailābhas taruṇārkanibhānanaḥ
abravīt prāñjalir vākyaṃ hanumān mārutātmajaḥ', null, 4025003),
('ramayana-4-25-4', 4, 'Kishkindha Kanda, Sarga 25, Verse 4', 'भवत्प्रसादात्सुग्रीवः पितृपैतामहं महत्।
वानराणां सुदुष्प्रापं प्राप्तो राज्यमिदं प्रभो॥', 'bhavatprasādāt sugrīvaḥ pitṛpaitāmahaṃ mahat
vānarāṇāṃ suduṣprāpaṃ prāpto rājyam idaṃ prabho', null, 4025004),
('ramayana-4-25-5', 5, 'Kishkindha Kanda, Sarga 25, Verse 5', 'भवता समनुज्ञातः प्रविश्य नगरं शुभम्।
संविधास्यति कार्याणि सर्वाणि ससुहृज्जनः॥', 'bhavatā samanujñātaḥ praviśya nagaraṃ śubham
saṃvidhāsyati kāryāṇi sarvāṇi sasuhṛjjanaḥ', null, 4025005),
('ramayana-4-25-6', 6, 'Kishkindha Kanda, Sarga 25, Verse 6', 'स्नातोऽयं विविधैर्गन्धैरौषधैश्च यथाविधि।
अर्चयिष्यति रत्नैश्च माल्यैश्च त्वां विशेषतः॥', 'snāto ''yaṃ vividhair gandhair auṣadhaiś ca yathāvidhi
arcayiṣyati ratnaiś ca mālyaiś ca tvāṃ viśeṣataḥ', null, 4025006),
('ramayana-4-25-7', 7, 'Kishkindha Kanda, Sarga 25, Verse 7', 'इमां गिरिगुहां रम्यामभिगन्तुमितोऽर्हसि।
कुरुष्व स्वामि संबन्धं वानरान्संप्रहर्षयन्॥', 'imāṃ giriguhāṃ ramyām abhigantum ito ''rhasi
kuruṣva svāmi saṃbandhaṃ vānarān saṃpraharṣayan', null, 4025007),
('ramayana-4-25-8', 8, 'Kishkindha Kanda, Sarga 25, Verse 8', 'एवमुक्तो हनुमता राघवः परवीरहा।
प्रत्युवाच हनूमन्तं बुद्धिमान्वाक्यकोविदः॥', 'evam ukto hanumatā rāghavaḥ paravīrahā
pratyuvāca hanūmantaṃ buddhimān vākyakovidaḥ', null, 4025008),
('ramayana-4-25-9', 9, 'Kishkindha Kanda, Sarga 25, Verse 9', 'चतुर्दशसमाः सौम्य ग्रामं वा यदि वा पुरम्।
न प्रवेक्ष्यामि हनुमन्पितुर्निर्देशपालकः॥', 'caturdaśasamāḥ saumya grāmaṃ vā yadi vā puram
na pravekṣyāmi hanuman pitur nirdeśapālakaḥ', null, 4025009),
('ramayana-4-25-10', 10, 'Kishkindha Kanda, Sarga 25, Verse 10', 'सुसमृद्धां गुहां दिव्यां सुग्रीवो वानरर्षभः।
प्रविष्टो विधिवद्वीरः क्षिप्रं राज्येऽभिषिच्यताम्॥', 'susamṛddhāṃ guhāṃ divyāṃ sugrīvo vānararṣabhaḥ
praviṣṭo vidhivad vīraḥ kṣipraṃ rājye ''bhiṣicyatām', null, 4025010),
('ramayana-4-25-11', 11, 'Kishkindha Kanda, Sarga 25, Verse 11', 'एवमुक्त्वा हनूमन्तं रामः सुग्रीवमब्रवीत्।
इममप्यङ्गदं वीर यौवराज्येऽभिषेचय॥', 'evam uktvā hanūmantaṃ rāmaḥ sugrīvam abravīt
imam apy aṅgadaṃ vīra yauvarājye ''bhiṣecaya', null, 4025011),
('ramayana-4-25-12', 12, 'Kishkindha Kanda, Sarga 25, Verse 12', 'पूर्वोऽयं वार्षिको मासः श्रावणः सलिलागमः।
प्रवृत्ताः सौम्य चत्वारो मासा वार्षिकसंज्ञिताः॥', 'pūrvo ''yaṃ vārṣiko māsaḥ śrāvaṇaḥ salilāgamaḥ
pravṛttāḥ saumya catvāro māsā vārṣikasaṃjñitāḥ', null, 4025012),
('ramayana-4-25-13', 13, 'Kishkindha Kanda, Sarga 25, Verse 13', 'नायमुद्योगसमयः प्रविश त्वं पुरीं शुभाम्।
अस्मिन्वत्स्याम्यहं सौम्य पर्वते सहलक्ष्मणः॥', 'nāyam udyogasamayaḥ praviśa tvaṃ purīṃ śubhām
asmin vatsyāmy ahaṃ saumya parvate sahalakṣmaṇaḥ', null, 4025013),
('ramayana-4-25-14', 14, 'Kishkindha Kanda, Sarga 25, Verse 14', 'इयं गिरिगुहा रम्या विशाला युक्तमारुता।
प्रभूतसलिला सौम्य प्रभूतकमलोत्पला॥', 'iyaṃ giriguhā ramyā viśālā yuktamārutā
prabhūtasalilā saumya prabhūtakamalotpalā', null, 4025014),
('ramayana-4-25-15', 15, 'Kishkindha Kanda, Sarga 25, Verse 15', 'कार्तिके समनुप्राप्ते त्वं रावणवधे यत।
एष नः समयः सौम्य प्रविश त्वं स्वमालयम्।
अभिषिञ्चस्व राज्ये च सुहृदः संप्रहर्षय॥', 'kārtike samanuprāpte tvaṃ rāvaṇavadhe yata
eṣa naḥ samayaḥ saumya praviśa tvaṃ svam ālayam
abhiṣiñcasva rājye ca suhṛdaḥ saṃpraharṣaya', null, 4025015),
('ramayana-4-25-16', 16, 'Kishkindha Kanda, Sarga 25, Verse 16', 'इति रामाभ्यनुज्ञातः सुग्रीवो वानरर्षभः।
प्रविवेश पुरीं रम्यां किष्किन्धां वालिपालिताम्॥', 'iti rāmābhyanujñātaḥ sugrīvo vānararṣabhaḥ
praviveśa purīṃ ramyāṃ kiṣkindhāṃ vālipālitām', null, 4025016),
('ramayana-4-25-17', 17, 'Kishkindha Kanda, Sarga 25, Verse 17', 'तं वानरसहस्राणि प्रविष्टं वानरेश्वरम्।
अभिवाद्य प्रहृष्टानि सर्वतः पर्यवारयन्॥', 'taṃ vānarasahasrāṇi praviṣṭaṃ vānareśvaram
abhivādya prahṛṣṭāni sarvataḥ paryavārayan', null, 4025017),
('ramayana-4-25-18', 18, 'Kishkindha Kanda, Sarga 25, Verse 18', 'ततः प्रकृतयः सर्वा दृष्ट्वा हरिगणेश्वरम्।
प्रणम्य मूर्ध्ना पतिता वसुधायां समाहिताः॥', 'tataḥ prakṛtayaḥ sarvā dṛṣṭvā harigaṇeśvaram
praṇamya mūrdhnā patitā vasudhāyāṃ samāhitāḥ', null, 4025018),
('ramayana-4-25-19', 19, 'Kishkindha Kanda, Sarga 25, Verse 19', 'सुग्रीवः प्रकृतीः सर्वाः संभाष्योत्थाप्य वीर्यवान्।
भ्रातुरन्तःपुरं सौम्यं प्रविवेश महाबलः॥', 'sugrīvaḥ prakṛtīḥ sarvāḥ saṃbhāṣyotthāpya vīryavān
bhrātur antaḥpuraṃ saumyaṃ praviveśa mahābalaḥ', null, 4025019),
('ramayana-4-25-20', 20, 'Kishkindha Kanda, Sarga 25, Verse 20', 'प्रविश्य त्वभिनिष्क्रान्तं सुग्रीवं वानरर्षभम्।
अभ्यषिञ्चन्त सुहृदः सहस्राक्षमिवामराः॥', 'praviśya tv abhiniṣkrāntaṃ sugrīvaṃ vānararṣabham
abhyaṣiñcanta suhṛdaḥ sahasrākṣam ivāmarāḥ', null, 4025020),
('ramayana-4-25-21', 21, 'Kishkindha Kanda, Sarga 25, Verse 21', 'तस्य पाण्डुरमाजह्रुश्छत्रं हेमपरिष्कृतम्।
शुक्ले च बालव्यजने हेमदण्डे यशस्करे॥', 'tasya pāṇḍuram ājahruś chatraṃ hemapariṣkṛtam
śukle ca bālavyajane hemadaṇḍe yaśaskare', null, 4025021),
('ramayana-4-25-22', 22, 'Kishkindha Kanda, Sarga 25, Verse 22', 'तथा सर्वाणि रत्नानि सर्वबीजौषधानि च।
सक्षीराणां च वृक्षाणां प्ररोहान्कुसुमानि च॥', 'tathā sarvāṇi ratnāni sarvabījauṣadhāni ca
sakṣīrāṇāṃ ca vṛkṣāṇāṃ prarohān kusumāni ca', null, 4025022),
('ramayana-4-25-23', 23, 'Kishkindha Kanda, Sarga 25, Verse 23', 'शुक्लानि चैव वस्त्राणि श्वेतं चैवानुलेपनम्।
सुगन्धीनि च माल्यानि स्थलजान्यम्बुजानि च॥', 'śuklāni caiva vastrāṇi śvetaṃ caivānulepanam
sugandhīni ca mālyāni sthalajāny ambujāni ca', null, 4025023),
('ramayana-4-25-24', 24, 'Kishkindha Kanda, Sarga 25, Verse 24', 'चन्दनानि च दिव्यानि गन्धांश्च विविधान्बहून्।
अक्षतं जातरूपं च प्रियङ्गुमधुसर्पिषी॥', 'candanāni ca divyāni gandhāṃś ca vividhān bahūn
akṣataṃ jātarūpaṃ ca priyaṅgumadhusarpiṣī', null, 4025024),
('ramayana-4-25-25', 25, 'Kishkindha Kanda, Sarga 25, Verse 25', 'दधिचर्म च वैयाघ्रं वाराही चाप्युपानहौ।
समालम्भनमादाय रोचनां समनःशिलाम्।
आजग्मुस्तत्र मुदिता वराः कन्यास्तु षोडश॥', 'dadhicarma ca vaiyāghraṃ vārāhī cāpy upānahau
samālambhanam ādāya rocanāṃ samanaḥśilām
ājagmus tatra muditā varāḥ kanyās tu ṣoḍaśa', null, 4025025),
('ramayana-4-25-26', 26, 'Kishkindha Kanda, Sarga 25, Verse 26', 'ततस्ते वानरश्रेष्ठं यथाकालं यथाविधि।
रत्नैर्वस्त्रैश्च भक्ष्यैश्च तोषयित्वा द्विजर्षभान्॥', 'tatas te vānaraśreṣṭhaṃ yathākālaṃ yathāvidhi
ratnair vastraiś ca bhakṣyaiś ca toṣayitvā dvijarṣabhān', null, 4025026),
('ramayana-4-25-27', 27, 'Kishkindha Kanda, Sarga 25, Verse 27', 'ततः कुशपरिस्तीर्णं समिद्धं जातवेदसं।
मन्त्रपूतेन हविषा हुत्वा मन्त्रविदो जनाः॥', 'tataḥ kuśaparistīrṇaṃ samiddhaṃ jātavedasaṃ
mantrapūtena haviṣā hutvā mantravido janāḥ', null, 4025027),
('ramayana-4-25-28', 28, 'Kishkindha Kanda, Sarga 25, Verse 28', 'ततो हेमप्रतिष्ठाने वरास्तरणसंवृते।
प्रासादशिखरे रम्ये चित्रमाल्योपशोभिते॥', 'tato hemapratiṣṭhāne varāstaraṇasaṃvṛte
prāsādaśikhare ramye citramālyopaśobhite', null, 4025028),
('ramayana-4-25-29', 29, 'Kishkindha Kanda, Sarga 25, Verse 29', 'प्राङ्मुखं विविधैर्मन्त्रैः स्थापयित्वा वरासने।
नदीनदेभ्यः संहृत्य तीर्थेभ्यश्च समन्ततः॥', 'prāṅmukhaṃ vividhair mantraiḥ sthāpayitvā varāsane
nadīnadebhyaḥ saṃhṛtya tīrthebhyaś ca samantataḥ', null, 4025029),
('ramayana-4-25-30', 30, 'Kishkindha Kanda, Sarga 25, Verse 30', 'आहृत्य च समुद्रेभ्यः सर्वेभ्यो वानरर्षभाः।
अपः कनककुम्भेषु निधाय विमलाः शुभाः॥', 'āhṛtya ca samudrebhyaḥ sarvebhyo vānararṣabhāḥ
apaḥ kanakakumbheṣu nidhāya vimalāḥ śubhāḥ', null, 4025030),
('ramayana-4-25-31', 31, 'Kishkindha Kanda, Sarga 25, Verse 31', 'शुभैर्वृषभशृङ्गैश्च कलशैश्चापि काञ्चनैः।
शास्त्रदृष्टेन विधिना महर्षिविहितेन च॥', 'śubhair vṛṣabhaśṛṅgaiś ca kalaśaiś cāpi kāñcanaiḥ
śāstradṛṣṭena vidhinā maharṣivihitena ca', null, 4025031),
('ramayana-4-25-32', 32, 'Kishkindha Kanda, Sarga 25, Verse 32', 'गजो गवाक्षो गवयः शरभो गन्धमादनः।
मैन्दश्च द्विविदश्चैव हनूमाञ्जाम्बवान्नलः॥', 'gajo gavākṣo gavayaḥ śarabho gandhamādanaḥ
maindaś ca dvividaś caiva hanūmāñ jāmbavān nalaḥ', null, 4025032),
('ramayana-4-25-33', 33, 'Kishkindha Kanda, Sarga 25, Verse 33', 'अभ्यषिञ्चन्त सुग्रीवं प्रसन्नेन सुगन्धिना।
सलिलेन सहस्राक्षं वसवो वासवं यथा॥', 'abhyaṣiñcanta sugrīvaṃ prasannena sugandhinā
salilena sahasrākṣaṃ vasavo vāsavaṃ yathā', null, 4025033),
('ramayana-4-25-34', 34, 'Kishkindha Kanda, Sarga 25, Verse 34', 'अभिषिक्ते तु सुग्रीवे सर्वे वानरपुंगवाः।
प्रचुक्रुशुर्महात्मानो हृष्टास्तत्र सहस्रशः॥', 'abhiṣikte tu sugrīve sarve vānarapuṃgavāḥ
pracukruśur mahātmāno hṛṣṭās tatra sahasraśaḥ', null, 4025034),
('ramayana-4-25-35', 35, 'Kishkindha Kanda, Sarga 25, Verse 35', 'रामस्य तु वचः कुर्वन्सुग्रीवो हरिपुंगवः।
अङ्गदं संपरिष्वज्य यौवराज्येऽभिषेचयत्॥', 'rāmasya tu vacaḥ kurvan sugrīvo haripuṃgavaḥ
aṅgadaṃ saṃpariṣvajya yauvarājye ''bhiṣecayat', null, 4025035),
('ramayana-4-25-36', 36, 'Kishkindha Kanda, Sarga 25, Verse 36', 'अङ्गदे चाभिषिक्ते तु सानुक्रोशाः प्लवंगमाः।
साधु साध्विति सुग्रीवं महात्मानोऽभ्यपूजयन्॥', 'aṅgade cābhiṣikte tu sānukrośāḥ plavaṃgamāḥ
sādhu sādhv iti sugrīvaṃ mahātmāno ''bhyapūjayan', null, 4025036),
('ramayana-4-25-37', 37, 'Kishkindha Kanda, Sarga 25, Verse 37', 'हृष्टपुष्टजनाकीर्णा पताकाध्वजशोभिता।
बभूव नगरी रम्या क्षिकिन्धा गिरिगह्वरे॥', 'hṛṣṭapuṣṭajanākīrṇā patākādhvajaśobhitā
babhūva nagarī ramyā kṣikindhā girigahvare', null, 4025037),
('ramayana-4-25-38', 38, 'Kishkindha Kanda, Sarga 25, Verse 38', 'निवेद्य रामाय तदा महात्मने महाभिषेकं कपिवाहिनीपतिः।
रुमां च भार्यां प्रतिलभ्य वीर्यवानवाप राज्यं त्रिदशाधिपो यथा॥', 'nivedya rāmāya tadā mahātmane mahābhiṣekaṃ kapivāhinīpatiḥ
rumāṃ ca bhāryāṃ pratilabhya vīryavān avāpa rājyaṃ tridaśādhipo yathā', null, 4025038)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 26 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-26-1', 1, 'Kishkindha Kanda, Sarga 26, Verse 1', 'अभिषिक्ते तु सुग्रीवे प्रविष्टे वानरे गुहाम्।
आजगाम सह भ्रात्रा रामः प्रस्रवणं गिरिम्॥', 'abhiṣikte tu sugrīve praviṣṭe vānare guhām
ājagāma saha bhrātrā rāmaḥ prasravaṇaṃ girim', null, 4026001),
('ramayana-4-26-2', 2, 'Kishkindha Kanda, Sarga 26, Verse 2', 'शार्दूलमृगसंघुष्टं सिंहैर्भीमरवैर्वृतम्।
नानागुल्मलतागूढं बहुपादपसंकुलम्॥', 'śārdūlamṛgasaṃghuṣṭaṃ siṃhair bhīmaravair vṛtam
nānāgulmalatāgūḍhaṃ bahupādapasaṃkulam', null, 4026002),
('ramayana-4-26-3', 3, 'Kishkindha Kanda, Sarga 26, Verse 3', 'ऋक्षवानरगोपुच्छैर्मार्जारैश्च निषेवितम्।
मेघराशिनिभं शैलं नित्यं शुचिजलाश्रयम्॥', 'ṛkṣavānaragopucchair mārjāraiś ca niṣevitam
megharāśinibhaṃ śailaṃ nityaṃ śucijalāśrayam', null, 4026003),
('ramayana-4-26-4', 4, 'Kishkindha Kanda, Sarga 26, Verse 4', 'तस्य शैलस्य शिखरे महतीमायतां गुहाम्।
प्रत्यगृह्णत वासार्थं रामः सौमित्रिणा सह॥', 'tasya śailasya śikhare mahatīm āyatāṃ guhām
pratyagṛhṇata vāsārthaṃ rāmaḥ saumitriṇā saha', null, 4026004),
('ramayana-4-26-5', 5, 'Kishkindha Kanda, Sarga 26, Verse 5', 'अवसत्तत्र धर्मात्मा राघवः सहलक्ष्मणः।
बहुदृश्यदरीकुञ्जे तस्मिन्प्रस्रवणे गिरौ॥', 'avasat tatra dharmātmā rāghavaḥ sahalakṣmaṇaḥ
bahudṛśyadarīkuñje tasmin prasravaṇe girau', null, 4026005),
('ramayana-4-26-6', 6, 'Kishkindha Kanda, Sarga 26, Verse 6', 'सुसुखेऽपि बहुद्रव्ये तस्मिन्हि धरणीधरे।
वसतस्तस्य रामस्य रतिरल्पापि नाभवत्।
हृतां हि भार्यां स्मरतः प्राणेभ्योऽपि गरीयसीम्॥', 'susukhe ''pi bahudravye tasmin hi dharaṇīdhare
vasatas tasya rāmasya ratir alpāpi nābhavat
hṛtāṃ hi bhāryāṃ smarataḥ prāṇebhyo ''pi garīyasīm', null, 4026006),
('ramayana-4-26-7', 7, 'Kishkindha Kanda, Sarga 26, Verse 7', 'उदयाभ्युदितं दृष्ट्वा शशाङ्कं च विशेषतः।
आविवेश न तं निद्रा निशासु शयनं गतम्॥', 'udayābhyuditaṃ dṛṣṭvā śaśāṅkaṃ ca viśeṣataḥ
āviveśa na taṃ nidrā niśāsu śayanaṃ gatam', null, 4026007),
('ramayana-4-26-8', 8, 'Kishkindha Kanda, Sarga 26, Verse 8', 'तत्समुत्थेन शोकेन बाष्पोपहतचेतसं।
तं शोचमानं काकुत्स्थं नित्यं शोकपरायणम्।
तुल्यदुःखोऽब्रवीद्भ्राता लक्ष्मणोऽनुनयन्वचः॥', 'tat samutthena śokena bāṣpopahatacetasaṃ
taṃ śocamānaṃ kākutsthaṃ nityaṃ śokaparāyaṇam
tulyaduḥkho ''bravīd bhrātā lakṣmaṇo ''nunayan vacaḥ', null, 4026008),
('ramayana-4-26-9', 9, 'Kishkindha Kanda, Sarga 26, Verse 9', 'अलं वीर व्यथां गत्वा न त्वं शोचितुमर्हसि।
शोचतो ह्यवसीदन्ति सर्वार्था विदितं हि ते॥', 'alaṃ vīra vyathāṃ gatvā na tvaṃ śocitum arhasi
śocato hy avasīdanti sarvārthā viditaṃ hi te', null, 4026009),
('ramayana-4-26-10', 10, 'Kishkindha Kanda, Sarga 26, Verse 10', 'भवान्क्रियापरो लोके भवान्देवपरायणः।
आस्तिको धर्मशीलश्च व्यवसायी च राघव॥', 'bhavān kriyāparo loke bhavān devaparāyaṇaḥ
āstiko dharmaśīlaś ca vyavasāyī ca rāghava', null, 4026010),
('ramayana-4-26-11', 11, 'Kishkindha Kanda, Sarga 26, Verse 11', 'न ह्यव्यवसितः शत्रुं राक्षसं तं विशेषतः।
समर्थस्त्वं रणे हन्तुं विक्रमैर्जिह्मकारिणम्॥', 'na hy avyavasitaḥ śatruṃ rākṣasaṃ taṃ viśeṣataḥ
samarthas tvaṃ raṇe hantuṃ vikramair jihmakāriṇam', null, 4026011),
('ramayana-4-26-12', 12, 'Kishkindha Kanda, Sarga 26, Verse 12', 'समुन्मूलय शोकं त्वं व्यवसायं स्थिरं कुरु।
ततः सपरिवारं तं निर्मूलं कुरु राक्षसं॥', 'samunmūlaya śokaṃ tvaṃ vyavasāyaṃ sthiraṃ kuru
tataḥ saparivāraṃ taṃ nirmūlaṃ kuru rākṣasaṃ', null, 4026012),
('ramayana-4-26-13', 13, 'Kishkindha Kanda, Sarga 26, Verse 13', 'पृथिवीमपि काकुत्स्थ ससागरवनाचलाम्।
परिवर्तयितुं शक्तः किमङ्ग पुन रावणम्॥', 'pṛthivīm api kākutstha sasāgaravanācalām
parivartayituṃ śaktaḥ kim aṅga puna rāvaṇam', null, 4026013),
('ramayana-4-26-14', 14, 'Kishkindha Kanda, Sarga 26, Verse 14', 'अहं तु खलु ते वीर्यं प्रसुप्तं प्रतिबोधये।
दीप्तैराहुतिभिः काले भस्मच्छन्नमिवानलम्॥', 'ahaṃ tu khalu te vīryaṃ prasuptaṃ pratibodhaye
dīptair āhutibhiḥ kāle bhasmac channam ivānalam', null, 4026014),
('ramayana-4-26-15', 15, 'Kishkindha Kanda, Sarga 26, Verse 15', 'लक्ष्मणस्य तु तद्वाक्यं प्रतिपूज्य हितं शुभम्।
राघवः सुहृदं स्निग्धमिदं वचनमब्रवीत्॥', 'lakṣmaṇasya tu tad vākyaṃ pratipūjya hitaṃ śubham
rāghavaḥ suhṛdaṃ snigdham idaṃ vacanam abravīt', null, 4026015),
('ramayana-4-26-16', 16, 'Kishkindha Kanda, Sarga 26, Verse 16', 'वाच्यं यदनुरक्तेन स्निग्धेन च हितेन च।
सत्यविक्रम युक्तेन तदुक्तं लक्ष्मण त्वया॥', 'vācyaṃ yad anuraktena snigdhena ca hitena ca
satyavikrama yuktena tad uktaṃ lakṣmaṇa tvayā', null, 4026016),
('ramayana-4-26-17', 17, 'Kishkindha Kanda, Sarga 26, Verse 17', 'एष शोकः परित्यक्तः सर्वकार्यावसादकः।
विक्रमेष्वप्रतिहतं तेजः प्रोत्साहयाम्यहम्॥', 'eṣa śokaḥ parityaktaḥ sarvakāryāvasādakaḥ
vikrameṣv apratihataṃ tejaḥ protsāhayāmy aham', null, 4026017),
('ramayana-4-26-18', 18, 'Kishkindha Kanda, Sarga 26, Verse 18', 'शरत्कालं प्रतीक्षेऽहमियं प्रावृडुपस्थिता।
ततः सराष्ट्रं सगणं राक्षसं तं निहन्म्यहम्॥', 'śaratkālaṃ pratīkṣe ''ham iyaṃ prāvṛḍ upasthitā
tataḥ sarāṣṭraṃ sagaṇaṃ rākṣasaṃ taṃ nihanmy aham', null, 4026018),
('ramayana-4-26-19', 19, 'Kishkindha Kanda, Sarga 26, Verse 19', 'तस्य तद्वचनं श्रुत्वा हृष्टो रामस्य लक्ष्मणः।
पुनरेवाब्रवीद्वाक्यं सौमित्रिर्मित्रनन्दनः॥', 'tasya tad vacanaṃ śrutvā hṛṣṭo rāmasya lakṣmaṇaḥ
punar evābravīd vākyaṃ saumitrir mitranandanaḥ', null, 4026019),
('ramayana-4-26-20', 20, 'Kishkindha Kanda, Sarga 26, Verse 20', 'एतत्ते सदृशं वाक्यमुक्तं शत्रुनिबर्हण।
इदानीमसि काकुत्स्थ प्रकृतिं स्वामुपागतः॥', 'etat te sadṛśaṃ vākyam uktaṃ śatrunibarhaṇa
idānīm asi kākutstha prakṛtiṃ svām upāgataḥ', null, 4026020),
('ramayana-4-26-21', 21, 'Kishkindha Kanda, Sarga 26, Verse 21', 'विज्ञाय ह्यात्मनो वीर्यं तथ्यं भवितुमर्हसि।
एतत्सदृशमुक्तं ते श्रुतस्याभिजनस्य च॥', 'vijñāya hy ātmano vīryaṃ tathyaṃ bhavitum arhasi
etat sadṛśam uktaṃ te śrutasyābhijanasya ca', null, 4026021),
('ramayana-4-26-22', 22, 'Kishkindha Kanda, Sarga 26, Verse 22', 'तस्मात्पुरुषशार्दूल चिन्तयञ्शत्रुनिग्रहम्।
वर्षारात्रमनुप्राप्तमतिक्रामय राघव॥', 'tasmāt puruṣaśārdūla cintayañ śatrunigraham
varṣārātram anuprāptam atikrāmaya rāghava', null, 4026022),
('ramayana-4-26-23', 23, 'Kishkindha Kanda, Sarga 26, Verse 23', 'नियम्य कोपं प्रतिपाल्यतां शरत्क्षमस्व मासांश्चतुरो मया सह।
वसाचलेऽस्मिन्मृगराजसेविते संवर्धयञ्शत्रुवधे समुद्यतः॥', 'niyamya kopaṃ pratipālyatāṃ śarat kṣamasva māsāṃś caturo mayā saha
vasācale ''smin mṛgarājasevite saṃvardhayañ śatruvadhe samudyataḥ', null, 4026023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 27 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-27-1', 1, 'Kishkindha Kanda, Sarga 27, Verse 1', 'स तदा वालिनं हत्वा सुग्रीवमभिषिच्य च।
वसन्माल्यवतः पृष्टे रामो लक्ष्मणमब्रवीत्॥', 'sa tadā vālinaṃ hatvā sugrīvam abhiṣicya ca
vasan mālyavataḥ pṛṣṭe rāmo lakṣmaṇam abravīt', null, 4027001),
('ramayana-4-27-2', 2, 'Kishkindha Kanda, Sarga 27, Verse 2', 'अयं स कालः संप्राप्तः समयोऽद्य जलागमः।
संपश्य त्वं नभो मेघैः संवृतं गिरिसंनिभैः॥', 'ayaṃ sa kālaḥ saṃprāptaḥ samayo ''dya jalāgamaḥ
saṃpaśya tvaṃ nabho meghaiḥ saṃvṛtaṃ girisaṃnibhaiḥ', null, 4027002),
('ramayana-4-27-3', 3, 'Kishkindha Kanda, Sarga 27, Verse 3', 'नव मास धृतं गर्भं भास्कारस्य गभस्तिभिः।
पीत्वा रसं समुद्राणां द्यौः प्रसूते रसायनम्॥', 'nava māsa dhṛtaṃ garbhaṃ bhāskārasya gabhastibhiḥ
pītvā rasaṃ samudrāṇāṃ dyauḥ prasūte rasāyanam', null, 4027003),
('ramayana-4-27-4', 4, 'Kishkindha Kanda, Sarga 27, Verse 4', 'शक्यमम्बरमारुह्य मेघसोपानपङ्क्तिभिः।
कुटजार्जुनमालाभिरलंकर्तुं दिवाकरम्॥', 'śakyam ambaram āruhya meghasopānapaṅktibhiḥ
kuṭajārjunamālābhir alaṃkartuṃ divākaram', null, 4027004),
('ramayana-4-27-5', 5, 'Kishkindha Kanda, Sarga 27, Verse 5', 'संध्यारागोत्थितैस्ताम्रैरन्तेष्वधिकपाण्डुरैः।
स्निग्धैरभ्रपटच्छदैर्बद्धव्रणमिवाम्बरम्॥', 'saṃdhyārāgotthitais tāmrair anteṣv adhikapāṇḍuraiḥ
snigdhair abhrapaṭacchadair baddhavraṇam ivāmbaram', null, 4027005),
('ramayana-4-27-6', 6, 'Kishkindha Kanda, Sarga 27, Verse 6', 'मन्दमारुतनिःश्वासं संध्याचन्दनरञ्जितम्।
आपाण्डुजलदं भाति कामातुरमिवाम्बरम्॥', 'mandamārutaniḥśvāsaṃ saṃdhyācandanarañjitam
āpāṇḍujaladaṃ bhāti kāmāturam ivāmbaram', null, 4027006),
('ramayana-4-27-7', 7, 'Kishkindha Kanda, Sarga 27, Verse 7', 'एषा धर्मपरिक्लिष्टा नववारिपरिप्लुता।
सीतेव शोकसंतप्ता मही बाष्पं विमुञ्चति॥', 'eṣā dharmaparikliṣṭā navavāripariplutā
sīteva śokasaṃtaptā mahī bāṣpaṃ vimuñcati', null, 4027007),
('ramayana-4-27-8', 8, 'Kishkindha Kanda, Sarga 27, Verse 8', 'मेघोदरविनिर्मुक्ताः कह्लारसुखशीतलाः।
शक्यमञ्जलिभिः पातुं वाताः केतकिगन्धिनः॥', 'meghodaravinirmuktāḥ kahlārasukhaśītalāḥ
śakyam añjalibhiḥ pātuṃ vātāḥ ketakigandhinaḥ', null, 4027008),
('ramayana-4-27-9', 9, 'Kishkindha Kanda, Sarga 27, Verse 9', 'एष फुल्लार्जुनः शैलः केतकैरधिवासितः।
सुग्रीव इव शान्तारिर्धाराभिरभिषिच्यते॥', 'eṣa phullārjunaḥ śailaḥ ketakair adhivāsitaḥ
sugrīva iva śāntārir dhārābhir abhiṣicyate', null, 4027009),
('ramayana-4-27-10', 10, 'Kishkindha Kanda, Sarga 27, Verse 10', 'मेघकृष्णाजिनधरा धारायज्ञोपवीतिनः।
मारुतापूरितगुहाः प्राधीता इव पर्वताः॥', 'meghakṛṣṇājinadharā dhārāyajñopavītinaḥ
mārutāpūritaguhāḥ prādhītā iva parvatāḥ', null, 4027010),
('ramayana-4-27-11', 11, 'Kishkindha Kanda, Sarga 27, Verse 11', 'कशाभिरिव हैमीभिर्विद्युद्भिरिव ताडितम्।
अन्तःस्तनितनिर्घोषं सवेदनमिवाम्बरम्॥', 'kaśābhir iva haimībhir vidyudbhir iva tāḍitam
antaḥstanitanirghoṣaṃ savedanam ivāmbaram', null, 4027011),
('ramayana-4-27-12', 12, 'Kishkindha Kanda, Sarga 27, Verse 12', 'नीलमेघाश्रिता विद्युत्स्फुरन्ती प्रतिभाति मे।
स्फुरन्ती रावणस्याङ्के वैदेहीव तपस्विनी॥', 'nīlameghāśritā vidyut sphurantī pratibhāti me
sphurantī rāvaṇasyāṅke vaidehīva tapasvinī', null, 4027012),
('ramayana-4-27-13', 13, 'Kishkindha Kanda, Sarga 27, Verse 13', 'इमास्ता मन्मथवतां हिताः प्रतिहता दिशः।
अनुलिप्ता इव घनैर्नष्टग्रहनिशाकराः॥', 'imās tā manmathavatāṃ hitāḥ pratihatā diśaḥ
anuliptā iva ghanair naṣṭagrahaniśākarāḥ', null, 4027013),
('ramayana-4-27-14', 14, 'Kishkindha Kanda, Sarga 27, Verse 14', 'क्व चिद्बाष्पाभिसंरुद्धान्वर्षागमसमुत्सुकान्।
कुटजान्पश्य सौमित्रे पुष्टितान्गिरिसानुषु।
मम शोकाभिभूतस्य कामसंदीपनान्स्थितान्॥', 'kva cid bāṣpābhisaṃruddhān varṣāgamasamutsukān
kuṭajān paśya saumitre puṣṭitān girisānuṣu
mama śokābhibhūtasya kāmasaṃdīpanān sthitān', null, 4027014),
('ramayana-4-27-15', 15, 'Kishkindha Kanda, Sarga 27, Verse 15', 'रजः प्रशान्तं सहिमोऽद्य वायुर्निदाघदोषप्रसराः प्रशान्ताः।
स्थिता हि यात्रा वसुधाधिपानां प्रवासिनो यान्ति नराः स्वदेशान्॥', 'rajaḥ praśāntaṃ sahimo ''dya vāyur nidāghadoṣaprasarāḥ praśāntāḥ
sthitā hi yātrā vasudhādhipānāṃ pravāsino yānti narāḥ svadeśān', null, 4027015),
('ramayana-4-27-16', 16, 'Kishkindha Kanda, Sarga 27, Verse 16', 'संप्रस्थिता मानसवासलुब्धाः प्रियान्विताः संप्रति चक्रवाकः।
अभीक्ष्णवर्षोदकविक्षतेषु यानानि मार्गेषु न संपतन्ति॥', 'saṃprasthitā mānasavāsalubdhāḥ priyānvitāḥ saṃprati cakravākaḥ
abhīkṣṇavarṣodakavikṣateṣu yānāni mārgeṣu na saṃpatanti', null, 4027016),
('ramayana-4-27-17', 17, 'Kishkindha Kanda, Sarga 27, Verse 17', 'क्व चित्प्रकाशं क्व चिदप्रकाशं नभः प्रकीर्णाम्बुधरं विभाति।
क्व चित्क्व चित्पर्वतसंनिरुद्धं रूपं यथा शान्तमहार्णवस्य॥', 'kva cit prakāśaṃ kva cid aprakāśaṃ nabhaḥ prakīrṇāmbudharaṃ vibhāti
kva cit kva cit parvatasaṃniruddhaṃ rūpaṃ yathā śāntamahārṇavasya', null, 4027017),
('ramayana-4-27-18', 18, 'Kishkindha Kanda, Sarga 27, Verse 18', 'व्यामिश्रितं सर्जकदम्बपुष्पैर्नवं जलं पर्वतधातुताम्रम्।
मयूरकेकाभिरनुप्रयातं शैलापगाः शीघ्रतरं वहन्ति॥', 'vyāmiśritaṃ sarjakadambapuṣpair navaṃ jalaṃ parvatadhātutāmram
mayūrakekābhir anuprayātaṃ śailāpagāḥ śīghrataraṃ vahanti', null, 4027018),
('ramayana-4-27-19', 19, 'Kishkindha Kanda, Sarga 27, Verse 19', 'रसाकुलं षट्पदसंनिकाशं प्रभुज्यते जम्बुफलं प्रकामम्।
अनेकवर्णं पवनावधूतं भूमौ पतत्याम्रफलं विपक्वम्॥', 'rasākulaṃ ṣaṭpadasaṃnikāśaṃ prabhujyate jambuphalaṃ prakāmam
anekavarṇaṃ pavanāvadhūtaṃ bhūmau pataty āmraphalaṃ vipakvam', null, 4027019),
('ramayana-4-27-20', 20, 'Kishkindha Kanda, Sarga 27, Verse 20', 'विद्युत्पताकाः सबलाक मालाः शैलेन्द्रकूटाकृतिसंनिकाशाः।
गर्जन्ति मेघाः समुदीर्णनादा मत्तगजेन्द्रा इव संयुगस्थः॥', 'vidyutpatākāḥ sabalāka mālāḥ śailendrakūṭākṛtisaṃnikāśāḥ
garjanti meghāḥ samudīrṇanādā mattagajendrā iva saṃyugasthaḥ', null, 4027020),
('ramayana-4-27-21', 21, 'Kishkindha Kanda, Sarga 27, Verse 21', 'मेघाभिकामी परिसंपतन्ती संमोदिता भाति बलाकपङ्क्तिः।
वातावधूता वरपौण्डरीकी लम्बेव माला रचिताम्बरस्य॥', 'meghābhikāmī parisaṃpatantī saṃmoditā bhāti balākapaṅktiḥ
vātāvadhūtā varapauṇḍarīkī lambeva mālā racitāmbarasya', null, 4027021),
('ramayana-4-27-22', 22, 'Kishkindha Kanda, Sarga 27, Verse 22', 'निद्रा शनैः केशवमभ्युपैति द्रुतं नदी सागरमभ्युपैति।
हृष्टा बलाका घनमभ्युपैति कान्ता सकामा प्रियमभ्युपैति॥', 'nidrā śanaiḥ keśavam abhyupaiti drutaṃ nadī sāgaram abhyupaiti
hṛṣṭā balākā ghanam abhyupaiti kāntā sakāmā priyam abhyupaiti', null, 4027022),
('ramayana-4-27-23', 23, 'Kishkindha Kanda, Sarga 27, Verse 23', 'जाता वनान्ताः शिखिसुप्रनृत्ता जाताः कदम्बाः सकदम्बशाखाः।
जाता वृषा गोषु समानकामा जाता मही सस्यवनाभिरामा॥', 'jātā vanāntāḥ śikhisupranṛttā jātāḥ kadambāḥ sakadambaśākhāḥ
jātā vṛṣā goṣu samānakāmā jātā mahī sasyavanābhirāmā', null, 4027023),
('ramayana-4-27-24', 24, 'Kishkindha Kanda, Sarga 27, Verse 24', 'वहन्ति वर्षन्ति नदन्ति भान्ति ध्यायन्ति नृत्यन्ति समाश्वसन्ति।
नद्यो घना मत्तगजा वनान्ताः प्रियाविनीहाः शिखिनः प्लवंगाः॥', 'vahanti varṣanti nadanti bhānti dhyāyanti nṛtyanti samāśvasanti
nadyo ghanā mattagajā vanāntāḥ priyāvinīhāḥ śikhinaḥ plavaṃgāḥ', null, 4027024),
('ramayana-4-27-25', 25, 'Kishkindha Kanda, Sarga 27, Verse 25', 'प्रहर्षिताः केतकपुष्पगन्धमाघ्राय हृष्टा वननिर्झरेषु।
प्रपात शब्दाकुलिता गजेन्द्राः सार्धं मयूरैः समदा नदन्ति॥', 'praharṣitāḥ ketakapuṣpagandham āghrāya hṛṣṭā vananirjhareṣu
prapāta śabdākulitā gajendrāḥ sārdhaṃ mayūraiḥ samadā nadanti', null, 4027025),
('ramayana-4-27-26', 26, 'Kishkindha Kanda, Sarga 27, Verse 26', 'धारानिपातैरभिहन्यमानाः कदम्बशाखासु विलम्बमानाः।
क्षणार्जितं पुष्परसावगाढं शनैर्मदं षट्चरणास्त्यजन्ति॥', 'dhārānipātair abhihanyamānāḥ kadambaśākhāsu vilambamānāḥ
kṣaṇārjitaṃ puṣparasāvagāḍhaṃ śanair madaṃ ṣaṭcaraṇās tyajanti', null, 4027026),
('ramayana-4-27-27', 27, 'Kishkindha Kanda, Sarga 27, Verse 27', 'अङ्गारचूर्णोत्करसंनिकाशैः फलैः सुपर्याप्त रसैः समृद्धैः।
जम्बूद्रुमाणां प्रविभान्ति शाखा निलीयमाना इव षट्पदौघैः॥', 'aṅgāracūrṇotkarasaṃnikāśaiḥ phalaiḥ suparyāpta rasaiḥ samṛddhaiḥ
jambūdrumāṇāṃ pravibhānti śākhā nilīyamānā iva ṣaṭpadaughaiḥ', null, 4027027),
('ramayana-4-27-28', 28, 'Kishkindha Kanda, Sarga 27, Verse 28', 'तडित्पताकाभिरलंकृतानामुदीर्णगम्भीरमहारवाणाम्।
विभान्ति रूपाणि बलाहकानां रणोद्यतानामिव वारणानाम्॥', 'taḍitpatākābhir alaṃkṛtānām udīrṇagambhīramahāravāṇām
vibhānti rūpāṇi balāhakānāṃ raṇodyatānām iva vāraṇānām', null, 4027028),
('ramayana-4-27-29', 29, 'Kishkindha Kanda, Sarga 27, Verse 29', 'मार्गानुगः शैलवनानुसारी संप्रस्थितो मेघरवं निशम्य।
युद्धाभिकामः प्रतिनागशङ्की मत्तो गजेन्द्रः प्रतिसंनिवृत्तः॥', 'mārgānugaḥ śailavanānusārī saṃprasthito megharavaṃ niśamya
yuddhābhikāmaḥ pratināgaśaṅkī matto gajendraḥ pratisaṃnivṛttaḥ', null, 4027029),
('ramayana-4-27-30', 30, 'Kishkindha Kanda, Sarga 27, Verse 30', 'मुक्तासकाशं सलिलं पतद्वै सुनिर्मलं पत्रपुटेषु लग्नम्।
हृष्टा विवर्णच्छदना विहंगाः सुरेन्द्रदत्तं तृषिताः पिबन्ति॥', 'muktāsakāśaṃ salilaṃ patad vai sunirmalaṃ patrapuṭeṣu lagnam
hṛṣṭā vivarṇacchadanā vihaṃgāḥ surendradattaṃ tṛṣitāḥ pibanti', null, 4027030),
('ramayana-4-27-31', 31, 'Kishkindha Kanda, Sarga 27, Verse 31', 'नीलेषु नीला नववारिपूर्णा मेघेषु मेघाः प्रविभान्ति सक्ताः।
दवाग्निदग्धेषु दवाग्निदग्धाः शैलेषु शैला इव बद्धमूलाः॥', 'nīleṣu nīlā navavāripūrṇā megheṣu meghāḥ pravibhānti saktāḥ
davāgnidagdheṣu davāgnidagdhāḥ śaileṣu śailā iva baddhamūlāḥ', null, 4027031),
('ramayana-4-27-32', 32, 'Kishkindha Kanda, Sarga 27, Verse 32', 'मत्ता गजेन्द्रा मुदिता गवेन्द्रा वनेषु विश्रान्ततरा मृगेन्द्राः।
रम्या नगेन्द्रा निभृता नगेन्द्राः प्रक्रीडितो वारिधरैः सुरेन्द्रः॥', 'mattā gajendrā muditā gavendrā vaneṣu viśrāntatarā mṛgendrāḥ
ramyā nagendrā nibhṛtā nagendrāḥ prakrīḍito vāridharaiḥ surendraḥ', null, 4027032),
('ramayana-4-27-33', 33, 'Kishkindha Kanda, Sarga 27, Verse 33', 'वृत्ता यात्रा नरेन्द्राणां सेना प्रतिनिवर्तते।
वैराणि चैव मार्गाश्च सलिलेन समीकृताः॥', 'vṛttā yātrā narendrāṇāṃ senā pratinivartate
vairāṇi caiva mārgāś ca salilena samīkṛtāḥ', null, 4027033),
('ramayana-4-27-34', 34, 'Kishkindha Kanda, Sarga 27, Verse 34', 'मासि प्रौष्ठपदे ब्रह्म ब्राह्मणानां विवक्षताम्।
अयमध्यायसमयः सामगानामुपस्थितः॥', 'māsi prauṣṭhapade brahma brāhmaṇānāṃ vivakṣatām
ayam adhyāyasamayaḥ sāmagānām upasthitaḥ', null, 4027034),
('ramayana-4-27-35', 35, 'Kishkindha Kanda, Sarga 27, Verse 35', 'निवृत्तकर्मायतनो नूनं संचितसंचयः।
आषाढीमभ्युपगतो भरतः कोषकाधिपः॥', 'nivṛttakarmāyatano nūnaṃ saṃcitasaṃcayaḥ
āṣāḍhīm abhyupagato bharataḥ koṣakādhipaḥ', null, 4027035),
('ramayana-4-27-36', 36, 'Kishkindha Kanda, Sarga 27, Verse 36', 'नूनमापूर्यमाणायाः सरय्वा वधते रयः।
मां समीक्ष्य समायान्तमयोध्याया इव स्वनः॥', 'nūnam āpūryamāṇāyāḥ sarayvā vadhate rayaḥ
māṃ samīkṣya samāyāntam ayodhyāyā iva svanaḥ', null, 4027036),
('ramayana-4-27-37', 37, 'Kishkindha Kanda, Sarga 27, Verse 37', 'इमाः स्फीतगुणा वर्षाः सुग्रीवः सुखमश्नुते।
विजितारिः सदारश्च राज्ये महति च स्थितः॥', 'imāḥ sphītaguṇā varṣāḥ sugrīvaḥ sukham aśnute
vijitāriḥ sadāraś ca rājye mahati ca sthitaḥ', null, 4027037),
('ramayana-4-27-38', 38, 'Kishkindha Kanda, Sarga 27, Verse 38', 'अहं तु हृतदारश्च राज्याच्च महतश्च्युतः।
नदीकूलमिव क्लिन्नमवसीदामि लक्ष्मण॥', 'ahaṃ tu hṛtadāraś ca rājyāc ca mahataś cyutaḥ
nadīkūlam iva klinnam avasīdāmi lakṣmaṇa', null, 4027038),
('ramayana-4-27-39', 39, 'Kishkindha Kanda, Sarga 27, Verse 39', 'शोकश्च मम विस्तीर्णो वर्षाश्च भृशदुर्गमाः।
रावणश्च महाञ्शत्रुरपारं प्रतिभाति मे॥', 'śokaś ca mama vistīrṇo varṣāś ca bhṛśadurgamāḥ
rāvaṇaś ca mahāñ śatrur apāraṃ pratibhāti me', null, 4027039),
('ramayana-4-27-40', 40, 'Kishkindha Kanda, Sarga 27, Verse 40', 'अयात्रां चैव दृष्ट्वेमां मार्गांश्च भृशदुर्गमान्।
प्रणते चैव सुग्रीवे न मया किं चिदीरितम्॥', 'ayātrāṃ caiva dṛṣṭvemāṃ mārgāṃś ca bhṛśadurgamān
praṇate caiva sugrīve na mayā kiṃ cid īritam', null, 4027040),
('ramayana-4-27-41', 41, 'Kishkindha Kanda, Sarga 27, Verse 41', 'अपि चातिपरिक्लिष्टं चिराद्दारैः समागतम्।
आत्मकार्यगरीयस्त्वाद्वक्तुं नेच्छामि वानरम्॥', 'api cātiparikliṣṭaṃ cirād dāraiḥ samāgatam
ātmakāryagarīyastvād vaktuṃ necchāmi vānaram', null, 4027041),
('ramayana-4-27-42', 42, 'Kishkindha Kanda, Sarga 27, Verse 42', 'स्वयमेव हि विश्रम्य ज्ञात्वा कालमुपागतम्।
उपकारं च सुग्रीवो वेत्स्यते नात्र संशयः॥', 'svayam eva hi viśramya jñātvā kālam upāgatam
upakāraṃ ca sugrīvo vetsyate nātra saṃśayaḥ', null, 4027042),
('ramayana-4-27-43', 43, 'Kishkindha Kanda, Sarga 27, Verse 43', 'तस्मात्कालप्रतीक्षोऽहं स्थितोऽस्मि शुभलक्षण।
सुग्रीवस्य नदीनां च प्रसादमनुपालयन्॥', 'tasmāt kālapratīkṣo ''haṃ sthito ''smi śubhalakṣaṇa
sugrīvasya nadīnāṃ ca prasādam anupālayan', null, 4027043),
('ramayana-4-27-44', 44, 'Kishkindha Kanda, Sarga 27, Verse 44', 'उपकारेण वीरो हि प्रतिकारेण युज्यते।
अकृतज्ञोऽप्रतिकृतो हन्ति सत्त्ववतां मनः॥', 'upakāreṇa vīro hi pratikāreṇa yujyate
akṛtajño ''pratikṛto hanti sattvavatāṃ manaḥ', null, 4027044),
('ramayana-4-27-45', 45, 'Kishkindha Kanda, Sarga 27, Verse 45', 'अथैवमुक्तः प्रणिधाय लक्ष्मणः कृताञ्जलिस्तत्प्रतिपूज्य भाषितम्।
उवाच रामं स्वभिराम दर्शनं प्रदर्शयन्दर्शनमात्मनः शुभम्॥', 'athaivam uktaḥ praṇidhāya lakṣmaṇaḥ kṛtāñjalis tat pratipūjya bhāṣitam
uvāca rāmaṃ svabhirāma darśanaṃ pradarśayan darśanam ātmanaḥ śubham', null, 4027045),
('ramayana-4-27-46', 46, 'Kishkindha Kanda, Sarga 27, Verse 46', 'यथोक्तमेतत्तव सर्वमीप्सितं नरेन्द्र कर्ता नचिराद्धरीश्वरः।
शरत्प्रतीक्षः क्षमतामिमं भवाञ्जलप्रपातं रिपुनिग्रहे धृतः॥', 'yathoktam etat tava sarvam īpsitaṃ narendra kartā nacirād dharīśvaraḥ
śaratpratīkṣaḥ kṣamatām imaṃ bhavāñ jalaprapātaṃ ripunigrahe dhṛtaḥ', null, 4027046)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 28 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-28-1', 1, 'Kishkindha Kanda, Sarga 28, Verse 1', 'समीक्ष्य विमलं व्योम गतविद्युद्बलाहकम्।
सारसारवसंघुष्टं रम्यज्योत्स्नानुलेपनम्॥', 'samīkṣya vimalaṃ vyoma gatavidyudbalāhakam
sārasāravasaṃghuṣṭaṃ ramyajyotsnānulepanam', null, 4028001),
('ramayana-4-28-2', 2, 'Kishkindha Kanda, Sarga 28, Verse 2', 'समृद्धार्थं च सुग्रीवं मन्दधर्मार्थसंग्रहम्।
अत्यर्थमसतां मार्गमेकान्तगतमानसं॥', 'samṛddhārthaṃ ca sugrīvaṃ mandadharmārthasaṃgraham
atyartham asatāṃ mārgam ekāntagatamānasaṃ', null, 4028002),
('ramayana-4-28-3', 3, 'Kishkindha Kanda, Sarga 28, Verse 3', 'निवृत्तकार्यं सिद्धार्थं प्रमदाभिरतं सदा।
प्राप्तवन्तमभिप्रेतान्सर्वानेव मनोरथान्॥', 'nivṛttakāryaṃ siddhārthaṃ pramadābhirataṃ sadā
prāptavantam abhipretān sarvān eva manorathān', null, 4028003),
('ramayana-4-28-4', 4, 'Kishkindha Kanda, Sarga 28, Verse 4', 'स्वां च पात्नीमभिप्रेतां तारां चापि समीप्सिताम्।
विहरन्तमहोरात्रं कृतार्थं विगतज्वलम्॥', 'svāṃ ca pātnīm abhipretāṃ tārāṃ cāpi samīpsitām
viharantam ahorātraṃ kṛtārthaṃ vigatajvalam', null, 4028004),
('ramayana-4-28-5', 5, 'Kishkindha Kanda, Sarga 28, Verse 5', 'क्रीडन्तमिव देवेशं नन्दनेऽप्सरसां गणैः।
मन्त्रिषु न्यस्तकार्यं च मन्त्रिणामनवेक्षकम्॥', 'krīḍantam iva deveśaṃ nandane ''psarasāṃ gaṇaiḥ
mantriṣu nyastakāryaṃ ca mantriṇām anavekṣakam', null, 4028005),
('ramayana-4-28-6', 6, 'Kishkindha Kanda, Sarga 28, Verse 6', 'उत्सन्नराज्यसंदेशं कामवृत्तमवस्थितम्।
निश्चितार्थोऽर्थतत्त्वज्ञः कालधर्मविशेषवित्॥', 'utsannarājyasaṃdeśaṃ kāmavṛttam avasthitam
niścitārtho ''rthatattvajñaḥ kāladharmaviśeṣavit', null, 4028006),
('ramayana-4-28-7', 7, 'Kishkindha Kanda, Sarga 28, Verse 7', 'प्रसाद्य वाक्यैर्मधुरैर्हेतुमद्भिर्मनोरमैः।
वाक्यविद्वाक्यतत्त्वज्ञं हरीशं मारुतात्मजः॥', 'prasādya vākyair madhurair hetumadbhir manoramaiḥ
vākyavid vākyatattvajñaṃ harīśaṃ mārutātmajaḥ', null, 4028007),
('ramayana-4-28-8', 8, 'Kishkindha Kanda, Sarga 28, Verse 8', 'हितं तथ्यं च पथ्यं च सामधर्मार्थनीतिमत्।
प्रणयप्रीतिसंयुक्तं विश्वासकृतनिश्चयम्।
हरीश्वरमुपागम्य हनुमान्वाक्यमब्रवीत्॥', 'hitaṃ tathyaṃ ca pathyaṃ ca sāmadharmārthanītimat
praṇayaprītisaṃyuktaṃ viśvāsakṛtaniścayam
harīśvaram upāgamya hanumān vākyam abravīt', null, 4028008),
('ramayana-4-28-9', 9, 'Kishkindha Kanda, Sarga 28, Verse 9', 'राज्यं प्राप्तं यशश्चैव कौली श्रीरभिवर्थिता।
मित्राणां संग्रहः शेषस्तद्भवान्कर्तुमर्हति॥', 'rājyaṃ prāptaṃ yaśaś caiva kaulī śrīr abhivarthitā
mitrāṇāṃ saṃgrahaḥ śeṣas tad bhavān kartum arhati', null, 4028009),
('ramayana-4-28-10', 10, 'Kishkindha Kanda, Sarga 28, Verse 10', 'यो हि मित्रेषु कालज्ञः सततं साधु वर्तते।
तस्य राज्यं च कीर्तिश्च प्रतापश्चाभिवर्धते॥', 'yo hi mitreṣu kālajñaḥ satataṃ sādhu vartate
tasya rājyaṃ ca kīrtiś ca pratāpaś cābhivardhate', null, 4028010),
('ramayana-4-28-11', 11, 'Kishkindha Kanda, Sarga 28, Verse 11', 'यस्य कोशश्च दण्डश्च मित्राण्यात्मा च भूमिप।
समवेतानि सर्वाणि स राज्यं महदश्नुते॥', 'yasya kośaś ca daṇḍaś ca mitrāṇy ātmā ca bhūmipa
samavetāni sarvāṇi sa rājyaṃ mahad aśnute', null, 4028011),
('ramayana-4-28-12', 12, 'Kishkindha Kanda, Sarga 28, Verse 12', 'तद्भवान्वृत्तसंपन्नः स्थितः पथि निरत्यये।
मित्रार्थमभिनीतार्थं यथावत्कर्तुमर्हति॥', 'tad bhavān vṛttasaṃpannaḥ sthitaḥ pathi niratyaye
mitrārtham abhinītārthaṃ yathāvat kartum arhati', null, 4028012),
('ramayana-4-28-13', 13, 'Kishkindha Kanda, Sarga 28, Verse 13', 'यस्तु कालव्यतीतेषु मित्रकार्येषु वर्तते।
स कृत्वा महतोऽप्यर्थान्न मित्रार्थेन युज्यते॥', 'yas tu kālavyatīteṣu mitrakāryeṣu vartate
sa kṛtvā mahato ''py arthān na mitrārthena yujyate', null, 4028013),
('ramayana-4-28-14', 14, 'Kishkindha Kanda, Sarga 28, Verse 14', 'क्रियतां राघवस्यैतद्वैदेह्याः परिमार्गणम्।
तदिदं वीर कार्यं ते कालातीतमरिंदम॥', 'kriyatāṃ rāghavasyaitad vaidehyāḥ parimārgaṇam
tad idaṃ vīra kāryaṃ te kālātītam ariṃdama', null, 4028014),
('ramayana-4-28-15', 15, 'Kishkindha Kanda, Sarga 28, Verse 15', 'न च कालमतीतं ते निवेदयति कालवित्।
त्वरमाणोऽपि सन्प्राज्ञस्तव राजन्वशानुगः॥', 'na ca kālam atītaṃ te nivedayati kālavit
tvaramāṇo ''pi san prājñas tava rājan vaśānugaḥ', null, 4028015),
('ramayana-4-28-16', 16, 'Kishkindha Kanda, Sarga 28, Verse 16', 'कुलस्य केतुः स्फीतस्य दीर्घबन्धुश्च राघवः।
अप्रमेयप्रभावश्च स्वयं चाप्रतिमो गुणैः॥', 'kulasya ketuḥ sphītasya dīrghabandhuś ca rāghavaḥ
aprameyaprabhāvaś ca svayaṃ cāpratimo guṇaiḥ', null, 4028016),
('ramayana-4-28-17', 17, 'Kishkindha Kanda, Sarga 28, Verse 17', 'तस्य त्वं कुरु वै कार्यं पूर्वं तेन कृतं तव।
हरीश्वर हरिश्रेष्ठानाज्ञापयितुमर्हसि॥', 'tasya tvaṃ kuru vai kāryaṃ pūrvaṃ tena kṛtaṃ tava
harīśvara hariśreṣṭhān ājñāpayitum arhasi', null, 4028017),
('ramayana-4-28-18', 18, 'Kishkindha Kanda, Sarga 28, Verse 18', 'न हि तावद्भवेत्कालो व्यतीतश्चोदनादृते।
चोदितस्य हि कार्यस्य भवेत्कालव्यतिक्रमः॥', 'na hi tāvad bhavet kālo vyatītaś codanād ṛte
coditasya hi kāryasya bhavet kālavyatikramaḥ', null, 4028018),
('ramayana-4-28-19', 19, 'Kishkindha Kanda, Sarga 28, Verse 19', 'अकर्तुरपि कार्यस्य भवान्कर्ता हरीश्वर।
किं पुनः प्रतिकर्तुस्ते राज्येन च धनेन च॥', 'akartur api kāryasya bhavān kartā harīśvara
kiṃ punaḥ pratikartus te rājyena ca dhanena ca', null, 4028019),
('ramayana-4-28-20', 20, 'Kishkindha Kanda, Sarga 28, Verse 20', 'शक्तिमानसि विक्रान्तो वानरर्ष्क गणेश्वर।
कर्तुं दाशरथेः प्रीतिमाज्ञायां किं नु सज्जसे॥', 'śaktimān asi vikrānto vānararṣka gaṇeśvara
kartuṃ dāśaratheḥ prītim ājñāyāṃ kiṃ nu sajjase', null, 4028020),
('ramayana-4-28-21', 21, 'Kishkindha Kanda, Sarga 28, Verse 21', 'कामं खलु शरैर्शक्तः सुरासुरमहोरगान्।
वशे दाशरथिः कर्तुं त्वत्प्रतिज्ञां तु काङ्क्षते॥', 'kāmaṃ khalu śarair śaktaḥ surāsuramahoragān
vaśe dāśarathiḥ kartuṃ tvatpratijñāṃ tu kāṅkṣate', null, 4028021),
('ramayana-4-28-22', 22, 'Kishkindha Kanda, Sarga 28, Verse 22', 'प्राणत्यागाविशङ्केन कृतं तेन तव प्रियम्।
तस्य मार्गाम वैदेहीं पृथिव्यामपि चाम्बरे॥', 'prāṇatyāgāviśaṅkena kṛtaṃ tena tava priyam
tasya mārgāma vaidehīṃ pṛthivyām api cāmbare', null, 4028022),
('ramayana-4-28-23', 23, 'Kishkindha Kanda, Sarga 28, Verse 23', 'न देवा न च गन्धर्वा नासुरा न मरुद्गणाः।
न च यक्षा भयं तस्य कुर्युः किमुत राक्षसाः॥', 'na devā na ca gandharvā nāsurā na marudgaṇāḥ
na ca yakṣā bhayaṃ tasya kuryuḥ kim uta rākṣasāḥ', null, 4028023),
('ramayana-4-28-24', 24, 'Kishkindha Kanda, Sarga 28, Verse 24', 'तदेवं शक्तियुक्तस्य पूर्वं प्रियकृतस्तथा।
रामस्यार्हसि पिङ्गेश कर्तुं सर्वात्मना प्रियम्॥', 'tad evaṃ śaktiyuktasya pūrvaṃ priyakṛtas tathā
rāmasyārhasi piṅgeśa kartuṃ sarvātmanā priyam', null, 4028024),
('ramayana-4-28-25', 25, 'Kishkindha Kanda, Sarga 28, Verse 25', 'नाधस्तादवनौ नाप्सु गतिर्नोपरि चाम्बरे।
कस्य चित्सज्जतेऽस्माकं कपीश्वर तवाज्ञया॥', 'nādhastād avanau nāpsu gatir nopari cāmbare
kasya cit sajjate ''smākaṃ kapīśvara tavājñayā', null, 4028025),
('ramayana-4-28-26', 26, 'Kishkindha Kanda, Sarga 28, Verse 26', 'तदाज्ञापय कः किं ते कृते वसतु कुत्र चित्।
हरयो ह्यप्रधृष्यास्ते सन्ति कोट्यग्रतोऽनघ॥', 'tad ājñāpaya kaḥ kiṃ te kṛte vasatu kutra cit
harayo hy apradhṛṣyās te santi koṭyagrato ''nagha', null, 4028026),
('ramayana-4-28-27', 27, 'Kishkindha Kanda, Sarga 28, Verse 27', 'तस्य तद्वचनं श्रुत्वा काले साधुनिवेदितम्।
सुग्रीवः सत्त्वसंपन्नश्चकार मतिमुत्तमाम्॥', 'tasya tad vacanaṃ śrutvā kāle sādhuniveditam
sugrīvaḥ sattvasaṃpannaś cakāra matim uttamām', null, 4028027),
('ramayana-4-28-28', 28, 'Kishkindha Kanda, Sarga 28, Verse 28', 'स संदिदेशाभिमतं नीलं नित्यकृतोद्यमम्।
दिक्षु सर्वासु सर्वेषां सैन्यानामुपसंग्रहे॥', 'sa saṃdideśābhimataṃ nīlaṃ nityakṛtodyamam
dikṣu sarvāsu sarveṣāṃ sainyānām upasaṃgrahe', null, 4028028),
('ramayana-4-28-29', 29, 'Kishkindha Kanda, Sarga 28, Verse 29', 'यथा सेना समग्रा मे यूथपालाश्च सर्वशः।
समागच्छन्त्यसंगेन सेनाग्राणि तथा कुरु॥', 'yathā senā samagrā me yūthapālāś ca sarvaśaḥ
samāgacchanty asaṃgena senāgrāṇi tathā kuru', null, 4028029),
('ramayana-4-28-30', 30, 'Kishkindha Kanda, Sarga 28, Verse 30', 'ये त्वन्तपालाः प्लवगाः शीघ्रगा व्यवसायिनः।
समानयन्तु ते सैन्यं त्वरिताः शासनान्मम।
स्वयं चानन्तरं सैन्यं भवानेवानुपश्यतु॥', 'ye tv antapālāḥ plavagāḥ śīghragā vyavasāyinaḥ
samānayantu te sainyaṃ tvaritāḥ śāsanān mama
svayaṃ cānantaraṃ sainyaṃ bhavān evānupaśyatu', null, 4028030),
('ramayana-4-28-31', 31, 'Kishkindha Kanda, Sarga 28, Verse 31', 'त्रिपञ्चरात्रादूर्ध्वं यः प्राप्नुयान्नेह वानरः।
तस्य प्राणान्तिको दण्डो नात्र कार्या विचारणा॥', 'tripañcarātrād ūrdhvaṃ yaḥ prāpnuyān neha vānaraḥ
tasya prāṇāntiko daṇḍo nātra kāryā vicāraṇā', null, 4028031),
('ramayana-4-28-32', 32, 'Kishkindha Kanda, Sarga 28, Verse 32', 'हरींश्च वृद्धानुपयातु साङ्गदो भवान्ममाज्ञामधिकृत्य निश्चिताम्।
इति व्यवस्थां हरिपुंगवेश्वरो विधाय वेश्म प्रविवेश वीर्यवान्॥', 'harīṃś ca vṛddhān upayātu sāṅgado bhavān mamājñām adhikṛtya niścitām
iti vyavasthāṃ haripuṃgaveśvaro vidhāya veśma praviveśa vīryavān', null, 4028032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 29 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-29-1', 1, 'Kishkindha Kanda, Sarga 29, Verse 1', 'गुहां प्रविष्टे सुग्रीवे विमुक्ते गगने घनैः।
वर्षरात्रोषितो रामः कामशोकाभिपीडितः॥', 'guhāṃ praviṣṭe sugrīve vimukte gagane ghanaiḥ
varṣarātroṣito rāmaḥ kāmaśokābhipīḍitaḥ', null, 4029001),
('ramayana-4-29-2', 2, 'Kishkindha Kanda, Sarga 29, Verse 2', 'पाण्डुरं गगनं दृष्ट्वा विमलं चन्द्रमण्डलम्।
शारदीं रजनीं चैव दृष्ट्वा ज्योत्स्नानुलेपनाम्॥', 'pāṇḍuraṃ gaganaṃ dṛṣṭvā vimalaṃ candramaṇḍalam
śāradīṃ rajanīṃ caiva dṛṣṭvā jyotsnānulepanām', null, 4029002),
('ramayana-4-29-3', 3, 'Kishkindha Kanda, Sarga 29, Verse 3', 'कामवृत्तं च सुग्रीवं नष्टां च जनकात्मजाम्।
बुद्ध्वा कालमतीतं च मुमोह परमातुरः॥', 'kāmavṛttaṃ ca sugrīvaṃ naṣṭāṃ ca janakātmajām
buddhvā kālam atītaṃ ca mumoha paramāturaḥ', null, 4029003),
('ramayana-4-29-4', 4, 'Kishkindha Kanda, Sarga 29, Verse 4', 'स तु संज्ञामुपागम्य मुहूर्तान्मतिमान्पुनः।
मनःस्थामपि वैदेहीं चिन्तयामास राघवः॥', 'sa tu saṃjñām upāgamya muhūrtān matimān punaḥ
manaḥsthām api vaidehīṃ cintayām āsa rāghavaḥ', null, 4029004),
('ramayana-4-29-5', 5, 'Kishkindha Kanda, Sarga 29, Verse 5', 'आसीनः पर्वतस्याग्रे हेमधातुविभूषिते।
शारदं गगनं दृष्ट्व जगाम मनसा प्रियाम्॥', 'āsīnaḥ parvatasyāgre hemadhātuvibhūṣite
śāradaṃ gaganaṃ dṛṣṭva jagāma manasā priyām', null, 4029005),
('ramayana-4-29-6', 6, 'Kishkindha Kanda, Sarga 29, Verse 6', 'दृष्ट्वा च विमलं व्योम गतविद्युद्बलाहकम्।
सारसारवसंघुष्टं विललापार्तया गिरा॥', 'dṛṣṭvā ca vimalaṃ vyoma gatavidyudbalāhakam
sārasāravasaṃghuṣṭaṃ vilalāpārtayā girā', null, 4029006),
('ramayana-4-29-7', 7, 'Kishkindha Kanda, Sarga 29, Verse 7', 'सारसारवसंनादैः सारसारवनादिनी।
याश्रमे रमते बाला साद्य मे रमते कथम्॥', 'sārasāravasaṃnādaiḥ sārasāravanādinī
yāśrame ramate bālā sādya me ramate katham', null, 4029007),
('ramayana-4-29-8', 8, 'Kishkindha Kanda, Sarga 29, Verse 8', 'पुष्पितांश्चासनान्दृष्ट्वा काञ्चनानिव निर्मलान्।
कथं स रमते बाला पश्यन्ती मामपश्यती॥', 'puṣpitāṃś cāsanān dṛṣṭvā kāñcanān iva nirmalān
kathaṃ sa ramate bālā paśyantī mām apaśyatī', null, 4029008),
('ramayana-4-29-9', 9, 'Kishkindha Kanda, Sarga 29, Verse 9', 'या पुरा कलहंसानां स्वरेण कलभाषिणी।
बुध्यते चारुसर्वाङ्गी साद्य मे बुध्यते कथम्॥', 'yā purā kalahaṃsānāṃ svareṇa kalabhāṣiṇī
budhyate cārusarvāṅgī sādya me budhyate katham', null, 4029009),
('ramayana-4-29-10', 10, 'Kishkindha Kanda, Sarga 29, Verse 10', 'निःस्वनं चक्रवाकानां निशम्य सहचारिणाम्।
पुण्डरीकविशालाक्षी कथमेषा भविष्यति॥', 'niḥsvanaṃ cakravākānāṃ niśamya sahacāriṇām
puṇḍarīkaviśālākṣī katham eṣā bhaviṣyati', null, 4029010),
('ramayana-4-29-11', 11, 'Kishkindha Kanda, Sarga 29, Verse 11', 'सरांसि सरितो वापीः काननानि वनानि च।
तां विना मृगशावाक्षीं चरन्नाद्य सुखं लभे॥', 'sarāṃsi sarito vāpīḥ kānanāni vanāni ca
tāṃ vinā mṛgaśāvākṣīṃ caran nādya sukhaṃ labhe', null, 4029011),
('ramayana-4-29-12', 12, 'Kishkindha Kanda, Sarga 29, Verse 12', 'अपि तां मद्वियोगाच्च सौकुमार्याच्च भामिनीम्।
न दूरं पीडयेत्कामः शरद्गुणनिरन्तरः॥', 'api tāṃ madviyogāc ca saukumāryāc ca bhāminīm
na dūraṃ pīḍayet kāmaḥ śaradguṇanirantaraḥ', null, 4029012),
('ramayana-4-29-13', 13, 'Kishkindha Kanda, Sarga 29, Verse 13', 'एवमादि नरश्रेष्ठो विललाप नृपात्मजः।
विहंग इव सारङ्गः सलिलं त्रिदशेश्वरात्॥', 'evamādi naraśreṣṭho vilalāpa nṛpātmajaḥ
vihaṃga iva sāraṅgaḥ salilaṃ tridaśeśvarāt', null, 4029013),
('ramayana-4-29-14', 14, 'Kishkindha Kanda, Sarga 29, Verse 14', 'ततश्चञ्चूर्य रम्येषु फलार्थी गिरिसानुषु।
ददर्श पर्युपावृत्तो लक्ष्मीवांल्लक्ष्मणोऽग्रजम्॥', 'tataś cañcūrya ramyeṣu phalārthī girisānuṣu
dadarśa paryupāvṛtto lakṣmīvāṃl lakṣmaṇo ''grajam', null, 4029014),
('ramayana-4-29-15', 15, 'Kishkindha Kanda, Sarga 29, Verse 15', 'तं चिन्तया दुःसहया परीतं विसंज्ञमेकं विजने मनस्वी।
भ्रातुर्विषादात्परितापदीनः समीक्ष्य सौमित्रिरुवाच रामम्॥', 'taṃ cintayā duḥsahayā parītaṃ visaṃjñam ekaṃ vijane manasvī
bhrātur viṣādāt paritāpadīnaḥ samīkṣya saumitrir uvāca rāmam', null, 4029015),
('ramayana-4-29-16', 16, 'Kishkindha Kanda, Sarga 29, Verse 16', 'किमार्य कामस्य वशंगतेन किमात्मपौरुष्यपराभवेन।
अयं सदा संहृइयते समाधिः किमत्र योगेन निवर्तितेन॥', 'kim ārya kāmasya vaśaṃgatena kim ātmapauruṣyaparābhavena
ayaṃ sadā saṃhṛiyate samādhiḥ kim atra yogena nivartitena', null, 4029016),
('ramayana-4-29-17', 17, 'Kishkindha Kanda, Sarga 29, Verse 17', 'क्रियाभियोगं मनसः प्रसादं समाधियोगानुगतं च कालम्।
सहायसामर्थ्यमदीनसत्त्व स्वकर्महेतुं च कुरुष्व हेतुम्॥', 'kriyābhiyogaṃ manasaḥ prasādaṃ samādhiyogānugataṃ ca kālam
sahāyasāmarthyam adīnasattva svakarmahetuṃ ca kuruṣva hetum', null, 4029017),
('ramayana-4-29-18', 18, 'Kishkindha Kanda, Sarga 29, Verse 18', 'न जानकी मानववंशनाथ त्वया सनाथा सुलभा परेण।
न चाग्निचूडां ज्वलितामुपेत्य न दह्यते वीरवरार्ह कश्चित्॥', 'na jānakī mānavavaṃśanātha tvayā sanāthā sulabhā pareṇa
na cāgnicūḍāṃ jvalitām upetya na dahyate vīravarārha kaś cit', null, 4029018),
('ramayana-4-29-19', 19, 'Kishkindha Kanda, Sarga 29, Verse 19', 'सलक्ष्मणं लक्ष्मणमप्रधृष्यं स्वभावजं वाक्यमुवाच रामः।
हितं च पथ्यं च नयप्रसक्तं ससामधर्मार्थसमाहितं च॥', 'salakṣmaṇaṃ lakṣmaṇam apradhṛṣyaṃ svabhāvajaṃ vākyam uvāca rāmaḥ
hitaṃ ca pathyaṃ ca nayaprasaktaṃ sasāmadharmārthasamāhitaṃ ca', null, 4029019),
('ramayana-4-29-20', 20, 'Kishkindha Kanda, Sarga 29, Verse 20', 'निःसंशयं कार्यमवेक्षितव्यं क्रियाविशेषो ह्यनुवर्तितव्यः।
ननु प्रवृत्तस्य दुरासदस्य कुमारकार्यस्य फलं न चिन्त्यम्॥', 'niḥsaṃśayaṃ kāryam avekṣitavyaṃ kriyāviśeṣo hy anuvartitavyaḥ
nanu pravṛttasya durāsadasya kumārakāryasya phalaṃ na cintyam', null, 4029020),
('ramayana-4-29-21', 21, 'Kishkindha Kanda, Sarga 29, Verse 21', 'अथ पद्मपलाशाक्षीं मैथिलीमनुचिन्तयन्।
उवाच लक्ष्मणं रामो मुखेन परिशुष्यता॥', 'atha padmapalāśākṣīṃ maithilīm anucintayan
uvāca lakṣmaṇaṃ rāmo mukhena pariśuṣyatā', null, 4029021),
('ramayana-4-29-22', 22, 'Kishkindha Kanda, Sarga 29, Verse 22', 'तर्पयित्वा सहस्राक्षः सलिलेन वसुंधराम्।
निर्वर्तयित्वा सस्यानि कृतकर्मा व्यवस्थितः॥', 'tarpayitvā sahasrākṣaḥ salilena vasuṃdharām
nirvartayitvā sasyāni kṛtakarmā vyavasthitaḥ', null, 4029022),
('ramayana-4-29-23', 23, 'Kishkindha Kanda, Sarga 29, Verse 23', 'स्निग्धगम्भीरनिर्घोषाः शैलद्रुमपुरोगमाः।
विसृज्य सलिलं मेघाः परिश्रान्ता नृपात्मज॥', 'snigdhagambhīranirghoṣāḥ śailadrumapurogamāḥ
visṛjya salilaṃ meghāḥ pariśrāntā nṛpātmaja', null, 4029023),
('ramayana-4-29-24', 24, 'Kishkindha Kanda, Sarga 29, Verse 24', 'नीलोत्पलदलश्यामः श्यामीकृत्वा दिशो दश।
विमदा इव मातङ्गाः शान्तवेगाः पयोधराः॥', 'nīlotpaladalaśyāmaḥ śyāmīkṛtvā diśo daśa
vimadā iva mātaṅgāḥ śāntavegāḥ payodharāḥ', null, 4029024),
('ramayana-4-29-25', 25, 'Kishkindha Kanda, Sarga 29, Verse 25', 'जलगर्भा महावेगाः कुटजार्जुनगन्धिनः।
चरित्वा विरताः सौम्य वृष्टिवाताः समुद्यताः॥', 'jalagarbhā mahāvegāḥ kuṭajārjunagandhinaḥ
caritvā viratāḥ saumya vṛṣṭivātāḥ samudyatāḥ', null, 4029025),
('ramayana-4-29-26', 26, 'Kishkindha Kanda, Sarga 29, Verse 26', 'घनानां वारणानां च मयूराणां च लक्ष्मण।
नादः प्रस्रवणानां च प्रशान्तः सहसानघ॥', 'ghanānāṃ vāraṇānāṃ ca mayūrāṇāṃ ca lakṣmaṇa
nādaḥ prasravaṇānāṃ ca praśāntaḥ sahasānagha', null, 4029026),
('ramayana-4-29-27', 27, 'Kishkindha Kanda, Sarga 29, Verse 27', 'अभिवृष्टा महामेघैर्निर्मलाश्चित्रसानवः।
अनुलिप्ता इवाभान्ति गिरयश्चन्द्ररश्मिभिः॥', 'abhivṛṣṭā mahāmeghair nirmalāś citrasānavaḥ
anuliptā ivābhānti girayaś candraraśmibhiḥ', null, 4029027),
('ramayana-4-29-28', 28, 'Kishkindha Kanda, Sarga 29, Verse 28', 'दर्शयन्ति शरन्नद्यः पुलिनानि शनैः शनैः।
नवसंगमसव्रीडा जघनानीव योषितः॥', 'darśayanti śarannadyaḥ pulināni śanaiḥ śanaiḥ
navasaṃgamasavrīḍā jaghanānīva yoṣitaḥ', null, 4029028),
('ramayana-4-29-29', 29, 'Kishkindha Kanda, Sarga 29, Verse 29', 'प्रसन्नसलिलाः सौम्य कुररीभिर्विनादिताः।
चक्रवाकगणाकीर्णा विभान्ति सलिलाशयाः॥', 'prasannasalilāḥ saumya kurarībhir vināditāḥ
cakravākagaṇākīrṇā vibhānti salilāśayāḥ', null, 4029029),
('ramayana-4-29-30', 30, 'Kishkindha Kanda, Sarga 29, Verse 30', 'अन्योन्यबद्धवैराणां जिगीषूणां नृपात्मज।
उद्योगसमयः सौम्य पार्थिवानामुपस्थितः॥', 'anyonyabaddhavairāṇāṃ jigīṣūṇāṃ nṛpātmaja
udyogasamayaḥ saumya pārthivānām upasthitaḥ', null, 4029030),
('ramayana-4-29-31', 31, 'Kishkindha Kanda, Sarga 29, Verse 31', 'इयं सा प्रथमा यात्रा पार्थिवानां नृपात्मज।
न च पश्यामि सुग्रीवमुद्योगं वा तथाविधम्॥', 'iyaṃ sā prathamā yātrā pārthivānāṃ nṛpātmaja
na ca paśyāmi sugrīvam udyogaṃ vā tathāvidham', null, 4029031),
('ramayana-4-29-32', 32, 'Kishkindha Kanda, Sarga 29, Verse 32', 'चत्वारो वार्षिका मासा गता वर्षशतोपमाः।
मम शोकाभितप्तस्य सौम्य सीतामपश्यतः॥', 'catvāro vārṣikā māsā gatā varṣaśatopamāḥ
mama śokābhitaptasya saumya sītām apaśyataḥ', null, 4029032),
('ramayana-4-29-33', 33, 'Kishkindha Kanda, Sarga 29, Verse 33', 'प्रियाविहीने दुःखार्ते हृतराज्ये विवासिते।
कृपां न कुरुते राजा सुग्रीवो मयि लक्ष्मण॥', 'priyāvihīne duḥkhārte hṛtarājye vivāsite
kṛpāṃ na kurute rājā sugrīvo mayi lakṣmaṇa', null, 4029033),
('ramayana-4-29-34', 34, 'Kishkindha Kanda, Sarga 29, Verse 34', 'अनाथो हृतराज्योऽयं रावणेन च धर्षितः।
दीनो दूरगृहः कामी मां चैव शरणं गतः॥', 'anātho hṛtarājyo ''yaṃ rāvaṇena ca dharṣitaḥ
dīno dūragṛhaḥ kāmī māṃ caiva śaraṇaṃ gataḥ', null, 4029034),
('ramayana-4-29-35', 35, 'Kishkindha Kanda, Sarga 29, Verse 35', 'इत्येतैः कारणैः सौम्य सुग्रीवस्य दुरात्मनः।
अहं वानरराजस्य परिभूतः परंतप॥', 'ity etaiḥ kāraṇaiḥ saumya sugrīvasya durātmanaḥ
ahaṃ vānararājasya paribhūtaḥ paraṃtapa', null, 4029035),
('ramayana-4-29-36', 36, 'Kishkindha Kanda, Sarga 29, Verse 36', 'स कालं परिसंख्याय सीतायाः परिमार्गणे।
कृतार्थः समयं कृत्वा दुर्मतिर्नावबुध्यते॥', 'sa kālaṃ parisaṃkhyāya sītāyāḥ parimārgaṇe
kṛtārthaḥ samayaṃ kṛtvā durmatir nāvabudhyate', null, 4029036),
('ramayana-4-29-37', 37, 'Kishkindha Kanda, Sarga 29, Verse 37', 'त्वं प्रविश्य च किष्किन्धां ब्रूहि वानरपुंगवम्।
मूर्खं ग्राम्य सुखे सक्तं सुग्रीवं वचनान्मम॥', 'tvaṃ praviśya ca kiṣkindhāṃ brūhi vānarapuṃgavam
mūrkhaṃ grāmya sukhe saktaṃ sugrīvaṃ vacanān mama', null, 4029037),
('ramayana-4-29-38', 38, 'Kishkindha Kanda, Sarga 29, Verse 38', 'अर्थिनामुपपन्नानां पूर्वं चाप्युपकारिणाम्।
आशां संश्रुत्य यो हन्ति स लोके पुरुषाधमः॥', 'arthinām upapannānāṃ pūrvaṃ cāpy upakāriṇām
āśāṃ saṃśrutya yo hanti sa loke puruṣādhamaḥ', null, 4029038),
('ramayana-4-29-39', 39, 'Kishkindha Kanda, Sarga 29, Verse 39', 'शुभं वा यदि वा पापं यो हि वाक्यमुदीरितम्।
सत्येन परिगृह्णाति स वीरः पुरुषोत्तमः॥', 'śubhaṃ vā yadi vā pāpaṃ yo hi vākyam udīritam
satyena parigṛhṇāti sa vīraḥ puruṣottamaḥ', null, 4029039),
('ramayana-4-29-40', 40, 'Kishkindha Kanda, Sarga 29, Verse 40', 'कृतार्था ह्यकृतार्थानां मित्राणां न भवन्ति ये।
तान्मृतानपि क्रव्यादः कृतघ्नान्नोपभुञ्जते॥', 'kṛtārthā hy akṛtārthānāṃ mitrāṇāṃ na bhavanti ye
tān mṛtān api kravyādaḥ kṛtaghnān nopabhuñjate', null, 4029040),
('ramayana-4-29-41', 41, 'Kishkindha Kanda, Sarga 29, Verse 41', 'नूनं काञ्चनपृष्ठस्य विकृष्टस्य मया रणे।
द्रष्टुमिच्छन्ति चापस्य रूपं विद्युद्गणोपमम्॥', 'nūnaṃ kāñcanapṛṣṭhasya vikṛṣṭasya mayā raṇe
draṣṭum icchanti cāpasya rūpaṃ vidyudgaṇopamam', null, 4029041),
('ramayana-4-29-42', 42, 'Kishkindha Kanda, Sarga 29, Verse 42', 'घोरं ज्यातलनिर्घोषं क्रुद्धस्य मम संयुगे।
निर्घोषमिव वज्रस्य पुनः संश्रोतुमिच्छति॥', 'ghoraṃ jyātalanirghoṣaṃ kruddhasya mama saṃyuge
nirghoṣam iva vajrasya punaḥ saṃśrotum icchati', null, 4029042),
('ramayana-4-29-43', 43, 'Kishkindha Kanda, Sarga 29, Verse 43', 'काममेवंगतेऽप्यस्य परिज्ञाते पराक्रमे।
त्वत्सहायस्य मे वीर न चिन्ता स्यान्नृपात्मज॥', 'kāmam evaṃgate ''py asya parijñāte parākrame
tvatsahāyasya me vīra na cintā syān nṛpātmaja', null, 4029043),
('ramayana-4-29-44', 44, 'Kishkindha Kanda, Sarga 29, Verse 44', 'यदर्थमयमारम्भः कृतः परपुरंजय।
समयं नाभिजानाति कृतार्थः प्लवगेश्वरः॥', 'yadartham ayam ārambhaḥ kṛtaḥ parapuraṃjaya
samayaṃ nābhijānāti kṛtārthaḥ plavageśvaraḥ', null, 4029044),
('ramayana-4-29-45', 45, 'Kishkindha Kanda, Sarga 29, Verse 45', 'वर्षासमयकालं तु प्रतिज्ञाय हरीश्वरः।
व्यतीतांश्चतुरो मासान्विहरन्नावबुध्यते॥', 'varṣāsamayakālaṃ tu pratijñāya harīśvaraḥ
vyatītāṃś caturo māsān viharan nāvabudhyate', null, 4029045),
('ramayana-4-29-46', 46, 'Kishkindha Kanda, Sarga 29, Verse 46', 'सामात्यपरिषत्क्रीडन्पानमेवोपसेवते।
शोकदीनेषु नास्मासु सुग्रीवः कुरुते दयाम्॥', 'sāmātyapariṣat krīḍan pānam evopasevate
śokadīneṣu nāsmāsu sugrīvaḥ kurute dayām', null, 4029046),
('ramayana-4-29-47', 47, 'Kishkindha Kanda, Sarga 29, Verse 47', 'उच्यतां गच्छ सुग्रीवस्त्वया वत्स महाबल।
मम रोषस्य यद्रूपं ब्रूयाश्चैनमिदं वचः॥', 'ucyatāṃ gaccha sugrīvas tvayā vatsa mahābala
mama roṣasya yadrūpaṃ brūyāś cainam idaṃ vacaḥ', null, 4029047),
('ramayana-4-29-48', 48, 'Kishkindha Kanda, Sarga 29, Verse 48', 'न च संकुचितः पन्था येन वाली हतो गतः।
समये तिष्ठ सुग्रीवमा वालिपथमन्वगाः॥', 'na ca saṃkucitaḥ panthā yena vālī hato gataḥ
samaye tiṣṭha sugrīvamā vālipatham anvagāḥ', null, 4029048),
('ramayana-4-29-49', 49, 'Kishkindha Kanda, Sarga 29, Verse 49', 'एक एव रणे वाली शरेण निहतो मया।
त्वां तु सत्यादतिक्रान्तं हनिष्यामि सबान्धवम्॥', 'eka eva raṇe vālī śareṇa nihato mayā
tvāṃ tu satyād atikrāntaṃ haniṣyāmi sabāndhavam', null, 4029049),
('ramayana-4-29-50', 50, 'Kishkindha Kanda, Sarga 29, Verse 50', 'तदेवं विहिते कार्ये यद्धितं पुरुषर्षभ।
तत्तद्ब्रूहि नरश्रेष्ठ त्वर कालव्यतिक्रमः॥', 'tad evaṃ vihite kārye yad dhitaṃ puruṣarṣabha
tat tad brūhi naraśreṣṭha tvara kālavyatikramaḥ', null, 4029050),
('ramayana-4-29-51', 51, 'Kishkindha Kanda, Sarga 29, Verse 51', 'कुरुष्व सत्यं मयि वानरेश्वर प्रतिश्रुतं धर्ममवेक्ष्य शाश्वतम्।
मा वालिनं प्रेत्य गतो यमक्षयं त्वमद्य पश्येर्मम चोदितैः शरैः॥', 'kuruṣva satyaṃ mayi vānareśvara pratiśrutaṃ dharmam avekṣya śāśvatam
mā vālinaṃ pretya gato yamakṣayaṃ tvam adya paśyer mama coditaiḥ śaraiḥ', null, 4029051),
('ramayana-4-29-52', 52, 'Kishkindha Kanda, Sarga 29, Verse 52', 'स पूर्वजं तीव्रविवृद्धकोपं लालप्यमानं प्रसमीक्ष्य दीनम्।
चकार तीव्रां मतिमुग्रतेजा हरीश्वरमानववंशनाथः॥', 'sa pūrvajaṃ tīvravivṛddhakopaṃ lālapyamānaṃ prasamīkṣya dīnam
cakāra tīvrāṃ matim ugratejā harīśvaramānavavaṃśanāthaḥ', null, 4029052)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 30 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-30-1', 1, 'Kishkindha Kanda, Sarga 30, Verse 1', 'स कामिनं दीनमदीनसत्त्वः शोकाभिपन्नं समुदीर्णकोपम्।
नरेन्द्रसूनुर्नरदेवपुत्रं रामानुजः पूर्वजमित्युवाच॥', 'sa kāminaṃ dīnam adīnasattvaḥ śokābhipannaṃ samudīrṇakopam
narendrasūnur naradevaputraṃ rāmānujaḥ pūrvajam ity uvāca', null, 4030001),
('ramayana-4-30-2', 2, 'Kishkindha Kanda, Sarga 30, Verse 2', 'न वानरः स्थास्यति साधुवृत्ते न मंस्यते कार्यफलानुषङ्गान्।
न भक्ष्यते वानरराज्यलक्ष्मीं तथा हि नाभिक्रमतेऽस्य बुद्धिः॥', 'na vānaraḥ sthāsyati sādhuvṛtte na maṃsyate kāryaphalānuṣaṅgān
na bhakṣyate vānararājyalakṣmīṃ tathā hi nābhikramate ''sya buddhiḥ', null, 4030002),
('ramayana-4-30-3', 3, 'Kishkindha Kanda, Sarga 30, Verse 3', 'मतिक्षयाद्ग्राम्यसुखेषु सक्तस्तव प्रसादाप्रतिकारबुद्धिः।
हतोऽग्रजं पश्यतु वालिनं स न राज्यमेवं विगुणस्य देयम्॥', 'matikṣayād grāmyasukheṣu saktas tava prasādāpratikārabuddhiḥ
hato ''grajaṃ paśyatu vālinaṃ sa na rājyam evaṃ viguṇasya deyam', null, 4030003),
('ramayana-4-30-4', 4, 'Kishkindha Kanda, Sarga 30, Verse 4', 'न धारये कोपमुदीर्णवेगं निहन्मि सुग्रीवमसत्यमद्य।
हरिप्रवीरैः सह वालिपुत्रो नरेन्द्रपत्न्या विचयं करोतु॥', 'na dhāraye kopam udīrṇavegaṃ nihanmi sugrīvam asatyam adya
haripravīraiḥ saha vāliputro narendrapatnyā vicayaṃ karotu', null, 4030004),
('ramayana-4-30-5', 5, 'Kishkindha Kanda, Sarga 30, Verse 5', 'तमात्तबाणासनमुत्पतन्तं निवेदितार्थं रणचण्डकोपम्।
उवच रामः परवीरहन्ता स्ववेक्षितं सानुनयं च वाक्यम्॥', 'tam āttabāṇāsanam utpatantaṃ niveditārthaṃ raṇacaṇḍakopam
uvaca rāmaḥ paravīrahantā svavekṣitaṃ sānunayaṃ ca vākyam', null, 4030005),
('ramayana-4-30-6', 6, 'Kishkindha Kanda, Sarga 30, Verse 6', 'न हि वै त्वद्विधो लोके पापमेवं समाचरेत्।
पापमार्येण यो हन्ति स वीरः पुरुषोत्तमः॥', 'na hi vai tvadvidho loke pāpam evaṃ samācaret
pāpam āryeṇa yo hanti sa vīraḥ puruṣottamaḥ', null, 4030006),
('ramayana-4-30-7', 7, 'Kishkindha Kanda, Sarga 30, Verse 7', 'नेदमद्य त्वया ग्राह्यं साधुवृत्तेन लक्ष्मण।
तां प्रीतिमनुवर्तस्व पूर्ववृत्तं च संगतम्॥', 'nedam adya tvayā grāhyaṃ sādhuvṛttena lakṣmaṇa
tāṃ prītim anuvartasva pūrvavṛttaṃ ca saṃgatam', null, 4030007),
('ramayana-4-30-8', 8, 'Kishkindha Kanda, Sarga 30, Verse 8', 'सामोपहितया वाचा रूक्षाणि परिवर्जयन्।
वक्तुमर्हसि सुग्रीवं व्यतीतं कालपर्यये॥', 'sāmopahitayā vācā rūkṣāṇi parivarjayan
vaktum arhasi sugrīvaṃ vyatītaṃ kālaparyaye', null, 4030008),
('ramayana-4-30-9', 9, 'Kishkindha Kanda, Sarga 30, Verse 9', 'सोऽ ग्रजेनानुशिष्टार्थो यथावत्पुरुषर्षभः।
प्रविवेश पुरीं वीरो लक्ष्मणः परवीरहा॥', 'so'' grajenānuśiṣṭārtho yathāvat puruṣarṣabhaḥ
praviveśa purīṃ vīro lakṣmaṇaḥ paravīrahā', null, 4030009),
('ramayana-4-30-10', 10, 'Kishkindha Kanda, Sarga 30, Verse 10', 'ततः शुभमतिः प्राज्ञो भ्रातुः प्रियहिते रतः।
लक्ष्मणः प्रतिसंरब्धो जगाम भवनं कपेः॥', 'tataḥ śubhamatiḥ prājño bhrātuḥ priyahite rataḥ
lakṣmaṇaḥ pratisaṃrabdho jagāma bhavanaṃ kapeḥ', null, 4030010),
('ramayana-4-30-11', 11, 'Kishkindha Kanda, Sarga 30, Verse 11', 'शक्रबाणासनप्रख्यं धनुः कालान्तकोपमः।
प्रगृह्य गिरिशृङ्गाभं मन्दरः सानुमानिव॥', 'śakrabāṇāsanaprakhyaṃ dhanuḥ kālāntakopamaḥ
pragṛhya giriśṛṅgābhaṃ mandaraḥ sānumān iva', null, 4030011),
('ramayana-4-30-12', 12, 'Kishkindha Kanda, Sarga 30, Verse 12', 'यथोक्तकारी वचनमुत्तरं चैव सोत्तरम्।
बृहस्पतिसमो बुद्ध्या मत्त्वा रामानुजस्तदा॥', 'yathoktakārī vacanam uttaraṃ caiva sottaram
bṛhaspatisamo buddhyā mattvā rāmānujas tadā', null, 4030012),
('ramayana-4-30-13', 13, 'Kishkindha Kanda, Sarga 30, Verse 13', 'कामक्रोधसमुत्थेन भ्रातुः कोपाग्निना वृतः।
प्रभञ्जन इवाप्रीतः प्रययौ लक्ष्मणस्तदा॥', 'kāmakrodhasamutthena bhrātuḥ kopāgninā vṛtaḥ
prabhañjana ivāprītaḥ prayayau lakṣmaṇas tadā', null, 4030013),
('ramayana-4-30-14', 14, 'Kishkindha Kanda, Sarga 30, Verse 14', 'सालतालाश्वकर्णांश्च तरसा पातयन्बहून्।
पर्यस्यन्गिरिकूटानि द्रुमानन्यांश्च वेगतः॥', 'sālatālāśvakarṇāṃś ca tarasā pātayan bahūn
paryasyan girikūṭāni drumān anyāṃś ca vegataḥ', null, 4030014),
('ramayana-4-30-15', 15, 'Kishkindha Kanda, Sarga 30, Verse 15', 'शिलाश्च शकलीकुर्वन्पद्भ्यां गज इवाशुगः।
दूरमेकपदं त्यक्त्वा ययौ कार्यवशाद्द्रुतम्॥', 'śilāś ca śakalīkurvan padbhyāṃ gaja ivāśugaḥ
dūram ekapadaṃ tyaktvā yayau kāryavaśād drutam', null, 4030015),
('ramayana-4-30-16', 16, 'Kishkindha Kanda, Sarga 30, Verse 16', 'तामपश्यद्बलाकीर्णां हरिराजमहापुरीम्।
दुर्गामिक्ष्वाकुशार्दूलः किष्किन्धां गिरिसंकटे॥', 'tām apaśyad balākīrṇāṃ harirājamahāpurīm
durgām ikṣvākuśārdūlaḥ kiṣkindhāṃ girisaṃkaṭe', null, 4030016),
('ramayana-4-30-17', 17, 'Kishkindha Kanda, Sarga 30, Verse 17', 'रोषात्प्रस्फुरमाणौष्ठः सुग्रीवं प्रति कल्ष्मणः।
ददर्श वानरान्भीमान्किष्किन्धाया बहिश्चरान्॥', 'roṣāt prasphuramāṇauṣṭhaḥ sugrīvaṃ prati kalṣmaṇaḥ
dadarśa vānarān bhīmān kiṣkindhāyā bahiścarān', null, 4030017),
('ramayana-4-30-18', 18, 'Kishkindha Kanda, Sarga 30, Verse 18', 'शैलशृङ्गाणि शतशः प्रवृद्धांश्च महीरुहान्।
जगृहुः कुञ्जरप्रख्या वानराः पर्वतान्तरे॥', 'śailaśṛṅgāṇi śataśaḥ pravṛddhāṃś ca mahīruhān
jagṛhuḥ kuñjaraprakhyā vānarāḥ parvatāntare', null, 4030018),
('ramayana-4-30-19', 19, 'Kishkindha Kanda, Sarga 30, Verse 19', 'तान्गृहीतप्रहरणान्हरीन्दृष्ट्वा तु लक्ष्मणः।
बभूव द्विगुणं क्रुद्धो बह्विन्धन इवानलः॥', 'tān gṛhītapraharaṇān harīn dṛṣṭvā tu lakṣmaṇaḥ
babhūva dviguṇaṃ kruddho bahvindhana ivānalaḥ', null, 4030019),
('ramayana-4-30-20', 20, 'Kishkindha Kanda, Sarga 30, Verse 20', 'तं ते भयपरीताङ्गाः क्रुद्धं दृष्ट्वा प्लवंगमाः।
कालमृत्युयुगान्ताभं शतशो विद्रुता दिशः॥', 'taṃ te bhayaparītāṅgāḥ kruddhaṃ dṛṣṭvā plavaṃgamāḥ
kālamṛtyuyugāntābhaṃ śataśo vidrutā diśaḥ', null, 4030020),
('ramayana-4-30-21', 21, 'Kishkindha Kanda, Sarga 30, Verse 21', 'ततः सुग्रीवभवनं प्रविश्य हरिपुंगवाः।
क्रोधमागमनं चैव लक्ष्मणस्य न्यवेदयन्॥', 'tataḥ sugrīvabhavanaṃ praviśya haripuṃgavāḥ
krodham āgamanaṃ caiva lakṣmaṇasya nyavedayan', null, 4030021),
('ramayana-4-30-22', 22, 'Kishkindha Kanda, Sarga 30, Verse 22', 'तारया सहितः कामी सक्तः कपिवृषो रहः।
न तेषां कपिवीराणां शुश्राव वचनं तदा॥', 'tārayā sahitaḥ kāmī saktaḥ kapivṛṣo rahaḥ
na teṣāṃ kapivīrāṇāṃ śuśrāva vacanaṃ tadā', null, 4030022),
('ramayana-4-30-23', 23, 'Kishkindha Kanda, Sarga 30, Verse 23', 'ततः सचिवसंदिष्टा हरयो रोमहर्षणाः।
गिरिकुञ्जरमेघाभा नगर्या निर्ययुस्तदा॥', 'tataḥ sacivasaṃdiṣṭā harayo romaharṣaṇāḥ
girikuñjarameghābhā nagaryā niryayus tadā', null, 4030023),
('ramayana-4-30-24', 24, 'Kishkindha Kanda, Sarga 30, Verse 24', 'नखदंष्ट्रायुधा घोराः सर्वे विकृतदर्शनाः।
सर्वे शार्दूलदर्पाश्च सर्वे च विकृताननाः॥', 'nakhadaṃṣṭrāyudhā ghorāḥ sarve vikṛtadarśanāḥ
sarve śārdūladarpāś ca sarve ca vikṛtānanāḥ', null, 4030024),
('ramayana-4-30-25', 25, 'Kishkindha Kanda, Sarga 30, Verse 25', 'दशनागबलाः के चित्के चिद्दशगुणोत्तराः।
के चिन्नागसहस्रस्य बभूवुस्तुल्यविक्रमाः॥', 'daśanāgabalāḥ ke cit ke cid daśaguṇottarāḥ
ke cin nāgasahasrasya babhūvus tulyavikramāḥ', null, 4030025),
('ramayana-4-30-26', 26, 'Kishkindha Kanda, Sarga 30, Verse 26', 'कृत्स्नां हि कपिभिर्व्याप्तां द्रुमहस्तैर्महाबलैः।
अपश्यल्लक्ष्मणः क्रुद्धः किष्किन्धां तां दुरासदम्॥', 'kṛtsnāṃ hi kapibhir vyāptāṃ drumahastair mahābalaiḥ
apaśyal lakṣmaṇaḥ kruddhaḥ kiṣkindhāṃ tāṃ durāsadam', null, 4030026),
('ramayana-4-30-27', 27, 'Kishkindha Kanda, Sarga 30, Verse 27', 'ततस्ते हरयः सर्वे प्राकारपरिखान्तरात्।
निष्क्रम्योदग्रसत्त्वास्तु तस्थुराविष्कृतं तदा॥', 'tatas te harayaḥ sarve prākāraparikhāntarāt
niṣkramyodagrasattvās tu tasthur āviṣkṛtaṃ tadā', null, 4030027),
('ramayana-4-30-28', 28, 'Kishkindha Kanda, Sarga 30, Verse 28', 'सुग्रीवस्य प्रमादं च पूर्वजं चार्तमात्मवान्।
बुद्ध्वा कोपवशं वीरः पुनरेव जगाम सः॥', 'sugrīvasya pramādaṃ ca pūrvajaṃ cārtam ātmavān
buddhvā kopavaśaṃ vīraḥ punar eva jagāma saḥ', null, 4030028),
('ramayana-4-30-29', 29, 'Kishkindha Kanda, Sarga 30, Verse 29', 'स दीर्घोष्णमहोच्छ्वासः कोपसंरक्तलोचनः।
बभूव नरशार्दूलसधूम इव पावकः॥', 'sa dīrghoṣṇamahocchvāsaḥ kopasaṃraktalocanaḥ
babhūva naraśārdūlasadhūma iva pāvakaḥ', null, 4030029),
('ramayana-4-30-30', 30, 'Kishkindha Kanda, Sarga 30, Verse 30', 'बाणशल्यस्फुरज्जिह्वः सायकासनभोगवान्।
स्वतेजोविषसंघातः पञ्चास्य इव पन्नगः॥', 'bāṇaśalyasphurajjihvaḥ sāyakāsanabhogavān
svatejoviṣasaṃghātaḥ pañcāsya iva pannagaḥ', null, 4030030),
('ramayana-4-30-31', 31, 'Kishkindha Kanda, Sarga 30, Verse 31', 'तं दीप्तमिव कालाग्निं नागेन्द्रमिव कोपितम्।
समासाद्याङ्गदस्त्रासाद्विषादमगमद्भृशम्॥', 'taṃ dīptam iva kālāgniṃ nāgendram iva kopitam
samāsādyāṅgadas trāsād viṣādam agamad bhṛśam', null, 4030031),
('ramayana-4-30-32', 32, 'Kishkindha Kanda, Sarga 30, Verse 32', 'सोऽङ्गदं रोषताम्राक्षः संदिदेश महायशाः।
सुग्रीवः कथ्यतां वत्स ममागमनमित्युत॥', 'so ''ṅgadaṃ roṣatāmrākṣaḥ saṃdideśa mahāyaśāḥ
sugrīvaḥ kathyatāṃ vatsa mamāgamanam ity uta', null, 4030032),
('ramayana-4-30-33', 33, 'Kishkindha Kanda, Sarga 30, Verse 33', 'एष रामानुजः प्राप्तस्त्वत्सकाशमरिंदमः।
भ्रातुर्व्यसनसंतप्तो द्वारि तिष्ठति लक्ष्मणः॥', 'eṣa rāmānujaḥ prāptas tvatsakāśam ariṃdamaḥ
bhrātur vyasanasaṃtapto dvāri tiṣṭhati lakṣmaṇaḥ', null, 4030033),
('ramayana-4-30-34', 34, 'Kishkindha Kanda, Sarga 30, Verse 34', 'लक्ष्मणस्य वचः श्रुत्वा शोकाविष्टोऽङ्गदोऽब्रवीत्।
पितुः समीपमागम्य सौमित्रिरयमागतः॥', 'lakṣmaṇasya vacaḥ śrutvā śokāviṣṭo ''ṅgado ''bravīt
pituḥ samīpam āgamya saumitrir ayam āgataḥ', null, 4030034),
('ramayana-4-30-35', 35, 'Kishkindha Kanda, Sarga 30, Verse 35', 'ते महौघनिभं दृष्ट्वा वज्राशनिसमस्वनम्।
सिंहनादं समं चक्रुर्लक्ष्मणस्य समीपतः॥', 'te mahaughanibhaṃ dṛṣṭvā vajrāśanisamasvanam
siṃhanādaṃ samaṃ cakrur lakṣmaṇasya samīpataḥ', null, 4030035),
('ramayana-4-30-36', 36, 'Kishkindha Kanda, Sarga 30, Verse 36', 'तेन शब्देन महता प्रत्यबुध्यत वानरः।
मदविह्वलताम्राक्षो व्याकुलस्रग्विभूषणः॥', 'tena śabdena mahatā pratyabudhyata vānaraḥ
madavihvalatāmrākṣo vyākulasragvibhūṣaṇaḥ', null, 4030036),
('ramayana-4-30-37', 37, 'Kishkindha Kanda, Sarga 30, Verse 37', 'अथाङ्गदवचः श्रुत्वा तेनैव च समागतौ।
मन्त्रिणो वानरेन्द्रस्य संमतोदारदर्शिनौ॥', 'athāṅgadavacaḥ śrutvā tenaiva ca samāgatau
mantriṇo vānarendrasya saṃmatodāradarśinau', null, 4030037),
('ramayana-4-30-38', 38, 'Kishkindha Kanda, Sarga 30, Verse 38', 'प्लक्षश्चैव प्रभावश्च मन्त्रिणावर्थधर्मयोः।
वक्तुमुच्चावचं प्राप्तं लक्ष्मणं तौ शशंसतुः॥', 'plakṣaś caiva prabhāvaś ca mantriṇāv arthadharmayoḥ
vaktum uccāvacaṃ prāptaṃ lakṣmaṇaṃ tau śaśaṃsatuḥ', null, 4030038),
('ramayana-4-30-39', 39, 'Kishkindha Kanda, Sarga 30, Verse 39', 'प्रसादयित्वा सुग्रीवं वचनैः सामनिश्चितैः।
आसीनं पर्युपासीनौ यथा शक्रं मरुत्पतिम्॥', 'prasādayitvā sugrīvaṃ vacanaiḥ sāmaniścitaiḥ
āsīnaṃ paryupāsīnau yathā śakraṃ marutpatim', null, 4030039),
('ramayana-4-30-40', 40, 'Kishkindha Kanda, Sarga 30, Verse 40', 'सत्यसंधौ महाभागौ भ्रातरौ रामलक्ष्मणौ।
वयस्य भावं संप्राप्तौ राज्यार्हौ राज्यदायिनौ॥', 'satyasaṃdhau mahābhāgau bhrātarau rāmalakṣmaṇau
vayasya bhāvaṃ saṃprāptau rājyārhau rājyadāyinau', null, 4030040),
('ramayana-4-30-41', 41, 'Kishkindha Kanda, Sarga 30, Verse 41', 'तयोरेको धनुष्पाणिर्द्वारि तिष्ठति लक्ष्मणः।
यस्य भीताः प्रवेपन्ते नादान्मुञ्चन्ति वानराः॥', 'tayor eko dhanuṣpāṇir dvāri tiṣṭhati lakṣmaṇaḥ
yasya bhītāḥ pravepante nādān muñcanti vānarāḥ', null, 4030041),
('ramayana-4-30-42', 42, 'Kishkindha Kanda, Sarga 30, Verse 42', 'स एष राघवभ्राता लक्ष्मणो वाक्यसारथिः।
व्यवसाय रथः प्राप्तस्तस्य रामस्य शासनात्॥', 'sa eṣa rāghavabhrātā lakṣmaṇo vākyasārathiḥ
vyavasāya rathaḥ prāptas tasya rāmasya śāsanāt', null, 4030042),
('ramayana-4-30-43', 43, 'Kishkindha Kanda, Sarga 30, Verse 43', 'तस्य मूर्ध्ना प्रणम्य त्वं सपुत्रः सह बन्धुभिः।
राजंस्तिष्ठ स्वसमये भव सत्यप्रतिश्रवः॥', 'tasya mūrdhnā praṇamya tvaṃ saputraḥ saha bandhubhiḥ
rājaṃs tiṣṭha svasamaye bhava satyapratiśravaḥ', null, 4030043)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 31 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-31-1', 1, 'Kishkindha Kanda, Sarga 31, Verse 1', 'अङ्गदस्य वचः श्रुत्वा सुग्रीवः सचिवैः सह।
लक्ष्मणं कुपितं श्रुत्वा मुमोचासनमात्मवान्॥', 'aṅgadasya vacaḥ śrutvā sugrīvaḥ sacivaiḥ saha
lakṣmaṇaṃ kupitaṃ śrutvā mumocāsanam ātmavān', null, 4031001),
('ramayana-4-31-2', 2, 'Kishkindha Kanda, Sarga 31, Verse 2', 'सचिवानब्रवीद्वाक्यं निश्चित्य गुरुलाघवम्।
मन्त्रज्ञान्मन्त्रकुशलो मन्त्रेषु परिनिष्ठितः॥', 'sacivān abravīd vākyaṃ niścitya gurulāghavam
mantrajñān mantrakuśalo mantreṣu pariniṣṭhitaḥ', null, 4031002),
('ramayana-4-31-3', 3, 'Kishkindha Kanda, Sarga 31, Verse 3', 'न मे दुर्व्याहृतं किं चिन्नापि मे दुरनुष्ठितम्।
लक्ष्मणो राघवभ्राता क्रुद्धः किमिति चिन्तये॥', 'na me durvyāhṛtaṃ kiṃ cin nāpi me duranuṣṭhitam
lakṣmaṇo rāghavabhrātā kruddhaḥ kim iti cintaye', null, 4031003),
('ramayana-4-31-4', 4, 'Kishkindha Kanda, Sarga 31, Verse 4', 'असुहृद्भिर्ममामित्रैर्नित्यमन्तरदर्शिभिः।
मम दोषानसंभूताञ्श्रावितो राघवानुजः॥', 'asuhṛdbhir mamāmitrair nityam antaradarśibhiḥ
mama doṣān asaṃbhūtāñ śrāvito rāghavānujaḥ', null, 4031004),
('ramayana-4-31-5', 5, 'Kishkindha Kanda, Sarga 31, Verse 5', 'अत्र तावद्यथाबुद्धि सर्वैरेव यथाविधि।
भवद्भिर्निश्चयस्तस्य विज्ञेयो निपुणं शनैः॥', 'atra tāvad yathābuddhi sarvair eva yathāvidhi
bhavadbhir niścayas tasya vijñeyo nipuṇaṃ śanaiḥ', null, 4031005),
('ramayana-4-31-6', 6, 'Kishkindha Kanda, Sarga 31, Verse 6', 'न खल्वस्ति मम त्रासो लक्ष्मणान्नापि राघवात्।
मित्रं त्वस्थान कुपितं जनयत्येव संभ्रमम्॥', 'na khalv asti mama trāso lakṣmaṇān nāpi rāghavāt
mitraṃ tv asthāna kupitaṃ janayaty eva saṃbhramam', null, 4031006),
('ramayana-4-31-7', 7, 'Kishkindha Kanda, Sarga 31, Verse 7', 'सर्वथा सुकरं मित्रं दुष्करं परिपालनम्।
अनित्यत्वात्तु चित्तानां प्रीतिरल्पेऽपि भिद्यते॥', 'sarvathā sukaraṃ mitraṃ duṣkaraṃ paripālanam
anityatvāt tu cittānāṃ prītir alpe ''pi bhidyate', null, 4031007),
('ramayana-4-31-8', 8, 'Kishkindha Kanda, Sarga 31, Verse 8', 'अतोनिमित्तं त्रस्तोऽहं रामेण तु महात्मना।
यन्ममोपकृतं शक्यं प्रतिकर्तुं न तन्मया॥', 'atonimittaṃ trasto ''haṃ rāmeṇa tu mahātmanā
yan mamopakṛtaṃ śakyaṃ pratikartuṃ na tan mayā', null, 4031008),
('ramayana-4-31-9', 9, 'Kishkindha Kanda, Sarga 31, Verse 9', 'सुग्रीवेणैवमुक्तस्तु हनुमान्हरिपुंगवः।
उवाच स्वेन तर्केण मध्ये वानरमन्त्रिणाम्॥', 'sugrīveṇaivam uktas tu hanumān haripuṃgavaḥ
uvāca svena tarkeṇa madhye vānaramantriṇām', null, 4031009),
('ramayana-4-31-10', 10, 'Kishkindha Kanda, Sarga 31, Verse 10', 'सर्वथा नैतदाश्चर्यं यत्त्वं हरिगणेश्वर।
न विस्मरसि सुस्निग्धमुपकारकृतं शुभम्॥', 'sarvathā naitad āścaryaṃ yat tvaṃ harigaṇeśvara
na vismarasi susnigdham upakārakṛtaṃ śubham', null, 4031010),
('ramayana-4-31-11', 11, 'Kishkindha Kanda, Sarga 31, Verse 11', 'राघवेण तु शूरेण भयमुत्सृज्य दूरतः।
त्वत्प्रियार्थं हतो वाली शक्रतुल्यपराक्रमः॥', 'rāghaveṇa tu śūreṇa bhayam utsṛjya dūrataḥ
tvatpriyārthaṃ hato vālī śakratulyaparākramaḥ', null, 4031011),
('ramayana-4-31-12', 12, 'Kishkindha Kanda, Sarga 31, Verse 12', 'सर्वथा प्रणयात्क्रुद्धो राघवो नात्र संशयः।
भ्रातरं स प्रहितवांल्लक्ष्मणं लक्ष्मिवर्धनम्॥', 'sarvathā praṇayāt kruddho rāghavo nātra saṃśayaḥ
bhrātaraṃ sa prahitavāṃl lakṣmaṇaṃ lakṣmivardhanam', null, 4031012),
('ramayana-4-31-13', 13, 'Kishkindha Kanda, Sarga 31, Verse 13', 'त्वं प्रमत्तो न जानीषे कालं कलविदां वर।
फुल्लसप्तच्छदश्यामा प्रवृत्ता तु शरच्छिवा॥', 'tvaṃ pramatto na jānīṣe kālaṃ kalavidāṃ vara
phullasaptacchadaśyāmā pravṛttā tu śarac chivā', null, 4031013),
('ramayana-4-31-14', 14, 'Kishkindha Kanda, Sarga 31, Verse 14', 'निर्मल ग्रहनक्षत्रा द्यौः प्रनष्टबलाहका।
प्रसन्नाश्च दिशः सर्वाः सरितश्च सरांसि च॥', 'nirmala grahanakṣatrā dyauḥ pranaṣṭabalāhakā
prasannāś ca diśaḥ sarvāḥ saritaś ca sarāṃsi ca', null, 4031014),
('ramayana-4-31-15', 15, 'Kishkindha Kanda, Sarga 31, Verse 15', 'प्राप्तमुद्योगकालं तु नावैषि हरिपुंगव।
त्वं प्रमत्त इति व्यक्तं लक्ष्मणोऽयमिहागतः॥', 'prāptam udyogakālaṃ tu nāvaiṣi haripuṃgava
tvaṃ pramatta iti vyaktaṃ lakṣmaṇo ''yam ihāgataḥ', null, 4031015),
('ramayana-4-31-16', 16, 'Kishkindha Kanda, Sarga 31, Verse 16', 'आर्तस्य हृतदारस्य परुषं पुरुषान्तरात्।
वचनं मर्षणीयं ते राघवस्य महात्मनः॥', 'ārtasya hṛtadārasya paruṣaṃ puruṣāntarāt
vacanaṃ marṣaṇīyaṃ te rāghavasya mahātmanaḥ', null, 4031016),
('ramayana-4-31-17', 17, 'Kishkindha Kanda, Sarga 31, Verse 17', 'कृतापराधस्य हि ते नान्यत्पश्याम्यहं क्षमम्।
अन्तरेणाञ्जलिं बद्ध्वा लक्ष्मणस्य प्रसादनात्॥', 'kṛtāparādhasya hi te nānyat paśyāmy ahaṃ kṣamam
antareṇāñjaliṃ baddhvā lakṣmaṇasya prasādanāt', null, 4031017),
('ramayana-4-31-18', 18, 'Kishkindha Kanda, Sarga 31, Verse 18', 'नियुक्तैर्मन्त्रिभिर्वाच्यो अवश्यं पार्थिवो हितम्।
अत एव भयं त्यक्त्वा ब्रवीम्यवधृतं वचः॥', 'niyuktair mantribhir vācyo avaśyaṃ pārthivo hitam
ata eva bhayaṃ tyaktvā bravīmy avadhṛtaṃ vacaḥ', null, 4031018),
('ramayana-4-31-19', 19, 'Kishkindha Kanda, Sarga 31, Verse 19', 'अभिक्रुद्धः समर्थो हि चापमुद्यम्य राघवः।
सदेवासुरगन्धर्वं वशे स्थापयितुं जगत्॥', 'abhikruddhaḥ samartho hi cāpam udyamya rāghavaḥ
sadevāsuragandharvaṃ vaśe sthāpayituṃ jagat', null, 4031019),
('ramayana-4-31-20', 20, 'Kishkindha Kanda, Sarga 31, Verse 20', 'न स क्षमः कोपयितुं यः प्रसाद्य पुनर्भवेत्।
पूर्वोपकारं स्मरता कृतज्ञेन विशेषतः॥', 'na sa kṣamaḥ kopayituṃ yaḥ prasādya punar bhavet
pūrvopakāraṃ smaratā kṛtajñena viśeṣataḥ', null, 4031020),
('ramayana-4-31-21', 21, 'Kishkindha Kanda, Sarga 31, Verse 21', 'तस्य मूर्ध्ना प्रणम्य त्वं सपुत्रः ससुहृज्जनः।
राजंस्तिष्ठ स्वसमये भर्तुर्भार्येव तद्वशे॥', 'tasya mūrdhnā praṇamya tvaṃ saputraḥ sasuhṛjjanaḥ
rājaṃs tiṣṭha svasamaye bhartur bhāryeva tadvaśe', null, 4031021),
('ramayana-4-31-22', 22, 'Kishkindha Kanda, Sarga 31, Verse 22', 'न रामरामानुजशासनं त्वया कपीन्द्रयुक्तं मनसाप्यपोहितुम्।
मनो हि ते ज्ञास्यति मानुषं बलं सराघवस्यास्य सुरेन्द्रवर्चसः॥', 'na rāmarāmānujaśāsanaṃ tvayā kapīndrayuktaṃ manasāpy apohitum
mano hi te jñāsyati mānuṣaṃ balaṃ sarāghavasyāsya surendravarcasaḥ', null, 4031022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 32 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-32-1', 1, 'Kishkindha Kanda, Sarga 32, Verse 1', 'अथ प्रतिसमादिष्टो लक्ष्मणः परवीरहा।
प्रविवेश गुहां घोरां किष्किन्धां रामशासनात्॥', 'atha pratisamādiṣṭo lakṣmaṇaḥ paravīrahā
praviveśa guhāṃ ghorāṃ kiṣkindhāṃ rāmaśāsanāt', null, 4032001),
('ramayana-4-32-2', 2, 'Kishkindha Kanda, Sarga 32, Verse 2', 'द्वारस्था हरयस्तत्र महाकाया महाबलाः।
बभूवुर्लक्ष्मणं दृष्ट्वा सर्वे प्राञ्जलयः स्थिताः॥', 'dvārasthā harayas tatra mahākāyā mahābalāḥ
babhūvur lakṣmaṇaṃ dṛṣṭvā sarve prāñjalayaḥ sthitāḥ', null, 4032002),
('ramayana-4-32-3', 3, 'Kishkindha Kanda, Sarga 32, Verse 3', 'निःश्वसन्तं तु तं दृष्ट्वा क्रुद्धं दशरथात्मजम्।
बभूवुर्हरयस्त्रस्ता न चैनं पर्यवारयन्॥', 'niḥśvasantaṃ tu taṃ dṛṣṭvā kruddhaṃ daśarathātmajam
babhūvur harayas trastā na cainaṃ paryavārayan', null, 4032003),
('ramayana-4-32-4', 4, 'Kishkindha Kanda, Sarga 32, Verse 4', 'स तं रत्नमयीं श्रीमान्दिव्यां पुष्पितकाननाम्।
रम्यां रत्नसमाकीर्णां ददर्श महतीं गुहाम्॥', 'sa taṃ ratnamayīṃ śrīmān divyāṃ puṣpitakānanām
ramyāṃ ratnasamākīrṇāṃ dadarśa mahatīṃ guhām', null, 4032004),
('ramayana-4-32-5', 5, 'Kishkindha Kanda, Sarga 32, Verse 5', 'हर्म्यप्रासादसंबाधां नानापण्योपशोभिताम्।
सर्वकामफलैर्वृक्षैः पुष्पितैरुपशोभिताम्॥', 'harmyaprāsādasaṃbādhāṃ nānāpaṇyopaśobhitām
sarvakāmaphalair vṛkṣaiḥ puṣpitair upaśobhitām', null, 4032005),
('ramayana-4-32-6', 6, 'Kishkindha Kanda, Sarga 32, Verse 6', 'देवगन्धर्वपुत्रैश्च वानरैः कामरूपिभिः।
दिव्य माल्याम्बरधारैः शोभितां प्रियदर्शनैः॥', 'devagandharvaputraiś ca vānaraiḥ kāmarūpibhiḥ
divya mālyāmbaradhāraiḥ śobhitāṃ priyadarśanaiḥ', null, 4032006),
('ramayana-4-32-7', 7, 'Kishkindha Kanda, Sarga 32, Verse 7', 'चन्दनागरुपद्मानां गन्धैः सुरभिगन्धिनाम्।
मैरेयाणां मधूनां च संमोदितमहापथाम्॥', 'candanāgarupadmānāṃ gandhaiḥ surabhigandhinām
maireyāṇāṃ madhūnāṃ ca saṃmoditamahāpathām', null, 4032007),
('ramayana-4-32-8', 8, 'Kishkindha Kanda, Sarga 32, Verse 8', 'विन्ध्यमेरुगिरिप्रस्थैः प्रासादैर्नैकभूमिभिः।
ददर्श गिरिनद्यश्च विमलास्तत्र राघवः॥', 'vindhyamerugiriprasthaiḥ prāsādair naikabhūmibhiḥ
dadarśa girinadyaś ca vimalās tatra rāghavaḥ', null, 4032008),
('ramayana-4-32-9', 9, 'Kishkindha Kanda, Sarga 32, Verse 9', 'अङ्गदस्य गृहं रम्यं मैन्दस्य द्विविदस्य च।
गवयस्य गवाक्षस्य गजस्य शरभस्य च॥', 'aṅgadasya gṛhaṃ ramyaṃ maindasya dvividasya ca
gavayasya gavākṣasya gajasya śarabhasya ca', null, 4032009),
('ramayana-4-32-10', 10, 'Kishkindha Kanda, Sarga 32, Verse 10', 'विद्युन्मालेश्च संपातेः सूर्याक्षस्य हनूमतः।
वीरबाहोः सुबाहोश्च नलस्य च महात्मनः॥', 'vidyunmāleś ca saṃpāteḥ sūryākṣasya hanūmataḥ
vīrabāhoḥ subāhoś ca nalasya ca mahātmanaḥ', null, 4032010),
('ramayana-4-32-11', 11, 'Kishkindha Kanda, Sarga 32, Verse 11', 'कुमुदस्य सुषेणस्य तारजाम्बवतोस्तथा।
दधिवक्त्रस्य नीलस्य सुपाटलसुनेत्रयोः॥', 'kumudasya suṣeṇasya tārajāmbavatos tathā
dadhivaktrasya nīlasya supāṭalasunetrayoḥ', null, 4032011),
('ramayana-4-32-12', 12, 'Kishkindha Kanda, Sarga 32, Verse 12', 'एतेषां कपिमुख्यानां राजमार्गे महात्मनाम्।
ददर्श गृहमुख्यानि महासाराणि लक्ष्मणः॥', 'eteṣāṃ kapimukhyānāṃ rājamārge mahātmanām
dadarśa gṛhamukhyāni mahāsārāṇi lakṣmaṇaḥ', null, 4032012),
('ramayana-4-32-13', 13, 'Kishkindha Kanda, Sarga 32, Verse 13', 'पाण्डुराभ्रप्रकाशानि दिव्यमाल्ययुतानि च।
प्रभूतधनधान्यानि स्त्रीरत्नैः शोभितानि च॥', 'pāṇḍurābhraprakāśāni divyamālyayutāni ca
prabhūtadhanadhānyāni strīratnaiḥ śobhitāni ca', null, 4032013),
('ramayana-4-32-14', 14, 'Kishkindha Kanda, Sarga 32, Verse 14', 'पाण्डुरेण तु शैलेन परिक्षिप्तं दुरासदम्।
वानरेन्द्रगृहं रम्यं महेन्द्रसदनोपमम्॥', 'pāṇḍureṇa tu śailena parikṣiptaṃ durāsadam
vānarendragṛhaṃ ramyaṃ mahendrasadanopamam', null, 4032014),
('ramayana-4-32-15', 15, 'Kishkindha Kanda, Sarga 32, Verse 15', 'शुल्कैः प्रासादशिखरैः कैलासशिखरोपमैः।
सर्वकामफलैर्वृक्षैः पुष्टितैरुपशोभितम्॥', 'śulkaiḥ prāsādaśikharaiḥ kailāsaśikharopamaiḥ
sarvakāmaphalair vṛkṣaiḥ puṣṭitair upaśobhitam', null, 4032015),
('ramayana-4-32-16', 16, 'Kishkindha Kanda, Sarga 32, Verse 16', 'महेन्द्रदत्तैः श्रीमद्भिर्नीलजीमूतसंनिभैः।
दिव्यपुष्पफलैर्वृक्षैः शीतच्छायैर्मनोरमैः॥', 'mahendradattaiḥ śrīmadbhir nīlajīmūtasaṃnibhaiḥ
divyapuṣpaphalair vṛkṣaiḥ śītacchāyair manoramaiḥ', null, 4032016),
('ramayana-4-32-17', 17, 'Kishkindha Kanda, Sarga 32, Verse 17', 'हरिभिः संवृतद्वारं बलिभिः शस्त्रपाणिभिः।
दिव्यमाल्यावृतं शुभ्रं तप्तकाञ्चनतोरणम्॥', 'haribhiḥ saṃvṛtadvāraṃ balibhiḥ śastrapāṇibhiḥ
divyamālyāvṛtaṃ śubhraṃ taptakāñcanatoraṇam', null, 4032017),
('ramayana-4-32-18', 18, 'Kishkindha Kanda, Sarga 32, Verse 18', 'सुग्रीवस्य गृहं रम्यं प्रविवेश महाबलः।
अवार्यमाणः सौमित्रिर्महाभ्रमिव भास्करः॥', 'sugrīvasya gṛhaṃ ramyaṃ praviveśa mahābalaḥ
avāryamāṇaḥ saumitrir mahābhram iva bhāskaraḥ', null, 4032018),
('ramayana-4-32-19', 19, 'Kishkindha Kanda, Sarga 32, Verse 19', 'स सप्त कक्ष्या धर्मात्मा यानासनसमावृताः।
प्रविश्य सुमहद्गुप्तं ददर्शान्तःपुरं महत्॥', 'sa sapta kakṣyā dharmātmā yānāsanasamāvṛtāḥ
praviśya sumahad guptaṃ dadarśāntaḥpuraṃ mahat', null, 4032019),
('ramayana-4-32-20', 20, 'Kishkindha Kanda, Sarga 32, Verse 20', 'हैमराजतपर्यङ्कैर्बहुभिश्च वरासनैः।
महार्हास्तरणोपेतैस्तत्र तत्रोपशोभितम्॥', 'haimarājataparyaṅkair bahubhiś ca varāsanaiḥ
mahārhāstaraṇopetais tatra tatropaśobhitam', null, 4032020),
('ramayana-4-32-21', 21, 'Kishkindha Kanda, Sarga 32, Verse 21', 'प्रविशन्नेव सततं शुश्राव मधुरस्वरम्।
तन्त्रीगीतसमाकीर्णं समगीतपदाक्षरम्॥', 'praviśann eva satataṃ śuśrāva madhurasvaram
tantrīgītasamākīrṇaṃ samagītapadākṣaram', null, 4032021),
('ramayana-4-32-22', 22, 'Kishkindha Kanda, Sarga 32, Verse 22', 'बह्वीश्च विविधाकारा रूपयौवनगर्विताः।
स्त्रियः सुग्रीवभवने ददर्श स महाबलः॥', 'bahvīś ca vividhākārā rūpayauvanagarvitāḥ
striyaḥ sugrīvabhavane dadarśa sa mahābalaḥ', null, 4032022),
('ramayana-4-32-23', 23, 'Kishkindha Kanda, Sarga 32, Verse 23', 'दृष्ट्वाभिजनसंपन्नाश्चित्रमाल्यकृतस्रजः।
वरमाल्यकृतव्यग्रा भूषणोत्तमभूषिताः॥', 'dṛṣṭvābhijanasaṃpannāś citramālyakṛtasrajaḥ
varamālyakṛtavyagrā bhūṣaṇottamabhūṣitāḥ', null, 4032023),
('ramayana-4-32-24', 24, 'Kishkindha Kanda, Sarga 32, Verse 24', 'नातृप्तान्नाति च व्यग्रान्नानुदात्तपरिच्छदान्।
सुग्रीवानुचरांश्चापि लक्षयामास लक्ष्मणः॥', 'nātṛptān nāti ca vyagrān nānudāttaparicchadān
sugrīvānucarāṃś cāpi lakṣayām āsa lakṣmaṇaḥ', null, 4032024),
('ramayana-4-32-25', 25, 'Kishkindha Kanda, Sarga 32, Verse 25', 'ततः सुग्रीवमासीनं काञ्चने परमासने।
महार्हास्तरणोपेते ददर्शादित्यसंनिभम्॥', 'tataḥ sugrīvam āsīnaṃ kāñcane paramāsane
mahārhāstaraṇopete dadarśādityasaṃnibham', null, 4032025),
('ramayana-4-32-26', 26, 'Kishkindha Kanda, Sarga 32, Verse 26', 'दिव्याभरणचित्राङ्गं दिव्यरूपं यशस्विनम्।
दिव्यमाल्याम्बरधरं महेन्द्रमिव दुर्जयम्।
दिव्याभरणमाल्याभिः प्रमदाभिः समावृतम्॥', 'divyābharaṇacitrāṅgaṃ divyarūpaṃ yaśasvinam
divyamālyāmbaradharaṃ mahendram iva durjayam
divyābharaṇamālyābhiḥ pramadābhiḥ samāvṛtam', null, 4032026),
('ramayana-4-32-27', 27, 'Kishkindha Kanda, Sarga 32, Verse 27', 'रुमां तु वीरः परिरभ्य गाढं वरासनस्थो वरहेमवर्णः।
ददर्श सौमित्रिमदीनसत्त्वं विशालनेत्रः सुविशालनेत्रम्॥', 'rumāṃ tu vīraḥ parirabhya gāḍhaṃ varāsanastho varahemavarṇaḥ
dadarśa saumitrim adīnasattvaṃ viśālanetraḥ suviśālanetram', null, 4032027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 33 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-33-1', 1, 'Kishkindha Kanda, Sarga 33, Verse 1', 'तमप्रतिहतं क्रुद्धं प्रविष्टं पुरुषर्षभम्।
सुग्रीवो लक्ष्मणं दृष्ट्वा बभूव व्यथितेन्द्रियः॥', 'tam apratihataṃ kruddhaṃ praviṣṭaṃ puruṣarṣabham
sugrīvo lakṣmaṇaṃ dṛṣṭvā babhūva vyathitendriyaḥ', null, 4033001),
('ramayana-4-33-2', 2, 'Kishkindha Kanda, Sarga 33, Verse 2', 'क्रुद्धं निःश्वसमानं तं प्रदीप्तमिव तेजसा।
भ्रातुर्व्यसनसंतप्तं दृष्ट्वा दशरथात्मजम्॥', 'kruddhaṃ niḥśvasamānaṃ taṃ pradīptam iva tejasā
bhrātur vyasanasaṃtaptaṃ dṛṣṭvā daśarathātmajam', null, 4033002),
('ramayana-4-33-3', 3, 'Kishkindha Kanda, Sarga 33, Verse 3', 'उत्पपात हरिश्रेष्ठो हित्वा सौवर्णमासनम्।
महान्महेन्द्रस्य यथा स्वलंकृत इव ध्वजः॥', 'utpapāta hariśreṣṭho hitvā sauvarṇam āsanam
mahān mahendrasya yathā svalaṃkṛta iva dhvajaḥ', null, 4033003),
('ramayana-4-33-4', 4, 'Kishkindha Kanda, Sarga 33, Verse 4', 'उत्पतन्तमनूत्पेतू रुमाप्रभृतयः स्त्रियः।
सुग्रीवं गगने पूर्णं चन्द्रं तारागणा इव॥', 'utpatantam anūtpetū rumāprabhṛtayaḥ striyaḥ
sugrīvaṃ gagane pūrṇaṃ candraṃ tārāgaṇā iva', null, 4033004),
('ramayana-4-33-5', 5, 'Kishkindha Kanda, Sarga 33, Verse 5', 'संरक्तनयनः श्रीमान्विचचाल कृताञ्जलिः।
बभूवावस्थितस्तत्र कल्पवृक्षो महानिव॥', 'saṃraktanayanaḥ śrīmān vicacāla kṛtāñjaliḥ
babhūvāvasthitas tatra kalpavṛkṣo mahān iva', null, 4033005),
('ramayana-4-33-6', 6, 'Kishkindha Kanda, Sarga 33, Verse 6', 'रुमा द्वितीयं सुग्रीवं नारीमध्यगतं स्थितम्।
अब्रवील्लक्ष्मणः क्रुद्धः सतारं शशिनं यथा॥', 'rumā dvitīyaṃ sugrīvaṃ nārīmadhyagataṃ sthitam
abravīl lakṣmaṇaḥ kruddhaḥ satāraṃ śaśinaṃ yathā', null, 4033006),
('ramayana-4-33-7', 7, 'Kishkindha Kanda, Sarga 33, Verse 7', 'सत्त्वाभिजनसंपन्नः सानुक्रोशो जितेन्द्रियः।
कृतज्ञः सत्यवादी च राजा लोके महीयते॥', 'sattvābhijanasaṃpannaḥ sānukrośo jitendriyaḥ
kṛtajñaḥ satyavādī ca rājā loke mahīyate', null, 4033007),
('ramayana-4-33-8', 8, 'Kishkindha Kanda, Sarga 33, Verse 8', 'यस्तु राजा स्थितोऽधर्मे मित्राणामुपकारिणाम्।
मिथ्याप्रतिज्ञां कुरुते को नृशंसतरस्ततः॥', 'yas tu rājā sthito ''dharme mitrāṇām upakāriṇām
mithyāpratijñāṃ kurute ko nṛśaṃsataras tataḥ', null, 4033008),
('ramayana-4-33-9', 9, 'Kishkindha Kanda, Sarga 33, Verse 9', 'शतमश्वानृते हन्ति सहस्रं तु गवानृते।
आत्मानं स्वजनं हन्ति पुरुषः पुरुषानृते॥', 'śatam aśvānṛte hanti sahasraṃ tu gavānṛte
ātmānaṃ svajanaṃ hanti puruṣaḥ puruṣānṛte', null, 4033009),
('ramayana-4-33-10', 10, 'Kishkindha Kanda, Sarga 33, Verse 10', 'पूर्वं कृतार्थो मित्राणां न तत्प्रतिकरोति यः।
कृतघ्नः सर्वभूतानां स वध्यः प्लवगेश्वर॥', 'pūrvaṃ kṛtārtho mitrāṇāṃ na tat pratikaroti yaḥ
kṛtaghnaḥ sarvabhūtānāṃ sa vadhyaḥ plavageśvara', null, 4033010),
('ramayana-4-33-11', 11, 'Kishkindha Kanda, Sarga 33, Verse 11', 'गीतोऽयं ब्रह्मणा श्लोकः सर्वलोकनमस्कृतः।
दृष्ट्वा कृतघ्नं क्रुद्धेन तं निबोध प्लवंगम॥', 'gīto ''yaṃ brahmaṇā ślokaḥ sarvalokanamaskṛtaḥ
dṛṣṭvā kṛtaghnaṃ kruddhena taṃ nibodha plavaṃgama', null, 4033011),
('ramayana-4-33-12', 12, 'Kishkindha Kanda, Sarga 33, Verse 12', 'ब्रह्मघ्ने च सुरापे च चोरे भग्नव्रते तथा।
निष्कृतिर्विहिता सद्भिः कृतघ्ने नास्ति निष्कृतिः॥', 'brahmaghne ca surāpe ca core bhagnavrate tathā
niṣkṛtir vihitā sadbhiḥ kṛtaghne nāsti niṣkṛtiḥ', null, 4033012),
('ramayana-4-33-13', 13, 'Kishkindha Kanda, Sarga 33, Verse 13', 'अनार्यस्त्वं कृतघ्नश्च मिथ्यावादी च वानर।
पूर्वं कृतार्थो रामस्य न तत्प्रतिकरोषि यत्॥', 'anāryas tvaṃ kṛtaghnaś ca mithyāvādī ca vānara
pūrvaṃ kṛtārtho rāmasya na tat pratikaroṣi yat', null, 4033013),
('ramayana-4-33-14', 14, 'Kishkindha Kanda, Sarga 33, Verse 14', 'ननु नाम कृतार्थेन त्वया रामस्य वानर।
सीताया मार्गणे यत्नः कर्तव्यः कृतमिच्छता॥', 'nanu nāma kṛtārthena tvayā rāmasya vānara
sītāyā mārgaṇe yatnaḥ kartavyaḥ kṛtam icchatā', null, 4033014),
('ramayana-4-33-15', 15, 'Kishkindha Kanda, Sarga 33, Verse 15', 'स त्वं ग्राम्येषु भोगेषु सक्तो मिथ्या प्रतिश्रवः।
न त्वां रामो विजानीते सर्पं मण्डूकराविणम्॥', 'sa tvaṃ grāmyeṣu bhogeṣu sakto mithyā pratiśravaḥ
na tvāṃ rāmo vijānīte sarpaṃ maṇḍūkarāviṇam', null, 4033015),
('ramayana-4-33-16', 16, 'Kishkindha Kanda, Sarga 33, Verse 16', 'महाभागेन रामेण पापः करुणवेदिना।
हरीणां प्रापितो राज्यं त्वं दुरात्मा महात्मना॥', 'mahābhāgena rāmeṇa pāpaḥ karuṇavedinā
harīṇāṃ prāpito rājyaṃ tvaṃ durātmā mahātmanā', null, 4033016),
('ramayana-4-33-17', 17, 'Kishkindha Kanda, Sarga 33, Verse 17', 'कृतं चेन्नाभिजानीषे रामस्याक्लिष्टकर्मणः।
सद्यस्त्वं निशितैर्बाणैर्हतो द्रक्ष्यसि वालिनम्॥', 'kṛtaṃ cen nābhijānīṣe rāmasyākliṣṭakarmaṇaḥ
sadyas tvaṃ niśitair bāṇair hato drakṣyasi vālinam', null, 4033017),
('ramayana-4-33-18', 18, 'Kishkindha Kanda, Sarga 33, Verse 18', 'न च संकुचितः पन्था येन वाली हतो गतः।
समये तिष्ठ सुग्रीव मा वालिपथमन्वगाः॥', 'na ca saṃkucitaḥ panthā yena vālī hato gataḥ
samaye tiṣṭha sugrīva mā vālipatham anvagāḥ', null, 4033018),
('ramayana-4-33-19', 19, 'Kishkindha Kanda, Sarga 33, Verse 19', 'न नूनमिक्ष्वाकुवरस्य कार्मुकाच्च्युताञ्शरान्पश्यसि वज्रसंनिभान्।
ततः सुखं नाम निषेवसे सुखी न रामकार्यं मनसाप्यवेक्षसे॥', 'na nūnam ikṣvākuvarasya kārmukāc cyutāñ śarān paśyasi vajrasaṃnibhān
tataḥ sukhaṃ nāma niṣevase sukhī na rāmakāryaṃ manasāpy avekṣase', null, 4033019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 34 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-34-1', 1, 'Kishkindha Kanda, Sarga 34, Verse 1', 'तथा ब्रुवाणं सौमित्रिं प्रदीप्तमिव तेजसा।
अब्रवील्लक्ष्मणं तारा ताराधिपनिभानना॥', 'tathā bruvāṇaṃ saumitriṃ pradīptam iva tejasā
abravīl lakṣmaṇaṃ tārā tārādhipanibhānanā', null, 4034001),
('ramayana-4-34-2', 2, 'Kishkindha Kanda, Sarga 34, Verse 2', 'नैवं लक्ष्मण वक्तव्यो नायं परुषमर्हति।
हरीणामीश्वरः श्रोतुं तव वक्त्राद्विशेषतः॥', 'naivaṃ lakṣmaṇa vaktavyo nāyaṃ paruṣam arhati
harīṇām īśvaraḥ śrotuṃ tava vaktrād viśeṣataḥ', null, 4034002),
('ramayana-4-34-3', 3, 'Kishkindha Kanda, Sarga 34, Verse 3', 'नैवाकृतज्ञः सुग्रीवो न शठो नापि दारुणः।
नैवानृतकथो वीर न जिह्मश्च कपीश्वरः॥', 'naivākṛtajñaḥ sugrīvo na śaṭho nāpi dāruṇaḥ
naivānṛtakatho vīra na jihmaś ca kapīśvaraḥ', null, 4034003),
('ramayana-4-34-4', 4, 'Kishkindha Kanda, Sarga 34, Verse 4', 'उपकारं कृतं वीरो नाप्ययं विस्मृतः कपिः।
रामेण वीर सुग्रीवो यदन्यैर्दुष्करं रणे॥', 'upakāraṃ kṛtaṃ vīro nāpy ayaṃ vismṛtaḥ kapiḥ
rāmeṇa vīra sugrīvo yad anyair duṣkaraṃ raṇe', null, 4034004),
('ramayana-4-34-5', 5, 'Kishkindha Kanda, Sarga 34, Verse 5', 'रामप्रसादात्कीर्तिं च कपिराज्यं च शाश्वतम्।
प्राप्तवानिह सुग्रीवो रुमां मां च परंतप॥', 'rāmaprasādāt kīrtiṃ ca kapirājyaṃ ca śāśvatam
prāptavān iha sugrīvo rumāṃ māṃ ca paraṃtapa', null, 4034005),
('ramayana-4-34-6', 6, 'Kishkindha Kanda, Sarga 34, Verse 6', 'सुदुःखं शायितः पूर्वं प्राप्येदं सुखमुत्तमम्।
प्राप्तकालं न जानीते विश्वामित्रो यथा मुनिः॥', 'suduḥkhaṃ śāyitaḥ pūrvaṃ prāpyedaṃ sukham uttamam
prāptakālaṃ na jānīte viśvāmitro yathā muniḥ', null, 4034006),
('ramayana-4-34-7', 7, 'Kishkindha Kanda, Sarga 34, Verse 7', 'घृताच्यां किल संसक्तो दशवर्षाणि लक्ष्मण।
अहोऽमन्यत धर्मात्मा विश्वामित्रो महामुनिः॥', 'ghṛtācyāṃ kila saṃsakto daśavarṣāṇi lakṣmaṇa
aho ''manyata dharmātmā viśvāmitro mahāmuniḥ', null, 4034007),
('ramayana-4-34-8', 8, 'Kishkindha Kanda, Sarga 34, Verse 8', 'स हि प्राप्तं न जानीते कालं कालविदां वरः।
विश्वामित्रो महातेजाः किं पुनर्यः पृथग्जनः॥', 'sa hi prāptaṃ na jānīte kālaṃ kālavidāṃ varaḥ
viśvāmitro mahātejāḥ kiṃ punar yaḥ pṛthagjanaḥ', null, 4034008),
('ramayana-4-34-9', 9, 'Kishkindha Kanda, Sarga 34, Verse 9', 'देहधर्मं गतस्यास्य परिश्रान्तस्य लक्ष्मण।
अवितृप्तस्य कामेषु रामः क्षन्तुमिहार्हति॥', 'dehadharmaṃ gatasyāsya pariśrāntasya lakṣmaṇa
avitṛptasya kāmeṣu rāmaḥ kṣantum ihārhati', null, 4034009),
('ramayana-4-34-10', 10, 'Kishkindha Kanda, Sarga 34, Verse 10', 'न च रोषवशं तात गन्तुमर्हसि लक्ष्मण।
निश्चयार्थमविज्ञाय सहसा प्राकृतो यथा॥', 'na ca roṣavaśaṃ tāta gantum arhasi lakṣmaṇa
niścayārtham avijñāya sahasā prākṛto yathā', null, 4034010),
('ramayana-4-34-11', 11, 'Kishkindha Kanda, Sarga 34, Verse 11', 'सत्त्वयुक्ता हि पुरुषास्त्वद्विधाः पुरुषर्षभ।
अविमृश्य न रोषस्य सहसा यान्ति वश्यताम्॥', 'sattvayuktā hi puruṣās tvadvidhāḥ puruṣarṣabha
avimṛśya na roṣasya sahasā yānti vaśyatām', null, 4034011),
('ramayana-4-34-12', 12, 'Kishkindha Kanda, Sarga 34, Verse 12', 'प्रसादये त्वां धर्मज्ञ सुग्रीवार्थे समाहिता।
महान्रोषसमुत्पन्नः संरम्भस्त्यज्यतामयम्॥', 'prasādaye tvāṃ dharmajña sugrīvārthe samāhitā
mahān roṣasamutpannaḥ saṃrambhas tyajyatām ayam', null, 4034012),
('ramayana-4-34-13', 13, 'Kishkindha Kanda, Sarga 34, Verse 13', 'रुमां मां कपिराज्यं च धनधान्यवसूनि च।
रामप्रियार्थं सुग्रीवस्त्यजेदिति मतिर्मम॥', 'rumāṃ māṃ kapirājyaṃ ca dhanadhānyavasūni ca
rāmapriyārthaṃ sugrīvas tyajed iti matir mama', null, 4034013),
('ramayana-4-34-14', 14, 'Kishkindha Kanda, Sarga 34, Verse 14', 'समानेष्व्यति सुग्रीवः सीतया सह राघवम्।
शशाङ्कमिव रोहिष्या निहत्वा रावणं रणे॥', 'samāneṣvyati sugrīvaḥ sītayā saha rāghavam
śaśāṅkam iva rohiṣyā nihatvā rāvaṇaṃ raṇe', null, 4034014),
('ramayana-4-34-15', 15, 'Kishkindha Kanda, Sarga 34, Verse 15', 'शतकोटिसहस्राणि लङ्कायां किल रक्षसाम्।
अयुतानि च षट्त्रिंशत्सहस्राणि शतानि च॥', 'śatakoṭisahasrāṇi laṅkāyāṃ kila rakṣasām
ayutāni ca ṣaṭtriṃśat sahasrāṇi śatāni ca', null, 4034015),
('ramayana-4-34-16', 16, 'Kishkindha Kanda, Sarga 34, Verse 16', 'अहत्वा तांश्च दुर्धर्षान्राक्षसान्कामरूपिणः।
न शक्यो रावणो हन्तुं येन सा मैथिली हृता॥', 'ahatvā tāṃś ca durdharṣān rākṣasān kāmarūpiṇaḥ
na śakyo rāvaṇo hantuṃ yena sā maithilī hṛtā', null, 4034016),
('ramayana-4-34-17', 17, 'Kishkindha Kanda, Sarga 34, Verse 17', 'ते न शक्या रणे हन्तुमसहायेन लक्ष्मण।
रावणः क्रूरकर्मा च सुग्रीवेण विशेषतः॥', 'te na śakyā raṇe hantum asahāyena lakṣmaṇa
rāvaṇaḥ krūrakarmā ca sugrīveṇa viśeṣataḥ', null, 4034017),
('ramayana-4-34-18', 18, 'Kishkindha Kanda, Sarga 34, Verse 18', 'एवमाख्यातवान्वाली स ह्यभिज्ञो हरीश्वरः।
आगमस्तु न मे व्यक्तः श्रवात्तस्य ब्रवीम्यहम्॥', 'evam ākhyātavān vālī sa hy abhijño harīśvaraḥ
āgamas tu na me vyaktaḥ śravāt tasya bravīmy aham', null, 4034018),
('ramayana-4-34-19', 19, 'Kishkindha Kanda, Sarga 34, Verse 19', 'त्वत्सहायनिमित्तं वै प्रेषिता हरिपुंगवाः।
आनेतुं वानरान्युद्धे सुबहून्हरियूथपान्॥', 'tvatsahāyanimittaṃ vai preṣitā haripuṃgavāḥ
ānetuṃ vānarān yuddhe subahūn hariyūthapān', null, 4034019),
('ramayana-4-34-20', 20, 'Kishkindha Kanda, Sarga 34, Verse 20', 'तांश्च प्रतीक्षमाणोऽयं विक्रान्तान्सुमहाबलान्।
राघवस्यार्थसिद्ध्यर्थं न निर्याति हरीश्वरः॥', 'tāṃś ca pratīkṣamāṇo ''yaṃ vikrāntān sumahābalān
rāghavasyārthasiddhyarthaṃ na niryāti harīśvaraḥ', null, 4034020),
('ramayana-4-34-21', 21, 'Kishkindha Kanda, Sarga 34, Verse 21', 'कृता तु संस्था सौमित्रे सुग्रीवेण यथापुरा।
अद्य तैर्वानरैर्सर्वैरागन्तव्यं महाबलैः॥', 'kṛtā tu saṃsthā saumitre sugrīveṇa yathāpurā
adya tair vānarair sarvair āgantavyaṃ mahābalaiḥ', null, 4034021),
('ramayana-4-34-22', 22, 'Kishkindha Kanda, Sarga 34, Verse 22', 'ऋक्षकोटिसहस्राणि गोलाङ्गूलशतानि च।
अद्य त्वामुपयास्यन्ति जहि कोपमरिंदम।
कोट्योऽनेकास्तु काकुत्स्थ कपीनां दीप्ततेजसाम्॥', 'ṛkṣakoṭisahasrāṇi golāṅgūlaśatāni ca
adya tvām upayāsyanti jahi kopam ariṃdama
koṭyo ''nekās tu kākutstha kapīnāṃ dīptatejasām', null, 4034022),
('ramayana-4-34-23', 23, 'Kishkindha Kanda, Sarga 34, Verse 23', 'तव हि मुखमिदं निरीक्ष्य कोपात्क्षतजनिभे नयने निरीक्षमाणाः।
हरिवरवनिता न यान्ति शान्तिं प्रथमभयस्य हि शङ्किताः स्म सर्वाः॥', 'tava hi mukham idaṃ nirīkṣya kopāt kṣatajanibhe nayane nirīkṣamāṇāḥ
harivaravanitā na yānti śāntiṃ prathamabhayasya hi śaṅkitāḥ sma sarvāḥ', null, 4034023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 35 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-35-1', 1, 'Kishkindha Kanda, Sarga 35, Verse 1', 'इत्युक्तस्तारया वाक्यं प्रश्रितं धर्मसंहितम्।
मृदुस्वभावः सौमित्रिः प्रतिजग्राह तद्वचः॥', 'ity uktas tārayā vākyaṃ praśritaṃ dharmasaṃhitam
mṛdusvabhāvaḥ saumitriḥ pratijagrāha tad vacaḥ', null, 4035001),
('ramayana-4-35-2', 2, 'Kishkindha Kanda, Sarga 35, Verse 2', 'तस्मिन्प्रतिगृहीते तु वाक्ये हरिगणेश्वरः।
लक्ष्मणात्सुमहत्त्रासं वस्त्रं क्लिन्नमिवात्यजत्॥', 'tasmin pratigṛhīte tu vākye harigaṇeśvaraḥ
lakṣmaṇāt sumahat trāsaṃ vastraṃ klinnam ivātyajat', null, 4035002),
('ramayana-4-35-3', 3, 'Kishkindha Kanda, Sarga 35, Verse 3', 'ततः कण्ठगतं माल्यं चित्रं बहुगुणं महत्।
चिच्छेद विमदश्चासीत्सुग्रीवो वानरेश्वरः॥', 'tataḥ kaṇṭhagataṃ mālyaṃ citraṃ bahuguṇaṃ mahat
ciccheda vimadaś cāsīt sugrīvo vānareśvaraḥ', null, 4035003),
('ramayana-4-35-4', 4, 'Kishkindha Kanda, Sarga 35, Verse 4', 'स लक्ष्मणं भीमबलं सर्ववानरसत्तमः।
अब्रवीत्प्रश्रितं वाक्यं सुग्रीवः संप्रहर्षयन्॥', 'sa lakṣmaṇaṃ bhīmabalaṃ sarvavānarasattamaḥ
abravīt praśritaṃ vākyaṃ sugrīvaḥ saṃpraharṣayan', null, 4035004),
('ramayana-4-35-5', 5, 'Kishkindha Kanda, Sarga 35, Verse 5', 'प्रनष्टा श्रीश्च कीर्तिश्च कपिराज्यं च शाश्वतम्।
रामप्रसादात्सौमित्रे पुनः प्राप्तमिदं मया॥', 'pranaṣṭā śrīś ca kīrtiś ca kapirājyaṃ ca śāśvatam
rāmaprasādāt saumitre punaḥ prāptam idaṃ mayā', null, 4035005),
('ramayana-4-35-6', 6, 'Kishkindha Kanda, Sarga 35, Verse 6', 'कः शक्तस्तस्य देवस्य ख्यातस्य स्वेन कर्मणा।
तादृशं विक्रमं वीर प्रतिकर्तुमरिंदम॥', 'kaḥ śaktas tasya devasya khyātasya svena karmaṇā
tādṛśaṃ vikramaṃ vīra pratikartum ariṃdama', null, 4035006),
('ramayana-4-35-7', 7, 'Kishkindha Kanda, Sarga 35, Verse 7', 'सीतां प्राप्स्यति धर्मात्मा वधिष्यति च रावणम्।
सहायमात्रेण मया राघवः स्वेन तेजसा॥', 'sītāṃ prāpsyati dharmātmā vadhiṣyati ca rāvaṇam
sahāyamātreṇa mayā rāghavaḥ svena tejasā', null, 4035007),
('ramayana-4-35-8', 8, 'Kishkindha Kanda, Sarga 35, Verse 8', 'सहायकृत्यं हि तस्य येन सप्त महाद्रुमाः।
शैलश्च वसुधा चैव बाणेनैकेन दारिताः॥', 'sahāyakṛtyaṃ hi tasya yena sapta mahādrumāḥ
śailaś ca vasudhā caiva bāṇenaikena dāritāḥ', null, 4035008),
('ramayana-4-35-9', 9, 'Kishkindha Kanda, Sarga 35, Verse 9', 'धनुर्विस्फारमाणस्य यस्य शब्देन लक्ष्मण।
सशैला कम्पिता भूमिः सहायैस्तस्य किं नु वै॥', 'dhanur visphāramāṇasya yasya śabdena lakṣmaṇa
saśailā kampitā bhūmiḥ sahāyais tasya kiṃ nu vai', null, 4035009),
('ramayana-4-35-10', 10, 'Kishkindha Kanda, Sarga 35, Verse 10', 'अनुयात्रां नरेन्द्रस्य करिष्येऽहं नरर्षभ।
गच्छतो रावणं हन्तुं वैरिणं सपुरःसरम्॥', 'anuyātrāṃ narendrasya kariṣye ''haṃ nararṣabha
gacchato rāvaṇaṃ hantuṃ vairiṇaṃ sapuraḥsaram', null, 4035010),
('ramayana-4-35-11', 11, 'Kishkindha Kanda, Sarga 35, Verse 11', 'यदि किं चिदतिक्रान्तं विश्वासात्प्रणयेन वा।
प्रेष्यस्य क्षमितव्यं मे न कश्चिन्नापराध्यति॥', 'yadi kiṃ cid atikrāntaṃ viśvāsāt praṇayena vā
preṣyasya kṣamitavyaṃ me na kaś cin nāparādhyati', null, 4035011),
('ramayana-4-35-12', 12, 'Kishkindha Kanda, Sarga 35, Verse 12', 'इति तस्य ब्रुवाणस्य सुग्रीवस्य महात्मनः।
अभवल्लक्ष्मणः प्रीतः प्रेंणा चेदमुवाच ह॥', 'iti tasya bruvāṇasya sugrīvasya mahātmanaḥ
abhaval lakṣmaṇaḥ prītaḥ preṃṇā cedam uvāca ha', null, 4035012),
('ramayana-4-35-13', 13, 'Kishkindha Kanda, Sarga 35, Verse 13', 'सर्वथा हि मम भ्राता सनाथो वानरेश्वर।
त्वया नाथेन सुग्रीव प्रश्रितेन विशेषतः॥', 'sarvathā hi mama bhrātā sanātho vānareśvara
tvayā nāthena sugrīva praśritena viśeṣataḥ', null, 4035013),
('ramayana-4-35-14', 14, 'Kishkindha Kanda, Sarga 35, Verse 14', 'यस्ते प्रभावः सुग्रीव यच्च ते शौचमुत्तमम्।
अर्हस्तं कपिराज्यस्य श्रियं भोक्तुमनुत्तमाम्॥', 'yas te prabhāvaḥ sugrīva yac ca te śaucam uttamam
arhas taṃ kapirājyasya śriyaṃ bhoktum anuttamām', null, 4035014),
('ramayana-4-35-15', 15, 'Kishkindha Kanda, Sarga 35, Verse 15', 'सहायेन च सुग्रीव त्वया रामः प्रतापवान्।
वधिष्यति रणे शत्रूनचिरान्नात्र संशयः॥', 'sahāyena ca sugrīva tvayā rāmaḥ pratāpavān
vadhiṣyati raṇe śatrūn acirān nātra saṃśayaḥ', null, 4035015),
('ramayana-4-35-16', 16, 'Kishkindha Kanda, Sarga 35, Verse 16', 'धर्मज्ञस्य कृतज्ञस्य संग्रामेष्वनिवर्तिनः।
उपपन्नं च युक्तं च सुग्रीव तव भाषितम्॥', 'dharmajñasya kṛtajñasya saṃgrāmeṣv anivartinaḥ
upapannaṃ ca yuktaṃ ca sugrīva tava bhāṣitam', null, 4035016),
('ramayana-4-35-17', 17, 'Kishkindha Kanda, Sarga 35, Verse 17', 'दोषज्ञः सति सामर्थ्ये कोऽन्यो भाषितुमर्हति।
वर्जयित्वा मम ज्येष्ठं त्वां च वानरसत्तम॥', 'doṣajñaḥ sati sāmarthye ko ''nyo bhāṣitum arhati
varjayitvā mama jyeṣṭhaṃ tvāṃ ca vānarasattama', null, 4035017),
('ramayana-4-35-18', 18, 'Kishkindha Kanda, Sarga 35, Verse 18', 'सदृशश्चासि रामस्य विक्रमेण बलेन च।
सहायो दैवतैर्दत्तश्चिराय हरिपुंगव॥', 'sadṛśaś cāsi rāmasya vikrameṇa balena ca
sahāyo daivatair dattaś cirāya haripuṃgava', null, 4035018),
('ramayana-4-35-19', 19, 'Kishkindha Kanda, Sarga 35, Verse 19', 'किं तु शीघ्रमितो वीर निष्क्राम त्वं मया सह।
सान्त्वयस्व वयस्यं च भार्याहरणदुःखितम्॥', 'kiṃ tu śīghram ito vīra niṣkrāma tvaṃ mayā saha
sāntvayasva vayasyaṃ ca bhāryāharaṇaduḥkhitam', null, 4035019),
('ramayana-4-35-20', 20, 'Kishkindha Kanda, Sarga 35, Verse 20', 'यच्च शोकाभिभूतस्य श्रुत्वा रामस्य भाषितम्।
मया त्वं परुषाण्युक्तस्तच्च त्वं क्षन्तुमर्हसि॥', 'yac ca śokābhibhūtasya śrutvā rāmasya bhāṣitam
mayā tvaṃ paruṣāṇy uktas tac ca tvaṃ kṣantum arhasi', null, 4035020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 36 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-36-1', 1, 'Kishkindha Kanda, Sarga 36, Verse 1', 'एवमुक्तस्तु सुग्रीवो लक्ष्मणेन महात्मना।
हनुमन्तं स्थितं पार्श्वे सचिवं वाक्यमब्रवीत्॥', 'evam uktas tu sugrīvo lakṣmaṇena mahātmanā
hanumantaṃ sthitaṃ pārśve sacivaṃ vākyam abravīt', null, 4036001),
('ramayana-4-36-2', 2, 'Kishkindha Kanda, Sarga 36, Verse 2', 'महेन्द्रहिमवद्विन्ध्यकैलासशिखरेषु च।
मन्दरे पाण्डुशिखरे पञ्चशैलेषु ये स्थिताः॥', 'mahendrahimavadvindhyakailāsaśikhareṣu ca
mandare pāṇḍuśikhare pañcaśaileṣu ye sthitāḥ', null, 4036002),
('ramayana-4-36-3', 3, 'Kishkindha Kanda, Sarga 36, Verse 3', 'तरुणादित्यवर्णेषु भ्राजमानेषु सर्वशः।
पर्वतेषु समुद्रान्ते पश्चिमस्यां तु ये दिशि॥', 'taruṇādityavarṇeṣu bhrājamāneṣu sarvaśaḥ
parvateṣu samudrānte paścimasyāṃ tu ye diśi', null, 4036003),
('ramayana-4-36-4', 4, 'Kishkindha Kanda, Sarga 36, Verse 4', 'आदित्यभवने चैव गिरौ संध्याभ्रसंनिभे।
पद्मतालवनं भीमं संश्रिता हरिपुंगवाः॥', 'ādityabhavane caiva girau saṃdhyābhrasaṃnibhe
padmatālavanaṃ bhīmaṃ saṃśritā haripuṃgavāḥ', null, 4036004),
('ramayana-4-36-5', 5, 'Kishkindha Kanda, Sarga 36, Verse 5', 'अञ्जनाम्बुदसंकाशाः कुञ्जरप्रतिमौजसः।
अञ्जने परते चैव ये वसन्ति प्लवंगमाः॥', 'añjanāmbudasaṃkāśāḥ kuñjarapratimaujasaḥ
añjane parate caiva ye vasanti plavaṃgamāḥ', null, 4036005),
('ramayana-4-36-6', 6, 'Kishkindha Kanda, Sarga 36, Verse 6', 'मनःशिला गुहावासा वानराः कनकप्रभाः।
मेरुपार्श्वगताश्चैव ये च धूम्रगिरिं श्रिताः॥', 'manaḥśilā guhāvāsā vānarāḥ kanakaprabhāḥ
merupārśvagatāś caiva ye ca dhūmragiriṃ śritāḥ', null, 4036006),
('ramayana-4-36-7', 7, 'Kishkindha Kanda, Sarga 36, Verse 7', 'तरुणादित्यवर्णाश्च पर्वते ये महारुणे।
पिबन्तो मधुमैरेयं भीमवेगाः प्लवंगमाः॥', 'taruṇādityavarṇāś ca parvate ye mahāruṇe
pibanto madhumaireyaṃ bhīmavegāḥ plavaṃgamāḥ', null, 4036007),
('ramayana-4-36-8', 8, 'Kishkindha Kanda, Sarga 36, Verse 8', 'वनेषु च सुरम्येषु सुगन्धिषु महत्सु च।
तापसानां च रम्येषु वनान्तेषु समन्ततः॥', 'vaneṣu ca suramyeṣu sugandhiṣu mahatsu ca
tāpasānāṃ ca ramyeṣu vanānteṣu samantataḥ', null, 4036008),
('ramayana-4-36-9', 9, 'Kishkindha Kanda, Sarga 36, Verse 9', 'तांस्तांस्त्वमानय क्षिप्रं पृथिव्यां सर्ववानरान्।
सामदानादिभिः कल्पैराशु प्रेषय वानरान्॥', 'tāṃs tāṃs tvam ānaya kṣipraṃ pṛthivyāṃ sarvavānarān
sāmadānādibhiḥ kalpair āśu preṣaya vānarān', null, 4036009),
('ramayana-4-36-10', 10, 'Kishkindha Kanda, Sarga 36, Verse 10', 'प्रेषिताः प्रथमं ये च मया दूता महाजवाः।
त्वरणार्थं तु भूयस्त्वं हरीन्संप्रेषयापरान्॥', 'preṣitāḥ prathamaṃ ye ca mayā dūtā mahājavāḥ
tvaraṇārthaṃ tu bhūyas tvaṃ harīn saṃpreṣayāparān', null, 4036010),
('ramayana-4-36-11', 11, 'Kishkindha Kanda, Sarga 36, Verse 11', 'ये प्रसक्ताश्च कामेषु दीर्घसूत्राश्च वानराः।
इहानयस्व तान्सर्वाञ्शीघ्रं तु मम शासनात्॥', 'ye prasaktāś ca kāmeṣu dīrghasūtrāś ca vānarāḥ
ihānayasva tān sarvāñ śīghraṃ tu mama śāsanāt', null, 4036011),
('ramayana-4-36-12', 12, 'Kishkindha Kanda, Sarga 36, Verse 12', 'अहोभिर्दशभिर्ये च नागच्छन्ति ममाज्ञया।
हन्तव्यास्ते दुरात्मानो राजशासनदूषकाः॥', 'ahobhir daśabhir ye ca nāgacchanti mamājñayā
hantavyās te durātmāno rājaśāsanadūṣakāḥ', null, 4036012),
('ramayana-4-36-13', 13, 'Kishkindha Kanda, Sarga 36, Verse 13', 'शतान्यथ सहस्राणि कोट्यश्च मम शासनात्।
प्रयान्तु कपिसिंहानां दिशो मम मते स्थिताः॥', 'śatāny atha sahasrāṇi koṭyaś ca mama śāsanāt
prayāntu kapisiṃhānāṃ diśo mama mate sthitāḥ', null, 4036013),
('ramayana-4-36-14', 14, 'Kishkindha Kanda, Sarga 36, Verse 14', 'मेघपर्वतसंकाशाश्छादयन्त इवाम्बरम्।
घोररूपाः कपिश्रेष्ठा यान्तु मच्छासनादितः॥', 'meghaparvatasaṃkāśāś chādayanta ivāmbaram
ghorarūpāḥ kapiśreṣṭhā yāntu macchāsanād itaḥ', null, 4036014),
('ramayana-4-36-15', 15, 'Kishkindha Kanda, Sarga 36, Verse 15', 'ते गतिज्ञा गतिं गत्वा पृथिव्यां सर्ववानराः।
आनयन्तु हरीन्सर्वांस्त्वरिताः शासनान्मम॥', 'te gatijñā gatiṃ gatvā pṛthivyāṃ sarvavānarāḥ
ānayantu harīn sarvāṃs tvaritāḥ śāsanān mama', null, 4036015),
('ramayana-4-36-16', 16, 'Kishkindha Kanda, Sarga 36, Verse 16', 'तस्य वानरराजस्य श्रुत्वा वायुसुतो वचः।
दिक्षु सर्वासु विक्रान्तान्प्रेषयामास वानरान्॥', 'tasya vānararājasya śrutvā vāyusuto vacaḥ
dikṣu sarvāsu vikrāntān preṣayām āsa vānarān', null, 4036016),
('ramayana-4-36-17', 17, 'Kishkindha Kanda, Sarga 36, Verse 17', 'ते पदं विष्णुविक्रान्तं पतत्रिज्योतिरध्वगाः।
प्रयाताः प्रहिता राज्ञा हरयस्तत्क्षणेन वै॥', 'te padaṃ viṣṇuvikrāntaṃ patatrijyotiradhvagāḥ
prayātāḥ prahitā rājñā harayas tatkṣaṇena vai', null, 4036017),
('ramayana-4-36-18', 18, 'Kishkindha Kanda, Sarga 36, Verse 18', 'ते समुद्रेषु गिरिषु वनेषु च सरित्सु च।
वानरा वानरान्सर्वान्रामहेतोरचोदयन्॥', 'te samudreṣu giriṣu vaneṣu ca saritsu ca
vānarā vānarān sarvān rāmahetor acodayan', null, 4036018),
('ramayana-4-36-19', 19, 'Kishkindha Kanda, Sarga 36, Verse 19', 'मृत्युकालोपमस्याज्ञां राजराजस्य वानराः।
सुग्रीवस्याययुः श्रुत्वा सुग्रीवभयदर्शिनः॥', 'mṛtyukālopamasyājñāṃ rājarājasya vānarāḥ
sugrīvasyāyayuḥ śrutvā sugrīvabhayadarśinaḥ', null, 4036019),
('ramayana-4-36-20', 20, 'Kishkindha Kanda, Sarga 36, Verse 20', 'ततस्तेऽञ्जनसंकाशा गिरेस्तस्मान्महाजवाः।
तिस्रः कोट्यः प्लवंगानां निर्ययुर्यत्र राघवः॥', 'tatas te ''ñjanasaṃkāśā gires tasmān mahājavāḥ
tisraḥ koṭyaḥ plavaṃgānāṃ niryayur yatra rāghavaḥ', null, 4036020),
('ramayana-4-36-21', 21, 'Kishkindha Kanda, Sarga 36, Verse 21', 'अस्तं गच्छति यत्रार्कस्तस्मिन्गिरिवरे रताः।
तप्तहेमसमाभासास्तस्मात्कोट्यो दशच्युताः॥', 'astaṃ gacchati yatrārkas tasmin girivare ratāḥ
taptahemasamābhāsās tasmāt koṭyo daśacyutāḥ', null, 4036021),
('ramayana-4-36-22', 22, 'Kishkindha Kanda, Sarga 36, Verse 22', 'कैलास शिखरेभ्यश्च सिंहकेसरवर्चसाम्।
ततः कोटिसहस्राणि वानराणामुपागमन्॥', 'kailāsa śikharebhyaś ca siṃhakesaravarcasām
tataḥ koṭisahasrāṇi vānarāṇām upāgaman', null, 4036022),
('ramayana-4-36-23', 23, 'Kishkindha Kanda, Sarga 36, Verse 23', 'फलमूलेन जीवन्तो हिमवन्तमुपाश्रिताः।
तेषां कोटिसहस्राणां सहस्रं समवर्तत॥', 'phalamūlena jīvanto himavantam upāśritāḥ
teṣāṃ koṭisahasrāṇāṃ sahasraṃ samavartata', null, 4036023),
('ramayana-4-36-24', 24, 'Kishkindha Kanda, Sarga 36, Verse 24', 'अङ्गारक समानानां भीमानां भीमकर्मणाम्।
विन्ध्याद्वानरकोटीनां सहस्राण्यपतन्द्रुतम्॥', 'aṅgāraka samānānāṃ bhīmānāṃ bhīmakarmaṇām
vindhyād vānarakoṭīnāṃ sahasrāṇy apatan drutam', null, 4036024),
('ramayana-4-36-25', 25, 'Kishkindha Kanda, Sarga 36, Verse 25', 'क्षीरोदवेलानिलयास्तमालवनवासिनः।
नारिकेलाशनाश्चैव तेषां संख्या न विद्यते॥', 'kṣīrodavelānilayās tamālavanavāsinaḥ
nārikelāśanāś caiva teṣāṃ saṃkhyā na vidyate', null, 4036025),
('ramayana-4-36-26', 26, 'Kishkindha Kanda, Sarga 36, Verse 26', 'वनेभ्यो गह्वरेभ्यश्च सरिद्भ्यश्च महाजवाः।
आगच्छद्वानरी सेना पिबन्तीव दिवाकरम्॥', 'vanebhyo gahvarebhyaś ca saridbhyaś ca mahājavāḥ
āgacchad vānarī senā pibantīva divākaram', null, 4036026),
('ramayana-4-36-27', 27, 'Kishkindha Kanda, Sarga 36, Verse 27', 'ये तु त्वरयितुं याता वानराः सर्ववानरान्।
ते वीरा हिमवच्छैलं ददृशुस्तं महाद्रुमम्॥', 'ye tu tvarayituṃ yātā vānarāḥ sarvavānarān
te vīrā himavac chailaṃ dadṛśus taṃ mahādrumam', null, 4036027),
('ramayana-4-36-28', 28, 'Kishkindha Kanda, Sarga 36, Verse 28', 'तस्मिन्गिरिवरे रम्ये यज्ञो महेश्वरः पुरा।
सर्वदेवमनस्तोषो बभौ दिव्यो मनोहरः॥', 'tasmin girivare ramye yajño maheśvaraḥ purā
sarvadevamanastoṣo babhau divyo manoharaḥ', null, 4036028),
('ramayana-4-36-29', 29, 'Kishkindha Kanda, Sarga 36, Verse 29', 'अन्नविष्यन्दजातानि मूलानि च फलानि च।
अमृतस्वादुकल्पानि ददृशुस्तत्र वानराः॥', 'annaviṣyandajātāni mūlāni ca phalāni ca
amṛtasvādukalpāni dadṛśus tatra vānarāḥ', null, 4036029),
('ramayana-4-36-30', 30, 'Kishkindha Kanda, Sarga 36, Verse 30', 'तदन्न संभवं दिव्यं फलं मूलं मनोहरम्।
यः कश्चित्सकृदश्नाति मासं भवति तर्पितः॥', 'tad anna saṃbhavaṃ divyaṃ phalaṃ mūlaṃ manoharam
yaḥ kaś cit sakṛd aśnāti māsaṃ bhavati tarpitaḥ', null, 4036030),
('ramayana-4-36-31', 31, 'Kishkindha Kanda, Sarga 36, Verse 31', 'तानि मूलानि दिव्यानि फलानि च फलाशनाः।
औषधानि च दिव्यानि जगृहुर्हरियूथपाः॥', 'tāni mūlāni divyāni phalāni ca phalāśanāḥ
auṣadhāni ca divyāni jagṛhur hariyūthapāḥ', null, 4036031),
('ramayana-4-36-32', 32, 'Kishkindha Kanda, Sarga 36, Verse 32', 'तस्माच्च यज्ञायतनात्पुष्पाणि सुरभीणि च।
आनिन्युर्वानरा गत्वा सुग्रीवप्रियकारणात्॥', 'tasmāc ca yajñāyatanāt puṣpāṇi surabhīṇi ca
āninyur vānarā gatvā sugrīvapriyakāraṇāt', null, 4036032),
('ramayana-4-36-33', 33, 'Kishkindha Kanda, Sarga 36, Verse 33', 'ते तु सर्वे हरिवराः पृथिव्यां सर्ववानरान्।
संचोदयित्वा त्वरितं यूथानां जग्मुरग्रतः॥', 'te tu sarve harivarāḥ pṛthivyāṃ sarvavānarān
saṃcodayitvā tvaritaṃ yūthānāṃ jagmur agrataḥ', null, 4036033),
('ramayana-4-36-34', 34, 'Kishkindha Kanda, Sarga 36, Verse 34', 'ते तु तेन मुहूर्तेन यूथपाः शीघ्रकारिणः।
किष्किन्धां त्वरया प्राप्ताः सुग्रीवो यत्र वानरः॥', 'te tu tena muhūrtena yūthapāḥ śīghrakāriṇaḥ
kiṣkindhāṃ tvarayā prāptāḥ sugrīvo yatra vānaraḥ', null, 4036034),
('ramayana-4-36-35', 35, 'Kishkindha Kanda, Sarga 36, Verse 35', 'ते गृहीत्वौषधीः सर्वाः फलं मूलं च वानराः।
तं प्रतिग्राहयामासुर्वचनं चेदमब्रुवन्॥', 'te gṛhītvauṣadhīḥ sarvāḥ phalaṃ mūlaṃ ca vānarāḥ
taṃ pratigrāhayām āsur vacanaṃ cedam abruvan', null, 4036035),
('ramayana-4-36-36', 36, 'Kishkindha Kanda, Sarga 36, Verse 36', 'सर्वे परिगताः शैलाः समुद्राश्च वनानि च।
पृथिव्यां वानराः सर्वे शासनादुपयान्ति ते॥', 'sarve parigatāḥ śailāḥ samudrāś ca vanāni ca
pṛthivyāṃ vānarāḥ sarve śāsanād upayānti te', null, 4036036),
('ramayana-4-36-37', 37, 'Kishkindha Kanda, Sarga 36, Verse 37', 'एवं श्रुत्वा ततो हृष्टः सुग्रीवः प्लवगाधिपः।
प्रतिजग्राह च प्रीतस्तेषां सर्वमुपायनम्॥', 'evaṃ śrutvā tato hṛṣṭaḥ sugrīvaḥ plavagādhipaḥ
pratijagrāha ca prītas teṣāṃ sarvam upāyanam', null, 4036037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 37 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-37-1', 1, 'Kishkindha Kanda, Sarga 37, Verse 1', 'प्रतिगृह्य च तत्सर्वमुपानयमुपाहृतम्।
वानरान्सान्त्वयित्वा च सर्वानेव व्यसर्जयत्॥', 'pratigṛhya ca tat sarvam upānayam upāhṛtam
vānarān sāntvayitvā ca sarvān eva vyasarjayat', null, 4037001),
('ramayana-4-37-2', 2, 'Kishkindha Kanda, Sarga 37, Verse 2', 'विसर्जयित्वा स हरीञ्शूरांस्तान्कृतकर्मणः।
मेने कृतार्थमात्मानं राघवं च महाबलम्॥', 'visarjayitvā sa harīñ śūrāṃs tān kṛtakarmaṇaḥ
mene kṛtārtham ātmānaṃ rāghavaṃ ca mahābalam', null, 4037002),
('ramayana-4-37-3', 3, 'Kishkindha Kanda, Sarga 37, Verse 3', 'स लक्ष्मणो भीमबलं सर्ववानरसत्तमम्।
अब्रवीत्प्रश्रितं वाक्यं सुग्रीवं संप्रहर्षयन्।
किष्किन्धाया विनिष्क्राम यदि ते सौम्य रोचते॥', 'sa lakṣmaṇo bhīmabalaṃ sarvavānarasattamam
abravīt praśritaṃ vākyaṃ sugrīvaṃ saṃpraharṣayan
kiṣkindhāyā viniṣkrāma yadi te saumya rocate', null, 4037003),
('ramayana-4-37-4', 4, 'Kishkindha Kanda, Sarga 37, Verse 4', 'तस्य तद्वचनं श्रुत्वा लक्ष्मणस्य सुभाषितम्।
सुग्रीवः परमप्रीतो वाक्यमेतदुवाच ह॥', 'tasya tad vacanaṃ śrutvā lakṣmaṇasya subhāṣitam
sugrīvaḥ paramaprīto vākyam etad uvāca ha', null, 4037004),
('ramayana-4-37-5', 5, 'Kishkindha Kanda, Sarga 37, Verse 5', 'एवं भवतु गच्छामः स्थेयं त्वच्छासने मया।
तमेवमुक्त्वा सुग्रीवो लक्ष्मणं शुभलक्ष्मणम्॥', 'evaṃ bhavatu gacchāmaḥ stheyaṃ tvacchāsane mayā
tam evam uktvā sugrīvo lakṣmaṇaṃ śubhalakṣmaṇam', null, 4037005),
('ramayana-4-37-6', 6, 'Kishkindha Kanda, Sarga 37, Verse 6', 'विसर्जयामास तदा तारामन्याश्च योषितः।
एतेत्युच्चैर्हरिवरान्सुग्रीवः समुदाहरत्॥', 'visarjayām āsa tadā tārām anyāś ca yoṣitaḥ
etety uccair harivarān sugrīvaḥ samudāharat', null, 4037006),
('ramayana-4-37-7', 7, 'Kishkindha Kanda, Sarga 37, Verse 7', 'तस्य तद्वचनं श्रुत्वा हरयः शीघ्रमाययुः।
बद्धाञ्जलिपुटाः सर्वे ये स्युः स्त्रीदर्शनक्षमाः॥', 'tasya tad vacanaṃ śrutvā harayaḥ śīghram āyayuḥ
baddhāñjalipuṭāḥ sarve ye syuḥ strīdarśanakṣamāḥ', null, 4037007),
('ramayana-4-37-8', 8, 'Kishkindha Kanda, Sarga 37, Verse 8', 'तानुवाच ततः प्राप्तान्राजार्कसदृशप्रभः।
उपस्थापयत क्षिप्रं शिबिकां मम वानराः॥', 'tān uvāca tataḥ prāptān rājārkasadṛśaprabhaḥ
upasthāpayata kṣipraṃ śibikāṃ mama vānarāḥ', null, 4037008),
('ramayana-4-37-9', 9, 'Kishkindha Kanda, Sarga 37, Verse 9', 'श्रुत्वा तु वचनं तस्य हरयः शीघ्रविक्रमाः।
समुपस्थापयामासुः शिबिकां प्रियदर्शनाम्॥', 'śrutvā tu vacanaṃ tasya harayaḥ śīghravikramāḥ
samupasthāpayām āsuḥ śibikāṃ priyadarśanām', null, 4037009),
('ramayana-4-37-10', 10, 'Kishkindha Kanda, Sarga 37, Verse 10', 'तामुपस्थापितां दृष्ट्वा शिबिकां वानराधिपः।
लक्ष्मणारुह्यतां शीघ्रमिति सौमित्रिमब्रवीत्॥', 'tām upasthāpitāṃ dṛṣṭvā śibikāṃ vānarādhipaḥ
lakṣmaṇāruhyatāṃ śīghram iti saumitrim abravīt', null, 4037010),
('ramayana-4-37-11', 11, 'Kishkindha Kanda, Sarga 37, Verse 11', 'इत्युक्त्वा काञ्चनं यानं सुग्रीवः सूर्यसंनिभम्।
बृहद्भिर्हरिभिर्युक्तमारुरोह सलक्ष्मणः॥', 'ity uktvā kāñcanaṃ yānaṃ sugrīvaḥ sūryasaṃnibham
bṛhadbhir haribhir yuktam āruroha salakṣmaṇaḥ', null, 4037011),
('ramayana-4-37-12', 12, 'Kishkindha Kanda, Sarga 37, Verse 12', 'पाण्डुरेणातपत्रेण ध्रियमाणेन मूर्धनि।
शुक्लैश्च बालव्यजनैर्धूयमानैः समन्ततः॥', 'pāṇḍureṇātapatreṇa dhriyamāṇena mūrdhani
śuklaiś ca bālavyajanair dhūyamānaiḥ samantataḥ', null, 4037012),
('ramayana-4-37-13', 13, 'Kishkindha Kanda, Sarga 37, Verse 13', 'शङ्खभेरीनिनादैश्च बन्दिभिश्चाभिवन्दितः।
निर्ययौ प्राप्य सुग्रीवो राज्यश्रियमनुत्तमाम्॥', 'śaṅkhabherīninādaiś ca bandibhiś cābhivanditaḥ
niryayau prāpya sugrīvo rājyaśriyam anuttamām', null, 4037013),
('ramayana-4-37-14', 14, 'Kishkindha Kanda, Sarga 37, Verse 14', 'स वानरशतैस्तीष्क्णैर्बहुभिः शस्त्रपाणिभिः।
परिकीर्णो ययौ तत्र यत्र रामो व्यवस्थितः॥', 'sa vānaraśatais tīṣkṇair bahubhiḥ śastrapāṇibhiḥ
parikīrṇo yayau tatra yatra rāmo vyavasthitaḥ', null, 4037014),
('ramayana-4-37-15', 15, 'Kishkindha Kanda, Sarga 37, Verse 15', 'स तं देशमनुप्राप्य श्रेष्ठं रामनिषेवितम्।
अवातरन्महातेजाः शिबिकायाः सलक्ष्मणः॥', 'sa taṃ deśam anuprāpya śreṣṭhaṃ rāmaniṣevitam
avātaran mahātejāḥ śibikāyāḥ salakṣmaṇaḥ', null, 4037015),
('ramayana-4-37-16', 16, 'Kishkindha Kanda, Sarga 37, Verse 16', 'आसाद्य च ततो रामं कृताञ्जलिपुटोऽभवत्।
कृताञ्जलौ स्थिते तस्मिन्वानराश्चभवंस्तथा॥', 'āsādya ca tato rāmaṃ kṛtāñjalipuṭo ''bhavat
kṛtāñjalau sthite tasmin vānarāś cabhavaṃs tathā', null, 4037016),
('ramayana-4-37-17', 17, 'Kishkindha Kanda, Sarga 37, Verse 17', 'तटाकमिव तद्दृष्ट्वा रामः कुड्मलपङ्कजम्।
वानराणां महत्सैन्यं सुग्रीवे प्रीतिमानभूत्॥', 'taṭākam iva tad dṛṣṭvā rāmaḥ kuḍmalapaṅkajam
vānarāṇāṃ mahat sainyaṃ sugrīve prītimān abhūt', null, 4037017),
('ramayana-4-37-18', 18, 'Kishkindha Kanda, Sarga 37, Verse 18', 'पादयोः पतितं मूर्ध्ना तमुत्थाप्य हरीश्वरम्।
प्रेंणा च बहुमानाच्च राघवः परिषस्वजे॥', 'pādayoḥ patitaṃ mūrdhnā tam utthāpya harīśvaram
preṃṇā ca bahumānāc ca rāghavaḥ pariṣasvaje', null, 4037018),
('ramayana-4-37-19', 19, 'Kishkindha Kanda, Sarga 37, Verse 19', 'परिष्वज्य च धर्मात्मा निषीदेति ततोऽब्रवीत्।
तं निषण्णं ततो दृष्ट्वा क्षितौ रामोऽब्रवीद्वचः॥', 'pariṣvajya ca dharmātmā niṣīdeti tato ''bravīt
taṃ niṣaṇṇaṃ tato dṛṣṭvā kṣitau rāmo ''bravīd vacaḥ', null, 4037019),
('ramayana-4-37-20', 20, 'Kishkindha Kanda, Sarga 37, Verse 20', 'धर्ममर्थं च कामं च काले यस्तु निषेवते।
विभज्य सततं वीर स राजा हरिसत्तम॥', 'dharmam arthaṃ ca kāmaṃ ca kāle yas tu niṣevate
vibhajya satataṃ vīra sa rājā harisattama', null, 4037020),
('ramayana-4-37-21', 21, 'Kishkindha Kanda, Sarga 37, Verse 21', 'हित्वा धर्मं तथार्थं च कामं यस्तु निषेवते।
स वृक्षाग्रे यथा सुप्तः पतितः प्रतिबुध्यते॥', 'hitvā dharmaṃ tathārthaṃ ca kāmaṃ yas tu niṣevate
sa vṛkṣāgre yathā suptaḥ patitaḥ pratibudhyate', null, 4037021),
('ramayana-4-37-22', 22, 'Kishkindha Kanda, Sarga 37, Verse 22', 'अमित्राणां वधे युक्तो मित्राणां संग्रहे रतः।
त्रिवर्गफलभोक्ता तु राजा धर्मेण युज्यते॥', 'amitrāṇāṃ vadhe yukto mitrāṇāṃ saṃgrahe rataḥ
trivargaphalabhoktā tu rājā dharmeṇa yujyate', null, 4037022),
('ramayana-4-37-23', 23, 'Kishkindha Kanda, Sarga 37, Verse 23', 'उद्योगसमयस्त्वेष प्राप्तः शत्रुविनाशन।
संचिन्त्यतां हि पिङ्गेश हरिभिः सह मन्त्रिभिः॥', 'udyogasamayas tv eṣa prāptaḥ śatruvināśana
saṃcintyatāṃ hi piṅgeśa haribhiḥ saha mantribhiḥ', null, 4037023),
('ramayana-4-37-24', 24, 'Kishkindha Kanda, Sarga 37, Verse 24', 'एवमुक्तस्तु सुग्रीवो रामं वचनमब्रवीत्॥', 'evam uktas tu sugrīvo rāmaṃ vacanam abravīt', null, 4037024),
('ramayana-4-37-25', 25, 'Kishkindha Kanda, Sarga 37, Verse 25', 'प्रनष्टा श्रीश्च कीर्तिश्च कपिराज्यं च शाश्वतम्।
त्वत्प्रसादान्महाबाहो पुनः प्राप्तमिदं मया॥', 'pranaṣṭā śrīś ca kīrtiś ca kapirājyaṃ ca śāśvatam
tvatprasādān mahābāho punaḥ prāptam idaṃ mayā', null, 4037025),
('ramayana-4-37-26', 26, 'Kishkindha Kanda, Sarga 37, Verse 26', 'तव देवप्रसदाच्च भ्रातुश्च जयतां वर।
कृतं न प्रतिकुर्याद्यः पुरुषाणां स दूषकः॥', 'tava devaprasadāc ca bhrātuś ca jayatāṃ vara
kṛtaṃ na pratikuryād yaḥ puruṣāṇāṃ sa dūṣakaḥ', null, 4037026),
('ramayana-4-37-27', 27, 'Kishkindha Kanda, Sarga 37, Verse 27', 'एते वानरमुख्याश्च शतशः शत्रुसूदन।
प्राप्ताश्चादाय बलिनः पृथिव्यां सर्ववानरान्॥', 'ete vānaramukhyāś ca śataśaḥ śatrusūdana
prāptāś cādāya balinaḥ pṛthivyāṃ sarvavānarān', null, 4037027),
('ramayana-4-37-28', 28, 'Kishkindha Kanda, Sarga 37, Verse 28', 'ऋक्षाश्चावहिताः शूरा गोलाङ्गूलाश्च राघव।
कान्तार वनदुर्गाणामभिज्ञा घोरदर्शनाः॥', 'ṛkṣāś cāvahitāḥ śūrā golāṅgūlāś ca rāghava
kāntāra vanadurgāṇām abhijñā ghoradarśanāḥ', null, 4037028),
('ramayana-4-37-29', 29, 'Kishkindha Kanda, Sarga 37, Verse 29', 'देवगन्धर्वपुत्राश्च वानराः कामरूपिणः।
स्वैः स्वैः परिवृताः सैन्यैर्वर्तन्ते पथि राघव॥', 'devagandharvaputrāś ca vānarāḥ kāmarūpiṇaḥ
svaiḥ svaiḥ parivṛtāḥ sainyair vartante pathi rāghava', null, 4037029),
('ramayana-4-37-30', 30, 'Kishkindha Kanda, Sarga 37, Verse 30', 'शतैः शतसहस्रैश्च कोटिभिश्च प्लवंगमाः।
अयुतैश्चावृता वीरा शङ्कुभिश्च परंतप॥', 'śataiḥ śatasahasraiś ca koṭibhiś ca plavaṃgamāḥ
ayutaiś cāvṛtā vīrā śaṅkubhiś ca paraṃtapa', null, 4037030),
('ramayana-4-37-31', 31, 'Kishkindha Kanda, Sarga 37, Verse 31', 'अर्बुदैरर्बुदशतैर्मध्यैश्चान्तैश्च वानराः।
समुद्रैश्च परार्धैश्च हरयो हरियूथपाः॥', 'arbudair arbudaśatair madhyaiś cāntaiś ca vānarāḥ
samudraiś ca parārdhaiś ca harayo hariyūthapāḥ', null, 4037031),
('ramayana-4-37-32', 32, 'Kishkindha Kanda, Sarga 37, Verse 32', 'आगमिष्यन्ति ते राजन्महेन्द्रसमविक्रमाः।
मेरुमन्दरसंकाशा विन्ध्यमेरुकृतालयाः॥', 'āgamiṣyanti te rājan mahendrasamavikramāḥ
merumandarasaṃkāśā vindhyamerukṛtālayāḥ', null, 4037032),
('ramayana-4-37-33', 33, 'Kishkindha Kanda, Sarga 37, Verse 33', 'ते त्वामभिगमिष्यन्ति राक्षसं ये सबान्धवम्।
निहत्य रावणं संख्ये ह्यानयिष्यन्ति मैथिलीम्॥', 'te tvām abhigamiṣyanti rākṣasaṃ ye sabāndhavam
nihatya rāvaṇaṃ saṃkhye hy ānayiṣyanti maithilīm', null, 4037033),
('ramayana-4-37-34', 34, 'Kishkindha Kanda, Sarga 37, Verse 34', 'ततस्तमुद्योगमवेक्ष्य बुद्धिमान्हरिप्रवीरस्य निदेशवर्तिनः।
बभूव हर्षाद्वसुधाधिपात्मजः प्रबुद्धनीलोत्पलतुल्यदर्शनः॥', 'tatas tam udyogam avekṣya buddhimān haripravīrasya nideśavartinaḥ
babhūva harṣād vasudhādhipātmajaḥ prabuddhanīlotpalatulyadarśanaḥ', null, 4037034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 38 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-38-1', 1, 'Kishkindha Kanda, Sarga 38, Verse 1', 'इति ब्रुवाणं सुग्रीवं रामो धर्मभृतां वरः।
बाहुभ्यां संपरिष्वज्य प्रत्युवाच कृताञ्जलिम्॥', 'iti bruvāṇaṃ sugrīvaṃ rāmo dharmabhṛtāṃ varaḥ
bāhubhyāṃ saṃpariṣvajya pratyuvāca kṛtāñjalim', null, 4038001),
('ramayana-4-38-2', 2, 'Kishkindha Kanda, Sarga 38, Verse 2', 'यदिन्द्रो वर्षते वर्षं न तच्चित्रं भवेद्भुवि।
आदित्यो वा सहस्रांशुः कुर्याद्वितिमिरं नभः॥', 'yad indro varṣate varṣaṃ na tac citraṃ bhaved bhuvi
ādityo vā sahasrāṃśuḥ kuryād vitimiraṃ nabhaḥ', null, 4038002),
('ramayana-4-38-3', 3, 'Kishkindha Kanda, Sarga 38, Verse 3', 'चन्द्रमा रश्मिभिः कुर्यात्पृथिवीं सौम्य निर्मलाम्।
त्वद्विधो वापि मित्राणां प्रतिकुर्यात्परंतप॥', 'candramā raśmibhiḥ kuryāt pṛthivīṃ saumya nirmalām
tvadvidho vāpi mitrāṇāṃ pratikuryāt paraṃtapa', null, 4038003),
('ramayana-4-38-4', 4, 'Kishkindha Kanda, Sarga 38, Verse 4', 'एवं त्वयि न तच्चित्रं भवेद्यत्सौम्य शोभनम्।
जानाम्यहं त्वां सुग्रीव सततं प्रियवादिनम्॥', 'evaṃ tvayi na tac citraṃ bhaved yat saumya śobhanam
jānāmy ahaṃ tvāṃ sugrīva satataṃ priyavādinam', null, 4038004),
('ramayana-4-38-5', 5, 'Kishkindha Kanda, Sarga 38, Verse 5', 'त्वत्सनाथः सखे संख्ये जेतास्मि सकलानरीन्।
त्वमेव मे सुहृन्मित्रं साहाय्यं कर्तुमर्हसि॥', 'tvatsanāthaḥ sakhe saṃkhye jetāsmi sakalān arīn
tvam eva me suhṛn mitraṃ sāhāyyaṃ kartum arhasi', null, 4038005),
('ramayana-4-38-6', 6, 'Kishkindha Kanda, Sarga 38, Verse 6', 'जहारात्मविनाशाय वैदेहीं राक्षसाधमः।
वञ्चयित्वा तु पौलोमीमनुह्लादो यथा शचीम्॥', 'jahārātmavināśāya vaidehīṃ rākṣasādhamaḥ
vañcayitvā tu paulomīm anuhlādo yathā śacīm', null, 4038006),
('ramayana-4-38-7', 7, 'Kishkindha Kanda, Sarga 38, Verse 7', 'नचिरात्तं हनिष्यामि रावणं निशितैः शरैः।
पौलोम्याः पितरं दृप्तं शतक्रतुरिवारिहा॥', 'nacirāt taṃ haniṣyāmi rāvaṇaṃ niśitaiḥ śaraiḥ
paulomyāḥ pitaraṃ dṛptaṃ śatakratur ivārihā', null, 4038007),
('ramayana-4-38-8', 8, 'Kishkindha Kanda, Sarga 38, Verse 8', 'एतस्मिन्नन्तरे चैव रजः समभिवर्तत।
उष्णां तीव्रां सहस्रांशोश्छादयद्गगने प्रभाम्॥', 'etasminn antare caiva rajaḥ samabhivartata
uṣṇāṃ tīvrāṃ sahasrāṃśoś chādayad gagane prabhām', null, 4038008),
('ramayana-4-38-9', 9, 'Kishkindha Kanda, Sarga 38, Verse 9', 'दिशः पर्याकुलाश्चासन्रजसा तेन मूर्छिताः।
चचाल च मही सर्वा सशैलवनकानना॥', 'diśaḥ paryākulāś cāsan rajasā tena mūrchitāḥ
cacāla ca mahī sarvā saśailavanakānanā', null, 4038009),
('ramayana-4-38-10', 10, 'Kishkindha Kanda, Sarga 38, Verse 10', 'ततो नगेन्द्रसंकाशैस्तीक्ष्ण दंष्ट्रैर्महाबलैः।
कृत्स्ना संछादिता भूमिरसंख्येयैः प्लवंगमैः॥', 'tato nagendrasaṃkāśais tīkṣṇa daṃṣṭrair mahābalaiḥ
kṛtsnā saṃchāditā bhūmir asaṃkhyeyaiḥ plavaṃgamaiḥ', null, 4038010),
('ramayana-4-38-11', 11, 'Kishkindha Kanda, Sarga 38, Verse 11', 'निमेषान्तरमात्रेण ततस्तैर्हरियूथपैः।
कोटीशतपरीवारैः कामरूपिभिरावृता॥', 'nimeṣāntaramātreṇa tatas tair hariyūthapaiḥ
koṭīśataparīvāraiḥ kāmarūpibhir āvṛtā', null, 4038011),
('ramayana-4-38-12', 12, 'Kishkindha Kanda, Sarga 38, Verse 12', 'नादेयैः पार्वतीयैश्च सामुद्रैश्च महाबलैः।
हरिभिर्मेघनिर्ह्रादैरन्यैश्च वनचारिभिः॥', 'nādeyaiḥ pārvatīyaiś ca sāmudraiś ca mahābalaiḥ
haribhir meghanirhrādair anyaiś ca vanacāribhiḥ', null, 4038012),
('ramayana-4-38-13', 13, 'Kishkindha Kanda, Sarga 38, Verse 13', 'तरुणादित्यवर्णैश्च शशिगौरैश्च वानरैः।
पद्मकेसरवर्णैश्च श्वेतैर्मेरुकृतालयैः॥', 'taruṇādityavarṇaiś ca śaśigauraiś ca vānaraiḥ
padmakesaravarṇaiś ca śvetair merukṛtālayaiḥ', null, 4038013),
('ramayana-4-38-14', 14, 'Kishkindha Kanda, Sarga 38, Verse 14', 'कोटीसहस्रैर्दशभिः श्रीमान्परिवृतस्तदा।
वीरः शतबलिर्नाम वानरः प्रत्यदृश्यत॥', 'koṭīsahasrair daśabhiḥ śrīmān parivṛtas tadā
vīraḥ śatabalir nāma vānaraḥ pratyadṛśyata', null, 4038014),
('ramayana-4-38-15', 15, 'Kishkindha Kanda, Sarga 38, Verse 15', 'ततः काञ्चनशैलाभस्ताराया वीर्यवान्पिता।
अनेकैर्दशसाहस्रैः कोटिभिः प्रत्यदृश्यत॥', 'tataḥ kāñcanaśailābhas tārāyā vīryavān pitā
anekair daśasāhasraiḥ koṭibhiḥ pratyadṛśyata', null, 4038015),
('ramayana-4-38-16', 16, 'Kishkindha Kanda, Sarga 38, Verse 16', 'पद्मकेसरसंकाशस्तरुणार्कनिभाननः।
बुद्धिमान्वानरश्रेष्ठः सर्ववानरसत्तमः॥', 'padmakesarasaṃkāśas taruṇārkanibhānanaḥ
buddhimān vānaraśreṣṭhaḥ sarvavānarasattamaḥ', null, 4038016),
('ramayana-4-38-17', 17, 'Kishkindha Kanda, Sarga 38, Verse 17', 'अनीकैर्बहुसाहस्रैर्वानराणां समन्वितः।
पिता हनुमतः श्रीमान्केसरी प्रत्यदृश्यत॥', 'anīkair bahusāhasrair vānarāṇāṃ samanvitaḥ
pitā hanumataḥ śrīmān kesarī pratyadṛśyata', null, 4038017),
('ramayana-4-38-18', 18, 'Kishkindha Kanda, Sarga 38, Verse 18', 'गोलाङ्गूलमहाराजो गवाक्षो भीमविक्रमः।
वृतः कोटिसहस्रेण वानराणामदृश्यत॥', 'golāṅgūlamahārājo gavākṣo bhīmavikramaḥ
vṛtaḥ koṭisahasreṇa vānarāṇām adṛśyata', null, 4038018),
('ramayana-4-38-19', 19, 'Kishkindha Kanda, Sarga 38, Verse 19', 'ऋक्षाणां भीमवेगानां धूम्रः शत्रुनिबर्हणः।
वृतः कोटिसहस्राभ्यां द्वाभ्यां समभिवर्तत॥', 'ṛkṣāṇāṃ bhīmavegānāṃ dhūmraḥ śatrunibarhaṇaḥ
vṛtaḥ koṭisahasrābhyāṃ dvābhyāṃ samabhivartata', null, 4038019),
('ramayana-4-38-20', 20, 'Kishkindha Kanda, Sarga 38, Verse 20', 'महाचलनिभैर्घोरैः पनसो नाम यूथपः।
आजगाम महावीर्यस्तिसृभिः कोटिभिर्वृतः॥', 'mahācalanibhair ghoraiḥ panaso nāma yūthapaḥ
ājagāma mahāvīryas tisṛbhiḥ koṭibhir vṛtaḥ', null, 4038020),
('ramayana-4-38-21', 21, 'Kishkindha Kanda, Sarga 38, Verse 21', 'नीलाञ्जनचयाकारो नीलो नामाथ यूथपः।
अदृश्यत महाकायः कोटिभिर्दशभिर्वृतः॥', 'nīlāñjanacayākāro nīlo nāmātha yūthapaḥ
adṛśyata mahākāyaḥ koṭibhir daśabhir vṛtaḥ', null, 4038021),
('ramayana-4-38-22', 22, 'Kishkindha Kanda, Sarga 38, Verse 22', 'दरीमुखश्च बलवान्यूथपोऽभ्याययौ तदा।
वृतः कोटिसहस्रेण सुग्रीवं समुपस्थितः॥', 'darīmukhaś ca balavān yūthapo ''bhyāyayau tadā
vṛtaḥ koṭisahasreṇa sugrīvaṃ samupasthitaḥ', null, 4038022),
('ramayana-4-38-23', 23, 'Kishkindha Kanda, Sarga 38, Verse 23', 'मैन्दश्च द्विविदश्चोभावश्विपुत्रौ महावलौ।
कोटिकोटिसहस्रेण वानराणामदृश्यताम्॥', 'maindaś ca dvividaś cobhāv aśviputrau mahāvalau
koṭikoṭisahasreṇa vānarāṇām adṛśyatām', null, 4038023),
('ramayana-4-38-24', 24, 'Kishkindha Kanda, Sarga 38, Verse 24', 'ततः कोटिसहस्राणां सहस्रेण शतेन च।
पृष्ठतोऽनुगतः प्राप्तो हरिभिर्गन्धमादनः॥', 'tataḥ koṭisahasrāṇāṃ sahasreṇa śatena ca
pṛṣṭhato ''nugataḥ prāpto haribhir gandhamādanaḥ', null, 4038024),
('ramayana-4-38-25', 25, 'Kishkindha Kanda, Sarga 38, Verse 25', 'ततः पद्मसहस्रेण वृतः शङ्कुशतेन च।
युवराजोऽङ्गदः प्राप्तः पितृतुल्यपराक्रमः॥', 'tataḥ padmasahasreṇa vṛtaḥ śaṅkuśatena ca
yuvarājo ''ṅgadaḥ prāptaḥ pitṛtulyaparākramaḥ', null, 4038025),
('ramayana-4-38-26', 26, 'Kishkindha Kanda, Sarga 38, Verse 26', 'ततस्ताराद्युतिस्तारो हरिर्भीमपराक्रमः।
पञ्चभिर्हरिकोटीभिर्दूरतः प्रत्यदृश्यत॥', 'tatas tārādyutis tāro harir bhīmaparākramaḥ
pañcabhir harikoṭībhir dūrataḥ pratyadṛśyata', null, 4038026),
('ramayana-4-38-27', 27, 'Kishkindha Kanda, Sarga 38, Verse 27', 'इन्द्रजानुः कपिर्वीरो यूथपः प्रत्यदृश्यत।
एकादशानां कोटीनामीश्वरस्तैश्च संवृतः॥', 'indrajānuḥ kapir vīro yūthapaḥ pratyadṛśyata
ekādaśānāṃ koṭīnām īśvaras taiś ca saṃvṛtaḥ', null, 4038027),
('ramayana-4-38-28', 28, 'Kishkindha Kanda, Sarga 38, Verse 28', 'ततो रम्भस्त्वनुप्राप्तस्तरुणादित्यसंनिभः।
अयुतेन वृतश्चैव सहस्रेण शतेन च॥', 'tato rambhas tv anuprāptas taruṇādityasaṃnibhaḥ
ayutena vṛtaś caiva sahasreṇa śatena ca', null, 4038028),
('ramayana-4-38-29', 29, 'Kishkindha Kanda, Sarga 38, Verse 29', 'ततो यूथपतिर्वीरो दुर्मुखो नाम वानरः।
प्रत्यदृश्यत कोटिभ्यां द्वाभ्यां परिवृतो बली॥', 'tato yūthapatir vīro durmukho nāma vānaraḥ
pratyadṛśyata koṭibhyāṃ dvābhyāṃ parivṛto balī', null, 4038029),
('ramayana-4-38-30', 30, 'Kishkindha Kanda, Sarga 38, Verse 30', 'कैलासशिखराकारैर्वानरैर्भीमविक्रमैः।
वृतः कोटिसहस्रेण हनुमान्प्रत्यदृश्यत॥', 'kailāsaśikharākārair vānarair bhīmavikramaiḥ
vṛtaḥ koṭisahasreṇa hanumān pratyadṛśyata', null, 4038030),
('ramayana-4-38-31', 31, 'Kishkindha Kanda, Sarga 38, Verse 31', 'नलश्चापि महावीर्यः संवृतो द्रुमवासिभिः।
कोटीशतेन संप्राप्तः सहस्रेण शतेन च॥', 'nalaś cāpi mahāvīryaḥ saṃvṛto drumavāsibhiḥ
koṭīśatena saṃprāptaḥ sahasreṇa śatena ca', null, 4038031),
('ramayana-4-38-32', 32, 'Kishkindha Kanda, Sarga 38, Verse 32', 'शरभः कुमुदो वह्निर्वानरो रम्भ एव च।
एते चान्ये च बहवो वानराः कामरूपिणः॥', 'śarabhaḥ kumudo vahnir vānaro rambha eva ca
ete cānye ca bahavo vānarāḥ kāmarūpiṇaḥ', null, 4038032),
('ramayana-4-38-33', 33, 'Kishkindha Kanda, Sarga 38, Verse 33', 'आवृत्य पृथिवीं सर्वां पर्वतांश्च वनानि च।
आप्लवन्तः प्लवन्तश्च गर्जन्तश्च प्लवंगमाः।
अभ्यवर्तन्त सुग्रीवं सूर्यमभ्रगणा इव॥', 'āvṛtya pṛthivīṃ sarvāṃ parvatāṃś ca vanāni ca
āplavantaḥ plavantaś ca garjantaś ca plavaṃgamāḥ
abhyavartanta sugrīvaṃ sūryam abhragaṇā iva', null, 4038033),
('ramayana-4-38-34', 34, 'Kishkindha Kanda, Sarga 38, Verse 34', 'कुर्वाणा बहुशब्दांश्च प्रहृष्टा बलशालिनः।
शिरोभिर्वानरेन्द्राय सुग्रीवाय न्यवेदयन्॥', 'kurvāṇā bahuśabdāṃś ca prahṛṣṭā balaśālinaḥ
śirobhir vānarendrāya sugrīvāya nyavedayan', null, 4038034),
('ramayana-4-38-35', 35, 'Kishkindha Kanda, Sarga 38, Verse 35', 'अपरे वानरश्रेष्ठाः संगम्य च यथोचितम्।
सुग्रीवेण समागम्य स्थिताः प्राञ्जलयस्तदा॥', 'apare vānaraśreṣṭhāḥ saṃgamya ca yathocitam
sugrīveṇa samāgamya sthitāḥ prāñjalayas tadā', null, 4038035),
('ramayana-4-38-36', 36, 'Kishkindha Kanda, Sarga 38, Verse 36', 'सुग्रीवस्त्वरितो रामे सर्वांस्तान्वानरर्षभान्।
निवेदयित्वा धर्मज्ञः स्थितः प्राञ्जलिरब्रवीत्॥', 'sugrīvas tvarito rāme sarvāṃs tān vānararṣabhān
nivedayitvā dharmajñaḥ sthitaḥ prāñjalir abravīt', null, 4038036),
('ramayana-4-38-37', 37, 'Kishkindha Kanda, Sarga 38, Verse 37', 'यथा सुखं पर्वतनिर्झरेषु वनेषु सर्वेषु च वानरेन्द्राः।
निवेशयित्वा विधिवद्बलानि बलं बलज्ञः प्रतिपत्तुमीष्टे॥', 'yathā sukhaṃ parvatanirjhareṣu vaneṣu sarveṣu ca vānarendrāḥ
niveśayitvā vidhivad balāni balaṃ balajñaḥ pratipattum īṣṭe', null, 4038037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 39 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-39-1', 1, 'Kishkindha Kanda, Sarga 39, Verse 1', 'अथ राजा समृद्धार्थः सुग्रीवः प्लवगेश्वरः।
उवाच नरशार्दूलं रामं परबलार्दनम्॥', 'atha rājā samṛddhārthaḥ sugrīvaḥ plavageśvaraḥ
uvāca naraśārdūlaṃ rāmaṃ parabalārdanam', null, 4039001),
('ramayana-4-39-2', 2, 'Kishkindha Kanda, Sarga 39, Verse 2', 'आगता विनिविष्टाश्च बलिनः कामरूपिणः।
वानरेन्द्रा महेन्द्राभा ये मद्विषयवासिनः॥', 'āgatā viniviṣṭāś ca balinaḥ kāmarūpiṇaḥ
vānarendrā mahendrābhā ye madviṣayavāsinaḥ', null, 4039002),
('ramayana-4-39-3', 3, 'Kishkindha Kanda, Sarga 39, Verse 3', 'त इमे बहुसाहस्रैर्हरिभिर्भीमविक्रमैः।
आगता वानरा घोरा दैत्यदानवसंनिभाः॥', 'ta ime bahusāhasrair haribhir bhīmavikramaiḥ
āgatā vānarā ghorā daityadānavasaṃnibhāḥ', null, 4039003),
('ramayana-4-39-4', 4, 'Kishkindha Kanda, Sarga 39, Verse 4', 'ख्यातकर्मापदानाश्च बलवन्तो जितक्लमाः।
पराक्रमेषु विख्याता व्यवसायेषु चोत्तमाः॥', 'khyātakarmāpadānāś ca balavanto jitaklamāḥ
parākrameṣu vikhyātā vyavasāyeṣu cottamāḥ', null, 4039004),
('ramayana-4-39-5', 5, 'Kishkindha Kanda, Sarga 39, Verse 5', 'पृथिव्यम्बुचरा राम नानानगनिवासिनः।
कोट्यग्रश इमे प्राप्ता वानरास्तव किंकराः॥', 'pṛthivyambucarā rāma nānānaganivāsinaḥ
koṭyagraśa ime prāptā vānarās tava kiṃkarāḥ', null, 4039005),
('ramayana-4-39-6', 6, 'Kishkindha Kanda, Sarga 39, Verse 6', 'निदेशवर्तिनः सर्वे सर्वे गुरुहिते रताः।
अभिप्रेतमनुष्ठातुं तव शक्ष्यन्त्यरिंदम॥', 'nideśavartinaḥ sarve sarve guruhite ratāḥ
abhipretam anuṣṭhātuṃ tava śakṣyanty ariṃdama', null, 4039006),
('ramayana-4-39-7', 7, 'Kishkindha Kanda, Sarga 39, Verse 7', 'यन्मन्यसे नरव्याघ्र प्राप्तकालं तदुच्यताम्।
तत्सैन्यं त्वद्वशे युक्तमाज्ञापयितुमर्हसि॥', 'yan manyase naravyāghra prāptakālaṃ tad ucyatām
tat sainyaṃ tvadvaśe yuktam ājñāpayitum arhasi', null, 4039007),
('ramayana-4-39-8', 8, 'Kishkindha Kanda, Sarga 39, Verse 8', 'काममेषामिदं कार्यं विदितं मम तत्त्वतः।
तथापि तु यथा तत्त्वमाज्ञापयितुमर्हसि॥', 'kāmam eṣām idaṃ kāryaṃ viditaṃ mama tattvataḥ
tathāpi tu yathā tattvam ājñāpayitum arhasi', null, 4039008),
('ramayana-4-39-9', 9, 'Kishkindha Kanda, Sarga 39, Verse 9', 'तथा ब्रुवाणं सुग्रीवं रामो दशरथात्मजः।
बाहुभ्यां संपरिष्वज्य इदं वचनमब्रवीत्॥', 'tathā bruvāṇaṃ sugrīvaṃ rāmo daśarathātmajaḥ
bāhubhyāṃ saṃpariṣvajya idaṃ vacanam abravīt', null, 4039009),
('ramayana-4-39-10', 10, 'Kishkindha Kanda, Sarga 39, Verse 10', 'ज्ञायतां सौम्य वैदेही यदि जीवति वा न वा।
स च देशो महाप्राज्ञ यस्मिन्वसति रावणः॥', 'jñāyatāṃ saumya vaidehī yadi jīvati vā na vā
sa ca deśo mahāprājña yasmin vasati rāvaṇaḥ', null, 4039010),
('ramayana-4-39-11', 11, 'Kishkindha Kanda, Sarga 39, Verse 11', 'अधिगम्य च वैदेहीं निलयं रावणस्य च।
प्राप्तकालं विधास्यामि तस्मिन्काले सह त्वया॥', 'adhigamya ca vaidehīṃ nilayaṃ rāvaṇasya ca
prāptakālaṃ vidhāsyāmi tasmin kāle saha tvayā', null, 4039011),
('ramayana-4-39-12', 12, 'Kishkindha Kanda, Sarga 39, Verse 12', 'नाहमस्मिन्प्रभुः कार्ये वानरेश न लक्ष्मणः।
त्वमस्य हेतुः कार्यस्य प्रभुश्च प्लवगेश्वर॥', 'nāham asmin prabhuḥ kārye vānareśa na lakṣmaṇaḥ
tvam asya hetuḥ kāryasya prabhuś ca plavageśvara', null, 4039012),
('ramayana-4-39-13', 13, 'Kishkindha Kanda, Sarga 39, Verse 13', 'त्वमेवाज्ञापय विभो मम कार्यविनिश्चयम्।
त्वं हि जानासि यत्कार्यं मम वीर न संशयः॥', 'tvam evājñāpaya vibho mama kāryaviniścayam
tvaṃ hi jānāsi yat kāryaṃ mama vīra na saṃśayaḥ', null, 4039013),
('ramayana-4-39-14', 14, 'Kishkindha Kanda, Sarga 39, Verse 14', 'सुहृद्द्वितीयो विक्रान्तः प्राज्ञः कालविशेषवित्।
भवानस्मद्धिते युक्तः सुकृतार्थोऽर्थवित्तमः॥', 'suhṛddvitīyo vikrāntaḥ prājñaḥ kālaviśeṣavit
bhavān asmaddhite yuktaḥ sukṛtārtho ''rthavittamaḥ', null, 4039014),
('ramayana-4-39-15', 15, 'Kishkindha Kanda, Sarga 39, Verse 15', 'एवमुक्तस्तु सुग्रीवो विनतं नाम यूथपम्।
अब्रवीद्राम साम्निध्ये लक्ष्मणस्य च धीमतः।
शैलाभं मेघनिर्घोषमूर्जितं प्लवगेश्वरम्॥', 'evam uktas tu sugrīvo vinataṃ nāma yūthapam
abravīd rāma sāmnidhye lakṣmaṇasya ca dhīmataḥ
śailābhaṃ meghanirghoṣam ūrjitaṃ plavageśvaram', null, 4039015),
('ramayana-4-39-16', 16, 'Kishkindha Kanda, Sarga 39, Verse 16', 'सोमसूर्यात्मजैः सार्धं वानरैर्वानरोत्तम।
देशकालनयैर्युक्तः कार्याकार्यविनिश्चये॥', 'somasūryātmajaiḥ sārdhaṃ vānarair vānarottama
deśakālanayair yuktaḥ kāryākāryaviniścaye', null, 4039016),
('ramayana-4-39-17', 17, 'Kishkindha Kanda, Sarga 39, Verse 17', 'वृतः शतसहस्रेण वानराणां तरस्विनाम्।
अधिगच्छ दिशं पूर्वां सशैलवनकाननाम्॥', 'vṛtaḥ śatasahasreṇa vānarāṇāṃ tarasvinām
adhigaccha diśaṃ pūrvāṃ saśailavanakānanām', null, 4039017),
('ramayana-4-39-18', 18, 'Kishkindha Kanda, Sarga 39, Verse 18', 'तत्र सीतां च वैदेहीं निलयं रावणस्य च।
मार्गध्वं गिरिदुर्गेषु वनेषु च नदीषु च॥', 'tatra sītāṃ ca vaidehīṃ nilayaṃ rāvaṇasya ca
mārgadhvaṃ giridurgeṣu vaneṣu ca nadīṣu ca', null, 4039018),
('ramayana-4-39-19', 19, 'Kishkindha Kanda, Sarga 39, Verse 19', 'नदीं भागीरथीं रम्यां सरयूं कौशिकीं तथा।
कालिन्दीं यमुनां रम्यां यामुनं च महागिरिम्॥', 'nadīṃ bhāgīrathīṃ ramyāṃ sarayūṃ kauśikīṃ tathā
kālindīṃ yamunāṃ ramyāṃ yāmunaṃ ca mahāgirim', null, 4039019),
('ramayana-4-39-20', 20, 'Kishkindha Kanda, Sarga 39, Verse 20', 'सरस्वतीं च सिन्धुं च शोणं मणिनिभोदकम्।
महीं कालमहीं चैव शैलकाननशोभिताम्॥', 'sarasvatīṃ ca sindhuṃ ca śoṇaṃ maṇinibhodakam
mahīṃ kālamahīṃ caiva śailakānanaśobhitām', null, 4039020),
('ramayana-4-39-21', 21, 'Kishkindha Kanda, Sarga 39, Verse 21', 'ब्रह्ममालान्विदेहांश्च मालवान्काशिकोसलान्।
मागधांश्च महाग्रामान्पुण्ड्रान्वङ्गांस्तथैव च॥', 'brahmamālān videhāṃś ca mālavān kāśikosalān
māgadhāṃś ca mahāgrāmān puṇḍrān vaṅgāṃs tathaiva ca', null, 4039021),
('ramayana-4-39-22', 22, 'Kishkindha Kanda, Sarga 39, Verse 22', 'पत्तनं कोशकाराणां भूमिं च रजताकराम्।
सर्वमेतद्विचेतव्यं मृगयद्भिर्ततस्ततः॥', 'pattanaṃ kośakārāṇāṃ bhūmiṃ ca rajatākarām
sarvam etad vicetavyaṃ mṛgayadbhir tatas tataḥ', null, 4039022),
('ramayana-4-39-23', 23, 'Kishkindha Kanda, Sarga 39, Verse 23', 'रामस्य दयितां भार्यां सीतां दशरतः स्नुषाम्।
समुद्रमवगाढांश्च पर्वतान्पत्तनानि च॥', 'rāmasya dayitāṃ bhāryāṃ sītāṃ daśarataḥ snuṣām
samudram avagāḍhāṃś ca parvatān pattanāni ca', null, 4039023),
('ramayana-4-39-24', 24, 'Kishkindha Kanda, Sarga 39, Verse 24', 'मन्दरस्य च ये कोटिं संश्रिताः के चिदायताम्।
कर्णप्रावरणाश्चैव तथा चाप्योष्ठकर्णकाः॥', 'mandarasya ca ye koṭiṃ saṃśritāḥ ke cid āyatām
karṇaprāvaraṇāś caiva tathā cāpy oṣṭhakarṇakāḥ', null, 4039024),
('ramayana-4-39-25', 25, 'Kishkindha Kanda, Sarga 39, Verse 25', 'घोरा लोहमुखाश्चैव जवनाश्चैकपादकाः।
अक्षया बलवन्तश्च पुरुषाः पुरुषादकाः॥', 'ghorā lohamukhāś caiva javanāś caikapādakāḥ
akṣayā balavantaś ca puruṣāḥ puruṣādakāḥ', null, 4039025),
('ramayana-4-39-26', 26, 'Kishkindha Kanda, Sarga 39, Verse 26', 'किराताः कर्णचूडाश्च हेमाङ्गाः प्रियदर्शनाः।
आममीनाशनास्तत्र किराता द्वीपवासिनः॥', 'kirātāḥ karṇacūḍāś ca hemāṅgāḥ priyadarśanāḥ
āmamīnāśanās tatra kirātā dvīpavāsinaḥ', null, 4039026),
('ramayana-4-39-27', 27, 'Kishkindha Kanda, Sarga 39, Verse 27', 'अन्तर्जलचरा घोरा नरव्याघ्रा इति श्रुताः।
एतेषामालयाः सर्वे विचेयाः काननौकसः॥', 'antarjalacarā ghorā naravyāghrā iti śrutāḥ
eteṣām ālayāḥ sarve viceyāḥ kānanaukasaḥ', null, 4039027),
('ramayana-4-39-28', 28, 'Kishkindha Kanda, Sarga 39, Verse 28', 'गिरिभिर्ये च गम्यन्ते प्लवनेन प्लवेन च।
रत्नवन्तं यवद्वीपं सप्तराज्योपशोभितम्॥', 'giribhir ye ca gamyante plavanena plavena ca
ratnavantaṃ yavadvīpaṃ saptarājyopaśobhitam', null, 4039028),
('ramayana-4-39-29', 29, 'Kishkindha Kanda, Sarga 39, Verse 29', 'सुवर्णरूप्यकं चैव सुवर्णाकरमण्डितम्।
यवद्वीपमतिक्रम्य शिशिरो नाम पर्वतः॥', 'suvarṇarūpyakaṃ caiva suvarṇākaramaṇḍitam
yavadvīpam atikramya śiśiro nāma parvataḥ', null, 4039029),
('ramayana-4-39-30', 30, 'Kishkindha Kanda, Sarga 39, Verse 30', 'दिवं स्पृशति शृङ्गेण देवदानवसेवितः।
एतेषां गिरिदुर्गेषु प्रतापेषु वनेषु च॥', 'divaṃ spṛśati śṛṅgeṇa devadānavasevitaḥ
eteṣāṃ giridurgeṣu pratāpeṣu vaneṣu ca', null, 4039030),
('ramayana-4-39-31', 31, 'Kishkindha Kanda, Sarga 39, Verse 31', 'रावणः सह वैदेह्या मार्गितव्यस्ततस्ततः।
ततः समुद्रद्वीपांश्च सुभीमान्द्रष्टुमर्हथ॥', 'rāvaṇaḥ saha vaidehyā mārgitavyas tatas tataḥ
tataḥ samudradvīpāṃś ca subhīmān draṣṭum arhatha', null, 4039031),
('ramayana-4-39-32', 32, 'Kishkindha Kanda, Sarga 39, Verse 32', 'तत्रासुरा महाकायाश्छायां गृह्णन्ति नित्यशः।
ब्रह्मणा समनुज्ञाता दीर्घकालं बुभुक्षिताः॥', 'tatrāsurā mahākāyāś chāyāṃ gṛhṇanti nityaśaḥ
brahmaṇā samanujñātā dīrghakālaṃ bubhukṣitāḥ', null, 4039032),
('ramayana-4-39-33', 33, 'Kishkindha Kanda, Sarga 39, Verse 33', 'तं कालमेघप्रतिमं महोरगनिषेवितम्।
अभिगम्य महानादं तीर्थेनैव महोदधिम्॥', 'taṃ kālameghapratimaṃ mahoraganiṣevitam
abhigamya mahānādaṃ tīrthenaiva mahodadhim', null, 4039033),
('ramayana-4-39-34', 34, 'Kishkindha Kanda, Sarga 39, Verse 34', 'ततो रक्तजलं भीमं लोहितं नाम सागरम्।
गता द्रक्ष्यथ तां चैव बृहतीं कूटशाल्मलीम्॥', 'tato raktajalaṃ bhīmaṃ lohitaṃ nāma sāgaram
gatā drakṣyatha tāṃ caiva bṛhatīṃ kūṭaśālmalīm', null, 4039034),
('ramayana-4-39-35', 35, 'Kishkindha Kanda, Sarga 39, Verse 35', 'गृहं च वैनतेयस्य नानारत्नविभूषितम्।
तत्र कैलाससंकाशं विहितं विश्वकर्मणा॥', 'gṛhaṃ ca vainateyasya nānāratnavibhūṣitam
tatra kailāsasaṃkāśaṃ vihitaṃ viśvakarmaṇā', null, 4039035),
('ramayana-4-39-36', 36, 'Kishkindha Kanda, Sarga 39, Verse 36', 'तत्र शैलनिभा भीमा मन्देहा नाम राक्षसाः।
शैलशृङ्गेषु लम्बन्ते नानारूपा भयावहाः॥', 'tatra śailanibhā bhīmā mandehā nāma rākṣasāḥ
śailaśṛṅgeṣu lambante nānārūpā bhayāvahāḥ', null, 4039036),
('ramayana-4-39-37', 37, 'Kishkindha Kanda, Sarga 39, Verse 37', 'ते पतन्ति जले नित्यं सूर्यस्योदयनं प्रति।
अभितप्ताश्च सूर्येण लम्बन्ते स्म पुनः पुनः॥', 'te patanti jale nityaṃ sūryasyodayanaṃ prati
abhitaptāś ca sūryeṇa lambante sma punaḥ punaḥ', null, 4039037),
('ramayana-4-39-38', 38, 'Kishkindha Kanda, Sarga 39, Verse 38', 'ततः पाण्डुरमेघाभं क्षीरौदं नाम सागरम्।
गता द्रक्ष्यथ दुर्धर्षा मुखा हारमिवोर्मिभिः॥', 'tataḥ pāṇḍurameghābhaṃ kṣīraudaṃ nāma sāgaram
gatā drakṣyatha durdharṣā mukhā hāram ivormibhiḥ', null, 4039038),
('ramayana-4-39-39', 39, 'Kishkindha Kanda, Sarga 39, Verse 39', 'तस्य मध्ये महाश्वेत ऋषभो नाम पर्वतः।
दिव्यगन्धैः कुसुमितै रजतैश्च नगैर्वृतः॥', 'tasya madhye mahāśveta ṛṣabho nāma parvataḥ
divyagandhaiḥ kusumitai rajataiś ca nagair vṛtaḥ', null, 4039039),
('ramayana-4-39-40', 40, 'Kishkindha Kanda, Sarga 39, Verse 40', 'सरश्च राजतैः पद्मैर्ज्वलितैर्हेमकेसरैः।
नाम्ना सुदर्शनं नाम राजहंसैः समाकुलम्॥', 'saraś ca rājataiḥ padmair jvalitair hemakesaraiḥ
nāmnā sudarśanaṃ nāma rājahaṃsaiḥ samākulam', null, 4039040),
('ramayana-4-39-41', 41, 'Kishkindha Kanda, Sarga 39, Verse 41', 'विबुधाश्चारणा यक्षाः किंनराः साप्सरोगणाः।
हृष्टाः समभिगच्छन्ति नलिनीं तां रिरंसवः॥', 'vibudhāś cāraṇā yakṣāḥ kiṃnarāḥ sāpsarogaṇāḥ
hṛṣṭāḥ samabhigacchanti nalinīṃ tāṃ riraṃsavaḥ', null, 4039041),
('ramayana-4-39-42', 42, 'Kishkindha Kanda, Sarga 39, Verse 42', 'क्षीरोदं समतिक्रम्य ततो द्रक्ष्यथ वानराः।
जलोदं सागरश्रेष्ठं सर्वभूतभयावहम्॥', 'kṣīrodaṃ samatikramya tato drakṣyatha vānarāḥ
jalodaṃ sāgaraśreṣṭhaṃ sarvabhūtabhayāvaham', null, 4039042),
('ramayana-4-39-43', 43, 'Kishkindha Kanda, Sarga 39, Verse 43', 'तत्र तत्कोपजं तेजः कृतं हयमुखं महत्।
अस्याहुस्तन्महावेगमोदनं सचराचरम्॥', 'tatra tat kopajaṃ tejaḥ kṛtaṃ hayamukhaṃ mahat
asyāhus tan mahāvegam odanaṃ sacarācaram', null, 4039043),
('ramayana-4-39-44', 44, 'Kishkindha Kanda, Sarga 39, Verse 44', 'तत्र विक्रोशतां नादो भूतानां सागरौकसाम्।
श्रूयते चासमर्थानां दृष्ट्वा तद्वडवामुखम्॥', 'tatra vikrośatāṃ nādo bhūtānāṃ sāgaraukasām
śrūyate cāsamarthānāṃ dṛṣṭvā tad vaḍavāmukham', null, 4039044),
('ramayana-4-39-45', 45, 'Kishkindha Kanda, Sarga 39, Verse 45', 'स्वादूदस्योत्तरे देशे योजनानि त्रयोदश।
जातरूपशिलो नाम महान्कनकपर्वतः॥', 'svādūdasyottare deśe yojanāni trayodaśa
jātarūpaśilo nāma mahān kanakaparvataḥ', null, 4039045),
('ramayana-4-39-46', 46, 'Kishkindha Kanda, Sarga 39, Verse 46', 'आसीनं पर्वतस्याग्रे सर्वभूतनमस्कृतम्।
सहस्रशिरसं देवमनन्तं नीलवाससं॥', 'āsīnaṃ parvatasyāgre sarvabhūtanamaskṛtam
sahasraśirasaṃ devam anantaṃ nīlavāsasaṃ', null, 4039046),
('ramayana-4-39-47', 47, 'Kishkindha Kanda, Sarga 39, Verse 47', 'त्रिशिराः काञ्चनः केतुस्तालस्तस्य महात्मनः।
स्थापितः पर्वतस्याग्रे विराजति सवेदिकः॥', 'triśirāḥ kāñcanaḥ ketus tālas tasya mahātmanaḥ
sthāpitaḥ parvatasyāgre virājati savedikaḥ', null, 4039047),
('ramayana-4-39-48', 48, 'Kishkindha Kanda, Sarga 39, Verse 48', 'पूर्वस्यां दिशि निर्माणं कृतं तत्त्रिदशेश्वरैः।
ततः परं हेममयः श्रीमानुदयपर्वतः॥', 'pūrvasyāṃ diśi nirmāṇaṃ kṛtaṃ tat tridaśeśvaraiḥ
tataḥ paraṃ hemamayaḥ śrīmān udayaparvataḥ', null, 4039048),
('ramayana-4-39-49', 49, 'Kishkindha Kanda, Sarga 39, Verse 49', 'तस्य कोटिर्दिवं स्पृष्ट्वा शतयोजनमायता।
जातरूपमयी दिव्या विराजति सवेदिका॥', 'tasya koṭir divaṃ spṛṣṭvā śatayojanam āyatā
jātarūpamayī divyā virājati savedikā', null, 4039049),
('ramayana-4-39-50', 50, 'Kishkindha Kanda, Sarga 39, Verse 50', 'सालैस्तालैस्तमालैश्च कर्णिकारैश्च पुष्पितैः।
जातरूपमयैर्दिव्यैः शोभते सूर्यसंनिभैः॥', 'sālais tālais tamālaiś ca karṇikāraiś ca puṣpitaiḥ
jātarūpamayair divyaiḥ śobhate sūryasaṃnibhaiḥ', null, 4039050),
('ramayana-4-39-51', 51, 'Kishkindha Kanda, Sarga 39, Verse 51', 'तत्र योजनविस्तारमुच्छ्रितं दशयोजनम्।
शृङ्गं सौमनसं नाम जातरूपमयं ध्रुवम्॥', 'tatra yojanavistāram ucchritaṃ daśayojanam
śṛṅgaṃ saumanasaṃ nāma jātarūpamayaṃ dhruvam', null, 4039051),
('ramayana-4-39-52', 52, 'Kishkindha Kanda, Sarga 39, Verse 52', 'तत्र पूर्वं पदं कृत्वा पुरा विष्णुस्त्रिविक्रमे।
द्वितीयं शिखरं मेरोश्चकार पुरुषोत्तमः॥', 'tatra pūrvaṃ padaṃ kṛtvā purā viṣṇus trivikrame
dvitīyaṃ śikharaṃ meroś cakāra puruṣottamaḥ', null, 4039052),
('ramayana-4-39-53', 53, 'Kishkindha Kanda, Sarga 39, Verse 53', 'उत्तरेण परिक्रम्य जम्बूद्वीपं दिवाकरः।
दृश्यो भवति भूयिष्ठं शिखरं तन्महोच्छ्रयम्॥', 'uttareṇa parikramya jambūdvīpaṃ divākaraḥ
dṛśyo bhavati bhūyiṣṭhaṃ śikharaṃ tan mahocchrayam', null, 4039053),
('ramayana-4-39-54', 54, 'Kishkindha Kanda, Sarga 39, Verse 54', 'तत्र वैखानसा नाम वालखिल्या महर्षयः।
प्रकाशमाना दृश्यन्ते सूर्यवर्णास्तपस्विनः॥', 'tatra vaikhānasā nāma vālakhilyā maharṣayaḥ
prakāśamānā dṛśyante sūryavarṇās tapasvinaḥ', null, 4039054),
('ramayana-4-39-55', 55, 'Kishkindha Kanda, Sarga 39, Verse 55', 'अयं सुदर्शनो द्वीपः पुरो यस्य प्रकाशते।
यस्मिंस्तेजश्च चक्षुश्च सर्वप्रानभृतामपि॥', 'ayaṃ sudarśano dvīpaḥ puro yasya prakāśate
yasmiṃs tejaś ca cakṣuś ca sarvaprānabhṛtām api', null, 4039055),
('ramayana-4-39-56', 56, 'Kishkindha Kanda, Sarga 39, Verse 56', 'शैलस्य तस्य कुञ्जेषु कन्दरेषु वनेषु च।
रावणः सह वैदेह्या मार्गितव्यस्ततस्ततः॥', 'śailasya tasya kuñjeṣu kandareṣu vaneṣu ca
rāvaṇaḥ saha vaidehyā mārgitavyas tatas tataḥ', null, 4039056),
('ramayana-4-39-57', 57, 'Kishkindha Kanda, Sarga 39, Verse 57', 'काञ्चनस्य च शैलस्य सूर्यस्य च महात्मनः।
आविष्टा तेजसा संध्या पूर्वा रक्ता प्रकाशते॥', 'kāñcanasya ca śailasya sūryasya ca mahātmanaḥ
āviṣṭā tejasā saṃdhyā pūrvā raktā prakāśate', null, 4039057),
('ramayana-4-39-58', 58, 'Kishkindha Kanda, Sarga 39, Verse 58', 'ततः परमगम्या स्याद्दिक्पूर्वा त्रिदशावृता।
रहिता चन्द्रसूर्याभ्यामदृश्या तिमिरावृता॥', 'tataḥ paramagamyā syād dik pūrvā tridaśāvṛtā
rahitā candrasūryābhyām adṛśyā timirāvṛtā', null, 4039058),
('ramayana-4-39-59', 59, 'Kishkindha Kanda, Sarga 39, Verse 59', 'शैलेषु तेषु सर्वेषु कन्दरेषु वनेषु च।
य च नोक्ता मया देशा विचेया तेषु जानकी॥', 'śaileṣu teṣu sarveṣu kandareṣu vaneṣu ca
ya ca noktā mayā deśā viceyā teṣu jānakī', null, 4039059),
('ramayana-4-39-60', 60, 'Kishkindha Kanda, Sarga 39, Verse 60', 'एतावद्वानरैः शक्यं गन्तुं वानरपुंगवाः।
अभास्करममर्यादं न जानीमस्ततः परम्॥', 'etāvad vānaraiḥ śakyaṃ gantuṃ vānarapuṃgavāḥ
abhāskaram amaryādaṃ na jānīmas tataḥ param', null, 4039060),
('ramayana-4-39-61', 61, 'Kishkindha Kanda, Sarga 39, Verse 61', 'अधिगम्य तु वैदेहीं निलयं रावणस्य च।
मासे पूर्णे निवर्तध्वमुदयं प्राप्य पर्वतम्॥', 'adhigamya tu vaidehīṃ nilayaṃ rāvaṇasya ca
māse pūrṇe nivartadhvam udayaṃ prāpya parvatam', null, 4039061),
('ramayana-4-39-62', 62, 'Kishkindha Kanda, Sarga 39, Verse 62', 'ऊर्ध्वं मासान्न वस्तव्यं वसन्वध्यो भवेन्मम।
सिद्धार्थाः संनिवर्तध्वमधिगम्य च मैथिलीम्॥', 'ūrdhvaṃ māsān na vastavyaṃ vasan vadhyo bhaven mama
siddhārthāḥ saṃnivartadhvam adhigamya ca maithilīm', null, 4039062),
('ramayana-4-39-63', 63, 'Kishkindha Kanda, Sarga 39, Verse 63', 'महेन्द्रकान्तां वनषण्ड मण्डितां दिशं चरित्वा निपुणेन वानराः।
अवाप्य सीतां रघुवंशजप्रियां ततो निवृत्ताः सुखितो भविष्यथ॥', 'mahendrakāntāṃ vanaṣaṇḍa maṇḍitāṃ diśaṃ caritvā nipuṇena vānarāḥ
avāpya sītāṃ raghuvaṃśajapriyāṃ tato nivṛttāḥ sukhito bhaviṣyatha', null, 4039063)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 40 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-40-1', 1, 'Kishkindha Kanda, Sarga 40, Verse 1', 'ततः प्रस्थाप्य सुग्रीवस्तन्महद्वानरं बलम्।
दक्षिणां प्रेषयामास वानरानभिलक्षितान्॥', 'tataḥ prasthāpya sugrīvas tan mahad vānaraṃ balam
dakṣiṇāṃ preṣayām āsa vānarān abhilakṣitān', null, 4040001),
('ramayana-4-40-2', 2, 'Kishkindha Kanda, Sarga 40, Verse 2', 'नीलमग्निसुतं चैव हनुमन्तं च वानरम्।
पितामहसुतं चैव जाम्बवन्तं महाकपिम्॥', 'nīlam agnisutaṃ caiva hanumantaṃ ca vānaram
pitāmahasutaṃ caiva jāmbavantaṃ mahākapim', null, 4040002),
('ramayana-4-40-3', 3, 'Kishkindha Kanda, Sarga 40, Verse 3', 'सुहोत्रं च शरीरं च शरगुल्मं तथैव च।
गजं गवाक्षं गवयं सुषेणमृषभं तथा॥', 'suhotraṃ ca śarīraṃ ca śaragulmaṃ tathaiva ca
gajaṃ gavākṣaṃ gavayaṃ suṣeṇam ṛṣabhaṃ tathā', null, 4040003),
('ramayana-4-40-4', 4, 'Kishkindha Kanda, Sarga 40, Verse 4', 'मैन्दं च द्विविदं चैव विजयं गन्धमादनम्।
उल्कामुखमसङ्गं च हुताशन सुतावुभौ॥', 'maindaṃ ca dvividaṃ caiva vijayaṃ gandhamādanam
ulkāmukham asaṅgaṃ ca hutāśana sutāv ubhau', null, 4040004),
('ramayana-4-40-5', 5, 'Kishkindha Kanda, Sarga 40, Verse 5', 'अङ्गदप्रमुखान्वीरान्वीरः कपिगणेश्वरः।
वेगविक्रमसंपन्नान्संदिदेश विशेषवित्॥', 'aṅgadapramukhān vīrān vīraḥ kapigaṇeśvaraḥ
vegavikramasaṃpannān saṃdideśa viśeṣavit', null, 4040005),
('ramayana-4-40-6', 6, 'Kishkindha Kanda, Sarga 40, Verse 6', 'तेषामग्रेषरं चैव महद्बलमसंगगम्।
विधाय हरिवीराणामादिशद्दक्षिणां दिशम्॥', 'teṣām agreṣaraṃ caiva mahad balam asaṃgagam
vidhāya harivīrāṇām ādiśad dakṣiṇāṃ diśam', null, 4040006),
('ramayana-4-40-7', 7, 'Kishkindha Kanda, Sarga 40, Verse 7', 'ये के चन समुद्देशास्तस्यां दिशि सुदुर्गमाः।
कपीशः कपिमुख्यानां स तेषां तानुदाहरत्॥', 'ye ke cana samuddeśās tasyāṃ diśi sudurgamāḥ
kapīśaḥ kapimukhyānāṃ sa teṣāṃ tān udāharat', null, 4040007),
('ramayana-4-40-8', 8, 'Kishkindha Kanda, Sarga 40, Verse 8', 'सहस्रशिरसं विन्ध्यं नानाद्रुमलतावृतम्।
नर्मदां च नदीं दुर्गां महोरगनिषेविताम्॥', 'sahasraśirasaṃ vindhyaṃ nānādrumalatāvṛtam
narmadāṃ ca nadīṃ durgāṃ mahoraganiṣevitām', null, 4040008),
('ramayana-4-40-9', 9, 'Kishkindha Kanda, Sarga 40, Verse 9', 'ततो गोदावरीं रम्यां कृष्णावेणीं महानदीम्।
वरदां च महाभागां महोरगनिषेविताम्॥', 'tato godāvarīṃ ramyāṃ kṛṣṇāveṇīṃ mahānadīm
varadāṃ ca mahābhāgāṃ mahoraganiṣevitām', null, 4040009),
('ramayana-4-40-10', 10, 'Kishkindha Kanda, Sarga 40, Verse 10', 'मेखलानुत्कलांश्चैव दशार्णनगराण्यपि।
अवन्तीमभ्रवन्तीं च सर्वमेवानुपश्यत॥', 'mekhalān utkalāṃś caiva daśārṇanagarāṇy api
avantīm abhravantīṃ ca sarvam evānupaśyata', null, 4040010),
('ramayana-4-40-11', 11, 'Kishkindha Kanda, Sarga 40, Verse 11', 'विदर्भानृषिकांश्चैव रम्यान्माहिषकानपि।
तथा बङ्गान्कलिङ्गांश्च कौशिकांश्च समन्ततः॥', 'vidarbhān ṛṣikāṃś caiva ramyān māhiṣakān api
tathā baṅgān kaliṅgāṃś ca kauśikāṃś ca samantataḥ', null, 4040011),
('ramayana-4-40-12', 12, 'Kishkindha Kanda, Sarga 40, Verse 12', 'अन्वीक्ष्य दण्डकारण्यं सपर्वतनदीगुहम्।
नदीं गोदावरीं चैव सर्वमेवानुपश्यत॥', 'anvīkṣya daṇḍakāraṇyaṃ saparvatanadīguham
nadīṃ godāvarīṃ caiva sarvam evānupaśyata', null, 4040012),
('ramayana-4-40-13', 13, 'Kishkindha Kanda, Sarga 40, Verse 13', 'तथैवान्ध्रांश्च पुण्ड्रांश्च चोलान्पाण्ड्यान्सकेरलान्।
अयोमुखश्च गन्तव्यः पर्वतो धातुमण्डितः॥', 'tathaivāndhrāṃś ca puṇḍrāṃś ca colān pāṇḍyān sakeralān
ayomukhaś ca gantavyaḥ parvato dhātumaṇḍitaḥ', null, 4040013),
('ramayana-4-40-14', 14, 'Kishkindha Kanda, Sarga 40, Verse 14', 'विचित्रशिखरः श्रीमांश्चित्रपुष्पितकाननः।
सचन्दनवनोद्देशो मार्गितव्यो महागिरिः॥', 'vicitraśikharaḥ śrīmāṃś citrapuṣpitakānanaḥ
sacandanavanoddeśo mārgitavyo mahāgiriḥ', null, 4040014),
('ramayana-4-40-15', 15, 'Kishkindha Kanda, Sarga 40, Verse 15', 'ततस्तामापगां दिव्यां प्रसन्नसलिलां शिवाम्।
तत्र द्रक्ष्यथ कावेरीं विहृतामप्सरोगणैः॥', 'tatas tām āpagāṃ divyāṃ prasannasalilāṃ śivām
tatra drakṣyatha kāverīṃ vihṛtām apsarogaṇaiḥ', null, 4040015),
('ramayana-4-40-16', 16, 'Kishkindha Kanda, Sarga 40, Verse 16', 'तस्यासीनं नगस्याग्रे मलयस्य महौजसं।
द्रक्ष्यथादित्यसंकाशमगस्त्यमृषिसत्तमम्॥', 'tasyāsīnaṃ nagasyāgre malayasya mahaujasaṃ
drakṣyathādityasaṃkāśam agastyam ṛṣisattamam', null, 4040016),
('ramayana-4-40-17', 17, 'Kishkindha Kanda, Sarga 40, Verse 17', 'ततस्तेनाभ्यनुज्ञाताः प्रसन्नेन महात्मना।
ताम्रपर्णीं ग्राहजुष्टां तरिष्यथ महानदीम्॥', 'tatas tenābhyanujñātāḥ prasannena mahātmanā
tāmraparṇīṃ grāhajuṣṭāṃ tariṣyatha mahānadīm', null, 4040017),
('ramayana-4-40-18', 18, 'Kishkindha Kanda, Sarga 40, Verse 18', 'सा चन्दनवनैर्दिव्यैः प्रच्छन्ना द्वीप शालिनी।
कान्तेव युवतिः कान्तं समुद्रमवगाहते॥', 'sā candanavanair divyaiḥ pracchannā dvīpa śālinī
kānteva yuvatiḥ kāntaṃ samudram avagāhate', null, 4040018),
('ramayana-4-40-19', 19, 'Kishkindha Kanda, Sarga 40, Verse 19', 'ततो हेममयं दिव्यं मुक्तामणिविभूषितम्।
युक्तं कवाटं पाण्ड्यानां गता द्रक्ष्यथ वानराः॥', 'tato hemamayaṃ divyaṃ muktāmaṇivibhūṣitam
yuktaṃ kavāṭaṃ pāṇḍyānāṃ gatā drakṣyatha vānarāḥ', null, 4040019),
('ramayana-4-40-20', 20, 'Kishkindha Kanda, Sarga 40, Verse 20', 'ततः समुद्रमासाद्य संप्रधार्यार्थनिश्चयम्।
अगस्त्येनान्तरे तत्र सागरे विनिवेशितः॥', 'tataḥ samudram āsādya saṃpradhāryārthaniścayam
agastyenāntare tatra sāgare viniveśitaḥ', null, 4040020),
('ramayana-4-40-21', 21, 'Kishkindha Kanda, Sarga 40, Verse 21', 'चित्रनानानगः श्रीमान्महेन्द्रः पर्वतोत्तमः।
जातरूपमयः श्रीमानवगाढो महार्णवम्॥', 'citranānānagaḥ śrīmān mahendraḥ parvatottamaḥ
jātarūpamayaḥ śrīmān avagāḍho mahārṇavam', null, 4040021),
('ramayana-4-40-22', 22, 'Kishkindha Kanda, Sarga 40, Verse 22', 'नानाविधैर्नगैः फुल्लैर्लताभिश्चोपशोभितम्।
देवर्षियक्षप्रवरैरप्सरोभिश्च सेवितम्॥', 'nānāvidhair nagaiḥ phullair latābhiś copaśobhitam
devarṣiyakṣapravarair apsarobhiś ca sevitam', null, 4040022),
('ramayana-4-40-23', 23, 'Kishkindha Kanda, Sarga 40, Verse 23', 'सिद्धचारणसंघैश्च प्रकीर्णं सुमनोहरम्।
तमुपैति सहस्राक्षः सदा पर्वसु पर्वसु॥', 'siddhacāraṇasaṃghaiś ca prakīrṇaṃ sumanoharam
tam upaiti sahasrākṣaḥ sadā parvasu parvasu', null, 4040023),
('ramayana-4-40-24', 24, 'Kishkindha Kanda, Sarga 40, Verse 24', 'द्वीपस्तस्यापरे पारे शतयोजनमायतः।
अगम्यो मानुषैर्दीप्तस्तं मार्गध्वं समन्ततः।
तत्र सर्वात्मना सीता मार्गितव्या विशेषतः॥', 'dvīpas tasyāpare pāre śatayojanam āyataḥ
agamyo mānuṣair dīptas taṃ mārgadhvaṃ samantataḥ
tatra sarvātmanā sītā mārgitavyā viśeṣataḥ', null, 4040024),
('ramayana-4-40-25', 25, 'Kishkindha Kanda, Sarga 40, Verse 25', 'स हि देशस्तु वध्यस्य रावणस्य दुरात्मनः।
राक्षसाधिपतेर्वासः सहस्राक्षसमद्युतेः॥', 'sa hi deśas tu vadhyasya rāvaṇasya durātmanaḥ
rākṣasādhipater vāsaḥ sahasrākṣasamadyuteḥ', null, 4040025),
('ramayana-4-40-26', 26, 'Kishkindha Kanda, Sarga 40, Verse 26', 'दक्षिणस्य समुद्रस्य मध्ये तस्य तु राक्षसी।
अङ्गारकेति विख्याता छायामाक्षिप्य भोजिनी॥', 'dakṣiṇasya samudrasya madhye tasya tu rākṣasī
aṅgāraketi vikhyātā chāyām ākṣipya bhojinī', null, 4040026),
('ramayana-4-40-27', 27, 'Kishkindha Kanda, Sarga 40, Verse 27', 'तमतिक्रम्य लक्ष्मीवान्समुद्रे शतयोजने।
गिरिः पुष्पितको नाम सिद्धचारणसेवितः॥', 'tam atikramya lakṣmīvān samudre śatayojane
giriḥ puṣpitako nāma siddhacāraṇasevitaḥ', null, 4040027),
('ramayana-4-40-28', 28, 'Kishkindha Kanda, Sarga 40, Verse 28', 'चन्द्रसूर्यांशुसंकाशः सागराम्बुसमावृतः।
भ्राजते विपुलैः शृङ्गैरम्बरं विलिखन्निव॥', 'candrasūryāṃśusaṃkāśaḥ sāgarāmbusamāvṛtaḥ
bhrājate vipulaiḥ śṛṅgair ambaraṃ vilikhann iva', null, 4040028),
('ramayana-4-40-29', 29, 'Kishkindha Kanda, Sarga 40, Verse 29', 'तस्यैकं काञ्चनं शृङ्गं सेवते यं दिवाकरः।
श्वेतं राजतमेकं च सेवते यं निशाकरः॥', 'tasyaikaṃ kāñcanaṃ śṛṅgaṃ sevate yaṃ divākaraḥ
śvetaṃ rājatam ekaṃ ca sevate yaṃ niśākaraḥ', null, 4040029),
('ramayana-4-40-30', 30, 'Kishkindha Kanda, Sarga 40, Verse 30', 'न तं कृतघ्नाः पश्यन्ति न नृशंसा न नास्तिकाः।
प्रणम्य शिरसा शैलं तं विमार्गत वानराः॥', 'na taṃ kṛtaghnāḥ paśyanti na nṛśaṃsā na nāstikāḥ
praṇamya śirasā śailaṃ taṃ vimārgata vānarāḥ', null, 4040030),
('ramayana-4-40-31', 31, 'Kishkindha Kanda, Sarga 40, Verse 31', 'तमतिक्रम्य दुर्धर्षाः सूर्यवान्नाम पर्वतः।
अध्वना दुर्विगाहेन योजनानि चतुर्दश॥', 'tam atikramya durdharṣāḥ sūryavān nāma parvataḥ
adhvanā durvigāhena yojanāni caturdaśa', null, 4040031),
('ramayana-4-40-32', 32, 'Kishkindha Kanda, Sarga 40, Verse 32', 'ततस्तमप्यतिक्रम्य वैद्युतो नाम पर्वतः।
सर्वकामफलैर्वृक्षैः सर्वकालमनोहरैः॥', 'tatas tam apy atikramya vaidyuto nāma parvataḥ
sarvakāmaphalair vṛkṣaiḥ sarvakālamanoharaiḥ', null, 4040032),
('ramayana-4-40-33', 33, 'Kishkindha Kanda, Sarga 40, Verse 33', 'तत्र भुक्त्वा वरार्हाणि मूलानि च फलानि च।
मधूनि पीत्वा मुख्यानि परं गच्छत वानराः॥', 'tatra bhuktvā varārhāṇi mūlāni ca phalāni ca
madhūni pītvā mukhyāni paraṃ gacchata vānarāḥ', null, 4040033),
('ramayana-4-40-34', 34, 'Kishkindha Kanda, Sarga 40, Verse 34', 'तत्र नेत्रमनःकान्तः कुञ्जरो नाम पर्वतः।
अगस्त्यभवनं यत्र निर्मितं विश्वकर्मणा॥', 'tatra netramanaḥkāntaḥ kuñjaro nāma parvataḥ
agastyabhavanaṃ yatra nirmitaṃ viśvakarmaṇā', null, 4040034),
('ramayana-4-40-35', 35, 'Kishkindha Kanda, Sarga 40, Verse 35', 'तत्र योजनविस्तारमुच्छ्रितं दशयोजनम्।
शरणं काञ्चनं दिव्यं नानारत्नविभूषितम्॥', 'tatra yojanavistāram ucchritaṃ daśayojanam
śaraṇaṃ kāñcanaṃ divyaṃ nānāratnavibhūṣitam', null, 4040035),
('ramayana-4-40-36', 36, 'Kishkindha Kanda, Sarga 40, Verse 36', 'तत्र भोगवती नाम सर्पाणामालयः पुरी।
विशालरथ्या दुर्धर्षा सर्वतः परिरक्षिता।
रक्षिता पन्नगैर्घोरैस्तीक्ष्णदंष्ट्रैर्महाविषैः॥', 'tatra bhogavatī nāma sarpāṇām ālayaḥ purī
viśālarathyā durdharṣā sarvataḥ parirakṣitā
rakṣitā pannagair ghorais tīkṣṇadaṃṣṭrair mahāviṣaiḥ', null, 4040036),
('ramayana-4-40-37', 37, 'Kishkindha Kanda, Sarga 40, Verse 37', 'सर्पराजो महाघोरो यस्यां वसति वासुकिः।
निर्याय मार्गितव्या च सा च भोगवती पुरी॥', 'sarparājo mahāghoro yasyāṃ vasati vāsukiḥ
niryāya mārgitavyā ca sā ca bhogavatī purī', null, 4040037),
('ramayana-4-40-38', 38, 'Kishkindha Kanda, Sarga 40, Verse 38', 'तं च देशमतिक्रम्य महानृषभसंस्थितः।
सर्वरत्नमयः श्रीमानृषभो नाम पर्वतः॥', 'taṃ ca deśam atikramya mahān ṛṣabhasaṃsthitaḥ
sarvaratnamayaḥ śrīmān ṛṣabho nāma parvataḥ', null, 4040038),
('ramayana-4-40-39', 39, 'Kishkindha Kanda, Sarga 40, Verse 39', 'गोशीर्षकं पद्मकं च हरिश्यामं च चन्दनम्।
दिव्यमुत्पद्यते यत्र तच्चैवाग्निसमप्रभम्॥', 'gośīrṣakaṃ padmakaṃ ca hariśyāmaṃ ca candanam
divyam utpadyate yatra tac caivāgnisamaprabham', null, 4040039),
('ramayana-4-40-40', 40, 'Kishkindha Kanda, Sarga 40, Verse 40', 'न तु तच्चन्दनं दृष्ट्वा स्प्रष्टव्यं च कदा चन।
रोहिता नाम गन्धर्वा घोरा रक्षन्ति तद्वनम्॥', 'na tu tac candanaṃ dṛṣṭvā spraṣṭavyaṃ ca kadā cana
rohitā nāma gandharvā ghorā rakṣanti tad vanam', null, 4040040),
('ramayana-4-40-41', 41, 'Kishkindha Kanda, Sarga 40, Verse 41', 'तत्र गन्धर्वपतयः पञ्चसूर्यसमप्रभाः।
शैलूषो ग्रामणीर्भिक्षुः शुभ्रो बभ्रुस्तथैव च॥', 'tatra gandharvapatayaḥ pañcasūryasamaprabhāḥ
śailūṣo grāmaṇīr bhikṣuḥ śubhro babhrus tathaiva ca', null, 4040041),
('ramayana-4-40-42', 42, 'Kishkindha Kanda, Sarga 40, Verse 42', 'अन्ते पृथिव्या दुर्धर्षास्तत्र स्वर्गजितः स्थिताः।
ततः परं न वः सेव्यः पितृलोकः सुदारुणः।
राजधानी यमस्यैषा कष्टेन तमसावृता॥', 'ante pṛthivyā durdharṣās tatra svargajitaḥ sthitāḥ
tataḥ paraṃ na vaḥ sevyaḥ pitṛlokaḥ sudāruṇaḥ
rājadhānī yamasyaiṣā kaṣṭena tamasāvṛtā', null, 4040042),
('ramayana-4-40-43', 43, 'Kishkindha Kanda, Sarga 40, Verse 43', 'एतावदेव युष्माभिर्वीरा वानरपुंगवाः।
शक्यं विचेतुं गन्तुं वा नातो गतिमतां गतिः॥', 'etāvad eva yuṣmābhir vīrā vānarapuṃgavāḥ
śakyaṃ vicetuṃ gantuṃ vā nāto gatimatāṃ gatiḥ', null, 4040043),
('ramayana-4-40-44', 44, 'Kishkindha Kanda, Sarga 40, Verse 44', 'सर्वमेतत्समालोक्य यच्चान्यदपि दृश्यते।
गतिं विदित्वा वैदेह्याः संनिवर्तितमर्हथ॥', 'sarvam etat samālokya yac cānyad api dṛśyate
gatiṃ viditvā vaidehyāḥ saṃnivartitam arhatha', null, 4040044),
('ramayana-4-40-45', 45, 'Kishkindha Kanda, Sarga 40, Verse 45', 'यस्तु मासान्निवृत्तोऽग्रे दृष्टा सीतेति वक्ष्यति।
मत्तुल्यविभवो भोगैः सुखं स विहरिष्यति॥', 'yas tu māsān nivṛtto ''gre dṛṣṭā sīteti vakṣyati
mattulyavibhavo bhogaiḥ sukhaṃ sa vihariṣyati', null, 4040045),
('ramayana-4-40-46', 46, 'Kishkindha Kanda, Sarga 40, Verse 46', 'ततः प्रियतरो नास्ति मम प्राणाद्विशेषतः।
कृतापराधो बहुशो मम बन्धुर्भविष्यति॥', 'tataḥ priyataro nāsti mama prāṇād viśeṣataḥ
kṛtāparādho bahuśo mama bandhur bhaviṣyati', null, 4040046),
('ramayana-4-40-47', 47, 'Kishkindha Kanda, Sarga 40, Verse 47', 'अमितबलपराक्रमा भवन्तो विपुलगुणेषु कुलेषु च प्रसूताः।
मनुजपतिसुतां यथा लभध्वं तदधिगुणं पुरुषार्थमारभध्वम्॥', 'amitabalaparākramā bhavanto vipulaguṇeṣu kuleṣu ca prasūtāḥ
manujapatisutāṃ yathā labhadhvaṃ tad adhiguṇaṃ puruṣārtham ārabhadhvam', null, 4040047)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 41 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-41-1', 1, 'Kishkindha Kanda, Sarga 41, Verse 1', 'ततः प्रस्थाप्य सुग्रीवस्तान्हरीन्दक्षिणां दिशम्।
बुद्धिविक्रमसंपन्नान्वायुवेगसमाञ्जवे॥', 'tataḥ prasthāpya sugrīvas tān harīn dakṣiṇāṃ diśam
buddhivikramasaṃpannān vāyuvegasamāñjave', null, 4041001),
('ramayana-4-41-2', 2, 'Kishkindha Kanda, Sarga 41, Verse 2', 'अथाहूय महातेजाः सुषेणं नाम यूथपम्।
तारायाः पितरं राजा श्वशुरभीमविक्रमम्॥', 'athāhūya mahātejāḥ suṣeṇaṃ nāma yūthapam
tārāyāḥ pitaraṃ rājā śvaśurabhīmavikramam', null, 4041002),
('ramayana-4-41-3', 3, 'Kishkindha Kanda, Sarga 41, Verse 3', 'अब्रवीत्प्राञ्जलिर्वाक्यमभिगम्य प्रणम्य च।
साहाय्यं कुरु रामस्य कृत्येऽस्मिन्समुपस्थिते॥', 'abravīt prāñjalir vākyam abhigamya praṇamya ca
sāhāyyaṃ kuru rāmasya kṛtye ''smin samupasthite', null, 4041003),
('ramayana-4-41-4', 4, 'Kishkindha Kanda, Sarga 41, Verse 4', 'वृतः शतसहस्रेण वानराणां तरस्विनाम्।
अभिगच्छ दिशं सौम्य पश्चिमां वारुणीं प्रभो॥', 'vṛtaḥ śatasahasreṇa vānarāṇāṃ tarasvinām
abhigaccha diśaṃ saumya paścimāṃ vāruṇīṃ prabho', null, 4041004),
('ramayana-4-41-5', 5, 'Kishkindha Kanda, Sarga 41, Verse 5', 'सुराष्ट्रान्सह बाह्लीकाञ्शूराभीरांस्तथैव च।
स्फीताञ्जनपदान्रम्यान्विपुलानि पुराणि च॥', 'surāṣṭrān saha bāhlīkāñ śūrābhīrāṃs tathaiva ca
sphītāñjanapadān ramyān vipulāni purāṇi ca', null, 4041005),
('ramayana-4-41-6', 6, 'Kishkindha Kanda, Sarga 41, Verse 6', 'पुंनागगहनं कुक्षिं बहुलोद्दालकाकुलम्।
तथा केतकषण्डांश्च मार्गध्वं हरियूथपाः॥', 'puṃnāgagahanaṃ kukṣiṃ bahuloddālakākulam
tathā ketakaṣaṇḍāṃś ca mārgadhvaṃ hariyūthapāḥ', null, 4041006),
('ramayana-4-41-7', 7, 'Kishkindha Kanda, Sarga 41, Verse 7', 'प्रत्यक्स्रोतोगमाश्चैव नद्यः शीतजलाः शिवाः।
तापसानामरण्यानि कान्तारा गिरयश्च ये॥', 'pratyak srotogamāś caiva nadyaḥ śītajalāḥ śivāḥ
tāpasānām araṇyāni kāntārā girayaś ca ye', null, 4041007),
('ramayana-4-41-8', 8, 'Kishkindha Kanda, Sarga 41, Verse 8', 'गिरिजालावृतां दुर्गां मार्गित्वा पश्चिमां दिशम्।
ततः पश्चिममासाद्य समुद्रं द्रष्टुमर्हथ।
तिमि नक्रायुत जलमक्षोभ्यमथ वानरः॥', 'girijālāvṛtāṃ durgāṃ mārgitvā paścimāṃ diśam
tataḥ paścimam āsādya samudraṃ draṣṭum arhatha
timi nakrāyuta jalam akṣobhyam atha vānaraḥ', null, 4041008),
('ramayana-4-41-9', 9, 'Kishkindha Kanda, Sarga 41, Verse 9', 'ततः केतकषण्डेषु तमालगहनेषु च।
कपयो विहरिष्यन्ति नारिकेलवनेषु च॥', 'tataḥ ketakaṣaṇḍeṣu tamālagahaneṣu ca
kapayo vihariṣyanti nārikelavaneṣu ca', null, 4041009),
('ramayana-4-41-10', 10, 'Kishkindha Kanda, Sarga 41, Verse 10', 'तत्र सीतां च मार्गध्वं निलयं रावणस्य च।
मरीचिपत्तनं चैव रम्यं चैव जटीपुरम्॥', 'tatra sītāṃ ca mārgadhvaṃ nilayaṃ rāvaṇasya ca
marīcipattanaṃ caiva ramyaṃ caiva jaṭīpuram', null, 4041010),
('ramayana-4-41-11', 11, 'Kishkindha Kanda, Sarga 41, Verse 11', 'अवन्तीमङ्गलोपां च तथा चालक्षितं वनम्।
राष्ट्राणि च विशालानि पत्तनानि ततस्ततः॥', 'avantīm aṅgalopāṃ ca tathā cālakṣitaṃ vanam
rāṣṭrāṇi ca viśālāni pattanāni tatas tataḥ', null, 4041011),
('ramayana-4-41-12', 12, 'Kishkindha Kanda, Sarga 41, Verse 12', 'सिन्धुसागरयोश्चैव संगमे तत्र पर्वतः।
महान्हेमगिरिर्नाम शतशृङ्गो महाद्रुमः॥', 'sindhusāgarayoś caiva saṃgame tatra parvataḥ
mahān hemagirir nāma śataśṛṅgo mahādrumaḥ', null, 4041012),
('ramayana-4-41-13', 13, 'Kishkindha Kanda, Sarga 41, Verse 13', 'तस्य प्रस्थेषु रम्येषु सिंहाः पक्षगमाः स्थिताः।
तिमिमत्स्यगजांश्चैव नीडान्यारोपयन्ति ते॥', 'tasya prastheṣu ramyeṣu siṃhāḥ pakṣagamāḥ sthitāḥ
timimatsyagajāṃś caiva nīḍāny āropayanti te', null, 4041013),
('ramayana-4-41-14', 14, 'Kishkindha Kanda, Sarga 41, Verse 14', 'तानि नीडानि सिंहानां गिरिशृङ्गगताश्च ये।
दृप्तास्तृप्ताश्च मातङ्गास्तोयदस्वननिःस्वनाः।
विचरन्ति विशालेऽस्मिंस्तोयपूर्णे समन्ततः॥', 'tāni nīḍāni siṃhānāṃ giriśṛṅgagatāś ca ye
dṛptās tṛptāś ca mātaṅgās toyadasvananiḥsvanāḥ
vicaranti viśāle ''smiṃs toyapūrṇe samantataḥ', null, 4041014),
('ramayana-4-41-15', 15, 'Kishkindha Kanda, Sarga 41, Verse 15', 'तस्य शृङ्गं दिवस्पर्शं काञ्चनं चित्रपादपम्।
सर्वमाशु विचेतव्यं कपिभिः कामरूपिभिः॥', 'tasya śṛṅgaṃ divasparśaṃ kāñcanaṃ citrapādapam
sarvam āśu vicetavyaṃ kapibhiḥ kāmarūpibhiḥ', null, 4041015),
('ramayana-4-41-16', 16, 'Kishkindha Kanda, Sarga 41, Verse 16', 'कोटिं तत्र समुद्रे तु काञ्चनीं शतयोजनम्।
दुर्दर्शां परियात्रस्य गता द्रक्ष्यथ वानराः॥', 'koṭiṃ tatra samudre tu kāñcanīṃ śatayojanam
durdarśāṃ pariyātrasya gatā drakṣyatha vānarāḥ', null, 4041016),
('ramayana-4-41-17', 17, 'Kishkindha Kanda, Sarga 41, Verse 17', 'कोट्यस्तत्र चतुर्विंशद्गन्धर्वाणां तरस्विनाम्।
वसन्त्यग्निनिकाशानां घोराणां कामरूपिणाम्॥', 'koṭyas tatra caturviṃśad gandharvāṇāṃ tarasvinām
vasanty agninikāśānāṃ ghorāṇāṃ kāmarūpiṇām', null, 4041017),
('ramayana-4-41-18', 18, 'Kishkindha Kanda, Sarga 41, Verse 18', 'नात्यासादयितव्यास्ते वानरैर्भीमविक्रमैः।
नादेयं च फलं तस्माद्देशात्किं चित्प्लवंगमैः॥', 'nātyāsādayitavyās te vānarair bhīmavikramaiḥ
nādeyaṃ ca phalaṃ tasmād deśāt kiṃ cit plavaṃgamaiḥ', null, 4041018),
('ramayana-4-41-19', 19, 'Kishkindha Kanda, Sarga 41, Verse 19', 'दुरासदा हि ते वीराः सत्त्ववन्तो महाबलाः।
फलमूलानि ते तत्र रक्षन्ते भीमविक्रमाः॥', 'durāsadā hi te vīrāḥ sattvavanto mahābalāḥ
phalamūlāni te tatra rakṣante bhīmavikramāḥ', null, 4041019),
('ramayana-4-41-20', 20, 'Kishkindha Kanda, Sarga 41, Verse 20', 'तत्र यत्नश्च कर्तव्यो मार्गितव्या च जानकी।
न हि तेभ्यो भयं किं चित्कपित्वमनुवर्तताम्॥', 'tatra yatnaś ca kartavyo mārgitavyā ca jānakī
na hi tebhyo bhayaṃ kiṃ cit kapitvam anuvartatām', null, 4041020),
('ramayana-4-41-21', 21, 'Kishkindha Kanda, Sarga 41, Verse 21', 'चतुर्भागे समुद्रस्य चक्रवान्नाम पर्वतः।
तत्र चक्रं सहस्रारं निर्मितं विश्वकर्मणा॥', 'caturbhāge samudrasya cakravān nāma parvataḥ
tatra cakraṃ sahasrāraṃ nirmitaṃ viśvakarmaṇā', null, 4041021),
('ramayana-4-41-22', 22, 'Kishkindha Kanda, Sarga 41, Verse 22', 'तत्र पञ्चजनं हत्वा हयग्रीवं च दानवम्।
आजहार ततश्चक्रं शङ्खं च पुरुषोत्तमः॥', 'tatra pañcajanaṃ hatvā hayagrīvaṃ ca dānavam
ājahāra tataś cakraṃ śaṅkhaṃ ca puruṣottamaḥ', null, 4041022),
('ramayana-4-41-23', 23, 'Kishkindha Kanda, Sarga 41, Verse 23', 'तस्य सानुषु चित्रेषु विशालासु गुहासु च।
रावणः सह वैदेह्या मार्गितव्यस्ततस्ततः॥', 'tasya sānuṣu citreṣu viśālāsu guhāsu ca
rāvaṇaḥ saha vaidehyā mārgitavyas tatas tataḥ', null, 4041023),
('ramayana-4-41-24', 24, 'Kishkindha Kanda, Sarga 41, Verse 24', 'योजनानि चतुःषष्टिर्वराहो नाम पर्वतः।
सुवर्णशृङ्गः सुश्रीमानगाधे वरुणालये॥', 'yojanāni catuḥṣaṣṭir varāho nāma parvataḥ
suvarṇaśṛṅgaḥ suśrīmān agādhe varuṇālaye', null, 4041024),
('ramayana-4-41-25', 25, 'Kishkindha Kanda, Sarga 41, Verse 25', 'तत्र प्राग्ज्योतिषं नाम जातरूपमयं पुरम्।
यस्मिन्वस्ति दुष्टात्मा नरको नाम गुहासु च॥', 'tatra prāgjyotiṣaṃ nāma jātarūpamayaṃ puram
yasmin vasti duṣṭātmā narako nāma guhāsu ca', null, 4041025),
('ramayana-4-41-26', 26, 'Kishkindha Kanda, Sarga 41, Verse 26', 'तस्य सानुषु चित्रेषु विशालासु गुहासु च।
रावणः सह वैदेह्या मार्गितव्यस्ततस्ततः॥', 'tasya sānuṣu citreṣu viśālāsu guhāsu ca
rāvaṇaḥ saha vaidehyā mārgitavyas tatas tataḥ', null, 4041026),
('ramayana-4-41-27', 27, 'Kishkindha Kanda, Sarga 41, Verse 27', 'तमतिक्रम्य शैलेन्द्रं काञ्चनान्तरनिर्दरः।
पर्वतः सर्वसौवर्णो धारा प्रस्रवणायुतः॥', 'tam atikramya śailendraṃ kāñcanāntaranirdaraḥ
parvataḥ sarvasauvarṇo dhārā prasravaṇāyutaḥ', null, 4041027),
('ramayana-4-41-28', 28, 'Kishkindha Kanda, Sarga 41, Verse 28', 'तं गजाश्च वराहाश्च सिंहा व्याघ्राश्च सर्वतः।
अभिगर्जन्ति सततं तेन शब्देन दर्पिताः॥', 'taṃ gajāś ca varāhāś ca siṃhā vyāghrāś ca sarvataḥ
abhigarjanti satataṃ tena śabdena darpitāḥ', null, 4041028),
('ramayana-4-41-29', 29, 'Kishkindha Kanda, Sarga 41, Verse 29', 'तस्मिन्हरिहयः श्रीमान्महेन्द्रः पाकशासनः।
अभिषिक्तः सुरै राजा मेघवान्नाम पर्वतः॥', 'tasmin harihayaḥ śrīmān mahendraḥ pākaśāsanaḥ
abhiṣiktaḥ surai rājā meghavān nāma parvataḥ', null, 4041029),
('ramayana-4-41-30', 30, 'Kishkindha Kanda, Sarga 41, Verse 30', 'तमतिक्रम्य शैलेन्द्रं महेन्द्रपरिपालितम्।
षष्टिं गिरिसहस्राणि काञ्चनानि गमिष्यथ॥', 'tam atikramya śailendraṃ mahendraparipālitam
ṣaṣṭiṃ girisahasrāṇi kāñcanāni gamiṣyatha', null, 4041030),
('ramayana-4-41-31', 31, 'Kishkindha Kanda, Sarga 41, Verse 31', 'तरुणादित्यवर्णानि भ्राजमानानि सर्वतः।
जातरूपमयैर्वृक्षैः शोभितानि सुपुष्पितैः॥', 'taruṇādityavarṇāni bhrājamānāni sarvataḥ
jātarūpamayair vṛkṣaiḥ śobhitāni supuṣpitaiḥ', null, 4041031),
('ramayana-4-41-32', 32, 'Kishkindha Kanda, Sarga 41, Verse 32', 'तेषां मध्ये स्थितो राजा मेरुरुत्तमपर्वतः।
आदित्येन प्रसन्नेन शैलो दत्तवरः पुरा॥', 'teṣāṃ madhye sthito rājā merur uttamaparvataḥ
ādityena prasannena śailo dattavaraḥ purā', null, 4041032),
('ramayana-4-41-33', 33, 'Kishkindha Kanda, Sarga 41, Verse 33', 'तेनैवमुक्तः शैलेन्द्रः सर्व एव त्वदाश्रयाः।
मत्प्रसादाद्भविष्यन्ति दिवारात्रौ च काञ्चनाः॥', 'tenaivam uktaḥ śailendraḥ sarva eva tvadāśrayāḥ
matprasādād bhaviṣyanti divārātrau ca kāñcanāḥ', null, 4041033),
('ramayana-4-41-34', 34, 'Kishkindha Kanda, Sarga 41, Verse 34', 'त्वयि ये चापि वत्स्यन्ति देवगन्धर्वदानवाः।
ते भविष्यन्ति रक्ताश्च प्रभया काञ्चनप्रभाः॥', 'tvayi ye cāpi vatsyanti devagandharvadānavāḥ
te bhaviṣyanti raktāś ca prabhayā kāñcanaprabhāḥ', null, 4041034),
('ramayana-4-41-35', 35, 'Kishkindha Kanda, Sarga 41, Verse 35', 'आदित्या वसवो रुद्रा मरुतश्च दिवौकसः।
आगम्य पश्चिमां संध्यां मेरुमुत्तमपर्वतम्॥', 'ādityā vasavo rudrā marutaś ca divaukasaḥ
āgamya paścimāṃ saṃdhyāṃ merum uttamaparvatam', null, 4041035),
('ramayana-4-41-36', 36, 'Kishkindha Kanda, Sarga 41, Verse 36', 'आदित्यमुपतिष्ठन्ति तैश्च सूर्योऽभिपूजितः।
अदृश्यः सर्वभूतानामस्तं गच्छति पर्वतम्॥', 'ādityam upatiṣṭhanti taiś ca sūryo ''bhipūjitaḥ
adṛśyaḥ sarvabhūtānām astaṃ gacchati parvatam', null, 4041036),
('ramayana-4-41-37', 37, 'Kishkindha Kanda, Sarga 41, Verse 37', 'योजनानां सहस्राणि दशतानि दिवाकरः।
मुहूर्तार्धेन तं शीघ्रमभियाति शिलोच्चयम्॥', 'yojanānāṃ sahasrāṇi daśatāni divākaraḥ
muhūrtārdhena taṃ śīghram abhiyāti śiloccayam', null, 4041037),
('ramayana-4-41-38', 38, 'Kishkindha Kanda, Sarga 41, Verse 38', 'शृङ्गे तस्य महद्दिव्यं भवनं सूर्यसंनिभम्।
प्रासादगुणसंबाधं विहितं विश्वकर्मणा॥', 'śṛṅge tasya mahad divyaṃ bhavanaṃ sūryasaṃnibham
prāsādaguṇasaṃbādhaṃ vihitaṃ viśvakarmaṇā', null, 4041038),
('ramayana-4-41-39', 39, 'Kishkindha Kanda, Sarga 41, Verse 39', 'शोभितं तरुभिश्चित्रैर्नानापक्षिसमाकुलैः।
निकेतं पाशहस्तस्य वरुणस्य महात्मनः॥', 'śobhitaṃ tarubhiś citrair nānāpakṣisamākulaiḥ
niketaṃ pāśahastasya varuṇasya mahātmanaḥ', null, 4041039),
('ramayana-4-41-40', 40, 'Kishkindha Kanda, Sarga 41, Verse 40', 'अन्तरा मेरुमस्तं च तालो दशशिरा महान्।
जातरूपमयः श्रीमान्भ्राजते चित्रवेदिकः॥', 'antarā merum astaṃ ca tālo daśaśirā mahān
jātarūpamayaḥ śrīmān bhrājate citravedikaḥ', null, 4041040),
('ramayana-4-41-41', 41, 'Kishkindha Kanda, Sarga 41, Verse 41', 'तेषु सर्वेषु दुर्गेषु सरःसु च सरित्सु च।
रावणः सह वैदेह्या मार्गितव्यस्ततस्ततः॥', 'teṣu sarveṣu durgeṣu saraḥsu ca saritsu ca
rāvaṇaḥ saha vaidehyā mārgitavyas tatas tataḥ', null, 4041041),
('ramayana-4-41-42', 42, 'Kishkindha Kanda, Sarga 41, Verse 42', 'यत्र तिष्ठति धर्मात्मा तपसा स्वेन भावितः।
मेरुसावर्णिरित्येव ख्यातो वै ब्रह्मणा समः॥', 'yatra tiṣṭhati dharmātmā tapasā svena bhāvitaḥ
merusāvarṇir ity eva khyāto vai brahmaṇā samaḥ', null, 4041042),
('ramayana-4-41-43', 43, 'Kishkindha Kanda, Sarga 41, Verse 43', 'प्रष्टव्यो मेरुसावर्णिर्महर्षिः सूर्यसंनिभः।
प्रणम्य शिरसा भूमौ प्रवृत्तिं मैथिलीं प्रति॥', 'praṣṭavyo merusāvarṇir maharṣiḥ sūryasaṃnibhaḥ
praṇamya śirasā bhūmau pravṛttiṃ maithilīṃ prati', null, 4041043),
('ramayana-4-41-44', 44, 'Kishkindha Kanda, Sarga 41, Verse 44', 'एतावज्जीवलोकस्य भास्करो रजनीक्षये।
कृत्वा वितिमिरं सर्वमस्तं गच्छति पर्वतम्॥', 'etāvaj jīvalokasya bhāskaro rajanīkṣaye
kṛtvā vitimiraṃ sarvam astaṃ gacchati parvatam', null, 4041044),
('ramayana-4-41-45', 45, 'Kishkindha Kanda, Sarga 41, Verse 45', 'एतावद्वानरैः शक्यं गन्तुं वानरपुंगवाः।
अभास्करममर्यादं न जानीमस्ततः परम्॥', 'etāvad vānaraiḥ śakyaṃ gantuṃ vānarapuṃgavāḥ
abhāskaram amaryādaṃ na jānīmas tataḥ param', null, 4041045),
('ramayana-4-41-46', 46, 'Kishkindha Kanda, Sarga 41, Verse 46', 'अधिगम्य तु वैदेहीं निलयं रावणस्य च।
अस्तं पर्वतमासाद्य पूर्णे मासे निवर्तत॥', 'adhigamya tu vaidehīṃ nilayaṃ rāvaṇasya ca
astaṃ parvatam āsādya pūrṇe māse nivartata', null, 4041046),
('ramayana-4-41-47', 47, 'Kishkindha Kanda, Sarga 41, Verse 47', 'ऊर्ध्वं मासान्न वस्तव्यं वसन्वध्यो भवेन्मम।
सहैव शूरो युष्माभिः श्वशुरो मे गमिष्यति॥', 'ūrdhvaṃ māsān na vastavyaṃ vasan vadhyo bhaven mama
sahaiva śūro yuṣmābhiḥ śvaśuro me gamiṣyati', null, 4041047),
('ramayana-4-41-48', 48, 'Kishkindha Kanda, Sarga 41, Verse 48', 'श्रोतव्यं सर्वमेतस्य भवद्भिर्दिष्ट कारिभिः।
गुरुरेष महाबाहुः श्वशुरो मे महाबलः॥', 'śrotavyaṃ sarvam etasya bhavadbhir diṣṭa kāribhiḥ
gurur eṣa mahābāhuḥ śvaśuro me mahābalaḥ', null, 4041048),
('ramayana-4-41-49', 49, 'Kishkindha Kanda, Sarga 41, Verse 49', 'भवन्तश्चापि विक्रान्ताः प्रमाणं सर्वकर्मसु।
प्रमाणमेनं संस्थाप्य पश्यध्वं पश्चिमां दिशम्॥', 'bhavantaś cāpi vikrāntāḥ pramāṇaṃ sarvakarmasu
pramāṇam enaṃ saṃsthāpya paśyadhvaṃ paścimāṃ diśam', null, 4041049),
('ramayana-4-41-50', 50, 'Kishkindha Kanda, Sarga 41, Verse 50', 'दृष्टायां तु नरेन्द्रस्या पत्न्याममिततेजसः।
कृतकृत्या भविष्यामः कृतस्य प्रतिकर्मणा॥', 'dṛṣṭāyāṃ tu narendrasyā patnyām amitatejasaḥ
kṛtakṛtyā bhaviṣyāmaḥ kṛtasya pratikarmaṇā', null, 4041050),
('ramayana-4-41-51', 51, 'Kishkindha Kanda, Sarga 41, Verse 51', 'अतोऽन्यदपि यत्किं चित्कार्यस्यास्य हितं भवेत्।
संप्रधार्य भवद्भिश्च देशकालार्थसंहितम्॥', 'ato ''nyad api yat kiṃ cit kāryasyāsya hitaṃ bhavet
saṃpradhārya bhavadbhiś ca deśakālārthasaṃhitam', null, 4041051),
('ramayana-4-41-52', 52, 'Kishkindha Kanda, Sarga 41, Verse 52', 'ततः सुषेण प्रमुखाः प्लवंगमाः सुग्रीववाक्यं निपुणं निशम्य।
आमन्त्र्य सर्वे प्लवगाधिपं ते जग्मुर्दिशं तां वरुणाभिगुप्ताम्॥', 'tataḥ suṣeṇa pramukhāḥ plavaṃgamāḥ sugrīvavākyaṃ nipuṇaṃ niśamya
āmantrya sarve plavagādhipaṃ te jagmur diśaṃ tāṃ varuṇābhiguptām', null, 4041052)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 42 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-42-1', 1, 'Kishkindha Kanda, Sarga 42, Verse 1', 'ततः संदिश्य सुग्रीवः श्वशुरं पश्चिमां दिशम्।
वीरं शतबलिं नाम वानरं वानरर्षभः॥', 'tataḥ saṃdiśya sugrīvaḥ śvaśuraṃ paścimāṃ diśam
vīraṃ śatabaliṃ nāma vānaraṃ vānararṣabhaḥ', null, 4042001),
('ramayana-4-42-2', 2, 'Kishkindha Kanda, Sarga 42, Verse 2', 'उवाच राजा मन्त्रज्ञः सर्ववानरसंमतम्।
वाक्यमात्महितं चैव रामस्य च हितं तथा॥', 'uvāca rājā mantrajñaḥ sarvavānarasaṃmatam
vākyam ātmahitaṃ caiva rāmasya ca hitaṃ tathā', null, 4042002),
('ramayana-4-42-3', 3, 'Kishkindha Kanda, Sarga 42, Verse 3', 'वृतः शतसहस्रेण त्वद्विधानां वनौकसाम्।
वैवस्वत सुतैः सार्धं प्रतिष्ठस्व स्वमन्त्रिभिः॥', 'vṛtaḥ śatasahasreṇa tvadvidhānāṃ vanaukasām
vaivasvata sutaiḥ sārdhaṃ pratiṣṭhasva svamantribhiḥ', null, 4042003),
('ramayana-4-42-4', 4, 'Kishkindha Kanda, Sarga 42, Verse 4', 'दिशं ह्युदीचीं विक्रान्तां हिमशैलावतंसकाम्।
सर्वतः परिमार्गध्वं रामपत्नीमनिन्दिताम्॥', 'diśaṃ hy udīcīṃ vikrāntāṃ himaśailāvataṃsakām
sarvataḥ parimārgadhvaṃ rāmapatnīm aninditām', null, 4042004),
('ramayana-4-42-5', 5, 'Kishkindha Kanda, Sarga 42, Verse 5', 'अस्मिन्कार्ये विनिवृत्ते कृते दाशरथेः प्रिये।
ऋणान्मुक्ता भविष्यामः कृतार्थार्थविदां वराः॥', 'asmin kārye vinivṛtte kṛte dāśaratheḥ priye
ṛṇān muktā bhaviṣyāmaḥ kṛtārthārthavidāṃ varāḥ', null, 4042005),
('ramayana-4-42-6', 6, 'Kishkindha Kanda, Sarga 42, Verse 6', 'कृतं हि प्रियमस्माकं राघवेण महात्मना।
तस्य चेत्प्रतिकारोऽस्ति सफलं जीवितं भवेत्॥', 'kṛtaṃ hi priyam asmākaṃ rāghaveṇa mahātmanā
tasya cet pratikāro ''sti saphalaṃ jīvitaṃ bhavet', null, 4042006),
('ramayana-4-42-7', 7, 'Kishkindha Kanda, Sarga 42, Verse 7', 'एतां बुद्धिं समास्थाय दृश्यते जानकी यथा।
तथा भवद्भिः कर्तव्यमस्मत्प्रियहितैषिभिः॥', 'etāṃ buddhiṃ samāsthāya dṛśyate jānakī yathā
tathā bhavadbhiḥ kartavyam asmatpriyahitaiṣibhiḥ', null, 4042007),
('ramayana-4-42-8', 8, 'Kishkindha Kanda, Sarga 42, Verse 8', 'अयं हि सर्वभूतानां मान्यस्तु नरसत्तमः।
अस्मासु चागतप्रीती रामः परपुरंजयः॥', 'ayaṃ hi sarvabhūtānāṃ mānyas tu narasattamaḥ
asmāsu cāgataprītī rāmaḥ parapuraṃjayaḥ', null, 4042008),
('ramayana-4-42-9', 9, 'Kishkindha Kanda, Sarga 42, Verse 9', 'इमानि वनदुर्गाणि नद्यः शैलान्तराणि च।
भवन्तः परिमार्गंस्तु बुद्धिविक्रमसंपदा॥', 'imāni vanadurgāṇi nadyaḥ śailāntarāṇi ca
bhavantaḥ parimārgaṃs tu buddhivikramasaṃpadā', null, 4042009),
('ramayana-4-42-10', 10, 'Kishkindha Kanda, Sarga 42, Verse 10', 'तत्र म्लेच्छान्पुलिन्दांश्च शूरसेनांस्तथैव च।
प्रस्थालान्भरतांश्चैव कुरूंश्च सह मद्रकैः॥', 'tatra mlecchān pulindāṃś ca śūrasenāṃs tathaiva ca
prasthālān bharatāṃś caiva kurūṃś ca saha madrakaiḥ', null, 4042010),
('ramayana-4-42-11', 11, 'Kishkindha Kanda, Sarga 42, Verse 11', 'काम्बोजान्यवनांश्चैव शकानारट्टकानपि।
बाह्लीकानृषिकांश्चैव पौरवानथ टङ्कणान्॥', 'kāmbojān yavanāṃś caiva śakān āraṭṭakān api
bāhlīkān ṛṣikāṃś caiva pauravān atha ṭaṅkaṇān', null, 4042011),
('ramayana-4-42-12', 12, 'Kishkindha Kanda, Sarga 42, Verse 12', 'चीनान्परमचीनांश्च नीहारांश्च पुनः पुनः।
अन्विष्य दरदांश्चैव हिमवन्तं विचिन्वथ॥', 'cīnān paramacīnāṃś ca nīhārāṃś ca punaḥ punaḥ
anviṣya daradāṃś caiva himavantaṃ vicinvatha', null, 4042012),
('ramayana-4-42-13', 13, 'Kishkindha Kanda, Sarga 42, Verse 13', 'लोध्रपद्मकषण्डेषु देवदारुवनेषु च।
रावणः सह वैदेह्य मार्गितव्यस्ततस्ततः॥', 'lodhrapadmakaṣaṇḍeṣu devadāruvaneṣu ca
rāvaṇaḥ saha vaidehya mārgitavyas tatas tataḥ', null, 4042013),
('ramayana-4-42-14', 14, 'Kishkindha Kanda, Sarga 42, Verse 14', 'ततः सोमाश्रमं गत्वा देवगन्धर्वसेवितम्।
कालं नाम महासानुं पर्वतं तं गमिष्यथ॥', 'tataḥ somāśramaṃ gatvā devagandharvasevitam
kālaṃ nāma mahāsānuṃ parvataṃ taṃ gamiṣyatha', null, 4042014),
('ramayana-4-42-15', 15, 'Kishkindha Kanda, Sarga 42, Verse 15', 'महत्सु तस्य शृङ्गेषु निर्दरेषु गुहासु च।
विचिनुध्वं महाभागां रामपत्नीं यशस्विनीम्॥', 'mahatsu tasya śṛṅgeṣu nirdareṣu guhāsu ca
vicinudhvaṃ mahābhāgāṃ rāmapatnīṃ yaśasvinīm', null, 4042015),
('ramayana-4-42-16', 16, 'Kishkindha Kanda, Sarga 42, Verse 16', 'तमतिक्रम्य शैलेन्द्रं हेमवर्गं महागिरिम्।
ततः सुदर्शनं नाम पर्वतं गन्तुमर्हथ॥', 'tam atikramya śailendraṃ hemavargaṃ mahāgirim
tataḥ sudarśanaṃ nāma parvataṃ gantum arhatha', null, 4042016),
('ramayana-4-42-17', 17, 'Kishkindha Kanda, Sarga 42, Verse 17', 'तस्य काननषण्डेषु निर्दरेषु गुहासु च।
रावणः सह वैदेह्या मार्गितव्यस्ततस्ततः॥', 'tasya kānanaṣaṇḍeṣu nirdareṣu guhāsu ca
rāvaṇaḥ saha vaidehyā mārgitavyas tatas tataḥ', null, 4042017),
('ramayana-4-42-18', 18, 'Kishkindha Kanda, Sarga 42, Verse 18', 'तमतिक्रम्य चाकाशं सर्वतः शतयोजनम्।
अपर्वतनदी वृक्षं सर्वसत्त्वविवर्जितम्॥', 'tam atikramya cākāśaṃ sarvataḥ śatayojanam
aparvatanadī vṛkṣaṃ sarvasattvavivarjitam', null, 4042018),
('ramayana-4-42-19', 19, 'Kishkindha Kanda, Sarga 42, Verse 19', 'तं तु शीघ्रमतिक्रम्य कान्तारं रोमहर्षणम्।
कैलासं पाण्डुरं शैलं प्राप्य हृष्टा भविष्यथ॥', 'taṃ tu śīghram atikramya kāntāraṃ romaharṣaṇam
kailāsaṃ pāṇḍuraṃ śailaṃ prāpya hṛṣṭā bhaviṣyatha', null, 4042019),
('ramayana-4-42-20', 20, 'Kishkindha Kanda, Sarga 42, Verse 20', 'तत्र पाण्डुरमेघाभं जाम्बूनदपरिष्कृतम्।
कुबेरभवनं दिव्यं निर्मितं विश्वकर्मणा॥', 'tatra pāṇḍurameghābhaṃ jāmbūnadapariṣkṛtam
kuberabhavanaṃ divyaṃ nirmitaṃ viśvakarmaṇā', null, 4042020),
('ramayana-4-42-21', 21, 'Kishkindha Kanda, Sarga 42, Verse 21', 'विशाला नलिनी यत्र प्रभूतकमलोत्पला।
हंसकारण्डवाकीर्णा अप्सरोगणसेविता॥', 'viśālā nalinī yatra prabhūtakamalotpalā
haṃsakāraṇḍavākīrṇā apsarogaṇasevitā', null, 4042021),
('ramayana-4-42-22', 22, 'Kishkindha Kanda, Sarga 42, Verse 22', 'तत्र वैश्रवणो राजा सर्वभूतनमस्कृतः।
धनदो रमते श्रीमान्गुह्यकैः सह यक्षराट्॥', 'tatra vaiśravaṇo rājā sarvabhūtanamaskṛtaḥ
dhanado ramate śrīmān guhyakaiḥ saha yakṣarāṭ', null, 4042022),
('ramayana-4-42-23', 23, 'Kishkindha Kanda, Sarga 42, Verse 23', 'तस्य चन्द्रनिकशेषु पर्वतेषु गुहासु च।
रावणः सह वैदेह्या मार्गितव्यस्ततस्ततः॥', 'tasya candranikaśeṣu parvateṣu guhāsu ca
rāvaṇaḥ saha vaidehyā mārgitavyas tatas tataḥ', null, 4042023),
('ramayana-4-42-24', 24, 'Kishkindha Kanda, Sarga 42, Verse 24', 'क्रौञ्चं तु गिरिमासाद्य बिलं तस्य सुदुर्गमम्।
अप्रमत्तैः प्रवेष्टव्यं दुष्प्रवेशं हि तत्स्मृतम्॥', 'krauñcaṃ tu girim āsādya bilaṃ tasya sudurgamam
apramattaiḥ praveṣṭavyaṃ duṣpraveśaṃ hi tat smṛtam', null, 4042024),
('ramayana-4-42-25', 25, 'Kishkindha Kanda, Sarga 42, Verse 25', 'वसन्ति हि महात्मानस्तत्र सूर्यसमप्रभाः।
देवैरप्यर्चिताः सम्यग्देवरूपा महर्षयः॥', 'vasanti hi mahātmānas tatra sūryasamaprabhāḥ
devair apy arcitāḥ samyag devarūpā maharṣayaḥ', null, 4042025),
('ramayana-4-42-26', 26, 'Kishkindha Kanda, Sarga 42, Verse 26', 'क्रौञ्चस्य तु गुहाश्चान्याः सानूनि शिखराणि च।
निर्दराश्च नितम्बाश्च विचेतव्यास्ततस्ततः॥', 'krauñcasya tu guhāś cānyāḥ sānūni śikharāṇi ca
nirdarāś ca nitambāś ca vicetavyās tatas tataḥ', null, 4042026),
('ramayana-4-42-27', 27, 'Kishkindha Kanda, Sarga 42, Verse 27', 'क्रौञ्चस्य शिखरं चापि निरीक्ष्य च ततस्ततः।
अवृक्षं कामशैलं च मानसं विहगालयम्॥', 'krauñcasya śikharaṃ cāpi nirīkṣya ca tatas tataḥ
avṛkṣaṃ kāmaśailaṃ ca mānasaṃ vihagālayam', null, 4042027),
('ramayana-4-42-28', 28, 'Kishkindha Kanda, Sarga 42, Verse 28', 'न गतिस्तत्र भूतानां देवदानवरक्षसाम्।
स च सर्वैर्विचेतव्यः ससानुप्रस्थभूधरः॥', 'na gatis tatra bhūtānāṃ devadānavarakṣasām
sa ca sarvair vicetavyaḥ sasānuprasthabhūdharaḥ', null, 4042028),
('ramayana-4-42-29', 29, 'Kishkindha Kanda, Sarga 42, Verse 29', 'क्रौञ्चं गिरिमतिक्रम्य मैनाको नाम पर्वतः।
मयस्य भवनं तत्र दानवस्य स्वयं कृतम्॥', 'krauñcaṃ girim atikramya maināko nāma parvataḥ
mayasya bhavanaṃ tatra dānavasya svayaṃ kṛtam', null, 4042029),
('ramayana-4-42-30', 30, 'Kishkindha Kanda, Sarga 42, Verse 30', 'मैनाकस्तु विचेतव्यः ससानुप्रस्थकन्दरः।
स्त्रीणामश्वमुखीनां च निकेतास्तत्र तत्र तु॥', 'mainākas tu vicetavyaḥ sasānuprasthakandaraḥ
strīṇām aśvamukhīnāṃ ca niketās tatra tatra tu', null, 4042030),
('ramayana-4-42-31', 31, 'Kishkindha Kanda, Sarga 42, Verse 31', 'तं देशं समतिक्रम्य आश्रमं सिद्धसेवितम्।
सिद्धा वैखानसास्तत्र वालखिल्याश्च तापसाः॥', 'taṃ deśaṃ samatikramya āśramaṃ siddhasevitam
siddhā vaikhānasās tatra vālakhilyāś ca tāpasāḥ', null, 4042031),
('ramayana-4-42-32', 32, 'Kishkindha Kanda, Sarga 42, Verse 32', 'वन्द्यास्ते तु तपःसिद्धास्तापसा वीतकल्मषाः।
प्रष्टव्याश्चापि सीतायाः प्रवृत्तं विनयान्वितैः॥', 'vandyās te tu tapaḥsiddhās tāpasā vītakalmaṣāḥ
praṣṭavyāś cāpi sītāyāḥ pravṛttaṃ vinayānvitaiḥ', null, 4042032),
('ramayana-4-42-33', 33, 'Kishkindha Kanda, Sarga 42, Verse 33', 'हेमपुष्करसंछन्नं तत्र वैखानसं सरः।
तरुणादित्यसंकाशैर्हंसैर्विचरितं शुभैः॥', 'hemapuṣkarasaṃchannaṃ tatra vaikhānasaṃ saraḥ
taruṇādityasaṃkāśair haṃsair vicaritaṃ śubhaiḥ', null, 4042033),
('ramayana-4-42-34', 34, 'Kishkindha Kanda, Sarga 42, Verse 34', 'औपवाह्यः कुबेरस्य सर्वभौम इति स्मृतः।
गजः पर्येति तं देशं सदा सह करेणुभिः॥', 'aupavāhyaḥ kuberasya sarvabhauma iti smṛtaḥ
gajaḥ paryeti taṃ deśaṃ sadā saha kareṇubhiḥ', null, 4042034),
('ramayana-4-42-35', 35, 'Kishkindha Kanda, Sarga 42, Verse 35', 'तत्सारः समतिक्रम्य नष्टचन्द्रदिवाकरम्।
अनक्षत्रगणं व्योम निष्पयोदमनादिमत्॥', 'tat sāraḥ samatikramya naṣṭacandradivākaram
anakṣatragaṇaṃ vyoma niṣpayodam anādimat', null, 4042035),
('ramayana-4-42-36', 36, 'Kishkindha Kanda, Sarga 42, Verse 36', 'गभस्तिभिरिवार्कस्य स तु देशः प्रकाशते।
विश्राम्यद्भिस्तपः सिद्धैर्देवकल्पैः स्वयम्प्रभैः॥', 'gabhastibhir ivārkasya sa tu deśaḥ prakāśate
viśrāmyadbhis tapaḥ siddhair devakalpaiḥ svayamprabhaiḥ', null, 4042036),
('ramayana-4-42-37', 37, 'Kishkindha Kanda, Sarga 42, Verse 37', 'तं तु देशमतिक्रम्य शैलोदा नाम निम्नगा।
उभयोस्तीरयोर्यस्याः कीचका नाम वेणवः॥', 'taṃ tu deśam atikramya śailodā nāma nimnagā
ubhayos tīrayor yasyāḥ kīcakā nāma veṇavaḥ', null, 4042037),
('ramayana-4-42-38', 38, 'Kishkindha Kanda, Sarga 42, Verse 38', 'ते नयन्ति परं तीरं सिद्धान्प्रत्यानयन्ति च।
उत्तराः कुरवस्तत्र कृतपुण्यप्रतिश्रियाः॥', 'te nayanti paraṃ tīraṃ siddhān pratyānayanti ca
uttarāḥ kuravas tatra kṛtapuṇyapratiśriyāḥ', null, 4042038),
('ramayana-4-42-39', 39, 'Kishkindha Kanda, Sarga 42, Verse 39', 'ततः काञ्चनपद्माभिः पद्मिनीभिः कृतोदकाः।
नीलवैदूर्यपत्राढ्या नद्यस्तत्र सहस्रशः॥', 'tataḥ kāñcanapadmābhiḥ padminībhiḥ kṛtodakāḥ
nīlavaidūryapatrāḍhyā nadyas tatra sahasraśaḥ', null, 4042039),
('ramayana-4-42-40', 40, 'Kishkindha Kanda, Sarga 42, Verse 40', 'रक्तोत्पलवनैश्चात्र मण्डिताश्च हिरण्मयैः।
तरुणादित्यसदृशैर्भान्ति तत्र जलाशयाः॥', 'raktotpalavanaiś cātra maṇḍitāś ca hiraṇmayaiḥ
taruṇādityasadṛśair bhānti tatra jalāśayāḥ', null, 4042040),
('ramayana-4-42-41', 41, 'Kishkindha Kanda, Sarga 42, Verse 41', 'महार्हमणिपत्रैश्च काञ्चनप्रभ केसरैः।
नीलोत्पलवनैश्चित्रैः स देशः सर्वतोवृतः॥', 'mahārhamaṇipatraiś ca kāñcanaprabha kesaraiḥ
nīlotpalavanaiś citraiḥ sa deśaḥ sarvatovṛtaḥ', null, 4042041),
('ramayana-4-42-42', 42, 'Kishkindha Kanda, Sarga 42, Verse 42', 'निस्तुलाभिश्च मुक्ताभिर्मणिभिश्च महाधनैः।
उद्भूतपुलिनास्तत्र जातरूपैश्च निम्नगाः॥', 'nistulābhiś ca muktābhir maṇibhiś ca mahādhanaiḥ
udbhūtapulinās tatra jātarūpaiś ca nimnagāḥ', null, 4042042),
('ramayana-4-42-43', 43, 'Kishkindha Kanda, Sarga 42, Verse 43', 'सर्वरत्नमयैश्चित्रैरवगाढा नगोत्तमैः।
जातरूपमयैश्चापि हुताशनसमप्रभैः॥', 'sarvaratnamayaiś citrair avagāḍhā nagottamaiḥ
jātarūpamayaiś cāpi hutāśanasamaprabhaiḥ', null, 4042043),
('ramayana-4-42-44', 44, 'Kishkindha Kanda, Sarga 42, Verse 44', 'नित्यपुष्पफलाश्चात्र नगाः पत्ररथाकुलाः।
दिव्यगन्धरसस्पर्शाः सर्वकामान्स्रवन्ति च॥', 'nityapuṣpaphalāś cātra nagāḥ patrarathākulāḥ
divyagandharasasparśāḥ sarvakāmān sravanti ca', null, 4042044),
('ramayana-4-42-45', 45, 'Kishkindha Kanda, Sarga 42, Verse 45', 'नानाकाराणि वासांसि फलन्त्यन्ये नगोत्तमाः।
मुक्तावैदूर्यचित्राणि भूषणानि तथैव च॥', 'nānākārāṇi vāsāṃsi phalanty anye nagottamāḥ
muktāvaidūryacitrāṇi bhūṣaṇāni tathaiva ca', null, 4042045),
('ramayana-4-42-46', 46, 'Kishkindha Kanda, Sarga 42, Verse 46', 'स्त्रीणां यान्यनुरूपाणि पुरुषाणां तथैव च।
सर्वर्तुसुखसेव्यानि फलन्त्यन्ये नगोत्तमाः॥', 'strīṇāṃ yāny anurūpāṇi puruṣāṇāṃ tathaiva ca
sarvartusukhasevyāni phalanty anye nagottamāḥ', null, 4042046),
('ramayana-4-42-47', 47, 'Kishkindha Kanda, Sarga 42, Verse 47', 'महार्हाणि विचित्राणि हैमान्यन्ये नगोत्तमाः।
शयनानि प्रसूयन्ते चित्रास्तारणवन्ति च॥', 'mahārhāṇi vicitrāṇi haimāny anye nagottamāḥ
śayanāni prasūyante citrāstāraṇavanti ca', null, 4042047),
('ramayana-4-42-48', 48, 'Kishkindha Kanda, Sarga 42, Verse 48', 'मनःकान्तानि माल्यानि फलन्त्यत्रापरे द्रुमाः।
पानानि च महार्हाणि भक्ष्याणि विविधानि च॥', 'manaḥkāntāni mālyāni phalanty atrāpare drumāḥ
pānāni ca mahārhāṇi bhakṣyāṇi vividhāni ca', null, 4042048),
('ramayana-4-42-49', 49, 'Kishkindha Kanda, Sarga 42, Verse 49', 'स्त्रियश्च गुणसंपन्ना रूपयौवनलक्षिताः।
गन्धर्वाः किंनरा सिद्धा नागा विद्याधरास्तथा।
रमन्ते सहितास्तत्र नारीभिर्भास्करप्रभाः॥', 'striyaś ca guṇasaṃpannā rūpayauvanalakṣitāḥ
gandharvāḥ kiṃnarā siddhā nāgā vidyādharās tathā
ramante sahitās tatra nārībhir bhāskaraprabhāḥ', null, 4042049),
('ramayana-4-42-50', 50, 'Kishkindha Kanda, Sarga 42, Verse 50', 'सर्वे सुकृतकर्माणः सर्वे रतिपरायणाः।
सर्वे कामार्थसहिता वसन्ति सह योषितः॥', 'sarve sukṛtakarmāṇaḥ sarve ratiparāyaṇāḥ
sarve kāmārthasahitā vasanti saha yoṣitaḥ', null, 4042050),
('ramayana-4-42-51', 51, 'Kishkindha Kanda, Sarga 42, Verse 51', 'गीतवादित्रनिर्घोषः सोत्कृष्टहसितस्वनः।
श्रूयते सततं तत्र सर्वभूतमनोहरः॥', 'gītavāditranirghoṣaḥ sotkṛṣṭahasitasvanaḥ
śrūyate satataṃ tatra sarvabhūtamanoharaḥ', null, 4042051),
('ramayana-4-42-52', 52, 'Kishkindha Kanda, Sarga 42, Verse 52', 'तत्र नामुदितः कश्चिन्नास्ति कश्चिदसत्प्रियः।
अहन्यहनि वर्धन्ते गुणास्तत्र मनोरमाः॥', 'tatra nāmuditaḥ kaś cin nāsti kaś cid asatpriyaḥ
ahany ahani vardhante guṇās tatra manoramāḥ', null, 4042052),
('ramayana-4-42-53', 53, 'Kishkindha Kanda, Sarga 42, Verse 53', 'समतिक्रम्य तं देशमुत्तरस्तोयसां निधिः।
तत्र सोमगिरिर्नाम मध्ये हेममयो महान्॥', 'samatikramya taṃ deśam uttaras toyasāṃ nidhiḥ
tatra somagirir nāma madhye hemamayo mahān', null, 4042053),
('ramayana-4-42-54', 54, 'Kishkindha Kanda, Sarga 42, Verse 54', 'इन्द्रलोकगता ये च ब्रह्मलोकगताश्च ये।
देवास्तं समवेक्षन्ते गिरिराजं दिवं गतम्॥', 'indralokagatā ye ca brahmalokagatāś ca ye
devās taṃ samavekṣante girirājaṃ divaṃ gatam', null, 4042054),
('ramayana-4-42-55', 55, 'Kishkindha Kanda, Sarga 42, Verse 55', 'स तु देशो विसूर्योऽपि तस्य भासा प्रकाशते।
सूर्यलक्ष्म्याभिविज्ञेयस्तपसेव विवस्वता॥', 'sa tu deśo visūryo ''pi tasya bhāsā prakāśate
sūryalakṣmyābhivijñeyas tapaseva vivasvatā', null, 4042055),
('ramayana-4-42-56', 56, 'Kishkindha Kanda, Sarga 42, Verse 56', 'भगवानपि विश्वात्मा शम्भुरेकादशात्मकः।
ब्रह्मा वसति देवेशो ब्रह्मर्षिपरिवारितः॥', 'bhagavān api viśvātmā śambhur ekādaśātmakaḥ
brahmā vasati deveśo brahmarṣiparivāritaḥ', null, 4042056),
('ramayana-4-42-57', 57, 'Kishkindha Kanda, Sarga 42, Verse 57', 'न कथं चन गन्तव्यं कुरूणामुत्तरेण वः।
अन्येषामपि भूतानां नातिक्रामति वै गतिः॥', 'na kathaṃ cana gantavyaṃ kurūṇām uttareṇa vaḥ
anyeṣām api bhūtānāṃ nātikrāmati vai gatiḥ', null, 4042057),
('ramayana-4-42-58', 58, 'Kishkindha Kanda, Sarga 42, Verse 58', 'सा हि सोमगिरिर्नाम देवानामपि दुर्गमः।
तमालोक्य ततः क्षिप्रमुपावर्तितुमर्हथ॥', 'sā hi somagirir nāma devānām api durgamaḥ
tam ālokya tataḥ kṣipram upāvartitum arhatha', null, 4042058),
('ramayana-4-42-59', 59, 'Kishkindha Kanda, Sarga 42, Verse 59', 'एतावद्वानरैः शक्यं गन्तुं वानरपुंगवाः।
अभास्करममर्यादं न जानीमस्ततः परम्॥', 'etāvad vānaraiḥ śakyaṃ gantuṃ vānarapuṃgavāḥ
abhāskaram amaryādaṃ na jānīmas tataḥ param', null, 4042059),
('ramayana-4-42-60', 60, 'Kishkindha Kanda, Sarga 42, Verse 60', 'सर्वमेतद्विचेतव्यं यन्मया परिकीर्तितम्।
यदन्यदपि नोक्तं च तत्रापि क्रियतां मतिः॥', 'sarvam etad vicetavyaṃ yan mayā parikīrtitam
yad anyad api noktaṃ ca tatrāpi kriyatāṃ matiḥ', null, 4042060),
('ramayana-4-42-61', 61, 'Kishkindha Kanda, Sarga 42, Verse 61', 'ततः कृतं दाशरथेर्महत्प्रियं महत्तरं चापि ततो मम प्रियम्।
कृतं भविष्यत्यनिलानलोपमा विदेहजा दर्शनजेन कर्मणा॥', 'tataḥ kṛtaṃ dāśarather mahat priyaṃ mahattaraṃ cāpi tato mama priyam
kṛtaṃ bhaviṣyaty anilānalopamā videhajā darśanajena karmaṇā', null, 4042061),
('ramayana-4-42-62', 62, 'Kishkindha Kanda, Sarga 42, Verse 62', 'ततः कृतार्थाः सहिताः सबान्धवा मयार्चिताः सर्वगुणैर्मनोरमैः।
चरिष्यथोर्वीं प्रतिशान्तशत्रवः सहप्रिया भूतधराः प्लवंगमाः॥', 'tataḥ kṛtārthāḥ sahitāḥ sabāndhavā mayārcitāḥ sarvaguṇair manoramaiḥ
cariṣyathorvīṃ pratiśāntaśatravaḥ sahapriyā bhūtadharāḥ plavaṃgamāḥ', null, 4042062)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 43 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-43-1', 1, 'Kishkindha Kanda, Sarga 43, Verse 1', 'विशेषेण तु सुग्रीवो हनुमत्यर्थमुक्तवान्।
स हि तस्मिन्हरिश्रेष्ठे निश्चितार्थोऽर्थसाधने॥', 'viśeṣeṇa tu sugrīvo hanumatyartham uktavān
sa hi tasmin hariśreṣṭhe niścitārtho ''rthasādhane', null, 4043001),
('ramayana-4-43-2', 2, 'Kishkindha Kanda, Sarga 43, Verse 2', 'न भूमौ नान्तरिक्षे वा नाम्बरे नामरालये।
नाप्सु वा गतिसंगं ते पश्यामि हरिपुंगव॥', 'na bhūmau nāntarikṣe vā nāmbare nāmarālaye
nāpsu vā gatisaṃgaṃ te paśyāmi haripuṃgava', null, 4043002),
('ramayana-4-43-3', 3, 'Kishkindha Kanda, Sarga 43, Verse 3', 'सासुराः सहगन्धर्वाः सनागनरदेवताः।
विदिताः सर्वलोकास्ते ससागरधराधराः॥', 'sāsurāḥ sahagandharvāḥ sanāganaradevatāḥ
viditāḥ sarvalokās te sasāgaradharādharāḥ', null, 4043003),
('ramayana-4-43-4', 4, 'Kishkindha Kanda, Sarga 43, Verse 4', 'गतिर्वेगश्च तेजश्च लाघवं च महाकपे।
पितुस्ते सदृशं वीर मारुतस्य महौजसः॥', 'gatir vegaś ca tejaś ca lāghavaṃ ca mahākape
pitus te sadṛśaṃ vīra mārutasya mahaujasaḥ', null, 4043004),
('ramayana-4-43-5', 5, 'Kishkindha Kanda, Sarga 43, Verse 5', 'तेजसा वापि ते भूतं समं भुवि न विद्यते।
तद्यथा लभ्यते सीता तत्त्वमेवोपपादय॥', 'tejasā vāpi te bhūtaṃ samaṃ bhuvi na vidyate
tad yathā labhyate sītā tattvam evopapādaya', null, 4043005),
('ramayana-4-43-6', 6, 'Kishkindha Kanda, Sarga 43, Verse 6', 'त्वय्येव हनुमन्नस्ति बलं बुद्धिः पराक्रमः।
देशकालानुवृत्तश्च नयश्च नयपण्डित॥', 'tvayy eva hanumann asti balaṃ buddhiḥ parākramaḥ
deśakālānuvṛttaś ca nayaś ca nayapaṇḍita', null, 4043006),
('ramayana-4-43-7', 7, 'Kishkindha Kanda, Sarga 43, Verse 7', 'ततः कार्यसमासंगमवगम्य हनूमति।
विदित्वा हनुमन्तं च चिन्तयामास राघवः॥', 'tataḥ kāryasamāsaṃgam avagamya hanūmati
viditvā hanumantaṃ ca cintayām āsa rāghavaḥ', null, 4043007),
('ramayana-4-43-8', 8, 'Kishkindha Kanda, Sarga 43, Verse 8', 'सर्वथा निश्चितार्थोऽयं हनूमति हरीश्वरः।
निश्चितार्थतरश्चापि हनूमान्कार्यसाधने॥', 'sarvathā niścitārtho ''yaṃ hanūmati harīśvaraḥ
niścitārthataraś cāpi hanūmān kāryasādhane', null, 4043008),
('ramayana-4-43-9', 9, 'Kishkindha Kanda, Sarga 43, Verse 9', 'तदेवं प्रस्थितस्यास्य परिज्ञातस्य कर्मभिः।
भर्त्रा परिगृहीतस्य ध्रुवः कार्यफलोदयः॥', 'tad evaṃ prasthitasyāsya parijñātasya karmabhiḥ
bhartrā parigṛhītasya dhruvaḥ kāryaphalodayaḥ', null, 4043009),
('ramayana-4-43-10', 10, 'Kishkindha Kanda, Sarga 43, Verse 10', 'तं समीक्ष्य महातेजा व्यवसायोत्तरं हरिम्।
कृतार्थ इव संवृत्तः प्रहृष्टेन्द्रियमानसः॥', 'taṃ samīkṣya mahātejā vyavasāyottaraṃ harim
kṛtārtha iva saṃvṛttaḥ prahṛṣṭendriyamānasaḥ', null, 4043010),
('ramayana-4-43-11', 11, 'Kishkindha Kanda, Sarga 43, Verse 11', 'ददौ तस्य ततः प्रीतः स्वनामाङ्कोपशोभितम्।
अङ्गुलीयमभिज्ञानं राजपुत्र्याः परंतपः॥', 'dadau tasya tataḥ prītaḥ svanāmāṅkopaśobhitam
aṅgulīyam abhijñānaṃ rājaputryāḥ paraṃtapaḥ', null, 4043011),
('ramayana-4-43-12', 12, 'Kishkindha Kanda, Sarga 43, Verse 12', 'अनेन त्वां हरिश्रेष्ठ चिह्नेन जनकात्मजा।
मत्सकाशादनुप्राप्तमनुद्विग्नानुपश्यति॥', 'anena tvāṃ hariśreṣṭha cihnena janakātmajā
matsakāśād anuprāptam anudvignānupaśyati', null, 4043012),
('ramayana-4-43-13', 13, 'Kishkindha Kanda, Sarga 43, Verse 13', 'व्यवसायश्च ते वीर सत्त्वयुक्तश्च विक्रमः।
सुग्रीवस्य च संदेशः सिद्धिं कथयतीव मे॥', 'vyavasāyaś ca te vīra sattvayuktaś ca vikramaḥ
sugrīvasya ca saṃdeśaḥ siddhiṃ kathayatīva me', null, 4043013),
('ramayana-4-43-14', 14, 'Kishkindha Kanda, Sarga 43, Verse 14', 'स तद्गृह्य हरिश्रेष्ठः स्थाप्य मूर्ध्नि कृताञ्जलिः।
वन्दित्वा चरणौ चैव प्रस्थितः प्लवगोत्तमः॥', 'sa tad gṛhya hariśreṣṭhaḥ sthāpya mūrdhni kṛtāñjaliḥ
vanditvā caraṇau caiva prasthitaḥ plavagottamaḥ', null, 4043014),
('ramayana-4-43-15', 15, 'Kishkindha Kanda, Sarga 43, Verse 15', 'स तत्प्रकर्षन्हरिणां बलं महद्बभूव वीरः पवनात्मजः कपि।
गताम्बुदे व्योम्नि विशुद्धमण्डलः शशीव नक्षत्रगणोपशोभितः॥', 'sa tat prakarṣan hariṇāṃ balaṃ mahad babhūva vīraḥ pavanātmajaḥ kapi
gatāmbude vyomni viśuddhamaṇḍalaḥ śaśīva nakṣatragaṇopaśobhitaḥ', null, 4043015),
('ramayana-4-43-16', 16, 'Kishkindha Kanda, Sarga 43, Verse 16', 'अतिबलबलमाश्रितस्तवाहं हरिवरविक्रमविक्रमैरनल्पैः।
पवनसुत यथाभिगम्यते सा जनकसुता हनुमंस्तथा कुरुष्व॥', 'atibalabalam āśritas tavāhaṃ harivaravikramavikramair analpaiḥ
pavanasuta yathābhigamyate sā janakasutā hanumaṃs tathā kuruṣva', null, 4043016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 44 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-44-1', 1, 'Kishkindha Kanda, Sarga 44, Verse 1', 'तदुग्रशासनं भर्तुर्विज्ञाय हरिपुंगवाः।
शलभा इव संछाद्य मेदिनीं संप्रतस्थिरे॥', 'tad ugraśāsanaṃ bhartur vijñāya haripuṃgavāḥ
śalabhā iva saṃchādya medinīṃ saṃpratasthire', null, 4044001),
('ramayana-4-44-2', 2, 'Kishkindha Kanda, Sarga 44, Verse 2', 'रामः प्रस्रवणे तस्मिन्न्यवसत्सहलक्ष्मणः।
प्रतीक्षमाणस्तं मासं यः सीताधिगमे कृतः॥', 'rāmaḥ prasravaṇe tasmin nyavasat sahalakṣmaṇaḥ
pratīkṣamāṇas taṃ māsaṃ yaḥ sītādhigame kṛtaḥ', null, 4044002),
('ramayana-4-44-3', 3, 'Kishkindha Kanda, Sarga 44, Verse 3', 'उत्तरां तु दिशं रम्यां गिरिराजसमावृताम्।
प्रतस्थे सहसा वीरो हरिः शतबलिस्तदा॥', 'uttarāṃ tu diśaṃ ramyāṃ girirājasamāvṛtām
pratasthe sahasā vīro hariḥ śatabalis tadā', null, 4044003),
('ramayana-4-44-4', 4, 'Kishkindha Kanda, Sarga 44, Verse 4', 'पूर्वां दिशं प्रति ययौ विनतो हरियूथपः॥', 'pūrvāṃ diśaṃ prati yayau vinato hariyūthapaḥ', null, 4044004),
('ramayana-4-44-5', 5, 'Kishkindha Kanda, Sarga 44, Verse 5', 'ताराङ्गदादि सहितः प्लवगः पवनात्मजः।
अगस्त्यचरितामाशां दक्षिणां हरियूथपः॥', 'tārāṅgadādi sahitaḥ plavagaḥ pavanātmajaḥ
agastyacaritām āśāṃ dakṣiṇāṃ hariyūthapaḥ', null, 4044005),
('ramayana-4-44-6', 6, 'Kishkindha Kanda, Sarga 44, Verse 6', 'पश्चिमां तु दिशं घोरां सुषेणः प्लवगेश्वरः।
प्रतस्थे हरिशार्दूलो भृशं वरुणपालिताम्॥', 'paścimāṃ tu diśaṃ ghorāṃ suṣeṇaḥ plavageśvaraḥ
pratasthe hariśārdūlo bhṛśaṃ varuṇapālitām', null, 4044006),
('ramayana-4-44-7', 7, 'Kishkindha Kanda, Sarga 44, Verse 7', 'ततः सर्वा दिशो राजा चोदयित्वा यथा तथम्।
कपिसेना पतीन्मुख्यान्मुमोद सुखितः सुखम्॥', 'tataḥ sarvā diśo rājā codayitvā yathā tatham
kapisenā patīn mukhyān mumoda sukhitaḥ sukham', null, 4044007),
('ramayana-4-44-8', 8, 'Kishkindha Kanda, Sarga 44, Verse 8', 'एवं संचोदिताः सर्वे राज्ञा वानरयूथपाः।
स्वां स्वां दिशमभिप्रेत्य त्वरिताः संप्रतस्थिरे॥', 'evaṃ saṃcoditāḥ sarve rājñā vānarayūthapāḥ
svāṃ svāṃ diśam abhipretya tvaritāḥ saṃpratasthire', null, 4044008),
('ramayana-4-44-9', 9, 'Kishkindha Kanda, Sarga 44, Verse 9', 'नदन्तश्चोन्नदन्तश्च गर्जन्तश्च प्लवंगमाः।
क्ष्वेलन्तो धावमानाश्च ययुः प्लवगसत्तमाः।
आनयिष्यामहे सीतां हनिष्यामश्च रावणम्॥', 'nadantaś connadantaś ca garjantaś ca plavaṃgamāḥ
kṣvelanto dhāvamānāś ca yayuḥ plavagasattamāḥ
ānayiṣyāmahe sītāṃ haniṣyāmaś ca rāvaṇam', null, 4044009),
('ramayana-4-44-10', 10, 'Kishkindha Kanda, Sarga 44, Verse 10', 'अहमेको हनिष्यामि प्राप्तं रावणमाहवे।
ततश्चोन्मथ्य सहसा हरिष्ये जनकात्मजाम्॥', 'aham eko haniṣyāmi prāptaṃ rāvaṇam āhave
tataś conmathya sahasā hariṣye janakātmajām', null, 4044010),
('ramayana-4-44-11', 11, 'Kishkindha Kanda, Sarga 44, Verse 11', 'वेपमानं श्रमेणाद्य भवद्भिः स्थीयतामिति।
एक एवाहरिष्यामि पातालादपि जानकीम्॥', 'vepamānaṃ śrameṇādya bhavadbhiḥ sthīyatām iti
eka evāhariṣyāmi pātālād api jānakīm', null, 4044011),
('ramayana-4-44-12', 12, 'Kishkindha Kanda, Sarga 44, Verse 12', 'विधमिष्याम्यहं वृक्षान्दारयिष्याम्यहं गिरीन्।
धरणीं दारयिष्यामि क्षोभयिष्यामि सागरान्॥', 'vidhamiṣyāmy ahaṃ vṛkṣān dārayiṣyāmy ahaṃ girīn
dharaṇīṃ dārayiṣyāmi kṣobhayiṣyāmi sāgarān', null, 4044012),
('ramayana-4-44-13', 13, 'Kishkindha Kanda, Sarga 44, Verse 13', 'अहं योजनसंख्यायाः प्लविता नात्र संशयः।
शतं योजनसंख्यायाः शतं समधिकं ह्यहम्॥', 'ahaṃ yojanasaṃkhyāyāḥ plavitā nātra saṃśayaḥ
śataṃ yojanasaṃkhyāyāḥ śataṃ samadhikaṃ hy aham', null, 4044013),
('ramayana-4-44-14', 14, 'Kishkindha Kanda, Sarga 44, Verse 14', 'भूतले सागरे वापि शैलेषु च वनेषु च।
पातालस्यापि वा मध्ये न ममाच्छिद्यते गतिः॥', 'bhūtale sāgare vāpi śaileṣu ca vaneṣu ca
pātālasyāpi vā madhye na mamācchidyate gatiḥ', null, 4044014),
('ramayana-4-44-15', 15, 'Kishkindha Kanda, Sarga 44, Verse 15', 'इत्येकैकं तदा तत्र वानरा बलदर्पिताः।
ऊचुश्च वचनं तस्मिन्हरिराजस्य संनिधौ॥', 'ity ekaikaṃ tadā tatra vānarā baladarpitāḥ
ūcuś ca vacanaṃ tasmin harirājasya saṃnidhau', null, 4044015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 45 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-45-1', 1, 'Kishkindha Kanda, Sarga 45, Verse 1', 'गतेषु वानरेन्द्रेषु रामः सुग्रीवमब्रवीत्।
कथं भवान्विनाजीते सर्वं वै मण्डलं भुवः॥', 'gateṣu vānarendreṣu rāmaḥ sugrīvam abravīt
kathaṃ bhavān vinājīte sarvaṃ vai maṇḍalaṃ bhuvaḥ', null, 4045001),
('ramayana-4-45-2', 2, 'Kishkindha Kanda, Sarga 45, Verse 2', 'सुग्रीवस्तु ततो राममुवाच प्रणतात्मवान्।
श्रूयतां सर्वमाख्यास्ये विस्तरेण नरर्षभ॥', 'sugrīvas tu tato rāmam uvāca praṇatātmavān
śrūyatāṃ sarvam ākhyāsye vistareṇa nararṣabha', null, 4045002),
('ramayana-4-45-3', 3, 'Kishkindha Kanda, Sarga 45, Verse 3', 'यदा तु दुन्दुभिं नाम दानवं महिषाकृतिम्।
परिकालयते वाली मलयं प्रति पर्वतम्॥', 'yadā tu dundubhiṃ nāma dānavaṃ mahiṣākṛtim
parikālayate vālī malayaṃ prati parvatam', null, 4045003),
('ramayana-4-45-4', 4, 'Kishkindha Kanda, Sarga 45, Verse 4', 'तदा विवेश महिषो मलयस्य गुहां प्रति।
विवेश वाली तत्रापि मलयं तज्जिघांसया॥', 'tadā viveśa mahiṣo malayasya guhāṃ prati
viveśa vālī tatrāpi malayaṃ tajjighāṃsayā', null, 4045004),
('ramayana-4-45-5', 5, 'Kishkindha Kanda, Sarga 45, Verse 5', 'ततोऽहं तत्र निक्षिप्तो गुहाद्वारिविनीतवत्।
न च निष्क्रमते वाली तदा संवत्सरे गते॥', 'tato ''haṃ tatra nikṣipto guhād vārivinītavat
na ca niṣkramate vālī tadā saṃvatsare gate', null, 4045005),
('ramayana-4-45-6', 6, 'Kishkindha Kanda, Sarga 45, Verse 6', 'ततः क्षतजवेगेन आपुपूरे तदा बिलम्।
तदहं विस्मितो दृष्ट्वा भ्रातृशोकविषार्दितः॥', 'tataḥ kṣatajavegena āpupūre tadā bilam
tad ahaṃ vismito dṛṣṭvā bhrātṛśokaviṣārditaḥ', null, 4045006),
('ramayana-4-45-7', 7, 'Kishkindha Kanda, Sarga 45, Verse 7', 'अथाहं कृतबुद्धिस्तु सुव्यक्तं निहतो गुरुः।
शिलापर्वतसंकाशा बिलद्वारि मया कृता।
अशक्नुवन्निष्क्रमितुं महिषो विनशेदिति॥', 'athāhaṃ kṛtabuddhis tu suvyaktaṃ nihato guruḥ
śilāparvatasaṃkāśā biladvāri mayā kṛtā
aśaknuvan niṣkramituṃ mahiṣo vinaśed iti', null, 4045007),
('ramayana-4-45-8', 8, 'Kishkindha Kanda, Sarga 45, Verse 8', 'ततोऽहमागां किष्किन्धां निराशस्तस्य जीविते।
राज्यं च सुमहत्प्राप्तं तारा च रुमया सह।
मित्रैश्च सहितस्तत्र वसामि विगतज्वरः॥', 'tato ''ham āgāṃ kiṣkindhāṃ nirāśas tasya jīvite
rājyaṃ ca sumahat prāptaṃ tārā ca rumayā saha
mitraiś ca sahitas tatra vasāmi vigatajvaraḥ', null, 4045008),
('ramayana-4-45-9', 9, 'Kishkindha Kanda, Sarga 45, Verse 9', 'आजगाम ततो वाली हत्वा तं दानवर्षभम्।
ततोऽहमददां राज्यं गौरवाद्भययन्त्रितः॥', 'ājagāma tato vālī hatvā taṃ dānavarṣabham
tato ''ham adadāṃ rājyaṃ gauravād bhayayantritaḥ', null, 4045009),
('ramayana-4-45-10', 10, 'Kishkindha Kanda, Sarga 45, Verse 10', 'स मां जिघांसुर्दुष्टात्मा वाली प्रव्यथितेन्द्रियः।
परिलाकयते क्रोधाद्धावन्तं सचिवैः सह॥', 'sa māṃ jighāṃsur duṣṭātmā vālī pravyathitendriyaḥ
parilākayate krodhād dhāvantaṃ sacivaiḥ saha', null, 4045010),
('ramayana-4-45-11', 11, 'Kishkindha Kanda, Sarga 45, Verse 11', 'ततोऽहं वालिना तेन सानुबन्धः प्रधावितः।
नदीश्च विविधाः पश्यन्वनानि नगराणि च॥', 'tato ''haṃ vālinā tena sānubandhaḥ pradhāvitaḥ
nadīś ca vividhāḥ paśyan vanāni nagarāṇi ca', null, 4045011),
('ramayana-4-45-12', 12, 'Kishkindha Kanda, Sarga 45, Verse 12', 'आदर्शतलसंकाशा ततो वै पृथिवी मया।
अलातचक्रप्रतिमा दृष्टा गोष्पदवत्तदा॥', 'ādarśatalasaṃkāśā tato vai pṛthivī mayā
alātacakrapratimā dṛṣṭā goṣpadavat tadā', null, 4045012),
('ramayana-4-45-13', 13, 'Kishkindha Kanda, Sarga 45, Verse 13', 'ततः पूर्वमहं गत्वा दक्षिणामहमाश्रितः।
दिशं च पश्चिमां भूयो गतोऽस्मि भयशङ्कितः।
उत्तरां तु दिशं यान्तं हनुमान्मामथाब्रवीत्॥', 'tataḥ pūrvam ahaṃ gatvā dakṣiṇām aham āśritaḥ
diśaṃ ca paścimāṃ bhūyo gato ''smi bhayaśaṅkitaḥ
uttarāṃ tu diśaṃ yāntaṃ hanumān mām athābravīt', null, 4045013),
('ramayana-4-45-14', 14, 'Kishkindha Kanda, Sarga 45, Verse 14', 'इदानीं मे स्मृतं राजन्यथा वाली हरीश्वरः।
मतङ्गेन तदा शप्तो ह्यस्मिन्नाश्रममण्डले॥', 'idānīṃ me smṛtaṃ rājan yathā vālī harīśvaraḥ
mataṅgena tadā śapto hy asminn āśramamaṇḍale', null, 4045014),
('ramayana-4-45-15', 15, 'Kishkindha Kanda, Sarga 45, Verse 15', 'प्रविशेद्यदि वा वाली मूर्धास्य शतधा भवेत्।
तत्र वासः सुखोऽस्माकं निरुद्विग्नो भविष्यति॥', 'praviśed yadi vā vālī mūrdhāsya śatadhā bhavet
tatra vāsaḥ sukho ''smākaṃ nirudvigno bhaviṣyati', null, 4045015),
('ramayana-4-45-16', 16, 'Kishkindha Kanda, Sarga 45, Verse 16', 'ततः पर्वतमासाद्य ऋश्यमूकं नृपात्मज।
न विवेश तदा वाली मतङ्गस्य भयात्तदा॥', 'tataḥ parvatam āsādya ṛśyamūkaṃ nṛpātmaja
na viveśa tadā vālī mataṅgasya bhayāt tadā', null, 4045016),
('ramayana-4-45-17', 17, 'Kishkindha Kanda, Sarga 45, Verse 17', 'एवं मया तदा राजन्प्रत्यक्षमुपलक्षितम्।
पृथिवीमण्डलं कृत्स्नं गुहामस्म्यागतस्ततः॥', 'evaṃ mayā tadā rājan pratyakṣam upalakṣitam
pṛthivīmaṇḍalaṃ kṛtsnaṃ guhām asmy āgatas tataḥ', null, 4045017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 46 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-46-1', 1, 'Kishkindha Kanda, Sarga 46, Verse 1', 'दर्शनार्थं तु वैदेह्याः सर्वतः कपियूथपाः।
व्यादिष्टाः कपिराजेन यथोक्तं जग्मुरञ्जसा॥', 'darśanārthaṃ tu vaidehyāḥ sarvataḥ kapiyūthapāḥ
vyādiṣṭāḥ kapirājena yathoktaṃ jagmur añjasā', null, 4046001),
('ramayana-4-46-2', 2, 'Kishkindha Kanda, Sarga 46, Verse 2', 'सरांसि सरितः कक्षानाकाशं नगराणि च।
नदीदुर्गांस्तथा शैलान्विचिन्वन्ति समन्ततः॥', 'sarāṃsi saritaḥ kakṣān ākāśaṃ nagarāṇi ca
nadīdurgāṃs tathā śailān vicinvanti samantataḥ', null, 4046002),
('ramayana-4-46-3', 3, 'Kishkindha Kanda, Sarga 46, Verse 3', 'सुग्रीवेण समाख्यातान्सर्वे वानरयूथपाः।
प्रदेशान्प्रविचिन्वन्ति सशैलवनकाननान्॥', 'sugrīveṇa samākhyātān sarve vānarayūthapāḥ
pradeśān pravicinvanti saśailavanakānanān', null, 4046003),
('ramayana-4-46-4', 4, 'Kishkindha Kanda, Sarga 46, Verse 4', 'विचिन्त्य दिवसं सर्वे सीताधिगमने धृताः।
समायान्ति स्म मेदिन्यां निशाकालेशु वानराः॥', 'vicintya divasaṃ sarve sītādhigamane dhṛtāḥ
samāyānti sma medinyāṃ niśākāleśu vānarāḥ', null, 4046004),
('ramayana-4-46-5', 5, 'Kishkindha Kanda, Sarga 46, Verse 5', 'सर्वर्तुकांश्च देशेषु वानराः सफलान्द्रुमान्।
आसाद्य रजनीं शय्यां चक्रुः सर्वेष्वहःसु ते॥', 'sarvartukāṃś ca deśeṣu vānarāḥ saphalān drumān
āsādya rajanīṃ śayyāṃ cakruḥ sarveṣv ahaḥsu te', null, 4046005),
('ramayana-4-46-6', 6, 'Kishkindha Kanda, Sarga 46, Verse 6', 'तदहः प्रथमं कृत्वा मासे प्रस्रवणं गताः।
कपिराजेन संगम्य निराशाः कपियूथपाः॥', 'tad ahaḥ prathamaṃ kṛtvā māse prasravaṇaṃ gatāḥ
kapirājena saṃgamya nirāśāḥ kapiyūthapāḥ', null, 4046006),
('ramayana-4-46-7', 7, 'Kishkindha Kanda, Sarga 46, Verse 7', 'विचित्य तु दिशं पूर्वां यथोक्तां सचिवैः सह।
अदृष्ट्वा विनतः सीतामाजगाम महाबलः॥', 'vicitya tu diśaṃ pūrvāṃ yathoktāṃ sacivaiḥ saha
adṛṣṭvā vinataḥ sītām ājagāma mahābalaḥ', null, 4046007),
('ramayana-4-46-8', 8, 'Kishkindha Kanda, Sarga 46, Verse 8', 'उत्तरां तु दिशं सर्वां विचित्य स महाकपिः।
आगतः सह सैन्येन वीरः शतबलिस्तदा॥', 'uttarāṃ tu diśaṃ sarvāṃ vicitya sa mahākapiḥ
āgataḥ saha sainyena vīraḥ śatabalis tadā', null, 4046008),
('ramayana-4-46-9', 9, 'Kishkindha Kanda, Sarga 46, Verse 9', 'सुषेणः पश्चिमामाशां विचित्य सह वानरैः।
समेत्य मासे संपूर्णे सुग्रीवमुपचक्रमे॥', 'suṣeṇaḥ paścimām āśāṃ vicitya saha vānaraiḥ
sametya māse saṃpūrṇe sugrīvam upacakrame', null, 4046009),
('ramayana-4-46-10', 10, 'Kishkindha Kanda, Sarga 46, Verse 10', 'तं प्रस्रवणपृष्ठस्थं समासाद्याभिवाद्य च।
आसीनं सह रामेण सुग्रीवमिदमब्रुवन्॥', 'taṃ prasravaṇapṛṣṭhasthaṃ samāsādyābhivādya ca
āsīnaṃ saha rāmeṇa sugrīvam idam abruvan', null, 4046010),
('ramayana-4-46-11', 11, 'Kishkindha Kanda, Sarga 46, Verse 11', 'विचिताः पर्वताः सर्वे वनानि नगराणि च।
निम्नगाः सागरान्ताश्च सर्वे जनपदास्तथा॥', 'vicitāḥ parvatāḥ sarve vanāni nagarāṇi ca
nimnagāḥ sāgarāntāś ca sarve janapadās tathā', null, 4046011),
('ramayana-4-46-12', 12, 'Kishkindha Kanda, Sarga 46, Verse 12', 'गुहाश्च विचिताः सर्वा यास्त्वया परिकीर्तिताः।
विचिताश्च महागुल्मा लताविततसंतताः॥', 'guhāś ca vicitāḥ sarvā yās tvayā parikīrtitāḥ
vicitāś ca mahāgulmā latāvitatasaṃtatāḥ', null, 4046012),
('ramayana-4-46-13', 13, 'Kishkindha Kanda, Sarga 46, Verse 13', 'गहनेषु च देशेषु दुर्गेषु विषमेषु च।
सत्त्वान्यतिप्रमाणानि विचितानि हतानि च।
ये चैव गहना देशा विचितास्ते पुनः पुनः॥', 'gahaneṣu ca deśeṣu durgeṣu viṣameṣu ca
sattvāny atipramāṇāni vicitāni hatāni ca
ye caiva gahanā deśā vicitās te punaḥ punaḥ', null, 4046013),
('ramayana-4-46-14', 14, 'Kishkindha Kanda, Sarga 46, Verse 14', 'उदारसत्त्वाभिजनो महात्मा स मैथिलीं द्रक्ष्यति वानरेन्द्रः।
दिशं तु यामेव गता तु सीता तामास्थितो वायुसुतो हनूमान्॥', 'udārasattvābhijano mahātmā sa maithilīṃ drakṣyati vānarendraḥ
diśaṃ tu yām eva gatā tu sītā tām āsthito vāyusuto hanūmān', null, 4046014)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 47 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-47-1', 1, 'Kishkindha Kanda, Sarga 47, Verse 1', 'सहताराङ्गदाभ्यां तु गत्वा स हनुमान्कपिः।
सुग्रीवेण यथोद्दिष्टं तं देशमुपचक्रमे॥', 'sahatārāṅgadābhyāṃ tu gatvā sa hanumān kapiḥ
sugrīveṇa yathoddiṣṭaṃ taṃ deśam upacakrame', null, 4047001),
('ramayana-4-47-2', 2, 'Kishkindha Kanda, Sarga 47, Verse 2', 'स तु दूरमुपागम्य सर्वैस्तैः कपिसत्तमैः।
विचिनोति स्म विन्ध्यस्य गुहाश्च गहनानि च॥', 'sa tu dūram upāgamya sarvais taiḥ kapisattamaiḥ
vicinoti sma vindhyasya guhāś ca gahanāni ca', null, 4047002),
('ramayana-4-47-3', 3, 'Kishkindha Kanda, Sarga 47, Verse 3', 'पर्वताग्रान्नदीदुर्गान्सरांसि विपुलान्द्रुमान्।
वृक्षषण्डांश्च विविधान्पर्वतान्घनपादपान्॥', 'parvatāgrān nadīdurgān sarāṃsi vipulān drumān
vṛkṣaṣaṇḍāṃś ca vividhān parvatān ghanapādapān', null, 4047003),
('ramayana-4-47-4', 4, 'Kishkindha Kanda, Sarga 47, Verse 4', 'अन्वेषमाणास्ते सर्वे वानराः सर्वतो दिशम्।
न सीतां ददृशुर्वीरा मैथिलीं जनकात्मजाम्॥', 'anveṣamāṇās te sarve vānarāḥ sarvato diśam
na sītāṃ dadṛśur vīrā maithilīṃ janakātmajām', null, 4047004),
('ramayana-4-47-5', 5, 'Kishkindha Kanda, Sarga 47, Verse 5', 'ते भक्षयन्तो मूलानि फलानि विविधानि च।
अन्वेषमाणा दुर्धर्षा न्यवसंस्तत्र तत्र ह।
स तु देशो दुरन्वेषो गुहागहनवान्महान्॥', 'te bhakṣayanto mūlāni phalāni vividhāni ca
anveṣamāṇā durdharṣā nyavasaṃs tatra tatra ha
sa tu deśo duranveṣo guhāgahanavān mahān', null, 4047005),
('ramayana-4-47-6', 6, 'Kishkindha Kanda, Sarga 47, Verse 6', 'त्यक्त्वा तु तं तदा देशं सर्वे वै हरियूथपाः।
देशमन्यं दुराधर्षं विविशुश्चाकुतोभयाः॥', 'tyaktvā tu taṃ tadā deśaṃ sarve vai hariyūthapāḥ
deśam anyaṃ durādharṣaṃ viviśuś cākutobhayāḥ', null, 4047006),
('ramayana-4-47-7', 7, 'Kishkindha Kanda, Sarga 47, Verse 7', 'यत्र वन्ध्यफला वृक्षा विपुष्पाः पर्णवर्जिताः।
निस्तोयाः सरितो यत्र मूलं यत्र सुदुर्लभम्॥', 'yatra vandhyaphalā vṛkṣā vipuṣpāḥ parṇavarjitāḥ
nistoyāḥ sarito yatra mūlaṃ yatra sudurlabham', null, 4047007),
('ramayana-4-47-8', 8, 'Kishkindha Kanda, Sarga 47, Verse 8', 'न सन्ति महिषा यत्र न मृगा न च हस्तिनः।
शार्दूलाः पक्षिणो वापि ये चान्ये वनगोचराः॥', 'na santi mahiṣā yatra na mṛgā na ca hastinaḥ
śārdūlāḥ pakṣiṇo vāpi ye cānye vanagocarāḥ', null, 4047008),
('ramayana-4-47-9', 9, 'Kishkindha Kanda, Sarga 47, Verse 9', 'स्निग्धपत्राः स्थले यत्र पद्मिन्यः फुल्लपङ्कजाः।
प्रेक्षणीयाः सुगन्धाश्च भ्रमरैश्चापि वर्जिताः॥', 'snigdhapatrāḥ sthale yatra padminyaḥ phullapaṅkajāḥ
prekṣaṇīyāḥ sugandhāś ca bhramaraiś cāpi varjitāḥ', null, 4047009),
('ramayana-4-47-10', 10, 'Kishkindha Kanda, Sarga 47, Verse 10', 'कण्डुर्नाम महाभागः सत्यवादी तपोधनः।
महर्षिः परमामर्षी नियमैर्दुष्प्रधर्षणः॥', 'kaṇḍur nāma mahābhāgaḥ satyavādī tapodhanaḥ
maharṣiḥ paramāmarṣī niyamair duṣpradharṣaṇaḥ', null, 4047010),
('ramayana-4-47-11', 11, 'Kishkindha Kanda, Sarga 47, Verse 11', 'तस्य तस्मिन्वने पुत्रो बालको दशवार्षिकः।
प्रनष्टो जीवितान्ताय क्रुद्धस्तत्र महामुनिः॥', 'tasya tasmin vane putro bālako daśavārṣikaḥ
pranaṣṭo jīvitāntāya kruddhas tatra mahāmuniḥ', null, 4047011),
('ramayana-4-47-12', 12, 'Kishkindha Kanda, Sarga 47, Verse 12', 'तेन धर्मात्मना शप्तं कृत्स्नं तत्र महद्वनम्।
अशरण्यं दुराधर्षं मृगपक्षिविवर्जितम्॥', 'tena dharmātmanā śaptaṃ kṛtsnaṃ tatra mahad vanam
aśaraṇyaṃ durādharṣaṃ mṛgapakṣivivarjitam', null, 4047012),
('ramayana-4-47-13', 13, 'Kishkindha Kanda, Sarga 47, Verse 13', 'तस्य ते काननान्तांस्तु गिरीणां कन्दराणि च।
प्रभवानि नदीनांच विचिन्वन्ति समाहिताः॥', 'tasya te kānanāntāṃs tu girīṇāṃ kandarāṇi ca
prabhavāni nadīnāṃca vicinvanti samāhitāḥ', null, 4047013),
('ramayana-4-47-14', 14, 'Kishkindha Kanda, Sarga 47, Verse 14', 'तत्र चापि महात्मानो नापश्यञ्जनकात्मजाम्।
हर्तारं रावणं वापि सुग्रीवप्रियकारिणः॥', 'tatra cāpi mahātmāno nāpaśyañ janakātmajām
hartāraṃ rāvaṇaṃ vāpi sugrīvapriyakāriṇaḥ', null, 4047014),
('ramayana-4-47-15', 15, 'Kishkindha Kanda, Sarga 47, Verse 15', 'ते प्रविश्य तु तं भीमं लतागुल्मसमावृतम्।
ददृशुः क्रूरकर्माणमसुरं सुरनिर्भयम्॥', 'te praviśya tu taṃ bhīmaṃ latāgulmasamāvṛtam
dadṛśuḥ krūrakarmāṇam asuraṃ suranirbhayam', null, 4047015),
('ramayana-4-47-16', 16, 'Kishkindha Kanda, Sarga 47, Verse 16', 'तं दृष्ट्वा वनरा घोरं स्थितं शैलमिवापरम्।
गाढं परिहिताः सर्वे दृष्ट्वा तं पर्वतोपमम्॥', 'taṃ dṛṣṭvā vanarā ghoraṃ sthitaṃ śailam ivāparam
gāḍhaṃ parihitāḥ sarve dṛṣṭvā taṃ parvatopamam', null, 4047016),
('ramayana-4-47-17', 17, 'Kishkindha Kanda, Sarga 47, Verse 17', 'सोऽपि तान्वानरान्सर्वान्नष्टाः स्थेत्यब्रवीद्बली।
अभ्यधावत संक्रुद्धो मुष्टिमुद्यम्य संहितम्॥', 'so ''pi tān vānarān sarvān naṣṭāḥ sthety abravīd balī
abhyadhāvata saṃkruddho muṣṭim udyamya saṃhitam', null, 4047017),
('ramayana-4-47-18', 18, 'Kishkindha Kanda, Sarga 47, Verse 18', 'तमापतन्तं सहसा वालिपुत्रोऽङ्गदस्तदा।
रावणोऽयमिति ज्ञात्वा तलेनाभिजघान ह॥', 'tam āpatantaṃ sahasā vāliputro ''ṅgadas tadā
rāvaṇo ''yam iti jñātvā talenābhijaghāna ha', null, 4047018),
('ramayana-4-47-19', 19, 'Kishkindha Kanda, Sarga 47, Verse 19', 'स वालिपुत्राभिहतो वक्त्राच्छोणितमुद्वमन्।
असुरो न्यपतद्भूमौ पर्यस्त इव पर्वतः॥', 'sa vāliputrābhihato vaktrāc choṇitam udvaman
asuro nyapatad bhūmau paryasta iva parvataḥ', null, 4047019),
('ramayana-4-47-20', 20, 'Kishkindha Kanda, Sarga 47, Verse 20', 'ते तु तस्मिन्निरुच्छ्वासे वानरा जितकाशिनः।
व्यचिन्वन्प्रायशस्तत्र सर्वं तद्गिरिगह्वरम्॥', 'te tu tasmin nirucchvāse vānarā jitakāśinaḥ
vyacinvan prāyaśas tatra sarvaṃ tad girigahvaram', null, 4047020),
('ramayana-4-47-21', 21, 'Kishkindha Kanda, Sarga 47, Verse 21', 'विचितं तु ततः कृत्वा सर्वे ते काननं पुनः।
अन्यदेवापरं घोरं विविशुर्गिरिगह्वरम्॥', 'vicitaṃ tu tataḥ kṛtvā sarve te kānanaṃ punaḥ
anyadevāparaṃ ghoraṃ viviśur girigahvaram', null, 4047021),
('ramayana-4-47-22', 22, 'Kishkindha Kanda, Sarga 47, Verse 22', 'ते विचिन्त्य पुनः खिन्ना विनिष्पत्य समागताः।
एकान्ते वृक्षमूले तु निषेदुर्दीनमानसाः॥', 'te vicintya punaḥ khinnā viniṣpatya samāgatāḥ
ekānte vṛkṣamūle tu niṣedur dīnamānasāḥ', null, 4047022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 48 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-48-1', 1, 'Kishkindha Kanda, Sarga 48, Verse 1', 'अथाङ्गदस्तदा सर्वान्वानरानिदमब्रवीत्।
परिश्रान्तो महाप्राज्ञः समाश्वास्य शनैर्वचः॥', 'athāṅgadas tadā sarvān vānarān idam abravīt
pariśrānto mahāprājñaḥ samāśvāsya śanair vacaḥ', null, 4048001),
('ramayana-4-48-2', 2, 'Kishkindha Kanda, Sarga 48, Verse 2', 'वनानि गिरयो नद्यो दुर्गाणि गहनानि च।
दर्यो गिरिगुहाश्चैव विचिता नः समन्ततः॥', 'vanāni girayo nadyo durgāṇi gahanāni ca
daryo giriguhāś caiva vicitā naḥ samantataḥ', null, 4048002),
('ramayana-4-48-3', 3, 'Kishkindha Kanda, Sarga 48, Verse 3', 'तत्र तत्र सहास्माभिर्जानकी न च दृश्यते।
तद्वा रक्षो हृता येन सीता सुरसुतोपमा॥', 'tatra tatra sahāsmābhir jānakī na ca dṛśyate
tad vā rakṣo hṛtā yena sītā surasutopamā', null, 4048003),
('ramayana-4-48-4', 4, 'Kishkindha Kanda, Sarga 48, Verse 4', 'कालश्च नो महान्यातः सुग्रीवश्चोग्रशासनः।
तस्माद्भवन्तः सहिता विचिन्वन्तु समन्ततः॥', 'kālaś ca no mahān yātaḥ sugrīvaś cograśāsanaḥ
tasmād bhavantaḥ sahitā vicinvantu samantataḥ', null, 4048004),
('ramayana-4-48-5', 5, 'Kishkindha Kanda, Sarga 48, Verse 5', 'विहाय तन्द्रीं शोकं च निद्रां चैव समुत्थिताम्।
विचिनुध्वं यथा सीतां पश्यामो जनकात्मजाम्॥', 'vihāya tandrīṃ śokaṃ ca nidrāṃ caiva samutthitām
vicinudhvaṃ yathā sītāṃ paśyāmo janakātmajām', null, 4048005),
('ramayana-4-48-6', 6, 'Kishkindha Kanda, Sarga 48, Verse 6', 'अनिर्वेदं च दाक्ष्यं च मनसश्चापराजयम्।
कार्यसिद्धिकराण्याहुस्तस्मादेतद्ब्रवीम्यहम्॥', 'anirvedaṃ ca dākṣyaṃ ca manasaś cāparājayam
kāryasiddhikarāṇy āhus tasmād etad bravīmy aham', null, 4048006),
('ramayana-4-48-7', 7, 'Kishkindha Kanda, Sarga 48, Verse 7', 'अद्यापीदं वनं दुर्गं विचिन्वन्तु वनौकसः।
खेदं त्यक्त्वा पुनः सर्वं वनमेतद्विचीयताम्॥', 'adyāpīdaṃ vanaṃ durgaṃ vicinvantu vanaukasaḥ
khedaṃ tyaktvā punaḥ sarvaṃ vanam etad vicīyatām', null, 4048007),
('ramayana-4-48-8', 8, 'Kishkindha Kanda, Sarga 48, Verse 8', 'अवश्यं क्रियमाणस्य दृश्यते कर्मणः फलम्।
अलं निर्वेदमागम्य न हि नो मलिनं क्षमम्॥', 'avaśyaṃ kriyamāṇasya dṛśyate karmaṇaḥ phalam
alaṃ nirvedam āgamya na hi no malinaṃ kṣamam', null, 4048008),
('ramayana-4-48-9', 9, 'Kishkindha Kanda, Sarga 48, Verse 9', 'सुग्रीवः क्रोधनो राजा तीक्ष्णदण्डश्च वानराः।
भेतव्यं तस्य सततं रामस्य च महात्मनः॥', 'sugrīvaḥ krodhano rājā tīkṣṇadaṇḍaś ca vānarāḥ
bhetavyaṃ tasya satataṃ rāmasya ca mahātmanaḥ', null, 4048009),
('ramayana-4-48-10', 10, 'Kishkindha Kanda, Sarga 48, Verse 10', 'हितार्थमेतदुक्तं वः क्रियतां यदि रोचते।
उच्यतां वा क्षमं यन्नः सर्वेषामेव वानराः॥', 'hitārtham etad uktaṃ vaḥ kriyatāṃ yadi rocate
ucyatāṃ vā kṣamaṃ yan naḥ sarveṣām eva vānarāḥ', null, 4048010),
('ramayana-4-48-11', 11, 'Kishkindha Kanda, Sarga 48, Verse 11', 'अङ्गदस्य वचः श्रुत्वा वचनं गन्धमादनः।
उवाचाव्यक्तया वाचा पिपासा श्रमखिन्नया॥', 'aṅgadasya vacaḥ śrutvā vacanaṃ gandhamādanaḥ
uvācāvyaktayā vācā pipāsā śramakhinnayā', null, 4048011),
('ramayana-4-48-12', 12, 'Kishkindha Kanda, Sarga 48, Verse 12', 'सदृशं खलु वो वाक्यमङ्गदो यदुवाच ह।
हितं चैवानुकूलं च क्रियतामस्य भाषितम्॥', 'sadṛśaṃ khalu vo vākyam aṅgado yad uvāca ha
hitaṃ caivānukūlaṃ ca kriyatām asya bhāṣitam', null, 4048012),
('ramayana-4-48-13', 13, 'Kishkindha Kanda, Sarga 48, Verse 13', 'पुनर्मार्गामहे शैलान्कन्दरांश्च दरीस्तथा।
काननानि च शून्यानि गिरिप्रस्रवणानि च॥', 'punar mārgāmahe śailān kandarāṃś ca darīs tathā
kānanāni ca śūnyāni giriprasravaṇāni ca', null, 4048013),
('ramayana-4-48-14', 14, 'Kishkindha Kanda, Sarga 48, Verse 14', 'यथोद्दिष्ठानि सर्वाणि सुग्रीवेण महात्मना।
विचिन्वन्तु वनं सर्वे गिरिदुर्गाणि सर्वशः॥', 'yathoddiṣṭhāni sarvāṇi sugrīveṇa mahātmanā
vicinvantu vanaṃ sarve giridurgāṇi sarvaśaḥ', null, 4048014),
('ramayana-4-48-15', 15, 'Kishkindha Kanda, Sarga 48, Verse 15', 'ततः समुत्थाय पुनर्वानरास्ते महाबलाः।
विन्ध्यकाननसंकीर्णां विचेरुर्दक्षिणां दिशम्॥', 'tataḥ samutthāya punar vānarās te mahābalāḥ
vindhyakānanasaṃkīrṇāṃ vicerur dakṣiṇāṃ diśam', null, 4048015),
('ramayana-4-48-16', 16, 'Kishkindha Kanda, Sarga 48, Verse 16', 'ते शारदाभ्रप्रतिमं श्रीमद्रजतपर्वतम्।
शृङ्गवन्तं दरीवन्तमधिरुह्य च वानराः॥', 'te śāradābhrapratimaṃ śrīmadrajataparvatam
śṛṅgavantaṃ darīvantam adhiruhya ca vānarāḥ', null, 4048016),
('ramayana-4-48-17', 17, 'Kishkindha Kanda, Sarga 48, Verse 17', 'तत्र लोध्रवनं रम्यं सप्तपर्णवनानि च।
विचिन्वन्तो हरिवराः सीतादर्शनकाङ्क्षिणः॥', 'tatra lodhravanaṃ ramyaṃ saptaparṇavanāni ca
vicinvanto harivarāḥ sītādarśanakāṅkṣiṇaḥ', null, 4048017),
('ramayana-4-48-18', 18, 'Kishkindha Kanda, Sarga 48, Verse 18', 'तस्याग्रमधिरूढास्ते श्रान्ता विपुलविक्रमाः।
न पश्यन्ति स्म वैदेहीं रामस्य महिषीं प्रियाम्॥', 'tasyāgram adhirūḍhās te śrāntā vipulavikramāḥ
na paśyanti sma vaidehīṃ rāmasya mahiṣīṃ priyām', null, 4048018),
('ramayana-4-48-19', 19, 'Kishkindha Kanda, Sarga 48, Verse 19', 'ते तु दृष्टिगतं कृत्वा तं शैलं बहुकन्दरम्।
अवारोहन्त हरयो वीक्षमाणाः समन्ततः॥', 'te tu dṛṣṭigataṃ kṛtvā taṃ śailaṃ bahukandaram
avārohanta harayo vīkṣamāṇāḥ samantataḥ', null, 4048019),
('ramayana-4-48-20', 20, 'Kishkindha Kanda, Sarga 48, Verse 20', 'अवरुह्य ततो भूमिं श्रान्ता विगतचेतसः।
स्थित्वा मुहूर्तं तत्राथ वृक्षमूलमुपाश्रिताः॥', 'avaruhya tato bhūmiṃ śrāntā vigatacetasaḥ
sthitvā muhūrtaṃ tatrātha vṛkṣamūlam upāśritāḥ', null, 4048020),
('ramayana-4-48-21', 21, 'Kishkindha Kanda, Sarga 48, Verse 21', 'ते मुहूर्तं समाश्वस्ताः किं चिद्भग्नपरिश्रमाः।
पुनरेवोद्यताः कृत्स्नां मार्गितुं दक्षिणां दिशम्॥', 'te muhūrtaṃ samāśvastāḥ kiṃ cid bhagnapariśramāḥ
punar evodyatāḥ kṛtsnāṃ mārgituṃ dakṣiṇāṃ diśam', null, 4048021),
('ramayana-4-48-22', 22, 'Kishkindha Kanda, Sarga 48, Verse 22', 'हनुमत्प्रमुखास्ते तु प्रस्थिताः प्लवगर्षभाः।
विन्ध्यमेवादितस्तावद्विचेरुस्ते समन्ततः॥', 'hanumatpramukhās te tu prasthitāḥ plavagarṣabhāḥ
vindhyam evāditas tāvad vicerus te samantataḥ', null, 4048022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 49 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-49-1', 1, 'Kishkindha Kanda, Sarga 49, Verse 1', 'सह ताराङ्गदाभ्यां तु संगम्य हनुमान्कपिः।
विचिनोति स्म विन्ध्यस्य गुहाश्च गहनानि च॥', 'saha tārāṅgadābhyāṃ tu saṃgamya hanumān kapiḥ
vicinoti sma vindhyasya guhāś ca gahanāni ca', null, 4049001),
('ramayana-4-49-2', 2, 'Kishkindha Kanda, Sarga 49, Verse 2', 'सिंहशार्दूलजुष्टाश्च गुहाश्च परितस्तथा।
विषमेषु नगेन्द्रस्य महाप्रस्रवणेषु च॥', 'siṃhaśārdūlajuṣṭāś ca guhāś ca paritas tathā
viṣameṣu nagendrasya mahāprasravaṇeṣu ca', null, 4049002),
('ramayana-4-49-3', 3, 'Kishkindha Kanda, Sarga 49, Verse 3', 'तेषां तत्रैव वसतां स कालो व्यत्यवर्तत॥', 'teṣāṃ tatraiva vasatāṃ sa kālo vyatyavartata', null, 4049003),
('ramayana-4-49-4', 4, 'Kishkindha Kanda, Sarga 49, Verse 4', 'स हि देशो दुरन्वेषो गुहा गहनवान्महान्।
तत्र वायुसुतः सर्वं विचिनोति स्म पर्वतम्॥', 'sa hi deśo duranveṣo guhā gahanavān mahān
tatra vāyusutaḥ sarvaṃ vicinoti sma parvatam', null, 4049004),
('ramayana-4-49-5', 5, 'Kishkindha Kanda, Sarga 49, Verse 5', 'परस्परेण रहिता अन्योन्यस्याविदूरतः।
गजो गवाक्षो गवयः शरभो गन्धमादनः॥', 'paraspareṇa rahitā anyonyasyāvidūrataḥ
gajo gavākṣo gavayaḥ śarabho gandhamādanaḥ', null, 4049005),
('ramayana-4-49-6', 6, 'Kishkindha Kanda, Sarga 49, Verse 6', 'मैन्दश्च द्विविदश्चैव हनुमाञ्जाम्बवानपि।
अङ्गदो युवराजश्च तारश्च वनगोचरः॥', 'maindaś ca dvividaś caiva hanumāñ jāmbavān api
aṅgado yuvarājaś ca tāraś ca vanagocaraḥ', null, 4049006),
('ramayana-4-49-7', 7, 'Kishkindha Kanda, Sarga 49, Verse 7', 'गिरिजालावृतान्देशान्मार्गित्वा दक्षिणां दिशम्।
क्षुत्पिपासा परीताश्च श्रान्ताश्च सलिलार्थिनः।
अवकीर्णं लतावृक्षैर्ददृशुस्ते महाबिलम्॥', 'girijālāvṛtān deśān mārgitvā dakṣiṇāṃ diśam
kṣutpipāsā parītāś ca śrāntāś ca salilārthinaḥ
avakīrṇaṃ latāvṛkṣair dadṛśus te mahābilam', null, 4049007),
('ramayana-4-49-8', 8, 'Kishkindha Kanda, Sarga 49, Verse 8', 'ततः क्रौञ्चाश्च हंसाश्च सारसाश्चापि निष्क्रमन्।
जलार्द्राश्चक्रवाकाश्च रक्ताङ्गाः पद्मरेणुभिः॥', 'tataḥ krauñcāś ca haṃsāś ca sārasāś cāpi niṣkraman
jalārdrāś cakravākāś ca raktāṅgāḥ padmareṇubhiḥ', null, 4049008),
('ramayana-4-49-9', 9, 'Kishkindha Kanda, Sarga 49, Verse 9', 'ततस्तद्बिलमासाद्य सुगन्धि दुरतिक्रमम्।
विस्मयव्यग्रमनसो बभूवुर्वानरर्षभाः॥', 'tatas tad bilam āsādya sugandhi duratikramam
vismayavyagramanaso babhūvur vānararṣabhāḥ', null, 4049009),
('ramayana-4-49-10', 10, 'Kishkindha Kanda, Sarga 49, Verse 10', 'संजातपरिशङ्कास्ते तद्बिलं प्लवगोत्तमाः।
अभ्यपद्यन्त संहृष्टास्तेजोवन्तो महाबलाः॥', 'saṃjātapariśaṅkās te tad bilaṃ plavagottamāḥ
abhyapadyanta saṃhṛṣṭās tejovanto mahābalāḥ', null, 4049010),
('ramayana-4-49-11', 11, 'Kishkindha Kanda, Sarga 49, Verse 11', 'ततः पर्वतकूटाभो हनुमान्मारुतात्मजः।
अब्रवीद्वानरान्सर्वान्कान्तार वनकोविदः॥', 'tataḥ parvatakūṭābho hanumān mārutātmajaḥ
abravīd vānarān sarvān kāntāra vanakovidaḥ', null, 4049011),
('ramayana-4-49-12', 12, 'Kishkindha Kanda, Sarga 49, Verse 12', 'गिरिजालावृतान्देशान्मार्गित्वा दक्षिणां दिशम्।
वयं सर्वे परिश्रान्ता न च पश्यामि मैथिलीम्॥', 'girijālāvṛtān deśān mārgitvā dakṣiṇāṃ diśam
vayaṃ sarve pariśrāntā na ca paśyāmi maithilīm', null, 4049012),
('ramayana-4-49-13', 13, 'Kishkindha Kanda, Sarga 49, Verse 13', 'अस्माच्चापि बिलाद्धंसाः क्रौञ्चाश्च सह सारसैः।
जलार्द्राश्चक्रवाकाश्च निष्पतन्ति स्म सर्वशः॥', 'asmāc cāpi bilād dhaṃsāḥ krauñcāś ca saha sārasaiḥ
jalārdrāś cakravākāś ca niṣpatanti sma sarvaśaḥ', null, 4049013),
('ramayana-4-49-14', 14, 'Kishkindha Kanda, Sarga 49, Verse 14', 'नूनं सलिलवानत्र कूपो वा यदि वा ह्रदः।
तथा चेमे बिलद्वारे स्निग्धास्तिष्ठन्ति पादपाः॥', 'nūnaṃ salilavān atra kūpo vā yadi vā hradaḥ
tathā ceme biladvāre snigdhās tiṣṭhanti pādapāḥ', null, 4049014),
('ramayana-4-49-15', 15, 'Kishkindha Kanda, Sarga 49, Verse 15', 'इत्युक्तास्तद्बिलं सर्वे विविशुस्तिमिरावृतम्।
अचन्द्रसूर्यं हरयो ददृशू रोमहर्षणम्॥', 'ity uktās tad bilaṃ sarve viviśus timirāvṛtam
acandrasūryaṃ harayo dadṛśū romaharṣaṇam', null, 4049015),
('ramayana-4-49-16', 16, 'Kishkindha Kanda, Sarga 49, Verse 16', 'ततस्तस्मिन्बिले दुर्गे नानापादपसंकुले।
अन्योन्यं संपरिष्वज्य जग्मुर्योजनमन्तरम्॥', 'tatas tasmin bile durge nānāpādapasaṃkule
anyonyaṃ saṃpariṣvajya jagmur yojanam antaram', null, 4049016),
('ramayana-4-49-17', 17, 'Kishkindha Kanda, Sarga 49, Verse 17', 'ते नष्टसंज्ञास्तृषिताः संभ्रान्ताः सलिलार्थिनः।
परिपेतुर्बिले तस्मिन्कं चित्कालमतन्द्रिताः॥', 'te naṣṭasaṃjñās tṛṣitāḥ saṃbhrāntāḥ salilārthinaḥ
paripetur bile tasmin kaṃ cit kālam atandritāḥ', null, 4049017),
('ramayana-4-49-18', 18, 'Kishkindha Kanda, Sarga 49, Verse 18', 'ते कृशा दीनवदनाः परिश्रान्ताः प्लवंगमाः।
आलोकं ददृशुर्वीरा निराशा जीविते तदा॥', 'te kṛśā dīnavadanāḥ pariśrāntāḥ plavaṃgamāḥ
ālokaṃ dadṛśur vīrā nirāśā jīvite tadā', null, 4049018),
('ramayana-4-49-19', 19, 'Kishkindha Kanda, Sarga 49, Verse 19', 'ततस्तं देशमागम्य सौम्यं वितिमिरं वनम्।
ददृशुः काञ्चनान्वृक्षान्दीप्तवैश्वानरप्रभान्॥', 'tatas taṃ deśam āgamya saumyaṃ vitimiraṃ vanam
dadṛśuḥ kāñcanān vṛkṣān dīptavaiśvānaraprabhān', null, 4049019),
('ramayana-4-49-20', 20, 'Kishkindha Kanda, Sarga 49, Verse 20', 'सालांस्तालांश्च पुंनागान्ककुभान्वञ्जुलान्धवान्।
चम्पकान्नागवृक्षांश्च कर्णिकारांश्च पुष्पितान्॥', 'sālāṃs tālāṃś ca puṃnāgān kakubhān vañjulān dhavān
campakān nāgavṛkṣāṃś ca karṇikārāṃś ca puṣpitān', null, 4049020),
('ramayana-4-49-21', 21, 'Kishkindha Kanda, Sarga 49, Verse 21', 'तरुणादित्यसंकाशान्वैदूर्यमयवेदिकान्।
नीलवैदूर्यवर्णाश्च पद्मिनीः पतगावृताः॥', 'taruṇādityasaṃkāśān vaidūryamayavedikān
nīlavaidūryavarṇāś ca padminīḥ patagāvṛtāḥ', null, 4049021),
('ramayana-4-49-22', 22, 'Kishkindha Kanda, Sarga 49, Verse 22', 'महद्भिः काञ्चनैर्वृक्षैर्वृतं बालार्क संनिभैः।
जातरूपमयैर्मत्स्यैर्महद्भिश्च सकच्छपैः॥', 'mahadbhiḥ kāñcanair vṛkṣair vṛtaṃ bālārka saṃnibhaiḥ
jātarūpamayair matsyair mahadbhiś ca sakacchapaiḥ', null, 4049022),
('ramayana-4-49-23', 23, 'Kishkindha Kanda, Sarga 49, Verse 23', 'नलिनीस्तत्र ददृशुः प्रसन्नसलिलायुताः।
काञ्चनानि विमानानि राजतानि तथैव च॥', 'nalinīs tatra dadṛśuḥ prasannasalilāyutāḥ
kāñcanāni vimānāni rājatāni tathaiva ca', null, 4049023),
('ramayana-4-49-24', 24, 'Kishkindha Kanda, Sarga 49, Verse 24', 'तपनीयगवाक्षाणि मुक्ताजालावृतानि च।
हैमराजतभौमानि वैदूर्यमणिमन्ति च॥', 'tapanīyagavākṣāṇi muktājālāvṛtāni ca
haimarājatabhaumāni vaidūryamaṇimanti ca', null, 4049024),
('ramayana-4-49-25', 25, 'Kishkindha Kanda, Sarga 49, Verse 25', 'ददृशुस्तत्र हरयो गृहमुख्यानि सर्वशः।
पुष्पितान्फलिनो वृक्षान्प्रवालमणिसंनिभान्॥', 'dadṛśus tatra harayo gṛhamukhyāni sarvaśaḥ
puṣpitān phalino vṛkṣān pravālamaṇisaṃnibhān', null, 4049025),
('ramayana-4-49-26', 26, 'Kishkindha Kanda, Sarga 49, Verse 26', 'काञ्चनभ्रमरांश्चैव मधूनि च समन्ततः।
मणिकाञ्चनचित्राणि शयनान्यासनानि च॥', 'kāñcanabhramarāṃś caiva madhūni ca samantataḥ
maṇikāñcanacitrāṇi śayanāny āsanāni ca', null, 4049026),
('ramayana-4-49-27', 27, 'Kishkindha Kanda, Sarga 49, Verse 27', 'महार्हाणि च यानानि ददृशुस्ते समन्ततः।
हैमराजतकांस्यानां भाजनानां च संचयान्॥', 'mahārhāṇi ca yānāni dadṛśus te samantataḥ
haimarājatakāṃsyānāṃ bhājanānāṃ ca saṃcayān', null, 4049027),
('ramayana-4-49-28', 28, 'Kishkindha Kanda, Sarga 49, Verse 28', 'अगरूणां च दिव्यानां चन्दनानां च संचयान्।
शुचीन्यभ्यवहार्याणि मूलानि च फलानि च॥', 'agarūṇāṃ ca divyānāṃ candanānāṃ ca saṃcayān
śucīny abhyavahāryāṇi mūlāni ca phalāni ca', null, 4049028),
('ramayana-4-49-29', 29, 'Kishkindha Kanda, Sarga 49, Verse 29', 'महार्हाणि च पानानि मधूनि रसवन्ति च।
दिव्यानामम्बराणां च महार्हाणां च संचयान्।
कम्बलानां च चित्राणामजिनानां च संचयान्॥', 'mahārhāṇi ca pānāni madhūni rasavanti ca
divyānām ambarāṇāṃ ca mahārhāṇāṃ ca saṃcayān
kambalānāṃ ca citrāṇām ajinānāṃ ca saṃcayān', null, 4049029),
('ramayana-4-49-30', 30, 'Kishkindha Kanda, Sarga 49, Verse 30', 'तत्र तत्र विचिन्वन्तो बिले तत्र महाप्रभाः।
ददृशुर्वानराः शूराः स्त्रियं कां चिददूरतः॥', 'tatra tatra vicinvanto bile tatra mahāprabhāḥ
dadṛśur vānarāḥ śūrāḥ striyaṃ kāṃ cid adūrataḥ', null, 4049030),
('ramayana-4-49-31', 31, 'Kishkindha Kanda, Sarga 49, Verse 31', 'तां दृष्ट्वा भृशसंत्रस्ताश्चीरकृष्णाजिनाम्बराम्।
तापसीं नियताहारां ज्वलन्तीमिव तेजसा॥', 'tāṃ dṛṣṭvā bhṛśasaṃtrastāś cīrakṛṣṇājināmbarām
tāpasīṃ niyatāhārāṃ jvalantīm iva tejasā', null, 4049031),
('ramayana-4-49-32', 32, 'Kishkindha Kanda, Sarga 49, Verse 32', 'ततो हनूमान्गिरिसंनिकाशः कृताञ्जलिस्तामभिवाद्य वृद्धाम्।
पप्रच्छ का त्वं भवनं बिलं च रत्नानि चेमानि वदस्व कस्य॥', 'tato hanūmān girisaṃnikāśaḥ kṛtāñjalis tām abhivādya vṛddhām
papraccha kā tvaṃ bhavanaṃ bilaṃ ca ratnāni cemāni vadasva kasya', null, 4049032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 50 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-50-1', 1, 'Kishkindha Kanda, Sarga 50, Verse 1', 'इत्युक्त्वा हनुमांस्तत्र पुनः कृष्णाजिनाम्बराम्।
अब्रवीत्तां महाभागां तापसीं धर्मचारिणीम्॥', 'ity uktvā hanumāṃs tatra punaḥ kṛṣṇājināmbarām
abravīt tāṃ mahābhāgāṃ tāpasīṃ dharmacāriṇīm', null, 4050001),
('ramayana-4-50-2', 2, 'Kishkindha Kanda, Sarga 50, Verse 2', 'इदं प्रविष्टाः सहसा बिलं तिमिरसंवृतम्।
क्षुत्पिपासा परिश्रान्ताः परिखिन्नाश्च सर्वशः॥', 'idaṃ praviṣṭāḥ sahasā bilaṃ timirasaṃvṛtam
kṣutpipāsā pariśrāntāḥ parikhinnāś ca sarvaśaḥ', null, 4050002),
('ramayana-4-50-3', 3, 'Kishkindha Kanda, Sarga 50, Verse 3', 'महद्धिरण्या विवरं प्रविष्टाः स्म पिपासिताः।
इमांस्त्वेवं विधान्भावान्विविधानद्भुतोपमान्।
दृष्ट्वा वयं प्रव्यथिताः संभ्रान्ता नष्टचेतसः॥', 'mahad dhiraṇyā vivaraṃ praviṣṭāḥ sma pipāsitāḥ
imāṃs tv evaṃ vidhān bhāvān vividhān adbhutopamān
dṛṣṭvā vayaṃ pravyathitāḥ saṃbhrāntā naṣṭacetasaḥ', null, 4050003),
('ramayana-4-50-4', 4, 'Kishkindha Kanda, Sarga 50, Verse 4', 'कस्येमे काञ्चना वृक्षास्तरुणादित्यसंनिभाः।
शुचीन्यभ्यवहार्याणि मूलानि च फलानि च॥', 'kasyeme kāñcanā vṛkṣās taruṇādityasaṃnibhāḥ
śucīny abhyavahāryāṇi mūlāni ca phalāni ca', null, 4050004),
('ramayana-4-50-5', 5, 'Kishkindha Kanda, Sarga 50, Verse 5', 'काञ्चनानि विमानानि राजतानि गृहाणि च।
तपनीय गवाक्षाणि मणिजालावृतानि च॥', 'kāñcanāni vimānāni rājatāni gṛhāṇi ca
tapanīya gavākṣāṇi maṇijālāvṛtāni ca', null, 4050005),
('ramayana-4-50-6', 6, 'Kishkindha Kanda, Sarga 50, Verse 6', 'पुष्पिताः फालवन्तश्च पुण्याः सुरभिगन्धिनः।
इमे जाम्बूनदमयाः पादपाः कस्य तेजसा॥', 'puṣpitāḥ phālavantaś ca puṇyāḥ surabhigandhinaḥ
ime jāmbūnadamayāḥ pādapāḥ kasya tejasā', null, 4050006),
('ramayana-4-50-7', 7, 'Kishkindha Kanda, Sarga 50, Verse 7', 'काञ्चनानि च पद्मानि जातानि विमले जले।
कथं मत्स्याश्च सौवर्णा चरन्ति सह कच्छपैः॥', 'kāñcanāni ca padmāni jātāni vimale jale
kathaṃ matsyāś ca sauvarṇā caranti saha kacchapaiḥ', null, 4050007),
('ramayana-4-50-8', 8, 'Kishkindha Kanda, Sarga 50, Verse 8', 'आत्मानमनुभावं च कस्य चैतत्तपोबलम्।
अजानतां नः सर्वेषां सर्वमाख्यातुमर्हसि॥', 'ātmānam anubhāvaṃ ca kasya caitat tapobalam
ajānatāṃ naḥ sarveṣāṃ sarvam ākhyātum arhasi', null, 4050008),
('ramayana-4-50-9', 9, 'Kishkindha Kanda, Sarga 50, Verse 9', 'एवमुक्ता हनुमता तापसी धर्मचारिणी।
प्रत्युवाच हनूमन्तं सर्वभूतहिते रता॥', 'evam uktā hanumatā tāpasī dharmacāriṇī
pratyuvāca hanūmantaṃ sarvabhūtahite ratā', null, 4050009),
('ramayana-4-50-10', 10, 'Kishkindha Kanda, Sarga 50, Verse 10', 'मयो नाम महातेजा मायावी दानवर्षभः।
तेनेदं निर्मितं सर्वं मायया काञ्चनं वनम्॥', 'mayo nāma mahātejā māyāvī dānavarṣabhaḥ
tenedaṃ nirmitaṃ sarvaṃ māyayā kāñcanaṃ vanam', null, 4050010),
('ramayana-4-50-11', 11, 'Kishkindha Kanda, Sarga 50, Verse 11', 'पुरा दानवमुख्यानां विश्वकर्मा बभूव ह।
येनेदं काञ्चनं दिव्यं निर्मितं भवनोत्तमम्॥', 'purā dānavamukhyānāṃ viśvakarmā babhūva ha
yenedaṃ kāñcanaṃ divyaṃ nirmitaṃ bhavanottamam', null, 4050011),
('ramayana-4-50-12', 12, 'Kishkindha Kanda, Sarga 50, Verse 12', 'स तु वर्षसहस्राणि तपस्तप्त्वा महावने।
पितामहाद्वरं लेभे सर्वमौशसनं धनम्॥', 'sa tu varṣasahasrāṇi tapas taptvā mahāvane
pitāmahād varaṃ lebhe sarvam auśasanaṃ dhanam', null, 4050012),
('ramayana-4-50-13', 13, 'Kishkindha Kanda, Sarga 50, Verse 13', 'विधाय सर्वं बलवान्सर्वकामेश्वरस्तदा।
उवास सुखितः कालं कं चिदस्मिन्महावने॥', 'vidhāya sarvaṃ balavān sarvakāmeśvaras tadā
uvāsa sukhitaḥ kālaṃ kaṃ cid asmin mahāvane', null, 4050013),
('ramayana-4-50-14', 14, 'Kishkindha Kanda, Sarga 50, Verse 14', 'तमप्सरसि हेमायां सक्तं दानवपुंगवम्।
विक्रम्यैवाशनिं गृह्य जघानेशः पुरंदरः॥', 'tam apsarasi hemāyāṃ saktaṃ dānavapuṃgavam
vikramyaivāśaniṃ gṛhya jaghāneśaḥ puraṃdaraḥ', null, 4050014),
('ramayana-4-50-15', 15, 'Kishkindha Kanda, Sarga 50, Verse 15', 'इदं च ब्रह्मणा दत्तं हेमायै वनमुत्तमम्।
शाश्वतः कामभोगश्च गृहं चेदं हिरण्मयम्॥', 'idaṃ ca brahmaṇā dattaṃ hemāyai vanam uttamam
śāśvataḥ kāmabhogaś ca gṛhaṃ cedaṃ hiraṇmayam', null, 4050015),
('ramayana-4-50-16', 16, 'Kishkindha Kanda, Sarga 50, Verse 16', 'दुहिता मेरुसावर्णेरहं तस्याः स्वयं प्रभा।
इदं रक्षामि भवनं हेमाया वानरोत्तम॥', 'duhitā merusāvarṇer ahaṃ tasyāḥ svayaṃ prabhā
idaṃ rakṣāmi bhavanaṃ hemāyā vānarottama', null, 4050016),
('ramayana-4-50-17', 17, 'Kishkindha Kanda, Sarga 50, Verse 17', 'मम प्रियसखी हेमा नृत्तगीतविशारदा।
तया दत्तवरा चास्मि रक्षामि भवनोत्तमम्॥', 'mama priyasakhī hemā nṛttagītaviśāradā
tayā dattavarā cāsmi rakṣāmi bhavanottamam', null, 4050017),
('ramayana-4-50-18', 18, 'Kishkindha Kanda, Sarga 50, Verse 18', 'किं कार्यं कस्य वा हेतोः कान्ताराणि प्रपद्यथ।
कथं चेदं वनं दुर्गं युष्माभिरुपलक्षितम्॥', 'kiṃ kāryaṃ kasya vā hetoḥ kāntārāṇi prapadyatha
kathaṃ cedaṃ vanaṃ durgaṃ yuṣmābhir upalakṣitam', null, 4050018),
('ramayana-4-50-19', 19, 'Kishkindha Kanda, Sarga 50, Verse 19', 'इमान्यभ्यवहार्याणि मूलानि च फलानि च।
भुक्त्वा पीत्वा च पानीयं सर्वं मे वक्तुमर्हथ॥', 'imāny abhyavahāryāṇi mūlāni ca phalāni ca
bhuktvā pītvā ca pānīyaṃ sarvaṃ me vaktum arhatha', null, 4050019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 51 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-51-1', 1, 'Kishkindha Kanda, Sarga 51, Verse 1', 'अथ तानब्रवीत्सर्वान्विश्रान्तान्हरियूथपान्।
इदं वचनमेकाग्रा तापसी धर्मचारिणी॥', 'atha tān abravīt sarvān viśrāntān hariyūthapān
idaṃ vacanam ekāgrā tāpasī dharmacāriṇī', null, 4051001),
('ramayana-4-51-2', 2, 'Kishkindha Kanda, Sarga 51, Verse 2', 'वानरा यदि वः खेदः प्रनष्टः फलभक्षणात्।
यदि चैतन्मया श्राव्यं श्रोतुमिच्छामि कथ्यताम्॥', 'vānarā yadi vaḥ khedaḥ pranaṣṭaḥ phalabhakṣaṇāt
yadi caitan mayā śrāvyaṃ śrotum icchāmi kathyatām', null, 4051002),
('ramayana-4-51-3', 3, 'Kishkindha Kanda, Sarga 51, Verse 3', 'तस्यास्तद्वचनं श्रुत्वा हनुमान्मारुतात्मजः।
आर्जवेन यथातत्त्वमाख्यातुमुपचक्रमे॥', 'tasyās tad vacanaṃ śrutvā hanumān mārutātmajaḥ
ārjavena yathātattvam ākhyātum upacakrame', null, 4051003),
('ramayana-4-51-4', 4, 'Kishkindha Kanda, Sarga 51, Verse 4', 'राजा सर्वस्य लोकस्य महेन्द्रवरुणोपमः।
रामो दाशरथिः श्रीमान्प्रविष्टो दण्डकावनम्॥', 'rājā sarvasya lokasya mahendravaruṇopamaḥ
rāmo dāśarathiḥ śrīmān praviṣṭo daṇḍakāvanam', null, 4051004),
('ramayana-4-51-5', 5, 'Kishkindha Kanda, Sarga 51, Verse 5', 'लक्ष्मणेन सह भ्रात्रा वैदेह्या चापि भार्यया।
तस्य भार्या जनस्थानाद्रावणेन हृता बलात्॥', 'lakṣmaṇena saha bhrātrā vaidehyā cāpi bhāryayā
tasya bhāryā janasthānād rāvaṇena hṛtā balāt', null, 4051005),
('ramayana-4-51-6', 6, 'Kishkindha Kanda, Sarga 51, Verse 6', 'वीरस्तस्य सखा राज्ञः सुग्रीवो नाम वानरः।
राजा वानरमुख्यानां येन प्रस्थापिता वयम्॥', 'vīras tasya sakhā rājñaḥ sugrīvo nāma vānaraḥ
rājā vānaramukhyānāṃ yena prasthāpitā vayam', null, 4051006),
('ramayana-4-51-7', 7, 'Kishkindha Kanda, Sarga 51, Verse 7', 'अगस्त्यचरितामाशां दक्षिणां यमरक्षिताम्।
सहैभिर्वानरैर्मुख्यैरङ्गदप्रमुखैर्वयम्॥', 'agastyacaritām āśāṃ dakṣiṇāṃ yamarakṣitām
sahaibhir vānarair mukhyair aṅgadapramukhair vayam', null, 4051007),
('ramayana-4-51-8', 8, 'Kishkindha Kanda, Sarga 51, Verse 8', 'रावणं सहिताः सर्वे राक्षसं कामरूपिणम्।
सीतया सह वैदेह्या मार्गध्वमिति चोदिताः॥', 'rāvaṇaṃ sahitāḥ sarve rākṣasaṃ kāmarūpiṇam
sītayā saha vaidehyā mārgadhvam iti coditāḥ', null, 4051008),
('ramayana-4-51-9', 9, 'Kishkindha Kanda, Sarga 51, Verse 9', 'विचित्य तु वयं सर्वे समग्रां दक्षिणां दिशम्।
बुभुक्षिताः परिश्रान्ता वृक्षमूलमुपाश्रिताः॥', 'vicitya tu vayaṃ sarve samagrāṃ dakṣiṇāṃ diśam
bubhukṣitāḥ pariśrāntā vṛkṣamūlam upāśritāḥ', null, 4051009),
('ramayana-4-51-10', 10, 'Kishkindha Kanda, Sarga 51, Verse 10', 'विवर्णवदनाः सर्वे सर्वे ध्यानपरायणाः।
नाधिगच्छामहे पारं मग्नाश्चिन्तामहार्णवे॥', 'vivarṇavadanāḥ sarve sarve dhyānaparāyaṇāḥ
nādhigacchāmahe pāraṃ magnāś cintāmahārṇave', null, 4051010),
('ramayana-4-51-11', 11, 'Kishkindha Kanda, Sarga 51, Verse 11', 'चारयन्तस्ततश्चक्षुर्दृष्टवन्तो महद्बिलम्।
लतापादपसंछन्नं तिमिरेण समावृतम्॥', 'cārayantas tataś cakṣur dṛṣṭavanto mahad bilam
latāpādapasaṃchannaṃ timireṇa samāvṛtam', null, 4051011),
('ramayana-4-51-12', 12, 'Kishkindha Kanda, Sarga 51, Verse 12', 'अस्माद्धंसा जलक्लिन्नाः पक्षैः सलिलरेणुभिः।
कुरराः सारसाश्चैव निष्पतन्ति पतत्रिणः।
साध्वत्र प्रविशामेति मया तूक्ताः प्लवंगमाः॥', 'asmād dhaṃsā jalaklinnāḥ pakṣaiḥ salilareṇubhiḥ
kurarāḥ sārasāś caiva niṣpatanti patatriṇaḥ
sādhv atra praviśāmeti mayā tūktāḥ plavaṃgamāḥ', null, 4051012),
('ramayana-4-51-13', 13, 'Kishkindha Kanda, Sarga 51, Verse 13', 'तेषामपि हि सर्वेषामनुमानमुपागतम्।
गच्छामः प्रविशामेति भर्तृकार्यत्वरान्विताः॥', 'teṣām api hi sarveṣām anumānam upāgatam
gacchāmaḥ praviśāmeti bhartṛkāryatvarānvitāḥ', null, 4051013),
('ramayana-4-51-14', 14, 'Kishkindha Kanda, Sarga 51, Verse 14', 'ततो गाढं निपतिता गृह्य हस्तौ परस्परम्।
इदं प्रविष्टाः सहसा बिलं तिमिरसंवृतम्॥', 'tato gāḍhaṃ nipatitā gṛhya hastau parasparam
idaṃ praviṣṭāḥ sahasā bilaṃ timirasaṃvṛtam', null, 4051014),
('ramayana-4-51-15', 15, 'Kishkindha Kanda, Sarga 51, Verse 15', 'एतन्नः कायमेतेन कृत्येन वयमागताः।
त्वां चैवोपगताः सर्वे परिद्यूना बुभुक्षिताः॥', 'etan naḥ kāyam etena kṛtyena vayam āgatāḥ
tvāṃ caivopagatāḥ sarve paridyūnā bubhukṣitāḥ', null, 4051015),
('ramayana-4-51-16', 16, 'Kishkindha Kanda, Sarga 51, Verse 16', 'आतिथ्यधर्मदत्तानि मूलानि च फलानि च।
अस्माभिरुपभुक्तानि बुभुक्षापरिपीडितैः॥', 'ātithyadharmadattāni mūlāni ca phalāni ca
asmābhir upabhuktāni bubhukṣāparipīḍitaiḥ', null, 4051016),
('ramayana-4-51-17', 17, 'Kishkindha Kanda, Sarga 51, Verse 17', 'यत्त्वया रक्षिताः सर्वे म्रियमाणा बुभुक्षया।
ब्रूहि प्रत्युपकारार्थं किं ते कुर्वन्तु वानराः॥', 'yat tvayā rakṣitāḥ sarve mriyamāṇā bubhukṣayā
brūhi pratyupakārārthaṃ kiṃ te kurvantu vānarāḥ', null, 4051017),
('ramayana-4-51-18', 18, 'Kishkindha Kanda, Sarga 51, Verse 18', 'एवमुक्ता तु सर्वज्ञा वानरैस्तैः स्वयंप्रभा।
प्रत्युवाच ततः सर्वानिदं वानरयूथपम्॥', 'evam uktā tu sarvajñā vānarais taiḥ svayaṃprabhā
pratyuvāca tataḥ sarvān idaṃ vānarayūthapam', null, 4051018),
('ramayana-4-51-19', 19, 'Kishkindha Kanda, Sarga 51, Verse 19', 'सर्वेषां परितुष्टास्मि वानराणां तरस्विनाम्।
चरन्त्या मम धर्मेण न कार्यमिह केन चित्॥', 'sarveṣāṃ parituṣṭāsmi vānarāṇāṃ tarasvinām
carantyā mama dharmeṇa na kāryam iha kena cit', null, 4051019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 52 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-52-1', 1, 'Kishkindha Kanda, Sarga 52, Verse 1', 'एवमुक्तः शुभं वाक्यं तापस्या धर्मसंहितम्।
उवाच हनुमान्वाक्यं तामनिन्दितचेष्टिताम्॥', 'evam uktaḥ śubhaṃ vākyaṃ tāpasyā dharmasaṃhitam
uvāca hanumān vākyaṃ tām aninditaceṣṭitām', null, 4052001),
('ramayana-4-52-2', 2, 'Kishkindha Kanda, Sarga 52, Verse 2', 'शरणं त्वां प्रपन्नाः स्मः सर्वे वै धर्मचारिणि।
यः कृतः समयोऽस्माकं सुग्रीवेण महात्मना।
स तु कालो व्यतिक्रान्तो बिले च परिवर्तताम्॥', 'śaraṇaṃ tvāṃ prapannāḥ smaḥ sarve vai dharmacāriṇi
yaḥ kṛtaḥ samayo ''smākaṃ sugrīveṇa mahātmanā
sa tu kālo vyatikrānto bile ca parivartatām', null, 4052002),
('ramayana-4-52-3', 3, 'Kishkindha Kanda, Sarga 52, Verse 3', 'सा त्वमस्माद्बिलाद्घोरादुत्तारयितुमर्हसि॥', 'sā tvam asmād bilād ghorād uttārayitum arhasi', null, 4052003),
('ramayana-4-52-4', 4, 'Kishkindha Kanda, Sarga 52, Verse 4', 'तस्मात्सुग्रीववचनादतिक्रान्तान्गतायुषः।
त्रातुमर्हसि नः सर्वान्सुग्रीवभयशङ्कितान्॥', 'tasmāt sugrīvavacanād atikrāntān gatāyuṣaḥ
trātum arhasi naḥ sarvān sugrīvabhayaśaṅkitān', null, 4052004),
('ramayana-4-52-5', 5, 'Kishkindha Kanda, Sarga 52, Verse 5', 'महच्च कार्यमस्माभिः कर्तव्यं धर्मचारिणि।
तच्चापि न कृतं कार्यमस्माभिरिह वासिभिः॥', 'mahac ca kāryam asmābhiḥ kartavyaṃ dharmacāriṇi
tac cāpi na kṛtaṃ kāryam asmābhir iha vāsibhiḥ', null, 4052005),
('ramayana-4-52-6', 6, 'Kishkindha Kanda, Sarga 52, Verse 6', 'एवमुक्ता हनुमता तापसी वाक्यमब्रवीत्।
जीवता दुष्करं मन्ये प्रविष्टेन निवर्तितुम्॥', 'evam uktā hanumatā tāpasī vākyam abravīt
jīvatā duṣkaraṃ manye praviṣṭena nivartitum', null, 4052006),
('ramayana-4-52-7', 7, 'Kishkindha Kanda, Sarga 52, Verse 7', 'तपसस्तु प्रभावेन नियमोपार्जितेन च।
सर्वानेव बिलादस्मादुद्धरिष्यामि वानरान्॥', 'tapasas tu prabhāvena niyamopārjitena ca
sarvān eva bilād asmād uddhariṣyāmi vānarān', null, 4052007),
('ramayana-4-52-8', 8, 'Kishkindha Kanda, Sarga 52, Verse 8', 'निमीलयत चक्षूंषि सर्वे वानरपुंगवाः।
न हि निष्क्रमितुं शक्यमनिमीलितलोचनैः॥', 'nimīlayata cakṣūṃṣi sarve vānarapuṃgavāḥ
na hi niṣkramituṃ śakyam animīlitalocanaiḥ', null, 4052008),
('ramayana-4-52-9', 9, 'Kishkindha Kanda, Sarga 52, Verse 9', 'ततः संमीलिताः सर्वे सुकुमाराङ्गुलैः करैः।
सहसा पिदधुर्दृष्टिं हृष्टा गमनकाङ्क्षिणः॥', 'tataḥ saṃmīlitāḥ sarve sukumārāṅgulaiḥ karaiḥ
sahasā pidadhur dṛṣṭiṃ hṛṣṭā gamanakāṅkṣiṇaḥ', null, 4052009),
('ramayana-4-52-10', 10, 'Kishkindha Kanda, Sarga 52, Verse 10', 'वानरास्तु महात्मानो हस्तरुद्धमुखास्तदा।
निमेषान्तरमात्रेण बिलादुत्तारितास्तया॥', 'vānarās tu mahātmāno hastaruddhamukhās tadā
nimeṣāntaramātreṇa bilād uttāritās tayā', null, 4052010),
('ramayana-4-52-11', 11, 'Kishkindha Kanda, Sarga 52, Verse 11', 'ततस्तान्वानरान्सर्वांस्तापसी धर्मचारिणी।
निःसृतान्विषमात्तस्मात्समाश्वास्येदमब्रवीत्॥', 'tatas tān vānarān sarvāṃs tāpasī dharmacāriṇī
niḥsṛtān viṣamāt tasmāt samāśvāsyedam abravīt', null, 4052011),
('ramayana-4-52-12', 12, 'Kishkindha Kanda, Sarga 52, Verse 12', 'एष विन्ध्यो गिरिः श्रीमान्नानाद्रुमलतायुतः।
एष प्रसवणः शैलः सागरोऽयं महोदधिः॥', 'eṣa vindhyo giriḥ śrīmān nānādrumalatāyutaḥ
eṣa prasavaṇaḥ śailaḥ sāgaro ''yaṃ mahodadhiḥ', null, 4052012),
('ramayana-4-52-13', 13, 'Kishkindha Kanda, Sarga 52, Verse 13', 'स्वस्ति वोऽस्तु गमिष्यामि भवनं वानरर्षभाः।
इत्युक्त्वा तद्बिलं श्रीमत्प्रविवेश स्वयंप्रभा॥', 'svasti vo ''stu gamiṣyāmi bhavanaṃ vānararṣabhāḥ
ity uktvā tad bilaṃ śrīmat praviveśa svayaṃprabhā', null, 4052013),
('ramayana-4-52-14', 14, 'Kishkindha Kanda, Sarga 52, Verse 14', 'ततस्ते ददृशुर्घोरं सागरं वरुणालयम्।
अपारमभिगर्जन्तं घोरैरूर्मिभिराकुलम्॥', 'tatas te dadṛśur ghoraṃ sāgaraṃ varuṇālayam
apāram abhigarjantaṃ ghorair ūrmibhir ākulam', null, 4052014),
('ramayana-4-52-15', 15, 'Kishkindha Kanda, Sarga 52, Verse 15', 'मयस्य माया विहितं गिरिदुर्गं विचिन्वताम्।
तेषां मासो व्यतिक्रान्तो यो राज्ञा समयः कृतः॥', 'mayasya māyā vihitaṃ giridurgaṃ vicinvatām
teṣāṃ māso vyatikrānto yo rājñā samayaḥ kṛtaḥ', null, 4052015),
('ramayana-4-52-16', 16, 'Kishkindha Kanda, Sarga 52, Verse 16', 'विन्ध्यस्य तु गिरेः पादे संप्रपुष्पितपादपे।
उपविश्य महाभागाश्चिन्तामापेदिरे तदा॥', 'vindhyasya tu gireḥ pāde saṃprapuṣpitapādape
upaviśya mahābhāgāś cintām āpedire tadā', null, 4052016),
('ramayana-4-52-17', 17, 'Kishkindha Kanda, Sarga 52, Verse 17', 'ततः पुष्पातिभाराग्रांल्लताशतसमावृतान्।
द्रुमान्वासन्तिकान्दृष्ट्वा बभूवुर्भयशङ्किताः॥', 'tataḥ puṣpātibhārāgrāṃl latāśatasamāvṛtān
drumān vāsantikān dṛṣṭvā babhūvur bhayaśaṅkitāḥ', null, 4052017),
('ramayana-4-52-18', 18, 'Kishkindha Kanda, Sarga 52, Verse 18', 'ते वसन्तमनुप्राप्तं प्रतिवेद्य परस्परम्।
नष्टसंदेशकालार्था निपेतुर्धरणीतले॥', 'te vasantam anuprāptaṃ prativedya parasparam
naṣṭasaṃdeśakālārthā nipetur dharaṇītale', null, 4052018),
('ramayana-4-52-19', 19, 'Kishkindha Kanda, Sarga 52, Verse 19', 'स तु सिंहर्षभ स्कन्धः पीनायतभुजः कपिः।
युवराजो महाप्राज्ञ अङ्गदो वाक्यमब्रवीत्॥', 'sa tu siṃharṣabha skandhaḥ pīnāyatabhujaḥ kapiḥ
yuvarājo mahāprājña aṅgado vākyam abravīt', null, 4052019),
('ramayana-4-52-20', 20, 'Kishkindha Kanda, Sarga 52, Verse 20', 'शासनात्कपिराजस्य वयं सर्वे विनिर्गताः।
मासः पूर्णो बिलस्थानां हरयः किं न बुध्यते॥', 'śāsanāt kapirājasya vayaṃ sarve vinirgatāḥ
māsaḥ pūrṇo bilasthānāṃ harayaḥ kiṃ na budhyate', null, 4052020),
('ramayana-4-52-21', 21, 'Kishkindha Kanda, Sarga 52, Verse 21', 'तस्मिन्नतीते काले तु सुग्रीवेण कृते स्वयम्।
प्रायोपवेशनं युक्तं सर्वेषां च वनौकसाम्॥', 'tasminn atīte kāle tu sugrīveṇa kṛte svayam
prāyopaveśanaṃ yuktaṃ sarveṣāṃ ca vanaukasām', null, 4052021),
('ramayana-4-52-22', 22, 'Kishkindha Kanda, Sarga 52, Verse 22', 'तीक्ष्णः प्रकृत्या सुग्रीवः स्वामिभावे व्यवस्थितः।
न क्षमिष्यति नः सर्वानपराधकृतो गतान्॥', 'tīkṣṇaḥ prakṛtyā sugrīvaḥ svāmibhāve vyavasthitaḥ
na kṣamiṣyati naḥ sarvān aparādhakṛto gatān', null, 4052022),
('ramayana-4-52-23', 23, 'Kishkindha Kanda, Sarga 52, Verse 23', 'अप्रवृत्तौ च सीतायाः पापमेव करिष्यति।
तस्मात्क्षममिहाद्यैव प्रायोपविशनं हि नः॥', 'apravṛttau ca sītāyāḥ pāpam eva kariṣyati
tasmāt kṣamam ihādyaiva prāyopaviśanaṃ hi naḥ', null, 4052023),
('ramayana-4-52-24', 24, 'Kishkindha Kanda, Sarga 52, Verse 24', 'त्यक्त्वा पुत्रांश्च दारांश्च धनानि च गृहाणि च।
यावन्न घातयेद्राजा सर्वान्प्रतिगतानितः।
वधेनाप्रतिरूपेण श्रेयान्मृत्युरिहैव नः॥', 'tyaktvā putrāṃś ca dārāṃś ca dhanāni ca gṛhāṇi ca
yāvan na ghātayed rājā sarvān pratigatān itaḥ
vadhenāpratirūpeṇa śreyān mṛtyur ihaiva naḥ', null, 4052024),
('ramayana-4-52-25', 25, 'Kishkindha Kanda, Sarga 52, Verse 25', 'न चाहं यौवराज्येन सुग्रीवेणाभिषेचितः।
नरेन्द्रेणाभिषिक्तोऽस्मि रामेणाक्लिष्टकर्मणा॥', 'na cāhaṃ yauvarājyena sugrīveṇābhiṣecitaḥ
narendreṇābhiṣikto ''smi rāmeṇākliṣṭakarmaṇā', null, 4052025),
('ramayana-4-52-26', 26, 'Kishkindha Kanda, Sarga 52, Verse 26', 'स पूर्वं बद्धवैरो मां राजा दृष्ट्वा व्यतिक्रमम्।
घातयिष्यति दण्डेन तीक्ष्णेन कृतनिश्चयः॥', 'sa pūrvaṃ baddhavairo māṃ rājā dṛṣṭvā vyatikramam
ghātayiṣyati daṇḍena tīkṣṇena kṛtaniścayaḥ', null, 4052026),
('ramayana-4-52-27', 27, 'Kishkindha Kanda, Sarga 52, Verse 27', 'किं मे सुहृद्भिर्व्यसनं पश्यद्भिर्जीवितान्तरे।
इहैव प्रायमासिष्ये पुण्ये सागररोधसि॥', 'kiṃ me suhṛdbhir vyasanaṃ paśyadbhir jīvitāntare
ihaiva prāyam āsiṣye puṇye sāgararodhasi', null, 4052027),
('ramayana-4-52-28', 28, 'Kishkindha Kanda, Sarga 52, Verse 28', 'एतच्छ्रुत्वा कुमारेण युवराजेन भाषितम्।
सर्वे ते वानरश्रेष्ठाः करुणं वाक्यमब्रुवन्॥', 'etac chrutvā kumāreṇa yuvarājena bhāṣitam
sarve te vānaraśreṣṭhāḥ karuṇaṃ vākyam abruvan', null, 4052028),
('ramayana-4-52-29', 29, 'Kishkindha Kanda, Sarga 52, Verse 29', 'तीक्ष्णः प्रकृत्या सुग्रीवः प्रियासक्तश्च राघवः।
अदृष्टायां च वैदेह्यां दृष्ट्वास्मांश्च समागतान्॥', 'tīkṣṇaḥ prakṛtyā sugrīvaḥ priyāsaktaś ca rāghavaḥ
adṛṣṭāyāṃ ca vaidehyāṃ dṛṣṭvāsmāṃś ca samāgatān', null, 4052029),
('ramayana-4-52-30', 30, 'Kishkindha Kanda, Sarga 52, Verse 30', 'राघवप्रियकामार्थं घातयिष्यत्यसंशयम्।
न क्षमं चापराद्धानां गमनं स्वामिपार्श्वतः॥', 'rāghavapriyakāmārthaṃ ghātayiṣyaty asaṃśayam
na kṣamaṃ cāparāddhānāṃ gamanaṃ svāmipārśvataḥ', null, 4052030),
('ramayana-4-52-31', 31, 'Kishkindha Kanda, Sarga 52, Verse 31', 'प्लवंगमानां तु भयार्दितानां श्रुत्वा वचस्तार इदं बभाषे।
अलं विषादेन बिलं प्रविश्य वसाम सर्वे यदि रोचते वः॥', 'plavaṃgamānāṃ tu bhayārditānāṃ śrutvā vacas tāra idaṃ babhāṣe
alaṃ viṣādena bilaṃ praviśya vasāma sarve yadi rocate vaḥ', null, 4052031),
('ramayana-4-52-32', 32, 'Kishkindha Kanda, Sarga 52, Verse 32', 'इदं हि माया विहितं सुदुर्गमं प्रभूतवृक्षोदकभोज्यपेयम्।
इहास्ति नो नैव भयं पुरंदरान्न राघवाद्वानरराजतोऽपि वा॥', 'idaṃ hi māyā vihitaṃ sudurgamaṃ prabhūtavṛkṣodakabhojyapeyam
ihāsti no naiva bhayaṃ puraṃdarān na rāghavād vānararājato ''pi vā', null, 4052032),
('ramayana-4-52-33', 33, 'Kishkindha Kanda, Sarga 52, Verse 33', 'श्रुत्वाङ्गदस्यापि वचोऽनुकूलमूचुश्च सर्वे हरयः प्रतीताः।
यथा न हन्येम तथाविधानमसक्तमद्यैव विधीयतां नः॥', 'śrutvāṅgadasyāpi vaco ''nukūlam ūcuś ca sarve harayaḥ pratītāḥ
yathā na hanyema tathāvidhānam asaktam adyaiva vidhīyatāṃ naḥ', null, 4052033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 53 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-53-1', 1, 'Kishkindha Kanda, Sarga 53, Verse 1', 'तथा ब्रुवति तारे तु ताराधिपतिवर्चसि।
अथ मेने हृतं राज्यं हनुमानङ्गदेन तत्॥', 'tathā bruvati tāre tu tārādhipativarcasi
atha mene hṛtaṃ rājyaṃ hanumān aṅgadena tat', null, 4053001),
('ramayana-4-53-2', 2, 'Kishkindha Kanda, Sarga 53, Verse 2', 'बुद्ध्या ह्यष्टाङ्गया युक्तं चतुर्बलसमन्वितम्।
चतुर्दशगुणं मेने हनुमान्वालिनः सुतम्॥', 'buddhyā hy aṣṭāṅgayā yuktaṃ caturbalasamanvitam
caturdaśaguṇaṃ mene hanumān vālinaḥ sutam', null, 4053002),
('ramayana-4-53-3', 3, 'Kishkindha Kanda, Sarga 53, Verse 3', 'आपूर्यमाणं शश्वच्च तेजोबलपराक्रमैः।
शशिनं शुक्लपक्षादौ वर्धमानमिव श्रिया॥', 'āpūryamāṇaṃ śaśvac ca tejobalaparākramaiḥ
śaśinaṃ śuklapakṣādau vardhamānam iva śriyā', null, 4053003),
('ramayana-4-53-4', 4, 'Kishkindha Kanda, Sarga 53, Verse 4', 'बृहस्पतिसमं बुद्ध्या विक्रमे सदृशं पितुः।
शुश्रूषमाणं तारस्य शुक्रस्येव पुरंदरम्॥', 'bṛhaspatisamaṃ buddhyā vikrame sadṛśaṃ pituḥ
śuśrūṣamāṇaṃ tārasya śukrasyeva puraṃdaram', null, 4053004),
('ramayana-4-53-5', 5, 'Kishkindha Kanda, Sarga 53, Verse 5', 'भर्तुरर्थे परिश्रान्तं सर्वशास्त्रविशारदम्।
अभिसंधातुमारेभे हनुमानङ्गदं ततः॥', 'bhartur arthe pariśrāntaṃ sarvaśāstraviśāradam
abhisaṃdhātum ārebhe hanumān aṅgadaṃ tataḥ', null, 4053005),
('ramayana-4-53-6', 6, 'Kishkindha Kanda, Sarga 53, Verse 6', 'स चतुर्णामुपायानां तृतीयमुपवर्णयन्।
भेदयामास तान्सर्वान्वानरान्वाक्यसंपदा॥', 'sa caturṇām upāyānāṃ tṛtīyam upavarṇayan
bhedayām āsa tān sarvān vānarān vākyasaṃpadā', null, 4053006),
('ramayana-4-53-7', 7, 'Kishkindha Kanda, Sarga 53, Verse 7', 'तेषु सर्वेषु भिन्नेषु ततोऽभीषयदङ्गदम्।
भीषणैर्बहुभिर्वाक्यैः कोपोपायसमन्वितैः॥', 'teṣu sarveṣu bhinneṣu tato ''bhīṣayad aṅgadam
bhīṣaṇair bahubhir vākyaiḥ kopopāyasamanvitaiḥ', null, 4053007),
('ramayana-4-53-8', 8, 'Kishkindha Kanda, Sarga 53, Verse 8', 'त्वं समर्थतरः पित्रा युद्धे तारेय वै धुरम्।
दृढं धारयितुं शक्तः कपिराज्यं यथा पिता॥', 'tvaṃ samarthataraḥ pitrā yuddhe tāreya vai dhuram
dṛḍhaṃ dhārayituṃ śaktaḥ kapirājyaṃ yathā pitā', null, 4053008),
('ramayana-4-53-9', 9, 'Kishkindha Kanda, Sarga 53, Verse 9', 'नित्यमस्थिरचित्ता हि कपयो हरिपुंगव।
नाज्ञाप्यं विषहिष्यन्ति पुत्रदारान्विना त्वया॥', 'nityam asthiracittā hi kapayo haripuṃgava
nājñāpyaṃ viṣahiṣyanti putradārān vinā tvayā', null, 4053009),
('ramayana-4-53-10', 10, 'Kishkindha Kanda, Sarga 53, Verse 10', 'त्वां नैते ह्यनुयुञ्जेयुः प्रत्यक्षं प्रवदामि ते।
यथायं जाम्बवान्नीलः सुहोत्रश्च महाकपिः॥', 'tvāṃ naite hy anuyuñjeyuḥ pratyakṣaṃ pravadāmi te
yathāyaṃ jāmbavān nīlaḥ suhotraś ca mahākapiḥ', null, 4053010),
('ramayana-4-53-11', 11, 'Kishkindha Kanda, Sarga 53, Verse 11', 'न ह्यहं त इमे सर्वे सामदानादिभिर्गुणैः।
दण्डेन न त्वया शक्याः सुग्रीवादपकर्षितुम्॥', 'na hy ahaṃ ta ime sarve sāmadānādibhir guṇaiḥ
daṇḍena na tvayā śakyāḥ sugrīvād apakarṣitum', null, 4053011),
('ramayana-4-53-12', 12, 'Kishkindha Kanda, Sarga 53, Verse 12', 'विगृह्यासनमप्याहुर्दुर्बलेन बलीयसः।
आत्मरक्षाकरस्तस्मान्न विगृह्णीत दुर्बलः॥', 'vigṛhyāsanam apy āhur durbalena balīyasaḥ
ātmarakṣākaras tasmān na vigṛhṇīta durbalaḥ', null, 4053012),
('ramayana-4-53-13', 13, 'Kishkindha Kanda, Sarga 53, Verse 13', 'यां चेमां मन्यसे धात्रीमेतद्बिलमिति श्रुतम्।
एतल्लक्ष्मणबाणानामीषत्कार्यं विदारणे॥', 'yāṃ cemāṃ manyase dhātrīm etad bilam iti śrutam
etal lakṣmaṇabāṇānām īṣatkāryaṃ vidāraṇe', null, 4053013),
('ramayana-4-53-14', 14, 'Kishkindha Kanda, Sarga 53, Verse 14', 'स्वल्पं हि कृतमिन्द्रेण क्षिपता ह्यशनिं पुरा।
लक्ष्मणो निशितैर्बाणैर्भिन्द्यात्पत्रपुटं यथा।
लक्ष्मणस्य च नाराचा बहवः सन्ति तद्विधाः॥', 'svalpaṃ hi kṛtam indreṇa kṣipatā hy aśaniṃ purā
lakṣmaṇo niśitair bāṇair bhindyāt patrapuṭaṃ yathā
lakṣmaṇasya ca nārācā bahavaḥ santi tadvidhāḥ', null, 4053014),
('ramayana-4-53-15', 15, 'Kishkindha Kanda, Sarga 53, Verse 15', 'अवस्थाने यदैव त्वमासिष्यसि परंतप।
तदैव हरयः सर्वे त्यक्ष्यन्ति कृतनिश्चयाः॥', 'avasthāne yadaiva tvam āsiṣyasi paraṃtapa
tadaiva harayaḥ sarve tyakṣyanti kṛtaniścayāḥ', null, 4053015),
('ramayana-4-53-16', 16, 'Kishkindha Kanda, Sarga 53, Verse 16', 'स्मरन्तः पुत्रदाराणां नित्योद्विग्ना बुभुक्षिताः।
खेदिता दुःखशय्याभिस्त्वां करिष्यन्ति पृष्ठतः॥', 'smarantaḥ putradārāṇāṃ nityodvignā bubhukṣitāḥ
kheditā duḥkhaśayyābhis tvāṃ kariṣyanti pṛṣṭhataḥ', null, 4053016),
('ramayana-4-53-17', 17, 'Kishkindha Kanda, Sarga 53, Verse 17', 'स त्वं हीनः सुहृद्भिश्च हितकामैश्च बन्धुभिः।
तृणादपि भृशोद्विग्नः स्पन्दमानाद्भविष्यसि॥', 'sa tvaṃ hīnaḥ suhṛdbhiś ca hitakāmaiś ca bandhubhiḥ
tṛṇād api bhṛśodvignaḥ spandamānād bhaviṣyasi', null, 4053017),
('ramayana-4-53-18', 18, 'Kishkindha Kanda, Sarga 53, Verse 18', 'न च जातु न हिंस्युस्त्वां घोरा लक्ष्मणसायकाः।
अपवृत्तं जिघांसन्तो महावेगा दुरासदाः॥', 'na ca jātu na hiṃsyus tvāṃ ghorā lakṣmaṇasāyakāḥ
apavṛttaṃ jighāṃsanto mahāvegā durāsadāḥ', null, 4053018),
('ramayana-4-53-19', 19, 'Kishkindha Kanda, Sarga 53, Verse 19', 'अस्माभिस्तु गतं सार्धं विनीतवदुपस्थितम्।
आनुपूर्व्यात्तु सुग्रीवो राज्ये त्वां स्थापयिष्यति॥', 'asmābhis tu gataṃ sārdhaṃ vinītavad upasthitam
ānupūrvyāt tu sugrīvo rājye tvāṃ sthāpayiṣyati', null, 4053019),
('ramayana-4-53-20', 20, 'Kishkindha Kanda, Sarga 53, Verse 20', 'धर्मकामः पितृव्यस्ते प्रीतिकामो दृढव्रतः।
शुचिः सत्यप्रतिज्ञश्च ना त्वां जातु जिघांसति॥', 'dharmakāmaḥ pitṛvyas te prītikāmo dṛḍhavrataḥ
śuciḥ satyapratijñaś ca nā tvāṃ jātu jighāṃsati', null, 4053020),
('ramayana-4-53-21', 21, 'Kishkindha Kanda, Sarga 53, Verse 21', 'प्रियकामश्च ते मातुस्तदर्थं चास्य जीवितम्।
तस्यापत्यं च नास्त्यन्यत्तस्मादङ्गद गम्यताम्॥', 'priyakāmaś ca te mātus tadarthaṃ cāsya jīvitam
tasyāpatyaṃ ca nāsty anyat tasmād aṅgada gamyatām', null, 4053021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 54 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-54-1', 1, 'Kishkindha Kanda, Sarga 54, Verse 1', 'श्रुत्वा हनुमतो वाक्यं प्रश्रितं धर्मसंहितम्।
स्वामिसत्कारसंयुक्तमङ्गदो वाक्यमब्रवीत्॥', 'śrutvā hanumato vākyaṃ praśritaṃ dharmasaṃhitam
svāmisatkārasaṃyuktam aṅgado vākyam abravīt', null, 4054001),
('ramayana-4-54-2', 2, 'Kishkindha Kanda, Sarga 54, Verse 2', 'स्थैर्यं सर्वात्मना शौचमानृशंस्यमथार्जवम्।
विक्रमैश्चैव धैर्यं च सुग्रीवे नोपपद्यते॥', 'sthairyaṃ sarvātmanā śaucam ānṛśaṃsyam athārjavam
vikramaiś caiva dhairyaṃ ca sugrīve nopapadyate', null, 4054002),
('ramayana-4-54-3', 3, 'Kishkindha Kanda, Sarga 54, Verse 3', 'भ्रातुर्ज्येष्ठस्य यो भार्यां जीवितो महिषीं प्रियाम्।
धर्मेण मातरं यस्तु स्वीकरोति जुगुप्सितः॥', 'bhrātur jyeṣṭhasya yo bhāryāṃ jīvito mahiṣīṃ priyām
dharmeṇa mātaraṃ yas tu svīkaroti jugupsitaḥ', null, 4054003),
('ramayana-4-54-4', 4, 'Kishkindha Kanda, Sarga 54, Verse 4', 'कथं स धर्मं जानीते येन भ्रात्रा दुरात्मना।
युद्धायाभिनियुक्तेन बिलस्य पिहितं मुखम्॥', 'kathaṃ sa dharmaṃ jānīte yena bhrātrā durātmanā
yuddhāyābhiniyuktena bilasya pihitaṃ mukham', null, 4054004),
('ramayana-4-54-5', 5, 'Kishkindha Kanda, Sarga 54, Verse 5', 'सत्यात्पाणिगृहीतश्च कृतकर्मा महायशाः।
विस्मृतो राघवो येन स कस्य सुकृतं स्मरेत्॥', 'satyāt pāṇigṛhītaś ca kṛtakarmā mahāyaśāḥ
vismṛto rāghavo yena sa kasya sukṛtaṃ smaret', null, 4054005),
('ramayana-4-54-6', 6, 'Kishkindha Kanda, Sarga 54, Verse 6', 'लक्ष्मणस्य भयाद्येन नाधर्मभयभीरुणा।
आदिष्टा मार्गितुं सीतां धर्ममस्मिन्कथं भवेत्॥', 'lakṣmaṇasya bhayād yena nādharmabhayabhīruṇā
ādiṣṭā mārgituṃ sītāṃ dharmam asmin kathaṃ bhavet', null, 4054006),
('ramayana-4-54-7', 7, 'Kishkindha Kanda, Sarga 54, Verse 7', 'तस्मिन्पापे कृतघ्ने तु स्मृतिहीने चलात्मनि।
आर्यः को विश्वसेज्जातु तत्कुलीनो जिजीविषुः॥', 'tasmin pāpe kṛtaghne tu smṛtihīne calātmani
āryaḥ ko viśvasej jātu tat kulīno jijīviṣuḥ', null, 4054007),
('ramayana-4-54-8', 8, 'Kishkindha Kanda, Sarga 54, Verse 8', 'राज्ये पुत्रं प्रतिष्ठाप्य सगुणो निर्गुणोऽपि वा।
कथं शत्रुकुलीनं मां सुग्रीवो जीवयिष्यति॥', 'rājye putraṃ pratiṣṭhāpya saguṇo nirguṇo ''pi vā
kathaṃ śatrukulīnaṃ māṃ sugrīvo jīvayiṣyati', null, 4054008),
('ramayana-4-54-9', 9, 'Kishkindha Kanda, Sarga 54, Verse 9', 'भिन्नमन्त्रोऽपराद्धश्च हीनशक्तिः कथं ह्यहम्।
किष्किन्धां प्राप्य जीवेयमनाथ इव दुर्बलः॥', 'bhinnamantro ''parāddhaś ca hīnaśaktiḥ kathaṃ hy aham
kiṣkindhāṃ prāpya jīveyam anātha iva durbalaḥ', null, 4054009),
('ramayana-4-54-10', 10, 'Kishkindha Kanda, Sarga 54, Verse 10', 'उपांशुदण्डेन हि मां बन्धनेनोपपादयेत्।
शठः क्रूरो नृशंसश्च सुग्रीवो राज्यकारणात्॥', 'upāṃśudaṇḍena hi māṃ bandhanenopapādayet
śaṭhaḥ krūro nṛśaṃsaś ca sugrīvo rājyakāraṇāt', null, 4054010),
('ramayana-4-54-11', 11, 'Kishkindha Kanda, Sarga 54, Verse 11', 'बन्धनाच्चावसादान्मे श्रेयः प्रायोपवेशनम्।
अनुजानीत मां सर्वे गृहान्गच्छन्तु वानराः॥', 'bandhanāc cāvasādān me śreyaḥ prāyopaveśanam
anujānīta māṃ sarve gṛhān gacchantu vānarāḥ', null, 4054011),
('ramayana-4-54-12', 12, 'Kishkindha Kanda, Sarga 54, Verse 12', 'अहं वः प्रतिजानामि न गमिष्याम्यहं पुरीम्।
इहैव प्रायमासिष्ये श्रेयो मरणमेव मे॥', 'ahaṃ vaḥ pratijānāmi na gamiṣyāmy ahaṃ purīm
ihaiva prāyam āsiṣye śreyo maraṇam eva me', null, 4054012),
('ramayana-4-54-13', 13, 'Kishkindha Kanda, Sarga 54, Verse 13', 'अभिवादनपूर्वं तु राजा कुशलमेव च।
वाच्यस्ततो यवीयान्मे सुग्रीवो वानरेश्वरः॥', 'abhivādanapūrvaṃ tu rājā kuśalam eva ca
vācyas tato yavīyān me sugrīvo vānareśvaraḥ', null, 4054013),
('ramayana-4-54-14', 14, 'Kishkindha Kanda, Sarga 54, Verse 14', 'आरोग्यपूर्वं कुशलं वाच्या माता रुमा च मे।
मातरं चैव मे तारामाश्वासयितुमर्हथ॥', 'ārogyapūrvaṃ kuśalaṃ vācyā mātā rumā ca me
mātaraṃ caiva me tārām āśvāsayitum arhatha', null, 4054014),
('ramayana-4-54-15', 15, 'Kishkindha Kanda, Sarga 54, Verse 15', 'प्रकृत्या प्रियपुत्रा सा सानुक्रोशा तपस्विनी।
विनष्टं मामिह श्रुत्वा व्यक्तं हास्यति जीवितम्॥', 'prakṛtyā priyaputrā sā sānukrośā tapasvinī
vinaṣṭaṃ mām iha śrutvā vyaktaṃ hāsyati jīvitam', null, 4054015),
('ramayana-4-54-16', 16, 'Kishkindha Kanda, Sarga 54, Verse 16', 'एतावदुक्त्वा वचनं वृद्धानप्यभिवाद्य च।
संविवेशाङ्गदो भूमौ रुदन्दर्भेषु दुर्मनाः॥', 'etāvad uktvā vacanaṃ vṛddhān apy abhivādya ca
saṃviveśāṅgado bhūmau rudan darbheṣu durmanāḥ', null, 4054016),
('ramayana-4-54-17', 17, 'Kishkindha Kanda, Sarga 54, Verse 17', 'तस्य संविशतस्तत्र रुदन्तो वानरर्षभाः।
नयनेभ्यः प्रमुमुचुरुष्णं वै वारिदुःखिताः॥', 'tasya saṃviśatas tatra rudanto vānararṣabhāḥ
nayanebhyaḥ pramumucur uṣṇaṃ vai vāriduḥkhitāḥ', null, 4054017),
('ramayana-4-54-18', 18, 'Kishkindha Kanda, Sarga 54, Verse 18', 'सुग्रीवं चैव निन्दन्तः प्रशंसन्तश्च वालिनम्।
परिवार्याङ्गदो सर्वे व्यवस्यन्प्रायमासितुम्॥', 'sugrīvaṃ caiva nindantaḥ praśaṃsantaś ca vālinam
parivāryāṅgado sarve vyavasyan prāyam āsitum', null, 4054018),
('ramayana-4-54-19', 19, 'Kishkindha Kanda, Sarga 54, Verse 19', 'मतं तद्वालिपुत्रस्य विज्ञाय प्लवगर्षभाः।
उपस्पृश्योदकं सर्वे प्राङ्मुखाः समुपाविशन्।
दक्षिणाग्रेषु दर्भेषु उदक्तीरं समाश्रिताः॥', 'mataṃ tad vāliputrasya vijñāya plavagarṣabhāḥ
upaspṛśyodakaṃ sarve prāṅmukhāḥ samupāviśan
dakṣiṇāgreṣu darbheṣu udaktīraṃ samāśritāḥ', null, 4054019),
('ramayana-4-54-20', 20, 'Kishkindha Kanda, Sarga 54, Verse 20', 'स संविशद्भिर्बहुभिर्महीधरो महाद्रिकूटप्रमितैः प्लवंगमैः॥', 'sa saṃviśadbhir bahubhir mahīdharo mahādrikūṭapramitaiḥ plavaṃgamaiḥ', null, 4054020),
('ramayana-4-54-21', 21, 'Kishkindha Kanda, Sarga 54, Verse 21', 'बभूव संनादितनिर्झरान्तरो भृशं नदद्भिर्जलदैरिवोल्बणैः॥', 'babhūva saṃnāditanirjharāntaro bhṛśaṃ nadadbhir jaladair ivolbaṇaiḥ', null, 4054021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 55 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-55-1', 1, 'Kishkindha Kanda, Sarga 55, Verse 1', 'उपविष्टास्तु ते सर्वे यस्मिन्प्रायं गिरिस्थले।
हरयो गृध्रराजश्च तं देशमुपचक्रमे॥', 'upaviṣṭās tu te sarve yasmin prāyaṃ giristhale
harayo gṛdhrarājaś ca taṃ deśam upacakrame', null, 4055001),
('ramayana-4-55-2', 2, 'Kishkindha Kanda, Sarga 55, Verse 2', 'साम्पातिर्नाम नाम्ना तु चिरजीवी विहंगमः।
भ्राता जटायुषः श्रीमान्प्रख्यातबलपौरुषः॥', 'sāmpātir nāma nāmnā tu cirajīvī vihaṃgamaḥ
bhrātā jaṭāyuṣaḥ śrīmān prakhyātabalapauruṣaḥ', null, 4055002),
('ramayana-4-55-3', 3, 'Kishkindha Kanda, Sarga 55, Verse 3', 'कन्दरादभिनिष्क्रम्य स विन्ध्यस्य महागिरेः।
उपविष्टान्हरीन्दृष्ट्वा हृष्टात्मा गिरमब्रवीत्॥', 'kandarād abhiniṣkramya sa vindhyasya mahāgireḥ
upaviṣṭān harīn dṛṣṭvā hṛṣṭātmā giram abravīt', null, 4055003),
('ramayana-4-55-4', 4, 'Kishkindha Kanda, Sarga 55, Verse 4', 'विधिः किल नरं लोके विधानेनानुवर्तते।
यथायं विहितो भक्ष्यश्चिरान्मह्यमुपागतः॥', 'vidhiḥ kila naraṃ loke vidhānenānuvartate
yathāyaṃ vihito bhakṣyaś cirān mahyam upāgataḥ', null, 4055004),
('ramayana-4-55-5', 5, 'Kishkindha Kanda, Sarga 55, Verse 5', 'परम्पराणां भक्षिष्ये वानराणां मृतं मृतम्।
उवाचैवं वचः पक्षी तान्निरीक्ष्य प्लवंगमान्॥', 'paramparāṇāṃ bhakṣiṣye vānarāṇāṃ mṛtaṃ mṛtam
uvācaivaṃ vacaḥ pakṣī tān nirīkṣya plavaṃgamān', null, 4055005),
('ramayana-4-55-6', 6, 'Kishkindha Kanda, Sarga 55, Verse 6', 'तस्य तद्वचनं श्रुत्वा भक्षलुब्धस्य पक्षिणः।
अङ्गदः परमायस्तो हनूमन्तमथाब्रवीत्॥', 'tasya tad vacanaṃ śrutvā bhakṣalubdhasya pakṣiṇaḥ
aṅgadaḥ param āyasto hanūmantam athābravīt', null, 4055006),
('ramayana-4-55-7', 7, 'Kishkindha Kanda, Sarga 55, Verse 7', 'पश्य सीतापदेशेन साक्षाद्वैवस्वतो यमः।
इमं देशमनुप्राप्तो वानराणां विपत्तये॥', 'paśya sītāpadeśena sākṣād vaivasvato yamaḥ
imaṃ deśam anuprāpto vānarāṇāṃ vipattaye', null, 4055007),
('ramayana-4-55-8', 8, 'Kishkindha Kanda, Sarga 55, Verse 8', 'रामस्य न कृतं कार्यं राज्ञो न च वचः कृतम्।
हरीणामियमज्ञाता विपत्तिः सहसागता॥', 'rāmasya na kṛtaṃ kāryaṃ rājño na ca vacaḥ kṛtam
harīṇām iyam ajñātā vipattiḥ sahasāgatā', null, 4055008),
('ramayana-4-55-9', 9, 'Kishkindha Kanda, Sarga 55, Verse 9', 'वैदेह्याः प्रियकामेन कृतं कर्म जटायुषा।
गृध्रराजेन यत्तत्र श्रुतं वस्तदशेषतः॥', 'vaidehyāḥ priyakāmena kṛtaṃ karma jaṭāyuṣā
gṛdhrarājena yat tatra śrutaṃ vas tad aśeṣataḥ', null, 4055009),
('ramayana-4-55-10', 10, 'Kishkindha Kanda, Sarga 55, Verse 10', 'तथा सर्वाणि भूतानि तिर्यग्योनिगतान्यपि।
प्रियं कुर्वन्ति रामस्य त्यक्त्वा प्राणान्यथा वयम्॥', 'tathā sarvāṇi bhūtāni tiryagyonigatāny api
priyaṃ kurvanti rāmasya tyaktvā prāṇān yathā vayam', null, 4055010),
('ramayana-4-55-11', 11, 'Kishkindha Kanda, Sarga 55, Verse 11', 'राघवार्थे परिश्रान्ता वयं संत्यक्तजीविताः।
कान्ताराणि प्रपन्नाः स्म न च पश्याम मैथिलीम्॥', 'rāghavārthe pariśrāntā vayaṃ saṃtyaktajīvitāḥ
kāntārāṇi prapannāḥ sma na ca paśyāma maithilīm', null, 4055011),
('ramayana-4-55-12', 12, 'Kishkindha Kanda, Sarga 55, Verse 12', 'स सुखी गृध्रराजस्तु रावणेन हतो रणे।
मुक्तश्च सुग्रीवभयाद्गतश्च परमां गतिम्॥', 'sa sukhī gṛdhrarājas tu rāvaṇena hato raṇe
muktaś ca sugrīvabhayād gataś ca paramāṃ gatim', null, 4055012),
('ramayana-4-55-13', 13, 'Kishkindha Kanda, Sarga 55, Verse 13', 'जटायुषो विनाशेन राज्ञो दशरथस्य च।
हरणेन च वैदेह्याः संशयं हरयो गताः॥', 'jaṭāyuṣo vināśena rājño daśarathasya ca
haraṇena ca vaidehyāḥ saṃśayaṃ harayo gatāḥ', null, 4055013),
('ramayana-4-55-14', 14, 'Kishkindha Kanda, Sarga 55, Verse 14', 'रामलक्ष्मणयोर्वासामरण्ये सह सीतया।
राघवस्य च बाणेन वालिनश्च तथा वधः॥', 'rāmalakṣmaṇayor vāsām araṇye saha sītayā
rāghavasya ca bāṇena vālinaś ca tathā vadhaḥ', null, 4055014),
('ramayana-4-55-15', 15, 'Kishkindha Kanda, Sarga 55, Verse 15', 'रामकोपादशेषाणां राक्षसानां तथा वधः।
कैकेय्या वरदानेन इदं हि विकृतं कृतम्॥', 'rāmakopād aśeṣāṇāṃ rākṣasānāṃ tathā vadhaḥ
kaikeyyā varadānena idaṃ hi vikṛtaṃ kṛtam', null, 4055015),
('ramayana-4-55-16', 16, 'Kishkindha Kanda, Sarga 55, Verse 16', 'तत्तु श्रुत्वा तदा वाक्यमङ्गदस्य मुखोद्गतम्।
अब्रवीद्वचनं गृध्रस्तीक्ष्णतुण्डो महास्वनः॥', 'tat tu śrutvā tadā vākyam aṅgadasya mukhodgatam
abravīd vacanaṃ gṛdhras tīkṣṇatuṇḍo mahāsvanaḥ', null, 4055016),
('ramayana-4-55-17', 17, 'Kishkindha Kanda, Sarga 55, Verse 17', 'कोऽयं गिरा घोषयति प्राणैः प्रियतरस्य मे।
जटायुषो वधं भ्रातुः कम्पयन्निव मे मनः॥', 'ko ''yaṃ girā ghoṣayati prāṇaiḥ priyatarasya me
jaṭāyuṣo vadhaṃ bhrātuḥ kampayann iva me manaḥ', null, 4055017),
('ramayana-4-55-18', 18, 'Kishkindha Kanda, Sarga 55, Verse 18', 'कथमासीज्जनस्थाने युद्धं राक्षसगृध्रयोः।
नामधेयमिदं भ्रातुश्चिरस्याद्य मया श्रुतम्॥', 'katham āsīj janasthāne yuddhaṃ rākṣasagṛdhrayoḥ
nāmadheyam idaṃ bhrātuś cirasyādya mayā śrutam', null, 4055018),
('ramayana-4-55-19', 19, 'Kishkindha Kanda, Sarga 55, Verse 19', 'यवीयसो गुणज्ञस्य श्लाघनीयस्य विक्रमैः।
तदिच्छेयमहं श्रोतुं विनाशं वानरर्षभाः॥', 'yavīyaso guṇajñasya ślāghanīyasya vikramaiḥ
tad iccheyam ahaṃ śrotuṃ vināśaṃ vānararṣabhāḥ', null, 4055019),
('ramayana-4-55-20', 20, 'Kishkindha Kanda, Sarga 55, Verse 20', 'भ्रातुर्जटायुषस्तस्य जनस्थाननिवासिनः।
तस्यैव च मम भ्रातुः सखा दशरथः कथम्।
यस्य रामः प्रियः पुत्रो ज्येष्ठो गुरुजनप्रियः॥', 'bhrātur jaṭāyuṣas tasya janasthānanivāsinaḥ
tasyaiva ca mama bhrātuḥ sakhā daśarathaḥ katham
yasya rāmaḥ priyaḥ putro jyeṣṭho gurujanapriyaḥ', null, 4055020),
('ramayana-4-55-21', 21, 'Kishkindha Kanda, Sarga 55, Verse 21', 'सूर्यांशुदग्धपक्षत्वान्न शक्नोमि विसर्पितुम्।
इच्छेयं पर्वतादस्मादवतर्तुमरिंदमाः॥', 'sūryāṃśudagdhapakṣatvān na śaknomi visarpitum
iccheyaṃ parvatād asmād avatartum ariṃdamāḥ', null, 4055021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 56 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-56-1', 1, 'Kishkindha Kanda, Sarga 56, Verse 1', 'शोकाद्भ्रष्टस्वरमपि श्रुत्वा ते हरियूथपाः।
श्रद्दधुर्नैव तद्वाक्यं कर्मणा तस्य शङ्किताः॥', 'śokād bhraṣṭasvaram api śrutvā te hariyūthapāḥ
śraddadhur naiva tad vākyaṃ karmaṇā tasya śaṅkitāḥ', null, 4056001),
('ramayana-4-56-2', 2, 'Kishkindha Kanda, Sarga 56, Verse 2', 'ते प्रायमुपविष्टास्तु दृष्ट्वा गृध्रं प्लवंगमाः।
चक्रुर्बुद्धिं तदा रौद्रां सर्वान्नो भक्षयिष्यति॥', 'te prāyam upaviṣṭās tu dṛṣṭvā gṛdhraṃ plavaṃgamāḥ
cakrur buddhiṃ tadā raudrāṃ sarvān no bhakṣayiṣyati', null, 4056002),
('ramayana-4-56-3', 3, 'Kishkindha Kanda, Sarga 56, Verse 3', 'सर्वथा प्रायमासीनान्यदि नो भक्षयिष्यति।
कृतकृत्या भविष्यामः क्षिप्रं सिद्धिमितो गताः॥', 'sarvathā prāyam āsīnān yadi no bhakṣayiṣyati
kṛtakṛtyā bhaviṣyāmaḥ kṣipraṃ siddhim ito gatāḥ', null, 4056003),
('ramayana-4-56-4', 4, 'Kishkindha Kanda, Sarga 56, Verse 4', 'एतां बुद्धिं ततश्चक्रुः सर्वे ते वानरर्षभाः।
अवतार्य गिरेः शृङ्गाद्गृध्रमाहाङ्गदस्तदा॥', 'etāṃ buddhiṃ tataś cakruḥ sarve te vānararṣabhāḥ
avatārya gireḥ śṛṅgād gṛdhram āhāṅgadas tadā', null, 4056004),
('ramayana-4-56-5', 5, 'Kishkindha Kanda, Sarga 56, Verse 5', 'बभूवुर्क्षरजो नाम वानरेन्द्रः प्रतापवान्।
ममार्यः पार्थिवः पक्षिन्धार्मिकौ तस्य चात्मजौ॥', 'babhūvur kṣarajo nāma vānarendraḥ pratāpavān
mamāryaḥ pārthivaḥ pakṣin dhārmikau tasya cātmajau', null, 4056005),
('ramayana-4-56-6', 6, 'Kishkindha Kanda, Sarga 56, Verse 6', 'सुग्रीवश्चैव वली च पुत्रावोघबलावुभौ।
लोके विश्रुतकर्माभूद्राजा वाली पिता मम॥', 'sugrīvaś caiva valī ca putrāv oghabalāv ubhau
loke viśrutakarmābhūd rājā vālī pitā mama', null, 4056006),
('ramayana-4-56-7', 7, 'Kishkindha Kanda, Sarga 56, Verse 7', 'राजा कृत्स्नस्य जगत इक्ष्वाकूणां महारथः।
रामो दाशरथिः श्रीमान्प्रविष्टो दण्डकावनम्॥', 'rājā kṛtsnasya jagata ikṣvākūṇāṃ mahārathaḥ
rāmo dāśarathiḥ śrīmān praviṣṭo daṇḍakāvanam', null, 4056007),
('ramayana-4-56-8', 8, 'Kishkindha Kanda, Sarga 56, Verse 8', 'लक्ष्मणेन सह भ्रात्रा वैदेह्या चापि भार्यया।
पितुर्निदेशनिरतो धर्म्यं पन्थानमाश्रितः।
तस्य भार्या जनस्थानाद्रावणेन हृता बलात्॥', 'lakṣmaṇena saha bhrātrā vaidehyā cāpi bhāryayā
pitur nideśanirato dharmyaṃ panthānam āśritaḥ
tasya bhāryā janasthānād rāvaṇena hṛtā balāt', null, 4056008),
('ramayana-4-56-9', 9, 'Kishkindha Kanda, Sarga 56, Verse 9', 'रामस्य च पितुर्मित्रं जटायुर्नाम गृध्रराट्।
ददर्श सीतां वैदेहीं ह्रियमाणां विहायसा॥', 'rāmasya ca pitur mitraṃ jaṭāyur nāma gṛdhrarāṭ
dadarśa sītāṃ vaidehīṃ hriyamāṇāṃ vihāyasā', null, 4056009),
('ramayana-4-56-10', 10, 'Kishkindha Kanda, Sarga 56, Verse 10', 'रावणं विरथं कृत्वा स्थापयित्वा च मैथिलीम्।
परिश्रान्तश्च वृद्धश्च रावणेन हतो रणे॥', 'rāvaṇaṃ virathaṃ kṛtvā sthāpayitvā ca maithilīm
pariśrāntaś ca vṛddhaś ca rāvaṇena hato raṇe', null, 4056010),
('ramayana-4-56-11', 11, 'Kishkindha Kanda, Sarga 56, Verse 11', 'एवं गृध्रो हतस्तेन रावणेन बहीयसा।
संस्कृतश्चापि रामेण गतश्च गतिमुत्तमाम्॥', 'evaṃ gṛdhro hatas tena rāvaṇena bahīyasā
saṃskṛtaś cāpi rāmeṇa gataś ca gatim uttamām', null, 4056011),
('ramayana-4-56-12', 12, 'Kishkindha Kanda, Sarga 56, Verse 12', 'ततो मम पितृव्येण सुग्रीवेण महात्मना।
चकार राघवः सख्यं सोऽवधीत्पितरं मम॥', 'tato mama pitṛvyeṇa sugrīveṇa mahātmanā
cakāra rāghavaḥ sakhyaṃ so ''vadhīt pitaraṃ mama', null, 4056012),
('ramayana-4-56-13', 13, 'Kishkindha Kanda, Sarga 56, Verse 13', 'माम पित्रा विरुद्धो हि सुग्रीवः सचिवैः सह।
निहत्य वालिनं रामस्ततस्तमभिषेचयत्॥', 'māma pitrā viruddho hi sugrīvaḥ sacivaiḥ saha
nihatya vālinaṃ rāmas tatas tam abhiṣecayat', null, 4056013),
('ramayana-4-56-14', 14, 'Kishkindha Kanda, Sarga 56, Verse 14', 'स राज्ये स्थापितस्तेन सुग्रीवो वानरेश्वरः।
राजा वानरमुख्यानां येन प्रस्थापिता वयम्॥', 'sa rājye sthāpitas tena sugrīvo vānareśvaraḥ
rājā vānaramukhyānāṃ yena prasthāpitā vayam', null, 4056014),
('ramayana-4-56-15', 15, 'Kishkindha Kanda, Sarga 56, Verse 15', 'एवं रामप्रयुक्तास्तु मार्गमाणास्ततस्ततः।
वैदेहीं नाधिगच्छामो रात्रौ सूर्यप्रभामिव॥', 'evaṃ rāmaprayuktās tu mārgamāṇās tatas tataḥ
vaidehīṃ nādhigacchāmo rātrau sūryaprabhām iva', null, 4056015),
('ramayana-4-56-16', 16, 'Kishkindha Kanda, Sarga 56, Verse 16', 'ते वयं दण्दकारण्यं विचित्य सुसमाहिताः।
अज्ञानात्तु प्रविष्टाः स्म धरण्या विवृतं बिलम्॥', 'te vayaṃ daṇdakāraṇyaṃ vicitya susamāhitāḥ
ajñānāt tu praviṣṭāḥ sma dharaṇyā vivṛtaṃ bilam', null, 4056016),
('ramayana-4-56-17', 17, 'Kishkindha Kanda, Sarga 56, Verse 17', 'मयस्य माया विहितं तद्बिलं च विचिन्वताम्।
व्यतीतस्तत्र नो मासो यो राज्ञा सामयः कृतः॥', 'mayasya māyā vihitaṃ tad bilaṃ ca vicinvatām
vyatītas tatra no māso yo rājñā sāmayaḥ kṛtaḥ', null, 4056017),
('ramayana-4-56-18', 18, 'Kishkindha Kanda, Sarga 56, Verse 18', 'ते वयं कपिराजस्य सर्वे वचनकारिणः।
कृतां संस्थामतिक्रान्ता भयात्प्रायमुपास्महे॥', 'te vayaṃ kapirājasya sarve vacanakāriṇaḥ
kṛtāṃ saṃsthām atikrāntā bhayāt prāyam upāsmahe', null, 4056018),
('ramayana-4-56-19', 19, 'Kishkindha Kanda, Sarga 56, Verse 19', 'क्रुद्धे तस्मिंस्तु काकुत्स्थे सुग्रीवे च सलक्ष्मणे।
गतानामपि सर्वेषां तत्र नो नास्ति जीवितम्॥', 'kruddhe tasmiṃs tu kākutsthe sugrīve ca salakṣmaṇe
gatānām api sarveṣāṃ tatra no nāsti jīvitam', null, 4056019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 57 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-57-1', 1, 'Kishkindha Kanda, Sarga 57, Verse 1', 'इत्युक्तः करुणं वाक्यं वानरैस्त्यक्तजीवितैः।
सबाष्पो वानरान्गृध्रः प्रत्युवाच महास्वनः॥', 'ity uktaḥ karuṇaṃ vākyaṃ vānarais tyaktajīvitaiḥ
sabāṣpo vānarān gṛdhraḥ pratyuvāca mahāsvanaḥ', null, 4057001),
('ramayana-4-57-2', 2, 'Kishkindha Kanda, Sarga 57, Verse 2', 'यवीयान्मम स भ्राता जटायुर्नाम वानराः।
यमाख्यात हतं युद्धे रावणेन बलीयसा॥', 'yavīyān mama sa bhrātā jaṭāyur nāma vānarāḥ
yamākhyāta hataṃ yuddhe rāvaṇena balīyasā', null, 4057002),
('ramayana-4-57-3', 3, 'Kishkindha Kanda, Sarga 57, Verse 3', 'वृद्धभावादपक्षत्वाच्छृण्वंस्तदपि मर्षये।
न हि मे शक्तिरद्यास्ति भ्रातुर्वैरविमोक्षणे॥', 'vṛddhabhāvād apakṣatvāc chṛṇvaṃs tad api marṣaye
na hi me śaktir adyāsti bhrātur vairavimokṣaṇe', null, 4057003),
('ramayana-4-57-4', 4, 'Kishkindha Kanda, Sarga 57, Verse 4', 'पुरा वृत्रवधे वृत्ते स चाहं च जयैषिणौ।
आदित्यमुपयातौ स्वो ज्वलन्तं रश्मिमालिनम्॥', 'purā vṛtravadhe vṛtte sa cāhaṃ ca jayaiṣiṇau
ādityam upayātau svo jvalantaṃ raśmimālinam', null, 4057004),
('ramayana-4-57-5', 5, 'Kishkindha Kanda, Sarga 57, Verse 5', 'आवृत्याकाशमार्गेण जवेन स्म गतौ भृशम्।
मध्यं प्राप्ते च सूर्ये च जटायुरवसीदति॥', 'āvṛtyākāśamārgeṇa javena sma gatau bhṛśam
madhyaṃ prāpte ca sūrye ca jaṭāyur avasīdati', null, 4057005),
('ramayana-4-57-6', 6, 'Kishkindha Kanda, Sarga 57, Verse 6', 'तमहं भ्रातरं दृष्ट्वा सूर्यरश्मिभिरर्दितम्।
पक्षाभ्यं छादयामास स्नेहात्परमविह्वलम्॥', 'tam ahaṃ bhrātaraṃ dṛṣṭvā sūryaraśmibhir arditam
pakṣābhyaṃ chādayām āsa snehāt paramavihvalam', null, 4057006),
('ramayana-4-57-7', 7, 'Kishkindha Kanda, Sarga 57, Verse 7', 'निर्दग्धपक्षः पतितो विन्ध्येऽहं वानरोत्तमाः।
अहमस्मिन्वसन्भ्रातुः प्रवृत्तिं नोपलक्षये॥', 'nirdagdhapakṣaḥ patito vindhye ''haṃ vānarottamāḥ
aham asmin vasan bhrātuḥ pravṛttiṃ nopalakṣaye', null, 4057007),
('ramayana-4-57-8', 8, 'Kishkindha Kanda, Sarga 57, Verse 8', 'जटायुषस्त्वेवमुक्तो भ्रात्रा संपातिना तदा।
युवराजो महाप्राज्ञः प्रत्युवाचाङ्गदस्तदा॥', 'jaṭāyuṣas tv evam ukto bhrātrā saṃpātinā tadā
yuvarājo mahāprājñaḥ pratyuvācāṅgadas tadā', null, 4057008),
('ramayana-4-57-9', 9, 'Kishkindha Kanda, Sarga 57, Verse 9', 'जटायुषो यदि भ्राता श्रुतं ते गदितं मया।
आख्याहि यदि जानासि निलयं तस्य रक्षसः॥', 'jaṭāyuṣo yadi bhrātā śrutaṃ te gaditaṃ mayā
ākhyāhi yadi jānāsi nilayaṃ tasya rakṣasaḥ', null, 4057009),
('ramayana-4-57-10', 10, 'Kishkindha Kanda, Sarga 57, Verse 10', 'अदीर्घदर्शिनं तं वा रावणं राक्षसाधिपम्।
अन्तिके यदि वा दूरे यदि जानासि शंस नः॥', 'adīrghadarśinaṃ taṃ vā rāvaṇaṃ rākṣasādhipam
antike yadi vā dūre yadi jānāsi śaṃsa naḥ', null, 4057010),
('ramayana-4-57-11', 11, 'Kishkindha Kanda, Sarga 57, Verse 11', 'ततोऽब्रवीन्महातेजा ज्येष्ठो भ्राता जटायुषः।
आत्मानुरूपं वचनं वानरान्संप्रहर्षयन्॥', 'tato ''bravīn mahātejā jyeṣṭho bhrātā jaṭāyuṣaḥ
ātmānurūpaṃ vacanaṃ vānarān saṃpraharṣayan', null, 4057011),
('ramayana-4-57-12', 12, 'Kishkindha Kanda, Sarga 57, Verse 12', 'निर्दग्धपक्षो गृध्रोऽहं गतवीर्यः प्लवंगमाः।
वाङ्मात्रेण तु रामस्य करिष्ये साह्यमुत्तमम्॥', 'nirdagdhapakṣo gṛdhro ''haṃ gatavīryaḥ plavaṃgamāḥ
vāṅmātreṇa tu rāmasya kariṣye sāhyam uttamam', null, 4057012),
('ramayana-4-57-13', 13, 'Kishkindha Kanda, Sarga 57, Verse 13', 'जानामि वारुणाल्लोकान्विष्णोस्त्रैविक्रमानपि।
देवासुरविमर्दांश्च अमृतस्य च मन्थनम्॥', 'jānāmi vāruṇāl lokān viṣṇos traivikramān api
devāsuravimardāṃś ca amṛtasya ca manthanam', null, 4057013),
('ramayana-4-57-14', 14, 'Kishkindha Kanda, Sarga 57, Verse 14', 'रामस्य यदिदं कार्यं कर्तव्यं प्रथमं मया।
जरया च हृतं तेजः प्राणाश्च शिथिला मम॥', 'rāmasya yad idaṃ kāryaṃ kartavyaṃ prathamaṃ mayā
jarayā ca hṛtaṃ tejaḥ prāṇāś ca śithilā mama', null, 4057014),
('ramayana-4-57-15', 15, 'Kishkindha Kanda, Sarga 57, Verse 15', 'तरुणी रूपसंपन्ना सर्वाभरणभूषिता।
ह्रियमाणा मया दृष्टा रावणेन दुरात्मना॥', 'taruṇī rūpasaṃpannā sarvābharaṇabhūṣitā
hriyamāṇā mayā dṛṣṭā rāvaṇena durātmanā', null, 4057015),
('ramayana-4-57-16', 16, 'Kishkindha Kanda, Sarga 57, Verse 16', 'क्रोशन्ती राम रामेति लक्ष्मणेति च भामिनी।
भूषणान्यपविध्यन्ती गात्राणि च विधुन्वती॥', 'krośantī rāma rāmeti lakṣmaṇeti ca bhāminī
bhūṣaṇāny apavidhyantī gātrāṇi ca vidhunvatī', null, 4057016),
('ramayana-4-57-17', 17, 'Kishkindha Kanda, Sarga 57, Verse 17', 'सूर्यप्रभेव शैलाग्रे तस्याः कौशेयमुत्तमम्।
असिते राक्षसे भाति यथा वा तडिदम्बुदे॥', 'sūryaprabheva śailāgre tasyāḥ kauśeyam uttamam
asite rākṣase bhāti yathā vā taḍidambude', null, 4057017),
('ramayana-4-57-18', 18, 'Kishkindha Kanda, Sarga 57, Verse 18', 'तां तु सीतामहं मन्ये रामस्य परिकीर्तनात्।
श्रूयतां मे कथयतो निलयं तस्य रक्षसः॥', 'tāṃ tu sītām ahaṃ manye rāmasya parikīrtanāt
śrūyatāṃ me kathayato nilayaṃ tasya rakṣasaḥ', null, 4057018),
('ramayana-4-57-19', 19, 'Kishkindha Kanda, Sarga 57, Verse 19', 'पुत्रो विश्रवसः साक्षाद्भ्राता वैश्रवणस्य च।
अध्यास्ते नगरीं लङ्कां रावणो नाम राकसः॥', 'putro viśravasaḥ sākṣād bhrātā vaiśravaṇasya ca
adhyāste nagarīṃ laṅkāṃ rāvaṇo nāma rākasaḥ', null, 4057019),
('ramayana-4-57-20', 20, 'Kishkindha Kanda, Sarga 57, Verse 20', 'इतो द्वीपे समुद्रस्य संपूर्णे शतयोजने।
तस्मिंल्लङ्का पुरी रम्या निर्मिता विश्वकर्मणा॥', 'ito dvīpe samudrasya saṃpūrṇe śatayojane
tasmiṃl laṅkā purī ramyā nirmitā viśvakarmaṇā', null, 4057020),
('ramayana-4-57-21', 21, 'Kishkindha Kanda, Sarga 57, Verse 21', 'तस्यां वसति वैदेही दीना कौशेयवासिनी।
रावणान्तःपुरे रुद्धा राक्षसीभिः सुरक्षिता॥', 'tasyāṃ vasati vaidehī dīnā kauśeyavāsinī
rāvaṇāntaḥpure ruddhā rākṣasībhiḥ surakṣitā', null, 4057021),
('ramayana-4-57-22', 22, 'Kishkindha Kanda, Sarga 57, Verse 22', 'जनकस्यात्मजां राज्ञस्तस्यां द्रक्ष्यथ मैथिलीम्।
लङ्कायामथ गुप्तायां सागरेण समन्ततः॥', 'janakasyātmajāṃ rājñas tasyāṃ drakṣyatha maithilīm
laṅkāyām atha guptāyāṃ sāgareṇa samantataḥ', null, 4057022),
('ramayana-4-57-23', 23, 'Kishkindha Kanda, Sarga 57, Verse 23', 'संप्राप्य सागरस्यान्तं संपूर्णं शतयोजनम्।
आसाद्य दक्षिणं कूलं ततो द्रक्ष्यथ रावणम्॥', 'saṃprāpya sāgarasyāntaṃ saṃpūrṇaṃ śatayojanam
āsādya dakṣiṇaṃ kūlaṃ tato drakṣyatha rāvaṇam', null, 4057023),
('ramayana-4-57-24', 24, 'Kishkindha Kanda, Sarga 57, Verse 24', 'तत्रैव त्वरिताः क्षिप्रं विक्रमध्वं प्लवंगमाः।
ज्ञानेन खलु पश्यामि दृष्ट्वा प्रत्यागमिष्यथ॥', 'tatraiva tvaritāḥ kṣipraṃ vikramadhvaṃ plavaṃgamāḥ
jñānena khalu paśyāmi dṛṣṭvā pratyāgamiṣyatha', null, 4057024),
('ramayana-4-57-25', 25, 'Kishkindha Kanda, Sarga 57, Verse 25', 'आद्यः पन्थाः कुलिङ्गानां ये चान्ये धान्यजीविनः।
द्वितीयो बलिभोजानां ये च वृक्षफलाशिनः॥', 'ādyaḥ panthāḥ kuliṅgānāṃ ye cānye dhānyajīvinaḥ
dvitīyo balibhojānāṃ ye ca vṛkṣaphalāśinaḥ', null, 4057025),
('ramayana-4-57-26', 26, 'Kishkindha Kanda, Sarga 57, Verse 26', 'भासास्तृतीयं गच्छन्ति क्रौञ्चाश्च कुररैः सह।
श्येनाश्चतुर्थं गच्छन्ति गृध्रा गच्छन्ति पञ्चमम्॥', 'bhāsās tṛtīyaṃ gacchanti krauñcāś ca kuraraiḥ saha
śyenāś caturthaṃ gacchanti gṛdhrā gacchanti pañcamam', null, 4057026),
('ramayana-4-57-27', 27, 'Kishkindha Kanda, Sarga 57, Verse 27', 'बलवीर्योपपन्नानां रूपयौवनशालिनाम्।
षष्ठस्तु पन्था हंसानां वैनतेयगतिः परा।
वैनतेयाच्च नो जन्म सर्वेषां वानरर्षभाः॥', 'balavīryopapannānāṃ rūpayauvanaśālinām
ṣaṣṭhas tu panthā haṃsānāṃ vainateyagatiḥ parā
vainateyāc ca no janma sarveṣāṃ vānararṣabhāḥ', null, 4057027),
('ramayana-4-57-28', 28, 'Kishkindha Kanda, Sarga 57, Verse 28', 'गर्हितं तु कृतं कर्म येन स्म पिशिताशनाः।
इहस्थोऽहं प्रपश्यामि रावणं जानकीं तथा॥', 'garhitaṃ tu kṛtaṃ karma yena sma piśitāśanāḥ
ihastho ''haṃ prapaśyāmi rāvaṇaṃ jānakīṃ tathā', null, 4057028),
('ramayana-4-57-29', 29, 'Kishkindha Kanda, Sarga 57, Verse 29', 'अस्माकमपि सौवर्णं दिव्यं चक्षुर्बलं तथा।
तस्मादाहारवीर्येण निसर्गेण च वानराः।
आयोजनशतात्साग्राद्वयं पश्याम नित्यशः॥', 'asmākam api sauvarṇaṃ divyaṃ cakṣurbalaṃ tathā
tasmād āhāravīryeṇa nisargeṇa ca vānarāḥ
āyojanaśatāt sāgrād vayaṃ paśyāma nityaśaḥ', null, 4057029),
('ramayana-4-57-30', 30, 'Kishkindha Kanda, Sarga 57, Verse 30', 'अस्माकं विहिता वृत्तिर्निसार्गेण च दूरतः।
विहिता पादमूले तु वृत्तिश्चरणयोधिनाम्॥', 'asmākaṃ vihitā vṛttir nisārgeṇa ca dūrataḥ
vihitā pādamūle tu vṛttiś caraṇayodhinām', null, 4057030),
('ramayana-4-57-31', 31, 'Kishkindha Kanda, Sarga 57, Verse 31', 'उपायो दृश्यतां कश्चिल्लङ्घने लवणाम्भसः।
अभिगम्य तु वैदेहीं समृद्धार्था गमिष्यथ॥', 'upāyo dṛśyatāṃ kaś cil laṅghane lavaṇāmbhasaḥ
abhigamya tu vaidehīṃ samṛddhārthā gamiṣyatha', null, 4057031),
('ramayana-4-57-32', 32, 'Kishkindha Kanda, Sarga 57, Verse 32', 'समुद्रं नेतुमिच्छामि भवद्भिर्वरुणालयम्।
प्रदास्याम्युदकं भ्रातुः स्वर्गतस्य महात्मनः॥', 'samudraṃ netum icchāmi bhavadbhir varuṇālayam
pradāsyāmy udakaṃ bhrātuḥ svargatasya mahātmanaḥ', null, 4057032),
('ramayana-4-57-33', 33, 'Kishkindha Kanda, Sarga 57, Verse 33', 'ततो नीत्वा तु तं देशं तीरे नदनदीपतेः।
निर्दग्धपक्षं संपातिं वानराः सुमहौजसः॥', 'tato nītvā tu taṃ deśaṃ tīre nadanadīpateḥ
nirdagdhapakṣaṃ saṃpātiṃ vānarāḥ sumahaujasaḥ', null, 4057033),
('ramayana-4-57-34', 34, 'Kishkindha Kanda, Sarga 57, Verse 34', 'पुनः प्रत्यानयित्वा वै तं देशं पतगेश्वरम्।
बभूवुर्वानरा हृष्टाः प्रवृत्तिमुपलभ्य ते॥', 'punaḥ pratyānayitvā vai taṃ deśaṃ patageśvaram
babhūvur vānarā hṛṣṭāḥ pravṛttim upalabhya te', null, 4057034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 58 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-58-1', 1, 'Kishkindha Kanda, Sarga 58, Verse 1', 'ततस्तदमृतास्वादं गृध्रराजेन भाषितम्।
निशम्य वदतो हृष्टास्ते वचः प्लवगर्षभाः॥', 'tatas tad amṛtāsvādaṃ gṛdhrarājena bhāṣitam
niśamya vadato hṛṣṭās te vacaḥ plavagarṣabhāḥ', null, 4058001),
('ramayana-4-58-2', 2, 'Kishkindha Kanda, Sarga 58, Verse 2', 'जाम्बवान्वै हरिश्रेष्ठः सह सर्वैः प्लवंगमैः।
भूतलात्सहसोत्थाय गृध्रराजानमब्रवीत्॥', 'jāmbavān vai hariśreṣṭhaḥ saha sarvaiḥ plavaṃgamaiḥ
bhūtalāt sahasotthāya gṛdhrarājānam abravīt', null, 4058002),
('ramayana-4-58-3', 3, 'Kishkindha Kanda, Sarga 58, Verse 3', 'क्व सीता केन वा दृष्टा को वा हरति मैथिलीम्।
तदाख्यातु भवान्सर्वं गतिर्भव वनौकसाम्॥', 'kva sītā kena vā dṛṣṭā ko vā harati maithilīm
tad ākhyātu bhavān sarvaṃ gatir bhava vanaukasām', null, 4058003),
('ramayana-4-58-4', 4, 'Kishkindha Kanda, Sarga 58, Verse 4', 'को दाशरथिबाणानां वज्रवेगनिपातिनाम्।
स्वयं लक्ष्मणमुक्तानां न चिन्तयति विक्रमम्॥', 'ko dāśarathibāṇānāṃ vajraveganipātinām
svayaṃ lakṣmaṇam uktānāṃ na cintayati vikramam', null, 4058004),
('ramayana-4-58-5', 5, 'Kishkindha Kanda, Sarga 58, Verse 5', 'स हरीन्प्रीतिसंयुक्तान्सीता श्रुतिसमाहितान्।
पुनराश्वासयन्प्रीत इदं वचनमब्रवीत्॥', 'sa harīn prītisaṃyuktān sītā śrutisamāhitān
punar āśvāsayan prīta idaṃ vacanam abravīt', null, 4058005),
('ramayana-4-58-6', 6, 'Kishkindha Kanda, Sarga 58, Verse 6', 'श्रूयतामिह वैदेह्या यथा मे हरणं श्रुतम्।
येन चापि ममाख्यातं यत्र चायतलोचना॥', 'śrūyatām iha vaidehyā yathā me haraṇaṃ śrutam
yena cāpi mamākhyātaṃ yatra cāyatalocanā', null, 4058006),
('ramayana-4-58-7', 7, 'Kishkindha Kanda, Sarga 58, Verse 7', 'अहमस्मिन्गिरौ दुर्गे बहुयोजनमायते।
चिरान्निपतितो वृद्धः क्षीणप्राणपराक्रमः॥', 'aham asmin girau durge bahuyojanam āyate
cirān nipatito vṛddhaḥ kṣīṇaprāṇaparākramaḥ', null, 4058007),
('ramayana-4-58-8', 8, 'Kishkindha Kanda, Sarga 58, Verse 8', 'तं मामेवंगतं पुत्रः सुपार्श्वो नाम नामतः।
आहारेण यथाकालं बिभर्ति पततां वरः॥', 'taṃ mām evaṃgataṃ putraḥ supārśvo nāma nāmataḥ
āhāreṇa yathākālaṃ bibharti patatāṃ varaḥ', null, 4058008),
('ramayana-4-58-9', 9, 'Kishkindha Kanda, Sarga 58, Verse 9', 'तीक्ष्णकामास्तु गन्धर्वास्तीक्ष्णकोपा भुजंगमाः।
मृगाणां तु भयं तीक्ष्णं ततस्तीक्ष्णक्षुधा वयम्॥', 'tīkṣṇakāmās tu gandharvās tīkṣṇakopā bhujaṃgamāḥ
mṛgāṇāṃ tu bhayaṃ tīkṣṇaṃ tatas tīkṣṇakṣudhā vayam', null, 4058009),
('ramayana-4-58-10', 10, 'Kishkindha Kanda, Sarga 58, Verse 10', 'स कदा चित्क्षुधार्तस्य मम चाहारकाङ्क्षिणः।
गतसूर्योऽहनि प्राप्तो मम पुत्रो ह्यनामिषः॥', 'sa kadā cit kṣudhārtasya mama cāhārakāṅkṣiṇaḥ
gatasūryo ''hani prāpto mama putro hy anāmiṣaḥ', null, 4058010),
('ramayana-4-58-11', 11, 'Kishkindha Kanda, Sarga 58, Verse 11', 'स मया वृद्धभावाच्च कोपाच्च परिभर्त्सितः।
क्षुत्पिपासा परीतेन कुमारः पततां वरः॥', 'sa mayā vṛddhabhāvāc ca kopāc ca paribhartsitaḥ
kṣutpipāsā parītena kumāraḥ patatāṃ varaḥ', null, 4058011),
('ramayana-4-58-12', 12, 'Kishkindha Kanda, Sarga 58, Verse 12', 'स ममाहारसंरोधात्पीडितः प्रीतिवर्धनः।
अनुमान्य यथातत्त्वमिदं वचनमब्रवीत्॥', 'sa mamāhārasaṃrodhāt pīḍitaḥ prītivardhanaḥ
anumānya yathātattvam idaṃ vacanam abravīt', null, 4058012),
('ramayana-4-58-13', 13, 'Kishkindha Kanda, Sarga 58, Verse 13', 'अहं तात यथाकालमामिषार्थी खमाप्लुतः।
महेन्द्रस्य गिरेर्द्वारमावृत्य च समास्थितः॥', 'ahaṃ tāta yathākālam āmiṣārthī kham āplutaḥ
mahendrasya girer dvāram āvṛtya ca samāsthitaḥ', null, 4058013),
('ramayana-4-58-14', 14, 'Kishkindha Kanda, Sarga 58, Verse 14', 'तत्र सत्त्वसहस्राणां सागरान्तरचारिणाम्।
पन्थानमेकोऽध्यवसं संनिरोद्धुमवाङ्मुखः॥', 'tatra sattvasahasrāṇāṃ sāgarāntaracāriṇām
panthānam eko ''dhyavasaṃ saṃniroddhum avāṅmukhaḥ', null, 4058014),
('ramayana-4-58-15', 15, 'Kishkindha Kanda, Sarga 58, Verse 15', 'तत्र कश्चिन्मया दृष्टः सूर्योदयसमप्रभाम्।
स्त्रियमादाय गच्छन्वै भिन्नाञ्जनचयोपमः॥', 'tatra kaś cin mayā dṛṣṭaḥ sūryodayasamaprabhām
striyam ādāya gacchan vai bhinnāñjanacayopamaḥ', null, 4058015),
('ramayana-4-58-16', 16, 'Kishkindha Kanda, Sarga 58, Verse 16', 'सोऽहमभ्यवहारार्थी तौ दृष्ट्वा कृतनिश्चयः।
तेन साम्ना विनीतेन पन्थानमभियाचितः॥', 'so ''ham abhyavahārārthī tau dṛṣṭvā kṛtaniścayaḥ
tena sāmnā vinītena panthānam abhiyācitaḥ', null, 4058016),
('ramayana-4-58-17', 17, 'Kishkindha Kanda, Sarga 58, Verse 17', 'न हि सामोपपन्नानां प्रहर्ता विद्यते क्व चित्।
नीचेष्वपि जनः कश्चित्किमङ्ग बत मद्विधः॥', 'na hi sāmopapannānāṃ prahartā vidyate kva cit
nīceṣv api janaḥ kaś cit kim aṅga bata madvidhaḥ', null, 4058017),
('ramayana-4-58-18', 18, 'Kishkindha Kanda, Sarga 58, Verse 18', 'स यातस्तेजसा व्योम संक्षिपन्निव वेगतः।
अथाहं खे चरैर्भूतैरभिगम्य सभाजितः॥', 'sa yātas tejasā vyoma saṃkṣipann iva vegataḥ
athāhaṃ khe carair bhūtair abhigamya sabhājitaḥ', null, 4058018),
('ramayana-4-58-19', 19, 'Kishkindha Kanda, Sarga 58, Verse 19', 'दिष्ट्या जीवसि तातेति अब्रुवन्मां महर्षयः।
कथं चित्सकलत्रोऽसौ गतस्ते स्वस्त्यसंशयम्॥', 'diṣṭyā jīvasi tāteti abruvan māṃ maharṣayaḥ
kathaṃ cit sakalatro ''sau gatas te svasty asaṃśayam', null, 4058019),
('ramayana-4-58-20', 20, 'Kishkindha Kanda, Sarga 58, Verse 20', 'एवमुक्तस्ततोऽहं तैः सिद्धैः परमशोभनैः।
स च मे रावणो राजा रक्षसां प्रतिवेदितः॥', 'evam uktas tato ''haṃ taiḥ siddhaiḥ paramaśobhanaiḥ
sa ca me rāvaṇo rājā rakṣasāṃ prativeditaḥ', null, 4058020),
('ramayana-4-58-21', 21, 'Kishkindha Kanda, Sarga 58, Verse 21', 'हरन्दाशरथेर्भार्यां रामस्य जनकात्मजाम्।
भ्रष्टाभरणकौशेयां शोकवेगपराजिताम्॥', 'haran dāśarather bhāryāṃ rāmasya janakātmajām
bhraṣṭābharaṇakauśeyāṃ śokavegaparājitām', null, 4058021),
('ramayana-4-58-22', 22, 'Kishkindha Kanda, Sarga 58, Verse 22', 'रामलक्ष्मणयोर्नाम क्रोशन्तीं मुक्तमूर्धजाम्।
एष कालात्ययस्तावदिति वाक्यविदां वरः॥', 'rāmalakṣmaṇayor nāma krośantīṃ muktamūrdhajām
eṣa kālātyayas tāvad iti vākyavidāṃ varaḥ', null, 4058022),
('ramayana-4-58-23', 23, 'Kishkindha Kanda, Sarga 58, Verse 23', 'एतमर्थं समग्रं मे सुपार्श्वः प्रत्यवेदयत्।
तच्छ्रुत्वापि हि मे बुद्धिर्नासीत्का चित्पराक्रमे॥', 'etam arthaṃ samagraṃ me supārśvaḥ pratyavedayat
tac chrutvāpi hi me buddhir nāsīt kā cit parākrame', null, 4058023),
('ramayana-4-58-24', 24, 'Kishkindha Kanda, Sarga 58, Verse 24', 'अपक्षो हि कथं पक्षी कर्म किं चिदुपक्रमेत्।
यत्तु शक्यं मया कर्तुं वाग्बुद्धिगुणवर्तिना॥', 'apakṣo hi kathaṃ pakṣī karma kiṃ cid upakramet
yat tu śakyaṃ mayā kartuṃ vāgbuddhiguṇavartinā', null, 4058024),
('ramayana-4-58-25', 25, 'Kishkindha Kanda, Sarga 58, Verse 25', 'श्रूयतां तत्प्रवक्ष्यामि भवतां पौरुषाश्रयम्।
वाङ्मतिभ्यां हि सार्वेषां करिष्यामि प्रियं हि वः।
यद्धि दाशरथेः कार्यं मम तन्नात्र संशयः॥', 'śrūyatāṃ tat pravakṣyāmi bhavatāṃ pauruṣāśrayam
vāṅmatibhyāṃ hi sārveṣāṃ kariṣyāmi priyaṃ hi vaḥ
yad dhi dāśaratheḥ kāryaṃ mama tan nātra saṃśayaḥ', null, 4058025),
('ramayana-4-58-26', 26, 'Kishkindha Kanda, Sarga 58, Verse 26', 'ते भवन्तो मतिश्रेष्ठा बलवन्तो मनस्विनः।
सहिताः कपिराजेन देवैरपि दुरासदाः॥', 'te bhavanto matiśreṣṭhā balavanto manasvinaḥ
sahitāḥ kapirājena devair api durāsadāḥ', null, 4058026),
('ramayana-4-58-27', 27, 'Kishkindha Kanda, Sarga 58, Verse 27', 'रामलक्ष्मणबाणाश्च निशिताः कङ्कपत्रिणः।
त्रयाणामपि लोकानां पर्याप्तास्त्राणनिग्रहे॥', 'rāmalakṣmaṇabāṇāś ca niśitāḥ kaṅkapatriṇaḥ
trayāṇām api lokānāṃ paryāptās trāṇanigrahe', null, 4058027),
('ramayana-4-58-28', 28, 'Kishkindha Kanda, Sarga 58, Verse 28', 'कामं खलु दशग्रीवस्तेजोबलसमन्वितः।
भवतां तु समर्थानां न किं चिदपि दुष्करम्॥', 'kāmaṃ khalu daśagrīvas tejobalasamanvitaḥ
bhavatāṃ tu samarthānāṃ na kiṃ cid api duṣkaram', null, 4058028),
('ramayana-4-58-29', 29, 'Kishkindha Kanda, Sarga 58, Verse 29', 'तदलं कालसंगेन क्रियतां बुद्धिनिश्चयः।
न हि कर्मसु सज्जन्ते बुद्धिमन्तो भवद्विधाः॥', 'tad alaṃ kālasaṃgena kriyatāṃ buddhiniścayaḥ
na hi karmasu sajjante buddhimanto bhavadvidhāḥ', null, 4058029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 59 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-59-1', 1, 'Kishkindha Kanda, Sarga 59, Verse 1', 'ततः कृतोदकं स्नातं तं गृध्रं हरियूथपाः।
उपविष्टा गिरौ दुर्गे परिवार्य समन्ततः॥', 'tataḥ kṛtodakaṃ snātaṃ taṃ gṛdhraṃ hariyūthapāḥ
upaviṣṭā girau durge parivārya samantataḥ', null, 4059001),
('ramayana-4-59-2', 2, 'Kishkindha Kanda, Sarga 59, Verse 2', 'तमङ्गदमुपासीनं तैः सर्वैर्हरिभिर्वृतम्।
जनितप्रत्ययो हर्षात्संपातिः पुनरब्रवीत्॥', 'tam aṅgadam upāsīnaṃ taiḥ sarvair haribhir vṛtam
janitapratyayo harṣāt saṃpātiḥ punar abravīt', null, 4059002),
('ramayana-4-59-3', 3, 'Kishkindha Kanda, Sarga 59, Verse 3', 'कृत्वा निःशब्दमेकाग्राः शृण्वन्तु हरयो मम।
तत्त्वं संकीर्तयिष्यामि यथा जानामि मैथिलीम्॥', 'kṛtvā niḥśabdam ekāgrāḥ śṛṇvantu harayo mama
tattvaṃ saṃkīrtayiṣyāmi yathā jānāmi maithilīm', null, 4059003),
('ramayana-4-59-4', 4, 'Kishkindha Kanda, Sarga 59, Verse 4', 'अस्य विन्ध्यस्य शिखरे पतितोऽस्मि पुरा वने।
सूर्यातपपरीताङ्गो निर्दग्धः सूर्यरश्मिभिः॥', 'asya vindhyasya śikhare patito ''smi purā vane
sūryātapaparītāṅgo nirdagdhaḥ sūryaraśmibhiḥ', null, 4059004),
('ramayana-4-59-5', 5, 'Kishkindha Kanda, Sarga 59, Verse 5', 'लब्धसंज्ञस्तु षड्रात्राद्विवशो विह्वलन्निव।
वीक्षमाणो दिशः सर्वा नाभिजानामि किं चन॥', 'labdhasaṃjñas tu ṣaḍrātrād vivaśo vihvalann iva
vīkṣamāṇo diśaḥ sarvā nābhijānāmi kiṃ cana', null, 4059005),
('ramayana-4-59-6', 6, 'Kishkindha Kanda, Sarga 59, Verse 6', 'ततस्तु सागराञ्शैलान्नदीः सर्वाः सरांसि च।
वनान्यटविदेशांश्च समीक्ष्य मतिरागमत्॥', 'tatas tu sāgarāñ śailān nadīḥ sarvāḥ sarāṃsi ca
vanāny aṭavideśāṃś ca samīkṣya matir āgamat', null, 4059006),
('ramayana-4-59-7', 7, 'Kishkindha Kanda, Sarga 59, Verse 7', 'हृष्टपक्षिगणाकीर्णः कन्दरान्तरकूटवान्।
दक्षिणस्योदधेस्तीरे विन्ध्योऽयमिति निश्चितः॥', 'hṛṣṭapakṣigaṇākīrṇaḥ kandarāntarakūṭavān
dakṣiṇasyodadhes tīre vindhyo ''yam iti niścitaḥ', null, 4059007),
('ramayana-4-59-8', 8, 'Kishkindha Kanda, Sarga 59, Verse 8', 'आसीच्चात्राश्रमं पुण्यं सुरैरपि सुपूजितम्।
ऋषिर्निशाकरो नाम यस्मिन्नुग्रतपाभवत्॥', 'āsīc cātrāśramaṃ puṇyaṃ surair api supūjitam
ṛṣir niśākaro nāma yasminn ugratapābhavat', null, 4059008),
('ramayana-4-59-9', 9, 'Kishkindha Kanda, Sarga 59, Verse 9', 'अष्टौ वर्षसहस्राणि तेनास्मिन्नृषिणा विना।
वसतो मम धर्मज्ञाः स्वर्गते तु निशाकरे॥', 'aṣṭau varṣasahasrāṇi tenāsminn ṛṣiṇā vinā
vasato mama dharmajñāḥ svargate tu niśākare', null, 4059009),
('ramayana-4-59-10', 10, 'Kishkindha Kanda, Sarga 59, Verse 10', 'अवतीर्य च विन्ध्याग्रात्कृच्छ्रेण विषमाच्छनैः।
तीक्ष्णदर्भां वसुमतीं दुःखेन पुनरागतः॥', 'avatīrya ca vindhyāgrāt kṛcchreṇa viṣamāc chanaiḥ
tīkṣṇadarbhāṃ vasumatīṃ duḥkhena punar āgataḥ', null, 4059010),
('ramayana-4-59-11', 11, 'Kishkindha Kanda, Sarga 59, Verse 11', 'तमृषिं द्रष्टु कामोऽस्मि दुःखेनाभ्यागतो भृशम्।
जटायुषा मया चैव बहुशोऽभिगतो हि सः॥', 'tam ṛṣiṃ draṣṭu kāmo ''smi duḥkhenābhyāgato bhṛśam
jaṭāyuṣā mayā caiva bahuśo ''bhigato hi saḥ', null, 4059011),
('ramayana-4-59-12', 12, 'Kishkindha Kanda, Sarga 59, Verse 12', 'तस्याश्रमपदाभ्याशे ववुर्वाताः सुगन्धिनः।
वृक्षो नापुष्पितः कश्चिदफलो वा न दृश्यते॥', 'tasyāśramapadābhyāśe vavur vātāḥ sugandhinaḥ
vṛkṣo nāpuṣpitaḥ kaś cid aphalo vā na dṛśyate', null, 4059012),
('ramayana-4-59-13', 13, 'Kishkindha Kanda, Sarga 59, Verse 13', 'उपेत्य चाश्रमं पुण्यं वृक्षमूलमुपाश्रितः।
द्रष्टुकामः प्रतीक्षे च भगवन्तं निशाकरम्॥', 'upetya cāśramaṃ puṇyaṃ vṛkṣamūlam upāśritaḥ
draṣṭukāmaḥ pratīkṣe ca bhagavantaṃ niśākaram', null, 4059013),
('ramayana-4-59-14', 14, 'Kishkindha Kanda, Sarga 59, Verse 14', 'अथापश्यमदूरस्थमृषिं ज्वलिततेजसं।
कृताभिषेकं दुर्धर्षमुपावृत्तमुदङ्मुखम्॥', 'athāpaśyam adūrastham ṛṣiṃ jvalitatejasaṃ
kṛtābhiṣekaṃ durdharṣam upāvṛttam udaṅmukham', null, 4059014),
('ramayana-4-59-15', 15, 'Kishkindha Kanda, Sarga 59, Verse 15', 'तमृक्षाः सृमरा व्याघ्राः सिंहा नागाः सरीसृपाः।
परिवार्योपगच्छन्ति दातारं प्राणिनो यथा॥', 'tam ṛkṣāḥ sṛmarā vyāghrāḥ siṃhā nāgāḥ sarīsṛpāḥ
parivāryopagacchanti dātāraṃ prāṇino yathā', null, 4059015),
('ramayana-4-59-16', 16, 'Kishkindha Kanda, Sarga 59, Verse 16', 'ततः प्राप्तमृषिं ज्ञात्वा तानि सत्त्वानि वै ययुः।
प्रविष्टे राजनि यथा सर्वं सामात्यकं बलम्॥', 'tataḥ prāptam ṛṣiṃ jñātvā tāni sattvāni vai yayuḥ
praviṣṭe rājani yathā sarvaṃ sāmātyakaṃ balam', null, 4059016),
('ramayana-4-59-17', 17, 'Kishkindha Kanda, Sarga 59, Verse 17', 'ऋषिस्तु दृष्ट्वा मां तुष्टः प्रविष्टश्चाश्रमं पुनः।
मुहूर्तमात्रान्निष्क्रम्य ततः कार्यमपृच्छत॥', 'ṛṣis tu dṛṣṭvā māṃ tuṣṭaḥ praviṣṭaś cāśramaṃ punaḥ
muhūrtamātrān niṣkramya tataḥ kāryam apṛcchata', null, 4059017),
('ramayana-4-59-18', 18, 'Kishkindha Kanda, Sarga 59, Verse 18', 'सौम्य वैकल्यतां दृष्ट्वा रोंणां ते नावगम्यते।
अग्निदग्धाविमौ पक्षौ त्वक्चैव व्रणिता तव॥', 'saumya vaikalyatāṃ dṛṣṭvā roṃṇāṃ te nāvagamyate
agnidagdhāv imau pakṣau tvak caiva vraṇitā tava', null, 4059018),
('ramayana-4-59-19', 19, 'Kishkindha Kanda, Sarga 59, Verse 19', 'द्वौ गृध्रौ दृष्टपूर्वौ मे मातरिश्वसमौ जवे।
गृध्राणां चैव राजानौ भ्रातरौ कामरूपिणौ॥', 'dvau gṛdhrau dṛṣṭapūrvau me mātariśvasamau jave
gṛdhrāṇāṃ caiva rājānau bhrātarau kāmarūpiṇau', null, 4059019),
('ramayana-4-59-20', 20, 'Kishkindha Kanda, Sarga 59, Verse 20', 'ज्येष्ठस्त्वं तु च संपातिर्जटायुरनुजस्तव।
मानुषं रूपमास्थाय गृह्णीतां चरणौ मम॥', 'jyeṣṭhas tvaṃ tu ca saṃpātir jaṭāyur anujas tava
mānuṣaṃ rūpam āsthāya gṛhṇītāṃ caraṇau mama', null, 4059020),
('ramayana-4-59-21', 21, 'Kishkindha Kanda, Sarga 59, Verse 21', 'किं ते व्याधिसमुत्थानं पक्षयोः पतनं कथम्।
दण्डो वायं धृतः केन सर्वमाख्याहि पृच्छतः॥', 'kiṃ te vyādhisamutthānaṃ pakṣayoḥ patanaṃ katham
daṇḍo vāyaṃ dhṛtaḥ kena sarvam ākhyāhi pṛcchataḥ', null, 4059021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 60 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-60-1', 1, 'Kishkindha Kanda, Sarga 60, Verse 1', 'ततस्तद्दारुणं कर्म दुष्करं साहसात्कृतम्।
आचचक्षे मुनेः सर्वं सूर्यानुगमनं तथा॥', 'tatas tad dāruṇaṃ karma duṣkaraṃ sāhasāt kṛtam
ācacakṣe muneḥ sarvaṃ sūryānugamanaṃ tathā', null, 4060001),
('ramayana-4-60-2', 2, 'Kishkindha Kanda, Sarga 60, Verse 2', 'भगवन्व्रणयुक्तत्वाल्लज्जया चाकुलेन्द्रियः।
परिश्रान्तो न शक्नोमि वचनं परिभाषितुम्॥', 'bhagavan vraṇayuktatvāl lajjayā cākulendriyaḥ
pariśrānto na śaknomi vacanaṃ paribhāṣitum', null, 4060002),
('ramayana-4-60-3', 3, 'Kishkindha Kanda, Sarga 60, Verse 3', 'अहं चैव जटायुश्च संघर्षाद्दर्पमोहितौ।
आकाशं पतितौ वीरौ जिघासन्तौ पराक्रमम्॥', 'ahaṃ caiva jaṭāyuś ca saṃgharṣād darpamohitau
ākāśaṃ patitau vīrau jighāsantau parākramam', null, 4060003),
('ramayana-4-60-4', 4, 'Kishkindha Kanda, Sarga 60, Verse 4', 'कैलासशिखरे बद्ध्वा मुनीनामग्रतः पणम्।
रविः स्यादनुयातव्यो यावदस्तं महागिरिम्॥', 'kailāsaśikhare baddhvā munīnām agrataḥ paṇam
raviḥ syād anuyātavyo yāvad astaṃ mahāgirim', null, 4060004),
('ramayana-4-60-5', 5, 'Kishkindha Kanda, Sarga 60, Verse 5', 'अथावां युगपत्प्राप्तावपश्याव महीतले।
रथचक्रप्रमाणानि नगराणि पृथक्पृथक्॥', 'athāvāṃ yugapat prāptāv apaśyāva mahītale
rathacakrapramāṇāni nagarāṇi pṛthak pṛthak', null, 4060005),
('ramayana-4-60-6', 6, 'Kishkindha Kanda, Sarga 60, Verse 6', 'क्व चिद्वादित्रघोषांश्च ब्रह्मघोषांश्च शुश्रुव।
गायन्तीश्चाङ्गना बह्वीः पश्यावो रक्तवाससः॥', 'kva cid vāditraghoṣāṃś ca brahmaghoṣāṃś ca śuśruva
gāyantīś cāṅganā bahvīḥ paśyāvo raktavāsasaḥ', null, 4060006),
('ramayana-4-60-7', 7, 'Kishkindha Kanda, Sarga 60, Verse 7', 'तूर्णमुत्पत्य चाकाशमादित्यपथमास्थितौ।
आवामालोकयावस्तद्वनं शाद्वलसंस्थितम्॥', 'tūrṇam utpatya cākāśam ādityapatham āsthitau
āvām ālokayāvas tad vanaṃ śādvalasaṃsthitam', null, 4060007),
('ramayana-4-60-8', 8, 'Kishkindha Kanda, Sarga 60, Verse 8', 'उपलैरिव संछन्ना दृश्यते भूः शिलोच्चयैः।
आपगाभिश्च संवीता सूत्रैरिव वसुंधरा॥', 'upalair iva saṃchannā dṛśyate bhūḥ śiloccayaiḥ
āpagābhiś ca saṃvītā sūtrair iva vasuṃdharā', null, 4060008),
('ramayana-4-60-9', 9, 'Kishkindha Kanda, Sarga 60, Verse 9', 'हिमवांश्चैव विन्ध्यश्च मेरुश्च सुमहान्नगः।
भूतले संप्रकाशन्ते नागा इव जलाशये॥', 'himavāṃś caiva vindhyaś ca meruś ca sumahān nagaḥ
bhūtale saṃprakāśante nāgā iva jalāśaye', null, 4060009),
('ramayana-4-60-10', 10, 'Kishkindha Kanda, Sarga 60, Verse 10', 'तीव्रस्वेदश्च खेदश्च भयं चासीत्तदावयोः।
समाविशत मोहश्च मोहान्मूर्छा च दारुणा॥', 'tīvrasvedaś ca khedaś ca bhayaṃ cāsīt tadāvayoḥ
samāviśata mohaś ca mohān mūrchā ca dāruṇā', null, 4060010),
('ramayana-4-60-11', 11, 'Kishkindha Kanda, Sarga 60, Verse 11', 'न दिग्विज्ञायते याम्या नागेन्या न च वारुणी।
युगान्ते नियतो लोको हतो दग्ध इवाग्निना॥', 'na dig vijñāyate yāmyā nāgenyā na ca vāruṇī
yugānte niyato loko hato dagdha ivāgninā', null, 4060011),
('ramayana-4-60-12', 12, 'Kishkindha Kanda, Sarga 60, Verse 12', 'यत्नेन महता भूयो रविः समवलोकितः।
तुल्यः पृथ्वीप्रमाणेन भास्करः प्रतिभाति नौ॥', 'yatnena mahatā bhūyo raviḥ samavalokitaḥ
tulyaḥ pṛthvīpramāṇena bhāskaraḥ pratibhāti nau', null, 4060012),
('ramayana-4-60-13', 13, 'Kishkindha Kanda, Sarga 60, Verse 13', 'जटायुर्मामनापृच्छ्य निपपात महीं ततः।
तं दृष्ट्वा तूर्णमाकाशादात्मानं मुक्तवानहम्॥', 'jaṭāyur mām anāpṛcchya nipapāta mahīṃ tataḥ
taṃ dṛṣṭvā tūrṇam ākāśād ātmānaṃ muktavān aham', null, 4060013),
('ramayana-4-60-14', 14, 'Kishkindha Kanda, Sarga 60, Verse 14', 'पक्षिभ्यां च मया गुप्तो जटायुर्न प्रदह्यत।
प्रमादात्तत्र निर्दग्धः पतन्वायुपथादहम्॥', 'pakṣibhyāṃ ca mayā gupto jaṭāyur na pradahyata
pramādāt tatra nirdagdhaḥ patan vāyupathād aham', null, 4060014),
('ramayana-4-60-15', 15, 'Kishkindha Kanda, Sarga 60, Verse 15', 'आशङ्के तं निपतितं जनस्थाने जटायुषम्।
अहं तु पतितो विन्ध्ये दग्धपक्षो जडीकृतः॥', 'āśaṅke taṃ nipatitaṃ janasthāne jaṭāyuṣam
ahaṃ tu patito vindhye dagdhapakṣo jaḍīkṛtaḥ', null, 4060015),
('ramayana-4-60-16', 16, 'Kishkindha Kanda, Sarga 60, Verse 16', 'राज्येन हीनो भ्रात्रा च पक्षाभ्यां विक्रमेण च।
सर्वथा मर्तुमेवेच्छन्पतिष्ये शिखराद्गिरेः॥', 'rājyena hīno bhrātrā ca pakṣābhyāṃ vikrameṇa ca
sarvathā martum evecchan patiṣye śikharād gireḥ', null, 4060016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 61 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-61-1', 1, 'Kishkindha Kanda, Sarga 61, Verse 1', 'एवमुक्त्वा मुनिश्रेष्ठमरुदं दुःखितो भृशम्।
अथ ध्यात्वा मुहूर्तं तु भगवानिदमब्रवीत्॥', 'evam uktvā muniśreṣṭham arudaṃ duḥkhito bhṛśam
atha dhyātvā muhūrtaṃ tu bhagavān idam abravīt', null, 4061001),
('ramayana-4-61-2', 2, 'Kishkindha Kanda, Sarga 61, Verse 2', 'पक्षौ च ते प्रपक्षौ च पुनरन्यौ भविष्यतः।
चक्षुषी चैव प्राणाश्च विक्रमश्च बलं च ते॥', 'pakṣau ca te prapakṣau ca punar anyau bhaviṣyataḥ
cakṣuṣī caiva prāṇāś ca vikramaś ca balaṃ ca te', null, 4061002),
('ramayana-4-61-3', 3, 'Kishkindha Kanda, Sarga 61, Verse 3', 'पुराणे सुमहत्कार्यं भविष्यं हि मया श्रुतम्।
दृष्टं मे तपसा चैव श्रुत्वा च विदितं मम॥', 'purāṇe sumahat kāryaṃ bhaviṣyaṃ hi mayā śrutam
dṛṣṭaṃ me tapasā caiva śrutvā ca viditaṃ mama', null, 4061003),
('ramayana-4-61-4', 4, 'Kishkindha Kanda, Sarga 61, Verse 4', 'राजा दशरथो नाम कश्चिदिक्ष्वाकुनन्दनः।
तस्य पुत्रो महातेजा रामो नाम भविष्यति॥', 'rājā daśaratho nāma kaś cid ikṣvākunandanaḥ
tasya putro mahātejā rāmo nāma bhaviṣyati', null, 4061004),
('ramayana-4-61-5', 5, 'Kishkindha Kanda, Sarga 61, Verse 5', 'अरण्यं च सह भ्रात्रा लक्ष्मणेन गमिष्यति।
तस्मिन्नर्थे नियुक्तः सन्पित्रा सत्यपराक्रमः॥', 'araṇyaṃ ca saha bhrātrā lakṣmaṇena gamiṣyati
tasminn arthe niyuktaḥ san pitrā satyaparākramaḥ', null, 4061005),
('ramayana-4-61-6', 6, 'Kishkindha Kanda, Sarga 61, Verse 6', 'नैरृतो रावणो नाम तस्या भार्यां हरिष्यति।
राक्षसेन्द्रो जनस्थानादवध्यः सुरदानवैः॥', 'nairṛto rāvaṇo nāma tasyā bhāryāṃ hariṣyati
rākṣasendro janasthānād avadhyaḥ suradānavaiḥ', null, 4061006),
('ramayana-4-61-7', 7, 'Kishkindha Kanda, Sarga 61, Verse 7', 'सा च कामैः प्रलोभ्यन्ती भक्ष्यैर्भोज्यैश्च मैथिली।
न भोक्ष्यति महाभागा दुःखमग्ना यशस्विनी॥', 'sā ca kāmaiḥ pralobhyantī bhakṣyair bhojyaiś ca maithilī
na bhokṣyati mahābhāgā duḥkhamagnā yaśasvinī', null, 4061007),
('ramayana-4-61-8', 8, 'Kishkindha Kanda, Sarga 61, Verse 8', 'परमान्नं तु वैदेह्या ज्ञात्वा दास्यति वासवः।
यदन्नममृतप्रख्यं सुराणामपि दुर्लभम्॥', 'paramānnaṃ tu vaidehyā jñātvā dāsyati vāsavaḥ
yad annam amṛtaprakhyaṃ surāṇām api durlabham', null, 4061008),
('ramayana-4-61-9', 9, 'Kishkindha Kanda, Sarga 61, Verse 9', 'तदन्नं मैथिली प्राप्य विज्ञायेन्द्रादिदं त्विति।
अग्रमुद्धृत्य रामाय भूतले निर्वपिष्यति॥', 'tad annaṃ maithilī prāpya vijñāyendrād idaṃ tv iti
agram uddhṛtya rāmāya bhūtale nirvapiṣyati', null, 4061009),
('ramayana-4-61-10', 10, 'Kishkindha Kanda, Sarga 61, Verse 10', 'यदि जीवति मे भर्ता लक्ष्मणेन सह प्रभुः।
देवत्वं गतयोर्वापि तयोरन्नमिदं त्विति॥', 'yadi jīvati me bhartā lakṣmaṇena saha prabhuḥ
devatvaṃ gatayor vāpi tayor annam idaṃ tv iti', null, 4061010),
('ramayana-4-61-11', 11, 'Kishkindha Kanda, Sarga 61, Verse 11', 'एष्यन्त्यन्वेषकास्तस्या रामदूताः प्लवंगमाः।
आख्येया राममहिषी त्वया तेभ्यो विहंगम॥', 'eṣyanty anveṣakās tasyā rāmadūtāḥ plavaṃgamāḥ
ākhyeyā rāmamahiṣī tvayā tebhyo vihaṃgama', null, 4061011),
('ramayana-4-61-12', 12, 'Kishkindha Kanda, Sarga 61, Verse 12', 'सर्वथा तु न गन्तव्यमीदृशः क्व गमिष्यसि।
देशकालौ प्रतीक्षस्व पक्षौ त्वं प्रतिपत्स्यसे॥', 'sarvathā tu na gantavyam īdṛśaḥ kva gamiṣyasi
deśakālau pratīkṣasva pakṣau tvaṃ pratipatsyase', null, 4061012),
('ramayana-4-61-13', 13, 'Kishkindha Kanda, Sarga 61, Verse 13', 'उत्सहेयमहं कर्तुमद्यैव त्वां सपक्षकम्।
इहस्थस्त्वं तु लोकानां हितं कार्यं करिष्यसि॥', 'utsaheyam ahaṃ kartum adyaiva tvāṃ sapakṣakam
ihasthas tvaṃ tu lokānāṃ hitaṃ kāryaṃ kariṣyasi', null, 4061013),
('ramayana-4-61-14', 14, 'Kishkindha Kanda, Sarga 61, Verse 14', 'त्वयापि खलु तत्कार्यं तयोश्च नृपपुत्रयोः।
ब्राह्मणानां सुराणां च मुनीनां वासवस्य च॥', 'tvayāpi khalu tat kāryaṃ tayoś ca nṛpaputrayoḥ
brāhmaṇānāṃ surāṇāṃ ca munīnāṃ vāsavasya ca', null, 4061014),
('ramayana-4-61-15', 15, 'Kishkindha Kanda, Sarga 61, Verse 15', 'इच्छाम्यहमपि द्रष्टुं भ्रातरु रामलक्ष्मणौ।
नेच्छे चिरं धारयितुं प्राणांस्त्यक्ष्ये कलेवरम्॥', 'icchāmy aham api draṣṭuṃ bhrātaru rāmalakṣmaṇau
necche ciraṃ dhārayituṃ prāṇāṃs tyakṣye kalevaram', null, 4061015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 62 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-62-1', 1, 'Kishkindha Kanda, Sarga 62, Verse 1', 'एतैरन्यैश्च बहुभिर्वाक्यैर्वाक्यविशारदः।
मां प्रशस्याभ्यनुज्ञाप्य प्रविष्टः स स्वमाश्रमम्॥', 'etair anyaiś ca bahubhir vākyair vākyaviśāradaḥ
māṃ praśasyābhyanujñāpya praviṣṭaḥ sa svam āśramam', null, 4062001),
('ramayana-4-62-2', 2, 'Kishkindha Kanda, Sarga 62, Verse 2', 'कन्दरात्तु विसर्पित्वा पर्वतस्य शनैः शनैः।
अहं विन्ध्यं समारुह्य भवतः प्रतिपालये॥', 'kandarāt tu visarpitvā parvatasya śanaiḥ śanaiḥ
ahaṃ vindhyaṃ samāruhya bhavataḥ pratipālaye', null, 4062002),
('ramayana-4-62-3', 3, 'Kishkindha Kanda, Sarga 62, Verse 3', 'अद्य त्वेतस्य कालस्य साग्रं वर्षशतं गतम्।
देशकालप्रतीक्षोऽस्मि हृदि कृत्वा मुनेर्वचः॥', 'adya tv etasya kālasya sāgraṃ varṣaśataṃ gatam
deśakālapratīkṣo ''smi hṛdi kṛtvā muner vacaḥ', null, 4062003),
('ramayana-4-62-4', 4, 'Kishkindha Kanda, Sarga 62, Verse 4', 'महाप्रस्थानमासाद्य स्वर्गते तु निशाकरे।
मां निर्दहति संतापो वितर्कैर्बहुभिर्वृतम्॥', 'mahāprasthānam āsādya svargate tu niśākare
māṃ nirdahati saṃtāpo vitarkair bahubhir vṛtam', null, 4062004),
('ramayana-4-62-5', 5, 'Kishkindha Kanda, Sarga 62, Verse 5', 'उत्थितां मरणे बुद्धिं मुनि वाक्यैर्निवर्तये।
बुद्धिर्या तेन मे दत्ता प्राणसंरक्षणाय तु।
सा मेऽपनयते दुःखं दीप्तेवाग्निशिखा तमः॥', 'utthitāṃ maraṇe buddhiṃ muni vākyair nivartaye
buddhir yā tena me dattā prāṇasaṃrakṣaṇāya tu
sā me ''panayate duḥkhaṃ dīptevāgniśikhā tamaḥ', null, 4062005),
('ramayana-4-62-6', 6, 'Kishkindha Kanda, Sarga 62, Verse 6', 'बुध्यता च मया वीर्यं रावणस्य दुरात्मनः।
पुत्रः संतर्जितो वाग्भिर्न त्राता मैथिली कथम्॥', 'budhyatā ca mayā vīryaṃ rāvaṇasya durātmanaḥ
putraḥ saṃtarjito vāgbhir na trātā maithilī katham', null, 4062006),
('ramayana-4-62-7', 7, 'Kishkindha Kanda, Sarga 62, Verse 7', 'तस्या विलपितं श्रुत्वा तौ च सीता विनाकृतौ।
न मे दशरथस्नेहात्पुत्रेणोत्पादितं प्रियम्॥', 'tasyā vilapitaṃ śrutvā tau ca sītā vinākṛtau
na me daśarathasnehāt putreṇotpāditaṃ priyam', null, 4062007),
('ramayana-4-62-8', 8, 'Kishkindha Kanda, Sarga 62, Verse 8', 'तस्य त्वेवं ब्रुवाणस्य संपातेर्वानरैः सह।
उत्पेततुस्तदा पक्षौ समक्षं वनचारिणाम्॥', 'tasya tv evaṃ bruvāṇasya saṃpāter vānaraiḥ saha
utpetatus tadā pakṣau samakṣaṃ vanacāriṇām', null, 4062008),
('ramayana-4-62-9', 9, 'Kishkindha Kanda, Sarga 62, Verse 9', 'स दृष्ट्वा स्वां तनुं पक्षैरुद्गतैररुणच्छदैः।
प्रहर्षमतुलं लेभे वानरांश्चेदमब्रवीत्॥', 'sa dṛṣṭvā svāṃ tanuṃ pakṣair udgatair aruṇacchadaiḥ
praharṣam atulaṃ lebhe vānarāṃś cedam abravīt', null, 4062009),
('ramayana-4-62-10', 10, 'Kishkindha Kanda, Sarga 62, Verse 10', 'निशाकरस्य महर्षेः प्रभावादमितात्मनः।
आदित्यरश्मिनिर्दग्धौ पक्षौ मे पुनरुत्थितौ॥', 'niśākarasya maharṣeḥ prabhāvād amitātmanaḥ
ādityaraśminirdagdhau pakṣau me punar utthitau', null, 4062010),
('ramayana-4-62-11', 11, 'Kishkindha Kanda, Sarga 62, Verse 11', 'यौवने वर्तमानस्य ममासीद्यः पराक्रमः।
तमेवाद्यावगच्छामि बलं पौरुषमेव च॥', 'yauvane vartamānasya mamāsīd yaḥ parākramaḥ
tam evādyāvagacchāmi balaṃ pauruṣam eva ca', null, 4062011),
('ramayana-4-62-12', 12, 'Kishkindha Kanda, Sarga 62, Verse 12', 'सर्वथा क्रियतां यत्नः सीतामधिगमिष्यथ।
पक्षलाभो ममायं वः सिद्धिप्रत्यय कारकः॥', 'sarvathā kriyatāṃ yatnaḥ sītām adhigamiṣyatha
pakṣalābho mamāyaṃ vaḥ siddhipratyaya kārakaḥ', null, 4062012),
('ramayana-4-62-13', 13, 'Kishkindha Kanda, Sarga 62, Verse 13', 'इत्युक्त्वा तान्हरीन्सर्वान्संपातिः पततां वरः।
उत्पपात गिरेः शृङ्गाज्जिज्ञासुः खगमो गतिम्॥', 'ity uktvā tān harīn sarvān saṃpātiḥ patatāṃ varaḥ
utpapāta gireḥ śṛṅgāj jijñāsuḥ khagamo gatim', null, 4062013),
('ramayana-4-62-14', 14, 'Kishkindha Kanda, Sarga 62, Verse 14', 'तस्य तद्वचनं श्रुत्वा प्रीतिसंहृष्टमानसाः।
बभूवुर्हरिशार्दूला विक्रमाभ्युदयोन्मुखाः॥', 'tasya tad vacanaṃ śrutvā prītisaṃhṛṣṭamānasāḥ
babhūvur hariśārdūlā vikramābhyudayonmukhāḥ', null, 4062014),
('ramayana-4-62-15', 15, 'Kishkindha Kanda, Sarga 62, Verse 15', 'अथ पवनसमानविक्रमाः प्लवगवराः प्रतिलब्ध पौरुषाः।
अभिजिदभिमुखां दिशं ययुर्जनकसुता परिमार्गणोन्मुखाः॥', 'atha pavanasamānavikramāḥ plavagavarāḥ pratilabdha pauruṣāḥ
abhijidabhimukhāṃ diśaṃ yayur janakasutā parimārgaṇonmukhāḥ', null, 4062015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 63 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-63-1', 1, 'Kishkindha Kanda, Sarga 63, Verse 1', 'आख्याता गृध्रराजेन समुत्पत्य प्लवंगमाः।
संगताः प्रीतिसंयुक्ता विनेदुः सिंहविक्रमाः॥', 'ākhyātā gṛdhrarājena samutpatya plavaṃgamāḥ
saṃgatāḥ prītisaṃyuktā vineduḥ siṃhavikramāḥ', null, 4063001),
('ramayana-4-63-2', 2, 'Kishkindha Kanda, Sarga 63, Verse 2', 'संपातेर्वचनं श्रुत्वा हरयो रावणक्षयम्।
हृष्टाः सागरमाजग्मुः सीतादर्शनकाङ्क्षिणः॥', 'saṃpāter vacanaṃ śrutvā harayo rāvaṇakṣayam
hṛṣṭāḥ sāgaram ājagmuḥ sītādarśanakāṅkṣiṇaḥ', null, 4063002),
('ramayana-4-63-3', 3, 'Kishkindha Kanda, Sarga 63, Verse 3', 'अभिक्रम्य तु तं देशं ददृशुर्भीमविक्रमाः।
कृत्स्नं लोकस्य महतः प्रतिबिम्बमिव स्थितम्॥', 'abhikramya tu taṃ deśaṃ dadṛśur bhīmavikramāḥ
kṛtsnaṃ lokasya mahataḥ pratibimbam iva sthitam', null, 4063003),
('ramayana-4-63-4', 4, 'Kishkindha Kanda, Sarga 63, Verse 4', 'दक्षिणस्य समुद्रस्य समासाद्योत्तरां दिशम्।
संनिवेशं ततश्चक्रुः सहिता वानरोत्तमाः॥', 'dakṣiṇasya samudrasya samāsādyottarāṃ diśam
saṃniveśaṃ tataś cakruḥ sahitā vānarottamāḥ', null, 4063004),
('ramayana-4-63-5', 5, 'Kishkindha Kanda, Sarga 63, Verse 5', 'सत्त्वैर्महद्भिर्विकृतैः क्रीडद्भिर्विविधैर्जले।
व्यात्तास्यैः सुमहाकायैरूर्मिभिश्च समाकुलम्॥', 'sattvair mahadbhir vikṛtaiḥ krīḍadbhir vividhair jale
vyāttāsyaiḥ sumahākāyair ūrmibhiś ca samākulam', null, 4063005),
('ramayana-4-63-6', 6, 'Kishkindha Kanda, Sarga 63, Verse 6', 'प्रसुप्तमिव चान्यत्र क्रीडन्तमिव चान्यतः।
क्व चित्पर्वतमात्रैश्च जलराशिभिरावृतम्॥', 'prasuptam iva cānyatra krīḍantam iva cānyataḥ
kva cit parvatamātraiś ca jalarāśibhir āvṛtam', null, 4063006),
('ramayana-4-63-7', 7, 'Kishkindha Kanda, Sarga 63, Verse 7', 'संकुलं दानवेन्द्रैश्च पातालतलवासिभिः।
रोमहर्षकरं दृष्ट्वा विषेदुः कपिकुञ्जराः॥', 'saṃkulaṃ dānavendraiś ca pātālatalavāsibhiḥ
romaharṣakaraṃ dṛṣṭvā viṣeduḥ kapikuñjarāḥ', null, 4063007),
('ramayana-4-63-8', 8, 'Kishkindha Kanda, Sarga 63, Verse 8', 'आकाशमिव दुष्पारं सागरं प्रेक्ष्य वानराः।
विषेदुः सहसा सर्वे कथं कार्यमिति ब्रुवन्॥', 'ākāśam iva duṣpāraṃ sāgaraṃ prekṣya vānarāḥ
viṣeduḥ sahasā sarve kathaṃ kāryam iti bruvan', null, 4063008),
('ramayana-4-63-9', 9, 'Kishkindha Kanda, Sarga 63, Verse 9', 'विषण्णां वाहिनीं दृष्ट्वा सागरस्य निरीक्षणात्।
आश्वासयामास हरीन्भयार्तान्हरिसत्तमः॥', 'viṣaṇṇāṃ vāhinīṃ dṛṣṭvā sāgarasya nirīkṣaṇāt
āśvāsayām āsa harīn bhayārtān harisattamaḥ', null, 4063009),
('ramayana-4-63-10', 10, 'Kishkindha Kanda, Sarga 63, Verse 10', 'न निषादेन नः कार्यं विषादो दोषवत्तरः।
विषादो हन्ति पुरुषं बालं क्रुद्ध इवोरगः॥', 'na niṣādena naḥ kāryaṃ viṣādo doṣavattaraḥ
viṣādo hanti puruṣaṃ bālaṃ kruddha ivoragaḥ', null, 4063010),
('ramayana-4-63-11', 11, 'Kishkindha Kanda, Sarga 63, Verse 11', 'विषादोऽयं प्रसहते विक्रमे पर्युपस्थिते।
तेजसा तस्य हीनस्य पुरुषार्थो न सिध्यति॥', 'viṣādo ''yaṃ prasahate vikrame paryupasthite
tejasā tasya hīnasya puruṣārtho na sidhyati', null, 4063011),
('ramayana-4-63-12', 12, 'Kishkindha Kanda, Sarga 63, Verse 12', 'तस्यां रात्र्यां व्यतीतायामङ्गदो वानरैः सह।
हरिवृद्धैः समागम्य पुनर्मन्त्रममन्त्रयत्॥', 'tasyāṃ rātryāṃ vyatītāyām aṅgado vānaraiḥ saha
harivṛddhaiḥ samāgamya punar mantram amantrayat', null, 4063012),
('ramayana-4-63-13', 13, 'Kishkindha Kanda, Sarga 63, Verse 13', 'सा वानराणां ध्वजिनी परिवार्याङ्गदं बभौ।
वासवं परिवार्येव मरुतां वाहिनी स्थिता॥', 'sā vānarāṇāṃ dhvajinī parivāryāṅgadaṃ babhau
vāsavaṃ parivāryeva marutāṃ vāhinī sthitā', null, 4063013),
('ramayana-4-63-14', 14, 'Kishkindha Kanda, Sarga 63, Verse 14', 'कोऽन्यस्तां वानरीं सेनां शक्तः स्तम्भयितुं भवेत्।
अन्यत्र वालितनयादन्यत्र च हनूमतः॥', 'ko ''nyas tāṃ vānarīṃ senāṃ śaktaḥ stambhayituṃ bhavet
anyatra vālitanayād anyatra ca hanūmataḥ', null, 4063014),
('ramayana-4-63-15', 15, 'Kishkindha Kanda, Sarga 63, Verse 15', 'ततस्तान्हरिवृद्धांश्च तच्च सैन्यमरिंदमः।
अनुमान्याङ्गदः श्रीमान्वाक्यमर्थवदब्रवीत्॥', 'tatas tān harivṛddhāṃś ca tac ca sainyam ariṃdamaḥ
anumānyāṅgadaḥ śrīmān vākyam arthavad abravīt', null, 4063015),
('ramayana-4-63-16', 16, 'Kishkindha Kanda, Sarga 63, Verse 16', 'क इदानीं महातेजा लङ्घयिष्यति सागरम्।
कः करिष्यति सुग्रीवं सत्यसंधमरिंदमम्॥', 'ka idānīṃ mahātejā laṅghayiṣyati sāgaram
kaḥ kariṣyati sugrīvaṃ satyasaṃdham ariṃdamam', null, 4063016),
('ramayana-4-63-17', 17, 'Kishkindha Kanda, Sarga 63, Verse 17', 'को वीरो योजनशतं लङ्घयेत प्लवंगमाः।
इमांश्च यूथपान्सर्वान्मोचयेत्को महाभयात्॥', 'ko vīro yojanaśataṃ laṅghayeta plavaṃgamāḥ
imāṃś ca yūthapān sarvān mocayet ko mahābhayāt', null, 4063017),
('ramayana-4-63-18', 18, 'Kishkindha Kanda, Sarga 63, Verse 18', 'कस्य प्रसादाद्दारांश्च पुत्रांश्चैव गृहाणि च।
इतो निवृत्ताः पश्येम सिद्धार्थाः सुखिनो वयम्॥', 'kasya prasādād dārāṃś ca putrāṃś caiva gṛhāṇi ca
ito nivṛttāḥ paśyema siddhārthāḥ sukhino vayam', null, 4063018),
('ramayana-4-63-19', 19, 'Kishkindha Kanda, Sarga 63, Verse 19', 'कस्य प्रसादाद्रामं च लक्ष्मणं च महाबलम्।
अभिगच्छेम संहृष्टाः सुग्रीवं च महाबलम्॥', 'kasya prasādād rāmaṃ ca lakṣmaṇaṃ ca mahābalam
abhigacchema saṃhṛṣṭāḥ sugrīvaṃ ca mahābalam', null, 4063019),
('ramayana-4-63-20', 20, 'Kishkindha Kanda, Sarga 63, Verse 20', 'यदि कश्चित्समर्थो वः सागरप्लवने हरिः।
स ददात्विह नः शीघ्रं पुण्यामभयदक्षिणाम्॥', 'yadi kaś cit samartho vaḥ sāgaraplavane hariḥ
sa dadātv iha naḥ śīghraṃ puṇyām abhayadakṣiṇām', null, 4063020),
('ramayana-4-63-21', 21, 'Kishkindha Kanda, Sarga 63, Verse 21', 'अङ्गदस्य वचः श्रुत्वा न कश्चित्किं चिदब्रवीत्।
स्तिमितेवाभवत्सर्वा सा तत्र हरिवाहिनी॥', 'aṅgadasya vacaḥ śrutvā na kaś cit kiṃ cid abravīt
stimitevābhavat sarvā sā tatra harivāhinī', null, 4063021),
('ramayana-4-63-22', 22, 'Kishkindha Kanda, Sarga 63, Verse 22', 'पुनरेवाङ्गदः प्राह तान्हरीन्हरिसत्तमः।
सर्वे बलवतां श्रेष्ठा भवन्तो दृढविक्रमाः॥', 'punar evāṅgadaḥ prāha tān harīn harisattamaḥ
sarve balavatāṃ śreṣṭhā bhavanto dṛḍhavikramāḥ', null, 4063022),
('ramayana-4-63-23', 23, 'Kishkindha Kanda, Sarga 63, Verse 23', 'व्यपदेश्य कुले जाताः पूजिताश्चाप्यभीक्ष्णशः।
न हि वो गमने संगः कदा चिदपि कस्य चित्॥', 'vyapadeśya kule jātāḥ pūjitāś cāpy abhīkṣṇaśaḥ
na hi vo gamane saṃgaḥ kadā cid api kasya cit', null, 4063023),
('ramayana-4-63-24', 24, 'Kishkindha Kanda, Sarga 63, Verse 24', 'ब्रुवध्वं यस्य या शक्तिर्गमने प्लवगर्षभाः॥', 'bruvadhvaṃ yasya yā śaktir gamane plavagarṣabhāḥ', null, 4063024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 64 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-64-1', 1, 'Kishkindha Kanda, Sarga 64, Verse 1', 'ततोऽङ्गदवचः श्रुत्वा सर्वे ते वानरोत्तमाः।
स्वं स्वं गतौ समुत्साहमाहुस्तत्र यथाक्रमम्॥', 'tato ''ṅgadavacaḥ śrutvā sarve te vānarottamāḥ
svaṃ svaṃ gatau samutsāham āhus tatra yathākramam', null, 4064001),
('ramayana-4-64-2', 2, 'Kishkindha Kanda, Sarga 64, Verse 2', 'गजो गवाक्षो गवयः शरभो गन्धमादनः।
मैन्दश्च द्विविदश्चैव सुषेणो जाम्बवांस्तथा॥', 'gajo gavākṣo gavayaḥ śarabho gandhamādanaḥ
maindaś ca dvividaś caiva suṣeṇo jāmbavāṃs tathā', null, 4064002),
('ramayana-4-64-3', 3, 'Kishkindha Kanda, Sarga 64, Verse 3', 'आबभाषे गजस्तत्र प्लवेयं दशयोजनम्।
गवाक्षो योजनान्याह गमिष्यामीति विंशतिम्॥', 'ābabhāṣe gajas tatra plaveyaṃ daśayojanam
gavākṣo yojanāny āha gamiṣyāmīti viṃśatim', null, 4064003),
('ramayana-4-64-4', 4, 'Kishkindha Kanda, Sarga 64, Verse 4', 'गवयो वानरस्तत्र वानरांस्तानुवाच ह।
त्रिंशतं तु गमिष्यामि योजनानां प्लवंगमाः॥', 'gavayo vānaras tatra vānarāṃs tān uvāca ha
triṃśataṃ tu gamiṣyāmi yojanānāṃ plavaṃgamāḥ', null, 4064004),
('ramayana-4-64-5', 5, 'Kishkindha Kanda, Sarga 64, Verse 5', 'शरभो वानरस्तत्र वानरांस्तानुवाच ह।
चत्वारिंशद्गमिष्यामि योजनानां न संशयः॥', 'śarabho vānaras tatra vānarāṃs tān uvāca ha
catvāriṃśad gamiṣyāmi yojanānāṃ na saṃśayaḥ', null, 4064005),
('ramayana-4-64-6', 6, 'Kishkindha Kanda, Sarga 64, Verse 6', 'वानरांस्तु महातेजा अब्रवीद्गन्धमादनः।
योजनानां गमिष्यामि पञ्चाशत्तु न संशयः॥', 'vānarāṃs tu mahātejā abravīd gandhamādanaḥ
yojanānāṃ gamiṣyāmi pañcāśat tu na saṃśayaḥ', null, 4064006),
('ramayana-4-64-7', 7, 'Kishkindha Kanda, Sarga 64, Verse 7', 'मैन्दस्तु वानरस्तत्र वानरांस्तानुवाच ह।
योजनानां परं षष्टिमहं प्लवितुमुत्सहे॥', 'maindas tu vānaras tatra vānarāṃs tān uvāca ha
yojanānāṃ paraṃ ṣaṣṭim ahaṃ plavitum utsahe', null, 4064007),
('ramayana-4-64-8', 8, 'Kishkindha Kanda, Sarga 64, Verse 8', 'ततस्तत्र महातेजा द्विविदः प्रत्यभाषत।
गमिष्यामि न संदेहः सप्ततिं योजनान्यहम्॥', 'tatas tatra mahātejā dvividaḥ pratyabhāṣata
gamiṣyāmi na saṃdehaḥ saptatiṃ yojanāny aham', null, 4064008),
('ramayana-4-64-9', 9, 'Kishkindha Kanda, Sarga 64, Verse 9', 'सुषेणस्तु हरिश्रेष्ठः प्रोक्तवान्कपिसत्तमान्।
अशीतिं योजनानां तु प्लवेयं प्लवगर्षभाः॥', 'suṣeṇas tu hariśreṣṭhaḥ proktavān kapisattamān
aśītiṃ yojanānāṃ tu plaveyaṃ plavagarṣabhāḥ', null, 4064009),
('ramayana-4-64-10', 10, 'Kishkindha Kanda, Sarga 64, Verse 10', 'तेषां कथयतां तत्र सर्वांस्ताननुमान्य च।
ततो वृद्धतमस्तेषां जाम्बवान्प्रत्यभाषत॥', 'teṣāṃ kathayatāṃ tatra sarvāṃs tān anumānya ca
tato vṛddhatamas teṣāṃ jāmbavān pratyabhāṣata', null, 4064010),
('ramayana-4-64-11', 11, 'Kishkindha Kanda, Sarga 64, Verse 11', 'पूर्वमस्माकमप्यासीत्कश्चिद्गतिपराक्रमः।
ते वयं वयसः पारमनुप्राप्ताः स्म साम्प्रतम्॥', 'pūrvam asmākam apy āsīt kaś cid gatiparākramaḥ
te vayaṃ vayasaḥ pāram anuprāptāḥ sma sāmpratam', null, 4064011),
('ramayana-4-64-12', 12, 'Kishkindha Kanda, Sarga 64, Verse 12', 'किं तु नैवं गते शक्यमिदं कार्यमुपेक्षितुम्।
यदर्थं कपिराजश्च रामश्च कृतनिश्चयौ॥', 'kiṃ tu naivaṃ gate śakyam idaṃ kāryam upekṣitum
yad arthaṃ kapirājaś ca rāmaś ca kṛtaniścayau', null, 4064012),
('ramayana-4-64-13', 13, 'Kishkindha Kanda, Sarga 64, Verse 13', 'साम्प्रतं कालभेदेन या गतिस्तां निबोधत।
नवतिं योजनानां तु गमिष्यामि न संशयः॥', 'sāmprataṃ kālabhedena yā gatis tāṃ nibodhata
navatiṃ yojanānāṃ tu gamiṣyāmi na saṃśayaḥ', null, 4064013),
('ramayana-4-64-14', 14, 'Kishkindha Kanda, Sarga 64, Verse 14', 'तांश्च सर्वान्हरिश्रेष्ठाञ्जाम्बवान्पुनरब्रवीत्।
न खल्वेतावदेवासीद्गमने मे पराक्रमः॥', 'tāṃś ca sarvān hariśreṣṭhāñ jāmbavān punar abravīt
na khalv etāvad evāsīd gamane me parākramaḥ', null, 4064014),
('ramayana-4-64-15', 15, 'Kishkindha Kanda, Sarga 64, Verse 15', 'मया महाबलैश्चैव यज्ञे विष्णुः सनातनः।
प्रदक्षिणीकृतः पूर्वं क्रममाणस्त्रिविक्रमः॥', 'mayā mahābalaiś caiva yajñe viṣṇuḥ sanātanaḥ
pradakṣiṇīkṛtaḥ pūrvaṃ kramamāṇas trivikramaḥ', null, 4064015),
('ramayana-4-64-16', 16, 'Kishkindha Kanda, Sarga 64, Verse 16', 'स इदानीमहं वृद्धः प्लवने मन्दविक्रमः।
यौवने च तदासीन्मे बलमप्रतिमं परैः॥', 'sa idānīm ahaṃ vṛddhaḥ plavane mandavikramaḥ
yauvane ca tadāsīn me balam apratimaṃ paraiḥ', null, 4064016),
('ramayana-4-64-17', 17, 'Kishkindha Kanda, Sarga 64, Verse 17', 'संप्रत्येतावतीं शक्तिं गमने तर्कयाम्यहम्।
नैतावता च संसिद्धिः कार्यस्यास्य भविष्यति॥', 'saṃpraty etāvatīṃ śaktiṃ gamane tarkayāmy aham
naitāvatā ca saṃsiddhiḥ kāryasyāsya bhaviṣyati', null, 4064017),
('ramayana-4-64-18', 18, 'Kishkindha Kanda, Sarga 64, Verse 18', 'अथोत्तरमुदारार्थमब्रवीदङ्गदस्तदा।
अनुमान्य महाप्राज्ञो जाम्बवन्तं महाकपिम्॥', 'athottaram udārārtham abravīd aṅgadas tadā
anumānya mahāprājño jāmbavantaṃ mahākapim', null, 4064018),
('ramayana-4-64-19', 19, 'Kishkindha Kanda, Sarga 64, Verse 19', 'अहमेतद्गमिष्यामि योजनानां शतं महत्।
निवर्तने तु मे शक्तिः स्यान्न वेति न निश्चितम्॥', 'aham etad gamiṣyāmi yojanānāṃ śataṃ mahat
nivartane tu me śaktiḥ syān na veti na niścitam', null, 4064019),
('ramayana-4-64-20', 20, 'Kishkindha Kanda, Sarga 64, Verse 20', 'तमुवाच हरिश्रेष्ठो जाम्बवान्वाक्यकोविदः।
ज्ञायते गमने शक्तिस्तव हर्यृक्षसत्तम॥', 'tam uvāca hariśreṣṭho jāmbavān vākyakovidaḥ
jñāyate gamane śaktis tava haryṛkṣasattama', null, 4064020),
('ramayana-4-64-21', 21, 'Kishkindha Kanda, Sarga 64, Verse 21', 'कामं शतसहस्रं वा न ह्येष विधिरुच्यते।
योजनानां भवाञ्शक्तो गन्तुं प्रतिनिवर्तितुम्॥', 'kāmaṃ śatasahasraṃ vā na hy eṣa vidhir ucyate
yojanānāṃ bhavāñ śakto gantuṃ pratinivartitum', null, 4064021),
('ramayana-4-64-22', 22, 'Kishkindha Kanda, Sarga 64, Verse 22', 'न हि प्रेषयिता तत स्वामी प्रेष्यः कथं चन।
भवतायं जनः सर्वः प्रेष्यः प्लवगसत्तम॥', 'na hi preṣayitā tata svāmī preṣyaḥ kathaṃ cana
bhavatāyaṃ janaḥ sarvaḥ preṣyaḥ plavagasattama', null, 4064022),
('ramayana-4-64-23', 23, 'Kishkindha Kanda, Sarga 64, Verse 23', 'भवान्कलत्रमस्माकं स्वामिभावे व्यवस्थितः।
स्वामी कलत्रं सैन्यस्य गतिरेषा परंतप॥', 'bhavān kalatram asmākaṃ svāmibhāve vyavasthitaḥ
svāmī kalatraṃ sainyasya gatir eṣā paraṃtapa', null, 4064023),
('ramayana-4-64-24', 24, 'Kishkindha Kanda, Sarga 64, Verse 24', 'तस्मात्कलत्रवत्तात प्रतिपाल्यः सदा भवान्।
अपि चैतस्य कार्यस्य भवान्मूलमरिंदम॥', 'tasmāt kalatravat tāta pratipālyaḥ sadā bhavān
api caitasya kāryasya bhavān mūlam ariṃdama', null, 4064024),
('ramayana-4-64-25', 25, 'Kishkindha Kanda, Sarga 64, Verse 25', 'मूलमर्थस्य संरक्ष्यमेष कार्यविदां नयः।
मूले हि सति सिध्यन्ति गुणाः पुष्पफलादयः॥', 'mūlam arthasya saṃrakṣyam eṣa kāryavidāṃ nayaḥ
mūle hi sati sidhyanti guṇāḥ puṣpaphalādayaḥ', null, 4064025),
('ramayana-4-64-26', 26, 'Kishkindha Kanda, Sarga 64, Verse 26', 'तद्भवानस्या कार्यस्य साधने सत्यविक्रमः।
बुद्धिविक्रमसंपन्नो हेतुरत्र परंतपः॥', 'tad bhavān asyā kāryasya sādhane satyavikramaḥ
buddhivikramasaṃpanno hetur atra paraṃtapaḥ', null, 4064026),
('ramayana-4-64-27', 27, 'Kishkindha Kanda, Sarga 64, Verse 27', 'गुरुश्च गुरुपुत्रश्च त्वं हि नः कपिसत्तम।
भवन्तमाश्रित्य वयं समर्था ह्यर्थसाधने॥', 'guruś ca guruputraś ca tvaṃ hi naḥ kapisattama
bhavantam āśritya vayaṃ samarthā hy arthasādhane', null, 4064027),
('ramayana-4-64-28', 28, 'Kishkindha Kanda, Sarga 64, Verse 28', 'उक्तवाक्यं महाप्राज्ञं जाम्बवन्तं महाकपिः।
प्रत्युवाचोत्तरं वाक्यं वालिसूनुरथाङ्गदः॥', 'uktavākyaṃ mahāprājñaṃ jāmbavantaṃ mahākapiḥ
pratyuvācottaraṃ vākyaṃ vālisūnur athāṅgadaḥ', null, 4064028),
('ramayana-4-64-29', 29, 'Kishkindha Kanda, Sarga 64, Verse 29', 'यदि नाहं गमिष्यामि नान्यो वानरपुंगवः।
पुनः खल्विदमस्माभिः कार्यं प्रायोपवेशनम्॥', 'yadi nāhaṃ gamiṣyāmi nānyo vānarapuṃgavaḥ
punaḥ khalv idam asmābhiḥ kāryaṃ prāyopaveśanam', null, 4064029),
('ramayana-4-64-30', 30, 'Kishkindha Kanda, Sarga 64, Verse 30', 'न ह्यकृत्वा हरिपतेः संदेशं तस्य धीमतः।
तत्रापि गत्वा प्राणानां पश्यामि परिरक्षणम्॥', 'na hy akṛtvā haripateḥ saṃdeśaṃ tasya dhīmataḥ
tatrāpi gatvā prāṇānāṃ paśyāmi parirakṣaṇam', null, 4064030),
('ramayana-4-64-31', 31, 'Kishkindha Kanda, Sarga 64, Verse 31', 'स हि प्रसादे चात्यर्थं कोपे च हरिरीश्वरः।
अतीत्य तस्य संदेशं विनाशो गमने भवेत्॥', 'sa hi prasāde cātyarthaṃ kope ca harir īśvaraḥ
atītya tasya saṃdeśaṃ vināśo gamane bhavet', null, 4064031),
('ramayana-4-64-32', 32, 'Kishkindha Kanda, Sarga 64, Verse 32', 'तद्यथा ह्यस्य कार्यस्य न भवत्यन्यथा गतिः।
तद्भवानेव दृष्टार्थः संचिन्तयितुमर्हति॥', 'tad yathā hy asya kāryasya na bhavaty anyathā gatiḥ
tad bhavān eva dṛṣṭārthaḥ saṃcintayitum arhati', null, 4064032),
('ramayana-4-64-33', 33, 'Kishkindha Kanda, Sarga 64, Verse 33', 'सोऽङ्गदेन तदा वीरः प्रत्युक्तः प्लवगर्षभः।
जाम्बवानुत्तरं वाक्यं प्रोवाचेदं ततोऽङ्गदम्॥', 'so ''ṅgadena tadā vīraḥ pratyuktaḥ plavagarṣabhaḥ
jāmbavān uttaraṃ vākyaṃ provācedaṃ tato ''ṅgadam', null, 4064033),
('ramayana-4-64-34', 34, 'Kishkindha Kanda, Sarga 64, Verse 34', 'अस्य ते वीर कार्यस्य न किं चित्परिहीयते।
एष संचोदयाम्येनं यः कार्यं साधयिष्यति॥', 'asya te vīra kāryasya na kiṃ cit parihīyate
eṣa saṃcodayāmy enaṃ yaḥ kāryaṃ sādhayiṣyati', null, 4064034),
('ramayana-4-64-35', 35, 'Kishkindha Kanda, Sarga 64, Verse 35', 'ततः प्रतीतं प्लवतां वरिष्ठमेकान्तमाश्रित्य सुखोपविष्टम्।
संचोदयामास हरिप्रवीरो हरिप्रवीरं हनुमन्तमेव॥', 'tataḥ pratītaṃ plavatāṃ variṣṭham ekāntam āśritya sukhopaviṣṭam
saṃcodayām āsa haripravīro haripravīraṃ hanumantam eva', null, 4064035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 65 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-65-1', 1, 'Kishkindha Kanda, Sarga 65, Verse 1', 'अनेकशतसाहस्रीं विषण्णां हरिवाहिनीम्।
जाम्बवान्समुदीक्ष्यैवं हनुमन्तमथाब्रवीत्॥', 'anekaśatasāhasrīṃ viṣaṇṇāṃ harivāhinīm
jāmbavān samudīkṣyaivaṃ hanumantam athābravīt', null, 4065001),
('ramayana-4-65-2', 2, 'Kishkindha Kanda, Sarga 65, Verse 2', 'वीर वानरलोकस्य सर्वशास्त्रविदां वर।
तूष्णीमेकान्तमाश्रित्य हनुमन्किं न जल्पसि॥', 'vīra vānaralokasya sarvaśāstravidāṃ vara
tūṣṇīm ekāntam āśritya hanuman kiṃ na jalpasi', null, 4065002),
('ramayana-4-65-3', 3, 'Kishkindha Kanda, Sarga 65, Verse 3', 'हनुमन्हरिराजस्य सुग्रीवस्य समो ह्यसि।
रामलक्ष्मणयोश्चापि तेजसा च बलेन च॥', 'hanuman harirājasya sugrīvasya samo hy asi
rāmalakṣmaṇayoś cāpi tejasā ca balena ca', null, 4065003),
('ramayana-4-65-4', 4, 'Kishkindha Kanda, Sarga 65, Verse 4', 'अरिष्टनेमिनः पुत्रौ वैनतेयो महाबलः।
गरुत्मानिव विख्यात उत्तमः सर्वपक्षिणाम्॥', 'ariṣṭaneminaḥ putrau vainateyo mahābalaḥ
garutmān iva vikhyāta uttamaḥ sarvapakṣiṇām', null, 4065004),
('ramayana-4-65-5', 5, 'Kishkindha Kanda, Sarga 65, Verse 5', 'बहुशो हि मया दृष्टः सागरे स महाबलः।
भुजगानुद्धरन्पक्षी महावेगो महायशाः॥', 'bahuśo hi mayā dṛṣṭaḥ sāgare sa mahābalaḥ
bhujagān uddharan pakṣī mahāvego mahāyaśāḥ', null, 4065005),
('ramayana-4-65-6', 6, 'Kishkindha Kanda, Sarga 65, Verse 6', 'पक्षयोर्यद्बलं तस्य तावद्भुजबलं तव।
विक्रमश्चापि वेगश्च न ते तेनापहीयते॥', 'pakṣayor yad balaṃ tasya tāvad bhujabalaṃ tava
vikramaś cāpi vegaś ca na te tenāpahīyate', null, 4065006),
('ramayana-4-65-7', 7, 'Kishkindha Kanda, Sarga 65, Verse 7', 'बलं बुद्धिश्च तेजश्च सत्त्वं च हरिसत्तम।
विशिष्टं सर्वभूतेषु किमात्मानं न बुध्यसे॥', 'balaṃ buddhiś ca tejaś ca sattvaṃ ca harisattama
viśiṣṭaṃ sarvabhūteṣu kim ātmānaṃ na budhyase', null, 4065007),
('ramayana-4-65-8', 8, 'Kishkindha Kanda, Sarga 65, Verse 8', 'अप्सराप्सरसां श्रेष्ठा विख्याता पुञ्जिकस्थला।
अज्ञनेति परिख्याता पत्नी केसरिणो हरेः॥', 'apsarāpsarasāṃ śreṣṭhā vikhyātā puñjikasthalā
ajñaneti parikhyātā patnī kesariṇo hareḥ', null, 4065008),
('ramayana-4-65-9', 9, 'Kishkindha Kanda, Sarga 65, Verse 9', 'अभिशापादभूत्तात वानरी कामरूपिणी।
दुहिता वानरेन्द्रस्य कुञ्जरस्य महात्मनः॥', 'abhiśāpād abhūt tāta vānarī kāmarūpiṇī
duhitā vānarendrasya kuñjarasya mahātmanaḥ', null, 4065009),
('ramayana-4-65-10', 10, 'Kishkindha Kanda, Sarga 65, Verse 10', 'कपित्वे चारुसर्वाङ्गी कदा चित्कामरूपिणी।
मानुषं विग्रहं कृत्वा यौवनोत्तमशालिनी॥', 'kapitve cārusarvāṅgī kadā cit kāmarūpiṇī
mānuṣaṃ vigrahaṃ kṛtvā yauvanottamaśālinī', null, 4065010),
('ramayana-4-65-11', 11, 'Kishkindha Kanda, Sarga 65, Verse 11', 'अचरत्पर्वतस्याग्रे प्रावृडम्बुदसंनिभे।
विचित्रमाल्याभरणा महार्हक्षौमवासिनी॥', 'acarat parvatasyāgre prāvṛḍambudasaṃnibhe
vicitramālyābharaṇā mahārhakṣaumavāsinī', null, 4065011),
('ramayana-4-65-12', 12, 'Kishkindha Kanda, Sarga 65, Verse 12', 'तस्या वस्त्रं विशालाक्ष्याः पीतं रक्तदशं शुभम्।
स्थितायाः पर्वतस्याग्रे मारुतोऽपहरच्छनैः॥', 'tasyā vastraṃ viśālākṣyāḥ pītaṃ raktadaśaṃ śubham
sthitāyāḥ parvatasyāgre māruto ''paharac chanaiḥ', null, 4065012),
('ramayana-4-65-13', 13, 'Kishkindha Kanda, Sarga 65, Verse 13', 'स ददर्श ततस्तस्या वृत्तावूरू सुसंहतौ।
स्तनौ च पीनौ सहितौ सुजातं चारु चाननम्॥', 'sa dadarśa tatas tasyā vṛttāv ūrū susaṃhatau
stanau ca pīnau sahitau sujātaṃ cāru cānanam', null, 4065013),
('ramayana-4-65-14', 14, 'Kishkindha Kanda, Sarga 65, Verse 14', 'तां विशालायतश्रोणीं तनुमध्यां यशस्विनीम्।
दृष्ट्वैव शुभसर्वाग्नीं पवनः काममोहितः॥', 'tāṃ viśālāyataśroṇīṃ tanumadhyāṃ yaśasvinīm
dṛṣṭvaiva śubhasarvāgnīṃ pavanaḥ kāmamohitaḥ', null, 4065014),
('ramayana-4-65-15', 15, 'Kishkindha Kanda, Sarga 65, Verse 15', 'स तां भुजाभ्यां पीनाभ्यां पर्यष्वजत मारुतः।
मन्मथाविष्टसर्वाङ्गो गतात्मा तामनिन्दिताम्॥', 'sa tāṃ bhujābhyāṃ pīnābhyāṃ paryaṣvajata mārutaḥ
manmathāviṣṭasarvāṅgo gatātmā tām aninditām', null, 4065015),
('ramayana-4-65-16', 16, 'Kishkindha Kanda, Sarga 65, Verse 16', 'सा तु तत्रैव संभ्रान्ता सुवृत्ता वाक्यमब्रवीत्।
एकपत्नीव्रतमिदं को नाशयितुमिच्छति॥', 'sā tu tatraiva saṃbhrāntā suvṛttā vākyam abravīt
ekapatnīvratam idaṃ ko nāśayitum icchati', null, 4065016),
('ramayana-4-65-17', 17, 'Kishkindha Kanda, Sarga 65, Verse 17', 'अञ्जनाया वचः श्रुत्वा मारुतः प्रत्यभाषत।
न त्वां हिंसामि सुश्रोणि मा भूत्ते सुभगे भयम्॥', 'añjanāyā vacaḥ śrutvā mārutaḥ pratyabhāṣata
na tvāṃ hiṃsāmi suśroṇi mā bhūt te subhage bhayam', null, 4065017),
('ramayana-4-65-18', 18, 'Kishkindha Kanda, Sarga 65, Verse 18', 'मनसास्मि गतो यत्त्वां परिष्वज्य यशस्विनि।
वीर्यवान्बुद्धिसंपन्नः पुत्रस्तव भविष्यति॥', 'manasāsmi gato yat tvāṃ pariṣvajya yaśasvini
vīryavān buddhisaṃpannaḥ putras tava bhaviṣyati', null, 4065018),
('ramayana-4-65-19', 19, 'Kishkindha Kanda, Sarga 65, Verse 19', 'अभ्युत्थितं ततः सूर्यं बालो दृष्ट्वा महावने।
फलं चेति जिघृक्षुस्त्वमुत्प्लुत्याभ्यपतो दिवम्॥', 'abhyutthitaṃ tataḥ sūryaṃ bālo dṛṣṭvā mahāvane
phalaṃ ceti jighṛkṣus tvam utplutyābhyapato divam', null, 4065019),
('ramayana-4-65-20', 20, 'Kishkindha Kanda, Sarga 65, Verse 20', 'शतानि त्रीणि गत्वाथ योजनानां महाकपे।
तेजसा तस्य निर्धूतो न विषादं ततो गतः॥', 'śatāni trīṇi gatvātha yojanānāṃ mahākape
tejasā tasya nirdhūto na viṣādaṃ tato gataḥ', null, 4065020),
('ramayana-4-65-21', 21, 'Kishkindha Kanda, Sarga 65, Verse 21', 'तावदापततस्तूर्णमन्तरिक्षं महाकपे।
क्षिप्तमिन्द्रेण ते वज्रं क्रोधाविष्टेन धीमता॥', 'tāvad āpatatas tūrṇam antarikṣaṃ mahākape
kṣiptam indreṇa te vajraṃ krodhāviṣṭena dhīmatā', null, 4065021),
('ramayana-4-65-22', 22, 'Kishkindha Kanda, Sarga 65, Verse 22', 'ततः शैलाग्रशिखरे वामो हनुरभज्यत।
ततो हि नामधेयं ते हनुमानिति कीर्त्यते॥', 'tataḥ śailāgraśikhare vāmo hanur abhajyata
tato hi nāmadheyaṃ te hanumān iti kīrtyate', null, 4065022),
('ramayana-4-65-23', 23, 'Kishkindha Kanda, Sarga 65, Verse 23', 'ततस्त्वां निहतं दृष्ट्वा वायुर्गन्धवहः स्वयम्।
त्रैलोक्ये भृशसंक्रुद्धो न ववौ वै प्रभञ्जनः॥', 'tatas tvāṃ nihataṃ dṛṣṭvā vāyur gandhavahaḥ svayam
trailokye bhṛśasaṃkruddho na vavau vai prabhañjanaḥ', null, 4065023),
('ramayana-4-65-24', 24, 'Kishkindha Kanda, Sarga 65, Verse 24', 'संभ्रान्ताश्च सुराः सर्वे त्रैलोक्ये क्षुभिते सति।
प्रसादयन्ति संक्रुद्धं मारुतं भुवनेश्वराः॥', 'saṃbhrāntāś ca surāḥ sarve trailokye kṣubhite sati
prasādayanti saṃkruddhaṃ mārutaṃ bhuvaneśvarāḥ', null, 4065024),
('ramayana-4-65-25', 25, 'Kishkindha Kanda, Sarga 65, Verse 25', 'प्रसादिते च पवने ब्रह्मा तुभ्यं वरं ददौ।
अशस्त्रवध्यतां तात समरे सत्यविक्रम॥', 'prasādite ca pavane brahmā tubhyaṃ varaṃ dadau
aśastravadhyatāṃ tāta samare satyavikrama', null, 4065025),
('ramayana-4-65-26', 26, 'Kishkindha Kanda, Sarga 65, Verse 26', 'वज्रस्य च निपातेन विरुजं त्वां समीक्ष्य च।
सहस्रनेत्रः प्रीतात्मा ददौ ते वरमुत्तमम्॥', 'vajrasya ca nipātena virujaṃ tvāṃ samīkṣya ca
sahasranetraḥ prītātmā dadau te varam uttamam', null, 4065026),
('ramayana-4-65-27', 27, 'Kishkindha Kanda, Sarga 65, Verse 27', 'स्वच्छन्दतश्च मरणं ते भूयादिति वै प्रभो।
स त्वं केसरिणः पुत्रः क्षेत्रजो भीमविक्रमः॥', 'svacchandataś ca maraṇaṃ te bhūyād iti vai prabho
sa tvaṃ kesariṇaḥ putraḥ kṣetrajo bhīmavikramaḥ', null, 4065027),
('ramayana-4-65-28', 28, 'Kishkindha Kanda, Sarga 65, Verse 28', 'मारुतस्यौरसः पुत्रस्तेजसा चापि तत्समः।
त्वं हि वायुसुतो वत्स प्लवने चापि तत्समः॥', 'mārutasyaurasaḥ putras tejasā cāpi tatsamaḥ
tvaṃ hi vāyusuto vatsa plavane cāpi tatsamaḥ', null, 4065028),
('ramayana-4-65-29', 29, 'Kishkindha Kanda, Sarga 65, Verse 29', 'वयमद्य गतप्राणा भवानस्मासु साम्प्रतम्।
दाक्ष्यविक्रमसंपन्नः पक्षिराज इवापरः॥', 'vayam adya gataprāṇā bhavān asmāsu sāmpratam
dākṣyavikramasaṃpannaḥ pakṣirāja ivāparaḥ', null, 4065029),
('ramayana-4-65-30', 30, 'Kishkindha Kanda, Sarga 65, Verse 30', 'त्रिविक्रमे मया तात सशैलवनकानना।
त्रिः सप्तकृत्वः पृथिवी परिक्रान्ता प्रदक्षिणम्॥', 'trivikrame mayā tāta saśailavanakānanā
triḥ saptakṛtvaḥ pṛthivī parikrāntā pradakṣiṇam', null, 4065030),
('ramayana-4-65-31', 31, 'Kishkindha Kanda, Sarga 65, Verse 31', 'तदा चौषधयोऽस्माभिः संचिता देवशासनात्।
निष्पन्नममृतं याभिस्तदासीन्नो महद्बलम्॥', 'tadā cauṣadhayo ''smābhiḥ saṃcitā devaśāsanāt
niṣpannam amṛtaṃ yābhis tadāsīn no mahad balam', null, 4065031),
('ramayana-4-65-32', 32, 'Kishkindha Kanda, Sarga 65, Verse 32', 'स इदानीमहं वृद्धः परिहीनपराक्रमः।
साम्प्रतं कालमस्माकं भवान्सर्वगुणान्वितः॥', 'sa idānīm ahaṃ vṛddhaḥ parihīnaparākramaḥ
sāmprataṃ kālam asmākaṃ bhavān sarvaguṇānvitaḥ', null, 4065032),
('ramayana-4-65-33', 33, 'Kishkindha Kanda, Sarga 65, Verse 33', 'तद्विजृम्भस्व विक्रान्तः प्लवतामुत्तमो ह्यसि।
त्वद्वीर्यं द्रष्टुकामेयं सर्वा वानरवाहिनी॥', 'tad vijṛmbhasva vikrāntaḥ plavatām uttamo hy asi
tvadvīryaṃ draṣṭukāmeyaṃ sarvā vānaravāhinī', null, 4065033),
('ramayana-4-65-34', 34, 'Kishkindha Kanda, Sarga 65, Verse 34', 'उत्तिष्ठ हरिशार्दूल लङ्घयस्व महार्णवम्।
परा हि सर्वभूतानां हनुमन्या गतिस्तव॥', 'uttiṣṭha hariśārdūla laṅghayasva mahārṇavam
parā hi sarvabhūtānāṃ hanuman yā gatis tava', null, 4065034),
('ramayana-4-65-35', 35, 'Kishkindha Kanda, Sarga 65, Verse 35', 'विषाण्णा हरयः सर्वे हनुमन्किमुपेक्षसे।
विक्रमस्व महावेगो विष्णुस्त्रीन्विक्रमानिव॥', 'viṣāṇṇā harayaḥ sarve hanuman kim upekṣase
vikramasva mahāvego viṣṇus trīn vikramān iva', null, 4065035),
('ramayana-4-65-36', 36, 'Kishkindha Kanda, Sarga 65, Verse 36', 'ततस्तु वै जाम्बवताभिचोदितः प्रतीतवेगः पवनात्मजः कपिः।
प्रहर्षयंस्तां हरिवीर वाहिनीं चकार रूपं महदात्मनस्तदा॥', 'tatas tu vai jāmbavatābhicoditaḥ pratītavegaḥ pavanātmajaḥ kapiḥ
praharṣayaṃs tāṃ harivīra vāhinīṃ cakāra rūpaṃ mahad ātmanas tadā', null, 4065036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 66 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 4 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-4-66-1', 1, 'Kishkindha Kanda, Sarga 66, Verse 1', 'संस्तूयमानो हनुमान्व्यवर्धत महाबलः।
समाविध्य च लाङ्गूलं हर्षाच्च बलमेयिवान्॥', 'saṃstūyamāno hanumān vyavardhata mahābalaḥ
samāvidhya ca lāṅgūlaṃ harṣāc ca balam eyivān', null, 4066001),
('ramayana-4-66-2', 2, 'Kishkindha Kanda, Sarga 66, Verse 2', 'तस्य संस्तूयमानस्य सर्वैर्वानरपुंगवैः।
तेजसापूर्यमाणस्य रूपमासीदनुत्तमम्॥', 'tasya saṃstūyamānasya sarvair vānarapuṃgavaiḥ
tejasāpūryamāṇasya rūpam āsīd anuttamam', null, 4066002),
('ramayana-4-66-3', 3, 'Kishkindha Kanda, Sarga 66, Verse 3', 'यथा विजृम्भते सिंहो विवृद्धो गिरिगह्वरे।
मारुतस्यौरसः पुत्रस्तथा संप्रति जृम्भते॥', 'yathā vijṛmbhate siṃho vivṛddho girigahvare
mārutasyaurasaḥ putras tathā saṃprati jṛmbhate', null, 4066003),
('ramayana-4-66-4', 4, 'Kishkindha Kanda, Sarga 66, Verse 4', 'अशोभत मुखं तस्य जृम्भमाणस्य धीमतः।
अम्बरीषोपमं दीप्तं विधूम इव पावकः॥', 'aśobhata mukhaṃ tasya jṛmbhamāṇasya dhīmataḥ
ambarīṣopamaṃ dīptaṃ vidhūma iva pāvakaḥ', null, 4066004),
('ramayana-4-66-5', 5, 'Kishkindha Kanda, Sarga 66, Verse 5', 'हरीणामुत्थितो मध्यात्संप्रहृष्टतनूरुहः।
अभिवाद्य हरीन्वृद्धान्हनुमानिदमब्रवीत्॥', 'harīṇām utthito madhyāt saṃprahṛṣṭatanūruhaḥ
abhivādya harīn vṛddhān hanumān idam abravīt', null, 4066005),
('ramayana-4-66-6', 6, 'Kishkindha Kanda, Sarga 66, Verse 6', 'अरुजन्पर्वताग्राणि हुताशनसखोऽनिलः।
बलवानप्रमेयश्च वायुराकाशगोचरः॥', 'arujan parvatāgrāṇi hutāśanasakho ''nilaḥ
balavān aprameyaś ca vāyur ākāśagocaraḥ', null, 4066006),
('ramayana-4-66-7', 7, 'Kishkindha Kanda, Sarga 66, Verse 7', 'तस्याहं शीघ्रवेगस्य शीघ्रगस्य महात्मनः।
मारुतस्यौरसः पुत्रः प्लवने नास्ति मे समः॥', 'tasyāhaṃ śīghravegasya śīghragasya mahātmanaḥ
mārutasyaurasaḥ putraḥ plavane nāsti me samaḥ', null, 4066007),
('ramayana-4-66-8', 8, 'Kishkindha Kanda, Sarga 66, Verse 8', 'उत्सहेयं हि विस्तीर्णमालिखन्तमिवाम्बरम्।
मेरुं गिरिमसंगेन परिगन्तुं सहस्रशः॥', 'utsaheyaṃ hi vistīrṇam ālikhantam ivāmbaram
meruṃ girim asaṃgena parigantuṃ sahasraśaḥ', null, 4066008),
('ramayana-4-66-9', 9, 'Kishkindha Kanda, Sarga 66, Verse 9', 'बाहुवेगप्रणुन्नेन सागरेणाहमुत्सहे।
समाप्लावयितुं लोकं सपर्वतनदीह्रदम्॥', 'bāhuvegapraṇunnena sāgareṇāham utsahe
samāplāvayituṃ lokaṃ saparvatanadīhradam', null, 4066009),
('ramayana-4-66-10', 10, 'Kishkindha Kanda, Sarga 66, Verse 10', 'ममोरुजङ्घावेगेन भविष्यति समुत्थितः।
संमूर्छितमहाग्राहः समुद्रो वरुणालयः॥', 'mamorujaṅghāvegena bhaviṣyati samutthitaḥ
saṃmūrchitamahāgrāhaḥ samudro varuṇālayaḥ', null, 4066010),
('ramayana-4-66-11', 11, 'Kishkindha Kanda, Sarga 66, Verse 11', 'पन्नगाशनमाकाशे पतन्तं पक्षिसेवितम्।
वैनतेयमहं शक्तः परिगन्तुं सहस्रशः॥', 'pannagāśanam ākāśe patantaṃ pakṣisevitam
vainateyam ahaṃ śaktaḥ parigantuṃ sahasraśaḥ', null, 4066011),
('ramayana-4-66-12', 12, 'Kishkindha Kanda, Sarga 66, Verse 12', 'उदयात्प्रस्थितं वापि ज्वलन्तं रश्मिमालिनम्।
अनस्तमितमादित्यमभिगन्तुं समुत्सहे॥', 'udayāt prasthitaṃ vāpi jvalantaṃ raśmimālinam
anastamitam ādityam abhigantuṃ samutsahe', null, 4066012),
('ramayana-4-66-13', 13, 'Kishkindha Kanda, Sarga 66, Verse 13', 'ततो भूमिमसंस्पृश्य पुनरागन्तुमुत्सहे।
प्रवेगेनैव महता भीमेन प्लवगर्षभाः॥', 'tato bhūmim asaṃspṛśya punar āgantum utsahe
pravegenaiva mahatā bhīmena plavagarṣabhāḥ', null, 4066013),
('ramayana-4-66-14', 14, 'Kishkindha Kanda, Sarga 66, Verse 14', 'उत्सहेयमतिक्रान्तुं सर्वानाकाशगोचरान्।
सागरं क्षोभयिष्यामि दारयिष्यामि मेदिनीम्॥', 'utsaheyam atikrāntuṃ sarvān ākāśagocarān
sāgaraṃ kṣobhayiṣyāmi dārayiṣyāmi medinīm', null, 4066014),
('ramayana-4-66-15', 15, 'Kishkindha Kanda, Sarga 66, Verse 15', 'पर्वतान्कम्पयिष्यामि प्लवमानः प्लवंगमाः।
हरिष्ये चोरुवेगेन प्लवमानो महार्णवम्॥', 'parvatān kampayiṣyāmi plavamānaḥ plavaṃgamāḥ
hariṣye coruvegena plavamāno mahārṇavam', null, 4066015),
('ramayana-4-66-16', 16, 'Kishkindha Kanda, Sarga 66, Verse 16', 'लतानां वीरुधां पुष्पं पादपानां च सर्वशः।
अनुयास्यति मामद्य प्लवमानं विहायसा।
भविष्यति हि मे पन्थाः स्वातेः पन्था इवाम्बरे॥', 'latānāṃ vīrudhāṃ puṣpaṃ pādapānāṃ ca sarvaśaḥ
anuyāsyati mām adya plavamānaṃ vihāyasā
bhaviṣyati hi me panthāḥ svāteḥ panthā ivāmbare', null, 4066016),
('ramayana-4-66-17', 17, 'Kishkindha Kanda, Sarga 66, Verse 17', 'चरन्तं घोरमाकाशमुत्पतिष्यन्तमेव च।
द्रक्ष्यन्ति निपतन्तं च सर्वभूतानि वानराः॥', 'carantaṃ ghoram ākāśam utpatiṣyantam eva ca
drakṣyanti nipatantaṃ ca sarvabhūtāni vānarāḥ', null, 4066017),
('ramayana-4-66-18', 18, 'Kishkindha Kanda, Sarga 66, Verse 18', 'महामेरुप्रतीकाशं मां द्रक्ष्यध्वं प्लवंगमाः।
दिवमावृत्य गच्छन्तं ग्रसमानमिवाम्बरम्॥', 'mahāmerupratīkāśaṃ māṃ drakṣyadhvaṃ plavaṃgamāḥ
divam āvṛtya gacchantaṃ grasamānam ivāmbaram', null, 4066018),
('ramayana-4-66-19', 19, 'Kishkindha Kanda, Sarga 66, Verse 19', 'विधमिष्यामि जीमूतान्कम्पयिष्यामि पर्वतान्।
सागरं क्षोभयिष्यामि प्लवमानः समाहितः॥', 'vidhamiṣyāmi jīmūtān kampayiṣyāmi parvatān
sāgaraṃ kṣobhayiṣyāmi plavamānaḥ samāhitaḥ', null, 4066019),
('ramayana-4-66-20', 20, 'Kishkindha Kanda, Sarga 66, Verse 20', 'वैनतेयस्य वा शक्तिर्मम वा मारुतस्य वा।
ऋते सुपर्णराजानं मारुतं वा महाबलम्।
न हि भूतं प्रपश्यामि यो मां प्लुतमनुव्रजेत्॥', 'vainateyasya vā śaktir mama vā mārutasya vā
ṛte suparṇarājānaṃ mārutaṃ vā mahābalam
na hi bhūtaṃ prapaśyāmi yo māṃ plutam anuvrajet', null, 4066020),
('ramayana-4-66-21', 21, 'Kishkindha Kanda, Sarga 66, Verse 21', 'निमेषान्तरमात्रेण निरालम्भनमम्बरम्।
सहसा निपतिष्यामि घनाद्विद्युदिवोत्थिता॥', 'nimeṣāntaramātreṇa nirālambhanam ambaram
sahasā nipatiṣyāmi ghanād vidyud ivotthitā', null, 4066021),
('ramayana-4-66-22', 22, 'Kishkindha Kanda, Sarga 66, Verse 22', 'भविष्यति हि मे रूपं प्लवमानस्य सागरम्।
विष्णोः प्रक्रममाणस्य तदा त्रीन्विक्रमानिव॥', 'bhaviṣyati hi me rūpaṃ plavamānasya sāgaram
viṣṇoḥ prakramamāṇasya tadā trīn vikramān iva', null, 4066022),
('ramayana-4-66-23', 23, 'Kishkindha Kanda, Sarga 66, Verse 23', 'बुद्ध्या चाहं प्रपश्यामि मनश्चेष्टा च मे तथा।
अहं द्रक्ष्यामि वैदेहीं प्रमोदध्वं प्लवंगमाः॥', 'buddhyā cāhaṃ prapaśyāmi manaś ceṣṭā ca me tathā
ahaṃ drakṣyāmi vaidehīṃ pramodadhvaṃ plavaṃgamāḥ', null, 4066023),
('ramayana-4-66-24', 24, 'Kishkindha Kanda, Sarga 66, Verse 24', 'मारुतस्य समो वेगे गरुडस्य समो जवे।
अयुतं योजनानां तु गमिष्यामीति मे मतिः॥', 'mārutasya samo vege garuḍasya samo jave
ayutaṃ yojanānāṃ tu gamiṣyāmīti me matiḥ', null, 4066024),
('ramayana-4-66-25', 25, 'Kishkindha Kanda, Sarga 66, Verse 25', 'वासवस्य सवज्रस्य ब्रह्मणो वा स्वयम्भुवः।
विक्रम्य सहसा हस्तादमृतं तदिहानये।
लङ्कां वापि समुत्क्षिप्य गच्छेयमिति मे मतिः॥', 'vāsavasya savajrasya brahmaṇo vā svayambhuvaḥ
vikramya sahasā hastād amṛtaṃ tad ihānaye
laṅkāṃ vāpi samutkṣipya gaccheyam iti me matiḥ', null, 4066025),
('ramayana-4-66-26', 26, 'Kishkindha Kanda, Sarga 66, Verse 26', 'तमेवं वानरश्रेष्ठं गर्जन्तममितौजसं।
उवाच परिसंहृष्टो जाम्बवान्हरिसत्तमः॥', 'tam evaṃ vānaraśreṣṭhaṃ garjantam amitaujasaṃ
uvāca parisaṃhṛṣṭo jāmbavān harisattamaḥ', null, 4066026),
('ramayana-4-66-27', 27, 'Kishkindha Kanda, Sarga 66, Verse 27', 'वीर केसरिणः पुत्र वेगवन्मारुतात्मज।
ज्ञातीनां विपुलं शोकस्त्वया तात प्रणाशितः॥', 'vīra kesariṇaḥ putra vegavan mārutātmaja
jñātīnāṃ vipulaṃ śokas tvayā tāta praṇāśitaḥ', null, 4066027),
('ramayana-4-66-28', 28, 'Kishkindha Kanda, Sarga 66, Verse 28', 'तव कल्याणरुचयः कपिमुख्याः समागताः।
मङ्गलं कार्यसिद्ध्यर्थं करिष्यन्ति समाहिताः॥', 'tava kalyāṇarucayaḥ kapimukhyāḥ samāgatāḥ
maṅgalaṃ kāryasiddhyarthaṃ kariṣyanti samāhitāḥ', null, 4066028),
('ramayana-4-66-29', 29, 'Kishkindha Kanda, Sarga 66, Verse 29', 'ऋषीणां च प्रसादेन कपिवृद्धमतेन च।
गुरूणां च प्रसादेन प्लवस्व त्वं महार्णवम्॥', 'ṛṣīṇāṃ ca prasādena kapivṛddhamatena ca
gurūṇāṃ ca prasādena plavasva tvaṃ mahārṇavam', null, 4066029),
('ramayana-4-66-30', 30, 'Kishkindha Kanda, Sarga 66, Verse 30', 'स्थास्यामश्चैकपादेन यावदागमनं तव।
त्वद्गतानि च सर्वेषां जीवितानि वनौकसाम्॥', 'sthāsyāmaś caikapādena yāvadāgamanaṃ tava
tvadgatāni ca sarveṣāṃ jīvitāni vanaukasām', null, 4066030),
('ramayana-4-66-31', 31, 'Kishkindha Kanda, Sarga 66, Verse 31', 'ततस्तु हरिशार्दूलस्तानुवाच वनौकसः।
नेयं मम मही वेगं प्लवने धारयिष्यति॥', 'tatas tu hariśārdūlas tān uvāca vanaukasaḥ
neyaṃ mama mahī vegaṃ plavane dhārayiṣyati', null, 4066031),
('ramayana-4-66-32', 32, 'Kishkindha Kanda, Sarga 66, Verse 32', 'एतानि हि नगस्यास्य शिलासंकटशालिनः।
शिखराणि महेन्द्रस्य स्थिराणि च महान्ति च॥', 'etāni hi nagasyāsya śilāsaṃkaṭaśālinaḥ
śikharāṇi mahendrasya sthirāṇi ca mahānti ca', null, 4066032),
('ramayana-4-66-33', 33, 'Kishkindha Kanda, Sarga 66, Verse 33', 'एतानि मम निष्पेषं पादयोः पततां वराः।
प्लवतो धारयिष्यन्ति योजनानामितः शतम्॥', 'etāni mama niṣpeṣaṃ pādayoḥ patatāṃ varāḥ
plavato dhārayiṣyanti yojanānām itaḥ śatam', null, 4066033),
('ramayana-4-66-34', 34, 'Kishkindha Kanda, Sarga 66, Verse 34', 'ततस्तु मारुतप्रख्यः स हरिर्मारुतात्मजः।
आरुरोह नगश्रेष्ठं महेन्द्रमरिमर्दनः॥', 'tatas tu mārutaprakhyaḥ sa harir mārutātmajaḥ
āruroha nagaśreṣṭhaṃ mahendram arimardanaḥ', null, 4066034),
('ramayana-4-66-35', 35, 'Kishkindha Kanda, Sarga 66, Verse 35', 'वृतं नानाविधैर्वृक्षैर्मृगसेवितशाद्वलम्।
लताकुसुमसंबाधं नित्यपुष्पफलद्रुमम्॥', 'vṛtaṃ nānāvidhair vṛkṣair mṛgasevitaśādvalam
latākusumasaṃbādhaṃ nityapuṣpaphaladrumam', null, 4066035),
('ramayana-4-66-36', 36, 'Kishkindha Kanda, Sarga 66, Verse 36', 'सिंहशार्दूलचरितं मत्तमातङ्गसेवितम्।
मत्तद्विजगणोद्घुष्टं सलिलोत्पीडसंकुलम्॥', 'siṃhaśārdūlacaritaṃ mattamātaṅgasevitam
mattadvijagaṇodghuṣṭaṃ salilotpīḍasaṃkulam', null, 4066036),
('ramayana-4-66-37', 37, 'Kishkindha Kanda, Sarga 66, Verse 37', 'महद्भिरुच्छ्रितं शृङ्गैर्महेन्द्रं स महाबलः।
विचचार हरिश्रेष्ठो महेन्द्रसमविक्रमः॥', 'mahadbhir ucchritaṃ śṛṅgair mahendraṃ sa mahābalaḥ
vicacāra hariśreṣṭho mahendrasamavikramaḥ', null, 4066037),
('ramayana-4-66-38', 38, 'Kishkindha Kanda, Sarga 66, Verse 38', 'पादाभ्यां पीडितस्तेन महाशैलो महात्मना।
ररास सिंहाभिहतो महान्मत्त इव द्विपः॥', 'pādābhyāṃ pīḍitas tena mahāśailo mahātmanā
rarāsa siṃhābhihato mahān matta iva dvipaḥ', null, 4066038),
('ramayana-4-66-39', 39, 'Kishkindha Kanda, Sarga 66, Verse 39', 'मुमोच सलिलोत्पीडान्विप्रकीर्णशिलोच्चयः।
वित्रस्तमृगमातङ्गः प्रकम्पितमहाद्रुमः॥', 'mumoca salilotpīḍān viprakīrṇaśiloccayaḥ
vitrastamṛgamātaṅgaḥ prakampitamahādrumaḥ', null, 4066039),
('ramayana-4-66-40', 40, 'Kishkindha Kanda, Sarga 66, Verse 40', 'नानागन्धर्वमिथुनैः पानसंसर्गकर्कशैः।
उत्पतद्भिर्विहंगैश्च विद्याधरगणैरपि॥', 'nānāgandharvamithunaiḥ pānasaṃsargakarkaśaiḥ
utpatadbhir vihaṃgaiś ca vidyādharagaṇair api', null, 4066040),
('ramayana-4-66-41', 41, 'Kishkindha Kanda, Sarga 66, Verse 41', 'त्यज्यमानमहासानुः संनिलीनमहोरगः।
शैलशृङ्गशिलोद्घातस्तदाभूत्स महागिरिः॥', 'tyajyamānamahāsānuḥ saṃnilīnamahoragaḥ
śailaśṛṅgaśilodghātas tadābhūt sa mahāgiriḥ', null, 4066041),
('ramayana-4-66-42', 42, 'Kishkindha Kanda, Sarga 66, Verse 42', 'निःश्वसद्भिस्तदा तैस्तु भुजगैरर्धनिःसृतैः।
सपताक इवाभाति स तदा धरणीधरः॥', 'niḥśvasadbhis tadā tais tu bhujagair ardhaniḥsṛtaiḥ
sapatāka ivābhāti sa tadā dharaṇīdharaḥ', null, 4066042),
('ramayana-4-66-43', 43, 'Kishkindha Kanda, Sarga 66, Verse 43', 'ऋषिभिस्त्रास संभ्रान्तैस्त्यज्यमानः शिलोच्चयः।
सीदन्महति कान्तारे सार्थहीन इवाध्वगः॥', 'ṛṣibhis trāsa saṃbhrāntais tyajyamānaḥ śiloccayaḥ
sīdan mahati kāntāre sārthahīna ivādhvagaḥ', null, 4066043),
('ramayana-4-66-44', 44, 'Kishkindha Kanda, Sarga 66, Verse 44', 'स वेगवान्वेगसमाहितात्मा हरिप्रवीरः परवीरहन्ता।
मनः समाधाय महानुभावो जगाम लङ्कां मनसा मनस्वी॥', 'sa vegavān vegasamāhitātmā haripravīraḥ paravīrahantā
manaḥ samādhāya mahānubhāvo jagāma laṅkāṃ manasā manasvī', null, 4066044)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into translations (verse_id, language, text, source_id, is_primary) values
('ramayana-4-1-1', 'en', 'Reaching that lake crowded with lotuses, lilies and fish, Rama with Lakshmana lamented, his senses in turmoil.', 'veda-app-ai-draft', true),
('ramayana-4-1-2', 'en', 'As soon as he saw it his senses trembled with excitement, and overcome by longing he said this to Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-1-3', 'en', 'Lakshmana, see the beautiful forest of the Pampa, where trees shine like hills with peaks.', 'veda-app-ai-draft', true),
('ramayana-4-1-4', 'en', 'But I, burning with grief, am tormented by sorrows, by Bharata''s suffering and by Vaidehi''s abduction.', 'veda-app-ai-draft', true),
('ramayana-4-1-5', 'en', 'This blue and yellow meadow shines all the more, as if spread with carpets of the trees'' many flowers.', 'veda-app-ai-draft', true),
('ramayana-4-1-6', 'en', 'Lakshmana, this is a season of pleasant breezes and strong love, a fragrant month when trees bear flowers and fruit.', 'veda-app-ai-draft', true),
('ramayana-4-1-7', 'en', 'See, Lakshmana, the forests rich in blossoms pouring down showers of flowers like clouds pouring rain.', 'veda-app-ai-draft', true),
('ramayana-4-1-8', 'en', 'On the lovely rocky slopes, many forest trees, shaken by the wind, scatter flowers over the ground.', 'veda-app-ai-draft', true),
('ramayana-4-1-9', 'en', 'The breeze blows pleasant to the touch, cool as sandal, while bees hum in the honey-scented woods.', 'veda-app-ai-draft', true),
('ramayana-4-1-10', 'en', 'On the lovely slopes, mountains shine with great flowering trees, their tops crowded together.', 'veda-app-ai-draft', true),
('ramayana-4-1-11', 'en', 'See these karnikara trees with flowering tips all around, covered in gold like men dressed in yellow.', 'veda-app-ai-draft', true),
('ramayana-4-1-12', 'en', 'This spring, Lakshmana, ringing with many birds, inflames the grief of me who am parted from Sita.', 'veda-app-ai-draft', true),
('ramayana-4-1-13', 'en', 'Love torments me, overcome with grief as I am, and the cuckoo, joyful and singing, calls to me.', 'veda-app-ai-draft', true),
('ramayana-4-1-14', 'en', 'This happy datyuha bird crying by the lovely forest stream will make me, gripped by love, grieve more, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-1-15', 'en', 'Birds mingle with their mates, delighted by their own flocks, sweet-voiced and gladdened by the bee-kings.', 'veda-app-ai-draft', true),
('ramayana-4-1-16', 'en', 'That fawn-eyed one torments me, Lakshmana, as I am forced by worry and grief, and the cruel breeze of spring burns me.', 'veda-app-ai-draft', true),
('ramayana-4-1-17', 'en', 'Peacocks on the mountain slopes surrounded by peahens increase the love of me, already overcome by it.', 'veda-app-ai-draft', true),
('ramayana-4-1-18', 'en', 'See, Lakshmana, the peahen, moved by love, dances around her dancing mate on the mountain slopes.', 'veda-app-ai-draft', true),
('ramayana-4-1-19', 'en', 'Surely no demon has carried off the peacock''s beloved in the forest. But for me, living without her in this flowering month is unbearable.', 'veda-app-ai-draft', true),
('ramayana-4-1-20', 'en', 'See, Lakshmana, the flowers of the forests heavy with blossom at winter''s end are fruitless for me.', 'veda-app-ai-draft', true),
('ramayana-4-1-21', 'en', 'Joyful birds in flocks call sweetly, as if calling to one another, maddening me with longing.', 'veda-app-ai-draft', true),
('ramayana-4-1-22', 'en', 'Surely Sita, in another''s power, grieves as I do, my dark, lotus-eyed, soft-spoken love.', 'veda-app-ai-draft', true),
('ramayana-4-1-23', 'en', 'This breeze bearing flowers, pleasant and cool, feels like fire to me as I think of my beloved.', 'veda-app-ai-draft', true),
('ramayana-4-1-24', 'en', 'That crow sitting in the tree cawed joyfully then, when I was without her.', 'veda-app-ai-draft', true),
('ramayana-4-1-25', 'en', 'That very bird was the herald of Vaidehi''s loss. Now it will lead me near the wide-eyed one.', 'veda-app-ai-draft', true),
('ramayana-4-1-26', 'en', 'See, Lakshmana, the loud calling in the forest of birds singing on the flowering treetops, which heightens passion.', 'veda-app-ai-draft', true),
('ramayana-4-1-27', 'en', 'Lakshmana, see the lotuses in the colourful forest rows of the Pampa shining in the water like the rising sun.', 'veda-app-ai-draft', true),
('ramayana-4-1-28', 'en', 'This Pampa has clear water, is spread with lotuses and blue lilies, crowded with swans and ducks, and full of fragrant flowers.', 'veda-app-ai-draft', true),
('ramayana-4-1-29', 'en', 'It is always home to chakravaka birds, has lovely slopes and groves, and shines with herds of elephants and deer coming for water.', 'veda-app-ai-draft', true),
('ramayana-4-1-30', 'en', 'My eyes want to look at the lotus buds and petals, Lakshmana, because they are like the shape of Sita''s eyes.', 'veda-app-ai-draft', true),
('ramayana-4-1-31', 'en', 'Mixed with lotus pollen and flowing out between the trees, the charming breeze blows like Sita''s breath.', 'veda-app-ai-draft', true),
('ramayana-4-1-32', 'en', 'Lakshmana, see on the southern mountain slope of the Pampa a flowering karnikara branch of great beauty.', 'veda-app-ai-draft', true),
('ramayana-4-1-33', 'en', 'This king of mountains, adorned with minerals, sends up colourful dust stirred by the wind.', 'veda-app-ai-draft', true),
('ramayana-4-1-34', 'en', 'The mountain slopes all round, Lakshmana, look as if aflame with leafless, fully flowered kimshuka trees.', 'veda-app-ai-draft', true),
('ramayana-4-1-35', 'en', 'These grow on the Pampa''s banks, clustered and honey-scented: jasmine and mallika thickets and flowering karavira.', 'veda-app-ai-draft', true),
('ramayana-4-1-36', 'en', 'Ketaki, sinduvara and vasanti in full bloom, fragrant madhavi and kunda bushes everywhere.', 'veda-app-ai-draft', true),
('ramayana-4-1-37', 'en', 'Chiribilva, madhuka, vanjula and bakula, champaka, tilaka and naga trees are in bloom.', 'veda-app-ai-draft', true),
('ramayana-4-1-38', 'en', 'Nipa, varana and date palms in full bloom, ankola, kuranta, churnaka and paribhadraka.', 'veda-app-ai-draft', true),
('ramayana-4-1-39', 'en', 'Mango, patali and kovidara in flower, mucukunda and arjuna trees are seen on the mountain slopes.', 'veda-app-ai-draft', true),
('ramayana-4-1-40', 'en', 'Ketaka, uddalaka, shirisha, shimshapa and dhava, silk-cotton, red kimshuka and kurabaka, tinisha, naktamala, sandal and syandana trees.', 'veda-app-ai-draft', true),
('ramayana-4-1-41', 'en', 'With all these flowers scattered on the mountain slopes, Lakshmana, the rocks have turned yellow and red.', 'veda-app-ai-draft', true),
('ramayana-4-1-42', 'en', 'See, Lakshmana, the trees blossoming at winter''s end. In the flower month they bloom as if competing with each other.', 'veda-app-ai-draft', true),
('ramayana-4-1-43', 'en', 'See this lake with cool water, Lakshmana, full of lotuses, visited by chakravakas and karandavas, filled with plavas and cranes, and frequented by boars and deer.', 'veda-app-ai-draft', true),
('ramayana-4-1-44', 'en', 'The Pampa shines all the more with singing birds.', 'veda-app-ai-draft', true),
('ramayana-4-1-45', 'en', 'The many joyful birds seem to kindle my longing as I remember my dark, moon-faced beloved with lotus eyes.', 'veda-app-ai-draft', true),
('ramayana-4-1-46', 'en', 'See on the colourful slopes the stags with their does, while I am separated from fawn-eyed Vaidehi.', 'veda-app-ai-draft', true),
('ramayana-4-1-47', 'en', 'Lamenting this way, his mind struck by grief, he looked at the auspicious, lovely Pampa with its beautiful waters.', 'veda-app-ai-draft', true),
('ramayana-4-1-48', 'en', 'Suddenly surveying the whole forest with its waterfalls and caves, the great one, troubled in mind and struck by sorrow, thought it over and set out with Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-1-49', 'en', 'The two went together toward Rishyamuka, home of Sugriva and his monkeys. The monkeys were frightened when they saw the mighty Raghava and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-2-1', 'en', 'Seeing the two great brothers Rama and Lakshmana, heroes carrying fine weapons, Sugriva became suspicious.', 'veda-app-ai-draft', true),
('ramayana-4-2-2', 'en', 'With an anxious heart, looking in every direction, the chief of monkeys could not stay still in any place.', 'veda-app-ai-draft', true),
('ramayana-4-2-3', 'en', 'He could not settle his mind as he watched the two mighty men, and the heart of the terrified monkey sank.', 'veda-app-ai-draft', true),
('ramayana-4-2-4', 'en', 'Righteous Sugriva, deeply troubled, thought it over with all his followers, weighing what was serious and what was slight.', 'veda-app-ai-draft', true),
('ramayana-4-2-5', 'en', 'Then Sugriva, lord of monkeys, very anxious, looking at Rama and Lakshmana, spoke to his ministers.', 'veda-app-ai-draft', true),
('ramayana-4-2-6', 'en', 'Surely these two have been sent by Vali into this hard forest, coming here disguised, wearing bark clothes.', 'veda-app-ai-draft', true),
('ramayana-4-2-7', 'en', 'Then Sugriva''s ministers, seeing the great archers, went from that mountainside to another high peak.', 'veda-app-ai-draft', true),
('ramayana-4-2-8', 'en', 'The troop leaders quickly came to their chief, the best of monkeys, and stood around him.', 'veda-app-ai-draft', true),
('ramayana-4-2-9', 'en', 'They leapt from hill to hill in a single line, shaking the mountain peaks with their speed.', 'veda-app-ai-draft', true),
('ramayana-4-2-10', 'en', 'All the mighty monkeys, leaping, broke the flowering trees growing in the rough places there.', 'veda-app-ai-draft', true),
('ramayana-4-2-11', 'en', 'The best of monkeys bounded all over that great mountain, frightening deer, wildcats and tigers as they went.', 'veda-app-ai-draft', true),
('ramayana-4-2-12', 'en', 'Then Sugriva''s ministers, settled on the king of mountains, met their chief and stood with folded hands.', 'veda-app-ai-draft', true),
('ramayana-4-2-13', 'en', 'Then Hanuman, skilled in speech, spoke to Sugriva, who was terrified and suspected some wrong from Vali.', 'veda-app-ai-draft', true),
('ramayana-4-2-14', 'en', 'I do not see here that cruel, fierce-looking Vali, because of whom you fled in fear, chief of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-2-15', 'en', 'Vali, the wicked elder brother of evil deeds you fear, gentle one, is not here. I see no danger for you.', 'veda-app-ai-draft', true),
('ramayana-4-2-16', 'en', 'Oh, your monkey nature is plain to see, leaper, for with a restless mind you do not keep yourself steady.', 'veda-app-ai-draft', true),
('ramayana-4-2-17', 'en', 'Endowed with intelligence and understanding, act on everything by reading signs. A king without good sense cannot rule all beings.', 'veda-app-ai-draft', true),
('ramayana-4-2-18', 'en', 'Hearing all of Hanuman''s good words, Sugriva then said even better words to Hanuman.', 'veda-app-ai-draft', true),
('ramayana-4-2-19', 'en', 'Long-armed and wide-eyed, carrying arrows, bows and swords, like sons of the gods, who would not fear these two on seeing them?', 'veda-app-ai-draft', true),
('ramayana-4-2-20', 'en', 'I suspect these two best of men were sent by Vali. Kings have many friends, and trust is not wise here.', 'veda-app-ai-draft', true),
('ramayana-4-2-21', 'en', 'A person must recognise enemies who move about in disguise. Untrustworthy, they strike the trusting at weak points.', 'veda-app-ai-draft', true),
('ramayana-4-2-22', 'en', 'Vali is clever in his affairs, and kings see far and destroy their enemies. They should be known through ordinary men.', 'veda-app-ai-draft', true),
('ramayana-4-2-23', 'en', 'Go to them as an ordinary person, monkey, and find them out by their manner, their looks and their speech.', 'veda-app-ai-draft', true),
('ramayana-4-2-24', 'en', 'Observe their mood, see if they are well-disposed, winning their trust with praise and with gestures again and again.', 'veda-app-ai-draft', true),
('ramayana-4-2-25', 'en', 'Standing facing me, chief of monkeys, ask the two archers why they have entered this forest.', 'veda-app-ai-draft', true),
('ramayana-4-2-26', 'en', 'Find out, monkey, if they are pure-hearted. Any wickedness in them can be known by their words or looks.', 'veda-app-ai-draft', true),
('ramayana-4-2-27', 'en', 'Instructed this way by the monkey king, the son of the Wind made up his mind to go where Rama and Lakshmana were.', 'veda-app-ai-draft', true),
('ramayana-4-2-28', 'en', 'Saying So be it and honouring the words of the frightened but formidable monkey, the noble Hanuman went to where Rama and mighty Lakshmana were.', 'veda-app-ai-draft', true),
('ramayana-4-3-1', 'en', 'Understanding the great Sugriva''s words, Hanuman leapt from Mount Rishyamuka to where the two Raghavas were.', 'veda-app-ai-draft', true),
('ramayana-4-3-2', 'en', 'Reaching there, mighty Hanuman, best of monkeys and true in valour, approached them with gentle words.', 'veda-app-ai-draft', true),
('ramayana-4-3-3', 'en', 'Giving up his own form, the monkey took the form of a mendicant, addressed the two heroes and praised them fittingly.', 'veda-app-ai-draft', true),
('ramayana-4-3-4', 'en', 'Like royal sages and gods, ascetics firm in vows, of noble complexion, how have you come to this place?', 'veda-app-ai-draft', true),
('ramayana-4-3-5', 'en', 'Frightening the herds of deer and other forest creatures, looking all around at the trees growing on the Pampa''s banks,', 'veda-app-ai-draft', true),
('ramayana-4-3-6', 'en', 'Making this lovely river shine, swift and steady, golden in colour, who are you two dressed in bark?', 'veda-app-ai-draft', true),
('ramayana-4-3-7', 'en', 'Heroes with the gaze of lions, with valour beyond a lion''s, holding bows like Indra''s rainbow in your strong arms,', 'veda-app-ai-draft', true),
('ramayana-4-3-8', 'en', 'Glorious and handsome, with the stride of the best bulls, arms like elephants'' trunks, radiant, bulls among men,', 'veda-app-ai-draft', true),
('ramayana-4-3-9', 'en', 'This king of mountains is lit by your glow. Worthy of kingship and like immortals, how have you come to this place?', 'veda-app-ai-draft', true),
('ramayana-4-3-10', 'en', 'Lotus-eyed heroes wearing coils of matted hair, alike to one another, as if come from the world of the gods,', 'veda-app-ai-draft', true),
('ramayana-4-3-11', 'en', 'Like the moon and sun come to earth by chance, broad-chested heroes, men with the forms of gods,', 'veda-app-ai-draft', true),
('ramayana-4-3-12', 'en', 'With lion''s shoulders, great strength, like proud bulls, your long, rounded arms like great iron bars deserve every ornament. Why are they unadorned?', 'veda-app-ai-draft', true),
('ramayana-4-3-13', 'en', 'I think you are both fit to protect this whole earth with its seas and forests, adorned by the Vindhya and Meru mountains.', 'veda-app-ai-draft', true),
('ramayana-4-3-14', 'en', 'And these two bows, bright, smooth and beautifully painted, shine like Indra''s thunderbolts decorated with gold.', 'veda-app-ai-draft', true),
('ramayana-4-3-15', 'en', 'And the lovely quivers are full of sharp arrows, deadly and terrible, like blazing serpents.', 'veda-app-ai-draft', true),
('ramayana-4-3-16', 'en', 'These two long, broad swords adorned with refined gold shine like snakes that have shed their skin.', 'veda-app-ai-draft', true),
('ramayana-4-3-17', 'en', 'Why do you not answer me when I speak to you like this?', 'veda-app-ai-draft', true),
('ramayana-4-3-18', 'en', 'There is a righteous chief of a monkey troop named Sugriva, a hero wronged by his brother, who wanders the world in sorrow.', 'veda-app-ai-draft', true),
('ramayana-4-3-19', 'en', 'I have come, sent by the great Sugriva, king of the chief monkeys. I am a monkey named Hanuman.', 'veda-app-ai-draft', true),
('ramayana-4-3-20', 'en', 'Righteous Sugriva wishes friendship with you both. Know me as his minister, a monkey, son of the Wind,', 'veda-app-ai-draft', true),
('ramayana-4-3-21', 'en', 'disguised as a mendicant to please Sugriva, come here from Rishyamuka, able to go where I wish and take any form.', 'veda-app-ai-draft', true),
('ramayana-4-3-22', 'en', 'Having said this to the heroes Rama and Lakshmana, who understood speech, Hanuman, skilled in words, said nothing more.', 'veda-app-ai-draft', true),
('ramayana-4-3-23', 'en', 'Hearing his words, glorious Rama, his face bright with joy, said to his brother Lakshmana standing beside him:', 'veda-app-ai-draft', true),
('ramayana-4-3-24', 'en', 'This is the minister of the great monkey king Sugriva, and he has come to me just as I was longing for Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-3-25', 'en', 'Speak to him, Lakshmana, to this monkey minister of Sugriva, skilled in speech and subduer of enemies, with sweet and friendly words.', 'veda-app-ai-draft', true),
('ramayana-4-4-1', 'en', 'Hearing those sweet words, Hanuman was delighted, thinking that Rama had a need, and his mind turned to Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-4-2', 'en', 'The great Sugriva''s return to kingship is near, since this man has come with a need, and a task has come to hand.', 'veda-app-ai-draft', true),
('ramayana-4-4-3', 'en', 'Then Hanuman, best of monkeys, overjoyed and skilled in speech, replied to Rama.', 'veda-app-ai-draft', true),
('ramayana-4-4-4', 'en', 'Why have you come with your younger brother to this fearful, hard forest adorned with the woods of the Pampa and full of beasts of prey?', 'veda-app-ai-draft', true),
('ramayana-4-4-5', 'en', 'Hearing his words, Lakshmana, urged by Rama, told him about the great Rama, son of Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-4-4-6', 'en', 'There is a king named Dasharatha, radiant and devoted to dharma. This is his eldest son, known among people as Rama.', 'veda-app-ai-draft', true),
('ramayana-4-4-7', 'en', 'He is a refuge for all beings, one who fulfils his father''s command, a hero, the most virtuous of Dasharatha''s sons.', 'veda-app-ai-draft', true),
('ramayana-4-4-8', 'en', 'Deprived of the kingdom, he came here with me to live in the forest, followed by his wife Sita, self-controlled and glorious, like the sun with its light at the end of the day.', 'veda-app-ai-draft', true),
('ramayana-4-4-9', 'en', 'I am his younger brother, drawn into his service by his virtues, a grateful and wise man. My name is Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-4-10', 'en', 'He deserves happiness and honour, his heart set on the good of all beings, yet he is without royal power and lives in the forest.', 'veda-app-ai-draft', true),
('ramayana-4-4-11', 'en', 'A demon who changes form at will carried off his wife when she was alone, and we do not know which demon took her.', 'veda-app-ai-draft', true),
('ramayana-4-4-12', 'en', 'Danu, a son of Shri, who had become a demon through a curse, told us that Sugriva, lord of monkeys, is capable.', 'veda-app-ai-draft', true),
('ramayana-4-4-13', 'en', 'He said that mighty one will know who stole your wife. Saying this, Danu went happily to heaven, shining.', 'veda-app-ai-draft', true),
('ramayana-4-4-14', 'en', 'I have told you all this truly as you asked. Rama and I have come to Sugriva for refuge.', 'veda-app-ai-draft', true),
('ramayana-4-4-15', 'en', 'He who once gave wealth and won the highest fame, who was a protector of the world, now wants Sugriva as his protector.', 'veda-app-ai-draft', true),
('ramayana-4-4-16', 'en', 'Sugriva with his troop leaders should show kindness to Rama, overwhelmed and stricken with grief, who has come for refuge.', 'veda-app-ai-draft', true),
('ramayana-4-4-17', 'en', 'As Lakshmana spoke this way, piteously and shedding tears, Hanuman, skilled in speech, replied.', 'veda-app-ai-draft', true),
('ramayana-4-4-18', 'en', 'The monkey king must meet such men, wise, who have conquered anger and the senses. By good fortune you have come into his sight.', 'veda-app-ai-draft', true),
('ramayana-4-4-19', 'en', 'For he has lost his kingdom, made an enemy of Vali, had his wife taken, and lives fearful in the forest, badly wronged by his brother.', 'veda-app-ai-draft', true),
('ramayana-4-4-20', 'en', 'Sugriva, son of the sun, will help you both, along with us, in the search for Sita.', 'veda-app-ai-draft', true),
('ramayana-4-4-21', 'en', 'Saying this gently in a sweet voice, Hanuman said to Raghava: Let us go to Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-4-22', 'en', 'As Hanuman spoke this way, righteous Lakshmana honoured him properly and said this to Raghava:', 'veda-app-ai-draft', true),
('ramayana-4-4-23', 'en', 'This monkey, son of the Wind, speaks joyfully as if he too has a need. You have achieved your purpose, Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-4-24', 'en', 'His face is bright and he clearly speaks with joy. The hero Hanuman, son of the Wind, will not speak falsely.', 'veda-app-ai-draft', true),
('ramayana-4-4-25', 'en', 'Then wise Hanuman, son of the Wind, took the two Raghava heroes and went to the monkey king.', 'veda-app-ai-draft', true),
('ramayana-4-4-26', 'en', 'That famous hero among monkeys, son of the Wind, mighty in stride and good-hearted, delighted as if his task were done, went to the great mountain with Rama and Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-5-1', 'en', 'Hanuman went from Rishyamuka to the Malaya hill and told the monkey king about the two Raghava heroes.', 'veda-app-ai-draft', true),
('ramayana-4-5-2', 'en', 'This is Rama, very wise, firm in valour, come with his brother Lakshmana. This is Rama, true in courage.', 'veda-app-ai-draft', true),
('ramayana-4-5-3', 'en', 'Born in the line of the Ikshvakus, Rama is Dasharatha''s son, praised for dharma, and keeps his father''s command.', 'veda-app-ai-draft', true),
('ramayana-4-5-4', 'en', 'While this disciplined great soul lived in the forest, a demon carried off his wife, and he has come to you for refuge.', 'veda-app-ai-draft', true),
('ramayana-4-5-5', 'en', 'His father honoured the fire with Rajasuya and Ashvamedha sacrifices and gave away cows by the hundreds of thousands as gifts.', 'veda-app-ai-draft', true),
('ramayana-4-5-6', 'en', 'He protected the earth by austerity and truthful speech. For the sake of a woman, his son Rama has come to you for refuge.', 'veda-app-ai-draft', true),
('ramayana-4-5-7', 'en', 'The brothers Rama and Lakshmana want friendship with you. Receive and honour them, for both are most worthy of honour.', 'veda-app-ai-draft', true),
('ramayana-4-5-8', 'en', 'Hearing Hanuman''s words, Sugriva was glad at heart and gave up his terrible fear of Raghava, his anxiety gone.', 'veda-app-ai-draft', true),
('ramayana-4-5-9', 'en', 'Sugriva, lord of monkeys, took a human form and, looking very handsome, spoke to Raghava with affection.', 'veda-app-ai-draft', true),
('ramayana-4-5-10', 'en', 'You are trained in dharma, valiant and kind to all. The son of the Wind has told me your virtues truly.', 'veda-app-ai-draft', true),
('ramayana-4-5-11', 'en', 'So it is an honour and the highest gain for me, lord, that you wish friendship with me, a monkey.', 'veda-app-ai-draft', true),
('ramayana-4-5-12', 'en', 'If friendship pleases you, here is my hand held out. Take my hand in yours and let a firm bond be made.', 'veda-app-ai-draft', true),
('ramayana-4-5-13', 'en', 'Hearing Sugriva''s well-spoken words, Rama, delighted, pressed his hand and, holding to heartfelt friendship, embraced him warmly.', 'veda-app-ai-draft', true),
('ramayana-4-5-14', 'en', 'Then Hanuman, subduer of enemies, dropped his mendicant form and in his own form kindled a fire with two sticks.', 'veda-app-ai-draft', true),
('ramayana-4-5-15', 'en', 'Honouring the blazing fire with flowers, he set it between the two, well pleased and fully attentive.', 'veda-app-ai-draft', true),
('ramayana-4-5-16', 'en', 'Then Sugriva and Raghava walked around the blazing fire and became friends.', 'veda-app-ai-draft', true),
('ramayana-4-5-17', 'en', 'Then the monkey and Raghava, both delighted, gazed at each other and could not look enough.', 'veda-app-ai-draft', true),
('ramayana-4-5-18', 'en', 'Then radiant Sugriva, with full attention, spoke to Rama, son of Dasharatha, who knew all things.', 'veda-app-ai-draft', true),
('ramayana-4-6-1', 'en', 'Rama, my minister Hanuman, best of counsellors, tells me why you came to this lonely forest:', 'veda-app-ai-draft', true),
('ramayana-4-6-2', 'en', 'While you lived in the forest with your brother Lakshmana, a demon carried off your wife Maithili, daughter of Janaka,', 'veda-app-ai-draft', true),
('ramayana-4-6-3', 'en', 'weeping and separated from you and wise Lakshmana, by that demon who sought his chance and killed the vulture Jatayu.', 'veda-app-ai-draft', true),
('ramayana-4-6-4', 'en', 'You will soon be free of the sorrow of separation from your wife. I will bring her back like the lost Vedic scripture.', 'veda-app-ai-draft', true),
('ramayana-4-6-5', 'en', 'Whether she is in the underworld or in the sky, I will bring your wife and give her back to you, subduer of enemies.', 'veda-app-ai-draft', true),
('ramayana-4-6-6', 'en', 'Know that my words are true, Raghava. Give up your grief, mighty-armed one. I will bring back your beloved.', 'veda-app-ai-draft', true),
('ramayana-4-6-7', 'en', 'I know by inference that it was Maithili, no doubt. I saw her being carried off by a demon of cruel deeds,', 'veda-app-ai-draft', true),
('ramayana-4-6-8', 'en', 'crying out Rama, Rama! and Lakshmana! in a broken voice, struggling in Ravana''s lap like the wife of a serpent king.', 'veda-app-ai-draft', true),
('ramayana-4-6-9', 'en', 'Seeing me standing with four others on the mountain slope, she dropped her upper cloth and beautiful ornaments.', 'veda-app-ai-draft', true),
('ramayana-4-6-10', 'en', 'We picked them up and kept them, Raghava. I will bring them, and you should recognise them.', 'veda-app-ai-draft', true),
('ramayana-4-6-11', 'en', 'Then Rama said to Sugriva, who spoke so kindly: Bring them quickly, friend. Why do you delay?', 'veda-app-ai-draft', true),
('ramayana-4-6-12', 'en', 'Told this, Sugriva quickly went into a deep cave in the mountain, wanting to please Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-6-13', 'en', 'Taking the upper cloth and the beautiful ornaments, the monkey showed them to Rama, saying: Look at this.', 'veda-app-ai-draft', true),
('ramayana-4-6-14', 'en', 'Taking the cloth and the lovely ornaments, Rama was choked with tears, like the moon veiled in mist.', 'veda-app-ai-draft', true),
('ramayana-4-6-15', 'en', 'Stained with tears from his love for Sita, he cried Ah, beloved! and, losing his composure, fell to the ground.', 'veda-app-ai-draft', true),
('ramayana-4-6-16', 'en', 'Pressing that fine ornament to his heart again and again, he sighed deeply like an angry snake in its hole.', 'veda-app-ai-draft', true),
('ramayana-4-6-17', 'en', 'With tears flowing without stop, Rama looked at Lakshmana beside him and began to lament miserably.', 'veda-app-ai-draft', true),
('ramayana-4-6-18', 'en', 'See, Lakshmana, this upper cloth and these ornaments from her body that Vaidehi dropped to the ground while being carried away.', 'veda-app-ai-draft', true),
('ramayana-4-6-19', 'en', 'Surely Sita dropped these ornaments on grassy ground while being carried off, for they look that way.', 'veda-app-ai-draft', true),
('ramayana-4-6-20', 'en', 'Tell me, Sugriva, toward what place did you see my beloved, dear as life, carried by that fierce-looking demon?', 'veda-app-ai-draft', true),
('ramayana-4-6-21', 'en', 'Where does that demon live who has caused me such great disaster? Because of him I will destroy all the demons.', 'veda-app-ai-draft', true),
('ramayana-4-6-22', 'en', 'By taking Maithili and angering me so greatly, he has opened the door of death to end his own life.', 'veda-app-ai-draft', true),
('ramayana-4-6-23', 'en', 'Tell me, lord of monkeys, who is that enemy, the night-roamer who tore my dearest from the forest? Today I will lead him to Yama.', 'veda-app-ai-draft', true),
('ramayana-4-7-1', 'en', 'Spoken to this way by the distressed Rama, the monkey Sugriva, with folded hands and voice choked with tears, replied.', 'veda-app-ai-draft', true),
('ramayana-4-7-2', 'en', 'I do not know at all where that wicked demon lives, nor his power, his valour, or the family of that low-born one.', 'veda-app-ai-draft', true),
('ramayana-4-7-3', 'en', 'But I promise you truly, give up grief, subduer of enemies. I will strive so that you regain Maithili.', 'veda-app-ai-draft', true),
('ramayana-4-7-4', 'en', 'Killing Ravana with his followers and pleasing you with your own valour, I will soon act so that you will be happy.', 'veda-app-ai-draft', true),
('ramayana-4-7-5', 'en', 'Enough of this despair. Remember the courage within you. Such weakness of mind is not fitting for one like you.', 'veda-app-ai-draft', true),
('ramayana-4-7-6', 'en', 'I too have suffered a great disaster through the taking of my wife, yet I do not grieve like this or give up my courage.', 'veda-app-ai-draft', true),
('ramayana-4-7-7', 'en', 'I do not keep grieving for her though I am only an ordinary monkey. How much more should you, a great, disciplined and steady soul, hold firm?', 'veda-app-ai-draft', true),
('ramayana-4-7-8', 'en', 'You should hold back the tears that have come, by your courage. Do not abandon the steadiness that marks the strong.', 'veda-app-ai-draft', true),
('ramayana-4-7-9', 'en', 'In disaster, in money troubles, in fear, or when life is in danger, a steady person who reflects with his own mind does not sink down.', 'veda-app-ai-draft', true),
('ramayana-4-7-10', 'en', 'But a foolish person who always gives in to despair sinks helplessly in grief, like an overloaded boat in water.', 'veda-app-ai-draft', true),
('ramayana-4-7-11', 'en', 'Here I fold my hands and appeal to you in friendship. Rely on your manliness and do not give grief a chance.', 'veda-app-ai-draft', true),
('ramayana-4-7-12', 'en', 'Those who give in to grief find no happiness, and their strength wastes away. You should not grieve.', 'veda-app-ai-draft', true),
('ramayana-4-7-13', 'en', 'I speak for your good as a friend, not to lecture you. Honour my friendship and do not grieve.', 'veda-app-ai-draft', true),
('ramayana-4-7-14', 'en', 'Comforted sweetly by Sugriva, Raghava wiped his tear-soaked face with the edge of his garment.', 'veda-app-ai-draft', true),
('ramayana-4-7-15', 'en', 'Restored to himself by Sugriva''s words, lord Rama embraced Sugriva and said:', 'veda-app-ai-draft', true),
('ramayana-4-7-16', 'en', 'You have done what a loving and well-meaning friend should do, Sugriva, fittingly and rightly.', 'veda-app-ai-draft', true),
('ramayana-4-7-17', 'en', 'I am myself again, friend, consoled by you. Such a friend is hard to find, especially at a time like this.', 'veda-app-ai-draft', true),
('ramayana-4-7-18', 'en', 'But you must make an effort to search for Maithili and for the fierce, wicked demon Ravana.', 'veda-app-ai-draft', true),
('ramayana-4-7-19', 'en', 'Tell me openly what I must do for you. Everything will come about for you like crops in good soil in the rains.', 'veda-app-ai-draft', true),
('ramayana-4-7-20', 'en', 'Take what I have said out of self-respect as the truth, tiger among monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-7-21', 'en', 'I have never spoken a lie and never will. I promise you this and swear it by truth itself.', 'veda-app-ai-draft', true),
('ramayana-4-7-22', 'en', 'Then Sugriva and his monkey ministers were delighted, hearing Raghava''s words and especially his promise.', 'veda-app-ai-draft', true),
('ramayana-4-7-23', 'en', 'Hearing the words of that noble bull among men, the wise monkey leader felt in his heart that his own task was as good as done.', 'veda-app-ai-draft', true),
('ramayana-4-8-1', 'en', 'Pleased by those words, the monkey Sugriva said this to Rama, Lakshmana''s elder brother.', 'veda-app-ai-draft', true),
('ramayana-4-8-2', 'en', 'Without doubt I am favoured by the gods in every way, since you, full of virtues, are my friend.', 'veda-app-ai-draft', true),
('ramayana-4-8-3', 'en', 'With you as my ally, sinless Rama, one could win even the kingdom of the gods, let alone my own kingdom.', 'veda-app-ai-draft', true),
('ramayana-4-8-4', 'en', 'I deserve honour from my kin and friends, Raghava, for I have gained a friend of Raghu''s line with fire as witness.', 'veda-app-ai-draft', true),
('ramayana-4-8-5', 'en', 'You will learn in time that I too am a worthy friend to you. I cannot speak of my own virtues myself.', 'veda-app-ai-draft', true),
('ramayana-4-8-6', 'en', 'The love of great souls like you, who have mastered themselves, stays unshaken, like the courage of the self-controlled.', 'veda-app-ai-draft', true),
('ramayana-4-8-7', 'en', 'Good people regard silver, gold, clothes or jewels as undivided between good friends.', 'veda-app-ai-draft', true),
('ramayana-4-8-8', 'en', 'Rich or poor, sad or happy, faultless or flawed, a friend is the highest refuge.', 'veda-app-ai-draft', true),
('ramayana-4-8-9', 'en', 'Seeing such love, people give up wealth, comfort, and even their bodies for a friend''s sake.', 'veda-app-ai-draft', true),
('ramayana-4-8-10', 'en', 'Wise Rama, glorious like Indra, said to kind-speaking Sugriva in front of Lakshmana: That is so.', 'veda-app-ai-draft', true),
('ramayana-4-8-11', 'en', 'Then, seeing Rama and mighty Lakshmana standing, Sugriva cast his restless eyes around the forest.', 'veda-app-ai-draft', true),
('ramayana-4-8-12', 'en', 'The lord of monkeys then saw a sala tree nearby, full of flowers and some leaves, and graced by bees.', 'veda-app-ai-draft', true),
('ramayana-4-8-13', 'en', 'Breaking off one leafy, flowering branch of the sala, Sugriva spread it out and sat down with Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-8-14', 'en', 'Seeing them seated, Hanuman also tore off a sala branch and seated the modest Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-8-15', 'en', 'Then Sugriva, delighted, spoke to Rama gently and sweetly with affection, his words faltering with joy.', 'veda-app-ai-draft', true),
('ramayana-4-8-16', 'en', 'Wronged by my brother, I wander here tormented by fear on Rishyamuka, best of mountains, deprived of my wife and deeply unhappy.', 'veda-app-ai-draft', true),
('ramayana-4-8-17', 'en', 'Frightened and sunk in fear, I live with a bewildered mind, wronged by my brother Vali, who is my enemy, Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-8-18', 'en', 'You who free all the world from fear, please show kindness to me too, helpless and afraid of Vali.', 'veda-app-ai-draft', true),
('ramayana-4-8-19', 'en', 'Hearing this, radiant Rama, knower and lover of dharma, replied to Sugriva as if smiling:', 'veda-app-ai-draft', true),
('ramayana-4-8-20', 'en', 'A friend is known by the help he gives, an enemy by the harm. This very day I will kill the one who stole your wife.', 'veda-app-ai-draft', true),
('ramayana-4-8-21', 'en', 'These swift, sharp arrows of mine, born in the reed forest of Kartikeya and adorned with gold,', 'veda-app-ai-draft', true),
('ramayana-4-8-22', 'en', 'feathered with heron plumes, like Indra''s thunderbolt, well-jointed and sharp-tipped, are like angry serpents.', 'veda-app-ai-draft', true),
('ramayana-4-8-23', 'en', 'See your enemy Vali, a brother only in name, who has done wrong, struck down by my arrows like a shattered mountain.', 'veda-app-ai-draft', true),
('ramayana-4-8-24', 'en', 'Hearing Raghava''s words, Sugriva, leader of the host, was overjoyed and said: Well said, well said!', 'veda-app-ai-draft', true),
('ramayana-4-8-25', 'en', 'I am overcome with grief, Rama. You are the refuge of the grieving. Taking you as a friend, I pour out my sorrow to you.', 'veda-app-ai-draft', true),
('ramayana-4-8-26', 'en', 'By giving your hand you have become my friend with fire as witness, dearer than life. I swear this by truth.', 'veda-app-ai-draft', true),
('ramayana-4-8-27', 'en', 'Taking you as a friend, I speak openly of the sorrow inside me that always burns my mind.', 'veda-app-ai-draft', true),
('ramayana-4-8-28', 'en', 'Having said this much, his eyes clouded with tears, he could not speak aloud in his tear-choked voice.', 'veda-app-ai-draft', true),
('ramayana-4-8-29', 'en', 'Sugriva steadily held back the sudden rush of tears, like a river''s flood, in Rama''s presence.', 'veda-app-ai-draft', true),
('ramayana-4-8-30', 'en', 'Holding back the tears and wiping his fine eyes, the radiant one sighed and spoke again to Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-8-31', 'en', 'Long ago, Rama, Vali threw me out of my own kingdom. The stronger one drove me away after speaking harsh words.', 'veda-app-ai-draft', true),
('ramayana-4-8-32', 'en', 'He took my wife, who is dearer than life, and my friends were put in chains.', 'veda-app-ai-draft', true),
('ramayana-4-8-33', 'en', 'That wicked one strives to destroy me, Raghava. Many monkeys he sent for that purpose have been killed by me.', 'veda-app-ai-draft', true),
('ramayana-4-8-34', 'en', 'Because of this fear, Raghava, when I saw you I did not come near. I was afraid, and everyone is afraid in danger.', 'veda-app-ai-draft', true),
('ramayana-4-8-35', 'en', 'My only allies are these, led by Hanuman. Because of them I hold on to life, though in great hardship.', 'veda-app-ai-draft', true),
('ramayana-4-8-36', 'en', 'These loving monkeys guard me on all sides. They go with me where I must go and always stay when I stay.', 'veda-app-ai-draft', true),
('ramayana-4-8-37', 'en', 'This is my story in brief, Rama. Why tell you at length? My enemy is my elder brother Vali, famous for his strength.', 'veda-app-ai-draft', true),
('ramayana-4-8-38', 'en', 'With his destruction, my sorrow would end at once. My happiness and my very life depend on his destruction.', 'veda-app-ai-draft', true),
('ramayana-4-8-39', 'en', 'This, Rama, is the end of my grief that I, grieving, have told you. Sad or not, a friend is always a friend''s refuge.', 'veda-app-ai-draft', true),
('ramayana-4-8-40', 'en', 'Hearing this, Rama said to Sugriva: I wish to hear truly why the enmity arose.', 'veda-app-ai-draft', true),
('ramayana-4-8-41', 'en', 'Once I hear the cause of your enmity, monkey, I will decide the next step after weighing strengths and weaknesses.', 'veda-app-ai-draft', true),
('ramayana-4-8-42', 'en', 'My anger grows strong on hearing how you were dishonoured, shaking my heart like a flood in the rainy season.', 'veda-app-ai-draft', true),
('ramayana-4-8-43', 'en', 'Tell me gladly and openly, while my bow is strung. Once my arrow is loosed, your enemy is gone.', 'veda-app-ai-draft', true),
('ramayana-4-8-44', 'en', 'Spoken to this way by the great Rama, Sugriva and his four monkeys were overjoyed.', 'veda-app-ai-draft', true),
('ramayana-4-8-45', 'en', 'Then Sugriva, his face bright with joy, began to tell Lakshmana''s elder brother the true cause of the enmity.', 'veda-app-ai-draft', true),
('ramayana-4-9-1', 'en', 'My elder brother is named Vali, a destroyer of enemies. Our father always held him in high esteem, and so did I in the past.', 'veda-app-ai-draft', true),
('ramayana-4-9-2', 'en', 'When our father died, the ministers made him king of the monkeys, saying he is the eldest, and he was highly regarded.', 'veda-app-ai-draft', true),
('ramayana-4-9-3', 'en', 'While he ruled the great kingdom of our fathers and forefathers, I always stood humbly by him like a servant.', 'veda-app-ai-draft', true),
('ramayana-4-9-4', 'en', 'Mayavi, the radiant elder son of Dundubhi, had a great and famous feud with him long ago over a woman.', 'veda-app-ai-draft', true),
('ramayana-4-9-5', 'en', 'At night when people were asleep, he came to the gate of Kishkindha, roaring in rage and challenging Vali to fight.', 'veda-app-ai-draft', true),
('ramayana-4-9-6', 'en', 'My brother, asleep, heard that terrible roar, and Vali, unable to bear it, rushed out swiftly.', 'veda-app-ai-draft', true),
('ramayana-4-9-7', 'en', 'He went out in anger to kill that great asura, though the women and I, bowing, tried to stop him.', 'veda-app-ai-draft', true),
('ramayana-4-9-8', 'en', 'Brushing us all aside, the mighty one went out, and I too went out with Vali out of affection.', 'veda-app-ai-draft', true),
('ramayana-4-9-9', 'en', 'Seeing my brother and me standing some distance away, the asura was terrified and ran away fast.', 'veda-app-ai-draft', true),
('ramayana-4-9-10', 'en', 'As he ran in fear, we followed faster, and the path was lit by the rising moon.', 'veda-app-ai-draft', true),
('ramayana-4-9-11', 'en', 'The asura rushed into a great hole in the earth, hard to reach and covered with grass, and we stopped there.', 'veda-app-ai-draft', true),
('ramayana-4-9-12', 'en', 'Seeing the enemy enter the hole, Vali was seized by anger and, agitated, said to me:', 'veda-app-ai-draft', true),
('ramayana-4-9-13', 'en', 'Stay here alert at the mouth of the cave, Sugriva, while I go in and kill the enemy in battle.', 'veda-app-ai-draft', true),
('ramayana-4-9-14', 'en', 'Hearing this, I begged him, scorcher of foes, but he made me swear by his feet and entered the cave.', 'veda-app-ai-draft', true),
('ramayana-4-9-15', 'en', 'After he entered the cave more than a year passed, and all that time I stayed at the entrance.', 'veda-app-ai-draft', true),
('ramayana-4-9-16', 'en', 'Thinking he was lost, I became alarmed out of love. I could not see my brother, and my mind feared the worst.', 'veda-app-ai-draft', true),
('ramayana-4-9-17', 'en', 'After a long time, I saw foaming red blood flowing out of that cave and was deeply grieved.', 'veda-app-ai-draft', true),
('ramayana-4-9-18', 'en', 'The sound of roaring asuras reached my ears, and the cry of my elder brother as if overcome in battle.', 'veda-app-ai-draft', true),
('ramayana-4-9-19', 'en', 'Concluding from these signs that my brother had been killed, I closed the cave mouth with a rock as big as a hill and, grieving, made water offerings and came back to Kishkindha, friend.', 'veda-app-ai-draft', true),
('ramayana-4-9-20', 'en', 'Though I tried to hide the truth, the ministers learned of it. They gathered together and crowned me.', 'veda-app-ai-draft', true),
('ramayana-4-9-21', 'en', 'While I ruled the kingdom justly, Raghava, Vali came back after killing that great asura.', 'veda-app-ai-draft', true),
('ramayana-4-9-22', 'en', 'Seeing me crowned, his eyes red with anger, he put my ministers in chains and spoke harsh words.', 'veda-app-ai-draft', true),
('ramayana-4-9-23', 'en', 'Though I could have restrained that wicked one, Raghava, my mind would not do it, held back by respect for my brother.', 'veda-app-ai-draft', true),
('ramayana-4-9-24', 'en', 'Honouring that great one, I greeted him properly, but he did not bless me with a pleased heart.', 'veda-app-ai-draft', true),
('ramayana-4-10-1', 'en', 'Then, wanting to please him, I tried to calm my brother, who came to me furious and agitated.', 'veda-app-ai-draft', true),
('ramayana-4-10-2', 'en', 'By good fortune you have come back safe and killed the enemy. You alone are my protector, I who was helpless, you the joy of the helpless.', 'veda-app-ai-draft', true),
('ramayana-4-10-3', 'en', 'Accept this umbrella with many ribs, like the rising full moon, with its yak-tail fan, which I hold out to you.', 'veda-app-ai-draft', true),
('ramayana-4-10-4', 'en', 'You alone are king, worthy of honour, and I am as before. I return this kingdom to you as a trust.', 'veda-app-ai-draft', true),
('ramayana-4-10-5', 'en', 'Do not be angry with me, gentle one, destroyer of enemies. I beg you with my head bowed, king, with folded hands.', 'veda-app-ai-draft', true),
('ramayana-4-10-6', 'en', 'I was forced into kingship by the ministers and townspeople who gathered, so the empty throne would not invite conquest.', 'veda-app-ai-draft', true),
('ramayana-4-10-7', 'en', 'But as I spoke so warmly, that monkey scolded me, saying Shame on you! and said many such things.', 'veda-app-ai-draft', true),
('ramayana-4-10-8', 'en', 'Gathering the subjects and the respected ministers, he spoke to me most insultingly in the midst of friends.', 'veda-app-ai-draft', true),
('ramayana-4-10-9', 'en', 'You know how that great asura Mayavi, cruel and wicked, challenged me at night, longing for battle.', 'veda-app-ai-draft', true),
('ramayana-4-10-10', 'en', 'Hearing his roar, I left the palace, and this cruel brother of mine quickly followed me.', 'veda-app-ai-draft', true),
('ramayana-4-10-11', 'en', 'As soon as the mighty one saw me at night with a companion, he fled in terror. Seeing us, he ran, and chased hard, he entered a great cave.', 'veda-app-ai-draft', true),
('ramayana-4-10-12', 'en', 'Knowing he had entered that dreadful great cave, I said to this cruel-looking brother of mine:', 'veda-app-ai-draft', true),
('ramayana-4-10-13', 'en', 'I cannot go back to the city without killing him. Wait at the mouth of the cave until I kill him.', 'veda-app-ai-draft', true),
('ramayana-4-10-14', 'en', 'Thinking he was standing guard, I went into that hard place. A year passed as I searched for him.', 'veda-app-ai-draft', true),
('ramayana-4-10-15', 'en', 'I found that fearsome enemy through persistence and killed that asura there along with his kin.', 'veda-app-ai-draft', true),
('ramayana-4-10-16', 'en', 'The cave was filled with the stream of blood pouring from his mouth as he roared on the ground, and it became hard to pass.', 'veda-app-ai-draft', true),
('ramayana-4-10-17', 'en', 'After killing that bold enemy, Dundubhi''s son, as I came out I saw the mouth of the cave was closed.', 'veda-app-ai-draft', true),
('ramayana-4-10-18', 'en', 'I called out Sugriva! again and again, and when there was no reply I was deeply hurt.', 'veda-app-ai-draft', true),
('ramayana-4-10-19', 'en', 'I broke it open with many kicks, and so I got out and came back.', 'veda-app-ai-draft', true),
('ramayana-4-10-20', 'en', 'There I was shut in by this cruel Sugriva, who wanted the kingdom for himself and forgot a brother''s love.', 'veda-app-ai-draft', true),
('ramayana-4-10-21', 'en', 'Having said this, the monkey Vali, without fear, drove me out with only a single garment.', 'veda-app-ai-draft', true),
('ramayana-4-10-22', 'en', 'Cast out by him and with my wife taken, Raghava, I wandered the whole earth with its forests and seas out of fear of him.', 'veda-app-ai-draft', true),
('ramayana-4-10-23', 'en', 'Grieving over the loss of my wife, I entered Rishyamuka, best of mountains, which Vali cannot approach for a certain reason.', 'veda-app-ai-draft', true),
('ramayana-4-10-24', 'en', 'I have told you the whole long story of the feud. See the disaster I, though innocent, have met, Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-10-25', 'en', 'Hero who frees all the world from fear, please show me kindness by subduing Vali, for I am stricken with fear of him.', 'veda-app-ai-draft', true),
('ramayana-4-10-26', 'en', 'Spoken to this way, the radiant knower of dharma began to speak words full of dharma to Sugriva, as if smiling.', 'veda-app-ai-draft', true),
('ramayana-4-10-27', 'en', 'These sharp, unfailing arrows of mine, bright as the sun, will fall in fury on that wrongdoer Vali.', 'veda-app-ai-draft', true),
('ramayana-4-10-28', 'en', 'Only until I see him, the one who took your wife, will that wicked Vali, corrupter of good conduct, stay alive.', 'veda-app-ai-draft', true),
('ramayana-4-10-29', 'en', 'Judging by my own pain, I see you sunk in an ocean of grief. I will bring you across, and you will gain all you desire.', 'veda-app-ai-draft', true),
('ramayana-4-11-1', 'en', 'Hearing Rama''s words, which increased his joy and courage, Sugriva honoured and praised Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-11-2', 'en', 'No doubt you, in anger, could burn the worlds with your blazing sharp arrows that pierce the vitals, like the sun at the end of an age.', 'veda-app-ai-draft', true),
('ramayana-4-11-3', 'en', 'Hear with full attention about Vali''s strength, his might and his endurance, then decide what to do next.', 'veda-app-ai-draft', true),
('ramayana-4-11-4', 'en', 'Before sunrise, Vali strides from the western sea to the eastern and from the southern to the northern, without tiring.', 'veda-app-ai-draft', true),
('ramayana-4-11-5', 'en', 'The mighty one climbs the tops of mountains, hurls even great peaks into the air and catches them.', 'veda-app-ai-draft', true),
('ramayana-4-11-6', 'en', 'Many strong trees of every kind in the forests have been broken by Vali to show off his strength.', 'veda-app-ai-draft', true),
('ramayana-4-11-7', 'en', 'There was a buffalo named Dundubhi, bright as a peak of Kailasa, who had the strength of a thousand elephants.', 'veda-app-ai-draft', true),
('ramayana-4-11-8', 'en', 'Swollen with pride in his strength and deluded by a boon, that huge wicked one went to the ocean, lord of rivers.', 'veda-app-ai-draft', true),
('ramayana-4-11-9', 'en', 'Passing over the wave-filled sea, that store of jewels, he said to the great ocean: Give me battle.', 'veda-app-ai-draft', true),
('ramayana-4-11-10', 'en', 'Then the righteous, mighty ocean rose up and spoke to the asura, who was driven by fate, O king.', 'veda-app-ai-draft', true),
('ramayana-4-11-11', 'en', 'I cannot give you battle, skilled fighter. Listen, I will tell you who will give you a fight.', 'veda-app-ai-draft', true),
('ramayana-4-11-12', 'en', 'In a great forest is the king of mountains, the best refuge of ascetics, Shiva''s father-in-law, famous by the name Himavan.', 'veda-app-ai-draft', true),
('ramayana-4-11-13', 'en', 'With caves and springs, many grottoes and waterfalls, he can give you matchless pleasure in battle.', 'veda-app-ai-draft', true),
('ramayana-4-11-14', 'en', 'Knowing the ocean was afraid, the great asura came to the Himalayan forest like an arrow loosed from a bow.', 'veda-app-ai-draft', true),
('ramayana-4-11-15', 'en', 'Then Dundubhi hurled down many white rocks of that mountain, huge as great elephants, and roared.', 'veda-app-ai-draft', true),
('ramayana-4-11-16', 'en', 'Then Himavan, shaped like a white cloud, gentle and pleasant in form, spoke standing on his own peak.', 'veda-app-ai-draft', true),
('ramayana-4-11-17', 'en', 'You should not trouble me, Dundubhi, lover of dharma. I am not skilled in war, I am a refuge for ascetics.', 'veda-app-ai-draft', true),
('ramayana-4-11-18', 'en', 'Hearing these words of the wise king of mountains, Dundubhi spoke, his eyes red with anger.', 'veda-app-ai-draft', true),
('ramayana-4-11-19', 'en', 'If you cannot fight, or are unwilling out of fear of me, tell me who would give me battle today, eager as I am to fight.', 'veda-app-ai-draft', true),
('ramayana-4-11-20', 'en', 'Hearing this, righteous Himavan, skilled in speech, spoke in anger to that great asura words he had never said before.', 'veda-app-ai-draft', true),
('ramayana-4-11-21', 'en', 'There is a monkey named Vali, very wise and equal to Indra in valour, glorious, who lives in matchless Kishkindha.', 'veda-app-ai-draft', true),
('ramayana-4-11-22', 'en', 'That wise one, skilled in war, can give you a great single combat, as Indra did to Namuchi.', 'veda-app-ai-draft', true),
('ramayana-4-11-23', 'en', 'Go to him quickly if you want a fight here, for he is always unbeatable and brave in battle.', 'veda-app-ai-draft', true),
('ramayana-4-11-24', 'en', 'Hearing Himavan''s words, Dundubhi, filled with anger, went to Vali''s city of Kishkindha.', 'veda-app-ai-draft', true),
('ramayana-4-11-25', 'en', 'He took the form of a buffalo with sharp horns, terrifying, like a great rain cloud full of water in the sky in the rainy season.', 'veda-app-ai-draft', true),
('ramayana-4-11-26', 'en', 'Coming to the gate of Kishkindha, mighty Dundubhi roared like a war drum, shaking the earth.', 'veda-app-ai-draft', true),
('ramayana-4-11-27', 'en', 'Breaking the trees nearby, tearing the earth with his hooves, he scraped the gate proudly with his horn like an elephant.', 'veda-app-ai-draft', true),
('ramayana-4-11-28', 'en', 'Vali, who was in the inner apartments, heard the noise and, unable to bear it, came out with his women, like the moon with the stars.', 'veda-app-ai-draft', true),
('ramayana-4-11-29', 'en', 'Vali, lord of monkeys and all forest creatures, spoke to Dundubhi in measured words, each syllable clear.', 'veda-app-ai-draft', true),
('ramayana-4-11-30', 'en', 'Why do you roar here blocking the city gate? I know you, Dundubhi. Save your life, mighty one.', 'veda-app-ai-draft', true),
('ramayana-4-11-31', 'en', 'Hearing these words of the wise monkey king, Dundubhi spoke with eyes red with anger.', 'veda-app-ai-draft', true),
('ramayana-4-11-32', 'en', 'You should not speak in front of women, hero. Give me battle, and then I will know your strength.', 'veda-app-ai-draft', true),
('ramayana-4-11-33', 'en', 'Or I will hold back my anger for tonight. Take your pleasures freely till sunrise, monkey.', 'veda-app-ai-draft', true),
('ramayana-4-11-34', 'en', 'Whoever kills someone like you, drunk, careless, asleep, alone or dazed with pleasure, is counted among the worst sinners in the world.', 'veda-app-ai-draft', true),
('ramayana-4-11-35', 'en', 'Laughing gently, Vali sent away all the women, Tara and the rest, and spoke angrily to that great asura.', 'veda-app-ai-draft', true),
('ramayana-4-11-36', 'en', 'Do not think I am drunk, if you are unafraid in battle. Take this intoxication as the hero''s drink before the fight.', 'veda-app-ai-draft', true),
('ramayana-4-11-37', 'en', 'Having said this, enraged, he put on the golden garland given to his father by Indra and stood ready for battle.', 'veda-app-ai-draft', true),
('ramayana-4-11-38', 'en', 'Grabbing mountain-like Dundubhi by the horns, Vali threw him down and roared loudly.', 'veda-app-ai-draft', true),
('ramayana-4-11-39', 'en', 'In that deadly fight Dundubhi was crushed. Blood flowed from his ears as he was thrown, and the huge one fell to the ground dead.', 'veda-app-ai-draft', true),
('ramayana-4-11-40', 'en', 'Lifting the lifeless, senseless body with his arms, mighty Vali flung it a full yojana with one heave.', 'veda-app-ai-draft', true),
('ramayana-4-11-41', 'en', 'As it was flung, drops of blood from its mouth, carried by the wind, fell toward Matanga''s hermitage.', 'veda-app-ai-draft', true),
('ramayana-4-11-42', 'en', 'Seeing the drops of blood fallen there, the sage laid a great curse on Vali who had thrown it: He must not enter here; if he enters he will die.', 'veda-app-ai-draft', true),
('ramayana-4-11-43', 'en', 'Vali went to the great sage and begged him with folded hands.', 'veda-app-ai-draft', true),
('ramayana-4-11-44', 'en', 'Since then, afraid of the curse, the monkey does not wish to enter or even look at the great mountain Rishyamuka, lord of men.', 'veda-app-ai-draft', true),
('ramayana-4-11-45', 'en', 'Knowing he cannot enter, Rama, I wander this great forest with my ministers, free from despair.', 'veda-app-ai-draft', true),
('ramayana-4-11-46', 'en', 'Here is Dundubhi''s heap of bones, huge like a mountain peak, thrown down because of Vali''s pride in his strength.', 'veda-app-ai-draft', true),
('ramayana-4-11-47', 'en', 'And these are seven great sal trees with hanging branches, any one of which Vali can strip of leaves by his strength.', 'veda-app-ai-draft', true),
('ramayana-4-11-48', 'en', 'I have shown you his unmatched strength, Rama. How will you be able to kill Vali in battle, king?', 'veda-app-ai-draft', true),
('ramayana-4-11-49', 'en', 'If you could split these sal trees with a single arrow, then I would know you are able to kill Vali, mighty-armed one.', 'veda-app-ai-draft', true),
('ramayana-4-11-50', 'en', 'Hearing great Sugriva''s words, mighty-armed Raghava lifted Dundubhi''s body playfully with his big toe and flung it ten yojanas.', 'veda-app-ai-draft', true),
('ramayana-4-11-51', 'en', 'Seeing the body thrown, Sugriva again spoke meaningful words to Rama in front of Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-11-52', 'en', 'Friend, the body was wet and full of fresh flesh when it was thrown before. Now it is light, fleshless, like straw, Raghava. One cannot tell from this whether your strength or his is greater.', 'veda-app-ai-draft', true),
('ramayana-4-12-1', 'en', 'Hearing Sugriva''s well-spoken words, radiant Rama took up his bow to give him confidence.', 'veda-app-ai-draft', true),
('ramayana-4-12-2', 'en', 'Taking the fearsome bow and a single arrow, the giver of honour aimed at the sal trees and shot, filling the directions with the twang of the string.', 'veda-app-ai-draft', true),
('ramayana-4-12-3', 'en', 'Released by the mighty one, the gold-adorned arrow split the seven sal trees on the hillside and entered the earth.', 'veda-app-ai-draft', true),
('ramayana-4-12-4', 'en', 'In a moment the swift arrow pierced the earth, came out again and quickly went back into Rama''s own quiver.', 'veda-app-ai-draft', true),
('ramayana-4-12-5', 'en', 'Seeing the seven sal trees pierced, the chief of monkeys was utterly amazed at the speed of Rama''s arrow.', 'veda-app-ai-draft', true),
('ramayana-4-12-6', 'en', 'Overjoyed, Sugriva fell with his head to the ground before Raghava, his ornaments hanging down, with folded hands.', 'veda-app-ai-draft', true),
('ramayana-4-12-7', 'en', 'Delighted by that deed, he said to Rama, knower of dharma, the best of all who know weapons, the hero standing there:', 'veda-app-ai-draft', true),
('ramayana-4-12-8', 'en', 'With your arrows you could kill even all the gods with Indra in battle, best of men. How much more Vali, lord!', 'veda-app-ai-draft', true),
('ramayana-4-12-9', 'en', 'Who could stand before you in battle, Kakutstha, when with one arrow you split seven great sal trees, a hill and the earth?', 'veda-app-ai-draft', true),
('ramayana-4-12-10', 'en', 'Today my grief is gone and my joy is supreme, having found you as a friend, like great Indra and Varuna.', 'veda-app-ai-draft', true),
('ramayana-4-12-11', 'en', 'For my sake, Kakutstha, kill Vali this very day, my enemy in the form of a brother. Here I fold my hands to you.', 'veda-app-ai-draft', true),
('ramayana-4-12-12', 'en', 'Then wise Rama embraced the handsome Sugriva and replied with words Lakshmana approved:', 'veda-app-ai-draft', true),
('ramayana-4-12-13', 'en', 'Let us go from here to Kishkindha. Go quickly ahead, Sugriva, and when you get there, challenge Vali, who is a brother only in name.', 'veda-app-ai-draft', true),
('ramayana-4-12-14', 'en', 'They all went quickly to Vali''s city of Kishkindha and stood hidden among the trees in the thick forest.', 'veda-app-ai-draft', true),
('ramayana-4-12-15', 'en', 'Sugriva, his garment tied tight, roared terribly to call Vali out, as if splitting the sky with his cries.', 'veda-app-ai-draft', true),
('ramayana-4-12-16', 'en', 'Hearing his brother''s roar, mighty Vali, enraged, rushed out like the sun from the edge of the setting mountain.', 'veda-app-ai-draft', true),
('ramayana-4-12-17', 'en', 'Then a tumultuous fight broke out between Vali and Sugriva, terrible like that of the planets Mercury and Mars in the sky.', 'veda-app-ai-draft', true),
('ramayana-4-12-18', 'en', 'The two brothers, mad with rage, struck each other in battle with palms like lightning and fists like thunderbolts.', 'veda-app-ai-draft', true),
('ramayana-4-12-19', 'en', 'Then Rama, bow in hand, looked at the two heroes, who were as alike as the twin Ashvin gods.', 'veda-app-ai-draft', true),
('ramayana-4-12-20', 'en', 'Because Raghava could not tell Sugriva from Vali, he did not decide to release his deadly arrow.', 'veda-app-ai-draft', true),
('ramayana-4-12-21', 'en', 'Meanwhile Sugriva, beaten by Vali and not seeing Raghava his protector, fled to Rishyamuka.', 'veda-app-ai-draft', true),
('ramayana-4-12-22', 'en', 'Exhausted, his body soaked in blood and battered by blows, chased by the angry Vali, he entered the great forest.', 'veda-app-ai-draft', true),
('ramayana-4-12-23', 'en', 'Seeing him enter the forest, mighty Vali, afraid of the curse, said You are spared and turned back.', 'veda-app-ai-draft', true),
('ramayana-4-12-24', 'en', 'Raghava too, with his brother and Hanuman, came to the same forest where Sugriva was.', 'veda-app-ai-draft', true),
('ramayana-4-12-25', 'en', 'Seeing Rama come with Lakshmana, Sugriva, ashamed, spoke miserably, looking at the ground.', 'veda-app-ai-draft', true),
('ramayana-4-12-26', 'en', 'You told me to challenge him, showed me your power, then let my enemy beat me. What have you done now?', 'veda-app-ai-draft', true),
('ramayana-4-12-27', 'en', 'You should have told me truly at that moment, Raghava, I will not kill Vali. Then I would not have gone from here.', 'veda-app-ai-draft', true),
('ramayana-4-12-28', 'en', 'As great Sugriva spoke so piteously in a miserable voice, Raghava spoke again.', 'veda-app-ai-draft', true),
('ramayana-4-12-29', 'en', 'Sugriva, my friend, listen and let go of your anger. Here is why I did not release this arrow.', 'veda-app-ai-draft', true),
('ramayana-4-12-30', 'en', 'In ornaments, dress, size and gait, you and Vali are alike, Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-12-31', 'en', 'In voice, radiance, glance, valour and speech, monkey, I could not tell you two apart.', 'veda-app-ai-draft', true),
('ramayana-4-12-32', 'en', 'So, confused by your likeness, best of monkeys, I did not loose my swift, enemy-destroying arrow.', 'veda-app-ai-draft', true),
('ramayana-4-12-33', 'en', 'But within a moment you will see Vali struck down in battle by one arrow from me, writhing on the ground.', 'veda-app-ai-draft', true),
('ramayana-4-12-34', 'en', 'Make a mark of recognition on yourself, lord of monkeys, so I can know you when you are fighting him.', 'veda-app-ai-draft', true),
('ramayana-4-12-35', 'en', 'Lakshmana, pull up this flowering gajapushpi vine with its lovely marks and put it around great Sugriva''s neck.', 'veda-app-ai-draft', true),
('ramayana-4-12-36', 'en', 'Then Lakshmana pulled up the flowering gajapushpi growing on the hillside and placed it around his neck.', 'veda-app-ai-draft', true),
('ramayana-4-12-37', 'en', 'With the vine around his neck, glorious Sugriva shone like a rain cloud at twilight with a garland of cranes.', 'veda-app-ai-draft', true),
('ramayana-4-12-38', 'en', 'Shining in body and reassured by Rama''s words, he went with Rama to Kishkindha, which Vali ruled.', 'veda-app-ai-draft', true),
('ramayana-4-13-1', 'en', 'Righteous Rama, Lakshmana''s elder brother, went with Sugriva from Rishyamuka to Kishkindha, guarded by Vali''s might.', 'veda-app-ai-draft', true),
('ramayana-4-13-2', 'en', 'Rama raised his great gold-adorned bow and took arrows bright as the sun, made for victory.', 'veda-app-ai-draft', true),
('ramayana-4-13-3', 'en', 'Ahead of great Raghava went sturdy-necked Sugriva and mighty Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-13-4', 'en', 'Behind came heroic Hanuman, Nala, the monkey Nila and radiant Tara, leaders of monkey troops.', 'veda-app-ai-draft', true),
('ramayana-4-13-5', 'en', 'They looked at the trees weighed down with flowers and the clear rivers flowing to the sea,', 'veda-app-ai-draft', true),
('ramayana-4-13-6', 'en', 'the grottoes, hills, waterfalls and caves, the chief peaks and lovely valleys,', 'veda-app-ai-draft', true),
('ramayana-4-13-7', 'en', 'and along the way they saw ponds full of water, adorned with leaves clear as beryl and lotuses with opening buds.', 'veda-app-ai-draft', true),
('ramayana-4-13-8', 'en', 'They rang with karandava ducks, cranes, swans, vanjula birds, water fowl, chakravakas and other birds.', 'veda-app-ai-draft', true),
('ramayana-4-13-9', 'en', 'They saw deer roaming everywhere on the open ground, fearless forest dwellers feeding on tender grass shoots.', 'veda-app-ai-draft', true),
('ramayana-4-13-10', 'en', 'And wild elephants, fierce, roaming alone, with white tusks, enemies of the ponds, breaking down the banks.', 'veda-app-ai-draft', true),
('ramayana-4-13-11', 'en', 'Seeing other forest creatures and birds flying through the sky, Sugriva''s followers went on quickly.', 'veda-app-ai-draft', true),
('ramayana-4-13-12', 'en', 'As they hurried on, Rama, joy of the Raghus, saw a forest thick with trees and said to Sugriva:', 'veda-app-ai-draft', true),
('ramayana-4-13-13', 'en', 'This cluster of trees shines like a cloud in the sky, vast as a mass of clouds and ringed with banana plants.', 'veda-app-ai-draft', true),
('ramayana-4-13-14', 'en', 'What is this? I wish to know, friend, I am curious. I would like you to satisfy my curiosity.', 'veda-app-ai-draft', true),
('ramayana-4-13-15', 'en', 'Hearing great Raghava''s words, Sugriva told him about that great forest as they walked.', 'veda-app-ai-draft', true),
('ramayana-4-13-16', 'en', 'This, Raghava, is a vast hermitage that removes weariness, rich in gardens and groves, with sweet roots, fruits and water.', 'veda-app-ai-draft', true),
('ramayana-4-13-17', 'en', 'Here lived seven sages called the Saptajanas, firm in their vows, who always lay in water with their heads down.', 'veda-app-ai-draft', true),
('ramayana-4-13-18', 'en', 'Living in the forest and eating only air every seventh night, after seven hundred years they went to heaven in their bodies.', 'veda-app-ai-draft', true),
('ramayana-4-13-19', 'en', 'By their power this hermitage, walled by trees, cannot be entered even by the gods and demons with Indra.', 'veda-app-ai-draft', true),
('ramayana-4-13-20', 'en', 'Birds and other forest creatures avoid it. Those who enter it by mistake never come back.', 'veda-app-ai-draft', true),
('ramayana-4-13-21', 'en', 'Here one hears the sound of ornaments with clear syllables, the sounds of instruments and singing, and a divine fragrance, Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-13-22', 'en', 'The three sacred fires still burn, and this smoke can be seen, thick and dusky red like a dove''s body, wrapping the treetops.', 'veda-app-ai-draft', true),
('ramayana-4-13-23', 'en', 'Righteous Raghava, bow to them with your brother Lakshmana, pure and with folded hands.', 'veda-app-ai-draft', true),
('ramayana-4-13-24', 'en', 'No harm is seen in the body of those who bow to those sages of perfected soul, Rama.', 'veda-app-ai-draft', true),
('ramayana-4-13-25', 'en', 'Then Rama with his brother Lakshmana, hands folded, paid respect to those great sages.', 'veda-app-ai-draft', true),
('ramayana-4-13-26', 'en', 'Having paid respect, righteous Rama, his brother Lakshmana, Sugriva and the monkeys went on with glad hearts.', 'veda-app-ai-draft', true),
('ramayana-4-13-27', 'en', 'Going a long way from that hermitage of the Saptajanas, they saw Kishkindha, hard to attack, guarded by Vali.', 'veda-app-ai-draft', true),
('ramayana-4-14-1', 'en', 'They all went quickly to Kishkindha, guarded by Vali, and stood hidden behind trees in the thick forest.', 'veda-app-ai-draft', true),
('ramayana-4-14-2', 'en', 'Looking all around the forest, Sugriva, fond of forests and broad-necked, worked himself into a fierce anger.', 'veda-app-ai-draft', true),
('ramayana-4-14-3', 'en', 'Then, surrounded by his companions, he roared terribly and challenged Vali to battle, as if splitting the sky with his cries.', 'veda-app-ai-draft', true),
('ramayana-4-14-4', 'en', 'Then Sugriva, bright as the young sun and moving like a proud lion, seeing Rama skilled in action, spoke:', 'veda-app-ai-draft', true),
('ramayana-4-14-5', 'en', 'We have reached Vali''s city of Kishkindha, full of monkeys as if netted, with gateways of refined gold and rich in flags and machines.', 'veda-app-ai-draft', true),
('ramayana-4-14-6', 'en', 'Hero, make your earlier promise to kill Vali come true quickly, as the season brings a vine to fruit.', 'veda-app-ai-draft', true),
('ramayana-4-14-7', 'en', 'Spoken to this way by Sugriva, righteous Raghava, destroyer of enemies, replied:', 'veda-app-ai-draft', true),
('ramayana-4-14-8', 'en', 'You bear a mark of recognition with this gajapushpi, like the sun in the sky ringed with a garland of stars.', 'veda-app-ai-draft', true),
('ramayana-4-14-9', 'en', 'Today, monkey, with a single arrow in battle I will free you from the fear and enmity Vali has caused.', 'veda-app-ai-draft', true),
('ramayana-4-14-10', 'en', 'Show me your enemy, Sugriva, who has the form of a brother, and Vali will be killed and rolling in the dust of the forest.', 'veda-app-ai-draft', true),
('ramayana-4-14-11', 'en', 'If he comes into my sight and goes back alive, then let me be blamed, and you may condemn me at once.', 'veda-app-ai-draft', true),
('ramayana-4-14-12', 'en', 'You saw me split the seven sal trees with an arrow. So know that by my strength Vali is as good as dead today.', 'veda-app-ai-draft', true),
('ramayana-4-14-13', 'en', 'I have never spoken a falsehood, hero, even in hardship, and bound by love of dharma I never will.', 'veda-app-ai-draft', true),
('ramayana-4-14-14', 'en', 'I will make my promise fruitful. Drop your worry, as Indra makes the rice in the field ripen with rain.', 'veda-app-ai-draft', true),
('ramayana-4-14-15', 'en', 'So, Sugriva, make that sound to call out gold-garlanded Vali, by which the monkey will rush out.', 'veda-app-ai-draft', true),
('ramayana-4-14-16', 'en', 'Proud of his victories, boasting of conquest, not beaten by you before, Vali who loves a fight will rush out from the city without hesitation.', 'veda-app-ai-draft', true),
('ramayana-4-14-17', 'en', 'Heroes who know their own strength do not tolerate insult from enemies in battle, especially in front of women.', 'veda-app-ai-draft', true),
('ramayana-4-14-18', 'en', 'Hearing Rama''s words, golden-tawny Sugriva roared a cruel roar, as if tearing the sky apart.', 'veda-app-ai-draft', true),
('ramayana-4-14-19', 'en', 'Frightened by the sound, cows ran off, their lustre gone, like noblewomen thrown into turmoil when a king''s misrule touches them.', 'veda-app-ai-draft', true),
('ramayana-4-14-20', 'en', 'Deer ran swiftly like horses routed in battle, and birds fell to the ground like planets whose merit is spent.', 'veda-app-ai-draft', true),
('ramayana-4-14-21', 'en', 'Then the son of the Sun, confident, his fire swelling with courage, quickly let out a roar like a mass of thunderclouds, like the ocean with its waves tossed by the wind.', 'veda-app-ai-draft', true),
('ramayana-4-15-1', 'en', 'Vali, in the inner apartments, heard that roar of his great brother Sugriva and could not bear it.', 'veda-app-ai-draft', true),
('ramayana-4-15-2', 'en', 'Hearing his roar that shook all beings, his intoxication vanished at once and a great anger fell on him.', 'veda-app-ai-draft', true),
('ramayana-4-15-3', 'en', 'Vali, his body seized by rage, glowing like the twilight sun, suddenly lost his lustre like the eclipsed sun.', 'veda-app-ai-draft', true),
('ramayana-4-15-4', 'en', 'Vali, fierce with his fangs and like a blazing fire in anger, looked like a lake with lotuses torn up along with their stalks.', 'veda-app-ai-draft', true),
('ramayana-4-15-5', 'en', 'Hearing that unbearable sound, the monkey rushed out, as if splitting the earth with his heavy strides.', 'veda-app-ai-draft', true),
('ramayana-4-15-6', 'en', 'But Tara embraced him lovingly, showing her care, and, frightened and anxious, spoke these well-meant words.', 'veda-app-ai-draft', true),
('ramayana-4-15-7', 'en', 'Hero, give up this anger that has come like a river''s flood, as one rising from bed in the morning throws off a used garland.', 'veda-app-ai-draft', true),
('ramayana-4-15-8', 'en', 'I do not like you rushing out so suddenly. Listen, I will tell you why you are being stopped.', 'veda-app-ai-draft', true),
('ramayana-4-15-9', 'en', 'He came before in anger and challenged you to battle. You came out, beat him, and he fled in all directions.', 'veda-app-ai-draft', true),
('ramayana-4-15-10', 'en', 'For him, beaten and especially hurt by you, to come back and challenge you again makes me suspicious.', 'veda-app-ai-draft', true),
('ramayana-4-15-11', 'en', 'The pride and resolve in his roar and its fury are no small matter.', 'veda-app-ai-draft', true),
('ramayana-4-15-12', 'en', 'I do not think Sugriva has come here without help. He has some support behind him that he relies on as he roars.', 'veda-app-ai-draft', true),
('ramayana-4-15-13', 'en', 'The monkey is clever and wise by nature. Sugriva will not go with someone whose strength he has not tested.', 'veda-app-ai-draft', true),
('ramayana-4-15-14', 'en', 'Hero, I heard earlier what young prince Angada said. I will tell you these words for your good.', 'veda-app-ai-draft', true),
('ramayana-4-15-15', 'en', 'Your brother''s famous ally, harsh in battle, is Rama, crusher of enemy armies, like the fire rising at the end of an age.', 'veda-app-ai-draft', true),
('ramayana-4-15-16', 'en', 'He is a sheltering tree for good people, the highest refuge of those in trouble, the shelter of the suffering, and the one vessel of fame.', 'veda-app-ai-draft', true),
('ramayana-4-15-17', 'en', 'Full of knowledge and wisdom, devoted to his father''s command, he is a great mine of virtues, as the king of mountains is of minerals.', 'veda-app-ai-draft', true),
('ramayana-4-15-18', 'en', 'So it is not wise for you to oppose that great soul Rama, unconquerable and immeasurable in battle.', 'veda-app-ai-draft', true),
('ramayana-4-15-19', 'en', 'Hero, I will tell you something, and I do not wish to find fault. Listen and do what I say for your good.', 'veda-app-ai-draft', true),
('ramayana-4-15-20', 'en', 'Quickly and rightly crown Sugriva as crown prince. Do not quarrel, hero king, with your stronger brother.', 'veda-app-ai-draft', true),
('ramayana-4-15-21', 'en', 'I think it right for you to make friends with Rama and be loving to Sugriva, casting enmity far away.', 'veda-app-ai-draft', true),
('ramayana-4-15-22', 'en', 'This younger brother, the monkey, deserves your care. Whether there or here, he is in every way your kin.', 'veda-app-ai-draft', true),
('ramayana-4-15-23', 'en', 'If you would do what pleases me, and if you know I want your good, then I beg you earnestly, follow my sound advice.', 'veda-app-ai-draft', true),
('ramayana-4-16-1', 'en', 'As Tara, whose face was like the moon, spoke this way, Vali rebuked her and said:', 'veda-app-ai-draft', true),
('ramayana-4-16-2', 'en', 'Why should I tolerate the fury of this roaring brother, who is especially my enemy, lovely one?', 'veda-app-ai-draft', true),
('ramayana-4-16-3', 'en', 'For heroes who have never been defeated and never retreat in battle, bearing an insult is worse than death, timid one.', 'veda-app-ai-draft', true),
('ramayana-4-16-4', 'en', 'I cannot bear the fury of Sugriva, eager for a fight and roaring, though he is weaker.', 'veda-app-ai-draft', true),
('ramayana-4-16-5', 'en', 'And you need not worry about Raghava on my account. He knows dharma and is grateful. How would he do wrong?', 'veda-app-ai-draft', true),
('ramayana-4-16-6', 'en', 'Go back with the women. Why do you follow me further? You have shown your love, Tara, and your devotion to me.', 'veda-app-ai-draft', true),
('ramayana-4-16-7', 'en', 'I will go and fight Sugriva. Drop your fear. I will crush his pride, but he will not lose his life.', 'veda-app-ai-draft', true),
('ramayana-4-16-8', 'en', 'I make you swear by my life and by my victory, go back. I will return after beating that brother in battle.', 'veda-app-ai-draft', true),
('ramayana-4-16-9', 'en', 'Then sweet-spoken Tara embraced Vali and, weeping softly, walked around him respectfully, keeping him to her right.', 'veda-app-ai-draft', true),
('ramayana-4-16-10', 'en', 'Then, wishing him victory, she recited blessings with mantras and, dazed with grief, went into the inner apartments with the women.', 'veda-app-ai-draft', true),
('ramayana-4-16-11', 'en', 'When Tara had gone home with the women, Vali left the city in anger, hissing like a great snake.', 'veda-app-ai-draft', true),
('ramayana-4-16-12', 'en', 'Sighing, the swift and furious Vali cast his eyes all around, eager to see his enemy.', 'veda-app-ai-draft', true),
('ramayana-4-16-13', 'en', 'Then glorious Vali saw golden-tawny Sugriva, well girded and firm, blazing like fire.', 'veda-app-ai-draft', true),
('ramayana-4-16-14', 'en', 'Seeing mighty Sugriva standing ready, the furious Vali tightened his garment.', 'veda-app-ai-draft', true),
('ramayana-4-16-15', 'en', 'Girded tight, mighty Vali raised his fist and, seizing the moment, went straight at Sugriva to fight.', 'veda-app-ai-draft', true),
('ramayana-4-16-16', 'en', 'Sugriva too raised his clenched fist and came at gold-garlanded Vali in greater fury.', 'veda-app-ai-draft', true),
('ramayana-4-16-17', 'en', 'Vali, eyes red with anger, said this to Sugriva, skilled in battle, as he rushed at him with great speed:', 'veda-app-ai-draft', true),
('ramayana-4-16-18', 'en', 'This fist I have clenched tight, fingers set firm, released with force, will take your life as it goes.', 'veda-app-ai-draft', true),
('ramayana-4-16-19', 'en', 'Told this, Sugriva angrily said to Vali: Let my fist fall on your head and take your life.', 'veda-app-ai-draft', true),
('ramayana-4-16-20', 'en', 'Struck by him, Vali rushed at him in rage, spouting blood like a mountain with streams gushing out.', 'veda-app-ai-draft', true),
('ramayana-4-16-21', 'en', 'Sugriva easily uprooted a sal tree and with force struck Vali on the limbs, like a thunderbolt hitting a great mountain.', 'veda-app-ai-draft', true),
('ramayana-4-16-22', 'en', 'Vali, shaken by the blow of the sal tree, reeled like a boat overloaded on the sea.', 'veda-app-ai-draft', true),
('ramayana-4-16-23', 'en', 'The two, terrible in strength and courage, swift as Garuda, swelled in fierce forms like the moon and sun in the sky.', 'veda-app-ai-draft', true),
('ramayana-4-16-24', 'en', 'Sugriva, his pride broken by Vali and his strength waning, still in anger showed his quickness against Vali.', 'veda-app-ai-draft', true),
('ramayana-4-16-25', 'en', 'Then Raghava fitted to his bow an arrow like a venomous snake, and the great arrow struck Vali''s chest.', 'veda-app-ai-draft', true),
('ramayana-4-16-26', 'en', 'Struck with force, Vali fell to the ground.', 'veda-app-ai-draft', true),
('ramayana-4-16-27', 'en', 'Drenched in streams of blood like a flowering ashoka shaken by the wind, the son of Indra fell senseless to the earth in battle like Indra''s banner thrown down.', 'veda-app-ai-draft', true),
('ramayana-4-17-1', 'en', 'Struck by Rama''s arrow, Vali, harsh in battle, fell suddenly like a felled tree.', 'veda-app-ai-draft', true),
('ramayana-4-17-2', 'en', 'With all his limbs stretched on the ground and his ornaments of refined gold, he fell like the banner of the king of gods with its ropes cut.', 'veda-app-ai-draft', true),
('ramayana-4-17-3', 'en', 'When the lord of monkeys and bears fell, the earth lost its brightness like the sky without the moon.', 'veda-app-ai-draft', true),
('ramayana-4-17-4', 'en', 'Even as the great one lay on the ground, his body was not left by glory, life, splendour or valour.', 'veda-app-ai-draft', true),
('ramayana-4-17-5', 'en', 'The fine golden garland set with gems, given by Indra, held the life, splendour and glory of the monkey chief.', 'veda-app-ai-draft', true),
('ramayana-4-17-6', 'en', 'With that golden garland the hero, leader of monkeys, looked like a rain cloud edged with twilight.', 'veda-app-ai-draft', true),
('ramayana-4-17-7', 'en', 'His garland, his body, and the arrow that pierced his vitals, like beauty made in three parts, shone even as he lay fallen.', 'veda-app-ai-draft', true),
('ramayana-4-17-8', 'en', 'That weapon, shot from Rama''s bow, which opens the way to heaven, brought the hero to the highest state.', 'veda-app-ai-draft', true),
('ramayana-4-17-9', 'en', 'Fallen in battle like a fire whose flames are gone, like Yayati fallen from heaven when his merit was spent,', 'veda-app-ai-draft', true),
('ramayana-4-17-10', 'en', 'like the sun thrown down to earth by Time at the end of an age, unconquerable like great Indra, unbearable like great Indra,', 'veda-app-ai-draft', true),
('ramayana-4-17-11', 'en', 'Vali, son of great Indra, wearing a golden garland, lion-chested, mighty-armed, with a blazing face and tawny eyes, lay fallen. Rama, followed by Lakshmana, saw him and approached.', 'veda-app-ai-draft', true),
('ramayana-4-17-12', 'en', 'Seeing Raghava and mighty Lakshmana, Vali spoke words that were courteous yet harsh, and grounded in dharma.', 'veda-app-ai-draft', true),
('ramayana-4-17-13', 'en', 'What merit have you gained by killing one who was facing away? I was absorbed in fighting and met my death because of you.', 'veda-app-ai-draft', true),
('ramayana-4-17-14', 'en', 'Rama is well born, strong in character, radiant, keeps his vows, feels compassion and is devoted to the good of the people.', 'veda-app-ai-draft', true),
('ramayana-4-17-15', 'en', 'He is kind, very energetic, knows what is proper, and is firm in his vows. So all beings proclaim your fame on earth.', 'veda-app-ai-draft', true),
('ramayana-4-17-16', 'en', 'Weighing those virtues and your noble birth, I came to fight Sugriva even though Tara tried to stop me.', 'veda-app-ai-draft', true),
('ramayana-4-17-17', 'en', 'Before I saw you, I thought: He will not shoot me while I am engaged and off guard with another.', 'veda-app-ai-draft', true),
('ramayana-4-17-18', 'en', 'I did not know you were a destroyer of your own soul, unrighteous behind a banner of righteousness, wicked in conduct, like a well covered with grass.', 'veda-app-ai-draft', true),
('ramayana-4-17-19', 'en', 'Wearing the dress of the good, you are sinful, like a hidden fire. I did not recognise you, cloaked in the disguise of dharma.', 'veda-app-ai-draft', true),
('ramayana-4-17-20', 'en', 'I did you no harm in your land or your city, nor did I insult you. Why do you kill me, who am blameless?', 'veda-app-ai-draft', true),
('ramayana-4-17-21', 'en', 'A monkey who lives in the forest, always eating fruits and roots, who was not fighting you but someone else.', 'veda-app-ai-draft', true),
('ramayana-4-17-22', 'en', 'You are a king''s son, trusted and handsome, and you bear the outward signs of dharma, king.', 'veda-app-ai-draft', true),
('ramayana-4-17-23', 'en', 'Who, born in a warrior family, learned and free of doubt, would hide behind the signs of dharma and do a cruel deed?', 'veda-app-ai-draft', true),
('ramayana-4-17-24', 'en', 'Rama, born in a royal line and famed as righteous, why do you go about unworthy in a worthy form?', 'veda-app-ai-draft', true),
('ramayana-4-17-25', 'en', 'Conciliation, generosity, forgiveness, dharma, truth, steadiness and valour are the virtues of kings, king, and punishment for wrongdoers.', 'veda-app-ai-draft', true),
('ramayana-4-17-26', 'en', 'We are forest creatures, Rama, animals eating roots and fruits. That is our nature, while you are a man, a lord of men.', 'veda-app-ai-draft', true),
('ramayana-4-17-27', 'en', 'Land, gold and silver are the reasons for conflict. What greed could you have for the forest or for my fruits?', 'veda-app-ai-draft', true),
('ramayana-4-17-28', 'en', 'Policy and discipline, punishment and favour: the conduct of kings is ordered, and kings do not act on whim.', 'veda-app-ai-draft', true),
('ramayana-4-17-29', 'en', 'But you are ruled by desire, angry, unsteady, careless of royal duties, and quick to use the bow.', 'veda-app-ai-draft', true),
('ramayana-4-17-30', 'en', 'You have no regard for dharma, your mind is not set on what is right, and you are dragged by the senses, acting on whim, lord of men.', 'veda-app-ai-draft', true),
('ramayana-4-17-31', 'en', 'Having killed me, an innocent, with an arrow here, Kakutstha, what will you say among good people after this shameful deed?', 'veda-app-ai-draft', true),
('ramayana-4-17-32', 'en', 'The killer of a king, of a brahmin, of cows, a thief, one who delights in killing living beings, an unbeliever, and one who marries before his elder brother all go to hell.', 'veda-app-ai-draft', true),
('ramayana-4-17-33', 'en', 'My skin cannot be worn by good people, my hair and bones are shunned, and my flesh is not to be eaten by the righteous like you.', 'veda-app-ai-draft', true),
('ramayana-4-17-34', 'en', 'Five five-clawed animals may be eaten by brahmins and kshatriyas, Raghava: the porcupine, the hedgehog, the monitor lizard, the hare and the tortoise.', 'veda-app-ai-draft', true),
('ramayana-4-17-35', 'en', 'The wise do not touch my skin or bones, king, and my flesh may not be eaten. Yet I, a five-clawed animal, have been killed.', 'veda-app-ai-draft', true),
('ramayana-4-17-36', 'en', 'With you as her protector, Kakutstha, the earth is unprotected, like a virtuous woman married to a scoundrel.', 'veda-app-ai-draft', true),
('ramayana-4-17-37', 'en', 'Deceitful, dishonest, petty, falsely humble, how were you, so wicked, born of the great Dasharatha?', 'veda-app-ai-draft', true),
('ramayana-4-17-38', 'en', 'I have been killed by the elephant Rama, who has broken the girth of good conduct, overstepped the dharma of the good, and thrown off the goad of righteousness.', 'veda-app-ai-draft', true),
('ramayana-4-17-39', 'en', 'If you had fought me in the open, prince, you would be seeing the god Yama today, killed by me.', 'veda-app-ai-draft', true),
('ramayana-4-17-40', 'en', 'But I, hard to overcome, was killed in battle by you unseen, like a drunk man asleep bitten by a snake.', 'veda-app-ai-draft', true),
('ramayana-4-17-41', 'en', 'If you killed me to please Sugriva, I could have tied Ravana by the neck and given him to you alive in battle.', 'veda-app-ai-draft', true),
('ramayana-4-17-42', 'en', 'Whether Maithili were thrown into the sea or the underworld, at your command I would have brought her back like the white mare.', 'veda-app-ai-draft', true),
('ramayana-4-17-43', 'en', 'It is fitting that Sugriva should get the kingdom when I have gone to heaven. What is not fitting is that you killed me unrighteously in battle.', 'veda-app-ai-draft', true),
('ramayana-4-17-44', 'en', 'The world is surely bound by Time in this way. If you have an answer that fits, think it over well.', 'veda-app-ai-draft', true),
('ramayana-4-17-45', 'en', 'Having said this, the great son of the king of gods, his mouth dry and in pain from the arrow, looked at Rama, bright as the sun, and fell silent.', 'veda-app-ai-draft', true),
('ramayana-4-18-1', 'en', 'Addressed by the stricken, fading Vali with words courteous yet harsh, full of dharma and meaning,', 'veda-app-ai-draft', true),
('ramayana-4-18-2', 'en', 'to him who was like the sun without light, a cloud emptied of rain, a quenched fire, having said his say,', 'veda-app-ai-draft', true),
('ramayana-4-18-3', 'en', 'to the matchless lord of monkeys, endowed with dharma and sense, Rama, having been reproached, spoke afterward.', 'veda-app-ai-draft', true),
('ramayana-4-18-4', 'en', 'Without understanding dharma, wealth, desire and the customs of the world, how can you in your childishness blame me here today?', 'veda-app-ai-draft', true),
('ramayana-4-18-5', 'en', 'Without asking wise elders respected by teachers, gentle one, you wish to speak to me out of a monkey''s restlessness.', 'veda-app-ai-draft', true),
('ramayana-4-18-6', 'en', 'This land, with its mountains, woods and forests, belongs to the Ikshvakus, and so does the power to punish or favour its animals, birds and people.', 'veda-app-ai-draft', true),
('ramayana-4-18-7', 'en', 'Righteous Bharata rules it, truthful and straight, knowing the truth of dharma, desire and wealth, devoted to punishing and favouring rightly.', 'veda-app-ai-draft', true),
('ramayana-4-18-8', 'en', 'He in whom policy, discipline and truth are firmly set, and valour as seen, is a king who knows time and place.', 'veda-app-ai-draft', true),
('ramayana-4-18-9', 'en', 'Under his righteous command, we and other kings travel the whole earth, wishing to spread dharma.', 'veda-app-ai-draft', true),
('ramayana-4-18-10', 'en', 'While Bharata, tiger among kings and lover of dharma, rules the whole earth, who could act against dharma?', 'veda-app-ai-draft', true),
('ramayana-4-18-11', 'en', 'Standing firm in our own highest duty, honouring Bharata''s command, we punish those who stray from the path, as the rules require.', 'veda-app-ai-draft', true),
('ramayana-4-18-12', 'en', 'But you have violated dharma, are condemned by your deeds, are ruled by desire, and have not kept to the path of a king.', 'veda-app-ai-draft', true),
('ramayana-4-18-13', 'en', 'An elder brother, a father, and one who gives knowledge: these three are to be regarded as fathers by those who walk the path of dharma.', 'veda-app-ai-draft', true),
('ramayana-4-18-14', 'en', 'A younger brother, one''s own son, and a virtuous disciple: these three are to be regarded as sons, if dharma is the rule.', 'veda-app-ai-draft', true),
('ramayana-4-18-15', 'en', 'The dharma of the good is subtle and very hard to know, monkey. The Self in the hearts of all beings knows what is right and wrong.', 'veda-app-ai-draft', true),
('ramayana-4-18-16', 'en', 'Restless yourself, consulting with restless, undisciplined monkeys, what can you see, like one born blind consulting the born blind?', 'veda-app-ai-draft', true),
('ramayana-4-18-17', 'en', 'I will make the meaning of what I say clear to you. You should not blame me merely out of anger.', 'veda-app-ai-draft', true),
('ramayana-4-18-18', 'en', 'See the reason I killed you: you live with your brother''s wife, abandoning the eternal dharma.', 'veda-app-ai-draft', true),
('ramayana-4-18-19', 'en', 'While great Sugriva is still alive, you, a doer of evil, live out of lust with Ruma, who is like a daughter-in-law to you.', 'veda-app-ai-draft', true),
('ramayana-4-18-20', 'en', 'So, monkey, since you have strayed from dharma and act on desire, this punishment has been given for touching your brother''s wife.', 'veda-app-ai-draft', true),
('ramayana-4-18-21', 'en', 'For one who goes against dharma and departs from the ways of the world, leader of monkeys, I see no restraint but punishment.', 'veda-app-ai-draft', true),
('ramayana-4-18-22', 'en', 'A man who out of lust approaches his own daughter, his sister, or his younger brother''s wife is held to deserve death.', 'veda-app-ai-draft', true),
('ramayana-4-18-23', 'en', 'Bharata is lord of the earth and we carry out his commands. You have overstepped dharma. How could this be ignored?', 'veda-app-ai-draft', true),
('ramayana-4-18-24', 'en', 'Wise Bharata, ruling by dharma, stands ready to restrain those who violate serious duties and act on desire.', 'veda-app-ai-draft', true),
('ramayana-4-18-25', 'en', 'Taking Bharata''s command as our rule, lord of monkeys, we stand ready to restrain those like you who break the bounds.', 'veda-app-ai-draft', true),
('ramayana-4-18-26', 'en', 'My friendship with Sugriva is like my bond with Lakshmana. He is devoted to my good in the matter of my wife and kingdom.', 'veda-app-ai-draft', true),
('ramayana-4-18-27', 'en', 'I gave my promise then in the presence of the monkeys. How could someone like me disregard a promise?', 'veda-app-ai-draft', true),
('ramayana-4-18-28', 'en', 'So for all these great reasons rooted in dharma, accept that your punishment was right.', 'veda-app-ai-draft', true),
('ramayana-4-18-29', 'en', 'In every way your punishment must be seen as dharma, by one who sees that helping a friend is also dharma.', 'veda-app-ai-draft', true),
('ramayana-4-18-30', 'en', 'People who have done wrong and are punished by kings become pure and go to heaven, like the good who have done good.', 'veda-app-ai-draft', true),
('ramayana-4-18-31', 'en', 'My noble ancestor Mandhata wished a terrible punishment on an ascetic who had done wrong, a wrong like the one you have done.', 'veda-app-ai-draft', true),
('ramayana-4-18-32', 'en', 'Other careless kings have also done wrong, and they perform atonement, by which that stain is removed.', 'veda-app-ai-draft', true),
('ramayana-4-18-33', 'en', 'So enough of grieving. Your death was decreed by dharma, tiger among monkeys. We do not act by our own will.', 'veda-app-ai-draft', true),
('ramayana-4-18-34', 'en', 'With nets, snares and many kinds of traps, hidden or in the open, men catch many animals, whether running, frightened, trusting or standing still.', 'veda-app-ai-draft', true),
('ramayana-4-18-35', 'en', 'Men who want meat shoot animals whether alert or not, even when they are turned away, and there is no fault in it.', 'veda-app-ai-draft', true),
('ramayana-4-18-36', 'en', 'Royal sages who know dharma go hunting too. So I killed you with an arrow in battle, monkey, whether you were fighting me or not, because you are an animal of the branches.', 'veda-app-ai-draft', true),
('ramayana-4-18-37', 'en', 'Kings, best of monkeys, are without doubt the givers of rare dharma, of life and of good fortune.', 'veda-app-ai-draft', true),
('ramayana-4-18-38', 'en', 'One should not harm them, abuse them, insult them, or speak unkindly to them. They are gods moving on earth in human form.', 'veda-app-ai-draft', true),
('ramayana-4-18-39', 'en', 'But you, not understanding dharma and resting only on anger, blame me, who stand in the dharma of my fathers and forefathers.', 'veda-app-ai-draft', true),
('ramayana-4-18-40', 'en', 'Told this by Rama, Vali, deeply pained, replied to Rama with folded hands, lord of monkeys that he was.', 'veda-app-ai-draft', true),
('ramayana-4-18-41', 'en', 'What you say, best of men, is so without doubt. The lesser cannot answer the greater.', 'veda-app-ai-draft', true),
('ramayana-4-18-42', 'en', 'Whatever unfitting, unkind words I spoke before in my rashness, do not hold them against me, Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-18-43', 'en', 'You know the true meaning of things and delight in the good of the people. Your mind is clear and unfailing in understanding causes and effects.', 'veda-app-ai-draft', true),
('ramayana-4-18-44', 'en', 'Protect me too with words of dharma, knower of dharma, though I strayed from dharma and put the transgressor first.', 'veda-app-ai-draft', true),
('ramayana-4-18-45', 'en', 'Then Vali, his throat choked with tears and crying softly in pain, looked at Rama and spoke like an elephant stuck in mud.', 'veda-app-ai-draft', true),
('ramayana-4-18-46', 'en', 'I do not grieve for myself, nor for Tara, nor my kin, as much as for my son Angada, best in virtue, with his golden armlets.', 'veda-app-ai-draft', true),
('ramayana-4-18-47', 'en', 'Cherished since childhood, he will be miserable not seeing me and will dry up like a pond whose water is drunk.', 'veda-app-ai-draft', true),
('ramayana-4-18-48', 'en', 'Set your best intentions on Sugriva and on Angada, for you are the ruler and protector who decides what should and should not be done.', 'veda-app-ai-draft', true),
('ramayana-4-18-49', 'en', 'The way you treat Bharata and Lakshmana, king, think of treating Sugriva and Angada the same way.', 'veda-app-ai-draft', true),
('ramayana-4-18-50', 'en', 'See to it that Sugriva does not despise poor Tara, who suffers because of my faults.', 'veda-app-ai-draft', true),
('ramayana-4-18-51', 'en', 'One who is favoured by you, follows your will and stays under your guidance can rule the kingdom well.', 'veda-app-ai-draft', true),
('ramayana-4-18-52', 'en', 'Rama comforted Vali, whose vision was now clear.', 'veda-app-ai-draft', true),
('ramayana-4-18-53', 'en', 'Do not worry about us, or about yourself, best of monkeys. We have decided rightly by dharma, especially regarding you.', 'veda-app-ai-draft', true),
('ramayana-4-18-54', 'en', 'One who punishes the punishable and one who is punished when deserving it both fulfil their purpose and do not perish.', 'veda-app-ai-draft', true),
('ramayana-4-18-55', 'en', 'So by this union with punishment you are freed from sin and have returned to your true, righteous nature by the path dharma shows.', 'veda-app-ai-draft', true),
('ramayana-4-18-56', 'en', 'Hearing the sweet, composed and fitting words of great Rama, follower of the path of dharma and crusher in battle, the monkey replied.', 'veda-app-ai-draft', true),
('ramayana-4-18-57', 'en', 'Burning from the arrow and out of my senses, I blamed you without knowing, lord. You of fearsome valour like Indra, be gracious and forgive me, lord of the earth.', 'veda-app-ai-draft', true),
('ramayana-4-19-1', 'en', 'The great king of monkeys, lying wounded by the arrow, given reasoned answers, made no reply.', 'veda-app-ai-draft', true),
('ramayana-4-19-2', 'en', 'His limbs broken by rocks, badly struck by trees, overcome by Rama''s arrow, he fainted at the end of his life.', 'veda-app-ai-draft', true),
('ramayana-4-19-3', 'en', 'Tara heard that Vali, tiger among monkeys, had been killed in battle by the arrow shot by Rama.', 'veda-app-ai-draft', true),
('ramayana-4-19-4', 'en', 'Hearing the terrible, painful news of her husband''s death, she rushed out with her son, terrified, from the mountain cave.', 'veda-app-ai-draft', true),
('ramayana-4-19-5', 'en', 'The mighty monkeys around Angada, seeing Rama with his bow, fled in fear.', 'veda-app-ai-draft', true),
('ramayana-4-19-6', 'en', 'She saw the frightened monkeys rushing toward her, like deer scattered from their herd when the leader has been killed.', 'veda-app-ai-draft', true),
('ramayana-4-19-7', 'en', 'Grieving herself, she went to the grieving monkeys, all frightened of Rama as if chased by his arrows, and said:', 'veda-app-ai-draft', true),
('ramayana-4-19-8', 'en', 'Monkeys, you who walked ahead of that lion among kings, why do you abandon him and run away in terror, wretched as you are?', 'veda-app-ai-draft', true),
('ramayana-4-19-9', 'en', 'If one brother was struck down by the cruel brother for the sake of the kingdom, by Rama''s arrows shot from afar...', 'veda-app-ai-draft', true),
('ramayana-4-19-10', 'en', 'Hearing the monkey queen''s words, the shape-shifting monkeys spoke timely, clear words to the lady.', 'veda-app-ai-draft', true),
('ramayana-4-19-11', 'en', 'Live, mother of a son! Turn back and protect your son Angada. Death in the form of Rama has killed Vali and is taking him away.', 'veda-app-ai-draft', true),
('ramayana-4-19-12', 'en', 'Brushing aside the trees and huge rocks thrown at him, Vali was struck down by arrows like thunderbolts, as if by a thunderbolt.', 'veda-app-ai-draft', true),
('ramayana-4-19-13', 'en', 'With this tiger among monkeys, bright as Indra, killed, this whole army has broken, fled and scattered.', 'veda-app-ai-draft', true),
('ramayana-4-19-14', 'en', 'Let the city be guarded by heroes and Angada be crowned. The monkeys will serve Vali''s son once he is on the throne.', 'veda-app-ai-draft', true),
('ramayana-4-19-15', 'en', 'Or, lovely-faced one, perhaps a safe place here suits you better. The monkeys are entering the strongholds quickly today.', 'veda-app-ai-draft', true),
('ramayana-4-19-16', 'en', 'There are forest dwellers here, with wives and without. From our own people, greedy and estranged, we face great danger.', 'veda-app-ai-draft', true),
('ramayana-4-19-17', 'en', 'Hearing the words of those who had gone only a little way, the lady with the lovely smile answered as befitted her.', 'veda-app-ai-draft', true),
('ramayana-4-19-18', 'en', 'What use is my son, the kingdom, or my own life, when that noble lion among monkeys, my husband, is dying?', 'veda-app-ai-draft', true),
('ramayana-4-19-19', 'en', 'I will go to the feet of that great one who was struck down by the arrow Rama shot.', 'veda-app-ai-draft', true),
('ramayana-4-19-20', 'en', 'Saying this, she ran, weeping and worn with grief, beating her head and chest with her arms in sorrow.', 'veda-app-ai-draft', true),
('ramayana-4-19-21', 'en', 'As she came she saw her husband fallen on the ground, the slayer of danava lords who never turned back in battle,', 'veda-app-ai-draft', true),
('ramayana-4-19-22', 'en', 'who hurled great mountains as Indra hurls thunderbolts, roaring like a mass of great clouds driven by a great wind,', 'veda-app-ai-draft', true),
('ramayana-4-19-23', 'en', 'equal to Indra in valour, now like a cloud that has finished raining, the fearsome roarer among roarers, a hero felled by a hero,', 'veda-app-ai-draft', true),
('ramayana-4-19-24', 'en', 'like a lion killed by a tiger for the sake of prey, or a shrine with banners and altar worshipped by all the world,', 'veda-app-ai-draft', true),
('ramayana-4-19-25', 'en', 'torn down by Garuda for the sake of a serpent. She saw Rama standing leaning on his mighty bow,', 'veda-app-ai-draft', true),
('ramayana-4-19-26', 'en', 'and Rama''s younger brother, and her husband''s younger brother. Passing them by, the lovely lady came to her husband killed in battle.', 'veda-app-ai-draft', true),
('ramayana-4-19-27', 'en', 'Seeing him, she fell to the ground in pain and confusion, then rose as if from sleep, crying out: My noble husband!', 'veda-app-ai-draft', true),
('ramayana-4-19-28', 'en', 'She wept seeing her husband bound by the cords of death. Seeing her crying like an osprey, Sugriva...', 'veda-app-ai-draft', true),
('ramayana-4-19-29', 'en', '...fell into deep despair, and seeing Angada arrive.', 'veda-app-ai-draft', true),
('ramayana-4-20-1', 'en', 'Seeing him struck to the ground by the deadly arrow from Rama''s bow, moon-faced Tara...', 'veda-app-ai-draft', true),
('ramayana-4-20-2', 'en', 'The lovely lady came to her husband and embraced him, seeing Vali, mighty as an elephant, struck by the arrow.', 'veda-app-ai-draft', true),
('ramayana-4-20-3', 'en', 'Her heart burning with grief, Tara lamented over the monkey king, bright as Indra, fallen like an uprooted tree.', 'veda-app-ai-draft', true),
('ramayana-4-20-4', 'en', 'Hero of fearsome valour in battle, best of leapers, why do you not speak to me today, helpless and alone?', 'veda-app-ai-draft', true),
('ramayana-4-20-5', 'en', 'Rise, tiger among monkeys, and take the best bed. The best of kings do not lie on the ground like this.', 'veda-app-ai-draft', true),
('ramayana-4-20-6', 'en', 'Surely the earth is very dear to you, lord of the earth, since even lifeless you embrace her with your limbs and leave me.', 'veda-app-ai-draft', true),
('ramayana-4-20-7', 'en', 'Clearly, hero, by following dharma you have built another lovely city like Kishkindha on the road to heaven.', 'veda-app-ai-draft', true),
('ramayana-4-20-8', 'en', 'The pleasures we shared with you in the honey-scented forests, you have now brought to an end.', 'veda-app-ai-draft', true),
('ramayana-4-20-9', 'en', 'Joyless and hopeless, I am sunk in an ocean of grief now that you, leader of great leaders, have died.', 'veda-app-ai-draft', true),
('ramayana-4-20-10', 'en', 'My heart must be very hard, for seeing you killed on the ground, burning with grief, it does not burst into a thousand pieces today.', 'veda-app-ai-draft', true),
('ramayana-4-20-11', 'en', 'You took Sugriva''s wife and banished him. This is the result of that, lord of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-20-12', 'en', 'Out of delusion you rebuked me, though I wished only your good and spoke helpful words, wanting the best for the monkey king.', 'veda-app-ai-draft', true),
('ramayana-4-20-13', 'en', 'Surely it was Time, beyond doubt, that ended your life, by which you were forced helplessly into Sugriva''s power.', 'veda-app-ai-draft', true),
('ramayana-4-20-14', 'en', 'Wretched as I am, never having known sorrow before, I will live a pitiful widow''s life of grief and pain, like one without a protector.', 'veda-app-ai-draft', true),
('ramayana-4-20-15', 'en', 'Heroic Angada, raised with love, tender and used to comfort, what state will he live in with his uncle mad with anger?', 'veda-app-ai-draft', true),
('ramayana-4-20-16', 'en', 'Son, look well at your father, who loved dharma. It will be hard for you to see him again, my child.', 'veda-app-ai-draft', true),
('ramayana-4-20-17', 'en', 'Comfort your son and give him your last message. Kiss him on the head, for you are setting out on a long journey.', 'veda-app-ai-draft', true),
('ramayana-4-20-18', 'en', 'Rama has done a great deed in killing you and has freed himself from his debt to Sugriva by keeping his promise.', 'veda-app-ai-draft', true),
('ramayana-4-20-19', 'en', 'Have your wish, Sugriva. You will get Ruma back. Enjoy the kingdom without worry. Your brother, your enemy, is struck down.', 'veda-app-ai-draft', true),
('ramayana-4-20-20', 'en', 'Why do you not speak to me lovingly as I lament like this? Look at these many fine wives of yours, lord of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-20-21', 'en', 'Hearing her lament, the monkey women all around took hold of the wretched Angada and wailed in sorrow.', 'veda-app-ai-draft', true),
('ramayana-4-20-22', 'en', 'Hero with armlets on your arms, why do you leave Angada and set out on a long journey today? It is not right to leave a son so full of virtue, you who love your son.', 'veda-app-ai-draft', true),
('ramayana-4-20-23', 'en', 'What wrong have I or your son done you, my lord of lovely dress, that you leave your companion today and go to Yama''s realm? This is unkind, hero.', 'veda-app-ai-draft', true),
('ramayana-4-20-24', 'en', 'If I did anything unkind to you without thinking, long-armed lord of the monkey race, forgive me. I bow my head to your feet, hero.', 'veda-app-ai-draft', true),
('ramayana-4-20-25', 'en', 'Weeping piteously beside her husband with the monkey women, Tara of faultless beauty resolved to fast to death, sitting on the ground where Vali lay.', 'veda-app-ai-draft', true),
('ramayana-4-21-1', 'en', 'Then Hanuman, leader of monkey troops, gently comforted Tara, who had fallen like a star from the sky.', 'veda-app-ai-draft', true),
('ramayana-4-21-2', 'en', 'Whatever a being does from virtue or fault, it receives calmly after death as the fruit of its own deeds, good or bad.', 'veda-app-ai-draft', true),
('ramayana-4-21-3', 'en', 'You who should be pitied, whom do you pity? Wretched, whom do you feel sorry for? Who should grieve for whom in this body, which is like a bubble?', 'veda-app-ai-draft', true),
('ramayana-4-21-4', 'en', 'You, mother of a living son, should look after young Angada. Think of the steps to be taken for his future.', 'veda-app-ai-draft', true),
('ramayana-4-21-5', 'en', 'You know how uncertain the coming and going of beings is. So, wise lady, one should do good that leads beyond this world.', 'veda-app-ai-draft', true),
('ramayana-4-21-6', 'en', 'He on whom thousands, millions and hundreds of millions of monkeys depended for their share has reached his destined end.', 'veda-app-ai-draft', true),
('ramayana-4-21-7', 'en', 'Since he saw his aims by justice and was devoted to conciliation, generosity and forgiveness, he has gone to the world won by dharma. You should not grieve for him.', 'veda-app-ai-draft', true),
('ramayana-4-21-8', 'en', 'All the monkeys, your son Angada, and the kingdom of monkeys and bears now have you as their protector, blameless one.', 'veda-app-ai-draft', true),
('ramayana-4-21-9', 'en', 'Gently guide these two who burn with grief, lady. Supported by you, let Angada rule the earth.', 'veda-app-ai-draft', true),
('ramayana-4-21-10', 'en', 'Let everything be done for the king as tradition holds and as the moment demands. This is the decree of Time.', 'veda-app-ai-draft', true),
('ramayana-4-21-11', 'en', 'Let the monkey king receive his funeral rites and Angada be crowned. Seeing your son on the lion throne, you will find peace.', 'veda-app-ai-draft', true),
('ramayana-4-21-12', 'en', 'Hearing his words, Tara, pained by her husband''s death, gave her answer to Hanuman standing there.', 'veda-app-ai-draft', true),
('ramayana-4-21-13', 'en', 'Better than a hundred sons like Angada is to embrace the body of this hero, even dead.', 'veda-app-ai-draft', true),
('ramayana-4-21-14', 'en', 'I have no authority over the monkey kingdom or over Angada. His uncle Sugriva is next in line for all duties.', 'veda-app-ai-draft', true),
('ramayana-4-21-15', 'en', 'This thought should not be held about Angada, Hanuman. A father is a son''s guardian, not a mother, best of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-21-16', 'en', 'Nothing here or hereafter is better for me than the shelter of the monkey king. This bed of a hero killed facing the enemy is the one fit for me to share.', 'veda-app-ai-draft', true),
('ramayana-4-22-1', 'en', 'Vali, his life ebbing and breathing faintly, looked all around and first saw Sugriva in front of his son.', 'veda-app-ai-draft', true),
('ramayana-4-22-2', 'en', 'Speaking clearly and with affection, Vali addressed Sugriva, lord of monkeys, who had won the victory.', 'veda-app-ai-draft', true),
('ramayana-4-22-3', 'en', 'Sugriva, do not take it amiss that I was dragged by force by fate and delusion of mind into wrongdoing.', 'veda-app-ai-draft', true),
('ramayana-4-22-4', 'en', 'I think, dear one, happiness was not meant for us both at the same time. The love that brothers share turned out otherwise for us.', 'veda-app-ai-draft', true),
('ramayana-4-22-5', 'en', 'Take the kingdom of these forest dwellers this very day, and know that I am going today to the realm of Yama.', 'veda-app-ai-draft', true),
('ramayana-4-22-6', 'en', 'I am quickly giving up my life, my kingdom, this great fortune, and my great and spotless fame.', 'veda-app-ai-draft', true),
('ramayana-4-22-7', 'en', 'In this state, hero, I will tell you something. Even if it is hard to do, king, you must do it.', 'veda-app-ai-draft', true),
('ramayana-4-22-8', 'en', 'Look at Angada lying on the ground, his face full of tears, a boy used to comfort and raised in happiness, yet no fool.', 'veda-app-ai-draft', true),
('ramayana-4-22-9', 'en', 'Protect in every way my son, dearer to me than life, as your own son. He lacks me but lacks nothing else.', 'veda-app-ai-draft', true),
('ramayana-4-22-10', 'en', 'Be his giver and protector in every way, lord of monkeys, and give him safety in danger as I did.', 'veda-app-ai-draft', true),
('ramayana-4-22-11', 'en', 'This glorious son of Tara, your equal in valour, will be at your front in killing those demons.', 'veda-app-ai-draft', true),
('ramayana-4-22-12', 'en', 'Strong and swift, young Angada, Tara''s son, will show his valour in battle and do deeds worthy of him.', 'veda-app-ai-draft', true),
('ramayana-4-22-13', 'en', 'This daughter of Sushena is fully skilled in judging subtle matters and reading omens of every kind.', 'veda-app-ai-draft', true),
('ramayana-4-22-14', 'en', 'Whatever she says is good should be done without doubt. Nothing Tara thinks ever turns out otherwise.', 'veda-app-ai-draft', true),
('ramayana-4-22-15', 'en', 'You must do Raghava''s task without hesitation. Not doing it would be wrong, and if dishonoured he might destroy you.', 'veda-app-ai-draft', true),
('ramayana-4-22-16', 'en', 'And put on this heavenly golden garland, Sugriva. Great glory dwells in it, which would leave it when I die.', 'veda-app-ai-draft', true),
('ramayana-4-22-17', 'en', 'Spoken to this way by Vali out of brotherly love, Sugriva lost his joy and became sad again, like the moon seized by an eclipse.', 'veda-app-ai-draft', true),
('ramayana-4-22-18', 'en', 'Calmed by Vali''s words, doing what was right and alert, he took the golden garland with permission.', 'veda-app-ai-draft', true),
('ramayana-4-22-19', 'en', 'Having given the golden garland, Vali, ready for the passage after death, saw his son standing there and spoke to Angada with love.', 'veda-app-ai-draft', true),
('ramayana-4-22-20', 'en', 'Respect time and place now, bear the pleasant and the unpleasant, endure joy and sorrow in their season, and be obedient to Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-22-21', 'en', 'Sugriva will not indulge you as I always did, mighty-armed one, if you behave that way.', 'veda-app-ai-draft', true),
('ramayana-4-22-22', 'en', 'Do not side with his foes or go with his enemies, subduer of enemies. Be devoted to your master''s interests, self-controlled and obedient to Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-22-23', 'en', 'Do not be too familiar, nor too distant. Both are great faults, so keep to the middle.', 'veda-app-ai-draft', true),
('ramayana-4-22-24', 'en', 'Having said this, his eyes rolling and pierced by the arrow, his fearsome teeth bared, he breathed his last.', 'veda-app-ai-draft', true),
('ramayana-4-22-25', 'en', 'When the heroic lord of monkeys was killed, the monkeys found no peace, like cows in a great forest with lions when the bull of the herd is killed.', 'veda-app-ai-draft', true),
('ramayana-4-22-26', 'en', 'Then Tara, plunged in an ocean of grief, looked at her dead husband''s face, embraced Vali and sank to the ground, like a vine clinging to a great tree cut down.', 'veda-app-ai-draft', true),
('ramayana-4-23-1', 'en', 'Then, kissing the monkey king''s face, Tara spoke to her husband, now dead and gone from the world.', 'veda-app-ai-draft', true),
('ramayana-4-23-2', 'en', 'You lie in pain on the hard, stony ground, hero, because you did not follow my words.', 'veda-app-ai-draft', true),
('ramayana-4-23-3', 'en', 'Surely the earth is dearer to you than I am, monkey king, for you lie embracing her and do not answer me.', 'veda-app-ai-draft', true),
('ramayana-4-23-4', 'en', 'Now Sugriva is the hero, rash and dear one. The chiefs of bears and monkeys will now serve him as mighty.', 'veda-app-ai-draft', true),
('ramayana-4-23-5', 'en', 'Hearing these painful laments and Angada grieving, and these words of mine, why do you not wake?', 'veda-app-ai-draft', true),
('ramayana-4-23-6', 'en', 'This is the hero''s bed on which you lie killed in battle, where you once laid low your enemies.', 'veda-app-ai-draft', true),
('ramayana-4-23-7', 'en', 'My dear, of pure nature and noble birth, lover of battle, giver of honour, you have gone and left me alone and unprotected.', 'veda-app-ai-draft', true),
('ramayana-4-23-8', 'en', 'A wise man should not give his daughter to a hero. See me, a hero''s wife, made a widow in an instant.', 'veda-app-ai-draft', true),
('ramayana-4-23-9', 'en', 'My pride is broken, my lasting refuge is broken, and I am sunk in a vast, bottomless ocean of grief.', 'veda-app-ai-draft', true),
('ramayana-4-23-10', 'en', 'My heart must be made of stone, so hard that it has not broken into a hundred pieces seeing my husband killed.', 'veda-app-ai-draft', true),
('ramayana-4-23-11', 'en', 'My friend and husband, dear to me by nature, a hero brave in battle, has met his death.', 'veda-app-ai-draft', true),
('ramayana-4-23-12', 'en', 'A woman without her husband, even if she has sons and is full of wealth and grain, is called a widow by the wise.', 'veda-app-ai-draft', true),
('ramayana-4-23-13', 'en', 'You lie, hero, in a circle of blood from your own body, as if on a bed with a crimson cover.', 'veda-app-ai-draft', true),
('ramayana-4-23-14', 'en', 'Your body is covered all over with dust and blood, and I cannot embrace you with my arms, bull among monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-23-15', 'en', 'Today Sugriva has achieved his aim in this terrible feud, his fear taken away by one arrow loosed by Rama.', 'veda-app-ai-draft', true),
('ramayana-4-23-16', 'en', 'The arrow lodged in your heart stops me from touching your body as I look at you, now that you are dead.', 'veda-app-ai-draft', true),
('ramayana-4-23-17', 'en', 'Then Nila drew out the arrow from his body, like a blazing venomous snake hidden in a mountain cave.', 'veda-app-ai-draft', true),
('ramayana-4-23-18', 'en', 'As the arrow was drawn out, its brilliance shone like the sun''s ray caught on the peak of the setting mountain.', 'veda-app-ai-draft', true),
('ramayana-4-23-19', 'en', 'Streams of blood fell from his wounds everywhere, like streams from a mountain mixed with red ochre.', 'veda-app-ai-draft', true),
('ramayana-4-23-20', 'en', 'Wiping her husband covered with battle dust, she bathed the hero struck by the weapon with tears from her eyes.', 'veda-app-ai-draft', true),
('ramayana-4-23-21', 'en', 'Seeing her husband killed, all his limbs soaked with blood, Tara said to her tawny-eyed son Angada:', 'veda-app-ai-draft', true),
('ramayana-4-23-22', 'en', 'See your father''s last, terrible state, son. The long feud has ended through his wrong deeds.', 'veda-app-ai-draft', true),
('ramayana-4-23-23', 'en', 'Bow to the king, your father, giver of honour, bright as the rising sun, who is going to the abode of Yama.', 'veda-app-ai-draft', true),
('ramayana-4-23-24', 'en', 'Told this, Angada rose and took his father''s feet in his strong round arms, saying: I am Angada.', 'veda-app-ai-draft', true),
('ramayana-4-23-25', 'en', 'Why do you not say to Angada as he bows, as before: Live long, son?', 'veda-app-ai-draft', true),
('ramayana-4-23-26', 'en', 'With my son I sit beside you who are lifeless, like a cow with her calf beside a bull just killed by a lion.', 'veda-app-ai-draft', true),
('ramayana-4-23-27', 'en', 'Having performed the sacrifice of battle with the waters of many weapons, how could you bathe in this final bath without me, your wife?', 'veda-app-ai-draft', true),
('ramayana-4-23-28', 'en', 'Why do I not see here the gold garland that the king of gods gave you, pleased with you in battle?', 'veda-app-ai-draft', true),
('ramayana-4-23-29', 'en', 'Royal glory does not leave you even in death, giver of honour, as light stays on the king of mountains when the sun turns away.', 'veda-app-ai-draft', true),
('ramayana-4-23-30', 'en', 'You did not heed my wholesome words, and I could not stop you. With you killed in battle, I and my son are destroyed, and fortune leaves me here along with you.', 'veda-app-ai-draft', true),
('ramayana-4-24-1', 'en', 'Seeing Vali dead, Raghava, scorcher of enemies, then spoke courteous words to Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-24-2', 'en', 'The dead are not helped by grief and lament. You should attend to what must be done next.', 'veda-app-ai-draft', true),
('ramayana-4-24-3', 'en', 'Worldly custom must be followed, and you have shed your tears. No act can be done beyond its proper time.', 'veda-app-ai-draft', true),
('ramayana-4-24-4', 'en', 'Destiny is the fixed cause in the world, destiny the means of action, destiny the cause of all beings'' engagements here.', 'veda-app-ai-draft', true),
('ramayana-4-24-5', 'en', 'No one is the doer of anything, nor master over his assignment. The world moves by its nature, and Time is its final support.', 'veda-app-ai-draft', true),
('ramayana-4-24-6', 'en', 'Time does not pass beyond Time, nor does Time fail. Having reached its nature, nothing goes beyond it.', 'veda-app-ai-draft', true),
('ramayana-4-24-7', 'en', 'Time has no kinship, no cause, no favouritism for valour, no ties of friend or relative, and it is not under anyone''s control.', 'veda-app-ai-draft', true),
('ramayana-4-24-8', 'en', 'But one who sees well must look at the workings of Time. Dharma, wealth and pleasure are all arranged in the order of Time.', 'veda-app-ai-draft', true),
('ramayana-4-24-9', 'en', 'From here Vali has gone to his own nature and received the fruit of his deeds, purified by the union of dharma, wealth and desire, lord of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-24-10', 'en', 'Through fulfilling his own duty, the great one has won heaven, not clinging to his life.', 'veda-app-ai-draft', true),
('ramayana-4-24-11', 'en', 'This is the best destiny, which the leader of monkey troops has reached. So enough of grieving; let what is timely be done.', 'veda-app-ai-draft', true),
('ramayana-4-24-12', 'en', 'When Rama finished speaking, Lakshmana, slayer of enemy heroes, spoke courteously to Sugriva, who was dazed.', 'veda-app-ai-draft', true),
('ramayana-4-24-13', 'en', 'Sugriva, perform his funeral rites now, together with Tara and Angada, for the cremation of Vali.', 'veda-app-ai-draft', true),
('ramayana-4-24-14', 'en', 'Order plenty of dry wood and heavenly sandalwood for Vali''s last rites.', 'veda-app-ai-draft', true),
('ramayana-4-24-15', 'en', 'Comfort Angada, who is downcast. Do not be foolish, for this city now depends on you.', 'veda-app-ai-draft', true),
('ramayana-4-24-16', 'en', 'Let Angada bring garlands, clothes of many kinds, ghee, oil, perfumes and whatever else is needed next.', 'veda-app-ai-draft', true),
('ramayana-4-24-17', 'en', 'Tara, quickly bring a palanquin and come. Speed is a virtue, especially at a time like this.', 'veda-app-ai-draft', true),
('ramayana-4-24-18', 'en', 'Let monkeys fit to carry a palanquin get ready. Strong and capable, they will carry Vali out.', 'veda-app-ai-draft', true),
('ramayana-4-24-19', 'en', 'Having said this to Sugriva, Lakshmana, joy of Sumitra and slayer of enemy heroes, stood beside his brother.', 'veda-app-ai-draft', true),
('ramayana-4-24-20', 'en', 'Hearing Lakshmana''s words, Tara, flustered, quickly entered the cave, his mind set on the palanquin.', 'veda-app-ai-draft', true),
('ramayana-4-24-21', 'en', 'Bringing the palanquin, Tara set it down, carried by heroic monkeys fit for the task.', 'veda-app-ai-draft', true),
('ramayana-4-24-22', 'en', 'Then Sugriva lifted Vali and, crying out, placed him on the palanquin together with Angada.', 'veda-app-ai-draft', true),
('ramayana-4-24-23', 'en', 'Having placed the lifeless Vali on the palanquin, adorned with many ornaments, garlands and clothes,', 'veda-app-ai-draft', true),
('ramayana-4-24-24', 'en', 'King Sugriva, lord of monkeys, then ordered: Let my noble brother''s funeral be performed fittingly.', 'veda-app-ai-draft', true),
('ramayana-4-24-25', 'en', 'Let monkeys go in front scattering many kinds of jewels, and the palanquin follow behind.', 'veda-app-ai-draft', true),
('ramayana-4-24-26', 'en', 'As the special splendours of kings are seen on earth, so they quickly performed Vali''s funeral.', 'veda-app-ai-draft', true),
('ramayana-4-24-27', 'en', 'Quickly taking Angada with them, the monkey Tara and all the others went, wailing, their kinsman killed.', 'veda-app-ai-draft', true),
('ramayana-4-24-28', 'en', 'Tara and all the monkey women, their leader killed, followed their husband, wailing in piteous voices.', 'veda-app-ai-draft', true),
('ramayana-4-24-29', 'en', 'With the sound of the monkey women weeping in the forest, all the woods and hills seemed to wail on every side.', 'veda-app-ai-draft', true),
('ramayana-4-24-30', 'en', 'On a secluded sandbank of a mountain river surrounded by water, many forest monkeys built a pyre.', 'veda-app-ai-draft', true),
('ramayana-4-24-31', 'en', 'The bearers lowered the palanquin from their shoulders and all stood apart, full of grief.', 'veda-app-ai-draft', true),
('ramayana-4-24-32', 'en', 'Then Tara, seeing her husband lying on the palanquin, took his head on her lap and lamented in deep sorrow.', 'veda-app-ai-draft', true),
('ramayana-4-24-33', 'en', 'Why do you look at these people stricken with grief? Even in death, giver of honour, your face seems joyful and has the colour of the setting sun, as if alive.', 'veda-app-ai-draft', true),
('ramayana-4-24-34', 'en', 'Time in the form of Rama drags you away, monkey, Time by whom we all were made widows with one arrow in battle.', 'veda-app-ai-draft', true),
('ramayana-4-24-35', 'en', 'These are your monkey queens, always dear to you, king of kings, come this long way on foot. Why do you not wake?', 'veda-app-ai-draft', true),
('ramayana-4-24-36', 'en', 'Are these not your beloved wives with faces like the moon? Why do you not now look at Sugriva, lord of monkeys?', 'veda-app-ai-draft', true),
('ramayana-4-24-37', 'en', 'These ministers of yours, king, Tara and the others, and these townspeople sit around you, sinless one.', 'veda-app-ai-draft', true),
('ramayana-4-24-38', 'en', 'Dismiss them as is proper, subduer of foes, and then we will all play in the forests, merry with wine.', 'veda-app-ai-draft', true),
('ramayana-4-24-39', 'en', 'As Tara lamented this way, flooded with grief for her husband, the monkey women, themselves worn by sorrow, raised her up.', 'veda-app-ai-draft', true),
('ramayana-4-24-40', 'en', 'Then Angada, weeping, his senses stunned by grief, placed his father on the pyre with Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-24-41', 'en', 'Then, lighting the fire as the rites require, he walked around it keeping it to his left, distraught at his father setting out on the long road.', 'veda-app-ai-draft', true),
('ramayana-4-24-42', 'en', 'Having cremated Vali properly, the monkeys came to the lovely cool river to make water offerings.', 'veda-app-ai-draft', true),
('ramayana-4-24-43', 'en', 'Gathered there, putting Angada in front, with Sugriva and Tara, they poured water for Vali.', 'veda-app-ai-draft', true),
('ramayana-4-24-44', 'en', 'Mighty Kakutstha, saddened as Sugriva was sad and sharing his grief, had the funeral rites carried out.', 'veda-app-ai-draft', true),
('ramayana-4-25-1', 'en', 'Then the monkey chiefs surrounded and attended Sugriva, burning with grief, his clothes still wet.', 'veda-app-ai-draft', true),
('ramayana-4-25-2', 'en', 'Approaching mighty-armed Rama, tireless in action, they all stood with folded hands like sages before Brahma.', 'veda-app-ai-draft', true),
('ramayana-4-25-3', 'en', 'Then Hanuman, son of the Wind, like a golden mountain, his face like the rising sun, spoke with folded hands:', 'veda-app-ai-draft', true),
('ramayana-4-25-4', 'en', 'By your grace, lord, Sugriva has won this great ancestral kingdom of the monkeys, so hard to gain.', 'veda-app-ai-draft', true),
('ramayana-4-25-5', 'en', 'With your permission he will enter the fine city and arrange all affairs with his friends.', 'veda-app-ai-draft', true),
('ramayana-4-25-6', 'en', 'After bathing in the rites with many perfumes and herbs, he will honour you especially with jewels and garlands.', 'veda-app-ai-draft', true),
('ramayana-4-25-7', 'en', 'Please come to this lovely mountain cave and become our lord, delighting the monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-25-8', 'en', 'Told this by Hanuman, Raghava, slayer of enemy heroes, wise and skilled in speech, replied to Hanuman:', 'veda-app-ai-draft', true),
('ramayana-4-25-9', 'en', 'For fourteen years, gentle Hanuman, I will not enter a village or a city, keeping my father''s command.', 'veda-app-ai-draft', true),
('ramayana-4-25-10', 'en', 'Let heroic Sugriva, bull among monkeys, enter the rich and lovely cave properly and quickly be crowned king.', 'veda-app-ai-draft', true),
('ramayana-4-25-11', 'en', 'Having said this to Hanuman, Rama said to Sugriva: Crown this hero Angada as crown prince too.', 'veda-app-ai-draft', true),
('ramayana-4-25-12', 'en', 'This is the first month of the rains, Shravana, when the waters come. The four months called the rainy season have begun, gentle one.', 'veda-app-ai-draft', true),
('ramayana-4-25-13', 'en', 'This is not the time for a campaign. Enter your fine city. I will live on this mountain with Lakshmana, gentle one.', 'veda-app-ai-draft', true),
('ramayana-4-25-14', 'en', 'This mountain cave is lovely and spacious, airy, with plenty of water and plenty of lotuses and lilies, gentle one.', 'veda-app-ai-draft', true),
('ramayana-4-25-15', 'en', 'When the month of Kartika comes, strive for Ravana''s killing. This is our agreement, gentle one. Enter your home, be crowned king, and gladden your friends.', 'veda-app-ai-draft', true),
('ramayana-4-25-16', 'en', 'Given leave by Rama, Sugriva, bull among monkeys, entered lovely Kishkindha, once ruled by Vali.', 'veda-app-ai-draft', true),
('ramayana-4-25-17', 'en', 'Thousands of monkeys greeted the lord of monkeys joyfully as he entered and surrounded him on all sides.', 'veda-app-ai-draft', true),
('ramayana-4-25-18', 'en', 'Then all the subjects, seeing the lord of the monkey hosts, bowed with their heads to the ground, attentive.', 'veda-app-ai-draft', true),
('ramayana-4-25-19', 'en', 'Mighty Sugriva spoke with all the subjects, raised them up, and entered his brother''s pleasant inner apartments.', 'veda-app-ai-draft', true),
('ramayana-4-25-20', 'en', 'When Sugriva came out again, his friends consecrated the bull among monkeys as the immortals consecrated thousand-eyed Indra.', 'veda-app-ai-draft', true),
('ramayana-4-25-21', 'en', 'They brought him a white umbrella adorned with gold and two white yak-tail fans with golden handles, bringing glory.', 'veda-app-ai-draft', true),
('ramayana-4-25-22', 'en', 'Likewise all kinds of jewels, all seeds and herbs, shoots and flowers of milky trees,', 'veda-app-ai-draft', true),
('ramayana-4-25-23', 'en', 'white clothes, white unguent, fragrant garlands of land and water flowers,', 'veda-app-ai-draft', true),
('ramayana-4-25-24', 'en', 'heavenly sandalwood and many kinds of perfumes, unbroken rice, gold, priyangu, honey and ghee,', 'veda-app-ai-draft', true),
('ramayana-4-25-25', 'en', 'curd, a tiger skin and boar-skin sandals. Taking unguents, yellow pigment and red arsenic, sixteen fine maidens came there joyfully.', 'veda-app-ai-draft', true),
('ramayana-4-25-26', 'en', 'Then, at the proper time and by the rites, having pleased the best of brahmins with jewels, clothes and food for the best of monkeys,', 'veda-app-ai-draft', true),
('ramayana-4-25-27', 'en', 'those who knew the mantras offered oblations purified by mantras into the blazing fire spread with kusha grass.', 'veda-app-ai-draft', true),
('ramayana-4-25-28', 'en', 'Then on a lovely palace terrace adorned with colourful garlands, on a golden base covered with fine rugs,', 'veda-app-ai-draft', true),
('ramayana-4-25-29', 'en', 'they seated him facing east on the best seat with many mantras. Gathering water from rivers and streams and from sacred places all around,', 'veda-app-ai-draft', true),
('ramayana-4-25-30', 'en', 'and bringing it from all the seas, the bull-like monkeys placed the pure, clean water in golden jars.', 'veda-app-ai-draft', true),
('ramayana-4-25-31', 'en', 'With fine bull horns and golden pitchers, by the rite seen in the scriptures and ordained by the great sages,', 'veda-app-ai-draft', true),
('ramayana-4-25-32', 'en', 'Gaja, Gavaksha, Gavaya, Sharabha, Gandhamadana, Mainda, Dvivida, Hanuman, Jambavan and Nala', 'veda-app-ai-draft', true),
('ramayana-4-25-33', 'en', 'consecrated Sugriva with clear, fragrant water, as the Vasus consecrated thousand-eyed Indra.', 'veda-app-ai-draft', true),
('ramayana-4-25-34', 'en', 'When Sugriva was consecrated, all the great monkey chiefs shouted for joy there in their thousands.', 'veda-app-ai-draft', true),
('ramayana-4-25-35', 'en', 'Following Rama''s word, Sugriva, chief of monkeys, embraced Angada and made him crown prince.', 'veda-app-ai-draft', true),
('ramayana-4-25-36', 'en', 'When Angada was consecrated, the kind-hearted monkeys honoured Sugriva, saying: Well done, well done!', 'veda-app-ai-draft', true),
('ramayana-4-25-37', 'en', 'Lovely Kishkindha in its mountain cave became full of happy, well-fed people and bright with banners and flags.', 'veda-app-ai-draft', true),
('ramayana-4-25-38', 'en', 'Having reported the great coronation to great Rama, the mighty leader of the monkey host, having got back his wife Ruma, gained the kingdom as Indra did heaven.', 'veda-app-ai-draft', true),
('ramayana-4-26-1', 'en', 'When Sugriva was crowned and had entered the cave, Rama came with his brother to Mount Prasravana.', 'veda-app-ai-draft', true),
('ramayana-4-26-2', 'en', 'It echoed with tigers and deer, was full of lions with fearsome roars, hidden by many bushes and creepers and crowded with trees.', 'veda-app-ai-draft', true),
('ramayana-4-26-3', 'en', 'Home to bears, monkeys, langurs and wildcats, the mountain was like a mass of clouds and always had pure water.', 'veda-app-ai-draft', true),
('ramayana-4-26-4', 'en', 'On the peak of that mountain Rama and Lakshmana took a large, long cave as their dwelling.', 'veda-app-ai-draft', true),
('ramayana-4-26-5', 'en', 'Righteous Raghava lived there with Lakshmana on Mount Prasravana with its many lovely valleys and groves.', 'veda-app-ai-draft', true),
('ramayana-4-26-6', 'en', 'Though that mountain was very pleasant and rich in resources, Rama found no joy at all living there, remembering his wife who had been taken, dearer to him than life.', 'veda-app-ai-draft', true),
('ramayana-4-26-7', 'en', 'Especially when he saw the moon rising over the eastern hill, sleep would not come to him when he went to bed at night.', 'veda-app-ai-draft', true),
('ramayana-4-26-8', 'en', 'Seeing Kakutstha grieving always, his mind clouded with tears from that sorrow, his brother Lakshmana, sharing his pain, spoke consoling words:', 'veda-app-ai-draft', true),
('ramayana-4-26-9', 'en', 'Enough of this anguish, hero. You should not grieve. Everything fails for one who grieves, as you know.', 'veda-app-ai-draft', true),
('ramayana-4-26-10', 'en', 'You are devoted to action in the world, devoted to the gods, a believer, righteous and resolute, Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-26-11', 'en', 'Without resolve you cannot kill your enemy in battle, especially that crooked demon, even with all your valour.', 'veda-app-ai-draft', true),
('ramayana-4-26-12', 'en', 'Uproot your grief and make your resolve firm. Then destroy that demon with all his followers.', 'veda-app-ai-draft', true),
('ramayana-4-26-13', 'en', 'Kakutstha, you could overturn even the earth with its seas, forests and mountains. How much more Ravana!', 'veda-app-ai-draft', true),
('ramayana-4-26-14', 'en', 'I am only awakening your sleeping strength, like a fire hidden under ashes roused in time with bright offerings.', 'veda-app-ai-draft', true),
('ramayana-4-26-15', 'en', 'Honouring Lakshmana''s good and helpful words, Raghava spoke these words to his loving friend:', 'veda-app-ai-draft', true),
('ramayana-4-26-16', 'en', 'You have said, Lakshmana, what should be said by one who is devoted, loving, well-meaning and truly brave.', 'veda-app-ai-draft', true),
('ramayana-4-26-17', 'en', 'I have given up this grief that ruins all tasks. I will rouse my strength, unchecked in valour.', 'veda-app-ai-draft', true),
('ramayana-4-26-18', 'en', 'I await the autumn, now that the rainy season has come. Then I will kill that demon with his kingdom and followers.', 'veda-app-ai-draft', true),
('ramayana-4-26-19', 'en', 'Hearing Rama''s words, Lakshmana, delighting his friends, was glad and spoke again:', 'veda-app-ai-draft', true),
('ramayana-4-26-20', 'en', 'These words are worthy of you, destroyer of enemies. Now, Kakutstha, you have returned to your true nature.', 'veda-app-ai-draft', true),
('ramayana-4-26-21', 'en', 'Knowing your own strength, you should make it real. What you have said fits your learning and your lineage.', 'veda-app-ai-draft', true),
('ramayana-4-26-22', 'en', 'So, tiger among men, thinking of how to defeat the enemy, let the rainy season that has come pass, Raghava.', 'veda-app-ai-draft', true),
('ramayana-4-26-23', 'en', 'Hold back your anger and wait for autumn. Bear these four months with me, living on this mountain where lions roam, building up your strength, ready to kill the enemy.', 'veda-app-ai-draft', true),
('ramayana-4-27-1', 'en', 'Having killed Vali and crowned Sugriva, Rama, living on the ridge of Malyavan, said to Lakshmana:', 'veda-app-ai-draft', true),
('ramayana-4-27-2', 'en', 'The season of rain has come. Look at the sky covered with clouds like mountains.', 'veda-app-ai-draft', true),
('ramayana-4-27-3', 'en', 'Having drunk the essence of the seas through the sun''s rays and carried it like a child for nine months, the sky now gives birth to the elixir of rain.', 'veda-app-ai-draft', true),
('ramayana-4-27-4', 'en', 'One could climb into the sky on the stairways of clouds and adorn the sun with garlands of kutaja and arjuna flowers.', 'veda-app-ai-draft', true),
('ramayana-4-27-5', 'en', 'With copper-red clouds risen from the glow of dusk, paler at the edges, the sky looks as if its wounds were bound with soft bandages of cloud.', 'veda-app-ai-draft', true),
('ramayana-4-27-6', 'en', 'With gentle breezes for its sighs, tinted with the sandal of twilight and pale clouds, the sky seems sick with love.', 'veda-app-ai-draft', true),
('ramayana-4-27-7', 'en', 'This earth, worn by the heat and now flooded with new rain, sheds tears like Sita burning with grief.', 'veda-app-ai-draft', true),
('ramayana-4-27-8', 'en', 'The winds released from the clouds'' bellies, cool as kahlara lilies and scented with ketaki, could almost be drunk from cupped hands.', 'veda-app-ai-draft', true),
('ramayana-4-27-9', 'en', 'This mountain with flowering arjuna trees, scented with ketaki, is bathed by the rain like Sugriva consecrated when his enemy was quelled.', 'veda-app-ai-draft', true),
('ramayana-4-27-10', 'en', 'Wearing clouds like black deerskins and streams of rain like sacred threads, their caves filled with wind, the mountains seem like students reciting the Veda.', 'veda-app-ai-draft', true),
('ramayana-4-27-11', 'en', 'Struck by lightning as if by golden whips, with thunder rumbling within, the sky seems to cry out in pain.', 'veda-app-ai-draft', true),
('ramayana-4-27-12', 'en', 'The lightning flashing against the dark cloud seems to me like poor Vaidehi struggling in Ravana''s lap.', 'veda-app-ai-draft', true),
('ramayana-4-27-13', 'en', 'These directions, so pleasing to lovers, are now blotted out, as if smeared with clouds, the planets and moon hidden.', 'veda-app-ai-draft', true),
('ramayana-4-27-14', 'en', 'See, Lakshmana, the kutaja trees blooming on the mountain slopes, here and there choked with mist and eager for the rains, kindling longing in me, overcome by grief.', 'veda-app-ai-draft', true),
('ramayana-4-27-15', 'en', 'The dust has settled, the wind is cool today, the troubles of summer heat have ceased. Kings have halted their campaigns, and travellers go home.', 'veda-app-ai-draft', true),
('ramayana-4-27-16', 'en', 'The chakravaka birds, eager to live by Lake Manasa, have set out with their mates. On roads broken by constant rain, vehicles do not move.', 'veda-app-ai-draft', true),
('ramayana-4-27-17', 'en', 'The sky, strewn with clouds, shines bright in some places and dark in others, here and there blocked by mountains, like the face of a calm great ocean.', 'veda-app-ai-draft', true),
('ramayana-4-27-18', 'en', 'Mountain streams rush faster, carrying new water reddened by mountain minerals and mixed with sarja and kadamba flowers, followed by the cries of peacocks.', 'veda-app-ai-draft', true),
('ramayana-4-27-19', 'en', 'Juicy rose-apples, dark as bees, are eaten freely, and ripe mangoes of many colours, shaken by the wind, fall to the ground.', 'veda-app-ai-draft', true),
('ramayana-4-27-20', 'en', 'With lightning for banners and garlands of cranes, shaped like the peaks of great mountains, the clouds roar loudly like mad elephants in battle.', 'veda-app-ai-draft', true),
('ramayana-4-27-21', 'en', 'The line of cranes, longing for the clouds and flying joyfully, looks like a garland of fine white lotuses swaying in the wind, hung on the sky.', 'veda-app-ai-draft', true),
('ramayana-4-27-22', 'en', 'Sleep slowly comes to Keshava, the river quickly reaches the sea, the happy crane goes to the cloud, and the loving woman goes to her beloved.', 'veda-app-ai-draft', true),
('ramayana-4-27-23', 'en', 'The forests are alive with dancing peacocks, the kadambas are in bloom, the bulls share desire with the cows, and the earth is lovely with crops and woods.', 'veda-app-ai-draft', true),
('ramayana-4-27-24', 'en', 'The rivers flow, the clouds rain, the mad elephants trumpet, the forests shine, separated lovers brood, peacocks dance and monkeys take comfort.', 'veda-app-ai-draft', true),
('ramayana-4-27-25', 'en', 'Delighted by the scent of ketaki flowers, great elephants by the forest falls, deafened by the sound of the cascades, trumpet with the peacocks in their passion.', 'veda-app-ai-draft', true),
('ramayana-4-27-26', 'en', 'Beaten by the falling rain, hanging on kadamba branches, the bees slowly lose the intoxication they had just drawn deep from the flowers'' nectar.', 'veda-app-ai-draft', true),
('ramayana-4-27-27', 'en', 'The branches of the rose-apple trees, laden with ripe juicy fruit like heaps of charcoal, look as if covered with swarms of bees.', 'veda-app-ai-draft', true),
('ramayana-4-27-28', 'en', 'The clouds, adorned with lightning banners and roaring deep and loud, look like elephants ready for battle.', 'veda-app-ai-draft', true),
('ramayana-4-27-29', 'en', 'A mad elephant following the path through the mountain forests, hearing the thunder and thinking it a rival, eager to fight, turns back.', 'veda-app-ai-draft', true),
('ramayana-4-27-30', 'en', 'Thirsty birds with ruffled feathers joyfully drink the pearl-like rainwater caught in cups of leaves, a gift from the king of gods.', 'veda-app-ai-draft', true),
('ramayana-4-27-31', 'en', 'Dark clouds full of new rain cling to dark clouds and shine like burnt mountains rooted against burnt mountains.', 'veda-app-ai-draft', true),
('ramayana-4-27-32', 'en', 'Great elephants are in rut, bulls are happy, lions rest in the forests, the great mountains are lovely and quiet, and Indra plays with the clouds.', 'veda-app-ai-draft', true),
('ramayana-4-27-33', 'en', 'The kings'' campaigns are over and their armies turn back. The rains have made enmities and roads alike impassable.', 'veda-app-ai-draft', true),
('ramayana-4-27-34', 'en', 'In the month of Praushthapada, the season for study has come for brahmins wishing to recite the Veda and for the Sama singers.', 'veda-app-ai-draft', true),
('ramayana-4-27-35', 'en', 'Surely Bharata, lord of the treasury, having finished his work and gathered his stores, has begun the Ashadhi observance.', 'veda-app-ai-draft', true),
('ramayana-4-27-36', 'en', 'Surely the swelling Sarayu is rising in flood, its roar like Ayodhya''s on seeing me come home.', 'veda-app-ai-draft', true),
('ramayana-4-27-37', 'en', 'Sugriva enjoys these rich rains in comfort, his enemy conquered, with his wife, settled in a great kingdom.', 'veda-app-ai-draft', true),
('ramayana-4-27-38', 'en', 'But I, my wife taken and fallen from a great kingdom, sink like a soaked riverbank, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-27-39', 'en', 'My grief is vast, the rains make travel very hard, and Ravana is a great enemy. It all seems endless to me.', 'veda-app-ai-draft', true),
('ramayana-4-27-40', 'en', 'Seeing that this is no time to march and that the roads are very hard, I said nothing to Sugriva, though he bowed to me.', 'veda-app-ai-draft', true),
('ramayana-4-27-41', 'en', 'He has suffered greatly and is reunited with his wife after long. Though my own task weighs heavy, I do not wish to press the monkey.', 'veda-app-ai-draft', true),
('ramayana-4-27-42', 'en', 'Having rested and knowing that the time has come, Sugriva will himself remember the help he received. There is no doubt of that.', 'veda-app-ai-draft', true),
('ramayana-4-27-43', 'en', 'So I wait for the right time, auspicious one, waiting for Sugriva''s goodwill and for the rivers to clear.', 'veda-app-ai-draft', true),
('ramayana-4-27-44', 'en', 'A hero who is helped is bound to help in return. One who is ungrateful and does not repay wounds the hearts of the noble.', 'veda-app-ai-draft', true),
('ramayana-4-27-45', 'en', 'Told this, Lakshmana, with folded hands, reflected, honoured what was said, and spoke to Rama of lovely appearance, showing his own good insight.', 'veda-app-ai-draft', true),
('ramayana-4-27-46', 'en', 'Lord of men, the monkey king will soon do all you wish, as you have said. Waiting for autumn, bear this rainy season, firm in your resolve to subdue the enemy.', 'veda-app-ai-draft', true),
('ramayana-4-28-1', 'en', 'Seeing the clear sky free of lightning and clouds, ringing with the calls of cranes and bathed in lovely moonlight,', 'veda-app-ai-draft', true),
('ramayana-4-28-2', 'en', 'and Sugriva, his wealth secure but careless in gathering dharma and wealth, given far to the ways of the unworthy, his mind set on private pleasure,', 'veda-app-ai-draft', true),
('ramayana-4-28-3', 'en', 'his work done, his aims achieved, always enjoying the company of women, having gained all the desires he wished for,', 'veda-app-ai-draft', true),
('ramayana-4-28-4', 'en', 'sporting day and night with his beloved wife and with Tara whom he also desired, satisfied and free of anxiety,', 'veda-app-ai-draft', true),
('ramayana-4-28-5', 'en', 'playing like the lord of gods in Nandana with troops of apsaras, leaving affairs to his ministers and not overseeing them,', 'veda-app-ai-draft', true),
('ramayana-4-28-6', 'en', 'the business of the kingdom neglected, living by desire, Hanuman, who was sure of the facts, knew the truth of things and the special duties of the season,', 'veda-app-ai-draft', true),
('ramayana-4-28-7', 'en', 'the son of the Wind, skilled in speech, pleased the monkey king, who knew the truth of words, with sweet, reasoned and charming words.', 'veda-app-ai-draft', true),
('ramayana-4-28-8', 'en', 'Going to the monkey king, Hanuman spoke words that were beneficial, true and wholesome, full of conciliation, dharma, profit and policy, joined with affection and resolved in trust.', 'veda-app-ai-draft', true),
('ramayana-4-28-9', 'en', 'You have gained the kingdom and fame, and your family''s fortune has grown. What remains is to secure your friends, and you should do it.', 'veda-app-ai-draft', true),
('ramayana-4-28-10', 'en', 'Whoever always behaves well toward friends and knows the right time, his kingdom, fame and power grow.', 'veda-app-ai-draft', true),
('ramayana-4-28-11', 'en', 'The king whose treasury, army, friends and self all work together enjoys a great kingdom, lord of the earth.', 'veda-app-ai-draft', true),
('ramayana-4-28-12', 'en', 'So you, rich in good conduct and standing on the safe path, should do properly what your friend needs.', 'veda-app-ai-draft', true),
('ramayana-4-28-13', 'en', 'But one who attends to a friend''s affairs after the time has passed gains no credit with that friend, even if he does great things.', 'veda-app-ai-draft', true),
('ramayana-4-28-14', 'en', 'Let the search for Vaidehi be made for Raghava. This task of yours, hero, is already past its time, subduer of enemies.', 'veda-app-ai-draft', true),
('ramayana-4-28-15', 'en', 'Though he knows the time and is in a hurry, the wise Rama does not tell you the time has passed, king, for he defers to your will.', 'veda-app-ai-draft', true),
('ramayana-4-28-16', 'en', 'Raghava is the banner of a flourishing family, a lasting friend, of immeasurable power and himself without equal in virtues.', 'veda-app-ai-draft', true),
('ramayana-4-28-17', 'en', 'Do his work, since he did yours first. Lord of monkeys, you should command the best monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-28-18', 'en', 'The time is not yet lost if you act without being urged. But if the task must be urged, the time will have passed.', 'veda-app-ai-draft', true),
('ramayana-4-28-19', 'en', 'You would help even someone who had never helped you, lord of monkeys. How much more him who gave you the kingdom and wealth!', 'veda-app-ai-draft', true),
('ramayana-4-28-20', 'en', 'You are able and brave, lord of the monkey and bear hosts. Why do you hesitate to command what will please the son of Dasharatha?', 'veda-app-ai-draft', true),
('ramayana-4-28-21', 'en', 'Dasharatha''s son could bring gods, demons and great serpents under his control with his arrows, but he waits for you to keep your promise.', 'veda-app-ai-draft', true),
('ramayana-4-28-22', 'en', 'Without hesitating to risk his life, he did what you wanted. Let us search for Vaidehi on earth and in the sky.', 'veda-app-ai-draft', true),
('ramayana-4-28-23', 'en', 'Neither gods, gandharvas, asuras, maruts nor yakshas can make him afraid, let alone rakshasas.', 'veda-app-ai-draft', true),
('ramayana-4-28-24', 'en', 'So you should do everything to please Rama, who is so powerful and who first did you a kindness, tawny lord.', 'veda-app-ai-draft', true),
('ramayana-4-28-25', 'en', 'Under your command, lord of monkeys, none of us is held back from going below the earth, into the waters, or up into the sky.', 'veda-app-ai-draft', true),
('ramayana-4-28-26', 'en', 'So command who should go where and what each should do for you. You have more than ten million unassailable monkeys, sinless one.', 'veda-app-ai-draft', true),
('ramayana-4-28-27', 'en', 'Hearing his words, well spoken at the right time, Sugriva, strong in character, made a fine decision.', 'veda-app-ai-draft', true),
('ramayana-4-28-28', 'en', 'He ordered Nila, ever active, whom he valued, to gather all the troops from every direction.', 'veda-app-ai-draft', true),
('ramayana-4-28-29', 'en', 'Make sure my whole army and all the troop leaders come together without delay, with the vanguards.', 'veda-app-ai-draft', true),
('ramayana-4-28-30', 'en', 'Let the swift and resolute monkeys guarding the borders quickly bring in the troops at my command, and you yourself then inspect the army.', 'veda-app-ai-draft', true),
('ramayana-4-28-31', 'en', 'Any monkey who does not arrive here within fifteen nights shall be put to death. There is no need for discussion.', 'veda-app-ai-draft', true),
('ramayana-4-28-32', 'en', 'With Angada, go to the elder monkeys under my firm command. Having made these arrangements, the mighty lord of monkey chiefs entered his palace.', 'veda-app-ai-draft', true),
('ramayana-4-29-1', 'en', 'When Sugriva had gone into the cave and the sky was free of clouds, Rama, having spent the rainy season there, was tormented by longing and grief.', 'veda-app-ai-draft', true),
('ramayana-4-29-2', 'en', 'Seeing the pale sky and the clear disc of the moon, and seeing the autumn night bathed in moonlight,', 'veda-app-ai-draft', true),
('ramayana-4-29-3', 'en', 'and realising that Sugriva was living for pleasure, that Janaka''s daughter was lost and the time had passed, he fainted in great distress.', 'veda-app-ai-draft', true),
('ramayana-4-29-4', 'en', 'Regaining consciousness after a moment, wise Raghava thought again of Vaidehi, who lived in his heart.', 'veda-app-ai-draft', true),
('ramayana-4-29-5', 'en', 'Sitting on the mountain top adorned with golden minerals, seeing the autumn sky, he went in his mind to his beloved.', 'veda-app-ai-draft', true),
('ramayana-4-29-6', 'en', 'Seeing the clear sky without lightning or clouds, ringing with the calls of cranes, he lamented in a pained voice:', 'veda-app-ai-draft', true),
('ramayana-4-29-7', 'en', 'She who once delighted in the hermitage with the cries of cranes, herself speaking like a crane, how does that young girl find delight now?', 'veda-app-ai-draft', true),
('ramayana-4-29-8', 'en', 'Seeing the flowering asana trees bright as pure gold, how can that young girl be happy, looking for me and not seeing me?', 'veda-app-ai-draft', true),
('ramayana-4-29-9', 'en', 'She who used to wake to the voices of the kalahamsa geese, sweet-voiced and lovely in every limb, how does she wake now?', 'veda-app-ai-draft', true),
('ramayana-4-29-10', 'en', 'Hearing the calls of chakravakas wandering with their mates, how will the lotus-eyed one be?', 'veda-app-ai-draft', true),
('ramayana-4-29-11', 'en', 'Wandering among lakes, rivers, ponds, woods and forests without that fawn-eyed one, I find no happiness today.', 'veda-app-ai-draft', true),
('ramayana-4-29-12', 'en', 'Surely longing, heightened by the beauty of autumn, will torment that lovely one, delicate as she is and parted from me.', 'veda-app-ai-draft', true),
('ramayana-4-29-13', 'en', 'So the prince, best of men, lamented, like the saranga bird crying to Indra for water.', 'veda-app-ai-draft', true),
('ramayana-4-29-14', 'en', 'Then glorious Lakshmana, who had been wandering the lovely mountain slopes looking for fruit, returned and saw his elder brother.', 'veda-app-ai-draft', true),
('ramayana-4-29-15', 'en', 'Seeing him alone in that lonely place, overcome by unbearable worry and senseless, high-minded Lakshmana, saddened by his brother''s grief, spoke to Rama.', 'veda-app-ai-draft', true),
('ramayana-4-29-16', 'en', 'Noble brother, what good is giving in to longing and defeating your own manliness? Your composure is always being stolen away. What use is giving up your discipline?', 'veda-app-ai-draft', true),
('ramayana-4-29-17', 'en', 'Take up action, calm your mind, use your time in steady focus, rely on your allies'' strength, and with an undaunted spirit make your own effort the cause of success.', 'veda-app-ai-draft', true),
('ramayana-4-29-18', 'en', 'Lord of the human race, with you as her protector Janaki cannot easily be held by another. No one, best of heroes, touches a blazing flame and is not burned.', 'veda-app-ai-draft', true),
('ramayana-4-29-19', 'en', 'Rama spoke to Lakshmana, auspicious and unassailable, words from his own nature, beneficial, wholesome, full of policy, conciliation, dharma and purpose.', 'veda-app-ai-draft', true),
('ramayana-4-29-20', 'en', 'Without doubt the task must be looked to and the right action followed. One should not brood over the fruit of a hard task already begun.', 'veda-app-ai-draft', true),
('ramayana-4-29-21', 'en', 'Then, thinking of lotus-eyed Maithili, Rama spoke to Lakshmana with a drying face:', 'veda-app-ai-draft', true),
('ramayana-4-29-22', 'en', 'Thousand-eyed Indra, having satisfied the earth with water and ripened the crops, has finished his work and rests.', 'veda-app-ai-draft', true),
('ramayana-4-29-23', 'en', 'The clouds with their deep, soft rumble, which went ahead of mountains and trees, have released their water and are tired, prince.', 'veda-app-ai-draft', true),
('ramayana-4-29-24', 'en', 'The clouds, dark as blue lily petals, having darkened the ten directions, are now calm like elephants whose rut is over.', 'veda-app-ai-draft', true),
('ramayana-4-29-25', 'en', 'The rain winds, heavy with water and swift, scented with kutaja and arjuna, have blown and now ceased, gentle one.', 'veda-app-ai-draft', true),
('ramayana-4-29-26', 'en', 'The sound of clouds, elephants, peacocks and waterfalls has suddenly fallen silent, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-29-27', 'en', 'Washed by the great clouds, the mountains with their colourful slopes are clean and shine as if smeared with moonbeams.', 'veda-app-ai-draft', true),
('ramayana-4-29-28', 'en', 'The autumn rivers slowly reveal their sandbanks, like shy young brides.', 'veda-app-ai-draft', true),
('ramayana-4-29-29', 'en', 'The lakes with clear water shine, gentle one, ringing with ospreys and crowded with flocks of chakravakas.', 'veda-app-ai-draft', true),
('ramayana-4-29-30', 'en', 'The season for campaigns has come for kings bent on conquest and bound in mutual enmity, prince.', 'veda-app-ai-draft', true),
('ramayana-4-29-31', 'en', 'This is the first season for kings to march, prince, yet I do not see Sugriva or any such effort.', 'veda-app-ai-draft', true),
('ramayana-4-29-32', 'en', 'The four months of rain have passed like a hundred years for me, burning with grief, not seeing Sita, gentle one.', 'veda-app-ai-draft', true),
('ramayana-4-29-33', 'en', 'King Sugriva shows no pity for me, Lakshmana, though I am without my beloved, in pain, robbed of my kingdom and exiled.', 'veda-app-ai-draft', true),
('ramayana-4-29-34', 'en', 'Thinking: He is helpless, robbed of his kingdom, insulted by Ravana, wretched, far from home, longing, and has come to me for refuge.', 'veda-app-ai-draft', true),
('ramayana-4-29-35', 'en', 'For these reasons, gentle one, I am slighted by the wicked monkey king Sugriva, scorcher of foes.', 'veda-app-ai-draft', true),
('ramayana-4-29-36', 'en', 'Having fixed the time for the search for Sita and made a pact, now that he has what he wants, the fool does not remember.', 'veda-app-ai-draft', true),
('ramayana-4-29-37', 'en', 'Go into Kishkindha and tell Sugriva, that foolish monkey attached to vulgar pleasures, from me:', 'veda-app-ai-draft', true),
('ramayana-4-29-38', 'en', 'Whoever raises the hopes of those who come asking, especially of those who helped him first, and then destroys them, is the lowest of men in the world.', 'veda-app-ai-draft', true),
('ramayana-4-29-39', 'en', 'Whoever holds to the word he has spoken with truth, whether it turns out good or bad, is a hero and the best of men.', 'veda-app-ai-draft', true),
('ramayana-4-29-40', 'en', 'Those who, having got what they want, do not help friends who have not, are ungrateful. Even flesh-eaters will not eat them when they are dead.', 'veda-app-ai-draft', true),
('ramayana-4-29-41', 'en', 'Surely he wants to see again my gold-backed bow drawn in battle, flashing like a mass of lightning.', 'veda-app-ai-draft', true),
('ramayana-4-29-42', 'en', 'He wants to hear again the terrible twang of my bowstring in battle when I am angry, like the crash of a thunderbolt.', 'veda-app-ai-draft', true),
('ramayana-4-29-43', 'en', 'Even now, knowing my valour, with you as my ally, hero, I should not have to worry, prince.', 'veda-app-ai-draft', true),
('ramayana-4-29-44', 'en', 'The monkey king, having got what he wanted, does not remember the pact for whose sake this undertaking was made, conqueror of enemy cities.', 'veda-app-ai-draft', true),
('ramayana-4-29-45', 'en', 'Having promised the end of the rainy season, the lord of monkeys, enjoying himself, does not notice the four months have passed.', 'veda-app-ai-draft', true),
('ramayana-4-29-46', 'en', 'Playing with his ministers and assembly, he does nothing but drink. Sugriva shows no pity for us who are wretched with grief.', 'veda-app-ai-draft', true),
('ramayana-4-29-47', 'en', 'Go, mighty child, and speak to Sugriva. Tell him what my anger looks like, and say these words:', 'veda-app-ai-draft', true),
('ramayana-4-29-48', 'en', 'The road Vali took when he was killed has not closed. Keep to your pact, Sugriva. Do not follow Vali''s path.', 'veda-app-ai-draft', true),
('ramayana-4-29-49', 'en', 'Vali alone was killed by my arrow in battle. But you, if you stray from truth, I will kill with your kin.', 'veda-app-ai-draft', true),
('ramayana-4-29-50', 'en', 'So, best of men, now that the task is set, say whatever is best. Hurry, the time is passing.', 'veda-app-ai-draft', true),
('ramayana-4-29-51', 'en', 'Keep the promise you made me, lord of monkeys, mindful of eternal dharma, or today you may follow Vali to Yama''s realm, driven by my arrows.', 'veda-app-ai-draft', true),
('ramayana-4-29-52', 'en', 'Seeing his elder brother in fierce, swelling anger and lamenting wretchedly, fiery Lakshmana made a fierce resolve about the monkey king.', 'veda-app-ai-draft', true),
('ramayana-4-30-1', 'en', 'Rama''s younger brother, undaunted in spirit, spoke to his elder brother, son of a king, who was longing, wretched, stricken with grief and swelling with anger:', 'veda-app-ai-draft', true),
('ramayana-4-30-2', 'en', 'The monkey will not keep to good conduct, will not think of the results of his duties, and will not enjoy the monkey kingdom''s fortune, for his mind does not go that way.', 'veda-app-ai-draft', true),
('ramayana-4-30-3', 'en', 'His judgement gone, attached to vulgar pleasures, with no thought of repaying your kindness, let him be killed and see his brother Vali. A kingdom should not be given to one so worthless.', 'veda-app-ai-draft', true),
('ramayana-4-30-4', 'en', 'I cannot hold back this rising anger. I will kill lying Sugriva today. Let Vali''s son with the monkey heroes search for the king''s wife.', 'veda-app-ai-draft', true),
('ramayana-4-30-5', 'en', 'As he rose, bow in hand, his purpose declared and fierce in battle-anger, Rama, slayer of enemy heroes, spoke to him with careful and soothing words:', 'veda-app-ai-draft', true),
('ramayana-4-30-6', 'en', 'One like you in the world should not do such a wrong. A hero who overcomes wrong through nobility is the best of men.', 'veda-app-ai-draft', true),
('ramayana-4-30-7', 'en', 'You, so good in conduct, should not take this view today, Lakshmana. Keep to the old affection and the friendship made before.', 'veda-app-ai-draft', true),
('ramayana-4-30-8', 'en', 'Avoiding harsh words, speaking conciliating words, you should tell Sugriva that the appointed time has passed.', 'veda-app-ai-draft', true),
('ramayana-4-30-9', 'en', 'Instructed properly by his elder brother, heroic Lakshmana, bull among men and slayer of enemy heroes, entered the city.', 'veda-app-ai-draft', true),
('ramayana-4-30-10', 'en', 'Then wise, good-minded Lakshmana, devoted to his brother''s welfare, went angrily to the monkey''s palace.', 'veda-app-ai-draft', true),
('ramayana-4-30-11', 'en', 'Holding a bow like Indra''s rainbow, he looked like Death at the end of time, like Mount Mandara with its ridges and a mountain peak.', 'veda-app-ai-draft', true),
('ramayana-4-30-12', 'en', 'Doing as he was told, and thinking over his words and the replies to them, Rama''s brother, equal to Brihaspati in wisdom, went on.', 'veda-app-ai-draft', true),
('ramayana-4-30-13', 'en', 'Filled with the fire of his brother''s anger born of longing and wrath, Lakshmana went on, displeased like a storm wind.', 'veda-app-ai-draft', true),
('ramayana-4-30-14', 'en', 'Forcefully knocking down many sal, palm and ashvakarna trees, hurling aside mountain peaks and other trees as he went,', 'veda-app-ai-draft', true),
('ramayana-4-30-15', 'en', 'smashing rocks with his feet like a swift elephant, taking long strides, he hurried on because of his task.', 'veda-app-ai-draft', true),
('ramayana-4-30-16', 'en', 'The tiger of the Ikshvakus saw the great city of the monkey king, Kishkindha, crowded with troops and hard to reach in a mountain gorge.', 'veda-app-ai-draft', true),
('ramayana-4-30-17', 'en', 'His lips trembling with anger at Sugriva, Lakshmana saw the fearsome monkeys moving outside Kishkindha.', 'veda-app-ai-draft', true),
('ramayana-4-30-18', 'en', 'The monkeys, huge as elephants, seized hundreds of mountain peaks and tall trees in the mountain valley.', 'veda-app-ai-draft', true),
('ramayana-4-30-19', 'en', 'Seeing the monkeys holding weapons, Lakshmana grew twice as angry, like a fire with much fuel.', 'veda-app-ai-draft', true),
('ramayana-4-30-20', 'en', 'Seeing him angry, like Death at the end of an age, the monkeys, their limbs gripped by fear, fled by hundreds in all directions.', 'veda-app-ai-draft', true),
('ramayana-4-30-21', 'en', 'Then the chief monkeys entered Sugriva''s palace and reported Lakshmana''s anger and arrival.', 'veda-app-ai-draft', true),
('ramayana-4-30-22', 'en', 'The lustful monkey king, absorbed with Tara in private, did not hear the words of those monkey heroes.', 'veda-app-ai-draft', true),
('ramayana-4-30-23', 'en', 'Then, at the ministers'' command, the hair-raising monkeys, like mountains, elephants and clouds, went out of the city.', 'veda-app-ai-draft', true),
('ramayana-4-30-24', 'en', 'Armed with nails and fangs, fearsome and grotesque in look, all proud as tigers and with fierce faces,', 'veda-app-ai-draft', true),
('ramayana-4-30-25', 'en', 'some had the strength of ten elephants, some ten times more, some equal in might to a thousand elephants.', 'veda-app-ai-draft', true),
('ramayana-4-30-26', 'en', 'Angry Lakshmana saw all of Kishkindha, hard to approach, filled with mighty monkeys holding trees in their hands.', 'veda-app-ai-draft', true),
('ramayana-4-30-27', 'en', 'Then all the monkeys came out from between the wall and the moat and stood openly, spirited.', 'veda-app-ai-draft', true),
('ramayana-4-30-28', 'en', 'Knowing Sugriva''s negligence and his elder brother''s pain, the self-possessed hero, overcome by anger, went on again.', 'veda-app-ai-draft', true),
('ramayana-4-30-29', 'en', 'Breathing long, hot, heavy breaths, his eyes red with anger, the tiger among men was like a fire with smoke.', 'veda-app-ai-draft', true),
('ramayana-4-30-30', 'en', 'With arrows for his flickering tongue and his bow for his coils, a mass of the venom of his own fire, he was like a five-headed serpent.', 'veda-app-ai-draft', true),
('ramayana-4-30-31', 'en', 'Coming upon him, blazing like the fire of doom and angry as a serpent king, Angada fell into deep dismay from fear.', 'veda-app-ai-draft', true),
('ramayana-4-30-32', 'en', 'The famous one, his eyes red with rage, instructed Angada: Let Sugriva be told of my arrival, child.', 'veda-app-ai-draft', true),
('ramayana-4-30-33', 'en', 'Say: Rama''s younger brother Lakshmana, subduer of enemies, has come to you, troubled by his brother''s distress, and stands at the gate.', 'veda-app-ai-draft', true),
('ramayana-4-30-34', 'en', 'Hearing Lakshmana''s words, grief-stricken Angada went to his uncle and said: Lakshmana has come.', 'veda-app-ai-draft', true),
('ramayana-4-30-35', 'en', 'Seeing Lakshmana like a great flood and with a voice like a thunderbolt, the monkeys near him all roared a lion''s roar together.', 'veda-app-ai-draft', true),
('ramayana-4-30-36', 'en', 'At that great sound the monkey woke, his eyes red and unsteady with drink, his garlands and ornaments in disarray.', 'veda-app-ai-draft', true),
('ramayana-4-30-37', 'en', 'Then, hearing Angada''s words and coming with him, two ministers of the monkey king, respected and far-sighted,', 'veda-app-ai-draft', true),
('ramayana-4-30-38', 'en', 'Plaksha and Prabhava, ministers for policy and dharma, told him of Lakshmana''s arrival, to speak of matters high and low.', 'veda-app-ai-draft', true),
('ramayana-4-30-39', 'en', 'Having calmed Sugriva with words settled in conciliation, they sat by him as the Maruts by Indra.', 'veda-app-ai-draft', true),
('ramayana-4-30-40', 'en', 'The two brothers Rama and Lakshmana, true to their word and noble, have become your friends, worthy of kingship and givers of kingship.', 'veda-app-ai-draft', true),
('ramayana-4-30-41', 'en', 'One of them, Lakshmana, bow in hand, stands at the gate. The monkeys tremble in fear of him and cry out.', 'veda-app-ai-draft', true),
('ramayana-4-30-42', 'en', 'This Lakshmana, Raghava''s brother, with words as his charioteer and resolve as his chariot, has come at Rama''s command.', 'veda-app-ai-draft', true),
('ramayana-4-30-43', 'en', 'Bow your head to him with your son and kin, king. Keep to your pact and be true to your promise.', 'veda-app-ai-draft', true),
('ramayana-4-31-1', 'en', 'Hearing Angada''s words and that Lakshmana was angry, self-possessed Sugriva and his ministers rose from their seats.', 'veda-app-ai-draft', true),
('ramayana-4-31-2', 'en', 'Skilled in counsel and settled in deliberation, having weighed what was serious and what was slight, he spoke to his ministers who knew counsel:', 'veda-app-ai-draft', true),
('ramayana-4-31-3', 'en', 'I have said nothing wrong and done nothing wrong. I wonder why Lakshmana, Raghava''s brother, is angry.', 'veda-app-ai-draft', true),
('ramayana-4-31-4', 'en', 'Unfriendly enemies of mine, always looking for weak points, must have told Raghava''s brother of faults I do not have.', 'veda-app-ai-draft', true),
('ramayana-4-31-5', 'en', 'Here, all of you, use your judgement properly and find out carefully and slowly what he intends.', 'veda-app-ai-draft', true),
('ramayana-4-31-6', 'en', 'I have no fear of Lakshmana or Raghava. But a friend angered without cause does cause alarm.', 'veda-app-ai-draft', true),
('ramayana-4-31-7', 'en', 'Making a friend is easy in every way; keeping one is hard. Because minds are changeable, affection breaks over even a little thing.', 'veda-app-ai-draft', true),
('ramayana-4-31-8', 'en', 'That is why I am afraid of great Rama, for I cannot repay the help he gave me.', 'veda-app-ai-draft', true),
('ramayana-4-31-9', 'en', 'When Sugriva said this, Hanuman, chief of monkeys, spoke his own reasoning among the monkey ministers.', 'veda-app-ai-draft', true),
('ramayana-4-31-10', 'en', 'It is no wonder at all, lord of the monkey hosts, that you do not forget the loving, good help you received.', 'veda-app-ai-draft', true),
('ramayana-4-31-11', 'en', 'For your sake heroic Raghava, casting fear far away, killed Vali, equal to Indra in valour.', 'veda-app-ai-draft', true),
('ramayana-4-31-12', 'en', 'No doubt Raghava is angry out of affection. He has sent his brother Lakshmana, who increases fortune.', 'veda-app-ai-draft', true),
('ramayana-4-31-13', 'en', 'Careless, you do not see the time, best of those who know time. The lovely autumn has begun, dark with blooming saptachchada trees.', 'veda-app-ai-draft', true),
('ramayana-4-31-14', 'en', 'The sky is clear of clouds, the planets and stars are bright, and all directions, rivers and lakes are clear.', 'veda-app-ai-draft', true),
('ramayana-4-31-15', 'en', 'You do not know that the time for action has come, chief of monkeys. Clearly you are careless, and so Lakshmana has come here.', 'veda-app-ai-draft', true),
('ramayana-4-31-16', 'en', 'You should bear even harsh words from great Raghava, spoken through another, for he is in pain and his wife was taken.', 'veda-app-ai-draft', true),
('ramayana-4-31-17', 'en', 'Since you are at fault, I see nothing fitting except to fold your hands and win Lakshmana''s goodwill.', 'veda-app-ai-draft', true),
('ramayana-4-31-18', 'en', 'Ministers appointed must surely tell the king what is good. So, putting fear aside, I speak firm words.', 'veda-app-ai-draft', true),
('ramayana-4-31-19', 'en', 'When angered, Raghava, lifting his bow, could bring the whole world with gods, asuras and gandharvas under his control.', 'veda-app-ai-draft', true),
('ramayana-4-31-20', 'en', 'One whom you must win back later is not one to anger, especially for a grateful person who remembers past help.', 'veda-app-ai-draft', true),
('ramayana-4-31-21', 'en', 'Bow your head to him with your son and friends, king, and keep to your pact, under his will as a wife under her husband''s.', 'veda-app-ai-draft', true),
('ramayana-4-31-22', 'en', 'You should not set aside, even in thought, the command of Rama and his brother, given to the monkey king. Your mind knows the human strength of Raghava, bright as the king of gods.', 'veda-app-ai-draft', true),
('ramayana-4-32-1', 'en', 'Then, having been invited in, Lakshmana, slayer of enemy heroes, entered the fearsome cave city of Kishkindha at Rama''s command.', 'veda-app-ai-draft', true),
('ramayana-4-32-2', 'en', 'The huge, mighty monkeys at the gate all stood with folded hands when they saw Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-32-3', 'en', 'Seeing Dasharatha''s son angry and breathing hard, the monkeys were afraid and did not surround him.', 'veda-app-ai-draft', true),
('ramayana-4-32-4', 'en', 'Glorious Lakshmana saw that great cave, made of jewels, heavenly, with flowering groves, lovely and strewn with gems.', 'veda-app-ai-draft', true),
('ramayana-4-32-5', 'en', 'It was crowded with mansions and palaces, bright with many goods, and adorned with flowering trees bearing every desired fruit.', 'veda-app-ai-draft', true),
('ramayana-4-32-6', 'en', 'It was graced by shape-shifting monkeys, sons of gods and gandharvas, handsome and wearing heavenly garlands and clothes.', 'veda-app-ai-draft', true),
('ramayana-4-32-7', 'en', 'Its great roads were fragrant with sandal, agaru and lotus, and with the scent of wines and honeyed drinks.', 'veda-app-ai-draft', true),
('ramayana-4-32-8', 'en', 'Raghava''s brother saw palaces of many storeys like the slopes of the Vindhya and Meru, and clear mountain streams there.', 'veda-app-ai-draft', true),
('ramayana-4-32-9', 'en', 'The lovely homes of Angada, Mainda and Dvivida, of Gavaya, Gavaksha, Gaja and Sharabha,', 'veda-app-ai-draft', true),
('ramayana-4-32-10', 'en', 'of Vidyunmali, Sampati, Suryaksha and Hanuman, of Virabahu, Subahu and great Nala,', 'veda-app-ai-draft', true),
('ramayana-4-32-11', 'en', 'of Kumuda, Sushena, Tara and Jambavan, of Dadhivaktra, Nila, Supatala and Sunetra.', 'veda-app-ai-draft', true),
('ramayana-4-32-12', 'en', 'Lakshmana saw the fine, solid mansions of these great monkey chiefs along the royal road.', 'veda-app-ai-draft', true),
('ramayana-4-32-13', 'en', 'They shone like white clouds, hung with heavenly garlands, rich in wealth and grain, and graced with fine women.', 'veda-app-ai-draft', true),
('ramayana-4-32-14', 'en', 'The monkey king''s lovely palace, hard to approach, was surrounded by a white rock wall, like the mansion of great Indra.', 'veda-app-ai-draft', true),
('ramayana-4-32-15', 'en', 'It was graced with white palace towers like the peaks of Kailasa and with flowering trees bearing every desired fruit.', 'veda-app-ai-draft', true),
('ramayana-4-32-16', 'en', 'with glorious trees given by great Indra, dark as blue clouds, with heavenly flowers and fruits, cool shade and charm,', 'veda-app-ai-draft', true),
('ramayana-4-32-17', 'en', 'its gate guarded by strong monkeys with weapons in hand, bright, hung with heavenly garlands, with a gateway of refined gold.', 'veda-app-ai-draft', true),
('ramayana-4-32-18', 'en', 'Mighty Lakshmana entered Sugriva''s lovely palace unhindered, like the sun entering a great cloud.', 'veda-app-ai-draft', true),
('ramayana-4-32-19', 'en', 'Passing through seven courtyards filled with carriages and seats, righteous Lakshmana saw the great, well-guarded inner apartments.', 'veda-app-ai-draft', true),
('ramayana-4-32-20', 'en', 'It was adorned here and there with many gold and silver couches and fine seats with costly covers.', 'veda-app-ai-draft', true),
('ramayana-4-32-21', 'en', 'As he entered he heard a constant sweet sound, full of stringed music and singing, with syllables and words in harmony.', 'veda-app-ai-draft', true),
('ramayana-4-32-22', 'en', 'Mighty Lakshmana saw many women of many kinds in Sugriva''s palace, proud of their beauty and youth.', 'veda-app-ai-draft', true),
('ramayana-4-32-23', 'en', 'He saw them of noble birth, wearing colourful garlands, busy making fine garlands, adorned with the best ornaments.', 'veda-app-ai-draft', true),
('ramayana-4-32-24', 'en', 'Lakshmana also noticed Sugriva''s attendants, none unsatisfied, none overly busy, none poorly dressed.', 'veda-app-ai-draft', true),
('ramayana-4-32-25', 'en', 'Then he saw Sugriva seated on a fine golden throne with a costly cover, shining like the sun,', 'veda-app-ai-draft', true),
('ramayana-4-32-26', 'en', 'his limbs bright with heavenly ornaments, divine in form and famous, wearing heavenly garlands and clothes, unconquerable like great Indra, surrounded by women with heavenly jewels and garlands.', 'veda-app-ai-draft', true),
('ramayana-4-32-27', 'en', 'The hero, golden in colour, seated on a fine seat and holding Ruma tightly, with wide eyes looked at wide-eyed Lakshmana, undaunted in spirit.', 'veda-app-ai-draft', true),
('ramayana-4-33-1', 'en', 'Seeing Lakshmana, the bull among men, angry and entered without hindrance, Sugriva''s senses were shaken.', 'veda-app-ai-draft', true),
('ramayana-4-33-2', 'en', 'Seeing Dasharatha''s son angry and breathing hard, as if blazing with fire, burning over his brother''s distress,', 'veda-app-ai-draft', true),
('ramayana-4-33-3', 'en', 'the best of monkeys sprang up, leaving his golden seat, like Indra''s great well-decorated banner.', 'veda-app-ai-draft', true),
('ramayana-4-33-4', 'en', 'Ruma and the other women sprang up after Sugriva as he rose, like stars after the full moon in the sky.', 'veda-app-ai-draft', true),
('ramayana-4-33-5', 'en', 'Glorious, his eyes reddened, he came forward with folded hands and stood there like a great wish-granting tree.', 'veda-app-ai-draft', true),
('ramayana-4-33-6', 'en', 'Angry Lakshmana spoke to Sugriva, standing among the women with Ruma, like the moon with the stars:', 'veda-app-ai-draft', true),
('ramayana-4-33-7', 'en', 'A king who is strong in character and birth, compassionate, master of his senses, grateful and truthful, is honoured in the world.', 'veda-app-ai-draft', true),
('ramayana-4-33-8', 'en', 'But a king who, standing in unrighteousness, makes false promises to friends who helped him, who is crueller than he?', 'veda-app-ai-draft', true),
('ramayana-4-33-9', 'en', 'A man kills a hundred by lying about a horse, a thousand by lying about a cow, and himself and his kin by lying about a man.', 'veda-app-ai-draft', true),
('ramayana-4-33-10', 'en', 'Whoever, having first got what he wanted from friends, does not repay them is ungrateful and deserves death from all beings, lord of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-33-11', 'en', 'This verse was sung by Brahma, honoured by all the worlds, when he angrily saw an ungrateful person. Hear it, monkey.', 'veda-app-ai-draft', true),
('ramayana-4-33-12', 'en', 'For the killer of a brahmin, a drinker of liquor, a thief and one who breaks vows, the good have set out atonements. For the ungrateful there is no atonement.', 'veda-app-ai-draft', true),
('ramayana-4-33-13', 'en', 'You are ignoble, ungrateful and a liar, monkey, since having got your aim first from Rama, you do not repay him.', 'veda-app-ai-draft', true),
('ramayana-4-33-14', 'en', 'Surely, monkey, having gained your aim through Rama, you should strive to search for Sita, wishing to repay what was done.', 'veda-app-ai-draft', true),
('ramayana-4-33-15', 'en', 'But you, attached to vulgar pleasures and false in your promise, Rama does not see you for what you are: a snake croaking like a frog.', 'veda-app-ai-draft', true),
('ramayana-4-33-16', 'en', 'You, wicked and evil-minded, were given the monkey kingdom by noble, compassionate, great-souled Rama.', 'veda-app-ai-draft', true),
('ramayana-4-33-17', 'en', 'If you do not recognise what Rama, tireless in action, has done, you will soon see Vali, killed by sharp arrows.', 'veda-app-ai-draft', true),
('ramayana-4-33-18', 'en', 'The road Vali took when he was killed is not closed. Keep to your pact, Sugriva. Do not follow Vali''s path.', 'veda-app-ai-draft', true),
('ramayana-4-33-19', 'en', 'Surely you do not see the thunderbolt-like arrows released from the bow of the best of the Ikshvakus. So you live at ease in pleasure and do not even think of Rama''s task.', 'veda-app-ai-draft', true),
('ramayana-4-34-1', 'en', 'As Lakshmana spoke, blazing with fire, moon-faced Tara spoke to him:', 'veda-app-ai-draft', true),
('ramayana-4-34-2', 'en', 'Lakshmana, he should not be spoken to like this. The lord of monkeys does not deserve to hear harsh words, especially from your mouth.', 'veda-app-ai-draft', true),
('ramayana-4-34-3', 'en', 'Sugriva is not ungrateful, not deceitful, not cruel, not a liar and not crooked, hero.', 'veda-app-ai-draft', true),
('ramayana-4-34-4', 'en', 'This heroic monkey Sugriva has not forgotten the help Rama gave him in battle, which others could not have done.', 'veda-app-ai-draft', true),
('ramayana-4-34-5', 'en', 'By Rama''s grace Sugriva has gained fame, the lasting monkey kingdom, Ruma and me, scorcher of foes.', 'veda-app-ai-draft', true),
('ramayana-4-34-6', 'en', 'Having suffered greatly before and now gained this great happiness, he did not notice the time had come, like the sage Vishvamitra.', 'veda-app-ai-draft', true),
('ramayana-4-34-7', 'en', 'They say the righteous great sage Vishvamitra, attached to Ghritachi, thought ten years were but a day, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-34-8', 'en', 'If even radiant Vishvamitra, best of those who know time, did not notice the time had come, what of an ordinary being?', 'veda-app-ai-draft', true),
('ramayana-4-34-9', 'en', 'Rama should forgive him here, Lakshmana, as he has given in to bodily nature, was exhausted, and was not yet satisfied in his desires.', 'veda-app-ai-draft', true),
('ramayana-4-34-10', 'en', 'And you should not give way to anger, dear Lakshmana, without knowing the facts, rashly like an ordinary man.', 'veda-app-ai-draft', true),
('ramayana-4-34-11', 'en', 'Men of strong character like you, bull among men, do not fall suddenly under the sway of anger without reflection.', 'veda-app-ai-draft', true),
('ramayana-4-34-12', 'en', 'I appeal to you, knower of dharma, earnestly for Sugriva''s sake. Give up this great agitation born of anger.', 'veda-app-ai-draft', true),
('ramayana-4-34-13', 'en', 'I believe Sugriva would give up Ruma, me, the monkey kingdom, wealth, grain and riches to please Rama.', 'veda-app-ai-draft', true),
('ramayana-4-34-14', 'en', 'Sugriva will kill Ravana in battle and bring Raghava together with Sita, like the moon with Rohini.', 'veda-app-ai-draft', true),
('ramayana-4-34-15', 'en', 'They say there are a hundred thousand crores of demons in Lanka, and thirty-six ayutas, thousands and hundreds more.', 'veda-app-ai-draft', true),
('ramayana-4-34-16', 'en', 'Without killing those invincible, shape-shifting demons, Ravana, who took Maithili, cannot be killed.', 'veda-app-ai-draft', true),
('ramayana-4-34-17', 'en', 'They cannot be killed in battle without help, Lakshmana, nor can cruel Ravana, and especially not without Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-34-18', 'en', 'So Vali told me, for the lord of monkeys knew. I do not know it directly; I tell you what I heard from him.', 'veda-app-ai-draft', true),
('ramayana-4-34-19', 'en', 'The best monkeys have been sent to bring many monkeys and troop leaders for battle, to help you.', 'veda-app-ai-draft', true),
('ramayana-4-34-20', 'en', 'Waiting for those brave and mighty ones, the lord of monkeys has not set out yet, for the success of Raghava''s purpose.', 'veda-app-ai-draft', true),
('ramayana-4-34-21', 'en', 'Sugriva made the arrangement as before, Lakshmana. Today all those mighty monkeys are to arrive.', 'veda-app-ai-draft', true),
('ramayana-4-34-22', 'en', 'Thousands of crores of bears and hundreds of langurs will come to you today. Give up your anger, subduer of enemies. Many crores of blazing monkeys are coming too, Kakutstha.', 'veda-app-ai-draft', true),
('ramayana-4-34-23', 'en', 'Seeing your face in anger and your eyes red as blood, the wives of the best monkeys find no peace; we are all afraid as if of the first danger.', 'veda-app-ai-draft', true),
('ramayana-4-35-1', 'en', 'Told this courteous speech full of dharma by Tara, gentle-natured Lakshmana accepted her words.', 'veda-app-ai-draft', true),
('ramayana-4-35-2', 'en', 'When his words were accepted, the lord of the monkey hosts threw off his great fear of Lakshmana like a wet garment.', 'veda-app-ai-draft', true),
('ramayana-4-35-3', 'en', 'Then Sugriva, lord of monkeys, tore off the large, colourful, many-stranded garland from his neck and became sober.', 'veda-app-ai-draft', true),
('ramayana-4-35-4', 'en', 'Sugriva, best of all monkeys, spoke humble words to Lakshmana of fearsome strength, delighting him:', 'veda-app-ai-draft', true),
('ramayana-4-35-5', 'en', 'My fortune, fame and the lasting monkey kingdom were lost, Lakshmana, and by Rama''s grace I have regained them.', 'veda-app-ai-draft', true),
('ramayana-4-35-6', 'en', 'Who could repay that godlike one, famous for his own deeds, for such valour, hero and subduer of foes?', 'veda-app-ai-draft', true),
('ramayana-4-35-7', 'en', 'Righteous Raghava will regain Sita and kill Ravana by his own power, with me only as a helper.', 'veda-app-ai-draft', true),
('ramayana-4-35-8', 'en', 'He who split seven great trees, a mountain and the earth with one arrow hardly needs help.', 'veda-app-ai-draft', true),
('ramayana-4-35-9', 'en', 'When he draws his bow, Lakshmana, the earth with its mountains shakes at the sound. What need has he of allies?', 'veda-app-ai-draft', true),
('ramayana-4-35-10', 'en', 'I will follow the king of men, bull among men, when he goes to kill his enemy Ravana and those with him.', 'veda-app-ai-draft', true),
('ramayana-4-35-11', 'en', 'If I have overstepped in anything out of trust or affection, it should be forgiven in a servant. There is no one who never errs.', 'veda-app-ai-draft', true),
('ramayana-4-35-12', 'en', 'As great Sugriva said this, Lakshmana was pleased and spoke with affection:', 'veda-app-ai-draft', true),
('ramayana-4-35-13', 'en', 'My brother has a true protector in you, lord of monkeys, Sugriva, especially since you are so humble.', 'veda-app-ai-draft', true),
('ramayana-4-35-14', 'en', 'With your power, Sugriva, and your excellent integrity, you deserve to enjoy the unmatched fortune of the monkey kingdom.', 'veda-app-ai-draft', true),
('ramayana-4-35-15', 'en', 'With you as his ally, Sugriva, mighty Rama will soon kill his enemies in battle. There is no doubt.', 'veda-app-ai-draft', true),
('ramayana-4-35-16', 'en', 'What you said, Sugriva, is fitting and right for one who knows dharma, is grateful and never retreats in battle.', 'veda-app-ai-draft', true),
('ramayana-4-35-17', 'en', 'Who else, knowing his faults while having the power, would speak like this, except my elder brother and you, best of monkeys?', 'veda-app-ai-draft', true),
('ramayana-4-35-18', 'en', 'You are Rama''s equal in valour and strength, an ally given by the gods for a long time, chief of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-35-19', 'en', 'But come out quickly with me, hero, and comfort your friend, who grieves over the taking of his wife.', 'veda-app-ai-draft', true),
('ramayana-4-35-20', 'en', 'And forgive the harsh words I spoke to you after hearing grief-stricken Rama''s speech.', 'veda-app-ai-draft', true),
('ramayana-4-36-1', 'en', 'Spoken to this way by great Lakshmana, Sugriva said to Hanuman, his minister standing beside him:', 'veda-app-ai-draft', true),
('ramayana-4-36-2', 'en', 'Those who live on the peaks of Mahendra, Himavan, Vindhya and Kailasa, on Mandara, Pandushikhara and the five mountains,', 'veda-app-ai-draft', true),
('ramayana-4-36-3', 'en', 'on mountains shining all over with the colour of the rising sun, at the edge of the sea in the western direction,', 'veda-app-ai-draft', true),
('ramayana-4-36-4', 'en', 'the chief monkeys who live on the Adityabhavana mountain like a twilight cloud and in the fearsome Padmatala forest,', 'veda-app-ai-draft', true),
('ramayana-4-36-5', 'en', 'the monkeys like collyrium-dark clouds, with the might of elephants, who live on Mount Anjana,', 'veda-app-ai-draft', true),
('ramayana-4-36-6', 'en', 'the golden monkeys living in caves of red arsenic, those on the slopes of Meru and those on Dhumragiri,', 'veda-app-ai-draft', true),
('ramayana-4-36-7', 'en', 'the fierce, swift monkeys the colour of the rising sun on Mount Maharuna, drinking honey wine,', 'veda-app-ai-draft', true),
('ramayana-4-36-8', 'en', 'and those in the lovely, fragrant great forests and in the charming woods of ascetics all around,', 'veda-app-ai-draft', true),
('ramayana-4-36-9', 'en', 'bring all those monkeys of the earth quickly. Send monkeys swiftly, using conciliation, gifts and other means.', 'veda-app-ai-draft', true),
('ramayana-4-36-10', 'en', 'And send other monkeys again to hurry those swift messengers I sent first.', 'veda-app-ai-draft', true),
('ramayana-4-36-11', 'en', 'Bring here at once by my command all the monkeys who are lost in pleasure or slow to act.', 'veda-app-ai-draft', true),
('ramayana-4-36-12', 'en', 'Those wicked ones who do not come within ten days at my command, defying the king''s order, shall be killed.', 'veda-app-ai-draft', true),
('ramayana-4-36-13', 'en', 'Let hundreds, thousands and crores of lion-like monkeys go in all directions by my command, following my will.', 'veda-app-ai-draft', true),
('ramayana-4-36-14', 'en', 'Let the fearsome best of monkeys, like clouds and mountains, go from here at my command as if covering the sky.', 'veda-app-ai-draft', true),
('ramayana-4-36-15', 'en', 'Let all the monkeys who know the routes go across the earth and quickly bring all the monkeys at my command.', 'veda-app-ai-draft', true),
('ramayana-4-36-16', 'en', 'Hearing the monkey king''s words, the son of the Wind sent bold monkeys in every direction.', 'veda-app-ai-draft', true),
('ramayana-4-36-17', 'en', 'Sent by the king, the monkeys set out at once on the path of birds and stars, the sky Vishnu strode across.', 'veda-app-ai-draft', true),
('ramayana-4-36-18', 'en', 'In seas, mountains, forests and rivers, the monkeys urged all the monkeys on for Rama''s sake.', 'veda-app-ai-draft', true),
('ramayana-4-36-19', 'en', 'Hearing the command of Sugriva, king of kings, which was like the hour of death, the monkeys came, fearing Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-36-20', 'en', 'Then three crores of very swift monkeys, dark as collyrium, came out from that mountain to where Raghava was.', 'veda-app-ai-draft', true),
('ramayana-4-36-21', 'en', 'Ten crores, shining like molten gold, came from the great mountain where the sun sets.', 'veda-app-ai-draft', true),
('ramayana-4-36-22', 'en', 'Then from the peaks of Kailasa came thousands of crores of monkeys with the lustre of a lion''s mane.', 'veda-app-ai-draft', true),
('ramayana-4-36-23', 'en', 'Of those who live on Himavan, surviving on fruits and roots, there were a thousand thousands of crores.', 'veda-app-ai-draft', true),
('ramayana-4-36-24', 'en', 'From the Vindhya, thousands of crores of fearsome monkeys of fierce deeds, red like Mars, rushed swiftly.', 'veda-app-ai-draft', true),
('ramayana-4-36-25', 'en', 'Those living on the shore of the Milk Ocean, dwelling in tamala forests and eating coconuts, were beyond counting.', 'veda-app-ai-draft', true),
('ramayana-4-36-26', 'en', 'From forests, caves and rivers came the swift monkey army, as if drinking up the sun.', 'veda-app-ai-draft', true),
('ramayana-4-36-27', 'en', 'The heroic monkeys who had gone to hurry all the others saw the great tree on the Himalaya.', 'veda-app-ai-draft', true),
('ramayana-4-36-28', 'en', 'On that lovely great mountain long ago there was a sacrifice of Maheshvara, heavenly and charming, which pleased the minds of all the gods.', 'veda-app-ai-draft', true),
('ramayana-4-36-29', 'en', 'There the monkeys saw roots and fruits sprung from the overflow of food offerings, tasting like nectar.', 'veda-app-ai-draft', true),
('ramayana-4-36-30', 'en', 'Whoever eats even once that divine, charming fruit and root sprung from that food stays satisfied for a month.', 'veda-app-ai-draft', true),
('ramayana-4-36-31', 'en', 'The fruit-eating monkey leaders gathered those divine roots and fruits and divine herbs.', 'veda-app-ai-draft', true),
('ramayana-4-36-32', 'en', 'And from that place of sacrifice the monkeys brought fragrant flowers to please Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-36-33', 'en', 'All those best monkeys, having swiftly urged on all the monkeys of the earth, went ahead of the troops.', 'veda-app-ai-draft', true),
('ramayana-4-36-34', 'en', 'Those swift troop leaders reached Kishkindha in haste in that moment, where the monkey Sugriva was.', 'veda-app-ai-draft', true),
('ramayana-4-36-35', 'en', 'Taking all the herbs, fruits and roots, the monkeys presented them to him and said:', 'veda-app-ai-draft', true),
('ramayana-4-36-36', 'en', 'All the mountains, seas and forests have been visited. All the monkeys on earth are coming to you at your command.', 'veda-app-ai-draft', true),
('ramayana-4-36-37', 'en', 'Hearing this, Sugriva, lord of monkeys, was delighted and gladly accepted all their gifts.', 'veda-app-ai-draft', true),
('ramayana-4-37-1', 'en', 'Having accepted all the gifts brought to him and comforted the monkeys, he dismissed them all.', 'veda-app-ai-draft', true),
('ramayana-4-37-2', 'en', 'Having dismissed those heroes who had done their work, he felt that he and mighty Raghava had achieved their aim.', 'veda-app-ai-draft', true),
('ramayana-4-37-3', 'en', 'Lakshmana spoke humbly to Sugriva, best of all monkeys and of fearsome strength, delighting him: Come out of Kishkindha, gentle one, if you are willing.', 'veda-app-ai-draft', true),
('ramayana-4-37-4', 'en', 'Hearing Lakshmana''s well-spoken words, Sugriva, greatly pleased, said this:', 'veda-app-ai-draft', true),
('ramayana-4-37-5', 'en', 'So be it. Let us go. I must stand by your command. Having said this to auspicious Lakshmana,', 'veda-app-ai-draft', true),
('ramayana-4-37-6', 'en', 'Sugriva then dismissed Tara and the other women, and called out loudly to the best monkeys: Come!', 'veda-app-ai-draft', true),
('ramayana-4-37-7', 'en', 'Hearing his call, the monkeys came quickly, all with folded hands, those permitted to see the women''s quarters.', 'veda-app-ai-draft', true),
('ramayana-4-37-8', 'en', 'The king, shining like the sun, said to them when they came: Monkeys, quickly bring my palanquin.', 'veda-app-ai-draft', true),
('ramayana-4-37-9', 'en', 'Hearing his words, the swift monkeys brought a beautiful palanquin.', 'veda-app-ai-draft', true),
('ramayana-4-37-10', 'en', 'Seeing the palanquin brought, the lord of monkeys said to Lakshmana: Get in quickly, Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-37-11', 'en', 'Saying this, Sugriva with Lakshmana mounted the golden carriage, bright as the sun and borne by large monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-37-12', 'en', 'A white umbrella was held over his head, and white yak-tail fans waved all around him.', 'veda-app-ai-draft', true),
('ramayana-4-37-13', 'en', 'Hailed by the sounds of conches and drums and by bards, Sugriva went out, having gained supreme royal splendour.', 'veda-app-ai-draft', true),
('ramayana-4-37-14', 'en', 'Surrounded by many hundreds of fierce monkeys with weapons in hand, he went to where Rama was staying.', 'veda-app-ai-draft', true),
('ramayana-4-37-15', 'en', 'Reaching that fine place where Rama lived, radiant Sugriva got down from the palanquin with Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-4-37-16', 'en', 'Approaching Rama, he stood with folded hands, and as he stood so, the monkeys did the same.', 'veda-app-ai-draft', true),
('ramayana-4-37-17', 'en', 'Seeing that great army of monkeys like a pond full of lotus buds, Rama was pleased with Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-37-18', 'en', 'Raising the monkey king who had fallen at his feet with his head, Raghava embraced him with love and great respect.', 'veda-app-ai-draft', true),
('ramayana-4-37-19', 'en', 'Having embraced him, the righteous one said: Sit down. Seeing him seated on the ground, Rama spoke:', 'veda-app-ai-draft', true),
('ramayana-4-37-20', 'en', 'Whoever pursues dharma, wealth and pleasure each at its proper time, always dividing them, is a king, hero, best of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-37-21', 'en', 'But whoever gives up dharma and wealth and pursues pleasure alone is like a man asleep at the top of a tree who wakes only when he has fallen.', 'veda-app-ai-draft', true),
('ramayana-4-37-22', 'en', 'A king who is intent on killing enemies and gathering friends enjoys the fruit of the three aims and is joined with dharma.', 'veda-app-ai-draft', true),
('ramayana-4-37-23', 'en', 'This is the time for action, destroyer of enemies. Let it be considered with the monkey ministers, tawny lord.', 'veda-app-ai-draft', true),
('ramayana-4-37-24', 'en', 'Told this, Sugriva said to Rama:', 'veda-app-ai-draft', true),
('ramayana-4-37-25', 'en', 'My lost fortune, fame and the lasting monkey kingdom I have regained by your grace, mighty-armed one.', 'veda-app-ai-draft', true),
('ramayana-4-37-26', 'en', 'By your grace and your brother''s, best of victors, one who does not repay a kindness is a disgrace among men.', 'veda-app-ai-draft', true),
('ramayana-4-37-27', 'en', 'These monkey chiefs, by hundreds, have come, destroyer of enemies, bringing with them all the mighty monkeys of the earth.', 'veda-app-ai-draft', true),
('ramayana-4-37-28', 'en', 'And brave, attentive bears and langurs, Raghava, fearsome to see and knowing the wild forests and strongholds.', 'veda-app-ai-draft', true),
('ramayana-4-37-29', 'en', 'Monkeys who are sons of gods and gandharvas, able to change form, are on the way, Raghava, each surrounded by his own army.', 'veda-app-ai-draft', true),
('ramayana-4-37-30', 'en', 'Heroic monkeys surrounded by hundreds, hundreds of thousands, crores, ayutas and shankus, scorcher of foes,', 'veda-app-ai-draft', true),
('ramayana-4-37-31', 'en', 'with arbudas, hundreds of arbudas, madhyas, antyas, samudras and parardhas of monkeys and troop leaders,', 'veda-app-ai-draft', true),
('ramayana-4-37-32', 'en', 'they will come, king, equal in valour to great Indra, like Meru and Mandara, living in the Vindhya and Meru.', 'veda-app-ai-draft', true),
('ramayana-4-37-33', 'en', 'They will come to you, kill the demon Ravana with his kin in battle, and bring back Maithili.', 'veda-app-ai-draft', true),
('ramayana-4-37-34', 'en', 'Seeing the effort of the monkey hero who followed his command, the wise prince grew joyful, his eyes like blooming blue lotuses.', 'veda-app-ai-draft', true),
('ramayana-4-38-1', 'en', 'As Sugriva spoke this way, Rama, best of the upholders of dharma, embraced him with both arms and replied to him with folded hands:', 'veda-app-ai-draft', true),
('ramayana-4-38-2', 'en', 'It is no wonder on earth that Indra sends rain or that the thousand-rayed sun makes the sky free of darkness.', 'veda-app-ai-draft', true),
('ramayana-4-38-3', 'en', 'Or that the moon with its rays makes the earth bright, gentle one, or that one like you repays his friends, scorcher of foes.', 'veda-app-ai-draft', true),
('ramayana-4-38-4', 'en', 'So it is no wonder in you, gentle one, that you do what is fine. I know you, Sugriva, as always kind in speech.', 'veda-app-ai-draft', true),
('ramayana-4-38-5', 'en', 'With you as my protector, friend, I will conquer all my enemies in battle. You alone are my true friend and should give me help.', 'veda-app-ai-draft', true),
('ramayana-4-38-6', 'en', 'That lowest of demons carried off Vaidehi to his own ruin, as Anuhlada deceived and took Shachi, daughter of Puloman.', 'veda-app-ai-draft', true),
('ramayana-4-38-7', 'en', 'Soon I will kill Ravana with sharp arrows, as Indra, slayer of foes, killed the proud father of Puloman''s daughter.', 'veda-app-ai-draft', true),
('ramayana-4-38-8', 'en', 'Just then a cloud of dust rose up, covering in the sky the hot, fierce light of the sun.', 'veda-app-ai-draft', true),
('ramayana-4-38-9', 'en', 'The directions were thrown into confusion, darkened by that dust, and the whole earth with its mountains and forests shook.', 'veda-app-ai-draft', true),
('ramayana-4-38-10', 'en', 'Then the whole earth was covered by countless mighty monkeys like great mountains, with sharp teeth.', 'veda-app-ai-draft', true),
('ramayana-4-38-11', 'en', 'In the blink of an eye it was filled with shape-shifting monkey leaders, each with hundreds of crores of followers.', 'veda-app-ai-draft', true),
('ramayana-4-38-12', 'en', 'with mighty monkeys from rivers, mountains and seas, with voices like thunder, and other forest dwellers,', 'veda-app-ai-draft', true),
('ramayana-4-38-13', 'en', 'with monkeys the colour of the rising sun, white as the moon, coloured like lotus filaments, and white ones who live on Meru.', 'veda-app-ai-draft', true),
('ramayana-4-38-14', 'en', 'Then the glorious hero monkey named Shatabali appeared, surrounded by ten thousand crores.', 'veda-app-ai-draft', true),
('ramayana-4-38-15', 'en', 'Then Tara''s mighty father, like a golden mountain, appeared with many tens of thousands of crores.', 'veda-app-ai-draft', true),
('ramayana-4-38-16', 'en', 'Coloured like lotus filaments, with a face like the rising sun, wise, the best of monkeys and finest of all,', 'veda-app-ai-draft', true),
('ramayana-4-38-17', 'en', 'glorious Kesari, Hanuman''s father, appeared with many thousands of monkey battalions.', 'veda-app-ai-draft', true),
('ramayana-4-38-18', 'en', 'Gavaksha, the great king of the langurs, of fearsome valour, appeared surrounded by a thousand crores of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-38-19', 'en', 'Dhumra, destroyer of foes, came with two thousand crores of fiercely swift bears.', 'veda-app-ai-draft', true),
('ramayana-4-38-20', 'en', 'The mighty troop leader named Panasa came surrounded by three crores of fearsome monkeys like great mountains.', 'veda-app-ai-draft', true),
('ramayana-4-38-21', 'en', 'Then the troop leader named Nila, huge and shaped like a heap of blue collyrium, appeared surrounded by ten crores.', 'veda-app-ai-draft', true),
('ramayana-4-38-22', 'en', 'Then mighty troop leader Darimukha came, surrounded by a thousand crores, and presented himself to Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-38-23', 'en', 'Mainda and Dvivida, both mighty sons of the Ashvins, appeared with a thousand crores of crores of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-38-24', 'en', 'Then Gandhamadana arrived, followed behind by a hundred and a thousand thousands of crores of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-38-25', 'en', 'Then crown prince Angada, equal to his father in valour, arrived surrounded by a thousand padmas and a hundred shankus.', 'veda-app-ai-draft', true),
('ramayana-4-38-26', 'en', 'Then Tara, bright as a star, a monkey of fearsome valour, was seen from afar with five crores of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-38-27', 'en', 'The heroic monkey troop leader Indrajanu appeared, lord of eleven crores and surrounded by them.', 'veda-app-ai-draft', true),
('ramayana-4-38-28', 'en', 'Then Rambha arrived, like the rising sun, surrounded by ten thousand and a thousand and a hundred.', 'veda-app-ai-draft', true),
('ramayana-4-38-29', 'en', 'Then the heroic troop leader, the monkey named Durmukha, appeared, mighty, surrounded by two crores.', 'veda-app-ai-draft', true),
('ramayana-4-38-30', 'en', 'Hanuman appeared surrounded by a thousand crores of monkeys of fearsome valour, shaped like the peaks of Kailasa.', 'veda-app-ai-draft', true),
('ramayana-4-38-31', 'en', 'Mighty Nala also arrived, surrounded by tree-dwellers, a hundred crores and a thousand and a hundred.', 'veda-app-ai-draft', true),
('ramayana-4-38-32', 'en', 'Sharabha, Kumuda, Vahni, the monkey Rambha, and many other shape-shifting monkeys,', 'veda-app-ai-draft', true),
('ramayana-4-38-33', 'en', 'covering the whole earth, mountains and forests, leaping, bounding and roaring, the monkeys came up to Sugriva like masses of cloud to the sun.', 'veda-app-ai-draft', true),
('ramayana-4-38-34', 'en', 'Making many sounds, joyful and mighty, they bowed their heads and reported to Sugriva, king of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-38-35', 'en', 'Other best monkeys met properly and, meeting Sugriva, stood with folded hands.', 'veda-app-ai-draft', true),
('ramayana-4-38-36', 'en', 'Sugriva, knower of dharma, quickly presented all those monkey bulls to Rama and, standing with folded hands, said:', 'veda-app-ai-draft', true),
('ramayana-4-38-37', 'en', 'Let the monkey kings settle their forces properly and at ease by the mountain streams and in all the forests. The one who knows the army can then take charge of it.', 'veda-app-ai-draft', true),
('ramayana-4-39-1', 'en', 'Then King Sugriva, lord of monkeys, his aims fulfilled, spoke to Rama, tiger among men and crusher of enemy forces:', 'veda-app-ai-draft', true),
('ramayana-4-39-2', 'en', 'The mighty shape-shifting monkey kings, bright as great Indra, who live in my realm have come and settled.', 'veda-app-ai-draft', true),
('ramayana-4-39-3', 'en', 'These fearsome monkeys, like daityas and danavas, have come with many thousands of monkeys of terrible valour.', 'veda-app-ai-draft', true),
('ramayana-4-39-4', 'en', 'Famous for their deeds and exploits, mighty, tireless, renowned for valour and excellent in resolve,', 'veda-app-ai-draft', true),
('ramayana-4-39-5', 'en', 'these monkeys moving on land and water and living on many mountains have come by crores, Rama, as your servants.', 'veda-app-ai-draft', true),
('ramayana-4-39-6', 'en', 'All obey commands and are devoted to their master''s good. They will be able to do what you wish, subduer of enemies.', 'veda-app-ai-draft', true),
('ramayana-4-39-7', 'en', 'Tell me what you think is timely, tiger among men. That army is at your command; you should give the orders.', 'veda-app-ai-draft', true),
('ramayana-4-39-8', 'en', 'Though I truly know this task of theirs, still you should command them as is right.', 'veda-app-ai-draft', true),
('ramayana-4-39-9', 'en', 'As Sugriva spoke, Rama, son of Dasharatha, embraced him with both arms and said:', 'veda-app-ai-draft', true),
('ramayana-4-39-10', 'en', 'Let it be found out, gentle one, whether Vaidehi is alive or not, and the land where Ravana lives, wise one.', 'veda-app-ai-draft', true),
('ramayana-4-39-11', 'en', 'When we have found Vaidehi and Ravana''s dwelling, I will do what the time requires, together with you.', 'veda-app-ai-draft', true),
('ramayana-4-39-12', 'en', 'Neither I nor Lakshmana is master in this task, lord of monkeys. You are its cause and its master.', 'veda-app-ai-draft', true),
('ramayana-4-39-13', 'en', 'You yourself give the orders for my task, lord. You know what my task is, hero, without doubt.', 'veda-app-ai-draft', true),
('ramayana-4-39-14', 'en', 'You are my second friend, brave, wise, knowing the right time, devoted to our good, accomplished and most skilled in affairs.', 'veda-app-ai-draft', true),
('ramayana-4-39-15', 'en', 'Told this, Sugriva, in the presence of Rama and wise Lakshmana, spoke to the troop leader named Vinata, mighty lord of monkeys like a mountain with a voice like thunder:', 'veda-app-ai-draft', true),
('ramayana-4-39-16', 'en', 'Best of monkeys, with monkeys born of the moon and the sun, skilled in time, place and policy, and in deciding what to do and not,', 'veda-app-ai-draft', true),
('ramayana-4-39-17', 'en', 'surrounded by a hundred thousand swift monkeys, go to the eastern direction with its mountains, woods and forests.', 'veda-app-ai-draft', true),
('ramayana-4-39-18', 'en', 'There search for Sita, Vaidehi, and for Ravana''s dwelling in the mountain strongholds, forests and rivers.', 'veda-app-ai-draft', true),
('ramayana-4-39-19', 'en', 'The lovely Bhagirathi river, the Sarayu and the Kaushiki, the Kalindi and lovely Yamuna, and the great Yamuna mountain,', 'veda-app-ai-draft', true),
('ramayana-4-39-20', 'en', 'the Sarasvati and the Sindhu, the Shona with jewel-clear water, the Mahi and Kalamahi, adorned with mountains and forests,', 'veda-app-ai-draft', true),
('ramayana-4-39-21', 'en', 'the Brahmamalas, the Videhas, the Malavas, Kashi and Kosala, the Magadhas with their great villages, the Pundras and Vangas,', 'veda-app-ai-draft', true),
('ramayana-4-39-22', 'en', 'the town of the silkworm-keepers and the land of silver mines: all this must be searched, looking here and there,', 'veda-app-ai-draft', true),
('ramayana-4-39-23', 'en', 'for Sita, Rama''s beloved wife and Dasharatha''s daughter-in-law, and the mountains and towns that lie in the sea,', 'veda-app-ai-draft', true),
('ramayana-4-39-24', 'en', 'and those who live on the long ridge of Mandara: people whose ears cover them, and those with ears on their lips,', 'veda-app-ai-draft', true),
('ramayana-4-39-25', 'en', 'fearsome iron-faced people, swift one-footed people, the strong imperishable people and man-eaters,', 'veda-app-ai-draft', true),
('ramayana-4-39-26', 'en', 'Kiratas with topknots on their ears, golden-limbed and handsome, and island-dwelling Kiratas who eat raw fish,', 'veda-app-ai-draft', true),
('ramayana-4-39-27', 'en', 'and fearsome creatures moving underwater, known as man-tigers. All the homes of these must be searched by the forest dwellers.', 'veda-app-ai-draft', true),
('ramayana-4-39-28', 'en', 'Places reached by way of mountains, by leaping or by boat; Yavadvipa, rich in jewels, graced by seven kingdoms,', 'veda-app-ai-draft', true),
('ramayana-4-39-29', 'en', 'Suvarnarupyaka, adorned with gold mines; and beyond Yavadvipa is a mountain named Shishira,', 'veda-app-ai-draft', true),
('ramayana-4-39-30', 'en', 'which touches the sky with its peak, frequented by gods and danavas. In the mountain strongholds, waterfalls and forests of these,', 'veda-app-ai-draft', true),
('ramayana-4-39-31', 'en', 'Ravana must be searched for along with Vaidehi here and there. Then you should see the very fearsome islands in the sea.', 'veda-app-ai-draft', true),
('ramayana-4-39-32', 'en', 'There huge asuras always seize shadows, permitted by Brahma, hungry for a long time.', 'veda-app-ai-draft', true),
('ramayana-4-39-33', 'en', 'Reaching the great ocean, like a black cloud, home to great serpents and loud with roaring, cross it by a proper ford.', 'veda-app-ai-draft', true),
('ramayana-4-39-34', 'en', 'Then you will reach the fearsome sea of red water named Lohita, and see the great Kutashalmali tree.', 'veda-app-ai-draft', true),
('ramayana-4-39-35', 'en', 'and the house of Garuda adorned with many jewels, built there by Vishvakarma, like Kailasa.', 'veda-app-ai-draft', true),
('ramayana-4-39-36', 'en', 'There fearsome demons called Mandehas, like mountains and of many forms, hang from the mountain peaks, causing terror.', 'veda-app-ai-draft', true),
('ramayana-4-39-37', 'en', 'They fall into the water every day at sunrise and, scorched by the sun, hang again and again.', 'veda-app-ai-draft', true),
('ramayana-4-39-38', 'en', 'Then you will reach the Milk Ocean, like pale clouds, its waves like a necklace of pearls on its face, hard to approach.', 'veda-app-ai-draft', true),
('ramayana-4-39-39', 'en', 'In its middle is a great white mountain named Rishabha, surrounded by trees with heavenly fragrant flowers and of silver.', 'veda-app-ai-draft', true),
('ramayana-4-39-40', 'en', 'and a lake named Sudarshana, full of royal swans, with shining silver lotuses with golden filaments.', 'veda-app-ai-draft', true),
('ramayana-4-39-41', 'en', 'Gods, charanas, yakshas, kinnaras and troops of apsaras come joyfully to that lotus pond for pleasure.', 'veda-app-ai-draft', true),
('ramayana-4-39-42', 'en', 'Having crossed the Milk Ocean, monkeys, you will then see the Jaloda, best of seas, terrifying to all beings.', 'veda-app-ai-draft', true),
('ramayana-4-39-43', 'en', 'There is the great horse-faced fire born of anger. They say its food is the whole moving and unmoving world.', 'veda-app-ai-draft', true),
('ramayana-4-39-44', 'en', 'There the cry of helpless sea creatures wailing is heard as they see that mare-faced fire.', 'veda-app-ai-draft', true),
('ramayana-4-39-45', 'en', 'Thirteen yojanas north of the sweet-water sea is a great golden mountain named Jatarupashila.', 'veda-app-ai-draft', true),
('ramayana-4-39-46', 'en', 'On its summit sits the thousand-headed god Ananta, dressed in blue, honoured by all beings.', 'veda-app-ai-draft', true),
('ramayana-4-39-47', 'en', 'The great one''s golden three-headed palm-tree banner, set on the mountain top with its altar, shines brightly.', 'veda-app-ai-draft', true),
('ramayana-4-39-48', 'en', 'This marker was made by the lords of the gods in the eastern direction. Beyond it is the glorious golden Udaya mountain.', 'veda-app-ai-draft', true),
('ramayana-4-39-49', 'en', 'Its heavenly golden summit with its altar, a hundred yojanas long, touches the sky and shines.', 'veda-app-ai-draft', true),
('ramayana-4-39-50', 'en', 'It is beautiful with heavenly golden sal, palm, tamala and flowering karnikara trees, bright as the sun.', 'veda-app-ai-draft', true),
('ramayana-4-39-51', 'en', 'There is a golden peak named Saumanasa, a yojana wide and ten yojanas high, ever firm.', 'veda-app-ai-draft', true),
('ramayana-4-39-52', 'en', 'There long ago Vishnu, best of beings, set his first step in his three strides and made his second on the summit of Meru.', 'veda-app-ai-draft', true),
('ramayana-4-39-53', 'en', 'Circling Jambudvipa from the north, the sun is most visible on that very lofty peak.', 'veda-app-ai-draft', true),
('ramayana-4-39-54', 'en', 'There the great sages called Vaikhanasas and Valakhilyas are seen shining, sun-coloured ascetics.', 'veda-app-ai-draft', true),
('ramayana-4-39-55', 'en', 'This is the island Sudarshana, before which it shines, in which lies the light and the sight of all living beings.', 'veda-app-ai-draft', true),
('ramayana-4-39-56', 'en', 'In the groves, caves and forests of that mountain, Ravana must be searched for along with Vaidehi here and there.', 'veda-app-ai-draft', true),
('ramayana-4-39-57', 'en', 'The eastern twilight, filled with the radiance of the golden mountain and the great sun, shines red.', 'veda-app-ai-draft', true),
('ramayana-4-39-58', 'en', 'Beyond that the eastern direction is impassable, surrounded by the gods, without moon or sun, invisible and wrapped in darkness.', 'veda-app-ai-draft', true),
('ramayana-4-39-59', 'en', 'In all those mountains, caves and forests, and in places I have not named, Janaki must be searched for.', 'veda-app-ai-draft', true),
('ramayana-4-39-60', 'en', 'This far the monkeys can go, chiefs of monkeys. Beyond, where there is no sun and no boundary, we do not know.', 'veda-app-ai-draft', true),
('ramayana-4-39-61', 'en', 'Having found Vaidehi and Ravana''s dwelling, return when a month is complete, after reaching the Udaya mountain.', 'veda-app-ai-draft', true),
('ramayana-4-39-62', 'en', 'Do not stay beyond a month; whoever stays will be put to death by me. Return successful, having found Maithili.', 'veda-app-ai-draft', true),
('ramayana-4-39-63', 'en', 'Having searched carefully the direction dear to great Indra, adorned with groves, and found Sita, beloved of Raghu''s heir, you will return and be happy, monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-40-1', 'en', 'Having sent off that great monkey army, Sugriva sent chosen monkeys to the south.', 'veda-app-ai-draft', true),
('ramayana-4-40-2', 'en', 'Nila, son of Agni, the monkey Hanuman, and Jambavan, the great monkey, son of the Grandfather,', 'veda-app-ai-draft', true),
('ramayana-4-40-3', 'en', 'Suhotra, Sharari, Sharagulma, Gaja, Gavaksha, Gavaya, Sushena and Rishabha,', 'veda-app-ai-draft', true),
('ramayana-4-40-4', 'en', 'Mainda and Dvivida, Vijaya, Gandhamadana, Ulkamukha and Asanga, the two sons of the Fire god,', 'veda-app-ai-draft', true),
('ramayana-4-40-5', 'en', 'the heroic lord of the monkey hosts, knowing their special skills, instructed these heroes led by Angada, endowed with speed and valour.', 'veda-app-ai-draft', true),
('ramayana-4-40-6', 'en', 'Making a great unstoppable force the vanguard of those monkey heroes, he directed them to the southern direction.', 'veda-app-ai-draft', true),
('ramayana-4-40-7', 'en', 'The lord of monkeys described to the monkey chiefs whatever regions in that direction were hard to reach.', 'veda-app-ai-draft', true),
('ramayana-4-40-8', 'en', 'The thousand-peaked Vindhya covered with many trees and creepers, and the hard-to-cross Narmada river, home of great serpents,', 'veda-app-ai-draft', true),
('ramayana-4-40-9', 'en', 'then the lovely Godavari, the great river Krishnaveni, and the blessed Varada, home of great serpents,', 'veda-app-ai-draft', true),
('ramayana-4-40-10', 'en', 'the Mekhalas, Utkalas and the towns of Dasharna, Avanti and Abhravanti: search all of these.', 'veda-app-ai-draft', true),
('ramayana-4-40-11', 'en', 'Vidarbha, the Rishikas, the lovely Mahishakas, Bangas, Kalingas and Kaushikas all around,', 'veda-app-ai-draft', true),
('ramayana-4-40-12', 'en', 'search the Dandaka forest with its mountains, rivers and caves, and the Godavari river: search all of it.', 'veda-app-ai-draft', true),
('ramayana-4-40-13', 'en', 'Likewise the Andhras, Pundras, Cholas, Pandyas and Keralas. You must go to the Ayomukha mountain, adorned with minerals.', 'veda-app-ai-draft', true),
('ramayana-4-40-14', 'en', 'That great glorious mountain with colourful peaks, forests full of flowers and areas of sandalwood forest, must be searched.', 'veda-app-ai-draft', true),
('ramayana-4-40-15', 'en', 'Then you will see the heavenly river Kaveri, clear-watered and auspicious, where troops of apsaras play.', 'veda-app-ai-draft', true),
('ramayana-4-40-16', 'en', 'On the top of the Malaya mountain you will see the mighty sage Agastya, best of sages, seated and shining like the sun.', 'veda-app-ai-draft', true),
('ramayana-4-40-17', 'en', 'Then, with permission from that pleased great soul, you will cross the great river Tamraparni, full of crocodiles.', 'veda-app-ai-draft', true),
('ramayana-4-40-18', 'en', 'Covered by heavenly sandal forests and dotted with islands, it enters the sea like a young woman going to her beloved.', 'veda-app-ai-draft', true),
('ramayana-4-40-19', 'en', 'Then, monkeys, you will see the heavenly golden gate of the Pandyas, adorned with pearls and gems.', 'veda-app-ai-draft', true),
('ramayana-4-40-20', 'en', 'Then, reaching the sea and settling your plan, there in the ocean, placed by Agastya,', 'veda-app-ai-draft', true),
('ramayana-4-40-21', 'en', 'is glorious Mahendra, best of mountains, with many colourful trees, golden and plunged in the great ocean.', 'veda-app-ai-draft', true),
('ramayana-4-40-22', 'en', 'It is adorned with many flowering trees and creepers and frequented by divine sages, chief yakshas and apsaras.', 'veda-app-ai-draft', true),
('ramayana-4-40-23', 'en', 'Strewn with hosts of siddhas and charanas, very charming, thousand-eyed Indra visits it at every festival.', 'veda-app-ai-draft', true),
('ramayana-4-40-24', 'en', 'On its far shore is an island a hundred yojanas long, shining and unreachable by men. Search it all around. There Sita must be searched for with all your effort.', 'veda-app-ai-draft', true),
('ramayana-4-40-25', 'en', 'That land is the home of the wicked Ravana, who is to be killed, the lord of demons, bright as thousand-eyed Indra.', 'veda-app-ai-draft', true),
('ramayana-4-40-26', 'en', 'In the middle of that southern sea lives a demoness famous as Angaraka, who feeds by seizing shadows.', 'veda-app-ai-draft', true),
('ramayana-4-40-27', 'en', 'Beyond it, a hundred yojanas into the sea, is a glorious mountain named Pushpitaka, frequented by siddhas and charanas.', 'veda-app-ai-draft', true),
('ramayana-4-40-28', 'en', 'Shining like the rays of the moon and sun, surrounded by sea water, it gleams with vast peaks as if scratching the sky.', 'veda-app-ai-draft', true),
('ramayana-4-40-29', 'en', 'One of its peaks is golden, served by the sun, and one is white silver, served by the moon.', 'veda-app-ai-draft', true),
('ramayana-4-40-30', 'en', 'The ungrateful, the cruel and unbelievers do not see it. Bow your heads to that mountain and search it, monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-40-31', 'en', 'Beyond that is the unassailable mountain Suryavan, fourteen yojanas along a hard road.', 'veda-app-ai-draft', true),
('ramayana-4-40-32', 'en', 'Beyond that is the mountain Vaidyuta, with trees bearing every desired fruit, charming in every season.', 'veda-app-ai-draft', true),
('ramayana-4-40-33', 'en', 'There eat the finest roots and fruits, drink the best honey, and go on, monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-40-34', 'en', 'There is the mountain named Kunjara, pleasing to eye and mind, where Agastya''s dwelling was built by Vishvakarma.', 'veda-app-ai-draft', true),
('ramayana-4-40-35', 'en', 'There is a heavenly golden home a yojana wide and ten yojanas high, adorned with many jewels.', 'veda-app-ai-draft', true),
('ramayana-4-40-36', 'en', 'There is the serpents'' city named Bhogavati, with wide streets, unassailable and guarded on all sides by fearsome serpents with sharp fangs and deadly poison.', 'veda-app-ai-draft', true),
('ramayana-4-40-37', 'en', 'There lives Vasuki, the very fearsome king of serpents. That city Bhogavati must also be searched after going out.', 'veda-app-ai-draft', true),
('ramayana-4-40-38', 'en', 'Passing that region, there is a great mountain shaped like a bull, made of every jewel and glorious, named Rishabha.', 'veda-app-ai-draft', true),
('ramayana-4-40-39', 'en', 'There grows heavenly sandal of the goshirshaka, padmaka and harishyama kinds, shining like fire.', 'veda-app-ai-draft', true),
('ramayana-4-40-40', 'en', 'Having seen that sandal, never touch it. Fearsome gandharvas named Rohitas guard that forest.', 'veda-app-ai-draft', true),
('ramayana-4-40-41', 'en', 'There are the gandharva lords, bright as five suns: Shailusha, Gramani, Bhikshu, Shubhra and Babhru.', 'veda-app-ai-draft', true),
('ramayana-4-40-42', 'en', 'At the end of the earth stand the unassailable ones who have won heaven. Beyond that you must not go: the dreadful world of the ancestors, Yama''s capital, wrapped in grim darkness.', 'veda-app-ai-draft', true),
('ramayana-4-40-43', 'en', 'This far you can search or go, heroic monkey chiefs. Beyond this there is no path for those who move.', 'veda-app-ai-draft', true),
('ramayana-4-40-44', 'en', 'Having looked at all this and whatever else you see, and having learned where Vaidehi is, you should return.', 'veda-app-ai-draft', true),
('ramayana-4-40-45', 'en', 'Whoever returns within the month and says I have seen Sita will enjoy pleasures with splendour equal to mine and live happily.', 'veda-app-ai-draft', true),
('ramayana-4-40-46', 'en', 'No one will be dearer to me than him, more than my life. Even if he has often offended, he will be my kinsman.', 'veda-app-ai-draft', true),
('ramayana-4-40-47', 'en', 'You are of boundless strength and valour, born in families of great virtue. Undertake this supreme human endeavour so that you may find the king''s daughter.', 'veda-app-ai-draft', true),
('ramayana-4-41-1', 'en', 'Having sent those monkeys, full of intelligence and valour and swift as the wind, to the south,', 'veda-app-ai-draft', true),
('ramayana-4-41-2', 'en', 'the radiant king summoned the troop leader named Sushena, Tara''s father, his father-in-law of fearsome valour,', 'veda-app-ai-draft', true),
('ramayana-4-41-3', 'en', 'and approaching him with folded hands and bowing, said: Help Rama in this task that has come.', 'veda-app-ai-draft', true),
('ramayana-4-41-4', 'en', 'Surrounded by a hundred thousand swift monkeys, go to the western direction of Varuna, gentle lord.', 'veda-app-ai-draft', true),
('ramayana-4-41-5', 'en', 'Search Surashtra with the Bahlikas, the brave Abhiras, the rich and lovely lands and the great cities,', 'veda-app-ai-draft', true),
('ramayana-4-41-6', 'en', 'Kukshi, thick with punnaga trees and crowded with uddalaka trees, and the clumps of ketaka, troop leaders.', 'veda-app-ai-draft', true),
('ramayana-4-41-7', 'en', 'the westward-flowing rivers with cool, auspicious water, the forests of ascetics, the wild places and the mountains.', 'veda-app-ai-draft', true),
('ramayana-4-41-8', 'en', 'Having searched the western direction, hard and covered with chains of mountains, reach the western sea and see the ocean of water, full of whales and crocodiles and unshakable, monkey.', 'veda-app-ai-draft', true),
('ramayana-4-41-9', 'en', 'Then the monkeys will roam in the clumps of ketaka, the thick tamala groves and the coconut forests.', 'veda-app-ai-draft', true),
('ramayana-4-41-10', 'en', 'There search for Sita and for Ravana''s home, and for Marichipattana and lovely Jatipura,', 'veda-app-ai-draft', true),
('ramayana-4-41-11', 'en', 'Avanti, Angalopa, the Alakshita forest, and the great kingdoms and towns here and there.', 'veda-app-ai-draft', true),
('ramayana-4-41-12', 'en', 'At the meeting of the Sindhu and the sea is a great mountain named Hemagiri, with a hundred peaks and great trees.', 'veda-app-ai-draft', true),
('ramayana-4-41-13', 'en', 'On its lovely slopes live winged lions, who carry whales, fish and elephants up to their nests.', 'veda-app-ai-draft', true),
('ramayana-4-41-14', 'en', 'Around those lions'' nests and on the mountain peaks, proud, sated elephants with voices like thunderclouds roam everywhere on this vast, water-filled land.', 'veda-app-ai-draft', true),
('ramayana-4-41-15', 'en', 'Its golden peak, touching the sky and full of colourful trees, must all be quickly searched by the shape-shifting monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-41-16', 'en', 'There in the sea you will see the golden ridge of Pariyatra, a hundred yojanas long and hard to look at, monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-41-17', 'en', 'Twenty-four crores of swift gandharvas live there, fearsome, fiery and able to change form.', 'veda-app-ai-draft', true),
('ramayana-4-41-18', 'en', 'The monkeys of fearsome valour must not approach them too closely, nor take any fruit from that place.', 'veda-app-ai-draft', true),
('ramayana-4-41-19', 'en', 'Those heroes are hard to face, strong and mighty, and of fearsome valour they guard the fruits and roots there.', 'veda-app-ai-draft', true),
('ramayana-4-41-20', 'en', 'There you must make an effort and search for Janaki. You need have no fear of them if you behave as monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-41-21', 'en', 'In a quarter of the sea is the mountain named Chakravan, where Vishvakarma made a thousand-spoked discus.', 'veda-app-ai-draft', true),
('ramayana-4-41-22', 'en', 'There the Supreme Being killed Panchajana and the danava Hayagriva and took the discus and conch.', 'veda-app-ai-draft', true),
('ramayana-4-41-23', 'en', 'On its colourful slopes and in its wide caves, Ravana must be searched for with Vaidehi here and there.', 'veda-app-ai-draft', true),
('ramayana-4-41-24', 'en', 'In the bottomless home of Varuna is a mountain named Varaha, sixty-four yojanas, glorious with golden peaks.', 'veda-app-ai-draft', true),
('ramayana-4-41-25', 'en', 'There is a golden city named Pragjyotisha, where the wicked Naraka lives in caves.', 'veda-app-ai-draft', true),
('ramayana-4-41-26', 'en', 'On its colourful slopes and in its wide caves, Ravana must be searched for with Vaidehi here and there.', 'veda-app-ai-draft', true),
('ramayana-4-41-27', 'en', 'Beyond that king of mountains is a mountain all of gold, with golden valleys and full of streams and springs.', 'veda-app-ai-draft', true),
('ramayana-4-41-28', 'en', 'Elephants, boars, lions and tigers roar all around it constantly, made proud by that sound.', 'veda-app-ai-draft', true),
('ramayana-4-41-29', 'en', 'On it glorious great Indra, chastiser of Paka, with his tawny horses, was consecrated king by the gods; the mountain is called Meghavan.', 'veda-app-ai-draft', true),
('ramayana-4-41-30', 'en', 'Passing that king of mountains guarded by great Indra, you will come to sixty thousand golden mountains.', 'veda-app-ai-draft', true),
('ramayana-4-41-31', 'en', 'They shine all around with the colour of the rising sun, beautiful with golden trees in full flower.', 'veda-app-ai-draft', true),
('ramayana-4-41-32', 'en', 'In their midst stands Meru, king and best of mountains, to which the pleased sun once gave a boon.', 'veda-app-ai-draft', true),
('ramayana-4-41-33', 'en', 'The sun told that king of mountains: By my grace all who shelter in you will be golden by day and by night.', 'veda-app-ai-draft', true),
('ramayana-4-41-34', 'en', 'Gods, gandharvas and danavas who live on you will be red and shine with a golden glow.', 'veda-app-ai-draft', true),
('ramayana-4-41-35', 'en', 'The Adityas, Vasus, Rudras, Maruts and other dwellers of heaven come at the western twilight to Meru, best of mountains,', 'veda-app-ai-draft', true),
('ramayana-4-41-36', 'en', 'and wait upon the sun, and honoured by them the sun goes, unseen by all beings, to the mountain of sunset.', 'veda-app-ai-draft', true),
('ramayana-4-41-37', 'en', 'The sun swiftly travels ten thousand yojanas to that mountain in half a muhurta.', 'veda-app-ai-draft', true),
('ramayana-4-41-38', 'en', 'On its peak is a great heavenly mansion like the sun, full of palace features, built by Vishvakarma.', 'veda-app-ai-draft', true),
('ramayana-4-41-39', 'en', 'Graced with colourful trees full of many birds, it is the home of great Varuna, who holds the noose.', 'veda-app-ai-draft', true),
('ramayana-4-41-40', 'en', 'Between Meru and the sunset mountain is a great golden ten-headed palm, glorious and shining, with a colourful altar.', 'veda-app-ai-draft', true),
('ramayana-4-41-41', 'en', 'In all those strongholds, lakes and rivers, Ravana must be searched for with Vaidehi here and there.', 'veda-app-ai-draft', true),
('ramayana-4-41-42', 'en', 'There lives the righteous one, purified by his own austerity, famous as Merusavarni, equal to Brahma.', 'veda-app-ai-draft', true),
('ramayana-4-41-43', 'en', 'Bowing your heads to the ground, ask the great sage Merusavarni, bright as the sun, for news of Maithili.', 'veda-app-ai-draft', true),
('ramayana-4-41-44', 'en', 'This far, at the end of night, the sun lights up the whole world of the living and then goes to the sunset mountain.', 'veda-app-ai-draft', true),
('ramayana-4-41-45', 'en', 'This far the monkeys can go, chiefs of monkeys. Beyond, where there is no sun and no boundary, we do not know.', 'veda-app-ai-draft', true),
('ramayana-4-41-46', 'en', 'Having found Vaidehi and Ravana''s home, reach the sunset mountain and return when the month is complete.', 'veda-app-ai-draft', true),
('ramayana-4-41-47', 'en', 'Do not stay beyond a month; whoever stays will be put to death by me. My heroic father-in-law will go with you.', 'veda-app-ai-draft', true),
('ramayana-4-41-48', 'en', 'You who carry out orders must listen to everything he says. This mighty-armed father-in-law of mine is your elder and very strong.', 'veda-app-ai-draft', true),
('ramayana-4-41-49', 'en', 'You too are brave and an authority in all tasks. But taking him as your authority, search the western direction.', 'veda-app-ai-draft', true),
('ramayana-4-41-50', 'en', 'When the wife of the king of boundless glory is found, we will have done our duty by repaying what was done for us.', 'veda-app-ai-draft', true),
('ramayana-4-41-51', 'en', 'Beyond this, whatever else may help the task, decide it yourselves according to place, time and purpose.', 'veda-app-ai-draft', true),
('ramayana-4-41-52', 'en', 'Then the monkeys led by Sushena, having listened carefully to Sugriva''s words and taken leave of the monkey king, all went to the direction guarded by Varuna.', 'veda-app-ai-draft', true),
('ramayana-4-42-1', 'en', 'Then, having sent his father-in-law to the west, Sugriva, bull among monkeys, turned to the heroic monkey named Shatabali.', 'veda-app-ai-draft', true),
('ramayana-4-42-2', 'en', 'The king, wise in counsel, spoke words respected by all monkeys, good for himself and for Rama:', 'veda-app-ai-draft', true),
('ramayana-4-42-3', 'en', 'Surrounded by a hundred thousand forest dwellers like you, set out with your ministers and the sons of Yama.', 'veda-app-ai-draft', true),
('ramayana-4-42-4', 'en', 'Search all over the bold northern direction, crowned by the snowy mountains, for Rama''s blameless wife.', 'veda-app-ai-draft', true),
('ramayana-4-42-5', 'en', 'When this task is done and Dasharatha''s son is pleased, we will be free of debt, best of those who know their aims.', 'veda-app-ai-draft', true),
('ramayana-4-42-6', 'en', 'Great Raghava has done us a kindness. If we can repay it, our life will be fruitful.', 'veda-app-ai-draft', true),
('ramayana-4-42-7', 'en', 'Holding to this thought, you who wish our good should act so that Janaki is found.', 'veda-app-ai-draft', true),
('ramayana-4-42-8', 'en', 'This best of men is honoured by all beings, and Rama, conqueror of enemy cities, has come to love us.', 'veda-app-ai-draft', true),
('ramayana-4-42-9', 'en', 'With your wealth of intelligence and valour, search these forest strongholds, rivers and mountain passes.', 'veda-app-ai-draft', true),
('ramayana-4-42-10', 'en', 'There search the Mlecchas, Pulindas and Shurasenas, the Prasthalas, Bharatas and Kurus with the Madrakas,', 'veda-app-ai-draft', true),
('ramayana-4-42-11', 'en', 'the Kambojas, Yavanas, Shakas and Arattakas, the Bahlikas, Rishikas, Pauravas and Tankanas,', 'veda-app-ai-draft', true),
('ramayana-4-42-12', 'en', 'the Chinas and Paramachinas, the Niharas again and again, and having searched the Daradas, search the Himalaya.', 'veda-app-ai-draft', true),
('ramayana-4-42-13', 'en', 'In the clumps of lodhra and padmaka and in the deodar forests, Ravana must be searched for with Vaidehi here and there.', 'veda-app-ai-draft', true),
('ramayana-4-42-14', 'en', 'Then, going to the Soma hermitage frequented by gods and gandharvas, you will reach the great mountain named Kala with its wide slopes.', 'veda-app-ai-draft', true),
('ramayana-4-42-15', 'en', 'In its great peaks, valleys and caves, search for Rama''s noble and famous wife.', 'veda-app-ai-draft', true),
('ramayana-4-42-16', 'en', 'Passing that king of mountains, the great golden mountain, you should then go to the mountain named Sudarshana.', 'veda-app-ai-draft', true),
('ramayana-4-42-17', 'en', 'In its forest clumps, valleys and caves, Ravana must be searched for with Vaidehi here and there.', 'veda-app-ai-draft', true),
('ramayana-4-42-18', 'en', 'Beyond it is an open space a hundred yojanas all around, without mountains, rivers or trees, and empty of all creatures.', 'veda-app-ai-draft', true),
('ramayana-4-42-19', 'en', 'Crossing that hair-raising wilderness quickly, you will reach the white mountain Kailasa and rejoice.', 'veda-app-ai-draft', true),
('ramayana-4-42-20', 'en', 'There is Kubera''s heavenly palace, like a white cloud, adorned with gold, built by Vishvakarma.', 'veda-app-ai-draft', true),
('ramayana-4-42-21', 'en', 'There is a wide lotus pond full of lotuses and lilies, crowded with swans and ducks and visited by troops of apsaras.', 'veda-app-ai-draft', true),
('ramayana-4-42-22', 'en', 'There King Vaishravana, honoured by all beings, the glorious giver of wealth and king of yakshas, delights with the guhyakas.', 'veda-app-ai-draft', true),
('ramayana-4-42-23', 'en', 'In its moon-bright mountains and caves, Ravana must be searched for with Vaidehi here and there.', 'veda-app-ai-draft', true),
('ramayana-4-42-24', 'en', 'Reaching Mount Krauncha, its tunnel is very hard to pass. It must be entered carefully, for it is known to be hard to enter.', 'veda-app-ai-draft', true),
('ramayana-4-42-25', 'en', 'For great souls bright as the sun live there, great sages in the form of gods, fully honoured even by the gods.', 'veda-app-ai-draft', true),
('ramayana-4-42-26', 'en', 'Krauncha''s other caves, slopes, peaks, valleys and ridges must be searched here and there.', 'veda-app-ai-draft', true),
('ramayana-4-42-27', 'en', 'After looking over the peak of Krauncha here and there, see the treeless Kamashaila and Manasa, home of birds.', 'veda-app-ai-draft', true),
('ramayana-4-42-28', 'en', 'No creatures go there, neither gods, danavas nor rakshasas. That mountain with its slopes and plateaus must be searched by all of you.', 'veda-app-ai-draft', true),
('ramayana-4-42-29', 'en', 'Beyond Mount Krauncha is a mountain named Mainaka, where the danava Maya built his own house.', 'veda-app-ai-draft', true),
('ramayana-4-42-30', 'en', 'Mainaka must be searched with its slopes, plateaus and caves. Here and there are homes of horse-faced women.', 'veda-app-ai-draft', true),
('ramayana-4-42-31', 'en', 'Passing that region, there is a hermitage frequented by siddhas, where siddhas, Vaikhanasas and Valakhilya ascetics live.', 'veda-app-ai-draft', true),
('ramayana-4-42-32', 'en', 'Those ascetics, perfected by austerity and free of sin, must be honoured and humbly asked for news of Sita.', 'veda-app-ai-draft', true),
('ramayana-4-42-33', 'en', 'There is the Vaikhanasa lake, covered with golden lotuses and visited by lovely swans like the rising sun.', 'veda-app-ai-draft', true),
('ramayana-4-42-34', 'en', 'Kubera''s riding elephant, known as Sarvabhauma, always roams that region with his females.', 'veda-app-ai-draft', true),
('ramayana-4-42-35', 'en', 'Beyond that lake is a sky without moon or sun, without stars, without clouds and without sound.', 'veda-app-ai-draft', true),
('ramayana-4-42-36', 'en', 'That region shines as if with the sun''s rays, from self-luminous, godlike ascetics resting there, perfected by austerity.', 'veda-app-ai-draft', true),
('ramayana-4-42-37', 'en', 'Beyond that region is a river named Shailoda, on both banks of which grow bamboos called kichaka.', 'veda-app-ai-draft', true),
('ramayana-4-42-38', 'en', 'They carry the siddhas to the far shore and bring them back. There are the Uttara Kurus, the refuge of those who did good deeds.', 'veda-app-ai-draft', true),
('ramayana-4-42-39', 'en', 'There thousands of rivers flow with golden lotus ponds, rich in leaves of blue beryl.', 'veda-app-ai-draft', true),
('ramayana-4-42-40', 'en', 'The lakes there shine like the rising sun, adorned with groves of red lotuses and golden ones.', 'veda-app-ai-draft', true),
('ramayana-4-42-41', 'en', 'That land is covered all over with colourful groves of blue lotuses, with leaves of precious gems and golden filaments.', 'veda-app-ai-draft', true),
('ramayana-4-42-42', 'en', 'The rivers there have banks raised from matchless pearls, costly gems and gold.', 'veda-app-ai-draft', true),
('ramayana-4-42-43', 'en', 'They are entered by fine mountains made of every jewel and of gold, bright as fire.', 'veda-app-ai-draft', true),
('ramayana-4-42-44', 'en', 'The trees there always bear flowers and fruits, are full of birds, and yield every desire with heavenly scent, taste and touch.', 'veda-app-ai-draft', true),
('ramayana-4-42-45', 'en', 'Other fine trees bear clothes of many kinds, and ornaments set with pearls and beryl.', 'veda-app-ai-draft', true),
('ramayana-4-42-46', 'en', 'Other fine trees bear things fit for women and men, pleasant to enjoy in every season.', 'veda-app-ai-draft', true),
('ramayana-4-42-47', 'en', 'Other fine trees produce costly, colourful golden beds with bright covers.', 'veda-app-ai-draft', true),
('ramayana-4-42-48', 'en', 'Other trees there bear garlands that please the mind, costly drinks and many kinds of food.', 'veda-app-ai-draft', true),
('ramayana-4-42-49', 'en', 'Women endowed with virtue, beauty and youth, and gandharvas, kinnaras, siddhas, nagas and vidyadharas bright as the sun, delight there together with women.', 'veda-app-ai-draft', true),
('ramayana-4-42-50', 'en', 'All have done good deeds, all are devoted to joy, all live with their partners, having pleasure and wealth.', 'veda-app-ai-draft', true),
('ramayana-4-42-51', 'en', 'The sound of song and music with loud laughter is always heard there, delighting all beings.', 'veda-app-ai-draft', true),
('ramayana-4-42-52', 'en', 'There no one is unhappy and no one loves the unworthy. Day by day lovely virtues grow there.', 'veda-app-ai-draft', true),
('ramayana-4-42-53', 'en', 'Beyond that land is the northern ocean, in the middle of which is a great golden mountain named Somagiri.', 'veda-app-ai-draft', true),
('ramayana-4-42-54', 'en', 'The gods who have gone to Indra''s world and to Brahma''s world gaze at that king of mountains that has reached heaven.', 'veda-app-ai-draft', true),
('ramayana-4-42-55', 'en', 'That region, though without sun, is lit by its glow and is known by a sun-like splendour, as if by the austerity of Vivasvan.', 'veda-app-ai-draft', true),
('ramayana-4-42-56', 'en', 'There dwells the Lord, soul of the universe, Shambhu in his eleven forms, and Brahma, lord of gods, surrounded by brahmarshis.', 'veda-app-ai-draft', true),
('ramayana-4-42-57', 'en', 'You must not go north of the Kurus in any way. Other beings too cannot pass beyond there.', 'veda-app-ai-draft', true),
('ramayana-4-42-58', 'en', 'That mountain named Somagiri is hard even for the gods to reach. Having seen it, you should quickly turn back.', 'veda-app-ai-draft', true),
('ramayana-4-42-59', 'en', 'This far the monkeys can go, chiefs of monkeys. Beyond, where there is no sun and no boundary, we do not know.', 'veda-app-ai-draft', true),
('ramayana-4-42-60', 'en', 'All that I have described must be searched, and turn your minds also to what I have not mentioned.', 'veda-app-ai-draft', true),
('ramayana-4-42-61', 'en', 'Then, by the act of finding Videha''s daughter, which is like wind and fire, a great kindness will be done to Dasharatha''s son, and an even greater one to me.', 'veda-app-ai-draft', true),
('ramayana-4-42-62', 'en', 'Then, successful, together with your kin and honoured by me with every pleasing gift, you will roam the earth with your loved ones, your enemies calmed, monkeys who uphold beings.', 'veda-app-ai-draft', true),
('ramayana-4-43-1', 'en', 'Sugriva spoke especially to Hanuman about the task, for he was sure that best of monkeys would accomplish it.', 'veda-app-ai-draft', true),
('ramayana-4-43-2', 'en', 'On earth, in the air, in the sky, in the home of the gods or in the waters, I see nothing that stops your movement, chief of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-43-3', 'en', 'You know all the worlds with their asuras, gandharvas, nagas, men and gods, their seas and mountains.', 'veda-app-ai-draft', true),
('ramayana-4-43-4', 'en', 'Your speed, swiftness, energy and agility, great monkey, are like those of your father, the mighty Wind, hero.', 'veda-app-ai-draft', true),
('ramayana-4-43-5', 'en', 'No being on earth equals you in energy. So bring about the true way to find Sita.', 'veda-app-ai-draft', true),
('ramayana-4-43-6', 'en', 'In you alone, Hanuman, are strength, intelligence, valour, attention to place and time, and wise policy, master of policy.', 'veda-app-ai-draft', true),
('ramayana-4-43-7', 'en', 'Then Raghava, seeing that the task rested on Hanuman and knowing Hanuman, reflected:', 'veda-app-ai-draft', true),
('ramayana-4-43-8', 'en', 'The monkey king is fully confident in Hanuman, and Hanuman is even more confident of accomplishing the task.', 'veda-app-ai-draft', true),
('ramayana-4-43-9', 'en', 'Since he sets out like this, proven by his deeds and chosen by his master, the fruit of the task is sure to come.', 'veda-app-ai-draft', true),
('ramayana-4-43-10', 'en', 'Seeing that monkey, excelling in resolve, the radiant one felt as if his aim were already achieved, joyful in senses and mind.', 'veda-app-ai-draft', true),
('ramayana-4-43-11', 'en', 'Then, pleased, the scorcher of foes gave him his ring marked with his own name as a token for the princess.', 'veda-app-ai-draft', true),
('ramayana-4-43-12', 'en', 'By this sign, best of monkeys, Janaka''s daughter will see without fear that you have come from me.', 'veda-app-ai-draft', true),
('ramayana-4-43-13', 'en', 'Your resolve, hero, your courage and valour, and Sugriva''s message seem to tell me of success.', 'veda-app-ai-draft', true),
('ramayana-4-43-14', 'en', 'Taking it, the best of monkeys placed it on his head with folded hands, bowed at Rama''s feet and set out.', 'veda-app-ai-draft', true),
('ramayana-4-43-15', 'en', 'Leading that great monkey army, the heroic son of the Wind looked like the clear moon in a cloudless sky, adorned with hosts of stars.', 'veda-app-ai-draft', true),
('ramayana-4-43-16', 'en', 'I rely on your great strength, son of the Wind. With your many feats of monkey valour, Hanuman, do whatever it takes to find Janaka''s daughter.', 'veda-app-ai-draft', true),
('ramayana-4-44-1', 'en', 'Understanding their master''s fierce command, the chief monkeys set out, covering the earth like locusts.', 'veda-app-ai-draft', true),
('ramayana-4-44-2', 'en', 'Rama stayed on Prasravana with Lakshmana, waiting for the month set for finding Sita.', 'veda-app-ai-draft', true),
('ramayana-4-44-3', 'en', 'The heroic monkey Shatabali set out swiftly to the lovely northern direction surrounded by the king of mountains.', 'veda-app-ai-draft', true),
('ramayana-4-44-4', 'en', 'Vinata, leader of monkey troops, went toward the eastern direction.', 'veda-app-ai-draft', true),
('ramayana-4-44-5', 'en', 'The monkey leader, son of the Wind, with Tara, Angada and others, went to the southern direction where Agastya had walked.', 'veda-app-ai-draft', true),
('ramayana-4-44-6', 'en', 'Sushena, lord of monkeys and tiger among them, set out to the fearsome western direction guarded by Varuna.', 'veda-app-ai-draft', true),
('ramayana-4-44-7', 'en', 'Having urged the chiefs of the monkey army properly in all directions, the king rejoiced, happy and at ease.', 'veda-app-ai-draft', true),
('ramayana-4-44-8', 'en', 'Urged in this way by the king, all the monkey troop leaders hurried off, each to his own direction.', 'veda-app-ai-draft', true),
('ramayana-4-44-9', 'en', 'Roaring, shouting, bellowing, crying out and running, the best monkeys went, saying: We will bring back Sita and kill Ravana!', 'veda-app-ai-draft', true),
('ramayana-4-44-10', 'en', 'I alone will kill Ravana when I meet him in battle, then crush him suddenly and carry off Janaka''s daughter.', 'veda-app-ai-draft', true),
('ramayana-4-44-11', 'en', 'You who tremble from weariness today, just stay here. I alone will bring Janaki back even from the underworld.', 'veda-app-ai-draft', true),
('ramayana-4-44-12', 'en', 'I will shatter trees, split mountains, tear the earth and stir up the seas.', 'veda-app-ai-draft', true),
('ramayana-4-44-13', 'en', 'I can leap a yojana without doubt. I can leap a hundred yojanas, even more than a hundred.', 'veda-app-ai-draft', true),
('ramayana-4-44-14', 'en', 'On land, at sea, in mountains, in forests, or even in the middle of the underworld, nothing stops my going.', 'veda-app-ai-draft', true),
('ramayana-4-44-15', 'en', 'So each of the monkeys, proud of their strength, spoke there in the presence of the monkey king.', 'veda-app-ai-draft', true),
('ramayana-4-45-1', 'en', 'When the monkey chiefs had gone, Rama said to Sugriva: How do you know the whole circle of the earth?', 'veda-app-ai-draft', true),
('ramayana-4-45-2', 'en', 'Then Sugriva, bowing humbly, said to Rama: Listen, I will tell you everything in detail, bull among men.', 'veda-app-ai-draft', true),
('ramayana-4-45-3', 'en', 'When Vali was chasing the danava named Dundubhi, in the form of a buffalo, toward the Malaya mountain,', 'veda-app-ai-draft', true),
('ramayana-4-45-4', 'en', 'the buffalo entered a cave of Malaya, and Vali too entered Malaya wanting to kill him.', 'veda-app-ai-draft', true),
('ramayana-4-45-5', 'en', 'I was left there at the cave, as one trained to guard, and Vali did not come out when a year had passed.', 'veda-app-ai-draft', true),
('ramayana-4-45-6', 'en', 'Then the cave filled with a rush of blood. Seeing it, I was amazed and stricken by grief for my brother.', 'veda-app-ai-draft', true),
('ramayana-4-45-7', 'en', 'Deciding that my elder had clearly been killed, I placed a rock like a mountain at the mouth of the cave, thinking the buffalo would perish, unable to get out.', 'veda-app-ai-draft', true),
('ramayana-4-45-8', 'en', 'Then, having lost hope of his life, I came to Kishkindha. I gained the great kingdom and Tara with Ruma, and lived there with friends, free of worry.', 'veda-app-ai-draft', true),
('ramayana-4-45-9', 'en', 'Then Vali came back after killing that chief of danavas. I gave him back the kingdom out of respect, bound by fear.', 'veda-app-ai-draft', true),
('ramayana-4-45-10', 'en', 'That wicked Vali, wanting to kill me and agitated, chased me in anger as I ran with my ministers.', 'veda-app-ai-draft', true),
('ramayana-4-45-11', 'en', 'Chased by Vali along with my followers, I saw many rivers, forests and cities.', 'veda-app-ai-draft', true),
('ramayana-4-45-12', 'en', 'Then the earth looked to me like the surface of a mirror, like a whirling firebrand, like the size of a cow''s hoofprint.', 'veda-app-ai-draft', true),
('ramayana-4-45-13', 'en', 'I went east, then took refuge in the south, then went west again in fear. As I went north, Hanuman said to me:', 'veda-app-ai-draft', true),
('ramayana-4-45-14', 'en', 'Now I remember, king, how Vali, lord of monkeys, was cursed by Matanga concerning this hermitage area.', 'veda-app-ai-draft', true),
('ramayana-4-45-15', 'en', 'If Vali enters, his head will split into a hundred pieces. Living there will be happy and free of worry for us.', 'veda-app-ai-draft', true),
('ramayana-4-45-16', 'en', 'Then we reached Mount Rishyamuka, prince, and Vali did not enter it for fear of Matanga.', 'veda-app-ai-draft', true),
('ramayana-4-45-17', 'en', 'So, king, I saw the whole circle of the earth with my own eyes, and then I came to the cave.', 'veda-app-ai-draft', true),
('ramayana-4-46-1', 'en', 'To find Vaidehi, the monkey troop leaders, directed by the monkey king, went quickly everywhere as told.', 'veda-app-ai-draft', true),
('ramayana-4-46-2', 'en', 'They searched lakes, rivers, thickets, the sky, cities, river strongholds and mountains all around.', 'veda-app-ai-draft', true),
('ramayana-4-46-3', 'en', 'All the monkey troop leaders searched the regions Sugriva had described, with their mountains, woods and forests.', 'veda-app-ai-draft', true),
('ramayana-4-46-4', 'en', 'Having searched all day, intent on finding Sita, the monkeys would gather on the ground at nightfall.', 'veda-app-ai-draft', true),
('ramayana-4-46-5', 'en', 'Every day, finding trees bearing fruit in every season in those lands, the monkeys made their beds there for the night.', 'veda-app-ai-draft', true),
('ramayana-4-46-6', 'en', 'Counting from that first day, after a month the troop leaders came back to Prasravana and met the monkey king, without hope.', 'veda-app-ai-draft', true),
('ramayana-4-46-7', 'en', 'Having searched the eastern direction as told, with his ministers, mighty Vinata came back without seeing Sita.', 'veda-app-ai-draft', true),
('ramayana-4-46-8', 'en', 'Having searched the whole northern direction, the great monkey, heroic Shatabali, came back with his army.', 'veda-app-ai-draft', true),
('ramayana-4-46-9', 'en', 'Sushena, having searched the western direction with the monkeys, came when the month was complete and approached Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-46-10', 'en', 'Coming to Sugriva, seated with Rama on the ridge of Prasravana, they saluted him and said:', 'veda-app-ai-draft', true),
('ramayana-4-46-11', 'en', 'All the mountains, forests and cities have been searched, the rivers, the shores of the sea, and all the lands.', 'veda-app-ai-draft', true),
('ramayana-4-46-12', 'en', 'All the caves you described have been searched, and the great thickets covered with spreading creepers.', 'veda-app-ai-draft', true),
('ramayana-4-46-13', 'en', 'In dense places, strongholds and rough lands, huge creatures were searched out and killed, and the dense places were searched again and again.', 'veda-app-ai-draft', true),
('ramayana-4-46-14', 'en', 'That great monkey lord, noble in character and birth, will see Maithili. Hanuman, son of the Wind, has gone to the very direction Sita went.', 'veda-app-ai-draft', true),
('ramayana-4-47-1', 'en', 'The monkey Hanuman went with Tara and Angada and began to search the region Sugriva had pointed out.', 'veda-app-ai-draft', true),
('ramayana-4-47-2', 'en', 'Having gone far with all those best monkeys, he searched the caves and thickets of the Vindhya.', 'veda-app-ai-draft', true),
('ramayana-4-47-3', 'en', 'mountain tops, river strongholds, lakes, great trees, many clumps of trees and mountains thick with trees.', 'veda-app-ai-draft', true),
('ramayana-4-47-4', 'en', 'Searching in every direction, all the heroic monkeys did not see Sita, Maithili, daughter of Janaka.', 'veda-app-ai-draft', true),
('ramayana-4-47-5', 'en', 'Eating roots and fruits of many kinds and searching, the invincible ones stayed here and there. That great region with caves and thickets was hard to search.', 'veda-app-ai-draft', true),
('ramayana-4-47-6', 'en', 'Leaving that region, all the troop leaders, fearing nothing, entered another region hard to approach.', 'veda-app-ai-draft', true),
('ramayana-4-47-7', 'en', 'There the trees bore no fruit, had no flowers and no leaves, the rivers had no water, and roots were very hard to find.', 'veda-app-ai-draft', true),
('ramayana-4-47-8', 'en', 'There were no buffaloes, deer or elephants, no tigers or birds, or any other forest creatures.', 'veda-app-ai-draft', true),
('ramayana-4-47-9', 'en', 'There were lotus ponds on dry land with glossy leaves and blooming lotuses, lovely and fragrant, yet without any bees.', 'veda-app-ai-draft', true),
('ramayana-4-47-10', 'en', 'There was a great sage named Kandu, truthful and rich in austerity, very wrathful and unassailable through his disciplines.', 'veda-app-ai-draft', true),
('ramayana-4-47-11', 'en', 'His son, a boy of ten years, died in that forest, and the great sage became angry there.', 'veda-app-ai-draft', true),
('ramayana-4-47-12', 'en', 'That righteous one cursed the whole great forest, making it shelterless, unapproachable and empty of animals and birds.', 'veda-app-ai-draft', true),
('ramayana-4-47-13', 'en', 'They searched its forest edges, the caves of its mountains and the sources of its rivers carefully.', 'veda-app-ai-draft', true),
('ramayana-4-47-14', 'en', 'Even there the great ones, wishing to please Sugriva, did not see Janaka''s daughter or Ravana who took her.', 'veda-app-ai-draft', true),
('ramayana-4-47-15', 'en', 'Entering that fearsome place covered with creepers and bushes, they saw an asura of cruel deeds who feared no god.', 'veda-app-ai-draft', true),
('ramayana-4-47-16', 'en', 'Seeing that fearsome one standing like another mountain, the monkeys all tightened their garments.', 'veda-app-ai-draft', true),
('ramayana-4-47-17', 'en', 'The mighty one said to all the monkeys: You are dead! and rushed at them in rage, raising his clenched fist.', 'veda-app-ai-draft', true),
('ramayana-4-47-18', 'en', 'As he rushed at them suddenly, Angada, Vali''s son, thinking This is Ravana, struck him with his palm.', 'veda-app-ai-draft', true),
('ramayana-4-47-19', 'en', 'Struck by Vali''s son, the asura, vomiting blood from his mouth, fell to the ground like an overturned mountain.', 'veda-app-ai-draft', true),
('ramayana-4-47-20', 'en', 'When he stopped breathing, the victorious monkeys searched almost all of that mountain cave.', 'veda-app-ai-draft', true),
('ramayana-4-47-21', 'en', 'Having searched that forest again, they all entered another fearsome mountain cave.', 'veda-app-ai-draft', true),
('ramayana-4-47-22', 'en', 'Having searched again and grown weary, they came out together and sat down sadly at the foot of a tree in a lonely place.', 'veda-app-ai-draft', true),
('ramayana-4-48-1', 'en', 'Then Angada, tired but very wise, comforted all the monkeys and spoke these words gently:', 'veda-app-ai-draft', true),
('ramayana-4-48-2', 'en', 'We have searched all around the forests, mountains, rivers, strongholds, thickets, valleys and mountain caves.', 'veda-app-ai-draft', true),
('ramayana-4-48-3', 'en', 'Yet nowhere have we found Janaki, or the demon who carried off Sita, who is like a daughter of the gods.', 'veda-app-ai-draft', true),
('ramayana-4-48-4', 'en', 'Much of our time has passed, and Sugriva''s command is fierce. So all of you together search everywhere.', 'veda-app-ai-draft', true),
('ramayana-4-48-5', 'en', 'Throwing off sloth, grief and the sleep that has come over you, search so that we may see Sita, Janaka''s daughter.', 'veda-app-ai-draft', true),
('ramayana-4-48-6', 'en', 'Perseverance, skill and an unbeaten mind are said to bring success in any task. That is why I say this.', 'veda-app-ai-draft', true),
('ramayana-4-48-7', 'en', 'Even now let the forest dwellers search this hard forest. Throwing off weariness, let this whole forest be searched again.', 'veda-app-ai-draft', true),
('ramayana-4-48-8', 'en', 'The fruit of work that is done is surely seen. Enough of losing heart; giving up does not suit us.', 'veda-app-ai-draft', true),
('ramayana-4-48-9', 'en', 'Sugriva is a wrathful king who punishes sharply, monkeys. We must always fear him and great Rama.', 'veda-app-ai-draft', true),
('ramayana-4-48-10', 'en', 'I have said this for your good. Do it if you agree, or tell me what is best for all of us, monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-48-11', 'en', 'Hearing Angada''s words, Gandhamadana spoke in an unclear voice, worn by thirst and weariness:', 'veda-app-ai-draft', true),
('ramayana-4-48-12', 'en', 'What Angada has said is truly worthy of you. It is good and suitable; let his words be followed.', 'veda-app-ai-draft', true),
('ramayana-4-48-13', 'en', 'Let us search again the mountains, grottoes and valleys, the empty forests and mountain springs,', 'veda-app-ai-draft', true),
('ramayana-4-48-14', 'en', 'all the places great Sugriva named. Let all search the forest and the mountain strongholds everywhere.', 'veda-app-ai-draft', true),
('ramayana-4-48-15', 'en', 'Then the mighty monkeys rose again and roamed the southern direction filled with Vindhya forests.', 'veda-app-ai-draft', true),
('ramayana-4-48-16', 'en', 'The monkeys climbed a glorious silver mountain like an autumn cloud, with peaks and valleys.', 'veda-app-ai-draft', true),
('ramayana-4-48-17', 'en', 'There the best monkeys searched the lovely lodhra forest and the saptaparna forests, longing to see Sita.', 'veda-app-ai-draft', true),
('ramayana-4-48-18', 'en', 'Climbing to its top, the tired monkeys of great valour did not see Vaidehi, Rama''s beloved queen.', 'veda-app-ai-draft', true),
('ramayana-4-48-19', 'en', 'Having looked over that mountain with many caves, the monkeys came down, looking all around.', 'veda-app-ai-draft', true),
('ramayana-4-48-20', 'en', 'Coming down to the ground, tired and dazed, they rested a moment at the foot of a tree.', 'veda-app-ai-draft', true),
('ramayana-4-48-21', 'en', 'Refreshed for a while, their weariness somewhat eased, they set out again to search the whole southern region.', 'veda-app-ai-draft', true),
('ramayana-4-48-22', 'en', 'Led by Hanuman, those bull-like monkeys set off and first roamed all over the Vindhya range.', 'veda-app-ai-draft', true),
('ramayana-4-49-1', 'en', 'Joining Tara and Angada, the monkey Hanuman searched the caves and thickets of the Vindhya.', 'veda-app-ai-draft', true),
('ramayana-4-49-2', 'en', 'He searched the caves haunted by lions and tigers all around, and the rugged places and great waterfalls of that king of mountains.', 'veda-app-ai-draft', true),
('ramayana-4-49-3', 'en', 'While they stayed there, the time for their task slipped by.', 'veda-app-ai-draft', true),
('ramayana-4-49-4', 'en', 'That region, full of caves and thickets, was vast and hard to search, yet the Wind''s son searched the entire mountain.', 'veda-app-ai-draft', true),
('ramayana-4-49-5', 'en', 'Apart from each other but never far away searched Gaja, Gavaksha, Gavaya, Sharabha and Gandhamadana,', 'veda-app-ai-draft', true),
('ramayana-4-49-6', 'en', 'Mainda and Dvivida, Hanuman and Jambavan, the crown prince Angada, and Tara the forest-dweller.', 'veda-app-ai-draft', true),
('ramayana-4-49-7', 'en', 'Having searched the southern lands hemmed in by mountain ranges, gripped by hunger and thirst, tired and longing for water, they saw a great cave covered with creepers and trees.', 'veda-app-ai-draft', true),
('ramayana-4-49-8', 'en', 'Out of it flew curlews, swans and cranes, and ruddy geese wet with water, their bodies reddened by lotus pollen.', 'veda-app-ai-draft', true),
('ramayana-4-49-9', 'en', 'Reaching that fragrant, hard-to-enter cave, the leading monkeys were filled with wonder and unease.', 'veda-app-ai-draft', true),
('ramayana-4-49-10', 'en', 'Though suspicious of the cave, those mighty, spirited monkeys approached it gladly.', 'veda-app-ai-draft', true),
('ramayana-4-49-11', 'en', 'Then Hanuman, son of the Wind, tall as a mountain peak and skilled in wild forest ways, spoke to all the monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-49-12', 'en', 'We have searched the southern lands hemmed in by mountains. We are all worn out, and I do not see Maithili.', 'veda-app-ai-draft', true),
('ramayana-4-49-13', 'en', 'And from this cave swans, curlews, cranes and ruddy geese wet with water are flying out on every side.', 'veda-app-ai-draft', true),
('ramayana-4-49-14', 'en', 'Surely there is a well or a lake with water here, for the trees by the mouth of the cave are lush and green.', 'veda-app-ai-draft', true),
('ramayana-4-49-15', 'en', 'At these words they all entered the cave wrapped in darkness, and saw a hair-raising place without moon or sun.', 'veda-app-ai-draft', true),
('ramayana-4-49-16', 'en', 'In that grim cave crowded with trees, they held on to one another and went a full yojana in.', 'veda-app-ai-draft', true),
('ramayana-4-49-17', 'en', 'Senseless, thirsty, bewildered and seeking water, they wandered in that cave for some time without giving up.', 'veda-app-ai-draft', true),
('ramayana-4-49-18', 'en', 'Thin, downcast and exhausted, despairing even of life, the heroic monkeys then saw light.', 'veda-app-ai-draft', true),
('ramayana-4-49-19', 'en', 'Reaching that place, a gentle forest free of darkness, they saw golden trees shining like blazing fire.', 'veda-app-ai-draft', true),
('ramayana-4-49-20', 'en', 'Sal, palmyra, punnaga, kakubha, vanjula and dhava trees, champaka, nagavriksha and karnikara trees in flower,', 'veda-app-ai-draft', true),
('ramayana-4-49-21', 'en', 'bright as the rising sun, with terraces of beryl, and lotus pools the colour of blue beryl, thronged with birds,', 'veda-app-ai-draft', true),
('ramayana-4-49-22', 'en', 'surrounded by great golden trees like the young sun, with large golden fish and turtles,', 'veda-app-ai-draft', true),
('ramayana-4-49-23', 'en', 'there they saw lotus ponds of clear water, and mansions of gold and of silver,', 'veda-app-ai-draft', true),
('ramayana-4-49-24', 'en', 'with windows of refined gold hung with nets of pearls, with floors of gold and silver, set with beryl and gems.', 'veda-app-ai-draft', true),
('ramayana-4-49-25', 'en', 'The monkeys saw fine houses everywhere, and trees in flower and fruit that looked like coral and gems,', 'veda-app-ai-draft', true),
('ramayana-4-49-26', 'en', 'golden bees and honey all around, and beds and seats inlaid with gems and gold,', 'veda-app-ai-draft', true),
('ramayana-4-49-27', 'en', 'and costly carriages on every side, and heaps of vessels of gold, silver and bronze,', 'veda-app-ai-draft', true),
('ramayana-4-49-28', 'en', 'heaps of heavenly aloe wood and sandalwood, and pure foods, roots and fruits,', 'veda-app-ai-draft', true),
('ramayana-4-49-29', 'en', 'costly drinks and sweet juices, piles of fine heavenly garments, colourful blankets and deerskins.', 'veda-app-ai-draft', true),
('ramayana-4-49-30', 'en', 'Searching here and there in that cave, the bold, radiant monkeys saw a woman not far away.', 'veda-app-ai-draft', true),
('ramayana-4-49-31', 'en', 'Seeing her, dressed in bark and black deerskin, an ascetic of disciplined diet, blazing as if with spiritual power, they were deeply alarmed.', 'veda-app-ai-draft', true),
('ramayana-4-49-32', 'en', 'Then Hanuman, huge as a mountain, folded his hands, saluted the elderly woman and asked: Who are you? Whose is this dwelling, this cave and these jewels? Please tell us.', 'veda-app-ai-draft', true),
('ramayana-4-50-1', 'en', 'Having said this, Hanuman spoke again to that noble ascetic in black deerskin, who followed dharma.', 'veda-app-ai-draft', true),
('ramayana-4-50-2', 'en', 'We rushed into this dark cave, worn out with hunger and thirst and utterly weary.', 'veda-app-ai-draft', true),
('ramayana-4-50-3', 'en', 'Thirsty, we entered this great golden cavern. Seeing so many wonderful things of every kind, we are shaken, bewildered and confused.', 'veda-app-ai-draft', true),
('ramayana-4-50-4', 'en', 'Whose are these golden trees bright as the rising sun, these pure foods, roots and fruits?', 'veda-app-ai-draft', true),
('ramayana-4-50-5', 'en', 'the golden mansions and silver houses, with windows of refined gold hung with nets of gems?', 'veda-app-ai-draft', true),
('ramayana-4-50-6', 'en', 'By whose power are these holy, fragrant trees of river-gold in flower and fruit?', 'veda-app-ai-draft', true),
('ramayana-4-50-7', 'en', 'How do golden lotuses grow in clear water, and how do golden fish swim with the turtles?', 'veda-app-ai-draft', true),
('ramayana-4-50-8', 'en', 'Whose ascetic power is this, and what is your own greatness? We know nothing, so please tell us everything.', 'veda-app-ai-draft', true),
('ramayana-4-50-9', 'en', 'Asked this by Hanuman, the ascetic, devoted to dharma and to the good of all beings, replied to him.', 'veda-app-ai-draft', true),
('ramayana-4-50-10', 'en', 'There was a mighty asura, a master of illusion named Maya. By his magic he made this whole golden forest.', 'veda-app-ai-draft', true),
('ramayana-4-50-11', 'en', 'He was once the divine architect of the chief asuras, and he built this heavenly golden mansion.', 'veda-app-ai-draft', true),
('ramayana-4-50-12', 'en', 'After practising austerities in the great forest for thousands of years, he won from Brahma the boon of all the wealth of Ushanas.', 'veda-app-ai-draft', true),
('ramayana-4-50-13', 'en', 'Having created all this, the mighty one, master of every desire, lived happily in this great forest for some time.', 'veda-app-ai-draft', true),
('ramayana-4-50-14', 'en', 'When that bull among asuras became attached to the nymph Hema, Indra, lord of the gods, attacked, seized his thunderbolt and killed him.', 'veda-app-ai-draft', true),
('ramayana-4-50-15', 'en', 'Brahma then gave this excellent forest to Hema, with lasting pleasures and this golden home.', 'veda-app-ai-draft', true),
('ramayana-4-50-16', 'en', 'I am Svayamprabha, daughter of Merusavarni. I guard this dwelling of Hema, best of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-50-17', 'en', 'Hema, skilled in dance and song, is my dear friend. Granted a boon by her, I protect this fine dwelling.', 'veda-app-ai-draft', true),
('ramayana-4-50-18', 'en', 'What is your task, and why have you come into these wilds? And how did you find this hidden forest?', 'veda-app-ai-draft', true),
('ramayana-4-50-19', 'en', 'First eat these foods, roots and fruits, and drink the water, then tell me everything.', 'veda-app-ai-draft', true),
('ramayana-4-51-1', 'en', 'Then, when the monkey leaders had rested, the ascetic devoted to dharma spoke to them all attentively.', 'veda-app-ai-draft', true),
('ramayana-4-51-2', 'en', 'Monkeys, if eating the fruit has eased your weariness, and if it is something I may hear, I wish to hear your story.', 'veda-app-ai-draft', true),
('ramayana-4-51-3', 'en', 'Hearing her words, Hanuman, son of the Wind, began to tell her honestly and exactly what had happened.', 'veda-app-ai-draft', true),
('ramayana-4-51-4', 'en', 'The king of the whole world, equal to great Indra and Varuna, the glorious Rama, son of Dasharatha, entered the Dandaka forest', 'veda-app-ai-draft', true),
('ramayana-4-51-5', 'en', 'with his brother Lakshmana and his wife Vaidehi. His wife was carried off by force from Janasthana by Ravana.', 'veda-app-ai-draft', true),
('ramayana-4-51-6', 'en', 'That king''s friend is the hero Sugriva, king of the monkey chiefs, who has sent us out.', 'veda-app-ai-draft', true),
('ramayana-4-51-7', 'en', 'With these chief monkeys led by Angada, we were sent to the south, the region Agastya frequented, guarded by Yama,', 'veda-app-ai-draft', true),
('ramayana-4-51-8', 'en', 'ordered: Search together for Ravana, the shape-shifting rakshasa, and for Sita, princess of Videha.', 'veda-app-ai-draft', true),
('ramayana-4-51-9', 'en', 'Having searched the whole southern region, hungry and exhausted, we sat down at the foot of a tree.', 'veda-app-ai-draft', true),
('ramayana-4-51-10', 'en', 'Pale-faced and lost in thought, we could find no shore, sunk in a great ocean of worry.', 'veda-app-ai-draft', true),
('ramayana-4-51-11', 'en', 'Then, looking around, we saw a great cave covered with creepers and trees and wrapped in darkness.', 'veda-app-ai-draft', true),
('ramayana-4-51-12', 'en', 'From it flew swans wet with water, with drops on their wings, and ospreys and cranes. I told the monkeys: Let us go in.', 'veda-app-ai-draft', true),
('ramayana-4-51-13', 'en', 'They all agreed with my reasoning, and eager to do our master''s work, said: Let us go in.', 'veda-app-ai-draft', true),
('ramayana-4-51-14', 'en', 'Then, holding one another''s hands tightly, we plunged into this dark cave.', 'veda-app-ai-draft', true),
('ramayana-4-51-15', 'en', 'This is our business, and this is why we came. We all reached you worn out and starving.', 'veda-app-ai-draft', true),
('ramayana-4-51-16', 'en', 'Tormented by hunger, we have eaten the roots and fruits you gave us in hospitality.', 'veda-app-ai-draft', true),
('ramayana-4-51-17', 'en', 'You saved us all when we were dying of hunger. Tell us what the monkeys can do for you in return.', 'veda-app-ai-draft', true),
('ramayana-4-51-18', 'en', 'Addressed this way by the monkeys, the all-knowing Svayamprabha replied to the monkey leaders.', 'veda-app-ai-draft', true),
('ramayana-4-51-19', 'en', 'I am pleased with all you mighty monkeys. I live by dharma and need nothing from anyone here.', 'veda-app-ai-draft', true),
('ramayana-4-52-1', 'en', 'Hearing these good words grounded in dharma from the ascetic of blameless conduct, Hanuman spoke to her.', 'veda-app-ai-draft', true),
('ramayana-4-52-2', 'en', 'We have all come to you for refuge, follower of dharma. The time agreed with the noble Sugriva has run out while we wandered in the cave.', 'veda-app-ai-draft', true),
('ramayana-4-52-3', 'en', 'Please lift us out of this dreadful cave.', 'veda-app-ai-draft', true),
('ramayana-4-52-4', 'en', 'Having overstayed Sugriva''s order, our lives are as good as lost. Save us all, who fear Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-52-5', 'en', 'We have a great task to do, follower of dharma, and while we stay here it remains undone.', 'veda-app-ai-draft', true),
('ramayana-4-52-6', 'en', 'Asked this by Hanuman, the ascetic said: I think it is hard for one who enters here to get out alive.', 'veda-app-ai-draft', true),
('ramayana-4-52-7', 'en', 'But by the power of my austerity, earned through discipline, I will lift all you monkeys out of this cave.', 'veda-app-ai-draft', true),
('ramayana-4-52-8', 'en', 'Close your eyes, all you leading monkeys. No one can leave with eyes open.', 'veda-app-ai-draft', true),
('ramayana-4-52-9', 'en', 'Then, eager to go, they all gladly covered their eyes with their soft-fingered hands.', 'veda-app-ai-draft', true),
('ramayana-4-52-10', 'en', 'With their faces covered by their hands, the great monkeys were lifted out of the cave by her in the blink of an eye.', 'veda-app-ai-draft', true),
('ramayana-4-52-11', 'en', 'Then the ascetic devoted to dharma comforted all the monkeys, now out of that dangerous place, and said:', 'veda-app-ai-draft', true),
('ramayana-4-52-12', 'en', 'This is the glorious Vindhya mountain, full of trees and creepers. That is Mount Prasravana, and this is the great ocean.', 'veda-app-ai-draft', true),
('ramayana-4-52-13', 'en', 'Farewell to you, best of monkeys. I will go home. Saying this, Svayamprabha went back into the splendid cave.', 'veda-app-ai-draft', true),
('ramayana-4-52-14', 'en', 'Then they saw the terrible ocean, home of Varuna, endless and roaring, churning with fearsome waves.', 'veda-app-ai-draft', true),
('ramayana-4-52-15', 'en', 'While they searched the mountain stronghold made by Maya''s magic, the month fixed by the king had passed.', 'veda-app-ai-draft', true),
('ramayana-4-52-16', 'en', 'Sitting at the foot of the Vindhya among flowering trees, the noble monkeys fell into worry.', 'veda-app-ai-draft', true),
('ramayana-4-52-17', 'en', 'Seeing the spring trees bowed with blossoms and covered with hundreds of creepers, they were filled with dread.', 'veda-app-ai-draft', true),
('ramayana-4-52-18', 'en', 'Telling each other that spring had come, and seeing the time set for their mission was lost, they sank to the ground.', 'veda-app-ai-draft', true),
('ramayana-4-52-19', 'en', 'Then the monkey with shoulders like a lion''s or a bull''s and long, thick arms, the wise crown prince Angada, spoke.', 'veda-app-ai-draft', true),
('ramayana-4-52-20', 'en', 'We all set out on the monkey king''s command. Monkeys, do you not see that a month has passed while we were in the cave?', 'veda-app-ai-draft', true),
('ramayana-4-52-21', 'en', 'Since the time Sugriva himself fixed has passed, it is fitting for all of us forest-dwellers to fast to death.', 'veda-app-ai-draft', true),
('ramayana-4-52-22', 'en', 'Sugriva is harsh by nature and firmly set in his role as master. He will not forgive us for returning guilty.', 'veda-app-ai-draft', true),
('ramayana-4-52-23', 'en', 'Without news of Sita he will surely do us harm. So it is better for us to fast to death here, today.', 'veda-app-ai-draft', true),
('ramayana-4-52-24', 'en', 'Before the king kills us all on our return, leaving sons, wives, wealth and homes behind, better to die here than by a shameful execution.', 'veda-app-ai-draft', true),
('ramayana-4-52-25', 'en', 'It was not Sugriva who made me crown prince. I was consecrated by Rama, lord of men, whose deeds are flawless.', 'veda-app-ai-draft', true),
('ramayana-4-52-26', 'en', 'The king, long hostile to me, will see this lapse and, his mind made up, will have me killed with harsh punishment.', 'veda-app-ai-draft', true),
('ramayana-4-52-27', 'en', 'What use are friends who will watch my ruin at the end of my life? I will fast to death right here on the holy seashore.', 'veda-app-ai-draft', true),
('ramayana-4-52-28', 'en', 'Hearing what the young crown prince said, all the leading monkeys spoke these pitiful words.', 'veda-app-ai-draft', true),
('ramayana-4-52-29', 'en', 'Sugriva is harsh by nature, and Rama is devoted to his beloved. If Vaidehi is not found and he sees us come back,', 'veda-app-ai-draft', true),
('ramayana-4-52-30', 'en', 'he will surely kill us to please Rama. It is not right for offenders to go back to their master.', 'veda-app-ai-draft', true),
('ramayana-4-52-31', 'en', 'Hearing the words of the frightened monkeys, Tara said: Enough of despair. Let us all go back into the cave and live there, if you like.', 'veda-app-ai-draft', true),
('ramayana-4-52-32', 'en', 'This place made by magic is very hard to reach, with plenty of trees, water, food and drink. Here we need fear neither Indra, nor Rama, nor the monkey king.', 'veda-app-ai-draft', true),
('ramayana-4-52-33', 'en', 'Hearing this, and agreeing with Angada too, all the monkeys said with confidence: Let a plan be made at once, without delay, so that we are not killed.', 'veda-app-ai-draft', true),
('ramayana-4-53-1', 'en', 'As Tara, radiant as the moon, spoke this way, Hanuman thought the kingdom was as good as seized by Angada.', 'veda-app-ai-draft', true),
('ramayana-4-53-2', 'en', 'Hanuman knew Vali''s son had the eight qualities of intellect, the four kinds of strength and the fourteen royal virtues,', 'veda-app-ai-draft', true),
('ramayana-4-53-3', 'en', 'always growing in energy, strength and courage, like the moon waxing in splendour at the start of the bright fortnight,', 'veda-app-ai-draft', true),
('ramayana-4-53-4', 'en', 'equal to Brihaspati in wisdom and to his father in valour, and listening to Tara as Indra listens to Shukra.', 'veda-app-ai-draft', true),
('ramayana-4-53-5', 'en', 'Then Hanuman, learned in all the sciences, set about winning over Angada, who had grown weary in his master''s service.', 'veda-app-ai-draft', true),
('ramayana-4-53-6', 'en', 'Using the third of the four methods, he skilfully talked all the monkeys away from Angada''s side.', 'veda-app-ai-draft', true),
('ramayana-4-53-7', 'en', 'When all of them had been won away, he made Angada afraid with many alarming words backed by the threat of force.', 'veda-app-ai-draft', true),
('ramayana-4-53-8', 'en', 'Son of Tara, you are even abler in battle than your father. You can carry the burden of the monkey kingdom firmly, as he did.', 'veda-app-ai-draft', true),
('ramayana-4-53-9', 'en', 'But monkeys are always fickle, bull among monkeys. Parted from their children and wives, they will not bear your orders.', 'veda-app-ai-draft', true),
('ramayana-4-53-10', 'en', 'I tell you openly, these will not follow you, not Jambavan, nor Nila, nor the great monkey Suhotra.', 'veda-app-ai-draft', true),
('ramayana-4-53-11', 'en', 'Neither I nor any of these can be drawn away from Sugriva by you, whether by kind words, gifts or force.', 'veda-app-ai-draft', true),
('ramayana-4-53-12', 'en', 'It is said that the weak may sit tight against the strong, but a weak one who wants to stay safe should not pick a quarrel.', 'veda-app-ai-draft', true),
('ramayana-4-53-13', 'en', 'This cave you think of as your nurse and shelter is, as we have heard, a small job for Lakshmana''s arrows to split open.', 'veda-app-ai-draft', true),
('ramayana-4-53-14', 'en', 'Indra did little when he once threw his thunderbolt here. Lakshmana could pierce it with his sharp arrows like a leaf-cup, and he has many such shafts.', 'veda-app-ai-draft', true),
('ramayana-4-53-15', 'en', 'The moment you settle in there, scorcher of foes, all the monkeys will make up their minds and leave you.', 'veda-app-ai-draft', true),
('ramayana-4-53-16', 'en', 'Remembering their children and wives, always anxious and hungry, wearied by hard beds, they will turn their backs on you.', 'veda-app-ai-draft', true),
('ramayana-4-53-17', 'en', 'Then, without friends or well-wishing kin, you will be so nervous that even a quivering blade of grass will frighten you.', 'veda-app-ai-draft', true),
('ramayana-4-53-18', 'en', 'And Lakshmana''s terrible arrows, swift and unstoppable, eager to strike a deserter, will surely not spare you.', 'veda-app-ai-draft', true),
('ramayana-4-53-19', 'en', 'But if you go back with us and present yourself humbly, Sugriva will in due course set you on the throne.', 'veda-app-ai-draft', true),
('ramayana-4-53-20', 'en', 'Your uncle loves dharma and wants your affection. He is firm in his vows, pure and true to his word. He will never want to kill you.', 'veda-app-ai-draft', true),
('ramayana-4-53-21', 'en', 'He wants to please your mother, and his life is devoted to her. He has no other child, so go back, Angada.', 'veda-app-ai-draft', true),
('ramayana-4-54-1', 'en', 'Hearing Hanuman''s courteous words, rooted in dharma and full of respect for their master, Angada replied.', 'veda-app-ai-draft', true),
('ramayana-4-54-2', 'en', 'Steadiness, purity of heart, kindness, honesty, valour and courage are not found in Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-54-3', 'en', 'He took his elder brother''s beloved queen while his brother lived, a woman who by dharma was like a mother to him. He is contemptible.', 'veda-app-ai-draft', true),
('ramayana-4-54-4', 'en', 'How can he know dharma, the wicked one who blocked the mouth of the cave when his brother had gone in to fight?', 'veda-app-ai-draft', true),
('ramayana-4-54-5', 'en', 'He forgot Rama, who had taken his hand in a truthful pact and done great service for him. Whose good deed would such a one remember?', 'veda-app-ai-draft', true),
('ramayana-4-54-6', 'en', 'He sent us to search for Sita out of fear of Lakshmana, not fear of wrongdoing. How can there be dharma in him?', 'veda-app-ai-draft', true),
('ramayana-4-54-7', 'en', 'What noble person of good family who wants to live would ever trust that sinful, ungrateful, forgetful and fickle one?', 'veda-app-ai-draft', true),
('ramayana-4-54-8', 'en', 'Whether the son is worthy or not, once he sets his own son on the throne, how will Sugriva let me, of a rival line, live?', 'veda-app-ai-draft', true),
('ramayana-4-54-9', 'en', 'My plans exposed, guilty and powerless, how can I go to Kishkindha and survive, weak and with no protector?', 'veda-app-ai-draft', true),
('ramayana-4-54-10', 'en', 'Sly, cruel and ruthless for the sake of the throne, Sugriva would secretly punish me or put me in chains.', 'veda-app-ai-draft', true),
('ramayana-4-54-11', 'en', 'Fasting to death is better for me than chains and misery. Give me leave, all of you, and let the monkeys go home.', 'veda-app-ai-draft', true),
('ramayana-4-54-12', 'en', 'I promise you I will not go to the city. I will fast to death right here. Death is better for me.', 'veda-app-ai-draft', true),
('ramayana-4-54-13', 'en', 'Greet my uncle the king respectfully and wish him well: Sugriva, lord of the monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-54-14', 'en', 'Give my mother Ruma my good wishes for her health, and please comfort my mother Tara.', 'veda-app-ai-draft', true),
('ramayana-4-54-15', 'en', 'She loves her son by nature, is tender-hearted and suffering. Hearing that I died here, she will surely give up her life.', 'veda-app-ai-draft', true),
('ramayana-4-54-16', 'en', 'Having said this and saluted his elders, Angada lay down weeping on the darbha grass, sick at heart.', 'veda-app-ai-draft', true),
('ramayana-4-54-17', 'en', 'As he lay down there, the leading monkeys wept, shedding hot tears in their grief.', 'veda-app-ai-draft', true),
('ramayana-4-54-18', 'en', 'Blaming Sugriva and praising Vali, they all gathered round Angada and resolved to fast to death.', 'veda-app-ai-draft', true),
('ramayana-4-54-19', 'en', 'Knowing the mind of Vali''s son, the monkeys all touched water and sat facing east on darbha grass pointing south, on the northern shore.', 'veda-app-ai-draft', true),
('ramayana-4-54-20', 'en', 'With the many monkeys lying there, as big as great mountain peaks, that mountain', 'veda-app-ai-draft', true),
('ramayana-4-54-21', 'en', 'rang inside its waterfalls, as if with loud, roaring thunderclouds.', 'veda-app-ai-draft', true),
('ramayana-4-55-1', 'en', 'To the mountain slope where all the monkeys sat fasting came the king of vultures.', 'veda-app-ai-draft', true),
('ramayana-4-55-2', 'en', 'He was the long-lived bird named Sampati, glorious brother of Jatayu, famous for his strength and might.', 'veda-app-ai-draft', true),
('ramayana-4-55-3', 'en', 'Coming out of a cave of the great Vindhya mountain and seeing the monkeys sitting there, he spoke gladly.', 'veda-app-ai-draft', true),
('ramayana-4-55-4', 'en', 'Fate, it seems, follows a creature in this world by its own design, since this food meant for me has come to me after so long.', 'veda-app-ai-draft', true),
('ramayana-4-55-5', 'en', 'I will eat these monkeys one by one as each dies. So the bird spoke, looking at the monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-55-6', 'en', 'Hearing the words of that bird greedy for food, Angada, deeply troubled, said to Hanuman:', 'veda-app-ai-draft', true),
('ramayana-4-55-7', 'en', 'Look, Yama himself, son of Vivasvan, has come to this place in the guise of Sita''s cause, to destroy the monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-55-8', 'en', 'Rama''s work is not done, nor the king''s order carried out, and this unforeseen disaster has suddenly fallen on the monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-55-9', 'en', 'You have all heard in full what the vulture king Jatayu did there out of love for Vaidehi.', 'veda-app-ai-draft', true),
('ramayana-4-55-10', 'en', 'In the same way all creatures, even those born as animals, do what pleases Rama by giving up their lives, as we are doing.', 'veda-app-ai-draft', true),
('ramayana-4-55-11', 'en', 'For Rama''s sake we wore ourselves out and gave up our lives. We went through the wilds, yet we do not see Maithili.', 'veda-app-ai-draft', true),
('ramayana-4-55-12', 'en', 'Happy is the vulture king, killed by Ravana in battle. He is free from fear of Sugriva and has reached the highest state.', 'veda-app-ai-draft', true),
('ramayana-4-55-13', 'en', 'Through Jatayu''s death, King Dasharatha''s death and the abduction of Vaidehi, the monkeys have come into peril.', 'veda-app-ai-draft', true),
('ramayana-4-55-14', 'en', 'Rama and Lakshmana living in the forest with Sita, Vali''s death by Rama''s arrow,', 'veda-app-ai-draft', true),
('ramayana-4-55-15', 'en', 'and the slaughter of all the rakshasas by Rama''s anger: all this harm came from Kaikeyi''s boons.', 'veda-app-ai-draft', true),
('ramayana-4-55-16', 'en', 'Hearing these words from Angada''s mouth, the sharp-beaked, loud-voiced vulture spoke.', 'veda-app-ai-draft', true),
('ramayana-4-55-17', 'en', 'Who is this, proclaiming the death of my brother Jatayu, dearer to me than life, shaking my heart?', 'veda-app-ai-draft', true),
('ramayana-4-55-18', 'en', 'How did a battle between a rakshasa and a vulture happen in Janasthana? I hear my brother''s name today after so long.', 'veda-app-ai-draft', true),
('ramayana-4-55-19', 'en', 'Best of monkeys, I wish to hear about the death of my younger brother, who knew virtue and was praised for his valour,', 'veda-app-ai-draft', true),
('ramayana-4-55-20', 'en', 'my brother Jatayu who lived in Janasthana. And how was Dasharatha my brother''s friend, he whose eldest, beloved son is Rama, loved by his elders?', 'veda-app-ai-draft', true),
('ramayana-4-55-21', 'en', 'My wings are burnt by the sun''s rays, so I cannot move. I want to come down from this mountain, tamers of foes.', 'veda-app-ai-draft', true),
('ramayana-4-56-1', 'en', 'Though they heard his voice broken with grief, the monkey leaders did not believe him, suspicious because of what he had said before.', 'veda-app-ai-draft', true),
('ramayana-4-56-2', 'en', 'Seeing the vulture as they sat fasting, the monkeys had a grim thought: He will eat us all.', 'veda-app-ai-draft', true),
('ramayana-4-56-3', 'en', 'If he eats us while we sit fasting, we will have done our part and soon reach our goal.', 'veda-app-ai-draft', true),
('ramayana-4-56-4', 'en', 'With this thought all the leading monkeys brought the vulture down from the peak, and Angada spoke to him.', 'veda-app-ai-draft', true),
('ramayana-4-56-5', 'en', 'There was a mighty monkey king named Riksharaja, my grandfather, bird. His two sons were righteous,', 'veda-app-ai-draft', true),
('ramayana-4-56-6', 'en', 'Sugriva and Vali, both of overwhelming strength. King Vali, my father, was famous in the world for his deeds.', 'veda-app-ai-draft', true),
('ramayana-4-56-7', 'en', 'The king of the whole world, the great chariot warrior of the Ikshvakus, glorious Rama son of Dasharatha, entered the Dandaka forest', 'veda-app-ai-draft', true),
('ramayana-4-56-8', 'en', 'with his brother Lakshmana and his wife Vaidehi, devoted to his father''s command and keeping to the path of dharma. His wife was carried off by force from Janasthana by Ravana.', 'veda-app-ai-draft', true),
('ramayana-4-56-9', 'en', 'Jatayu, the vulture king, friend of Rama''s father, saw Sita of Videha being carried away through the sky.', 'veda-app-ai-draft', true),
('ramayana-4-56-10', 'en', 'He knocked Ravana out of his chariot and set Maithili down, but tired and old, he was killed by Ravana in battle.', 'veda-app-ai-draft', true),
('ramayana-4-56-11', 'en', 'So the vulture was killed by the far stronger Ravana, cremated by Rama, and went to the highest state.', 'veda-app-ai-draft', true),
('ramayana-4-56-12', 'en', 'Then Rama made friends with my uncle, the great Sugriva, and killed my father.', 'veda-app-ai-draft', true),
('ramayana-4-56-13', 'en', 'Sugriva and his ministers were at odds with my father. Rama killed Vali and then crowned Sugriva.', 'veda-app-ai-draft', true),
('ramayana-4-56-14', 'en', 'Set on the throne by him, Sugriva is lord of the monkeys, king of the monkey chiefs, and he sent us out.', 'veda-app-ai-draft', true),
('ramayana-4-56-15', 'en', 'Sent by Rama, we have searched everywhere but cannot find Vaidehi, like sunlight at night.', 'veda-app-ai-draft', true),
('ramayana-4-56-16', 'en', 'After carefully searching the Dandaka forest, we unknowingly entered a cave open in the earth.', 'veda-app-ai-draft', true),
('ramayana-4-56-17', 'en', 'While we searched that cave made by Maya''s magic, the month fixed by the king passed.', 'veda-app-ai-draft', true),
('ramayana-4-56-18', 'en', 'All of us are servants of the monkey king. Having broken the agreed limit, we sit fasting out of fear.', 'veda-app-ai-draft', true),
('ramayana-4-56-19', 'en', 'With Rama, Sugriva and Lakshmana angry, none of us would live even if we went back.', 'veda-app-ai-draft', true),
('ramayana-4-57-1', 'en', 'Spoken to so pitifully by the monkeys who had given up on life, the loud-voiced vulture replied in tears.', 'veda-app-ai-draft', true),
('ramayana-4-57-2', 'en', 'Monkeys, Jatayu, whom you say was killed in battle by the mighty Ravana, was my younger brother.', 'veda-app-ai-draft', true),
('ramayana-4-57-3', 'en', 'Old and wingless, I must bear even hearing this. I have no strength now to avenge my brother.', 'veda-app-ai-draft', true),
('ramayana-4-57-4', 'en', 'Long ago, when Vritra had been slain, Jatayu and I, eager to win, flew towards the blazing, ray-wreathed sun.', 'veda-app-ai-draft', true),
('ramayana-4-57-5', 'en', 'We sped along the path of the sky at great speed. When the sun reached midday, Jatayu began to sink.', 'veda-app-ai-draft', true),
('ramayana-4-57-6', 'en', 'Seeing my brother scorched by the sun''s rays and in great distress, out of love I covered him with my wings.', 'veda-app-ai-draft', true),
('ramayana-4-57-7', 'en', 'With my wings burnt, I fell on the Vindhya, best of monkeys. Living here, I have had no news of my brother.', 'veda-app-ai-draft', true),
('ramayana-4-57-8', 'en', 'Spoken to thus by Sampati, Jatayu''s brother, the wise crown prince Angada replied.', 'veda-app-ai-draft', true),
('ramayana-4-57-9', 'en', 'If you are Jatayu''s brother and have heard what I said, tell us, if you know, where that rakshasa lives.', 'veda-app-ai-draft', true),
('ramayana-4-57-10', 'en', 'If you know whether that short-sighted rakshasa king Ravana is near or far, tell us.', 'veda-app-ai-draft', true),
('ramayana-4-57-11', 'en', 'Then the radiant elder brother of Jatayu spoke words worthy of himself, delighting the monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-57-12', 'en', 'Monkeys, I am a vulture with burnt wings and no strength left, but with words alone I will give Rama the best help.', 'veda-app-ai-draft', true),
('ramayana-4-57-13', 'en', 'I know the realms of Varuna, and Vishnu''s three strides, the battles of gods and asuras, and the churning for the nectar.', 'veda-app-ai-draft', true),
('ramayana-4-57-14', 'en', 'This task of Rama''s is the first thing I must do, though old age has taken my vigour and my life breath is weak.', 'veda-app-ai-draft', true),
('ramayana-4-57-15', 'en', 'I saw a beautiful young woman, adorned with every ornament, being carried off by the wicked Ravana.', 'veda-app-ai-draft', true),
('ramayana-4-57-16', 'en', 'The lovely lady was crying Rama, Rama and Lakshmana, throwing off her ornaments and twisting her body.', 'veda-app-ai-draft', true),
('ramayana-4-57-17', 'en', 'Her fine silk shone against the dark rakshasa like sunlight on a mountain peak, or lightning in a cloud.', 'veda-app-ai-draft', true),
('ramayana-4-57-18', 'en', 'Since she called out Rama''s name, I think she was Sita. Hear me as I tell you where that rakshasa lives.', 'veda-app-ai-draft', true),
('ramayana-4-57-19', 'en', 'The rakshasa named Ravana, son of Vishravas and brother of Vaishravana, lives in the city of Lanka.', 'veda-app-ai-draft', true),
('ramayana-4-57-20', 'en', 'From here, on an island in the ocean a full hundred yojanas away, is the lovely city of Lanka, built by Vishvakarma.', 'veda-app-ai-draft', true),
('ramayana-4-57-21', 'en', 'There Vaidehi lives in misery, wearing silk, confined in Ravana''s inner palace, closely guarded by rakshasa women.', 'veda-app-ai-draft', true),
('ramayana-4-57-22', 'en', 'There, in Lanka, guarded by the ocean on every side, you will see Maithili, daughter of King Janaka.', 'veda-app-ai-draft', true),
('ramayana-4-57-23', 'en', 'Cross to the far side of the ocean, a full hundred yojanas, reach the southern shore, and there you will see Ravana.', 'veda-app-ai-draft', true),
('ramayana-4-57-24', 'en', 'Hurry there quickly and show your courage, monkeys. By my insight I see that you will find her and return.', 'veda-app-ai-draft', true),
('ramayana-4-57-25', 'en', 'The first path of the sky belongs to sparrows and grain-eaters, the second to crows and birds that eat tree fruit,', 'veda-app-ai-draft', true),
('ramayana-4-57-26', 'en', 'the third to bhasa birds, curlews and ospreys, the fourth to hawks, and vultures fly the fifth.', 'veda-app-ai-draft', true),
('ramayana-4-57-27', 'en', 'The sixth path is for swans, strong and beautiful, and highest of all is the course of Garuda. All of us are descended from Garuda, best of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-57-28', 'en', 'Because of some blameworthy deed, we eat flesh. From here I can see Ravana and Janaki.', 'veda-app-ai-draft', true),
('ramayana-4-57-29', 'en', 'We too have divine, golden power of sight. So by the strength of our food and by nature, monkeys, we always see more than a hundred yojanas.', 'veda-app-ai-draft', true),
('ramayana-4-57-30', 'en', 'By nature our food is found far away, while birds that fight with their feet find theirs at their feet.', 'veda-app-ai-draft', true),
('ramayana-4-57-31', 'en', 'Find some way to leap across the salt sea. Once you reach Vaidehi, you will return with your goal achieved.', 'veda-app-ai-draft', true),
('ramayana-4-57-32', 'en', 'I want you to carry me to the ocean, home of Varuna. I will offer water for my great brother who has gone to heaven.', 'veda-app-ai-draft', true),
('ramayana-4-57-33', 'en', 'Then the mighty monkeys carried Sampati, his wings burnt, to a place on the shore of the lord of rivers,', 'veda-app-ai-draft', true),
('ramayana-4-57-34', 'en', 'and brought the king of birds back again to his place. The monkeys were overjoyed to have the news.', 'veda-app-ai-draft', true),
('ramayana-4-58-1', 'en', 'Hearing the vulture king''s words, sweet as nectar, the leading monkeys were delighted.', 'veda-app-ai-draft', true),
('ramayana-4-58-2', 'en', 'Jambavan, best of monkeys, rose suddenly from the ground with all the monkeys and spoke to the vulture king.', 'veda-app-ai-draft', true),
('ramayana-4-58-3', 'en', 'Where is Sita? Who saw her? Who carried Maithili off? Tell us everything, and be the refuge of the forest-dwellers.', 'veda-app-ai-draft', true),
('ramayana-4-58-4', 'en', 'Who does not fear the might of Rama''s arrows, which strike with the force of thunderbolts, and those loosed by Lakshmana himself?', 'veda-app-ai-draft', true),
('ramayana-4-58-5', 'en', 'Pleased, he comforted again the monkeys, who were filled with affection and intent on hearing of Sita, and said:', 'veda-app-ai-draft', true),
('ramayana-4-58-6', 'en', 'Hear how I learned of Vaidehi''s abduction, who told me, and where the wide-eyed lady is.', 'veda-app-ai-draft', true),
('ramayana-4-58-7', 'en', 'I fell long ago on this rugged mountain stretching many yojanas, and now I am old, with little life or strength left.', 'veda-app-ai-draft', true),
('ramayana-4-58-8', 'en', 'My son, named Suparshva, best of birds, feeds me in this condition at the proper times.', 'veda-app-ai-draft', true),
('ramayana-4-58-9', 'en', 'Gandharvas are fierce in desire, serpents fierce in anger, deer in fear, and we in hunger.', 'veda-app-ai-draft', true),
('ramayana-4-58-10', 'en', 'One day, when I was hungry and longing for food, my son came after sunset without any meat.', 'veda-app-ai-draft', true),
('ramayana-4-58-11', 'en', 'Gripped by hunger and thirst, cranky with age and anger, I scolded the young bird, best of flyers.', 'veda-app-ai-draft', true),
('ramayana-4-58-12', 'en', 'Hurt by my holding back food from him, my loving son respectfully told me the truth.', 'veda-app-ai-draft', true),
('ramayana-4-58-13', 'en', 'Father, I flew into the sky at the proper time looking for meat, and stationed myself blocking the pass of Mount Mahendra.', 'veda-app-ai-draft', true),
('ramayana-4-58-14', 'en', 'There, alone and facing downwards, I set out to block the path of thousands of creatures that move across the ocean.', 'veda-app-ai-draft', true),
('ramayana-4-58-15', 'en', 'There I saw someone like a heap of black collyrium, going along carrying a woman radiant as the rising sun.', 'veda-app-ai-draft', true),
('ramayana-4-58-16', 'en', 'Wanting them for food, I made up my mind, but he politely asked me with soft words to let him pass.', 'veda-app-ai-draft', true),
('ramayana-4-58-17', 'en', 'No one anywhere, even among low folk, strikes those who come with gentle words, so how much less one like me?', 'veda-app-ai-draft', true),
('ramayana-4-58-18', 'en', 'He flew on through the sky with such force that he seemed to shrink it. Then beings that move in the sky came and honoured me.', 'veda-app-ai-draft', true),
('ramayana-4-58-19', 'en', 'The great sages said to me: Luckily you are alive, son. He and the woman with him got past you safely, no doubt.', 'veda-app-ai-draft', true),
('ramayana-4-58-20', 'en', 'So those glorious siddhas told me, and they told me he was Ravana, king of the rakshasas.', 'veda-app-ai-draft', true),
('ramayana-4-58-21', 'en', 'He was carrying off Janaka''s daughter, wife of Rama son of Dasharatha, her ornaments and silks slipping, overcome with grief,', 'veda-app-ai-draft', true),
('ramayana-4-58-22', 'en', 'her hair loose, crying the names of Rama and Lakshmana. That is why I was late, said that master of speech.', 'veda-app-ai-draft', true),
('ramayana-4-58-23', 'en', 'Suparshva told me all this. Even hearing it, I had no thought of fighting.', 'veda-app-ai-draft', true),
('ramayana-4-58-24', 'en', 'How can a wingless bird attempt any deed? But what I can do, through words and insight,', 'veda-app-ai-draft', true),
('ramayana-4-58-25', 'en', 'hear it, I will tell you, since it rests on your courage. With words and counsel I will do what pleases you all, for Rama''s work is mine, there is no doubt.', 'veda-app-ai-draft', true),
('ramayana-4-58-26', 'en', 'You are best in wisdom, strong and high-minded. United with the monkey king, even the gods cannot overcome you.', 'veda-app-ai-draft', true),
('ramayana-4-58-27', 'en', 'The sharp, heron-feathered arrows of Rama and Lakshmana are enough to protect or punish all three worlds.', 'veda-app-ai-draft', true),
('ramayana-4-58-28', 'en', 'Ravana surely has energy and strength, but nothing is too hard for capable ones like you.', 'veda-app-ai-draft', true),
('ramayana-4-58-29', 'en', 'So stop wasting time and make your decision. Wise ones like you do not falter in their tasks.', 'veda-app-ai-draft', true),
('ramayana-4-59-1', 'en', 'Then the monkey leaders sat down around the vulture on the rugged mountain after he had bathed and offered water.', 'veda-app-ai-draft', true),
('ramayana-4-59-2', 'en', 'Gaining their trust, Sampati gladly spoke again to Angada, who sat surrounded by all the monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-59-3', 'en', 'Let the monkeys be silent and listen closely. I will tell the truth of how I know about Maithili.', 'veda-app-ai-draft', true),
('ramayana-4-59-4', 'en', 'Long ago I fell in the forest on this Vindhya peak, my body seared by the sun''s heat, burnt by its rays.', 'veda-app-ai-draft', true),
('ramayana-4-59-5', 'en', 'Regaining consciousness after six nights, helpless and dazed, I looked in every direction and recognised nothing.', 'veda-app-ai-draft', true),
('ramayana-4-59-6', 'en', 'Then, looking at the seas, mountains, rivers, lakes, forests and wild lands, my memory returned.', 'veda-app-ai-draft', true),
('ramayana-4-59-7', 'en', 'Full of happy flocks of birds, with caves and peaks, I decided this was the Vindhya on the shore of the southern ocean.', 'veda-app-ai-draft', true),
('ramayana-4-59-8', 'en', 'Here was a holy hermitage honoured even by the gods, where a sage named Nishakara practised fierce austerities.', 'veda-app-ai-draft', true),
('ramayana-4-59-9', 'en', 'I have lived here eight thousand years without that sage, knowers of dharma, since Nishakara went to heaven.', 'veda-app-ai-draft', true),
('ramayana-4-59-10', 'en', 'Slowly and painfully I came down from the rough Vindhya peak to the ground covered with sharp darbha grass.', 'veda-app-ai-draft', true),
('ramayana-4-59-11', 'en', 'I wanted to see that sage and came to him with great difficulty, for Jatayu and I had visited him many times.', 'veda-app-ai-draft', true),
('ramayana-4-59-12', 'en', 'Near his hermitage fragrant breezes blew. No tree was seen without flowers or fruit.', 'veda-app-ai-draft', true),
('ramayana-4-59-13', 'en', 'Reaching the holy hermitage, I rested at the foot of a tree and waited to see the blessed Nishakara.', 'veda-app-ai-draft', true),
('ramayana-4-59-14', 'en', 'Then I saw the sage nearby, blazing with power, having bathed, unassailable, returning and facing north.', 'veda-app-ai-draft', true),
('ramayana-4-59-15', 'en', 'Bears, deer, tigers, lions, elephants and reptiles surrounded him and came close, as living beings gather round a giver.', 'veda-app-ai-draft', true),
('ramayana-4-59-16', 'en', 'Knowing the sage had arrived, those creatures left, as a king''s whole retinue with his ministers withdraws when he goes in.', 'veda-app-ai-draft', true),
('ramayana-4-59-17', 'en', 'The sage was pleased to see me, went into his hermitage, and coming out after a moment, asked my business.', 'veda-app-ai-draft', true),
('ramayana-4-59-18', 'en', 'Gentle one, seeing your feathers so damaged, I do not recognise you. Your wings are burnt by fire and your skin is wounded.', 'veda-app-ai-draft', true),
('ramayana-4-59-19', 'en', 'I have seen two vultures before, swift as the wind, kings of vultures, brothers, able to take any form.', 'veda-app-ai-draft', true),
('ramayana-4-59-20', 'en', 'You are the elder, Sampati, and Jatayu is your younger brother. You used to take human form and clasp my feet.', 'veda-app-ai-draft', true),
('ramayana-4-59-21', 'en', 'What illness is this? How did your wings fall? Who dealt you this punishment? Tell me everything I ask.', 'veda-app-ai-draft', true),
('ramayana-4-60-1', 'en', 'Then I told the sage all about that terrible, reckless deed done out of rashness, how we had followed the sun.', 'veda-app-ai-draft', true),
('ramayana-4-60-2', 'en', 'Blessed one, with my wounds and my shame, my senses are confused and I am too tired to speak.', 'veda-app-ai-draft', true),
('ramayana-4-60-3', 'en', 'Jatayu and I, deluded by pride and rivalry, flew up into the sky, wanting to test our strength.', 'veda-app-ai-draft', true),
('ramayana-4-60-4', 'en', 'We made a wager before the sages on the peak of Kailasa: the sun must be followed until it sets behind the great western mountain.', 'veda-app-ai-draft', true),
('ramayana-4-60-5', 'en', 'Then together we reached the sky and saw below on the earth cities, each like a chariot wheel in size.', 'veda-app-ai-draft', true),
('ramayana-4-60-6', 'en', 'Here and there we heard the sound of music and of Vedic chanting, and we saw many women in red singing.', 'veda-app-ai-draft', true),
('ramayana-4-60-7', 'en', 'Quickly flying up into the sky and taking the sun''s path, we looked down at the forest lying like a green lawn.', 'veda-app-ai-draft', true),
('ramayana-4-60-8', 'en', 'The earth seemed strewn with pebbles that were mountains, and wrapped in rivers as if with threads.', 'veda-app-ai-draft', true),
('ramayana-4-60-9', 'en', 'Himavat, the Vindhya and the great mountain Meru shone on the earth like elephants in a pond.', 'veda-app-ai-draft', true),
('ramayana-4-60-10', 'en', 'Then heavy sweat, exhaustion and fear came over us, and confusion, and from confusion a dreadful faint.', 'veda-app-ai-draft', true),
('ramayana-4-60-11', 'en', 'We could not tell south from east or west. The world seemed destroyed, as if burnt by fire at the end of an age.', 'veda-app-ai-draft', true),
('ramayana-4-60-12', 'en', 'With great effort we looked at the sun again, and it seemed to us as large as the earth.', 'veda-app-ai-draft', true),
('ramayana-4-60-13', 'en', 'Then Jatayu, without telling me, dropped towards the earth. Seeing him, I quickly let myself fall from the sky.', 'veda-app-ai-draft', true),
('ramayana-4-60-14', 'en', 'Shielded by my wings, Jatayu was not burnt, but through carelessness I was scorched as I fell from the path of the wind.', 'veda-app-ai-draft', true),
('ramayana-4-60-15', 'en', 'I believe Jatayu fell in Janasthana, while I fell on the Vindhya, my wings burnt and my body numbed.', 'veda-app-ai-draft', true),
('ramayana-4-60-16', 'en', 'Robbed of my kingdom, my brother, my wings and my strength, I want only to die, and I will throw myself from the mountain peak.', 'veda-app-ai-draft', true),
('ramayana-4-61-1', 'en', 'Having said this to the great sage, I wept in deep sorrow. Then the blessed one, after reflecting a moment, said this.', 'veda-app-ai-draft', true),
('ramayana-4-61-2', 'en', 'You will grow new wings and feathers, and your sight, life breath, courage and strength will return.', 'veda-app-ai-draft', true),
('ramayana-4-61-3', 'en', 'I have heard of a great task to come, told in the old lore. I have seen it through austerity, and I know it from what I have heard.', 'veda-app-ai-draft', true),
('ramayana-4-61-4', 'en', 'There will be a king named Dasharatha, a joy of the Ikshvaku line. His son, of great splendour, will be named Rama.', 'veda-app-ai-draft', true),
('ramayana-4-61-5', 'en', 'Rama, true in valour, will go to the forest with his brother Lakshmana, appointed to it by his father.', 'veda-app-ai-draft', true),
('ramayana-4-61-6', 'en', 'The rakshasa king Ravana, whom gods and asuras cannot kill, will carry off Rama''s wife from Janasthana.', 'veda-app-ai-draft', true),
('ramayana-4-61-7', 'en', 'Though tempted with pleasures and with all kinds of food, the noble, famous Maithili, sunk in grief, will not eat.', 'veda-app-ai-draft', true),
('ramayana-4-61-8', 'en', 'Knowing this, Indra will give Vaidehi the finest food, like nectar, hard to obtain even for the gods.', 'veda-app-ai-draft', true),
('ramayana-4-61-9', 'en', 'Receiving that food and knowing it is from Indra, Maithili will take out the first portion and offer it on the ground to Rama,', 'veda-app-ai-draft', true),
('ramayana-4-61-10', 'en', 'saying: Whether my husband the lord lives with Lakshmana, or both have gone to the world of the gods, this food is for them.', 'veda-app-ai-draft', true),
('ramayana-4-61-11', 'en', 'Monkeys, messengers of Rama, will come searching for her. You must tell them about Rama''s queen, bird.', 'veda-app-ai-draft', true),
('ramayana-4-61-12', 'en', 'You must not go anywhere at all. In this state where would you go? Wait for the right place and time, and you will get your wings back.', 'veda-app-ai-draft', true),
('ramayana-4-61-13', 'en', 'I could give you wings today, but by staying here you will do a deed for the good of the worlds.', 'veda-app-ai-draft', true),
('ramayana-4-61-14', 'en', 'You too must do this task for those two princes, for the brahmins, the gods, the sages and Indra.', 'veda-app-ai-draft', true),
('ramayana-4-61-15', 'en', 'I too wish to see the brothers Rama and Lakshmana, but I do not wish to hold on to life long. I will leave this body.', 'veda-app-ai-draft', true),
('ramayana-4-62-1', 'en', 'With these and many other words, that master of speech praised me, took his leave and went into his hermitage.', 'veda-app-ai-draft', true),
('ramayana-4-62-2', 'en', 'Crawling slowly out of the mountain cave, I climbed the Vindhya and have been waiting for you.', 'veda-app-ai-draft', true),
('ramayana-4-62-3', 'en', 'Today more than a hundred years have passed since then. Keeping the sage''s words in my heart, I wait for the place and time.', 'veda-app-ai-draft', true),
('ramayana-4-62-4', 'en', 'After Nishakara took his great departure to heaven, grief burned me, and I was beset by many doubts.', 'veda-app-ai-draft', true),
('ramayana-4-62-5', 'en', 'When the thought of death rose up, I turned it back with the sage''s words. The understanding he gave me to protect my life drives away my sorrow, as a bright flame drives away darkness.', 'veda-app-ai-draft', true),
('ramayana-4-62-6', 'en', 'Knowing the might of the wicked Ravana, I scolded my son: How did you not save Maithili?', 'veda-app-ai-draft', true),
('ramayana-4-62-7', 'en', 'Though he heard her cries and knew the two were parted from Sita, my son did nothing to please me out of my love for Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-4-62-8', 'en', 'As Sampati spoke this way with the monkeys, his wings sprang up then, before the eyes of the forest-dwellers.', 'veda-app-ai-draft', true),
('ramayana-4-62-9', 'en', 'Seeing his body with wings grown out, covered in reddish feathers, he felt boundless joy and said to the monkeys:', 'veda-app-ai-draft', true),
('ramayana-4-62-10', 'en', 'By the power of the great sage Nishakara of boundless spirit, my wings, burnt by the sun''s rays, have grown again.', 'veda-app-ai-draft', true),
('ramayana-4-62-11', 'en', 'The strength I had in my youth, that same strength and vigour I feel today.', 'veda-app-ai-draft', true),
('ramayana-4-62-12', 'en', 'Make every effort. You will find Sita. My getting back my wings is proof that you will succeed.', 'veda-app-ai-draft', true),
('ramayana-4-62-13', 'en', 'Saying this to all the monkeys, Sampati, best of birds, flew up from the mountain peak to test his flight.', 'veda-app-ai-draft', true),
('ramayana-4-62-14', 'en', 'Hearing his words, the tiger-like monkeys were overjoyed and eager to show their courage.', 'veda-app-ai-draft', true),
('ramayana-4-62-15', 'en', 'Then the leading monkeys, swift as the wind, their courage restored, set off towards the south, eager to search for Janaka''s daughter.', 'veda-app-ai-draft', true),
('ramayana-4-63-1', 'en', 'Told the way by the vulture king, the lion-brave monkeys leapt up, gathered joyfully and roared.', 'veda-app-ai-draft', true),
('ramayana-4-63-2', 'en', 'Hearing from Sampati where Ravana lived, the monkeys came gladly to the ocean, longing to see Sita.', 'veda-app-ai-draft', true),
('ramayana-4-63-3', 'en', 'Reaching that place, the fearsome monkeys saw the ocean, standing like a reflection of the whole vast world.', 'veda-app-ai-draft', true),
('ramayana-4-63-4', 'en', 'On the northern side of the southern ocean, the best of the monkeys made camp together.', 'veda-app-ai-draft', true),
('ramayana-4-63-5', 'en', 'It was crowded with huge, strange creatures playing in the water, with gaping mouths and enormous bodies, and churning with waves.', 'veda-app-ai-draft', true),
('ramayana-4-63-6', 'en', 'In one place it seemed asleep, in another at play, and elsewhere it was covered with masses of water like mountains.', 'veda-app-ai-draft', true),
('ramayana-4-63-7', 'en', 'It was thronged with asura lords living in the underworld. Seeing it, hair-raising, the great monkeys lost heart.', 'veda-app-ai-draft', true),
('ramayana-4-63-8', 'en', 'Seeing the ocean as hard to cross as the sky, all the monkeys suddenly despaired, saying: What can we do?', 'veda-app-ai-draft', true),
('ramayana-4-63-9', 'en', 'Seeing the army dejected at the sight of the ocean, the best of monkeys comforted the frightened monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-63-10', 'en', 'We must not give in to despair. Despair is the worst fault. Despair kills a person as an angry snake kills a child.', 'veda-app-ai-draft', true),
('ramayana-4-63-11', 'en', 'When the moment for courage comes, despair overpowers a person. One who loses his spirit to it never achieves his goal.', 'veda-app-ai-draft', true),
('ramayana-4-63-12', 'en', 'When that night had passed, Angada gathered with the monkeys and elders and took counsel again.', 'veda-app-ai-draft', true),
('ramayana-4-63-13', 'en', 'The monkey host around Angada shone like the army of the Maruts surrounding Indra.', 'veda-app-ai-draft', true),
('ramayana-4-63-14', 'en', 'Who else could hold that monkey army together, apart from Vali''s son and Hanuman?', 'veda-app-ai-draft', true),
('ramayana-4-63-15', 'en', 'Then glorious Angada, tamer of foes, respectfully addressed the monkey elders and the army with meaningful words.', 'veda-app-ai-draft', true),
('ramayana-4-63-16', 'en', 'Who, mighty one, will now leap across the ocean? Who will make Sugriva, tamer of foes, true to his promise?', 'veda-app-ai-draft', true),
('ramayana-4-63-17', 'en', 'Which hero will leap a hundred yojanas, monkeys? Who will free all these troop leaders from great fear?', 'veda-app-ai-draft', true),
('ramayana-4-63-18', 'en', 'By whose grace will we return from here successful and happy, and see our wives, sons and homes again?', 'veda-app-ai-draft', true),
('ramayana-4-63-19', 'en', 'By whose grace will we joyfully meet Rama, mighty Lakshmana and mighty Sugriva?', 'veda-app-ai-draft', true),
('ramayana-4-63-20', 'en', 'If any monkey among you can leap the ocean, let him quickly give us the sacred gift of freedom from fear.', 'veda-app-ai-draft', true),
('ramayana-4-63-21', 'en', 'Hearing Angada''s words, no one said anything. The whole monkey army there seemed frozen.', 'veda-app-ai-draft', true),
('ramayana-4-63-22', 'en', 'Again Angada, best of monkeys, said to them: You are all the best of the strong, firm in courage,', 'veda-app-ai-draft', true),
('ramayana-4-63-23', 'en', 'born in famous families and always honoured. None of you has ever been held back in moving anywhere.', 'veda-app-ai-draft', true),
('ramayana-4-63-24', 'en', 'Say, best of monkeys, how far each of you can go.', 'veda-app-ai-draft', true),
('ramayana-4-64-1', 'en', 'Hearing Angada, all the best monkeys spoke in turn of their own ability to leap.', 'veda-app-ai-draft', true),
('ramayana-4-64-2', 'en', 'Gaja, Gavaksha, Gavaya, Sharabha, Gandhamadana, Mainda, Dvivida, Sushena and Jambavan.', 'veda-app-ai-draft', true),
('ramayana-4-64-3', 'en', 'Gaja said: I can leap ten yojanas. Gavaksha said he would go twenty yojanas.', 'veda-app-ai-draft', true),
('ramayana-4-64-4', 'en', 'The monkey Gavaya said to the monkeys: I will go thirty yojanas.', 'veda-app-ai-draft', true),
('ramayana-4-64-5', 'en', 'The monkey Sharabha said to the monkeys: I will go forty yojanas, without doubt.', 'veda-app-ai-draft', true),
('ramayana-4-64-6', 'en', 'Mighty Gandhamadana said to the monkeys: I will certainly go fifty yojanas.', 'veda-app-ai-draft', true),
('ramayana-4-64-7', 'en', 'The monkey Mainda said to the monkeys: I can leap as far as sixty yojanas.', 'veda-app-ai-draft', true),
('ramayana-4-64-8', 'en', 'Then mighty Dvivida replied: I will go seventy yojanas, no doubt.', 'veda-app-ai-draft', true),
('ramayana-4-64-9', 'en', 'Sushena, best of monkeys, said to the others: I can leap eighty yojanas, bulls among monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-64-10', 'en', 'As they spoke, Jambavan, the eldest of them, respected them all and replied.', 'veda-app-ai-draft', true),
('ramayana-4-64-11', 'en', 'We too once had some power of movement, but now we have reached the far end of our age.', 'veda-app-ai-draft', true),
('ramayana-4-64-12', 'en', 'Yet this task cannot be neglected now, for the monkey king and Rama are set on it.', 'veda-app-ai-draft', true),
('ramayana-4-64-13', 'en', 'Hear what my range is now in these changed times: I will go ninety yojanas, without doubt.', 'veda-app-ai-draft', true),
('ramayana-4-64-14', 'en', 'Jambavan spoke again to all the best monkeys: My power of leaping was not always only this much.', 'veda-app-ai-draft', true),
('ramayana-4-64-15', 'en', 'Long ago, at a sacrifice, I and other mighty ones circled the eternal Vishnu as he took his three strides.', 'veda-app-ai-draft', true),
('ramayana-4-64-16', 'en', 'Now I am old and slow at leaping, but in my youth my strength was unmatched by others.', 'veda-app-ai-draft', true),
('ramayana-4-64-17', 'en', 'I reckon this is the extent of my power now, and with this alone the task will not succeed.', 'veda-app-ai-draft', true),
('ramayana-4-64-18', 'en', 'Then the wise Angada, respecting the great monkey Jambavan, gave a noble reply.', 'veda-app-ai-draft', true),
('ramayana-4-64-19', 'en', 'I will go this great hundred yojanas, but whether I have the strength to come back, I am not sure.', 'veda-app-ai-draft', true),
('ramayana-4-64-20', 'en', 'Jambavan, best of monkeys and skilled in speech, said to him: Your power to go is well known, best of monkeys and bears.', 'veda-app-ai-draft', true),
('ramayana-4-64-21', 'en', 'You could go and come back a hundred thousand yojanas if you wished, but that is not the right way.', 'veda-app-ai-draft', true),
('ramayana-4-64-22', 'en', 'A master who sends others is never himself sent, dear one. All of us here are yours to send, best of monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-64-23', 'en', 'You stand as our master and our mainstay. The master is the mainstay of an army; that is the rule, scorcher of foes.', 'veda-app-ai-draft', true),
('ramayana-4-64-24', 'en', 'So, dear one, you must always be protected like a mainstay. You are also the root of this task, tamer of foes.', 'veda-app-ai-draft', true),
('ramayana-4-64-25', 'en', 'The root of an undertaking must be guarded. That is the way of those who know how to act. Only when the root is there do flowers and fruit come.', 'veda-app-ai-draft', true),
('ramayana-4-64-26', 'en', 'So you, true in valour, rich in wisdom and courage, are the cause of achieving this task, scorcher of foes.', 'veda-app-ai-draft', true),
('ramayana-4-64-27', 'en', 'You are our master and our master''s son, best of monkeys. Relying on you, we are able to achieve our aim.', 'veda-app-ai-draft', true),
('ramayana-4-64-28', 'en', 'When the wise Jambavan had spoken, the great monkey Angada, son of Vali, replied.', 'veda-app-ai-draft', true),
('ramayana-4-64-29', 'en', 'If I do not go, and no other bull among monkeys does, then we must surely fast to death again.', 'veda-app-ai-draft', true),
('ramayana-4-64-30', 'en', 'For if we go back without carrying out the wise monkey king''s order, I see no way to save our lives there either.', 'veda-app-ai-draft', true),
('ramayana-4-64-31', 'en', 'The monkey king is lord over both great favour and great anger. If we go back having failed his order, we will be destroyed.', 'veda-app-ai-draft', true),
('ramayana-4-64-32', 'en', 'So you, who see the matter clearly, should think how this task will not fail.', 'veda-app-ai-draft', true),
('ramayana-4-64-33', 'en', 'Answered this way by Angada, the heroic Jambavan, bull among monkeys, replied to him.', 'veda-app-ai-draft', true),
('ramayana-4-64-34', 'en', 'Hero, nothing of this task of yours will fall short. I will now urge on the one who will accomplish it.', 'veda-app-ai-draft', true),
('ramayana-4-64-35', 'en', 'Then that hero among monkeys urged on the hero among monkeys, Hanuman, the best of leapers, who sat calmly apart.', 'veda-app-ai-draft', true),
('ramayana-4-65-1', 'en', 'Looking at the despondent monkey army, many hundreds of thousands strong, Jambavan said to Hanuman:', 'veda-app-ai-draft', true),
('ramayana-4-65-2', 'en', 'Hero of the monkey world, best of those who know every science, why do you sit silent and apart, Hanuman, and say nothing?', 'veda-app-ai-draft', true),
('ramayana-4-65-3', 'en', 'Hanuman, you are equal to Sugriva, king of the monkeys, and even to Rama and Lakshmana in energy and strength.', 'veda-app-ai-draft', true),
('ramayana-4-65-4', 'en', 'You are famous like mighty Garuda, son of Vinata and Arishtanemi''s line, the greatest of all birds.', 'veda-app-ai-draft', true),
('ramayana-4-65-5', 'en', 'Many times I have seen that mighty, swift and famous bird lift serpents out of the ocean.', 'veda-app-ai-draft', true),
('ramayana-4-65-6', 'en', 'The strength in his wings is the strength in your arms. Your courage and speed are no less than his.', 'veda-app-ai-draft', true),
('ramayana-4-65-7', 'en', 'Strength, intelligence, energy and spirit, best of monkeys, are yours beyond all beings. Why do you not know yourself?', 'veda-app-ai-draft', true),
('ramayana-4-65-8', 'en', 'Punjikasthala, a famous and foremost apsaras, became known as Anjana, the wife of the monkey Kesari.', 'veda-app-ai-draft', true),
('ramayana-4-65-9', 'en', 'Through a curse she was born a monkey who could take any form, the daughter of the great monkey lord Kunjara.', 'veda-app-ai-draft', true),
('ramayana-4-65-10', 'en', 'Once, beautiful in every limb and able to change form, she took a human shape in the bloom of youth.', 'veda-app-ai-draft', true),
('ramayana-4-65-11', 'en', 'She walked on a mountain top dark as a rain cloud, wearing bright garlands and ornaments and costly linen.', 'veda-app-ai-draft', true),
('ramayana-4-65-12', 'en', 'As the wide-eyed lady stood on the mountain top, the Wind gently lifted her lovely yellow garment with its red border.', 'veda-app-ai-draft', true),
('ramayana-4-65-13', 'en', 'Then he saw her graceful form and her lovely face.', 'veda-app-ai-draft', true),
('ramayana-4-65-14', 'en', 'Seeing that famous lady, slender and beautiful in every way, the Wind was overcome with love.', 'veda-app-ai-draft', true),
('ramayana-4-65-15', 'en', 'The Wind, his whole being filled with love, embraced the blameless lady with his strong arms.', 'veda-app-ai-draft', true),
('ramayana-4-65-16', 'en', 'Alarmed, the virtuous lady said: Who wants to break my vow of faithfulness to one husband?', 'veda-app-ai-draft', true),
('ramayana-4-65-17', 'en', 'Hearing Anjana''s words, the Wind replied: I do not harm you, lovely one. Do not be afraid, blessed lady.', 'veda-app-ai-draft', true),
('ramayana-4-65-18', 'en', 'Since I have embraced you only with my mind, famous lady, you will have a son who is mighty and wise.', 'veda-app-ai-draft', true),
('ramayana-4-65-19', 'en', 'As a child in the great forest, seeing the sun rising and thinking it a fruit, you leapt up to the sky to grab it.', 'veda-app-ai-draft', true),
('ramayana-4-65-20', 'en', 'Having gone three hundred yojanas, great monkey, you were scorched by its heat, yet you did not lose heart.', 'veda-app-ai-draft', true),
('ramayana-4-65-21', 'en', 'As you sped through the sky, great monkey, wise Indra, filled with anger, hurled his thunderbolt at you.', 'veda-app-ai-draft', true),
('ramayana-4-65-22', 'en', 'Then, on a mountain peak, your left jaw was broken, and that is why you are called Hanuman.', 'veda-app-ai-draft', true),
('ramayana-4-65-23', 'en', 'Seeing you struck down, the Wind himself, bearer of fragrance, grew furious and stopped blowing in the three worlds.', 'veda-app-ai-draft', true),
('ramayana-4-65-24', 'en', 'When the three worlds were in turmoil, all the alarmed gods, lords of the worlds, tried to calm the angry Wind.', 'veda-app-ai-draft', true),
('ramayana-4-65-25', 'en', 'When the Wind was calmed, Brahma gave you a boon, dear one: that no weapon could kill you in battle, you of true valour.', 'veda-app-ai-draft', true),
('ramayana-4-65-26', 'en', 'And seeing you unhurt by the thunderbolt''s blow, the thousand-eyed Indra, pleased, gave you an excellent boon:', 'veda-app-ai-draft', true),
('ramayana-4-65-27', 'en', 'that you would die only when you chose, lord. So you are the son of Kesari by his wife, of terrible valour,', 'veda-app-ai-draft', true),
('ramayana-4-65-28', 'en', 'and the true son of the Wind, equal to him in energy. You are the Wind''s son, dear child, and equal to him in leaping too.', 'veda-app-ai-draft', true),
('ramayana-4-65-29', 'en', 'Today we are as good as dead. Now among us you are skilled and brave, like a second king of birds.', 'veda-app-ai-draft', true),
('ramayana-4-65-30', 'en', 'When Vishnu took his three strides, dear one, I went around the earth with its mountains and forests twenty-one times, keeping it to my right.', 'veda-app-ai-draft', true),
('ramayana-4-65-31', 'en', 'Then, at the gods'' command, we gathered the herbs from which the nectar was made. Our strength was great then.', 'veda-app-ai-draft', true),
('ramayana-4-65-32', 'en', 'Now I am old and my strength has faded. At this time you have every quality.', 'veda-app-ai-draft', true),
('ramayana-4-65-33', 'en', 'So rise up in your power, for you are the best of leapers. The whole monkey army wants to see your strength.', 'veda-app-ai-draft', true),
('ramayana-4-65-34', 'en', 'Rise, tiger among monkeys, and leap across the great ocean. Your speed, Hanuman, surpasses that of all beings.', 'veda-app-ai-draft', true),
('ramayana-4-65-35', 'en', 'All the monkeys are downcast. Why do you hold back, Hanuman? Stride out with great speed, as Vishnu took his three strides.', 'veda-app-ai-draft', true),
('ramayana-4-65-36', 'en', 'Urged on by Jambavan, the monkey son of the Wind, confident of his speed, delighted the army of heroic monkeys and took on a huge form.', 'veda-app-ai-draft', true),
('ramayana-4-66-1', 'en', 'Praised by all, mighty Hanuman grew in size. Swinging his tail in joy, he felt his full strength.', 'veda-app-ai-draft', true),
('ramayana-4-66-2', 'en', 'As all the leading monkeys praised him and he filled with energy, his form became unsurpassed.', 'veda-app-ai-draft', true),
('ramayana-4-66-3', 'en', 'As a lion stretches when grown in a mountain cave, so the true son of the Wind now stretched himself.', 'veda-app-ai-draft', true),
('ramayana-4-66-4', 'en', 'The face of the wise one as he stretched shone like a glowing pan, like a smokeless fire.', 'veda-app-ai-draft', true),
('ramayana-4-66-5', 'en', 'Rising from among the monkeys, his hair bristling with joy, Hanuman saluted the elder monkeys and said:', 'veda-app-ai-draft', true),
('ramayana-4-66-6', 'en', 'The Wind, friend of fire, breaks mountain peaks. Mighty and immeasurable, he moves through the sky.', 'veda-app-ai-draft', true),
('ramayana-4-66-7', 'en', 'I am the true son of that swift-moving, great-souled Wind. No one equals me in leaping.', 'veda-app-ai-draft', true),
('ramayana-4-66-8', 'en', 'I could circle Mount Meru, which seems to scrape the vast sky, a thousand times without stopping.', 'veda-app-ai-draft', true),
('ramayana-4-66-9', 'en', 'With the sea driven by the force of my arms, I could flood the world with its mountains, rivers and lakes.', 'veda-app-ai-draft', true),
('ramayana-4-66-10', 'en', 'With the force of my thighs and legs, the ocean, home of Varuna, will rise up with its great sea creatures stunned.', 'veda-app-ai-draft', true),
('ramayana-4-66-11', 'en', 'I can circle a thousand times Garuda, eater of serpents, served by birds, as he flies through the sky.', 'veda-app-ai-draft', true),
('ramayana-4-66-12', 'en', 'I can reach the blazing, ray-wreathed sun as it sets out from the eastern mountain, before it sets.', 'veda-app-ai-draft', true),
('ramayana-4-66-13', 'en', 'And then I can come back without touching the ground, bulls among monkeys, with great and fearsome speed.', 'veda-app-ai-draft', true),
('ramayana-4-66-14', 'en', 'I can pass all who travel the sky. I will stir up the ocean and split the earth.', 'veda-app-ai-draft', true),
('ramayana-4-66-15', 'en', 'As I leap, monkeys, I will shake the mountains, and with the force of my thighs I will sweep across the great ocean.', 'veda-app-ai-draft', true),
('ramayana-4-66-16', 'en', 'Today the flowers of creepers, shrubs and trees will follow me as I leap through the sky. My path will be like the path of the star Svati in the sky.', 'veda-app-ai-draft', true),
('ramayana-4-66-17', 'en', 'All beings, monkeys, will see me travelling through the fearsome sky, rising up and coming down.', 'veda-app-ai-draft', true),
('ramayana-4-66-18', 'en', 'You will see me like great Meru, monkeys, covering the heavens as I go, as if swallowing the sky.', 'veda-app-ai-draft', true),
('ramayana-4-66-19', 'en', 'I will scatter the clouds, shake the mountains and stir the ocean as I leap, fully focused.', 'veda-app-ai-draft', true),
('ramayana-4-66-20', 'en', 'Only Garuda or the Wind have strength like mine. Apart from the king of eagles and the mighty Wind, I see no being that could follow my leap.', 'veda-app-ai-draft', true),
('ramayana-4-66-21', 'en', 'In the blink of an eye I will suddenly fly through the unsupported sky, like lightning rising from a cloud.', 'veda-app-ai-draft', true),
('ramayana-4-66-22', 'en', 'As I leap the ocean, my form will be like Vishnu''s when he took his three strides.', 'veda-app-ai-draft', true),
('ramayana-4-66-23', 'en', 'I see it with my understanding, and my mind and actions agree: I will see Vaidehi. Rejoice, monkeys.', 'veda-app-ai-draft', true),
('ramayana-4-66-24', 'en', 'Equal to the Wind in force and to Garuda in speed, I believe I could go ten thousand yojanas.', 'veda-app-ai-draft', true),
('ramayana-4-66-25', 'en', 'I could snatch the nectar by force from the hand of thunderbolt-wielding Indra or of self-born Brahma and bring it here, or lift up Lanka itself and carry it off. That is my belief.', 'veda-app-ai-draft', true),
('ramayana-4-66-26', 'en', 'As the best of monkeys, of boundless energy, roared like this, Jambavan, best of monkeys, overjoyed, said to him:', 'veda-app-ai-draft', true),
('ramayana-4-66-27', 'en', 'Hero, son of Kesari, swift son of the Wind, you have wiped away the great grief of your kinsmen, dear one.', 'veda-app-ai-draft', true),
('ramayana-4-66-28', 'en', 'The leading monkeys gathered here wish you well. Together they will perform blessings for the success of your task.', 'veda-app-ai-draft', true),
('ramayana-4-66-29', 'en', 'By the grace of the sages, the counsel of the monkey elders and the grace of your teachers, leap across the great ocean.', 'veda-app-ai-draft', true),
('ramayana-4-66-30', 'en', 'We will stand on one foot until you return. The lives of all the forest-dwellers depend on you.', 'veda-app-ai-draft', true),
('ramayana-4-66-31', 'en', 'Then the tiger among monkeys said to the forest-dwellers: This ground will not bear the force of my leap.', 'veda-app-ai-draft', true),
('ramayana-4-66-32', 'en', 'These peaks of Mount Mahendra, crowded with rocks, are firm and great.', 'veda-app-ai-draft', true),
('ramayana-4-66-33', 'en', 'These will bear the pressure of my feet, best of flyers, as I leap a hundred yojanas from here.', 'veda-app-ai-draft', true),
('ramayana-4-66-34', 'en', 'Then the monkey son of the Wind, like the Wind himself, crusher of foes, climbed Mahendra, best of mountains.', 'veda-app-ai-draft', true),
('ramayana-4-66-35', 'en', 'It was covered with many kinds of trees, its lawns grazed by deer, thick with flowering creepers, its trees always in flower and fruit,', 'veda-app-ai-draft', true),
('ramayana-4-66-36', 'en', 'roamed by lions and tigers, frequented by rutting elephants, loud with flocks of excited birds, and full of gushing water.', 'veda-app-ai-draft', true),
('ramayana-4-66-37', 'en', 'The mighty best of monkeys, as powerful as great Indra, moved about on Mahendra with its great lofty peaks.', 'veda-app-ai-draft', true),
('ramayana-4-66-38', 'en', 'Pressed by his feet, the great mountain roared like a huge rutting elephant struck by a lion.', 'veda-app-ai-draft', true),
('ramayana-4-66-39', 'en', 'Its rocks scattered, it released gushes of water. Its deer and elephants were terrified and its great trees shook.', 'veda-app-ai-draft', true),
('ramayana-4-66-40', 'en', 'Gandharva couples, lost in drinking, and birds and vidyadharas flew up from it.', 'veda-app-ai-draft', true),
('ramayana-4-66-41', 'en', 'Its great slopes abandoned, its great serpents hiding, its peaks and rocks breaking off, the great mountain was in turmoil.', 'veda-app-ai-draft', true),
('ramayana-4-66-42', 'en', 'With serpents half emerged and hissing, the mountain looked as if it were hung with banners.', 'veda-app-ai-draft', true),
('ramayana-4-66-43', 'en', 'Abandoned by sages shaken with fear, the mountain seemed like a traveller left behind by his caravan in a great wilderness.', 'veda-app-ai-draft', true),
('ramayana-4-66-44', 'en', 'That swift, mighty hero among monkeys, slayer of enemy heroes, his mind gathered for the leap, fixed his thoughts and, high-minded, went to Lanka in his mind.', 'veda-app-ai-draft', true);
