from (values
('ramayana-5-1-1', 1, 'Sundara Kanda, Sarga 1, Verse 1', 'ततो रावणनीतायाः सीतायाः शत्रुकर्शनः।
इयेष पदमन्वेष्टुं चारणाचरिते पथि॥', 'tato rāvaṇanītāyāḥ sītāyāḥ śatrukarśanaḥ
iyeṣa padam anveṣṭuṃ cāraṇācarite pathi', null, 5001001),
('ramayana-5-1-2', 2, 'Sundara Kanda, Sarga 1, Verse 2', 'अथ वैदूर्यवर्णेषु शाद्वलेषु महाबलः।
धीरः सलिलकल्पेषु विचचार यथासुखम्॥', 'atha vaidūryavarṇeṣu śādvaleṣu mahābalaḥ
dhīraḥ salilakalpeṣu vicacāra yathāsukham', null, 5001002),
('ramayana-5-1-3', 3, 'Sundara Kanda, Sarga 1, Verse 3', 'द्विजान्वित्रासयन्धीमानुरसा पादपान्हरन्।
मृगांश्च सुबहून्निघ्नन्प्रवृद्ध इव केसरी॥', 'dvijān vitrāsayan dhīmān urasā pādapān haran
mṛgāṃś ca subahūn nighnan pravṛddha iva kesarī', null, 5001003),
('ramayana-5-1-4', 4, 'Sundara Kanda, Sarga 1, Verse 4', 'नीललोहितमाञ्जिष्ठपद्मवर्णैः सितासितैः।
स्वभावविहितैश्चित्रैर्धातुभिः समलंकृतम्॥', 'nīlalohitamāñjiṣṭhapadmavarṇaiḥ sitāsitaiḥ
svabhāvavihitaiś citrair dhātubhiḥ samalaṃkṛtam', null, 5001004),
('ramayana-5-1-5', 5, 'Sundara Kanda, Sarga 1, Verse 5', 'कामरूपिभिराविष्टमभीक्ष्णं सपरिच्छदैः।
यक्षकिंनरगन्धर्वैर्देवकल्पैश्च पन्नगैः॥', 'kāmarūpibhir āviṣṭam abhīkṣṇaṃ saparicchadaiḥ
yakṣakiṃnaragandharvair devakalpaiś ca pannagaiḥ', null, 5001005),
('ramayana-5-1-6', 6, 'Sundara Kanda, Sarga 1, Verse 6', 'स तस्य गिरिवर्यस्य तले नागवरायुते।
तिष्ठन्कपिवरस्तत्र ह्रदे नाग इवाबभौ॥', 'sa tasya girivaryasya tale nāgavarāyute
tiṣṭhan kapivaras tatra hrade nāga ivābabhau', null, 5001006),
('ramayana-5-1-7', 7, 'Sundara Kanda, Sarga 1, Verse 7', 'स सूर्याय महेन्द्राय पवनाय स्वयम्भुवे।
भूतेभ्यश्चाञ्जलिं कृत्वा चकार गमने मतिम्॥', 'sa sūryāya mahendrāya pavanāya svayambhuve
bhūtebhyaś cāñjaliṃ kṛtvā cakāra gamane matim', null, 5001007),
('ramayana-5-1-8', 8, 'Sundara Kanda, Sarga 1, Verse 8', 'अञ्जलिं प्राङ्मुखः कुर्वन्पवनायात्मयोनये।
ततो हि ववृधे गन्तुं दक्षिणो दक्षिणां दिशम्॥', 'añjaliṃ prāṅmukhaḥ kurvan pavanāyātmayonaye
tato hi vavṛdhe gantuṃ dakṣiṇo dakṣiṇāṃ diśam', null, 5001008),
('ramayana-5-1-9', 9, 'Sundara Kanda, Sarga 1, Verse 9', 'प्लवंगप्रवरैर्दृष्टः प्लवने कृतनिश्चयः।
ववृधे रामवृद्ध्यर्थं समुद्र इव पर्वसु॥', 'plavaṃgapravarair dṛṣṭaḥ plavane kṛtaniścayaḥ
vavṛdhe rāmavṛddhyarthaṃ samudra iva parvasu', null, 5001009),
('ramayana-5-1-10', 10, 'Sundara Kanda, Sarga 1, Verse 10', 'निष्प्रमाण शरीरः संल्लिलङ्घयिषुरर्णवम्।
बाहुभ्यां पीडयामास चरणाभ्यां च पर्वतम्॥', 'niṣpramāṇa śarīraḥ saṃl lilaṅghayiṣur arṇavam
bāhubhyāṃ pīḍayām āsa caraṇābhyāṃ ca parvatam', null, 5001010),
('ramayana-5-1-11', 11, 'Sundara Kanda, Sarga 1, Verse 11', 'स चचालाचलाश्चारु मुहूर्तं कपिपीडितः।
तरूणां पुष्पिताग्राणां सर्वं पुष्पमशातयत्॥', 'sa cacālācalāś cāru muhūrtaṃ kapipīḍitaḥ
tarūṇāṃ puṣpitāgrāṇāṃ sarvaṃ puṣpam aśātayat', null, 5001011),
('ramayana-5-1-12', 12, 'Sundara Kanda, Sarga 1, Verse 12', 'तेन पादपमुक्तेन पुष्पौघेण सुगन्धिना।
सर्वतः संवृतः शैलो बभौ पुष्पमयो यथा॥', 'tena pādapamuktena puṣpaugheṇa sugandhinā
sarvataḥ saṃvṛtaḥ śailo babhau puṣpamayo yathā', null, 5001012),
('ramayana-5-1-13', 13, 'Sundara Kanda, Sarga 1, Verse 13', 'तेन चोत्तमवीर्येण पीड्यमानः स पर्वतः।
सलिलं संप्रसुस्राव मदं मत्त इव द्विपः॥', 'tena cottamavīryeṇa pīḍyamānaḥ sa parvataḥ
salilaṃ saṃprasusrāva madaṃ matta iva dvipaḥ', null, 5001013),
('ramayana-5-1-14', 14, 'Sundara Kanda, Sarga 1, Verse 14', 'पीड्यमानस्तु बलिना महेन्द्रस्तेन पर्वतः।
रीतिर्निर्वर्तयामास काञ्चनाञ्जनराजतीः।
मुमोच च शिलाः शैलो विशालाः समनःशिलाः॥', 'pīḍyamānas tu balinā mahendras tena parvataḥ
rītir nirvartayām āsa kāñcanāñjanarājatīḥ
mumoca ca śilāḥ śailo viśālāḥ samanaḥśilāḥ', null, 5001014),
('ramayana-5-1-15', 15, 'Sundara Kanda, Sarga 1, Verse 15', 'गिरिणा पीड्यमानेन पीड्यमानानि सर्वशः।
गुहाविष्टानि भूतानि विनेदुर्विकृतैः स्वरैः॥', 'giriṇā pīḍyamānena pīḍyamānāni sarvaśaḥ
guhāviṣṭāni bhūtāni vinedur vikṛtaiḥ svaraiḥ', null, 5001015),
('ramayana-5-1-16', 16, 'Sundara Kanda, Sarga 1, Verse 16', 'स महासत्त्वसंनादः शैलपीडानिमित्तजः।
पृथिवीं पूरयामास दिशश्चोपवनानि च॥', 'sa mahāsattvasaṃnādaḥ śailapīḍānimittajaḥ
pṛthivīṃ pūrayām āsa diśaś copavanāni ca', null, 5001016),
('ramayana-5-1-17', 17, 'Sundara Kanda, Sarga 1, Verse 17', 'शिरोभिः पृथुभिः सर्पा व्यक्तस्वस्तिकलक्षणैः।
वमन्तः पावकं घोरं ददंशुर्दशनैः शिलाः॥', 'śirobhiḥ pṛthubhiḥ sarpā vyaktasvastikalakṣaṇaiḥ
vamantaḥ pāvakaṃ ghoraṃ dadaṃśur daśanaiḥ śilāḥ', null, 5001017),
('ramayana-5-1-18', 18, 'Sundara Kanda, Sarga 1, Verse 18', 'तास्तदा सविषैर्दष्टाः कुपितैस्तैर्महाशिलाः।
जज्वलुः पावकोद्दीप्ता विभिदुश्च सहस्रधा॥', 'tās tadā saviṣair daṣṭāḥ kupitais tair mahāśilāḥ
jajvaluḥ pāvakoddīptā vibhiduś ca sahasradhā', null, 5001018),
('ramayana-5-1-19', 19, 'Sundara Kanda, Sarga 1, Verse 19', 'यानि चौषधजालानि तस्मिञ्जातानि पर्वते।
विषघ्नान्यपि नागानां न शेकुः शमितुं विषम्॥', 'yāni cauṣadhajālāni tasmiñ jātāni parvate
viṣaghnāny api nāgānāṃ na śekuḥ śamituṃ viṣam', null, 5001019),
('ramayana-5-1-20', 20, 'Sundara Kanda, Sarga 1, Verse 20', 'भिद्यतेऽयं गिरिर्भूतैरिति मत्वा तपस्विनः।
त्रस्ता विद्याधरास्तस्मादुत्पेतुः स्त्रीगणैः सह॥', 'bhidyate ''yaṃ girir bhūtair iti matvā tapasvinaḥ
trastā vidyādharās tasmād utpetuḥ strīgaṇaiḥ saha', null, 5001020),
('ramayana-5-1-21', 21, 'Sundara Kanda, Sarga 1, Verse 21', 'पानभूमिगतं हित्वा हैममासनभाजनम्।
पात्राणि च महार्हाणि करकांश्च हिरण्मयान्॥', 'pānabhūmigataṃ hitvā haimam āsanabhājanam
pātrāṇi ca mahārhāṇi karakāṃś ca hiraṇmayān', null, 5001021),
('ramayana-5-1-22', 22, 'Sundara Kanda, Sarga 1, Verse 22', 'लेह्यानुच्चावचान्भक्ष्यान्मांसानि विविधानि च।
आर्षभाणि च चर्माणि खड्गांश्च कनकत्सरून्॥', 'lehyān uccāvacān bhakṣyān māṃsāni vividhāni ca
ārṣabhāṇi ca carmāṇi khaḍgāṃś ca kanakatsarūn', null, 5001022),
('ramayana-5-1-23', 23, 'Sundara Kanda, Sarga 1, Verse 23', 'कृतकण्ठगुणाः क्षीबा रक्तमाल्यानुलेपनाः।
रक्ताक्षाः पुष्कराक्षाश्च गगनं प्रतिपेदिरे॥', 'kṛtakaṇṭhaguṇāḥ kṣībā raktamālyānulepanāḥ
raktākṣāḥ puṣkarākṣāś ca gaganaṃ pratipedire', null, 5001023),
('ramayana-5-1-24', 24, 'Sundara Kanda, Sarga 1, Verse 24', 'हारनूपुरकेयूर पारिहार्य धराः स्त्रियः।
विस्मिताः सस्मितास्तस्थुराकाशे रमणैः सह॥', 'hāranūpurakeyūra pārihārya dharāḥ striyaḥ
vismitāḥ sasmitās tasthur ākāśe ramaṇaiḥ saha', null, 5001024),
('ramayana-5-1-25', 25, 'Sundara Kanda, Sarga 1, Verse 25', 'दर्शयन्तो महाविद्यां विद्याधरमहर्षयः।
सहितास्तस्थुराकाशे वीक्षां चक्रुश्च पर्वतम्॥', 'darśayanto mahāvidyāṃ vidyādharamaharṣayaḥ
sahitās tasthur ākāśe vīkṣāṃ cakruś ca parvatam', null, 5001025),
('ramayana-5-1-26', 26, 'Sundara Kanda, Sarga 1, Verse 26', 'शुश्रुवुश्च तदा शब्दमृषीणां भावितात्मनाम्।
चारणानां च सिद्धानां स्थितानां विमलेऽम्बरे॥', 'śuśruvuś ca tadā śabdam ṛṣīṇāṃ bhāvitātmanām
cāraṇānāṃ ca siddhānāṃ sthitānāṃ vimale ''mbare', null, 5001026),
('ramayana-5-1-27', 27, 'Sundara Kanda, Sarga 1, Verse 27', 'एष पर्वतसंकाशो हनूमान्मारुतात्मजः।
तितीर्षति महावेगं समुद्रं मकरालयम्॥', 'eṣa parvatasaṃkāśo hanūmān mārutātmajaḥ
titīrṣati mahāvegaṃ samudraṃ makarālayam', null, 5001027),
('ramayana-5-1-28', 28, 'Sundara Kanda, Sarga 1, Verse 28', 'रामार्थं वानरार्थं च चिकीर्षन्कर्म दुष्करम्।
समुद्रस्य परं पारं दुष्प्रापं प्राप्तुमिच्छति॥', 'rāmārthaṃ vānarārthaṃ ca cikīrṣan karma duṣkaram
samudrasya paraṃ pāraṃ duṣprāpaṃ prāptum icchati', null, 5001028),
('ramayana-5-1-29', 29, 'Sundara Kanda, Sarga 1, Verse 29', 'दुधुवे च स रोमाणि चकम्पे चाचलोपमः।
ननाद च महानादं सुमहानिव तोयदः॥', 'dudhuve ca sa romāṇi cakampe cācalopamaḥ
nanāda ca mahānādaṃ sumahān iva toyadaḥ', null, 5001029),
('ramayana-5-1-30', 30, 'Sundara Kanda, Sarga 1, Verse 30', 'आनुपूर्व्याच्च वृत्तं च लाङ्गूलं रोमभिश्चितम्।
उत्पतिष्यन्विचिक्षेप पक्षिराज इवोरगम्॥', 'ānupūrvyāc ca vṛttaṃ ca lāṅgūlaṃ romabhiś citam
utpatiṣyan vicikṣepa pakṣirāja ivoragam', null, 5001030),
('ramayana-5-1-31', 31, 'Sundara Kanda, Sarga 1, Verse 31', 'तस्य लाङ्गूलमाविद्धमतिवेगस्य पृष्ठतः।
ददृशे गरुडेनेव ह्रियमाणो महोरगः॥', 'tasya lāṅgūlam āviddham ativegasya pṛṣṭhataḥ
dadṛśe garuḍeneva hriyamāṇo mahoragaḥ', null, 5001031),
('ramayana-5-1-32', 32, 'Sundara Kanda, Sarga 1, Verse 32', 'बाहू संस्तम्भयामास महापरिघसंनिभौ।
ससाद च कपिः कट्यां चरणौ संचुकोप च॥', 'bāhū saṃstambhayām āsa mahāparighasaṃnibhau
sasāda ca kapiḥ kaṭyāṃ caraṇau saṃcukopa ca', null, 5001032),
('ramayana-5-1-33', 33, 'Sundara Kanda, Sarga 1, Verse 33', 'संहृत्य च भुजौ श्रीमांस्तथैव च शिरोधराम्।
तेजः सत्त्वं तथा वीर्यमाविवेश स वीर्यवान्॥', 'saṃhṛtya ca bhujau śrīmāṃs tathaiva ca śirodharām
tejaḥ sattvaṃ tathā vīryam āviveśa sa vīryavān', null, 5001033),
('ramayana-5-1-34', 34, 'Sundara Kanda, Sarga 1, Verse 34', 'मार्गमालोकयन्दूरादूर्ध्वप्रणिहितेक्षणः।
रुरोध हृदये प्राणानाकाशमवलोकयन्॥', 'mārgam ālokayan dūrād ūrdhvapraṇihitekṣaṇaḥ
rurodha hṛdaye prāṇān ākāśam avalokayan', null, 5001034),
('ramayana-5-1-35', 35, 'Sundara Kanda, Sarga 1, Verse 35', 'पद्भ्यां दृढमवस्थानं कृत्वा स कपिकुञ्जरः।
निकुञ्च्य कर्णौ हनुमानुत्पतिष्यन्महाबलः।
वानरान्वानरश्रेष्ठ इदं वचनमब्रवीत्॥', 'padbhyāṃ dṛḍham avasthānaṃ kṛtvā sa kapikuñjaraḥ
nikuñcya karṇau hanumān utpatiṣyan mahābalaḥ
vānarān vānaraśreṣṭha idaṃ vacanam abravīt', null, 5001035),
('ramayana-5-1-36', 36, 'Sundara Kanda, Sarga 1, Verse 36', 'यथा राघवनिर्मुक्तः शरः श्वसनविक्रमः।
गच्छेत्तद्वद्गमिष्यामि लङ्कां रावणपालिताम्॥', 'yathā rāghavanirmuktaḥ śaraḥ śvasanavikramaḥ
gacchet tadvad gamiṣyāmi laṅkāṃ rāvaṇapālitām', null, 5001036),
('ramayana-5-1-37', 37, 'Sundara Kanda, Sarga 1, Verse 37', 'न हि द्रक्ष्यामि यदि तां लङ्कायां जनकात्मजाम्।
अनेनैव हि वेगेन गमिष्यामि सुरालयम्॥', 'na hi drakṣyāmi yadi tāṃ laṅkāyāṃ janakātmajām
anenaiva hi vegena gamiṣyāmi surālayam', null, 5001037),
('ramayana-5-1-38', 38, 'Sundara Kanda, Sarga 1, Verse 38', 'यदि वा त्रिदिवे सीतां न द्रक्ष्यामि कृतश्रमः।
बद्ध्वा राक्षसराजानमानयिष्यामि रावणम्॥', 'yadi vā tridive sītāṃ na drakṣyāmi kṛtaśramaḥ
baddhvā rākṣasarājānam ānayiṣyāmi rāvaṇam', null, 5001038),
('ramayana-5-1-39', 39, 'Sundara Kanda, Sarga 1, Verse 39', 'सर्वथा कृतकार्योऽहमेष्यामि सह सीतया।
आनयिष्यामि वा लङ्कां समुत्पाट्य सरावणाम्॥', 'sarvathā kṛtakāryo ''ham eṣyāmi saha sītayā
ānayiṣyāmi vā laṅkāṃ samutpāṭya sarāvaṇām', null, 5001039),
('ramayana-5-1-40', 40, 'Sundara Kanda, Sarga 1, Verse 40', 'एवमुक्त्वा तु हनुमान्वानरान्वानरोत्तमः।
उत्पपाताथ वेगेन वेगवानविचारयन्॥', 'evam uktvā tu hanumān vānarān vānarottamaḥ
utpapātātha vegena vegavān avicārayan', null, 5001040),
('ramayana-5-1-41', 41, 'Sundara Kanda, Sarga 1, Verse 41', 'समुत्पतति तस्मिंस्तु वेगात्ते नगरोहिणः।
संहृत्य विटपान्सर्वान्समुत्पेतुः समन्ततः॥', 'samutpatati tasmiṃs tu vegāt te nagarohiṇaḥ
saṃhṛtya viṭapān sarvān samutpetuḥ samantataḥ', null, 5001041),
('ramayana-5-1-42', 42, 'Sundara Kanda, Sarga 1, Verse 42', 'स मत्तकोयष्टिभकान्पादपान्पुष्पशालिनः।
उद्वहन्नूरुवेगेन जगाम विमलेऽम्बरे॥', 'sa mattakoyaṣṭibhakān pādapān puṣpaśālinaḥ
udvahann ūruvegena jagāma vimale ''mbare', null, 5001042),
('ramayana-5-1-43', 43, 'Sundara Kanda, Sarga 1, Verse 43', 'ऊरुवेगोद्धता वृक्षा मुहूर्तं कपिमन्वयुः।
प्रस्थितं दीर्घमध्वानं स्वबन्धुमिव बान्धवाः॥', 'ūruvegoddhatā vṛkṣā muhūrtaṃ kapim anvayuḥ
prasthitaṃ dīrgham adhvānaṃ svabandhum iva bāndhavāḥ', null, 5001043),
('ramayana-5-1-44', 44, 'Sundara Kanda, Sarga 1, Verse 44', 'तमूरुवेगोन्मथिताः सालाश्चान्ये नगोत्तमाः।
अनुजग्मुर्हनूमन्तं सैन्या इव महीपतिम्॥', 'tam ūruvegonmathitāḥ sālāś cānye nagottamāḥ
anujagmur hanūmantaṃ sainyā iva mahīpatim', null, 5001044),
('ramayana-5-1-45', 45, 'Sundara Kanda, Sarga 1, Verse 45', 'सुपुष्पिताग्रैर्बहुभिः पादपैरन्वितः कपिः।
हनुमान्पर्वताकारो बभूवाद्भुतदर्शनः॥', 'supuṣpitāgrair bahubhiḥ pādapair anvitaḥ kapiḥ
hanumān parvatākāro babhūvādbhutadarśanaḥ', null, 5001045),
('ramayana-5-1-46', 46, 'Sundara Kanda, Sarga 1, Verse 46', 'सारवन्तोऽथ ये वृक्षा न्यमज्जंल्लवणाम्भसि।
भयादिव महेन्द्रस्य पर्वता वरुणालये॥', 'sāravanto ''tha ye vṛkṣā nyamajjaṃl lavaṇāmbhasi
bhayād iva mahendrasya parvatā varuṇālaye', null, 5001046),
('ramayana-5-1-47', 47, 'Sundara Kanda, Sarga 1, Verse 47', 'स नानाकुसुमैः कीर्णः कपिः साङ्कुरकोरकैः।
शुशुभे मेघसंकाशः खद्योतैरिव पर्वतः॥', 'sa nānākusumaiḥ kīrṇaḥ kapiḥ sāṅkurakorakaiḥ
śuśubhe meghasaṃkāśaḥ khadyotair iva parvataḥ', null, 5001047),
('ramayana-5-1-48', 48, 'Sundara Kanda, Sarga 1, Verse 48', 'विमुक्तास्तस्य वेगेन मुक्त्वा पुष्पाणि ते द्रुमाः।
अवशीर्यन्त सलिले निवृत्ताः सुहृदो यथा॥', 'vimuktās tasya vegena muktvā puṣpāṇi te drumāḥ
avaśīryanta salile nivṛttāḥ suhṛdo yathā', null, 5001048),
('ramayana-5-1-49', 49, 'Sundara Kanda, Sarga 1, Verse 49', 'लघुत्वेनोपपन्नं तद्विचित्रं सागरेऽपतत्।
द्रुमाणां विविधं पुष्पं कपिवायुसमीरितम्॥', 'laghutvenopapannaṃ tad vicitraṃ sāgare ''patat
drumāṇāṃ vividhaṃ puṣpaṃ kapivāyusamīritam', null, 5001049),
('ramayana-5-1-50', 50, 'Sundara Kanda, Sarga 1, Verse 50', 'पुष्पौघेणानुबद्धेन नानावर्णेन वानरः।
बभौ मेघ इवोद्यन्वै विद्युद्गणविभूषितः॥', 'puṣpaugheṇānubaddhena nānāvarṇena vānaraḥ
babhau megha ivodyan vai vidyudgaṇavibhūṣitaḥ', null, 5001050),
('ramayana-5-1-51', 51, 'Sundara Kanda, Sarga 1, Verse 51', 'तस्य वेगसमुद्भूतैः पुष्पैस्तोयमदृश्यत।
ताराभिरभिरामाभिरुदिताभिरिवाम्बरम्॥', 'tasya vegasamudbhūtaiḥ puṣpais toyam adṛśyata
tārābhir abhirāmābhir uditābhir ivāmbaram', null, 5001051),
('ramayana-5-1-52', 52, 'Sundara Kanda, Sarga 1, Verse 52', 'तस्याम्बरगतौ बाहू ददृशाते प्रसारितौ।
पर्वताग्राद्विनिष्क्रान्तौ पञ्चास्याविव पन्नगौ॥', 'tasyāmbaragatau bāhū dadṛśāte prasāritau
parvatāgrād viniṣkrāntau pañcāsyāv iva pannagau', null, 5001052),
('ramayana-5-1-53', 53, 'Sundara Kanda, Sarga 1, Verse 53', 'पिबन्निव बभौ चापि सोर्मिजालं महार्णवम्।
पिपासुरिव चाकाशं ददृशे स महाकपिः॥', 'pibann iva babhau cāpi sormijālaṃ mahārṇavam
pipāsur iva cākāśaṃ dadṛśe sa mahākapiḥ', null, 5001053),
('ramayana-5-1-54', 54, 'Sundara Kanda, Sarga 1, Verse 54', 'तस्य विद्युत्प्रभाकारे वायुमार्गानुसारिणः।
नयने विप्रकाशेते पर्वतस्थाविवानलौ॥', 'tasya vidyutprabhākāre vāyumārgānusāriṇaḥ
nayane viprakāśete parvatasthāv ivānalau', null, 5001054),
('ramayana-5-1-55', 55, 'Sundara Kanda, Sarga 1, Verse 55', 'पिङ्गे पिङ्गाक्षमुख्यस्य बृहती परिमण्डले।
चक्षुषी संप्रकशेते चन्द्रसूर्याविव स्थितौ॥', 'piṅge piṅgākṣamukhyasya bṛhatī parimaṇḍale
cakṣuṣī saṃprakaśete candrasūryāv iva sthitau', null, 5001055),
('ramayana-5-1-56', 56, 'Sundara Kanda, Sarga 1, Verse 56', 'मुखं नासिकया तस्य ताम्रया ताम्रमाबभौ।
संध्यया समभिस्पृष्टं यथा सूर्यस्य मण्डलम्॥', 'mukhaṃ nāsikayā tasya tāmrayā tāmram ābabhau
saṃdhyayā samabhispṛṣṭaṃ yathā sūryasya maṇḍalam', null, 5001056),
('ramayana-5-1-57', 57, 'Sundara Kanda, Sarga 1, Verse 57', 'लाङ्गलं च समाविद्धं प्लवमानस्य शोभते।
अम्बरे वायुपुत्रस्य शक्रध्वज इवोच्छ्रितः॥', 'lāṅgalaṃ ca samāviddhaṃ plavamānasya śobhate
ambare vāyuputrasya śakradhvaja ivocchritaḥ', null, 5001057),
('ramayana-5-1-58', 58, 'Sundara Kanda, Sarga 1, Verse 58', 'लाङ्गूलचक्रेण महाञ्शुक्लदंष्ट्रोऽनिलात्मजः।
व्यरोचत महाप्राज्ञः परिवेषीव भास्करः॥', 'lāṅgūlacakreṇa mahāñ śukladaṃṣṭro ''nilātmajaḥ
vyarocata mahāprājñaḥ pariveṣīva bhāskaraḥ', null, 5001058),
('ramayana-5-1-59', 59, 'Sundara Kanda, Sarga 1, Verse 59', 'स्फिग्देशेनाभिताम्रेण रराज स महाकपिः।
महता दारितेनेव गिरिर्गैरिकधातुना॥', 'sphigdeśenābhitāmreṇa rarāja sa mahākapiḥ
mahatā dāriteneva girir gairikadhātunā', null, 5001059),
('ramayana-5-1-60', 60, 'Sundara Kanda, Sarga 1, Verse 60', 'तस्य वानरसिंहस्य प्लवमानस्य सागरम्।
कक्षान्तरगतो वायुर्जीमूत इव गर्जति॥', 'tasya vānarasiṃhasya plavamānasya sāgaram
kakṣāntaragato vāyur jīmūta iva garjati', null, 5001060),
('ramayana-5-1-61', 61, 'Sundara Kanda, Sarga 1, Verse 61', 'खे यथा निपतत्युल्का उत्तरान्ताद्विनिःसृता।
दृश्यते सानुबन्धा च तथा स कपिकुञ्जरः॥', 'khe yathā nipataty ulkā uttarāntād viniḥsṛtā
dṛśyate sānubandhā ca tathā sa kapikuñjaraḥ', null, 5001061),
('ramayana-5-1-62', 62, 'Sundara Kanda, Sarga 1, Verse 62', 'पतत्पतंगसंकाशो व्यायतः शुशुभे कपिः।
प्रवृद्ध इव मातंगः कक्ष्यया बध्यमानया॥', 'patatpataṃgasaṃkāśo vyāyataḥ śuśubhe kapiḥ
pravṛddha iva mātaṃgaḥ kakṣyayā badhyamānayā', null, 5001062),
('ramayana-5-1-63', 63, 'Sundara Kanda, Sarga 1, Verse 63', 'उपरिष्टाच्छरीरेण छायया चावगाढया।
सागरे मारुताविष्टा नौरिवासीत्तदा कपिः॥', 'upariṣṭāc charīreṇa chāyayā cāvagāḍhayā
sāgare mārutāviṣṭā naur ivāsīt tadā kapiḥ', null, 5001063),
('ramayana-5-1-64', 64, 'Sundara Kanda, Sarga 1, Verse 64', 'यं यं देशं समुद्रस्य जगाम स महाकपिः।
स स तस्याङ्गवेगेन सोन्माद इव लक्ष्यते॥', 'yaṃ yaṃ deśaṃ samudrasya jagāma sa mahākapiḥ
sa sa tasyāṅgavegena sonmāda iva lakṣyate', null, 5001064),
('ramayana-5-1-65', 65, 'Sundara Kanda, Sarga 1, Verse 65', 'सागरस्योर्मिजालानामुरसा शैलवर्ष्मणाम्।
अभिघ्नंस्तु महावेगः पुप्लुवे स महाकपिः॥', 'sāgarasyormijālānām urasā śailavarṣmaṇām
abhighnaṃs tu mahāvegaḥ pupluve sa mahākapiḥ', null, 5001065),
('ramayana-5-1-66', 66, 'Sundara Kanda, Sarga 1, Verse 66', 'कपिवातश्च बलवान्मेघवातश्च निःसृतः।
सागरं भीमनिर्घोषं कम्पयामासतुर्भृशम्॥', 'kapivātaś ca balavān meghavātaś ca niḥsṛtaḥ
sāgaraṃ bhīmanirghoṣaṃ kampayām āsatur bhṛśam', null, 5001066),
('ramayana-5-1-67', 67, 'Sundara Kanda, Sarga 1, Verse 67', 'विकर्षन्नूर्मिजालानि बृहन्ति लवणाम्भसि।
अत्यक्रामन्महावेगस्तरङ्गान्गणयन्निव॥', 'vikarṣann ūrmijālāni bṛhanti lavaṇāmbhasi
atyakrāman mahāvegas taraṅgān gaṇayann iva', null, 5001067),
('ramayana-5-1-68', 68, 'Sundara Kanda, Sarga 1, Verse 68', 'प्लवमानं समीक्ष्याथ भुजङ्गाः सागरालयाः।
व्योम्नि तं कपिशार्दूलं सुपर्णमिति मेनिरे॥', 'plavamānaṃ samīkṣyātha bhujaṅgāḥ sāgarālayāḥ
vyomni taṃ kapiśārdūlaṃ suparṇam iti menire', null, 5001068),
('ramayana-5-1-69', 69, 'Sundara Kanda, Sarga 1, Verse 69', 'दशयोजनविस्तीर्णा त्रिंशद्योजनमायता।
छाया वानरसिंहस्य जले चारुतराभवत्॥', 'daśayojanavistīrṇā triṃśadyojanam āyatā
chāyā vānarasiṃhasya jale cārutarābhavat', null, 5001069),
('ramayana-5-1-70', 70, 'Sundara Kanda, Sarga 1, Verse 70', 'श्वेताभ्रघनराजीव वायुपुत्रानुगामिनी।
तस्य सा शुशुभे छाया वितता लवणाम्भसि॥', 'śvetābhraghanarājīva vāyuputrānugāminī
tasya sā śuśubhe chāyā vitatā lavaṇāmbhasi', null, 5001070),
('ramayana-5-1-71', 71, 'Sundara Kanda, Sarga 1, Verse 71', 'प्लवमानं तु तं दृष्ट्वा प्लवगं त्वरितं तदा।
ववृषुः पुष्पवर्षाणि देवगन्धर्वदानवाः॥', 'plavamānaṃ tu taṃ dṛṣṭvā plavagaṃ tvaritaṃ tadā
vavṛṣuḥ puṣpavarṣāṇi devagandharvadānavāḥ', null, 5001071),
('ramayana-5-1-72', 72, 'Sundara Kanda, Sarga 1, Verse 72', 'तताप न हि तं सूर्यः प्लवन्तं वानरेश्वरम्।
सिषेवे च तदा वायू रामकार्यार्थसिद्धये॥', 'tatāpa na hi taṃ sūryaḥ plavantaṃ vānareśvaram
siṣeve ca tadā vāyū rāmakāryārthasiddhaye', null, 5001072),
('ramayana-5-1-73', 73, 'Sundara Kanda, Sarga 1, Verse 73', 'ऋषयस्तुष्टुवुश्चैनं प्लवमानं विहायसा।
जगुश्च देवगन्धर्वाः प्रशंसन्तो महौजसं॥', 'ṛṣayas tuṣṭuvuś cainaṃ plavamānaṃ vihāyasā
jaguś ca devagandharvāḥ praśaṃsanto mahaujasaṃ', null, 5001073),
('ramayana-5-1-74', 74, 'Sundara Kanda, Sarga 1, Verse 74', 'नागाश्च तुष्टुवुर्यक्षा रक्षांसि विबुधाः खगाः।
प्रेक्ष्याकाशे कपिवरं सहसा विगतक्लमम्॥', 'nāgāś ca tuṣṭuvur yakṣā rakṣāṃsi vibudhāḥ khagāḥ
prekṣyākāśe kapivaraṃ sahasā vigataklamam', null, 5001074),
('ramayana-5-1-75', 75, 'Sundara Kanda, Sarga 1, Verse 75', 'तस्मिन्प्लवगशार्दूले प्लवमाने हनूमति।
इक्ष्वाकुकुलमानार्थी चिन्तयामास सागरः॥', 'tasmin plavagaśārdūle plavamāne hanūmati
ikṣvākukulamānārthī cintayām āsa sāgaraḥ', null, 5001075),
('ramayana-5-1-76', 76, 'Sundara Kanda, Sarga 1, Verse 76', 'साहाय्यं वानरेन्द्रस्य यदि नाहं हनूमतः।
करिष्यामि भविष्यामि सर्ववाच्यो विवक्षताम्॥', 'sāhāyyaṃ vānarendrasya yadi nāhaṃ hanūmataḥ
kariṣyāmi bhaviṣyāmi sarvavācyo vivakṣatām', null, 5001076),
('ramayana-5-1-77', 77, 'Sundara Kanda, Sarga 1, Verse 77', 'अहमिक्ष्वाकुनाथेन सगरेण विवर्धितः।
इक्ष्वाकुसचिवश्चायं नावसीदितुमर्हति॥', 'aham ikṣvākunāthena sagareṇa vivardhitaḥ
ikṣvākusacivaś cāyaṃ nāvasīditum arhati', null, 5001077),
('ramayana-5-1-78', 78, 'Sundara Kanda, Sarga 1, Verse 78', 'तथा मया विधातव्यं विश्रमेत यथा कपिः।
शेषं च मयि विश्रान्तः सुखेनातिपतिष्यति॥', 'tathā mayā vidhātavyaṃ viśrameta yathā kapiḥ
śeṣaṃ ca mayi viśrāntaḥ sukhenātipatiṣyati', null, 5001078),
('ramayana-5-1-79', 79, 'Sundara Kanda, Sarga 1, Verse 79', 'इति कृत्वा मतिं साध्वीं समुद्रश्छन्नमम्भसि।
हिरण्यनाभं मैनाकमुवाच गिरिसत्तमम्॥', 'iti kṛtvā matiṃ sādhvīṃ samudraś channam ambhasi
hiraṇyanābhaṃ mainākam uvāca girisattamam', null, 5001079),
('ramayana-5-1-80', 80, 'Sundara Kanda, Sarga 1, Verse 80', 'त्वमिहासुरसंघानां पातालतलवासिनाम्।
देवराज्ञा गिरिश्रेष्ठ परिघः संनिवेशितः॥', 'tvam ihāsurasaṃghānāṃ pātālatalavāsinām
devarājñā giriśreṣṭha parighaḥ saṃniveśitaḥ', null, 5001080),
('ramayana-5-1-81', 81, 'Sundara Kanda, Sarga 1, Verse 81', 'त्वमेषां ज्ञातवीर्याणां पुनरेवोत्पतिष्यताम्।
पातालस्याप्रमेयस्य द्वारमावृत्य तिष्ठसि॥', 'tvam eṣāṃ jñātavīryāṇāṃ punar evotpatiṣyatām
pātālasyāprameyasya dvāram āvṛtya tiṣṭhasi', null, 5001081),
('ramayana-5-1-82', 82, 'Sundara Kanda, Sarga 1, Verse 82', 'तिर्यगूर्ध्वमधश्चैव शक्तिस्ते शैलवर्धितुम्।
तस्मात्संचोदयामि त्वामुत्तिष्ठ नगसत्तम॥', 'tiryag ūrdhvam adhaś caiva śaktis te śailavardhitum
tasmāt saṃcodayāmi tvām uttiṣṭha nagasattama', null, 5001082),
('ramayana-5-1-83', 83, 'Sundara Kanda, Sarga 1, Verse 83', 'स एष कपिशार्दूलस्त्वामुपर्येति वीर्यवान्।
हनूमान्रामकार्यार्थं भीमकर्मा खमाप्लुतः॥', 'sa eṣa kapiśārdūlas tvām uparyeti vīryavān
hanūmān rāmakāryārthaṃ bhīmakarmā kham āplutaḥ', null, 5001083),
('ramayana-5-1-84', 84, 'Sundara Kanda, Sarga 1, Verse 84', 'तस्य साह्यं मया कार्यमिक्ष्वाकुकुलवर्तिनः।
मम इक्ष्वाकवः पूज्याः परं पूज्यतमास्तव॥', 'tasya sāhyaṃ mayā kāryam ikṣvākukulavartinaḥ
mama ikṣvākavaḥ pūjyāḥ paraṃ pūjyatamās tava', null, 5001084),
('ramayana-5-1-85', 85, 'Sundara Kanda, Sarga 1, Verse 85', 'कुरु साचिव्यमस्माकं न नः कार्यमतिक्रमेत्।
कर्तव्यमकृतं कार्यं सतां मन्युमुदीरयेत्॥', 'kuru sācivyam asmākaṃ na naḥ kāryam atikramet
kartavyam akṛtaṃ kāryaṃ satāṃ manyum udīrayet', null, 5001085),
('ramayana-5-1-86', 86, 'Sundara Kanda, Sarga 1, Verse 86', 'सलिलादूर्ध्वमुत्तिष्ठ तिष्ठत्वेष कपिस्त्वयि।
अस्माकमतिथिश्चैव पूज्यश्च प्लवतां वरः॥', 'salilād ūrdhvam uttiṣṭha tiṣṭhatv eṣa kapis tvayi
asmākam atithiś caiva pūjyaś ca plavatāṃ varaḥ', null, 5001086),
('ramayana-5-1-87', 87, 'Sundara Kanda, Sarga 1, Verse 87', 'चामीकरमहानाभ देवगन्धर्वसेवित।
हनूमांस्त्वयि विश्रान्तस्ततः शेषं गमिष्यति॥', 'cāmīkaramahānābha devagandharvasevita
hanūmāṃs tvayi viśrāntas tataḥ śeṣaṃ gamiṣyati', null, 5001087),
('ramayana-5-1-88', 88, 'Sundara Kanda, Sarga 1, Verse 88', 'काकुत्स्थस्यानृशंस्यं च मैथिल्याश्च विवासनम्।
श्रमं च प्लवगेन्द्रस्य समीक्ष्योत्थातुमर्हसि॥', 'kākutsthasyānṛśaṃsyaṃ ca maithilyāś ca vivāsanam
śramaṃ ca plavagendrasya samīkṣyotthātum arhasi', null, 5001088),
('ramayana-5-1-89', 89, 'Sundara Kanda, Sarga 1, Verse 89', 'हिरण्यनाभो मैनाको निशम्य लवणाम्भसः।
उत्पपात जलात्तूर्णं महाद्रुमलतायुतः॥', 'hiraṇyanābho maināko niśamya lavaṇāmbhasaḥ
utpapāta jalāt tūrṇaṃ mahādrumalatāyutaḥ', null, 5001089),
('ramayana-5-1-90', 90, 'Sundara Kanda, Sarga 1, Verse 90', 'स सागरजलं भित्त्वा बभूवात्युत्थितस्तदा।
यथा जलधरं भित्त्वा दीप्तरश्मिर्दिवाकरः॥', 'sa sāgarajalaṃ bhittvā babhūvātyutthitas tadā
yathā jaladharaṃ bhittvā dīptaraśmir divākaraḥ', null, 5001090),
('ramayana-5-1-91', 91, 'Sundara Kanda, Sarga 1, Verse 91', 'शातकुम्भमयैः शृङ्गैः सकिंनरमहोरगैः।
आदित्योदयसंकाशैरालिखद्भिरिवाम्बरम्॥', 'śātakumbhamayaiḥ śṛṅgaiḥ sakiṃnaramahoragaiḥ
ādityodayasaṃkāśair ālikhadbhir ivāmbaram', null, 5001091),
('ramayana-5-1-92', 92, 'Sundara Kanda, Sarga 1, Verse 92', 'तस्य जाम्बूनदैः शृङ्गैः पर्वतस्य समुत्थितैः।
आकाशं शस्त्रसंकाशमभवत्काञ्चनप्रभम्॥', 'tasya jāmbūnadaiḥ śṛṅgaiḥ parvatasya samutthitaiḥ
ākāśaṃ śastrasaṃkāśam abhavat kāñcanaprabham', null, 5001092),
('ramayana-5-1-93', 93, 'Sundara Kanda, Sarga 1, Verse 93', 'जातरूपमयैः शृङ्गैर्भ्राजमानैः स्वयं प्रभैः।
आदित्यशतसंकाशः सोऽभवद्गिरिसत्तमः॥', 'jātarūpamayaiḥ śṛṅgair bhrājamānaiḥ svayaṃ prabhaiḥ
ādityaśatasaṃkāśaḥ so ''bhavad girisattamaḥ', null, 5001093),
('ramayana-5-1-94', 94, 'Sundara Kanda, Sarga 1, Verse 94', 'तमुत्थितमसंगेन हनूमानग्रतः स्थितम्।
मध्ये लवणतोयस्य विघ्नोऽयमिति निश्चितः॥', 'tam utthitam asaṃgena hanūmān agrataḥ sthitam
madhye lavaṇatoyasya vighno ''yam iti niścitaḥ', null, 5001094),
('ramayana-5-1-95', 95, 'Sundara Kanda, Sarga 1, Verse 95', 'स तमुच्छ्रितमत्यर्थं महावेगो महाकपिः।
उरसा पातयामास जीमूतमिव मारुतः॥', 'sa tam ucchritam atyarthaṃ mahāvego mahākapiḥ
urasā pātayām āsa jīmūtam iva mārutaḥ', null, 5001095),
('ramayana-5-1-96', 96, 'Sundara Kanda, Sarga 1, Verse 96', 'स तदा पातितस्तेन कपिना पर्वतोत्तमः।
बुद्ध्वा तस्य कपेर्वेगं जहर्ष च ननन्द च॥', 'sa tadā pātitas tena kapinā parvatottamaḥ
buddhvā tasya kaper vegaṃ jaharṣa ca nananda ca', null, 5001096),
('ramayana-5-1-97', 97, 'Sundara Kanda, Sarga 1, Verse 97', 'तमाकाशगतं वीरमाकाशे समवस्थितम्।
प्रीतो हृष्टमना वाक्यमब्रवीत्पर्वतः कपिम्।
मानुषं धरयन्रूपमात्मनः शिखरे स्थितः॥', 'tam ākāśagataṃ vīram ākāśe samavasthitam
prīto hṛṣṭamanā vākyam abravīt parvataḥ kapim
mānuṣaṃ dharayan rūpam ātmanaḥ śikhare sthitaḥ', null, 5001097),
('ramayana-5-1-98', 98, 'Sundara Kanda, Sarga 1, Verse 98', 'दुष्करं कृतवान्कर्म त्वमिदं वानरोत्तम।
निपत्य मम शृङ्गेषु विश्रमस्व यथासुखम्॥', 'duṣkaraṃ kṛtavān karma tvam idaṃ vānarottama
nipatya mama śṛṅgeṣu viśramasva yathāsukham', null, 5001098),
('ramayana-5-1-99', 99, 'Sundara Kanda, Sarga 1, Verse 99', 'राघावस्य कुले जातैरुदधिः परिवर्धितः।
स त्वां रामहिते युक्तं प्रत्यर्चयति सागरः॥', 'rāghāvasya kule jātair udadhiḥ parivardhitaḥ
sa tvāṃ rāmahite yuktaṃ pratyarcayati sāgaraḥ', null, 5001099),
('ramayana-5-1-100', 100, 'Sundara Kanda, Sarga 1, Verse 100', 'कृते च प्रतिकर्तव्यमेष धर्मः सनातनः।
सोऽयं तत्प्रतिकारार्थी त्वत्तः संमानमर्हति॥', 'kṛte ca pratikartavyam eṣa dharmaḥ sanātanaḥ
so ''yaṃ tat pratikārārthī tvattaḥ saṃmānam arhati', null, 5001100),
('ramayana-5-1-101', 101, 'Sundara Kanda, Sarga 1, Verse 101', 'त्वन्निमित्तमनेनाहं बहुमानात्प्रचोदितः।
योजनानां शतं चापि कपिरेष समाप्लुतः।
तव सानुषु विश्रान्तः शेषं प्रक्रमतामिति॥', 'tvannimittam anenāhaṃ bahumānāt pracoditaḥ
yojanānāṃ śataṃ cāpi kapir eṣa samāplutaḥ
tava sānuṣu viśrāntaḥ śeṣaṃ prakramatām iti', null, 5001101),
('ramayana-5-1-102', 102, 'Sundara Kanda, Sarga 1, Verse 102', 'तिष्ठ त्वं हरिशार्दूल मयि विश्रम्य गम्यताम्।
तदिदं गन्धवत्स्वादु कन्दमूलफलं बहु।
तदास्वाद्य हरिश्रेष्ठ विश्रान्तोऽनुगमिष्यसि॥', 'tiṣṭha tvaṃ hariśārdūla mayi viśramya gamyatām
tad idaṃ gandhavat svādu kandamūlaphalaṃ bahu
tad āsvādya hariśreṣṭha viśrānto ''nugamiṣyasi', null, 5001102),
('ramayana-5-1-103', 103, 'Sundara Kanda, Sarga 1, Verse 103', 'अस्माकमपि संबन्धः कपिमुख्यस्त्वयास्ति वै।
प्रख्यातस्त्रिषु लोकेषु महागुणपरिग्रहः॥', 'asmākam api saṃbandhaḥ kapimukhyas tvayāsti vai
prakhyātas triṣu lokeṣu mahāguṇaparigrahaḥ', null, 5001103),
('ramayana-5-1-104', 104, 'Sundara Kanda, Sarga 1, Verse 104', 'वेगवन्तः प्लवन्तो ये प्लवगा मारुतात्मज।
तेषां मुख्यतमं मन्ये त्वामहं कपिकुञ्जर॥', 'vegavantaḥ plavanto ye plavagā mārutātmaja
teṣāṃ mukhyatamaṃ manye tvām ahaṃ kapikuñjara', null, 5001104),
('ramayana-5-1-105', 105, 'Sundara Kanda, Sarga 1, Verse 105', 'अतिथिः किल पूजार्हः प्राकृतोऽपि विजानता।
धर्मं जिज्ञासमानेन किं पुनर्यादृशो भवान्॥', 'atithiḥ kila pūjārhaḥ prākṛto ''pi vijānatā
dharmaṃ jijñāsamānena kiṃ punar yādṛśo bhavān', null, 5001105),
('ramayana-5-1-106', 106, 'Sundara Kanda, Sarga 1, Verse 106', 'त्वं हि देववरिष्ठस्य मारुतस्य महात्मनः।
पुत्रस्तस्यैव वेगेन सदृशः कपिकुञ्जर॥', 'tvaṃ hi devavariṣṭhasya mārutasya mahātmanaḥ
putras tasyaiva vegena sadṛśaḥ kapikuñjara', null, 5001106),
('ramayana-5-1-107', 107, 'Sundara Kanda, Sarga 1, Verse 107', 'पूजिते त्वयि धर्मज्ञ पूजां प्राप्नोति मारुतः।
तस्मात्त्वं पूजनीयो मे शृणु चाप्यत्र कारणम्॥', 'pūjite tvayi dharmajña pūjāṃ prāpnoti mārutaḥ
tasmāt tvaṃ pūjanīyo me śṛṇu cāpy atra kāraṇam', null, 5001107),
('ramayana-5-1-108', 108, 'Sundara Kanda, Sarga 1, Verse 108', 'पूर्वं कृतयुगे तात पर्वताः पक्षिणोऽभवन्।
तेऽपि जग्मुर्दिशः सर्वा गरुडानिलवेगिनः॥', 'pūrvaṃ kṛtayuge tāta parvatāḥ pakṣiṇo ''bhavan
te ''pi jagmur diśaḥ sarvā garuḍānilaveginaḥ', null, 5001108),
('ramayana-5-1-109', 109, 'Sundara Kanda, Sarga 1, Verse 109', 'ततस्तेषु प्रयातेषु देवसंघाः सहर्षिभिः।
भूतानि च भयं जग्मुस्तेषां पतनशङ्कया॥', 'tatas teṣu prayāteṣu devasaṃghāḥ saharṣibhiḥ
bhūtāni ca bhayaṃ jagmus teṣāṃ patanaśaṅkayā', null, 5001109),
('ramayana-5-1-110', 110, 'Sundara Kanda, Sarga 1, Verse 110', 'ततः क्रुद्धः सहस्राक्षः पर्वतानां शतक्रतुः।
पक्षांश्चिच्छेद वज्रेण तत्र तत्र सहस्रशः॥', 'tataḥ kruddhaḥ sahasrākṣaḥ parvatānāṃ śatakratuḥ
pakṣāṃś ciccheda vajreṇa tatra tatra sahasraśaḥ', null, 5001110),
('ramayana-5-1-111', 111, 'Sundara Kanda, Sarga 1, Verse 111', 'स मामुपगतः क्रुद्धो वज्रमुद्यम्य देवराट्।
ततोऽहं सहसा क्षिप्तः श्वसनेन महात्मना॥', 'sa mām upagataḥ kruddho vajram udyamya devarāṭ
tato ''haṃ sahasā kṣiptaḥ śvasanena mahātmanā', null, 5001111),
('ramayana-5-1-112', 112, 'Sundara Kanda, Sarga 1, Verse 112', 'अस्मिंल्लवणतोये च प्रक्षिप्तः प्लवगोत्तम।
गुप्तपक्षः समग्रश्च तव पित्राभिरक्षितः॥', 'asmiṃl lavaṇatoye ca prakṣiptaḥ plavagottama
guptapakṣaḥ samagraś ca tava pitrābhirakṣitaḥ', null, 5001112),
('ramayana-5-1-113', 113, 'Sundara Kanda, Sarga 1, Verse 113', 'ततोऽहं मानयामि त्वां मान्यो हि मम मारुतः।
त्वया मे ह्येष संबन्धः कपिमुख्य महागुणः॥', 'tato ''haṃ mānayāmi tvāṃ mānyo hi mama mārutaḥ
tvayā me hy eṣa saṃbandhaḥ kapimukhya mahāguṇaḥ', null, 5001113),
('ramayana-5-1-114', 114, 'Sundara Kanda, Sarga 1, Verse 114', 'अस्मिन्नेवंगते कार्ये सागरस्य ममैव च।
प्रीतिं प्रीतमना कर्तुं त्वमर्हसि महाकपे॥', 'asminn evaṃgate kārye sāgarasya mamaiva ca
prītiṃ prītamanā kartuṃ tvam arhasi mahākape', null, 5001114),
('ramayana-5-1-115', 115, 'Sundara Kanda, Sarga 1, Verse 115', 'श्रमं मोक्षय पूजां च गृहाण कपिसत्तम।
प्रीतिं च बहुमन्यस्व प्रीतोऽस्मि तव दर्शनात्॥', 'śramaṃ mokṣaya pūjāṃ ca gṛhāṇa kapisattama
prītiṃ ca bahumanyasva prīto ''smi tava darśanāt', null, 5001115),
('ramayana-5-1-116', 116, 'Sundara Kanda, Sarga 1, Verse 116', 'एवमुक्तः कपिश्रेष्ठस्तं नगोत्तममब्रवीत्।
प्रीतोऽस्मि कृतमातिथ्यं मन्युरेषोऽपनीयताम्॥', 'evam uktaḥ kapiśreṣṭhas taṃ nagottamam abravīt
prīto ''smi kṛtam ātithyaṃ manyur eṣo ''panīyatām', null, 5001116),
('ramayana-5-1-117', 117, 'Sundara Kanda, Sarga 1, Verse 117', 'त्वरते कार्यकालो मे अहश्चाप्यतिवर्तते।
प्रतिज्ञा च मया दत्ता न स्थातव्यमिहान्तरा॥', 'tvarate kāryakālo me ahaś cāpy ativartate
pratijñā ca mayā dattā na sthātavyam ihāntarā', null, 5001117),
('ramayana-5-1-118', 118, 'Sundara Kanda, Sarga 1, Verse 118', 'इत्युक्त्वा पाणिना शैलमालभ्य हरिपुंगवः।
जगामाकाशमाविश्य वीर्यवान्प्रहसन्निव॥', 'ity uktvā pāṇinā śailam ālabhya haripuṃgavaḥ
jagāmākāśam āviśya vīryavān prahasann iva', null, 5001118),
('ramayana-5-1-119', 119, 'Sundara Kanda, Sarga 1, Verse 119', 'स पर्वतसमुद्राभ्यां बहुमानादवेक्षितः।
पूजितश्चोपपन्नाभिराशीर्भिरनिलात्मजः॥', 'sa parvatasamudrābhyāṃ bahumānād avekṣitaḥ
pūjitaś copapannābhir āśīrbhir anilātmajaḥ', null, 5001119),
('ramayana-5-1-120', 120, 'Sundara Kanda, Sarga 1, Verse 120', 'अथोर्ध्वं दूरमुत्पत्य हित्वा शैलमहार्णवौ।
पितुः पन्थानमास्थाय जगाम विमलेऽम्बरे॥', 'athordhvaṃ dūram utpatya hitvā śailamahārṇavau
pituḥ panthānam āsthāya jagāma vimale ''mbare', null, 5001120),
('ramayana-5-1-121', 121, 'Sundara Kanda, Sarga 1, Verse 121', 'भूयश्चोर्ध्वगतिं प्राप्य गिरिं तमवलोकयन्।
वायुसूनुर्निरालम्बे जगाम विमलेऽम्बरे॥', 'bhūyaś cordhvagatiṃ prāpya giriṃ tam avalokayan
vāyusūnur nirālambe jagāma vimale ''mbare', null, 5001121),
('ramayana-5-1-122', 122, 'Sundara Kanda, Sarga 1, Verse 122', 'तद्द्वितीयं हनुमतो दृष्ट्वा कर्म सुदुष्करम्।
प्रशशंसुः सुराः सर्वे सिद्धाश्च परमर्षयः॥', 'tad dvitīyaṃ hanumato dṛṣṭvā karma suduṣkaram
praśaśaṃsuḥ surāḥ sarve siddhāś ca paramarṣayaḥ', null, 5001122),
('ramayana-5-1-123', 123, 'Sundara Kanda, Sarga 1, Verse 123', 'देवताश्चाभवन्हृष्टास्तत्रस्थास्तस्य कर्मणा।
काञ्चनस्य सुनाभस्य सहस्राक्षश्च वासवः॥', 'devatāś cābhavan hṛṣṭās tatrasthās tasya karmaṇā
kāñcanasya sunābhasya sahasrākṣaś ca vāsavaḥ', null, 5001123),
('ramayana-5-1-124', 124, 'Sundara Kanda, Sarga 1, Verse 124', 'उवाच वचनं धीमान्परितोषात्सगद्गदम्।
सुनाभं पर्वतश्रेष्ठं स्वयमेव शचीपतिः॥', 'uvāca vacanaṃ dhīmān paritoṣāt sagadgadam
sunābhaṃ parvataśreṣṭhaṃ svayam eva śacīpatiḥ', null, 5001124),
('ramayana-5-1-125', 125, 'Sundara Kanda, Sarga 1, Verse 125', 'हिरण्यनाभशैलेन्द्रपरितुष्टोऽस्मि ते भृशम्।
अभयं ते प्रयच्छामि तिष्ठ सौम्य यथासुखम्॥', 'hiraṇyanābhaśailendraparituṣṭo ''smi te bhṛśam
abhayaṃ te prayacchāmi tiṣṭha saumya yathāsukham', null, 5001125),
('ramayana-5-1-126', 126, 'Sundara Kanda, Sarga 1, Verse 126', 'साह्यं कृतं ते सुमहद्विक्रान्तस्य हनूमतः।
क्रमतो योजनशतं निर्भयस्य भये सति॥', 'sāhyaṃ kṛtaṃ te sumahad vikrāntasya hanūmataḥ
kramato yojanaśataṃ nirbhayasya bhaye sati', null, 5001126),
('ramayana-5-1-127', 127, 'Sundara Kanda, Sarga 1, Verse 127', 'रामस्यैष हि दौत्येन याति दाशरथेर्हरिः।
सत्क्रियां कुर्वता शक्या तोषितोऽस्मि दृढं त्वया॥', 'rāmasyaiṣa hi dautyena yāti dāśarather hariḥ
satkriyāṃ kurvatā śakyā toṣito ''smi dṛḍhaṃ tvayā', null, 5001127),
('ramayana-5-1-128', 128, 'Sundara Kanda, Sarga 1, Verse 128', 'ततः प्रहर्षमलभद्विपुलं पर्वतोत्तमः।
देवतानां पतिं दृष्ट्वा परितुष्टं शतक्रतुम्॥', 'tataḥ praharṣam alabhad vipulaṃ parvatottamaḥ
devatānāṃ patiṃ dṛṣṭvā parituṣṭaṃ śatakratum', null, 5001128),
('ramayana-5-1-129', 129, 'Sundara Kanda, Sarga 1, Verse 129', 'स वै दत्तवरः शैलो बभूवावस्थितस्तदा।
हनूमांश्च मुहूर्तेन व्यतिचक्राम सागरम्॥', 'sa vai dattavaraḥ śailo babhūvāvasthitas tadā
hanūmāṃś ca muhūrtena vyaticakrāma sāgaram', null, 5001129),
('ramayana-5-1-130', 130, 'Sundara Kanda, Sarga 1, Verse 130', 'ततो देवाः सगन्धर्वाः सिद्धाश्च परमर्षयः।
अब्रुवन्सूर्यसंकाशां सुरसां नागमातरम्॥', 'tato devāḥ sagandharvāḥ siddhāś ca paramarṣayaḥ
abruvan sūryasaṃkāśāṃ surasāṃ nāgamātaram', null, 5001130),
('ramayana-5-1-131', 131, 'Sundara Kanda, Sarga 1, Verse 131', 'अयं वातात्मजः श्रीमान्प्लवते सागरोपरि।
हनूमान्नाम तस्य त्वं मुहूर्तं विघ्नमाचर॥', 'ayaṃ vātātmajaḥ śrīmān plavate sāgaropari
hanūmān nāma tasya tvaṃ muhūrtaṃ vighnam ācara', null, 5001131),
('ramayana-5-1-132', 132, 'Sundara Kanda, Sarga 1, Verse 132', 'राक्षसं रूपमास्थाय सुघोरं पर्वतोपमम्।
दंष्ट्राकरालं पिङ्गाक्षं वक्त्रं कृत्वा नभःस्पृशम्॥', 'rākṣasaṃ rūpam āsthāya sughoraṃ parvatopamam
daṃṣṭrākarālaṃ piṅgākṣaṃ vaktraṃ kṛtvā nabhaḥspṛśam', null, 5001132),
('ramayana-5-1-133', 133, 'Sundara Kanda, Sarga 1, Verse 133', 'बलमिच्छामहे ज्ञातुं भूयश्चास्य पराक्रमम्।
त्वां विजेष्यत्युपायेन विषदं वा गमिष्यति॥', 'balam icchāmahe jñātuṃ bhūyaś cāsya parākramam
tvāṃ vijeṣyaty upāyena viṣadaṃ vā gamiṣyati', null, 5001133),
('ramayana-5-1-134', 134, 'Sundara Kanda, Sarga 1, Verse 134', 'एवमुक्ता तु सा देवी दैवतैरभिसत्कृता।
समुद्रमध्ये सुरसा बिभ्रती राक्षसं वपुः॥', 'evam uktā tu sā devī daivatair abhisatkṛtā
samudramadhye surasā bibhratī rākṣasaṃ vapuḥ', null, 5001134),
('ramayana-5-1-135', 135, 'Sundara Kanda, Sarga 1, Verse 135', 'विकृतं च विरूपं च सर्वस्य च भयावहम्।
प्लवमानं हनूमन्तमावृत्येदमुवाच ह॥', 'vikṛtaṃ ca virūpaṃ ca sarvasya ca bhayāvaham
plavamānaṃ hanūmantam āvṛtyedam uvāca ha', null, 5001135),
('ramayana-5-1-136', 136, 'Sundara Kanda, Sarga 1, Verse 136', 'मम भक्षः प्रदिष्टस्त्वमीश्वरैर्वानरर्षभ।
अहं त्वां भक्षयिष्यामि प्रविशेदं ममाननम्॥', 'mama bhakṣaḥ pradiṣṭas tvam īśvarair vānararṣabha
ahaṃ tvāṃ bhakṣayiṣyāmi praviśedaṃ mamānanam', null, 5001136),
('ramayana-5-1-137', 137, 'Sundara Kanda, Sarga 1, Verse 137', 'एवमुक्तः सुरसया प्राञ्जलिर्वानरर्षभः।
प्रहृष्टवदनः श्रीमानिदं वचनमब्रवीत्॥', 'evam uktaḥ surasayā prāñjalir vānararṣabhaḥ
prahṛṣṭavadanaḥ śrīmān idaṃ vacanam abravīt', null, 5001137),
('ramayana-5-1-138', 138, 'Sundara Kanda, Sarga 1, Verse 138', 'रामो दाशरथिर्नाम प्रविष्टो दण्डकावनम्।
लक्ष्मणेन सह भ्रात्रा वैदेह्या चापि भार्यया॥', 'rāmo dāśarathir nāma praviṣṭo daṇḍakāvanam
lakṣmaṇena saha bhrātrā vaidehyā cāpi bhāryayā', null, 5001138),
('ramayana-5-1-139', 139, 'Sundara Kanda, Sarga 1, Verse 139', 'अस्य कार्यविषक्तस्य बद्धवैरस्य राक्षसैः।
तस्य सीता हृता भार्या रावणेन यशस्विनी॥', 'asya kāryaviṣaktasya baddhavairasya rākṣasaiḥ
tasya sītā hṛtā bhāryā rāvaṇena yaśasvinī', null, 5001139),
('ramayana-5-1-140', 140, 'Sundara Kanda, Sarga 1, Verse 140', 'तस्याः सकाशं दूतोऽहं गमिष्ये रामशासनात्।
कर्तुमर्हसि रामस्य साह्यं विषयवासिनि॥', 'tasyāḥ sakāśaṃ dūto ''haṃ gamiṣye rāmaśāsanāt
kartum arhasi rāmasya sāhyaṃ viṣayavāsini', null, 5001140),
('ramayana-5-1-141', 141, 'Sundara Kanda, Sarga 1, Verse 141', 'अथ वा मैथिलीं दृष्ट्वा रामं चाक्लिष्टकारिणम्।
आगमिष्यामि ते वक्त्रं सत्यं प्रतिशृणोमि ते॥', 'atha vā maithilīṃ dṛṣṭvā rāmaṃ cākliṣṭakāriṇam
āgamiṣyāmi te vaktraṃ satyaṃ pratiśṛṇomi te', null, 5001141),
('ramayana-5-1-142', 142, 'Sundara Kanda, Sarga 1, Verse 142', 'एवमुक्ता हनुमता सुरसा कामरूपिणी।
अब्रवीन्नातिवर्तेन्मां कश्चिदेष वरो मम॥', 'evam uktā hanumatā surasā kāmarūpiṇī
abravīn nātivarten māṃ kaś cid eṣa varo mama', null, 5001142),
('ramayana-5-1-143', 143, 'Sundara Kanda, Sarga 1, Verse 143', 'एवमुक्तः सुरसया क्रुद्धो वानरपुंगवः।
अब्रवीत्कुरु वै वक्त्रं येन मां विषहिष्यसे॥', 'evam uktaḥ surasayā kruddho vānarapuṃgavaḥ
abravīt kuru vai vaktraṃ yena māṃ viṣahiṣyase', null, 5001143),
('ramayana-5-1-144', 144, 'Sundara Kanda, Sarga 1, Verse 144', 'इत्युक्त्वा सुरसां क्रुद्धो दशयोजनमायतः।
दशयोजनविस्तारो बभूव हनुमांस्तदा॥', 'ity uktvā surasāṃ kruddho daśayojanam āyataḥ
daśayojanavistāro babhūva hanumāṃs tadā', null, 5001144),
('ramayana-5-1-145', 145, 'Sundara Kanda, Sarga 1, Verse 145', 'तं दृष्ट्वा मेघसंकाशं दशयोजनमायतम्।
चकार सुरसाप्यास्यं विंशद्योजनमायतम्॥', 'taṃ dṛṣṭvā meghasaṃkāśaṃ daśayojanam āyatam
cakāra surasāpy āsyaṃ viṃśadyojanam āyatam', null, 5001145),
('ramayana-5-1-146', 146, 'Sundara Kanda, Sarga 1, Verse 146', 'हनुमांस्तु ततः क्रुद्धस्त्रिंशद्योजनमायतः।
चकार सुरसा वक्त्रं चत्वारिंशत्तथोच्छ्रितम्॥', 'hanumāṃs tu tataḥ kruddhas triṃśadyojanam āyataḥ
cakāra surasā vaktraṃ catvāriṃśat tathocchritam', null, 5001146),
('ramayana-5-1-147', 147, 'Sundara Kanda, Sarga 1, Verse 147', 'बभूव हनुमान्वीरः पञ्चाशद्योजनोच्छ्रितः।
चकार सुरसा वक्त्रं षष्टियोजनमायतम्॥', 'babhūva hanumān vīraḥ pañcāśadyojanocchritaḥ
cakāra surasā vaktraṃ ṣaṣṭiyojanam āyatam', null, 5001147),
('ramayana-5-1-148', 148, 'Sundara Kanda, Sarga 1, Verse 148', 'तथैव हनुमान्वीरः सप्ततिं योजनोच्छ्रितः।
चकार सुरसा वक्त्रमशीतिं योजनायतम्॥', 'tathaiva hanumān vīraḥ saptatiṃ yojanocchritaḥ
cakāra surasā vaktram aśītiṃ yojanāyatam', null, 5001148),
('ramayana-5-1-149', 149, 'Sundara Kanda, Sarga 1, Verse 149', 'हनूमानचल प्रख्यो नवतिं योजनोच्छ्रितः।
चकार सुरसा वक्त्रं शतयोजनमायतम्॥', 'hanūmān acala prakhyo navatiṃ yojanocchritaḥ
cakāra surasā vaktraṃ śatayojanam āyatam', null, 5001149),
('ramayana-5-1-150', 150, 'Sundara Kanda, Sarga 1, Verse 150', 'तद्दृष्ट्वा व्यादितं त्वास्यं वायुपुत्रः स बुद्धिमान्।
दीर्घजिह्वं सुरसया सुघोरं नरकोपमम्॥', 'tad dṛṣṭvā vyāditaṃ tv āsyaṃ vāyuputraḥ sa buddhimān
dīrghajihvaṃ surasayā sughoraṃ narakopamam', null, 5001150),
('ramayana-5-1-151', 151, 'Sundara Kanda, Sarga 1, Verse 151', 'स संक्षिप्यात्मनः कायं जीमूत इव मारुतिः।
तस्मिन्मुहूर्ते हनुमान्बभूवाङ्गुष्ठमात्रकः॥', 'sa saṃkṣipyātmanaḥ kāyaṃ jīmūta iva mārutiḥ
tasmin muhūrte hanumān babhūvāṅguṣṭhamātrakaḥ', null, 5001151),
('ramayana-5-1-152', 152, 'Sundara Kanda, Sarga 1, Verse 152', 'सोऽभिपत्याशु तद्वक्त्रं निष्पत्य च महाजवः।
अन्तरिक्षे स्थितः श्रीमानिदं वचनमब्रवीत्॥', 'so ''bhipatyāśu tad vaktraṃ niṣpatya ca mahājavaḥ
antarikṣe sthitaḥ śrīmān idaṃ vacanam abravīt', null, 5001152),
('ramayana-5-1-153', 153, 'Sundara Kanda, Sarga 1, Verse 153', 'प्रविष्टोऽस्मि हि ते वक्त्रं दाक्षायणि नमोऽस्तु ते।
गमिष्ये यत्र वैदेही सत्यं चास्तु वचस्तव॥', 'praviṣṭo ''smi hi te vaktraṃ dākṣāyaṇi namo ''stu te
gamiṣye yatra vaidehī satyaṃ cāstu vacas tava', null, 5001153),
('ramayana-5-1-154', 154, 'Sundara Kanda, Sarga 1, Verse 154', 'तं दृष्ट्वा वदनान्मुक्तं चन्द्रं राहुमुखादिव।
अब्रवीत्सुरसा देवी स्वेन रूपेण वानरम्॥', 'taṃ dṛṣṭvā vadanān muktaṃ candraṃ rāhumukhād iva
abravīt surasā devī svena rūpeṇa vānaram', null, 5001154),
('ramayana-5-1-155', 155, 'Sundara Kanda, Sarga 1, Verse 155', 'अर्थसिद्ध्यै हरिश्रेष्ठ गच्छ सौम्य यथासुखम्।
समानय च वैदेहीं राघवेण महात्मना॥', 'arthasiddhyai hariśreṣṭha gaccha saumya yathāsukham
samānaya ca vaidehīṃ rāghaveṇa mahātmanā', null, 5001155),
('ramayana-5-1-156', 156, 'Sundara Kanda, Sarga 1, Verse 156', 'तत्तृतीयं हनुमतो दृष्ट्वा कर्म सुदुष्करम्।
साधु साध्विति भूतानि प्रशशंसुस्तदा हरिम्॥', 'tat tṛtīyaṃ hanumato dṛṣṭvā karma suduṣkaram
sādhu sādhv iti bhūtāni praśaśaṃsus tadā harim', null, 5001156),
('ramayana-5-1-157', 157, 'Sundara Kanda, Sarga 1, Verse 157', 'स सागरमनाधृष्यमभ्येत्य वरुणालयम्।
जगामाकाशमाविश्य वेगेन गरुणोपमः॥', 'sa sāgaram anādhṛṣyam abhyetya varuṇālayam
jagāmākāśam āviśya vegena garuṇopamaḥ', null, 5001157),
('ramayana-5-1-158', 158, 'Sundara Kanda, Sarga 1, Verse 158', 'सेविते वारिधारिभिः पतगैश्च निषेविते।
चरिते कैशिकाचार्यैरैरावतनिषेविते॥', 'sevite vāridhāribhiḥ patagaiś ca niṣevite
carite kaiśikācāryair airāvataniṣevite', null, 5001158),
('ramayana-5-1-159', 159, 'Sundara Kanda, Sarga 1, Verse 159', 'सिंहकुञ्जरशार्दूलपतगोरगवाहनैः।
विमानैः संपतद्भिश्च विमलैः समलंकृते॥', 'siṃhakuñjaraśārdūlapatagoragavāhanaiḥ
vimānaiḥ saṃpatadbhiś ca vimalaiḥ samalaṃkṛte', null, 5001159),
('ramayana-5-1-160', 160, 'Sundara Kanda, Sarga 1, Verse 160', 'वज्राशनिसमाघातैः पावकैरुपशोभिते।
कृतपुण्यैर्महाभागैः स्वर्गजिद्भिरलंकृते॥', 'vajrāśanisamāghātaiḥ pāvakair upaśobhite
kṛtapuṇyair mahābhāgaiḥ svargajidbhir alaṃkṛte', null, 5001160),
('ramayana-5-1-161', 161, 'Sundara Kanda, Sarga 1, Verse 161', 'बहता हव्यमत्यन्तं सेविते चित्रभानुना।
ग्रहनक्षत्रचन्द्रार्कतारागणविभूषिते॥', 'bahatā havyam atyantaṃ sevite citrabhānunā
grahanakṣatracandrārkatārāgaṇavibhūṣite', null, 5001161),
('ramayana-5-1-162', 162, 'Sundara Kanda, Sarga 1, Verse 162', 'महर्षिगणगन्धर्वनागयक्षसमाकुले।
विविक्ते विमले विश्वे विश्वावसुनिषेविते॥', 'maharṣigaṇagandharvanāgayakṣasamākule
vivikte vimale viśve viśvāvasuniṣevite', null, 5001162),
('ramayana-5-1-163', 163, 'Sundara Kanda, Sarga 1, Verse 163', 'देवराजगजाक्रान्ते चन्द्रसूर्यपथे शिवे।
विताने जीवलोकस्य विततो ब्रह्मनिर्मिते॥', 'devarājagajākrānte candrasūryapathe śive
vitāne jīvalokasya vitato brahmanirmite', null, 5001163),
('ramayana-5-1-164', 164, 'Sundara Kanda, Sarga 1, Verse 164', 'बहुशः सेविते वीरैर्विद्याधरगणैर्वरैः।
कपिना कृष्यमाणानि महाभ्राणि चकाशिरे॥', 'bahuśaḥ sevite vīrair vidyādharagaṇair varaiḥ
kapinā kṛṣyamāṇāni mahābhrāṇi cakāśire', null, 5001164),
('ramayana-5-1-165', 165, 'Sundara Kanda, Sarga 1, Verse 165', 'प्रविशन्नभ्रजालानि निष्पतंश्च पुनः पुनः।
प्रावृषीन्दुरिवाभाति निष्पतन्प्रविशंस्तदा॥', 'praviśann abhrajālāni niṣpataṃś ca punaḥ punaḥ
prāvṛṣīndur ivābhāti niṣpatan praviśaṃs tadā', null, 5001165),
('ramayana-5-1-166', 166, 'Sundara Kanda, Sarga 1, Verse 166', 'प्लवमानं तु तं दृष्ट्वा सिंहिका नाम राक्षसी।
मनसा चिन्तयामास प्रवृद्धा कामरूपिणी॥', 'plavamānaṃ tu taṃ dṛṣṭvā siṃhikā nāma rākṣasī
manasā cintayām āsa pravṛddhā kāmarūpiṇī', null, 5001166),
('ramayana-5-1-167', 167, 'Sundara Kanda, Sarga 1, Verse 167', 'अद्य दीर्घस्य कालस्य भविष्याम्यहमाशिता।
इदं हि मे महत्सत्त्वं चिरस्य वशमागतम्॥', 'adya dīrghasya kālasya bhaviṣyāmy aham āśitā
idaṃ hi me mahat sattvaṃ cirasya vaśam āgatam', null, 5001167),
('ramayana-5-1-168', 168, 'Sundara Kanda, Sarga 1, Verse 168', 'इति संचिन्त्य मनसा छायामस्य समक्षिपत्।
छायायां संगृहीतायां चिन्तयामास वानरः॥', 'iti saṃcintya manasā chāyām asya samakṣipat
chāyāyāṃ saṃgṛhītāyāṃ cintayām āsa vānaraḥ', null, 5001168),
('ramayana-5-1-169', 169, 'Sundara Kanda, Sarga 1, Verse 169', 'समाक्षिप्तोऽस्मि सहसा पङ्गूकृतपराक्रमः।
प्रतिलोमेन वातेन महानौरिव सागरे॥', 'samākṣipto ''smi sahasā paṅgūkṛtaparākramaḥ
pratilomena vātena mahānaur iva sāgare', null, 5001169),
('ramayana-5-1-170', 170, 'Sundara Kanda, Sarga 1, Verse 170', 'तिर्यगूर्ध्वमधश्चैव वीक्षमाणस्ततः कपिः।
ददर्श स महासत्त्वमुत्थितं लवणाम्भसि॥', 'tiryag ūrdhvam adhaś caiva vīkṣamāṇas tataḥ kapiḥ
dadarśa sa mahāsattvam utthitaṃ lavaṇāmbhasi', null, 5001170),
('ramayana-5-1-171', 171, 'Sundara Kanda, Sarga 1, Verse 171', 'कपिराज्ञा यदाख्यातं सत्त्वमद्भुतदर्शनम्।
छायाग्राहि महावीर्यं तदिदं नात्र संशयः॥', 'kapirājñā yad ākhyātaṃ sattvam adbhutadarśanam
chāyāgrāhi mahāvīryaṃ tad idaṃ nātra saṃśayaḥ', null, 5001171),
('ramayana-5-1-172', 172, 'Sundara Kanda, Sarga 1, Verse 172', 'स तां बुद्ध्वार्थतत्त्वेन सिंहिकां मतिमान्कपिः।
व्यवर्धत महाकायः प्रावृषीव बलाहकः॥', 'sa tāṃ buddhvārthatattvena siṃhikāṃ matimān kapiḥ
vyavardhata mahākāyaḥ prāvṛṣīva balāhakaḥ', null, 5001172),
('ramayana-5-1-173', 173, 'Sundara Kanda, Sarga 1, Verse 173', 'तस्य सा कायमुद्वीक्ष्य वर्धमानं महाकपेः।
वक्त्रं प्रसारयामास पातालाम्बरसंनिभम्॥', 'tasya sā kāyam udvīkṣya vardhamānaṃ mahākapeḥ
vaktraṃ prasārayām āsa pātālāmbarasaṃnibham', null, 5001173),
('ramayana-5-1-174', 174, 'Sundara Kanda, Sarga 1, Verse 174', 'स ददर्श ततस्तस्या विकृतं सुमहन्मुखम्।
कायमात्रं च मेधावी मर्माणि च महाकपिः॥', 'sa dadarśa tatas tasyā vikṛtaṃ sumahan mukham
kāyamātraṃ ca medhāvī marmāṇi ca mahākapiḥ', null, 5001174),
('ramayana-5-1-175', 175, 'Sundara Kanda, Sarga 1, Verse 175', 'स तस्या विवृते वक्त्रे वज्रसंहननः कपिः।
संक्षिप्य मुहुरात्मानं निष्पपात महाबलः॥', 'sa tasyā vivṛte vaktre vajrasaṃhananaḥ kapiḥ
saṃkṣipya muhur ātmānaṃ niṣpapāta mahābalaḥ', null, 5001175),
('ramayana-5-1-176', 176, 'Sundara Kanda, Sarga 1, Verse 176', 'आस्ये तस्या निमज्जन्तं ददृशुः सिद्धचारणाः।
ग्रस्यमानं यथा चन्द्रं पूर्णं पर्वणि राहुणा॥', 'āsye tasyā nimajjantaṃ dadṛśuḥ siddhacāraṇāḥ
grasyamānaṃ yathā candraṃ pūrṇaṃ parvaṇi rāhuṇā', null, 5001176),
('ramayana-5-1-177', 177, 'Sundara Kanda, Sarga 1, Verse 177', 'ततस्तस्य नखैस्तीक्ष्णैर्मर्माण्युत्कृत्य वानरः।
उत्पपाताथ वेगेन मनःसंपातविक्रमः॥', 'tatas tasya nakhais tīkṣṇair marmāṇy utkṛtya vānaraḥ
utpapātātha vegena manaḥsaṃpātavikramaḥ', null, 5001177),
('ramayana-5-1-178', 178, 'Sundara Kanda, Sarga 1, Verse 178', 'तां हतां वानरेणाशु पतितां वीक्ष्य सिंहिकाम्।
भूतान्याकाशचारीणि तमूचुः प्लवगर्षभम्॥', 'tāṃ hatāṃ vānareṇāśu patitāṃ vīkṣya siṃhikām
bhūtāny ākāśacārīṇi tam ūcuḥ plavagarṣabham', null, 5001178),
('ramayana-5-1-179', 179, 'Sundara Kanda, Sarga 1, Verse 179', 'भीममद्य कृतं कर्म महत्सत्त्वं त्वया हतम्।
साधयार्थमभिप्रेतमरिष्टं प्लवतां वर॥', 'bhīmam adya kṛtaṃ karma mahat sattvaṃ tvayā hatam
sādhayārtham abhipretam ariṣṭaṃ plavatāṃ vara', null, 5001179),
('ramayana-5-1-180', 180, 'Sundara Kanda, Sarga 1, Verse 180', 'यस्य त्वेतानि चत्वारि वानरेन्द्र यथा तव।
धृतिर्दृष्टिर्मतिर्दाक्ष्यं स कर्मसु न सीदति॥', 'yasya tv etāni catvāri vānarendra yathā tava
dhṛtir dṛṣṭir matir dākṣyaṃ sa karmasu na sīdati', null, 5001180),
('ramayana-5-1-181', 181, 'Sundara Kanda, Sarga 1, Verse 181', 'स तैः संभावितः पूज्यः प्रतिपन्नप्रयोजनः।
जगामाकाशमाविश्य पन्नगाशनवत्कपिः॥', 'sa taiḥ saṃbhāvitaḥ pūjyaḥ pratipannaprayojanaḥ
jagāmākāśam āviśya pannagāśanavat kapiḥ', null, 5001181),
('ramayana-5-1-182', 182, 'Sundara Kanda, Sarga 1, Verse 182', 'प्राप्तभूयिष्ठ पारस्तु सर्वतः प्रतिलोकयन्।
योजनानां शतस्यान्ते वनराजिं ददर्श सः॥', 'prāptabhūyiṣṭha pāras tu sarvataḥ pratilokayan
yojanānāṃ śatasyānte vanarājiṃ dadarśa saḥ', null, 5001182),
('ramayana-5-1-183', 183, 'Sundara Kanda, Sarga 1, Verse 183', 'ददर्श च पतन्नेव विविधद्रुमभूषितम्।
द्वीपं शाखामृगश्रेष्ठो मलयोपवनानि च॥', 'dadarśa ca patann eva vividhadrumabhūṣitam
dvīpaṃ śākhāmṛgaśreṣṭho malayopavanāni ca', null, 5001183),
('ramayana-5-1-184', 184, 'Sundara Kanda, Sarga 1, Verse 184', 'सागरं सागरानूपान्सागरानूपजान्द्रुमान्।
सागरस्य च पत्नीनां मुखान्यपि विलोकयन्॥', 'sāgaraṃ sāgarānūpān sāgarānūpajān drumān
sāgarasya ca patnīnāṃ mukhāny api vilokayan', null, 5001184),
('ramayana-5-1-185', 185, 'Sundara Kanda, Sarga 1, Verse 185', 'स महामेघसंकाशं समीक्ष्यात्मानमात्मना।
निरुन्धन्तमिवाकाशं चकार मतिमान्मतिम्॥', 'sa mahāmeghasaṃkāśaṃ samīkṣyātmānam ātmanā
nirundhantam ivākāśaṃ cakāra matimān matim', null, 5001185),
('ramayana-5-1-186', 186, 'Sundara Kanda, Sarga 1, Verse 186', 'कायवृद्धिं प्रवेगं च मम दृष्ट्वैव राक्षसाः।
मयि कौतूहलं कुर्युरिति मेने महाकपिः॥', 'kāyavṛddhiṃ pravegaṃ ca mama dṛṣṭvaiva rākṣasāḥ
mayi kautūhalaṃ kuryur iti mene mahākapiḥ', null, 5001186),
('ramayana-5-1-187', 187, 'Sundara Kanda, Sarga 1, Verse 187', 'ततः शरीरं संक्षिप्य तन्महीधरसंनिभम्।
पुनः प्रकृतिमापेदे वीतमोह इवात्मवान्॥', 'tataḥ śarīraṃ saṃkṣipya tan mahīdharasaṃnibham
punaḥ prakṛtim āpede vītamoha ivātmavān', null, 5001187),
('ramayana-5-1-188', 188, 'Sundara Kanda, Sarga 1, Verse 188', 'स चारुनानाविधरूपधारी परं समासाद्य समुद्रतीरम्।
परैरशक्यप्रतिपन्नरूपः समीक्षितात्मा समवेक्षितार्थः॥', 'sa cārunānāvidharūpadhārī paraṃ samāsādya samudratīram
parair aśakyapratipannarūpaḥ samīkṣitātmā samavekṣitārthaḥ', null, 5001188),
('ramayana-5-1-189', 189, 'Sundara Kanda, Sarga 1, Verse 189', 'ततः स लम्बस्य गिरेः समृद्धे विचित्रकूटे निपपात कूटे।
सकेतकोद्दालकनालिकेरे महाद्रिकूटप्रतिमो महात्मा॥', 'tataḥ sa lambasya gireḥ samṛddhe vicitrakūṭe nipapāta kūṭe
saketakoddālakanālikere mahādrikūṭapratimo mahātmā', null, 5001189),
('ramayana-5-1-190', 190, 'Sundara Kanda, Sarga 1, Verse 190', 'स सागरं दानवपन्नगायुतं बलेन विक्रम्य महोर्मिमालिनम्।
निपत्य तीरे च महोदधेस्तदा ददर्श लङ्काममरावतीमिव॥', 'sa sāgaraṃ dānavapannagāyutaṃ balena vikramya mahormimālinam
nipatya tīre ca mahodadhes tadā dadarśa laṅkām amarāvatīm iva', null, 5001190)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 2 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-2-1', 1, 'Sundara Kanda, Sarga 2, Verse 1', 'स सागरमनाधृष्यमतिक्रम्य महाबलः।
त्रिकूटशिखरे लङ्कां स्थितां स्वस्थो ददर्श ह॥', 'sa sāgaram anādhṛṣyam atikramya mahābalaḥ
trikūṭaśikhare laṅkāṃ sthitāṃ svastho dadarśa ha', null, 5002001),
('ramayana-5-2-2', 2, 'Sundara Kanda, Sarga 2, Verse 2', 'ततः पादपमुक्तेन पुष्पवर्षेण वीर्यवान्।
अभिवृष्टः स्थितस्तत्र बभौ पुष्पमयो यथा॥', 'tataḥ pādapamuktena puṣpavarṣeṇa vīryavān
abhivṛṣṭaḥ sthitas tatra babhau puṣpamayo yathā', null, 5002002),
('ramayana-5-2-3', 3, 'Sundara Kanda, Sarga 2, Verse 3', 'योजनानां शतं श्रीमांस्तीर्त्वाप्युत्तमविक्रमः।
अनिश्वसन्कपिस्तत्र न ग्लानिमधिगच्छति॥', 'yojanānāṃ śataṃ śrīmāṃs tīrtvāpy uttamavikramaḥ
aniśvasan kapis tatra na glānim adhigacchati', null, 5002003),
('ramayana-5-2-4', 4, 'Sundara Kanda, Sarga 2, Verse 4', 'शतान्यहं योजनानां क्रमेयं सुबहून्यपि।
किं पुनः सागरस्यान्तं संख्यातं शतयोजनम्॥', 'śatāny ahaṃ yojanānāṃ krameyaṃ subahūny api
kiṃ punaḥ sāgarasyāntaṃ saṃkhyātaṃ śatayojanam', null, 5002004),
('ramayana-5-2-5', 5, 'Sundara Kanda, Sarga 2, Verse 5', 'स तु वीर्यवतां श्रेष्ठः प्लवतामपि चोत्तमः।
जगाम वेगवांल्लङ्कां लङ्घयित्वा महोदधिम्॥', 'sa tu vīryavatāṃ śreṣṭhaḥ plavatām api cottamaḥ
jagāma vegavāṃl laṅkāṃ laṅghayitvā mahodadhim', null, 5002005),
('ramayana-5-2-6', 6, 'Sundara Kanda, Sarga 2, Verse 6', 'शाद्वलानि च नीलानि गन्धवन्ति वनानि च।
गण्डवन्ति च मध्येन जगाम नगवन्ति च॥', 'śādvalāni ca nīlāni gandhavanti vanāni ca
gaṇḍavanti ca madhyena jagāma nagavanti ca', null, 5002006),
('ramayana-5-2-7', 7, 'Sundara Kanda, Sarga 2, Verse 7', 'शैलांश्च तरुसंछन्नान्वनराजीश्च पुष्पिताः।
अभिचक्राम तेजस्वी हनुमान्प्लवगर्षभः॥', 'śailāṃś ca tarusaṃchannān vanarājīś ca puṣpitāḥ
abhicakrāma tejasvī hanumān plavagarṣabhaḥ', null, 5002007),
('ramayana-5-2-8', 8, 'Sundara Kanda, Sarga 2, Verse 8', 'स तस्मिन्नचले तिष्ठन्वनान्युपवनानि च।
स नगाग्रे च तां लङ्कां ददर्श पवनात्मजः॥', 'sa tasminn acale tiṣṭhan vanāny upavanāni ca
sa nagāgre ca tāṃ laṅkāṃ dadarśa pavanātmajaḥ', null, 5002008),
('ramayana-5-2-9', 9, 'Sundara Kanda, Sarga 2, Verse 9', 'सरलान्कर्णिकारांश्च खर्जूरांश्च सुपुष्पितान्।
प्रियालान्मुचुलिन्दांश्च कुटजान्केतकानपि॥', 'saralān karṇikārāṃś ca kharjūrāṃś ca supuṣpitān
priyālān muculindāṃś ca kuṭajān ketakān api', null, 5002009),
('ramayana-5-2-10', 10, 'Sundara Kanda, Sarga 2, Verse 10', 'प्रियङ्गून्गन्धपूर्णांश्च नीपान्सप्तच्छदांस्तथा।
असनान्कोविदारांश्च करवीरांश्च पुष्पितान्॥', 'priyaṅgūn gandhapūrṇāṃś ca nīpān saptacchadāṃs tathā
asanān kovidārāṃś ca karavīrāṃś ca puṣpitān', null, 5002010),
('ramayana-5-2-11', 11, 'Sundara Kanda, Sarga 2, Verse 11', 'पुष्पभारनिबद्धांश्च तथा मुकुलितानपि।
पादपान्विहगाकीर्णान्पवनाधूतमस्तकान्॥', 'puṣpabhāranibaddhāṃś ca tathā mukulitān api
pādapān vihagākīrṇān pavanādhūtamastakān', null, 5002011),
('ramayana-5-2-12', 12, 'Sundara Kanda, Sarga 2, Verse 12', 'हंसकारण्डवाकीर्णा वापीः पद्मोत्पलायुताः।
आक्रीडान्विविधान्रम्यान्विविधांश्च जलाशयान्॥', 'haṃsakāraṇḍavākīrṇā vāpīḥ padmotpalāyutāḥ
ākrīḍān vividhān ramyān vividhāṃś ca jalāśayān', null, 5002012),
('ramayana-5-2-13', 13, 'Sundara Kanda, Sarga 2, Verse 13', 'संततान्विविधैर्वृक्षैः सर्वर्तुफलपुष्पितैः।
उद्यानानि च रम्याणि ददर्श कपिकुञ्जरः॥', 'saṃtatān vividhair vṛkṣaiḥ sarvartuphalapuṣpitaiḥ
udyānāni ca ramyāṇi dadarśa kapikuñjaraḥ', null, 5002013),
('ramayana-5-2-14', 14, 'Sundara Kanda, Sarga 2, Verse 14', 'समासाद्य च लक्ष्मीवांल्लङ्कां रावणपालिताम्।
परिखाभिः सपद्माभिः सोत्पलाभिरलंकृताम्॥', 'samāsādya ca lakṣmīvāṃl laṅkāṃ rāvaṇapālitām
parikhābhiḥ sapadmābhiḥ sotpalābhir alaṃkṛtām', null, 5002014),
('ramayana-5-2-15', 15, 'Sundara Kanda, Sarga 2, Verse 15', 'सीतापहरणार्थेन रावणेन सुरक्षिताम्।
समन्ताद्विचरद्भिश्च राक्षसैरुग्रधन्विभिः॥', 'sītāpaharaṇārthena rāvaṇena surakṣitām
samantād vicaradbhiś ca rākṣasair ugradhanvibhiḥ', null, 5002015),
('ramayana-5-2-16', 16, 'Sundara Kanda, Sarga 2, Verse 16', 'काञ्चनेनावृतां रम्यां प्राकारेण महापुरीम्।
अट्टालकशताकीर्णां पताकाध्वजमालिनीम्॥', 'kāñcanenāvṛtāṃ ramyāṃ prākāreṇa mahāpurīm
aṭṭālakaśatākīrṇāṃ patākādhvajamālinīm', null, 5002016),
('ramayana-5-2-17', 17, 'Sundara Kanda, Sarga 2, Verse 17', 'तोरणैः काञ्चनैर्दिव्यैर्लतापङ्क्तिविचित्रितैः।
ददर्श हनुमांल्लङ्कां दिवि देवपुरीमिव॥', 'toraṇaiḥ kāñcanair divyair latāpaṅktivicitritaiḥ
dadarśa hanumāṃl laṅkāṃ divi devapurīm iva', null, 5002017),
('ramayana-5-2-18', 18, 'Sundara Kanda, Sarga 2, Verse 18', 'गिरिमूर्ध्नि स्थितां लङ्कां पाण्डुरैर्भवनैः शुभैः।
ददर्श स कपिः श्रीमान्पुरमाकाशगं यथा॥', 'girimūrdhni sthitāṃ laṅkāṃ pāṇḍurair bhavanaiḥ śubhaiḥ
dadarśa sa kapiḥ śrīmān puram ākāśagaṃ yathā', null, 5002018),
('ramayana-5-2-19', 19, 'Sundara Kanda, Sarga 2, Verse 19', 'पालितां राक्षसेन्द्रेण निर्मितां विश्वकर्मणा।
प्लवमानामिवाकाशे ददर्श हनुमान्पुरीम्॥', 'pālitāṃ rākṣasendreṇa nirmitāṃ viśvakarmaṇā
plavamānām ivākāśe dadarśa hanumān purīm', null, 5002019),
('ramayana-5-2-20', 20, 'Sundara Kanda, Sarga 2, Verse 20', 'संपूर्णां राक्षसैर्घोरैर्नागैर्भोगवतीमिव।
अचिन्त्यां सुकृतां स्पष्टां कुबेराध्युषितां पुरा॥', 'saṃpūrṇāṃ rākṣasair ghorair nāgair bhogavatīm iva
acintyāṃ sukṛtāṃ spaṣṭāṃ kuberādhyuṣitāṃ purā', null, 5002020),
('ramayana-5-2-21', 21, 'Sundara Kanda, Sarga 2, Verse 21', 'दंष्ट्रिभिर्बहुभिः शूरैः शूलपट्टिशपाणिभिः।
रक्षितां राक्षसैर्घोरैर्गुहामाशीविषैरपि॥', 'daṃṣṭribhir bahubhiḥ śūraiḥ śūlapaṭṭiśapāṇibhiḥ
rakṣitāṃ rākṣasair ghorair guhām āśīviṣair api', null, 5002021),
('ramayana-5-2-22', 22, 'Sundara Kanda, Sarga 2, Verse 22', 'वप्रप्राकारजघनां विपुलाम्बुनवाम्बराम्।
शतघ्नीशूलकेशान्तामट्टालकवतंसकाम्॥', 'vapraprākārajaghanāṃ vipulāmbunavāmbarām
śataghnīśūlakeśāntām aṭṭālakavataṃsakām', null, 5002022),
('ramayana-5-2-23', 23, 'Sundara Kanda, Sarga 2, Verse 23', 'द्वारमुत्तरमासाद्य चिन्तयामास वानरः।
कैलासशिखरप्रख्यमालिखन्तमिवाम्बरम्।
ध्रियमाणमिवाकाशमुच्छ्रितैर्भवनोत्तमैः॥', 'dvāram uttaram āsādya cintayām āsa vānaraḥ
kailāsaśikharaprakhyam ālikhantam ivāmbaram
dhriyamāṇam ivākāśam ucchritair bhavanottamaiḥ', null, 5002023),
('ramayana-5-2-24', 24, 'Sundara Kanda, Sarga 2, Verse 24', 'तस्याश्च महतीं गुप्तिं सागरं च निरीक्ष्य सः।
रावणं च रिपुं घोरं चिन्तयामास वानरः॥', 'tasyāś ca mahatīṃ guptiṃ sāgaraṃ ca nirīkṣya saḥ
rāvaṇaṃ ca ripuṃ ghoraṃ cintayām āsa vānaraḥ', null, 5002024),
('ramayana-5-2-25', 25, 'Sundara Kanda, Sarga 2, Verse 25', 'आगत्यापीह हरयो भविष्यन्ति निरर्थकाः।
न हि युद्धेन वै लङ्का शक्या जेतुं सुरैरपि॥', 'āgatyāpīha harayo bhaviṣyanti nirarthakāḥ
na hi yuddhena vai laṅkā śakyā jetuṃ surair api', null, 5002025),
('ramayana-5-2-26', 26, 'Sundara Kanda, Sarga 2, Verse 26', 'इमां तु विषमां दुर्गां लङ्कां रावणपालिताम्।
प्राप्यापि स महाबाहुः किं करिष्यति राघवः॥', 'imāṃ tu viṣamāṃ durgāṃ laṅkāṃ rāvaṇapālitām
prāpyāpi sa mahābāhuḥ kiṃ kariṣyati rāghavaḥ', null, 5002026),
('ramayana-5-2-27', 27, 'Sundara Kanda, Sarga 2, Verse 27', 'अवकाशो न सान्त्वस्य राक्षसेष्वभिगम्यते।
न दानस्य न भेदस्य नैव युद्धस्य दृश्यते॥', 'avakāśo na sāntvasya rākṣaseṣv abhigamyate
na dānasya na bhedasya naiva yuddhasya dṛśyate', null, 5002027),
('ramayana-5-2-28', 28, 'Sundara Kanda, Sarga 2, Verse 28', 'चतुर्णामेव हि गतिर्वानराणां महात्मनाम्।
वालिपुत्रस्य नीलस्य मम राज्ञश्च धीमतः॥', 'caturṇām eva hi gatir vānarāṇāṃ mahātmanām
vāliputrasya nīlasya mama rājñaś ca dhīmataḥ', null, 5002028),
('ramayana-5-2-29', 29, 'Sundara Kanda, Sarga 2, Verse 29', 'यावज्जानामि वैदेहीं यदि जीवति वा न वा।
तत्रैव चिन्तयिष्यामि दृष्ट्वा तां जनकात्मजाम्॥', 'yāvaj jānāmi vaidehīṃ yadi jīvati vā na vā
tatraiva cintayiṣyāmi dṛṣṭvā tāṃ janakātmajām', null, 5002029),
('ramayana-5-2-30', 30, 'Sundara Kanda, Sarga 2, Verse 30', 'ततः स चिन्तयामास मुहूर्तं कपिकुञ्जरः।
गिरिशृङ्गे स्थितस्तस्मिन्रामस्याभ्युदये रतः॥', 'tataḥ sa cintayām āsa muhūrtaṃ kapikuñjaraḥ
giriśṛṅge sthitas tasmin rāmasyābhyudaye rataḥ', null, 5002030),
('ramayana-5-2-31', 31, 'Sundara Kanda, Sarga 2, Verse 31', 'अनेन रूपेण मया न शक्या रक्षसां पुरी।
प्रवेष्टुं राक्षसैर्गुप्ता क्रूरैर्बलसमन्वितैः॥', 'anena rūpeṇa mayā na śakyā rakṣasāṃ purī
praveṣṭuṃ rākṣasair guptā krūrair balasamanvitaiḥ', null, 5002031),
('ramayana-5-2-32', 32, 'Sundara Kanda, Sarga 2, Verse 32', 'उग्रौजसो महावीर्यो बलवन्तश्च राक्षसाः।
वञ्चनीया मया सर्वे जानकीं परिमार्गिता॥', 'ugraujaso mahāvīryo balavantaś ca rākṣasāḥ
vañcanīyā mayā sarve jānakīṃ parimārgitā', null, 5002032),
('ramayana-5-2-33', 33, 'Sundara Kanda, Sarga 2, Verse 33', 'लक्ष्यालक्ष्येण रूपेण रात्रौ लङ्का पुरी मया।
प्रवेष्टुं प्राप्तकालं मे कृत्यं साधयितुं महत्॥', 'lakṣyālakṣyeṇa rūpeṇa rātrau laṅkā purī mayā
praveṣṭuṃ prāptakālaṃ me kṛtyaṃ sādhayituṃ mahat', null, 5002033),
('ramayana-5-2-34', 34, 'Sundara Kanda, Sarga 2, Verse 34', 'तां पुरीं तादृशीं दृष्ट्वा दुराधर्षां सुरासुरैः।
हनूमांश्चिन्तयामास विनिःश्वस्य मुहुर्मुहुः॥', 'tāṃ purīṃ tādṛśīṃ dṛṣṭvā durādharṣāṃ surāsuraiḥ
hanūmāṃś cintayām āsa viniḥśvasya muhur muhuḥ', null, 5002034),
('ramayana-5-2-35', 35, 'Sundara Kanda, Sarga 2, Verse 35', 'केनोपायेन पश्येयं मैथिलीं जनकात्मजाम्।
अदृष्टो राक्षसेन्द्रेण रावणेन दुरात्मना॥', 'kenopāyena paśyeyaṃ maithilīṃ janakātmajām
adṛṣṭo rākṣasendreṇa rāvaṇena durātmanā', null, 5002035),
('ramayana-5-2-36', 36, 'Sundara Kanda, Sarga 2, Verse 36', 'न विनश्येत्कथं कार्यं रामस्य विदितात्मनः।
एकामेकश्च पश्येयं रहिते जनकात्मजाम्॥', 'na vinaśyet kathaṃ kāryaṃ rāmasya viditātmanaḥ
ekām ekaś ca paśyeyaṃ rahite janakātmajām', null, 5002036),
('ramayana-5-2-37', 37, 'Sundara Kanda, Sarga 2, Verse 37', 'भूताश्चार्थो विपद्यन्ते देशकालविरोधिताः।
विक्लवं दूतमासाद्य तमः सूर्योदये यथा॥', 'bhūtāś cārtho vipadyante deśakālavirodhitāḥ
viklavaṃ dūtam āsādya tamaḥ sūryodaye yathā', null, 5002037),
('ramayana-5-2-38', 38, 'Sundara Kanda, Sarga 2, Verse 38', 'अर्थानर्थान्तरे बुद्धिर्निश्चितापि न शोभते।
घातयन्ति हि कार्याणि दूताः पण्डितमानिनः॥', 'arthānarthāntare buddhir niścitāpi na śobhate
ghātayanti hi kāryāṇi dūtāḥ paṇḍitamāninaḥ', null, 5002038),
('ramayana-5-2-39', 39, 'Sundara Kanda, Sarga 2, Verse 39', 'न विनश्येत्कथं कार्यं वैक्लव्यं न कथं भवेत्।
लङ्घनं च समुद्रस्य कथं नु न वृथा भवेत्॥', 'na vinaśyet kathaṃ kāryaṃ vaiklavyaṃ na kathaṃ bhavet
laṅghanaṃ ca samudrasya kathaṃ nu na vṛthā bhavet', null, 5002039),
('ramayana-5-2-40', 40, 'Sundara Kanda, Sarga 2, Verse 40', 'मयि दृष्टे तु रक्षोभी रामस्य विदितात्मनः।
भवेद्व्यर्थमिदं कार्यं रावणानर्थमिच्छतः॥', 'mayi dṛṣṭe tu rakṣobhī rāmasya viditātmanaḥ
bhaved vyartham idaṃ kāryaṃ rāvaṇānartham icchataḥ', null, 5002040),
('ramayana-5-2-41', 41, 'Sundara Kanda, Sarga 2, Verse 41', 'न हि शक्यं क्व चित्स्थातुमविज्ञातेन राक्षसैः।
अपि राक्षसरूपेण किमुतान्येन केन चित्॥', 'na hi śakyaṃ kva cit sthātum avijñātena rākṣasaiḥ
api rākṣasarūpeṇa kim utānyena kena cit', null, 5002041),
('ramayana-5-2-42', 42, 'Sundara Kanda, Sarga 2, Verse 42', 'वायुरप्यत्र नाज्ञातश्चरेदिति मतिर्मम।
न ह्यस्त्यविदितं किं चिद्राक्षसानां बलीयसाम्॥', 'vāyur apy atra nājñātaś cared iti matir mama
na hy asty aviditaṃ kiṃ cid rākṣasānāṃ balīyasām', null, 5002042),
('ramayana-5-2-43', 43, 'Sundara Kanda, Sarga 2, Verse 43', 'इहाहं यदि तिष्ठामि स्वेन रूपेण संवृतः।
विनाशमुपयास्यामि भर्तुरर्थश्च हीयते॥', 'ihāhaṃ yadi tiṣṭhāmi svena rūpeṇa saṃvṛtaḥ
vināśam upayāsyāmi bhartur arthaś ca hīyate', null, 5002043),
('ramayana-5-2-44', 44, 'Sundara Kanda, Sarga 2, Verse 44', 'तदहं स्वेन रूपेण रजन्यां ह्रस्वतां गतः।
लङ्कामभिपतिष्यामि राघवस्यार्थसिद्धये॥', 'tad ahaṃ svena rūpeṇa rajanyāṃ hrasvatāṃ gataḥ
laṅkām abhipatiṣyāmi rāghavasyārthasiddhaye', null, 5002044),
('ramayana-5-2-45', 45, 'Sundara Kanda, Sarga 2, Verse 45', 'रावणस्य पुरीं रात्रौ प्रविश्य सुदुरासदाम्।
विचिन्वन्भवनं सर्वं द्रक्ष्यामि जनकात्मजाम्॥', 'rāvaṇasya purīṃ rātrau praviśya sudurāsadām
vicinvan bhavanaṃ sarvaṃ drakṣyāmi janakātmajām', null, 5002045),
('ramayana-5-2-46', 46, 'Sundara Kanda, Sarga 2, Verse 46', 'इति संचिन्त्य हनुमान्सूर्यस्यास्तमयं कपिः।
आचकाङ्क्षे तदा वीरा वैदेह्या दर्शनोत्सुकः।
पृषदंशकमात्रः सन्बभूवाद्भुतदर्शनः॥', 'iti saṃcintya hanumān sūryasyāstamayaṃ kapiḥ
ācakāṅkṣe tadā vīrā vaidehyā darśanotsukaḥ
pṛṣadaṃśakamātraḥ san babhūvādbhutadarśanaḥ', null, 5002046),
('ramayana-5-2-47', 47, 'Sundara Kanda, Sarga 2, Verse 47', 'प्रदोषकाले हनुमांस्तूर्णमुत्पत्य वीर्यवान्।
प्रविवेश पुरीं रम्यां सुविभक्तमहापथम्॥', 'pradoṣakāle hanumāṃs tūrṇam utpatya vīryavān
praviveśa purīṃ ramyāṃ suvibhaktamahāpatham', null, 5002047),
('ramayana-5-2-48', 48, 'Sundara Kanda, Sarga 2, Verse 48', 'प्रासादमालाविततां स्तम्भैः काञ्चनराजतैः।
शातकुम्भमयैर्जालैर्गन्धर्वनगरोपमाम्॥', 'prāsādamālāvitatāṃ stambhaiḥ kāñcanarājataiḥ
śātakumbhamayair jālair gandharvanagaropamām', null, 5002048),
('ramayana-5-2-49', 49, 'Sundara Kanda, Sarga 2, Verse 49', 'सप्तभौमाष्टभौमैश्च स ददर्श महापुरीम्।
तलैः स्फाटिकसंपूर्णैः कार्तस्वरविभूषितैः॥', 'saptabhaumāṣṭabhaumaiś ca sa dadarśa mahāpurīm
talaiḥ sphāṭikasaṃpūrṇaiḥ kārtasvaravibhūṣitaiḥ', null, 5002049),
('ramayana-5-2-50', 50, 'Sundara Kanda, Sarga 2, Verse 50', 'वैदूर्यमणिचित्रैश्च मुक्ताजालविभूषितैः।
तलैः शुशुभिरे तानि भवनान्यत्र रक्षसाम्॥', 'vaidūryamaṇicitraiś ca muktājālavibhūṣitaiḥ
talaiḥ śuśubhire tāni bhavanāny atra rakṣasām', null, 5002050),
('ramayana-5-2-51', 51, 'Sundara Kanda, Sarga 2, Verse 51', 'काञ्चनानि विचित्राणि तोरणानि च रक्षसाम्।
लङ्कामुद्द्योतयामासुः सर्वतः समलंकृताम्॥', 'kāñcanāni vicitrāṇi toraṇāni ca rakṣasām
laṅkām uddyotayām āsuḥ sarvataḥ samalaṃkṛtām', null, 5002051),
('ramayana-5-2-52', 52, 'Sundara Kanda, Sarga 2, Verse 52', 'अचिन्त्यामद्भुताकारां दृष्ट्वा लङ्कां महाकपिः।
आसीद्विषण्णो हृष्टश्च वैदेह्या दर्शनोत्सुकः॥', 'acintyām adbhutākārāṃ dṛṣṭvā laṅkāṃ mahākapiḥ
āsīd viṣaṇṇo hṛṣṭaś ca vaidehyā darśanotsukaḥ', null, 5002052),
('ramayana-5-2-53', 53, 'Sundara Kanda, Sarga 2, Verse 53', 'स पाण्डुरोद्विद्धविमानमालिनीं महार्हजाम्बूनदजालतोरणाम्।
यशस्विनां रावणबाहुपालितां क्षपाचरैर्भीमबलैः समावृताम्॥', 'sa pāṇḍurodviddhavimānamālinīṃ mahārhajāmbūnadajālatoraṇām
yaśasvināṃ rāvaṇabāhupālitāṃ kṣapācarair bhīmabalaiḥ samāvṛtām', null, 5002053),
('ramayana-5-2-54', 54, 'Sundara Kanda, Sarga 2, Verse 54', 'चन्द्रोऽपि साचिव्यमिवास्य कुर्वंस्तारागणैर्मध्यगतो विराजन्।
ज्योत्स्नावितानेन वितत्य लोकमुत्तिष्ठते नैकसहस्ररश्मिः॥', 'candro ''pi sācivyam ivāsya kurvaṃs tārāgaṇair madhyagato virājan
jyotsnāvitānena vitatya lokam uttiṣṭhate naikasahasraraśmiḥ', null, 5002054),
('ramayana-5-2-55', 55, 'Sundara Kanda, Sarga 2, Verse 55', 'शङ्खप्रभं क्षीरमृणालवर्णमुद्गच्छमानं व्यवभासमानम्।
ददर्श चन्द्रं स कपिप्रवीरः पोप्लूयमानं सरसीव हंसं॥', 'śaṅkhaprabhaṃ kṣīramṛṇālavarṇam udgacchamānaṃ vyavabhāsamānam
dadarśa candraṃ sa kapipravīraḥ poplūyamānaṃ sarasīva haṃsaṃ', null, 5002055)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 3 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-3-1', 1, 'Sundara Kanda, Sarga 3, Verse 1', 'स लम्बशिखरे लम्बे लम्बतोयदसंनिभे।
सत्त्वमास्थाय मेधावी हनुमान्मारुतात्मजः॥', 'sa lambaśikhare lambe lambatoyadasaṃnibhe
sattvam āsthāya medhāvī hanumān mārutātmajaḥ', null, 5003001),
('ramayana-5-3-2', 2, 'Sundara Kanda, Sarga 3, Verse 2', 'निशि लङ्कां महासत्त्वो विवेश कपिकुञ्जरः।
रम्यकाननतोयाढ्यां पुरीं रावणपालिताम्॥', 'niśi laṅkāṃ mahāsattvo viveśa kapikuñjaraḥ
ramyakānanatoyāḍhyāṃ purīṃ rāvaṇapālitām', null, 5003002),
('ramayana-5-3-3', 3, 'Sundara Kanda, Sarga 3, Verse 3', 'शारदाम्बुधरप्रख्यैर्भवनैरुपशोभिताम्।
सागरोपमनिर्घोषां सागरानिलसेविताम्॥', 'śāradāmbudharaprakhyair bhavanair upaśobhitām
sāgaropamanirghoṣāṃ sāgarānilasevitām', null, 5003003),
('ramayana-5-3-4', 4, 'Sundara Kanda, Sarga 3, Verse 4', 'सुपुष्टबलसंगुप्तां यथैव विटपावतीम्।
चारुतोरणनिर्यूहां पाण्डुरद्वारतोरणाम्॥', 'supuṣṭabalasaṃguptāṃ yathaiva viṭapāvatīm
cārutoraṇaniryūhāṃ pāṇḍuradvāratoraṇām', null, 5003004),
('ramayana-5-3-5', 5, 'Sundara Kanda, Sarga 3, Verse 5', 'भुजगाचरितां गुप्तां शुभां भोगवतीमिव।
तां सविद्युद्घनाकीर्णां ज्योतिर्मार्गनिषेविताम्॥', 'bhujagācaritāṃ guptāṃ śubhāṃ bhogavatīm iva
tāṃ savidyudghanākīrṇāṃ jyotirmārganiṣevitām', null, 5003005),
('ramayana-5-3-6', 6, 'Sundara Kanda, Sarga 3, Verse 6', 'चण्डमारुतनिर्ह्रादां यथेन्द्रस्यामरावतीम्।
शातकुम्भेन महता प्राकारेणाभिसंवृताम्॥', 'caṇḍamārutanirhrādāṃ yathendrasyāmarāvatīm
śātakumbhena mahatā prākāreṇābhisaṃvṛtām', null, 5003006),
('ramayana-5-3-7', 7, 'Sundara Kanda, Sarga 3, Verse 7', 'किङ्किणीजालघोषाभिः पताकाभिरलंकृताम्।
आसाद्य सहसा हृष्टः प्राकारमभिपेदिवान्॥', 'kiṅkiṇījālaghoṣābhiḥ patākābhir alaṃkṛtām
āsādya sahasā hṛṣṭaḥ prākāram abhipedivān', null, 5003007),
('ramayana-5-3-8', 8, 'Sundara Kanda, Sarga 3, Verse 8', 'विस्मयाविष्टहृदयः पुरीमालोक्य सर्वतः।
जाम्बूनदमयैर्द्वारैर्वैदूर्यकृतवेदिकैः॥', 'vismayāviṣṭahṛdayaḥ purīm ālokya sarvataḥ
jāmbūnadamayair dvārair vaidūryakṛtavedikaiḥ', null, 5003008),
('ramayana-5-3-9', 9, 'Sundara Kanda, Sarga 3, Verse 9', 'मणिस्फटिक मुक्ताभिर्मणिकुट्टिमभूषितैः।
तप्तहाटकनिर्यूहै राजतामलपाण्डुरैः॥', 'maṇisphaṭika muktābhir maṇikuṭṭimabhūṣitaiḥ
taptahāṭakaniryūhai rājatāmalapāṇḍuraiḥ', null, 5003009),
('ramayana-5-3-10', 10, 'Sundara Kanda, Sarga 3, Verse 10', 'वैदूर्यतलसोपानैः स्फाटिकान्तरपांसुभिः।
चारुसंजवनोपेतैः खमिवोत्पतितैः शुभैः॥', 'vaidūryatalasopānaiḥ sphāṭikāntarapāṃsubhiḥ
cārusaṃjavanopetaiḥ kham ivotpatitaiḥ śubhaiḥ', null, 5003010),
('ramayana-5-3-11', 11, 'Sundara Kanda, Sarga 3, Verse 11', 'क्रौञ्चबर्हिणसंघुष्टे राजहंसनिषेवितैः।
तूर्याभरणनिर्घोषैः सर्वतः प्रतिनादिताम्॥', 'krauñcabarhiṇasaṃghuṣṭe rājahaṃsaniṣevitaiḥ
tūryābharaṇanirghoṣaiḥ sarvataḥ pratināditām', null, 5003011),
('ramayana-5-3-12', 12, 'Sundara Kanda, Sarga 3, Verse 12', 'वस्वोकसाराप्रतिमां समीक्ष्य नगरीं ततः।
खमिवोत्पतितां लङ्कां जहर्ष हनुमान्कपिः॥', 'vasvokasārāpratimāṃ samīkṣya nagarīṃ tataḥ
kham ivotpatitāṃ laṅkāṃ jaharṣa hanumān kapiḥ', null, 5003012),
('ramayana-5-3-13', 13, 'Sundara Kanda, Sarga 3, Verse 13', 'तां समीक्ष्य पुरीं लङ्कां राक्षसाधिपतेः शुभाम्।
अनुत्तमामृद्धियुतां चिन्तयामास वीर्यवान्॥', 'tāṃ samīkṣya purīṃ laṅkāṃ rākṣasādhipateḥ śubhām
anuttamām ṛddhiyutāṃ cintayām āsa vīryavān', null, 5003013),
('ramayana-5-3-14', 14, 'Sundara Kanda, Sarga 3, Verse 14', 'नेयमन्येन नगरी शक्या धर्षयितुं बलात्।
रक्षिता रावणबलैरुद्यतायुधधारिभिः॥', 'neyam anyena nagarī śakyā dharṣayituṃ balāt
rakṣitā rāvaṇabalair udyatāyudhadhāribhiḥ', null, 5003014),
('ramayana-5-3-15', 15, 'Sundara Kanda, Sarga 3, Verse 15', 'कुमुदाङ्गदयोर्वापि सुषेणस्य महाकपेः।
प्रसिद्धेयं भवेद्भूमिर्मैन्दद्विविदयोरपि॥', 'kumudāṅgadayor vāpi suṣeṇasya mahākapeḥ
prasiddheyaṃ bhaved bhūmir maindadvividayor api', null, 5003015),
('ramayana-5-3-16', 16, 'Sundara Kanda, Sarga 3, Verse 16', 'विवस्वतस्तनूजस्य हरेश्च कुशपर्वणः।
ऋक्षस्य केतुमालस्य मम चैव गतिर्भवेत्॥', 'vivasvatas tanūjasya hareś ca kuśaparvaṇaḥ
ṛkṣasya ketumālasya mama caiva gatir bhavet', null, 5003016),
('ramayana-5-3-17', 17, 'Sundara Kanda, Sarga 3, Verse 17', 'समीक्ष्य तु महाबाहो राघवस्य पराक्रमम्।
लक्ष्मणस्य च विक्रान्तमभवत्प्रीतिमान्कपिः॥', 'samīkṣya tu mahābāho rāghavasya parākramam
lakṣmaṇasya ca vikrāntam abhavat prītimān kapiḥ', null, 5003017),
('ramayana-5-3-18', 18, 'Sundara Kanda, Sarga 3, Verse 18', 'तां रत्नवसनोपेतां कोष्ठागारावतंसकाम्।
यन्त्रागारस्तनीमृद्धां प्रमदामिव भूषिताम्॥', 'tāṃ ratnavasanopetāṃ koṣṭhāgārāvataṃsakām
yantrāgārastanīm ṛddhāṃ pramadām iva bhūṣitām', null, 5003018),
('ramayana-5-3-19', 19, 'Sundara Kanda, Sarga 3, Verse 19', 'तां नष्टतिमिरां दीपैर्भास्वरैश्च महागृहैः।
नगरीं राक्षसेन्द्रस्य ददर्श स महाकपिः॥', 'tāṃ naṣṭatimirāṃ dīpair bhāsvaraiś ca mahāgṛhaiḥ
nagarīṃ rākṣasendrasya dadarśa sa mahākapiḥ', null, 5003019),
('ramayana-5-3-20', 20, 'Sundara Kanda, Sarga 3, Verse 20', 'प्रविष्टः सत्त्वसंपन्नो निशायां मारुतात्मजः।
स महापथमास्थाय मुक्तापुष्पविराजितम्॥', 'praviṣṭaḥ sattvasaṃpanno niśāyāṃ mārutātmajaḥ
sa mahāpatham āsthāya muktāpuṣpavirājitam', null, 5003020),
('ramayana-5-3-21', 21, 'Sundara Kanda, Sarga 3, Verse 21', 'हसितोद्घुष्टनिनदैस्तूर्यघोष पुरः सरैः।
वज्राङ्कुशनिकाशैश्च वज्रजालविभूषितैः।
गृहमेधैः पुरी रम्या बभासे द्यौरिवाम्बुदैः॥', 'hasitodghuṣṭaninadais tūryaghoṣa puraḥ saraiḥ
vajrāṅkuśanikāśaiś ca vajrajālavibhūṣitaiḥ
gṛhamedhaiḥ purī ramyā babhāse dyaur ivāmbudaiḥ', null, 5003021),
('ramayana-5-3-22', 22, 'Sundara Kanda, Sarga 3, Verse 22', 'प्रजज्वाल तदा लङ्का रक्षोगणगृहैः शुभैः।
सिताभ्रसदृशैश्चित्रैः पद्मस्वस्तिकसंस्थितैः।
वर्धमानगृहैश्चापि सर्वतः सुविभाषितैः॥', 'prajajvāla tadā laṅkā rakṣogaṇagṛhaiḥ śubhaiḥ
sitābhrasadṛśaiś citraiḥ padmasvastikasaṃsthitaiḥ
vardhamānagṛhaiś cāpi sarvataḥ suvibhāṣitaiḥ', null, 5003022),
('ramayana-5-3-23', 23, 'Sundara Kanda, Sarga 3, Verse 23', 'तां चित्रमाल्याभरणां कपिराजहितंकरः।
राघवार्थं चरञ्श्रीमान्ददर्श च ननन्द च॥', 'tāṃ citramālyābharaṇāṃ kapirājahitaṃkaraḥ
rāghavārthaṃ carañ śrīmān dadarśa ca nananda ca', null, 5003023),
('ramayana-5-3-24', 24, 'Sundara Kanda, Sarga 3, Verse 24', 'शुश्राव मधुरं गीतं त्रिस्थानस्वरभूषितम्।
स्त्रीणां मदसमृद्धानां दिवि चाप्सरसामिव॥', 'śuśrāva madhuraṃ gītaṃ tristhānasvarabhūṣitam
strīṇāṃ madasamṛddhānāṃ divi cāpsarasām iva', null, 5003024),
('ramayana-5-3-25', 25, 'Sundara Kanda, Sarga 3, Verse 25', 'शुश्राव काञ्चीनिनादं नूपुराणां च निःस्वनम्।
सोपाननिनदांश्चैव भवनेषु महात्मनम्।
आस्फोटितनिनादांश्च क्ष्वेडितांश्च ततस्ततः॥', 'śuśrāva kāñcīninādaṃ nūpurāṇāṃ ca niḥsvanam
sopānaninadāṃś caiva bhavaneṣu mahātmanam
āsphoṭitaninādāṃś ca kṣveḍitāṃś ca tatas tataḥ', null, 5003025),
('ramayana-5-3-26', 26, 'Sundara Kanda, Sarga 3, Verse 26', 'स्वाध्याय निरतांश्चैव यातुधानान्ददर्श सः।
रावणस्तवसंयुक्तान्गर्जतो राक्षसानपि॥', 'svādhyāya niratāṃś caiva yātudhānān dadarśa saḥ
rāvaṇastavasaṃyuktān garjato rākṣasān api', null, 5003026),
('ramayana-5-3-27', 27, 'Sundara Kanda, Sarga 3, Verse 27', 'राजमार्गं समावृत्य स्थितं रक्षोबलं महत्।
ददर्श मध्यमे गुल्मे राक्षसस्य चरान्बहून्॥', 'rājamārgaṃ samāvṛtya sthitaṃ rakṣobalaṃ mahat
dadarśa madhyame gulme rākṣasasya carān bahūn', null, 5003027),
('ramayana-5-3-28', 28, 'Sundara Kanda, Sarga 3, Verse 28', 'दीक्षिताञ्जटिलान्मुण्डान्गोऽजिनाम्बरवाससः।
दर्भमुष्टिप्रहरणानग्निकुण्डायुधांस्तथा॥', 'dīkṣitāñ jaṭilān muṇḍān go''jināmbaravāsasaḥ
darbhamuṣṭipraharaṇān agnikuṇḍāyudhāṃs tathā', null, 5003028),
('ramayana-5-3-29', 29, 'Sundara Kanda, Sarga 3, Verse 29', 'कूटमुद्गरपाणींश्च दण्डायुधधरानपि।
एकाक्षानेककर्णांश्च चलल्लम्बपयोधरान्॥', 'kūṭamudgarapāṇīṃś ca daṇḍāyudhadharān api
ekākṣānekakarṇāṃś ca calallambapayodharān', null, 5003029),
('ramayana-5-3-30', 30, 'Sundara Kanda, Sarga 3, Verse 30', 'करालान्भुग्नवक्त्रांश्च विकटान्वामनांस्तथा।
धन्विनः खड्गिनश्चैव शतघ्नी मुसलायुधान्।
परिघोत्तमहस्तांश्च विचित्रकवचोज्ज्वलान्॥', 'karālān bhugnavaktrāṃś ca vikaṭān vāmanāṃs tathā
dhanvinaḥ khaḍginaś caiva śataghnī musalāyudhān
parighottamahastāṃś ca vicitrakavacojjvalān', null, 5003030),
('ramayana-5-3-31', 31, 'Sundara Kanda, Sarga 3, Verse 31', 'नातिष्ठूलान्नातिकृशान्नातिदीर्घातिह्रस्वकान्।
विरूपान्बहुरूपांश्च सुरूपांश्च सुवर्चसः॥', 'nātiṣṭhūlān nātikṛśān nātidīrghātihrasvakān
virūpān bahurūpāṃś ca surūpāṃś ca suvarcasaḥ', null, 5003031),
('ramayana-5-3-32', 32, 'Sundara Kanda, Sarga 3, Verse 32', 'शक्तिवृक्षायुधांश्चैव पट्टिशाशनिधारिणः।
क्षेपणीपाशहस्तांश्च ददर्श स महाकपिः॥', 'śaktivṛkṣāyudhāṃś caiva paṭṭiśāśanidhāriṇaḥ
kṣepaṇīpāśahastāṃś ca dadarśa sa mahākapiḥ', null, 5003032),
('ramayana-5-3-33', 33, 'Sundara Kanda, Sarga 3, Verse 33', 'स्रग्विणस्त्वनुलिप्तांश्च वराभरणभूषितान्।
तीक्ष्णशूलधरांश्चैव वज्रिणश्च महाबलान्॥', 'sragviṇas tv anuliptāṃś ca varābharaṇabhūṣitān
tīkṣṇaśūladharāṃś caiva vajriṇaś ca mahābalān', null, 5003033),
('ramayana-5-3-34', 34, 'Sundara Kanda, Sarga 3, Verse 34', 'शतसाहस्रमव्यग्रमारक्षं मध्यमं कपिः।
प्राकारावृतमत्यन्तं ददर्श स महाकपिः॥', 'śatasāhasram avyagram ārakṣaṃ madhyamaṃ kapiḥ
prākārāvṛtam atyantaṃ dadarśa sa mahākapiḥ', null, 5003034),
('ramayana-5-3-35', 35, 'Sundara Kanda, Sarga 3, Verse 35', 'त्रिविष्टपनिभं दिव्यं दिव्यनादविनादितम्।
वाजिहेषितसंघुष्टं नादितं भूषणैस्तथा॥', 'triviṣṭapanibhaṃ divyaṃ divyanādavināditam
vājiheṣitasaṃghuṣṭaṃ nāditaṃ bhūṣaṇais tathā', null, 5003035),
('ramayana-5-3-36', 36, 'Sundara Kanda, Sarga 3, Verse 36', 'रथैर्यानैर्विमानैश्च तथा गजहयैः शुभैः।
वारणैश्च चतुर्दन्तैः श्वेताभ्रनिचयोपमैः॥', 'rathair yānair vimānaiś ca tathā gajahayaiḥ śubhaiḥ
vāraṇaiś ca caturdantaiḥ śvetābhranicayopamaiḥ', null, 5003036),
('ramayana-5-3-37', 37, 'Sundara Kanda, Sarga 3, Verse 37', 'भूषितं रुचिरद्वारं मत्तैश्च मृगपक्षिभिः।
राक्षसाधिपतेर्गुप्तमाविवेश गृहं कपिः॥', 'bhūṣitaṃ ruciradvāraṃ mattaiś ca mṛgapakṣibhiḥ
rākṣasādhipater guptam āviveśa gṛhaṃ kapiḥ', null, 5003037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 4 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-4-1', 1, 'Sundara Kanda, Sarga 4, Verse 1', 'ततः स मध्यं गतमंशुमन्तं ज्योत्स्नावितानं महदुद्वमन्तम्।
ददर्श धीमान्दिवि भानुमन्तं गोष्ठे वृषं मत्तमिव भ्रमन्तम्॥', 'tataḥ sa madhyaṃ gatam aṃśumantaṃ jyotsnāvitānaṃ mahad udvamantam
dadarśa dhīmān divi bhānumantaṃ goṣṭhe vṛṣaṃ mattam iva bhramantam', null, 5004001),
('ramayana-5-4-2', 2, 'Sundara Kanda, Sarga 4, Verse 2', 'लोकस्य पापानि विनाशयन्तं महोदधिं चापि समेधयन्तम्।
भूतानि सर्वाणि विराजयन्तं ददर्श शीतांशुमथाभियान्तम्॥', 'lokasya pāpāni vināśayantaṃ mahodadhiṃ cāpi samedhayantam
bhūtāni sarvāṇi virājayantaṃ dadarśa śītāṃśum athābhiyāntam', null, 5004002),
('ramayana-5-4-3', 3, 'Sundara Kanda, Sarga 4, Verse 3', 'या भाति लक्ष्मीर्भुवि मन्दरस्था तथा प्रदोषेषु च सागरस्था।
तथैव तोयेषु च पुष्करस्था रराज सा चारुनिशाकरस्था॥', 'yā bhāti lakṣmīr bhuvi mandarasthā tathā pradoṣeṣu ca sāgarasthā
tathaiva toyeṣu ca puṣkarasthā rarāja sā cāruniśākarasthā', null, 5004003),
('ramayana-5-4-4', 4, 'Sundara Kanda, Sarga 4, Verse 4', 'हंसो यथा राजतपञ्जुरस्थः सिंहो यथा मन्दरकन्दरस्थः।
वीरो यथा गर्वितकुञ्जरस्थश्चन्द्रोऽपि बभ्राज तथाम्बरस्थः॥', 'haṃso yathā rājatapañjurasthaḥ siṃho yathā mandarakandarasthaḥ
vīro yathā garvitakuñjarasthaś candro ''pi babhrāja tathāmbarasthaḥ', null, 5004004),
('ramayana-5-4-5', 5, 'Sundara Kanda, Sarga 4, Verse 5', 'स्थितः ककुद्मानिव तीक्ष्णशृङ्गो महाचलः श्वेत इवोच्चशृङ्गः।
हस्तीव जाम्बूनदबद्धशृङ्गो विभाति चन्द्रः परिपूर्णशृङ्गः॥', 'sthitaḥ kakudmān iva tīkṣṇaśṛṅgo mahācalaḥ śveta ivoccaśṛṅgaḥ
hastīva jāmbūnadabaddhaśṛṅgo vibhāti candraḥ paripūrṇaśṛṅgaḥ', null, 5004005),
('ramayana-5-4-6', 6, 'Sundara Kanda, Sarga 4, Verse 6', 'प्रकाशचन्द्रोदयनष्टदोषः प्रवृद्धरक्षः पिशिताशदोषः।
रामाभिरामेरितचित्तदोषः स्वर्गप्रकाशो भगवान्प्रदोषः॥', 'prakāśacandrodayanaṣṭadoṣaḥ pravṛddharakṣaḥ piśitāśadoṣaḥ
rāmābhirāmeritacittadoṣaḥ svargaprakāśo bhagavān pradoṣaḥ', null, 5004006),
('ramayana-5-4-7', 7, 'Sundara Kanda, Sarga 4, Verse 7', 'तन्त्री स्वनाः कर्णसुखाः प्रवृत्ताः स्वपन्ति नार्यः पतिभिः सुवृत्ताः।
नक्तंचराश्चापि तथा प्रवृत्ता विहर्तुमत्यद्भुतरौद्रवृत्ताः॥', 'tantrī svanāḥ karṇasukhāḥ pravṛttāḥ svapanti nāryaḥ patibhiḥ suvṛttāḥ
naktaṃcarāś cāpi tathā pravṛttā vihartum atyadbhutaraudravṛttāḥ', null, 5004007),
('ramayana-5-4-8', 8, 'Sundara Kanda, Sarga 4, Verse 8', 'मत्तप्रमत्तानि समाकुलानि रथाश्वभद्रासनसंकुलानि।
वीरश्रिया चापि समाकुलानि ददर्श धीमान्स कपिः कुलानि॥', 'mattapramattāni samākulāni rathāśvabhadrāsanasaṃkulāni
vīraśriyā cāpi samākulāni dadarśa dhīmān sa kapiḥ kulāni', null, 5004008),
('ramayana-5-4-9', 9, 'Sundara Kanda, Sarga 4, Verse 9', 'परस्परं चाधिकमाक्षिपन्ति भुजांश्च पीनानधिविक्षिपन्ति।
मत्तप्रलापानधिविक्षिपन्ति मत्तानि चान्योन्यमधिक्षिपन्ति॥', 'parasparaṃ cādhikam ākṣipanti bhujāṃś ca pīnān adhivikṣipanti
mattapralāpān adhivikṣipanti mattāni cānyonyam adhikṣipanti', null, 5004009),
('ramayana-5-4-10', 10, 'Sundara Kanda, Sarga 4, Verse 10', 'रक्षांसि वक्षांसि च विक्षिपन्ति गात्राणि कान्तासु च विक्षिपन्ति।
ददर्श कान्ताश्च समालपन्ति तथापरास्तत्र पुनः स्वपन्ति॥', 'rakṣāṃsi vakṣāṃsi ca vikṣipanti gātrāṇi kāntāsu ca vikṣipanti
dadarśa kāntāś ca samālapanti tathāparās tatra punaḥ svapanti', null, 5004010),
('ramayana-5-4-11', 11, 'Sundara Kanda, Sarga 4, Verse 11', 'महागजैश्चापि तथा नदद्भिः सूपूजितैश्चापि तथा सुसद्भिः।
रराज वीरैश्च विनिःश्वसद्भिर्ह्रदो भुजङ्गैरिव निःश्वसद्भिः॥', 'mahāgajaiś cāpi tathā nadadbhiḥ sūpūjitaiś cāpi tathā susadbhiḥ
rarāja vīraiś ca viniḥśvasadbhir hrado bhujaṅgair iva niḥśvasadbhiḥ', null, 5004011),
('ramayana-5-4-12', 12, 'Sundara Kanda, Sarga 4, Verse 12', 'बुद्धिप्रधानान्रुचिराभिधानान्संश्रद्दधानाञ्जगतः प्रधानान्।
नानाविधानान्रुचिराभिधानान्ददर्श तस्यां पुरि यातुधानान्॥', 'buddhipradhānān rucirābhidhānān saṃśraddadhānāñ jagataḥ pradhānān
nānāvidhānān rucirābhidhānān dadarśa tasyāṃ puri yātudhānān', null, 5004012),
('ramayana-5-4-13', 13, 'Sundara Kanda, Sarga 4, Verse 13', 'ननन्द दृष्ट्वा स च तान्सुरूपान्नानागुणानात्मगुणानुरूपान्।
विद्योतमानान्स च तान्सुरूपान्ददर्श कांश्चिच्च पुनर्विरूपान्॥', 'nananda dṛṣṭvā sa ca tān surūpān nānāguṇān ātmaguṇānurūpān
vidyotamānān sa ca tān surūpān dadarśa kāṃś cic ca punar virūpān', null, 5004013),
('ramayana-5-4-14', 14, 'Sundara Kanda, Sarga 4, Verse 14', 'ततो वरार्हाः सुविशुद्धभावास्तेषां स्त्रियस्तत्र महानुभावाः।
प्रियेषु पानेषु च सक्तभावा ददर्श तारा इव सुप्रभावाः॥', 'tato varārhāḥ suviśuddhabhāvās teṣāṃ striyas tatra mahānubhāvāḥ
priyeṣu pāneṣu ca saktabhāvā dadarśa tārā iva suprabhāvāḥ', null, 5004014),
('ramayana-5-4-15', 15, 'Sundara Kanda, Sarga 4, Verse 15', 'श्रिया ज्वलन्तीस्त्रपयोपगूढा निशीथकाले रमणोपगूढाः।
ददर्श काश्चित्प्रमदोपगूढा यथा विहंगाः कुसुमोपगूडाः॥', 'śriyā jvalantīs trapayopagūḍhā niśīthakāle ramaṇopagūḍhāḥ
dadarśa kāś cit pramadopagūḍhā yathā vihaṃgāḥ kusumopagūḍāḥ', null, 5004015),
('ramayana-5-4-16', 16, 'Sundara Kanda, Sarga 4, Verse 16', 'अन्याः पुनर्हर्म्यतलोपविष्टास्तत्र प्रियाङ्केषु सुखोपविष्टाः।
भर्तुः प्रिया धर्मपरा निविष्टा ददर्श धीमान्मनदाभिविष्टाः॥', 'anyāḥ punar harmyatalopaviṣṭās tatra priyāṅkeṣu sukhopaviṣṭāḥ
bhartuḥ priyā dharmaparā niviṣṭā dadarśa dhīmān manadābhiviṣṭāḥ', null, 5004016),
('ramayana-5-4-17', 17, 'Sundara Kanda, Sarga 4, Verse 17', 'अप्रावृताः काञ्चनराजिवर्णाः काश्चित्परार्ध्यास्तपनीयवर्णाः।
पुनश्च काश्चिच्छशलक्ष्मवर्णाः कान्तप्रहीणा रुचिराङ्गवर्णाः॥', 'aprāvṛtāḥ kāñcanarājivarṇāḥ kāś cit parārdhyās tapanīyavarṇāḥ
punaś ca kāś cic chaśalakṣmavarṇāḥ kāntaprahīṇā rucirāṅgavarṇāḥ', null, 5004017),
('ramayana-5-4-18', 18, 'Sundara Kanda, Sarga 4, Verse 18', 'ततः प्रियान्प्राप्य मनोऽभिरामान्सुप्रीतियुक्ताः प्रसमीक्ष्य रामाः।
गृहेषु हृष्टाः परमाभिरामा हरिप्रवीरः स ददर्श रामाः॥', 'tataḥ priyān prāpya mano''bhirāmān suprītiyuktāḥ prasamīkṣya rāmāḥ
gṛheṣu hṛṣṭāḥ paramābhirāmā haripravīraḥ sa dadarśa rāmāḥ', null, 5004018),
('ramayana-5-4-19', 19, 'Sundara Kanda, Sarga 4, Verse 19', 'चन्द्रप्रकाशाश्च हि वक्त्रमाला वक्राक्षिपक्ष्माश्च सुनेत्रमालाः।
विभूषणानां च ददर्श मालाः शतह्रदानामिव चारुमालाः॥', 'candraprakāśāś ca hi vaktramālā vakrākṣipakṣmāś ca sunetramālāḥ
vibhūṣaṇānāṃ ca dadarśa mālāḥ śatahradānām iva cārumālāḥ', null, 5004019),
('ramayana-5-4-20', 20, 'Sundara Kanda, Sarga 4, Verse 20', 'न त्वेव सीतां परमाभिजातां पथि स्थिते राजकुले प्रजाताम्।
लतां प्रफुल्लामिव साधुजातां ददर्श तन्वीं मनसाभिजाताम्॥', 'na tv eva sītāṃ paramābhijātāṃ pathi sthite rājakule prajātām
latāṃ praphullām iva sādhujātāṃ dadarśa tanvīṃ manasābhijātām', null, 5004020),
('ramayana-5-4-21', 21, 'Sundara Kanda, Sarga 4, Verse 21', 'सनातने वर्त्मनि संनिविष्टां रामेक्षणीं तां मदनाभिविष्टाम्।
भर्तुर्मनः श्रीमदनुप्रविष्टां स्त्रीभ्यो वराभ्यश्च सदा विशिष्टाम्॥', 'sanātane vartmani saṃniviṣṭāṃ rāmekṣaṇīṃ tāṃ madanābhiviṣṭām
bhartur manaḥ śrīmad anupraviṣṭāṃ strībhyo varābhyaś ca sadā viśiṣṭām', null, 5004021),
('ramayana-5-4-22', 22, 'Sundara Kanda, Sarga 4, Verse 22', 'उष्णार्दितां सानुसृतास्रकण्ठीं पुरा वरार्होत्तमनिष्ककण्ठीम्।
सुजातपक्ष्मामभिरक्तकण्ठीं वने प्रवृत्तामिव नीलकण्ठीम्॥', 'uṣṇārditāṃ sānusṛtāsrakaṇṭhīṃ purā varārhottamaniṣkakaṇṭhīm
sujātapakṣmām abhiraktakaṇṭhīṃ vane pravṛttām iva nīlakaṇṭhīm', null, 5004022),
('ramayana-5-4-23', 23, 'Sundara Kanda, Sarga 4, Verse 23', 'अव्यक्तलेखामिव चन्द्रलेखां पांसुप्रदिग्धामिव हेमलेखाम्।
क्षतप्ररूढामिव बाणलेखां वायुप्रभिन्नामिव मेघलेखाम्॥', 'avyaktalekhām iva candralekhāṃ pāṃsupradigdhām iva hemalekhām
kṣataprarūḍhām iva bāṇalekhāṃ vāyuprabhinnām iva meghalekhām', null, 5004023),
('ramayana-5-4-24', 24, 'Sundara Kanda, Sarga 4, Verse 24', 'सीतामपश्यन्मनुजेश्वरस्य रामस्य पत्नीं वदतां वरस्य।
बभूव दुःखाभिहतश्चिरस्य प्लवंगमो मन्द इवाचिरस्य॥', 'sītām apaśyan manujeśvarasya rāmasya patnīṃ vadatāṃ varasya
babhūva duḥkhābhihataś cirasya plavaṃgamo manda ivācirasya', null, 5004024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 5 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-5-1', 1, 'Sundara Kanda, Sarga 5, Verse 1', 'स निकामं विनामेषु विचरन्कामरूपधृक्।
विचचार कपिर्लङ्कां लाघवेन समन्वितः॥', 'sa nikāmaṃ vināmeṣu vicaran kāmarūpadhṛk
vicacāra kapir laṅkāṃ lāghavena samanvitaḥ', null, 5005001),
('ramayana-5-5-2', 2, 'Sundara Kanda, Sarga 5, Verse 2', 'आससादाथ लक्ष्मीवान्राक्षसेन्द्रनिवेशनम्।
प्राकारेणार्कवर्णेन भास्वरेणाभिसंवृतम्॥', 'āsasādātha lakṣmīvān rākṣasendraniveśanam
prākāreṇārkavarṇena bhāsvareṇābhisaṃvṛtam', null, 5005002),
('ramayana-5-5-3', 3, 'Sundara Kanda, Sarga 5, Verse 3', 'रक्षितं राक्षसैर्भीमैः सिंहैरिव महद्वनम्।
समीक्षमाणो भवनं चकाशे कपिकुञ्जरः॥', 'rakṣitaṃ rākṣasair bhīmaiḥ siṃhair iva mahad vanam
samīkṣamāṇo bhavanaṃ cakāśe kapikuñjaraḥ', null, 5005003),
('ramayana-5-5-4', 4, 'Sundara Kanda, Sarga 5, Verse 4', 'रूप्यकोपहितैश्चित्रैस्तोरणैर्हेमभूषितैः।
विचित्राभिश्च कक्ष्याभिर्द्वारैश्च रुचिरैर्वृतम्॥', 'rūpyakopahitaiś citrais toraṇair hemabhūṣitaiḥ
vicitrābhiś ca kakṣyābhir dvāraiś ca rucirair vṛtam', null, 5005004),
('ramayana-5-5-5', 5, 'Sundara Kanda, Sarga 5, Verse 5', 'गजास्थितैर्महामात्रैः शूरैश्च विगतश्रमैः।
उपस्थितमसंहार्यैर्हयैः स्यन्दनयायिभिः॥', 'gajāsthitair mahāmātraiḥ śūraiś ca vigataśramaiḥ
upasthitam asaṃhāryair hayaiḥ syandanayāyibhiḥ', null, 5005005),
('ramayana-5-5-6', 6, 'Sundara Kanda, Sarga 5, Verse 6', 'सिंहव्याघ्रतनुत्राणैर्दान्तकाञ्चनराजतैः।
घोषवद्भिर्विचित्रैश्च सदा विचरितं रथैः॥', 'siṃhavyāghratanutrāṇair dāntakāñcanarājataiḥ
ghoṣavadbhir vicitraiś ca sadā vicaritaṃ rathaiḥ', null, 5005006),
('ramayana-5-5-7', 7, 'Sundara Kanda, Sarga 5, Verse 7', 'बहुरत्नसमाकीर्णं परार्ध्यासनभाजनम्।
महारथसमावासं महारथमहासनम्॥', 'bahuratnasamākīrṇaṃ parārdhyāsanabhājanam
mahārathasamāvāsaṃ mahārathamahāsanam', null, 5005007),
('ramayana-5-5-8', 8, 'Sundara Kanda, Sarga 5, Verse 8', 'दृश्यैश्च परमोदारैस्तैस्तैश्च मृगपक्षिभिः।
विविधैर्बहुसाहस्रैः परिपूर्णं समन्ततः॥', 'dṛśyaiś ca paramodārais tais taiś ca mṛgapakṣibhiḥ
vividhair bahusāhasraiḥ paripūrṇaṃ samantataḥ', null, 5005008),
('ramayana-5-5-9', 9, 'Sundara Kanda, Sarga 5, Verse 9', 'विनीतैरन्तपालैश्च रक्षोभिश्च सुरक्षितम्।
मुख्याभिश्च वरस्त्रीभिः परिपूर्णं समन्ततः॥', 'vinītair antapālaiś ca rakṣobhiś ca surakṣitam
mukhyābhiś ca varastrībhiḥ paripūrṇaṃ samantataḥ', null, 5005009),
('ramayana-5-5-10', 10, 'Sundara Kanda, Sarga 5, Verse 10', 'मुदितप्रमदा रत्नं राक्षसेन्द्रनिवेशनम्।
वराभरणनिर्ह्रादैः समुद्रस्वननिःस्वनम्॥', 'muditapramadā ratnaṃ rākṣasendraniveśanam
varābharaṇanirhrādaiḥ samudrasvananiḥsvanam', null, 5005010),
('ramayana-5-5-11', 11, 'Sundara Kanda, Sarga 5, Verse 11', 'तद्राजगुणसंपन्नं मुख्यैश्च वरचन्दनैः।
भेरीमृदङ्गाभिरुतं शङ्खघोषविनादितम्॥', 'tad rājaguṇasaṃpannaṃ mukhyaiś ca varacandanaiḥ
bherīmṛdaṅgābhirutaṃ śaṅkhaghoṣavināditam', null, 5005011),
('ramayana-5-5-12', 12, 'Sundara Kanda, Sarga 5, Verse 12', 'नित्यार्चितं पर्वहुतं पूजितं राक्षसैः सदा।
समुद्रमिव गम्भीरं समुद्रमिव निःस्वनम्॥', 'nityārcitaṃ parvahutaṃ pūjitaṃ rākṣasaiḥ sadā
samudram iva gambhīraṃ samudram iva niḥsvanam', null, 5005012),
('ramayana-5-5-13', 13, 'Sundara Kanda, Sarga 5, Verse 13', 'महात्मानो महद्वेश्म महारत्नपरिच्छदम्।
महाजनसमाकीर्णं ददर्श स महाकपिः॥', 'mahātmāno mahad veśma mahāratnaparicchadam
mahājanasamākīrṇaṃ dadarśa sa mahākapiḥ', null, 5005013),
('ramayana-5-5-14', 14, 'Sundara Kanda, Sarga 5, Verse 14', 'विराजमानं वपुषा गजाश्वरथसंकुलम्।
लङ्काभरणमित्येव सोऽमन्यत महाकपिः॥', 'virājamānaṃ vapuṣā gajāśvarathasaṃkulam
laṅkābharaṇam ity eva so ''manyata mahākapiḥ', null, 5005014),
('ramayana-5-5-15', 15, 'Sundara Kanda, Sarga 5, Verse 15', 'गृहाद्गृहं राक्षसानामुद्यानानि च वानरः।
वीक्षमाणो ह्यसंत्रस्तः प्रासादांश्च चचार सः॥', 'gṛhād gṛhaṃ rākṣasānām udyānāni ca vānaraḥ
vīkṣamāṇo hy asaṃtrastaḥ prāsādāṃś ca cacāra saḥ', null, 5005015),
('ramayana-5-5-16', 16, 'Sundara Kanda, Sarga 5, Verse 16', 'अवप्लुत्य महावेगः प्रहस्तस्य निवेशनम्।
ततोऽन्यत्पुप्लुवे वेश्म महापार्श्वस्य वीर्यवान्॥', 'avaplutya mahāvegaḥ prahastasya niveśanam
tato ''nyat pupluve veśma mahāpārśvasya vīryavān', null, 5005016),
('ramayana-5-5-17', 17, 'Sundara Kanda, Sarga 5, Verse 17', 'अथ मेघप्रतीकाशं कुम्भकर्णनिवेशनम्।
विभीषणस्य च तथा पुप्लुवे स महाकपिः॥', 'atha meghapratīkāśaṃ kumbhakarṇaniveśanam
vibhīṣaṇasya ca tathā pupluve sa mahākapiḥ', null, 5005017),
('ramayana-5-5-18', 18, 'Sundara Kanda, Sarga 5, Verse 18', 'महोदरस्य च तथा विरूपाक्षस्य चैव हि।
विद्युज्जिह्वस्य भवनं विद्युन्मालेस्तथैव च।
वज्रदंष्ट्रस्य च तथा पुप्लुवे स महाकपिः॥', 'mahodarasya ca tathā virūpākṣasya caiva hi
vidyujjihvasya bhavanaṃ vidyunmāles tathaiva ca
vajradaṃṣṭrasya ca tathā pupluve sa mahākapiḥ', null, 5005018),
('ramayana-5-5-19', 19, 'Sundara Kanda, Sarga 5, Verse 19', 'शुकस्य च महावेगः सारणस्य च धीमतः।
तथा चेन्द्रजितो वेश्म जगाम हरियूथपः॥', 'śukasya ca mahāvegaḥ sāraṇasya ca dhīmataḥ
tathā cendrajito veśma jagāma hariyūthapaḥ', null, 5005019),
('ramayana-5-5-20', 20, 'Sundara Kanda, Sarga 5, Verse 20', 'जम्बुमालेः सुमालेश्च जगाम हरियूथपः।
रश्मिकेतोश्च भवनं सूर्यशत्रोस्तथैव च॥', 'jambumāleḥ sumāleś ca jagāma hariyūthapaḥ
raśmiketoś ca bhavanaṃ sūryaśatros tathaiva ca', null, 5005020),
('ramayana-5-5-21', 21, 'Sundara Kanda, Sarga 5, Verse 21', 'धूम्राक्षस्य च संपातेर्भवनं मारुतात्मजः।
विद्युद्रूपस्य भीमस्य घनस्य विघनस्य च॥', 'dhūmrākṣasya ca saṃpāter bhavanaṃ mārutātmajaḥ
vidyudrūpasya bhīmasya ghanasya vighanasya ca', null, 5005021),
('ramayana-5-5-22', 22, 'Sundara Kanda, Sarga 5, Verse 22', 'शुकनाभस्य वक्रस्य शठस्य विकटस्य च।
ह्रस्वकर्णस्य दंष्ट्रस्य रोमशस्य च रक्षसः॥', 'śukanābhasya vakrasya śaṭhasya vikaṭasya ca
hrasvakarṇasya daṃṣṭrasya romaśasya ca rakṣasaḥ', null, 5005022),
('ramayana-5-5-23', 23, 'Sundara Kanda, Sarga 5, Verse 23', 'युद्धोन्मत्तस्य मत्तस्य ध्वजग्रीवस्य नादिनः।
विद्युज्जिह्वेन्द्रजिह्वानां तथा हस्तिमुखस्य च॥', 'yuddhonmattasya mattasya dhvajagrīvasya nādinaḥ
vidyujjihvendrajihvānāṃ tathā hastimukhasya ca', null, 5005023),
('ramayana-5-5-24', 24, 'Sundara Kanda, Sarga 5, Verse 24', 'करालस्य पिशाचस्य शोणिताक्षस्य चैव हि।
क्रममाणः क्रमेणैव हनूमान्मारुतात्मजः॥', 'karālasya piśācasya śoṇitākṣasya caiva hi
kramamāṇaḥ krameṇaiva hanūmān mārutātmajaḥ', null, 5005024),
('ramayana-5-5-25', 25, 'Sundara Kanda, Sarga 5, Verse 25', 'तेषु तेषु महार्हेषु भवनेषु महायशाः।
तेषामृद्धिमतामृद्धिं ददर्श स महाकपिः॥', 'teṣu teṣu mahārheṣu bhavaneṣu mahāyaśāḥ
teṣām ṛddhimatām ṛddhiṃ dadarśa sa mahākapiḥ', null, 5005025),
('ramayana-5-5-26', 26, 'Sundara Kanda, Sarga 5, Verse 26', 'सर्वेषां समतिक्रम्य भवनानि समन्ततः।
आससादाथ लक्ष्मीवान्राक्षसेन्द्रनिवेशनम्॥', 'sarveṣāṃ samatikramya bhavanāni samantataḥ
āsasādātha lakṣmīvān rākṣasendraniveśanam', null, 5005026),
('ramayana-5-5-27', 27, 'Sundara Kanda, Sarga 5, Verse 27', 'रावणस्योपशायिन्यो ददर्श हरिसत्तमः।
विचरन्हरिशार्दूलो राक्षसीर्विकृतेक्षणाः।
शूलमुद्गरहस्ताश्च शक्तो तोमरधारिणीः॥', 'rāvaṇasyopaśāyinyo dadarśa harisattamaḥ
vicaran hariśārdūlo rākṣasīr vikṛtekṣaṇāḥ
śūlamudgarahastāś ca śakto tomaradhāriṇīḥ', null, 5005027),
('ramayana-5-5-28', 28, 'Sundara Kanda, Sarga 5, Verse 28', 'ददर्श विविधान्गुल्मांस्तस्य रक्षःपतेर्गृहे॥', 'dadarśa vividhān gulmāṃs tasya rakṣaḥpater gṛhe', null, 5005028),
('ramayana-5-5-29', 29, 'Sundara Kanda, Sarga 5, Verse 29', 'रक्ताञ्श्वेतान्सितांश्चैव हरींश्चैव महाजवान्।
कुलीनान्रूपसंपन्नान्गजान्परगजारुजान्॥', 'raktāñ śvetān sitāṃś caiva harīṃś caiva mahājavān
kulīnān rūpasaṃpannān gajān paragajārujān', null, 5005029),
('ramayana-5-5-30', 30, 'Sundara Kanda, Sarga 5, Verse 30', 'निष्ठितान्गजशिखायामैरावतसमान्युधि।
निहन्तॄन्परसैन्यानां गृहे तस्मिन्ददर्श सः॥', 'niṣṭhitān gajaśikhāyām airāvatasamān yudhi
nihantṝn parasainyānāṃ gṛhe tasmin dadarśa saḥ', null, 5005030),
('ramayana-5-5-31', 31, 'Sundara Kanda, Sarga 5, Verse 31', 'क्षरतश्च यथा मेघान्स्रवतश्च यथा गिरीन्।
मेघस्तनितनिर्घोषान्दुर्धर्षान्समरे परैः॥', 'kṣarataś ca yathā meghān sravataś ca yathā girīn
meghastanitanirghoṣān durdharṣān samare paraiḥ', null, 5005031),
('ramayana-5-5-32', 32, 'Sundara Kanda, Sarga 5, Verse 32', 'सहस्रं वाहिनीस्तत्र जाम्बूनदपरिष्कृताः।
हेमजालैरविच्छिन्नास्तरुणादित्यसंनिभाः॥', 'sahasraṃ vāhinīs tatra jāmbūnadapariṣkṛtāḥ
hemajālair avicchinnās taruṇādityasaṃnibhāḥ', null, 5005032),
('ramayana-5-5-33', 33, 'Sundara Kanda, Sarga 5, Verse 33', 'ददर्श राक्षसेन्द्रस्य रावणस्य निवेशने।
शिबिका विविधाकाराः स कपिर्मारुतात्मजः॥', 'dadarśa rākṣasendrasya rāvaṇasya niveśane
śibikā vividhākārāḥ sa kapir mārutātmajaḥ', null, 5005033),
('ramayana-5-5-34', 34, 'Sundara Kanda, Sarga 5, Verse 34', 'लतागृहाणि चित्राणि चित्रशालागृहाणि च।
क्रीडागृहाणि चान्यानि दारुपर्वतकानपि॥', 'latāgṛhāṇi citrāṇi citraśālāgṛhāṇi ca
krīḍāgṛhāṇi cānyāni dāruparvatakān api', null, 5005034),
('ramayana-5-5-35', 35, 'Sundara Kanda, Sarga 5, Verse 35', 'कामस्य गृहकं रम्यं दिवागृहकमेव च।
ददर्श राक्षसेन्द्रस्य रावणस्य निवेशने॥', 'kāmasya gṛhakaṃ ramyaṃ divāgṛhakam eva ca
dadarśa rākṣasendrasya rāvaṇasya niveśane', null, 5005035),
('ramayana-5-5-36', 36, 'Sundara Kanda, Sarga 5, Verse 36', 'स मन्दरतलप्रख्यं मयूरस्थानसंकुलम्।
ध्वजयष्टिभिराकीर्णं ददर्श भवनोत्तमम्॥', 'sa mandaratalaprakhyaṃ mayūrasthānasaṃkulam
dhvajayaṣṭibhir ākīrṇaṃ dadarśa bhavanottamam', null, 5005036),
('ramayana-5-5-37', 37, 'Sundara Kanda, Sarga 5, Verse 37', 'अनन्तरत्ननिचयं निधिजालं समन्ततः।
धीरनिष्ठितकर्मान्तं गृहं भूतपतेरिव॥', 'anantaratnanicayaṃ nidhijālaṃ samantataḥ
dhīraniṣṭhitakarmāntaṃ gṛhaṃ bhūtapater iva', null, 5005037),
('ramayana-5-5-38', 38, 'Sundara Kanda, Sarga 5, Verse 38', 'अर्चिर्भिश्चापि रत्नानां तेजसा रावणस्य च।
विरराजाथ तद्वेश्म रश्मिमानिव रश्मिभिः॥', 'arcirbhiś cāpi ratnānāṃ tejasā rāvaṇasya ca
virarājātha tad veśma raśmimān iva raśmibhiḥ', null, 5005038),
('ramayana-5-5-39', 39, 'Sundara Kanda, Sarga 5, Verse 39', 'जाम्बूनदमयान्येव शयनान्यासनानि च।
भाजनानि च शुभ्राणि ददर्श हरियूथपः॥', 'jāmbūnadamayāny eva śayanāny āsanāni ca
bhājanāni ca śubhrāṇi dadarśa hariyūthapaḥ', null, 5005039),
('ramayana-5-5-40', 40, 'Sundara Kanda, Sarga 5, Verse 40', 'मध्वासवकृतक्लेदं मणिभाजनसंकुलम्।
मनोरममसंबाधं कुबेरभवनं यथा॥', 'madhvāsavakṛtakledaṃ maṇibhājanasaṃkulam
manoramam asaṃbādhaṃ kuberabhavanaṃ yathā', null, 5005040),
('ramayana-5-5-41', 41, 'Sundara Kanda, Sarga 5, Verse 41', 'नूपुराणां च घोषेण काञ्चीनां निनदेन च।
मृदङ्गतलघोषैश्च घोषवद्भिर्विनादितम्॥', 'nūpurāṇāṃ ca ghoṣeṇa kāñcīnāṃ ninadena ca
mṛdaṅgatalaghoṣaiś ca ghoṣavadbhir vināditam', null, 5005041),
('ramayana-5-5-42', 42, 'Sundara Kanda, Sarga 5, Verse 42', 'प्रासादसंघातयुतं स्त्रीरत्नशतसंकुलम्।
सुव्यूढकक्ष्यं हनुमान्प्रविवेश महागृहम्॥', 'prāsādasaṃghātayutaṃ strīratnaśatasaṃkulam
suvyūḍhakakṣyaṃ hanumān praviveśa mahāgṛham', null, 5005042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 6 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-6-1', 1, 'Sundara Kanda, Sarga 6, Verse 1', 'स वेश्मजालं बलवान्ददर्श व्यासक्तवैदूर्यसुवर्णजालम्।
यथा महत्प्रावृषि मेघजालं विद्युत्पिनद्धं सविहंगजालम्॥', 'sa veśmajālaṃ balavān dadarśa vyāsaktavaidūryasuvarṇajālam
yathā mahat prāvṛṣi meghajālaṃ vidyutpinaddhaṃ savihaṃgajālam', null, 5006001),
('ramayana-5-6-2', 2, 'Sundara Kanda, Sarga 6, Verse 2', 'निवेशनानां विविधाश्च शालाः प्रधानशङ्खायुधचापशालाः।
मनोहराश्चापि पुनर्विशाला ददर्श वेश्माद्रिषु चन्द्रशालाः॥', 'niveśanānāṃ vividhāś ca śālāḥ pradhānaśaṅkhāyudhacāpaśālāḥ
manoharāś cāpi punar viśālā dadarśa veśmādriṣu candraśālāḥ', null, 5006002),
('ramayana-5-6-3', 3, 'Sundara Kanda, Sarga 6, Verse 3', 'गृहाणि नानावसुराजितानि देवासुरैश्चापि सुपूजितानि।
सर्वैश्च दोषैः परिवर्जितानि कपिर्ददर्श स्वबलार्जितानि॥', 'gṛhāṇi nānāvasurājitāni devāsuraiś cāpi supūjitāni
sarvaiś ca doṣaiḥ parivarjitāni kapir dadarśa svabalārjitāni', null, 5006003),
('ramayana-5-6-4', 4, 'Sundara Kanda, Sarga 6, Verse 4', 'तानि प्रयत्नाभिसमाहितानि मयेन साक्षादिव निर्मितानि।
महीतले सर्वगुणोत्तराणि ददर्श लङ्काधिपतेर्गृहाणि॥', 'tāni prayatnābhisamāhitāni mayena sākṣād iva nirmitāni
mahītale sarvaguṇottarāṇi dadarśa laṅkādhipater gṛhāṇi', null, 5006004),
('ramayana-5-6-5', 5, 'Sundara Kanda, Sarga 6, Verse 5', 'ततो ददर्शोच्छ्रितमेघरूपं मनोहरं काञ्चनचारुरूपम्।
रक्षोऽधिपस्यात्मबलानुरूपं गृहोत्तमं ह्यप्रतिरूपरूपम्॥', 'tato dadarśocchritamegharūpaṃ manoharaṃ kāñcanacārurūpam
rakṣo''dhipasyātmabalānurūpaṃ gṛhottamaṃ hy apratirūparūpam', null, 5006005),
('ramayana-5-6-6', 6, 'Sundara Kanda, Sarga 6, Verse 6', 'महीतले स्वर्गमिव प्रकीर्णं श्रिया ज्वलन्तं बहुरत्नकीर्णम्।
नानातरूणां कुसुमावकीर्णं गिरेरिवाग्रं रजसावकीर्णम्॥', 'mahītale svargam iva prakīrṇaṃ śriyā jvalantaṃ bahuratnakīrṇam
nānātarūṇāṃ kusumāvakīrṇaṃ girer ivāgraṃ rajasāvakīrṇam', null, 5006006),
('ramayana-5-6-7', 7, 'Sundara Kanda, Sarga 6, Verse 7', 'नारीप्रवेकैरिव दीप्यमानं तडिद्भिरम्भोदवदर्च्यमानम्।
हंसप्रवेकैरिव वाह्यमानं श्रिया युतं खे सुकृतां विमानम्॥', 'nārīpravekair iva dīpyamānaṃ taḍidbhir ambhodavad arcyamānam
haṃsapravekair iva vāhyamānaṃ śriyā yutaṃ khe sukṛtāṃ vimānam', null, 5006007),
('ramayana-5-6-8', 8, 'Sundara Kanda, Sarga 6, Verse 8', 'यथा नगाग्रं बहुधातुचित्रं यथा नभश्च ग्रहचन्द्रचित्रम्।
ददर्श युक्तीकृतमेघचित्रं विमानरत्नं बहुरत्नचित्रम्॥', 'yathā nagāgraṃ bahudhātucitraṃ yathā nabhaś ca grahacandracitram
dadarśa yuktīkṛtameghacitraṃ vimānaratnaṃ bahuratnacitram', null, 5006008),
('ramayana-5-6-9', 9, 'Sundara Kanda, Sarga 6, Verse 9', 'मही कृता पर्वतराजिपूर्णा शैलाः कृता वृक्षवितानपूर्णाः।
वृक्षाः कृताः पुष्पवितानपूर्णाः पुष्पं कृतं केसरपत्रपूर्णम्॥', 'mahī kṛtā parvatarājipūrṇā śailāḥ kṛtā vṛkṣavitānapūrṇāḥ
vṛkṣāḥ kṛtāḥ puṣpavitānapūrṇāḥ puṣpaṃ kṛtaṃ kesarapatrapūrṇam', null, 5006009),
('ramayana-5-6-10', 10, 'Sundara Kanda, Sarga 6, Verse 10', 'कृतानि वेश्मानि च पाण्डुराणि तथा सुपुष्पा अपि पुष्करिण्यः।
पुनश्च पद्मानि सकेसराणि धन्यानि चित्राणि तथा वनानि॥', 'kṛtāni veśmāni ca pāṇḍurāṇi tathā supuṣpā api puṣkariṇyaḥ
punaś ca padmāni sakesarāṇi dhanyāni citrāṇi tathā vanāni', null, 5006010),
('ramayana-5-6-11', 11, 'Sundara Kanda, Sarga 6, Verse 11', 'पुष्पाह्वयं नाम विराजमानं रत्नप्रभाभिश्च विवर्धमानम्।
वेश्मोत्तमानामपि चोच्चमानं महाकपिस्तत्र महाविमानम्॥', 'puṣpāhvayaṃ nāma virājamānaṃ ratnaprabhābhiś ca vivardhamānam
veśmottamānām api coccamānaṃ mahākapis tatra mahāvimānam', null, 5006011),
('ramayana-5-6-12', 12, 'Sundara Kanda, Sarga 6, Verse 12', 'कृताश्च वैदूर्यमया विहंगा रूप्यप्रवालैश्च तथा विहंगाः।
चित्राश्च नानावसुभिर्भुजंगा जात्यानुरूपास्तुरगाः शुभाङ्गाः॥', 'kṛtāś ca vaidūryamayā vihaṃgā rūpyapravālaiś ca tathā vihaṃgāḥ
citrāś ca nānāvasubhir bhujaṃgā jātyānurūpās turagāḥ śubhāṅgāḥ', null, 5006012),
('ramayana-5-6-13', 13, 'Sundara Kanda, Sarga 6, Verse 13', 'प्रवालजाम्बूनदपुष्पपक्षाः सलीलमावर्जितजिह्मपक्षाः।
कामस्य साक्षादिव भान्ति पक्षाः कृता विहंगाः सुमुखाः सुपक्षाः॥', 'pravālajāmbūnadapuṣpapakṣāḥ salīlam āvarjitajihmapakṣāḥ
kāmasya sākṣād iva bhānti pakṣāḥ kṛtā vihaṃgāḥ sumukhāḥ supakṣāḥ', null, 5006013),
('ramayana-5-6-14', 14, 'Sundara Kanda, Sarga 6, Verse 14', 'नियुज्यमानाश्च गजाः सुहस्ताः सकेसराश्चोत्पलपत्रहस्ताः।
बभूव देवी च कृता सुहस्ता लक्ष्मीस्तथा पद्मिनि पद्महस्ता॥', 'niyujyamānāś ca gajāḥ suhastāḥ sakesarāś cotpalapatrahastāḥ
babhūva devī ca kṛtā suhastā lakṣmīs tathā padmini padmahastā', null, 5006014),
('ramayana-5-6-15', 15, 'Sundara Kanda, Sarga 6, Verse 15', 'इतीव तद्गृहमभिगम्य शोभनं सविस्मयो नगमिव चारुशोभनम्।
पुनश्च तत्परमसुगन्धि सुन्दरं हिमात्यये नगमिव चारुकन्दरम्॥', 'itīva tad gṛham abhigamya śobhanaṃ savismayo nagam iva cāruśobhanam
punaś ca tat paramasugandhi sundaraṃ himātyaye nagam iva cārukandaram', null, 5006015),
('ramayana-5-6-16', 16, 'Sundara Kanda, Sarga 6, Verse 16', 'ततः स तां कपिरभिपत्य पूजितां चरन्पुरीं दशमुखबाहुपालिताम्।
अदृश्य तां जनकसुतां सुपूजितां सुदुःखितां पतिगुणवेगनिर्जिताम्॥', 'tataḥ sa tāṃ kapir abhipatya pūjitāṃ caran purīṃ daśamukhabāhupālitām
adṛśya tāṃ janakasutāṃ supūjitāṃ suduḥkhitāṃ patiguṇaveganirjitām', null, 5006016),
('ramayana-5-6-17', 17, 'Sundara Kanda, Sarga 6, Verse 17', 'ततस्तदा बहुविधभावितात्मनः कृतात्मनो जनकसुतां सुवर्त्मनः।
अपश्यतोऽभवदतिदुःखितं मनः सुचक्षुषः प्रविचरतो महात्मनः॥', 'tatas tadā bahuvidhabhāvitātmanaḥ kṛtātmano janakasutāṃ suvartmanaḥ
apaśyato ''bhavad atiduḥkhitaṃ manaḥ sucakṣuṣaḥ pravicarato mahātmanaḥ', null, 5006017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 7 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-7-1', 1, 'Sundara Kanda, Sarga 7, Verse 1', 'तस्यालयवरिष्ठस्य मध्ये विपुलमायतम्।
ददर्श भवनश्रेष्ठं हनूमान्मारुतात्मजः॥', 'tasyālayavariṣṭhasya madhye vipulam āyatam
dadarśa bhavanaśreṣṭhaṃ hanūmān mārutātmajaḥ', null, 5007001),
('ramayana-5-7-2', 2, 'Sundara Kanda, Sarga 7, Verse 2', 'अर्धयोजनविस्तीर्णमायतं योजनं हि तत्।
भवनं राक्षसेन्द्रस्य बहुप्रासादसंकुलम्॥', 'ardhayojanavistīrṇam āyataṃ yojanaṃ hi tat
bhavanaṃ rākṣasendrasya bahuprāsādasaṃkulam', null, 5007002),
('ramayana-5-7-3', 3, 'Sundara Kanda, Sarga 7, Verse 3', 'मार्गमाणस्तु वैदेहीं सीतामायतलोचनाम्।
सर्वतः परिचक्राम हनूमानरिसूदनः॥', 'mārgamāṇas tu vaidehīṃ sītām āyatalocanām
sarvataḥ paricakrāma hanūmān arisūdanaḥ', null, 5007003),
('ramayana-5-7-4', 4, 'Sundara Kanda, Sarga 7, Verse 4', 'चतुर्विषाणैर्द्विरदैस्त्रिविषाणैस्तथैव च।
परिक्षिप्तमसंबाधं रक्ष्यमाणमुदायुधैः॥', 'caturviṣāṇair dviradais triviṣāṇais tathaiva ca
parikṣiptam asaṃbādhaṃ rakṣyamāṇam udāyudhaiḥ', null, 5007004),
('ramayana-5-7-5', 5, 'Sundara Kanda, Sarga 7, Verse 5', 'राक्षसीभिश्च पत्नीभी रावणस्य निवेशनम्।
आहृताभिश्च विक्रम्य राजकन्याभिरावृतम्॥', 'rākṣasībhiś ca patnībhī rāvaṇasya niveśanam
āhṛtābhiś ca vikramya rājakanyābhir āvṛtam', null, 5007005),
('ramayana-5-7-6', 6, 'Sundara Kanda, Sarga 7, Verse 6', 'तन्नक्रमकराकीर्णं तिमिंगिलझषाकुलम्।
वायुवेगसमाधूतं पन्नगैरिव सागरम्॥', 'tan nakramakarākīrṇaṃ timiṃgilajhaṣākulam
vāyuvegasamādhūtaṃ pannagair iva sāgaram', null, 5007006),
('ramayana-5-7-7', 7, 'Sundara Kanda, Sarga 7, Verse 7', 'या हि वैश्वरणे लक्ष्मीर्या चेन्द्रे हरिवाहने।
सा रावणगृहे सर्वा नित्यमेवानपायिनी॥', 'yā hi vaiśvaraṇe lakṣmīr yā cendre harivāhane
sā rāvaṇagṛhe sarvā nityam evānapāyinī', null, 5007007),
('ramayana-5-7-8', 8, 'Sundara Kanda, Sarga 7, Verse 8', 'या च राज्ञः कुबेरस्य यमस्य वरुणस्य च।
तादृशी तद्विशिष्टा वा ऋद्धी रक्षो गृहेष्विह॥', 'yā ca rājñaḥ kuberasya yamasya varuṇasya ca
tādṛśī tad viśiṣṭā vā ṛddhī rakṣo gṛheṣv iha', null, 5007008),
('ramayana-5-7-9', 9, 'Sundara Kanda, Sarga 7, Verse 9', 'तस्य हर्म्यस्य मध्यस्थं वेश्म चान्यत्सुनिर्मितम्।
बहुनिर्यूह संकीर्णं ददर्श पवनात्मजः॥', 'tasya harmyasya madhyasthaṃ veśma cānyat sunirmitam
bahuniryūha saṃkīrṇaṃ dadarśa pavanātmajaḥ', null, 5007009),
('ramayana-5-7-10', 10, 'Sundara Kanda, Sarga 7, Verse 10', 'ब्रह्मणोऽर्थे कृतं दिव्यं दिवि यद्विश्वकर्मणा।
विमानं पुष्पकं नाम सर्वरत्नविभूषितम्॥', 'brahmaṇo ''rthe kṛtaṃ divyaṃ divi yad viśvakarmaṇā
vimānaṃ puṣpakaṃ nāma sarvaratnavibhūṣitam', null, 5007010),
('ramayana-5-7-11', 11, 'Sundara Kanda, Sarga 7, Verse 11', 'परेण तपसा लेभे यत्कुबेरः पितामहात्।
कुबेरमोजसा जित्वा लेभे तद्राक्षसेश्वरः॥', 'pareṇa tapasā lebhe yat kuberaḥ pitāmahāt
kuberam ojasā jitvā lebhe tad rākṣaseśvaraḥ', null, 5007011),
('ramayana-5-7-12', 12, 'Sundara Kanda, Sarga 7, Verse 12', 'ईहा मृगसमायुक्तैः कार्यस्वरहिरण्मयैः।
सुकृतैराचितं स्तम्भैः प्रदीप्तमिव च श्रिया॥', 'īhā mṛgasamāyuktaiḥ kāryasvarahiraṇmayaiḥ
sukṛtair ācitaṃ stambhaiḥ pradīptam iva ca śriyā', null, 5007012),
('ramayana-5-7-13', 13, 'Sundara Kanda, Sarga 7, Verse 13', 'मेरुमन्दरसंकाशैरुल्लिखद्भिरिवाम्बरम्।
कूटागारैः शुभाकारैः सर्वतः समलंकृतम्॥', 'merumandarasaṃkāśair ullikhadbhir ivāmbaram
kūṭāgāraiḥ śubhākāraiḥ sarvataḥ samalaṃkṛtam', null, 5007013),
('ramayana-5-7-14', 14, 'Sundara Kanda, Sarga 7, Verse 14', 'ज्वलनार्कप्रतीकाशं सुकृतं विश्वकर्मणा।
हेमसोपानसंयुक्तं चारुप्रवरवेदिकम्॥', 'jvalanārkapratīkāśaṃ sukṛtaṃ viśvakarmaṇā
hemasopānasaṃyuktaṃ cārupravaravedikam', null, 5007014),
('ramayana-5-7-15', 15, 'Sundara Kanda, Sarga 7, Verse 15', 'जालवातायनैर्युक्तं काञ्चनैः स्थाटिकैरपि।
इन्द्रनीलमहानीलमणिप्रवरवेदिकम्।
विमानं पुष्पकं दिव्यमारुरोह महाकपिः॥', 'jālavātāyanair yuktaṃ kāñcanaiḥ sthāṭikair api
indranīlamahānīlamaṇipravaravedikam
vimānaṃ puṣpakaṃ divyam āruroha mahākapiḥ', null, 5007015),
('ramayana-5-7-16', 16, 'Sundara Kanda, Sarga 7, Verse 16', 'तत्रस्थः स तदा गन्धं पानभक्ष्यान्नसंभवम्।
दिव्यं संमूर्छितं जिघ्रन्रूपवन्तमिवानिलम्॥', 'tatrasthaḥ sa tadā gandhaṃ pānabhakṣyānnasaṃbhavam
divyaṃ saṃmūrchitaṃ jighran rūpavantam ivānilam', null, 5007016),
('ramayana-5-7-17', 17, 'Sundara Kanda, Sarga 7, Verse 17', 'स गन्धस्तं महासत्त्वं बन्धुर्बन्धुमिवोत्तमम्।
इत एहीत्युवाचेव तत्र यत्र स रावणः॥', 'sa gandhas taṃ mahāsattvaṃ bandhur bandhum ivottamam
ita ehīty uvāceva tatra yatra sa rāvaṇaḥ', null, 5007017),
('ramayana-5-7-18', 18, 'Sundara Kanda, Sarga 7, Verse 18', 'ततस्तां प्रस्थितः शालां ददर्श महतीं शुभाम्।
रावणस्य मनःकान्तां कान्तामिव वरस्त्रियम्॥', 'tatas tāṃ prasthitaḥ śālāṃ dadarśa mahatīṃ śubhām
rāvaṇasya manaḥkāntāṃ kāntām iva varastriyam', null, 5007018),
('ramayana-5-7-19', 19, 'Sundara Kanda, Sarga 7, Verse 19', 'मणिसोपानविकृतां हेमजालविराजिताम्।
स्फाटिकैरावृततलां दन्तान्तरितरूपिकाम्॥', 'maṇisopānavikṛtāṃ hemajālavirājitām
sphāṭikair āvṛtatalāṃ dantāntaritarūpikām', null, 5007019),
('ramayana-5-7-20', 20, 'Sundara Kanda, Sarga 7, Verse 20', 'मुक्ताभिश्च प्रवालैश्च रूप्यचामीकरैरपि।
विभूषितां मणिस्तम्भैः सुबहुस्तम्भभूषिताम्॥', 'muktābhiś ca pravālaiś ca rūpyacāmīkarair api
vibhūṣitāṃ maṇistambhaiḥ subahustambhabhūṣitām', null, 5007020),
('ramayana-5-7-21', 21, 'Sundara Kanda, Sarga 7, Verse 21', 'समैरृजुभिरत्युच्चैः समन्तात्सुविभूषितैः।
स्तम्भैः पक्षैरिवात्युच्चैर्दिवं संप्रस्थितामिव॥', 'samair ṛjubhir atyuccaiḥ samantāt suvibhūṣitaiḥ
stambhaiḥ pakṣair ivātyuccair divaṃ saṃprasthitām iva', null, 5007021),
('ramayana-5-7-22', 22, 'Sundara Kanda, Sarga 7, Verse 22', 'महत्या कुथयास्त्रीणं पृथिवीलक्षणाङ्कया।
पृथिवीमिव विस्तीर्णां सराष्ट्रगृहमालिनीम्॥', 'mahatyā kuthayāstrīṇaṃ pṛthivīlakṣaṇāṅkayā
pṛthivīm iva vistīrṇāṃ sarāṣṭragṛhamālinīm', null, 5007022),
('ramayana-5-7-23', 23, 'Sundara Kanda, Sarga 7, Verse 23', 'नादितां मत्तविहगैर्दिव्यगन्धाधिवासिताम्।
परार्ध्यास्तरणोपेतां रक्षोऽधिपनिषेविताम्॥', 'nāditāṃ mattavihagair divyagandhādhivāsitām
parārdhyāstaraṇopetāṃ rakṣo''dhipaniṣevitām', null, 5007023),
('ramayana-5-7-24', 24, 'Sundara Kanda, Sarga 7, Verse 24', 'धूम्रामगरुधूपेन विमलां हंसपाण्डुराम्।
चित्रां पुष्पोपहारेण कल्माषीमिव सुप्रभाम्॥', 'dhūmrām agarudhūpena vimalāṃ haṃsapāṇḍurām
citrāṃ puṣpopahāreṇa kalmāṣīm iva suprabhām', null, 5007024),
('ramayana-5-7-25', 25, 'Sundara Kanda, Sarga 7, Verse 25', 'मनःसंह्लादजननीं वर्णस्यापि प्रसादिनीम्।
तां शोकनाशिनीं दिव्यां श्रियः संजननीमिव॥', 'manaḥsaṃhlādajananīṃ varṇasyāpi prasādinīm
tāṃ śokanāśinīṃ divyāṃ śriyaḥ saṃjananīm iva', null, 5007025),
('ramayana-5-7-26', 26, 'Sundara Kanda, Sarga 7, Verse 26', 'इन्द्रियाणीन्द्रियार्थैस्तु पञ्च पञ्चभिरुत्तमैः।
तर्पयामास मातेव तदा रावणपालिता॥', 'indriyāṇīndriyārthais tu pañca pañcabhir uttamaiḥ
tarpayām āsa māteva tadā rāvaṇapālitā', null, 5007026),
('ramayana-5-7-27', 27, 'Sundara Kanda, Sarga 7, Verse 27', 'स्वर्गोऽयं देवलोकोऽयमिन्द्रस्येयं पुरी भवेत्।
सिद्धिर्वेयं परा हि स्यादित्यमन्यत मारुतिः॥', 'svargo ''yaṃ devaloko ''yam indrasyeyaṃ purī bhavet
siddhir veyaṃ parā hi syād ity amanyata mārutiḥ', null, 5007027),
('ramayana-5-7-28', 28, 'Sundara Kanda, Sarga 7, Verse 28', 'प्रध्यायत इवापश्यत्प्रदीपांस्तत्र काञ्चनान्।
धूर्तानिव महाधूर्तैर्देवनेन पराजितान्॥', 'pradhyāyata ivāpaśyat pradīpāṃs tatra kāñcanān
dhūrtān iva mahādhūrtair devanena parājitān', null, 5007028),
('ramayana-5-7-29', 29, 'Sundara Kanda, Sarga 7, Verse 29', 'दीपानां च प्रकाशेन तेजसा रावणस्य च।
अर्चिर्भिर्भूषणानां च प्रदीप्तेत्यभ्यमन्यत॥', 'dīpānāṃ ca prakāśena tejasā rāvaṇasya ca
arcirbhir bhūṣaṇānāṃ ca pradīptety abhyamanyata', null, 5007029),
('ramayana-5-7-30', 30, 'Sundara Kanda, Sarga 7, Verse 30', 'ततोऽपश्यत्कुथासीनं नानावर्णाम्बरस्रजम्।
सहस्रं वरनारीणां नानावेषविभूषितम्॥', 'tato ''paśyat kuthāsīnaṃ nānāvarṇāmbarasrajam
sahasraṃ varanārīṇāṃ nānāveṣavibhūṣitam', null, 5007030),
('ramayana-5-7-31', 31, 'Sundara Kanda, Sarga 7, Verse 31', 'परिवृत्तेऽर्धरात्रे तु पाननिद्रावशं गतम्।
क्रीडित्वोपरतं रात्रौ सुष्वाप बलवत्तदा॥', 'parivṛtte ''rdharātre tu pānanidrāvaśaṃ gatam
krīḍitvoparataṃ rātrau suṣvāpa balavat tadā', null, 5007031),
('ramayana-5-7-32', 32, 'Sundara Kanda, Sarga 7, Verse 32', 'तत्प्रसुप्तं विरुरुचे निःशब्दान्तरभूषणम्।
निःशब्दहंसभ्रमरं यथा पद्मवनं महत्॥', 'tat prasuptaṃ viruruce niḥśabdāntarabhūṣaṇam
niḥśabdahaṃsabhramaraṃ yathā padmavanaṃ mahat', null, 5007032),
('ramayana-5-7-33', 33, 'Sundara Kanda, Sarga 7, Verse 33', 'तासां संवृतदन्तानि मीलिताक्षाणि मारुतिः।
अपश्यत्पद्मगन्धीनि वदनानि सुयोषिताम्॥', 'tāsāṃ saṃvṛtadantāni mīlitākṣāṇi mārutiḥ
apaśyat padmagandhīni vadanāni suyoṣitām', null, 5007033),
('ramayana-5-7-34', 34, 'Sundara Kanda, Sarga 7, Verse 34', 'प्रबुद्धानीव पद्मानि तासां भूत्वा क्षपाक्षये।
पुनःसंवृतपत्राणि रात्राविव बभुस्तदा॥', 'prabuddhānīva padmāni tāsāṃ bhūtvā kṣapākṣaye
punaḥsaṃvṛtapatrāṇi rātrāv iva babhus tadā', null, 5007034),
('ramayana-5-7-35', 35, 'Sundara Kanda, Sarga 7, Verse 35', 'इमानि मुखपद्मानि नियतं मत्तषट्पदाः।
अम्बुजानीव फुल्लानि प्रार्थयन्ति पुनः पुनः॥', 'imāni mukhapadmāni niyataṃ mattaṣaṭpadāḥ
ambujānīva phullāni prārthayanti punaḥ punaḥ', null, 5007035),
('ramayana-5-7-36', 36, 'Sundara Kanda, Sarga 7, Verse 36', 'इति वामन्यत श्रीमानुपपत्त्या महाकपिः।
मेने हि गुणतस्तानि समानि सलिलोद्भवैः॥', 'iti vāmanyata śrīmān upapattyā mahākapiḥ
mene hi guṇatas tāni samāni salilodbhavaiḥ', null, 5007036),
('ramayana-5-7-37', 37, 'Sundara Kanda, Sarga 7, Verse 37', 'सा तस्य शुशुभे शाला ताभिः स्त्रीभिर्विराजिता।
शारदीव प्रसन्ना द्यौस्ताराभिरभिशोभिता॥', 'sā tasya śuśubhe śālā tābhiḥ strībhir virājitā
śāradīva prasannā dyaus tārābhir abhiśobhitā', null, 5007037),
('ramayana-5-7-38', 38, 'Sundara Kanda, Sarga 7, Verse 38', 'स च ताभिः परिवृतः शुशुभे राक्षसाधिपः।
यथा ह्युडुपतिः श्रीमांस्ताराभिरभिसंवृतः॥', 'sa ca tābhiḥ parivṛtaḥ śuśubhe rākṣasādhipaḥ
yathā hy uḍupatiḥ śrīmāṃs tārābhir abhisaṃvṛtaḥ', null, 5007038),
('ramayana-5-7-39', 39, 'Sundara Kanda, Sarga 7, Verse 39', 'याश्च्यवन्तेऽम्बरात्ताराः पुण्यशेषसमावृताः।
इमास्ताः संगताः कृत्स्ना इति मेने हरिस्तदा॥', 'yāś cyavante ''mbarāt tārāḥ puṇyaśeṣasamāvṛtāḥ
imās tāḥ saṃgatāḥ kṛtsnā iti mene haris tadā', null, 5007039),
('ramayana-5-7-40', 40, 'Sundara Kanda, Sarga 7, Verse 40', 'ताराणामिव सुव्यक्तं महतीनां शुभार्चिषाम्।
प्रभावर्णप्रसादाश्च विरेजुस्तत्र योषिताम्॥', 'tārāṇām iva suvyaktaṃ mahatīnāṃ śubhārciṣām
prabhāvarṇaprasādāś ca virejus tatra yoṣitām', null, 5007040),
('ramayana-5-7-41', 41, 'Sundara Kanda, Sarga 7, Verse 41', 'व्यावृत्तगुरुपीनस्रक्प्रकीर्णवरभूषणाः।
पानव्यायामकालेषु निद्रापहृतचेतसः॥', 'vyāvṛttagurupīnasrakprakīrṇavarabhūṣaṇāḥ
pānavyāyāmakāleṣu nidrāpahṛtacetasaḥ', null, 5007041),
('ramayana-5-7-42', 42, 'Sundara Kanda, Sarga 7, Verse 42', 'व्यावृत्ततिलकाः काश्चित्काश्चिदुद्भ्रान्तनूपुराः।
पार्श्वे गलितहाराश्च काश्चित्परमयोषितः॥', 'vyāvṛttatilakāḥ kāś cit kāś cid udbhrāntanūpurāḥ
pārśve galitahārāś ca kāś cit paramayoṣitaḥ', null, 5007042),
('ramayana-5-7-43', 43, 'Sundara Kanda, Sarga 7, Verse 43', 'मुखा हारवृताश्चान्याः काश्चित्प्रस्रस्तवाससः।
व्याविद्धरशना दामाः किशोर्य इव वाहिताः॥', 'mukhā hāravṛtāś cānyāḥ kāś cit prasrastavāsasaḥ
vyāviddharaśanā dāmāḥ kiśorya iva vāhitāḥ', null, 5007043),
('ramayana-5-7-44', 44, 'Sundara Kanda, Sarga 7, Verse 44', 'सुकुण्डलधराश्चान्या विच्छिन्नमृदितस्रजः।
गजेन्द्रमृदिताः फुल्ला लता इव महावने॥', 'sukuṇḍaladharāś cānyā vicchinnamṛditasrajaḥ
gajendramṛditāḥ phullā latā iva mahāvane', null, 5007044),
('ramayana-5-7-45', 45, 'Sundara Kanda, Sarga 7, Verse 45', 'चन्द्रांशुकिरणाभाश्च हाराः कासां चिदुत्कटाः।
हंसा इव बभुः सुप्ताः स्तनमध्येषु योषिताम्॥', 'candrāṃśukiraṇābhāś ca hārāḥ kāsāṃ cid utkaṭāḥ
haṃsā iva babhuḥ suptāḥ stanamadhyeṣu yoṣitām', null, 5007045),
('ramayana-5-7-46', 46, 'Sundara Kanda, Sarga 7, Verse 46', 'अपरासां च वैदूर्याः कादम्बा इव पक्षिणः।
हेमसूत्राणि चान्यासां चक्रवाका इवाभवन्॥', 'aparāsāṃ ca vaidūryāḥ kādambā iva pakṣiṇaḥ
hemasūtrāṇi cānyāsāṃ cakravākā ivābhavan', null, 5007046),
('ramayana-5-7-47', 47, 'Sundara Kanda, Sarga 7, Verse 47', 'हंसकारण्डवाकीर्णाश्चक्रवाकोपशोभिताः।
आपगा इव ता रेजुर्जघनैः पुलिनैरिव॥', 'haṃsakāraṇḍavākīrṇāś cakravākopaśobhitāḥ
āpagā iva tā rejur jaghanaiḥ pulinair iva', null, 5007047),
('ramayana-5-7-48', 48, 'Sundara Kanda, Sarga 7, Verse 48', 'किङ्किणीजालसंकाशास्ता हेमविपुलाम्बुजाः।
भावग्राहा यशस्तीराः सुप्ता नद्य इवाबभुः॥', 'kiṅkiṇījālasaṃkāśās tā hemavipulāmbujāḥ
bhāvagrāhā yaśastīrāḥ suptā nadya ivābabhuḥ', null, 5007048),
('ramayana-5-7-49', 49, 'Sundara Kanda, Sarga 7, Verse 49', 'मृदुष्वङ्गेषु कासां चित्कुचाग्रेषु च संस्थिताः।
बभूवुर्भूषणानीव शुभा भूषणराजयः॥', 'mṛduṣv aṅgeṣu kāsāṃ cit kucāgreṣu ca saṃsthitāḥ
babhūvur bhūṣaṇānīva śubhā bhūṣaṇarājayaḥ', null, 5007049),
('ramayana-5-7-50', 50, 'Sundara Kanda, Sarga 7, Verse 50', 'अंशुकान्ताश्च कासां चिन्मुखमारुतकम्पिताः।
उपर्युपरि वक्त्राणां व्याधूयन्ते पुनः पुनः॥', 'aṃśukāntāś ca kāsāṃ cin mukhamārutakampitāḥ
upary upari vaktrāṇāṃ vyādhūyante punaḥ punaḥ', null, 5007050),
('ramayana-5-7-51', 51, 'Sundara Kanda, Sarga 7, Verse 51', 'ताः पाताका इवोद्धूताः पत्नीनां रुचिरप्रभाः।
नानावर्णसुवर्णानां वक्त्रमूलेषु रेजिरे॥', 'tāḥ pātākā ivoddhūtāḥ patnīnāṃ ruciraprabhāḥ
nānāvarṇasuvarṇānāṃ vaktramūleṣu rejire', null, 5007051),
('ramayana-5-7-52', 52, 'Sundara Kanda, Sarga 7, Verse 52', 'ववल्गुश्चात्र कासां चित्कुण्डलानि शुभार्चिषाम्।
मुखमारुतसंसर्गान्मन्दं मन्दं सुयोषिताम्॥', 'vavalguś cātra kāsāṃ cit kuṇḍalāni śubhārciṣām
mukhamārutasaṃsargān mandaṃ mandaṃ suyoṣitām', null, 5007052),
('ramayana-5-7-53', 53, 'Sundara Kanda, Sarga 7, Verse 53', 'शर्करासवगन्धः स प्रकृत्या सुरभिः सुखः।
तासां वदननिःश्वासः सिषेवे रावणं तदा॥', 'śarkarāsavagandhaḥ sa prakṛtyā surabhiḥ sukhaḥ
tāsāṃ vadananiḥśvāsaḥ siṣeve rāvaṇaṃ tadā', null, 5007053),
('ramayana-5-7-54', 54, 'Sundara Kanda, Sarga 7, Verse 54', 'रावणाननशङ्काश्च काश्चिद्रावणयोषितः।
मुखानि स्म सपत्नीनामुपाजिघ्रन्पुनः पुनः॥', 'rāvaṇānanaśaṅkāś ca kāś cid rāvaṇayoṣitaḥ
mukhāni sma sapatnīnām upājighran punaḥ punaḥ', null, 5007054),
('ramayana-5-7-55', 55, 'Sundara Kanda, Sarga 7, Verse 55', 'अत्यर्थं सक्तमनसो रावणे ता वरस्त्रियः।
अस्वतन्त्राः सपत्नीनां प्रियमेवाचरंस्तदा॥', 'atyarthaṃ saktamanaso rāvaṇe tā varastriyaḥ
asvatantrāḥ sapatnīnāṃ priyam evācaraṃs tadā', null, 5007055),
('ramayana-5-7-56', 56, 'Sundara Kanda, Sarga 7, Verse 56', 'बाहूनुपनिधायान्याः पारिहार्य विभूषिताः।
अंशुकानि च रम्याणि प्रमदास्तत्र शिश्यिरे॥', 'bāhūn upanidhāyānyāḥ pārihārya vibhūṣitāḥ
aṃśukāni ca ramyāṇi pramadās tatra śiśyire', null, 5007056),
('ramayana-5-7-57', 57, 'Sundara Kanda, Sarga 7, Verse 57', 'अन्या वक्षसि चान्यस्यास्तस्याः का चित्पुनर्भुजम्।
अपरा त्वङ्कमन्यस्यास्तस्याश्चाप्यपरा भुजौ॥', 'anyā vakṣasi cānyasyās tasyāḥ kā cit punar bhujam
aparā tv aṅkam anyasyās tasyāś cāpy aparā bhujau', null, 5007057),
('ramayana-5-7-58', 58, 'Sundara Kanda, Sarga 7, Verse 58', 'ऊरुपार्श्वकटीपृष्ठमन्योन्यस्य समाश्रिताः।
परस्परनिविष्टाङ्ग्यो मदस्नेहवशानुगाः॥', 'ūrupārśvakaṭīpṛṣṭham anyonyasya samāśritāḥ
parasparaniviṣṭāṅgyo madasnehavaśānugāḥ', null, 5007058),
('ramayana-5-7-59', 59, 'Sundara Kanda, Sarga 7, Verse 59', 'अन्योन्यस्याङ्गसंस्पर्शात्प्रीयमाणाः सुमध्यमाः।
एकीकृतभुजाः सर्वाः सुषुपुस्तत्र योषितः॥', 'anyonyasyāṅgasaṃsparśāt prīyamāṇāḥ sumadhyamāḥ
ekīkṛtabhujāḥ sarvāḥ suṣupus tatra yoṣitaḥ', null, 5007059),
('ramayana-5-7-60', 60, 'Sundara Kanda, Sarga 7, Verse 60', 'अन्योन्यभुजसूत्रेण स्त्रीमालाग्रथिता हि सा।
मालेव ग्रथिता सूत्रे शुशुभे मत्तषट्पदा॥', 'anyonyabhujasūtreṇa strīmālāgrathitā hi sā
māleva grathitā sūtre śuśubhe mattaṣaṭpadā', null, 5007060),
('ramayana-5-7-61', 61, 'Sundara Kanda, Sarga 7, Verse 61', 'लतानां माधवे मासि फुल्लानां वायुसेवनात्।
अन्योन्यमालाग्रथितं संसक्तकुसुमोच्चयम्॥', 'latānāṃ mādhave māsi phullānāṃ vāyusevanāt
anyonyamālāgrathitaṃ saṃsaktakusumoccayam', null, 5007061),
('ramayana-5-7-62', 62, 'Sundara Kanda, Sarga 7, Verse 62', 'व्यतिवेष्टितसुस्कन्थमन्योन्यभ्रमराकुलम्।
आसीद्वनमिवोद्धूतं स्त्रीवनं रावणस्य तत्॥', 'vyativeṣṭitasuskantham anyonyabhramarākulam
āsīd vanam ivoddhūtaṃ strīvanaṃ rāvaṇasya tat', null, 5007062),
('ramayana-5-7-63', 63, 'Sundara Kanda, Sarga 7, Verse 63', 'उचितेष्वपि सुव्यक्तं न तासां योषितां तदा।
विवेकः शक्य आधातुं भूषणाङ्गाम्बरस्रजाम्॥', 'uciteṣv api suvyaktaṃ na tāsāṃ yoṣitāṃ tadā
vivekaḥ śakya ādhātuṃ bhūṣaṇāṅgāmbarasrajām', null, 5007063),
('ramayana-5-7-64', 64, 'Sundara Kanda, Sarga 7, Verse 64', 'रावणे सुखसंविष्टे ताः स्त्रियो विविधप्रभाः।
ज्वलन्तः काञ्चना दीपाः प्रेक्षन्तानिमिषा इव॥', 'rāvaṇe sukhasaṃviṣṭe tāḥ striyo vividhaprabhāḥ
jvalantaḥ kāñcanā dīpāḥ prekṣantānimiṣā iva', null, 5007064),
('ramayana-5-7-65', 65, 'Sundara Kanda, Sarga 7, Verse 65', 'राजर्षिपितृदैत्यानां गन्धर्वाणां च योषितः।
रक्षसां चाभवन्कन्यास्तस्य कामवशं गताः॥', 'rājarṣipitṛdaityānāṃ gandharvāṇāṃ ca yoṣitaḥ
rakṣasāṃ cābhavan kanyās tasya kāmavaśaṃ gatāḥ', null, 5007065),
('ramayana-5-7-66', 66, 'Sundara Kanda, Sarga 7, Verse 66', 'न तत्र का चित्प्रमदा प्रसह्य वीर्योपपन्नेन गुणेन लब्धा।
न चान्यकामापि न चान्यपूर्वा विना वरार्हां जनकात्मजां तु॥', 'na tatra kā cit pramadā prasahya vīryopapannena guṇena labdhā
na cānyakāmāpi na cānyapūrvā vinā varārhāṃ janakātmajāṃ tu', null, 5007066),
('ramayana-5-7-67', 67, 'Sundara Kanda, Sarga 7, Verse 67', 'न चाकुलीना न च हीनरूपा नादक्षिणा नानुपचार युक्ता।
भार्याभवत्तस्य न हीनसत्त्वा न चापि कान्तस्य न कामनीया॥', 'na cākulīnā na ca hīnarūpā nādakṣiṇā nānupacāra yuktā
bhāryābhavat tasya na hīnasattvā na cāpi kāntasya na kāmanīyā', null, 5007067),
('ramayana-5-7-68', 68, 'Sundara Kanda, Sarga 7, Verse 68', 'बभूव बुद्धिस्तु हरीश्वरस्य यदीदृशी राघवधर्मपत्नी।
इमा यथा राक्षसराजभार्याः सुजातमस्येति हि साधुबुद्धेः॥', 'babhūva buddhis tu harīśvarasya yadīdṛśī rāghavadharmapatnī
imā yathā rākṣasarājabhāryāḥ sujātam asyeti hi sādhubuddheḥ', null, 5007068),
('ramayana-5-7-69', 69, 'Sundara Kanda, Sarga 7, Verse 69', 'पुनश्च सोऽचिन्तयदार्तरूपो ध्रुवं विशिष्टा गुणतो हि सीता।
अथायमस्यां कृतवान्महात्मा लङ्केश्वरः कष्टमनार्यकर्म॥', 'punaś ca so ''cintayad ārtarūpo dhruvaṃ viśiṣṭā guṇato hi sītā
athāyam asyāṃ kṛtavān mahātmā laṅkeśvaraḥ kaṣṭam anāryakarma', null, 5007069)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 8 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-8-1', 1, 'Sundara Kanda, Sarga 8, Verse 1', 'तत्र दिव्योपमं मुख्यं स्फाटिकं रत्नभूषितम्।
अवेक्षमाणो हनुमान्ददर्श शयनासनम्॥', 'tatra divyopamaṃ mukhyaṃ sphāṭikaṃ ratnabhūṣitam
avekṣamāṇo hanumān dadarśa śayanāsanam', null, 5008001),
('ramayana-5-8-2', 2, 'Sundara Kanda, Sarga 8, Verse 2', 'तस्य चैकतमे देशे सोऽग्र्यमाल्यविभूषितम्।
ददर्श पाण्डुरं छत्रं ताराधिपतिसंनिभम्॥', 'tasya caikatame deśe so ''gryamālyavibhūṣitam
dadarśa pāṇḍuraṃ chatraṃ tārādhipatisaṃnibham', null, 5008002),
('ramayana-5-8-3', 3, 'Sundara Kanda, Sarga 8, Verse 3', 'बालव्यजनहस्ताभिर्वीज्यमानं समन्ततः।
गन्धैश्च विविधैर्जुष्टं वरधूपेन धूपितम्॥', 'bālavyajanahastābhir vījyamānaṃ samantataḥ
gandhaiś ca vividhair juṣṭaṃ varadhūpena dhūpitam', null, 5008003),
('ramayana-5-8-4', 4, 'Sundara Kanda, Sarga 8, Verse 4', 'परमास्तरणास्तीर्णमाविकाजिनसंवृतम्।
दामभिर्वरमाल्यानां समन्तादुपशोभितम्॥', 'paramāstaraṇāstīrṇam āvikājinasaṃvṛtam
dāmabhir varamālyānāṃ samantād upaśobhitam', null, 5008004),
('ramayana-5-8-5', 5, 'Sundara Kanda, Sarga 8, Verse 5', 'तस्मिञ्जीमूतसंकाशं प्रदीप्तोत्तमकुण्डलम्।
लोहिताक्षं महाबाहुं महारजतवाससं॥', 'tasmiñ jīmūtasaṃkāśaṃ pradīptottamakuṇḍalam
lohitākṣaṃ mahābāhuṃ mahārajatavāsasaṃ', null, 5008005),
('ramayana-5-8-6', 6, 'Sundara Kanda, Sarga 8, Verse 6', 'लोहितेनानुलिप्ताङ्गं चन्दनेन सुगन्धिना।
संध्यारक्तमिवाकाशे तोयदं सतडिद्गुणम्॥', 'lohitenānuliptāṅgaṃ candanena sugandhinā
saṃdhyāraktam ivākāśe toyadaṃ sataḍidguṇam', null, 5008006),
('ramayana-5-8-7', 7, 'Sundara Kanda, Sarga 8, Verse 7', 'वृतमाभरणैर्दिव्यैः सुरूपं कामरूपिणम्।
सवृक्षवनगुल्माढ्यं प्रसुप्तमिव मन्दरम्॥', 'vṛtam ābharaṇair divyaiḥ surūpaṃ kāmarūpiṇam
savṛkṣavanagulmāḍhyaṃ prasuptam iva mandaram', null, 5008007),
('ramayana-5-8-8', 8, 'Sundara Kanda, Sarga 8, Verse 8', 'क्रीडित्वोपरतं रात्रौ वराभरणभूषितम्।
प्रियं राक्षसकन्यानां राक्षसानां सुखावहम्॥', 'krīḍitvoparataṃ rātrau varābharaṇabhūṣitam
priyaṃ rākṣasakanyānāṃ rākṣasānāṃ sukhāvaham', null, 5008008),
('ramayana-5-8-9', 9, 'Sundara Kanda, Sarga 8, Verse 9', 'पीत्वाप्युपरतं चापि ददर्श स महाकपिः।
भास्करे शयने वीरं प्रसुप्तं राक्षसाधिपम्॥', 'pītvāpy uparataṃ cāpi dadarśa sa mahākapiḥ
bhāskare śayane vīraṃ prasuptaṃ rākṣasādhipam', null, 5008009),
('ramayana-5-8-10', 10, 'Sundara Kanda, Sarga 8, Verse 10', 'निःश्वसन्तं यथा नागं रावणं वानरोत्तमः।
आसाद्य परमोद्विग्नः सोऽपासर्पत्सुभीतवत्॥', 'niḥśvasantaṃ yathā nāgaṃ rāvaṇaṃ vānarottamaḥ
āsādya paramodvignaḥ so ''pāsarpat subhītavat', null, 5008010),
('ramayana-5-8-11', 11, 'Sundara Kanda, Sarga 8, Verse 11', 'अथारोहणमासाद्य वेदिकान्तरमाश्रितः।
सुप्तं राक्षसशार्दूलं प्रेक्षते स्म महाकपिः॥', 'athārohaṇam āsādya vedikāntaram āśritaḥ
suptaṃ rākṣasaśārdūlaṃ prekṣate sma mahākapiḥ', null, 5008011),
('ramayana-5-8-12', 12, 'Sundara Kanda, Sarga 8, Verse 12', 'शुशुभे राक्षसेन्द्रस्य स्वपतः शयनोत्तमम्।
गन्धहस्तिनि संविष्टे यथाप्रस्रवणं महत्॥', 'śuśubhe rākṣasendrasya svapataḥ śayanottamam
gandhahastini saṃviṣṭe yathāprasravaṇaṃ mahat', null, 5008012),
('ramayana-5-8-13', 13, 'Sundara Kanda, Sarga 8, Verse 13', 'काञ्चनाङ्गदनद्धौ च ददर्श स महात्मनः।
विक्षिप्तौ राक्षसेन्द्रस्य भुजाविन्द्रध्वजोपमौ॥', 'kāñcanāṅgadanaddhau ca dadarśa sa mahātmanaḥ
vikṣiptau rākṣasendrasya bhujāv indradhvajopamau', null, 5008013),
('ramayana-5-8-14', 14, 'Sundara Kanda, Sarga 8, Verse 14', 'ऐरावतविषाणाग्रैरापीडितकृतव्रणौ।
वज्रोल्लिखितपीनांसौ विष्णुचक्रपरिक्षितौ॥', 'airāvataviṣāṇāgrair āpīḍitakṛtavraṇau
vajrollikhitapīnāṃsau viṣṇucakraparikṣitau', null, 5008014),
('ramayana-5-8-15', 15, 'Sundara Kanda, Sarga 8, Verse 15', 'पीनौ समसुजातांसौ संगतौ बलसंयुतौ।
सुलक्षण नखाङ्गुष्ठौ स्वङ्गुलीतललक्षितौ॥', 'pīnau samasujātāṃsau saṃgatau balasaṃyutau
sulakṣaṇa nakhāṅguṣṭhau svaṅgulītalalakṣitau', null, 5008015),
('ramayana-5-8-16', 16, 'Sundara Kanda, Sarga 8, Verse 16', 'संहतौ परिघाकारौ वृत्तौ करिकरोपमौ।
विक्षिप्तौ शयने शुभ्रे पञ्चशीर्षाविवोरगौ॥', 'saṃhatau parighākārau vṛttau karikaropamau
vikṣiptau śayane śubhre pañcaśīrṣāv ivoragau', null, 5008016),
('ramayana-5-8-17', 17, 'Sundara Kanda, Sarga 8, Verse 17', 'शशक्षतजकल्पेन सुशीतेन सुगन्धिना।
चन्दनेन परार्ध्येन स्वनुलिप्तौ स्वलंकृतौ॥', 'śaśakṣatajakalpena suśītena sugandhinā
candanena parārdhyena svanuliptau svalaṃkṛtau', null, 5008017),
('ramayana-5-8-18', 18, 'Sundara Kanda, Sarga 8, Verse 18', 'उत्तमस्त्रीविमृदितौ गन्धोत्तमनिषेवितौ।
यक्षपन्नगगन्धर्वदेवदानवराविणौ॥', 'uttamastrīvimṛditau gandhottamaniṣevitau
yakṣapannagagandharvadevadānavarāviṇau', null, 5008018),
('ramayana-5-8-19', 19, 'Sundara Kanda, Sarga 8, Verse 19', 'ददर्श स कपिस्तस्य बाहू शयनसंस्थितौ।
मन्दरस्यान्तरे सुप्तौ महार्ही रुषिताविव॥', 'dadarśa sa kapis tasya bāhū śayanasaṃsthitau
mandarasyāntare suptau mahārhī ruṣitāv iva', null, 5008019),
('ramayana-5-8-20', 20, 'Sundara Kanda, Sarga 8, Verse 20', 'ताभ्यां स परिपूर्णाभ्यां भुजाभ्यां राक्षसाधिपः।
शुशुभेऽचलसंकाशः शृङ्गाभ्यामिव मन्दरः॥', 'tābhyāṃ sa paripūrṇābhyāṃ bhujābhyāṃ rākṣasādhipaḥ
śuśubhe ''calasaṃkāśaḥ śṛṅgābhyām iva mandaraḥ', null, 5008020),
('ramayana-5-8-21', 21, 'Sundara Kanda, Sarga 8, Verse 21', 'चूतपुंनागसुरभिर्बकुलोत्तमसंयुतः।
मृष्टान्नरससंयुक्तः पानगन्धपुरःसरः॥', 'cūtapuṃnāgasurabhir bakulottamasaṃyutaḥ
mṛṣṭānnarasasaṃyuktaḥ pānagandhapuraḥsaraḥ', null, 5008021),
('ramayana-5-8-22', 22, 'Sundara Kanda, Sarga 8, Verse 22', 'तस्य राक्षससिंहस्य निश्चक्राम मुखान्महान्।
शयानस्य विनिःश्वासः पूरयन्निव तद्गृहम्॥', 'tasya rākṣasasiṃhasya niścakrāma mukhān mahān
śayānasya viniḥśvāsaḥ pūrayann iva tad gṛham', null, 5008022),
('ramayana-5-8-23', 23, 'Sundara Kanda, Sarga 8, Verse 23', 'मुक्तामणिविचित्रेण काञ्चनेन विराजता।
मुकुटेनापवृत्तेन कुण्डलोज्ज्वलिताननम्॥', 'muktāmaṇivicitreṇa kāñcanena virājatā
mukuṭenāpavṛttena kuṇḍalojjvalitānanam', null, 5008023),
('ramayana-5-8-24', 24, 'Sundara Kanda, Sarga 8, Verse 24', 'रक्तचन्दनदिग्धेन तथा हारेण शोभिता।
पीनायतविशालेन वक्षसाभिविराजितम्॥', 'raktacandanadigdhena tathā hāreṇa śobhitā
pīnāyataviśālena vakṣasābhivirājitam', null, 5008024),
('ramayana-5-8-25', 25, 'Sundara Kanda, Sarga 8, Verse 25', 'पाण्डुरेणापविद्धेन क्षौमेण क्षतजेक्षणम्।
महार्हेण सुसंवीतं पीतेनोत्तमवाससा॥', 'pāṇḍureṇāpaviddhena kṣaumeṇa kṣatajekṣaṇam
mahārheṇa susaṃvītaṃ pītenottamavāsasā', null, 5008025),
('ramayana-5-8-26', 26, 'Sundara Kanda, Sarga 8, Verse 26', 'माषराशिप्रतीकाशं निःश्वसन्तं भुजङ्गवत्।
गाङ्गे महति तोयान्ते प्रसुतमिव कुञ्जरम्॥', 'māṣarāśipratīkāśaṃ niḥśvasantaṃ bhujaṅgavat
gāṅge mahati toyānte prasutamiva kuñjaram', null, 5008026),
('ramayana-5-8-27', 27, 'Sundara Kanda, Sarga 8, Verse 27', 'चतुर्भिः काञ्चनैर्दीपैर्दीप्यमानैश्चतुर्दिशम्।
प्रकाशीकृतसर्वाङ्गं मेघं विद्युद्गणैरिव॥', 'caturbhiḥ kāñcanair dīpair dīpyamānaiś caturdiśam
prakāśīkṛtasarvāṅgaṃ meghaṃ vidyudgaṇair iva', null, 5008027),
('ramayana-5-8-28', 28, 'Sundara Kanda, Sarga 8, Verse 28', 'पादमूलगताश्चापि ददर्श सुमहात्मनः।
पत्नीः स प्रियभार्यस्य तस्य रक्षःपतेर्गृहे॥', 'pādamūlagatāś cāpi dadarśa sumahātmanaḥ
patnīḥ sa priyabhāryasya tasya rakṣaḥpater gṛhe', null, 5008028),
('ramayana-5-8-29', 29, 'Sundara Kanda, Sarga 8, Verse 29', 'शशिप्रकाशवदना वरकुण्डलभूषिताः।
अम्लानमाल्याभरणा ददर्श हरियूथपः॥', 'śaśiprakāśavadanā varakuṇḍalabhūṣitāḥ
amlānamālyābharaṇā dadarśa hariyūthapaḥ', null, 5008029),
('ramayana-5-8-30', 30, 'Sundara Kanda, Sarga 8, Verse 30', 'नृत्तवादित्रकुशला राक्षसेन्द्रभुजाङ्कगाः।
वराभरणधारिण्यो निषन्ना ददृशे कपिः॥', 'nṛttavāditrakuśalā rākṣasendrabhujāṅkagāḥ
varābharaṇadhāriṇyo niṣannā dadṛśe kapiḥ', null, 5008030),
('ramayana-5-8-31', 31, 'Sundara Kanda, Sarga 8, Verse 31', 'वज्रवैदूर्यगर्भाणि श्रवणान्तेषु योषिताम्।
ददर्श तापनीयानि कुण्डलान्यङ्गदानि च॥', 'vajravaidūryagarbhāṇi śravaṇānteṣu yoṣitām
dadarśa tāpanīyāni kuṇḍalāny aṅgadāni ca', null, 5008031),
('ramayana-5-8-32', 32, 'Sundara Kanda, Sarga 8, Verse 32', 'तासां चन्द्रोपमैर्वक्त्रैः शुभैर्ललितकुण्डलैः।
विरराज विमानं तन्नभस्तारागणैरिव॥', 'tāsāṃ candropamair vaktraiḥ śubhair lalitakuṇḍalaiḥ
virarāja vimānaṃ tan nabhas tārāgaṇair iva', null, 5008032),
('ramayana-5-8-33', 33, 'Sundara Kanda, Sarga 8, Verse 33', 'मदव्यायामखिन्नास्ता राक्षसेन्द्रस्य योषितः।
तेषु तेष्ववकाशेषु प्रसुप्तास्तनुमध्यमाः॥', 'madavyāyāmakhinnās tā rākṣasendrasya yoṣitaḥ
teṣu teṣv avakāśeṣu prasuptās tanumadhyamāḥ', null, 5008033),
('ramayana-5-8-34', 34, 'Sundara Kanda, Sarga 8, Verse 34', 'का चिद्वीणां परिष्वज्य प्रसुप्ता संप्रकाशते।
महानदीप्रकीर्णेव नलिनी पोतमाश्रिता॥', 'kā cid vīṇāṃ pariṣvajya prasuptā saṃprakāśate
mahānadīprakīrṇeva nalinī potam āśritā', null, 5008034),
('ramayana-5-8-35', 35, 'Sundara Kanda, Sarga 8, Verse 35', 'अन्या कक्षगतेनैव मड्डुकेनासितेक्षणा।
प्रसुप्ता भामिनी भाति बालपुत्रेव वत्सला॥', 'anyā kakṣagatenaiva maḍḍukenāsitekṣaṇā
prasuptā bhāminī bhāti bālaputreva vatsalā', null, 5008035),
('ramayana-5-8-36', 36, 'Sundara Kanda, Sarga 8, Verse 36', 'पटहं चारुसर्वाङ्गी पीड्य शेते शुभस्तनी।
चिरस्य रमणं लब्ध्वा परिष्वज्येव कामिनी॥', 'paṭahaṃ cārusarvāṅgī pīḍya śete śubhastanī
cirasya ramaṇaṃ labdhvā pariṣvajyeva kāminī', null, 5008036),
('ramayana-5-8-37', 37, 'Sundara Kanda, Sarga 8, Verse 37', 'का चिदंशं परिष्वज्य सुप्ता कमललोचना।
निद्रावशमनुप्राप्ता सहकान्तेव भामिनी॥', 'kā cid aṃśaṃ pariṣvajya suptā kamalalocanā
nidrāvaśam anuprāptā sahakānteva bhāminī', null, 5008037),
('ramayana-5-8-38', 38, 'Sundara Kanda, Sarga 8, Verse 38', 'अन्या कनकसंकाशैर्मृदुपीनैर्मनोरमैः।
मृदङ्गं परिपीड्याङ्गैः प्रसुप्ता मत्तलोचना॥', 'anyā kanakasaṃkāśair mṛdupīnair manoramaiḥ
mṛdaṅgaṃ paripīḍyāṅgaiḥ prasuptā mattalocanā', null, 5008038),
('ramayana-5-8-39', 39, 'Sundara Kanda, Sarga 8, Verse 39', 'भुजपार्श्वान्तरस्थेन कक्षगेण कृशोदरी।
पणवेन सहानिन्द्या सुप्ता मदकृतश्रमा॥', 'bhujapārśvāntarasthena kakṣageṇa kṛśodarī
paṇavena sahānindyā suptā madakṛtaśramā', null, 5008039),
('ramayana-5-8-40', 40, 'Sundara Kanda, Sarga 8, Verse 40', 'डिण्डिमं परिगृह्यान्या तथैवासक्तडिण्डिमा।
प्रसुप्ता तरुणं वत्समुपगूह्येव भामिनी॥', 'ḍiṇḍimaṃ parigṛhyānyā tathaivāsaktaḍiṇḍimā
prasuptā taruṇaṃ vatsam upagūhyeva bhāminī', null, 5008040),
('ramayana-5-8-41', 41, 'Sundara Kanda, Sarga 8, Verse 41', 'का चिदाडम्बरं नारी भुजसंभोगपीडितम्।
कृत्वा कमलपत्राक्षी प्रसुप्ता मदमोहिता॥', 'kā cid āḍambaraṃ nārī bhujasaṃbhogapīḍitam
kṛtvā kamalapatrākṣī prasuptā madamohitā', null, 5008041),
('ramayana-5-8-42', 42, 'Sundara Kanda, Sarga 8, Verse 42', 'कलशीमपविद्ध्यान्या प्रसुप्ता भाति भामिनी।
वसन्ते पुष्पशबला मालेव परिमार्जिता॥', 'kalaśīm apaviddhyānyā prasuptā bhāti bhāminī
vasante puṣpaśabalā māleva parimārjitā', null, 5008042),
('ramayana-5-8-43', 43, 'Sundara Kanda, Sarga 8, Verse 43', 'पाणिभ्यां च कुचौ का चित्सुवर्णकलशोपमौ।
उपगूह्याबला सुप्ता निद्राबलपराजिता॥', 'pāṇibhyāṃ ca kucau kā cit suvarṇakalaśopamau
upagūhyābalā suptā nidrābalaparājitā', null, 5008043),
('ramayana-5-8-44', 44, 'Sundara Kanda, Sarga 8, Verse 44', 'अन्या कमलपत्राक्षी पूर्णेन्दुसदृशानना।
अन्यामालिङ्ग्य सुश्रोणी प्रसुप्ता मदविह्वला॥', 'anyā kamalapatrākṣī pūrṇendusadṛśānanā
anyām āliṅgya suśroṇī prasuptā madavihvalā', null, 5008044),
('ramayana-5-8-45', 45, 'Sundara Kanda, Sarga 8, Verse 45', 'आतोद्यानि विचित्राणि परिष्वज्य वरस्त्रियः।
निपीड्य च कुचैः सुप्ताः कामिन्यः कामुकानिव॥', 'ātodyāni vicitrāṇi pariṣvajya varastriyaḥ
nipīḍya ca kucaiḥ suptāḥ kāminyaḥ kāmukān iva', null, 5008045),
('ramayana-5-8-46', 46, 'Sundara Kanda, Sarga 8, Verse 46', 'तासामेकान्तविन्यस्ते शयानां शयने शुभे।
ददर्श रूपसंपन्नामपरां स कपिः स्त्रियम्॥', 'tāsām ekāntavinyaste śayānāṃ śayane śubhe
dadarśa rūpasaṃpannām aparāṃ sa kapiḥ striyam', null, 5008046),
('ramayana-5-8-47', 47, 'Sundara Kanda, Sarga 8, Verse 47', 'मुक्तामणिसमायुक्तैर्भूषणैः सुविभूषिताम्।
विभूषयन्तीमिव च स्वश्रिया भवनोत्तमम्॥', 'muktāmaṇisamāyuktair bhūṣaṇaiḥ suvibhūṣitām
vibhūṣayantīm iva ca svaśriyā bhavanottamam', null, 5008047),
('ramayana-5-8-48', 48, 'Sundara Kanda, Sarga 8, Verse 48', 'गौरीं कनकवर्णाभामिष्टामन्तःपुरेश्वरीम्।
कपिर्मन्दोदरीं तत्र शयानां चारुरूपिणीम्॥', 'gaurīṃ kanakavarṇābhām iṣṭām antaḥpureśvarīm
kapir mandodarīṃ tatra śayānāṃ cārurūpiṇīm', null, 5008048),
('ramayana-5-8-49', 49, 'Sundara Kanda, Sarga 8, Verse 49', 'स तां दृष्ट्वा महाबाहुर्भूषितां मारुतात्मजः।
तर्कयामास सीतेति रूपयौवनसंपदा।
हर्षेण महता युक्तो ननन्द हरियूथपः॥', 'sa tāṃ dṛṣṭvā mahābāhur bhūṣitāṃ mārutātmajaḥ
tarkayām āsa sīteti rūpayauvanasaṃpadā
harṣeṇa mahatā yukto nananda hariyūthapaḥ', null, 5008049),
('ramayana-5-8-50', 50, 'Sundara Kanda, Sarga 8, Verse 50', 'आस्फोटयामास चुचुम्ब पुच्छं ननन्द चिक्रीड जगौ जगाम।
स्तम्भानरोहन्निपपात भूमौ निदर्शयन्स्वां प्रकृतिं कपीनाम्॥', 'āsphoṭayām āsa cucumba pucchaṃ nananda cikrīḍa jagau jagāma
stambhān arohan nipapāta bhūmau nidarśayan svāṃ prakṛtiṃ kapīnām', null, 5008050)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 9 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-9-1', 1, 'Sundara Kanda, Sarga 9, Verse 1', 'अवधूय च तां बुद्धिं बभूवावस्थितस्तदा।
जगाम चापरां चिन्तां सीतां प्रति महाकपिः॥', 'avadhūya ca tāṃ buddhiṃ babhūvāvasthitas tadā
jagāma cāparāṃ cintāṃ sītāṃ prati mahākapiḥ', null, 5009001),
('ramayana-5-9-2', 2, 'Sundara Kanda, Sarga 9, Verse 2', 'न रामेण वियुक्ता सा स्वप्तुमर्हति भामिनी।
न भोक्तुं नाप्यलंकर्तुं न पानमुपसेवितुम्॥', 'na rāmeṇa viyuktā sā svaptum arhati bhāminī
na bhoktuṃ nāpy alaṃkartuṃ na pānam upasevitum', null, 5009002),
('ramayana-5-9-3', 3, 'Sundara Kanda, Sarga 9, Verse 3', 'नान्यं नरमुपस्थातुं सुराणामपि चेश्वरम्।
न हि रामसमः कश्चिद्विद्यते त्रिदशेष्वपि।
अन्येयमिति निश्चित्य पानभूमौ चचार सः॥', 'nānyaṃ naram upasthātuṃ surāṇām api ceśvaram
na hi rāmasamaḥ kaś cid vidyate tridaśeṣv api
anyeyam iti niścitya pānabhūmau cacāra saḥ', null, 5009003),
('ramayana-5-9-4', 4, 'Sundara Kanda, Sarga 9, Verse 4', 'क्रीडितेनापराः क्लान्ता गीतेन च तथा पराः।
नृत्तेन चापराः क्लान्ताः पानविप्रहतास्तथा॥', 'krīḍitenāparāḥ klāntā gītena ca tathā parāḥ
nṛttena cāparāḥ klāntāḥ pānaviprahatās tathā', null, 5009004),
('ramayana-5-9-5', 5, 'Sundara Kanda, Sarga 9, Verse 5', 'मुरजेषु मृदङ्गेषु पीठिकासु च संस्थिताः।
तथास्तरणमुख्य्येषु संविष्टाश्चापराः स्त्रियः॥', 'murajeṣu mṛdaṅgeṣu pīṭhikāsu ca saṃsthitāḥ
tathāstaraṇamukhyyeṣu saṃviṣṭāś cāparāḥ striyaḥ', null, 5009005),
('ramayana-5-9-6', 6, 'Sundara Kanda, Sarga 9, Verse 6', 'अङ्गनानां सहस्रेण भूषितेन विभूषणैः।
रूपसंलापशीलेन युक्तगीतार्थभाषिणा॥', 'aṅganānāṃ sahasreṇa bhūṣitena vibhūṣaṇaiḥ
rūpasaṃlāpaśīlena yuktagītārthabhāṣiṇā', null, 5009006),
('ramayana-5-9-7', 7, 'Sundara Kanda, Sarga 9, Verse 7', 'देशकालाभियुक्तेन युक्तवाक्याभिधायिना।
रताभिरतसंसुप्तं ददर्श हरियूथपः॥', 'deśakālābhiyuktena yuktavākyābhidhāyinā
ratābhiratasaṃsuptaṃ dadarśa hariyūthapaḥ', null, 5009007),
('ramayana-5-9-8', 8, 'Sundara Kanda, Sarga 9, Verse 8', 'तासां मध्ये महाबाहुः शुशुभे राक्षसेश्वरः।
गोष्ठे महति मुख्यानां गवां मध्ये यथा वृषः॥', 'tāsāṃ madhye mahābāhuḥ śuśubhe rākṣaseśvaraḥ
goṣṭhe mahati mukhyānāṃ gavāṃ madhye yathā vṛṣaḥ', null, 5009008),
('ramayana-5-9-9', 9, 'Sundara Kanda, Sarga 9, Verse 9', 'स राक्षसेन्द्रः शुशुभे ताभिः परिवृतः स्वयम्।
करेणुभिर्यथारण्यं परिकीर्णो महाद्विपः॥', 'sa rākṣasendraḥ śuśubhe tābhiḥ parivṛtaḥ svayam
kareṇubhir yathāraṇyaṃ parikīrṇo mahādvipaḥ', null, 5009009),
('ramayana-5-9-10', 10, 'Sundara Kanda, Sarga 9, Verse 10', 'सर्वकामैरुपेतां च पानभूमिं महात्मनः।
ददर्श कपिशार्दूलस्तस्य रक्षःपतेर्गृहे॥', 'sarvakāmair upetāṃ ca pānabhūmiṃ mahātmanaḥ
dadarśa kapiśārdūlas tasya rakṣaḥpater gṛhe', null, 5009010),
('ramayana-5-9-11', 11, 'Sundara Kanda, Sarga 9, Verse 11', 'मृगाणां महिषाणां च वराहाणां च भागशः।
तत्र न्यस्तानि मांसानि पानभूमौ ददर्श सः॥', 'mṛgāṇāṃ mahiṣāṇāṃ ca varāhāṇāṃ ca bhāgaśaḥ
tatra nyastāni māṃsāni pānabhūmau dadarśa saḥ', null, 5009011),
('ramayana-5-9-12', 12, 'Sundara Kanda, Sarga 9, Verse 12', 'रौक्मेषु च विशलेषु भाजनेष्वर्धभक्षितान्।
ददर्श कपिशार्दूल मयूरान्कुक्कुटांस्तथा॥', 'raukmeṣu ca viśaleṣu bhājaneṣv ardhabhakṣitān
dadarśa kapiśārdūla mayūrān kukkuṭāṃs tathā', null, 5009012),
('ramayana-5-9-13', 13, 'Sundara Kanda, Sarga 9, Verse 13', 'वराहवार्ध्राणसकान्दधिसौवर्चलायुतान्।
शल्यान्मृगमयूरांश्च हनूमानन्ववैक्षत॥', 'varāhavārdhrāṇasakān dadhisauvarcalāyutān
śalyān mṛgamayūrāṃś ca hanūmān anvavaikṣata', null, 5009013),
('ramayana-5-9-14', 14, 'Sundara Kanda, Sarga 9, Verse 14', 'कृकरान्विविधान्सिद्धांश्चकोरानर्धभक्षितान्।
महिषानेकशल्यांश्च छागांश्च कृतनिष्ठितान्।
लेख्यमुच्चावचं पेयं भोज्यानि विविधानि च॥', 'kṛkarān vividhān siddhāṃś cakorān ardhabhakṣitān
mahiṣān ekaśalyāṃś ca chāgāṃś ca kṛtaniṣṭhitān
lekhyam uccāvacaṃ peyaṃ bhojyāni vividhāni ca', null, 5009014),
('ramayana-5-9-15', 15, 'Sundara Kanda, Sarga 9, Verse 15', 'तथाम्ललवणोत्तंसैर्विविधै रागषाडवैः।
हार नूपुरकेयूरैरपविद्धैर्महाधनैः॥', 'tathāmlalavaṇottaṃsair vividhai rāgaṣāḍavaiḥ
hāra nūpurakeyūrair apaviddhair mahādhanaiḥ', null, 5009015),
('ramayana-5-9-16', 16, 'Sundara Kanda, Sarga 9, Verse 16', 'पानभाजनविक्षिप्तैः फलैश्च विविधैरपि।
कृतपुष्पोपहारा भूरधिकं पुष्यति श्रियम्॥', 'pānabhājanavikṣiptaiḥ phalaiś ca vividhair api
kṛtapuṣpopahārā bhūr adhikaṃ puṣyati śriyam', null, 5009016),
('ramayana-5-9-17', 17, 'Sundara Kanda, Sarga 9, Verse 17', 'तत्र तत्र च विन्यस्तैः सुश्लिष्टैः शयनासनैः।
पानभूमिर्विना वह्निं प्रदीप्तेवोपलक्ष्यते॥', 'tatra tatra ca vinyastaiḥ suśliṣṭaiḥ śayanāsanaiḥ
pānabhūmir vinā vahniṃ pradīptevopalakṣyate', null, 5009017),
('ramayana-5-9-18', 18, 'Sundara Kanda, Sarga 9, Verse 18', 'बहुप्रकारैर्विविधैर्वरसंस्कारसंस्कृतैः।
मांसैः कुशलसंयुक्तैः पानभूमिगतैः पृथक्॥', 'bahuprakārair vividhair varasaṃskārasaṃskṛtaiḥ
māṃsaiḥ kuśalasaṃyuktaiḥ pānabhūmigataiḥ pṛthak', null, 5009018),
('ramayana-5-9-19', 19, 'Sundara Kanda, Sarga 9, Verse 19', 'दिव्याः प्रसन्ना विविधाः सुराः कृतसुरा अपि।
शर्करासवमाध्वीकाः पुष्पासवफलासवाः।
वासचूर्णैश्च विविधैर्मृष्टास्तैस्तैः पृथक्पृथक्॥', 'divyāḥ prasannā vividhāḥ surāḥ kṛtasurā api
śarkarāsavamādhvīkāḥ puṣpāsavaphalāsavāḥ
vāsacūrṇaiś ca vividhair mṛṣṭās tais taiḥ pṛthakpṛthak', null, 5009019),
('ramayana-5-9-20', 20, 'Sundara Kanda, Sarga 9, Verse 20', 'संतता शुशुभे भूमिर्माल्यैश्च बहुसंस्थितैः।
हिरण्मयैश्च करकैर्भाजनैः स्फाटिकैरपि।
जाम्बूनदमयैश्चान्यैः करकैरभिसंवृता॥', 'saṃtatā śuśubhe bhūmir mālyaiś ca bahusaṃsthitaiḥ
hiraṇmayaiś ca karakair bhājanaiḥ sphāṭikair api
jāmbūnadamayaiś cānyaiḥ karakair abhisaṃvṛtā', null, 5009020),
('ramayana-5-9-21', 21, 'Sundara Kanda, Sarga 9, Verse 21', 'राजतेषु च कुम्भेषु जाम्बूनदमयेषु च।
पानश्रेष्ठं तदा भूरि कपिस्तत्र ददर्श ह॥', 'rājateṣu ca kumbheṣu jāmbūnadamayeṣu ca
pānaśreṣṭhaṃ tadā bhūri kapis tatra dadarśa ha', null, 5009021),
('ramayana-5-9-22', 22, 'Sundara Kanda, Sarga 9, Verse 22', 'सोऽपश्यच्छातकुम्भानि शीधोर्मणिमयानि च।
राजतानि च पूर्णानि भाजनानि महाकपिः॥', 'so ''paśyac chātakumbhāni śīdhor maṇimayāni ca
rājatāni ca pūrṇāni bhājanāni mahākapiḥ', null, 5009022),
('ramayana-5-9-23', 23, 'Sundara Kanda, Sarga 9, Verse 23', 'क्व चिदर्धावशेषाणि क्व चित्पीतानि सर्वशः।
क्व चिन्नैव प्रपीतानि पानानि स ददर्श ह॥', 'kva cid ardhāvaśeṣāṇi kva cit pītāni sarvaśaḥ
kva cin naiva prapītāni pānāni sa dadarśa ha', null, 5009023),
('ramayana-5-9-24', 24, 'Sundara Kanda, Sarga 9, Verse 24', 'क्व चिद्भक्ष्यांश्च विविधान्क्व चित्पानानि भागशः।
क्व चिदन्नावशेषाणि पश्यन्वै विचचार ह॥', 'kva cid bhakṣyāṃś ca vividhān kva cit pānāni bhāgaśaḥ
kva cid annāvaśeṣāṇi paśyan vai vicacāra ha', null, 5009024),
('ramayana-5-9-25', 25, 'Sundara Kanda, Sarga 9, Verse 25', 'क्व चित्प्रभिन्नैः करकैः क्व चिदालोडितैर्घटैः।
क्व चित्संपृक्तमाल्यानि जलानि च फलानि च॥', 'kva cit prabhinnaiḥ karakaiḥ kva cid āloḍitair ghaṭaiḥ
kva cit saṃpṛktamālyāni jalāni ca phalāni ca', null, 5009025),
('ramayana-5-9-26', 26, 'Sundara Kanda, Sarga 9, Verse 26', 'शयनान्यत्र नारीणां शून्यानि बहुधा पुनः।
परस्परं समाश्लिष्य काश्चित्सुप्ता वराङ्गनाः॥', 'śayanāny atra nārīṇāṃ śūnyāni bahudhā punaḥ
parasparaṃ samāśliṣya kāś cit suptā varāṅganāḥ', null, 5009026),
('ramayana-5-9-27', 27, 'Sundara Kanda, Sarga 9, Verse 27', 'का चिच्च वस्त्रमन्यस्या अपहृत्योपगुह्य च।
उपगम्याबला सुप्ता निद्राबलपराजिता॥', 'kā cic ca vastram anyasyā apahṛtyopaguhya ca
upagamyābalā suptā nidrābalaparājitā', null, 5009027),
('ramayana-5-9-28', 28, 'Sundara Kanda, Sarga 9, Verse 28', 'तासामुच्छ्वासवातेन वस्त्रं माल्यं च गात्रजम्।
नात्यर्थं स्पन्दते चित्रं प्राप्य मन्दमिवानिलम्॥', 'tāsām ucchvāsavātena vastraṃ mālyaṃ ca gātrajam
nātyarthaṃ spandate citraṃ prāpya mandam ivānilam', null, 5009028),
('ramayana-5-9-29', 29, 'Sundara Kanda, Sarga 9, Verse 29', 'चन्दनस्य च शीतस्य शीधोर्मधुरसस्य च।
विविधस्य च माल्यस्य पुष्पस्य विविधस्य च॥', 'candanasya ca śītasya śīdhor madhurasasya ca
vividhasya ca mālyasya puṣpasya vividhasya ca', null, 5009029),
('ramayana-5-9-30', 30, 'Sundara Kanda, Sarga 9, Verse 30', 'बहुधा मारुतस्तत्र गन्धं विविधमुद्वहन्।
स्नानानां चन्दनानां च धूपानां चैव मूर्छितः।
प्रववौ सुरभिर्गन्धो विमाने पुष्पके तदा॥', 'bahudhā mārutas tatra gandhaṃ vividham udvahan
snānānāṃ candanānāṃ ca dhūpānāṃ caiva mūrchitaḥ
pravavau surabhir gandho vimāne puṣpake tadā', null, 5009030),
('ramayana-5-9-31', 31, 'Sundara Kanda, Sarga 9, Verse 31', 'श्यामावदातास्तत्रान्याः काश्चित्कृष्णा वराङ्गनाः।
काश्चित्काञ्चनवर्णाङ्ग्यः प्रमदा राक्षसालये॥', 'śyāmāvadātās tatrānyāḥ kāś cit kṛṣṇā varāṅganāḥ
kāś cit kāñcanavarṇāṅgyaḥ pramadā rākṣasālaye', null, 5009031),
('ramayana-5-9-32', 32, 'Sundara Kanda, Sarga 9, Verse 32', 'तासां निद्रावशत्वाच्च मदनेन विमूर्छितम्।
पद्मिनीनां प्रसुप्तानां रूपमासीद्यथैव हि॥', 'tāsāṃ nidrāvaśatvāc ca madanena vimūrchitam
padminīnāṃ prasuptānāṃ rūpam āsīd yathaiva hi', null, 5009032),
('ramayana-5-9-33', 33, 'Sundara Kanda, Sarga 9, Verse 33', 'एवं सर्वमशेषेण रावणान्तःपुरं कपिः।
ददर्श सुमहातेजा न ददर्श च जानकीम्॥', 'evaṃ sarvam aśeṣeṇa rāvaṇāntaḥpuraṃ kapiḥ
dadarśa sumahātejā na dadarśa ca jānakīm', null, 5009033),
('ramayana-5-9-34', 34, 'Sundara Kanda, Sarga 9, Verse 34', 'निरीक्षमाणश्च ततस्ताः स्त्रियः स महाकपिः।
जगाम महतीं चिन्तां धर्मसाध्वसशङ्कितः॥', 'nirīkṣamāṇaś ca tatas tāḥ striyaḥ sa mahākapiḥ
jagāma mahatīṃ cintāṃ dharmasādhvasaśaṅkitaḥ', null, 5009034),
('ramayana-5-9-35', 35, 'Sundara Kanda, Sarga 9, Verse 35', 'परदारावरोधस्य प्रसुप्तस्य निरीक्षणम्।
इदं खलु ममात्यर्थं धर्मलोपं करिष्यति॥', 'paradārāvarodhasya prasuptasya nirīkṣaṇam
idaṃ khalu mamātyarthaṃ dharmalopaṃ kariṣyati', null, 5009035),
('ramayana-5-9-36', 36, 'Sundara Kanda, Sarga 9, Verse 36', 'न हि मे परदाराणां दृष्टिर्विषयवर्तिनी।
अयं चात्र मया दृष्टः परदारपरिग्रहः॥', 'na hi me paradārāṇāṃ dṛṣṭir viṣayavartinī
ayaṃ cātra mayā dṛṣṭaḥ paradāraparigrahaḥ', null, 5009036),
('ramayana-5-9-37', 37, 'Sundara Kanda, Sarga 9, Verse 37', 'तस्य प्रादुरभूच्चिन्तापुनरन्या मनस्विनः।
निश्चितैकान्तचित्तस्य कार्यनिश्चयदर्शिनी॥', 'tasya prādurabhūc cintāpunar anyā manasvinaḥ
niścitaikāntacittasya kāryaniścayadarśinī', null, 5009037),
('ramayana-5-9-38', 38, 'Sundara Kanda, Sarga 9, Verse 38', 'कामं दृष्ट्वा मया सर्वा विश्वस्ता रावणस्त्रियः।
न तु मे मनसः किं चिद्वैकृत्यमुपपद्यते॥', 'kāmaṃ dṛṣṭvā mayā sarvā viśvastā rāvaṇastriyaḥ
na tu me manasaḥ kiṃ cid vaikṛtyam upapadyate', null, 5009038),
('ramayana-5-9-39', 39, 'Sundara Kanda, Sarga 9, Verse 39', 'मनो हि हेतुः सर्वेषामिन्द्रियाणां प्रवर्तते।
शुभाशुभास्ववस्थासु तच्च मे सुव्यवस्थितम्॥', 'mano hi hetuḥ sarveṣām indriyāṇāṃ pravartate
śubhāśubhāsv avasthāsu tac ca me suvyavasthitam', null, 5009039),
('ramayana-5-9-40', 40, 'Sundara Kanda, Sarga 9, Verse 40', 'नान्यत्र हि मया शक्या वैदेही परिमार्गितुम्।
स्त्रियो हि स्त्रीषु दृश्यन्ते सदा संपरिमार्गणे॥', 'nānyatra hi mayā śakyā vaidehī parimārgitum
striyo hi strīṣu dṛśyante sadā saṃparimārgaṇe', null, 5009040),
('ramayana-5-9-41', 41, 'Sundara Kanda, Sarga 9, Verse 41', 'यस्य सत्त्वस्य या योनिस्तस्यां तत्परिमार्ग्यते।
न शक्यं प्रमदा नष्टा मृगीषु परिमार्गितुम्॥', 'yasya sattvasya yā yonis tasyāṃ tat parimārgyate
na śakyaṃ pramadā naṣṭā mṛgīṣu parimārgitum', null, 5009041),
('ramayana-5-9-42', 42, 'Sundara Kanda, Sarga 9, Verse 42', 'तदिदं मार्गितं तावच्छुद्धेन मनसा मया।
रावणान्तःपुरं सरं दृश्यते न च जानकी॥', 'tad idaṃ mārgitaṃ tāvac chuddhena manasā mayā
rāvaṇāntaḥpuraṃ saraṃ dṛśyate na ca jānakī', null, 5009042),
('ramayana-5-9-43', 43, 'Sundara Kanda, Sarga 9, Verse 43', 'देवगन्धर्वकन्याश्च नागकन्याश्च वीर्यवान्।
अवेक्षमाणो हनुमान्नैवापश्यत जानकीम्॥', 'devagandharvakanyāś ca nāgakanyāś ca vīryavān
avekṣamāṇo hanumān naivāpaśyata jānakīm', null, 5009043),
('ramayana-5-9-44', 44, 'Sundara Kanda, Sarga 9, Verse 44', 'तामपश्यन्कपिस्तत्र पश्यंश्चान्या वरस्त्रियः।
अपक्रम्य तदा वीरः प्रध्यातुमुपचक्रमे॥', 'tām apaśyan kapis tatra paśyaṃś cānyā varastriyaḥ
apakramya tadā vīraḥ pradhyātum upacakrame', null, 5009044)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 10 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-10-1', 1, 'Sundara Kanda, Sarga 10, Verse 1', 'स तस्य मध्ये भवनस्य वानरो लतागृहांश्चित्रगृहान्निशागृहान्।
जगाम सीतां प्रति दर्शनोत्सुको न चैव तां पश्यति चारुदर्शनाम्॥', 'sa tasya madhye bhavanasya vānaro latāgṛhāṃś citragṛhān niśāgṛhān
jagāma sītāṃ prati darśanotsuko na caiva tāṃ paśyati cārudarśanām', null, 5010001),
('ramayana-5-10-2', 2, 'Sundara Kanda, Sarga 10, Verse 2', 'स चिन्तयामास ततो महाकपिः प्रियामपश्यन्रघुनन्दनस्य ताम्।
ध्रुवं नु सीता म्रियते यथा न मे विचिन्वतो दर्शनमेति मैथिली॥', 'sa cintayām āsa tato mahākapiḥ priyām apaśyan raghunandanasya tām
dhruvaṃ nu sītā mriyate yathā na me vicinvato darśanam eti maithilī', null, 5010002),
('ramayana-5-10-3', 3, 'Sundara Kanda, Sarga 10, Verse 3', 'सा राक्षसानां प्रवरेण बाला स्वशीलसंरक्षण तत्परा सती।
अनेन नूनं प्रतिदुष्टकर्मणा हता भवेदार्यपथे परे स्थिता॥', 'sā rākṣasānāṃ pravareṇa bālā svaśīlasaṃrakṣaṇa tat parā satī
anena nūnaṃ pratiduṣṭakarmaṇā hatā bhaved āryapathe pare sthitā', null, 5010003),
('ramayana-5-10-4', 4, 'Sundara Kanda, Sarga 10, Verse 4', 'विरूपरूपा विकृता विवर्चसो महानना दीर्घविरूपदर्शनाः।
समीक्ष्य सा राक्षसराजयोषितो भयाद्विनष्टा जनकेश्वरात्मजा॥', 'virūparūpā vikṛtā vivarcaso mahānanā dīrghavirūpadarśanāḥ
samīkṣya sā rākṣasarājayoṣito bhayād vinaṣṭā janakeśvarātmajā', null, 5010004),
('ramayana-5-10-5', 5, 'Sundara Kanda, Sarga 10, Verse 5', 'सीतामदृष्ट्वा ह्यनवाप्य पौरुषं विहृत्य कालं सह वानरैश्चिरम्।
न मेऽस्ति सुग्रीवसमीपगा गतिः सुतीक्ष्णदण्डो बलवांश्च वानरः॥', 'sītām adṛṣṭvā hy anavāpya pauruṣaṃ vihṛtya kālaṃ saha vānaraiś ciram
na me ''sti sugrīvasamīpagā gatiḥ sutīkṣṇadaṇḍo balavāṃś ca vānaraḥ', null, 5010005),
('ramayana-5-10-6', 6, 'Sundara Kanda, Sarga 10, Verse 6', 'दृष्टमन्तःपुरं सर्वं दृष्ट्वा रावणयोषितः।
न सीता दृश्यते साध्वी वृथा जातो मम श्रमः॥', 'dṛṣṭam antaḥpuraṃ sarvaṃ dṛṣṭvā rāvaṇayoṣitaḥ
na sītā dṛśyate sādhvī vṛthā jāto mama śramaḥ', null, 5010006),
('ramayana-5-10-7', 7, 'Sundara Kanda, Sarga 10, Verse 7', 'किं नु मां वानराः सर्वे गतं वक्ष्यन्ति संगताः।
गत्वा तत्र त्वया वीर किं कृतं तद्वदस्व नः॥', 'kiṃ nu māṃ vānarāḥ sarve gataṃ vakṣyanti saṃgatāḥ
gatvā tatra tvayā vīra kiṃ kṛtaṃ tad vadasva naḥ', null, 5010007),
('ramayana-5-10-8', 8, 'Sundara Kanda, Sarga 10, Verse 8', 'अदृष्ट्वा किं प्रवक्ष्यामि तामहं जनकात्मजाम्।
ध्रुवं प्रायमुपेष्यन्ति कालस्य व्यतिवर्तने॥', 'adṛṣṭvā kiṃ pravakṣyāmi tām ahaṃ janakātmajām
dhruvaṃ prāyam upeṣyanti kālasya vyativartane', null, 5010008),
('ramayana-5-10-9', 9, 'Sundara Kanda, Sarga 10, Verse 9', 'किं वा वक्ष्यति वृद्धश्च जाम्बवानङ्गदश्च सः।
गतं पारं समुद्रस्य वानराश्च समागताः॥', 'kiṃ vā vakṣyati vṛddhaś ca jāmbavān aṅgadaś ca saḥ
gataṃ pāraṃ samudrasya vānarāś ca samāgatāḥ', null, 5010009),
('ramayana-5-10-10', 10, 'Sundara Kanda, Sarga 10, Verse 10', 'अनिर्वेदः श्रियो मूलमनिर्वेदः परं सुखम्।
भूयस्तावद्विचेष्यामि न यत्र विचयः कृतः॥', 'anirvedaḥ śriyo mūlam anirvedaḥ paraṃ sukham
bhūyas tāvad viceṣyāmi na yatra vicayaḥ kṛtaḥ', null, 5010010),
('ramayana-5-10-11', 11, 'Sundara Kanda, Sarga 10, Verse 11', 'अनिर्वेदो हि सततं सर्वार्थेषु प्रवर्तकः।
करोति सफलं जन्तोः कर्म यच्च करोति सः॥', 'anirvedo hi satataṃ sarvārtheṣu pravartakaḥ
karoti saphalaṃ jantoḥ karma yac ca karoti saḥ', null, 5010011),
('ramayana-5-10-12', 12, 'Sundara Kanda, Sarga 10, Verse 12', 'तस्मादनिर्वेद कृतं यत्नं चेष्टेऽहमुत्तमम्।
अदृष्टांश्च विचेष्यामि देशान्रावणपालितान्॥', 'tasmād anirveda kṛtaṃ yatnaṃ ceṣṭe ''ham uttamam
adṛṣṭāṃś ca viceṣyāmi deśān rāvaṇapālitān', null, 5010012),
('ramayana-5-10-13', 13, 'Sundara Kanda, Sarga 10, Verse 13', 'आपानशालाविचितास्तथा पुष्पगृहाणि च।
चित्रशालाश्च विचिता भूयः क्रीडागृहाणि च॥', 'āpānaśālāvicitās tathā puṣpagṛhāṇi ca
citraśālāś ca vicitā bhūyaḥ krīḍāgṛhāṇi ca', null, 5010013),
('ramayana-5-10-14', 14, 'Sundara Kanda, Sarga 10, Verse 14', 'निष्कुटान्तररथ्याश्च विमानानि च सर्वशः।
इति संचिन्त्य भूयोऽपि विचेतुमुपचक्रमे॥', 'niṣkuṭāntararathyāś ca vimānāni ca sarvaśaḥ
iti saṃcintya bhūyo ''pi vicetum upacakrame', null, 5010014),
('ramayana-5-10-15', 15, 'Sundara Kanda, Sarga 10, Verse 15', 'भूमीगृहांश्चैत्यगृहान्गृहातिगृहकानपि।
उत्पतन्निपतंश्चापि तिष्ठन्गच्छन्पुनः क्व चित्॥', 'bhūmīgṛhāṃś caityagṛhān gṛhātigṛhakān api
utpatan nipataṃś cāpi tiṣṭhan gacchan punaḥ kva cit', null, 5010015),
('ramayana-5-10-16', 16, 'Sundara Kanda, Sarga 10, Verse 16', 'अपावृण्वंश्च द्वाराणि कपाटान्यवघट्टयन्।
प्रविशन्निष्पतंश्चापि प्रपतन्नुत्पतन्नपि।
सर्वमप्यवकाशं स विचचार महाकपिः॥', 'apāvṛṇvaṃś ca dvārāṇi kapāṭāny avaghaṭṭayan
praviśan niṣpataṃś cāpi prapatann utpatann api
sarvam apy avakāśaṃ sa vicacāra mahākapiḥ', null, 5010016),
('ramayana-5-10-17', 17, 'Sundara Kanda, Sarga 10, Verse 17', 'चतुरङ्गुलमात्रोऽपि नावकाशः स विद्यते।
रावणान्तःपुरे तस्मिन्यं कपिर्न जगाम सः॥', 'caturaṅgulamātro ''pi nāvakāśaḥ sa vidyate
rāvaṇāntaḥpure tasmin yaṃ kapir na jagāma saḥ', null, 5010017),
('ramayana-5-10-18', 18, 'Sundara Kanda, Sarga 10, Verse 18', 'प्राकरान्तररथ्याश्च वेदिकश्चैत्यसंश्रयाः।
श्वभ्राश्च पुष्करिण्यश्च सर्वं तेनावलोकितम्॥', 'prākarāntararathyāś ca vedikaś caityasaṃśrayāḥ
śvabhrāś ca puṣkariṇyaś ca sarvaṃ tenāvalokitam', null, 5010018),
('ramayana-5-10-19', 19, 'Sundara Kanda, Sarga 10, Verse 19', 'राक्षस्यो विविधाकारा विरूपा विकृतास्तथा।
दृष्टा हनूमता तत्र न तु सा जनकात्मजा॥', 'rākṣasyo vividhākārā virūpā vikṛtās tathā
dṛṣṭā hanūmatā tatra na tu sā janakātmajā', null, 5010019),
('ramayana-5-10-20', 20, 'Sundara Kanda, Sarga 10, Verse 20', 'रूपेणाप्रतिमा लोके वरा विद्याधर स्त्रियः।
दृटा हनूमता तत्र न तु राघवनन्दिनी॥', 'rūpeṇāpratimā loke varā vidyādhara striyaḥ
dṛṭā hanūmatā tatra na tu rāghavanandinī', null, 5010020),
('ramayana-5-10-21', 21, 'Sundara Kanda, Sarga 10, Verse 21', 'नागकन्या वरारोहाः पूर्णचन्द्रनिभाननाः।
दृष्टा हनूमता तत्र न तु सीता सुमध्यमा॥', 'nāgakanyā varārohāḥ pūrṇacandranibhānanāḥ
dṛṣṭā hanūmatā tatra na tu sītā sumadhyamā', null, 5010021),
('ramayana-5-10-22', 22, 'Sundara Kanda, Sarga 10, Verse 22', 'प्रमथ्य राक्षसेन्द्रेण नागकन्या बलाद्धृताः।
दृष्टा हनूमता तत्र न सा जनकनन्दिनी॥', 'pramathya rākṣasendreṇa nāgakanyā balād dhṛtāḥ
dṛṣṭā hanūmatā tatra na sā janakanandinī', null, 5010022),
('ramayana-5-10-23', 23, 'Sundara Kanda, Sarga 10, Verse 23', 'सोऽपश्यंस्तां महाबाहुः पश्यंश्चान्या वरस्त्रियः।
विषसाद महाबाहुर्हनूमान्मारुतात्मजः॥', 'so ''paśyaṃs tāṃ mahābāhuḥ paśyaṃś cānyā varastriyaḥ
viṣasāda mahābāhur hanūmān mārutātmajaḥ', null, 5010023),
('ramayana-5-10-24', 24, 'Sundara Kanda, Sarga 10, Verse 24', 'उद्योगं वानरेन्द्राणं प्लवनं सागरस्य च।
व्यर्थं वीक्ष्यानिलसुतश्चिन्तां पुनरुपागमत्॥', 'udyogaṃ vānarendrāṇaṃ plavanaṃ sāgarasya ca
vyarthaṃ vīkṣyānilasutaś cintāṃ punar upāgamat', null, 5010024),
('ramayana-5-10-25', 25, 'Sundara Kanda, Sarga 10, Verse 25', 'अवतीर्य विमानाच्च हनूमान्मारुतात्मजः।
चिन्तामुपजगामाथ शोकोपहतचेतनः॥', 'avatīrya vimānāc ca hanūmān mārutātmajaḥ
cintām upajagāmātha śokopahatacetanaḥ', null, 5010025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 11 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-11-1', 1, 'Sundara Kanda, Sarga 11, Verse 1', 'विमानात्तु सुसंक्रम्य प्राकारं हरियूथपः।
हनूमान्वेगवानासीद्यथा विद्युद्घनान्तरे॥', 'vimānāt tu susaṃkramya prākāraṃ hariyūthapaḥ
hanūmān vegavān āsīd yathā vidyudghanāntare', null, 5011001),
('ramayana-5-11-2', 2, 'Sundara Kanda, Sarga 11, Verse 2', 'संपरिक्रम्य हनुमान्रावणस्य निवेशनान्।
अदृष्ट्वा जानकीं सीतामब्रवीद्वचनं कपिः॥', 'saṃparikramya hanumān rāvaṇasya niveśanān
adṛṣṭvā jānakīṃ sītām abravīd vacanaṃ kapiḥ', null, 5011002),
('ramayana-5-11-3', 3, 'Sundara Kanda, Sarga 11, Verse 3', 'भूयिष्ठं लोडिता लङ्का रामस्य चरता प्रियम्।
न हि पश्यामि वैदेहीं सीतां सर्वाङ्गशोभनाम्॥', 'bhūyiṣṭhaṃ loḍitā laṅkā rāmasya caratā priyam
na hi paśyāmi vaidehīṃ sītāṃ sarvāṅgaśobhanām', null, 5011003),
('ramayana-5-11-4', 4, 'Sundara Kanda, Sarga 11, Verse 4', 'पल्वलानि तटाकानि सरांसि सरितस्तथा।
नद्योऽनूपवनान्ताश्च दुर्गाश्च धरणीधराः।
लोडिता वसुधा सर्वा न च पश्यामि जानकीम्॥', 'palvalāni taṭākāni sarāṃsi saritas tathā
nadyo ''nūpavanāntāś ca durgāś ca dharaṇīdharāḥ
loḍitā vasudhā sarvā na ca paśyāmi jānakīm', null, 5011004),
('ramayana-5-11-5', 5, 'Sundara Kanda, Sarga 11, Verse 5', 'इह संपातिना सीता रावणस्य निवेशने।
आख्याता गृध्रराजेन न च पश्यामि तामहम्॥', 'iha saṃpātinā sītā rāvaṇasya niveśane
ākhyātā gṛdhrarājena na ca paśyāmi tām aham', null, 5011005),
('ramayana-5-11-6', 6, 'Sundara Kanda, Sarga 11, Verse 6', 'किं नु सीताथ वैदेही मैथिली जनकात्मजा।
उपतिष्ठेत विवशा रावणं दुष्टचारिणम्॥', 'kiṃ nu sītātha vaidehī maithilī janakātmajā
upatiṣṭheta vivaśā rāvaṇaṃ duṣṭacāriṇam', null, 5011006),
('ramayana-5-11-7', 7, 'Sundara Kanda, Sarga 11, Verse 7', 'क्षिप्रमुत्पततो मन्ये सीतामादाय रक्षसः।
बिभ्यतो रामबाणानामन्तरा पतिता भवेत्॥', 'kṣipram utpatato manye sītām ādāya rakṣasaḥ
bibhyato rāmabāṇānām antarā patitā bhavet', null, 5011007),
('ramayana-5-11-8', 8, 'Sundara Kanda, Sarga 11, Verse 8', 'अथ वा ह्रियमाणायाः पथि सिद्धनिषेविते।
मन्ये पतितमार्याया हृदयं प्रेक्ष्य सागरम्॥', 'atha vā hriyamāṇāyāḥ pathi siddhaniṣevite
manye patitam āryāyā hṛdayaṃ prekṣya sāgaram', null, 5011008),
('ramayana-5-11-9', 9, 'Sundara Kanda, Sarga 11, Verse 9', 'रावणस्योरुवेगेन भुजाभ्यां पीडितेन च।
तया मन्ये विशालाक्ष्या त्यक्तं जीवितमार्यया॥', 'rāvaṇasyoruvegena bhujābhyāṃ pīḍitena ca
tayā manye viśālākṣyā tyaktaṃ jīvitam āryayā', null, 5011009),
('ramayana-5-11-10', 10, 'Sundara Kanda, Sarga 11, Verse 10', 'उपर्युपरि वा नूनं सागरं क्रमतस्तदा।
विवेष्टमाना पतिता समुद्रे जनकात्मजा॥', 'upary upari vā nūnaṃ sāgaraṃ kramatas tadā
viveṣṭamānā patitā samudre janakātmajā', null, 5011010),
('ramayana-5-11-11', 11, 'Sundara Kanda, Sarga 11, Verse 11', 'आहो क्षुद्रेण चानेन रक्षन्ती शीलमात्मनः।
अबन्धुर्भक्षिता सीता रावणेन तपस्विनी॥', 'āho kṣudreṇa cānena rakṣantī śīlam ātmanaḥ
abandhur bhakṣitā sītā rāvaṇena tapasvinī', null, 5011011),
('ramayana-5-11-12', 12, 'Sundara Kanda, Sarga 11, Verse 12', 'अथ वा राक्षसेन्द्रस्य पत्नीभिरसितेक्षणा।
अदुष्टा दुष्टभावाभिर्भक्षिता सा भविष्यति॥', 'atha vā rākṣasendrasya patnībhir asitekṣaṇā
aduṣṭā duṣṭabhāvābhir bhakṣitā sā bhaviṣyati', null, 5011012),
('ramayana-5-11-13', 13, 'Sundara Kanda, Sarga 11, Verse 13', 'संपूर्णचन्द्रप्रतिमं पद्मपत्रनिभेक्षणम्।
रामस्य ध्यायती वक्त्रं पञ्चत्वं कृपणा गता॥', 'saṃpūrṇacandrapratimaṃ padmapatranibhekṣaṇam
rāmasya dhyāyatī vaktraṃ pañcatvaṃ kṛpaṇā gatā', null, 5011013),
('ramayana-5-11-14', 14, 'Sundara Kanda, Sarga 11, Verse 14', 'हा राम लक्ष्मणेत्येव हायोध्येति च मैथिली।
विलप्य बहु वैदेही न्यस्तदेहा भविष्यति॥', 'hā rāma lakṣmaṇety eva hāyodhyeti ca maithilī
vilapya bahu vaidehī nyastadehā bhaviṣyati', null, 5011014),
('ramayana-5-11-15', 15, 'Sundara Kanda, Sarga 11, Verse 15', 'अथ वा निहिता मन्ये रावणस्य निवेशने।
नूनं लालप्यते मन्दं पञ्जरस्थेव शारिका॥', 'atha vā nihitā manye rāvaṇasya niveśane
nūnaṃ lālapyate mandaṃ pañjarastheva śārikā', null, 5011015),
('ramayana-5-11-16', 16, 'Sundara Kanda, Sarga 11, Verse 16', 'जनकस्य कुले जाता रामपत्नी सुमध्यमा।
कथमुत्पलपत्राक्षी रावणस्य वशं व्रजेत्॥', 'janakasya kule jātā rāmapatnī sumadhyamā
katham utpalapatrākṣī rāvaṇasya vaśaṃ vrajet', null, 5011016),
('ramayana-5-11-17', 17, 'Sundara Kanda, Sarga 11, Verse 17', 'विनष्टा वा प्रनष्टा वा मृता वा जनकात्मजा।
रामस्य प्रियभार्यस्य न निवेदयितुं क्षमम्॥', 'vinaṣṭā vā pranaṣṭā vā mṛtā vā janakātmajā
rāmasya priyabhāryasya na nivedayituṃ kṣamam', null, 5011017),
('ramayana-5-11-18', 18, 'Sundara Kanda, Sarga 11, Verse 18', 'निवेद्यमाने दोषः स्याद्दोषः स्यादनिवेदने।
कथं नु खलु कर्तव्यं विषमं प्रतिभाति मे॥', 'nivedyamāne doṣaḥ syād doṣaḥ syād anivedane
kathaṃ nu khalu kartavyaṃ viṣamaṃ pratibhāti me', null, 5011018),
('ramayana-5-11-19', 19, 'Sundara Kanda, Sarga 11, Verse 19', 'अस्मिन्नेवंगते कर्ये प्राप्तकालं क्षमं च किम्।
भवेदिति मतिं भूयो हनुमान्प्रविचारयन्॥', 'asminn evaṃgate karye prāptakālaṃ kṣamaṃ ca kim
bhaved iti matiṃ bhūyo hanumān pravicārayan', null, 5011019),
('ramayana-5-11-20', 20, 'Sundara Kanda, Sarga 11, Verse 20', 'यदि सीतामदृष्ट्वाहं वानरेन्द्रपुरीमितः।
गमिष्यामि ततः को मे पुरुषार्थो भविष्यति॥', 'yadi sītām adṛṣṭvāhaṃ vānarendrapurīm itaḥ
gamiṣyāmi tataḥ ko me puruṣārtho bhaviṣyati', null, 5011020),
('ramayana-5-11-21', 21, 'Sundara Kanda, Sarga 11, Verse 21', 'ममेदं लङ्घनं व्यर्थं सागरस्य भविष्यति।
प्रवेशश्चिव लङ्काया राक्षसानां च दर्शनम्॥', 'mamedaṃ laṅghanaṃ vyarthaṃ sāgarasya bhaviṣyati
praveśaś civa laṅkāyā rākṣasānāṃ ca darśanam', null, 5011021),
('ramayana-5-11-22', 22, 'Sundara Kanda, Sarga 11, Verse 22', 'किं वा वक्ष्यति सुग्रीवो हरयो व समागताः।
किष्किन्धां समनुप्राप्तौ तौ वा दशरथात्मजौ॥', 'kiṃ vā vakṣyati sugrīvo harayo va samāgatāḥ
kiṣkindhāṃ samanuprāptau tau vā daśarathātmajau', null, 5011022),
('ramayana-5-11-23', 23, 'Sundara Kanda, Sarga 11, Verse 23', 'गत्वा तु यदि काकुत्स्थं वक्ष्यामि परमप्रियम्।
न दृष्टेति मया सीता ततस्त्यक्ष्यन्ति जीवितम्॥', 'gatvā tu yadi kākutsthaṃ vakṣyāmi param apriyam
na dṛṣṭeti mayā sītā tatas tyakṣyanti jīvitam', null, 5011023),
('ramayana-5-11-24', 24, 'Sundara Kanda, Sarga 11, Verse 24', 'परुषं दारुणं क्रूरं तीक्ष्णमिन्द्रियतापनम्।
सीतानिमित्तं दुर्वाक्यं श्रुत्वा स न भविष्यति॥', 'paruṣaṃ dāruṇaṃ krūraṃ tīkṣṇam indriyatāpanam
sītānimittaṃ durvākyaṃ śrutvā sa na bhaviṣyati', null, 5011024),
('ramayana-5-11-25', 25, 'Sundara Kanda, Sarga 11, Verse 25', 'तं तु कृच्छ्रगतं दृष्ट्वा पञ्चत्वगतमानसं।
भृशानुरक्तो मेधावी न भविष्यति लक्ष्मणः॥', 'taṃ tu kṛcchragataṃ dṛṣṭvā pañcatvagatamānasaṃ
bhṛśānurakto medhāvī na bhaviṣyati lakṣmaṇaḥ', null, 5011025),
('ramayana-5-11-26', 26, 'Sundara Kanda, Sarga 11, Verse 26', 'विनष्टौ भ्रातरौ श्रुत्वा भरतोऽपि मरिष्यति।
भरतं च मृतं दृष्ट्वा शत्रुघ्नो न भविष्यति॥', 'vinaṣṭau bhrātarau śrutvā bharato ''pi mariṣyati
bharataṃ ca mṛtaṃ dṛṣṭvā śatrughno na bhaviṣyati', null, 5011026),
('ramayana-5-11-27', 27, 'Sundara Kanda, Sarga 11, Verse 27', 'पुत्रान्मृतान्समीक्ष्याथ न भविष्यन्ति मातरः।
कौसल्या च सुमित्रा च कैकेयी च न संशयः॥', 'putrān mṛtān samīkṣyātha na bhaviṣyanti mātaraḥ
kausalyā ca sumitrā ca kaikeyī ca na saṃśayaḥ', null, 5011027),
('ramayana-5-11-28', 28, 'Sundara Kanda, Sarga 11, Verse 28', 'कृतज्ञः सत्यसंधश्च सुग्रीवः प्लवगाधिपः।
रामं तथा गतं दृष्ट्वा ततस्त्यक्ष्यन्ति जीवितम्॥', 'kṛtajñaḥ satyasaṃdhaś ca sugrīvaḥ plavagādhipaḥ
rāmaṃ tathā gataṃ dṛṣṭvā tatas tyakṣyanti jīvitam', null, 5011028),
('ramayana-5-11-29', 29, 'Sundara Kanda, Sarga 11, Verse 29', 'दुर्मना व्यथिता दीना निरानन्दा तपस्विनी।
पीडिता भर्तृशोकेन रुमा त्यक्ष्यति जीवितम्॥', 'durmanā vyathitā dīnā nirānandā tapasvinī
pīḍitā bhartṛśokena rumā tyakṣyati jīvitam', null, 5011029),
('ramayana-5-11-30', 30, 'Sundara Kanda, Sarga 11, Verse 30', 'वालिजेन तु दुःखेन पीडिता शोककर्शिता।
पञ्चत्वगमने राज्ञस्तारापि न भविष्यति॥', 'vālijena tu duḥkhena pīḍitā śokakarśitā
pañcatvagamane rājñas tārāpi na bhaviṣyati', null, 5011030),
('ramayana-5-11-31', 31, 'Sundara Kanda, Sarga 11, Verse 31', 'मातापित्रोर्विनाशेन सुग्रीव व्यसनेन च।
कुमारोऽप्यङ्गदः कस्माद्धारयिष्यति जीवितम्॥', 'mātāpitror vināśena sugrīva vyasanena ca
kumāro ''py aṅgadaḥ kasmād dhārayiṣyati jīvitam', null, 5011031),
('ramayana-5-11-32', 32, 'Sundara Kanda, Sarga 11, Verse 32', 'भर्तृजेन तु शोकेन अभिभूता वनौकसः।
शिरांस्यभिहनिष्यन्ति तलैर्मुष्टिभिरेव च॥', 'bhartṛjena tu śokena abhibhūtā vanaukasaḥ
śirāṃsy abhihaniṣyanti talair muṣṭibhir eva ca', null, 5011032),
('ramayana-5-11-33', 33, 'Sundara Kanda, Sarga 11, Verse 33', 'सान्त्वेनानुप्रदानेन मानेन च यशस्विना।
लालिताः कपिराजेन प्राणांस्त्यक्ष्यन्ति वानराः॥', 'sāntvenānupradānena mānena ca yaśasvinā
lālitāḥ kapirājena prāṇāṃs tyakṣyanti vānarāḥ', null, 5011033),
('ramayana-5-11-34', 34, 'Sundara Kanda, Sarga 11, Verse 34', 'न वनेषु न शैलेषु न निरोधेषु वा पुनः।
क्रीडामनुभविष्यन्ति समेत्य कपिकुञ्जराः॥', 'na vaneṣu na śaileṣu na nirodheṣu vā punaḥ
krīḍām anubhaviṣyanti sametya kapikuñjarāḥ', null, 5011034),
('ramayana-5-11-35', 35, 'Sundara Kanda, Sarga 11, Verse 35', 'सपुत्रदाराः सामात्या भर्तृव्यसनपीडिताः।
शैलाग्रेभ्यः पतिष्यन्ति समेत्य विषमेषु च॥', 'saputradārāḥ sāmātyā bhartṛvyasanapīḍitāḥ
śailāgrebhyaḥ patiṣyanti sametya viṣameṣu ca', null, 5011035),
('ramayana-5-11-36', 36, 'Sundara Kanda, Sarga 11, Verse 36', 'विषमुद्बन्धनं वापि प्रवेशं ज्वलनस्य वा।
उपवासमथो शस्त्रं प्रचरिष्यन्ति वानराः॥', 'viṣam udbandhanaṃ vāpi praveśaṃ jvalanasya vā
upavāsam atho śastraṃ pracariṣyanti vānarāḥ', null, 5011036),
('ramayana-5-11-37', 37, 'Sundara Kanda, Sarga 11, Verse 37', 'घोरमारोदनं मन्ये गते मयि भविष्यति।
इक्ष्वाकुकुलनाशश्च नाशश्चैव वनौकसाम्॥', 'ghoram ārodanaṃ manye gate mayi bhaviṣyati
ikṣvākukulanāśaś ca nāśaś caiva vanaukasām', null, 5011037),
('ramayana-5-11-38', 38, 'Sundara Kanda, Sarga 11, Verse 38', 'सोऽहं नैव गमिष्यामि किष्किन्धां नगरीमितः।
न हि शक्ष्याम्यहं द्रष्टुं सुग्रीवं मैथिलीं विना॥', 'so ''haṃ naiva gamiṣyāmi kiṣkindhāṃ nagarīm itaḥ
na hi śakṣyāmy ahaṃ draṣṭuṃ sugrīvaṃ maithilīṃ vinā', null, 5011038),
('ramayana-5-11-39', 39, 'Sundara Kanda, Sarga 11, Verse 39', 'मय्यगच्छति चेहस्थे धर्मात्मानौ महारथौ।
आशया तौ धरिष्येते वनराश्च मनस्विनः॥', 'mayy agacchati cehasthe dharmātmānau mahārathau
āśayā tau dhariṣyete vanarāś ca manasvinaḥ', null, 5011039),
('ramayana-5-11-40', 40, 'Sundara Kanda, Sarga 11, Verse 40', 'हस्तादानो मुखादानो नियतो वृक्षमूलिकः।
वानप्रस्थो भविष्यामि अदृष्ट्वा जनकात्मजाम्॥', 'hastādāno mukhādāno niyato vṛkṣamūlikaḥ
vānaprastho bhaviṣyāmi adṛṣṭvā janakātmajām', null, 5011040),
('ramayana-5-11-41', 41, 'Sundara Kanda, Sarga 11, Verse 41', 'सागरानूपजे देशे बहुमूलफलोदके।
चितां कृत्वा प्रवेक्ष्यामि समिद्धमरणीसुतम्॥', 'sāgarānūpaje deśe bahumūlaphalodake
citāṃ kṛtvā pravekṣyāmi samiddham araṇīsutam', null, 5011041),
('ramayana-5-11-42', 42, 'Sundara Kanda, Sarga 11, Verse 42', 'उपविष्टस्य वा सम्यग्लिङ्गिनं साधयिष्यतः।
शरीरं भक्षयिष्यन्ति वायसाः श्वापदानि च॥', 'upaviṣṭasya vā samyag liṅginaṃ sādhayiṣyataḥ
śarīraṃ bhakṣayiṣyanti vāyasāḥ śvāpadāni ca', null, 5011042),
('ramayana-5-11-43', 43, 'Sundara Kanda, Sarga 11, Verse 43', 'इदमप्यृषिभिर्दृष्टं निर्याणमिति मे मतिः।
सम्यगापः प्रवेक्ष्यामि न चेत्पश्यामि जानकीम्॥', 'idam apy ṛṣibhir dṛṣṭaṃ niryāṇam iti me matiḥ
samyag āpaḥ pravekṣyāmi na cet paśyāmi jānakīm', null, 5011043),
('ramayana-5-11-44', 44, 'Sundara Kanda, Sarga 11, Verse 44', 'सुजातमूला सुभगा कीर्तिमालायशस्विनी।
प्रभग्ना चिररात्रीयं मम सीतामपश्यतः॥', 'sujātamūlā subhagā kīrtimālāyaśasvinī
prabhagnā cirarātrīyaṃ mama sītām apaśyataḥ', null, 5011044),
('ramayana-5-11-45', 45, 'Sundara Kanda, Sarga 11, Verse 45', 'तापसो वा भविष्यामि नियतो वृक्षमूलिकः।
नेतः प्रतिगमिष्यामि तामदृष्ट्वासितेक्षणाम्॥', 'tāpaso vā bhaviṣyāmi niyato vṛkṣamūlikaḥ
netaḥ pratigamiṣyāmi tām adṛṣṭvāsitekṣaṇām', null, 5011045),
('ramayana-5-11-46', 46, 'Sundara Kanda, Sarga 11, Verse 46', 'यदीतः प्रतिगच्छामि सीतामनधिगम्य ताम्।
अङ्गदः सहितैः सर्वैर्वानरैर्न भविष्यति॥', 'yadītaḥ pratigacchāmi sītām anadhigamya tām
aṅgadaḥ sahitaiḥ sarvair vānarair na bhaviṣyati', null, 5011046),
('ramayana-5-11-47', 47, 'Sundara Kanda, Sarga 11, Verse 47', 'विनाशे बहवो दोषा जीवन्प्राप्नोति भद्रकम्।
तस्मात्प्राणान्धरिष्यामि ध्रुवो जीवति संगमः॥', 'vināśe bahavo doṣā jīvan prāpnoti bhadrakam
tasmāt prāṇān dhariṣyāmi dhruvo jīvati saṃgamaḥ', null, 5011047),
('ramayana-5-11-48', 48, 'Sundara Kanda, Sarga 11, Verse 48', 'एवं बहुविधं दुःखं मनसा धारयन्मुहुः।
नाध्यगच्छत्तदा पारं शोकस्य कपिकुञ्जरः॥', 'evaṃ bahuvidhaṃ duḥkhaṃ manasā dhārayan muhuḥ
nādhyagacchat tadā pāraṃ śokasya kapikuñjaraḥ', null, 5011048),
('ramayana-5-11-49', 49, 'Sundara Kanda, Sarga 11, Verse 49', 'रावणं वा वधिष्यामि दशग्रीवं महाबलम्।
काममस्तु हृता सीता प्रत्याचीर्णं भविष्यति॥', 'rāvaṇaṃ vā vadhiṣyāmi daśagrīvaṃ mahābalam
kāmam astu hṛtā sītā pratyācīrṇaṃ bhaviṣyati', null, 5011049),
('ramayana-5-11-50', 50, 'Sundara Kanda, Sarga 11, Verse 50', 'अथ वैनं समुत्क्षिप्य उपर्युपरि सागरम्।
रामायोपहरिष्यामि पशुं पशुपतेरिव॥', 'atha vainaṃ samutkṣipya upary upari sāgaram
rāmāyopahariṣyāmi paśuṃ paśupater iva', null, 5011050),
('ramayana-5-11-51', 51, 'Sundara Kanda, Sarga 11, Verse 51', 'इति चिन्ता समापन्नः सीतामनधिगम्य ताम्।
ध्यानशोका परीतात्मा चिन्तयामास वानरः॥', 'iti cintā samāpannaḥ sītām anadhigamya tām
dhyānaśokā parītātmā cintayām āsa vānaraḥ', null, 5011051),
('ramayana-5-11-52', 52, 'Sundara Kanda, Sarga 11, Verse 52', 'यावत्सीतां न पश्यामि रामपत्नीं यशस्विनीम्।
तावदेतां पुरीं लङ्कां विचिनोमि पुनः पुनः॥', 'yāvat sītāṃ na paśyāmi rāmapatnīṃ yaśasvinīm
tāvad etāṃ purīṃ laṅkāṃ vicinomi punaḥ punaḥ', null, 5011052),
('ramayana-5-11-53', 53, 'Sundara Kanda, Sarga 11, Verse 53', 'संपाति वचनाच्चापि रामं यद्यानयाम्यहम्।
अपश्यन्राघवो भार्यां निर्दहेत्सर्ववानरान्॥', 'saṃpāti vacanāc cāpi rāmaṃ yady ānayāmy aham
apaśyan rāghavo bhāryāṃ nirdahet sarvavānarān', null, 5011053),
('ramayana-5-11-54', 54, 'Sundara Kanda, Sarga 11, Verse 54', 'इहैव नियताहारो वत्स्यामि नियतेन्द्रियः।
न मत्कृते विनश्येयुः सर्वे ते नरवानराः॥', 'ihaiva niyatāhāro vatsyāmi niyatendriyaḥ
na matkṛte vinaśyeyuḥ sarve te naravānarāḥ', null, 5011054),
('ramayana-5-11-55', 55, 'Sundara Kanda, Sarga 11, Verse 55', 'अशोकवनिका चापि महतीयं महाद्रुमा।
इमामभिगमिष्यामि न हीयं विचिता मया॥', 'aśokavanikā cāpi mahatīyaṃ mahādrumā
imām abhigamiṣyāmi na hīyaṃ vicitā mayā', null, 5011055),
('ramayana-5-11-56', 56, 'Sundara Kanda, Sarga 11, Verse 56', 'वसून्रुद्रांस्तथादित्यानश्विनौ मरुतोऽपि च।
नमस्कृत्वा गमिष्यामि रक्षसां शोकवर्धनः॥', 'vasūn rudrāṃs tathādityān aśvinau maruto ''pi ca
namaskṛtvā gamiṣyāmi rakṣasāṃ śokavardhanaḥ', null, 5011056),
('ramayana-5-11-57', 57, 'Sundara Kanda, Sarga 11, Verse 57', 'जित्वा तु राक्षसान्देवीमिक्ष्वाकुकुलनन्दिनीम्।
संप्रदास्यामि रामाया यथासिद्धिं तपस्विने॥', 'jitvā tu rākṣasān devīm ikṣvākukulanandinīm
saṃpradāsyāmi rāmāyā yathāsiddhiṃ tapasvine', null, 5011057),
('ramayana-5-11-58', 58, 'Sundara Kanda, Sarga 11, Verse 58', 'स मुहूर्तमिव ध्यात्वा चिन्ताविग्रथितेन्द्रियः।
उदतिष्ठन्महाबाहुर्हनूमान्मारुतात्मजः॥', 'sa muhūrtam iva dhyātvā cintāvigrathitendriyaḥ
udatiṣṭhan mahābāhur hanūmān mārutātmajaḥ', null, 5011058),
('ramayana-5-11-59', 59, 'Sundara Kanda, Sarga 11, Verse 59', 'नमोऽस्तु रामाय सलक्ष्मणाय देव्यै च तस्यै जनकात्मजायै।
नमोऽस्तु रुद्रेन्द्रयमानिलेभ्यो नमोऽस्तु चन्द्रार्कमरुद्गणेभ्यः॥', 'namo ''stu rāmāya salakṣmaṇāya devyai ca tasyai janakātmajāyai
namo ''stu rudrendrayamānilebhyo namo ''stu candrārkamarudgaṇebhyaḥ', null, 5011059),
('ramayana-5-11-60', 60, 'Sundara Kanda, Sarga 11, Verse 60', 'स तेभ्यस्तु नमस्कृत्वा सुग्रीवाय च मारुतिः।
दिशः सर्वाः समालोक्य अशोकवनिकां प्रति॥', 'sa tebhyas tu namaskṛtvā sugrīvāya ca mārutiḥ
diśaḥ sarvāḥ samālokya aśokavanikāṃ prati', null, 5011060),
('ramayana-5-11-61', 61, 'Sundara Kanda, Sarga 11, Verse 61', 'स गत्वा मनसा पूर्वमशोकवनिकां शुभाम्।
उत्तरं चिन्तयामास वानरो मारुतात्मजः॥', 'sa gatvā manasā pūrvam aśokavanikāṃ śubhām
uttaraṃ cintayām āsa vānaro mārutātmajaḥ', null, 5011061),
('ramayana-5-11-62', 62, 'Sundara Kanda, Sarga 11, Verse 62', 'ध्रुवं तु रक्षोबहुला भविष्यति वनाकुला।
अशोकवनिका चिन्त्या सर्वसंस्कारसंस्कृता॥', 'dhruvaṃ tu rakṣobahulā bhaviṣyati vanākulā
aśokavanikā cintyā sarvasaṃskārasaṃskṛtā', null, 5011062),
('ramayana-5-11-63', 63, 'Sundara Kanda, Sarga 11, Verse 63', 'रक्षिणश्चात्र विहिता नूनं रक्षन्ति पादपान्।
भगवानपि सर्वात्मा नातिक्षोभं प्रवायति॥', 'rakṣiṇaś cātra vihitā nūnaṃ rakṣanti pādapān
bhagavān api sarvātmā nātikṣobhaṃ pravāyati', null, 5011063),
('ramayana-5-11-64', 64, 'Sundara Kanda, Sarga 11, Verse 64', 'संक्षिप्तोऽयं मयात्मा च रामार्थे रावणस्य च।
सिद्धिं मे संविधास्यन्ति देवाः सर्षिगणास्त्विह॥', 'saṃkṣipto ''yaṃ mayātmā ca rāmārthe rāvaṇasya ca
siddhiṃ me saṃvidhāsyanti devāḥ sarṣigaṇās tv iha', null, 5011064),
('ramayana-5-11-65', 65, 'Sundara Kanda, Sarga 11, Verse 65', 'ब्रह्मा स्वयम्भूर्भगवान्देवाश्चैव दिशन्तु मे।
सिद्धिमग्निश्च वायुश्च पुरुहूतश्च वज्रधृत्॥', 'brahmā svayambhūr bhagavān devāś caiva diśantu me
siddhim agniś ca vāyuś ca puruhūtaś ca vajradhṛt', null, 5011065),
('ramayana-5-11-66', 66, 'Sundara Kanda, Sarga 11, Verse 66', 'वरुणः पाशहस्तश्च सोमादित्यै तथैव च।
अश्विनौ च महात्मानौ मरुतः सर्व एव च॥', 'varuṇaḥ pāśahastaś ca somādityai tathaiva ca
aśvinau ca mahātmānau marutaḥ sarva eva ca', null, 5011066),
('ramayana-5-11-67', 67, 'Sundara Kanda, Sarga 11, Verse 67', 'सिद्धिं सर्वाणि भूतानि भूतानां चैव यः प्रभुः।
दास्यन्ति मम ये चान्ये अदृष्टाः पथि गोचराः॥', 'siddhiṃ sarvāṇi bhūtāni bhūtānāṃ caiva yaḥ prabhuḥ
dāsyanti mama ye cānye adṛṣṭāḥ pathi gocarāḥ', null, 5011067),
('ramayana-5-11-68', 68, 'Sundara Kanda, Sarga 11, Verse 68', 'तदुन्नसं पाण्डुरदन्तमव्रणं शुचिस्मितं पद्मपलाशलोचनम्।
द्रक्ष्ये तदार्यावदनं कदा न्वहं प्रसन्नताराधिपतुल्यदर्शनम्॥', 'tad unnasaṃ pāṇḍuradantam avraṇaṃ śucismitaṃ padmapalāśalocanam
drakṣye tad āryāvadanaṃ kadā nv ahaṃ prasannatārādhipatulyadarśanam', null, 5011068),
('ramayana-5-11-69', 69, 'Sundara Kanda, Sarga 11, Verse 69', 'क्षुद्रेण पापेन नृशंसकर्मणा सुदारुणालांकृतवेषधारिणा।
बलाभिभूता अबला तपस्विनी कथं नु मे दृष्टपथेऽद्य सा भवेत्॥', 'kṣudreṇa pāpena nṛśaṃsakarmaṇā sudāruṇālāṃkṛtaveṣadhāriṇā
balābhibhūtā abalā tapasvinī kathaṃ nu me dṛṣṭapathe ''dya sā bhavet', null, 5011069)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 12 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-12-1', 1, 'Sundara Kanda, Sarga 12, Verse 1', 'स मुहूर्तमिव ध्यत्वा मनसा चाधिगम्य ताम्।
अवप्लुतो महातेजाः प्राकारं तस्य वेश्मनः॥', 'sa muhūrtam iva dhyatvā manasā cādhigamya tām
avapluto mahātejāḥ prākāraṃ tasya veśmanaḥ', null, 5012001),
('ramayana-5-12-2', 2, 'Sundara Kanda, Sarga 12, Verse 2', 'स तु संहृष्टसर्वाङ्गः प्राकारस्थो महाकपिः।
पुष्पिताग्रान्वसन्तादौ ददर्श विविधान्द्रुमान्॥', 'sa tu saṃhṛṣṭasarvāṅgaḥ prākārastho mahākapiḥ
puṣpitāgrān vasantādau dadarśa vividhān drumān', null, 5012002),
('ramayana-5-12-3', 3, 'Sundara Kanda, Sarga 12, Verse 3', 'सालानशोकान्भव्यांश्च चम्पकांश्च सुपुष्पितान्।
उद्दालकान्नागवृक्षांश्चूतान्कपिमुखानपि॥', 'sālān aśokān bhavyāṃś ca campakāṃś ca supuṣpitān
uddālakān nāgavṛkṣāṃś cūtān kapimukhān api', null, 5012003),
('ramayana-5-12-4', 4, 'Sundara Kanda, Sarga 12, Verse 4', 'अथाम्रवणसंछन्नां लताशतसमावृताम्।
ज्यामुक्त इव नाराचः पुप्लुवे वृक्षवाटिकाम्॥', 'athāmravaṇasaṃchannāṃ latāśatasamāvṛtām
jyāmukta iva nārācaḥ pupluve vṛkṣavāṭikām', null, 5012004),
('ramayana-5-12-5', 5, 'Sundara Kanda, Sarga 12, Verse 5', 'स प्रविष्य विचित्रां तां विहगैरभिनादिताम्।
राजतैः काञ्चनैश्चैव पादपैः सर्वतोवृताम्॥', 'sa praviṣya vicitrāṃ tāṃ vihagair abhināditām
rājataiḥ kāñcanaiś caiva pādapaiḥ sarvatovṛtām', null, 5012005),
('ramayana-5-12-6', 6, 'Sundara Kanda, Sarga 12, Verse 6', 'विहगैर्मृगसंघैश्च विचित्रां चित्रकाननाम्।
उदितादित्यसंकाशां ददर्श हनुमान्कपिः॥', 'vihagair mṛgasaṃghaiś ca vicitrāṃ citrakānanām
uditādityasaṃkāśāṃ dadarśa hanumān kapiḥ', null, 5012006),
('ramayana-5-12-7', 7, 'Sundara Kanda, Sarga 12, Verse 7', 'वृतां नानाविधैर्वृक्षैः पुष्पोपगफलोपगैः।
कोकिलैर्भृङ्गराजैश्च मत्तैर्नित्यनिषेविताम्॥', 'vṛtāṃ nānāvidhair vṛkṣaiḥ puṣpopagaphalopagaiḥ
kokilair bhṛṅgarājaiś ca mattair nityaniṣevitām', null, 5012007),
('ramayana-5-12-8', 8, 'Sundara Kanda, Sarga 12, Verse 8', 'प्रहृष्टमनुजे कले मृगपक्षिसमाकुले।
मत्तबर्हिणसंघुष्टां नानाद्विजगणायुताम्॥', 'prahṛṣṭamanuje kale mṛgapakṣisamākule
mattabarhiṇasaṃghuṣṭāṃ nānādvijagaṇāyutām', null, 5012008),
('ramayana-5-12-9', 9, 'Sundara Kanda, Sarga 12, Verse 9', 'मार्गमाणो वरारोहां राजपुत्रीमनिन्दिताम्।
सुखप्रसुप्तान्विहगान्बोधयामास वानरः॥', 'mārgamāṇo varārohāṃ rājaputrīm aninditām
sukhaprasuptān vihagān bodhayām āsa vānaraḥ', null, 5012009),
('ramayana-5-12-10', 10, 'Sundara Kanda, Sarga 12, Verse 10', 'उत्पतद्भिर्द्विजगणैः पक्षैः सालाः समाहताः।
अनेकवर्णा विविधा मुमुचुः पुष्पवृष्टयः॥', 'utpatadbhir dvijagaṇaiḥ pakṣaiḥ sālāḥ samāhatāḥ
anekavarṇā vividhā mumucuḥ puṣpavṛṣṭayaḥ', null, 5012010),
('ramayana-5-12-11', 11, 'Sundara Kanda, Sarga 12, Verse 11', 'पुष्पावकीर्णः शुशुभे हनुमान्मारुतात्मजः।
अशोकवनिकामध्ये यथा पुष्पमयो गिरिः॥', 'puṣpāvakīrṇaḥ śuśubhe hanumān mārutātmajaḥ
aśokavanikāmadhye yathā puṣpamayo giriḥ', null, 5012011),
('ramayana-5-12-12', 12, 'Sundara Kanda, Sarga 12, Verse 12', 'दिशः सर्वाभिदावन्तं वृक्षषण्डगतं कपिम्।
दृष्ट्वा सर्वाणि भूतानि वसन्त इति मेनिरे॥', 'diśaḥ sarvābhidāvantaṃ vṛkṣaṣaṇḍagataṃ kapim
dṛṣṭvā sarvāṇi bhūtāni vasanta iti menire', null, 5012012),
('ramayana-5-12-13', 13, 'Sundara Kanda, Sarga 12, Verse 13', 'वृक्षेभ्यः पतितैः पुष्पैरवकीर्णा पृथग्विधैः।
रराज वसुधा तत्र प्रमदेव विभूषिता॥', 'vṛkṣebhyaḥ patitaiḥ puṣpair avakīrṇā pṛthagvidhaiḥ
rarāja vasudhā tatra pramadeva vibhūṣitā', null, 5012013),
('ramayana-5-12-14', 14, 'Sundara Kanda, Sarga 12, Verse 14', 'तरस्विना ते तरवस्तरसाभिप्रकम्पिताः।
कुसुमानि विचित्राणि ससृजुः कपिना तदा॥', 'tarasvinā te taravas tarasābhiprakampitāḥ
kusumāni vicitrāṇi sasṛjuḥ kapinā tadā', null, 5012014),
('ramayana-5-12-15', 15, 'Sundara Kanda, Sarga 12, Verse 15', 'निर्धूतपत्रशिखराः शीर्णपुष्पफलद्रुमाः।
निक्षिप्तवस्त्राभरणा धूर्ता इव पराजिताः॥', 'nirdhūtapatraśikharāḥ śīrṇapuṣpaphaladrumāḥ
nikṣiptavastrābharaṇā dhūrtā iva parājitāḥ', null, 5012015),
('ramayana-5-12-16', 16, 'Sundara Kanda, Sarga 12, Verse 16', 'हनूमता वेगवता कम्पितास्ते नगोत्तमाः।
पुष्पपर्णफलान्याशु मुमुचुः पुष्पशालिनः॥', 'hanūmatā vegavatā kampitās te nagottamāḥ
puṣpaparṇaphalāny āśu mumucuḥ puṣpaśālinaḥ', null, 5012016),
('ramayana-5-12-17', 17, 'Sundara Kanda, Sarga 12, Verse 17', 'विहंगसंघैर्हीनास्ते स्कन्धमात्राश्रया द्रुमाः।
बभूवुरगमाः सर्वे मारुतेनेव निर्धुताः॥', 'vihaṃgasaṃghair hīnās te skandhamātrāśrayā drumāḥ
babhūvur agamāḥ sarve māruteneva nirdhutāḥ', null, 5012017),
('ramayana-5-12-18', 18, 'Sundara Kanda, Sarga 12, Verse 18', 'विधूतकेशी युवतिर्यथा मृदितवर्णिका।
निष्पीतशुभदन्तौष्ठी नखैर्दन्तैश्च विक्षता॥', 'vidhūtakeśī yuvatir yathā mṛditavarṇikā
niṣpītaśubhadantauṣṭhī nakhair dantaiś ca vikṣatā', null, 5012018),
('ramayana-5-12-19', 19, 'Sundara Kanda, Sarga 12, Verse 19', 'तथा लाङ्गूलहस्तैश्च चरणाभ्यां च मर्दिता।
बभूवाशोकवनिका प्रभग्नवरपादपा॥', 'tathā lāṅgūlahastaiś ca caraṇābhyāṃ ca marditā
babhūvāśokavanikā prabhagnavarapādapā', null, 5012019),
('ramayana-5-12-20', 20, 'Sundara Kanda, Sarga 12, Verse 20', 'महालतानां दामानि व्यधमत्तरसा कपिः।
यथा प्रावृषि विन्ध्यस्य मेघजालानि मारुतः॥', 'mahālatānāṃ dāmāni vyadhamat tarasā kapiḥ
yathā prāvṛṣi vindhyasya meghajālāni mārutaḥ', null, 5012020),
('ramayana-5-12-21', 21, 'Sundara Kanda, Sarga 12, Verse 21', 'स तत्र मणिभूमीश्च राजतीश्च मनोरमाः।
तथा काञ्चनभूमीश्च विचरन्ददृशे कपिः॥', 'sa tatra maṇibhūmīś ca rājatīś ca manoramāḥ
tathā kāñcanabhūmīś ca vicaran dadṛśe kapiḥ', null, 5012021),
('ramayana-5-12-22', 22, 'Sundara Kanda, Sarga 12, Verse 22', 'वापीश्च विविधाकाराः पूर्णाः परमवारिणा।
महार्हैर्मणिसोपानैरुपपन्नास्ततस्ततः॥', 'vāpīś ca vividhākārāḥ pūrṇāḥ paramavāriṇā
mahārhair maṇisopānair upapannās tatas tataḥ', null, 5012022),
('ramayana-5-12-23', 23, 'Sundara Kanda, Sarga 12, Verse 23', 'मुक्ताप्रवालसिकता स्फटिकान्तरकुट्टिमाः।
काञ्चनैस्तरुभिश्चित्रैस्तीरजैरुपशोभिताः॥', 'muktāpravālasikatā sphaṭikāntarakuṭṭimāḥ
kāñcanais tarubhiś citrais tīrajair upaśobhitāḥ', null, 5012023),
('ramayana-5-12-24', 24, 'Sundara Kanda, Sarga 12, Verse 24', 'फुल्लपद्मोत्पलवनाश्चक्रवाकोपकूजिताः।
नत्यूहरुतसंघुष्टा हंससारसनादिताः॥', 'phullapadmotpalavanāś cakravākopakūjitāḥ
natyūharutasaṃghuṣṭā haṃsasārasanāditāḥ', null, 5012024),
('ramayana-5-12-25', 25, 'Sundara Kanda, Sarga 12, Verse 25', 'दीर्घाभिर्द्रुमयुक्ताभिः सरिद्भिश्च समन्ततः।
अमृतोपमतोयाभिः शिवाभिरुपसंस्कृताः॥', 'dīrghābhir drumayuktābhiḥ saridbhiś ca samantataḥ
amṛtopamatoyābhiḥ śivābhir upasaṃskṛtāḥ', null, 5012025),
('ramayana-5-12-26', 26, 'Sundara Kanda, Sarga 12, Verse 26', 'लताशतैरवतताः सन्तानकसमावृताः।
नानागुल्मावृतवनाः करवीरकृतान्तराः॥', 'latāśatair avatatāḥ santānakasamāvṛtāḥ
nānāgulmāvṛtavanāḥ karavīrakṛtāntarāḥ', null, 5012026),
('ramayana-5-12-27', 27, 'Sundara Kanda, Sarga 12, Verse 27', 'ततोऽम्बुधरसंकाशं प्रवृद्धशिखरं गिरिम्।
विचित्रकूटं कूटैश्च सर्वतः परिवारितम्॥', 'tato ''mbudharasaṃkāśaṃ pravṛddhaśikharaṃ girim
vicitrakūṭaṃ kūṭaiś ca sarvataḥ parivāritam', null, 5012027),
('ramayana-5-12-28', 28, 'Sundara Kanda, Sarga 12, Verse 28', 'शिलागृहैरवततं नानावृक्षैः समावृतम्।
ददर्श कपिशार्दूलो रम्यं जगति पर्वतम्॥', 'śilāgṛhair avatataṃ nānāvṛkṣaiḥ samāvṛtam
dadarśa kapiśārdūlo ramyaṃ jagati parvatam', null, 5012028),
('ramayana-5-12-29', 29, 'Sundara Kanda, Sarga 12, Verse 29', 'ददर्श च नगात्तस्मान्नदीं निपतितां कपिः।
अङ्कादिव समुत्पत्य प्रियस्य पतितां प्रियाम्॥', 'dadarśa ca nagāt tasmān nadīṃ nipatitāṃ kapiḥ
aṅkād iva samutpatya priyasya patitāṃ priyām', null, 5012029),
('ramayana-5-12-30', 30, 'Sundara Kanda, Sarga 12, Verse 30', 'जले निपतिताग्रैश्च पादपैरुपशोभिताम्।
वार्यमाणामिव क्रुद्धां प्रमदां प्रियबन्धुभिः॥', 'jale nipatitāgraiś ca pādapair upaśobhitām
vāryamāṇām iva kruddhāṃ pramadāṃ priyabandhubhiḥ', null, 5012030),
('ramayana-5-12-31', 31, 'Sundara Kanda, Sarga 12, Verse 31', 'पुनरावृत्ततोयां च ददर्श स महाकपिः।
प्रसन्नामिव कान्तस्य कान्तां पुनरुपस्थिताम्॥', 'punar āvṛttatoyāṃ ca dadarśa sa mahākapiḥ
prasannām iva kāntasya kāntāṃ punar upasthitām', null, 5012031),
('ramayana-5-12-32', 32, 'Sundara Kanda, Sarga 12, Verse 32', 'तस्यादूरात्स पद्मिन्यो नानाद्विजगणायुताः।
ददर्श कपिशार्दूलो हनुमान्मारुतात्मजः॥', 'tasyādūrāt sa padminyo nānādvijagaṇāyutāḥ
dadarśa kapiśārdūlo hanumān mārutātmajaḥ', null, 5012032),
('ramayana-5-12-33', 33, 'Sundara Kanda, Sarga 12, Verse 33', 'कृत्रिमां दीर्घिकां चापि पूर्णां शीतेन वारिणा।
मणिप्रवरसोपानां मुक्तासिकतशोभिताम्॥', 'kṛtrimāṃ dīrghikāṃ cāpi pūrṇāṃ śītena vāriṇā
maṇipravarasopānāṃ muktāsikataśobhitām', null, 5012033),
('ramayana-5-12-34', 34, 'Sundara Kanda, Sarga 12, Verse 34', 'विविधैर्मृगसंघैश्च विचित्रां चित्रकाननाम्।
प्रासादैः सुमहद्भिश्च निर्मितैर्विश्वकर्मणा।
काननैः कृत्रिमैश्चापि सर्वतः समलंकृताम्॥', 'vividhair mṛgasaṃghaiś ca vicitrāṃ citrakānanām
prāsādaiḥ sumahadbhiś ca nirmitair viśvakarmaṇā
kānanaiḥ kṛtrimaiś cāpi sarvataḥ samalaṃkṛtām', null, 5012034),
('ramayana-5-12-35', 35, 'Sundara Kanda, Sarga 12, Verse 35', 'ये के चित्पादपास्तत्र पुष्पोपगफलोपगाः।
सच्छत्राः सवितर्दीकाः सर्वे सौवर्णवेदिकाः॥', 'ye ke cit pādapās tatra puṣpopagaphalopagāḥ
sacchatrāḥ savitardīkāḥ sarve sauvarṇavedikāḥ', null, 5012035),
('ramayana-5-12-36', 36, 'Sundara Kanda, Sarga 12, Verse 36', 'लताप्रतानैर्बहुभिः पर्णैश्च बहुभिर्वृताम्।
काञ्चनीं शिंशुपामेकां ददर्श स महाकपिः॥', 'latāpratānair bahubhiḥ parṇaiś ca bahubhir vṛtām
kāñcanīṃ śiṃśupām ekāṃ dadarśa sa mahākapiḥ', null, 5012036),
('ramayana-5-12-37', 37, 'Sundara Kanda, Sarga 12, Verse 37', 'सोऽपश्यद्भूमिभागांश्च गर्तप्रस्रवणानि च।
सुवर्णवृक्षानपरान्ददर्श शिखिसंनिभान्॥', 'so ''paśyad bhūmibhāgāṃś ca gartaprasravaṇāni ca
suvarṇavṛkṣān aparān dadarśa śikhisaṃnibhān', null, 5012037),
('ramayana-5-12-38', 38, 'Sundara Kanda, Sarga 12, Verse 38', 'तेषां द्रुमाणां प्रभया मेरोरिव महाकपिः।
अमन्यत तदा वीरः काञ्चनोऽस्मीति वानरः॥', 'teṣāṃ drumāṇāṃ prabhayā meror iva mahākapiḥ
amanyata tadā vīraḥ kāñcano ''smīti vānaraḥ', null, 5012038),
('ramayana-5-12-39', 39, 'Sundara Kanda, Sarga 12, Verse 39', 'तां काञ्चनैस्तरुगणैर्मारुतेन च वीजिताम्।
किङ्किणीशतनिर्घोषां दृष्ट्वा विस्मयमागमत्॥', 'tāṃ kāñcanais tarugaṇair mārutena ca vījitām
kiṅkiṇīśatanirghoṣāṃ dṛṣṭvā vismayam āgamat', null, 5012039),
('ramayana-5-12-40', 40, 'Sundara Kanda, Sarga 12, Verse 40', 'सुपुष्पिताग्रां रुचिरां तरुणाङ्कुरपल्लवाम्।
तामारुह्य महावेगः शिंशपां पर्णसंवृताम्॥', 'supuṣpitāgrāṃ rucirāṃ taruṇāṅkurapallavām
tām āruhya mahāvegaḥ śiṃśapāṃ parṇasaṃvṛtām', null, 5012040),
('ramayana-5-12-41', 41, 'Sundara Kanda, Sarga 12, Verse 41', 'इतो द्रक्ष्यामि वैदेहीं राम दर्शनलालसाम्।
इतश्चेतश्च दुःखार्तां संपतन्तीं यदृच्छया॥', 'ito drakṣyāmi vaidehīṃ rāma darśanalālasām
itaś cetaś ca duḥkhārtāṃ saṃpatantīṃ yadṛcchayā', null, 5012041),
('ramayana-5-12-42', 42, 'Sundara Kanda, Sarga 12, Verse 42', 'अशोकवनिका चेयं दृढं रम्या दुरात्मनः।
चम्पकैश्चन्दनैश्चापि बकुलैश्च विभूषिता॥', 'aśokavanikā ceyaṃ dṛḍhaṃ ramyā durātmanaḥ
campakaiś candanaiś cāpi bakulaiś ca vibhūṣitā', null, 5012042),
('ramayana-5-12-43', 43, 'Sundara Kanda, Sarga 12, Verse 43', 'इयं च नलिनी रम्या द्विजसंघनिषेविता।
इमां सा राममहिषी नूनमेष्यति जानकी॥', 'iyaṃ ca nalinī ramyā dvijasaṃghaniṣevitā
imāṃ sā rāmamahiṣī nūnam eṣyati jānakī', null, 5012043),
('ramayana-5-12-44', 44, 'Sundara Kanda, Sarga 12, Verse 44', 'सा राम राममहिषी राघवस्य प्रिया सदा।
वनसंचारकुशला नूनमेष्यति जानकी॥', 'sā rāma rāmamahiṣī rāghavasya priyā sadā
vanasaṃcārakuśalā nūnam eṣyati jānakī', null, 5012044),
('ramayana-5-12-45', 45, 'Sundara Kanda, Sarga 12, Verse 45', 'अथ वा मृगशावाक्षी वनस्यास्य विचक्षणा।
वनमेष्यति सा चेह रामचिन्तानुकर्शिता॥', 'atha vā mṛgaśāvākṣī vanasyāsya vicakṣaṇā
vanam eṣyati sā ceha rāmacintānukarśitā', null, 5012045),
('ramayana-5-12-46', 46, 'Sundara Kanda, Sarga 12, Verse 46', 'रामशोकाभिसंतप्ता सा देवी वामलोचना।
वनवासरता नित्यमेष्यते वनचारिणी॥', 'rāmaśokābhisaṃtaptā sā devī vāmalocanā
vanavāsaratā nityam eṣyate vanacāriṇī', null, 5012046),
('ramayana-5-12-47', 47, 'Sundara Kanda, Sarga 12, Verse 47', 'वनेचराणां सततं नूनं स्पृहयते पुरा।
रामस्य दयिता भार्या जनकस्य सुता सती॥', 'vanecarāṇāṃ satataṃ nūnaṃ spṛhayate purā
rāmasya dayitā bhāryā janakasya sutā satī', null, 5012047),
('ramayana-5-12-48', 48, 'Sundara Kanda, Sarga 12, Verse 48', 'संध्याकालमनाः श्यामा ध्रुवमेष्यति जानकी।
नदीं चेमां शिवजलां संध्यार्थे वरवर्णिनी॥', 'saṃdhyākālamanāḥ śyāmā dhruvam eṣyati jānakī
nadīṃ cemāṃ śivajalāṃ saṃdhyārthe varavarṇinī', null, 5012048),
('ramayana-5-12-49', 49, 'Sundara Kanda, Sarga 12, Verse 49', 'तस्याश्चाप्यनुरूपेयमशोकवनिका शुभा।
शुभा या पार्थिवेन्द्रस्य पत्नी रामस्य संमिता॥', 'tasyāś cāpy anurūpeyam aśokavanikā śubhā
śubhā yā pārthivendrasya patnī rāmasya saṃmitā', null, 5012049),
('ramayana-5-12-50', 50, 'Sundara Kanda, Sarga 12, Verse 50', 'यदि जिवति सा देवी ताराधिपनिभानना।
आगमिष्यति सावश्यमिमां शिवजलां नदीम्॥', 'yadi jivati sā devī tārādhipanibhānanā
āgamiṣyati sāvaśyam imāṃ śivajalāṃ nadīm', null, 5012050),
('ramayana-5-12-51', 51, 'Sundara Kanda, Sarga 12, Verse 51', 'एवं तु मत्वा हनुमान्महात्मा प्रतीक्षमाणो मनुजेन्द्रपत्नीम्।
अवेक्षमाणश्च ददर्श सर्वं सुपुष्पिते पर्णघने निलीनः॥', 'evaṃ tu matvā hanumān mahātmā pratīkṣamāṇo manujendrapatnīm
avekṣamāṇaś ca dadarśa sarvaṃ supuṣpite parṇaghane nilīnaḥ', null, 5012051)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 13 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-13-1', 1, 'Sundara Kanda, Sarga 13, Verse 1', 'स वीक्षमाणस्तत्रस्थो मार्गमाणश्च मैथिलीम्।
अवेक्षमाणश्च महीं सर्वां तामन्ववैक्षत॥', 'sa vīkṣamāṇas tatrastho mārgamāṇaś ca maithilīm
avekṣamāṇaś ca mahīṃ sarvāṃ tām anvavaikṣata', null, 5013001),
('ramayana-5-13-2', 2, 'Sundara Kanda, Sarga 13, Verse 2', 'सन्तान कलताभिश्च पादपैरुपशोभिताम्।
दिव्यगन्धरसोपेतां सर्वतः समलंकृताम्॥', 'santāna kalatābhiś ca pādapair upaśobhitām
divyagandharasopetāṃ sarvataḥ samalaṃkṛtām', null, 5013002),
('ramayana-5-13-3', 3, 'Sundara Kanda, Sarga 13, Verse 3', 'तां स नन्दनसंकाशां मृगपक्षिभिरावृताम्।
हर्म्यप्रासादसंबाधां कोकिलाकुलनिःस्वनाम्॥', 'tāṃ sa nandanasaṃkāśāṃ mṛgapakṣibhir āvṛtām
harmyaprāsādasaṃbādhāṃ kokilākulaniḥsvanām', null, 5013003),
('ramayana-5-13-4', 4, 'Sundara Kanda, Sarga 13, Verse 4', 'काञ्चनोत्पलपद्माभिर्वापीभिरुपशोभिताम्।
बह्वासनकुथोपेतां बहुभूमिगृहायुताम्॥', 'kāñcanotpalapadmābhir vāpībhir upaśobhitām
bahvāsanakuthopetāṃ bahubhūmigṛhāyutām', null, 5013004),
('ramayana-5-13-5', 5, 'Sundara Kanda, Sarga 13, Verse 5', 'सर्वर्तुकुसुमै रम्यैः फलवद्भिश्च पादपैः।
पुष्पितानामशोकानां श्रिया सूर्योदयप्रभाम्॥', 'sarvartukusumai ramyaiḥ phalavadbhiś ca pādapaiḥ
puṣpitānām aśokānāṃ śriyā sūryodayaprabhām', null, 5013005),
('ramayana-5-13-6', 6, 'Sundara Kanda, Sarga 13, Verse 6', 'प्रदीप्तामिव तत्रस्थो मारुतिः समुदैक्षत।
निष्पत्रशाखां विहगैः क्रियमाणामिवासकृत्।
विनिष्पतद्भिः शतशश्चित्रैः पुष्पावतंसकैः॥', 'pradīptām iva tatrastho mārutiḥ samudaikṣata
niṣpatraśākhāṃ vihagaiḥ kriyamāṇām ivāsakṛt
viniṣpatadbhiḥ śataśaś citraiḥ puṣpāvataṃsakaiḥ', null, 5013006),
('ramayana-5-13-7', 7, 'Sundara Kanda, Sarga 13, Verse 7', 'आमूलपुष्पनिचितैरशोकैः शोकनाशनैः।
पुष्पभारातिभारैश्च स्पृशद्भिरिव मेदिनीम्॥', 'āmūlapuṣpanicitair aśokaiḥ śokanāśanaiḥ
puṣpabhārātibhāraiś ca spṛśadbhir iva medinīm', null, 5013007),
('ramayana-5-13-8', 8, 'Sundara Kanda, Sarga 13, Verse 8', 'कर्णिकारैः कुसुमितैः किंशुकैश्च सुपुष्पितैः।
स देशः प्रभया तेषां प्रदीप्त इव सर्वतः॥', 'karṇikāraiḥ kusumitaiḥ kiṃśukaiś ca supuṣpitaiḥ
sa deśaḥ prabhayā teṣāṃ pradīpta iva sarvataḥ', null, 5013008),
('ramayana-5-13-9', 9, 'Sundara Kanda, Sarga 13, Verse 9', 'पुंनागाः सप्तपर्णाश्च चम्पकोद्दालकास्तथा।
विवृद्धमूला बहवः शोभन्ते स्म सुपुष्पिताः॥', 'puṃnāgāḥ saptaparṇāś ca campakoddālakās tathā
vivṛddhamūlā bahavaḥ śobhante sma supuṣpitāḥ', null, 5013009),
('ramayana-5-13-10', 10, 'Sundara Kanda, Sarga 13, Verse 10', 'शातकुम्भनिभाः के चित्के चिदग्निशिखोपमाः।
नीलाञ्जननिभाः के चित्तत्राशोकाः सहस्रशः॥', 'śātakumbhanibhāḥ ke cit ke cid agniśikhopamāḥ
nīlāñjananibhāḥ ke cit tatrāśokāḥ sahasraśaḥ', null, 5013010),
('ramayana-5-13-11', 11, 'Sundara Kanda, Sarga 13, Verse 11', 'नन्दनं विविधोद्यानं चित्रं चैत्ररथं यथा।
अतिवृत्तमिवाचिन्त्यं दिव्यं रम्यं श्रिया वृतम्॥', 'nandanaṃ vividhodyānaṃ citraṃ caitrarathaṃ yathā
ativṛttam ivācintyaṃ divyaṃ ramyaṃ śriyā vṛtam', null, 5013011),
('ramayana-5-13-12', 12, 'Sundara Kanda, Sarga 13, Verse 12', 'द्वितीयमिव चाकाशं पुष्पज्योतिर्गणायुतम्।
पुष्परत्नशतैश्चित्रं पञ्चमं सागरं यथा॥', 'dvitīyam iva cākāśaṃ puṣpajyotirgaṇāyutam
puṣparatnaśataiś citraṃ pañcamaṃ sāgaraṃ yathā', null, 5013012),
('ramayana-5-13-13', 13, 'Sundara Kanda, Sarga 13, Verse 13', 'सर्वर्तुपुष्पैर्निचितं पादपैर्मधुगन्धिभिः।
नानानिनादैरुद्यानं रम्यं मृगगणैर्द्विजैः॥', 'sarvartupuṣpair nicitaṃ pādapair madhugandhibhiḥ
nānāninādair udyānaṃ ramyaṃ mṛgagaṇair dvijaiḥ', null, 5013013),
('ramayana-5-13-14', 14, 'Sundara Kanda, Sarga 13, Verse 14', 'अनेकगन्धप्रवहं पुण्यगन्धं मनोरमम्।
शैलेन्द्रमिव गन्धाढ्यं द्वितीयं गन्धमादनम्॥', 'anekagandhapravahaṃ puṇyagandhaṃ manoramam
śailendram iva gandhāḍhyaṃ dvitīyaṃ gandhamādanam', null, 5013014),
('ramayana-5-13-15', 15, 'Sundara Kanda, Sarga 13, Verse 15', 'अशोकवनिकायां तु तस्यां वानरपुंगवः।
स ददर्शाविदूरस्थं चैत्यप्रासादमूर्जितम्॥', 'aśokavanikāyāṃ tu tasyāṃ vānarapuṃgavaḥ
sa dadarśāvidūrasthaṃ caityaprāsādam ūrjitam', null, 5013015),
('ramayana-5-13-16', 16, 'Sundara Kanda, Sarga 13, Verse 16', 'मध्ये स्तम्भसहस्रेण स्थितं कैलासपाण्डुरम्।
प्रवालकृतसोपानं तप्तकाञ्चनवेदिकम्॥', 'madhye stambhasahasreṇa sthitaṃ kailāsapāṇḍuram
pravālakṛtasopānaṃ taptakāñcanavedikam', null, 5013016),
('ramayana-5-13-17', 17, 'Sundara Kanda, Sarga 13, Verse 17', 'मुष्णन्तमिव चक्षूंषि द्योतमानमिव श्रिया।
विमलं प्रांशुभावत्वादुल्लिखन्तमिवाम्बरम्॥', 'muṣṇantam iva cakṣūṃṣi dyotamānam iva śriyā
vimalaṃ prāṃśubhāvatvād ullikhantam ivāmbaram', null, 5013017),
('ramayana-5-13-18', 18, 'Sundara Kanda, Sarga 13, Verse 18', 'ततो मलिनसंवीतां राक्षसीभिः समावृताम्।
उपवासकृशां दीनां निःश्वसान्तीं पुनः पुनः।
ददर्श शुक्लपक्षादौ चन्द्ररेखामिवामलाम्॥', 'tato malinasaṃvītāṃ rākṣasībhiḥ samāvṛtām
upavāsakṛśāṃ dīnāṃ niḥśvasāntīṃ punaḥ punaḥ
dadarśa śuklapakṣādau candrarekhām ivāmalām', null, 5013018),
('ramayana-5-13-19', 19, 'Sundara Kanda, Sarga 13, Verse 19', 'मन्दप्रख्यायमानेन रूपेण रुचिरप्रभाम्।
पिनद्धां धूमजालेन शिखामिव विभावसोः॥', 'mandaprakhyāyamānena rūpeṇa ruciraprabhām
pinaddhāṃ dhūmajālena śikhām iva vibhāvasoḥ', null, 5013019),
('ramayana-5-13-20', 20, 'Sundara Kanda, Sarga 13, Verse 20', 'पीतेनैकेन संवीतां क्लिष्टेनोत्तमवाससा।
सपङ्कामनलंकारां विपद्मामिव पद्मिनीम्॥', 'pītenaikena saṃvītāṃ kliṣṭenottamavāsasā
sapaṅkām analaṃkārāṃ vipadmām iva padminīm', null, 5013020),
('ramayana-5-13-21', 21, 'Sundara Kanda, Sarga 13, Verse 21', 'व्रीडितां दुःखसंतप्तां परिम्लानां तपस्विनीम्।
ग्रहेणाङ्गारकेणैव पीडितामिव रोहिणीम्॥', 'vrīḍitāṃ duḥkhasaṃtaptāṃ parimlānāṃ tapasvinīm
graheṇāṅgārakeṇaiva pīḍitām iva rohiṇīm', null, 5013021),
('ramayana-5-13-22', 22, 'Sundara Kanda, Sarga 13, Verse 22', 'अश्रुपूर्णमुखीं दीनां कृशामननशेन च।
शोकध्यानपरां दीनां नित्यं दुःखपरायणाम्॥', 'aśrupūrṇamukhīṃ dīnāṃ kṛśām ananaśena ca
śokadhyānaparāṃ dīnāṃ nityaṃ duḥkhaparāyaṇām', null, 5013022),
('ramayana-5-13-23', 23, 'Sundara Kanda, Sarga 13, Verse 23', 'प्रियं जनमपश्यन्तीं पश्यन्तीं राक्षसीगणम्।
स्वगणेन मृगीं हीनां श्वगणाभिवृतामिव॥', 'priyaṃ janam apaśyantīṃ paśyantīṃ rākṣasīgaṇam
svagaṇena mṛgīṃ hīnāṃ śvagaṇābhivṛtām iva', null, 5013023),
('ramayana-5-13-24', 24, 'Sundara Kanda, Sarga 13, Verse 24', 'नीलनागाभया वेण्या जघनं गतयैकया।
सुखार्हां दुःखसंतप्तां व्यसनानामकोदिवाम्॥', 'nīlanāgābhayā veṇyā jaghanaṃ gatayaikayā
sukhārhāṃ duḥkhasaṃtaptāṃ vyasanānām akodivām', null, 5013024),
('ramayana-5-13-25', 25, 'Sundara Kanda, Sarga 13, Verse 25', 'तां समीक्ष्य विशालाक्षीमधिकं मलिनां कृशाम्।
तर्कयामास सीतेति कारणैरुपपादिभिः॥', 'tāṃ samīkṣya viśālākṣīm adhikaṃ malināṃ kṛśām
tarkayām āsa sīteti kāraṇair upapādibhiḥ', null, 5013025),
('ramayana-5-13-26', 26, 'Sundara Kanda, Sarga 13, Verse 26', 'ह्रियमाणा तदा तेन रक्षसा कामरूपिणा।
यथारूपा हि दृष्टा वै तथारूपेयमङ्गना॥', 'hriyamāṇā tadā tena rakṣasā kāmarūpiṇā
yathārūpā hi dṛṣṭā vai tathārūpeyam aṅganā', null, 5013026),
('ramayana-5-13-27', 27, 'Sundara Kanda, Sarga 13, Verse 27', 'पूर्णचन्द्राननां सुभ्रूं चारुवृत्तपयोधराम्।
कुर्वन्तीं प्रभया देवीं सर्वा वितिमिरा दिशः॥', 'pūrṇacandrānanāṃ subhrūṃ cāruvṛttapayodharām
kurvantīṃ prabhayā devīṃ sarvā vitimirā diśaḥ', null, 5013027),
('ramayana-5-13-28', 28, 'Sundara Kanda, Sarga 13, Verse 28', 'तां नीलकेशीं बिम्बौष्ठीं सुमध्यां सुप्रतिष्ठिताम्।
सीतां पद्मपलाशाक्षीं मन्मथस्य रतिं यथा॥', 'tāṃ nīlakeśīṃ bimbauṣṭhīṃ sumadhyāṃ supratiṣṭhitām
sītāṃ padmapalāśākṣīṃ manmathasya ratiṃ yathā', null, 5013028),
('ramayana-5-13-29', 29, 'Sundara Kanda, Sarga 13, Verse 29', 'इष्टां सर्वस्य जगतः पूर्णचन्द्रप्रभामिव।
भूमौ सुतनुमासीनां नियतामिव तापसीम्॥', 'iṣṭāṃ sarvasya jagataḥ pūrṇacandraprabhām iva
bhūmau sutanum āsīnāṃ niyatām iva tāpasīm', null, 5013029),
('ramayana-5-13-30', 30, 'Sundara Kanda, Sarga 13, Verse 30', 'निःश्वासबहुलां भीरुं भुजगेन्द्रवधूमिव।
शोकजालेन महता विततेन न राजतीम्॥', 'niḥśvāsabahulāṃ bhīruṃ bhujagendravadhūm iva
śokajālena mahatā vitatena na rājatīm', null, 5013030),
('ramayana-5-13-31', 31, 'Sundara Kanda, Sarga 13, Verse 31', 'संसक्तां धूमजालेन शिखामिव विभावसोः।
तां स्मृतीमिव संदिग्धामृद्धिं निपतितामिव॥', 'saṃsaktāṃ dhūmajālena śikhām iva vibhāvasoḥ
tāṃ smṛtīm iva saṃdigdhām ṛddhiṃ nipatitām iva', null, 5013031),
('ramayana-5-13-32', 32, 'Sundara Kanda, Sarga 13, Verse 32', 'विहतामिव च श्रद्धामाशां प्रतिहतामिव।
सोपसर्गां यथा सिद्धिं बुद्धिं सकलुषामिव॥', 'vihatām iva ca śraddhām āśāṃ pratihatām iva
sopasargāṃ yathā siddhiṃ buddhiṃ sakaluṣām iva', null, 5013032),
('ramayana-5-13-33', 33, 'Sundara Kanda, Sarga 13, Verse 33', 'अभूतेनापवादेन कीर्तिं निपतितामिव।
रामोपरोधव्यथितां रक्षोहरणकर्शिताम्॥', 'abhūtenāpavādena kīrtiṃ nipatitām iva
rāmoparodhavyathitāṃ rakṣoharaṇakarśitām', null, 5013033),
('ramayana-5-13-34', 34, 'Sundara Kanda, Sarga 13, Verse 34', 'अबलां मृगशावाक्षीं वीक्षमाणां ततस्ततः।
बाष्पाम्बुप्रतिपूर्णेन कृष्णवक्त्राक्षिपक्ष्मणा।
वदनेनाप्रसन्नेन निःश्वसन्तीं पुनः पुनः॥', 'abalāṃ mṛgaśāvākṣīṃ vīkṣamāṇāṃ tatas tataḥ
bāṣpāmbupratipūrṇena kṛṣṇavaktrākṣipakṣmaṇā
vadanenāprasannena niḥśvasantīṃ punaḥ punaḥ', null, 5013034),
('ramayana-5-13-35', 35, 'Sundara Kanda, Sarga 13, Verse 35', 'मलपङ्कधरां दीनां मण्डनार्हाममण्डिताम्।
प्रभां नक्षत्रराजस्य कालमेघैरिवावृताम्॥', 'malapaṅkadharāṃ dīnāṃ maṇḍanārhām amaṇḍitām
prabhāṃ nakṣatrarājasya kālameghair ivāvṛtām', null, 5013035),
('ramayana-5-13-36', 36, 'Sundara Kanda, Sarga 13, Verse 36', 'तस्य संदिदिहे बुद्धिर्मुहुः सीतां निरीक्ष्य तु।
आम्नायानामयोगेन विद्यां प्रशिथिलामिव॥', 'tasya saṃdidihe buddhir muhuḥ sītāṃ nirīkṣya tu
āmnāyānām ayogena vidyāṃ praśithilām iva', null, 5013036),
('ramayana-5-13-37', 37, 'Sundara Kanda, Sarga 13, Verse 37', 'दुःखेन बुबुधे सीतां हनुमाननलंकृताम्।
संस्कारेण यथाहीनां वाचमर्थान्तरं गताम्॥', 'duḥkhena bubudhe sītāṃ hanumān analaṃkṛtām
saṃskāreṇa yathāhīnāṃ vācam arthāntaraṃ gatām', null, 5013037),
('ramayana-5-13-38', 38, 'Sundara Kanda, Sarga 13, Verse 38', 'तां समीक्ष्य विशालाक्षीं राजपुत्रीमनिन्दिताम्।
तर्कयामास सीतेति कारणैरुपपादयन्॥', 'tāṃ samīkṣya viśālākṣīṃ rājaputrīm aninditām
tarkayām āsa sīteti kāraṇair upapādayan', null, 5013038),
('ramayana-5-13-39', 39, 'Sundara Kanda, Sarga 13, Verse 39', 'वैदेह्या यानि चाङ्गेषु तदा रामोऽन्वकीर्तयत्।
तान्याभरणजालानि गात्रशोभीन्यलक्षयत्॥', 'vaidehyā yāni cāṅgeṣu tadā rāmo ''nvakīrtayat
tāny ābharaṇajālāni gātraśobhīny alakṣayat', null, 5013039),
('ramayana-5-13-40', 40, 'Sundara Kanda, Sarga 13, Verse 40', 'सुकृतौ कर्णवेष्टौ च श्वदंष्ट्रौ च सुसंस्थितौ।
मणिविद्रुमचित्राणि हस्तेष्वाभरणानि च॥', 'sukṛtau karṇaveṣṭau ca śvadaṃṣṭrau ca susaṃsthitau
maṇividrumacitrāṇi hasteṣv ābharaṇāni ca', null, 5013040),
('ramayana-5-13-41', 41, 'Sundara Kanda, Sarga 13, Verse 41', 'श्यामानि चिरयुक्तत्वात्तथा संस्थानवन्ति च।
तान्येवैतानि मन्येऽहं यानि रामोऽव्नकीर्तयत्॥', 'śyāmāni cirayuktatvāt tathā saṃsthānavanti ca
tāny evaitāni manye ''haṃ yāni rāmo ''vnakīrtayat', null, 5013041),
('ramayana-5-13-42', 42, 'Sundara Kanda, Sarga 13, Verse 42', 'तत्र यान्यवहीनानि तान्यहं नोपलक्षये।
यान्यस्या नावहीनानि तानीमानि न संशयः॥', 'tatra yāny avahīnāni tāny ahaṃ nopalakṣaye
yāny asyā nāvahīnāni tānīmāni na saṃśayaḥ', null, 5013042),
('ramayana-5-13-43', 43, 'Sundara Kanda, Sarga 13, Verse 43', 'पीतं कनकपट्टाभं स्रस्तं तद्वसनं शुभम्।
उत्तरीयं नगासक्तं तदा दृष्टं प्लवंगमैः॥', 'pītaṃ kanakapaṭṭābhaṃ srastaṃ tad vasanaṃ śubham
uttarīyaṃ nagāsaktaṃ tadā dṛṣṭaṃ plavaṃgamaiḥ', null, 5013043),
('ramayana-5-13-44', 44, 'Sundara Kanda, Sarga 13, Verse 44', 'भूषणानि च मुख्यानि दृष्टानि धरणीतले।
अनयैवापविद्धानि स्वनवन्ति महान्ति च॥', 'bhūṣaṇāni ca mukhyāni dṛṣṭāni dharaṇītale
anayaivāpaviddhāni svanavanti mahānti ca', null, 5013044),
('ramayana-5-13-45', 45, 'Sundara Kanda, Sarga 13, Verse 45', 'इदं चिरगृहीतत्वाद्वसनं क्लिष्टवत्तरम्।
तथा हि नूनं तद्वर्णं तथा श्रीमद्यथेतरत्॥', 'idaṃ ciragṛhītatvād vasanaṃ kliṣṭavattaram
tathā hi nūnaṃ tad varṇaṃ tathā śrīmad yathetarat', null, 5013045),
('ramayana-5-13-46', 46, 'Sundara Kanda, Sarga 13, Verse 46', 'इयं कनकवर्णाङ्गी रामस्य महिषी प्रिया।
प्रनष्टापि सती यस्य मनसो न प्रणश्यति॥', 'iyaṃ kanakavarṇāṅgī rāmasya mahiṣī priyā
pranaṣṭāpi satī yasya manaso na praṇaśyati', null, 5013046),
('ramayana-5-13-47', 47, 'Sundara Kanda, Sarga 13, Verse 47', 'इयं सा यत्कृते रामश्चतुर्भिः परितप्यते।
कारुण्येनानृशंस्येन शोकेन मदनेन च॥', 'iyaṃ sā yat kṛte rāmaś caturbhiḥ paritapyate
kāruṇyenānṛśaṃsyena śokena madanena ca', null, 5013047),
('ramayana-5-13-48', 48, 'Sundara Kanda, Sarga 13, Verse 48', 'स्त्री प्रनष्टेति कारुण्यादाश्रितेत्यानृशंस्यतः।
पत्नी नष्टेति शोकेन प्रियेति मदनेन च॥', 'strī pranaṣṭeti kāruṇyād āśritety ānṛśaṃsyataḥ
patnī naṣṭeti śokena priyeti madanena ca', null, 5013048),
('ramayana-5-13-49', 49, 'Sundara Kanda, Sarga 13, Verse 49', 'अस्या देव्या यथा रूपमङ्गप्रत्यङ्गसौष्ठवम्।
रामस्य च यथारूपं तस्येयमसितेक्षणा॥', 'asyā devyā yathā rūpam aṅgapratyaṅgasauṣṭhavam
rāmasya ca yathārūpaṃ tasyeyam asitekṣaṇā', null, 5013049),
('ramayana-5-13-50', 50, 'Sundara Kanda, Sarga 13, Verse 50', 'अस्या देव्या मनस्तस्मिंस्तस्य चास्यां प्रतिष्ठितम्।
तेनेयं स च धर्मात्मा मुहूर्तमपि जीवति॥', 'asyā devyā manas tasmiṃs tasya cāsyāṃ pratiṣṭhitam
teneyaṃ sa ca dharmātmā muhūrtam api jīvati', null, 5013050),
('ramayana-5-13-51', 51, 'Sundara Kanda, Sarga 13, Verse 51', 'दुष्करं कुरुते रामो य इमां मत्तकाशिनीम्।
सीतां विना महाबाहुर्मुहूर्तमपि जीवति॥', 'duṣkaraṃ kurute rāmo ya imāṃ mattakāśinīm
sītāṃ vinā mahābāhur muhūrtam api jīvati', null, 5013051),
('ramayana-5-13-52', 52, 'Sundara Kanda, Sarga 13, Verse 52', 'एवं सीतां तदा दृष्ट्वा हृष्टः पवनसंभवः।
जगाम मनसा रामं प्रशशंस च तं प्रभुम्॥', 'evaṃ sītāṃ tadā dṛṣṭvā hṛṣṭaḥ pavanasaṃbhavaḥ
jagāma manasā rāmaṃ praśaśaṃsa ca taṃ prabhum', null, 5013052)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 14 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-14-1', 1, 'Sundara Kanda, Sarga 14, Verse 1', 'प्रशस्य तु प्रशस्तव्यां सीतां तां हरिपुंगवः।
गुणाभिरामं रामं च पुनश्चिन्तापरोऽभवत्॥', 'praśasya tu praśastavyāṃ sītāṃ tāṃ haripuṃgavaḥ
guṇābhirāmaṃ rāmaṃ ca punaś cintāparo ''bhavat', null, 5014001),
('ramayana-5-14-2', 2, 'Sundara Kanda, Sarga 14, Verse 2', 'स मुहूर्तमिव ध्यात्वा बाष्पपर्याकुलेक्षणः।
सीतामाश्रित्य तेजस्वी हनुमान्विललाप ह॥', 'sa muhūrtam iva dhyātvā bāṣpaparyākulekṣaṇaḥ
sītām āśritya tejasvī hanumān vilalāpa ha', null, 5014002),
('ramayana-5-14-3', 3, 'Sundara Kanda, Sarga 14, Verse 3', 'मान्या गुरुविनीतस्य लक्ष्मणस्य गुरुप्रिया।
यदि सीतापि दुःखार्ता कालो हि दुरतिक्रमः॥', 'mānyā guruvinītasya lakṣmaṇasya gurupriyā
yadi sītāpi duḥkhārtā kālo hi duratikramaḥ', null, 5014003),
('ramayana-5-14-4', 4, 'Sundara Kanda, Sarga 14, Verse 4', 'रामस्य व्यवसायज्ञा लक्ष्मणस्य च धीमतः।
नात्यर्थं क्षुभ्यते देवी गङ्गेव जलदागमे॥', 'rāmasya vyavasāyajñā lakṣmaṇasya ca dhīmataḥ
nātyarthaṃ kṣubhyate devī gaṅgeva jaladāgame', null, 5014004),
('ramayana-5-14-5', 5, 'Sundara Kanda, Sarga 14, Verse 5', 'तुल्यशीलवयोवृत्तां तुल्याभिजनलक्षणाम्।
राघवोऽर्हति वैदेहीं तं चेयमसितेक्षणा॥', 'tulyaśīlavayovṛttāṃ tulyābhijanalakṣaṇām
rāghavo ''rhati vaidehīṃ taṃ ceyam asitekṣaṇā', null, 5014005),
('ramayana-5-14-6', 6, 'Sundara Kanda, Sarga 14, Verse 6', 'तां दृष्ट्वा नवहेमाभां लोककान्तामिव श्रियम्।
जगाम मनसा रामं वचनं चेदमब्रवीत्॥', 'tāṃ dṛṣṭvā navahemābhāṃ lokakāntām iva śriyam
jagāma manasā rāmaṃ vacanaṃ cedam abravīt', null, 5014006),
('ramayana-5-14-7', 7, 'Sundara Kanda, Sarga 14, Verse 7', 'अस्या हेतोर्विशालाक्ष्या हतो वाली महाबलः।
रावणप्रतिमो वीर्ये कबन्धश्च निपातितः॥', 'asyā hetor viśālākṣyā hato vālī mahābalaḥ
rāvaṇapratimo vīrye kabandhaś ca nipātitaḥ', null, 5014007),
('ramayana-5-14-8', 8, 'Sundara Kanda, Sarga 14, Verse 8', 'विराधश्च हतः संख्ये राक्षसो भीमविक्रमः।
वने रामेण विक्रम्य महेन्द्रेणेव शम्बरः॥', 'virādhaś ca hataḥ saṃkhye rākṣaso bhīmavikramaḥ
vane rāmeṇa vikramya mahendreṇeva śambaraḥ', null, 5014008),
('ramayana-5-14-9', 9, 'Sundara Kanda, Sarga 14, Verse 9', 'चतुर्दशसहस्राणि रक्षसां भीमकर्मणाम्।
निहतानि जनस्थाने शरैरग्निशिखोपमैः॥', 'caturdaśasahasrāṇi rakṣasāṃ bhīmakarmaṇām
nihatāni janasthāne śarair agniśikhopamaiḥ', null, 5014009),
('ramayana-5-14-10', 10, 'Sundara Kanda, Sarga 14, Verse 10', 'खरश्च निहतः संख्ये त्रिशिराश्च निपातितः।
दूषणश्च महातेजा रामेण विदितात्मना॥', 'kharaś ca nihataḥ saṃkhye triśirāś ca nipātitaḥ
dūṣaṇaś ca mahātejā rāmeṇa viditātmanā', null, 5014010),
('ramayana-5-14-11', 11, 'Sundara Kanda, Sarga 14, Verse 11', 'ऐश्वर्यं वानराणां च दुर्लभं वालिपालितम्।
अस्या निमित्ते सुग्रीवः प्राप्तवांल्लोकसत्कृतम्॥', 'aiśvaryaṃ vānarāṇāṃ ca durlabhaṃ vālipālitam
asyā nimitte sugrīvaḥ prāptavāṃl lokasatkṛtam', null, 5014011),
('ramayana-5-14-12', 12, 'Sundara Kanda, Sarga 14, Verse 12', 'सागरश्च मया क्रान्तः श्रीमान्नदनदीपतिः।
अस्या हेतोर्विशालाक्ष्याः पुरी चेयं निरीक्षिता॥', 'sāgaraś ca mayā krāntaḥ śrīmān nadanadīpatiḥ
asyā hetor viśālākṣyāḥ purī ceyaṃ nirīkṣitā', null, 5014012),
('ramayana-5-14-13', 13, 'Sundara Kanda, Sarga 14, Verse 13', 'यदि रामः समुद्रान्तां मेदिनीं परिवर्तयेत्।
अस्याः कृते जगच्चापि युक्तमित्येव मे मतिः॥', 'yadi rāmaḥ samudrāntāṃ medinīṃ parivartayet
asyāḥ kṛte jagac cāpi yuktam ity eva me matiḥ', null, 5014013),
('ramayana-5-14-14', 14, 'Sundara Kanda, Sarga 14, Verse 14', 'राज्यं वा त्रिषु लोकेषु सीता वा जनकात्मजा।
त्रैलोक्यराज्यं सकलं सीताया नाप्नुयात्कलाम्॥', 'rājyaṃ vā triṣu lokeṣu sītā vā janakātmajā
trailokyarājyaṃ sakalaṃ sītāyā nāpnuyāt kalām', null, 5014014),
('ramayana-5-14-15', 15, 'Sundara Kanda, Sarga 14, Verse 15', 'इयं सा धर्मशीलस्य मैथिलस्य महात्मनः।
सुता जनकराजस्य सीता भर्तृदृढव्रता॥', 'iyaṃ sā dharmaśīlasya maithilasya mahātmanaḥ
sutā janakarājasya sītā bhartṛdṛḍhavratā', null, 5014015),
('ramayana-5-14-16', 16, 'Sundara Kanda, Sarga 14, Verse 16', 'उत्थिता मेदिनीं भित्त्वा क्षेत्रे हलमुखक्षते।
पद्मरेणुनिभैः कीर्णा शुभैः केदारपांसुभिः॥', 'utthitā medinīṃ bhittvā kṣetre halamukhakṣate
padmareṇunibhaiḥ kīrṇā śubhaiḥ kedārapāṃsubhiḥ', null, 5014016),
('ramayana-5-14-17', 17, 'Sundara Kanda, Sarga 14, Verse 17', 'विक्रान्तस्यार्यशीलस्य संयुगेष्वनिवर्तिनः।
स्नुषा दशरथस्यैषा ज्येष्ठा राज्ञो यशस्विनी॥', 'vikrāntasyāryaśīlasya saṃyugeṣv anivartinaḥ
snuṣā daśarathasyaiṣā jyeṣṭhā rājño yaśasvinī', null, 5014017),
('ramayana-5-14-18', 18, 'Sundara Kanda, Sarga 14, Verse 18', 'धर्मज्ञस्य कृतज्ञस्य रामस्य विदितात्मनः।
इयं सा दयिता भार्या राक्षसी वशमागता॥', 'dharmajñasya kṛtajñasya rāmasya viditātmanaḥ
iyaṃ sā dayitā bhāryā rākṣasī vaśam āgatā', null, 5014018),
('ramayana-5-14-19', 19, 'Sundara Kanda, Sarga 14, Verse 19', 'सर्वान्भोगान्परित्यज्य भर्तृस्नेहबलात्कृता।
अचिन्तयित्वा दुःखानि प्रविष्टा निर्जनं वनम्॥', 'sarvān bhogān parityajya bhartṛsnehabalāt kṛtā
acintayitvā duḥkhāni praviṣṭā nirjanaṃ vanam', null, 5014019),
('ramayana-5-14-20', 20, 'Sundara Kanda, Sarga 14, Verse 20', 'संतुष्टा फलमूलेन भर्तृशुश्रूषणे रता।
या परां भजते प्रीतिं वनेऽपि भवने यथा॥', 'saṃtuṣṭā phalamūlena bhartṛśuśrūṣaṇe ratā
yā parāṃ bhajate prītiṃ vane ''pi bhavane yathā', null, 5014020),
('ramayana-5-14-21', 21, 'Sundara Kanda, Sarga 14, Verse 21', 'सेयं कनकवर्णाङ्गी नित्यं सुस्मितभाषिणी।
सहते यातनामेतामनर्थानामभागिनी॥', 'seyaṃ kanakavarṇāṅgī nityaṃ susmitabhāṣiṇī
sahate yātanām etām anarthānām abhāginī', null, 5014021),
('ramayana-5-14-22', 22, 'Sundara Kanda, Sarga 14, Verse 22', 'इमां तु शीलसंपन्नां द्रष्टुमिच्छति राघवः।
रावणेन प्रमथितां प्रपामिव पिपासितः॥', 'imāṃ tu śīlasaṃpannāṃ draṣṭum icchati rāghavaḥ
rāvaṇena pramathitāṃ prapām iva pipāsitaḥ', null, 5014022),
('ramayana-5-14-23', 23, 'Sundara Kanda, Sarga 14, Verse 23', 'अस्या नूनं पुनर्लाभाद्राघवः प्रीतिमेष्यति।
राजा राज्यपरिभ्रष्टः पुनः प्राप्येव मेदिनीम्॥', 'asyā nūnaṃ punar lābhād rāghavaḥ prītim eṣyati
rājā rājyaparibhraṣṭaḥ punaḥ prāpyeva medinīm', null, 5014023),
('ramayana-5-14-24', 24, 'Sundara Kanda, Sarga 14, Verse 24', 'कामभोगैः परित्यक्ता हीना बन्धुजनेन च।
धारयत्यात्मनो देहं तत्समागमकाङ्क्षिणी॥', 'kāmabhogaiḥ parityaktā hīnā bandhujanena ca
dhārayaty ātmano dehaṃ tatsamāgamakāṅkṣiṇī', null, 5014024),
('ramayana-5-14-25', 25, 'Sundara Kanda, Sarga 14, Verse 25', 'नैषा पश्यति राक्षस्यो नेमान्पुष्पफलद्रुमान्।
एकस्थहृदया नूनं राममेवानुपश्यति॥', 'naiṣā paśyati rākṣasyo nemān puṣpaphaladrumān
ekasthahṛdayā nūnaṃ rāmam evānupaśyati', null, 5014025),
('ramayana-5-14-26', 26, 'Sundara Kanda, Sarga 14, Verse 26', 'भर्ता नाम परं नार्या भूषणं भूषणादपि।
एषा हि रहिता तेन शोभनार्हा न शोभते॥', 'bhartā nāma paraṃ nāryā bhūṣaṇaṃ bhūṣaṇād api
eṣā hi rahitā tena śobhanārhā na śobhate', null, 5014026),
('ramayana-5-14-27', 27, 'Sundara Kanda, Sarga 14, Verse 27', 'दुष्करं कुरुते रामो हीनो यदनया प्रभुः।
धारयत्यात्मनो देहं न दुःखेनावसीदति॥', 'duṣkaraṃ kurute rāmo hīno yad anayā prabhuḥ
dhārayaty ātmano dehaṃ na duḥkhenāvasīdati', null, 5014027),
('ramayana-5-14-28', 28, 'Sundara Kanda, Sarga 14, Verse 28', 'इमामसितकेशान्तां शतपत्रनिभेक्षणाम्।
सुखार्हां दुःखितां दृष्ट्वा ममापि व्यथितं मनः॥', 'imām asitakeśāntāṃ śatapatranibhekṣaṇām
sukhārhāṃ duḥkhitāṃ dṛṣṭvā mamāpi vyathitaṃ manaḥ', null, 5014028),
('ramayana-5-14-29', 29, 'Sundara Kanda, Sarga 14, Verse 29', 'क्षितिक्षमा पुष्करसंनिभाक्षी या रक्षिता राघवलक्ष्मणाभ्याम्।
सा राक्षसीभिर्विकृतेक्षणाभिः संरक्ष्यते संप्रति वृक्षमूले॥', 'kṣitikṣamā puṣkarasaṃnibhākṣī yā rakṣitā rāghavalakṣmaṇābhyām
sā rākṣasībhir vikṛtekṣaṇābhiḥ saṃrakṣyate saṃprati vṛkṣamūle', null, 5014029),
('ramayana-5-14-30', 30, 'Sundara Kanda, Sarga 14, Verse 30', 'हिमहतनलिनीव नष्टशोभा व्यसनपरम्परया निपीड्यमाना।
सहचररहितेव चक्रवाकी जनकसुता कृपणां दशां प्रपन्ना॥', 'himahatanalinīva naṣṭaśobhā vyasanaparamparayā nipīḍyamānā
sahacararahiteva cakravākī janakasutā kṛpaṇāṃ daśāṃ prapannā', null, 5014030),
('ramayana-5-14-31', 31, 'Sundara Kanda, Sarga 14, Verse 31', 'अस्या हि पुष्पावनताग्रशाखाः शोकं दृढं वै जनयत्यशोकाः।
हिमव्यपायेन च मन्दरश्मिरभ्युत्थितो नैकसहस्ररश्मिः॥', 'asyā hi puṣpāvanatāgraśākhāḥ śokaṃ dṛḍhaṃ vai janayaty aśokāḥ
himavyapāyena ca mandaraśmir abhyutthito naikasahasraraśmiḥ', null, 5014031),
('ramayana-5-14-32', 32, 'Sundara Kanda, Sarga 14, Verse 32', 'इत्येवमर्थं कपिरन्ववेक्ष्य सीतेयमित्येव निविष्टबुद्धिः।
संश्रित्य तस्मिन्निषसाद वृक्षे बली हरीणामृषभस्तरस्वी॥', 'ity evam arthaṃ kapir anvavekṣya sīteyam ity eva niviṣṭabuddhiḥ
saṃśritya tasmin niṣasāda vṛkṣe balī harīṇām ṛṣabhas tarasvī', null, 5014032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 15 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-15-1', 1, 'Sundara Kanda, Sarga 15, Verse 1', 'ततः कुमुदषण्डाभो निर्मलं निर्मलः स्वयम्।
प्रजगाम नभश्चन्द्रो हंसो नीलमिवोदकम्॥', 'tataḥ kumudaṣaṇḍābho nirmalaṃ nirmalaḥ svayam
prajagāma nabhaś candro haṃso nīlam ivodakam', null, 5015001),
('ramayana-5-15-2', 2, 'Sundara Kanda, Sarga 15, Verse 2', 'साचिव्यमिव कुर्वन्स प्रभया निर्मलप्रभः।
चन्द्रमा रश्मिभिः शीतैः सिषेवे पवनात्मजम्॥', 'sācivyam iva kurvan sa prabhayā nirmalaprabhaḥ
candramā raśmibhiḥ śītaiḥ siṣeve pavanātmajam', null, 5015002),
('ramayana-5-15-3', 3, 'Sundara Kanda, Sarga 15, Verse 3', 'स ददर्श ततः सीतां पूर्णचन्द्रनिभाननाम्।
शोकभारैरिव न्यस्तां भारैर्नावमिवाम्भसि॥', 'sa dadarśa tataḥ sītāṃ pūrṇacandranibhānanām
śokabhārair iva nyastāṃ bhārair nāvam ivāmbhasi', null, 5015003),
('ramayana-5-15-4', 4, 'Sundara Kanda, Sarga 15, Verse 4', 'दिदृक्षमाणो वैदेहीं हनूमान्मारुतात्मजः।
स ददर्शाविदूरस्था राक्षसीर्घोरदर्शनाः॥', 'didṛkṣamāṇo vaidehīṃ hanūmān mārutātmajaḥ
sa dadarśāvidūrasthā rākṣasīr ghoradarśanāḥ', null, 5015004),
('ramayana-5-15-5', 5, 'Sundara Kanda, Sarga 15, Verse 5', 'एकाक्षीमेककर्णां च कर्णप्रावरणां तथा।
अकर्णां शङ्कुकर्णां च मस्तकोच्छ्वासनासिकाम्॥', 'ekākṣīm ekakarṇāṃ ca karṇaprāvaraṇāṃ tathā
akarṇāṃ śaṅkukarṇāṃ ca mastakocchvāsanāsikām', null, 5015005),
('ramayana-5-15-6', 6, 'Sundara Kanda, Sarga 15, Verse 6', 'अतिकायोत्तमाङ्गीं च तनुदीर्घशिरोधराम्।
ध्वस्तकेशीं तथाकेशीं केशकम्बलधारिणीम्॥', 'atikāyottamāṅgīṃ ca tanudīrghaśirodharām
dhvastakeśīṃ tathākeśīṃ keśakambaladhāriṇīm', null, 5015006),
('ramayana-5-15-7', 7, 'Sundara Kanda, Sarga 15, Verse 7', 'लम्बकर्णललाटां च लम्बोदरपयोधराम्।
लम्बौष्ठीं चिबुकौष्ठीं च लम्बास्यां लम्बजानुकाम्॥', 'lambakarṇalalāṭāṃ ca lambodarapayodharām
lambauṣṭhīṃ cibukauṣṭhīṃ ca lambāsyāṃ lambajānukām', null, 5015007),
('ramayana-5-15-8', 8, 'Sundara Kanda, Sarga 15, Verse 8', 'ह्रस्वां दीर्घां च कुब्जां च विकटां वामनां तथा।
करालां भुग्नवस्त्रां च पिङ्गाक्षीं विकृताननाम्॥', 'hrasvāṃ dīrghāṃ ca kubjāṃ ca vikaṭāṃ vāmanāṃ tathā
karālāṃ bhugnavastrāṃ ca piṅgākṣīṃ vikṛtānanām', null, 5015008),
('ramayana-5-15-9', 9, 'Sundara Kanda, Sarga 15, Verse 9', 'विकृताः पिङ्गलाः कालीः क्रोधनाः कलहप्रियाः।
कालायसमहाशूलकूटमुद्गरधारिणीः॥', 'vikṛtāḥ piṅgalāḥ kālīḥ krodhanāḥ kalahapriyāḥ
kālāyasamahāśūlakūṭamudgaradhāriṇīḥ', null, 5015009),
('ramayana-5-15-10', 10, 'Sundara Kanda, Sarga 15, Verse 10', 'वराहमृगशार्दूलमहिषाजशिवा मुखाः।
गजोष्ट्रहयपादाश्च निखातशिरसोऽपराः॥', 'varāhamṛgaśārdūlamahiṣājaśivā mukhāḥ
gajoṣṭrahayapādāś ca nikhātaśiraso ''parāḥ', null, 5015010),
('ramayana-5-15-11', 11, 'Sundara Kanda, Sarga 15, Verse 11', 'एकहस्तैकपादाश्च खरकर्ण्यश्वकर्णिकाः।
गोकर्णीर्हस्तिकर्णीश्च हरिकर्णीस्तथापराः॥', 'ekahastaikapādāś ca kharakarṇyaśvakarṇikāḥ
gokarṇīr hastikarṇīś ca harikarṇīs tathāparāḥ', null, 5015011),
('ramayana-5-15-12', 12, 'Sundara Kanda, Sarga 15, Verse 12', 'अनासा अतिनासाश्च तिर्यन्नासा विनासिकाः।
गजसंनिभनासाश्च ललाटोच्छ्वासनासिकाः॥', 'anāsā atināsāś ca tiryan nāsā vināsikāḥ
gajasaṃnibhanāsāś ca lalāṭocchvāsanāsikāḥ', null, 5015012),
('ramayana-5-15-13', 13, 'Sundara Kanda, Sarga 15, Verse 13', 'हस्तिपादा महापादा गोपादाः पादचूलिकाः।
अतिमात्रशिरोग्रीवा अतिमात्रकुचोदरीः॥', 'hastipādā mahāpādā gopādāḥ pādacūlikāḥ
atimātraśirogrīvā atimātrakucodarīḥ', null, 5015013),
('ramayana-5-15-14', 14, 'Sundara Kanda, Sarga 15, Verse 14', 'अतिमात्रास्य नेत्राश्च दीर्घजिह्वानखास्तथा।
अजामुखीर्हस्तिमुखीर्गोमुखीः सूकरीमुखीः॥', 'atimātrāsya netrāś ca dīrghajihvānakhās tathā
ajāmukhīr hastimukhīr gomukhīḥ sūkarīmukhīḥ', null, 5015014),
('ramayana-5-15-15', 15, 'Sundara Kanda, Sarga 15, Verse 15', 'हयोष्ट्रखरवक्त्राश्च राक्षसीर्घोरदर्शनाः।
शूलमुद्गरहस्ताश्च क्रोधनाः कलहप्रियाः॥', 'hayoṣṭrakharavaktrāś ca rākṣasīr ghoradarśanāḥ
śūlamudgarahastāś ca krodhanāḥ kalahapriyāḥ', null, 5015015),
('ramayana-5-15-16', 16, 'Sundara Kanda, Sarga 15, Verse 16', 'कराला धूम्रकेशीश्च रक्षसीर्विकृताननाः।
पिबन्तीः सततं पानं सदा मांससुराप्रियाः॥', 'karālā dhūmrakeśīś ca rakṣasīr vikṛtānanāḥ
pibantīḥ satataṃ pānaṃ sadā māṃsasurāpriyāḥ', null, 5015016),
('ramayana-5-15-17', 17, 'Sundara Kanda, Sarga 15, Verse 17', 'मांसशोणितदिग्धाङ्गीर्मांसशोणितभोजनाः।
ता ददर्श कपिश्रेष्ठो रोमहर्षणदर्शनाः॥', 'māṃsaśoṇitadigdhāṅgīr māṃsaśoṇitabhojanāḥ
tā dadarśa kapiśreṣṭho romaharṣaṇadarśanāḥ', null, 5015017),
('ramayana-5-15-18', 18, 'Sundara Kanda, Sarga 15, Verse 18', 'स्कन्धवन्तमुपासीनाः परिवार्य वनस्पतिम्।
तस्याधस्ताच्च तां देवीं राजपुत्रीमनिन्दिताम्॥', 'skandhavantam upāsīnāḥ parivārya vanaspatim
tasyādhastāc ca tāṃ devīṃ rājaputrīm aninditām', null, 5015018),
('ramayana-5-15-19', 19, 'Sundara Kanda, Sarga 15, Verse 19', 'लक्षयामास लक्ष्मीवान्हनूमाञ्जनकात्मजाम्।
निष्प्रभां शोकसंतप्तां मलसंकुलमूर्धजाम्॥', 'lakṣayām āsa lakṣmīvān hanūmāñ janakātmajām
niṣprabhāṃ śokasaṃtaptāṃ malasaṃkulamūrdhajām', null, 5015019),
('ramayana-5-15-20', 20, 'Sundara Kanda, Sarga 15, Verse 20', 'क्षीणपुण्यां च्युतां भूमौ तारां निपतितामिव।
चारित्र्य व्यपदेशाढ्यां भर्तृदर्शनदुर्गताम्॥', 'kṣīṇapuṇyāṃ cyutāṃ bhūmau tārāṃ nipatitām iva
cāritrya vyapadeśāḍhyāṃ bhartṛdarśanadurgatām', null, 5015020),
('ramayana-5-15-21', 21, 'Sundara Kanda, Sarga 15, Verse 21', 'भूषणैरुत्तमैर्हीनां भर्तृवात्सल्यभूषिताम्।
राक्षसाधिपसंरुद्धां बन्धुभिश्च विनाकृताम्॥', 'bhūṣaṇair uttamair hīnāṃ bhartṛvātsalyabhūṣitām
rākṣasādhipasaṃruddhāṃ bandhubhiś ca vinākṛtām', null, 5015021),
('ramayana-5-15-22', 22, 'Sundara Kanda, Sarga 15, Verse 22', 'वियूथां सिंहसंरुद्धां बद्धां गजवधूमिव।
चन्द्रलेखां पयोदान्ते शारदाभ्रैरिवावृताम्॥', 'viyūthāṃ siṃhasaṃruddhāṃ baddhāṃ gajavadhūm iva
candralekhāṃ payodānte śāradābhrair ivāvṛtām', null, 5015022),
('ramayana-5-15-23', 23, 'Sundara Kanda, Sarga 15, Verse 23', 'क्लिष्टरूपामसंस्पर्शादयुक्तामिव वल्लकीम्।
सीतां भर्तृहिते युक्तामयुक्तां रक्षसां वशे॥', 'kliṣṭarūpām asaṃsparśād ayuktām iva vallakīm
sītāṃ bhartṛhite yuktām ayuktāṃ rakṣasāṃ vaśe', null, 5015023),
('ramayana-5-15-24', 24, 'Sundara Kanda, Sarga 15, Verse 24', 'अशोकवनिकामध्ये शोकसागरमाप्लुताम्।
ताभिः परिवृतां तत्र सग्रहामिव रोहिणीम्।
ददर्श हनुमान्देवीं लतामकुसुमामिव॥', 'aśokavanikāmadhye śokasāgaram āplutām
tābhiḥ parivṛtāṃ tatra sagrahām iva rohiṇīm
dadarśa hanumān devīṃ latām akusumām iva', null, 5015024),
('ramayana-5-15-25', 25, 'Sundara Kanda, Sarga 15, Verse 25', 'सा मलेन च दिग्धाङ्गी वपुषा चाप्यलंकृता।
मृणाली पङ्कदिग्धेव विभाति च न भाति च॥', 'sā malena ca digdhāṅgī vapuṣā cāpy alaṃkṛtā
mṛṇālī paṅkadigdheva vibhāti ca na bhāti ca', null, 5015025),
('ramayana-5-15-26', 26, 'Sundara Kanda, Sarga 15, Verse 26', 'मलिनेन तु वस्त्रेण परिक्लिष्टेन भामिनीम्।
संवृतां मृगशावाक्षीं ददर्श हनुमान्कपिः॥', 'malinena tu vastreṇa parikliṣṭena bhāminīm
saṃvṛtāṃ mṛgaśāvākṣīṃ dadarśa hanumān kapiḥ', null, 5015026),
('ramayana-5-15-27', 27, 'Sundara Kanda, Sarga 15, Verse 27', 'तां देवीं दीनवदनामदीनां भर्तृतेजसा।
रक्षितां स्वेन शीलेन सीतामसितलोचनाम्॥', 'tāṃ devīṃ dīnavadanām adīnāṃ bhartṛtejasā
rakṣitāṃ svena śīlena sītām asitalocanām', null, 5015027),
('ramayana-5-15-28', 28, 'Sundara Kanda, Sarga 15, Verse 28', 'तां दृष्ट्वा हनुमान्सीतां मृगशावनिभेक्षणाम्।
मृगकन्यामिव त्रस्तां वीक्षमाणां समन्ततः॥', 'tāṃ dṛṣṭvā hanumān sītāṃ mṛgaśāvanibhekṣaṇām
mṛgakanyām iva trastāṃ vīkṣamāṇāṃ samantataḥ', null, 5015028),
('ramayana-5-15-29', 29, 'Sundara Kanda, Sarga 15, Verse 29', 'दहन्तीमिव निःश्वासैर्वृक्षान्पल्लवधारिणः।
संघातमिव शोकानां दुःखस्योर्मिमिवोत्थिताम्॥', 'dahantīm iva niḥśvāsair vṛkṣān pallavadhāriṇaḥ
saṃghātam iva śokānāṃ duḥkhasyormim ivotthitām', null, 5015029),
('ramayana-5-15-30', 30, 'Sundara Kanda, Sarga 15, Verse 30', 'तां क्षामां सुविभक्ताङ्गीं विनाभरणशोभिनीम्॥', 'tāṃ kṣāmāṃ suvibhaktāṅgīṃ vinābharaṇaśobhinīm', null, 5015030),
('ramayana-5-15-31', 31, 'Sundara Kanda, Sarga 15, Verse 31', 'प्रहर्षमतुलं लेभे मारुतिः प्रेक्ष्य मैथिलीम्।
हर्षजानि च सोऽश्रूणि तां दृष्ट्वा मदिरेक्षणाम्।
मुमोच हनुमांस्तत्र नमश्चक्रे च राघवम्॥', 'praharṣam atulaṃ lebhe mārutiḥ prekṣya maithilīm
harṣajāni ca so ''śrūṇi tāṃ dṛṣṭvā madirekṣaṇām
mumoca hanumāṃs tatra namaś cakre ca rāghavam', null, 5015031),
('ramayana-5-15-32', 32, 'Sundara Kanda, Sarga 15, Verse 32', 'नमस्कृत्वा च रामाय लक्ष्मणाय च वीर्यवान्।
सीतादर्शनसंहृष्टो हनूमान्संवृतोऽभवत्॥', 'namaskṛtvā ca rāmāya lakṣmaṇāya ca vīryavān
sītādarśanasaṃhṛṣṭo hanūmān saṃvṛto ''bhavat', null, 5015032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 16 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-16-1', 1, 'Sundara Kanda, Sarga 16, Verse 1', 'तथा विप्रेक्षमाणस्य वनं पुष्पितपादपम्।
विचिन्वतश्च वैदेहीं किं चिच्छेषा निशाभवत्॥', 'tathā viprekṣamāṇasya vanaṃ puṣpitapādapam
vicinvataś ca vaidehīṃ kiṃ cic cheṣā niśābhavat', null, 5016001),
('ramayana-5-16-2', 2, 'Sundara Kanda, Sarga 16, Verse 2', 'षडङ्गवेदविदुषां क्रतुप्रवरयाजिनाम्।
शुश्राव ब्रह्मघोषांश्च विरात्रे ब्रह्मरक्षसाम्॥', 'ṣaḍaṅgavedaviduṣāṃ kratupravarayājinām
śuśrāva brahmaghoṣāṃś ca virātre brahmarakṣasām', null, 5016002),
('ramayana-5-16-3', 3, 'Sundara Kanda, Sarga 16, Verse 3', 'अथ मङ्गलवादित्रैः शब्दैः श्रोत्रमनोहरैः।
प्राबोध्यत महाबाहुर्दशग्रीवो महाबलः॥', 'atha maṅgalavāditraiḥ śabdaiḥ śrotramanoharaiḥ
prābodhyata mahābāhur daśagrīvo mahābalaḥ', null, 5016003),
('ramayana-5-16-4', 4, 'Sundara Kanda, Sarga 16, Verse 4', 'विबुध्य तु यथाकालं राक्षसेन्द्रः प्रतावपान्।
स्रस्तमाल्याम्बरधरो वैदेहीमन्वचिन्तयत्॥', 'vibudhya tu yathākālaṃ rākṣasendraḥ pratāvapān
srastamālyāmbaradharo vaidehīm anvacintayat', null, 5016004),
('ramayana-5-16-5', 5, 'Sundara Kanda, Sarga 16, Verse 5', 'भृशं नियुक्तस्तस्यां च मदनेन मदोत्कटः।
न स तं राक्षसः कामं शशाकात्मनि गूहितुम्॥', 'bhṛśaṃ niyuktas tasyāṃ ca madanena madotkaṭaḥ
na sa taṃ rākṣasaḥ kāmaṃ śaśākātmani gūhitum', null, 5016005),
('ramayana-5-16-6', 6, 'Sundara Kanda, Sarga 16, Verse 6', 'स सर्वाभरणैर्युक्तो बिभ्रच्छ्रियमनुत्तमाम्।
तां नगैर्विविधैर्जुष्टां सर्वपुष्पफलोपगैः॥', 'sa sarvābharaṇair yukto bibhrac chriyam anuttamām
tāṃ nagair vividhair juṣṭāṃ sarvapuṣpaphalopagaiḥ', null, 5016006),
('ramayana-5-16-7', 7, 'Sundara Kanda, Sarga 16, Verse 7', 'वृतां पुष्करिणीभिश्च नानापुष्पोपशोभिताम्।
सदामदैश्च विहगैर्विचित्रां परमाद्भुताम्॥', 'vṛtāṃ puṣkariṇībhiś ca nānāpuṣpopaśobhitām
sadāmadaiś ca vihagair vicitrāṃ paramādbhutām', null, 5016007),
('ramayana-5-16-8', 8, 'Sundara Kanda, Sarga 16, Verse 8', 'ईहामृगैश्च विविधैश्वृतां दृष्टिमनोहरैः।
वीथीः संप्रेक्षमाणश्च मणिकाञ्चनतोरणाः॥', 'īhāmṛgaiś ca vividhaiś vṛtāṃ dṛṣṭimanoharaiḥ
vīthīḥ saṃprekṣamāṇaś ca maṇikāñcanatoraṇāḥ', null, 5016008),
('ramayana-5-16-9', 9, 'Sundara Kanda, Sarga 16, Verse 9', 'नानामृगगणाकीर्णां फलैः प्रपतितैर्वृताम्।
अशोकवनिकामेव प्राविशत्संततद्रुमाम्॥', 'nānāmṛgagaṇākīrṇāṃ phalaiḥ prapatitair vṛtām
aśokavanikām eva prāviśat saṃtatadrumām', null, 5016009),
('ramayana-5-16-10', 10, 'Sundara Kanda, Sarga 16, Verse 10', 'अङ्गनाशतमात्रं तु तं व्रजन्तमनुव्रजत्।
महेन्द्रमिव पौलस्त्यं देवगन्धर्वयोषितः॥', 'aṅganāśatamātraṃ tu taṃ vrajantam anuvrajat
mahendram iva paulastyaṃ devagandharvayoṣitaḥ', null, 5016010),
('ramayana-5-16-11', 11, 'Sundara Kanda, Sarga 16, Verse 11', 'दीपिकाः काञ्चनीः काश्चिज्जगृहुस्तत्र योषितः।
बालव्यजनहस्ताश्च तालवृन्तानि चापराः॥', 'dīpikāḥ kāñcanīḥ kāś cij jagṛhus tatra yoṣitaḥ
bālavyajanahastāś ca tālavṛntāni cāparāḥ', null, 5016011),
('ramayana-5-16-12', 12, 'Sundara Kanda, Sarga 16, Verse 12', 'काञ्चनैरपि भृङ्गारैर्जह्रुः सलिलमग्रतः।
मण्डलाग्रानसींश्चैव गृह्यान्याः पृष्ठतो ययुः॥', 'kāñcanair api bhṛṅgārair jahruḥ salilam agrataḥ
maṇḍalāgrān asīṃś caiva gṛhyānyāḥ pṛṣṭhato yayuḥ', null, 5016012),
('ramayana-5-16-13', 13, 'Sundara Kanda, Sarga 16, Verse 13', 'का चिद्रत्नमयीं पात्रीं पूर्णां पानस्य भामिनी।
दक्षिणा दक्षिणेनैव तदा जग्राह पाणिना॥', 'kā cid ratnamayīṃ pātrīṃ pūrṇāṃ pānasya bhāminī
dakṣiṇā dakṣiṇenaiva tadā jagrāha pāṇinā', null, 5016013),
('ramayana-5-16-14', 14, 'Sundara Kanda, Sarga 16, Verse 14', 'राजहंसप्रतीकाशं छत्रं पूर्णशशिप्रभम्।
सौवर्णदण्डमपरा गृहीत्वा पृष्ठतो ययौ॥', 'rājahaṃsapratīkāśaṃ chatraṃ pūrṇaśaśiprabham
sauvarṇadaṇḍam aparā gṛhītvā pṛṣṭhato yayau', null, 5016014),
('ramayana-5-16-15', 15, 'Sundara Kanda, Sarga 16, Verse 15', 'निद्रामदपरीताक्ष्यो रावणस्योत्तमस्त्रियः।
अनुजग्मुः पतिं वीरं घनं विद्युल्लता इव॥', 'nidrāmadaparītākṣyo rāvaṇasyottamastriyaḥ
anujagmuḥ patiṃ vīraṃ ghanaṃ vidyullatā iva', null, 5016015),
('ramayana-5-16-16', 16, 'Sundara Kanda, Sarga 16, Verse 16', 'ततः काञ्चीनिनादं च नूपुराणां च निःस्वनम्।
शुश्राव परमस्त्रीणां स कपिर्मारुतात्मजः॥', 'tataḥ kāñcīninādaṃ ca nūpurāṇāṃ ca niḥsvanam
śuśrāva paramastrīṇāṃ sa kapir mārutātmajaḥ', null, 5016016),
('ramayana-5-16-17', 17, 'Sundara Kanda, Sarga 16, Verse 17', 'तं चाप्रतिमकर्माणमचिन्त्यबलपौरुषम्।
द्वारदेशमनुप्राप्तं ददर्श हनुमान्कपिः॥', 'taṃ cāpratimakarmāṇam acintyabalapauruṣam
dvāradeśam anuprāptaṃ dadarśa hanumān kapiḥ', null, 5016017),
('ramayana-5-16-18', 18, 'Sundara Kanda, Sarga 16, Verse 18', 'दीपिकाभिरनेकाभिः समन्तादवभासितम्।
गन्धतैलावसिक्ताभिर्ध्रियमाणाभिरग्रतः॥', 'dīpikābhir anekābhiḥ samantād avabhāsitam
gandhatailāvasiktābhir dhriyamāṇābhir agrataḥ', null, 5016018),
('ramayana-5-16-19', 19, 'Sundara Kanda, Sarga 16, Verse 19', 'कामदर्पमदैर्युक्तं जिह्मताम्रायतेक्षणम्।
समक्षमिव कन्दर्पमपविद्ध शरासनम्॥', 'kāmadarpamadair yuktaṃ jihmatāmrāyatekṣaṇam
samakṣam iva kandarpam apaviddha śarāsanam', null, 5016019),
('ramayana-5-16-20', 20, 'Sundara Kanda, Sarga 16, Verse 20', 'मथितामृतफेनाभमरजो वस्त्रमुत्तमम्।
सलीलमनुकर्षन्तं विमुक्तं सक्तमङ्गदे॥', 'mathitāmṛtaphenābham arajo vastram uttamam
salīlam anukarṣantaṃ vimuktaṃ saktam aṅgade', null, 5016020),
('ramayana-5-16-21', 21, 'Sundara Kanda, Sarga 16, Verse 21', 'तं पत्रविटपे लीनः पत्रपुष्पघनावृतः।
समीपमुपसंक्रान्तं निध्यातुमुपचक्रमे॥', 'taṃ patraviṭape līnaḥ patrapuṣpaghanāvṛtaḥ
samīpam upasaṃkrāntaṃ nidhyātum upacakrame', null, 5016021),
('ramayana-5-16-22', 22, 'Sundara Kanda, Sarga 16, Verse 22', 'अवेक्षमाणश्च ततो ददर्श कपिकुञ्जरः।
रूपयौवनसंपन्ना रावणस्य वरस्त्रियः॥', 'avekṣamāṇaś ca tato dadarśa kapikuñjaraḥ
rūpayauvanasaṃpannā rāvaṇasya varastriyaḥ', null, 5016022),
('ramayana-5-16-23', 23, 'Sundara Kanda, Sarga 16, Verse 23', 'ताभिः परिवृतो राजा सुरूपाभिर्महायशाः।
तन्मृगद्विजसंघुष्टं प्रविष्टः प्रमदावनम्॥', 'tābhiḥ parivṛto rājā surūpābhir mahāyaśāḥ
tanmṛgadvijasaṃghuṣṭaṃ praviṣṭaḥ pramadāvanam', null, 5016023),
('ramayana-5-16-24', 24, 'Sundara Kanda, Sarga 16, Verse 24', 'क्षीबो विचित्राभरणः शङ्कुकर्णो महाबलः।
तेन विश्रवसः पुत्रः स दृष्टो राक्षसाधिपः॥', 'kṣībo vicitrābharaṇaḥ śaṅkukarṇo mahābalaḥ
tena viśravasaḥ putraḥ sa dṛṣṭo rākṣasādhipaḥ', null, 5016024),
('ramayana-5-16-25', 25, 'Sundara Kanda, Sarga 16, Verse 25', 'वृतः परमनारीभिस्ताराभिरिव चन्द्रमाः।
तं ददर्श महातेजास्तेजोवन्तं महाकपिः॥', 'vṛtaḥ paramanārībhis tārābhir iva candramāḥ
taṃ dadarśa mahātejās tejovantaṃ mahākapiḥ', null, 5016025),
('ramayana-5-16-26', 26, 'Sundara Kanda, Sarga 16, Verse 26', 'रावणोऽयं महाबाहुरिति संचिन्त्य वानरः।
अवप्लुतो महातेजा हनूमान्मारुतात्मजः॥', 'rāvaṇo ''yaṃ mahābāhur iti saṃcintya vānaraḥ
avapluto mahātejā hanūmān mārutātmajaḥ', null, 5016026),
('ramayana-5-16-27', 27, 'Sundara Kanda, Sarga 16, Verse 27', 'स तथाप्युग्रतेजाः सन्निर्धूतस्तस्य तेजसा।
पत्रगुह्यान्तरे सक्तो हनूमान्संवृतोऽभवत्॥', 'sa tathāpy ugratejāḥ san nirdhūtas tasya tejasā
patraguhyāntare sakto hanūmān saṃvṛto ''bhavat', null, 5016027),
('ramayana-5-16-28', 28, 'Sundara Kanda, Sarga 16, Verse 28', 'स तामसितकेशान्तां सुश्रोणीं संहतस्तनीम्।
दिदृक्षुरसितापाङ्गीमुपावर्तत रावणः॥', 'sa tām asitakeśāntāṃ suśroṇīṃ saṃhatastanīm
didṛkṣur asitāpāṅgīm upāvartata rāvaṇaḥ', null, 5016028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 17 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-17-1', 1, 'Sundara Kanda, Sarga 17, Verse 1', 'तस्मिन्नेव ततः काले राजपुत्री त्वनिन्दिता।
रूपयौवनसंपन्नं भूषणोत्तमभूषितम्॥', 'tasminn eva tataḥ kāle rājaputrī tv aninditā
rūpayauvanasaṃpannaṃ bhūṣaṇottamabhūṣitam', null, 5017001),
('ramayana-5-17-2', 2, 'Sundara Kanda, Sarga 17, Verse 2', 'ततो दृष्ट्वैव वैदेही रावणं राक्षसाधिपम्।
प्रावेपत वरारोहा प्रवाते कदली यथा॥', 'tato dṛṣṭvaiva vaidehī rāvaṇaṃ rākṣasādhipam
prāvepata varārohā pravāte kadalī yathā', null, 5017002),
('ramayana-5-17-3', 3, 'Sundara Kanda, Sarga 17, Verse 3', 'ऊरुभ्यामुदरं छाद्य बाहुभ्यां च पयोधरौ।
उपविष्टा विशालाक्षी रुदन्ती वरवर्णिनी॥', 'ūrubhyām udaraṃ chādya bāhubhyāṃ ca payodharau
upaviṣṭā viśālākṣī rudantī varavarṇinī', null, 5017003),
('ramayana-5-17-4', 4, 'Sundara Kanda, Sarga 17, Verse 4', 'दशग्रीवस्तु वैदेहीं रक्षितां राक्षसीगणैः।
ददर्श दीनां दुःखार्तं नावं सन्नामिवार्णवे॥', 'daśagrīvas tu vaidehīṃ rakṣitāṃ rākṣasīgaṇaiḥ
dadarśa dīnāṃ duḥkhārtaṃ nāvaṃ sannām ivārṇave', null, 5017004),
('ramayana-5-17-5', 5, 'Sundara Kanda, Sarga 17, Verse 5', 'असंवृतायामासीनां धरण्यां संशितव्रताम्।
छिन्नां प्रपतितां भूमौ शाखामिव वनस्पतेः।
मलमण्डनदिग्धाङ्गीं मण्डनार्हाममण्डिताम्॥', 'asaṃvṛtāyām āsīnāṃ dharaṇyāṃ saṃśitavratām
chinnāṃ prapatitāṃ bhūmau śākhām iva vanaspateḥ
malamaṇḍanadigdhāṅgīṃ maṇḍanārhām amaṇḍitām', null, 5017005),
('ramayana-5-17-6', 6, 'Sundara Kanda, Sarga 17, Verse 6', 'समीपं राजसिंहस्य रामस्य विदितात्मनः।
संकल्पहयसंयुक्तैर्यान्तीमिव मनोरथैः॥', 'samīpaṃ rājasiṃhasya rāmasya viditātmanaḥ
saṃkalpahayasaṃyuktair yāntīm iva manorathaiḥ', null, 5017006),
('ramayana-5-17-7', 7, 'Sundara Kanda, Sarga 17, Verse 7', 'शुष्यन्तीं रुदतीमेकां ध्यानशोकपरायणाम्।
दुःखस्यान्तमपश्यन्तीं रामां राममनुव्रताम्॥', 'śuṣyantīṃ rudatīm ekāṃ dhyānaśokaparāyaṇām
duḥkhasyāntam apaśyantīṃ rāmāṃ rāmam anuvratām', null, 5017007),
('ramayana-5-17-8', 8, 'Sundara Kanda, Sarga 17, Verse 8', 'वेष्टमानामथाविष्टां पन्नगेन्द्रवधूमिव।
धूप्यमानां ग्रहेणेव रोहिणीं धूमकेतुना॥', 'veṣṭamānām athāviṣṭāṃ pannagendravadhūm iva
dhūpyamānāṃ graheṇeva rohiṇīṃ dhūmaketunā', null, 5017008),
('ramayana-5-17-9', 9, 'Sundara Kanda, Sarga 17, Verse 9', 'वृत्तशीले कुले जातामाचारवति धार्मिके।
पुनः संस्कारमापन्नां जातमिव च दुष्कुले॥', 'vṛttaśīle kule jātām ācāravati dhārmike
punaḥ saṃskāram āpannāṃ jātam iva ca duṣkule', null, 5017009),
('ramayana-5-17-10', 10, 'Sundara Kanda, Sarga 17, Verse 10', 'सन्नामिव महाकीर्तिं श्रद्धामिव विमानिताम्।
प्रज्ञामिव परिक्षीणामाशां प्रतिहतामिव॥', 'sannām iva mahākīrtiṃ śraddhām iva vimānitām
prajñām iva parikṣīṇām āśāṃ pratihatām iva', null, 5017010),
('ramayana-5-17-11', 11, 'Sundara Kanda, Sarga 17, Verse 11', 'आयतीमिव विध्वस्तामाज्ञां प्रतिहतामिव।
दीप्तामिव दिशं काले पूजामपहृतामिव॥', 'āyatīm iva vidhvastām ājñāṃ pratihatām iva
dīptām iva diśaṃ kāle pūjām apahṛtām iva', null, 5017011),
('ramayana-5-17-12', 12, 'Sundara Kanda, Sarga 17, Verse 12', 'पद्मिनीमिव विध्वस्तां हतशूरां चमूमिव।
प्रभामिव तपोध्वस्तामुपक्षीणामिवापगाम्॥', 'padminīm iva vidhvastāṃ hataśūrāṃ camūm iva
prabhām iva tapodhvastām upakṣīṇām ivāpagām', null, 5017012),
('ramayana-5-17-13', 13, 'Sundara Kanda, Sarga 17, Verse 13', 'वेदीमिव परामृष्टां शान्तामग्निशिखामिव।
पौर्णमासीमिव निशां राहुग्रस्तेन्दुमण्डलाम्॥', 'vedīm iva parāmṛṣṭāṃ śāntām agniśikhām iva
paurṇamāsīm iva niśāṃ rāhugrastendumaṇḍalām', null, 5017013),
('ramayana-5-17-14', 14, 'Sundara Kanda, Sarga 17, Verse 14', 'उत्कृष्टपर्णकमलां वित्रासितविहंगमाम्।
हस्तिहस्तपरामृष्टामाकुलां पद्मिनीमिव॥', 'utkṛṣṭaparṇakamalāṃ vitrāsitavihaṃgamām
hastihastaparāmṛṣṭām ākulāṃ padminīm iva', null, 5017014),
('ramayana-5-17-15', 15, 'Sundara Kanda, Sarga 17, Verse 15', 'पतिशोकातुरां शुष्कां नदीं विस्रावितामिव।
परया मृजया हीनां कृष्णपक्षे निशामिव॥', 'patiśokāturāṃ śuṣkāṃ nadīṃ visrāvitām iva
parayā mṛjayā hīnāṃ kṛṣṇapakṣe niśām iva', null, 5017015),
('ramayana-5-17-16', 16, 'Sundara Kanda, Sarga 17, Verse 16', 'सुकुमारीं सुजाताङ्गीं रत्नगर्भगृहोचिताम्।
तप्यमानामिवोष्णेन मृणालीमचिरोद्धृताम्॥', 'sukumārīṃ sujātāṅgīṃ ratnagarbhagṛhocitām
tapyamānām ivoṣṇena mṛṇālīm aciroddhṛtām', null, 5017016),
('ramayana-5-17-17', 17, 'Sundara Kanda, Sarga 17, Verse 17', 'गृहीतामालितां स्तम्भे यूथपेन विनाकृताम्।
निःश्वसन्तीं सुदुःखार्तां गजराजवधूमिव॥', 'gṛhītāmālitāṃ stambhe yūthapena vinākṛtām
niḥśvasantīṃ suduḥkhārtāṃ gajarājavadhūm iva', null, 5017017),
('ramayana-5-17-18', 18, 'Sundara Kanda, Sarga 17, Verse 18', 'एकया दीर्घया वेण्या शोभमानामयत्नतः।
नीलया नीरदापाये वनराज्या महीमिव॥', 'ekayā dīrghayā veṇyā śobhamānām ayatnataḥ
nīlayā nīradāpāye vanarājyā mahīm iva', null, 5017018),
('ramayana-5-17-19', 19, 'Sundara Kanda, Sarga 17, Verse 19', 'उपवासेन शोकेन ध्यानेन च भयेन च।
परिक्षीणां कृशां दीनामल्पाहारां तपोधनाम्॥', 'upavāsena śokena dhyānena ca bhayena ca
parikṣīṇāṃ kṛśāṃ dīnām alpāhārāṃ tapodhanām', null, 5017019),
('ramayana-5-17-20', 20, 'Sundara Kanda, Sarga 17, Verse 20', 'आयाचमानां दुःखार्तां प्राञ्जलिं देवतामिव।
भावेन रघुमुख्यस्य दशग्रीवपराभवम्॥', 'āyācamānāṃ duḥkhārtāṃ prāñjaliṃ devatām iva
bhāvena raghumukhyasya daśagrīvaparābhavam', null, 5017020),
('ramayana-5-17-21', 21, 'Sundara Kanda, Sarga 17, Verse 21', 'समीक्षमाणां रुदतीमनिन्दितां सुपक्ष्मताम्रायतशुक्ललोचनाम्।
अनुव्रतां राममतीव मैथिलीं प्रलोभयामास वधाय रावणः॥', 'samīkṣamāṇāṃ rudatīm aninditāṃ supakṣmatāmrāyataśuklalocanām
anuvratāṃ rāmam atīva maithilīṃ pralobhayām āsa vadhāya rāvaṇaḥ', null, 5017021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 18 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-18-1', 1, 'Sundara Kanda, Sarga 18, Verse 1', 'स तां परिवृतां दीनां निरानन्दां तपस्विनीम्।
साकारैर्मधुरैर्वाक्यैर्न्यदर्शयत रावणः॥', 'sa tāṃ parivṛtāṃ dīnāṃ nirānandāṃ tapasvinīm
sākārair madhurair vākyair nyadarśayata rāvaṇaḥ', null, 5018001),
('ramayana-5-18-2', 2, 'Sundara Kanda, Sarga 18, Verse 2', 'मां दृष्ट्वा नागनासोरुगूहमाना स्तनोदरम्।
अदर्शनमिवात्मानं भयान्नेतुं त्वमिच्छसि॥', 'māṃ dṛṣṭvā nāganāsorugūhamānā stanodaram
adarśanam ivātmānaṃ bhayān netuṃ tvam icchasi', null, 5018002),
('ramayana-5-18-3', 3, 'Sundara Kanda, Sarga 18, Verse 3', 'कामये त्वां विशालाक्षि बहुमन्यस्व मां प्रिये।
सर्वाङ्गगुणसंपन्ने सर्वलोकमनोहरे॥', 'kāmaye tvāṃ viśālākṣi bahumanyasva māṃ priye
sarvāṅgaguṇasaṃpanne sarvalokamanohare', null, 5018003),
('ramayana-5-18-4', 4, 'Sundara Kanda, Sarga 18, Verse 4', 'नेह के चिन्मनुष्या वा राक्षसाः कामरूपिणः।
व्यपसर्पतु ते सीते भयं मत्तः समुत्थितम्॥', 'neha ke cin manuṣyā vā rākṣasāḥ kāmarūpiṇaḥ
vyapasarpatu te sīte bhayaṃ mattaḥ samutthitam', null, 5018004),
('ramayana-5-18-5', 5, 'Sundara Kanda, Sarga 18, Verse 5', 'स्वधर्मे रक्षसां भीरु सर्वथैष न संशयः।
गमनं वा परस्त्रीणां हरणं संप्रमथ्य वा॥', 'svadharme rakṣasāṃ bhīru sarvathaiṣa na saṃśayaḥ
gamanaṃ vā parastrīṇāṃ haraṇaṃ saṃpramathya vā', null, 5018005),
('ramayana-5-18-6', 6, 'Sundara Kanda, Sarga 18, Verse 6', 'एवं चैतदकामां च न त्वां स्प्रक्ष्यामि मैथिलि।
कामं कामः शरीरे मे यथाकामं प्रवर्तताम्॥', 'evaṃ caitad akāmāṃ ca na tvāṃ sprakṣyāmi maithili
kāmaṃ kāmaḥ śarīre me yathākāmaṃ pravartatām', null, 5018006),
('ramayana-5-18-7', 7, 'Sundara Kanda, Sarga 18, Verse 7', 'देवि नेह भयं कार्यं मयि विश्वसिहि प्रिये।
प्रणयस्व च तत्त्वेन मैवं भूः शोकलालसा॥', 'devi neha bhayaṃ kāryaṃ mayi viśvasihi priye
praṇayasva ca tattvena maivaṃ bhūḥ śokalālasā', null, 5018007),
('ramayana-5-18-8', 8, 'Sundara Kanda, Sarga 18, Verse 8', 'एकवेणी धराशय्या ध्यानं मलिनमम्बरम्।
अस्थानेऽप्युपवासश्च नैतान्यौपयिकानि ते॥', 'ekaveṇī dharāśayyā dhyānaṃ malinam ambaram
asthāne ''py upavāsaś ca naitāny aupayikāni te', null, 5018008),
('ramayana-5-18-9', 9, 'Sundara Kanda, Sarga 18, Verse 9', 'विचित्राणि च माल्यानि चन्दनान्यगरूणि च।
विविधानि च वासांसि दिव्यान्याभरणानि च॥', 'vicitrāṇi ca mālyāni candanāny agarūṇi ca
vividhāni ca vāsāṃsi divyāny ābharaṇāni ca', null, 5018009),
('ramayana-5-18-10', 10, 'Sundara Kanda, Sarga 18, Verse 10', 'महार्हाणि च पानानि यानानि शयनानि च।
गीतं नृत्तं च वाद्यं च लभ मां प्राप्य मैथिलि॥', 'mahārhāṇi ca pānāni yānāni śayanāni ca
gītaṃ nṛttaṃ ca vādyaṃ ca labha māṃ prāpya maithili', null, 5018010),
('ramayana-5-18-11', 11, 'Sundara Kanda, Sarga 18, Verse 11', 'स्त्रीरत्नमसि मैवं भूः कुरु गात्रेषु भूषणम्।
मां प्राप्य तु कथं हि स्यास्त्वमनर्हा सुविग्रहे॥', 'strīratnam asi maivaṃ bhūḥ kuru gātreṣu bhūṣaṇam
māṃ prāpya tu kathaṃ hi syās tvam anarhā suvigrahe', null, 5018011),
('ramayana-5-18-12', 12, 'Sundara Kanda, Sarga 18, Verse 12', 'इदं ते चारुसंजातं यौवनं व्यतिवर्तते।
यदतीतं पुनर्नैति स्रोतः शीघ्रमपामिव॥', 'idaṃ te cārusaṃjātaṃ yauvanaṃ vyativartate
yad atītaṃ punar naiti srotaḥ śīghram apām iva', null, 5018012),
('ramayana-5-18-13', 13, 'Sundara Kanda, Sarga 18, Verse 13', 'त्वां कृत्वोपरतो मन्ये रूपकर्ता स विश्वकृत्।
न हि रूपोपमा त्वन्या तवास्ति शुभदर्शने॥', 'tvāṃ kṛtvoparato manye rūpakartā sa viśvakṛt
na hi rūpopamā tv anyā tavāsti śubhadarśane', null, 5018013),
('ramayana-5-18-14', 14, 'Sundara Kanda, Sarga 18, Verse 14', 'त्वां समासाद्य वैदेहि रूपयौवनशालिनीम्।
कः पुमानतिवर्तेत साक्षादपि पितामहः॥', 'tvāṃ samāsādya vaidehi rūpayauvanaśālinīm
kaḥ pumān ativarteta sākṣād api pitāmahaḥ', null, 5018014),
('ramayana-5-18-15', 15, 'Sundara Kanda, Sarga 18, Verse 15', 'यद्यत्पश्यामि ते गात्रं शीतांशुसदृशानने।
तस्मिंस्तस्मिन्पृथुश्रोणि चक्षुर्मम निबध्यते॥', 'yad yat paśyāmi te gātraṃ śītāṃśusadṛśānane
tasmiṃs tasmin pṛthuśroṇi cakṣur mama nibadhyate', null, 5018015),
('ramayana-5-18-16', 16, 'Sundara Kanda, Sarga 18, Verse 16', 'भव मैथिलि भार्या मे मोहमेनं विसर्जय।
बह्वीनामुत्तमस्त्रीणां ममाग्रमहिषी भव॥', 'bhava maithili bhāryā me moham enaṃ visarjaya
bahvīnām uttamastrīṇāṃ mamāgramahiṣī bhava', null, 5018016),
('ramayana-5-18-17', 17, 'Sundara Kanda, Sarga 18, Verse 17', 'लोकेभ्यो यानि रत्नानि संप्रमथ्याहृतानि मे।
तानि ते भीरु सर्वाणि राज्यं चैतदहं च ते॥', 'lokebhyo yāni ratnāni saṃpramathyāhṛtāni me
tāni te bhīru sarvāṇi rājyaṃ caitad ahaṃ ca te', null, 5018017),
('ramayana-5-18-18', 18, 'Sundara Kanda, Sarga 18, Verse 18', 'विजित्य पृथिवीं सर्वां नानानगरमालिनीम्।
जनकाय प्रदास्यामि तव हेतोर्विलासिनि॥', 'vijitya pṛthivīṃ sarvāṃ nānānagaramālinīm
janakāya pradāsyāmi tava hetor vilāsini', null, 5018018),
('ramayana-5-18-19', 19, 'Sundara Kanda, Sarga 18, Verse 19', 'नेह पश्यामि लोकेऽन्यं यो मे प्रतिबलो भवेत्।
पश्य मे सुमहद्वीर्यमप्रतिद्वन्द्वमाहवे॥', 'neha paśyāmi loke ''nyaṃ yo me pratibalo bhavet
paśya me sumahad vīryam apratidvandvam āhave', null, 5018019),
('ramayana-5-18-20', 20, 'Sundara Kanda, Sarga 18, Verse 20', 'असकृत्संयुगे भग्ना मया विमृदितध्वजाः।
अशक्ताः प्रत्यनीकेषु स्थातुं मम सुरासुराः॥', 'asakṛt saṃyuge bhagnā mayā vimṛditadhvajāḥ
aśaktāḥ pratyanīkeṣu sthātuṃ mama surāsurāḥ', null, 5018020),
('ramayana-5-18-21', 21, 'Sundara Kanda, Sarga 18, Verse 21', 'इच्छ मां क्रियतामद्य प्रतिकर्म तवोत्तमम्।
सप्रभाण्यवसज्जन्तां तवाङ्गे भूषणानि च।
साधु पश्यामि ते रूपं संयुक्तं प्रतिकर्मणा॥', 'iccha māṃ kriyatām adya pratikarma tavottamam
saprabhāṇy avasajjantāṃ tavāṅge bhūṣaṇāni ca
sādhu paśyāmi te rūpaṃ saṃyuktaṃ pratikarmaṇā', null, 5018021),
('ramayana-5-18-22', 22, 'Sundara Kanda, Sarga 18, Verse 22', 'प्रतिकर्माभिसंयुक्ता दाक्षिण्येन वरानने।
भुङ्क्ष्व भोगान्यथाकामं पिब भीरु रमस्व च।
यथेष्टं च प्रयच्छ त्वं पृथिवीं वा धनानि च॥', 'pratikarmābhisaṃyuktā dākṣiṇyena varānane
bhuṅkṣva bhogān yathākāmaṃ piba bhīru ramasva ca
yatheṣṭaṃ ca prayaccha tvaṃ pṛthivīṃ vā dhanāni ca', null, 5018022),
('ramayana-5-18-23', 23, 'Sundara Kanda, Sarga 18, Verse 23', 'ललस्व मयि विस्रब्धा धृष्टमाज्ञापयस्व च।
मत्प्रभावाल्ललन्त्याश्च ललन्तां बान्धवास्तव॥', 'lalasva mayi visrabdhā dhṛṣṭam ājñāpayasva ca
matprabhāvāl lalantyāś ca lalantāṃ bāndhavās tava', null, 5018023),
('ramayana-5-18-24', 24, 'Sundara Kanda, Sarga 18, Verse 24', 'ऋद्धिं ममानुपश्य त्वं श्रियं भद्रे यशश्च मे।
किं करिष्यसि रामेण सुभगे चीरवाससा॥', 'ṛddhiṃ mamānupaśya tvaṃ śriyaṃ bhadre yaśaś ca me
kiṃ kariṣyasi rāmeṇa subhage cīravāsasā', null, 5018024),
('ramayana-5-18-25', 25, 'Sundara Kanda, Sarga 18, Verse 25', 'निक्षिप्तविजयो रामो गतश्रीर्वनगोचरः।
व्रती स्थण्डिलशायी च शङ्के जीवति वा न वा॥', 'nikṣiptavijayo rāmo gataśrīr vanagocaraḥ
vratī sthaṇḍilaśāyī ca śaṅke jīvati vā na vā', null, 5018025),
('ramayana-5-18-26', 26, 'Sundara Kanda, Sarga 18, Verse 26', 'न हि वैदेहि रामस्त्वां द्रष्टुं वाप्युपलप्स्यते।
पुरो बलाकैरसितैर्मेघैर्ज्योत्स्नामिवावृताम्॥', 'na hi vaidehi rāmas tvāṃ draṣṭuṃ vāpy upalapsyate
puro balākair asitair meghair jyotsnām ivāvṛtām', null, 5018026),
('ramayana-5-18-27', 27, 'Sundara Kanda, Sarga 18, Verse 27', 'न चापि मम हस्तात्त्वां प्राप्तुमर्हति राघवः।
हिरण्यकशिपुः कीर्तिमिन्द्रहस्तगतामिव॥', 'na cāpi mama hastāt tvāṃ prāptum arhati rāghavaḥ
hiraṇyakaśipuḥ kīrtim indrahastagatām iva', null, 5018027),
('ramayana-5-18-28', 28, 'Sundara Kanda, Sarga 18, Verse 28', 'चारुस्मिते चारुदति चारुनेत्रे विलासिनि।
मनो हरसि मे भीरु सुपर्णः पन्नगं यथा॥', 'cārusmite cārudati cārunetre vilāsini
mano harasi me bhīru suparṇaḥ pannagaṃ yathā', null, 5018028),
('ramayana-5-18-29', 29, 'Sundara Kanda, Sarga 18, Verse 29', 'क्लिष्टकौशेयवसनां तन्वीमप्यनलंकृताम्।
तां दृष्ट्वा स्वेषु दारेषु रतिं नोपलभाम्यहम्॥', 'kliṣṭakauśeyavasanāṃ tanvīm apy analaṃkṛtām
tāṃ dṛṣṭvā sveṣu dāreṣu ratiṃ nopalabhāmy aham', null, 5018029),
('ramayana-5-18-30', 30, 'Sundara Kanda, Sarga 18, Verse 30', 'अन्तःपुरनिवासिन्यः स्त्रियः सर्वगुणान्विताः।
यावन्त्यो मम सर्वासामैश्वर्यं कुरु जानकि॥', 'antaḥpuranivāsinyaḥ striyaḥ sarvaguṇānvitāḥ
yāvantyo mama sarvāsām aiśvaryaṃ kuru jānaki', null, 5018030),
('ramayana-5-18-31', 31, 'Sundara Kanda, Sarga 18, Verse 31', 'मम ह्यसितकेशान्ते त्रैलोक्यप्रवराः स्त्रियः।
तास्त्वां परिचरिष्यन्ति श्रियमप्सरसो यथा॥', 'mama hy asitakeśānte trailokyapravarāḥ striyaḥ
tās tvāṃ paricariṣyanti śriyam apsaraso yathā', null, 5018031),
('ramayana-5-18-32', 32, 'Sundara Kanda, Sarga 18, Verse 32', 'यानि वैश्रवणे सुभ्रु रत्नानि च धनानि च।
तानि लोकांश्च सुश्रोणि मां च भुङ्क्ष्व यथासुखम्॥', 'yāni vaiśravaṇe subhru ratnāni ca dhanāni ca
tāni lokāṃś ca suśroṇi māṃ ca bhuṅkṣva yathāsukham', null, 5018032),
('ramayana-5-18-33', 33, 'Sundara Kanda, Sarga 18, Verse 33', 'न रामस्तपसा देवि न बलेन न विक्रमैः।
न धनेन मया तुल्यस्तेजसा यशसापि वा॥', 'na rāmas tapasā devi na balena na vikramaiḥ
na dhanena mayā tulyas tejasā yaśasāpi vā', null, 5018033),
('ramayana-5-18-34', 34, 'Sundara Kanda, Sarga 18, Verse 34', 'पिब विहर रमस्व भुङ्क्ष्व भोगान्धननिचयं प्रदिशामि मेदिनीं च।
मयि लल ललने यथासुखं त्वं त्वयि च समेत्य ललन्तु बान्धवास्ते॥', 'piba vihara ramasva bhuṅkṣva bhogān dhananicayaṃ pradiśāmi medinīṃ ca
mayi lala lalane yathāsukhaṃ tvaṃ tvayi ca sametya lalantu bāndhavās te', null, 5018034),
('ramayana-5-18-35', 35, 'Sundara Kanda, Sarga 18, Verse 35', 'कुसुमिततरुजालसंततानि भ्रमरयुतानि समुद्रतीरजानि।
कनकविमलहारभूषिताङ्गी विहर मया सह भीरु काननानि॥', 'kusumitatarujālasaṃtatāni bhramarayutāni samudratīrajāni
kanakavimalahārabhūṣitāṅgī vihara mayā saha bhīru kānanāni', null, 5018035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 19 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-19-1', 1, 'Sundara Kanda, Sarga 19, Verse 1', 'तस्य तद्वचनं श्रुत्वा सीता रौद्रस्य रक्षसः।
आर्ता दीनस्वरा दीनं प्रत्युवाच शनैर्वचः॥', 'tasya tad vacanaṃ śrutvā sītā raudrasya rakṣasaḥ
ārtā dīnasvarā dīnaṃ pratyuvāca śanair vacaḥ', null, 5019001),
('ramayana-5-19-2', 2, 'Sundara Kanda, Sarga 19, Verse 2', 'दुःखार्ता रुदती सीता वेपमाना तपस्विनी।
चिन्तयन्ती वरारोहा पतिमेव पतिव्रता॥', 'duḥkhārtā rudatī sītā vepamānā tapasvinī
cintayantī varārohā patim eva pativratā', null, 5019002),
('ramayana-5-19-3', 3, 'Sundara Kanda, Sarga 19, Verse 3', 'तृणमन्तरतः कृत्वा प्रत्युवाच शुचिस्मिता।
निवर्तय मनो मत्तः स्वजने क्रियतां मनः॥', 'tṛṇam antarataḥ kṛtvā pratyuvāca śucismitā
nivartaya mano mattaḥ svajane kriyatāṃ manaḥ', null, 5019003),
('ramayana-5-19-4', 4, 'Sundara Kanda, Sarga 19, Verse 4', 'न मां प्रार्थयितुं युक्तस्त्वं सिद्धिमिव पापकृत्।
अकार्यं न मया कार्यमेकपत्न्या विगर्हितम्।
कुलं संप्राप्तया पुण्यं कुले महति जातया॥', 'na māṃ prārthayituṃ yuktas tvaṃ siddhim iva pāpakṛt
akāryaṃ na mayā kāryam ekapatnyā vigarhitam
kulaṃ saṃprāptayā puṇyaṃ kule mahati jātayā', null, 5019004),
('ramayana-5-19-5', 5, 'Sundara Kanda, Sarga 19, Verse 5', 'एवमुक्त्वा तु वैदेही रावणं तं यशस्विनी।
राक्षसं पृष्ठतः कृत्वा भूयो वचनमब्रवीत्॥', 'evam uktvā tu vaidehī rāvaṇaṃ taṃ yaśasvinī
rākṣasaṃ pṛṣṭhataḥ kṛtvā bhūyo vacanam abravīt', null, 5019005),
('ramayana-5-19-6', 6, 'Sundara Kanda, Sarga 19, Verse 6', 'नाहमौपयिकी भार्या परभार्या सती तव।
साधु धर्ममवेक्षस्व साधु साधुव्रतं चर॥', 'nāham aupayikī bhāryā parabhāryā satī tava
sādhu dharmam avekṣasva sādhu sādhuvrataṃ cara', null, 5019006),
('ramayana-5-19-7', 7, 'Sundara Kanda, Sarga 19, Verse 7', 'यथा तव तथान्येषां रक्ष्या दारा निशाचर।
आत्मानमुपमां कृत्वा स्वेषु दारेषु रम्यताम्॥', 'yathā tava tathānyeṣāṃ rakṣyā dārā niśācara
ātmānam upamāṃ kṛtvā sveṣu dāreṣu ramyatām', null, 5019007),
('ramayana-5-19-8', 8, 'Sundara Kanda, Sarga 19, Verse 8', 'अतुष्टं स्वेषु दारेषु चपलं चलितेन्द्रियम्।
नयन्ति निकृतिप्रज्ञां परदाराः पराभवम्॥', 'atuṣṭaṃ sveṣu dāreṣu capalaṃ calitendriyam
nayanti nikṛtiprajñāṃ paradārāḥ parābhavam', null, 5019008),
('ramayana-5-19-9', 9, 'Sundara Kanda, Sarga 19, Verse 9', 'इह सन्तो न वा सन्ति सतो वा नानुवर्तसे।
वचो मिथ्या प्रणीतात्मा पथ्यमुक्तं विचक्षणैः॥', 'iha santo na vā santi sato vā nānuvartase
vaco mithyā praṇītātmā pathyam uktaṃ vicakṣaṇaiḥ', null, 5019009),
('ramayana-5-19-10', 10, 'Sundara Kanda, Sarga 19, Verse 10', 'अकृतात्मानमासाद्य राजानमनये रतम्।
समृद्धानि विनश्यन्ति राष्ट्राणि नगराणि च॥', 'akṛtātmānam āsādya rājānam anaye ratam
samṛddhāni vinaśyanti rāṣṭrāṇi nagarāṇi ca', null, 5019010),
('ramayana-5-19-11', 11, 'Sundara Kanda, Sarga 19, Verse 11', 'तथेयं त्वां समासाद्य लङ्का रत्नौघ संकुला।
अपराधात्तवैकस्य नचिराद्विनशिष्यति॥', 'tatheyaṃ tvāṃ samāsādya laṅkā ratnaugha saṃkulā
aparādhāt tavaikasya nacirād vinaśiṣyati', null, 5019011),
('ramayana-5-19-12', 12, 'Sundara Kanda, Sarga 19, Verse 12', 'स्वकृतैर्हन्यमानस्य रावणादीर्घदर्शिनः।
अभिनन्दन्ति भूतानि विनाशे पापकर्मणः॥', 'svakṛtair hanyamānasya rāvaṇādīrghadarśinaḥ
abhinandanti bhūtāni vināśe pāpakarmaṇaḥ', null, 5019012),
('ramayana-5-19-13', 13, 'Sundara Kanda, Sarga 19, Verse 13', 'एवं त्वां पापकर्माणं वक्ष्यन्ति निकृता जनाः।
दिष्ट्यैतद्व्यसनं प्राप्तो रौद्र इत्येव हर्षिताः॥', 'evaṃ tvāṃ pāpakarmāṇaṃ vakṣyanti nikṛtā janāḥ
diṣṭyaitad vyasanaṃ prāpto raudra ity eva harṣitāḥ', null, 5019013),
('ramayana-5-19-14', 14, 'Sundara Kanda, Sarga 19, Verse 14', 'शक्या लोभयितुं नाहमैश्वर्येण धनेन वा।
अनन्या राघवेणाहं भास्करेण प्रभा यथा॥', 'śakyā lobhayituṃ nāham aiśvaryeṇa dhanena vā
ananyā rāghaveṇāhaṃ bhāskareṇa prabhā yathā', null, 5019014),
('ramayana-5-19-15', 15, 'Sundara Kanda, Sarga 19, Verse 15', 'उपधाय भुजं तस्य लोकनाथस्य सत्कृतम्।
कथं नामोपधास्यामि भुजमन्यस्य कस्य चित्॥', 'upadhāya bhujaṃ tasya lokanāthasya satkṛtam
kathaṃ nāmopadhāsyāmi bhujam anyasya kasya cit', null, 5019015),
('ramayana-5-19-16', 16, 'Sundara Kanda, Sarga 19, Verse 16', 'अहमौपयिकी भार्या तस्यैव वसुधापतेः।
व्रतस्नातस्य विप्रस्य विद्येव विदितात्मनः॥', 'aham aupayikī bhāryā tasyaiva vasudhāpateḥ
vratasnātasya viprasya vidyeva viditātmanaḥ', null, 5019016),
('ramayana-5-19-17', 17, 'Sundara Kanda, Sarga 19, Verse 17', 'साधु रावण रामेण मां समानय दुःखिताम्।
वने वाशितया सार्धं करेण्वेव गजाधिपम्॥', 'sādhu rāvaṇa rāmeṇa māṃ samānaya duḥkhitām
vane vāśitayā sārdhaṃ kareṇveva gajādhipam', null, 5019017),
('ramayana-5-19-18', 18, 'Sundara Kanda, Sarga 19, Verse 18', 'मित्रमौपयिकं कर्तुं रामः स्थानं परीप्सता।
वधं चानिच्छता घोरं त्वयासौ पुरुषर्षभः॥', 'mitram aupayikaṃ kartuṃ rāmaḥ sthānaṃ parīpsatā
vadhaṃ cānicchatā ghoraṃ tvayāsau puruṣarṣabhaḥ', null, 5019018),
('ramayana-5-19-19', 19, 'Sundara Kanda, Sarga 19, Verse 19', 'वर्जयेद्वज्रमुत्सृष्टं वर्जयेदन्तकश्चिरम्।
त्वद्विधं न तु संक्रुद्धो लोकनाथः स राघवः॥', 'varjayed vajram utsṛṣṭaṃ varjayed antakaś ciram
tvadvidhaṃ na tu saṃkruddho lokanāthaḥ sa rāghavaḥ', null, 5019019),
('ramayana-5-19-20', 20, 'Sundara Kanda, Sarga 19, Verse 20', 'रामस्य धनुषः शब्दं श्रोष्यसि त्वं महास्वनम्।
शतक्रतुविसृष्टस्य निर्घोषमशनेरिव॥', 'rāmasya dhanuṣaḥ śabdaṃ śroṣyasi tvaṃ mahāsvanam
śatakratuvisṛṣṭasya nirghoṣam aśaner iva', null, 5019020),
('ramayana-5-19-21', 21, 'Sundara Kanda, Sarga 19, Verse 21', 'इह शीघ्रं सुपर्वाणो ज्वलितास्या इवोरगाः।
इषवो निपतिष्यन्ति रामलक्ष्मणलक्षणाः॥', 'iha śīghraṃ suparvāṇo jvalitāsyā ivoragāḥ
iṣavo nipatiṣyanti rāmalakṣmaṇalakṣaṇāḥ', null, 5019021),
('ramayana-5-19-22', 22, 'Sundara Kanda, Sarga 19, Verse 22', 'रक्षांसि परिनिघ्नन्तः पुर्यामस्यां समन्ततः।
असंपातं करिष्यन्ति पतन्तः कङ्कवाससः॥', 'rakṣāṃsi parinighnantaḥ puryām asyāṃ samantataḥ
asaṃpātaṃ kariṣyanti patantaḥ kaṅkavāsasaḥ', null, 5019022),
('ramayana-5-19-23', 23, 'Sundara Kanda, Sarga 19, Verse 23', 'राक्षसेन्द्रमहासर्पान्स रामगरुडो महान्।
उद्धरिष्यति वेगेन वैनतेय इवोरगान्॥', 'rākṣasendramahāsarpān sa rāmagaruḍo mahān
uddhariṣyati vegena vainateya ivoragān', null, 5019023),
('ramayana-5-19-24', 24, 'Sundara Kanda, Sarga 19, Verse 24', 'अपनेष्यति मां भर्ता त्वत्तः शीघ्रमरिंदमः।
असुरेभ्यः श्रियं दीप्तां विष्णुस्त्रिभिरिव क्रमैः॥', 'apaneṣyati māṃ bhartā tvattaḥ śīghram ariṃdamaḥ
asurebhyaḥ śriyaṃ dīptāṃ viṣṇus tribhir iva kramaiḥ', null, 5019024),
('ramayana-5-19-25', 25, 'Sundara Kanda, Sarga 19, Verse 25', 'जनस्थाने हतस्थाने निहते रक्षसां बले।
अशक्तेन त्वया रक्षः कृतमेतदसाधु वै॥', 'janasthāne hatasthāne nihate rakṣasāṃ bale
aśaktena tvayā rakṣaḥ kṛtam etad asādhu vai', null, 5019025),
('ramayana-5-19-26', 26, 'Sundara Kanda, Sarga 19, Verse 26', 'आश्रमं तु तयोः शून्यं प्रविश्य नरसिंहयोः।
गोचरं गतयोर्भ्रात्रोरपनीता त्वयाधम॥', 'āśramaṃ tu tayoḥ śūnyaṃ praviśya narasiṃhayoḥ
gocaraṃ gatayor bhrātror apanītā tvayādhama', null, 5019026),
('ramayana-5-19-27', 27, 'Sundara Kanda, Sarga 19, Verse 27', 'न हि गन्धमुपाघ्राय रामलक्ष्मणयोस्त्वया।
शक्यं संदर्शने स्थातुं शुना शार्दूलयोरिव॥', 'na hi gandham upāghrāya rāmalakṣmaṇayos tvayā
śakyaṃ saṃdarśane sthātuṃ śunā śārdūlayor iva', null, 5019027),
('ramayana-5-19-28', 28, 'Sundara Kanda, Sarga 19, Verse 28', 'तस्य ते विग्रहे ताभ्यां युगग्रहणमस्थिरम्।
वृत्रस्येवेन्द्रबाहुभ्यां बाहोरेकस्य निग्रहः॥', 'tasya te vigrahe tābhyāṃ yugagrahaṇam asthiram
vṛtrasyevendrabāhubhyāṃ bāhor ekasya nigrahaḥ', null, 5019028),
('ramayana-5-19-29', 29, 'Sundara Kanda, Sarga 19, Verse 29', 'क्षिप्रं तव स नाथो मे रामः सौमित्रिणा सह।
तोयमल्पमिवादित्यः प्राणानादास्यते शरैः॥', 'kṣipraṃ tava sa nātho me rāmaḥ saumitriṇā saha
toyam alpam ivādityaḥ prāṇān ādāsyate śaraiḥ', null, 5019029),
('ramayana-5-19-30', 30, 'Sundara Kanda, Sarga 19, Verse 30', 'गिरिं कुबेरस्य गतोऽथ वालयं सभां गतो वा वरुणस्य राज्ञः।
असंशयं दाशरथेर्न मोक्ष्यसे महाद्रुमः कालहतोऽशनेरिव॥', 'giriṃ kuberasya gato ''tha vālayaṃ sabhāṃ gato vā varuṇasya rājñaḥ
asaṃśayaṃ dāśarather na mokṣyase mahādrumaḥ kālahato ''śaner iva', null, 5019030)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 20 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-20-1', 1, 'Sundara Kanda, Sarga 20, Verse 1', 'सीताया वचनं श्रुत्वा परुषं राक्षसाधिपः।
प्रत्युवाच ततः सीतां विप्रियं प्रियदर्शनाम्॥', 'sītāyā vacanaṃ śrutvā paruṣaṃ rākṣasādhipaḥ
pratyuvāca tataḥ sītāṃ vipriyaṃ priyadarśanām', null, 5020001),
('ramayana-5-20-2', 2, 'Sundara Kanda, Sarga 20, Verse 2', 'यथा यथा सान्त्वयिता वश्यः स्त्रीणां तथा तथा।
यथा यथा प्रियं वक्ता परिभूतस्तथा तथा॥', 'yathā yathā sāntvayitā vaśyaḥ strīṇāṃ tathā tathā
yathā yathā priyaṃ vaktā paribhūtas tathā tathā', null, 5020002),
('ramayana-5-20-3', 3, 'Sundara Kanda, Sarga 20, Verse 3', 'संनियच्छति मे क्रोधं त्वयि कामः समुत्थितः।
द्रवतो मार्गमासाद्य हयानिव सुसारथिः॥', 'saṃniyacchati me krodhaṃ tvayi kāmaḥ samutthitaḥ
dravato mārgam āsādya hayān iva susārathiḥ', null, 5020003),
('ramayana-5-20-4', 4, 'Sundara Kanda, Sarga 20, Verse 4', 'वामः कामो मनुष्याणां यस्मिन्किल निबध्यते।
जने तस्मिंस्त्वनुक्रोशः स्नेहश्च किल जायते॥', 'vāmaḥ kāmo manuṣyāṇāṃ yasmin kila nibadhyate
jane tasmiṃs tv anukrośaḥ snehaś ca kila jāyate', null, 5020004),
('ramayana-5-20-5', 5, 'Sundara Kanda, Sarga 20, Verse 5', 'एतस्मात्कारणान्न तां घतयामि वरानने।
वधार्हामवमानार्हां मिथ्याप्रव्रजिते रताम्॥', 'etasmāt kāraṇān na tāṃ ghatayāmi varānane
vadhārhām avamānārhāṃ mithyāpravrajite ratām', null, 5020005),
('ramayana-5-20-6', 6, 'Sundara Kanda, Sarga 20, Verse 6', 'परुषाणि हि वाक्यानि यानि यानि ब्रवीषि माम्।
तेषु तेषु वधो युक्तस्तव मैथिलि दारुणः॥', 'paruṣāṇi hi vākyāni yāni yāni bravīṣi mām
teṣu teṣu vadho yuktas tava maithili dāruṇaḥ', null, 5020006),
('ramayana-5-20-7', 7, 'Sundara Kanda, Sarga 20, Verse 7', 'एवमुक्त्वा तु वैदेहीं रावणो राक्षसाधिपः।
क्रोधसंरम्भसंयुक्तः सीतामुत्तरमब्रवीत्॥', 'evam uktvā tu vaidehīṃ rāvaṇo rākṣasādhipaḥ
krodhasaṃrambhasaṃyuktaḥ sītām uttaram abravīt', null, 5020007),
('ramayana-5-20-8', 8, 'Sundara Kanda, Sarga 20, Verse 8', 'द्वौ मासौ रक्षितव्यौ मे योऽवधिस्ते मया कृतः।
ततः शयनमारोह मम त्वं वरवर्णिनि॥', 'dvau māsau rakṣitavyau me yo ''vadhis te mayā kṛtaḥ
tataḥ śayanam āroha mama tvaṃ varavarṇini', null, 5020008),
('ramayana-5-20-9', 9, 'Sundara Kanda, Sarga 20, Verse 9', 'द्वाभ्यामूर्ध्वं तु मासाभ्यां भर्तारं मामनिच्छतीम्।
मम त्वां प्रातराशार्थमारभन्ते महानसे॥', 'dvābhyām ūrdhvaṃ tu māsābhyāṃ bhartāraṃ mām anicchatīm
mama tvāṃ prātarāśārtham ārabhante mahānase', null, 5020009),
('ramayana-5-20-10', 10, 'Sundara Kanda, Sarga 20, Verse 10', 'तां तर्ज्यमानां संप्रेक्ष्य राक्षसेन्द्रेण जानकीम्।
देवगन्धर्वकन्यास्ता विषेदुर्विपुलेक्षणाः॥', 'tāṃ tarjyamānāṃ saṃprekṣya rākṣasendreṇa jānakīm
devagandharvakanyās tā viṣedur vipulekṣaṇāḥ', null, 5020010),
('ramayana-5-20-11', 11, 'Sundara Kanda, Sarga 20, Verse 11', 'ओष्ठप्रकारैरपरा नेत्रवक्त्रैस्तथापराः।
सीतामाश्वासयामासुस्तर्जितां तेन रक्षसा॥', 'oṣṭhaprakārair aparā netravaktrais tathāparāḥ
sītām āśvāsayām āsus tarjitāṃ tena rakṣasā', null, 5020011),
('ramayana-5-20-12', 12, 'Sundara Kanda, Sarga 20, Verse 12', 'ताभिराश्वासिता सीता रावणं राक्षसाधिपम्।
उवाचात्महितं वाक्यं वृत्तशौण्डीर्यगर्वितम्॥', 'tābhir āśvāsitā sītā rāvaṇaṃ rākṣasādhipam
uvācātmahitaṃ vākyaṃ vṛttaśauṇḍīryagarvitam', null, 5020012),
('ramayana-5-20-13', 13, 'Sundara Kanda, Sarga 20, Verse 13', 'नूनं न ते जनः कश्चिदसिन्निःश्रेयसे स्थितः।
निवारयति यो न त्वां कर्मणोऽस्माद्विगर्हितात्॥', 'nūnaṃ na te janaḥ kaś cid asin niḥśreyase sthitaḥ
nivārayati yo na tvāṃ karmaṇo ''smād vigarhitāt', null, 5020013),
('ramayana-5-20-14', 14, 'Sundara Kanda, Sarga 20, Verse 14', 'मां हि धर्मात्मनः पत्नीं शचीमिव शचीपतेः।
त्वदन्यस्त्रिषु लोकेषु प्रार्थयेन्मनसापि कः॥', 'māṃ hi dharmātmanaḥ patnīṃ śacīm iva śacīpateḥ
tvadanyas triṣu lokeṣu prārthayen manasāpi kaḥ', null, 5020014),
('ramayana-5-20-15', 15, 'Sundara Kanda, Sarga 20, Verse 15', 'राक्षसाधम रामस्य भार्याममिततेजसः।
उक्तवानसि यत्पापं क्व गतस्तस्य मोक्ष्यसे॥', 'rākṣasādhama rāmasya bhāryām amitatejasaḥ
uktavān asi yat pāpaṃ kva gatas tasya mokṣyase', null, 5020015),
('ramayana-5-20-16', 16, 'Sundara Kanda, Sarga 20, Verse 16', 'यथा दृप्तश्च मातङ्गः शशश्च सहितौ वने।
तथा द्विरदवद्रामस्त्वं नीच शशवत्स्मृतः॥', 'yathā dṛptaś ca mātaṅgaḥ śaśaś ca sahitau vane
tathā dviradavad rāmas tvaṃ nīca śaśavat smṛtaḥ', null, 5020016),
('ramayana-5-20-17', 17, 'Sundara Kanda, Sarga 20, Verse 17', 'स त्वमिक्ष्वाकुनाथं वै क्षिपन्निह न लज्जसे।
चक्षुषो विषयं तस्य न तावदुपगच्छसि॥', 'sa tvam ikṣvākunāthaṃ vai kṣipann iha na lajjase
cakṣuṣo viṣayaṃ tasya na tāvad upagacchasi', null, 5020017),
('ramayana-5-20-18', 18, 'Sundara Kanda, Sarga 20, Verse 18', 'इमे ते नयने क्रूरे विरूपे कृष्णपिङ्गले।
क्षितौ न पतिते कस्मान्मामनार्यनिरीक्षितः॥', 'ime te nayane krūre virūpe kṛṣṇapiṅgale
kṣitau na patite kasmān mām anāryanirīkṣitaḥ', null, 5020018),
('ramayana-5-20-19', 19, 'Sundara Kanda, Sarga 20, Verse 19', 'तस्य धर्मात्मनः पत्नीं स्नुषां दशरथस्य च।
कथं व्याहरतो मां ते न जिह्वा पाप शीर्यते॥', 'tasya dharmātmanaḥ patnīṃ snuṣāṃ daśarathasya ca
kathaṃ vyāharato māṃ te na jihvā pāpa śīryate', null, 5020019),
('ramayana-5-20-20', 20, 'Sundara Kanda, Sarga 20, Verse 20', 'असंदेशात्तु रामस्य तपसश्चानुपालनात्।
न त्वां कुर्मि दशग्रीव भस्म भस्मार्हतेजसा॥', 'asaṃdeśāt tu rāmasya tapasaś cānupālanāt
na tvāṃ kurmi daśagrīva bhasma bhasmārhatejasā', null, 5020020),
('ramayana-5-20-21', 21, 'Sundara Kanda, Sarga 20, Verse 21', 'नापहर्तुमहं शक्या तस्य रामस्य धीमतः।
विधिस्तव वधार्थाय विहितो नात्र संशयः॥', 'nāpahartum ahaṃ śakyā tasya rāmasya dhīmataḥ
vidhis tava vadhārthāya vihito nātra saṃśayaḥ', null, 5020021),
('ramayana-5-20-22', 22, 'Sundara Kanda, Sarga 20, Verse 22', 'शूरेण धनदभ्राता बलैः समुदितेन च।
अपोह्य रामं कस्माद्धि दारचौर्यं त्वया कृतम्॥', 'śūreṇa dhanadabhrātā balaiḥ samuditena ca
apohya rāmaṃ kasmād dhi dāracauryaṃ tvayā kṛtam', null, 5020022),
('ramayana-5-20-23', 23, 'Sundara Kanda, Sarga 20, Verse 23', 'सीताया वचनं श्रुत्वा रावणो राक्षसाधिपः।
विवृत्य नयने क्रूरे जानकीमन्ववैक्षत॥', 'sītāyā vacanaṃ śrutvā rāvaṇo rākṣasādhipaḥ
vivṛtya nayane krūre jānakīm anvavaikṣata', null, 5020023),
('ramayana-5-20-24', 24, 'Sundara Kanda, Sarga 20, Verse 24', 'नीलजीमूतसंकाशो महाभुजशिरोधरः।
सिंहसत्त्वगतिः श्रीमान्दीप्तजिह्वोग्रलोचनः॥', 'nīlajīmūtasaṃkāśo mahābhujaśirodharaḥ
siṃhasattvagatiḥ śrīmān dīptajihvogralocanaḥ', null, 5020024),
('ramayana-5-20-25', 25, 'Sundara Kanda, Sarga 20, Verse 25', 'चलाग्रमकुटः प्रांशुश्चित्रमाल्यानुलेपनः।
रक्तमाल्याम्बरधरस्तप्ताङ्गदविभूषणः॥', 'calāgramakuṭaḥ prāṃśuś citramālyānulepanaḥ
raktamālyāmbaradharas taptāṅgadavibhūṣaṇaḥ', null, 5020025),
('ramayana-5-20-26', 26, 'Sundara Kanda, Sarga 20, Verse 26', 'श्रोणीसूत्रेण महता मेककेन सुसंवृतः।
अमृतोत्पादनद्धेन भुजंगेनेव मन्दरः॥', 'śroṇīsūtreṇa mahatā mekakena susaṃvṛtaḥ
amṛtotpādanaddhena bhujaṃgeneva mandaraḥ', null, 5020026),
('ramayana-5-20-27', 27, 'Sundara Kanda, Sarga 20, Verse 27', 'तरुणादित्यवर्णाभ्यां कुण्डलाभ्यां विभूषितः।
रक्तपल्लवपुष्पाभ्यामशोकाभ्यामिवाचलः॥', 'taruṇādityavarṇābhyāṃ kuṇḍalābhyāṃ vibhūṣitaḥ
raktapallavapuṣpābhyām aśokābhyām ivācalaḥ', null, 5020027),
('ramayana-5-20-28', 28, 'Sundara Kanda, Sarga 20, Verse 28', 'अवेक्षमाणो वैदेहीं कोपसंरक्तलोचनः।
उवाच रावणः सीतां भुजंग इव निःश्वसन्॥', 'avekṣamāṇo vaidehīṃ kopasaṃraktalocanaḥ
uvāca rāvaṇaḥ sītāṃ bhujaṃga iva niḥśvasan', null, 5020028),
('ramayana-5-20-29', 29, 'Sundara Kanda, Sarga 20, Verse 29', 'अनयेनाभिसंपन्नमर्थहीनमनुव्रते।
नाशयाम्यहमद्य त्वां सूर्यः संध्यामिवौजसा॥', 'anayenābhisaṃpannam arthahīnam anuvrate
nāśayāmy aham adya tvāṃ sūryaḥ saṃdhyām ivaujasā', null, 5020029),
('ramayana-5-20-30', 30, 'Sundara Kanda, Sarga 20, Verse 30', 'इत्युक्त्वा मैथिलीं राजा रावणः शत्रुरावणः।
संदिदेश ततः सर्वा राक्षसीर्घोरदर्शनाः॥', 'ity uktvā maithilīṃ rājā rāvaṇaḥ śatrurāvaṇaḥ
saṃdideśa tataḥ sarvā rākṣasīr ghoradarśanāḥ', null, 5020030),
('ramayana-5-20-31', 31, 'Sundara Kanda, Sarga 20, Verse 31', 'एकाक्षीमेककर्णां च कर्णप्रावरणां तथा।
गोकर्णीं हस्तिकर्णीं च लम्बकर्णीमकर्णिकाम्॥', 'ekākṣīm ekakarṇāṃ ca karṇaprāvaraṇāṃ tathā
gokarṇīṃ hastikarṇīṃ ca lambakarṇīm akarṇikām', null, 5020031),
('ramayana-5-20-32', 32, 'Sundara Kanda, Sarga 20, Verse 32', 'हस्तिपद्य श्वपद्यौ च गोपदीं पादचूलिकाम्।
एकाक्षीमेकपादीं च पृथुपादीमपादिकाम्॥', 'hastipadya śvapadyau ca gopadīṃ pādacūlikām
ekākṣīm ekapādīṃ ca pṛthupādīm apādikām', null, 5020032),
('ramayana-5-20-33', 33, 'Sundara Kanda, Sarga 20, Verse 33', 'अतिमात्रशिरोग्रीवामतिमात्रकुचोदरीम्।
अतिमात्रास्यनेत्रां च दीर्घजिह्वामजिह्विकाम्।
अनासिकां सिंहमुखीं गोमुखीं सूकरीमुखीम्॥', 'atimātraśirogrīvām atimātrakucodarīm
atimātrāsyanetrāṃ ca dīrghajihvām ajihvikām
anāsikāṃ siṃhamukhīṃ gomukhīṃ sūkarīmukhīm', null, 5020033),
('ramayana-5-20-34', 34, 'Sundara Kanda, Sarga 20, Verse 34', 'यथा मद्वशगा सीता क्षिप्रं भवति जानकी।
तथा कुरुत राक्षस्यः सर्वाः क्षिप्रं समेत्य च॥', 'yathā madvaśagā sītā kṣipraṃ bhavati jānakī
tathā kuruta rākṣasyaḥ sarvāḥ kṣipraṃ sametya ca', null, 5020034),
('ramayana-5-20-35', 35, 'Sundara Kanda, Sarga 20, Verse 35', 'प्रतिलोमानुलोमैश्च सामदानादिभेदनैः।
आवर्तयत वैदेहीं दण्डस्योद्यमनेन च॥', 'pratilomānulomaiś ca sāmadānādibhedanaiḥ
āvartayata vaidehīṃ daṇḍasyodyamanena ca', null, 5020035),
('ramayana-5-20-36', 36, 'Sundara Kanda, Sarga 20, Verse 36', 'इति प्रतिसमादिश्य राक्षसेन्द्रः पुनः पुनः।
काममन्युपरीतात्मा जानकीं पर्यतर्जयत्॥', 'iti pratisamādiśya rākṣasendraḥ punaḥ punaḥ
kāmamanyuparītātmā jānakīṃ paryatarjayat', null, 5020036),
('ramayana-5-20-37', 37, 'Sundara Kanda, Sarga 20, Verse 37', 'उपगम्य ततः क्षिप्रं राक्षसी धान्यमालिनी।
परिष्वज्य दशग्रीवमिदं वचनमब्रवीत्॥', 'upagamya tataḥ kṣipraṃ rākṣasī dhānyamālinī
pariṣvajya daśagrīvam idaṃ vacanam abravīt', null, 5020037),
('ramayana-5-20-38', 38, 'Sundara Kanda, Sarga 20, Verse 38', 'मया क्रीड महाराजसीतया किं तवानया।
अकामां कामयानस्य शरीरमुपतप्यते।
इच्छन्तीं कामयानस्य प्रीतिर्भवति शोभना॥', 'mayā krīḍa mahārājasītayā kiṃ tavānayā
akāmāṃ kāmayānasya śarīram upatapyate
icchantīṃ kāmayānasya prītir bhavati śobhanā', null, 5020038),
('ramayana-5-20-39', 39, 'Sundara Kanda, Sarga 20, Verse 39', 'एवमुक्तस्तु राक्षस्या समुत्क्षिप्तस्ततो बली।
ज्वलद्भास्करवर्णाभं प्रविवेश निवेशनम्॥', 'evam uktas tu rākṣasyā samutkṣiptas tato balī
jvaladbhāskaravarṇābhaṃ praviveśa niveśanam', null, 5020039),
('ramayana-5-20-40', 40, 'Sundara Kanda, Sarga 20, Verse 40', 'देवगन्धर्वकन्याश्च नागकन्याश्च तास्ततः।
परिवार्य दशग्रीवं विविशुस्तद्गृहोत्तमम्॥', 'devagandharvakanyāś ca nāgakanyāś ca tās tataḥ
parivārya daśagrīvaṃ viviśus tad gṛhottamam', null, 5020040),
('ramayana-5-20-41', 41, 'Sundara Kanda, Sarga 20, Verse 41', 'स मैथिलीं धर्मपरामवस्थितां प्रवेपमानां परिभर्त्स्य रावणः।
विहाय सीतां मदनेन मोहितः स्वमेव वेश्म प्रविवेश भास्वरम्॥', 'sa maithilīṃ dharmaparām avasthitāṃ pravepamānāṃ paribhartsya rāvaṇaḥ
vihāya sītāṃ madanena mohitaḥ svam eva veśma praviveśa bhāsvaram', null, 5020041)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 21 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-21-1', 1, 'Sundara Kanda, Sarga 21, Verse 1', 'इत्युक्त्वा मैथिलीं राजा रावणः शत्रुरावणः।
संदिश्य च ततः सर्वा राक्षसीर्निर्जगाम ह॥', 'ity uktvā maithilīṃ rājā rāvaṇaḥ śatrurāvaṇaḥ
saṃdiśya ca tataḥ sarvā rākṣasīr nirjagāma ha', null, 5021001),
('ramayana-5-21-2', 2, 'Sundara Kanda, Sarga 21, Verse 2', 'निष्क्रान्ते राक्षसेन्द्रे तु पुनरन्तःपुरं गते।
राक्षस्यो भीमरूपास्ताः सीतां समभिदुद्रुवुः॥', 'niṣkrānte rākṣasendre tu punar antaḥpuraṃ gate
rākṣasyo bhīmarūpās tāḥ sītāṃ samabhidudruvuḥ', null, 5021002),
('ramayana-5-21-3', 3, 'Sundara Kanda, Sarga 21, Verse 3', 'ततः सीतामुपागम्य राक्षस्यः क्रोधमूर्छिताः।
परं परुषया वाचा वैदेहीमिदमब्रुवन्॥', 'tataḥ sītām upāgamya rākṣasyaḥ krodhamūrchitāḥ
paraṃ paruṣayā vācā vaidehīm idam abruvan', null, 5021003),
('ramayana-5-21-4', 4, 'Sundara Kanda, Sarga 21, Verse 4', 'पौलस्त्यस्य वरिष्ठस्य रावणस्य महात्मनः।
दशग्रीवस्य भार्यात्वं सीते न बहु मन्यसे॥', 'paulastyasya variṣṭhasya rāvaṇasya mahātmanaḥ
daśagrīvasya bhāryātvaṃ sīte na bahu manyase', null, 5021004),
('ramayana-5-21-5', 5, 'Sundara Kanda, Sarga 21, Verse 5', 'ततस्त्वेकजटा नाम राक्षसी वाक्यमब्रवीत्।
आमन्त्र्य क्रोधताम्राक्षी सीतां करतलोदरीम्॥', 'tatas tv ekajaṭā nāma rākṣasī vākyam abravīt
āmantrya krodhatāmrākṣī sītāṃ karatalodarīm', null, 5021005),
('ramayana-5-21-6', 6, 'Sundara Kanda, Sarga 21, Verse 6', 'प्रजापतीनां षण्णां तु चतुर्थो यः प्रजापतिः।
मानसो ब्रह्मणः पुत्रः पुलस्त्य इति विश्रुतः॥', 'prajāpatīnāṃ ṣaṇṇāṃ tu caturtho yaḥ prajāpatiḥ
mānaso brahmaṇaḥ putraḥ pulastya iti viśrutaḥ', null, 5021006),
('ramayana-5-21-7', 7, 'Sundara Kanda, Sarga 21, Verse 7', 'पुलस्त्यस्य तु तेजस्वी महर्षिर्मानसः सुतः।
नाम्ना स विश्रवा नाम प्रजापतिसमप्रभः॥', 'pulastyasya tu tejasvī maharṣir mānasaḥ sutaḥ
nāmnā sa viśravā nāma prajāpatisamaprabhaḥ', null, 5021007),
('ramayana-5-21-8', 8, 'Sundara Kanda, Sarga 21, Verse 8', 'तस्य पुत्रो विशालाक्षि रावणः शत्रुरावणः।
तस्य त्वं राक्षसेन्द्रस्य भार्या भवितुमर्हसि।
मयोक्तं चारुसर्वाङ्गि वाक्यं किं नानुमन्यसे॥', 'tasya putro viśālākṣi rāvaṇaḥ śatrurāvaṇaḥ
tasya tvaṃ rākṣasendrasya bhāryā bhavitum arhasi
mayoktaṃ cārusarvāṅgi vākyaṃ kiṃ nānumanyase', null, 5021008),
('ramayana-5-21-9', 9, 'Sundara Kanda, Sarga 21, Verse 9', 'ततो हरिजटा नाम राक्षसी वाक्यमब्रवीत्।
विवृत्य नयने कोपान्मार्जारसदृशेक्षणा॥', 'tato harijaṭā nāma rākṣasī vākyam abravīt
vivṛtya nayane kopān mārjārasadṛśekṣaṇā', null, 5021009),
('ramayana-5-21-10', 10, 'Sundara Kanda, Sarga 21, Verse 10', 'येन देवास्त्रयस्त्रिंशद्देवराजश्च निर्जितः।
तस्य त्वं राक्षसेन्द्रस्य भार्या भवितुमर्हसि॥', 'yena devās trayastriṃśad devarājaś ca nirjitaḥ
tasya tvaṃ rākṣasendrasya bhāryā bhavitum arhasi', null, 5021010),
('ramayana-5-21-11', 11, 'Sundara Kanda, Sarga 21, Verse 11', 'वीर्योत्सिक्तस्य शूरस्य संग्रामेष्वनिवर्तिनः।
बलिनो वीर्ययुक्तस्या भार्यात्वं किं न लप्स्यसे॥', 'vīryotsiktasya śūrasya saṃgrāmeṣv anivartinaḥ
balino vīryayuktasyā bhāryātvaṃ kiṃ na lapsyase', null, 5021011),
('ramayana-5-21-12', 12, 'Sundara Kanda, Sarga 21, Verse 12', 'प्रियां बहुमतां भार्यां त्यक्त्वा राजा महाबलः।
सर्वासां च महाभागां त्वामुपैष्यति रावणः॥', 'priyāṃ bahumatāṃ bhāryāṃ tyaktvā rājā mahābalaḥ
sarvāsāṃ ca mahābhāgāṃ tvām upaiṣyati rāvaṇaḥ', null, 5021012),
('ramayana-5-21-13', 13, 'Sundara Kanda, Sarga 21, Verse 13', 'समृद्धं स्त्रीसहस्रेण नानारत्नोपशोभितम्।
अन्तःपुरं समुत्सृज्य त्वामुपैष्यति रावणः॥', 'samṛddhaṃ strīsahasreṇa nānāratnopaśobhitam
antaḥpuraṃ samutsṛjya tvām upaiṣyati rāvaṇaḥ', null, 5021013),
('ramayana-5-21-14', 14, 'Sundara Kanda, Sarga 21, Verse 14', 'असकृद्देवता युद्धे नागगन्धर्वदानवाः।
निर्जिताः समरे येन स ते पार्श्वमुपागतः॥', 'asakṛd devatā yuddhe nāgagandharvadānavāḥ
nirjitāḥ samare yena sa te pārśvam upāgataḥ', null, 5021014),
('ramayana-5-21-15', 15, 'Sundara Kanda, Sarga 21, Verse 15', 'तस्य सर्वसमृद्धस्या रावणस्य महात्मनः।
किमर्थं राक्षसेन्द्रस्य भार्यात्वं नेच्छसेऽधमे॥', 'tasya sarvasamṛddhasyā rāvaṇasya mahātmanaḥ
kimarthaṃ rākṣasendrasya bhāryātvaṃ necchase ''dhame', null, 5021015),
('ramayana-5-21-16', 16, 'Sundara Kanda, Sarga 21, Verse 16', 'यस्य सूर्यो न तपति भीतो यस्य च मारुतः।
न वाति स्मायतापाङ्गे किं त्वं तस्य न तिष्ठसि॥', 'yasya sūryo na tapati bhīto yasya ca mārutaḥ
na vāti smāyatāpāṅge kiṃ tvaṃ tasya na tiṣṭhasi', null, 5021016),
('ramayana-5-21-17', 17, 'Sundara Kanda, Sarga 21, Verse 17', 'पुष्पवृष्टिं च तरवो मुमुचुर्यस्य वै भयात्।
शैलाश्च सुभ्रु पानीयं जलदाश्च यदेच्छति॥', 'puṣpavṛṣṭiṃ ca taravo mumucur yasya vai bhayāt
śailāś ca subhru pānīyaṃ jaladāś ca yadecchati', null, 5021017),
('ramayana-5-21-18', 18, 'Sundara Kanda, Sarga 21, Verse 18', 'तस्य नैरृतराजस्य राजराजस्य भामिनि।
किं त्वं न कुरुषे बुद्धिं भार्यार्थे रावणस्य हि॥', 'tasya nairṛtarājasya rājarājasya bhāmini
kiṃ tvaṃ na kuruṣe buddhiṃ bhāryārthe rāvaṇasya hi', null, 5021018),
('ramayana-5-21-19', 19, 'Sundara Kanda, Sarga 21, Verse 19', 'साधु ते तत्त्वतो देवि कथितं साधु भामिनि।
गृहाण सुस्मिते वाक्यमन्यथा न भविष्यसि॥', 'sādhu te tattvato devi kathitaṃ sādhu bhāmini
gṛhāṇa susmite vākyam anyathā na bhaviṣyasi', null, 5021019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 22 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-22-1', 1, 'Sundara Kanda, Sarga 22, Verse 1', 'ततः सीतामुपागम्य राक्षस्यो विकृताननाः।
परुषं परुषा नार्य ऊचुस्ता वाक्यमप्रियम्॥', 'tataḥ sītām upāgamya rākṣasyo vikṛtānanāḥ
paruṣaṃ paruṣā nārya ūcus tā vākyam apriyam', null, 5022001),
('ramayana-5-22-2', 2, 'Sundara Kanda, Sarga 22, Verse 2', 'किं त्वमन्तःपुरे सीते सर्वभूतमनोहरे।
महार्हशयनोपेते न वासमनुमन्यसे॥', 'kiṃ tvam antaḥpure sīte sarvabhūtamanohare
mahārhaśayanopete na vāsam anumanyase', null, 5022002),
('ramayana-5-22-3', 3, 'Sundara Kanda, Sarga 22, Verse 3', 'मानुषी मानुषस्यैव भार्यात्वं बहु मन्यसे।
प्रत्याहर मनो रामान्न त्वं जातु भविष्यसि॥', 'mānuṣī mānuṣasyaiva bhāryātvaṃ bahu manyase
pratyāhara mano rāmān na tvaṃ jātu bhaviṣyasi', null, 5022003),
('ramayana-5-22-4', 4, 'Sundara Kanda, Sarga 22, Verse 4', 'मानुषी मानुषं तं तु राममिच्छसि शोभने।
राज्याद्भ्रष्टमसिद्धार्थं विक्लवं तमनिन्दिते॥', 'mānuṣī mānuṣaṃ taṃ tu rāmam icchasi śobhane
rājyād bhraṣṭam asiddhārthaṃ viklavaṃ tam anindite', null, 5022004),
('ramayana-5-22-5', 5, 'Sundara Kanda, Sarga 22, Verse 5', 'राक्षसीनां वचः श्रुत्वा सीता पद्मनिभेक्षणा।
नेत्राभ्यामश्रुपूर्णाभ्यामिदं वचनमब्रवीत्॥', 'rākṣasīnāṃ vacaḥ śrutvā sītā padmanibhekṣaṇā
netrābhyām aśrupūrṇābhyām idaṃ vacanam abravīt', null, 5022005),
('ramayana-5-22-6', 6, 'Sundara Kanda, Sarga 22, Verse 6', 'यदिदं लोकविद्विष्टमुदाहरथ संगताः।
नैतन्मनसि वाक्यं मे किल्बिषं प्रतितिष्ठति॥', 'yad idaṃ lokavidviṣṭam udāharatha saṃgatāḥ
naitan manasi vākyaṃ me kilbiṣaṃ pratitiṣṭhati', null, 5022006),
('ramayana-5-22-7', 7, 'Sundara Kanda, Sarga 22, Verse 7', 'न मानुषी राक्षसस्य भार्या भवितुमर्हति।
कामं खादत मां सर्वा न करिष्यामि वो वचः।
दीनो वा राज्यहीनो वा यो मे भर्ता स मे गुरुः॥', 'na mānuṣī rākṣasasya bhāryā bhavitum arhati
kāmaṃ khādata māṃ sarvā na kariṣyāmi vo vacaḥ
dīno vā rājyahīno vā yo me bhartā sa me guruḥ', null, 5022007),
('ramayana-5-22-8', 8, 'Sundara Kanda, Sarga 22, Verse 8', 'सीताया वचनं श्रुत्वा राक्षस्यः क्रोधमूर्छिताः।
भर्त्सयन्ति स्म परुषैर्वाक्यै रावणचोदिताः॥', 'sītāyā vacanaṃ śrutvā rākṣasyaḥ krodhamūrchitāḥ
bhartsayanti sma paruṣair vākyai rāvaṇacoditāḥ', null, 5022008),
('ramayana-5-22-9', 9, 'Sundara Kanda, Sarga 22, Verse 9', 'अवलीनः स निर्वाक्यो हनुमाञ्शिंशपाद्रुमे।
सीतां संतर्जयन्तीस्ता राक्षसीरशृणोत्कपिः॥', 'avalīnaḥ sa nirvākyo hanumāñ śiṃśapādrume
sītāṃ saṃtarjayantīs tā rākṣasīr aśṛṇot kapiḥ', null, 5022009),
('ramayana-5-22-10', 10, 'Sundara Kanda, Sarga 22, Verse 10', 'तामभिक्रम्य संरब्धा वेपमानां समन्ततः।
भृशं संलिलिहुर्दीप्तान्प्रलम्बदशनच्छदान्॥', 'tām abhikramya saṃrabdhā vepamānāṃ samantataḥ
bhṛśaṃ saṃlilihur dīptān pralambadaśanacchadān', null, 5022010),
('ramayana-5-22-11', 11, 'Sundara Kanda, Sarga 22, Verse 11', 'ऊचुश्च परमक्रुद्धाः प्रगृह्याशु परश्वधान्।
नेयमर्हति भर्तारं रावणं राक्षसाधिपम्॥', 'ūcuś ca paramakruddhāḥ pragṛhyāśu paraśvadhān
neyam arhati bhartāraṃ rāvaṇaṃ rākṣasādhipam', null, 5022011),
('ramayana-5-22-12', 12, 'Sundara Kanda, Sarga 22, Verse 12', 'सा भर्त्स्यमाना भीमाभी राक्षसीभिर्वरानना।
सा बाष्पमपमार्जन्ती शिंशपां तामुपागमत्॥', 'sā bhartsyamānā bhīmābhī rākṣasībhir varānanā
sā bāṣpam apamārjantī śiṃśapāṃ tām upāgamat', null, 5022012),
('ramayana-5-22-13', 13, 'Sundara Kanda, Sarga 22, Verse 13', 'ततस्तां शिंशपां सीता राक्षसीभिः समावृता।
अभिगम्य विशालाक्षी तस्थौ शोकपरिप्लुता॥', 'tatas tāṃ śiṃśapāṃ sītā rākṣasībhiḥ samāvṛtā
abhigamya viśālākṣī tasthau śokapariplutā', null, 5022013),
('ramayana-5-22-14', 14, 'Sundara Kanda, Sarga 22, Verse 14', 'तां कृशां दीनवदनां मलिनाम्बरधारिणीम्।
भर्त्सयां चक्रिरे भीमा राक्षस्यस्ताः समन्ततः॥', 'tāṃ kṛśāṃ dīnavadanāṃ malināmbaradhāriṇīm
bhartsayāṃ cakrire bhīmā rākṣasyas tāḥ samantataḥ', null, 5022014),
('ramayana-5-22-15', 15, 'Sundara Kanda, Sarga 22, Verse 15', 'ततस्तां विनता नाम राक्षसी भीमदर्शना।
अब्रवीत्कुपिताकारा कराला निर्णतोदरी॥', 'tatas tāṃ vinatā nāma rākṣasī bhīmadarśanā
abravīt kupitākārā karālā nirṇatodarī', null, 5022015),
('ramayana-5-22-16', 16, 'Sundara Kanda, Sarga 22, Verse 16', 'सीते पर्याप्तमेतावद्भर्तृस्नेहो निदर्शितः।
सर्वत्रातिकृतं भद्रे व्यसनायोपकल्पते॥', 'sīte paryāptam etāvad bhartṛsneho nidarśitaḥ
sarvatrātikṛtaṃ bhadre vyasanāyopakalpate', null, 5022016),
('ramayana-5-22-17', 17, 'Sundara Kanda, Sarga 22, Verse 17', 'परितुष्टास्मि भद्रं ते मानुषस्ते कृतो विधिः।
ममापि तु वचः पथ्यं ब्रुवन्त्याः कुरु मैथिलि॥', 'parituṣṭāsmi bhadraṃ te mānuṣas te kṛto vidhiḥ
mamāpi tu vacaḥ pathyaṃ bruvantyāḥ kuru maithili', null, 5022017),
('ramayana-5-22-18', 18, 'Sundara Kanda, Sarga 22, Verse 18', 'रावणं भज भर्तारं भर्तारं सर्वरक्षसाम्।
विक्रान्तं रूपवन्तं च सुरेशमिव वासवम्॥', 'rāvaṇaṃ bhaja bhartāraṃ bhartāraṃ sarvarakṣasām
vikrāntaṃ rūpavantaṃ ca sureśam iva vāsavam', null, 5022018),
('ramayana-5-22-19', 19, 'Sundara Kanda, Sarga 22, Verse 19', 'दक्षिणं त्यागशीलं च सर्वस्य प्रियवादिनम्।
मानुषं कृपणं रामं त्यक्त्वा रावणमाश्रय॥', 'dakṣiṇaṃ tyāgaśīlaṃ ca sarvasya priyavādinam
mānuṣaṃ kṛpaṇaṃ rāmaṃ tyaktvā rāvaṇam āśraya', null, 5022019),
('ramayana-5-22-20', 20, 'Sundara Kanda, Sarga 22, Verse 20', 'दिव्याङ्गरागा वैदेहि दिव्याभरणभूषिता।
अद्य प्रभृति सर्वेषां लोकानामीश्वरी भव।
अग्नेः स्वाहा यथा देवी शचीवेन्द्रस्य शोभने॥', 'divyāṅgarāgā vaidehi divyābharaṇabhūṣitā
adya prabhṛti sarveṣāṃ lokānām īśvarī bhava
agneḥ svāhā yathā devī śacīvendrasya śobhane', null, 5022020),
('ramayana-5-22-21', 21, 'Sundara Kanda, Sarga 22, Verse 21', 'किं ते रामेण वैदेहि कृपणेन गतायुषा॥', 'kiṃ te rāmeṇa vaidehi kṛpaṇena gatāyuṣā', null, 5022021),
('ramayana-5-22-22', 22, 'Sundara Kanda, Sarga 22, Verse 22', 'एतदुक्तं च मे वाक्यं यदि त्वं न करिष्यसि।
अस्मिन्मुहूर्ते सर्वास्त्वां भक्षयिष्यामहे वयम्॥', 'etad uktaṃ ca me vākyaṃ yadi tvaṃ na kariṣyasi
asmin muhūrte sarvās tvāṃ bhakṣayiṣyāmahe vayam', null, 5022022),
('ramayana-5-22-23', 23, 'Sundara Kanda, Sarga 22, Verse 23', 'अन्या तु विकटा नाम लम्बमानपयोधरा।
अब्रवीत्कुपिता सीतां मुष्टिमुद्यम्य गर्जती॥', 'anyā tu vikaṭā nāma lambamānapayodharā
abravīt kupitā sītāṃ muṣṭim udyamya garjatī', null, 5022023),
('ramayana-5-22-24', 24, 'Sundara Kanda, Sarga 22, Verse 24', 'बहून्यप्रतिरूपाणि वचनानि सुदुर्मते।
अनुक्रोशान्मृदुत्वाच्च सोढानि तव मैथिलि।
न च नः कुरुषे वाक्यं हितं कालपुरस्कृतम्॥', 'bahūny apratirūpāṇi vacanāni sudurmate
anukrośān mṛdutvāc ca soḍhāni tava maithili
na ca naḥ kuruṣe vākyaṃ hitaṃ kālapuraskṛtam', null, 5022024),
('ramayana-5-22-25', 25, 'Sundara Kanda, Sarga 22, Verse 25', 'आनीतासि समुद्रस्य पारमन्यैर्दुरासदम्।
रावणान्तःपुरं घोरं प्रविष्टा चासि मैथिलि॥', 'ānītāsi samudrasya pāram anyair durāsadam
rāvaṇāntaḥpuraṃ ghoraṃ praviṣṭā cāsi maithili', null, 5022025),
('ramayana-5-22-26', 26, 'Sundara Kanda, Sarga 22, Verse 26', 'रावणस्य गृहे रुधा अस्माभिस्तु सुरक्षिता।
न त्वां शक्तः परित्रातुमपि साक्षात्पुरंदरः॥', 'rāvaṇasya gṛhe rudhā asmābhis tu surakṣitā
na tvāṃ śaktaḥ paritrātum api sākṣāt puraṃdaraḥ', null, 5022026),
('ramayana-5-22-27', 27, 'Sundara Kanda, Sarga 22, Verse 27', 'कुरुष्व हितवादिन्या वचनं मम मैथिलि।
अलमश्रुप्रपातेन त्यज शोकमनर्थकम्॥', 'kuruṣva hitavādinyā vacanaṃ mama maithili
alam aśruprapātena tyaja śokam anarthakam', null, 5022027),
('ramayana-5-22-28', 28, 'Sundara Kanda, Sarga 22, Verse 28', 'भज प्रीतिं प्रहर्षं च त्यजैतां नित्यदैन्यताम्।
सीते राक्षसराजेन सह क्रीड यथासुखम्॥', 'bhaja prītiṃ praharṣaṃ ca tyajaitāṃ nityadainyatām
sīte rākṣasarājena saha krīḍa yathāsukham', null, 5022028),
('ramayana-5-22-29', 29, 'Sundara Kanda, Sarga 22, Verse 29', 'जानासि हि यथा भीरु स्त्रीणां यौवनमध्रुवम्।
यावन्न ते व्यतिक्रामेत्तावत्सुखमवाप्नुहि॥', 'jānāsi hi yathā bhīru strīṇāṃ yauvanam adhruvam
yāvan na te vyatikrāmet tāvat sukham avāpnuhi', null, 5022029),
('ramayana-5-22-30', 30, 'Sundara Kanda, Sarga 22, Verse 30', 'उद्यानानि च रम्याणि पर्वतोपवनानि च।
सह राक्षसराजेन चर त्वं मदिरेक्षणे॥', 'udyānāni ca ramyāṇi parvatopavanāni ca
saha rākṣasarājena cara tvaṃ madirekṣaṇe', null, 5022030),
('ramayana-5-22-31', 31, 'Sundara Kanda, Sarga 22, Verse 31', 'स्त्रीसहस्राणि ते सप्त वशे स्थास्यन्ति सुन्दरि।
रावणं भज भर्तारं भर्तारं सर्वरक्षसाम्॥', 'strīsahasrāṇi te sapta vaśe sthāsyanti sundari
rāvaṇaṃ bhaja bhartāraṃ bhartāraṃ sarvarakṣasām', null, 5022031),
('ramayana-5-22-32', 32, 'Sundara Kanda, Sarga 22, Verse 32', 'उत्पाट्य वा ते हृदयं भक्षयिष्यामि मैथिलि।
यदि मे व्याहृतं वाक्यं न यथावत्करिष्यसि॥', 'utpāṭya vā te hṛdayaṃ bhakṣayiṣyāmi maithili
yadi me vyāhṛtaṃ vākyaṃ na yathāvat kariṣyasi', null, 5022032),
('ramayana-5-22-33', 33, 'Sundara Kanda, Sarga 22, Verse 33', 'ततश्चण्डोदरी नाम राक्षसी क्रूरदर्शना।
भ्रामयन्ती महच्छूलमिदं वचनमब्रवीत्॥', 'tataś caṇḍodarī nāma rākṣasī krūradarśanā
bhrāmayantī mahac chūlam idaṃ vacanam abravīt', null, 5022033),
('ramayana-5-22-34', 34, 'Sundara Kanda, Sarga 22, Verse 34', 'इमां हरिणलोकाक्षीं त्रासोत्कम्पपयोधराम्।
रावणेन हृतां दृष्ट्वा दौर्हृदो मे महानभूत्॥', 'imāṃ hariṇalokākṣīṃ trāsotkampapayodharām
rāvaṇena hṛtāṃ dṛṣṭvā daurhṛdo me mahān abhūt', null, 5022034),
('ramayana-5-22-35', 35, 'Sundara Kanda, Sarga 22, Verse 35', 'यकृत्प्लीहमथोत्पीडं हृदयं च सबन्धनम्।
अन्त्राण्यपि तथा शीर्षं खादेयमिति मे मतिः॥', 'yakṛtplīham athotpīḍaṃ hṛdayaṃ ca sabandhanam
antrāṇy api tathā śīrṣaṃ khādeyam iti me matiḥ', null, 5022035),
('ramayana-5-22-36', 36, 'Sundara Kanda, Sarga 22, Verse 36', 'ततस्तु प्रघसा नाम राक्षसी वाक्यमब्रवीत्।
कण्ठमस्या नृशंसायाः पीडयामः किमास्यते॥', 'tatas tu praghasā nāma rākṣasī vākyam abravīt
kaṇṭham asyā nṛśaṃsāyāḥ pīḍayāmaḥ kim āsyate', null, 5022036),
('ramayana-5-22-37', 37, 'Sundara Kanda, Sarga 22, Verse 37', 'निवेद्यतां ततो राज्ञे मानुषी सा मृतेति ह।
नात्र कश्चन संदेहः खादतेति स वक्ष्यति॥', 'nivedyatāṃ tato rājñe mānuṣī sā mṛteti ha
nātra kaś cana saṃdehaḥ khādateti sa vakṣyati', null, 5022037),
('ramayana-5-22-38', 38, 'Sundara Kanda, Sarga 22, Verse 38', 'ततस्त्वजामुखी नाम राक्षसी वाक्यमब्रवीत्।
विशस्येमां ततः सर्वान्समान्कुरुत पीलुकान्॥', 'tatas tv ajāmukhī nāma rākṣasī vākyam abravīt
viśasyemāṃ tataḥ sarvān samān kuruta pīlukān', null, 5022038),
('ramayana-5-22-39', 39, 'Sundara Kanda, Sarga 22, Verse 39', 'विभजाम ततः सर्वा विवादो मे न रोचते।
पेयमानीयतां क्षिप्रं माल्यं च विविधं बहु॥', 'vibhajāma tataḥ sarvā vivādo me na rocate
peyam ānīyatāṃ kṣipraṃ mālyaṃ ca vividhaṃ bahu', null, 5022039),
('ramayana-5-22-40', 40, 'Sundara Kanda, Sarga 22, Verse 40', 'ततः शूर्पणखा नाम राक्षसी वाक्यमब्रवीत्।
अजामुखा यदुक्तं हि तदेव मम रोचते॥', 'tataḥ śūrpaṇakhā nāma rākṣasī vākyam abravīt
ajāmukhā yad uktaṃ hi tad eva mama rocate', null, 5022040),
('ramayana-5-22-41', 41, 'Sundara Kanda, Sarga 22, Verse 41', 'सुरा चानीयतां क्षिप्रं सर्वशोकविनाशिनी।
मानुषं मांसमासाद्य नृत्यामोऽथ निकुम्भिलाम्॥', 'surā cānīyatāṃ kṣipraṃ sarvaśokavināśinī
mānuṣaṃ māṃsam āsādya nṛtyāmo ''tha nikumbhilām', null, 5022041),
('ramayana-5-22-42', 42, 'Sundara Kanda, Sarga 22, Verse 42', 'एवं संभर्त्स्यमाना सा सीता सुरसुतोपमा।
राक्षसीभिः सुघोराभिर्धैर्यमुत्सृज्य रोदिति॥', 'evaṃ saṃbhartsyamānā sā sītā surasutopamā
rākṣasībhiḥ sughorābhir dhairyam utsṛjya roditi', null, 5022042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 23 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-23-1', 1, 'Sundara Kanda, Sarga 23, Verse 1', 'तथा तासां वदन्तीनां परुषं दारुणं बहु।
राक्षसीनामसौम्यानां रुरोद जनकात्मजा॥', 'tathā tāsāṃ vadantīnāṃ paruṣaṃ dāruṇaṃ bahu
rākṣasīnām asaumyānāṃ ruroda janakātmajā', null, 5023001),
('ramayana-5-23-2', 2, 'Sundara Kanda, Sarga 23, Verse 2', 'एवमुक्ता तु वैदेही राक्षसीभिर्मनस्विनी।
उवाच परमत्रस्ता बाष्पगद्गदया गिरा॥', 'evam uktā tu vaidehī rākṣasībhir manasvinī
uvāca paramatrastā bāṣpagadgadayā girā', null, 5023002),
('ramayana-5-23-3', 3, 'Sundara Kanda, Sarga 23, Verse 3', 'न मानुषी राक्षसस्य भार्या भवितुमर्हति।
कामं खादत मां सर्वा न करिष्यामि वो वचः॥', 'na mānuṣī rākṣasasya bhāryā bhavitum arhati
kāmaṃ khādata māṃ sarvā na kariṣyāmi vo vacaḥ', null, 5023003),
('ramayana-5-23-4', 4, 'Sundara Kanda, Sarga 23, Verse 4', 'सा राक्षसी मध्यगता सीता सुरसुतोपमा।
न शर्म लेभे दुःखार्ता रावणेन च तर्जिता॥', 'sā rākṣasī madhyagatā sītā surasutopamā
na śarma lebhe duḥkhārtā rāvaṇena ca tarjitā', null, 5023004),
('ramayana-5-23-5', 5, 'Sundara Kanda, Sarga 23, Verse 5', 'वेपते स्माधिकं सीता विशन्तीवाङ्गमात्मनः।
वने यूथपरिभ्रष्टा मृगी कोकैरिवार्दिता॥', 'vepate smādhikaṃ sītā viśantīvāṅgam ātmanaḥ
vane yūthaparibhraṣṭā mṛgī kokair ivārditā', null, 5023005),
('ramayana-5-23-6', 6, 'Sundara Kanda, Sarga 23, Verse 6', 'सा त्वशोकस्य विपुलां शाखामालम्ब्य पुष्पिताम्।
चिन्तयामास शोकेन भर्तारं भग्नमानसा॥', 'sā tv aśokasya vipulāṃ śākhām ālambya puṣpitām
cintayām āsa śokena bhartāraṃ bhagnamānasā', null, 5023006),
('ramayana-5-23-7', 7, 'Sundara Kanda, Sarga 23, Verse 7', 'सा स्नापयन्ती विपुलौ स्तनौ नेत्रजलस्रवैः।
चिन्तयन्ती न शोकस्य तदान्तमधिगच्छति॥', 'sā snāpayantī vipulau stanau netrajalasravaiḥ
cintayantī na śokasya tadāntam adhigacchati', null, 5023007),
('ramayana-5-23-8', 8, 'Sundara Kanda, Sarga 23, Verse 8', 'सा वेपमाना पतिता प्रवाते कदली यथा।
राक्षसीनां भयत्रस्ता विवर्णवदनाभवत्॥', 'sā vepamānā patitā pravāte kadalī yathā
rākṣasīnāṃ bhayatrastā vivarṇavadanābhavat', null, 5023008),
('ramayana-5-23-9', 9, 'Sundara Kanda, Sarga 23, Verse 9', 'तस्या सा दीर्घविपुला वेपन्त्याः सीतया तदा।
ददृशे कम्पिनी वेणी व्यालीव परिसर्पती॥', 'tasyā sā dīrghavipulā vepantyāḥ sītayā tadā
dadṛśe kampinī veṇī vyālīva parisarpatī', null, 5023009),
('ramayana-5-23-10', 10, 'Sundara Kanda, Sarga 23, Verse 10', 'सा निःश्वसन्ती दुःखार्ता शोकोपहतचेतना।
आर्ता व्यसृजदश्रूणि मैथिली विललाप ह॥', 'sā niḥśvasantī duḥkhārtā śokopahatacetanā
ārtā vyasṛjad aśrūṇi maithilī vilalāpa ha', null, 5023010),
('ramayana-5-23-11', 11, 'Sundara Kanda, Sarga 23, Verse 11', 'हा रामेति च दुःखार्ता पुनर्हा लक्ष्मणेति च।
हा श्वश्रु मम कौसल्ये हा सुमित्रेति भाविनि॥', 'hā rāmeti ca duḥkhārtā punar hā lakṣmaṇeti ca
hā śvaśru mama kausalye hā sumitreti bhāvini', null, 5023011),
('ramayana-5-23-12', 12, 'Sundara Kanda, Sarga 23, Verse 12', 'लोकप्रवादः सत्योऽयं पण्डितैः समुदाहृतः।
अकाले दुर्लभो मृत्युः स्त्रिया वा पुरुषस्य वा॥', 'lokapravādaḥ satyo ''yaṃ paṇḍitaiḥ samudāhṛtaḥ
akāle durlabho mṛtyuḥ striyā vā puruṣasya vā', null, 5023012),
('ramayana-5-23-13', 13, 'Sundara Kanda, Sarga 23, Verse 13', 'यत्राहमाभिः क्रूराभी राक्षसीभिरिहार्दिता।
जीवामि हीना रामेण मुहूर्तमपि दुःखिता॥', 'yatrāham ābhiḥ krūrābhī rākṣasībhir ihārditā
jīvāmi hīnā rāmeṇa muhūrtam api duḥkhitā', null, 5023013),
('ramayana-5-23-14', 14, 'Sundara Kanda, Sarga 23, Verse 14', 'एषाल्पपुण्या कृपणा विनशिष्याम्यनाथवत्।
समुद्रमध्ये नौ पूर्णा वायुवेगैरिवाहता॥', 'eṣālpapuṇyā kṛpaṇā vinaśiṣyāmy anāthavat
samudramadhye nau pūrṇā vāyuvegair ivāhatā', null, 5023014),
('ramayana-5-23-15', 15, 'Sundara Kanda, Sarga 23, Verse 15', 'भर्तारं तमपश्यन्ती राक्षसीवशमागता।
सीदामि खलु शोकेन कूलं तोयहतं यथा॥', 'bhartāraṃ tam apaśyantī rākṣasīvaśam āgatā
sīdāmi khalu śokena kūlaṃ toyahataṃ yathā', null, 5023015),
('ramayana-5-23-16', 16, 'Sundara Kanda, Sarga 23, Verse 16', 'तं पद्मदलपत्राक्षं सिंहविक्रान्तगामिनम्।
धन्याः पश्यन्ति मे नाथं कृतज्ञं प्रियवादिनम्॥', 'taṃ padmadalapatrākṣaṃ siṃhavikrāntagāminam
dhanyāḥ paśyanti me nāthaṃ kṛtajñaṃ priyavādinam', null, 5023016),
('ramayana-5-23-17', 17, 'Sundara Kanda, Sarga 23, Verse 17', 'सर्वथा तेन हीनाया रामेण विदितात्मना।
तीष्क्णं विषमिवास्वाद्य दुर्लभं मम जीवितम्॥', 'sarvathā tena hīnāyā rāmeṇa viditātmanā
tīṣkṇaṃ viṣam ivāsvādya durlabhaṃ mama jīvitam', null, 5023017),
('ramayana-5-23-18', 18, 'Sundara Kanda, Sarga 23, Verse 18', 'कीदृशं तु मया पापं पुरा देहान्तरे कृतम्।
येनेदं प्राप्यते दुःखं मया घोरं सुदारुणम्॥', 'kīdṛśaṃ tu mayā pāpaṃ purā dehāntare kṛtam
yenedaṃ prāpyate duḥkhaṃ mayā ghoraṃ sudāruṇam', null, 5023018),
('ramayana-5-23-19', 19, 'Sundara Kanda, Sarga 23, Verse 19', 'जीवितं त्यक्तुमिच्छामि शोकेन महता वृता।
राक्षसीभिश्च रक्षन्त्या रामो नासाद्यते मया॥', 'jīvitaṃ tyaktum icchāmi śokena mahatā vṛtā
rākṣasībhiś ca rakṣantyā rāmo nāsādyate mayā', null, 5023019),
('ramayana-5-23-20', 20, 'Sundara Kanda, Sarga 23, Verse 20', 'धिगस्तु खलु मानुष्यं धिगस्तु परवश्यताम्।
न शक्यं यत्परित्यक्तुमात्मच्छन्देन जीवितम्॥', 'dhig astu khalu mānuṣyaṃ dhig astu paravaśyatām
na śakyaṃ yat parityaktum ātmacchandena jīvitam', null, 5023020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 24 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-24-1', 1, 'Sundara Kanda, Sarga 24, Verse 1', 'प्रसक्ताश्रुमुखीत्येवं ब्रुवन्ती जनकात्मजा।
अधोमुखमुखी बाला विलप्तुमुपचक्रमे॥', 'prasaktāśrumukhīty evaṃ bruvantī janakātmajā
adhomukhamukhī bālā vilaptum upacakrame', null, 5024001),
('ramayana-5-24-2', 2, 'Sundara Kanda, Sarga 24, Verse 2', 'उन्मत्तेव प्रमत्तेव भ्रान्तचित्तेव शोचती।
उपावृत्ता किशोरीव विवेष्टन्ती महीतले॥', 'unmatteva pramatteva bhrāntacitteva śocatī
upāvṛttā kiśorīva viveṣṭantī mahītale', null, 5024002),
('ramayana-5-24-3', 3, 'Sundara Kanda, Sarga 24, Verse 3', 'राघवस्याप्रमत्तस्य रक्षसा कामरूपिणा।
रावणेन प्रमथ्याहमानीता क्रोशती बलात्॥', 'rāghavasyāpramattasya rakṣasā kāmarūpiṇā
rāvaṇena pramathyāham ānītā krośatī balāt', null, 5024003),
('ramayana-5-24-4', 4, 'Sundara Kanda, Sarga 24, Verse 4', 'राक्षसी वशमापन्ना भर्त्यमाना सुदारुणम्।
चिन्तयन्ती सुदुःखार्ता नाहं जीवितुमुत्सहे॥', 'rākṣasī vaśam āpannā bhartyamānā sudāruṇam
cintayantī suduḥkhārtā nāhaṃ jīvitum utsahe', null, 5024004),
('ramayana-5-24-5', 5, 'Sundara Kanda, Sarga 24, Verse 5', 'न हि मे जीवितेनार्थो नैवार्थैर्न च भूषणैः।
वसन्त्या राक्षसी मध्ये विना रामं महारथम्॥', 'na hi me jīvitenārtho naivārthair na ca bhūṣaṇaiḥ
vasantyā rākṣasī madhye vinā rāmaṃ mahāratham', null, 5024005),
('ramayana-5-24-6', 6, 'Sundara Kanda, Sarga 24, Verse 6', 'धिङ्मामनार्यामसतीं याहं तेन विना कृता।
मुहूर्तमपि रक्षामि जीवितं पापजीविता॥', 'dhiṅ mām anāryām asatīṃ yāhaṃ tena vinā kṛtā
muhūrtam api rakṣāmi jīvitaṃ pāpajīvitā', null, 5024006),
('ramayana-5-24-7', 7, 'Sundara Kanda, Sarga 24, Verse 7', 'का च मे जीविते श्रद्धा सुखे वा तं प्रियं विना।
भर्तारं सागरान्ताया वसुधायाः प्रियं वदम्॥', 'kā ca me jīvite śraddhā sukhe vā taṃ priyaṃ vinā
bhartāraṃ sāgarāntāyā vasudhāyāḥ priyaṃ vadam', null, 5024007),
('ramayana-5-24-8', 8, 'Sundara Kanda, Sarga 24, Verse 8', 'भिद्यतां भक्ष्यतां वापि शरीरं विसृजाम्यहम्।
न चाप्यहं चिरं दुःखं सहेयं प्रियवर्जिता॥', 'bhidyatāṃ bhakṣyatāṃ vāpi śarīraṃ visṛjāmy aham
na cāpy ahaṃ ciraṃ duḥkhaṃ saheyaṃ priyavarjitā', null, 5024008),
('ramayana-5-24-9', 9, 'Sundara Kanda, Sarga 24, Verse 9', 'चरणेनापि सव्येन न स्पृशेयं निशाचरम्।
रावणं किं पुनरहं कामयेयं विगर्हितम्॥', 'caraṇenāpi savyena na spṛśeyaṃ niśācaram
rāvaṇaṃ kiṃ punar ahaṃ kāmayeyaṃ vigarhitam', null, 5024009),
('ramayana-5-24-10', 10, 'Sundara Kanda, Sarga 24, Verse 10', 'प्रत्याख्यातं न जानाति नात्मानं नात्मनः कुलम्।
यो नृशंस स्वभावेन मां प्रार्थयितुमिच्छति॥', 'pratyākhyātaṃ na jānāti nātmānaṃ nātmanaḥ kulam
yo nṛśaṃsa svabhāvena māṃ prārthayitum icchati', null, 5024010),
('ramayana-5-24-11', 11, 'Sundara Kanda, Sarga 24, Verse 11', 'छिन्ना भिन्ना विभक्ता वा दीप्ते वाग्नौ प्रदीपिता।
रावणं नोपतिष्ठेयं किं प्रलापेन वश्चिरम्॥', 'chinnā bhinnā vibhaktā vā dīpte vāgnau pradīpitā
rāvaṇaṃ nopatiṣṭheyaṃ kiṃ pralāpena vaś ciram', null, 5024011),
('ramayana-5-24-12', 12, 'Sundara Kanda, Sarga 24, Verse 12', 'ख्यातः प्राज्ञः कृतज्ञश्च सानुक्रोशश्च राघवः।
सद्वृत्तो निरनुक्रोशः शङ्के मद्भाग्यसंक्षयात्॥', 'khyātaḥ prājñaḥ kṛtajñaś ca sānukrośaś ca rāghavaḥ
sadvṛtto niranukrośaḥ śaṅke madbhāgyasaṃkṣayāt', null, 5024012),
('ramayana-5-24-13', 13, 'Sundara Kanda, Sarga 24, Verse 13', 'राक्षसानां जनस्थाने सहस्राणि चतुर्दश।
येनैकेन निरस्तानि स मां किं नाभिपद्यते॥', 'rākṣasānāṃ janasthāne sahasrāṇi caturdaśa
yenaikena nirastāni sa māṃ kiṃ nābhipadyate', null, 5024013),
('ramayana-5-24-14', 14, 'Sundara Kanda, Sarga 24, Verse 14', 'निरुद्धा रावणेनाहमल्पवीर्येण रक्षसा।
समर्थः खलु मे भर्ता रावणं हन्तुमाहवे॥', 'niruddhā rāvaṇenāham alpavīryeṇa rakṣasā
samarthaḥ khalu me bhartā rāvaṇaṃ hantum āhave', null, 5024014),
('ramayana-5-24-15', 15, 'Sundara Kanda, Sarga 24, Verse 15', 'विराधो दण्डकारण्ये येन राक्षसपुंगवः।
रणे रामेण निहतः स मां किं नाभिपद्यते॥', 'virādho daṇḍakāraṇye yena rākṣasapuṃgavaḥ
raṇe rāmeṇa nihataḥ sa māṃ kiṃ nābhipadyate', null, 5024015),
('ramayana-5-24-16', 16, 'Sundara Kanda, Sarga 24, Verse 16', 'कामं मध्ये समुद्रस्य लङ्केयं दुष्प्रधर्षणा।
न तु राघवबाणानां गतिरोधी ह विद्यते॥', 'kāmaṃ madhye samudrasya laṅkeyaṃ duṣpradharṣaṇā
na tu rāghavabāṇānāṃ gatirodhī ha vidyate', null, 5024016),
('ramayana-5-24-17', 17, 'Sundara Kanda, Sarga 24, Verse 17', 'किं नु तत्कारणं येन रामो दृढपराक्रमः।
रक्षसापहृतां भार्यामिष्टां नाभ्यवपद्यते॥', 'kiṃ nu tat kāraṇaṃ yena rāmo dṛḍhaparākramaḥ
rakṣasāpahṛtāṃ bhāryām iṣṭāṃ nābhyavapadyate', null, 5024017),
('ramayana-5-24-18', 18, 'Sundara Kanda, Sarga 24, Verse 18', 'इहस्थां मां न जानीते शङ्के लक्ष्मणपूर्वजः।
जानन्नपि हि तेजस्वी धर्षणां मर्षयिष्यति॥', 'ihasthāṃ māṃ na jānīte śaṅke lakṣmaṇapūrvajaḥ
jānann api hi tejasvī dharṣaṇāṃ marṣayiṣyati', null, 5024018),
('ramayana-5-24-19', 19, 'Sundara Kanda, Sarga 24, Verse 19', 'हृतेति योऽधिगत्वा मां राघवाय निवेदयेत्।
गृध्रराजोऽपि स रणे रावणेन निपातितः॥', 'hṛteti yo ''dhigatvā māṃ rāghavāya nivedayet
gṛdhrarājo ''pi sa raṇe rāvaṇena nipātitaḥ', null, 5024019),
('ramayana-5-24-20', 20, 'Sundara Kanda, Sarga 24, Verse 20', 'कृतं कर्म महत्तेन मां तदाभ्यवपद्यता।
तिष्ठता रावणद्वन्द्वे वृद्धेनापि जटायुषा॥', 'kṛtaṃ karma mahat tena māṃ tadābhyavapadyatā
tiṣṭhatā rāvaṇadvandve vṛddhenāpi jaṭāyuṣā', null, 5024020),
('ramayana-5-24-21', 21, 'Sundara Kanda, Sarga 24, Verse 21', 'यदि मामिह जानीयाद्वर्तमानां स राघवः।
अद्य बाणैरभिक्रुद्धः कुर्याल्लोकमराक्षसं॥', 'yadi mām iha jānīyād vartamānāṃ sa rāghavaḥ
adya bāṇair abhikruddhaḥ kuryāl lokam arākṣasaṃ', null, 5024021),
('ramayana-5-24-22', 22, 'Sundara Kanda, Sarga 24, Verse 22', 'विधमेच्च पुरीं लङ्कां शोषयेच्च महोदधिम्।
रावणस्य च नीचस्य कीर्तिं नाम च नाशयेत्॥', 'vidhamec ca purīṃ laṅkāṃ śoṣayec ca mahodadhim
rāvaṇasya ca nīcasya kīrtiṃ nāma ca nāśayet', null, 5024022),
('ramayana-5-24-23', 23, 'Sundara Kanda, Sarga 24, Verse 23', 'ततो निहतनथानां राक्षसीनां गृहे गृहे।
यथाहमेवं रुदती तथा भूयो न संशयः।
अन्विष्य रक्षसां लङ्कां कुर्याद्रामः सलक्ष्मणः॥', 'tato nihatanathānāṃ rākṣasīnāṃ gṛhe gṛhe
yathāham evaṃ rudatī tathā bhūyo na saṃśayaḥ
anviṣya rakṣasāṃ laṅkāṃ kuryād rāmaḥ salakṣmaṇaḥ', null, 5024023),
('ramayana-5-24-24', 24, 'Sundara Kanda, Sarga 24, Verse 24', 'न हि ताभ्यां रिपुर्दृष्टो मुहूतमपि जीवति।
चिता धूमाकुलपथा गृध्रमण्डलसंकुला।
अचिरेण तु लङ्केयं श्मशानसदृशी भवेत्॥', 'na hi tābhyāṃ ripur dṛṣṭo muhūtam api jīvati
citā dhūmākulapathā gṛdhramaṇḍalasaṃkulā
acireṇa tu laṅkeyaṃ śmaśānasadṛśī bhavet', null, 5024024),
('ramayana-5-24-25', 25, 'Sundara Kanda, Sarga 24, Verse 25', 'अचिरेणैव कालेन प्राप्स्याम्येव मनोरथम्।
दुष्प्रस्थानोऽयमाख्याति सर्वेषां वो विपर्ययः॥', 'acireṇaiva kālena prāpsyāmy eva manoratham
duṣprasthāno ''yam ākhyāti sarveṣāṃ vo viparyayaḥ', null, 5024025),
('ramayana-5-24-26', 26, 'Sundara Kanda, Sarga 24, Verse 26', 'यादृशानि तु दृश्यन्ते लङ्कायामशुभानि तु।
अचिरेणैव कालेन भविष्यति हतप्रभा॥', 'yādṛśāni tu dṛśyante laṅkāyām aśubhāni tu
acireṇaiva kālena bhaviṣyati hataprabhā', null, 5024026),
('ramayana-5-24-27', 27, 'Sundara Kanda, Sarga 24, Verse 27', 'नूनं लङ्का हते पापे रावणे राक्षसाधिपे।
शोषं यास्यति दुर्धर्षा प्रमदा विधवा यथा॥', 'nūnaṃ laṅkā hate pāpe rāvaṇe rākṣasādhipe
śoṣaṃ yāsyati durdharṣā pramadā vidhavā yathā', null, 5024027),
('ramayana-5-24-28', 28, 'Sundara Kanda, Sarga 24, Verse 28', 'पुष्योत्सवसमृद्धा च नष्टभर्त्री सराक्षसा।
भविष्यति पुरी लङ्का नष्टभर्त्री यथाङ्गना॥', 'puṣyotsavasamṛddhā ca naṣṭabhartrī sarākṣasā
bhaviṣyati purī laṅkā naṣṭabhartrī yathāṅganā', null, 5024028),
('ramayana-5-24-29', 29, 'Sundara Kanda, Sarga 24, Verse 29', 'नूनं राक्षसकन्यानां रुदन्तीनां गृहे गृहे।
श्रोष्यामि नचिरादेव दुःखार्तानामिह ध्वनिम्॥', 'nūnaṃ rākṣasakanyānāṃ rudantīnāṃ gṛhe gṛhe
śroṣyāmi nacirād eva duḥkhārtānām iha dhvanim', null, 5024029),
('ramayana-5-24-30', 30, 'Sundara Kanda, Sarga 24, Verse 30', 'सान्धकारा हतद्योता हतराक्षसपुंगवा।
भविष्यति पुरी लङ्का निर्दग्धा रामसायकैः॥', 'sāndhakārā hatadyotā hatarākṣasapuṃgavā
bhaviṣyati purī laṅkā nirdagdhā rāmasāyakaiḥ', null, 5024030),
('ramayana-5-24-31', 31, 'Sundara Kanda, Sarga 24, Verse 31', 'यदि नाम स शूरो मां रामो रक्तान्तलोचनः।
जानीयाद्वर्तमानां हि रावणस्य निवेशने॥', 'yadi nāma sa śūro māṃ rāmo raktāntalocanaḥ
jānīyād vartamānāṃ hi rāvaṇasya niveśane', null, 5024031),
('ramayana-5-24-32', 32, 'Sundara Kanda, Sarga 24, Verse 32', 'अनेन तु नृशंसेन रावणेनाधमेन मे।
समयो यस्तु निर्दिष्टस्तस्य कालोऽयमागतः॥', 'anena tu nṛśaṃsena rāvaṇenādhamena me
samayo yas tu nirdiṣṭas tasya kālo ''yam āgataḥ', null, 5024032),
('ramayana-5-24-33', 33, 'Sundara Kanda, Sarga 24, Verse 33', 'अकार्यं ये न जानन्ति नैरृताः पापकारिणः।
अधर्मात्तु महोत्पातो भविष्यति हि साम्प्रतम्॥', 'akāryaṃ ye na jānanti nairṛtāḥ pāpakāriṇaḥ
adharmāt tu mahotpāto bhaviṣyati hi sāmpratam', null, 5024033),
('ramayana-5-24-34', 34, 'Sundara Kanda, Sarga 24, Verse 34', 'नैते धर्मं विजानन्ति राक्षसाः पिशिताशनाः।
ध्रुवं मां प्रातराशार्थे राक्षसः कल्पयिष्यति॥', 'naite dharmaṃ vijānanti rākṣasāḥ piśitāśanāḥ
dhruvaṃ māṃ prātarāśārthe rākṣasaḥ kalpayiṣyati', null, 5024034),
('ramayana-5-24-35', 35, 'Sundara Kanda, Sarga 24, Verse 35', 'साहं कथं करिष्यामि तं विना प्रियदर्शनम्।
रामं रक्तान्तनयनमपश्यन्ती सुदुःखिता॥', 'sāhaṃ kathaṃ kariṣyāmi taṃ vinā priyadarśanam
rāmaṃ raktāntanayanam apaśyantī suduḥkhitā', null, 5024035),
('ramayana-5-24-36', 36, 'Sundara Kanda, Sarga 24, Verse 36', 'यदि कश्चित्प्रदाता मे विषस्याद्य भवेदिह।
क्षिप्रं वैवस्वतं देवं पश्येयं पतिना विना॥', 'yadi kaś cit pradātā me viṣasyādya bhaved iha
kṣipraṃ vaivasvataṃ devaṃ paśyeyaṃ patinā vinā', null, 5024036),
('ramayana-5-24-37', 37, 'Sundara Kanda, Sarga 24, Verse 37', 'नाजानाज्जीवतीं रामः स मां लक्ष्मणपूर्वजः।
जानन्तौ तौ न कुर्यातां नोर्व्यां हि मम मार्गणम्॥', 'nājānāj jīvatīṃ rāmaḥ sa māṃ lakṣmaṇapūrvajaḥ
jānantau tau na kuryātāṃ norvyāṃ hi mama mārgaṇam', null, 5024037),
('ramayana-5-24-38', 38, 'Sundara Kanda, Sarga 24, Verse 38', 'नूनं ममैव शोकेन स वीरो लक्ष्मणाग्रजः।
देवलोकमितो यातस्त्यक्त्वा देहं महीतले॥', 'nūnaṃ mamaiva śokena sa vīro lakṣmaṇāgrajaḥ
devalokam ito yātas tyaktvā dehaṃ mahītale', null, 5024038),
('ramayana-5-24-39', 39, 'Sundara Kanda, Sarga 24, Verse 39', 'धन्या देवाः सगन्धर्वाः सिद्धाश्च परमर्षयः।
मम पश्यन्ति ये नाथं रामं राजीवलोचनम्॥', 'dhanyā devāḥ sagandharvāḥ siddhāś ca paramarṣayaḥ
mama paśyanti ye nāthaṃ rāmaṃ rājīvalocanam', null, 5024039),
('ramayana-5-24-40', 40, 'Sundara Kanda, Sarga 24, Verse 40', 'अथ वा न हि तस्यार्थे धर्मकामस्य धीमतः।
मया रामस्य राजर्षेर्भार्यया परमात्मनः॥', 'atha vā na hi tasyārthe dharmakāmasya dhīmataḥ
mayā rāmasya rājarṣer bhāryayā paramātmanaḥ', null, 5024040),
('ramayana-5-24-41', 41, 'Sundara Kanda, Sarga 24, Verse 41', 'दृश्यमाने भवेत्प्रीतः सौहृदं नास्त्यपश्यतः।
नाशयन्ति कृतघ्रास्तु न रामो नाशयिष्यति॥', 'dṛśyamāne bhavet prītaḥ sauhṛdaṃ nāsty apaśyataḥ
nāśayanti kṛtaghrās tu na rāmo nāśayiṣyati', null, 5024041),
('ramayana-5-24-42', 42, 'Sundara Kanda, Sarga 24, Verse 42', 'किं नु मे न गुणाः के चित्किं वा भाग्य क्षयो हि मे।
याहं सीता वरार्हेण हीना रामेण भामिनी॥', 'kiṃ nu me na guṇāḥ ke cit kiṃ vā bhāgya kṣayo hi me
yāhaṃ sītā varārheṇa hīnā rāmeṇa bhāminī', null, 5024042),
('ramayana-5-24-43', 43, 'Sundara Kanda, Sarga 24, Verse 43', 'श्रेयो मे जीवितान्मर्तुं विहीना या महात्मना।
रामादक्लिष्टचारित्राच्छूराच्छत्रुनिबर्हणात्॥', 'śreyo me jīvitān martuṃ vihīnā yā mahātmanā
rāmād akliṣṭacāritrāc chūrāc chatrunibarhaṇāt', null, 5024043),
('ramayana-5-24-44', 44, 'Sundara Kanda, Sarga 24, Verse 44', 'अथ वा न्यस्तशस्त्रौ तौ वने मूलफलाशनौ।
भ्रातरौ हि नर श्रेष्ठौ चरन्तौ वनगोचरौ॥', 'atha vā nyastaśastrau tau vane mūlaphalāśanau
bhrātarau hi nara śreṣṭhau carantau vanagocarau', null, 5024044),
('ramayana-5-24-45', 45, 'Sundara Kanda, Sarga 24, Verse 45', 'अथ वा राक्षसेन्द्रेण रावणेन दुरात्मना।
छद्मना घातितौ शूरौ भ्रातरौ रामलक्ष्मणौ॥', 'atha vā rākṣasendreṇa rāvaṇena durātmanā
chadmanā ghātitau śūrau bhrātarau rāmalakṣmaṇau', null, 5024045),
('ramayana-5-24-46', 46, 'Sundara Kanda, Sarga 24, Verse 46', 'साहमेवंगते काले मर्तुमिच्छामि सर्वथा।
न च मे विहितो मृत्युरस्मिन्दुःखेऽपि वर्तति॥', 'sāham evaṃgate kāle martum icchāmi sarvathā
na ca me vihito mṛtyur asmin duḥkhe ''pi vartati', null, 5024046),
('ramayana-5-24-47', 47, 'Sundara Kanda, Sarga 24, Verse 47', 'धन्याः खलु महात्मानो मुनयः सत्यसंमताः।
जितात्मानो महाभागा येषां न स्तः प्रियाप्रिये॥', 'dhanyāḥ khalu mahātmāno munayaḥ satyasaṃmatāḥ
jitātmāno mahābhāgā yeṣāṃ na staḥ priyāpriye', null, 5024047),
('ramayana-5-24-48', 48, 'Sundara Kanda, Sarga 24, Verse 48', 'प्रियान्न संभवेद्दुःखमप्रियादधिकं भयम्।
ताभ्यां हि ये वियुज्यन्ते नमस्तेषां महात्मनाम्॥', 'priyān na saṃbhaved duḥkham apriyād adhikaṃ bhayam
tābhyāṃ hi ye viyujyante namas teṣāṃ mahātmanām', null, 5024048),
('ramayana-5-24-49', 49, 'Sundara Kanda, Sarga 24, Verse 49', 'साहं त्यक्ता प्रियेणेह रामेण विदितात्मना।
प्राणांस्त्यक्ष्यामि पापस्य रावणस्य गता वशम्॥', 'sāhaṃ tyaktā priyeṇeha rāmeṇa viditātmanā
prāṇāṃs tyakṣyāmi pāpasya rāvaṇasya gatā vaśam', null, 5024049)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 25 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-25-1', 1, 'Sundara Kanda, Sarga 25, Verse 1', 'इत्युक्ताः सीतया घोरं राक्षस्यः क्रोधमूर्छिताः।
काश्चिज्जग्मुस्तदाख्यातुं रावणस्य तरस्विनः॥', 'ity uktāḥ sītayā ghoraṃ rākṣasyaḥ krodhamūrchitāḥ
kāś cij jagmus tad ākhyātuṃ rāvaṇasya tarasvinaḥ', null, 5025001),
('ramayana-5-25-2', 2, 'Sundara Kanda, Sarga 25, Verse 2', 'ततः सीतामुपागम्य राक्षस्यो घोरदर्शनाः।
पुनः परुषमेकार्थमनर्थार्थमथाब्रुवन्॥', 'tataḥ sītām upāgamya rākṣasyo ghoradarśanāḥ
punaḥ paruṣam ekārtham anarthārtham athābruvan', null, 5025002),
('ramayana-5-25-3', 3, 'Sundara Kanda, Sarga 25, Verse 3', 'हन्तेदानीं तवानार्ये सीते पापविनिश्चये।
राक्षस्यो भक्षयिष्यन्ति मांसमेतद्यथासुखम्॥', 'hantedānīṃ tavānārye sīte pāpaviniścaye
rākṣasyo bhakṣayiṣyanti māṃsam etad yathāsukham', null, 5025003),
('ramayana-5-25-4', 4, 'Sundara Kanda, Sarga 25, Verse 4', 'सीतां ताभिरनार्याभिर्दृष्ट्वा संतर्जितां तदा।
राक्षसी त्रिजटावृद्धा शयाना वाक्यमब्रवीत्॥', 'sītāṃ tābhir anāryābhir dṛṣṭvā saṃtarjitāṃ tadā
rākṣasī trijaṭāvṛddhā śayānā vākyam abravīt', null, 5025004),
('ramayana-5-25-5', 5, 'Sundara Kanda, Sarga 25, Verse 5', 'आत्मानं खादतानार्या न सीतां भक्षयिष्यथ।
जनकस्य सुतामिष्टां स्नुषां दशरथस्य च॥', 'ātmānaṃ khādatānāryā na sītāṃ bhakṣayiṣyatha
janakasya sutām iṣṭāṃ snuṣāṃ daśarathasya ca', null, 5025005),
('ramayana-5-25-6', 6, 'Sundara Kanda, Sarga 25, Verse 6', 'स्वप्नो ह्यद्य मया दृष्टो दारुणो रोमहर्षणः।
राक्षसानामभावाय भर्तुरस्या भवाय च॥', 'svapno hy adya mayā dṛṣṭo dāruṇo romaharṣaṇaḥ
rākṣasānām abhāvāya bhartur asyā bhavāya ca', null, 5025006),
('ramayana-5-25-7', 7, 'Sundara Kanda, Sarga 25, Verse 7', 'एवमुक्तास्त्रिजटया राक्षस्यः क्रोधमूर्छिताः।
सर्वा एवाब्रुवन्भीतास्त्रिजटां तामिदं वचः॥', 'evam uktās trijaṭayā rākṣasyaḥ krodhamūrchitāḥ
sarvā evābruvan bhītās trijaṭāṃ tām idaṃ vacaḥ', null, 5025007),
('ramayana-5-25-8', 8, 'Sundara Kanda, Sarga 25, Verse 8', 'कथयस्व त्वया दृष्टः स्वप्नेऽयं कीदृशो निशि॥', 'kathayasva tvayā dṛṣṭaḥ svapne ''yaṃ kīdṛśo niśi', null, 5025008),
('ramayana-5-25-9', 9, 'Sundara Kanda, Sarga 25, Verse 9', 'तासां श्रुत्वा तु वचनं राक्षसीनां मुखोद्गतम्।
उवाच वचनं काले त्रिजटास्वप्नसंश्रितम्॥', 'tāsāṃ śrutvā tu vacanaṃ rākṣasīnāṃ mukhodgatam
uvāca vacanaṃ kāle trijaṭāsvapnasaṃśritam', null, 5025009),
('ramayana-5-25-10', 10, 'Sundara Kanda, Sarga 25, Verse 10', 'गजदन्तमयीं दिव्यां शिबिकामन्तरिक्षगाम्।
युक्तां वाजिसहस्रेण स्वयमास्थाय राघवः॥', 'gajadantamayīṃ divyāṃ śibikām antarikṣagām
yuktāṃ vājisahasreṇa svayam āsthāya rāghavaḥ', null, 5025010),
('ramayana-5-25-11', 11, 'Sundara Kanda, Sarga 25, Verse 11', 'स्वप्ने चाद्य मया दृष्टा सीता शुक्लाम्बरावृता।
सागरेण परिक्षिप्तं श्वेतपर्वतमास्थिता।
रामेण संगता सीता भास्करेण प्रभा यथा॥', 'svapne cādya mayā dṛṣṭā sītā śuklāmbarāvṛtā
sāgareṇa parikṣiptaṃ śvetaparvatam āsthitā
rāmeṇa saṃgatā sītā bhāskareṇa prabhā yathā', null, 5025011),
('ramayana-5-25-12', 12, 'Sundara Kanda, Sarga 25, Verse 12', 'राघवश्च मया दृष्टश्चतुर्दन्तं महागजम्।
आरूढः शैलसंकाशं चचार सहलक्ष्मणः॥', 'rāghavaś ca mayā dṛṣṭaś caturdantaṃ mahāgajam
ārūḍhaḥ śailasaṃkāśaṃ cacāra sahalakṣmaṇaḥ', null, 5025012),
('ramayana-5-25-13', 13, 'Sundara Kanda, Sarga 25, Verse 13', 'ततस्तौ नरशार्दूलौ दीप्यमानौ स्वतेजसा।
शुक्लमाल्याम्बरधरौ जानकीं पर्युपस्थितौ॥', 'tatas tau naraśārdūlau dīpyamānau svatejasā
śuklamālyāmbaradharau jānakīṃ paryupasthitau', null, 5025013),
('ramayana-5-25-14', 14, 'Sundara Kanda, Sarga 25, Verse 14', 'ततस्तस्य नगस्याग्रे आकाशस्थस्य दन्तिनः।
भर्त्रा परिगृहीतस्य जानकी स्कन्धमाश्रिता॥', 'tatas tasya nagasyāgre ākāśasthasya dantinaḥ
bhartrā parigṛhītasya jānakī skandham āśritā', null, 5025014),
('ramayana-5-25-15', 15, 'Sundara Kanda, Sarga 25, Verse 15', 'भर्तुरङ्कात्समुत्पत्य ततः कमललोचना।
चन्द्रसूर्यौ मया दृष्टा पाणिभ्यां परिमार्जती॥', 'bhartur aṅkāt samutpatya tataḥ kamalalocanā
candrasūryau mayā dṛṣṭā pāṇibhyāṃ parimārjatī', null, 5025015),
('ramayana-5-25-16', 16, 'Sundara Kanda, Sarga 25, Verse 16', 'ततस्ताभ्यां कुमाराभ्यामास्थितः स गजोत्तमः।
सीतया च विशालाक्ष्या लङ्काया उपरि स्थितः॥', 'tatas tābhyāṃ kumārābhyām āsthitaḥ sa gajottamaḥ
sītayā ca viśālākṣyā laṅkāyā upari sthitaḥ', null, 5025016),
('ramayana-5-25-17', 17, 'Sundara Kanda, Sarga 25, Verse 17', 'पाण्डुरर्षभयुक्तेन रथेनाष्टयुजा स्वयम्।
शुक्लमाल्याम्बरधरो लक्ष्मणेन समागतः।
लक्ष्मणेन सह भ्रात्रा सीतया सह भार्यया॥', 'pāṇḍurarṣabhayuktena rathenāṣṭayujā svayam
śuklamālyāmbaradharo lakṣmaṇena samāgataḥ
lakṣmaṇena saha bhrātrā sītayā saha bhāryayā', null, 5025017),
('ramayana-5-25-18', 18, 'Sundara Kanda, Sarga 25, Verse 18', 'विमानात्पुष्पकादद्य रावणः पतितो भुवि।
कृष्यपाणः स्त्रिया दृष्टो मुण्डः कृष्णाम्बरः पुनः॥', 'vimānāt puṣpakād adya rāvaṇaḥ patito bhuvi
kṛṣyapāṇaḥ striyā dṛṣṭo muṇḍaḥ kṛṣṇāmbaraḥ punaḥ', null, 5025018),
('ramayana-5-25-19', 19, 'Sundara Kanda, Sarga 25, Verse 19', 'रथेन खरयुक्तेन रक्तमाल्यानुलेपनः।
प्रयातो दक्षिणामाशां प्रविष्टः कर्दमं ह्रदम्॥', 'rathena kharayuktena raktamālyānulepanaḥ
prayāto dakṣiṇām āśāṃ praviṣṭaḥ kardamaṃ hradam', null, 5025019),
('ramayana-5-25-20', 20, 'Sundara Kanda, Sarga 25, Verse 20', 'कण्ठे बद्ध्वा दशग्रीवं प्रमदा रक्तवासिनी।
काली कर्दमलिप्ताङ्गी दिशं याम्यां प्रकर्षति॥', 'kaṇṭhe baddhvā daśagrīvaṃ pramadā raktavāsinī
kālī kardamaliptāṅgī diśaṃ yāmyāṃ prakarṣati', null, 5025020),
('ramayana-5-25-21', 21, 'Sundara Kanda, Sarga 25, Verse 21', 'वराहेण दशग्रीवः शिंशुमारेण चेन्द्रजित्।
उष्ट्रेण कुम्भकर्णश्च प्रयातो दक्षिणां दिशम्॥', 'varāheṇa daśagrīvaḥ śiṃśumāreṇa cendrajit
uṣṭreṇa kumbhakarṇaś ca prayāto dakṣiṇāṃ diśam', null, 5025021),
('ramayana-5-25-22', 22, 'Sundara Kanda, Sarga 25, Verse 22', 'समाजश्च महान्वृत्तो गीतवादित्रनिःस्वनः।
पिबतां रक्तमाल्यानां रक्षसां रक्तवाससाम्॥', 'samājaś ca mahān vṛtto gītavāditraniḥsvanaḥ
pibatāṃ raktamālyānāṃ rakṣasāṃ raktavāsasām', null, 5025022),
('ramayana-5-25-23', 23, 'Sundara Kanda, Sarga 25, Verse 23', 'लङ्का चेयं पुरी रम्या सवाजिरथसंकुला।
सागरे पतिता दृष्टा भग्नगोपुरतोरणा॥', 'laṅkā ceyaṃ purī ramyā savājirathasaṃkulā
sāgare patitā dṛṣṭā bhagnagopuratoraṇā', null, 5025023),
('ramayana-5-25-24', 24, 'Sundara Kanda, Sarga 25, Verse 24', 'पीत्व तैलं प्रनृत्ताश्च प्रहसन्त्यो महास्वनाः।
लङ्कायां भस्मरूक्षायां सर्वा राक्षसयोषितः॥', 'pītva tailaṃ pranṛttāś ca prahasantyo mahāsvanāḥ
laṅkāyāṃ bhasmarūkṣāyāṃ sarvā rākṣasayoṣitaḥ', null, 5025024),
('ramayana-5-25-25', 25, 'Sundara Kanda, Sarga 25, Verse 25', 'कुम्भकर्णादयश्चेमे सर्वे राक्षसपुंगवाः।
रक्तं निवसनं गृह्य प्रविष्टा गोमयह्रदे॥', 'kumbhakarṇādayaś ceme sarve rākṣasapuṃgavāḥ
raktaṃ nivasanaṃ gṛhya praviṣṭā gomayahrade', null, 5025025),
('ramayana-5-25-26', 26, 'Sundara Kanda, Sarga 25, Verse 26', 'अपगच्छत नश्यध्वं सीतामाप्नोति राघवः।
घातयेत्परमामर्षी सर्वैः सार्धं हि राक्षसैः॥', 'apagacchata naśyadhvaṃ sītām āpnoti rāghavaḥ
ghātayet paramāmarṣī sarvaiḥ sārdhaṃ hi rākṣasaiḥ', null, 5025026),
('ramayana-5-25-27', 27, 'Sundara Kanda, Sarga 25, Verse 27', 'प्रियां बहुमतां भार्यां वनवासमनुव्रताम्।
भर्त्सितां तर्जितां वापि नानुमंस्यति राघवः॥', 'priyāṃ bahumatāṃ bhāryāṃ vanavāsam anuvratām
bhartsitāṃ tarjitāṃ vāpi nānumaṃsyati rāghavaḥ', null, 5025027),
('ramayana-5-25-28', 28, 'Sundara Kanda, Sarga 25, Verse 28', 'तदलं क्रूरवाक्यैर्वः सान्त्वमेवाभिधीयताम्।
अभियाचाम वैदेहीमेतद्धि मम रोचते॥', 'tad alaṃ krūravākyair vaḥ sāntvam evābhidhīyatām
abhiyācāma vaidehīm etad dhi mama rocate', null, 5025028),
('ramayana-5-25-29', 29, 'Sundara Kanda, Sarga 25, Verse 29', 'यस्या ह्येवं विधः स्वप्नो दुःखितायाः प्रदृश्यते।
सा दुःखैर्बहुभिर्मुक्ता प्रियं प्राप्नोत्यनुत्तमम्॥', 'yasyā hy evaṃ vidhaḥ svapno duḥkhitāyāḥ pradṛśyate
sā duḥkhair bahubhir muktā priyaṃ prāpnoty anuttamam', null, 5025029),
('ramayana-5-25-30', 30, 'Sundara Kanda, Sarga 25, Verse 30', 'भर्त्सितामपि याचध्वं राक्षस्यः किं विवक्षया।
राघवाद्धि भयं घोरं राक्षसानामुपस्थितम्॥', 'bhartsitām api yācadhvaṃ rākṣasyaḥ kiṃ vivakṣayā
rāghavād dhi bhayaṃ ghoraṃ rākṣasānām upasthitam', null, 5025030),
('ramayana-5-25-31', 31, 'Sundara Kanda, Sarga 25, Verse 31', 'प्रणिपात प्रसन्ना हि मैथिली जनकात्मजा।
अलमेषा परित्रातुं राक्षस्यो महतो भयात्॥', 'praṇipāta prasannā hi maithilī janakātmajā
alam eṣā paritrātuṃ rākṣasyo mahato bhayāt', null, 5025031),
('ramayana-5-25-32', 32, 'Sundara Kanda, Sarga 25, Verse 32', 'अपि चास्या विशालाक्ष्या न किं चिदुपलक्षये।
विरुद्धमपि चाङ्गेषु सुसूक्ष्ममपि लक्ष्मणम्॥', 'api cāsyā viśālākṣyā na kiṃ cid upalakṣaye
viruddham api cāṅgeṣu susūkṣmam api lakṣmaṇam', null, 5025032),
('ramayana-5-25-33', 33, 'Sundara Kanda, Sarga 25, Verse 33', 'छाया वैगुण्य मात्रं तु शङ्के दुःखमुपस्थितम्।
अदुःखार्हामिमां देवीं वैहायसमुपस्थिताम्॥', 'chāyā vaiguṇya mātraṃ tu śaṅke duḥkham upasthitam
aduḥkhārhām imāṃ devīṃ vaihāyasam upasthitām', null, 5025033),
('ramayana-5-25-34', 34, 'Sundara Kanda, Sarga 25, Verse 34', 'अर्थसिद्धिं तु वैदेह्याः पश्याम्यहमुपस्थिताम्।
राक्षसेन्द्रविनाशं च विजयं राघवस्य च॥', 'arthasiddhiṃ tu vaidehyāḥ paśyāmy aham upasthitām
rākṣasendravināśaṃ ca vijayaṃ rāghavasya ca', null, 5025034),
('ramayana-5-25-35', 35, 'Sundara Kanda, Sarga 25, Verse 35', 'निमित्तभूतमेतत्तु श्रोतुमस्या महत्प्रियम्।
दृश्यते च स्फुरच्चक्षुः पद्मपत्रमिवायतम्॥', 'nimittabhūtam etat tu śrotum asyā mahat priyam
dṛśyate ca sphurac cakṣuḥ padmapatram ivāyatam', null, 5025035),
('ramayana-5-25-36', 36, 'Sundara Kanda, Sarga 25, Verse 36', 'ईषच्च हृषितो वास्या दक्षिणाया ह्यदक्षिणः।
अकस्मादेव वैदेह्या बाहुरेकः प्रकम्पते॥', 'īṣac ca hṛṣito vāsyā dakṣiṇāyā hy adakṣiṇaḥ
akasmād eva vaidehyā bāhur ekaḥ prakampate', null, 5025036),
('ramayana-5-25-37', 37, 'Sundara Kanda, Sarga 25, Verse 37', 'करेणुहस्तप्रतिमः सव्यश्चोरुरनुत्तमः।
वेपन्सूचयतीवास्या राघवं पुरतः स्थितम्॥', 'kareṇuhastapratimaḥ savyaś corur anuttamaḥ
vepan sūcayatīvāsyā rāghavaṃ purataḥ sthitam', null, 5025037),
('ramayana-5-25-38', 38, 'Sundara Kanda, Sarga 25, Verse 38', 'पक्षी च शाखा निलयं प्रविष्टः पुनः पुनश्चोत्तमसान्त्ववादी।
सुखागतां वाचमुदीरयाणः पुनः पुनश्चोदयतीव हृष्टः॥', 'pakṣī ca śākhā nilayaṃ praviṣṭaḥ punaḥ punaś cottamasāntvavādī
sukhāgatāṃ vācam udīrayāṇaḥ punaḥ punaś codayatīva hṛṣṭaḥ', null, 5025038)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 26 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-26-1', 1, 'Sundara Kanda, Sarga 26, Verse 1', 'सा राक्षसेन्द्रस्य वचो निशम्य तद्रावणस्याप्रियमप्रियार्ता।
सीता वितत्रास यथा वनान्ते सिंहाभिपन्ना गजराजकन्या॥', 'sā rākṣasendrasya vaco niśamya tad rāvaṇasyāpriyam apriyārtā
sītā vitatrāsa yathā vanānte siṃhābhipannā gajarājakanyā', null, 5026001),
('ramayana-5-26-2', 2, 'Sundara Kanda, Sarga 26, Verse 2', 'सा राक्षसी मध्यगता च भीरुर्वाग्भिर्भृशं रावणतर्जिता च।
कान्तारमध्ये विजने विसृष्टा बालेव कन्या विललाप सीता॥', 'sā rākṣasī madhyagatā ca bhīrur vāgbhir bhṛśaṃ rāvaṇatarjitā ca
kāntāramadhye vijane visṛṣṭā bāleva kanyā vilalāpa sītā', null, 5026002),
('ramayana-5-26-3', 3, 'Sundara Kanda, Sarga 26, Verse 3', 'सत्यं बतेदं प्रवदन्ति लोके नाकालमृत्युर्भवतीति सन्तः।
यत्राहमेवं परिभर्त्स्यमाना जीवामि किं चित्क्षणमप्यपुण्या॥', 'satyaṃ batedaṃ pravadanti loke nākālamṛtyur bhavatīti santaḥ
yatrāham evaṃ paribhartsyamānā jīvāmi kiṃ cit kṣaṇam apy apuṇyā', null, 5026003),
('ramayana-5-26-4', 4, 'Sundara Kanda, Sarga 26, Verse 4', 'सुखाद्विहीनं बहुदुःखपूर्णमिदं तु नूनं हृदयं स्थिरं मे।
विदीर्यते यन्न सहस्रधाद्य वज्राहतं शृङ्गमिवाचलस्य॥', 'sukhād vihīnaṃ bahuduḥkhapūrṇam idaṃ tu nūnaṃ hṛdayaṃ sthiraṃ me
vidīryate yan na sahasradhādya vajrāhataṃ śṛṅgam ivācalasya', null, 5026004),
('ramayana-5-26-5', 5, 'Sundara Kanda, Sarga 26, Verse 5', 'नैवास्ति नूनं मम दोषमत्र वध्याहमस्याप्रियदर्शनस्य।
भावं न चास्याहमनुप्रदातुमलं द्विजो मन्त्रमिवाद्विजाय॥', 'naivāsti nūnaṃ mama doṣam atra vadhyāham asyāpriyadarśanasya
bhāvaṃ na cāsyāham anupradātum alaṃ dvijo mantram ivādvijāya', null, 5026005),
('ramayana-5-26-6', 6, 'Sundara Kanda, Sarga 26, Verse 6', 'नूनं ममाङ्गान्यचिरादनार्यः शस्त्रैः शितैश्छेत्स्यति राक्षसेन्द्रः।
तस्मिन्ननागच्छति लोकनाथे गर्भस्थजन्तोरिव शल्यकृन्तः॥', 'nūnaṃ mamāṅgāny acirād anāryaḥ śastraiḥ śitaiś chetsyati rākṣasendraḥ
tasminn anāgacchati lokanāthe garbhasthajantor iva śalyakṛntaḥ', null, 5026006),
('ramayana-5-26-7', 7, 'Sundara Kanda, Sarga 26, Verse 7', 'दुःखं बतेदं मम दुःखिताया मासौ चिरायाभिगमिष्यतो द्वौ।
बद्धस्य वध्यस्य यथा निशान्ते राजापराधादिव तस्करस्य॥', 'duḥkhaṃ batedaṃ mama duḥkhitāyā māsau cirāyābhigamiṣyato dvau
baddhasya vadhyasya yathā niśānte rājāparādhād iva taskarasya', null, 5026007),
('ramayana-5-26-8', 8, 'Sundara Kanda, Sarga 26, Verse 8', 'हा राम हा लक्ष्मण हा सुमित्रे हा राम मातः सह मे जनन्या।
एषा विपद्याम्यहमल्पभाग्या महार्णवे नौरिव मूढ वाता॥', 'hā rāma hā lakṣmaṇa hā sumitre hā rāma mātaḥ saha me jananyā
eṣā vipadyāmy aham alpabhāgyā mahārṇave naur iva mūḍha vātā', null, 5026008),
('ramayana-5-26-9', 9, 'Sundara Kanda, Sarga 26, Verse 9', 'तरस्विनौ धारयता मृगस्य सत्त्वेन रूपं मनुजेन्द्रपुत्रौ।
नूनं विशस्तौ मम कारणात्तौ सिंहर्षभौ द्वाविव वैद्युतेन॥', 'tarasvinau dhārayatā mṛgasya sattvena rūpaṃ manujendraputrau
nūnaṃ viśastau mama kāraṇāt tau siṃharṣabhau dvāv iva vaidyutena', null, 5026009),
('ramayana-5-26-10', 10, 'Sundara Kanda, Sarga 26, Verse 10', 'नूनं स कालो मृगरूपधारी मामल्पभाग्यां लुलुभे तदानीम्।
यत्रार्यपुत्रं विससर्ज मूढा रामानुजं लक्ष्मणपूर्वकं च॥', 'nūnaṃ sa kālo mṛgarūpadhārī mām alpabhāgyāṃ lulubhe tadānīm
yatrāryaputraṃ visasarja mūḍhā rāmānujaṃ lakṣmaṇapūrvakaṃ ca', null, 5026010),
('ramayana-5-26-11', 11, 'Sundara Kanda, Sarga 26, Verse 11', 'हा राम सत्यव्रत दीर्घवाहो हा पूर्णचन्द्रप्रतिमानवक्त्र।
हा जीवलोकस्य हितः प्रियश्च वध्यां न मां वेत्सि हि राक्षसानाम्॥', 'hā rāma satyavrata dīrghavāho hā pūrṇacandrapratimānavaktra
hā jīvalokasya hitaḥ priyaś ca vadhyāṃ na māṃ vetsi hi rākṣasānām', null, 5026011),
('ramayana-5-26-12', 12, 'Sundara Kanda, Sarga 26, Verse 12', 'अनन्यदेवत्वमियं क्षमा च भूमौ च शय्या नियमश्च धर्मे।
पतिव्रतात्वं विफलं ममेदं कृतं कृतघ्नेष्विव मानुषाणाम्॥', 'ananyadevatvam iyaṃ kṣamā ca bhūmau ca śayyā niyamaś ca dharme
pativratātvaṃ viphalaṃ mamedaṃ kṛtaṃ kṛtaghneṣv iva mānuṣāṇām', null, 5026012),
('ramayana-5-26-13', 13, 'Sundara Kanda, Sarga 26, Verse 13', 'मोघो हि धर्मश्चरितो ममायं तथैकपत्नीत्वमिदं निरर्थम्।
या त्वां न पश्यामि कृशा विवर्णा हीना त्वया संगमने निराशा॥', 'mogho hi dharmaś carito mamāyaṃ tathaikapatnītvam idaṃ nirartham
yā tvāṃ na paśyāmi kṛśā vivarṇā hīnā tvayā saṃgamane nirāśā', null, 5026013),
('ramayana-5-26-14', 14, 'Sundara Kanda, Sarga 26, Verse 14', 'पितुर्निर्देशं नियमेन कृत्वा वनान्निवृत्तश्चरितव्रतश्च।
स्त्रीभिस्तु मन्ये विपुलेक्षणाभिः संरंस्यसे वीतभयः कृतार्थः॥', 'pitur nirdeśaṃ niyamena kṛtvā vanān nivṛttaś caritavrataś ca
strībhis tu manye vipulekṣaṇābhiḥ saṃraṃsyase vītabhayaḥ kṛtārthaḥ', null, 5026014),
('ramayana-5-26-15', 15, 'Sundara Kanda, Sarga 26, Verse 15', 'अहं तु राम त्वयि जातकामा चिरं विनाशाय निबद्धभावा।
मोघं चरित्वाथ तपोव्रतं च त्यक्ष्यामि धिग्जीवितमल्पभाग्या॥', 'ahaṃ tu rāma tvayi jātakāmā ciraṃ vināśāya nibaddhabhāvā
moghaṃ caritvātha tapovrataṃ ca tyakṣyāmi dhig jīvitam alpabhāgyā', null, 5026015),
('ramayana-5-26-16', 16, 'Sundara Kanda, Sarga 26, Verse 16', 'सा जीवितं क्षिप्रमहं त्यजेयं विषेण शस्त्रेण शितेन वापि।
विषस्य दाता न तु मेऽस्ति कश्चिच्छस्त्रस्य वा वेश्मनि राक्षसस्य॥', 'sā jīvitaṃ kṣipram ahaṃ tyajeyaṃ viṣeṇa śastreṇa śitena vāpi
viṣasya dātā na tu me ''sti kaś cic chastrasya vā veśmani rākṣasasya', null, 5026016),
('ramayana-5-26-17', 17, 'Sundara Kanda, Sarga 26, Verse 17', 'शोकाभितप्ता बहुधा विचिन्त्य सीताथ वेण्युद्ग्रथनं गृहीत्वा।
उद्बध्य वेण्युद्ग्रथनेन शीघ्रमहं गमिष्यामि यमस्य मूलम्॥', 'śokābhitaptā bahudhā vicintya sītātha veṇyudgrathanaṃ gṛhītvā
udbadhya veṇyudgrathanena śīghram ahaṃ gamiṣyāmi yamasya mūlam', null, 5026017),
('ramayana-5-26-18', 18, 'Sundara Kanda, Sarga 26, Verse 18', 'इतीव सीता बहुधा विलप्य सर्वात्मना राममनुस्मरन्ती।
प्रवेपमाना परिशुष्कवक्त्रा नगोत्तमं पुष्पितमाससाद॥', 'itīva sītā bahudhā vilapya sarvātmanā rāmam anusmarantī
pravepamānā pariśuṣkavaktrā nagottamaṃ puṣpitam āsasāda', null, 5026018),
('ramayana-5-26-19', 19, 'Sundara Kanda, Sarga 26, Verse 19', 'उपस्थिता सा मृदुर्सर्वगात्री शाखां गृहीत्वाथ नगस्य तस्य।
तस्यास्तु रामं प्रविचिन्तयन्त्या रामानुजं स्वं च कुलं शुभाङ्ग्याः॥', 'upasthitā sā mṛdur sarvagātrī śākhāṃ gṛhītvātha nagasya tasya
tasyās tu rāmaṃ pravicintayantyā rāmānujaṃ svaṃ ca kulaṃ śubhāṅgyāḥ', null, 5026019),
('ramayana-5-26-20', 20, 'Sundara Kanda, Sarga 26, Verse 20', 'शोकानिमित्तानि तदा बहूनि धैर्यार्जितानि प्रवराणि लोके।
प्रादुर्निमित्तानि तदा बभूवुः पुरापि सिद्धान्युपलक्षितानि॥', 'śokānimittāni tadā bahūni dhairyārjitāni pravarāṇi loke
prādurnimittāni tadā babhūvuḥ purāpi siddhāny upalakṣitāni', null, 5026020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 27 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-27-1', 1, 'Sundara Kanda, Sarga 27, Verse 1', 'तथागतां तां व्यथितामनिन्दितां व्यपेतहर्षां परिदीनमानसाम्।
शुभां निमित्तानि शुभानि भेजिरे नरं श्रिया जुष्टमिवोपजीविनः॥', 'tathāgatāṃ tāṃ vyathitām aninditāṃ vyapetaharṣāṃ paridīnamānasām
śubhāṃ nimittāni śubhāni bhejire naraṃ śriyā juṣṭam ivopajīvinaḥ', null, 5027001),
('ramayana-5-27-2', 2, 'Sundara Kanda, Sarga 27, Verse 2', 'तस्याः शुभं वाममरालपक्ष्म राजीवृतं कृष्णविशालशुक्लम्।
प्रास्पन्दतैकं नयनं सुकेश्या मीनाहतं पद्ममिवाभिताम्रम्॥', 'tasyāḥ śubhaṃ vāmam arālapakṣma rājīvṛtaṃ kṛṣṇaviśālaśuklam
prāspandataikaṃ nayanaṃ sukeśyā mīnāhataṃ padmam ivābhitāmram', null, 5027002),
('ramayana-5-27-3', 3, 'Sundara Kanda, Sarga 27, Verse 3', 'भुजश्च चार्वञ्चितपीनवृत्तः परार्ध्य कालागुरुचन्दनार्हः।
अनुत्तमेनाध्युषितः प्रियेण चिरेण वामः समवेपताशु॥', 'bhujaś ca cārvañcitapīnavṛttaḥ parārdhya kālāgurucandanārhaḥ
anuttamenādhyuṣitaḥ priyeṇa cireṇa vāmaḥ samavepatāśu', null, 5027003),
('ramayana-5-27-4', 4, 'Sundara Kanda, Sarga 27, Verse 4', 'गजेन्द्रहस्तप्रतिमश्च पीनस्तयोर्द्वयोः संहतयोः सुजातः।
प्रस्पन्दमानः पुनरूरुरस्या रामं पुरस्तात्स्थितमाचचक्षे॥', 'gajendrahastapratimaś ca pīnas tayor dvayoḥ saṃhatayoḥ sujātaḥ
praspandamānaḥ punar ūrur asyā rāmaṃ purastāt sthitam ācacakṣe', null, 5027004),
('ramayana-5-27-5', 5, 'Sundara Kanda, Sarga 27, Verse 5', 'शुभं पुनर्हेमसमानवर्णमीषद्रजोध्वस्तमिवामलाक्ष्याः।
वासः स्थितायाः शिखराग्रदन्त्याः किं चित्परिस्रंसत चारुगात्र्याः॥', 'śubhaṃ punar hemasamānavarṇam īṣadrajodhvastam ivāmalākṣyāḥ
vāsaḥ sthitāyāḥ śikharāgradantyāḥ kiṃ cit parisraṃsata cārugātryāḥ', null, 5027005),
('ramayana-5-27-6', 6, 'Sundara Kanda, Sarga 27, Verse 6', 'एतैर्निमित्तैरपरैश्च सुभ्रूः संबोधिता प्रागपि साधुसिद्धैः।
वातातपक्लान्तमिव प्रनष्टं वर्षेण बीजं प्रतिसंजहर्ष॥', 'etair nimittair aparaiś ca subhrūḥ saṃbodhitā prāg api sādhusiddhaiḥ
vātātapaklāntam iva pranaṣṭaṃ varṣeṇa bījaṃ pratisaṃjaharṣa', null, 5027006),
('ramayana-5-27-7', 7, 'Sundara Kanda, Sarga 27, Verse 7', 'तस्याः पुनर्बिम्बफलोपमौष्ठं स्वक्षिभ्रुकेशान्तमरालपक्ष्म।
वक्त्रं बभासे सितशुक्लदंष्ट्रं राहोर्मुखाच्चन्द्र इव प्रमुक्तः॥', 'tasyāḥ punar bimbaphalopamauṣṭhaṃ svakṣibhrukeśāntam arālapakṣma
vaktraṃ babhāse sitaśukladaṃṣṭraṃ rāhor mukhāc candra iva pramuktaḥ', null, 5027007),
('ramayana-5-27-8', 8, 'Sundara Kanda, Sarga 27, Verse 8', 'सा वीतशोका व्यपनीततन्द्री शान्तज्वरा हर्षविबुद्धसत्त्वा।
अशोभतार्या वदनेन शुक्ले शीतान्शुना रात्रिरिवोदितेन॥', 'sā vītaśokā vyapanītatandrī śāntajvarā harṣavibuddhasattvā
aśobhatāryā vadanena śukle śītānśunā rātrir ivoditena', null, 5027008)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 28 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-28-1', 1, 'Sundara Kanda, Sarga 28, Verse 1', 'हनुमानपि विक्रान्तः सर्वं शुश्राव तत्त्वतः।
सीतायास्त्रिजटायाश्च राक्षसीनां च तर्जनम्॥', 'hanumān api vikrāntaḥ sarvaṃ śuśrāva tattvataḥ
sītāyās trijaṭāyāś ca rākṣasīnāṃ ca tarjanam', null, 5028001),
('ramayana-5-28-2', 2, 'Sundara Kanda, Sarga 28, Verse 2', 'अवेक्षमाणस्तां देवीं देवतामिव नन्दने।
ततो बहुविधां चिन्तां चिन्तयामास वानरः॥', 'avekṣamāṇas tāṃ devīṃ devatām iva nandane
tato bahuvidhāṃ cintāṃ cintayām āsa vānaraḥ', null, 5028002),
('ramayana-5-28-3', 3, 'Sundara Kanda, Sarga 28, Verse 3', 'यां कपीनां सहस्राणि सुबहून्ययुतानि च।
दिक्षु सर्वासु मार्गन्ते सेयमासादिता मया॥', 'yāṃ kapīnāṃ sahasrāṇi subahūny ayutāni ca
dikṣu sarvāsu mārgante seyam āsāditā mayā', null, 5028003),
('ramayana-5-28-4', 4, 'Sundara Kanda, Sarga 28, Verse 4', 'चारेण तु सुयुक्तेन शत्रोः शक्तिमवेक्षिता।
गूढेन चरता तावदवेक्षितमिदं मया॥', 'cāreṇa tu suyuktena śatroḥ śaktim avekṣitā
gūḍhena caratā tāvad avekṣitam idaṃ mayā', null, 5028004),
('ramayana-5-28-5', 5, 'Sundara Kanda, Sarga 28, Verse 5', 'राक्षसानां विशेषश्च पुरी चेयमवेक्षिता।
राक्षसाधिपतेरस्य प्रभावो रावणस्य च॥', 'rākṣasānāṃ viśeṣaś ca purī ceyam avekṣitā
rākṣasādhipater asya prabhāvo rāvaṇasya ca', null, 5028005),
('ramayana-5-28-6', 6, 'Sundara Kanda, Sarga 28, Verse 6', 'युक्तं तस्याप्रमेयस्य सर्वसत्त्वदयावतः।
समाश्वासयितुं भार्यां पतिदर्शनकाङ्क्षिणीम्॥', 'yuktaṃ tasyāprameyasya sarvasattvadayāvataḥ
samāśvāsayituṃ bhāryāṃ patidarśanakāṅkṣiṇīm', null, 5028006),
('ramayana-5-28-7', 7, 'Sundara Kanda, Sarga 28, Verse 7', 'अहमाश्वासयाम्येनां पूर्णचन्द्रनिभाननाम्।
अदृष्टदुःखां दुःखस्य न ह्यन्तमधिगच्छतीम्॥', 'aham āśvāsayāmy enāṃ pūrṇacandranibhānanām
adṛṣṭaduḥkhāṃ duḥkhasya na hy antam adhigacchatīm', null, 5028007),
('ramayana-5-28-8', 8, 'Sundara Kanda, Sarga 28, Verse 8', 'यदि ह्यहमिमां देवीं शोकोपहतचेतनाम्।
अनाश्वास्य गमिष्यामि दोषवद्गमनं भवेत्॥', 'yadi hy aham imāṃ devīṃ śokopahatacetanām
anāśvāsya gamiṣyāmi doṣavad gamanaṃ bhavet', null, 5028008),
('ramayana-5-28-9', 9, 'Sundara Kanda, Sarga 28, Verse 9', 'गते हि मयि तत्रेयं राजपुत्री यशस्विनी।
परित्राणमविन्दन्ती जानकी जीवितं त्यजेत्॥', 'gate hi mayi tatreyaṃ rājaputrī yaśasvinī
paritrāṇam avindantī jānakī jīvitaṃ tyajet', null, 5028009),
('ramayana-5-28-10', 10, 'Sundara Kanda, Sarga 28, Verse 10', 'मया च स महाबाहुः पूर्णचन्द्रनिभाननः।
समाश्वासयितुं न्याय्यः सीतादर्शनलालसः॥', 'mayā ca sa mahābāhuḥ pūrṇacandranibhānanaḥ
samāśvāsayituṃ nyāyyaḥ sītādarśanalālasaḥ', null, 5028010),
('ramayana-5-28-11', 11, 'Sundara Kanda, Sarga 28, Verse 11', 'निशाचरीणां प्रत्यक्षमक्षमं चाभिभाषणम्।
कथं नु खलु कर्तव्यमिदं कृच्छ्र गतो ह्यहम्॥', 'niśācarīṇāṃ pratyakṣam akṣamaṃ cābhibhāṣaṇam
kathaṃ nu khalu kartavyam idaṃ kṛcchra gato hy aham', null, 5028011),
('ramayana-5-28-12', 12, 'Sundara Kanda, Sarga 28, Verse 12', 'अनेन रात्रिशेषेण यदि नाश्वास्यते मया।
सर्वथा नास्ति संदेहः परित्यक्ष्यति जीवितम्॥', 'anena rātriśeṣeṇa yadi nāśvāsyate mayā
sarvathā nāsti saṃdehaḥ parityakṣyati jīvitam', null, 5028012),
('ramayana-5-28-13', 13, 'Sundara Kanda, Sarga 28, Verse 13', 'रामश्च यदि पृच्छेन्मां किं मां सीताब्रवीद्वचः।
किमहं तं प्रतिब्रूयामसंभाष्य सुमध्यमाम्॥', 'rāmaś ca yadi pṛcchen māṃ kiṃ māṃ sītābravīd vacaḥ
kim ahaṃ taṃ pratibrūyām asaṃbhāṣya sumadhyamām', null, 5028013),
('ramayana-5-28-14', 14, 'Sundara Kanda, Sarga 28, Verse 14', 'सीतासंदेशरहितं मामितस्त्वरया गतम्।
निर्दहेदपि काकुत्स्थः क्रुद्धस्तीव्रेण चक्षुषा॥', 'sītāsaṃdeśarahitaṃ mām itas tvarayā gatam
nirdahed api kākutsthaḥ kruddhas tīvreṇa cakṣuṣā', null, 5028014),
('ramayana-5-28-15', 15, 'Sundara Kanda, Sarga 28, Verse 15', 'यदि चेद्योजयिष्यामि भर्तारं रामकारणात्।
व्यर्थमागमनं तस्य ससैन्यस्य भविष्यति॥', 'yadi ced yojayiṣyāmi bhartāraṃ rāmakāraṇāt
vyartham āgamanaṃ tasya sasainyasya bhaviṣyati', null, 5028015),
('ramayana-5-28-16', 16, 'Sundara Kanda, Sarga 28, Verse 16', 'अन्तरं त्वहमासाद्य राक्षसीनामिह स्थितः।
शनैराश्वासयिष्यामि संतापबहुलामिमाम्॥', 'antaraṃ tv aham āsādya rākṣasīnām iha sthitaḥ
śanair āśvāsayiṣyāmi saṃtāpabahulām imām', null, 5028016),
('ramayana-5-28-17', 17, 'Sundara Kanda, Sarga 28, Verse 17', 'अहं ह्यतितनुश्चैव वनरश्च विशेषतः।
वाचं चोदाहरिष्यामि मानुषीमिह संस्कृताम्॥', 'ahaṃ hy atitanuś caiva vanaraś ca viśeṣataḥ
vācaṃ codāhariṣyāmi mānuṣīm iha saṃskṛtām', null, 5028017),
('ramayana-5-28-18', 18, 'Sundara Kanda, Sarga 28, Verse 18', 'यदि वाचं प्रदास्यामि द्विजातिरिव संस्कृताम्।
रावणं मन्यमाना मां सीता भीता भविष्यति॥', 'yadi vācaṃ pradāsyāmi dvijātir iva saṃskṛtām
rāvaṇaṃ manyamānā māṃ sītā bhītā bhaviṣyati', null, 5028018),
('ramayana-5-28-19', 19, 'Sundara Kanda, Sarga 28, Verse 19', 'अवश्यमेव वक्तव्यं मानुषं वाक्यमर्थवत्।
मया सान्त्वयितुं शक्या नान्यथेयमनिन्दिता॥', 'avaśyam eva vaktavyaṃ mānuṣaṃ vākyam arthavat
mayā sāntvayituṃ śakyā nānyatheyam aninditā', null, 5028019),
('ramayana-5-28-20', 20, 'Sundara Kanda, Sarga 28, Verse 20', 'सेयमालोक्य मे रूपं जानकी भाषितं तथा।
रक्षोभिस्त्रासिता पूर्वं भूयस्त्रासं गमिष्यति॥', 'seyam ālokya me rūpaṃ jānakī bhāṣitaṃ tathā
rakṣobhis trāsitā pūrvaṃ bhūyas trāsaṃ gamiṣyati', null, 5028020),
('ramayana-5-28-21', 21, 'Sundara Kanda, Sarga 28, Verse 21', 'ततो जातपरित्रासा शब्दं कुर्यान्मनस्विनी।
जानमाना विशालाक्षी रावणं कामरूपिणम्॥', 'tato jātaparitrāsā śabdaṃ kuryān manasvinī
jānamānā viśālākṣī rāvaṇaṃ kāmarūpiṇam', null, 5028021),
('ramayana-5-28-22', 22, 'Sundara Kanda, Sarga 28, Verse 22', 'सीतया च कृते शब्दे सहसा राक्षसीगणः।
नानाप्रहरणो घोरः समेयादन्तकोपमः॥', 'sītayā ca kṛte śabde sahasā rākṣasīgaṇaḥ
nānāpraharaṇo ghoraḥ sameyād antakopamaḥ', null, 5028022),
('ramayana-5-28-23', 23, 'Sundara Kanda, Sarga 28, Verse 23', 'ततो मां संपरिक्षिप्य सर्वतो विकृताननाः।
वधे च ग्रहणे चैव कुर्युर्यत्नं यथाबलम्॥', 'tato māṃ saṃparikṣipya sarvato vikṛtānanāḥ
vadhe ca grahaṇe caiva kuryur yatnaṃ yathābalam', null, 5028023),
('ramayana-5-28-24', 24, 'Sundara Kanda, Sarga 28, Verse 24', 'तं मां शाखाः प्रशाखाश्च स्कन्धांश्चोत्तमशाखिनाम्।
दृष्ट्वा विपरिधावन्तं भवेयुर्भयशङ्किताः॥', 'taṃ māṃ śākhāḥ praśākhāś ca skandhāṃś cottamaśākhinām
dṛṣṭvā viparidhāvantaṃ bhaveyur bhayaśaṅkitāḥ', null, 5028024),
('ramayana-5-28-25', 25, 'Sundara Kanda, Sarga 28, Verse 25', 'मम रूपं च संप्रेक्ष्य वनं विचरतो महत्।
राक्षस्यो भयवित्रस्ता भवेयुर्विकृताननाः॥', 'mama rūpaṃ ca saṃprekṣya vanaṃ vicarato mahat
rākṣasyo bhayavitrastā bhaveyur vikṛtānanāḥ', null, 5028025),
('ramayana-5-28-26', 26, 'Sundara Kanda, Sarga 28, Verse 26', 'ततः कुर्युः समाह्वानं राक्षस्यो रक्षसामपि।
राक्षसेन्द्रनियुक्तानां राक्षसेन्द्रनिवेशने॥', 'tataḥ kuryuḥ samāhvānaṃ rākṣasyo rakṣasām api
rākṣasendraniyuktānāṃ rākṣasendraniveśane', null, 5028026),
('ramayana-5-28-27', 27, 'Sundara Kanda, Sarga 28, Verse 27', 'ते शूलशरनिस्त्रिंश विविधायुधपाणयः।
आपतेयुर्विमर्देऽस्मिन्वेगेनोद्विग्नकारिणः॥', 'te śūlaśaranistriṃśa vividhāyudhapāṇayaḥ
āpateyur vimarde ''smin vegenodvignakāriṇaḥ', null, 5028027),
('ramayana-5-28-28', 28, 'Sundara Kanda, Sarga 28, Verse 28', 'संक्रुद्धस्तैस्तु परितो विधमन्रक्षसां बलम्।
शक्नुयं न तु संप्राप्तुं परं पारं महोदधेः॥', 'saṃkruddhas tais tu parito vidhaman rakṣasāṃ balam
śaknuyaṃ na tu saṃprāptuṃ paraṃ pāraṃ mahodadheḥ', null, 5028028),
('ramayana-5-28-29', 29, 'Sundara Kanda, Sarga 28, Verse 29', 'मां वा गृह्णीयुराप्लुत्य बहवः शीघ्रकारिणः।
स्यादियं चागृहीतार्था मम च ग्रहणं भवेत्॥', 'māṃ vā gṛhṇīyur āplutya bahavaḥ śīghrakāriṇaḥ
syād iyaṃ cāgṛhītārthā mama ca grahaṇaṃ bhavet', null, 5028029),
('ramayana-5-28-30', 30, 'Sundara Kanda, Sarga 28, Verse 30', 'हिंसाभिरुचयो हिंस्युरिमां वा जनकात्मजाम्।
विपन्नं स्यात्ततः कार्यं रामसुग्रीवयोरिदम्॥', 'hiṃsābhirucayo hiṃsyur imāṃ vā janakātmajām
vipannaṃ syāt tataḥ kāryaṃ rāmasugrīvayor idam', null, 5028030),
('ramayana-5-28-31', 31, 'Sundara Kanda, Sarga 28, Verse 31', 'उद्देशे नष्टमार्गेऽस्मिन्राक्षसैः परिवारिते।
सागरेण परिक्षिप्ते गुप्ते वसति जानकी॥', 'uddeśe naṣṭamārge ''smin rākṣasaiḥ parivārite
sāgareṇa parikṣipte gupte vasati jānakī', null, 5028031),
('ramayana-5-28-32', 32, 'Sundara Kanda, Sarga 28, Verse 32', 'विशस्ते वा गृहीते वा रक्षोभिर्मयि संयुगे।
नान्यं पश्यामि रामस्य सहायं कार्यसाधने॥', 'viśaste vā gṛhīte vā rakṣobhir mayi saṃyuge
nānyaṃ paśyāmi rāmasya sahāyaṃ kāryasādhane', null, 5028032),
('ramayana-5-28-33', 33, 'Sundara Kanda, Sarga 28, Verse 33', 'विमृशंश्च न पश्यामि यो हते मयि वानरः।
शतयोजनविस्तीर्णं लङ्घयेत महोदधिम्॥', 'vimṛśaṃś ca na paśyāmi yo hate mayi vānaraḥ
śatayojanavistīrṇaṃ laṅghayeta mahodadhim', null, 5028033),
('ramayana-5-28-34', 34, 'Sundara Kanda, Sarga 28, Verse 34', 'कामं हन्तुं समर्थोऽस्मि सहस्राण्यपि रक्षसाम्।
न तु शक्ष्यामि संप्राप्तुं परं पारं महोदधेः॥', 'kāmaṃ hantuṃ samartho ''smi sahasrāṇy api rakṣasām
na tu śakṣyāmi saṃprāptuṃ paraṃ pāraṃ mahodadheḥ', null, 5028034),
('ramayana-5-28-35', 35, 'Sundara Kanda, Sarga 28, Verse 35', 'असत्यानि च युद्धानि संशयो मे न रोचते।
कश्च निःसंशयं कार्यं कुर्यात्प्राज्ञः ससंशयम्॥', 'asatyāni ca yuddhāni saṃśayo me na rocate
kaś ca niḥsaṃśayaṃ kāryaṃ kuryāt prājñaḥ sasaṃśayam', null, 5028035),
('ramayana-5-28-36', 36, 'Sundara Kanda, Sarga 28, Verse 36', 'एष दोषो महान्हि स्यान्मम सीताभिभाषणे।
प्राणत्यागश्च वैदेह्या भवेदनभिभाषणे॥', 'eṣa doṣo mahān hi syān mama sītābhibhāṣaṇe
prāṇatyāgaś ca vaidehyā bhaved anabhibhāṣaṇe', null, 5028036),
('ramayana-5-28-37', 37, 'Sundara Kanda, Sarga 28, Verse 37', 'भूताश्चार्था विनश्यन्ति देशकालविरोधिताः।
विक्लवं दूतमासाद्य तमः सूर्योदये यथा॥', 'bhūtāś cārthā vinaśyanti deśakālavirodhitāḥ
viklavaṃ dūtam āsādya tamaḥ sūryodaye yathā', null, 5028037),
('ramayana-5-28-38', 38, 'Sundara Kanda, Sarga 28, Verse 38', 'अर्थानर्थान्तरे बुद्धिर्निश्चितापि न शोभते।
घातयन्ति हि कार्याणि दूताः पण्डितमानिनः॥', 'arthānarthāntare buddhir niścitāpi na śobhate
ghātayanti hi kāryāṇi dūtāḥ paṇḍitamāninaḥ', null, 5028038),
('ramayana-5-28-39', 39, 'Sundara Kanda, Sarga 28, Verse 39', 'न विनश्येत्कथं कार्यं वैक्लव्यं न कथं भवेत्।
लङ्घनं च समुद्रस्य कथं नु न वृथा भवेत्॥', 'na vinaśyet kathaṃ kāryaṃ vaiklavyaṃ na kathaṃ bhavet
laṅghanaṃ ca samudrasya kathaṃ nu na vṛthā bhavet', null, 5028039),
('ramayana-5-28-40', 40, 'Sundara Kanda, Sarga 28, Verse 40', 'कथं नु खलु वाक्यं मे शृणुयान्नोद्विजेत च।
इति संचिन्त्य हनुमांश्चकार मतिमान्मतिम्॥', 'kathaṃ nu khalu vākyaṃ me śṛṇuyān nodvijeta ca
iti saṃcintya hanumāṃś cakāra matimān matim', null, 5028040),
('ramayana-5-28-41', 41, 'Sundara Kanda, Sarga 28, Verse 41', 'राममक्लिष्टकर्माणं स्वबन्धुमनुकीर्तयन्।
नैनामुद्वेजयिष्यामि तद्बन्धुगतमानसाम्॥', 'rāmam akliṣṭakarmāṇaṃ svabandhum anukīrtayan
nainām udvejayiṣyāmi tad bandhugatamānasām', null, 5028041),
('ramayana-5-28-42', 42, 'Sundara Kanda, Sarga 28, Verse 42', 'इक्ष्वाकूणां वरिष्ठस्य रामस्य विदितात्मनः।
शुभानि धर्मयुक्तानि वचनानि समर्पयन्॥', 'ikṣvākūṇāṃ variṣṭhasya rāmasya viditātmanaḥ
śubhāni dharmayuktāni vacanāni samarpayan', null, 5028042),
('ramayana-5-28-43', 43, 'Sundara Kanda, Sarga 28, Verse 43', 'श्रावयिष्यामि सर्वाणि मधुरां प्रब्रुवन्गिरम्।
श्रद्धास्यति यथा हीयं तथा सर्वं समादधे॥', 'śrāvayiṣyāmi sarvāṇi madhurāṃ prabruvan giram
śraddhāsyati yathā hīyaṃ tathā sarvaṃ samādadhe', null, 5028043),
('ramayana-5-28-44', 44, 'Sundara Kanda, Sarga 28, Verse 44', 'इति स बहुविधं महानुभावो जगतिपतेः प्रमदामवेक्षमाणः।
मधुरमवितथं जगाद वाक्यं द्रुमविटपान्तरमास्थितो हनूमान्॥', 'iti sa bahuvidhaṃ mahānubhāvo jagatipateḥ pramadām avekṣamāṇaḥ
madhuram avitathaṃ jagāda vākyaṃ drumaviṭapāntaram āsthito hanūmān', null, 5028044)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 29 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-29-1', 1, 'Sundara Kanda, Sarga 29, Verse 1', 'एवं बहुविधां चिन्तां चिन्तयित्व महाकपिः।
संश्रवे मधुरं वाक्यं वैदेह्या व्याजहार ह॥', 'evaṃ bahuvidhāṃ cintāṃ cintayitva mahākapiḥ
saṃśrave madhuraṃ vākyaṃ vaidehyā vyājahāra ha', null, 5029001),
('ramayana-5-29-2', 2, 'Sundara Kanda, Sarga 29, Verse 2', 'राजा दशरथो नाम रथकुञ्जरवाजिनाम्।
पुण्यशीलो महाकीर्तिरृजुरासीन्महायशाः।
चक्रवर्तिकुले जातः पुरंदरसमो बले॥', 'rājā daśaratho nāma rathakuñjaravājinām
puṇyaśīlo mahākīrtir ṛjur āsīn mahāyaśāḥ
cakravartikule jātaḥ puraṃdarasamo bale', null, 5029002),
('ramayana-5-29-3', 3, 'Sundara Kanda, Sarga 29, Verse 3', 'अहिंसारतिरक्षुद्रो घृणी सत्यपराक्रमः।
मुख्यश्चेक्ष्वाकुवंशस्य लक्ष्मीवांल्लक्ष्मिवर्धनः॥', 'ahiṃsāratir akṣudro ghṛṇī satyaparākramaḥ
mukhyaś cekṣvākuvaṃśasya lakṣmīvāṃl lakṣmivardhanaḥ', null, 5029003),
('ramayana-5-29-4', 4, 'Sundara Kanda, Sarga 29, Verse 4', 'पार्थिवव्यञ्जनैर्युक्तः पृथुश्रीः पार्थिवर्षभः।
पृथिव्यां चतुरन्तयां विश्रुतः सुखदः सुखी॥', 'pārthivavyañjanair yuktaḥ pṛthuśrīḥ pārthivarṣabhaḥ
pṛthivyāṃ caturantayāṃ viśrutaḥ sukhadaḥ sukhī', null, 5029004),
('ramayana-5-29-5', 5, 'Sundara Kanda, Sarga 29, Verse 5', 'तस्य पुत्रः प्रियो ज्येष्ठस्ताराधिपनिभाननः।
रामो नाम विशेषज्ञः श्रेष्ठः सर्वधनुष्मताम्॥', 'tasya putraḥ priyo jyeṣṭhas tārādhipanibhānanaḥ
rāmo nāma viśeṣajñaḥ śreṣṭhaḥ sarvadhanuṣmatām', null, 5029005),
('ramayana-5-29-6', 6, 'Sundara Kanda, Sarga 29, Verse 6', 'रक्षिता स्वस्य वृत्तस्य स्वजनस्यापि रक्षिता।
रक्षिता जीवलोकस्य धर्मस्य च परंतपः॥', 'rakṣitā svasya vṛttasya svajanasyāpi rakṣitā
rakṣitā jīvalokasya dharmasya ca paraṃtapaḥ', null, 5029006),
('ramayana-5-29-7', 7, 'Sundara Kanda, Sarga 29, Verse 7', 'तस्य सत्याभिसंधस्य वृद्धस्य वचनात्पितुः।
सभार्यः सह च भ्रात्रा वीरः प्रव्रजितो वनम्॥', 'tasya satyābhisaṃdhasya vṛddhasya vacanāt pituḥ
sabhāryaḥ saha ca bhrātrā vīraḥ pravrajito vanam', null, 5029007),
('ramayana-5-29-8', 8, 'Sundara Kanda, Sarga 29, Verse 8', 'तेन तत्र महारण्ये मृगयां परिधावता।
जनस्थानवधं श्रुत्वा हतौ च खरदूषणौ।
ततस्त्वमर्षापहृता जानकी रावणेन तु॥', 'tena tatra mahāraṇye mṛgayāṃ paridhāvatā
janasthānavadhaṃ śrutvā hatau ca kharadūṣaṇau
tatas tv amarṣāpahṛtā jānakī rāvaṇena tu', null, 5029008),
('ramayana-5-29-9', 9, 'Sundara Kanda, Sarga 29, Verse 9', 'यथारूपां यथावर्णां यथालक्ष्मीं विनिश्चिताम्।
अश्रौषं राघवस्याहं सेयमासादिता मया॥', 'yathārūpāṃ yathāvarṇāṃ yathālakṣmīṃ viniścitām
aśrauṣaṃ rāghavasyāhaṃ seyam āsāditā mayā', null, 5029009),
('ramayana-5-29-10', 10, 'Sundara Kanda, Sarga 29, Verse 10', 'विररामैवमुक्त्वासौ वाचं वानरपुंगवः।
जानकी चापि तच्छ्रुत्वा विस्मयं परमं गता॥', 'virarāmaivam uktvāsau vācaṃ vānarapuṃgavaḥ
jānakī cāpi tac chrutvā vismayaṃ paramaṃ gatā', null, 5029010),
('ramayana-5-29-11', 11, 'Sundara Kanda, Sarga 29, Verse 11', 'ततः सा वक्रकेशान्ता सुकेशी केशसंवृतम्।
उन्नम्य वदनं भीरुः शिंशपावृक्षमैक्षत॥', 'tataḥ sā vakrakeśāntā sukeśī keśasaṃvṛtam
unnamya vadanaṃ bhīruḥ śiṃśapāvṛkṣam aikṣata', null, 5029011),
('ramayana-5-29-12', 12, 'Sundara Kanda, Sarga 29, Verse 12', 'सा तिर्यगूर्ध्वं च तथाप्यधस्तान्निरीक्षमाणा तमचिन्त्य बुद्धिम्।
ददर्श पिङ्गाधिपतेरमात्यं वातात्मजं सूर्यमिवोदयस्थम्॥', 'sā tiryag ūrdhvaṃ ca tathāpy adhastān nirīkṣamāṇā tam acintya buddhim
dadarśa piṅgādhipater amātyaṃ vātātmajaṃ sūryam ivodayastham', null, 5029012)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 30 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-30-1', 1, 'Sundara Kanda, Sarga 30, Verse 1', 'ततः शाखान्तरे लीनं दृष्ट्वा चलितमानसा।
सा ददर्श कपिं तत्र प्रश्रितं प्रियवादिनम्॥', 'tataḥ śākhāntare līnaṃ dṛṣṭvā calitamānasā
sā dadarśa kapiṃ tatra praśritaṃ priyavādinam', null, 5030001),
('ramayana-5-30-2', 2, 'Sundara Kanda, Sarga 30, Verse 2', 'सा तु दृष्ट्वा हरिश्रेष्ठं विनीतवदुपस्थितम्।
मैथिली चिन्तयामास स्वप्नोऽयमिति भामिनी॥', 'sā tu dṛṣṭvā hariśreṣṭhaṃ vinītavad upasthitam
maithilī cintayām āsa svapno ''yam iti bhāminī', null, 5030002),
('ramayana-5-30-3', 3, 'Sundara Kanda, Sarga 30, Verse 3', 'सा तं समीक्ष्यैव भृशं विसंज्ञा गतासुकल्पेव बभूव सीता।
चिरेण संज्ञां प्रतिलभ्य चैव विचिन्तयामास विशालनेत्रा॥', 'sā taṃ samīkṣyaiva bhṛśaṃ visaṃjñā gatāsukalpeva babhūva sītā
cireṇa saṃjñāṃ pratilabhya caiva vicintayām āsa viśālanetrā', null, 5030003),
('ramayana-5-30-4', 4, 'Sundara Kanda, Sarga 30, Verse 4', 'स्वप्नो मयायं विकृतोऽद्य दृष्टः शाखामृगः शास्त्रगणैर्निषिद्धः।
स्वस्त्यस्तु रामाय सलक्ष्मणाय तथा पितुर्मे जनकस्य राज्ञः॥', 'svapno mayāyaṃ vikṛto ''dya dṛṣṭaḥ śākhāmṛgaḥ śāstragaṇair niṣiddhaḥ
svasty astu rāmāya salakṣmaṇāya tathā pitur me janakasya rājñaḥ', null, 5030004),
('ramayana-5-30-5', 5, 'Sundara Kanda, Sarga 30, Verse 5', 'स्वप्नोऽपि नायं न हि मेऽस्ति निद्रा शोकेन दुःखेन च पीडितायाः।
सुखं हि मे नास्ति यतोऽस्मि हीना तेनेन्दुपूर्णप्रतिमाननेन॥', 'svapno ''pi nāyaṃ na hi me ''sti nidrā śokena duḥkhena ca pīḍitāyāḥ
sukhaṃ hi me nāsti yato ''smi hīnā tenendupūrṇapratimānanena', null, 5030005),
('ramayana-5-30-6', 6, 'Sundara Kanda, Sarga 30, Verse 6', 'अहं हि तस्याद्य मनो भवेन संपीडिता तद्गतसर्वभावा।
विचिन्तयन्ती सततं तमेव तथैव पश्यामि तथा शृणोमि॥', 'ahaṃ hi tasyādya mano bhavena saṃpīḍitā tad gatasarvabhāvā
vicintayantī satataṃ tam eva tathaiva paśyāmi tathā śṛṇomi', null, 5030006),
('ramayana-5-30-7', 7, 'Sundara Kanda, Sarga 30, Verse 7', 'मनोरथः स्यादिति चिन्तयामि तथापि बुद्ध्या च वितर्कयामि।
किं कारणं तस्य हि नास्ति रूपं सुव्यक्तरूपश्च वदत्ययं माम्॥', 'manorathaḥ syād iti cintayāmi tathāpi buddhyā ca vitarkayāmi
kiṃ kāraṇaṃ tasya hi nāsti rūpaṃ suvyaktarūpaś ca vadaty ayaṃ mām', null, 5030007),
('ramayana-5-30-8', 8, 'Sundara Kanda, Sarga 30, Verse 8', 'नमोऽस्तु वाचस्पतये सवज्रिणे स्वयम्भुवे चैव हुताशनाय।
अनेन चोक्तं यदिदं ममाग्रतो वनौकसा तच्च तथास्तु नान्यथा॥', 'namo ''stu vācaspataye savajriṇe svayambhuve caiva hutāśanāya
anena coktaṃ yad idaṃ mamāgrato vanaukasā tac ca tathāstu nānyathā', null, 5030008)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 31 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-31-1', 1, 'Sundara Kanda, Sarga 31, Verse 1', 'तामब्रवीन्महातेजा हनूमान्मारुतात्मजः।
शिरस्यञ्जलिमाधाय सीतां मधुरया गिरा॥', 'tām abravīn mahātejā hanūmān mārutātmajaḥ
śirasy añjalim ādhāya sītāṃ madhurayā girā', null, 5031001),
('ramayana-5-31-2', 2, 'Sundara Kanda, Sarga 31, Verse 2', 'का नु पद्मपलाशाक्षी क्लिष्टकौशेयवासिनी।
द्रुमस्य शाखामालम्ब्य तिष्ठसि त्वमनिन्दिता॥', 'kā nu padmapalāśākṣī kliṣṭakauśeyavāsinī
drumasya śākhām ālambya tiṣṭhasi tvam aninditā', null, 5031002),
('ramayana-5-31-3', 3, 'Sundara Kanda, Sarga 31, Verse 3', 'किमर्थं तव नेत्राभ्यां वारि स्रवति शोकजम्।
पुण्डरीकपलाशाभ्यां विप्रकीर्णमिवोदकम्॥', 'kimarthaṃ tava netrābhyāṃ vāri sravati śokajam
puṇḍarīkapalāśābhyāṃ viprakīrṇam ivodakam', null, 5031003),
('ramayana-5-31-4', 4, 'Sundara Kanda, Sarga 31, Verse 4', 'सुराणामसुराणां च नागगन्धर्वरक्षसाम्।
यक्षाणां किंनराणां च का त्वं भवसि शोभने॥', 'surāṇām asurāṇāṃ ca nāgagandharvarakṣasām
yakṣāṇāṃ kiṃnarāṇāṃ ca kā tvaṃ bhavasi śobhane', null, 5031004),
('ramayana-5-31-5', 5, 'Sundara Kanda, Sarga 31, Verse 5', 'का त्वं भवसि रुद्राणां मरुतां वा वरानने।
वसूनां वा वरारोहे देवता प्रतिभासि मे॥', 'kā tvaṃ bhavasi rudrāṇāṃ marutāṃ vā varānane
vasūnāṃ vā varārohe devatā pratibhāsi me', null, 5031005),
('ramayana-5-31-6', 6, 'Sundara Kanda, Sarga 31, Verse 6', 'किं नु चन्द्रमसा हीना पतिता विबुधालयात्।
रोहिणी ज्योतिषां श्रेष्ठा श्रेष्ठा सर्वगुणान्विता॥', 'kiṃ nu candramasā hīnā patitā vibudhālayāt
rohiṇī jyotiṣāṃ śreṣṭhā śreṣṭhā sarvaguṇānvitā', null, 5031006),
('ramayana-5-31-7', 7, 'Sundara Kanda, Sarga 31, Verse 7', 'कोपाद्वा यदि वा मोहाद्भर्तारमसितेक्षणा।
वसिष्ठं कोपयित्वा त्वं नासि कल्याण्यरुन्धती॥', 'kopād vā yadi vā mohād bhartāram asitekṣaṇā
vasiṣṭhaṃ kopayitvā tvaṃ nāsi kalyāṇy arundhatī', null, 5031007),
('ramayana-5-31-8', 8, 'Sundara Kanda, Sarga 31, Verse 8', 'को नौ पुत्रः पिता भ्रात भर्ता वा ते सुमध्यमे।
अस्माल्लोकादमुं लोकं गतं त्वमनुशोचसि॥', 'ko nau putraḥ pitā bhrāta bhartā vā te sumadhyame
asmāl lokād amuṃ lokaṃ gataṃ tvam anuśocasi', null, 5031008),
('ramayana-5-31-9', 9, 'Sundara Kanda, Sarga 31, Verse 9', 'व्यञ्जनानि हि ते यानि लक्षणानि च लक्षये।
महिषी भूमिपालस्य राजकन्यासि मे मता॥', 'vyañjanāni hi te yāni lakṣaṇāni ca lakṣaye
mahiṣī bhūmipālasya rājakanyāsi me matā', null, 5031009),
('ramayana-5-31-10', 10, 'Sundara Kanda, Sarga 31, Verse 10', 'रावणेन जनस्थानाद्बलादपहृता यदि।
सीता त्वमसि भद्रं ते तन्ममाचक्ष्व पृच्छतः॥', 'rāvaṇena janasthānād balād apahṛtā yadi
sītā tvam asi bhadraṃ te tan mamācakṣva pṛcchataḥ', null, 5031010),
('ramayana-5-31-11', 11, 'Sundara Kanda, Sarga 31, Verse 11', 'सा तस्य वचनं श्रुत्वा रामकीर्तनहर्षिता।
उवाच वाक्यं वैदेही हनूमन्तं द्रुमाश्रितम्॥', 'sā tasya vacanaṃ śrutvā rāmakīrtanaharṣitā
uvāca vākyaṃ vaidehī hanūmantaṃ drumāśritam', null, 5031011),
('ramayana-5-31-12', 12, 'Sundara Kanda, Sarga 31, Verse 12', 'दुहिता जनकस्याहं वैदेहस्य महात्मनः।
सीता च नाम नाम्नाहं भार्या रामस्य धीमतः॥', 'duhitā janakasyāhaṃ vaidehasya mahātmanaḥ
sītā ca nāma nāmnāhaṃ bhāryā rāmasya dhīmataḥ', null, 5031012),
('ramayana-5-31-13', 13, 'Sundara Kanda, Sarga 31, Verse 13', 'समा द्वादश तत्राहं राघवस्य निवेशने।
भुञ्जाना मानुषान्भोगान्सर्वकामसमृद्धिनी॥', 'samā dvādaśa tatrāhaṃ rāghavasya niveśane
bhuñjānā mānuṣān bhogān sarvakāmasamṛddhinī', null, 5031013),
('ramayana-5-31-14', 14, 'Sundara Kanda, Sarga 31, Verse 14', 'ततस्त्रयोदशे वर्षे राज्येनेक्ष्वाकुनन्दनम्।
अभिषेचयितुं राजा सोपाध्यायः प्रचक्रमे॥', 'tatas trayodaśe varṣe rājyenekṣvākunandanam
abhiṣecayituṃ rājā sopādhyāyaḥ pracakrame', null, 5031014),
('ramayana-5-31-15', 15, 'Sundara Kanda, Sarga 31, Verse 15', 'तस्मिन्संभ्रियमाणे तु राघवस्याभिषेचने।
कैकेयी नाम भर्तारं देवी वचनमब्रवीत्॥', 'tasmin saṃbhriyamāṇe tu rāghavasyābhiṣecane
kaikeyī nāma bhartāraṃ devī vacanam abravīt', null, 5031015),
('ramayana-5-31-16', 16, 'Sundara Kanda, Sarga 31, Verse 16', 'न पिबेयं न खादेयं प्रत्यहं मम भोजनम्।
एष मे जीवितस्यान्तो रामो यद्यभिषिच्यते॥', 'na pibeyaṃ na khādeyaṃ pratyahaṃ mama bhojanam
eṣa me jīvitasyānto rāmo yady abhiṣicyate', null, 5031016),
('ramayana-5-31-17', 17, 'Sundara Kanda, Sarga 31, Verse 17', 'यत्तदुक्तं त्वया वाक्यं प्रीत्या नृपतिसत्तम।
तच्चेन्न वितथं कार्यं वनं गच्छतु राघवः॥', 'yat tad uktaṃ tvayā vākyaṃ prītyā nṛpatisattama
tac cen na vitathaṃ kāryaṃ vanaṃ gacchatu rāghavaḥ', null, 5031017),
('ramayana-5-31-18', 18, 'Sundara Kanda, Sarga 31, Verse 18', 'स राजा सत्यवाग्देव्या वरदानमनुस्मरन्।
मुमोह वचनं श्रुत्वा कैकेय्याः क्रूरमप्रियम्॥', 'sa rājā satyavāg devyā varadānam anusmaran
mumoha vacanaṃ śrutvā kaikeyyāḥ krūram apriyam', null, 5031018),
('ramayana-5-31-19', 19, 'Sundara Kanda, Sarga 31, Verse 19', 'ततस्तु स्थविरो राजा सत्यधर्मे व्यवस्थितः।
ज्येष्ठं यशस्विनं पुत्रं रुदन्राज्यमयाचत॥', 'tatas tu sthaviro rājā satyadharme vyavasthitaḥ
jyeṣṭhaṃ yaśasvinaṃ putraṃ rudan rājyam ayācata', null, 5031019),
('ramayana-5-31-20', 20, 'Sundara Kanda, Sarga 31, Verse 20', 'स पितुर्वचनं श्रीमानभिषेकात्परं प्रियम्।
मनसा पूर्वमासाद्य वाचा प्रतिगृहीतवान्॥', 'sa pitur vacanaṃ śrīmān abhiṣekāt paraṃ priyam
manasā pūrvam āsādya vācā pratigṛhītavān', null, 5031020),
('ramayana-5-31-21', 21, 'Sundara Kanda, Sarga 31, Verse 21', 'दद्यान्न प्रतिगृह्णीयान्न ब्रूयत्किं चिदप्रियम्।
अपि जीवितहेतोर्हि रामः सत्यपराक्रमः॥', 'dadyān na pratigṛhṇīyān na brūyat kiṃ cid apriyam
api jīvitahetor hi rāmaḥ satyaparākramaḥ', null, 5031021),
('ramayana-5-31-22', 22, 'Sundara Kanda, Sarga 31, Verse 22', 'स विहायोत्तरीयाणि महार्हाणि महायशाः।
विसृज्य मनसा राज्यं जनन्यै मां समादिशत्॥', 'sa vihāyottarīyāṇi mahārhāṇi mahāyaśāḥ
visṛjya manasā rājyaṃ jananyai māṃ samādiśat', null, 5031022),
('ramayana-5-31-23', 23, 'Sundara Kanda, Sarga 31, Verse 23', 'साहं तस्याग्रतस्तूर्णं प्रस्थिता वनचारिणी।
न हि मे तेन हीनाया वासः स्वर्गेऽपि रोचते॥', 'sāhaṃ tasyāgratas tūrṇaṃ prasthitā vanacāriṇī
na hi me tena hīnāyā vāsaḥ svarge ''pi rocate', null, 5031023),
('ramayana-5-31-24', 24, 'Sundara Kanda, Sarga 31, Verse 24', 'प्रागेव तु महाभागः सौमित्रिर्मित्रनन्दनः।
पूर्वजस्यानुयात्रार्थे द्रुमचीरैरलंकृतः॥', 'prāg eva tu mahābhāgaḥ saumitrir mitranandanaḥ
pūrvajasyānuyātrārthe drumacīrair alaṃkṛtaḥ', null, 5031024),
('ramayana-5-31-25', 25, 'Sundara Kanda, Sarga 31, Verse 25', 'ते वयं भर्तुरादेशं बहु मान्यदृढव्रताः।
प्रविष्टाः स्म पुराद्दृष्टं वनं गम्भीरदर्शनम्॥', 'te vayaṃ bhartur ādeśaṃ bahu mānyadṛḍhavratāḥ
praviṣṭāḥ sma purād dṛṣṭaṃ vanaṃ gambhīradarśanam', null, 5031025),
('ramayana-5-31-26', 26, 'Sundara Kanda, Sarga 31, Verse 26', 'वसतो दण्डकारण्ये तस्याहममितौजसः।
रक्षसापहृता भार्या रावणेन दुरात्मना॥', 'vasato daṇḍakāraṇye tasyāham amitaujasaḥ
rakṣasāpahṛtā bhāryā rāvaṇena durātmanā', null, 5031026),
('ramayana-5-31-27', 27, 'Sundara Kanda, Sarga 31, Verse 27', 'द्वौ मासौ तेन मे कालो जीवितानुग्रहः कृतः।
ऊर्ध्वं द्वाभ्यां तु मासाभ्यां ततस्त्यक्ष्यामि जीवितम्॥', 'dvau māsau tena me kālo jīvitānugrahaḥ kṛtaḥ
ūrdhvaṃ dvābhyāṃ tu māsābhyāṃ tatas tyakṣyāmi jīvitam', null, 5031027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 32 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-32-1', 1, 'Sundara Kanda, Sarga 32, Verse 1', 'तस्यास्तद्वचनं श्रुत्वा हनूमान्हरियूथपः।
दुःखाद्दुःखाभिभूतायाः सान्तमुत्तरमब्रवीत्॥', 'tasyās tad vacanaṃ śrutvā hanūmān hariyūthapaḥ
duḥkhād duḥkhābhibhūtāyāḥ sāntam uttaram abravīt', null, 5032001),
('ramayana-5-32-2', 2, 'Sundara Kanda, Sarga 32, Verse 2', 'अहं रामस्य संदेशाद्देवि दूतस्तवागतः।
वैदेहि कुशली रामस्त्वां च कौशलमब्रवीत्॥', 'ahaṃ rāmasya saṃdeśād devi dūtas tavāgataḥ
vaidehi kuśalī rāmas tvāṃ ca kauśalam abravīt', null, 5032002),
('ramayana-5-32-3', 3, 'Sundara Kanda, Sarga 32, Verse 3', 'यो ब्राह्ममस्त्रं वेदांश्च वेद वेदविदां वरः।
स त्वां दाशरथी रामो देवि कौशलमब्रवीत्॥', 'yo brāhmam astraṃ vedāṃś ca veda vedavidāṃ varaḥ
sa tvāṃ dāśarathī rāmo devi kauśalam abravīt', null, 5032003),
('ramayana-5-32-4', 4, 'Sundara Kanda, Sarga 32, Verse 4', 'लक्ष्मणश्च महातेजा भर्तुस्तेऽनुचरः प्रियः।
कृतवाञ्शोकसंतप्तः शिरसा तेऽभिवादनम्॥', 'lakṣmaṇaś ca mahātejā bhartus te ''nucaraḥ priyaḥ
kṛtavāñ śokasaṃtaptaḥ śirasā te ''bhivādanam', null, 5032004),
('ramayana-5-32-5', 5, 'Sundara Kanda, Sarga 32, Verse 5', 'सा तयोः कुशलं देवी निशम्य नरसिंहयोः।
प्रीतिसंहृष्टसर्वाङ्गी हनूमान्तमथाब्रवीत्॥', 'sā tayoḥ kuśalaṃ devī niśamya narasiṃhayoḥ
prītisaṃhṛṣṭasarvāṅgī hanūmāntam athābravīt', null, 5032005),
('ramayana-5-32-6', 6, 'Sundara Kanda, Sarga 32, Verse 6', 'कल्याणी बत गथेयं लौकिकी प्रतिभाति मे।
एहि जीवन्तमानदो नरं वर्षशतादपि॥', 'kalyāṇī bata gatheyaṃ laukikī pratibhāti me
ehi jīvantam ānado naraṃ varṣaśatād api', null, 5032006),
('ramayana-5-32-7', 7, 'Sundara Kanda, Sarga 32, Verse 7', 'तयोः समागमे तस्मिन्प्रीतिरुत्पादिताद्भुता।
परस्परेण चालापं विश्वस्तौ तौ प्रचक्रतुः॥', 'tayoḥ samāgame tasmin prītir utpāditādbhutā
paraspareṇa cālāpaṃ viśvastau tau pracakratuḥ', null, 5032007),
('ramayana-5-32-8', 8, 'Sundara Kanda, Sarga 32, Verse 8', 'तस्यास्तद्वचनं श्रुत्वा हनूमान्हरियूथपः।
सीतायाः शोकदीनायाः समीपमुपचक्रमे॥', 'tasyās tad vacanaṃ śrutvā hanūmān hariyūthapaḥ
sītāyāḥ śokadīnāyāḥ samīpam upacakrame', null, 5032008),
('ramayana-5-32-9', 9, 'Sundara Kanda, Sarga 32, Verse 9', 'यथा यथा समीपं स हनूमानुपसर्पति।
तथा तथा रावणं सा तं सीता परिशङ्कते॥', 'yathā yathā samīpaṃ sa hanūmān upasarpati
tathā tathā rāvaṇaṃ sā taṃ sītā pariśaṅkate', null, 5032009),
('ramayana-5-32-10', 10, 'Sundara Kanda, Sarga 32, Verse 10', 'अहो धिग्धिक्कृतमिदं कथितं हि यदस्य मे।
रूपान्तरमुपागम्य स एवायं हि रावणः॥', 'aho dhig dhik kṛtam idaṃ kathitaṃ hi yad asya me
rūpāntaram upāgamya sa evāyaṃ hi rāvaṇaḥ', null, 5032010),
('ramayana-5-32-11', 11, 'Sundara Kanda, Sarga 32, Verse 11', 'तामशोकस्य शाखां सा विमुक्त्वा शोककर्शिता।
तस्यामेवानवद्याङ्गी धरण्यां समुपाविशत्॥', 'tām aśokasya śākhāṃ sā vimuktvā śokakarśitā
tasyām evānavadyāṅgī dharaṇyāṃ samupāviśat', null, 5032011),
('ramayana-5-32-12', 12, 'Sundara Kanda, Sarga 32, Verse 12', 'अवन्दत महाबाहुस्ततस्तां जनकात्मजाम्।
सा चैनं भयवित्रस्ता भूयो नैवाभ्युदैक्षत॥', 'avandata mahābāhus tatas tāṃ janakātmajām
sā cainaṃ bhayavitrastā bhūyo naivābhyudaikṣata', null, 5032012),
('ramayana-5-32-13', 13, 'Sundara Kanda, Sarga 32, Verse 13', 'तं दृष्ट्वा वन्दमानं तु सीता शशिनिभानना।
अब्रवीद्दीर्घमुच्छ्वस्य वानरं मधुरस्वरा॥', 'taṃ dṛṣṭvā vandamānaṃ tu sītā śaśinibhānanā
abravīd dīrgham ucchvasya vānaraṃ madhurasvarā', null, 5032013),
('ramayana-5-32-14', 14, 'Sundara Kanda, Sarga 32, Verse 14', 'मायां प्रविष्टो मायावी यदि त्वं रावणः स्वयम्।
उत्पादयसि मे भूयः संतापं तन्न शोभनम्॥', 'māyāṃ praviṣṭo māyāvī yadi tvaṃ rāvaṇaḥ svayam
utpādayasi me bhūyaḥ saṃtāpaṃ tan na śobhanam', null, 5032014),
('ramayana-5-32-15', 15, 'Sundara Kanda, Sarga 32, Verse 15', 'स्वं परित्यज्य रूपं यः परिव्राजकरूपधृत्।
जनस्थाने मया दृष्टस्त्वं स एवासि रावणः॥', 'svaṃ parityajya rūpaṃ yaḥ parivrājakarūpadhṛt
janasthāne mayā dṛṣṭas tvaṃ sa evāsi rāvaṇaḥ', null, 5032015),
('ramayana-5-32-16', 16, 'Sundara Kanda, Sarga 32, Verse 16', 'उपवासकृशां दीनां कामरूप निशाचर।
संतापयसि मां भूयः संतापं तन्न शोभनम्॥', 'upavāsakṛśāṃ dīnāṃ kāmarūpa niśācara
saṃtāpayasi māṃ bhūyaḥ saṃtāpaṃ tan na śobhanam', null, 5032016),
('ramayana-5-32-17', 17, 'Sundara Kanda, Sarga 32, Verse 17', 'यदि रामस्य दूतस्त्वमागतो भद्रमस्तु ते।
पृच्छामि त्वां हरिश्रेष्ठ प्रिया राम कथा हि मे॥', 'yadi rāmasya dūtas tvam āgato bhadram astu te
pṛcchāmi tvāṃ hariśreṣṭha priyā rāma kathā hi me', null, 5032017),
('ramayana-5-32-18', 18, 'Sundara Kanda, Sarga 32, Verse 18', 'गुणान्रामस्य कथय प्रियस्य मम वानर।
चित्तं हरसि मे सौम्य नदीकूलं यथा रयः॥', 'guṇān rāmasya kathaya priyasya mama vānara
cittaṃ harasi me saumya nadīkūlaṃ yathā rayaḥ', null, 5032018),
('ramayana-5-32-19', 19, 'Sundara Kanda, Sarga 32, Verse 19', 'अहो स्वप्नस्य सुखता याहमेवं चिराहृता।
प्रेषितं नाम पश्यामि राघवेण वनौकसं॥', 'aho svapnasya sukhatā yāham evaṃ cirāhṛtā
preṣitaṃ nāma paśyāmi rāghaveṇa vanaukasaṃ', null, 5032019),
('ramayana-5-32-20', 20, 'Sundara Kanda, Sarga 32, Verse 20', 'स्वप्नेऽपि यद्यहं वीरं राघवं सहलक्ष्मणम्।
पश्येयं नावसीदेयं स्वप्नोऽपि मम मत्सरी॥', 'svapne ''pi yady ahaṃ vīraṃ rāghavaṃ sahalakṣmaṇam
paśyeyaṃ nāvasīdeyaṃ svapno ''pi mama matsarī', null, 5032020),
('ramayana-5-32-21', 21, 'Sundara Kanda, Sarga 32, Verse 21', 'नाहं स्वप्नमिमं मन्ये स्वप्ने दृष्ट्वा हि वानरम्।
न शक्योऽभ्युदयः प्राप्तुं प्राप्तश्चाभ्युदयो मम॥', 'nāhaṃ svapnam imaṃ manye svapne dṛṣṭvā hi vānaram
na śakyo ''bhyudayaḥ prāptuṃ prāptaś cābhyudayo mama', null, 5032021),
('ramayana-5-32-22', 22, 'Sundara Kanda, Sarga 32, Verse 22', 'किं नु स्याच्चित्तमोहोऽयं भवेद्वातगतिस्त्वियम्।
उन्मादजो विकारो वा स्यादियं मृगतृष्णिका॥', 'kiṃ nu syāc cittamoho ''yaṃ bhaved vātagatis tv iyam
unmādajo vikāro vā syād iyaṃ mṛgatṛṣṇikā', null, 5032022),
('ramayana-5-32-23', 23, 'Sundara Kanda, Sarga 32, Verse 23', 'अथ वा नायमुन्मादो मोहोऽप्युन्मादलक्ष्मणः।
संबुध्ये चाहमात्मानमिमं चापि वनौकसं॥', 'atha vā nāyam unmādo moho ''py unmādalakṣmaṇaḥ
saṃbudhye cāham ātmānam imaṃ cāpi vanaukasaṃ', null, 5032023),
('ramayana-5-32-24', 24, 'Sundara Kanda, Sarga 32, Verse 24', 'इत्येवं बहुधा सीता संप्रधार्य बलाबलम्।
रक्षसां कामरूपत्वान्मेने तं राक्षसाधिपम्॥', 'ity evaṃ bahudhā sītā saṃpradhārya balābalam
rakṣasāṃ kāmarūpatvān mene taṃ rākṣasādhipam', null, 5032024),
('ramayana-5-32-25', 25, 'Sundara Kanda, Sarga 32, Verse 25', 'एतां बुद्धिं तदा कृत्वा सीता सा तनुमध्यमा।
न प्रतिव्याजहाराथ वानरं जनकात्मजा॥', 'etāṃ buddhiṃ tadā kṛtvā sītā sā tanumadhyamā
na prativyājahārātha vānaraṃ janakātmajā', null, 5032025),
('ramayana-5-32-26', 26, 'Sundara Kanda, Sarga 32, Verse 26', 'सीतायाश्चिन्तितं बुद्ध्वा हनूमान्मारुतात्मजः।
श्रोत्रानुकूलैर्वचनैस्तदा तां संप्रहर्षयत्॥', 'sītāyāś cintitaṃ buddhvā hanūmān mārutātmajaḥ
śrotrānukūlair vacanais tadā tāṃ saṃpraharṣayat', null, 5032026),
('ramayana-5-32-27', 27, 'Sundara Kanda, Sarga 32, Verse 27', 'आदित्य इव तेजस्वी लोककान्तः शशी यथा।
राजा सर्वस्य लोकस्य देवो वैश्रवणो यथा॥', 'āditya iva tejasvī lokakāntaḥ śaśī yathā
rājā sarvasya lokasya devo vaiśravaṇo yathā', null, 5032027),
('ramayana-5-32-28', 28, 'Sundara Kanda, Sarga 32, Verse 28', 'विक्रमेणोपपन्नश्च यथा विष्णुर्महायशाः।
सत्यवादी मधुरवाग्देवो वाचस्पतिर्यथा॥', 'vikrameṇopapannaś ca yathā viṣṇur mahāyaśāḥ
satyavādī madhuravāg devo vācaspatir yathā', null, 5032028),
('ramayana-5-32-29', 29, 'Sundara Kanda, Sarga 32, Verse 29', 'रूपवान्सुभगः श्रीमान्कन्दर्प इव मूर्तिमान्।
स्थानक्रोधप्रहर्ता च श्रेष्ठो लोके महारथः।
बाहुच्छायामवष्टब्धो यस्य लोको महात्मनः॥', 'rūpavān subhagaḥ śrīmān kandarpa iva mūrtimān
sthānakrodhaprahartā ca śreṣṭho loke mahārathaḥ
bāhucchāyām avaṣṭabdho yasya loko mahātmanaḥ', null, 5032029),
('ramayana-5-32-30', 30, 'Sundara Kanda, Sarga 32, Verse 30', 'अपकृष्याश्रमपदान्मृगरूपेण राघवम्।
शून्ये येनापनीतासि तस्य द्रक्ष्यसि यत्फलम्॥', 'apakṛṣyāśramapadān mṛgarūpeṇa rāghavam
śūnye yenāpanītāsi tasya drakṣyasi yat phalam', null, 5032030),
('ramayana-5-32-31', 31, 'Sundara Kanda, Sarga 32, Verse 31', 'नचिराद्रावणं संख्ये यो वधिष्यति वीर्यवान्।
रोषप्रमुक्तैरिषुभिर्ज्वलद्भिरिव पावकैः॥', 'nacirād rāvaṇaṃ saṃkhye yo vadhiṣyati vīryavān
roṣapramuktair iṣubhir jvaladbhir iva pāvakaiḥ', null, 5032031),
('ramayana-5-32-32', 32, 'Sundara Kanda, Sarga 32, Verse 32', 'तेनाहं प्रेषितो दूतस्त्वत्सकाशमिहागतः।
त्वद्वियोगेन दुःखार्तः स त्वां कौशलमब्रवीत्॥', 'tenāhaṃ preṣito dūtas tvatsakāśam ihāgataḥ
tvadviyogena duḥkhārtaḥ sa tvāṃ kauśalam abravīt', null, 5032032),
('ramayana-5-32-33', 33, 'Sundara Kanda, Sarga 32, Verse 33', 'लक्ष्मणश्च महातेजाः सुमित्रानन्दवर्धनः।
अभिवाद्य महाबाहुः सोऽपि कौशलमब्रवीत्॥', 'lakṣmaṇaś ca mahātejāḥ sumitrānandavardhanaḥ
abhivādya mahābāhuḥ so ''pi kauśalam abravīt', null, 5032033),
('ramayana-5-32-34', 34, 'Sundara Kanda, Sarga 32, Verse 34', 'रामस्य च सखा देवि सुग्रीवो नाम वानरः।
राजा वानरमुख्यानां स त्वां कौशलमब्रवीत्॥', 'rāmasya ca sakhā devi sugrīvo nāma vānaraḥ
rājā vānaramukhyānāṃ sa tvāṃ kauśalam abravīt', null, 5032034),
('ramayana-5-32-35', 35, 'Sundara Kanda, Sarga 32, Verse 35', 'नित्यं स्मरति रामस्त्वां ससुग्रीवः सलक्ष्मणः।
दिष्ट्या जीवसि वैदेहि राक्षसी वशमागता॥', 'nityaṃ smarati rāmas tvāṃ sasugrīvaḥ salakṣmaṇaḥ
diṣṭyā jīvasi vaidehi rākṣasī vaśam āgatā', null, 5032035),
('ramayana-5-32-36', 36, 'Sundara Kanda, Sarga 32, Verse 36', 'नचिराद्द्रक्ष्यसे रामं लक्ष्मणं च महारथम्।
मध्ये वानरकोटीनां सुग्रीवं चामितौजसं॥', 'nacirād drakṣyase rāmaṃ lakṣmaṇaṃ ca mahāratham
madhye vānarakoṭīnāṃ sugrīvaṃ cāmitaujasaṃ', null, 5032036),
('ramayana-5-32-37', 37, 'Sundara Kanda, Sarga 32, Verse 37', 'अहं सुग्रीवसचिवो हनूमान्नाम वानरः।
प्रविष्टो नगरीं लङ्कां लङ्घयित्वा महोदधिम्॥', 'ahaṃ sugrīvasacivo hanūmān nāma vānaraḥ
praviṣṭo nagarīṃ laṅkāṃ laṅghayitvā mahodadhim', null, 5032037),
('ramayana-5-32-38', 38, 'Sundara Kanda, Sarga 32, Verse 38', 'कृत्वा मूर्ध्नि पदन्यासं रावणस्य दुरात्मनः।
त्वां द्रष्टुमुपयातोऽहं समाश्रित्य पराक्रमम्॥', 'kṛtvā mūrdhni padanyāsaṃ rāvaṇasya durātmanaḥ
tvāṃ draṣṭum upayāto ''haṃ samāśritya parākramam', null, 5032038),
('ramayana-5-32-39', 39, 'Sundara Kanda, Sarga 32, Verse 39', 'नाहमस्मि तथा देवि यथा मामवगच्छसि।
विशङ्का त्यज्यतामेषा श्रद्धत्स्व वदतो मम॥', 'nāham asmi tathā devi yathā mām avagacchasi
viśaṅkā tyajyatām eṣā śraddhatsva vadato mama', null, 5032039)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 33 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-33-1', 1, 'Sundara Kanda, Sarga 33, Verse 1', 'तां तु राम कथां श्रुत्वा वैदेही वानरर्षभात्।
उवाच वचनं सान्त्वमिदं मधुरया गिरा॥', 'tāṃ tu rāma kathāṃ śrutvā vaidehī vānararṣabhāt
uvāca vacanaṃ sāntvam idaṃ madhurayā girā', null, 5033001),
('ramayana-5-33-2', 2, 'Sundara Kanda, Sarga 33, Verse 2', 'क्व ते रामेण संसर्गः कथं जानासि लक्ष्मणम्।
वानराणां नराणां च कथमासीत्समागमः॥', 'kva te rāmeṇa saṃsargaḥ kathaṃ jānāsi lakṣmaṇam
vānarāṇāṃ narāṇāṃ ca katham āsīt samāgamaḥ', null, 5033002),
('ramayana-5-33-3', 3, 'Sundara Kanda, Sarga 33, Verse 3', 'यानि रामस्य लिङ्गानि लक्ष्मणस्य च वानर।
तानि भूयः समाचक्ष्व न मां शोकः समाविशेत्॥', 'yāni rāmasya liṅgāni lakṣmaṇasya ca vānara
tāni bhūyaḥ samācakṣva na māṃ śokaḥ samāviśet', null, 5033003),
('ramayana-5-33-4', 4, 'Sundara Kanda, Sarga 33, Verse 4', 'कीदृशं तस्य संस्थानं रूपं रामस्य कीदृशम्।
कथमूरू कथं बाहू लक्ष्मणस्य च शंस मे॥', 'kīdṛśaṃ tasya saṃsthānaṃ rūpaṃ rāmasya kīdṛśam
katham ūrū kathaṃ bāhū lakṣmaṇasya ca śaṃsa me', null, 5033004),
('ramayana-5-33-5', 5, 'Sundara Kanda, Sarga 33, Verse 5', 'एवमुक्तस्तु वैदेह्या हनूमान्मारुतात्मजः।
ततो रामं यथातत्त्वमाख्यातुमुपचक्रमे॥', 'evam uktas tu vaidehyā hanūmān mārutātmajaḥ
tato rāmaṃ yathātattvam ākhyātum upacakrame', null, 5033005),
('ramayana-5-33-6', 6, 'Sundara Kanda, Sarga 33, Verse 6', 'जानन्ती बत दिष्ट्या मां वैदेहि परिपृच्छसि।
भर्तुः कमलपत्राक्षि संख्यानं लक्ष्मणस्य च॥', 'jānantī bata diṣṭyā māṃ vaidehi paripṛcchasi
bhartuḥ kamalapatrākṣi saṃkhyānaṃ lakṣmaṇasya ca', null, 5033006),
('ramayana-5-33-7', 7, 'Sundara Kanda, Sarga 33, Verse 7', 'यानि रामस्य चिह्नानि लक्ष्मणस्य च यानि वै।
लक्षितानि विशालाक्षि वदतः शृणु तानि मे॥', 'yāni rāmasya cihnāni lakṣmaṇasya ca yāni vai
lakṣitāni viśālākṣi vadataḥ śṛṇu tāni me', null, 5033007),
('ramayana-5-33-8', 8, 'Sundara Kanda, Sarga 33, Verse 8', 'रामः कमलपत्राक्षः सर्वभूतमनोहरः।
रूपदाक्षिण्यसंपन्नः प्रसूतो जनकात्मजे॥', 'rāmaḥ kamalapatrākṣaḥ sarvabhūtamanoharaḥ
rūpadākṣiṇyasaṃpannaḥ prasūto janakātmaje', null, 5033008),
('ramayana-5-33-9', 9, 'Sundara Kanda, Sarga 33, Verse 9', 'तेजसादित्यसंकाशः क्षमया पृथिवीसमः।
बृहस्पतिसमो बुद्ध्या यशसा वासवोपमः॥', 'tejasādityasaṃkāśaḥ kṣamayā pṛthivīsamaḥ
bṛhaspatisamo buddhyā yaśasā vāsavopamaḥ', null, 5033009),
('ramayana-5-33-10', 10, 'Sundara Kanda, Sarga 33, Verse 10', 'रक्षिता जीवलोकस्य स्वजनस्य च रक्षिता।
रक्षिता स्वस्य वृत्तस्य धर्मस्य च परंतपः॥', 'rakṣitā jīvalokasya svajanasya ca rakṣitā
rakṣitā svasya vṛttasya dharmasya ca paraṃtapaḥ', null, 5033010),
('ramayana-5-33-11', 11, 'Sundara Kanda, Sarga 33, Verse 11', 'रामो भामिनि लोकस्य चातुर्वर्ण्यस्य रक्षिता।
मर्यादानां च लोकस्य कर्ता कारयिता च सः॥', 'rāmo bhāmini lokasya cāturvarṇyasya rakṣitā
maryādānāṃ ca lokasya kartā kārayitā ca saḥ', null, 5033011),
('ramayana-5-33-12', 12, 'Sundara Kanda, Sarga 33, Verse 12', 'अर्चिष्मानर्चितोऽत्यर्थं ब्रह्मचर्यव्रते स्थितः।
साधूनामुपकारज्ञः प्रचारज्ञश्च कर्मणाम्॥', 'arciṣmān arcito ''tyarthaṃ brahmacaryavrate sthitaḥ
sādhūnām upakārajñaḥ pracārajñaś ca karmaṇām', null, 5033012),
('ramayana-5-33-13', 13, 'Sundara Kanda, Sarga 33, Verse 13', 'राजविद्याविनीतश्च ब्राह्मणानामुपासिता।
श्रुतवाञ्शीलसंपन्नो विनीतश्च परंतपः॥', 'rājavidyāvinītaś ca brāhmaṇānām upāsitā
śrutavāñ śīlasaṃpanno vinītaś ca paraṃtapaḥ', null, 5033013),
('ramayana-5-33-14', 14, 'Sundara Kanda, Sarga 33, Verse 14', 'यजुर्वेदविनीतश्च वेदविद्भिः सुपूजितः।
धनुर्वेदे च वेदे च वेदाङ्गेषु च निष्ठितः॥', 'yajurvedavinītaś ca vedavidbhiḥ supūjitaḥ
dhanurvede ca vede ca vedāṅgeṣu ca niṣṭhitaḥ', null, 5033014),
('ramayana-5-33-15', 15, 'Sundara Kanda, Sarga 33, Verse 15', 'विपुलांसो महाबाहुः कम्बुग्रीवः शुभाननः।
गूढजत्रुः सुताम्राक्षो रामो देवि जनैः श्रुतः॥', 'vipulāṃso mahābāhuḥ kambugrīvaḥ śubhānanaḥ
gūḍhajatruḥ sutāmrākṣo rāmo devi janaiḥ śrutaḥ', null, 5033015),
('ramayana-5-33-16', 16, 'Sundara Kanda, Sarga 33, Verse 16', 'दुन्दुभिस्वननिर्घोषः स्निग्धवर्णः प्रतापवान्।
समः समविभक्ताङ्गो वर्णं श्यामं समाश्रितः॥', 'dundubhisvananirghoṣaḥ snigdhavarṇaḥ pratāpavān
samaḥ samavibhaktāṅgo varṇaṃ śyāmaṃ samāśritaḥ', null, 5033016),
('ramayana-5-33-17', 17, 'Sundara Kanda, Sarga 33, Verse 17', 'त्रिस्थिरस्त्रिप्रलम्बश्च त्रिसमस्त्रिषु चोन्नतः।
त्रिवलीवांस्त्र्यवणतश्चतुर्व्यङ्गस्त्रिशीर्षवान्॥', 'tristhiras tripralambaś ca trisamas triṣu connataḥ
trivalīvāṃs tryavaṇataś caturvyaṅgas triśīrṣavān', null, 5033017),
('ramayana-5-33-18', 18, 'Sundara Kanda, Sarga 33, Verse 18', 'चतुष्कलश्चतुर्लेखश्चतुष्किष्कुश्चतुःसमः।
चतुर्दशसमद्वन्द्वश्चतुर्दष्टश्चतुर्गतिः॥', 'catuṣkalaś caturlekhaś catuṣkiṣkuś catuḥsamaḥ
caturdaśasamadvandvaś caturdaṣṭaś caturgatiḥ', null, 5033018),
('ramayana-5-33-19', 19, 'Sundara Kanda, Sarga 33, Verse 19', 'महौष्ठहनुनासश्च पञ्चस्निग्धोऽष्टवंशवान्।
दशपद्मो दशबृहत्त्रिभिर्व्याप्तो द्विशुक्लवान्।
षडुन्नतो नवतनुस्त्रिभिर्व्याप्नोति राघवः॥', 'mahauṣṭhahanunāsaś ca pañcasnigdho ''ṣṭavaṃśavān
daśapadmo daśabṛhat tribhir vyāpto dviśuklavān
ṣaḍunnato navatanus tribhir vyāpnoti rāghavaḥ', null, 5033019),
('ramayana-5-33-20', 20, 'Sundara Kanda, Sarga 33, Verse 20', 'सत्यधर्मपरः श्रीमान्संग्रहानुग्रहे रतः।
देशकालविभागज्ञः सर्वलोकप्रियंवदः॥', 'satyadharmaparaḥ śrīmān saṃgrahānugrahe rataḥ
deśakālavibhāgajñaḥ sarvalokapriyaṃvadaḥ', null, 5033020),
('ramayana-5-33-21', 21, 'Sundara Kanda, Sarga 33, Verse 21', 'भ्राता च तस्य द्वैमात्रः सौमित्रिरपराजितः।
अनुरागेण रूपेण गुणैश्चैव तथाविधः॥', 'bhrātā ca tasya dvaimātraḥ saumitrir aparājitaḥ
anurāgeṇa rūpeṇa guṇaiś caiva tathāvidhaḥ', null, 5033021),
('ramayana-5-33-22', 22, 'Sundara Kanda, Sarga 33, Verse 22', 'त्वामेव मार्गमाणो तौ विचरन्तौ वसुंधराम्।
ददर्शतुर्मृगपतिं पूर्वजेनावरोपितम्॥', 'tvām eva mārgamāṇo tau vicarantau vasuṃdharām
dadarśatur mṛgapatiṃ pūrvajenāvaropitam', null, 5033022),
('ramayana-5-33-23', 23, 'Sundara Kanda, Sarga 33, Verse 23', 'ऋश्यमूकस्य पृष्ठे तु बहुपादपसंकुले।
भ्रातुर्भार्यार्तमासीनं सुग्रीवं प्रियदर्शनम्॥', 'ṛśyamūkasya pṛṣṭhe tu bahupādapasaṃkule
bhrātur bhāryārtam āsīnaṃ sugrīvaṃ priyadarśanam', null, 5033023),
('ramayana-5-33-24', 24, 'Sundara Kanda, Sarga 33, Verse 24', 'वयं तु हरिराजं तं सुग्रीवं सत्यसंगरम्।
परिचर्यामहे राज्यात्पूर्वजेनावरोपितम्॥', 'vayaṃ tu harirājaṃ taṃ sugrīvaṃ satyasaṃgaram
paricaryāmahe rājyāt pūrvajenāvaropitam', null, 5033024),
('ramayana-5-33-25', 25, 'Sundara Kanda, Sarga 33, Verse 25', 'ततस्तौ चीरवसनौ धनुःप्रवरपाणिनौ।
ऋश्यमूकस्य शैलस्य रम्यं देशमुपागतौ॥', 'tatas tau cīravasanau dhanuḥpravarapāṇinau
ṛśyamūkasya śailasya ramyaṃ deśam upāgatau', null, 5033025),
('ramayana-5-33-26', 26, 'Sundara Kanda, Sarga 33, Verse 26', 'स तौ दृष्ट्वा नरव्याघ्रौ धन्विनौ वानरर्षभः।
अभिप्लुतो गिरेस्तस्य शिखरं भयमोहितः॥', 'sa tau dṛṣṭvā naravyāghrau dhanvinau vānararṣabhaḥ
abhipluto gires tasya śikharaṃ bhayamohitaḥ', null, 5033026),
('ramayana-5-33-27', 27, 'Sundara Kanda, Sarga 33, Verse 27', 'ततः स शिखरे तस्मिन्वानरेन्द्रो व्यवस्थितः।
तयोः समीपं मामेव प्रेषयामास सत्वरः॥', 'tataḥ sa śikhare tasmin vānarendro vyavasthitaḥ
tayoḥ samīpaṃ mām eva preṣayām āsa satvaraḥ', null, 5033027),
('ramayana-5-33-28', 28, 'Sundara Kanda, Sarga 33, Verse 28', 'तावहं पुरुषव्याघ्रौ सुग्रीववचनात्प्रभू।
रूपलक्षणसंपन्नौ कृताञ्जलिरुपस्थितः॥', 'tāv ahaṃ puruṣavyāghrau sugrīvavacanāt prabhū
rūpalakṣaṇasaṃpannau kṛtāñjalir upasthitaḥ', null, 5033028),
('ramayana-5-33-29', 29, 'Sundara Kanda, Sarga 33, Verse 29', 'तौ परिज्ञाततत्त्वार्थौ मया प्रीतिसमन्वितौ।
पृष्ठमारोप्य तं देशं प्रापितौ पुरुषर्षभौ॥', 'tau parijñātatattvārthau mayā prītisamanvitau
pṛṣṭham āropya taṃ deśaṃ prāpitau puruṣarṣabhau', null, 5033029),
('ramayana-5-33-30', 30, 'Sundara Kanda, Sarga 33, Verse 30', 'निवेदितौ च तत्त्वेन सुग्रीवाय महात्मने।
तयोरन्योन्यसंभाषाद्भृशं प्रीतिरजायत॥', 'niveditau ca tattvena sugrīvāya mahātmane
tayor anyonyasaṃbhāṣād bhṛśaṃ prītir ajāyata', null, 5033030),
('ramayana-5-33-31', 31, 'Sundara Kanda, Sarga 33, Verse 31', 'तत्र तौ कीर्तिसंपन्नौ हरीश्वरनरेश्वरौ।
परस्परकृताश्वासौ कथया पूर्ववृत्तया॥', 'tatra tau kīrtisaṃpannau harīśvaranareśvarau
parasparakṛtāśvāsau kathayā pūrvavṛttayā', null, 5033031),
('ramayana-5-33-32', 32, 'Sundara Kanda, Sarga 33, Verse 32', 'तं ततः सान्त्वयामास सुग्रीवं लक्ष्मणाग्रजः।
स्त्रीहेतोर्वालिना भ्रात्रा निरस्तमुरु तेजसा॥', 'taṃ tataḥ sāntvayām āsa sugrīvaṃ lakṣmaṇāgrajaḥ
strīhetor vālinā bhrātrā nirastam uru tejasā', null, 5033032),
('ramayana-5-33-33', 33, 'Sundara Kanda, Sarga 33, Verse 33', 'ततस्त्वन्नाशजं शोकं रामस्याक्लिष्टकर्मणः।
लक्ष्मणो वानरेन्द्राय सुग्रीवाय न्यवेदयत्॥', 'tatas tvan nāśajaṃ śokaṃ rāmasyākliṣṭakarmaṇaḥ
lakṣmaṇo vānarendrāya sugrīvāya nyavedayat', null, 5033033),
('ramayana-5-33-34', 34, 'Sundara Kanda, Sarga 33, Verse 34', 'स श्रुत्वा वानरेन्द्रस्तु लक्ष्मणेनेरितं वचः।
तदासीन्निष्प्रभोऽत्यर्थं ग्रहग्रस्त इवांशुमान्॥', 'sa śrutvā vānarendras tu lakṣmaṇeneritaṃ vacaḥ
tadāsīn niṣprabho ''tyarthaṃ grahagrasta ivāṃśumān', null, 5033034),
('ramayana-5-33-35', 35, 'Sundara Kanda, Sarga 33, Verse 35', 'ततस्त्वद्गात्रशोभीनि रक्षसा ह्रियमाणया।
यान्याभरणजालानि पातितानि महीतले॥', 'tatas tvadgātraśobhīni rakṣasā hriyamāṇayā
yāny ābharaṇajālāni pātitāni mahītale', null, 5033035),
('ramayana-5-33-36', 36, 'Sundara Kanda, Sarga 33, Verse 36', 'तानि सर्वाणि रामाय आनीय हरियूथपाः।
संहृष्टा दर्शयामासुर्गतिं तु न विदुस्तव॥', 'tāni sarvāṇi rāmāya ānīya hariyūthapāḥ
saṃhṛṣṭā darśayām āsur gatiṃ tu na vidus tava', null, 5033036),
('ramayana-5-33-37', 37, 'Sundara Kanda, Sarga 33, Verse 37', 'तानि रामाय दत्तानि मयैवोपहृतानि च।
स्वनवन्त्यवकीर्णन्ति तस्मिन्विहतचेतसि॥', 'tāni rāmāya dattāni mayaivopahṛtāni ca
svanavanty avakīrṇanti tasmin vihatacetasi', null, 5033037),
('ramayana-5-33-38', 38, 'Sundara Kanda, Sarga 33, Verse 38', 'तान्यङ्के दर्शनीयानि कृत्वा बहुविधं ततः।
तेन देवप्रकाशेन देवेन परिदेवितम्॥', 'tāny aṅke darśanīyāni kṛtvā bahuvidhaṃ tataḥ
tena devaprakāśena devena paridevitam', null, 5033038),
('ramayana-5-33-39', 39, 'Sundara Kanda, Sarga 33, Verse 39', 'पश्यतस्तस्या रुदतस्ताम्यतश्च पुनः पुनः।
प्रादीपयन्दाशरथेस्तानि शोकहुताशनम्॥', 'paśyatas tasyā rudatas tāmyataś ca punaḥ punaḥ
prādīpayan dāśarathes tāni śokahutāśanam', null, 5033039),
('ramayana-5-33-40', 40, 'Sundara Kanda, Sarga 33, Verse 40', 'शयितं च चिरं तेन दुःखार्तेन महात्मना।
मयापि विविधैर्वाक्यैः कृच्छ्रादुत्थापितः पुनः॥', 'śayitaṃ ca ciraṃ tena duḥkhārtena mahātmanā
mayāpi vividhair vākyaiḥ kṛcchrād utthāpitaḥ punaḥ', null, 5033040),
('ramayana-5-33-41', 41, 'Sundara Kanda, Sarga 33, Verse 41', 'तानि दृष्ट्वा महार्हाणि दर्शयित्वा मुहुर्मुहुः।
राघवः सहसौमित्रिः सुग्रीवे स न्यवेदयत्॥', 'tāni dṛṣṭvā mahārhāṇi darśayitvā muhur muhuḥ
rāghavaḥ sahasaumitriḥ sugrīve sa nyavedayat', null, 5033041),
('ramayana-5-33-42', 42, 'Sundara Kanda, Sarga 33, Verse 42', 'स तवादर्शनादार्ये राघवः परितप्यते।
महता ज्वलता नित्यमग्निनेवाग्निपर्वतः॥', 'sa tavādarśanād ārye rāghavaḥ paritapyate
mahatā jvalatā nityam agninevāgniparvataḥ', null, 5033042),
('ramayana-5-33-43', 43, 'Sundara Kanda, Sarga 33, Verse 43', 'त्वत्कृते तमनिद्रा च शोकश्चिन्ता च राघवम्।
तापयन्ति महात्मानमग्न्यगारमिवाग्नयः॥', 'tvatkṛte tam anidrā ca śokaś cintā ca rāghavam
tāpayanti mahātmānam agnyagāram ivāgnayaḥ', null, 5033043),
('ramayana-5-33-44', 44, 'Sundara Kanda, Sarga 33, Verse 44', 'तवादर्शनशोकेन राघवः प्रविचाल्यते।
महता भूमिकम्पेन महानिव शिलोच्चयः॥', 'tavādarśanaśokena rāghavaḥ pravicālyate
mahatā bhūmikampena mahān iva śiloccayaḥ', null, 5033044),
('ramayana-5-33-45', 45, 'Sundara Kanda, Sarga 33, Verse 45', 'कानानानि सुरम्याणि नदीप्रस्रवणानि च।
चरन्न रतिमाप्नोति त्वमपश्यन्नृपात्मजे॥', 'kānānāni suramyāṇi nadīprasravaṇāni ca
caran na ratim āpnoti tvam apaśyan nṛpātmaje', null, 5033045),
('ramayana-5-33-46', 46, 'Sundara Kanda, Sarga 33, Verse 46', 'स त्वां मनुजशार्दूलः क्षिप्रं प्राप्स्यति राघवः।
समित्रबान्धवं हत्वा रावणं जनकात्मजे॥', 'sa tvāṃ manujaśārdūlaḥ kṣipraṃ prāpsyati rāghavaḥ
samitrabāndhavaṃ hatvā rāvaṇaṃ janakātmaje', null, 5033046),
('ramayana-5-33-47', 47, 'Sundara Kanda, Sarga 33, Verse 47', 'सहितौ रामसुग्रीवावुभावकुरुतां तदा।
समयं वालिनं हन्तुं तव चान्वेषणं तथा॥', 'sahitau rāmasugrīvāv ubhāv akurutāṃ tadā
samayaṃ vālinaṃ hantuṃ tava cānveṣaṇaṃ tathā', null, 5033047),
('ramayana-5-33-48', 48, 'Sundara Kanda, Sarga 33, Verse 48', 'ततो निहत्य तरसा रामो वालिनमाहवे।
सर्वर्क्षहरिसंघानां सुग्रीवमकरोत्पतिम्॥', 'tato nihatya tarasā rāmo vālinam āhave
sarvarkṣaharisaṃghānāṃ sugrīvam akarot patim', null, 5033048),
('ramayana-5-33-49', 49, 'Sundara Kanda, Sarga 33, Verse 49', 'रामसुग्रीवयोरैक्यं देव्येवं समजायत।
हनूमन्तं च मां विद्धि तयोर्दूतमिहागतम्॥', 'rāmasugrīvayor aikyaṃ devy evaṃ samajāyata
hanūmantaṃ ca māṃ viddhi tayor dūtam ihāgatam', null, 5033049),
('ramayana-5-33-50', 50, 'Sundara Kanda, Sarga 33, Verse 50', 'स्वराज्यं प्राप्य सुग्रीवः समनीय महाहरीन्।
त्वदर्थं प्रेषयामास दिशो दश महाबलान्॥', 'svarājyaṃ prāpya sugrīvaḥ samanīya mahāharīn
tvadarthaṃ preṣayām āsa diśo daśa mahābalān', null, 5033050),
('ramayana-5-33-51', 51, 'Sundara Kanda, Sarga 33, Verse 51', 'आदिष्टा वानरेन्द्रेण सुग्रीवेण महौजसः।
अद्रिराजप्रतीकाशाः सर्वतः प्रस्थिता महीम्॥', 'ādiṣṭā vānarendreṇa sugrīveṇa mahaujasaḥ
adrirājapratīkāśāḥ sarvataḥ prasthitā mahīm', null, 5033051),
('ramayana-5-33-52', 52, 'Sundara Kanda, Sarga 33, Verse 52', 'अङ्गदो नाम लक्ष्मीवान्वालिसूनुर्महाबलः।
प्रस्थितः कपिशार्दूलस्त्रिभागबलसंवृतः॥', 'aṅgado nāma lakṣmīvān vālisūnur mahābalaḥ
prasthitaḥ kapiśārdūlas tribhāgabalasaṃvṛtaḥ', null, 5033052),
('ramayana-5-33-53', 53, 'Sundara Kanda, Sarga 33, Verse 53', 'तेषां नो विप्रनष्टानां विन्ध्ये पर्वतसत्तमे।
भृशं शोकपरीतनामहोरात्रगणा गताः॥', 'teṣāṃ no vipranaṣṭānāṃ vindhye parvatasattame
bhṛśaṃ śokaparītanām ahorātragaṇā gatāḥ', null, 5033053),
('ramayana-5-33-54', 54, 'Sundara Kanda, Sarga 33, Verse 54', 'ते वयं कार्यनैराश्यात्कालस्यातिक्रमेण च।
भयाच्च कपिराजस्य प्राणांस्त्यक्तुं व्यवस्थिताः॥', 'te vayaṃ kāryanairāśyāt kālasyātikrameṇa ca
bhayāc ca kapirājasya prāṇāṃs tyaktuṃ vyavasthitāḥ', null, 5033054),
('ramayana-5-33-55', 55, 'Sundara Kanda, Sarga 33, Verse 55', 'विचित्य वनदुर्गाणि गिरिप्रस्रवणानि च।
अनासाद्य पदं देव्याः प्राणांस्त्यक्तुं व्यवस्थिताः॥', 'vicitya vanadurgāṇi giriprasravaṇāni ca
anāsādya padaṃ devyāḥ prāṇāṃs tyaktuṃ vyavasthitāḥ', null, 5033055),
('ramayana-5-33-56', 56, 'Sundara Kanda, Sarga 33, Verse 56', 'भृशं शोकार्णवे मग्नः पर्यदेवयदङ्गदः।
तव नाशं च वैदेहि वालिनश्च तथा वधम्।
प्रायोपवेशमस्माकं मरणं च जटायुषः॥', 'bhṛśaṃ śokārṇave magnaḥ paryadevayad aṅgadaḥ
tava nāśaṃ ca vaidehi vālinaś ca tathā vadham
prāyopaveśam asmākaṃ maraṇaṃ ca jaṭāyuṣaḥ', null, 5033056),
('ramayana-5-33-57', 57, 'Sundara Kanda, Sarga 33, Verse 57', 'तेषां नः स्वामिसंदेशान्निराशानां मुमूर्षताम्।
कार्यहेतोरिवायातः शकुनिर्वीर्यवान्महान्॥', 'teṣāṃ naḥ svāmisaṃdeśān nirāśānāṃ mumūrṣatām
kāryahetor ivāyātaḥ śakunir vīryavān mahān', null, 5033057),
('ramayana-5-33-58', 58, 'Sundara Kanda, Sarga 33, Verse 58', 'गृध्रराजस्य सोदर्यः संपातिर्नाम गृध्रराट्।
श्रुत्वा भ्रातृवधं कोपादिदं वचनमब्रवीत्॥', 'gṛdhrarājasya sodaryaḥ saṃpātir nāma gṛdhrarāṭ
śrutvā bhrātṛvadhaṃ kopād idaṃ vacanam abravīt', null, 5033058),
('ramayana-5-33-59', 59, 'Sundara Kanda, Sarga 33, Verse 59', 'यवीयान्केन मे भ्राता हतः क्व च विनाशितः।
एतदाख्यातुमिच्छामि भवद्भिर्वानरोत्तमाः॥', 'yavīyān kena me bhrātā hataḥ kva ca vināśitaḥ
etad ākhyātum icchāmi bhavadbhir vānarottamāḥ', null, 5033059),
('ramayana-5-33-60', 60, 'Sundara Kanda, Sarga 33, Verse 60', 'अङ्गदोऽकथयत्तस्य जनस्थाने महद्वधम्।
रक्षसा भीमरूपेण त्वामुद्दिश्य यथातथम्॥', 'aṅgado ''kathayat tasya janasthāne mahad vadham
rakṣasā bhīmarūpeṇa tvām uddiśya yathātatham', null, 5033060),
('ramayana-5-33-61', 61, 'Sundara Kanda, Sarga 33, Verse 61', 'जटायोस्तु वधं श्रुत्वा दुःखितः सोऽरुणात्मजः।
त्वामाह स वरारोहे वसन्तीं रावणालये॥', 'jaṭāyos tu vadhaṃ śrutvā duḥkhitaḥ so ''ruṇātmajaḥ
tvām āha sa varārohe vasantīṃ rāvaṇālaye', null, 5033061),
('ramayana-5-33-62', 62, 'Sundara Kanda, Sarga 33, Verse 62', 'तस्य तद्वचनं श्रुत्वा संपातेः प्रीतिवर्धनम्।
अङ्गदप्रमुखाः सर्वे ततः संप्रस्थिता वयम्।
त्वद्दर्शनकृतोत्साहा हृष्टास्तुष्टाः प्लवंगमाः॥', 'tasya tad vacanaṃ śrutvā saṃpāteḥ prītivardhanam
aṅgadapramukhāḥ sarve tataḥ saṃprasthitā vayam
tvaddarśanakṛtotsāhā hṛṣṭās tuṣṭāḥ plavaṃgamāḥ', null, 5033062),
('ramayana-5-33-63', 63, 'Sundara Kanda, Sarga 33, Verse 63', 'अथाहं हरिसैन्यस्य सागरं दृश्य सीदतः।
व्यवधूय भयं तीव्रं योजनानां शतं प्लुतः॥', 'athāhaṃ harisainyasya sāgaraṃ dṛśya sīdataḥ
vyavadhūya bhayaṃ tīvraṃ yojanānāṃ śataṃ plutaḥ', null, 5033063),
('ramayana-5-33-64', 64, 'Sundara Kanda, Sarga 33, Verse 64', 'लङ्का चापि मया रात्रौ प्रविष्टा राक्षसाकुला।
रावणश्च मया दृष्टस्त्वं च शोकनिपीडिता॥', 'laṅkā cāpi mayā rātrau praviṣṭā rākṣasākulā
rāvaṇaś ca mayā dṛṣṭas tvaṃ ca śokanipīḍitā', null, 5033064),
('ramayana-5-33-65', 65, 'Sundara Kanda, Sarga 33, Verse 65', 'एतत्ते सर्वमाख्यातं यथावृत्तमनिन्दिते।
अभिभाषस्व मां देवि दूतो दाशरथेरहम्॥', 'etat te sarvam ākhyātaṃ yathāvṛttam anindite
abhibhāṣasva māṃ devi dūto dāśarather aham', null, 5033065),
('ramayana-5-33-66', 66, 'Sundara Kanda, Sarga 33, Verse 66', 'त्वं मां रामकृतोद्योगं त्वन्निमित्तमिहागतम्।
सुग्रीव सचिवं देवि बुध्यस्व पवनात्मजम्॥', 'tvaṃ māṃ rāmakṛtodyogaṃ tvannimittam ihāgatam
sugrīva sacivaṃ devi budhyasva pavanātmajam', null, 5033066),
('ramayana-5-33-67', 67, 'Sundara Kanda, Sarga 33, Verse 67', 'कुशली तव काकुत्स्थः सर्वशस्त्रभृतां वरः।
गुरोराराधने युक्तो लक्ष्मणश्च सुलक्षणः॥', 'kuśalī tava kākutsthaḥ sarvaśastrabhṛtāṃ varaḥ
guror ārādhane yukto lakṣmaṇaś ca sulakṣaṇaḥ', null, 5033067),
('ramayana-5-33-68', 68, 'Sundara Kanda, Sarga 33, Verse 68', 'तस्य वीर्यवतो देवि भर्तुस्तव हिते रतः।
अहमेकस्तु संप्राप्तः सुग्रीववचनादिह॥', 'tasya vīryavato devi bhartus tava hite rataḥ
aham ekas tu saṃprāptaḥ sugrīvavacanād iha', null, 5033068),
('ramayana-5-33-69', 69, 'Sundara Kanda, Sarga 33, Verse 69', 'मयेयमसहायेन चरता कामरूपिणा।
दक्षिणा दिगनुक्रान्ता त्वन्मार्गविचयैषिणा॥', 'mayeyam asahāyena caratā kāmarūpiṇā
dakṣiṇā dig anukrāntā tvanmārgavicayaiṣiṇā', null, 5033069),
('ramayana-5-33-70', 70, 'Sundara Kanda, Sarga 33, Verse 70', 'दिष्ट्याहं हरिसैन्यानां त्वन्नाशमनुशोचताम्।
अपनेष्यामि संतापं तवाभिगमशंसनात्॥', 'diṣṭyāhaṃ harisainyānāṃ tvannāśam anuśocatām
apaneṣyāmi saṃtāpaṃ tavābhigamaśaṃsanāt', null, 5033070),
('ramayana-5-33-71', 71, 'Sundara Kanda, Sarga 33, Verse 71', 'दिष्ट्या हि न मम व्यर्थं देवि सागरलङ्घनम्।
प्राप्स्याम्यहमिदं दिष्ट्या त्वद्दर्शनकृतं यशः॥', 'diṣṭyā hi na mama vyarthaṃ devi sāgaralaṅghanam
prāpsyāmy aham idaṃ diṣṭyā tvaddarśanakṛtaṃ yaśaḥ', null, 5033071),
('ramayana-5-33-72', 72, 'Sundara Kanda, Sarga 33, Verse 72', 'राघवश्च महावीर्यः क्षिप्रं त्वामभिपत्स्यते।
समित्रबान्धवं हत्वा रावणं राक्षसाधिपम्॥', 'rāghavaś ca mahāvīryaḥ kṣipraṃ tvām abhipatsyate
samitrabāndhavaṃ hatvā rāvaṇaṃ rākṣasādhipam', null, 5033072),
('ramayana-5-33-73', 73, 'Sundara Kanda, Sarga 33, Verse 73', 'कौरजो नाम वैदेहि गिरीणामुत्तमो गिरिः।
ततो गच्छति गोकर्णं पर्वतं केसरी हरिः॥', 'kaurajo nāma vaidehi girīṇām uttamo giriḥ
tato gacchati gokarṇaṃ parvataṃ kesarī hariḥ', null, 5033073),
('ramayana-5-33-74', 74, 'Sundara Kanda, Sarga 33, Verse 74', 'स च देवर्षिभिर्दृष्टः पिता मम महाकपिः।
तीर्थे नदीपतेः पुण्ये शम्बसादनमुद्धरत्॥', 'sa ca devarṣibhir dṛṣṭaḥ pitā mama mahākapiḥ
tīrthe nadīpateḥ puṇye śambasādanam uddharat', null, 5033074),
('ramayana-5-33-75', 75, 'Sundara Kanda, Sarga 33, Verse 75', 'तस्याहं हरिणः क्षेत्रे जातो वातेन मैथिलि।
हनूमानिति विख्यातो लोके स्वेनैव कर्मणा।
विश्वासार्थं तु वैदेहि भर्तुरुक्ता मया गुणाः॥', 'tasyāhaṃ hariṇaḥ kṣetre jāto vātena maithili
hanūmān iti vikhyāto loke svenaiva karmaṇā
viśvāsārthaṃ tu vaidehi bhartur uktā mayā guṇāḥ', null, 5033075),
('ramayana-5-33-76', 76, 'Sundara Kanda, Sarga 33, Verse 76', 'एवं विश्वासिता सीता हेतुभिः शोककर्शिता।
उपपन्नैरभिज्ञानैर्दूतं तमवगच्छति॥', 'evaṃ viśvāsitā sītā hetubhiḥ śokakarśitā
upapannair abhijñānair dūtaṃ tam avagacchati', null, 5033076),
('ramayana-5-33-77', 77, 'Sundara Kanda, Sarga 33, Verse 77', 'अतुलं च गता हर्षं प्रहर्षेण तु जानकी।
नेत्राभ्यां वक्रपक्ष्माभ्यां मुमोचानन्दजं जलम्॥', 'atulaṃ ca gatā harṣaṃ praharṣeṇa tu jānakī
netrābhyāṃ vakrapakṣmābhyāṃ mumocānandajaṃ jalam', null, 5033077),
('ramayana-5-33-78', 78, 'Sundara Kanda, Sarga 33, Verse 78', 'चारु तच्चाननं तस्यास्ताम्रशुक्लायतेक्षणम्।
अशोभत विशालाक्ष्या राहुमुक्त इवोडुराट्।
हनूमन्तं कपिं व्यक्तं मन्यते नान्यथेति सा॥', 'cāru tac cānanaṃ tasyās tāmraśuklāyatekṣaṇam
aśobhata viśālākṣyā rāhumukta ivoḍurāṭ
hanūmantaṃ kapiṃ vyaktaṃ manyate nānyatheti sā', null, 5033078),
('ramayana-5-33-79', 79, 'Sundara Kanda, Sarga 33, Verse 79', 'अथोवाच हनूमांस्तामुत्तरं प्रियदर्शनाम्॥', 'athovāca hanūmāṃs tām uttaraṃ priyadarśanām', null, 5033079),
('ramayana-5-33-80', 80, 'Sundara Kanda, Sarga 33, Verse 80', 'हतेऽसुरे संयति शम्बसादने कपिप्रवीरेण महर्षिचोदनात्।
ततोऽस्मि वायुप्रभवो हि मैथिलि प्रभावतस्तत्प्रतिमश्च वानरः॥', 'hate ''sure saṃyati śambasādane kapipravīreṇa maharṣicodanāt
tato ''smi vāyuprabhavo hi maithili prabhāvatas tatpratimaś ca vānaraḥ', null, 5033080)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 34 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-34-1', 1, 'Sundara Kanda, Sarga 34, Verse 1', 'भूय एव महातेजा हनूमान्मारुतात्मजः।
अब्रवीत्प्रश्रितं वाक्यं सीताप्रत्ययकारणात्॥', 'bhūya eva mahātejā hanūmān mārutātmajaḥ
abravīt praśritaṃ vākyaṃ sītāpratyayakāraṇāt', null, 5034001),
('ramayana-5-34-2', 2, 'Sundara Kanda, Sarga 34, Verse 2', 'वानरोऽहं महाभागे दूतो रामस्य धीमतः।
रामनामाङ्कितं चेदं पश्य देव्यङ्गुलीयकम्।
समाश्वसिहि भद्रं ते क्षीणदुःखफला ह्यसि॥', 'vānaro ''haṃ mahābhāge dūto rāmasya dhīmataḥ
rāmanāmāṅkitaṃ cedaṃ paśya devy aṅgulīyakam
samāśvasihi bhadraṃ te kṣīṇaduḥkhaphalā hy asi', null, 5034002),
('ramayana-5-34-3', 3, 'Sundara Kanda, Sarga 34, Verse 3', 'गृहीत्वा प्रेक्षमाणा सा भर्तुः करविभूषणम्।
भर्तारमिव संप्राप्ता जानकी मुदिताभवत्॥', 'gṛhītvā prekṣamāṇā sā bhartuḥ karavibhūṣaṇam
bhartāram iva saṃprāptā jānakī muditābhavat', null, 5034003),
('ramayana-5-34-4', 4, 'Sundara Kanda, Sarga 34, Verse 4', 'चारु तद्वदनं तस्यास्ताम्रशुक्लायतेक्षणम्।
बभूव प्रहर्षोदग्रं राहुमुक्त इवोडुराट्॥', 'cāru tad vadanaṃ tasyās tāmraśuklāyatekṣaṇam
babhūva praharṣodagraṃ rāhumukta ivoḍurāṭ', null, 5034004),
('ramayana-5-34-5', 5, 'Sundara Kanda, Sarga 34, Verse 5', 'ततः सा ह्रीमती बाला भर्तुः संदेशहर्षिता।
परितुट्षा प्रियं श्रुत्वा प्राशंसत महाकपिम्॥', 'tataḥ sā hrīmatī bālā bhartuḥ saṃdeśaharṣitā
parituṭṣā priyaṃ śrutvā prāśaṃsata mahākapim', null, 5034005),
('ramayana-5-34-6', 6, 'Sundara Kanda, Sarga 34, Verse 6', 'विक्रान्तस्त्वं समर्थस्त्वं प्राज्ञस्त्वं वानरोत्तम।
येनेदं राक्षसपदं त्वयैकेन प्रधर्षितम्॥', 'vikrāntas tvaṃ samarthas tvaṃ prājñas tvaṃ vānarottama
yenedaṃ rākṣasapadaṃ tvayaikena pradharṣitam', null, 5034006),
('ramayana-5-34-7', 7, 'Sundara Kanda, Sarga 34, Verse 7', 'शतयोजनविस्तीर्णः सागरो मकरालयः।
विक्रमश्लाघनीयेन क्रमता गोष्पदीकृतः॥', 'śatayojanavistīrṇaḥ sāgaro makarālayaḥ
vikramaślāghanīyena kramatā goṣpadīkṛtaḥ', null, 5034007),
('ramayana-5-34-8', 8, 'Sundara Kanda, Sarga 34, Verse 8', 'न हि त्वां प्राकृतं मन्ये वनरं वनरर्षभ।
यस्य ते नास्ति संत्रासो रावणान्नापि संभ्रमः॥', 'na hi tvāṃ prākṛtaṃ manye vanaraṃ vanararṣabha
yasya te nāsti saṃtrāso rāvaṇān nāpi saṃbhramaḥ', null, 5034008),
('ramayana-5-34-9', 9, 'Sundara Kanda, Sarga 34, Verse 9', 'अर्हसे च कपिश्रेष्ठ मया समभिभाषितुम्।
यद्यसि प्रेषितस्तेन रामेण विदितात्मना॥', 'arhase ca kapiśreṣṭha mayā samabhibhāṣitum
yady asi preṣitas tena rāmeṇa viditātmanā', null, 5034009),
('ramayana-5-34-10', 10, 'Sundara Kanda, Sarga 34, Verse 10', 'प्रेषयिष्यति दुर्धर्षो रामो न ह्यपरीक्षितम्।
पराक्रममविज्ञाय मत्सकाशं विशेषतः॥', 'preṣayiṣyati durdharṣo rāmo na hy aparīkṣitam
parākramam avijñāya matsakāśaṃ viśeṣataḥ', null, 5034010),
('ramayana-5-34-11', 11, 'Sundara Kanda, Sarga 34, Verse 11', 'दिष्ट्या च कुशली रामो धर्मात्मा धर्मवत्सलः।
लक्ष्मणश्च महातेजाः सुमित्रानन्दवर्धनः॥', 'diṣṭyā ca kuśalī rāmo dharmātmā dharmavatsalaḥ
lakṣmaṇaś ca mahātejāḥ sumitrānandavardhanaḥ', null, 5034011),
('ramayana-5-34-12', 12, 'Sundara Kanda, Sarga 34, Verse 12', 'कुशली यदि काकुत्स्थः किं नु सागरमेखलाम्।
महीं दहति कोपेन युगान्ताग्निरिवोत्थितः॥', 'kuśalī yadi kākutsthaḥ kiṃ nu sāgaramekhalām
mahīṃ dahati kopena yugāntāgnir ivotthitaḥ', null, 5034012),
('ramayana-5-34-13', 13, 'Sundara Kanda, Sarga 34, Verse 13', 'अथ वा शक्तिमन्तौ तौ सुराणामपि निग्रहे।
ममैव तु न दुःखानामस्ति मन्ये विपर्ययः॥', 'atha vā śaktimantau tau surāṇām api nigrahe
mamaiva tu na duḥkhānām asti manye viparyayaḥ', null, 5034013),
('ramayana-5-34-14', 14, 'Sundara Kanda, Sarga 34, Verse 14', 'कच्चिच्च व्यथते रामः कच्चिन्न परिपत्यते।
उत्तराणि च कार्याणि कुरुते पुरुषोत्तमः॥', 'kaccic ca vyathate rāmaḥ kaccin na paripatyate
uttarāṇi ca kāryāṇi kurute puruṣottamaḥ', null, 5034014),
('ramayana-5-34-15', 15, 'Sundara Kanda, Sarga 34, Verse 15', 'कच्चिन्न दीनः संभ्रान्तः कार्येषु च न मुह्यति।
कच्चिन्पुरुषकार्याणि कुरुते नृपतेः सुतः॥', 'kaccin na dīnaḥ saṃbhrāntaḥ kāryeṣu ca na muhyati
kaccin puruṣakāryāṇi kurute nṛpateḥ sutaḥ', null, 5034015),
('ramayana-5-34-16', 16, 'Sundara Kanda, Sarga 34, Verse 16', 'द्विविधं त्रिविधोपायमुपायमपि सेवते।
विजिगीषुः सुहृत्कच्चिन्मित्रेषु च परंतपः॥', 'dvividhaṃ trividhopāyam upāyam api sevate
vijigīṣuḥ suhṛt kaccin mitreṣu ca paraṃtapaḥ', null, 5034016),
('ramayana-5-34-17', 17, 'Sundara Kanda, Sarga 34, Verse 17', 'कच्चिन्मित्राणि लभते मित्रैश्चाप्यभिगम्यते।
कच्चित्कल्याणमित्रश्च मित्रैश्चापि पुरस्कृतः॥', 'kaccin mitrāṇi labhate mitraiś cāpy abhigamyate
kaccit kalyāṇamitraś ca mitraiś cāpi puraskṛtaḥ', null, 5034017),
('ramayana-5-34-18', 18, 'Sundara Kanda, Sarga 34, Verse 18', 'कच्चिदाशास्ति देवानां प्रसादं पार्थिवात्मजः।
कच्चित्पुरुषकारं च दैवं च प्रतिपद्यते॥', 'kaccid āśāsti devānāṃ prasādaṃ pārthivātmajaḥ
kaccit puruṣakāraṃ ca daivaṃ ca pratipadyate', null, 5034018),
('ramayana-5-34-19', 19, 'Sundara Kanda, Sarga 34, Verse 19', 'कच्चिन्न विगतस्नेहो विवासान्मयि राघवः।
कच्चिन्मां व्यसनादस्मान्मोक्षयिष्यति वानरः॥', 'kaccin na vigatasneho vivāsān mayi rāghavaḥ
kaccin māṃ vyasanād asmān mokṣayiṣyati vānaraḥ', null, 5034019),
('ramayana-5-34-20', 20, 'Sundara Kanda, Sarga 34, Verse 20', 'सुखानामुचितो नित्यमसुखानामनूचितः।
दुःखमुत्तरमासाद्य कच्चिद्रामो न सीदति॥', 'sukhānām ucito nityam asukhānām anūcitaḥ
duḥkham uttaram āsādya kaccid rāmo na sīdati', null, 5034020),
('ramayana-5-34-21', 21, 'Sundara Kanda, Sarga 34, Verse 21', 'कौसल्यायास्तथा कच्चित्सुमित्रायास्तथैव च।
अभीक्ष्णं श्रूयते कच्चित्कुशलं भरतस्य च॥', 'kausalyāyās tathā kaccit sumitrāyās tathaiva ca
abhīkṣṇaṃ śrūyate kaccit kuśalaṃ bharatasya ca', null, 5034021),
('ramayana-5-34-22', 22, 'Sundara Kanda, Sarga 34, Verse 22', 'मन्निमित्तेन मानार्हः कच्चिच्छोकेन राघवः।
कच्चिन्नान्यमना रामः कच्चिन्मां तारयिष्यति॥', 'mannimittena mānārhaḥ kaccic chokena rāghavaḥ
kaccin nānyamanā rāmaḥ kaccin māṃ tārayiṣyati', null, 5034022),
('ramayana-5-34-23', 23, 'Sundara Kanda, Sarga 34, Verse 23', 'कच्चिदक्षौहिणीं भीमां भरतो भ्रातृवत्सलः।
ध्वजिनीं मन्त्रिभिर्गुप्तां प्रेषयिष्यति मत्कृते॥', 'kaccid akṣauhiṇīṃ bhīmāṃ bharato bhrātṛvatsalaḥ
dhvajinīṃ mantribhir guptāṃ preṣayiṣyati matkṛte', null, 5034023),
('ramayana-5-34-24', 24, 'Sundara Kanda, Sarga 34, Verse 24', 'वानराधिपतिः श्रीमान्सुग्रीवः कच्चिदेष्यति।
मत्कृते हरिभिर्वीरैर्वृतो दन्तनखायुधैः॥', 'vānarādhipatiḥ śrīmān sugrīvaḥ kaccid eṣyati
matkṛte haribhir vīrair vṛto dantanakhāyudhaiḥ', null, 5034024),
('ramayana-5-34-25', 25, 'Sundara Kanda, Sarga 34, Verse 25', 'कच्चिच्च लक्ष्मणः शूरः सुमित्रानन्दवर्धनः।
अस्त्रविच्छरजालेन राक्षसान्विधमिष्यति॥', 'kaccic ca lakṣmaṇaḥ śūraḥ sumitrānandavardhanaḥ
astravic charajālena rākṣasān vidhamiṣyati', null, 5034025),
('ramayana-5-34-26', 26, 'Sundara Kanda, Sarga 34, Verse 26', 'रौद्रेण कच्चिदस्त्रेण रामेण निहतं रणे।
द्रक्ष्याम्यल्पेन कालेन रावणं ससुहृज्जनम्॥', 'raudreṇa kaccid astreṇa rāmeṇa nihataṃ raṇe
drakṣyāmy alpena kālena rāvaṇaṃ sasuhṛjjanam', null, 5034026),
('ramayana-5-34-27', 27, 'Sundara Kanda, Sarga 34, Verse 27', 'कच्चिन्न तद्धेमसमानवर्णं तस्याननं पद्मसमानगन्धि।
मया विना शुष्यति शोकदीनं जलक्षये पद्ममिवातपेन॥', 'kaccin na tad dhemasamānavarṇaṃ tasyānanaṃ padmasamānagandhi
mayā vinā śuṣyati śokadīnaṃ jalakṣaye padmam ivātapena', null, 5034027),
('ramayana-5-34-28', 28, 'Sundara Kanda, Sarga 34, Verse 28', 'धर्मापदेशात्त्यजतश्च राज्यां मां चाप्यरण्यं नयतः पदातिम्।
नासीद्व्यथा यस्य न भीर्न शोकः कच्चित्स धैर्यं हृदये करोति॥', 'dharmāpadeśāt tyajataś ca rājyāṃ māṃ cāpy araṇyaṃ nayataḥ padātim
nāsīd vyathā yasya na bhīr na śokaḥ kaccit sa dhairyaṃ hṛdaye karoti', null, 5034028),
('ramayana-5-34-29', 29, 'Sundara Kanda, Sarga 34, Verse 29', 'न चास्य माता न पिता न चान्यः स्नेहाद्विशिष्टोऽस्ति मया समो वा।
तावद्ध्यहं दूतजिजीविषेयं यावत्प्रवृत्तिं शृणुयां प्रियस्य॥', 'na cāsya mātā na pitā na cānyaḥ snehād viśiṣṭo ''sti mayā samo vā
tāvad dhy ahaṃ dūtajijīviṣeyaṃ yāvat pravṛttiṃ śṛṇuyāṃ priyasya', null, 5034029),
('ramayana-5-34-30', 30, 'Sundara Kanda, Sarga 34, Verse 30', 'इतीव देवी वचनं महार्थं तं वानरेन्द्रं मधुरार्थमुक्त्वा।
श्रोतुं पुनस्तस्य वचोऽभिरामं रामार्थयुक्तं विरराम रामा॥', 'itīva devī vacanaṃ mahārthaṃ taṃ vānarendraṃ madhurārtham uktvā
śrotuṃ punas tasya vaco ''bhirāmaṃ rāmārthayuktaṃ virarāma rāmā', null, 5034030),
('ramayana-5-34-31', 31, 'Sundara Kanda, Sarga 34, Verse 31', 'सीताया वचनं श्रुत्वा मारुतिर्भीमविक्रमः।
शिरस्यञ्जलिमाधाय वाक्यमुत्तरमब्रवीत्॥', 'sītāyā vacanaṃ śrutvā mārutir bhīmavikramaḥ
śirasy añjalim ādhāya vākyam uttaram abravīt', null, 5034031),
('ramayana-5-34-32', 32, 'Sundara Kanda, Sarga 34, Verse 32', 'न त्वामिहस्थां जानीते रामः कमललोचनः।
श्रुत्वैव तु वचो मह्यं क्षिप्रमेष्यति राघवः॥', 'na tvām ihasthāṃ jānīte rāmaḥ kamalalocanaḥ
śrutvaiva tu vaco mahyaṃ kṣipram eṣyati rāghavaḥ', null, 5034032),
('ramayana-5-34-33', 33, 'Sundara Kanda, Sarga 34, Verse 33', 'चमूं प्रकर्षन्महतीं हर्यृष्कगणसंकुलाम्।
विष्टम्भयित्वा बाणौघैरक्षोभ्यं वरुणालयम्।
करिष्यति पुरीं लङ्कां काकुत्स्थः शान्तराक्षसाम्॥', 'camūṃ prakarṣan mahatīṃ haryṛṣkagaṇasaṃkulām
viṣṭambhayitvā bāṇaughair akṣobhyaṃ varuṇālayam
kariṣyati purīṃ laṅkāṃ kākutsthaḥ śāntarākṣasām', null, 5034033),
('ramayana-5-34-34', 34, 'Sundara Kanda, Sarga 34, Verse 34', 'तत्र यद्यन्तरा मृत्युर्यदि देवाः सहासुराः।
स्थास्यन्ति पथि रामस्य स तानपि वधिष्यति॥', 'tatra yady antarā mṛtyur yadi devāḥ sahāsurāḥ
sthāsyanti pathi rāmasya sa tān api vadhiṣyati', null, 5034034),
('ramayana-5-34-35', 35, 'Sundara Kanda, Sarga 34, Verse 35', 'तवादर्शनजेनार्ये शोकेन स परिप्लुतः।
न शर्म लभते रामः सिंहार्दित इव द्विपः॥', 'tavādarśanajenārye śokena sa pariplutaḥ
na śarma labhate rāmaḥ siṃhārdita iva dvipaḥ', null, 5034035),
('ramayana-5-34-36', 36, 'Sundara Kanda, Sarga 34, Verse 36', 'दर्दरेण च ते देवि शपे मूलफलेन च।
मलयेन च विन्ध्येन मेरुणा मन्दरेण च॥', 'dardareṇa ca te devi śape mūlaphalena ca
malayena ca vindhyena meruṇā mandareṇa ca', null, 5034036),
('ramayana-5-34-37', 37, 'Sundara Kanda, Sarga 34, Verse 37', 'यथा सुनयनं वल्गु बिम्बौष्ठं चारुकुण्डलम्।
मुखं द्रक्ष्यसि रामस्य पूर्णचन्द्रमिवोदितम्॥', 'yathā sunayanaṃ valgu bimbauṣṭhaṃ cārukuṇḍalam
mukhaṃ drakṣyasi rāmasya pūrṇacandram ivoditam', null, 5034037),
('ramayana-5-34-38', 38, 'Sundara Kanda, Sarga 34, Verse 38', 'क्षिप्रं द्रक्ष्यसि वैदेहि रामं प्रस्रवणे गिरौ।
शतक्रतुमिवासीनं नाकपृष्ठस्य मूर्धनि॥', 'kṣipraṃ drakṣyasi vaidehi rāmaṃ prasravaṇe girau
śatakratum ivāsīnaṃ nākapṛṣṭhasya mūrdhani', null, 5034038),
('ramayana-5-34-39', 39, 'Sundara Kanda, Sarga 34, Verse 39', 'न मांसं राघवो भुङ्क्ते न चापि मधुसेवते।
वन्यं सुविहितं नित्यं भक्तमश्नाति पञ्चमम्॥', 'na māṃsaṃ rāghavo bhuṅkte na cāpi madhusevate
vanyaṃ suvihitaṃ nityaṃ bhaktam aśnāti pañcamam', null, 5034039),
('ramayana-5-34-40', 40, 'Sundara Kanda, Sarga 34, Verse 40', 'नैव दंशान्न मशकान्न कीटान्न सरीसृपान्।
राघवोऽपनयेद्गत्रात्त्वद्गतेनान्तरात्मना॥', 'naiva daṃśān na maśakān na kīṭān na sarīsṛpān
rāghavo ''panayed gatrāt tvadgatenāntarātmanā', null, 5034040),
('ramayana-5-34-41', 41, 'Sundara Kanda, Sarga 34, Verse 41', 'नित्यं ध्यानपरो रामो नित्यं शोकपरायणः।
नान्यच्चिन्तयते किं चित्स तु कामवशं गतः॥', 'nityaṃ dhyānaparo rāmo nityaṃ śokaparāyaṇaḥ
nānyac cintayate kiṃ cit sa tu kāmavaśaṃ gataḥ', null, 5034041),
('ramayana-5-34-42', 42, 'Sundara Kanda, Sarga 34, Verse 42', 'अनिद्रः सततं रामः सुप्तोऽपि च नरोत्तमः।
सीतेति मधुरां वाणीं व्याहरन्प्रतिबुध्यते॥', 'anidraḥ satataṃ rāmaḥ supto ''pi ca narottamaḥ
sīteti madhurāṃ vāṇīṃ vyāharan pratibudhyate', null, 5034042),
('ramayana-5-34-43', 43, 'Sundara Kanda, Sarga 34, Verse 43', 'दृष्ट्वा फलं वा पुष्पं वा यच्चान्यत्स्त्रीमनोहरम्।
बहुशो हा प्रियेत्येवं श्वसंस्त्वामभिभाषते॥', 'dṛṣṭvā phalaṃ vā puṣpaṃ vā yac cānyat strīmanoharam
bahuśo hā priyety evaṃ śvasaṃs tvām abhibhāṣate', null, 5034043),
('ramayana-5-34-44', 44, 'Sundara Kanda, Sarga 34, Verse 44', 'स देवि नित्यं परितप्यमानस्त्वामेव सीतेत्यभिभाषमाणः।
धृतव्रतो राजसुतो महात्मा तवैव लाभाय कृतप्रयत्नः॥', 'sa devi nityaṃ paritapyamānas tvām eva sītety abhibhāṣamāṇaḥ
dhṛtavrato rājasuto mahātmā tavaiva lābhāya kṛtaprayatnaḥ', null, 5034044),
('ramayana-5-34-45', 45, 'Sundara Kanda, Sarga 34, Verse 45', 'सा रामसंकीर्तनवीतशोका रामस्य शोकेन समानशोका।
शरन्मुखेनाम्बुदशेषचन्द्रा निशेव वैदेहसुता बभूव॥', 'sā rāmasaṃkīrtanavītaśokā rāmasya śokena samānaśokā
śaranmukhenāmbudaśeṣacandrā niśeva vaidehasutā babhūva', null, 5034045)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 35 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-35-1', 1, 'Sundara Kanda, Sarga 35, Verse 1', 'सीता तद्वचनं श्रुत्वा पूर्णचन्द्रनिभानना।
हनूमन्तमुवाचेदं धर्मार्थसहितं वचः॥', 'sītā tad vacanaṃ śrutvā pūrṇacandranibhānanā
hanūmantam uvācedaṃ dharmārthasahitaṃ vacaḥ', null, 5035001),
('ramayana-5-35-2', 2, 'Sundara Kanda, Sarga 35, Verse 2', 'अमृतं विषसंसृष्टं त्वया वानरभाषितम्।
यच्च नान्यमना रामो यच्च शोकपरायणः॥', 'amṛtaṃ viṣasaṃsṛṣṭaṃ tvayā vānarabhāṣitam
yac ca nānyamanā rāmo yac ca śokaparāyaṇaḥ', null, 5035002),
('ramayana-5-35-3', 3, 'Sundara Kanda, Sarga 35, Verse 3', 'ऐश्वर्ये वा सुविस्तीर्णे व्यसने वा सुदारुणे।
रज्ज्वेव पुरुषं बद्ध्वा कृतान्तः परिकर्षति॥', 'aiśvarye vā suvistīrṇe vyasane vā sudāruṇe
rajjveva puruṣaṃ baddhvā kṛtāntaḥ parikarṣati', null, 5035003),
('ramayana-5-35-4', 4, 'Sundara Kanda, Sarga 35, Verse 4', 'विधिर्नूनमसंहार्यः प्राणिनां प्लवगोत्तम।
सौमित्रिं मां च रामं च व्यसनैः पश्य मोहितान्॥', 'vidhir nūnam asaṃhāryaḥ prāṇināṃ plavagottama
saumitriṃ māṃ ca rāmaṃ ca vyasanaiḥ paśya mohitān', null, 5035004),
('ramayana-5-35-5', 5, 'Sundara Kanda, Sarga 35, Verse 5', 'शोकस्यास्य कदा पारं राघवोऽधिगमिष्यति।
प्लवमानः परिश्रान्तो हतनौः सागरे यथा॥', 'śokasyāsya kadā pāraṃ rāghavo ''dhigamiṣyati
plavamānaḥ pariśrānto hatanauḥ sāgare yathā', null, 5035005),
('ramayana-5-35-6', 6, 'Sundara Kanda, Sarga 35, Verse 6', 'राक्षसानां क्षयं कृत्वा सूदयित्वा च रावणम्।
लङ्कामुन्मूलितां कृत्वा कदा द्रक्ष्यति मां पतिः॥', 'rākṣasānāṃ kṣayaṃ kṛtvā sūdayitvā ca rāvaṇam
laṅkām unmūlitāṃ kṛtvā kadā drakṣyati māṃ patiḥ', null, 5035006),
('ramayana-5-35-7', 7, 'Sundara Kanda, Sarga 35, Verse 7', 'स वाच्यः संत्वरस्वेति यावदेव न पूर्यते।
अयं संवत्सरः कालस्तावद्धि मम जीवितम्॥', 'sa vācyaḥ saṃtvarasveti yāvad eva na pūryate
ayaṃ saṃvatsaraḥ kālas tāvad dhi mama jīvitam', null, 5035007),
('ramayana-5-35-8', 8, 'Sundara Kanda, Sarga 35, Verse 8', 'वर्तते दशमो मासो द्वौ तु शेषौ प्लवंगम।
रावणेन नृशंसेन समयो यः कृतो मम॥', 'vartate daśamo māso dvau tu śeṣau plavaṃgama
rāvaṇena nṛśaṃsena samayo yaḥ kṛto mama', null, 5035008),
('ramayana-5-35-9', 9, 'Sundara Kanda, Sarga 35, Verse 9', 'विभीषणेन च भ्रात्रा मम निर्यातनं प्रति।
अनुनीतः प्रयत्नेन न च तत्कुरुते मतिम्॥', 'vibhīṣaṇena ca bhrātrā mama niryātanaṃ prati
anunītaḥ prayatnena na ca tat kurute matim', null, 5035009),
('ramayana-5-35-10', 10, 'Sundara Kanda, Sarga 35, Verse 10', 'मम प्रतिप्रदानं हि रावणस्य न रोचते।
रावणं मार्गते संख्ये मृत्युः कालवशं गतम्॥', 'mama pratipradānaṃ hi rāvaṇasya na rocate
rāvaṇaṃ mārgate saṃkhye mṛtyuḥ kālavaśaṃ gatam', null, 5035010),
('ramayana-5-35-11', 11, 'Sundara Kanda, Sarga 35, Verse 11', 'ज्येष्ठा कन्यानला नम विभीषणसुता कपे।
तया ममैतदाख्यातं मात्रा प्रहितया स्वयम्॥', 'jyeṣṭhā kanyānalā nama vibhīṣaṇasutā kape
tayā mamaitad ākhyātaṃ mātrā prahitayā svayam', null, 5035011),
('ramayana-5-35-12', 12, 'Sundara Kanda, Sarga 35, Verse 12', 'अविन्ध्यो नाम मेधावी विद्वान्राक्षसपुंगवः।
धृतिमाञ्शीलवान्वृद्धो रावणस्य सुसंमतः॥', 'avindhyo nāma medhāvī vidvān rākṣasapuṃgavaḥ
dhṛtimāñ śīlavān vṛddho rāvaṇasya susaṃmataḥ', null, 5035012),
('ramayana-5-35-13', 13, 'Sundara Kanda, Sarga 35, Verse 13', 'रामात्क्षयमनुप्राप्तं रक्षसां प्रत्यचोदयत्।
न च तस्यापि दुष्टात्मा शृणोति वचनं हितम्॥', 'rāmāt kṣayam anuprāptaṃ rakṣasāṃ pratyacodayat
na ca tasyāpi duṣṭātmā śṛṇoti vacanaṃ hitam', null, 5035013),
('ramayana-5-35-14', 14, 'Sundara Kanda, Sarga 35, Verse 14', 'आशंसेति हरिश्रेष्ठ क्षिप्रं मां प्राप्स्यते पतिः।
अन्तरात्मा हि मे शुद्धस्तस्मिंश्च बहवो गुणाः॥', 'āśaṃseti hariśreṣṭha kṣipraṃ māṃ prāpsyate patiḥ
antarātmā hi me śuddhas tasmiṃś ca bahavo guṇāḥ', null, 5035014),
('ramayana-5-35-15', 15, 'Sundara Kanda, Sarga 35, Verse 15', 'उत्साहः पौरुषं सत्त्वमानृशंस्यं कृतज्ञता।
विक्रमश्च प्रभावश्च सन्ति वानरराघवे॥', 'utsāhaḥ pauruṣaṃ sattvam ānṛśaṃsyaṃ kṛtajñatā
vikramaś ca prabhāvaś ca santi vānararāghave', null, 5035015),
('ramayana-5-35-16', 16, 'Sundara Kanda, Sarga 35, Verse 16', 'चतुर्दशसहस्राणि राक्षसानां जघान यः।
जनस्थाने विना भ्रात्रा शत्रुः कस्तस्य नोद्विजेत्॥', 'caturdaśasahasrāṇi rākṣasānāṃ jaghāna yaḥ
janasthāne vinā bhrātrā śatruḥ kas tasya nodvijet', null, 5035016),
('ramayana-5-35-17', 17, 'Sundara Kanda, Sarga 35, Verse 17', 'न स शक्यस्तुलयितुं व्यसनैः पुरुषर्षभः।
अहं तस्यानुभावज्ञा शक्रस्येव पुलोमजा॥', 'na sa śakyas tulayituṃ vyasanaiḥ puruṣarṣabhaḥ
ahaṃ tasyānubhāvajñā śakrasyeva pulomajā', null, 5035017),
('ramayana-5-35-18', 18, 'Sundara Kanda, Sarga 35, Verse 18', 'शरजालांशुमाञ्शूरः कपे रामदिवाकरः।
शत्रुरक्षोमयं तोयमुपशोषं नयिष्यति॥', 'śarajālāṃśumāñ śūraḥ kape rāmadivākaraḥ
śatrurakṣomayaṃ toyam upaśoṣaṃ nayiṣyati', null, 5035018),
('ramayana-5-35-19', 19, 'Sundara Kanda, Sarga 35, Verse 19', 'इति संजल्पमानां तां रामार्थे शोककर्शिताम्।
अश्रुसंपूर्णवदनामुवाच हनुमान्कपिः॥', 'iti saṃjalpamānāṃ tāṃ rāmārthe śokakarśitām
aśrusaṃpūrṇavadanām uvāca hanumān kapiḥ', null, 5035019),
('ramayana-5-35-20', 20, 'Sundara Kanda, Sarga 35, Verse 20', 'श्रुत्वैव तु वचो मह्यं क्षिप्रमेष्यति राघवः।
चमूं प्रकर्षन्महतीं हर्यृक्षगणसंकुलाम्॥', 'śrutvaiva tu vaco mahyaṃ kṣipram eṣyati rāghavaḥ
camūṃ prakarṣan mahatīṃ haryṛkṣagaṇasaṃkulām', null, 5035020),
('ramayana-5-35-21', 21, 'Sundara Kanda, Sarga 35, Verse 21', 'अथ वा मोचयिष्यामि तामद्यैव हि राक्षसात्।
अस्माद्दुःखादुपारोह मम पृष्ठमनिन्दिते॥', 'atha vā mocayiṣyāmi tām adyaiva hi rākṣasāt
asmād duḥkhād upāroha mama pṛṣṭham anindite', null, 5035021),
('ramayana-5-35-22', 22, 'Sundara Kanda, Sarga 35, Verse 22', 'त्वं हि पृष्ठगतां कृत्वा संतरिष्यामि सागरम्।
शक्तिरस्ति हि मे वोढुं लङ्कामपि सरावणाम्॥', 'tvaṃ hi pṛṣṭhagatāṃ kṛtvā saṃtariṣyāmi sāgaram
śaktir asti hi me voḍhuṃ laṅkām api sarāvaṇām', null, 5035022),
('ramayana-5-35-23', 23, 'Sundara Kanda, Sarga 35, Verse 23', 'अहं प्रस्रवणस्थाय राघवायाद्य मैथिलि।
प्रापयिष्यामि शक्राय हव्यं हुतमिवानलः॥', 'ahaṃ prasravaṇasthāya rāghavāyādya maithili
prāpayiṣyāmi śakrāya havyaṃ hutam ivānalaḥ', null, 5035023),
('ramayana-5-35-24', 24, 'Sundara Kanda, Sarga 35, Verse 24', 'द्रक्ष्यस्यद्यैव वैदेहि राघवं सहलक्ष्मणम्।
व्यवसाय समायुक्तं विष्णुं दैत्यवधे यथा॥', 'drakṣyasy adyaiva vaidehi rāghavaṃ sahalakṣmaṇam
vyavasāya samāyuktaṃ viṣṇuṃ daityavadhe yathā', null, 5035024),
('ramayana-5-35-25', 25, 'Sundara Kanda, Sarga 35, Verse 25', 'त्वद्दर्शनकृतोत्साहमाश्रमस्थं महाबलम्।
पुरंदरमिवासीनं नागराजस्य मूर्धनि॥', 'tvaddarśanakṛtotsāham āśramasthaṃ mahābalam
puraṃdaram ivāsīnaṃ nāgarājasya mūrdhani', null, 5035025),
('ramayana-5-35-26', 26, 'Sundara Kanda, Sarga 35, Verse 26', 'पृष्ठमारोह मे देवि मा विकाङ्क्षस्व शोभने।
योगमन्विच्छ रामेण शशाङ्केनेव रोहिणी॥', 'pṛṣṭham āroha me devi mā vikāṅkṣasva śobhane
yogam anviccha rāmeṇa śaśāṅkeneva rohiṇī', null, 5035026),
('ramayana-5-35-27', 27, 'Sundara Kanda, Sarga 35, Verse 27', 'कथयन्तीव चन्द्रेण सूर्येणेव सुवर्चला।
मत्पृष्ठमधिरुह्य त्वं तराकाशमहार्णवम्॥', 'kathayantīva candreṇa sūryeṇeva suvarcalā
matpṛṣṭham adhiruhya tvaṃ tarākāśamahārṇavam', null, 5035027),
('ramayana-5-35-28', 28, 'Sundara Kanda, Sarga 35, Verse 28', 'न हि मे संप्रयातस्य त्वामितो नयतोऽङ्गने।
अनुगन्तुं गतिं शक्ताः सर्वे लङ्कानिवासिनः॥', 'na hi me saṃprayātasya tvām ito nayato ''ṅgane
anugantuṃ gatiṃ śaktāḥ sarve laṅkānivāsinaḥ', null, 5035028),
('ramayana-5-35-29', 29, 'Sundara Kanda, Sarga 35, Verse 29', 'यथैवाहमिह प्राप्तस्तथैवाहमसंशयम्।
यास्यामि पश्य वैदेहि त्वामुद्यम्य विहायसं॥', 'yathaivāham iha prāptas tathaivāham asaṃśayam
yāsyāmi paśya vaidehi tvām udyamya vihāyasaṃ', null, 5035029),
('ramayana-5-35-30', 30, 'Sundara Kanda, Sarga 35, Verse 30', 'मैथिली तु हरिश्रेष्ठाच्छ्रुत्वा वचनमद्भुतम्।
हर्षविस्मितसर्वाङ्गी हनूमन्तमथाब्रवीत्॥', 'maithilī tu hariśreṣṭhāc chrutvā vacanam adbhutam
harṣavismitasarvāṅgī hanūmantam athābravīt', null, 5035030),
('ramayana-5-35-31', 31, 'Sundara Kanda, Sarga 35, Verse 31', 'हनूमन्दूरमध्वनं कथं मां वोढुमिच्छसि।
तदेव खलु ते मन्ये कपित्वं हरियूथप॥', 'hanūman dūram adhvanaṃ kathaṃ māṃ voḍhum icchasi
tad eva khalu te manye kapitvaṃ hariyūthapa', null, 5035031),
('ramayana-5-35-32', 32, 'Sundara Kanda, Sarga 35, Verse 32', 'कथं वाल्पशरीरस्त्वं मामितो नेतुमिच्छसि।
सकाशं मानवेन्द्रस्य भर्तुर्मे प्लवगर्षभ॥', 'kathaṃ vālpaśarīras tvaṃ mām ito netum icchasi
sakāśaṃ mānavendrasya bhartur me plavagarṣabha', null, 5035032),
('ramayana-5-35-33', 33, 'Sundara Kanda, Sarga 35, Verse 33', 'सीताया वचनं श्रुत्वा हनूमान्मारुतात्मजः।
चिन्तयामास लक्ष्मीवान्नवं परिभवं कृतम्॥', 'sītāyā vacanaṃ śrutvā hanūmān mārutātmajaḥ
cintayām āsa lakṣmīvān navaṃ paribhavaṃ kṛtam', null, 5035033),
('ramayana-5-35-34', 34, 'Sundara Kanda, Sarga 35, Verse 34', 'न मे जानाति सत्त्वं वा प्रभावं वासितेक्षणा।
तस्मात्पश्यतु वैदेही यद्रूपं मम कामतः॥', 'na me jānāti sattvaṃ vā prabhāvaṃ vāsitekṣaṇā
tasmāt paśyatu vaidehī yad rūpaṃ mama kāmataḥ', null, 5035034),
('ramayana-5-35-35', 35, 'Sundara Kanda, Sarga 35, Verse 35', 'इति संचिन्त्य हनुमांस्तदा प्लवगसत्तमः।
दर्शयामास वैदेह्याः स्वरूपमरिमर्दनः॥', 'iti saṃcintya hanumāṃs tadā plavagasattamaḥ
darśayām āsa vaidehyāḥ svarūpam arimardanaḥ', null, 5035035),
('ramayana-5-35-36', 36, 'Sundara Kanda, Sarga 35, Verse 36', 'स तस्मात्पादपाद्धीमानाप्लुत्य प्लवगर्षभः।
ततो वर्धितुमारेभे सीताप्रत्ययकारणात्॥', 'sa tasmāt pādapād dhīmān āplutya plavagarṣabhaḥ
tato vardhitum ārebhe sītāpratyayakāraṇāt', null, 5035036),
('ramayana-5-35-37', 37, 'Sundara Kanda, Sarga 35, Verse 37', 'मेरुमन्दारसंकाशो बभौ दीप्तानलप्रभः।
अग्रतो व्यवतस्थे च सीताया वानरर्षभः॥', 'merumandārasaṃkāśo babhau dīptānalaprabhaḥ
agrato vyavatasthe ca sītāyā vānararṣabhaḥ', null, 5035037),
('ramayana-5-35-38', 38, 'Sundara Kanda, Sarga 35, Verse 38', 'हरिः पर्वतसंकाशस्ताम्रवक्त्रो महाबलः।
वज्रदंष्ट्रनखो भीमो वैदेहीमिदमब्रवीत्॥', 'hariḥ parvatasaṃkāśas tāmravaktro mahābalaḥ
vajradaṃṣṭranakho bhīmo vaidehīm idam abravīt', null, 5035038),
('ramayana-5-35-39', 39, 'Sundara Kanda, Sarga 35, Verse 39', 'सपर्वतवनोद्देशां साट्टप्राकारतोरणाम्।
लङ्कामिमां सनथां वा नयितुं शक्तिरस्ति मे॥', 'saparvatavanoddeśāṃ sāṭṭaprākāratoraṇām
laṅkām imāṃ sanathāṃ vā nayituṃ śaktir asti me', null, 5035039),
('ramayana-5-35-40', 40, 'Sundara Kanda, Sarga 35, Verse 40', 'तदवस्थाप्य तां बुद्धिरलं देवि विकाङ्क्षया।
विशोकं कुरु वैदेहि राघवं सहलक्ष्मणम्॥', 'tad avasthāpya tāṃ buddhir alaṃ devi vikāṅkṣayā
viśokaṃ kuru vaidehi rāghavaṃ sahalakṣmaṇam', null, 5035040),
('ramayana-5-35-41', 41, 'Sundara Kanda, Sarga 35, Verse 41', 'तं दृष्ट्वाचलसंकाशमुवाच जनकात्मजा।
पद्मपत्रविशालाक्षी मारुतस्यौरसं सुतम्॥', 'taṃ dṛṣṭvācalasaṃkāśam uvāca janakātmajā
padmapatraviśālākṣī mārutasyaurasaṃ sutam', null, 5035041),
('ramayana-5-35-42', 42, 'Sundara Kanda, Sarga 35, Verse 42', 'तव सत्त्वं बलं चैव विजानामि महाकपे।
वायोरिव गतिं चापि तेजश्चाग्निरिवाद्भुतम्॥', 'tava sattvaṃ balaṃ caiva vijānāmi mahākape
vāyor iva gatiṃ cāpi tejaś cāgnir ivādbhutam', null, 5035042),
('ramayana-5-35-43', 43, 'Sundara Kanda, Sarga 35, Verse 43', 'प्राकृतोऽन्यः कथं चेमां भूमिमागन्तुमर्हति।
उदधेरप्रमेयस्य पारं वानरपुंगव॥', 'prākṛto ''nyaḥ kathaṃ cemāṃ bhūmim āgantum arhati
udadher aprameyasya pāraṃ vānarapuṃgava', null, 5035043),
('ramayana-5-35-44', 44, 'Sundara Kanda, Sarga 35, Verse 44', 'जानामि गमने शक्तिं नयने चापि ते मम।
अवश्यं साम्प्रधार्याशु कार्यसिद्धिरिहात्मनः॥', 'jānāmi gamane śaktiṃ nayane cāpi te mama
avaśyaṃ sāmpradhāryāśu kāryasiddhir ihātmanaḥ', null, 5035044),
('ramayana-5-35-45', 45, 'Sundara Kanda, Sarga 35, Verse 45', 'अयुक्तं तु कपिश्रेष्ठ मया गन्तुं त्वया सह।
वायुवेगसवेगस्य वेगो मां मोहयेत्तव॥', 'ayuktaṃ tu kapiśreṣṭha mayā gantuṃ tvayā saha
vāyuvegasavegasya vego māṃ mohayet tava', null, 5035045),
('ramayana-5-35-46', 46, 'Sundara Kanda, Sarga 35, Verse 46', 'अहमाकाशमासक्ता उपर्युपरि सागरम्।
प्रपतेयं हि ते पृष्ठाद्भयाद्वेगेन गच्छतः॥', 'aham ākāśam āsaktā upary upari sāgaram
prapateyaṃ hi te pṛṣṭhād bhayād vegena gacchataḥ', null, 5035046),
('ramayana-5-35-47', 47, 'Sundara Kanda, Sarga 35, Verse 47', 'पतिता सागरे चाहं तिमिनक्रझषाकुले।
भयेयमाशु विवशा यादसामन्नमुत्तमम्॥', 'patitā sāgare cāhaṃ timinakrajhaṣākule
bhayeyam āśu vivaśā yādasām annam uttamam', null, 5035047),
('ramayana-5-35-48', 48, 'Sundara Kanda, Sarga 35, Verse 48', 'न च शक्ष्ये त्वया सार्धं गन्तुं शत्रुविनाशन।
कलत्रवति संदेहस्त्वय्यपि स्यादसंशयम्॥', 'na ca śakṣye tvayā sārdhaṃ gantuṃ śatruvināśana
kalatravati saṃdehas tvayy api syād asaṃśayam', null, 5035048),
('ramayana-5-35-49', 49, 'Sundara Kanda, Sarga 35, Verse 49', 'ह्रियमाणां तु मां दृष्ट्वा राक्षसा भीमविक्रमाः।
अनुगच्छेयुरादिष्टा रावणेन दुरात्मना॥', 'hriyamāṇāṃ tu māṃ dṛṣṭvā rākṣasā bhīmavikramāḥ
anugaccheyur ādiṣṭā rāvaṇena durātmanā', null, 5035049),
('ramayana-5-35-50', 50, 'Sundara Kanda, Sarga 35, Verse 50', 'तैस्त्वं परिवृतः शूरैः शूलमुद्गर पाणिभिः।
भवेस्त्वं संशयं प्राप्तो मया वीर कलत्रवान्॥', 'tais tvaṃ parivṛtaḥ śūraiḥ śūlam udgara pāṇibhiḥ
bhaves tvaṃ saṃśayaṃ prāpto mayā vīra kalatravān', null, 5035050),
('ramayana-5-35-51', 51, 'Sundara Kanda, Sarga 35, Verse 51', 'सायुधा बहवो व्योम्नि राक्षसास्त्वं निरायुधः।
कथं शक्ष्यसि संयातुं मां चैव परिरक्षितुम्॥', 'sāyudhā bahavo vyomni rākṣasās tvaṃ nirāyudhaḥ
kathaṃ śakṣyasi saṃyātuṃ māṃ caiva parirakṣitum', null, 5035051),
('ramayana-5-35-52', 52, 'Sundara Kanda, Sarga 35, Verse 52', 'युध्यमानस्य रक्षोभिस्ततस्तैः क्रूरकर्मभिः।
प्रपतेयं हि ते पृष्ठद्भयार्ता कपिसत्तम॥', 'yudhyamānasya rakṣobhis tatas taiḥ krūrakarmabhiḥ
prapateyaṃ hi te pṛṣṭhad bhayārtā kapisattama', null, 5035052),
('ramayana-5-35-53', 53, 'Sundara Kanda, Sarga 35, Verse 53', 'अथ रक्षांसि भीमानि महान्ति बलवन्ति च।
कथं चित्साम्पराये त्वां जयेयुः कपिसत्तम॥', 'atha rakṣāṃsi bhīmāni mahānti balavanti ca
kathaṃ cit sāmparāye tvāṃ jayeyuḥ kapisattama', null, 5035053),
('ramayana-5-35-54', 54, 'Sundara Kanda, Sarga 35, Verse 54', 'अथ वा युध्यमानस्य पतेयं विमुखस्य ते।
पतितां च गृहीत्वा मां नयेयुः पापराक्षसाः॥', 'atha vā yudhyamānasya pateyaṃ vimukhasya te
patitāṃ ca gṛhītvā māṃ nayeyuḥ pāparākṣasāḥ', null, 5035054),
('ramayana-5-35-55', 55, 'Sundara Kanda, Sarga 35, Verse 55', 'मां वा हरेयुस्त्वद्धस्ताद्विशसेयुरथापि वा।
अव्यवस्थौ हि दृश्येते युद्धे जयपराजयौ॥', 'māṃ vā hareyus tvaddhastād viśaseyur athāpi vā
avyavasthau hi dṛśyete yuddhe jayaparājayau', null, 5035055),
('ramayana-5-35-56', 56, 'Sundara Kanda, Sarga 35, Verse 56', 'अहं वापि विपद्येयं रक्षोभिरभितर्जिता।
त्वत्प्रयत्नो हरिश्रेष्ठ भवेन्निष्फल एव तु॥', 'ahaṃ vāpi vipadyeyaṃ rakṣobhir abhitarjitā
tvatprayatno hariśreṣṭha bhaven niṣphala eva tu', null, 5035056),
('ramayana-5-35-57', 57, 'Sundara Kanda, Sarga 35, Verse 57', 'कामं त्वमपि पर्याप्तो निहन्तुं सर्वराक्षसान्।
राघवस्य यशो हीयेत्त्वया शस्तैस्तु राक्षसैः॥', 'kāmaṃ tvam api paryāpto nihantuṃ sarvarākṣasān
rāghavasya yaśo hīyet tvayā śastais tu rākṣasaiḥ', null, 5035057),
('ramayana-5-35-58', 58, 'Sundara Kanda, Sarga 35, Verse 58', 'अथ वादाय रक्षांसि न्यस्येयुः संवृते हि माम्।
यत्र ते नाभिजानीयुर्हरयो नापि राघवः॥', 'atha vādāya rakṣāṃsi nyasyeyuḥ saṃvṛte hi mām
yatra te nābhijānīyur harayo nāpi rāghavaḥ', null, 5035058),
('ramayana-5-35-59', 59, 'Sundara Kanda, Sarga 35, Verse 59', 'आरम्भस्तु मदर्थोऽयं ततस्तव निरर्थकः।
त्वया हि सह रामस्य महानागमने गुणः॥', 'ārambhas tu madartho ''yaṃ tatas tava nirarthakaḥ
tvayā hi saha rāmasya mahān āgamane guṇaḥ', null, 5035059),
('ramayana-5-35-60', 60, 'Sundara Kanda, Sarga 35, Verse 60', 'मयि जीवितमायत्तं राघवस्य महात्मनः।
भ्रातॄणां च महाबाहो तव राजकुलस्य च॥', 'mayi jīvitam āyattaṃ rāghavasya mahātmanaḥ
bhrātṝṇāṃ ca mahābāho tava rājakulasya ca', null, 5035060),
('ramayana-5-35-61', 61, 'Sundara Kanda, Sarga 35, Verse 61', 'तौ निराशौ मदर्थे तु शोकसंतापकर्शितौ।
सह सर्वर्क्षहरिभिस्त्यक्ष्यतः प्राणसंग्रहम्॥', 'tau nirāśau madarthe tu śokasaṃtāpakarśitau
saha sarvarkṣaharibhis tyakṣyataḥ prāṇasaṃgraham', null, 5035061),
('ramayana-5-35-62', 62, 'Sundara Kanda, Sarga 35, Verse 62', 'भर्तुर्भक्तिं पुरस्कृत्य रामादन्यस्य वानर।
नाहं स्प्रष्टुं पदा गात्रमिच्छेयं वानरोत्तम॥', 'bhartur bhaktiṃ puraskṛtya rāmād anyasya vānara
nāhaṃ spraṣṭuṃ padā gātram iccheyaṃ vānarottama', null, 5035062),
('ramayana-5-35-63', 63, 'Sundara Kanda, Sarga 35, Verse 63', 'यदहं गात्रसंस्पर्शं रावणस्य गता बलात्।
अनीशा किं करिष्यामि विनाथा विवशा सती॥', 'yad ahaṃ gātrasaṃsparśaṃ rāvaṇasya gatā balāt
anīśā kiṃ kariṣyāmi vināthā vivaśā satī', null, 5035063),
('ramayana-5-35-64', 64, 'Sundara Kanda, Sarga 35, Verse 64', 'यदि रामो दशग्रीवमिह हत्वा सराक्षसं।
मामितो गृह्य गच्छेत तत्तस्य सदृशं भवेत्॥', 'yadi rāmo daśagrīvam iha hatvā sarākṣasaṃ
mām ito gṛhya gaccheta tat tasya sadṛśaṃ bhavet', null, 5035064),
('ramayana-5-35-65', 65, 'Sundara Kanda, Sarga 35, Verse 65', 'श्रुता हि दृष्टाश्च मया पराक्रमा महात्मनस्तस्य रणावमर्दिनः।
न देवगन्धर्वभुजंगराक्षसा भवन्ति रामेण समा हि संयुगे॥', 'śrutā hi dṛṣṭāś ca mayā parākramā mahātmanas tasya raṇāvamardinaḥ
na devagandharvabhujaṃgarākṣasā bhavanti rāmeṇa samā hi saṃyuge', null, 5035065),
('ramayana-5-35-66', 66, 'Sundara Kanda, Sarga 35, Verse 66', 'समीक्ष्य तं संयति चित्रकार्मुकं महाबलं वासवतुल्यविक्रमम्।
सलक्ष्मणं को विषहेत राघवं हुताशनं दीप्तमिवानिलेरितम्॥', 'samīkṣya taṃ saṃyati citrakārmukaṃ mahābalaṃ vāsavatulyavikramam
salakṣmaṇaṃ ko viṣaheta rāghavaṃ hutāśanaṃ dīptam ivānileritam', null, 5035066),
('ramayana-5-35-67', 67, 'Sundara Kanda, Sarga 35, Verse 67', 'सलक्ष्मणं राघवमाजिमर्दनं दिशागजं मत्तमिव व्यवस्थितम्।
सहेत को वानरमुख्य संयुगे युगान्तसूर्यप्रतिमं शरार्चिषम्॥', 'salakṣmaṇaṃ rāghavam ājimardanaṃ diśāgajaṃ mattam iva vyavasthitam
saheta ko vānaramukhya saṃyuge yugāntasūryapratimaṃ śarārciṣam', null, 5035067),
('ramayana-5-35-68', 68, 'Sundara Kanda, Sarga 35, Verse 68', 'स मे हरिश्रेष्ठ सलक्ष्मणं पतिं सयूथपं क्षिप्रमिहोपपादय।
चिराय रामं प्रति शोककर्शितां कुरुष्व मां वानरमुख्य हर्षिताम्॥', 'sa me hariśreṣṭha salakṣmaṇaṃ patiṃ sayūthapaṃ kṣipram ihopapādaya
cirāya rāmaṃ prati śokakarśitāṃ kuruṣva māṃ vānaramukhya harṣitām', null, 5035068)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 36 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-36-1', 1, 'Sundara Kanda, Sarga 36, Verse 1', 'ततः स कपिशार्दूलस्तेन वाक्येन हर्षितः।
सीतामुवाच तच्छ्रुत्वा वाक्यं वाक्यविशारदः॥', 'tataḥ sa kapiśārdūlas tena vākyena harṣitaḥ
sītām uvāca tac chrutvā vākyaṃ vākyaviśāradaḥ', null, 5036001),
('ramayana-5-36-2', 2, 'Sundara Kanda, Sarga 36, Verse 2', 'युक्तरूपं त्वया देवि भाषितं शुभदर्शने।
सदृशं स्त्रीस्वभावस्य साध्वीनां विनयस्य च॥', 'yuktarūpaṃ tvayā devi bhāṣitaṃ śubhadarśane
sadṛśaṃ strīsvabhāvasya sādhvīnāṃ vinayasya ca', null, 5036002),
('ramayana-5-36-3', 3, 'Sundara Kanda, Sarga 36, Verse 3', 'स्त्रीत्वं न तु समर्थं हि सागरं व्यतिवर्तितुम्।
मामधिष्ठाय विस्तीर्णं शतयोजनमायतम्॥', 'strītvaṃ na tu samarthaṃ hi sāgaraṃ vyativartitum
mām adhiṣṭhāya vistīrṇaṃ śatayojanam āyatam', null, 5036003),
('ramayana-5-36-4', 4, 'Sundara Kanda, Sarga 36, Verse 4', 'द्वितीयं कारणं यच्च ब्रवीषि विनयान्विते।
रामादन्यस्य नार्हामि संस्पर्शमिति जानकि॥', 'dvitīyaṃ kāraṇaṃ yac ca bravīṣi vinayānvite
rāmād anyasya nārhāmi saṃsparśam iti jānaki', null, 5036004),
('ramayana-5-36-5', 5, 'Sundara Kanda, Sarga 36, Verse 5', 'एतत्ते देवि सदृशं पत्न्यास्तस्य महात्मनः।
का ह्यन्या त्वामृते देवि ब्रूयाद्वचनमीदृशम्॥', 'etat te devi sadṛśaṃ patnyās tasya mahātmanaḥ
kā hy anyā tvām ṛte devi brūyād vacanam īdṛśam', null, 5036005),
('ramayana-5-36-6', 6, 'Sundara Kanda, Sarga 36, Verse 6', 'श्रोष्यते चैव काकुत्स्थः सर्वं निरवशेषतः।
चेष्टितं यत्त्वया देवि भाषितं मम चाग्रतः॥', 'śroṣyate caiva kākutsthaḥ sarvaṃ niravaśeṣataḥ
ceṣṭitaṃ yat tvayā devi bhāṣitaṃ mama cāgrataḥ', null, 5036006),
('ramayana-5-36-7', 7, 'Sundara Kanda, Sarga 36, Verse 7', 'कारणैर्बहुभिर्देवि राम प्रियचिकीर्षया।
स्नेहप्रस्कन्नमनसा मयैतत्समुदीरितम्॥', 'kāraṇair bahubhir devi rāma priyacikīrṣayā
snehapraskannamanasā mayaitat samudīritam', null, 5036007),
('ramayana-5-36-8', 8, 'Sundara Kanda, Sarga 36, Verse 8', 'लङ्काया दुष्प्रवेशत्वाद्दुस्तरत्वान्महोदधेः।
सामर्थ्यादात्मनश्चैव मयैतत्समुदाहृतम्॥', 'laṅkāyā duṣpraveśatvād dustaratvān mahodadheḥ
sāmarthyād ātmanaś caiva mayaitat samudāhṛtam', null, 5036008),
('ramayana-5-36-9', 9, 'Sundara Kanda, Sarga 36, Verse 9', 'इच्छामि त्वां समानेतुमद्यैव रघुबन्धुना।
गुरुस्नेहेन भक्त्या च नान्यथा तदुदाहृतम्॥', 'icchāmi tvāṃ samānetum adyaiva raghubandhunā
gurusnehena bhaktyā ca nānyathā tad udāhṛtam', null, 5036009),
('ramayana-5-36-10', 10, 'Sundara Kanda, Sarga 36, Verse 10', 'यदि नोत्सहसे यातुं मया सार्धमनिन्दिते।
अभिज्ञानं प्रयच्छ त्वं जानीयाद्राघवो हि यत्॥', 'yadi notsahase yātuṃ mayā sārdham anindite
abhijñānaṃ prayaccha tvaṃ jānīyād rāghavo hi yat', null, 5036010),
('ramayana-5-36-11', 11, 'Sundara Kanda, Sarga 36, Verse 11', 'एवमुक्ता हनुमता सीता सुरसुतोपमा।
उवाच वचनं मन्दं बाष्पप्रग्रथिताक्षरम्॥', 'evam uktā hanumatā sītā surasutopamā
uvāca vacanaṃ mandaṃ bāṣpapragrathitākṣaram', null, 5036011),
('ramayana-5-36-12', 12, 'Sundara Kanda, Sarga 36, Verse 12', 'इदं श्रेष्ठमभिज्ञानं ब्रूयास्त्वं तु मम प्रियम्।
शैलस्य चित्रकूटस्य पादे पूर्वोत्तरे तदा॥', 'idaṃ śreṣṭham abhijñānaṃ brūyās tvaṃ tu mama priyam
śailasya citrakūṭasya pāde pūrvottare tadā', null, 5036012),
('ramayana-5-36-13', 13, 'Sundara Kanda, Sarga 36, Verse 13', 'तापसाश्रमवासिन्याः प्राज्यमूलफलोदके।
तस्मिन्सिद्धाश्रमे देशे मन्दाकिन्या अदूरतः॥', 'tāpasāśramavāsinyāḥ prājyamūlaphalodake
tasmin siddhāśrame deśe mandākinyā adūrataḥ', null, 5036013),
('ramayana-5-36-14', 14, 'Sundara Kanda, Sarga 36, Verse 14', 'तस्योपवनषण्डेषु नानापुष्पसुगन्धिषु।
विहृत्य सलिलक्लिन्ना तवाङ्के समुपाविशम्॥', 'tasyopavanaṣaṇḍeṣu nānāpuṣpasugandhiṣu
vihṛtya salilaklinnā tavāṅke samupāviśam', null, 5036014),
('ramayana-5-36-15', 15, 'Sundara Kanda, Sarga 36, Verse 15', 'पर्यायेण प्रसुप्तश्च ममाङ्के भरताग्रजः॥', 'paryāyeṇa prasuptaś ca mamāṅke bharatāgrajaḥ', null, 5036015),
('ramayana-5-36-16', 16, 'Sundara Kanda, Sarga 36, Verse 16', 'ततो मांससमायुक्तो वायसः पर्यतुण्डयत्।
तमहं लोष्टमुद्यम्य वारयामि स्म वायसं॥', 'tato māṃsasamāyukto vāyasaḥ paryatuṇḍayat
tam ahaṃ loṣṭam udyamya vārayāmi sma vāyasaṃ', null, 5036016),
('ramayana-5-36-17', 17, 'Sundara Kanda, Sarga 36, Verse 17', 'दारयन्स च मां काकस्तत्रैव परिलीयते।
न चाप्युपरमन्मांसाद्भक्षार्थी बलिभोजनः॥', 'dārayan sa ca māṃ kākas tatraiva parilīyate
na cāpy uparaman māṃsād bhakṣārthī balibhojanaḥ', null, 5036017),
('ramayana-5-36-18', 18, 'Sundara Kanda, Sarga 36, Verse 18', 'उत्कर्षन्त्यां च रशनां क्रुद्धायां मयि पक्षिणे।
स्रंसमाने च वसने ततो दृष्टा त्वया ह्यहम्॥', 'utkarṣantyāṃ ca raśanāṃ kruddhāyāṃ mayi pakṣiṇe
sraṃsamāne ca vasane tato dṛṣṭā tvayā hy aham', null, 5036018),
('ramayana-5-36-19', 19, 'Sundara Kanda, Sarga 36, Verse 19', 'त्वया विहसिता चाहं क्रुद्धा संलज्जिता तदा।
भक्ष्य गृद्धेन कालेन दारिता त्वामुपागता॥', 'tvayā vihasitā cāhaṃ kruddhā saṃlajjitā tadā
bhakṣya gṛddhena kālena dāritā tvām upāgatā', null, 5036019),
('ramayana-5-36-20', 20, 'Sundara Kanda, Sarga 36, Verse 20', 'आसीनस्य च ते श्रान्ता पुनरुत्सङ्गमाविशम्।
क्रुध्यन्ती च प्रहृष्टेन त्वयाहं परिसान्त्विता॥', 'āsīnasya ca te śrāntā punar utsaṅgam āviśam
krudhyantī ca prahṛṣṭena tvayāhaṃ parisāntvitā', null, 5036020),
('ramayana-5-36-21', 21, 'Sundara Kanda, Sarga 36, Verse 21', 'बाष्पपूर्णमुखी मन्दं चक्षुषी परिमार्जती।
लक्षिताहं त्वया नाथ वायसेन प्रकोपिता॥', 'bāṣpapūrṇamukhī mandaṃ cakṣuṣī parimārjatī
lakṣitāhaṃ tvayā nātha vāyasena prakopitā', null, 5036021),
('ramayana-5-36-22', 22, 'Sundara Kanda, Sarga 36, Verse 22', 'आशीविष इव क्रुद्धः श्वसान्वाक्यमभाषथाः।
केन ते नागनासोरु विक्षतं वै स्तनान्तरम्।
कः क्रीडति सरोषेण पञ्चवक्त्रेण भोगिना॥', 'āśīviṣa iva kruddhaḥ śvasān vākyam abhāṣathāḥ
kena te nāganāsoru vikṣataṃ vai stanāntaram
kaḥ krīḍati saroṣeṇa pañcavaktreṇa bhoginā', null, 5036022),
('ramayana-5-36-23', 23, 'Sundara Kanda, Sarga 36, Verse 23', 'वीक्षमाणस्ततस्तं वै वायसं समवैक्षथाः।
नखैः सरुधिरैस्तीक्ष्णैर्मामेवाभिमुखं स्थितम्॥', 'vīkṣamāṇas tatas taṃ vai vāyasaṃ samavaikṣathāḥ
nakhaiḥ sarudhirais tīkṣṇair mām evābhimukhaṃ sthitam', null, 5036023),
('ramayana-5-36-24', 24, 'Sundara Kanda, Sarga 36, Verse 24', 'पुत्रः किल स शक्रस्य वायसः पततां वरः।
धरान्तरचरः शीघ्रं पवनस्य गतौ समः॥', 'putraḥ kila sa śakrasya vāyasaḥ patatāṃ varaḥ
dharāntaracaraḥ śīghraṃ pavanasya gatau samaḥ', null, 5036024),
('ramayana-5-36-25', 25, 'Sundara Kanda, Sarga 36, Verse 25', 'ततस्तस्मिन्महाबाहुः कोपसंवर्तितेक्षणः।
वायसे कृतवान्क्रूरां मतिं मतिमतां वर॥', 'tatas tasmin mahābāhuḥ kopasaṃvartitekṣaṇaḥ
vāyase kṛtavān krūrāṃ matiṃ matimatāṃ vara', null, 5036025),
('ramayana-5-36-26', 26, 'Sundara Kanda, Sarga 36, Verse 26', 'स दर्भसंस्तराद्गृह्य ब्रह्मणोऽस्त्रेण योजयः।
स दीप्त इव कालाग्निर्जज्वालाभिमुखो द्विजम्॥', 'sa darbhasaṃstarād gṛhya brahmaṇo ''streṇa yojayaḥ
sa dīpta iva kālāgnir jajvālābhimukho dvijam', null, 5036026),
('ramayana-5-36-27', 27, 'Sundara Kanda, Sarga 36, Verse 27', 'चिक्षेपिथ प्रदीप्तां तामिषीकां वायसं प्रति।
अनुसृष्टस्तदा कालो जगाम विविधां गतिम्।
त्राणकाम इमं लोकं सर्वं वै विचचार ह॥', 'cikṣepitha pradīptāṃ tām iṣīkāṃ vāyasaṃ prati
anusṛṣṭas tadā kālo jagāma vividhāṃ gatim
trāṇakāma imaṃ lokaṃ sarvaṃ vai vicacāra ha', null, 5036027),
('ramayana-5-36-28', 28, 'Sundara Kanda, Sarga 36, Verse 28', 'स पित्रा च परित्यक्तः सुरैः सर्वैर्महर्षिभिः।
त्रींल्लोकान्संपरिक्रम्य त्वामेव शरणं गतः॥', 'sa pitrā ca parityaktaḥ suraiḥ sarvair maharṣibhiḥ
trīṃl lokān saṃparikramya tvām eva śaraṇaṃ gataḥ', null, 5036028),
('ramayana-5-36-29', 29, 'Sundara Kanda, Sarga 36, Verse 29', 'तं त्वं निपतितं भूमौ शरण्यः शरणागतम्।
वधार्हमपि काकुत्स्थ कृपया पर्यपालयः।
न शर्म लब्ध्वा लोकेषु त्वामेव शरणं गतः॥', 'taṃ tvaṃ nipatitaṃ bhūmau śaraṇyaḥ śaraṇāgatam
vadhārham api kākutstha kṛpayā paryapālayaḥ
na śarma labdhvā lokeṣu tvām eva śaraṇaṃ gataḥ', null, 5036029),
('ramayana-5-36-30', 30, 'Sundara Kanda, Sarga 36, Verse 30', 'परिद्यूनं विषण्णं च स त्वमायान्तमुक्तवान्।
मोघं कर्तुं न शक्यं तु ब्राह्ममस्त्रं तदुच्यताम्॥', 'paridyūnaṃ viṣaṇṇaṃ ca sa tvam āyāntam uktavān
moghaṃ kartuṃ na śakyaṃ tu brāhmam astraṃ tad ucyatām', null, 5036030),
('ramayana-5-36-31', 31, 'Sundara Kanda, Sarga 36, Verse 31', 'ततस्तस्याक्षि काकस्य हिनस्ति स्म स दक्षिणम्॥', 'tatas tasyākṣi kākasya hinasti sma sa dakṣiṇam', null, 5036031),
('ramayana-5-36-32', 32, 'Sundara Kanda, Sarga 36, Verse 32', 'स ते तदा नमस्कृत्वा राज्ञे दशरथाय च।
त्वया वीर विसृष्टस्तु प्रतिपेदे स्वमालयम्॥', 'sa te tadā namaskṛtvā rājñe daśarathāya ca
tvayā vīra visṛṣṭas tu pratipede svam ālayam', null, 5036032),
('ramayana-5-36-33', 33, 'Sundara Kanda, Sarga 36, Verse 33', 'मत्कृते काकमात्रेऽपि ब्रह्मास्त्रं समुदीरितम्।
कस्माद्यो मां हरत्त्वत्तः क्षमसे तं महीपते॥', 'matkṛte kākamātre ''pi brahmāstraṃ samudīritam
kasmād yo māṃ harat tvattaḥ kṣamase taṃ mahīpate', null, 5036033),
('ramayana-5-36-34', 34, 'Sundara Kanda, Sarga 36, Verse 34', 'स कुरुष्व महोत्साहं कृपां मयि नरर्षभ।
आनृशंस्यं परो धर्मस्त्वत्त एव मया श्रुतः॥', 'sa kuruṣva mahotsāhaṃ kṛpāṃ mayi nararṣabha
ānṛśaṃsyaṃ paro dharmas tvatta eva mayā śrutaḥ', null, 5036034),
('ramayana-5-36-35', 35, 'Sundara Kanda, Sarga 36, Verse 35', 'जानामि त्वां महावीर्यं महोत्साहं महाबलम्।
अपारपारमक्षोभ्यं गाम्भीर्यात्सागरोपमम्।
भर्तारं ससमुद्राया धरण्या वासवोपमम्॥', 'jānāmi tvāṃ mahāvīryaṃ mahotsāhaṃ mahābalam
apārapāram akṣobhyaṃ gāmbhīryāt sāgaropamam
bhartāraṃ sasamudrāyā dharaṇyā vāsavopamam', null, 5036035),
('ramayana-5-36-36', 36, 'Sundara Kanda, Sarga 36, Verse 36', 'एवमस्त्रविदां श्रेष्ठः सत्त्ववान्बलवानपि।
किमर्थमस्त्रं रक्षःसु न योजयसि राघव॥', 'evam astravidāṃ śreṣṭhaḥ sattvavān balavān api
kimartham astraṃ rakṣaḥsu na yojayasi rāghava', null, 5036036),
('ramayana-5-36-37', 37, 'Sundara Kanda, Sarga 36, Verse 37', 'न नागा नापि गन्धर्वा नासुरा न मरुद्गणाः।
रामस्य समरे वेगं शक्ताः प्रति समाधितुम्॥', 'na nāgā nāpi gandharvā nāsurā na marudgaṇāḥ
rāmasya samare vegaṃ śaktāḥ prati samādhitum', null, 5036037),
('ramayana-5-36-38', 38, 'Sundara Kanda, Sarga 36, Verse 38', 'तस्या वीर्यवतः कश्चिद्यद्यस्ति मयि संभ्रमः।
किमर्थं न शरैस्तीक्ष्णैः क्षयं नयति राक्षसान्॥', 'tasyā vīryavataḥ kaś cid yady asti mayi saṃbhramaḥ
kimarthaṃ na śarais tīkṣṇaiḥ kṣayaṃ nayati rākṣasān', null, 5036038),
('ramayana-5-36-39', 39, 'Sundara Kanda, Sarga 36, Verse 39', 'भ्रातुरादेशमादाय लक्ष्मणो वा परंतपः।
कस्य हेतोर्न मां वीरः परित्राति महाबलः॥', 'bhrātur ādeśam ādāya lakṣmaṇo vā paraṃtapaḥ
kasya hetor na māṃ vīraḥ paritrāti mahābalaḥ', null, 5036039),
('ramayana-5-36-40', 40, 'Sundara Kanda, Sarga 36, Verse 40', 'यदि तौ पुरुषव्याघ्रौ वाय्विन्द्रसमतेजसौ।
सुराणामपि दुर्धर्षो किमर्थं मामुपेक्षतः॥', 'yadi tau puruṣavyāghrau vāyvindrasamatejasau
surāṇām api durdharṣo kimarthaṃ mām upekṣataḥ', null, 5036040),
('ramayana-5-36-41', 41, 'Sundara Kanda, Sarga 36, Verse 41', 'ममैव दुष्कृतं किं चिन्महदस्ति न संशयः।
समर्थावपि तौ यन्मां नावेक्षेते परंतपौ॥', 'mamaiva duṣkṛtaṃ kiṃ cin mahad asti na saṃśayaḥ
samarthāv api tau yan māṃ nāvekṣete paraṃtapau', null, 5036041),
('ramayana-5-36-42', 42, 'Sundara Kanda, Sarga 36, Verse 42', 'कौसल्या लोकभर्तारं सुषुवे यं मनस्विनी।
तं ममार्थे सुखं पृच्छ शिरसा चाभिवादय॥', 'kausalyā lokabhartāraṃ suṣuve yaṃ manasvinī
taṃ mamārthe sukhaṃ pṛccha śirasā cābhivādaya', null, 5036042),
('ramayana-5-36-43', 43, 'Sundara Kanda, Sarga 36, Verse 43', 'स्रजश्च सर्वरत्नानि प्रिया याश्च वराङ्गनाः।
ऐश्वर्यं च विशालायां पृथिव्यामपि दुर्लभम्॥', 'srajaś ca sarvaratnāni priyā yāś ca varāṅganāḥ
aiśvaryaṃ ca viśālāyāṃ pṛthivyām api durlabham', null, 5036043),
('ramayana-5-36-44', 44, 'Sundara Kanda, Sarga 36, Verse 44', 'पितरं मातरं चैव संमान्याभिप्रसाद्य च।
अनुप्रव्रजितो रामं सुमित्रा येन सुप्रजाः।
आनुकूल्येन धर्मात्मा त्यक्त्वा सुखमनुत्तमम्॥', 'pitaraṃ mātaraṃ caiva saṃmānyābhiprasādya ca
anupravrajito rāmaṃ sumitrā yena suprajāḥ
ānukūlyena dharmātmā tyaktvā sukham anuttamam', null, 5036044),
('ramayana-5-36-45', 45, 'Sundara Kanda, Sarga 36, Verse 45', 'अनुगच्छति काकुत्स्थं भ्रातरं पालयन्वने।
सिंहस्कन्धो महाबाहुर्मनस्वी प्रियदर्शनः॥', 'anugacchati kākutsthaṃ bhrātaraṃ pālayan vane
siṃhaskandho mahābāhur manasvī priyadarśanaḥ', null, 5036045),
('ramayana-5-36-46', 46, 'Sundara Kanda, Sarga 36, Verse 46', 'पितृवद्वर्तते रामे मातृवन्मां समाचरन्।
ह्रियमाणां तदा वीरो न तु मां वेद लक्ष्मणः॥', 'pitṛvad vartate rāme mātṛvan māṃ samācaran
hriyamāṇāṃ tadā vīro na tu māṃ veda lakṣmaṇaḥ', null, 5036046),
('ramayana-5-36-47', 47, 'Sundara Kanda, Sarga 36, Verse 47', 'वृद्धोपसेवी लक्ष्मीवाञ्शक्तो न बहुभाषिता।
राजपुत्रः प्रियश्रेष्ठः सदृशः श्वशुरस्य मे॥', 'vṛddhopasevī lakṣmīvāñ śakto na bahubhāṣitā
rājaputraḥ priyaśreṣṭhaḥ sadṛśaḥ śvaśurasya me', null, 5036047),
('ramayana-5-36-48', 48, 'Sundara Kanda, Sarga 36, Verse 48', 'मत्तः प्रियतरो नित्यं भ्राता रामस्य लक्ष्मणः।
नियुक्तो धुरि यस्यां तु तामुद्वहति वीर्यवान्॥', 'mattaḥ priyataro nityaṃ bhrātā rāmasya lakṣmaṇaḥ
niyukto dhuri yasyāṃ tu tām udvahati vīryavān', null, 5036048),
('ramayana-5-36-49', 49, 'Sundara Kanda, Sarga 36, Verse 49', 'यं दृष्ट्वा राघवो नैव वृद्धमार्यमनुस्मरत्।
स ममार्थाय कुशलं वक्तव्यो वचनान्मम।
मृदुर्नित्यं शुचिर्दक्षः प्रियो रामस्य लक्ष्मणः॥', 'yaṃ dṛṣṭvā rāghavo naiva vṛddham āryam anusmarat
sa mamārthāya kuśalaṃ vaktavyo vacanān mama
mṛdur nityaṃ śucir dakṣaḥ priyo rāmasya lakṣmaṇaḥ', null, 5036049),
('ramayana-5-36-50', 50, 'Sundara Kanda, Sarga 36, Verse 50', 'इदं ब्रूयाश्च मे नाथं शूरं रामं पुनः पुनः।
जीवितं धारयिष्यामि मासं दशरथात्मज।
ऊर्ध्वं मासान्न जीवेयं सत्येनाहं ब्रवीमि ते॥', 'idaṃ brūyāś ca me nāthaṃ śūraṃ rāmaṃ punaḥ punaḥ
jīvitaṃ dhārayiṣyāmi māsaṃ daśarathātmaja
ūrdhvaṃ māsān na jīveyaṃ satyenāhaṃ bravīmi te', null, 5036050),
('ramayana-5-36-51', 51, 'Sundara Kanda, Sarga 36, Verse 51', 'रावणेनोपरुद्धां मां निकृत्या पापकर्मणा।
त्रातुमर्हसि वीर त्वं पातालादिव कौशिकीम्॥', 'rāvaṇenoparuddhāṃ māṃ nikṛtyā pāpakarmaṇā
trātum arhasi vīra tvaṃ pātālād iva kauśikīm', null, 5036051),
('ramayana-5-36-52', 52, 'Sundara Kanda, Sarga 36, Verse 52', 'ततो वस्त्रगतं मुक्त्वा दिव्यं चूडामणिं शुभम्।
प्रदेयो राघवायेति सीता हनुमते ददौ॥', 'tato vastragataṃ muktvā divyaṃ cūḍāmaṇiṃ śubham
pradeyo rāghavāyeti sītā hanumate dadau', null, 5036052),
('ramayana-5-36-53', 53, 'Sundara Kanda, Sarga 36, Verse 53', 'प्रतिगृह्य ततो वीरो मणिरत्नमनुत्तमम्।
अङ्गुल्या योजयामास न ह्यस्या प्राभवद्भुजः॥', 'pratigṛhya tato vīro maṇiratnam anuttamam
aṅgulyā yojayām āsa na hy asyā prābhavad bhujaḥ', null, 5036053),
('ramayana-5-36-54', 54, 'Sundara Kanda, Sarga 36, Verse 54', 'मणिरत्नं कपिवरः प्रतिगृह्याभिवाद्य च।
सीतां प्रदक्षिणं कृत्वा प्रणतः पार्श्वतः स्थितः॥', 'maṇiratnaṃ kapivaraḥ pratigṛhyābhivādya ca
sītāṃ pradakṣiṇaṃ kṛtvā praṇataḥ pārśvataḥ sthitaḥ', null, 5036054),
('ramayana-5-36-55', 55, 'Sundara Kanda, Sarga 36, Verse 55', 'हर्षेण महता युक्तः सीतादर्शनजेन सः।
हृदयेन गतो रामं शरीरेण तु विष्ठितः॥', 'harṣeṇa mahatā yuktaḥ sītādarśanajena saḥ
hṛdayena gato rāmaṃ śarīreṇa tu viṣṭhitaḥ', null, 5036055),
('ramayana-5-36-56', 56, 'Sundara Kanda, Sarga 36, Verse 56', 'मणिवरमुपगृह्य तं महार्हं जनकनृपात्मजया धृतं प्रभावात्।
गिरिवरपवनावधूतमुक्तः सुखितमनाः प्रतिसंक्रमं प्रपेदे॥', 'maṇivaram upagṛhya taṃ mahārhaṃ janakanṛpātmajayā dhṛtaṃ prabhāvāt
girivarapavanāvadhūtamuktaḥ sukhitamanāḥ pratisaṃkramaṃ prapede', null, 5036056)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 37 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-37-1', 1, 'Sundara Kanda, Sarga 37, Verse 1', 'मणिं दत्त्वा ततः सीता हनूमन्तमथाब्रवीत्।
अभिज्ञानमभिज्ञातमेतद्रामस्य तत्त्वतः॥', 'maṇiṃ dattvā tataḥ sītā hanūmantam athābravīt
abhijñānam abhijñātam etad rāmasya tattvataḥ', null, 5037001),
('ramayana-5-37-2', 2, 'Sundara Kanda, Sarga 37, Verse 2', 'मणिं तु दृष्ट्वा रामो वै त्रयाणां संस्मरिष्यति।
वीरो जनन्या मम च राज्ञो दशरथस्य च॥', 'maṇiṃ tu dṛṣṭvā rāmo vai trayāṇāṃ saṃsmariṣyati
vīro jananyā mama ca rājño daśarathasya ca', null, 5037002),
('ramayana-5-37-3', 3, 'Sundara Kanda, Sarga 37, Verse 3', 'स भूयस्त्वं समुत्साहे चोदितो हरिसत्तम।
अस्मिन्कार्यसमारम्भे प्रचिन्तय यदुत्तरम्॥', 'sa bhūyas tvaṃ samutsāhe codito harisattama
asmin kāryasamārambhe pracintaya yaduttaram', null, 5037003),
('ramayana-5-37-4', 4, 'Sundara Kanda, Sarga 37, Verse 4', 'त्वमस्मिन्कार्यनिर्योगे प्रमाणं हरिसत्तम।
तस्य चिन्तय यो यत्नो दुःखक्षयकरो भवेत्॥', 'tvam asmin kāryaniryoge pramāṇaṃ harisattama
tasya cintaya yo yatno duḥkhakṣayakaro bhavet', null, 5037004),
('ramayana-5-37-5', 5, 'Sundara Kanda, Sarga 37, Verse 5', 'स तथेति प्रतिज्ञाय मारुतिर्भीमविक्रमः।
शिरसावन्द्य वैदेहीं गमनायोपचक्रमे॥', 'sa tatheti pratijñāya mārutir bhīmavikramaḥ
śirasāvandya vaidehīṃ gamanāyopacakrame', null, 5037005),
('ramayana-5-37-6', 6, 'Sundara Kanda, Sarga 37, Verse 6', 'ज्ञात्वा संप्रस्थितं देवी वानरं मारुतात्मजम्।
बाष्पगद्गदया वाचा मैथिली वाक्यमब्रवीत्॥', 'jñātvā saṃprasthitaṃ devī vānaraṃ mārutātmajam
bāṣpagadgadayā vācā maithilī vākyam abravīt', null, 5037006),
('ramayana-5-37-7', 7, 'Sundara Kanda, Sarga 37, Verse 7', 'कुशलं हनुमन्ब्रूयाः सहितौ रामलक्ष्मणौ।
सुग्रीवं च सहामात्यं वृद्धान्सर्वांश्च वानरान्॥', 'kuśalaṃ hanuman brūyāḥ sahitau rāmalakṣmaṇau
sugrīvaṃ ca sahāmātyaṃ vṛddhān sarvāṃś ca vānarān', null, 5037007),
('ramayana-5-37-8', 8, 'Sundara Kanda, Sarga 37, Verse 8', 'यथा च स महाबाहुर्मां तारयति राघवः।
अस्माद्दुःखाम्बुसंरोधात्त्वं समाधातुमर्हसि॥', 'yathā ca sa mahābāhur māṃ tārayati rāghavaḥ
asmād duḥkhāmbusaṃrodhāt tvaṃ samādhātum arhasi', null, 5037008),
('ramayana-5-37-9', 9, 'Sundara Kanda, Sarga 37, Verse 9', 'जीवन्तीं मां यथा रामः संभावयति कीर्तिमान्।
तत्त्वया हनुमन्वाच्यं वाचा धर्ममवाप्नुहि॥', 'jīvantīṃ māṃ yathā rāmaḥ saṃbhāvayati kīrtimān
tat tvayā hanuman vācyaṃ vācā dharmam avāpnuhi', null, 5037009),
('ramayana-5-37-10', 10, 'Sundara Kanda, Sarga 37, Verse 10', 'नित्यमुत्साहयुक्ताश्च वाचः श्रुत्वा मयेरिताः।
वर्धिष्यते दाशरथेः पौरुषं मदवाप्तये॥', 'nityam utsāhayuktāś ca vācaḥ śrutvā mayeritāḥ
vardhiṣyate dāśaratheḥ pauruṣaṃ madavāptaye', null, 5037010),
('ramayana-5-37-11', 11, 'Sundara Kanda, Sarga 37, Verse 11', 'मत्संदेशयुता वाचस्त्वत्तः श्रुत्वैव राघवः।
पराक्रमविधिं वीरो विधिवत्संविधास्यति॥', 'matsaṃdeśayutā vācas tvattaḥ śrutvaiva rāghavaḥ
parākramavidhiṃ vīro vidhivat saṃvidhāsyati', null, 5037011),
('ramayana-5-37-12', 12, 'Sundara Kanda, Sarga 37, Verse 12', 'सीतायास्तद्वचः श्रुत्वा हनुमान्मारुतात्मजः।
शिरस्यञ्जलिमाधाय वाक्यमुत्तरमब्रवीत्॥', 'sītāyās tad vacaḥ śrutvā hanumān mārutātmajaḥ
śirasy añjalim ādhāya vākyam uttaram abravīt', null, 5037012),
('ramayana-5-37-13', 13, 'Sundara Kanda, Sarga 37, Verse 13', 'क्षिप्रमेष्यति काकुत्स्थो हर्यृक्षप्रवरैर्वृतः।
यस्ते युधि विजित्यारीञ्शोकं व्यपनयिष्यति॥', 'kṣipram eṣyati kākutstho haryṛkṣapravarair vṛtaḥ
yas te yudhi vijityārīñ śokaṃ vyapanayiṣyati', null, 5037013),
('ramayana-5-37-14', 14, 'Sundara Kanda, Sarga 37, Verse 14', 'न हि पश्यामि मर्त्येषु नामरेष्वसुरेषु वा।
यस्तस्य वमतो बाणान्स्थातुमुत्सहतेऽग्रतः॥', 'na hi paśyāmi martyeṣu nāmareṣv asureṣu vā
yas tasya vamato bāṇān sthātum utsahate ''grataḥ', null, 5037014),
('ramayana-5-37-15', 15, 'Sundara Kanda, Sarga 37, Verse 15', 'अप्यर्कमपि पर्जन्यमपि वैवस्वतं यमम्।
स हि सोढुं रणे शक्तस्तवहेतोर्विशेषतः॥', 'apy arkam api parjanyam api vaivasvataṃ yamam
sa hi soḍhuṃ raṇe śaktas tavahetor viśeṣataḥ', null, 5037015),
('ramayana-5-37-16', 16, 'Sundara Kanda, Sarga 37, Verse 16', 'स हि सागरपर्यन्तां महीं शासितुमीहते।
त्वन्निमित्तो हि रामस्य जयो जनकनन्दिनि॥', 'sa hi sāgaraparyantāṃ mahīṃ śāsitum īhate
tvan nimitto hi rāmasya jayo janakanandini', null, 5037016),
('ramayana-5-37-17', 17, 'Sundara Kanda, Sarga 37, Verse 17', 'तस्य तद्वचनं श्रुत्वा सम्यक्सत्यं सुभाषितम्।
जानकी बहु मेनेऽथ वचनं चेदमब्रवीत्॥', 'tasya tad vacanaṃ śrutvā samyak satyaṃ subhāṣitam
jānakī bahu mene ''tha vacanaṃ cedam abravīt', null, 5037017),
('ramayana-5-37-18', 18, 'Sundara Kanda, Sarga 37, Verse 18', 'ततस्तं प्रस्थितं सीता वीक्षमाणा पुनः पुनः।
भर्तुः स्नेहान्वितं वाक्यं सौहार्दादनुमानयत्॥', 'tatas taṃ prasthitaṃ sītā vīkṣamāṇā punaḥ punaḥ
bhartuḥ snehānvitaṃ vākyaṃ sauhārdād anumānayat', null, 5037018),
('ramayana-5-37-19', 19, 'Sundara Kanda, Sarga 37, Verse 19', 'यदि वा मन्यसे वीर वसैकाहमरिंदम।
कस्मिंश्चित्संवृते देशे विश्रान्तः श्वो गमिष्यसि॥', 'yadi vā manyase vīra vasaikāham ariṃdama
kasmiṃś cit saṃvṛte deśe viśrāntaḥ śvo gamiṣyasi', null, 5037019),
('ramayana-5-37-20', 20, 'Sundara Kanda, Sarga 37, Verse 20', 'मम चेदल्पभाग्यायाः साम्निध्यात्तव वीर्यवान्।
अस्य शोकस्य महतो मुहूर्तं मोक्षणं भवेत्॥', 'mama ced alpabhāgyāyāḥ sāmnidhyāt tava vīryavān
asya śokasya mahato muhūrtaṃ mokṣaṇaṃ bhavet', null, 5037020),
('ramayana-5-37-21', 21, 'Sundara Kanda, Sarga 37, Verse 21', 'गते हि हरिशार्दूल पुनरागमनाय तु।
प्राणानामपि संदेहो मम स्यान्नात्र संशयः॥', 'gate hi hariśārdūla punarāgamanāya tu
prāṇānām api saṃdeho mama syān nātra saṃśayaḥ', null, 5037021),
('ramayana-5-37-22', 22, 'Sundara Kanda, Sarga 37, Verse 22', 'तवादर्शनजः शोको भूयो मां परितापयेत्।
दुःखाद्दुःखपरामृष्टां दीपयन्निव वानर॥', 'tavādarśanajaḥ śoko bhūyo māṃ paritāpayet
duḥkhād duḥkhaparāmṛṣṭāṃ dīpayann iva vānara', null, 5037022),
('ramayana-5-37-23', 23, 'Sundara Kanda, Sarga 37, Verse 23', 'अयं च वीर संदेहस्तिष्ठतीव ममाग्रतः।
सुमहांस्त्वत्सहायेषु हर्यृक्षेषु हरीश्वर॥', 'ayaṃ ca vīra saṃdehas tiṣṭhatīva mamāgrataḥ
sumahāṃs tvatsahāyeṣu haryṛkṣeṣu harīśvara', null, 5037023),
('ramayana-5-37-24', 24, 'Sundara Kanda, Sarga 37, Verse 24', 'कथं नु खलु दुष्पारं तरिष्यन्ति महोदधिम्।
तानि हर्यृक्षसैन्यानि तौ वा नरवरात्मजौ॥', 'kathaṃ nu khalu duṣpāraṃ tariṣyanti mahodadhim
tāni haryṛkṣasainyāni tau vā naravarātmajau', null, 5037024),
('ramayana-5-37-25', 25, 'Sundara Kanda, Sarga 37, Verse 25', 'त्रयाणामेव भूतानां सागरस्येह लङ्घने।
शक्तिः स्याद्वैनतेयस्य तव वा मारुतस्य वा॥', 'trayāṇām eva bhūtānāṃ sāgarasyeha laṅghane
śaktiḥ syād vainateyasya tava vā mārutasya vā', null, 5037025),
('ramayana-5-37-26', 26, 'Sundara Kanda, Sarga 37, Verse 26', 'तदस्मिन्कार्यनिर्योगे वीरैवं दुरतिक्रमे।
किं पश्यसि समाधानं त्वं हि कार्यविदां वरः॥', 'tad asmin kāryaniryoge vīraivaṃ duratikrame
kiṃ paśyasi samādhānaṃ tvaṃ hi kāryavidāṃ varaḥ', null, 5037026),
('ramayana-5-37-27', 27, 'Sundara Kanda, Sarga 37, Verse 27', 'काममस्य त्वमेवैकः कार्यस्य परिसाधने।
पर्याप्तः परवीरघ्न यशस्यस्ते बलोदयः॥', 'kāmam asya tvam evaikaḥ kāryasya parisādhane
paryāptaḥ paravīraghna yaśasyas te balodayaḥ', null, 5037027),
('ramayana-5-37-28', 28, 'Sundara Kanda, Sarga 37, Verse 28', 'बलैः समग्रैर्यदि मां रावणं जित्य संयुगे।
विजयी स्वपुरं यायात्तत्तु मे स्याद्यशस्करम्॥', 'balaiḥ samagrair yadi māṃ rāvaṇaṃ jitya saṃyuge
vijayī svapuraṃ yāyāt tat tu me syād yaśaskaram', null, 5037028),
('ramayana-5-37-29', 29, 'Sundara Kanda, Sarga 37, Verse 29', 'बलैस्तु संकुलां कृत्वा लङ्कां परबलार्दनः।
मां नयेद्यदि काकुत्स्थस्तत्तस्य सदृशं भवेत्॥', 'balais tu saṃkulāṃ kṛtvā laṅkāṃ parabalārdanaḥ
māṃ nayed yadi kākutsthas tat tasya sadṛśaṃ bhavet', null, 5037029),
('ramayana-5-37-30', 30, 'Sundara Kanda, Sarga 37, Verse 30', 'तद्यथा तस्य विक्रान्तमनुरूपं महात्मनः।
भवेदाहव शूरस्य तथा त्वमुपपादय॥', 'tad yathā tasya vikrāntam anurūpaṃ mahātmanaḥ
bhaved āhava śūrasya tathā tvam upapādaya', null, 5037030),
('ramayana-5-37-31', 31, 'Sundara Kanda, Sarga 37, Verse 31', 'तदर्थोपहितं वाक्यं सहितं हेतुसंहितम्।
निशम्य हनुमाञ्शेषं वाक्यमुत्तरमब्रवीत्॥', 'tad arthopahitaṃ vākyaṃ sahitaṃ hetusaṃhitam
niśamya hanumāñ śeṣaṃ vākyam uttaram abravīt', null, 5037031),
('ramayana-5-37-32', 32, 'Sundara Kanda, Sarga 37, Verse 32', 'देवि हर्यृक्षसैन्यानामीश्वरः प्लवतां वरः।
सुग्रीवः सत्त्वसंपन्नस्तवार्थे कृतनिश्चयः॥', 'devi haryṛkṣasainyānām īśvaraḥ plavatāṃ varaḥ
sugrīvaḥ sattvasaṃpannas tavārthe kṛtaniścayaḥ', null, 5037032),
('ramayana-5-37-33', 33, 'Sundara Kanda, Sarga 37, Verse 33', 'स वानरसहस्राणां कोटीभिरभिसंवृतः।
क्षिप्रमेष्यति वैदेहि राक्षसानां निबर्हणः॥', 'sa vānarasahasrāṇāṃ koṭībhir abhisaṃvṛtaḥ
kṣipram eṣyati vaidehi rākṣasānāṃ nibarhaṇaḥ', null, 5037033),
('ramayana-5-37-34', 34, 'Sundara Kanda, Sarga 37, Verse 34', 'तस्य विक्रमसंपन्नाः सत्त्ववन्तो महाबलाः।
मनःसंकल्पसंपाता निदेशे हरयः स्थिताः॥', 'tasya vikramasaṃpannāḥ sattvavanto mahābalāḥ
manaḥsaṃkalpasaṃpātā nideśe harayaḥ sthitāḥ', null, 5037034),
('ramayana-5-37-35', 35, 'Sundara Kanda, Sarga 37, Verse 35', 'येषां नोपरि नाधस्तान्न तिर्यक्सज्जते गतिः।
न च कर्मसु सीदन्ति महत्स्वमिततेजसः॥', 'yeṣāṃ nopari nādhastān na tiryak sajjate gatiḥ
na ca karmasu sīdanti mahatsv amitatejasaḥ', null, 5037035),
('ramayana-5-37-36', 36, 'Sundara Kanda, Sarga 37, Verse 36', 'असकृत्तैर्महोत्सहैः ससागरधराधरा।
प्रदक्षिणीकृता भूमिर्वायुमार्गानुसारिभिः॥', 'asakṛt tair mahotsahaiḥ sasāgaradharādharā
pradakṣiṇīkṛtā bhūmir vāyumārgānusāribhiḥ', null, 5037036),
('ramayana-5-37-37', 37, 'Sundara Kanda, Sarga 37, Verse 37', 'मद्विशिष्टाश्च तुल्याश्च सन्ति तत्र वनौकसः।
मत्तः प्रत्यवरः कश्चिन्नास्ति सुग्रीवसंनिधौ॥', 'madviśiṣṭāś ca tulyāś ca santi tatra vanaukasaḥ
mattaḥ pratyavaraḥ kaś cin nāsti sugrīvasaṃnidhau', null, 5037037),
('ramayana-5-37-38', 38, 'Sundara Kanda, Sarga 37, Verse 38', 'अहं तावदिह प्राप्तः किं पुनस्ते महाबलाः।
न हि प्रकृष्टाः प्रेष्यन्ते प्रेष्यन्ते हीतरे जनाः॥', 'ahaṃ tāvad iha prāptaḥ kiṃ punas te mahābalāḥ
na hi prakṛṣṭāḥ preṣyante preṣyante hītare janāḥ', null, 5037038),
('ramayana-5-37-39', 39, 'Sundara Kanda, Sarga 37, Verse 39', 'तदलं परितापेन देवि शोको व्यपैतु ते।
एकोत्पातेन ते लङ्कामेष्यन्ति हरियूथपाः॥', 'tad alaṃ paritāpena devi śoko vyapaitu te
ekotpātena te laṅkām eṣyanti hariyūthapāḥ', null, 5037039),
('ramayana-5-37-40', 40, 'Sundara Kanda, Sarga 37, Verse 40', 'मम पृष्ठगतौ तौ च चन्द्रसूर्याविवोदितौ।
त्वत्सकाशं महासत्त्वौ नृसिंहावागमिष्यतः॥', 'mama pṛṣṭhagatau tau ca candrasūryāv ivoditau
tvatsakāśaṃ mahāsattvau nṛsiṃhāv āgamiṣyataḥ', null, 5037040),
('ramayana-5-37-41', 41, 'Sundara Kanda, Sarga 37, Verse 41', 'तौ हि वीरौ नरवरौ सहितौ रामलक्ष्मणौ।
आगम्य नगरीं लङ्कां सायकैर्विधमिष्यतः॥', 'tau hi vīrau naravarau sahitau rāmalakṣmaṇau
āgamya nagarīṃ laṅkāṃ sāyakair vidhamiṣyataḥ', null, 5037041),
('ramayana-5-37-42', 42, 'Sundara Kanda, Sarga 37, Verse 42', 'सगणं रावणं हत्वा राघवो रघुनन्दनः।
त्वामादाय वरारोहे स्वपुरं प्रतियास्यति॥', 'sagaṇaṃ rāvaṇaṃ hatvā rāghavo raghunandanaḥ
tvām ādāya varārohe svapuraṃ pratiyāsyati', null, 5037042),
('ramayana-5-37-43', 43, 'Sundara Kanda, Sarga 37, Verse 43', 'तदाश्वसिहि भद्रं ते भव त्वं कालकाङ्क्षिणी।
नचिराद्द्रक्ष्यसे रामं प्रज्वजन्तमिवानिलम्॥', 'tad āśvasihi bhadraṃ te bhava tvaṃ kālakāṅkṣiṇī
nacirād drakṣyase rāmaṃ prajvajantam ivānilam', null, 5037043),
('ramayana-5-37-44', 44, 'Sundara Kanda, Sarga 37, Verse 44', 'निहते राक्षसेन्द्रे च सपुत्रामात्यबान्धवे।
त्वं समेष्यसि रामेण शशाङ्केनेव रोहिणी॥', 'nihate rākṣasendre ca saputrāmātyabāndhave
tvaṃ sameṣyasi rāmeṇa śaśāṅkeneva rohiṇī', null, 5037044),
('ramayana-5-37-45', 45, 'Sundara Kanda, Sarga 37, Verse 45', 'क्षिप्रं त्वं देवि शोकस्य पारं यास्यसि मैथिलि।
रावणं चैव रामेण निहतं द्रक्ष्यसेऽचिरात्॥', 'kṣipraṃ tvaṃ devi śokasya pāraṃ yāsyasi maithili
rāvaṇaṃ caiva rāmeṇa nihataṃ drakṣyase ''cirāt', null, 5037045),
('ramayana-5-37-46', 46, 'Sundara Kanda, Sarga 37, Verse 46', 'एवमाश्वस्य वैदेहीं हनूमान्मारुतात्मजः।
गमनाय मतिं कृत्वा वैदेहीं पुनरब्रवीत्॥', 'evam āśvasya vaidehīṃ hanūmān mārutātmajaḥ
gamanāya matiṃ kṛtvā vaidehīṃ punar abravīt', null, 5037046),
('ramayana-5-37-47', 47, 'Sundara Kanda, Sarga 37, Verse 47', 'तमरिघ्नं कृतात्मानं क्षिप्रं द्रक्ष्यसि राघवम्।
लक्ष्मणं च धनुष्पाणिं लङ्काद्वारमुपस्थितम्॥', 'tam arighnaṃ kṛtātmānaṃ kṣipraṃ drakṣyasi rāghavam
lakṣmaṇaṃ ca dhanuṣpāṇiṃ laṅkādvāram upasthitam', null, 5037047),
('ramayana-5-37-48', 48, 'Sundara Kanda, Sarga 37, Verse 48', 'नखदंष्ट्रायुधान्वीरान्सिंहशार्दूलविक्रमान्।
वानरान्वारणेन्द्राभान्क्षिप्रं द्रक्ष्यसि संगतान्॥', 'nakhadaṃṣṭrāyudhān vīrān siṃhaśārdūlavikramān
vānarān vāraṇendrābhān kṣipraṃ drakṣyasi saṃgatān', null, 5037048),
('ramayana-5-37-49', 49, 'Sundara Kanda, Sarga 37, Verse 49', 'शैलाम्बुदनिकाशानां लङ्कामलयसानुषु।
नर्दतां कपिमुख्यानामार्ये यूथान्यनेकशः॥', 'śailāmbudanikāśānāṃ laṅkāmalayasānuṣu
nardatāṃ kapimukhyānām ārye yūthāny anekaśaḥ', null, 5037049),
('ramayana-5-37-50', 50, 'Sundara Kanda, Sarga 37, Verse 50', 'स तु मर्मणि घोरेण ताडितो मन्मथेषुणा।
न शर्म लभते रामः सिंहार्दित इव द्विपः॥', 'sa tu marmaṇi ghoreṇa tāḍito manmatheṣuṇā
na śarma labhate rāmaḥ siṃhārdita iva dvipaḥ', null, 5037050),
('ramayana-5-37-51', 51, 'Sundara Kanda, Sarga 37, Verse 51', 'मा रुदो देवि शोकेन मा भूत्ते मनसोऽप्रियम्।
शचीव पथ्या शक्रेण भर्त्रा नाथवती ह्यसि॥', 'mā rudo devi śokena mā bhūt te manaso ''priyam
śacīva pathyā śakreṇa bhartrā nāthavatī hy asi', null, 5037051),
('ramayana-5-37-52', 52, 'Sundara Kanda, Sarga 37, Verse 52', 'रामाद्विशिष्टः कोऽन्योऽस्ति कश्चित्सौमित्रिणा समः।
अग्निमारुतकल्पौ तौ भ्रातरौ तव संश्रयौ॥', 'rāmād viśiṣṭaḥ ko ''nyo ''sti kaś cit saumitriṇā samaḥ
agnimārutakalpau tau bhrātarau tava saṃśrayau', null, 5037052),
('ramayana-5-37-53', 53, 'Sundara Kanda, Sarga 37, Verse 53', 'नास्मिंश्चिरं वत्स्यसि देवि देशे रक्षोगणैरध्युषितोऽतिरौद्रे।
न ते चिरादागमनं प्रियस्य क्षमस्व मत्संगमकालमात्रम्॥', 'nāsmiṃś ciraṃ vatsyasi devi deśe rakṣogaṇair adhyuṣito ''tiraudre
na te cirād āgamanaṃ priyasya kṣamasva matsaṃgamakālamātram', null, 5037053)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 38 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-38-1', 1, 'Sundara Kanda, Sarga 38, Verse 1', 'श्रुत्वा तु वचनं तस्य वायुसूनोर्महात्मनः।
उवाचात्महितं वाक्यं सीता सुरसुतोपमा॥', 'śrutvā tu vacanaṃ tasya vāyusūnor mahātmanaḥ
uvācātmahitaṃ vākyaṃ sītā surasutopamā', null, 5038001),
('ramayana-5-38-2', 2, 'Sundara Kanda, Sarga 38, Verse 2', 'त्वां दृष्ट्वा प्रियवक्तारं संप्रहृष्यामि वानर।
अर्धसंजातसस्येव वृष्टिं प्राप्य वसुंधरा॥', 'tvāṃ dṛṣṭvā priyavaktāraṃ saṃprahṛṣyāmi vānara
ardhasaṃjātasasyeva vṛṣṭiṃ prāpya vasuṃdharā', null, 5038002),
('ramayana-5-38-3', 3, 'Sundara Kanda, Sarga 38, Verse 3', 'यथा तं पुरुषव्याघ्रं गात्रैः शोकाभिकर्शितैः।
संस्पृशेयं सकामाहं तथा कुरु दयां मयि॥', 'yathā taṃ puruṣavyāghraṃ gātraiḥ śokābhikarśitaiḥ
saṃspṛśeyaṃ sakāmāhaṃ tathā kuru dayāṃ mayi', null, 5038003),
('ramayana-5-38-4', 4, 'Sundara Kanda, Sarga 38, Verse 4', 'अभिज्ञानं च रामस्य दत्तं हरिगणोत्तम।
क्षिप्तामीषिकां काकस्य कोपादेकाक्षिशातनीम्॥', 'abhijñānaṃ ca rāmasya dattaṃ harigaṇottama
kṣiptām īṣikāṃ kākasya kopād ekākṣiśātanīm', null, 5038004),
('ramayana-5-38-5', 5, 'Sundara Kanda, Sarga 38, Verse 5', 'मनःशिलायास्तिकलो गण्डपार्श्वे निवेशितः।
त्वया प्रनष्टे तिलके तं किल स्मर्तुमर्हसि॥', 'manaḥśilāyās tikalo gaṇḍapārśve niveśitaḥ
tvayā pranaṣṭe tilake taṃ kila smartum arhasi', null, 5038005),
('ramayana-5-38-6', 6, 'Sundara Kanda, Sarga 38, Verse 6', 'स वीर्यवान्कथं सीतां हृतां समनुमन्यसे।
वसन्तीं रक्षसां मध्ये महेन्द्रवरुणोपम॥', 'sa vīryavān kathaṃ sītāṃ hṛtāṃ samanumanyase
vasantīṃ rakṣasāṃ madhye mahendravaruṇopama', null, 5038006),
('ramayana-5-38-7', 7, 'Sundara Kanda, Sarga 38, Verse 7', 'एष चूडामणिर्दिव्यो मया सुपरिरक्षितः।
एतं दृष्ट्वा प्रहृष्यामि व्यसने त्वामिवानघ॥', 'eṣa cūḍāmaṇir divyo mayā suparirakṣitaḥ
etaṃ dṛṣṭvā prahṛṣyāmi vyasane tvām ivānagha', null, 5038007),
('ramayana-5-38-8', 8, 'Sundara Kanda, Sarga 38, Verse 8', 'एष निर्यातितः श्रीमान्मया ते वारिसंभवः।
अतः परं न शक्ष्यामि जीवितुं शोकलालसा॥', 'eṣa niryātitaḥ śrīmān mayā te vārisaṃbhavaḥ
ataḥ paraṃ na śakṣyāmi jīvituṃ śokalālasā', null, 5038008),
('ramayana-5-38-9', 9, 'Sundara Kanda, Sarga 38, Verse 9', 'असह्यानि च दुःखानि वाचश्च हृदयच्छिदः।
राक्षसीनां सुघोराणां त्वत्कृते मर्षयाम्यहम्॥', 'asahyāni ca duḥkhāni vācaś ca hṛdayacchidaḥ
rākṣasīnāṃ sughorāṇāṃ tvatkṛte marṣayāmy aham', null, 5038009),
('ramayana-5-38-10', 10, 'Sundara Kanda, Sarga 38, Verse 10', 'धारयिष्यामि मासं तु जीवितं शत्रुसूदन।
मासादूर्ध्वं न जीविष्ये त्वया हीना नृपात्मज॥', 'dhārayiṣyāmi māsaṃ tu jīvitaṃ śatrusūdana
māsād ūrdhvaṃ na jīviṣye tvayā hīnā nṛpātmaja', null, 5038010),
('ramayana-5-38-11', 11, 'Sundara Kanda, Sarga 38, Verse 11', 'घोरो राक्षसराजोऽयं दृष्टिश्च न सुखा मयि।
त्वां च श्रुत्वा विपद्यन्तं न जीवेयमहं क्षणम्॥', 'ghoro rākṣasarājo ''yaṃ dṛṣṭiś ca na sukhā mayi
tvāṃ ca śrutvā vipadyantaṃ na jīveyam ahaṃ kṣaṇam', null, 5038011),
('ramayana-5-38-12', 12, 'Sundara Kanda, Sarga 38, Verse 12', 'वैदेह्या वचनं श्रुत्वा करुणं साश्रुभाषितम्।
अथाब्रवीन्महातेजा हनुमान्मारुतात्मजः॥', 'vaidehyā vacanaṃ śrutvā karuṇaṃ sāśrubhāṣitam
athābravīn mahātejā hanumān mārutātmajaḥ', null, 5038012),
('ramayana-5-38-13', 13, 'Sundara Kanda, Sarga 38, Verse 13', 'त्वच्छोकविमुखो रामो देवि सत्येन ते शपे।
रामे शोकाभिभूते तु लक्ष्मणः परितप्यते॥', 'tvacchokavimukho rāmo devi satyena te śape
rāme śokābhibhūte tu lakṣmaṇaḥ paritapyate', null, 5038013),
('ramayana-5-38-14', 14, 'Sundara Kanda, Sarga 38, Verse 14', 'दृष्टा कथं चिद्भवती न कालः परिशोचितुम्।
इमं मुहूर्तं दुःखानामन्तं द्रक्ष्यसि भामिनि॥', 'dṛṣṭā kathaṃ cid bhavatī na kālaḥ pariśocitum
imaṃ muhūrtaṃ duḥkhānām antaṃ drakṣyasi bhāmini', null, 5038014),
('ramayana-5-38-15', 15, 'Sundara Kanda, Sarga 38, Verse 15', 'तावुभौ पुरुषव्याघ्रौ राजपुत्रावनिन्दितौ।
त्वद्दर्शनकृतोत्साहौ लङ्कां भस्मीकरिष्यतः॥', 'tāv ubhau puruṣavyāghrau rājaputrāv aninditau
tvaddarśanakṛtotsāhau laṅkāṃ bhasmīkariṣyataḥ', null, 5038015),
('ramayana-5-38-16', 16, 'Sundara Kanda, Sarga 38, Verse 16', 'हत्वा तु समरे क्रूरं रावणं सह बान्धवम्।
राघवौ त्वां विशालाक्षि स्वां पुरीं प्रापयिष्यतः॥', 'hatvā tu samare krūraṃ rāvaṇaṃ saha bāndhavam
rāghavau tvāṃ viśālākṣi svāṃ purīṃ prāpayiṣyataḥ', null, 5038016),
('ramayana-5-38-17', 17, 'Sundara Kanda, Sarga 38, Verse 17', 'यत्तु रामो विजानीयादभिज्ञानमनिन्दिते।
प्रीतिसंजननं तस्य भूयस्त्वं दातुमर्हसि॥', 'yat tu rāmo vijānīyād abhijñānam anindite
prītisaṃjananaṃ tasya bhūyas tvaṃ dātum arhasi', null, 5038017),
('ramayana-5-38-18', 18, 'Sundara Kanda, Sarga 38, Verse 18', 'साब्रवीद्दत्तमेवेह मयाभिज्ञानमुत्तमम्।
एतदेव हि रामस्य दृष्ट्वा मत्केशभूषणम्।
श्रद्धेयं हनुमन्वाक्यं तव वीर भविष्यति॥', 'sābravīd dattam eveha mayābhijñānam uttamam
etad eva hi rāmasya dṛṣṭvā matkeśabhūṣaṇam
śraddheyaṃ hanuman vākyaṃ tava vīra bhaviṣyati', null, 5038018),
('ramayana-5-38-19', 19, 'Sundara Kanda, Sarga 38, Verse 19', 'स तं मणिवरं गृह्य श्रीमान्प्लवगसत्तमः।
प्रणम्य शिरसा देवीं गमनायोपचक्रमे॥', 'sa taṃ maṇivaraṃ gṛhya śrīmān plavagasattamaḥ
praṇamya śirasā devīṃ gamanāyopacakrame', null, 5038019),
('ramayana-5-38-20', 20, 'Sundara Kanda, Sarga 38, Verse 20', 'तमुत्पातकृतोत्साहमवेक्ष्य हरिपुंगवम्।
वर्धमानं महावेगमुवाच जनकात्मजा।
अश्रुपूर्णमुखी दीना बाष्पगद्गदया गिरा॥', 'tam utpātakṛtotsāham avekṣya haripuṃgavam
vardhamānaṃ mahāvegam uvāca janakātmajā
aśrupūrṇamukhī dīnā bāṣpagadgadayā girā', null, 5038020),
('ramayana-5-38-21', 21, 'Sundara Kanda, Sarga 38, Verse 21', 'हनूमन्सिंहसंकाशौ भ्रातरौ रामलक्ष्मणौ।
सुग्रीवं च सहामात्यं सर्वान्ब्रूया अनामयम्॥', 'hanūman siṃhasaṃkāśau bhrātarau rāmalakṣmaṇau
sugrīvaṃ ca sahāmātyaṃ sarvān brūyā anāmayam', null, 5038021),
('ramayana-5-38-22', 22, 'Sundara Kanda, Sarga 38, Verse 22', 'यथा च स महाबाहुर्मां तारयति राघवः।
अस्माद्दुःखाम्बुसंरोधात्तत्समाधातुमर्हसि॥', 'yathā ca sa mahābāhur māṃ tārayati rāghavaḥ
asmād duḥkhāmbusaṃrodhāt tat samādhātum arhasi', null, 5038022),
('ramayana-5-38-23', 23, 'Sundara Kanda, Sarga 38, Verse 23', 'इमं च तीव्रं मम शोकवेगं रक्षोभिरेभिः परिभर्त्सनं च।
ब्रूयास्तु रामस्य गतः समीपं शिवश्च तेऽध्वास्तु हरिप्रवीर॥', 'imaṃ ca tīvraṃ mama śokavegaṃ rakṣobhir ebhiḥ paribhartsanaṃ ca
brūyās tu rāmasya gataḥ samīpaṃ śivaś ca te ''dhvāstu haripravīra', null, 5038023),
('ramayana-5-38-24', 24, 'Sundara Kanda, Sarga 38, Verse 24', 'स राजपुत्र्या प्रतिवेदितार्थः कपिः कृतार्थः परिहृष्टचेताः।
तदल्पशेषं प्रसमीक्ष्य कार्यं दिशं ह्युदीचीं मनसा जगाम॥', 'sa rājaputryā prativeditārthaḥ kapiḥ kṛtārthaḥ parihṛṣṭacetāḥ
tad alpaśeṣaṃ prasamīkṣya kāryaṃ diśaṃ hy udīcīṃ manasā jagāma', null, 5038024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 39 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-39-1', 1, 'Sundara Kanda, Sarga 39, Verse 1', 'स च वाग्भिः प्रशस्ताभिर्गमिष्यन्पूजितस्तया।
तस्माद्देशादपक्रम्य चिन्तयामास वानरः॥', 'sa ca vāgbhiḥ praśastābhir gamiṣyan pūjitas tayā
tasmād deśād apakramya cintayām āsa vānaraḥ', null, 5039001),
('ramayana-5-39-2', 2, 'Sundara Kanda, Sarga 39, Verse 2', 'अल्पशेषमिदं कार्यं दृष्टेयमसितेक्षणा।
त्रीनुपायानतिक्रम्य चतुर्थ इह दृश्यते॥', 'alpaśeṣam idaṃ kāryaṃ dṛṣṭeyam asitekṣaṇā
trīn upāyān atikramya caturtha iha dṛśyate', null, 5039002),
('ramayana-5-39-3', 3, 'Sundara Kanda, Sarga 39, Verse 3', 'न साम रक्षःसु गुणाय कल्पते न दनमर्थोपचितेषु वर्तते।
न भेदसाध्या बलदर्पिता जनाः पराक्रमस्त्वेष ममेह रोचते॥', 'na sāma rakṣaḥsu guṇāya kalpate na danam arthopaciteṣu vartate
na bhedasādhyā baladarpitā janāḥ parākramas tv eṣa mameha rocate', null, 5039003),
('ramayana-5-39-4', 4, 'Sundara Kanda, Sarga 39, Verse 4', 'न चास्य कार्यस्य पराक्रमादृते विनिश्चयः कश्चिदिहोपपद्यते।
हृतप्रवीरास्तु रणे हि राक्षसाः कथं चिदीयुर्यदिहाद्य मार्दवम्॥', 'na cāsya kāryasya parākramād ṛte viniścayaḥ kaś cid ihopapadyate
hṛtapravīrās tu raṇe hi rākṣasāḥ kathaṃ cid īyur yad ihādya mārdavam', null, 5039004),
('ramayana-5-39-5', 5, 'Sundara Kanda, Sarga 39, Verse 5', 'कार्ये कर्मणि निर्दिष्टो यो बहून्यपि साधयेत्।
पूर्वकार्यविरोधेन स कार्यं कर्तुमर्हति॥', 'kārye karmaṇi nirdiṣṭo yo bahūny api sādhayet
pūrvakāryavirodhena sa kāryaṃ kartum arhati', null, 5039005),
('ramayana-5-39-6', 6, 'Sundara Kanda, Sarga 39, Verse 6', 'न ह्येकः साधको हेतुः स्वल्पस्यापीह कर्मणः।
यो ह्यर्थं बहुधा वेद स समर्थोऽर्थसाधने॥', 'na hy ekaḥ sādhako hetuḥ svalpasyāpīha karmaṇaḥ
yo hy arthaṃ bahudhā veda sa samartho ''rthasādhane', null, 5039006),
('ramayana-5-39-7', 7, 'Sundara Kanda, Sarga 39, Verse 7', 'इहैव तावत्कृतनिश्चयो ह्यहं यदि व्रजेयं प्लवगेश्वरालयम्।
परात्मसंमर्द विशेषतत्त्ववित्ततः कृतं स्यान्मम भर्तृशासनम्॥', 'ihaiva tāvat kṛtaniścayo hy ahaṃ yadi vrajeyaṃ plavageśvarālayam
parātmasaṃmarda viśeṣatattvavit tataḥ kṛtaṃ syān mama bhartṛśāsanam', null, 5039007),
('ramayana-5-39-8', 8, 'Sundara Kanda, Sarga 39, Verse 8', 'कथं नु खल्वद्य भवेत्सुखागतं प्रसह्य युद्धं मम राक्षसैः सह।
तथैव खल्वात्मबलं च सारवत्समानयेन्मां च रणे दशाननः॥', 'kathaṃ nu khalv adya bhavet sukhāgataṃ prasahya yuddhaṃ mama rākṣasaiḥ saha
tathaiva khalv ātmabalaṃ ca sāravat samānayen māṃ ca raṇe daśānanaḥ', null, 5039008),
('ramayana-5-39-9', 9, 'Sundara Kanda, Sarga 39, Verse 9', 'इदमस्य नृशंसस्य नन्दनोपममुत्तमम्।
वनं नेत्रमनःकान्तं नानाद्रुमलतायुतम्॥', 'idam asya nṛśaṃsasya nandanopamam uttamam
vanaṃ netramanaḥkāntaṃ nānādrumalatāyutam', null, 5039009),
('ramayana-5-39-10', 10, 'Sundara Kanda, Sarga 39, Verse 10', 'इदं विध्वंसयिष्यामि शुष्कं वनमिवानलः।
अस्मिन्भग्ने ततः कोपं करिष्यति स रावणः॥', 'idaṃ vidhvaṃsayiṣyāmi śuṣkaṃ vanam ivānalaḥ
asmin bhagne tataḥ kopaṃ kariṣyati sa rāvaṇaḥ', null, 5039010),
('ramayana-5-39-11', 11, 'Sundara Kanda, Sarga 39, Verse 11', 'ततो महत्साश्वमहारथद्विपं बलं समानेष्वपि राक्षसाधिपः।
त्रिशूलकालायसपट्टिशायुधं ततो महद्युद्धमिदं भविष्यति॥', 'tato mahat sāśvamahārathadvipaṃ balaṃ samāneṣv api rākṣasādhipaḥ
triśūlakālāyasapaṭṭiśāyudhaṃ tato mahad yuddham idaṃ bhaviṣyati', null, 5039011),
('ramayana-5-39-12', 12, 'Sundara Kanda, Sarga 39, Verse 12', 'अहं तु तैः संयति चण्डविक्रमैः समेत्य रक्षोभिरसंगविक्रमः।
निहत्य तद्रावणचोदितं बलं सुखं गमिष्यामि कपीश्वरालयम्॥', 'ahaṃ tu taiḥ saṃyati caṇḍavikramaiḥ sametya rakṣobhir asaṃgavikramaḥ
nihatya tad rāvaṇacoditaṃ balaṃ sukhaṃ gamiṣyāmi kapīśvarālayam', null, 5039012),
('ramayana-5-39-13', 13, 'Sundara Kanda, Sarga 39, Verse 13', 'ततो मारुतवत्क्रुद्धो मारुतिर्भीमविक्रमः।
ऊरुवेगेन महता द्रुमान्क्षेप्तुमथारभत्॥', 'tato mārutavat kruddho mārutir bhīmavikramaḥ
ūruvegena mahatā drumān kṣeptum athārabhat', null, 5039013),
('ramayana-5-39-14', 14, 'Sundara Kanda, Sarga 39, Verse 14', 'ततस्तद्धनुमान्वीरो बभञ्ज प्रमदावनम्।
मत्तद्विजसमाघुष्टं नानाद्रुमलतायुतम्॥', 'tatas tad dhanumān vīro babhañja pramadāvanam
mattadvijasamāghuṣṭaṃ nānādrumalatāyutam', null, 5039014),
('ramayana-5-39-15', 15, 'Sundara Kanda, Sarga 39, Verse 15', 'तद्वनं मथितैर्वृक्षैर्भिन्नैश्च सलिलाशयैः।
चूर्णितैः पर्वताग्रैश्च बभूवाप्रियदर्शनम्॥', 'tad vanaṃ mathitair vṛkṣair bhinnaiś ca salilāśayaiḥ
cūrṇitaiḥ parvatāgraiś ca babhūvāpriyadarśanam', null, 5039015),
('ramayana-5-39-16', 16, 'Sundara Kanda, Sarga 39, Verse 16', 'लतागृहैश्चित्रगृहैश्च नाशितैर्महोरगैर्व्यालमृगैश्च निर्धुतैः।
शिलागृहैरुन्मथितैस्तथा गृहैः प्रनष्टरूपं तदभून्महद्वनम्॥', 'latāgṛhaiś citragṛhaiś ca nāśitair mahoragair vyālamṛgaiś ca nirdhutaiḥ
śilāgṛhair unmathitais tathā gṛhaiḥ pranaṣṭarūpaṃ tad abhūn mahad vanam', null, 5039016),
('ramayana-5-39-17', 17, 'Sundara Kanda, Sarga 39, Verse 17', 'स तस्य कृत्वार्थपतेर्महाकपिर्महद्व्यलीकं मनसो महात्मनः।
युयुत्सुरेको बहुभिर्महाबलैः श्रिया ज्वलंस्तोरणमाश्रितः कपिः॥', 'sa tasya kṛtvārthapater mahākapir mahad vyalīkaṃ manaso mahātmanaḥ
yuyutsur eko bahubhir mahābalaiḥ śriyā jvalaṃs toraṇam āśritaḥ kapiḥ', null, 5039017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 40 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-40-1', 1, 'Sundara Kanda, Sarga 40, Verse 1', 'ततः पक्षिनिनादेन वृक्षभङ्गस्वनेन च।
बभूवुस्त्राससंभ्रान्ताः सर्वे लङ्कानिवासिनः॥', 'tataḥ pakṣininādena vṛkṣabhaṅgasvanena ca
babhūvus trāsasaṃbhrāntāḥ sarve laṅkānivāsinaḥ', null, 5040001),
('ramayana-5-40-2', 2, 'Sundara Kanda, Sarga 40, Verse 2', 'विद्रुताश्च भयत्रस्ता विनेदुर्मृगपक्षुणः।
रक्षसां च निमित्तानि क्रूराणि प्रतिपेदिरे॥', 'vidrutāś ca bhayatrastā vinedur mṛgapakṣuṇaḥ
rakṣasāṃ ca nimittāni krūrāṇi pratipedire', null, 5040002),
('ramayana-5-40-3', 3, 'Sundara Kanda, Sarga 40, Verse 3', 'ततो गतायां निद्रायां राक्षस्यो विकृताननाः।
तद्वनं ददृशुर्भग्नं तं च वीरं महाकपिम्॥', 'tato gatāyāṃ nidrāyāṃ rākṣasyo vikṛtānanāḥ
tad vanaṃ dadṛśur bhagnaṃ taṃ ca vīraṃ mahākapim', null, 5040003),
('ramayana-5-40-4', 4, 'Sundara Kanda, Sarga 40, Verse 4', 'स ता दृष्ट्व महाबाहुर्महासत्त्वो महाबलः।
चकार सुमहद्रूपं राक्षसीनां भयावहम्॥', 'sa tā dṛṣṭva mahābāhur mahāsattvo mahābalaḥ
cakāra sumahad rūpaṃ rākṣasīnāṃ bhayāvaham', null, 5040004),
('ramayana-5-40-5', 5, 'Sundara Kanda, Sarga 40, Verse 5', 'ततस्तं गिरिसंकाशमतिकायं महाबलम्।
राक्षस्यो वानरं दृष्ट्वा पप्रच्छुर्जनकात्मजाम्॥', 'tatas taṃ girisaṃkāśam atikāyaṃ mahābalam
rākṣasyo vānaraṃ dṛṣṭvā papracchur janakātmajām', null, 5040005),
('ramayana-5-40-6', 6, 'Sundara Kanda, Sarga 40, Verse 6', 'कोऽयं कस्य कुतो वायं किंनिमित्तमिहागतः।
कथं त्वया सहानेन संवादः कृत इत्युत॥', 'ko ''yaṃ kasya kuto vāyaṃ kiṃnimittam ihāgataḥ
kathaṃ tvayā sahānena saṃvādaḥ kṛta ity uta', null, 5040006),
('ramayana-5-40-7', 7, 'Sundara Kanda, Sarga 40, Verse 7', 'आचक्ष्व नो विशालाक्षि मा भूत्ते सुभगे भयम्।
संवादमसितापाङ्गे त्वया किं कृतवानयम्॥', 'ācakṣva no viśālākṣi mā bhūt te subhage bhayam
saṃvādam asitāpāṅge tvayā kiṃ kṛtavān ayam', null, 5040007),
('ramayana-5-40-8', 8, 'Sundara Kanda, Sarga 40, Verse 8', 'अथाब्रवीत्तदा साध्वी सीता सर्वाङ्गशोभना।
रक्षसां कामरूपाणां विज्ञाने मम का गतिः॥', 'athābravīt tadā sādhvī sītā sarvāṅgaśobhanā
rakṣasāṃ kāmarūpāṇāṃ vijñāne mama kā gatiḥ', null, 5040008),
('ramayana-5-40-9', 9, 'Sundara Kanda, Sarga 40, Verse 9', 'यूयमेवास्य जानीत योऽयं यद्वा करिष्यति।
अहिरेव अहेः पादान्विजानाति न संशयः॥', 'yūyam evāsya jānīta yo ''yaṃ yad vā kariṣyati
ahir eva aheḥ pādān vijānāti na saṃśayaḥ', null, 5040009),
('ramayana-5-40-10', 10, 'Sundara Kanda, Sarga 40, Verse 10', 'अहमप्यस्य भीतास्मि नैनं जानामि कोऽन्वयम्।
वेद्मि राक्षसमेवैनं कामरूपिणमागतम्॥', 'aham apy asya bhītāsmi nainaṃ jānāmi ko ''nvayam
vedmi rākṣasam evainaṃ kāmarūpiṇam āgatam', null, 5040010),
('ramayana-5-40-11', 11, 'Sundara Kanda, Sarga 40, Verse 11', 'वैदेह्या वचनं श्रुत्वा राक्षस्यो विद्रुता द्रुतम्।
स्थिताः काश्चिद्गताः काश्चिद्रावणाय निवेदितुम्॥', 'vaidehyā vacanaṃ śrutvā rākṣasyo vidrutā drutam
sthitāḥ kāś cid gatāḥ kāś cid rāvaṇāya niveditum', null, 5040011),
('ramayana-5-40-12', 12, 'Sundara Kanda, Sarga 40, Verse 12', 'रावणस्य समीपे तु राक्षस्यो विकृताननाः।
विरूपं वानरं भीममाख्यातुमुपचक्रमुः॥', 'rāvaṇasya samīpe tu rākṣasyo vikṛtānanāḥ
virūpaṃ vānaraṃ bhīmam ākhyātum upacakramuḥ', null, 5040012),
('ramayana-5-40-13', 13, 'Sundara Kanda, Sarga 40, Verse 13', 'अशोकवनिका मध्ये राजन्भीमवपुः कपिः।
सीतया कृतसंवादस्तिष्ठत्यमितविक्रमः॥', 'aśokavanikā madhye rājan bhīmavapuḥ kapiḥ
sītayā kṛtasaṃvādas tiṣṭhaty amitavikramaḥ', null, 5040013),
('ramayana-5-40-14', 14, 'Sundara Kanda, Sarga 40, Verse 14', 'न च तं जानकी सीता हरिं हरिणलोचणा।
अस्माभिर्बहुधा पृष्टा निवेदयितुमिच्छति॥', 'na ca taṃ jānakī sītā hariṃ hariṇalocaṇā
asmābhir bahudhā pṛṣṭā nivedayitum icchati', null, 5040014),
('ramayana-5-40-15', 15, 'Sundara Kanda, Sarga 40, Verse 15', 'वासवस्य भवेद्दूतो दूतो वैश्रवणस्य वा।
प्रेषितो वापि रामेण सीतान्वेषणकाङ्क्षया॥', 'vāsavasya bhaved dūto dūto vaiśravaṇasya vā
preṣito vāpi rāmeṇa sītānveṣaṇakāṅkṣayā', null, 5040015),
('ramayana-5-40-16', 16, 'Sundara Kanda, Sarga 40, Verse 16', 'तेन त्वद्भूतरूपेण यत्तत्तव मनोहरम्।
नानामृगगणाकीर्णं प्रमृष्टं प्रमदावनम्॥', 'tena tvadbhūtarūpeṇa yat tat tava manoharam
nānāmṛgagaṇākīrṇaṃ pramṛṣṭaṃ pramadāvanam', null, 5040016),
('ramayana-5-40-17', 17, 'Sundara Kanda, Sarga 40, Verse 17', 'न तत्र कश्चिदुद्देशो यस्तेन न विनाशितः।
यत्र सा जानकी सीता स तेन न विनाशितः॥', 'na tatra kaś cid uddeśo yas tena na vināśitaḥ
yatra sā jānakī sītā sa tena na vināśitaḥ', null, 5040017),
('ramayana-5-40-18', 18, 'Sundara Kanda, Sarga 40, Verse 18', 'जानकीरक्षणार्थं वा श्रमाद्वा नोपलभ्यते।
अथ वा कः श्रमस्तस्य सैव तेनाभिरक्षिता॥', 'jānakīrakṣaṇārthaṃ vā śramād vā nopalabhyate
atha vā kaḥ śramas tasya saiva tenābhirakṣitā', null, 5040018),
('ramayana-5-40-19', 19, 'Sundara Kanda, Sarga 40, Verse 19', 'चारुपल्लवपत्राढ्यं यं सीता स्वयमास्थिता।
प्रवृद्धः शिंशपावृक्षः स च तेनाभिरक्षितः॥', 'cārupallavapatrāḍhyaṃ yaṃ sītā svayam āsthitā
pravṛddhaḥ śiṃśapāvṛkṣaḥ sa ca tenābhirakṣitaḥ', null, 5040019),
('ramayana-5-40-20', 20, 'Sundara Kanda, Sarga 40, Verse 20', 'तस्योग्ररूपस्योग्रं त्वं दण्डमाज्ञातुमर्हसि।
सीता संभाषिता येन तद्वनं च विनाशितम्॥', 'tasyograrūpasyograṃ tvaṃ daṇḍam ājñātum arhasi
sītā saṃbhāṣitā yena tad vanaṃ ca vināśitam', null, 5040020),
('ramayana-5-40-21', 21, 'Sundara Kanda, Sarga 40, Verse 21', 'मनःपरिगृहीतां तां तव रक्षोगणेश्वर।
कः सीतामभिभाषेत यो न स्यात्त्यक्तजीवितः॥', 'manaḥparigṛhītāṃ tāṃ tava rakṣogaṇeśvara
kaḥ sītām abhibhāṣeta yo na syāt tyaktajīvitaḥ', null, 5040021),
('ramayana-5-40-22', 22, 'Sundara Kanda, Sarga 40, Verse 22', 'राक्षसीनां वचः श्रुत्वा रावणो राक्षसेश्वरः।
हुतागिरिव जज्वाल कोपसंवर्तितेक्षणः॥', 'rākṣasīnāṃ vacaḥ śrutvā rāvaṇo rākṣaseśvaraḥ
hutāgir iva jajvāla kopasaṃvartitekṣaṇaḥ', null, 5040022),
('ramayana-5-40-23', 23, 'Sundara Kanda, Sarga 40, Verse 23', 'आत्मनः सदृशाञ्शूरान्किंकरान्नाम राक्षसान्।
व्यादिदेश महातेजा निग्रहार्थं हनूमतः॥', 'ātmanaḥ sadṛśāñ śūrān kiṃkarān nāma rākṣasān
vyādideśa mahātejā nigrahārthaṃ hanūmataḥ', null, 5040023),
('ramayana-5-40-24', 24, 'Sundara Kanda, Sarga 40, Verse 24', 'तेषामशीतिसाहस्रं किंकराणां तरस्विनाम्।
निर्ययुर्भवनात्तस्मात्कूटमुद्गरपाणयः॥', 'teṣām aśītisāhasraṃ kiṃkarāṇāṃ tarasvinām
niryayur bhavanāt tasmāt kūṭamudgarapāṇayaḥ', null, 5040024),
('ramayana-5-40-25', 25, 'Sundara Kanda, Sarga 40, Verse 25', 'महोदरा महादंष्ट्रा घोररूपा महाबलाः।
युद्धाभिमनसः सर्वे हनूमद्ग्रहणोन्मुखाः॥', 'mahodarā mahādaṃṣṭrā ghorarūpā mahābalāḥ
yuddhābhimanasaḥ sarve hanūmadgrahaṇonmukhāḥ', null, 5040025),
('ramayana-5-40-26', 26, 'Sundara Kanda, Sarga 40, Verse 26', 'ते कपिं तं समासाद्य तोरणस्थमवस्थितम्।
अभिपेतुर्महावेगाः पतङ्गा इव पावकम्॥', 'te kapiṃ taṃ samāsādya toraṇastham avasthitam
abhipetur mahāvegāḥ pataṅgā iva pāvakam', null, 5040026),
('ramayana-5-40-27', 27, 'Sundara Kanda, Sarga 40, Verse 27', 'ते गदाभिर्विचित्राभिः परिघैः काञ्चनाङ्गदैः।
आजघ्नुर्वानरश्रेष्ठं शरैरादित्यसंनिभैः॥', 'te gadābhir vicitrābhiḥ parighaiḥ kāñcanāṅgadaiḥ
ājaghnur vānaraśreṣṭhaṃ śarair ādityasaṃnibhaiḥ', null, 5040027),
('ramayana-5-40-28', 28, 'Sundara Kanda, Sarga 40, Verse 28', 'हनूमानपि तेजस्वी श्रीमान्पर्वतसंनिभः।
क्षितावाविध्य लाङ्गूलं ननाद च महास्वनम्॥', 'hanūmān api tejasvī śrīmān parvatasaṃnibhaḥ
kṣitāv āvidhya lāṅgūlaṃ nanāda ca mahāsvanam', null, 5040028),
('ramayana-5-40-29', 29, 'Sundara Kanda, Sarga 40, Verse 29', 'तस्य संनादशब्देन तेऽभवन्भयशङ्किताः।
ददृशुश्च हनूमन्तं संध्यामेघमिवोन्नतम्॥', 'tasya saṃnādaśabdena te ''bhavan bhayaśaṅkitāḥ
dadṛśuś ca hanūmantaṃ saṃdhyāmegham ivonnatam', null, 5040029),
('ramayana-5-40-30', 30, 'Sundara Kanda, Sarga 40, Verse 30', 'स्वामिसंदेशनिःशङ्कास्ततस्ते राक्षसाः कपिम्।
चित्रैः प्रहरणैर्भीमैरभिपेतुस्ततस्ततः॥', 'svāmisaṃdeśaniḥśaṅkās tatas te rākṣasāḥ kapim
citraiḥ praharaṇair bhīmair abhipetus tatas tataḥ', null, 5040030),
('ramayana-5-40-31', 31, 'Sundara Kanda, Sarga 40, Verse 31', 'स तैः परिवृतः शूरैः सर्वतः स महाबलः।
आससादायसं भीमं परिघं तोरणाश्रितम्॥', 'sa taiḥ parivṛtaḥ śūraiḥ sarvataḥ sa mahābalaḥ
āsasādāyasaṃ bhīmaṃ parighaṃ toraṇāśritam', null, 5040031),
('ramayana-5-40-32', 32, 'Sundara Kanda, Sarga 40, Verse 32', 'स तं परिघमादाय जघान रजनीचरान्॥', 'sa taṃ parigham ādāya jaghāna rajanīcarān', null, 5040032),
('ramayana-5-40-33', 33, 'Sundara Kanda, Sarga 40, Verse 33', 'स पन्नगमिवादाय स्फुरन्तं विनतासुतः।
विचचाराम्बरे वीरः परिगृह्य च मारुतिः॥', 'sa pannagam ivādāya sphurantaṃ vinatāsutaḥ
vicacārāmbare vīraḥ parigṛhya ca mārutiḥ', null, 5040033),
('ramayana-5-40-34', 34, 'Sundara Kanda, Sarga 40, Verse 34', 'स हत्वा राक्षसान्वीरः किंकरान्मारुतात्मजः।
युद्धाकाङ्क्षी पुनर्वीरस्तोरणं समुपस्थितः॥', 'sa hatvā rākṣasān vīraḥ kiṃkarān mārutātmajaḥ
yuddhākāṅkṣī punar vīras toraṇaṃ samupasthitaḥ', null, 5040034),
('ramayana-5-40-35', 35, 'Sundara Kanda, Sarga 40, Verse 35', 'ततस्तस्माद्भयान्मुक्ताः कति चित्तत्र राक्षसाः।
निहतान्किंकरान्सर्वान्रावणाय न्यवेदयन्॥', 'tatas tasmād bhayān muktāḥ kati cit tatra rākṣasāḥ
nihatān kiṃkarān sarvān rāvaṇāya nyavedayan', null, 5040035),
('ramayana-5-40-36', 36, 'Sundara Kanda, Sarga 40, Verse 36', 'स राक्षसानां निहतं महाबलं निशम्य राजा परिवृत्तलोचनः।
समादिदेशाप्रतिमं पराक्रमे प्रहस्तपुत्रं समरे सुदुर्जयम्॥', 'sa rākṣasānāṃ nihataṃ mahābalaṃ niśamya rājā parivṛttalocanaḥ
samādideśāpratimaṃ parākrame prahastaputraṃ samare sudurjayam', null, 5040036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 41 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-41-1', 1, 'Sundara Kanda, Sarga 41, Verse 1', 'ततः स किंकरान्हत्वा हनूमान्ध्यानमास्थितः।
वनं भग्नं मया चैत्यप्रासादो न विनाशितः।
तस्मात्प्रासादमप्येवमिमं विध्वंसयाम्यहम्॥', 'tataḥ sa kiṃkarān hatvā hanūmān dhyānam āsthitaḥ
vanaṃ bhagnaṃ mayā caityaprāsādo na vināśitaḥ
tasmāt prāsādam apy evam imaṃ vidhvaṃsayāmy aham', null, 5041001),
('ramayana-5-41-2', 2, 'Sundara Kanda, Sarga 41, Verse 2', 'इति संचिन्त्य हनुमान्मनसा दर्शयन्बलम्।
चैत्यप्रासादमाप्लुत्य मेरुशृङ्गमिवोन्नतम्।
आरुरोह हरिश्रेष्ठो हनूमान्मारुतात्मजः॥', 'iti saṃcintya hanumān manasā darśayan balam
caityaprāsādam āplutya meruśṛṅgam ivonnatam
āruroha hariśreṣṭho hanūmān mārutātmajaḥ', null, 5041002),
('ramayana-5-41-3', 3, 'Sundara Kanda, Sarga 41, Verse 3', 'संप्रधृष्य च दुर्धर्षश्चैत्यप्रासादमुन्नतम्।
हनूमान्प्रज्वलंल्लक्ष्म्या पारियात्रोपमोऽभवत्॥', 'saṃpradhṛṣya ca durdharṣaś caityaprāsādam unnatam
hanūmān prajvalaṃl lakṣmyā pāriyātropamo ''bhavat', null, 5041003),
('ramayana-5-41-4', 4, 'Sundara Kanda, Sarga 41, Verse 4', 'स भूत्वा तु महाकायो हनूमान्मारुतात्मजः।
धृष्टमास्फोटयामास लङ्कां शब्देन पूरयन्॥', 'sa bhūtvā tu mahākāyo hanūmān mārutātmajaḥ
dhṛṣṭam āsphoṭayām āsa laṅkāṃ śabdena pūrayan', null, 5041004),
('ramayana-5-41-5', 5, 'Sundara Kanda, Sarga 41, Verse 5', 'तस्यास्फोटितशब्देन महता श्रोत्रघातिना।
पेतुर्विहंगा गगनादुच्चैश्चेदमघोषयत्॥', 'tasyāsphoṭitaśabdena mahatā śrotraghātinā
petur vihaṃgā gaganād uccaiś cedam aghoṣayat', null, 5041005),
('ramayana-5-41-6', 6, 'Sundara Kanda, Sarga 41, Verse 6', 'जयत्यतिबलो रामो लक्ष्मणश्च महाबलः।
राजा जयति सुग्रीवो राघवेणाभिपालितः॥', 'jayaty atibalo rāmo lakṣmaṇaś ca mahābalaḥ
rājā jayati sugrīvo rāghaveṇābhipālitaḥ', null, 5041006),
('ramayana-5-41-7', 7, 'Sundara Kanda, Sarga 41, Verse 7', 'दासोऽहं कोसलेन्द्रस्य रामस्याक्लिष्टकर्मणः।
हनुमाञ्शत्रुसैन्यानां निहन्ता मारुतात्मजः॥', 'dāso ''haṃ kosalendrasya rāmasyākliṣṭakarmaṇaḥ
hanumāñ śatrusainyānāṃ nihantā mārutātmajaḥ', null, 5041007),
('ramayana-5-41-8', 8, 'Sundara Kanda, Sarga 41, Verse 8', 'न रावणसहस्रं मे युद्धे प्रतिबलं भवेत्।
शिलाभिस्तु प्रहरतः पादपैश्च सहस्रशः॥', 'na rāvaṇasahasraṃ me yuddhe pratibalaṃ bhavet
śilābhis tu praharataḥ pādapaiś ca sahasraśaḥ', null, 5041008),
('ramayana-5-41-9', 9, 'Sundara Kanda, Sarga 41, Verse 9', 'अर्दयित्वा पुरीं लङ्कामभिवाद्य च मैथिलीम्।
समृद्धार्थो गमिष्यामि मिषतां सर्वरक्षसाम्॥', 'ardayitvā purīṃ laṅkām abhivādya ca maithilīm
samṛddhārtho gamiṣyāmi miṣatāṃ sarvarakṣasām', null, 5041009),
('ramayana-5-41-10', 10, 'Sundara Kanda, Sarga 41, Verse 10', 'एवमुक्त्वा विमानस्थश्चैत्यस्थान्हरिपुंगवः।
ननाद भीमनिर्ह्रादो रक्षसां जनयन्भयम्॥', 'evam uktvā vimānasthaś caityasthān haripuṃgavaḥ
nanāda bhīmanirhrādo rakṣasāṃ janayan bhayam', null, 5041010),
('ramayana-5-41-11', 11, 'Sundara Kanda, Sarga 41, Verse 11', 'तेन शब्देन महता चैत्यपालाः शतं ययुः।
गृहीत्वा विविधानस्त्रान्प्रासान्खड्गान्परश्वधान्।
विसृजन्तो महाक्षया मारुतिं पर्यवारयन्॥', 'tena śabdena mahatā caityapālāḥ śataṃ yayuḥ
gṛhītvā vividhān astrān prāsān khaḍgān paraśvadhān
visṛjanto mahākṣayā mārutiṃ paryavārayan', null, 5041011),
('ramayana-5-41-12', 12, 'Sundara Kanda, Sarga 41, Verse 12', 'आवर्त इव गङ्गायास्तोयस्य विपुलो महान्।
परिक्षिप्य हरिश्रेष्ठं स बभौ रक्षसां गणः॥', 'āvarta iva gaṅgāyās toyasya vipulo mahān
parikṣipya hariśreṣṭhaṃ sa babhau rakṣasāṃ gaṇaḥ', null, 5041012),
('ramayana-5-41-13', 13, 'Sundara Kanda, Sarga 41, Verse 13', 'ततो वातात्मजः क्रुद्धो भीमरूपं समास्थितः॥', 'tato vātātmajaḥ kruddho bhīmarūpaṃ samāsthitaḥ', null, 5041013),
('ramayana-5-41-14', 14, 'Sundara Kanda, Sarga 41, Verse 14', 'प्रासादस्य महांस्तस्य स्तम्भं हेमपरिष्कृतम्।
उत्पाटयित्वा वेगेन हनूमान्मारुतात्मजः।
ततस्तं भ्रामयामास शतधारं महाबलः॥', 'prāsādasya mahāṃs tasya stambhaṃ hemapariṣkṛtam
utpāṭayitvā vegena hanūmān mārutātmajaḥ
tatas taṃ bhrāmayām āsa śatadhāraṃ mahābalaḥ', null, 5041014),
('ramayana-5-41-15', 15, 'Sundara Kanda, Sarga 41, Verse 15', 'स राक्षसशतं हत्वा वज्रेणेन्द्र इवासुरान्।
अन्तरिक्षस्थितः श्रीमानिदं वचनमब्रवीत्॥', 'sa rākṣasaśataṃ hatvā vajreṇendra ivāsurān
antarikṣasthitaḥ śrīmān idaṃ vacanam abravīt', null, 5041015),
('ramayana-5-41-16', 16, 'Sundara Kanda, Sarga 41, Verse 16', 'मादृशानां सहस्राणि विसृष्टानि महात्मनाम्।
बलिनां वानरेन्द्राणां सुग्रीववशवर्तिनाम्॥', 'mādṛśānāṃ sahasrāṇi visṛṣṭāni mahātmanām
balināṃ vānarendrāṇāṃ sugrīvavaśavartinām', null, 5041016),
('ramayana-5-41-17', 17, 'Sundara Kanda, Sarga 41, Verse 17', 'शतैः शतसहस्रैश्च कोटीभिरयुतैरपि।
आगमिष्यति सुग्रीवः सर्वेषां वो निषूदनः॥', 'śataiḥ śatasahasraiś ca koṭībhir ayutair api
āgamiṣyati sugrīvaḥ sarveṣāṃ vo niṣūdanaḥ', null, 5041017),
('ramayana-5-41-18', 18, 'Sundara Kanda, Sarga 41, Verse 18', 'नेयमस्ति पुरी लङ्का न यूयं न च रावणः।
यस्मादिक्ष्वाकुनाथेन बद्धं वैरं महात्मना॥', 'neyam asti purī laṅkā na yūyaṃ na ca rāvaṇaḥ
yasmād ikṣvākunāthena baddhaṃ vairaṃ mahātmanā', null, 5041018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 42 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-42-1', 1, 'Sundara Kanda, Sarga 42, Verse 1', 'संदिष्टो राक्षसेन्द्रेण प्रहस्तस्य सुतो बली।
जम्बुमाली महादंष्ट्रो निर्जगाम धनुर्धरः॥', 'saṃdiṣṭo rākṣasendreṇa prahastasya suto balī
jambumālī mahādaṃṣṭro nirjagāma dhanurdharaḥ', null, 5042001),
('ramayana-5-42-2', 2, 'Sundara Kanda, Sarga 42, Verse 2', 'रक्तमाल्याम्बरधरः स्रग्वी रुचिरकुण्डलः।
महान्विवृत्तनयनश्चण्डः समरदुर्जयः॥', 'raktamālyāmbaradharaḥ sragvī rucirakuṇḍalaḥ
mahān vivṛttanayanaś caṇḍaḥ samaradurjayaḥ', null, 5042002),
('ramayana-5-42-3', 3, 'Sundara Kanda, Sarga 42, Verse 3', 'धनुः शक्रधनुः प्रख्यं महद्रुचिरसायकम्।
विस्फारयाणो वेगेन वज्राशनिसमस्वनम्॥', 'dhanuḥ śakradhanuḥ prakhyaṃ mahad rucirasāyakam
visphārayāṇo vegena vajrāśanisamasvanam', null, 5042003),
('ramayana-5-42-4', 4, 'Sundara Kanda, Sarga 42, Verse 4', 'तस्य विस्फारघोषेण धनुषो महता दिशः।
प्रदिशश्च नभश्चैव सहसा समपूर्यत॥', 'tasya visphāraghoṣeṇa dhanuṣo mahatā diśaḥ
pradiśaś ca nabhaś caiva sahasā samapūryata', null, 5042004),
('ramayana-5-42-5', 5, 'Sundara Kanda, Sarga 42, Verse 5', 'रथेन खरयुक्तेन तमागतमुदीक्ष्य सः।
हनूमान्वेगसंपन्नो जहर्ष च ननाद च॥', 'rathena kharayuktena tam āgatam udīkṣya saḥ
hanūmān vegasaṃpanno jaharṣa ca nanāda ca', null, 5042005),
('ramayana-5-42-6', 6, 'Sundara Kanda, Sarga 42, Verse 6', 'तं तोरणविटङ्कस्थं हनूमन्तं महाकपिम्।
जम्बुमाली महाबाहुर्विव्याध निशितैः शरैः॥', 'taṃ toraṇaviṭaṅkasthaṃ hanūmantaṃ mahākapim
jambumālī mahābāhur vivyādha niśitaiḥ śaraiḥ', null, 5042006),
('ramayana-5-42-7', 7, 'Sundara Kanda, Sarga 42, Verse 7', 'अर्धचन्द्रेण वदने शिरस्येकेन कर्णिना।
बाह्वोर्विव्याध नाराचैर्दशभिस्तं कपीश्वरम्॥', 'ardhacandreṇa vadane śirasy ekena karṇinā
bāhvor vivyādha nārācair daśabhis taṃ kapīśvaram', null, 5042007),
('ramayana-5-42-8', 8, 'Sundara Kanda, Sarga 42, Verse 8', 'तस्य तच्छुशुभे ताम्रं शरेणाभिहतं मुखम्।
शरदीवाम्बुजं फुल्लं विद्धं भास्कररश्मिना॥', 'tasya tac chuśubhe tāmraṃ śareṇābhihataṃ mukham
śaradīvāmbujaṃ phullaṃ viddhaṃ bhāskararaśminā', null, 5042008),
('ramayana-5-42-9', 9, 'Sundara Kanda, Sarga 42, Verse 9', 'चुकोप बाणाभिहतो राक्षसस्य महाकपिः।
ततः पार्श्वेऽतिविपुलां ददर्श महतीं शिलाम्॥', 'cukopa bāṇābhihato rākṣasasya mahākapiḥ
tataḥ pārśve ''tivipulāṃ dadarśa mahatīṃ śilām', null, 5042009),
('ramayana-5-42-10', 10, 'Sundara Kanda, Sarga 42, Verse 10', 'तरसा तां समुत्पाट्य चिक्षेप बलवद्बली।
तां शरैर्दशभिः क्रुद्धस्ताडयामास राक्षसः॥', 'tarasā tāṃ samutpāṭya cikṣepa balavad balī
tāṃ śarair daśabhiḥ kruddhas tāḍayām āsa rākṣasaḥ', null, 5042010),
('ramayana-5-42-11', 11, 'Sundara Kanda, Sarga 42, Verse 11', 'विपन्नं कर्म तद्दृष्ट्वा हनूमांश्चण्डविक्रमः।
सालं विपुलमुत्पाट्य भ्रामयामास वीर्यवान्॥', 'vipannaṃ karma tad dṛṣṭvā hanūmāṃś caṇḍavikramaḥ
sālaṃ vipulam utpāṭya bhrāmayām āsa vīryavān', null, 5042011),
('ramayana-5-42-12', 12, 'Sundara Kanda, Sarga 42, Verse 12', 'भ्रामयन्तं कपिं दृष्ट्वा सालवृक्षं महाबलम्।
चिक्षेप सुबहून्बाणाञ्जम्बुमाली महाबलः॥', 'bhrāmayantaṃ kapiṃ dṛṣṭvā sālavṛkṣaṃ mahābalam
cikṣepa subahūn bāṇāñ jambumālī mahābalaḥ', null, 5042012),
('ramayana-5-42-13', 13, 'Sundara Kanda, Sarga 42, Verse 13', 'सालं चतुर्भिर्चिच्छेद वानरं पञ्चभिर्भुजे।
उरस्येकेन बाणेन दशभिस्तु स्तनान्तरे॥', 'sālaṃ caturbhir ciccheda vānaraṃ pañcabhir bhuje
urasy ekena bāṇena daśabhis tu stanāntare', null, 5042013),
('ramayana-5-42-14', 14, 'Sundara Kanda, Sarga 42, Verse 14', 'स शरैः पूरिततनुः क्रोधेन महता वृतः।
तमेव परिघं गृह्य भ्रामयामास वेगितः॥', 'sa śaraiḥ pūritatanuḥ krodhena mahatā vṛtaḥ
tam eva parighaṃ gṛhya bhrāmayām āsa vegitaḥ', null, 5042014),
('ramayana-5-42-15', 15, 'Sundara Kanda, Sarga 42, Verse 15', 'अतिवेगोऽतिवेगेन भ्रामयित्वा बलोत्कटः।
परिघं पातयामास जम्बुमालेर्महोरसि॥', 'ativego ''tivegena bhrāmayitvā balotkaṭaḥ
parighaṃ pātayām āsa jambumāler mahorasi', null, 5042015),
('ramayana-5-42-16', 16, 'Sundara Kanda, Sarga 42, Verse 16', 'तस्य चैव शिरो नास्ति न बाहू न च जानुनी।
न धनुर्न रथो नाश्वास्तत्रादृश्यन्त नेषवः॥', 'tasya caiva śiro nāsti na bāhū na ca jānunī
na dhanur na ratho nāśvās tatrādṛśyanta neṣavaḥ', null, 5042016),
('ramayana-5-42-17', 17, 'Sundara Kanda, Sarga 42, Verse 17', 'स हतस्तरसा तेन जम्बुमाली महारथः।
पपात निहतो भूमौ चूर्णिताङ्गविभूषणः॥', 'sa hatas tarasā tena jambumālī mahārathaḥ
papāta nihato bhūmau cūrṇitāṅgavibhūṣaṇaḥ', null, 5042017),
('ramayana-5-42-18', 18, 'Sundara Kanda, Sarga 42, Verse 18', 'जम्बुमालिं च निहतं किंकरांश्च महाबलान्।
चुक्रोध रावणः श्रुत्वा कोपसंरक्तलोचनः॥', 'jambumāliṃ ca nihataṃ kiṃkarāṃś ca mahābalān
cukrodha rāvaṇaḥ śrutvā kopasaṃraktalocanaḥ', null, 5042018),
('ramayana-5-42-19', 19, 'Sundara Kanda, Sarga 42, Verse 19', 'स रोषसंवर्तितताम्रलोचनः प्रहस्तपुत्रे निहते महाबले।
अमात्यपुत्रानतिवीर्यविक्रमान्समादिदेशाशु निशाचरेश्वरः॥', 'sa roṣasaṃvartitatāmralocanaḥ prahastaputre nihate mahābale
amātyaputrān ativīryavikramān samādideśāśu niśācareśvaraḥ', null, 5042019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 43 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-43-1', 1, 'Sundara Kanda, Sarga 43, Verse 1', 'ततस्ते राक्षसेन्द्रेण चोदिता मन्त्रिणः सुताः।
निर्ययुर्भवनात्तस्मात्सप्त सप्तार्चिवर्चसः॥', 'tatas te rākṣasendreṇa coditā mantriṇaḥ sutāḥ
niryayur bhavanāt tasmāt sapta saptārcivarcasaḥ', null, 5043001),
('ramayana-5-43-2', 2, 'Sundara Kanda, Sarga 43, Verse 2', 'महाबलपरीवारा धनुष्मन्तो महाबलाः।
कृतास्त्रास्त्रविदां श्रेष्ठाः परस्परजयैषिणः॥', 'mahābalaparīvārā dhanuṣmanto mahābalāḥ
kṛtāstrāstravidāṃ śreṣṭhāḥ parasparajayaiṣiṇaḥ', null, 5043002),
('ramayana-5-43-3', 3, 'Sundara Kanda, Sarga 43, Verse 3', 'हेमजालपरिक्षिप्तैर्ध्वजवद्भिः पताकिभिः।
तोयदस्वननिर्घोषैर्वाजियुक्तैर्महारथैः॥', 'hemajālaparikṣiptair dhvajavadbhiḥ patākibhiḥ
toyadasvananirghoṣair vājiyuktair mahārathaiḥ', null, 5043003),
('ramayana-5-43-4', 4, 'Sundara Kanda, Sarga 43, Verse 4', 'तप्तकाञ्चनचित्राणि चापान्यमितविक्रमाः।
विस्फारयन्तः संहृष्टास्तडिद्वन्त इवाम्बुदाः॥', 'taptakāñcanacitrāṇi cāpāny amitavikramāḥ
visphārayantaḥ saṃhṛṣṭās taḍidvanta ivāmbudāḥ', null, 5043004),
('ramayana-5-43-5', 5, 'Sundara Kanda, Sarga 43, Verse 5', 'जनन्यस्तास्ततस्तेषां विदित्वा किंकरान्हतान्।
बभूवुः शोकसंभ्रान्ताः सबान्धवसुहृज्जनाः॥', 'jananyas tās tatas teṣāṃ viditvā kiṃkarān hatān
babhūvuḥ śokasaṃbhrāntāḥ sabāndhavasuhṛjjanāḥ', null, 5043005),
('ramayana-5-43-6', 6, 'Sundara Kanda, Sarga 43, Verse 6', 'ते परस्परसंघर्षास्तप्तकाञ्चनभूषणाः।
अभिपेतुर्हनूमन्तं तोरणस्थमवस्थितम्॥', 'te parasparasaṃgharṣās taptakāñcanabhūṣaṇāḥ
abhipetur hanūmantaṃ toraṇastham avasthitam', null, 5043006),
('ramayana-5-43-7', 7, 'Sundara Kanda, Sarga 43, Verse 7', 'सृजन्तो बाणवृष्टिं ते रथगर्जितनिःस्वनाः।
वृष्टिमन्त इवाम्भोदा विचेरुर्नैरृतर्षभाः॥', 'sṛjanto bāṇavṛṣṭiṃ te rathagarjitaniḥsvanāḥ
vṛṣṭimanta ivāmbhodā vicerur nairṛtarṣabhāḥ', null, 5043007),
('ramayana-5-43-8', 8, 'Sundara Kanda, Sarga 43, Verse 8', 'अवकीर्णस्ततस्ताभिर्हनूमाञ्शरवृष्टिभिः।
अभवत्संवृताकारः शैलराडिव वृष्टिभिः॥', 'avakīrṇas tatas tābhir hanūmāñ śaravṛṣṭibhiḥ
abhavat saṃvṛtākāraḥ śailarāḍ iva vṛṣṭibhiḥ', null, 5043008),
('ramayana-5-43-9', 9, 'Sundara Kanda, Sarga 43, Verse 9', 'स शरान्वञ्चयामास तेषामाशुचरः कपिः।
रथवेगांश्च वीराणां विचरन्विमलेऽम्बरे॥', 'sa śarān vañcayām āsa teṣām āśucaraḥ kapiḥ
rathavegāṃś ca vīrāṇāṃ vicaran vimale ''mbare', null, 5043009),
('ramayana-5-43-10', 10, 'Sundara Kanda, Sarga 43, Verse 10', 'स तैः क्रीडन्धनुष्मद्भिर्व्योम्नि वीरः प्रकाशते।
धनुष्मद्भिर्यथा मेघैर्मारुतः प्रभुरम्बरे॥', 'sa taiḥ krīḍan dhanuṣmadbhir vyomni vīraḥ prakāśate
dhanuṣmadbhir yathā meghair mārutaḥ prabhur ambare', null, 5043010),
('ramayana-5-43-11', 11, 'Sundara Kanda, Sarga 43, Verse 11', 'स कृत्वा निनदं घोरं त्रासयंस्तां महाचमूम्।
चकार हनुमान्वेगं तेषु रक्षःसु वीर्यवान्॥', 'sa kṛtvā ninadaṃ ghoraṃ trāsayaṃs tāṃ mahācamūm
cakāra hanumān vegaṃ teṣu rakṣaḥsu vīryavān', null, 5043011),
('ramayana-5-43-12', 12, 'Sundara Kanda, Sarga 43, Verse 12', 'तलेनाभिहनत्कांश्चित्पादैः कांश्चित्परंतपः।
मुष्टिनाभ्यहनत्कांश्चिन्नखैः कांश्चिद्व्यदारयत्॥', 'talenābhihanat kāṃś cit pādaiḥ kāṃś cit paraṃtapaḥ
muṣṭinābhyahanat kāṃś cin nakhaiḥ kāṃś cid vyadārayat', null, 5043012),
('ramayana-5-43-13', 13, 'Sundara Kanda, Sarga 43, Verse 13', 'प्रममाथोरसा कांश्चिदूरुभ्यामपरान्कपिः।
के चित्तस्यैव नादेन तत्रैव पतिता भुवि॥', 'pramamāthorasā kāṃś cid ūrubhyām aparān kapiḥ
ke cit tasyaiva nādena tatraiva patitā bhuvi', null, 5043013),
('ramayana-5-43-14', 14, 'Sundara Kanda, Sarga 43, Verse 14', 'ततस्तेष्ववपन्नेषु भूमौ निपतितेषु च।
तत्सैन्यमगमत्सर्वं दिशो दशभयार्दितम्॥', 'tatas teṣv avapanneṣu bhūmau nipatiteṣu ca
tat sainyam agamat sarvaṃ diśo daśabhayārditam', null, 5043014),
('ramayana-5-43-15', 15, 'Sundara Kanda, Sarga 43, Verse 15', 'विनेदुर्विस्वरं नागा निपेतुर्भुवि वाजिनः।
भग्ननीडध्वजच्छत्रैर्भूश्च कीर्णाभवद्रथैः॥', 'vinedur visvaraṃ nāgā nipetur bhuvi vājinaḥ
bhagnanīḍadhvajacchatrair bhūś ca kīrṇābhavad rathaiḥ', null, 5043015),
('ramayana-5-43-16', 16, 'Sundara Kanda, Sarga 43, Verse 16', 'स तान्प्रवृद्धान्विनिहत्य राक्षसान्महाबलश्चण्डपराक्रमः कपिः।
युयुत्सुरन्यैः पुनरेव राक्षसैस्तदेव वीरोऽभिजगाम तोरणम्॥', 'sa tān pravṛddhān vinihatya rākṣasān mahābalaś caṇḍaparākramaḥ kapiḥ
yuyutsur anyaiḥ punar eva rākṣasais tad eva vīro ''bhijagāma toraṇam', null, 5043016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 44 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-44-1', 1, 'Sundara Kanda, Sarga 44, Verse 1', 'हतान्मन्त्रिसुतान्बुद्ध्वा वानरेण महात्मना।
रावणः संवृताकारश्चकार मतिमुत्तमाम्॥', 'hatān mantrisutān buddhvā vānareṇa mahātmanā
rāvaṇaḥ saṃvṛtākāraś cakāra matim uttamām', null, 5044001),
('ramayana-5-44-2', 2, 'Sundara Kanda, Sarga 44, Verse 2', 'स विरूपाक्षयूपाक्षौ दुर्धरं चैव राक्षसं।
प्रघसं भासकर्णं च पञ्चसेनाग्रनायकान्॥', 'sa virūpākṣayūpākṣau durdharaṃ caiva rākṣasaṃ
praghasaṃ bhāsakarṇaṃ ca pañcasenāgranāyakān', null, 5044002),
('ramayana-5-44-3', 3, 'Sundara Kanda, Sarga 44, Verse 3', 'संदिदेश दशग्रीवो वीरान्नयविशारदान्।
हनूमद्ग्रहणे व्यग्रान्वायुवेगसमान्युधि॥', 'saṃdideśa daśagrīvo vīrān nayaviśāradān
hanūmadgrahaṇe vyagrān vāyuvegasamān yudhi', null, 5044003),
('ramayana-5-44-4', 4, 'Sundara Kanda, Sarga 44, Verse 4', 'यात सेनाग्रगाः सर्वे महाबलपरिग्रहाः।
सवाजिरथमातङ्गाः स कपिः शास्यतामिति॥', 'yāta senāgragāḥ sarve mahābalaparigrahāḥ
savājirathamātaṅgāḥ sa kapiḥ śāsyatām iti', null, 5044004),
('ramayana-5-44-5', 5, 'Sundara Kanda, Sarga 44, Verse 5', 'यत्तैश्च खलु भाव्यं स्यात्तमासाद्य वनालयम्।
कर्म चापि समाधेयं देशकालविरोधितम्॥', 'yat taiś ca khalu bhāvyaṃ syāt tam āsādya vanālayam
karma cāpi samādheyaṃ deśakālavirodhitam', null, 5044005),
('ramayana-5-44-6', 6, 'Sundara Kanda, Sarga 44, Verse 6', 'न ह्यहं तं कपिं मन्ये कर्मणा प्रतितर्कयन्।
सर्वथा तन्महद्भूतं महाबलपरिग्रहम्।
भवेदिन्द्रेण वा सृष्टमस्मदर्थं तपोबलात्॥', 'na hy ahaṃ taṃ kapiṃ manye karmaṇā pratitarkayan
sarvathā tan mahad bhūtaṃ mahābalaparigraham
bhaved indreṇa vā sṛṣṭam asmadarthaṃ tapobalāt', null, 5044006),
('ramayana-5-44-7', 7, 'Sundara Kanda, Sarga 44, Verse 7', 'सनागयक्षगन्धर्वा देवासुरमहर्षयः।
युष्माभिः सहितैः सर्वैर्मया सह विनिर्जिताः॥', 'sanāgayakṣagandharvā devāsuramaharṣayaḥ
yuṣmābhiḥ sahitaiḥ sarvair mayā saha vinirjitāḥ', null, 5044007),
('ramayana-5-44-8', 8, 'Sundara Kanda, Sarga 44, Verse 8', 'तैरवश्यं विधातव्यं व्यलीकं किं चिदेव नः।
तदेव नात्र संदेहः प्रसह्य परिगृह्यताम्॥', 'tair avaśyaṃ vidhātavyaṃ vyalīkaṃ kiṃ cid eva naḥ
tad eva nātra saṃdehaḥ prasahya parigṛhyatām', null, 5044008),
('ramayana-5-44-9', 9, 'Sundara Kanda, Sarga 44, Verse 9', 'नावमन्यो भवद्भिश्च हरिः क्रूरपराक्रमः।
दृष्टा हि हरयः शीघ्रा मया विपुलविक्रमाः॥', 'nāvamanyo bhavadbhiś ca hariḥ krūraparākramaḥ
dṛṣṭā hi harayaḥ śīghrā mayā vipulavikramāḥ', null, 5044009),
('ramayana-5-44-10', 10, 'Sundara Kanda, Sarga 44, Verse 10', 'वाली च सह सुग्रीवो जाम्बवांश्च महाबलः।
नीलः सेनापतिश्चैव ये चान्ये द्विविदादयः॥', 'vālī ca saha sugrīvo jāmbavāṃś ca mahābalaḥ
nīlaḥ senāpatiś caiva ye cānye dvividādayaḥ', null, 5044010),
('ramayana-5-44-11', 11, 'Sundara Kanda, Sarga 44, Verse 11', 'नैव तेषां गतिर्भीमा न तेजो न पराक्रमः।
न मतिर्न बलोत्साहो न रूपपरिकल्पनम्॥', 'naiva teṣāṃ gatir bhīmā na tejo na parākramaḥ
na matir na balotsāho na rūpaparikalpanam', null, 5044011),
('ramayana-5-44-12', 12, 'Sundara Kanda, Sarga 44, Verse 12', 'महत्सत्त्वमिदं ज्ञेयं कपिरूपं व्यवस्थितम्।
प्रयत्नं महदास्थाय क्रियतामस्य निग्रहः॥', 'mahat sattvam idaṃ jñeyaṃ kapirūpaṃ vyavasthitam
prayatnaṃ mahad āsthāya kriyatām asya nigrahaḥ', null, 5044012),
('ramayana-5-44-13', 13, 'Sundara Kanda, Sarga 44, Verse 13', 'कामं लोकास्त्रयः सेन्द्राः ससुरासुरमानवाः।
भवतामग्रतः स्थातुं न पर्याप्ता रणाजिरे॥', 'kāmaṃ lokās trayaḥ sendrāḥ sasurāsuramānavāḥ
bhavatām agrataḥ sthātuṃ na paryāptā raṇājire', null, 5044013),
('ramayana-5-44-14', 14, 'Sundara Kanda, Sarga 44, Verse 14', 'तथापि तु नयज्ञेन जयमाकाङ्क्षता रणे।
आत्मा रक्ष्यः प्रयत्नेन युद्धसिद्धिर्हि चञ्चला॥', 'tathāpi tu nayajñena jayam ākāṅkṣatā raṇe
ātmā rakṣyaḥ prayatnena yuddhasiddhir hi cañcalā', null, 5044014),
('ramayana-5-44-15', 15, 'Sundara Kanda, Sarga 44, Verse 15', 'ते स्वामिवचनं सर्वे प्रतिगृह्य महौजसः।
समुत्पेतुर्महावेगा हुताशसमतेजसः॥', 'te svāmivacanaṃ sarve pratigṛhya mahaujasaḥ
samutpetur mahāvegā hutāśasamatejasaḥ', null, 5044015),
('ramayana-5-44-16', 16, 'Sundara Kanda, Sarga 44, Verse 16', 'रथैश्च मत्तैर्नागैश्च वाजिभिश्च महाजवैः।
शस्त्रैश्च विविधैस्तीक्ष्णैः सर्वैश्चोपचिता बलैः॥', 'rathaiś ca mattair nāgaiś ca vājibhiś ca mahājavaiḥ
śastraiś ca vividhais tīkṣṇaiḥ sarvaiś copacitā balaiḥ', null, 5044016),
('ramayana-5-44-17', 17, 'Sundara Kanda, Sarga 44, Verse 17', 'ततस्तं ददृशुर्वीरा दीप्यमानं महाकपिम्।
रश्मिमन्तमिवोद्यन्तं स्वतेजोरश्मिमालिनम्॥', 'tatas taṃ dadṛśur vīrā dīpyamānaṃ mahākapim
raśmimantam ivodyantaṃ svatejoraśmimālinam', null, 5044017),
('ramayana-5-44-18', 18, 'Sundara Kanda, Sarga 44, Verse 18', 'तोरणस्थं महावेगं महासत्त्वं महाबलम्।
महामतिं महोत्साहं महाकायं महाबलम्॥', 'toraṇasthaṃ mahāvegaṃ mahāsattvaṃ mahābalam
mahāmatiṃ mahotsāhaṃ mahākāyaṃ mahābalam', null, 5044018),
('ramayana-5-44-19', 19, 'Sundara Kanda, Sarga 44, Verse 19', 'तं समीक्ष्यैव ते सर्वे दिक्षु सर्वास्ववस्थिताः।
तैस्तैः प्रहरणैर्भीमैरभिपेतुस्ततस्ततः॥', 'taṃ samīkṣyaiva te sarve dikṣu sarvāsv avasthitāḥ
tais taiḥ praharaṇair bhīmair abhipetus tatas tataḥ', null, 5044019),
('ramayana-5-44-20', 20, 'Sundara Kanda, Sarga 44, Verse 20', 'तस्य पञ्चायसास्तीक्ष्णाः सिताः पीतमुखाः शराः।
शिरस्त्युत्पलपत्राभा दुर्धरेण निपातिताः॥', 'tasya pañcāyasās tīkṣṇāḥ sitāḥ pītamukhāḥ śarāḥ
śirasty utpalapatrābhā durdhareṇa nipātitāḥ', null, 5044020),
('ramayana-5-44-21', 21, 'Sundara Kanda, Sarga 44, Verse 21', 'स तैः पञ्चभिराविद्धः शरैः शिरसि वानरः।
उत्पपात नदन्व्योम्नि दिशो दश विनादयन्॥', 'sa taiḥ pañcabhir āviddhaḥ śaraiḥ śirasi vānaraḥ
utpapāta nadan vyomni diśo daśa vinādayan', null, 5044021),
('ramayana-5-44-22', 22, 'Sundara Kanda, Sarga 44, Verse 22', 'ततस्तु दुर्धरो वीरः सरथः सज्जकार्मुकः।
किरञ्शरशतैर्नैकैरभिपेदे महाबलः॥', 'tatas tu durdharo vīraḥ sarathaḥ sajjakārmukaḥ
kirañ śaraśatair naikair abhipede mahābalaḥ', null, 5044022),
('ramayana-5-44-23', 23, 'Sundara Kanda, Sarga 44, Verse 23', 'स कपिर्वारयामास तं व्योम्नि शरवर्षिणम्।
वृष्टिमन्तं पयोदान्ते पयोदमिव मारुतः॥', 'sa kapir vārayām āsa taṃ vyomni śaravarṣiṇam
vṛṣṭimantaṃ payodānte payodam iva mārutaḥ', null, 5044023),
('ramayana-5-44-24', 24, 'Sundara Kanda, Sarga 44, Verse 24', 'अर्द्यमानस्ततस्तेन दुर्धरेणानिलात्मजः।
चकार निनदं भूयो व्यवर्धत च वेगवान्॥', 'ardyamānas tatas tena durdhareṇānilātmajaḥ
cakāra ninadaṃ bhūyo vyavardhata ca vegavān', null, 5044024),
('ramayana-5-44-25', 25, 'Sundara Kanda, Sarga 44, Verse 25', 'स दूरं सहसोत्पत्य दुर्धरस्य रथे हरिः।
निपपात महावेगो विद्युद्राशिर्गिराविव॥', 'sa dūraṃ sahasotpatya durdharasya rathe hariḥ
nipapāta mahāvego vidyudrāśir girāv iva', null, 5044025),
('ramayana-5-44-26', 26, 'Sundara Kanda, Sarga 44, Verse 26', 'ततस्तं मथिताष्टाश्वं रथं भग्नाक्षकूवरम्।
विहाय न्यपतद्भूमौ दुर्धरस्त्यक्तजीवितः॥', 'tatas taṃ mathitāṣṭāśvaṃ rathaṃ bhagnākṣakūvaram
vihāya nyapatad bhūmau durdharas tyaktajīvitaḥ', null, 5044026),
('ramayana-5-44-27', 27, 'Sundara Kanda, Sarga 44, Verse 27', 'तं विरूपाक्षयूपाक्षौ दृष्ट्वा निपतितं भुवि।
संजातरोषौ दुर्धर्षावुत्पेततुररिंदमौ॥', 'taṃ virūpākṣayūpākṣau dṛṣṭvā nipatitaṃ bhuvi
saṃjātaroṣau durdharṣāv utpetatur ariṃdamau', null, 5044027),
('ramayana-5-44-28', 28, 'Sundara Kanda, Sarga 44, Verse 28', 'स ताभ्यां सहसोत्पत्य विष्ठितो विमलेऽम्बरे।
मुद्गराभ्यां महाबाहुर्वक्षस्यभिहतः कपिः॥', 'sa tābhyāṃ sahasotpatya viṣṭhito vimale ''mbare
mudgarābhyāṃ mahābāhur vakṣasy abhihataḥ kapiḥ', null, 5044028),
('ramayana-5-44-29', 29, 'Sundara Kanda, Sarga 44, Verse 29', 'तयोर्वेगवतोर्वेगं विनिहत्य महाबलः।
निपपात पुनर्भूमौ सुपर्णसमविक्रमः॥', 'tayor vegavator vegaṃ vinihatya mahābalaḥ
nipapāta punar bhūmau suparṇasamavikramaḥ', null, 5044029),
('ramayana-5-44-30', 30, 'Sundara Kanda, Sarga 44, Verse 30', 'स सालवृक्षमासाद्य समुत्पाट्य च वानरः।
तावुभौ राक्षसौ वीरौ जघान पवनात्मजः॥', 'sa sālavṛkṣam āsādya samutpāṭya ca vānaraḥ
tāv ubhau rākṣasau vīrau jaghāna pavanātmajaḥ', null, 5044030),
('ramayana-5-44-31', 31, 'Sundara Kanda, Sarga 44, Verse 31', 'ततस्तांस्त्रीन्हताञ्ज्ञात्वा वानरेण तरस्विना।
अभिपेदे महावेगः प्रसह्य प्रघसो हरिम्॥', 'tatas tāṃs trīn hatāñ jñātvā vānareṇa tarasvinā
abhipede mahāvegaḥ prasahya praghaso harim', null, 5044031),
('ramayana-5-44-32', 32, 'Sundara Kanda, Sarga 44, Verse 32', 'भासकर्णश्च संक्रुद्धः शूलमादाय वीर्यवान्।
एकतः कपिशार्दूलं यशस्विनमवस्थितौ॥', 'bhāsakarṇaś ca saṃkruddhaḥ śūlam ādāya vīryavān
ekataḥ kapiśārdūlaṃ yaśasvinam avasthitau', null, 5044032),
('ramayana-5-44-33', 33, 'Sundara Kanda, Sarga 44, Verse 33', 'पट्टिशेन शिताग्रेण प्रघसः प्रत्यपोथयत्।
भासकर्णश्च शूलेन राक्षसः कपिसत्तमम्॥', 'paṭṭiśena śitāgreṇa praghasaḥ pratyapothayat
bhāsakarṇaś ca śūlena rākṣasaḥ kapisattamam', null, 5044033),
('ramayana-5-44-34', 34, 'Sundara Kanda, Sarga 44, Verse 34', 'स ताभ्यां विक्षतैर्गात्रैरसृग्दिग्धतनूरुहः।
अभवद्वानरः क्रुद्धो बालसूर्यसमप्रभः॥', 'sa tābhyāṃ vikṣatair gātrair asṛgdigdhatanūruhaḥ
abhavad vānaraḥ kruddho bālasūryasamaprabhaḥ', null, 5044034),
('ramayana-5-44-35', 35, 'Sundara Kanda, Sarga 44, Verse 35', 'समुत्पाट्य गिरेः शृङ्गं समृगव्यालपादपम्।
जघान हनुमान्वीरो राक्षसौ कपिकुञ्जरः॥', 'samutpāṭya gireḥ śṛṅgaṃ samṛgavyālapādapam
jaghāna hanumān vīro rākṣasau kapikuñjaraḥ', null, 5044035),
('ramayana-5-44-36', 36, 'Sundara Kanda, Sarga 44, Verse 36', 'ततस्तेष्ववसन्नेषु सेनापतिषु पञ्चसु।
बलं तदवशेषं तु नाशयामास वानरः॥', 'tatas teṣv avasanneṣu senāpatiṣu pañcasu
balaṃ tad avaśeṣaṃ tu nāśayām āsa vānaraḥ', null, 5044036),
('ramayana-5-44-37', 37, 'Sundara Kanda, Sarga 44, Verse 37', 'अश्वैरश्वान्गजैर्नागान्योधैर्योधान्रथै रथान्।
स कपिर्नाशयामास सहस्राक्ष इवासुरान्॥', 'aśvair aśvān gajair nāgān yodhair yodhān rathai rathān
sa kapir nāśayām āsa sahasrākṣa ivāsurān', null, 5044037),
('ramayana-5-44-38', 38, 'Sundara Kanda, Sarga 44, Verse 38', 'हतैर्नागैश्च तुरगैर्भग्नाक्षैश्च महारथैः।
हतैश्च राक्षसैर्भूमी रुद्धमार्गा समन्ततः॥', 'hatair nāgaiś ca turagair bhagnākṣaiś ca mahārathaiḥ
hataiś ca rākṣasair bhūmī ruddhamārgā samantataḥ', null, 5044038),
('ramayana-5-44-39', 39, 'Sundara Kanda, Sarga 44, Verse 39', 'ततः कपिस्तान्ध्वजिनीपतीन्रणे निहत्य वीरान्सबलान्सवाहनान्।
तदेव वीरः परिगृह्य तोरणं कृतक्षणः काल इव प्रजाक्षये॥', 'tataḥ kapis tān dhvajinīpatīn raṇe nihatya vīrān sabalān savāhanān
tad eva vīraḥ parigṛhya toraṇaṃ kṛtakṣaṇaḥ kāla iva prajākṣaye', null, 5044039)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 45 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-45-1', 1, 'Sundara Kanda, Sarga 45, Verse 1', 'सेनापतीन्पञ्च स तु प्रमापितान्हनूमता सानुचरान्सवाहनान्।
समीक्ष्य राजा समरोद्धतोन्मुखं कुमारमक्षं प्रसमैक्षताक्षतम्॥', 'senāpatīn pañca sa tu pramāpitān hanūmatā sānucarān savāhanān
samīkṣya rājā samaroddhatonmukhaṃ kumāram akṣaṃ prasamaikṣatākṣatam', null, 5045001),
('ramayana-5-45-2', 2, 'Sundara Kanda, Sarga 45, Verse 2', 'स तस्य दृष्ट्यर्पणसंप्रचोदितः प्रतापवान्काञ्चनचित्रकार्मुकः।
समुत्पपाताथ सदस्युदीरितो द्विजातिमुख्यैर्हविषेव पावकः॥', 'sa tasya dṛṣṭyarpaṇasaṃpracoditaḥ pratāpavān kāñcanacitrakārmukaḥ
samutpapātātha sadasy udīrito dvijātimukhyair haviṣeva pāvakaḥ', null, 5045002),
('ramayana-5-45-3', 3, 'Sundara Kanda, Sarga 45, Verse 3', 'ततो महद्बालदिवाकरप्रभं प्रतप्तजाम्बूनदजालसंततम्।
रथां समास्थाय ययौ स वीर्यवान्महाहरिं तं प्रति नैरृतर्षभः॥', 'tato mahad bāladivākaraprabhaṃ prataptajāmbūnadajālasaṃtatam
rathāṃ samāsthāya yayau sa vīryavān mahāhariṃ taṃ prati nairṛtarṣabhaḥ', null, 5045003),
('ramayana-5-45-4', 4, 'Sundara Kanda, Sarga 45, Verse 4', 'ततस्तपःसंग्रहसंचयार्जितं प्रतप्तजाम्बूनदजालशोभितम्।
पताकिनं रत्नविभूषितध्वजं मनोजवाष्टाश्ववरैः सुयोजितम्॥', 'tatas tapaḥsaṃgrahasaṃcayārjitaṃ prataptajāmbūnadajālaśobhitam
patākinaṃ ratnavibhūṣitadhvajaṃ manojavāṣṭāśvavaraiḥ suyojitam', null, 5045004),
('ramayana-5-45-5', 5, 'Sundara Kanda, Sarga 45, Verse 5', 'सुरासुराधृष्यमसंगचारिणं रविप्रभं व्योमचरं समाहितम्।
सतूणमष्टासिनिबद्धबन्धुरं यथाक्रमावेशितशक्तितोमरम्॥', 'surāsurādhṛṣyam asaṃgacāriṇaṃ raviprabhaṃ vyomacaraṃ samāhitam
satūṇam aṣṭāsinibaddhabandhuraṃ yathākramāveśitaśaktitomaram', null, 5045005),
('ramayana-5-45-6', 6, 'Sundara Kanda, Sarga 45, Verse 6', 'विराजमानं प्रतिपूर्णवस्तुना सहेमदाम्ना शशिसूर्यवर्वसा।
दिवाकराभं रथमास्थितस्ततः स निर्जगामामरतुल्यविक्रमः॥', 'virājamānaṃ pratipūrṇavastunā sahemadāmnā śaśisūryavarvasā
divākarābhaṃ ratham āsthitas tataḥ sa nirjagāmāmaratulyavikramaḥ', null, 5045006),
('ramayana-5-45-7', 7, 'Sundara Kanda, Sarga 45, Verse 7', 'स पूरयन्खं च महीं च साचलां तुरंगमतङ्गमहारथस्वनैः।
बलैः समेतैः स हि तोरणस्थितं समर्थमासीनमुपागमत्कपिम्॥', 'sa pūrayan khaṃ ca mahīṃ ca sācalāṃ turaṃgamataṅgamahārathasvanaiḥ
balaiḥ sametaiḥ sa hi toraṇasthitaṃ samartham āsīnam upāgamat kapim', null, 5045007),
('ramayana-5-45-8', 8, 'Sundara Kanda, Sarga 45, Verse 8', 'स तं समासाद्य हरिं हरीक्षणो युगान्तकालाग्निमिव प्रजाक्षये।
अवस्थितं विस्मितजातसंभ्रमः समैक्षताक्षो बहुमानचक्षुषा॥', 'sa taṃ samāsādya hariṃ harīkṣaṇo yugāntakālāgnim iva prajākṣaye
avasthitaṃ vismitajātasaṃbhramaḥ samaikṣatākṣo bahumānacakṣuṣā', null, 5045008),
('ramayana-5-45-9', 9, 'Sundara Kanda, Sarga 45, Verse 9', 'स तस्य वेगं च कपेर्महात्मनः पराक्रमं चारिषु पार्थिवात्मजः।
विचारयन्खं च बलं महाबलो हिमक्षये सूर्य इवाभिवर्धते॥', 'sa tasya vegaṃ ca kaper mahātmanaḥ parākramaṃ cāriṣu pārthivātmajaḥ
vicārayan khaṃ ca balaṃ mahābalo himakṣaye sūrya ivābhivardhate', null, 5045009),
('ramayana-5-45-10', 10, 'Sundara Kanda, Sarga 45, Verse 10', 'स जातमन्युः प्रसमीक्ष्य विक्रमं स्थिरः स्थितः संयति दुर्निवारणम्।
समाहितात्मा हनुमन्तमाहवे प्रचोदयामास शरैस्त्रिभिः शितैः॥', 'sa jātamanyuḥ prasamīkṣya vikramaṃ sthiraḥ sthitaḥ saṃyati durnivāraṇam
samāhitātmā hanumantam āhave pracodayām āsa śarais tribhiḥ śitaiḥ', null, 5045010),
('ramayana-5-45-11', 11, 'Sundara Kanda, Sarga 45, Verse 11', 'ततः कपिं तं प्रसमीक्ष्य गर्वितं जितश्रमं शत्रुपराजयोर्जितम्।
अवैक्षताक्षः समुदीर्णमानसः सबाणपाणिः प्रगृहीतकार्मुकः॥', 'tataḥ kapiṃ taṃ prasamīkṣya garvitaṃ jitaśramaṃ śatruparājayor jitam
avaikṣatākṣaḥ samudīrṇamānasaḥ sabāṇapāṇiḥ pragṛhītakārmukaḥ', null, 5045011),
('ramayana-5-45-12', 12, 'Sundara Kanda, Sarga 45, Verse 12', 'स हेमनिष्काङ्गदचारुकुण्डलः समाससादाशु पराक्रमः कपिम्।
तयोर्बभूवाप्रतिमः समागमः सुरासुराणामपि संभ्रमप्रदः॥', 'sa hemaniṣkāṅgadacārukuṇḍalaḥ samāsasādāśu parākramaḥ kapim
tayor babhūvāpratimaḥ samāgamaḥ surāsurāṇām api saṃbhramapradaḥ', null, 5045012),
('ramayana-5-45-13', 13, 'Sundara Kanda, Sarga 45, Verse 13', 'ररास भूमिर्न तताप भानुमान्ववौ न वायुः प्रचचाल चाचलः।
कपेः कुमारस्य च वीक्ष्य संयुगं ननाद च द्यौरुदधिश्च चुक्षुभे॥', 'rarāsa bhūmir na tatāpa bhānumān vavau na vāyuḥ pracacāla cācalaḥ
kapeḥ kumārasya ca vīkṣya saṃyugaṃ nanāda ca dyaur udadhiś ca cukṣubhe', null, 5045013),
('ramayana-5-45-14', 14, 'Sundara Kanda, Sarga 45, Verse 14', 'ततः स वीरः सुमुखान्पतत्रिणः सुवर्णपुङ्खान्सविषानिवोरगान्।
समाधिसंयोगविमोक्षतत्त्वविच्छरानथ त्रीन्कपिमूर्ध्न्यपातयत्॥', 'tataḥ sa vīraḥ sumukhān patatriṇaḥ suvarṇapuṅkhān saviṣān ivoragān
samādhisaṃyogavimokṣatattvavic charān atha trīn kapimūrdhny apātayat', null, 5045014),
('ramayana-5-45-15', 15, 'Sundara Kanda, Sarga 45, Verse 15', 'स तैः शरैर्मूर्ध्नि समं निपातितैः क्षरन्नसृग्दिग्धविवृत्तलोचनः।
नवोदितादित्यनिभः शरांशुमान्व्यराजतादित्य इवांशुमालिकः॥', 'sa taiḥ śarair mūrdhni samaṃ nipātitaiḥ kṣarann asṛgdigdhavivṛttalocanaḥ
navoditādityanibhaḥ śarāṃśumān vyarājatāditya ivāṃśumālikaḥ', null, 5045015),
('ramayana-5-45-16', 16, 'Sundara Kanda, Sarga 45, Verse 16', 'ततः स पिङ्गाधिपमन्त्रिसत्तमः समीक्ष्य तं राजवरात्मजं रणे।
उदग्रचित्रायुधचित्रकार्मुकं जहर्ष चापूर्यत चाहवोन्मुखः॥', 'tataḥ sa piṅgādhipamantrisattamaḥ samīkṣya taṃ rājavarātmajaṃ raṇe
udagracitrāyudhacitrakārmukaṃ jaharṣa cāpūryata cāhavonmukhaḥ', null, 5045016),
('ramayana-5-45-17', 17, 'Sundara Kanda, Sarga 45, Verse 17', 'स मन्दराग्रस्थ इवांशुमाली विवृद्धकोपो बलवीर्यसंयुतः।
कुमारमक्षं सबलं सवाहनं ददाह नेत्राग्निमरीचिभिस्तदा॥', 'sa mandarāgrastha ivāṃśumālī vivṛddhakopo balavīryasaṃyutaḥ
kumāram akṣaṃ sabalaṃ savāhanaṃ dadāha netrāgnimarīcibhis tadā', null, 5045017),
('ramayana-5-45-18', 18, 'Sundara Kanda, Sarga 45, Verse 18', 'ततः स बाणासनशक्रकार्मुकः शरप्रवर्षो युधि राक्षसाम्बुदः।
शरान्मुमोचाशु हरीश्वराचले बलाहको वृष्टिमिवाचलोत्तमे॥', 'tataḥ sa bāṇāsanaśakrakārmukaḥ śarapravarṣo yudhi rākṣasāmbudaḥ
śarān mumocāśu harīśvarācale balāhako vṛṣṭim ivācalottame', null, 5045018),
('ramayana-5-45-19', 19, 'Sundara Kanda, Sarga 45, Verse 19', 'ततः कपिस्तं रणचण्डविक्रमं विवृद्धतेजोबलवीर्यसायकम्।
कुमारमक्षं प्रसमीक्ष्य संयुगे ननाद हर्षाद्घनतुल्यविक्रमः॥', 'tataḥ kapis taṃ raṇacaṇḍavikramaṃ vivṛddhatejobalavīryasāyakam
kumāram akṣaṃ prasamīkṣya saṃyuge nanāda harṣād ghanatulyavikramaḥ', null, 5045019),
('ramayana-5-45-20', 20, 'Sundara Kanda, Sarga 45, Verse 20', 'स बालभावाद्युधि वीर्यदर्पितः प्रवृद्धमन्युः क्षतजोपमेक्षणः।
समाससादाप्रतिमं रणे कपिं गजो महाकूपमिवावृतं तृणैः॥', 'sa bālabhāvād yudhi vīryadarpitaḥ pravṛddhamanyuḥ kṣatajopamekṣaṇaḥ
samāsasādāpratimaṃ raṇe kapiṃ gajo mahākūpam ivāvṛtaṃ tṛṇaiḥ', null, 5045020),
('ramayana-5-45-21', 21, 'Sundara Kanda, Sarga 45, Verse 21', 'स तेन बाणैः प्रसभं निपातितैश्चकार नादं घननादनिःस्वनः।
समुत्पपाताशु नभः स मारुतिर्भुजोरुविक्षेपण घोरदर्शनः॥', 'sa tena bāṇaiḥ prasabhaṃ nipātitaiś cakāra nādaṃ ghananādaniḥsvanaḥ
samutpapātāśu nabhaḥ sa mārutir bhujoruvikṣepaṇa ghoradarśanaḥ', null, 5045021),
('ramayana-5-45-22', 22, 'Sundara Kanda, Sarga 45, Verse 22', 'समुत्पतन्तं समभिद्रवद्बली स राक्षसानां प्रवरः प्रतापवान्।
रथी रथश्रेष्ठतमः किरञ्शरैः पयोधरः शैलमिवाश्मवृष्टिभिः॥', 'samutpatantaṃ samabhidravad balī sa rākṣasānāṃ pravaraḥ pratāpavān
rathī rathaśreṣṭhatamaḥ kirañ śaraiḥ payodharaḥ śailam ivāśmavṛṣṭibhiḥ', null, 5045022),
('ramayana-5-45-23', 23, 'Sundara Kanda, Sarga 45, Verse 23', 'स ताञ्शरांस्तस्य विमोक्षयन्कपिश्चचार वीरः पथि वायुसेविते।
शरान्तरे मारुतवद्विनिष्पतन्मनोजवः संयति चण्डविक्रमः॥', 'sa tāñ śarāṃs tasya vimokṣayan kapiś cacāra vīraḥ pathi vāyusevite
śarāntare mārutavad viniṣpatan manojavaḥ saṃyati caṇḍavikramaḥ', null, 5045023),
('ramayana-5-45-24', 24, 'Sundara Kanda, Sarga 45, Verse 24', 'तमात्तबाणासनमाहवोन्मुखं खमास्तृणन्तं विविधैः शरोत्तमैः।
अवैक्षताक्षं बहुमानचक्षुषा जगाम चिन्तां च स मारुतात्मजः॥', 'tam āttabāṇāsanam āhavonmukhaṃ kham āstṛṇantaṃ vividhaiḥ śarottamaiḥ
avaikṣatākṣaṃ bahumānacakṣuṣā jagāma cintāṃ ca sa mārutātmajaḥ', null, 5045024),
('ramayana-5-45-25', 25, 'Sundara Kanda, Sarga 45, Verse 25', 'ततः शरैर्भिन्नभुजान्तरः कपिः कुमारवर्येण महात्मना नदन्।
महाभुजः कर्मविशेषतत्त्वविद्विचिन्तयामास रणे पराक्रमम्॥', 'tataḥ śarair bhinnabhujāntaraḥ kapiḥ kumāravaryeṇa mahātmanā nadan
mahābhujaḥ karmaviśeṣatattvavid vicintayām āsa raṇe parākramam', null, 5045025),
('ramayana-5-45-26', 26, 'Sundara Kanda, Sarga 45, Verse 26', 'अबालवद्बालदिवाकरप्रभः करोत्ययं कर्म महन्महाबलः।
न चास्य सर्वाहवकर्मशोभिनः प्रमापणे मे मतिरत्र जायते॥', 'abālavad bāladivākaraprabhaḥ karoty ayaṃ karma mahan mahābalaḥ
na cāsya sarvāhavakarmaśobhinaḥ pramāpaṇe me matir atra jāyate', null, 5045026),
('ramayana-5-45-27', 27, 'Sundara Kanda, Sarga 45, Verse 27', 'अयं महात्मा च महांश्च वीर्यतः समाहितश्चातिसहश्च संयुगे।
असंशयं कर्मगुणोदयादयं सनागयक्षैर्मुनिभिश्च पूजितः॥', 'ayaṃ mahātmā ca mahāṃś ca vīryataḥ samāhitaś cātisahaś ca saṃyuge
asaṃśayaṃ karmaguṇodayād ayaṃ sanāgayakṣair munibhiś ca pūjitaḥ', null, 5045027),
('ramayana-5-45-28', 28, 'Sundara Kanda, Sarga 45, Verse 28', 'पराक्रमोत्साहविवृद्धमानसः समीक्षते मां प्रमुखागतः स्थितः।
पराक्रमो ह्यस्य मनांसि कम्पयेत्सुरासुराणामपि शीघ्रकारिणः॥', 'parākramotsāhavivṛddhamānasaḥ samīkṣate māṃ pramukhāgataḥ sthitaḥ
parākramo hy asya manāṃsi kampayet surāsurāṇām api śīghrakāriṇaḥ', null, 5045028),
('ramayana-5-45-29', 29, 'Sundara Kanda, Sarga 45, Verse 29', 'न खल्वयं नाभिभवेदुपेक्षितः पराक्रमो ह्यस्य रणे विवर्धते।
प्रमापणं त्वेव ममास्य रोचते न वर्धमानोऽग्निरुपेक्षितुं क्षमः॥', 'na khalv ayaṃ nābhibhaved upekṣitaḥ parākramo hy asya raṇe vivardhate
pramāpaṇaṃ tv eva mamāsya rocate na vardhamāno ''gnir upekṣituṃ kṣamaḥ', null, 5045029),
('ramayana-5-45-30', 30, 'Sundara Kanda, Sarga 45, Verse 30', 'इति प्रवेगं तु परस्य तर्कयन्स्वकर्मयोगं च विधाय वीर्यवान्।
चकार वेगं तु महाबलस्तदा मतिं च चक्रेऽस्य वधे महाकपिः॥', 'iti pravegaṃ tu parasya tarkayan svakarmayogaṃ ca vidhāya vīryavān
cakāra vegaṃ tu mahābalas tadā matiṃ ca cakre ''sya vadhe mahākapiḥ', null, 5045030),
('ramayana-5-45-31', 31, 'Sundara Kanda, Sarga 45, Verse 31', 'स तस्य तानष्टहयान्महाजवान्समाहितान्भारसहान्विवर्तने।
जघान वीरः पथि वायुसेविते तलप्रहालैः पवनात्मजः कपिः॥', 'sa tasya tān aṣṭahayān mahājavān samāhitān bhārasahān vivartane
jaghāna vīraḥ pathi vāyusevite talaprahālaiḥ pavanātmajaḥ kapiḥ', null, 5045031),
('ramayana-5-45-32', 32, 'Sundara Kanda, Sarga 45, Verse 32', 'ततस्तलेनाभिहतो महारथः स तस्य पिङ्गाधिपमन्त्रिनिर्जितः।
स भग्ननीडः परिमुक्तकूबरः पपात भूमौ हतवाजिरम्बरात्॥', 'tatas talenābhihato mahārathaḥ sa tasya piṅgādhipamantrinirjitaḥ
sa bhagnanīḍaḥ parimuktakūbaraḥ papāta bhūmau hatavājir ambarāt', null, 5045032),
('ramayana-5-45-33', 33, 'Sundara Kanda, Sarga 45, Verse 33', 'स तं परित्यज्य महारथो रथं सकार्मुकः खड्गधरः खमुत्पतत्।
तपोऽभियोगादृषिरुग्रवीर्यवान्विहाय देहं मरुतामिवालयम्॥', 'sa taṃ parityajya mahāratho rathaṃ sakārmukaḥ khaḍgadharaḥ kham utpatat
tapo''bhiyogād ṛṣir ugravīryavān vihāya dehaṃ marutām ivālayam', null, 5045033),
('ramayana-5-45-34', 34, 'Sundara Kanda, Sarga 45, Verse 34', 'ततः कपिस्तं विचरन्तमम्बरे पतत्रिराजानिलसिद्धसेविते।
समेत्य तं मारुतवेगविक्रमः क्रमेण जग्राह च पादयोर्दृढम्॥', 'tataḥ kapis taṃ vicarantam ambare patatrirājānilasiddhasevite
sametya taṃ mārutavegavikramaḥ krameṇa jagrāha ca pādayor dṛḍham', null, 5045034),
('ramayana-5-45-35', 35, 'Sundara Kanda, Sarga 45, Verse 35', 'स तं समाविध्य सहस्रशः कपिर्महोरगं गृह्य इवाण्डजेश्वरः।
मुमोच वेगात्पितृतुल्यविक्रमो महीतले संयति वानरोत्तमः॥', 'sa taṃ samāvidhya sahasraśaḥ kapir mahoragaṃ gṛhya ivāṇḍajeśvaraḥ
mumoca vegāt pitṛtulyavikramo mahītale saṃyati vānarottamaḥ', null, 5045035),
('ramayana-5-45-36', 36, 'Sundara Kanda, Sarga 45, Verse 36', 'स भग्नबाहूरुकटीशिरो धरः क्षरन्नसृन्निर्मथितास्थिलोचनः।
स भिन्नसंधिः प्रविकीर्णबन्धनो हतः क्षितौ वायुसुतेन राक्षसः॥', 'sa bhagnabāhūrukaṭīśiro dharaḥ kṣarann asṛn nirmathitāsthilocanaḥ
sa bhinnasaṃdhiḥ pravikīrṇabandhano hataḥ kṣitau vāyusutena rākṣasaḥ', null, 5045036),
('ramayana-5-45-37', 37, 'Sundara Kanda, Sarga 45, Verse 37', 'महाकपिर्भूमितले निपीड्य तं चकार रक्षोऽधिपतेर्महद्भयम्॥', 'mahākapir bhūmitale nipīḍya taṃ cakāra rakṣo''dhipater mahad bhayam', null, 5045037),
('ramayana-5-45-38', 38, 'Sundara Kanda, Sarga 45, Verse 38', 'महर्षिभिश्चक्रचरैर्महाव्रतैः समेत्य भूतैश्च सयक्षपन्नगैः।
सुरैश्च सेन्द्रैर्भृशजातविस्मयैर्हते कुमारे स कपिर्निरीक्षितः॥', 'maharṣibhiś cakracarair mahāvrataiḥ sametya bhūtaiś ca sayakṣapannagaiḥ
suraiś ca sendrair bhṛśajātavismayair hate kumāre sa kapir nirīkṣitaḥ', null, 5045038),
('ramayana-5-45-39', 39, 'Sundara Kanda, Sarga 45, Verse 39', 'निहत्य तं वज्रसुतोपमप्रभं कुमारमक्षं क्षतजोपमेक्षणम्।
तदेव वीरोऽभिजगाम तोरणं कृतक्षणः काल इव प्रजाक्षये॥', 'nihatya taṃ vajrasutopamaprabhaṃ kumāram akṣaṃ kṣatajopamekṣaṇam
tad eva vīro ''bhijagāma toraṇaṃ kṛtakṣaṇaḥ kāla iva prajākṣaye', null, 5045039)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 46 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-46-1', 1, 'Sundara Kanda, Sarga 46, Verse 1', 'ततस्तु रक्षोऽधिपतिर्महात्मा हनूमताक्षे निहते कुमारे।
मनः समाधाय तदेन्द्रकल्पं समादिदेशेन्द्रजितं स रोषात्॥', 'tatas tu rakṣo''dhipatir mahātmā hanūmatākṣe nihate kumāre
manaḥ samādhāya tadendrakalpaṃ samādideśendrajitaṃ sa roṣāt', null, 5046001),
('ramayana-5-46-2', 2, 'Sundara Kanda, Sarga 46, Verse 2', 'त्वमस्त्रविच्छस्त्रभृतां वरिष्ठः सुरासुराणामपि शोकदाता।
सुरेषु सेन्द्रेषु च दृष्टकर्मा पितामहाराधनसंचितास्त्रः॥', 'tvam astravic chastrabhṛtāṃ variṣṭhaḥ surāsurāṇām api śokadātā
sureṣu sendreṣu ca dṛṣṭakarmā pitāmahārādhanasaṃcitāstraḥ', null, 5046002),
('ramayana-5-46-3', 3, 'Sundara Kanda, Sarga 46, Verse 3', 'तवास्त्रबलमासाद्य नासुरा न मरुद्गणाः।
न कश्चित्त्रिषु लोकेषु संयुगे न गतश्रमः॥', 'tavāstrabalam āsādya nāsurā na marudgaṇāḥ
na kaś cit triṣu lokeṣu saṃyuge na gataśramaḥ', null, 5046003),
('ramayana-5-46-4', 4, 'Sundara Kanda, Sarga 46, Verse 4', 'भुजवीर्याभिगुप्तश्च तपसा चाभिरक्षितः।
देशकालविभागज्ञस्त्वमेव मतिसत्तमः॥', 'bhujavīryābhiguptaś ca tapasā cābhirakṣitaḥ
deśakālavibhāgajñas tvam eva matisattamaḥ', null, 5046004),
('ramayana-5-46-5', 5, 'Sundara Kanda, Sarga 46, Verse 5', 'न तेऽस्त्यशक्यं समरेषु कर्मणा न तेऽस्त्यकार्यं मतिपूर्वमन्त्रणे।
न सोऽस्ति कश्चित्त्रिषु संग्रहेषु वै न वेद यस्तेऽस्त्रबलं बलं च ते॥', 'na te ''sty aśakyaṃ samareṣu karmaṇā na te ''sty akāryaṃ matipūrvamantraṇe
na so ''sti kaś cit triṣu saṃgraheṣu vai na veda yas te ''strabalaṃ balaṃ ca te', null, 5046005),
('ramayana-5-46-6', 6, 'Sundara Kanda, Sarga 46, Verse 6', 'ममानुरूपं तपसो बलं च ते पराक्रमश्चास्त्रबलं च संयुगे।
न त्वां समासाद्य रणावमर्दे मनः श्रमं गच्छति निश्चितार्थम्॥', 'mamānurūpaṃ tapaso balaṃ ca te parākramaś cāstrabalaṃ ca saṃyuge
na tvāṃ samāsādya raṇāvamarde manaḥ śramaṃ gacchati niścitārtham', null, 5046006),
('ramayana-5-46-7', 7, 'Sundara Kanda, Sarga 46, Verse 7', 'निहता इंकराः सर्वे जम्बुमाली च राक्षसः।
अमात्यपुत्रा वीराश्च पञ्च सेनाग्रयायिनः॥', 'nihatā iṃkarāḥ sarve jambumālī ca rākṣasaḥ
amātyaputrā vīrāś ca pañca senāgrayāyinaḥ', null, 5046007),
('ramayana-5-46-8', 8, 'Sundara Kanda, Sarga 46, Verse 8', 'सहोदरस्ते दयितः कुमारोऽक्षश्च सूदितः।
न तु तेष्वेव मे सारो यस्त्वय्यरिनिषूदन॥', 'sahodaras te dayitaḥ kumāro ''kṣaś ca sūditaḥ
na tu teṣv eva me sāro yas tvayy ariniṣūdana', null, 5046008),
('ramayana-5-46-9', 9, 'Sundara Kanda, Sarga 46, Verse 9', 'इदं हि दृष्ट्वा मतिमन्महद्बलं कपेः प्रभावं च पराक्रमं च।
त्वमात्मनश्चापि समीक्ष्य सारं कुरुष्व वेगं स्वबलानुरूपम्॥', 'idaṃ hi dṛṣṭvā matiman mahad balaṃ kapeḥ prabhāvaṃ ca parākramaṃ ca
tvam ātmanaś cāpi samīkṣya sāraṃ kuruṣva vegaṃ svabalānurūpam', null, 5046009),
('ramayana-5-46-10', 10, 'Sundara Kanda, Sarga 46, Verse 10', 'बलावमर्दस्त्वयि संनिकृष्टे यथा गते शाम्यति शान्तशत्रौ।
तथा समीक्ष्यात्मबलं परं च समारभस्वास्त्रविदां वरिष्ठ॥', 'balāvamardas tvayi saṃnikṛṣṭe yathā gate śāmyati śāntaśatrau
tathā samīkṣyātmabalaṃ paraṃ ca samārabhasvāstravidāṃ variṣṭha', null, 5046010),
('ramayana-5-46-11', 11, 'Sundara Kanda, Sarga 46, Verse 11', 'न खल्वियं मतिः श्रेष्ठा यत्त्वां संप्रेषयाम्यहम्।
इयं च राजधर्माणां क्षत्रस्य च मतिर्मता॥', 'na khalv iyaṃ matiḥ śreṣṭhā yat tvāṃ saṃpreṣayāmy aham
iyaṃ ca rājadharmāṇāṃ kṣatrasya ca matir matā', null, 5046011),
('ramayana-5-46-12', 12, 'Sundara Kanda, Sarga 46, Verse 12', 'नानाशस्त्रैश्च संग्रामे वैशारद्यमरिंदम।
अवश्यमेव बोद्धव्यं काम्यश्च विजयो रणे॥', 'nānāśastraiś ca saṃgrāme vaiśāradyam ariṃdama
avaśyam eva boddhavyaṃ kāmyaś ca vijayo raṇe', null, 5046012),
('ramayana-5-46-13', 13, 'Sundara Kanda, Sarga 46, Verse 13', 'ततः पितुस्तद्वचनं निशम्य प्रदक्षिणं दक्षसुतप्रभावः।
चकार भर्तारमदीनसत्त्वो रणाय वीरः प्रतिपन्नबुद्धिः॥', 'tataḥ pitus tad vacanaṃ niśamya pradakṣiṇaṃ dakṣasutaprabhāvaḥ
cakāra bhartāram adīnasattvo raṇāya vīraḥ pratipannabuddhiḥ', null, 5046013),
('ramayana-5-46-14', 14, 'Sundara Kanda, Sarga 46, Verse 14', 'ततस्तैः स्वगणैरिष्टैरिन्द्रजित्प्रतिपूजितः।
युद्धोद्धतकृतोत्साहः संग्रामं प्रतिपद्यत॥', 'tatas taiḥ svagaṇair iṣṭair indrajit pratipūjitaḥ
yuddhoddhatakṛtotsāhaḥ saṃgrāmaṃ pratipadyata', null, 5046014),
('ramayana-5-46-15', 15, 'Sundara Kanda, Sarga 46, Verse 15', 'श्रीमान्पद्मपलाशाक्षो राक्षसाधिपतेः सुतः।
निर्जगाम महातेजाः समुद्र इव पर्वसु॥', 'śrīmān padmapalāśākṣo rākṣasādhipateḥ sutaḥ
nirjagāma mahātejāḥ samudra iva parvasu', null, 5046015),
('ramayana-5-46-16', 16, 'Sundara Kanda, Sarga 46, Verse 16', 'स पक्षि राजोपमतुल्यवेगैर्व्यालैश्चतुर्भिः सिततीक्ष्णदंष्ट्रैः।
रथं समायुक्तमसंगवेगं समारुरोहेन्द्रजिदिन्द्रकल्पः॥', 'sa pakṣi rājopamatulyavegair vyālaiś caturbhiḥ sitatīkṣṇadaṃṣṭraiḥ
rathaṃ samāyuktam asaṃgavegaṃ samārurohendrajid indrakalpaḥ', null, 5046016),
('ramayana-5-46-17', 17, 'Sundara Kanda, Sarga 46, Verse 17', 'स रथी धन्विनां श्रेष्ठः शस्त्रज्ञोऽस्त्रविदां वरः।
रथेनाभिययौ क्षिप्रं हनूमान्यत्र सोऽभवत्॥', 'sa rathī dhanvināṃ śreṣṭhaḥ śastrajño ''stravidāṃ varaḥ
rathenābhiyayau kṣipraṃ hanūmān yatra so ''bhavat', null, 5046017),
('ramayana-5-46-18', 18, 'Sundara Kanda, Sarga 46, Verse 18', 'स तस्य रथनिर्घोषं ज्यास्वनं कार्मुकस्य च।
निशम्य हरिवीरोऽसौ संप्रहृष्टतरोऽभवत्॥', 'sa tasya rathanirghoṣaṃ jyāsvanaṃ kārmukasya ca
niśamya harivīro ''sau saṃprahṛṣṭataro ''bhavat', null, 5046018),
('ramayana-5-46-19', 19, 'Sundara Kanda, Sarga 46, Verse 19', 'सुमहच्चापमादाय शितशल्यांश्च सायकान्।
हनूमन्तमभिप्रेत्य जगाम रणपण्डितः॥', 'sumahac cāpam ādāya śitaśalyāṃś ca sāyakān
hanūmantam abhipretya jagāma raṇapaṇḍitaḥ', null, 5046019),
('ramayana-5-46-20', 20, 'Sundara Kanda, Sarga 46, Verse 20', 'तस्मिंस्ततः संयति जातहर्षे रणाय निर्गच्छति बाणपाणौ।
दिशश्च सर्वाः कलुषा बभूवुर्मृगाश्च रौद्रा बहुधा विनेदुः॥', 'tasmiṃs tataḥ saṃyati jātaharṣe raṇāya nirgacchati bāṇapāṇau
diśaś ca sarvāḥ kaluṣā babhūvur mṛgāś ca raudrā bahudhā vineduḥ', null, 5046020),
('ramayana-5-46-21', 21, 'Sundara Kanda, Sarga 46, Verse 21', 'समागतास्तत्र तु नागयक्षा महर्षयश्चक्रचराश्च सिद्धाः।
नभः समावृत्य च पक्षिसंघा विनेदुरुच्चैः परमप्रहृष्टाः॥', 'samāgatās tatra tu nāgayakṣā maharṣayaś cakracarāś ca siddhāḥ
nabhaḥ samāvṛtya ca pakṣisaṃghā vinedur uccaiḥ paramaprahṛṣṭāḥ', null, 5046021),
('ramayana-5-46-22', 22, 'Sundara Kanda, Sarga 46, Verse 22', 'आयन्तं सरथं दृष्ट्वा तूर्णमिन्द्रजितं कपिः।
विननाद महानादं व्यवर्धत च वेगवान्॥', 'āyantaṃ sarathaṃ dṛṣṭvā tūrṇam indrajitaṃ kapiḥ
vinanāda mahānādaṃ vyavardhata ca vegavān', null, 5046022),
('ramayana-5-46-23', 23, 'Sundara Kanda, Sarga 46, Verse 23', 'इन्द्रजित्तु रथं दिव्यमास्थितश्चित्रकार्मुकः।
धनुर्विस्फारयामास तडिदूर्जितनिःस्वनम्॥', 'indrajit tu rathaṃ divyam āsthitaś citrakārmukaḥ
dhanur visphārayām āsa taḍidūrjitaniḥsvanam', null, 5046023),
('ramayana-5-46-24', 24, 'Sundara Kanda, Sarga 46, Verse 24', 'ततः समेतावतितीक्ष्णवेगौ महाबलौ तौ रणनिर्विशङ्कौ।
कपिश्च रक्षोऽधिपतेश्च पुत्रः सुरासुरेन्द्राविव बद्धवैरौ॥', 'tataḥ sametāv atitīkṣṇavegau mahābalau tau raṇanirviśaṅkau
kapiś ca rakṣo''dhipateś ca putraḥ surāsurendrāv iva baddhavairau', null, 5046024),
('ramayana-5-46-25', 25, 'Sundara Kanda, Sarga 46, Verse 25', 'स तस्य वीरस्य महारथस्या धनुष्मतः संयति संमतस्य।
शरप्रवेगं व्यहनत्प्रवृद्धश्चचार मार्गे पितुरप्रमेयः॥', 'sa tasya vīrasya mahārathasyā dhanuṣmataḥ saṃyati saṃmatasya
śarapravegaṃ vyahanat pravṛddhaś cacāra mārge pitur aprameyaḥ', null, 5046025),
('ramayana-5-46-26', 26, 'Sundara Kanda, Sarga 46, Verse 26', 'ततः शरानायततीक्ष्णशल्यान्सुपत्रिणः काञ्चनचित्रपुङ्खान्।
मुमोच वीरः परवीरहन्ता सुसंततान्वज्रनिपातवेगान्॥', 'tataḥ śarān āyatatīkṣṇaśalyān supatriṇaḥ kāñcanacitrapuṅkhān
mumoca vīraḥ paravīrahantā susaṃtatān vajranipātavegān', null, 5046026),
('ramayana-5-46-27', 27, 'Sundara Kanda, Sarga 46, Verse 27', 'स तस्य तत्स्यन्दननिःस्वनं च मृदङ्गभेरीपटहस्वनं च।
विकृष्यमाणस्य च कार्मुकस्य निशम्य घोषं पुनरुत्पपात॥', 'sa tasya tat syandananiḥsvanaṃ ca mṛdaṅgabherīpaṭahasvanaṃ ca
vikṛṣyamāṇasya ca kārmukasya niśamya ghoṣaṃ punar utpapāta', null, 5046027),
('ramayana-5-46-28', 28, 'Sundara Kanda, Sarga 46, Verse 28', 'शराणामन्तरेष्वाशु व्यवर्तत महाकपिः।
हरिस्तस्याभिलक्षस्य मोक्षयंल्लक्ष्यसंग्रहम्॥', 'śarāṇām antareṣv āśu vyavartata mahākapiḥ
haris tasyābhilakṣasya mokṣayaṃl lakṣyasaṃgraham', null, 5046028),
('ramayana-5-46-29', 29, 'Sundara Kanda, Sarga 46, Verse 29', 'शराणामग्रतस्तस्य पुनः समभिवर्तत।
प्रसार्य हस्तौ हनुमानुत्पपातानिलात्मजः॥', 'śarāṇām agratas tasya punaḥ samabhivartata
prasārya hastau hanumān utpapātānilātmajaḥ', null, 5046029),
('ramayana-5-46-30', 30, 'Sundara Kanda, Sarga 46, Verse 30', 'तावुभौ वेगसंपन्नौ रणकर्मविशारदौ।
सर्वभूतमनोग्राहि चक्रतुर्युद्धमुत्तमम्॥', 'tāv ubhau vegasaṃpannau raṇakarmaviśāradau
sarvabhūtamanogrāhi cakratur yuddham uttamam', null, 5046030),
('ramayana-5-46-31', 31, 'Sundara Kanda, Sarga 46, Verse 31', 'हनूमतो वेद न राक्षसोऽन्तरं न मारुतिस्तस्य महात्मनोऽन्तरम्।
परस्परं निर्विषहौ बभूवतुः समेत्य तौ देवसमानविक्रमौ॥', 'hanūmato veda na rākṣaso ''ntaraṃ na mārutis tasya mahātmano ''ntaram
parasparaṃ nirviṣahau babhūvatuḥ sametya tau devasamānavikramau', null, 5046031),
('ramayana-5-46-32', 32, 'Sundara Kanda, Sarga 46, Verse 32', 'ततस्तु लक्ष्ये स विहन्यमाने शरेषु मोघेषु च संपतत्सु।
जगाम चिन्तां महतीं महात्मा समाधिसंयोगसमाहितात्मा॥', 'tatas tu lakṣye sa vihanyamāne śareṣu mogheṣu ca saṃpatatsu
jagāma cintāṃ mahatīṃ mahātmā samādhisaṃyogasamāhitātmā', null, 5046032),
('ramayana-5-46-33', 33, 'Sundara Kanda, Sarga 46, Verse 33', 'ततो मतिं राक्षसराजसूनुश्चकार तस्मिन्हरिवीरमुख्ये।
अवध्यतां तस्य कपेः समीक्ष्य कथं निगच्छेदिति निग्रहार्थम्॥', 'tato matiṃ rākṣasarājasūnuś cakāra tasmin harivīramukhye
avadhyatāṃ tasya kapeḥ samīkṣya kathaṃ nigacched iti nigrahārtham', null, 5046033),
('ramayana-5-46-34', 34, 'Sundara Kanda, Sarga 46, Verse 34', 'ततः पैतामहां वीरः सोऽस्त्रमस्त्रविदां वरः।
संदधे सुमहातेजास्तं हरिप्रवरं प्रति॥', 'tataḥ paitāmahāṃ vīraḥ so ''stram astravidāṃ varaḥ
saṃdadhe sumahātejās taṃ haripravaraṃ prati', null, 5046034),
('ramayana-5-46-35', 35, 'Sundara Kanda, Sarga 46, Verse 35', 'अवध्योऽयमिति ज्ञात्वा तमस्त्रेणास्त्रतत्त्ववित्।
निजग्राह महाबाहुर्मारुतात्मजमिन्द्रजित्॥', 'avadhyo ''yam iti jñātvā tam astreṇāstratattvavit
nijagrāha mahābāhur mārutātmajam indrajit', null, 5046035),
('ramayana-5-46-36', 36, 'Sundara Kanda, Sarga 46, Verse 36', 'तेन बद्धस्ततोऽस्त्रेण राक्षसेन स वानरः।
अभवन्निर्विचेष्टश्च पपात च महीतले॥', 'tena baddhas tato ''streṇa rākṣasena sa vānaraḥ
abhavan nirviceṣṭaś ca papāta ca mahītale', null, 5046036),
('ramayana-5-46-37', 37, 'Sundara Kanda, Sarga 46, Verse 37', 'ततोऽथ बुद्ध्वा स तदास्त्रबन्धं प्रभोः प्रभावाद्विगताल्पवेगः।
पितामहानुग्रहमात्मनश्च विचिन्तयामास हरिप्रवीरः॥', 'tato ''tha buddhvā sa tadāstrabandhaṃ prabhoḥ prabhāvād vigatālpavegaḥ
pitāmahānugraham ātmanaś ca vicintayām āsa haripravīraḥ', null, 5046037),
('ramayana-5-46-38', 38, 'Sundara Kanda, Sarga 46, Verse 38', 'ततः स्वायम्भुवैर्मन्त्रैर्ब्रह्मास्त्रमभिमन्त्रितम्।
हनूमांश्चिन्तयामास वरदानं पितामहात्॥', 'tataḥ svāyambhuvair mantrair brahmāstram abhimantritam
hanūmāṃś cintayām āsa varadānaṃ pitāmahāt', null, 5046038),
('ramayana-5-46-39', 39, 'Sundara Kanda, Sarga 46, Verse 39', 'न मेऽस्त्रबन्धस्य च शक्तिरस्ति विमोक्षणे लोकगुरोः प्रभावात्।
इत्येवमेवंविहितोऽस्त्रबन्धो मयात्मयोनेरनुवर्तितव्यः॥', 'na me ''strabandhasya ca śaktir asti vimokṣaṇe lokaguroḥ prabhāvāt
ity evam evaṃvihito ''strabandho mayātmayoner anuvartitavyaḥ', null, 5046039),
('ramayana-5-46-40', 40, 'Sundara Kanda, Sarga 46, Verse 40', 'स वीर्यमस्त्रस्य कपिर्विचार्य पितामहानुग्रहमात्मनश्च।
विमोक्षशक्तिं परिचिन्तयित्वा पितामहाज्ञामनुवर्तते स्म॥', 'sa vīryam astrasya kapir vicārya pitāmahānugraham ātmanaś ca
vimokṣaśaktiṃ paricintayitvā pitāmahājñām anuvartate sma', null, 5046040),
('ramayana-5-46-41', 41, 'Sundara Kanda, Sarga 46, Verse 41', 'अस्त्रेणापि हि बद्धस्य भयं मम न जायते।
पितामहमहेन्द्राभ्यां रक्षितस्यानिलेन च॥', 'astreṇāpi hi baddhasya bhayaṃ mama na jāyate
pitāmahamahendrābhyāṃ rakṣitasyānilena ca', null, 5046041),
('ramayana-5-46-42', 42, 'Sundara Kanda, Sarga 46, Verse 42', 'ग्रहणे चापि रक्षोभिर्महन्मे गुणदर्शनम्।
राक्षसेन्द्रेण संवादस्तस्माद्गृह्णन्तु मां परे॥', 'grahaṇe cāpi rakṣobhir mahan me guṇadarśanam
rākṣasendreṇa saṃvādas tasmād gṛhṇantu māṃ pare', null, 5046042),
('ramayana-5-46-43', 43, 'Sundara Kanda, Sarga 46, Verse 43', 'स निश्चितार्थः परवीरहन्ता समीक्ष्य करी विनिवृत्तचेष्टः।
परैः प्रसह्याभिगतैर्निगृह्य ननाद तैस्तैः परिभर्त्स्यमानः॥', 'sa niścitārthaḥ paravīrahantā samīkṣya karī vinivṛttaceṣṭaḥ
paraiḥ prasahyābhigatair nigṛhya nanāda tais taiḥ paribhartsyamānaḥ', null, 5046043),
('ramayana-5-46-44', 44, 'Sundara Kanda, Sarga 46, Verse 44', 'ततस्तं राक्षसा दृष्ट्वा निर्विचेष्टमरिंदमम्।
बबन्धुः शणवल्कैश्च द्रुमचीरैश्च संहतैः॥', 'tatas taṃ rākṣasā dṛṣṭvā nirviceṣṭam ariṃdamam
babandhuḥ śaṇavalkaiś ca drumacīraiś ca saṃhataiḥ', null, 5046044),
('ramayana-5-46-45', 45, 'Sundara Kanda, Sarga 46, Verse 45', 'स रोचयामास परैश्च बन्धनं प्रसह्य वीरैरभिनिग्रहं च।
कौतूहलान्मां यदि राक्षसेन्द्रो द्रष्टुं व्यवस्येदिति निश्चितार्थः॥', 'sa rocayām āsa paraiś ca bandhanaṃ prasahya vīrair abhinigrahaṃ ca
kautūhalān māṃ yadi rākṣasendro draṣṭuṃ vyavasyed iti niścitārthaḥ', null, 5046045),
('ramayana-5-46-46', 46, 'Sundara Kanda, Sarga 46, Verse 46', 'स बद्धस्तेन वल्केन विमुक्तोऽस्त्रेण वीर्यवान्।
अस्त्रबन्धः स चान्यं हि न बन्धमनुवर्तते॥', 'sa baddhas tena valkena vimukto ''streṇa vīryavān
astrabandhaḥ sa cānyaṃ hi na bandham anuvartate', null, 5046046),
('ramayana-5-46-47', 47, 'Sundara Kanda, Sarga 46, Verse 47', 'अथेन्द्रजित्तं द्रुमचीरबन्धं विचार्य वीरः कपिसत्तमं तम्।
विमुक्तमस्त्रेण जगाम चिन्तामन्येन बद्धो ह्यनुवर्ततेऽस्त्रम्॥', 'athendrajit taṃ drumacīrabandhaṃ vicārya vīraḥ kapisattamaṃ tam
vimuktam astreṇa jagāma cintām anyena baddho hy anuvartate ''stram', null, 5046047),
('ramayana-5-46-48', 48, 'Sundara Kanda, Sarga 46, Verse 48', 'अहो महत्कर्म कृतं निरर्थकं न राक्षसैर्मन्त्रगतिर्विमृष्टा।
पुनश्च नास्त्रे विहतेऽस्त्रमन्यत्प्रवर्तते संशयिताः स्म सर्वे॥', 'aho mahat karma kṛtaṃ nirarthakaṃ na rākṣasair mantragatir vimṛṣṭā
punaś ca nāstre vihate ''stram anyat pravartate saṃśayitāḥ sma sarve', null, 5046048),
('ramayana-5-46-49', 49, 'Sundara Kanda, Sarga 46, Verse 49', 'अस्त्रेण हनुमान्मुक्तो नात्मानमवबुध्यते।
कृष्यमाणस्तु रक्षोभिस्तैश्च बन्धैर्निपीडितः॥', 'astreṇa hanumān mukto nātmānam avabudhyate
kṛṣyamāṇas tu rakṣobhis taiś ca bandhair nipīḍitaḥ', null, 5046049),
('ramayana-5-46-50', 50, 'Sundara Kanda, Sarga 46, Verse 50', 'हन्यमानस्ततः क्रूरै राक्षसैः काष्ठमुष्टिभिः।
समीपं राक्षसेन्द्रस्य प्राकृष्यत स वानरः॥', 'hanyamānas tataḥ krūrai rākṣasaiḥ kāṣṭhamuṣṭibhiḥ
samīpaṃ rākṣasendrasya prākṛṣyata sa vānaraḥ', null, 5046050),
('ramayana-5-46-51', 51, 'Sundara Kanda, Sarga 46, Verse 51', 'अथेन्द्रजित्तं प्रसमीक्ष्य मुक्तमस्त्रेण बद्धं द्रुमचीरसूत्रैः।
व्यदर्शयत्तत्र महाबलं तं हरिप्रवीरं सगणाय राज्ञे॥', 'athendrajit taṃ prasamīkṣya muktam astreṇa baddhaṃ drumacīrasūtraiḥ
vyadarśayat tatra mahābalaṃ taṃ haripravīraṃ sagaṇāya rājñe', null, 5046051),
('ramayana-5-46-52', 52, 'Sundara Kanda, Sarga 46, Verse 52', 'तं मत्तमिव मातङ्गं बद्धं कपिवरोत्तमम्।
राक्षसा राक्षसेन्द्राय रावणाय न्यवेदयन्॥', 'taṃ mattam iva mātaṅgaṃ baddhaṃ kapivarottamam
rākṣasā rākṣasendrāya rāvaṇāya nyavedayan', null, 5046052),
('ramayana-5-46-53', 53, 'Sundara Kanda, Sarga 46, Verse 53', 'कोऽयं कस्य कुतो वापि किं कार्यं को व्यपाश्रयः।
इति राक्षसवीराणां तत्र संजज्ञिरे कथाः॥', 'ko ''yaṃ kasya kuto vāpi kiṃ kāryaṃ ko vyapāśrayaḥ
iti rākṣasavīrāṇāṃ tatra saṃjajñire kathāḥ', null, 5046053),
('ramayana-5-46-54', 54, 'Sundara Kanda, Sarga 46, Verse 54', 'हन्यतां दह्यतां वापि भक्ष्यतामिति चापरे।
राक्षसास्तत्र संक्रुद्धाः परस्परमथाब्रुवन्॥', 'hanyatāṃ dahyatāṃ vāpi bhakṣyatām iti cāpare
rākṣasās tatra saṃkruddhāḥ parasparam athābruvan', null, 5046054),
('ramayana-5-46-55', 55, 'Sundara Kanda, Sarga 46, Verse 55', 'अतीत्य मार्गं सहसा महात्मा स तत्र रक्षोऽधिपपादमूले।
ददर्श राज्ञः परिचारवृद्धान्गृहं महारत्नविभूषितं च॥', 'atītya mārgaṃ sahasā mahātmā sa tatra rakṣo''dhipapādamūle
dadarśa rājñaḥ paricāravṛddhān gṛhaṃ mahāratnavibhūṣitaṃ ca', null, 5046055),
('ramayana-5-46-56', 56, 'Sundara Kanda, Sarga 46, Verse 56', 'स ददर्श महातेजा रावणः कपिसत्तमम्।
रक्षोभिर्विकृताकारैः कृष्यमाणमितस्ततः॥', 'sa dadarśa mahātejā rāvaṇaḥ kapisattamam
rakṣobhir vikṛtākāraiḥ kṛṣyamāṇam itas tataḥ', null, 5046056),
('ramayana-5-46-57', 57, 'Sundara Kanda, Sarga 46, Verse 57', 'राक्षसाधिपतिं चापि ददर्श कपिसत्तमः।
तेजोबलसमायुक्तं तपन्तमिव भास्करम्॥', 'rākṣasādhipatiṃ cāpi dadarśa kapisattamaḥ
tejobalasamāyuktaṃ tapantam iva bhāskaram', null, 5046057),
('ramayana-5-46-58', 58, 'Sundara Kanda, Sarga 46, Verse 58', 'स रोषसंवर्तितताम्रदृष्टिर्दशाननस्तं कपिमन्ववेक्ष्य।
अथोपविष्टान्कुलशीलवृद्धान्समादिशत्तं प्रति मन्त्रमुख्यान्॥', 'sa roṣasaṃvartitatāmradṛṣṭir daśānanas taṃ kapim anvavekṣya
athopaviṣṭān kulaśīlavṛddhān samādiśat taṃ prati mantramukhyān', null, 5046058),
('ramayana-5-46-59', 59, 'Sundara Kanda, Sarga 46, Verse 59', 'यथाक्रमं तैः स कपिश्च पृष्टः कार्यार्थमर्थस्य च मूलमादौ।
निवेदयामास हरीश्वरस्य दूतः सकाशादहमागतोऽस्मि॥', 'yathākramaṃ taiḥ sa kapiś ca pṛṣṭaḥ kāryārtham arthasya ca mūlam ādau
nivedayām āsa harīśvarasya dūtaḥ sakāśād aham āgato ''smi', null, 5046059)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 47 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-47-1', 1, 'Sundara Kanda, Sarga 47, Verse 1', 'ततः स कर्मणा तस्य विस्मितो भीमविक्रमः।
हनुमान्रोषताम्राक्षो रक्षोऽधिपमवैक्षत॥', 'tataḥ sa karmaṇā tasya vismito bhīmavikramaḥ
hanumān roṣatāmrākṣo rakṣo''dhipam avaikṣata', null, 5047001),
('ramayana-5-47-2', 2, 'Sundara Kanda, Sarga 47, Verse 2', 'भाजमानं महार्हेण काञ्चनेन विराजता।
मुक्ताजालावृतेनाथ मुकुटेन महाद्युतिम्॥', 'bhājamānaṃ mahārheṇa kāñcanena virājatā
muktājālāvṛtenātha mukuṭena mahādyutim', null, 5047002),
('ramayana-5-47-3', 3, 'Sundara Kanda, Sarga 47, Verse 3', 'वज्रसंयोगसंयुक्तैर्महार्हमणिविग्रहैः।
हैमैराभरणैश्चित्रैर्मनसेव प्रकल्पितैः॥', 'vajrasaṃyogasaṃyuktair mahārhamaṇivigrahaiḥ
haimair ābharaṇaiś citrair manaseva prakalpitaiḥ', null, 5047003),
('ramayana-5-47-4', 4, 'Sundara Kanda, Sarga 47, Verse 4', 'महार्हक्षौमसंवीतं रक्तचन्दनरूषितम्।
स्वनुलिप्तं विचित्राभिर्विविधभिश्च भक्तिभिः॥', 'mahārhakṣaumasaṃvītaṃ raktacandanarūṣitam
svanuliptaṃ vicitrābhir vividhabhiś ca bhaktibhiḥ', null, 5047004),
('ramayana-5-47-5', 5, 'Sundara Kanda, Sarga 47, Verse 5', 'विपुलैर्दर्शनीयैश्च रक्षाक्षैर्भीमदर्शनैः।
दीप्ततीक्ष्णमहादंष्ट्रैः प्रलम्बदशनच्छदैः॥', 'vipulair darśanīyaiś ca rakṣākṣair bhīmadarśanaiḥ
dīptatīkṣṇamahādaṃṣṭraiḥ pralambadaśanacchadaiḥ', null, 5047005),
('ramayana-5-47-6', 6, 'Sundara Kanda, Sarga 47, Verse 6', 'शिरोभिर्दशभिर्वीरं भ्राजमानं महौजसं।
नानाव्यालसमाकीर्णैः शिखरैरिव मन्दरम्॥', 'śirobhir daśabhir vīraṃ bhrājamānaṃ mahaujasaṃ
nānāvyālasamākīrṇaiḥ śikharair iva mandaram', null, 5047006),
('ramayana-5-47-7', 7, 'Sundara Kanda, Sarga 47, Verse 7', 'नीलाञ्जनचय प्रख्यं हारेणोरसि राजता।
पूर्णचन्द्राभवक्त्रेण सबलाकमिवाम्बुदम्॥', 'nīlāñjanacaya prakhyaṃ hāreṇorasi rājatā
pūrṇacandrābhavaktreṇa sabalākam ivāmbudam', null, 5047007),
('ramayana-5-47-8', 8, 'Sundara Kanda, Sarga 47, Verse 8', 'बाहुभिर्बद्धकेयूरैश्चन्दनोत्तमरूषितैः।
भ्राजमानाङ्गदैः पीनैः पञ्चशीर्षैरिवोरगैः॥', 'bāhubhir baddhakeyūraiś candanottamarūṣitaiḥ
bhrājamānāṅgadaiḥ pīnaiḥ pañcaśīrṣair ivoragaiḥ', null, 5047008),
('ramayana-5-47-9', 9, 'Sundara Kanda, Sarga 47, Verse 9', 'महति स्फाटिके चित्रे रत्नसंयोगसंस्कृते।
उत्तमास्तरणास्तीर्णे उपविष्टं वरासने॥', 'mahati sphāṭike citre ratnasaṃyogasaṃskṛte
uttamāstaraṇāstīrṇe upaviṣṭaṃ varāsane', null, 5047009),
('ramayana-5-47-10', 10, 'Sundara Kanda, Sarga 47, Verse 10', 'अलंकृताभिरत्यर्थं प्रमदाभिः समन्ततः।
वालव्यजनहस्ताभिरारात्समुपसेवितम्॥', 'alaṃkṛtābhir atyarthaṃ pramadābhiḥ samantataḥ
vālavyajanahastābhir ārāt samupasevitam', null, 5047010),
('ramayana-5-47-11', 11, 'Sundara Kanda, Sarga 47, Verse 11', 'दुर्धरेण प्रहस्तेन महापार्श्वेन रक्षसा।
मन्त्रिभिर्मन्त्रतत्त्वज्ञैर्निकुम्भेन च मन्त्रिणा॥', 'durdhareṇa prahastena mahāpārśvena rakṣasā
mantribhir mantratattvajñair nikumbhena ca mantriṇā', null, 5047011),
('ramayana-5-47-12', 12, 'Sundara Kanda, Sarga 47, Verse 12', 'उपोपविष्टं रक्षोभिश्चतुर्भिर्बलदर्पितैः।
कृत्स्नैः परिवृतं लोकं चतुर्भिरिव सागरैः॥', 'upopaviṣṭaṃ rakṣobhiś caturbhir baladarpitaiḥ
kṛtsnaiḥ parivṛtaṃ lokaṃ caturbhir iva sāgaraiḥ', null, 5047012),
('ramayana-5-47-13', 13, 'Sundara Kanda, Sarga 47, Verse 13', 'मन्त्रिभिर्मन्त्रतत्त्वज्ञैरन्यैश्च शुभबुद्धिभिः।
अन्वास्यमानं सचिवैः सुरैरिव सुरेश्वरम्॥', 'mantribhir mantratattvajñair anyaiś ca śubhabuddhibhiḥ
anvāsyamānaṃ sacivaiḥ surair iva sureśvaram', null, 5047013),
('ramayana-5-47-14', 14, 'Sundara Kanda, Sarga 47, Verse 14', 'अपश्यद्राक्षसपतिं हनूमानतितेजसं।
विष्ठितं मेरुशिखरे सतोयमिव तोयदम्॥', 'apaśyad rākṣasapatiṃ hanūmān atitejasaṃ
viṣṭhitaṃ meruśikhare satoyam iva toyadam', null, 5047014),
('ramayana-5-47-15', 15, 'Sundara Kanda, Sarga 47, Verse 15', 'स तैः संपीड्यमानोऽपि रक्षोभिर्भीमविक्रमैः।
विस्मयं परमं गत्वा रक्षोऽधिपमवैक्षत॥', 'sa taiḥ saṃpīḍyamāno ''pi rakṣobhir bhīmavikramaiḥ
vismayaṃ paramaṃ gatvā rakṣo''dhipam avaikṣata', null, 5047015),
('ramayana-5-47-16', 16, 'Sundara Kanda, Sarga 47, Verse 16', 'भ्राजमानं ततो दृष्ट्वा हनुमान्राक्षसेश्वरम्।
मनसा चिन्तयामास तेजसा तस्य मोहितः॥', 'bhrājamānaṃ tato dṛṣṭvā hanumān rākṣaseśvaram
manasā cintayām āsa tejasā tasya mohitaḥ', null, 5047016),
('ramayana-5-47-17', 17, 'Sundara Kanda, Sarga 47, Verse 17', 'अहो रूपमहो धैर्यमहो सत्त्वमहो द्युतिः।
अहो राक्षसराजस्य सर्वलक्षणयुक्तता॥', 'aho rūpam aho dhairyam aho sattvam aho dyutiḥ
aho rākṣasarājasya sarvalakṣaṇayuktatā', null, 5047017),
('ramayana-5-47-18', 18, 'Sundara Kanda, Sarga 47, Verse 18', 'यद्यधर्मो न बलवान्स्यादयं राक्षसेश्वरः।
स्यादयं सुरलोकस्य सशक्रस्यापि रक्षिता॥', 'yady adharmo na balavān syād ayaṃ rākṣaseśvaraḥ
syād ayaṃ suralokasya saśakrasyāpi rakṣitā', null, 5047018),
('ramayana-5-47-19', 19, 'Sundara Kanda, Sarga 47, Verse 19', 'तेन बिभ्यति खल्वस्माल्लोकाः सामरदानवाः।
अयं ह्युत्सहते क्रुद्धः कर्तुमेकार्णवं जगत्॥', 'tena bibhyati khalv asmāl lokāḥ sāmaradānavāḥ
ayaṃ hy utsahate kruddhaḥ kartum ekārṇavaṃ jagat', null, 5047019),
('ramayana-5-47-20', 20, 'Sundara Kanda, Sarga 47, Verse 20', 'इति चिन्तां बहुविधामकरोन्मतिमान्कपिः।
दृष्ट्वा राक्षसराजस्य प्रभावममितौजसः॥', 'iti cintāṃ bahuvidhām akaron matimān kapiḥ
dṛṣṭvā rākṣasarājasya prabhāvam amitaujasaḥ', null, 5047020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 48 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-48-1', 1, 'Sundara Kanda, Sarga 48, Verse 1', 'तमुद्वीक्ष्य महाबाहुः पिङ्गाक्षं पुरतः स्थितम्।
रोषेण महताविष्टो रावणो लोकरावणः॥', 'tam udvīkṣya mahābāhuḥ piṅgākṣaṃ purataḥ sthitam
roṣeṇa mahatāviṣṭo rāvaṇo lokarāvaṇaḥ', null, 5048001),
('ramayana-5-48-2', 2, 'Sundara Kanda, Sarga 48, Verse 2', 'स राजा रोषताम्राक्षः प्रहस्तं मन्त्रिसत्तमम्।
कालयुक्तमुवाचेदं वचो विपुलमर्थवत्॥', 'sa rājā roṣatāmrākṣaḥ prahastaṃ mantrisattamam
kālayuktam uvācedaṃ vaco vipulam arthavat', null, 5048002),
('ramayana-5-48-3', 3, 'Sundara Kanda, Sarga 48, Verse 3', 'दुरात्मा पृच्छ्यतामेष कुतः किं वास्य कारणम्।
वनभङ्गे च कोऽस्यार्थो राक्षसीनां च तर्जने॥', 'durātmā pṛcchyatām eṣa kutaḥ kiṃ vāsya kāraṇam
vanabhaṅge ca ko ''syārtho rākṣasīnāṃ ca tarjane', null, 5048003),
('ramayana-5-48-4', 4, 'Sundara Kanda, Sarga 48, Verse 4', 'रावणस्य वचः श्रुत्वा प्रहस्तो वाक्यमब्रवीत्।
समाश्वसिहि भद्रं ते न भीः कार्या त्वया कपे॥', 'rāvaṇasya vacaḥ śrutvā prahasto vākyam abravīt
samāśvasihi bhadraṃ te na bhīḥ kāryā tvayā kape', null, 5048004),
('ramayana-5-48-5', 5, 'Sundara Kanda, Sarga 48, Verse 5', 'यदि तावत्त्वमिन्द्रेण प्रेषितो रावणालयम्।
तत्त्वमाख्याहि मा ते भूद्भयं वानर मोक्ष्यसे॥', 'yadi tāvat tvam indreṇa preṣito rāvaṇālayam
tattvam ākhyāhi mā te bhūd bhayaṃ vānara mokṣyase', null, 5048005),
('ramayana-5-48-6', 6, 'Sundara Kanda, Sarga 48, Verse 6', 'यदि वैश्रवणस्य त्वं यमस्य वरुणस्य च।
चारुरूपमिदं कृत्वा यमस्य वरुणस्य च॥', 'yadi vaiśravaṇasya tvaṃ yamasya varuṇasya ca
cārurūpam idaṃ kṛtvā yamasya varuṇasya ca', null, 5048006),
('ramayana-5-48-7', 7, 'Sundara Kanda, Sarga 48, Verse 7', 'विष्णुना प्रेषितो वापि दूतो विजयकाङ्क्षिणा।
न हि ते वानरं तेजो रूपमात्रं तु वानरम्॥', 'viṣṇunā preṣito vāpi dūto vijayakāṅkṣiṇā
na hi te vānaraṃ tejo rūpamātraṃ tu vānaram', null, 5048007),
('ramayana-5-48-8', 8, 'Sundara Kanda, Sarga 48, Verse 8', 'तत्त्वतः कथयस्वाद्य ततो वानर मोक्ष्यसे।
अनृतं वदतश्चापि दुर्लभं तव जीवितम्॥', 'tattvataḥ kathayasvādya tato vānara mokṣyase
anṛtaṃ vadataś cāpi durlabhaṃ tava jīvitam', null, 5048008),
('ramayana-5-48-9', 9, 'Sundara Kanda, Sarga 48, Verse 9', 'अथ वा यन्निमित्तस्ते प्रवेशो रावणालये॥', 'atha vā yannimittas te praveśo rāvaṇālaye', null, 5048009),
('ramayana-5-48-10', 10, 'Sundara Kanda, Sarga 48, Verse 10', 'एवमुक्तो हरिवरस्तदा रक्षोगणेश्वरम्।
अब्रवीन्नास्मि शक्रस्य यमस्य वरुणस्य वा॥', 'evam ukto harivaras tadā rakṣogaṇeśvaram
abravīn nāsmi śakrasya yamasya varuṇasya vā', null, 5048010),
('ramayana-5-48-11', 11, 'Sundara Kanda, Sarga 48, Verse 11', 'धनदेन न मे सख्यं विष्णुना नास्मि चोदितः।
जातिरेव मम त्वेषा वानरोऽहमिहागतः॥', 'dhanadena na me sakhyaṃ viṣṇunā nāsmi coditaḥ
jātir eva mama tv eṣā vānaro ''ham ihāgataḥ', null, 5048011),
('ramayana-5-48-12', 12, 'Sundara Kanda, Sarga 48, Verse 12', 'दर्शने राक्षसेन्द्रस्य दुर्लभे तदिदं मया।
वनं राक्षसराजस्य दर्शनार्थे विनाशितम्॥', 'darśane rākṣasendrasya durlabhe tad idaṃ mayā
vanaṃ rākṣasarājasya darśanārthe vināśitam', null, 5048012),
('ramayana-5-48-13', 13, 'Sundara Kanda, Sarga 48, Verse 13', 'ततस्ते राक्षसाः प्राप्ता बलिनो युद्धकाङ्क्षिणः।
रक्षणार्थं च देहस्य प्रतियुद्धा मया रणे॥', 'tatas te rākṣasāḥ prāptā balino yuddhakāṅkṣiṇaḥ
rakṣaṇārthaṃ ca dehasya pratiyuddhā mayā raṇe', null, 5048013),
('ramayana-5-48-14', 14, 'Sundara Kanda, Sarga 48, Verse 14', 'अस्त्रपाशैर्न शक्योऽहं बद्धुं देवासुरैरपि।
पितामहादेव वरो ममाप्येषोऽभ्युपागतः॥', 'astrapāśair na śakyo ''haṃ baddhuṃ devāsurair api
pitāmahād eva varo mamāpy eṣo ''bhyupāgataḥ', null, 5048014),
('ramayana-5-48-15', 15, 'Sundara Kanda, Sarga 48, Verse 15', 'राजानं द्रष्टुकामेन मयास्त्रमनुवर्तितम्।
विमुक्तो अहमस्त्रेण राक्षसैस्त्वतिपीडितः॥', 'rājānaṃ draṣṭukāmena mayāstram anuvartitam
vimukto aham astreṇa rākṣasais tv atipīḍitaḥ', null, 5048015),
('ramayana-5-48-16', 16, 'Sundara Kanda, Sarga 48, Verse 16', 'दूतोऽहमिति विज्ञेयो राघवस्यामितौजसः।
श्रूयतां चापि वचनं मम पथ्यमिदं प्रभो॥', 'dūto ''ham iti vijñeyo rāghavasyāmitaujasaḥ
śrūyatāṃ cāpi vacanaṃ mama pathyam idaṃ prabho', null, 5048016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 49 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-49-1', 1, 'Sundara Kanda, Sarga 49, Verse 1', 'तं समीक्ष्य महासत्त्वं सत्त्ववान्हरिसत्तमः।
वाक्यमर्थवदव्यग्रस्तमुवाच दशाननम्॥', 'taṃ samīkṣya mahāsattvaṃ sattvavān harisattamaḥ
vākyam arthavad avyagras tam uvāca daśānanam', null, 5049001),
('ramayana-5-49-2', 2, 'Sundara Kanda, Sarga 49, Verse 2', 'अहं सुग्रीवसंदेशादिह प्राप्तस्तवालयम्।
राक्षसेन्द्र हरीशस्त्वां भ्राता कुशलमब्रवीत्॥', 'ahaṃ sugrīvasaṃdeśād iha prāptas tavālayam
rākṣasendra harīśas tvāṃ bhrātā kuśalam abravīt', null, 5049002),
('ramayana-5-49-3', 3, 'Sundara Kanda, Sarga 49, Verse 3', 'भ्रातुः शृणु समादेशं सुग्रीवस्य महात्मनः।
धर्मार्थोपहितं वाक्यमिह चामुत्र च क्षमम्॥', 'bhrātuḥ śṛṇu samādeśaṃ sugrīvasya mahātmanaḥ
dharmārthopahitaṃ vākyam iha cāmutra ca kṣamam', null, 5049003),
('ramayana-5-49-4', 4, 'Sundara Kanda, Sarga 49, Verse 4', 'राजा दशरथो नाम रथकुञ्जरवाजिमान्।
पितेव बन्धुर्लोकस्य सुरेश्वरसमद्युतिः॥', 'rājā daśaratho nāma rathakuñjaravājimān
piteva bandhur lokasya sureśvarasamadyutiḥ', null, 5049004),
('ramayana-5-49-5', 5, 'Sundara Kanda, Sarga 49, Verse 5', 'ज्येष्ठस्तस्य महाबाहुः पुत्रः प्रियकरः प्रभुः।
पितुर्निदेशान्निष्क्रान्तः प्रविष्टो दण्डकावनम्॥', 'jyeṣṭhas tasya mahābāhuḥ putraḥ priyakaraḥ prabhuḥ
pitur nideśān niṣkrāntaḥ praviṣṭo daṇḍakāvanam', null, 5049005),
('ramayana-5-49-6', 6, 'Sundara Kanda, Sarga 49, Verse 6', 'लक्ष्मणेन सह भ्रात्रा सीतया चापि भार्यया।
रामो नाम महातेजा धर्म्यं पन्थानमाश्रितः॥', 'lakṣmaṇena saha bhrātrā sītayā cāpi bhāryayā
rāmo nāma mahātejā dharmyaṃ panthānam āśritaḥ', null, 5049006),
('ramayana-5-49-7', 7, 'Sundara Kanda, Sarga 49, Verse 7', 'तस्य भार्या वने नष्टा सीता पतिमनुव्रता।
वैदेहस्य सुता राज्ञो जनकस्य महात्मनः॥', 'tasya bhāryā vane naṣṭā sītā patim anuvratā
vaidehasya sutā rājño janakasya mahātmanaḥ', null, 5049007),
('ramayana-5-49-8', 8, 'Sundara Kanda, Sarga 49, Verse 8', 'स मार्गमाणस्तां देवीं राजपुत्रः सहानुजः।
ऋश्यमूकमनुप्राप्तः सुग्रीवेण च संगतः॥', 'sa mārgamāṇas tāṃ devīṃ rājaputraḥ sahānujaḥ
ṛśyamūkam anuprāptaḥ sugrīveṇa ca saṃgataḥ', null, 5049008),
('ramayana-5-49-9', 9, 'Sundara Kanda, Sarga 49, Verse 9', 'तस्य तेन प्रतिज्ञातं सीतायाः परिमार्गणम्।
सुग्रीवस्यापि रामेण हरिराज्यं निवेदितम्॥', 'tasya tena pratijñātaṃ sītāyāḥ parimārgaṇam
sugrīvasyāpi rāmeṇa harirājyaṃ niveditam', null, 5049009),
('ramayana-5-49-10', 10, 'Sundara Kanda, Sarga 49, Verse 10', 'ततस्तेन मृधे हत्वा राजपुत्रेण वालिनम्।
सुग्रीवः स्थापितो राज्ये हर्यृक्षाणां गणेश्वरः॥', 'tatas tena mṛdhe hatvā rājaputreṇa vālinam
sugrīvaḥ sthāpito rājye haryṛkṣāṇāṃ gaṇeśvaraḥ', null, 5049010),
('ramayana-5-49-11', 11, 'Sundara Kanda, Sarga 49, Verse 11', 'स सीतामार्गणे व्यग्रः सुग्रीवः सत्यसंगरः।
हरीन्संप्रेषयामास दिशः सर्वा हरीश्वरः॥', 'sa sītāmārgaṇe vyagraḥ sugrīvaḥ satyasaṃgaraḥ
harīn saṃpreṣayām āsa diśaḥ sarvā harīśvaraḥ', null, 5049011),
('ramayana-5-49-12', 12, 'Sundara Kanda, Sarga 49, Verse 12', 'तां हरीणां सहस्राणि शतानि नियुतानि च।
दिक्षु सर्वासु मार्गन्ते अधश्चोपरि चाम्बरे॥', 'tāṃ harīṇāṃ sahasrāṇi śatāni niyutāni ca
dikṣu sarvāsu mārgante adhaś copari cāmbare', null, 5049012),
('ramayana-5-49-13', 13, 'Sundara Kanda, Sarga 49, Verse 13', 'वैनतेय समाः के चित्के चित्तत्रानिलोपमाः।
असंगगतयः शीघ्रा हरिवीरा महाबलाः॥', 'vainateya samāḥ ke cit ke cit tatrānilopamāḥ
asaṃgagatayaḥ śīghrā harivīrā mahābalāḥ', null, 5049013),
('ramayana-5-49-14', 14, 'Sundara Kanda, Sarga 49, Verse 14', 'अहं तु हनुमान्नाम मारुतस्यौरसः सुतः।
सीतायास्तु कृते तूर्णं शतयोजनमायतम्।
समुद्रं लङ्घयित्वैव तां दिदृक्षुरिहागतः॥', 'ahaṃ tu hanumān nāma mārutasyaurasaḥ sutaḥ
sītāyās tu kṛte tūrṇaṃ śatayojanam āyatam
samudraṃ laṅghayitvaiva tāṃ didṛkṣur ihāgataḥ', null, 5049014),
('ramayana-5-49-15', 15, 'Sundara Kanda, Sarga 49, Verse 15', 'तद्भवान्दृष्टधर्मार्थस्तपः कृतपरिग्रहः।
परदारान्महाप्राज्ञ नोपरोद्धुं त्वमर्हसि॥', 'tad bhavān dṛṣṭadharmārthas tapaḥ kṛtaparigrahaḥ
paradārān mahāprājña noparoddhuṃ tvam arhasi', null, 5049015),
('ramayana-5-49-16', 16, 'Sundara Kanda, Sarga 49, Verse 16', 'न हि धर्मविरुद्धेषु बह्वपायेषु कर्मसु।
मूलघातिषु सज्जन्ते बुद्धिमन्तो भवद्विधाः॥', 'na hi dharmaviruddheṣu bahv apāyeṣu karmasu
mūlaghātiṣu sajjante buddhimanto bhavadvidhāḥ', null, 5049016),
('ramayana-5-49-17', 17, 'Sundara Kanda, Sarga 49, Verse 17', 'कश्च लक्ष्मणमुक्तानां रामकोपानुवर्तिनाम्।
शराणामग्रतः स्थातुं शक्तो देवासुरेष्वपि॥', 'kaś ca lakṣmaṇamuktānāṃ rāmakopānuvartinām
śarāṇām agrataḥ sthātuṃ śakto devāsureṣv api', null, 5049017),
('ramayana-5-49-18', 18, 'Sundara Kanda, Sarga 49, Verse 18', 'न चापि त्रिषु लोकेषु राजन्विद्येत कश्चन।
राघवस्य व्यलीकं यः कृत्वा सुखमवाप्नुयात्॥', 'na cāpi triṣu lokeṣu rājan vidyeta kaś cana
rāghavasya vyalīkaṃ yaḥ kṛtvā sukham avāpnuyāt', null, 5049018),
('ramayana-5-49-19', 19, 'Sundara Kanda, Sarga 49, Verse 19', 'तत्त्रिकालहितं वाक्यं धर्म्यमर्थानुबन्धि च।
मन्यस्व नरदेवाय जानकी प्रतिदीयताम्॥', 'tat trikālahitaṃ vākyaṃ dharmyam arthānubandhi ca
manyasva naradevāya jānakī pratidīyatām', null, 5049019),
('ramayana-5-49-20', 20, 'Sundara Kanda, Sarga 49, Verse 20', 'दृष्टा हीयं मया देवी लब्धं यदिह दुर्लभम्।
उत्तरं कर्म यच्छेषं निमित्तं तत्र राघवः॥', 'dṛṣṭā hīyaṃ mayā devī labdhaṃ yad iha durlabham
uttaraṃ karma yac cheṣaṃ nimittaṃ tatra rāghavaḥ', null, 5049020),
('ramayana-5-49-21', 21, 'Sundara Kanda, Sarga 49, Verse 21', 'लक्षितेयं मया सीता तथा शोकपरायणा।
गृह्य यां नाभिजानासि पञ्चास्यामिव पन्नगीम्॥', 'lakṣiteyaṃ mayā sītā tathā śokaparāyaṇā
gṛhya yāṃ nābhijānāsi pañcāsyām iva pannagīm', null, 5049021),
('ramayana-5-49-22', 22, 'Sundara Kanda, Sarga 49, Verse 22', 'नेयं जरयितुं शक्या सासुरैरमरैरपि।
विषसंसृष्टमत्यर्थं भुक्तमन्नमिवौजसा॥', 'neyaṃ jarayituṃ śakyā sāsurair amarair api
viṣasaṃsṛṣṭam atyarthaṃ bhuktam annam ivaujasā', null, 5049022),
('ramayana-5-49-23', 23, 'Sundara Kanda, Sarga 49, Verse 23', 'तपःसंतापलब्धस्ते योऽयं धर्मपरिग्रहः।
न स नाशयितुं न्याय्य आत्मप्राणपरिग्रहः॥', 'tapaḥsaṃtāpalabdhas te yo ''yaṃ dharmaparigrahaḥ
na sa nāśayituṃ nyāyya ātmaprāṇaparigrahaḥ', null, 5049023),
('ramayana-5-49-24', 24, 'Sundara Kanda, Sarga 49, Verse 24', 'अवध्यतां तपोभिर्यां भवान्समनुपश्यति।
आत्मनः सासुरैर्देवैर्हेतुस्तत्राप्ययं महान्॥', 'avadhyatāṃ tapobhir yāṃ bhavān samanupaśyati
ātmanaḥ sāsurair devair hetus tatrāpy ayaṃ mahān', null, 5049024),
('ramayana-5-49-25', 25, 'Sundara Kanda, Sarga 49, Verse 25', 'सुग्रीवो न हि देवोऽयं नासुरो न च मानुषः।
न राक्षसो न गन्धर्वो न यक्षो न च पन्नगः॥', 'sugrīvo na hi devo ''yaṃ nāsuro na ca mānuṣaḥ
na rākṣaso na gandharvo na yakṣo na ca pannagaḥ', null, 5049025),
('ramayana-5-49-26', 26, 'Sundara Kanda, Sarga 49, Verse 26', 'मानुषो राघवो राजन्सुग्रीवश्च हरीश्वरः।
तस्मात्प्राणपरित्राणं कथं राजन्करिष्यसि॥', 'mānuṣo rāghavo rājan sugrīvaś ca harīśvaraḥ
tasmāt prāṇaparitrāṇaṃ kathaṃ rājan kariṣyasi', null, 5049026),
('ramayana-5-49-27', 27, 'Sundara Kanda, Sarga 49, Verse 27', 'न तु धर्मोपसंहारमधर्मफलसंहितम्।
तदेव फलमन्वेति धर्मश्चाधर्मनाशनः॥', 'na tu dharmopasaṃhāram adharmaphalasaṃhitam
tad eva phalam anveti dharmaś cādharmanāśanaḥ', null, 5049027),
('ramayana-5-49-28', 28, 'Sundara Kanda, Sarga 49, Verse 28', 'प्राप्तं धर्मफलं तावद्भवता नात्र संशयः।
फलमस्याप्यधर्मस्य क्षिप्रमेव प्रपत्स्यसे॥', 'prāptaṃ dharmaphalaṃ tāvad bhavatā nātra saṃśayaḥ
phalam asyāpy adharmasya kṣipram eva prapatsyase', null, 5049028),
('ramayana-5-49-29', 29, 'Sundara Kanda, Sarga 49, Verse 29', 'जनस्थानवधं बुद्ध्वा बुद्ध्वा वालिवधं तथा।
रामसुग्रीवसख्यं च बुध्यस्व हितमात्मनः॥', 'janasthānavadhaṃ buddhvā buddhvā vālivadhaṃ tathā
rāmasugrīvasakhyaṃ ca budhyasva hitam ātmanaḥ', null, 5049029),
('ramayana-5-49-30', 30, 'Sundara Kanda, Sarga 49, Verse 30', 'कामं खल्वहमप्येकः सवाजिरथकुञ्जराम्।
लङ्कां नाशयितुं शक्तस्तस्यैष तु विनिश्चयः॥', 'kāmaṃ khalv aham apy ekaḥ savājirathakuñjarām
laṅkāṃ nāśayituṃ śaktas tasyaiṣa tu viniścayaḥ', null, 5049030),
('ramayana-5-49-31', 31, 'Sundara Kanda, Sarga 49, Verse 31', 'रामेण हि प्रतिज्ञातं हर्यृक्षगणसंनिधौ।
उत्सादनममित्राणां सीता यैस्तु प्रधर्षिता॥', 'rāmeṇa hi pratijñātaṃ haryṛkṣagaṇasaṃnidhau
utsādanam amitrāṇāṃ sītā yais tu pradharṣitā', null, 5049031),
('ramayana-5-49-32', 32, 'Sundara Kanda, Sarga 49, Verse 32', 'अपकुर्वन्हि रामस्य साक्षादपि पुरंदरः।
न सुखं प्राप्नुयादन्यः किं पुनस्त्वद्विधो जनः॥', 'apakurvan hi rāmasya sākṣād api puraṃdaraḥ
na sukhaṃ prāpnuyād anyaḥ kiṃ punas tvadvidho janaḥ', null, 5049032),
('ramayana-5-49-33', 33, 'Sundara Kanda, Sarga 49, Verse 33', 'यां सीतेत्यभिजानासि येयं तिष्ठति ते वशे।
कालरात्रीति तां विद्धि सर्वलङ्काविनाशिनीम्॥', 'yāṃ sītety abhijānāsi yeyaṃ tiṣṭhati te vaśe
kālarātrīti tāṃ viddhi sarvalaṅkāvināśinīm', null, 5049033),
('ramayana-5-49-34', 34, 'Sundara Kanda, Sarga 49, Verse 34', 'तदलं कालपाशेन सीता विग्रहरूपिणा।
स्वयं स्कन्धावसक्तेन क्षममात्मनि चिन्त्यताम्॥', 'tad alaṃ kālapāśena sītā vigraharūpiṇā
svayaṃ skandhāvasaktena kṣamam ātmani cintyatām', null, 5049034),
('ramayana-5-49-35', 35, 'Sundara Kanda, Sarga 49, Verse 35', 'सीतायास्तेजसा दग्धां रामकोपप्रपीडिताम्।
दह्यमनामिमां पश्य पुरीं साट्टप्रतोलिकाम्॥', 'sītāyās tejasā dagdhāṃ rāmakopaprapīḍitām
dahyamanām imāṃ paśya purīṃ sāṭṭapratolikām', null, 5049035),
('ramayana-5-49-36', 36, 'Sundara Kanda, Sarga 49, Verse 36', 'स सौष्ठवोपेतमदीनवादिनः कपेर्निशम्याप्रतिमोऽप्रियं वचः।
दशाननः कोपविवृत्तलोचनः समादिशत्तस्य वधं महाकपेः॥', 'sa sauṣṭhavopetam adīnavādinaḥ kaper niśamyāpratimo ''priyaṃ vacaḥ
daśānanaḥ kopavivṛttalocanaḥ samādiśat tasya vadhaṃ mahākapeḥ', null, 5049036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 50 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-50-1', 1, 'Sundara Kanda, Sarga 50, Verse 1', 'तस्य तद्वचनं श्रुत्वा वानरस्य महात्मनः।
आज्ञापयद्वधं तस्य रावणः क्रोधमूर्छितः॥', 'tasya tad vacanaṃ śrutvā vānarasya mahātmanaḥ
ājñāpayad vadhaṃ tasya rāvaṇaḥ krodhamūrchitaḥ', null, 5050001),
('ramayana-5-50-2', 2, 'Sundara Kanda, Sarga 50, Verse 2', 'वधे तस्य समाज्ञप्ते रावणेन दुरात्मना।
निवेदितवतो दौत्यं नानुमेने विभीषणः॥', 'vadhe tasya samājñapte rāvaṇena durātmanā
niveditavato dautyaṃ nānumene vibhīṣaṇaḥ', null, 5050002),
('ramayana-5-50-3', 3, 'Sundara Kanda, Sarga 50, Verse 3', 'तं रक्षोऽधिपतिं क्रुद्धं तच्च कार्यमुपस्थितम्।
विदित्वा चिन्तयामास कार्यं कार्यविधौ स्थितः॥', 'taṃ rakṣo''dhipatiṃ kruddhaṃ tac ca kāryam upasthitam
viditvā cintayām āsa kāryaṃ kāryavidhau sthitaḥ', null, 5050003),
('ramayana-5-50-4', 4, 'Sundara Kanda, Sarga 50, Verse 4', 'निश्चितार्थस्ततः साम्नापूज्य शत्रुजिदग्रजम्।
उवाच हितमत्यर्थं वाक्यं वाक्यविशारदः॥', 'niścitārthas tataḥ sāmnāpūjya śatrujidagrajam
uvāca hitam atyarthaṃ vākyaṃ vākyaviśāradaḥ', null, 5050004),
('ramayana-5-50-5', 5, 'Sundara Kanda, Sarga 50, Verse 5', 'राजन्धर्मविरुद्धं च लोकवृत्तेश्च गर्हितम्।
तव चासदृशं वीर कपेरस्य प्रमापणम्॥', 'rājan dharmaviruddhaṃ ca lokavṛtteś ca garhitam
tava cāsadṛśaṃ vīra kaper asya pramāpaṇam', null, 5050005),
('ramayana-5-50-6', 6, 'Sundara Kanda, Sarga 50, Verse 6', 'असंशयं शत्रुरयं प्रवृद्धः कृतं ह्यनेनाप्रियमप्रमेयम्।
न दूतवध्यां प्रवदन्ति सन्तो दूतस्य दृष्टा बहवो हि दण्डाः॥', 'asaṃśayaṃ śatrur ayaṃ pravṛddhaḥ kṛtaṃ hy anenāpriyam aprameyam
na dūtavadhyāṃ pravadanti santo dūtasya dṛṣṭā bahavo hi daṇḍāḥ', null, 5050006),
('ramayana-5-50-7', 7, 'Sundara Kanda, Sarga 50, Verse 7', 'वैरूप्यामङ्गेषु कशाभिघातो मौण्ड्यं तथा लक्ष्मणसंनिपातः।
एतान्हि दूते प्रवदन्ति दण्डान्वधस्तु दूतस्य न नः श्रुतोऽपि॥', 'vairūpyām aṅgeṣu kaśābhighāto mauṇḍyaṃ tathā lakṣmaṇasaṃnipātaḥ
etān hi dūte pravadanti daṇḍān vadhas tu dūtasya na naḥ śruto ''pi', null, 5050007),
('ramayana-5-50-8', 8, 'Sundara Kanda, Sarga 50, Verse 8', 'कथं च धर्मार्थविनीतबुद्धिः परावरप्रत्ययनिश्चितार्थः।
भवद्विधः कोपवशे हि तिष्ठेत्कोपं नियच्छन्ति हि सत्त्ववन्तः॥', 'kathaṃ ca dharmārthavinītabuddhiḥ parāvarapratyayaniścitārthaḥ
bhavadvidhaḥ kopavaśe hi tiṣṭhet kopaṃ niyacchanti hi sattvavantaḥ', null, 5050008),
('ramayana-5-50-9', 9, 'Sundara Kanda, Sarga 50, Verse 9', 'न धर्मवादे न च लोकवृत्ते न शास्त्रबुद्धिग्रहणेषु वापि।
विद्येत कश्चित्तव वीरतुल्यस्त्वं ह्युत्तमः सर्वसुरासुराणाम्॥', 'na dharmavāde na ca lokavṛtte na śāstrabuddhigrahaṇeṣu vāpi
vidyeta kaś cit tava vīratulyas tvaṃ hy uttamaḥ sarvasurāsurāṇām', null, 5050009),
('ramayana-5-50-10', 10, 'Sundara Kanda, Sarga 50, Verse 10', 'न चाप्यस्य कपेर्घाते कं चित्पश्याम्यहं गुणम्।
तेष्वयं पात्यतां दण्डो यैरयं प्रेषितः कपिः॥', 'na cāpy asya kaper ghāte kaṃ cit paśyāmy ahaṃ guṇam
teṣv ayaṃ pātyatāṃ daṇḍo yair ayaṃ preṣitaḥ kapiḥ', null, 5050010),
('ramayana-5-50-11', 11, 'Sundara Kanda, Sarga 50, Verse 11', 'साधुर्वा यदि वासाधुर्परैरेष समर्पितः।
ब्रुवन्परार्थं परवान्न दूतो वधमर्हति॥', 'sādhur vā yadi vāsādhur parair eṣa samarpitaḥ
bruvan parārthaṃ paravān na dūto vadham arhati', null, 5050011),
('ramayana-5-50-12', 12, 'Sundara Kanda, Sarga 50, Verse 12', 'अपि चास्मिन्हते राजन्नान्यं पश्यामि खेचरम्।
इह यः पुनरागच्छेत्परं पारं महोदधिः॥', 'api cāsmin hate rājan nānyaṃ paśyāmi khecaram
iha yaḥ punar āgacchet paraṃ pāraṃ mahodadhiḥ', null, 5050012),
('ramayana-5-50-13', 13, 'Sundara Kanda, Sarga 50, Verse 13', 'तस्मान्नास्य वधे यत्नः कार्यः परपुरंजय।
भवान्सेन्द्रेषु देवेषु यत्नमास्थातुमर्हति॥', 'tasmān nāsya vadhe yatnaḥ kāryaḥ parapuraṃjaya
bhavān sendreṣu deveṣu yatnam āsthātum arhati', null, 5050013),
('ramayana-5-50-14', 14, 'Sundara Kanda, Sarga 50, Verse 14', 'अस्मिन्विनष्टे न हि दूतमन्यं पश्यामि यस्तौ नरराजपुत्रौ।
युद्धाय युद्धप्रियदुर्विनीतावुद्योजयेद्दीर्घपथावरुद्धौ॥', 'asmin vinaṣṭe na hi dūtam anyaṃ paśyāmi yas tau nararājaputrau
yuddhāya yuddhapriyadurvinītāv udyojayed dīrghapathāvaruddhau', null, 5050014),
('ramayana-5-50-15', 15, 'Sundara Kanda, Sarga 50, Verse 15', 'पराक्रमोत्साहमनस्विनां च सुरासुराणामपि दुर्जयेन।
त्वया मनोनन्दन नैरृतानां युद्धायतिर्नाशयितुं न युक्ता॥', 'parākramotsāhamanasvināṃ ca surāsurāṇām api durjayena
tvayā manonandana nairṛtānāṃ yuddhāyatir nāśayituṃ na yuktā', null, 5050015),
('ramayana-5-50-16', 16, 'Sundara Kanda, Sarga 50, Verse 16', 'हिताश्च शूराश्च समाहिताश्च कुलेषु जाताश्च महागुणेषु।
मनस्विनः शस्त्रभृतां वरिष्ठाः कोट्यग्रशस्ते सुभृताश्च योधाः॥', 'hitāś ca śūrāś ca samāhitāś ca kuleṣu jātāś ca mahāguṇeṣu
manasvinaḥ śastrabhṛtāṃ variṣṭhāḥ koṭyagraśaste subhṛtāś ca yodhāḥ', null, 5050016),
('ramayana-5-50-17', 17, 'Sundara Kanda, Sarga 50, Verse 17', 'तदेकदेशेन बलस्य तावत्के चित्तवादेशकृतोऽपयान्तु।
तौ राजपुत्रौ विनिगृह्य मूढौ परेषु ते भावयितुं प्रभावम्॥', 'tad ekadeśena balasya tāvat ke cit tavādeśakṛto ''payāntu
tau rājaputrau vinigṛhya mūḍhau pareṣu te bhāvayituṃ prabhāvam', null, 5050017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 51 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-51-1', 1, 'Sundara Kanda, Sarga 51, Verse 1', 'तस्य तद्वचनं श्रुत्वा दशग्रीवो महाबलः।
देशकालहितं वाक्यं भ्रातुरुत्तममब्रवीत्॥', 'tasya tad vacanaṃ śrutvā daśagrīvo mahābalaḥ
deśakālahitaṃ vākyaṃ bhrātur uttamam abravīt', null, 5051001),
('ramayana-5-51-2', 2, 'Sundara Kanda, Sarga 51, Verse 2', 'सम्यगुक्तं हि भवता दूतवध्या विगर्हिता।
अवश्यं तु वधादन्यः क्रियतामस्य निग्रहः॥', 'samyag uktaṃ hi bhavatā dūtavadhyā vigarhitā
avaśyaṃ tu vadhād anyaḥ kriyatām asya nigrahaḥ', null, 5051002),
('ramayana-5-51-3', 3, 'Sundara Kanda, Sarga 51, Verse 3', 'कपीनां किल लाङ्गूलमिष्टं भवति भूषणम्।
तदस्य दीप्यतां शीघ्रं तेन दग्धेन गच्छतु॥', 'kapīnāṃ kila lāṅgūlam iṣṭaṃ bhavati bhūṣaṇam
tad asya dīpyatāṃ śīghraṃ tena dagdhena gacchatu', null, 5051003),
('ramayana-5-51-4', 4, 'Sundara Kanda, Sarga 51, Verse 4', 'ततः पश्यन्त्विमं दीनमङ्गवैरूप्यकर्शितम्।
समित्रा ज्ञातयः सर्वे बान्धवाः ससुहृज्जनाः॥', 'tataḥ paśyantv imaṃ dīnam aṅgavairūpyakarśitam
samitrā jñātayaḥ sarve bāndhavāḥ sasuhṛjjanāḥ', null, 5051004),
('ramayana-5-51-5', 5, 'Sundara Kanda, Sarga 51, Verse 5', 'आज्ञापयद्राक्षसेन्द्रः पुरं सर्वं सचत्वरम्।
लाङ्गूलेन प्रदीप्तेन रक्षोभिः परिणीयताम्॥', 'ājñāpayad rākṣasendraḥ puraṃ sarvaṃ sacatvaram
lāṅgūlena pradīptena rakṣobhiḥ pariṇīyatām', null, 5051005),
('ramayana-5-51-6', 6, 'Sundara Kanda, Sarga 51, Verse 6', 'तस्य तद्वचनं श्रुत्वा राक्षसाः कोपकर्कशाः।
वेष्टन्ते तस्य लाङ्गूलं जीर्णैः कार्पासिकैः पटैः॥', 'tasya tad vacanaṃ śrutvā rākṣasāḥ kopakarkaśāḥ
veṣṭante tasya lāṅgūlaṃ jīrṇaiḥ kārpāsikaiḥ paṭaiḥ', null, 5051006),
('ramayana-5-51-7', 7, 'Sundara Kanda, Sarga 51, Verse 7', 'संवेष्ट्यमाने लाङ्गूले व्यवर्धत महाकपिः।
शुष्कमिन्धनमासाद्य वनेष्विव हुताशनः॥', 'saṃveṣṭyamāne lāṅgūle vyavardhata mahākapiḥ
śuṣkam indhanam āsādya vaneṣv iva hutāśanaḥ', null, 5051007),
('ramayana-5-51-8', 8, 'Sundara Kanda, Sarga 51, Verse 8', 'तैलेन परिषिच्याथ तेऽग्निं तत्रावपातयन्॥', 'tailena pariṣicyātha te ''gniṃ tatrāvapātayan', null, 5051008),
('ramayana-5-51-9', 9, 'Sundara Kanda, Sarga 51, Verse 9', 'लाङ्गूलेन प्रदीप्तेन राक्षसांस्तानपातयत्।
रोषामर्षपरीतात्मा बालसूर्यसमाननः॥', 'lāṅgūlena pradīptena rākṣasāṃs tān apātayat
roṣāmarṣaparītātmā bālasūryasamānanaḥ', null, 5051009),
('ramayana-5-51-10', 10, 'Sundara Kanda, Sarga 51, Verse 10', 'स भूयः संगतैः क्रूरै राकसैर्हरिसत्तमः।
निबद्धः कृतवान्वीरस्तत्कालसदृशीं मतिम्॥', 'sa bhūyaḥ saṃgataiḥ krūrai rākasair harisattamaḥ
nibaddhaḥ kṛtavān vīras tatkālasadṛśīṃ matim', null, 5051010),
('ramayana-5-51-11', 11, 'Sundara Kanda, Sarga 51, Verse 11', 'कामं खलु न मे शक्ता निबधस्यापि राक्षसाः।
छित्त्वा पाशान्समुत्पत्य हन्यामहमिमान्पुनः॥', 'kāmaṃ khalu na me śaktā nibadhasyāpi rākṣasāḥ
chittvā pāśān samutpatya hanyām aham imān punaḥ', null, 5051011),
('ramayana-5-51-12', 12, 'Sundara Kanda, Sarga 51, Verse 12', 'सर्वेषामेव पर्याप्तो राक्षसानामहं युधि।
किं तु रामस्य प्रीत्यर्थं विषहिष्येऽहमीदृशम्॥', 'sarveṣām eva paryāpto rākṣasānām ahaṃ yudhi
kiṃ tu rāmasya prītyarthaṃ viṣahiṣye ''ham īdṛśam', null, 5051012),
('ramayana-5-51-13', 13, 'Sundara Kanda, Sarga 51, Verse 13', 'लङ्का चरयितव्या मे पुनरेव भवेदिति।
रात्रौ न हि सुदृष्टा मे दुर्गकर्मविधानतः।
अवश्यमेव द्रष्टव्या मया लङ्का निशाक्षये॥', 'laṅkā carayitavyā me punar eva bhaved iti
rātrau na hi sudṛṣṭā me durgakarmavidhānataḥ
avaśyam eva draṣṭavyā mayā laṅkā niśākṣaye', null, 5051013),
('ramayana-5-51-14', 14, 'Sundara Kanda, Sarga 51, Verse 14', 'कामं बन्धैश्च मे भूयः पुच्छस्योद्दीपनेन च।
पीडां कुर्वन्तु रक्षांसि न मेऽस्ति मनसः श्रमः॥', 'kāmaṃ bandhaiś ca me bhūyaḥ pucchasyoddīpanena ca
pīḍāṃ kurvantu rakṣāṃsi na me ''sti manasaḥ śramaḥ', null, 5051014),
('ramayana-5-51-15', 15, 'Sundara Kanda, Sarga 51, Verse 15', 'ततस्ते संवृताकारं सत्त्ववन्तं महाकपिम्।
परिगृह्य ययुर्हृष्टा राक्षसाः कपिकुञ्जरम्॥', 'tatas te saṃvṛtākāraṃ sattvavantaṃ mahākapim
parigṛhya yayur hṛṣṭā rākṣasāḥ kapikuñjaram', null, 5051015),
('ramayana-5-51-16', 16, 'Sundara Kanda, Sarga 51, Verse 16', 'शङ्खभेरीनिनादैस्तैर्घोषयन्तः स्वकर्मभिः।
राक्षसाः क्रूरकर्माणश्चारयन्ति स्म तां पुरीम्॥', 'śaṅkhabherīninādais tair ghoṣayantaḥ svakarmabhiḥ
rākṣasāḥ krūrakarmāṇaś cārayanti sma tāṃ purīm', null, 5051016),
('ramayana-5-51-17', 17, 'Sundara Kanda, Sarga 51, Verse 17', 'हनुमांश्चारयामास राक्षसानां महापुरीम्।
अथापश्यद्विमानानि विचित्राणि महाकपिः॥', 'hanumāṃś cārayām āsa rākṣasānāṃ mahāpurīm
athāpaśyad vimānāni vicitrāṇi mahākapiḥ', null, 5051017),
('ramayana-5-51-18', 18, 'Sundara Kanda, Sarga 51, Verse 18', 'संवृतान्भूमिभागांश्च सुविभक्तांश्च चत्वरान्।
रथ्याश्च गृहसंबाधाः कपिः शृङ्गाटकानि च॥', 'saṃvṛtān bhūmibhāgāṃś ca suvibhaktāṃś ca catvarān
rathyāś ca gṛhasaṃbādhāḥ kapiḥ śṛṅgāṭakāni ca', null, 5051018),
('ramayana-5-51-19', 19, 'Sundara Kanda, Sarga 51, Verse 19', 'चत्वरेषु चतुष्केषु राजमार्गे तथैव च।
घोषयन्ति कपिं सर्वे चारीक इति राक्षसाः॥', 'catvareṣu catuṣkeṣu rājamārge tathaiva ca
ghoṣayanti kapiṃ sarve cārīka iti rākṣasāḥ', null, 5051019),
('ramayana-5-51-20', 20, 'Sundara Kanda, Sarga 51, Verse 20', 'दीप्यमाने ततस्तस्य लाङ्गूलाग्रे हनूमतः।
राक्षस्यस्ता विरूपाक्ष्यः शंसुर्देव्यास्तदप्रियम्॥', 'dīpyamāne tatas tasya lāṅgūlāgre hanūmataḥ
rākṣasyas tā virūpākṣyaḥ śaṃsur devyās tad apriyam', null, 5051020),
('ramayana-5-51-21', 21, 'Sundara Kanda, Sarga 51, Verse 21', 'यस्त्वया कृतसंवादः सीते ताम्रमुखः कपिः।
लाङ्गूलेन प्रदीप्तेन स एष परिणीयते॥', 'yas tvayā kṛtasaṃvādaḥ sīte tāmramukhaḥ kapiḥ
lāṅgūlena pradīptena sa eṣa pariṇīyate', null, 5051021),
('ramayana-5-51-22', 22, 'Sundara Kanda, Sarga 51, Verse 22', 'श्रुत्वा तद्वचनं क्रूरमात्मापहरणोपमम्।
वैदेही शोकसंतप्ता हुताशनमुपागमत्॥', 'śrutvā tad vacanaṃ krūram ātmāpaharaṇopamam
vaidehī śokasaṃtaptā hutāśanam upāgamat', null, 5051022),
('ramayana-5-51-23', 23, 'Sundara Kanda, Sarga 51, Verse 23', 'मङ्गलाभिमुखी तस्य सा तदासीन्महाकपेः।
उपतस्थे विशालाक्षी प्रयता हव्यवाहनम्॥', 'maṅgalābhimukhī tasya sā tadāsīn mahākapeḥ
upatasthe viśālākṣī prayatā havyavāhanam', null, 5051023),
('ramayana-5-51-24', 24, 'Sundara Kanda, Sarga 51, Verse 24', 'यद्यस्ति पतिशुश्रूषा यद्यस्ति चरितं तपः।
यदि चास्त्येकपत्नीत्वं शीतो भव हनूमतः॥', 'yady asti patiśuśrūṣā yady asti caritaṃ tapaḥ
yadi cāsty ekapatnītvaṃ śīto bhava hanūmataḥ', null, 5051024),
('ramayana-5-51-25', 25, 'Sundara Kanda, Sarga 51, Verse 25', 'यदि कश्चिदनुक्रोशस्तस्य मय्यस्ति धीमतः।
यदि वा भाग्यशेषं मे शीतो भव हनूमतः॥', 'yadi kaś cid anukrośas tasya mayy asti dhīmataḥ
yadi vā bhāgyaśeṣaṃ me śīto bhava hanūmataḥ', null, 5051025),
('ramayana-5-51-26', 26, 'Sundara Kanda, Sarga 51, Verse 26', 'यदि मां वृत्तसंपन्नां तत्समागमलालसाम्।
स विजानाति धर्मात्मा शीतो भव हनूमतः॥', 'yadi māṃ vṛttasaṃpannāṃ tatsamāgamalālasām
sa vijānāti dharmātmā śīto bhava hanūmataḥ', null, 5051026),
('ramayana-5-51-27', 27, 'Sundara Kanda, Sarga 51, Verse 27', 'यदि मां तारयत्यार्यः सुग्रीवः सत्यसंगरः।
अस्माद्दुःखान्महाबाहुः शीतो भव हनूमतः॥', 'yadi māṃ tārayaty āryaḥ sugrīvaḥ satyasaṃgaraḥ
asmād duḥkhān mahābāhuḥ śīto bhava hanūmataḥ', null, 5051027),
('ramayana-5-51-28', 28, 'Sundara Kanda, Sarga 51, Verse 28', 'ततस्तीक्ष्णार्चिरव्यग्रः प्रदक्षिणशिखोऽनलः।
जज्वाल मृगशावाक्ष्याः शंसन्निव शिवं कपेः॥', 'tatas tīkṣṇārcir avyagraḥ pradakṣiṇaśikho ''nalaḥ
jajvāla mṛgaśāvākṣyāḥ śaṃsann iva śivaṃ kapeḥ', null, 5051028),
('ramayana-5-51-29', 29, 'Sundara Kanda, Sarga 51, Verse 29', 'दह्यमाने च लाङ्गूले चिन्तयामास वानरः।
प्रदीप्तोऽग्निरयं कस्मान्न मां दहति सर्वतः॥', 'dahyamāne ca lāṅgūle cintayām āsa vānaraḥ
pradīpto ''gnir ayaṃ kasmān na māṃ dahati sarvataḥ', null, 5051029),
('ramayana-5-51-30', 30, 'Sundara Kanda, Sarga 51, Verse 30', 'दृश्यते च महाज्वालः करोति च न मे रुजम्।
शिशिरस्येव संपातो लाङ्गूलाग्रे प्रतिष्ठितः॥', 'dṛśyate ca mahājvālaḥ karoti ca na me rujam
śiśirasyeva saṃpāto lāṅgūlāgre pratiṣṭhitaḥ', null, 5051030),
('ramayana-5-51-31', 31, 'Sundara Kanda, Sarga 51, Verse 31', 'अथ वा तदिदं व्यक्तं यद्दृष्टं प्लवता मया।
रामप्रभावादाश्चर्यं पर्वतः सरितां पतौ॥', 'atha vā tad idaṃ vyaktaṃ yad dṛṣṭaṃ plavatā mayā
rāmaprabhāvād āścaryaṃ parvataḥ saritāṃ patau', null, 5051031),
('ramayana-5-51-32', 32, 'Sundara Kanda, Sarga 51, Verse 32', 'यदि तावत्समुद्रस्य मैनाकस्य च धीमथ।
रामार्थं संभ्रमस्तादृक्किमग्निर्न करिष्यति॥', 'yadi tāvat samudrasya mainākasya ca dhīmatha
rāmārthaṃ saṃbhramas tādṛk kim agnir na kariṣyati', null, 5051032),
('ramayana-5-51-33', 33, 'Sundara Kanda, Sarga 51, Verse 33', 'सीतायाश्चानृशंस्येन तेजसा राघवस्य च।
पितुश्च मम सख्येन न मां दहति पावकः॥', 'sītāyāś cānṛśaṃsyena tejasā rāghavasya ca
pituś ca mama sakhyena na māṃ dahati pāvakaḥ', null, 5051033),
('ramayana-5-51-34', 34, 'Sundara Kanda, Sarga 51, Verse 34', 'भूयः स चिन्तयामास मुहूर्तं कपिकुञ्जरः।
उत्पपाताथ वेगेन ननाद च महाकपिः॥', 'bhūyaḥ sa cintayām āsa muhūrtaṃ kapikuñjaraḥ
utpapātātha vegena nanāda ca mahākapiḥ', null, 5051034),
('ramayana-5-51-35', 35, 'Sundara Kanda, Sarga 51, Verse 35', 'पुरद्वारं ततः श्रीमाञ्शैलशृङ्गमिवोन्नतम्।
विभक्तरक्षःसंबाधमाससादानिलात्मजः॥', 'puradvāraṃ tataḥ śrīmāñ śailaśṛṅgam ivonnatam
vibhaktarakṣaḥsaṃbādham āsasādānilātmajaḥ', null, 5051035),
('ramayana-5-51-36', 36, 'Sundara Kanda, Sarga 51, Verse 36', 'स भूत्वा शैलसंकाशः क्षणेन पुनरात्मवान्।
ह्रस्वतां परमां प्राप्तो बन्धनान्यवशातयत्॥', 'sa bhūtvā śailasaṃkāśaḥ kṣaṇena punar ātmavān
hrasvatāṃ paramāṃ prāpto bandhanāny avaśātayat', null, 5051036),
('ramayana-5-51-37', 37, 'Sundara Kanda, Sarga 51, Verse 37', 'विमुक्तश्चाभवच्छ्रीमान्पुनः पर्वतसंनिभः।
वीक्षमाणश्च ददृशे परिघं तोरणाश्रितम्॥', 'vimuktaś cābhavac chrīmān punaḥ parvatasaṃnibhaḥ
vīkṣamāṇaś ca dadṛśe parighaṃ toraṇāśritam', null, 5051037),
('ramayana-5-51-38', 38, 'Sundara Kanda, Sarga 51, Verse 38', 'स तं गृह्य महाबाहुः कालायसपरिष्कृतम्।
रक्षिणस्तान्पुनः सर्वान्सूदयामास मारुतिः॥', 'sa taṃ gṛhya mahābāhuḥ kālāyasapariṣkṛtam
rakṣiṇas tān punaḥ sarvān sūdayām āsa mārutiḥ', null, 5051038),
('ramayana-5-51-39', 39, 'Sundara Kanda, Sarga 51, Verse 39', 'स तान्निहत्वा रणचण्डविक्रमः समीक्षमाणः पुनरेव लङ्काम्।
प्रदीप्तलाङ्गूलकृतार्चिमाली प्रकाशतादित्य इवांशुमाली॥', 'sa tān nihatvā raṇacaṇḍavikramaḥ samīkṣamāṇaḥ punar eva laṅkām
pradīptalāṅgūlakṛtārcimālī prakāśatāditya ivāṃśumālī', null, 5051039)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 52 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-52-1', 1, 'Sundara Kanda, Sarga 52, Verse 1', 'वीक्षमाणस्ततो लङ्कां कपिः कृतमनोरथः।
वर्धमानसमुत्साहः कार्यशेषमचिन्तयत्॥', 'vīkṣamāṇas tato laṅkāṃ kapiḥ kṛtamanorathaḥ
vardhamānasamutsāhaḥ kāryaśeṣam acintayat', null, 5052001),
('ramayana-5-52-2', 2, 'Sundara Kanda, Sarga 52, Verse 2', 'किं नु खल्वविशिष्टं मे कर्तव्यमिह साम्प्रतम्।
यदेषां रक्षसां भूयः संतापजननं भवेत्॥', 'kiṃ nu khalv aviśiṣṭaṃ me kartavyam iha sāmpratam
yad eṣāṃ rakṣasāṃ bhūyaḥ saṃtāpajananaṃ bhavet', null, 5052002),
('ramayana-5-52-3', 3, 'Sundara Kanda, Sarga 52, Verse 3', 'वनं तावत्प्रमथितं प्रकृष्टा राक्षसा हताः।
बलैकदेशः क्षपितः शेषं दुर्गविनाशनम्॥', 'vanaṃ tāvat pramathitaṃ prakṛṣṭā rākṣasā hatāḥ
balaikadeśaḥ kṣapitaḥ śeṣaṃ durgavināśanam', null, 5052003),
('ramayana-5-52-4', 4, 'Sundara Kanda, Sarga 52, Verse 4', 'दुर्गे विनाशिते कर्म भवेत्सुखपरिश्रमम्।
अल्पयत्नेन कार्येऽस्मिन्मम स्यात्सफलः श्रमः॥', 'durge vināśite karma bhavet sukhapariśramam
alpayatnena kārye ''smin mama syāt saphalaḥ śramaḥ', null, 5052004),
('ramayana-5-52-5', 5, 'Sundara Kanda, Sarga 52, Verse 5', 'यो ह्ययं मम लाङ्गूले दीप्यते हव्यवाहनः।
अस्य संतर्पणं न्याय्यं कर्तुमेभिर्गृहोत्तमैः॥', 'yo hy ayaṃ mama lāṅgūle dīpyate havyavāhanaḥ
asya saṃtarpaṇaṃ nyāyyaṃ kartum ebhir gṛhottamaiḥ', null, 5052005),
('ramayana-5-52-6', 6, 'Sundara Kanda, Sarga 52, Verse 6', 'ततः प्रदीप्तलाङ्गूलः सविद्युदिव तोयदः।
भवनाग्रेषु लङ्काया विचचार महाकपिः॥', 'tataḥ pradīptalāṅgūlaḥ savidyud iva toyadaḥ
bhavanāgreṣu laṅkāyā vicacāra mahākapiḥ', null, 5052006),
('ramayana-5-52-7', 7, 'Sundara Kanda, Sarga 52, Verse 7', 'मुमोच हनुमानग्निं कालानलशिखोपमम्॥', 'mumoca hanumān agniṃ kālānalaśikhopamam', null, 5052007),
('ramayana-5-52-8', 8, 'Sundara Kanda, Sarga 52, Verse 8', 'श्वसनेन च संयोगादतिवेगो महाबलः।
कालाग्निरिव जज्वाल प्रावर्धत हुताशनः॥', 'śvasanena ca saṃyogād ativego mahābalaḥ
kālāgnir iva jajvāla prāvardhata hutāśanaḥ', null, 5052008),
('ramayana-5-52-9', 9, 'Sundara Kanda, Sarga 52, Verse 9', 'प्रदीप्तमग्निं पवनस्तेषु वेश्मसु चारयत्॥', 'pradīptam agniṃ pavanas teṣu veśmasu cārayat', null, 5052009),
('ramayana-5-52-10', 10, 'Sundara Kanda, Sarga 52, Verse 10', 'तानि काञ्चनजालानि मुक्तामणिमयानि च।
भवनान्यवशीर्यन्त रत्नवन्ति महान्ति च॥', 'tāni kāñcanajālāni muktāmaṇimayāni ca
bhavanāny avaśīryanta ratnavanti mahānti ca', null, 5052010),
('ramayana-5-52-11', 11, 'Sundara Kanda, Sarga 52, Verse 11', 'तानि भग्नविमानानि निपेतुर्वसुधातले।
भवनानीव सिद्धानामम्बरात्पुण्यसंक्षये॥', 'tāni bhagnavimānāni nipetur vasudhātale
bhavanānīva siddhānām ambarāt puṇyasaṃkṣaye', null, 5052011),
('ramayana-5-52-12', 12, 'Sundara Kanda, Sarga 52, Verse 12', 'वज्रविद्रुमवैदूर्यमुक्तारजतसंहितान्।
विचित्रान्भवनाद्धातून्स्यन्दमानान्ददर्श सः॥', 'vajravidrumavaidūryamuktārajatasaṃhitān
vicitrān bhavanād dhātūn syandamānān dadarśa saḥ', null, 5052012),
('ramayana-5-52-13', 13, 'Sundara Kanda, Sarga 52, Verse 13', 'नाग्निस्तृप्यति काष्ठानां तृणानां च यथा तथा।
हनूमान्राक्षसेन्द्राणां वधे किं चिन्न तृप्यति॥', 'nāgnis tṛpyati kāṣṭhānāṃ tṛṇānāṃ ca yathā tathā
hanūmān rākṣasendrāṇāṃ vadhe kiṃ cin na tṛpyati', null, 5052013),
('ramayana-5-52-14', 14, 'Sundara Kanda, Sarga 52, Verse 14', 'हुताशनज्वालसमावृता सा हतप्रवीरा परिवृत्तयोधा।
हनूमातः क्रोधबलाभिभूता बभूव शापोपहतेव लङ्का॥', 'hutāśanajvālasamāvṛtā sā hatapravīrā parivṛttayodhā
hanūmātaḥ krodhabalābhibhūtā babhūva śāpopahateva laṅkā', null, 5052014),
('ramayana-5-52-15', 15, 'Sundara Kanda, Sarga 52, Verse 15', 'ससंभ्रमं त्रस्तविषण्णराक्षसां समुज्ज्वलज्ज्वालहुताशनाङ्किताम्।
ददर्श लङ्कां हनुमान्महामनाः स्वयम्भुकोपोपहतामिवावनिम्॥', 'sasaṃbhramaṃ trastaviṣaṇṇarākṣasāṃ samujjvalaj jvālahutāśanāṅkitām
dadarśa laṅkāṃ hanumān mahāmanāḥ svayambhukopopahatām ivāvanim', null, 5052015),
('ramayana-5-52-16', 16, 'Sundara Kanda, Sarga 52, Verse 16', 'स राक्षसांस्तान्सुबहूंश्च हत्वा वनं च भङ्क्त्वा बहुपादपं तत्।
विसृज्य रक्षो भवनेषु चाग्निं जगाम रामं मनसा महात्मा॥', 'sa rākṣasāṃs tān subahūṃś ca hatvā vanaṃ ca bhaṅktvā bahupādapaṃ tat
visṛjya rakṣo bhavaneṣu cāgniṃ jagāma rāmaṃ manasā mahātmā', null, 5052016),
('ramayana-5-52-17', 17, 'Sundara Kanda, Sarga 52, Verse 17', 'लङ्कां समस्तां संदीप्य लाङ्गूलाग्निं महाकपिः।
निर्वापयामास तदा समुद्रे हरिसत्तमः॥', 'laṅkāṃ samastāṃ saṃdīpya lāṅgūlāgniṃ mahākapiḥ
nirvāpayām āsa tadā samudre harisattamaḥ', null, 5052017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 53 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-53-1', 1, 'Sundara Kanda, Sarga 53, Verse 1', 'संदीप्यमानां विध्वस्तां त्रस्तरक्षो गणां पुरीम्।
अवेक्ष्य हानुमांल्लङ्कां चिन्तयामास वानरः॥', 'saṃdīpyamānāṃ vidhvastāṃ trastarakṣo gaṇāṃ purīm
avekṣya hānumāṃl laṅkāṃ cintayām āsa vānaraḥ', null, 5053001),
('ramayana-5-53-2', 2, 'Sundara Kanda, Sarga 53, Verse 2', 'तस्याभूत्सुमहांस्त्रासः कुत्सा चात्मन्यजायत।
लङ्कां प्रदहता कर्म किंस्वित्कृतमिदं मया॥', 'tasyābhūt sumahāṃs trāsaḥ kutsā cātmany ajāyata
laṅkāṃ pradahatā karma kiṃsvit kṛtam idaṃ mayā', null, 5053002),
('ramayana-5-53-3', 3, 'Sundara Kanda, Sarga 53, Verse 3', 'धन्यास्ते पुरुषश्रेष्ठ ये बुद्ध्या कोपमुत्थितम्।
निरुन्धन्ति महात्मानो दीप्तमग्निमिवाम्भसा॥', 'dhanyās te puruṣaśreṣṭha ye buddhyā kopam utthitam
nirundhanti mahātmāno dīptam agnim ivāmbhasā', null, 5053003),
('ramayana-5-53-4', 4, 'Sundara Kanda, Sarga 53, Verse 4', 'यदि दग्धा त्वियं लङ्का नूनमार्यापि जानकी।
दग्धा तेन मया भर्तुर्हतं कार्यमजानता॥', 'yadi dagdhā tv iyaṃ laṅkā nūnam āryāpi jānakī
dagdhā tena mayā bhartur hataṃ kāryam ajānatā', null, 5053004),
('ramayana-5-53-5', 5, 'Sundara Kanda, Sarga 53, Verse 5', 'यदर्थमयमारम्भस्तत्कार्यमवसादितम्।
मया हि दहता लङ्कां न सीता परिरक्षिता॥', 'yad artham ayam ārambhas tat kāryam avasāditam
mayā hi dahatā laṅkāṃ na sītā parirakṣitā', null, 5053005),
('ramayana-5-53-6', 6, 'Sundara Kanda, Sarga 53, Verse 6', 'ईषत्कार्यमिदं कार्यं कृतमासीन्न संशयः।
तस्य क्रोधाभिभूतेन मया मूलक्षयः कृतः॥', 'īṣatkāryam idaṃ kāryaṃ kṛtam āsīn na saṃśayaḥ
tasya krodhābhibhūtena mayā mūlakṣayaḥ kṛtaḥ', null, 5053006),
('ramayana-5-53-7', 7, 'Sundara Kanda, Sarga 53, Verse 7', 'विनष्टा जानकी व्यक्तं न ह्यदग्धः प्रदृश्यते।
लङ्कायाः कश्चिदुद्देशः सर्वा भस्मीकृता पुरी॥', 'vinaṣṭā jānakī vyaktaṃ na hy adagdhaḥ pradṛśyate
laṅkāyāḥ kaś cid uddeśaḥ sarvā bhasmīkṛtā purī', null, 5053007),
('ramayana-5-53-8', 8, 'Sundara Kanda, Sarga 53, Verse 8', 'यदि तद्विहतं कार्यं मया प्रज्ञाविपर्ययात्।
इहैव प्राणसंन्यासो ममापि ह्यतिरोचते॥', 'yadi tad vihataṃ kāryaṃ mayā prajñāviparyayāt
ihaiva prāṇasaṃnyāso mamāpi hy atirocate', null, 5053008),
('ramayana-5-53-9', 9, 'Sundara Kanda, Sarga 53, Verse 9', 'किमग्नौ निपताम्यद्य आहोस्विद्वडवामुखे।
शरीरमाहो सत्त्वानां दद्मि सागरवासिनाम्॥', 'kim agnau nipatāmy adya āhosvid vaḍavāmukhe
śarīram āho sattvānāṃ dadmi sāgaravāsinām', null, 5053009),
('ramayana-5-53-10', 10, 'Sundara Kanda, Sarga 53, Verse 10', 'कथं हि जीवता शक्यो मया द्रष्टुं हरीश्वरः।
तौ वा पुरुषशार्दूलौ कार्यसर्वस्वघातिना॥', 'kathaṃ hi jīvatā śakyo mayā draṣṭuṃ harīśvaraḥ
tau vā puruṣaśārdūlau kāryasarvasvaghātinā', null, 5053010),
('ramayana-5-53-11', 11, 'Sundara Kanda, Sarga 53, Verse 11', 'मया खलु तदेवेदं रोषदोषात्प्रदर्शितम्।
प्रथितं त्रिषु लोकेषु कपितमनवस्थितम्॥', 'mayā khalu tad evedaṃ roṣadoṣāt pradarśitam
prathitaṃ triṣu lokeṣu kapitam anavasthitam', null, 5053011),
('ramayana-5-53-12', 12, 'Sundara Kanda, Sarga 53, Verse 12', 'धिगस्तु राजसं भावमनीशमनवस्थितम्।
ईश्वरेणापि यद्रागान्मया सीता न रक्षिता॥', 'dhig astu rājasaṃ bhāvam anīśam anavasthitam
īśvareṇāpi yad rāgān mayā sītā na rakṣitā', null, 5053012),
('ramayana-5-53-13', 13, 'Sundara Kanda, Sarga 53, Verse 13', 'विनष्टायां तु सीतायां तावुभौ विनशिष्यतः।
तयोर्विनाशे सुग्रीवः सबन्धुर्विनशिष्यति॥', 'vinaṣṭāyāṃ tu sītāyāṃ tāv ubhau vinaśiṣyataḥ
tayor vināśe sugrīvaḥ sabandhur vinaśiṣyati', null, 5053013),
('ramayana-5-53-14', 14, 'Sundara Kanda, Sarga 53, Verse 14', 'एतदेव वचः श्रुत्वा भरतो भ्रातृवत्सलः।
धर्मात्मा सहशत्रुघ्नः कथं शक्ष्यति जीवितुम्॥', 'etad eva vacaḥ śrutvā bharato bhrātṛvatsalaḥ
dharmātmā sahaśatrughnaḥ kathaṃ śakṣyati jīvitum', null, 5053014),
('ramayana-5-53-15', 15, 'Sundara Kanda, Sarga 53, Verse 15', 'इक्ष्वाकुवंशे धर्मिष्ठे गते नाशमसंशयम्।
भविष्यन्ति प्रजाः सर्वाः शोकसंतापपीडिताः॥', 'ikṣvākuvaṃśe dharmiṣṭhe gate nāśam asaṃśayam
bhaviṣyanti prajāḥ sarvāḥ śokasaṃtāpapīḍitāḥ', null, 5053015),
('ramayana-5-53-16', 16, 'Sundara Kanda, Sarga 53, Verse 16', 'तदहं भाग्यरहितो लुप्तधर्मार्थसंग्रहः।
रोषदोषपरीतात्मा व्यक्तं लोकविनाशनः॥', 'tad ahaṃ bhāgyarahito luptadharmārthasaṃgrahaḥ
roṣadoṣaparītātmā vyaktaṃ lokavināśanaḥ', null, 5053016),
('ramayana-5-53-17', 17, 'Sundara Kanda, Sarga 53, Verse 17', 'इति चिन्तयतस्तस्य निमित्तान्युपपेदिरे।
पूरमप्युपलब्धानि साक्षात्पुनरचिन्तयत्॥', 'iti cintayatas tasya nimittāny upapedire
pūram apy upalabdhāni sākṣāt punar acintayat', null, 5053017),
('ramayana-5-53-18', 18, 'Sundara Kanda, Sarga 53, Verse 18', 'अथ वा चारुसर्वाङ्गी रक्षिता स्वेन तेजसा।
न नशिष्यति कल्याणी नाग्निरग्नौ प्रवर्तते॥', 'atha vā cārusarvāṅgī rakṣitā svena tejasā
na naśiṣyati kalyāṇī nāgnir agnau pravartate', null, 5053018),
('ramayana-5-53-19', 19, 'Sundara Kanda, Sarga 53, Verse 19', 'न हि धर्मान्मनस्तस्य भार्याममिततेजसः।
स्वचारित्राभिगुप्तां तां स्प्रष्टुमर्हति पावकः॥', 'na hi dharmān manas tasya bhāryām amitatejasaḥ
svacāritrābhiguptāṃ tāṃ spraṣṭum arhati pāvakaḥ', null, 5053019),
('ramayana-5-53-20', 20, 'Sundara Kanda, Sarga 53, Verse 20', 'नूनं रामप्रभावेन वैदेह्याः सुकृतेन च।
यन्मां दहनकर्मायं नादहद्धव्यवाहनः॥', 'nūnaṃ rāmaprabhāvena vaidehyāḥ sukṛtena ca
yan māṃ dahanakarmāyaṃ nādahad dhavyavāhanaḥ', null, 5053020),
('ramayana-5-53-21', 21, 'Sundara Kanda, Sarga 53, Verse 21', 'त्रयाणां भरतादीनां भ्रातॄणां देवता च या।
रामस्य च मनःकान्ता सा कथं विनशिष्यति॥', 'trayāṇāṃ bharatādīnāṃ bhrātṝṇāṃ devatā ca yā
rāmasya ca manaḥkāntā sā kathaṃ vinaśiṣyati', null, 5053021),
('ramayana-5-53-22', 22, 'Sundara Kanda, Sarga 53, Verse 22', 'यद्वा दहनकर्मायं सर्वत्र प्रभुरव्ययः।
न मे दहति लाङ्गूलं कथमार्यां प्रधक्ष्यति॥', 'yad vā dahanakarmāyaṃ sarvatra prabhur avyayaḥ
na me dahati lāṅgūlaṃ katham āryāṃ pradhakṣyati', null, 5053022),
('ramayana-5-53-23', 23, 'Sundara Kanda, Sarga 53, Verse 23', 'तपसा सत्यवाक्येन अनन्यत्वाच्च भर्तरि।
अपि सा निर्दहेदग्निं न तामग्निः प्रधक्ष्यति॥', 'tapasā satyavākyena ananyatvāc ca bhartari
api sā nirdahed agniṃ na tām agniḥ pradhakṣyati', null, 5053023),
('ramayana-5-53-24', 24, 'Sundara Kanda, Sarga 53, Verse 24', 'स तथा चिन्तयंस्तत्र देव्या धर्मपरिग्रहम्।
शुश्राव हनुमान्वाक्यं चारणानां महात्मनाम्॥', 'sa tathā cintayaṃs tatra devyā dharmaparigraham
śuśrāva hanumān vākyaṃ cāraṇānāṃ mahātmanām', null, 5053024),
('ramayana-5-53-25', 25, 'Sundara Kanda, Sarga 53, Verse 25', 'अहो खलु कृतं कर्म दुर्विषह्यं हनूमता।
अग्निं विसृजताभीक्ष्णं भीमं राक्षससद्मनि॥', 'aho khalu kṛtaṃ karma durviṣahyaṃ hanūmatā
agniṃ visṛjatābhīkṣṇaṃ bhīmaṃ rākṣasasadmani', null, 5053025),
('ramayana-5-53-26', 26, 'Sundara Kanda, Sarga 53, Verse 26', 'दग्धेयं नगरी लङ्का साट्टप्राकारतोरणा।
जानकी न च दग्धेति विस्मयोऽद्भुत एव नः॥', 'dagdheyaṃ nagarī laṅkā sāṭṭaprākāratoraṇā
jānakī na ca dagdheti vismayo ''dbhuta eva naḥ', null, 5053026),
('ramayana-5-53-27', 27, 'Sundara Kanda, Sarga 53, Verse 27', 'स निमित्तैश्च दृष्टार्थैः कारणैश्च महागुणैः।
ऋषिवाक्यैश्च हनुमानभवत्प्रीतमानसः॥', 'sa nimittaiś ca dṛṣṭārthaiḥ kāraṇaiś ca mahāguṇaiḥ
ṛṣivākyaiś ca hanumān abhavat prītamānasaḥ', null, 5053027),
('ramayana-5-53-28', 28, 'Sundara Kanda, Sarga 53, Verse 28', 'ततः कपिः प्राप्तमनोरथार्थस्तामक्षतां राजसुतां विदित्वा।
प्रत्यक्षतस्तां पुनरेव दृष्ट्वा प्रतिप्रयाणाय मतिं चकार॥', 'tataḥ kapiḥ prāptamanorathārthas tām akṣatāṃ rājasutāṃ viditvā
pratyakṣatas tāṃ punar eva dṛṣṭvā pratiprayāṇāya matiṃ cakāra', null, 5053028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 54 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-54-1', 1, 'Sundara Kanda, Sarga 54, Verse 1', 'ततस्तु शिंशपामूले जानकीं पर्यवस्थिताम्।
अभिवाद्याब्रवीद्दिष्ट्या पश्यामि त्वामिहाक्षताम्॥', 'tatas tu śiṃśapāmūle jānakīṃ paryavasthitām
abhivādyābravīd diṣṭyā paśyāmi tvām ihākṣatām', null, 5054001),
('ramayana-5-54-2', 2, 'Sundara Kanda, Sarga 54, Verse 2', 'ततस्तं प्रस्थितं सीता वीक्षमाणा पुनः पुनः।
भर्तृस्नेहान्वितं वाक्यं हनूमन्तमभाषत॥', 'tatas taṃ prasthitaṃ sītā vīkṣamāṇā punaḥ punaḥ
bhartṛsnehānvitaṃ vākyaṃ hanūmantam abhāṣata', null, 5054002),
('ramayana-5-54-3', 3, 'Sundara Kanda, Sarga 54, Verse 3', 'काममस्य त्वमेवैकः कार्यस्य परिसाधने।
पर्याप्तः परवीरघ्न यशस्यस्ते बलोदयः॥', 'kāmam asya tvam evaikaḥ kāryasya parisādhane
paryāptaḥ paravīraghna yaśasyas te balodayaḥ', null, 5054003),
('ramayana-5-54-4', 4, 'Sundara Kanda, Sarga 54, Verse 4', 'बलैस्तु संकुलां कृत्वा लङ्कां परबलार्दनः।
मां नयेद्यदि काकुत्स्थस्तस्य तत्सादृशं भवेत्॥', 'balais tu saṃkulāṃ kṛtvā laṅkāṃ parabalārdanaḥ
māṃ nayed yadi kākutsthas tasya tat sādṛśaṃ bhavet', null, 5054004),
('ramayana-5-54-5', 5, 'Sundara Kanda, Sarga 54, Verse 5', 'तद्यथा तस्य विक्रान्तमनुरूपं महात्मनः।
भवत्याहवशूरस्य तत्त्वमेवोपपादय॥', 'tad yathā tasya vikrāntam anurūpaṃ mahātmanaḥ
bhavaty āhavaśūrasya tattvam evopapādaya', null, 5054005),
('ramayana-5-54-6', 6, 'Sundara Kanda, Sarga 54, Verse 6', 'तदर्थोपहितं वाक्यं प्रश्रितं हेतुसंहितम्।
निशम्य हनुमांस्तस्या वाक्यमुत्तरमब्रवीत्॥', 'tad arthopahitaṃ vākyaṃ praśritaṃ hetusaṃhitam
niśamya hanumāṃs tasyā vākyam uttaram abravīt', null, 5054006),
('ramayana-5-54-7', 7, 'Sundara Kanda, Sarga 54, Verse 7', 'क्षिप्रमेष्यति काकुत्स्थो हर्यृक्षप्रवरैर्वृतः।
यस्ते युधि विजित्यारीञ्शोकं व्यपनयिष्यति॥', 'kṣipram eṣyati kākutstho haryṛkṣapravarair vṛtaḥ
yas te yudhi vijityārīñ śokaṃ vyapanayiṣyati', null, 5054007),
('ramayana-5-54-8', 8, 'Sundara Kanda, Sarga 54, Verse 8', 'एवमाश्वास्य वैदेहीं हनूमान्मारुतात्मजः।
गमनाय मतिं कृत्वा वैदेहीमभ्यवादयत्॥', 'evam āśvāsya vaidehīṃ hanūmān mārutātmajaḥ
gamanāya matiṃ kṛtvā vaidehīm abhyavādayat', null, 5054008),
('ramayana-5-54-9', 9, 'Sundara Kanda, Sarga 54, Verse 9', 'ततः स कपिशार्दूलः स्वामिसंदर्शनोत्सुकः।
आरुरोह गिरिश्रेष्ठमरिष्टमरिमर्दनः॥', 'tataḥ sa kapiśārdūlaḥ svāmisaṃdarśanotsukaḥ
āruroha giriśreṣṭham ariṣṭam arimardanaḥ', null, 5054009),
('ramayana-5-54-10', 10, 'Sundara Kanda, Sarga 54, Verse 10', 'तुङ्गपद्मकजुष्टाभिर्नीलाभिर्वनराजिभिः।
सालतालाश्वकर्णैश्च वंशैश्च बहुभिर्वृतम्॥', 'tuṅgapadmakajuṣṭābhir nīlābhir vanarājibhiḥ
sālatālāśvakarṇaiś ca vaṃśaiś ca bahubhir vṛtam', null, 5054010),
('ramayana-5-54-11', 11, 'Sundara Kanda, Sarga 54, Verse 11', 'लतावितानैर्विततैः पुष्पवद्भिरलंकृतम्।
नानामृगगणाकीर्णं धातुनिष्यन्दभूषितम्॥', 'latāvitānair vitataiḥ puṣpavadbhir alaṃkṛtam
nānāmṛgagaṇākīrṇaṃ dhātuniṣyandabhūṣitam', null, 5054011),
('ramayana-5-54-12', 12, 'Sundara Kanda, Sarga 54, Verse 12', 'बहुप्रस्रवणोपेतं शिलासंचयसंकटम्।
महर्षियक्षगन्धर्वकिंनरोरगसेवितम्॥', 'bahuprasravaṇopetaṃ śilāsaṃcayasaṃkaṭam
maharṣiyakṣagandharvakiṃnaroragasevitam', null, 5054012),
('ramayana-5-54-13', 13, 'Sundara Kanda, Sarga 54, Verse 13', 'लतापादपसंबाधं सिंहाकुलितकन्दरम्।
व्याघ्रसंघसमाकीर्णं स्वादुमूलफलद्रुमम्॥', 'latāpādapasaṃbādhaṃ siṃhākulitakandaram
vyāghrasaṃghasamākīrṇaṃ svādumūlaphaladrumam', null, 5054013),
('ramayana-5-54-14', 14, 'Sundara Kanda, Sarga 54, Verse 14', 'तमारुरोहातिबलः पर्वतं प्लवगोत्तमः।
रामदर्शनशीघ्रेण प्रहर्षेणाभिचोदितः॥', 'tam ārurohātibalaḥ parvataṃ plavagottamaḥ
rāmadarśanaśīghreṇa praharṣeṇābhicoditaḥ', null, 5054014),
('ramayana-5-54-15', 15, 'Sundara Kanda, Sarga 54, Verse 15', 'तेन पादतलाक्रान्ता रम्येषु गिरिसानुषु।
सघोषाः समशीर्यन्त शिलाश्चूर्णीकृतास्ततः॥', 'tena pādatalākrāntā ramyeṣu girisānuṣu
saghoṣāḥ samaśīryanta śilāś cūrṇīkṛtās tataḥ', null, 5054015),
('ramayana-5-54-16', 16, 'Sundara Kanda, Sarga 54, Verse 16', 'स तमारुह्य शैलेन्द्रं व्यवर्धत महाकपिः।
दक्षिणादुत्तरं पारं प्रार्थयंल्लवणाम्भसः॥', 'sa tam āruhya śailendraṃ vyavardhata mahākapiḥ
dakṣiṇād uttaraṃ pāraṃ prārthayaṃl lavaṇāmbhasaḥ', null, 5054016),
('ramayana-5-54-17', 17, 'Sundara Kanda, Sarga 54, Verse 17', 'अधिरुह्य ततो वीरः पर्वतं पवनात्मजः।
ददर्श सागरं भीमं मीनोरगनिषेवितम्॥', 'adhiruhya tato vīraḥ parvataṃ pavanātmajaḥ
dadarśa sāgaraṃ bhīmaṃ mīnoraganiṣevitam', null, 5054017),
('ramayana-5-54-18', 18, 'Sundara Kanda, Sarga 54, Verse 18', 'स मारुत इवाकाशं मारुतस्यात्मसंभवः।
प्रपेदे हरिशार्दूलो दक्षिणादुत्तरां दिशम्॥', 'sa māruta ivākāśaṃ mārutasyātmasaṃbhavaḥ
prapede hariśārdūlo dakṣiṇād uttarāṃ diśam', null, 5054018),
('ramayana-5-54-19', 19, 'Sundara Kanda, Sarga 54, Verse 19', 'स तदा पीडितस्तेन कपिना पर्वतोत्तमः।
ररास सह तैर्भूतैः प्राविशद्वसुधातलम्।
कम्पमानैश्च शिखरैः पतद्भिरपि च द्रुमैः॥', 'sa tadā pīḍitas tena kapinā parvatottamaḥ
rarāsa saha tair bhūtaiḥ prāviśad vasudhātalam
kampamānaiś ca śikharaiḥ patadbhir api ca drumaiḥ', null, 5054019),
('ramayana-5-54-20', 20, 'Sundara Kanda, Sarga 54, Verse 20', 'तस्योरुवेगान्मथिताः पादपाः पुष्पशालिनः।
निपेतुर्भूतले रुग्णाः शक्रायुधहता इव॥', 'tasyoruvegān mathitāḥ pādapāḥ puṣpaśālinaḥ
nipetur bhūtale rugṇāḥ śakrāyudhahatā iva', null, 5054020),
('ramayana-5-54-21', 21, 'Sundara Kanda, Sarga 54, Verse 21', 'कन्दरोदरसंस्थानां पीडितानां महौजसाम्।
सिंहानां निनदो भीमो नभो भिन्दन्स शुश्रुवे॥', 'kandarodarasaṃsthānāṃ pīḍitānāṃ mahaujasām
siṃhānāṃ ninado bhīmo nabho bhindan sa śuśruve', null, 5054021),
('ramayana-5-54-22', 22, 'Sundara Kanda, Sarga 54, Verse 22', 'स्रस्तव्याविद्धवसना व्याकुलीकृतभूषणा।
विद्याधर्यः समुत्पेतुः सहसा धरणीधरात्॥', 'srastavyāviddhavasanā vyākulīkṛtabhūṣaṇā
vidyādharyaḥ samutpetuḥ sahasā dharaṇīdharāt', null, 5054022),
('ramayana-5-54-23', 23, 'Sundara Kanda, Sarga 54, Verse 23', 'अतिप्रमाणा बलिनो दीप्तजिह्वा महाविषाः।
निपीडितशिरोग्रीवा व्यवेष्टन्त महाहयः॥', 'atipramāṇā balino dīptajihvā mahāviṣāḥ
nipīḍitaśirogrīvā vyaveṣṭanta mahāhayaḥ', null, 5054023),
('ramayana-5-54-24', 24, 'Sundara Kanda, Sarga 54, Verse 24', 'किंनरोरगगन्धर्वयक्षविद्याधरास्तथा।
पीडितं तं नगवरं त्यक्त्वा गगनमास्थिताः॥', 'kiṃnaroragagandharvayakṣavidyādharās tathā
pīḍitaṃ taṃ nagavaraṃ tyaktvā gaganam āsthitāḥ', null, 5054024),
('ramayana-5-54-25', 25, 'Sundara Kanda, Sarga 54, Verse 25', 'स च भूमिधरः श्रीमान्बलिना तेन पीडितः।
सवृक्षशिखरोदग्राः प्रविवेश रसातलम्॥', 'sa ca bhūmidharaḥ śrīmān balinā tena pīḍitaḥ
savṛkṣaśikharodagrāḥ praviveśa rasātalam', null, 5054025),
('ramayana-5-54-26', 26, 'Sundara Kanda, Sarga 54, Verse 26', 'दशयोजनविस्तारस्त्रिंशद्योजनमुच्छ्रितः।
धरण्यां समतां यातः स बभूव धराधरः॥', 'daśayojanavistāras triṃśadyojanam ucchritaḥ
dharaṇyāṃ samatāṃ yātaḥ sa babhūva dharādharaḥ', null, 5054026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 55 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-55-1', 1, 'Sundara Kanda, Sarga 55, Verse 1', 'सचन्द्रकुमुदं रम्यं सार्ककारण्डवं शुभम्।
तिष्यश्रवणकदम्बमभ्रशैवलशाद्वलम्॥', 'sacandrakumudaṃ ramyaṃ sārkakāraṇḍavaṃ śubham
tiṣyaśravaṇakadambam abhraśaivalaśādvalam', null, 5055001),
('ramayana-5-55-2', 2, 'Sundara Kanda, Sarga 55, Verse 2', 'पुनर्वसु महामीनं लोहिताङ्गमहाग्रहम्।
ऐरावतमहाद्वीपं स्वातीहंसविलोडितम्॥', 'punarvasu mahāmīnaṃ lohitāṅgamahāgraham
airāvatamahādvīpaṃ svātīhaṃsaviloḍitam', null, 5055002),
('ramayana-5-55-3', 3, 'Sundara Kanda, Sarga 55, Verse 3', 'वातसंघातजातोर्मिं चन्द्रांशुशिशिराम्बुमत्।
भुजंगयक्षगन्धर्वप्रबुद्धकमलोत्पलम्॥', 'vātasaṃghātajātormiṃ candrāṃśuśiśirāmbumat
bhujaṃgayakṣagandharvaprabuddhakamalotpalam', null, 5055003),
('ramayana-5-55-4', 4, 'Sundara Kanda, Sarga 55, Verse 4', 'ग्रसमान इवाकाशं ताराधिपमिवालिखन्।
हरन्निव सनक्षत्रं गगनं सार्कमण्डलम्॥', 'grasamāna ivākāśaṃ tārādhipam ivālikhan
harann iva sanakṣatraṃ gaganaṃ sārkamaṇḍalam', null, 5055004),
('ramayana-5-55-5', 5, 'Sundara Kanda, Sarga 55, Verse 5', 'मारुतस्यालयं श्रीमान्कपिर्व्योमचरो महान्।
हनूमान्मेघजालानि विकर्षन्निव गच्छति॥', 'mārutasyālayaṃ śrīmān kapir vyomacaro mahān
hanūmān meghajālāni vikarṣann iva gacchati', null, 5055005),
('ramayana-5-55-6', 6, 'Sundara Kanda, Sarga 55, Verse 6', 'पाण्डुरारुणवर्णानि नीलमाञ्जिष्ठकानि च।
हरितारुणवर्णानि महाभ्राणि चकाशिरे॥', 'pāṇḍurāruṇavarṇāni nīlamāñjiṣṭhakāni ca
haritāruṇavarṇāni mahābhrāṇi cakāśire', null, 5055006),
('ramayana-5-55-7', 7, 'Sundara Kanda, Sarga 55, Verse 7', 'प्रविशन्नभ्रजालानि निष्क्रमंश्च पुनः पुनः।
प्रच्छन्नश्च प्रकाशश्च चन्द्रमा इव लक्ष्यते॥', 'praviśann abhrajālāni niṣkramaṃś ca punaḥ punaḥ
pracchannaś ca prakāśaś ca candramā iva lakṣyate', null, 5055007),
('ramayana-5-55-8', 8, 'Sundara Kanda, Sarga 55, Verse 8', 'नदन्नादेन महता मेघस्वनमहास्वनः।
आजगाम महातेजाः पुनर्मध्येन सागरम्॥', 'nadan nādena mahatā meghasvanamahāsvanaḥ
ājagāma mahātejāḥ punar madhyena sāgaram', null, 5055008),
('ramayana-5-55-9', 9, 'Sundara Kanda, Sarga 55, Verse 9', 'पर्वतेन्द्रं सुनाभं च समुपस्पृश्य वीर्यवान्।
ज्यामुक्त इव नाराचो महावेगोऽभ्युपागतः॥', 'parvatendraṃ sunābhaṃ ca samupaspṛśya vīryavān
jyāmukta iva nārāco mahāvego ''bhyupāgataḥ', null, 5055009),
('ramayana-5-55-10', 10, 'Sundara Kanda, Sarga 55, Verse 10', 'स किं चिदनुसंप्राप्तः समालोक्य महागिरिम्।
महेन्द्रमेघसंकाशं ननाद हरिपुंगवः॥', 'sa kiṃ cid anusaṃprāptaḥ samālokya mahāgirim
mahendrameghasaṃkāśaṃ nanāda haripuṃgavaḥ', null, 5055010),
('ramayana-5-55-11', 11, 'Sundara Kanda, Sarga 55, Verse 11', 'निशम्य नदतो नादं वानरास्ते समन्ततः।
बभूवुरुत्सुकाः सर्वे सुहृद्दर्शनकाङ्क्षिणः॥', 'niśamya nadato nādaṃ vānarās te samantataḥ
babhūvur utsukāḥ sarve suhṛddarśanakāṅkṣiṇaḥ', null, 5055011),
('ramayana-5-55-12', 12, 'Sundara Kanda, Sarga 55, Verse 12', 'जाम्बवान्स हरिश्रेष्ठः प्रीतिसंहृष्टमानसः।
उपामन्त्र्य हरीन्सर्वानिदं वचनमब्रवीत्॥', 'jāmbavān sa hariśreṣṭhaḥ prītisaṃhṛṣṭamānasaḥ
upāmantrya harīn sarvān idaṃ vacanam abravīt', null, 5055012),
('ramayana-5-55-13', 13, 'Sundara Kanda, Sarga 55, Verse 13', 'सर्वथा कृतकार्योऽसौ हनूमान्नात्र संशयः।
न ह्यस्याकृतकार्यस्य नाद एवंविधो भवेत्॥', 'sarvathā kṛtakāryo ''sau hanūmān nātra saṃśayaḥ
na hy asyākṛtakāryasya nāda evaṃvidho bhavet', null, 5055013),
('ramayana-5-55-14', 14, 'Sundara Kanda, Sarga 55, Verse 14', 'तस्या बाहूरुवेगं च निनादं च महात्मनः।
निशम्य हरयो हृष्टाः समुत्पेतुस्ततस्ततः॥', 'tasyā bāhūruvegaṃ ca ninādaṃ ca mahātmanaḥ
niśamya harayo hṛṣṭāḥ samutpetus tatas tataḥ', null, 5055014),
('ramayana-5-55-15', 15, 'Sundara Kanda, Sarga 55, Verse 15', 'ते नगाग्रान्नगाग्राणि शिखराच्छिखराणि च।
प्रहृष्टाः समपद्यन्त हनूमन्तं दिदृक्षवः॥', 'te nagāgrān nagāgrāṇi śikharāc chikharāṇi ca
prahṛṣṭāḥ samapadyanta hanūmantaṃ didṛkṣavaḥ', null, 5055015),
('ramayana-5-55-16', 16, 'Sundara Kanda, Sarga 55, Verse 16', 'ते प्रीताः पादपाग्रेषु गृह्य शाखाः सुपुष्पिताः।
वासांसीव प्रकाशानि समाविध्यन्त वानराः॥', 'te prītāḥ pādapāgreṣu gṛhya śākhāḥ supuṣpitāḥ
vāsāṃsīva prakāśāni samāvidhyanta vānarāḥ', null, 5055016),
('ramayana-5-55-17', 17, 'Sundara Kanda, Sarga 55, Verse 17', 'तमभ्रघनसंकाशमापतन्तं महाकपिम्।
दृष्ट्वा ते वानराः सर्वे तस्थुः प्राञ्जलयस्तदा॥', 'tam abhraghanasaṃkāśam āpatantaṃ mahākapim
dṛṣṭvā te vānarāḥ sarve tasthuḥ prāñjalayas tadā', null, 5055017),
('ramayana-5-55-18', 18, 'Sundara Kanda, Sarga 55, Verse 18', 'ततस्तु वेगवांस्तस्य गिरेर्गिरिनिभः कपिः।
निपपात महेन्द्रस्य शिखरे पादपाकुले॥', 'tatas tu vegavāṃs tasya girer girinibhaḥ kapiḥ
nipapāta mahendrasya śikhare pādapākule', null, 5055018),
('ramayana-5-55-19', 19, 'Sundara Kanda, Sarga 55, Verse 19', 'ततस्ते प्रीतमनसः सर्वे वानरपुंगवाः।
हनूमन्तं महात्मानं परिवार्योपतस्थिरे॥', 'tatas te prītamanasaḥ sarve vānarapuṃgavāḥ
hanūmantaṃ mahātmānaṃ parivāryopatasthire', null, 5055019),
('ramayana-5-55-20', 20, 'Sundara Kanda, Sarga 55, Verse 20', 'परिवार्य च ते सर्वे परां प्रीतिमुपागताः।
प्रहृष्टवदनाः सर्वे तमरोगमुपागतम्॥', 'parivārya ca te sarve parāṃ prītim upāgatāḥ
prahṛṣṭavadanāḥ sarve tam arogam upāgatam', null, 5055020),
('ramayana-5-55-21', 21, 'Sundara Kanda, Sarga 55, Verse 21', 'उपायनानि चादाय मूलानि च फलानि च।
प्रत्यर्चयन्हरिश्रेष्ठं हरयो मारुतात्मजम्॥', 'upāyanāni cādāya mūlāni ca phalāni ca
pratyarcayan hariśreṣṭhaṃ harayo mārutātmajam', null, 5055021),
('ramayana-5-55-22', 22, 'Sundara Kanda, Sarga 55, Verse 22', 'विनेदुर्मुदिताः के चिच्चक्रुः किल किलां तथा।
हृष्टाः पादपशाखाश्च आनिन्युर्वानरर्षभाः॥', 'vinedur muditāḥ ke cic cakruḥ kila kilāṃ tathā
hṛṣṭāḥ pādapaśākhāś ca āninyur vānararṣabhāḥ', null, 5055022),
('ramayana-5-55-23', 23, 'Sundara Kanda, Sarga 55, Verse 23', 'हनूमांस्तु गुरून्वृद्धाञ्जाम्बवत्प्रमुखांस्तदा।
कुमारमङ्गदं चैव सोऽवन्दत महाकपिः॥', 'hanūmāṃs tu gurūn vṛddhāñ jāmbavat pramukhāṃs tadā
kumāram aṅgadaṃ caiva so ''vandata mahākapiḥ', null, 5055023),
('ramayana-5-55-24', 24, 'Sundara Kanda, Sarga 55, Verse 24', 'स ताभ्यां पूजितः पूज्यः कपिभिश्च प्रसादितः।
दृष्टा देवीति विक्रान्तः संक्षेपेण न्यवेदयत्॥', 'sa tābhyāṃ pūjitaḥ pūjyaḥ kapibhiś ca prasāditaḥ
dṛṣṭā devīti vikrāntaḥ saṃkṣepeṇa nyavedayat', null, 5055024),
('ramayana-5-55-25', 25, 'Sundara Kanda, Sarga 55, Verse 25', 'निषसाद च हस्तेन गृहीत्वा वालिनः सुतम्।
रमणीये वनोद्देशे महेन्द्रस्य गिरेस्तदा॥', 'niṣasāda ca hastena gṛhītvā vālinaḥ sutam
ramaṇīye vanoddeśe mahendrasya gires tadā', null, 5055025),
('ramayana-5-55-26', 26, 'Sundara Kanda, Sarga 55, Verse 26', 'हनूमानब्रवीद्धृष्टस्तदा तान्वानरर्षभान्।
अशोकवनिकासंस्था दृष्टा सा जनकात्मजा॥', 'hanūmān abravīd dhṛṣṭas tadā tān vānararṣabhān
aśokavanikāsaṃsthā dṛṣṭā sā janakātmajā', null, 5055026),
('ramayana-5-55-27', 27, 'Sundara Kanda, Sarga 55, Verse 27', 'रक्ष्यमाणा सुघोराभी राक्षसीभिरनिन्दिता।
एकवेणीधरा बाला रामदर्शनलालसा।
उपवासपरिश्रान्ता मलिना जटिला कृशा॥', 'rakṣyamāṇā sughorābhī rākṣasībhir aninditā
ekaveṇīdharā bālā rāmadarśanalālasā
upavāsapariśrāntā malinā jaṭilā kṛśā', null, 5055027),
('ramayana-5-55-28', 28, 'Sundara Kanda, Sarga 55, Verse 28', 'ततो दृष्टेति वचनं महार्थममृतोपमम्।
निशम्य मारुतेः सर्वे मुदिता वानरा भवन्॥', 'tato dṛṣṭeti vacanaṃ mahārtham amṛtopamam
niśamya māruteḥ sarve muditā vānarā bhavan', null, 5055028),
('ramayana-5-55-29', 29, 'Sundara Kanda, Sarga 55, Verse 29', 'क्ष्वेडन्त्यन्ये नदन्त्यन्ये गर्जन्त्यन्ये महाबलाः।
चक्रुः किल किलामन्ये प्रतिगर्जन्ति चापरे॥', 'kṣveḍanty anye nadanty anye garjanty anye mahābalāḥ
cakruḥ kila kilām anye pratigarjanti cāpare', null, 5055029),
('ramayana-5-55-30', 30, 'Sundara Kanda, Sarga 55, Verse 30', 'के चिदुच्छ्रितलाङ्गूलाः प्रहृष्टाः कपिकुञ्जराः।
अञ्चितायतदीर्घाणि लाङ्गूलानि प्रविव्यधुः॥', 'ke cid ucchritalāṅgūlāḥ prahṛṣṭāḥ kapikuñjarāḥ
añcitāyatadīrghāṇi lāṅgūlāni pravivyadhuḥ', null, 5055030),
('ramayana-5-55-31', 31, 'Sundara Kanda, Sarga 55, Verse 31', 'अपरे तु हनूमन्तं वानरा वारणोपमम्।
आप्लुत्य गिरिशृङ्गेभ्यः संस्पृशन्ति स्म हर्षिताः॥', 'apare tu hanūmantaṃ vānarā vāraṇopamam
āplutya giriśṛṅgebhyaḥ saṃspṛśanti sma harṣitāḥ', null, 5055031),
('ramayana-5-55-32', 32, 'Sundara Kanda, Sarga 55, Verse 32', 'उक्तवाक्यं हनूमन्तमङ्गदस्तु तदाब्रवीत्।
सर्वेषां हरिवीराणां मध्ये वाचमनुत्तमाम्॥', 'uktavākyaṃ hanūmantam aṅgadas tu tadābravīt
sarveṣāṃ harivīrāṇāṃ madhye vācam anuttamām', null, 5055032),
('ramayana-5-55-33', 33, 'Sundara Kanda, Sarga 55, Verse 33', 'सत्त्वे वीर्ये न ते कश्चित्समो वानरविद्यते।
यदवप्लुत्य विस्तीर्णं सागरं पुनरागतः॥', 'sattve vīrye na te kaś cit samo vānaravidyate
yad avaplutya vistīrṇaṃ sāgaraṃ punar āgataḥ', null, 5055033),
('ramayana-5-55-34', 34, 'Sundara Kanda, Sarga 55, Verse 34', 'दिष्ट्या दृष्टा त्वया देवी रामपत्नी यशस्विनी।
दिष्ट्या त्यक्ष्यति काकुत्स्थः शोकं सीता वियोगजम्॥', 'diṣṭyā dṛṣṭā tvayā devī rāmapatnī yaśasvinī
diṣṭyā tyakṣyati kākutsthaḥ śokaṃ sītā viyogajam', null, 5055034),
('ramayana-5-55-35', 35, 'Sundara Kanda, Sarga 55, Verse 35', 'ततोऽङ्गदं हनूमन्तं जाम्बवन्तं च वानराः।
परिवार्य प्रमुदिता भेजिरे विपुलाः शिलाः॥', 'tato ''ṅgadaṃ hanūmantaṃ jāmbavantaṃ ca vānarāḥ
parivārya pramuditā bhejire vipulāḥ śilāḥ', null, 5055035),
('ramayana-5-55-36', 36, 'Sundara Kanda, Sarga 55, Verse 36', 'श्रोतुकामाः समुद्रस्य लङ्घनं वानरोत्तमाः।
दर्शनं चापि लङ्कायाः सीताया रावणस्य च।
तस्थुः प्राञ्जलयः सर्वे हनूमद्वदनोन्मुखाः॥', 'śrotukāmāḥ samudrasya laṅghanaṃ vānarottamāḥ
darśanaṃ cāpi laṅkāyāḥ sītāyā rāvaṇasya ca
tasthuḥ prāñjalayaḥ sarve hanūmad vadanonmukhāḥ', null, 5055036),
('ramayana-5-55-37', 37, 'Sundara Kanda, Sarga 55, Verse 37', 'तस्थौ तत्राङ्गदः श्रीमान्वानरैर्बहुभिर्वृतः।
उपास्यमानो विबुधैर्दिवि देवपतिर्यथा॥', 'tasthau tatrāṅgadaḥ śrīmān vānarair bahubhir vṛtaḥ
upāsyamāno vibudhair divi devapatir yathā', null, 5055037),
('ramayana-5-55-38', 38, 'Sundara Kanda, Sarga 55, Verse 38', 'हनूमता कीर्तिमता यशस्विना तथाङ्गदेनाङ्गदबद्धबाहुना।
मुदा तदाध्यासितमुन्नतं महन्महीधराग्रं ज्वलितं श्रियाभवत्॥', 'hanūmatā kīrtimatā yaśasvinā tathāṅgadenāṅgadabaddhabāhunā
mudā tadādhyāsitam unnataṃ mahan mahīdharāgraṃ jvalitaṃ śriyābhavat', null, 5055038)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 56 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-56-1', 1, 'Sundara Kanda, Sarga 56, Verse 1', 'ततस्तस्य गिरेः शृङ्गे महेन्द्रस्य महाबलाः।
हनुमत्प्रमुखाः प्रीतिं हरयो जग्मुरुत्तमाम्॥', 'tatas tasya gireḥ śṛṅge mahendrasya mahābalāḥ
hanumatpramukhāḥ prītiṃ harayo jagmur uttamām', null, 5056001),
('ramayana-5-56-2', 2, 'Sundara Kanda, Sarga 56, Verse 2', 'तं ततः प्रतिसंहृष्टः प्रीतिमन्तं महाकपिम्।
जाम्बवान्कार्यवृत्तान्तमपृच्छदनिलात्मजम्॥', 'taṃ tataḥ pratisaṃhṛṣṭaḥ prītimantaṃ mahākapim
jāmbavān kāryavṛttāntam apṛcchad anilātmajam', null, 5056002),
('ramayana-5-56-3', 3, 'Sundara Kanda, Sarga 56, Verse 3', 'कथं दृष्टा त्वया देवी कथं वा तत्र वर्तते।
तस्यां वा स कथं वृत्तः क्रूरकर्मा दशाननः॥', 'kathaṃ dṛṣṭā tvayā devī kathaṃ vā tatra vartate
tasyāṃ vā sa kathaṃ vṛttaḥ krūrakarmā daśānanaḥ', null, 5056003),
('ramayana-5-56-4', 4, 'Sundara Kanda, Sarga 56, Verse 4', 'तत्त्वतः सर्वमेतन्नः प्रब्रूहि त्वं महाकपे।
श्रुतार्थाश्चिन्तयिष्यामो भूयः कार्यविनिश्चयम्॥', 'tattvataḥ sarvam etan naḥ prabrūhi tvaṃ mahākape
śrutārthāś cintayiṣyāmo bhūyaḥ kāryaviniścayam', null, 5056004),
('ramayana-5-56-5', 5, 'Sundara Kanda, Sarga 56, Verse 5', 'यश्चार्थस्तत्र वक्तव्यो गतैरस्माभिरात्मवान्।
रक्षितव्यं च यत्तत्र तद्भवान्व्याकरोतु नः॥', 'yaś cārthas tatra vaktavyo gatair asmābhir ātmavān
rakṣitavyaṃ ca yat tatra tad bhavān vyākarotu naḥ', null, 5056005),
('ramayana-5-56-6', 6, 'Sundara Kanda, Sarga 56, Verse 6', 'स नियुक्तस्ततस्तेन संप्रहृष्टतनूरुहः।
नमस्यञ्शिरसा देव्यै सीतायै प्रत्यभाषत॥', 'sa niyuktas tatas tena saṃprahṛṣṭatanūruhaḥ
namasyañ śirasā devyai sītāyai pratyabhāṣata', null, 5056006),
('ramayana-5-56-7', 7, 'Sundara Kanda, Sarga 56, Verse 7', 'प्रत्यक्षमेव भवतां महेन्द्राग्रात्खमाप्लुतः।
उदधेर्दक्षिणं पारं काङ्क्षमाणः समाहितः॥', 'pratyakṣam eva bhavatāṃ mahendrāgrāt kham āplutaḥ
udadher dakṣiṇaṃ pāraṃ kāṅkṣamāṇaḥ samāhitaḥ', null, 5056007),
('ramayana-5-56-8', 8, 'Sundara Kanda, Sarga 56, Verse 8', 'गच्छतश्च हि मे घोरं विघ्नरूपमिवाभवत्।
काञ्चनं शिखरं दिव्यं पश्यामि सुमनोहरम्॥', 'gacchataś ca hi me ghoraṃ vighnarūpam ivābhavat
kāñcanaṃ śikharaṃ divyaṃ paśyāmi sumanoharam', null, 5056008),
('ramayana-5-56-9', 9, 'Sundara Kanda, Sarga 56, Verse 9', 'स्थितं पन्थानमावृत्य मेने विघ्नं च तं नगम्॥', 'sthitaṃ panthānam āvṛtya mene vighnaṃ ca taṃ nagam', null, 5056009),
('ramayana-5-56-10', 10, 'Sundara Kanda, Sarga 56, Verse 10', 'उपसंगम्य तं दिव्यं काञ्चनं नगसत्तमम्।
कृता मे मनसा बुद्धिर्भेत्तव्योऽयं मयेति च॥', 'upasaṃgamya taṃ divyaṃ kāñcanaṃ nagasattamam
kṛtā me manasā buddhir bhettavyo ''yaṃ mayeti ca', null, 5056010),
('ramayana-5-56-11', 11, 'Sundara Kanda, Sarga 56, Verse 11', 'प्रहतं च मया तस्य लाङ्गूलेन महागिरेः।
शिखरं सूर्यसंकाशं व्यशीर्यत सहस्रधा॥', 'prahataṃ ca mayā tasya lāṅgūlena mahāgireḥ
śikharaṃ sūryasaṃkāśaṃ vyaśīryata sahasradhā', null, 5056011),
('ramayana-5-56-12', 12, 'Sundara Kanda, Sarga 56, Verse 12', 'व्यवसायं च मे बुद्ध्वा स होवाच महागिरिः।
पुत्रेति मधुरां बाणीं मनःप्रह्लादयन्निव॥', 'vyavasāyaṃ ca me buddhvā sa hovāca mahāgiriḥ
putreti madhurāṃ bāṇīṃ manaḥprahlādayann iva', null, 5056012),
('ramayana-5-56-13', 13, 'Sundara Kanda, Sarga 56, Verse 13', 'पितृव्यं चापि मां विद्धि सखायं मातरिश्वनः।
मैनाकमिति विख्यातं निवसन्तं महोदधौ॥', 'pitṛvyaṃ cāpi māṃ viddhi sakhāyaṃ mātariśvanaḥ
mainākam iti vikhyātaṃ nivasantaṃ mahodadhau', null, 5056013),
('ramayana-5-56-14', 14, 'Sundara Kanda, Sarga 56, Verse 14', 'पक्ष्ववन्तः पुरा पुत्र बभूवुः पर्वतोत्तमाः।
छन्दतः पृथिवीं चेरुर्बाधमानाः समन्ततः॥', 'pakṣvavantaḥ purā putra babhūvuḥ parvatottamāḥ
chandataḥ pṛthivīṃ cerur bādhamānāḥ samantataḥ', null, 5056014),
('ramayana-5-56-15', 15, 'Sundara Kanda, Sarga 56, Verse 15', 'श्रुत्वा नगानां चरितं महेन्द्रः पाकशासनः।
चिच्छेद भगवान्पक्षान्वज्रेणैषां सहस्रशः॥', 'śrutvā nagānāṃ caritaṃ mahendraḥ pākaśāsanaḥ
ciccheda bhagavān pakṣān vajreṇaiṣāṃ sahasraśaḥ', null, 5056015),
('ramayana-5-56-16', 16, 'Sundara Kanda, Sarga 56, Verse 16', 'अहं तु मोक्षितस्तस्मात्तव पित्रा महात्मना।
मारुतेन तदा वत्स प्रक्षिप्तोऽस्मि महार्णवे॥', 'ahaṃ tu mokṣitas tasmāt tava pitrā mahātmanā
mārutena tadā vatsa prakṣipto ''smi mahārṇave', null, 5056016),
('ramayana-5-56-17', 17, 'Sundara Kanda, Sarga 56, Verse 17', 'रामस्य च मया साह्ये वर्तितव्यमरिंदम।
रामो धर्मभृतां श्रेष्ठो महेन्द्रसमविक्रमः॥', 'rāmasya ca mayā sāhye vartitavyam ariṃdama
rāmo dharmabhṛtāṃ śreṣṭho mahendrasamavikramaḥ', null, 5056017),
('ramayana-5-56-18', 18, 'Sundara Kanda, Sarga 56, Verse 18', 'एतच्छ्रुत्वा मया तस्य मैनाकस्य महात्मनः।
कार्यमावेद्य तु गिरेरुद्धतं च मनो मम॥', 'etac chrutvā mayā tasya mainākasya mahātmanaḥ
kāryam āvedya tu girer uddhataṃ ca mano mama', null, 5056018),
('ramayana-5-56-19', 19, 'Sundara Kanda, Sarga 56, Verse 19', 'तेन चाहमनुज्ञातो मैनाकेन महात्मना।
उत्तमं जवमास्थाय शेषमध्वानमास्थितः॥', 'tena cāham anujñāto mainākena mahātmanā
uttamaṃ javam āsthāya śeṣam adhvānam āsthitaḥ', null, 5056019),
('ramayana-5-56-20', 20, 'Sundara Kanda, Sarga 56, Verse 20', 'ततोऽहं सुचिरं कालं वेगेनाभ्यगमं पथि।
ततः पश्याम्यहं देवीं सुरसां नागमातरम्॥', 'tato ''haṃ suciraṃ kālaṃ vegenābhyagamaṃ pathi
tataḥ paśyāmy ahaṃ devīṃ surasāṃ nāgamātaram', null, 5056020),
('ramayana-5-56-21', 21, 'Sundara Kanda, Sarga 56, Verse 21', 'समुद्रमध्ये सा देवी वचनं मामभाषत।
मम भक्ष्यः प्रदिष्टस्त्वममारैर्हरिसत्तमम्।
ततस्त्वां भक्षयिष्यामि विहितस्त्वं चिरस्य मे॥', 'samudramadhye sā devī vacanaṃ mām abhāṣata
mama bhakṣyaḥ pradiṣṭas tvam amārair harisattamam
tatas tvāṃ bhakṣayiṣyāmi vihitas tvaṃ cirasya me', null, 5056021),
('ramayana-5-56-22', 22, 'Sundara Kanda, Sarga 56, Verse 22', 'एवमुक्तः सुरसया प्राञ्जलिः प्रणतः स्थितः।
विवर्णवदनो भूत्वा वाक्यं चेदमुदीरयम्॥', 'evam uktaḥ surasayā prāñjaliḥ praṇataḥ sthitaḥ
vivarṇavadano bhūtvā vākyaṃ cedam udīrayam', null, 5056022),
('ramayana-5-56-23', 23, 'Sundara Kanda, Sarga 56, Verse 23', 'रामो दाशरथिः श्रीमान्प्रविष्टो दण्डकावनम्।
लक्ष्मणेन सह भ्रात्रा सीतया च परंतपः॥', 'rāmo dāśarathiḥ śrīmān praviṣṭo daṇḍakāvanam
lakṣmaṇena saha bhrātrā sītayā ca paraṃtapaḥ', null, 5056023),
('ramayana-5-56-24', 24, 'Sundara Kanda, Sarga 56, Verse 24', 'तस्य सीता हृता भार्या रावणेन दुरात्मना।
तस्याः सकाशं दूतोऽहं गमिष्ये रामशासनात्॥', 'tasya sītā hṛtā bhāryā rāvaṇena durātmanā
tasyāḥ sakāśaṃ dūto ''haṃ gamiṣye rāmaśāsanāt', null, 5056024),
('ramayana-5-56-25', 25, 'Sundara Kanda, Sarga 56, Verse 25', 'कर्तुमर्हसि रामस्य साह्यं विषयवासिनि॥', 'kartum arhasi rāmasya sāhyaṃ viṣayavāsini', null, 5056025),
('ramayana-5-56-26', 26, 'Sundara Kanda, Sarga 56, Verse 26', 'अथ वा मैथिलीं दृष्ट्वा रामं चाक्लिष्टकारिणम्।
आगमिष्यामि ते वक्त्रं सत्यं प्रतिशृणोति मे॥', 'atha vā maithilīṃ dṛṣṭvā rāmaṃ cākliṣṭakāriṇam
āgamiṣyāmi te vaktraṃ satyaṃ pratiśṛṇoti me', null, 5056026),
('ramayana-5-56-27', 27, 'Sundara Kanda, Sarga 56, Verse 27', 'एवमुक्ता मया सा तु सुरसा कामरूपिणी।
अब्रवीन्नातिवर्तेत कश्चिदेष वरो मम॥', 'evam uktā mayā sā tu surasā kāmarūpiṇī
abravīn nātivarteta kaś cid eṣa varo mama', null, 5056027),
('ramayana-5-56-28', 28, 'Sundara Kanda, Sarga 56, Verse 28', 'एवमुक्तः सुरसया दशयोजनमायतः।
ततोऽर्धगुणविस्तारो बभूवाहं क्षणेन तु॥', 'evam uktaḥ surasayā daśayojanam āyataḥ
tato ''rdhaguṇavistāro babhūvāhaṃ kṣaṇena tu', null, 5056028),
('ramayana-5-56-29', 29, 'Sundara Kanda, Sarga 56, Verse 29', 'मत्प्रमाणानुरूपं च व्यादितं तन्मुखं तया।
तद्दृष्ट्वा व्यादितं त्वास्यं ह्रस्वं ह्यकरवं वपुः॥', 'matpramāṇānurūpaṃ ca vyāditaṃ tanmukhaṃ tayā
tad dṛṣṭvā vyāditaṃ tv āsyaṃ hrasvaṃ hy akaravaṃ vapuḥ', null, 5056029),
('ramayana-5-56-30', 30, 'Sundara Kanda, Sarga 56, Verse 30', 'तस्मिन्मुहूर्ते च पुनर्बभूवाङ्गुष्ठसंमितः।
अभिपत्याशु तद्वक्त्रं निर्गतोऽहं ततः क्षणात्॥', 'tasmin muhūrte ca punar babhūvāṅguṣṭhasaṃmitaḥ
abhipatyāśu tad vaktraṃ nirgato ''haṃ tataḥ kṣaṇāt', null, 5056030),
('ramayana-5-56-31', 31, 'Sundara Kanda, Sarga 56, Verse 31', 'अब्रवीत्सुरसा देवी स्वेन रूपेण मां पुनः।
अर्थसिद्ध्यै हरिश्रेष्ठ गच्छ सौम्य यथासुखम्॥', 'abravīt surasā devī svena rūpeṇa māṃ punaḥ
arthasiddhyai hariśreṣṭha gaccha saumya yathāsukham', null, 5056031),
('ramayana-5-56-32', 32, 'Sundara Kanda, Sarga 56, Verse 32', 'समानय च वैदेहीं राघवेण महात्मना।
सुखी भव महाबाहो प्रीतास्मि तव वानर॥', 'samānaya ca vaidehīṃ rāghaveṇa mahātmanā
sukhī bhava mahābāho prītāsmi tava vānara', null, 5056032),
('ramayana-5-56-33', 33, 'Sundara Kanda, Sarga 56, Verse 33', 'ततोऽहं साधु साध्वीति सर्वभूतैः प्रशंसितः।
ततोऽन्तरिक्षं विपुलं प्लुतोऽहं गरुडो यथा॥', 'tato ''haṃ sādhu sādhvīti sarvabhūtaiḥ praśaṃsitaḥ
tato ''ntarikṣaṃ vipulaṃ pluto ''haṃ garuḍo yathā', null, 5056033),
('ramayana-5-56-34', 34, 'Sundara Kanda, Sarga 56, Verse 34', 'छाया मे निगृहीता च न च पश्यामि किं चन।
सोऽहं विगतवेगस्तु दिशो दश विलोकयन्।
न किं चित्तत्र पश्यामि येन मेऽपहृता गतिः॥', 'chāyā me nigṛhītā ca na ca paśyāmi kiṃ cana
so ''haṃ vigatavegas tu diśo daśa vilokayan
na kiṃ cit tatra paśyāmi yena me ''pahṛtā gatiḥ', null, 5056034),
('ramayana-5-56-35', 35, 'Sundara Kanda, Sarga 56, Verse 35', 'ततो मे बुद्धिरुत्पन्ना किं नाम गमने मम।
ईदृशो विघ्न उत्पन्नो रूपं यत्र न दृश्यते॥', 'tato me buddhir utpannā kiṃ nāma gamane mama
īdṛśo vighna utpanno rūpaṃ yatra na dṛśyate', null, 5056035),
('ramayana-5-56-36', 36, 'Sundara Kanda, Sarga 56, Verse 36', 'अधो भागेन मे दृष्टिः शोचता पातिता मया।
ततोऽद्राक्षमहं भीमां राक्षसीं सलिले शयाम्॥', 'adho bhāgena me dṛṣṭiḥ śocatā pātitā mayā
tato ''drākṣam ahaṃ bhīmāṃ rākṣasīṃ salile śayām', null, 5056036),
('ramayana-5-56-37', 37, 'Sundara Kanda, Sarga 56, Verse 37', 'प्रहस्य च महानादमुक्तोऽहं भीमया तया।
अवस्थितमसंभ्रान्तमिदं वाक्यमशोभनम्॥', 'prahasya ca mahānādam ukto ''haṃ bhīmayā tayā
avasthitam asaṃbhrāntam idaṃ vākyam aśobhanam', null, 5056037),
('ramayana-5-56-38', 38, 'Sundara Kanda, Sarga 56, Verse 38', 'क्वासि गन्ता महाकाय क्षुधिताया ममेप्सितः।
भक्षः प्रीणय मे देहं चिरमाहारवर्जितम्॥', 'kvāsi gantā mahākāya kṣudhitāyā mamepsitaḥ
bhakṣaḥ prīṇaya me dehaṃ ciram āhāravarjitam', null, 5056038),
('ramayana-5-56-39', 39, 'Sundara Kanda, Sarga 56, Verse 39', 'बाढमित्येव तां वाणीं प्रत्यगृह्णामहं ततः।
आस्य प्रमाणादधिकं तस्याः कायमपूरयम्॥', 'bāḍham ity eva tāṃ vāṇīṃ pratyagṛhṇām ahaṃ tataḥ
āsya pramāṇād adhikaṃ tasyāḥ kāyam apūrayam', null, 5056039),
('ramayana-5-56-40', 40, 'Sundara Kanda, Sarga 56, Verse 40', 'तस्याश्चास्यं महद्भीमं वर्धते मम भक्षणे।
न च मां सा तु बुबुधे मम वा विकृतं कृतम्॥', 'tasyāś cāsyaṃ mahad bhīmaṃ vardhate mama bhakṣaṇe
na ca māṃ sā tu bubudhe mama vā vikṛtaṃ kṛtam', null, 5056040),
('ramayana-5-56-41', 41, 'Sundara Kanda, Sarga 56, Verse 41', 'ततोऽहं विपुलं रूपं संक्षिप्य निमिषान्तरात्।
तस्या हृदयमादाय प्रपतामि नभस्तलम्॥', 'tato ''haṃ vipulaṃ rūpaṃ saṃkṣipya nimiṣāntarāt
tasyā hṛdayam ādāya prapatāmi nabhastalam', null, 5056041),
('ramayana-5-56-42', 42, 'Sundara Kanda, Sarga 56, Verse 42', 'सा विसृष्टभुजा भीमा पपात लवणाम्भसि।
मया पर्वतसंकाशा निकृत्तहृदया सती॥', 'sā visṛṣṭabhujā bhīmā papāta lavaṇāmbhasi
mayā parvatasaṃkāśā nikṛttahṛdayā satī', null, 5056042),
('ramayana-5-56-43', 43, 'Sundara Kanda, Sarga 56, Verse 43', 'शृणोमि खगतानां च सिद्धानां चारणैः सह।
राक्षसी सिंहिका भीमा क्षिप्रं हनुमता हृता॥', 'śṛṇomi khagatānāṃ ca siddhānāṃ cāraṇaiḥ saha
rākṣasī siṃhikā bhīmā kṣipraṃ hanumatā hṛtā', null, 5056043),
('ramayana-5-56-44', 44, 'Sundara Kanda, Sarga 56, Verse 44', 'तां हत्वा पुनरेवाहं कृत्यमात्ययिकं स्मरन्।
गत्वा च महदध्वानं पश्यामि नगमण्डितम्।
दक्षिणं तीरमुदधेर्लङ्का यत्र च सा पुरी॥', 'tāṃ hatvā punar evāhaṃ kṛtyam ātyayikaṃ smaran
gatvā ca mahad adhvānaṃ paśyāmi nagamaṇḍitam
dakṣiṇaṃ tīram udadher laṅkā yatra ca sā purī', null, 5056044),
('ramayana-5-56-45', 45, 'Sundara Kanda, Sarga 56, Verse 45', 'अस्तं दिनकरे याते रक्षसां निलयं पुरीम्।
प्रविष्टोऽहमविज्ञातो रक्षोभिर्भीमविक्रमैः॥', 'astaṃ dinakare yāte rakṣasāṃ nilayaṃ purīm
praviṣṭo ''ham avijñāto rakṣobhir bhīmavikramaiḥ', null, 5056045),
('ramayana-5-56-46', 46, 'Sundara Kanda, Sarga 56, Verse 46', 'तत्राहं सर्वरात्रं तु विचिन्वञ्जनकात्मजाम्।
रावणान्तःपुरगतो न चापश्यं सुमध्यमाम्॥', 'tatrāhaṃ sarvarātraṃ tu vicinvañ janakātmajām
rāvaṇāntaḥpuragato na cāpaśyaṃ sumadhyamām', null, 5056046),
('ramayana-5-56-47', 47, 'Sundara Kanda, Sarga 56, Verse 47', 'ततः सीतामपश्यंस्तु रावणस्य निवेशने।
शोकसागरमासाद्य न पारमुपलक्षये॥', 'tataḥ sītām apaśyaṃs tu rāvaṇasya niveśane
śokasāgaram āsādya na pāram upalakṣaye', null, 5056047),
('ramayana-5-56-48', 48, 'Sundara Kanda, Sarga 56, Verse 48', 'शोचता च मया दृष्टं प्राकारेण समावृतम्।
काञ्चनेन विकृष्टेन गृहोपवनमुत्तमम्॥', 'śocatā ca mayā dṛṣṭaṃ prākāreṇa samāvṛtam
kāñcanena vikṛṣṭena gṛhopavanam uttamam', null, 5056048),
('ramayana-5-56-49', 49, 'Sundara Kanda, Sarga 56, Verse 49', 'स प्राकारमवप्लुत्य पश्यामि बहुपादपम्॥', 'sa prākāram avaplutya paśyāmi bahupādapam', null, 5056049),
('ramayana-5-56-50', 50, 'Sundara Kanda, Sarga 56, Verse 50', 'अशोकवनिकामध्ये शिंशपापादपो महान्।
तमारुह्य च पश्यामि काञ्चनं कदली वनम्॥', 'aśokavanikāmadhye śiṃśapāpādapo mahān
tam āruhya ca paśyāmi kāñcanaṃ kadalī vanam', null, 5056050),
('ramayana-5-56-51', 51, 'Sundara Kanda, Sarga 56, Verse 51', 'अदूराच्छिंशपावृक्षात्पश्यामि वनवर्णिनीम्।
श्यामां कमलपत्राक्षीमुपवासकृशाननाम्॥', 'adūrāc chiṃśapāvṛkṣāt paśyāmi vanavarṇinīm
śyāmāṃ kamalapatrākṣīm upavāsakṛśānanām', null, 5056051),
('ramayana-5-56-52', 52, 'Sundara Kanda, Sarga 56, Verse 52', 'राक्षसीभिर्विरूपाभिः क्रूराभिरभिसंवृताम्।
मांसशोणितभक्ष्याभिर्व्याघ्रीभिर्हरिणीं यथा॥', 'rākṣasībhir virūpābhiḥ krūrābhir abhisaṃvṛtām
māṃsaśoṇitabhakṣyābhir vyāghrībhir hariṇīṃ yathā', null, 5056052),
('ramayana-5-56-53', 53, 'Sundara Kanda, Sarga 56, Verse 53', 'तां दृष्ट्वा तादृशीं नारीं रामपत्नीमनिन्दिताम्।
तत्रैव शिंशपावृक्षे पश्यन्नहमवस्थितः॥', 'tāṃ dṛṣṭvā tādṛśīṃ nārīṃ rāmapatnīm aninditām
tatraiva śiṃśapāvṛkṣe paśyann aham avasthitaḥ', null, 5056053),
('ramayana-5-56-54', 54, 'Sundara Kanda, Sarga 56, Verse 54', 'ततो हलहलाशब्दं काञ्चीनूपुरमिश्रितम्।
शृणोम्यधिकगम्भीरं रावणस्य निवेशने॥', 'tato halahalāśabdaṃ kāñcīnūpuramiśritam
śṛṇomy adhikagambhīraṃ rāvaṇasya niveśane', null, 5056054),
('ramayana-5-56-55', 55, 'Sundara Kanda, Sarga 56, Verse 55', 'ततोऽहं परमोद्विग्नः स्वरूपं प्रत्यसंहरम्।
अहं च शिंशपावृक्षे पक्षीव गहने स्थितः॥', 'tato ''haṃ paramodvignaḥ svarūpaṃ pratyasaṃharam
ahaṃ ca śiṃśapāvṛkṣe pakṣīva gahane sthitaḥ', null, 5056055),
('ramayana-5-56-56', 56, 'Sundara Kanda, Sarga 56, Verse 56', 'ततो रावणदाराश्च रावणश्च महाबलः।
तं देशं समनुप्राप्ता यत्र सीताभवत्स्थिता॥', 'tato rāvaṇadārāś ca rāvaṇaś ca mahābalaḥ
taṃ deśaṃ samanuprāptā yatra sītābhavat sthitā', null, 5056056),
('ramayana-5-56-57', 57, 'Sundara Kanda, Sarga 56, Verse 57', 'तं दृष्ट्वाथ वरारोहा सीता रक्षोगणेश्वरम्।
संकुच्योरू स्तनौ पीनौ बाहुभ्यां परिरभ्य च॥', 'taṃ dṛṣṭvātha varārohā sītā rakṣogaṇeśvaram
saṃkucyorū stanau pīnau bāhubhyāṃ parirabhya ca', null, 5056057),
('ramayana-5-56-58', 58, 'Sundara Kanda, Sarga 56, Verse 58', 'तामुवाच दशग्रीवः सीतां परमदुःखिताम्।
अवाक्शिराः प्रपतितो बहु मन्यस्व मामिति॥', 'tām uvāca daśagrīvaḥ sītāṃ paramaduḥkhitām
avākśirāḥ prapatito bahu manyasva mām iti', null, 5056058),
('ramayana-5-56-59', 59, 'Sundara Kanda, Sarga 56, Verse 59', 'यदि चेत्त्वं तु मां दर्पान्नाभिनन्दसि गर्विते।
द्विमासानन्तरं सीते पास्यामि रुधिरं तव॥', 'yadi cet tvaṃ tu māṃ darpān nābhinandasi garvite
dvimāsānantaraṃ sīte pāsyāmi rudhiraṃ tava', null, 5056059),
('ramayana-5-56-60', 60, 'Sundara Kanda, Sarga 56, Verse 60', 'एतच्छ्रुत्वा वचस्तस्य रावणस्य दुरात्मनः।
उवाच परमक्रुद्धा सीता वचनमुत्तमम्॥', 'etac chrutvā vacas tasya rāvaṇasya durātmanaḥ
uvāca paramakruddhā sītā vacanam uttamam', null, 5056060),
('ramayana-5-56-61', 61, 'Sundara Kanda, Sarga 56, Verse 61', 'राक्षसाधम रामस्य भार्याममिततेजसः।
इक्ष्वाकुकुलनाथस्य स्नुषां दशरथस्य च।
अवाच्यं वदतो जिह्वा कथं न पतिता तव॥', 'rākṣasādhama rāmasya bhāryām amitatejasaḥ
ikṣvākukulanāthasya snuṣāṃ daśarathasya ca
avācyaṃ vadato jihvā kathaṃ na patitā tava', null, 5056061),
('ramayana-5-56-62', 62, 'Sundara Kanda, Sarga 56, Verse 62', 'किंस्विद्वीर्यं तवानार्य यो मां भर्तुरसंनिधौ।
अपहृत्यागतः पाप तेनादृष्टो महात्मना॥', 'kiṃsvid vīryaṃ tavānārya yo māṃ bhartur asaṃnidhau
apahṛtyāgataḥ pāpa tenādṛṣṭo mahātmanā', null, 5056062),
('ramayana-5-56-63', 63, 'Sundara Kanda, Sarga 56, Verse 63', 'न त्वं रामस्य सदृशो दास्येऽप्यस्या न युज्यसे।
यज्ञीयः सत्यवाक्चैव रणश्लाघी च राघवः॥', 'na tvaṃ rāmasya sadṛśo dāsye ''py asyā na yujyase
yajñīyaḥ satyavāk caiva raṇaślāghī ca rāghavaḥ', null, 5056063),
('ramayana-5-56-64', 64, 'Sundara Kanda, Sarga 56, Verse 64', 'जानक्या परुषं वाक्यमेवमुक्तो दशाननः।
जज्वाल सहसा कोपाच्चितास्थ इव पावकः॥', 'jānakyā paruṣaṃ vākyam evam ukto daśānanaḥ
jajvāla sahasā kopāc citāstha iva pāvakaḥ', null, 5056064),
('ramayana-5-56-65', 65, 'Sundara Kanda, Sarga 56, Verse 65', 'विवृत्य नयने क्रूरे मुष्टिमुद्यम्य दक्षिणम्।
मैथिलीं हन्तुमारब्धः स्त्रीभिर्हाहाकृतं तदा॥', 'vivṛtya nayane krūre muṣṭim udyamya dakṣiṇam
maithilīṃ hantum ārabdhaḥ strībhir hāhākṛtaṃ tadā', null, 5056065),
('ramayana-5-56-66', 66, 'Sundara Kanda, Sarga 56, Verse 66', 'स्त्रीणां मध्यात्समुत्पत्य तस्य भार्या दुरात्मनः।
वरा मन्दोदरी नाम तया स प्रतिषेधितः॥', 'strīṇāṃ madhyāt samutpatya tasya bhāryā durātmanaḥ
varā mandodarī nāma tayā sa pratiṣedhitaḥ', null, 5056066),
('ramayana-5-56-67', 67, 'Sundara Kanda, Sarga 56, Verse 67', 'उक्तश्च मधुरां वाणीं तया स मदनार्दितः।
सीतया तव किं कार्यं महेन्द्रसमविक्रम।
मया सह रमस्वाद्य मद्विशिष्टा न जानकी॥', 'uktaś ca madhurāṃ vāṇīṃ tayā sa madanārditaḥ
sītayā tava kiṃ kāryaṃ mahendrasamavikrama
mayā saha ramasvādya madviśiṣṭā na jānakī', null, 5056067),
('ramayana-5-56-68', 68, 'Sundara Kanda, Sarga 56, Verse 68', 'देवगन्धर्वकन्याभिर्यक्षकन्याभिरेव च।
सार्धं प्रभो रमस्वेह सीतया किं करिष्यसि॥', 'devagandharvakanyābhir yakṣakanyābhir eva ca
sārdhaṃ prabho ramasveha sītayā kiṃ kariṣyasi', null, 5056068),
('ramayana-5-56-69', 69, 'Sundara Kanda, Sarga 56, Verse 69', 'ततस्ताभिः समेताभिर्नारीभिः स महाबलः।
उत्थाप्य सहसा नीतो भवनं स्वं निशाचरः॥', 'tatas tābhiḥ sametābhir nārībhiḥ sa mahābalaḥ
utthāpya sahasā nīto bhavanaṃ svaṃ niśācaraḥ', null, 5056069),
('ramayana-5-56-70', 70, 'Sundara Kanda, Sarga 56, Verse 70', 'याते तस्मिन्दशग्रीवे राक्षस्यो विकृताननाः।
सीतां निर्भर्त्सयामासुर्वाक्यैः क्रूरैः सुदारुणैः॥', 'yāte tasmin daśagrīve rākṣasyo vikṛtānanāḥ
sītāṃ nirbhartsayām āsur vākyaiḥ krūraiḥ sudāruṇaiḥ', null, 5056070),
('ramayana-5-56-71', 71, 'Sundara Kanda, Sarga 56, Verse 71', 'तृणवद्भाषितं तासां गणयामास जानकी।
तर्जितं च तदा तासां सीतां प्राप्य निरर्थकम्॥', 'tṛṇavad bhāṣitaṃ tāsāṃ gaṇayām āsa jānakī
tarjitaṃ ca tadā tāsāṃ sītāṃ prāpya nirarthakam', null, 5056071),
('ramayana-5-56-72', 72, 'Sundara Kanda, Sarga 56, Verse 72', 'वृथागर्जितनिश्चेष्टा राक्षस्यः पिशिताशनाः।
रावणाय शशंसुस्ताः सीताव्यवसितं महत्॥', 'vṛthāgarjitaniśceṣṭā rākṣasyaḥ piśitāśanāḥ
rāvaṇāya śaśaṃsus tāḥ sītāvyavasitaṃ mahat', null, 5056072),
('ramayana-5-56-73', 73, 'Sundara Kanda, Sarga 56, Verse 73', 'ततस्ताः सहिताः सर्वा विहताशा निरुद्यमाः।
परिक्षिप्य समन्तात्तां निद्रावशमुपागताः॥', 'tatas tāḥ sahitāḥ sarvā vihatāśā nirudyamāḥ
parikṣipya samantāt tāṃ nidrāvaśam upāgatāḥ', null, 5056073),
('ramayana-5-56-74', 74, 'Sundara Kanda, Sarga 56, Verse 74', 'तासु चैव प्रसुप्तासु सीता भर्तृहिते रता।
विलप्य करुणं दीना प्रशुशोच सुदुःखिता॥', 'tāsu caiva prasuptāsu sītā bhartṛhite ratā
vilapya karuṇaṃ dīnā praśuśoca suduḥkhitā', null, 5056074),
('ramayana-5-56-75', 75, 'Sundara Kanda, Sarga 56, Verse 75', 'तां चाहं तादृशीं दृष्ट्वा सीताया दारुणां दशाम्।
चिन्तयामास विश्रान्तो न च मे निर्वृतं मनः॥', 'tāṃ cāhaṃ tādṛśīṃ dṛṣṭvā sītāyā dāruṇāṃ daśām
cintayām āsa viśrānto na ca me nirvṛtaṃ manaḥ', null, 5056075),
('ramayana-5-56-76', 76, 'Sundara Kanda, Sarga 56, Verse 76', 'संभाषणार्थे च मया जानक्याश्चिन्तितो विधिः।
इक्ष्वाकुकुलवंशस्तु ततो मम पुरस्कृतः॥', 'saṃbhāṣaṇārthe ca mayā jānakyāś cintito vidhiḥ
ikṣvākukulavaṃśas tu tato mama puraskṛtaḥ', null, 5056076),
('ramayana-5-56-77', 77, 'Sundara Kanda, Sarga 56, Verse 77', 'श्रुत्वा तु गदितां वाचं राजर्षिगणपूजिताम्।
प्रत्यभाषत मां देवी बाष्पैः पिहितलोचना॥', 'śrutvā tu gaditāṃ vācaṃ rājarṣigaṇapūjitām
pratyabhāṣata māṃ devī bāṣpaiḥ pihitalocanā', null, 5056077),
('ramayana-5-56-78', 78, 'Sundara Kanda, Sarga 56, Verse 78', 'कस्त्वं केन कथं चेह प्राप्तो वानरपुंगव।
का च रामेण ते प्रीतिस्तन्मे शंसितुमर्हसि॥', 'kas tvaṃ kena kathaṃ ceha prāpto vānarapuṃgava
kā ca rāmeṇa te prītis tan me śaṃsitum arhasi', null, 5056078),
('ramayana-5-56-79', 79, 'Sundara Kanda, Sarga 56, Verse 79', 'तस्यास्तद्वचनं श्रुत्वा अहमप्यब्रुवं वचः।
देवि रामस्य भर्तुस्ते सहायो भीमविक्रमः।
सुग्रीवो नाम विक्रान्तो वानरेन्दो महाबलः॥', 'tasyās tad vacanaṃ śrutvā aham apy abruvaṃ vacaḥ
devi rāmasya bhartus te sahāyo bhīmavikramaḥ
sugrīvo nāma vikrānto vānarendo mahābalaḥ', null, 5056079),
('ramayana-5-56-80', 80, 'Sundara Kanda, Sarga 56, Verse 80', 'तस्य मां विद्धि भृत्यं त्वं हनूमन्तमिहागतम्।
भर्त्राहं प्रहितस्तुभ्यं रामेणाक्लिष्टकर्मणा॥', 'tasya māṃ viddhi bhṛtyaṃ tvaṃ hanūmantam ihāgatam
bhartrāhaṃ prahitas tubhyaṃ rāmeṇākliṣṭakarmaṇā', null, 5056080),
('ramayana-5-56-81', 81, 'Sundara Kanda, Sarga 56, Verse 81', 'इदं च पुरुषव्याघ्रः श्रीमान्दाशरथिः स्वयम्।
अङ्गुलीयमभिज्ञानमदात्तुभ्यं यशस्विनि॥', 'idaṃ ca puruṣavyāghraḥ śrīmān dāśarathiḥ svayam
aṅgulīyam abhijñānam adāt tubhyaṃ yaśasvini', null, 5056081),
('ramayana-5-56-82', 82, 'Sundara Kanda, Sarga 56, Verse 82', 'तदिच्छामि त्वयाज्ञप्तं देवि किं करवाण्यहम्।
रामलक्ष्मणयोः पार्श्वं नयामि त्वां किमुत्तरम्॥', 'tad icchāmi tvayājñaptaṃ devi kiṃ karavāṇy aham
rāmalakṣmaṇayoḥ pārśvaṃ nayāmi tvāṃ kim uttaram', null, 5056082),
('ramayana-5-56-83', 83, 'Sundara Kanda, Sarga 56, Verse 83', 'एतच्छ्रुत्वा विदित्वा च सीता जनकनन्दिनी।
आह रावणमुत्साद्य राघवो मां नयत्विति॥', 'etac chrutvā viditvā ca sītā janakanandinī
āha rāvaṇam utsādya rāghavo māṃ nayatv iti', null, 5056083),
('ramayana-5-56-84', 84, 'Sundara Kanda, Sarga 56, Verse 84', 'प्रणम्य शिरसा देवीमहमार्यामनिन्दिताम्।
राघवस्य मनोह्लादमभिज्ञानमयाचिषम्॥', 'praṇamya śirasā devīm aham āryām aninditām
rāghavasya manohlādam abhijñānam ayāciṣam', null, 5056084),
('ramayana-5-56-85', 85, 'Sundara Kanda, Sarga 56, Verse 85', 'एवमुक्ता वरारोहा मणिप्रवरमुत्तमम्।
प्रायच्छत्परमोद्विग्ना वाचा मां संदिदेश ह॥', 'evam uktā varārohā maṇipravaram uttamam
prāyacchat paramodvignā vācā māṃ saṃdideśa ha', null, 5056085),
('ramayana-5-56-86', 86, 'Sundara Kanda, Sarga 56, Verse 86', 'ततस्तस्यै प्रणम्याहं राजपुत्र्यै समाहितः।
प्रदक्षिणं परिक्राममिहाभ्युद्गतमानसः॥', 'tatas tasyai praṇamyāhaṃ rājaputryai samāhitaḥ
pradakṣiṇaṃ parikrāmam ihābhyudgatamānasaḥ', null, 5056086),
('ramayana-5-56-87', 87, 'Sundara Kanda, Sarga 56, Verse 87', 'उत्तरं पुनरेवाह निश्चित्य मनसा तदा।
हनूमन्मम वृत्तान्तं वक्तुमर्हसि राघवे॥', 'uttaraṃ punar evāha niścitya manasā tadā
hanūman mama vṛttāntaṃ vaktum arhasi rāghave', null, 5056087),
('ramayana-5-56-88', 88, 'Sundara Kanda, Sarga 56, Verse 88', 'यथा श्रुत्वैव नचिरात्तावुभौ रामलक्ष्मणौ।
सुग्रीवसहितौ वीरावुपेयातां तथा कुरु॥', 'yathā śrutvaiva nacirāt tāv ubhau rāmalakṣmaṇau
sugrīvasahitau vīrāv upeyātāṃ tathā kuru', null, 5056088),
('ramayana-5-56-89', 89, 'Sundara Kanda, Sarga 56, Verse 89', 'यद्यन्यथा भवेदेतद्द्वौ मासौ जीवितं मम।
न मां द्रक्ष्यति काकुत्स्थो म्रिये साहमनाथवत्॥', 'yady anyathā bhaved etad dvau māsau jīvitaṃ mama
na māṃ drakṣyati kākutstho mriye sāham anāthavat', null, 5056089),
('ramayana-5-56-90', 90, 'Sundara Kanda, Sarga 56, Verse 90', 'तच्छ्रुत्वा करुणं वाक्यं क्रोधो मामभ्यवर्तत।
उत्तरं च मया दृष्टं कार्यशेषमनन्तरम्॥', 'tac chrutvā karuṇaṃ vākyaṃ krodho mām abhyavartata
uttaraṃ ca mayā dṛṣṭaṃ kāryaśeṣam anantaram', null, 5056090),
('ramayana-5-56-91', 91, 'Sundara Kanda, Sarga 56, Verse 91', 'ततोऽवर्धत मे कायस्तदा पर्वतसंनिभः।
युद्धकाङ्क्षी वनं तच्च विनाशयितुमारभे॥', 'tato ''vardhata me kāyas tadā parvatasaṃnibhaḥ
yuddhakāṅkṣī vanaṃ tac ca vināśayitum ārabhe', null, 5056091),
('ramayana-5-56-92', 92, 'Sundara Kanda, Sarga 56, Verse 92', 'तद्भग्नं वनषण्डं तु भ्रान्तत्रस्तमृगद्विजम्।
प्रतिबुद्धा निरीक्षन्ते राक्षस्यो विकृताननाः॥', 'tad bhagnaṃ vanaṣaṇḍaṃ tu bhrāntatrastamṛgadvijam
pratibuddhā nirīkṣante rākṣasyo vikṛtānanāḥ', null, 5056092),
('ramayana-5-56-93', 93, 'Sundara Kanda, Sarga 56, Verse 93', 'मां च दृष्ट्वा वने तस्मिन्समागम्य ततस्ततः।
ताः समभ्यागताः क्षिप्रं रावणायाचचक्षिरे॥', 'māṃ ca dṛṣṭvā vane tasmin samāgamya tatas tataḥ
tāḥ samabhyāgatāḥ kṣipraṃ rāvaṇāyācacakṣire', null, 5056093),
('ramayana-5-56-94', 94, 'Sundara Kanda, Sarga 56, Verse 94', 'राजन्वनमिदं दुर्गं तव भग्नं दुरात्मना।
वानरेण ह्यविज्ञाय तव वीर्यं महाबल॥', 'rājan vanam idaṃ durgaṃ tava bhagnaṃ durātmanā
vānareṇa hy avijñāya tava vīryaṃ mahābala', null, 5056094),
('ramayana-5-56-95', 95, 'Sundara Kanda, Sarga 56, Verse 95', 'दुर्बुद्धेस्तस्य राजेन्द्र तव विप्रियकारिणः।
वधमाज्ञापय क्षिप्रं यथासौ विलयं व्रजेत्॥', 'durbuddhes tasya rājendra tava vipriyakāriṇaḥ
vadham ājñāpaya kṣipraṃ yathāsau vilayaṃ vrajet', null, 5056095),
('ramayana-5-56-96', 96, 'Sundara Kanda, Sarga 56, Verse 96', 'तच्छ्रुत्वा राक्षसेन्द्रेण विसृष्टा भृशदुर्जयाः।
राक्षसाः किंकरा नाम रावणस्य मनोऽनुगाः॥', 'tac chrutvā rākṣasendreṇa visṛṣṭā bhṛśadurjayāḥ
rākṣasāḥ kiṃkarā nāma rāvaṇasya mano''nugāḥ', null, 5056096),
('ramayana-5-56-97', 97, 'Sundara Kanda, Sarga 56, Verse 97', 'तेषामशीतिसाहस्रं शूलमुद्गरपाणिनाम्।
मया तस्मिन्वनोद्देशे परिघेण निषूदितम्॥', 'teṣām aśītisāhasraṃ śūlamudgarapāṇinām
mayā tasmin vanoddeśe parigheṇa niṣūditam', null, 5056097),
('ramayana-5-56-98', 98, 'Sundara Kanda, Sarga 56, Verse 98', 'तेषां तु हतशेषा ये ते गता लघुविक्रमाः।
निहतं च मया सैन्यं रावणायाचचक्षिरे॥', 'teṣāṃ tu hataśeṣā ye te gatā laghuvikramāḥ
nihataṃ ca mayā sainyaṃ rāvaṇāyācacakṣire', null, 5056098),
('ramayana-5-56-99', 99, 'Sundara Kanda, Sarga 56, Verse 99', 'ततो मे बुद्धिरुत्पन्ना चैत्यप्रासादमाक्रमम्॥', 'tato me buddhir utpannā caityaprāsādam ākramam', null, 5056099),
('ramayana-5-56-100', 100, 'Sundara Kanda, Sarga 56, Verse 100', 'तत्रस्थान्राक्षसान्हत्वा शतं स्तम्भेन वै पुनः।
ललाम भूतो लङ्काया मया विध्वंसितो रुषा॥', 'tatrasthān rākṣasān hatvā śataṃ stambhena vai punaḥ
lalāma bhūto laṅkāyā mayā vidhvaṃsito ruṣā', null, 5056100),
('ramayana-5-56-101', 101, 'Sundara Kanda, Sarga 56, Verse 101', 'ततः प्रहस्तस्य सुतं जम्बुमालिनमादिशत्॥', 'tataḥ prahastasya sutaṃ jambumālinam ādiśat', null, 5056101),
('ramayana-5-56-102', 102, 'Sundara Kanda, Sarga 56, Verse 102', 'तमहं बलसंपन्नं राक्षसं रणकोविदम्।
परिघेणातिघोरेण सूदयामि सहानुगम्॥', 'tam ahaṃ balasaṃpannaṃ rākṣasaṃ raṇakovidam
parigheṇātighoreṇa sūdayāmi sahānugam', null, 5056102),
('ramayana-5-56-103', 103, 'Sundara Kanda, Sarga 56, Verse 103', 'तच्छ्रुत्वा राक्षसेन्द्रस्तु मन्त्रिपुत्रान्महाबलान्।
पदातिबलसंपन्नान्प्रेषयामास रावणः।
परिघेणैव तान्सर्वान्नयामि यमसादनम्॥', 'tac chrutvā rākṣasendras tu mantriputrān mahābalān
padātibalasaṃpannān preṣayām āsa rāvaṇaḥ
parigheṇaiva tān sarvān nayāmi yamasādanam', null, 5056103),
('ramayana-5-56-104', 104, 'Sundara Kanda, Sarga 56, Verse 104', 'मन्त्रिपुत्रान्हताञ्श्रुत्वा समरे लघुविक्रमान्।
पञ्चसेनाग्रगाञ्शूरान्प्रेषयामास रावणः।
तानहं सह सैन्यान्वै सर्वानेवाभ्यसूदयम्॥', 'mantriputrān hatāñ śrutvā samare laghuvikramān
pañcasenāgragāñ śūrān preṣayām āsa rāvaṇaḥ
tān ahaṃ saha sainyān vai sarvān evābhyasūdayam', null, 5056104),
('ramayana-5-56-105', 105, 'Sundara Kanda, Sarga 56, Verse 105', 'ततः पुनर्दशग्रीवः पुत्रमक्षं महाबलम्।
बहुभी राकसैः सार्धं प्रेषयामास संयुगे॥', 'tataḥ punar daśagrīvaḥ putram akṣaṃ mahābalam
bahubhī rākasaiḥ sārdhaṃ preṣayām āsa saṃyuge', null, 5056105),
('ramayana-5-56-106', 106, 'Sundara Kanda, Sarga 56, Verse 106', 'तं तु मन्दोदरी पुत्रं कुमारं रणपण्डितम्।
सहसा खं समुत्क्रान्तं पादयोश्च गृहीतवान्।
चर्मासिनं शतगुणं भ्रामयित्वा व्यपेषयम्॥', 'taṃ tu mandodarī putraṃ kumāraṃ raṇapaṇḍitam
sahasā khaṃ samutkrāntaṃ pādayoś ca gṛhītavān
carmāsinaṃ śataguṇaṃ bhrāmayitvā vyapeṣayam', null, 5056106),
('ramayana-5-56-107', 107, 'Sundara Kanda, Sarga 56, Verse 107', 'तमक्षमागतं भग्नं निशम्य स दशाननः।
तत इन्द्रजितं नाम द्वितीयं रावणः सुतम्।
व्यादिदेश सुसंक्रुद्धो बलिनं युद्धदुर्मदम्॥', 'tam akṣam āgataṃ bhagnaṃ niśamya sa daśānanaḥ
tata indrajitaṃ nāma dvitīyaṃ rāvaṇaḥ sutam
vyādideśa susaṃkruddho balinaṃ yuddhadurmadam', null, 5056107),
('ramayana-5-56-108', 108, 'Sundara Kanda, Sarga 56, Verse 108', 'तस्याप्यहं बलं सर्वं तं च राक्षसपुंगवम्।
नष्टौजसं रणे कृत्वा परं हर्षमुपागमम्॥', 'tasyāpy ahaṃ balaṃ sarvaṃ taṃ ca rākṣasapuṃgavam
naṣṭaujasaṃ raṇe kṛtvā paraṃ harṣam upāgamam', null, 5056108),
('ramayana-5-56-109', 109, 'Sundara Kanda, Sarga 56, Verse 109', 'महता हि महाबाहुः प्रत्ययेन महाबलः।
प्रेषितो रावणेनैष सह वीरैर्मदोत्कटैः॥', 'mahatā hi mahābāhuḥ pratyayena mahābalaḥ
preṣito rāvaṇenaiṣa saha vīrair madotkaṭaiḥ', null, 5056109),
('ramayana-5-56-110', 110, 'Sundara Kanda, Sarga 56, Verse 110', 'ब्राह्मेणास्त्रेण स तु मां प्रबध्नाच्चातिवेगतः।
रज्जूभिरभिबध्नन्ति ततो मां तत्र राक्षसाः॥', 'brāhmeṇāstreṇa sa tu māṃ prabadhnāc cātivegataḥ
rajjūbhir abhibadhnanti tato māṃ tatra rākṣasāḥ', null, 5056110),
('ramayana-5-56-111', 111, 'Sundara Kanda, Sarga 56, Verse 111', 'रावणस्य समीपं च गृहीत्वा मामुपानयन्।
दृष्ट्वा संभाषितश्चाहं रावणेन दुरात्मना॥', 'rāvaṇasya samīpaṃ ca gṛhītvā mām upānayan
dṛṣṭvā saṃbhāṣitaś cāhaṃ rāvaṇena durātmanā', null, 5056111),
('ramayana-5-56-112', 112, 'Sundara Kanda, Sarga 56, Verse 112', 'पृष्टश्च लङ्कागमनं राक्षसानां च तद्वधम्।
तत्सर्वं च मया तत्र सीतार्थमिति जल्पितम्॥', 'pṛṣṭaś ca laṅkāgamanaṃ rākṣasānāṃ ca tad vadham
tat sarvaṃ ca mayā tatra sītārtham iti jalpitam', null, 5056112),
('ramayana-5-56-113', 113, 'Sundara Kanda, Sarga 56, Verse 113', 'अस्याहं दर्शनाकाङ्क्षी प्राप्तस्त्वद्भवनं विभो।
मारुतस्यौरसः पुत्रो वानरो हनुमानहम्॥', 'asyāhaṃ darśanākāṅkṣī prāptas tvadbhavanaṃ vibho
mārutasyaurasaḥ putro vānaro hanumān aham', null, 5056113),
('ramayana-5-56-114', 114, 'Sundara Kanda, Sarga 56, Verse 114', 'रामदूतं च मां विद्धि सुग्रीवसचिवं कपिम्।
सोऽहं दौत्येन रामस्य त्वत्समीपमिहागतः॥', 'rāmadūtaṃ ca māṃ viddhi sugrīvasacivaṃ kapim
so ''haṃ dautyena rāmasya tvatsamīpam ihāgataḥ', null, 5056114),
('ramayana-5-56-115', 115, 'Sundara Kanda, Sarga 56, Verse 115', 'शृणु चापि समादेशं यदहं प्रब्रवीमि ते।
राक्षसेश हरीशस्त्वां वाक्यमाह समाहितम्।
धर्मार्थकामसहितं हितं पथ्यमिवाशनम्॥', 'śṛṇu cāpi samādeśaṃ yad ahaṃ prabravīmi te
rākṣaseśa harīśas tvāṃ vākyam āha samāhitam
dharmārthakāmasahitaṃ hitaṃ pathyam ivāśanam', null, 5056115),
('ramayana-5-56-116', 116, 'Sundara Kanda, Sarga 56, Verse 116', 'वसतो ऋष्यमूके मे पर्वते विपुलद्रुमे।
राघवो रणविक्रान्तो मित्रत्वं समुपागतः॥', 'vasato ṛṣyamūke me parvate vipuladrume
rāghavo raṇavikrānto mitratvaṃ samupāgataḥ', null, 5056116),
('ramayana-5-56-117', 117, 'Sundara Kanda, Sarga 56, Verse 117', 'तेन मे कथितं राजन्भार्या मे रक्षसा हृता।
तत्र साहाय्यहेतोर्मे समयं कर्तुमर्हसि॥', 'tena me kathitaṃ rājan bhāryā me rakṣasā hṛtā
tatra sāhāyyahetor me samayaṃ kartum arhasi', null, 5056117),
('ramayana-5-56-118', 118, 'Sundara Kanda, Sarga 56, Verse 118', 'वालिना हृतराज्येन सुग्रीवेण सह प्रभुः।
चक्रेऽग्निसाक्षिकं सक्यं राघवः सहलक्ष्मणः॥', 'vālinā hṛtarājyena sugrīveṇa saha prabhuḥ
cakre ''gnisākṣikaṃ sakyaṃ rāghavaḥ sahalakṣmaṇaḥ', null, 5056118),
('ramayana-5-56-119', 119, 'Sundara Kanda, Sarga 56, Verse 119', 'तेन वालिनमुत्साद्य शरेणैकेन संयुगे।
वानराणां महाराजः कृतः संप्लवतां प्रभुः॥', 'tena vālinam utsādya śareṇaikena saṃyuge
vānarāṇāṃ mahārājaḥ kṛtaḥ saṃplavatāṃ prabhuḥ', null, 5056119),
('ramayana-5-56-120', 120, 'Sundara Kanda, Sarga 56, Verse 120', 'तस्य साहाय्यमस्माभिः कार्यं सर्वात्मना त्विह।
तेन प्रस्थापितस्तुभ्यं समीपमिह धर्मतः॥', 'tasya sāhāyyam asmābhiḥ kāryaṃ sarvātmanā tv iha
tena prasthāpitas tubhyaṃ samīpam iha dharmataḥ', null, 5056120),
('ramayana-5-56-121', 121, 'Sundara Kanda, Sarga 56, Verse 121', 'क्षिप्रमानीयतां सीता दीयतां राघवस्य च।
यावन्न हरयो वीरा विधमन्ति बलं तव॥', 'kṣipram ānīyatāṃ sītā dīyatāṃ rāghavasya ca
yāvan na harayo vīrā vidhamanti balaṃ tava', null, 5056121),
('ramayana-5-56-122', 122, 'Sundara Kanda, Sarga 56, Verse 122', 'वानराणां प्रभवो हि न केन विदितः पुरा।
देवतानां सकाशं च ये गच्छन्ति निमन्त्रिताः॥', 'vānarāṇāṃ prabhavo hi na kena viditaḥ purā
devatānāṃ sakāśaṃ ca ye gacchanti nimantritāḥ', null, 5056122),
('ramayana-5-56-123', 123, 'Sundara Kanda, Sarga 56, Verse 123', 'इति वानरराजस्त्वामाहेत्यभिहितो मया।
मामैक्षत ततो रुष्टश्चक्षुषा प्रदहन्निव॥', 'iti vānararājas tvām āhety abhihito mayā
mām aikṣata tato ruṣṭaś cakṣuṣā pradahann iva', null, 5056123),
('ramayana-5-56-124', 124, 'Sundara Kanda, Sarga 56, Verse 124', 'तेन वध्योऽहमाज्ञप्तो रक्षसा रौद्रकर्मणा॥', 'tena vadhyo ''ham ājñapto rakṣasā raudrakarmaṇā', null, 5056124),
('ramayana-5-56-125', 125, 'Sundara Kanda, Sarga 56, Verse 125', 'ततो विभीषणो नाम तस्य भ्राता महामतिः।
तेन राक्षसराजोऽसौ याचितो मम कारणात्॥', 'tato vibhīṣaṇo nāma tasya bhrātā mahāmatiḥ
tena rākṣasarājo ''sau yācito mama kāraṇāt', null, 5056125),
('ramayana-5-56-126', 126, 'Sundara Kanda, Sarga 56, Verse 126', 'दूतवध्या न दृष्टा हि राजशास्त्रेषु राक्षस।
दूतेन वेदितव्यं च यथार्थं हितवादिना॥', 'dūtavadhyā na dṛṣṭā hi rājaśāstreṣu rākṣasa
dūtena veditavyaṃ ca yathārthaṃ hitavādinā', null, 5056126),
('ramayana-5-56-127', 127, 'Sundara Kanda, Sarga 56, Verse 127', 'सुमहत्यपराधेऽपि दूतस्यातुलविक्रमः।
विरूपकरणं दृष्टं न वधोऽस्तीह शास्त्रतः॥', 'sumahaty aparādhe ''pi dūtasyātulavikramaḥ
virūpakaraṇaṃ dṛṣṭaṃ na vadho ''stīha śāstrataḥ', null, 5056127),
('ramayana-5-56-128', 128, 'Sundara Kanda, Sarga 56, Verse 128', 'विभीषणेनैवमुक्तो रावणः संदिदेश तान्।
राक्षसानेतदेवाद्य लाङ्गूलं दह्यतामिति॥', 'vibhīṣaṇenaivam ukto rāvaṇaḥ saṃdideśa tān
rākṣasān etad evādya lāṅgūlaṃ dahyatām iti', null, 5056128),
('ramayana-5-56-129', 129, 'Sundara Kanda, Sarga 56, Verse 129', 'ततस्तस्य वचः श्रुत्वा मम पुच्छं समन्ततः।
वेष्टितं शणवल्कैश्च पटैः कार्पासकैस्तथा॥', 'tatas tasya vacaḥ śrutvā mama pucchaṃ samantataḥ
veṣṭitaṃ śaṇavalkaiś ca paṭaiḥ kārpāsakais tathā', null, 5056129),
('ramayana-5-56-130', 130, 'Sundara Kanda, Sarga 56, Verse 130', 'राक्षसाः सिद्धसंनाहास्ततस्ते चण्डविक्रमाः।
तदादीप्यन्त मे पुच्छं हनन्तः काष्ठमुष्टिभिः॥', 'rākṣasāḥ siddhasaṃnāhās tatas te caṇḍavikramāḥ
tad ādīpyanta me pucchaṃ hanantaḥ kāṣṭhamuṣṭibhiḥ', null, 5056130),
('ramayana-5-56-131', 131, 'Sundara Kanda, Sarga 56, Verse 131', 'बद्धस्य बहुभिः पाशैर्यन्त्रितस्य च राक्षसैः।
न मे पीडा भवेत्का चिद्दिदृक्षोर्नगरीं दिवा॥', 'baddhasya bahubhiḥ pāśair yantritasya ca rākṣasaiḥ
na me pīḍā bhavet kā cid didṛkṣor nagarīṃ divā', null, 5056131),
('ramayana-5-56-132', 132, 'Sundara Kanda, Sarga 56, Verse 132', 'ततस्ते राक्षसाः शूरा बद्धं मामग्निसंवृतम्।
अघोषयन्राजमार्गे नगरद्वारमागताः॥', 'tatas te rākṣasāḥ śūrā baddhaṃ mām agnisaṃvṛtam
aghoṣayan rājamārge nagaradvāram āgatāḥ', null, 5056132),
('ramayana-5-56-133', 133, 'Sundara Kanda, Sarga 56, Verse 133', 'ततोऽहं सुमहद्रूपं संक्षिप्य पुनरात्मनः।
विमोचयित्वा तं बन्धं प्रकृतिष्ठः स्थितः पुनः॥', 'tato ''haṃ sumahad rūpaṃ saṃkṣipya punar ātmanaḥ
vimocayitvā taṃ bandhaṃ prakṛtiṣṭhaḥ sthitaḥ punaḥ', null, 5056133),
('ramayana-5-56-134', 134, 'Sundara Kanda, Sarga 56, Verse 134', 'आयसं परिघं गृह्य तानि रक्षांस्यसूदयम्।
ततस्तन्नगरद्वारं वेगेनाप्लुतवानहम्॥', 'āyasaṃ parighaṃ gṛhya tāni rakṣāṃsy asūdayam
tatas tan nagaradvāraṃ vegenāplutavān aham', null, 5056134),
('ramayana-5-56-135', 135, 'Sundara Kanda, Sarga 56, Verse 135', 'पुच्छेन च प्रदीप्तेन तां पुरीं साट्टगोपुराम्।
दहाम्यहमसंभ्रान्तो युगान्ताग्निरिव प्रजाः॥', 'pucchena ca pradīptena tāṃ purīṃ sāṭṭagopurām
dahāmy aham asaṃbhrānto yugāntāgnir iva prajāḥ', null, 5056135),
('ramayana-5-56-136', 136, 'Sundara Kanda, Sarga 56, Verse 136', 'दग्ध्वा लङ्कां पुनश्चैव शङ्का मामभ्यवर्तत।
दहता च मया लङ्कां दग्धा सीता न संशयः॥', 'dagdhvā laṅkāṃ punaś caiva śaṅkā mām abhyavartata
dahatā ca mayā laṅkāṃ dagdhā sītā na saṃśayaḥ', null, 5056136),
('ramayana-5-56-137', 137, 'Sundara Kanda, Sarga 56, Verse 137', 'अथाहं वाचमश्रौषं चारणानां शुभाक्षराम्।
जानकी न च दग्धेति विस्मयोदन्तभाषिणाम्॥', 'athāhaṃ vācam aśrauṣaṃ cāraṇānāṃ śubhākṣarām
jānakī na ca dagdheti vismayodantabhāṣiṇām', null, 5056137),
('ramayana-5-56-138', 138, 'Sundara Kanda, Sarga 56, Verse 138', 'ततो मे बुद्धिरुत्पन्ना श्रुत्वा तामद्भुतां गिरम्।
पुनर्दृष्टा च वैदेही विसृष्टश्च तया पुनः॥', 'tato me buddhir utpannā śrutvā tām adbhutāṃ giram
punar dṛṣṭā ca vaidehī visṛṣṭaś ca tayā punaḥ', null, 5056138),
('ramayana-5-56-139', 139, 'Sundara Kanda, Sarga 56, Verse 139', 'राघवस्य प्रभावेन भवतां चैव तेजसा।
सुग्रीवस्य च कार्यार्थं मया सर्वमनुष्ठितम्॥', 'rāghavasya prabhāvena bhavatāṃ caiva tejasā
sugrīvasya ca kāryārthaṃ mayā sarvam anuṣṭhitam', null, 5056139),
('ramayana-5-56-140', 140, 'Sundara Kanda, Sarga 56, Verse 140', 'एतत्सर्वं मया तत्र यथावदुपपादितम्।
अत्र यन्न कृतं शेषं तत्सर्वं क्रियतामिति॥', 'etat sarvaṃ mayā tatra yathāvad upapāditam
atra yan na kṛtaṃ śeṣaṃ tat sarvaṃ kriyatām iti', null, 5056140)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 57 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-57-1', 1, 'Sundara Kanda, Sarga 57, Verse 1', 'एतदाख्यानं तत्सर्वं हनूमान्मारुतात्मजः।
भूयः समुपचक्राम वचनं वक्तुमुत्तरम्॥', 'etad ākhyānaṃ tat sarvaṃ hanūmān mārutātmajaḥ
bhūyaḥ samupacakrāma vacanaṃ vaktum uttaram', null, 5057001),
('ramayana-5-57-2', 2, 'Sundara Kanda, Sarga 57, Verse 2', 'सफलो राघवोद्योगः सुग्रीवस्य च संभ्रमः।
शीलमासाद्य सीताया मम च प्लवनं महत्॥', 'saphalo rāghavodyogaḥ sugrīvasya ca saṃbhramaḥ
śīlam āsādya sītāyā mama ca plavanaṃ mahat', null, 5057002),
('ramayana-5-57-3', 3, 'Sundara Kanda, Sarga 57, Verse 3', 'आर्यायाः सदृशं शीलं सीतायाः प्लवगर्षभाः।
तपसा धारयेल्लोकान्क्रुद्धा वा निर्दहेदपि॥', 'āryāyāḥ sadṛśaṃ śīlaṃ sītāyāḥ plavagarṣabhāḥ
tapasā dhārayel lokān kruddhā vā nirdahed api', null, 5057003),
('ramayana-5-57-4', 4, 'Sundara Kanda, Sarga 57, Verse 4', 'सर्वथातिप्रवृद्धोऽसौ रावणो राक्षसाधिपः।
यस्य तां स्पृशतो गात्रं तपसा न विनाशितम्॥', 'sarvathātipravṛddho ''sau rāvaṇo rākṣasādhipaḥ
yasya tāṃ spṛśato gātraṃ tapasā na vināśitam', null, 5057004),
('ramayana-5-57-5', 5, 'Sundara Kanda, Sarga 57, Verse 5', 'न तदग्निशिखा कुर्यात्संस्पृष्टा पाणिना सती।
जनकस्यात्मजा कुर्यादुत्क्रोधकलुषीकृता॥', 'na tad agniśikhā kuryāt saṃspṛṣṭā pāṇinā satī
janakasyātmajā kuryād utkrodhakaluṣīkṛtā', null, 5057005),
('ramayana-5-57-6', 6, 'Sundara Kanda, Sarga 57, Verse 6', 'अशोकवनिकामध्ये रावणस्य दुरात्मनः।
अधस्ताच्छिंशपावृक्षे साध्वी करुणमास्थिता॥', 'aśokavanikāmadhye rāvaṇasya durātmanaḥ
adhastāc chiṃśapāvṛkṣe sādhvī karuṇam āsthitā', null, 5057006),
('ramayana-5-57-7', 7, 'Sundara Kanda, Sarga 57, Verse 7', 'राक्षसीभिः परिवृता शोकसंतापकर्शिता।
मेघलेखापरिवृता चन्द्रलेखेव निष्प्रभा॥', 'rākṣasībhiḥ parivṛtā śokasaṃtāpakarśitā
meghalekhāparivṛtā candralekheva niṣprabhā', null, 5057007),
('ramayana-5-57-8', 8, 'Sundara Kanda, Sarga 57, Verse 8', 'अचिन्तयन्ती वैदेही रावणं बलदर्पितम्।
पतिव्रता च सुश्रोणी अवष्टब्धा च जानकी॥', 'acintayantī vaidehī rāvaṇaṃ baladarpitam
pativratā ca suśroṇī avaṣṭabdhā ca jānakī', null, 5057008),
('ramayana-5-57-9', 9, 'Sundara Kanda, Sarga 57, Verse 9', 'अनुरक्ता हि वैदेही रामं सर्वात्मना शुभा।
अनन्यचित्ता रामे च पौलोमीव पुरंदरे॥', 'anuraktā hi vaidehī rāmaṃ sarvātmanā śubhā
ananyacittā rāme ca paulomīva puraṃdare', null, 5057009),
('ramayana-5-57-10', 10, 'Sundara Kanda, Sarga 57, Verse 10', 'तदेकवासःसंवीता रजोध्वस्ता तथैव च।
शोकसंतापदीनाङ्गी सीता भर्तृहिते रता॥', 'tad ekavāsaḥsaṃvītā rajodhvastā tathaiva ca
śokasaṃtāpadīnāṅgī sītā bhartṛhite ratā', null, 5057010),
('ramayana-5-57-11', 11, 'Sundara Kanda, Sarga 57, Verse 11', 'सा मया राक्षसी मध्ये तर्ज्यमाना मुहुर्मुहुः।
राक्षसीभिर्विरूपाभिर्दृष्टा हि प्रमदा वने॥', 'sā mayā rākṣasī madhye tarjyamānā muhur muhuḥ
rākṣasībhir virūpābhir dṛṣṭā hi pramadā vane', null, 5057011),
('ramayana-5-57-12', 12, 'Sundara Kanda, Sarga 57, Verse 12', 'एकवेणीधरा दीना भर्तृचिन्तापरायणा।
अधःशय्या विवर्णाङ्गी पद्मिनीव हिमागमे॥', 'ekaveṇīdharā dīnā bhartṛcintāparāyaṇā
adhaḥśayyā vivarṇāṅgī padminīva himāgame', null, 5057012),
('ramayana-5-57-13', 13, 'Sundara Kanda, Sarga 57, Verse 13', 'रावणाद्विनिवृत्तार्था मर्तव्यकृतनिश्चया।
कथं चिन्मृगशावाक्षी विश्वासमुपपादिता॥', 'rāvaṇād vinivṛttārthā martavyakṛtaniścayā
kathaṃ cin mṛgaśāvākṣī viśvāsam upapāditā', null, 5057013),
('ramayana-5-57-14', 14, 'Sundara Kanda, Sarga 57, Verse 14', 'ततः संभाषिता चैव सर्वमर्थं च दर्शिता।
रामसुग्रीवसख्यं च श्रुत्वा प्रीतिमुपागता॥', 'tataḥ saṃbhāṣitā caiva sarvam arthaṃ ca darśitā
rāmasugrīvasakhyaṃ ca śrutvā prītim upāgatā', null, 5057014),
('ramayana-5-57-15', 15, 'Sundara Kanda, Sarga 57, Verse 15', 'नियतः समुदाचारो भक्तिर्भर्तरि चोत्तमा॥', 'niyataḥ samudācāro bhaktir bhartari cottamā', null, 5057015),
('ramayana-5-57-16', 16, 'Sundara Kanda, Sarga 57, Verse 16', 'यन्न हन्ति दशग्रीवं स महात्मा दशाननः।
निमित्तमात्रं रामस्तु वधे तस्य भविष्यति॥', 'yan na hanti daśagrīvaṃ sa mahātmā daśānanaḥ
nimittamātraṃ rāmas tu vadhe tasya bhaviṣyati', null, 5057016),
('ramayana-5-57-17', 17, 'Sundara Kanda, Sarga 57, Verse 17', 'एवमास्ते महाभागा सीता शोकपरायणा।
यदत्र प्रतिकर्तव्यं तत्सर्वमुपपाद्यताम्॥', 'evam āste mahābhāgā sītā śokaparāyaṇā
yad atra pratikartavyaṃ tat sarvam upapādyatām', null, 5057017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 58 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-58-1', 1, 'Sundara Kanda, Sarga 58, Verse 1', 'तस्य तद्वचनं श्रुत्वा वालिसूनुरभाषत।
जाम्बवत्प्रमुखान्सर्वाननुज्ञाप्य महाकपीन्॥', 'tasya tad vacanaṃ śrutvā vālisūnur abhāṣata
jāmbavatpramukhān sarvān anujñāpya mahākapīn', null, 5058001),
('ramayana-5-58-2', 2, 'Sundara Kanda, Sarga 58, Verse 2', 'अस्मिन्नेवंगते कार्ये भवतां च निवेदिते।
न्याय्यं स्म सह वैदेह्या द्रष्टुं तौ पार्थिवात्मजौ॥', 'asminn evaṃgate kārye bhavatāṃ ca nivedite
nyāyyaṃ sma saha vaidehyā draṣṭuṃ tau pārthivātmajau', null, 5058002),
('ramayana-5-58-3', 3, 'Sundara Kanda, Sarga 58, Verse 3', 'अहमेकोऽपि पर्याप्तः सराक्षसगणां पुरीम्।
तां लङ्कां तरसा हन्तुं रावणं च महाबलम्॥', 'aham eko ''pi paryāptaḥ sarākṣasagaṇāṃ purīm
tāṃ laṅkāṃ tarasā hantuṃ rāvaṇaṃ ca mahābalam', null, 5058003),
('ramayana-5-58-4', 4, 'Sundara Kanda, Sarga 58, Verse 4', 'किं पुनः सहितो वीरैर्बलवद्भिः कृतात्मभिः।
कृतास्त्रैः प्लवगैः शक्तैर्भवद्भिर्विजयैषिभिः॥', 'kiṃ punaḥ sahito vīrair balavadbhiḥ kṛtātmabhiḥ
kṛtāstraiḥ plavagaiḥ śaktair bhavadbhir vijayaiṣibhiḥ', null, 5058004),
('ramayana-5-58-5', 5, 'Sundara Kanda, Sarga 58, Verse 5', 'अहं तु रावणं युद्धे ससैन्यं सपुरःसरम्।
सपुत्रं विधमिष्यामि सहोदरयुतं युधि॥', 'ahaṃ tu rāvaṇaṃ yuddhe sasainyaṃ sapuraḥsaram
saputraṃ vidhamiṣyāmi sahodarayutaṃ yudhi', null, 5058005),
('ramayana-5-58-6', 6, 'Sundara Kanda, Sarga 58, Verse 6', 'ब्राह्ममैन्द्रं च रौद्रं च वायव्यं वारुणं तथा।
यदि शक्रजितोऽस्त्राणि दुर्निरीक्ष्याणि संयुगे।
तान्यहं विधमिष्यामि निहनिष्यामि राक्षसान्॥', 'brāhmam aindraṃ ca raudraṃ ca vāyavyaṃ vāruṇaṃ tathā
yadi śakrajito ''strāṇi durnirīkṣyāṇi saṃyuge
tāny ahaṃ vidhamiṣyāmi nihaniṣyāmi rākṣasān', null, 5058006),
('ramayana-5-58-7', 7, 'Sundara Kanda, Sarga 58, Verse 7', 'भवतामभ्यनुज्ञातो विक्रमो मे रुणद्धि तम्॥', 'bhavatām abhyanujñāto vikramo me ruṇaddhi tam', null, 5058007),
('ramayana-5-58-8', 8, 'Sundara Kanda, Sarga 58, Verse 8', 'मयातुला विसृष्टा हि शैलवृष्टिर्निरन्तरा।
देवानपि रणे हन्यात्किं पुनस्तान्निशाचरान्॥', 'mayātulā visṛṣṭā hi śailavṛṣṭir nirantarā
devān api raṇe hanyāt kiṃ punas tān niśācarān', null, 5058008),
('ramayana-5-58-9', 9, 'Sundara Kanda, Sarga 58, Verse 9', 'सागरोऽप्यतियाद्वेलां मन्दरः प्रचलेदपि।
न जाम्बवन्तं समरे कम्पयेदरिवाहिनी॥', 'sāgaro ''py atiyād velāṃ mandaraḥ pracaled api
na jāmbavantaṃ samare kampayed arivāhinī', null, 5058009),
('ramayana-5-58-10', 10, 'Sundara Kanda, Sarga 58, Verse 10', 'सर्वराक्षससंघानां राक्षसा ये च पूर्वकाः।
अलमेको विनाशाय वीरो वायुसुतः कपिः॥', 'sarvarākṣasasaṃghānāṃ rākṣasā ye ca pūrvakāḥ
alam eko vināśāya vīro vāyusutaḥ kapiḥ', null, 5058010),
('ramayana-5-58-11', 11, 'Sundara Kanda, Sarga 58, Verse 11', 'पनसस्योरुवेगेन नीलस्य च महात्मनः।
मन्दरोऽप्यवशीर्येत किं पुनर्युधि राक्षसाः॥', 'panasasyoruvegena nīlasya ca mahātmanaḥ
mandaro ''py avaśīryeta kiṃ punar yudhi rākṣasāḥ', null, 5058011),
('ramayana-5-58-12', 12, 'Sundara Kanda, Sarga 58, Verse 12', 'सदेवासुरयुद्धेषु गन्धर्वोरगपक्षिषु।
मैन्दस्य प्रतियोद्धारं शंसत द्विविदस्य वा॥', 'sadevāsurayuddheṣu gandharvoragapakṣiṣu
maindasya pratiyoddhāraṃ śaṃsata dvividasya vā', null, 5058012),
('ramayana-5-58-13', 13, 'Sundara Kanda, Sarga 58, Verse 13', 'अश्विपुत्रौ महावेगावेतौ प्लवगसत्तमौ।
पितामहवरोत्सेकात्परमं दर्पमास्थितौ॥', 'aśviputrau mahāvegāv etau plavagasattamau
pitāmahavarotsekāt paramaṃ darpam āsthitau', null, 5058013),
('ramayana-5-58-14', 14, 'Sundara Kanda, Sarga 58, Verse 14', 'अश्विनोर्माननार्थं हि सर्वलोकपितामहः।
सर्वावध्यत्वमतुलमनयोर्दत्तवान्पुरा॥', 'aśvinor mānanārthaṃ hi sarvalokapitāmahaḥ
sarvāvadhyatvam atulam anayor dattavān purā', null, 5058014),
('ramayana-5-58-15', 15, 'Sundara Kanda, Sarga 58, Verse 15', 'वरोत्सेकेन मत्तौ च प्रमथ्य महतीं चमूम्।
सुराणाममृतं वीरौ पीतवन्तौ प्लवंगमौ॥', 'varotsekena mattau ca pramathya mahatīṃ camūm
surāṇām amṛtaṃ vīrau pītavantau plavaṃgamau', null, 5058015),
('ramayana-5-58-16', 16, 'Sundara Kanda, Sarga 58, Verse 16', 'एतावेव हि संक्रुद्धौ सवाजिरथकुञ्जराम्।
लङ्कां नाशयितुं शक्तौ सर्वे तिष्ठन्तु वानराः॥', 'etāv eva hi saṃkruddhau savājirathakuñjarām
laṅkāṃ nāśayituṃ śaktau sarve tiṣṭhantu vānarāḥ', null, 5058016),
('ramayana-5-58-17', 17, 'Sundara Kanda, Sarga 58, Verse 17', 'अयुक्तं तु विना देवीं दृष्टबद्भिः प्लवंगमाः।
समीपं गन्तुमस्माभी राघवस्य महात्मनः॥', 'ayuktaṃ tu vinā devīṃ dṛṣṭabadbhiḥ plavaṃgamāḥ
samīpaṃ gantum asmābhī rāghavasya mahātmanaḥ', null, 5058017),
('ramayana-5-58-18', 18, 'Sundara Kanda, Sarga 58, Verse 18', 'दृष्टा देवी न चानीता इति तत्र निवेदनम्।
अयुक्तमिव पश्यामि भवद्भिः ख्यातविक्रमैः॥', 'dṛṣṭā devī na cānītā iti tatra nivedanam
ayuktam iva paśyāmi bhavadbhiḥ khyātavikramaiḥ', null, 5058018),
('ramayana-5-58-19', 19, 'Sundara Kanda, Sarga 58, Verse 19', 'न हि वः प्लवते कश्चिन्नापि कश्चित्पराक्रमे।
तुल्यः सामरदैत्येषु लोकेषु हरिसत्तमाः॥', 'na hi vaḥ plavate kaś cin nāpi kaś cit parākrame
tulyaḥ sāmaradaityeṣu lokeṣu harisattamāḥ', null, 5058019),
('ramayana-5-58-20', 20, 'Sundara Kanda, Sarga 58, Verse 20', 'तेष्वेवं हतवीरेषु राक्षसेषु हनूमता।
किमन्यदत्र कर्तव्यं गृहीत्वा याम जानकीम्॥', 'teṣv evaṃ hatavīreṣu rākṣaseṣu hanūmatā
kim anyad atra kartavyaṃ gṛhītvā yāma jānakīm', null, 5058020),
('ramayana-5-58-21', 21, 'Sundara Kanda, Sarga 58, Verse 21', 'तमेवं कृतसंकल्पं जाम्बवान्हरिसत्तमः।
उवाच परमप्रीतो वाक्यमर्थवदर्थवित्॥', 'tam evaṃ kṛtasaṃkalpaṃ jāmbavān harisattamaḥ
uvāca paramaprīto vākyam arthavad arthavit', null, 5058021),
('ramayana-5-58-22', 22, 'Sundara Kanda, Sarga 58, Verse 22', 'न तावदेषा मतिरक्षमा नो यथा भवान्पश्यति राजपुत्र।
यथा तु रामस्य मतिर्निविष्टा तथा भवान्पश्यतु कार्यसिद्धिम्॥', 'na tāvad eṣā matir akṣamā no yathā bhavān paśyati rājaputra
yathā tu rāmasya matir niviṣṭā tathā bhavān paśyatu kāryasiddhim', null, 5058022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 59 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-59-1', 1, 'Sundara Kanda, Sarga 59, Verse 1', 'ततो जाम्बवतो वाक्यमगृह्णन्त वनौकसः।
अङ्गदप्रमुखा वीरा हनूमांश्च महाकपिः॥', 'tato jāmbavato vākyam agṛhṇanta vanaukasaḥ
aṅgadapramukhā vīrā hanūmāṃś ca mahākapiḥ', null, 5059001),
('ramayana-5-59-2', 2, 'Sundara Kanda, Sarga 59, Verse 2', 'प्रीतिमन्तस्ततः सर्वे वायुपुत्रपुरःसराः।
महेन्द्राग्रं परित्यज्य पुप्लुवुः प्लवगर्षभाः॥', 'prītimantas tataḥ sarve vāyuputrapuraḥsarāḥ
mahendrāgraṃ parityajya pupluvuḥ plavagarṣabhāḥ', null, 5059002),
('ramayana-5-59-3', 3, 'Sundara Kanda, Sarga 59, Verse 3', 'मेरुमन्दरसंकाशा मत्ता इव महागजाः।
छादयन्त इवाकाशं महाकाया महाबलाः॥', 'merumandarasaṃkāśā mattā iva mahāgajāḥ
chādayanta ivākāśaṃ mahākāyā mahābalāḥ', null, 5059003),
('ramayana-5-59-4', 4, 'Sundara Kanda, Sarga 59, Verse 4', 'सभाज्यमानं भूतैस्तमात्मवन्तं महाबलम्।
हनूमन्तं महावेगं वहन्त इव दृष्टिभिः॥', 'sabhājyamānaṃ bhūtais tam ātmavantaṃ mahābalam
hanūmantaṃ mahāvegaṃ vahanta iva dṛṣṭibhiḥ', null, 5059004),
('ramayana-5-59-5', 5, 'Sundara Kanda, Sarga 59, Verse 5', 'राघवे चार्थनिर्वृत्तिं भर्तुश्च परमं यशः।
समाधाय समृद्धार्थाः कर्मसिद्धिभिरुन्नताः॥', 'rāghave cārthanirvṛttiṃ bhartuś ca paramaṃ yaśaḥ
samādhāya samṛddhārthāḥ karmasiddhibhir unnatāḥ', null, 5059005),
('ramayana-5-59-6', 6, 'Sundara Kanda, Sarga 59, Verse 6', 'प्रियाख्यानोन्मुखाः सर्वे सर्वे युद्धाभिनन्दिनः।
सर्वे रामप्रतीकारे निश्चितार्था मनस्विनः॥', 'priyākhyānonmukhāḥ sarve sarve yuddhābhinandinaḥ
sarve rāmapratīkāre niścitārthā manasvinaḥ', null, 5059006),
('ramayana-5-59-7', 7, 'Sundara Kanda, Sarga 59, Verse 7', 'प्लवमानाः खमाप्लुत्य ततस्ते काननौक्षकः।
नन्दनोपममासेदुर्वनं द्रुमलतायुतम्॥', 'plavamānāḥ kham āplutya tatas te kānanaukṣakaḥ
nandanopamam āsedur vanaṃ drumalatāyutam', null, 5059007),
('ramayana-5-59-8', 8, 'Sundara Kanda, Sarga 59, Verse 8', 'यत्तन्मधुवनं नाम सुग्रीवस्याभिरक्षितम्।
अधृष्यं सर्वभूतानां सर्वभूतमनोहरम्॥', 'yat tan madhuvanaṃ nāma sugrīvasyābhirakṣitam
adhṛṣyaṃ sarvabhūtānāṃ sarvabhūtamanoharam', null, 5059008),
('ramayana-5-59-9', 9, 'Sundara Kanda, Sarga 59, Verse 9', 'यद्रक्षति महावीर्यः सदा दधिमुखः कपिः।
मातुलः कपिमुख्यस्य सुग्रीवस्य महात्मनः॥', 'yad rakṣati mahāvīryaḥ sadā dadhimukhaḥ kapiḥ
mātulaḥ kapimukhyasya sugrīvasya mahātmanaḥ', null, 5059009),
('ramayana-5-59-10', 10, 'Sundara Kanda, Sarga 59, Verse 10', 'ते तद्वनमुपागम्य बभूवुः परमोत्कटाः।
वानरा वानरेन्द्रस्य मनःकान्ततमं महत्॥', 'te tad vanam upāgamya babhūvuḥ paramotkaṭāḥ
vānarā vānarendrasya manaḥkāntatamaṃ mahat', null, 5059010),
('ramayana-5-59-11', 11, 'Sundara Kanda, Sarga 59, Verse 11', 'ततस्ते वानरा हृष्टा दृष्ट्वा मधुवनं महत्।
कुमारमभ्ययाचन्त मधूनि मधुपिङ्गलाः॥', 'tatas te vānarā hṛṣṭā dṛṣṭvā madhuvanaṃ mahat
kumāram abhyayācanta madhūni madhupiṅgalāḥ', null, 5059011),
('ramayana-5-59-12', 12, 'Sundara Kanda, Sarga 59, Verse 12', 'ततः कुमारस्तान्वृद्धाञ्जाम्बवत्प्रमुखान्कपीन्।
अनुमान्य ददौ तेषां निसर्गं मधुभक्षणे॥', 'tataḥ kumāras tān vṛddhāñ jāmbavatpramukhān kapīn
anumānya dadau teṣāṃ nisargaṃ madhubhakṣaṇe', null, 5059012),
('ramayana-5-59-13', 13, 'Sundara Kanda, Sarga 59, Verse 13', 'ततश्चानुमताः सर्वे संप्रहृष्टा वनौकसः।
मुदिताश्च ततस्ते च प्रनृत्यन्ति ततस्ततः॥', 'tataś cānumatāḥ sarve saṃprahṛṣṭā vanaukasaḥ
muditāś ca tatas te ca pranṛtyanti tatas tataḥ', null, 5059013),
('ramayana-5-59-14', 14, 'Sundara Kanda, Sarga 59, Verse 14', 'गायन्ति के चित्प्रणमन्ति के चिन्नृत्यन्ति के चित्प्रहसन्ति के चित्।
पतन्ति के चिद्विचरन्ति के चित्प्लवन्ति के चित्प्रलपन्ति के चित्॥', 'gāyanti ke cit praṇamanti ke cin nṛtyanti ke cit prahasanti ke cit
patanti ke cid vicaranti ke cit plavanti ke cit pralapanti ke cit', null, 5059014),
('ramayana-5-59-15', 15, 'Sundara Kanda, Sarga 59, Verse 15', 'परस्परं के चिदुपाश्रयन्ते परस्परं के चिदतिब्रुवन्ते।
द्रुमाद्द्रुमं के चिदभिप्लवन्ते क्षितौ नगाग्रान्निपतन्ति के चित्॥', 'parasparaṃ ke cid upāśrayante parasparaṃ ke cid atibruvante
drumād drumaṃ ke cid abhiplavante kṣitau nagāgrān nipatanti ke cit', null, 5059015),
('ramayana-5-59-16', 16, 'Sundara Kanda, Sarga 59, Verse 16', 'महीतलात्के चिदुदीर्णवेगा महाद्रुमाग्राण्यभिसंपतन्ते।
गायन्तमन्यः प्रहसन्नुपैति हसन्तमन्यः प्रहसन्नुपैति॥', 'mahītalāt ke cid udīrṇavegā mahādrumāgrāṇy abhisaṃpatante
gāyantam anyaḥ prahasann upaiti hasantam anyaḥ prahasann upaiti', null, 5059016),
('ramayana-5-59-17', 17, 'Sundara Kanda, Sarga 59, Verse 17', 'रुदन्तमन्यः प्ररुदन्नुपैति नुदन्तमन्यः प्रणुदन्नुपैति।
समाकुलं तत्कपिसैन्यमासीन्मधुप्रपानोत्कट सत्त्वचेष्टम्।
न चात्र कश्चिन्न बभूव मत्तो न चात्र कश्चिन्न बभूव तृप्तो॥', 'rudantam anyaḥ prarudann upaiti nudantam anyaḥ praṇudann upaiti
samākulaṃ tat kapisainyam āsīn madhuprapānotkaṭa sattvaceṣṭam
na cātra kaś cin na babhūva matto na cātra kaś cin na babhūva tṛpto', null, 5059017),
('ramayana-5-59-18', 18, 'Sundara Kanda, Sarga 59, Verse 18', 'ततो वनं तत्परिभक्ष्यमाणं द्रुमांश्च विध्वंसितपत्रपुष्पान्।
समीक्ष्य कोपाद्दधिवक्त्रनामा निवारयामास कपिः कपींस्तान्॥', 'tato vanaṃ tat paribhakṣyamāṇaṃ drumāṃś ca vidhvaṃsitapatrapuṣpān
samīkṣya kopād dadhivaktranāmā nivārayām āsa kapiḥ kapīṃs tān', null, 5059018),
('ramayana-5-59-19', 19, 'Sundara Kanda, Sarga 59, Verse 19', 'स तैः प्रवृद्धैः परिभर्त्स्यमानो वनस्य गोप्ता हरिवीरवृद्धः।
चकार भूयो मतिमुग्रतेजा वनस्य रक्षां प्रति वानरेभ्यः॥', 'sa taiḥ pravṛddhaiḥ paribhartsyamāno vanasya goptā harivīravṛddhaḥ
cakāra bhūyo matim ugratejā vanasya rakṣāṃ prati vānarebhyaḥ', null, 5059019),
('ramayana-5-59-20', 20, 'Sundara Kanda, Sarga 59, Verse 20', 'उवाच कांश्चित्परुषाणि धृष्टमसक्तमन्यांश्च तलैर्जघान।
समेत्य कैश्चित्कलहं चकार तथैव साम्नोपजगाम कांश्चित्॥', 'uvāca kāṃś cit paruṣāṇi dhṛṣṭam asaktam anyāṃś ca talair jaghāna
sametya kaiś cit kalahaṃ cakāra tathaiva sāmnopajagāma kāṃś cit', null, 5059020),
('ramayana-5-59-21', 21, 'Sundara Kanda, Sarga 59, Verse 21', 'स तैर्मदाच्चाप्रतिवार्य वेगैर्बलाच्च तेनाप्रतिवार्यमाणैः।
प्रधर्षितस्त्यक्तभयैः समेत्य प्रकृष्यते चाप्यनवेक्ष्य दोषम्॥', 'sa tair madāc cāprativārya vegair balāc ca tenāprativāryamāṇaiḥ
pradharṣitas tyaktabhayaiḥ sametya prakṛṣyate cāpy anavekṣya doṣam', null, 5059021),
('ramayana-5-59-22', 22, 'Sundara Kanda, Sarga 59, Verse 22', 'नखैस्तुदन्तो दशनैर्दशन्तस्तलैश्च पादैश्च समाप्नुवन्तः।
मदात्कपिं तं कपयः समग्रा महावनं निर्विषयं च चक्रुः॥', 'nakhais tudanto daśanair daśantas talaiś ca pādaiś ca samāpnuvantaḥ
madāt kapiṃ taṃ kapayaḥ samagrā mahāvanaṃ nirviṣayaṃ ca cakruḥ', null, 5059022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 60 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-60-1', 1, 'Sundara Kanda, Sarga 60, Verse 1', 'तानुवाच हरिश्रेष्ठो हनूमान्वानरर्षभः।
अव्यग्रमनसो यूयं मधु सेवत वानराः॥', 'tān uvāca hariśreṣṭho hanūmān vānararṣabhaḥ
avyagramanaso yūyaṃ madhu sevata vānarāḥ', null, 5060001),
('ramayana-5-60-2', 2, 'Sundara Kanda, Sarga 60, Verse 2', 'श्रुत्वा हनुमतो वाक्यं हरीणां प्रवरोऽङ्गदः।
प्रत्युवाच प्रसन्नात्मा पिबन्तु हरयो मधु॥', 'śrutvā hanumato vākyaṃ harīṇāṃ pravaro ''ṅgadaḥ
pratyuvāca prasannātmā pibantu harayo madhu', null, 5060002),
('ramayana-5-60-3', 3, 'Sundara Kanda, Sarga 60, Verse 3', 'अवश्यं कृतकार्यस्य वाक्यं हनुमतो मया।
अकार्यमपि कर्तव्यं किमङ्ग पुनरीदृशम्॥', 'avaśyaṃ kṛtakāryasya vākyaṃ hanumato mayā
akāryam api kartavyaṃ kim aṅga punar īdṛśam', null, 5060003),
('ramayana-5-60-4', 4, 'Sundara Kanda, Sarga 60, Verse 4', 'अन्दगस्य मुखाच्छ्रुत्वा वचनं वानरर्षभाः।
साधु साध्विति संहृष्टा वानराः प्रत्यपूजयन्॥', 'andagasya mukhāc chrutvā vacanaṃ vānararṣabhāḥ
sādhu sādhv iti saṃhṛṣṭā vānarāḥ pratyapūjayan', null, 5060004),
('ramayana-5-60-5', 5, 'Sundara Kanda, Sarga 60, Verse 5', 'पूजयित्वाङ्गदं सर्वे वानरा वानरर्षभम्।
जग्मुर्मधुवनं यत्र नदीवेग इव द्रुतम्॥', 'pūjayitvāṅgadaṃ sarve vānarā vānararṣabham
jagmur madhuvanaṃ yatra nadīvega iva drutam', null, 5060005),
('ramayana-5-60-6', 6, 'Sundara Kanda, Sarga 60, Verse 6', 'ते प्रहृष्टा मधुवनं पालानाक्रम्य वीर्यतः।
अतिसर्गाच्च पटवो दृष्ट्वा श्रुत्वा च मैथिलीम्॥', 'te prahṛṣṭā madhuvanaṃ pālān ākramya vīryataḥ
atisargāc ca paṭavo dṛṣṭvā śrutvā ca maithilīm', null, 5060006),
('ramayana-5-60-7', 7, 'Sundara Kanda, Sarga 60, Verse 7', 'उत्पत्य च ततः सर्वे वनपालान्समागताः।
ताडयन्ति स्म शतशः सक्तान्मधुवने तदा॥', 'utpatya ca tataḥ sarve vanapālān samāgatāḥ
tāḍayanti sma śataśaḥ saktān madhuvane tadā', null, 5060007),
('ramayana-5-60-8', 8, 'Sundara Kanda, Sarga 60, Verse 8', 'मधूनि द्रोणमात्राणि बहुभिः परिगृह्य ते।
घ्नन्ति स्म सहिताः सर्वे भक्षयन्ति तथापरे॥', 'madhūni droṇamātrāṇi bahubhiḥ parigṛhya te
ghnanti sma sahitāḥ sarve bhakṣayanti tathāpare', null, 5060008),
('ramayana-5-60-9', 9, 'Sundara Kanda, Sarga 60, Verse 9', 'के चित्पीत्वापविध्यन्ति मधूनि मधुपिङ्गलाः।
मधूच्चिष्टेन के चिच्च जघ्नुरन्योन्यमुत्कटाः॥', 'ke cit pītvāpavidhyanti madhūni madhupiṅgalāḥ
madhūcciṣṭena ke cic ca jaghnur anyonyam utkaṭāḥ', null, 5060009),
('ramayana-5-60-10', 10, 'Sundara Kanda, Sarga 60, Verse 10', 'अपरे वृक्षमूलेषु शाखां गृह्य व्यवस्थितः।
अत्यर्थं च मदग्लानाः पर्णान्यास्तीर्य शेरते॥', 'apare vṛkṣamūleṣu śākhāṃ gṛhya vyavasthitaḥ
atyarthaṃ ca madaglānāḥ parṇāny āstīrya śerate', null, 5060010),
('ramayana-5-60-11', 11, 'Sundara Kanda, Sarga 60, Verse 11', 'उन्मत्तभूताः प्लवगा मधुमत्ताश्च हृष्टवत्।
क्षिपन्त्यपि तथान्योन्यं स्खलन्त्यपि तथापरे॥', 'unmattabhūtāḥ plavagā madhumattāś ca hṛṣṭavat
kṣipanty api tathānyonyaṃ skhalanty api tathāpare', null, 5060011),
('ramayana-5-60-12', 12, 'Sundara Kanda, Sarga 60, Verse 12', 'के चित्क्ष्वेडान्प्रकुर्वन्ति के चित्कूजन्ति हृष्टवत्।
हरयो मधुना मत्ताः के चित्सुप्ता महीतले॥', 'ke cit kṣveḍān prakurvanti ke cit kūjanti hṛṣṭavat
harayo madhunā mattāḥ ke cit suptā mahītale', null, 5060012),
('ramayana-5-60-13', 13, 'Sundara Kanda, Sarga 60, Verse 13', 'येऽप्यत्र मधुपालाः स्युः प्रेष्या दधिमुखस्य तु।
तेऽपि तैर्वानरैर्भीमैः प्रतिषिद्धा दिशो गताः॥', 'ye ''py atra madhupālāḥ syuḥ preṣyā dadhimukhasya tu
te ''pi tair vānarair bhīmaiḥ pratiṣiddhā diśo gatāḥ', null, 5060013),
('ramayana-5-60-14', 14, 'Sundara Kanda, Sarga 60, Verse 14', 'जानुभिश्च प्रकृष्टाश्च देवमार्गं च दर्शिताः।
अब्रुवन्परमोद्विग्ना गत्वा दधिमुखं वचः॥', 'jānubhiś ca prakṛṣṭāś ca devamārgaṃ ca darśitāḥ
abruvan paramodvignā gatvā dadhimukhaṃ vacaḥ', null, 5060014),
('ramayana-5-60-15', 15, 'Sundara Kanda, Sarga 60, Verse 15', 'हनूमता दत्तवरैर्हतं मधुवनं बलात्।
वयं च जानुभिः कृष्टा देवमार्गं च दर्शिताः॥', 'hanūmatā dattavarair hataṃ madhuvanaṃ balāt
vayaṃ ca jānubhiḥ kṛṣṭā devamārgaṃ ca darśitāḥ', null, 5060015),
('ramayana-5-60-16', 16, 'Sundara Kanda, Sarga 60, Verse 16', 'ततो दधिमुखः क्रुद्धो वनपस्तत्र वानरः।
हतं मधुवनं श्रुत्वा सान्त्वयामास तान्हरीन्॥', 'tato dadhimukhaḥ kruddho vanapas tatra vānaraḥ
hataṃ madhuvanaṃ śrutvā sāntvayām āsa tān harīn', null, 5060016),
('ramayana-5-60-17', 17, 'Sundara Kanda, Sarga 60, Verse 17', 'एतागच्छत गच्छामो वानरानतिदर्पितान्।
बलेनावारयिष्यामो मधु भक्षयतो वयम्॥', 'etāgacchata gacchāmo vānarān atidarpitān
balenāvārayiṣyāmo madhu bhakṣayato vayam', null, 5060017),
('ramayana-5-60-18', 18, 'Sundara Kanda, Sarga 60, Verse 18', 'श्रुत्वा दधिमुखस्येदं वचनं वानरर्षभाः।
पुनर्वीरा मधुवनं तेनैव सहिता ययुः॥', 'śrutvā dadhimukhasyedaṃ vacanaṃ vānararṣabhāḥ
punar vīrā madhuvanaṃ tenaiva sahitā yayuḥ', null, 5060018),
('ramayana-5-60-19', 19, 'Sundara Kanda, Sarga 60, Verse 19', 'मध्ये चैषां दधिमुखः प्रगृह्य सुमहातरुम्।
समभ्यधावद्वेगेना ते च सर्वे प्लवंगमाः॥', 'madhye caiṣāṃ dadhimukhaḥ pragṛhya sumahātarum
samabhyadhāvad vegenā te ca sarve plavaṃgamāḥ', null, 5060019),
('ramayana-5-60-20', 20, 'Sundara Kanda, Sarga 60, Verse 20', 'ते शिलाः पादपांश्चापि पाषाणांश्चापि वानराः।
गृहीत्वाभ्यागमन्क्रुद्धा यत्र ते कपिकुञ्जराः॥', 'te śilāḥ pādapāṃś cāpi pāṣāṇāṃś cāpi vānarāḥ
gṛhītvābhyāgaman kruddhā yatra te kapikuñjarāḥ', null, 5060020),
('ramayana-5-60-21', 21, 'Sundara Kanda, Sarga 60, Verse 21', 'ते स्वामिवचनं वीरा हृदयेष्ववसज्य तत्।
त्वरया ह्यभ्यधावन्त सालतालशिलायुधाः॥', 'te svāmivacanaṃ vīrā hṛdayeṣv avasajya tat
tvarayā hy abhyadhāvanta sālatālaśilāyudhāḥ', null, 5060021),
('ramayana-5-60-22', 22, 'Sundara Kanda, Sarga 60, Verse 22', 'वृक्षस्थांश्च तलस्थांश्च वानरान्बलदर्पितान्।
अभ्यक्रामन्त ते वीराः पालास्तत्र सहस्रशः॥', 'vṛkṣasthāṃś ca talasthāṃś ca vānarān baladarpitān
abhyakrāmanta te vīrāḥ pālās tatra sahasraśaḥ', null, 5060022),
('ramayana-5-60-23', 23, 'Sundara Kanda, Sarga 60, Verse 23', 'अथ दृष्ट्वा दधिमुखं क्रुद्धं वानरपुंगवाः।
अभ्यधावन्त वेगेन हनूमत्प्रमुखास्तदा॥', 'atha dṛṣṭvā dadhimukhaṃ kruddhaṃ vānarapuṃgavāḥ
abhyadhāvanta vegena hanūmatpramukhās tadā', null, 5060023),
('ramayana-5-60-24', 24, 'Sundara Kanda, Sarga 60, Verse 24', 'तं सवृक्षं महाबाहुमापतन्तं महाबलम्।
आर्यकं प्राहरत्तत्र बाहुभ्यां कुपितोऽङ्गदः॥', 'taṃ savṛkṣaṃ mahābāhum āpatantaṃ mahābalam
āryakaṃ prāharat tatra bāhubhyāṃ kupito ''ṅgadaḥ', null, 5060024),
('ramayana-5-60-25', 25, 'Sundara Kanda, Sarga 60, Verse 25', 'मदान्धश न वेदैनमार्यकोऽयं ममेति सः।
अथैनं निष्पिपेषाशु वेगवद्वसुधातले॥', 'madāndhaś a na vedainam āryako ''yaṃ mameti saḥ
athainaṃ niṣpipeṣāśu vegavad vasudhātale', null, 5060025),
('ramayana-5-60-26', 26, 'Sundara Kanda, Sarga 60, Verse 26', 'स भग्नबाहुर्विमुखो विह्वलः शोणितोक्षितः।
मुमोह सहसा वीरो मुहूर्तं कपिकुञ्जरः॥', 'sa bhagnabāhur vimukho vihvalaḥ śoṇitokṣitaḥ
mumoha sahasā vīro muhūrtaṃ kapikuñjaraḥ', null, 5060026),
('ramayana-5-60-27', 27, 'Sundara Kanda, Sarga 60, Verse 27', 'स कथं चिद्विमुक्तस्तैर्वानरैर्वानरर्षभः।
उवाचैकान्तमागम्य भृत्यांस्तान्समुपागतान्॥', 'sa kathaṃ cid vimuktas tair vānarair vānararṣabhaḥ
uvācaikāntam āgamya bhṛtyāṃs tān samupāgatān', null, 5060027),
('ramayana-5-60-28', 28, 'Sundara Kanda, Sarga 60, Verse 28', 'एते तिष्ठन्तु गच्छामो भर्ता नो यत्र वानरः।
सुग्रीवो विपुलग्रीवः सह रामेण तिष्ठति॥', 'ete tiṣṭhantu gacchāmo bhartā no yatra vānaraḥ
sugrīvo vipulagrīvaḥ saha rāmeṇa tiṣṭhati', null, 5060028),
('ramayana-5-60-29', 29, 'Sundara Kanda, Sarga 60, Verse 29', 'सर्वं चैवाङ्गदे दोषं श्रावयिष्यामि पार्थिव।
अमर्षी वचनं श्रुत्वा घातयिष्यति वानरान्॥', 'sarvaṃ caivāṅgade doṣaṃ śrāvayiṣyāmi pārthiva
amarṣī vacanaṃ śrutvā ghātayiṣyati vānarān', null, 5060029),
('ramayana-5-60-30', 30, 'Sundara Kanda, Sarga 60, Verse 30', 'इष्टं मधुवनं ह्येतत्सुग्रीवस्य महात्मनः।
पितृपैतामहं दिव्यं देवैरपि दुरासदम्॥', 'iṣṭaṃ madhuvanaṃ hy etat sugrīvasya mahātmanaḥ
pitṛpaitāmahaṃ divyaṃ devair api durāsadam', null, 5060030),
('ramayana-5-60-31', 31, 'Sundara Kanda, Sarga 60, Verse 31', 'स वानरानिमान्सर्वान्मधुलुब्धान्गतायुषः।
घातयिष्यति दण्डेन सुग्रीवः ससुहृज्जनान्॥', 'sa vānarān imān sarvān madhulubdhān gatāyuṣaḥ
ghātayiṣyati daṇḍena sugrīvaḥ sasuhṛjjanān', null, 5060031),
('ramayana-5-60-32', 32, 'Sundara Kanda, Sarga 60, Verse 32', 'वध्या ह्येते दुरात्मानो नृपाज्ञा परिभाविनः।
अमर्षप्रभवो रोषः सफलो नो भविष्यति॥', 'vadhyā hy ete durātmāno nṛpājñā paribhāvinaḥ
amarṣaprabhavo roṣaḥ saphalo no bhaviṣyati', null, 5060032),
('ramayana-5-60-33', 33, 'Sundara Kanda, Sarga 60, Verse 33', 'एवमुक्त्वा दधिमुखो वनपालान्महाबलः।
जगाम सहसोत्पत्य वनपालैः समन्वितः॥', 'evam uktvā dadhimukho vanapālān mahābalaḥ
jagāma sahasotpatya vanapālaiḥ samanvitaḥ', null, 5060033),
('ramayana-5-60-34', 34, 'Sundara Kanda, Sarga 60, Verse 34', 'निमेषान्तरमात्रेण स हि प्राप्तो वनालयः।
सहस्रांशुसुतो धीमान्सुग्रीवो यत्र वानरः॥', 'nimeṣāntaramātreṇa sa hi prāpto vanālayaḥ
sahasrāṃśusuto dhīmān sugrīvo yatra vānaraḥ', null, 5060034),
('ramayana-5-60-35', 35, 'Sundara Kanda, Sarga 60, Verse 35', 'रामं च लक्ष्मणं चैव दृष्ट्वा सुग्रीवमेव च।
समप्रतिष्ठां जगतीमाकाशान्निपपात ह॥', 'rāmaṃ ca lakṣmaṇaṃ caiva dṛṣṭvā sugrīvam eva ca
samapratiṣṭhāṃ jagatīm ākāśān nipapāta ha', null, 5060035),
('ramayana-5-60-36', 36, 'Sundara Kanda, Sarga 60, Verse 36', 'स निपत्य महावीर्यः सर्वैस्तैः परिवारितः।
हरिर्दधिमुखः पालैः पालानां परमेश्वरः॥', 'sa nipatya mahāvīryaḥ sarvais taiḥ parivāritaḥ
harir dadhimukhaḥ pālaiḥ pālānāṃ parameśvaraḥ', null, 5060036),
('ramayana-5-60-37', 37, 'Sundara Kanda, Sarga 60, Verse 37', 'स दीनवदनो भूत्वा कृत्वा शिरसि चाञ्जलिम्।
सुग्रीवस्य शुभौ मूर्ध्ना चरणौ प्रत्यपीडयत्॥', 'sa dīnavadano bhūtvā kṛtvā śirasi cāñjalim
sugrīvasya śubhau mūrdhnā caraṇau pratyapīḍayat', null, 5060037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 61 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-61-1', 1, 'Sundara Kanda, Sarga 61, Verse 1', 'ततो मूर्ध्ना निपतितं वानरं वानरर्षभः।
दृष्ट्वैवोद्विग्नहृदयो वाक्यमेतदुवाच ह॥', 'tato mūrdhnā nipatitaṃ vānaraṃ vānararṣabhaḥ
dṛṣṭvaivodvignahṛdayo vākyam etad uvāca ha', null, 5061001),
('ramayana-5-61-2', 2, 'Sundara Kanda, Sarga 61, Verse 2', 'उत्तिष्ठोत्तिष्ठ कस्मात्त्वं पादयोः पतितो मम।
अभयं ते भवेद्वीर सत्यमेवाभिधीयताम्॥', 'uttiṣṭhottiṣṭha kasmāt tvaṃ pādayoḥ patito mama
abhayaṃ te bhaved vīra satyam evābhidhīyatām', null, 5061002),
('ramayana-5-61-3', 3, 'Sundara Kanda, Sarga 61, Verse 3', 'स तु विश्वासितस्तेन सुग्रीवेण महात्मना।
उत्थाय च महाप्राज्ञो वाक्यं दधिमुखोऽब्रवीत्॥', 'sa tu viśvāsitas tena sugrīveṇa mahātmanā
utthāya ca mahāprājño vākyaṃ dadhimukho ''bravīt', null, 5061003),
('ramayana-5-61-4', 4, 'Sundara Kanda, Sarga 61, Verse 4', 'नैवर्क्षरजसा राजन्न त्वया नापि वालिना।
वनं निसृष्टपूर्वं हि भक्षितं तत्तु वानरैः॥', 'naivarkṣarajasā rājan na tvayā nāpi vālinā
vanaṃ nisṛṣṭapūrvaṃ hi bhakṣitaṃ tat tu vānaraiḥ', null, 5061004),
('ramayana-5-61-5', 5, 'Sundara Kanda, Sarga 61, Verse 5', 'एभिः प्रधर्षिताश्चैव वारिता वनरक्षिभिः।
मधून्यचिन्तयित्वेमान्भक्षयन्ति पिबन्ति च॥', 'ebhiḥ pradharṣitāś caiva vāritā vanarakṣibhiḥ
madhūny acintayitvemān bhakṣayanti pibanti ca', null, 5061005),
('ramayana-5-61-6', 6, 'Sundara Kanda, Sarga 61, Verse 6', 'शिष्टमत्रापविध्यन्ति भक्षयन्ति तथापरे।
निवार्यमाणास्ते सर्वे भ्रुवौ वै दर्शयन्ति हि॥', 'śiṣṭam atrāpavidhyanti bhakṣayanti tathāpare
nivāryamāṇās te sarve bhruvau vai darśayanti hi', null, 5061006),
('ramayana-5-61-7', 7, 'Sundara Kanda, Sarga 61, Verse 7', 'इमे हि संरब्धतरास्तथा तैः संप्रधर्षिताः।
वारयन्तो वनात्तस्मात्क्रुद्धैर्वानरपुंगवैः॥', 'ime hi saṃrabdhatarās tathā taiḥ saṃpradharṣitāḥ
vārayanto vanāt tasmāt kruddhair vānarapuṃgavaiḥ', null, 5061007),
('ramayana-5-61-8', 8, 'Sundara Kanda, Sarga 61, Verse 8', 'ततस्तैर्बहुभिर्वीरैर्वानरैर्वानरर्षभाः।
संरक्तनयनैः क्रोधाद्धरयः संप्रचालिताः॥', 'tatas tair bahubhir vīrair vānarair vānararṣabhāḥ
saṃraktanayanaiḥ krodhād dharayaḥ saṃpracālitāḥ', null, 5061008),
('ramayana-5-61-9', 9, 'Sundara Kanda, Sarga 61, Verse 9', 'पाणिभिर्निहताः के चित्के चिज्जानुभिराहताः।
प्रकृष्टाश्च यथाकामं देवमार्गं च दर्शिताः॥', 'pāṇibhir nihatāḥ ke cit ke cij jānubhir āhatāḥ
prakṛṣṭāś ca yathākāmaṃ devamārgaṃ ca darśitāḥ', null, 5061009),
('ramayana-5-61-10', 10, 'Sundara Kanda, Sarga 61, Verse 10', 'एवमेते हताः शूरास्त्वयि तिष्ठति भर्तरि।
कृत्स्नं मधुवनं चैव प्रकामं तैः प्रभक्ष्यते॥', 'evam ete hatāḥ śūrās tvayi tiṣṭhati bhartari
kṛtsnaṃ madhuvanaṃ caiva prakāmaṃ taiḥ prabhakṣyate', null, 5061010),
('ramayana-5-61-11', 11, 'Sundara Kanda, Sarga 61, Verse 11', 'एवं विज्ञाप्यमानं तु सुग्रीवं वानरर्षभम्।
अपृच्छत्तं महाप्राज्ञो लक्ष्मणः परवीरहा॥', 'evaṃ vijñāpyamānaṃ tu sugrīvaṃ vānararṣabham
apṛcchat taṃ mahāprājño lakṣmaṇaḥ paravīrahā', null, 5061011),
('ramayana-5-61-12', 12, 'Sundara Kanda, Sarga 61, Verse 12', 'किमयं वानरो राजन्वनपः प्रत्युपस्थितः।
कं चार्थमभिनिर्दिश्य दुःखितो वाक्यमब्रवीत्॥', 'kim ayaṃ vānaro rājan vanapaḥ pratyupasthitaḥ
kaṃ cārtham abhinirdiśya duḥkhito vākyam abravīt', null, 5061012),
('ramayana-5-61-13', 13, 'Sundara Kanda, Sarga 61, Verse 13', 'एवमुक्तस्तु सुग्रीवो लक्ष्मणेन महात्मना।
लक्ष्मणं प्रत्युवाचेदं वाक्यं वाक्यविशारदः॥', 'evam uktas tu sugrīvo lakṣmaṇena mahātmanā
lakṣmaṇaṃ pratyuvācedaṃ vākyaṃ vākyaviśāradaḥ', null, 5061013),
('ramayana-5-61-14', 14, 'Sundara Kanda, Sarga 61, Verse 14', 'आर्य लक्ष्मण संप्राह वीरो दधिमुखः कपिः।
अङ्गदप्रमुखैर्वीरैर्भक्षितं मधुवानरैः॥', 'ārya lakṣmaṇa saṃprāha vīro dadhimukhaḥ kapiḥ
aṅgadapramukhair vīrair bhakṣitaṃ madhuvānaraiḥ', null, 5061014),
('ramayana-5-61-15', 15, 'Sundara Kanda, Sarga 61, Verse 15', 'नैषामकृतकृत्यानामीदृशः स्यादुपक्रमः।
वनं यथाभिपन्नं तैः साधितं कर्म वानरैः॥', 'naiṣām akṛtakṛtyānām īdṛśaḥ syād upakramaḥ
vanaṃ yathābhipannaṃ taiḥ sādhitaṃ karma vānaraiḥ', null, 5061015),
('ramayana-5-61-16', 16, 'Sundara Kanda, Sarga 61, Verse 16', 'दृष्टा देवी न संदेहो न चान्येन हनूमता।
न ह्यन्यः साधने हेतुः कर्मणोऽस्य हनूमतः॥', 'dṛṣṭā devī na saṃdeho na cānyena hanūmatā
na hy anyaḥ sādhane hetuḥ karmaṇo ''sya hanūmataḥ', null, 5061016),
('ramayana-5-61-17', 17, 'Sundara Kanda, Sarga 61, Verse 17', 'कार्यसिद्धिर्हनुमति मतिश्च हरिपुंगव।
व्यवसायश्च वीर्यं च श्रुतं चापि प्रतिष्ठितम्॥', 'kāryasiddhir hanumati matiś ca haripuṃgava
vyavasāyaś ca vīryaṃ ca śrutaṃ cāpi pratiṣṭhitam', null, 5061017),
('ramayana-5-61-18', 18, 'Sundara Kanda, Sarga 61, Verse 18', 'जाम्बवान्यत्र नेता स्यादङ्गदस्य बलेश्वरः।
हनूमांश्चाप्यधिष्ठाता न तस्य गतिरन्यथा॥', 'jāmbavān yatra netā syād aṅgadasya baleśvaraḥ
hanūmāṃś cāpy adhiṣṭhātā na tasya gatir anyathā', null, 5061018),
('ramayana-5-61-19', 19, 'Sundara Kanda, Sarga 61, Verse 19', 'अङ्गदप्रमुखैर्वीरैर्हतं मधुवनं किल।
विचिन्त्य दक्षिणामाशामागतैर्हरिपुंगवैः॥', 'aṅgadapramukhair vīrair hataṃ madhuvanaṃ kila
vicintya dakṣiṇām āśām āgatair haripuṃgavaiḥ', null, 5061019),
('ramayana-5-61-20', 20, 'Sundara Kanda, Sarga 61, Verse 20', 'आगतैश्च प्रविष्टं तद्यथा मधुवनं हि तैः।
धर्षितं च वनं कृत्स्नमुपयुक्तं च वानरैः।
वारिताः सहिताः पालास्तथा जानुभिराहताः॥', 'āgataiś ca praviṣṭaṃ tad yathā madhuvanaṃ hi taiḥ
dharṣitaṃ ca vanaṃ kṛtsnam upayuktaṃ ca vānaraiḥ
vāritāḥ sahitāḥ pālās tathā jānubhir āhatāḥ', null, 5061020),
('ramayana-5-61-21', 21, 'Sundara Kanda, Sarga 61, Verse 21', 'एतदर्थमयं प्राप्तो वक्तुं मधुरवागिह।
नाम्ना दधिमुखो नाम हरिः प्रख्यातविक्रमः॥', 'etadartham ayaṃ prāpto vaktuṃ madhuravāg iha
nāmnā dadhimukho nāma hariḥ prakhyātavikramaḥ', null, 5061021),
('ramayana-5-61-22', 22, 'Sundara Kanda, Sarga 61, Verse 22', 'दृष्टा सीता महाबाहो सौमित्रे पश्य तत्त्वतः।
अभिगम्य यथा सर्वे पिबन्ति मधु वानराः॥', 'dṛṣṭā sītā mahābāho saumitre paśya tattvataḥ
abhigamya yathā sarve pibanti madhu vānarāḥ', null, 5061022),
('ramayana-5-61-23', 23, 'Sundara Kanda, Sarga 61, Verse 23', 'न चाप्यदृष्ट्वा वैदेहीं विश्रुताः पुरुषर्षभ।
वनं दात्त वरं दिव्यं धर्षयेयुर्वनौकसः॥', 'na cāpy adṛṣṭvā vaidehīṃ viśrutāḥ puruṣarṣabha
vanaṃ dātta varaṃ divyaṃ dharṣayeyur vanaukasaḥ', null, 5061023),
('ramayana-5-61-24', 24, 'Sundara Kanda, Sarga 61, Verse 24', 'ततः प्रहृष्टो धर्मात्मा लक्ष्मणः सहराघवः।
श्रुत्वा कर्णसुखां वाणीं सुग्रीववदनाच्च्युताम्॥', 'tataḥ prahṛṣṭo dharmātmā lakṣmaṇaḥ saharāghavaḥ
śrutvā karṇasukhāṃ vāṇīṃ sugrīvavadanāc cyutām', null, 5061024),
('ramayana-5-61-25', 25, 'Sundara Kanda, Sarga 61, Verse 25', 'प्राहृष्यत भृशं रामो लक्ष्मणश्च महायशाः।
श्रुत्वा दधिमुखस्येदं सुग्रीवस्तु प्रहृष्य च।
वनपालं पुनर्वाक्यं सुग्रीवः प्रत्यभाषत॥', 'prāhṛṣyata bhṛśaṃ rāmo lakṣmaṇaś ca mahāyaśāḥ
śrutvā dadhimukhasyedaṃ sugrīvas tu prahṛṣya ca
vanapālaṃ punar vākyaṃ sugrīvaḥ pratyabhāṣata', null, 5061025),
('ramayana-5-61-26', 26, 'Sundara Kanda, Sarga 61, Verse 26', 'प्रीतोऽस्मि सौम्य यद्भुक्तं वनं तैः कृतकर्मभिः।
मर्षितं मर्षणीयं च चेष्टितं कृतकर्मणाम्॥', 'prīto ''smi saumya yad bhuktaṃ vanaṃ taiḥ kṛtakarmabhiḥ
marṣitaṃ marṣaṇīyaṃ ca ceṣṭitaṃ kṛtakarmaṇām', null, 5061026),
('ramayana-5-61-27', 27, 'Sundara Kanda, Sarga 61, Verse 27', 'इच्छामि शीघ्रं हनुमत्प्रधानान्शाखामृगांस्तान्मृगराजदर्पान्।
द्रष्टुं कृतार्थान्सह राघवाभ्यां श्रोतुं च सीताधिगमे प्रयत्नम्॥', 'icchāmi śīghraṃ hanumatpradhānān śākhāmṛgāṃs tān mṛgarājadarpān
draṣṭuṃ kṛtārthān saha rāghavābhyāṃ śrotuṃ ca sītādhigame prayatnam', null, 5061027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 62 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-62-1', 1, 'Sundara Kanda, Sarga 62, Verse 1', 'सुग्रीवेणैवमुक्तस्तु हृष्टो दधिमुखः कपिः।
राघवं लक्ष्मणं चैव सुग्रीवं चाभ्यवादयत्॥', 'sugrīveṇaivam uktas tu hṛṣṭo dadhimukhaḥ kapiḥ
rāghavaṃ lakṣmaṇaṃ caiva sugrīvaṃ cābhyavādayat', null, 5062001),
('ramayana-5-62-2', 2, 'Sundara Kanda, Sarga 62, Verse 2', 'स प्रणम्य च सुग्रीवं राघवौ च महाबलौ।
वानरैः सहितैः शूरैर्दिवमेवोत्पपात ह॥', 'sa praṇamya ca sugrīvaṃ rāghavau ca mahābalau
vānaraiḥ sahitaiḥ śūrair divam evotpapāta ha', null, 5062002),
('ramayana-5-62-3', 3, 'Sundara Kanda, Sarga 62, Verse 3', 'स यथैवागतः पूर्वं तथैव त्वरितो गतः।
निपत्य गगनाद्भूमौ तद्वनं प्रविवेश ह॥', 'sa yathaivāgataḥ pūrvaṃ tathaiva tvarito gataḥ
nipatya gaganād bhūmau tad vanaṃ praviveśa ha', null, 5062003),
('ramayana-5-62-4', 4, 'Sundara Kanda, Sarga 62, Verse 4', 'स प्रविष्टो मधुवनं ददर्श हरियूथपान्।
विमदानुद्धतान्सर्वान्मेहमानान्मधूदकम्॥', 'sa praviṣṭo madhuvanaṃ dadarśa hariyūthapān
vimadān uddhatān sarvān mehamānān madhūdakam', null, 5062004),
('ramayana-5-62-5', 5, 'Sundara Kanda, Sarga 62, Verse 5', 'स तानुपागमद्वीरो बद्ध्वा करपुटाञ्जलिम्।
उवाच वचनं श्लक्ष्णमिदं हृष्टवदङ्गदम्॥', 'sa tān upāgamad vīro baddhvā karapuṭāñjalim
uvāca vacanaṃ ślakṣṇam idaṃ hṛṣṭavad aṅgadam', null, 5062005),
('ramayana-5-62-6', 6, 'Sundara Kanda, Sarga 62, Verse 6', 'सौम्य रोषो न कर्तव्यो यदेभिरभिवारितः।
अज्ञानाद्रक्षिभिः क्रोधाद्भवन्तः प्रतिषेधिताः॥', 'saumya roṣo na kartavyo yad ebhir abhivāritaḥ
ajñānād rakṣibhiḥ krodhād bhavantaḥ pratiṣedhitāḥ', null, 5062006),
('ramayana-5-62-7', 7, 'Sundara Kanda, Sarga 62, Verse 7', 'युवराजस्त्वमीशश्च वनस्यास्य महाबल।
मौर्ख्यात्पूर्वं कृतो दोषस्तद्भवान्क्षन्तुमर्हति॥', 'yuvarājas tvam īśaś ca vanasyāsya mahābala
maurkhyāt pūrvaṃ kṛto doṣas tad bhavān kṣantum arhati', null, 5062007),
('ramayana-5-62-8', 8, 'Sundara Kanda, Sarga 62, Verse 8', 'यथैव हि पिता तेऽभूत्पूर्वं हरिगणेश्वरः।
तथा त्वमपि सुग्रीवो नान्यस्तु हरिसत्तम॥', 'yathaiva hi pitā te ''bhūt pūrvaṃ harigaṇeśvaraḥ
tathā tvam api sugrīvo nānyas tu harisattama', null, 5062008),
('ramayana-5-62-9', 9, 'Sundara Kanda, Sarga 62, Verse 9', 'आख्यातं हि मया गत्वा पितृव्यस्य तवानघ।
इहोपयानं सर्वेषामेतेषां वनचारिणाम्॥', 'ākhyātaṃ hi mayā gatvā pitṛvyasya tavānagha
ihopayānaṃ sarveṣām eteṣāṃ vanacāriṇām', null, 5062009),
('ramayana-5-62-10', 10, 'Sundara Kanda, Sarga 62, Verse 10', 'स त्वदागमनं श्रुत्वा सहैभिर्हरियूथपैः।
प्रहृष्टो न तु रुष्टोऽसौ वनं श्रुत्वा प्रधर्षितम्॥', 'sa tvadāgamanaṃ śrutvā sahaibhir hariyūthapaiḥ
prahṛṣṭo na tu ruṣṭo ''sau vanaṃ śrutvā pradharṣitam', null, 5062010),
('ramayana-5-62-11', 11, 'Sundara Kanda, Sarga 62, Verse 11', 'प्रहृष्टो मां पितृव्यस्ते सुग्रीवो वानरेश्वरः।
शीघ्रं प्रेषय सर्वांस्तानिति होवाच पार्थिवः॥', 'prahṛṣṭo māṃ pitṛvyas te sugrīvo vānareśvaraḥ
śīghraṃ preṣaya sarvāṃs tān iti hovāca pārthivaḥ', null, 5062011),
('ramayana-5-62-12', 12, 'Sundara Kanda, Sarga 62, Verse 12', 'श्रुत्वा दधिमुखस्यैतद्वचनं श्लक्ष्णमङ्गदः।
अब्रवीत्तान्हरिश्रेष्ठो वाक्यं वाक्यविशारदः॥', 'śrutvā dadhimukhasyaitad vacanaṃ ślakṣṇam aṅgadaḥ
abravīt tān hariśreṣṭho vākyaṃ vākyaviśāradaḥ', null, 5062012),
('ramayana-5-62-13', 13, 'Sundara Kanda, Sarga 62, Verse 13', 'शङ्के श्रुतोऽयं वृत्तान्तो रामेण हरियूथपाः।
तत्क्षमं नेह नः स्थातुं कृते कार्ये परंतपाः॥', 'śaṅke śruto ''yaṃ vṛttānto rāmeṇa hariyūthapāḥ
tat kṣamaṃ neha naḥ sthātuṃ kṛte kārye paraṃtapāḥ', null, 5062013),
('ramayana-5-62-14', 14, 'Sundara Kanda, Sarga 62, Verse 14', 'पीत्वा मधु यथाकामं विश्रान्ता वनचारिणः।
किं शेषं गमनं तत्र सुग्रीवो यत्र मे गुरुः॥', 'pītvā madhu yathākāmaṃ viśrāntā vanacāriṇaḥ
kiṃ śeṣaṃ gamanaṃ tatra sugrīvo yatra me guruḥ', null, 5062014),
('ramayana-5-62-15', 15, 'Sundara Kanda, Sarga 62, Verse 15', 'सर्वे यथा मां वक्ष्यन्ति समेत्य हरियूथपाः।
तथास्मि कर्ता कर्तव्ये भवद्भिः परवानहम्॥', 'sarve yathā māṃ vakṣyanti sametya hariyūthapāḥ
tathāsmi kartā kartavye bhavadbhiḥ paravān aham', null, 5062015),
('ramayana-5-62-16', 16, 'Sundara Kanda, Sarga 62, Verse 16', 'नाज्ञापयितुमीशोऽहं युवराजोऽस्मि यद्यपि।
अयुक्तं कृतकर्माणो यूयं धर्षयितुं मया॥', 'nājñāpayitum īśo ''haṃ yuvarājo ''smi yady api
ayuktaṃ kṛtakarmāṇo yūyaṃ dharṣayituṃ mayā', null, 5062016),
('ramayana-5-62-17', 17, 'Sundara Kanda, Sarga 62, Verse 17', 'ब्रुवतश्चाङ्गदश्चैवं श्रुत्वा वचनमव्ययम्।
प्रहृष्टमनसो वाक्यमिदमूचुर्वनौकसः॥', 'bruvataś cāṅgadaś caivaṃ śrutvā vacanam avyayam
prahṛṣṭamanaso vākyam idam ūcur vanaukasaḥ', null, 5062017),
('ramayana-5-62-18', 18, 'Sundara Kanda, Sarga 62, Verse 18', 'एवं वक्ष्यति को राजन्प्रभुः सन्वानरर्षभ।
ऐश्वर्यमदमत्तो हि सर्वोऽहमिति मन्यते॥', 'evaṃ vakṣyati ko rājan prabhuḥ san vānararṣabha
aiśvaryamadamatto hi sarvo ''ham iti manyate', null, 5062018),
('ramayana-5-62-19', 19, 'Sundara Kanda, Sarga 62, Verse 19', 'तव चेदं सुसदृशं वाक्यं नान्यस्य कस्य चित्।
संनतिर्हि तवाख्याति भविष्यच्छुभभाग्यताम्॥', 'tava cedaṃ susadṛśaṃ vākyaṃ nānyasya kasya cit
saṃnatir hi tavākhyāti bhaviṣyac chubhabhāgyatām', null, 5062019),
('ramayana-5-62-20', 20, 'Sundara Kanda, Sarga 62, Verse 20', 'सर्वे वयमपि प्राप्तास्तत्र गन्तुं कृतक्षणाः।
स यत्र हरिवीराणां सुग्रीवः पतिरव्ययः॥', 'sarve vayam api prāptās tatra gantuṃ kṛtakṣaṇāḥ
sa yatra harivīrāṇāṃ sugrīvaḥ patir avyayaḥ', null, 5062020),
('ramayana-5-62-21', 21, 'Sundara Kanda, Sarga 62, Verse 21', 'त्वया ह्यनुक्तैर्हरिभिर्नैव शक्यं पदात्पदम्।
क्व चिद्गन्तुं हरिश्रेष्ठ ब्रूमः सत्यमिदं तु ते॥', 'tvayā hy anuktair haribhir naiva śakyaṃ padāt padam
kva cid gantuṃ hariśreṣṭha brūmaḥ satyam idaṃ tu te', null, 5062021),
('ramayana-5-62-22', 22, 'Sundara Kanda, Sarga 62, Verse 22', 'एवं तु वदतां तेषामङ्गदः प्रत्यभाषत।
बाढं गच्छाम इत्युक्त्वा उत्पपात महीतलात्॥', 'evaṃ tu vadatāṃ teṣām aṅgadaḥ pratyabhāṣata
bāḍhaṃ gacchāma ity uktvā utpapāta mahītalāt', null, 5062022),
('ramayana-5-62-23', 23, 'Sundara Kanda, Sarga 62, Verse 23', 'उत्पतन्तमनूत्पेतुः सर्वे ते हरियूथपाः।
कृत्वाकाशं निराकाशं यज्ञोत्क्षिप्ता इवानलाः॥', 'utpatantam anūtpetuḥ sarve te hariyūthapāḥ
kṛtvākāśaṃ nirākāśaṃ yajñotkṣiptā ivānalāḥ', null, 5062023),
('ramayana-5-62-24', 24, 'Sundara Kanda, Sarga 62, Verse 24', 'तेऽम्बरं सहसोत्पत्य वेगवन्तः प्लवंगमाः।
विनदन्तो महानादं घना वातेरिता यथा॥', 'te ''mbaraṃ sahasotpatya vegavantaḥ plavaṃgamāḥ
vinadanto mahānādaṃ ghanā vāteritā yathā', null, 5062024),
('ramayana-5-62-25', 25, 'Sundara Kanda, Sarga 62, Verse 25', 'अङ्गदे ह्यननुप्राप्ते सुग्रीवो वानराधिपः।
उवाच शोकोपहतं रामं कमललोचनम्॥', 'aṅgade hy ananuprāpte sugrīvo vānarādhipaḥ
uvāca śokopahataṃ rāmaṃ kamalalocanam', null, 5062025),
('ramayana-5-62-26', 26, 'Sundara Kanda, Sarga 62, Verse 26', 'समाश्वसिहि भद्रं ते दृष्टा देवी न संशयः।
नागन्तुमिह शक्यं तैरतीते समये हि नः॥', 'samāśvasihi bhadraṃ te dṛṣṭā devī na saṃśayaḥ
nāgantum iha śakyaṃ tair atīte samaye hi naḥ', null, 5062026),
('ramayana-5-62-27', 27, 'Sundara Kanda, Sarga 62, Verse 27', 'न मत्सकाशमागच्छेत्कृत्ये हि विनिपातिते।
युवराजो महाबाहुः प्लवतां प्रवरोऽङ्गदः॥', 'na matsakāśam āgacchet kṛtye hi vinipātite
yuvarājo mahābāhuḥ plavatāṃ pravaro ''ṅgadaḥ', null, 5062027),
('ramayana-5-62-28', 28, 'Sundara Kanda, Sarga 62, Verse 28', 'यद्यप्यकृतकृत्यानामीदृशः स्यादुपक्रमः।
भवेत्तु दीनवदनो भ्रान्तविप्लुतमानसः॥', 'yady apy akṛtakṛtyānām īdṛśaḥ syād upakramaḥ
bhavet tu dīnavadano bhrāntaviplutamānasaḥ', null, 5062028),
('ramayana-5-62-29', 29, 'Sundara Kanda, Sarga 62, Verse 29', 'पितृपैतामहं चैतत्पूर्वकैरभिरक्षितम्।
न मे मधुवनं हन्यादहृष्टः प्लवगेश्वरः॥', 'pitṛpaitāmahaṃ caitat pūrvakair abhirakṣitam
na me madhuvanaṃ hanyād ahṛṣṭaḥ plavageśvaraḥ', null, 5062029),
('ramayana-5-62-30', 30, 'Sundara Kanda, Sarga 62, Verse 30', 'कौसल्या सुप्रजा राम समाश्वसिहि सुव्रत।
दृष्टा देवी न संदेहो न चान्येन हनूमता।
न ह्यन्यः कर्मणो हेतुः साधने तद्विधो भवेत्॥', 'kausalyā suprajā rāma samāśvasihi suvrata
dṛṣṭā devī na saṃdeho na cānyena hanūmatā
na hy anyaḥ karmaṇo hetuḥ sādhane tadvidho bhavet', null, 5062030),
('ramayana-5-62-31', 31, 'Sundara Kanda, Sarga 62, Verse 31', 'हनूमति हि सिद्धिश्च मतिश्च मतिसत्तम।
व्यवसायश्च वीर्यं च सूर्ये तेज इव ध्रुवम्॥', 'hanūmati hi siddhiś ca matiś ca matisattama
vyavasāyaś ca vīryaṃ ca sūrye teja iva dhruvam', null, 5062031),
('ramayana-5-62-32', 32, 'Sundara Kanda, Sarga 62, Verse 32', 'जाम्बवान्यत्र नेता स्यादङ्गदश्च बलेश्वरः।
हनूमांश्चाप्यधिष्ठाता न तस्य गतिरन्यथा॥', 'jāmbavān yatra netā syād aṅgadaś ca baleśvaraḥ
hanūmāṃś cāpy adhiṣṭhātā na tasya gatir anyathā', null, 5062032),
('ramayana-5-62-33', 33, 'Sundara Kanda, Sarga 62, Verse 33', 'मा भूश्चिन्ता समायुक्तः संप्रत्यमितविक्रम॥', 'mā bhūś cintā samāyuktaḥ saṃpraty amitavikrama', null, 5062033),
('ramayana-5-62-34', 34, 'Sundara Kanda, Sarga 62, Verse 34', 'ततः किल किला शब्दं शुश्रावासन्नमम्बरे।
हनूमत्कर्मदृप्तानां नर्दतां काननौकसाम्।
किष्किन्धामुपयातानां सिद्धिं कथयतामिव॥', 'tataḥ kila kilā śabdaṃ śuśrāvāsannam ambare
hanūmat karmadṛptānāṃ nardatāṃ kānanaukasām
kiṣkindhām upayātānāṃ siddhiṃ kathayatām iva', null, 5062034),
('ramayana-5-62-35', 35, 'Sundara Kanda, Sarga 62, Verse 35', 'ततः श्रुत्वा निनादं तं कपीनां कपिसत्तमः।
आयताञ्चितलाङ्गूलः सोऽभवद्धृष्टमानसः॥', 'tataḥ śrutvā ninādaṃ taṃ kapīnāṃ kapisattamaḥ
āyatāñcitalāṅgūlaḥ so ''bhavad dhṛṣṭamānasaḥ', null, 5062035),
('ramayana-5-62-36', 36, 'Sundara Kanda, Sarga 62, Verse 36', 'आजग्मुस्तेऽपि हरयो रामदर्शनकाङ्क्षिणः।
अङ्गदं पुरतः कृत्वा हनूमन्तं च वानरम्॥', 'ājagmus te ''pi harayo rāmadarśanakāṅkṣiṇaḥ
aṅgadaṃ purataḥ kṛtvā hanūmantaṃ ca vānaram', null, 5062036),
('ramayana-5-62-37', 37, 'Sundara Kanda, Sarga 62, Verse 37', 'तेऽङ्गदप्रमुखा वीराः प्रहृष्टाश्च मुदान्विताः।
निपेतुर्हरिराजस्य समीपे राघवस्य च॥', 'te ''ṅgadapramukhā vīrāḥ prahṛṣṭāś ca mudānvitāḥ
nipetur harirājasya samīpe rāghavasya ca', null, 5062037),
('ramayana-5-62-38', 38, 'Sundara Kanda, Sarga 62, Verse 38', 'हनूमांश्च महाबहुः प्रणम्य शिरसा ततः।
नियतामक्षतां देवीं राघवाय न्यवेदयत्॥', 'hanūmāṃś ca mahābahuḥ praṇamya śirasā tataḥ
niyatām akṣatāṃ devīṃ rāghavāya nyavedayat', null, 5062038),
('ramayana-5-62-39', 39, 'Sundara Kanda, Sarga 62, Verse 39', 'निश्चितार्थं ततस्तस्मिन्सुग्रीवं पवनात्मजे।
लक्ष्मणः प्रीतिमान्प्रीतं बहुमानादवैक्षत॥', 'niścitārthaṃ tatas tasmin sugrīvaṃ pavanātmaje
lakṣmaṇaḥ prītimān prītaṃ bahumānād avaikṣata', null, 5062039),
('ramayana-5-62-40', 40, 'Sundara Kanda, Sarga 62, Verse 40', 'प्रीत्या च रममाणोऽथ राघवः परवीरहा।
बहु मानेन महता हनूमन्तमवैक्षत॥', 'prītyā ca ramamāṇo ''tha rāghavaḥ paravīrahā
bahu mānena mahatā hanūmantam avaikṣata', null, 5062040)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 63 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-63-1', 1, 'Sundara Kanda, Sarga 63, Verse 1', 'ततः प्रस्रवणं शैलं ते गत्वा चित्रकाननम्।
प्रणम्य शिरसा रामं लक्ष्मणं च महाबलम्॥', 'tataḥ prasravaṇaṃ śailaṃ te gatvā citrakānanam
praṇamya śirasā rāmaṃ lakṣmaṇaṃ ca mahābalam', null, 5063001),
('ramayana-5-63-2', 2, 'Sundara Kanda, Sarga 63, Verse 2', 'युवराजं पुरस्कृत्य सुग्रीवमभिवाद्य च।
प्रवृत्तमथ सीतायाः प्रवक्तुमुपचक्रमुः॥', 'yuvarājaṃ puraskṛtya sugrīvam abhivādya ca
pravṛttam atha sītāyāḥ pravaktum upacakramuḥ', null, 5063002),
('ramayana-5-63-3', 3, 'Sundara Kanda, Sarga 63, Verse 3', 'रावणान्तःपुरे रोधं राक्षसीभिश्च तर्जनम्।
रामे समनुरागं च यश्चापि समयः कृतः॥', 'rāvaṇāntaḥpure rodhaṃ rākṣasībhiś ca tarjanam
rāme samanurāgaṃ ca yaś cāpi samayaḥ kṛtaḥ', null, 5063003),
('ramayana-5-63-4', 4, 'Sundara Kanda, Sarga 63, Verse 4', 'एतदाख्यान्ति ते सर्वे हरयो राम संनिधौ।
वैदेहीमक्षतां श्रुत्वा रामस्तूत्तरमब्रवीत्॥', 'etad ākhyānti te sarve harayo rāma saṃnidhau
vaidehīm akṣatāṃ śrutvā rāmas tūttaram abravīt', null, 5063004),
('ramayana-5-63-5', 5, 'Sundara Kanda, Sarga 63, Verse 5', 'क्व सीता वर्तते देवी कथं च मयि वर्तते।
एतन्मे सर्वमाख्यात वैदेहीं प्रति वानराः॥', 'kva sītā vartate devī kathaṃ ca mayi vartate
etan me sarvam ākhyāta vaidehīṃ prati vānarāḥ', null, 5063005),
('ramayana-5-63-6', 6, 'Sundara Kanda, Sarga 63, Verse 6', 'रामस्य गदितं श्रुत्व हरयो रामसंनिधौ।
चोदयन्ति हनूमन्तं सीतावृत्तान्तकोविदम्॥', 'rāmasya gaditaṃ śrutva harayo rāmasaṃnidhau
codayanti hanūmantaṃ sītāvṛttāntakovidam', null, 5063006),
('ramayana-5-63-7', 7, 'Sundara Kanda, Sarga 63, Verse 7', 'श्रुत्वा तु वचनं तेषां हनूमान्मारुतात्मजः।
उवाच वाक्यं वाक्यज्ञः सीताया दर्शनं यथा॥', 'śrutvā tu vacanaṃ teṣāṃ hanūmān mārutātmajaḥ
uvāca vākyaṃ vākyajñaḥ sītāyā darśanaṃ yathā', null, 5063007),
('ramayana-5-63-8', 8, 'Sundara Kanda, Sarga 63, Verse 8', 'समुद्रं लङ्घयित्वाहं शतयोजनमायतम्।
अगच्छं जानकीं सीतां मार्गमाणो दिदृक्षया॥', 'samudraṃ laṅghayitvāhaṃ śatayojanam āyatam
agacchaṃ jānakīṃ sītāṃ mārgamāṇo didṛkṣayā', null, 5063008),
('ramayana-5-63-9', 9, 'Sundara Kanda, Sarga 63, Verse 9', 'तत्र लङ्केति नगरी रावणस्य दुरात्मनः।
दक्षिणस्य समुद्रस्य तीरे वसति दक्षिणे॥', 'tatra laṅketi nagarī rāvaṇasya durātmanaḥ
dakṣiṇasya samudrasya tīre vasati dakṣiṇe', null, 5063009),
('ramayana-5-63-10', 10, 'Sundara Kanda, Sarga 63, Verse 10', 'तत्र दृष्टा मया सीता रावणान्तःपुरे सती।
संन्यस्य त्वयि जीवन्ती रामा राम मनोरथम्॥', 'tatra dṛṣṭā mayā sītā rāvaṇāntaḥpure satī
saṃnyasya tvayi jīvantī rāmā rāma manoratham', null, 5063010),
('ramayana-5-63-11', 11, 'Sundara Kanda, Sarga 63, Verse 11', 'दृष्टा मे राक्षसी मध्ये तर्ज्यमाना मुहुर्मुहुः।
राक्षसीभिर्विरूपाभी रक्षिता प्रमदावने॥', 'dṛṣṭā me rākṣasī madhye tarjyamānā muhur muhuḥ
rākṣasībhir virūpābhī rakṣitā pramadāvane', null, 5063011),
('ramayana-5-63-12', 12, 'Sundara Kanda, Sarga 63, Verse 12', 'दुःखमापद्यते देवी तवादुःखोचिता सती।
रावणान्तःपुरे रुद्ध्वा राक्षसीभिः सुरक्षिता॥', 'duḥkham āpadyate devī tavāduḥkhocitā satī
rāvaṇāntaḥpure ruddhvā rākṣasībhiḥ surakṣitā', null, 5063012),
('ramayana-5-63-13', 13, 'Sundara Kanda, Sarga 63, Verse 13', 'एकवेणीधरा दीना त्वयि चिन्तापरायणा।
अधःशय्या विवर्णाङ्गी पद्मिनीव हिमागमे॥', 'ekaveṇīdharā dīnā tvayi cintāparāyaṇā
adhaḥśayyā vivarṇāṅgī padminīva himāgame', null, 5063013),
('ramayana-5-63-14', 14, 'Sundara Kanda, Sarga 63, Verse 14', 'रावणाद्विनिवृत्तार्था मर्तव्यकृतनिश्चया।
देवी कथं चित्काकुत्स्थ त्वन्मना मार्गिता मया॥', 'rāvaṇād vinivṛttārthā martavyakṛtaniścayā
devī kathaṃ cit kākutstha tvanmanā mārgitā mayā', null, 5063014),
('ramayana-5-63-15', 15, 'Sundara Kanda, Sarga 63, Verse 15', 'इक्ष्वाकुवंशविख्यातिं शनैः कीर्तयतानघ।
स मया नरशार्दूल विश्वासमुपपादिता॥', 'ikṣvākuvaṃśavikhyātiṃ śanaiḥ kīrtayatānagha
sa mayā naraśārdūla viśvāsam upapāditā', null, 5063015),
('ramayana-5-63-16', 16, 'Sundara Kanda, Sarga 63, Verse 16', 'ततः संभाषिता देवी सर्वमर्थं च दर्शिता।
रामसुग्रीवसख्यं च श्रुत्वा प्रीतिमुपागता॥', 'tataḥ saṃbhāṣitā devī sarvam arthaṃ ca darśitā
rāmasugrīvasakhyaṃ ca śrutvā prītim upāgatā', null, 5063016),
('ramayana-5-63-17', 17, 'Sundara Kanda, Sarga 63, Verse 17', 'नियतः समुदाचारो भक्तिश्चास्यास्तथा त्वयि।
एवं मया महाभागा दृष्टा जनकनन्दिनी।
उग्रेण तपसा युक्ता त्वद्भक्त्या पुरुषर्षभ॥', 'niyataḥ samudācāro bhaktiś cāsyās tathā tvayi
evaṃ mayā mahābhāgā dṛṣṭā janakanandinī
ugreṇa tapasā yuktā tvadbhaktyā puruṣarṣabha', null, 5063017),
('ramayana-5-63-18', 18, 'Sundara Kanda, Sarga 63, Verse 18', 'अभिज्ञानं च मे दत्तं यथावृत्तं तवान्तिके।
चित्रकूटे महाप्राज्ञ वायसं प्रति राघव॥', 'abhijñānaṃ ca me dattaṃ yathāvṛttaṃ tavāntike
citrakūṭe mahāprājña vāyasaṃ prati rāghava', null, 5063018),
('ramayana-5-63-19', 19, 'Sundara Kanda, Sarga 63, Verse 19', 'विज्ञाप्यश्च नर व्याघ्रो रामो वायुसुत त्वया।
अखिलेनेह यद्दृष्टमिति मामाह जानकी॥', 'vijñāpyaś ca nara vyāghro rāmo vāyusuta tvayā
akhileneha yad dṛṣṭam iti mām āha jānakī', null, 5063019),
('ramayana-5-63-20', 20, 'Sundara Kanda, Sarga 63, Verse 20', 'इदं चास्मै प्रदातव्यं यत्नात्सुपरिरक्षितम्।
ब्रुवता वचनान्येवं सुग्रीवस्योपशृण्वतः॥', 'idaṃ cāsmai pradātavyaṃ yatnāt suparirakṣitam
bruvatā vacanāny evaṃ sugrīvasyopaśṛṇvataḥ', null, 5063020),
('ramayana-5-63-21', 21, 'Sundara Kanda, Sarga 63, Verse 21', 'एष चूडामणिः श्रीमान्मया ते यत्नरक्षितः।
मनःशिलायास्तिकलस्तं स्मरस्वेति चाब्रवीत्॥', 'eṣa cūḍāmaṇiḥ śrīmān mayā te yatnarakṣitaḥ
manaḥśilāyās tikalas taṃ smarasveti cābravīt', null, 5063021),
('ramayana-5-63-22', 22, 'Sundara Kanda, Sarga 63, Verse 22', 'एष निर्यातितः श्रीमान्मया ते वारिसंभवः।
एतं दृष्ट्वा प्रमोदिष्ये व्यसने त्वामिवानघ॥', 'eṣa niryātitaḥ śrīmān mayā te vārisaṃbhavaḥ
etaṃ dṛṣṭvā pramodiṣye vyasane tvām ivānagha', null, 5063022),
('ramayana-5-63-23', 23, 'Sundara Kanda, Sarga 63, Verse 23', 'जीवितं धारयिष्यामि मासं दशरथात्मज।
ऊर्ध्वं मासान्न जीवेयं रक्षसां वशमागता॥', 'jīvitaṃ dhārayiṣyāmi māsaṃ daśarathātmaja
ūrdhvaṃ māsān na jīveyaṃ rakṣasāṃ vaśam āgatā', null, 5063023),
('ramayana-5-63-24', 24, 'Sundara Kanda, Sarga 63, Verse 24', 'इति मामब्रवीत्सीता कृशाङ्गी धर्म चारिणी।
रावणान्तःपुरे रुद्धा मृगीवोत्फुल्ललोचना॥', 'iti mām abravīt sītā kṛśāṅgī dharma cāriṇī
rāvaṇāntaḥpure ruddhā mṛgīvotphullalocanā', null, 5063024),
('ramayana-5-63-25', 25, 'Sundara Kanda, Sarga 63, Verse 25', 'एतदेव मयाख्यातं सर्वं राघव यद्यथा।
सर्वथा सागरजले संतारः प्रविधीयताम्॥', 'etad eva mayākhyātaṃ sarvaṃ rāghava yad yathā
sarvathā sāgarajale saṃtāraḥ pravidhīyatām', null, 5063025),
('ramayana-5-63-26', 26, 'Sundara Kanda, Sarga 63, Verse 26', 'तौ जाताश्वासौ राजपुत्रौ विदित्वा तच्चाभिज्ञानं राघवाय प्रदाय।
देव्या चाख्यातं सर्वमेवानुपूर्व्याद्वाचा संपूर्णं वायुपुत्रः शशंस॥', 'tau jātāśvāsau rājaputrau viditvā tac cābhijñānaṃ rāghavāya pradāya
devyā cākhyātaṃ sarvam evānupūrvyād vācā saṃpūrṇaṃ vāyuputraḥ śaśaṃsa', null, 5063026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 64 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-64-1', 1, 'Sundara Kanda, Sarga 64, Verse 1', 'एवमुक्तो हनुमता रामो दशरथात्मजः।
तं मणिं हृदये कृत्वा प्ररुरोद सलक्ष्मणः॥', 'evam ukto hanumatā rāmo daśarathātmajaḥ
taṃ maṇiṃ hṛdaye kṛtvā praruroda salakṣmaṇaḥ', null, 5064001),
('ramayana-5-64-2', 2, 'Sundara Kanda, Sarga 64, Verse 2', 'तं तु दृष्ट्वा मणिश्रेष्ठं राघवः शोककर्शितः।
नेत्राभ्यामश्रुपूर्णाभ्यां सुग्रीवमिदमब्रवीत्॥', 'taṃ tu dṛṣṭvā maṇiśreṣṭhaṃ rāghavaḥ śokakarśitaḥ
netrābhyām aśrupūrṇābhyāṃ sugrīvam idam abravīt', null, 5064002),
('ramayana-5-64-3', 3, 'Sundara Kanda, Sarga 64, Verse 3', 'यथैव धेनुः स्रवति स्नेहाद्वत्सस्य वत्सला।
तथा ममापि हृदयं मणिरत्नस्य दर्शनात्॥', 'yathaiva dhenuḥ sravati snehād vatsasya vatsalā
tathā mamāpi hṛdayaṃ maṇiratnasya darśanāt', null, 5064003),
('ramayana-5-64-4', 4, 'Sundara Kanda, Sarga 64, Verse 4', 'मणिरत्नमिदं दत्तं वैदेह्याः श्वशुरेण मे।
वधूकाले यथा बद्धमधिकं मूर्ध्नि शोभते॥', 'maṇiratnam idaṃ dattaṃ vaidehyāḥ śvaśureṇa me
vadhūkāle yathā baddham adhikaṃ mūrdhni śobhate', null, 5064004),
('ramayana-5-64-5', 5, 'Sundara Kanda, Sarga 64, Verse 5', 'अयं हि जलसंभूतो मणिः प्रवरपूजितः।
यज्ञे परमतुष्टेन दत्तः शक्रेण धीमता॥', 'ayaṃ hi jalasaṃbhūto maṇiḥ pravarapūjitaḥ
yajñe paramatuṣṭena dattaḥ śakreṇa dhīmatā', null, 5064005),
('ramayana-5-64-6', 6, 'Sundara Kanda, Sarga 64, Verse 6', 'इमं दृष्ट्वा मणिश्रेष्ठं तथा तातस्य दर्शनम्।
अद्यास्म्यवगतः सौम्य वैदेहस्य तथा विभोः॥', 'imaṃ dṛṣṭvā maṇiśreṣṭhaṃ tathā tātasya darśanam
adyāsmy avagataḥ saumya vaidehasya tathā vibhoḥ', null, 5064006),
('ramayana-5-64-7', 7, 'Sundara Kanda, Sarga 64, Verse 7', 'अयं हि शोभते तस्याः प्रियाया मूर्ध्नि मे मणिः।
अद्यास्य दर्शनेनाहं प्राप्तां तामिव चिन्तये॥', 'ayaṃ hi śobhate tasyāḥ priyāyā mūrdhni me maṇiḥ
adyāsya darśanenāhaṃ prāptāṃ tām iva cintaye', null, 5064007),
('ramayana-5-64-8', 8, 'Sundara Kanda, Sarga 64, Verse 8', 'किमाह सीता वैदेही ब्रूहि सौम्य पुनः पुनः।
परासुमिव तोयेन सिञ्चन्ती वाक्यवारिणा॥', 'kim āha sītā vaidehī brūhi saumya punaḥ punaḥ
parāsum iva toyena siñcantī vākyavāriṇā', null, 5064008),
('ramayana-5-64-9', 9, 'Sundara Kanda, Sarga 64, Verse 9', 'इतस्तु किं दुःखतरं यदिमं वारिसंभवम्।
मणिं पश्यामि सौमित्रे वैदेहीमागतं विना॥', 'itas tu kiṃ duḥkhataraṃ yad imaṃ vārisaṃbhavam
maṇiṃ paśyāmi saumitre vaidehīm āgataṃ vinā', null, 5064009),
('ramayana-5-64-10', 10, 'Sundara Kanda, Sarga 64, Verse 10', 'चिरं जीवति वैदेही यदि मासं धरिष्यति।
क्षणं सौम्य न जीवेयं विना तामसितेक्षणाम्॥', 'ciraṃ jīvati vaidehī yadi māsaṃ dhariṣyati
kṣaṇaṃ saumya na jīveyaṃ vinā tām asitekṣaṇām', null, 5064010),
('ramayana-5-64-11', 11, 'Sundara Kanda, Sarga 64, Verse 11', 'नय मामपि तं देशं यत्र दृष्टा मम प्रिया।
न तिष्ठेयं क्षणमपि प्रवृत्तिमुपलभ्य च॥', 'naya mām api taṃ deśaṃ yatra dṛṣṭā mama priyā
na tiṣṭheyaṃ kṣaṇam api pravṛttim upalabhya ca', null, 5064011),
('ramayana-5-64-12', 12, 'Sundara Kanda, Sarga 64, Verse 12', 'कथं सा मम सुश्रोणि भीरु भीरुः सती तदा।
भयावहानां घोराणां मध्ये तिष्ठति रक्षसाम्॥', 'kathaṃ sā mama suśroṇi bhīru bhīruḥ satī tadā
bhayāvahānāṃ ghorāṇāṃ madhye tiṣṭhati rakṣasām', null, 5064012),
('ramayana-5-64-13', 13, 'Sundara Kanda, Sarga 64, Verse 13', 'शारदस्तिमिरोन्मुखो नूनं चन्द्र इवाम्बुदैः।
आवृतं वदनं तस्या न विराजति राक्षसैः॥', 'śāradas timironmukho nūnaṃ candra ivāmbudaiḥ
āvṛtaṃ vadanaṃ tasyā na virājati rākṣasaiḥ', null, 5064013),
('ramayana-5-64-14', 14, 'Sundara Kanda, Sarga 64, Verse 14', 'किमाह सीता हनुमंस्तत्त्वतः कथयस्व मे।
एतेन खलु जीविष्ये भेषजेनातुरो यथा॥', 'kim āha sītā hanumaṃs tattvataḥ kathayasva me
etena khalu jīviṣye bheṣajenāturo yathā', null, 5064014),
('ramayana-5-64-15', 15, 'Sundara Kanda, Sarga 64, Verse 15', 'मधुरा मधुरालापा किमाह मम भामिनी।
मद्विहीना वरारोहा हनुमन्कथयस्व मे।
दुःखाद्दुःखतरं प्राप्य कथं जीवति जानकी॥', 'madhurā madhurālāpā kim āha mama bhāminī
madvihīnā varārohā hanuman kathayasva me
duḥkhād duḥkhataraṃ prāpya kathaṃ jīvati jānakī', null, 5064015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 65 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-65-1', 1, 'Sundara Kanda, Sarga 65, Verse 1', 'एवमुक्तस्तु हनुमान्राघवेण महात्मना।
सीताया भाषितं सर्वं न्यवेदयत राघवे॥', 'evam uktas tu hanumān rāghaveṇa mahātmanā
sītāyā bhāṣitaṃ sarvaṃ nyavedayata rāghave', null, 5065001),
('ramayana-5-65-2', 2, 'Sundara Kanda, Sarga 65, Verse 2', 'इदमुक्तवती देवी जानकी पुरुषर्षभ।
पूर्ववृत्तमभिज्ञानं चित्रकूटे यथा तथम्॥', 'idam uktavatī devī jānakī puruṣarṣabha
pūrvavṛttam abhijñānaṃ citrakūṭe yathā tatham', null, 5065002),
('ramayana-5-65-3', 3, 'Sundara Kanda, Sarga 65, Verse 3', 'सुखसुप्ता त्वया सार्धं जानकी पूर्वमुत्थिता।
वायसः सहसोत्पत्य विरराद स्तनान्तरे॥', 'sukhasuptā tvayā sārdhaṃ jānakī pūrvam utthitā
vāyasaḥ sahasotpatya virarāda stanāntare', null, 5065003),
('ramayana-5-65-4', 4, 'Sundara Kanda, Sarga 65, Verse 4', 'पर्यायेण च सुप्तस्त्वं देव्यङ्के भरताग्रज।
पुनश्च किल पक्षी स देव्या जनयति व्यथाम्॥', 'paryāyeṇa ca suptas tvaṃ devyaṅke bharatāgraja
punaś ca kila pakṣī sa devyā janayati vyathām', null, 5065004),
('ramayana-5-65-5', 5, 'Sundara Kanda, Sarga 65, Verse 5', 'ततः पुनरुपागम्य विरराद भृशं किल।
ततस्त्वं बोधितस्तस्याः शोणितेन समुक्षितः॥', 'tataḥ punar upāgamya virarāda bhṛśaṃ kila
tatas tvaṃ bodhitas tasyāḥ śoṇitena samukṣitaḥ', null, 5065005),
('ramayana-5-65-6', 6, 'Sundara Kanda, Sarga 65, Verse 6', 'वायसेन च तेनैव सततं बाध्यमानया।
बोधितः किल देव्यास्त्वं सुखसुप्तः परंतप॥', 'vāyasena ca tenaiva satataṃ bādhyamānayā
bodhitaḥ kila devyās tvaṃ sukhasuptaḥ paraṃtapa', null, 5065006),
('ramayana-5-65-7', 7, 'Sundara Kanda, Sarga 65, Verse 7', 'तां तु दृष्ट्वा महाबाहो रादितां च स्तनान्तरे।
आशीविष इव क्रुद्धो निःश्वसन्नभ्यभाषथाः॥', 'tāṃ tu dṛṣṭvā mahābāho rāditāṃ ca stanāntare
āśīviṣa iva kruddho niḥśvasann abhyabhāṣathāḥ', null, 5065007),
('ramayana-5-65-8', 8, 'Sundara Kanda, Sarga 65, Verse 8', 'नखाग्रैः केन ते भीरु दारितं तु स्तनान्तरम्।
कः क्रीडति सरोषेण पञ्चवक्त्रेण भोगिना॥', 'nakhāgraiḥ kena te bhīru dāritaṃ tu stanāntaram
kaḥ krīḍati saroṣeṇa pañcavaktreṇa bhoginā', null, 5065008),
('ramayana-5-65-9', 9, 'Sundara Kanda, Sarga 65, Verse 9', 'निरीक्षमाणः सहसा वायसं समवैक्षताः।
नखैः सरुधिरैस्तीक्ष्णैर्मामेवाभिमुखं स्थितम्॥', 'nirīkṣamāṇaḥ sahasā vāyasaṃ samavaikṣatāḥ
nakhaiḥ sarudhirais tīkṣṇair mām evābhimukhaṃ sthitam', null, 5065009),
('ramayana-5-65-10', 10, 'Sundara Kanda, Sarga 65, Verse 10', 'सुतः किल स शक्रस्य वायसः पततां वरः।
धरान्तरचरः शीघ्रं पवनस्य गतौ समः॥', 'sutaḥ kila sa śakrasya vāyasaḥ patatāṃ varaḥ
dharāntaracaraḥ śīghraṃ pavanasya gatau samaḥ', null, 5065010),
('ramayana-5-65-11', 11, 'Sundara Kanda, Sarga 65, Verse 11', 'ततस्तस्मिन्महाबाहो कोपसंवर्तितेक्षणः।
वायसे त्वं कृत्वाः क्रूरां मतिं मतिमतां वर॥', 'tatas tasmin mahābāho kopasaṃvartitekṣaṇaḥ
vāyase tvaṃ kṛtvāḥ krūrāṃ matiṃ matimatāṃ vara', null, 5065011),
('ramayana-5-65-12', 12, 'Sundara Kanda, Sarga 65, Verse 12', 'स दर्भं संस्तराद्गृह्य ब्रह्मास्त्रेण न्ययोजयः।
स दीप्त इव कालाग्निर्जज्वालाभिमुखः खगम्॥', 'sa darbhaṃ saṃstarād gṛhya brahmāstreṇa nyayojayaḥ
sa dīpta iva kālāgnir jajvālābhimukhaḥ khagam', null, 5065012),
('ramayana-5-65-13', 13, 'Sundara Kanda, Sarga 65, Verse 13', 'स त्वं प्रदीप्तं चिक्षेप दर्भं तं वायसं प्रति।
ततस्तु वायसं दीप्तः स दर्भोऽनुजगाम ह॥', 'sa tvaṃ pradīptaṃ cikṣepa darbhaṃ taṃ vāyasaṃ prati
tatas tu vāyasaṃ dīptaḥ sa darbho ''nujagāma ha', null, 5065013),
('ramayana-5-65-14', 14, 'Sundara Kanda, Sarga 65, Verse 14', 'स पित्रा च परित्यक्तः सुरैः सर्वैर्महर्षिभिः।
त्रींल्लोकान्संपरिक्रम्य त्रातारं नाधिगच्छति॥', 'sa pitrā ca parityaktaḥ suraiḥ sarvair maharṣibhiḥ
trīṃl lokān saṃparikramya trātāraṃ nādhigacchati', null, 5065014),
('ramayana-5-65-15', 15, 'Sundara Kanda, Sarga 65, Verse 15', 'तं त्वं निपतितं भूमौ शरण्यः शरणागतम्।
वधार्हमपि काकुत्स्थ कृपया परिपालयः॥', 'taṃ tvaṃ nipatitaṃ bhūmau śaraṇyaḥ śaraṇāgatam
vadhārham api kākutstha kṛpayā paripālayaḥ', null, 5065015),
('ramayana-5-65-16', 16, 'Sundara Kanda, Sarga 65, Verse 16', 'मोघमस्त्रं न शक्यं तु कर्तुमित्येव राघव।
ततस्तस्याक्षिकाकस्य हिनस्ति स्म स दक्षिणम्॥', 'mogham astraṃ na śakyaṃ tu kartum ity eva rāghava
tatas tasyākṣikākasya hinasti sma sa dakṣiṇam', null, 5065016),
('ramayana-5-65-17', 17, 'Sundara Kanda, Sarga 65, Verse 17', 'राम त्वां स नमस्कृत्वा राज्ञो दशरथस्य च।
विसृष्टस्तु तदा काकः प्रतिपेदे खमालयम्॥', 'rāma tvāṃ sa namaskṛtvā rājño daśarathasya ca
visṛṣṭas tu tadā kākaḥ pratipede kham ālayam', null, 5065017),
('ramayana-5-65-18', 18, 'Sundara Kanda, Sarga 65, Verse 18', 'एवमस्त्रविदां श्रेष्ठः सत्त्ववाञ्शीलवानपि।
किमर्थमस्त्रं रक्षःसु न योजयसि राघव॥', 'evam astravidāṃ śreṣṭhaḥ sattvavāñ śīlavān api
kimartham astraṃ rakṣaḥsu na yojayasi rāghava', null, 5065018),
('ramayana-5-65-19', 19, 'Sundara Kanda, Sarga 65, Verse 19', 'न नागा नापि गन्धर्वा नासुरा न मरुद्गणाः।
तव राम मुखे स्थातुं शक्ताः प्रतिसमाधितुम्॥', 'na nāgā nāpi gandharvā nāsurā na marudgaṇāḥ
tava rāma mukhe sthātuṃ śaktāḥ pratisamādhitum', null, 5065019),
('ramayana-5-65-20', 20, 'Sundara Kanda, Sarga 65, Verse 20', 'तव वीर्यवतः कच्चिन्मयि यद्यस्ति संभ्रमः।
क्षिप्रं सुनिशितैर्बाणैर्हन्यतां युधि रावणः॥', 'tava vīryavataḥ kaccin mayi yady asti saṃbhramaḥ
kṣipraṃ suniśitair bāṇair hanyatāṃ yudhi rāvaṇaḥ', null, 5065020),
('ramayana-5-65-21', 21, 'Sundara Kanda, Sarga 65, Verse 21', 'भ्रातुरादेशमादाय लक्ष्मणो वा परंतपः।
स किमर्थं नरवरो न मां रक्षति राघवः॥', 'bhrātur ādeśam ādāya lakṣmaṇo vā paraṃtapaḥ
sa kimarthaṃ naravaro na māṃ rakṣati rāghavaḥ', null, 5065021),
('ramayana-5-65-22', 22, 'Sundara Kanda, Sarga 65, Verse 22', 'शक्तौ तौ पुरुषव्याघ्रौ वाय्वग्निसमतेजसौ।
सुराणामपि दुर्धर्षौ किमर्थं मामुपेक्षतः॥', 'śaktau tau puruṣavyāghrau vāyvagnisamatejasau
surāṇām api durdharṣau kimarthaṃ mām upekṣataḥ', null, 5065022),
('ramayana-5-65-23', 23, 'Sundara Kanda, Sarga 65, Verse 23', 'ममैव दुष्कृतं किं चिन्महदस्ति न संशयः।
समर्थौ सहितौ यन्मां नापेक्षेते परंतपौ॥', 'mamaiva duṣkṛtaṃ kiṃ cin mahad asti na saṃśayaḥ
samarthau sahitau yan māṃ nāpekṣete paraṃtapau', null, 5065023),
('ramayana-5-65-24', 24, 'Sundara Kanda, Sarga 65, Verse 24', 'वैदेह्या वचनं श्रुत्वा करुणं साश्रुभाषितम्।
पुनरप्यहमार्यां तामिदं वचनमब्रुवम्॥', 'vaidehyā vacanaṃ śrutvā karuṇaṃ sāśrubhāṣitam
punar apy aham āryāṃ tām idaṃ vacanam abruvam', null, 5065024),
('ramayana-5-65-25', 25, 'Sundara Kanda, Sarga 65, Verse 25', 'त्वच्छोकविमुखो रामो देवि सत्येन ते शपे।
रामे दुःखाभिभूते च लक्ष्मणः परितप्यते॥', 'tvacchokavimukho rāmo devi satyena te śape
rāme duḥkhābhibhūte ca lakṣmaṇaḥ paritapyate', null, 5065025),
('ramayana-5-65-26', 26, 'Sundara Kanda, Sarga 65, Verse 26', 'कथं चिद्भवती दृष्टा न कालः परिशोचितुम्।
इमं मुहूर्तं दुःखानामन्तं द्रक्ष्यसि भामिनि॥', 'kathaṃ cid bhavatī dṛṣṭā na kālaḥ pariśocitum
imaṃ muhūrtaṃ duḥkhānām antaṃ drakṣyasi bhāmini', null, 5065026),
('ramayana-5-65-27', 27, 'Sundara Kanda, Sarga 65, Verse 27', 'तावुभौ नरशार्दूलौ राजपुत्रावरिंदमौ।
त्वद्दर्शनकृतोत्साहौ लङ्कां भस्मीकरिष्यतः॥', 'tāv ubhau naraśārdūlau rājaputrāv ariṃdamau
tvaddarśanakṛtotsāhau laṅkāṃ bhasmīkariṣyataḥ', null, 5065027),
('ramayana-5-65-28', 28, 'Sundara Kanda, Sarga 65, Verse 28', 'हत्वा च समरे रौद्रं रावणं सह बान्धवम्।
राघवस्त्वां महाबाहुः स्वां पुरीं नयते ध्रुवम्॥', 'hatvā ca samare raudraṃ rāvaṇaṃ saha bāndhavam
rāghavas tvāṃ mahābāhuḥ svāṃ purīṃ nayate dhruvam', null, 5065028),
('ramayana-5-65-29', 29, 'Sundara Kanda, Sarga 65, Verse 29', 'यत्तु रामो विजानीयादभिज्ञानमनिन्दिते।
प्रीतिसंजननं तस्य प्रदातुं तत्त्वमर्हसि॥', 'yat tu rāmo vijānīyād abhijñānam anindite
prītisaṃjananaṃ tasya pradātuṃ tattvam arhasi', null, 5065029),
('ramayana-5-65-30', 30, 'Sundara Kanda, Sarga 65, Verse 30', 'साभिवीक्ष्य दिशः सर्वा वेण्युद्ग्रथनमुत्तमम्।
मुक्त्वा वस्त्राद्ददौ मह्यं मणिमेतं महाबल॥', 'sābhivīkṣya diśaḥ sarvā veṇyudgrathanam uttamam
muktvā vastrād dadau mahyaṃ maṇim etaṃ mahābala', null, 5065030),
('ramayana-5-65-31', 31, 'Sundara Kanda, Sarga 65, Verse 31', 'प्रतिगृह्य मणिं दिव्यं तव हेतो रघूत्तम।
शिरसा संप्रणम्यैनामहमागमने त्वरे॥', 'pratigṛhya maṇiṃ divyaṃ tava heto raghūttama
śirasā saṃpraṇamyainām aham āgamane tvare', null, 5065031),
('ramayana-5-65-32', 32, 'Sundara Kanda, Sarga 65, Verse 32', 'गमने च कृतोत्साहमवेक्ष्य वरवर्णिनी।
विवर्धमानं च हि मामुवाच जनकात्मजा।
अश्रुपूर्णमुखी दीना बाष्पसंदिग्धभाषिणी॥', 'gamane ca kṛtotsāham avekṣya varavarṇinī
vivardhamānaṃ ca hi mām uvāca janakātmajā
aśrupūrṇamukhī dīnā bāṣpasaṃdigdhabhāṣiṇī', null, 5065032),
('ramayana-5-65-33', 33, 'Sundara Kanda, Sarga 65, Verse 33', 'हनुमन्सिंहसंकाशौ तावुभौ रामलक्ष्मणौ।
सुग्रीवं च सहामात्यं सर्वान्ब्रूया अनामयम्॥', 'hanuman siṃhasaṃkāśau tāv ubhau rāmalakṣmaṇau
sugrīvaṃ ca sahāmātyaṃ sarvān brūyā anāmayam', null, 5065033),
('ramayana-5-65-34', 34, 'Sundara Kanda, Sarga 65, Verse 34', 'यथा च स महाबाहुर्मां तारयति राघवः।
अस्माद्दुःखाम्बुसंरोधात्तत्समाधातुमर्हसि॥', 'yathā ca sa mahābāhur māṃ tārayati rāghavaḥ
asmād duḥkhāmbusaṃrodhāt tat samādhātum arhasi', null, 5065034),
('ramayana-5-65-35', 35, 'Sundara Kanda, Sarga 65, Verse 35', 'इमं च तीव्रं मम शोकवेगं रक्षोभिरेभिः परिभर्त्सनं च।
ब्रूयास्तु रामस्य गतः समीपं शिवश्च तेऽध्वास्तु हरिप्रवीर॥', 'imaṃ ca tīvraṃ mama śokavegaṃ rakṣobhir ebhiḥ paribhartsanaṃ ca
brūyās tu rāmasya gataḥ samīpaṃ śivaś ca te ''dhvāstu haripravīra', null, 5065035),
('ramayana-5-65-36', 36, 'Sundara Kanda, Sarga 65, Verse 36', 'एतत्तवार्या नृपराजसिंह सीता वचः प्राह विषादपूर्वम्।
एतच्च बुद्ध्वा गदितं मया त्वं श्रद्धत्स्व सीतां कुशलां समग्राम्॥', 'etat tavāryā nṛparājasiṃha sītā vacaḥ prāha viṣādapūrvam
etac ca buddhvā gaditaṃ mayā tvaṃ śraddhatsva sītāṃ kuśalāṃ samagrām', null, 5065036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 66 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 5 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-5-66-1', 1, 'Sundara Kanda, Sarga 66, Verse 1', 'अथाहमुत्तरं देव्या पुनरुक्तः ससंभ्रमम्।
तव स्नेहान्नरव्याघ्र सौहार्यादनुमान्य च॥', 'athāham uttaraṃ devyā punar uktaḥ sasaṃbhramam
tava snehān naravyāghra sauhāryād anumānya ca', null, 5066001),
('ramayana-5-66-2', 2, 'Sundara Kanda, Sarga 66, Verse 2', 'एवं बहुविधं वाच्यो रामो दाशरथिस्त्वया।
यथा मामाप्नुयाच्छीघ्रं हत्वा रावणमाहवे॥', 'evaṃ bahuvidhaṃ vācyo rāmo dāśarathis tvayā
yathā mām āpnuyāc chīghraṃ hatvā rāvaṇam āhave', null, 5066002),
('ramayana-5-66-3', 3, 'Sundara Kanda, Sarga 66, Verse 3', 'यदि वा मन्यसे वीर वसैकाहमरिंदम।
कस्मिंश्चित्संवृते देशे विश्रान्तः श्वो गमिष्यसि॥', 'yadi vā manyase vīra vasaikāham ariṃdama
kasmiṃś cit saṃvṛte deśe viśrāntaḥ śvo gamiṣyasi', null, 5066003),
('ramayana-5-66-4', 4, 'Sundara Kanda, Sarga 66, Verse 4', 'मम चाप्यल्पभाग्यायाः साम्निध्यात्तव वानर।
अस्य शोकविपाकस्य मुहूर्तं स्याद्विमोक्षणम्॥', 'mama cāpy alpabhāgyāyāḥ sāmnidhyāt tava vānara
asya śokavipākasya muhūrtaṃ syād vimokṣaṇam', null, 5066004),
('ramayana-5-66-5', 5, 'Sundara Kanda, Sarga 66, Verse 5', 'गते हि त्वयि विक्रान्ते पुनरागमनाय वै।
प्राणानामपि संदेहो मम स्यान्नात्र संशयः॥', 'gate hi tvayi vikrānte punarāgamanāya vai
prāṇānām api saṃdeho mama syān nātra saṃśayaḥ', null, 5066005),
('ramayana-5-66-6', 6, 'Sundara Kanda, Sarga 66, Verse 6', 'तवादर्शनजः शोको भूयो मां परितापयेत्।
दुःखाद्दुःखपराभूतां दुर्गतां दुःखभागिनीम्॥', 'tavādarśanajaḥ śoko bhūyo māṃ paritāpayet
duḥkhād duḥkhaparābhūtāṃ durgatāṃ duḥkhabhāginīm', null, 5066006),
('ramayana-5-66-7', 7, 'Sundara Kanda, Sarga 66, Verse 7', 'अयं तु वीरसंदेहस्तिष्ठतीव ममाग्रतः।
सुमहांस्त्वत्सहायेषु हर्यृक्षेषु असंशयः॥', 'ayaṃ tu vīrasaṃdehas tiṣṭhatīva mamāgrataḥ
sumahāṃs tvatsahāyeṣu haryṛkṣeṣu asaṃśayaḥ', null, 5066007),
('ramayana-5-66-8', 8, 'Sundara Kanda, Sarga 66, Verse 8', 'कथं नु खलु दुष्पारं तरिष्यन्ति महोदधिम्।
तानि हर्यृक्षसैन्यानि तौ वा नरवरात्मजौ॥', 'kathaṃ nu khalu duṣpāraṃ tariṣyanti mahodadhim
tāni haryṛkṣasainyāni tau vā naravarātmajau', null, 5066008),
('ramayana-5-66-9', 9, 'Sundara Kanda, Sarga 66, Verse 9', 'त्रयाणामेव भूतानां सागरस्यास्य लङ्घने।
शक्तिः स्याद्वैनतेयस्य वायोर्वा तव वानघ॥', 'trayāṇām eva bhūtānāṃ sāgarasyāsya laṅghane
śaktiḥ syād vainateyasya vāyor vā tava vānagha', null, 5066009),
('ramayana-5-66-10', 10, 'Sundara Kanda, Sarga 66, Verse 10', 'तदस्मिन्कार्यनियोगे वीरैवं दुरतिक्रमे।
किं पश्यसि समाधानं ब्रूहि कार्यविदां वर॥', 'tad asmin kāryaniyoge vīraivaṃ duratikrame
kiṃ paśyasi samādhānaṃ brūhi kāryavidāṃ vara', null, 5066010),
('ramayana-5-66-11', 11, 'Sundara Kanda, Sarga 66, Verse 11', 'काममस्य त्वमेवैकः कार्यस्य परिसाधने।
पर्याप्तः परवीरघ्न यशस्यस्ते बलोदयः॥', 'kāmam asya tvam evaikaḥ kāryasya parisādhane
paryāptaḥ paravīraghna yaśasyas te balodayaḥ', null, 5066011),
('ramayana-5-66-12', 12, 'Sundara Kanda, Sarga 66, Verse 12', 'बलैः समग्रैर्यदि मां हत्वा रावणमाहवे।
विजयी स्वां पुरीं रामो नयेत्तत्स्याद्यशस्करम्॥', 'balaiḥ samagrair yadi māṃ hatvā rāvaṇam āhave
vijayī svāṃ purīṃ rāmo nayet tat syād yaśaskaram', null, 5066012),
('ramayana-5-66-13', 13, 'Sundara Kanda, Sarga 66, Verse 13', 'यथाहं तस्य वीरस्य वनादुपधिना हृता।
रक्षसा तद्भयादेव तथा नार्हति राघवः॥', 'yathāhaṃ tasya vīrasya vanād upadhinā hṛtā
rakṣasā tad bhayād eva tathā nārhati rāghavaḥ', null, 5066013),
('ramayana-5-66-14', 14, 'Sundara Kanda, Sarga 66, Verse 14', 'बलैस्तु संकुलां कृत्वा लङ्कां परबलार्दनः।
मां नयेद्यदि काकुत्स्थस्तत्तस्य सदृशं भवेत्॥', 'balais tu saṃkulāṃ kṛtvā laṅkāṃ parabalārdanaḥ
māṃ nayed yadi kākutsthas tat tasya sadṛśaṃ bhavet', null, 5066014),
('ramayana-5-66-15', 15, 'Sundara Kanda, Sarga 66, Verse 15', 'तद्यथा तस्य विक्रान्तमनुरूपं महात्मनः।
भवत्याहवशूरस्य तथा त्वमुपपादय॥', 'tad yathā tasya vikrāntam anurūpaṃ mahātmanaḥ
bhavaty āhavaśūrasya tathā tvam upapādaya', null, 5066015),
('ramayana-5-66-16', 16, 'Sundara Kanda, Sarga 66, Verse 16', 'तदर्थोपहितं वाक्यं प्रश्रितं हेतुसंहितम्।
निशम्याहं ततः शेषं वाक्यमुत्तरमब्रुवम्॥', 'tad arthopahitaṃ vākyaṃ praśritaṃ hetusaṃhitam
niśamyāhaṃ tataḥ śeṣaṃ vākyam uttaram abruvam', null, 5066016),
('ramayana-5-66-17', 17, 'Sundara Kanda, Sarga 66, Verse 17', 'देवि हर्यृक्षसैन्यानामीश्वरः प्लवतां वरः।
सुग्रीवः सत्त्वसंपन्नस्तवार्थे कृतनिश्चयः॥', 'devi haryṛkṣasainyānām īśvaraḥ plavatāṃ varaḥ
sugrīvaḥ sattvasaṃpannas tavārthe kṛtaniścayaḥ', null, 5066017),
('ramayana-5-66-18', 18, 'Sundara Kanda, Sarga 66, Verse 18', 'तस्य विक्रमसंपन्नाः सत्त्ववन्तो महाबलाः।
मनःसंकल्पसंपाता निदेशे हरयः स्थिताः॥', 'tasya vikramasaṃpannāḥ sattvavanto mahābalāḥ
manaḥsaṃkalpasaṃpātā nideśe harayaḥ sthitāḥ', null, 5066018),
('ramayana-5-66-19', 19, 'Sundara Kanda, Sarga 66, Verse 19', 'येषां नोपरि नाधस्तान्न तिर्यक्सज्जते गतिः।
न च कर्मसु सीदन्ति महत्स्वमिततेजसः॥', 'yeṣāṃ nopari nādhastān na tiryak sajjate gatiḥ
na ca karmasu sīdanti mahatsv amitatejasaḥ', null, 5066019),
('ramayana-5-66-20', 20, 'Sundara Kanda, Sarga 66, Verse 20', 'असकृत्तैर्महाभागैर्वानरैर्बलसंयुतैः।
प्रदक्षिणीकृता भूमिर्वायुमार्गानुसारिभिः॥', 'asakṛt tair mahābhāgair vānarair balasaṃyutaiḥ
pradakṣiṇīkṛtā bhūmir vāyumārgānusāribhiḥ', null, 5066020),
('ramayana-5-66-21', 21, 'Sundara Kanda, Sarga 66, Verse 21', 'मद्विशिष्टाश्च तुल्याश्च सन्ति तत्र वनौकसः।
मत्तः प्रत्यवरः कश्चिन्नास्ति सुग्रीवसंनिधौ॥', 'madviśiṣṭāś ca tulyāś ca santi tatra vanaukasaḥ
mattaḥ pratyavaraḥ kaś cin nāsti sugrīvasaṃnidhau', null, 5066021),
('ramayana-5-66-22', 22, 'Sundara Kanda, Sarga 66, Verse 22', 'अहं तावदिह प्राप्तः किं पुनस्ते महाबलाः।
न हि प्रकृष्टाः प्रेष्यन्ते प्रेष्यन्ते हीतरे जनाः॥', 'ahaṃ tāvad iha prāptaḥ kiṃ punas te mahābalāḥ
na hi prakṛṣṭāḥ preṣyante preṣyante hītare janāḥ', null, 5066022),
('ramayana-5-66-23', 23, 'Sundara Kanda, Sarga 66, Verse 23', 'तदलं परितापेन देवि मन्युर्व्यपैतु ते।
एकोत्पातेन ते लङ्कामेष्यन्ति हरियूथपाः॥', 'tad alaṃ paritāpena devi manyur vyapaitu te
ekotpātena te laṅkām eṣyanti hariyūthapāḥ', null, 5066023),
('ramayana-5-66-24', 24, 'Sundara Kanda, Sarga 66, Verse 24', 'मम पृष्ठगतौ तौ च चन्द्रसूर्याविवोदितौ।
त्वत्सकाशं महाभागे नृसिंहावागमिष्यतः॥', 'mama pṛṣṭhagatau tau ca candrasūryāv ivoditau
tvatsakāśaṃ mahābhāge nṛsiṃhāv āgamiṣyataḥ', null, 5066024),
('ramayana-5-66-25', 25, 'Sundara Kanda, Sarga 66, Verse 25', 'अरिघ्नं सिंहसंकाशं क्षिप्रं द्रक्ष्यसि राघवम्।
लक्ष्मणं च धनुष्पाणिं लङ्का द्वारमुपस्थितम्॥', 'arighnaṃ siṃhasaṃkāśaṃ kṣipraṃ drakṣyasi rāghavam
lakṣmaṇaṃ ca dhanuṣpāṇiṃ laṅkā dvāram upasthitam', null, 5066025),
('ramayana-5-66-26', 26, 'Sundara Kanda, Sarga 66, Verse 26', 'नखदंष्ट्रायुधान्वीरान्सिंहशार्दूलविक्रमान्।
वानरान्वानरेन्द्राभान्क्षिप्रं द्रक्ष्यसि संगतान्॥', 'nakhadaṃṣṭrāyudhān vīrān siṃhaśārdūlavikramān
vānarān vānarendrābhān kṣipraṃ drakṣyasi saṃgatān', null, 5066026),
('ramayana-5-66-27', 27, 'Sundara Kanda, Sarga 66, Verse 27', 'शैलाम्बुदन्निकाशानां लङ्कामलयसानुषु।
नर्दतां कपिमुख्यानामचिराच्छोष्यसे स्वनम्॥', 'śailāmbudan nikāśānāṃ laṅkāmalayasānuṣu
nardatāṃ kapimukhyānām acirāc choṣyase svanam', null, 5066027),
('ramayana-5-66-28', 28, 'Sundara Kanda, Sarga 66, Verse 28', 'निवृत्तवनवासं च त्वया सार्धमरिंदमम्।
अभिषिक्तमयोध्यायां क्षिप्रं द्रक्ष्यसि राघवम्॥', 'nivṛttavanavāsaṃ ca tvayā sārdham ariṃdamam
abhiṣiktam ayodhyāyāṃ kṣipraṃ drakṣyasi rāghavam', null, 5066028),
('ramayana-5-66-29', 29, 'Sundara Kanda, Sarga 66, Verse 29', 'ततो मया वाग्भिरदीनभाषिणी शिवाभिरिष्टाभिरभिप्रसादिता।
जगाम शान्तिं मम मैथिलात्मजा तवापि शोकेन तथाभिपीडिता॥', 'tato mayā vāgbhir adīnabhāṣiṇī śivābhir iṣṭābhir abhiprasāditā
jagāma śāntiṃ mama maithilātmajā tavāpi śokena tathābhipīḍitā', null, 5066029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into translations (verse_id, language, text, source_id, is_primary) values
('ramayana-5-1-1', 'en', 'Then the destroyer of foes resolved to search, along the path travelled by the charanas, for the trail of Sita whom Ravana had carried off.', 'veda-app-ai-draft', true),
('ramayana-5-1-2', 'en', 'The mighty, steady one roamed at ease over lawns the colour of beryl, smooth as water.', 'veda-app-ai-draft', true),
('ramayana-5-1-3', 'en', 'The wise one scared the birds, knocked down trees with his chest, and struck many animals, like a lion in his prime.', 'veda-app-ai-draft', true),
('ramayana-5-1-4', 'en', 'The mountain was adorned with natural streaks of colourful minerals, blue, red, madder, lotus-coloured, white and black.', 'veda-app-ai-draft', true),
('ramayana-5-1-5', 'en', 'It was always frequented by shape-changing yakshas, kinnaras and gandharvas with their retinues, and by godlike serpents.', 'veda-app-ai-draft', true),
('ramayana-5-1-6', 'en', 'Standing at the foot of that great mountain, crowded with great elephants, the best of monkeys looked like an elephant in a lake.', 'veda-app-ai-draft', true),
('ramayana-5-1-7', 'en', 'He folded his hands to the Sun, to great Indra, to the Wind, to self-born Brahma and to all beings, and made up his mind to go.', 'veda-app-ai-draft', true),
('ramayana-5-1-8', 'en', 'Facing east, he folded his hands to the Wind, his own father, and then the able one grew in size to go south.', 'veda-app-ai-draft', true),
('ramayana-5-1-9', 'en', 'Watched by the leading monkeys, resolved on the leap, he swelled for Rama''s sake like the ocean at the full moon.', 'veda-app-ai-draft', true),
('ramayana-5-1-10', 'en', 'With a body beyond measure, eager to leap the ocean, he pressed down the mountain with his hands and feet.', 'veda-app-ai-draft', true),
('ramayana-5-1-11', 'en', 'The mountain, pressed by the monkey, shook for a moment and shed all the flowers from the blossoming tree-tops.', 'veda-app-ai-draft', true),
('ramayana-5-1-12', 'en', 'Covered on all sides by the fragrant shower of flowers released by the trees, the mountain looked as if made of flowers.', 'veda-app-ai-draft', true),
('ramayana-5-1-13', 'en', 'Pressed by that mighty one, the mountain poured out water, like an elephant in rut pouring out ichor.', 'veda-app-ai-draft', true),
('ramayana-5-1-14', 'en', 'Pressed by the strong one, Mount Mahendra released streams of gold, black and silver ore, and threw off huge rocks with red arsenic.', 'veda-app-ai-draft', true),
('ramayana-5-1-15', 'en', 'As the mountain was pressed, all the creatures in its caves were squeezed too and cried out with strange voices.', 'veda-app-ai-draft', true),
('ramayana-5-1-16', 'en', 'That great uproar of creatures, caused by the pressure on the mountain, filled the earth, the directions and the groves.', 'veda-app-ai-draft', true),
('ramayana-5-1-17', 'en', 'Snakes with broad hoods bearing clear swastika marks spewed terrible fire and bit the rocks with their fangs.', 'veda-app-ai-draft', true),
('ramayana-5-1-18', 'en', 'The great rocks bitten by those angry, venomous snakes blazed up with fire and split into a thousand pieces.', 'veda-app-ai-draft', true),
('ramayana-5-1-19', 'en', 'The herbs growing on that mountain, though they cure poison, could not quell the serpents'' venom.', 'veda-app-ai-draft', true),
('ramayana-5-1-20', 'en', 'Thinking beings were breaking the mountain, the ascetics and frightened vidyadharas flew up from it with their women.', 'veda-app-ai-draft', true),
('ramayana-5-1-21', 'en', 'They left their drinking places, golden seats and vessels, costly cups and golden water jars,', 'veda-app-ai-draft', true),
('ramayana-5-1-22', 'en', 'various foods and dishes, and shields of bull''s hide and swords with golden hilts.', 'veda-app-ai-draft', true),
('ramayana-5-1-23', 'en', 'Wearing garlands round their necks, flushed, with red garlands and unguents, red-eyed and lotus-eyed, they rose into the sky.', 'veda-app-ai-draft', true),
('ramayana-5-1-24', 'en', 'Women wearing necklaces, anklets and armlets stood in the sky with their lovers, astonished and smiling.', 'veda-app-ai-draft', true),
('ramayana-5-1-25', 'en', 'Showing their great magical knowledge, the vidyadhara sages stood together in the sky and gazed at the mountain.', 'veda-app-ai-draft', true),
('ramayana-5-1-26', 'en', 'Then they heard the words of sages of perfected minds, and of charanas and siddhas standing in the clear sky:', 'veda-app-ai-draft', true),
('ramayana-5-1-27', 'en', 'This Hanuman, son of the Wind, huge as a mountain, wants to cross the swift ocean, home of sea monsters.', 'veda-app-ai-draft', true),
('ramayana-5-1-28', 'en', 'Wanting to do a hard deed for Rama and for the monkeys, he seeks to reach the far shore of the ocean, hard to reach.', 'veda-app-ai-draft', true),
('ramayana-5-1-29', 'en', 'He shook his hair, quivered like a mountain, and gave a great roar like a huge thundercloud.', 'veda-app-ai-draft', true),
('ramayana-5-1-30', 'en', 'About to leap, he flung up his long, round, hairy tail, as the king of birds lifts a serpent.', 'veda-app-ai-draft', true),
('ramayana-5-1-31', 'en', 'His tail, curling behind the swift one, looked like a great serpent being carried off by Garuda.', 'veda-app-ai-draft', true),
('ramayana-5-1-32', 'en', 'He stiffened his arms, which were like great iron bars, crouched at the waist and drew in his feet.', 'veda-app-ai-draft', true),
('ramayana-5-1-33', 'en', 'Drawing in his arms and his neck, the mighty one filled himself with energy, spirit and strength.', 'veda-app-ai-draft', true),
('ramayana-5-1-34', 'en', 'Looking far along his path, eyes fixed upward, gazing at the sky, he held his breath in his heart.', 'veda-app-ai-draft', true),
('ramayana-5-1-35', 'en', 'Planting his feet firmly and flattening his ears, mighty Hanuman, best of monkeys, about to leap, said this to the monkeys:', 'veda-app-ai-draft', true),
('ramayana-5-1-36', 'en', 'As an arrow loosed by Rama flies with the speed of the wind, so I will go to Lanka, guarded by Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-1-37', 'en', 'If I do not see Janaka''s daughter in Lanka, with this same speed I will go to the home of the gods.', 'veda-app-ai-draft', true),
('ramayana-5-1-38', 'en', 'And if, after all my effort, I do not see Sita in heaven, I will bind Ravana, king of the rakshasas, and bring him back.', 'veda-app-ai-draft', true),
('ramayana-5-1-39', 'en', 'Either way I will come back with my task done, with Sita, or I will uproot Lanka with Ravana and bring it here.', 'veda-app-ai-draft', true),
('ramayana-5-1-40', 'en', 'Having said this to the monkeys, Hanuman, best of monkeys, leapt up swiftly without a second thought.', 'veda-app-ai-draft', true),
('ramayana-5-1-41', 'en', 'As he leapt, the trees growing on the mountain were swept up by his force and rose up all around, their branches drawn together.', 'veda-app-ai-draft', true),
('ramayana-5-1-42', 'en', 'Carrying along flowering trees full of excited lapwings with the force of his thighs, he went through the clear sky.', 'veda-app-ai-draft', true),
('ramayana-5-1-43', 'en', 'Uprooted by his thighs'' force, the trees followed the monkey for a moment, as kin follow a loved one setting out on a long journey.', 'veda-app-ai-draft', true),
('ramayana-5-1-44', 'en', 'Sal trees and other great trees, churned by his thighs'' force, followed Hanuman like soldiers following a king.', 'veda-app-ai-draft', true),
('ramayana-5-1-45', 'en', 'Followed by many trees with flowering tops, Hanuman, huge as a mountain, was wonderful to see.', 'veda-app-ai-draft', true),
('ramayana-5-1-46', 'en', 'The heavy trees sank into the salt sea, like mountains sinking into Varuna''s home out of fear of Indra.', 'veda-app-ai-draft', true),
('ramayana-5-1-47', 'en', 'Covered with flowers, buds and shoots, the cloud-like monkey shone like a mountain covered with fireflies.', 'veda-app-ai-draft', true),
('ramayana-5-1-48', 'en', 'Released from his pull, the trees dropped their flowers and fell into the water, like friends turning back.', 'veda-app-ai-draft', true),
('ramayana-5-1-49', 'en', 'Light and colourful, the many flowers of the trees, blown by the monkey''s wind, fell on the ocean.', 'veda-app-ai-draft', true),
('ramayana-5-1-50', 'en', 'With the many-coloured flowers clinging to him, the monkey looked like a rising cloud adorned with flashes of lightning.', 'veda-app-ai-draft', true),
('ramayana-5-1-51', 'en', 'With the flowers stirred by his speed, the water looked like the sky with lovely rising stars.', 'veda-app-ai-draft', true),
('ramayana-5-1-52', 'en', 'His arms stretched out in the sky looked like two five-headed serpents coming out of a mountain peak.', 'veda-app-ai-draft', true),
('ramayana-5-1-53', 'en', 'He seemed to drink the great ocean with its waves, and the great monkey looked as if thirsty for the sky.', 'veda-app-ai-draft', true),
('ramayana-5-1-54', 'en', 'As he followed the path of the wind, his lightning-bright eyes blazed like two fires on a mountain.', 'veda-app-ai-draft', true),
('ramayana-5-1-55', 'en', 'The tawny, large, round eyes of that foremost tawny-eyed one shone like the moon and the sun.', 'veda-app-ai-draft', true),
('ramayana-5-1-56', 'en', 'His face with its copper-red nose glowed red, like the disc of the sun touched by twilight.', 'veda-app-ai-draft', true),
('ramayana-5-1-57', 'en', 'The tail of the Wind''s son, raised as he flew, shone in the sky like Indra''s lofty banner.', 'veda-app-ai-draft', true),
('ramayana-5-1-58', 'en', 'With the circle of his tail, the great, wise, white-fanged son of the Wind shone like the sun with a halo.', 'veda-app-ai-draft', true),
('ramayana-5-1-59', 'en', 'With his reddish haunches, the great monkey shone like a mountain split open, showing red ochre.', 'veda-app-ai-draft', true),
('ramayana-5-1-60', 'en', 'As the lion among monkeys flew over the ocean, the wind passing under his arms roared like a thundercloud.', 'veda-app-ai-draft', true),
('ramayana-5-1-61', 'en', 'Like a meteor falling from the northern sky trailing light, so the elephant among monkeys appeared.', 'veda-app-ai-draft', true),
('ramayana-5-1-62', 'en', 'Stretched out, the monkey shone like the falling sun, like a great elephant being bound with a girth.', 'veda-app-ai-draft', true),
('ramayana-5-1-63', 'en', 'With his body above and his shadow sunk in the water, the monkey was like a ship on the sea driven by the wind.', 'veda-app-ai-draft', true),
('ramayana-5-1-64', 'en', 'Whatever part of the ocean the great monkey passed over seemed driven wild by the force of his body.', 'veda-app-ai-draft', true),
('ramayana-5-1-65', 'en', 'Striking with his chest the mountain-sized masses of waves, the swift great monkey flew on.', 'veda-app-ai-draft', true),
('ramayana-5-1-66', 'en', 'The strong wind from the monkey and the wind from the clouds together shook the terribly roaring ocean.', 'veda-app-ai-draft', true),
('ramayana-5-1-67', 'en', 'Pulling at the great waves in the salt sea, the swift one passed over them as if counting the waves.', 'veda-app-ai-draft', true),
('ramayana-5-1-68', 'en', 'Seeing him flying in the sky, the serpents living in the ocean thought the tiger among monkeys was Garuda.', 'veda-app-ai-draft', true),
('ramayana-5-1-69', 'en', 'The shadow of the lion among monkeys, ten yojanas wide and thirty long, looked lovely on the water.', 'veda-app-ai-draft', true),
('ramayana-5-1-70', 'en', 'That shadow following the Wind''s son, spread over the salt sea, shone like a line of dense white clouds.', 'veda-app-ai-draft', true),
('ramayana-5-1-71', 'en', 'Seeing the monkey flying swiftly, gods, gandharvas and danavas showered flowers on him.', 'veda-app-ai-draft', true),
('ramayana-5-1-72', 'en', 'The sun did not scorch him as he flew, and the wind served him, for the success of Rama''s task.', 'veda-app-ai-draft', true),
('ramayana-5-1-73', 'en', 'The sages praised him as he flew through the sky, and the gods and gandharvas sang, extolling the mighty one.', 'veda-app-ai-draft', true),
('ramayana-5-1-74', 'en', 'Nagas, yakshas, rakshasas, gods and birds praised the best of monkeys, seeing him in the sky untouched by weariness.', 'veda-app-ai-draft', true),
('ramayana-5-1-75', 'en', 'As the tiger among monkeys, Hanuman, flew, the Ocean, wishing to honour the Ikshvaku line, reflected.', 'veda-app-ai-draft', true),
('ramayana-5-1-76', 'en', 'If I do not help Hanuman, lord of monkeys, I will be blamed by everyone who speaks.', 'veda-app-ai-draft', true),
('ramayana-5-1-77', 'en', 'I was enlarged by Sagara, lord of the Ikshvakus, and this one is the Ikshvakus'' helper. He must not tire.', 'veda-app-ai-draft', true),
('ramayana-5-1-78', 'en', 'I must arrange for the monkey to rest, so that, having rested on me, he can easily cover the rest of the way.', 'veda-app-ai-draft', true),
('ramayana-5-1-79', 'en', 'With this good thought, the Ocean spoke to Mainaka, best of mountains, with its golden centre, hidden in the water.', 'veda-app-ai-draft', true),
('ramayana-5-1-80', 'en', 'Best of mountains, you were placed here by the king of the gods as a barrier against the asura hosts living in the underworld.', 'veda-app-ai-draft', true),
('ramayana-5-1-81', 'en', 'You stand blocking the gate of the boundless underworld against these asuras of known strength, who may rise up again.', 'veda-app-ai-draft', true),
('ramayana-5-1-82', 'en', 'Mountain, you can grow sideways, upward and downward. So I urge you: rise, best of mountains.', 'veda-app-ai-draft', true),
('ramayana-5-1-83', 'en', 'This mighty tiger among monkeys, Hanuman of fearsome deeds, is passing over you, flying through the sky for Rama''s sake.', 'veda-app-ai-draft', true),
('ramayana-5-1-84', 'en', 'I must help him, who serves the Ikshvaku line. The Ikshvakus are worthy of my honour, and even more of yours.', 'veda-app-ai-draft', true),
('ramayana-5-1-85', 'en', 'Help us, so that our duty is not neglected. A duty left undone stirs the anger of the good.', 'veda-app-ai-draft', true),
('ramayana-5-1-86', 'en', 'Rise up out of the water and let this monkey rest on you. The best of leapers is our guest and worthy of honour.', 'veda-app-ai-draft', true),
('ramayana-5-1-87', 'en', 'You of the great golden centre, served by gods and gandharvas, Hanuman will rest on you and then go the rest of the way.', 'veda-app-ai-draft', true),
('ramayana-5-1-88', 'en', 'Considering Rama''s kindness, Maithili''s exile and the toil of the monkey chief, you should rise.', 'veda-app-ai-draft', true),
('ramayana-5-1-89', 'en', 'Hearing the salt sea, golden-centred Mainaka rose quickly from the water with its great trees and creepers.', 'veda-app-ai-draft', true),
('ramayana-5-1-90', 'en', 'Bursting through the ocean water, it rose high, like the bright-rayed sun bursting through a cloud.', 'veda-app-ai-draft', true),
('ramayana-5-1-91', 'en', 'Its golden peaks, home to kinnaras and great serpents, bright as the rising sun, seemed to scrape the sky.', 'veda-app-ai-draft', true),
('ramayana-5-1-92', 'en', 'With the mountain''s golden peaks risen up, the sky, grey as a sword blade, took on a golden glow.', 'veda-app-ai-draft', true),
('ramayana-5-1-93', 'en', 'With its self-luminous golden peaks shining, the best of mountains was like a hundred suns.', 'veda-app-ai-draft', true),
('ramayana-5-1-94', 'en', 'Seeing it rise suddenly and stand before him in the middle of the salt sea, Hanuman decided it was an obstacle.', 'veda-app-ai-draft', true),
('ramayana-5-1-95', 'en', 'The swift great monkey knocked down the towering mountain with his chest, as the wind scatters a cloud.', 'veda-app-ai-draft', true),
('ramayana-5-1-96', 'en', 'Pushed down by the monkey, the best of mountains understood the monkey''s speed and was delighted and glad.', 'veda-app-ai-draft', true),
('ramayana-5-1-97', 'en', 'Taking human form and standing on his own peak, the mountain, pleased and happy, spoke to the heroic monkey poised in the sky.', 'veda-app-ai-draft', true),
('ramayana-5-1-98', 'en', 'Best of monkeys, you have done a hard deed. Come down on my peaks and rest at ease.', 'veda-app-ai-draft', true),
('ramayana-5-1-99', 'en', 'The ocean was enlarged by those born in Rama''s line. So the Ocean honours you in return, engaged as you are in Rama''s good.', 'veda-app-ai-draft', true),
('ramayana-5-1-100', 'en', 'When good is done, it must be returned. This is the eternal dharma. Wishing to repay, the Ocean deserves your respect.', 'veda-app-ai-draft', true),
('ramayana-5-1-101', 'en', 'For your sake the Ocean urged me with great respect: This monkey has leapt a hundred yojanas. Let him rest on your slopes and then go the rest of the way.', 'veda-app-ai-draft', true),
('ramayana-5-1-102', 'en', 'Stay, tiger among monkeys, rest on me and then go. Here are many fragrant, sweet roots, bulbs and fruits. Eat them, best of monkeys, and go on refreshed.', 'veda-app-ai-draft', true),
('ramayana-5-1-103', 'en', 'We too have a bond with you, chief of monkeys, famous in the three worlds and endowed with great virtues.', 'veda-app-ai-draft', true),
('ramayana-5-1-104', 'en', 'Of all the swift monkeys that leap, son of the Wind, I think you are the foremost, elephant among monkeys.', 'veda-app-ai-draft', true),
('ramayana-5-1-105', 'en', 'One who understands and seeks dharma should honour even an ordinary guest, so how much more one like you!', 'veda-app-ai-draft', true),
('ramayana-5-1-106', 'en', 'You are the son of the great Wind, best of gods, and equal to him in speed, elephant among monkeys.', 'veda-app-ai-draft', true),
('ramayana-5-1-107', 'en', 'When you are honoured, knower of dharma, the Wind is honoured. So you deserve my honour. Hear the reason why.', 'veda-app-ai-draft', true),
('ramayana-5-1-108', 'en', 'Long ago, in the Krita age, dear one, mountains had wings. They flew in every direction with the speed of Garuda and the wind.', 'veda-app-ai-draft', true),
('ramayana-5-1-109', 'en', 'As they flew about, the gods, sages and all beings grew afraid that they might fall on them.', 'veda-app-ai-draft', true),
('ramayana-5-1-110', 'en', 'Then angry thousand-eyed Indra cut off the mountains'' wings with his thunderbolt here and there, by the thousand.', 'veda-app-ai-draft', true),
('ramayana-5-1-111', 'en', 'The angry king of the gods came at me with his thunderbolt raised, but the great Wind suddenly hurled me away.', 'veda-app-ai-draft', true),
('ramayana-5-1-112', 'en', 'I was thrown into this salt sea, best of monkeys, with my wings kept safe and whole, protected by your father.', 'veda-app-ai-draft', true),
('ramayana-5-1-113', 'en', 'So I honour you, for the Wind is worthy of my honour. This is my bond with you, chief of monkeys, a bond of great worth.', 'veda-app-ai-draft', true),
('ramayana-5-1-114', 'en', 'In this situation, great monkey, you should gladly give joy to the Ocean and to me.', 'veda-app-ai-draft', true),
('ramayana-5-1-115', 'en', 'Rest from your toil and accept our honour, best of monkeys. Value our affection. I am delighted to see you.', 'veda-app-ai-draft', true),
('ramayana-5-1-116', 'en', 'Spoken to in this way, the best of monkeys said to the best of mountains: I am pleased. Your hospitality is as good as received. Let this be no cause for hurt.', 'veda-app-ai-draft', true),
('ramayana-5-1-117', 'en', 'The time for my task presses, and the day is passing. I have given my word not to stop along the way.', 'veda-app-ai-draft', true),
('ramayana-5-1-118', 'en', 'Saying this, the bull among monkeys touched the mountain with his hand and, smiling, went on into the sky.', 'veda-app-ai-draft', true),
('ramayana-5-1-119', 'en', 'The son of the Wind was looked on with great respect by the mountain and the Ocean, and honoured with fitting blessings.', 'veda-app-ai-draft', true),
('ramayana-5-1-120', 'en', 'Then, flying high and far, leaving mountain and ocean behind, he took his father''s path through the clear sky.', 'veda-app-ai-draft', true),
('ramayana-5-1-121', 'en', 'Rising higher still and looking back at the mountain, the Wind''s son went on through the clear, unsupported sky.', 'veda-app-ai-draft', true),
('ramayana-5-1-122', 'en', 'Seeing this second very difficult deed of Hanuman, all the gods, siddhas and great sages praised him.', 'veda-app-ai-draft', true),
('ramayana-5-1-123', 'en', 'The gods there were delighted by his deed and by that of golden Sunabha (Mainaka), and so was thousand-eyed Indra.', 'veda-app-ai-draft', true),
('ramayana-5-1-124', 'en', 'Wise Indra, husband of Shachi, himself spoke to Sunabha, best of mountains, his voice choked with joy.', 'veda-app-ai-draft', true),
('ramayana-5-1-125', 'en', 'Golden-centred lord of mountains, I am very pleased with you. I grant you freedom from fear. Stay at ease, gentle one.', 'veda-app-ai-draft', true),
('ramayana-5-1-126', 'en', 'You have given great help to brave Hanuman, fearless though fear was near, as he crossed a hundred yojanas.', 'veda-app-ai-draft', true),
('ramayana-5-1-127', 'en', 'This monkey goes as messenger of Rama, son of Dasharatha. By honouring him as you could, you have greatly pleased me.', 'veda-app-ai-draft', true),
('ramayana-5-1-128', 'en', 'Then the best of mountains felt great joy, seeing Indra, lord of the gods, pleased.', 'veda-app-ai-draft', true),
('ramayana-5-1-129', 'en', 'Granted this boon, the mountain stayed where it was, and Hanuman crossed that stretch of ocean in a moment.', 'veda-app-ai-draft', true),
('ramayana-5-1-130', 'en', 'Then the gods, gandharvas, siddhas and great sages spoke to Surasa, mother of serpents, bright as the sun.', 'veda-app-ai-draft', true),
('ramayana-5-1-131', 'en', 'This glorious son of the Wind named Hanuman is flying over the ocean. Put an obstacle in his way for a moment.', 'veda-app-ai-draft', true),
('ramayana-5-1-132', 'en', 'Take the form of a terrible rakshasi, mountain-like, with dreadful fangs, tawny eyes and a mouth that touches the sky.', 'veda-app-ai-draft', true),
('ramayana-5-1-133', 'en', 'We want to know his strength and his courage once more. Will he defeat you by some means, or will he lose heart?', 'veda-app-ai-draft', true),
('ramayana-5-1-134', 'en', 'Addressed this way and honoured by the gods, the goddess Surasa took on a rakshasa body in the middle of the ocean,', 'veda-app-ai-draft', true),
('ramayana-5-1-135', 'en', 'hideous, deformed and terrifying to all. Blocking Hanuman''s flight, she said:', 'veda-app-ai-draft', true),
('ramayana-5-1-136', 'en', 'Bull among monkeys, the gods have given you to me as food. I will eat you. Enter my mouth.', 'veda-app-ai-draft', true),
('ramayana-5-1-137', 'en', 'Spoken to this way by Surasa, the glorious bull among monkeys folded his hands and, with a cheerful face, said this:', 'veda-app-ai-draft', true),
('ramayana-5-1-138', 'en', 'Rama, son of Dasharatha, entered the Dandaka forest with his brother Lakshmana and his wife Vaidehi.', 'veda-app-ai-draft', true),
('ramayana-5-1-139', 'en', 'While he was busy with his work and at enmity with the rakshasas, his famous wife Sita was carried off by Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-1-140', 'en', 'At Rama''s command I go to her as messenger. You who live in his realm should help Rama.', 'veda-app-ai-draft', true),
('ramayana-5-1-141', 'en', 'Or else, once I have seen Maithili and told Rama of flawless deeds, I will come back to your mouth. I truly promise you.', 'veda-app-ai-draft', true),
('ramayana-5-1-142', 'en', 'Spoken to by Hanuman, shape-changing Surasa said: No one may pass me. This is my boon.', 'veda-app-ai-draft', true),
('ramayana-5-1-143', 'en', 'Spoken to this way by Surasa, the angry bull among monkeys said: Then make your mouth big enough to hold me.', 'veda-app-ai-draft', true),
('ramayana-5-1-144', 'en', 'Saying this angrily to Surasa, Hanuman then grew ten yojanas long and ten yojanas wide.', 'veda-app-ai-draft', true),
('ramayana-5-1-145', 'en', 'Seeing him like a cloud, ten yojanas long, Surasa made her mouth twenty yojanas long.', 'veda-app-ai-draft', true),
('ramayana-5-1-146', 'en', 'Then angry Hanuman grew thirty yojanas long, and Surasa made her mouth forty yojanas high.', 'veda-app-ai-draft', true),
('ramayana-5-1-147', 'en', 'Heroic Hanuman grew fifty yojanas tall, and Surasa made her mouth sixty yojanas long.', 'veda-app-ai-draft', true),
('ramayana-5-1-148', 'en', 'Then heroic Hanuman grew seventy yojanas tall, and Surasa made her mouth eighty yojanas long.', 'veda-app-ai-draft', true),
('ramayana-5-1-149', 'en', 'Hanuman, like a mountain, grew ninety yojanas tall, and Surasa made her mouth a hundred yojanas long.', 'veda-app-ai-draft', true),
('ramayana-5-1-150', 'en', 'Seeing that gaping mouth of Surasa, with its long tongue, dreadful as hell, the wise son of the Wind', 'veda-app-ai-draft', true),
('ramayana-5-1-151', 'en', 'shrank his body like a cloud, and in that moment Hanuman became the size of a thumb.', 'veda-app-ai-draft', true),
('ramayana-5-1-152', 'en', 'Swiftly darting into her mouth and out again, the glorious, swift one stood in the sky and said:', 'veda-app-ai-draft', true),
('ramayana-5-1-153', 'en', 'I have entered your mouth, daughter of Daksha. Salutations to you. I will go where Vaidehi is. Your word has come true.', 'veda-app-ai-draft', true),
('ramayana-5-1-154', 'en', 'Seeing the monkey freed from her mouth like the moon from Rahu''s jaws, the goddess Surasa, in her own form, said:', 'veda-app-ai-draft', true),
('ramayana-5-1-155', 'en', 'Go, best of monkeys, gentle one, at ease, to achieve your goal. Bring Vaidehi together with great-souled Rama.', 'veda-app-ai-draft', true),
('ramayana-5-1-156', 'en', 'Seeing this third very difficult deed of Hanuman, all beings praised the monkey, crying: Well done, well done!', 'veda-app-ai-draft', true),
('ramayana-5-1-157', 'en', 'Reaching the unassailable ocean, home of Varuna, he flew into the sky with speed like Garuda.', 'veda-app-ai-draft', true),
('ramayana-5-1-158', 'en', 'He flew through the sky frequented by rain clouds and birds, travelled by masters of music, and by Airavata,', 'veda-app-ai-draft', true),
('ramayana-5-1-159', 'en', 'adorned with bright vimanas flying by, drawn by lions, elephants, tigers, birds and serpents,', 'veda-app-ai-draft', true),
('ramayana-5-1-160', 'en', 'lit by fires with the force of thunderbolts, and adorned by fortunate beings who won heaven through good deeds,', 'veda-app-ai-draft', true),
('ramayana-5-1-161', 'en', 'frequented by the bright fire that carries offerings, and adorned with planets, constellations, moon, sun and hosts of stars,', 'veda-app-ai-draft', true),
('ramayana-5-1-162', 'en', 'crowded with hosts of great sages, gandharvas, nagas and yakshas, open, clear and vast, frequented by Vishvavasu,', 'veda-app-ai-draft', true),
('ramayana-5-1-163', 'en', 'traversed by the elephant of the king of gods, the auspicious path of moon and sun, the canopy of the living world spread out by Brahma,', 'veda-app-ai-draft', true),
('ramayana-5-1-164', 'en', 'often visited by heroes and the best of vidyadharas. The great clouds drawn along by the monkey shone brightly.', 'veda-app-ai-draft', true),
('ramayana-5-1-165', 'en', 'Entering banks of clouds and coming out again and again, he looked like the moon in the rainy season, appearing and disappearing.', 'veda-app-ai-draft', true),
('ramayana-5-1-166', 'en', 'Seeing him flying, a huge shape-changing rakshasi named Simhika thought to herself:', 'veda-app-ai-draft', true),
('ramayana-5-1-167', 'en', 'Today, after a long time, I will be fed. This great creature has come into my power at last.', 'veda-app-ai-draft', true),
('ramayana-5-1-168', 'en', 'Thinking this, she seized his shadow. With his shadow caught, the monkey thought:', 'veda-app-ai-draft', true),
('ramayana-5-1-169', 'en', 'I have suddenly been held back, my strength crippled, like a great ship at sea against a contrary wind.', 'veda-app-ai-draft', true),
('ramayana-5-1-170', 'en', 'Looking sideways, up and down, the monkey saw a great creature risen from the salt sea.', 'veda-app-ai-draft', true),
('ramayana-5-1-171', 'en', 'This is surely the wondrous, mighty shadow-grabbing creature the monkey king told me of. There is no doubt.', 'veda-app-ai-draft', true),
('ramayana-5-1-172', 'en', 'Knowing her truly to be Simhika, the clever monkey grew huge, like a rain cloud in the monsoon.', 'veda-app-ai-draft', true),
('ramayana-5-1-173', 'en', 'Seeing the great monkey''s body growing, she opened her mouth as wide as the space between the underworld and the sky.', 'veda-app-ai-draft', true),
('ramayana-5-1-174', 'en', 'The wise great monkey saw her huge, hideous mouth, the size of her body and her vital points.', 'veda-app-ai-draft', true),
('ramayana-5-1-175', 'en', 'Into her open mouth the mighty monkey, hard as a thunderbolt, shrank himself again and dropped.', 'veda-app-ai-draft', true),
('ramayana-5-1-176', 'en', 'The siddhas and charanas saw him sinking into her mouth, like the full moon being swallowed by Rahu at the full-moon eclipse.', 'veda-app-ai-draft', true),
('ramayana-5-1-177', 'en', 'Then the monkey tore out her vital parts with his sharp nails and leapt up again with speed swift as thought.', 'veda-app-ai-draft', true),
('ramayana-5-1-178', 'en', 'Seeing Simhika quickly killed by the monkey and fallen, the beings moving in the sky said to the bull among monkeys:', 'veda-app-ai-draft', true),
('ramayana-5-1-179', 'en', 'Today you have done a fearsome deed and killed a great creature. Achieve your desired goal unharmed, best of leapers.', 'veda-app-ai-draft', true),
('ramayana-5-1-180', 'en', 'Lord of monkeys, whoever has these four, as you do, steadiness, foresight, intelligence and skill, never fails in his work.', 'veda-app-ai-draft', true),
('ramayana-5-1-181', 'en', 'Honoured and esteemed by them, his purpose clear, the monkey flew on into the sky like Garuda, eater of serpents.', 'veda-app-ai-draft', true),
('ramayana-5-1-182', 'en', 'Having nearly reached the far shore, looking all around, at the end of the hundred yojanas he saw a line of forest.', 'veda-app-ai-draft', true),
('ramayana-5-1-183', 'en', 'As he descended, the best of monkeys saw an island adorned with many trees, and the groves of the Malaya hills.', 'veda-app-ai-draft', true),
('ramayana-5-1-184', 'en', 'He looked at the sea, the coastal lands, the trees growing on the shore, and the mouths of the rivers, the Ocean''s wives.', 'veda-app-ai-draft', true),
('ramayana-5-1-185', 'en', 'Seeing himself like a huge cloud, as if blocking the sky, the wise one gave it careful thought.', 'veda-app-ai-draft', true),
('ramayana-5-1-186', 'en', 'The great monkey thought: If the rakshasas see my huge size and speed, they will be curious about me.', 'veda-app-ai-draft', true),
('ramayana-5-1-187', 'en', 'So he shrank his mountain-like body and returned to his natural form, like a self-possessed person freed from delusion.', 'veda-app-ai-draft', true),
('ramayana-5-1-188', 'en', 'Able to take many lovely forms, he reached the far shore of the ocean in a form others could not match, self-aware and mindful of his purpose.', 'veda-app-ai-draft', true),
('ramayana-5-1-189', 'en', 'Then the great one, like a great mountain peak himself, landed on a rich, many-coloured peak of Mount Lamba, with ketaka, uddalaka and coconut trees.', 'veda-app-ai-draft', true),
('ramayana-5-1-190', 'en', 'Having crossed by his strength the wave-crested ocean full of danavas and serpents, and landing on its shore, he saw Lanka, like Amaravati, the city of the gods.', 'veda-app-ai-draft', true),
('ramayana-5-2-1', 'en', 'Having crossed the unassailable ocean, the mighty one, at ease, saw Lanka standing on the peak of Mount Trikuta.', 'veda-app-ai-draft', true),
('ramayana-5-2-2', 'en', 'Showered with flowers falling from the trees, the mighty one standing there looked as if made of flowers.', 'veda-app-ai-draft', true),
('ramayana-5-2-3', 'en', 'Though he had crossed a hundred yojanas, the glorious, valiant monkey did not even pant or feel weary.', 'veda-app-ai-draft', true),
('ramayana-5-2-4', 'en', 'I could leap many hundreds of yojanas, so what of the ocean''s breadth, measured at just a hundred?', 'veda-app-ai-draft', true),
('ramayana-5-2-5', 'en', 'The best of the mighty and finest of leapers, having crossed the great sea, went swiftly towards Lanka.', 'veda-app-ai-draft', true),
('ramayana-5-2-6', 'en', 'He went through green lawns, fragrant woods, rocky places and wooded hills.', 'veda-app-ai-draft', true),
('ramayana-5-2-7', 'en', 'The radiant Hanuman, bull among monkeys, passed mountains covered with trees and lines of flowering forest.', 'veda-app-ai-draft', true),
('ramayana-5-2-8', 'en', 'Standing on that mountain, the son of the Wind saw woods and groves, and Lanka on the summit.', 'veda-app-ai-draft', true),
('ramayana-5-2-9', 'en', 'He saw sarala, karnikara and date palms in flower, priyala, muchulinda, kutaja and ketaka trees,', 'veda-app-ai-draft', true),
('ramayana-5-2-10', 'en', 'fragrant priyangu, nipa and saptacchada trees, asana, kovidara and flowering karavira,', 'veda-app-ai-draft', true),
('ramayana-5-2-11', 'en', 'trees heavy with flowers or in bud, full of birds, their crowns swaying in the wind.', 'veda-app-ai-draft', true),
('ramayana-5-2-12', 'en', 'ponds full of swans and ducks, with lotuses and water lilies, pleasure gardens of many kinds and lovely lakes,', 'veda-app-ai-draft', true),
('ramayana-5-2-13', 'en', 'and lovely parks full of trees fruiting and flowering in every season: all this the elephant among monkeys saw.', 'veda-app-ai-draft', true),
('ramayana-5-2-14', 'en', 'The glorious one reached Lanka, guarded by Ravana, adorned with moats full of lotuses and water lilies,', 'veda-app-ai-draft', true),
('ramayana-5-2-15', 'en', 'closely guarded by Ravana since Sita''s abduction, with rakshasas carrying fierce bows patrolling all around,', 'veda-app-ai-draft', true),
('ramayana-5-2-16', 'en', 'a lovely great city surrounded by a golden wall, full of hundreds of watchtowers and garlanded with flags and banners,', 'veda-app-ai-draft', true),
('ramayana-5-2-17', 'en', 'with divine golden archways decorated with rows of creepers. Hanuman saw Lanka like a city of the gods in heaven.', 'veda-app-ai-draft', true),
('ramayana-5-2-18', 'en', 'The glorious monkey saw Lanka on the mountain top with lovely white mansions, like a city in the sky.', 'veda-app-ai-draft', true),
('ramayana-5-2-19', 'en', 'Hanuman saw the city, built by Vishvakarma and guarded by the rakshasa king, as if floating in the sky.', 'veda-app-ai-draft', true),
('ramayana-5-2-20', 'en', 'Full of terrible rakshasas, as Bhogavati is full of serpents, it was beyond imagining, well made and clear, where Kubera once lived.', 'veda-app-ai-draft', true),
('ramayana-5-2-21', 'en', 'It was guarded by many brave, fanged rakshasas holding spears and axes, like a cave guarded by venomous snakes.', 'veda-app-ai-draft', true),
('ramayana-5-2-22', 'en', 'With ramparts for hips, the sea for her garment, cannons and spears for her hair, and watchtowers for her earrings, the city was like a woman.', 'veda-app-ai-draft', true),
('ramayana-5-2-23', 'en', 'Reaching the northern gate, tall as Kailasa''s peak, as if scraping the sky and holding it up with its lofty mansions, the monkey thought hard.', 'veda-app-ai-draft', true),
('ramayana-5-2-24', 'en', 'Seeing the city''s strong defences, the ocean and his fearsome enemy Ravana, the monkey reflected:', 'veda-app-ai-draft', true),
('ramayana-5-2-25', 'en', 'Even if the monkeys come here, it will be useless. Lanka cannot be won in battle even by the gods.', 'veda-app-ai-draft', true),
('ramayana-5-2-26', 'en', 'Even if he reaches this rugged, impregnable Lanka guarded by Ravana, what will mighty-armed Rama do?', 'veda-app-ai-draft', true),
('ramayana-5-2-27', 'en', 'With rakshasas there is no room for conciliation, nor for gifts or for dividing them, and even battle seems hopeless.', 'veda-app-ai-draft', true),
('ramayana-5-2-28', 'en', 'Only four great monkeys could even come here: Vali''s son, Nila, myself and our wise king.', 'veda-app-ai-draft', true),
('ramayana-5-2-29', 'en', 'First let me find out whether Vaidehi is alive or not. I will think about the rest once I have seen Janaka''s daughter.', 'veda-app-ai-draft', true),
('ramayana-5-2-30', 'en', 'Then the elephant among monkeys, standing on the mountain top, devoted to Rama''s success, thought for a moment.', 'veda-app-ai-draft', true),
('ramayana-5-2-31', 'en', 'In this form I cannot enter the rakshasas'' city, guarded by cruel and powerful rakshasas.', 'veda-app-ai-draft', true),
('ramayana-5-2-32', 'en', 'The rakshasas are fierce, mighty and strong. To search for Janaki I must get past them all.', 'veda-app-ai-draft', true),
('ramayana-5-2-33', 'en', 'It is time for me to enter Lanka at night in a form that can be barely seen, to accomplish this great task.', 'veda-app-ai-draft', true),
('ramayana-5-2-34', 'en', 'Seeing that city, unassailable even by gods and asuras, Hanuman sighed again and again and thought:', 'veda-app-ai-draft', true),
('ramayana-5-2-35', 'en', 'By what means can I see Maithili, Janaka''s daughter, without being seen by the wicked rakshasa king Ravana?', 'veda-app-ai-draft', true),
('ramayana-5-2-36', 'en', 'How can I keep the task of wise Rama from failing? How can I see Janaka''s daughter alone, in a private place?', 'veda-app-ai-draft', true),
('ramayana-5-2-37', 'en', 'Tasks that are ready to succeed fail when they go against place and time, or fall to a nervous messenger, as darkness fails at sunrise.', 'veda-app-ai-draft', true),
('ramayana-5-2-38', 'en', 'Even a firm decision about what to do and what not to do does not shine if misused. Messengers who think themselves clever ruin tasks.', 'veda-app-ai-draft', true),
('ramayana-5-2-39', 'en', 'How can I keep the task from failing? How can I avoid losing my nerve? How can my leap across the ocean not be in vain?', 'veda-app-ai-draft', true),
('ramayana-5-2-40', 'en', 'If the rakshasas see me, this task of wise Rama, who wishes Ravana''s ruin, will come to nothing.', 'veda-app-ai-draft', true),
('ramayana-5-2-41', 'en', 'No one can stay anywhere here unknown to the rakshasas, even in rakshasa form, let alone in any other form.', 'veda-app-ai-draft', true),
('ramayana-5-2-42', 'en', 'I think even the wind cannot move here unnoticed. Nothing is unknown to the mighty rakshasas.', 'veda-app-ai-draft', true),
('ramayana-5-2-43', 'en', 'If I stay here in my own form, I will be destroyed and my master''s purpose will fail.', 'veda-app-ai-draft', true),
('ramayana-5-2-44', 'en', 'So, in my own form but made small, I will slip into Lanka at night to achieve Rama''s purpose.', 'veda-app-ai-draft', true),
('ramayana-5-2-45', 'en', 'Entering Ravana''s hard-to-reach city at night, I will search every house and find Janaka''s daughter.', 'veda-app-ai-draft', true),
('ramayana-5-2-46', 'en', 'Thinking this, the heroic monkey Hanuman, eager to see Vaidehi, waited for sunset, and shrank to the size of a cat, wonderful to see.', 'veda-app-ai-draft', true),
('ramayana-5-2-47', 'en', 'At dusk mighty Hanuman quickly leapt up and entered the lovely city with its well-laid main roads.', 'veda-app-ai-draft', true),
('ramayana-5-2-48', 'en', 'It was lined with rows of mansions, with gold and silver pillars and golden lattices, like a city of the gandharvas.', 'veda-app-ai-draft', true),
('ramayana-5-2-49', 'en', 'He saw the great city with seven- and eight-storey buildings, crystal floors adorned with gold,', 'veda-app-ai-draft', true),
('ramayana-5-2-50', 'en', 'floors inlaid with beryl and gems and adorned with pearl lattices. The rakshasas'' houses shone with them.', 'veda-app-ai-draft', true),
('ramayana-5-2-51', 'en', 'The rakshasas'' many-coloured golden archways lit up Lanka, adorned on every side.', 'veda-app-ai-draft', true),
('ramayana-5-2-52', 'en', 'Seeing Lanka, unimaginable and wondrous, the great monkey was both dismayed and delighted, eager to see Vaidehi.', 'veda-app-ai-draft', true),
('ramayana-5-2-53', 'en', 'He saw the city garlanded with tall white palaces, with costly golden lattices and arches, guarded by Ravana''s arms and surrounded by night-roamers of fearsome strength.', 'veda-app-ai-draft', true),
('ramayana-5-2-54', 'en', 'The moon too, as if helping him, rose shining among the hosts of stars, spreading over the world a canopy of moonlight with its countless rays.', 'veda-app-ai-draft', true),
('ramayana-5-2-55', 'en', 'The hero among monkeys saw the moon rising and shining, bright as a conch, white as milk or lotus fibre, like a swan floating on a lake.', 'veda-app-ai-draft', true),
('ramayana-5-3-1', 'en', 'On Mount Lamba''s tall peak, like a hanging cloud, the wise Hanuman, son of the Wind, summoned his courage.', 'veda-app-ai-draft', true),
('ramayana-5-3-2', 'en', 'At night the mighty elephant among monkeys entered Lanka, guarded by Ravana, rich in lovely woods and water.', 'veda-app-ai-draft', true),
('ramayana-5-3-3', 'en', 'It was adorned with mansions like autumn clouds, roaring like the ocean, and fanned by sea breezes.', 'veda-app-ai-draft', true),
('ramayana-5-3-4', 'en', 'It was guarded by well-fed troops like Vitapavati, with lovely arches and turrets, and white gates and archways.', 'veda-app-ai-draft', true),
('ramayana-5-3-5', 'en', 'Like lovely Bhogavati, guarded and frequented by serpents, it was full of clouds with lightning and visited by the stars.', 'veda-app-ai-draft', true),
('ramayana-5-3-6', 'en', 'Roaring with fierce winds like Indra''s Amaravati, it was surrounded by a great golden wall.', 'veda-app-ai-draft', true),
('ramayana-5-3-7', 'en', 'Adorned with flags tinkling with bells, it delighted him. Reaching it suddenly, he climbed onto the wall.', 'veda-app-ai-draft', true),
('ramayana-5-3-8', 'en', 'His heart filled with wonder, he looked all over the city, with gates of gold and platforms of beryl,', 'veda-app-ai-draft', true),
('ramayana-5-3-9', 'en', 'floors inlaid with gems, crystal and pearls, turrets of refined gold, and spotless white silver,', 'veda-app-ai-draft', true),
('ramayana-5-3-10', 'en', 'beryl stairways, crystal-clean inner courts, lovely halls, beautiful as if risen into the sky,', 'veda-app-ai-draft', true),
('ramayana-5-3-11', 'en', 'echoing with curlews and peacocks, frequented by royal swans, and resounding everywhere with music and jingling ornaments.', 'veda-app-ai-draft', true),
('ramayana-5-3-12', 'en', 'Seeing the city like Indra''s capital, Lanka as if risen into the sky, the monkey Hanuman was delighted.', 'veda-app-ai-draft', true),
('ramayana-5-3-13', 'en', 'Seeing that lovely, matchless, prosperous city of the rakshasa king, the mighty one thought:', 'veda-app-ai-draft', true),
('ramayana-5-3-14', 'en', 'No one else could take this city by force, guarded by Ravana''s troops with weapons raised.', 'veda-app-ai-draft', true),
('ramayana-5-3-15', 'en', 'This land may be open to Kumuda and Angada, to the great monkey Sushena, and to Mainda and Dvivida,', 'veda-app-ai-draft', true),
('ramayana-5-3-16', 'en', 'and to the son of Vivasvan, to the monkey Kushaparvan, to the bear Ketumala, and to me.', 'veda-app-ai-draft', true),
('ramayana-5-3-17', 'en', 'But thinking of the might of mighty-armed Rama and the valour of Lakshmana, the monkey was cheered.', 'veda-app-ai-draft', true),
('ramayana-5-3-18', 'en', 'With jewels for clothing, storehouses for earrings and arsenals for breasts, the rich city was like an adorned young woman.', 'veda-app-ai-draft', true),
('ramayana-5-3-19', 'en', 'The great monkey saw the rakshasa king''s city, its darkness driven away by bright lamps and great houses.', 'veda-app-ai-draft', true),
('ramayana-5-3-20', 'en', 'Entering at night, full of courage, the son of the Wind took the main road, gleaming with pearls and flowers.', 'veda-app-ai-draft', true),
('ramayana-5-3-21', 'en', 'With sounds of laughter and shouting and music, and houses like thunderbolts and goads hung with diamond lattices, the lovely city shone like the sky with clouds.', 'veda-app-ai-draft', true),
('ramayana-5-3-22', 'en', 'Lanka blazed with the rakshasas'' fine houses, like white clouds, built in lotus and swastika patterns and in vardhamana style, beautifully adorned.', 'veda-app-ai-draft', true),
('ramayana-5-3-23', 'en', 'Moving for Rama''s sake, the glorious well-wisher of the monkey king saw that city with its colourful garlands and ornaments and was glad.', 'veda-app-ai-draft', true),
('ramayana-5-3-24', 'en', 'He heard sweet singing, graced with notes from the three registers, by women flushed with wine, like apsarases in heaven.', 'veda-app-ai-draft', true),
('ramayana-5-3-25', 'en', 'He heard the jingle of girdles and anklets, footsteps on stairs in the houses, and here and there the sound of hand-slapping and shouts.', 'veda-app-ai-draft', true),
('ramayana-5-3-26', 'en', 'He saw rakshasas devoted to Vedic study, and others roaring out praises of Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-3-27', 'en', 'He saw a great rakshasa force blocking the royal road, and many of Ravana''s spies at the central post.', 'veda-app-ai-draft', true),
('ramayana-5-3-28', 'en', 'He saw initiates, some with matted hair, some shaven, wearing cowhide and skins, carrying fistfuls of darbha grass and firepots as weapons,', 'veda-app-ai-draft', true),
('ramayana-5-3-29', 'en', 'some holding hammers and clubs, others carrying staffs, some one-eyed, some with many ears,', 'veda-app-ai-draft', true),
('ramayana-5-3-30', 'en', 'fearsome ones with crooked faces, monstrous ones and dwarfs, archers and swordsmen, some with cannons and maces, holding iron bars, shining in colourful armour.', 'veda-app-ai-draft', true),
('ramayana-5-3-31', 'en', 'Neither too fat nor too thin, too tall nor too short, ugly ones, shape-changers, handsome ones and radiant ones.', 'veda-app-ai-draft', true),
('ramayana-5-3-32', 'en', 'The great monkey saw them armed with spears and trees, with axes and thunderbolts, with slings and nooses in hand.', 'veda-app-ai-draft', true),
('ramayana-5-3-33', 'en', 'Some wore garlands and unguents and fine ornaments, others held sharp spears and thunderbolts, all of great strength.', 'veda-app-ai-draft', true),
('ramayana-5-3-34', 'en', 'The great monkey saw a central guard of a hundred thousand, alert and enclosed by a high wall.', 'veda-app-ai-draft', true),
('ramayana-5-3-35', 'en', 'It was like heaven, divine and filled with divine sounds, echoing with the neighing of horses and the jingling of ornaments.', 'veda-app-ai-draft', true),
('ramayana-5-3-36', 'en', 'It was adorned with chariots, carriages, flying vimanas, fine elephants and horses, and four-tusked elephants like heaps of white cloud,', 'veda-app-ai-draft', true),
('ramayana-5-3-37', 'en', 'with lovely gates and lively animals and birds. The monkey entered the rakshasa king''s guarded home.', 'veda-app-ai-draft', true),
('ramayana-5-4-1', 'en', 'Then the wise one saw the bright-rayed moon high in the sky, pouring out its great canopy of moonlight, roaming like an excited bull in a cowpen.', 'veda-app-ai-draft', true),
('ramayana-5-4-2', 'en', 'He saw the cool-rayed moon moving on, destroying the world''s sins, swelling the great ocean and making all beings shine.', 'veda-app-ai-draft', true),
('ramayana-5-4-3', 'en', 'The beauty that shines on Mandara, on the ocean at dusk and on lotuses in water, now shone in the lovely moon.', 'veda-app-ai-draft', true),
('ramayana-5-4-4', 'en', 'Like a swan in a silver cage, a lion in a cave of Mandara, a hero on a proud elephant, so shone the moon in the sky.', 'veda-app-ai-draft', true),
('ramayana-5-4-5', 'en', 'The full moon shone like a sharp-horned bull, like a lofty white mountain, like an elephant with gold-bound tusks.', 'veda-app-ai-draft', true),
('ramayana-5-4-6', 'en', 'The blessed evening, bright as heaven, its darkness ended by the moonrise, its rakshasas'' flesh-eating grown stronger, its lovers'' minds stirred by their beloveds.', 'veda-app-ai-draft', true),
('ramayana-5-4-7', 'en', 'The sweet sound of lutes began; virtuous women slept with their husbands; and night-roamers set out to wander, wondrous and fierce.', 'veda-app-ai-draft', true),
('ramayana-5-4-8', 'en', 'The wise monkey saw houses full of drunken, careless people, crowded with chariots, horses and fine seats, and full of martial splendour.', 'veda-app-ai-draft', true),
('ramayana-5-4-9', 'en', 'They taunted each other, flung about their thick arms, babbled drunkenly and abused one another.', 'veda-app-ai-draft', true),
('ramayana-5-4-10', 'en', 'Rakshasas puffed out their chests and draped their arms over their beloveds. He saw some women chatting while others went back to sleep.', 'veda-app-ai-draft', true),
('ramayana-5-4-11', 'en', 'With great trumpeting elephants, well-honoured good people, and sighing heroes, the city shone like a lake with hissing serpents.', 'veda-app-ai-draft', true),
('ramayana-5-4-12', 'en', 'In that city he saw rakshasas who were intelligent, fine-spoken, faithful, leaders in the world, of many kinds and pleasing names.', 'veda-app-ai-draft', true),
('ramayana-5-4-13', 'en', 'He was glad to see the handsome ones with many virtues matching their nature, shining and fair, and he saw some who were ugly.', 'veda-app-ai-draft', true),
('ramayana-5-4-14', 'en', 'He saw their noble, pure-hearted wives, worthy of the best, devoted to their dear ones and to drink, radiant as stars.', 'veda-app-ai-draft', true),
('ramayana-5-4-15', 'en', 'He saw some women blazing with beauty and covered with modesty, embraced by lovers at midnight, like birds hidden among flowers.', 'veda-app-ai-draft', true),
('ramayana-5-4-16', 'en', 'Others sat on rooftops, resting happily on their husbands'' laps, loving and devoted to their duty.', 'veda-app-ai-draft', true),
('ramayana-5-4-17', 'en', 'Some, uncovered, had the colour of gold lines, some the hue of refined gold, and some, parted from their lovers, were pale as the moon.', 'veda-app-ai-draft', true),
('ramayana-5-4-18', 'en', 'The hero among monkeys saw lovely women in their homes, joyful and loving, having found their dear ones.', 'veda-app-ai-draft', true),
('ramayana-5-4-19', 'en', 'He saw rows of moon-bright faces, rows of lovely eyes with curved lashes, and rows of ornaments like lovely flashes of lightning.', 'veda-app-ai-draft', true),
('ramayana-5-4-20', 'en', 'But he did not see Sita, nobly born of a royal line on the right path, slender like a flowering creeper, born of the mind.', 'veda-app-ai-draft', true),
('ramayana-5-4-21', 'en', 'Firm on the eternal path, her eyes only for Rama, filled with love, she had entered her husband''s noble heart and was always above the finest women.', 'veda-app-ai-draft', true),
('ramayana-5-4-22', 'en', 'Tormented by heat, her throat choked with tears, she who once wore the finest necklace, with lovely lashes and a sweet voice, like a peahen in the forest,', 'veda-app-ai-draft', true),
('ramayana-5-4-23', 'en', 'like a faint sliver of moon, like a streak of gold covered in dust, like an arrow wound that has healed over, like a line of cloud torn by the wind.', 'veda-app-ai-draft', true),
('ramayana-5-4-24', 'en', 'Not seeing Sita, wife of Rama, lord of men and best of speakers, the monkey was struck with sorrow and for a moment felt dull.', 'veda-app-ai-draft', true),
('ramayana-5-5-1', 'en', 'Moving freely among the mansions, able to change form, the monkey roamed Lanka with lightness.', 'veda-app-ai-draft', true),
('ramayana-5-5-2', 'en', 'Then the glorious one reached the rakshasa king''s palace, surrounded by a bright wall the colour of the sun.', 'veda-app-ai-draft', true),
('ramayana-5-5-3', 'en', 'Guarded by fearsome rakshasas like a great forest by lions, the palace shone as the elephant among monkeys looked at it.', 'veda-app-ai-draft', true),
('ramayana-5-5-4', 'en', 'It was surrounded by silver-plated, colourful archways adorned with gold, lovely courtyards and fine gates.', 'veda-app-ai-draft', true),
('ramayana-5-5-5', 'en', 'It was attended by mahouts on elephants, by tireless brave soldiers and by unstoppable horses drawing chariots.', 'veda-app-ai-draft', true),
('ramayana-5-5-6', 'en', 'Chariots always moved about it, armoured in lion and tiger skins, with ivory, gold and silver, colourful and rumbling.', 'veda-app-ai-draft', true),
('ramayana-5-5-7', 'en', 'It was full of many jewels, with costly seats and vessels, the home of great warriors, with great seats for them.', 'veda-app-ai-draft', true),
('ramayana-5-5-8', 'en', 'It was filled on every side with many thousands of beautiful and noble animals and birds.', 'veda-app-ai-draft', true),
('ramayana-5-5-9', 'en', 'It was well guarded by disciplined border guards and rakshasas, and full on every side of the foremost fine women.', 'veda-app-ai-draft', true),
('ramayana-5-5-10', 'en', 'The rakshasa king''s palace, a jewel of joyful women, roared like the sea with the sound of fine ornaments.', 'veda-app-ai-draft', true),
('ramayana-5-5-11', 'en', 'It had every royal quality and the finest sandalwood, and echoed with kettledrums, tabors and conches.', 'veda-app-ai-draft', true),
('ramayana-5-5-12', 'en', 'Always worshipped, with offerings on holy days, honoured by the rakshasas, it was deep as the ocean and loud as the ocean.', 'veda-app-ai-draft', true),
('ramayana-5-5-13', 'en', 'The great monkey saw that great mansion of the great one, with great jewelled furnishings and crowded with great people.', 'veda-app-ai-draft', true),
('ramayana-5-5-14', 'en', 'Shining with its form, crowded with elephants, horses and chariots, the great monkey thought: This is the ornament of Lanka.', 'veda-app-ai-draft', true),
('ramayana-5-5-15', 'en', 'Unafraid, the monkey went from house to house of the rakshasas, looking at gardens and mansions.', 'veda-app-ai-draft', true),
('ramayana-5-5-16', 'en', 'The swift, mighty one leapt down to Prahasta''s house, then leapt to another, Mahaparshva''s.', 'veda-app-ai-draft', true),
('ramayana-5-5-17', 'en', 'Then the great monkey leapt to Kumbhakarna''s house, like a cloud, and to Vibhishana''s.', 'veda-app-ai-draft', true),
('ramayana-5-5-18', 'en', 'He leapt to the houses of Mahodara, Virupaksha, Vidyujjihva, Vidyunmali and Vajradamshtra.', 'veda-app-ai-draft', true),
('ramayana-5-5-19', 'en', 'The swift troop leader went to the houses of Shuka, wise Sarana and Indrajit.', 'veda-app-ai-draft', true),
('ramayana-5-5-20', 'en', 'The troop leader went to the houses of Jambumali, Sumali, Rashmiketu and Suryashatru.', 'veda-app-ai-draft', true),
('ramayana-5-5-21', 'en', 'The son of the Wind went to the houses of Dhumraksha, Sampati, Vidyudrupa, Bhima, Ghana and Vighana,', 'veda-app-ai-draft', true),
('ramayana-5-5-22', 'en', 'of Shukanabha, Vakra, Shatha, Vikata, Hrasvakarna, Damshtra and the rakshasa Romasha,', 'veda-app-ai-draft', true),
('ramayana-5-5-23', 'en', 'of Yuddhonmatta, Matta, Dhvajagriva, Nadin, Vidyujjihva, Indrajihva and Hastimukha,', 'veda-app-ai-draft', true),
('ramayana-5-5-24', 'en', 'of Karala, Pishacha and Shonitaksha: Hanuman, son of the Wind, went through them one by one.', 'veda-app-ai-draft', true),
('ramayana-5-5-25', 'en', 'In each of those costly houses the famous great monkey saw the wealth of those wealthy ones.', 'veda-app-ai-draft', true),
('ramayana-5-5-26', 'en', 'Passing all the houses around, the glorious one then reached the rakshasa king''s own palace.', 'veda-app-ai-draft', true),
('ramayana-5-5-27', 'en', 'Moving about, the tiger among monkeys saw rakshasis with hideous eyes who slept near Ravana, holding spears, hammers, lances and javelins.', 'veda-app-ai-draft', true),
('ramayana-5-5-28', 'en', 'He saw many kinds of guard posts in the rakshasa lord''s house.', 'veda-app-ai-draft', true),
('ramayana-5-5-29', 'en', 'red, white and grey horses, swift steeds, and well-bred, handsome elephants that crushed enemy elephants,', 'veda-app-ai-draft', true),
('ramayana-5-5-30', 'en', 'trained in elephant lore, equal to Airavata in battle, slayers of enemy armies: these he saw in that house.', 'veda-app-ai-draft', true),
('ramayana-5-5-31', 'en', 'They were like raining clouds and streaming mountains, roaring like thunder, invincible in battle.', 'veda-app-ai-draft', true),
('ramayana-5-5-32', 'en', 'There were a thousand troops adorned with gold, covered with gold nets, bright as the rising sun.', 'veda-app-ai-draft', true),
('ramayana-5-5-33', 'en', 'In the rakshasa king Ravana''s palace the monkey, son of the Wind, saw palanquins of many shapes.', 'veda-app-ai-draft', true),
('ramayana-5-5-34', 'en', 'There were colourful bowers of creepers, picture galleries, pleasure houses and artificial hills of wood.', 'veda-app-ai-draft', true),
('ramayana-5-5-35', 'en', 'In Ravana''s palace he saw a lovely house of love and a daytime house.', 'veda-app-ai-draft', true),
('ramayana-5-5-36', 'en', 'He saw a splendid mansion like the slopes of Mandara, full of peacock perches and crowded with flagpoles.', 'veda-app-ai-draft', true),
('ramayana-5-5-37', 'en', 'It held endless heaps of jewels and treasure on every side, its works done by skilled hands, like the house of the lord of beings.', 'veda-app-ai-draft', true),
('ramayana-5-5-38', 'en', 'With the rays of its gems and the splendour of Ravana, the mansion shone like the sun with its rays.', 'veda-app-ai-draft', true),
('ramayana-5-5-39', 'en', 'The troop leader saw golden beds and seats and bright vessels.', 'veda-app-ai-draft', true),
('ramayana-5-5-40', 'en', 'Wet with honey and liquor, full of jewelled vessels, it was charming and spacious, like Kubera''s home.', 'veda-app-ai-draft', true),
('ramayana-5-5-41', 'en', 'It echoed with the sound of anklets and girdles and the loud beat of drums and hand-claps.', 'veda-app-ai-draft', true),
('ramayana-5-5-42', 'en', 'Hanuman entered the great house, with its many palaces, hundreds of fine women and well-laid courtyards.', 'veda-app-ai-draft', true),
('ramayana-5-6-1', 'en', 'The strong one saw the network of houses with lattices of beryl and gold, like a great mass of monsoon clouds laced with lightning and flocks of birds.', 'veda-app-ai-draft', true),
('ramayana-5-6-2', 'en', 'He saw many halls in the houses, chief among them halls for conches, weapons and bows, and charming, spacious moonlit terraces on the house-mountains.', 'veda-app-ai-draft', true),
('ramayana-5-6-3', 'en', 'The monkey saw houses adorned with many riches, honoured by gods and asuras, free of every flaw, won by his own strength.', 'veda-app-ai-draft', true),
('ramayana-5-6-4', 'en', 'He saw the houses of Lanka''s lord, carefully made, as if built by Maya himself, the finest in every way on earth.', 'veda-app-ai-draft', true),
('ramayana-5-6-5', 'en', 'Then he saw the rakshasa lord''s best house, tall as a cloud, charming, of lovely golden form, matching his own power, without equal.', 'veda-app-ai-draft', true),
('ramayana-5-6-6', 'en', 'It was like heaven spread out on earth, blazing with splendour, strewn with many jewels and with flowers of many trees, like a mountain top covered in pollen.', 'veda-app-ai-draft', true),
('ramayana-5-6-7', 'en', 'It shone as if with the finest women, gleamed like a cloud with lightning, and seemed drawn by the finest swans, like a vimana of the virtuous in the sky.', 'veda-app-ai-draft', true),
('ramayana-5-6-8', 'en', 'He saw that jewel of a vimana, colourful with many gems, like a mountain top bright with minerals, like the sky bright with planets and moon.', 'veda-app-ai-draft', true),
('ramayana-5-6-9', 'en', 'On it the earth was made full of mountain ranges, the mountains full of tree canopies, the trees full of blossoms, the flowers full of filaments and petals.', 'veda-app-ai-draft', true),
('ramayana-5-6-10', 'en', 'White houses were made, and lotus ponds in full flower, lotuses with filaments, and lovely, colourful woods.', 'veda-app-ai-draft', true),
('ramayana-5-6-11', 'en', 'There the great monkey saw the great vimana named Pushpaka, shining, glowing with the light of gems, towering above even the finest mansions.', 'veda-app-ai-draft', true),
('ramayana-5-6-12', 'en', 'Birds were made of beryl, others of silver and coral, colourful serpents of many gems, and fine horses true to their breed.', 'veda-app-ai-draft', true),
('ramayana-5-6-13', 'en', 'Birds with fine faces and wings were made, wings of coral and golden flowers, gracefully bent and curved, like Kama''s own wings.', 'veda-app-ai-draft', true),
('ramayana-5-6-14', 'en', 'Elephants with fine trunks, holding lotus leaves with filaments, were shown serving the goddess Lakshmi, made with fine hands, holding a lotus.', 'veda-app-ai-draft', true),
('ramayana-5-6-15', 'en', 'Coming to that lovely house, wonderstruck, he found it like a lovely mountain, very fragrant and beautiful, like a mountain with lovely caves at winter''s end.', 'veda-app-ai-draft', true),
('ramayana-5-6-16', 'en', 'Then the monkey roamed that honoured city guarded by the ten-headed one''s arms, without seeing the honoured, grief-stricken daughter of Janaka, overcome by her husband''s virtues.', 'veda-app-ai-draft', true),
('ramayana-5-6-17', 'en', 'Then, not seeing Janaka''s daughter, the great soul, sharp-eyed and self-controlled, who had trained his mind in many ways and walked the good path, grew very sad as he wandered.', 'veda-app-ai-draft', true),
('ramayana-5-7-1', 'en', 'In the middle of that finest of dwellings, Hanuman, son of the Wind, saw a vast, long, best of buildings.', 'veda-app-ai-draft', true),
('ramayana-5-7-2', 'en', 'The rakshasa king''s palace was half a yojana wide and a yojana long, crowded with many mansions.', 'veda-app-ai-draft', true),
('ramayana-5-7-3', 'en', 'Searching for Vaidehi, wide-eyed Sita, Hanuman, slayer of foes, went all around it.', 'veda-app-ai-draft', true),
('ramayana-5-7-4', 'en', 'It was surrounded by four-tusked and three-tusked elephants, spacious, and guarded by soldiers with raised weapons.', 'veda-app-ai-draft', true),
('ramayana-5-7-5', 'en', 'Ravana''s palace was filled with his rakshasi wives and with princesses he had carried off by force.', 'veda-app-ai-draft', true),
('ramayana-5-7-6', 'en', 'It was like the ocean, full of crocodiles and sea monsters, teeming with timingila fish, tossed by the wind, as if with serpents.', 'veda-app-ai-draft', true),
('ramayana-5-7-7', 'en', 'The splendour of Kubera and of Indra with his bay horses was all in Ravana''s house, never leaving it.', 'veda-app-ai-draft', true),
('ramayana-5-7-8', 'en', 'The wealth of King Kubera, of Yama and of Varuna was here in the rakshasa''s houses, equal or greater.', 'veda-app-ai-draft', true),
('ramayana-5-7-9', 'en', 'In the middle of that mansion the son of the Wind saw another well-built house, crowded with many turrets.', 'veda-app-ai-draft', true),
('ramayana-5-7-10', 'en', 'It was the divine vimana called Pushpaka, adorned with every jewel, made in heaven by Vishvakarma for Brahma.', 'veda-app-ai-draft', true),
('ramayana-5-7-11', 'en', 'What Kubera won from Brahma by great austerity, the rakshasa lord took by defeating Kubera with his might.', 'veda-app-ai-draft', true),
('ramayana-5-7-12', 'en', 'It was covered with well-made pillars of gold, carved with wolves and deer, and seemed to blaze with splendour.', 'veda-app-ai-draft', true),
('ramayana-5-7-13', 'en', 'It was adorned all over with lovely pavilions like Meru and Mandara, as if scraping the sky.', 'veda-app-ai-draft', true),
('ramayana-5-7-14', 'en', 'Like blazing fire or the sun, it was well made by Vishvakarma, with golden stairs and fine, lovely platforms.', 'veda-app-ai-draft', true),
('ramayana-5-7-15', 'en', 'With latticed windows of gold and crystal and fine platforms of sapphire and great blue gems, the great monkey climbed onto the divine vimana Pushpaka.', 'veda-app-ai-draft', true),
('ramayana-5-7-16', 'en', 'Standing there, he smelled the divine, mingled fragrance of drinks, foods and dishes, like the wind made visible.', 'veda-app-ai-draft', true),
('ramayana-5-7-17', 'en', 'That fragrance seemed to say to the great one, as a kinsman to his dearest kin: Come here, where Ravana is.', 'veda-app-ai-draft', true),
('ramayana-5-7-18', 'en', 'Going towards it, he saw a great, lovely hall, dear to Ravana''s heart as a beloved fine woman.', 'veda-app-ai-draft', true),
('ramayana-5-7-19', 'en', 'It had jewelled stairs, shone with gold lattices, had crystal floors and ivory figures inset.', 'veda-app-ai-draft', true),
('ramayana-5-7-20', 'en', 'It was adorned with pearls, coral, silver and gold, and with many jewelled pillars.', 'veda-app-ai-draft', true),
('ramayana-5-7-21', 'en', 'With even, straight, very tall pillars richly adorned all around, it seemed to rise to heaven as if on wings.', 'veda-app-ai-draft', true),
('ramayana-5-7-22', 'en', 'Spread with a great carpet marked with the features of the earth, it was as wide as the earth, garlanded with kingdoms and houses.', 'veda-app-ai-draft', true),
('ramayana-5-7-23', 'en', 'It echoed with excited birds, was scented with divine perfumes, had costly coverings, and was frequented by the rakshasa lord.', 'veda-app-ai-draft', true),
('ramayana-5-7-24', 'en', 'Smoky with aloe incense, yet clean and white as a swan, colourful with flower offerings, it shone like the spotted wish-granting cow.', 'veda-app-ai-draft', true),
('ramayana-5-7-25', 'en', 'It delighted the mind, brightened the complexion, drove away grief, and seemed to give birth to splendour itself.', 'veda-app-ai-draft', true),
('ramayana-5-7-26', 'en', 'Guarded by Ravana, the hall pleased the five senses with the five finest sense objects, like a mother.', 'veda-app-ai-draft', true),
('ramayana-5-7-27', 'en', 'Is this heaven, the world of the gods, or Indra''s city? Or is it the supreme attainment? So the son of the Wind wondered.', 'veda-app-ai-draft', true),
('ramayana-5-7-28', 'en', 'He saw golden lamps there, seemingly lost in thought, like gamblers beaten at dice by greater gamblers.', 'veda-app-ai-draft', true),
('ramayana-5-7-29', 'en', 'With the light of the lamps, Ravana''s splendour and the gleam of ornaments, he thought the hall was ablaze.', 'veda-app-ai-draft', true),
('ramayana-5-7-30', 'en', 'Then he saw a thousand fine women seated on carpets, in robes and garlands of many colours, dressed in many styles.', 'veda-app-ai-draft', true),
('ramayana-5-7-31', 'en', 'After midnight, overcome by drink and sleep, having ceased their play, they fell into deep sleep.', 'veda-app-ai-draft', true),
('ramayana-5-7-32', 'en', 'Asleep, with their ornaments silent, the gathering shone like a great lotus forest with its swans and bees fallen silent.', 'veda-app-ai-draft', true),
('ramayana-5-7-33', 'en', 'The son of the Wind saw the faces of those lovely women, lips closed, eyes shut, fragrant as lotuses.', 'veda-app-ai-draft', true),
('ramayana-5-7-34', 'en', 'Their faces, like lotuses that open at dawn and close their petals again at night, looked like that then.', 'veda-app-ai-draft', true),
('ramayana-5-7-35', 'en', 'Surely bees seek these lotus faces again and again, as they seek blossoming lotuses.', 'veda-app-ai-draft', true),
('ramayana-5-7-36', 'en', 'So the glorious great monkey reasoned, for he judged those faces equal in quality to water-born lotuses.', 'veda-app-ai-draft', true),
('ramayana-5-7-37', 'en', 'Adorned with those women, his hall shone like the clear autumn sky lit with stars.', 'veda-app-ai-draft', true),
('ramayana-5-7-38', 'en', 'Surrounded by them, the rakshasa lord shone like the glorious moon, lord of stars, among the stars.', 'veda-app-ai-draft', true),
('ramayana-5-7-39', 'en', 'The monkey then thought: The stars that fall from the sky when their merit runs out have all gathered here.', 'veda-app-ai-draft', true),
('ramayana-5-7-40', 'en', 'The radiance, colour and grace of the women shone there like that of great, bright stars.', 'veda-app-ai-draft', true),
('ramayana-5-7-41', 'en', 'Their heavy garlands askew, their fine ornaments scattered, their minds taken by sleep after drinking and dancing,', 'veda-app-ai-draft', true),
('ramayana-5-7-42', 'en', 'some had their forehead marks smudged, some their anklets slipped, some had necklaces fallen to their sides.', 'veda-app-ai-draft', true),
('ramayana-5-7-43', 'en', 'Others had faces covered by necklaces, some had loosened garments and girdles, like young mares after being driven.', 'veda-app-ai-draft', true),
('ramayana-5-7-44', 'en', 'Others, wearing fine earrings with garlands torn and crushed, were like flowering creepers trampled by a great elephant in the forest.', 'veda-app-ai-draft', true),
('ramayana-5-7-45', 'en', 'The large necklaces of some, bright as moonbeams, looked like sleeping swans.', 'veda-app-ai-draft', true),
('ramayana-5-7-46', 'en', 'Others'' beryl ornaments looked like kadamba birds, and others'' gold chains looked like ruddy geese.', 'veda-app-ai-draft', true),
('ramayana-5-7-47', 'en', 'They shone like rivers full of swans and ducks, graced with ruddy geese, with sandbanks.', 'veda-app-ai-draft', true),
('ramayana-5-7-48', 'en', 'Like sleeping rivers they shone, with bells for ripples, golden ornaments for lotuses, feelings for crocodiles and fame for banks.', 'veda-app-ai-draft', true),
('ramayana-5-7-49', 'en', 'Lovely lines of ornament marks on soft limbs looked like ornaments themselves.', 'veda-app-ai-draft', true),
('ramayana-5-7-50', 'en', 'The edges of some veils, stirred by their breath, fluttered again and again over their faces.', 'veda-app-ai-draft', true),
('ramayana-5-7-51', 'en', 'Those bright veils of many colours shone at the wives'' faces like waving banners.', 'veda-app-ai-draft', true),
('ramayana-5-7-52', 'en', 'The earrings of some lovely, radiant women swayed gently with their breathing.', 'veda-app-ai-draft', true),
('ramayana-5-7-53', 'en', 'Their breath, naturally fragrant and pleasant, scented with sugar wine, wafted over Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-7-54', 'en', 'Some of Ravana''s wives, thinking it was Ravana''s face, kept nuzzling the faces of their co-wives.', 'veda-app-ai-draft', true),
('ramayana-5-7-55', 'en', 'Deeply attached to Ravana, those fine women, not in control of themselves, showed affection to their co-wives.', 'veda-app-ai-draft', true),
('ramayana-5-7-56', 'en', 'Other young women slept with their arms as pillows, on their lovely garments, adorned with bangles.', 'veda-app-ai-draft', true),
('ramayana-5-7-57', 'en', 'One lay on another''s chest, another on her arm, another on someone''s lap, another on her arms.', 'veda-app-ai-draft', true),
('ramayana-5-7-58', 'en', 'Leaning on one another''s thighs, sides, waists and backs, their limbs intertwined, they followed the sway of wine and affection.', 'veda-app-ai-draft', true),
('ramayana-5-7-59', 'en', 'Pleased by touching each other, those slender women all slept there with their arms linked together.', 'veda-app-ai-draft', true),
('ramayana-5-7-60', 'en', 'Strung together by the thread of their linked arms, the garland of women shone like a garland on a string visited by bees.', 'veda-app-ai-draft', true),
('ramayana-5-7-61', 'en', 'Like flowering creepers in spring, stirred by the wind, entwined into garlands, their heaps of flowers touching,', 'veda-app-ai-draft', true),
('ramayana-5-7-62', 'en', 'with well-joined branches twined together and full of bees, Ravana''s forest of women was like a wind-tossed wood.', 'veda-app-ai-draft', true),
('ramayana-5-7-63', 'en', 'Though clearly visible, one could not then tell apart the women''s ornaments, limbs, garments and garlands.', 'veda-app-ai-draft', true),
('ramayana-5-7-64', 'en', 'While Ravana slept at ease, the golden lamps seemed to gaze unblinking at those women of many hues.', 'veda-app-ai-draft', true),
('ramayana-5-7-65', 'en', 'Daughters of royal sages, of ancestors, daityas, gandharvas and rakshasas had come under the sway of his desire.', 'veda-app-ai-draft', true),
('ramayana-5-7-66', 'en', 'No woman there had been taken by force; all were won by his valour and qualities. None loved another or had belonged to another, except the noble daughter of Janaka.', 'veda-app-ai-draft', true),
('ramayana-5-7-67', 'en', 'None of his wives was low-born or plain, ungracious or lacking courtesy, weak in spirit or undesirable to her lover.', 'veda-app-ai-draft', true),
('ramayana-5-7-68', 'en', 'The good-hearted lord of monkeys thought: If Rama''s lawful wife were treated as these wives of the rakshasa king are, it would be well for him.', 'veda-app-ai-draft', true),
('ramayana-5-7-69', 'en', 'Then, distressed, he thought again: Surely Sita is far above them in virtue, and the great lord of Lanka has done a cruel, ignoble thing to her.', 'veda-app-ai-draft', true),
('ramayana-5-8-1', 'en', 'Looking around, Hanuman saw there a heavenly, splendid crystal couch adorned with jewels.', 'veda-app-ai-draft', true),
('ramayana-5-8-2', 'en', 'In one part of it he saw a white parasol adorned with fine garlands, like the moon, lord of stars.', 'veda-app-ai-draft', true),
('ramayana-5-8-3', 'en', 'It was fanned on all sides by women with yak-tail fans, filled with many scents and perfumed with fine incense.', 'veda-app-ai-draft', true),
('ramayana-5-8-4', 'en', 'It was spread with the finest coverings, wrapped in sheepskin, and adorned all around with strings of fine garlands.', 'veda-app-ai-draft', true),
('ramayana-5-8-5', 'en', 'On it lay one like a dark cloud, with blazing earrings, red eyes, mighty arms, and robes of fine gold,', 'veda-app-ai-draft', true),
('ramayana-5-8-6', 'en', 'his body anointed with fragrant red sandal, like a cloud reddened by twilight and laced with lightning,', 'veda-app-ai-draft', true),
('ramayana-5-8-7', 'en', 'wearing divine ornaments, handsome and able to change form, like Mount Mandara asleep with its trees, woods and thickets.', 'veda-app-ai-draft', true),
('ramayana-5-8-8', 'en', 'Having ceased his play at night, adorned with fine ornaments, beloved of rakshasa women, and the joy of the rakshasas,', 'veda-app-ai-draft', true),
('ramayana-5-8-9', 'en', 'having drunk and rested, the great monkey saw the heroic rakshasa lord asleep on a shining bed.', 'veda-app-ai-draft', true),
('ramayana-5-8-10', 'en', 'Coming near Ravana, who breathed like a serpent, the best of monkeys was alarmed and drew back as if frightened.', 'veda-app-ai-draft', true),
('ramayana-5-8-11', 'en', 'Then, climbing up to a platform, the great monkey watched the sleeping tiger among rakshasas.', 'veda-app-ai-draft', true),
('ramayana-5-8-12', 'en', 'The rakshasa lord''s fine bed shone as he slept, like a great waterfall with a scented elephant lying near it.', 'veda-app-ai-draft', true),
('ramayana-5-8-13', 'en', 'He saw the great one''s arms flung out, bound with gold armlets, like Indra''s banners.', 'veda-app-ai-draft', true),
('ramayana-5-8-14', 'en', 'They bore scars from the tips of Airavata''s tusks, his thick shoulders were scratched by the thunderbolt and marked by Vishnu''s discus.', 'veda-app-ai-draft', true),
('ramayana-5-8-15', 'en', 'They were thick, with well-formed, even shoulders, strong and close-knit, with fine nails and thumbs and well-marked fingers and palms.', 'veda-app-ai-draft', true),
('ramayana-5-8-16', 'en', 'Firm, like iron bars, round like an elephant''s trunk, flung out on the white bed like five-headed serpents.', 'veda-app-ai-draft', true),
('ramayana-5-8-17', 'en', 'They were smeared with costly, cool, fragrant sandal, red as hare''s blood, and well adorned.', 'veda-app-ai-draft', true),
('ramayana-5-8-18', 'en', 'Caressed by the finest women and scented with the best perfumes, those arms made yakshas, serpents, gandharvas, gods and danavas cry out.', 'veda-app-ai-draft', true),
('ramayana-5-8-19', 'en', 'The monkey saw his two arms on the bed like two angry great serpents asleep in a cave of Mandara.', 'veda-app-ai-draft', true),
('ramayana-5-8-20', 'en', 'With those full arms, the mountain-like rakshasa lord shone like Mandara with two peaks.', 'veda-app-ai-draft', true),
('ramayana-5-8-21', 'en', 'Fragrant with mango and punnaga, with the finest bakula, mingled with fine food and drink and led by the smell of wine,', 'veda-app-ai-draft', true),
('ramayana-5-8-22', 'en', 'a great breath came from the mouth of the sleeping lion among rakshasas, as if filling the house.', 'veda-app-ai-draft', true),
('ramayana-5-8-23', 'en', 'His face glowed with earrings and with a shining golden crown, studded with pearls and gems, slipped aside.', 'veda-app-ai-draft', true),
('ramayana-5-8-24', 'en', 'He was adorned with a necklace smeared with red sandal, and his broad, thick, long chest shone.', 'veda-app-ai-draft', true),
('ramayana-5-8-25', 'en', 'Red-eyed, he was wrapped in a costly yellow robe, with a white linen cloth thrown aside.', 'veda-app-ai-draft', true),
('ramayana-5-8-26', 'en', 'Like a heap of black beans, hissing like a serpent, he was like an elephant asleep in the deep water of the Ganga.', 'veda-app-ai-draft', true),
('ramayana-5-8-27', 'en', 'Lit on all four sides by four blazing golden lamps, his whole body was illuminated like a cloud with flashes of lightning.', 'veda-app-ai-draft', true),
('ramayana-5-8-28', 'en', 'He also saw the wives of the great rakshasa lord, who loved his wives, lying at his feet in his house.', 'veda-app-ai-draft', true),
('ramayana-5-8-29', 'en', 'The troop leader saw them with moon-bright faces, adorned with fine earrings, their garlands and ornaments unfaded.', 'veda-app-ai-draft', true),
('ramayana-5-8-30', 'en', 'The monkey saw women skilled in dance and music, who lay in the rakshasa king''s arms and lap, wearing fine ornaments, resting.', 'veda-app-ai-draft', true),
('ramayana-5-8-31', 'en', 'He saw gold earrings and armlets set with diamonds and beryl at the women''s ears.', 'veda-app-ai-draft', true),
('ramayana-5-8-32', 'en', 'With their moon-like faces and lovely swinging earrings, the vimana shone like the sky with hosts of stars.', 'veda-app-ai-draft', true),
('ramayana-5-8-33', 'en', 'Tired from wine and dancing, the slender wives of the rakshasa king slept wherever there was room.', 'veda-app-ai-draft', true),
('ramayana-5-8-34', 'en', 'One shone asleep embracing her vina, like a lotus washed down a great river clinging to a boat.', 'veda-app-ai-draft', true),
('ramayana-5-8-35', 'en', 'Another dark-eyed lady slept with a small drum under her arm, like a loving mother with her baby son.', 'veda-app-ai-draft', true),
('ramayana-5-8-36', 'en', 'A graceful one slept hugging a drum, like a woman embracing her beloved after a long time.', 'veda-app-ai-draft', true),
('ramayana-5-8-37', 'en', 'One lotus-eyed lady slept with her arms around another''s shoulder, overcome by sleep, as if with her beloved.', 'veda-app-ai-draft', true),
('ramayana-5-8-38', 'en', 'Another, her eyes heavy, slept hugging a tabor with her soft, golden limbs.', 'veda-app-ai-draft', true),
('ramayana-5-8-39', 'en', 'A slender, blameless one, tired from wine, slept with a small drum tucked under her arm.', 'veda-app-ai-draft', true),
('ramayana-5-8-40', 'en', 'Another slept holding a dindima drum, like a lady cuddling a young calf.', 'veda-app-ai-draft', true),
('ramayana-5-8-41', 'en', 'A lotus-eyed woman, dazed with wine, slept with an adambara drum clasped in her arms.', 'veda-app-ai-draft', true),
('ramayana-5-8-42', 'en', 'Another lady slept with her water jar tossed aside, like a spring garland bright with flowers, freshly sprinkled.', 'veda-app-ai-draft', true),
('ramayana-5-8-43', 'en', 'One young woman slept with her arms folded across herself, beaten by the power of sleep.', 'veda-app-ai-draft', true),
('ramayana-5-8-44', 'en', 'Another lotus-eyed lady with a face like the full moon slept embracing a friend, overcome with wine.', 'veda-app-ai-draft', true),
('ramayana-5-8-45', 'en', 'Fine women slept clasping their colourful instruments as lovers clasp their beloveds.', 'veda-app-ai-draft', true),
('ramayana-5-8-46', 'en', 'Apart from them, on a lovely bed set aside, the monkey saw another beautiful woman lying.', 'veda-app-ai-draft', true),
('ramayana-5-8-47', 'en', 'She was richly adorned with ornaments of pearls and gems, and seemed to adorn that fine palace with her own splendour.', 'veda-app-ai-draft', true),
('ramayana-5-8-48', 'en', 'The monkey saw Mandodari lying there, fair, golden-hued, beloved, mistress of the inner palace, of lovely form.', 'veda-app-ai-draft', true),
('ramayana-5-8-49', 'en', 'Seeing her adorned, the mighty-armed son of the Wind guessed from her beauty and youth that she was Sita, and the troop leader was filled with great joy.', 'veda-app-ai-draft', true),
('ramayana-5-8-50', 'en', 'He slapped his arms, kissed his tail, rejoiced, played, sang, ran about, climbed pillars and jumped to the ground, showing his monkey nature.', 'veda-app-ai-draft', true),
('ramayana-5-9-1', 'en', 'Shaking off that idea, the great monkey grew steady, and had another thought about Sita.', 'veda-app-ai-draft', true),
('ramayana-5-9-2', 'en', 'Parted from Rama, that lady would not sleep, eat, adorn herself or drink.', 'veda-app-ai-draft', true),
('ramayana-5-9-3', 'en', 'She would never go near another man, not even the lord of the gods, for no one even among the gods equals Rama. Deciding this was someone else, he moved on through the banquet hall.', 'veda-app-ai-draft', true),
('ramayana-5-9-4', 'en', 'Some women were tired from play, others from song, others from dance, others overcome by drink.', 'veda-app-ai-draft', true),
('ramayana-5-9-5', 'en', 'Other women lay on drums, tabors and stools, and on the finest rugs.', 'veda-app-ai-draft', true),
('ramayana-5-9-6', 'en', 'with a thousand women adorned with ornaments, skilled in beauty and conversation, speaking the meaning of songs,', 'veda-app-ai-draft', true),
('ramayana-5-9-7', 'en', 'knowing place and time and speaking fitting words: among them the troop leader saw Ravana, asleep after his pleasures.', 'veda-app-ai-draft', true),
('ramayana-5-9-8', 'en', 'In their midst the mighty-armed rakshasa lord shone like a bull among the best cows in a great pen.', 'veda-app-ai-draft', true),
('ramayana-5-9-9', 'en', 'Surrounded by them, the rakshasa lord himself shone like a great elephant in the forest surrounded by female elephants.', 'veda-app-ai-draft', true),
('ramayana-5-9-10', 'en', 'The tiger among monkeys saw the great one''s banquet hall in the rakshasa lord''s house, supplied with every pleasure.', 'veda-app-ai-draft', true),
('ramayana-5-9-11', 'en', 'In the banquet hall he saw meats of deer, buffalo and boar set out in portions.', 'veda-app-ai-draft', true),
('ramayana-5-9-12', 'en', 'In large golden dishes the tiger among monkeys saw half-eaten peacocks and fowl.', 'veda-app-ai-draft', true),
('ramayana-5-9-13', 'en', 'Hanuman looked at boar and rhinoceros dishes with curd and salt, porcupine, deer and peacock.', 'veda-app-ai-draft', true),
('ramayana-5-9-14', 'en', 'He saw many kinds of cooked partridges, half-eaten chakoras, buffalo, goats well prepared, and all kinds of food, drink and dishes.', 'veda-app-ai-draft', true),
('ramayana-5-9-15', 'en', 'with sour and salty relishes, many kinds of sweets and sauces, and costly necklaces, anklets and armlets tossed aside,', 'veda-app-ai-draft', true),
('ramayana-5-9-16', 'en', 'With scattered drinking vessels and many fruits, the floor, decked with flower offerings, looked even more splendid.', 'veda-app-ai-draft', true),
('ramayana-5-9-17', 'en', 'With well-set beds and seats placed here and there, the banquet hall seemed ablaze without fire.', 'veda-app-ai-draft', true),
('ramayana-5-9-18', 'en', 'There were meats of many kinds, prepared with fine seasoning by skilled cooks, set apart in the banquet hall.', 'veda-app-ai-draft', true),
('ramayana-5-9-19', 'en', 'There were divine, clear wines of many kinds, distilled liquors, sugar wines, honey wines, flower and fruit wines, each scented with various perfumed powders.', 'veda-app-ai-draft', true),
('ramayana-5-9-20', 'en', 'The floor shone, covered with many garlands, with golden jars, crystal vessels and other golden pitchers.', 'veda-app-ai-draft', true),
('ramayana-5-9-21', 'en', 'In silver and golden pots the monkey saw plenty of the finest drink.', 'veda-app-ai-draft', true),
('ramayana-5-9-22', 'en', 'The great monkey saw golden, jewelled and silver vessels full of liquor.', 'veda-app-ai-draft', true),
('ramayana-5-9-23', 'en', 'He saw drinks here half finished, there drunk to the last drop, and elsewhere untouched.', 'veda-app-ai-draft', true),
('ramayana-5-9-24', 'en', 'He wandered on, seeing foods of many kinds here, drinks in portions there, and leftovers elsewhere.', 'veda-app-ai-draft', true),
('ramayana-5-9-25', 'en', 'Here were broken pitchers, there overturned pots, elsewhere water and fruit mixed with garlands.', 'veda-app-ai-draft', true),
('ramayana-5-9-26', 'en', 'Many of the women''s beds were empty, while some fine ladies slept holding each other.', 'veda-app-ai-draft', true),
('ramayana-5-9-27', 'en', 'One young woman, overcome by sleep, took another''s garment, wrapped herself in it and fell asleep.', 'veda-app-ai-draft', true),
('ramayana-5-9-28', 'en', 'Stirred by their breath, their garments and garlands moved only slightly, as if in a gentle breeze.', 'veda-app-ai-draft', true),
('ramayana-5-9-29', 'en', 'The scent of cool sandal, of sweet liquor, of many garlands and many flowers,', 'veda-app-ai-draft', true),
('ramayana-5-9-30', 'en', 'and of baths, sandal and incense, carried in many ways by the wind, filled the Pushpaka vimana with fragrance.', 'veda-app-ai-draft', true),
('ramayana-5-9-31', 'en', 'In the rakshasa''s home some fine women were dusky, some fair, some dark, some golden-skinned.', 'veda-app-ai-draft', true),
('ramayana-5-9-32', 'en', 'Overcome by sleep and wine, they looked like lotus pools asleep.', 'veda-app-ai-draft', true),
('ramayana-5-9-33', 'en', 'So the radiant monkey saw the whole of Ravana''s inner palace, but he did not see Janaki.', 'veda-app-ai-draft', true),
('ramayana-5-9-34', 'en', 'Looking at those women, the great monkey fell into deep thought, worried about breaking dharma.', 'veda-app-ai-draft', true),
('ramayana-5-9-35', 'en', 'Looking at the sleeping women of another man''s household will surely make me break dharma badly.', 'veda-app-ai-draft', true),
('ramayana-5-9-36', 'en', 'My gaze has never strayed to other men''s wives, yet here I have seen the wives of another.', 'veda-app-ai-draft', true),
('ramayana-5-9-37', 'en', 'Then another thought came to the wise one, whose mind was fixed on one aim, a thought that saw clearly what the task required.', 'veda-app-ai-draft', true),
('ramayana-5-9-38', 'en', 'True, I have seen all Ravana''s wives off guard, but no change at all has come over my mind.', 'veda-app-ai-draft', true),
('ramayana-5-9-39', 'en', 'The mind is what drives all the senses, in good and bad states alike, and my mind is firmly steady.', 'veda-app-ai-draft', true),
('ramayana-5-9-40', 'en', 'I could not have searched for Vaidehi anywhere else. When searching, women are always looked for among women.', 'veda-app-ai-draft', true),
('ramayana-5-9-41', 'en', 'A creature is sought among its own kind. A lost woman cannot be searched for among does.', 'veda-app-ai-draft', true),
('ramayana-5-9-42', 'en', 'So I have searched the whole of Ravana''s inner palace with a pure mind, but Janaki is not to be seen.', 'veda-app-ai-draft', true),
('ramayana-5-9-43', 'en', 'Looking at daughters of gods, gandharvas and nagas, mighty Hanuman did not see Janaki.', 'veda-app-ai-draft', true),
('ramayana-5-9-44', 'en', 'Not seeing her, but seeing other fine women, the hero withdrew and began to think deeply.', 'veda-app-ai-draft', true),
('ramayana-5-10-1', 'en', 'Eager to see Sita, the monkey went through bowers, picture halls and night chambers in the middle of the palace, but he did not see the lovely one.', 'veda-app-ai-draft', true),
('ramayana-5-10-2', 'en', 'The great monkey thought, not finding Rama''s beloved: Surely Sita is dead, since Maithili does not appear to me as I search.', 'veda-app-ai-draft', true),
('ramayana-5-10-3', 'en', 'That young, virtuous lady, devoted to guarding her own virtue and firm on the noble path, must have been killed by this wicked best of rakshasas.', 'veda-app-ai-draft', true),
('ramayana-5-10-4', 'en', 'Or perhaps, seeing the rakshasa king''s women, deformed, ugly, pale, wide-mouthed and grim-looking, Janaka''s daughter died of fear.', 'veda-app-ai-draft', true),
('ramayana-5-10-5', 'en', 'Without seeing Sita and without showing any manliness, having spent so long with the monkeys, I have no way back to Sugriva, for the monkey is strong and his punishments harsh.', 'veda-app-ai-draft', true),
('ramayana-5-10-6', 'en', 'I have seen the whole inner palace and all Ravana''s women, but the virtuous Sita is not seen. My effort has been in vain.', 'veda-app-ai-draft', true),
('ramayana-5-10-7', 'en', 'What will all the monkeys say when they gather and I return? Hero, you went there; tell us what you did.', 'veda-app-ai-draft', true),
('ramayana-5-10-8', 'en', 'Having not seen Janaka''s daughter, what will I tell them? They will surely fast to death now the time has passed.', 'veda-app-ai-draft', true),
('ramayana-5-10-9', 'en', 'What will old Jambavan and Angada say, and the monkeys gathered there, when I go back across the ocean?', 'veda-app-ai-draft', true),
('ramayana-5-10-10', 'en', 'Not losing heart is the root of success; not losing heart is the highest happiness. I will search again where I have not searched.', 'veda-app-ai-draft', true),
('ramayana-5-10-11', 'en', 'Not losing heart always drives every undertaking forward. It makes whatever a person does bear fruit.', 'veda-app-ai-draft', true),
('ramayana-5-10-12', 'en', 'So I will make the highest effort, born of not losing heart, and search the places guarded by Ravana that I have not yet seen.', 'veda-app-ai-draft', true),
('ramayana-5-10-13', 'en', 'The drinking halls have been searched, the flower houses, the picture halls, and again the pleasure houses.', 'veda-app-ai-draft', true),
('ramayana-5-10-14', 'en', 'and the lanes between the gardens, and all the vimanas. Thinking this, he began to search again.', 'veda-app-ai-draft', true),
('ramayana-5-10-15', 'en', 'Underground rooms, shrines, and houses beyond houses: leaping up and dropping down, standing still here, moving on there,', 'veda-app-ai-draft', true),
('ramayana-5-10-16', 'en', 'opening doors, pushing on panels, going in and coming out, falling and rising, the great monkey went through every space.', 'veda-app-ai-draft', true),
('ramayana-5-10-17', 'en', 'There was not even a space four fingers wide in Ravana''s inner palace that the monkey did not visit.', 'veda-app-ai-draft', true),
('ramayana-5-10-18', 'en', 'The lanes within the walls, the platforms by the shrines, the pits and the lotus ponds: he looked at everything.', 'veda-app-ai-draft', true),
('ramayana-5-10-19', 'en', 'Hanuman saw rakshasis of many shapes, ugly and deformed, but not Janaka''s daughter.', 'veda-app-ai-draft', true),
('ramayana-5-10-20', 'en', 'Hanuman saw vidyadhara women, unmatched in beauty in the world, but not Rama''s delight.', 'veda-app-ai-draft', true),
('ramayana-5-10-21', 'en', 'Hanuman saw lovely naga maidens with faces like the full moon, but not slender Sita.', 'veda-app-ai-draft', true),
('ramayana-5-10-22', 'en', 'Hanuman saw naga maidens carried off by force by the rakshasa lord, but not Janaka''s daughter.', 'veda-app-ai-draft', true),
('ramayana-5-10-23', 'en', 'Not seeing her, but seeing other fine women, mighty-armed Hanuman, son of the Wind, lost heart.', 'veda-app-ai-draft', true),
('ramayana-5-10-24', 'en', 'Seeing the monkey chiefs'' efforts and his leap across the ocean wasted, the Wind''s son fell into worry again.', 'veda-app-ai-draft', true),
('ramayana-5-10-25', 'en', 'Coming down from the vimana, Hanuman, son of the Wind, his mind struck by grief, fell to thinking.', 'veda-app-ai-draft', true),
('ramayana-5-11-1', 'en', 'Moving from the vimana to the wall, the troop leader Hanuman was swift like lightning in a cloud.', 'veda-app-ai-draft', true),
('ramayana-5-11-2', 'en', 'Having gone all around Ravana''s palaces without seeing Janaki, the monkey said:', 'veda-app-ai-draft', true),
('ramayana-5-11-3', 'en', 'I have searched most of Lanka to please Rama, but I do not see Vaidehi, lovely in every limb.', 'veda-app-ai-draft', true),
('ramayana-5-11-4', 'en', 'Pools, tanks, lakes, streams, rivers, marshy woods, fortresses and mountains: the whole land is searched, and I do not see Janaki.', 'veda-app-ai-draft', true),
('ramayana-5-11-5', 'en', 'The vulture king Sampati said Sita was here in Ravana''s house, yet I do not see her.', 'veda-app-ai-draft', true),
('ramayana-5-11-6', 'en', 'Could Sita, Vaidehi, Maithili, Janaka''s daughter, helpless, have yielded to the evil-doing Ravana?', 'veda-app-ai-draft', true),
('ramayana-5-11-7', 'en', 'I think that as the rakshasa flew up quickly carrying Sita, afraid of Rama''s arrows, she may have fallen on the way.', 'veda-app-ai-draft', true),
('ramayana-5-11-8', 'en', 'Or perhaps, as the noble lady was carried along the path of the siddhas, her heart failed when she saw the ocean.', 'veda-app-ai-draft', true),
('ramayana-5-11-9', 'en', 'I think the noble wide-eyed lady gave up her life, crushed by Ravana''s arms and the force of his flight.', 'veda-app-ai-draft', true),
('ramayana-5-11-10', 'en', 'Or surely, as he crossed high over the ocean, Janaka''s daughter struggled and fell into the sea.', 'veda-app-ai-draft', true),
('ramayana-5-11-11', 'en', 'Or perhaps the poor, friendless Sita, guarding her virtue, was eaten by this petty Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-11-12', 'en', 'Or the innocent dark-eyed lady may have been eaten by the rakshasa king''s spiteful wives.', 'veda-app-ai-draft', true),
('ramayana-5-11-13', 'en', 'Thinking of Rama''s face, like the full moon, with eyes like lotus petals, the poor lady may have died.', 'veda-app-ai-draft', true),
('ramayana-5-11-14', 'en', 'Crying Oh Rama, oh Lakshmana, oh Ayodhya, Maithili may have wept much and given up her body.', 'veda-app-ai-draft', true),
('ramayana-5-11-15', 'en', 'Or I think she is hidden away in Ravana''s house, surely crying softly like a myna in a cage.', 'veda-app-ai-draft', true),
('ramayana-5-11-16', 'en', 'How could slender, lotus-eyed Sita, born in Janaka''s line and Rama''s wife, ever fall under Ravana''s power?', 'veda-app-ai-draft', true),
('ramayana-5-11-17', 'en', 'Whether Janaka''s daughter is lost, vanished or dead, it is not right to tell Rama, who loves his wife so much.', 'veda-app-ai-draft', true),
('ramayana-5-11-18', 'en', 'There is harm in telling him and harm in not telling. What should I do? It all seems so hard.', 'veda-app-ai-draft', true),
('ramayana-5-11-19', 'en', 'In this situation, what is timely and right? Hanuman thought it over again.', 'veda-app-ai-draft', true),
('ramayana-5-11-20', 'en', 'If I go back to the monkey king''s city without seeing Sita, what will I have achieved?', 'veda-app-ai-draft', true),
('ramayana-5-11-21', 'en', 'My leap across the ocean will be wasted, and my entering Lanka and seeing the rakshasas too.', 'veda-app-ai-draft', true),
('ramayana-5-11-22', 'en', 'What will Sugriva say, or the monkeys gathered there, or the two sons of Dasharatha who have come to Kishkindha?', 'veda-app-ai-draft', true),
('ramayana-5-11-23', 'en', 'If I go and give Rama the terrible news that I did not see Sita, he will give up his life.', 'veda-app-ai-draft', true),
('ramayana-5-11-24', 'en', 'Hearing such harsh, cruel, piercing words about Sita, which burn the senses, he will not survive.', 'veda-app-ai-draft', true),
('ramayana-5-11-25', 'en', 'Seeing him in distress and set on death, loyal, wise Lakshmana will not survive either.', 'veda-app-ai-draft', true),
('ramayana-5-11-26', 'en', 'Hearing that both brothers have died, Bharata will die too, and seeing Bharata dead, Shatrughna will not live.', 'veda-app-ai-draft', true),
('ramayana-5-11-27', 'en', 'Seeing their sons dead, the mothers Kausalya, Sumitra and Kaikeyi will not live, no doubt.', 'veda-app-ai-draft', true),
('ramayana-5-11-28', 'en', 'Grateful Sugriva, lord of the monkeys, true to his word, seeing Rama gone, will give up his life.', 'veda-app-ai-draft', true),
('ramayana-5-11-29', 'en', 'Heartbroken, pained, wretched and joyless, tormented by grief for her husband, poor Ruma will give up her life.', 'veda-app-ai-draft', true),
('ramayana-5-11-30', 'en', 'Already pained by grief for Vali and worn by sorrow, Tara too will not live when the king dies.', 'veda-app-ai-draft', true),
('ramayana-5-11-31', 'en', 'With his mother and father gone and Sugriva lost, why would young Angada keep his life?', 'veda-app-ai-draft', true),
('ramayana-5-11-32', 'en', 'Overwhelmed by grief for their master, the forest-dwellers will beat their heads with palms and fists.', 'veda-app-ai-draft', true),
('ramayana-5-11-33', 'en', 'The monkeys, cherished by the famous monkey king with kindness, gifts and honour, will give up their lives.', 'veda-app-ai-draft', true),
('ramayana-5-11-34', 'en', 'The great monkeys will no longer gather to play in the woods, on the mountains or in hidden places.', 'veda-app-ai-draft', true),
('ramayana-5-11-35', 'en', 'With their children, wives and ministers, pained by their master''s ruin, they will gather and throw themselves from mountain tops onto rough ground.', 'veda-app-ai-draft', true),
('ramayana-5-11-36', 'en', 'The monkeys will take poison, hang themselves, enter fire, fast or use weapons.', 'veda-app-ai-draft', true),
('ramayana-5-11-37', 'en', 'I think a terrible wailing will arise when I return, and the ruin of the Ikshvaku line and of the forest-dwellers.', 'veda-app-ai-draft', true),
('ramayana-5-11-38', 'en', 'So I will not go from here to the city of Kishkindha. I cannot face Sugriva without Maithili.', 'veda-app-ai-draft', true),
('ramayana-5-11-39', 'en', 'If I stay here and do not go, the two righteous great warriors and the high-minded monkeys will live on in hope.', 'veda-app-ai-draft', true),
('ramayana-5-11-40', 'en', 'Without seeing Janaka''s daughter I will become a forest hermit, living on what falls into my hand or mouth, disciplined, at the foot of a tree.', 'veda-app-ai-draft', true),
('ramayana-5-11-41', 'en', 'In the coastal land rich in roots, fruit and water, I will build a pyre and enter the blazing fire.', 'veda-app-ai-draft', true),
('ramayana-5-11-42', 'en', 'Or as I sit fasting to the end, crows and beasts of prey will eat my body.', 'veda-app-ai-draft', true),
('ramayana-5-11-43', 'en', 'This too is a way of departing seen by the sages, I think: I will enter the water, if I do not see Janaki.', 'veda-app-ai-draft', true),
('ramayana-5-11-44', 'en', 'My long night, of fine roots, fortunate, glorious with a garland of fame, is broken, since I do not see Sita.', 'veda-app-ai-draft', true),
('ramayana-5-11-45', 'en', 'Or I will become an ascetic, disciplined, living at the foot of a tree. I will not go back without seeing the dark-eyed lady.', 'veda-app-ai-draft', true),
('ramayana-5-11-46', 'en', 'If I go back without finding Sita, Angada and all the monkeys with him will not survive.', 'veda-app-ai-draft', true),
('ramayana-5-11-47', 'en', 'Death brings many evils; one who lives finds good fortune. So I will hold on to life, for the living are sure to meet again.', 'veda-app-ai-draft', true),
('ramayana-5-11-48', 'en', 'Bearing in his mind many such sorrows again and again, the elephant among monkeys could not find the end of his grief.', 'veda-app-ai-draft', true),
('ramayana-5-11-49', 'en', 'Or I will kill the mighty ten-necked Ravana. Even if Sita is taken, she will be avenged.', 'veda-app-ai-draft', true),
('ramayana-5-11-50', 'en', 'Or I will lift him up and carry him over the ocean and offer him to Rama, as an animal is offered to Pashupati.', 'veda-app-ai-draft', true),
('ramayana-5-11-51', 'en', 'Thus troubled, not finding Sita, his mind consumed by thought and grief, the monkey reflected.', 'veda-app-ai-draft', true),
('ramayana-5-11-52', 'en', 'Until I see Rama''s famous wife Sita, I will search this city of Lanka again and again.', 'veda-app-ai-draft', true),
('ramayana-5-11-53', 'en', 'Even if I bring Rama here on Sampati''s word, if Rama does not see his wife, he may burn up all the monkeys.', 'veda-app-ai-draft', true),
('ramayana-5-11-54', 'en', 'I will stay right here, eating little, senses controlled. All those men and monkeys must not perish because of me.', 'veda-app-ai-draft', true),
('ramayana-5-11-55', 'en', 'And this great Ashoka grove with its great trees: I will go there, for I have not searched it.', 'veda-app-ai-draft', true),
('ramayana-5-11-56', 'en', 'Bowing to the Vasus, Rudras, Adityas, the Ashvins and the Maruts, I will go, increasing the rakshasas'' grief.', 'veda-app-ai-draft', true),
('ramayana-5-11-57', 'en', 'Defeating the rakshasas, I will give the queen, delight of the Ikshvaku line, back to Rama, as success is given to an ascetic.', 'veda-app-ai-draft', true),
('ramayana-5-11-58', 'en', 'After thinking for a moment, his senses knotted with worry, mighty-armed Hanuman, son of the Wind, rose up.', 'veda-app-ai-draft', true),
('ramayana-5-11-59', 'en', 'Salutations to Rama with Lakshmana, and to the queen, Janaka''s daughter. Salutations to Rudra, Indra, Yama and the Wind; salutations to the Moon, the Sun and the hosts of Maruts.', 'veda-app-ai-draft', true),
('ramayana-5-11-60', 'en', 'Having bowed to them and to Sugriva, the son of the Wind looked in every direction and turned towards the Ashoka grove.', 'veda-app-ai-draft', true),
('ramayana-5-11-61', 'en', 'Having first gone in his mind to the lovely Ashoka grove, the monkey son of the Wind thought about what came next.', 'veda-app-ai-draft', true),
('ramayana-5-11-62', 'en', 'Surely the Ashoka grove, thick with trees and carefully kept, will be full of rakshasas. I must think about it.', 'veda-app-ai-draft', true),
('ramayana-5-11-63', 'en', 'Guards must be posted there to protect the trees. Even the blessed Wind, soul of all, does not blow too hard there.', 'veda-app-ai-draft', true),
('ramayana-5-11-64', 'en', 'I have made myself small for Rama''s sake and against Ravana. May the gods and the hosts of sages grant me success here.', 'veda-app-ai-draft', true),
('ramayana-5-11-65', 'en', 'May blessed self-born Brahma and the gods grant me success, and Fire, the Wind, and Indra who holds the thunderbolt,', 'veda-app-ai-draft', true),
('ramayana-5-11-66', 'en', 'and Varuna with his noose, the Moon and the Sun, the great Ashvins and all the Maruts.', 'veda-app-ai-draft', true),
('ramayana-5-11-67', 'en', 'May all beings and the lord of beings, and any others unseen who move along my path, grant me success.', 'veda-app-ai-draft', true),
('ramayana-5-11-68', 'en', 'When will I see that noble lady''s face, with its fine nose, white teeth and pure smile, eyes like lotus petals, lovely as the clear moon?', 'veda-app-ai-draft', true),
('ramayana-5-11-69', 'en', 'How can that poor, helpless lady, overpowered by force by that petty, sinful, cruel one dressed in a dreadful fine disguise, come into my sight today?', 'veda-app-ai-draft', true),
('ramayana-5-12-1', 'en', 'After thinking for a moment and reaching her in his mind, the radiant one leapt onto the wall of that house.', 'veda-app-ai-draft', true),
('ramayana-5-12-2', 'en', 'Standing on the wall, every limb thrilled, the great monkey saw many kinds of trees in flower at the start of spring.', 'veda-app-ai-draft', true),
('ramayana-5-12-3', 'en', 'Sal, ashoka, lovely champaka in full bloom, uddalaka, nagavriksha, mango and kapimukha trees.', 'veda-app-ai-draft', true),
('ramayana-5-12-4', 'en', 'Then he leapt like an arrow loosed from a bowstring into the garden, thick with mango trees and covered by hundreds of creepers.', 'veda-app-ai-draft', true),
('ramayana-5-12-5', 'en', 'Entering that colourful garden, echoing with birds, surrounded on all sides by silver and golden trees,', 'veda-app-ai-draft', true),
('ramayana-5-12-6', 'en', 'Hanuman saw it, bright as the rising sun, colourful with birds and herds of deer, a lovely wood.', 'veda-app-ai-draft', true),
('ramayana-5-12-7', 'en', 'It was full of trees of many kinds in flower and fruit, always frequented by excited cuckoos and bees.', 'veda-app-ai-draft', true),
('ramayana-5-12-8', 'en', 'At a time when people were happy, full of animals and birds, echoing with excited peacocks and many flocks of birds,', 'veda-app-ai-draft', true),
('ramayana-5-12-9', 'en', 'searching for the lovely, blameless princess, the monkey woke the happily sleeping birds.', 'veda-app-ai-draft', true),
('ramayana-5-12-10', 'en', 'Struck by the wings of the flocks flying up, the sal trees let fall showers of many-coloured flowers.', 'veda-app-ai-draft', true),
('ramayana-5-12-11', 'en', 'Covered with flowers, Hanuman, son of the Wind, shone in the middle of the Ashoka grove like a mountain made of flowers.', 'veda-app-ai-draft', true),
('ramayana-5-12-12', 'en', 'Seeing the monkey rushing in every direction among the trees, all beings thought it was spring itself.', 'veda-app-ai-draft', true),
('ramayana-5-12-13', 'en', 'Strewn with flowers of every kind fallen from the trees, the earth there shone like an adorned young woman.', 'veda-app-ai-draft', true),
('ramayana-5-12-14', 'en', 'Shaken hard by the swift monkey, those trees let fall colourful flowers.', 'veda-app-ai-draft', true),
('ramayana-5-12-15', 'en', 'Their tops stripped of leaves, their flowers and fruit fallen, the trees were like gamblers who had lost and thrown down their clothes and jewels.', 'veda-app-ai-draft', true),
('ramayana-5-12-16', 'en', 'Shaken by swift Hanuman, those fine flowering trees quickly dropped their flowers, leaves and fruit.', 'veda-app-ai-draft', true),
('ramayana-5-12-17', 'en', 'Abandoned by the flocks of birds, left with only their trunks, all the trees stood bare as if shaken by the wind.', 'veda-app-ai-draft', true),
('ramayana-5-12-18', 'en', 'Like a young woman with dishevelled hair and smudged make-up,', 'veda-app-ai-draft', true),
('ramayana-5-12-19', 'en', 'so the Ashoka grove, trampled by tail, hands and feet, its fine trees broken, looked dishevelled.', 'veda-app-ai-draft', true),
('ramayana-5-12-20', 'en', 'The monkey forcefully tore through the strands of great creepers, as the monsoon wind scatters masses of cloud on the Vindhya.', 'veda-app-ai-draft', true),
('ramayana-5-12-21', 'en', 'Moving about there, the monkey saw lovely grounds of gems, silver and gold.', 'veda-app-ai-draft', true),
('ramayana-5-12-22', 'en', 'He saw pools of many shapes, full of fine water, with costly jewelled stairs here and there,', 'veda-app-ai-draft', true),
('ramayana-5-12-23', 'en', 'with sands of pearl and coral, crystal floors, and colourful golden trees growing on their banks,', 'veda-app-ai-draft', true),
('ramayana-5-12-24', 'en', 'with groves of blooming lotuses and lilies, calling ruddy geese, the cries of gallinules, and the calls of swans and cranes,', 'veda-app-ai-draft', true),
('ramayana-5-12-25', 'en', 'fed on all sides by long, tree-lined streams of auspicious water like nectar,', 'veda-app-ai-draft', true),
('ramayana-5-12-26', 'en', 'spread with hundreds of creepers, covered with santanaka trees, with thickets of many bushes and oleanders between.', 'veda-app-ai-draft', true),
('ramayana-5-12-27', 'en', 'Then he saw a mountain like a cloud, with tall peaks, many-coloured crests, surrounded on all sides by summits,', 'veda-app-ai-draft', true),
('ramayana-5-12-28', 'en', 'spread with stone houses and covered with many trees: the tiger among monkeys saw the loveliest mountain in the world.', 'veda-app-ai-draft', true),
('ramayana-5-12-29', 'en', 'The monkey saw a river falling from that mountain, like a beloved woman who has sprung from her lover''s lap and fallen.', 'veda-app-ai-draft', true),
('ramayana-5-12-30', 'en', 'Graced by trees whose tips dipped into the water, it was like an angry young woman being held back by dear relatives.', 'veda-app-ai-draft', true),
('ramayana-5-12-31', 'en', 'The great monkey saw its water turning back again, like a beloved returning, calmed, to her lover.', 'veda-app-ai-draft', true),
('ramayana-5-12-32', 'en', 'Not far from it, Hanuman, son of the Wind, saw lotus pools full of flocks of birds.', 'veda-app-ai-draft', true),
('ramayana-5-12-33', 'en', 'And a man-made pond full of cool water, with fine jewelled steps, adorned with pearl sand,', 'veda-app-ai-draft', true),
('ramayana-5-12-34', 'en', 'colourful with herds of animals, a lovely wood, adorned all around with great palaces built by Vishvakarma and with artificial groves.', 'veda-app-ai-draft', true),
('ramayana-5-12-35', 'en', 'All the trees there in flower and fruit had parasols and platforms, all with golden terraces.', 'veda-app-ai-draft', true),
('ramayana-5-12-36', 'en', 'The great monkey saw a single golden shimshapa tree, covered with many spreading creepers and leaves.', 'veda-app-ai-draft', true),
('ramayana-5-12-37', 'en', 'He saw patches of ground, hollows and springs, and other golden trees like fire.', 'veda-app-ai-draft', true),
('ramayana-5-12-38', 'en', 'With the radiance of those trees, like that of Meru, the heroic monkey thought he himself had turned to gold.', 'veda-app-ai-draft', true),
('ramayana-5-12-39', 'en', 'Seeing it fanned by the wind, with its golden trees and the jingle of hundreds of little bells, he was filled with wonder.', 'veda-app-ai-draft', true),
('ramayana-5-12-40', 'en', 'The swift one climbed that lovely shimshapa tree, its top in full flower, with fresh shoots, covered in leaves.', 'veda-app-ai-draft', true),
('ramayana-5-12-41', 'en', 'From here I will see Vaidehi, longing to see Rama, wandering here and there by chance, stricken with grief.', 'veda-app-ai-draft', true),
('ramayana-5-12-42', 'en', 'This Ashoka grove of the wicked one is very lovely, adorned with champaka, sandal and bakula trees.', 'veda-app-ai-draft', true),
('ramayana-5-12-43', 'en', 'And this lotus pond is lovely, frequented by flocks of birds. Janaki, Rama''s queen, will surely come to it.', 'veda-app-ai-draft', true),
('ramayana-5-12-44', 'en', 'Janaki, Rama''s queen, always dear to Rama, skilled at roaming the forest, will surely come.', 'veda-app-ai-draft', true),
('ramayana-5-12-45', 'en', 'Or the fawn-eyed lady, who knows the forest well, worn down by thoughts of Rama, will come here to the wood.', 'veda-app-ai-draft', true),
('ramayana-5-12-46', 'en', 'Burning with grief for Rama, the lovely-eyed queen who loved forest life will surely come, for she is a forest-dweller.', 'veda-app-ai-draft', true),
('ramayana-5-12-47', 'en', 'Surely Rama''s beloved wife, Janaka''s faithful daughter, always longed for the forest-dwellers'' life.', 'veda-app-ai-draft', true),
('ramayana-5-12-48', 'en', 'Mindful of the hour of evening prayer, the lovely young Janaki will surely come to this river of pure water for her evening rites.', 'veda-app-ai-draft', true),
('ramayana-5-12-49', 'en', 'This lovely Ashoka grove is worthy of her, the lovely wife of Rama, king among rulers.', 'veda-app-ai-draft', true),
('ramayana-5-12-50', 'en', 'If the queen with a face like the moon is alive, she will surely come to this river of pure water.', 'veda-app-ai-draft', true),
('ramayana-5-12-51', 'en', 'Thinking this, great-souled Hanuman waited for the wife of the lord of men, hidden in the dense, flowering leaves, watching everything.', 'veda-app-ai-draft', true),
('ramayana-5-13-1', 'en', 'Staying there, looking around and searching for Maithili, he gazed over the whole ground.', 'veda-app-ai-draft', true),
('ramayana-5-13-2', 'en', 'It was graced with santanaka creepers and trees, full of divine scents and flavours, adorned all around.', 'veda-app-ai-draft', true),
('ramayana-5-13-3', 'en', 'Like Nandana garden, full of animals and birds, crowded with mansions and palaces, ringing with cuckoos,', 'veda-app-ai-draft', true),
('ramayana-5-13-4', 'en', 'graced with pools of golden lilies and lotuses, with many seats and rugs and many underground chambers,', 'veda-app-ai-draft', true),
('ramayana-5-13-5', 'en', 'with lovely trees bearing flowers and fruit in every season, and shining like sunrise with the splendour of the flowering ashokas.', 'veda-app-ai-draft', true),
('ramayana-5-13-6', 'en', 'The son of the Wind gazed at it as if ablaze, its branches seemingly stripped again and again by birds, hundreds flying off like colourful flower crests.', 'veda-app-ai-draft', true),
('ramayana-5-13-7', 'en', 'The ashokas, which destroy sorrow, were covered with flowers from root to top, so laden they seemed to touch the earth.', 'veda-app-ai-draft', true),
('ramayana-5-13-8', 'en', 'With flowering karnikaras and kimshukas in full bloom, the place seemed ablaze everywhere with their glow.', 'veda-app-ai-draft', true),
('ramayana-5-13-9', 'en', 'Punnagas, saptaparnas, champakas and uddalakas, with spreading roots, shone in full flower.', 'veda-app-ai-draft', true),
('ramayana-5-13-10', 'en', 'There were thousands of ashokas, some like gold, some like flame, some like dark collyrium.', 'veda-app-ai-draft', true),
('ramayana-5-13-11', 'en', 'It was like Nandana, with many gardens, colourful like Chaitraratha, surpassing them, unimaginable, divine, lovely and full of splendour.', 'veda-app-ai-draft', true),
('ramayana-5-13-12', 'en', 'It was like a second sky with flowers for stars, colourful with hundreds of flower-jewels like a fifth ocean.', 'veda-app-ai-draft', true),
('ramayana-5-13-13', 'en', 'The lovely garden was full of honey-scented trees with flowers of every season, and many sounds of animals and birds.', 'veda-app-ai-draft', true),
('ramayana-5-13-14', 'en', 'Carrying many fragrances, holy-scented and charming, it was rich in scent like a second Gandhamadana mountain.', 'veda-app-ai-draft', true),
('ramayana-5-13-15', 'en', 'In that Ashoka grove, the best of monkeys saw not far away a lofty temple-palace.', 'veda-app-ai-draft', true),
('ramayana-5-13-16', 'en', 'It stood in the middle on a thousand pillars, white as Kailasa, with coral stairs and platforms of refined gold.', 'veda-app-ai-draft', true),
('ramayana-5-13-17', 'en', 'It seemed to dazzle the eyes and blaze with splendour, spotless, and so tall it seemed to scrape the sky.', 'veda-app-ai-draft', true),
('ramayana-5-13-18', 'en', 'Then he saw a woman in soiled clothes, surrounded by rakshasis, thin from fasting, wretched, sighing again and again, like a pure sliver of moon at the start of the bright fortnight.', 'veda-app-ai-draft', true),
('ramayana-5-13-19', 'en', 'Her beauty, barely visible, still shone, like a flame of fire wrapped in smoke.', 'veda-app-ai-draft', true),
('ramayana-5-13-20', 'en', 'She wore a single soiled yellow garment, fine but worn, stained with mud and without ornaments, like a lotus pool without lotuses.', 'veda-app-ai-draft', true),
('ramayana-5-13-21', 'en', 'Ashamed, burning with sorrow, faded and suffering, she was like Rohini afflicted by the planet Mars.', 'veda-app-ai-draft', true),
('ramayana-5-13-22', 'en', 'Her face full of tears, wretched, thin from not eating, lost in grief and brooding, always sunk in sorrow,', 'veda-app-ai-draft', true),
('ramayana-5-13-23', 'en', 'not seeing those she loved, seeing only rakshasis, like a doe separated from her herd and surrounded by dogs.', 'veda-app-ai-draft', true),
('ramayana-5-13-24', 'en', 'with a single braid like a black serpent falling to her hips, worthy of happiness but burning with sorrow, never having known misfortune before.', 'veda-app-ai-draft', true),
('ramayana-5-13-25', 'en', 'Seeing that wide-eyed woman, very soiled and thin, he reasoned from the clues that she was Sita.', 'veda-app-ai-draft', true),
('ramayana-5-13-26', 'en', 'This woman looks just as the woman did whom we saw being carried off by that shape-changing rakshasa.', 'veda-app-ai-draft', true),
('ramayana-5-13-27', 'en', 'With a face like the full moon, fine brows and graceful form, the queen lit up every direction with her radiance.', 'veda-app-ai-draft', true),
('ramayana-5-13-28', 'en', 'Sita, with dark hair, lips red as bimba fruit, slender waist and lotus-petal eyes, like Rati, wife of the god of love,', 'veda-app-ai-draft', true),
('ramayana-5-13-29', 'en', 'dear to the whole world, bright as the full moon, seated on the ground like a disciplined ascetic,', 'veda-app-ai-draft', true),
('ramayana-5-13-30', 'en', 'sighing often, timid like the wife of a serpent king, not shining because of the great net of grief spread over her.', 'veda-app-ai-draft', true),
('ramayana-5-13-31', 'en', 'like a flame clouded with smoke, like a memory in doubt, like fortune fallen,', 'veda-app-ai-draft', true),
('ramayana-5-13-32', 'en', 'like faith broken, hope dashed, success beset by obstacles, understanding clouded,', 'veda-app-ai-draft', true),
('ramayana-5-13-33', 'en', 'like fame fallen through false slander, pained by being kept from Rama, worn by the rakshasa''s abduction,', 'veda-app-ai-draft', true),
('ramayana-5-13-34', 'en', 'the helpless, fawn-eyed lady looking here and there, with tear-filled eyes and dark lashes, her face clouded, sighing again and again,', 'veda-app-ai-draft', true),
('ramayana-5-13-35', 'en', 'covered in dirt and mud, wretched, worthy of ornaments but unadorned, like the light of the moon covered by black clouds.', 'veda-app-ai-draft', true),
('ramayana-5-13-36', 'en', 'Looking at Sita again and again, his mind wavered, like knowledge grown weak through lack of practice.', 'veda-app-ai-draft', true),
('ramayana-5-13-37', 'en', 'With difficulty Hanuman recognised the unadorned Sita, like speech without refinement that takes on another meaning.', 'veda-app-ai-draft', true),
('ramayana-5-13-38', 'en', 'Looking at the wide-eyed, blameless princess, he reasoned from the evidence that she was Sita.', 'veda-app-ai-draft', true),
('ramayana-5-13-39', 'en', 'He noticed on her limbs the ornaments that Rama had described as being on Vaidehi''s body.', 'veda-app-ai-draft', true),
('ramayana-5-13-40', 'en', 'The well-made earrings and the dog-tooth ear ornaments set in place, and the bracelets on her hands inlaid with gems and coral,', 'veda-app-ai-draft', true),
('ramayana-5-13-41', 'en', 'darkened from long wear but still in shape: I think these are the very ones Rama described.', 'veda-app-ai-draft', true),
('ramayana-5-13-42', 'en', 'The ones that are missing I do not see here; the ones she still has are surely these.', 'veda-app-ai-draft', true),
('ramayana-5-13-43', 'en', 'The lovely yellow cloth like a strip of gold, her upper garment caught on a tree, was what the monkeys saw then.', 'veda-app-ai-draft', true),
('ramayana-5-13-44', 'en', 'And the fine, large, jingling ornaments seen on the ground were thrown down by her.', 'veda-app-ai-draft', true),
('ramayana-5-13-45', 'en', 'This garment, worn so long, is very worn, yet surely it is the same colour and as fine as the other.', 'veda-app-ai-draft', true),
('ramayana-5-13-46', 'en', 'This golden-limbed lady is Rama''s beloved queen. Though lost to him, she has never been lost from his mind.', 'veda-app-ai-draft', true),
('ramayana-5-13-47', 'en', 'She is the one for whom Rama suffers in four ways: through compassion, kindness, grief and love.', 'veda-app-ai-draft', true),
('ramayana-5-13-48', 'en', 'Compassion because a woman is lost, kindness because she depended on him, grief because his wife is lost, and love because she is his beloved.', 'veda-app-ai-draft', true),
('ramayana-5-13-49', 'en', 'As the queen''s form is perfect in every limb, so is Rama''s; the dark-eyed lady is his equal.', 'veda-app-ai-draft', true),
('ramayana-5-13-50', 'en', 'Her mind is fixed on him and his on her. That is why she and that righteous one live even a moment.', 'veda-app-ai-draft', true),
('ramayana-5-13-51', 'en', 'Rama does something very hard: the mighty-armed one lives even a moment without this splendid Sita.', 'veda-app-ai-draft', true),
('ramayana-5-13-52', 'en', 'Seeing Sita thus, the son of the Wind was overjoyed; in his mind he went to Rama and praised that lord.', 'veda-app-ai-draft', true),
('ramayana-5-14-1', 'en', 'Having praised Sita, worthy of praise, and Rama, delightful in his virtues, the best of monkeys fell to thinking again.', 'veda-app-ai-draft', true),
('ramayana-5-14-2', 'en', 'After a moment''s thought, his eyes filled with tears, radiant Hanuman lamented for Sita.', 'veda-app-ai-draft', true),
('ramayana-5-14-3', 'en', 'If even Sita, honoured by Lakshmana who honours his elders, dear to her elders, suffers so, then time is hard to overcome.', 'veda-app-ai-draft', true),
('ramayana-5-14-4', 'en', 'Knowing the resolve of Rama and wise Lakshmana, the queen is not too shaken, like the Ganga when the rains come.', 'veda-app-ai-draft', true),
('ramayana-5-14-5', 'en', 'Equal in character, age and conduct, equal in family and marks, Rama is worthy of Vaidehi, and the dark-eyed lady of him.', 'veda-app-ai-draft', true),
('ramayana-5-14-6', 'en', 'Seeing her, bright as new gold, like Lakshmi beloved of the world, he went to Rama in his mind and said:', 'veda-app-ai-draft', true),
('ramayana-5-14-7', 'en', 'For this wide-eyed lady''s sake mighty Vali was killed, and Kabandha, equal to Ravana in strength, was struck down.', 'veda-app-ai-draft', true),
('ramayana-5-14-8', 'en', 'And the rakshasa Viradha of fearsome strength was killed in battle in the forest by Rama''s valour, as Shambara was by great Indra.', 'veda-app-ai-draft', true),
('ramayana-5-14-9', 'en', 'Fourteen thousand rakshasas of fearsome deeds were killed in Janasthana by arrows like flames.', 'veda-app-ai-draft', true),
('ramayana-5-14-10', 'en', 'Khara was killed in battle, Trishiras struck down, and mighty Dushana too, by wise Rama.', 'veda-app-ai-draft', true),
('ramayana-5-14-11', 'en', 'For her sake Sugriva gained the monkey kingdom, hard to win, once guarded by Vali, and honoured by the world.', 'veda-app-ai-draft', true),
('ramayana-5-14-12', 'en', 'For this wide-eyed lady''s sake I crossed the glorious ocean, lord of rivers, and searched this city.', 'veda-app-ai-draft', true),
('ramayana-5-14-13', 'en', 'If Rama were to turn the sea-bound earth upside down, or even the whole world, for her sake, I think it would be right.', 'veda-app-ai-draft', true),
('ramayana-5-14-14', 'en', 'Kingship in the three worlds, or Sita, Janaka''s daughter? All the kingdoms of the three worlds would not equal a fraction of Sita.', 'veda-app-ai-draft', true),
('ramayana-5-14-15', 'en', 'This is Sita, daughter of the righteous, great King Janaka of Mithila, firm in her vow to her husband.', 'veda-app-ai-draft', true),
('ramayana-5-14-16', 'en', 'She rose from the earth when a field was furrowed by the plough, covered in the lovely dust of the field, like lotus pollen.', 'veda-app-ai-draft', true),
('ramayana-5-14-17', 'en', 'She is the famous eldest daughter-in-law of King Dasharatha, brave, noble, never retreating in battle.', 'veda-app-ai-draft', true),
('ramayana-5-14-18', 'en', 'This is the beloved wife of righteous, grateful, wise Rama, now in the power of rakshasis.', 'veda-app-ai-draft', true),
('ramayana-5-14-19', 'en', 'Driven by love for her husband, she left every pleasure and, without thinking of hardships, entered the lonely forest.', 'veda-app-ai-draft', true),
('ramayana-5-14-20', 'en', 'Content with fruit and roots, devoted to serving her husband, she found the highest joy in the forest as in a palace.', 'veda-app-ai-draft', true),
('ramayana-5-14-21', 'en', 'This golden-limbed lady, always smiling as she spoke, endures this torment though she never deserved misfortune.', 'veda-app-ai-draft', true),
('ramayana-5-14-22', 'en', 'Rama longs to see this virtuous lady, crushed by Ravana, as a thirsty man longs for a well.', 'veda-app-ai-draft', true),
('ramayana-5-14-23', 'en', 'Surely Rama will rejoice to get her back, like a king who lost his kingdom regaining the earth.', 'veda-app-ai-draft', true),
('ramayana-5-14-24', 'en', 'Deprived of pleasures and parted from her kin, she keeps her body alive, longing to be reunited with him.', 'veda-app-ai-draft', true),
('ramayana-5-14-25', 'en', 'She does not see the rakshasis, nor these flowering, fruiting trees. With her heart on one thing, she surely sees only Rama.', 'veda-app-ai-draft', true),
('ramayana-5-14-26', 'en', 'A husband is a woman''s finest ornament, finer than ornaments. Without him, she who deserves to shine does not shine.', 'veda-app-ai-draft', true),
('ramayana-5-14-27', 'en', 'Rama does something hard: parted from her, the lord keeps his body alive and does not sink under his sorrow.', 'veda-app-ai-draft', true),
('ramayana-5-14-28', 'en', 'Seeing her, with dark hair and eyes like a hundred-petalled lotus, worthy of happiness yet in sorrow, my heart aches too.', 'veda-app-ai-draft', true),
('ramayana-5-14-29', 'en', 'She who is patient as the earth, lotus-eyed, once protected by Rama and Lakshmana, is now guarded under a tree by hideous-eyed rakshasis.', 'veda-app-ai-draft', true),
('ramayana-5-14-30', 'en', 'Like a lotus struck by frost, her beauty gone, crushed by one misfortune after another, Janaka''s daughter has fallen into a pitiful state, like a chakravaki bird without her mate.', 'veda-app-ai-draft', true),
('ramayana-5-14-31', 'en', 'The ashoka trees, their branches bowed with flowers, cause her deep sorrow, and so does the moon, rising with its many thousand rays now that the cold has passed.', 'veda-app-ai-draft', true),
('ramayana-5-14-32', 'en', 'Weighing all this, his mind settled that this was Sita, the strong, swift bull among monkeys sat down, hidden in that tree.', 'veda-app-ai-draft', true),
('ramayana-5-15-1', 'en', 'Then the moon, white as a cluster of lilies and spotless itself, rose into the clear sky, like a swan on blue water.', 'veda-app-ai-draft', true),
('ramayana-5-15-2', 'en', 'As if helping him with its clear light, the moon with its cool rays served the son of the Wind.', 'veda-app-ai-draft', true),
('ramayana-5-15-3', 'en', 'Then he saw Sita, her face like the full moon, weighed down by burdens of grief like a boat sinking under loads in the water.', 'veda-app-ai-draft', true),
('ramayana-5-15-4', 'en', 'As Hanuman, son of the Wind, tried to see Vaidehi, he saw fearsome rakshasis near her.', 'veda-app-ai-draft', true),
('ramayana-5-15-5', 'en', 'One had one eye, another one ear, one wore her ears as a cloak, one had no ears, one had peg-like ears, one had a nose on top of her head.', 'veda-app-ai-draft', true),
('ramayana-5-15-6', 'en', 'One had a huge head, one a long thin neck, one had wispy hair, one was bald, one wore her hair like a blanket.', 'veda-app-ai-draft', true),
('ramayana-5-15-7', 'en', 'Some had long ears and foreheads, sagging bellies, long lips, lips on their chins, long faces and long knees.', 'veda-app-ai-draft', true),
('ramayana-5-15-8', 'en', 'Short, tall, hunchbacked, misshapen, dwarfish, frightful, with crooked garments, tawny eyes and distorted faces.', 'veda-app-ai-draft', true),
('ramayana-5-15-9', 'en', 'Deformed, tawny or black, angry and quarrelsome, they carried great iron spears, hammers and clubs.', 'veda-app-ai-draft', true),
('ramayana-5-15-10', 'en', 'Their faces were like boars, deer, tigers, buffaloes, goats and jackals; their feet like elephants, camels and horses; some had heads sunk in their bodies.', 'veda-app-ai-draft', true),
('ramayana-5-15-11', 'en', 'Some had one hand and one foot, some donkey or horse ears, cow ears, elephant ears or lion ears.', 'veda-app-ai-draft', true),
('ramayana-5-15-12', 'en', 'Some had no nose, some huge noses, crooked noses or no nostrils, noses like elephant trunks, or noses on their foreheads.', 'veda-app-ai-draft', true),
('ramayana-5-15-13', 'en', 'Elephant-footed, big-footed, cow-footed, with tufted feet, with huge heads and necks, huge breasts and bellies,', 'veda-app-ai-draft', true),
('ramayana-5-15-14', 'en', 'with huge mouths and eyes, long tongues and nails, goat faces, elephant faces, cow faces and pig faces,', 'veda-app-ai-draft', true),
('ramayana-5-15-15', 'en', 'horse, camel and donkey faces: fearsome rakshasis with spears and clubs in hand, angry and quarrelsome.', 'veda-app-ai-draft', true),
('ramayana-5-15-16', 'en', 'Frightful, grey-haired rakshasis with distorted faces, always drinking, always fond of meat and wine.', 'veda-app-ai-draft', true),
('ramayana-5-15-17', 'en', 'The best of monkeys saw them, their bodies smeared with flesh and blood, eating flesh and blood, a hair-raising sight.', 'veda-app-ai-draft', true),
('ramayana-5-15-18', 'en', 'They sat around a great-trunked tree, and beneath it was the blameless princess, the queen.', 'veda-app-ai-draft', true),
('ramayana-5-15-19', 'en', 'Glorious Hanuman made out Janaka''s daughter, without lustre, burning with grief, her hair matted with dirt,', 'veda-app-ai-draft', true),
('ramayana-5-15-20', 'en', 'like a star whose merit has run out, fallen to earth, rich in good character, in distress because she could not see her husband,', 'veda-app-ai-draft', true),
('ramayana-5-15-21', 'en', 'without fine ornaments but adorned with love for her husband, held captive by the rakshasa lord, cut off from her kin,', 'veda-app-ai-draft', true),
('ramayana-5-15-22', 'en', 'like a she-elephant separated from her herd, bound and cornered by a lion, like a sliver of moon covered by autumn clouds at the end of the rains,', 'veda-app-ai-draft', true),
('ramayana-5-15-23', 'en', 'her beauty worn, like a vina left untouched and untuned; Sita, devoted to her husband''s good, unfit to be in the rakshasas'' power,', 'veda-app-ai-draft', true),
('ramayana-5-15-24', 'en', 'plunged in an ocean of grief in the middle of the Ashoka grove, surrounded by them like Rohini by planets: Hanuman saw the queen, like a creeper without flowers.', 'veda-app-ai-draft', true),
('ramayana-5-15-25', 'en', 'Her body smeared with dirt yet adorned with its own beauty, she shone and did not shine, like a lotus stalk smeared with mud.', 'veda-app-ai-draft', true),
('ramayana-5-15-26', 'en', 'Hanuman saw the lovely fawn-eyed lady wrapped in a soiled, worn garment.', 'veda-app-ai-draft', true),
('ramayana-5-15-27', 'en', 'The queen, her face downcast but her spirit not cast down because of her husband''s power, protected by her own virtue, dark-eyed Sita,', 'veda-app-ai-draft', true),
('ramayana-5-15-28', 'en', 'Seeing Sita with eyes like a fawn''s, frightened like a young doe and looking all around,', 'veda-app-ai-draft', true),
('ramayana-5-15-29', 'en', 'as if burning the leafy trees with her sighs, a mass of sorrows, a rising wave of grief,', 'veda-app-ai-draft', true),
('ramayana-5-15-30', 'en', 'thin, with well-formed limbs, lovely even without ornaments,', 'veda-app-ai-draft', true),
('ramayana-5-15-31', 'en', 'seeing Maithili, the son of the Wind felt boundless joy. Seeing the lovely-eyed lady, Hanuman shed tears of joy and bowed to Rama.', 'veda-app-ai-draft', true),
('ramayana-5-15-32', 'en', 'Having bowed to Rama and Lakshmana, mighty Hanuman, thrilled at seeing Sita, stayed hidden.', 'veda-app-ai-draft', true),
('ramayana-5-16-1', 'en', 'As he gazed at the flowering forest and searched for Vaidehi, only a little of the night remained.', 'veda-app-ai-draft', true),
('ramayana-5-16-2', 'en', 'Before dawn he heard the chanting of brahma-rakshasas learned in the Vedas and their six limbs, performers of the finest sacrifices.', 'veda-app-ai-draft', true),
('ramayana-5-16-3', 'en', 'Then mighty ten-necked Ravana was woken by the pleasing sounds of auspicious music.', 'veda-app-ai-draft', true),
('ramayana-5-16-4', 'en', 'Waking at the proper time, the powerful rakshasa king, his garland and robe slipping, thought of Vaidehi.', 'veda-app-ai-draft', true),
('ramayana-5-16-5', 'en', 'Strongly bound to her by desire and inflamed by pride, the rakshasa could not hide his desire within himself.', 'veda-app-ai-draft', true),
('ramayana-5-16-6', 'en', 'Wearing all his ornaments and bearing unmatched splendour, he went to that grove full of trees of every flower and fruit,', 'veda-app-ai-draft', true),
('ramayana-5-16-7', 'en', 'surrounded by lotus ponds and adorned with many flowers, colourful with ever-excited birds, very wonderful,', 'veda-app-ai-draft', true),
('ramayana-5-16-8', 'en', 'full of carved animals pleasing to the eye. Looking at its paths with archways of gems and gold,', 'veda-app-ai-draft', true),
('ramayana-5-16-9', 'en', 'full of herds of animals and strewn with fallen fruit, he entered the Ashoka grove with its rows of trees.', 'veda-app-ai-draft', true),
('ramayana-5-16-10', 'en', 'About a hundred women followed him as he went, as the women of gods and gandharvas follow great Indra.', 'veda-app-ai-draft', true),
('ramayana-5-16-11', 'en', 'Some women carried golden lamps, others yak-tail fans, others palm-leaf fans.', 'veda-app-ai-draft', true),
('ramayana-5-16-12', 'en', 'Some carried water ahead in golden pitchers; others walked behind holding curved swords.', 'veda-app-ai-draft', true),
('ramayana-5-16-13', 'en', 'One lovely, capable woman held in her right hand a jewelled vessel full of drink.', 'veda-app-ai-draft', true),
('ramayana-5-16-14', 'en', 'Another walked behind holding a parasol like a royal swan, bright as the full moon, with a golden handle.', 'veda-app-ai-draft', true),
('ramayana-5-16-15', 'en', 'Ravana''s finest women, eyes heavy with sleep and wine, followed their heroic husband like streaks of lightning following a cloud.', 'veda-app-ai-draft', true),
('ramayana-5-16-16', 'en', 'Then the monkey, son of the Wind, heard the jingle of girdles and the tinkle of anklets of those fine women.', 'veda-app-ai-draft', true),
('ramayana-5-16-17', 'en', 'Hanuman saw him, of matchless deeds and unimaginable strength and might, arrive at the gateway.', 'veda-app-ai-draft', true),
('ramayana-5-16-18', 'en', 'He was lit up on all sides by many lamps soaked in scented oil, carried before him.', 'veda-app-ai-draft', true),
('ramayana-5-16-19', 'en', 'Filled with desire, arrogance and wine, his eyes slanting, red and long, he was like the god of love himself with his bow laid aside.', 'veda-app-ai-draft', true),
('ramayana-5-16-20', 'en', 'He playfully trailed his fine, spotless robe, white as churned nectar foam, which had come loose and caught on his armlet.', 'veda-app-ai-draft', true),
('ramayana-5-16-21', 'en', 'Hidden in the leafy branches, covered by dense leaves and flowers, Hanuman began to watch him as he came near.', 'veda-app-ai-draft', true),
('ramayana-5-16-22', 'en', 'Looking on, the elephant among monkeys saw Ravana''s fine women, rich in beauty and youth.', 'veda-app-ai-draft', true),
('ramayana-5-16-23', 'en', 'Surrounded by those lovely women, the famous king entered the pleasure grove, echoing with animals and birds.', 'veda-app-ai-draft', true),
('ramayana-5-16-24', 'en', 'Drunk, with colourful ornaments and peg-like ears, the mighty son of Vishravas, lord of the rakshasas, was seen by him.', 'veda-app-ai-draft', true),
('ramayana-5-16-25', 'en', 'The radiant great monkey saw the radiant one surrounded by fine women, like the moon by stars.', 'veda-app-ai-draft', true),
('ramayana-5-16-26', 'en', 'Thinking, This is mighty-armed Ravana, radiant Hanuman, son of the Wind, slipped down a little.', 'veda-app-ai-draft', true),
('ramayana-5-16-27', 'en', 'Though fierce in his own power, Hanuman was overwhelmed by Ravana''s splendour and stayed hidden, pressed into the leaves.', 'veda-app-ai-draft', true),
('ramayana-5-16-28', 'en', 'Ravana approached the dark-haired, dark-eyed lady, wanting to see her.', 'veda-app-ai-draft', true),
('ramayana-5-17-1', 'en', 'At that very time, the blameless princess saw him, rich in beauty and youth, adorned with the finest ornaments.', 'veda-app-ai-draft', true),
('ramayana-5-17-2', 'en', 'On seeing Ravana, lord of the rakshasas, lovely Vaidehi trembled like a plantain in a strong wind.', 'veda-app-ai-draft', true),
('ramayana-5-17-3', 'en', 'Covering herself with her knees and arms, the wide-eyed, lovely lady sat weeping.', 'veda-app-ai-draft', true),
('ramayana-5-17-4', 'en', 'Ten-necked Ravana saw Vaidehi guarded by the rakshasis, wretched and stricken, like a boat sinking in the sea.', 'veda-app-ai-draft', true),
('ramayana-5-17-5', 'en', 'She sat on the bare ground, strict in her vows, like a branch cut from a tree and fallen to earth, her body smeared with dirt, worthy of adornment yet unadorned.', 'veda-app-ai-draft', true),
('ramayana-5-17-6', 'en', 'She seemed to travel in her mind, in chariots drawn by the horses of her resolve, to the side of the lion among kings, wise Rama.', 'veda-app-ai-draft', true),
('ramayana-5-17-7', 'en', 'Wasting away, weeping alone, lost in grief and thought, seeing no end to her sorrow, the lovely lady was devoted only to Rama.', 'veda-app-ai-draft', true),
('ramayana-5-17-8', 'en', 'She was writhing like the wife of a serpent king under a spell, like Rohini darkened by the comet.', 'veda-app-ai-draft', true),
('ramayana-5-17-9', 'en', 'Born in a righteous family of good conduct and good custom, she seemed as if, after her rites of passage, she had been reborn into a bad family.', 'veda-app-ai-draft', true),
('ramayana-5-17-10', 'en', 'She was like great fame sunk low, like faith insulted, like wisdom worn away, like hope dashed,', 'veda-app-ai-draft', true),
('ramayana-5-17-11', 'en', 'like a future destroyed, a command defied, a direction ablaze at the end of time, worship stolen away,', 'veda-app-ai-draft', true),
('ramayana-5-17-12', 'en', 'like a lotus pool ravaged, an army whose heroes are slain, light dimmed by darkness, a river run dry,', 'veda-app-ai-draft', true),
('ramayana-5-17-13', 'en', 'like an altar defiled, a flame put out, a full-moon night with the moon swallowed by Rahu,', 'veda-app-ai-draft', true),
('ramayana-5-17-14', 'en', 'like a lotus pond in turmoil, its lotuses torn, its birds frightened, mauled by an elephant''s trunk,', 'veda-app-ai-draft', true),
('ramayana-5-17-15', 'en', 'pained by grief for her husband, like a dried-up river drained of water, without fine grooming like a night in the dark fortnight,', 'veda-app-ai-draft', true),
('ramayana-5-17-16', 'en', 'delicate, well-formed, fit for a jewelled chamber, like a lotus stalk just pulled out and wilting in the heat,', 'veda-app-ai-draft', true),
('ramayana-5-17-17', 'en', 'like the wife of an elephant king, seized and tied to a post, parted from the herd leader, sighing in deep distress,', 'veda-app-ai-draft', true),
('ramayana-5-17-18', 'en', 'lovely without effort with her single long braid, like the earth after the rains with a dark line of forest,', 'veda-app-ai-draft', true),
('ramayana-5-17-19', 'en', 'worn thin, wretched, eating little, rich in austerity, wasted by fasting, grief, brooding and fear,', 'veda-app-ai-draft', true),
('ramayana-5-17-20', 'en', 'praying in her distress, hands folded, as if to a god, in her heart, for Ravana''s defeat by the chief of the Raghus,', 'veda-app-ai-draft', true),
('ramayana-5-17-21', 'en', 'Ravana, to his own destruction, tried to tempt Maithili, the blameless lady, weeping and looking about with long, red-rimmed, fine-lashed eyes, utterly devoted to Rama.', 'veda-app-ai-draft', true),
('ramayana-5-18-1', 'en', 'Ravana spoke to that wretched, joyless, suffering lady, surrounded by guards, with sweet and suggestive words.', 'veda-app-ai-draft', true),
('ramayana-5-18-2', 'en', 'Seeing me, you hide yourself, wanting out of fear to make yourself invisible.', 'veda-app-ai-draft', true),
('ramayana-5-18-3', 'en', 'I desire you, wide-eyed one. Think well of me, my dear, perfect in every limb, delight of all the worlds.', 'veda-app-ai-draft', true),
('ramayana-5-18-4', 'en', 'There are no men here, nor shape-changing rakshasas. Let the fear you feel of me go, Sita.', 'veda-app-ai-draft', true),
('ramayana-5-18-5', 'en', 'For rakshasas, timid one, it is their own custom without doubt to go to other men''s wives or carry them off by force.', 'veda-app-ai-draft', true),
('ramayana-5-18-6', 'en', 'Even so, I will not touch you, Maithili, while you are unwilling. Let desire do what it will in my body.', 'veda-app-ai-draft', true),
('ramayana-5-18-7', 'en', 'Queen, there is no need for fear. Trust me, my dear, love me truly, and do not be so given to grief.', 'veda-app-ai-draft', true),
('ramayana-5-18-8', 'en', 'A single braid, sleeping on the ground, brooding, a soiled garment and needless fasting: these do not suit you.', 'veda-app-ai-draft', true),
('ramayana-5-18-9', 'en', 'Colourful garlands, sandal and aloe, many kinds of clothes and divine ornaments,', 'veda-app-ai-draft', true),
('ramayana-5-18-10', 'en', 'costly drinks, carriages and beds, song, dance and music: have them all by having me, Maithili.', 'veda-app-ai-draft', true),
('ramayana-5-18-11', 'en', 'You are a jewel among women. Do not be like this; adorn your limbs. Having me, how could you, so lovely, lack anything?', 'veda-app-ai-draft', true),
('ramayana-5-18-12', 'en', 'Your lovely youth is passing. What has gone never returns, like the swift current of a river.', 'veda-app-ai-draft', true),
('ramayana-5-18-13', 'en', 'I think the maker of forms, creator of the world, stopped after making you, for there is no other woman as beautiful as you, lovely one.', 'veda-app-ai-draft', true),
('ramayana-5-18-14', 'en', 'Coming upon you, Vaidehi, rich in beauty and youth, what man could pass you by, even Brahma himself?', 'veda-app-ai-draft', true),
('ramayana-5-18-15', 'en', 'Whatever part of you I look at, moon-faced one, there my eye stays fixed.', 'veda-app-ai-draft', true),
('ramayana-5-18-16', 'en', 'Be my wife, Maithili; give up this folly. Be my chief queen among my many fine women.', 'veda-app-ai-draft', true),
('ramayana-5-18-17', 'en', 'All the treasures I have seized from the worlds, timid one, all of them, this kingdom and I myself, are yours.', 'veda-app-ai-draft', true),
('ramayana-5-18-18', 'en', 'Having conquered the whole earth with its many cities, I will give it to Janaka for your sake, lovely one.', 'veda-app-ai-draft', true),
('ramayana-5-18-19', 'en', 'I see no one in this world who could match me in strength. See my great might, unrivalled in battle.', 'veda-app-ai-draft', true),
('ramayana-5-18-20', 'en', 'Again and again in battle I have broken gods and asuras, their banners crushed; they cannot stand against me.', 'veda-app-ai-draft', true),
('ramayana-5-18-21', 'en', 'Accept me. Let the finest grooming be done for you today, and let bright ornaments be placed on your body. I would love to see you adorned.', 'veda-app-ai-draft', true),
('ramayana-5-18-22', 'en', 'Adorned, lovely-faced one, enjoy pleasures as you wish, drink, play, and give away land or wealth as you please.', 'veda-app-ai-draft', true),
('ramayana-5-18-23', 'en', 'Be at ease with me, command me boldly, and let your relatives too enjoy themselves through my power while you enjoy yourself.', 'veda-app-ai-draft', true),
('ramayana-5-18-24', 'en', 'See my wealth, my splendour and my fame, good lady. What will you do with Rama, who wears bark clothes?', 'veda-app-ai-draft', true),
('ramayana-5-18-25', 'en', 'Rama has given up victory, lost his fortune, roams the forest, keeps vows and sleeps on the bare ground. I doubt whether he is even alive.', 'veda-app-ai-draft', true),
('ramayana-5-18-26', 'en', 'Rama will never even get to see you, Vaidehi, any more than moonlight covered by dark clouds with cranes in front.', 'veda-app-ai-draft', true),
('ramayana-5-18-27', 'en', 'Rama cannot take you from my hands, just as Hiranyakashipu could not take back the glory in Indra''s hands.', 'veda-app-ai-draft', true),
('ramayana-5-18-28', 'en', 'Lovely-smiling, lovely-toothed, lovely-eyed, graceful one, you steal my heart, timid one, as Garuda steals a serpent.', 'veda-app-ai-draft', true),
('ramayana-5-18-29', 'en', 'Seeing you, slender and unadorned, in your worn silk, I find no pleasure in my own wives.', 'veda-app-ai-draft', true),
('ramayana-5-18-30', 'en', 'Be the mistress of all the women in my inner palace, all endowed with every quality, Janaki.', 'veda-app-ai-draft', true),
('ramayana-5-18-31', 'en', 'My women, dark-haired one, the finest in the three worlds, will wait on you as apsarases wait on Lakshmi.', 'veda-app-ai-draft', true),
('ramayana-5-18-32', 'en', 'The jewels and wealth of Kubera, lovely-browed one, and the worlds and me: enjoy them as you please.', 'veda-app-ai-draft', true),
('ramayana-5-18-33', 'en', 'Rama is not my equal in austerity, strength, valour, wealth, splendour or fame, queen.', 'veda-app-ai-draft', true),
('ramayana-5-18-34', 'en', 'Drink, roam, play, enjoy pleasures. I give you heaps of wealth and the earth. Delight in me as you please, lovely one, and let your relatives come and delight in you.', 'veda-app-ai-draft', true),
('ramayana-5-18-35', 'en', 'Adorned with spotless golden necklaces, roam with me, timid one, the seaside woods full of flowering trees and bees.', 'veda-app-ai-draft', true),
('ramayana-5-19-1', 'en', 'Hearing the fierce rakshasa''s words, Sita, distressed, answered softly in a weak and sad voice.', 'veda-app-ai-draft', true),
('ramayana-5-19-2', 'en', 'Pained and weeping, trembling and suffering, the lovely Sita, devoted to her husband, thought only of him.', 'veda-app-ai-draft', true),
('ramayana-5-19-3', 'en', 'Placing a blade of grass between them, the pure-smiling lady replied: Turn your mind away from me; set your heart on your own wives.', 'veda-app-ai-draft', true),
('ramayana-5-19-4', 'en', 'It is not fitting for you to want me, as it is not fitting for a sinner to hope for perfection. I, devoted to one husband, born into a great family and married into a holy one, will not do what is forbidden.', 'veda-app-ai-draft', true),
('ramayana-5-19-5', 'en', 'Having said this to Ravana, the famous Vaidehi turned her back on the rakshasa and spoke again.', 'veda-app-ai-draft', true),
('ramayana-5-19-6', 'en', 'I am not a fit wife for you, being the faithful wife of another. Look to dharma well, and keep to the good path.', 'veda-app-ai-draft', true),
('ramayana-5-19-7', 'en', 'As your wives are to be protected, so are others'' wives, night-roamer. Taking yourself as the measure, find delight in your own wives.', 'veda-app-ai-draft', true),
('ramayana-5-19-8', 'en', 'One who is not content with his own wives, who is fickle with restless senses and crooked of mind, is brought to ruin by other men''s wives.', 'veda-app-ai-draft', true),
('ramayana-5-19-9', 'en', 'Are there no good people here, or do you not follow the good? Your mind bent on falsehood, you ignore the sound advice of the wise.', 'veda-app-ai-draft', true),
('ramayana-5-19-10', 'en', 'When a king of undisciplined mind, devoted to wrongdoing, comes to rule, prosperous kingdoms and cities perish.', 'veda-app-ai-draft', true),
('ramayana-5-19-11', 'en', 'So Lanka, full of heaps of jewels, having you as its king, will soon perish through your offence alone.', 'veda-app-ai-draft', true),
('ramayana-5-19-12', 'en', 'When a short-sighted evil-doer is struck down by his own deeds, Ravana, all beings rejoice at his destruction.', 'veda-app-ai-draft', true),
('ramayana-5-19-13', 'en', 'So the people you have wronged will say of you, the evil-doer: How lucky that this fierce one has met with disaster!', 'veda-app-ai-draft', true),
('ramayana-5-19-14', 'en', 'I cannot be tempted by power or wealth. I am one with Rama, as light is one with the sun.', 'veda-app-ai-draft', true),
('ramayana-5-19-15', 'en', 'Having rested my head on the honoured arm of that lord of the world, how could I ever rest it on anyone else''s arm?', 'veda-app-ai-draft', true),
('ramayana-5-19-16', 'en', 'I am the fit wife of that lord of the earth alone, as knowledge belongs to a self-aware brahmin who has completed his vows.', 'veda-app-ai-draft', true),
('ramayana-5-19-17', 'en', 'Ravana, do the right thing: bring me, grieving, back to Rama, as a she-elephant is brought back to the lord of the herd in the forest.', 'veda-app-ai-draft', true),
('ramayana-5-19-18', 'en', 'If you wish to keep your position and avoid a terrible death, you should make that bull among men your friend.', 'veda-app-ai-draft', true),
('ramayana-5-19-19', 'en', 'A thunderbolt once thrown might spare you; Death might spare you for a long time; but Rama, lord of the world, once angered, will not spare one like you.', 'veda-app-ai-draft', true),
('ramayana-5-19-20', 'en', 'You will hear the great twang of Rama''s bow, like the roar of a thunderbolt hurled by Indra.', 'veda-app-ai-draft', true),
('ramayana-5-19-21', 'en', 'Soon here, arrows well-jointed like serpents with blazing mouths, marked with the names of Rama and Lakshmana, will fall.', 'veda-app-ai-draft', true),
('ramayana-5-19-22', 'en', 'Killing rakshasas all over this city, those heron-feathered arrows will fall so thick there will be no gap between them.', 'veda-app-ai-draft', true),
('ramayana-5-19-23', 'en', 'Rama, the great Garuda, will swiftly pluck out the great serpents, the rakshasa lords, as Garuda plucks out snakes.', 'veda-app-ai-draft', true),
('ramayana-5-19-24', 'en', 'My husband, tamer of foes, will soon take me from you, as Vishnu with three strides took the blazing fortune from the asuras.', 'veda-app-ai-draft', true),
('ramayana-5-19-25', 'en', 'When the rakshasa army was killed in Janasthana, the place of slaughter, you, too weak to fight, did this wicked thing.', 'veda-app-ai-draft', true),
('ramayana-5-19-26', 'en', 'You entered the empty hermitage of those two lions among men while the brothers were away, and carried me off, vilest one.', 'veda-app-ai-draft', true),
('ramayana-5-19-27', 'en', 'You could not stand in sight of Rama and Lakshmana once you caught their scent, as a dog cannot face two tigers.', 'veda-app-ai-draft', true),
('ramayana-5-19-28', 'en', 'In a fight with them your hold is unstable, like Vritra''s single arm against Indra''s two.', 'veda-app-ai-draft', true),
('ramayana-5-19-29', 'en', 'Soon my lord Rama, with Lakshmana, will take your life with his arrows, as the sun dries up a little water.', 'veda-app-ai-draft', true),
('ramayana-5-19-30', 'en', 'Whether you go to Kubera''s mountain, to your own home, or to the court of King Varuna, you will not escape the son of Dasharatha, no doubt, just as a great tree doomed by time cannot escape the thunderbolt.', 'veda-app-ai-draft', true),
('ramayana-5-20-1', 'en', 'Hearing Sita''s harsh words, the rakshasa lord replied with unkind words to the lovely Sita.', 'veda-app-ai-draft', true),
('ramayana-5-20-2', 'en', 'The more a man soothes women, the more he is in their power; the more he speaks kindly, the more he is scorned.', 'veda-app-ai-draft', true),
('ramayana-5-20-3', 'en', 'The desire I feel for you holds back my anger, as a good charioteer holds back horses running off the road.', 'veda-app-ai-draft', true),
('ramayana-5-20-4', 'en', 'Desire is perverse in people: towards whoever it is bound, pity and affection arise.', 'veda-app-ai-draft', true),
('ramayana-5-20-5', 'en', 'That is why I do not kill you, lovely-faced one, though you deserve death and contempt for loving one who wanders in a false ascetic''s life.', 'veda-app-ai-draft', true),
('ramayana-5-20-6', 'en', 'For every harsh word you speak to me, Maithili, a terrible death would be fitting for you.', 'veda-app-ai-draft', true),
('ramayana-5-20-7', 'en', 'Having said this to Vaidehi, Ravana, lord of the rakshasas, full of rage, said more to Sita.', 'veda-app-ai-draft', true),
('ramayana-5-20-8', 'en', 'I will wait two months, the limit I have set for you. Then you must come to my bed, lovely one.', 'veda-app-ai-draft', true),
('ramayana-5-20-9', 'en', 'If after two months you still do not want me as your husband, they will cut you up in my kitchen for my breakfast.', 'veda-app-ai-draft', true),
('ramayana-5-20-10', 'en', 'Seeing Janaki threatened by the rakshasa king, the wide-eyed daughters of the gods and gandharvas were dismayed.', 'veda-app-ai-draft', true),
('ramayana-5-20-11', 'en', 'Some with movements of their lips, others with their eyes and faces, comforted Sita, threatened by that rakshasa.', 'veda-app-ai-draft', true),
('ramayana-5-20-12', 'en', 'Comforted by them, Sita spoke words for her own good to Ravana, lord of the rakshasas, proud of his conduct and courage.', 'veda-app-ai-draft', true),
('ramayana-5-20-13', 'en', 'Surely there is no one among your people who cares for your welfare, to stop you from this shameful act.', 'veda-app-ai-draft', true),
('ramayana-5-20-14', 'en', 'Who in the three worlds but you would even in his mind desire me, wife of the righteous one, as Shachi is wife of Indra?', 'veda-app-ai-draft', true),
('ramayana-5-20-15', 'en', 'Vilest of rakshasas, where will you go to escape the sin of what you have said to the wife of Rama of boundless power?', 'veda-app-ai-draft', true),
('ramayana-5-20-16', 'en', 'As a proud elephant and a hare in the forest, so Rama is like the elephant and you, lowly one, like the hare.', 'veda-app-ai-draft', true),
('ramayana-5-20-17', 'en', 'You are not ashamed to insult the lord of the Ikshvakus here, yet you do not come within range of his eyes.', 'veda-app-ai-draft', true),
('ramayana-5-20-18', 'en', 'Why have your cruel, ugly, dark-tawny eyes not fallen to the ground for looking at me so ignobly?', 'veda-app-ai-draft', true),
('ramayana-5-20-19', 'en', 'How does your tongue not wither, sinner, as you speak to me, wife of that righteous one and daughter-in-law of Dasharatha?', 'veda-app-ai-draft', true),
('ramayana-5-20-20', 'en', 'Only because Rama has not commanded it, and to guard my austerity, I do not burn you to ashes with my power, ten-necked one, though you deserve it.', 'veda-app-ai-draft', true),
('ramayana-5-20-21', 'en', 'I could not have been carried off from wise Rama. Fate has surely arranged this for your destruction, no doubt.', 'veda-app-ai-draft', true),
('ramayana-5-20-22', 'en', 'You, a hero, brother of Kubera, with a mighty army, why did you lure Rama away and steal his wife?', 'veda-app-ai-draft', true),
('ramayana-5-20-23', 'en', 'Hearing Sita''s words, Ravana, lord of the rakshasas, rolled his cruel eyes and stared at Janaki.', 'veda-app-ai-draft', true),
('ramayana-5-20-24', 'en', 'Like a dark thundercloud, with mighty arms and neck, with a lion''s strength and gait, splendid, with blazing tongue and fierce eyes,', 'veda-app-ai-draft', true),
('ramayana-5-20-25', 'en', 'tall, his crown''s tip trembling, with colourful garlands and unguents, red garlands and robes, adorned with armlets of refined gold,', 'veda-app-ai-draft', true),
('ramayana-5-20-26', 'en', 'girded with a great dark sash, like Mandara wrapped by the serpent at the churning for nectar,', 'veda-app-ai-draft', true),
('ramayana-5-20-27', 'en', 'adorned with earrings bright as the rising sun, like a mountain with two ashoka trees in red leaf and flower,', 'veda-app-ai-draft', true),
('ramayana-5-20-28', 'en', 'Ravana, looking at Vaidehi with eyes red with rage, hissing like a serpent, said to Sita:', 'veda-app-ai-draft', true),
('ramayana-5-20-29', 'en', 'You who are devoted to a man without policy or wealth, I will destroy you today, as the sun destroys twilight with its power.', 'veda-app-ai-draft', true),
('ramayana-5-20-30', 'en', 'Having said this to Maithili, King Ravana, who makes his enemies wail, gave orders to all the fearsome rakshasis:', 'veda-app-ai-draft', true),
('ramayana-5-20-31', 'en', 'the one-eyed, the one-eared, the one with ears as a cloak, the cow-eared, the elephant-eared, the long-eared and the earless,', 'veda-app-ai-draft', true),
('ramayana-5-20-32', 'en', 'the elephant-footed, the horse-footed, the cow-footed, the tuft-footed, the one-eyed, the one-footed, the broad-footed and the footless,', 'veda-app-ai-draft', true),
('ramayana-5-20-33', 'en', 'the one with huge head and neck, the one with huge breasts and belly, the one with huge mouth and eyes, the long-tongued and the tongueless, the noseless, the lion-faced, the cow-faced and the pig-faced:', 'veda-app-ai-draft', true),
('ramayana-5-20-34', 'en', 'All of you rakshasis, come together and quickly see that Sita, Janaki, comes under my control.', 'veda-app-ai-draft', true),
('ramayana-5-20-35', 'en', 'Turn Vaidehi with harsh and gentle ways, with conciliation, gifts and division, and with the threat of punishment.', 'veda-app-ai-draft', true),
('ramayana-5-20-36', 'en', 'Having given these orders again and again, the rakshasa lord, filled with desire and anger, threatened Janaki.', 'veda-app-ai-draft', true),
('ramayana-5-20-37', 'en', 'Then the rakshasi Dhanyamalini quickly came up, embraced the ten-necked one and said:', 'veda-app-ai-draft', true),
('ramayana-5-20-38', 'en', 'Play with me, great king; what do you want with this Sita? One who desires an unwilling woman only torments his body; joy comes from desiring one who is willing.', 'veda-app-ai-draft', true),
('ramayana-5-20-39', 'en', 'Spoken to by the rakshasi and led away by her, the mighty one entered his palace, shining like the blazing sun.', 'veda-app-ai-draft', true),
('ramayana-5-20-40', 'en', 'The daughters of gods, gandharvas and nagas surrounded the ten-necked one and entered that fine house.', 'veda-app-ai-draft', true),
('ramayana-5-20-41', 'en', 'Having threatened trembling Maithili, steadfast and devoted to dharma, Ravana, deluded by desire, left Sita and entered his own shining palace.', 'veda-app-ai-draft', true),
('ramayana-5-21-1', 'en', 'Having spoken thus to Maithili and given orders to all the rakshasis, King Ravana, who makes his enemies wail, went out.', 'veda-app-ai-draft', true),
('ramayana-5-21-2', 'en', 'When the rakshasa lord had gone back to his inner palace, the fearsome rakshasis rushed at Sita.', 'veda-app-ai-draft', true),
('ramayana-5-21-3', 'en', 'Then, approaching Sita, the rakshasis, beside themselves with anger, spoke very harshly to Vaidehi.', 'veda-app-ai-draft', true),
('ramayana-5-21-4', 'en', 'Sita, do you not value being the wife of Ravana, the great and noble descendant of Pulastya, the ten-necked one?', 'veda-app-ai-draft', true),
('ramayana-5-21-5', 'en', 'Then a rakshasi named Ekajata, her eyes red with anger, addressed slender-waisted Sita.', 'veda-app-ai-draft', true),
('ramayana-5-21-6', 'en', 'Of the six Prajapatis, the fourth is Pulastya, famous as the mind-born son of Brahma.', 'veda-app-ai-draft', true),
('ramayana-5-21-7', 'en', 'Pulastya''s radiant mind-born son is the great sage named Vishravas, bright as a Prajapati.', 'veda-app-ai-draft', true),
('ramayana-5-21-8', 'en', 'His son, wide-eyed one, is Ravana, who makes his enemies wail. You ought to be the wife of that rakshasa lord. Why do you not agree to what I say, lovely one?', 'veda-app-ai-draft', true),
('ramayana-5-21-9', 'en', 'Then a rakshasi named Harijata, with eyes like a cat''s, rolling her eyes in anger, spoke.', 'veda-app-ai-draft', true),
('ramayana-5-21-10', 'en', 'You ought to be the wife of the rakshasa lord who conquered the thirty-three gods and their king.', 'veda-app-ai-draft', true),
('ramayana-5-21-11', 'en', 'Why will you not be the wife of that strong hero, proud of his might, never retreating in battle?', 'veda-app-ai-draft', true),
('ramayana-5-21-12', 'en', 'The mighty king Ravana will leave his beloved, honoured wife, the noble chief of them all, and come to you.', 'veda-app-ai-draft', true),
('ramayana-5-21-13', 'en', 'Ravana will leave his inner palace, rich with a thousand women and adorned with many jewels, and come to you.', 'veda-app-ai-draft', true),
('ramayana-5-21-14', 'en', 'He who has again and again defeated gods, nagas, gandharvas and danavas in battle has come to your side.', 'veda-app-ai-draft', true),
('ramayana-5-21-15', 'en', 'Why, vile one, do you not want to be the wife of the great Ravana, rich in everything, lord of the rakshasas?', 'veda-app-ai-draft', true),
('ramayana-5-21-16', 'en', 'He for fear of whom the sun does not scorch and the wind does not blow, long-eyed one, why do you not stay with him?', 'veda-app-ai-draft', true),
('ramayana-5-21-17', 'en', 'For fear of him the trees rain flowers, lovely-browed one, and the mountains and clouds give water when he wishes.', 'veda-app-ai-draft', true),
('ramayana-5-21-18', 'en', 'Why do you not make up your mind to be the wife of Ravana, king of rakshasas, king of kings, lovely one?', 'veda-app-ai-draft', true),
('ramayana-5-21-19', 'en', 'We have told you well and truly, queen. Take our advice, sweet-smiling one, or you will not live.', 'veda-app-ai-draft', true),
('ramayana-5-22-1', 'en', 'Then the ugly-faced rakshasis came up to Sita, and those harsh women said harsh, unpleasant things.', 'veda-app-ai-draft', true),
('ramayana-5-22-2', 'en', 'Why, Sita, delight of all beings, do you not agree to live in the inner palace with its costly beds?', 'veda-app-ai-draft', true),
('ramayana-5-22-3', 'en', 'Being a human woman, you value being a human man''s wife. Turn your mind from Rama; you will never be his again.', 'veda-app-ai-draft', true),
('ramayana-5-22-4', 'en', 'You, a human woman, want Rama, a human man, lovely one, who has lost his kingdom, failed in his aims, and is helpless.', 'veda-app-ai-draft', true),
('ramayana-5-22-5', 'en', 'Hearing the rakshasis, lotus-eyed Sita spoke, her eyes full of tears.', 'veda-app-ai-draft', true),
('ramayana-5-22-6', 'en', 'What you all say together, hated by the world, does not find a place in my mind; it is sinful.', 'veda-app-ai-draft', true),
('ramayana-5-22-7', 'en', 'A human woman cannot be a rakshasa''s wife. Eat me if you like, all of you; I will not do what you say. Poor or without a kingdom, my husband is my guide.', 'veda-app-ai-draft', true),
('ramayana-5-22-8', 'en', 'Hearing Sita, the rakshasis, mad with anger and urged on by Ravana, scolded her with harsh words.', 'veda-app-ai-draft', true),
('ramayana-5-22-9', 'en', 'Hidden silently in the shimshapa tree, the monkey Hanuman heard the rakshasis threatening Sita.', 'veda-app-ai-draft', true),
('ramayana-5-22-10', 'en', 'Coming at the trembling woman from all sides, enraged, they licked their burning, hanging lips.', 'veda-app-ai-draft', true),
('ramayana-5-22-11', 'en', 'In great anger they quickly seized axes and said: She does not deserve Ravana, lord of the rakshasas, as husband.', 'veda-app-ai-draft', true),
('ramayana-5-22-12', 'en', 'Threatened by the fearsome rakshasis, the lovely-faced lady wiped away her tears and went to the shimshapa tree.', 'veda-app-ai-draft', true),
('ramayana-5-22-13', 'en', 'Surrounded by rakshasis, wide-eyed Sita reached the shimshapa and stood there, flooded with grief.', 'veda-app-ai-draft', true),
('ramayana-5-22-14', 'en', 'The fearsome rakshasis scolded her all around, thin, sad-faced and in soiled clothes.', 'veda-app-ai-draft', true),
('ramayana-5-22-15', 'en', 'Then a fearsome rakshasi named Vinata, angry-looking, frightful, with a sunken belly, said:', 'veda-app-ai-draft', true),
('ramayana-5-22-16', 'en', 'Sita, you have shown enough love for your husband. Anything overdone, good lady, leads to disaster.', 'veda-app-ai-draft', true),
('ramayana-5-22-17', 'en', 'I am pleased with you, bless you; you have done your human duty. But follow my good advice too, Maithili.', 'veda-app-ai-draft', true),
('ramayana-5-22-18', 'en', 'Take Ravana as husband, lord of all rakshasas, valiant and handsome as Indra, lord of the gods.', 'veda-app-ai-draft', true),
('ramayana-5-22-19', 'en', 'Generous, open-handed and pleasant to all: leave the poor human Rama and turn to Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-22-20', 'en', 'With heavenly unguents and divine ornaments, Vaidehi, be from today the mistress of all the worlds, as Svaha is to Fire and Shachi to Indra.', 'veda-app-ai-draft', true),
('ramayana-5-22-21', 'en', 'What do you want with Rama, Vaidehi, poor and as good as dead?', 'veda-app-ai-draft', true),
('ramayana-5-22-22', 'en', 'If you will not do what I have told you, we will all eat you this very moment.', 'veda-app-ai-draft', true),
('ramayana-5-22-23', 'en', 'Another, named Vikata, angry, raised her fist and roared at Sita:', 'veda-app-ai-draft', true),
('ramayana-5-22-24', 'en', 'Foolish one, we have put up with many improper words from you out of pity and softness, Maithili, but you do not follow our timely advice.', 'veda-app-ai-draft', true),
('ramayana-5-22-25', 'en', 'You were brought across the ocean, unreachable by others, and you have entered Ravana''s dreadful inner palace, Maithili.', 'veda-app-ai-draft', true),
('ramayana-5-22-26', 'en', 'Locked in Ravana''s house and well guarded by us, not even Indra himself could save you.', 'veda-app-ai-draft', true),
('ramayana-5-22-27', 'en', 'Do what I say, Maithili; I speak for your good. Enough of shedding tears; give up this pointless grief.', 'veda-app-ai-draft', true),
('ramayana-5-22-28', 'en', 'Take on love and joy; give up this constant misery. Sita, enjoy yourself with the rakshasa king as you please.', 'veda-app-ai-draft', true),
('ramayana-5-22-29', 'en', 'You know, timid one, how fleeting a woman''s youth is. Take your pleasure before it passes.', 'veda-app-ai-draft', true),
('ramayana-5-22-30', 'en', 'Roam the lovely gardens and mountain groves with the rakshasa king, lovely-eyed one.', 'veda-app-ai-draft', true),
('ramayana-5-22-31', 'en', 'Seven thousand women will be at your command, lovely one. Take Ravana, lord of all rakshasas, as your husband.', 'veda-app-ai-draft', true),
('ramayana-5-22-32', 'en', 'Or I will tear out your heart and eat it, Maithili, if you do not do exactly what I have said.', 'veda-app-ai-draft', true),
('ramayana-5-22-33', 'en', 'Then a cruel-looking rakshasi named Chandodari, whirling a great spear, said:', 'veda-app-ai-draft', true),
('ramayana-5-22-34', 'en', 'Seeing this doe-eyed woman, trembling with fear, carried off by Ravana, a great craving arose in me.', 'veda-app-ai-draft', true),
('ramayana-5-22-35', 'en', 'I want to eat her liver, spleen, heart and entrails, and her head.', 'veda-app-ai-draft', true),
('ramayana-5-22-36', 'en', 'Then a rakshasi named Praghasa said: Let us strangle this cruel woman. Why sit here?', 'veda-app-ai-draft', true),
('ramayana-5-22-37', 'en', 'Then let the king be told the human woman has died. No doubt he will say: Eat her.', 'veda-app-ai-draft', true),
('ramayana-5-22-38', 'en', 'Then a rakshasi named Ajamukhi said: Cut her up and make equal portions for all.', 'veda-app-ai-draft', true),
('ramayana-5-22-39', 'en', 'Let us share her out among us all; I dislike quarrels. Let drink and many garlands be brought quickly.', 'veda-app-ai-draft', true),
('ramayana-5-22-40', 'en', 'Then a rakshasi named Shurpanakha said: What Ajamukhi has said pleases me.', 'veda-app-ai-draft', true),
('ramayana-5-22-41', 'en', 'Let wine, which destroys all sorrow, be brought quickly. Having human flesh, we will dance before Nikumbhila.', 'veda-app-ai-draft', true),
('ramayana-5-22-42', 'en', 'Threatened like this by the dreadful rakshasis, Sita, like a daughter of the gods, lost her composure and wept.', 'veda-app-ai-draft', true),
('ramayana-5-23-1', 'en', 'As the unkind rakshasis said so many harsh, cruel things, Janaka''s daughter wept.', 'veda-app-ai-draft', true),
('ramayana-5-23-2', 'en', 'Addressed this way by the rakshasis, high-minded Vaidehi, terrified, spoke in a voice choked with tears.', 'veda-app-ai-draft', true),
('ramayana-5-23-3', 'en', 'A human woman cannot be a rakshasa''s wife. Eat me if you like, all of you; I will not do what you say.', 'veda-app-ai-draft', true),
('ramayana-5-23-4', 'en', 'Sita, like a daughter of the gods, in the midst of the rakshasis, found no peace, pained and threatened by Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-23-5', 'en', 'Sita trembled all the more, as if shrinking into herself, like a doe separated from her herd in the forest, attacked by wolves.', 'veda-app-ai-draft', true),
('ramayana-5-23-6', 'en', 'Holding a great flowering branch of the ashoka, she thought of her husband, heartbroken with grief.', 'veda-app-ai-draft', true),
('ramayana-5-23-7', 'en', 'Bathing herself in streams of tears and thinking, she found no end to her sorrow.', 'veda-app-ai-draft', true),
('ramayana-5-23-8', 'en', 'Trembling, she fell like a plantain in a gale; terrified of the rakshasis, her face grew pale.', 'veda-app-ai-draft', true),
('ramayana-5-23-9', 'en', 'As she trembled, her long thick braid was seen quivering like a gliding snake.', 'veda-app-ai-draft', true),
('ramayana-5-23-10', 'en', 'Sighing, pained, her mind struck by grief, Maithili shed tears and lamented.', 'veda-app-ai-draft', true),
('ramayana-5-23-11', 'en', 'Oh Rama! she cried in pain, and again, Oh Lakshmana! Oh my mother-in-law Kausalya! Oh Sumitra!', 'veda-app-ai-draft', true),
('ramayana-5-23-12', 'en', 'This saying spoken by the wise is true: death is hard to come by before its time, for woman or for man.', 'veda-app-ai-draft', true),
('ramayana-5-23-13', 'en', 'since here I am, tormented by these cruel rakshasis, and still I live, even a moment, wretched without Rama.', 'veda-app-ai-draft', true),
('ramayana-5-23-14', 'en', 'With little merit and in misery, I will perish like an orphan, like a laden ship in mid-ocean struck by gales.', 'veda-app-ai-draft', true),
('ramayana-5-23-15', 'en', 'Not seeing my husband, in the rakshasis'' power, I sink with grief like a bank beaten by water.', 'veda-app-ai-draft', true),
('ramayana-5-23-16', 'en', 'Blessed are those who see my lord, lotus-eyed, walking with a lion''s stride, grateful and kind of speech.', 'veda-app-ai-draft', true),
('ramayana-5-23-17', 'en', 'Without wise Rama, my life is as hard to keep as if I had tasted deadly poison.', 'veda-app-ai-draft', true),
('ramayana-5-23-18', 'en', 'What sin did I commit in a former life, that I should meet this terrible, dreadful sorrow?', 'veda-app-ai-draft', true),
('ramayana-5-23-19', 'en', 'Overcome by great grief, I want to give up my life. Guarded by the rakshasis, I cannot reach Rama.', 'veda-app-ai-draft', true),
('ramayana-5-23-20', 'en', 'Shame on human life, shame on being in another''s power, where one cannot even give up one''s life at will.', 'veda-app-ai-draft', true),
('ramayana-5-24-1', 'en', 'Saying this, her face streaming with tears, Janaka''s young daughter, head bowed, began to lament.', 'veda-app-ai-draft', true),
('ramayana-5-24-2', 'en', 'Like one mad, distracted, bewildered, she grieved, rolling on the ground like a young mare.', 'veda-app-ai-draft', true),
('ramayana-5-24-3', 'en', 'While Rama was off guard, the shape-changing rakshasa Ravana seized me by force and carried me off screaming.', 'veda-app-ai-draft', true),
('ramayana-5-24-4', 'en', 'Fallen into the rakshasis'' power, threatened so cruelly, brooding in deep sorrow, I cannot bear to live.', 'veda-app-ai-draft', true),
('ramayana-5-24-5', 'en', 'I have no use for life, wealth or ornaments, living among rakshasis without Rama, the great warrior.', 'veda-app-ai-draft', true),
('ramayana-5-24-6', 'en', 'Shame on me, ignoble and unfaithful, that I keep this sinful life even a moment without him.', 'veda-app-ai-draft', true),
('ramayana-5-24-7', 'en', 'What hope have I in life or happiness without my beloved husband, kind of speech, lord of the sea-bound earth?', 'veda-app-ai-draft', true),
('ramayana-5-24-8', 'en', 'Let my body be cut or eaten; I give it up. I cannot bear this sorrow long without my beloved.', 'veda-app-ai-draft', true),
('ramayana-5-24-9', 'en', 'I would not touch the night-roamer even with my left foot, so how could I ever love the despicable Ravana?', 'veda-app-ai-draft', true),
('ramayana-5-24-10', 'en', 'Cruel by nature, he does not know he has been refused, nor knows himself or his own family, wanting to woo me.', 'veda-app-ai-draft', true),
('ramayana-5-24-11', 'en', 'Cut, split, torn apart or burned in blazing fire, I will not go to Ravana. Why all your long chatter?', 'veda-app-ai-draft', true),
('ramayana-5-24-12', 'en', 'Rama is famous, wise, grateful and compassionate, of good conduct; I fear he has become pitiless because my fortune has run out.', 'veda-app-ai-draft', true),
('ramayana-5-24-13', 'en', 'He who alone destroyed fourteen thousand rakshasas in Janasthana, why does he not come for me?', 'veda-app-ai-draft', true),
('ramayana-5-24-14', 'en', 'I am held by Ravana, a rakshasa of little strength. My husband is surely able to kill Ravana in battle.', 'veda-app-ai-draft', true),
('ramayana-5-24-15', 'en', 'Rama, who killed Viradha, bull among rakshasas, in battle in the Dandaka forest, why does he not come for me?', 'veda-app-ai-draft', true),
('ramayana-5-24-16', 'en', 'True, this Lanka in mid-ocean is hard to attack, but nothing can stop the flight of Rama''s arrows.', 'veda-app-ai-draft', true),
('ramayana-5-24-17', 'en', 'What can be the reason that Rama, firm in valour, does not come to rescue his beloved wife, carried off by a rakshasa?', 'veda-app-ai-draft', true),
('ramayana-5-24-18', 'en', 'I suspect Lakshmana''s elder brother does not know I am here. Knowing it, the mighty one would never tolerate such an insult.', 'veda-app-ai-draft', true),
('ramayana-5-24-19', 'en', 'Even the vulture king, who could have found out and told Rama I was carried off, was struck down by Ravana in battle.', 'veda-app-ai-draft', true),
('ramayana-5-24-20', 'en', 'Old Jatayu did a great deed in coming to my rescue and standing against Ravana in single combat.', 'veda-app-ai-draft', true),
('ramayana-5-24-21', 'en', 'If Rama knew I was here, today in his anger he would rid the world of rakshasas with his arrows.', 'veda-app-ai-draft', true),
('ramayana-5-24-22', 'en', 'He would destroy the city of Lanka, dry up the great ocean, and wipe out the fame and name of vile Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-24-23', 'en', 'Then in every house the rakshasi widows would weep as I weep now, no doubt; Rama with Lakshmana would search out Lanka.', 'veda-app-ai-draft', true),
('ramayana-5-24-24', 'en', 'No enemy seen by those two lives even a moment. Soon Lanka will be like a cremation ground, its roads thick with pyre smoke and crowded with circling vultures.', 'veda-app-ai-draft', true),
('ramayana-5-24-25', 'en', 'Very soon I will have my wish. This evil course of yours points to the ruin of you all.', 'veda-app-ai-draft', true),
('ramayana-5-24-26', 'en', 'Judging by the ill omens seen in Lanka, very soon it will lose its splendour.', 'veda-app-ai-draft', true),
('ramayana-5-24-27', 'en', 'Surely when wicked Ravana, the rakshasa lord, is killed, unconquerable Lanka will wither like a widowed woman.', 'veda-app-ai-draft', true),
('ramayana-5-24-28', 'en', 'Lanka, now rich with festivals, will lose its lord and its rakshasas, like a woman who has lost her husband.', 'veda-app-ai-draft', true),
('ramayana-5-24-29', 'en', 'Surely before long I will hear here the cries of grieving rakshasa women weeping in every house.', 'veda-app-ai-draft', true),
('ramayana-5-24-30', 'en', 'Dark and lightless, its rakshasa heroes slain, the city of Lanka will be burnt by Rama''s arrows.', 'veda-app-ai-draft', true),
('ramayana-5-24-31', 'en', 'If only brave Rama, with his red-cornered eyes, knew that I am in Ravana''s house!', 'veda-app-ai-draft', true),
('ramayana-5-24-32', 'en', 'The time limit set for me by this cruel, vile Ravana has now arrived.', 'veda-app-ai-draft', true),
('ramayana-5-24-33', 'en', 'These evil-doing rakshasas do not know what must not be done. From such wrongdoing a great disaster will soon come.', 'veda-app-ai-draft', true),
('ramayana-5-24-34', 'en', 'These flesh-eating rakshasas do not know dharma. The rakshasa will surely make me his breakfast.', 'veda-app-ai-draft', true),
('ramayana-5-24-35', 'en', 'What can I do without handsome Rama, his eyes red-cornered, not seeing him, in deep sorrow?', 'veda-app-ai-draft', true),
('ramayana-5-24-36', 'en', 'If anyone here would give me poison today, I would soon see the god Yama, without my husband.', 'veda-app-ai-draft', true),
('ramayana-5-24-37', 'en', 'Rama, Lakshmana''s elder brother, does not know I am alive. If they knew, the two would surely search the whole earth for me.', 'veda-app-ai-draft', true),
('ramayana-5-24-38', 'en', 'Or surely, from grief for me, the hero, Lakshmana''s elder brother, has left his body on earth and gone to the world of the gods.', 'veda-app-ai-draft', true),
('ramayana-5-24-39', 'en', 'Blessed are the gods, gandharvas, siddhas and great sages who see my lord, lotus-eyed Rama.', 'veda-app-ai-draft', true),
('ramayana-5-24-40', 'en', 'Or perhaps wise Rama, the royal sage, who seeks only dharma, the supreme soul, has no need of me as his wife.', 'veda-app-ai-draft', true),
('ramayana-5-24-41', 'en', 'Affection lasts while one is seen and fades when one is not. But the ungrateful destroy love; Rama will not.', 'veda-app-ai-draft', true),
('ramayana-5-24-42', 'en', 'Do I have no virtues, or has my fortune run out, that I, Sita, am parted from Rama, the noblest of men?', 'veda-app-ai-draft', true),
('ramayana-5-24-43', 'en', 'Better for me to die than live, parted from great Rama of flawless conduct, brave slayer of foes.', 'veda-app-ai-draft', true),
('ramayana-5-24-44', 'en', 'Or perhaps the two brothers, best of men, have laid down their weapons and live in the forest eating roots and fruit.', 'veda-app-ai-draft', true),
('ramayana-5-24-45', 'en', 'Or the wicked rakshasa lord Ravana has killed the brave brothers Rama and Lakshmana by trickery.', 'veda-app-ai-draft', true),
('ramayana-5-24-46', 'en', 'At such a time I wish only to die, yet death is not fated for me even in this sorrow.', 'veda-app-ai-draft', true),
('ramayana-5-24-47', 'en', 'Blessed indeed are the great sages, true and self-controlled, for whom nothing is liked or disliked.', 'veda-app-ai-draft', true),
('ramayana-5-24-48', 'en', 'Sorrow does not come from what is loved, but from loss of the loved one, and greater fear from what is disliked. Salutations to those great souls who are free of both.', 'veda-app-ai-draft', true),
('ramayana-5-24-49', 'en', 'Abandoned here by my beloved, wise Rama, fallen into the power of sinful Ravana, I will give up my life.', 'veda-app-ai-draft', true),
('ramayana-5-25-1', 'en', 'Spoken to so grimly by Sita, some rakshasis, mad with anger, went to tell the powerful Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-25-2', 'en', 'Then the fearsome rakshasis came up to Sita and again said harsh things, all to one end, all meaning harm.', 'veda-app-ai-draft', true),
('ramayana-5-25-3', 'en', 'Now, wicked Sita, set on evil, the rakshasis will eat your flesh at their pleasure.', 'veda-app-ai-draft', true),
('ramayana-5-25-4', 'en', 'Seeing Sita threatened by those ignoble ones, the old rakshasi Trijata, who had been lying down, spoke.', 'veda-app-ai-draft', true),
('ramayana-5-25-5', 'en', 'Eat yourselves, ignoble ones; you will not eat Sita, the beloved daughter of Janaka and daughter-in-law of Dasharatha.', 'veda-app-ai-draft', true),
('ramayana-5-25-6', 'en', 'Today I had a terrible, hair-raising dream, foretelling the end of the rakshasas and the rise of her husband.', 'veda-app-ai-draft', true),
('ramayana-5-25-7', 'en', 'Spoken to this way by Trijata, the rakshasis, though mad with anger, all grew afraid and said to Trijata:', 'veda-app-ai-draft', true),
('ramayana-5-25-8', 'en', 'Tell us what kind of dream you saw in the night.', 'veda-app-ai-draft', true),
('ramayana-5-25-9', 'en', 'Hearing the words from the rakshasis'' mouths, Trijata spoke at the right moment about her dream.', 'veda-app-ai-draft', true),
('ramayana-5-25-10', 'en', 'Rama himself, riding a heavenly ivory palanquin moving through the sky, yoked to a thousand horses,', 'veda-app-ai-draft', true),
('ramayana-5-25-11', 'en', 'and in my dream I saw Sita dressed in white, seated on a white mountain surrounded by the sea, united with Rama like light with the sun.', 'veda-app-ai-draft', true),
('ramayana-5-25-12', 'en', 'I saw Rama riding a great four-tusked elephant, huge as a mountain, moving with Lakshmana.', 'veda-app-ai-draft', true),
('ramayana-5-25-13', 'en', 'Then those two tigers among men, blazing with their own splendour, in white garlands and robes, came to Janaki.', 'veda-app-ai-draft', true),
('ramayana-5-25-14', 'en', 'Then Janaki, taken by her husband, sat on the shoulder of that elephant standing in the sky on the mountain top.', 'veda-app-ai-draft', true),
('ramayana-5-25-15', 'en', 'Rising from her husband''s lap, the lotus-eyed lady seemed to me to stroke the moon and sun with her hands.', 'veda-app-ai-draft', true),
('ramayana-5-25-16', 'en', 'Then that great elephant, carrying the two princes and wide-eyed Sita, stood above Lanka.', 'veda-app-ai-draft', true),
('ramayana-5-25-17', 'en', 'Rama himself, in white garlands and robes, came in a chariot drawn by eight white bulls, with his brother Lakshmana and his wife Sita.', 'veda-app-ai-draft', true),
('ramayana-5-25-18', 'en', 'Today Ravana fell from the Pushpaka vimana to the ground, dragged by a woman, shaven-headed and dressed in black.', 'veda-app-ai-draft', true),
('ramayana-5-25-19', 'en', 'In a chariot drawn by donkeys, wearing red garlands and unguents, he went south and entered a muddy pool.', 'veda-app-ai-draft', true),
('ramayana-5-25-20', 'en', 'A dark woman in red, her body smeared with mud, tied a rope round the ten-necked one''s neck and dragged him south.', 'veda-app-ai-draft', true),
('ramayana-5-25-21', 'en', 'Ten-necked Ravana on a boar, Indrajit on a porpoise and Kumbhakarna on a camel went south.', 'veda-app-ai-draft', true),
('ramayana-5-25-22', 'en', 'There was a great gathering with song and music, of rakshasas in red garlands and red clothes, drinking.', 'veda-app-ai-draft', true),
('ramayana-5-25-23', 'en', 'And this lovely city of Lanka, full of horses and chariots, was seen fallen into the sea, its gates and arches broken.', 'veda-app-ai-draft', true),
('ramayana-5-25-24', 'en', 'All the rakshasa women, having drunk oil, danced and laughed loudly in Lanka, rough with ashes.', 'veda-app-ai-draft', true),
('ramayana-5-25-25', 'en', 'And Kumbhakarna and all these rakshasa chiefs, wearing red, entered a pool of cow dung.', 'veda-app-ai-draft', true),
('ramayana-5-25-26', 'en', 'Get away, be gone! Rama is winning Sita back. In his great fury he will kill you along with all the rakshasas.', 'veda-app-ai-draft', true),
('ramayana-5-25-27', 'en', 'Rama will not forgive anyone who scolded or threatened his beloved, honoured wife who followed him into the forest.', 'veda-app-ai-draft', true),
('ramayana-5-25-28', 'en', 'So enough of your cruel words; speak only kindly. Let us beg Vaidehi''s favour; that is what I want.', 'veda-app-ai-draft', true),
('ramayana-5-25-29', 'en', 'A grieving woman who sees such a dream is freed from her many sorrows and gains the highest joy.', 'veda-app-ai-draft', true),
('ramayana-5-25-30', 'en', 'Though you threatened her, beg her pardon, rakshasis; why argue? A terrible danger from Rama has come upon the rakshasas.', 'veda-app-ai-draft', true),
('ramayana-5-25-31', 'en', 'Maithili, Janaka''s daughter, is won over by bowing. She is able to save you from great danger, rakshasis.', 'veda-app-ai-draft', true),
('ramayana-5-25-32', 'en', 'I see no bad sign at all on this wide-eyed lady''s body, not even the slightest.', 'veda-app-ai-draft', true),
('ramayana-5-25-33', 'en', 'I think the sorrow that has come to this queen, who does not deserve sorrow, is only a passing shadow; I see her rising to the sky.', 'veda-app-ai-draft', true),
('ramayana-5-25-34', 'en', 'I see Vaidehi''s goal coming true, the destruction of the rakshasa lord and Rama''s victory.', 'veda-app-ai-draft', true),
('ramayana-5-25-35', 'en', 'There is a sign that she will soon hear something very dear: her long, lotus-petal eye is twitching.', 'veda-app-ai-draft', true),
('ramayana-5-25-36', 'en', 'And suddenly one arm of this gracious lady is trembling a little, thrilled.', 'veda-app-ai-draft', true),
('ramayana-5-25-37', 'en', 'And her fine left thigh, like an elephant''s trunk, trembling, seems to show that Rama stands before her.', 'veda-app-ai-draft', true),
('ramayana-5-25-38', 'en', 'And a bird, entering its nest in a branch again and again, calling sweetly, seems to urge her on joyfully, speaking words of welcome.', 'veda-app-ai-draft', true),
('ramayana-5-26-1', 'en', 'Hearing the unwelcome words of Ravana, the rakshasa lord, Sita, pained, trembled like a young she-elephant attacked by a lion at the forest''s edge.', 'veda-app-ai-draft', true),
('ramayana-5-26-2', 'en', 'Timid Sita, in the midst of the rakshasis and harshly threatened by Ravana, lamented like a young girl left alone in a deserted wilderness.', 'veda-app-ai-draft', true),
('ramayana-5-26-3', 'en', 'Truly the good say there is no untimely death in this world, since I, so threatened, ill-fated, still live even a moment.', 'veda-app-ai-draft', true),
('ramayana-5-26-4', 'en', 'Surely my heart, robbed of happiness and full of sorrow, is hard as stone, since it does not shatter into a thousand pieces like a mountain peak struck by a thunderbolt.', 'veda-app-ai-draft', true),
('ramayana-5-26-5', 'en', 'There is surely no fault of mine here. I am to be killed by this hateful one, for I can no more give him my heart than a brahmin can give a mantra to one not initiated.', 'veda-app-ai-draft', true),
('ramayana-5-26-6', 'en', 'Surely, with the lord of the world not coming, the ignoble rakshasa lord will soon cut my limbs with sharp weapons, like a surgeon removing an unborn child.', 'veda-app-ai-draft', true),
('ramayana-5-26-7', 'en', 'How sad that for me in my sorrow the two months will soon be over, like a thief bound for execution at night''s end for offending the king.', 'veda-app-ai-draft', true),
('ramayana-5-26-8', 'en', 'Oh Rama, oh Lakshmana, oh Sumitra, oh Rama''s mother and my own mother! Ill-fated, I perish like a ship in a great ocean struck by gales.', 'veda-app-ai-draft', true),
('ramayana-5-26-9', 'en', 'The two mighty princes, sons of the lord of men, have surely been killed because of me by that creature in the shape of a deer, like two lions slain by lightning.', 'veda-app-ai-draft', true),
('ramayana-5-26-10', 'en', 'Surely it was Death himself in the form of a deer who lured unlucky me then, when foolishly I sent away my noble husband, and Lakshmana after him.', 'veda-app-ai-draft', true),
('ramayana-5-26-11', 'en', 'Oh Rama, true to your vows, long-armed, face like the full moon, friend and beloved of the living world, you do not know I am to be killed by rakshasas.', 'veda-app-ai-draft', true),
('ramayana-5-26-12', 'en', 'My devotion to you as my only god, my patience, sleeping on the ground, my discipline in dharma, my faithfulness: all this has been in vain, like a kindness done to the ungrateful.', 'veda-app-ai-draft', true),
('ramayana-5-26-13', 'en', 'The dharma I have practised is in vain, and my faithfulness to one husband is pointless, since I cannot see you; thin and pale, parted from you, I have no hope of meeting.', 'veda-app-ai-draft', true),
('ramayana-5-26-14', 'en', 'Having carried out your father''s order faithfully and returned from the forest with your vow fulfilled, I think you will enjoy yourself, free of fear and successful, with wide-eyed women.', 'veda-app-ai-draft', true),
('ramayana-5-26-15', 'en', 'But I, Rama, who loved you and was bound to you to my own ruin, having practised austerity in vain, will give up this life. Shame on unlucky me.', 'veda-app-ai-draft', true),
('ramayana-5-26-16', 'en', 'I would quickly give up my life with poison or a sharp weapon, but there is no one in the rakshasa''s house to give me poison or a weapon.', 'veda-app-ai-draft', true),
('ramayana-5-26-17', 'en', 'Burning with grief and thinking it over many ways, Sita took hold of her braid: With my braid I will quickly hang myself and go to Yama.', 'veda-app-ai-draft', true),
('ramayana-5-26-18', 'en', 'Lamenting thus in many ways, remembering Rama with all her being, trembling and dry-mouthed, Sita came to the finest flowering tree.', 'veda-app-ai-draft', true),
('ramayana-5-26-19', 'en', 'Standing there, soft in every limb, holding a branch of the tree, thinking of Rama, of Lakshmana and of her own good family,', 'veda-app-ai-draft', true),
('ramayana-5-26-20', 'en', 'many signs that end sorrow, well known in the world for bringing courage, and proven before, then appeared to her.', 'veda-app-ai-draft', true),
('ramayana-5-27-1', 'en', 'To that blameless, distressed lady, her joy gone and her heart sunk in sorrow, good omens came, as dependants come to a man blessed with fortune.', 'veda-app-ai-draft', true),
('ramayana-5-27-2', 'en', 'Her lovely left eye, with curved lashes, dark, wide and white, framed by lines, twitched, like a reddish lotus struck by a fish.', 'veda-app-ai-draft', true),
('ramayana-5-27-3', 'en', 'And her lovely, rounded left arm, fit for the finest aloe and sandal, on which her beloved had long rested, quickly trembled.', 'veda-app-ai-draft', true),
('ramayana-5-27-4', 'en', 'And her shapely thigh, like an elephant''s trunk, trembling again, seemed to say that Rama stood before her.', 'veda-app-ai-draft', true),
('ramayana-5-27-5', 'en', 'And the lovely gold-coloured garment of the clear-eyed, graceful lady, a little dusty, slipped slightly as she stood.', 'veda-app-ai-draft', true),
('ramayana-5-27-6', 'en', 'Awakened by these and other signs, proven reliable before, the fair-browed lady revived, like a seed withered by wind and sun revived by rain.', 'veda-app-ai-draft', true),
('ramayana-5-27-7', 'en', 'Her face, with lips like bimba fruit, fine eyes and brows, curved lashes and white teeth, shone like the moon freed from Rahu''s mouth.', 'veda-app-ai-draft', true),
('ramayana-5-27-8', 'en', 'Her grief gone, her weariness lifted, her fever calmed, her spirit awakened by joy, the noble lady shone with her face like the night with the rising moon.', 'veda-app-ai-draft', true),
('ramayana-5-28-1', 'en', 'Valiant Hanuman heard everything truly: Sita''s words, Trijata''s dream and the rakshasis'' threats.', 'veda-app-ai-draft', true),
('ramayana-5-28-2', 'en', 'Gazing at the queen like a goddess in Nandana, the monkey thought many thoughts.', 'veda-app-ai-draft', true),
('ramayana-5-28-3', 'en', 'She whom many thousands and tens of thousands of monkeys seek in every direction, I have found.', 'veda-app-ai-draft', true),
('ramayana-5-28-4', 'en', 'Moving secretly as a careful spy, I have observed the enemy''s strength.', 'veda-app-ai-draft', true),
('ramayana-5-28-5', 'en', 'I have seen the rakshasas'' strength, this city, and the power of Ravana, lord of the rakshasas.', 'veda-app-ai-draft', true),
('ramayana-5-28-6', 'en', 'It is right to comfort the wife of that boundless one, compassionate to all beings, who longs to see her husband.', 'veda-app-ai-draft', true),
('ramayana-5-28-7', 'en', 'I will comfort this lady with a face like the full moon, who never knew sorrow and finds no end to it.', 'veda-app-ai-draft', true),
('ramayana-5-28-8', 'en', 'If I leave without comforting this queen, her mind struck by grief, my leaving would be wrong.', 'veda-app-ai-draft', true),
('ramayana-5-28-9', 'en', 'Once I have gone, the famous princess Janaki, finding no rescue, may give up her life.', 'veda-app-ai-draft', true),
('ramayana-5-28-10', 'en', 'And I must also comfort the mighty-armed one with a face like the full moon, who longs to see Sita.', 'veda-app-ai-draft', true),
('ramayana-5-28-11', 'en', 'But speaking to her in front of the night-roaming women is unwise. How should I do this? I am in a difficult spot.', 'veda-app-ai-draft', true),
('ramayana-5-28-12', 'en', 'If I do not comfort her before the night ends, there is no doubt she will give up her life.', 'veda-app-ai-draft', true),
('ramayana-5-28-13', 'en', 'And if Rama asks me what Sita said to him, what will I answer if I have not spoken to her?', 'veda-app-ai-draft', true),
('ramayana-5-28-14', 'en', 'If I rush back without a message from Sita, Rama might burn me in anger with his fierce gaze.', 'veda-app-ai-draft', true),
('ramayana-5-28-15', 'en', 'If I bring her husband here for Rama''s cause without proof, his coming with the army would be in vain.', 'veda-app-ai-draft', true),
('ramayana-5-28-16', 'en', 'Waiting here for a gap among the rakshasis, I will gently comfort this much-suffering lady.', 'veda-app-ai-draft', true),
('ramayana-5-28-17', 'en', 'I am very small, and a monkey besides. I will speak to her in human speech, in Sanskrit.', 'veda-app-ai-draft', true),
('ramayana-5-28-18', 'en', 'But if I speak refined Sanskrit like a brahmin, Sita will think I am Ravana and be afraid.', 'veda-app-ai-draft', true),
('ramayana-5-28-19', 'en', 'I must speak meaningful human words; otherwise I cannot comfort the blameless lady.', 'veda-app-ai-draft', true),
('ramayana-5-28-20', 'en', 'Seeing my form and hearing me speak, Janaki, already frightened by the rakshasas, will be frightened again.', 'veda-app-ai-draft', true),
('ramayana-5-28-21', 'en', 'Then, terrified, the wise wide-eyed lady may cry out, thinking I am shape-changing Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-28-22', 'en', 'If Sita cries out, the dreadful host of rakshasis, like Death, will rush up with all kinds of weapons.', 'veda-app-ai-draft', true),
('ramayana-5-28-23', 'en', 'Then, surrounding me on all sides, the ugly-faced ones would try their best to kill or capture me.', 'veda-app-ai-draft', true),
('ramayana-5-28-24', 'en', 'Seeing me leap about the branches, sub-branches and trunks of the great trees, they would grow fearful.', 'veda-app-ai-draft', true),
('ramayana-5-28-25', 'en', 'Seeing my form as I roam the great grove, the ugly-faced rakshasis would be terrified.', 'veda-app-ai-draft', true),
('ramayana-5-28-26', 'en', 'Then the rakshasis would summon the rakshasas posted by the rakshasa lord in his palace.', 'veda-app-ai-draft', true),
('ramayana-5-28-27', 'en', 'Holding spears, arrows, swords and all kinds of weapons, they would rush into the fight, causing alarm.', 'veda-app-ai-draft', true),
('ramayana-5-28-28', 'en', 'Even if in my anger I destroyed the rakshasa army around me, I might not be able to reach the far shore of the ocean.', 'veda-app-ai-draft', true),
('ramayana-5-28-29', 'en', 'Or many swift ones might leap on me and seize me; then her hope would be unmet and I would be captured.', 'veda-app-ai-draft', true),
('ramayana-5-28-30', 'en', 'Or those who love violence might harm Janaka''s daughter; then the work of Rama and Sugriva would fail.', 'veda-app-ai-draft', true),
('ramayana-5-28-31', 'en', 'Janaki lives in a hidden place whose way is lost, surrounded by rakshasas and enclosed by the sea.', 'veda-app-ai-draft', true),
('ramayana-5-28-32', 'en', 'If I am killed or captured by the rakshasas in battle, I see no other helper for Rama in achieving his aim.', 'veda-app-ai-draft', true),
('ramayana-5-28-33', 'en', 'Thinking it over, I see no monkey who could leap the hundred-yojana ocean if I were killed.', 'veda-app-ai-draft', true),
('ramayana-5-28-34', 'en', 'I can certainly kill thousands of rakshasas, but I might not be able to reach the far shore of the ocean.', 'veda-app-ai-draft', true),
('ramayana-5-28-35', 'en', 'Battles are uncertain, and I do not like doubt. What wise person would turn a sure task into an unsure one?', 'veda-app-ai-draft', true),
('ramayana-5-28-36', 'en', 'Speaking to Sita carries great risk, and not speaking could cost Vaidehi her life.', 'veda-app-ai-draft', true),
('ramayana-5-28-37', 'en', 'Tasks that are ready to succeed fail when they go against place and time, or fall to a nervous messenger, as darkness fails at sunrise.', 'veda-app-ai-draft', true),
('ramayana-5-28-38', 'en', 'Even a firm decision about what to do does not shine if misused. Messengers who think themselves clever ruin tasks.', 'veda-app-ai-draft', true),
('ramayana-5-28-39', 'en', 'How can I keep the task from failing? How can I avoid losing my nerve? How can my leap across the ocean not be in vain?', 'veda-app-ai-draft', true),
('ramayana-5-28-40', 'en', 'How can she hear my words without being alarmed? Thinking this, wise Hanuman made up his mind.', 'veda-app-ai-draft', true),
('ramayana-5-28-41', 'en', 'By praising Rama of flawless deeds, her own beloved, I will not alarm her, for her mind is fixed on him.', 'veda-app-ai-draft', true),
('ramayana-5-28-42', 'en', 'Offering good, righteous words about wise Rama, best of the Ikshvakus,', 'veda-app-ai-draft', true),
('ramayana-5-28-43', 'en', 'I will tell her everything, speaking sweetly, and arrange it all so that she believes me.', 'veda-app-ai-draft', true),
('ramayana-5-28-44', 'en', 'So, thinking in many ways and gazing at the wife of the lord of the earth, great Hanuman, sitting among the branches, spoke sweet and truthful words.', 'veda-app-ai-draft', true),
('ramayana-5-29-1', 'en', 'After thinking in many ways, the great monkey spoke sweet words within Vaidehi''s hearing.', 'veda-app-ai-draft', true),
('ramayana-5-29-2', 'en', 'There was a king named Dasharatha, rich in chariots, elephants and horses, virtuous, very famous, honest and glorious, born in a line of emperors, equal to Indra in strength.', 'veda-app-ai-draft', true),
('ramayana-5-29-3', 'en', 'He loved non-violence, was never petty, was compassionate and truly valiant, the foremost of the Ikshvaku line, prosperous and a bringer of prosperity.', 'veda-app-ai-draft', true),
('ramayana-5-29-4', 'en', 'He had all the marks of a king, great fortune, was a bull among kings, famous across the four-cornered earth, giving happiness and happy himself.', 'veda-app-ai-draft', true),
('ramayana-5-29-5', 'en', 'His dear eldest son, with a face like the moon, is named Rama, discerning, the best of all archers.', 'veda-app-ai-draft', true),
('ramayana-5-29-6', 'en', 'Protector of his own conduct and of his people, protector of the living world and of dharma, scorcher of foes.', 'veda-app-ai-draft', true),
('ramayana-5-29-7', 'en', 'At the word of his old father, true to his promise, the hero went into the forest with his wife and brother.', 'veda-app-ai-draft', true),
('ramayana-5-29-8', 'en', 'There in the great forest, while he was out hunting, Ravana, angered at hearing of the slaughter at Janasthana and the killing of Khara and Dushana, carried off Janaki.', 'veda-app-ai-draft', true),
('ramayana-5-29-9', 'en', 'Just as Rama described her form, colour and beauty, so I have found her here.', 'veda-app-ai-draft', true),
('ramayana-5-29-10', 'en', 'Having said this, the best of monkeys fell silent, and Janaki, hearing it, was filled with great wonder.', 'veda-app-ai-draft', true),
('ramayana-5-29-11', 'en', 'Then the timid lady, her hair curling at the ends, lifted her face covered by her hair and looked at the shimshapa tree.', 'veda-app-ai-draft', true),
('ramayana-5-29-12', 'en', 'Looking sideways, up and down, she saw the minister of the monkey king, the son of the Wind, of unimaginable wisdom, like the sun rising.', 'veda-app-ai-draft', true),
('ramayana-5-30-1', 'en', 'Then, seeing him hidden among the branches, her mind shaken, she saw the monkey there, humble and kind of speech.', 'veda-app-ai-draft', true),
('ramayana-5-30-2', 'en', 'Seeing the best of monkeys standing there respectfully, lovely Maithili thought: This is a dream.', 'veda-app-ai-draft', true),
('ramayana-5-30-3', 'en', 'On seeing him Sita fainted, as if lifeless; regaining consciousness after a long time, the wide-eyed lady thought:', 'veda-app-ai-draft', true),
('ramayana-5-30-4', 'en', 'Today I saw a strange dream, a monkey, which the scriptures forbid. May all be well with Rama and Lakshmana, and with my father King Janaka.', 'veda-app-ai-draft', true),
('ramayana-5-30-5', 'en', 'But this is no dream, for I do not sleep, tormented by grief and sorrow. There is no happiness for me, parted from him whose face is like the full moon.', 'veda-app-ai-draft', true),
('ramayana-5-30-6', 'en', 'Tormented by love for him, my whole being given to him, always thinking of him, I see and hear only him.', 'veda-app-ai-draft', true),
('ramayana-5-30-7', 'en', 'I think it may be my own wish, yet I reason with my mind: what is the cause? A wish has no form, yet this one clearly speaks to me.', 'veda-app-ai-draft', true),
('ramayana-5-30-8', 'en', 'Salutations to Brihaspati, to Indra with his thunderbolt, to self-born Brahma and to Fire. May what this forest-dweller has said before me be true and not otherwise.', 'veda-app-ai-draft', true),
('ramayana-5-31-1', 'en', 'Radiant Hanuman, son of the Wind, folded his hands above his head and spoke to Sita in a sweet voice.', 'veda-app-ai-draft', true),
('ramayana-5-31-2', 'en', 'Who are you, lotus-eyed blameless one, in worn silk, standing holding the branch of a tree?', 'veda-app-ai-draft', true),
('ramayana-5-31-3', 'en', 'Why do tears of grief flow from your eyes, like water scattered from lotus petals?', 'veda-app-ai-draft', true),
('ramayana-5-31-4', 'en', 'Lovely one, are you one of the gods, asuras, nagas, gandharvas, rakshasas, yakshas or kinnaras?', 'veda-app-ai-draft', true),
('ramayana-5-31-5', 'en', 'Are you one of the Rudras, the Maruts or the Vasus, lovely-faced one? You seem to me a goddess.', 'veda-app-ai-draft', true),
('ramayana-5-31-6', 'en', 'Are you Rohini, best of stars, endowed with every virtue, fallen from the home of the gods, parted from the Moon?', 'veda-app-ai-draft', true),
('ramayana-5-31-7', 'en', 'Or, dark-eyed one, are you the blessed Arundhati, who angered her husband Vasishtha out of anger or confusion?', 'veda-app-ai-draft', true),
('ramayana-5-31-8', 'en', 'Who is it, slender one, son, father, brother or husband, gone from this world to the next, that you grieve for?', 'veda-app-ai-draft', true),
('ramayana-5-31-9', 'en', 'From the signs and marks I see on you, I think you are a queen of a king, a king''s daughter.', 'veda-app-ai-draft', true),
('ramayana-5-31-10', 'en', 'If you are Sita, carried off by force by Ravana from Janasthana, bless you, tell me as I ask.', 'veda-app-ai-draft', true),
('ramayana-5-31-11', 'en', 'Hearing his words and delighted by the praise of Rama, Vaidehi spoke to Hanuman in the tree.', 'veda-app-ai-draft', true),
('ramayana-5-31-12', 'en', 'I am the daughter of great Janaka of Videha. My name is Sita, and I am the wife of wise Rama.', 'veda-app-ai-draft', true),
('ramayana-5-31-13', 'en', 'For twelve years I lived in Rama''s house, enjoying human pleasures, with every wish fulfilled.', 'veda-app-ai-draft', true),
('ramayana-5-31-14', 'en', 'Then in the thirteenth year the king, with his priests, began to consecrate the delight of the Ikshvakus as king.', 'veda-app-ai-draft', true),
('ramayana-5-31-15', 'en', 'While Rama''s consecration was being prepared, Queen Kaikeyi said to her husband:', 'veda-app-ai-draft', true),
('ramayana-5-31-16', 'en', 'I will neither drink nor eat my daily food. If Rama is consecrated, this will be the end of my life.', 'veda-app-ai-draft', true),
('ramayana-5-31-17', 'en', 'If what you promised me in love, best of kings, is not to be false, let Rama go to the forest.', 'veda-app-ai-draft', true),
('ramayana-5-31-18', 'en', 'The truthful king, remembering the boon he had given the queen, fainted on hearing Kaikeyi''s cruel, unwelcome words.', 'veda-app-ai-draft', true),
('ramayana-5-31-19', 'en', 'Then the old king, firm in the dharma of truth, weeping, asked his famous eldest son for the kingdom.', 'veda-app-ai-draft', true),
('ramayana-5-31-20', 'en', 'Glorious Rama first accepted his father''s word in his mind, dearer to him than the consecration, and then accepted it in words.', 'veda-app-ai-draft', true),
('ramayana-5-31-21', 'en', 'Rama, true in valour, would give and not take, and would never say anything unkind, even to save his life.', 'veda-app-ai-draft', true),
('ramayana-5-31-22', 'en', 'The famous one put off his costly upper garments, gave up the kingdom in his mind, and entrusted me to his mother.', 'veda-app-ai-draft', true),
('ramayana-5-31-23', 'en', 'But I set out quickly ahead of him to live in the forest, for without him even heaven would not please me.', 'veda-app-ai-draft', true),
('ramayana-5-31-24', 'en', 'Even before that, noble Lakshmana, son of Sumitra and joy of his friends, put on bark clothes to follow his elder brother.', 'veda-app-ai-draft', true),
('ramayana-5-31-25', 'en', 'Honouring our master''s command and firm in our vows, we left the city and entered the deep, dark forest.', 'veda-app-ai-draft', true),
('ramayana-5-31-26', 'en', 'While that hero of boundless power lived in the Dandaka forest, I, his wife, was carried off by the wicked rakshasa Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-31-27', 'en', 'He gave me two months as a grace of life; after those two months I will give up my life.', 'veda-app-ai-draft', true),
('ramayana-5-32-1', 'en', 'Hearing her words, Hanuman, leader of monkey troops, gave a gentle, soothing reply to her who was overwhelmed with sorrow.', 'veda-app-ai-draft', true),
('ramayana-5-32-2', 'en', '"O Queen, I have come as Rama''s messenger, at his command. Vaidehi, Rama is well, and he asks after your welfare."', 'veda-app-ai-draft', true),
('ramayana-5-32-3', 'en', '"Rama, son of Dasharatha, who knows the Brahma weapon and the Vedas, best of the learned, asks after your welfare, O Queen."', 'veda-app-ai-draft', true),
('ramayana-5-32-4', 'en', '"Mighty Lakshmana too, your husband''s beloved companion, burning with grief, bows his head to you in greeting."', 'veda-app-ai-draft', true),
('ramayana-5-32-5', 'en', 'Hearing that those two lions among men were well, the queen thrilled with joy in every limb and spoke to Hanuman.', 'veda-app-ai-draft', true),
('ramayana-5-32-6', 'en', '"How true this popular saying now seems to me: joy comes to a man who stays alive, even after a hundred years."', 'veda-app-ai-draft', true),
('ramayana-5-32-7', 'en', 'At that meeting a wonderful affection arose between them, and trusting each other, they began to talk.', 'veda-app-ai-draft', true),
('ramayana-5-32-8', 'en', 'Hearing her words, Hanuman moved nearer to Sita, who was pale with grief.', 'veda-app-ai-draft', true),
('ramayana-5-32-9', 'en', 'But the closer Hanuman came, the more Sita suspected that he was Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-32-10', 'en', '"Alas, shame on me for what I have told him! This is Ravana himself, having taken another form."', 'veda-app-ai-draft', true),
('ramayana-5-32-11', 'en', 'Worn with sorrow, the faultless Sita let go of the ashoka branch and sat down on the ground.', 'veda-app-ai-draft', true),
('ramayana-5-32-12', 'en', 'Then the mighty-armed Hanuman bowed to Janaka''s daughter, but she, shaking with fear, would not look at him again.', 'veda-app-ai-draft', true),
('ramayana-5-32-13', 'en', 'Seeing him bowing, moon-faced Sita sighed deeply and spoke to the monkey in a sweet voice.', 'veda-app-ai-draft', true),
('ramayana-5-32-14', 'en', '"If you are Ravana himself, the master of illusion, disguised by magic, it is not right that you torment me again."', 'veda-app-ai-draft', true),
('ramayana-5-32-15', 'en', '"You who dropped your own form and took the guise of a wandering ascetic, whom I saw in Janasthana, you are that same Ravana!"', 'veda-app-ai-draft', true),
('ramayana-5-32-16', 'en', '"Shape-shifting night-walker, it is not right that you torment me again, weak from fasting and wretched as I am."', 'veda-app-ai-draft', true),
('ramayana-5-32-17', 'en', '"But if you have truly come as Rama''s messenger, bless you. Best of monkeys, I ask you, for talk of Rama is dear to me."', 'veda-app-ai-draft', true),
('ramayana-5-32-18', 'en', '"Tell me of my beloved Rama''s virtues, monkey. Gentle one, you carry my heart away as a flood carries off a river''s bank."', 'veda-app-ai-draft', true),
('ramayana-5-32-19', 'en', '"Oh, how sweet is this dream, in which I, carried off so long ago, see a forest-dweller sent by Raghava!"', 'veda-app-ai-draft', true),
('ramayana-5-32-20', 'en', '"If I could see the hero Raghava with Lakshmana even in a dream, I would not lose heart; but even dreams are grudging to me."', 'veda-app-ai-draft', true),
('ramayana-5-32-21', 'en', '"I do not think this is a dream, for one who sees a monkey in a dream cannot gain good fortune, and good fortune has come to me."', 'veda-app-ai-draft', true),
('ramayana-5-32-22', 'en', '"Could this be a confusion of mind, a disturbance of the humours, a disorder born of madness, or a mirage?"', 'veda-app-ai-draft', true),
('ramayana-5-32-23', 'en', '"Or no, this is not madness, nor a confusion like madness, for I know myself and I also see this forest-dweller clearly."', 'veda-app-ai-draft', true),
('ramayana-5-32-24', 'en', 'Weighing all this in many ways, Sita, knowing rakshasas can change shape at will, took him for the lord of the rakshasas.', 'veda-app-ai-draft', true),
('ramayana-5-32-25', 'en', 'Having reached this conclusion, slender-waisted Sita, daughter of Janaka, made no reply to the monkey.', 'veda-app-ai-draft', true),
('ramayana-5-32-26', 'en', 'Understanding Sita''s thoughts, Hanuman, son of the Wind, gladdened her with words pleasing to her ears.', 'veda-app-ai-draft', true),
('ramayana-5-32-27', 'en', '"Radiant as the sun, loved by the world like the moon, he is king of all the world, like the god Kubera."', 'veda-app-ai-draft', true),
('ramayana-5-32-28', 'en', '"Valiant like glorious Vishnu, truthful and sweet-spoken like Brihaspati, lord of speech."', 'veda-app-ai-draft', true),
('ramayana-5-32-29', 'en', '"Handsome, fortunate and splendid like Kama in bodily form, angry only when anger is due, the best chariot warrior in the world; the whole world rests in the shade of that great soul''s arms."', 'veda-app-ai-draft', true),
('ramayana-5-32-30', 'en', '"You will see what fruit comes to him who lured Raghava from the hermitage with a deer''s form and carried you off from the empty place."', 'veda-app-ai-draft', true),
('ramayana-5-32-31', 'en', '"Before long that valiant one will slay Ravana in battle with arrows loosed in anger, blazing like fire."', 'veda-app-ai-draft', true),
('ramayana-5-32-32', 'en', '"He sent me here to you as his messenger. Grieving at your separation, he asks after your welfare."', 'veda-app-ai-draft', true),
('ramayana-5-32-33', 'en', '"Mighty Lakshmana, who brings joy to Sumitra, bows to you and also asks after your welfare."', 'veda-app-ai-draft', true),
('ramayana-5-32-34', 'en', '"Rama''s friend, the monkey named Sugriva, king of the chief monkeys, asks after your welfare too."', 'veda-app-ai-draft', true),
('ramayana-5-32-35', 'en', '"Rama always remembers you, with Sugriva and Lakshmana. Thank heaven you are alive, Vaidehi, though in the power of rakshasis."', 'veda-app-ai-draft', true),
('ramayana-5-32-36', 'en', '"Before long you will see Rama, the great warrior Lakshmana, and Sugriva of boundless strength amid millions of monkeys."', 'veda-app-ai-draft', true),
('ramayana-5-32-37', 'en', '"I am Sugriva''s minister, a monkey named Hanuman. I leapt across the great ocean and entered the city of Lanka."', 'veda-app-ai-draft', true),
('ramayana-5-32-38', 'en', '"Setting my foot on the head of wicked Ravana, relying on my strength, I have come to see you."', 'veda-app-ai-draft', true),
('ramayana-5-32-39', 'en', '"I am not what you take me to be, O Queen. Give up this suspicion and trust what I say."', 'veda-app-ai-draft', true),
('ramayana-5-33-1', 'en', 'Hearing that account of Rama from the bull among monkeys, Vaidehi spoke these gentle words in a sweet voice.', 'veda-app-ai-draft', true),
('ramayana-5-33-2', 'en', '"How did you come to be with Rama? How do you know Lakshmana? How did monkeys and men come to meet?"', 'veda-app-ai-draft', true),
('ramayana-5-33-3', 'en', '"Tell me again the marks of Rama and Lakshmana, monkey, so that sorrow does not overwhelm me."', 'veda-app-ai-draft', true),
('ramayana-5-33-4', 'en', '"What is Rama''s build, what his form? What are his thighs and arms like, and Lakshmana''s? Tell me."', 'veda-app-ai-draft', true),
('ramayana-5-33-5', 'en', 'Asked thus by Vaidehi, Hanuman, son of the Wind, began to describe Rama exactly as he was.', 'veda-app-ai-draft', true),
('ramayana-5-33-6', 'en', '"How fortunate that you, knowing all this, question me about your husband and Lakshmana, lotus-eyed Vaidehi."', 'veda-app-ai-draft', true),
('ramayana-5-33-7', 'en', '"Hear from me, large-eyed one, the marks of Rama and Lakshmana that I have observed."', 'veda-app-ai-draft', true),
('ramayana-5-33-8', 'en', '"Rama is lotus-eyed and wins the hearts of all beings; he was born gifted with beauty and courtesy, daughter of Janaka."', 'veda-app-ai-draft', true),
('ramayana-5-33-9', 'en', '"In splendour he is like the sun, in patience like the earth, in wisdom like Brihaspati, in fame like Indra."', 'veda-app-ai-draft', true),
('ramayana-5-33-10', 'en', '"He protects the living world and his own people; he guards his own conduct and dharma, that scorcher of foes."', 'veda-app-ai-draft', true),
('ramayana-5-33-11', 'en', '"Rama, lovely lady, is the protector of the world and its four classes; he sets the bounds of right conduct and causes others to keep them."', 'veda-app-ai-draft', true),
('ramayana-5-33-12', 'en', '"Radiant and deeply honoured, firm in his vows of self-control, he knows how to repay the good and how to carry out tasks."', 'veda-app-ai-draft', true),
('ramayana-5-33-13', 'en', '"Trained in the science of kingship, he serves the learned; he is well-read, of good character, modest, a scorcher of foes."', 'veda-app-ai-draft', true),
('ramayana-5-33-14', 'en', '"Trained in the Yajur Veda, honoured by those who know the Vedas, he is accomplished in archery, the Vedas and their branches."', 'veda-app-ai-draft', true),
('ramayana-5-33-15', 'en', '"Broad-shouldered, long-armed, with a neck shaped like a conch and a handsome face, collarbones well covered, eyes reddish: so is Rama known among people, O Queen."', 'veda-app-ai-draft', true),
('ramayana-5-33-16', 'en', '"His voice resounds like a kettledrum; his skin is glossy; he is majestic, well-proportioned in every limb, and dark in complexion."', 'veda-app-ai-draft', true),
('ramayana-5-33-17', 'en', '"He is firm in three parts, long in three, even in three, raised in three, has three folds and is bowed in three, with four hollows and three crowns."', 'veda-app-ai-draft', true),
('ramayana-5-33-18', 'en', '"He has four lines, four marks, is four cubits in measure, even in four, with fourteen even pairs, four teeth and four ways of moving."', 'veda-app-ai-draft', true),
('ramayana-5-33-19', 'en', '"He has a great lip, jaw and nose, five glossy features, eight long parts, ten lotus-like features, ten broad ones; he is pervaded by three, has two white features, six raised parts and nine fine ones, and pervades with three."', 'veda-app-ai-draft', true),
('ramayana-5-33-20', 'en', '"Devoted to truth and dharma, glorious, eager to gather and help others, he knows how to judge time and place, and speaks kindly to all."', 'veda-app-ai-draft', true),
('ramayana-5-33-21', 'en', '"His half-brother, Sumitra''s unconquered son, is like him in affection, appearance and virtues."', 'veda-app-ai-draft', true),
('ramayana-5-33-22', 'en', '"Wandering the earth in search of you alone, the two saw the lord of monkeys, who had been deposed by his elder brother."', 'veda-app-ai-draft', true),
('ramayana-5-33-23', 'en', '"On the slopes of Rishyamuka, thick with trees, sat handsome Sugriva, grieving for the wife his brother took from him."', 'veda-app-ai-draft', true),
('ramayana-5-33-24', 'en', '"We serve that king of monkeys, Sugriva, true to his word, whom his elder brother drove from the kingdom."', 'veda-app-ai-draft', true),
('ramayana-5-33-25', 'en', '"Then those two, wearing bark garments and carrying fine bows, came to a lovely spot on Mount Rishyamuka."', 'veda-app-ai-draft', true),
('ramayana-5-33-26', 'en', '"Seeing those two tigers among men with bows, the bull among monkeys leapt to the peak of the mountain in fear."', 'veda-app-ai-draft', true),
('ramayana-5-33-27', 'en', '"Standing on that peak, the monkey king quickly sent me to them."', 'veda-app-ai-draft', true),
('ramayana-5-33-28', 'en', '"At Sugriva''s word, I went with folded hands to those two noble lords, gifted with beauty and fine marks."', 'veda-app-ai-draft', true),
('ramayana-5-33-29', 'en', '"When I understood the truth about them and they were pleased with me, I carried those two bulls among men on my back to that place."', 'veda-app-ai-draft', true),
('ramayana-5-33-30', 'en', '"I introduced them truthfully to the great Sugriva, and as they talked together, deep friendship arose."', 'veda-app-ai-draft', true),
('ramayana-5-33-31', 'en', '"There the two famous lords, of monkeys and of men, comforted each other with the story of what had befallen them."', 'veda-app-ai-draft', true),
('ramayana-5-33-32', 'en', '"Then Lakshmana''s elder brother consoled Sugriva, who had been driven out by his mighty brother Vali over a woman."', 'veda-app-ai-draft', true),
('ramayana-5-33-33', 'en', '"Then Lakshmana told the monkey king Sugriva of the grief that tireless Rama felt at losing you."', 'veda-app-ai-draft', true),
('ramayana-5-33-34', 'en', '"When the monkey king heard Lakshmana''s words, he grew pale, like the sun seized by an eclipse."', 'veda-app-ai-draft', true),
('ramayana-5-33-35', 'en', '"Then the ornaments that adorned your body, which you dropped to the ground as the rakshasa carried you off,"', 'veda-app-ai-draft', true),
('ramayana-5-33-36', 'en', '"the monkey leaders gladly brought them all and showed them to Rama, but they did not know where you had gone."', 'veda-app-ai-draft', true),
('ramayana-5-33-37', 'en', '"I myself gathered them and gave them to Rama; as they jingled and spilled, he was struck senseless."', 'veda-app-ai-draft', true),
('ramayana-5-33-38', 'en', '"Holding those lovely ornaments in his lap, that godlike lord lamented in many ways."', 'veda-app-ai-draft', true),
('ramayana-5-33-39', 'en', '"As he looked at them, weeping and fainting again and again, they fanned the fire of grief in Dasharatha''s son."', 'veda-app-ai-draft', true),
('ramayana-5-33-40', 'en', '"The great soul lay a long time in anguish, and I lifted him up again with difficulty, using many words."', 'veda-app-ai-draft', true),
('ramayana-5-33-41', 'en', '"Having looked at those precious ornaments and shown them again and again, Raghava with Lakshmana entrusted them to Sugriva."', 'veda-app-ai-draft', true),
('ramayana-5-33-42', 'en', '"Not seeing you, noble lady, Raghava burns constantly, like a volcano with a great blazing fire."', 'veda-app-ai-draft', true),
('ramayana-5-33-43', 'en', '"Sleeplessness, grief and worry for you scorch the great Raghava, as fires scorch a fire-house."', 'veda-app-ai-draft', true),
('ramayana-5-33-44', 'en', '"Raghava is shaken by the grief of not seeing you, as a great mountain is shaken by a mighty earthquake."', 'veda-app-ai-draft', true),
('ramayana-5-33-45', 'en', '"Wandering through lovely forests, rivers and springs, he finds no joy, princess, without seeing you."', 'veda-app-ai-draft', true),
('ramayana-5-33-46', 'en', '"That tiger among men, Raghava, will soon win you back, daughter of Janaka, after slaying Ravana with his friends and kin."', 'veda-app-ai-draft', true),
('ramayana-5-33-47', 'en', '"Then Rama and Sugriva together made a pact: to slay Vali and to search for you."', 'veda-app-ai-draft', true),
('ramayana-5-33-48', 'en', '"Then Rama swiftly slew Vali in battle and made Sugriva lord of all the hosts of bears and monkeys."', 'veda-app-ai-draft', true),
('ramayana-5-33-49', 'en', '"So the friendship of Rama and Sugriva came about, O Queen. Know me as Hanuman, their messenger, come here."', 'veda-app-ai-draft', true),
('ramayana-5-33-50', 'en', '"Having regained his kingdom, Sugriva gathered the great monkeys and sent the mighty ones in all ten directions for your sake."', 'veda-app-ai-draft', true),
('ramayana-5-33-51', 'en', '"Ordered by Sugriva, king of monkeys, those powerful ones, like great mountains, set out across the whole earth."', 'veda-app-ai-draft', true),
('ramayana-5-33-52', 'en', '"Splendid Angada, Vali''s mighty son, a tiger among monkeys, set out with a third of the army."', 'veda-app-ai-draft', true),
('ramayana-5-33-53', 'en', '"Lost in the Vindhya, best of mountains, deeply grieving, we let many days and nights go by."', 'veda-app-ai-draft', true),
('ramayana-5-33-54', 'en', '"Hopeless of success, past our deadline, and fearing the monkey king, we resolved to give up our lives."', 'veda-app-ai-draft', true),
('ramayana-5-33-55', 'en', '"Having searched forest strongholds, mountains and springs without finding a trace of the queen, we resolved to give up our lives."', 'veda-app-ai-draft', true),
('ramayana-5-33-56', 'en', '"Sunk in an ocean of grief, Angada lamented your loss, Vaidehi, Vali''s death, our vow to fast to death, and the death of Jatayu."', 'veda-app-ai-draft', true),
('ramayana-5-33-57', 'en', '"As we lay hopeless and ready to die because of our master''s command, a great and mighty bird came, as if to help our cause."', 'veda-app-ai-draft', true),
('ramayana-5-33-58', 'en', '"The king of vultures named Sampati, brother of the vulture king Jatayu, hearing of his brother''s death, spoke in anger."', 'veda-app-ai-draft', true),
('ramayana-5-33-59', 'en', '"''Who killed my younger brother, and where was he slain? I wish you to tell me this, best of monkeys.''"', 'veda-app-ai-draft', true),
('ramayana-5-33-60', 'en', '"Angada told him truly of Jatayu''s great slaying in Janasthana by the fearsome rakshasa, for your sake."', 'veda-app-ai-draft', true),
('ramayana-5-33-61', 'en', '"Grieved to hear of Jatayu''s death, that son of Aruna told us, lovely lady, that you were living in Ravana''s house."', 'veda-app-ai-draft', true),
('ramayana-5-33-62', 'en', '"Hearing Sampati''s joyful words, all of us monkeys, led by Angada, set out, glad and eager to see you."', 'veda-app-ai-draft', true),
('ramayana-5-33-63', 'en', '"Then, seeing the monkey army losing heart before the ocean, I shook off my great fear and leapt a hundred leagues."', 'veda-app-ai-draft', true),
('ramayana-5-33-64', 'en', '"I entered Lanka, swarming with rakshasas, by night; I saw Ravana, and you, worn down with grief."', 'veda-app-ai-draft', true),
('ramayana-5-33-65', 'en', '"I have told you all this just as it happened, blameless lady. Speak to me, O Queen; I am Dasharatha''s son''s messenger."', 'veda-app-ai-draft', true),
('ramayana-5-33-66', 'en', '"Know me, O Queen, as Sugriva''s minister, son of the Wind, who came here for your sake through Rama''s effort."', 'veda-app-ai-draft', true),
('ramayana-5-33-67', 'en', '"Your Kakutstha, best of all who bear arms, is well; and Lakshmana, of fine marks, devoted to serving his elder, is well too."', 'veda-app-ai-draft', true),
('ramayana-5-33-68', 'en', '"Devoted to the welfare of your valiant husband, O Queen, I alone have come here at Sugriva''s word."', 'veda-app-ai-draft', true),
('ramayana-5-33-69', 'en', '"Wandering without companions, able to take any shape, I searched the southern region seeking your trail."', 'veda-app-ai-draft', true),
('ramayana-5-33-70', 'en', '"Fortunately I will remove the grief of the monkey armies who mourn your loss by telling them I have found you."', 'veda-app-ai-draft', true),
('ramayana-5-33-71', 'en', '"Fortunately my leap across the ocean was not in vain, O Queen. Happily I will gain the glory of having found you."', 'veda-app-ai-draft', true),
('ramayana-5-33-72', 'en', '"And mighty Raghava will soon win you back, after slaying Ravana, lord of the rakshasas, with his friends and kin."', 'veda-app-ai-draft', true),
('ramayana-5-33-73', 'en', '"Vaidehi, there is a fine mountain named Kauraja. From there the monkey Kesari went to Mount Gokarna."', 'veda-app-ai-draft', true),
('ramayana-5-33-74', 'en', '"My father, that great monkey, was chosen by the divine sages, and at the holy ford of the lord of rivers he slew the demon Shambasadana."', 'veda-app-ai-draft', true),
('ramayana-5-33-75', 'en', '"In that monkey''s field I was born of the Wind, Maithili, and I am known in the world as Hanuman by my own deeds. I have spoken of your husband''s virtues to win your trust, Vaidehi."', 'veda-app-ai-draft', true),
('ramayana-5-33-76', 'en', 'Reassured by these reasons and fitting tokens, grief-worn Sita accepted him as a true messenger.', 'veda-app-ai-draft', true),
('ramayana-5-33-77', 'en', 'Janaki felt boundless joy, and from her eyes with curved lashes she shed tears of happiness.', 'veda-app-ai-draft', true),
('ramayana-5-33-78', 'en', 'Her lovely face, with large eyes white and copper-tinged, shone like the moon freed from Rahu, and she was sure he was the monkey Hanuman and no other.', 'veda-app-ai-draft', true),
('ramayana-5-33-79', 'en', 'Then Hanuman gave a further reply to the lovely lady.', 'veda-app-ai-draft', true),
('ramayana-5-33-80', 'en', '"When the demon Shambasadana was slain in battle by that great monkey at the great sages'' urging, I was born of the Wind, Maithili, a monkey like him in power."', 'veda-app-ai-draft', true),
('ramayana-5-34-1', 'en', 'Once more the radiant Hanuman, son of the Wind, spoke humbly, to give Sita proof.', 'veda-app-ai-draft', true),
('ramayana-5-34-2', 'en', '"I am a monkey, blessed lady, messenger of wise Rama. Look, O Queen, at this ring marked with Rama''s name. Take comfort; bless you, your sorrows are nearly over."', 'veda-app-ai-draft', true),
('ramayana-5-34-3', 'en', 'Taking her husband''s ring and gazing at it, Janaki was as glad as if she had met her husband himself.', 'veda-app-ai-draft', true),
('ramayana-5-34-4', 'en', 'Her lovely face, with large eyes white and copper-tinged, grew radiant with joy, like the moon freed from Rahu.', 'veda-app-ai-draft', true),
('ramayana-5-34-5', 'en', 'Then the modest young woman, delighted by her husband''s message and pleased with the good news, praised the great monkey.', 'veda-app-ai-draft', true),
('ramayana-5-34-6', 'en', '"You are brave, capable and wise, best of monkeys, for you alone have overcome this rakshasa stronghold."', 'veda-app-ai-draft', true),
('ramayana-5-34-7', 'en', '"The ocean, a hundred leagues wide, home of sea monsters, you crossed as if it were a calf''s hoofprint, worthy of praise for your valour."', 'veda-app-ai-draft', true),
('ramayana-5-34-8', 'en', '"I do not think you an ordinary monkey, bull among monkeys, for you have no fear of Ravana, nor any alarm."', 'veda-app-ai-draft', true),
('ramayana-5-34-9', 'en', '"You are worthy to speak with me, best of monkeys, if you were sent by Rama, who knows himself."', 'veda-app-ai-draft', true),
('ramayana-5-34-10', 'en', '"For invincible Rama would not send an untested person, especially to me, without knowing his valour."', 'veda-app-ai-draft', true),
('ramayana-5-34-11', 'en', '"Thank heaven righteous Rama, lover of dharma, is well, and mighty Lakshmana, joy of Sumitra."', 'veda-app-ai-draft', true),
('ramayana-5-34-12', 'en', '"If Kakutstha is well, why does he not burn the sea-girdled earth in anger, like the fire at the end of an age?"', 'veda-app-ai-draft', true),
('ramayana-5-34-13', 'en', '"Or perhaps those two are able to subdue even the gods, and I think it is only my sorrows that do not change."', 'veda-app-ai-draft', true),
('ramayana-5-34-14', 'en', '"Does Rama suffer? Is he not tormented? Is that best of men doing what must be done next?"', 'veda-app-ai-draft', true),
('ramayana-5-34-15', 'en', '"Is the prince not dejected or confused? Is he not bewildered in his tasks? Does he do what a man must do?"', 'veda-app-ai-draft', true),
('ramayana-5-34-16', 'en', '"Does that scorcher of foes, seeking victory and friendly to his allies, use the twofold and threefold means of statecraft?"', 'veda-app-ai-draft', true),
('ramayana-5-34-17', 'en', '"Does he win friends, and do friends come to him? Does he have good friends, and is he honoured by them?"', 'veda-app-ai-draft', true),
('ramayana-5-34-18', 'en', '"Does the prince seek the gods'' grace? Does he rely on both human effort and fate?"', 'veda-app-ai-draft', true),
('ramayana-5-34-19', 'en', '"Has Raghava''s love for me faded because I am far away? Will he free me from this misery, monkey?"', 'veda-app-ai-draft', true),
('ramayana-5-34-20', 'en', '"Always used to comfort, unused to hardship, does Rama not sink under this great sorrow?"', 'veda-app-ai-draft', true),
('ramayana-5-34-21', 'en', '"Does he often hear good news of Kausalya, Sumitra and Bharata?"', 'veda-app-ai-draft', true),
('ramayana-5-34-22', 'en', '"Is honourable Raghava grieving for me? Is his mind on nothing else? Will he rescue me?"', 'veda-app-ai-draft', true),
('ramayana-5-34-23', 'en', '"Will Bharata, who loves his brother, send a fearsome army guarded by ministers, for my sake?"', 'veda-app-ai-draft', true),
('ramayana-5-34-24', 'en', '"Will glorious Sugriva, lord of monkeys, come for me with heroic monkeys armed with teeth and claws?"', 'veda-app-ai-draft', true),
('ramayana-5-34-25', 'en', '"Will brave Lakshmana, skilled in weapons, scatter the rakshasas with a net of arrows?"', 'veda-app-ai-draft', true),
('ramayana-5-34-26', 'en', '"Will I soon see Ravana and his friends slain in battle by Rama with a terrible weapon?"', 'veda-app-ai-draft', true),
('ramayana-5-34-27', 'en', '"Is his golden face, fragrant as a lotus, not withering with grief without me, like a lotus in the sun when the water dries?"', 'veda-app-ai-draft', true),
('ramayana-5-34-28', 'en', '"He felt no pain, fear or grief when he gave up the kingdom for dharma and led me on foot into the forest. Does he keep that courage in his heart now?"', 'veda-app-ai-draft', true),
('ramayana-5-34-29', 'en', '"Neither his mother, nor his father, nor anyone else is dearer to him than me or equal to me. Messenger, I wish to live only as long as I hear news of my beloved."', 'veda-app-ai-draft', true),
('ramayana-5-34-30', 'en', 'Having spoken these meaningful, sweet words to the monkey chief, the lovely queen fell silent, longing to hear more delightful words about Rama.', 'veda-app-ai-draft', true),
('ramayana-5-34-31', 'en', 'Hearing Sita''s words, Hanuman of fearsome valour placed his joined palms on his head and replied.', 'veda-app-ai-draft', true),
('ramayana-5-34-32', 'en', '"Lotus-eyed Rama does not know you are here. As soon as he hears my words, Raghava will come quickly."', 'veda-app-ai-draft', true),
('ramayana-5-34-33', 'en', '"Leading a great army thronged with monkeys and bears, and halting the unshakeable ocean with floods of arrows, Kakutstha will make Lanka a city emptied of rakshasas."', 'veda-app-ai-draft', true),
('ramayana-5-34-34', 'en', '"If death itself, or the gods and demons, stand in Rama''s way, he will slay them too."', 'veda-app-ai-draft', true),
('ramayana-5-34-35', 'en', '"Flooded with grief at not seeing you, noble lady, Rama finds no peace, like an elephant attacked by a lion."', 'veda-app-ai-draft', true),
('ramayana-5-34-36', 'en', '"I swear to you, O Queen, by Mount Dardara, by roots and fruits, by Malaya, Vindhya, Meru and Mandara,"', 'veda-app-ai-draft', true),
('ramayana-5-34-37', 'en', '"that you will see Rama''s face, with fine eyes, lips red as bimba fruit and lovely earrings, like the full moon risen."', 'veda-app-ai-draft', true),
('ramayana-5-34-38', 'en', '"Soon, Vaidehi, you will see Rama on Mount Prasravana, like Indra seated on the summit of heaven."', 'veda-app-ai-draft', true),
('ramayana-5-34-39', 'en', '"Raghava eats no meat, nor does he take honey; he eats only simple forest food, well prepared, at the fifth part of the day."', 'veda-app-ai-draft', true),
('ramayana-5-34-40', 'en', '"His mind so fixed on you, Raghava does not even brush gnats, mosquitoes, insects or crawling things from his body."', 'veda-app-ai-draft', true),
('ramayana-5-34-41', 'en', '"Rama is always lost in thought and always in grief. He thinks of nothing else, overcome by longing."', 'veda-app-ai-draft', true),
('ramayana-5-34-42', 'en', '"Rama is always sleepless, and even when that best of men sleeps, he wakes up softly calling ''Sita''."', 'veda-app-ai-draft', true),
('ramayana-5-34-43', 'en', '"Seeing a fruit or flower or anything else a woman would like, he sighs again and again, ''Ah, beloved,'' and speaks to you."', 'veda-app-ai-draft', true),
('ramayana-5-34-44', 'en', '"Always burning with grief, O Queen, always calling ''Sita'', the great prince, firm in his vows, strives only to win you back."', 'veda-app-ai-draft', true),
('ramayana-5-34-45', 'en', 'Freed of grief by hearing of Rama, yet grieving as Rama grieved, Vaidehi was like an autumn night with a moon still veiled by the last clouds.', 'veda-app-ai-draft', true),
('ramayana-5-35-1', 'en', 'Hearing his words, moon-faced Sita spoke to Hanuman words full of dharma and sense.', 'veda-app-ai-draft', true),
('ramayana-5-35-2', 'en', '"Monkey, your words are nectar mixed with poison: that Rama thinks of nothing else, and that he is lost in grief."', 'veda-app-ai-draft', true),
('ramayana-5-35-3', 'en', '"Whether in great wealth or terrible misfortune, fate drags a person along as if bound by a rope."', 'veda-app-ai-draft', true),
('ramayana-5-35-4', 'en', '"Surely fate cannot be avoided by living beings, best of monkeys. See how Lakshmana, Rama and I are all bewildered by misfortune."', 'veda-app-ai-draft', true),
('ramayana-5-35-5', 'en', '"When will Raghava reach the far shore of this grief, like a weary swimmer in the ocean whose boat is wrecked?"', 'veda-app-ai-draft', true),
('ramayana-5-35-6', 'en', '"When will my husband, having destroyed the rakshasas, slain Ravana and uprooted Lanka, see me?"', 'veda-app-ai-draft', true),
('ramayana-5-35-7', 'en', '"Tell him to hurry, for I will live only until this year is complete."', 'veda-app-ai-draft', true),
('ramayana-5-35-8', 'en', '"This is the tenth month; two remain, monkey, of the term the cruel Ravana set for me."', 'veda-app-ai-draft', true),
('ramayana-5-35-9', 'en', '"His brother Vibhishana earnestly urged him to return me, but he would not agree."', 'veda-app-ai-draft', true),
('ramayana-5-35-10', 'en', '"Ravana does not wish to give me back. Death, under time''s power, is seeking Ravana in battle."', 'veda-app-ai-draft', true),
('ramayana-5-35-11', 'en', '"Vibhishana''s eldest daughter, named Anala, told me this herself, sent by her mother."', 'veda-app-ai-draft', true),
('ramayana-5-35-12', 'en', '"There is a wise and learned rakshasa named Avindhya, steady, good-natured, old, and highly respected by Ravana."', 'veda-app-ai-draft', true),
('ramayana-5-35-13', 'en', '"He warned Ravana that the rakshasas'' destruction at Rama''s hands was near, but the wicked one does not listen even to his good advice."', 'veda-app-ai-draft', true),
('ramayana-5-35-14', 'en', '"I hope, best of monkeys, that my husband will soon win me back, for my heart is pure and he has many virtues."', 'veda-app-ai-draft', true),
('ramayana-5-35-15', 'en', '"Energy, manliness, strength, kindness, gratitude, valour and power are all in Raghava."', 'veda-app-ai-draft', true),
('ramayana-5-35-16', 'en', '"He slew fourteen thousand rakshasas in Janasthana without his brother. What enemy would not fear him?"', 'veda-app-ai-draft', true),
('ramayana-5-35-17', 'en', '"That bull among men cannot be shaken by misfortunes. I know his greatness, as Shachi knows Indra''s."', 'veda-app-ai-draft', true),
('ramayana-5-35-18', 'en', '"Monkey, the hero Rama, a sun whose rays are nets of arrows, will dry up the water that is the rakshasa enemy."', 'veda-app-ai-draft', true),
('ramayana-5-35-19', 'en', 'As she spoke thus, worn with grief for Rama, her face full of tears, the monkey Hanuman spoke to her.', 'veda-app-ai-draft', true),
('ramayana-5-35-20', 'en', '"As soon as he hears my words, Raghava will come quickly, leading a great army thronged with monkeys and bears."', 'veda-app-ai-draft', true),
('ramayana-5-35-21', 'en', '"Or I will free you from the rakshasa today, from this misery. Climb on my back, blameless lady."', 'veda-app-ai-draft', true),
('ramayana-5-35-22', 'en', '"With you on my back I will cross the ocean. I have strength to carry even Lanka with Ravana in it."', 'veda-app-ai-draft', true),
('ramayana-5-35-23', 'en', '"Today, Maithili, I will bring you to Raghava on Mount Prasravana, as fire carries an offering to Indra."', 'veda-app-ai-draft', true),
('ramayana-5-35-24', 'en', '"Today, Vaidehi, you will see Raghava with Lakshmana, resolute like Vishnu in slaying demons."', 'veda-app-ai-draft', true),
('ramayana-5-35-25', 'en', '"You will see that mighty one, eager to see you, seated in his hermitage like Indra on the head of the king of elephants."', 'veda-app-ai-draft', true),
('ramayana-5-35-26', 'en', '"Climb on my back, O Queen; do not hesitate, lovely one. Seek union with Rama, as Rohini with the moon."', 'veda-app-ai-draft', true),
('ramayana-5-35-27', 'en', '"Like one speaking with the moon, like Suvarchala with the sun, climb on my back and cross the great ocean of the sky."', 'veda-app-ai-draft', true),
('ramayana-5-35-28', 'en', '"When I set out carrying you away from here, my lady, none of Lanka''s people will be able to follow my path."', 'veda-app-ai-draft', true),
('ramayana-5-35-29', 'en', '"Just as I came here, so surely I will go, carrying you through the sky. See, Vaidehi!"', 'veda-app-ai-draft', true),
('ramayana-5-35-30', 'en', 'Hearing these wonderful words from the best of monkeys, Maithili, thrilled with joy and amazement, spoke to Hanuman.', 'veda-app-ai-draft', true),
('ramayana-5-35-31', 'en', '"Hanuman, how can you wish to carry me so far? I think this is just your monkey nature, leader of monkeys."', 'veda-app-ai-draft', true),
('ramayana-5-35-32', 'en', '"How can you, with so small a body, wish to take me from here to my husband, lord of men, bull among monkeys?"', 'veda-app-ai-draft', true),
('ramayana-5-35-33', 'en', 'Hearing Sita''s words, splendid Hanuman, son of the Wind, thought he had met with a new slight.', 'veda-app-ai-draft', true),
('ramayana-5-35-34', 'en', '"This dark-eyed lady does not know my strength or power. So let Vaidehi see the form I can take at will."', 'veda-app-ai-draft', true),
('ramayana-5-35-35', 'en', 'Thinking thus, Hanuman, best of monkeys and crusher of foes, showed Vaidehi his true form.', 'veda-app-ai-draft', true),
('ramayana-5-35-36', 'en', 'The wise bull among monkeys leapt down from the tree and began to grow, to give Sita proof.', 'veda-app-ai-draft', true),
('ramayana-5-35-37', 'en', 'Like Meru or Mandara, blazing like fire, the bull among monkeys stood before Sita.', 'veda-app-ai-draft', true),
('ramayana-5-35-38', 'en', 'The mighty monkey, like a mountain, red-faced, with teeth and nails like thunderbolts, fearsome, said to Vaidehi:', 'veda-app-ai-draft', true),
('ramayana-5-35-39', 'en', '"I have the strength to carry off this Lanka, with its mountains, forests, towers, walls and gates, and its lord too."', 'veda-app-ai-draft', true),
('ramayana-5-35-40', 'en', '"So settle your mind, O Queen; enough of doubt. Free Raghava and Lakshmana from grief, Vaidehi."', 'veda-app-ai-draft', true),
('ramayana-5-35-41', 'en', 'Seeing him like a mountain, Janaka''s daughter, with eyes large as lotus petals, spoke to the Wind''s own son.', 'veda-app-ai-draft', true),
('ramayana-5-35-42', 'en', '"I know your strength and might, great monkey, your speed like the wind''s and your wondrous splendour like fire''s."', 'veda-app-ai-draft', true),
('ramayana-5-35-43', 'en', '"How could any ordinary being reach this land, across the boundless ocean, chief of monkeys?"', 'veda-app-ai-draft', true),
('ramayana-5-35-44', 'en', '"I know your power to travel and to carry me. Yet one must quickly weigh how the task can truly succeed."', 'veda-app-ai-draft', true),
('ramayana-5-35-45', 'en', '"But it is not right for me to go with you, best of monkeys. Your speed, like the wind''s, might make me faint."', 'veda-app-ai-draft', true),
('ramayana-5-35-46', 'en', '"Hanging in the sky high above the ocean, I might fall from your back in fear as you rush along."', 'veda-app-ai-draft', true),
('ramayana-5-35-47', 'en', '"And falling into the ocean full of whales, crocodiles and fish, I would helplessly become choice food for sea creatures."', 'veda-app-ai-draft', true),
('ramayana-5-35-48', 'en', '"I cannot go with you, destroyer of foes. Carrying a woman, you too would surely be in danger."', 'veda-app-ai-draft', true),
('ramayana-5-35-49', 'en', '"Seeing me carried off, the fearsome rakshasas, ordered by wicked Ravana, would pursue us."', 'veda-app-ai-draft', true),
('ramayana-5-35-50', 'en', '"Surrounded by those heroes with spears and hammers in hand, you would be in peril, hero, burdened with me."', 'veda-app-ai-draft', true),
('ramayana-5-35-51', 'en', '"Many armed rakshasas in the sky, and you unarmed: how could you fight and also protect me?"', 'veda-app-ai-draft', true),
('ramayana-5-35-52', 'en', '"While you fought those cruel rakshasas, I might fall from your back in terror, best of monkeys."', 'veda-app-ai-draft', true),
('ramayana-5-35-53', 'en', '"Or those great, fearsome, mighty rakshasas might somehow defeat you in battle, best of monkeys."', 'veda-app-ai-draft', true),
('ramayana-5-35-54', 'en', '"Or while you were fighting, turned away, I might fall, and the wicked rakshasas would seize me and take me back."', 'veda-app-ai-draft', true),
('ramayana-5-35-55', 'en', '"They might snatch me from your hands or even kill me, for victory and defeat in battle are never certain."', 'veda-app-ai-draft', true),
('ramayana-5-35-56', 'en', '"Or I might die, threatened by the rakshasas, and then your effort, best of monkeys, would be in vain."', 'veda-app-ai-draft', true),
('ramayana-5-35-57', 'en', '"Even if you could kill all the rakshasas, Raghava''s glory would suffer if they were slain by you."', 'veda-app-ai-draft', true),
('ramayana-5-35-58', 'en', '"Or the rakshasas might take me and hide me somewhere secret, where neither the monkeys nor Raghava could find me."', 'veda-app-ai-draft', true),
('ramayana-5-35-59', 'en', '"Then your effort for my sake would be useless. But if Rama comes with you, great good will come of it."', 'veda-app-ai-draft', true),
('ramayana-5-35-60', 'en', '"The life of great Raghava, of his brothers, and of your royal house too, mighty-armed one, depends on me."', 'veda-app-ai-draft', true),
('ramayana-5-35-61', 'en', '"If they lost hope for me, those two, worn with grief, would give up their lives along with all the bears and monkeys."', 'veda-app-ai-draft', true),
('ramayana-5-35-62', 'en', '"And, out of devotion to my husband, monkey, I do not wish to touch the body of anyone but Rama, even with my foot."', 'veda-app-ai-draft', true),
('ramayana-5-35-63', 'en', '"That I was touched by Ravana was by force; helpless, without my lord, powerless, what could I do?"', 'veda-app-ai-draft', true),
('ramayana-5-35-64', 'en', '"If Rama slays the ten-headed one here with his rakshasas and takes me from here, that would be worthy of him."', 'veda-app-ai-draft', true),
('ramayana-5-35-65', 'en', '"I have heard of and seen the feats of that great soul who crushes in battle. Neither gods, gandharvas, serpents nor rakshasas equal Rama in war."', 'veda-app-ai-draft', true),
('ramayana-5-35-66', 'en', '"Seeing him in battle with his bright bow, mighty, valiant as Indra, with Lakshmana, who could withstand Raghava, like a blazing fire fanned by wind?"', 'veda-app-ai-draft', true),
('ramayana-5-35-67', 'en', '"Who could withstand Raghava and Lakshmana in battle, crusher of foes, standing like a maddened elephant of the quarters, flashing arrows like the sun at the end of an age?"', 'veda-app-ai-draft', true),
('ramayana-5-35-68', 'en', '"So, best of monkeys, bring my husband here soon with Lakshmana and the troop-leaders. Make me happy, chief of monkeys, long worn with grief for Rama."', 'veda-app-ai-draft', true),
('ramayana-5-36-1', 'en', 'Then the tiger among monkeys, skilled in speech and pleased by her words, spoke to Sita.', 'veda-app-ai-draft', true),
('ramayana-5-36-2', 'en', '"What you have said is fitting, lovely Queen, worthy of a woman''s nature and the modesty of the virtuous."', 'veda-app-ai-draft', true),
('ramayana-5-36-3', 'en', '"It is true a woman could not well cross the wide ocean, a hundred leagues long, riding on me."', 'veda-app-ai-draft', true),
('ramayana-5-36-4', 'en', '"And the second reason you give, modest one, that you should not be touched by anyone but Rama, Janaki,"', 'veda-app-ai-draft', true),
('ramayana-5-36-5', 'en', '"this is worthy of you, wife of that great soul. Who else but you, O Queen, would speak such words?"', 'veda-app-ai-draft', true),
('ramayana-5-36-6', 'en', '"Kakutstha will hear everything, fully, that you have done and said before me, O Queen."', 'veda-app-ai-draft', true),
('ramayana-5-36-7', 'en', '"For many reasons, O Queen, wishing to please Rama, with a heart moved by affection, I said this."', 'veda-app-ai-draft', true),
('ramayana-5-36-8', 'en', '"Because Lanka is hard to enter and the ocean hard to cross, and because I am able, I made this offer."', 'veda-app-ai-draft', true),
('ramayana-5-36-9', 'en', '"I wished to bring you to Rama today itself; I said it out of love and devotion to my master, not otherwise."', 'veda-app-ai-draft', true),
('ramayana-5-36-10', 'en', '"If you do not wish to go with me, blameless lady, give me a token that Raghava will recognise."', 'veda-app-ai-draft', true),
('ramayana-5-36-11', 'en', 'Asked thus by Hanuman, Sita, like a daughter of the gods, spoke softly, her words choked with tears.', 'veda-app-ai-draft', true),
('ramayana-5-36-12', 'en', '"Tell my beloved this best of tokens: once, at the north-east foot of Mount Chitrakuta,"', 'veda-app-ai-draft', true),
('ramayana-5-36-13', 'en', '"while I was living in a hermitage of ascetics, rich in roots, fruits and water, in that holy place near the Mandakini,"', 'veda-app-ai-draft', true),
('ramayana-5-36-14', 'en', '"after wandering in its groves fragrant with many flowers, still wet from the water, I sat down beside you."', 'veda-app-ai-draft', true),
('ramayana-5-36-15', 'en', '"Later Bharata''s elder brother fell asleep resting on my lap."', 'veda-app-ai-draft', true),
('ramayana-5-36-16', 'en', '"Then a crow, greedy for food, kept pecking at me. I raised a clod of earth and tried to drive the crow away."', 'veda-app-ai-draft', true),
('ramayana-5-36-17', 'en', '"The crow, wounding me, kept hiding nearby; greedy for food, that eater of offerings would not stop."', 'veda-app-ai-draft', true),
('ramayana-5-36-18', 'en', '"As I, angry at the bird, tugged at my girdle and my garment slipped, you saw me then."', 'veda-app-ai-draft', true),
('ramayana-5-36-19', 'en', '"You laughed at me, and I was angry and embarrassed. Wounded by the greedy crow, I came to you."', 'veda-app-ai-draft', true),
('ramayana-5-36-20', 'en', '"Tired, I sat on your lap again as you sat, and though I was cross, you, smiling, comforted me."', 'veda-app-ai-draft', true),
('ramayana-5-36-21', 'en', '"My face full of tears, softly wiping my eyes, you saw, my lord, that I had been provoked by the crow."', 'veda-app-ai-draft', true),
('ramayana-5-36-22', 'en', '"Hissing like an angry snake, you said: ''Who has wounded you near the heart? Who is playing with an angry five-headed serpent?''"', 'veda-app-ai-draft', true),
('ramayana-5-36-23', 'en', '"Looking around, you saw that crow facing me, its sharp claws stained with blood."', 'veda-app-ai-draft', true),
('ramayana-5-36-24', 'en', '"That crow, it seems, was the son of Indra, best of birds, moving swiftly through the earth''s regions, swift as the wind."', 'veda-app-ai-draft', true),
('ramayana-5-36-25', 'en', '"Then, wisest of the wise, mighty-armed one, eyes rolling in anger, you resolved to punish the crow severely."', 'veda-app-ai-draft', true),
('ramayana-5-36-26', 'en', '"Taking a blade of darbha grass from the mat, you charged it with the Brahma weapon, and it blazed toward the bird like the fire of doom."', 'veda-app-ai-draft', true),
('ramayana-5-36-27', 'en', '"You hurled that blazing blade at the crow. Pursued by it, the crow fled in many directions, seeking protection, and wandered through the whole world."', 'veda-app-ai-draft', true),
('ramayana-5-36-28', 'en', '"Abandoned by his father, by all the gods and great sages, having wandered the three worlds, he came to you alone for refuge."', 'veda-app-ai-draft', true),
('ramayana-5-36-29', 'en', '"Though he deserved death, Kakutstha, you, the giver of refuge, protected him with compassion when he fell to the ground seeking shelter. Finding no peace anywhere, he had come to you."', 'veda-app-ai-draft', true),
('ramayana-5-36-30', 'en', '"To him, exhausted and despairing, you said: ''The Brahma weapon cannot be made fruitless; tell me what it should strike.''"', 'veda-app-ai-draft', true),
('ramayana-5-36-31', 'en', '"Then it struck the crow''s right eye."', 'veda-app-ai-draft', true),
('ramayana-5-36-32', 'en', '"Bowing to you and to King Dasharatha, released by you, hero, he went back to his home."', 'veda-app-ai-draft', true),
('ramayana-5-36-33', 'en', '"For my sake you used the Brahma weapon even on a mere crow. Why, lord of the earth, do you forgive the one who took me from you?"', 'veda-app-ai-draft', true),
('ramayana-5-36-34', 'en', '"So show great energy and pity for me, bull among men. I heard from you that kindness is the highest dharma."', 'veda-app-ai-draft', true),
('ramayana-5-36-35', 'en', '"I know you are mighty, energetic and strong, boundless, unshakeable, deep as the ocean, lord of the sea-girt earth, like Indra."', 'veda-app-ai-draft', true),
('ramayana-5-36-36', 'en', '"Being thus the best of those who know weapons, strong and courageous, why, Raghava, do you not use your weapons on the rakshasas?"', 'veda-app-ai-draft', true),
('ramayana-5-36-37', 'en', '"Neither serpents nor gandharvas, demons nor storm-gods can withstand Rama''s force in battle."', 'veda-app-ai-draft', true),
('ramayana-5-36-38', 'en', '"If that mighty one has any care for me, why does he not destroy the rakshasas with sharp arrows?"', 'veda-app-ai-draft', true),
('ramayana-5-36-39', 'en', '"Or why does Lakshmana, scorcher of foes, taking his brother''s command, not rescue me, that mighty hero?"', 'veda-app-ai-draft', true),
('ramayana-5-36-40', 'en', '"If those two tigers among men, splendid as Wind and Indra, invincible even to the gods, why do they neglect me?"', 'veda-app-ai-draft', true),
('ramayana-5-36-41', 'en', '"Surely I must have some great wrong of my own, since those two, though able, do not look after me."', 'veda-app-ai-draft', true),
('ramayana-5-36-42', 'en', '"Ask after the welfare, for my sake, of him whom high-minded Kausalya bore as lord of the world, and bow your head to him."', 'veda-app-ai-draft', true),
('ramayana-5-36-43', 'en', '"Garlands, all jewels, beloved fine women, and lordship hard to find even on the wide earth,"', 'veda-app-ai-draft', true),
('ramayana-5-36-44', 'en', '"honouring and pleasing his father and mother, he followed Rama into exile, he through whom Sumitra is blessed in her son, that righteous one, giving up the highest comfort."', 'veda-app-ai-draft', true),
('ramayana-5-36-45', 'en', '"He follows Kakutstha, guarding his brother in the forest, lion-shouldered, mighty-armed, high-minded, handsome."', 'veda-app-ai-draft', true),
('ramayana-5-36-46', 'en', '"He treats Rama like a father and me like a mother. The hero Lakshmana did not know when I was carried off."', 'veda-app-ai-draft', true),
('ramayana-5-36-47', 'en', '"He serves elders, is splendid, capable, not talkative, a prince most dear, like my father-in-law."', 'veda-app-ai-draft', true),
('ramayana-5-36-48', 'en', '"Lakshmana, Rama''s brother, has always been dearer to him than I am. Whatever burden he is given, that mighty one carries."', 'veda-app-ai-draft', true),
('ramayana-5-36-49', 'en', '"Seeing him, Raghava no longer misses his late father. Ask after his welfare for me in my words: Lakshmana, always gentle, pure, able and dear to Rama."', 'veda-app-ai-draft', true),
('ramayana-5-36-50', 'en', '"And tell my lord, the hero Rama, again and again: I will hold on to life for a month, son of Dasharatha. Beyond that month I will not live; I tell you this truly."', 'veda-app-ai-draft', true),
('ramayana-5-36-51', 'en', '"Confined by wicked Ravana through deceit, I should be rescued by you, hero, as Kaushiki was from the underworld."', 'veda-app-ai-draft', true),
('ramayana-5-36-52', 'en', 'Then, untying from her garment her lovely divine crest-jewel, Sita gave it to Hanuman, saying, "Give this to Raghava."', 'veda-app-ai-draft', true),
('ramayana-5-36-53', 'en', 'The hero took that peerless jewel and slipped it onto his finger, for his arm was too big for it to go further.', 'veda-app-ai-draft', true),
('ramayana-5-36-54', 'en', 'Taking the jewel, the best of monkeys bowed, walked around Sita respectfully, and stood humbly at her side.', 'veda-app-ai-draft', true),
('ramayana-5-36-55', 'en', 'Filled with great joy at having found Sita, his heart went to Rama while his body stayed there.', 'veda-app-ai-draft', true),
('ramayana-5-36-56', 'en', 'Holding that precious jewel, which the princess had kept by her own power, he felt like one released after being shaken by the wind on a great mountain, and turned back, glad at heart.', 'veda-app-ai-draft', true),
('ramayana-5-37-1', 'en', 'Having given the jewel, Sita said to Hanuman: "This token is well known to Rama."', 'veda-app-ai-draft', true),
('ramayana-5-37-2', 'en', '"Seeing this jewel, the hero Rama will remember three people: my mother, me, and King Dasharatha."', 'veda-app-ai-draft', true),
('ramayana-5-37-3', 'en', '"Spurred on to further effort, best of monkeys, consider what should come next in this undertaking."', 'veda-app-ai-draft', true),
('ramayana-5-37-4', 'en', '"In carrying out this task you are the one to rely on, best of monkeys. Think what effort will end my sorrows."', 'veda-app-ai-draft', true),
('ramayana-5-37-5', 'en', 'Promising, "So be it," Hanuman of fearsome valour bowed his head to Vaidehi and prepared to go.', 'veda-app-ai-draft', true),
('ramayana-5-37-6', 'en', 'Knowing the monkey was setting out, the queen Maithili spoke in a voice choked with tears.', 'veda-app-ai-draft', true),
('ramayana-5-37-7', 'en', '"Hanuman, give my greetings to Rama and Lakshmana together, to Sugriva and his ministers, and to all the elder monkeys."', 'veda-app-ai-draft', true),
('ramayana-5-37-8', 'en', '"Arrange it so that the mighty-armed Raghava rescues me from this flood of sorrow."', 'veda-app-ai-draft', true),
('ramayana-5-37-9', 'en', '"Tell famous Rama in such a way that he finds me still alive, Hanuman, and earn merit by your words."', 'veda-app-ai-draft', true),
('ramayana-5-37-10', 'en', '"Hearing the words I have spoken, full of resolve, Dasharatha''s son''s courage will grow to win me back."', 'veda-app-ai-draft', true),
('ramayana-5-37-11', 'en', '"As soon as Raghava hears my message from you, the hero will rightly plan his course of valour."', 'veda-app-ai-draft', true),
('ramayana-5-37-12', 'en', 'Hearing Sita''s words, Hanuman, son of the Wind, placed his joined palms on his head and replied.', 'veda-app-ai-draft', true),
('ramayana-5-37-13', 'en', '"Kakutstha will come quickly, surrounded by the best of monkeys and bears, and conquering his foes in battle, he will remove your sorrow."', 'veda-app-ai-draft', true),
('ramayana-5-37-14', 'en', '"I see no one among mortals, gods or demons who could stand before him when he looses his arrows."', 'veda-app-ai-draft', true),
('ramayana-5-37-15', 'en', '"He could withstand even the sun, the rain-god, or Yama, son of Vivasvan, in battle, especially for your sake."', 'veda-app-ai-draft', true),
('ramayana-5-37-16', 'en', '"He seeks to rule the earth to the ocean''s edge, and Rama''s victory will be because of you, joy of Janaka."', 'veda-app-ai-draft', true),
('ramayana-5-37-17', 'en', 'Hearing his true and well-spoken words, Janaki honoured them greatly and said this.', 'veda-app-ai-draft', true),
('ramayana-5-37-18', 'en', 'Then, looking again and again at him as he set out, Sita, out of affection, spoke loving words about her husband.', 'veda-app-ai-draft', true),
('ramayana-5-37-19', 'en', '"If you think fit, hero, stay one day, tamer of foes, rest in some hidden place, and go tomorrow."', 'veda-app-ai-draft', true),
('ramayana-5-37-20', 'en', '"Your presence, mighty one, might give me, unlucky as I am, a moment''s release from this great grief."', 'veda-app-ai-draft', true),
('ramayana-5-37-21', 'en', '"Once you have gone, tiger among monkeys, until you return, even my life will surely be in doubt."', 'veda-app-ai-draft', true),
('ramayana-5-37-22', 'en', '"Grief at not seeing you will torment me further, monkey, burning me who am already struck by sorrow upon sorrow."', 'veda-app-ai-draft', true),
('ramayana-5-37-23', 'en', '"And this great doubt, hero, stands before me about your allies, the monkeys and bears, lord of monkeys:"', 'veda-app-ai-draft', true),
('ramayana-5-37-24', 'en', '"How will those armies of monkeys and bears, or those two princes, cross the impassable ocean?"', 'veda-app-ai-draft', true),
('ramayana-5-37-25', 'en', '"Only three beings could leap the ocean here: Garuda, you, or the Wind."', 'veda-app-ai-draft', true),
('ramayana-5-37-26', 'en', '"So in this hard undertaking, hero, what solution do you see? You are the best of those who know how to get things done."', 'veda-app-ai-draft', true),
('ramayana-5-37-27', 'en', '"Surely you alone are enough to accomplish this task, slayer of enemy heroes; your strength brings you glory."', 'veda-app-ai-draft', true),
('ramayana-5-37-28', 'en', '"But if Rama defeats Ravana in battle with all his forces and returns victorious to his city with me, that would bring me honour."', 'veda-app-ai-draft', true),
('ramayana-5-37-29', 'en', '"If Kakutstha fills Lanka with his armies and takes me away, crushing the enemy host, that would be worthy of him."', 'veda-app-ai-draft', true),
('ramayana-5-37-30', 'en', '"So arrange it, you, that things happen in a way worthy of the valour of that great soul, hero in battle."', 'veda-app-ai-draft', true),
('ramayana-5-37-31', 'en', 'Hearing her meaningful, affectionate and well-reasoned words, Hanuman gave his final reply.', 'veda-app-ai-draft', true),
('ramayana-5-37-32', 'en', '"O Queen, Sugriva, lord of the armies of monkeys and bears, best of leapers, full of courage, is determined to act for you."', 'veda-app-ai-draft', true),
('ramayana-5-37-33', 'en', '"He will come quickly, Vaidehi, surrounded by millions upon millions of monkeys, to destroy the rakshasas."', 'veda-app-ai-draft', true),
('ramayana-5-37-34', 'en', '"Under his command are monkeys full of valour, courage and great strength, swift as thought."', 'veda-app-ai-draft', true),
('ramayana-5-37-35', 'en', '"Their movement is not stopped above, below or sideways, and those of boundless energy never falter at great tasks."', 'veda-app-ai-draft', true),
('ramayana-5-37-36', 'en', '"Many times those energetic ones have circled the earth with its oceans and mountains, following the path of the wind."', 'veda-app-ai-draft', true),
('ramayana-5-37-37', 'en', '"There are forest-dwellers there greater than me and equal to me; none near Sugriva is lesser than me."', 'veda-app-ai-draft', true),
('ramayana-5-37-38', 'en', '"If I have come here, how much more can those mighty ones? For the best are not sent as messengers; others are sent."', 'veda-app-ai-draft', true),
('ramayana-5-37-39', 'en', '"So enough of anguish, O Queen; let your grief pass. In a single leap the monkey leaders will reach Lanka."', 'veda-app-ai-draft', true),
('ramayana-5-37-40', 'en', '"Riding on my back, like the sun and moon risen, those two great lions among men will come to you."', 'veda-app-ai-draft', true),
('ramayana-5-37-41', 'en', '"Those two heroes, Rama and Lakshmana, best of men, will come to Lanka together and destroy it with their arrows."', 'veda-app-ai-draft', true),
('ramayana-5-37-42', 'en', '"Raghava, joy of the Raghus, will slay Ravana and his followers, take you, lovely lady, and return to his own city."', 'veda-app-ai-draft', true),
('ramayana-5-37-43', 'en', '"So take heart, bless you, and wait for the time. Before long you will see Rama, blazing like fire."', 'veda-app-ai-draft', true),
('ramayana-5-37-44', 'en', '"When the lord of rakshasas is slain with his sons, ministers and kin, you will be united with Rama, as Rohini with the moon."', 'veda-app-ai-draft', true),
('ramayana-5-37-45', 'en', '"Soon, O Queen Maithili, you will reach the far shore of your grief, and before long you will see Ravana slain by Rama."', 'veda-app-ai-draft', true),
('ramayana-5-37-46', 'en', 'Having comforted Vaidehi thus, Hanuman, son of the Wind, resolved to go and spoke to her again.', 'veda-app-ai-draft', true),
('ramayana-5-37-47', 'en', '"Soon you will see Raghava, slayer of foes, self-possessed, and Lakshmana, bow in hand, at the gate of Lanka."', 'veda-app-ai-draft', true),
('ramayana-5-37-48', 'en', '"Soon you will see heroic monkeys gathered, armed with nails and teeth, valiant as lions and tigers, like great elephants."', 'veda-app-ai-draft', true),
('ramayana-5-37-49', 'en', '"Noble lady, you will see many troops of monkey chiefs, like mountains and clouds, roaring on the slopes of Lanka''s Malaya hills."', 'veda-app-ai-draft', true),
('ramayana-5-37-50', 'en', '"Struck to the heart by love''s fierce arrow, Rama finds no peace, like an elephant attacked by a lion."', 'veda-app-ai-draft', true),
('ramayana-5-37-51', 'en', '"Do not weep with grief, O Queen; let no sorrow be in your mind. Like Shachi with Indra, you have a husband who protects you."', 'veda-app-ai-draft', true),
('ramayana-5-37-52', 'en', '"Who is greater than Rama? Who is equal to Lakshmana? Those two brothers, like fire and wind, are your refuge."', 'veda-app-ai-draft', true),
('ramayana-5-37-53', 'en', '"You will not stay long in this terrible place full of rakshasas, O Queen. Your beloved will come soon; bear it only until I meet him."', 'veda-app-ai-draft', true),
('ramayana-5-38-1', 'en', 'Hearing the words of the great son of the Wind, Sita, like a daughter of the gods, spoke words for her own good.', 'veda-app-ai-draft', true),
('ramayana-5-38-2', 'en', '"Seeing you, bearer of good news, I rejoice, monkey, like the earth with half-grown crops when the rain comes."', 'veda-app-ai-draft', true),
('ramayana-5-38-3', 'en', '"Be kind to me, so that with these grief-worn limbs I may yet touch that tiger among men, as I long to."', 'veda-app-ai-draft', true),
('ramayana-5-38-4', 'en', '"And give Rama this token, best of monkeys: the grass blade he hurled in anger at the crow, which took one of its eyes."', 'veda-app-ai-draft', true),
('ramayana-5-38-5', 'en', '"And remind him of the mark of red arsenic he placed on my cheek when my forehead mark had worn off."', 'veda-app-ai-draft', true),
('ramayana-5-38-6', 'en', '"Mighty one, like great Indra and Varuna, how can you allow Sita to stay carried off among the rakshasas?"', 'veda-app-ai-draft', true),
('ramayana-5-38-7', 'en', '"This divine crest-jewel I have guarded carefully. Looking at it in my misfortune, I rejoiced as if seeing you, sinless one."', 'veda-app-ai-draft', true),
('ramayana-5-38-8', 'en', '"I return to you this splendid jewel, born of the waters. Beyond this, I cannot live, consumed by grief."', 'veda-app-ai-draft', true),
('ramayana-5-38-9', 'en', '"For your sake I endure unbearable sorrows and heart-piercing words from the fearsome rakshasis."', 'veda-app-ai-draft', true),
('ramayana-5-38-10', 'en', '"I will hold on to life one month, slayer of foes. Beyond that month I will not live without you, prince."', 'veda-app-ai-draft', true),
('ramayana-5-38-11', 'en', '"This king of rakshasas is terrible, and he does not look on me kindly. If I heard you were delaying, I would not live a moment."', 'veda-app-ai-draft', true),
('ramayana-5-38-12', 'en', 'Hearing Vaidehi''s piteous, tearful words, the radiant Hanuman, son of the Wind, spoke.', 'veda-app-ai-draft', true),
('ramayana-5-38-13', 'en', '"Rama has turned from everything in his grief for you, O Queen; I swear this truly. And as Rama is overwhelmed with grief, Lakshmana suffers too."', 'veda-app-ai-draft', true),
('ramayana-5-38-14', 'en', '"You have been found at last; this is no time for mourning. At this very moment, lovely lady, you will see the end of your sorrows."', 'veda-app-ai-draft', true),
('ramayana-5-38-15', 'en', '"Those two tigers among men, the blameless princes, roused by finding you, will burn Lanka to ashes."', 'veda-app-ai-draft', true),
('ramayana-5-38-16', 'en', '"Having slain cruel Ravana and his kin in battle, the two Raghavas will bring you to their city, large-eyed one."', 'veda-app-ai-draft', true),
('ramayana-5-38-17', 'en', '"Blameless lady, you should give me one more token that Rama would know, to give him joy."', 'veda-app-ai-draft', true),
('ramayana-5-38-18', 'en', 'She said: "I have already given you the best token here. Seeing this ornament from my hair, Rama will trust your words, hero Hanuman."', 'veda-app-ai-draft', true),
('ramayana-5-38-19', 'en', 'Taking that fine jewel, the splendid best of monkeys bowed his head to the queen and prepared to leave.', 'veda-app-ai-draft', true),
('ramayana-5-38-20', 'en', 'Seeing the bull among monkeys ready to leap and growing in size with great speed, Janaka''s daughter spoke, her face full of tears, in a sad, choked voice:', 'veda-app-ai-draft', true),
('ramayana-5-38-21', 'en', '"Hanuman, tell the lion-like brothers Rama and Lakshmana, Sugriva and his ministers, all of them, that I am well."', 'veda-app-ai-draft', true),
('ramayana-5-38-22', 'en', '"Arrange it so that mighty-armed Raghava rescues me from this flood of sorrow."', 'veda-app-ai-draft', true),
('ramayana-5-38-23', 'en', '"Tell Rama, when you reach him, of this fierce rush of grief and the threats of these rakshasis. May your journey be safe, hero among monkeys."', 'veda-app-ai-draft', true),
('ramayana-5-38-24', 'en', 'Told all the princess wished, his purpose achieved and his heart glad, the monkey saw that little of the task remained and in his mind went northwards.', 'veda-app-ai-draft', true),
('ramayana-5-39-1', 'en', 'Honoured by her with words of praise as he was about to go, the monkey moved away from that place and thought.', 'veda-app-ai-draft', true),
('ramayana-5-39-2', 'en', '"Little of the task is left; this dark-eyed lady has been found. Passing over three means, the fourth is what applies here."', 'veda-app-ai-draft', true),
('ramayana-5-39-3', 'en', '"Conciliation does not work with rakshasas; gifts do not work with those who have wealth; people proud of their strength cannot be divided. Valour is what appeals to me here."', 'veda-app-ai-draft', true),
('ramayana-5-39-4', 'en', '"Nothing can be settled in this task except by valour. If the rakshasas lose their best warriors in battle, they may somehow turn gentle."', 'veda-app-ai-draft', true),
('ramayana-5-39-5', 'en', '"One assigned a task who achieves many things besides, without harming the first task, is the one fit to do it."', 'veda-app-ai-draft', true),
('ramayana-5-39-6', 'en', '"No single means achieves even a small task. One who knows a matter in many ways is able to succeed."', 'veda-app-ai-draft', true),
('ramayana-5-39-7', 'en', '"If I go to the monkey king''s home having settled things here, knowing the real strength of ourselves and the enemy, then I will have done my master''s command."', 'veda-app-ai-draft', true),
('ramayana-5-39-8', 'en', '"How can my visit here end well today? By forcing a fight with the rakshasas, so that the ten-headed one measures his own strength and calls me to battle."', 'veda-app-ai-draft', true),
('ramayana-5-39-9', 'en', '"This grove of the cruel one, like Nandana, delightful to eye and mind, full of many trees and creepers,"', 'veda-app-ai-draft', true),
('ramayana-5-39-10', 'en', '"I will destroy, as fire burns a dry forest. When it is broken, Ravana will grow angry."', 'veda-app-ai-draft', true),
('ramayana-5-39-11', 'en', '"Then the lord of rakshasas will bring a great army with horses, chariots and elephants, armed with tridents, iron clubs and swords, and a great battle will follow."', 'veda-app-ai-draft', true),
('ramayana-5-39-12', 'en', '"Meeting those fierce rakshasas in battle with unstoppable valour, I will destroy the army Ravana sends and then go happily to the monkey king''s home."', 'veda-app-ai-draft', true),
('ramayana-5-39-13', 'en', 'Then, angry like the wind, the son of the Wind, of fearsome valour, began hurling down trees with the great force of his thighs.', 'veda-app-ai-draft', true),
('ramayana-5-39-14', 'en', 'Then the hero Hanuman wrecked the women''s pleasure grove, loud with the cries of excited birds and full of many trees and creepers.', 'veda-app-ai-draft', true),
('ramayana-5-39-15', 'en', 'With its trees crushed, its pools broken and its hillocks pounded to dust, the grove became an ugly sight.', 'veda-app-ai-draft', true),
('ramayana-5-39-16', 'en', 'With its creeper-bowers and painted houses destroyed, its great snakes and wild beasts driven off, its stone houses and other buildings torn down, the great grove lost all its beauty.', 'veda-app-ai-draft', true),
('ramayana-5-39-17', 'en', 'Having done this great offence to the mind of that lord of wealth, the great monkey, wishing to fight many mighty foes alone, stood at the gateway, blazing with splendour.', 'veda-app-ai-draft', true),
('ramayana-5-40-1', 'en', 'Then, at the cries of the birds and the crash of breaking trees, all the people of Lanka were alarmed and confused.', 'veda-app-ai-draft', true),
('ramayana-5-40-2', 'en', 'Beasts and birds fled in terror and cried out, and the rakshasas saw cruel omens.', 'veda-app-ai-draft', true),
('ramayana-5-40-3', 'en', 'Then the grim-faced rakshasis, their sleep gone, saw the ruined grove and that heroic great monkey.', 'veda-app-ai-draft', true),
('ramayana-5-40-4', 'en', 'Seeing them, the mighty-armed, powerful one took on a huge form that struck fear into the rakshasis.', 'veda-app-ai-draft', true),
('ramayana-5-40-5', 'en', 'Seeing that mountain-like, huge, mighty monkey, the rakshasis asked Janaka''s daughter:', 'veda-app-ai-draft', true),
('ramayana-5-40-6', 'en', '"Who is this? Whose is he? Where is he from? Why has he come here? How did you come to speak with him?"', 'veda-app-ai-draft', true),
('ramayana-5-40-7', 'en', '"Tell us, large-eyed one; do not be afraid, fortunate lady. What did he say to you, dark-eyed one?"', 'veda-app-ai-draft', true),
('ramayana-5-40-8', 'en', 'Then virtuous Sita, lovely in every limb, said: "How should I know rakshasas who change shape at will?"', 'veda-app-ai-draft', true),
('ramayana-5-40-9', 'en', '"You yourselves should know who he is and what he will do. Surely only a snake knows a snake''s tracks."', 'veda-app-ai-draft', true),
('ramayana-5-40-10', 'en', '"I too am afraid of him; I do not know who he is. I think he is a rakshasa who came in a form of his choosing."', 'veda-app-ai-draft', true),
('ramayana-5-40-11', 'en', 'Hearing Vaidehi''s words, the rakshasis ran off quickly; some stayed, and some went to tell Ravana.', 'veda-app-ai-draft', true),
('ramayana-5-40-12', 'en', 'Before Ravana, the grim-faced rakshasis began to describe the hideous, fearsome monkey.', 'veda-app-ai-draft', true),
('ramayana-5-40-13', 'en', '"King, in the middle of the ashoka grove stands a monkey of fearsome body and boundless valour, who has spoken with Sita."', 'veda-app-ai-draft', true),
('ramayana-5-40-14', 'en', '"And though we asked her many times, doe-eyed Sita, daughter of Janaka, will not tell us about that monkey."', 'veda-app-ai-draft', true),
('ramayana-5-40-15', 'en', '"He may be a messenger of Indra or of Kubera, or sent by Rama wishing to find Sita."', 'veda-app-ai-draft', true),
('ramayana-5-40-16', 'en', '"That strange-formed creature has wrecked your lovely pleasure grove, full of many kinds of animals."', 'veda-app-ai-draft', true),
('ramayana-5-40-17', 'en', '"There is no spot he has not destroyed, except the place where Sita, daughter of Janaka, is."', 'veda-app-ai-draft', true),
('ramayana-5-40-18', 'en', '"Whether to protect Janaki or out of weariness, we cannot tell. But what weariness could he have? He must have been protecting her."', 'veda-app-ai-draft', true),
('ramayana-5-40-19', 'en', '"The tall shimshapa tree rich with lovely shoots and leaves, where Sita herself sits, he has also spared."', 'veda-app-ai-draft', true),
('ramayana-5-40-20', 'en', '"You should order a harsh punishment for that fierce one who spoke with Sita and destroyed the grove."', 'veda-app-ai-draft', true),
('ramayana-5-40-21', 'en', '"Lord of the rakshasa hosts, who would speak to Sita, whom you have set your mind on, unless he had given up on life?"', 'veda-app-ai-draft', true),
('ramayana-5-40-22', 'en', 'Hearing the rakshasis, Ravana, lord of rakshasas, blazed like a sacrificial fire, his eyes rolling in anger.', 'veda-app-ai-draft', true),
('ramayana-5-40-23', 'en', 'The mighty one ordered rakshasas called Kinkaras, heroes like himself, to seize Hanuman.', 'veda-app-ai-draft', true),
('ramayana-5-40-24', 'en', 'Eighty thousand swift Kinkaras rushed out of the palace with hammers and clubs in hand.', 'veda-app-ai-draft', true),
('ramayana-5-40-25', 'en', 'Big-bellied, big-tusked, fearsome and mighty, all eager for battle and intent on seizing Hanuman.', 'veda-app-ai-draft', true),
('ramayana-5-40-26', 'en', 'Reaching the monkey standing at the gateway, they rushed at him with great speed, like moths into a fire.', 'veda-app-ai-draft', true),
('ramayana-5-40-27', 'en', 'They struck the best of monkeys with fine maces, gold-banded iron bars, and arrows bright as the sun.', 'veda-app-ai-draft', true),
('ramayana-5-40-28', 'en', 'Radiant Hanuman, splendid and like a mountain, lashed his tail on the ground and roared mightily.', 'veda-app-ai-draft', true),
('ramayana-5-40-29', 'en', 'At his roar they grew afraid, and saw Hanuman towering like an evening cloud.', 'veda-app-ai-draft', true),
('ramayana-5-40-30', 'en', 'Fearless because of their master''s orders, the rakshasas attacked the monkey from all sides with strange, fearsome weapons.', 'veda-app-ai-draft', true),
('ramayana-5-40-31', 'en', 'Surrounded on all sides by those heroes, the mighty one seized a fearsome iron bar fixed to the gateway.', 'veda-app-ai-draft', true),
('ramayana-5-40-32', 'en', 'Taking that bar, he struck down the night-walkers.', 'veda-app-ai-draft', true),
('ramayana-5-40-33', 'en', 'Holding it like Garuda holding a writhing serpent, the hero son of the Wind moved through the sky.', 'veda-app-ai-draft', true),
('ramayana-5-40-34', 'en', 'Having slain the Kinkara rakshasas, the heroic son of the Wind, eager for more battle, took his place again at the gateway.', 'veda-app-ai-draft', true),
('ramayana-5-40-35', 'en', 'A few rakshasas who escaped that terror told Ravana that all the Kinkaras had been killed.', 'veda-app-ai-draft', true),
('ramayana-5-40-36', 'en', 'Hearing that the great rakshasa force was destroyed, the king, eyes rolling, ordered Prahasta''s son, matchless in valour and hard to defeat in battle.', 'veda-app-ai-draft', true),
('ramayana-5-41-1', 'en', 'Having slain the Kinkaras, Hanuman reflected: "I have broken the grove but not the temple-palace. So I will destroy this palace too."', 'veda-app-ai-draft', true),
('ramayana-5-41-2', 'en', 'Thinking thus, to show his strength, Hanuman, best of monkeys, son of the Wind, leapt up onto the temple-palace, tall as a peak of Meru.', 'veda-app-ai-draft', true),
('ramayana-5-41-3', 'en', 'Having overrun the lofty temple-palace, invincible Hanuman, blazing with splendour, was like the Pariyatra mountain.', 'veda-app-ai-draft', true),
('ramayana-5-41-4', 'en', 'Growing huge, Hanuman, son of the Wind, boldly slapped his arms, filling Lanka with the sound.', 'veda-app-ai-draft', true),
('ramayana-5-41-5', 'en', 'At that great, ear-splitting sound, birds fell from the sky, and he proclaimed loudly:', 'veda-app-ai-draft', true),
('ramayana-5-41-6', 'en', '"Victory to mighty Rama and to powerful Lakshmana! Victory to King Sugriva, protected by Raghava!"', 'veda-app-ai-draft', true),
('ramayana-5-41-7', 'en', '"I am the servant of Rama, lord of Kosala, of tireless deeds: Hanuman, son of the Wind, destroyer of enemy armies."', 'veda-app-ai-draft', true),
('ramayana-5-41-8', 'en', '"A thousand Ravanas could not match me in battle as I strike with rocks and trees by the thousand."', 'veda-app-ai-draft', true),
('ramayana-5-41-9', 'en', '"Having battered the city of Lanka and bowed to Maithili, I will go, my purpose achieved, while all the rakshasas look on."', 'veda-app-ai-draft', true),
('ramayana-5-41-10', 'en', 'Having said this, the bull among monkeys, standing on the palace, roared with a fearsome sound, striking fear into the temple guards.', 'veda-app-ai-draft', true),
('ramayana-5-41-11', 'en', 'At that great sound, a hundred temple guards came, seizing many weapons, darts, swords and axes, and hurling them, surrounded the son of the Wind.', 'veda-app-ai-draft', true),
('ramayana-5-41-12', 'en', 'Surrounding the best of monkeys, that host of rakshasas looked like a vast whirlpool in the Ganga.', 'veda-app-ai-draft', true),
('ramayana-5-41-13', 'en', 'Then the son of the Wind, angered, took on a fearsome form.', 'veda-app-ai-draft', true),
('ramayana-5-41-14', 'en', 'Tearing out with great force a huge gold-adorned pillar of the palace, Hanuman, son of the Wind, whirled it around, that mighty one.', 'veda-app-ai-draft', true),
('ramayana-5-41-15', 'en', 'Having slain the hundred rakshasas, as Indra slew the demons with his thunderbolt, the splendid one, standing in the sky, said:', 'veda-app-ai-draft', true),
('ramayana-5-41-16', 'en', '"Thousands of great, mighty monkey chiefs like me, obedient to Sugriva, have been sent out."', 'veda-app-ai-draft', true),
('ramayana-5-41-17', 'en', '"With hundreds, hundreds of thousands, tens of millions and myriads, Sugriva will come, the destroyer of you all."', 'veda-app-ai-draft', true),
('ramayana-5-41-18', 'en', '"Neither this city of Lanka, nor you, nor Ravana will remain, since you have made an enemy of the great lord of the Ikshvakus."', 'veda-app-ai-draft', true),
('ramayana-5-42-1', 'en', 'Commanded by the lord of rakshasas, Prahasta''s mighty son Jambumali, with great tusks, came out bearing a bow.', 'veda-app-ai-draft', true),
('ramayana-5-42-2', 'en', 'Wearing red garlands and clothes, with bright earrings, huge, eyes rolling, fierce, hard to defeat in battle.', 'veda-app-ai-draft', true),
('ramayana-5-42-3', 'en', 'Twanging with force his great bow, bright as Indra''s rainbow, with shining arrows, sounding like a thunderbolt,', 'veda-app-ai-draft', true),
('ramayana-5-42-4', 'en', 'the great twang of his bow suddenly filled all the directions, the in-between regions and the sky.', 'veda-app-ai-draft', true),
('ramayana-5-42-5', 'en', 'Seeing him arrive in a chariot drawn by donkeys, swift Hanuman rejoiced and roared.', 'veda-app-ai-draft', true),
('ramayana-5-42-6', 'en', 'Mighty-armed Jambumali pierced the great monkey Hanuman, standing on the gateway''s arch, with sharp arrows.', 'veda-app-ai-draft', true),
('ramayana-5-42-7', 'en', 'He struck the lord of monkeys in the face with a crescent arrow, in the head with a barbed one, and in the arms with ten iron shafts.', 'veda-app-ai-draft', true),
('ramayana-5-42-8', 'en', 'His coppery face, struck by the arrow, shone like a full-blown autumn lotus touched by a sunbeam.', 'veda-app-ai-draft', true),
('ramayana-5-42-9', 'en', 'Struck by the rakshasa''s arrows, the great monkey grew angry, and saw beside him a huge rock.', 'veda-app-ai-draft', true),
('ramayana-5-42-10', 'en', 'Tearing it up swiftly, the mighty one hurled it hard, but the angry rakshasa struck it with ten arrows.', 'veda-app-ai-draft', true),
('ramayana-5-42-11', 'en', 'Seeing that effort foiled, Hanuman of fierce valour tore up a huge sala tree and whirled it.', 'veda-app-ai-draft', true),
('ramayana-5-42-12', 'en', 'Seeing the monkey whirling the sala tree, mighty Jambumali loosed very many arrows.', 'veda-app-ai-draft', true),
('ramayana-5-42-13', 'en', 'With four he cut the tree; with five he struck the monkey''s arms, with one his chest, and with ten the middle of his breast.', 'veda-app-ai-draft', true),
('ramayana-5-42-14', 'en', 'His body full of arrows, filled with great anger, he seized that same iron bar and whirled it with speed.', 'veda-app-ai-draft', true),
('ramayana-5-42-15', 'en', 'Very swift and of overwhelming strength, he whirled the bar with great force and brought it down on Jambumali''s broad chest.', 'veda-app-ai-draft', true),
('ramayana-5-42-16', 'en', 'Nothing was left to be seen of him: no head, arms or knees, no bow, chariot, horses or arrows.', 'veda-app-ai-draft', true),
('ramayana-5-42-17', 'en', 'Struck down by that force, the great chariot warrior Jambumali fell dead to the ground, his limbs and ornaments crushed.', 'veda-app-ai-draft', true),
('ramayana-5-42-18', 'en', 'Hearing that Jambumali and the mighty Kinkaras were slain, Ravana grew furious, eyes red with anger.', 'veda-app-ai-draft', true),
('ramayana-5-42-19', 'en', 'With Prahasta''s mighty son slain, the lord of night-walkers, his coppery eyes rolling in rage, quickly ordered the sons of his ministers, of great valour.', 'veda-app-ai-draft', true),
('ramayana-5-43-1', 'en', 'Then, urged by the lord of rakshasas, the seven sons of the ministers, bright as fire, came out of the palace.', 'veda-app-ai-draft', true),
('ramayana-5-43-2', 'en', 'Surrounded by great forces, bowmen of great strength, skilled in weapons, best of weapon-knowers, each eager to outdo the others,', 'veda-app-ai-draft', true),
('ramayana-5-43-3', 'en', 'in great chariots drawn by horses, covered in golden nets, with banners and flags, rumbling like thunderclouds,', 'veda-app-ai-draft', true),
('ramayana-5-43-4', 'en', 'twanging their bows adorned with bright gold, those of boundless valour, delighted, were like clouds with lightning.', 'veda-app-ai-draft', true),
('ramayana-5-43-5', 'en', 'Their mothers, knowing the Kinkaras had been killed, were troubled with grief, along with their kin and friends.', 'veda-app-ai-draft', true),
('ramayana-5-43-6', 'en', 'Rivalling one another, adorned with bright gold, they rushed at Hanuman standing at the gateway.', 'veda-app-ai-draft', true),
('ramayana-5-43-7', 'en', 'Pouring a rain of arrows, their chariots thundering, the bulls among rakshasas moved like rain-clouds.', 'veda-app-ai-draft', true),
('ramayana-5-43-8', 'en', 'Covered by those showers of arrows, Hanuman was hidden from view, like a king of mountains in the rains.', 'veda-app-ai-draft', true),
('ramayana-5-43-9', 'en', 'The swift monkey dodged their arrows and the rush of the heroes'' chariots, moving through the clear sky.', 'veda-app-ai-draft', true),
('ramayana-5-43-10', 'en', 'Playing with those bowmen in the sky, the hero shone like the mighty wind among bow-bearing clouds.', 'veda-app-ai-draft', true),
('ramayana-5-43-11', 'en', 'Giving a terrible roar that frightened that great army, mighty Hanuman charged at the rakshasas.', 'veda-app-ai-draft', true),
('ramayana-5-43-12', 'en', 'The scorcher of foes struck some with his palm, some with his feet, some with his fist, and tore some with his nails.', 'veda-app-ai-draft', true),
('ramayana-5-43-13', 'en', 'Some he crushed with his chest, others with his thighs; some fell to the ground at his roar alone.', 'veda-app-ai-draft', true),
('ramayana-5-43-14', 'en', 'When they had fallen to the ground, their whole army fled in all ten directions, struck with fear.', 'veda-app-ai-draft', true),
('ramayana-5-43-15', 'en', 'Elephants trumpeted wildly, horses fell to the ground, and the earth was strewn with chariots with broken seats, banners and parasols.', 'veda-app-ai-draft', true),
('ramayana-5-43-16', 'en', 'Having slain those swollen rakshasas, the mighty monkey of fierce valour, wishing to fight others, went back to that same gateway.', 'veda-app-ai-draft', true),
('ramayana-5-44-1', 'en', 'Learning that the ministers'' sons had been killed by the great monkey, Ravana, hiding his feelings, made a careful plan.', 'veda-app-ai-draft', true),
('ramayana-5-44-2', 'en', 'Virupaksha, Yupaksha, the rakshasa Durdhara, Praghasa and Bhasakarna, five leaders of his army,', 'veda-app-ai-draft', true),
('ramayana-5-44-3', 'en', 'the ten-headed one commanded, heroes skilled in strategy, eager to capture Hanuman, swift as the wind in battle.', 'veda-app-ai-draft', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values
('ramayana-5-1-1', 'en', 'Hanuman begins his mission.', 'Sundara Kanda, chapter 1: Hanuman leaps from Mount Mahendra across the ocean towards Lanka, and the Ocean asks Mount Mainaka to rise and give him a resting place. The Sundara Kanda, the ''beautiful book'', tells of Hanuman''s journey to Lanka and his finding of Sita.', '[{"word":"śatrukarśana","meaning":"destroyer of foes"},{"word":"anveṣṭum","meaning":"to search"},{"word":"cāraṇa","meaning":"celestial singer"}]'::jsonb, 'veda-app-ai-draft', 'draft'),
