insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 1 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-1-1', 1, 'Yuddha Kanda, Sarga 1, Verse 1', 'श्रुत्वा हनुमतो वाक्यं यथावदभिभाषितम्।
रामः प्रीतिसमायुक्तो वाक्यमुत्तरमब्रवीत्॥', 'śrutvā hanumato vākyaṃ yathāvad abhibhāṣitam
rāmaḥ prītisamāyukto vākyam uttaram abravīt', null, 6001001),
('ramayana-6-1-2', 2, 'Yuddha Kanda, Sarga 1, Verse 2', 'कृतं हनुमता कार्यं सुमहद्भुवि दुष्करम्।
मनसापि यदन्येन न शक्यं धरणीतले॥', 'kṛtaṃ hanumatā kāryaṃ sumahad bhuvi duṣkaram
manasāpi yad anyena na śakyaṃ dharaṇītale', null, 6001002),
('ramayana-6-1-3', 3, 'Yuddha Kanda, Sarga 1, Verse 3', 'न हि तं परिपश्यामि यस्तरेत महार्णवम्।
अन्यत्र गरुणाद्वायोरन्यत्र च हनूमतः॥', 'na hi taṃ paripaśyāmi yas tareta mahārṇavam
anyatra garuṇād vāyor anyatra ca hanūmataḥ', null, 6001003),
('ramayana-6-1-4', 4, 'Yuddha Kanda, Sarga 1, Verse 4', 'देवदानवयक्षाणां गन्धर्वोरगरक्षसाम्।
अप्रधृष्यां पुरीं लङ्कां रावणेन सुरक्षिताम्॥', 'devadānavayakṣāṇāṃ gandharvoragarakṣasām
apradhṛṣyāṃ purīṃ laṅkāṃ rāvaṇena surakṣitām', null, 6001004),
('ramayana-6-1-5', 5, 'Yuddha Kanda, Sarga 1, Verse 5', 'प्रविष्टः सत्त्वमाश्रित्य जीवन्को नाम निष्क्रमेत्।
को विशेत्सुदुराधर्षां राक्षसैश्च सुरक्षिताम्।
यो वीर्यबलसंपन्नो न समः स्याद्धनूमतः॥', 'praviṣṭaḥ sattvam āśritya jīvan ko nāma niṣkramet
ko viśet sudurādharṣāṃ rākṣasaiś ca surakṣitām
yo vīryabalasaṃpanno na samaḥ syād dhanūmataḥ', null, 6001005),
('ramayana-6-1-6', 6, 'Yuddha Kanda, Sarga 1, Verse 6', 'भृत्यकार्यं हनुमता सुग्रीवस्य कृतं महत्।
एवं विधाय स्वबलं सदृशं विक्रमस्य च॥', 'bhṛtyakāryaṃ hanumatā sugrīvasya kṛtaṃ mahat
evaṃ vidhāya svabalaṃ sadṛśaṃ vikramasya ca', null, 6001006),
('ramayana-6-1-7', 7, 'Yuddha Kanda, Sarga 1, Verse 7', 'यो हि भृत्यो नियुक्तः सन्भर्त्रा कर्मणि दुष्करे।
कुर्यात्तदनुरागेण तमाहुः पुरुषोत्तमम्॥', 'yo hi bhṛtyo niyuktaḥ san bhartrā karmaṇi duṣkare
kuryāt tadanurāgeṇa tam āhuḥ puruṣottamam', null, 6001007),
('ramayana-6-1-8', 8, 'Yuddha Kanda, Sarga 1, Verse 8', 'नियुक्तो नृपतेः कार्यं न कुर्याद्यः समाहितः।
भृत्यो युक्तः समर्थश्च तमाहुः पुरुषाधमम्॥', 'niyukto nṛpateḥ kāryaṃ na kuryād yaḥ samāhitaḥ
bhṛtyo yuktaḥ samarthaś ca tam āhuḥ puruṣādhamam', null, 6001008),
('ramayana-6-1-9', 9, 'Yuddha Kanda, Sarga 1, Verse 9', 'तन्नियोगे नियुक्तेन कृतं कृत्यं हनूमता।
न चात्मा लघुतां नीतः सुग्रीवश्चापि तोषितः॥', 'tanniyoge niyuktena kṛtaṃ kṛtyaṃ hanūmatā
na cātmā laghutāṃ nītaḥ sugrīvaś cāpi toṣitaḥ', null, 6001009),
('ramayana-6-1-10', 10, 'Yuddha Kanda, Sarga 1, Verse 10', 'अहं च रघुवंशश्च लक्ष्मणश्च महाबलः।
वैदेह्या दर्शनेनाद्य धर्मतः परिरक्षिताः॥', 'ahaṃ ca raghuvaṃśaś ca lakṣmaṇaś ca mahābalaḥ
vaidehyā darśanenādya dharmataḥ parirakṣitāḥ', null, 6001010),
('ramayana-6-1-11', 11, 'Yuddha Kanda, Sarga 1, Verse 11', 'इदं तु मम दीनस्या मनो भूयः प्रकर्षति।
यदिहास्य प्रियाख्यातुर्न कुर्मि सदृशं प्रियम्॥', 'idaṃ tu mama dīnasyā mano bhūyaḥ prakarṣati
yad ihāsya priyākhyātur na kurmi sadṛśaṃ priyam', null, 6001011),
('ramayana-6-1-12', 12, 'Yuddha Kanda, Sarga 1, Verse 12', 'एष सर्वस्वभूतस्तु परिष्वङ्गो हनूमतः।
मया कालमिमं प्राप्य दत्तस्तस्य महात्मनः॥', 'eṣa sarvasvabhūtas tu pariṣvaṅgo hanūmataḥ
mayā kālam imaṃ prāpya dattas tasya mahātmanaḥ', null, 6001012),
('ramayana-6-1-13', 13, 'Yuddha Kanda, Sarga 1, Verse 13', 'सर्वथा सुकृतं तावत्सीतायाः परिमार्गणम्।
सागरं तु समासाद्य पुनर्नष्टं मनो मम॥', 'sarvathā sukṛtaṃ tāvat sītāyāḥ parimārgaṇam
sāgaraṃ tu samāsādya punar naṣṭaṃ mano mama', null, 6001013),
('ramayana-6-1-14', 14, 'Yuddha Kanda, Sarga 1, Verse 14', 'कथं नाम समुद्रस्य दुष्पारस्य महाम्भसः।
हरयो दक्षिणं पारं गमिष्यन्ति समाहिताः॥', 'kathaṃ nāma samudrasya duṣpārasya mahāmbhasaḥ
harayo dakṣiṇaṃ pāraṃ gamiṣyanti samāhitāḥ', null, 6001014),
('ramayana-6-1-15', 15, 'Yuddha Kanda, Sarga 1, Verse 15', 'यद्यप्येष तु वृत्तान्तो वैदेह्या गदितो मम।
समुद्रपारगमने हरीणां किमिवोत्तरम्॥', 'yady apy eṣa tu vṛttānto vaidehyā gadito mama
samudrapāragamane harīṇāṃ kim ivottaram', null, 6001015),
('ramayana-6-1-16', 16, 'Yuddha Kanda, Sarga 1, Verse 16', 'इत्युक्त्वा शोकसंभ्रान्तो रामः शत्रुनिबर्हणः।
हनूमन्तं महाबाहुस्ततो ध्यानमुपागमत्॥', 'ity uktvā śokasaṃbhrānto rāmaḥ śatrunibarhaṇaḥ
hanūmantaṃ mahābāhus tato dhyānam upāgamat', null, 6001016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 2 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-2-1', 1, 'Yuddha Kanda, Sarga 2, Verse 1', 'तं तु शोकपरिद्यूनं रामं दशरथात्मजम्।
उवाच वचनं श्रीमान्सुग्रीवः शोकनाशनम्॥', 'taṃ tu śokaparidyūnaṃ rāmaṃ daśarathātmajam
uvāca vacanaṃ śrīmān sugrīvaḥ śokanāśanam', null, 6002001),
('ramayana-6-2-2', 2, 'Yuddha Kanda, Sarga 2, Verse 2', 'किं त्वं संतप्यसे वीर यथान्यः प्राकृतस्तथा।
मैवं भूस्त्यज संतापं कृतघ्न इव सौहृदम्॥', 'kiṃ tvaṃ saṃtapyase vīra yathānyaḥ prākṛtas tathā
maivaṃ bhūs tyaja saṃtāpaṃ kṛtaghna iva sauhṛdam', null, 6002002),
('ramayana-6-2-3', 3, 'Yuddha Kanda, Sarga 2, Verse 3', 'संतापस्य च ते स्थानं न हि पश्यामि राघव।
प्रवृत्तावुपलब्धायां ज्ञाते च निलये रिपोः॥', 'saṃtāpasya ca te sthānaṃ na hi paśyāmi rāghava
pravṛttāv upalabdhāyāṃ jñāte ca nilaye ripoḥ', null, 6002003),
('ramayana-6-2-4', 4, 'Yuddha Kanda, Sarga 2, Verse 4', 'धृतिमाञ्शास्त्रवित्प्राज्ञः पण्डितश्चासि राघव।
त्यजेमां पापिकां बुद्धिं कृत्वात्मेवार्थदूषणीम्॥', 'dhṛtimāñ śāstravit prājñaḥ paṇḍitaś cāsi rāghava
tyajemāṃ pāpikāṃ buddhiṃ kṛtvātmevārthadūṣaṇīm', null, 6002004),
('ramayana-6-2-5', 5, 'Yuddha Kanda, Sarga 2, Verse 5', 'समुद्रं लङ्घयित्वा तु महानक्रसमाकुलम्।
लङ्कामारोहयिष्यामो हनिष्यामश्च ते रिपुम्॥', 'samudraṃ laṅghayitvā tu mahānakrasamākulam
laṅkām ārohayiṣyāmo haniṣyāmaś ca te ripum', null, 6002005),
('ramayana-6-2-6', 6, 'Yuddha Kanda, Sarga 2, Verse 6', 'निरुत्साहस्य दीनस्य शोकपर्याकुलात्मनः।
सर्वार्था व्यवसीदन्ति व्यसनं चाधिगच्छति॥', 'nirutsāhasya dīnasya śokaparyākulātmanaḥ
sarvārthā vyavasīdanti vyasanaṃ cādhigacchati', null, 6002006),
('ramayana-6-2-7', 7, 'Yuddha Kanda, Sarga 2, Verse 7', 'इमे शूराः समर्थाश्च सर्वे नो हरियूथपाः।
त्वत्प्रियार्थं कृतोत्साहाः प्रवेष्टुमपि पावकम्॥', 'ime śūrāḥ samarthāś ca sarve no hariyūthapāḥ
tvatpriyārthaṃ kṛtotsāhāḥ praveṣṭum api pāvakam', null, 6002007),
('ramayana-6-2-8', 8, 'Yuddha Kanda, Sarga 2, Verse 8', 'एषां हर्षेण जानामि तर्कश्चास्मिन्दृढो मम।
विक्रमेण समानेष्ये सीतां हत्वा यथा रिपुम्॥', 'eṣāṃ harṣeṇa jānāmi tarkaś cāsmin dṛḍho mama
vikrameṇa samāneṣye sītāṃ hatvā yathā ripum', null, 6002008),
('ramayana-6-2-9', 9, 'Yuddha Kanda, Sarga 2, Verse 9', 'सेतुरत्र यथा वध्येद्यथा पश्येम तां पुरीम्।
तस्य राक्षसराजस्य तथा त्वं कुरु राघव॥', 'setur atra yathā vadhyed yathā paśyema tāṃ purīm
tasya rākṣasarājasya tathā tvaṃ kuru rāghava', null, 6002009),
('ramayana-6-2-10', 10, 'Yuddha Kanda, Sarga 2, Verse 10', 'दृष्ट्वा तां हि पुरीं लङ्कां त्रिकूटशिखरे स्थिताम्।
हतं च रावणं युद्धे दर्शनादुपधारय॥', 'dṛṣṭvā tāṃ hi purīṃ laṅkāṃ trikūṭaśikhare sthitām
hataṃ ca rāvaṇaṃ yuddhe darśanād upadhāraya', null, 6002010),
('ramayana-6-2-11', 11, 'Yuddha Kanda, Sarga 2, Verse 11', 'सेतुबद्धः समुद्रे च यावल्लङ्का समीपतः।
सर्वं तीर्णं च वै सैन्यं जितमित्युपधार्यताम्॥', 'setubaddhaḥ samudre ca yāval laṅkā samīpataḥ
sarvaṃ tīrṇaṃ ca vai sainyaṃ jitam ity upadhāryatām', null, 6002011),
('ramayana-6-2-12', 12, 'Yuddha Kanda, Sarga 2, Verse 12', 'इमे हि समरे शूरा हरयः कामरूपिणः।
तदलं विक्लवा बुद्धी राजन्सर्वार्थनाशनी॥', 'ime hi samare śūrā harayaḥ kāmarūpiṇaḥ
tad alaṃ viklavā buddhī rājan sarvārthanāśanī', null, 6002012),
('ramayana-6-2-13', 13, 'Yuddha Kanda, Sarga 2, Verse 13', 'पुरुषस्य हि लोकेऽस्मिञ्शोकः शौर्यापकर्षणः।
यत्तु कार्यं मनुष्येण शौण्डीर्यमवलम्बता।
शूराणां हि मनुष्याणां त्वद्विधानां महात्मनाम्॥', 'puruṣasya hi loke ''smiñ śokaḥ śauryāpakarṣaṇaḥ
yat tu kāryaṃ manuṣyeṇa śauṇḍīryam avalambatā
śūrāṇāṃ hi manuṣyāṇāṃ tvadvidhānāṃ mahātmanām', null, 6002013),
('ramayana-6-2-14', 14, 'Yuddha Kanda, Sarga 2, Verse 14', 'विनष्टे वा प्रनष्टे वा शोकः सर्वार्थनाशनः।
त्वं तु बुद्धिमतां श्रेष्ठः सर्वशास्त्रार्थकोविदः॥', 'vinaṣṭe vā pranaṣṭe vā śokaḥ sarvārthanāśanaḥ
tvaṃ tu buddhimatāṃ śreṣṭhaḥ sarvaśāstrārthakovidaḥ', null, 6002014),
('ramayana-6-2-15', 15, 'Yuddha Kanda, Sarga 2, Verse 15', 'मद्विधैः सचिवैः सार्थमरिं जेतुमिहार्हसि।
न हि पश्याम्यहं कं चित्त्रिषु लोकेषु राघव॥', 'madvidhaiḥ sacivaiḥ sārtham ariṃ jetum ihārhasi
na hi paśyāmy ahaṃ kaṃ cit triṣu lokeṣu rāghava', null, 6002015),
('ramayana-6-2-16', 16, 'Yuddha Kanda, Sarga 2, Verse 16', 'गृहीतधनुषो यस्ते तिष्ठेदभिमुखो रणे।
वानरेषु समासक्तं न ते कार्यं विपत्स्यते॥', 'gṛhītadhanuṣo yas te tiṣṭhed abhimukho raṇe
vānareṣu samāsaktaṃ na te kāryaṃ vipatsyate', null, 6002016),
('ramayana-6-2-17', 17, 'Yuddha Kanda, Sarga 2, Verse 17', 'अचिराद्द्रक्ष्यसे सीतां तीर्त्वा सागरमक्षयम्।
तदलं शोकमालम्ब्य क्रोधमालम्ब भूपते॥', 'acirād drakṣyase sītāṃ tīrtvā sāgaram akṣayam
tad alaṃ śokam ālambya krodham ālamba bhūpate', null, 6002017),
('ramayana-6-2-18', 18, 'Yuddha Kanda, Sarga 2, Verse 18', 'निश्चेष्टाः क्षत्रिया मन्दाः सर्वे चण्डस्य बिभ्यति।
लङ्गनार्थं च घोरस्य समुद्रस्य नदीपतेः॥', 'niśceṣṭāḥ kṣatriyā mandāḥ sarve caṇḍasya bibhyati
laṅganārthaṃ ca ghorasya samudrasya nadīpateḥ', null, 6002018),
('ramayana-6-2-19', 19, 'Yuddha Kanda, Sarga 2, Verse 19', 'सहास्माभिरिहोपेतः सूक्ष्मबुद्धिर्विचारय।
इमे हि समरे शूरा हरयः कामरूपिणः॥', 'sahāsmābhir ihopetaḥ sūkṣmabuddhir vicāraya
ime hi samare śūrā harayaḥ kāmarūpiṇaḥ', null, 6002019),
('ramayana-6-2-20', 20, 'Yuddha Kanda, Sarga 2, Verse 20', 'तानरीन्विधमिष्यन्ति शिलापादपवृष्टिभिः।
कथं चित्परिपश्यामस्ते वयं वरुणालयम्॥', 'tān arīn vidhamiṣyanti śilāpādapavṛṣṭibhiḥ
kathaṃ cit paripaśyāmas te vayaṃ varuṇālayam', null, 6002020),
('ramayana-6-2-21', 21, 'Yuddha Kanda, Sarga 2, Verse 21', 'किमुक्त्वा बहुधा चापि सर्वथा विजयी भवान्॥', 'kim uktvā bahudhā cāpi sarvathā vijayī bhavān', null, 6002021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 3 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-3-1', 1, 'Yuddha Kanda, Sarga 3, Verse 1', 'सुग्रीवस्य वचः श्रुत्वा हेतुमत्परमार्थवित्।
प्रतिजग्राह काकुत्स्थो हनूमन्तमथाब्रवीत्॥', 'sugrīvasya vacaḥ śrutvā hetumat paramārthavit
pratijagrāha kākutstho hanūmantam athābravīt', null, 6003001),
('ramayana-6-3-2', 2, 'Yuddha Kanda, Sarga 3, Verse 2', 'तरसा सेतुबन्धेन सागरोच्छोषणेन वा।
सर्वथा सुसमर्थोऽस्मि सागरस्यास्य लङ्घने॥', 'tarasā setubandhena sāgarocchoṣaṇena vā
sarvathā susamartho ''smi sāgarasyāsya laṅghane', null, 6003002),
('ramayana-6-3-3', 3, 'Yuddha Kanda, Sarga 3, Verse 3', 'कति दुर्गाणि दुर्गाया लङ्कायास्तद्ब्रवीहि मे।
ज्ञातुमिच्छामि तत्सर्वं दर्शनादिव वानर॥', 'kati durgāṇi durgāyā laṅkāyās tad bravīhi me
jñātum icchāmi tat sarvaṃ darśanād iva vānara', null, 6003003),
('ramayana-6-3-4', 4, 'Yuddha Kanda, Sarga 3, Verse 4', 'बलस्य परिमाणं च द्वारदुर्गक्रियामपि।
गुप्ति कर्म च लङ्काया रक्षसां सदनानि च॥', 'balasya parimāṇaṃ ca dvāradurgakriyām api
gupti karma ca laṅkāyā rakṣasāṃ sadanāni ca', null, 6003004),
('ramayana-6-3-5', 5, 'Yuddha Kanda, Sarga 3, Verse 5', 'यथासुखं यथावच्च लङ्कायामसि दृष्टवान्।
सरमाचक्ष्व तत्त्वेन सर्वथा कुशलो ह्यसि॥', 'yathāsukhaṃ yathāvac ca laṅkāyām asi dṛṣṭavān
saram ācakṣva tattvena sarvathā kuśalo hy asi', null, 6003005),
('ramayana-6-3-6', 6, 'Yuddha Kanda, Sarga 3, Verse 6', 'श्रुत्वा रामस्य वचनं हनूमान्मारुतात्मजः।
वाक्यं वाक्यविदां श्रेष्ठो रामं पुनरथाब्रवीत्॥', 'śrutvā rāmasya vacanaṃ hanūmān mārutātmajaḥ
vākyaṃ vākyavidāṃ śreṣṭho rāmaṃ punar athābravīt', null, 6003006),
('ramayana-6-3-7', 7, 'Yuddha Kanda, Sarga 3, Verse 7', 'श्रूयतां सर्वमाख्यास्ये दुर्गकर्मविधानतः।
गुप्ता पुरी यथा लङ्का रक्षिता च यथा बलैः॥', 'śrūyatāṃ sarvam ākhyāsye durgakarmavidhānataḥ
guptā purī yathā laṅkā rakṣitā ca yathā balaiḥ', null, 6003007),
('ramayana-6-3-8', 8, 'Yuddha Kanda, Sarga 3, Verse 8', 'परां समृद्धिं लङ्कायाः सागरस्य च भीमताम्।
विभागं च बलौघस्य निर्देशं वाहनस्य च॥', 'parāṃ samṛddhiṃ laṅkāyāḥ sāgarasya ca bhīmatām
vibhāgaṃ ca balaughasya nirdeśaṃ vāhanasya ca', null, 6003008),
('ramayana-6-3-9', 9, 'Yuddha Kanda, Sarga 3, Verse 9', 'प्रहृष्टा मुदिता लङ्का मत्तद्विपसमाकुला।
महती रथसंपूर्णा रक्षोगणसमाकुला॥', 'prahṛṣṭā muditā laṅkā mattadvipasamākulā
mahatī rathasaṃpūrṇā rakṣogaṇasamākulā', null, 6003009),
('ramayana-6-3-10', 10, 'Yuddha Kanda, Sarga 3, Verse 10', 'दृढबद्धकवाटानि महापरिघवन्ति च।
द्वाराणि विपुलान्यस्याश्चत्वारि सुमहान्ति च॥', 'dṛḍhabaddhakavāṭāni mahāparighavanti ca
dvārāṇi vipulāny asyāś catvāri sumahānti ca', null, 6003010),
('ramayana-6-3-11', 11, 'Yuddha Kanda, Sarga 3, Verse 11', 'वप्रेषूपलयन्त्राणि बलवन्ति महान्ति च।
आगतं परसैन्यं तैस्तत्र प्रतिनिवार्यते॥', 'vapreṣūpalayantrāṇi balavanti mahānti ca
āgataṃ parasainyaṃ tais tatra pratinivāryate', null, 6003011),
('ramayana-6-3-12', 12, 'Yuddha Kanda, Sarga 3, Verse 12', 'द्वारेषु संस्कृता भीमाः कालायसमयाः शिताः।
शतशो रोचिता वीरैः शतघ्न्यो रक्षसां गणैः॥', 'dvāreṣu saṃskṛtā bhīmāḥ kālāyasamayāḥ śitāḥ
śataśo rocitā vīraiḥ śataghnyo rakṣasāṃ gaṇaiḥ', null, 6003012),
('ramayana-6-3-13', 13, 'Yuddha Kanda, Sarga 3, Verse 13', 'सौवर्णश्च महांस्तस्याः प्राकारो दुष्प्रधर्षणः।
मणिविद्रुमवैदूर्यमुक्ताविचरितान्तरः॥', 'sauvarṇaś ca mahāṃs tasyāḥ prākāro duṣpradharṣaṇaḥ
maṇividrumavaidūryamuktāvicaritāntaraḥ', null, 6003013),
('ramayana-6-3-14', 14, 'Yuddha Kanda, Sarga 3, Verse 14', 'सर्वतश्च महाभीमाः शीततोया महाशुभाः।
अगाधा ग्राहवत्यश्च परिखा मीनसेविताः॥', 'sarvataś ca mahābhīmāḥ śītatoyā mahāśubhāḥ
agādhā grāhavatyaś ca parikhā mīnasevitāḥ', null, 6003014),
('ramayana-6-3-15', 15, 'Yuddha Kanda, Sarga 3, Verse 15', 'द्वारेषु तासां चत्वारः संक्रमाः परमायताः।
यन्त्रैरुपेता बहुभिर्महद्भिर्दृढसंधिभिः॥', 'dvāreṣu tāsāṃ catvāraḥ saṃkramāḥ paramāyatāḥ
yantrair upetā bahubhir mahadbhir dṛḍhasaṃdhibhiḥ', null, 6003015),
('ramayana-6-3-16', 16, 'Yuddha Kanda, Sarga 3, Verse 16', 'त्रायन्ते संक्रमास्तत्र परसैन्यागमे सति।
यन्त्रैस्तैरवकीर्यन्ते परिखासु समन्ततः॥', 'trāyante saṃkramās tatra parasainyāgame sati
yantrais tair avakīryante parikhāsu samantataḥ', null, 6003016),
('ramayana-6-3-17', 17, 'Yuddha Kanda, Sarga 3, Verse 17', 'एकस्त्वकम्प्यो बलवान्संक्रमः सुमहादृढः।
काञ्चनैर्बहुभिः स्तम्भैर्वेदिकाभिश्च शोभितः॥', 'ekas tv akampyo balavān saṃkramaḥ sumahādṛḍhaḥ
kāñcanair bahubhiḥ stambhair vedikābhiś ca śobhitaḥ', null, 6003017),
('ramayana-6-3-18', 18, 'Yuddha Kanda, Sarga 3, Verse 18', 'स्वयं प्रकृतिसंपन्नो युयुत्सू राम रावणः।
उत्थितश्चाप्रमत्तश्च बलानामनुदर्शने॥', 'svayaṃ prakṛtisaṃpanno yuyutsū rāma rāvaṇaḥ
utthitaś cāpramattaś ca balānām anudarśane', null, 6003018),
('ramayana-6-3-19', 19, 'Yuddha Kanda, Sarga 3, Verse 19', 'लङ्का पुरी निरालम्बा देवदुर्गा भयावहा।
नादेयं पार्वतं वन्यं कृत्रिमं च चतुर्विधम्॥', 'laṅkā purī nirālambā devadurgā bhayāvahā
nādeyaṃ pārvataṃ vanyaṃ kṛtrimaṃ ca caturvidham', null, 6003019),
('ramayana-6-3-20', 20, 'Yuddha Kanda, Sarga 3, Verse 20', 'स्थिता पारे समुद्रस्य दूरपारस्य राघव।
नौपथश्चापि नास्त्यत्र निरादेशश्च सर्वतः॥', 'sthitā pāre samudrasya dūrapārasya rāghava
naupathaś cāpi nāsty atra nirādeśaś ca sarvataḥ', null, 6003020),
('ramayana-6-3-21', 21, 'Yuddha Kanda, Sarga 3, Verse 21', 'शैलाग्रे रचिता दुर्गा सा पूर्देवपुरोपमा।
वाजिवारणसंपूर्णा लङ्का परमदुर्जया॥', 'śailāgre racitā durgā sā pūr devapuropamā
vājivāraṇasaṃpūrṇā laṅkā paramadurjayā', null, 6003021),
('ramayana-6-3-22', 22, 'Yuddha Kanda, Sarga 3, Verse 22', 'परिघाश्च शतघ्न्यश्च यन्त्राणि विविधानि च।
शोभयन्ति पुरीं लङ्कां रावणस्य दुरात्मनः॥', 'parighāś ca śataghnyaś ca yantrāṇi vividhāni ca
śobhayanti purīṃ laṅkāṃ rāvaṇasya durātmanaḥ', null, 6003022),
('ramayana-6-3-23', 23, 'Yuddha Kanda, Sarga 3, Verse 23', 'अयुतं रक्षसामत्र पश्चिमद्वारमाश्रितम्।
शूलहस्ता दुराधर्षाः सर्वे खड्गाग्रयोधिनः॥', 'ayutaṃ rakṣasām atra paścimadvāram āśritam
śūlahastā durādharṣāḥ sarve khaḍgāgrayodhinaḥ', null, 6003023),
('ramayana-6-3-24', 24, 'Yuddha Kanda, Sarga 3, Verse 24', 'नियुतं रक्षसामत्र दक्षिणद्वारमाश्रितम्।
चतुरङ्गेण सैन्येन योधास्तत्राप्यनुत्तमाः॥', 'niyutaṃ rakṣasām atra dakṣiṇadvāram āśritam
caturaṅgeṇa sainyena yodhās tatrāpy anuttamāḥ', null, 6003024),
('ramayana-6-3-25', 25, 'Yuddha Kanda, Sarga 3, Verse 25', 'प्रयुतं रक्षसामत्र पूर्वद्वारं समाश्रितम्।
चर्मखड्गधराः सर्वे तथा सर्वास्त्रकोविदाः॥', 'prayutaṃ rakṣasām atra pūrvadvāraṃ samāśritam
carmakhaḍgadharāḥ sarve tathā sarvāstrakovidāḥ', null, 6003025),
('ramayana-6-3-26', 26, 'Yuddha Kanda, Sarga 3, Verse 26', 'अर्बुदं रक्षसामत्र उत्तरद्वारमाश्रितम्।
रथिनश्चाश्ववाहाश्च कुलपुत्राः सुपूजिताः॥', 'arbudaṃ rakṣasām atra uttaradvāram āśritam
rathinaś cāśvavāhāś ca kulaputrāḥ supūjitāḥ', null, 6003026),
('ramayana-6-3-27', 27, 'Yuddha Kanda, Sarga 3, Verse 27', 'शतं शतसहस्राणां मध्यमं गुल्ममाश्रितम्।
यातुधाना दुराधर्षाः साग्रकोटिश्च रक्षसाम्॥', 'śataṃ śatasahasrāṇāṃ madhyamaṃ gulmam āśritam
yātudhānā durādharṣāḥ sāgrakoṭiś ca rakṣasām', null, 6003027),
('ramayana-6-3-28', 28, 'Yuddha Kanda, Sarga 3, Verse 28', 'ते मया संक्रमा भग्नाः परिखाश्चावपूरिताः।
दग्धा च नगरी लङ्का प्राकाराश्चावसादिताः॥', 'te mayā saṃkramā bhagnāḥ parikhāś cāvapūritāḥ
dagdhā ca nagarī laṅkā prākārāś cāvasāditāḥ', null, 6003028),
('ramayana-6-3-29', 29, 'Yuddha Kanda, Sarga 3, Verse 29', 'येन केन तु मार्गेण तराम वरुणालयम्।
हतेति नगरी लङ्कां वानरैरवधार्यताम्॥', 'yena kena tu mārgeṇa tarāma varuṇālayam
hateti nagarī laṅkāṃ vānarair avadhāryatām', null, 6003029),
('ramayana-6-3-30', 30, 'Yuddha Kanda, Sarga 3, Verse 30', 'अङ्गदो द्विविदो मैन्दो जाम्बवान्पनसो नलः।
नीलः सेनापतिश्चैव बलशेषेण किं तव॥', 'aṅgado dvivido maindo jāmbavān panaso nalaḥ
nīlaḥ senāpatiś caiva balaśeṣeṇa kiṃ tava', null, 6003030),
('ramayana-6-3-31', 31, 'Yuddha Kanda, Sarga 3, Verse 31', 'प्लवमाना हि गत्वा तां रावणस्य महापुरीम्।
सप्रकारां सभवनामानयिष्यन्ति मैथिलीम्॥', 'plavamānā hi gatvā tāṃ rāvaṇasya mahāpurīm
saprakārāṃ sabhavanām ānayiṣyanti maithilīm', null, 6003031),
('ramayana-6-3-32', 32, 'Yuddha Kanda, Sarga 3, Verse 32', 'एवमाज्ञापय क्षिप्रं बलानां सर्वसंग्रहम्।
मुहूर्तेन तु युक्तेन प्रस्थानमभिरोचय॥', 'evam ājñāpaya kṣipraṃ balānāṃ sarvasaṃgraham
muhūrtena tu yuktena prasthānam abhirocaya', null, 6003032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 4 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-4-1', 1, 'Yuddha Kanda, Sarga 4, Verse 1', 'श्रुत्वा हनूमतो वाक्यं यथावदनुपूर्वशः।
ततोऽब्रवीन्महातेजा रामः सत्यपराक्रमः॥', 'śrutvā hanūmato vākyaṃ yathāvad anupūrvaśaḥ
tato ''bravīn mahātejā rāmaḥ satyaparākramaḥ', null, 6004001),
('ramayana-6-4-2', 2, 'Yuddha Kanda, Sarga 4, Verse 2', 'यां निवेदयसे लङ्कां पुरीं भीमस्य रक्षसः।
क्षिप्रमेनां वधिष्यामि सत्यमेतद्ब्रवीमि ते॥', 'yāṃ nivedayase laṅkāṃ purīṃ bhīmasya rakṣasaḥ
kṣipram enāṃ vadhiṣyāmi satyam etad bravīmi te', null, 6004002),
('ramayana-6-4-3', 3, 'Yuddha Kanda, Sarga 4, Verse 3', 'अस्मिन्मुहूर्ते सुग्रीव प्रयाणमभिरोचये।
युक्तो मुहूर्तो विजयः प्राप्तो मध्यं दिवाकरः॥', 'asmin muhūrte sugrīva prayāṇam abhirocaye
yukto muhūrto vijayaḥ prāpto madhyaṃ divākaraḥ', null, 6004003),
('ramayana-6-4-4', 4, 'Yuddha Kanda, Sarga 4, Verse 4', 'उत्तरा फल्गुनी ह्यद्य श्वस्तु हस्तेन योक्ष्यते।
अभिप्रयाम सुग्रीव सर्वानीकसमावृताः॥', 'uttarā phalgunī hy adya śvas tu hastena yokṣyate
abhiprayāma sugrīva sarvānīkasamāvṛtāḥ', null, 6004004),
('ramayana-6-4-5', 5, 'Yuddha Kanda, Sarga 4, Verse 5', 'निमित्तानि च धन्यानि यानि प्रादुर्भवन्ति मे।
निहत्य रावणं सीतामानयिष्यामि जानकीम्॥', 'nimittāni ca dhanyāni yāni prādurbhavanti me
nihatya rāvaṇaṃ sītām ānayiṣyāmi jānakīm', null, 6004005),
('ramayana-6-4-6', 6, 'Yuddha Kanda, Sarga 4, Verse 6', 'उपरिष्टाद्धि नयनं स्फुरमाणमिदं मम।
विजयं समनुप्राप्तं शंसतीव मनोरथम्॥', 'upariṣṭād dhi nayanaṃ sphuramāṇam idaṃ mama
vijayaṃ samanuprāptaṃ śaṃsatīva manoratham', null, 6004006),
('ramayana-6-4-7', 7, 'Yuddha Kanda, Sarga 4, Verse 7', 'अग्रे यातु बलस्यास्य नीलो मार्गमवेक्षितुम्।
वृतः शतसहस्रेण वानराणां तरस्विनाम्॥', 'agre yātu balasyāsya nīlo mārgam avekṣitum
vṛtaḥ śatasahasreṇa vānarāṇāṃ tarasvinām', null, 6004007),
('ramayana-6-4-8', 8, 'Yuddha Kanda, Sarga 4, Verse 8', 'फलमूलवता नील शीतकाननवारिणा।
पथा मधुमता चाशु सेनां सेनापते नय॥', 'phalamūlavatā nīla śītakānanavāriṇā
pathā madhumatā cāśu senāṃ senāpate naya', null, 6004008),
('ramayana-6-4-9', 9, 'Yuddha Kanda, Sarga 4, Verse 9', 'दूषयेयुर्दुरात्मानः पथि मूलफलोदकम्।
राक्षसाः परिरक्षेथास्तेभ्यस्त्वं नित्यमुद्यतः॥', 'dūṣayeyur durātmānaḥ pathi mūlaphalodakam
rākṣasāḥ parirakṣethās tebhyas tvaṃ nityam udyataḥ', null, 6004009),
('ramayana-6-4-10', 10, 'Yuddha Kanda, Sarga 4, Verse 10', 'निम्नेषु वनदुर्गेषु वनेषु च वनौकसः।
अभिप्लुत्याभिपश्येयुः परेषां निहतं बलम्॥', 'nimneṣu vanadurgeṣu vaneṣu ca vanaukasaḥ
abhiplutyābhipaśyeyuḥ pareṣāṃ nihataṃ balam', null, 6004010),
('ramayana-6-4-11', 11, 'Yuddha Kanda, Sarga 4, Verse 11', 'सागरौघनिभं भीममग्रानीकं महाबलाः।
कपिसिंहा प्रकर्षन्तु शतशोऽथ सहस्रशः॥', 'sāgaraughanibhaṃ bhīmam agrānīkaṃ mahābalāḥ
kapisiṃhā prakarṣantu śataśo ''tha sahasraśaḥ', null, 6004011),
('ramayana-6-4-12', 12, 'Yuddha Kanda, Sarga 4, Verse 12', 'गजश्च गिरिसंकाशो गवयश्च महाबलः।
गवाक्षश्चाग्रतो यान्तु गवां दृप्ता इवर्षभाः॥', 'gajaś ca girisaṃkāśo gavayaś ca mahābalaḥ
gavākṣaś cāgrato yāntu gavāṃ dṛptā ivarṣabhāḥ', null, 6004012),
('ramayana-6-4-13', 13, 'Yuddha Kanda, Sarga 4, Verse 13', 'यातु वानरवाहिन्या वानरः प्लवतां पतिः।
पालयन्दक्षिणं पार्श्वमृषभो वानरर्षभः॥', 'yātu vānaravāhinyā vānaraḥ plavatāṃ patiḥ
pālayan dakṣiṇaṃ pārśvam ṛṣabho vānararṣabhaḥ', null, 6004013),
('ramayana-6-4-14', 14, 'Yuddha Kanda, Sarga 4, Verse 14', 'गन्धहस्तीव दुर्धर्षस्तरस्वी गन्धमादनः।
यातु वानरवाहिन्याः सव्यं पार्श्वमधिष्ठितः॥', 'gandhahastīva durdharṣas tarasvī gandhamādanaḥ
yātu vānaravāhinyāḥ savyaṃ pārśvam adhiṣṭhitaḥ', null, 6004014),
('ramayana-6-4-15', 15, 'Yuddha Kanda, Sarga 4, Verse 15', 'यास्यामि बलमध्येऽहं बलौघमभिहर्षयन्।
अधिरुह्य हनूमन्तमैरावतमिवेश्वरः॥', 'yāsyāmi balamadhye ''haṃ balaugham abhiharṣayan
adhiruhya hanūmantam airāvatam iveśvaraḥ', null, 6004015),
('ramayana-6-4-16', 16, 'Yuddha Kanda, Sarga 4, Verse 16', 'अङ्गदेनैष संयातु लक्ष्मणश्चान्तकोपमः।
सार्वभौमेण भूतेशो द्रविणाधिपतिर्यथा॥', 'aṅgadenaiṣa saṃyātu lakṣmaṇaś cāntakopamaḥ
sārvabhaumeṇa bhūteśo draviṇādhipatir yathā', null, 6004016),
('ramayana-6-4-17', 17, 'Yuddha Kanda, Sarga 4, Verse 17', 'जाम्बवांश्च सुषेणश्च वेगदर्शी च वानरः।
ऋक्षराजो महासत्त्वः कुक्षिं रक्षन्तु ते त्रयः॥', 'jāmbavāṃś ca suṣeṇaś ca vegadarśī ca vānaraḥ
ṛkṣarājo mahāsattvaḥ kukṣiṃ rakṣantu te trayaḥ', null, 6004017),
('ramayana-6-4-18', 18, 'Yuddha Kanda, Sarga 4, Verse 18', 'राघवस्य वचः श्रुत्वा सुग्रीवो वाहिनीपतिः।
व्यादिदेश महावीर्यान्वानरान्वानरर्षभः॥', 'rāghavasya vacaḥ śrutvā sugrīvo vāhinīpatiḥ
vyādideśa mahāvīryān vānarān vānararṣabhaḥ', null, 6004018),
('ramayana-6-4-19', 19, 'Yuddha Kanda, Sarga 4, Verse 19', 'ते वानरगणाः सर्वे समुत्पत्य युयुत्सवः।
गुहाभ्यः शिखरेभ्यश्च आशु पुप्लुविरे तदा॥', 'te vānaragaṇāḥ sarve samutpatya yuyutsavaḥ
guhābhyaḥ śikharebhyaś ca āśu pupluvire tadā', null, 6004019),
('ramayana-6-4-20', 20, 'Yuddha Kanda, Sarga 4, Verse 20', 'ततो वानरराजेन लक्ष्मणेन च पूजितः।
जगाम रामो धर्मात्मा ससैन्यो दक्षिणां दिशम्॥', 'tato vānararājena lakṣmaṇena ca pūjitaḥ
jagāma rāmo dharmātmā sasainyo dakṣiṇāṃ diśam', null, 6004020),
('ramayana-6-4-21', 21, 'Yuddha Kanda, Sarga 4, Verse 21', 'शतैः शतसहस्रैश्च कोटीभिरयुतैरपि।
वारणाभिश्च हरिभिर्ययौ परिवृतस्तदा॥', 'śataiḥ śatasahasraiś ca koṭībhir ayutair api
vāraṇābhiś ca haribhir yayau parivṛtas tadā', null, 6004021),
('ramayana-6-4-22', 22, 'Yuddha Kanda, Sarga 4, Verse 22', 'तं यान्तमनुयाति स्म महती हरिवाहिनी॥', 'taṃ yāntam anuyāti sma mahatī harivāhinī', null, 6004022),
('ramayana-6-4-23', 23, 'Yuddha Kanda, Sarga 4, Verse 23', 'हृष्टाः प्रमुदिताः सर्वे सुग्रीवेणाभिपालिताः।
आप्लवन्तः प्लवन्तश्च गर्जन्तश्च प्लवंगमाः।
क्ष्वेलन्तो निनदन्तश्च जग्मुर्वै दक्षिणां दिशम्॥', 'hṛṣṭāḥ pramuditāḥ sarve sugrīveṇābhipālitāḥ
āplavantaḥ plavantaś ca garjantaś ca plavaṃgamāḥ
kṣvelanto ninadantaś ca jagmur vai dakṣiṇāṃ diśam', null, 6004023),
('ramayana-6-4-24', 24, 'Yuddha Kanda, Sarga 4, Verse 24', 'भक्षयन्तः सुगन्धीनि मधूनि च फलानि च।
उद्वहन्तो महावृक्षान्मञ्जरीपुञ्जधारिणः॥', 'bhakṣayantaḥ sugandhīni madhūni ca phalāni ca
udvahanto mahāvṛkṣān mañjarīpuñjadhāriṇaḥ', null, 6004024),
('ramayana-6-4-25', 25, 'Yuddha Kanda, Sarga 4, Verse 25', 'अन्योन्यं सहसा दृष्टा निर्वहन्ति क्षिपन्ति च।
पतन्तश्चोत्पतन्त्यन्ये पातयन्त्यपरे परान्॥', 'anyonyaṃ sahasā dṛṣṭā nirvahanti kṣipanti ca
patantaś cotpatanty anye pātayanty apare parān', null, 6004025),
('ramayana-6-4-26', 26, 'Yuddha Kanda, Sarga 4, Verse 26', 'रावणो नो निहन्तव्यः सर्वे च रजनीचराः।
इति गर्जन्ति हरयो राघवस्य समीपतः॥', 'rāvaṇo no nihantavyaḥ sarve ca rajanīcarāḥ
iti garjanti harayo rāghavasya samīpataḥ', null, 6004026),
('ramayana-6-4-27', 27, 'Yuddha Kanda, Sarga 4, Verse 27', 'पुरस्तादृषभो वीरो नीलः कुमुद एव च।
पथानं शोधयन्ति स्म वानरैर्बहुभिः सह॥', 'purastād ṛṣabho vīro nīlaḥ kumuda eva ca
pathānaṃ śodhayanti sma vānarair bahubhiḥ saha', null, 6004027),
('ramayana-6-4-28', 28, 'Yuddha Kanda, Sarga 4, Verse 28', 'मध्ये तु राजा सुग्रीवो रामो लक्ष्मण एव च।
बहुभिर्बलिभिर्भीमैर्वृताः शत्रुनिबर्हणः॥', 'madhye tu rājā sugrīvo rāmo lakṣmaṇa eva ca
bahubhir balibhir bhīmair vṛtāḥ śatrunibarhaṇaḥ', null, 6004028),
('ramayana-6-4-29', 29, 'Yuddha Kanda, Sarga 4, Verse 29', 'हरिः शतबलिर्वीरः कोटीभिर्दशभिर्वृतः।
सर्वामेको ह्यवष्टभ्य ररक्ष हरिवाहिनीम्॥', 'hariḥ śatabalir vīraḥ koṭībhir daśabhir vṛtaḥ
sarvām eko hy avaṣṭabhya rarakṣa harivāhinīm', null, 6004029),
('ramayana-6-4-30', 30, 'Yuddha Kanda, Sarga 4, Verse 30', 'कोटीशतपरीवारः केसरी पनसो गजः।
अर्कश्चातिबलः पार्श्वमेकं तस्याभिरक्षति॥', 'koṭīśataparīvāraḥ kesarī panaso gajaḥ
arkaś cātibalaḥ pārśvam ekaṃ tasyābhirakṣati', null, 6004030),
('ramayana-6-4-31', 31, 'Yuddha Kanda, Sarga 4, Verse 31', 'सुषेणो जाम्बवांश्चैव ऋक्षैर्बहुभिरावृतः।
सुग्रीवं पुरतः कृत्वा जघनं संररक्षतुः॥', 'suṣeṇo jāmbavāṃś caiva ṛkṣair bahubhir āvṛtaḥ
sugrīvaṃ purataḥ kṛtvā jaghanaṃ saṃrarakṣatuḥ', null, 6004031),
('ramayana-6-4-32', 32, 'Yuddha Kanda, Sarga 4, Verse 32', 'तेषां सेनापतिर्वीरो नीलो वानरपुंगवः।
संपतन्पततां श्रेष्ठस्तद्बलं पर्यपालयत्॥', 'teṣāṃ senāpatir vīro nīlo vānarapuṃgavaḥ
saṃpatan patatāṃ śreṣṭhas tad balaṃ paryapālayat', null, 6004032),
('ramayana-6-4-33', 33, 'Yuddha Kanda, Sarga 4, Verse 33', 'दरीमिखः प्रजङ्घश्च जम्भोऽथ रभसः कपिः।
सर्वतश्च ययुर्वीरास्त्वरयन्तः प्लवंगमान्॥', 'darīmikhaḥ prajaṅghaś ca jambho ''tha rabhasaḥ kapiḥ
sarvataś ca yayur vīrās tvarayantaḥ plavaṃgamān', null, 6004033),
('ramayana-6-4-34', 34, 'Yuddha Kanda, Sarga 4, Verse 34', 'एवं ते हरिशार्दूला गच्छन्तो बलदर्पिताः।
अपश्यंस्ते गिरिश्रेष्ठं सह्यं द्रुमलतायुतम्॥', 'evaṃ te hariśārdūlā gacchanto baladarpitāḥ
apaśyaṃs te giriśreṣṭhaṃ sahyaṃ drumalatāyutam', null, 6004034),
('ramayana-6-4-35', 35, 'Yuddha Kanda, Sarga 4, Verse 35', 'सागरौघनिभं भीमं तद्वानरबलं महत्।
निःससर्प महाघोषं भीमवेग इवार्णवः॥', 'sāgaraughanibhaṃ bhīmaṃ tad vānarabalaṃ mahat
niḥsasarpa mahāghoṣaṃ bhīmavega ivārṇavaḥ', null, 6004035),
('ramayana-6-4-36', 36, 'Yuddha Kanda, Sarga 4, Verse 36', 'तस्य दाशरथेः पार्श्वे शूरास्ते कपिकुञ्जराः।
तूर्णमापुप्लुवुः सर्वे सदश्वा इव चोदिताः॥', 'tasya dāśaratheḥ pārśve śūrās te kapikuñjarāḥ
tūrṇam āpupluvuḥ sarve sadaśvā iva coditāḥ', null, 6004036),
('ramayana-6-4-37', 37, 'Yuddha Kanda, Sarga 4, Verse 37', 'कपिभ्यामुह्यमानौ तौ शुशुभते नरर्षभौ।
महद्भ्यामिव संस्पृष्टौ ग्राहाभ्यां चन्द्रभास्करौ॥', 'kapibhyām uhyamānau tau śuśubhate nararṣabhau
mahadbhyām iva saṃspṛṣṭau grāhābhyāṃ candrabhāskarau', null, 6004037),
('ramayana-6-4-38', 38, 'Yuddha Kanda, Sarga 4, Verse 38', 'तमङ्गदगतो रामं लक्ष्मणः शुभया गिरा।
उवाच प्रतिपूर्णार्थः स्मृतिमान्प्रतिभानवान्॥', 'tam aṅgadagato rāmaṃ lakṣmaṇaḥ śubhayā girā
uvāca pratipūrṇārthaḥ smṛtimān pratibhānavān', null, 6004038),
('ramayana-6-4-39', 39, 'Yuddha Kanda, Sarga 4, Verse 39', 'हृतामवाप्य वैदेहीं क्षिप्रं हत्वा च रावणम्।
समृद्धार्थः समृद्धार्थामयोध्यां प्रतियास्यसि॥', 'hṛtām avāpya vaidehīṃ kṣipraṃ hatvā ca rāvaṇam
samṛddhārthaḥ samṛddhārthām ayodhyāṃ pratiyāsyasi', null, 6004039),
('ramayana-6-4-40', 40, 'Yuddha Kanda, Sarga 4, Verse 40', 'महान्ति च निमित्तानि दिवि भूमौ च राघव।
शुभान्ति तव पश्यामि सर्वाण्येवार्थसिद्धये॥', 'mahānti ca nimittāni divi bhūmau ca rāghava
śubhānti tava paśyāmi sarvāṇy evārthasiddhaye', null, 6004040),
('ramayana-6-4-41', 41, 'Yuddha Kanda, Sarga 4, Verse 41', 'अनु वाति शुभो वायुः सेनां मृदुहितः सुखः।
पूर्णवल्गुस्वराश्चेमे प्रवदन्ति मृगद्विजाः॥', 'anu vāti śubho vāyuḥ senāṃ mṛduhitaḥ sukhaḥ
pūrṇavalgusvarāś ceme pravadanti mṛgadvijāḥ', null, 6004041),
('ramayana-6-4-42', 42, 'Yuddha Kanda, Sarga 4, Verse 42', 'प्रसन्नाश्च दिशः सर्वा विमलश्च दिवाकरः।
उशना च प्रसन्नार्चिरनु त्वां भार्गवो गतः॥', 'prasannāś ca diśaḥ sarvā vimalaś ca divākaraḥ
uśanā ca prasannārcir anu tvāṃ bhārgavo gataḥ', null, 6004042),
('ramayana-6-4-43', 43, 'Yuddha Kanda, Sarga 4, Verse 43', 'ब्रह्मराशिर्विशुद्धश्च शुद्धाश्च परमर्षयः।
अर्चिष्मन्तः प्रकाशन्ते ध्रुवं सर्वे प्रदक्षिणम्॥', 'brahmarāśir viśuddhaś ca śuddhāś ca paramarṣayaḥ
arciṣmantaḥ prakāśante dhruvaṃ sarve pradakṣiṇam', null, 6004043),
('ramayana-6-4-44', 44, 'Yuddha Kanda, Sarga 4, Verse 44', 'त्रिशङ्कुर्विमलो भाति राजर्षिः सपुरोहितः।
पितामहवरोऽस्माकमिष्क्वाकूणां महात्मनाम्॥', 'triśaṅkur vimalo bhāti rājarṣiḥ sapurohitaḥ
pitāmahavaro ''smākam iṣkvākūṇāṃ mahātmanām', null, 6004044),
('ramayana-6-4-45', 45, 'Yuddha Kanda, Sarga 4, Verse 45', 'विमले च प्रकाशेते विशाखे निरुपद्रवे।
नक्षत्रं परमस्माकमिक्ष्वाकूणां महात्मनाम्॥', 'vimale ca prakāśete viśākhe nirupadrave
nakṣatraṃ param asmākam ikṣvākūṇāṃ mahātmanām', null, 6004045),
('ramayana-6-4-46', 46, 'Yuddha Kanda, Sarga 4, Verse 46', 'नैरृतं नैरृतानां च नक्षत्रमभिपीड्यते।
मूलं मूलवता स्पृष्टं धूप्यते धूमकेतुना॥', 'nairṛtaṃ nairṛtānāṃ ca nakṣatram abhipīḍyate
mūlaṃ mūlavatā spṛṣṭaṃ dhūpyate dhūmaketunā', null, 6004046),
('ramayana-6-4-47', 47, 'Yuddha Kanda, Sarga 4, Verse 47', 'सरं चैतद्विनाशाय राक्षसानामुपस्थितम्।
काले कालगृहीतानां नकत्रं ग्रहपीडितम्॥', 'saraṃ caitad vināśāya rākṣasānām upasthitam
kāle kālagṛhītānāṃ nakatraṃ grahapīḍitam', null, 6004047),
('ramayana-6-4-48', 48, 'Yuddha Kanda, Sarga 4, Verse 48', 'प्रसन्नाः सुरसाश्चापो वनानि फलवन्ति च।
प्रवान्त्यभ्यधिकं गन्धा यथर्तुकुसुमा द्रुमाः॥', 'prasannāḥ surasāś cāpo vanāni phalavanti ca
pravānty abhyadhikaṃ gandhā yathartukusumā drumāḥ', null, 6004048),
('ramayana-6-4-49', 49, 'Yuddha Kanda, Sarga 4, Verse 49', 'व्यूढानि कपिसैन्यानि प्रकाशन्तेऽधिकं प्रभो।
देवानामिव सैन्यानि संग्रामे तारकामये॥', 'vyūḍhāni kapisainyāni prakāśante ''dhikaṃ prabho
devānām iva sainyāni saṃgrāme tārakāmaye', null, 6004049),
('ramayana-6-4-50', 50, 'Yuddha Kanda, Sarga 4, Verse 50', 'एवमार्य समीक्ष्यैतान्प्रीतो भवितुमर्हसि।
इति भ्रातरमाश्वास्य हृष्टः सौमित्रिरब्रवीत्॥', 'evam ārya samīkṣyaitān prīto bhavitum arhasi
iti bhrātaram āśvāsya hṛṣṭaḥ saumitrir abravīt', null, 6004050),
('ramayana-6-4-51', 51, 'Yuddha Kanda, Sarga 4, Verse 51', 'अथावृत्य महीं कृत्स्नां जगाम महती चमूः।
ऋक्षवानरशार्दूलैर्नखदंष्ट्रायुधैर्वृता॥', 'athāvṛtya mahīṃ kṛtsnāṃ jagāma mahatī camūḥ
ṛkṣavānaraśārdūlair nakhadaṃṣṭrāyudhair vṛtā', null, 6004051),
('ramayana-6-4-52', 52, 'Yuddha Kanda, Sarga 4, Verse 52', 'कराग्रैश्चरणाग्रैश्च वानरैरुद्धतं रजः।
भौममन्तर्दधे लोकं निवार्य सवितुः प्रभाम्॥', 'karāgraiś caraṇāgraiś ca vānarair uddhataṃ rajaḥ
bhaumam antardadhe lokaṃ nivārya savituḥ prabhām', null, 6004052),
('ramayana-6-4-53', 53, 'Yuddha Kanda, Sarga 4, Verse 53', 'सा स्म याति दिवारात्रं महती हरिवाहिनी।
हृष्टप्रमुदिता सेना सुग्रीवेणाभिरक्षिता॥', 'sā sma yāti divārātraṃ mahatī harivāhinī
hṛṣṭapramuditā senā sugrīveṇābhirakṣitā', null, 6004053),
('ramayana-6-4-54', 54, 'Yuddha Kanda, Sarga 4, Verse 54', 'वनरास्त्वरितं यान्ति सर्वे युद्धाभिनन्दनः।
मुमोक्षयिषवः सीतां मुहूर्तं क्वापि नासत॥', 'vanarās tvaritaṃ yānti sarve yuddhābhinandanaḥ
mumokṣayiṣavaḥ sītāṃ muhūrtaṃ kvāpi nāsata', null, 6004054),
('ramayana-6-4-55', 55, 'Yuddha Kanda, Sarga 4, Verse 55', 'ततः पादपसंबाधं नानामृगसमाकुलम्।
सह्यपर्वतमासेदुर्मलयं च मही धरम्॥', 'tataḥ pādapasaṃbādhaṃ nānāmṛgasamākulam
sahyaparvatam āsedur malayaṃ ca mahī dharam', null, 6004055),
('ramayana-6-4-56', 56, 'Yuddha Kanda, Sarga 4, Verse 56', 'काननानि विचित्राणि नदीप्रस्रवणानि च।
पश्यन्नपि ययौ रामः सह्यस्य मलयस्य च॥', 'kānanāni vicitrāṇi nadīprasravaṇāni ca
paśyann api yayau rāmaḥ sahyasya malayasya ca', null, 6004056),
('ramayana-6-4-57', 57, 'Yuddha Kanda, Sarga 4, Verse 57', 'चम्पकांस्तिलकांश्चूतानशोकान्सिन्दुवारकान्।
करवीरांश्च तिमिशान्भञ्जन्ति स्म प्लवंगमाः॥', 'campakāṃs tilakāṃś cūtān aśokān sinduvārakān
karavīrāṃś ca timiśān bhañjanti sma plavaṃgamāḥ', null, 6004057),
('ramayana-6-4-58', 58, 'Yuddha Kanda, Sarga 4, Verse 58', 'फलान्यमृतगन्धीनि मूलानि कुसुमानि च।
बुभुजुर्वानरास्तत्र पादपानां बलोत्कटाः॥', 'phalāny amṛtagandhīni mūlāni kusumāni ca
bubhujur vānarās tatra pādapānāṃ balotkaṭāḥ', null, 6004058),
('ramayana-6-4-59', 59, 'Yuddha Kanda, Sarga 4, Verse 59', 'द्रोणमात्रप्रमाणानि लम्बमानानि वानराः।
ययुः पिबन्तो हृष्टास्ते मधूनि मधुपिङ्गलाः॥', 'droṇamātrapramāṇāni lambamānāni vānarāḥ
yayuḥ pibanto hṛṣṭās te madhūni madhupiṅgalāḥ', null, 6004059),
('ramayana-6-4-60', 60, 'Yuddha Kanda, Sarga 4, Verse 60', 'पादपानवभञ्जन्तो विकर्षन्तस्तथा लताः।
विधमन्तो गिरिवरान्प्रययुः प्लवगर्षभाः॥', 'pādapān avabhañjanto vikarṣantas tathā latāḥ
vidhamanto girivarān prayayuḥ plavagarṣabhāḥ', null, 6004060),
('ramayana-6-4-61', 61, 'Yuddha Kanda, Sarga 4, Verse 61', 'वृक्षेभ्योऽन्ये तु कपयो नर्दन्तो मधुदर्पिताः।
अन्ये वृक्षान्प्रपद्यन्ते प्रपतन्त्यपि चापरे॥', 'vṛkṣebhyo ''nye tu kapayo nardanto madhudarpitāḥ
anye vṛkṣān prapadyante prapatanty api cāpare', null, 6004061),
('ramayana-6-4-62', 62, 'Yuddha Kanda, Sarga 4, Verse 62', 'बभूव वसुधा तैस्तु संपूर्णा हरिपुंगवैः।
यथा कमलकेदारैः पक्वैरिव वसुंधरा॥', 'babhūva vasudhā tais tu saṃpūrṇā haripuṃgavaiḥ
yathā kamalakedāraiḥ pakvair iva vasuṃdharā', null, 6004062),
('ramayana-6-4-63', 63, 'Yuddha Kanda, Sarga 4, Verse 63', 'महेन्द्रमथ संप्राप्य रामो राजीवलोचनः।
अध्यारोहन्महाबाहुः शिखरं द्रुमभूषितम्॥', 'mahendram atha saṃprāpya rāmo rājīvalocanaḥ
adhyārohan mahābāhuḥ śikharaṃ drumabhūṣitam', null, 6004063),
('ramayana-6-4-64', 64, 'Yuddha Kanda, Sarga 4, Verse 64', 'ततः शिखरमारुह्य रामो दशरथात्मजः।
कूर्ममीनसमाकीर्णमपश्यत्सलिलाशयम्॥', 'tataḥ śikharam āruhya rāmo daśarathātmajaḥ
kūrmamīnasamākīrṇam apaśyat salilāśayam', null, 6004064),
('ramayana-6-4-65', 65, 'Yuddha Kanda, Sarga 4, Verse 65', 'ते सह्यं समतिक्रम्य मलयं च महागिरिम्।
आसेदुरानुपूर्व्येण समुद्रं भीमनिःस्वनम्॥', 'te sahyaṃ samatikramya malayaṃ ca mahāgirim
āsedur ānupūrvyeṇa samudraṃ bhīmaniḥsvanam', null, 6004065),
('ramayana-6-4-66', 66, 'Yuddha Kanda, Sarga 4, Verse 66', 'अवरुह्य जगामाशु वेलावनमनुत्तमम्।
रामो रमयतां श्रेष्ठः ससुग्रीवः सलक्ष्मणः॥', 'avaruhya jagāmāśu velāvanam anuttamam
rāmo ramayatāṃ śreṣṭhaḥ sasugrīvaḥ salakṣmaṇaḥ', null, 6004066),
('ramayana-6-4-67', 67, 'Yuddha Kanda, Sarga 4, Verse 67', 'अथ धौतोपलतलां तोयौघैः सहसोत्थितैः।
वेलामासाद्य विपुलां रामो वचनमब्रवीत्॥', 'atha dhautopalatalāṃ toyaughaiḥ sahasotthitaiḥ
velām āsādya vipulāṃ rāmo vacanam abravīt', null, 6004067),
('ramayana-6-4-68', 68, 'Yuddha Kanda, Sarga 4, Verse 68', 'एते वयमनुप्राप्ताः सुग्रीव वरुणालयम्।
इहेदानीं विचिन्ता सा या न पूर्वं समुत्थिता॥', 'ete vayam anuprāptāḥ sugrīva varuṇālayam
ihedānīṃ vicintā sā yā na pūrvaṃ samutthitā', null, 6004068),
('ramayana-6-4-69', 69, 'Yuddha Kanda, Sarga 4, Verse 69', 'अतः परमतीरोऽयं सागरः सरितां पति।
न चायमनुपायेन शक्यस्तरितुमर्णवः॥', 'ataḥ paramatīro ''yaṃ sāgaraḥ saritāṃ pati
na cāyam anupāyena śakyas taritum arṇavaḥ', null, 6004069),
('ramayana-6-4-70', 70, 'Yuddha Kanda, Sarga 4, Verse 70', 'तदिहैव निवेशोऽस्तु मन्त्रः प्रस्तूयतामिह।
यथेदं वानरबलं परं पारमवाप्नुयात्॥', 'tad ihaiva niveśo ''stu mantraḥ prastūyatām iha
yathedaṃ vānarabalaṃ paraṃ pāram avāpnuyāt', null, 6004070),
('ramayana-6-4-71', 71, 'Yuddha Kanda, Sarga 4, Verse 71', 'इतीव स महाबाहुः सीताहरणकर्शितः।
रामः सागरमासाद्य वासमाज्ञापयत्तदा॥', 'itīva sa mahābāhuḥ sītāharaṇakarśitaḥ
rāmaḥ sāgaram āsādya vāsam ājñāpayat tadā', null, 6004071),
('ramayana-6-4-72', 72, 'Yuddha Kanda, Sarga 4, Verse 72', 'संप्राप्तो मन्त्रकालो नः सागरस्येह लङ्घने।
स्वां स्वां सेनां समुत्सृज्य मा च कश्चित्कुतो व्रजेत्।
गच्छन्तु वानराः शूरा ज्ञेयं छन्नं भयं च नः॥', 'saṃprāpto mantrakālo naḥ sāgarasyeha laṅghane
svāṃ svāṃ senāṃ samutsṛjya mā ca kaś cit kuto vrajet
gacchantu vānarāḥ śūrā jñeyaṃ channaṃ bhayaṃ ca naḥ', null, 6004072),
('ramayana-6-4-73', 73, 'Yuddha Kanda, Sarga 4, Verse 73', 'रामस्य वचनं श्रुत्वा सुग्रीवः सहलक्ष्मणः।
सेनां न्यवेशयत्तीरे सागरस्य द्रुमायुते॥', 'rāmasya vacanaṃ śrutvā sugrīvaḥ sahalakṣmaṇaḥ
senāṃ nyaveśayat tīre sāgarasya drumāyute', null, 6004073),
('ramayana-6-4-74', 74, 'Yuddha Kanda, Sarga 4, Verse 74', 'विरराज समीपस्थं सागरस्य तु तद्बलम्।
मधुपाण्डुजलः श्रीमान्द्वितीय इव सागरः॥', 'virarāja samīpasthaṃ sāgarasya tu tad balam
madhupāṇḍujalaḥ śrīmān dvitīya iva sāgaraḥ', null, 6004074),
('ramayana-6-4-75', 75, 'Yuddha Kanda, Sarga 4, Verse 75', 'वेलावनमुपागम्य ततस्ते हरिपुंगवाः।
विनिविष्टाः परं पारं काङ्क्षमाणा महोदधेः॥', 'velāvanam upāgamya tatas te haripuṃgavāḥ
viniviṣṭāḥ paraṃ pāraṃ kāṅkṣamāṇā mahodadheḥ', null, 6004075),
('ramayana-6-4-76', 76, 'Yuddha Kanda, Sarga 4, Verse 76', 'सा महार्णवमासाद्य हृष्टा वानरवाहिनी।
वायुवेगसमाधूतं पश्यमाना महार्णवम्॥', 'sā mahārṇavam āsādya hṛṣṭā vānaravāhinī
vāyuvegasamādhūtaṃ paśyamānā mahārṇavam', null, 6004076),
('ramayana-6-4-77', 77, 'Yuddha Kanda, Sarga 4, Verse 77', 'दूरपारमसंबाधं रक्षोगणनिषेवितम्।
पश्यन्तो वरुणावासं निषेदुर्हरियूथपाः॥', 'dūrapāram asaṃbādhaṃ rakṣogaṇaniṣevitam
paśyanto varuṇāvāsaṃ niṣedur hariyūthapāḥ', null, 6004077),
('ramayana-6-4-78', 78, 'Yuddha Kanda, Sarga 4, Verse 78', 'चण्डनक्रग्रहं घोरं क्षपादौ दिवसक्षये।
चन्द्रोदये समाधूतं प्रतिचन्द्रसमाकुलम्॥', 'caṇḍanakragrahaṃ ghoraṃ kṣapādau divasakṣaye
candrodaye samādhūtaṃ praticandrasamākulam', null, 6004078),
('ramayana-6-4-79', 79, 'Yuddha Kanda, Sarga 4, Verse 79', 'चण्डानिलमहाग्राहैः कीर्णं तिमितिमिंगिलैः।
दीप्तभोगैरिवाक्रीर्णं भुजंगैर्वरुणालयम्॥', 'caṇḍānilamahāgrāhaiḥ kīrṇaṃ timitimiṃgilaiḥ
dīptabhogair ivākrīrṇaṃ bhujaṃgair varuṇālayam', null, 6004079),
('ramayana-6-4-80', 80, 'Yuddha Kanda, Sarga 4, Verse 80', 'अवगाढं महासत्तैर्नानाशैलसमाकुलम्।
दुर्गं द्रुगममार्गं तमगाधमसुरालयम्॥', 'avagāḍhaṃ mahāsattair nānāśailasamākulam
durgaṃ drugam amārgaṃ tam agādham asurālayam', null, 6004080),
('ramayana-6-4-81', 81, 'Yuddha Kanda, Sarga 4, Verse 81', 'मकरैर्नागभोगैश्च विगाढा वातलोहिताः।
उत्पेतुश्च निपेतुश्च प्रवृद्धा जलराशयः॥', 'makarair nāgabhogaiś ca vigāḍhā vātalohitāḥ
utpetuś ca nipetuś ca pravṛddhā jalarāśayaḥ', null, 6004081),
('ramayana-6-4-82', 82, 'Yuddha Kanda, Sarga 4, Verse 82', 'अग्निचूर्णमिवाविद्धं भास्कराम्बुमनोरगम्।
सुरारिविषयं घोरं पातालविषमं सदा॥', 'agnicūrṇam ivāviddhaṃ bhāskarāmbumanoragam
surāriviṣayaṃ ghoraṃ pātālaviṣamaṃ sadā', null, 6004082),
('ramayana-6-4-83', 83, 'Yuddha Kanda, Sarga 4, Verse 83', 'सागरं चाम्बरप्रख्यमम्बरं सागरोपमम्।
सागरं चाम्बरं चेति निर्विशेषमदृश्यत॥', 'sāgaraṃ cāmbaraprakhyam ambaraṃ sāgaropamam
sāgaraṃ cāmbaraṃ ceti nirviśeṣam adṛśyata', null, 6004083),
('ramayana-6-4-84', 84, 'Yuddha Kanda, Sarga 4, Verse 84', 'संपृक्तं नभसा ह्यम्भः संपृक्तं च नभोऽम्भसा।
तादृग्रूपे स्म दृश्येते तारा रत्नसमाकुले॥', 'saṃpṛktaṃ nabhasā hy ambhaḥ saṃpṛktaṃ ca nabho ''mbhasā
tādṛgrūpe sma dṛśyete tārā ratnasamākule', null, 6004084),
('ramayana-6-4-85', 85, 'Yuddha Kanda, Sarga 4, Verse 85', 'समुत्पतितमेघस्य वीच्चि मालाकुलस्य च।
विशेषो न द्वयोरासीत्सागरस्याम्बरस्य च॥', 'samutpatitameghasya vīcci mālākulasya ca
viśeṣo na dvayor āsīt sāgarasyāmbarasya ca', null, 6004085),
('ramayana-6-4-86', 86, 'Yuddha Kanda, Sarga 4, Verse 86', 'अन्योन्यैराहताः सक्ताः सस्वनुर्भीमनिःस्वनाः।
ऊर्मयः सिन्धुराजस्य महाभेर्य इवाहवे॥', 'anyonyair āhatāḥ saktāḥ sasvanur bhīmaniḥsvanāḥ
ūrmayaḥ sindhurājasya mahābherya ivāhave', null, 6004086),
('ramayana-6-4-87', 87, 'Yuddha Kanda, Sarga 4, Verse 87', 'रत्नौघजलसंनादं विषक्तमिव वायुना।
उत्पतन्तमिव क्रुद्धं यादोगणसमाकुलम्॥', 'ratnaughajalasaṃnādaṃ viṣaktam iva vāyunā
utpatantam iva kruddhaṃ yādogaṇasamākulam', null, 6004087),
('ramayana-6-4-88', 88, 'Yuddha Kanda, Sarga 4, Verse 88', 'ददृशुस्ते महात्मानो वाताहतजलाशयम्।
अनिलोद्धूतमाकाशे प्रवल्गतमिवोर्मिभिः।
भ्रान्तोर्मिजलसंनादं प्रलोलमिव सागरम्॥', 'dadṛśus te mahātmāno vātāhatajalāśayam
aniloddhūtam ākāśe pravalgatam ivormibhiḥ
bhrāntormijalasaṃnādaṃ pralolam iva sāgaram', null, 6004088)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 5 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-5-1', 1, 'Yuddha Kanda, Sarga 5, Verse 1', 'सा तु नीलेन विधिवत्स्वारक्षा सुसमाहिता।
सागरस्योत्तरे तीरे साधु सेना निवेशिता॥', 'sā tu nīlena vidhivat svārakṣā susamāhitā
sāgarasyottare tīre sādhu senā niveśitā', null, 6005001),
('ramayana-6-5-2', 2, 'Yuddha Kanda, Sarga 5, Verse 2', 'मैन्दश्च द्विविधश्चोभौ तत्र वानरपुंगवौ।
विचेरतुश्च तां सेनां रक्षार्थं सर्वतो दिशम्॥', 'maindaś ca dvividhaś cobhau tatra vānarapuṃgavau
viceratuś ca tāṃ senāṃ rakṣārthaṃ sarvato diśam', null, 6005002),
('ramayana-6-5-3', 3, 'Yuddha Kanda, Sarga 5, Verse 3', 'निविष्टायां तु सेनायां तीरे नदनदीपतेः।
पार्श्वस्थं लक्ष्मणं दृष्ट्वा रामो वचनमब्रवीत्॥', 'niviṣṭāyāṃ tu senāyāṃ tīre nadanadīpateḥ
pārśvasthaṃ lakṣmaṇaṃ dṛṣṭvā rāmo vacanam abravīt', null, 6005003),
('ramayana-6-5-4', 4, 'Yuddha Kanda, Sarga 5, Verse 4', 'शोकश्च किल कालेन गच्छता ह्यपगच्छति।
मम चापश्यतः कान्तामहन्यहनि वर्धते॥', 'śokaś ca kila kālena gacchatā hy apagacchati
mama cāpaśyataḥ kāntām ahany ahani vardhate', null, 6005004),
('ramayana-6-5-5', 5, 'Yuddha Kanda, Sarga 5, Verse 5', 'न मे दुःखं प्रिया दूरे न मे दुःखं हृतेति च।
एतदेवानुशोचामि वयोऽस्या ह्यतिवर्तते॥', 'na me duḥkhaṃ priyā dūre na me duḥkhaṃ hṛteti ca
etad evānuśocāmi vayo ''syā hy ativartate', null, 6005005),
('ramayana-6-5-6', 6, 'Yuddha Kanda, Sarga 5, Verse 6', 'वाहि वात यतः कन्या तां स्पृष्ट्वा मामपि स्पृश।
त्वयि मे गात्रसंस्पर्शश्चन्द्रे दृष्टिसमागमः॥', 'vāhi vāta yataḥ kanyā tāṃ spṛṣṭvā mām api spṛśa
tvayi me gātrasaṃsparśaś candre dṛṣṭisamāgamaḥ', null, 6005006),
('ramayana-6-5-7', 7, 'Yuddha Kanda, Sarga 5, Verse 7', 'तन्मे दहति गात्राणि विषं पीतमिवाशये।
हा नाथेति प्रिया सा मां ह्रियमाणा यदब्रवीत्॥', 'tan me dahati gātrāṇi viṣaṃ pītam ivāśaye
hā nātheti priyā sā māṃ hriyamāṇā yad abravīt', null, 6005007),
('ramayana-6-5-8', 8, 'Yuddha Kanda, Sarga 5, Verse 8', 'तद्वियोगेन्धनवता तच्चिन्ताविपुलार्चिषा।
रात्रिं दिवं शरीरं मे दह्यते मदनाग्निना॥', 'tadviyogendhanavatā taccintāvipulārciṣā
rātriṃ divaṃ śarīraṃ me dahyate madanāgninā', null, 6005008),
('ramayana-6-5-9', 9, 'Yuddha Kanda, Sarga 5, Verse 9', 'अवगाह्यार्णवं स्वप्स्ये सौमित्रे भवता विना।
कथं चित्प्रज्वलन्कामः समासुप्तं जले दहेत्॥', 'avagāhyārṇavaṃ svapsye saumitre bhavatā vinā
kathaṃ cit prajvalan kāmaḥ samāsuptaṃ jale dahet', null, 6005009),
('ramayana-6-5-10', 10, 'Yuddha Kanda, Sarga 5, Verse 10', 'बह्वेतत्कामयानस्य शक्यमेतेन जीवितुम्।
यदहं सा च वामोरुरेकां धरणिमाश्रितौ॥', 'bahv etat kāmayānasya śakyam etena jīvitum
yad ahaṃ sā ca vāmorur ekāṃ dharaṇim āśritau', null, 6005010),
('ramayana-6-5-11', 11, 'Yuddha Kanda, Sarga 5, Verse 11', 'केदारस्येव केदारः सोदकस्य निरूदकः।
उपस्नेहेन जीवामि जीवन्तीं यच्छृणोमि ताम्॥', 'kedārasyeva kedāraḥ sodakasya nirūdakaḥ
upasnehena jīvāmi jīvantīṃ yac chṛṇomi tām', null, 6005011),
('ramayana-6-5-12', 12, 'Yuddha Kanda, Sarga 5, Verse 12', 'कदा तु खलु सुस्शोणीं शतपत्रायतेक्षणाम्।
विजित्य शत्रून्द्रक्ष्यामि सीतां स्फीतामिव श्रियम्॥', 'kadā tu khalu susśoṇīṃ śatapatrāyatekṣaṇām
vijitya śatrūn drakṣyāmi sītāṃ sphītām iva śriyam', null, 6005012),
('ramayana-6-5-13', 13, 'Yuddha Kanda, Sarga 5, Verse 13', 'कदा नु चारुबिम्बौष्ठं तस्याः पद्ममिवाननम्।
ईषदुन्नम्य पास्यामि रसायनमिवातुरः॥', 'kadā nu cārubimbauṣṭhaṃ tasyāḥ padmam ivānanam
īṣadunnamya pāsyāmi rasāyanam ivāturaḥ', null, 6005013),
('ramayana-6-5-14', 14, 'Yuddha Kanda, Sarga 5, Verse 14', 'तौ तस्याः संहतौ पीनौ स्तनौ तालफलोपमौ।
कदा नु खलु सोत्कम्पौ हसन्त्या मां भजिष्यतः॥', 'tau tasyāḥ saṃhatau pīnau stanau tālaphalopamau
kadā nu khalu sotkampau hasantyā māṃ bhajiṣyataḥ', null, 6005014),
('ramayana-6-5-15', 15, 'Yuddha Kanda, Sarga 5, Verse 15', 'सा नूनमसितापाङ्गी रक्षोमध्यगता सती।
मन्नाथा नाथहीनेव त्रातारं नाधिगच्छति॥', 'sā nūnam asitāpāṅgī rakṣomadhyagatā satī
mannāthā nāthahīneva trātāraṃ nādhigacchati', null, 6005015),
('ramayana-6-5-16', 16, 'Yuddha Kanda, Sarga 5, Verse 16', 'कदा विक्षोभ्य रक्षांसि सा विधूयोत्पतिष्यति।
विधूय जलदान्नीलाञ्शशिलेखा शरत्स्विव॥', 'kadā vikṣobhya rakṣāṃsi sā vidhūyotpatiṣyati
vidhūya jaladān nīlāñ śaśilekhā śaratsv iva', null, 6005016),
('ramayana-6-5-17', 17, 'Yuddha Kanda, Sarga 5, Verse 17', 'स्वभावतनुका नूनं शोकेनानशनेन च।
भूयस्तनुतरा सीता देशकालविपर्ययात्॥', 'svabhāvatanukā nūnaṃ śokenānaśanena ca
bhūyas tanutarā sītā deśakālaviparyayāt', null, 6005017),
('ramayana-6-5-18', 18, 'Yuddha Kanda, Sarga 5, Verse 18', 'कदा नु राक्षसेन्द्रस्य निधायोरसि सायकान्।
सीतां प्रत्याहरिष्यामि शोकमुत्सृज्य मानसं॥', 'kadā nu rākṣasendrasya nidhāyorasi sāyakān
sītāṃ pratyāhariṣyāmi śokam utsṛjya mānasaṃ', null, 6005018),
('ramayana-6-5-19', 19, 'Yuddha Kanda, Sarga 5, Verse 19', 'कदा नु खलु मां साध्वी सीतामरसुतोपमा।
सोत्कण्ठा कण्ठमालम्ब्य मोक्ष्यत्यानन्दजं जलम्॥', 'kadā nu khalu māṃ sādhvī sītāmarasutopamā
sotkaṇṭhā kaṇṭham ālambya mokṣyaty ānandajaṃ jalam', null, 6005019),
('ramayana-6-5-20', 20, 'Yuddha Kanda, Sarga 5, Verse 20', 'कदा शोकमिमं घोरं मैथिली विप्रयोगजम्।
सहसा विप्रमोक्ष्यामि वासः शुक्लेतरं यथा॥', 'kadā śokam imaṃ ghoraṃ maithilī viprayogajam
sahasā vipramokṣyāmi vāsaḥ śukletaraṃ yathā', null, 6005020),
('ramayana-6-5-21', 21, 'Yuddha Kanda, Sarga 5, Verse 21', 'एवं विलपतस्तस्य तत्र रामस्य धीमतः।
दिनक्षयान्मन्दवपुर्भास्करोऽस्तमुपागमत्॥', 'evaṃ vilapatas tasya tatra rāmasya dhīmataḥ
dinakṣayān mandavapur bhāskaro ''stam upāgamat', null, 6005021),
('ramayana-6-5-22', 22, 'Yuddha Kanda, Sarga 5, Verse 22', 'आश्वासितो लक्ष्मणेन रामः संध्यामुपासत।
स्मरन्कमलपत्राक्षीं सीतां शोकाकुलीकृतः॥', 'āśvāsito lakṣmaṇena rāmaḥ saṃdhyām upāsata
smaran kamalapatrākṣīṃ sītāṃ śokākulīkṛtaḥ', null, 6005022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 6 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-6-1', 1, 'Yuddha Kanda, Sarga 6, Verse 1', 'लङ्कायां तु कृतं कर्म घोरं दृष्ट्वा भवावहम्।
राक्षसेन्द्रो हनुमता शक्रेणेव महात्मना।
अब्रवीद्राक्षसान्सर्वान्ह्रिया किं चिदवाङ्मुखः॥', 'laṅkāyāṃ tu kṛtaṃ karma ghoraṃ dṛṣṭvā bhavāvaham
rākṣasendro hanumatā śakreṇeva mahātmanā
abravīd rākṣasān sarvān hriyā kiṃ cid avāṅmukhaḥ', null, 6006001),
('ramayana-6-6-2', 2, 'Yuddha Kanda, Sarga 6, Verse 2', 'धर्षिता च प्रविष्टा च लङ्का दुष्प्रसहा पुरी।
तेन वानरमात्रेण दृष्टा सीता च जानकी॥', 'dharṣitā ca praviṣṭā ca laṅkā duṣprasahā purī
tena vānaramātreṇa dṛṣṭā sītā ca jānakī', null, 6006002),
('ramayana-6-6-3', 3, 'Yuddha Kanda, Sarga 6, Verse 3', 'प्रसादो धर्षितश्चैत्यः प्रवरा राक्षसा हताः।
आविला च पुरी लङ्का सर्वा हनुमता कृता॥', 'prasādo dharṣitaś caityaḥ pravarā rākṣasā hatāḥ
āvilā ca purī laṅkā sarvā hanumatā kṛtā', null, 6006003),
('ramayana-6-6-4', 4, 'Yuddha Kanda, Sarga 6, Verse 4', 'किं करिष्यामि भद्रं वः किं वा युक्तमनन्तरम्।
उच्यतां नः समर्थं यत्कृतं च सुकृतं भवेत्॥', 'kiṃ kariṣyāmi bhadraṃ vaḥ kiṃ vā yuktam anantaram
ucyatāṃ naḥ samarthaṃ yat kṛtaṃ ca sukṛtaṃ bhavet', null, 6006004),
('ramayana-6-6-5', 5, 'Yuddha Kanda, Sarga 6, Verse 5', 'मन्त्रमूलं हि विजयं प्राहुरार्या मनस्विनः।
तस्माद्वै रोचये मन्त्रं रामं प्रति महाबलाः॥', 'mantramūlaṃ hi vijayaṃ prāhur āryā manasvinaḥ
tasmād vai rocaye mantraṃ rāmaṃ prati mahābalāḥ', null, 6006005),
('ramayana-6-6-6', 6, 'Yuddha Kanda, Sarga 6, Verse 6', 'त्रिविधाः पुरुषा लोके उत्तमाधममध्यमाः।
तेषां तु समवेतानां गुणदोषं वदाम्यहम्॥', 'trividhāḥ puruṣā loke uttamādhamamadhyamāḥ
teṣāṃ tu samavetānāṃ guṇadoṣaṃ vadāmy aham', null, 6006006),
('ramayana-6-6-7', 7, 'Yuddha Kanda, Sarga 6, Verse 7', 'मन्त्रिभिर्हितसंयुक्तैः समर्थैर्मन्त्रनिर्णये।
मित्रैर्वापि समानार्थैर्बान्धवैरपि वा हितैः॥', 'mantribhir hitasaṃyuktaiḥ samarthair mantranirṇaye
mitrair vāpi samānārthair bāndhavair api vā hitaiḥ', null, 6006007),
('ramayana-6-6-8', 8, 'Yuddha Kanda, Sarga 6, Verse 8', 'सहितो मन्त्रयित्वा यः कर्मारम्भान्प्रवर्तयेत्।
दैवे च कुरुते यत्नं तमाहुः पुरुषोत्तमम्॥', 'sahito mantrayitvā yaḥ karmārambhān pravartayet
daive ca kurute yatnaṃ tam āhuḥ puruṣottamam', null, 6006008),
('ramayana-6-6-9', 9, 'Yuddha Kanda, Sarga 6, Verse 9', 'एकोऽर्थं विमृशेदेको धर्मे प्रकुरुते मनः।
एकः कार्याणि कुरुते तमाहुर्मध्यमं नरम्॥', 'eko ''rthaṃ vimṛśed eko dharme prakurute manaḥ
ekaḥ kāryāṇi kurute tam āhur madhyamaṃ naram', null, 6006009),
('ramayana-6-6-10', 10, 'Yuddha Kanda, Sarga 6, Verse 10', 'गुणदोषावनिश्चित्य त्यक्त्वा दैवव्यपाश्रयम्।
करिष्यामीति यः कार्यमुपेक्षेत्स नराधमः॥', 'guṇadoṣāv aniścitya tyaktvā daivavyapāśrayam
kariṣyāmīti yaḥ kāryam upekṣet sa narādhamaḥ', null, 6006010),
('ramayana-6-6-11', 11, 'Yuddha Kanda, Sarga 6, Verse 11', 'यथेमे पुरुषा नित्यमुत्तमाधममध्यमाः।
एवं मन्त्रोऽपि विज्ञेय उत्तमाधममध्यमः॥', 'yatheme puruṣā nityam uttamādhamamadhyamāḥ
evaṃ mantro ''pi vijñeya uttamādhamamadhyamaḥ', null, 6006011),
('ramayana-6-6-12', 12, 'Yuddha Kanda, Sarga 6, Verse 12', 'ऐकमत्यमुपागम्य शास्त्रदृष्टेन चक्षुषा।
मन्त्रिणो यत्र निरस्तास्तमाहुर्मन्त्रमुत्तमम्॥', 'aikamatyam upāgamya śāstradṛṣṭena cakṣuṣā
mantriṇo yatra nirastās tam āhur mantram uttamam', null, 6006012),
('ramayana-6-6-13', 13, 'Yuddha Kanda, Sarga 6, Verse 13', 'बह्व्योऽपि मतयो गत्वा मन्त्रिणो ह्यर्थनिर्णये।
पुनर्यत्रैकतां प्राप्तः स मन्त्रो मध्यमः स्मृतः॥', 'bahvyo ''pi matayo gatvā mantriṇo hy arthanirṇaye
punar yatraikatāṃ prāptaḥ sa mantro madhyamaḥ smṛtaḥ', null, 6006013),
('ramayana-6-6-14', 14, 'Yuddha Kanda, Sarga 6, Verse 14', 'अन्योन्यमतिमास्थाय यत्र संप्रतिभाष्यते।
न चैकमत्ये श्रेयोऽस्ति मन्त्रः सोऽधम उच्यते॥', 'anyonyamatim āsthāya yatra saṃpratibhāṣyate
na caikamatye śreyo ''sti mantraḥ so ''dhama ucyate', null, 6006014),
('ramayana-6-6-15', 15, 'Yuddha Kanda, Sarga 6, Verse 15', 'तस्मात्सुमन्त्रितं साधु भवन्तो मन्त्रिसत्तमाः।
कार्यं संप्रतिपद्यन्तामेतत्कृत्यतमं मम॥', 'tasmāt sumantritaṃ sādhu bhavanto mantrisattamāḥ
kāryaṃ saṃpratipadyantām etat kṛtyatamaṃ mama', null, 6006015),
('ramayana-6-6-16', 16, 'Yuddha Kanda, Sarga 6, Verse 16', 'वानराणां हि वीराणां सहस्रैः परिवारितः।
रामोऽभ्येति पुरीं लङ्कामस्माकमुपरोधकः॥', 'vānarāṇāṃ hi vīrāṇāṃ sahasraiḥ parivāritaḥ
rāmo ''bhyeti purīṃ laṅkām asmākam uparodhakaḥ', null, 6006016),
('ramayana-6-6-17', 17, 'Yuddha Kanda, Sarga 6, Verse 17', 'तरिष्यति च सुव्यक्तं राघवः सागरं सुखम्।
तरसा युक्तरूपेण सानुजः सबलानुगः॥', 'tariṣyati ca suvyaktaṃ rāghavaḥ sāgaraṃ sukham
tarasā yuktarūpeṇa sānujaḥ sabalānugaḥ', null, 6006017),
('ramayana-6-6-18', 18, 'Yuddha Kanda, Sarga 6, Verse 18', 'अस्मिन्नेवंगते कार्ये विरुद्धे वानरैः सह।
हितं पुरे च सैन्ये च सर्वं संमन्त्र्यतां मम॥', 'asminn evaṃgate kārye viruddhe vānaraiḥ saha
hitaṃ pure ca sainye ca sarvaṃ saṃmantryatāṃ mama', null, 6006018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 7 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-7-1', 1, 'Yuddha Kanda, Sarga 7, Verse 1', 'इत्युक्ता राक्षसेन्द्रेण राक्षसास्ते महाबलाः।
ऊचुः प्राञ्जलयः सर्वे रावणं राक्षसेश्वरम्॥', 'ity uktā rākṣasendreṇa rākṣasās te mahābalāḥ
ūcuḥ prāñjalayaḥ sarve rāvaṇaṃ rākṣaseśvaram', null, 6007001),
('ramayana-6-7-2', 2, 'Yuddha Kanda, Sarga 7, Verse 2', 'राजन्परिघशक्त्यृष्टिशूलपट्टससंकुलम्।
सुमहन्नो बलं कस्माद्विषादं भजते भवान्॥', 'rājan parighaśaktyṛṣṭiśūlapaṭṭasasaṃkulam
sumahan no balaṃ kasmād viṣādaṃ bhajate bhavān', null, 6007002),
('ramayana-6-7-3', 3, 'Yuddha Kanda, Sarga 7, Verse 3', 'कैलासशिखरावासी यक्षैर्बहुभिरावृतः।
सुमहत्कदनं कृत्वा वश्यस्ते धनदः कृतः॥', 'kailāsaśikharāvāsī yakṣair bahubhir āvṛtaḥ
sumahat kadanaṃ kṛtvā vaśyas te dhanadaḥ kṛtaḥ', null, 6007003),
('ramayana-6-7-4', 4, 'Yuddha Kanda, Sarga 7, Verse 4', 'स महेश्वरसख्येन श्लाघमानस्त्वया विभो।
निर्जितः समरे रोषाल्लोकपालो महाबलः॥', 'sa maheśvarasakhyena ślāghamānas tvayā vibho
nirjitaḥ samare roṣāl lokapālo mahābalaḥ', null, 6007004),
('ramayana-6-7-5', 5, 'Yuddha Kanda, Sarga 7, Verse 5', 'विनिहत्य च यक्षौघान्विक्षोभ्य च विगृह्य च।
त्वया कैलासशिखराद्विमानमिदमाहृतम्॥', 'vinihatya ca yakṣaughān vikṣobhya ca vigṛhya ca
tvayā kailāsaśikharād vimānam idam āhṛtam', null, 6007005),
('ramayana-6-7-6', 6, 'Yuddha Kanda, Sarga 7, Verse 6', 'मयेन दानवेन्द्रेण त्वद्भयात्सख्यमिच्छता।
दुहिता तव भार्यार्थे दत्ता राक्षसपुंगव॥', 'mayena dānavendreṇa tvadbhayāt sakhyam icchatā
duhitā tava bhāryārthe dattā rākṣasapuṃgava', null, 6007006),
('ramayana-6-7-7', 7, 'Yuddha Kanda, Sarga 7, Verse 7', 'दानवेन्द्रो मधुर्नाम वीर्योत्सिक्तो दुरासदः।
विगृह्य वशमानीतः कुम्भीनस्याः सुखावहः॥', 'dānavendro madhur nāma vīryotsikto durāsadaḥ
vigṛhya vaśam ānītaḥ kumbhīnasyāḥ sukhāvahaḥ', null, 6007007),
('ramayana-6-7-8', 8, 'Yuddha Kanda, Sarga 7, Verse 8', 'निर्जितास्ते महाबाहो नागा गत्वा रसातलम्।
वासुकिस्तक्षकः शङ्खो जटी च वशमाहृताः॥', 'nirjitās te mahābāho nāgā gatvā rasātalam
vāsukis takṣakaḥ śaṅkho jaṭī ca vaśam āhṛtāḥ', null, 6007008),
('ramayana-6-7-9', 9, 'Yuddha Kanda, Sarga 7, Verse 9', 'अक्षया बलवन्तश्च शूरा लब्धवराः पुनः।
त्वया संवत्सरं युद्ध्वा समरे दानवा विभो॥', 'akṣayā balavantaś ca śūrā labdhavarāḥ punaḥ
tvayā saṃvatsaraṃ yuddhvā samare dānavā vibho', null, 6007009),
('ramayana-6-7-10', 10, 'Yuddha Kanda, Sarga 7, Verse 10', 'स्वबलं समुपाश्रित्य नीता वशमरिंदम।
मायाश्चाधिगतास्तत्र बहवो राक्षसाधिप॥', 'svabalaṃ samupāśritya nītā vaśam ariṃdama
māyāś cādhigatās tatra bahavo rākṣasādhipa', null, 6007010),
('ramayana-6-7-11', 11, 'Yuddha Kanda, Sarga 7, Verse 11', 'शूराश्च बलवन्तश्च वरुणस्य सुता रणे।
निर्जितास्ते महाबाहो चतुर्विधबलानुगाः॥', 'śūrāś ca balavantaś ca varuṇasya sutā raṇe
nirjitās te mahābāho caturvidhabalānugāḥ', null, 6007011),
('ramayana-6-7-12', 12, 'Yuddha Kanda, Sarga 7, Verse 12', 'मृत्युदण्डमहाग्राहं शाल्मलिद्वीपमण्डितम्।
अवगाह्य त्वया राजन्यमस्य बलसागरम्॥', 'mṛtyudaṇḍamahāgrāhaṃ śālmalidvīpamaṇḍitam
avagāhya tvayā rājan yamasya balasāgaram', null, 6007012),
('ramayana-6-7-13', 13, 'Yuddha Kanda, Sarga 7, Verse 13', 'जयश्च विप्लुलः प्राप्तो मृत्युश्च प्रतिषेधितः।
सुयुद्धेन च ते सर्वे लोकास्तत्र सुतोषिताः॥', 'jayaś ca viplulaḥ prāpto mṛtyuś ca pratiṣedhitaḥ
suyuddhena ca te sarve lokās tatra sutoṣitāḥ', null, 6007013),
('ramayana-6-7-14', 14, 'Yuddha Kanda, Sarga 7, Verse 14', 'क्षत्रियैर्बहुभिर्वीरैः शक्रतुल्यपराक्रमैः।
आसीद्वसुमती पूर्णा महद्भिरिव पादपैः॥', 'kṣatriyair bahubhir vīraiḥ śakratulyaparākramaiḥ
āsīd vasumatī pūrṇā mahadbhir iva pādapaiḥ', null, 6007014),
('ramayana-6-7-15', 15, 'Yuddha Kanda, Sarga 7, Verse 15', 'तेषां वीर्यगुणोत्साहैर्न समो राघवो रणे।
प्रसह्य ते त्वया राजन्हताः परमदुर्जयाः॥', 'teṣāṃ vīryaguṇotsāhair na samo rāghavo raṇe
prasahya te tvayā rājan hatāḥ paramadurjayāḥ', null, 6007015),
('ramayana-6-7-16', 16, 'Yuddha Kanda, Sarga 7, Verse 16', 'राजन्नापदयुक्तेयमागता प्राकृताज्जनात्।
हृदि नैव त्वया कार्या त्वं वधिष्यसि राघवम्॥', 'rājan nāpad ayukteyam āgatā prākṛtāj janāt
hṛdi naiva tvayā kāryā tvaṃ vadhiṣyasi rāghavam', null, 6007016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 8 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-8-1', 1, 'Yuddha Kanda, Sarga 8, Verse 1', 'ततो नीलाम्बुदनिभः प्रहस्तो नाम राक्षसः।
अब्रवीत्प्राञ्जलिर्वाक्यं शूरः सेनापतिस्तदा॥', 'tato nīlāmbudanibhaḥ prahasto nāma rākṣasaḥ
abravīt prāñjalir vākyaṃ śūraḥ senāpatis tadā', null, 6008001),
('ramayana-6-8-2', 2, 'Yuddha Kanda, Sarga 8, Verse 2', 'देवदानवगन्धर्वाः पिशाचपतगोरगाः।
न त्वां धर्षयितुं शक्ताः किं पुनर्वानरा रणे॥', 'devadānavagandharvāḥ piśācapatagoragāḥ
na tvāṃ dharṣayituṃ śaktāḥ kiṃ punar vānarā raṇe', null, 6008002),
('ramayana-6-8-3', 3, 'Yuddha Kanda, Sarga 8, Verse 3', 'सर्वे प्रमत्ता विश्वस्ता वञ्चिताः स्म हनूमता।
न हि मे जीवतो गच्छेज्जीवन्स वनगोचरः॥', 'sarve pramattā viśvastā vañcitāḥ sma hanūmatā
na hi me jīvato gacchej jīvan sa vanagocaraḥ', null, 6008003),
('ramayana-6-8-4', 4, 'Yuddha Kanda, Sarga 8, Verse 4', 'सर्वां सागरपर्यन्तां सशैलवनकाननाम्।
करोम्यवानरां भूमिमाज्ञापयतु मां भवान्॥', 'sarvāṃ sāgaraparyantāṃ saśailavanakānanām
karomy avānarāṃ bhūmim ājñāpayatu māṃ bhavān', null, 6008004),
('ramayana-6-8-5', 5, 'Yuddha Kanda, Sarga 8, Verse 5', 'रक्षां चैव विधास्यामि वानराद्रजनीचर।
नागमिष्यति ते दुःखं किं चिदात्मापराधजम्॥', 'rakṣāṃ caiva vidhāsyāmi vānarād rajanīcara
nāgamiṣyati te duḥkhaṃ kiṃ cid ātmāparādhajam', null, 6008005),
('ramayana-6-8-6', 6, 'Yuddha Kanda, Sarga 8, Verse 6', 'अब्रवीच्च सुसंक्रुद्धो दुर्मुखो नाम राक्षसः।
इदं न क्षमणीयं हि सर्वेषां नः प्रधर्षणम्॥', 'abravīc ca susaṃkruddho durmukho nāma rākṣasaḥ
idaṃ na kṣamaṇīyaṃ hi sarveṣāṃ naḥ pradharṣaṇam', null, 6008006),
('ramayana-6-8-7', 7, 'Yuddha Kanda, Sarga 8, Verse 7', 'अयं परिभवो भूयः पुरस्यान्तःपुरस्य च।
श्रीमतो राक्षसेन्द्रस्य वानरेन्द्रप्रधर्षणम्॥', 'ayaṃ paribhavo bhūyaḥ purasyāntaḥpurasya ca
śrīmato rākṣasendrasya vānarendrapradharṣaṇam', null, 6008007),
('ramayana-6-8-8', 8, 'Yuddha Kanda, Sarga 8, Verse 8', 'अस्मिन्मुहूर्ते हत्वैको निवर्तिष्यामि वानरान्।
प्रविष्टान्सागरं भीममम्बरं वा रसातलम्॥', 'asmin muhūrte hatvaiko nivartiṣyāmi vānarān
praviṣṭān sāgaraṃ bhīmam ambaraṃ vā rasātalam', null, 6008008),
('ramayana-6-8-9', 9, 'Yuddha Kanda, Sarga 8, Verse 9', 'ततोऽब्रवीत्सुसंक्रुद्धो वज्रदंष्ट्रो महाबलः।
प्रगृह्य परिघं घोरं मांसशोणितरूपितम्॥', 'tato ''bravīt susaṃkruddho vajradaṃṣṭro mahābalaḥ
pragṛhya parighaṃ ghoraṃ māṃsaśoṇitarūpitam', null, 6008009),
('ramayana-6-8-10', 10, 'Yuddha Kanda, Sarga 8, Verse 10', 'किं वो हनुमता कार्यं कृपणेन तपस्विना।
रामे तिष्ठति दुर्धर्षे सुग्रीवे सहलक्ष्मणे॥', 'kiṃ vo hanumatā kāryaṃ kṛpaṇena tapasvinā
rāme tiṣṭhati durdharṣe sugrīve sahalakṣmaṇe', null, 6008010),
('ramayana-6-8-11', 11, 'Yuddha Kanda, Sarga 8, Verse 11', 'अद्य रामं ससुग्रीवं परिघेण सलक्ष्मणम्।
आगमिष्यामि हत्वैको विक्षोभ्य हरिवाहिनीम्॥', 'adya rāmaṃ sasugrīvaṃ parigheṇa salakṣmaṇam
āgamiṣyāmi hatvaiko vikṣobhya harivāhinīm', null, 6008011),
('ramayana-6-8-12', 12, 'Yuddha Kanda, Sarga 8, Verse 12', 'कौम्भकर्णिस्ततो वीरो निकुम्भो नाम वीर्यवान्।
अब्रवीत्परमकुर्द्धो रावणं लोकरावणम्॥', 'kaumbhakarṇis tato vīro nikumbho nāma vīryavān
abravīt paramakurddho rāvaṇaṃ lokarāvaṇam', null, 6008012),
('ramayana-6-8-13', 13, 'Yuddha Kanda, Sarga 8, Verse 13', 'सर्वे भवन्तस्तिष्ठन्तु महाराजेन संगताः।
अहमेको हनिष्यामि राघवं सहलक्ष्मणम्॥', 'sarve bhavantas tiṣṭhantu mahārājena saṃgatāḥ
aham eko haniṣyāmi rāghavaṃ sahalakṣmaṇam', null, 6008013),
('ramayana-6-8-14', 14, 'Yuddha Kanda, Sarga 8, Verse 14', 'ततो वज्रहनुर्नाम राक्षसः पर्वतोपमः।
क्रुद्धः परिलिहन्वक्त्रं जिह्वया वाक्यमब्रवीत्॥', 'tato vajrahanur nāma rākṣasaḥ parvatopamaḥ
kruddhaḥ parilihan vaktraṃ jihvayā vākyam abravīt', null, 6008014),
('ramayana-6-8-15', 15, 'Yuddha Kanda, Sarga 8, Verse 15', 'स्वैरं कुर्वन्तु कार्याणि भवन्तो विगतज्वराः।
एकोऽहं भक्षयिष्यामि तान्सर्वान्हरियूथपान्॥', 'svairaṃ kurvantu kāryāṇi bhavanto vigatajvarāḥ
eko ''haṃ bhakṣayiṣyāmi tān sarvān hariyūthapān', null, 6008015),
('ramayana-6-8-16', 16, 'Yuddha Kanda, Sarga 8, Verse 16', 'स्वस्थाः क्रीडन्तु निश्चिन्ताः पिबन्तु मधुवारुणीम्।
अहमेको हनिष्यामि सुग्रीवं सहलक्ष्मणम्।
साङ्गदं च हनूमन्तं रामं च रणकुञ्जरम्॥', 'svasthāḥ krīḍantu niścintāḥ pibantu madhuvāruṇīm
aham eko haniṣyāmi sugrīvaṃ sahalakṣmaṇam
sāṅgadaṃ ca hanūmantaṃ rāmaṃ ca raṇakuñjaram', null, 6008016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 9 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-9-1', 1, 'Yuddha Kanda, Sarga 9, Verse 1', 'ततो निकुम्भो रभसः सूर्यशत्रुर्महाबलः।
सुप्तघ्नो यज्ञकोपश्च महापार्श्वो महोदरः॥', 'tato nikumbho rabhasaḥ sūryaśatrur mahābalaḥ
suptaghno yajñakopaś ca mahāpārśvo mahodaraḥ', null, 6009001),
('ramayana-6-9-2', 2, 'Yuddha Kanda, Sarga 9, Verse 2', 'अग्निकेतुश्च दुर्धर्षो रश्मिकेतुश्च राक्षसः।
इन्द्रजिच्च महातेजा बलवान्रावणात्मजः॥', 'agniketuś ca durdharṣo raśmiketuś ca rākṣasaḥ
indrajic ca mahātejā balavān rāvaṇātmajaḥ', null, 6009002),
('ramayana-6-9-3', 3, 'Yuddha Kanda, Sarga 9, Verse 3', 'प्रहस्तोऽथ विरूपाक्षो वज्रदंष्ट्रो महाबलः।
धूम्राक्षश्चातिकायश्च दुर्मुखश्चैव राक्षसः॥', 'prahasto ''tha virūpākṣo vajradaṃṣṭro mahābalaḥ
dhūmrākṣaś cātikāyaś ca durmukhaś caiva rākṣasaḥ', null, 6009003),
('ramayana-6-9-4', 4, 'Yuddha Kanda, Sarga 9, Verse 4', 'परिघान्पट्टसान्प्रासाञ्शक्तिशूलपरश्वधान्।
चापानि च सबाणानि खड्गांश्च विपुलाञ्शितान्॥', 'parighān paṭṭasān prāsāñ śaktiśūlaparaśvadhān
cāpāni ca sabāṇāni khaḍgāṃś ca vipulāñ śitān', null, 6009004),
('ramayana-6-9-5', 5, 'Yuddha Kanda, Sarga 9, Verse 5', 'प्रगृह्य परमक्रुद्धाः समुत्पत्य च राक्षसाः।
अब्रुवन्रावणं सर्वे प्रदीप्ता इव तेजसा॥', 'pragṛhya paramakruddhāḥ samutpatya ca rākṣasāḥ
abruvan rāvaṇaṃ sarve pradīptā iva tejasā', null, 6009005),
('ramayana-6-9-6', 6, 'Yuddha Kanda, Sarga 9, Verse 6', 'अद्य रामं वधिष्यामः सुग्रीवं च सलक्ष्मणम्।
कृपणं च हनूमन्तं लङ्का येन प्रधर्षिता॥', 'adya rāmaṃ vadhiṣyāmaḥ sugrīvaṃ ca salakṣmaṇam
kṛpaṇaṃ ca hanūmantaṃ laṅkā yena pradharṣitā', null, 6009006),
('ramayana-6-9-7', 7, 'Yuddha Kanda, Sarga 9, Verse 7', 'तान्गृहीतायुधान्सर्वान्वारयित्वा विभीषणः।
अब्रवीत्प्राञ्जलिर्वाक्यं पुनः प्रत्युपवेश्य तान्॥', 'tān gṛhītāyudhān sarvān vārayitvā vibhīṣaṇaḥ
abravīt prāñjalir vākyaṃ punaḥ pratyupaveśya tān', null, 6009007),
('ramayana-6-9-8', 8, 'Yuddha Kanda, Sarga 9, Verse 8', 'अप्युपायैस्त्रिभिस्तात योऽर्थः प्राप्तुं न शक्यते।
तस्य विक्रमकालांस्तान्युक्तानाहुर्मनीषिणः॥', 'apy upāyais tribhis tāta yo ''rthaḥ prāptuṃ na śakyate
tasya vikramakālāṃs tān yuktān āhur manīṣiṇaḥ', null, 6009008),
('ramayana-6-9-9', 9, 'Yuddha Kanda, Sarga 9, Verse 9', 'प्रमत्तेष्वभियुक्तेषु दैवेन प्रहतेषु च।
विक्रमास्तात सिध्यन्ति परीक्ष्य विधिना कृताः॥', 'pramatteṣv abhiyukteṣu daivena prahateṣu ca
vikramās tāta sidhyanti parīkṣya vidhinā kṛtāḥ', null, 6009009),
('ramayana-6-9-10', 10, 'Yuddha Kanda, Sarga 9, Verse 10', 'अप्रमत्तं कथं तं तु विजिगीषुं बले स्थितम्।
जितरोषं दुराधर्षं प्रधर्षयितुमिच्छथ॥', 'apramattaṃ kathaṃ taṃ tu vijigīṣuṃ bale sthitam
jitaroṣaṃ durādharṣaṃ pradharṣayitum icchatha', null, 6009010),
('ramayana-6-9-11', 11, 'Yuddha Kanda, Sarga 9, Verse 11', 'समुद्रं लङ्घयित्वा तु घोरं नदनदीपतिम्।
कृतं हनुमता कर्म दुष्करं तर्कयेत कः॥', 'samudraṃ laṅghayitvā tu ghoraṃ nadanadīpatim
kṛtaṃ hanumatā karma duṣkaraṃ tarkayeta kaḥ', null, 6009011),
('ramayana-6-9-12', 12, 'Yuddha Kanda, Sarga 9, Verse 12', 'बलान्यपरिमेयानि वीर्याणि च निशाचराः।
परेषां सहसावज्ञा न कर्तव्या कथं चन॥', 'balāny aparimeyāni vīryāṇi ca niśācarāḥ
pareṣāṃ sahasāvajñā na kartavyā kathaṃ cana', null, 6009012),
('ramayana-6-9-13', 13, 'Yuddha Kanda, Sarga 9, Verse 13', 'किं च राक्षसराजस्य रामेणापकृतं पुरा।
आजहार जनस्थानाद्यस्य भार्यां यशस्विनः॥', 'kiṃ ca rākṣasarājasya rāmeṇāpakṛtaṃ purā
ājahāra janasthānād yasya bhāryāṃ yaśasvinaḥ', null, 6009013),
('ramayana-6-9-14', 14, 'Yuddha Kanda, Sarga 9, Verse 14', 'खरो यद्यतिवृत्तस्तु रामेण निहतो रणे।
अवश्यं प्राणिनां प्राणा रक्षितव्या यथा बलम्॥', 'kharo yady ativṛttas tu rāmeṇa nihato raṇe
avaśyaṃ prāṇināṃ prāṇā rakṣitavyā yathā balam', null, 6009014),
('ramayana-6-9-15', 15, 'Yuddha Kanda, Sarga 9, Verse 15', 'एतन्निमित्तं वैदेही भयं नः सुमहद्भवेत्।
आहृता सा परित्याज्या कलहार्थे कृते न किम्॥', 'etannimittaṃ vaidehī bhayaṃ naḥ sumahad bhavet
āhṛtā sā parityājyā kalahārthe kṛte na kim', null, 6009015),
('ramayana-6-9-16', 16, 'Yuddha Kanda, Sarga 9, Verse 16', 'न नः क्षमं वीर्यवता तेन धर्मानुवर्तिना।
वैरं निरर्थकं कर्तुं दीयतामस्य मैथिली॥', 'na naḥ kṣamaṃ vīryavatā tena dharmānuvartinā
vairaṃ nirarthakaṃ kartuṃ dīyatām asya maithilī', null, 6009016),
('ramayana-6-9-17', 17, 'Yuddha Kanda, Sarga 9, Verse 17', 'यावन्न सगजां साश्वां बहुरत्नसमाकुलाम्।
पुरीं दारयते बाणैर्दीयतामस्य मैथिली॥', 'yāvan na sagajāṃ sāśvāṃ bahuratnasamākulām
purīṃ dārayate bāṇair dīyatām asya maithilī', null, 6009017),
('ramayana-6-9-18', 18, 'Yuddha Kanda, Sarga 9, Verse 18', 'यावत्सुघोरा महती दुर्धर्षा हरिवाहिनी।
नावस्कन्दति नो लङ्कां तावत्सीता प्रदीयताम्॥', 'yāvat sughorā mahatī durdharṣā harivāhinī
nāvaskandati no laṅkāṃ tāvat sītā pradīyatām', null, 6009018),
('ramayana-6-9-19', 19, 'Yuddha Kanda, Sarga 9, Verse 19', 'विनश्येद्धि पुरी लङ्का शूराः सर्वे च राक्षसाः।
रामस्य दयिता पत्नी न स्वयं यदि दीयते॥', 'vinaśyed dhi purī laṅkā śūrāḥ sarve ca rākṣasāḥ
rāmasya dayitā patnī na svayaṃ yadi dīyate', null, 6009019),
('ramayana-6-9-20', 20, 'Yuddha Kanda, Sarga 9, Verse 20', 'प्रसादये त्वां बन्धुत्वात्कुरुष्व वचनं मम।
हितं पथ्यं त्वहं ब्रूमि दीयतामस्य मैथिली॥', 'prasādaye tvāṃ bandhutvāt kuruṣva vacanaṃ mama
hitaṃ pathyaṃ tv ahaṃ brūmi dīyatām asya maithilī', null, 6009020),
('ramayana-6-9-21', 21, 'Yuddha Kanda, Sarga 9, Verse 21', 'पुरा शरत्सूर्यमरीचिसंनिभान्नवाग्रपुङ्खान्सुदृढान्नृपात्मजः।
सृजत्यमोघान्विशिखान्वधाय ते प्रदीयतां दाशरथाय मैथिली॥', 'purā śaratsūryamarīcisaṃnibhān navāgrapuṅkhān sudṛḍhān nṛpātmajaḥ
sṛjaty amoghān viśikhān vadhāya te pradīyatāṃ dāśarathāya maithilī', null, 6009021),
('ramayana-6-9-22', 22, 'Yuddha Kanda, Sarga 9, Verse 22', 'त्यजस्व कोपं सुखधर्मनाशनं भजस्व धर्मं रतिकीर्तिवर्धनम्।
प्रसीद जीवेम सपुत्रबान्धवाः प्रदीयतां दाशरथाय मैथिली॥', 'tyajasva kopaṃ sukhadharmanāśanaṃ bhajasva dharmaṃ ratikīrtivardhanam
prasīda jīvema saputrabāndhavāḥ pradīyatāṃ dāśarathāya maithilī', null, 6009022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 10 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-10-1', 1, 'Yuddha Kanda, Sarga 10, Verse 1', 'सुनिविष्टं हितं वाक्यमुक्तवन्तं विभीषणम्।
अब्रवीत्परुषं वाक्यं रावणः कालचोदितः॥', 'suniviṣṭaṃ hitaṃ vākyam uktavantaṃ vibhīṣaṇam
abravīt paruṣaṃ vākyaṃ rāvaṇaḥ kālacoditaḥ', null, 6010001),
('ramayana-6-10-2', 2, 'Yuddha Kanda, Sarga 10, Verse 2', 'वसेत्सह सपत्नेन क्रुद्धेनाशीविषेण वा।
न तु मित्रप्रवादेन संवसेच्छत्रुसेविना॥', 'vaset saha sapatnena kruddhenāśīviṣeṇa vā
na tu mitrapravādena saṃvasec chatrusevinā', null, 6010002),
('ramayana-6-10-3', 3, 'Yuddha Kanda, Sarga 10, Verse 3', 'जानामि शीलं ज्ञातीनां सर्वलोकेषु राक्षस।
हृष्यन्ति व्यसनेष्वेते ज्ञातीनां ज्ञातयः सदा॥', 'jānāmi śīlaṃ jñātīnāṃ sarvalokeṣu rākṣasa
hṛṣyanti vyasaneṣv ete jñātīnāṃ jñātayaḥ sadā', null, 6010003),
('ramayana-6-10-4', 4, 'Yuddha Kanda, Sarga 10, Verse 4', 'प्रधानं साधकं वैद्यं धर्मशीलं च राक्षस।
ज्ञातयो ह्यवमन्यन्ते शूरं परिभवन्ति च॥', 'pradhānaṃ sādhakaṃ vaidyaṃ dharmaśīlaṃ ca rākṣasa
jñātayo hy avamanyante śūraṃ paribhavanti ca', null, 6010004),
('ramayana-6-10-5', 5, 'Yuddha Kanda, Sarga 10, Verse 5', 'नित्यमन्योन्यसंहृष्टा व्यसनेष्वाततायिनः।
प्रच्छन्नहृदया घोरा ज्ञातयस्तु भयावहाः॥', 'nityam anyonyasaṃhṛṣṭā vyasaneṣv ātatāyinaḥ
pracchannahṛdayā ghorā jñātayas tu bhayāvahāḥ', null, 6010005),
('ramayana-6-10-6', 6, 'Yuddha Kanda, Sarga 10, Verse 6', 'श्रूयन्ते हस्तिभिर्गीताः श्लोकाः पद्मवने क्व चित्।
पाशहस्तान्नरान्दृष्ट्वा शृणु तान्गदतो मम॥', 'śrūyante hastibhir gītāḥ ślokāḥ padmavane kva cit
pāśahastān narān dṛṣṭvā śṛṇu tān gadato mama', null, 6010006),
('ramayana-6-10-7', 7, 'Yuddha Kanda, Sarga 10, Verse 7', 'नाग्निर्नान्यानि शस्त्राणि न नः पाशा भयावहाः।
घोराः स्वार्थप्रयुक्तास्तु ज्ञातयो नो भयावहाः॥', 'nāgnir nānyāni śastrāṇi na naḥ pāśā bhayāvahāḥ
ghorāḥ svārthaprayuktās tu jñātayo no bhayāvahāḥ', null, 6010007),
('ramayana-6-10-8', 8, 'Yuddha Kanda, Sarga 10, Verse 8', 'उपायमेते वक्ष्यन्ति ग्रहणे नात्र संशयः।
कृत्स्नाद्भयाज्ज्ञातिभयं सुकष्टं विदितं च नः॥', 'upāyam ete vakṣyanti grahaṇe nātra saṃśayaḥ
kṛtsnād bhayāj jñātibhayaṃ sukaṣṭaṃ viditaṃ ca naḥ', null, 6010008),
('ramayana-6-10-9', 9, 'Yuddha Kanda, Sarga 10, Verse 9', 'विद्यते गोषु संपन्नं विद्यते ब्राह्मणे दमः।
विद्यते स्त्रीषु चापल्यं विद्यते ज्ञातितो भयम्॥', 'vidyate goṣu saṃpannaṃ vidyate brāhmaṇe damaḥ
vidyate strīṣu cāpalyaṃ vidyate jñātito bhayam', null, 6010009),
('ramayana-6-10-10', 10, 'Yuddha Kanda, Sarga 10, Verse 10', 'ततो नेष्टमिदं सौम्य यदहं लोकसत्कृतः।
ऐश्वर्यमभिजातश्च रिपूणां मूर्ध्नि च स्थितः॥', 'tato neṣṭam idaṃ saumya yad ahaṃ lokasatkṛtaḥ
aiśvaryam abhijātaś ca ripūṇāṃ mūrdhni ca sthitaḥ', null, 6010010),
('ramayana-6-10-11', 11, 'Yuddha Kanda, Sarga 10, Verse 11', 'अन्यस्त्वेवंविधं ब्रूयाद्वाक्यमेतन्निशाचर।
अस्मिन्मुहूर्ते न भवेत्त्वां तु धिक्कुलपांसनम्॥', 'anyas tv evaṃvidhaṃ brūyād vākyam etan niśācara
asmin muhūrte na bhavet tvāṃ tu dhik kulapāṃsanam', null, 6010011),
('ramayana-6-10-12', 12, 'Yuddha Kanda, Sarga 10, Verse 12', 'इत्युक्तः परुषं वाक्यं न्यायवादी विभीषणः।
उत्पपात गदापाणिश्चतुर्भिः सह राक्षसैः॥', 'ity uktaḥ paruṣaṃ vākyaṃ nyāyavādī vibhīṣaṇaḥ
utpapāta gadāpāṇiś caturbhiḥ saha rākṣasaiḥ', null, 6010012),
('ramayana-6-10-13', 13, 'Yuddha Kanda, Sarga 10, Verse 13', 'अब्रवीच्च तदा वाक्यं जातक्रोधो विभीषणः।
अन्तरिक्षगतः श्रीमान्भ्रातरं राक्षसाधिपम्॥', 'abravīc ca tadā vākyaṃ jātakrodho vibhīṣaṇaḥ
antarikṣagataḥ śrīmān bhrātaraṃ rākṣasādhipam', null, 6010013),
('ramayana-6-10-14', 14, 'Yuddha Kanda, Sarga 10, Verse 14', 'स त्वं भ्रातासि मे राजन्ब्रूहि मां यद्यदिच्छसि।
इदं तु परुषं वाक्यं न क्षमाम्यनृतं तव॥', 'sa tvaṃ bhrātāsi me rājan brūhi māṃ yad yad icchasi
idaṃ tu paruṣaṃ vākyaṃ na kṣamāmy anṛtaṃ tava', null, 6010014),
('ramayana-6-10-15', 15, 'Yuddha Kanda, Sarga 10, Verse 15', 'सुनीतं हितकामेन वाक्यमुक्तं दशानन।
न गृह्णन्त्यकृतात्मानः कालस्य वशमागताः॥', 'sunītaṃ hitakāmena vākyam uktaṃ daśānana
na gṛhṇanty akṛtātmānaḥ kālasya vaśam āgatāḥ', null, 6010015),
('ramayana-6-10-16', 16, 'Yuddha Kanda, Sarga 10, Verse 16', 'सुलभाः पुरुषा राजन्सततं प्रियवादिनः।
अप्रियस्य तु पथ्यस्य वक्ता श्रोता च दुर्लभः॥', 'sulabhāḥ puruṣā rājan satataṃ priyavādinaḥ
apriyasya tu pathyasya vaktā śrotā ca durlabhaḥ', null, 6010016),
('ramayana-6-10-17', 17, 'Yuddha Kanda, Sarga 10, Verse 17', 'बद्धं कालस्य पाशेन सर्वभूतापहारिणा।
न नश्यन्तमुपेक्षेयं प्रदीप्तं शरणं यथा॥', 'baddhaṃ kālasya pāśena sarvabhūtāpahāriṇā
na naśyantam upekṣeyaṃ pradīptaṃ śaraṇaṃ yathā', null, 6010017),
('ramayana-6-10-18', 18, 'Yuddha Kanda, Sarga 10, Verse 18', 'दीप्तपावकसंकाशैः शितैः काञ्चनभूषणैः।
न त्वामिच्छाम्यहं द्रष्टुं रामेण निहतं शरैः॥', 'dīptapāvakasaṃkāśaiḥ śitaiḥ kāñcanabhūṣaṇaiḥ
na tvām icchāmy ahaṃ draṣṭuṃ rāmeṇa nihataṃ śaraiḥ', null, 6010018),
('ramayana-6-10-19', 19, 'Yuddha Kanda, Sarga 10, Verse 19', 'शूराश्च बलवन्तश्च कृतास्त्राश्च रणाजिरे।
कालाभिपन्ना सीदन्ति यथा वालुकसेतवः॥', 'śūrāś ca balavantaś ca kṛtāstrāś ca raṇājire
kālābhipannā sīdanti yathā vālukasetavaḥ', null, 6010019),
('ramayana-6-10-20', 20, 'Yuddha Kanda, Sarga 10, Verse 20', 'आत्मानं सर्वथा रक्ष पुरीं चेमां सराक्षसाम्।
स्वस्ति तेऽस्तु गमिष्यामि सुखी भव मया विना॥', 'ātmānaṃ sarvathā rakṣa purīṃ cemāṃ sarākṣasām
svasti te ''stu gamiṣyāmi sukhī bhava mayā vinā', null, 6010020),
('ramayana-6-10-21', 21, 'Yuddha Kanda, Sarga 10, Verse 21', 'निवार्यमाणस्य मया हितैषिणा न रोचते ते वचनं निशाचर।
परीतकाला हि गतायुषो नरा हितं न गृह्णन्ति सुहृद्भिरीरितम्॥', 'nivāryamāṇasya mayā hitaiṣiṇā na rocate te vacanaṃ niśācara
parītakālā hi gatāyuṣo narā hitaṃ na gṛhṇanti suhṛdbhir īritam', null, 6010021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 11 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-11-1', 1, 'Yuddha Kanda, Sarga 11, Verse 1', 'इत्युक्त्वा परुषं वाक्यं रावणं रावणानुजः।
आजगाम मुहूर्तेन यत्र रामः सलक्ष्मणः॥', 'ity uktvā paruṣaṃ vākyaṃ rāvaṇaṃ rāvaṇānujaḥ
ājagāma muhūrtena yatra rāmaḥ salakṣmaṇaḥ', null, 6011001),
('ramayana-6-11-2', 2, 'Yuddha Kanda, Sarga 11, Verse 2', 'तं मेरुशिखराकारं दीप्तामिव शतह्रदाम्।
गगनस्थं महीस्थास्ते ददृशुर्वानराधिपाः॥', 'taṃ meruśikharākāraṃ dīptām iva śatahradām
gaganasthaṃ mahīsthās te dadṛśur vānarādhipāḥ', null, 6011002),
('ramayana-6-11-3', 3, 'Yuddha Kanda, Sarga 11, Verse 3', 'तमात्मपञ्चमं दृष्ट्वा सुग्रीवो वानराधिपः।
वानरैः सह दुर्धर्षश्चिन्तयामास बुद्धिमान्॥', 'tam ātmapañcamaṃ dṛṣṭvā sugrīvo vānarādhipaḥ
vānaraiḥ saha durdharṣaś cintayām āsa buddhimān', null, 6011003),
('ramayana-6-11-4', 4, 'Yuddha Kanda, Sarga 11, Verse 4', 'चिन्तयित्वा मुहूर्तं तु वानरांस्तानुवाच ह।
हनूमत्प्रमुखान्सर्वानिदं वचनमुत्तमम्॥', 'cintayitvā muhūrtaṃ tu vānarāṃs tān uvāca ha
hanūmatpramukhān sarvān idaṃ vacanam uttamam', null, 6011004),
('ramayana-6-11-5', 5, 'Yuddha Kanda, Sarga 11, Verse 5', 'एष सर्वायुधोपेतश्चतुर्भिः सह राक्षसैः।
राक्षसोऽभ्येति पश्यध्वमस्मान्हन्तुं न संशयः॥', 'eṣa sarvāyudhopetaś caturbhiḥ saha rākṣasaiḥ
rākṣaso ''bhyeti paśyadhvam asmān hantuṃ na saṃśayaḥ', null, 6011005),
('ramayana-6-11-6', 6, 'Yuddha Kanda, Sarga 11, Verse 6', 'सुग्रीवस्य वचः श्रुत्वा सर्वे ते वानरोत्तमाः।
सालानुद्यम्य शैलांश्च इदं वचनमब्रुवन्॥', 'sugrīvasya vacaḥ śrutvā sarve te vānarottamāḥ
sālān udyamya śailāṃś ca idaṃ vacanam abruvan', null, 6011006),
('ramayana-6-11-7', 7, 'Yuddha Kanda, Sarga 11, Verse 7', 'शीघ्रं व्यादिश नो राजन्वधायैषां दुरात्मनाम्।
निपतन्तु हताश्चैते धरण्यामल्पजीविताः॥', 'śīghraṃ vyādiśa no rājan vadhāyaiṣāṃ durātmanām
nipatantu hatāś caite dharaṇyām alpajīvitāḥ', null, 6011007),
('ramayana-6-11-8', 8, 'Yuddha Kanda, Sarga 11, Verse 8', 'तेषां संभाषमाणानामन्योन्यं स विभीषणः।
उत्तरं तीरमासाद्य खस्थ एव व्यतिष्ठत॥', 'teṣāṃ saṃbhāṣamāṇānām anyonyaṃ sa vibhīṣaṇaḥ
uttaraṃ tīram āsādya khastha eva vyatiṣṭhata', null, 6011008),
('ramayana-6-11-9', 9, 'Yuddha Kanda, Sarga 11, Verse 9', 'उवाच च महाप्राज्ञः स्वरेण महता महान्।
सुग्रीवं तांश्च संप्रेक्ष्य खस्थ एव विभीषणः॥', 'uvāca ca mahāprājñaḥ svareṇa mahatā mahān
sugrīvaṃ tāṃś ca saṃprekṣya khastha eva vibhīṣaṇaḥ', null, 6011009),
('ramayana-6-11-10', 10, 'Yuddha Kanda, Sarga 11, Verse 10', 'रावणो नाम दुर्वृत्तो राक्षसो राक्षसेश्वरः।
तस्याहमनुजो भ्राता विभीषण इति श्रुतः॥', 'rāvaṇo nāma durvṛtto rākṣaso rākṣaseśvaraḥ
tasyāham anujo bhrātā vibhīṣaṇa iti śrutaḥ', null, 6011010),
('ramayana-6-11-11', 11, 'Yuddha Kanda, Sarga 11, Verse 11', 'तेन सीता जनस्थानाद्धृता हत्वा जटायुषम्।
रुद्ध्वा च विवशा दीना राक्षसीभिः सुरक्षिता॥', 'tena sītā janasthānād dhṛtā hatvā jaṭāyuṣam
ruddhvā ca vivaśā dīnā rākṣasībhiḥ surakṣitā', null, 6011011),
('ramayana-6-11-12', 12, 'Yuddha Kanda, Sarga 11, Verse 12', 'तमहं हेतुभिर्वाक्यैर्विविधैश्च न्यदर्शयम्।
साधु निर्यात्यतां सीता रामायेति पुनः पुनः॥', 'tam ahaṃ hetubhir vākyair vividhaiś ca nyadarśayam
sādhu niryātyatāṃ sītā rāmāyeti punaḥ punaḥ', null, 6011012),
('ramayana-6-11-13', 13, 'Yuddha Kanda, Sarga 11, Verse 13', 'स च न प्रतिजग्राह रावणः कालचोदितः।
उच्यमानो हितं वाक्यं विपरीत इवौषधम्॥', 'sa ca na pratijagrāha rāvaṇaḥ kālacoditaḥ
ucyamāno hitaṃ vākyaṃ viparīta ivauṣadham', null, 6011013),
('ramayana-6-11-14', 14, 'Yuddha Kanda, Sarga 11, Verse 14', 'सोऽहं परुषितस्तेन दासवच्चावमानितः।
त्यक्त्वा पुत्रांश्च दारांश्च राघवं शरणं गतः॥', 'so ''haṃ paruṣitas tena dāsavac cāvamānitaḥ
tyaktvā putrāṃś ca dārāṃś ca rāghavaṃ śaraṇaṃ gataḥ', null, 6011014),
('ramayana-6-11-15', 15, 'Yuddha Kanda, Sarga 11, Verse 15', 'सर्वलोकशरण्याय राघवाय महात्मने।
निवेदयत मां क्षिप्रं विभीषणमुपस्थितम्॥', 'sarvalokaśaraṇyāya rāghavāya mahātmane
nivedayata māṃ kṣipraṃ vibhīṣaṇam upasthitam', null, 6011015),
('ramayana-6-11-16', 16, 'Yuddha Kanda, Sarga 11, Verse 16', 'एतत्तु वचनं श्रुत्वा सुग्रीवो लघुविक्रमः।
लक्ष्मणस्याग्रतो रामं संरब्धमिदमब्रवीत्॥', 'etat tu vacanaṃ śrutvā sugrīvo laghuvikramaḥ
lakṣmaṇasyāgrato rāmaṃ saṃrabdham idam abravīt', null, 6011016),
('ramayana-6-11-17', 17, 'Yuddha Kanda, Sarga 11, Verse 17', 'रावणस्यानुजो भ्राता विभीषण इति श्रुतः।
चतुर्भिः सह रक्षोभिर्भवन्तं शरणं गतः॥', 'rāvaṇasyānujo bhrātā vibhīṣaṇa iti śrutaḥ
caturbhiḥ saha rakṣobhir bhavantaṃ śaraṇaṃ gataḥ', null, 6011017),
('ramayana-6-11-18', 18, 'Yuddha Kanda, Sarga 11, Verse 18', 'रावणेन प्रणिहितं तमवेहि विभीषणम्।
तस्याहं निग्रहं मन्ये क्षमं क्षमवतां वर॥', 'rāvaṇena praṇihitaṃ tam avehi vibhīṣaṇam
tasyāhaṃ nigrahaṃ manye kṣamaṃ kṣamavatāṃ vara', null, 6011018),
('ramayana-6-11-19', 19, 'Yuddha Kanda, Sarga 11, Verse 19', 'राक्षसो जिह्मया बुद्ध्या संदिष्टोऽयमुपस्थितः।
प्रहर्तुं मायया छन्नो विश्वस्ते त्वयि राघव॥', 'rākṣaso jihmayā buddhyā saṃdiṣṭo ''yam upasthitaḥ
prahartuṃ māyayā channo viśvaste tvayi rāghava', null, 6011019),
('ramayana-6-11-20', 20, 'Yuddha Kanda, Sarga 11, Verse 20', 'बध्यतामेष तीव्रेण दण्डेन सचिवैः सह।
रावणस्य नृशंसस्य भ्राता ह्येष विभीषणः॥', 'badhyatām eṣa tīvreṇa daṇḍena sacivaiḥ saha
rāvaṇasya nṛśaṃsasya bhrātā hy eṣa vibhīṣaṇaḥ', null, 6011020),
('ramayana-6-11-21', 21, 'Yuddha Kanda, Sarga 11, Verse 21', 'एवमुक्त्वा तु तं रामं संरब्धो वाहिनीपतिः।
वाक्यज्ञो वाक्यकुशलं ततो मौनमुपागमत्॥', 'evam uktvā tu taṃ rāmaṃ saṃrabdho vāhinīpatiḥ
vākyajño vākyakuśalaṃ tato maunam upāgamat', null, 6011021),
('ramayana-6-11-22', 22, 'Yuddha Kanda, Sarga 11, Verse 22', 'सुग्रीवस्य तु तद्वाक्यं श्रुत्वा रामो महाबलः।
समीपस्थानुवाचेदं हनूमत्प्रमुखान्हरीन्॥', 'sugrīvasya tu tad vākyaṃ śrutvā rāmo mahābalaḥ
samīpasthān uvācedaṃ hanūmatpramukhān harīn', null, 6011022),
('ramayana-6-11-23', 23, 'Yuddha Kanda, Sarga 11, Verse 23', 'यदुक्तं कपिराजेन रावणावरजं प्रति।
वाक्यं हेतुमदत्यर्थं भवद्भिरपि तच्छ्रुतम्॥', 'yad uktaṃ kapirājena rāvaṇāvarajaṃ prati
vākyaṃ hetumad atyarthaṃ bhavadbhir api tac chrutam', null, 6011023),
('ramayana-6-11-24', 24, 'Yuddha Kanda, Sarga 11, Verse 24', 'सुहृदा ह्यर्थकृच्छेषु युक्तं बुद्धिमता सता।
समर्थेनापि संदेष्टुं शाश्वतीं भूतिमिच्छता॥', 'suhṛdā hy arthakṛccheṣu yuktaṃ buddhimatā satā
samarthenāpi saṃdeṣṭuṃ śāśvatīṃ bhūtim icchatā', null, 6011024),
('ramayana-6-11-25', 25, 'Yuddha Kanda, Sarga 11, Verse 25', 'इत्येवं परिपृष्टास्ते स्वं स्वं मतमतन्द्रिताः।
सोपचारं तदा राममूचुर्हितचिकीर्षवः॥', 'ity evaṃ paripṛṣṭās te svaṃ svaṃ matam atandritāḥ
sopacāraṃ tadā rāmam ūcur hitacikīrṣavaḥ', null, 6011025),
('ramayana-6-11-26', 26, 'Yuddha Kanda, Sarga 11, Verse 26', 'अज्ञातं नास्ति ते किं चित्त्रिषु लोकेषु राघव।
आत्मानं पूजयन्राम पृच्छस्यस्मान्सुहृत्तया॥', 'ajñātaṃ nāsti te kiṃ cit triṣu lokeṣu rāghava
ātmānaṃ pūjayan rāma pṛcchasy asmān suhṛttayā', null, 6011026),
('ramayana-6-11-27', 27, 'Yuddha Kanda, Sarga 11, Verse 27', 'त्वं हि सत्यव्रतः शूरो धार्मिको दृढविक्रमः।
परीक्ष्य कारा स्मृतिमान्निसृष्टात्मा सुहृत्सु च॥', 'tvaṃ hi satyavrataḥ śūro dhārmiko dṛḍhavikramaḥ
parīkṣya kārā smṛtimān nisṛṣṭātmā suhṛtsu ca', null, 6011027),
('ramayana-6-11-28', 28, 'Yuddha Kanda, Sarga 11, Verse 28', 'तस्मादेकैकशस्तावद्ब्रुवन्तु सचिवास्तव।
हेतुतो मतिसंपन्नाः समर्थाश्च पुनः पुनः॥', 'tasmād ekaikaśas tāvad bruvantu sacivās tava
hetuto matisaṃpannāḥ samarthāś ca punaḥ punaḥ', null, 6011028),
('ramayana-6-11-29', 29, 'Yuddha Kanda, Sarga 11, Verse 29', 'इत्युक्ते राघवायाथ मतिमानङ्गदोऽग्रतः।
विभीषणपरीक्षार्थमुवाच वचनं हरिः॥', 'ity ukte rāghavāyātha matimān aṅgado ''grataḥ
vibhīṣaṇaparīkṣārtham uvāca vacanaṃ hariḥ', null, 6011029),
('ramayana-6-11-30', 30, 'Yuddha Kanda, Sarga 11, Verse 30', 'शत्रोः सकाशात्संप्राप्तः सर्वथा शङ्क्य एव हि।
विश्वासयोग्यः सहसा न कर्तव्यो विभीषणः॥', 'śatroḥ sakāśāt saṃprāptaḥ sarvathā śaṅkya eva hi
viśvāsayogyaḥ sahasā na kartavyo vibhīṣaṇaḥ', null, 6011030),
('ramayana-6-11-31', 31, 'Yuddha Kanda, Sarga 11, Verse 31', 'छादयित्वात्मभावं हि चरन्ति शठबुद्धयः।
प्रहरन्ति च रन्ध्रेषु सोऽनर्थः सुमहान्भवेत्॥', 'chādayitvātmabhāvaṃ hi caranti śaṭhabuddhayaḥ
praharanti ca randhreṣu so ''narthaḥ sumahān bhavet', null, 6011031),
('ramayana-6-11-32', 32, 'Yuddha Kanda, Sarga 11, Verse 32', 'अर्थानर्थौ विनिश्चित्य व्यवसायं भजेत ह।
गुणतः संग्रहं कुर्याद्दोषतस्तु विसर्जयेत्॥', 'arthānarthau viniścitya vyavasāyaṃ bhajeta ha
guṇataḥ saṃgrahaṃ kuryād doṣatas tu visarjayet', null, 6011032),
('ramayana-6-11-33', 33, 'Yuddha Kanda, Sarga 11, Verse 33', 'यदि दोषो महांस्तस्मिंस्त्यज्यतामविशङ्कितम्।
गुणान्वापि बहूञ्ज्ञात्वा संग्रहः क्रियतां नृप॥', 'yadi doṣo mahāṃs tasmiṃs tyajyatām aviśaṅkitam
guṇān vāpi bahūñ jñātvā saṃgrahaḥ kriyatāṃ nṛpa', null, 6011033),
('ramayana-6-11-34', 34, 'Yuddha Kanda, Sarga 11, Verse 34', 'शरभस्त्वथ निश्चित्य सार्थं वचनमब्रवीत्।
क्षिप्रमस्मिन्नरव्याघ्र चारः प्रतिविधीयताम्॥', 'śarabhas tv atha niścitya sārthaṃ vacanam abravīt
kṣipram asmin naravyāghra cāraḥ pratividhīyatām', null, 6011034),
('ramayana-6-11-35', 35, 'Yuddha Kanda, Sarga 11, Verse 35', 'प्रणिधाय हि चारेण यथावत्सूक्ष्मबुद्धिना।
परीक्ष्य च ततः कार्यो यथान्यायं परिग्रहः॥', 'praṇidhāya hi cāreṇa yathāvat sūkṣmabuddhinā
parīkṣya ca tataḥ kāryo yathānyāyaṃ parigrahaḥ', null, 6011035),
('ramayana-6-11-36', 36, 'Yuddha Kanda, Sarga 11, Verse 36', 'जाम्बवांस्त्वथ संप्रेक्ष्य शास्त्रबुद्ध्या विचक्षणः।
वाक्यं विज्ञापयामास गुणवद्दोषवर्जितम्॥', 'jāmbavāṃs tv atha saṃprekṣya śāstrabuddhyā vicakṣaṇaḥ
vākyaṃ vijñāpayām āsa guṇavad doṣavarjitam', null, 6011036),
('ramayana-6-11-37', 37, 'Yuddha Kanda, Sarga 11, Verse 37', 'बद्धवैराच्च पापाच्च राक्षसेन्द्राद्विभीषणः।
अदेश काले संप्राप्तः सर्वथा शङ्क्यतामयम्॥', 'baddhavairāc ca pāpāc ca rākṣasendrād vibhīṣaṇaḥ
adeśa kāle saṃprāptaḥ sarvathā śaṅkyatām ayam', null, 6011037),
('ramayana-6-11-38', 38, 'Yuddha Kanda, Sarga 11, Verse 38', 'ततो मैन्दस्तु संप्रेक्ष्य नयापनयकोविदः।
वाक्यं वचनसंपन्नो बभाषे हेतुमत्तरम्॥', 'tato maindas tu saṃprekṣya nayāpanayakovidaḥ
vākyaṃ vacanasaṃpanno babhāṣe hetumattaram', null, 6011038),
('ramayana-6-11-39', 39, 'Yuddha Kanda, Sarga 11, Verse 39', 'वचनं नाम तस्यैष रावणस्य विभीषणः।
पृच्छ्यतां मधुरेणायं शनैर्नरवरेश्वर॥', 'vacanaṃ nāma tasyaiṣa rāvaṇasya vibhīṣaṇaḥ
pṛcchyatāṃ madhureṇāyaṃ śanair naravareśvara', null, 6011039),
('ramayana-6-11-40', 40, 'Yuddha Kanda, Sarga 11, Verse 40', 'भावमस्य तु विज्ञाय ततस्तत्त्वं करिष्यसि।
यदि दृष्टो न दुष्टो वा बुद्धिपूर्वं नरर्षभ॥', 'bhāvam asya tu vijñāya tatas tattvaṃ kariṣyasi
yadi dṛṣṭo na duṣṭo vā buddhipūrvaṃ nararṣabha', null, 6011040),
('ramayana-6-11-41', 41, 'Yuddha Kanda, Sarga 11, Verse 41', 'अथ संस्कारसंपन्नो हनूमान्सचिवोत्तमः।
उवाच वचनं श्लक्ष्णमर्थवन्मधुरं लघु॥', 'atha saṃskārasaṃpanno hanūmān sacivottamaḥ
uvāca vacanaṃ ślakṣṇam arthavan madhuraṃ laghu', null, 6011041),
('ramayana-6-11-42', 42, 'Yuddha Kanda, Sarga 11, Verse 42', 'न भवन्तं मतिश्रेष्ठं समर्थं वदतां वरम्।
अतिशाययितुं शक्तो बृहस्पतिरपि ब्रुवन्॥', 'na bhavantaṃ matiśreṣṭhaṃ samarthaṃ vadatāṃ varam
atiśāyayituṃ śakto bṛhaspatir api bruvan', null, 6011042),
('ramayana-6-11-43', 43, 'Yuddha Kanda, Sarga 11, Verse 43', 'न वादान्नापि संघर्षान्नाधिक्यान्न च कामतः।
वक्ष्यामि वचनं राजन्यथार्थं रामगौरवात्॥', 'na vādān nāpi saṃgharṣān nādhikyān na ca kāmataḥ
vakṣyāmi vacanaṃ rājan yathārthaṃ rāmagauravāt', null, 6011043),
('ramayana-6-11-44', 44, 'Yuddha Kanda, Sarga 11, Verse 44', 'अर्थानर्थनिमित्तं हि यदुक्तं सचिवैस्तव।
तत्र दोषं प्रपश्यामि क्रिया न ह्युपपद्यते॥', 'arthānarthanimittaṃ hi yad uktaṃ sacivais tava
tatra doṣaṃ prapaśyāmi kriyā na hy upapadyate', null, 6011044),
('ramayana-6-11-45', 45, 'Yuddha Kanda, Sarga 11, Verse 45', 'ऋते नियोगात्सामर्थ्यमवबोद्धुं न शक्यते।
सहसा विनियोगो हि दोषवान्प्रतिभाति मे॥', 'ṛte niyogāt sāmarthyam avaboddhuṃ na śakyate
sahasā viniyogo hi doṣavān pratibhāti me', null, 6011045),
('ramayana-6-11-46', 46, 'Yuddha Kanda, Sarga 11, Verse 46', 'चारप्रणिहितं युक्तं यदुक्तं सचिवैस्तव।
अर्थस्यासंभवात्तत्र कारणं नोपपद्यते॥', 'cārapraṇihitaṃ yuktaṃ yad uktaṃ sacivais tava
arthasyāsaṃbhavāt tatra kāraṇaṃ nopapadyate', null, 6011046),
('ramayana-6-11-47', 47, 'Yuddha Kanda, Sarga 11, Verse 47', 'अदेश काले संप्राप्त इत्ययं यद्विभीषणः।
विवक्षा चात्र मेऽस्तीयं तां निबोध यथा मति॥', 'adeśa kāle saṃprāpta ity ayaṃ yad vibhīṣaṇaḥ
vivakṣā cātra me ''stīyaṃ tāṃ nibodha yathā mati', null, 6011047),
('ramayana-6-11-48', 48, 'Yuddha Kanda, Sarga 11, Verse 48', 'स एष देशः कालश्च भवतीह यथा तथा।
पुरुषात्पुरुषं प्राप्य तथा दोषगुणावपि॥', 'sa eṣa deśaḥ kālaś ca bhavatīha yathā tathā
puruṣāt puruṣaṃ prāpya tathā doṣaguṇāv api', null, 6011048),
('ramayana-6-11-49', 49, 'Yuddha Kanda, Sarga 11, Verse 49', 'दौरात्म्यं रावणे दृष्ट्वा विक्रमं च तथा त्वयि।
युक्तमागमनं तस्य सदृशं तस्य बुद्धितः॥', 'daurātmyaṃ rāvaṇe dṛṣṭvā vikramaṃ ca tathā tvayi
yuktam āgamanaṃ tasya sadṛśaṃ tasya buddhitaḥ', null, 6011049),
('ramayana-6-11-50', 50, 'Yuddha Kanda, Sarga 11, Verse 50', 'अज्ञातरूपैः पुरुषैः स राजन्पृच्छ्यतामिति।
यदुक्तमत्र मे प्रेक्षा का चिदस्ति समीक्षिता॥', 'ajñātarūpaiḥ puruṣaiḥ sa rājan pṛcchyatām iti
yad uktam atra me prekṣā kā cid asti samīkṣitā', null, 6011050),
('ramayana-6-11-51', 51, 'Yuddha Kanda, Sarga 11, Verse 51', 'पृच्छ्यमानो विशङ्केत सहसा बुद्धिमान्वचः।
तत्र मित्रं प्रदुष्येत मिथ्यपृष्टं सुखागतम्॥', 'pṛcchyamāno viśaṅketa sahasā buddhimān vacaḥ
tatra mitraṃ praduṣyeta mithyapṛṣṭaṃ sukhāgatam', null, 6011051),
('ramayana-6-11-52', 52, 'Yuddha Kanda, Sarga 11, Verse 52', 'अशक्यः सहसा राजन्भावो वेत्तुं परस्य वै।
अन्तः स्वभावैर्गीतैस्तैर्नैपुण्यं पश्यता भृशम्॥', 'aśakyaḥ sahasā rājan bhāvo vettuṃ parasya vai
antaḥ svabhāvair gītais tair naipuṇyaṃ paśyatā bhṛśam', null, 6011052),
('ramayana-6-11-53', 53, 'Yuddha Kanda, Sarga 11, Verse 53', 'न त्वस्य ब्रुवतो जातु लक्ष्यते दुष्टभावता।
प्रसन्नं वदनं चापि तस्मान्मे नास्ति संशयः॥', 'na tv asya bruvato jātu lakṣyate duṣṭabhāvatā
prasannaṃ vadanaṃ cāpi tasmān me nāsti saṃśayaḥ', null, 6011053),
('ramayana-6-11-54', 54, 'Yuddha Kanda, Sarga 11, Verse 54', 'अशङ्कितमतिः स्वस्थो न शठः परिसर्पति।
न चास्य दुष्टा वाक्चापि तस्मान्नास्तीह संशयः॥', 'aśaṅkitamatiḥ svastho na śaṭhaḥ parisarpati
na cāsya duṣṭā vāk cāpi tasmān nāstīha saṃśayaḥ', null, 6011054),
('ramayana-6-11-55', 55, 'Yuddha Kanda, Sarga 11, Verse 55', 'आकारश्छाद्यमानोऽपि न शक्यो विनिगूहितुम्।
बलाद्धि विवृणोत्येव भावमन्तर्गतं नृणाम्॥', 'ākāraś chādyamāno ''pi na śakyo vinigūhitum
balād dhi vivṛṇoty eva bhāvam antargataṃ nṛṇām', null, 6011055),
('ramayana-6-11-56', 56, 'Yuddha Kanda, Sarga 11, Verse 56', 'देशकालोपपन्नं च कार्यं कार्यविदां वर।
सफलं कुरुते क्षिप्रं प्रयोगेणाभिसंहितम्॥', 'deśakālopapannaṃ ca kāryaṃ kāryavidāṃ vara
saphalaṃ kurute kṣipraṃ prayogeṇābhisaṃhitam', null, 6011056),
('ramayana-6-11-57', 57, 'Yuddha Kanda, Sarga 11, Verse 57', 'उद्योगं तव संप्रेक्ष्य मिथ्यावृत्तं च रावणम्।
वालिनश्च वधं श्रुत्वा सुग्रीवं चाभिषेचितम्॥', 'udyogaṃ tava saṃprekṣya mithyāvṛttaṃ ca rāvaṇam
vālinaś ca vadhaṃ śrutvā sugrīvaṃ cābhiṣecitam', null, 6011057),
('ramayana-6-11-58', 58, 'Yuddha Kanda, Sarga 11, Verse 58', 'राज्यं प्रार्थयमानश्च बुद्धिपूर्वमिहागतः।
एतावत्तु पुरस्कृत्य युज्यते त्वस्य संग्रहः॥', 'rājyaṃ prārthayamānaś ca buddhipūrvam ihāgataḥ
etāvat tu puraskṛtya yujyate tv asya saṃgrahaḥ', null, 6011058),
('ramayana-6-11-59', 59, 'Yuddha Kanda, Sarga 11, Verse 59', 'यथाशक्ति मयोक्तं तु राक्षसस्यार्जवं प्रति।
त्वं प्रमाणं तु शेषस्य श्रुत्वा बुद्धिमतां वर॥', 'yathāśakti mayoktaṃ tu rākṣasasyārjavaṃ prati
tvaṃ pramāṇaṃ tu śeṣasya śrutvā buddhimatāṃ vara', null, 6011059)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 12 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-12-1', 1, 'Yuddha Kanda, Sarga 12, Verse 1', 'अथ रामः प्रसन्नात्मा श्रुत्वा वायुसुतस्य ह।
प्रत्यभाषत दुर्धर्षः श्रुतवानात्मनि स्थितम्॥', 'atha rāmaḥ prasannātmā śrutvā vāyusutasya ha
pratyabhāṣata durdharṣaḥ śrutavān ātmani sthitam', null, 6012001),
('ramayana-6-12-2', 2, 'Yuddha Kanda, Sarga 12, Verse 2', 'ममापि तु विवक्षास्ति का चित्प्रति विभीषणम्।
श्रुतमिच्छामि तत्सर्वं भवद्भिः श्रेयसि स्थितैः॥', 'mamāpi tu vivakṣāsti kā cit prati vibhīṣaṇam
śrutam icchāmi tat sarvaṃ bhavadbhiḥ śreyasi sthitaiḥ', null, 6012002),
('ramayana-6-12-3', 3, 'Yuddha Kanda, Sarga 12, Verse 3', 'मित्रभावेन संप्राप्तं न त्यजेयं कथं चन।
दोषो यद्यपि तस्य स्यात्सतामेतदगर्हितम्॥', 'mitrabhāvena saṃprāptaṃ na tyajeyaṃ kathaṃ cana
doṣo yady api tasya syāt satām etad agarhitam', null, 6012003),
('ramayana-6-12-4', 4, 'Yuddha Kanda, Sarga 12, Verse 4', 'रामस्य वचनं श्रुत्वा सुग्रीवः प्लवगेश्वरः।
प्रत्यभाषत काकुत्स्थं सौहार्देनाभिचोदितः॥', 'rāmasya vacanaṃ śrutvā sugrīvaḥ plavageśvaraḥ
pratyabhāṣata kākutsthaṃ sauhārdenābhicoditaḥ', null, 6012004),
('ramayana-6-12-5', 5, 'Yuddha Kanda, Sarga 12, Verse 5', 'किमत्र चित्रं धर्मज्ञ लोकनाथशिखामणे।
यत्त्वमार्यं प्रभाषेथाः सत्त्ववान्सपथे स्थितः॥', 'kim atra citraṃ dharmajña lokanāthaśikhāmaṇe
yat tvam āryaṃ prabhāṣethāḥ sattvavān sapathe sthitaḥ', null, 6012005),
('ramayana-6-12-6', 6, 'Yuddha Kanda, Sarga 12, Verse 6', 'मम चाप्यन्तरात्मायं शुद्धिं वेत्ति विभीषणम्।
अनुमनाच्च भावाच्च सर्वतः सुपरीक्षितः॥', 'mama cāpy antarātmāyaṃ śuddhiṃ vetti vibhīṣaṇam
anumanāc ca bhāvāc ca sarvataḥ suparīkṣitaḥ', null, 6012006),
('ramayana-6-12-7', 7, 'Yuddha Kanda, Sarga 12, Verse 7', 'तस्मात्क्षिप्रं सहास्माभिस्तुल्यो भवतु राघव।
विभीषणो महाप्राज्ञः सखित्वं चाभ्युपैतु नः॥', 'tasmāt kṣipraṃ sahāsmābhis tulyo bhavatu rāghava
vibhīṣaṇo mahāprājñaḥ sakhitvaṃ cābhyupaitu naḥ', null, 6012007),
('ramayana-6-12-8', 8, 'Yuddha Kanda, Sarga 12, Verse 8', 'स सुग्रीवस्य तद्वाक्यं रामः श्रुत्वा विमृश्य च।
ततः शुभतरं वाक्यमुवाच हरिपुंगवम्॥', 'sa sugrīvasya tad vākyaṃ rāmaḥ śrutvā vimṛśya ca
tataḥ śubhataraṃ vākyam uvāca haripuṃgavam', null, 6012008),
('ramayana-6-12-9', 9, 'Yuddha Kanda, Sarga 12, Verse 9', 'सुदुष्टो वाप्यदुष्टो वा किमेष रजनीचरः।
सूक्ष्ममप्यहितं कर्तुं ममाशक्तः कथं चन॥', 'suduṣṭo vāpy aduṣṭo vā kim eṣa rajanīcaraḥ
sūkṣmam apy ahitaṃ kartuṃ mamāśaktaḥ kathaṃ cana', null, 6012009),
('ramayana-6-12-10', 10, 'Yuddha Kanda, Sarga 12, Verse 10', 'पिशाचान्दानवान्यक्षान्पृथिव्यां चैव राक्षसान्।
अङ्गुल्यग्रेण तान्हन्यामिच्छन्हरिगणेश्वर॥', 'piśācān dānavān yakṣān pṛthivyāṃ caiva rākṣasān
aṅgulyagreṇa tān hanyām icchan harigaṇeśvara', null, 6012010),
('ramayana-6-12-11', 11, 'Yuddha Kanda, Sarga 12, Verse 11', 'श्रूयते हि कपोतेन शत्रुः शरणमागतः।
अर्चितश्च यथान्यायं स्वैश्च मांसैर्निमन्त्रितः॥', 'śrūyate hi kapotena śatruḥ śaraṇam āgataḥ
arcitaś ca yathānyāyaṃ svaiś ca māṃsair nimantritaḥ', null, 6012011),
('ramayana-6-12-12', 12, 'Yuddha Kanda, Sarga 12, Verse 12', 'स हि तं प्रतिजग्राह भार्या हर्तारमागतम्।
कपोतो वानरश्रेष्ठ किं पुनर्मद्विधो जनः॥', 'sa hi taṃ pratijagrāha bhāryā hartāram āgatam
kapoto vānaraśreṣṭha kiṃ punar madvidho janaḥ', null, 6012012),
('ramayana-6-12-13', 13, 'Yuddha Kanda, Sarga 12, Verse 13', 'ऋषेः कण्वस्य पुत्रेण कण्डुना परमर्षिणा।
शृणु गाथां पुरा गीतां धर्मिष्ठां सत्यवादिना॥', 'ṛṣeḥ kaṇvasya putreṇa kaṇḍunā paramarṣiṇā
śṛṇu gāthāṃ purā gītāṃ dharmiṣṭhāṃ satyavādinā', null, 6012013),
('ramayana-6-12-14', 14, 'Yuddha Kanda, Sarga 12, Verse 14', 'बद्धाञ्जलिपुटं दीनं याचन्तं शरणागतम्।
न हन्यादानृशंस्यार्थमपि शत्रुं परं पत॥', 'baddhāñjalipuṭaṃ dīnaṃ yācantaṃ śaraṇāgatam
na hanyād ānṛśaṃsyārtham api śatruṃ paraṃ pata', null, 6012014),
('ramayana-6-12-15', 15, 'Yuddha Kanda, Sarga 12, Verse 15', 'आर्तो वा यदि वा दृप्तः परेषां शरणं गतः।
अरिः प्राणान्परित्यज्य रक्षितव्यः कृतात्मना॥', 'ārto vā yadi vā dṛptaḥ pareṣāṃ śaraṇaṃ gataḥ
ariḥ prāṇān parityajya rakṣitavyaḥ kṛtātmanā', null, 6012015),
('ramayana-6-12-16', 16, 'Yuddha Kanda, Sarga 12, Verse 16', 'स चेद्भयाद्वा मोहाद्वा कामाद्वापि न रक्षति।
स्वया शक्त्या यथातत्त्वं तत्पापं लोकगर्हितम्॥', 'sa ced bhayād vā mohād vā kāmād vāpi na rakṣati
svayā śaktyā yathātattvaṃ tat pāpaṃ lokagarhitam', null, 6012016),
('ramayana-6-12-17', 17, 'Yuddha Kanda, Sarga 12, Verse 17', 'विनष्टः पश्यतस्तस्य रक्षिणः शरणागतः।
आदाय सुकृतं तस्य सर्वं गच्छेदरक्षितः॥', 'vinaṣṭaḥ paśyatas tasya rakṣiṇaḥ śaraṇāgataḥ
ādāya sukṛtaṃ tasya sarvaṃ gacched arakṣitaḥ', null, 6012017),
('ramayana-6-12-18', 18, 'Yuddha Kanda, Sarga 12, Verse 18', 'एवं दोषो महानत्र प्रपन्नानामरक्षणे।
अस्वर्ग्यं चायशस्यं च बलवीर्यविनाशनम्॥', 'evaṃ doṣo mahān atra prapannānām arakṣaṇe
asvargyaṃ cāyaśasyaṃ ca balavīryavināśanam', null, 6012018),
('ramayana-6-12-19', 19, 'Yuddha Kanda, Sarga 12, Verse 19', 'करिष्यामि यथार्थं तु कण्डोर्वचनमुत्तमम्।
धर्मिष्ठं च यशस्यं च स्वर्ग्यं स्यात्तु फलोदये॥', 'kariṣyāmi yathārthaṃ tu kaṇḍor vacanam uttamam
dharmiṣṭhaṃ ca yaśasyaṃ ca svargyaṃ syāt tu phalodaye', null, 6012019),
('ramayana-6-12-20', 20, 'Yuddha Kanda, Sarga 12, Verse 20', 'सकृदेव प्रपन्नाय तवास्मीति च याचते।
अभयं सर्वभूतेभ्यो ददाम्येतद्व्रतं मम॥', 'sakṛd eva prapannāya tavāsmīti ca yācate
abhayaṃ sarvabhūtebhyo dadāmy etad vrataṃ mama', null, 6012020),
('ramayana-6-12-21', 21, 'Yuddha Kanda, Sarga 12, Verse 21', 'आनयैनं हरिश्रेष्ठ दत्तमस्याभयं मया।
विभीषणो वा सुग्रीव यदि वा रावणः स्वयम्॥', 'ānayainaṃ hariśreṣṭha dattam asyābhayaṃ mayā
vibhīṣaṇo vā sugrīva yadi vā rāvaṇaḥ svayam', null, 6012021),
('ramayana-6-12-22', 22, 'Yuddha Kanda, Sarga 12, Verse 22', 'ततस्तु सुग्रीववचो निशम्य तद्धरीश्वरेणाभिहितं नरेश्वरः।
विभीषणेनाशु जगाम संगमं पतत्रिराजेन यथा पुरंदरः॥', 'tatas tu sugrīvavaco niśamya tad dharīśvareṇābhihitaṃ nareśvaraḥ
vibhīṣaṇenāśu jagāma saṃgamaṃ patatrirājena yathā puraṃdaraḥ', null, 6012022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 13 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-13-1', 1, 'Yuddha Kanda, Sarga 13, Verse 1', 'राघवेणाभये दत्ते संनतो रावणानुजः।
खात्पपातावनिं हृष्टो भक्तैरनुचरैः सह॥', 'rāghaveṇābhaye datte saṃnato rāvaṇānujaḥ
khāt papātāvaniṃ hṛṣṭo bhaktair anucaraiḥ saha', null, 6013001),
('ramayana-6-13-2', 2, 'Yuddha Kanda, Sarga 13, Verse 2', 'स तु रामस्य धर्मात्मा निपपात विभीषणः।
पादयोः शरणान्वेषी चतुर्भिः सह राक्षसैः॥', 'sa tu rāmasya dharmātmā nipapāta vibhīṣaṇaḥ
pādayoḥ śaraṇānveṣī caturbhiḥ saha rākṣasaiḥ', null, 6013002),
('ramayana-6-13-3', 3, 'Yuddha Kanda, Sarga 13, Verse 3', 'अब्रवीच्च तदा रामं वाक्यं तत्र विभीषणः।
धर्मयुक्तं च युक्तं च साम्प्रतं संप्रहर्षणम्॥', 'abravīc ca tadā rāmaṃ vākyaṃ tatra vibhīṣaṇaḥ
dharmayuktaṃ ca yuktaṃ ca sāmprataṃ saṃpraharṣaṇam', null, 6013003),
('ramayana-6-13-4', 4, 'Yuddha Kanda, Sarga 13, Verse 4', 'अनुजो रावणस्याहं तेन चास्म्यवमानितः।
भवन्तं सर्वभूतानां शरण्यं शरणं गतः॥', 'anujo rāvaṇasyāhaṃ tena cāsmy avamānitaḥ
bhavantaṃ sarvabhūtānāṃ śaraṇyaṃ śaraṇaṃ gataḥ', null, 6013004),
('ramayana-6-13-5', 5, 'Yuddha Kanda, Sarga 13, Verse 5', 'परित्यक्ता मया लङ्का मित्राणि च धनानि च।
भवद्गतं मे राज्यं च जीवितं च सुखानि च॥', 'parityaktā mayā laṅkā mitrāṇi ca dhanāni ca
bhavadgataṃ me rājyaṃ ca jīvitaṃ ca sukhāni ca', null, 6013005),
('ramayana-6-13-6', 6, 'Yuddha Kanda, Sarga 13, Verse 6', 'राक्षसानां वधे साह्यं लङ्कायाश्च प्रधर्षणे।
करिष्यामि यथाप्राणं प्रवेक्ष्यामि च वाहिनीम्॥', 'rākṣasānāṃ vadhe sāhyaṃ laṅkāyāś ca pradharṣaṇe
kariṣyāmi yathāprāṇaṃ pravekṣyāmi ca vāhinīm', null, 6013006),
('ramayana-6-13-7', 7, 'Yuddha Kanda, Sarga 13, Verse 7', 'इति ब्रुवाणं रामस्तु परिष्वज्य विभीषणम्।
अब्रवील्लक्ष्मणं प्रीतः समुद्राज्जलमानय॥', 'iti bruvāṇaṃ rāmas tu pariṣvajya vibhīṣaṇam
abravīl lakṣmaṇaṃ prītaḥ samudrāj jalam ānaya', null, 6013007),
('ramayana-6-13-8', 8, 'Yuddha Kanda, Sarga 13, Verse 8', 'तेन चेमं महाप्राज्ञमभिषिञ्च विभीषणम्।
राजानं रक्षसां क्षिप्रं प्रसन्ने मयि मानद॥', 'tena cemaṃ mahāprājñam abhiṣiñca vibhīṣaṇam
rājānaṃ rakṣasāṃ kṣipraṃ prasanne mayi mānada', null, 6013008),
('ramayana-6-13-9', 9, 'Yuddha Kanda, Sarga 13, Verse 9', 'एवमुक्तस्तु सौमित्रिरभ्यषिञ्चद्विभीषणम्।
मध्ये वानरमुख्यानां राजानं रामशासनात्॥', 'evam uktas tu saumitrir abhyaṣiñcad vibhīṣaṇam
madhye vānaramukhyānāṃ rājānaṃ rāmaśāsanāt', null, 6013009),
('ramayana-6-13-10', 10, 'Yuddha Kanda, Sarga 13, Verse 10', 'तं प्रसादं तु रामस्य दृष्ट्वा सद्यः प्लवंगमाः।
प्रचुक्रुशुर्महानादान्साधु साध्विति चाब्रुवन्॥', 'taṃ prasādaṃ tu rāmasya dṛṣṭvā sadyaḥ plavaṃgamāḥ
pracukruśur mahānādān sādhu sādhv iti cābruvan', null, 6013010),
('ramayana-6-13-11', 11, 'Yuddha Kanda, Sarga 13, Verse 11', 'अब्रवीच्च हनूमांश्च सुग्रीवश्च विभीषणम्।
कथं सागरमक्षोभ्यं तराम वरुणालयम्॥', 'abravīc ca hanūmāṃś ca sugrīvaś ca vibhīṣaṇam
kathaṃ sāgaram akṣobhyaṃ tarāma varuṇālayam', null, 6013011),
('ramayana-6-13-12', 12, 'Yuddha Kanda, Sarga 13, Verse 12', 'उपायैरभिगच्छामो यथा नदनदीपतिम्।
तराम तरसा सर्वे ससैन्या वरुणालयम्॥', 'upāyair abhigacchāmo yathā nadanadīpatim
tarāma tarasā sarve sasainyā varuṇālayam', null, 6013012),
('ramayana-6-13-13', 13, 'Yuddha Kanda, Sarga 13, Verse 13', 'एवमुक्तस्तु धर्मज्ञः प्रत्युवाच विभीषणः।
समुद्रं राघवो राजा शरणं गन्तुमर्हति॥', 'evam uktas tu dharmajñaḥ pratyuvāca vibhīṣaṇaḥ
samudraṃ rāghavo rājā śaraṇaṃ gantum arhati', null, 6013013),
('ramayana-6-13-14', 14, 'Yuddha Kanda, Sarga 13, Verse 14', 'खानितः सगरेणायमप्रमेयो महोदधिः।
कर्तुमर्हति रामस्य ज्ञातेः कार्यं महोदधिः॥', 'khānitaḥ sagareṇāyam aprameyo mahodadhiḥ
kartum arhati rāmasya jñāteḥ kāryaṃ mahodadhiḥ', null, 6013014),
('ramayana-6-13-15', 15, 'Yuddha Kanda, Sarga 13, Verse 15', 'एवं विभीषणेनोक्ते राक्षसेन विपश्चिता।
प्रकृत्या धर्मशीलस्य राघवस्याप्यरोचत॥', 'evaṃ vibhīṣaṇenokte rākṣasena vipaścitā
prakṛtyā dharmaśīlasya rāghavasyāpy arocata', null, 6013015),
('ramayana-6-13-16', 16, 'Yuddha Kanda, Sarga 13, Verse 16', 'स लक्ष्मणं महातेजाः सुग्रीवं च हरीश्वरम्।
सत्क्रियार्थं क्रियादक्षः स्मितपूर्वमुवाच ह॥', 'sa lakṣmaṇaṃ mahātejāḥ sugrīvaṃ ca harīśvaram
satkriyārthaṃ kriyādakṣaḥ smitapūrvam uvāca ha', null, 6013016),
('ramayana-6-13-17', 17, 'Yuddha Kanda, Sarga 13, Verse 17', 'विभीषणस्य मन्त्रोऽयं मम लक्ष्मण रोचते।
ब्रूहि त्वं सहसुग्रीवस्तवापि यदि रोचते॥', 'vibhīṣaṇasya mantro ''yaṃ mama lakṣmaṇa rocate
brūhi tvaṃ sahasugrīvas tavāpi yadi rocate', null, 6013017),
('ramayana-6-13-18', 18, 'Yuddha Kanda, Sarga 13, Verse 18', 'सुग्रीवः पण्डितो नित्यं भवान्मन्त्रविचक्षणः।
उभाभ्यां संप्रधार्यार्यं रोचते यत्तदुच्यताम्॥', 'sugrīvaḥ paṇḍito nityaṃ bhavān mantravicakṣaṇaḥ
ubhābhyāṃ saṃpradhāryāryaṃ rocate yat tad ucyatām', null, 6013018),
('ramayana-6-13-19', 19, 'Yuddha Kanda, Sarga 13, Verse 19', 'एवमुक्तौ तु तौ वीरावुभौ सुग्रीवलक्ष्मणौ।
समुदाचार संयुक्तमिदं वचनमूचतुः॥', 'evam uktau tu tau vīrāv ubhau sugrīvalakṣmaṇau
samudācāra saṃyuktam idaṃ vacanam ūcatuḥ', null, 6013019),
('ramayana-6-13-20', 20, 'Yuddha Kanda, Sarga 13, Verse 20', 'किमर्थं नो नरव्याघ्र न रोचिष्यति राघव।
विभीषणेन यत्तूक्तमस्मिन्काले सुखावहम्॥', 'kimarthaṃ no naravyāghra na rociṣyati rāghava
vibhīṣaṇena yat tūktam asmin kāle sukhāvaham', null, 6013020),
('ramayana-6-13-21', 21, 'Yuddha Kanda, Sarga 13, Verse 21', 'अबद्ध्वा सागरे सेतुं घोरेऽस्मिन्वरुणालये।
लङ्का नासादितुं शक्या सेन्द्रैरपि सुरासुरैः॥', 'abaddhvā sāgare setuṃ ghore ''smin varuṇālaye
laṅkā nāsādituṃ śakyā sendrair api surāsuraiḥ', null, 6013021),
('ramayana-6-13-22', 22, 'Yuddha Kanda, Sarga 13, Verse 22', 'विभीषणस्य शूरस्य यथार्थं क्रियतां वचः।
अलं कालात्ययं कृत्वा समुद्रोऽयं नियुज्यताम्॥', 'vibhīṣaṇasya śūrasya yathārthaṃ kriyatāṃ vacaḥ
alaṃ kālātyayaṃ kṛtvā samudro ''yaṃ niyujyatām', null, 6013022),
('ramayana-6-13-23', 23, 'Yuddha Kanda, Sarga 13, Verse 23', 'एवमुक्तः कुशास्तीर्णे तीरे नदनदीपतेः।
संविवेश तदा रामो वेद्यामिव हुताशनः॥', 'evam uktaḥ kuśāstīrṇe tīre nadanadīpateḥ
saṃviveśa tadā rāmo vedyām iva hutāśanaḥ', null, 6013023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 14 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-14-1', 1, 'Yuddha Kanda, Sarga 14, Verse 1', 'तस्य रामस्य सुप्तस्य कुशास्तीर्णे महीतले।
नियमादप्रमत्तस्य निशास्तिस्रोऽतिचक्रमुः॥', 'tasya rāmasya suptasya kuśāstīrṇe mahītale
niyamād apramattasya niśās tisro ''ticakramuḥ', null, 6014001),
('ramayana-6-14-2', 2, 'Yuddha Kanda, Sarga 14, Verse 2', 'न च दर्शयते मन्दस्तदा रामस्य सागरः।
प्रयतेनापि रामेण यथार्हमभिपूजितः॥', 'na ca darśayate mandas tadā rāmasya sāgaraḥ
prayatenāpi rāmeṇa yathārham abhipūjitaḥ', null, 6014002),
('ramayana-6-14-3', 3, 'Yuddha Kanda, Sarga 14, Verse 3', 'समुद्रस्य ततः क्रुद्धो रामो रक्तान्तलोचनः।
समीपस्थमुवाचेदं लक्ष्मणं शुभलक्ष्मणम्॥', 'samudrasya tataḥ kruddho rāmo raktāntalocanaḥ
samīpastham uvācedaṃ lakṣmaṇaṃ śubhalakṣmaṇam', null, 6014003),
('ramayana-6-14-4', 4, 'Yuddha Kanda, Sarga 14, Verse 4', 'पश्य तावदनार्यस्य पूज्यमानस्य लक्ष्मण।
अवलेपं समुद्रस्य न दर्शयति यत्स्वयम्॥', 'paśya tāvad anāryasya pūjyamānasya lakṣmaṇa
avalepaṃ samudrasya na darśayati yat svayam', null, 6014004),
('ramayana-6-14-5', 5, 'Yuddha Kanda, Sarga 14, Verse 5', 'प्रशमश्च क्षमा चैव आर्जवं प्रियवादिता।
असामर्थ्यं फलन्त्येते निर्गुणेषु सतां गुणाः॥', 'praśamaś ca kṣamā caiva ārjavaṃ priyavāditā
asāmarthyaṃ phalanty ete nirguṇeṣu satāṃ guṇāḥ', null, 6014005),
('ramayana-6-14-6', 6, 'Yuddha Kanda, Sarga 14, Verse 6', 'आत्मप्रशंसिनं दुष्टं धृष्टं विपरिधावकम्।
सर्वत्रोत्सृष्टदण्डं च लोकः सत्कुरुते नरम्॥', 'ātmapraśaṃsinaṃ duṣṭaṃ dhṛṣṭaṃ viparidhāvakam
sarvatrotsṛṣṭadaṇḍaṃ ca lokaḥ satkurute naram', null, 6014006),
('ramayana-6-14-7', 7, 'Yuddha Kanda, Sarga 14, Verse 7', 'न साम्ना शक्यते कीर्तिर्न साम्ना शक्यते यशः।
प्राप्तुं लक्ष्मण लोकेऽस्मिञ्जयो वा रणमूधनि॥', 'na sāmnā śakyate kīrtir na sāmnā śakyate yaśaḥ
prāptuṃ lakṣmaṇa loke ''smiñ jayo vā raṇamūdhani', null, 6014007),
('ramayana-6-14-8', 8, 'Yuddha Kanda, Sarga 14, Verse 8', 'अद्य मद्बाणनिर्भिन्नैर्मकरैर्मकरालयम्।
निरुद्धतोयं सौमित्रे प्लवद्भिः पश्य सर्वतः॥', 'adya madbāṇanirbhinnair makarair makarālayam
niruddhatoyaṃ saumitre plavadbhiḥ paśya sarvataḥ', null, 6014008),
('ramayana-6-14-9', 9, 'Yuddha Kanda, Sarga 14, Verse 9', 'महाभोगानि मत्स्यानां करिणां च करानिह।
भोगांश्च पश्य नागानां मया भिन्नानि लक्ष्मण॥', 'mahābhogāni matsyānāṃ kariṇāṃ ca karān iha
bhogāṃś ca paśya nāgānāṃ mayā bhinnāni lakṣmaṇa', null, 6014009),
('ramayana-6-14-10', 10, 'Yuddha Kanda, Sarga 14, Verse 10', 'सशङ्खशुक्तिका जालं समीनमकरं शरैः।
अद्य युद्धेन महता समुद्रं परिशोषये॥', 'saśaṅkhaśuktikā jālaṃ samīnamakaraṃ śaraiḥ
adya yuddhena mahatā samudraṃ pariśoṣaye', null, 6014010),
('ramayana-6-14-11', 11, 'Yuddha Kanda, Sarga 14, Verse 11', 'क्षमया हि समायुक्तं मामयं मकरालयः।
असमर्थं विजानाति धिक्क्षमामीदृशे जने॥', 'kṣamayā hi samāyuktaṃ mām ayaṃ makarālayaḥ
asamarthaṃ vijānāti dhik kṣamām īdṛśe jane', null, 6014011),
('ramayana-6-14-12', 12, 'Yuddha Kanda, Sarga 14, Verse 12', 'चापमानय सौमित्रे शरांश्चाशीविषोपमान्।
अद्याक्षोभ्यमपि क्रुद्धः क्षोभयिष्यामि सागरम्॥', 'cāpam ānaya saumitre śarāṃś cāśīviṣopamān
adyākṣobhyam api kruddhaḥ kṣobhayiṣyāmi sāgaram', null, 6014012),
('ramayana-6-14-13', 13, 'Yuddha Kanda, Sarga 14, Verse 13', 'वेलासु कृतमर्यादं सहसोर्मिसमाकुलम्।
निर्मर्यादं करिष्यामि सायकैर्वरुणालयम्॥', 'velāsu kṛtamaryādaṃ sahasormisamākulam
nirmaryādaṃ kariṣyāmi sāyakair varuṇālayam', null, 6014013),
('ramayana-6-14-14', 14, 'Yuddha Kanda, Sarga 14, Verse 14', 'एवमुक्त्वा धनुष्पाणिः क्रोधविस्फारितेक्षणः।
बभूव रामो दुर्धर्षो युगान्ताग्निरिव ज्वलन्॥', 'evam uktvā dhanuṣpāṇiḥ krodhavisphāritekṣaṇaḥ
babhūva rāmo durdharṣo yugāntāgnir iva jvalan', null, 6014014),
('ramayana-6-14-15', 15, 'Yuddha Kanda, Sarga 14, Verse 15', 'संपीड्य च धनुर्घोरं कम्पयित्वा शरैर्जगत्।
मुमोच विशिखानुग्रान्वज्राणीव शतक्रतुः॥', 'saṃpīḍya ca dhanur ghoraṃ kampayitvā śarair jagat
mumoca viśikhān ugrān vajrāṇīva śatakratuḥ', null, 6014015),
('ramayana-6-14-16', 16, 'Yuddha Kanda, Sarga 14, Verse 16', 'ते ज्वलन्तो महावेगास्तेजसा सायकोत्तमाः।
प्रविशन्ति समुद्रस्य सलिलं त्रस्तपन्नगम्॥', 'te jvalanto mahāvegās tejasā sāyakottamāḥ
praviśanti samudrasya salilaṃ trastapannagam', null, 6014016),
('ramayana-6-14-17', 17, 'Yuddha Kanda, Sarga 14, Verse 17', 'ततो वेगः समुद्रस्य सनक्रमकरो महान्।
संबभूव महाघोरः समारुतरवस्तदा॥', 'tato vegaḥ samudrasya sanakramakaro mahān
saṃbabhūva mahāghoraḥ samārutaravas tadā', null, 6014017),
('ramayana-6-14-18', 18, 'Yuddha Kanda, Sarga 14, Verse 18', 'महोर्मिमालाविततः शङ्खशुक्तिसमाकुलः।
सधूमपरिवृत्तोर्मिः सहसाभून्महोदधिः॥', 'mahormimālāvitataḥ śaṅkhaśuktisamākulaḥ
sadhūmaparivṛttormiḥ sahasābhūn mahodadhiḥ', null, 6014018),
('ramayana-6-14-19', 19, 'Yuddha Kanda, Sarga 14, Verse 19', 'व्यथिताः पन्नगाश्चासन्दीप्तास्या दीप्तलोचनाः।
दानवाश्च महावीर्याः पातालतलवासिनः॥', 'vyathitāḥ pannagāś cāsan dīptāsyā dīptalocanāḥ
dānavāś ca mahāvīryāḥ pātālatalavāsinaḥ', null, 6014019),
('ramayana-6-14-20', 20, 'Yuddha Kanda, Sarga 14, Verse 20', 'ऊर्मयः सिन्धुराजस्य सनक्रमकरास्तदा।
विन्ध्यमन्दरसंकाशाः समुत्पेतुः सहस्रशः॥', 'ūrmayaḥ sindhurājasya sanakramakarās tadā
vindhyamandarasaṃkāśāḥ samutpetuḥ sahasraśaḥ', null, 6014020),
('ramayana-6-14-21', 21, 'Yuddha Kanda, Sarga 14, Verse 21', 'आघूर्णिततरङ्गौघः संभ्रान्तोरगराक्षसः।
उद्वर्तित महाग्राहः संवृत्तः सलिलाशयः॥', 'āghūrṇitataraṅgaughaḥ saṃbhrāntoragarākṣasaḥ
udvartita mahāgrāhaḥ saṃvṛttaḥ salilāśayaḥ', null, 6014021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 15 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-15-1', 1, 'Yuddha Kanda, Sarga 15, Verse 1', 'ततो मध्यात्समुद्रस्य सागरः स्वयमुत्थितः।
उदयन्हि महाशैलान्मेरोरिव दिवाकरः।
पन्नगैः सह दीप्तास्यैः समुद्रः प्रत्यदृश्यत॥', 'tato madhyāt samudrasya sāgaraḥ svayam utthitaḥ
udayan hi mahāśailān meror iva divākaraḥ
pannagaiḥ saha dīptāsyaiḥ samudraḥ pratyadṛśyata', null, 6015001),
('ramayana-6-15-2', 2, 'Yuddha Kanda, Sarga 15, Verse 2', 'स्निग्धवैदूर्यसंकाशो जाम्बूनदविभूषितः।
रक्तमाल्याम्बरधरः पद्मपत्रनिभेक्षणः॥', 'snigdhavaidūryasaṃkāśo jāmbūnadavibhūṣitaḥ
raktamālyāmbaradharaḥ padmapatranibhekṣaṇaḥ', null, 6015002),
('ramayana-6-15-3', 3, 'Yuddha Kanda, Sarga 15, Verse 3', 'सागरः समतिक्रम्य पूर्वमामन्त्र्य वीर्यवान्।
अब्रवीत्प्राञ्जलिर्वाक्यं राघवं शरपाणिनम्॥', 'sāgaraḥ samatikramya pūrvam āmantrya vīryavān
abravīt prāñjalir vākyaṃ rāghavaṃ śarapāṇinam', null, 6015003),
('ramayana-6-15-4', 4, 'Yuddha Kanda, Sarga 15, Verse 4', 'पृथिवी वायुराकाशमापो ज्योतिश्च राघवः।
स्वभावे सौम्य तिष्ठन्ति शाश्वतं मार्गमाश्रिताः॥', 'pṛthivī vāyur ākāśam āpo jyotiś ca rāghavaḥ
svabhāve saumya tiṣṭhanti śāśvataṃ mārgam āśritāḥ', null, 6015004),
('ramayana-6-15-5', 5, 'Yuddha Kanda, Sarga 15, Verse 5', 'तत्स्वभावो ममाप्येष यदगाधोऽहमप्लवः।
विकारस्तु भवेद्राध एतत्ते प्रवदाम्यहम्॥', 'tat svabhāvo mamāpy eṣa yad agādho ''ham aplavaḥ
vikāras tu bhaved rādha etat te pravadāmy aham', null, 6015005),
('ramayana-6-15-6', 6, 'Yuddha Kanda, Sarga 15, Verse 6', 'न कामान्न च लोभाद्वा न भयात्पार्थिवात्मज।
ग्राहनक्राकुलजलं स्तम्भयेयं कथं चन॥', 'na kāmān na ca lobhād vā na bhayāt pārthivātmaja
grāhanakrākulajalaṃ stambhayeyaṃ kathaṃ cana', null, 6015006),
('ramayana-6-15-7', 7, 'Yuddha Kanda, Sarga 15, Verse 7', 'विधास्ये राम येनापि विषहिष्ये ह्यहं तथा।
ग्राहा न प्रहरिष्यन्ति यावत्सेना तरिष्यति॥', 'vidhāsye rāma yenāpi viṣahiṣye hy ahaṃ tathā
grāhā na prahariṣyanti yāvat senā tariṣyati', null, 6015007),
('ramayana-6-15-8', 8, 'Yuddha Kanda, Sarga 15, Verse 8', 'अयं सौम्य नलो नाम तनुजो विश्वकर्मणः।
पित्रा दत्तवरः श्रीमान्प्रतिमो विश्वकर्मणः॥', 'ayaṃ saumya nalo nāma tanujo viśvakarmaṇaḥ
pitrā dattavaraḥ śrīmān pratimo viśvakarmaṇaḥ', null, 6015008),
('ramayana-6-15-9', 9, 'Yuddha Kanda, Sarga 15, Verse 9', 'एष सेतुं महोत्साहः करोतु मयि वानरः।
तमहं धारयिष्यामि तथा ह्येष यथा पिता॥', 'eṣa setuṃ mahotsāhaḥ karotu mayi vānaraḥ
tam ahaṃ dhārayiṣyāmi tathā hy eṣa yathā pitā', null, 6015009),
('ramayana-6-15-10', 10, 'Yuddha Kanda, Sarga 15, Verse 10', 'एवमुक्त्वोदधिर्नष्टः समुत्थाय नलस्ततः।
अब्रवीद्वानरश्रेष्ठो वाक्यं रामं महाबलः॥', 'evam uktvodadhir naṣṭaḥ samutthāya nalas tataḥ
abravīd vānaraśreṣṭho vākyaṃ rāmaṃ mahābalaḥ', null, 6015010),
('ramayana-6-15-11', 11, 'Yuddha Kanda, Sarga 15, Verse 11', 'अहं सेतुं करिष्यामि विस्तीर्णे वरुणालये।
पितुः सामर्थ्यमास्थाय तत्त्वमाह महोदधिः॥', 'ahaṃ setuṃ kariṣyāmi vistīrṇe varuṇālaye
pituḥ sāmarthyam āsthāya tattvam āha mahodadhiḥ', null, 6015011),
('ramayana-6-15-12', 12, 'Yuddha Kanda, Sarga 15, Verse 12', 'मम मातुर्वरो दत्तो मन्दरे विश्वकर्मणा।
औरसस्तस्य पुत्रोऽहं सदृशो विश्वकर्मणा॥', 'mama mātur varo datto mandare viśvakarmaṇā
aurasas tasya putro ''haṃ sadṛśo viśvakarmaṇā', null, 6015012),
('ramayana-6-15-13', 13, 'Yuddha Kanda, Sarga 15, Verse 13', 'न चाप्यहमनुक्तो वै प्रब्रूयामात्मनो गुणान्।
काममद्यैव बध्नन्तु सेतुं वानरपुंगवाः॥', 'na cāpy aham anukto vai prabrūyām ātmano guṇān
kāmam adyaiva badhnantu setuṃ vānarapuṃgavāḥ', null, 6015013),
('ramayana-6-15-14', 14, 'Yuddha Kanda, Sarga 15, Verse 14', 'ततो निसृष्टरामेण सर्वतो हरियूथपाः।
अभिपेतुर्महारण्यं हृष्टाः शतसहस्रशः॥', 'tato nisṛṣṭarāmeṇa sarvato hariyūthapāḥ
abhipetur mahāraṇyaṃ hṛṣṭāḥ śatasahasraśaḥ', null, 6015014),
('ramayana-6-15-15', 15, 'Yuddha Kanda, Sarga 15, Verse 15', 'ते नगान्नगसंकाशाः शाखामृगगणर्षभाः।
बभञ्जुर्वानरास्तत्र प्रचकर्षुश्च सागरम्॥', 'te nagān nagasaṃkāśāḥ śākhāmṛgagaṇarṣabhāḥ
babhañjur vānarās tatra pracakarṣuś ca sāgaram', null, 6015015),
('ramayana-6-15-16', 16, 'Yuddha Kanda, Sarga 15, Verse 16', 'ते सालैश्चाश्वकर्णैश्च धवैर्वंशैश्च वानराः।
कुटजैरर्जुनैस्तालैस्तिकलैस्तिमिशैरपि॥', 'te sālaiś cāśvakarṇaiś ca dhavair vaṃśaiś ca vānarāḥ
kuṭajair arjunais tālais tikalais timiśair api', null, 6015016),
('ramayana-6-15-17', 17, 'Yuddha Kanda, Sarga 15, Verse 17', 'बिल्वकैः सप्तपर्णैश्च कर्णिकारैश्च पुष्पितैः।
चूतैश्चाशोकवृक्षैश्च सागरं समपूरयन्॥', 'bilvakaiḥ saptaparṇaiś ca karṇikāraiś ca puṣpitaiḥ
cūtaiś cāśokavṛkṣaiś ca sāgaraṃ samapūrayan', null, 6015017),
('ramayana-6-15-18', 18, 'Yuddha Kanda, Sarga 15, Verse 18', 'समूलांश्च विमूलांश्च पादपान्हरिसत्तमाः।
इन्द्रकेतूनिवोद्यम्य प्रजह्रुर्हरयस्तरून्॥', 'samūlāṃś ca vimūlāṃś ca pādapān harisattamāḥ
indraketūn ivodyamya prajahrur harayas tarūn', null, 6015018),
('ramayana-6-15-19', 19, 'Yuddha Kanda, Sarga 15, Verse 19', 'प्रक्षिप्यमाणैरचलैः सहसा जलमुद्धतम्।
समुत्पतितमाकाशमपासर्पत्ततस्ततः॥', 'prakṣipyamāṇair acalaiḥ sahasā jalam uddhatam
samutpatitam ākāśam apāsarpat tatas tataḥ', null, 6015019),
('ramayana-6-15-20', 20, 'Yuddha Kanda, Sarga 15, Verse 20', 'दशयोजनविस्तीर्णं शतयोजनमायतम्।
नलश्चक्रे महासेतुं मध्ये नदनदीपतेः॥', 'daśayojanavistīrṇaṃ śatayojanam āyatam
nalaś cakre mahāsetuṃ madhye nadanadīpateḥ', null, 6015020),
('ramayana-6-15-21', 21, 'Yuddha Kanda, Sarga 15, Verse 21', 'शिलानां क्षिप्यमाणानां शैलानां तत्र पात्यताम्।
बभूव तुमुलः शब्दस्तदा तस्मिन्महोदधौ॥', 'śilānāṃ kṣipyamāṇānāṃ śailānāṃ tatra pātyatām
babhūva tumulaḥ śabdas tadā tasmin mahodadhau', null, 6015021),
('ramayana-6-15-22', 22, 'Yuddha Kanda, Sarga 15, Verse 22', 'स नलेन कृतः सेतुः सागरे मकरालये।
शुशुभे सुभगः श्रीमान्स्वातीपथ इवाम्बरे॥', 'sa nalena kṛtaḥ setuḥ sāgare makarālaye
śuśubhe subhagaḥ śrīmān svātīpatha ivāmbare', null, 6015022),
('ramayana-6-15-23', 23, 'Yuddha Kanda, Sarga 15, Verse 23', 'ततो देवाः सगन्धर्वाः सिद्धाश्च परमर्षयः॥', 'tato devāḥ sagandharvāḥ siddhāś ca paramarṣayaḥ', null, 6015023),
('ramayana-6-15-24', 24, 'Yuddha Kanda, Sarga 15, Verse 24', 'आप्लवन्तः प्लवन्तश्च गर्जन्तश्च प्लवंगमाः।
तमचिन्त्यमसह्यं च अद्भुतं लोमहर्षणम्।
ददृशुः सर्वभूतानि सागरे सेतुबन्धनम्॥', 'āplavantaḥ plavantaś ca garjantaś ca plavaṃgamāḥ
tam acintyam asahyaṃ ca adbhutaṃ lomaharṣaṇam
dadṛśuḥ sarvabhūtāni sāgare setubandhanam', null, 6015024),
('ramayana-6-15-25', 25, 'Yuddha Kanda, Sarga 15, Verse 25', 'तानि कोटिसहस्राणि वानराणां महौजसाम्।
बध्नन्तः सागरे सेतुं जग्मुः पारं महोदधेः॥', 'tāni koṭisahasrāṇi vānarāṇāṃ mahaujasām
badhnantaḥ sāgare setuṃ jagmuḥ pāraṃ mahodadheḥ', null, 6015025),
('ramayana-6-15-26', 26, 'Yuddha Kanda, Sarga 15, Verse 26', 'विशालः सुकृतः श्रीमान्सुभूमिः सुसमाहितः।
अशोभत महासेतुः सीमन्त इव सागरे॥', 'viśālaḥ sukṛtaḥ śrīmān subhūmiḥ susamāhitaḥ
aśobhata mahāsetuḥ sīmanta iva sāgare', null, 6015026),
('ramayana-6-15-27', 27, 'Yuddha Kanda, Sarga 15, Verse 27', 'ततः परे समुद्रस्य गदापाणिर्विभीषणः।
परेषामभिघतार्थमतिष्ठत्सचिवैः सह॥', 'tataḥ pare samudrasya gadāpāṇir vibhīṣaṇaḥ
pareṣām abhighatārtham atiṣṭhat sacivaiḥ saha', null, 6015027),
('ramayana-6-15-28', 28, 'Yuddha Kanda, Sarga 15, Verse 28', 'अग्रतस्तस्य सैन्यस्य श्रीमान्रामः सलक्ष्मणः।
जगाम धन्वी धर्मात्मा सुग्रीवेण समन्वितः॥', 'agratas tasya sainyasya śrīmān rāmaḥ salakṣmaṇaḥ
jagāma dhanvī dharmātmā sugrīveṇa samanvitaḥ', null, 6015028),
('ramayana-6-15-29', 29, 'Yuddha Kanda, Sarga 15, Verse 29', 'अन्ये मध्येन गच्छन्ति पार्श्वतोऽन्ये प्लवंगमाः।
सलिले प्रपतन्त्यन्ये मार्गमन्ये न लेभिरे।
के चिद्वैहायस गताः सुपर्णा इव पुप्लुवुः॥', 'anye madhyena gacchanti pārśvato ''nye plavaṃgamāḥ
salile prapatanty anye mārgam anye na lebhire
ke cid vaihāyasa gatāḥ suparṇā iva pupluvuḥ', null, 6015029),
('ramayana-6-15-30', 30, 'Yuddha Kanda, Sarga 15, Verse 30', 'घोषेण महता घोषं सागरस्य समुच्छ्रितम्।
भीममन्तर्दधे भीमा तरन्ती हरिवाहिनी॥', 'ghoṣeṇa mahatā ghoṣaṃ sāgarasya samucchritam
bhīmam antardadhe bhīmā tarantī harivāhinī', null, 6015030),
('ramayana-6-15-31', 31, 'Yuddha Kanda, Sarga 15, Verse 31', 'वानराणां हि सा तीर्णा वाहिनी नल सेतुना।
तीरे निविविशे राज्ञा बहुमूलफलोदके॥', 'vānarāṇāṃ hi sā tīrṇā vāhinī nala setunā
tīre niviviśe rājñā bahumūlaphalodake', null, 6015031),
('ramayana-6-15-32', 32, 'Yuddha Kanda, Sarga 15, Verse 32', 'तदद्भुतं राघव कर्म दुष्करं समीक्ष्य देवाः सह सिद्धचारणैः।
उपेत्य रामं सहिता महर्षिभिः समभ्यषिञ्चन्सुशुभैर्जलैः पृथक्॥', 'tad adbhutaṃ rāghava karma duṣkaraṃ samīkṣya devāḥ saha siddhacāraṇaiḥ
upetya rāmaṃ sahitā maharṣibhiḥ samabhyaṣiñcan suśubhair jalaiḥ pṛthak', null, 6015032),
('ramayana-6-15-33', 33, 'Yuddha Kanda, Sarga 15, Verse 33', 'जयस्व शत्रून्नरदेव मेदिनीं ससागरां पालय शाश्वतीः समाः।
इतीव रामं नरदेवसत्कृतं शुभैर्वचोभिर्विविधैरपूजयन्॥', 'jayasva śatrūn naradeva medinīṃ sasāgarāṃ pālaya śāśvatīḥ samāḥ
itīva rāmaṃ naradevasatkṛtaṃ śubhair vacobhir vividhair apūjayan', null, 6015033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 16 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-16-1', 1, 'Yuddha Kanda, Sarga 16, Verse 1', 'सबले सागरं तीर्णे रामे दशरथात्मजे।
अमात्यौ रावणः श्रीमानब्रवीच्छुकसारणौ॥', 'sabale sāgaraṃ tīrṇe rāme daśarathātmaje
amātyau rāvaṇaḥ śrīmān abravīc chukasāraṇau', null, 6016001),
('ramayana-6-16-2', 2, 'Yuddha Kanda, Sarga 16, Verse 2', 'समग्रं सागरं तीर्णं दुस्तरं वानरं बलम्।
अभूतपूर्वं रामेण सागरे सेतुबन्धनम्॥', 'samagraṃ sāgaraṃ tīrṇaṃ dustaraṃ vānaraṃ balam
abhūtapūrvaṃ rāmeṇa sāgare setubandhanam', null, 6016002),
('ramayana-6-16-3', 3, 'Yuddha Kanda, Sarga 16, Verse 3', 'सागरे सेतुबन्धं तु न श्रद्दध्यां कथं चन।
अवश्यं चापि संख्येयं तन्मया वानरं बलम्॥', 'sāgare setubandhaṃ tu na śraddadhyāṃ kathaṃ cana
avaśyaṃ cāpi saṃkhyeyaṃ tan mayā vānaraṃ balam', null, 6016003),
('ramayana-6-16-4', 4, 'Yuddha Kanda, Sarga 16, Verse 4', 'भवन्तौ वानरं सैन्यं प्रविश्यानुपलक्षितौ।
परिमाणं च वीर्यं च ये च मुख्याः प्लवंगमाः॥', 'bhavantau vānaraṃ sainyaṃ praviśyānupalakṣitau
parimāṇaṃ ca vīryaṃ ca ye ca mukhyāḥ plavaṃgamāḥ', null, 6016004),
('ramayana-6-16-5', 5, 'Yuddha Kanda, Sarga 16, Verse 5', 'मन्त्रिणो ये च रामस्य सुग्रीवस्य च संमताः।
ये पूर्वमभिवर्तन्ते ये च शूराः प्लवंगमाः॥', 'mantriṇo ye ca rāmasya sugrīvasya ca saṃmatāḥ
ye pūrvam abhivartante ye ca śūrāḥ plavaṃgamāḥ', null, 6016005),
('ramayana-6-16-6', 6, 'Yuddha Kanda, Sarga 16, Verse 6', 'स च सेतुर्यथा बद्धः सागरे सलिलार्णवे।
निवेशश्च यथा तेषां वानराणां महात्मनाम्॥', 'sa ca setur yathā baddhaḥ sāgare salilārṇave
niveśaś ca yathā teṣāṃ vānarāṇāṃ mahātmanām', null, 6016006),
('ramayana-6-16-7', 7, 'Yuddha Kanda, Sarga 16, Verse 7', 'रामस्य व्यवसायं च वीर्यं प्रहरणानि च।
लक्ष्मणस्य च वीरस्य तत्त्वतो ज्ञातुमर्हथ॥', 'rāmasya vyavasāyaṃ ca vīryaṃ praharaṇāni ca
lakṣmaṇasya ca vīrasya tattvato jñātum arhatha', null, 6016007),
('ramayana-6-16-8', 8, 'Yuddha Kanda, Sarga 16, Verse 8', 'कश्च सेनापतिस्तेषां वानराणां महौजसाम्।
एतज्ज्ञात्वा यथातत्त्वं शीघ्रमगन्तुमर्हथः॥', 'kaś ca senāpatis teṣāṃ vānarāṇāṃ mahaujasām
etaj jñātvā yathātattvaṃ śīghram agantum arhathaḥ', null, 6016008),
('ramayana-6-16-9', 9, 'Yuddha Kanda, Sarga 16, Verse 9', 'इति प्रतिसमादिष्टौ राक्षसौ शुकसारणौ।
हरिरूपधरौ वीरौ प्रविष्टौ वानरं बलम्॥', 'iti pratisamādiṣṭau rākṣasau śukasāraṇau
harirūpadharau vīrau praviṣṭau vānaraṃ balam', null, 6016009),
('ramayana-6-16-10', 10, 'Yuddha Kanda, Sarga 16, Verse 10', 'ततस्तद्वानरं सैन्यमचिन्त्यं लोमहर्षणम्।
संख्यातुं नाध्यगच्छेतां तदा तौ शुकसारणौ॥', 'tatas tad vānaraṃ sainyam acintyaṃ lomaharṣaṇam
saṃkhyātuṃ nādhyagacchetāṃ tadā tau śukasāraṇau', null, 6016010),
('ramayana-6-16-11', 11, 'Yuddha Kanda, Sarga 16, Verse 11', 'तत्स्थितं पर्वताग्रेषु निर्दरेषु गुहासु च।
समुद्रस्य च तीरेषु वनेषूपवनेषु च॥', 'tat sthitaṃ parvatāgreṣu nirdareṣu guhāsu ca
samudrasya ca tīreṣu vaneṣūpavaneṣu ca', null, 6016011),
('ramayana-6-16-12', 12, 'Yuddha Kanda, Sarga 16, Verse 12', 'तरमाणं च तीर्णं च तर्तुकामं च सर्वशः।
निविष्टं निविशच्चैव भीमनादं महाबलम्॥', 'taramāṇaṃ ca tīrṇaṃ ca tartukāmaṃ ca sarvaśaḥ
niviṣṭaṃ niviśac caiva bhīmanādaṃ mahābalam', null, 6016012),
('ramayana-6-16-13', 13, 'Yuddha Kanda, Sarga 16, Verse 13', 'तौ ददर्श महातेजाः प्रच्छन्नौ च विभीषणः।
आचचक्षेऽथ रामाय गृहीत्वा शुकसारणौ।
लङ्कायाः समनुप्राप्तौ चारौ परपुरंजयौ॥', 'tau dadarśa mahātejāḥ pracchannau ca vibhīṣaṇaḥ
ācacakṣe ''tha rāmāya gṛhītvā śukasāraṇau
laṅkāyāḥ samanuprāptau cārau parapuraṃjayau', null, 6016013),
('ramayana-6-16-14', 14, 'Yuddha Kanda, Sarga 16, Verse 14', 'तौ दृष्ट्वा व्यथितौ रामं निराशौ जीविते तदा।
कृताञ्जलिपुटौ भीतौ वचनं चेदमूचतुः॥', 'tau dṛṣṭvā vyathitau rāmaṃ nirāśau jīvite tadā
kṛtāñjalipuṭau bhītau vacanaṃ cedam ūcatuḥ', null, 6016014),
('ramayana-6-16-15', 15, 'Yuddha Kanda, Sarga 16, Verse 15', 'आवामिहागतौ सौम्य रावणप्रहितावुभौ।
परिज्ञातुं बलं कृत्स्नं तवेदं रघुनन्दन॥', 'āvām ihāgatau saumya rāvaṇaprahitāv ubhau
parijñātuṃ balaṃ kṛtsnaṃ tavedaṃ raghunandana', null, 6016015),
('ramayana-6-16-16', 16, 'Yuddha Kanda, Sarga 16, Verse 16', 'तयोस्तद्वचनं श्रुत्वा रामो दशरथात्मजः।
अब्रवीत्प्रहसन्वाक्यं सर्वभूतहिते रतः॥', 'tayos tad vacanaṃ śrutvā rāmo daśarathātmajaḥ
abravīt prahasan vākyaṃ sarvabhūtahite rataḥ', null, 6016016),
('ramayana-6-16-17', 17, 'Yuddha Kanda, Sarga 16, Verse 17', 'यदि दृष्टं बलं कृत्स्नं वयं वा सुसमीक्षिताः।
यथोक्तं वा कृतं कार्यं छन्दतः प्रतिगम्यताम्॥', 'yadi dṛṣṭaṃ balaṃ kṛtsnaṃ vayaṃ vā susamīkṣitāḥ
yathoktaṃ vā kṛtaṃ kāryaṃ chandataḥ pratigamyatām', null, 6016017),
('ramayana-6-16-18', 18, 'Yuddha Kanda, Sarga 16, Verse 18', 'प्रविश्य नगरीं लङ्कां भवद्भ्यां धनदानुजः।
वक्तव्यो रक्षसां राजा यथोक्तं वचनं मम॥', 'praviśya nagarīṃ laṅkāṃ bhavadbhyāṃ dhanadānujaḥ
vaktavyo rakṣasāṃ rājā yathoktaṃ vacanaṃ mama', null, 6016018),
('ramayana-6-16-19', 19, 'Yuddha Kanda, Sarga 16, Verse 19', 'यद्बलं च समाश्रित्य सीतां मे हृतवानसि।
तद्दर्शय यथाकामं ससैन्यः सहबान्धवः॥', 'yad balaṃ ca samāśritya sītāṃ me hṛtavān asi
tad darśaya yathākāmaṃ sasainyaḥ sahabāndhavaḥ', null, 6016019),
('ramayana-6-16-20', 20, 'Yuddha Kanda, Sarga 16, Verse 20', 'श्वःकाले नगरीं लङ्कां सप्राकारां सतोरणाम्।
राक्षसं च बलं पश्य शरैर्विध्वंसितं मया॥', 'śvaḥkāle nagarīṃ laṅkāṃ saprākārāṃ satoraṇām
rākṣasaṃ ca balaṃ paśya śarair vidhvaṃsitaṃ mayā', null, 6016020),
('ramayana-6-16-21', 21, 'Yuddha Kanda, Sarga 16, Verse 21', 'घोरं रोषमहं मोक्ष्ये बलं धारय रावण।
श्वःकाले वज्रवान्वज्रं दानवेष्विव वासवः॥', 'ghoraṃ roṣam ahaṃ mokṣye balaṃ dhāraya rāvaṇa
śvaḥkāle vajravān vajraṃ dānaveṣv iva vāsavaḥ', null, 6016021),
('ramayana-6-16-22', 22, 'Yuddha Kanda, Sarga 16, Verse 22', 'इति प्रतिसमादिष्टौ राक्षसौ शुकसारणौ।
आगम्य नगरीं लङ्कामब्रूतां राक्षसाधिपम्॥', 'iti pratisamādiṣṭau rākṣasau śukasāraṇau
āgamya nagarīṃ laṅkām abrūtāṃ rākṣasādhipam', null, 6016022),
('ramayana-6-16-23', 23, 'Yuddha Kanda, Sarga 16, Verse 23', 'विभीषणगृहीतौ तु वधार्हौ राक्षसेश्वर।
दृष्ट्वा धर्मात्मना मुक्तौ रामेणामिततेजसा॥', 'vibhīṣaṇagṛhītau tu vadhārhau rākṣaseśvara
dṛṣṭvā dharmātmanā muktau rāmeṇāmitatejasā', null, 6016023),
('ramayana-6-16-24', 24, 'Yuddha Kanda, Sarga 16, Verse 24', 'एकस्थानगता यत्र चत्वारः पुरुषर्षभाः।
लोकपालोपमाः शूराः कृतास्त्रा दृढविक्रमाः॥', 'ekasthānagatā yatra catvāraḥ puruṣarṣabhāḥ
lokapālopamāḥ śūrāḥ kṛtāstrā dṛḍhavikramāḥ', null, 6016024),
('ramayana-6-16-25', 25, 'Yuddha Kanda, Sarga 16, Verse 25', 'रामो दाशरथिः श्रीमांल्लक्ष्मणश्च विभीषणः।
सुग्रीवश्च महातेजा महेन्द्रसमविक्रमः॥', 'rāmo dāśarathiḥ śrīmāṃl lakṣmaṇaś ca vibhīṣaṇaḥ
sugrīvaś ca mahātejā mahendrasamavikramaḥ', null, 6016025),
('ramayana-6-16-26', 26, 'Yuddha Kanda, Sarga 16, Verse 26', 'एते शक्ताः पुरीं लङ्कां सप्राकारां सतोरणाम्।
उत्पाट्य संक्रामयितुं सर्वे तिष्ठन्तु वानराः॥', 'ete śaktāḥ purīṃ laṅkāṃ saprākārāṃ satoraṇām
utpāṭya saṃkrāmayituṃ sarve tiṣṭhantu vānarāḥ', null, 6016026),
('ramayana-6-16-27', 27, 'Yuddha Kanda, Sarga 16, Verse 27', 'यादृशं तस्य रामस्य रूपं प्रहरणानि च।
वधिष्यति पुरीं लङ्कामेकस्तिष्ठन्तु ते त्रयः॥', 'yādṛśaṃ tasya rāmasya rūpaṃ praharaṇāni ca
vadhiṣyati purīṃ laṅkām ekas tiṣṭhantu te trayaḥ', null, 6016027),
('ramayana-6-16-28', 28, 'Yuddha Kanda, Sarga 16, Verse 28', 'रामलक्ष्मणगुप्ता सा सुग्रीवेण च वाहिनी।
बभूव दुर्धर्षतरा सर्वैरपि सुरासुरैः॥', 'rāmalakṣmaṇaguptā sā sugrīveṇa ca vāhinī
babhūva durdharṣatarā sarvair api surāsuraiḥ', null, 6016028),
('ramayana-6-16-29', 29, 'Yuddha Kanda, Sarga 16, Verse 29', 'प्रहृष्टरूपा ध्वजिनी वनौकसां महात्मनां संप्रति योद्धुमिच्छताम्।
अलं विरोधेन शमो विधीयतां प्रदीयतां दाशरथाय मैथिली॥', 'prahṛṣṭarūpā dhvajinī vanaukasāṃ mahātmanāṃ saṃprati yoddhum icchatām
alaṃ virodhena śamo vidhīyatāṃ pradīyatāṃ dāśarathāya maithilī', null, 6016029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 17 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-17-1', 1, 'Yuddha Kanda, Sarga 17, Verse 1', 'तद्वचः पथ्यमक्लीबं सारणेनाभिभाषितम्।
निशम्य रावणो राजा प्रत्यभाषत सारणम्॥', 'tad vacaḥ pathyam aklībaṃ sāraṇenābhibhāṣitam
niśamya rāvaṇo rājā pratyabhāṣata sāraṇam', null, 6017001),
('ramayana-6-17-2', 2, 'Yuddha Kanda, Sarga 17, Verse 2', 'यदि मामभियुञ्जीरन्देवगन्धर्वदानवाः।
नैव सीतां प्रदास्यामि सर्वलोकभयादपि॥', 'yadi mām abhiyuñjīran devagandharvadānavāḥ
naiva sītāṃ pradāsyāmi sarvalokabhayād api', null, 6017002),
('ramayana-6-17-3', 3, 'Yuddha Kanda, Sarga 17, Verse 3', 'त्वं तु सौम्य परित्रस्तो हरिभिर्निर्जितो भृशम्।
प्रतिप्रदानमद्यैव सीतायाः साधु मन्यसे।
को हि नाम सपत्नो मां समरे जेतुमर्हति॥', 'tvaṃ tu saumya paritrasto haribhir nirjito bhṛśam
pratipradānam adyaiva sītāyāḥ sādhu manyase
ko hi nāma sapatno māṃ samare jetum arhati', null, 6017003),
('ramayana-6-17-4', 4, 'Yuddha Kanda, Sarga 17, Verse 4', 'इत्युक्त्वा परुषं वाक्यं रावणो राक्षसाधिपः।
आरुरोह ततः श्रीमान्प्रासादं हिमपाण्डुरम्।
बहुतालसमुत्सेधं रावणोऽथ दिदृक्षया॥', 'ity uktvā paruṣaṃ vākyaṃ rāvaṇo rākṣasādhipaḥ
āruroha tataḥ śrīmān prāsādaṃ himapāṇḍuram
bahutālasamutsedhaṃ rāvaṇo ''tha didṛkṣayā', null, 6017004),
('ramayana-6-17-5', 5, 'Yuddha Kanda, Sarga 17, Verse 5', 'ताभ्यां चराभ्यां सहितो रावणः क्रोधमूर्छितः।
पश्यमानः समुद्रं च पर्वतांश्च वनानि च।
ददर्श पृथिवीदेशं सुसंपूर्णं प्लवंगमैः॥', 'tābhyāṃ carābhyāṃ sahito rāvaṇaḥ krodhamūrchitaḥ
paśyamānaḥ samudraṃ ca parvatāṃś ca vanāni ca
dadarśa pṛthivīdeśaṃ susaṃpūrṇaṃ plavaṃgamaiḥ', null, 6017005),
('ramayana-6-17-6', 6, 'Yuddha Kanda, Sarga 17, Verse 6', 'तदपारमसंख्येयं वानराणां महद्बलम्।
आलोक्य रावणो राजा परिपप्रच्छ सारणम्॥', 'tad apāram asaṃkhyeyaṃ vānarāṇāṃ mahad balam
ālokya rāvaṇo rājā paripapraccha sāraṇam', null, 6017006),
('ramayana-6-17-7', 7, 'Yuddha Kanda, Sarga 17, Verse 7', 'एषां वानरमुख्यानां के शूराः के महाबलाः।
के पूर्वमभिवर्तन्ते महोत्साहाः समन्ततः॥', 'eṣāṃ vānaramukhyānāṃ ke śūrāḥ ke mahābalāḥ
ke pūrvam abhivartante mahotsāhāḥ samantataḥ', null, 6017007),
('ramayana-6-17-8', 8, 'Yuddha Kanda, Sarga 17, Verse 8', 'केषां शृणोति सुग्रीवः के वा यूथपयूथपाः।
सारणाचक्ष्व मे सर्वं के प्रधानाः प्लवंगमाः॥', 'keṣāṃ śṛṇoti sugrīvaḥ ke vā yūthapayūthapāḥ
sāraṇācakṣva me sarvaṃ ke pradhānāḥ plavaṃgamāḥ', null, 6017008),
('ramayana-6-17-9', 9, 'Yuddha Kanda, Sarga 17, Verse 9', 'सारणो राक्षसेन्द्रस्य वचनं परिपृच्छतः।
आचचक्षेऽथ मुख्यज्ञो मुख्यांस्तांस्तु वनौकसः॥', 'sāraṇo rākṣasendrasya vacanaṃ paripṛcchataḥ
ācacakṣe ''tha mukhyajño mukhyāṃs tāṃs tu vanaukasaḥ', null, 6017009),
('ramayana-6-17-10', 10, 'Yuddha Kanda, Sarga 17, Verse 10', 'एष योऽभिमुखो लङ्कां नर्दंस्तिष्ठति वानरः।
यूथपानां सहस्राणां शतेन परिवारितः॥', 'eṣa yo ''bhimukho laṅkāṃ nardaṃs tiṣṭhati vānaraḥ
yūthapānāṃ sahasrāṇāṃ śatena parivāritaḥ', null, 6017010),
('ramayana-6-17-11', 11, 'Yuddha Kanda, Sarga 17, Verse 11', 'यस्य घोषेण महता सप्राकारा सतोरणा।
लङ्का प्रवेपते सर्वा सशैलवनकानना॥', 'yasya ghoṣeṇa mahatā saprākārā satoraṇā
laṅkā pravepate sarvā saśailavanakānanā', null, 6017011),
('ramayana-6-17-12', 12, 'Yuddha Kanda, Sarga 17, Verse 12', 'सर्वशाखामृगेन्द्रस्य सुग्रीवस्य महात्मनः।
बलाग्रे तिष्ठते वीरो नीलो नामैष यूथपः॥', 'sarvaśākhāmṛgendrasya sugrīvasya mahātmanaḥ
balāgre tiṣṭhate vīro nīlo nāmaiṣa yūthapaḥ', null, 6017012),
('ramayana-6-17-13', 13, 'Yuddha Kanda, Sarga 17, Verse 13', 'बाहू प्रगृह्य यः पद्भ्यां महीं गच्छति वीर्यवान्।
लङ्कामभिमुखः कोपादभीक्ष्णं च विजृम्भते॥', 'bāhū pragṛhya yaḥ padbhyāṃ mahīṃ gacchati vīryavān
laṅkām abhimukhaḥ kopād abhīkṣṇaṃ ca vijṛmbhate', null, 6017013),
('ramayana-6-17-14', 14, 'Yuddha Kanda, Sarga 17, Verse 14', 'गिरिशृङ्गप्रतीकाशः पद्मकिञ्जल्कसंनिभः।
स्फोटयत्यभिसंरब्धो लाङ्गूलं च पुनः पुनः॥', 'giriśṛṅgapratīkāśaḥ padmakiñjalkasaṃnibhaḥ
sphoṭayaty abhisaṃrabdho lāṅgūlaṃ ca punaḥ punaḥ', null, 6017014),
('ramayana-6-17-15', 15, 'Yuddha Kanda, Sarga 17, Verse 15', 'यस्य लाङ्गूलशब्देन स्वनन्तीव दिशो दश।
एष वानरराजेन सुर्ग्रीवेणाभिषेचितः।
यौवराज्येऽङ्गदो नाम त्वामाह्वयति संयुगे॥', 'yasya lāṅgūlaśabdena svanantīva diśo daśa
eṣa vānararājena surgrīveṇābhiṣecitaḥ
yauvarājye ''ṅgado nāma tvām āhvayati saṃyuge', null, 6017015),
('ramayana-6-17-16', 16, 'Yuddha Kanda, Sarga 17, Verse 16', 'ये तु विष्टभ्य गात्राणि क्ष्वेडयन्ति नदन्ति च।
उत्थाय च विजृम्भन्ते क्रोधेन हरिपुंगवाः॥', 'ye tu viṣṭabhya gātrāṇi kṣveḍayanti nadanti ca
utthāya ca vijṛmbhante krodhena haripuṃgavāḥ', null, 6017016),
('ramayana-6-17-17', 17, 'Yuddha Kanda, Sarga 17, Verse 17', 'एते दुष्प्रसहा घोराश्चण्डाश्चण्डपराक्रमाः।
अष्टौ शतसहस्राणि दशकोटिशतानि च॥', 'ete duṣprasahā ghorāś caṇḍāś caṇḍaparākramāḥ
aṣṭau śatasahasrāṇi daśakoṭiśatāni ca', null, 6017017),
('ramayana-6-17-18', 18, 'Yuddha Kanda, Sarga 17, Verse 18', 'य एनमनुगच्छन्ति वीराश्चन्दनवासिनः।
एष आशंसते लङ्कां स्वेनानीकेन मर्दितुम्॥', 'ya enam anugacchanti vīrāś candanavāsinaḥ
eṣa āśaṃsate laṅkāṃ svenānīkena marditum', null, 6017018),
('ramayana-6-17-19', 19, 'Yuddha Kanda, Sarga 17, Verse 19', 'श्वेतो रजतसंकाशः सबलो भीमविक्रमः।
बुद्धिमान्वानरः शूरस्त्रिषु लोकेषु विश्रुतः॥', 'śveto rajatasaṃkāśaḥ sabalo bhīmavikramaḥ
buddhimān vānaraḥ śūras triṣu lokeṣu viśrutaḥ', null, 6017019),
('ramayana-6-17-20', 20, 'Yuddha Kanda, Sarga 17, Verse 20', 'तूर्णं सुग्रीवमागम्य पुनर्गच्छति वानरः।
विभजन्वानरीं सेनामनीकानि प्रहर्षयन्॥', 'tūrṇaṃ sugrīvam āgamya punar gacchati vānaraḥ
vibhajan vānarīṃ senām anīkāni praharṣayan', null, 6017020),
('ramayana-6-17-21', 21, 'Yuddha Kanda, Sarga 17, Verse 21', 'यः पुरा गोमतीतीरे रम्यं पर्येति पर्वतम्।
नाम्ना संकोचनो नाम नानानगयुतो गिरिः॥', 'yaḥ purā gomatītīre ramyaṃ paryeti parvatam
nāmnā saṃkocano nāma nānānagayuto giriḥ', null, 6017021),
('ramayana-6-17-22', 22, 'Yuddha Kanda, Sarga 17, Verse 22', 'तत्र राज्यं प्रशास्त्येष कुमुदो नाम यूथपः।
योऽसौ शतसहस्राणां सहस्रं परिकर्षति॥', 'tatra rājyaṃ praśāsty eṣa kumudo nāma yūthapaḥ
yo ''sau śatasahasrāṇāṃ sahasraṃ parikarṣati', null, 6017022),
('ramayana-6-17-23', 23, 'Yuddha Kanda, Sarga 17, Verse 23', 'यस्य वाला बहुव्यामा दीर्घलाङ्गूलमाश्रिताः।
ताम्राः पीताः सिताः श्वेताः प्रकीर्णा घोरकर्मणः॥', 'yasya vālā bahuvyāmā dīrghalāṅgūlam āśritāḥ
tāmrāḥ pītāḥ sitāḥ śvetāḥ prakīrṇā ghorakarmaṇaḥ', null, 6017023),
('ramayana-6-17-24', 24, 'Yuddha Kanda, Sarga 17, Verse 24', 'अदीनो रोषणश्चण्डः संग्राममभिकाङ्क्षति।
एषैवाशंसते लङ्कां स्वेनानीकेन मर्दितुम्॥', 'adīno roṣaṇaś caṇḍaḥ saṃgrāmam abhikāṅkṣati
eṣaivāśaṃsate laṅkāṃ svenānīkena marditum', null, 6017024),
('ramayana-6-17-25', 25, 'Yuddha Kanda, Sarga 17, Verse 25', 'यस्त्वेष सिंहसंकाशः कपिलो दीर्घकेसरः।
निभृतः प्रेक्षते लङ्कां दिधक्षन्निव चक्षुषा॥', 'yas tv eṣa siṃhasaṃkāśaḥ kapilo dīrghakesaraḥ
nibhṛtaḥ prekṣate laṅkāṃ didhakṣann iva cakṣuṣā', null, 6017025),
('ramayana-6-17-26', 26, 'Yuddha Kanda, Sarga 17, Verse 26', 'विन्ध्यं कृष्णगिरिं सह्यं पर्वतं च सुदर्शनम्।
राजन्सततमध्यास्ते रम्भो नामैष यूथपः॥', 'vindhyaṃ kṛṣṇagiriṃ sahyaṃ parvataṃ ca sudarśanam
rājan satatam adhyāste rambho nāmaiṣa yūthapaḥ', null, 6017026),
('ramayana-6-17-27', 27, 'Yuddha Kanda, Sarga 17, Verse 27', 'शतं शतसहस्राणां त्रिंशच्च हरियूथपाः।
परिवार्यानुगच्छन्ति लङ्कां मर्दितुमोजसा॥', 'śataṃ śatasahasrāṇāṃ triṃśac ca hariyūthapāḥ
parivāryānugacchanti laṅkāṃ marditum ojasā', null, 6017027),
('ramayana-6-17-28', 28, 'Yuddha Kanda, Sarga 17, Verse 28', 'यस्तु कर्णौ विवृणुते जृम्भते च पुनः पुनः।
न च संविजते मृत्योर्न च यूथाद्विधावति॥', 'yas tu karṇau vivṛṇute jṛmbhate ca punaḥ punaḥ
na ca saṃvijate mṛtyor na ca yūthād vidhāvati', null, 6017028),
('ramayana-6-17-29', 29, 'Yuddha Kanda, Sarga 17, Verse 29', 'महाबलो वीतभयो रम्यं साल्वेय पर्वतम्।
राजन्सततमध्यास्ते शरभो नाम यूथपः॥', 'mahābalo vītabhayo ramyaṃ sālveya parvatam
rājan satatam adhyāste śarabho nāma yūthapaḥ', null, 6017029),
('ramayana-6-17-30', 30, 'Yuddha Kanda, Sarga 17, Verse 30', 'एतस्य बलिनः सर्वे विहारा नाम यूथपाः।
राजञ्शतसहस्राणि चत्वारिंशत्तथैव च॥', 'etasya balinaḥ sarve vihārā nāma yūthapāḥ
rājañ śatasahasrāṇi catvāriṃśat tathaiva ca', null, 6017030),
('ramayana-6-17-31', 31, 'Yuddha Kanda, Sarga 17, Verse 31', 'यस्तु मेघ इवाकाशं महानावृत्य तिष्ठति।
मध्ये वानरवीराणां सुराणामिव वासवः॥', 'yas tu megha ivākāśaṃ mahān āvṛtya tiṣṭhati
madhye vānaravīrāṇāṃ surāṇām iva vāsavaḥ', null, 6017031),
('ramayana-6-17-32', 32, 'Yuddha Kanda, Sarga 17, Verse 32', 'भेरीणामिव संनादो यस्यैष श्रूयते महान्।
घोरः शाखामृगेन्द्राणां संग्राममभिकाङ्क्षताम्॥', 'bherīṇām iva saṃnādo yasyaiṣa śrūyate mahān
ghoraḥ śākhāmṛgendrāṇāṃ saṃgrāmam abhikāṅkṣatām', null, 6017032),
('ramayana-6-17-33', 33, 'Yuddha Kanda, Sarga 17, Verse 33', 'एष पर्वतमध्यास्ते पारियात्रमनुत्तमम्।
युद्धे दुष्प्रसहो नित्यं पनसो नाम यूथपः॥', 'eṣa parvatam adhyāste pāriyātram anuttamam
yuddhe duṣprasaho nityaṃ panaso nāma yūthapaḥ', null, 6017033),
('ramayana-6-17-34', 34, 'Yuddha Kanda, Sarga 17, Verse 34', 'एनं शतसहस्राणां शतार्धं पर्युपासते।
यूथपा यूथपश्रेष्ठं येषां यूथानि भागशः॥', 'enaṃ śatasahasrāṇāṃ śatārdhaṃ paryupāsate
yūthapā yūthapaśreṣṭhaṃ yeṣāṃ yūthāni bhāgaśaḥ', null, 6017034),
('ramayana-6-17-35', 35, 'Yuddha Kanda, Sarga 17, Verse 35', 'यस्तु भीमां प्रवल्गन्तीं चमूं तिष्ठति शोभयन्।
स्थितां तीरे समुद्रस्य द्वितीय इव सागरः॥', 'yas tu bhīmāṃ pravalgantīṃ camūṃ tiṣṭhati śobhayan
sthitāṃ tīre samudrasya dvitīya iva sāgaraḥ', null, 6017035),
('ramayana-6-17-36', 36, 'Yuddha Kanda, Sarga 17, Verse 36', 'एष दर्दरसंकाशो विनतो नाम यूथपः।
पिबंश्चरति पर्णाशां नदीनामुत्तमां नदीम्॥', 'eṣa dardarasaṃkāśo vinato nāma yūthapaḥ
pibaṃś carati parṇāśāṃ nadīnām uttamāṃ nadīm', null, 6017036),
('ramayana-6-17-37', 37, 'Yuddha Kanda, Sarga 17, Verse 37', 'षष्टिः शतसहस्राणि बलमस्य प्लवंगमाः।
त्वामाह्वयति युद्धाय क्रथनो नाम यूथपः॥', 'ṣaṣṭiḥ śatasahasrāṇi balam asya plavaṃgamāḥ
tvām āhvayati yuddhāya krathano nāma yūthapaḥ', null, 6017037),
('ramayana-6-17-38', 38, 'Yuddha Kanda, Sarga 17, Verse 38', 'यस्तु गैरिकवर्णाभं वपुः पुष्यति वानरः।
गवयो नाम तेजस्वी त्वां क्रोधादभिवर्तते॥', 'yas tu gairikavarṇābhaṃ vapuḥ puṣyati vānaraḥ
gavayo nāma tejasvī tvāṃ krodhād abhivartate', null, 6017038),
('ramayana-6-17-39', 39, 'Yuddha Kanda, Sarga 17, Verse 39', 'एनं शतसहस्राणि सप्ततिः पर्युपासते।
एष आशंसते लङ्कां स्वेनानीकेन मर्दितुम्॥', 'enaṃ śatasahasrāṇi saptatiḥ paryupāsate
eṣa āśaṃsate laṅkāṃ svenānīkena marditum', null, 6017039),
('ramayana-6-17-40', 40, 'Yuddha Kanda, Sarga 17, Verse 40', 'एते दुष्प्रसहा घोरा बलिनः कामरूपिणः।
यूथपा यूथपश्रेष्ठा येषां संख्या न विद्यते॥', 'ete duṣprasahā ghorā balinaḥ kāmarūpiṇaḥ
yūthapā yūthapaśreṣṭhā yeṣāṃ saṃkhyā na vidyate', null, 6017040)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 18 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-18-1', 1, 'Yuddha Kanda, Sarga 18, Verse 1', 'तांस्तु तेऽहं प्रवक्ष्यामि प्रेक्षमाणस्य यूथपान्।
राघवार्थे पराक्रान्ता ये न रक्षन्ति जीवितम्॥', 'tāṃs tu te ''haṃ pravakṣyāmi prekṣamāṇasya yūthapān
rāghavārthe parākrāntā ye na rakṣanti jīvitam', null, 6018001),
('ramayana-6-18-2', 2, 'Yuddha Kanda, Sarga 18, Verse 2', 'स्निग्धा यस्य बहुश्यामा बाला लाङ्गूलमाश्रिताः।
ताम्राः पीताः सिताः श्वेताः प्रकीर्णा घोरकर्मणः॥', 'snigdhā yasya bahuśyāmā bālā lāṅgūlam āśritāḥ
tāmrāḥ pītāḥ sitāḥ śvetāḥ prakīrṇā ghorakarmaṇaḥ', null, 6018002),
('ramayana-6-18-3', 3, 'Yuddha Kanda, Sarga 18, Verse 3', 'प्रगृहीताः प्रकाशन्ते सूर्यस्येव मरीचयः।
पृथिव्यां चानुकृष्यन्ते हरो नामैष यूथपः॥', 'pragṛhītāḥ prakāśante sūryasyeva marīcayaḥ
pṛthivyāṃ cānukṛṣyante haro nāmaiṣa yūthapaḥ', null, 6018003),
('ramayana-6-18-4', 4, 'Yuddha Kanda, Sarga 18, Verse 4', 'यं पृष्ठतोऽनुगच्छन्ति शतशोऽथ सहस्रशः।
द्रुमानुद्यम्य सहिता लङ्कारोहणतत्पराः॥', 'yaṃ pṛṣṭhato ''nugacchanti śataśo ''tha sahasraśaḥ
drumān udyamya sahitā laṅkārohaṇatatparāḥ', null, 6018004),
('ramayana-6-18-5', 5, 'Yuddha Kanda, Sarga 18, Verse 5', 'एष कोटीसहस्रेण वानराणां महौजसाम्।
आकाङ्क्षते त्वां संग्रामे जेतुं परपुरंजय॥', 'eṣa koṭīsahasreṇa vānarāṇāṃ mahaujasām
ākāṅkṣate tvāṃ saṃgrāme jetuṃ parapuraṃjaya', null, 6018005),
('ramayana-6-18-6', 6, 'Yuddha Kanda, Sarga 18, Verse 6', 'नीलानिव महामेघांस्तिष्ठतो यांस्तु पश्यसि।
असिताञ्जनसंकाशान्युद्धे सत्यपराक्रमान्॥', 'nīlān iva mahāmeghāṃs tiṣṭhato yāṃs tu paśyasi
asitāñ janasaṃkāśān yuddhe satyaparākramān', null, 6018006),
('ramayana-6-18-7', 7, 'Yuddha Kanda, Sarga 18, Verse 7', 'नखदंष्ट्रायुधान्वीरांस्तीक्ष्णकोपान्भयावहान्।
असंख्येयाननिर्देश्यान्परं पारमिवोदधेः॥', 'nakhadaṃṣṭrāyudhān vīrāṃs tīkṣṇakopān bhayāvahān
asaṃkhyeyān anirdeśyān paraṃ pāram ivodadheḥ', null, 6018007),
('ramayana-6-18-8', 8, 'Yuddha Kanda, Sarga 18, Verse 8', 'पर्वतेषु च ये के चिद्विषमेषु नदीषु च।
एते त्वामभिवर्तन्ते राजन्नृष्काः सुदारुणाः॥', 'parvateṣu ca ye ke cid viṣameṣu nadīṣu ca
ete tvām abhivartante rājann ṛṣkāḥ sudāruṇāḥ', null, 6018008),
('ramayana-6-18-9', 9, 'Yuddha Kanda, Sarga 18, Verse 9', 'एषां मध्ये स्थितो राजन्भीमाक्षो भीमदर्शनः।
पर्जन्य इव जीमूतैः समन्तात्परिवारितः॥', 'eṣāṃ madhye sthito rājan bhīmākṣo bhīmadarśanaḥ
parjanya iva jīmūtaiḥ samantāt parivāritaḥ', null, 6018009),
('ramayana-6-18-10', 10, 'Yuddha Kanda, Sarga 18, Verse 10', 'ऋक्षवन्तं गिरिश्रेष्ठमध्यास्ते नर्मदां पिबन्।
सर्वर्क्षाणामधिपतिर्धूम्रो नामैष यूथपः॥', 'ṛkṣavantaṃ giriśreṣṭham adhyāste narmadāṃ piban
sarvarkṣāṇām adhipatir dhūmro nāmaiṣa yūthapaḥ', null, 6018010),
('ramayana-6-18-11', 11, 'Yuddha Kanda, Sarga 18, Verse 11', 'यवीयानस्य तु भ्राता पश्यैनं पर्वतोपमम्।
भ्रात्रा समानो रूपेण विशिष्टस्तु पराक्रमे॥', 'yavīyān asya tu bhrātā paśyainaṃ parvatopamam
bhrātrā samāno rūpeṇa viśiṣṭas tu parākrame', null, 6018011),
('ramayana-6-18-12', 12, 'Yuddha Kanda, Sarga 18, Verse 12', 'स एष जाम्बवान्नाम महायूथपयूथपः।
प्रशान्तो गुरुवर्ती च संप्रहारेष्वमर्षणः॥', 'sa eṣa jāmbavān nāma mahāyūthapayūthapaḥ
praśānto guruvartī ca saṃprahāreṣv amarṣaṇaḥ', null, 6018012),
('ramayana-6-18-13', 13, 'Yuddha Kanda, Sarga 18, Verse 13', 'एतेन साह्यं सुमहत्कृतं शक्रस्य धीमता।
देवासुरे जाम्बवता लब्धाश्च बहवो वराः॥', 'etena sāhyaṃ sumahat kṛtaṃ śakrasya dhīmatā
devāsure jāmbavatā labdhāś ca bahavo varāḥ', null, 6018013),
('ramayana-6-18-14', 14, 'Yuddha Kanda, Sarga 18, Verse 14', 'आरुह्य पर्वताग्रेभ्यो महाभ्रविपुलाः शिलाः।
मुञ्चन्ति विपुलाकारा न मृत्योरुद्विजन्ति च॥', 'āruhya parvatāgrebhyo mahābhravipulāḥ śilāḥ
muñcanti vipulākārā na mṛtyor udvijanti ca', null, 6018014),
('ramayana-6-18-15', 15, 'Yuddha Kanda, Sarga 18, Verse 15', 'राक्षसानां च सदृशाः पिशाचानां च रोमशाः।
एतस्य सैन्ये बहवो विचरन्त्यग्नितेजसः॥', 'rākṣasānāṃ ca sadṛśāḥ piśācānāṃ ca romaśāḥ
etasya sainye bahavo vicaranty agnitejasaḥ', null, 6018015),
('ramayana-6-18-16', 16, 'Yuddha Kanda, Sarga 18, Verse 16', 'यं त्वेनमभिसंरब्धं प्लवमानमिव स्थितम्।
प्रेक्षन्ते वानराः सर्वे स्थितं यूथपयूथपम्॥', 'yaṃ tv enam abhisaṃrabdhaṃ plavamānam iva sthitam
prekṣante vānarāḥ sarve sthitaṃ yūthapayūthapam', null, 6018016),
('ramayana-6-18-17', 17, 'Yuddha Kanda, Sarga 18, Verse 17', 'एष राजन्सहस्राक्षं पर्युपास्ते हरीश्वरः।
बलेन बलसंपन्नो रम्भो नामैष यूथपः॥', 'eṣa rājan sahasrākṣaṃ paryupāste harīśvaraḥ
balena balasaṃpanno rambho nāmaiṣa yūthapaḥ', null, 6018017),
('ramayana-6-18-18', 18, 'Yuddha Kanda, Sarga 18, Verse 18', 'यः स्थितं योजने शैलं गच्छन्पार्श्वेन सेवते।
ऊर्ध्वं तथैव कायेन गतः प्राप्नोति योजनम्॥', 'yaḥ sthitaṃ yojane śailaṃ gacchan pārśvena sevate
ūrdhvaṃ tathaiva kāyena gataḥ prāpnoti yojanam', null, 6018018),
('ramayana-6-18-19', 19, 'Yuddha Kanda, Sarga 18, Verse 19', 'यस्मान्न परमं रूपं चतुष्पादेषु विद्यते।
श्रुतः संनादनो नाम वानराणां पितामहः॥', 'yasmān na paramaṃ rūpaṃ catuṣpādeṣu vidyate
śrutaḥ saṃnādano nāma vānarāṇāṃ pitāmahaḥ', null, 6018019),
('ramayana-6-18-20', 20, 'Yuddha Kanda, Sarga 18, Verse 20', 'येन युद्धं तदा दत्तं रणे शक्रस्य धीमता।
पराजयश्च न प्राप्तः सोऽयं यूथपयूथपः।
यस्य विक्रममाणस्य शक्रस्येव पराक्रमः॥', 'yena yuddhaṃ tadā dattaṃ raṇe śakrasya dhīmatā
parājayaś ca na prāptaḥ so ''yaṃ yūthapayūthapaḥ
yasya vikramamāṇasya śakrasyeva parākramaḥ', null, 6018020),
('ramayana-6-18-21', 21, 'Yuddha Kanda, Sarga 18, Verse 21', 'एष गन्धर्वकन्यायामुत्पन्नः कृष्णवर्त्मना।
पुरा देवासुरे युद्धे साह्यार्थं त्रिदिवौकसाम्॥', 'eṣa gandharvakanyāyām utpannaḥ kṛṣṇavartmanā
purā devāsure yuddhe sāhyārthaṃ tridivaukasām', null, 6018021),
('ramayana-6-18-22', 22, 'Yuddha Kanda, Sarga 18, Verse 22', 'यस्य वैश्रवणो राजा जम्बूमुपनिषेवते।
यो राजा पर्वतेन्द्राणां बहुकिंनरसेविनाम्॥', 'yasya vaiśravaṇo rājā jambūm upaniṣevate
yo rājā parvatendrāṇāṃ bahukiṃnarasevinām', null, 6018022),
('ramayana-6-18-23', 23, 'Yuddha Kanda, Sarga 18, Verse 23', 'विहारसुखदो नित्यं भ्रातुस्ते राक्षसाधिप।
तत्रैष वसति श्रीमान्बलवान्वानरर्षभः।
युद्धेष्वकत्थनो नित्यं क्रथनो नाम यूथपः॥', 'vihārasukhado nityaṃ bhrātus te rākṣasādhipa
tatraiṣa vasati śrīmān balavān vānararṣabhaḥ
yuddheṣv akatthano nityaṃ krathano nāma yūthapaḥ', null, 6018023),
('ramayana-6-18-24', 24, 'Yuddha Kanda, Sarga 18, Verse 24', 'वृतः कोटिसहस्रेण हरीणां समुपस्थितः।
एषैवाशंसते लङ्कां स्वेनानीकेन मर्दितुम्॥', 'vṛtaḥ koṭisahasreṇa harīṇāṃ samupasthitaḥ
eṣaivāśaṃsate laṅkāṃ svenānīkena marditum', null, 6018024),
('ramayana-6-18-25', 25, 'Yuddha Kanda, Sarga 18, Verse 25', 'यो गङ्गामनु पर्येति त्रासयन्हस्तियूथपान्।
हस्तिनां वानराणां च पूर्ववैरमनुस्मरन्॥', 'yo gaṅgām anu paryeti trāsayan hastiyūthapān
hastināṃ vānarāṇāṃ ca pūrvavairam anusmaran', null, 6018025),
('ramayana-6-18-26', 26, 'Yuddha Kanda, Sarga 18, Verse 26', 'एष यूथपतिर्नेता गच्छन्गिरिगुहाशयः।
हरीणां वाहिनी मुख्यो नदीं हैमवतीमनु॥', 'eṣa yūthapatir netā gacchan giriguhāśayaḥ
harīṇāṃ vāhinī mukhyo nadīṃ haimavatīm anu', null, 6018026),
('ramayana-6-18-27', 27, 'Yuddha Kanda, Sarga 18, Verse 27', 'उशीर बीजमाश्रित्य पर्वतं मन्दरोपमम्।
रमते वानरश्रेष्ठो दिवि शक्र इव स्वयम्॥', 'uśīra bījam āśritya parvataṃ mandaropamam
ramate vānaraśreṣṭho divi śakra iva svayam', null, 6018027),
('ramayana-6-18-28', 28, 'Yuddha Kanda, Sarga 18, Verse 28', 'एनं शतसहस्राणां सहस्रमभिवर्तते।
एष दुर्मर्षणो राजन्प्रमाथी नाम यूथपः॥', 'enaṃ śatasahasrāṇāṃ sahasram abhivartate
eṣa durmarṣaṇo rājan pramāthī nāma yūthapaḥ', null, 6018028),
('ramayana-6-18-29', 29, 'Yuddha Kanda, Sarga 18, Verse 29', 'वातेनेवोद्धतं मेघं यमेनमनुपश्यसि।
विवर्तमानं बहुशो यत्रैतद्बहुलं रजः॥', 'vātenevoddhataṃ meghaṃ yam enam anupaśyasi
vivartamānaṃ bahuśo yatraitad bahulaṃ rajaḥ', null, 6018029),
('ramayana-6-18-30', 30, 'Yuddha Kanda, Sarga 18, Verse 30', 'एतेऽसितमुखा घोरा गोलाङ्गूला महाबलाः।
शतं शतसहस्राणि दृष्ट्वा वै सेतुबन्धनम्॥', 'ete ''sitamukhā ghorā golāṅgūlā mahābalāḥ
śataṃ śatasahasrāṇi dṛṣṭvā vai setubandhanam', null, 6018030),
('ramayana-6-18-31', 31, 'Yuddha Kanda, Sarga 18, Verse 31', 'गोलाङ्गूलं महावेगं गवाक्षं नाम यूथपम्।
परिवार्याभिवर्तन्ते लङ्कां मर्दितुमोजसा॥', 'golāṅgūlaṃ mahāvegaṃ gavākṣaṃ nāma yūthapam
parivāryābhivartante laṅkāṃ marditum ojasā', null, 6018031),
('ramayana-6-18-32', 32, 'Yuddha Kanda, Sarga 18, Verse 32', 'भ्रमराचरिता यत्र सर्वकामफलद्रुमाः।
यं सूर्यतुल्यवर्णाभमनुपर्येति पर्वतम्॥', 'bhramarācaritā yatra sarvakāmaphaladrumāḥ
yaṃ sūryatulyavarṇābham anuparyeti parvatam', null, 6018032),
('ramayana-6-18-33', 33, 'Yuddha Kanda, Sarga 18, Verse 33', 'यस्य भासा सदा भान्ति तद्वर्णा मृगपक्षिणः।
यस्य प्रस्थं महात्मानो न त्यजन्ति महर्षयः॥', 'yasya bhāsā sadā bhānti tadvarṇā mṛgapakṣiṇaḥ
yasya prasthaṃ mahātmāno na tyajanti maharṣayaḥ', null, 6018033),
('ramayana-6-18-34', 34, 'Yuddha Kanda, Sarga 18, Verse 34', 'तत्रैष रमते राजन्रम्ये काञ्चनपर्वते।
मुख्यो वानरमुख्यानां केसरी नाम यूथपः॥', 'tatraiṣa ramate rājan ramye kāñcanaparvate
mukhyo vānaramukhyānāṃ kesarī nāma yūthapaḥ', null, 6018034),
('ramayana-6-18-35', 35, 'Yuddha Kanda, Sarga 18, Verse 35', 'षष्टिर्गिरिसहस्राणां रम्याः काञ्चनपर्वताः।
तेषां मध्ये गिरिवरस्त्वमिवानघ रक्षसाम्॥', 'ṣaṣṭir girisahasrāṇāṃ ramyāḥ kāñcanaparvatāḥ
teṣāṃ madhye girivaras tvam ivānagha rakṣasām', null, 6018035),
('ramayana-6-18-36', 36, 'Yuddha Kanda, Sarga 18, Verse 36', 'तत्रैते कपिलाः श्वेतास्ताम्रास्या मधुपिङ्गलाः।
निवसन्त्युत्तमगिरौ तीक्ष्णदंष्ट्रानखायुधाः॥', 'tatraite kapilāḥ śvetās tāmrāsyā madhupiṅgalāḥ
nivasanty uttamagirau tīkṣṇadaṃṣṭrānakhāyudhāḥ', null, 6018036),
('ramayana-6-18-37', 37, 'Yuddha Kanda, Sarga 18, Verse 37', 'सिंह इव चतुर्दंष्ट्रा व्याघ्रा इव दुरासदाः।
सर्वे वैश्वनरसमा ज्वलिताशीविषोपमाः॥', 'siṃha iva caturdaṃṣṭrā vyāghrā iva durāsadāḥ
sarve vaiśvanarasamā jvalitāśīviṣopamāḥ', null, 6018037),
('ramayana-6-18-38', 38, 'Yuddha Kanda, Sarga 18, Verse 38', 'सुदीर्घाञ्चितलाङ्गूला मत्तमातंगसंनिभाः।
महापर्वतसंकाशा महाजीमूतनिस्वनाः॥', 'sudīrghāñcitalāṅgūlā mattamātaṃgasaṃnibhāḥ
mahāparvatasaṃkāśā mahājīmūtanisvanāḥ', null, 6018038),
('ramayana-6-18-39', 39, 'Yuddha Kanda, Sarga 18, Verse 39', 'एष चैषामधिपतिर्मध्ये तिष्ठति वीर्यवान्।
नाम्ना पृथिव्यां विख्यातो राजञ्शतबलीति यः।
एषैवाशंसते लङ्कां स्वेनानीकेन मर्दितुम्॥', 'eṣa caiṣām adhipatir madhye tiṣṭhati vīryavān
nāmnā pṛthivyāṃ vikhyāto rājañ śatabalīti yaḥ
eṣaivāśaṃsate laṅkāṃ svenānīkena marditum', null, 6018039),
('ramayana-6-18-40', 40, 'Yuddha Kanda, Sarga 18, Verse 40', 'गजो गवाक्षो गवयो नलो नीलश्च वानरः।
एकैक एव यूथानां कोटिभिर्दशभिर्वृतः॥', 'gajo gavākṣo gavayo nalo nīlaś ca vānaraḥ
ekaika eva yūthānāṃ koṭibhir daśabhir vṛtaḥ', null, 6018040),
('ramayana-6-18-41', 41, 'Yuddha Kanda, Sarga 18, Verse 41', 'तथान्ये वानरश्रेष्ठा विन्ध्यपर्वतवासिनः।
न शक्यन्ते बहुत्वात्तु संख्यातुं लघुविक्रमाः॥', 'tathānye vānaraśreṣṭhā vindhyaparvatavāsinaḥ
na śakyante bahutvāt tu saṃkhyātuṃ laghuvikramāḥ', null, 6018041),
('ramayana-6-18-42', 42, 'Yuddha Kanda, Sarga 18, Verse 42', 'सर्वे महाराज महाप्रभावाः सर्वे महाशैलनिकाशकायाः।
सर्वे समर्थाः पृथिवीं क्षणेन कर्तुं प्रविध्वस्तविकीर्णशैलाम्॥', 'sarve mahārāja mahāprabhāvāḥ sarve mahāśailanikāśakāyāḥ
sarve samarthāḥ pṛthivīṃ kṣaṇena kartuṃ pravidhvastavikīrṇaśailām', null, 6018042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 19 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-19-1', 1, 'Yuddha Kanda, Sarga 19, Verse 1', 'सारणस्य वचः श्रुत्वा रावणं राक्षसाधिपम्।
बलमालोकयन्सर्वं शुको वाक्यमथाब्रवीत्॥', 'sāraṇasya vacaḥ śrutvā rāvaṇaṃ rākṣasādhipam
balam ālokayan sarvaṃ śuko vākyam athābravīt', null, 6019001),
('ramayana-6-19-2', 2, 'Yuddha Kanda, Sarga 19, Verse 2', 'स्थितान्पश्यसि यानेतान्मत्तानिव महाद्विपान्।
न्यग्रोधानिव गाङ्गेयान्सालान्हैमवतीनिव॥', 'sthitān paśyasi yān etān mattān iva mahādvipān
nyagrodhān iva gāṅgeyān sālān haimavatīn iva', null, 6019002),
('ramayana-6-19-3', 3, 'Yuddha Kanda, Sarga 19, Verse 3', 'एते दुष्प्रसहा राजन्बलिनः कामरूपिणः।
दैत्यदानवसंकाशा युद्धे देवपराक्रमाः॥', 'ete duṣprasahā rājan balinaḥ kāmarūpiṇaḥ
daityadānavasaṃkāśā yuddhe devaparākramāḥ', null, 6019003),
('ramayana-6-19-4', 4, 'Yuddha Kanda, Sarga 19, Verse 4', 'एषां कोटिसहस्राणि नव पञ्चच सप्त च।
तथा शङ्खसहस्राणि तथा वृन्दशतानि च॥', 'eṣāṃ koṭisahasrāṇi nava pañcaca sapta ca
tathā śaṅkhasahasrāṇi tathā vṛndaśatāni ca', null, 6019004),
('ramayana-6-19-5', 5, 'Yuddha Kanda, Sarga 19, Verse 5', 'एते सुग्रीवसचिवाः किष्किन्धानिलयाः सदा।
हरयो देवगन्धर्वैरुत्पन्नाः कामरूपिणः॥', 'ete sugrīvasacivāḥ kiṣkindhānilayāḥ sadā
harayo devagandharvair utpannāḥ kāmarūpiṇaḥ', null, 6019005),
('ramayana-6-19-6', 6, 'Yuddha Kanda, Sarga 19, Verse 6', 'यौ तौ पश्यसि तिष्ठन्तौ कुमारौ देवरूपिणौ।
मैन्दश्च द्विविदश्चोभौ ताभ्यां नास्ति समो युधि॥', 'yau tau paśyasi tiṣṭhantau kumārau devarūpiṇau
maindaś ca dvividaś cobhau tābhyāṃ nāsti samo yudhi', null, 6019006),
('ramayana-6-19-7', 7, 'Yuddha Kanda, Sarga 19, Verse 7', 'ब्रह्मणा समनुज्ञातावमृतप्राशिनावुभौ।
आशंसेते युधा लङ्कामेतौ मर्दितुमोजसा॥', 'brahmaṇā samanujñātāv amṛtaprāśināv ubhau
āśaṃsete yudhā laṅkām etau marditum ojasā', null, 6019007),
('ramayana-6-19-8', 8, 'Yuddha Kanda, Sarga 19, Verse 8', 'यावेतावेतयोः पार्श्वे स्थितौ पर्वतसंनिभौ।
सुमुखो विमुखश्चैव मृत्युपुत्रौ पितुः समौ॥', 'yāv etāv etayoḥ pārśve sthitau parvatasaṃnibhau
sumukho vimukhaś caiva mṛtyuputrau pituḥ samau', null, 6019008),
('ramayana-6-19-9', 9, 'Yuddha Kanda, Sarga 19, Verse 9', 'यं तु पश्यसि तिष्ठन्तं प्रभिन्नमिव कुञ्जरम्।
यो बलात्क्षोभयेत्क्रुद्धः समुद्रमपि वानरः॥', 'yaṃ tu paśyasi tiṣṭhantaṃ prabhinnam iva kuñjaram
yo balāt kṣobhayet kruddhaḥ samudram api vānaraḥ', null, 6019009),
('ramayana-6-19-10', 10, 'Yuddha Kanda, Sarga 19, Verse 10', 'एषोऽभिगन्ता लङ्काया वैदेह्यास्तव च प्रभो।
एनं पश्य पुरा दृष्टं वानरं पुनरागतम्॥', 'eṣo ''bhigantā laṅkāyā vaidehyās tava ca prabho
enaṃ paśya purā dṛṣṭaṃ vānaraṃ punar āgatam', null, 6019010),
('ramayana-6-19-11', 11, 'Yuddha Kanda, Sarga 19, Verse 11', 'ज्येष्ठः केसरिणः पुत्रो वातात्मज इति श्रुतः।
हनूमानिति विख्यातो लङ्घितो येन सागरः॥', 'jyeṣṭhaḥ kesariṇaḥ putro vātātmaja iti śrutaḥ
hanūmān iti vikhyāto laṅghito yena sāgaraḥ', null, 6019011),
('ramayana-6-19-12', 12, 'Yuddha Kanda, Sarga 19, Verse 12', 'कामरूपी हरिश्रेष्ठो बलरूपसमन्वितः।
अनिवार्यगतिश्चैव यथा सततगः प्रभुः॥', 'kāmarūpī hariśreṣṭho balarūpasamanvitaḥ
anivāryagatiś caiva yathā satatagaḥ prabhuḥ', null, 6019012),
('ramayana-6-19-13', 13, 'Yuddha Kanda, Sarga 19, Verse 13', 'उद्यन्तं भास्करं दृष्ट्वा बालः किल पिपासितः।
त्रियोजनसहस्रं तु अध्वानमवतीर्य हि॥', 'udyantaṃ bhāskaraṃ dṛṣṭvā bālaḥ kila pipāsitaḥ
triyojanasahasraṃ tu adhvānam avatīrya hi', null, 6019013),
('ramayana-6-19-14', 14, 'Yuddha Kanda, Sarga 19, Verse 14', 'आदित्यमाहरिष्यामि न मे क्षुत्प्रतियास्यति।
इति संचिन्त्य मनसा पुरैष बलदर्पितः॥', 'ādityam āhariṣyāmi na me kṣut pratiyāsyati
iti saṃcintya manasā puraiṣa baladarpitaḥ', null, 6019014),
('ramayana-6-19-15', 15, 'Yuddha Kanda, Sarga 19, Verse 15', 'अनाधृष्यतमं देवमपि देवर्षिदानवैः।
अनासाद्यैव पतितो भास्करोदयने गिरौ॥', 'anādhṛṣyatamaṃ devam api devarṣidānavaiḥ
anāsādyaiva patito bhāskarodayane girau', null, 6019015),
('ramayana-6-19-16', 16, 'Yuddha Kanda, Sarga 19, Verse 16', 'पतितस्य कपेरस्य हनुरेका शिलातले।
किं चिद्भिन्ना दृढहनोर्हनूमानेष तेन वै॥', 'patitasya kaper asya hanur ekā śilātale
kiṃ cid bhinnā dṛḍhahanor hanūmān eṣa tena vai', null, 6019016),
('ramayana-6-19-17', 17, 'Yuddha Kanda, Sarga 19, Verse 17', 'सत्यमागमयोगेन ममैष विदितो हरिः।
नास्य शक्यं बलं रूपं प्रभावो वानुभाषितुम्॥', 'satyam āgamayogena mamaiṣa vidito hariḥ
nāsya śakyaṃ balaṃ rūpaṃ prabhāvo vānubhāṣitum', null, 6019017),
('ramayana-6-19-18', 18, 'Yuddha Kanda, Sarga 19, Verse 18', 'एष आशंसते लङ्कामेको मर्दितुमोजसा।
यश्चैषोऽनन्तरः शूरः श्यामः पद्मनिभेक्षणः॥', 'eṣa āśaṃsate laṅkām eko marditum ojasā
yaś caiṣo ''nantaraḥ śūraḥ śyāmaḥ padmanibhekṣaṇaḥ', null, 6019018),
('ramayana-6-19-19', 19, 'Yuddha Kanda, Sarga 19, Verse 19', 'इक्ष्वाकूणामतिरथो लोके विख्यात पौरुषः।
यस्मिन्न चलते धर्मो यो धर्मं नातिवर्तते॥', 'ikṣvākūṇām atiratho loke vikhyāta pauruṣaḥ
yasmin na calate dharmo yo dharmaṃ nātivartate', null, 6019019),
('ramayana-6-19-20', 20, 'Yuddha Kanda, Sarga 19, Verse 20', 'यो ब्राह्ममस्त्रं वेदांश्च वेद वेदविदां वरः।
यो भिन्द्याद्गगनं बाणैः पर्वतांश्चापि दारयेत्॥', 'yo brāhmam astraṃ vedāṃś ca veda vedavidāṃ varaḥ
yo bhindyād gaganaṃ bāṇaiḥ parvatāṃś cāpi dārayet', null, 6019020),
('ramayana-6-19-21', 21, 'Yuddha Kanda, Sarga 19, Verse 21', 'यस्य मृत्योरिव क्रोधः शक्रस्येव पराक्रमः।
स एष रामस्त्वां योद्धुं राजन्समभिवर्तते॥', 'yasya mṛtyor iva krodhaḥ śakrasyeva parākramaḥ
sa eṣa rāmas tvāṃ yoddhuṃ rājan samabhivartate', null, 6019021),
('ramayana-6-19-22', 22, 'Yuddha Kanda, Sarga 19, Verse 22', 'यश्चैष दक्षिणे पार्श्वे शुद्धजाम्बूनदप्रभः।
विशालवक्षास्ताम्राक्षो नीलकुञ्चितमूर्धजः॥', 'yaś caiṣa dakṣiṇe pārśve śuddhajāmbūnadaprabhaḥ
viśālavakṣās tāmrākṣo nīlakuñcitamūrdhajaḥ', null, 6019022),
('ramayana-6-19-23', 23, 'Yuddha Kanda, Sarga 19, Verse 23', 'एषोऽस्य लक्ष्मणो नाम भ्राता प्राणसमः प्रियः।
नये युद्धे च कुशलः सर्वशास्त्रविशारदः॥', 'eṣo ''sya lakṣmaṇo nāma bhrātā prāṇasamaḥ priyaḥ
naye yuddhe ca kuśalaḥ sarvaśāstraviśāradaḥ', null, 6019023),
('ramayana-6-19-24', 24, 'Yuddha Kanda, Sarga 19, Verse 24', 'अमर्षी दुर्जयो जेता विक्रान्तो बुद्धिमान्बली।
रामस्य दक्षिणो बाहुर्नित्यं प्राणो बहिश्चरः॥', 'amarṣī durjayo jetā vikrānto buddhimān balī
rāmasya dakṣiṇo bāhur nityaṃ prāṇo bahiścaraḥ', null, 6019024),
('ramayana-6-19-25', 25, 'Yuddha Kanda, Sarga 19, Verse 25', 'न ह्येष राघवस्यार्थे जीवितं परिरक्षति।
एषैवाशंसते युद्धे निहन्तुं सर्वराक्षसान्॥', 'na hy eṣa rāghavasyārthe jīvitaṃ parirakṣati
eṣaivāśaṃsate yuddhe nihantuṃ sarvarākṣasān', null, 6019025),
('ramayana-6-19-26', 26, 'Yuddha Kanda, Sarga 19, Verse 26', 'यस्तु सव्यमसौ पक्षं रामस्याश्रित्य तिष्ठति।
रक्षोगणपरिक्षिप्तो राजा ह्येष विभीषणः॥', 'yas tu savyam asau pakṣaṃ rāmasyāśritya tiṣṭhati
rakṣogaṇaparikṣipto rājā hy eṣa vibhīṣaṇaḥ', null, 6019026),
('ramayana-6-19-27', 27, 'Yuddha Kanda, Sarga 19, Verse 27', 'श्रीमता राजराजेन लङ्कायामभिषेचितः।
त्वामेव प्रतिसंरब्धो युद्धायैषोऽभिवर्तते॥', 'śrīmatā rājarājena laṅkāyām abhiṣecitaḥ
tvām eva pratisaṃrabdho yuddhāyaiṣo ''bhivartate', null, 6019027),
('ramayana-6-19-28', 28, 'Yuddha Kanda, Sarga 19, Verse 28', 'यं तु पश्यसि तिष्ठन्तं मध्ये गिरिमिवाचलम्।
सर्वशाखामृगेन्द्राणां भर्तारमपराजितम्॥', 'yaṃ tu paśyasi tiṣṭhantaṃ madhye girim ivācalam
sarvaśākhāmṛgendrāṇāṃ bhartāram aparājitam', null, 6019028),
('ramayana-6-19-29', 29, 'Yuddha Kanda, Sarga 19, Verse 29', 'तेजसा यशसा बुद्ध्या ज्ञानेनाभिजनेन च।
यः कपीनति बभ्राज हिमवानिव पर्वतान्॥', 'tejasā yaśasā buddhyā jñānenābhijanena ca
yaḥ kapīn ati babhrāja himavān iva parvatān', null, 6019029),
('ramayana-6-19-30', 30, 'Yuddha Kanda, Sarga 19, Verse 30', 'किष्किन्धां यः समध्यास्ते गुहां सगहनद्रुमाम्।
दुर्गां पर्वतदुर्गस्थां प्रधानैः सह यूथपैः॥', 'kiṣkindhāṃ yaḥ samadhyāste guhāṃ sagahanadrumām
durgāṃ parvatadurgasthāṃ pradhānaiḥ saha yūthapaiḥ', null, 6019030),
('ramayana-6-19-31', 31, 'Yuddha Kanda, Sarga 19, Verse 31', 'यस्यैषा काञ्चनी माला शोभते शतपुष्करा।
कान्ता देवमनुष्याणां यस्यां लक्ष्मीः प्रतिष्ठिता॥', 'yasyaiṣā kāñcanī mālā śobhate śatapuṣkarā
kāntā devamanuṣyāṇāṃ yasyāṃ lakṣmīḥ pratiṣṭhitā', null, 6019031),
('ramayana-6-19-32', 32, 'Yuddha Kanda, Sarga 19, Verse 32', 'एतां च मालां तारां च कपिराज्यं च शाश्वतम्।
सुग्रीवो वालिनं हत्वा रामेण प्रतिपादितः॥', 'etāṃ ca mālāṃ tārāṃ ca kapirājyaṃ ca śāśvatam
sugrīvo vālinaṃ hatvā rāmeṇa pratipāditaḥ', null, 6019032),
('ramayana-6-19-33', 33, 'Yuddha Kanda, Sarga 19, Verse 33', 'एवं कोटिसहस्रेण शङ्कूनां च शतेन च।
सुग्रीवो वानरेन्द्रस्त्वां युद्धार्थमभिवर्तते॥', 'evaṃ koṭisahasreṇa śaṅkūnāṃ ca śatena ca
sugrīvo vānarendras tvāṃ yuddhārtham abhivartate', null, 6019033),
('ramayana-6-19-34', 34, 'Yuddha Kanda, Sarga 19, Verse 34', 'इमां महाराजसमीक्ष्य वाहिनीमुपस्थितां प्रज्वलितग्रहोपमाम्।
ततः प्रयत्नः परमो विधीयतां यथा जयः स्यान्न परैः पराजयः॥', 'imāṃ mahārājasamīkṣya vāhinīm upasthitāṃ prajvalitagrahopamām
tataḥ prayatnaḥ paramo vidhīyatāṃ yathā jayaḥ syān na paraiḥ parājayaḥ', null, 6019034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 20 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-20-1', 1, 'Yuddha Kanda, Sarga 20, Verse 1', 'शुकेन तु समाख्यातांस्तान्दृष्ट्वा हरियूथपान्।
समीपस्थं च रामस्य भ्रातरं स्वं विभीषणम्॥', 'śukena tu samākhyātāṃs tān dṛṣṭvā hariyūthapān
samīpasthaṃ ca rāmasya bhrātaraṃ svaṃ vibhīṣaṇam', null, 6020001),
('ramayana-6-20-2', 2, 'Yuddha Kanda, Sarga 20, Verse 2', 'लक्ष्मणं च महावीर्यं भुजं रामस्य दक्षिणम्।
सर्ववानरराजं च सुग्रीवं भीमविक्रमम्॥', 'lakṣmaṇaṃ ca mahāvīryaṃ bhujaṃ rāmasya dakṣiṇam
sarvavānararājaṃ ca sugrīvaṃ bhīmavikramam', null, 6020002),
('ramayana-6-20-3', 3, 'Yuddha Kanda, Sarga 20, Verse 3', 'किं चिदाविग्नहृदयो जातक्रोधश्च रावणः।
भर्त्सयामास तौ वीरौ कथान्ते शुकसारणौ॥', 'kiṃ cid āvignahṛdayo jātakrodhaś ca rāvaṇaḥ
bhartsayām āsa tau vīrau kathānte śukasāraṇau', null, 6020003),
('ramayana-6-20-4', 4, 'Yuddha Kanda, Sarga 20, Verse 4', 'अधोमुखौ तौ प्रणतावब्रवीच्छुकसारणौ।
रोषगद्गदया वाचा संरब्धः परुषं वचः॥', 'adhomukhau tau praṇatāv abravīc chukasāraṇau
roṣagadgadayā vācā saṃrabdhaḥ paruṣaṃ vacaḥ', null, 6020004),
('ramayana-6-20-5', 5, 'Yuddha Kanda, Sarga 20, Verse 5', 'न तावत्सदृशं नाम सचिवैरुपजीविभिः।
विप्रियं नृपतेर्वक्तुं निग्रहप्रग्रहे विभोः॥', 'na tāvat sadṛśaṃ nāma sacivair upajīvibhiḥ
vipriyaṃ nṛpater vaktuṃ nigrahapragrahe vibhoḥ', null, 6020005),
('ramayana-6-20-6', 6, 'Yuddha Kanda, Sarga 20, Verse 6', 'रिपूणां प्रतिकूलानां युद्धार्थमभिवर्तताम्।
उभाभ्यां सदृशं नाम वक्तुमप्रस्तवे स्तवम्॥', 'ripūṇāṃ pratikūlānāṃ yuddhārtham abhivartatām
ubhābhyāṃ sadṛśaṃ nāma vaktum aprastave stavam', null, 6020006),
('ramayana-6-20-7', 7, 'Yuddha Kanda, Sarga 20, Verse 7', 'आचार्या गुरवो वृद्धा वृथा वां पर्युपासिताः।
सारं यद्राजशास्त्राणामनुजीव्यं न गृह्यते॥', 'ācāryā guravo vṛddhā vṛthā vāṃ paryupāsitāḥ
sāraṃ yad rājaśāstrāṇām anujīvyaṃ na gṛhyate', null, 6020007),
('ramayana-6-20-8', 8, 'Yuddha Kanda, Sarga 20, Verse 8', 'गृहीतो वा न विज्ञातो भारो ज्ञानस्य वोछ्यते।
ईदृशैः सचिवैर्युक्तो मूर्खैर्दिष्ट्या धराम्यहम्॥', 'gṛhīto vā na vijñāto bhāro jñānasya vochyate
īdṛśaiḥ sacivair yukto mūrkhair diṣṭyā dharāmy aham', null, 6020008),
('ramayana-6-20-9', 9, 'Yuddha Kanda, Sarga 20, Verse 9', 'किं नु मृत्योर्भयं नास्ति मां वक्तुं परुषं वचः।
यस्य मे शासतो जिह्वा प्रयच्छति शुभाशुभम्॥', 'kiṃ nu mṛtyor bhayaṃ nāsti māṃ vaktuṃ paruṣaṃ vacaḥ
yasya me śāsato jihvā prayacchati śubhāśubham', null, 6020009),
('ramayana-6-20-10', 10, 'Yuddha Kanda, Sarga 20, Verse 10', 'अप्येव दहनं स्पृष्ट्वा वने तिष्ठन्ति पादपाः।
राजदोषपरामृष्टास्तिष्ठन्ते नापराधिनः॥', 'apy eva dahanaṃ spṛṣṭvā vane tiṣṭhanti pādapāḥ
rājadoṣaparāmṛṣṭās tiṣṭhante nāparādhinaḥ', null, 6020010),
('ramayana-6-20-11', 11, 'Yuddha Kanda, Sarga 20, Verse 11', 'हन्यामहमिमौ पापौ शत्रुपक्षप्रशंसकौ।
यदि पूर्वोपकारैर्मे न क्रोधो मृदुतां व्रजेत्॥', 'hanyām aham imau pāpau śatrupakṣapraśaṃsakau
yadi pūrvopakārair me na krodho mṛdutāṃ vrajet', null, 6020011),
('ramayana-6-20-12', 12, 'Yuddha Kanda, Sarga 20, Verse 12', 'अपध्वंसत गच्छध्वं संनिकर्षादितो मम।
न हि वां हन्तुमिच्छामि स्मरन्नुपकृतानि वाम्।
हतावेव कृतघ्नौ तौ मयि स्नेहपराङ्मुखौ॥', 'apadhvaṃsata gacchadhvaṃ saṃnikarṣād ito mama
na hi vāṃ hantum icchāmi smarann upakṛtāni vām
hatāv eva kṛtaghnau tau mayi snehaparāṅmukhau', null, 6020012),
('ramayana-6-20-13', 13, 'Yuddha Kanda, Sarga 20, Verse 13', 'एवमुक्तौ तु सव्रीडौ तावुभौ शुकसारणौ।
रावणं जयशब्देन प्रतिनन्द्याभिनिःसृतौ॥', 'evam uktau tu savrīḍau tāv ubhau śukasāraṇau
rāvaṇaṃ jayaśabdena pratinandyābhiniḥsṛtau', null, 6020013),
('ramayana-6-20-14', 14, 'Yuddha Kanda, Sarga 20, Verse 14', 'अब्रवीत्स दशग्रीवः समीपस्थं महोदरम्।
उपस्थापय शीघ्रं मे चारान्नीतिविशारदान्॥', 'abravīt sa daśagrīvaḥ samīpasthaṃ mahodaram
upasthāpaya śīghraṃ me cārān nītiviśāradān', null, 6020014),
('ramayana-6-20-15', 15, 'Yuddha Kanda, Sarga 20, Verse 15', 'ततश्चराः संत्वरिताः प्राप्ताः पार्थिवशासनात्।
उपस्थिताः प्राञ्जलयो वर्धयित्वा जयाशिषा॥', 'tataś carāḥ saṃtvaritāḥ prāptāḥ pārthivaśāsanāt
upasthitāḥ prāñjalayo vardhayitvā jayāśiṣā', null, 6020015),
('ramayana-6-20-16', 16, 'Yuddha Kanda, Sarga 20, Verse 16', 'तानब्रवीत्ततो वाक्यं रावणो राक्षसाधिपः।
चारान्प्रत्ययिकाञ्शूरान्भक्तान्विगतसाध्वसान्॥', 'tān abravīt tato vākyaṃ rāvaṇo rākṣasādhipaḥ
cārān pratyayikāñ śūrān bhaktān vigatasādhvasān', null, 6020016),
('ramayana-6-20-17', 17, 'Yuddha Kanda, Sarga 20, Verse 17', 'इतो गच्छत रामस्य व्यवसायं परीक्षथ।
मन्त्रेष्वभ्यन्तरा येऽस्य प्रीत्या तेन समागताः॥', 'ito gacchata rāmasya vyavasāyaṃ parīkṣatha
mantreṣv abhyantarā ye ''sya prītyā tena samāgatāḥ', null, 6020017),
('ramayana-6-20-18', 18, 'Yuddha Kanda, Sarga 20, Verse 18', 'कथं स्वपिति जागर्ति किमन्यच्च करिष्यति।
विज्ञाय निपुणं सर्वमागन्तव्यमशेषतः॥', 'kathaṃ svapiti jāgarti kim anyac ca kariṣyati
vijñāya nipuṇaṃ sarvam āgantavyam aśeṣataḥ', null, 6020018),
('ramayana-6-20-19', 19, 'Yuddha Kanda, Sarga 20, Verse 19', 'चारेण विदितः शत्रुः पण्डितैर्वसुधाधिपैः।
युद्धे स्वल्पेन यत्नेन समासाद्य निरस्यते॥', 'cāreṇa viditaḥ śatruḥ paṇḍitair vasudhādhipaiḥ
yuddhe svalpena yatnena samāsādya nirasyate', null, 6020019),
('ramayana-6-20-20', 20, 'Yuddha Kanda, Sarga 20, Verse 20', 'चारास्तु ते तथेत्युक्त्वा प्रहृष्टा राक्षसेश्वरम्।
कृत्वा प्रदक्षिणं जग्मुर्यत्र रामः सलक्ष्मणः॥', 'cārās tu te tathety uktvā prahṛṣṭā rākṣaseśvaram
kṛtvā pradakṣiṇaṃ jagmur yatra rāmaḥ salakṣmaṇaḥ', null, 6020020),
('ramayana-6-20-21', 21, 'Yuddha Kanda, Sarga 20, Verse 21', 'ते सुवेलस्य शैलस्य समीपे रामलक्ष्मणौ।
प्रच्छन्ना ददृशुर्गत्वा ससुग्रीवविभीषणौ॥', 'te suvelasya śailasya samīpe rāmalakṣmaṇau
pracchannā dadṛśur gatvā sasugrīvavibhīṣaṇau', null, 6020021),
('ramayana-6-20-22', 22, 'Yuddha Kanda, Sarga 20, Verse 22', 'ते तु धर्मात्मना दृष्टा राक्षसेन्द्रेण राक्षसाः।
विभीषणेन तत्रस्था निगृहीता यदृच्छया॥', 'te tu dharmātmanā dṛṣṭā rākṣasendreṇa rākṣasāḥ
vibhīṣaṇena tatrasthā nigṛhītā yadṛcchayā', null, 6020022),
('ramayana-6-20-23', 23, 'Yuddha Kanda, Sarga 20, Verse 23', 'वानरैरर्दितास्ते तु विक्रान्तैर्लघुविक्रमैः।
पुनर्लङ्कामनुप्राप्ताः श्वसन्तो नष्टचेतसः॥', 'vānarair arditās te tu vikrāntair laghuvikramaiḥ
punar laṅkām anuprāptāḥ śvasanto naṣṭacetasaḥ', null, 6020023),
('ramayana-6-20-24', 24, 'Yuddha Kanda, Sarga 20, Verse 24', 'ततो दशग्रीवमुपस्थितास्ते चारा बहिर्नित्यचरा निशाचराः।
गिरेः सुवेलस्य समीपवासिनं न्यवेदयन्भीमबलं महाबलाः॥', 'tato daśagrīvam upasthitās te cārā bahirnityacarā niśācarāḥ
gireḥ suvelasya samīpavāsinaṃ nyavedayan bhīmabalaṃ mahābalāḥ', null, 6020024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 21 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-21-1', 1, 'Yuddha Kanda, Sarga 21, Verse 1', 'ततस्तमक्षोभ्य बलं लङ्काधिपतये चराः।
सुवेले राघवं शैले निविष्टं प्रत्यवेदयन्॥', 'tatas tam akṣobhya balaṃ laṅkādhipataye carāḥ
suvele rāghavaṃ śaile niviṣṭaṃ pratyavedayan', null, 6021001),
('ramayana-6-21-2', 2, 'Yuddha Kanda, Sarga 21, Verse 2', 'चाराणां रावणः श्रुत्वा प्राप्तं रामं महाबलम्।
जातोद्वेगोऽभवत्किं चिच्छार्दूलं वाक्यमब्रवीत्॥', 'cārāṇāṃ rāvaṇaḥ śrutvā prāptaṃ rāmaṃ mahābalam
jātodvego ''bhavat kiṃ cic chārdūlaṃ vākyam abravīt', null, 6021002),
('ramayana-6-21-3', 3, 'Yuddha Kanda, Sarga 21, Verse 3', 'अयथावच्च ते वर्णो दीनश्चासि निशाचर।
नासि कच्चिदमित्राणां क्रुद्धानां वशमागतः॥', 'ayathāvac ca te varṇo dīnaś cāsi niśācara
nāsi kaccid amitrāṇāṃ kruddhānāṃ vaśam āgataḥ', null, 6021003),
('ramayana-6-21-4', 4, 'Yuddha Kanda, Sarga 21, Verse 4', 'इति तेनानुशिष्टस्तु वाचं मन्दमुदीरयत्।
तदा राक्षसशार्दूलं शार्दूलो भयविह्वलः॥', 'iti tenānuśiṣṭas tu vācaṃ mandam udīrayat
tadā rākṣasaśārdūlaṃ śārdūlo bhayavihvalaḥ', null, 6021004),
('ramayana-6-21-5', 5, 'Yuddha Kanda, Sarga 21, Verse 5', 'न ते चारयितुं शक्या राजन्वानरपुंगवाः।
विक्रान्ता बलवन्तश्च राघवेण च रक्षिताः॥', 'na te cārayituṃ śakyā rājan vānarapuṃgavāḥ
vikrāntā balavantaś ca rāghaveṇa ca rakṣitāḥ', null, 6021005),
('ramayana-6-21-6', 6, 'Yuddha Kanda, Sarga 21, Verse 6', 'नापि संभाषितुं शक्याः संप्रश्नोऽत्र न लभ्यते।
सर्वतो रक्ष्यते पन्था वानरैः पर्वतोपमैः॥', 'nāpi saṃbhāṣituṃ śakyāḥ saṃpraśno ''tra na labhyate
sarvato rakṣyate panthā vānaraiḥ parvatopamaiḥ', null, 6021006),
('ramayana-6-21-7', 7, 'Yuddha Kanda, Sarga 21, Verse 7', 'प्रविष्टमात्रे ज्ञातोऽहं बले तस्मिन्नचारिते।
बलाद्गृहीतो बहुभिर्बहुधास्मि विदारितः॥', 'praviṣṭamātre jñāto ''haṃ bale tasminn acārite
balād gṛhīto bahubhir bahudhāsmi vidāritaḥ', null, 6021007),
('ramayana-6-21-8', 8, 'Yuddha Kanda, Sarga 21, Verse 8', 'जानुभिर्मुष्टिभिर्दन्तैस्तलैश्चाभिहतो भृशम्।
परिणीतोऽस्मि हरिभिर्बलवद्भिरमर्षणैः॥', 'jānubhir muṣṭibhir dantais talaiś cābhihato bhṛśam
pariṇīto ''smi haribhir balavadbhir amarṣaṇaiḥ', null, 6021008),
('ramayana-6-21-9', 9, 'Yuddha Kanda, Sarga 21, Verse 9', 'परिणीय च सर्वत्र नीतोऽहं रामसंसदम्।
रुधिरादिग्धसर्वाङ्गो विह्वलश्चलितेन्द्रियः॥', 'pariṇīya ca sarvatra nīto ''haṃ rāmasaṃsadam
rudhirādigdhasarvāṅgo vihvalaś calitendriyaḥ', null, 6021009),
('ramayana-6-21-10', 10, 'Yuddha Kanda, Sarga 21, Verse 10', 'हरिभिर्वध्यमानश्च याचमानः कृताञ्जलिः।
राघवेण परित्रातो जीवामि ह यदृच्छया॥', 'haribhir vadhyamānaś ca yācamānaḥ kṛtāñjaliḥ
rāghaveṇa paritrāto jīvāmi ha yadṛcchayā', null, 6021010),
('ramayana-6-21-11', 11, 'Yuddha Kanda, Sarga 21, Verse 11', 'एष शैलैः शिलाभिश्च पूरयित्वा महार्णवम्।
द्वारमाश्रित्य लङ्काया रामस्तिष्ठति सायुधः॥', 'eṣa śailaiḥ śilābhiś ca pūrayitvā mahārṇavam
dvāram āśritya laṅkāyā rāmas tiṣṭhati sāyudhaḥ', null, 6021011),
('ramayana-6-21-12', 12, 'Yuddha Kanda, Sarga 21, Verse 12', 'गरुडव्यूहमास्थाय सर्वतो हरिभिर्वृतः।
मां विसृज्य महातेजा लङ्कामेवाभिवर्तते॥', 'garuḍavyūham āsthāya sarvato haribhir vṛtaḥ
māṃ visṛjya mahātejā laṅkām evābhivartate', null, 6021012),
('ramayana-6-21-13', 13, 'Yuddha Kanda, Sarga 21, Verse 13', 'पुरा प्राकारमायाति क्षिप्रमेकतरं कुरु।
सीतां चास्मै प्रयच्छाशु सुयुद्धं वा प्रदीयताम्॥', 'purā prākāram āyāti kṣipram ekataraṃ kuru
sītāṃ cāsmai prayacchāśu suyuddhaṃ vā pradīyatām', null, 6021013),
('ramayana-6-21-14', 14, 'Yuddha Kanda, Sarga 21, Verse 14', 'मनसा संततापाथ तच्छ्रुत्वा राक्षसाधिपः।
शार्दूलस्य महद्वाक्यमथोवाच स रावणः॥', 'manasā saṃtatāpātha tac chrutvā rākṣasādhipaḥ
śārdūlasya mahad vākyam athovāca sa rāvaṇaḥ', null, 6021014),
('ramayana-6-21-15', 15, 'Yuddha Kanda, Sarga 21, Verse 15', 'यदि मां प्रतियुध्येरन्देवगन्धर्वदानवाः।
नैव सीतां प्रदास्यामि सर्वलोकभयादपि॥', 'yadi māṃ pratiyudhyeran devagandharvadānavāḥ
naiva sītāṃ pradāsyāmi sarvalokabhayād api', null, 6021015),
('ramayana-6-21-16', 16, 'Yuddha Kanda, Sarga 21, Verse 16', 'एवमुक्त्वा महातेजा रावणः पुनरब्रवीत्।
चारिता भवता सेना केऽत्र शूराः प्लवंगमाः॥', 'evam uktvā mahātejā rāvaṇaḥ punar abravīt
cāritā bhavatā senā ke ''tra śūrāḥ plavaṃgamāḥ', null, 6021016),
('ramayana-6-21-17', 17, 'Yuddha Kanda, Sarga 21, Verse 17', 'कीदृशाः किंप्रभावाश्च वानरा ये दुरासदाः।
कस्य पुत्राश्च पौत्राश्च तत्त्वमाख्याहि राक्षस॥', 'kīdṛśāḥ kiṃprabhāvāś ca vānarā ye durāsadāḥ
kasya putrāś ca pautrāś ca tattvam ākhyāhi rākṣasa', null, 6021017),
('ramayana-6-21-18', 18, 'Yuddha Kanda, Sarga 21, Verse 18', 'तत्रत्र प्रतिपत्स्यामि ज्ञात्वा तेषां बलाबलम्।
अवश्यं बलसंख्यानं कर्तव्यं युद्धमिच्छता॥', 'tatr atra pratipatsyāmi jñātvā teṣāṃ balābalam
avaśyaṃ balasaṃkhyānaṃ kartavyaṃ yuddham icchatā', null, 6021018),
('ramayana-6-21-19', 19, 'Yuddha Kanda, Sarga 21, Verse 19', 'अथैवमुक्तः शार्दूलो रावणेनोत्तमश्चरः।
इदं वचनमारेभे वक्तुं रावणसंनिधौ॥', 'athaivam uktaḥ śārdūlo rāvaṇenottamaś caraḥ
idaṃ vacanam ārebhe vaktuṃ rāvaṇasaṃnidhau', null, 6021019),
('ramayana-6-21-20', 20, 'Yuddha Kanda, Sarga 21, Verse 20', 'अथर्क्षरजसः पुत्रो युधि राजन्सुदुर्जयः।
गद्गदस्याथ पुत्रोऽत्र जाम्बवानिति विश्रुतः॥', 'atharkṣarajasaḥ putro yudhi rājan sudurjayaḥ
gadgadasyātha putro ''tra jāmbavān iti viśrutaḥ', null, 6021020),
('ramayana-6-21-21', 21, 'Yuddha Kanda, Sarga 21, Verse 21', 'गद्गदस्यैव पुत्रोऽन्यो गुरुपुत्रः शतक्रतोः।
कदनं यस्य पुत्रेण कृतमेकेन रक्षसाम्॥', 'gadgadasyaiva putro ''nyo guruputraḥ śatakratoḥ
kadanaṃ yasya putreṇa kṛtam ekena rakṣasām', null, 6021021),
('ramayana-6-21-22', 22, 'Yuddha Kanda, Sarga 21, Verse 22', 'सुषेणश्चापि धर्मात्मा पुत्रो धर्मस्य वीर्यवान्।
सौम्यः सोमात्मजश्चात्र राजन्दधिमुखः कपिः॥', 'suṣeṇaś cāpi dharmātmā putro dharmasya vīryavān
saumyaḥ somātmajaś cātra rājan dadhimukhaḥ kapiḥ', null, 6021022),
('ramayana-6-21-23', 23, 'Yuddha Kanda, Sarga 21, Verse 23', 'सुमुखो दुर्मुखश्चात्र वेगदर्शी च वानरः।
मृत्युर्वानररूपेण नूनं सृष्टः स्वयम्भुवा॥', 'sumukho durmukhaś cātra vegadarśī ca vānaraḥ
mṛtyur vānararūpeṇa nūnaṃ sṛṣṭaḥ svayambhuvā', null, 6021023),
('ramayana-6-21-24', 24, 'Yuddha Kanda, Sarga 21, Verse 24', 'पुत्रो हुतवहस्याथ नीलः सेनापतिः स्वयम्।
अनिलस्य च पुत्रोऽत्र हनूमानिति विश्रुतः॥', 'putro hutavahasyātha nīlaḥ senāpatiḥ svayam
anilasya ca putro ''tra hanūmān iti viśrutaḥ', null, 6021024),
('ramayana-6-21-25', 25, 'Yuddha Kanda, Sarga 21, Verse 25', 'नप्ता शक्रस्य दुर्धर्षो बलवानङ्गदो युवा।
मैन्दश्च द्विविदश्चोभौ बलिनावश्विसंभवौ॥', 'naptā śakrasya durdharṣo balavān aṅgado yuvā
maindaś ca dvividaś cobhau balināv aśvisaṃbhavau', null, 6021025),
('ramayana-6-21-26', 26, 'Yuddha Kanda, Sarga 21, Verse 26', 'पुत्रा वैवस्वतस्यात्र पञ्चकालान्तकोपमाः।
गजो गवाक्षो गवयः शरभो गन्धमादनः॥', 'putrā vaivasvatasyātra pañcakālāntakopamāḥ
gajo gavākṣo gavayaḥ śarabho gandhamādanaḥ', null, 6021026),
('ramayana-6-21-27', 27, 'Yuddha Kanda, Sarga 21, Verse 27', 'श्वेतो ज्योतिर्मुखश्चात्र भास्करस्यात्मसंभवौ।
वरुणस्य च पुत्रोऽथ हेमकूटः प्लवंगमः॥', 'śveto jyotirmukhaś cātra bhāskarasyātmasaṃbhavau
varuṇasya ca putro ''tha hemakūṭaḥ plavaṃgamaḥ', null, 6021027),
('ramayana-6-21-28', 28, 'Yuddha Kanda, Sarga 21, Verse 28', 'विश्वकर्मसुतो वीरो नलः प्लवगसत्तमः।
विक्रान्तो वेगवानत्र वसुपुत्रः सुदुर्धरः॥', 'viśvakarmasuto vīro nalaḥ plavagasattamaḥ
vikrānto vegavān atra vasuputraḥ sudurdharaḥ', null, 6021028),
('ramayana-6-21-29', 29, 'Yuddha Kanda, Sarga 21, Verse 29', 'दशवानरकोट्यश्च शूराणां युद्धकाङ्क्षिणाम्।
श्रीमतां देवपुत्राणां शेषान्नाख्यातुमुत्सहे॥', 'daśavānarakoṭyaś ca śūrāṇāṃ yuddhakāṅkṣiṇām
śrīmatāṃ devaputrāṇāṃ śeṣān nākhyātum utsahe', null, 6021029),
('ramayana-6-21-30', 30, 'Yuddha Kanda, Sarga 21, Verse 30', 'पुत्रो दशरथस्यैष सिंहसंहननो युवा।
दूषणो निहतो येन खरश्च त्रिशिरास्तथा॥', 'putro daśarathasyaiṣa siṃhasaṃhanano yuvā
dūṣaṇo nihato yena kharaś ca triśirās tathā', null, 6021030),
('ramayana-6-21-31', 31, 'Yuddha Kanda, Sarga 21, Verse 31', 'नास्ति रामस्य सदृशो विक्रमे भुवि कश्चन।
विराधो निहतो येन कबन्धश्चान्तकोपमः॥', 'nāsti rāmasya sadṛśo vikrame bhuvi kaś cana
virādho nihato yena kabandhaś cāntakopamaḥ', null, 6021031),
('ramayana-6-21-32', 32, 'Yuddha Kanda, Sarga 21, Verse 32', 'वक्तुं न शक्तो रामस्य नरः कश्चिद्गुणान्क्षितौ।
जनस्थानगता येन तावन्तो राक्षसा हताः॥', 'vaktuṃ na śakto rāmasya naraḥ kaś cid guṇān kṣitau
janasthānagatā yena tāvanto rākṣasā hatāḥ', null, 6021032),
('ramayana-6-21-33', 33, 'Yuddha Kanda, Sarga 21, Verse 33', 'लक्ष्मणश्चात्र धर्मात्मा मातंगानामिवर्षभः।
यस्य बाणपथं प्राप्य न जीवेदपि वासवः॥', 'lakṣmaṇaś cātra dharmātmā mātaṃgānām ivarṣabhaḥ
yasya bāṇapathaṃ prāpya na jīved api vāsavaḥ', null, 6021033),
('ramayana-6-21-34', 34, 'Yuddha Kanda, Sarga 21, Verse 34', 'राक्षसानां वरिष्ठश्च तव भ्राता विभीषणः।
परिगृह्य पुरीं लङ्कां राघवस्य हिते रतः॥', 'rākṣasānāṃ variṣṭhaś ca tava bhrātā vibhīṣaṇaḥ
parigṛhya purīṃ laṅkāṃ rāghavasya hite rataḥ', null, 6021034),
('ramayana-6-21-35', 35, 'Yuddha Kanda, Sarga 21, Verse 35', 'इति सर्वं समाख्यातं तवेदं वानरं बलम्।
सुवेलेऽधिष्ठितं शैले शेषकार्ये भवान्गतिः॥', 'iti sarvaṃ samākhyātaṃ tavedaṃ vānaraṃ balam
suvele ''dhiṣṭhitaṃ śaile śeṣakārye bhavān gatiḥ', null, 6021035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 22 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-22-1', 1, 'Yuddha Kanda, Sarga 22, Verse 1', 'ततस्तमक्षोभ्यबलं लङ्कायां नृपतेश्चरः।
सुवेले राघवं शैले निविष्टं प्रत्यवेदयन्॥', 'tatas tam akṣobhyabalaṃ laṅkāyāṃ nṛpateś caraḥ
suvele rāghavaṃ śaile niviṣṭaṃ pratyavedayan', null, 6022001),
('ramayana-6-22-2', 2, 'Yuddha Kanda, Sarga 22, Verse 2', 'चाराणां रावणः श्रुत्वा प्राप्तं रामं महाबलम्।
जातोद्वेगोऽभवत्किं चित्सचिवांश्चेदमब्रवीत्॥', 'cārāṇāṃ rāvaṇaḥ śrutvā prāptaṃ rāmaṃ mahābalam
jātodvego ''bhavat kiṃ cit sacivāṃś cedam abravīt', null, 6022002),
('ramayana-6-22-3', 3, 'Yuddha Kanda, Sarga 22, Verse 3', 'मन्त्रिणः शीघ्रमायान्तु सर्वे वै सुसमाहिताः।
अयं नो मन्त्रकालो हि संप्राप्त इव राक्षसाः॥', 'mantriṇaḥ śīghram āyāntu sarve vai susamāhitāḥ
ayaṃ no mantrakālo hi saṃprāpta iva rākṣasāḥ', null, 6022003),
('ramayana-6-22-4', 4, 'Yuddha Kanda, Sarga 22, Verse 4', 'तस्य तच्छासनं श्रुत्वा मन्त्रिणोऽभ्यागमन्द्रुतम्।
ततः संमन्त्रयामास सचिवै राक्षसैः सह॥', 'tasya tac chāsanaṃ śrutvā mantriṇo ''bhyāgaman drutam
tataḥ saṃmantrayām āsa sacivai rākṣasaiḥ saha', null, 6022004),
('ramayana-6-22-5', 5, 'Yuddha Kanda, Sarga 22, Verse 5', 'मन्त्रयित्वा स दुर्धर्षः क्षमं यत्समनन्तरम्।
विसर्जयित्वा सचिवान्प्रविवेश स्वमालयम्॥', 'mantrayitvā sa durdharṣaḥ kṣamaṃ yat samanantaram
visarjayitvā sacivān praviveśa svam ālayam', null, 6022005),
('ramayana-6-22-6', 6, 'Yuddha Kanda, Sarga 22, Verse 6', 'ततो राक्षसमाहूय विद्युज्जिह्वं महाबलम्।
मायाविदं महामायः प्राविशद्यत्र मैथिली॥', 'tato rākṣasam āhūya vidyujjihvaṃ mahābalam
māyāvidaṃ mahāmāyaḥ prāviśad yatra maithilī', null, 6022006),
('ramayana-6-22-7', 7, 'Yuddha Kanda, Sarga 22, Verse 7', 'विद्युज्जिह्वं च मायाज्ञमब्रवीद्राक्षसाधिपः।
मोहयिष्यामहे सीतां मायया जनकात्मजाम्॥', 'vidyujjihvaṃ ca māyājñam abravīd rākṣasādhipaḥ
mohayiṣyāmahe sītāṃ māyayā janakātmajām', null, 6022007),
('ramayana-6-22-8', 8, 'Yuddha Kanda, Sarga 22, Verse 8', 'शिरो मायामयं गृह्य राघवस्य निशाचर।
मां त्वं समुपतिष्ठस्व महच्च सशरं धनुः॥', 'śiro māyāmayaṃ gṛhya rāghavasya niśācara
māṃ tvaṃ samupatiṣṭhasva mahac ca saśaraṃ dhanuḥ', null, 6022008),
('ramayana-6-22-9', 9, 'Yuddha Kanda, Sarga 22, Verse 9', 'एवमुक्तस्तथेत्याह विद्युज्जिह्वो निशाचरः।
तस्य तुष्टोऽभवद्राजा प्रददौ च विभूषणम्॥', 'evam uktas tathety āha vidyujjihvo niśācaraḥ
tasya tuṣṭo ''bhavad rājā pradadau ca vibhūṣaṇam', null, 6022009),
('ramayana-6-22-10', 10, 'Yuddha Kanda, Sarga 22, Verse 10', 'अशोकवनिकायां तु प्रविवेश महाबलः।
ततो दीनामदैन्यार्हां ददर्श धनदानुजः।
अधोमुखीं शोकपरामुपविष्टां महीतले॥', 'aśokavanikāyāṃ tu praviveśa mahābalaḥ
tato dīnām adainyārhāṃ dadarśa dhanadānujaḥ
adhomukhīṃ śokaparām upaviṣṭāṃ mahītale', null, 6022010),
('ramayana-6-22-11', 11, 'Yuddha Kanda, Sarga 22, Verse 11', 'भर्तारमेव ध्यायन्तीमशोकवनिकां गताम्।
उपास्यमानां घोराभी राक्षसीभिरदूरतः॥', 'bhartāram eva dhyāyantīm aśokavanikāṃ gatām
upāsyamānāṃ ghorābhī rākṣasībhir adūrataḥ', null, 6022011),
('ramayana-6-22-12', 12, 'Yuddha Kanda, Sarga 22, Verse 12', 'उपसृत्य ततः सीतां प्रहर्षन्नाम कीर्तयन्।
इदं च वचनं धृष्टमुवाच जनकात्मजाम्॥', 'upasṛtya tataḥ sītāṃ praharṣan nāma kīrtayan
idaṃ ca vacanaṃ dhṛṣṭam uvāca janakātmajām', null, 6022012),
('ramayana-6-22-13', 13, 'Yuddha Kanda, Sarga 22, Verse 13', 'सान्त्व्यमाना मया भद्रे यमुपाश्रित्य वल्गसे।
खर हन्ता स ते भर्ता राघवः समरे हतः॥', 'sāntvyamānā mayā bhadre yam upāśritya valgase
khara hantā sa te bhartā rāghavaḥ samare hataḥ', null, 6022013),
('ramayana-6-22-14', 14, 'Yuddha Kanda, Sarga 22, Verse 14', 'छिन्नं ते सर्वतो मूलं दर्पस्ते निहतो मया।
व्यसनेनात्मनः सीते मम भार्या भविष्यसि॥', 'chinnaṃ te sarvato mūlaṃ darpas te nihato mayā
vyasanenātmanaḥ sīte mama bhāryā bhaviṣyasi', null, 6022014),
('ramayana-6-22-15', 15, 'Yuddha Kanda, Sarga 22, Verse 15', 'अल्पपुण्ये निवृत्तार्थे मूढे पण्डितमानिनि।
शृणु भर्तृबधं सीते घोरं वृत्रवधं यथा॥', 'alpapuṇye nivṛttārthe mūḍhe paṇḍitamānini
śṛṇu bhartṛbadhaṃ sīte ghoraṃ vṛtravadhaṃ yathā', null, 6022015),
('ramayana-6-22-16', 16, 'Yuddha Kanda, Sarga 22, Verse 16', 'समायातः समुद्रान्तं मां हन्तुं किल राघवः।
वानरेन्द्रप्रणीतेन बलेन महता वृतः॥', 'samāyātaḥ samudrāntaṃ māṃ hantuṃ kila rāghavaḥ
vānarendrapraṇītena balena mahatā vṛtaḥ', null, 6022016),
('ramayana-6-22-17', 17, 'Yuddha Kanda, Sarga 22, Verse 17', 'संनिविष्टः समुद्रस्य तीरमासाद्य दक्षिणम्।
बलेन महता रामो व्रजत्यस्तं दिवाकरे॥', 'saṃniviṣṭaḥ samudrasya tīram āsādya dakṣiṇam
balena mahatā rāmo vrajaty astaṃ divākare', null, 6022017),
('ramayana-6-22-18', 18, 'Yuddha Kanda, Sarga 22, Verse 18', 'अथाध्वनि परिश्रान्तमर्धरात्रे स्थितं बलम्।
सुखसुप्तं समासाद्य चारितं प्रथमं चरैः॥', 'athādhvani pariśrāntam ardharātre sthitaṃ balam
sukhasuptaṃ samāsādya cāritaṃ prathamaṃ caraiḥ', null, 6022018),
('ramayana-6-22-19', 19, 'Yuddha Kanda, Sarga 22, Verse 19', 'तत्प्रहस्तप्रणीतेन बलेन महता मम।
बलमस्य हतं रात्रौ यत्र रामः सुलक्ष्मणः॥', 'tat prahastapraṇītena balena mahatā mama
balam asya hataṃ rātrau yatra rāmaḥ sulakṣmaṇaḥ', null, 6022019),
('ramayana-6-22-20', 20, 'Yuddha Kanda, Sarga 22, Verse 20', 'पट्टसान्परिघान्खड्गांश्चक्रान्दण्डान्महायसान्।
बाणजालानि शूलानि भास्वरान्कूटमुद्गरान्॥', 'paṭṭasān parighān khaḍgāṃś cakrān daṇḍān mahāyasān
bāṇajālāni śūlāni bhāsvarān kūṭamudgarān', null, 6022020),
('ramayana-6-22-21', 21, 'Yuddha Kanda, Sarga 22, Verse 21', 'यष्टीश्च तोमरान्प्रासंश्चक्राणि मुसलानि च।
उद्यम्योद्यम्य रक्षोभिर्वानरेषु निपातिताः॥', 'yaṣṭīś ca tomarān prāsaṃś cakrāṇi musalāni ca
udyamyodyamya rakṣobhir vānareṣu nipātitāḥ', null, 6022021),
('ramayana-6-22-22', 22, 'Yuddha Kanda, Sarga 22, Verse 22', 'अथ सुप्तस्य रामस्य प्रहस्तेन प्रमाथिना।
असक्तं कृतहस्तेन शिरश्छिन्नं महासिना॥', 'atha suptasya rāmasya prahastena pramāthinā
asaktaṃ kṛtahastena śiraś chinnaṃ mahāsinā', null, 6022022),
('ramayana-6-22-23', 23, 'Yuddha Kanda, Sarga 22, Verse 23', 'विभीषणः समुत्पत्य निगृहीतो यदृच्छया।
दिशः प्रव्राजितः सर्वैर्लक्ष्मणः प्लवगैः सह॥', 'vibhīṣaṇaḥ samutpatya nigṛhīto yadṛcchayā
diśaḥ pravrājitaḥ sarvair lakṣmaṇaḥ plavagaiḥ saha', null, 6022023),
('ramayana-6-22-24', 24, 'Yuddha Kanda, Sarga 22, Verse 24', 'सुग्रीवो ग्रीवया शेते भग्नया प्लवगाधिपः।
निरस्तहनुकः शेते हनूमान्राक्षसैर्हतः॥', 'sugrīvo grīvayā śete bhagnayā plavagādhipaḥ
nirastahanukaḥ śete hanūmān rākṣasair hataḥ', null, 6022024),
('ramayana-6-22-25', 25, 'Yuddha Kanda, Sarga 22, Verse 25', 'जाम्बवानथ जानुभ्यामुत्पतन्निहतो युधि।
पट्टसैर्बहुभिश्छिन्नो निकृत्तः पादपो यथा॥', 'jāmbavān atha jānubhyām utpatan nihato yudhi
paṭṭasair bahubhiś chinno nikṛttaḥ pādapo yathā', null, 6022025),
('ramayana-6-22-26', 26, 'Yuddha Kanda, Sarga 22, Verse 26', 'मैन्दश्च द्विविदश्चोभौ निहतौ वानरर्षभौ।
निःश्वसन्तौ रुदन्तौ च रुधिरेण समुक्षितौ॥', 'maindaś ca dvividaś cobhau nihatau vānararṣabhau
niḥśvasantau rudantau ca rudhireṇa samukṣitau', null, 6022026),
('ramayana-6-22-27', 27, 'Yuddha Kanda, Sarga 22, Verse 27', 'असिनाभ्याहतश्छिन्नो मध्ये रिपुनिषूदनः।
अभिष्टनति मेदिन्यां पनसः पनसो यथा॥', 'asinābhyāhataś chinno madhye ripuniṣūdanaḥ
abhiṣṭanati medinyāṃ panasaḥ panaso yathā', null, 6022027),
('ramayana-6-22-28', 28, 'Yuddha Kanda, Sarga 22, Verse 28', 'नाराचैर्बहुभिश्छिन्नः शेते दर्यां दरीमुखः।
कुमुदस्तु महातेजा निष्कूजन्सायकैर्हतः॥', 'nārācair bahubhiś chinnaḥ śete daryāṃ darīmukhaḥ
kumudas tu mahātejā niṣkūjan sāyakair hataḥ', null, 6022028),
('ramayana-6-22-29', 29, 'Yuddha Kanda, Sarga 22, Verse 29', 'अङ्गदो बहुभिश्छिन्नः शरैरासाद्य राक्षसैः।
पातितो रुधिरोद्गारी क्षितौ निपतितोऽङ्गदः॥', 'aṅgado bahubhiś chinnaḥ śarair āsādya rākṣasaiḥ
pātito rudhirodgārī kṣitau nipatito ''ṅgadaḥ', null, 6022029),
('ramayana-6-22-30', 30, 'Yuddha Kanda, Sarga 22, Verse 30', 'हरयो मथिता नागै रथजालैस्तथापरे।
शायिता मृदितास्तत्र वायुवेगैरिवाम्बुदाः॥', 'harayo mathitā nāgai rathajālais tathāpare
śāyitā mṛditās tatra vāyuvegair ivāmbudāḥ', null, 6022030),
('ramayana-6-22-31', 31, 'Yuddha Kanda, Sarga 22, Verse 31', 'प्रद्रुताश्च परे त्रस्ता हन्यमाना जघन्यतः।
अभिद्रुतास्तु रक्षोभिः सिंहैरिव महाद्विपाः॥', 'pradrutāś ca pare trastā hanyamānā jaghanyataḥ
abhidrutās tu rakṣobhiḥ siṃhair iva mahādvipāḥ', null, 6022031),
('ramayana-6-22-32', 32, 'Yuddha Kanda, Sarga 22, Verse 32', 'सागरे पतिताः के चित्के चिद्गगनमाश्रिताः।
ऋक्षा वृक्षानुपारूढा वानरैस्तु विमिश्रिताः॥', 'sāgare patitāḥ ke cit ke cid gaganam āśritāḥ
ṛkṣā vṛkṣān upārūḍhā vānarais tu vimiśritāḥ', null, 6022032),
('ramayana-6-22-33', 33, 'Yuddha Kanda, Sarga 22, Verse 33', 'सागरस्य च तीरेषु शैलेषु च वनेषु च।
पिङ्गाक्षास्ते विरूपाक्षैर्बहुभिर्बहवो हताः॥', 'sāgarasya ca tīreṣu śaileṣu ca vaneṣu ca
piṅgākṣās te virūpākṣair bahubhir bahavo hatāḥ', null, 6022033),
('ramayana-6-22-34', 34, 'Yuddha Kanda, Sarga 22, Verse 34', 'एवं तव हतो भर्ता ससैन्यो मम सेनया।
क्षतजार्द्रं रजोध्वस्तमिदं चास्याहृतं शिरः॥', 'evaṃ tava hato bhartā sasainyo mama senayā
kṣatajārdraṃ rajodhvastam idaṃ cāsyāhṛtaṃ śiraḥ', null, 6022034),
('ramayana-6-22-35', 35, 'Yuddha Kanda, Sarga 22, Verse 35', 'ततः परमदुर्धर्षो रावणो राक्षसेश्वरः।
सीतायामुपशृण्वन्त्यां राक्षसीमिदमब्रवीत्॥', 'tataḥ paramadurdharṣo rāvaṇo rākṣaseśvaraḥ
sītāyām upaśṛṇvantyāṃ rākṣasīm idam abravīt', null, 6022035),
('ramayana-6-22-36', 36, 'Yuddha Kanda, Sarga 22, Verse 36', 'राक्षसं क्रूरकर्माणं विद्युज्जिह्वं त्वमानय।
येन तद्राघवशिरः संग्रामात्स्वयमाहृतम्॥', 'rākṣasaṃ krūrakarmāṇaṃ vidyujjihvaṃ tvam ānaya
yena tad rāghavaśiraḥ saṃgrāmāt svayam āhṛtam', null, 6022036),
('ramayana-6-22-37', 37, 'Yuddha Kanda, Sarga 22, Verse 37', 'विद्युज्जिह्वस्ततो गृह्य शिरस्तत्सशरासनम्।
प्रणामं शिरसा कृत्वा रावणस्याग्रतः स्थितः॥', 'vidyujjihvas tato gṛhya śiras tat saśarāsanam
praṇāmaṃ śirasā kṛtvā rāvaṇasyāgrataḥ sthitaḥ', null, 6022037),
('ramayana-6-22-38', 38, 'Yuddha Kanda, Sarga 22, Verse 38', 'तमब्रवीत्ततो राजा रावणो राक्षसं स्थितम्।
विद्युज्जिह्वं महाजिह्वं समीपपरिवर्तिनम्॥', 'tam abravīt tato rājā rāvaṇo rākṣasaṃ sthitam
vidyujjihvaṃ mahājihvaṃ samīpaparivartinam', null, 6022038),
('ramayana-6-22-39', 39, 'Yuddha Kanda, Sarga 22, Verse 39', 'अग्रतः कुरु सीतायाः शीघ्रं दाशरथेः शिरः।
अवस्थां पश्चिमां भर्तुः कृपणा साधु पश्यतु॥', 'agrataḥ kuru sītāyāḥ śīghraṃ dāśaratheḥ śiraḥ
avasthāṃ paścimāṃ bhartuḥ kṛpaṇā sādhu paśyatu', null, 6022039),
('ramayana-6-22-40', 40, 'Yuddha Kanda, Sarga 22, Verse 40', 'एवमुक्तं तु तद्रक्षः शिरस्तत्प्रियदर्शनम्।
उपनिक्षिप्य सीतायाः क्षिप्रमन्तरधीयत॥', 'evam uktaṃ tu tad rakṣaḥ śiras tat priyadarśanam
upanikṣipya sītāyāḥ kṣipram antaradhīyata', null, 6022040),
('ramayana-6-22-41', 41, 'Yuddha Kanda, Sarga 22, Verse 41', 'रावणश्चापि चिक्षेप भास्वरं कार्मुकं महत्।
त्रिषु लोकेषु विख्यातं सीतामिदमुवाच ह॥', 'rāvaṇaś cāpi cikṣepa bhāsvaraṃ kārmukaṃ mahat
triṣu lokeṣu vikhyātaṃ sītām idam uvāca ha', null, 6022041),
('ramayana-6-22-42', 42, 'Yuddha Kanda, Sarga 22, Verse 42', 'इदं तत्तव रामस्य कार्मुकं ज्यासमन्वितम्।
इह प्रहस्तेनानीतं हत्वा तं निशि मानुषम्॥', 'idaṃ tat tava rāmasya kārmukaṃ jyāsamanvitam
iha prahastenānītaṃ hatvā taṃ niśi mānuṣam', null, 6022042),
('ramayana-6-22-43', 43, 'Yuddha Kanda, Sarga 22, Verse 43', 'स विद्युज्जिह्वेन सहैव तच्छिरो धनुश्च भूमौ विनिकीर्य रावणः।
विदेहराजस्य सुतां यशस्विनीं ततोऽब्रवीत्तां भव मे वशानुगा॥', 'sa vidyujjihvena sahaiva tac chiro dhanuś ca bhūmau vinikīrya rāvaṇaḥ
videharājasya sutāṃ yaśasvinīṃ tato ''bravīt tāṃ bhava me vaśānugā', null, 6022043)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 23 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-23-1', 1, 'Yuddha Kanda, Sarga 23, Verse 1', 'सा सीता तच्छिरो दृष्ट्वा तच्च कार्मुकमुत्तमम्।
सुग्रीवप्रतिसंसर्गमाख्यातं च हनूमता॥', 'sā sītā tac chiro dṛṣṭvā tac ca kārmukam uttamam
sugrīvapratisaṃsargam ākhyātaṃ ca hanūmatā', null, 6023001),
('ramayana-6-23-2', 2, 'Yuddha Kanda, Sarga 23, Verse 2', 'नयने मुखवर्णं च भर्तुस्तत्सदृशं मुखम्।
केशान्केशान्तदेशं च तं च चूडामणिं शुभम्॥', 'nayane mukhavarṇaṃ ca bhartus tat sadṛśaṃ mukham
keśān keśāntadeśaṃ ca taṃ ca cūḍāmaṇiṃ śubham', null, 6023002),
('ramayana-6-23-3', 3, 'Yuddha Kanda, Sarga 23, Verse 3', 'एतैः सर्वैरभिज्ञानैरभिज्ञाय सुदुःखिता।
विजगर्हेऽथ कैकेयीं क्रोशन्ती कुररी यथा॥', 'etaiḥ sarvair abhijñānair abhijñāya suduḥkhitā
vijagarhe ''tha kaikeyīṃ krośantī kurarī yathā', null, 6023003),
('ramayana-6-23-4', 4, 'Yuddha Kanda, Sarga 23, Verse 4', 'सकामा भव कैकेयि हतोऽयं कुलनन्दनः।
कुलमुत्सादितं सर्वं त्वया कलहशीलया॥', 'sakāmā bhava kaikeyi hato ''yaṃ kulanandanaḥ
kulam utsāditaṃ sarvaṃ tvayā kalahaśīlayā', null, 6023004),
('ramayana-6-23-5', 5, 'Yuddha Kanda, Sarga 23, Verse 5', 'आर्येण किं नु कैकेय्याः कृतं रामेण विप्रियम्।
यद्गृहाच्चीरवसनस्तया प्रस्थापितो वनम्॥', 'āryeṇa kiṃ nu kaikeyyāḥ kṛtaṃ rāmeṇa vipriyam
yad gṛhāc cīravasanas tayā prasthāpito vanam', null, 6023005),
('ramayana-6-23-6', 6, 'Yuddha Kanda, Sarga 23, Verse 6', 'एवमुक्त्वा तु वैदेही वेपमाना तपस्विनी।
जगाम जगतीं बाला छिन्ना तु कदली यथा॥', 'evam uktvā tu vaidehī vepamānā tapasvinī
jagāma jagatīṃ bālā chinnā tu kadalī yathā', null, 6023006),
('ramayana-6-23-7', 7, 'Yuddha Kanda, Sarga 23, Verse 7', 'सा मुहूर्तात्समाश्वस्य प्रतिलभ्य च चेतनाम्।
तच्छिरः समुपाघ्राय विललापायतेक्षणा॥', 'sā muhūrtāt samāśvasya pratilabhya ca cetanām
tac chiraḥ samupāghrāya vilalāpāyatekṣaṇā', null, 6023007),
('ramayana-6-23-8', 8, 'Yuddha Kanda, Sarga 23, Verse 8', 'हा हतास्मि महाबाहो वीरव्रतमनुव्रता।
इमां ते पश्चिमावस्थां गतास्मि विधवा कृता॥', 'hā hatāsmi mahābāho vīravratam anuvratā
imāṃ te paścimāvasthāṃ gatāsmi vidhavā kṛtā', null, 6023008),
('ramayana-6-23-9', 9, 'Yuddha Kanda, Sarga 23, Verse 9', 'प्रथमं मरणं नार्या भर्तुर्वैगुण्यमुच्यते।
सुवृत्तः साधुवृत्तायाः संवृत्तस्त्वं ममाग्रतः॥', 'prathamaṃ maraṇaṃ nāryā bhartur vaiguṇyam ucyate
suvṛttaḥ sādhuvṛttāyāḥ saṃvṛttas tvaṃ mamāgrataḥ', null, 6023009),
('ramayana-6-23-10', 10, 'Yuddha Kanda, Sarga 23, Verse 10', 'दुःखाद्दुःखं प्रपन्नाया मग्नायाः शोकसागरे।
यो हि मामुद्यतस्त्रातुं सोऽपि त्वं विनिपातितः॥', 'duḥkhād duḥkhaṃ prapannāyā magnāyāḥ śokasāgare
yo hi mām udyatas trātuṃ so ''pi tvaṃ vinipātitaḥ', null, 6023010),
('ramayana-6-23-11', 11, 'Yuddha Kanda, Sarga 23, Verse 11', 'सा श्वश्रूर्मम कौसल्या त्वया पुत्रेण राघव।
वत्सेनेव यथा धेनुर्विवत्सा वत्सला कृता॥', 'sā śvaśrūr mama kausalyā tvayā putreṇa rāghava
vatseneva yathā dhenur vivatsā vatsalā kṛtā', null, 6023011),
('ramayana-6-23-12', 12, 'Yuddha Kanda, Sarga 23, Verse 12', 'आदिष्टं दीर्घमायुस्ते यैरचिन्त्यपराक्रम।
अनृतं वचनं तेषामल्पायुरसि राघव॥', 'ādiṣṭaṃ dīrgham āyus te yair acintyaparākrama
anṛtaṃ vacanaṃ teṣām alpāyur asi rāghava', null, 6023012),
('ramayana-6-23-13', 13, 'Yuddha Kanda, Sarga 23, Verse 13', 'अथ वा नश्यति प्रज्ञा प्राज्ञस्यापि सतस्तव।
पचत्येनं तथा कालो भूतानां प्रभवो ह्ययम्॥', 'atha vā naśyati prajñā prājñasyāpi satas tava
pacaty enaṃ tathā kālo bhūtānāṃ prabhavo hy ayam', null, 6023013),
('ramayana-6-23-14', 14, 'Yuddha Kanda, Sarga 23, Verse 14', 'अदृष्टं मृत्युमापन्नः कस्मात्त्वं नयशास्त्रवित्।
व्यसनानामुपायज्ञः कुशलो ह्यसि वर्जने॥', 'adṛṣṭaṃ mṛtyum āpannaḥ kasmāt tvaṃ nayaśāstravit
vyasanānām upāyajñaḥ kuśalo hy asi varjane', null, 6023014),
('ramayana-6-23-15', 15, 'Yuddha Kanda, Sarga 23, Verse 15', 'तथा त्वं संपरिष्वज्य रौद्रयातिनृशंसया।
कालरात्र्या मयाच्छिद्य हृतः कमललोचनः॥', 'tathā tvaṃ saṃpariṣvajya raudrayātinṛśaṃsayā
kālarātryā mayācchidya hṛtaḥ kamalalocanaḥ', null, 6023015),
('ramayana-6-23-16', 16, 'Yuddha Kanda, Sarga 23, Verse 16', 'उपशेषे महाबाहो मां विहाय तपस्विनीम्।
प्रियामिव शुभां नारीं पृथिवीं पुरुषर्षभ॥', 'upaśeṣe mahābāho māṃ vihāya tapasvinīm
priyām iva śubhāṃ nārīṃ pṛthivīṃ puruṣarṣabha', null, 6023016),
('ramayana-6-23-17', 17, 'Yuddha Kanda, Sarga 23, Verse 17', 'अर्चितं सततं यत्नाद्गन्धमाल्यैर्मया तव।
इदं ते मत्प्रियं वीर धनुः काञ्चनभूषितम्॥', 'arcitaṃ satataṃ yatnād gandhamālyair mayā tava
idaṃ te matpriyaṃ vīra dhanuḥ kāñcanabhūṣitam', null, 6023017),
('ramayana-6-23-18', 18, 'Yuddha Kanda, Sarga 23, Verse 18', 'पित्रा दशरथेन त्वं श्वशुरेण ममानघ।
पूर्वैश्च पितृभिः सार्धं नूनं स्वर्गे समागतः॥', 'pitrā daśarathena tvaṃ śvaśureṇa mamānagha
pūrvaiś ca pitṛbhiḥ sārdhaṃ nūnaṃ svarge samāgataḥ', null, 6023018),
('ramayana-6-23-19', 19, 'Yuddha Kanda, Sarga 23, Verse 19', 'दिवि नक्षत्रभूतस्त्वं महत्कर्म कृतं प्रियम्।
पुण्यं राजर्षिवंशं त्वमात्मनः समुपेक्षसे॥', 'divi nakṣatrabhūtas tvaṃ mahat karma kṛtaṃ priyam
puṇyaṃ rājarṣivaṃśaṃ tvam ātmanaḥ samupekṣase', null, 6023019),
('ramayana-6-23-20', 20, 'Yuddha Kanda, Sarga 23, Verse 20', 'किं मान्न प्रेक्षसे राजन्किं मां न प्रतिभाषसे।
बालां बालेन संप्राप्तां भार्यां मां सहचारिणीम्॥', 'kiṃ mān na prekṣase rājan kiṃ māṃ na pratibhāṣase
bālāṃ bālena saṃprāptāṃ bhāryāṃ māṃ sahacāriṇīm', null, 6023020),
('ramayana-6-23-21', 21, 'Yuddha Kanda, Sarga 23, Verse 21', 'संश्रुतं गृह्णता पाणिं चरिष्यामीति यत्त्वया।
स्मर तन्मम काकुत्स्थ नय मामपि दुःखिताम्॥', 'saṃśrutaṃ gṛhṇatā pāṇiṃ cariṣyāmīti yat tvayā
smara tan mama kākutstha naya mām api duḥkhitām', null, 6023021),
('ramayana-6-23-22', 22, 'Yuddha Kanda, Sarga 23, Verse 22', 'कस्मान्मामपहाय त्वं गतो गतिमतां वर।
अस्माल्लोकादमुं लोकं त्यक्त्वा मामिह दुःखिताम्॥', 'kasmān mām apahāya tvaṃ gato gatimatāṃ vara
asmāl lokād amuṃ lokaṃ tyaktvā mām iha duḥkhitām', null, 6023022),
('ramayana-6-23-23', 23, 'Yuddha Kanda, Sarga 23, Verse 23', 'कल्याणैरुचितं यत्तत्परिष्वक्तं मयैव तु।
क्रव्यादैस्तच्छरीरं ते नूनं विपरिकृष्यते॥', 'kalyāṇair ucitaṃ yat tat pariṣvaktaṃ mayaiva tu
kravyādais tac charīraṃ te nūnaṃ viparikṛṣyate', null, 6023023),
('ramayana-6-23-24', 24, 'Yuddha Kanda, Sarga 23, Verse 24', 'अग्निष्टोमादिभिर्यज्ञैरिष्टवानाप्तदक्षिणैः।
अग्निहोत्रेण संस्कारं केन त्वं तु न लप्स्यसे॥', 'agniṣṭomādibhir yajñair iṣṭavān āptadakṣiṇaiḥ
agnihotreṇa saṃskāraṃ kena tvaṃ tu na lapsyase', null, 6023024),
('ramayana-6-23-25', 25, 'Yuddha Kanda, Sarga 23, Verse 25', 'प्रव्रज्यामुपपन्नानां त्रयाणामेकमागतम्।
परिप्रक्ष्यति कौसल्या लक्ष्मणं शोकलालसा॥', 'pravrajyām upapannānāṃ trayāṇām ekam āgatam
pariprakṣyati kausalyā lakṣmaṇaṃ śokalālasā', null, 6023025),
('ramayana-6-23-26', 26, 'Yuddha Kanda, Sarga 23, Verse 26', 'स तस्याः परिपृच्छन्त्या वधं मित्रबलस्य ते।
तव चाख्यास्यते नूनं निशायां राक्षसैर्वधम्॥', 'sa tasyāḥ paripṛcchantyā vadhaṃ mitrabalasya te
tava cākhyāsyate nūnaṃ niśāyāṃ rākṣasair vadham', null, 6023026),
('ramayana-6-23-27', 27, 'Yuddha Kanda, Sarga 23, Verse 27', 'सा त्वां सुप्तं हतं श्रुत्वा मां च रक्षोगृहं गताम्।
हृदयेन विदीर्णेन न भविष्यति राघव॥', 'sā tvāṃ suptaṃ hataṃ śrutvā māṃ ca rakṣogṛhaṃ gatām
hṛdayena vidīrṇena na bhaviṣyati rāghava', null, 6023027),
('ramayana-6-23-28', 28, 'Yuddha Kanda, Sarga 23, Verse 28', 'साधु पातय मां क्षिप्रं रामस्योपरि रावणः।
समानय पतिं पत्न्या कुरु कल्याणमुत्तमम्॥', 'sādhu pātaya māṃ kṣipraṃ rāmasyopari rāvaṇaḥ
samānaya patiṃ patnyā kuru kalyāṇam uttamam', null, 6023028),
('ramayana-6-23-29', 29, 'Yuddha Kanda, Sarga 23, Verse 29', 'शिरसा मे शिरश्चास्य कायं कायेन योजय।
रावणानुगमिष्यामि गतिं भर्तुर्महात्मनः।
मुहूर्तमपि नेच्छामि जीवितुं पापजीविना॥', 'śirasā me śiraś cāsya kāyaṃ kāyena yojaya
rāvaṇānugamiṣyāmi gatiṃ bhartur mahātmanaḥ
muhūrtam api necchāmi jīvituṃ pāpajīvinā', null, 6023029),
('ramayana-6-23-30', 30, 'Yuddha Kanda, Sarga 23, Verse 30', 'श्रुतं मया वेदविदां ब्राह्मणानां पितुर्गृहे।
यासां स्त्रीणां प्रियो भर्ता तासां लोका महोदयाः॥', 'śrutaṃ mayā vedavidāṃ brāhmaṇānāṃ pitur gṛhe
yāsāṃ strīṇāṃ priyo bhartā tāsāṃ lokā mahodayāḥ', null, 6023030),
('ramayana-6-23-31', 31, 'Yuddha Kanda, Sarga 23, Verse 31', 'क्षमा यस्मिन्दमस्त्यागः सत्यं धर्मः कृतज्ञता।
अहिंसा चैव भूतानां तमृते का गतिर्मम॥', 'kṣamā yasmin damas tyāgaḥ satyaṃ dharmaḥ kṛtajñatā
ahiṃsā caiva bhūtānāṃ tam ṛte kā gatir mama', null, 6023031),
('ramayana-6-23-32', 32, 'Yuddha Kanda, Sarga 23, Verse 32', 'इति सा दुःखसंतप्ता विललापायतेक्षणा।
भर्तुः शिरो धनुस्तत्र समीक्ष्य जनकात्मजा॥', 'iti sā duḥkhasaṃtaptā vilalāpāyatekṣaṇā
bhartuḥ śiro dhanus tatra samīkṣya janakātmajā', null, 6023032),
('ramayana-6-23-33', 33, 'Yuddha Kanda, Sarga 23, Verse 33', 'एवं लालप्यमानायां सीतायां तत्र राक्षसः।
अभिचक्राम भर्तारमनीकस्थः कृताञ्जलिः॥', 'evaṃ lālapyamānāyāṃ sītāyāṃ tatra rākṣasaḥ
abhicakrāma bhartāram anīkasthaḥ kṛtāñjaliḥ', null, 6023033),
('ramayana-6-23-34', 34, 'Yuddha Kanda, Sarga 23, Verse 34', 'विजयस्वार्यपुत्रेति सोऽभिवाद्य प्रसाद्य च।
न्यवेदयदनुप्राप्तं प्रहस्तं वाहिनीपतिम्॥', 'vijayasvāryaputreti so ''bhivādya prasādya ca
nyavedayad anuprāptaṃ prahastaṃ vāhinīpatim', null, 6023034),
('ramayana-6-23-35', 35, 'Yuddha Kanda, Sarga 23, Verse 35', 'अमात्यैः सहितः सर्वैः प्रहस्तः समुपस्थितः।
किं चिदात्ययिकं कार्यं तेषां त्वं दर्शनं कुरु॥', 'amātyaiḥ sahitaḥ sarvaiḥ prahastaḥ samupasthitaḥ
kiṃ cid ātyayikaṃ kāryaṃ teṣāṃ tvaṃ darśanaṃ kuru', null, 6023035),
('ramayana-6-23-36', 36, 'Yuddha Kanda, Sarga 23, Verse 36', 'एतच्छ्रुत्वा दशग्रीवो राक्षसप्रतिवेदितम्।
अशोकवनिकां त्यक्त्वा मन्त्रिणां दर्शनं ययौ॥', 'etac chrutvā daśagrīvo rākṣasaprativeditam
aśokavanikāṃ tyaktvā mantriṇāṃ darśanaṃ yayau', null, 6023036),
('ramayana-6-23-37', 37, 'Yuddha Kanda, Sarga 23, Verse 37', 'स तु सर्वं समर्थ्यैव मन्त्रिभिः कृत्यमात्मनः।
सभां प्रविश्य विदधे विदित्वा रामविक्रमम्॥', 'sa tu sarvaṃ samarthyaiva mantribhiḥ kṛtyam ātmanaḥ
sabhāṃ praviśya vidadhe viditvā rāmavikramam', null, 6023037),
('ramayana-6-23-38', 38, 'Yuddha Kanda, Sarga 23, Verse 38', 'अन्तर्धानं तु तच्छीर्षं तच्च कार्मुकमुत्तमम्।
जगाम रावणस्यैव निर्याणसमनन्तरम्॥', 'antardhānaṃ tu tac chīrṣaṃ tac ca kārmukam uttamam
jagāma rāvaṇasyaiva niryāṇasamanantaram', null, 6023038),
('ramayana-6-23-39', 39, 'Yuddha Kanda, Sarga 23, Verse 39', 'राक्षसेन्द्रस्तु तैः सार्धं मन्त्रिभिर्भीमविक्रमैः।
समर्थयामास तदा रामकार्यविनिश्चयम्॥', 'rākṣasendras tu taiḥ sārdhaṃ mantribhir bhīmavikramaiḥ
samarthayām āsa tadā rāmakāryaviniścayam', null, 6023039),
('ramayana-6-23-40', 40, 'Yuddha Kanda, Sarga 23, Verse 40', 'अविदूरस्थितान्सर्वान्बलाध्यक्षान्हितैषिणः।
अब्रवीत्कालसदृशो रावणो राक्षसाधिपः॥', 'avidūrasthitān sarvān balādhyakṣān hitaiṣiṇaḥ
abravīt kālasadṛśo rāvaṇo rākṣasādhipaḥ', null, 6023040),
('ramayana-6-23-41', 41, 'Yuddha Kanda, Sarga 23, Verse 41', 'शीघ्रं भेरीनिनादेन स्फुटकोणाहतेन मे।
समानयध्वं सैन्यानि वक्तव्यं च न कारणम्॥', 'śīghraṃ bherīninādena sphuṭakoṇāhatena me
samānayadhvaṃ sainyāni vaktavyaṃ ca na kāraṇam', null, 6023041),
('ramayana-6-23-42', 42, 'Yuddha Kanda, Sarga 23, Verse 42', 'ततस्तथेति प्रतिगृह्य तद्वचो बलाधिपास्ते महदात्मनो बलम्।
समानयंश्चैव समागतं च ते न्यवेदयन्भर्तरि युद्धकाङ्क्षिणि॥', 'tatas tatheti pratigṛhya tad vaco balādhipās te mahad ātmano balam
samānayaṃś caiva samāgataṃ ca te nyavedayan bhartari yuddhakāṅkṣiṇi', null, 6023042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 24 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-24-1', 1, 'Yuddha Kanda, Sarga 24, Verse 1', 'सीतां तु मोहितां दृष्ट्वा सरमा नाम राक्षसी।
आससादाशु वैदेहीं प्रियां प्रणयिनी सखी॥', 'sītāṃ tu mohitāṃ dṛṣṭvā saramā nāma rākṣasī
āsasādāśu vaidehīṃ priyāṃ praṇayinī sakhī', null, 6024001),
('ramayana-6-24-2', 2, 'Yuddha Kanda, Sarga 24, Verse 2', 'सा हि तत्र कृता मित्रं सीतया रक्ष्यमाणया।
रक्षन्ती रावणादिष्टा सानुक्रोशा दृढव्रता॥', 'sā hi tatra kṛtā mitraṃ sītayā rakṣyamāṇayā
rakṣantī rāvaṇād iṣṭā sānukrośā dṛḍhavratā', null, 6024002),
('ramayana-6-24-3', 3, 'Yuddha Kanda, Sarga 24, Verse 3', 'सा ददर्श सखीं सीतां सरमा नष्टचेतनाम्।
उपावृत्योत्थितां ध्वस्तां वडवामिव पांसुषु॥', 'sā dadarśa sakhīṃ sītāṃ saramā naṣṭacetanām
upāvṛtyotthitāṃ dhvastāṃ vaḍavām iva pāṃsuṣu', null, 6024003),
('ramayana-6-24-4', 4, 'Yuddha Kanda, Sarga 24, Verse 4', 'तां समाश्वासयामास सखी स्नेहेन सुव्रता।
उक्ता यद्रावणेन त्वं प्रत्युक्तं च स्वयं त्वया॥', 'tāṃ samāśvāsayām āsa sakhī snehena suvratā
uktā yad rāvaṇena tvaṃ pratyuktaṃ ca svayaṃ tvayā', null, 6024004),
('ramayana-6-24-5', 5, 'Yuddha Kanda, Sarga 24, Verse 5', 'सखीस्नेहेन तद्भीरु मया सर्वं प्रतिश्रुतम्।
लीनया गनहे शूह्ये भयमुत्सृज्य रावणात्।
तव हेतोर्विशालाक्षि न हि मे जीवितं प्रियम्॥', 'sakhīsnehena tad bhīru mayā sarvaṃ pratiśrutam
līnayā ganahe śūhye bhayam utsṛjya rāvaṇāt
tava hetor viśālākṣi na hi me jīvitaṃ priyam', null, 6024005),
('ramayana-6-24-6', 6, 'Yuddha Kanda, Sarga 24, Verse 6', 'स संभ्रान्तश्च निष्क्रान्तो यत्कृते राक्षसाधिपः।
तच्च मे विदितं सर्वमभिनिष्क्रम्य मैथिलि॥', 'sa saṃbhrāntaś ca niṣkrānto yat kṛte rākṣasādhipaḥ
tac ca me viditaṃ sarvam abhiniṣkramya maithili', null, 6024006),
('ramayana-6-24-7', 7, 'Yuddha Kanda, Sarga 24, Verse 7', 'न शक्यं सौप्तिकं कर्तुं रामस्य विदितात्मनः।
वधश्च पुरुषव्याघ्रे तस्मिन्नेवोपपद्यते॥', 'na śakyaṃ sauptikaṃ kartuṃ rāmasya viditātmanaḥ
vadhaś ca puruṣavyāghre tasminn evopapadyate', null, 6024007),
('ramayana-6-24-8', 8, 'Yuddha Kanda, Sarga 24, Verse 8', 'न चैव वानरा हन्तुं शक्याः पादपयोधिनः।
सुरा देवर्षभेणेव रामेण हि सुरक्षिताः॥', 'na caiva vānarā hantuṃ śakyāḥ pādapayodhinaḥ
surā devarṣabheṇeva rāmeṇa hi surakṣitāḥ', null, 6024008),
('ramayana-6-24-9', 9, 'Yuddha Kanda, Sarga 24, Verse 9', 'दीर्घवृत्तभुजः श्रीमान्महोरस्कः प्रतापवान्।
धन्वी संहननोपेतो धर्मात्मा भुवि विश्रुतः॥', 'dīrghavṛttabhujaḥ śrīmān mahoraskaḥ pratāpavān
dhanvī saṃhananopeto dharmātmā bhuvi viśrutaḥ', null, 6024009),
('ramayana-6-24-10', 10, 'Yuddha Kanda, Sarga 24, Verse 10', 'विक्रान्तो रक्षिता नित्यमात्मनश्च परस्य च।
लक्ष्मणेन सह भ्रात्रा कुशली नयशास्त्रवित्॥', 'vikrānto rakṣitā nityam ātmanaś ca parasya ca
lakṣmaṇena saha bhrātrā kuśalī nayaśāstravit', null, 6024010),
('ramayana-6-24-11', 11, 'Yuddha Kanda, Sarga 24, Verse 11', 'हन्ता परबलौघानामचिन्त्यबलपौरुषः।
न हतो राघवः श्रीमान्सीते शत्रुनिबर्हणः॥', 'hantā parabalaughānām acintyabalapauruṣaḥ
na hato rāghavaḥ śrīmān sīte śatrunibarhaṇaḥ', null, 6024011),
('ramayana-6-24-12', 12, 'Yuddha Kanda, Sarga 24, Verse 12', 'अयुक्तबुद्धिकृत्येन सर्वभूतविरोधिना।
इयं प्रयुक्ता रौद्रेण माया मायाविदा त्वयि॥', 'ayuktabuddhikṛtyena sarvabhūtavirodhinā
iyaṃ prayuktā raudreṇa māyā māyāvidā tvayi', null, 6024012),
('ramayana-6-24-13', 13, 'Yuddha Kanda, Sarga 24, Verse 13', 'शोकस्ते विगतः सर्वः कल्याणं त्वामुपस्थितम्।
ध्रुवं त्वां भजते लक्ष्मीः प्रियं प्रीतिकरं शृणु॥', 'śokas te vigataḥ sarvaḥ kalyāṇaṃ tvām upasthitam
dhruvaṃ tvāṃ bhajate lakṣmīḥ priyaṃ prītikaraṃ śṛṇu', null, 6024013),
('ramayana-6-24-14', 14, 'Yuddha Kanda, Sarga 24, Verse 14', 'उत्तीर्य सागरं रामः सह वानरसेनया।
संनिविष्टः समुद्रस्य तीरमासाद्य दक्षिणम्॥', 'uttīrya sāgaraṃ rāmaḥ saha vānarasenayā
saṃniviṣṭaḥ samudrasya tīram āsādya dakṣiṇam', null, 6024014),
('ramayana-6-24-15', 15, 'Yuddha Kanda, Sarga 24, Verse 15', 'दृष्टो मे परिपूर्णार्थः काकुत्स्थः सहलक्ष्मणः।
सहितैः सागरान्तस्थैर्बलैस्तिष्ठति रक्षितः॥', 'dṛṣṭo me paripūrṇārthaḥ kākutsthaḥ sahalakṣmaṇaḥ
sahitaiḥ sāgarāntasthair balais tiṣṭhati rakṣitaḥ', null, 6024015),
('ramayana-6-24-16', 16, 'Yuddha Kanda, Sarga 24, Verse 16', 'अनेन प्रेषिता ये च राक्षसा लघुविक्रमः।
राघवस्तीर्ण इत्येवं प्रवृत्तिस्तैरिहाहृता॥', 'anena preṣitā ye ca rākṣasā laghuvikramaḥ
rāghavas tīrṇa ity evaṃ pravṛttis tair ihāhṛtā', null, 6024016),
('ramayana-6-24-17', 17, 'Yuddha Kanda, Sarga 24, Verse 17', 'स तां श्रुत्वा विशालाक्षि प्रवृत्तिं राक्षसाधिपः।
एष मन्त्रयते सर्वैः सचिवैः सह रावणः॥', 'sa tāṃ śrutvā viśālākṣi pravṛttiṃ rākṣasādhipaḥ
eṣa mantrayate sarvaiḥ sacivaiḥ saha rāvaṇaḥ', null, 6024017),
('ramayana-6-24-18', 18, 'Yuddha Kanda, Sarga 24, Verse 18', 'इति ब्रुवाणा सरमा राक्षसी सीतया सह।
सर्वोद्योगेन सैन्यानां शब्दं शुश्राव भैरवम्॥', 'iti bruvāṇā saramā rākṣasī sītayā saha
sarvodyogena sainyānāṃ śabdaṃ śuśrāva bhairavam', null, 6024018),
('ramayana-6-24-19', 19, 'Yuddha Kanda, Sarga 24, Verse 19', 'दण्डनिर्घातवादिन्याः श्रुत्वा भेर्या महास्वनम्।
उवाच सरमा सीतामिदं मधुरभाषिणी॥', 'daṇḍanirghātavādinyāḥ śrutvā bheryā mahāsvanam
uvāca saramā sītām idaṃ madhurabhāṣiṇī', null, 6024019),
('ramayana-6-24-20', 20, 'Yuddha Kanda, Sarga 24, Verse 20', 'संनाहजननी ह्येषा भैरवा भीरु भेरिका।
भेरीनादं च गम्भीरं शृणु तोयदनिस्वनम्॥', 'saṃnāhajananī hy eṣā bhairavā bhīru bherikā
bherīnādaṃ ca gambhīraṃ śṛṇu toyadanisvanam', null, 6024020),
('ramayana-6-24-21', 21, 'Yuddha Kanda, Sarga 24, Verse 21', 'कल्प्यन्ते मत्तमातंगा युज्यन्ते रथवाजिनः।
तत्र तत्र च संनद्धाः संपतन्ति पदातयः॥', 'kalpyante mattamātaṃgā yujyante rathavājinaḥ
tatra tatra ca saṃnaddhāḥ saṃpatanti padātayaḥ', null, 6024021),
('ramayana-6-24-22', 22, 'Yuddha Kanda, Sarga 24, Verse 22', 'आपूर्यन्ते राजमार्गाः सैन्यैरद्भुतदर्शनैः।
वेगवद्भिर्नदद्भिश्च तोयौघैरिव सागरः॥', 'āpūryante rājamārgāḥ sainyair adbhutadarśanaiḥ
vegavadbhir nadadbhiś ca toyaughair iva sāgaraḥ', null, 6024022),
('ramayana-6-24-23', 23, 'Yuddha Kanda, Sarga 24, Verse 23', 'शास्त्राणां च प्रसन्नानां चर्मणां वर्मणां तथा।
रथवाजिगजानां च भूषितानां च रक्षसाम्॥', 'śāstrāṇāṃ ca prasannānāṃ carmaṇāṃ varmaṇāṃ tathā
rathavājigajānāṃ ca bhūṣitānāṃ ca rakṣasām', null, 6024023),
('ramayana-6-24-24', 24, 'Yuddha Kanda, Sarga 24, Verse 24', 'प्रभां विसृजतां पश्य नानावर्णां समुत्थिताम्।
वनं निर्दहतो धर्मे यथारूपं विभावसोः॥', 'prabhāṃ visṛjatāṃ paśya nānāvarṇāṃ samutthitām
vanaṃ nirdahato dharme yathārūpaṃ vibhāvasoḥ', null, 6024024),
('ramayana-6-24-25', 25, 'Yuddha Kanda, Sarga 24, Verse 25', 'घण्टानां शृणु निर्घोषं रथानां शृणु निस्वनम्।
हयानां हेषमाणानां शृणु तूर्यध्वनिं यथा॥', 'ghaṇṭānāṃ śṛṇu nirghoṣaṃ rathānāṃ śṛṇu nisvanam
hayānāṃ heṣamāṇānāṃ śṛṇu tūryadhvaniṃ yathā', null, 6024025),
('ramayana-6-24-26', 26, 'Yuddha Kanda, Sarga 24, Verse 26', 'उद्यतायुधहस्तानां राक्षसेन्द्रानुयायिनाम्।
संभ्रमो रक्षसामेष तुमुलो लोमहर्षणः॥', 'udyatāyudhahastānāṃ rākṣasendrānuyāyinām
saṃbhramo rakṣasām eṣa tumulo lomaharṣaṇaḥ', null, 6024026),
('ramayana-6-24-27', 27, 'Yuddha Kanda, Sarga 24, Verse 27', 'श्रीस्त्वां भजति शोकघ्नी रक्षसां भयमागतम्।
रामात्कमलपत्राक्षि दैत्यानामिव वासवात्॥', 'śrīs tvāṃ bhajati śokaghnī rakṣasāṃ bhayam āgatam
rāmāt kamalapatrākṣi daityānām iva vāsavāt', null, 6024027),
('ramayana-6-24-28', 28, 'Yuddha Kanda, Sarga 24, Verse 28', 'अवजित्य जितक्रोधस्तमचिन्त्यपराक्रमः।
रावणं समरे हत्वा भर्ता त्वाधिगमिष्यति॥', 'avajitya jitakrodhas tam acintyaparākramaḥ
rāvaṇaṃ samare hatvā bhartā tvādhigamiṣyati', null, 6024028),
('ramayana-6-24-29', 29, 'Yuddha Kanda, Sarga 24, Verse 29', 'विक्रमिष्यति रक्षःसु भर्ता ते सहलक्ष्मणः।
यथा शत्रुषु शत्रुघ्नो विष्णुना सह वासवः॥', 'vikramiṣyati rakṣaḥsu bhartā te sahalakṣmaṇaḥ
yathā śatruṣu śatrughno viṣṇunā saha vāsavaḥ', null, 6024029),
('ramayana-6-24-30', 30, 'Yuddha Kanda, Sarga 24, Verse 30', 'आगतस्य हि रामस्य क्षिप्रमङ्कगतां सतीम्।
अहं द्रक्ष्यामि सिद्धार्थां त्वां शत्रौ विनिपातिते॥', 'āgatasya hi rāmasya kṣipram aṅkagatāṃ satīm
ahaṃ drakṣyāmi siddhārthāṃ tvāṃ śatrau vinipātite', null, 6024030),
('ramayana-6-24-31', 31, 'Yuddha Kanda, Sarga 24, Verse 31', 'अश्रूण्यानन्दजानि त्वं वर्तयिष्यसि शोभने।
समागम्य परिष्वक्ता तस्योरसि महोरसः॥', 'aśrūṇy ānandajāni tvaṃ vartayiṣyasi śobhane
samāgamya pariṣvaktā tasyorasi mahorasaḥ', null, 6024031),
('ramayana-6-24-32', 32, 'Yuddha Kanda, Sarga 24, Verse 32', 'अचिरान्मोक्ष्यते सीते देवि ते जघनं गताम्।
धृतामेतां बहून्मासान्वेणीं रामो महाबलः॥', 'acirān mokṣyate sīte devi te jaghanaṃ gatām
dhṛtām etāṃ bahūn māsān veṇīṃ rāmo mahābalaḥ', null, 6024032),
('ramayana-6-24-33', 33, 'Yuddha Kanda, Sarga 24, Verse 33', 'तस्य दृष्ट्वा मुखं देवि पूर्णचन्द्रमिवोदितम्।
मोक्ष्यसे शोकजं वारि निर्मोकमिव पन्नगी॥', 'tasya dṛṣṭvā mukhaṃ devi pūrṇacandram ivoditam
mokṣyase śokajaṃ vāri nirmokam iva pannagī', null, 6024033),
('ramayana-6-24-34', 34, 'Yuddha Kanda, Sarga 24, Verse 34', 'रावणं समरे हत्वा नचिरादेव मैथिलि।
त्वया समग्रं प्रियया सुखार्हो लप्स्यते सुखम्॥', 'rāvaṇaṃ samare hatvā nacirād eva maithili
tvayā samagraṃ priyayā sukhārho lapsyate sukham', null, 6024034),
('ramayana-6-24-35', 35, 'Yuddha Kanda, Sarga 24, Verse 35', 'समागता त्वं रामेण मोदिष्यसि महात्मना।
सुवर्षेण समायुक्ता यथा सस्येन मेदिनी॥', 'samāgatā tvaṃ rāmeṇa modiṣyasi mahātmanā
suvarṣeṇa samāyuktā yathā sasyena medinī', null, 6024035),
('ramayana-6-24-36', 36, 'Yuddha Kanda, Sarga 24, Verse 36', 'गिरिवरमभितोऽनुवर्तमानो हय इव मण्डलमाशु यः करोति।
तमिह शरणमभ्युपेहि देवि दिवसकरं प्रभवो ह्ययं प्रजानाम्॥', 'girivaram abhito ''nuvartamāno haya iva maṇḍalam āśu yaḥ karoti
tam iha śaraṇam abhyupehi devi divasakaraṃ prabhavo hy ayaṃ prajānām', null, 6024036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 25 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-25-1', 1, 'Yuddha Kanda, Sarga 25, Verse 1', 'अथ तां जातसंतापां तेन वाक्येन मोहिताम्।
सरमा ह्लादयामास पृतिवीं द्यौरिवाम्भसा॥', 'atha tāṃ jātasaṃtāpāṃ tena vākyena mohitām
saramā hlādayām āsa pṛtivīṃ dyaur ivāmbhasā', null, 6025001),
('ramayana-6-25-2', 2, 'Yuddha Kanda, Sarga 25, Verse 2', 'ततस्तस्या हितं सख्याश्चिकीर्षन्ती सखी वचः।
उवाच काले कालज्ञा स्मितपूर्वाभिभाषिणी॥', 'tatas tasyā hitaṃ sakhyāś cikīrṣantī sakhī vacaḥ
uvāca kāle kālajñā smitapūrvābhibhāṣiṇī', null, 6025002),
('ramayana-6-25-3', 3, 'Yuddha Kanda, Sarga 25, Verse 3', 'उत्सहेयमहं गत्वा त्वद्वाक्यमसितेक्षणे।
निवेद्य कुशलं रामे प्रतिच्छन्ना निवर्तितुम्॥', 'utsaheyam ahaṃ gatvā tvadvākyam asitekṣaṇe
nivedya kuśalaṃ rāme praticchannā nivartitum', null, 6025003),
('ramayana-6-25-4', 4, 'Yuddha Kanda, Sarga 25, Verse 4', 'न हि मे क्रममाणाया निरालम्बे विहायसि।
समर्थो गतिमन्वेतुं पवनो गरुडोऽपि वा॥', 'na hi me kramamāṇāyā nirālambe vihāyasi
samartho gatim anvetuṃ pavano garuḍo ''pi vā', null, 6025004),
('ramayana-6-25-5', 5, 'Yuddha Kanda, Sarga 25, Verse 5', 'एवं ब्रुवाणां तां सीता सरमां पुनरब्रवीत्।
मधुरं श्लक्ष्णया वाचा पूर्वशोकाभिपन्नया॥', 'evaṃ bruvāṇāṃ tāṃ sītā saramāṃ punar abravīt
madhuraṃ ślakṣṇayā vācā pūrvaśokābhipannayā', null, 6025005),
('ramayana-6-25-6', 6, 'Yuddha Kanda, Sarga 25, Verse 6', 'समर्था गगनं गन्तुमपि वा त्वं रसातलम्।
अवगच्छाम्यकर्तव्यं कर्तव्यं ते मदन्तरे॥', 'samarthā gaganaṃ gantum api vā tvaṃ rasātalam
avagacchāmy akartavyaṃ kartavyaṃ te madantare', null, 6025006),
('ramayana-6-25-7', 7, 'Yuddha Kanda, Sarga 25, Verse 7', 'मत्प्रियं यदि कर्तव्यं यदि बुद्धिः स्थिरा तव।
ज्ञातुमिच्छामि तं गत्वा किं करोतीति रावणः॥', 'matpriyaṃ yadi kartavyaṃ yadi buddhiḥ sthirā tava
jñātum icchāmi taṃ gatvā kiṃ karotīti rāvaṇaḥ', null, 6025007),
('ramayana-6-25-8', 8, 'Yuddha Kanda, Sarga 25, Verse 8', 'स हि मायाबलः क्रूरो रावणः शत्रुरावणः।
मां मोहयति दुष्टात्मा पीतमात्रेव वारुणी॥', 'sa hi māyābalaḥ krūro rāvaṇaḥ śatrurāvaṇaḥ
māṃ mohayati duṣṭātmā pītamātreva vāruṇī', null, 6025008),
('ramayana-6-25-9', 9, 'Yuddha Kanda, Sarga 25, Verse 9', 'तर्जापयति मां नित्यं भर्त्सापयति चासकृत्।
राक्षसीभिः सुघोराभिर्या मां रक्षन्ति नित्यशः॥', 'tarjāpayati māṃ nityaṃ bhartsāpayati cāsakṛt
rākṣasībhiḥ sughorābhir yā māṃ rakṣanti nityaśaḥ', null, 6025009),
('ramayana-6-25-10', 10, 'Yuddha Kanda, Sarga 25, Verse 10', 'उद्विग्ना शङ्किता चास्मि न च स्वस्थं मनो मम।
तद्भयाच्चाहमुद्विग्ना अशोकवनिकां गताः॥', 'udvignā śaṅkitā cāsmi na ca svasthaṃ mano mama
tad bhayāc cāham udvignā aśokavanikāṃ gatāḥ', null, 6025010),
('ramayana-6-25-11', 11, 'Yuddha Kanda, Sarga 25, Verse 11', 'यदि नाम कथा तस्य निश्चितं वापि यद्भवेत्।
निवेदयेथाः सर्वं तत्परो मे स्यादनुग्रहः॥', 'yadi nāma kathā tasya niścitaṃ vāpi yad bhavet
nivedayethāḥ sarvaṃ tat paro me syād anugrahaḥ', null, 6025011),
('ramayana-6-25-12', 12, 'Yuddha Kanda, Sarga 25, Verse 12', 'सा त्वेवं ब्रुवतीं सीतां सरमा वल्गुभाषिणी।
उवाच वचनं तस्याः स्पृशन्ती बाष्पविक्लवम्॥', 'sā tv evaṃ bruvatīṃ sītāṃ saramā valgubhāṣiṇī
uvāca vacanaṃ tasyāḥ spṛśantī bāṣpaviklavam', null, 6025012),
('ramayana-6-25-13', 13, 'Yuddha Kanda, Sarga 25, Verse 13', 'एष ते यद्यभिप्रायस्तस्माद्गच्छामि जानकि।
गृह्य शत्रोरभिप्रायमुपावृत्तां च पश्य माम्॥', 'eṣa te yady abhiprāyas tasmād gacchāmi jānaki
gṛhya śatror abhiprāyam upāvṛttāṃ ca paśya mām', null, 6025013),
('ramayana-6-25-14', 14, 'Yuddha Kanda, Sarga 25, Verse 14', 'एवमुक्त्वा ततो गत्वा समीपं तस्य रक्षसः।
शुश्राव कथितं तस्य रावणस्य समन्त्रिणः॥', 'evam uktvā tato gatvā samīpaṃ tasya rakṣasaḥ
śuśrāva kathitaṃ tasya rāvaṇasya samantriṇaḥ', null, 6025014),
('ramayana-6-25-15', 15, 'Yuddha Kanda, Sarga 25, Verse 15', 'सा श्रुत्वा निश्चयं तस्य निश्चयज्ञा दुरात्मनः।
पुनरेवागमत्क्षिप्रमशोकवनिकां तदा॥', 'sā śrutvā niścayaṃ tasya niścayajñā durātmanaḥ
punar evāgamat kṣipram aśokavanikāṃ tadā', null, 6025015),
('ramayana-6-25-16', 16, 'Yuddha Kanda, Sarga 25, Verse 16', 'सा प्रविष्टा पुनस्तत्र ददर्श जनकात्मजाम्।
प्रतीक्षमाणां स्वामेव भ्रष्टपद्मामिव श्रियम्॥', 'sā praviṣṭā punas tatra dadarśa janakātmajām
pratīkṣamāṇāṃ svām eva bhraṣṭapadmām iva śriyam', null, 6025016),
('ramayana-6-25-17', 17, 'Yuddha Kanda, Sarga 25, Verse 17', 'तां तु सीता पुनः प्राप्तां सरमां वल्गुभाषिणीम्।
परिष्वज्य च सुस्निग्धं ददौ च स्वयमासनम्॥', 'tāṃ tu sītā punaḥ prāptāṃ saramāṃ valgubhāṣiṇīm
pariṣvajya ca susnigdhaṃ dadau ca svayam āsanam', null, 6025017),
('ramayana-6-25-18', 18, 'Yuddha Kanda, Sarga 25, Verse 18', 'इहासीना सुखं सर्वमाख्याहि मम तत्त्वतः।
क्रूरस्य निश्चयं तस्य रावणस्य दुरात्मनः॥', 'ihāsīnā sukhaṃ sarvam ākhyāhi mama tattvataḥ
krūrasya niścayaṃ tasya rāvaṇasya durātmanaḥ', null, 6025018),
('ramayana-6-25-19', 19, 'Yuddha Kanda, Sarga 25, Verse 19', 'एवमुक्ता तु सरमा सीतया वेपमानया।
कथितं सर्वमाचष्ट रावणस्य समन्त्रिणः॥', 'evam uktā tu saramā sītayā vepamānayā
kathitaṃ sarvam ācaṣṭa rāvaṇasya samantriṇaḥ', null, 6025019),
('ramayana-6-25-20', 20, 'Yuddha Kanda, Sarga 25, Verse 20', 'जनन्या राक्षसेन्द्रो वै त्वन्मोक्षार्थं बृहद्वचः।
अविद्धेन च वैदेहि मन्त्रिवृद्धेन बोधितः॥', 'jananyā rākṣasendro vai tvanmokṣārthaṃ bṛhadvacaḥ
aviddhena ca vaidehi mantrivṛddhena bodhitaḥ', null, 6025020),
('ramayana-6-25-21', 21, 'Yuddha Kanda, Sarga 25, Verse 21', 'दीयतामभिसत्कृत्य मनुजेन्द्राय मैथिली।
निदर्शनं ते पर्याप्तं जनस्थाने यदद्भुतम्॥', 'dīyatām abhisatkṛtya manujendrāya maithilī
nidarśanaṃ te paryāptaṃ janasthāne yad adbhutam', null, 6025021),
('ramayana-6-25-22', 22, 'Yuddha Kanda, Sarga 25, Verse 22', 'लङ्घनं च समुद्रस्य दर्शनं च हनूमतः।
वधं च रक्षसां युद्धे कः कुर्यान्मानुषो भुवि॥', 'laṅghanaṃ ca samudrasya darśanaṃ ca hanūmataḥ
vadhaṃ ca rakṣasāṃ yuddhe kaḥ kuryān mānuṣo bhuvi', null, 6025022),
('ramayana-6-25-23', 23, 'Yuddha Kanda, Sarga 25, Verse 23', 'एवं स मन्त्रिवृद्धैश्च मात्रा च बहु भाषितः।
न त्वामुत्सहते मोक्तुमर्तह्मर्थपरो यथा॥', 'evaṃ sa mantrivṛddhaiś ca mātrā ca bahu bhāṣitaḥ
na tvām utsahate moktum artahm arthaparo yathā', null, 6025023),
('ramayana-6-25-24', 24, 'Yuddha Kanda, Sarga 25, Verse 24', 'नोत्सहत्यमृतो मोक्तुं युद्धे त्वामिति मैथिलि।
सामात्यस्य नृशंसस्य निश्चयो ह्येष वर्तते॥', 'notsahaty amṛto moktuṃ yuddhe tvām iti maithili
sāmātyasya nṛśaṃsasya niścayo hy eṣa vartate', null, 6025024),
('ramayana-6-25-25', 25, 'Yuddha Kanda, Sarga 25, Verse 25', 'तदेषा सुस्थिरा बुद्धिर्मृत्युलोभादुपस्थिता।
भयान्न शक्तस्त्वां मोक्तुमनिरस्तस्तु संयुगे।
राक्षसानां च सर्वेषामात्मनश्च वधेन हि॥', 'tad eṣā susthirā buddhir mṛtyulobhād upasthitā
bhayān na śaktas tvāṃ moktum anirastas tu saṃyuge
rākṣasānāṃ ca sarveṣām ātmanaś ca vadhena hi', null, 6025025),
('ramayana-6-25-26', 26, 'Yuddha Kanda, Sarga 25, Verse 26', 'निहत्य रावणं संख्ये सर्वथा निशितैः शरैः।
प्रतिनेष्यति रामस्त्वामयोध्यामसितेक्षणे॥', 'nihatya rāvaṇaṃ saṃkhye sarvathā niśitaiḥ śaraiḥ
pratineṣyati rāmas tvām ayodhyām asitekṣaṇe', null, 6025026),
('ramayana-6-25-27', 27, 'Yuddha Kanda, Sarga 25, Verse 27', 'एतस्मिन्नन्तरे शब्दो भेरीशङ्खसमाकुलः।
श्रुतो वै सर्वसैन्यानां कम्पयन्धरणीतलम्॥', 'etasminn antare śabdo bherīśaṅkhasamākulaḥ
śruto vai sarvasainyānāṃ kampayan dharaṇītalam', null, 6025027),
('ramayana-6-25-28', 28, 'Yuddha Kanda, Sarga 25, Verse 28', 'श्रुत्वा तु तं वानरसैन्यशब्दं लङ्कागता राक्षसराजभृत्याः।
नष्टौजसो दैन्यपरीतचेष्टाः श्रेयो न पश्यन्ति नृपस्य दोषैः॥', 'śrutvā tu taṃ vānarasainyaśabdaṃ laṅkāgatā rākṣasarājabhṛtyāḥ
naṣṭaujaso dainyaparītaceṣṭāḥ śreyo na paśyanti nṛpasya doṣaiḥ', null, 6025028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 26 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-26-1', 1, 'Yuddha Kanda, Sarga 26, Verse 1', 'तेन शङ्खविमिश्रेण भेरीशब्देन राघवः।
उपयतो महाबाहू रामः परपुरंजयः॥', 'tena śaṅkhavimiśreṇa bherīśabdena rāghavaḥ
upayato mahābāhū rāmaḥ parapuraṃjayaḥ', null, 6026001),
('ramayana-6-26-2', 2, 'Yuddha Kanda, Sarga 26, Verse 2', 'तं निनादं निशम्याथ रावणो राक्षसेश्वरः।
मुहूर्तं ध्यानमास्थाय सचिवानभ्युदैक्षत॥', 'taṃ ninādaṃ niśamyātha rāvaṇo rākṣaseśvaraḥ
muhūrtaṃ dhyānam āsthāya sacivān abhyudaikṣata', null, 6026002),
('ramayana-6-26-3', 3, 'Yuddha Kanda, Sarga 26, Verse 3', 'अथ तान्सचिवांस्तत्र सर्वानाभाष्य रावणः।
सभां संनादयन्सर्वामित्युवाच महाबलः॥', 'atha tān sacivāṃs tatra sarvān ābhāṣya rāvaṇaḥ
sabhāṃ saṃnādayan sarvām ity uvāca mahābalaḥ', null, 6026003),
('ramayana-6-26-4', 4, 'Yuddha Kanda, Sarga 26, Verse 4', 'तरणं सागरस्यापि विक्रमं बलसंचयम्।
यदुक्तवन्तो रामस्य भवन्तस्तन्मया श्रुतम्।
भवतश्चाप्यहं वेद्मि युद्धे सत्यपराक्रमान्॥', 'taraṇaṃ sāgarasyāpi vikramaṃ balasaṃcayam
yad uktavanto rāmasya bhavantas tan mayā śrutam
bhavataś cāpy ahaṃ vedmi yuddhe satyaparākramān', null, 6026004),
('ramayana-6-26-5', 5, 'Yuddha Kanda, Sarga 26, Verse 5', 'ततस्तु सुमहाप्राज्ञो माल्यवान्नाम राक्षसः।
रावणस्य वचः श्रुत्वा मातुः पैतामहोऽब्रवीत्॥', 'tatas tu sumahāprājño mālyavān nāma rākṣasaḥ
rāvaṇasya vacaḥ śrutvā mātuḥ paitāmaho ''bravīt', null, 6026005),
('ramayana-6-26-6', 6, 'Yuddha Kanda, Sarga 26, Verse 6', 'विद्यास्वभिविनीतो यो राजा राजन्नयानुगः।
स शास्ति चिरमैश्वर्यमरींश्च कुरुते वशे॥', 'vidyāsv abhivinīto yo rājā rājan nayānugaḥ
sa śāsti ciram aiśvaryam arīṃś ca kurute vaśe', null, 6026006),
('ramayana-6-26-7', 7, 'Yuddha Kanda, Sarga 26, Verse 7', 'संदधानो हि कालेन विगृह्णंश्चारिभिः सह।
स्वपक्षवर्धनं कुर्वन्महदैश्वर्यमश्नुते॥', 'saṃdadhāno hi kālena vigṛhṇaṃś cāribhiḥ saha
svapakṣavardhanaṃ kurvan mahad aiśvaryam aśnute', null, 6026007),
('ramayana-6-26-8', 8, 'Yuddha Kanda, Sarga 26, Verse 8', 'हीयमानेन कर्तव्यो राज्ञा संधिः समेन च।
न शत्रुमवमन्येत ज्यायान्कुर्वीत विग्रहम्॥', 'hīyamānena kartavyo rājñā saṃdhiḥ samena ca
na śatrum avamanyeta jyāyān kurvīta vigraham', null, 6026008),
('ramayana-6-26-9', 9, 'Yuddha Kanda, Sarga 26, Verse 9', 'तन्मह्यं रोचते संधिः सह रामेण रावण।
यदर्थमभियुक्ताः स्म सीता तस्मै प्रदीयताम्॥', 'tan mahyaṃ rocate saṃdhiḥ saha rāmeṇa rāvaṇa
yadartham abhiyuktāḥ sma sītā tasmai pradīyatām', null, 6026009),
('ramayana-6-26-10', 10, 'Yuddha Kanda, Sarga 26, Verse 10', 'तस्य देवर्षयः सर्वे गन्धर्वाश्च जयैषिणः।
विरोधं मा गमस्तेन संधिस्ते तेन रोचताम्॥', 'tasya devarṣayaḥ sarve gandharvāś ca jayaiṣiṇaḥ
virodhaṃ mā gamas tena saṃdhis te tena rocatām', null, 6026010),
('ramayana-6-26-11', 11, 'Yuddha Kanda, Sarga 26, Verse 11', 'असृजद्भगवान्पक्षौ द्वावेव हि पितामहः।
सुराणामसुराणां च धर्माधर्मौ तदाश्रयौ॥', 'asṛjad bhagavān pakṣau dvāv eva hi pitāmahaḥ
surāṇām asurāṇāṃ ca dharmādharmau tadāśrayau', null, 6026011),
('ramayana-6-26-12', 12, 'Yuddha Kanda, Sarga 26, Verse 12', 'धर्मो हि श्रूयते पक्षः सुराणां च महात्मनाम्।
अधर्मो रक्षसं पक्षो ह्यसुराणां च रावण॥', 'dharmo hi śrūyate pakṣaḥ surāṇāṃ ca mahātmanām
adharmo rakṣasaṃ pakṣo hy asurāṇāṃ ca rāvaṇa', null, 6026012),
('ramayana-6-26-13', 13, 'Yuddha Kanda, Sarga 26, Verse 13', 'धर्मो वै ग्रसतेऽधर्मं ततः कृतमभूद्युगम्।
अधर्मो ग्रसते धर्मं ततस्तिष्यः प्रवर्तते॥', 'dharmo vai grasate ''dharmaṃ tataḥ kṛtam abhūd yugam
adharmo grasate dharmaṃ tatas tiṣyaḥ pravartate', null, 6026013),
('ramayana-6-26-14', 14, 'Yuddha Kanda, Sarga 26, Verse 14', 'तत्त्वया चरता लोकान्धर्मो विनिहतो महान्।
अधर्मः प्रगृहीतश्च तेनास्मद्बलिनः परे॥', 'tat tvayā caratā lokān dharmo vinihato mahān
adharmaḥ pragṛhītaś ca tenāsmadbalinaḥ pare', null, 6026014),
('ramayana-6-26-15', 15, 'Yuddha Kanda, Sarga 26, Verse 15', 'स प्रमादाद्विवृद्धस्तेऽधर्मोऽहिर्ग्रसते हि नः।
विवर्धयति पक्षं च सुराणां सुरभावनः॥', 'sa pramādād vivṛddhas te ''dharmo ''hir grasate hi naḥ
vivardhayati pakṣaṃ ca surāṇāṃ surabhāvanaḥ', null, 6026015),
('ramayana-6-26-16', 16, 'Yuddha Kanda, Sarga 26, Verse 16', 'विषयेषु प्रसक्तेन यत्किंचित्कारिणा त्वया।
ऋषीणामग्निकल्पानामुद्वेगो जनितो महान्।
तेषां प्रभावो दुर्धर्षः प्रदीप्त इव पावकः॥', 'viṣayeṣu prasaktena yatkiṃcitkāriṇā tvayā
ṛṣīṇām agnikalpānām udvego janito mahān
teṣāṃ prabhāvo durdharṣaḥ pradīpta iva pāvakaḥ', null, 6026016),
('ramayana-6-26-17', 17, 'Yuddha Kanda, Sarga 26, Verse 17', 'तपसा भावितात्मानो धर्मस्यानुग्रहे रताः।
मुख्यैर्यज्ञैर्यजन्त्येते नित्यं तैस्तैर्द्विजातयः॥', 'tapasā bhāvitātmāno dharmasyānugrahe ratāḥ
mukhyair yajñair yajanty ete nityaṃ tais tair dvijātayaḥ', null, 6026017),
('ramayana-6-26-18', 18, 'Yuddha Kanda, Sarga 26, Verse 18', 'जुह्वत्यग्नींश्च विधिवद्वेदांश्चोच्चैरधीयते।
अभिभूय च रक्षांसि ब्रह्मघोषानुदैरयन्।
दिशो विप्रद्रुताः सर्वे स्तनयित्नुरिवोष्णगे॥', 'juhvaty agnīṃś ca vidhivad vedāṃś coccair adhīyate
abhibhūya ca rakṣāṃsi brahmaghoṣān udairayan
diśo vipradrutāḥ sarve stanayitnur ivoṣṇage', null, 6026018),
('ramayana-6-26-19', 19, 'Yuddha Kanda, Sarga 26, Verse 19', 'ऋषीणामग्निकल्पानामग्निहोत्रसमुत्थितः।
आदत्ते रक्षसां तेजो धूमो व्याप्य दिशो दश॥', 'ṛṣīṇām agnikalpānām agnihotrasamutthitaḥ
ādatte rakṣasāṃ tejo dhūmo vyāpya diśo daśa', null, 6026019),
('ramayana-6-26-20', 20, 'Yuddha Kanda, Sarga 26, Verse 20', 'तेषु तेषु च देशेषु पुण्येषु च दृढव्रतैः।
चर्यमाणं तपस्तीव्रं संतापयति राक्षसान्॥', 'teṣu teṣu ca deśeṣu puṇyeṣu ca dṛḍhavrataiḥ
caryamāṇaṃ tapas tīvraṃ saṃtāpayati rākṣasān', null, 6026020),
('ramayana-6-26-21', 21, 'Yuddha Kanda, Sarga 26, Verse 21', 'उत्पातान्विविधान्दृष्ट्वा घोरान्बहुविधांस्तथा।
विनाशमनुपश्यामि सर्वेषां रक्षसामहम्॥', 'utpātān vividhān dṛṣṭvā ghorān bahuvidhāṃs tathā
vināśam anupaśyāmi sarveṣāṃ rakṣasām aham', null, 6026021),
('ramayana-6-26-22', 22, 'Yuddha Kanda, Sarga 26, Verse 22', 'खराभिस्तनिता घोरा मेघाः प्रतिभयंकरः।
शोणितेनाभिवर्षन्ति लङ्कामुष्णेन सर्वतः॥', 'kharābhis tanitā ghorā meghāḥ pratibhayaṃkaraḥ
śoṇitenābhivarṣanti laṅkām uṣṇena sarvataḥ', null, 6026022),
('ramayana-6-26-23', 23, 'Yuddha Kanda, Sarga 26, Verse 23', 'रुदतां वाहनानां च प्रपतन्त्यस्रबिन्दवः।
ध्वजा ध्वस्ता विवर्णाश्च न प्रभान्ति यथापुरम्॥', 'rudatāṃ vāhanānāṃ ca prapatanty asrabindavaḥ
dhvajā dhvastā vivarṇāś ca na prabhānti yathāpuram', null, 6026023),
('ramayana-6-26-24', 24, 'Yuddha Kanda, Sarga 26, Verse 24', 'व्याला गोमायवो गृध्रा वाशन्ति च सुभैरवम्।
प्रविश्य लङ्कामनिशं समवायांश्च कुर्वते॥', 'vyālā gomāyavo gṛdhrā vāśanti ca subhairavam
praviśya laṅkām aniśaṃ samavāyāṃś ca kurvate', null, 6026024),
('ramayana-6-26-25', 25, 'Yuddha Kanda, Sarga 26, Verse 25', 'कालिकाः पाण्डुरैर्दन्तैः प्रहसन्त्यग्रतः स्थिताः।
स्त्रियः स्वप्नेषु मुष्णन्त्यो गृहाणि प्रतिभाष्य च॥', 'kālikāḥ pāṇḍurair dantaiḥ prahasanty agrataḥ sthitāḥ
striyaḥ svapneṣu muṣṇantyo gṛhāṇi pratibhāṣya ca', null, 6026025),
('ramayana-6-26-26', 26, 'Yuddha Kanda, Sarga 26, Verse 26', 'गृहाणां बलिकर्माणि श्वानः पर्युपभुञ्जते।
खरा गोषु प्रजायन्ते मूषिका नकुलैः सह॥', 'gṛhāṇāṃ balikarmāṇi śvānaḥ paryupabhuñjate
kharā goṣu prajāyante mūṣikā nakulaiḥ saha', null, 6026026),
('ramayana-6-26-27', 27, 'Yuddha Kanda, Sarga 26, Verse 27', 'मार्जारा द्वीपिभिः सार्धं सूकराः शुनकैः सह।
किंनरा राक्षसैश्चापि समेयुर्मानुषैः सह॥', 'mārjārā dvīpibhiḥ sārdhaṃ sūkarāḥ śunakaiḥ saha
kiṃnarā rākṣasaiś cāpi sameyur mānuṣaiḥ saha', null, 6026027),
('ramayana-6-26-28', 28, 'Yuddha Kanda, Sarga 26, Verse 28', 'पाण्डुरा रक्तपादाश्च विहगाः कालचोदिताः।
राक्षसानां विनाशाय कपोता विचरन्ति च॥', 'pāṇḍurā raktapādāś ca vihagāḥ kālacoditāḥ
rākṣasānāṃ vināśāya kapotā vicaranti ca', null, 6026028),
('ramayana-6-26-29', 29, 'Yuddha Kanda, Sarga 26, Verse 29', 'चीकी कूचीति वाशन्त्यः शारिका वेश्मसु स्थिताः।
पतन्ति ग्रथिताश्चापि निर्जिताः कलहैषिणः॥', 'cīkī kūcīti vāśantyaḥ śārikā veśmasu sthitāḥ
patanti grathitāś cāpi nirjitāḥ kalahaiṣiṇaḥ', null, 6026029),
('ramayana-6-26-30', 30, 'Yuddha Kanda, Sarga 26, Verse 30', 'करालो विकटो मुण्डः पुरुषः कृष्णपिङ्गलः।
कालो गृहाणि सर्वेषां काले कालेऽन्ववेक्षते।
एतान्यन्यानि दुष्टानि निमित्तान्युत्पतन्ति च॥', 'karālo vikaṭo muṇḍaḥ puruṣaḥ kṛṣṇapiṅgalaḥ
kālo gṛhāṇi sarveṣāṃ kāle kāle ''nvavekṣate
etāny anyāni duṣṭāni nimittāny utpatanti ca', null, 6026030),
('ramayana-6-26-31', 31, 'Yuddha Kanda, Sarga 26, Verse 31', 'विष्णुं मन्यामहे रामं मानुषं देहमास्थितम्।
न हि मानुषमात्रोऽसौ राघवो दृढविक्रमः॥', 'viṣṇuṃ manyāmahe rāmaṃ mānuṣaṃ deham āsthitam
na hi mānuṣamātro ''sau rāghavo dṛḍhavikramaḥ', null, 6026031),
('ramayana-6-26-32', 32, 'Yuddha Kanda, Sarga 26, Verse 32', 'येन बद्धः समुद्रस्य स सेतुः परमाद्भुतः।
कुरुष्व नरराजेन संधिं रामेण रावण॥', 'yena baddhaḥ samudrasya sa setuḥ paramādbhutaḥ
kuruṣva nararājena saṃdhiṃ rāmeṇa rāvaṇa', null, 6026032),
('ramayana-6-26-33', 33, 'Yuddha Kanda, Sarga 26, Verse 33', 'इदं वचस्तत्र निगद्य माल्यवन्परीक्ष्य रक्षोऽधिपतेर्मनः पुनः।
अनुत्तमेषूत्तमपौरुषो बली बभूव तूष्णीं समवेक्ष्य रावणम्॥', 'idaṃ vacas tatra nigadya mālyavan parīkṣya rakṣo''dhipater manaḥ punaḥ
anuttameṣūttamapauruṣo balī babhūva tūṣṇīṃ samavekṣya rāvaṇam', null, 6026033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 27 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-27-1', 1, 'Yuddha Kanda, Sarga 27, Verse 1', 'तत्तु माल्यवतो वाक्यं हितमुक्तं दशाननः।
न मर्षयति दुष्टात्मा कालस्य वशमागतः॥', 'tat tu mālyavato vākyaṃ hitam uktaṃ daśānanaḥ
na marṣayati duṣṭātmā kālasya vaśam āgataḥ', null, 6027001),
('ramayana-6-27-2', 2, 'Yuddha Kanda, Sarga 27, Verse 2', 'स बद्ध्वा भ्रुकुटिं वक्त्रे क्रोधस्य वशमागतः।
अमर्षात्परिवृत्ताक्षो माल्यवन्तमथाब्रवीत्॥', 'sa baddhvā bhrukuṭiṃ vaktre krodhasya vaśam āgataḥ
amarṣāt parivṛttākṣo mālyavantam athābravīt', null, 6027002),
('ramayana-6-27-3', 3, 'Yuddha Kanda, Sarga 27, Verse 3', 'हितबुद्ध्या यदहितं वचः परुषमुच्यते।
परपक्षं प्रविश्यैव नैतच्छ्रोत्रगतं मम॥', 'hitabuddhyā yad ahitaṃ vacaḥ paruṣam ucyate
parapakṣaṃ praviśyaiva naitac chrotragataṃ mama', null, 6027003),
('ramayana-6-27-4', 4, 'Yuddha Kanda, Sarga 27, Verse 4', 'मानुषं कृपणं राममेकं शाखामृगाश्रयम्।
समर्थं मन्यसे केन त्यक्तं पित्रा वनालयम्॥', 'mānuṣaṃ kṛpaṇaṃ rāmam ekaṃ śākhāmṛgāśrayam
samarthaṃ manyase kena tyaktaṃ pitrā vanālayam', null, 6027004),
('ramayana-6-27-5', 5, 'Yuddha Kanda, Sarga 27, Verse 5', 'रक्षसामीश्वरं मां च देवतानां भयंकरम्।
हीनं मां मन्यसे केन अहीनं सर्वविक्रमैः॥', 'rakṣasām īśvaraṃ māṃ ca devatānāṃ bhayaṃkaram
hīnaṃ māṃ manyase kena ahīnaṃ sarvavikramaiḥ', null, 6027005),
('ramayana-6-27-6', 6, 'Yuddha Kanda, Sarga 27, Verse 6', 'वीरद्वेषेण वा शङ्के पक्षपातेन वा रिपोः।
त्वयाहं परुषाण्युक्तः परप्रोत्साहनेन वा॥', 'vīradveṣeṇa vā śaṅke pakṣapātena vā ripoḥ
tvayāhaṃ paruṣāṇy uktaḥ paraprotsāhanena vā', null, 6027006),
('ramayana-6-27-7', 7, 'Yuddha Kanda, Sarga 27, Verse 7', 'प्रभवन्तं पदस्थं हि परुषं कोऽभिधास्यति।
पण्डितः शास्त्रतत्त्वज्ञो विना प्रोत्साहनाद्रिपोः॥', 'prabhavantaṃ padasthaṃ hi paruṣaṃ ko ''bhidhāsyati
paṇḍitaḥ śāstratattvajño vinā protsāhanād ripoḥ', null, 6027007),
('ramayana-6-27-8', 8, 'Yuddha Kanda, Sarga 27, Verse 8', 'आनीय च वनात्सीतां पद्महीनामिव श्रियम्।
किमर्थं प्रतिदास्यामि राघवस्य भयादहम्॥', 'ānīya ca vanāt sītāṃ padmahīnām iva śriyam
kimarthaṃ pratidāsyāmi rāghavasya bhayād aham', null, 6027008),
('ramayana-6-27-9', 9, 'Yuddha Kanda, Sarga 27, Verse 9', 'वृतं वानरकोटीभिः ससुग्रीवं सलक्ष्मणम्।
पश्य कैश्चिदहोभिस्त्वं राघवं निहतं मया॥', 'vṛtaṃ vānarakoṭībhiḥ sasugrīvaṃ salakṣmaṇam
paśya kaiś cid ahobhis tvaṃ rāghavaṃ nihataṃ mayā', null, 6027009),
('ramayana-6-27-10', 10, 'Yuddha Kanda, Sarga 27, Verse 10', 'द्वन्द्वे यस्य न तिष्ठन्ति दैवतान्यपि संयुगे।
स कस्माद्रावणो युद्धे भयमाहारयिष्यति॥', 'dvandve yasya na tiṣṭhanti daivatāny api saṃyuge
sa kasmād rāvaṇo yuddhe bhayam āhārayiṣyati', null, 6027010),
('ramayana-6-27-11', 11, 'Yuddha Kanda, Sarga 27, Verse 11', 'द्विधा भज्येयमप्येवं न नमेयं तु कस्य चित्।
एष मे सहजो दोषः स्वभावो दुरतिक्रमः॥', 'dvidhā bhajyeyam apy evaṃ na nameyaṃ tu kasya cit
eṣa me sahajo doṣaḥ svabhāvo duratikramaḥ', null, 6027011),
('ramayana-6-27-12', 12, 'Yuddha Kanda, Sarga 27, Verse 12', 'यदि तावत्समुद्रे तु सेतुर्बद्धो यदृच्छया।
रामेण विस्मयः कोऽत्र येन ते भयमागतम्॥', 'yadi tāvat samudre tu setur baddho yadṛcchayā
rāmeṇa vismayaḥ ko ''tra yena te bhayam āgatam', null, 6027012),
('ramayana-6-27-13', 13, 'Yuddha Kanda, Sarga 27, Verse 13', 'स तु तीर्त्वार्णवं रामः सह वानरसेनया।
प्रतिजानामि ते सत्यं न जीवन्प्रतियास्यति॥', 'sa tu tīrtvārṇavaṃ rāmaḥ saha vānarasenayā
pratijānāmi te satyaṃ na jīvan pratiyāsyati', null, 6027013),
('ramayana-6-27-14', 14, 'Yuddha Kanda, Sarga 27, Verse 14', 'एवं ब्रुवाणं संरब्धं रुष्टं विज्ञाय रावणम्।
व्रीडितो माल्यवान्वाक्यं नोत्तरं प्रत्यपद्यत॥', 'evaṃ bruvāṇaṃ saṃrabdhaṃ ruṣṭaṃ vijñāya rāvaṇam
vrīḍito mālyavān vākyaṃ nottaraṃ pratyapadyata', null, 6027014),
('ramayana-6-27-15', 15, 'Yuddha Kanda, Sarga 27, Verse 15', 'जयाशिषा च राजानं वर्धयित्वा यथोचितम्।
माल्यवानभ्यनुज्ञातो जगाम स्वं निवेशनम्॥', 'jayāśiṣā ca rājānaṃ vardhayitvā yathocitam
mālyavān abhyanujñāto jagāma svaṃ niveśanam', null, 6027015),
('ramayana-6-27-16', 16, 'Yuddha Kanda, Sarga 27, Verse 16', 'रावणस्तु सहामात्यो मन्त्रयित्वा विमृश्य च।
लङ्कायामतुलां गुप्तिं कारयामास राक्षसः॥', 'rāvaṇas tu sahāmātyo mantrayitvā vimṛśya ca
laṅkāyām atulāṃ guptiṃ kārayām āsa rākṣasaḥ', null, 6027016),
('ramayana-6-27-17', 17, 'Yuddha Kanda, Sarga 27, Verse 17', 'व्यादिदेश च पूर्वस्यां प्रहस्तं द्वारि राक्षसं।
दक्षिणस्यां महावीर्यौ महापार्श्व महोदरौ॥', 'vyādideśa ca pūrvasyāṃ prahastaṃ dvāri rākṣasaṃ
dakṣiṇasyāṃ mahāvīryau mahāpārśva mahodarau', null, 6027017),
('ramayana-6-27-18', 18, 'Yuddha Kanda, Sarga 27, Verse 18', 'पश्चिमायामथो द्वारि पुत्रमिन्द्रजितं तथा।
व्यादिदेश महामायं राक्षसैर्बहुभिर्वृतम्॥', 'paścimāyām atho dvāri putram indrajitaṃ tathā
vyādideśa mahāmāyaṃ rākṣasair bahubhir vṛtam', null, 6027018),
('ramayana-6-27-19', 19, 'Yuddha Kanda, Sarga 27, Verse 19', 'उत्तरस्यां पुरद्वारि व्यादिश्य शुकसारणौ।
स्वयं चात्र भविष्यामि मन्त्रिणस्तानुवाच ह॥', 'uttarasyāṃ puradvāri vyādiśya śukasāraṇau
svayaṃ cātra bhaviṣyāmi mantriṇas tān uvāca ha', null, 6027019),
('ramayana-6-27-20', 20, 'Yuddha Kanda, Sarga 27, Verse 20', 'राक्षसं तु विरूपाक्षं महावीर्यपराक्रमम्।
मध्यमेऽस्थापयद्गुल्मे बहुभिः सह राक्षसैः॥', 'rākṣasaṃ tu virūpākṣaṃ mahāvīryaparākramam
madhyame ''sthāpayad gulme bahubhiḥ saha rākṣasaiḥ', null, 6027020),
('ramayana-6-27-21', 21, 'Yuddha Kanda, Sarga 27, Verse 21', 'एवंविधानं लङ्कायां कृत्वा राक्षसपुंगवः।
मेने कृतार्थमात्मानं कृतान्तवशमागतः॥', 'evaṃvidhānaṃ laṅkāyāṃ kṛtvā rākṣasapuṃgavaḥ
mene kṛtārtham ātmānaṃ kṛtāntavaśam āgataḥ', null, 6027021),
('ramayana-6-27-22', 22, 'Yuddha Kanda, Sarga 27, Verse 22', 'विसर्जयामास ततः स मन्त्रिणो विधानमाज्ञाप्य पुरस्य पुष्कलम्।
जयाशिषा मन्त्रगणेन पूजितो विवेश सोऽन्तःपुरमृद्धिमन्महत्॥', 'visarjayām āsa tataḥ sa mantriṇo vidhānam ājñāpya purasya puṣkalam
jayāśiṣā mantragaṇena pūjito viveśa so ''ntaḥpuram ṛddhiman mahat', null, 6027022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 28 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-28-1', 1, 'Yuddha Kanda, Sarga 28, Verse 1', 'नरवानरराजौ तौ स च वायुसुतः कपिः।
जाम्बवानृक्षराजश्च राक्षसश्च विभीषणः॥', 'naravānararājau tau sa ca vāyusutaḥ kapiḥ
jāmbavān ṛkṣarājaś ca rākṣasaś ca vibhīṣaṇaḥ', null, 6028001),
('ramayana-6-28-2', 2, 'Yuddha Kanda, Sarga 28, Verse 2', 'अङ्गदो वालिपुत्रश्च सौमित्रिः शरभः कपिः।
सुषेणः सहदायादो मैन्दो द्विविद एव च॥', 'aṅgado vāliputraś ca saumitriḥ śarabhaḥ kapiḥ
suṣeṇaḥ sahadāyādo maindo dvivida eva ca', null, 6028002),
('ramayana-6-28-3', 3, 'Yuddha Kanda, Sarga 28, Verse 3', 'गजो गवाक्षो कुमुदो नलोऽथ पनसस्तथा।
अमित्रविषयं प्राप्ताः समवेताः समर्थयन्॥', 'gajo gavākṣo kumudo nalo ''tha panasas tathā
amitraviṣayaṃ prāptāḥ samavetāḥ samarthayan', null, 6028003),
('ramayana-6-28-4', 4, 'Yuddha Kanda, Sarga 28, Verse 4', 'इयं सा लक्ष्यते लङ्का पुरी रावणपालिता।
सासुरोरगगन्धर्वैरमरैरपि दुर्जया॥', 'iyaṃ sā lakṣyate laṅkā purī rāvaṇapālitā
sāsuroragagandharvair amarair api durjayā', null, 6028004),
('ramayana-6-28-5', 5, 'Yuddha Kanda, Sarga 28, Verse 5', 'कार्यसिद्धिं पुरस्कृत्य मन्त्रयध्वं विनिर्णये।
नित्यं संनिहितो ह्यत्र रावणो राक्षसाधिपः॥', 'kāryasiddhiṃ puraskṛtya mantrayadhvaṃ vinirṇaye
nityaṃ saṃnihito hy atra rāvaṇo rākṣasādhipaḥ', null, 6028005),
('ramayana-6-28-6', 6, 'Yuddha Kanda, Sarga 28, Verse 6', 'तथा तेषु ब्रुवाणेषु रावणावरजोऽब्रवीत्।
वाक्यमग्राम्यपदवत्पुष्कलार्थं विभीषणः॥', 'tathā teṣu bruvāṇeṣu rāvaṇāvarajo ''bravīt
vākyam agrāmyapadavat puṣkalārthaṃ vibhīṣaṇaḥ', null, 6028006),
('ramayana-6-28-7', 7, 'Yuddha Kanda, Sarga 28, Verse 7', 'अनलः शरभश्चैव संपातिः प्रघसस्तथा।
गत्वा लङ्कां ममामात्याः पुरीं पुनरिहागताः॥', 'analaḥ śarabhaś caiva saṃpātiḥ praghasas tathā
gatvā laṅkāṃ mamāmātyāḥ purīṃ punar ihāgatāḥ', null, 6028007),
('ramayana-6-28-8', 8, 'Yuddha Kanda, Sarga 28, Verse 8', 'भूत्वा शकुनयः सर्वे प्रविष्टाश्च रिपोर्बलम्।
विधानं विहितं यच्च तद्दृष्ट्वा समुपस्थिताः॥', 'bhūtvā śakunayaḥ sarve praviṣṭāś ca ripor balam
vidhānaṃ vihitaṃ yac ca tad dṛṣṭvā samupasthitāḥ', null, 6028008),
('ramayana-6-28-9', 9, 'Yuddha Kanda, Sarga 28, Verse 9', 'संविधानं यथाहुस्ते रावणस्य दुरात्मनः।
राम तद्ब्रुवतः सर्वं यथातथ्येन मे शृणु॥', 'saṃvidhānaṃ yathāhus te rāvaṇasya durātmanaḥ
rāma tad bruvataḥ sarvaṃ yathātathyena me śṛṇu', null, 6028009),
('ramayana-6-28-10', 10, 'Yuddha Kanda, Sarga 28, Verse 10', 'पूर्वं प्रहस्तः सबलो द्वारमासाद्य तिष्ठति।
दक्षिणं च महावीर्यौ महापार्श्वमहोदरौ॥', 'pūrvaṃ prahastaḥ sabalo dvāram āsādya tiṣṭhati
dakṣiṇaṃ ca mahāvīryau mahāpārśvamahodarau', null, 6028010),
('ramayana-6-28-11', 11, 'Yuddha Kanda, Sarga 28, Verse 11', 'इन्द्रजित्पश्चिमद्वारं राक्षसैर्बहुभिर्वृतः।
पट्टसासिधनुष्मद्भिः शूलमुद्गरपाणिभिः॥', 'indrajit paścimadvāraṃ rākṣasair bahubhir vṛtaḥ
paṭṭasāsidhanuṣmadbhiḥ śūlamudgarapāṇibhiḥ', null, 6028011),
('ramayana-6-28-12', 12, 'Yuddha Kanda, Sarga 28, Verse 12', 'नानाप्रहरणैः शूरैरावृतो रावणात्मजः।
राक्षसानां सहस्रैस्तु बहुभिः शस्त्रपाणिभिः॥', 'nānāpraharaṇaiḥ śūrair āvṛto rāvaṇātmajaḥ
rākṣasānāṃ sahasrais tu bahubhiḥ śastrapāṇibhiḥ', null, 6028012),
('ramayana-6-28-13', 13, 'Yuddha Kanda, Sarga 28, Verse 13', 'युक्तः परमसंविग्नो राक्षसैर्बहुभिर्वृतः।
उत्तरं नगरद्वारं रावणः स्वयमास्थितः॥', 'yuktaḥ paramasaṃvigno rākṣasair bahubhir vṛtaḥ
uttaraṃ nagaradvāraṃ rāvaṇaḥ svayam āsthitaḥ', null, 6028013),
('ramayana-6-28-14', 14, 'Yuddha Kanda, Sarga 28, Verse 14', 'विरूपाक्षस्तु महता शूलखड्गधनुष्मता।
बलेन राक्षसैः सार्धं मध्यमं गुल्ममास्थितः॥', 'virūpākṣas tu mahatā śūlakhaḍgadhanuṣmatā
balena rākṣasaiḥ sārdhaṃ madhyamaṃ gulmam āsthitaḥ', null, 6028014),
('ramayana-6-28-15', 15, 'Yuddha Kanda, Sarga 28, Verse 15', 'एतानेवंविधान्गुल्मांल्लङ्कायां समुदीक्ष्य ते।
मामकाः सचिवाः सर्वे शीघ्रं पुनरिहागताः॥', 'etān evaṃvidhān gulmāṃl laṅkāyāṃ samudīkṣya te
māmakāḥ sacivāḥ sarve śīghraṃ punar ihāgatāḥ', null, 6028015),
('ramayana-6-28-16', 16, 'Yuddha Kanda, Sarga 28, Verse 16', 'गजानां च सहस्रं च रथानामयुतं पुरे।
हयानामयुते द्वे च साग्रकोटी च रक्षसाम्॥', 'gajānāṃ ca sahasraṃ ca rathānām ayutaṃ pure
hayānām ayute dve ca sāgrakoṭī ca rakṣasām', null, 6028016),
('ramayana-6-28-17', 17, 'Yuddha Kanda, Sarga 28, Verse 17', 'विक्रान्ता बलवन्तश्च संयुगेष्वाततायिनः।
इष्टा राक्षसराजस्य नित्यमेते निशाचराः॥', 'vikrāntā balavantaś ca saṃyugeṣv ātatāyinaḥ
iṣṭā rākṣasarājasya nityam ete niśācarāḥ', null, 6028017),
('ramayana-6-28-18', 18, 'Yuddha Kanda, Sarga 28, Verse 18', 'एकैकस्यात्र युद्धार्थे राक्षसस्य विशां पते।
परिवारः सहस्राणां सहस्रमुपतिष्ठते॥', 'ekaikasyātra yuddhārthe rākṣasasya viśāṃ pate
parivāraḥ sahasrāṇāṃ sahasram upatiṣṭhate', null, 6028018),
('ramayana-6-28-19', 19, 'Yuddha Kanda, Sarga 28, Verse 19', 'एतां प्रवृत्तिं लङ्कायां मन्त्रिप्रोक्तं विभीषणः।
रामं कमलपत्राक्षमिदमुत्तरमब्रवीत्॥', 'etāṃ pravṛttiṃ laṅkāyāṃ mantriproktaṃ vibhīṣaṇaḥ
rāmaṃ kamalapatrākṣam idam uttaram abravīt', null, 6028019),
('ramayana-6-28-20', 20, 'Yuddha Kanda, Sarga 28, Verse 20', 'कुबेरं तु यदा राम रावणः प्रत्ययुध्यत।
षष्टिः शतसहस्राणि तदा निर्यान्ति राक्षसाः॥', 'kuberaṃ tu yadā rāma rāvaṇaḥ pratyayudhyata
ṣaṣṭiḥ śatasahasrāṇi tadā niryānti rākṣasāḥ', null, 6028020),
('ramayana-6-28-21', 21, 'Yuddha Kanda, Sarga 28, Verse 21', 'पराक्रमेण वीर्येण तेजसा सत्त्वगौरवात्।
सदृशा योऽत्र दर्पेण रावणस्य दुरात्मनः॥', 'parākrameṇa vīryeṇa tejasā sattvagauravāt
sadṛśā yo ''tra darpeṇa rāvaṇasya durātmanaḥ', null, 6028021),
('ramayana-6-28-22', 22, 'Yuddha Kanda, Sarga 28, Verse 22', 'अत्र मन्युर्न कर्तव्यो रोषये त्वां न भीषये।
समर्थो ह्यसि वीर्येण सुराणामपि निग्रहे॥', 'atra manyur na kartavyo roṣaye tvāṃ na bhīṣaye
samartho hy asi vīryeṇa surāṇām api nigrahe', null, 6028022),
('ramayana-6-28-23', 23, 'Yuddha Kanda, Sarga 28, Verse 23', 'तद्भवांश्चतुरङ्गेण बलेन महता वृतः।
व्यूह्येदं वानरानीकं निर्मथिष्यसि रावणम्॥', 'tad bhavāṃś caturaṅgeṇa balena mahatā vṛtaḥ
vyūhyedaṃ vānarānīkaṃ nirmathiṣyasi rāvaṇam', null, 6028023),
('ramayana-6-28-24', 24, 'Yuddha Kanda, Sarga 28, Verse 24', 'रावणावरजे वाक्यमेवं ब्रुवति राघवः।
शत्रूणां प्रतिघातार्थमिदं वचनमब्रवीत्॥', 'rāvaṇāvaraje vākyam evaṃ bruvati rāghavaḥ
śatrūṇāṃ pratighātārtham idaṃ vacanam abravīt', null, 6028024),
('ramayana-6-28-25', 25, 'Yuddha Kanda, Sarga 28, Verse 25', 'पूर्वद्वारे तु लङ्काया नीलो वानरपुंगवः।
प्रहस्तं प्रतियोद्धा स्याद्वानरैर्बहुभिर्वृतः॥', 'pūrvadvāre tu laṅkāyā nīlo vānarapuṃgavaḥ
prahastaṃ pratiyoddhā syād vānarair bahubhir vṛtaḥ', null, 6028025),
('ramayana-6-28-26', 26, 'Yuddha Kanda, Sarga 28, Verse 26', 'अङ्गदो वालिपुत्रस्तु बलेन महता वृतः।
दक्षिणे बाधतां द्वारे महापार्श्वमहोदरौ॥', 'aṅgado vāliputras tu balena mahatā vṛtaḥ
dakṣiṇe bādhatāṃ dvāre mahāpārśvamahodarau', null, 6028026),
('ramayana-6-28-27', 27, 'Yuddha Kanda, Sarga 28, Verse 27', 'हनूमान्पश्चिमद्वारं निपीड्य पवनात्मजः।
प्रविशत्वप्रमेयात्मा बहुभिः कपिभिर्वृतः॥', 'hanūmān paścimadvāraṃ nipīḍya pavanātmajaḥ
praviśatv aprameyātmā bahubhiḥ kapibhir vṛtaḥ', null, 6028027),
('ramayana-6-28-28', 28, 'Yuddha Kanda, Sarga 28, Verse 28', 'दैत्यदानवसंघानामृषीणां च महात्मनाम्।
विप्रकारप्रियः क्षुद्रो वरदानबलान्वितः॥', 'daityadānavasaṃghānām ṛṣīṇāṃ ca mahātmanām
viprakārapriyaḥ kṣudro varadānabalānvitaḥ', null, 6028028),
('ramayana-6-28-29', 29, 'Yuddha Kanda, Sarga 28, Verse 29', 'परिक्रामति यः सर्वांल्लोकान्संतापयन्प्रजाः।
तस्याहं राक्षसेन्द्रस्य स्वयमेव वधे धृतः॥', 'parikrāmati yaḥ sarvāṃl lokān saṃtāpayan prajāḥ
tasyāhaṃ rākṣasendrasya svayam eva vadhe dhṛtaḥ', null, 6028029),
('ramayana-6-28-30', 30, 'Yuddha Kanda, Sarga 28, Verse 30', 'उत्तरं नगरद्वारमहं सौमित्रिणा सह।
निपीड्याभिप्रवेक्ष्यामि सबलो यत्र रावणः॥', 'uttaraṃ nagaradvāram ahaṃ saumitriṇā saha
nipīḍyābhipravekṣyāmi sabalo yatra rāvaṇaḥ', null, 6028030),
('ramayana-6-28-31', 31, 'Yuddha Kanda, Sarga 28, Verse 31', 'वानरेन्द्रश्च बलवानृक्षराजश्च जाम्बवान्।
राक्षसेन्द्रानुजश्चैव गुल्मे भवतु मध्यमे॥', 'vānarendraś ca balavān ṛkṣarājaś ca jāmbavān
rākṣasendrānujaś caiva gulme bhavatu madhyame', null, 6028031),
('ramayana-6-28-32', 32, 'Yuddha Kanda, Sarga 28, Verse 32', 'न चैव मानुषं रूपं कार्यं हरिभिराहवे।
एषा भवतु नः संज्ञा युद्धेऽस्मिन्वानरे बले॥', 'na caiva mānuṣaṃ rūpaṃ kāryaṃ haribhir āhave
eṣā bhavatu naḥ saṃjñā yuddhe ''smin vānare bale', null, 6028032),
('ramayana-6-28-33', 33, 'Yuddha Kanda, Sarga 28, Verse 33', 'वानरा एव निश्चिह्नं स्वजनेऽस्मिन्भविष्यति।
वयं तु मानुषेणैव सप्त योत्स्यामहे परान्॥', 'vānarā eva niścihnaṃ svajane ''smin bhaviṣyati
vayaṃ tu mānuṣeṇaiva sapta yotsyāmahe parān', null, 6028033),
('ramayana-6-28-34', 34, 'Yuddha Kanda, Sarga 28, Verse 34', 'अहमेव सह भ्रात्रा लक्ष्मणेन महौजसा।
आत्मना पञ्चमश्चायं सखा मम विभीषणः॥', 'aham eva saha bhrātrā lakṣmaṇena mahaujasā
ātmanā pañcamaś cāyaṃ sakhā mama vibhīṣaṇaḥ', null, 6028034),
('ramayana-6-28-35', 35, 'Yuddha Kanda, Sarga 28, Verse 35', 'स रामः कार्यसिद्ध्यर्थमेवमुक्त्वा विभीषणम्।
सुवेलारोहणे बुद्धिं चकार मतिमान्मतिम्॥', 'sa rāmaḥ kāryasiddhyartham evam uktvā vibhīṣaṇam
suvelārohaṇe buddhiṃ cakāra matimān matim', null, 6028035),
('ramayana-6-28-36', 36, 'Yuddha Kanda, Sarga 28, Verse 36', 'ततस्तु रामो महता बलेन प्रच्छाद्य सर्वां पृथिवीं महात्मा।
प्रहृष्टरूपोऽभिजगाम लङ्कां कृत्वा मतिं सोऽरिवधे महात्मा॥', 'tatas tu rāmo mahatā balena pracchādya sarvāṃ pṛthivīṃ mahātmā
prahṛṣṭarūpo ''bhijagāma laṅkāṃ kṛtvā matiṃ so ''rivadhe mahātmā', null, 6028036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 29 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-29-1', 1, 'Yuddha Kanda, Sarga 29, Verse 1', 'स तु कृत्वा सुवेलस्य मतिमारोहणं प्रति।
लक्ष्मणानुगतो रामः सुग्रीवमिदमब्रवीत्॥', 'sa tu kṛtvā suvelasya matim ārohaṇaṃ prati
lakṣmaṇānugato rāmaḥ sugrīvam idam abravīt', null, 6029001),
('ramayana-6-29-2', 2, 'Yuddha Kanda, Sarga 29, Verse 2', 'विभीषणं च धर्मज्ञमनुरक्तं निशाचरम्।
मन्त्रज्ञं च विधिज्ञं च श्लक्ष्णया परया गिरा॥', 'vibhīṣaṇaṃ ca dharmajñam anuraktaṃ niśācaram
mantrajñaṃ ca vidhijñaṃ ca ślakṣṇayā parayā girā', null, 6029002),
('ramayana-6-29-3', 3, 'Yuddha Kanda, Sarga 29, Verse 3', 'सुवेलं साधु शैलेन्द्रमिमं धातुशतैश्चितम्।
अध्यारोहामहे सर्वे वत्स्यामोऽत्र निशामिमाम्॥', 'suvelaṃ sādhu śailendram imaṃ dhātuśataiś citam
adhyārohāmahe sarve vatsyāmo ''tra niśām imām', null, 6029003),
('ramayana-6-29-4', 4, 'Yuddha Kanda, Sarga 29, Verse 4', 'लङ्कां चालोकयिष्यामो निलयं तस्य रक्षसः।
येन मे मरणान्ताय हृता भार्या दुरात्मना॥', 'laṅkāṃ cālokayiṣyāmo nilayaṃ tasya rakṣasaḥ
yena me maraṇāntāya hṛtā bhāryā durātmanā', null, 6029004),
('ramayana-6-29-5', 5, 'Yuddha Kanda, Sarga 29, Verse 5', 'येन धर्मो न विज्ञातो न वृत्तं न कुलं तथा।
राक्षस्या नीचया बुद्ध्या येन तद्गर्हितं कृतम्॥', 'yena dharmo na vijñāto na vṛttaṃ na kulaṃ tathā
rākṣasyā nīcayā buddhyā yena tad garhitaṃ kṛtam', null, 6029005),
('ramayana-6-29-6', 6, 'Yuddha Kanda, Sarga 29, Verse 6', 'यस्मिन्मे वर्धते रोषः कीर्तिते राक्षसाधमे।
यस्यापराधान्नीचस्य वधं द्रक्ष्यामि रक्षसाम्॥', 'yasmin me vardhate roṣaḥ kīrtite rākṣasādhame
yasyāparādhān nīcasya vadhaṃ drakṣyāmi rakṣasām', null, 6029006),
('ramayana-6-29-7', 7, 'Yuddha Kanda, Sarga 29, Verse 7', 'एको हि कुरुते पापं कालपाशवशं गतः।
नीचेनात्मापचारेण कुलं तेन विनश्यति॥', 'eko hi kurute pāpaṃ kālapāśavaśaṃ gataḥ
nīcenātmāpacāreṇa kulaṃ tena vinaśyati', null, 6029007),
('ramayana-6-29-8', 8, 'Yuddha Kanda, Sarga 29, Verse 8', 'एवं संमन्त्रयन्नेव सक्रोधो रावणं प्रति।
रामः सुवेलं वासाय चित्रसानुमुपारुहत्॥', 'evaṃ saṃmantrayann eva sakrodho rāvaṇaṃ prati
rāmaḥ suvelaṃ vāsāya citrasānum upāruhat', null, 6029008),
('ramayana-6-29-9', 9, 'Yuddha Kanda, Sarga 29, Verse 9', 'पृष्ठतो लक्ष्मण चैनमन्वगच्छत्समाहितः।
सशरं चापमुद्यम्य सुमहद्विक्रमे रतः॥', 'pṛṣṭhato lakṣmaṇa cainam anvagacchat samāhitaḥ
saśaraṃ cāpam udyamya sumahad vikrame rataḥ', null, 6029009),
('ramayana-6-29-10', 10, 'Yuddha Kanda, Sarga 29, Verse 10', 'तमन्वरोहत्सुग्रीवः सामात्यः सविभीषणः।
हनूमानङ्गदो नीलो मैन्दो द्विविद एव च॥', 'tam anvarohat sugrīvaḥ sāmātyaḥ savibhīṣaṇaḥ
hanūmān aṅgado nīlo maindo dvivida eva ca', null, 6029010),
('ramayana-6-29-11', 11, 'Yuddha Kanda, Sarga 29, Verse 11', 'गजो गवाक्षो गवयः शरभो गन्धमादनः।
पनसः कुमुदश्चैव हरो रम्भश्च यूथपः॥', 'gajo gavākṣo gavayaḥ śarabho gandhamādanaḥ
panasaḥ kumudaś caiva haro rambhaś ca yūthapaḥ', null, 6029011),
('ramayana-6-29-12', 12, 'Yuddha Kanda, Sarga 29, Verse 12', 'एते चान्ये च बहवो वानराः शीघ्रगामिनः।
ते वायुवेगप्रवणास्तं गिरिं गिरिचारिणः।
अध्यारोहन्त शतशः सुवेलं यत्र राघवः॥', 'ete cānye ca bahavo vānarāḥ śīghragāminaḥ
te vāyuvegapravaṇās taṃ giriṃ giricāriṇaḥ
adhyārohanta śataśaḥ suvelaṃ yatra rāghavaḥ', null, 6029012),
('ramayana-6-29-13', 13, 'Yuddha Kanda, Sarga 29, Verse 13', 'ते त्वदीर्घेण कालेन गिरिमारुह्य सर्वतः।
ददृशुः शिखरे तस्य विषक्तामिव खे पुरीम्॥', 'te tv adīrgheṇa kālena girim āruhya sarvataḥ
dadṛśuḥ śikhare tasya viṣaktām iva khe purīm', null, 6029013),
('ramayana-6-29-14', 14, 'Yuddha Kanda, Sarga 29, Verse 14', 'तां शुभां प्रवरद्वारां प्राकारवरशोभिताम्।
लङ्कां राक्षससंपूर्णां ददृशुर्हरियूथपाः॥', 'tāṃ śubhāṃ pravaradvārāṃ prākāravaraśobhitām
laṅkāṃ rākṣasasaṃpūrṇāṃ dadṛśur hariyūthapāḥ', null, 6029014),
('ramayana-6-29-15', 15, 'Yuddha Kanda, Sarga 29, Verse 15', 'प्राकारचयसंस्थैश्च तथा नीलैर्निशाचरैः।
ददृशुस्ते हरिश्रेष्ठाः प्राकारमपरं कृतम्॥', 'prākāracayasaṃsthaiś ca tathā nīlair niśācaraiḥ
dadṛśus te hariśreṣṭhāḥ prākāram aparaṃ kṛtam', null, 6029015),
('ramayana-6-29-16', 16, 'Yuddha Kanda, Sarga 29, Verse 16', 'ते दृष्ट्वा वानराः सर्वे राक्षसान्युद्धकाङ्क्षिणः।
मुमुचुर्विपुलान्नादांस्तत्र रामस्य पश्यतः॥', 'te dṛṣṭvā vānarāḥ sarve rākṣasān yuddhakāṅkṣiṇaḥ
mumucur vipulān nādāṃs tatra rāmasya paśyataḥ', null, 6029016),
('ramayana-6-29-17', 17, 'Yuddha Kanda, Sarga 29, Verse 17', 'ततोऽस्तमगमत्सूर्यः संध्यया प्रतिरञ्जितः।
पूर्णचन्द्रप्रदीपा च क्षपा समभिवर्तते॥', 'tato ''stam agamat sūryaḥ saṃdhyayā pratirañjitaḥ
pūrṇacandrapradīpā ca kṣapā samabhivartate', null, 6029017),
('ramayana-6-29-18', 18, 'Yuddha Kanda, Sarga 29, Verse 18', 'ततः स रामो हरिवाहिनीपतिर्विभीषणेन प्रतिनन्द्य सत्कृतः।
सलक्ष्मणो यूथपयूथसंवृतः सुवेल पृष्ठे न्यवसद्यथासुखम्॥', 'tataḥ sa rāmo harivāhinīpatir vibhīṣaṇena pratinandya satkṛtaḥ
salakṣmaṇo yūthapayūthasaṃvṛtaḥ suvela pṛṣṭhe nyavasad yathāsukham', null, 6029018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 30 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-30-1', 1, 'Yuddha Kanda, Sarga 30, Verse 1', 'तां रात्रिमुषितास्तत्र सुवेले हरिपुंगवाः।
लङ्कायां ददृशुर्वीरा वनान्युपवनानि च॥', 'tāṃ rātrim uṣitās tatra suvele haripuṃgavāḥ
laṅkāyāṃ dadṛśur vīrā vanāny upavanāni ca', null, 6030001),
('ramayana-6-30-2', 2, 'Yuddha Kanda, Sarga 30, Verse 2', 'समसौम्यानि रम्याणि विशालान्यायतानि च।
दृष्टिरम्याणि ते दृष्ट्वा बभूवुर्जातविस्मयाः॥', 'samasaumyāni ramyāṇi viśālāny āyatāni ca
dṛṣṭiramyāṇi te dṛṣṭvā babhūvur jātavismayāḥ', null, 6030002),
('ramayana-6-30-3', 3, 'Yuddha Kanda, Sarga 30, Verse 3', 'चम्पकाशोकपुंनागसालतालसमाकुला।
तमालवनसंछन्ना नागमालासमावृता॥', 'campakāśokapuṃnāgasālatālasamākulā
tamālavanasaṃchannā nāgamālāsamāvṛtā', null, 6030003),
('ramayana-6-30-4', 4, 'Yuddha Kanda, Sarga 30, Verse 4', 'हिन्तालैरर्जुनैर्नीपैः सप्तपर्णैश्च पुष्पितैः।
तिलकैः कर्णिकारैश्च पटालैश्च समन्ततः॥', 'hintālair arjunair nīpaiḥ saptaparṇaiś ca puṣpitaiḥ
tilakaiḥ karṇikāraiś ca paṭālaiś ca samantataḥ', null, 6030004),
('ramayana-6-30-5', 5, 'Yuddha Kanda, Sarga 30, Verse 5', 'शुशुभे पुष्पिताग्रैश्च लतापरिगतैर्द्रुमैः।
लङ्का बहुविधैर्दिव्यैर्यथेन्द्रस्यामरावती॥', 'śuśubhe puṣpitāgraiś ca latāparigatair drumaiḥ
laṅkā bahuvidhair divyair yathendrasyāmarāvatī', null, 6030005),
('ramayana-6-30-6', 6, 'Yuddha Kanda, Sarga 30, Verse 6', 'विचित्रकुसुमोपेतै रक्तकोमलपल्लवैः।
शाद्वलैश्च तथा नीलैश्चित्राभिर्वनराजिभिः॥', 'vicitrakusumopetai raktakomalapallavaiḥ
śādvalaiś ca tathā nīlaiś citrābhir vanarājibhiḥ', null, 6030006),
('ramayana-6-30-7', 7, 'Yuddha Kanda, Sarga 30, Verse 7', 'गन्धाढ्यान्यभिरम्याणि पुष्पाणि च फलानि च।
धारयन्त्यगमास्तत्र भूषणानीव मानवाः॥', 'gandhāḍhyāny abhiramyāṇi puṣpāṇi ca phalāni ca
dhārayanty agamās tatra bhūṣaṇānīva mānavāḥ', null, 6030007),
('ramayana-6-30-8', 8, 'Yuddha Kanda, Sarga 30, Verse 8', 'तच्चैत्ररथसंकाशं मनोज्ञं नन्दनोपमम्।
वनं सर्वर्तुकं रम्यं शुशुभे षट्पदायुतम्॥', 'tac caitrarathasaṃkāśaṃ manojñaṃ nandanopamam
vanaṃ sarvartukaṃ ramyaṃ śuśubhe ṣaṭpadāyutam', null, 6030008),
('ramayana-6-30-9', 9, 'Yuddha Kanda, Sarga 30, Verse 9', 'नत्यूहकोयष्टिभकैर्नृत्यमानैश्च बर्हिभिः।
रुतं परभृतानां च शुश्रुवे वननिर्झरे॥', 'natyūhakoyaṣṭibhakair nṛtyamānaiś ca barhibhiḥ
rutaṃ parabhṛtānāṃ ca śuśruve vananirjhare', null, 6030009),
('ramayana-6-30-10', 10, 'Yuddha Kanda, Sarga 30, Verse 10', 'नित्यमत्तविहंगानि भ्रमराचरितानि च।
कोकिलाकुलषण्डानि विहगाभिरुतानि च॥', 'nityamattavihaṃgāni bhramarācaritāni ca
kokilākulaṣaṇḍāni vihagābhirutāni ca', null, 6030010),
('ramayana-6-30-11', 11, 'Yuddha Kanda, Sarga 30, Verse 11', 'भृङ्गराजाभिगीतानि भ्रमरैः सेवितानि च।
कोणालकविघुष्टानि सारसाभिरुतानि च॥', 'bhṛṅgarājābhigītāni bhramaraiḥ sevitāni ca
koṇālakavighuṣṭāni sārasābhirutāni ca', null, 6030011),
('ramayana-6-30-12', 12, 'Yuddha Kanda, Sarga 30, Verse 12', 'विविशुस्ते ततस्तानि वनान्युपवनानि च।
हृष्टाः प्रमुदिता वीरा हरयः कामरूपिणः॥', 'viviśus te tatas tāni vanāny upavanāni ca
hṛṣṭāḥ pramuditā vīrā harayaḥ kāmarūpiṇaḥ', null, 6030012),
('ramayana-6-30-13', 13, 'Yuddha Kanda, Sarga 30, Verse 13', 'तेषां प्रविशतां तत्र वानराणां महौजसाम्।
पुष्पसंसर्गसुरभिर्ववौ घ्राणसुखोऽनिलः॥', 'teṣāṃ praviśatāṃ tatra vānarāṇāṃ mahaujasām
puṣpasaṃsargasurabhir vavau ghrāṇasukho ''nilaḥ', null, 6030013),
('ramayana-6-30-14', 14, 'Yuddha Kanda, Sarga 30, Verse 14', 'अन्ये तु हरिवीराणां यूथान्निष्क्रम्य यूथपाः।
सुग्रीवेणाभ्यनुज्ञाता लङ्कां जग्मुः पताकिनीम्॥', 'anye tu harivīrāṇāṃ yūthān niṣkramya yūthapāḥ
sugrīveṇābhyanujñātā laṅkāṃ jagmuḥ patākinīm', null, 6030014),
('ramayana-6-30-15', 15, 'Yuddha Kanda, Sarga 30, Verse 15', 'वित्रासयन्तो विहगांस्त्रासयन्तो मृगद्विपान्।
कम्पयन्तश्च तां लङ्कां नादैः स्वैर्नदतां वराः॥', 'vitrāsayanto vihagāṃs trāsayanto mṛgadvipān
kampayantaś ca tāṃ laṅkāṃ nādaiḥ svair nadatāṃ varāḥ', null, 6030015),
('ramayana-6-30-16', 16, 'Yuddha Kanda, Sarga 30, Verse 16', 'कुर्वन्तस्ते महावेगा महीं चारणपीडिताम्।
रजश्च सहसैवोर्ध्वं जगाम चरणोद्धतम्॥', 'kurvantas te mahāvegā mahīṃ cāraṇapīḍitām
rajaś ca sahasaivordhvaṃ jagāma caraṇoddhatam', null, 6030016),
('ramayana-6-30-17', 17, 'Yuddha Kanda, Sarga 30, Verse 17', 'ऋक्षाः सिंहा वराहाश्च महिषा वारणा मृगाः।
तेन शब्देन वित्रस्ता जग्मुर्भीता दिशो दश॥', 'ṛkṣāḥ siṃhā varāhāś ca mahiṣā vāraṇā mṛgāḥ
tena śabdena vitrastā jagmur bhītā diśo daśa', null, 6030017),
('ramayana-6-30-18', 18, 'Yuddha Kanda, Sarga 30, Verse 18', 'शिखरं तु त्रिकूटस्य प्रांशु चैकं दिविस्पृशम्।
समन्तात्पुष्पसंछन्नं महारजतसंनिभम्॥', 'śikharaṃ tu trikūṭasya prāṃśu caikaṃ divispṛśam
samantāt puṣpasaṃchannaṃ mahārajatasaṃnibham', null, 6030018),
('ramayana-6-30-19', 19, 'Yuddha Kanda, Sarga 30, Verse 19', 'शतयोजनविस्तीर्णं विमलं चारुदर्शनम्।
श्लक्ष्णं श्रीमन्महच्चैव दुष्प्रापं शकुनैरपि॥', 'śatayojanavistīrṇaṃ vimalaṃ cārudarśanam
ślakṣṇaṃ śrīman mahac caiva duṣprāpaṃ śakunair api', null, 6030019),
('ramayana-6-30-20', 20, 'Yuddha Kanda, Sarga 30, Verse 20', 'मनसापि दुरारोहं किं पुनः कर्मणा जनैः।
निविष्टा तत्र शिखरे लङ्का रावणपालिता॥', 'manasāpi durārohaṃ kiṃ punaḥ karmaṇā janaiḥ
niviṣṭā tatra śikhare laṅkā rāvaṇapālitā', null, 6030020),
('ramayana-6-30-21', 21, 'Yuddha Kanda, Sarga 30, Verse 21', 'सा पुरी गोपुरैरुच्चैः पाण्डुराम्बुदसंनिभैः।
काञ्चनेन च सालेन राजतेन च शोभिता॥', 'sā purī gopurair uccaiḥ pāṇḍurāmbudasaṃnibhaiḥ
kāñcanena ca sālena rājatena ca śobhitā', null, 6030021),
('ramayana-6-30-22', 22, 'Yuddha Kanda, Sarga 30, Verse 22', 'प्रासादैश्च विमानैश्च लङ्का परमभूषिता।
घनैरिवातपापाये मध्यमं वैष्णवं पदम्॥', 'prāsādaiś ca vimānaiś ca laṅkā paramabhūṣitā
ghanair ivātapāpāye madhyamaṃ vaiṣṇavaṃ padam', null, 6030022),
('ramayana-6-30-23', 23, 'Yuddha Kanda, Sarga 30, Verse 23', 'यस्यां स्तम्भसहस्रेण प्रासादः समलंकृतः।
कैलासशिखराकारो दृश्यते खमिवोल्लिखन्॥', 'yasyāṃ stambhasahasreṇa prāsādaḥ samalaṃkṛtaḥ
kailāsaśikharākāro dṛśyate kham ivollikhan', null, 6030023),
('ramayana-6-30-24', 24, 'Yuddha Kanda, Sarga 30, Verse 24', 'चैत्यः स राक्षसेन्द्रस्य बभूव पुरभूषणम्।
शतेन रक्षसां नित्यं यः समग्रेण रक्ष्यते॥', 'caityaḥ sa rākṣasendrasya babhūva purabhūṣaṇam
śatena rakṣasāṃ nityaṃ yaḥ samagreṇa rakṣyate', null, 6030024),
('ramayana-6-30-25', 25, 'Yuddha Kanda, Sarga 30, Verse 25', 'तां समृद्धां समृद्धार्थो लक्ष्मीवांल्लक्ष्मणाग्रजः।
रावणस्य पुरीं रामो ददर्श सह वानरैः॥', 'tāṃ samṛddhāṃ samṛddhārtho lakṣmīvāṃl lakṣmaṇāgrajaḥ
rāvaṇasya purīṃ rāmo dadarśa saha vānaraiḥ', null, 6030025),
('ramayana-6-30-26', 26, 'Yuddha Kanda, Sarga 30, Verse 26', 'तां रत्नपूर्णां बहुसंविधानां प्रासादमालाभिरलंकृतां च।
पुरीं महायन्त्रकवाटमुख्यां ददर्श रामो महता बलेन॥', 'tāṃ ratnapūrṇāṃ bahusaṃvidhānāṃ prāsādamālābhir alaṃkṛtāṃ ca
purīṃ mahāyantrakavāṭamukhyāṃ dadarśa rāmo mahatā balena', null, 6030026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 31 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-31-1', 1, 'Yuddha Kanda, Sarga 31, Verse 1', 'अथ तस्मिन्निमित्तानि दृष्ट्वा लक्ष्मणपूर्वजः।
लक्ष्मणं लक्ष्मिसंपन्नमिदं वचनमब्रवीत्॥', 'atha tasmin nimittāni dṛṣṭvā lakṣmaṇapūrvajaḥ
lakṣmaṇaṃ lakṣmisaṃpannam idaṃ vacanam abravīt', null, 6031001),
('ramayana-6-31-2', 2, 'Yuddha Kanda, Sarga 31, Verse 2', 'परिगृह्योदकं शीतं वनानि फलवन्ति च।
बलौघं संविभज्येमं व्यूह्य तिष्ठेम लक्ष्मण॥', 'parigṛhyodakaṃ śītaṃ vanāni phalavanti ca
balaughaṃ saṃvibhajyemaṃ vyūhya tiṣṭhema lakṣmaṇa', null, 6031002),
('ramayana-6-31-3', 3, 'Yuddha Kanda, Sarga 31, Verse 3', 'लोकक्षयकरं भीमं भयं पश्याम्युपस्थितम्।
निबर्हणं प्रवीराणामृक्षवानररक्षसाम्॥', 'lokakṣayakaraṃ bhīmaṃ bhayaṃ paśyāmy upasthitam
nibarhaṇaṃ pravīrāṇām ṛkṣavānararakṣasām', null, 6031003),
('ramayana-6-31-4', 4, 'Yuddha Kanda, Sarga 31, Verse 4', 'वाताश्च परुषं वान्ति कम्पते च वसुंधरा।
पर्वताग्राणि वेपन्ते पतन्ति धरणीधराः॥', 'vātāś ca paruṣaṃ vānti kampate ca vasuṃdharā
parvatāgrāṇi vepante patanti dharaṇīdharāḥ', null, 6031004),
('ramayana-6-31-5', 5, 'Yuddha Kanda, Sarga 31, Verse 5', 'मेघाः क्रव्यादसंकाशाः परुषाः परुषस्वनाः।
क्रूराः क्रूरं प्रवर्षन्ति मिश्रं शोणितबिन्दुभिः॥', 'meghāḥ kravyādasaṃkāśāḥ paruṣāḥ paruṣasvanāḥ
krūrāḥ krūraṃ pravarṣanti miśraṃ śoṇitabindubhiḥ', null, 6031005),
('ramayana-6-31-6', 6, 'Yuddha Kanda, Sarga 31, Verse 6', 'रक्तचन्दनसंकाशा संध्यापरमदारुणा।
ज्वलच्च निपतत्येतदादित्यादग्निमण्डलम्॥', 'raktacandanasaṃkāśā saṃdhyāparamadāruṇā
jvalac ca nipataty etad ādityād agnimaṇḍalam', null, 6031006),
('ramayana-6-31-7', 7, 'Yuddha Kanda, Sarga 31, Verse 7', 'आदित्यमभिवाश्यन्ते जनयन्तो महद्भयम्।
दीना दीनस्वरा घोरा अप्रशस्ता मृगद्विजाः॥', 'ādityam abhivāśyante janayanto mahad bhayam
dīnā dīnasvarā ghorā apraśastā mṛgadvijāḥ', null, 6031007),
('ramayana-6-31-8', 8, 'Yuddha Kanda, Sarga 31, Verse 8', 'रजन्यामप्रकाशश्च संतापयति चन्द्रमाः।
कृष्णरक्तांशुपर्यन्तो यथा लोकस्य संक्षये॥', 'rajanyām aprakāśaś ca saṃtāpayati candramāḥ
kṛṣṇaraktāṃśuparyanto yathā lokasya saṃkṣaye', null, 6031008),
('ramayana-6-31-9', 9, 'Yuddha Kanda, Sarga 31, Verse 9', 'ह्रस्वो रूक्षोऽप्रशस्तश्च परिवेषः सुलोहितः।
आदित्यमण्डले नीलं लक्ष्म लक्ष्मण दृश्यते॥', 'hrasvo rūkṣo ''praśastaś ca pariveṣaḥ sulohitaḥ
ādityamaṇḍale nīlaṃ lakṣma lakṣmaṇa dṛśyate', null, 6031009),
('ramayana-6-31-10', 10, 'Yuddha Kanda, Sarga 31, Verse 10', 'दृश्यन्ते न यथावच्च नक्षत्राण्यभिवर्तते।
युगान्तमिव लोकस्य पश्य लक्ष्मण शंसति॥', 'dṛśyante na yathāvac ca nakṣatrāṇy abhivartate
yugāntam iva lokasya paśya lakṣmaṇa śaṃsati', null, 6031010),
('ramayana-6-31-11', 11, 'Yuddha Kanda, Sarga 31, Verse 11', 'काकाः श्येनास्तथा गृध्रा नीचैः परिपतन्ति च।
शिवाश्चाप्यशिवा वाचः प्रवदन्ति महास्वनाः॥', 'kākāḥ śyenās tathā gṛdhrā nīcaiḥ paripatanti ca
śivāś cāpy aśivā vācaḥ pravadanti mahāsvanāḥ', null, 6031011),
('ramayana-6-31-12', 12, 'Yuddha Kanda, Sarga 31, Verse 12', 'क्षिप्रमद्य दुराधर्षां पुरीं रावणपालिताम्।
अभियाम जवेनैव सर्वतो हरिभिर्वृताः॥', 'kṣipram adya durādharṣāṃ purīṃ rāvaṇapālitām
abhiyāma javenaiva sarvato haribhir vṛtāḥ', null, 6031012),
('ramayana-6-31-13', 13, 'Yuddha Kanda, Sarga 31, Verse 13', 'इत्येवं तु वदन्वीरो लक्ष्मणं लक्ष्मणाग्रजः।
तस्मादवातरच्छीघ्रं पर्वताग्रान्महाबलः॥', 'ity evaṃ tu vadan vīro lakṣmaṇaṃ lakṣmaṇāgrajaḥ
tasmād avātarac chīghraṃ parvatāgrān mahābalaḥ', null, 6031013),
('ramayana-6-31-14', 14, 'Yuddha Kanda, Sarga 31, Verse 14', 'अवतीर्य तु धर्मात्मा तस्माच्छैलात्स राघवः।
परैः परमदुर्धर्षं ददर्श बलमात्मनः॥', 'avatīrya tu dharmātmā tasmāc chailāt sa rāghavaḥ
paraiḥ paramadurdharṣaṃ dadarśa balam ātmanaḥ', null, 6031014),
('ramayana-6-31-15', 15, 'Yuddha Kanda, Sarga 31, Verse 15', 'संनह्य तु ससुग्रीवः कपिराजबलं महत्।
कालज्ञो राघवः काले संयुगायाभ्यचोदयत्॥', 'saṃnahya tu sasugrīvaḥ kapirājabalaṃ mahat
kālajño rāghavaḥ kāle saṃyugāyābhyacodayat', null, 6031015),
('ramayana-6-31-16', 16, 'Yuddha Kanda, Sarga 31, Verse 16', 'ततः काले महाबाहुर्बलेन महता वृतः।
प्रस्थितः पुरतो धन्वी लङ्कामभिमुखः पुरीम्॥', 'tataḥ kāle mahābāhur balena mahatā vṛtaḥ
prasthitaḥ purato dhanvī laṅkām abhimukhaḥ purīm', null, 6031016),
('ramayana-6-31-17', 17, 'Yuddha Kanda, Sarga 31, Verse 17', 'तं विभीषण सुग्रीवौ हनूमाञ्जाम्बवान्नलः।
ऋक्षराजस्तथा नीलो लक्ष्मणश्चान्ययुस्तदा॥', 'taṃ vibhīṣaṇa sugrīvau hanūmāñ jāmbavān nalaḥ
ṛkṣarājas tathā nīlo lakṣmaṇaś cānyayus tadā', null, 6031017),
('ramayana-6-31-18', 18, 'Yuddha Kanda, Sarga 31, Verse 18', 'ततः पश्चात्सुमहती पृतनर्क्षवनौकसाम्।
प्रच्छाद्य महतीं भूमिमनुयाति स्म राघवम्॥', 'tataḥ paścāt sumahatī pṛtanarkṣavanaukasām
pracchādya mahatīṃ bhūmim anuyāti sma rāghavam', null, 6031018),
('ramayana-6-31-19', 19, 'Yuddha Kanda, Sarga 31, Verse 19', 'शैलशृङ्गाणि शतशः प्रवृद्धांश्च महीरुहाम्।
जगृहुः कुञ्जरप्रख्या वानराः परवारणाः॥', 'śailaśṛṅgāṇi śataśaḥ pravṛddhāṃś ca mahīruhām
jagṛhuḥ kuñjaraprakhyā vānarāḥ paravāraṇāḥ', null, 6031019),
('ramayana-6-31-20', 20, 'Yuddha Kanda, Sarga 31, Verse 20', 'तौ त्वदीर्घेण कालेन भ्रातरौ रामलक्ष्मणौ।
रावणस्य पुरीं लङ्कामासेदतुररिंदमौ॥', 'tau tv adīrgheṇa kālena bhrātarau rāmalakṣmaṇau
rāvaṇasya purīṃ laṅkām āsedatur ariṃdamau', null, 6031020),
('ramayana-6-31-21', 21, 'Yuddha Kanda, Sarga 31, Verse 21', 'पताकामालिनीं रम्यामुद्यानवनशोभिताम्।
चित्रवप्रां सुदुष्प्रापामुच्चप्राकारतोरणाम्॥', 'patākāmālinīṃ ramyām udyānavanaśobhitām
citravaprāṃ suduṣprāpām uccaprākāratoraṇām', null, 6031021),
('ramayana-6-31-22', 22, 'Yuddha Kanda, Sarga 31, Verse 22', 'तां सुरैरपि दुर्धर्षां रामवाक्यप्रचोदिताः।
यथानिदेशं संपीड्य न्यविशन्त वनौकसः॥', 'tāṃ surair api durdharṣāṃ rāmavākyapracoditāḥ
yathānideśaṃ saṃpīḍya nyaviśanta vanaukasaḥ', null, 6031022),
('ramayana-6-31-23', 23, 'Yuddha Kanda, Sarga 31, Verse 23', 'लङ्कायास्तूत्तरद्वारं शैलशृङ्गमिवोन्नतम्।
रामः सहानुजो धन्वी जुगोप च रुरोध च॥', 'laṅkāyās tūttaradvāraṃ śailaśṛṅgam ivonnatam
rāmaḥ sahānujo dhanvī jugopa ca rurodha ca', null, 6031023),
('ramayana-6-31-24', 24, 'Yuddha Kanda, Sarga 31, Verse 24', 'लङ्कामुपनिविष्टश्च रामो दशरथात्मजः।
लक्ष्मणानुचरो वीरः पुरीं रावणपालिताम्॥', 'laṅkām upaniviṣṭaś ca rāmo daśarathātmajaḥ
lakṣmaṇānucaro vīraḥ purīṃ rāvaṇapālitām', null, 6031024),
('ramayana-6-31-25', 25, 'Yuddha Kanda, Sarga 31, Verse 25', 'उत्तरद्वारमासाद्य यत्र तिष्ठति रावणः।
नान्यो रामाद्धि तद्द्वारं समर्थः परिरक्षितुम्॥', 'uttaradvāram āsādya yatra tiṣṭhati rāvaṇaḥ
nānyo rāmād dhi tad dvāraṃ samarthaḥ parirakṣitum', null, 6031025),
('ramayana-6-31-26', 26, 'Yuddha Kanda, Sarga 31, Verse 26', 'रावणाधिष्ठितं भीमं वरुणेनेव सागरम्।
सायुधौ राक्षसैर्भीमैरभिगुप्तं समन्ततः।
लघूनां त्रासजननं पातालमिव दानवैः॥', 'rāvaṇādhiṣṭhitaṃ bhīmaṃ varuṇeneva sāgaram
sāyudhau rākṣasair bhīmair abhiguptaṃ samantataḥ
laghūnāṃ trāsajananaṃ pātālam iva dānavaiḥ', null, 6031026),
('ramayana-6-31-27', 27, 'Yuddha Kanda, Sarga 31, Verse 27', 'विन्यस्तानि च योधानां बहूनि विविधानि च।
ददर्शायुधजालानि तथैव कवचानि च॥', 'vinyastāni ca yodhānāṃ bahūni vividhāni ca
dadarśāyudhajālāni tathaiva kavacāni ca', null, 6031027),
('ramayana-6-31-28', 28, 'Yuddha Kanda, Sarga 31, Verse 28', 'पूर्वं तु द्वारमासाद्य नीलो हरिचमूपतिः।
अतिष्ठत्सह मैन्देन द्विविदेन च वीर्यवान्॥', 'pūrvaṃ tu dvāram āsādya nīlo haricamūpatiḥ
atiṣṭhat saha maindena dvividena ca vīryavān', null, 6031028),
('ramayana-6-31-29', 29, 'Yuddha Kanda, Sarga 31, Verse 29', 'अङ्गदो दक्षिणद्वारं जग्राह सुमहाबलः।
ऋषभेण गवाक्षेण गजेन गवयेन च॥', 'aṅgado dakṣiṇadvāraṃ jagrāha sumahābalaḥ
ṛṣabheṇa gavākṣeṇa gajena gavayena ca', null, 6031029),
('ramayana-6-31-30', 30, 'Yuddha Kanda, Sarga 31, Verse 30', 'हनूमान्पश्चिमद्वारं ररक्ष बलवान्कपिः।
प्रमाथि प्रघसाभ्यां च वीरैरन्यैश्च संगतः॥', 'hanūmān paścimadvāraṃ rarakṣa balavān kapiḥ
pramāthi praghasābhyāṃ ca vīrair anyaiś ca saṃgataḥ', null, 6031030),
('ramayana-6-31-31', 31, 'Yuddha Kanda, Sarga 31, Verse 31', 'मध्यमे च स्वयं गुल्मे सुग्रीवः समतिष्ठत।
सह सर्वैर्हरिश्रेष्ठैः सुपर्णश्वसनोपमैः॥', 'madhyame ca svayaṃ gulme sugrīvaḥ samatiṣṭhata
saha sarvair hariśreṣṭhaiḥ suparṇaśvasanopamaiḥ', null, 6031031),
('ramayana-6-31-32', 32, 'Yuddha Kanda, Sarga 31, Verse 32', 'वानराणां तु षट्त्रिंशत्कोट्यः प्रख्यातयूथपाः।
निपीड्योपनिविष्टाश्च सुग्रीवो यत्र वानरः॥', 'vānarāṇāṃ tu ṣaṭtriṃśat koṭyaḥ prakhyātayūthapāḥ
nipīḍyopaniviṣṭāś ca sugrīvo yatra vānaraḥ', null, 6031032),
('ramayana-6-31-33', 33, 'Yuddha Kanda, Sarga 31, Verse 33', 'शासनेन तु रामस्य लक्ष्मणः सविभीषणः।
द्वारे द्वारे हरीणां तु कोटिं कोटिं न्यवेशयत्॥', 'śāsanena tu rāmasya lakṣmaṇaḥ savibhīṣaṇaḥ
dvāre dvāre harīṇāṃ tu koṭiṃ koṭiṃ nyaveśayat', null, 6031033),
('ramayana-6-31-34', 34, 'Yuddha Kanda, Sarga 31, Verse 34', 'पश्चिमेन तु रामस्य सुग्रीवः सह जाम्बवान्।
अदूरान्मध्यमे गुल्मे तस्थौ बहुबलानुगः॥', 'paścimena tu rāmasya sugrīvaḥ saha jāmbavān
adūrān madhyame gulme tasthau bahubalānugaḥ', null, 6031034),
('ramayana-6-31-35', 35, 'Yuddha Kanda, Sarga 31, Verse 35', 'ते तु वानरशार्दूलाः शार्दूला इव दंष्ट्रिणः।
गृहीत्वा द्रुमशैलाग्रान्हृष्टा युद्धाय तस्थिरे॥', 'te tu vānaraśārdūlāḥ śārdūlā iva daṃṣṭriṇaḥ
gṛhītvā drumaśailāgrān hṛṣṭā yuddhāya tasthire', null, 6031035),
('ramayana-6-31-36', 36, 'Yuddha Kanda, Sarga 31, Verse 36', 'सर्वे विकृतलाङ्गूलाः सर्वे दंष्ट्रानखायुधाः।
सर्वे विकृतचित्राङ्गाः सर्वे च विकृताननाः॥', 'sarve vikṛtalāṅgūlāḥ sarve daṃṣṭrānakhāyudhāḥ
sarve vikṛtacitrāṅgāḥ sarve ca vikṛtānanāḥ', null, 6031036),
('ramayana-6-31-37', 37, 'Yuddha Kanda, Sarga 31, Verse 37', 'दशनागबलाः के चित्के चिद्दशगुणोत्तराः।
के चिन्नागसहस्रस्य बभूवुस्तुल्यविक्रमाः॥', 'daśanāgabalāḥ ke cit ke cid daśaguṇottarāḥ
ke cin nāgasahasrasya babhūvus tulyavikramāḥ', null, 6031037),
('ramayana-6-31-38', 38, 'Yuddha Kanda, Sarga 31, Verse 38', 'सन्ति चौघा बलाः के चित्के चिच्छतगुणोत्तराः।
अप्रमेयबलाश्चान्ये तत्रासन्हरियूथपाः॥', 'santi caughā balāḥ ke cit ke cic chataguṇottarāḥ
aprameyabalāś cānye tatrāsan hariyūthapāḥ', null, 6031038),
('ramayana-6-31-39', 39, 'Yuddha Kanda, Sarga 31, Verse 39', 'अद्भुतश्च विचित्रश्च तेषामासीत्समागमः।
तत्र वानरसैन्यानां शलभानामिवोद्गमः॥', 'adbhutaś ca vicitraś ca teṣām āsīt samāgamaḥ
tatra vānarasainyānāṃ śalabhānām ivodgamaḥ', null, 6031039),
('ramayana-6-31-40', 40, 'Yuddha Kanda, Sarga 31, Verse 40', 'परिपूर्णमिवाकाशं संछन्नेव च मेदिनी।
लङ्कामुपनिविष्टैश्च संपतद्भिश्च वानरैः॥', 'paripūrṇam ivākāśaṃ saṃchanneva ca medinī
laṅkām upaniviṣṭaiś ca saṃpatadbhiś ca vānaraiḥ', null, 6031040),
('ramayana-6-31-41', 41, 'Yuddha Kanda, Sarga 31, Verse 41', 'शतं शतसहस्राणां पृथगृक्षवनौकसाम्।
लङ्का द्वाराण्युपाजग्मुरन्ये योद्धुं समन्ततः॥', 'śataṃ śatasahasrāṇāṃ pṛthag ṛkṣavanaukasām
laṅkā dvārāṇy upājagmur anye yoddhuṃ samantataḥ', null, 6031041),
('ramayana-6-31-42', 42, 'Yuddha Kanda, Sarga 31, Verse 42', 'आवृतः स गिरिः सर्वैस्तैः समन्तात्प्लवंगमैः।
अयुतानां सहस्रं च पुरीं तामभ्यवर्तत॥', 'āvṛtaḥ sa giriḥ sarvais taiḥ samantāt plavaṃgamaiḥ
ayutānāṃ sahasraṃ ca purīṃ tām abhyavartata', null, 6031042),
('ramayana-6-31-43', 43, 'Yuddha Kanda, Sarga 31, Verse 43', 'वानरैर्बलवद्भिश्च बभूव द्रुमपाणिभिः।
सर्वतः संवृता लङ्का दुष्प्रवेशापि वायुना॥', 'vānarair balavadbhiś ca babhūva drumapāṇibhiḥ
sarvataḥ saṃvṛtā laṅkā duṣpraveśāpi vāyunā', null, 6031043),
('ramayana-6-31-44', 44, 'Yuddha Kanda, Sarga 31, Verse 44', 'राक्षसा विस्मयं जग्मुः सहसाभिनिपीडिताः।
वानरैर्मेघसंकाशैः शक्रतुल्यपराक्रमैः॥', 'rākṣasā vismayaṃ jagmuḥ sahasābhinipīḍitāḥ
vānarair meghasaṃkāśaiḥ śakratulyaparākramaiḥ', null, 6031044),
('ramayana-6-31-45', 45, 'Yuddha Kanda, Sarga 31, Verse 45', 'महाञ्शब्दोऽभवत्तत्र बलौघस्याभिवर्ततः।
सागरस्येव भिन्नस्य यथा स्यात्सलिलस्वनः॥', 'mahāñ śabdo ''bhavat tatra balaughasyābhivartataḥ
sāgarasyeva bhinnasya yathā syāt salilasvanaḥ', null, 6031045),
('ramayana-6-31-46', 46, 'Yuddha Kanda, Sarga 31, Verse 46', 'तेन शब्देन महता सप्राकारा सतोरणा।
लङ्का प्रचलिता सर्वा सशैलवनकानना॥', 'tena śabdena mahatā saprākārā satoraṇā
laṅkā pracalitā sarvā saśailavanakānanā', null, 6031046),
('ramayana-6-31-47', 47, 'Yuddha Kanda, Sarga 31, Verse 47', 'रामलक्ष्मणगुप्ता सा सुग्रीवेण च वाहिनी।
बभूव दुर्धर्षतरा सर्वैरपि सुरासुरैः॥', 'rāmalakṣmaṇaguptā sā sugrīveṇa ca vāhinī
babhūva durdharṣatarā sarvair api surāsuraiḥ', null, 6031047),
('ramayana-6-31-48', 48, 'Yuddha Kanda, Sarga 31, Verse 48', 'राघवः संनिवेश्यैवं सैन्यं स्वं रक्षसां वधे।
संमन्त्र्य मन्त्रिभिः सार्धं निश्चित्य च पुनः पुनः॥', 'rāghavaḥ saṃniveśyaivaṃ sainyaṃ svaṃ rakṣasāṃ vadhe
saṃmantrya mantribhiḥ sārdhaṃ niścitya ca punaḥ punaḥ', null, 6031048),
('ramayana-6-31-49', 49, 'Yuddha Kanda, Sarga 31, Verse 49', 'आनन्तर्यमभिप्रेप्सुः क्रमयोगार्थतत्त्ववित्।
विभीषणस्यानुमते राजधर्ममनुस्मरन्।
अङ्गदं वालितनयं समाहूयेदमब्रवीत्॥', 'ānantaryam abhiprepsuḥ kramayogārthatattvavit
vibhīṣaṇasyānumate rājadharmam anusmaran
aṅgadaṃ vālitanayaṃ samāhūyedam abravīt', null, 6031049),
('ramayana-6-31-50', 50, 'Yuddha Kanda, Sarga 31, Verse 50', 'गत्वा सौम्य दशग्रीवं ब्रूहि मद्वचनात्कपे।
लङ्घयित्वा पुरीं लङ्कां भयं त्यक्त्वा गतव्यथः॥', 'gatvā saumya daśagrīvaṃ brūhi madvacanāt kape
laṅghayitvā purīṃ laṅkāṃ bhayaṃ tyaktvā gatavyathaḥ', null, 6031050),
('ramayana-6-31-51', 51, 'Yuddha Kanda, Sarga 31, Verse 51', 'भ्रष्टश्रीकगतैश्वर्यमुमूर्षो नष्टचेतनः।
ऋषीणां देवतानां च गन्धर्वाप्सरसां तथा॥', 'bhraṣṭaśrīkagataiśvaryamumūrṣo naṣṭacetanaḥ
ṛṣīṇāṃ devatānāṃ ca gandharvāpsarasāṃ tathā', null, 6031051),
('ramayana-6-31-52', 52, 'Yuddha Kanda, Sarga 31, Verse 52', 'नागानामथ यक्षाणां राज्ञां च रजनीचर।
यच्च पापं कृतं मोहादवलिप्तेन राक्षस॥', 'nāgānām atha yakṣāṇāṃ rājñāṃ ca rajanīcara
yac ca pāpaṃ kṛtaṃ mohād avaliptena rākṣasa', null, 6031052),
('ramayana-6-31-53', 53, 'Yuddha Kanda, Sarga 31, Verse 53', 'नूनमद्य गतो दर्पः स्वयम्भू वरदानजः।
यस्य दण्डधरस्तेऽहं दाराहरणकर्शितः।
दण्डं धारयमाणस्तु लङ्काद्वरे व्यवस्थितः॥', 'nūnam adya gato darpaḥ svayambhū varadānajaḥ
yasya daṇḍadharas te ''haṃ dārāharaṇakarśitaḥ
daṇḍaṃ dhārayamāṇas tu laṅkādvare vyavasthitaḥ', null, 6031053),
('ramayana-6-31-54', 54, 'Yuddha Kanda, Sarga 31, Verse 54', 'पदवीं देवतानां च महर्षीणां च राक्षस।
राजर्षीणां च सर्वेषां गमिष्यसि मया हतः॥', 'padavīṃ devatānāṃ ca maharṣīṇāṃ ca rākṣasa
rājarṣīṇāṃ ca sarveṣāṃ gamiṣyasi mayā hataḥ', null, 6031054),
('ramayana-6-31-55', 55, 'Yuddha Kanda, Sarga 31, Verse 55', 'बलेन येन वै सीतां मायया राक्षसाधम।
मामतिक्रामयित्वा त्वं हृतवांस्तद्विदर्शय॥', 'balena yena vai sītāṃ māyayā rākṣasādhama
mām atikrāmayitvā tvaṃ hṛtavāṃs tad vidarśaya', null, 6031055),
('ramayana-6-31-56', 56, 'Yuddha Kanda, Sarga 31, Verse 56', 'अराक्षसमिमं लोकं कर्तास्मि निशितैः शरैः।
न चेच्छरणमभ्येषि मामुपादाय मैथिलीम्॥', 'arākṣasam imaṃ lokaṃ kartāsmi niśitaiḥ śaraiḥ
na cec charaṇam abhyeṣi mām upādāya maithilīm', null, 6031056),
('ramayana-6-31-57', 57, 'Yuddha Kanda, Sarga 31, Verse 57', 'धर्मात्मा रक्षसां श्रेष्ठः संप्राप्तोऽयं विभीषणः।
लङ्कैश्वर्यं ध्रुवं श्रीमानयं प्राप्नोत्यकण्टकम्॥', 'dharmātmā rakṣasāṃ śreṣṭhaḥ saṃprāpto ''yaṃ vibhīṣaṇaḥ
laṅkaiśvaryaṃ dhruvaṃ śrīmān ayaṃ prāpnoty akaṇṭakam', null, 6031057),
('ramayana-6-31-58', 58, 'Yuddha Kanda, Sarga 31, Verse 58', 'न हि राज्यमधर्मेण भोक्तुं क्षणमपि त्वया।
शक्यं मूर्खसहायेन पापेनाविजितात्मना॥', 'na hi rājyam adharmeṇa bhoktuṃ kṣaṇam api tvayā
śakyaṃ mūrkhasahāyena pāpenāvijitātmanā', null, 6031058),
('ramayana-6-31-59', 59, 'Yuddha Kanda, Sarga 31, Verse 59', 'युध्यस्व वा धृतिं कृत्वा शौर्यमालम्ब्य राक्षस।
मच्छरैस्त्वं रणे शान्तस्ततः पूतो भविष्यसि॥', 'yudhyasva vā dhṛtiṃ kṛtvā śauryam ālambya rākṣasa
maccharais tvaṃ raṇe śāntas tataḥ pūto bhaviṣyasi', null, 6031059),
('ramayana-6-31-60', 60, 'Yuddha Kanda, Sarga 31, Verse 60', 'यद्याविशसि लोकांस्त्रीन्पक्षिभूतो मनोजवः।
मम चक्षुष्पथं प्राप्य न जीवन्प्रतियास्यसि॥', 'yady āviśasi lokāṃs trīn pakṣibhūto manojavaḥ
mama cakṣuṣpathaṃ prāpya na jīvan pratiyāsyasi', null, 6031060),
('ramayana-6-31-61', 61, 'Yuddha Kanda, Sarga 31, Verse 61', 'ब्रवीमि त्वां हितं वाक्यं क्रियतामौर्ध्वदेकिकम्।
सुदृष्टा क्रियतां लङ्का जीवितं ते मयि स्थितम्॥', 'bravīmi tvāṃ hitaṃ vākyaṃ kriyatām aurdhvadekikam
sudṛṣṭā kriyatāṃ laṅkā jīvitaṃ te mayi sthitam', null, 6031061),
('ramayana-6-31-62', 62, 'Yuddha Kanda, Sarga 31, Verse 62', 'इत्युक्तः स तु तारेयो रामेणाक्लिष्टकर्मणा।
जगामाकाशमाविश्य मूर्तिमानिव हव्यवाट्॥', 'ity uktaḥ sa tu tāreyo rāmeṇākliṣṭakarmaṇā
jagāmākāśam āviśya mūrtimān iva havyavāṭ', null, 6031062),
('ramayana-6-31-63', 63, 'Yuddha Kanda, Sarga 31, Verse 63', 'सोऽतिपत्य मुहूर्तेन श्रीमान्रावणमन्दिरम्।
ददर्शासीनमव्यग्रं रावणं सचिवैः सह॥', 'so ''tipatya muhūrtena śrīmān rāvaṇamandiram
dadarśāsīnam avyagraṃ rāvaṇaṃ sacivaiḥ saha', null, 6031063),
('ramayana-6-31-64', 64, 'Yuddha Kanda, Sarga 31, Verse 64', 'ततस्तस्याविदूरेण निपत्य हरिपुंगवः।
दीप्ताग्निसदृशस्तस्थावङ्गदः कनकाङ्गदः॥', 'tatas tasyāvidūreṇa nipatya haripuṃgavaḥ
dīptāgnisadṛśas tasthāv aṅgadaḥ kanakāṅgadaḥ', null, 6031064),
('ramayana-6-31-65', 65, 'Yuddha Kanda, Sarga 31, Verse 65', 'तद्रामवचनं सर्वमन्यूनाधिकमुत्तमम्।
सामात्यं श्रावयामास निवेद्यात्मानमात्मना॥', 'tad rāmavacanaṃ sarvam anyūnādhikam uttamam
sāmātyaṃ śrāvayām āsa nivedyātmānam ātmanā', null, 6031065),
('ramayana-6-31-66', 66, 'Yuddha Kanda, Sarga 31, Verse 66', 'दूतोऽहं कोसलेन्द्रस्य रामस्याक्लिष्टकर्मणः।
वालिपुत्रोऽङ्गदो नाम यदि ते श्रोत्रमागतः॥', 'dūto ''haṃ kosalendrasya rāmasyākliṣṭakarmaṇaḥ
vāliputro ''ṅgado nāma yadi te śrotram āgataḥ', null, 6031066),
('ramayana-6-31-67', 67, 'Yuddha Kanda, Sarga 31, Verse 67', 'आह त्वां राघवो रामः कौसल्यानन्दवर्धनः।
निष्पत्य प्रतियुध्यस्व नृशंसं पुरुषाधम॥', 'āha tvāṃ rāghavo rāmaḥ kausalyānandavardhanaḥ
niṣpatya pratiyudhyasva nṛśaṃsaṃ puruṣādhama', null, 6031067),
('ramayana-6-31-68', 68, 'Yuddha Kanda, Sarga 31, Verse 68', 'हन्तास्मि त्वां सहामात्यं सपुत्रज्ञातिबान्धवम्।
निरुद्विग्नास्त्रयो लोका भविष्यन्ति हते त्वयि॥', 'hantāsmi tvāṃ sahāmātyaṃ saputrajñātibāndhavam
nirudvignās trayo lokā bhaviṣyanti hate tvayi', null, 6031068),
('ramayana-6-31-69', 69, 'Yuddha Kanda, Sarga 31, Verse 69', 'देवदानवयक्षाणां गन्धर्वोरगरक्षसाम्।
शत्रुमद्योद्धरिष्यामि त्वामृषीणां च कण्टकम्॥', 'devadānavayakṣāṇāṃ gandharvoragarakṣasām
śatrum adyoddhariṣyāmi tvām ṛṣīṇāṃ ca kaṇṭakam', null, 6031069),
('ramayana-6-31-70', 70, 'Yuddha Kanda, Sarga 31, Verse 70', 'विभीषणस्य चैश्वर्यं भविष्यति हते त्वयि।
न चेत्सत्कृत्य वैदेहीं प्रणिपत्य प्रदास्यसि॥', 'vibhīṣaṇasya caiśvaryaṃ bhaviṣyati hate tvayi
na cet satkṛtya vaidehīṃ praṇipatya pradāsyasi', null, 6031070),
('ramayana-6-31-71', 71, 'Yuddha Kanda, Sarga 31, Verse 71', 'इत्येवं परुषं वाक्यं ब्रुवाणे हरिपुंगवे।
अमर्षवशमापन्नो निशाचरगणेश्वरः॥', 'ity evaṃ paruṣaṃ vākyaṃ bruvāṇe haripuṃgave
amarṣavaśam āpanno niśācaragaṇeśvaraḥ', null, 6031071),
('ramayana-6-31-72', 72, 'Yuddha Kanda, Sarga 31, Verse 72', 'ततः स रोषताम्राक्षः शशास सचिवांस्तदा।
गृह्यतामेष दुर्मेधा वध्यतामिति चासकृत्॥', 'tataḥ sa roṣatāmrākṣaḥ śaśāsa sacivāṃs tadā
gṛhyatām eṣa durmedhā vadhyatām iti cāsakṛt', null, 6031072),
('ramayana-6-31-73', 73, 'Yuddha Kanda, Sarga 31, Verse 73', 'रावणस्य वचः श्रुत्वा दीप्ताग्निसमतेजसः।
जगृहुस्तं ततो घोराश्चत्वारो रजनीचराः॥', 'rāvaṇasya vacaḥ śrutvā dīptāgnisamatejasaḥ
jagṛhus taṃ tato ghorāś catvāro rajanīcarāḥ', null, 6031073),
('ramayana-6-31-74', 74, 'Yuddha Kanda, Sarga 31, Verse 74', 'ग्राहयामास तारेयः स्वयमात्मानमात्मना।
बलं दर्शयितुं वीरो यातुधानगणे तदा॥', 'grāhayām āsa tāreyaḥ svayam ātmānam ātmanā
balaṃ darśayituṃ vīro yātudhānagaṇe tadā', null, 6031074),
('ramayana-6-31-75', 75, 'Yuddha Kanda, Sarga 31, Verse 75', 'स तान्बाहुद्वये सक्तानादाय पतगानिव।
प्रासादं शैलसंकाशमुत्पापाताङ्गदस्तदा॥', 'sa tān bāhudvaye saktān ādāya patagān iva
prāsādaṃ śailasaṃkāśam utpāpātāṅgadas tadā', null, 6031075),
('ramayana-6-31-76', 76, 'Yuddha Kanda, Sarga 31, Verse 76', 'तेऽन्तरिक्षाद्विनिर्धूतास्तस्य वेगेन राक्षसाः।
भुमौ निपतिताः सर्वे राक्षसेन्द्रस्य पश्यतः॥', 'te ''ntarikṣād vinirdhūtās tasya vegena rākṣasāḥ
bhumau nipatitāḥ sarve rākṣasendrasya paśyataḥ', null, 6031076),
('ramayana-6-31-77', 77, 'Yuddha Kanda, Sarga 31, Verse 77', 'ततः प्रासादशिखरं शैलशृङ्गमिवोन्नतम्।
तत्पफाल तदाक्रान्तं दशग्रीवस्य पश्यतः॥', 'tataḥ prāsādaśikharaṃ śailaśṛṅgam ivonnatam
tat paphāla tadākrāntaṃ daśagrīvasya paśyataḥ', null, 6031077),
('ramayana-6-31-78', 78, 'Yuddha Kanda, Sarga 31, Verse 78', 'भङ्क्त्वा प्रासादशिखरं नाम विश्राव्य चात्मनः।
विनद्य सुमहानादमुत्पपात विहायसा॥', 'bhaṅktvā prāsādaśikharaṃ nāma viśrāvya cātmanaḥ
vinadya sumahānādam utpapāta vihāyasā', null, 6031078),
('ramayana-6-31-79', 79, 'Yuddha Kanda, Sarga 31, Verse 79', 'रावणस्तु परं चक्रे क्रोधं प्रासादधर्षणात्।
विनाशं चात्मनः पश्यन्निःश्वासपरमोऽभवत्॥', 'rāvaṇas tu paraṃ cakre krodhaṃ prāsādadharṣaṇāt
vināśaṃ cātmanaḥ paśyan niḥśvāsaparamo ''bhavat', null, 6031079),
('ramayana-6-31-80', 80, 'Yuddha Kanda, Sarga 31, Verse 80', 'रामस्तु बहुभिर्हृष्टैर्निनदद्भिः प्लवंगमैः।
वृतो रिपुवधाकाङ्क्षी युद्धायैवाभ्यवर्तत॥', 'rāmas tu bahubhir hṛṣṭair ninadadbhiḥ plavaṃgamaiḥ
vṛto ripuvadhākāṅkṣī yuddhāyaivābhyavartata', null, 6031080),
('ramayana-6-31-81', 81, 'Yuddha Kanda, Sarga 31, Verse 81', 'सुषेणस्तु महावीर्यो गिरिकूटोपमो हरिः।
बहुभिः संवृतस्तत्र वानरैः कामरूपिभिः॥', 'suṣeṇas tu mahāvīryo girikūṭopamo hariḥ
bahubhiḥ saṃvṛtas tatra vānaraiḥ kāmarūpibhiḥ', null, 6031081),
('ramayana-6-31-82', 82, 'Yuddha Kanda, Sarga 31, Verse 82', 'चतुर्द्वाराणि सर्वाणि सुग्रीववचनात्कपिः।
पर्याक्रमत दुर्धर्षो नक्षत्राणीव चन्द्रमाः॥', 'caturdvārāṇi sarvāṇi sugrīvavacanāt kapiḥ
paryākramata durdharṣo nakṣatrāṇīva candramāḥ', null, 6031082),
('ramayana-6-31-83', 83, 'Yuddha Kanda, Sarga 31, Verse 83', 'तेषामक्षौहिणिशतं समवेक्ष्य वनौकसाम्।
लङ्कामुपनिविष्टानां सागरं चातिवर्तताम्॥', 'teṣām akṣauhiṇiśataṃ samavekṣya vanaukasām
laṅkām upaniviṣṭānāṃ sāgaraṃ cātivartatām', null, 6031083),
('ramayana-6-31-84', 84, 'Yuddha Kanda, Sarga 31, Verse 84', 'राक्षसा विस्मयं जग्मुस्त्रासं जग्मुस्तथापरे।
अपरे समरोद्धर्षाद्धर्षमेवोपपेदिरे॥', 'rākṣasā vismayaṃ jagmus trāsaṃ jagmus tathāpare
apare samaroddharṣād dharṣam evopapedire', null, 6031084),
('ramayana-6-31-85', 85, 'Yuddha Kanda, Sarga 31, Verse 85', 'कृत्स्नं हि कपिभिर्व्याप्तं प्राकारपरिखान्तरम्।
ददृशू राक्षसा दीनाः प्राकारं वानरीकृतम्॥', 'kṛtsnaṃ hi kapibhir vyāptaṃ prākāraparikhāntaram
dadṛśū rākṣasā dīnāḥ prākāraṃ vānarīkṛtam', null, 6031085),
('ramayana-6-31-86', 86, 'Yuddha Kanda, Sarga 31, Verse 86', 'तस्मिन्महाभीषणके प्रवृत्ते कोलाहले राक्षसराजधान्याम्।
प्रगृह्य रक्षांसि महायुधानि युगान्तवाता इव संविचेरुः॥', 'tasmin mahābhīṣaṇake pravṛtte kolāhale rākṣasarājadhānyām
pragṛhya rakṣāṃsi mahāyudhāni yugāntavātā iva saṃviceruḥ', null, 6031086)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 32 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-32-1', 1, 'Yuddha Kanda, Sarga 32, Verse 1', 'ततस्ते राक्षसास्तत्र गत्वा रावणमन्दिरम्।
न्यवेदयन्पुरीं रुद्धां रामेण सह वानरैः॥', 'tatas te rākṣasās tatra gatvā rāvaṇamandiram
nyavedayan purīṃ ruddhāṃ rāmeṇa saha vānaraiḥ', null, 6032001),
('ramayana-6-32-2', 2, 'Yuddha Kanda, Sarga 32, Verse 2', 'रुद्धां तु नगरीं श्रुत्वा जातक्रोधो निशाचरः।
विधानं द्विगुणं श्रुत्वा प्रासादं सोऽध्यरोहत॥', 'ruddhāṃ tu nagarīṃ śrutvā jātakrodho niśācaraḥ
vidhānaṃ dviguṇaṃ śrutvā prāsādaṃ so ''dhyarohata', null, 6032002),
('ramayana-6-32-3', 3, 'Yuddha Kanda, Sarga 32, Verse 3', 'स ददर्शावृतां लङ्कां सशैलवनकाननाम्।
असंख्येयैर्हरिगणैः सर्वतो युद्धकाङ्क्षिभिः॥', 'sa dadarśāvṛtāṃ laṅkāṃ saśailavanakānanām
asaṃkhyeyair harigaṇaiḥ sarvato yuddhakāṅkṣibhiḥ', null, 6032003),
('ramayana-6-32-4', 4, 'Yuddha Kanda, Sarga 32, Verse 4', 'स दृष्ट्वा वानरैः सर्वां वसुधां कवलीकृताम्।
कथं क्षपयितव्याः स्युरिति चिन्तापरोऽभवत्॥', 'sa dṛṣṭvā vānaraiḥ sarvāṃ vasudhāṃ kavalīkṛtām
kathaṃ kṣapayitavyāḥ syur iti cintāparo ''bhavat', null, 6032004),
('ramayana-6-32-5', 5, 'Yuddha Kanda, Sarga 32, Verse 5', 'स चिन्तयित्वा सुचिरं धैर्यमालम्ब्य रावणः।
राघवं हरियूथांश्च ददर्शायतलोचनः॥', 'sa cintayitvā suciraṃ dhairyam ālambya rāvaṇaḥ
rāghavaṃ hariyūthāṃś ca dadarśāyatalocanaḥ', null, 6032005),
('ramayana-6-32-6', 6, 'Yuddha Kanda, Sarga 32, Verse 6', 'प्रेक्षतो राक्षसेन्द्रस्य तान्यनीकानि भागशः।
राघवप्रियकामार्थं लङ्कामारुरुहुस्तदा॥', 'prekṣato rākṣasendrasya tāny anīkāni bhāgaśaḥ
rāghavapriyakāmārthaṃ laṅkām āruruhus tadā', null, 6032006),
('ramayana-6-32-7', 7, 'Yuddha Kanda, Sarga 32, Verse 7', 'ते ताम्रवक्त्रा हेमाभा रामार्थे त्यक्तजीविताः।
लङ्कामेवाह्यवर्तन्त सालतालशिलायुधाः॥', 'te tāmravaktrā hemābhā rāmārthe tyaktajīvitāḥ
laṅkām evāhyavartanta sālatālaśilāyudhāḥ', null, 6032007),
('ramayana-6-32-8', 8, 'Yuddha Kanda, Sarga 32, Verse 8', 'ते द्रुमैः पर्वताग्रैश्च मुष्टिभिश्च प्लवंगमाः।
प्रासादाग्राणि चोच्चानि ममन्तुस्तोरणानि च॥', 'te drumaiḥ parvatāgraiś ca muṣṭibhiś ca plavaṃgamāḥ
prāsādāgrāṇi coccāni mamantus toraṇāni ca', null, 6032008),
('ramayana-6-32-9', 9, 'Yuddha Kanda, Sarga 32, Verse 9', 'पारिखाः पूरयन्ति स्म प्रसन्नसलिलायुताः।
पांसुभिः पर्वताग्रैश्च तृणैः काष्ठैश्च वानराः॥', 'pārikhāḥ pūrayanti sma prasannasalilāyutāḥ
pāṃsubhiḥ parvatāgraiś ca tṛṇaiḥ kāṣṭhaiś ca vānarāḥ', null, 6032009),
('ramayana-6-32-10', 10, 'Yuddha Kanda, Sarga 32, Verse 10', 'ततः सहस्रयूथाश्च कोटियूथाश्च यूथपाः।
कोटीशतयुताश्चान्ये लङ्कामारुरुहुस्तदा॥', 'tataḥ sahasrayūthāś ca koṭiyūthāś ca yūthapāḥ
koṭīśatayutāś cānye laṅkām āruruhus tadā', null, 6032010),
('ramayana-6-32-11', 11, 'Yuddha Kanda, Sarga 32, Verse 11', 'काञ्चनानि प्रमृद्नन्तस्तोरणानि प्लवंगमाः।
कैलासशिखराभानि गोपुराणि प्रमथ्य च॥', 'kāñcanāni pramṛdnantas toraṇāni plavaṃgamāḥ
kailāsaśikharābhāni gopurāṇi pramathya ca', null, 6032011),
('ramayana-6-32-12', 12, 'Yuddha Kanda, Sarga 32, Verse 12', 'आप्लवन्तः प्लवन्तश्च गर्जन्तश्च प्लवंगमाः।
लङ्कां तामभ्यवर्तन्त महावारणसंनिभाः॥', 'āplavantaḥ plavantaś ca garjantaś ca plavaṃgamāḥ
laṅkāṃ tām abhyavartanta mahāvāraṇasaṃnibhāḥ', null, 6032012),
('ramayana-6-32-13', 13, 'Yuddha Kanda, Sarga 32, Verse 13', 'जयत्यतिबलो रामो लक्ष्मणश्च महाबलः।
राजा जयति सुग्रीवो राघवेणाभिपालितः॥', 'jayaty atibalo rāmo lakṣmaṇaś ca mahābalaḥ
rājā jayati sugrīvo rāghaveṇābhipālitaḥ', null, 6032013),
('ramayana-6-32-14', 14, 'Yuddha Kanda, Sarga 32, Verse 14', 'इत्येवं घोषयन्तश्च गर्जन्तश्च प्लवंगमाः।
अभ्यधावन्त लङ्कायाः प्राकारं कामरूपिणः॥', 'ity evaṃ ghoṣayantaś ca garjantaś ca plavaṃgamāḥ
abhyadhāvanta laṅkāyāḥ prākāraṃ kāmarūpiṇaḥ', null, 6032014),
('ramayana-6-32-15', 15, 'Yuddha Kanda, Sarga 32, Verse 15', 'वीरबाहुः सुबाहुश्च नलश्च वनगोचरः।
निपीड्योपनिविष्टास्ते प्राकारं हरियूथपाः॥', 'vīrabāhuḥ subāhuś ca nalaś ca vanagocaraḥ
nipīḍyopaniviṣṭās te prākāraṃ hariyūthapāḥ', null, 6032015),
('ramayana-6-32-16', 16, 'Yuddha Kanda, Sarga 32, Verse 16', 'एतस्मिन्नन्तरे चक्रुः स्कन्धावारनिवेशनम्॥', 'etasminn antare cakruḥ skandhāvāraniveśanam', null, 6032016),
('ramayana-6-32-17', 17, 'Yuddha Kanda, Sarga 32, Verse 17', 'पूर्वद्वारं तु कुमुदः कोटिभिर्दशभिर्वृतः।
आवृत्य बलवांस्तस्थौ हरिभिर्जितकाशिभिः॥', 'pūrvadvāraṃ tu kumudaḥ koṭibhir daśabhir vṛtaḥ
āvṛtya balavāṃs tasthau haribhir jitakāśibhiḥ', null, 6032017),
('ramayana-6-32-18', 18, 'Yuddha Kanda, Sarga 32, Verse 18', 'दक्षिणद्वारमागम्य वीरः शतबलिः कपिः।
आवृत्य बलवांस्तस्थौ विंशत्या कोटिभिर्वृतः॥', 'dakṣiṇadvāram āgamya vīraḥ śatabaliḥ kapiḥ
āvṛtya balavāṃs tasthau viṃśatyā koṭibhir vṛtaḥ', null, 6032018),
('ramayana-6-32-19', 19, 'Yuddha Kanda, Sarga 32, Verse 19', 'सुषेणः पश्चिमद्वारं गतस्तारा पिता हरिः।
आवृत्य बलवांस्तस्थौ षष्टि कोटिभिरावृतः॥', 'suṣeṇaḥ paścimadvāraṃ gatas tārā pitā hariḥ
āvṛtya balavāṃs tasthau ṣaṣṭi koṭibhir āvṛtaḥ', null, 6032019),
('ramayana-6-32-20', 20, 'Yuddha Kanda, Sarga 32, Verse 20', 'उत्तरद्वारमासाद्य रामः सौमित्रिणा सह।
आवृत्य बलवांस्तस्थौ सुग्रीवश्च हरीश्वरः॥', 'uttaradvāram āsādya rāmaḥ saumitriṇā saha
āvṛtya balavāṃs tasthau sugrīvaś ca harīśvaraḥ', null, 6032020),
('ramayana-6-32-21', 21, 'Yuddha Kanda, Sarga 32, Verse 21', 'गोलाङ्गूलो महाकायो गवाक्षो भीमदर्शनः।
वृतः कोट्या महावीर्यस्तस्थौ रामस्य पार्वतः॥', 'golāṅgūlo mahākāyo gavākṣo bhīmadarśanaḥ
vṛtaḥ koṭyā mahāvīryas tasthau rāmasya pārvataḥ', null, 6032021),
('ramayana-6-32-22', 22, 'Yuddha Kanda, Sarga 32, Verse 22', 'ऋष्काणां भीमवेगानां धूम्रः शत्रुनिबर्हणः।
वृतः कोट्या महावीर्यस्तस्थौ रामस्य पार्श्वतः॥', 'ṛṣkāṇāṃ bhīmavegānāṃ dhūmraḥ śatrunibarhaṇaḥ
vṛtaḥ koṭyā mahāvīryas tasthau rāmasya pārśvataḥ', null, 6032022),
('ramayana-6-32-23', 23, 'Yuddha Kanda, Sarga 32, Verse 23', 'संनद्धस्तु महावीर्यो गदापाणिर्विभीषणः।
वृतो यस्तैस्तु सचिवैस्तस्थौ तत्र महाबलः॥', 'saṃnaddhas tu mahāvīryo gadāpāṇir vibhīṣaṇaḥ
vṛto yas tais tu sacivais tasthau tatra mahābalaḥ', null, 6032023),
('ramayana-6-32-24', 24, 'Yuddha Kanda, Sarga 32, Verse 24', 'गजो गवाक्षो गवयः शरभो गन्धमादनः।
समन्तात्परिघावन्तो ररक्षुर्हरिवाहिनीम्॥', 'gajo gavākṣo gavayaḥ śarabho gandhamādanaḥ
samantāt parighāvanto rarakṣur harivāhinīm', null, 6032024),
('ramayana-6-32-25', 25, 'Yuddha Kanda, Sarga 32, Verse 25', 'ततः कोपपरीतात्मा रावणो राक्षसेश्वरः।
निर्याणं सर्वसैन्यानां द्रुतमाज्ञापयत्तदा॥', 'tataḥ kopaparītātmā rāvaṇo rākṣaseśvaraḥ
niryāṇaṃ sarvasainyānāṃ drutam ājñāpayat tadā', null, 6032025),
('ramayana-6-32-26', 26, 'Yuddha Kanda, Sarga 32, Verse 26', 'निष्पतन्ति ततः सैन्या हृष्टा रावणचोदिताः।
समये पूर्यमाणस्य वेगा इव महोदधेः॥', 'niṣpatanti tataḥ sainyā hṛṣṭā rāvaṇacoditāḥ
samaye pūryamāṇasya vegā iva mahodadheḥ', null, 6032026),
('ramayana-6-32-27', 27, 'Yuddha Kanda, Sarga 32, Verse 27', 'एतस्मिन्नन्तरे घोरः संग्रामः समपद्यत।
रक्षसां वानराणां च यथा देवासुरे पुरा॥', 'etasminn antare ghoraḥ saṃgrāmaḥ samapadyata
rakṣasāṃ vānarāṇāṃ ca yathā devāsure purā', null, 6032027),
('ramayana-6-32-28', 28, 'Yuddha Kanda, Sarga 32, Verse 28', 'ते गदाभिः प्रदीप्ताभिः शक्तिशूलपरश्वधैः।
निजघ्नुर्वानरान्घोराः कथयन्तः स्वविक्रमान्॥', 'te gadābhiḥ pradīptābhiḥ śaktiśūlaparaśvadhaiḥ
nijaghnur vānarān ghorāḥ kathayantaḥ svavikramān', null, 6032028),
('ramayana-6-32-29', 29, 'Yuddha Kanda, Sarga 32, Verse 29', 'तथा वृक्षैर्महाकायाः पर्वताग्रैश्च वानराः।
राक्षसास्तानि रक्षांसि नखैर्दन्तैश्च वेगिताः॥', 'tathā vṛkṣair mahākāyāḥ parvatāgraiś ca vānarāḥ
rākṣasās tāni rakṣāṃsi nakhair dantaiś ca vegitāḥ', null, 6032029),
('ramayana-6-32-30', 30, 'Yuddha Kanda, Sarga 32, Verse 30', 'राक्षसास्त्वपरे भीमाः प्राकारस्था महीगतान्।
भिण्डिपालैश्च खड्गैश्च शूलैश्चैव व्यदारयन्॥', 'rākṣasās tv apare bhīmāḥ prākārasthā mahīgatān
bhiṇḍipālaiś ca khaḍgaiś ca śūlaiś caiva vyadārayan', null, 6032030),
('ramayana-6-32-31', 31, 'Yuddha Kanda, Sarga 32, Verse 31', 'वानराश्चापि संक्रुद्धाः प्राकारस्थान्महीगताः।
राक्षसान्पातयामासुः समाप्लुत्य प्लवंगमाः॥', 'vānarāś cāpi saṃkruddhāḥ prākārasthān mahīgatāḥ
rākṣasān pātayām āsuḥ samāplutya plavaṃgamāḥ', null, 6032031),
('ramayana-6-32-32', 32, 'Yuddha Kanda, Sarga 32, Verse 32', 'स संप्रहारस्तुमुलो मांसशोणितकर्दमः।
रक्षसां वानराणां च संबभूवाद्भुतोपमाः॥', 'sa saṃprahāras tumulo māṃsaśoṇitakardamaḥ
rakṣasāṃ vānarāṇāṃ ca saṃbabhūvādbhutopamāḥ', null, 6032032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 33 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-33-1', 1, 'Yuddha Kanda, Sarga 33, Verse 1', 'युध्यतां तु ततस्तेषां वानराणां महात्मनाम्।
रक्षसां संबभूवाथ बलकोपः सुदारुणः॥', 'yudhyatāṃ tu tatas teṣāṃ vānarāṇāṃ mahātmanām
rakṣasāṃ saṃbabhūvātha balakopaḥ sudāruṇaḥ', null, 6033001),
('ramayana-6-33-2', 2, 'Yuddha Kanda, Sarga 33, Verse 2', 'ते हयैः काञ्चनापीडैर्ध्वजैश्चाग्निशिखोपमैः।
रथैश्चादित्यसंकाशैः कवचैश्च मनोरमैः॥', 'te hayaiḥ kāñcanāpīḍair dhvajaiś cāgniśikhopamaiḥ
rathaiś cādityasaṃkāśaiḥ kavacaiś ca manoramaiḥ', null, 6033002),
('ramayana-6-33-3', 3, 'Yuddha Kanda, Sarga 33, Verse 3', 'निर्ययू राक्षसव्याघ्रा नादयन्तो दिशो दश।
राक्षसा भीमकर्माणो रावणस्य जयैषिणः॥', 'niryayū rākṣasavyāghrā nādayanto diśo daśa
rākṣasā bhīmakarmāṇo rāvaṇasya jayaiṣiṇaḥ', null, 6033003),
('ramayana-6-33-4', 4, 'Yuddha Kanda, Sarga 33, Verse 4', 'वानराणामपि चमूर्महती जयमिच्चताम्।
अभ्यधावत तां सेनां रक्षसां कामरूपिणाम्॥', 'vānarāṇām api camūr mahatī jayam iccatām
abhyadhāvata tāṃ senāṃ rakṣasāṃ kāmarūpiṇām', null, 6033004),
('ramayana-6-33-5', 5, 'Yuddha Kanda, Sarga 33, Verse 5', 'एतस्मिन्नन्तरे तेषामन्योन्यमभिधावताम्।
रक्षसां वानराणां च द्वन्द्वयुद्धमवर्तत॥', 'etasminn antare teṣām anyonyam abhidhāvatām
rakṣasāṃ vānarāṇāṃ ca dvandvayuddham avartata', null, 6033005),
('ramayana-6-33-6', 6, 'Yuddha Kanda, Sarga 33, Verse 6', 'अङ्गदेनेन्द्रजित्सार्धं वालिपुत्रेण राक्षसः।
अयुध्यत महातेजास्त्र्यम्बकेण यथान्धकः॥', 'aṅgadenendrajit sārdhaṃ vāliputreṇa rākṣasaḥ
ayudhyata mahātejās tryambakeṇa yathāndhakaḥ', null, 6033006),
('ramayana-6-33-7', 7, 'Yuddha Kanda, Sarga 33, Verse 7', 'प्रजङ्घेन च संपातिर्नित्यं दुर्मर्षणो रणे।
जम्बूमालिनमारब्धो हनूमानपि वानरः॥', 'prajaṅghena ca saṃpātir nityaṃ durmarṣaṇo raṇe
jambūmālinam ārabdho hanūmān api vānaraḥ', null, 6033007),
('ramayana-6-33-8', 8, 'Yuddha Kanda, Sarga 33, Verse 8', 'संगतः सुमहाक्रोधो राक्षसो रावणानुजः।
समरे तीक्ष्णवेगेन मित्रघ्नेन विभीषणः॥', 'saṃgataḥ sumahākrodho rākṣaso rāvaṇānujaḥ
samare tīkṣṇavegena mitraghnena vibhīṣaṇaḥ', null, 6033008),
('ramayana-6-33-9', 9, 'Yuddha Kanda, Sarga 33, Verse 9', 'तपनेन गजः सार्धं राक्षसेन महाबलः।
निकुम्भेन महातेजा नीलोऽपि समयुध्यत॥', 'tapanena gajaḥ sārdhaṃ rākṣasena mahābalaḥ
nikumbhena mahātejā nīlo ''pi samayudhyata', null, 6033009),
('ramayana-6-33-10', 10, 'Yuddha Kanda, Sarga 33, Verse 10', 'वानरेन्द्रस्तु सुग्रीवः प्रघसेन समागतः।
संगतः समरे श्रीमान्विरूपाक्षेण लक्ष्मणः॥', 'vānarendras tu sugrīvaḥ praghasena samāgataḥ
saṃgataḥ samare śrīmān virūpākṣeṇa lakṣmaṇaḥ', null, 6033010),
('ramayana-6-33-11', 11, 'Yuddha Kanda, Sarga 33, Verse 11', 'अग्निकेतुश्च दुर्धर्षो रश्मिकेतुश्च राक्षसः।
सुप्तघ्नो यज्ञकोपश्च रामेण सह संगताः॥', 'agniketuś ca durdharṣo raśmiketuś ca rākṣasaḥ
suptaghno yajñakopaś ca rāmeṇa saha saṃgatāḥ', null, 6033011),
('ramayana-6-33-12', 12, 'Yuddha Kanda, Sarga 33, Verse 12', 'वज्रमुष्टिस्तु मैन्देन द्विविदेनाशनिप्रभः।
राक्षसाभ्यां सुघोराभ्यां कपिमुख्यौ समागतौ॥', 'vajramuṣṭis tu maindena dvividenāśaniprabhaḥ
rākṣasābhyāṃ sughorābhyāṃ kapimukhyau samāgatau', null, 6033012),
('ramayana-6-33-13', 13, 'Yuddha Kanda, Sarga 33, Verse 13', 'वीरः प्रतपनो घोरो राक्षसो रणदुर्धरः।
समरे तीक्ष्णवेगेन नलेन समयुध्यत॥', 'vīraḥ pratapano ghoro rākṣaso raṇadurdharaḥ
samare tīkṣṇavegena nalena samayudhyata', null, 6033013),
('ramayana-6-33-14', 14, 'Yuddha Kanda, Sarga 33, Verse 14', 'धर्मस्य पुत्रो बलवान्सुषेण इति विश्रुतः।
स विद्युन्मालिना सार्धमयुध्यत महाकपिः॥', 'dharmasya putro balavān suṣeṇa iti viśrutaḥ
sa vidyunmālinā sārdham ayudhyata mahākapiḥ', null, 6033014),
('ramayana-6-33-15', 15, 'Yuddha Kanda, Sarga 33, Verse 15', 'वानराश्चापरे भीमा राक्षसैरपरैः सह।
द्वन्द्वं समीयुर्बहुधा युद्धाय बहुभिः सह॥', 'vānarāś cāpare bhīmā rākṣasair aparaiḥ saha
dvandvaṃ samīyur bahudhā yuddhāya bahubhiḥ saha', null, 6033015),
('ramayana-6-33-16', 16, 'Yuddha Kanda, Sarga 33, Verse 16', 'तत्रासीत्सुमहद्युद्धं तुमुलं लोमहर्षणम्।
रक्षसां वानराणां च वीराणां जयमिच्छताम्॥', 'tatrāsīt sumahad yuddhaṃ tumulaṃ lomaharṣaṇam
rakṣasāṃ vānarāṇāṃ ca vīrāṇāṃ jayam icchatām', null, 6033016),
('ramayana-6-33-17', 17, 'Yuddha Kanda, Sarga 33, Verse 17', 'हरिराक्षसदेहेभ्यः प्रसृताः केशशाड्वलाः।
शरीरसंघाटवहाः प्रसुस्रुः शोणितापगाः॥', 'harirākṣasadehebhyaḥ prasṛtāḥ keśaśāḍvalāḥ
śarīrasaṃghāṭavahāḥ prasusruḥ śoṇitāpagāḥ', null, 6033017),
('ramayana-6-33-18', 18, 'Yuddha Kanda, Sarga 33, Verse 18', 'आजघानेन्द्रजित्क्रुद्धो वज्रेणेव शतक्रतुः।
अङ्गदं गदया वीरं शत्रुसैन्यविदारणम्॥', 'ājaghānendrajit kruddho vajreṇeva śatakratuḥ
aṅgadaṃ gadayā vīraṃ śatrusainyavidāraṇam', null, 6033018),
('ramayana-6-33-19', 19, 'Yuddha Kanda, Sarga 33, Verse 19', 'तस्य काञ्चनचित्राङ्गं रथं साश्वं ससारथिम्।
जघान समरे श्रीमानङ्गदो वेगवान्कपिः॥', 'tasya kāñcanacitrāṅgaṃ rathaṃ sāśvaṃ sasārathim
jaghāna samare śrīmān aṅgado vegavān kapiḥ', null, 6033019),
('ramayana-6-33-20', 20, 'Yuddha Kanda, Sarga 33, Verse 20', 'संपातिस्तु त्रिभिर्बाणैः प्रजङ्घेन समाहतः।
निजघानाश्वकर्णेन प्रजङ्घं रणमूर्धनि॥', 'saṃpātis tu tribhir bāṇaiḥ prajaṅghena samāhataḥ
nijaghānāśvakarṇena prajaṅghaṃ raṇamūrdhani', null, 6033020),
('ramayana-6-33-21', 21, 'Yuddha Kanda, Sarga 33, Verse 21', 'जम्बूमाली रथस्थस्तु रथशक्त्या महाबलः।
बिभेद समरे क्रुद्धो हनूमन्तं स्तनान्तरे॥', 'jambūmālī rathasthas tu rathaśaktyā mahābalaḥ
bibheda samare kruddho hanūmantaṃ stanāntare', null, 6033021),
('ramayana-6-33-22', 22, 'Yuddha Kanda, Sarga 33, Verse 22', 'तस्य तं रथमास्थाय हनूमान्मारुतात्मजः।
प्रममाथ तलेनाशु सह तेनैव रक्षसा॥', 'tasya taṃ ratham āsthāya hanūmān mārutātmajaḥ
pramamātha talenāśu saha tenaiva rakṣasā', null, 6033022),
('ramayana-6-33-23', 23, 'Yuddha Kanda, Sarga 33, Verse 23', 'भिन्नगात्रः शरैस्तीक्ष्णैः क्षिप्रहस्तेन रक्षसा।
प्रजघानाद्रिशृङ्गेण तपनं मुष्टिना गजः॥', 'bhinnagātraḥ śarais tīkṣṇaiḥ kṣiprahastena rakṣasā
prajaghānādriśṛṅgeṇa tapanaṃ muṣṭinā gajaḥ', null, 6033023),
('ramayana-6-33-24', 24, 'Yuddha Kanda, Sarga 33, Verse 24', 'ग्रसन्तमिव सैन्यानि प्रघसं वानराधिपः।
सुग्रीवः सप्तपर्णेन निर्बिभेद जघान च॥', 'grasantam iva sainyāni praghasaṃ vānarādhipaḥ
sugrīvaḥ saptaparṇena nirbibheda jaghāna ca', null, 6033024),
('ramayana-6-33-25', 25, 'Yuddha Kanda, Sarga 33, Verse 25', 'प्रपीड्य शरवर्षेण राक्षसं भीमदर्शनम्।
निजघान विरूपाक्षं शरेणैकेन लक्ष्मणः॥', 'prapīḍya śaravarṣeṇa rākṣasaṃ bhīmadarśanam
nijaghāna virūpākṣaṃ śareṇaikena lakṣmaṇaḥ', null, 6033025),
('ramayana-6-33-26', 26, 'Yuddha Kanda, Sarga 33, Verse 26', 'अग्निकेतुश्च दुर्धर्षो रश्मिकेतुश्च राक्षसः।
सुप्तिघ्नो यज्ञकोपश्च रामं निर्बिभिदुः शरैः॥', 'agniketuś ca durdharṣo raśmiketuś ca rākṣasaḥ
suptighno yajñakopaś ca rāmaṃ nirbibhiduḥ śaraiḥ', null, 6033026),
('ramayana-6-33-27', 27, 'Yuddha Kanda, Sarga 33, Verse 27', 'तेषां चतुर्णां रामस्तु शिरांसि समरे शरैः।
क्रुद्धश्चतुर्भिश्चिच्छेद घोरैरग्निशिखोपमैः॥', 'teṣāṃ caturṇāṃ rāmas tu śirāṃsi samare śaraiḥ
kruddhaś caturbhiś ciccheda ghorair agniśikhopamaiḥ', null, 6033027),
('ramayana-6-33-28', 28, 'Yuddha Kanda, Sarga 33, Verse 28', 'वज्रमुष्टिस्तु मैन्देन मुष्टिना निहतो रणे।
पपात सरथः साश्वः पुराट्ट इव भूतले॥', 'vajramuṣṭis tu maindena muṣṭinā nihato raṇe
papāta sarathaḥ sāśvaḥ purāṭṭa iva bhūtale', null, 6033028),
('ramayana-6-33-29', 29, 'Yuddha Kanda, Sarga 33, Verse 29', 'वज्राशनिसमस्पर्शो द्विविदोऽप्यशनिप्रभम्।
जघान गिरिशृङ्गेण मिषतां सर्वरक्षसाम्॥', 'vajrāśanisamasparśo dvivido ''py aśaniprabham
jaghāna giriśṛṅgeṇa miṣatāṃ sarvarakṣasām', null, 6033029),
('ramayana-6-33-30', 30, 'Yuddha Kanda, Sarga 33, Verse 30', 'द्विविदं वानरेन्द्रं तु द्रुमयोधिनमाहवे।
शरैरशनिसंकाशैः स विव्याधाशनिप्रभः॥', 'dvividaṃ vānarendraṃ tu drumayodhinam āhave
śarair aśanisaṃkāśaiḥ sa vivyādhāśaniprabhaḥ', null, 6033030),
('ramayana-6-33-31', 31, 'Yuddha Kanda, Sarga 33, Verse 31', 'स शरैरतिविद्धाङ्गो द्विविदः क्रोधमूर्छितः।
सालेन सरथं साश्वं निजघानाशनिप्रभम्॥', 'sa śarair atividdhāṅgo dvividaḥ krodhamūrchitaḥ
sālena sarathaṃ sāśvaṃ nijaghānāśaniprabham', null, 6033031),
('ramayana-6-33-32', 32, 'Yuddha Kanda, Sarga 33, Verse 32', 'निकुम्भस्तु रणे नीलं नीलाञ्जनचयप्रभम्।
निर्बिभेद शरैस्तीक्ष्णैः करैर्मेघमिवांशुमान्॥', 'nikumbhas tu raṇe nīlaṃ nīlāñjanacayaprabham
nirbibheda śarais tīkṣṇaiḥ karair megham ivāṃśumān', null, 6033032),
('ramayana-6-33-33', 33, 'Yuddha Kanda, Sarga 33, Verse 33', 'पुनः शरशतेनाथ क्षिप्रहस्तो निशाचरः।
बिभेद समरे नीलं निकुम्भः प्रजहास च॥', 'punaḥ śaraśatenātha kṣiprahasto niśācaraḥ
bibheda samare nīlaṃ nikumbhaḥ prajahāsa ca', null, 6033033),
('ramayana-6-33-34', 34, 'Yuddha Kanda, Sarga 33, Verse 34', 'तस्यैव रथचक्रेण नीलो विष्णुरिवाहवे।
शिरश्चिच्छेद समरे निकुम्भस्य च सारथेः॥', 'tasyaiva rathacakreṇa nīlo viṣṇur ivāhave
śiraś ciccheda samare nikumbhasya ca sāratheḥ', null, 6033034),
('ramayana-6-33-35', 35, 'Yuddha Kanda, Sarga 33, Verse 35', 'विद्युन्माली रथस्थस्तु शरैः काञ्चनभूषणैः।
सुषेणं ताडयामास ननाद च मुहुर्मुहुः॥', 'vidyunmālī rathasthas tu śaraiḥ kāñcanabhūṣaṇaiḥ
suṣeṇaṃ tāḍayām āsa nanāda ca muhur muhuḥ', null, 6033035),
('ramayana-6-33-36', 36, 'Yuddha Kanda, Sarga 33, Verse 36', 'तं रथस्थमथो दृष्ट्वा सुषेणो वानरोत्तमः।
गिरिशृङ्गेण महता रथमाशु न्यपातयत्॥', 'taṃ rathastham atho dṛṣṭvā suṣeṇo vānarottamaḥ
giriśṛṅgeṇa mahatā ratham āśu nyapātayat', null, 6033036),
('ramayana-6-33-37', 37, 'Yuddha Kanda, Sarga 33, Verse 37', 'लाघवेन तु संयुक्तो विद्युन्माली निशाचरः।
अपक्रम्य रथात्तूर्णं गदापाणिः क्षितौ स्थितः॥', 'lāghavena tu saṃyukto vidyunmālī niśācaraḥ
apakramya rathāt tūrṇaṃ gadāpāṇiḥ kṣitau sthitaḥ', null, 6033037),
('ramayana-6-33-38', 38, 'Yuddha Kanda, Sarga 33, Verse 38', 'ततः क्रोधसमाविष्टः सुषेणो हरिपुंगवः।
शिलां सुमहतीं गृह्य निशाचरमभिद्रवत्॥', 'tataḥ krodhasamāviṣṭaḥ suṣeṇo haripuṃgavaḥ
śilāṃ sumahatīṃ gṛhya niśācaram abhidravat', null, 6033038),
('ramayana-6-33-39', 39, 'Yuddha Kanda, Sarga 33, Verse 39', 'तमापतन्तं गदया विद्युन्माली निशाचरः।
वक्षस्यभिजग्नानाशु सुषेणं हरिसत्तमम्॥', 'tam āpatantaṃ gadayā vidyunmālī niśācaraḥ
vakṣasy abhijagnānāśu suṣeṇaṃ harisattamam', null, 6033039),
('ramayana-6-33-40', 40, 'Yuddha Kanda, Sarga 33, Verse 40', 'गदाप्रहारं तं घोरमचिन्त्यप्लवगोत्तमः।
तां शिलां पातयामास तस्योरसि महामृधे॥', 'gadāprahāraṃ taṃ ghoram acintyaplavagottamaḥ
tāṃ śilāṃ pātayām āsa tasyorasi mahāmṛdhe', null, 6033040),
('ramayana-6-33-41', 41, 'Yuddha Kanda, Sarga 33, Verse 41', 'शिलाप्रहाराभिहतो विद्युन्माली निशाचरः।
निष्पिष्टहृदयो भूमौ गतासुर्निपपात ह॥', 'śilāprahārābhihato vidyunmālī niśācaraḥ
niṣpiṣṭahṛdayo bhūmau gatāsur nipapāta ha', null, 6033041),
('ramayana-6-33-42', 42, 'Yuddha Kanda, Sarga 33, Verse 42', 'एवं तैर्वानरैः शूरैः शूरास्ते रजनीचराः।
द्वन्द्वे विमृदितास्तत्र दैत्या इव दिवौकसैः॥', 'evaṃ tair vānaraiḥ śūraiḥ śūrās te rajanīcarāḥ
dvandve vimṛditās tatra daityā iva divaukasaiḥ', null, 6033042),
('ramayana-6-33-43', 43, 'Yuddha Kanda, Sarga 33, Verse 43', 'भल्लैः खड्गैर्गदाभिश्च शक्तितोमर पट्टसैः।
अपविद्धश्च भिन्नश्च रथैः सांग्रामिकैर्हयैः॥', 'bhallaiḥ khaḍgair gadābhiś ca śaktitomara paṭṭasaiḥ
apaviddhaś ca bhinnaś ca rathaiḥ sāṃgrāmikair hayaiḥ', null, 6033043),
('ramayana-6-33-44', 44, 'Yuddha Kanda, Sarga 33, Verse 44', 'निहतैः कुञ्जरैर्मत्तैस्तथा वानरराक्षसैः।
चक्राक्षयुगदण्डैश्च भग्नैर्धरणिसंश्रितैः।
बभूवायोधनं घोरं गोमायुगणसेवितम्॥', 'nihataiḥ kuñjarair mattais tathā vānararākṣasaiḥ
cakrākṣayugadaṇḍaiś ca bhagnair dharaṇisaṃśritaiḥ
babhūvāyodhanaṃ ghoraṃ gomāyugaṇasevitam', null, 6033044),
('ramayana-6-33-45', 45, 'Yuddha Kanda, Sarga 33, Verse 45', 'कबन्धानि समुत्पेतुर्दिक्षु वानररक्षसाम्।
विमर्दे तुमुले तस्मिन्देवासुररणोपमे॥', 'kabandhāni samutpetur dikṣu vānararakṣasām
vimarde tumule tasmin devāsuraraṇopame', null, 6033045),
('ramayana-6-33-46', 46, 'Yuddha Kanda, Sarga 33, Verse 46', 'विदार्यमाणा हरिपुंगवैस्तदा निशाचराः शोणितदिग्धगात्राः।
पुनः सुयुद्धं तरसा समाश्रिता दिवाकरस्यास्तमयाभिकाङ्क्षिणः॥', 'vidāryamāṇā haripuṃgavais tadā niśācarāḥ śoṇitadigdhagātrāḥ
punaḥ suyuddhaṃ tarasā samāśritā divākarasyāstamayābhikāṅkṣiṇaḥ', null, 6033046)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 34 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-34-1', 1, 'Yuddha Kanda, Sarga 34, Verse 1', 'युध्यतामेव तेषां तु तदा वानररक्षसाम्।
रविरस्तं गतो रात्रिः प्रवृत्ता प्राणहारिणी॥', 'yudhyatām eva teṣāṃ tu tadā vānararakṣasām
ravir astaṃ gato rātriḥ pravṛttā prāṇahāriṇī', null, 6034001),
('ramayana-6-34-2', 2, 'Yuddha Kanda, Sarga 34, Verse 2', 'अन्योन्यं बद्धवैराणां घोराणां जयमिच्छताम्।
संप्रवृत्तं निशायुद्धं तदा वारणरक्षसाम्॥', 'anyonyaṃ baddhavairāṇāṃ ghorāṇāṃ jayam icchatām
saṃpravṛttaṃ niśāyuddhaṃ tadā vāraṇarakṣasām', null, 6034002),
('ramayana-6-34-3', 3, 'Yuddha Kanda, Sarga 34, Verse 3', 'राक्षसोऽसीति हरयो हरिश्चासीति राक्षसाः।
अन्योन्यं समरे जघ्नुस्तस्मिंस्तमसि दारुणे॥', 'rākṣaso ''sīti harayo hariś cāsīti rākṣasāḥ
anyonyaṃ samare jaghnus tasmiṃs tamasi dāruṇe', null, 6034003),
('ramayana-6-34-4', 4, 'Yuddha Kanda, Sarga 34, Verse 4', 'जहि दारय चैतीति कथं विद्रवसीति च।
एवं सुतुमुलः शब्दस्तस्मिंस्तमसि शुश्रुवे॥', 'jahi dāraya caitīti kathaṃ vidravasīti ca
evaṃ sutumulaḥ śabdas tasmiṃs tamasi śuśruve', null, 6034004),
('ramayana-6-34-5', 5, 'Yuddha Kanda, Sarga 34, Verse 5', 'कालाः काञ्चनसंनाहास्तस्मिंस्तमसि राक्षसाः।
संप्रादृश्यन्त शैलेन्द्रा दीप्तौषधिवना इव॥', 'kālāḥ kāñcanasaṃnāhās tasmiṃs tamasi rākṣasāḥ
saṃprādṛśyanta śailendrā dīptauṣadhivanā iva', null, 6034005),
('ramayana-6-34-6', 6, 'Yuddha Kanda, Sarga 34, Verse 6', 'तस्मिंस्तमसि दुष्पारे राक्षसाः क्रोधमूर्छिताः।
परिपेतुर्महावेगा भक्षयन्तः प्लवंगमान्॥', 'tasmiṃs tamasi duṣpāre rākṣasāḥ krodhamūrchitāḥ
paripetur mahāvegā bhakṣayantaḥ plavaṃgamān', null, 6034006),
('ramayana-6-34-7', 7, 'Yuddha Kanda, Sarga 34, Verse 7', 'ते हयान्काञ्चनापीडन्ध्वजांश्चाग्निशिखोपमान्।
आप्लुत्य दशनैस्तीक्ष्णैर्भीमकोपा व्यदारयन्॥', 'te hayān kāñcanāpīḍan dhvajāṃś cāgniśikhopamān
āplutya daśanais tīkṣṇair bhīmakopā vyadārayan', null, 6034007),
('ramayana-6-34-8', 8, 'Yuddha Kanda, Sarga 34, Verse 8', 'कुञ्जरान्कुञ्जरारोहान्पताकाध्वजिनो रथान्।
चकर्षुश्च ददंशुश्च दशनैः क्रोधमूर्छिताः॥', 'kuñjarān kuñjarārohān patākādhvajino rathān
cakarṣuś ca dadaṃśuś ca daśanaiḥ krodhamūrchitāḥ', null, 6034008),
('ramayana-6-34-9', 9, 'Yuddha Kanda, Sarga 34, Verse 9', 'लक्ष्मणश्चापि रामश्च शरैराशीविषोमपैः।
दृश्यादृश्यानि रक्षांसि प्रवराणि निजघ्नतुः॥', 'lakṣmaṇaś cāpi rāmaś ca śarair āśīviṣomapaiḥ
dṛśyādṛśyāni rakṣāṃsi pravarāṇi nijaghnatuḥ', null, 6034009),
('ramayana-6-34-10', 10, 'Yuddha Kanda, Sarga 34, Verse 10', 'तुरंगखुरविध्वस्तं रथनेमिसमुद्धतम्।
रुरोध कर्णनेत्राणिण्युध्यतां धरणीरजः॥', 'turaṃgakhuravidhvastaṃ rathanemisamuddhatam
rurodha karṇanetrāṇiṇyudhyatāṃ dharaṇīrajaḥ', null, 6034010),
('ramayana-6-34-11', 11, 'Yuddha Kanda, Sarga 34, Verse 11', 'वर्तमाने तथा घोरे संग्रामे लोमहर्षणे।
रुधिरोदा महावेगा नद्यस्तत्र प्रसुस्रुवुः॥', 'vartamāne tathā ghore saṃgrāme lomaharṣaṇe
rudhirodā mahāvegā nadyas tatra prasusruvuḥ', null, 6034011),
('ramayana-6-34-12', 12, 'Yuddha Kanda, Sarga 34, Verse 12', 'ततो भेरीमृदङ्गानां पणवानां च निस्वनः।
शङ्खवेणुस्वनोन्मिश्रः संबभूवाद्भुतोपमः॥', 'tato bherīmṛdaṅgānāṃ paṇavānāṃ ca nisvanaḥ
śaṅkhaveṇusvanonmiśraḥ saṃbabhūvādbhutopamaḥ', null, 6034012),
('ramayana-6-34-13', 13, 'Yuddha Kanda, Sarga 34, Verse 13', 'हतानां स्तनमानानां राक्षसानां च निस्वनः।
शस्त्राणां वानराणां च संबभूवातिदारुणः॥', 'hatānāṃ stanamānānāṃ rākṣasānāṃ ca nisvanaḥ
śastrāṇāṃ vānarāṇāṃ ca saṃbabhūvātidāruṇaḥ', null, 6034013),
('ramayana-6-34-14', 14, 'Yuddha Kanda, Sarga 34, Verse 14', 'शस्त्रपुष्पोपहारा च तत्रासीद्युद्धमेदिनी।
दुर्ज्ञेया दुर्निवेशा च शोणितास्रवकर्दमा॥', 'śastrapuṣpopahārā ca tatrāsīd yuddhamedinī
durjñeyā durniveśā ca śoṇitāsravakardamā', null, 6034014),
('ramayana-6-34-15', 15, 'Yuddha Kanda, Sarga 34, Verse 15', 'सा बभूव निशा घोरा हरिराक्षसहारिणी।
कालरात्रीव भूतानां सर्वेषां दुरतिक्रमा॥', 'sā babhūva niśā ghorā harirākṣasahāriṇī
kālarātrīva bhūtānāṃ sarveṣāṃ duratikramā', null, 6034015),
('ramayana-6-34-16', 16, 'Yuddha Kanda, Sarga 34, Verse 16', 'ततस्ते राक्षसास्तत्र तस्मिंस्तमसि दारुणे।
राममेवाभ्यधावन्त संहृष्टा शरवृष्टिभिः॥', 'tatas te rākṣasās tatra tasmiṃs tamasi dāruṇe
rāmam evābhyadhāvanta saṃhṛṣṭā śaravṛṣṭibhiḥ', null, 6034016),
('ramayana-6-34-17', 17, 'Yuddha Kanda, Sarga 34, Verse 17', 'तेषामापततां शब्दः क्रुद्धानामभिगर्जताम्।
उद्वर्त इव सप्तानां समुद्राणामभूत्स्वनः॥', 'teṣām āpatatāṃ śabdaḥ kruddhānām abhigarjatām
udvarta iva saptānāṃ samudrāṇām abhūt svanaḥ', null, 6034017),
('ramayana-6-34-18', 18, 'Yuddha Kanda, Sarga 34, Verse 18', 'तेषां रामः शरैः षड्भिः षड्जघान निशाचरान्।
निमेषान्तरमात्रेण शितैरग्निशिखोपमैः॥', 'teṣāṃ rāmaḥ śaraiḥ ṣaḍbhiḥ ṣaḍ jaghāna niśācarān
nimeṣāntaramātreṇa śitair agniśikhopamaiḥ', null, 6034018),
('ramayana-6-34-19', 19, 'Yuddha Kanda, Sarga 34, Verse 19', 'यज्ञशत्रुश्च दुर्धर्षो महापार्श्वमहोदरौ।
वज्रदंष्ट्रो महाकायस्तौ चोभौ शुकसारणौ॥', 'yajñaśatruś ca durdharṣo mahāpārśvamahodarau
vajradaṃṣṭro mahākāyas tau cobhau śukasāraṇau', null, 6034019),
('ramayana-6-34-20', 20, 'Yuddha Kanda, Sarga 34, Verse 20', 'ते तु रामेण बाणौघः सर्वमर्मसु ताडिताः।
युद्धादपसृतास्तत्र सावशेषायुषोऽभवन्॥', 'te tu rāmeṇa bāṇaughaḥ sarvamarmasu tāḍitāḥ
yuddhād apasṛtās tatra sāvaśeṣāyuṣo ''bhavan', null, 6034020),
('ramayana-6-34-21', 21, 'Yuddha Kanda, Sarga 34, Verse 21', 'ततः काञ्चनचित्राङ्गैः शरैरग्निशिखोपमैः।
दिशश्चकार विमलाः प्रदिशश्च महाबलः॥', 'tataḥ kāñcanacitrāṅgaiḥ śarair agniśikhopamaiḥ
diśaś cakāra vimalāḥ pradiśaś ca mahābalaḥ', null, 6034021),
('ramayana-6-34-22', 22, 'Yuddha Kanda, Sarga 34, Verse 22', 'ये त्वन्ये राक्षसा वीरा रामस्याभिमुखे स्थिताः।
तेऽपि नष्टाः समासाद्य पतंगा इव पावकम्॥', 'ye tv anye rākṣasā vīrā rāmasyābhimukhe sthitāḥ
te ''pi naṣṭāḥ samāsādya pataṃgā iva pāvakam', null, 6034022),
('ramayana-6-34-23', 23, 'Yuddha Kanda, Sarga 34, Verse 23', 'सुवर्णपुङ्खैर्विशिखैः संपतद्भिः सहस्रशः।
बभूव रजनी चित्रा खद्योतैरिव शारदी॥', 'suvarṇapuṅkhair viśikhaiḥ saṃpatadbhiḥ sahasraśaḥ
babhūva rajanī citrā khadyotair iva śāradī', null, 6034023),
('ramayana-6-34-24', 24, 'Yuddha Kanda, Sarga 34, Verse 24', 'राक्षसानां च निनदैर्हरीणां चापि गर्जितैः।
सा बभूव निशा घोरा भूयो घोरतरा तदा॥', 'rākṣasānāṃ ca ninadair harīṇāṃ cāpi garjitaiḥ
sā babhūva niśā ghorā bhūyo ghoratarā tadā', null, 6034024),
('ramayana-6-34-25', 25, 'Yuddha Kanda, Sarga 34, Verse 25', 'तेन शब्देन महता प्रवृद्धेन समन्ततः।
त्रिकूटः कन्दराकीर्णः प्रव्याहरदिवाचलः॥', 'tena śabdena mahatā pravṛddhena samantataḥ
trikūṭaḥ kandarākīrṇaḥ pravyāharad ivācalaḥ', null, 6034025),
('ramayana-6-34-26', 26, 'Yuddha Kanda, Sarga 34, Verse 26', 'गोलाङ्गूला महाकायास्तमसा तुल्यवर्चसः।
संपरिष्वज्य बाहुभ्यां भक्षयन्रजनीचरान्॥', 'golāṅgūlā mahākāyās tamasā tulyavarcasaḥ
saṃpariṣvajya bāhubhyāṃ bhakṣayan rajanīcarān', null, 6034026),
('ramayana-6-34-27', 27, 'Yuddha Kanda, Sarga 34, Verse 27', 'अङ्गदस्तु रणे शत्रुं निहन्तुं समुपस्थितः।
रावणेर्निजघानाशु सारथिं च हयानपि॥', 'aṅgadas tu raṇe śatruṃ nihantuṃ samupasthitaḥ
rāvaṇer nijaghānāśu sārathiṃ ca hayān api', null, 6034027),
('ramayana-6-34-28', 28, 'Yuddha Kanda, Sarga 34, Verse 28', 'इन्द्रजित्तु रथं त्यक्त्वा हताश्वो हतसारथिः।
अङ्गदेन महामायस्तत्रैवान्तरधीयत॥', 'indrajit tu rathaṃ tyaktvā hatāśvo hatasārathiḥ
aṅgadena mahāmāyas tatraivāntaradhīyata', null, 6034028),
('ramayana-6-34-29', 29, 'Yuddha Kanda, Sarga 34, Verse 29', 'सोऽन्तर्धान गतः पापो रावणी रणकर्कशः।
ब्रह्मदत्तवरो वीरो रावणिः क्रोधमूर्छितः।
अदृश्यो निशितान्बाणान्मुमोचाशनिवर्चसः॥', 'so ''ntardhāna gataḥ pāpo rāvaṇī raṇakarkaśaḥ
brahmadattavaro vīro rāvaṇiḥ krodhamūrchitaḥ
adṛśyo niśitān bāṇān mumocāśanivarcasaḥ', null, 6034029),
('ramayana-6-34-30', 30, 'Yuddha Kanda, Sarga 34, Verse 30', 'स रामं लक्ष्मणं चैव घोरैर्नागमयैः शरैः।
बिभेद समरे क्रुद्धः सर्वगात्रेषु राक्षसः॥', 'sa rāmaṃ lakṣmaṇaṃ caiva ghorair nāgamayaiḥ śaraiḥ
bibheda samare kruddhaḥ sarvagātreṣu rākṣasaḥ', null, 6034030)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 35 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-35-1', 1, 'Yuddha Kanda, Sarga 35, Verse 1', 'स तस्य गतिमन्विच्छन्राजपुत्रः प्रतापवान्।
दिदेशातिबलो रामो दशवानरयूथपान्॥', 'sa tasya gatim anvicchan rājaputraḥ pratāpavān
dideśātibalo rāmo daśavānarayūthapān', null, 6035001),
('ramayana-6-35-2', 2, 'Yuddha Kanda, Sarga 35, Verse 2', 'द्वौ सुषेणस्य दायादौ नीलं च प्लवगर्षभम्।
अङ्गदं वालिपुत्रं च शरभं च तरस्विनम्॥', 'dvau suṣeṇasya dāyādau nīlaṃ ca plavagarṣabham
aṅgadaṃ vāliputraṃ ca śarabhaṃ ca tarasvinam', null, 6035002),
('ramayana-6-35-3', 3, 'Yuddha Kanda, Sarga 35, Verse 3', 'विनतं जाम्बवन्तं च सानुप्रस्थं महाबलम्।
ऋषभं चर्षभस्कन्धमादिदेश परंतपः॥', 'vinataṃ jāmbavantaṃ ca sānuprasthaṃ mahābalam
ṛṣabhaṃ carṣabhaskandham ādideśa paraṃtapaḥ', null, 6035003),
('ramayana-6-35-4', 4, 'Yuddha Kanda, Sarga 35, Verse 4', 'ते संप्रहृष्टा हरयो भीमानुद्यम्य पादपान्।
आकाशं विविशुः सर्वे मार्गामाणा दिशो दश॥', 'te saṃprahṛṣṭā harayo bhīmān udyamya pādapān
ākāśaṃ viviśuḥ sarve mārgāmāṇā diśo daśa', null, 6035004),
('ramayana-6-35-5', 5, 'Yuddha Kanda, Sarga 35, Verse 5', 'तेषां वेगवतां वेगमिषुभिर्वेगवत्तरैः।
अस्त्रवित्परमास्त्रेण वारयामास रावणिः॥', 'teṣāṃ vegavatāṃ vegam iṣubhir vegavattaraiḥ
astravit paramāstreṇa vārayām āsa rāvaṇiḥ', null, 6035005),
('ramayana-6-35-6', 6, 'Yuddha Kanda, Sarga 35, Verse 6', 'तं भीमवेगा हरयो नाराचैः क्षतविक्षताः।
अन्धकारे न ददृशुर्मेघैः सूर्यमिवावृतम्॥', 'taṃ bhīmavegā harayo nārācaiḥ kṣatavikṣatāḥ
andhakāre na dadṛśur meghaiḥ sūryam ivāvṛtam', null, 6035006),
('ramayana-6-35-7', 7, 'Yuddha Kanda, Sarga 35, Verse 7', 'रामलक्ष्मणयोरेव सर्वमर्मभिदः शरान्।
भृशमावेशयामास रावणिः समितिंजयः॥', 'rāmalakṣmaṇayor eva sarvamarmabhidaḥ śarān
bhṛśam āveśayām āsa rāvaṇiḥ samitiṃjayaḥ', null, 6035007),
('ramayana-6-35-8', 8, 'Yuddha Kanda, Sarga 35, Verse 8', 'निरन्तरशरीरौ तु भ्रातरौ रामलक्ष्मणौ।
क्रुद्धेनेन्द्रजिता वीरौ पन्नगैः शरतां गतैः॥', 'nirantaraśarīrau tu bhrātarau rāmalakṣmaṇau
kruddhenendrajitā vīrau pannagaiḥ śaratāṃ gataiḥ', null, 6035008),
('ramayana-6-35-9', 9, 'Yuddha Kanda, Sarga 35, Verse 9', 'तयोः क्षतजमार्गेण सुस्राव रुधिरं बहु।
तावुभौ च प्रकाशेते पुष्पिताविव किंशुकौ॥', 'tayoḥ kṣatajamārgeṇa susrāva rudhiraṃ bahu
tāv ubhau ca prakāśete puṣpitāv iva kiṃśukau', null, 6035009),
('ramayana-6-35-10', 10, 'Yuddha Kanda, Sarga 35, Verse 10', 'ततः पर्यन्तरक्ताक्षो भिन्नाञ्जनचयोपमः।
रावणिर्भ्रातरौ वाक्यमन्तर्धानगतोऽब्रवीत्॥', 'tataḥ paryantaraktākṣo bhinnāñjanacayopamaḥ
rāvaṇir bhrātarau vākyam antardhānagato ''bravīt', null, 6035010),
('ramayana-6-35-11', 11, 'Yuddha Kanda, Sarga 35, Verse 11', 'युध्यमानमनालक्ष्यं शक्रोऽपि त्रिदशेश्वरः।
द्रष्टुमासादितुं वापि न शक्तः किं पुनर्युवाम्॥', 'yudhyamānam anālakṣyaṃ śakro ''pi tridaśeśvaraḥ
draṣṭum āsādituṃ vāpi na śaktaḥ kiṃ punar yuvām', null, 6035011),
('ramayana-6-35-12', 12, 'Yuddha Kanda, Sarga 35, Verse 12', 'प्रावृताविषुजालेन राघवौ कङ्कपत्रिणा।
एष रोषपरीतात्मा नयामि यमसादनम्॥', 'prāvṛtāv iṣujālena rāghavau kaṅkapatriṇā
eṣa roṣaparītātmā nayāmi yamasādanam', null, 6035012),
('ramayana-6-35-13', 13, 'Yuddha Kanda, Sarga 35, Verse 13', 'एवमुक्त्वा तु धर्मज्ञौ भ्रातरौ रामलक्ष्मणौ।
निर्बिभेद शितैर्बाणैः प्रजहर्ष ननाद च॥', 'evam uktvā tu dharmajñau bhrātarau rāmalakṣmaṇau
nirbibheda śitair bāṇaiḥ prajaharṣa nanāda ca', null, 6035013),
('ramayana-6-35-14', 14, 'Yuddha Kanda, Sarga 35, Verse 14', 'भिन्नाञ्जनचयश्यामो विस्फार्य विपुलं धनुः।
भूयो भूयः शरान्घोरान्विससर्ज महामृधे॥', 'bhinnāñjanacayaśyāmo visphārya vipulaṃ dhanuḥ
bhūyo bhūyaḥ śarān ghorān visasarja mahāmṛdhe', null, 6035014),
('ramayana-6-35-15', 15, 'Yuddha Kanda, Sarga 35, Verse 15', 'ततो मर्मसु मर्मज्ञो मज्जयन्निशिताञ्शरान्।
रामलक्ष्मणयोर्वीरो ननाद च मुहुर्मुहुः॥', 'tato marmasu marmajño majjayan niśitāñ śarān
rāmalakṣmaṇayor vīro nanāda ca muhur muhuḥ', null, 6035015),
('ramayana-6-35-16', 16, 'Yuddha Kanda, Sarga 35, Verse 16', 'बद्धौ तु शरबन्धेन तावुभौ रणमूर्धनि।
निमेषान्तरमात्रेण न शेकतुरुदीक्षितुम्॥', 'baddhau tu śarabandhena tāv ubhau raṇamūrdhani
nimeṣāntaramātreṇa na śekatur udīkṣitum', null, 6035016),
('ramayana-6-35-17', 17, 'Yuddha Kanda, Sarga 35, Verse 17', 'ततो विभिन्नसर्वाङ्गौ शरशल्याचितावुभौ।
ध्वजाविव महेन्द्रस्य रज्जुमुक्तौ प्रकम्पितौ॥', 'tato vibhinnasarvāṅgau śaraśalyācitāv ubhau
dhvajāv iva mahendrasya rajjumuktau prakampitau', null, 6035017),
('ramayana-6-35-18', 18, 'Yuddha Kanda, Sarga 35, Verse 18', 'तौ संप्रचलितौ वीरौ मर्मभेदेन कर्शितौ।
निपेततुर्महेष्वासौ जगत्यां जगतीपती॥', 'tau saṃpracalitau vīrau marmabhedena karśitau
nipetatur maheṣvāsau jagatyāṃ jagatīpatī', null, 6035018),
('ramayana-6-35-19', 19, 'Yuddha Kanda, Sarga 35, Verse 19', 'तौ वीरशयने वीरौ शयानौ रुधिरोक्षितौ।
शरवेष्टितसर्वाङ्गावार्तौ परमपीडितौ॥', 'tau vīraśayane vīrau śayānau rudhirokṣitau
śaraveṣṭitasarvāṅgāv ārtau paramapīḍitau', null, 6035019),
('ramayana-6-35-20', 20, 'Yuddha Kanda, Sarga 35, Verse 20', 'न ह्यविद्धं तयोर्गात्रं बभूवाङ्गुलमन्तरम्।
नानिर्भिन्नं न चास्तब्धमा कराग्रादजिह्मगैः॥', 'na hy aviddhaṃ tayor gātraṃ babhūvāṅgulam antaram
nānirbhinnaṃ na cāstabdham ā karāgrād ajihmagaiḥ', null, 6035020),
('ramayana-6-35-21', 21, 'Yuddha Kanda, Sarga 35, Verse 21', 'तौ तु क्रूरेण निहतौ रक्षसा कामरूपिणा।
असृक्सुस्रुवतुस्तीव्रं जलं प्रस्रवणाविव॥', 'tau tu krūreṇa nihatau rakṣasā kāmarūpiṇā
asṛksusruvatus tīvraṃ jalaṃ prasravaṇāv iva', null, 6035021),
('ramayana-6-35-22', 22, 'Yuddha Kanda, Sarga 35, Verse 22', 'पपात प्रथमं रामो विद्धो मर्मसु मार्गणैः।
क्रोधादिन्द्रजिता येन पुरा शक्रो विनिर्जितः॥', 'papāta prathamaṃ rāmo viddho marmasu mārgaṇaiḥ
krodhād indrajitā yena purā śakro vinirjitaḥ', null, 6035022),
('ramayana-6-35-23', 23, 'Yuddha Kanda, Sarga 35, Verse 23', 'नारचैरर्धनाराचैर्भल्लैरञ्जलिकैरपि।
विव्याध वत्सदन्तैश्च सिंहदंष्ट्रैः क्षुरैस्तथा॥', 'nāracair ardhanārācair bhallair añjalikair api
vivyādha vatsadantaiś ca siṃhadaṃṣṭraiḥ kṣurais tathā', null, 6035023),
('ramayana-6-35-24', 24, 'Yuddha Kanda, Sarga 35, Verse 24', 'स वीरशयने शिश्ये विज्यमादाय कार्मुकम्।
भिन्नमुष्टिपरीणाहं त्रिणतं रुक्मभूषितम्॥', 'sa vīraśayane śiśye vijyam ādāya kārmukam
bhinnamuṣṭiparīṇāhaṃ triṇataṃ rukmabhūṣitam', null, 6035024),
('ramayana-6-35-25', 25, 'Yuddha Kanda, Sarga 35, Verse 25', 'बाणपातान्तरे रामं पतितं पुरुषर्षभम्।
स तत्र लक्ष्मणो दृष्ट्वा निराशो जीवितेऽभवत्॥', 'bāṇapātāntare rāmaṃ patitaṃ puruṣarṣabham
sa tatra lakṣmaṇo dṛṣṭvā nirāśo jīvite ''bhavat', null, 6035025),
('ramayana-6-35-26', 26, 'Yuddha Kanda, Sarga 35, Verse 26', 'बद्धौ तु वीरौ पतितौ शयानौ तौ वानराः संपरिवार्य तस्थुः।
समागता वायुसुतप्रमुख्या विषदमार्ताः परमं च जग्मुः॥', 'baddhau tu vīrau patitau śayānau tau vānarāḥ saṃparivārya tasthuḥ
samāgatā vāyusutapramukhyā viṣadam ārtāḥ paramaṃ ca jagmuḥ', null, 6035026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 36 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-36-1', 1, 'Yuddha Kanda, Sarga 36, Verse 1', 'ततो द्यां पृथिवीं चैव वीक्षमाणा वनौकसः।
ददृशुः संततौ बाणैर्भ्रातरौ रामलक्ष्मणौ॥', 'tato dyāṃ pṛthivīṃ caiva vīkṣamāṇā vanaukasaḥ
dadṛśuḥ saṃtatau bāṇair bhrātarau rāmalakṣmaṇau', null, 6036001),
('ramayana-6-36-2', 2, 'Yuddha Kanda, Sarga 36, Verse 2', 'वृष्ट्वेवोपरते देवे कृतकर्मणि राक्षसे।
आजगामाथ तं देशं ससुग्रीवो विभीषणः॥', 'vṛṣṭvevoparate deve kṛtakarmaṇi rākṣase
ājagāmātha taṃ deśaṃ sasugrīvo vibhīṣaṇaḥ', null, 6036002),
('ramayana-6-36-3', 3, 'Yuddha Kanda, Sarga 36, Verse 3', 'नीलद्विविदमैन्दाश्च सुषेणसुमुखाङ्गदाः।
तूर्णं हनुमता सार्धमन्वशोचन्त राघवौ॥', 'nīladvividamaindāś ca suṣeṇasumukhāṅgadāḥ
tūrṇaṃ hanumatā sārdham anvaśocanta rāghavau', null, 6036003),
('ramayana-6-36-4', 4, 'Yuddha Kanda, Sarga 36, Verse 4', 'निश्चेष्टौ मन्दनिःश्वासौ शोणितौघपरिप्लुतौ।
शरजालाचितौ स्तब्धौ शयानौ शरतल्पयोः॥', 'niśceṣṭau mandaniḥśvāsau śoṇitaughapariplutau
śarajālācitau stabdhau śayānau śaratalpayoḥ', null, 6036004),
('ramayana-6-36-5', 5, 'Yuddha Kanda, Sarga 36, Verse 5', 'निःश्वसन्तौ यथा सर्पौ निश्चेष्टौ मन्दविक्रमौ।
रुधिरस्रावदिग्धाङ्गौ तापनीयाविव ध्वजौ॥', 'niḥśvasantau yathā sarpau niśceṣṭau mandavikramau
rudhirasrāvadigdhāṅgau tāpanīyāv iva dhvajau', null, 6036005),
('ramayana-6-36-6', 6, 'Yuddha Kanda, Sarga 36, Verse 6', 'तौ वीरशयने वीरौ शयानौ मन्दचेष्टितौ।
यूथपैस्तैः परिवृतौ बाष्पव्याकुललोचनैः॥', 'tau vīraśayane vīrau śayānau mandaceṣṭitau
yūthapais taiḥ parivṛtau bāṣpavyākulalocanaiḥ', null, 6036006),
('ramayana-6-36-7', 7, 'Yuddha Kanda, Sarga 36, Verse 7', 'राघवौ पतितौ दृष्ट्वा शरजालसमावृतौ।
बभूवुर्व्यथिताः सर्वे वानराः सविभीषणाः॥', 'rāghavau patitau dṛṣṭvā śarajālasamāvṛtau
babhūvur vyathitāḥ sarve vānarāḥ savibhīṣaṇāḥ', null, 6036007),
('ramayana-6-36-8', 8, 'Yuddha Kanda, Sarga 36, Verse 8', 'अन्तरिक्षं निरीक्षन्तो दिशः सर्वाश्च वानराः।
न चैनं मायया छन्नं ददृशू रावणिं रणे॥', 'antarikṣaṃ nirīkṣanto diśaḥ sarvāś ca vānarāḥ
na cainaṃ māyayā channaṃ dadṛśū rāvaṇiṃ raṇe', null, 6036008),
('ramayana-6-36-9', 9, 'Yuddha Kanda, Sarga 36, Verse 9', 'तं तु मायाप्रतिच्छिन्नं माययैव विभीषणः।
वीक्षमाणो ददर्शाथ भ्रातुः पुत्रमवस्थितम्॥', 'taṃ tu māyāpraticchinnaṃ māyayaiva vibhīṣaṇaḥ
vīkṣamāṇo dadarśātha bhrātuḥ putram avasthitam', null, 6036009),
('ramayana-6-36-10', 10, 'Yuddha Kanda, Sarga 36, Verse 10', 'तमप्रतिम कर्माणमप्रतिद्वन्द्वमाहवे।
ददर्शान्तर्हितं वीरं वरदानाद्विभीषणः॥', 'tam apratima karmāṇam apratidvandvam āhave
dadarśāntarhitaṃ vīraṃ varadānād vibhīṣaṇaḥ', null, 6036010),
('ramayana-6-36-11', 11, 'Yuddha Kanda, Sarga 36, Verse 11', 'इन्द्रजित्त्वात्मनः कर्म तौ शयानौ समीक्ष्य च।
उवाच परमप्रीतो हर्षयन्सर्वनैरृतान्॥', 'indrajit tv ātmanaḥ karma tau śayānau samīkṣya ca
uvāca paramaprīto harṣayan sarvanairṛtān', null, 6036011),
('ramayana-6-36-12', 12, 'Yuddha Kanda, Sarga 36, Verse 12', 'दूषणस्य च हन्तारौ खरस्य च महाबलौ।
सादितौ मामकैर्बाणैर्भ्रातरौ रामलक्ष्मणौ॥', 'dūṣaṇasya ca hantārau kharasya ca mahābalau
sāditau māmakair bāṇair bhrātarau rāmalakṣmaṇau', null, 6036012),
('ramayana-6-36-13', 13, 'Yuddha Kanda, Sarga 36, Verse 13', 'नेमौ मोक्षयितुं शक्यावेतस्मादिषुबन्धनात्।
सर्वैरपि समागम्य सर्षिसङ्घैः सुरासुरैः॥', 'nemau mokṣayituṃ śakyāv etasmād iṣubandhanāt
sarvair api samāgamya sarṣisaṅghaiḥ surāsuraiḥ', null, 6036013),
('ramayana-6-36-14', 14, 'Yuddha Kanda, Sarga 36, Verse 14', 'यत्कृते चिन्तयानस्य शोकार्तस्य पितुर्मम।
अस्पृष्ट्वा शयनं गात्रैस्त्रियामा याति शर्वती॥', 'yatkṛte cintayānasya śokārtasya pitur mama
aspṛṣṭvā śayanaṃ gātrais triyāmā yāti śarvatī', null, 6036014),
('ramayana-6-36-15', 15, 'Yuddha Kanda, Sarga 36, Verse 15', 'कृत्स्नेयं यत्कृते लङ्का नदी वर्षास्विवाकुला।
सोऽयं मूलहरोऽनर्थः सर्वेषां निहतो मया॥', 'kṛtsneyaṃ yatkṛte laṅkā nadī varṣāsv ivākulā
so ''yaṃ mūlaharo ''narthaḥ sarveṣāṃ nihato mayā', null, 6036015),
('ramayana-6-36-16', 16, 'Yuddha Kanda, Sarga 36, Verse 16', 'रामस्य लक्ष्मणस्यैव सर्वेषां च वनौकसाम्।
विक्रमा निष्फलाः सर्वे यथा शरदि तोयदाः॥', 'rāmasya lakṣmaṇasyaiva sarveṣāṃ ca vanaukasām
vikramā niṣphalāḥ sarve yathā śaradi toyadāḥ', null, 6036016),
('ramayana-6-36-17', 17, 'Yuddha Kanda, Sarga 36, Verse 17', 'एवमुक्त्वा तु तान्सर्वान्राक्षसान्परिपार्श्वगान्।
यूथपानपि तान्सर्वांस्ताडयामास रावणिः॥', 'evam uktvā tu tān sarvān rākṣasān paripārśvagān
yūthapān api tān sarvāṃs tāḍayām āsa rāvaṇiḥ', null, 6036017),
('ramayana-6-36-18', 18, 'Yuddha Kanda, Sarga 36, Verse 18', 'तानर्दयित्वा बाणौघैस्त्रासयित्वा च वानरान्।
प्रजहास महाबाहुर्वचनं चेदमब्रवीत्॥', 'tān ardayitvā bāṇaughais trāsayitvā ca vānarān
prajahāsa mahābāhur vacanaṃ cedam abravīt', null, 6036018),
('ramayana-6-36-19', 19, 'Yuddha Kanda, Sarga 36, Verse 19', 'शरबन्धेन घोरेण मया बद्धौ चमूमुखे।
सहितौ भ्रातरावेतौ निशामयत राक्षसाः॥', 'śarabandhena ghoreṇa mayā baddhau camūmukhe
sahitau bhrātarāv etau niśāmayata rākṣasāḥ', null, 6036019),
('ramayana-6-36-20', 20, 'Yuddha Kanda, Sarga 36, Verse 20', 'एवमुक्तास्तु ते सर्वे राक्षसाः कूटयोधिनः।
परं विस्मयमाजग्मुः कर्मणा तेन तोषिताः॥', 'evam uktās tu te sarve rākṣasāḥ kūṭayodhinaḥ
paraṃ vismayam ājagmuḥ karmaṇā tena toṣitāḥ', null, 6036020),
('ramayana-6-36-21', 21, 'Yuddha Kanda, Sarga 36, Verse 21', 'विनेदुश्च महानादान्सर्वे ते जलदोपमाः।
हतो राम इति ज्ञात्वा रावणिं समपूजयन्॥', 'vineduś ca mahānādān sarve te jaladopamāḥ
hato rāma iti jñātvā rāvaṇiṃ samapūjayan', null, 6036021),
('ramayana-6-36-22', 22, 'Yuddha Kanda, Sarga 36, Verse 22', 'निष्पन्दौ तु तदा दृष्ट्वा तावुभौ रामलक्ष्मणौ।
वसुधायां निरुच्छ्वासौ हतावित्यन्वमन्यत॥', 'niṣpandau tu tadā dṛṣṭvā tāv ubhau rāmalakṣmaṇau
vasudhāyāṃ nirucchvāsau hatāv ity anvamanyata', null, 6036022),
('ramayana-6-36-23', 23, 'Yuddha Kanda, Sarga 36, Verse 23', 'हर्षेण तु समाविष्ट इन्द्रजित्समितिंजयः।
प्रविवेश पुरीं लङ्कां हर्षयन्सर्वनैरृतान्॥', 'harṣeṇa tu samāviṣṭa indrajit samitiṃjayaḥ
praviveśa purīṃ laṅkāṃ harṣayan sarvanairṛtān', null, 6036023),
('ramayana-6-36-24', 24, 'Yuddha Kanda, Sarga 36, Verse 24', 'रामलक्ष्मणयोर्दृष्ट्वा शरीरे सायकैश्चिते।
सर्वाणि चाङ्गोपाङ्गानि सुग्रीवं भयमाविशत्॥', 'rāmalakṣmaṇayor dṛṣṭvā śarīre sāyakaiś cite
sarvāṇi cāṅgopāṅgāni sugrīvaṃ bhayam āviśat', null, 6036024),
('ramayana-6-36-25', 25, 'Yuddha Kanda, Sarga 36, Verse 25', 'तमुवाच परित्रस्तं वानरेन्द्रं विभीषणः।
सबाष्पवदनं दीनं शोकव्याकुललोचनम्॥', 'tam uvāca paritrastaṃ vānarendraṃ vibhīṣaṇaḥ
sabāṣpavadanaṃ dīnaṃ śokavyākulalocanam', null, 6036025),
('ramayana-6-36-26', 26, 'Yuddha Kanda, Sarga 36, Verse 26', 'अलं त्रासेन सुग्रीव बाष्पवेगो निगृह्यताम्।
एवं प्रायाणि युद्धानि विजयो नास्ति नैष्ठिकः॥', 'alaṃ trāsena sugrīva bāṣpavego nigṛhyatām
evaṃ prāyāṇi yuddhāni vijayo nāsti naiṣṭhikaḥ', null, 6036026),
('ramayana-6-36-27', 27, 'Yuddha Kanda, Sarga 36, Verse 27', 'सशेषभाग्यतास्माकं यदि वीर भविष्यति।
मोहमेतौ प्रहास्येते भ्रातरौ रामलक्ष्मणौ॥', 'saśeṣabhāgyatāsmākaṃ yadi vīra bhaviṣyati
moham etau prahāsyete bhrātarau rāmalakṣmaṇau', null, 6036027),
('ramayana-6-36-28', 28, 'Yuddha Kanda, Sarga 36, Verse 28', 'पर्यवस्थापयात्मानमनाथं मां च वानर।
सत्यधर्मानुरक्तानां नास्ति मृत्युकृतं भयम्॥', 'paryavasthāpayātmānam anāthaṃ māṃ ca vānara
satyadharmānuraktānāṃ nāsti mṛtyukṛtaṃ bhayam', null, 6036028),
('ramayana-6-36-29', 29, 'Yuddha Kanda, Sarga 36, Verse 29', 'एवमुक्त्वा ततस्तस्य जलक्लिन्नेन पाणिना।
सुग्रीवस्य शुभे नेत्रे प्रममार्ज विभीषणः॥', 'evam uktvā tatas tasya jalaklinnena pāṇinā
sugrīvasya śubhe netre pramamārja vibhīṣaṇaḥ', null, 6036029),
('ramayana-6-36-30', 30, 'Yuddha Kanda, Sarga 36, Verse 30', 'प्रमृज्य वदनं तस्य कपिराजस्य धीमतः।
अब्रवीत्कालसंप्रातमसंभ्रान्तमिदं वचः॥', 'pramṛjya vadanaṃ tasya kapirājasya dhīmataḥ
abravīt kālasaṃprātam asaṃbhrāntam idaṃ vacaḥ', null, 6036030),
('ramayana-6-36-31', 31, 'Yuddha Kanda, Sarga 36, Verse 31', 'न कालः कपिराजेन्द्र वैक्लव्यमनुवर्तितुम्।
अतिस्नेहोऽप्यकालेऽस्मिन्मरणायोपपद्यते॥', 'na kālaḥ kapirājendra vaiklavyam anuvartitum
atisneho ''py akāle ''smin maraṇāyopapadyate', null, 6036031),
('ramayana-6-36-32', 32, 'Yuddha Kanda, Sarga 36, Verse 32', 'तस्मादुत्सृज्य वैक्लव्यं सर्वकार्यविनाशनम्।
हितं रामपुरोगाणां सैन्यानामनुचिन्त्यताम्॥', 'tasmād utsṛjya vaiklavyaṃ sarvakāryavināśanam
hitaṃ rāmapurogāṇāṃ sainyānām anucintyatām', null, 6036032),
('ramayana-6-36-33', 33, 'Yuddha Kanda, Sarga 36, Verse 33', 'अथ वा रक्ष्यतां रामो यावत्संज्ञा विपर्ययः।
लब्धसंज्ञौ तु काकुत्स्थौ भयं नो व्यपनेष्यतः॥', 'atha vā rakṣyatāṃ rāmo yāvat saṃjñā viparyayaḥ
labdhasaṃjñau tu kākutsthau bhayaṃ no vyapaneṣyataḥ', null, 6036033),
('ramayana-6-36-34', 34, 'Yuddha Kanda, Sarga 36, Verse 34', 'नैतत्किं चन रामस्य न च रामो मुमूर्षति।
न ह्येनं हास्यते लक्ष्मीर्दुर्लभा या गतायुषाम्॥', 'naitat kiṃ cana rāmasya na ca rāmo mumūrṣati
na hy enaṃ hāsyate lakṣmīr durlabhā yā gatāyuṣām', null, 6036034),
('ramayana-6-36-35', 35, 'Yuddha Kanda, Sarga 36, Verse 35', 'तस्मादाश्वासयात्मानं बलं चाश्वासय स्वकम्।
यावत्सर्वाणि सैन्यानि पुनः संस्थापयाम्यहम्॥', 'tasmād āśvāsayātmānaṃ balaṃ cāśvāsaya svakam
yāvat sarvāṇi sainyāni punaḥ saṃsthāpayāmy aham', null, 6036035),
('ramayana-6-36-36', 36, 'Yuddha Kanda, Sarga 36, Verse 36', 'एते ह्युत्फुल्लनयनास्त्रासादागतसाध्वसाः।
कर्णे कर्णे प्रकथिता हरयो हरिपुंगव॥', 'ete hy utphullanayanās trāsād āgatasādhvasāḥ
karṇe karṇe prakathitā harayo haripuṃgava', null, 6036036),
('ramayana-6-36-37', 37, 'Yuddha Kanda, Sarga 36, Verse 37', 'मां तु दृष्ट्वा प्रधावन्तमनीकं संप्रहर्षितुम्।
त्यजन्तु हरयस्त्रासं भुक्तपूर्वामिव स्रजम्॥', 'māṃ tu dṛṣṭvā pradhāvantam anīkaṃ saṃpraharṣitum
tyajantu harayas trāsaṃ bhuktapūrvām iva srajam', null, 6036037),
('ramayana-6-36-38', 38, 'Yuddha Kanda, Sarga 36, Verse 38', 'समाश्वास्य तु सुग्रीवं राक्षसेन्द्रो विभीषणः।
विद्रुतं वानरानीकं तत्समाश्वासयत्पुनः॥', 'samāśvāsya tu sugrīvaṃ rākṣasendro vibhīṣaṇaḥ
vidrutaṃ vānarānīkaṃ tat samāśvāsayat punaḥ', null, 6036038),
('ramayana-6-36-39', 39, 'Yuddha Kanda, Sarga 36, Verse 39', 'इन्द्रजित्तु महामायः सर्वसैन्यसमावृतः।
विवेश नगरीं लङ्कां पितरं चाभ्युपागमत्॥', 'indrajit tu mahāmāyaḥ sarvasainyasamāvṛtaḥ
viveśa nagarīṃ laṅkāṃ pitaraṃ cābhyupāgamat', null, 6036039),
('ramayana-6-36-40', 40, 'Yuddha Kanda, Sarga 36, Verse 40', 'तत्र रावणमासीनमभिवाद्य कृताञ्जलिः।
आचचक्षे प्रियं पित्रे निहतौ रामलक्ष्मणौ॥', 'tatra rāvaṇam āsīnam abhivādya kṛtāñjaliḥ
ācacakṣe priyaṃ pitre nihatau rāmalakṣmaṇau', null, 6036040),
('ramayana-6-36-41', 41, 'Yuddha Kanda, Sarga 36, Verse 41', 'उत्पपात ततो हृष्टः पुत्रं च परिषस्वजे।
रावणो रक्षसां मध्ये श्रुत्वा शत्रू निपातितौ॥', 'utpapāta tato hṛṣṭaḥ putraṃ ca pariṣasvaje
rāvaṇo rakṣasāṃ madhye śrutvā śatrū nipātitau', null, 6036041),
('ramayana-6-36-42', 42, 'Yuddha Kanda, Sarga 36, Verse 42', 'उपाघ्राय स मूर्ध्न्येनं पप्रच्छ प्रीतमानसः।
पृच्छते च यथावृत्तं पित्रे सर्वं न्यवेदयत्॥', 'upāghrāya sa mūrdhny enaṃ papraccha prītamānasaḥ
pṛcchate ca yathāvṛttaṃ pitre sarvaṃ nyavedayat', null, 6036042),
('ramayana-6-36-43', 43, 'Yuddha Kanda, Sarga 36, Verse 43', 'स हर्षवेगानुगतान्तरात्मा श्रुत्वा वचस्तस्य महारथस्य।
जहौ ज्वरं दाशरथेः समुत्थितं प्रहृष्य वाचाभिननन्द पुत्रम्॥', 'sa harṣavegānugatāntarātmā śrutvā vacas tasya mahārathasya
jahau jvaraṃ dāśaratheḥ samutthitaṃ prahṛṣya vācābhinananda putram', null, 6036043)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 37 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-37-1', 1, 'Yuddha Kanda, Sarga 37, Verse 1', 'प्रतिप्रविष्टे लङ्कां तु कृतार्थे रावणात्मजे।
राघवं परिवार्यार्ता ररक्षुर्वानरर्षभाः॥', 'pratipraviṣṭe laṅkāṃ tu kṛtārthe rāvaṇātmaje
rāghavaṃ parivāryārtā rarakṣur vānararṣabhāḥ', null, 6037001),
('ramayana-6-37-2', 2, 'Yuddha Kanda, Sarga 37, Verse 2', 'हनूमानङ्गदो नीलः सुषेणः कुमुदो नलः।
गजो गवाक्षो गवयः शरभो गन्धमादनः॥', 'hanūmān aṅgado nīlaḥ suṣeṇaḥ kumudo nalaḥ
gajo gavākṣo gavayaḥ śarabho gandhamādanaḥ', null, 6037002),
('ramayana-6-37-3', 3, 'Yuddha Kanda, Sarga 37, Verse 3', 'जाम्बवानृषभः सुन्दो रम्भः शतबलिः पृथुः।
व्यूढानीकाश्च यत्ताश्च द्रुमानादाय सर्वतः॥', 'jāmbavān ṛṣabhaḥ sundo rambhaḥ śatabaliḥ pṛthuḥ
vyūḍhānīkāś ca yattāś ca drumān ādāya sarvataḥ', null, 6037003),
('ramayana-6-37-4', 4, 'Yuddha Kanda, Sarga 37, Verse 4', 'वीक्षमाणा दिशः सर्वास्तिर्यगूर्ध्वं च वानराः।
तृणेष्वपि च चेष्टत्सु राक्षसा इति मेनिरे॥', 'vīkṣamāṇā diśaḥ sarvās tiryag ūrdhvaṃ ca vānarāḥ
tṛṇeṣv api ca ceṣṭatsu rākṣasā iti menire', null, 6037004),
('ramayana-6-37-5', 5, 'Yuddha Kanda, Sarga 37, Verse 5', 'रावणश्चापि संहृष्टो विसृज्येन्द्रजितं सुतम्।
आजुहाव ततः सीता रक्षणी राक्षसीस्तदा॥', 'rāvaṇaś cāpi saṃhṛṣṭo visṛjyendrajitaṃ sutam
ājuhāva tataḥ sītā rakṣaṇī rākṣasīs tadā', null, 6037005),
('ramayana-6-37-6', 6, 'Yuddha Kanda, Sarga 37, Verse 6', 'राक्षस्यस्त्रिजटा चापि शासनात्तमुपस्थिताः।
ता उवाच ततो हृष्टो राक्षसी राक्षसेश्वरः॥', 'rākṣasyas trijaṭā cāpi śāsanāt tam upasthitāḥ
tā uvāca tato hṛṣṭo rākṣasī rākṣaseśvaraḥ', null, 6037006),
('ramayana-6-37-7', 7, 'Yuddha Kanda, Sarga 37, Verse 7', 'हताविन्द्रजिताख्यात वैदेह्या रामलक्ष्मणौ।
पुष्पकं च समारोप्य दर्शयध्वं हतौ रणे॥', 'hatāv indrajitākhyāta vaidehyā rāmalakṣmaṇau
puṣpakaṃ ca samāropya darśayadhvaṃ hatau raṇe', null, 6037007),
('ramayana-6-37-8', 8, 'Yuddha Kanda, Sarga 37, Verse 8', 'यदाश्रयादवष्टब्धो नेयं मामुपतिष्ठति।
सोऽस्या भर्ता सह भ्रात्रा निरस्तो रणमूर्धनि॥', 'yad āśrayād avaṣṭabdho neyaṃ mām upatiṣṭhati
so ''syā bhartā saha bhrātrā nirasto raṇamūrdhani', null, 6037008),
('ramayana-6-37-9', 9, 'Yuddha Kanda, Sarga 37, Verse 9', 'निर्विशङ्का निरुद्विग्ना निरपेक्षा च मैथिली।
मामुपस्थास्यते सीता सर्वाभरणभूषिता॥', 'nirviśaṅkā nirudvignā nirapekṣā ca maithilī
mām upasthāsyate sītā sarvābharaṇabhūṣitā', null, 6037009),
('ramayana-6-37-10', 10, 'Yuddha Kanda, Sarga 37, Verse 10', 'अद्य कालवशं प्राप्तं रणे रामं सलक्ष्मणम्।
अवेक्ष्य विनिवृत्ताशा नान्यां गतिमपश्यती॥', 'adya kālavaśaṃ prāptaṃ raṇe rāmaṃ salakṣmaṇam
avekṣya vinivṛttāśā nānyāṃ gatim apaśyatī', null, 6037010),
('ramayana-6-37-11', 11, 'Yuddha Kanda, Sarga 37, Verse 11', 'तस्य तद्वचनं श्रुत्वा रावणस्य दुरात्मनः।
राक्षस्यस्तास्तथेत्युक्त्वा प्रजग्मुर्यत्र पुष्पकम्॥', 'tasya tad vacanaṃ śrutvā rāvaṇasya durātmanaḥ
rākṣasyas tās tathety uktvā prajagmur yatra puṣpakam', null, 6037011),
('ramayana-6-37-12', 12, 'Yuddha Kanda, Sarga 37, Verse 12', 'ततः पुष्पकमादय राक्षस्यो रावणाज्ञया।
अशोकवनिकास्थां तां मैथिलीं समुपानयन्॥', 'tataḥ puṣpakam ādaya rākṣasyo rāvaṇājñayā
aśokavanikāsthāṃ tāṃ maithilīṃ samupānayan', null, 6037012),
('ramayana-6-37-13', 13, 'Yuddha Kanda, Sarga 37, Verse 13', 'तामादाय तु राक्षस्यो भर्तृशोकपरायणाम्।
सीतामारोपयामासुर्विमानं पुष्पकं तदा॥', 'tām ādāya tu rākṣasyo bhartṛśokaparāyaṇām
sītām āropayām āsur vimānaṃ puṣpakaṃ tadā', null, 6037013),
('ramayana-6-37-14', 14, 'Yuddha Kanda, Sarga 37, Verse 14', 'ततः पुष्पकमारोप्य सीतां त्रिजटया सह।
रावणोऽकारयल्लङ्कां पताकाध्वजमालिनीम्॥', 'tataḥ puṣpakam āropya sītāṃ trijaṭayā saha
rāvaṇo ''kārayal laṅkāṃ patākādhvajamālinīm', null, 6037014),
('ramayana-6-37-15', 15, 'Yuddha Kanda, Sarga 37, Verse 15', 'प्राघोषयत हृष्टश्च लङ्कायां राक्षसेश्वरः।
राघवो लक्ष्मणश्चैव हताविन्द्रजिता रणे॥', 'prāghoṣayata hṛṣṭaś ca laṅkāyāṃ rākṣaseśvaraḥ
rāghavo lakṣmaṇaś caiva hatāv indrajitā raṇe', null, 6037015),
('ramayana-6-37-16', 16, 'Yuddha Kanda, Sarga 37, Verse 16', 'विमानेनापि सीता तु गत्वा त्रिजटया सह।
ददर्श वानराणां तु सर्वं सिन्यं निपातितम्॥', 'vimānenāpi sītā tu gatvā trijaṭayā saha
dadarśa vānarāṇāṃ tu sarvaṃ sinyaṃ nipātitam', null, 6037016),
('ramayana-6-37-17', 17, 'Yuddha Kanda, Sarga 37, Verse 17', 'प्रहृष्टमनसश्चापि ददर्श पिशिताशनान्।
वानरांश्चापि दुःखार्तान्रामलक्ष्मणपार्श्वतः॥', 'prahṛṣṭamanasaś cāpi dadarśa piśitāśanān
vānarāṃś cāpi duḥkhārtān rāmalakṣmaṇapārśvataḥ', null, 6037017),
('ramayana-6-37-18', 18, 'Yuddha Kanda, Sarga 37, Verse 18', 'ततः सीता ददर्शोभौ शयानौ शततल्पयोः।
लक्ष्मणं चैव रामं च विसंज्ञौ शरपीडितौ॥', 'tataḥ sītā dadarśobhau śayānau śatatalpayoḥ
lakṣmaṇaṃ caiva rāmaṃ ca visaṃjñau śarapīḍitau', null, 6037018),
('ramayana-6-37-19', 19, 'Yuddha Kanda, Sarga 37, Verse 19', 'विध्वस्तकवचौ वीरौ विप्रविद्धशरासनौ।
सायकैश्छिन्नसर्वाङ्गौ शरस्तम्भमयौ क्षितौ॥', 'vidhvastakavacau vīrau vipraviddhaśarāsanau
sāyakaiś chinnasarvāṅgau śarastambhamayau kṣitau', null, 6037019),
('ramayana-6-37-20', 20, 'Yuddha Kanda, Sarga 37, Verse 20', 'तौ दृष्ट्वा भ्रातरौ तत्र वीरौ सा पुरुषर्षभौ।
दुःखार्ता सुभृशं सीता करुणं विललाप ह॥', 'tau dṛṣṭvā bhrātarau tatra vīrau sā puruṣarṣabhau
duḥkhārtā subhṛśaṃ sītā karuṇaṃ vilalāpa ha', null, 6037020),
('ramayana-6-37-21', 21, 'Yuddha Kanda, Sarga 37, Verse 21', 'सा बाष्पशोकाभिहता समीक्ष्य तौ भ्रातरौ देवसमप्रभावौ।
वितर्कयन्ती निधनं तयोः सा दुःखान्विता वाक्यमिदं जगाद॥', 'sā bāṣpaśokābhihatā samīkṣya tau bhrātarau devasamaprabhāvau
vitarkayantī nidhanaṃ tayoḥ sā duḥkhānvitā vākyam idaṃ jagāda', null, 6037021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 38 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-38-1', 1, 'Yuddha Kanda, Sarga 38, Verse 1', 'भर्तारं निहतं दृष्ट्वा लक्ष्मणं च महाबलम्।
विललाप भृशं सीता करुणं शोककर्शिता॥', 'bhartāraṃ nihataṃ dṛṣṭvā lakṣmaṇaṃ ca mahābalam
vilalāpa bhṛśaṃ sītā karuṇaṃ śokakarśitā', null, 6038001),
('ramayana-6-38-2', 2, 'Yuddha Kanda, Sarga 38, Verse 2', 'ऊचुर्लक्षणिका ये मां पुत्रिण्यविधवेति च।
तेऽस्य सर्वे हते रामेऽज्ञानिनोऽनृतवादिनः॥', 'ūcur lakṣaṇikā ye māṃ putriṇy avidhaveti ca
te ''sya sarve hate rāme ''jñānino ''nṛtavādinaḥ', null, 6038002),
('ramayana-6-38-3', 3, 'Yuddha Kanda, Sarga 38, Verse 3', 'यज्वनो महिषीं ये मामूचुः पत्नीं च सत्रिणः।
तेऽद्य सर्वे हते रामेऽज्ञानिनोऽनृतवादिनः॥', 'yajvano mahiṣīṃ ye mām ūcuḥ patnīṃ ca satriṇaḥ
te ''dya sarve hate rāme ''jñānino ''nṛtavādinaḥ', null, 6038003),
('ramayana-6-38-4', 4, 'Yuddha Kanda, Sarga 38, Verse 4', 'वीरपार्थिवपत्नी त्वं ये धन्येति च मां विदुः।
तेऽद्य सर्वे हते रामेऽज्ञानिनोऽनृतवादिनः॥', 'vīrapārthivapatnī tvaṃ ye dhanyeti ca māṃ viduḥ
te ''dya sarve hate rāme ''jñānino ''nṛtavādinaḥ', null, 6038004),
('ramayana-6-38-5', 5, 'Yuddha Kanda, Sarga 38, Verse 5', 'ऊचुः संश्रवणे ये मां द्विजाः कार्तान्तिकाः शुभाम्।
तेऽद्य सर्वे हते रामेऽज्ञानिनोऽनृतवादिनः॥', 'ūcuḥ saṃśravaṇe ye māṃ dvijāḥ kārtāntikāḥ śubhām
te ''dya sarve hate rāme ''jñānino ''nṛtavādinaḥ', null, 6038005),
('ramayana-6-38-6', 6, 'Yuddha Kanda, Sarga 38, Verse 6', 'इमानि खलु पद्मानि पादयोर्यैः किल स्त्रियः।
अधिराज्येऽभिषिच्यन्ते नरेन्द्रैः पतिभिः सह॥', 'imāni khalu padmāni pādayor yaiḥ kila striyaḥ
adhirājye ''bhiṣicyante narendraiḥ patibhiḥ saha', null, 6038006),
('ramayana-6-38-7', 7, 'Yuddha Kanda, Sarga 38, Verse 7', 'वैधव्यं यान्ति यैर्नार्योऽलक्षणैर्भाग्यदुर्लभाः।
नात्मनस्तानि पश्यामि पश्यन्ती हतलक्षणा॥', 'vaidhavyaṃ yānti yair nāryo ''lakṣaṇair bhāgyadurlabhāḥ
nātmanas tāni paśyāmi paśyantī hatalakṣaṇā', null, 6038007),
('ramayana-6-38-8', 8, 'Yuddha Kanda, Sarga 38, Verse 8', 'सत्यानीमानि पद्मानि स्त्रीणामुक्त्वानि लक्षणे।
तान्यद्य निहते रामे वितथानि भवन्ति मे॥', 'satyānīmāni padmāni strīṇām uktvāni lakṣaṇe
tāny adya nihate rāme vitathāni bhavanti me', null, 6038008),
('ramayana-6-38-9', 9, 'Yuddha Kanda, Sarga 38, Verse 9', 'केशाः सूक्ष्माः समा नीला भ्रुवौ चासंगते मम।
वृत्ते चालोमशे जङ्घे दन्ताश्चाविरला मम॥', 'keśāḥ sūkṣmāḥ samā nīlā bhruvau cāsaṃgate mama
vṛtte cālomaśe jaṅghe dantāś cāviralā mama', null, 6038009),
('ramayana-6-38-10', 10, 'Yuddha Kanda, Sarga 38, Verse 10', 'शङ्खे नेत्रे करौ पादौ गुल्फावूरू च मे चितौ।
अनुवृत्ता नखाः स्निग्धाः समाश्चाङ्गुलयो मम॥', 'śaṅkhe netre karau pādau gulphāv ūrū ca me citau
anuvṛttā nakhāḥ snigdhāḥ samāś cāṅgulayo mama', null, 6038010),
('ramayana-6-38-11', 11, 'Yuddha Kanda, Sarga 38, Verse 11', 'स्तनौ चाविरलौ पीनौ ममेमौ मग्नचूचुकौ।
मग्ना चोत्सङ्गिनी नाभिः पार्श्वोरस्कं च मे चितम्॥', 'stanau cāviralau pīnau mamemau magnacūcukau
magnā cotsaṅginī nābhiḥ pārśvoraskaṃ ca me citam', null, 6038011),
('ramayana-6-38-12', 12, 'Yuddha Kanda, Sarga 38, Verse 12', 'मम वर्णो मणिनिभो मृदून्यङ्गरुहाणि च।
प्रतिष्ठितां द्वदशभिर्मामूचुः शुभलक्षणाम्॥', 'mama varṇo maṇinibho mṛdūny aṅgaruhāṇi ca
pratiṣṭhitāṃ dvadaśabhir mām ūcuḥ śubhalakṣaṇām', null, 6038012),
('ramayana-6-38-13', 13, 'Yuddha Kanda, Sarga 38, Verse 13', 'समग्रयवमच्छिद्रं पाणिपादं च वर्णवत्।
मन्दस्मितेत्येव च मां कन्यालक्षणिका विदुः॥', 'samagrayavam acchidraṃ pāṇipādaṃ ca varṇavat
mandasmitety eva ca māṃ kanyālakṣaṇikā viduḥ', null, 6038013),
('ramayana-6-38-14', 14, 'Yuddha Kanda, Sarga 38, Verse 14', 'अधिराज्येऽभिषेको मे ब्राह्मणैः पतिना सह।
कृतान्तकुशलैरुक्तं तत्सर्वं वितथीकृतम्॥', 'adhirājye ''bhiṣeko me brāhmaṇaiḥ patinā saha
kṛtāntakuśalair uktaṃ tat sarvaṃ vitathīkṛtam', null, 6038014),
('ramayana-6-38-15', 15, 'Yuddha Kanda, Sarga 38, Verse 15', 'शोधयित्वा जनस्थानं प्रवृत्तिमुपलभ्य च।
तीर्त्वा सागरमक्षोभ्यं भ्रातरौ गोष्पदे हतौ॥', 'śodhayitvā janasthānaṃ pravṛttim upalabhya ca
tīrtvā sāgaram akṣobhyaṃ bhrātarau goṣpade hatau', null, 6038015),
('ramayana-6-38-16', 16, 'Yuddha Kanda, Sarga 38, Verse 16', 'ननु वारुणमाग्नेयमैन्द्रं वायव्यमेव च।
अस्त्रं ब्रह्मशिरश्चैव राघवौ प्रत्यपद्यताम्॥', 'nanu vāruṇam āgneyam aindraṃ vāyavyam eva ca
astraṃ brahmaśiraś caiva rāghavau pratyapadyatām', null, 6038016),
('ramayana-6-38-17', 17, 'Yuddha Kanda, Sarga 38, Verse 17', 'अदृश्यमानेन रणे मायया वासवोपमौ।
मम नाथावनाथाया निहतौ रामलक्ष्मणौ॥', 'adṛśyamānena raṇe māyayā vāsavopamau
mama nāthāv anāthāyā nihatau rāmalakṣmaṇau', null, 6038017),
('ramayana-6-38-18', 18, 'Yuddha Kanda, Sarga 38, Verse 18', 'न हि दृष्टिपथं प्राप्य राघवस्य रणे रिपुः।
जीवन्प्रतिनिवर्तेत यद्यपि स्यान्मनोजवः॥', 'na hi dṛṣṭipathaṃ prāpya rāghavasya raṇe ripuḥ
jīvan pratinivarteta yady api syān manojavaḥ', null, 6038018),
('ramayana-6-38-19', 19, 'Yuddha Kanda, Sarga 38, Verse 19', 'न कालस्यातिभारोऽस्ति कृतान्तश्च सुदुर्जयः।
यत्र रामः सह भ्रात्रा शेते युधि निपाथितः॥', 'na kālasyātibhāro ''sti kṛtāntaś ca sudurjayaḥ
yatra rāmaḥ saha bhrātrā śete yudhi nipāthitaḥ', null, 6038019),
('ramayana-6-38-20', 20, 'Yuddha Kanda, Sarga 38, Verse 20', 'नाहं शोचामि भर्तारं निहतं न च लक्ष्मणम्।
नात्मानं जननी चापि यथा श्वश्रूं तपस्विनीम्॥', 'nāhaṃ śocāmi bhartāraṃ nihataṃ na ca lakṣmaṇam
nātmānaṃ jananī cāpi yathā śvaśrūṃ tapasvinīm', null, 6038020),
('ramayana-6-38-21', 21, 'Yuddha Kanda, Sarga 38, Verse 21', 'सा हि चिन्तयते नित्यं समाप्तव्रतमागतम्।
कदा द्रक्ष्यामि सीतां च रामं च सहलक्ष्मणम्॥', 'sā hi cintayate nityaṃ samāptavratam āgatam
kadā drakṣyāmi sītāṃ ca rāmaṃ ca sahalakṣmaṇam', null, 6038021),
('ramayana-6-38-22', 22, 'Yuddha Kanda, Sarga 38, Verse 22', 'परिदेवयमानां तां राक्षसी त्रिजटाब्रवीत्।
मा विषादं कृथा देवि भर्तायं तव जीवति॥', 'paridevayamānāṃ tāṃ rākṣasī trijaṭābravīt
mā viṣādaṃ kṛthā devi bhartāyaṃ tava jīvati', null, 6038022),
('ramayana-6-38-23', 23, 'Yuddha Kanda, Sarga 38, Verse 23', 'कारणानि च वक्ष्यामि महान्ति सदृशानि च।
यथेमौ जीवतो देवि भ्रातरौ रामलक्ष्मणौ॥', 'kāraṇāni ca vakṣyāmi mahānti sadṛśāni ca
yathemau jīvato devi bhrātarau rāmalakṣmaṇau', null, 6038023),
('ramayana-6-38-24', 24, 'Yuddha Kanda, Sarga 38, Verse 24', 'न हि कोपपरीतानि हर्षपर्युत्सुकानि च।
भवन्ति युधि योधानां मुखानि निहते पतौ॥', 'na hi kopaparītāni harṣaparyutsukāni ca
bhavanti yudhi yodhānāṃ mukhāni nihate patau', null, 6038024),
('ramayana-6-38-25', 25, 'Yuddha Kanda, Sarga 38, Verse 25', 'इदं विमानं वैदेहि पुष्पकं नाम नामतः।
दिव्यं त्वां धारयेन्नेदं यद्येतौ गजजीवितौ॥', 'idaṃ vimānaṃ vaidehi puṣpakaṃ nāma nāmataḥ
divyaṃ tvāṃ dhārayen nedaṃ yady etau gajajīvitau', null, 6038025),
('ramayana-6-38-26', 26, 'Yuddha Kanda, Sarga 38, Verse 26', 'हतवीरप्रधाना हि हतोत्साहा निरुद्यमा।
सेना भ्रमति संख्येषु हतकर्णेव नौर्जले॥', 'hatavīrapradhānā hi hatotsāhā nirudyamā
senā bhramati saṃkhyeṣu hatakarṇeva naur jale', null, 6038026),
('ramayana-6-38-27', 27, 'Yuddha Kanda, Sarga 38, Verse 27', 'इयं पुनरसंभ्रान्ता निरुद्विग्ना तरस्विनी।
सेना रक्षति काकुत्स्थौ मायया निर्जितौ रणे॥', 'iyaṃ punar asaṃbhrāntā nirudvignā tarasvinī
senā rakṣati kākutsthau māyayā nirjitau raṇe', null, 6038027),
('ramayana-6-38-28', 28, 'Yuddha Kanda, Sarga 38, Verse 28', 'सा त्वं भव सुविस्रब्धा अनुमानैः सुखोदयैः।
अहतौ पश्य काकुत्स्थौ स्नेहादेतद्ब्रवीमि ते॥', 'sā tvaṃ bhava suvisrabdhā anumānaiḥ sukhodayaiḥ
ahatau paśya kākutsthau snehād etad bravīmi te', null, 6038028),
('ramayana-6-38-29', 29, 'Yuddha Kanda, Sarga 38, Verse 29', 'अनृतं नोक्तपूर्वं मे न च वक्ष्ये कदा चन।
चारित्रसुखशीलत्वात्प्रविष्टासि मनो मम॥', 'anṛtaṃ noktapūrvaṃ me na ca vakṣye kadā cana
cāritrasukhaśīlatvāt praviṣṭāsi mano mama', null, 6038029),
('ramayana-6-38-30', 30, 'Yuddha Kanda, Sarga 38, Verse 30', 'नेमौ शक्यौ रणे जेतुं सेन्द्रैरपि सुरासुरैः।
एतयोराननं दृष्ट्वा मया चावेदितं तव॥', 'nemau śakyau raṇe jetuṃ sendrair api surāsuraiḥ
etayor ānanaṃ dṛṣṭvā mayā cāveditaṃ tava', null, 6038030),
('ramayana-6-38-31', 31, 'Yuddha Kanda, Sarga 38, Verse 31', 'इदं च सुमहच्चिह्नं शनैः पश्यस्व मैथिलि।
निःसंज्ञावप्युभावेतौ नैव लक्ष्मीर्वियुज्यते॥', 'idaṃ ca sumahac cihnaṃ śanaiḥ paśyasva maithili
niḥsaṃjñāv apy ubhāv etau naiva lakṣmīr viyujyate', null, 6038031),
('ramayana-6-38-32', 32, 'Yuddha Kanda, Sarga 38, Verse 32', 'प्रायेण गतसत्त्वानां पुरुषाणां गतायुषाम्।
दृश्यमानेषु वक्त्रेषु परं भवति वैकृतम्॥', 'prāyeṇa gatasattvānāṃ puruṣāṇāṃ gatāyuṣām
dṛśyamāneṣu vaktreṣu paraṃ bhavati vaikṛtam', null, 6038032),
('ramayana-6-38-33', 33, 'Yuddha Kanda, Sarga 38, Verse 33', 'त्यज शोकं च दुःखं च मोहं च जनकात्मजे।
रामलक्ष्मणयोरर्थे नाद्य शक्यमजीवितुम्॥', 'tyaja śokaṃ ca duḥkhaṃ ca mohaṃ ca janakātmaje
rāmalakṣmaṇayor arthe nādya śakyam ajīvitum', null, 6038033),
('ramayana-6-38-34', 34, 'Yuddha Kanda, Sarga 38, Verse 34', 'श्रुत्वा तु वचनं तस्याः सीता सुरसुतोपमा।
कृताञ्जलिरुवाचेदमेवमस्त्विति मैथिली॥', 'śrutvā tu vacanaṃ tasyāḥ sītā surasutopamā
kṛtāñjalir uvācedam evam astv iti maithilī', null, 6038034),
('ramayana-6-38-35', 35, 'Yuddha Kanda, Sarga 38, Verse 35', 'विमानं पुष्पकं तत्तु समिवर्त्य मनोजवम्।
दीना त्रिजटया सीता लङ्कामेव प्रवेशिता॥', 'vimānaṃ puṣpakaṃ tat tu samivartya manojavam
dīnā trijaṭayā sītā laṅkām eva praveśitā', null, 6038035),
('ramayana-6-38-36', 36, 'Yuddha Kanda, Sarga 38, Verse 36', 'ततस्त्रिजटया सार्धं पुष्पकादवरुह्य सा।
अशोकवनिकामेव रक्षसीभिः प्रवेशिता॥', 'tatas trijaṭayā sārdhaṃ puṣpakād avaruhya sā
aśokavanikām eva rakṣasībhiḥ praveśitā', null, 6038036),
('ramayana-6-38-37', 37, 'Yuddha Kanda, Sarga 38, Verse 37', 'प्रविश्य सीता बहुवृक्षषण्डां तां राक्षसेन्द्रस्य विहारभूमिम्।
संप्रेक्ष्य संचिन्त्य च राजपुत्रौ परं विषादं समुपाजगाम॥', 'praviśya sītā bahuvṛkṣaṣaṇḍāṃ tāṃ rākṣasendrasya vihārabhūmim
saṃprekṣya saṃcintya ca rājaputrau paraṃ viṣādaṃ samupājagāma', null, 6038037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 39 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-39-1', 1, 'Yuddha Kanda, Sarga 39, Verse 1', 'घोरेण शरबन्धेन बद्धौ दशरथात्मजौ।
निश्वसन्तौ यथा नागौ शयानौ रुधिरोक्षितौ॥', 'ghoreṇa śarabandhena baddhau daśarathātmajau
niśvasantau yathā nāgau śayānau rudhirokṣitau', null, 6039001),
('ramayana-6-39-2', 2, 'Yuddha Kanda, Sarga 39, Verse 2', 'सर्वे ते वानरश्रेष्ठाः ससुग्रीवा महाबलाः।
परिवार्य महात्मानौ तस्थुः शोकपरिप्लुताः॥', 'sarve te vānaraśreṣṭhāḥ sasugrīvā mahābalāḥ
parivārya mahātmānau tasthuḥ śokapariplutāḥ', null, 6039002),
('ramayana-6-39-3', 3, 'Yuddha Kanda, Sarga 39, Verse 3', 'एतस्मिन्नन्तेरे रामः प्रत्यबुध्यत वीर्यवान्।
स्थिरत्वात्सत्त्वयोगाच्च शरैः संदानितोऽपि सन्॥', 'etasminn antere rāmaḥ pratyabudhyata vīryavān
sthiratvāt sattvayogāc ca śaraiḥ saṃdānito ''pi san', null, 6039003),
('ramayana-6-39-4', 4, 'Yuddha Kanda, Sarga 39, Verse 4', 'ततो दृष्ट्वा सरुधिरं विषण्णं गाढमर्पितम्।
भ्रातरं दीनवदनं पर्यदेवयदातुरः॥', 'tato dṛṣṭvā sarudhiraṃ viṣaṇṇaṃ gāḍham arpitam
bhrātaraṃ dīnavadanaṃ paryadevayad āturaḥ', null, 6039004),
('ramayana-6-39-5', 5, 'Yuddha Kanda, Sarga 39, Verse 5', 'किं नु मे सीतया कार्यं किं कार्यं जीवितेन वा।
शयानं योऽद्य पश्यामि भ्रातरं युधि निर्जितम्॥', 'kiṃ nu me sītayā kāryaṃ kiṃ kāryaṃ jīvitena vā
śayānaṃ yo ''dya paśyāmi bhrātaraṃ yudhi nirjitam', null, 6039005),
('ramayana-6-39-6', 6, 'Yuddha Kanda, Sarga 39, Verse 6', 'शक्या सीता समा नारी प्राप्तुं लोके विचिन्वता।
न लक्ष्मणसमो भ्राता सचिवः साम्परायिकः॥', 'śakyā sītā samā nārī prāptuṃ loke vicinvatā
na lakṣmaṇasamo bhrātā sacivaḥ sāmparāyikaḥ', null, 6039006),
('ramayana-6-39-7', 7, 'Yuddha Kanda, Sarga 39, Verse 7', 'परित्यक्ष्याम्यहं प्राणान्वानराणां तु पश्यताम्।
यदि पञ्चत्वमापन्नः सुमित्रानन्दवर्धनः॥', 'parityakṣyāmy ahaṃ prāṇān vānarāṇāṃ tu paśyatām
yadi pañcatvam āpannaḥ sumitrānandavardhanaḥ', null, 6039007),
('ramayana-6-39-8', 8, 'Yuddha Kanda, Sarga 39, Verse 8', 'किं नु वक्ष्यामि कौसल्यां मातरं किं नु कैकयीम्।
कथमम्बां सुमित्रांच पुत्रदर्शनलालसाम्॥', 'kiṃ nu vakṣyāmi kausalyāṃ mātaraṃ kiṃ nu kaikayīm
katham ambāṃ sumitrāṃca putradarśanalālasām', null, 6039008),
('ramayana-6-39-9', 9, 'Yuddha Kanda, Sarga 39, Verse 9', 'विवत्सां वेपमानां च क्रोशन्तीं कुररीमिव।
कथमाश्वासयिष्यामि यदि यास्यामि तं विना॥', 'vivatsāṃ vepamānāṃ ca krośantīṃ kurarīm iva
katham āśvāsayiṣyāmi yadi yāsyāmi taṃ vinā', null, 6039009),
('ramayana-6-39-10', 10, 'Yuddha Kanda, Sarga 39, Verse 10', 'कथं वक्ष्यामि शत्रुघ्नं भरतं च यशस्विनम्।
मया सह वनं यातो विना तेनागतः पुनः॥', 'kathaṃ vakṣyāmi śatrughnaṃ bharataṃ ca yaśasvinam
mayā saha vanaṃ yāto vinā tenāgataḥ punaḥ', null, 6039010),
('ramayana-6-39-11', 11, 'Yuddha Kanda, Sarga 39, Verse 11', 'उपालम्भं न शक्ष्यामि सोढुं बत सुमित्रया।
इहैव देहं त्यक्ष्यामि न हि जीवितुमुत्सहे॥', 'upālambhaṃ na śakṣyāmi soḍhuṃ bata sumitrayā
ihaiva dehaṃ tyakṣyāmi na hi jīvitum utsahe', null, 6039011),
('ramayana-6-39-12', 12, 'Yuddha Kanda, Sarga 39, Verse 12', 'धिङ्मां दुष्कृतकर्माणमनार्यं यत्कृते ह्यसौ।
लक्ष्मणः पतितः शेते शरतल्पे गतासुवत्॥', 'dhiṅ māṃ duṣkṛtakarmāṇam anāryaṃ yatkṛte hy asau
lakṣmaṇaḥ patitaḥ śete śaratalpe gatāsuvat', null, 6039012),
('ramayana-6-39-13', 13, 'Yuddha Kanda, Sarga 39, Verse 13', 'त्वं नित्यं सुविषण्णं मामाश्वासयसि लक्ष्मण।
गतासुर्नाद्य शक्नोषि मामार्तमभिभाषितुम्॥', 'tvaṃ nityaṃ suviṣaṇṇaṃ mām āśvāsayasi lakṣmaṇa
gatāsur nādya śaknoṣi mām ārtam abhibhāṣitum', null, 6039013),
('ramayana-6-39-14', 14, 'Yuddha Kanda, Sarga 39, Verse 14', 'येनाद्य बहवो युद्धे राक्षसा निहताः क्षितौ।
तस्यामेव क्षितौ वीरः स शेते निहतः परैः॥', 'yenādya bahavo yuddhe rākṣasā nihatāḥ kṣitau
tasyām eva kṣitau vīraḥ sa śete nihataḥ paraiḥ', null, 6039014),
('ramayana-6-39-15', 15, 'Yuddha Kanda, Sarga 39, Verse 15', 'शयानः शरतल्पेऽस्मिन्स्वशोणितपरिप्लुतः।
शरजालैश्चितो भाति भास्करोऽस्तमिव व्रजन्॥', 'śayānaḥ śaratalpe ''smin svaśoṇitapariplutaḥ
śarajālaiś cito bhāti bhāskaro ''stam iva vrajan', null, 6039015),
('ramayana-6-39-16', 16, 'Yuddha Kanda, Sarga 39, Verse 16', 'बाणाभिहतमर्मत्वान्न शक्नोत्यभिवीक्षितुम्।
रुजा चाब्रुवतो ह्यस्य दृष्टिरागेण सूच्यते॥', 'bāṇābhihatamarmatvān na śaknoty abhivīkṣitum
rujā cābruvato hy asya dṛṣṭirāgeṇa sūcyate', null, 6039016),
('ramayana-6-39-17', 17, 'Yuddha Kanda, Sarga 39, Verse 17', 'यथैव मां वनं यान्तमनुयातो महाद्युतिः।
अहमप्यनुयास्यामि तथैवैनं यमक्षयम्॥', 'yathaiva māṃ vanaṃ yāntam anuyāto mahādyutiḥ
aham apy anuyāsyāmi tathaivainaṃ yamakṣayam', null, 6039017),
('ramayana-6-39-18', 18, 'Yuddha Kanda, Sarga 39, Verse 18', 'इष्टबन्धुजनो नित्यं मां च नित्यमनुव्रतः।
इमामद्य गतोऽवस्थां ममानार्यस्य दुर्नयैः॥', 'iṣṭabandhujano nityaṃ māṃ ca nityam anuvrataḥ
imām adya gato ''vasthāṃ mamānāryasya durnayaiḥ', null, 6039018),
('ramayana-6-39-19', 19, 'Yuddha Kanda, Sarga 39, Verse 19', 'सुरुष्टेनापि वीरेण लक्ष्मणेना न संस्मरे।
परुषं विप्रियं वापि श्रावितं न कदा चन॥', 'suruṣṭenāpi vīreṇa lakṣmaṇenā na saṃsmare
paruṣaṃ vipriyaṃ vāpi śrāvitaṃ na kadā cana', null, 6039019),
('ramayana-6-39-20', 20, 'Yuddha Kanda, Sarga 39, Verse 20', 'विससर्जैकवेगेन पञ्चबाणशतानि यः।
इष्वस्त्रेष्वधिकस्तस्मात्कार्तवीर्याच्च लक्ष्मणः॥', 'visasarjaikavegena pañcabāṇaśatāni yaḥ
iṣvastreṣv adhikas tasmāt kārtavīryāc ca lakṣmaṇaḥ', null, 6039020),
('ramayana-6-39-21', 21, 'Yuddha Kanda, Sarga 39, Verse 21', 'अस्त्रैरस्त्राणि यो हन्याच्छक्रस्यापि महात्मनः।
सोऽयमुर्व्यांहतः शेते महार्हशयनोचितः॥', 'astrair astrāṇi yo hanyāc chakrasyāpi mahātmanaḥ
so ''yam urvyāṃhataḥ śete mahārhaśayanocitaḥ', null, 6039021),
('ramayana-6-39-22', 22, 'Yuddha Kanda, Sarga 39, Verse 22', 'तच्च मिथ्या प्रलप्तं मां प्रधक्ष्यति न संशयः।
यन्मया न कृतो राजा राक्षसानां विभीषणः॥', 'tac ca mithyā pralaptaṃ māṃ pradhakṣyati na saṃśayaḥ
yan mayā na kṛto rājā rākṣasānāṃ vibhīṣaṇaḥ', null, 6039022),
('ramayana-6-39-23', 23, 'Yuddha Kanda, Sarga 39, Verse 23', 'अस्मिन्मुहूर्ते सुग्रीव प्रतियातुमितोऽर्हसि।
मत्वा हीनं मया राजन्रावणोऽभिद्रवेद्बली॥', 'asmin muhūrte sugrīva pratiyātum ito ''rhasi
matvā hīnaṃ mayā rājan rāvaṇo ''bhidraved balī', null, 6039023),
('ramayana-6-39-24', 24, 'Yuddha Kanda, Sarga 39, Verse 24', 'अङ्गदं तु पुरस्कृत्य ससैन्यः ससुहृज्जनः।
सागरं तर सुग्रीव पुनस्तेनैव सेतुना॥', 'aṅgadaṃ tu puraskṛtya sasainyaḥ sasuhṛjjanaḥ
sāgaraṃ tara sugrīva punas tenaiva setunā', null, 6039024),
('ramayana-6-39-25', 25, 'Yuddha Kanda, Sarga 39, Verse 25', 'कृतं हनुमता कार्यं यदन्यैर्दुष्करं रणे।
ऋक्षराजेन तुष्यामि गोलाङ्गूलाधिपेन च॥', 'kṛtaṃ hanumatā kāryaṃ yad anyair duṣkaraṃ raṇe
ṛkṣarājena tuṣyāmi golāṅgūlādhipena ca', null, 6039025),
('ramayana-6-39-26', 26, 'Yuddha Kanda, Sarga 39, Verse 26', 'अङ्गदेन कृतं कर्म मैन्देन द्विविदेन च।
युद्धं केसरिणा संख्ये घोरं संपातिना कृतम्॥', 'aṅgadena kṛtaṃ karma maindena dvividena ca
yuddhaṃ kesariṇā saṃkhye ghoraṃ saṃpātinā kṛtam', null, 6039026),
('ramayana-6-39-27', 27, 'Yuddha Kanda, Sarga 39, Verse 27', 'गवयेन गवाक्षेण शरभेण गजेन च।
अन्यैश्च हरिभिर्युद्धं मदार्थे त्यक्तजीवितैः॥', 'gavayena gavākṣeṇa śarabheṇa gajena ca
anyaiś ca haribhir yuddhaṃ madārthe tyaktajīvitaiḥ', null, 6039027),
('ramayana-6-39-28', 28, 'Yuddha Kanda, Sarga 39, Verse 28', 'न चातिक्रमितुं शक्यं दैवं सुग्रीव मानुषैः।
यत्तु शक्यं वयस्येन सुहृदा वा परंतप।
कृतं सुग्रीव तत्सर्वं भवताधर्मभीरुणा॥', 'na cātikramituṃ śakyaṃ daivaṃ sugrīva mānuṣaiḥ
yat tu śakyaṃ vayasyena suhṛdā vā paraṃtapa
kṛtaṃ sugrīva tat sarvaṃ bhavatādharmabhīruṇā', null, 6039028),
('ramayana-6-39-29', 29, 'Yuddha Kanda, Sarga 39, Verse 29', 'मित्रकार्यं कृतमिदं भवद्भिर्वानरर्षभाः।
अनुज्ञाता मया सर्वे यथेष्टं गन्तुमर्हथ॥', 'mitrakāryaṃ kṛtam idaṃ bhavadbhir vānararṣabhāḥ
anujñātā mayā sarve yatheṣṭaṃ gantum arhatha', null, 6039029),
('ramayana-6-39-30', 30, 'Yuddha Kanda, Sarga 39, Verse 30', 'शुश्रुवुस्तस्य ते सर्वे वानराः परिदेवितम्।
वर्तयां चक्रुरश्रूणि नेत्रैः कृष्णेतरेक्षणाः॥', 'śuśruvus tasya te sarve vānarāḥ paridevitam
vartayāṃ cakrur aśrūṇi netraiḥ kṛṣṇetarekṣaṇāḥ', null, 6039030),
('ramayana-6-39-31', 31, 'Yuddha Kanda, Sarga 39, Verse 31', 'ततः सर्वाण्यनीकानि स्थापयित्वा विभीषणः।
आजगाम गदापाणिस्त्वरितो यत्र राघवः॥', 'tataḥ sarvāṇy anīkāni sthāpayitvā vibhīṣaṇaḥ
ājagāma gadāpāṇis tvarito yatra rāghavaḥ', null, 6039031),
('ramayana-6-39-32', 32, 'Yuddha Kanda, Sarga 39, Verse 32', 'तं दृष्ट्वा त्वरितं यान्तं नीलाञ्जनचयोपमम्।
वानरा दुद्रुवुः सर्वे मन्यमानास्तु रावणिम्॥', 'taṃ dṛṣṭvā tvaritaṃ yāntaṃ nīlāñjanacayopamam
vānarā dudruvuḥ sarve manyamānās tu rāvaṇim', null, 6039032)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 40 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-40-1', 1, 'Yuddha Kanda, Sarga 40, Verse 1', 'अथोवाच महातेजा हरिराजो महाबलः।
किमियं व्यथिता सेना मूढवातेव नौर्जले॥', 'athovāca mahātejā harirājo mahābalaḥ
kim iyaṃ vyathitā senā mūḍhavāteva naur jale', null, 6040001),
('ramayana-6-40-2', 2, 'Yuddha Kanda, Sarga 40, Verse 2', 'सुग्रीवस्य वचः श्रुत्वा वालिपुत्रोऽङ्गदोऽब्रवीत्।
न त्वं पश्यसि रामं च लक्ष्मणं च महाबलम्॥', 'sugrīvasya vacaḥ śrutvā vāliputro ''ṅgado ''bravīt
na tvaṃ paśyasi rāmaṃ ca lakṣmaṇaṃ ca mahābalam', null, 6040002),
('ramayana-6-40-3', 3, 'Yuddha Kanda, Sarga 40, Verse 3', 'शरजालाचितौ वीरावुभौ दशरथात्मजौ।
शरतल्पे महात्मानौ शयानौ रुधिरोक्षितौ॥', 'śarajālācitau vīrāv ubhau daśarathātmajau
śaratalpe mahātmānau śayānau rudhirokṣitau', null, 6040003),
('ramayana-6-40-4', 4, 'Yuddha Kanda, Sarga 40, Verse 4', 'अथाब्रवीद्वानरेन्द्रः सुग्रीवः पुत्रमङ्गदम्।
नानिमित्तमिदं मन्ये भवितव्यं भयेन तु॥', 'athābravīd vānarendraḥ sugrīvaḥ putram aṅgadam
nānimittam idaṃ manye bhavitavyaṃ bhayena tu', null, 6040004),
('ramayana-6-40-5', 5, 'Yuddha Kanda, Sarga 40, Verse 5', 'विषण्णवदना ह्येते त्यक्तप्रहरणा दिशः।
प्रपलायन्ति हरयस्त्रासादुत्फुल्ललोचनाः॥', 'viṣaṇṇavadanā hy ete tyaktapraharaṇā diśaḥ
prapalāyanti harayas trāsād utphullalocanāḥ', null, 6040005),
('ramayana-6-40-6', 6, 'Yuddha Kanda, Sarga 40, Verse 6', 'अन्योन्यस्य न लज्जन्ते न निरीक्षन्ति पृष्ठतः।
विप्रकर्षन्ति चान्योन्यं पतितं लङ्घयन्ति च॥', 'anyonyasya na lajjante na nirīkṣanti pṛṣṭhataḥ
viprakarṣanti cānyonyaṃ patitaṃ laṅghayanti ca', null, 6040006),
('ramayana-6-40-7', 7, 'Yuddha Kanda, Sarga 40, Verse 7', 'एतस्मिन्नन्तरे वीरो गदापाणिर्विभीषणः।
सुग्रीवं वर्धयामास राघवं च निरैक्षत॥', 'etasminn antare vīro gadāpāṇir vibhīṣaṇaḥ
sugrīvaṃ vardhayām āsa rāghavaṃ ca niraikṣata', null, 6040007),
('ramayana-6-40-8', 8, 'Yuddha Kanda, Sarga 40, Verse 8', 'विभीषणं तं सुग्रीवो दृष्ट्वा वानरभीषणम्।
ऋक्षराजं समीपस्थं जाम्बवन्तमुवाच ह॥', 'vibhīṣaṇaṃ taṃ sugrīvo dṛṣṭvā vānarabhīṣaṇam
ṛkṣarājaṃ samīpasthaṃ jāmbavantam uvāca ha', null, 6040008),
('ramayana-6-40-9', 9, 'Yuddha Kanda, Sarga 40, Verse 9', 'विभीषणोऽयं संप्राप्तो यं दृष्ट्वा वानरर्षभाः।
विद्रवन्ति परित्रस्ता रावणात्मजशङ्कया॥', 'vibhīṣaṇo ''yaṃ saṃprāpto yaṃ dṛṣṭvā vānararṣabhāḥ
vidravanti paritrastā rāvaṇātmajaśaṅkayā', null, 6040009),
('ramayana-6-40-10', 10, 'Yuddha Kanda, Sarga 40, Verse 10', 'शीघ्रमेतान्सुवित्रस्तान्बहुधा विप्रधावितान्।
पर्यवस्थापयाख्याहि विभीषणमुपस्थितम्॥', 'śīghram etān suvitrastān bahudhā vipradhāvitān
paryavasthāpayākhyāhi vibhīṣaṇam upasthitam', null, 6040010),
('ramayana-6-40-11', 11, 'Yuddha Kanda, Sarga 40, Verse 11', 'सुग्रीवेणैवमुक्तस्तु जाम्बवानृक्षपार्थिवः।
वानरान्सान्त्वयामास संनिवर्त्य प्रहावतः॥', 'sugrīveṇaivam uktas tu jāmbavān ṛkṣapārthivaḥ
vānarān sāntvayām āsa saṃnivartya prahāvataḥ', null, 6040011),
('ramayana-6-40-12', 12, 'Yuddha Kanda, Sarga 40, Verse 12', 'ते निवृत्ताः पुनः सर्वे वानरास्त्यक्तसंभ्रमाः।
ऋक्षराजवचः श्रुत्वा तं च दृष्ट्वा विभीषणम्॥', 'te nivṛttāḥ punaḥ sarve vānarās tyaktasaṃbhramāḥ
ṛkṣarājavacaḥ śrutvā taṃ ca dṛṣṭvā vibhīṣaṇam', null, 6040012),
('ramayana-6-40-13', 13, 'Yuddha Kanda, Sarga 40, Verse 13', 'विभीषणस्तु रामस्य दृष्ट्वा गात्रं शरैश्चितम्।
लक्ष्मणस्य च धर्मात्मा बभूव व्यथितेन्द्रियः॥', 'vibhīṣaṇas tu rāmasya dṛṣṭvā gātraṃ śaraiś citam
lakṣmaṇasya ca dharmātmā babhūva vyathitendriyaḥ', null, 6040013),
('ramayana-6-40-14', 14, 'Yuddha Kanda, Sarga 40, Verse 14', 'जलक्लिन्नेन हस्तेन तयोर्नेत्रे प्रमृज्य च।
शोकसंपीडितमना रुरोद विललाप च॥', 'jalaklinnena hastena tayor netre pramṛjya ca
śokasaṃpīḍitamanā ruroda vilalāpa ca', null, 6040014),
('ramayana-6-40-15', 15, 'Yuddha Kanda, Sarga 40, Verse 15', 'इमौ तौ सत्त्वसंपन्नौ विक्रान्तौ प्रियसंयुगौ।
इमामवस्थां गमितौ राकसैः कूटयोधिभिः॥', 'imau tau sattvasaṃpannau vikrāntau priyasaṃyugau
imām avasthāṃ gamitau rākasaiḥ kūṭayodhibhiḥ', null, 6040015),
('ramayana-6-40-16', 16, 'Yuddha Kanda, Sarga 40, Verse 16', 'भ्रातुः पुत्रेण मे तेन दुष्पुत्रेण दुरात्मना।
राक्षस्या जिह्मया बुद्ध्या छलितावृजुविक्रमौ॥', 'bhrātuḥ putreṇa me tena duṣputreṇa durātmanā
rākṣasyā jihmayā buddhyā chalitāv ṛjuvikramau', null, 6040016),
('ramayana-6-40-17', 17, 'Yuddha Kanda, Sarga 40, Verse 17', 'शरैरिमावलं विद्धौ रुधिरेण समुक्षितौ।
वसुधायामिम सुप्तौ दृश्येते शल्यकाविव॥', 'śarair imāv alaṃ viddhau rudhireṇa samukṣitau
vasudhāyām ima suptau dṛśyete śalyakāv iva', null, 6040017),
('ramayana-6-40-18', 18, 'Yuddha Kanda, Sarga 40, Verse 18', 'ययोर्वीर्यमुपाश्रित्य प्रतिष्ठा काङ्क्षिता मया।
तावुभौ देहनाशाय प्रसुप्तौ पुरुषर्षभौ॥', 'yayor vīryam upāśritya pratiṣṭhā kāṅkṣitā mayā
tāv ubhau dehanāśāya prasuptau puruṣarṣabhau', null, 6040018),
('ramayana-6-40-19', 19, 'Yuddha Kanda, Sarga 40, Verse 19', 'जीवन्नद्य विपन्नोऽस्मि नष्टराज्यमनोरथः।
प्राप्तप्रतिज्ञश्च रिपुः सकामो रावणः कृतः॥', 'jīvann adya vipanno ''smi naṣṭarājyamanorathaḥ
prāptapratijñaś ca ripuḥ sakāmo rāvaṇaḥ kṛtaḥ', null, 6040019),
('ramayana-6-40-20', 20, 'Yuddha Kanda, Sarga 40, Verse 20', 'एवं विलपमानं तं परिष्वज्य विभीषणम्।
सुग्रीवः सत्त्वसंपन्नो हरिराजोऽब्रवीदिदम्॥', 'evaṃ vilapamānaṃ taṃ pariṣvajya vibhīṣaṇam
sugrīvaḥ sattvasaṃpanno harirājo ''bravīd idam', null, 6040020),
('ramayana-6-40-21', 21, 'Yuddha Kanda, Sarga 40, Verse 21', 'राज्यं प्राप्स्यसि धर्मज्ञ लङ्कायां नात्र संशयः।
रावणः सह पुत्रेण स राज्यं नेह लप्स्यते॥', 'rājyaṃ prāpsyasi dharmajña laṅkāyāṃ nātra saṃśayaḥ
rāvaṇaḥ saha putreṇa sa rājyaṃ neha lapsyate', null, 6040021),
('ramayana-6-40-22', 22, 'Yuddha Kanda, Sarga 40, Verse 22', 'शरसंपीडितावेतावुभौ राघवलक्ष्मणौ।
त्यक्त्वा मोहं वधिष्येते सगणं रावणं रणे॥', 'śarasaṃpīḍitāv etāv ubhau rāghavalakṣmaṇau
tyaktvā mohaṃ vadhiṣyete sagaṇaṃ rāvaṇaṃ raṇe', null, 6040022),
('ramayana-6-40-23', 23, 'Yuddha Kanda, Sarga 40, Verse 23', 'तमेवं सान्त्वयित्वा तु समाश्वास्य च राक्षसं।
सुषेणं श्वशुरं पार्श्वे सुग्रीवस्तमुवाच ह॥', 'tam evaṃ sāntvayitvā tu samāśvāsya ca rākṣasaṃ
suṣeṇaṃ śvaśuraṃ pārśve sugrīvas tam uvāca ha', null, 6040023),
('ramayana-6-40-24', 24, 'Yuddha Kanda, Sarga 40, Verse 24', 'सह शूरैर्हरिगणैर्लब्धसंज्ञावरिंदमौ।
गच्छ त्वं भ्रातरौ गृह्य किष्किन्धां रामलक्ष्मणौ॥', 'saha śūrair harigaṇair labdhasaṃjñāv ariṃdamau
gaccha tvaṃ bhrātarau gṛhya kiṣkindhāṃ rāmalakṣmaṇau', null, 6040024),
('ramayana-6-40-25', 25, 'Yuddha Kanda, Sarga 40, Verse 25', 'अहं तु रावणं हत्वा सपुत्रं सहबान्धवम्।
मैथिलीमानयिष्यामि शक्रो नष्टामिव श्रियम्॥', 'ahaṃ tu rāvaṇaṃ hatvā saputraṃ sahabāndhavam
maithilīm ānayiṣyāmi śakro naṣṭām iva śriyam', null, 6040025),
('ramayana-6-40-26', 26, 'Yuddha Kanda, Sarga 40, Verse 26', 'श्रुत्वैतद्वानरेन्द्रस्य सुषेणो वाक्यमब्रवीत्।
देवासुरं महायुद्धमनुभूतं सुदारुणम्॥', 'śrutvaitad vānarendrasya suṣeṇo vākyam abravīt
devāsuraṃ mahāyuddham anubhūtaṃ sudāruṇam', null, 6040026),
('ramayana-6-40-27', 27, 'Yuddha Kanda, Sarga 40, Verse 27', 'तदा स्म दानवा देवाञ्शरसंस्पर्शकोविदाः।
निजघ्नुः शस्त्रविदुषश्छादयन्तो मुहुर्मुहुः॥', 'tadā sma dānavā devāñ śarasaṃsparśakovidāḥ
nijaghnuḥ śastraviduṣaś chādayanto muhur muhuḥ', null, 6040027),
('ramayana-6-40-28', 28, 'Yuddha Kanda, Sarga 40, Verse 28', 'तानार्तान्नष्टसंज्ञांश्च परासूंश्च बृहस्पतिः।
विध्याभिर्मन्त्रयुक्ताभिरोषधीभिश्चिकित्सति॥', 'tān ārtān naṣṭasaṃjñāṃś ca parāsūṃś ca bṛhaspatiḥ
vidhyābhir mantrayuktābhir oṣadhībhiś cikitsati', null, 6040028),
('ramayana-6-40-29', 29, 'Yuddha Kanda, Sarga 40, Verse 29', 'तान्यौषधान्यानयितुं क्षीरोदं यान्तु सागरम्।
जवेन वानराः शीघ्रं संपाति पनसादयः॥', 'tāny auṣadhāny ānayituṃ kṣīrodaṃ yāntu sāgaram
javena vānarāḥ śīghraṃ saṃpāti panasādayaḥ', null, 6040029),
('ramayana-6-40-30', 30, 'Yuddha Kanda, Sarga 40, Verse 30', 'हरयस्तु विजानन्ति पार्वती ते महौषधी।
संजीवकरणीं दिव्यां विशल्यां देवनिर्मिताम्॥', 'harayas tu vijānanti pārvatī te mahauṣadhī
saṃjīvakaraṇīṃ divyāṃ viśalyāṃ devanirmitām', null, 6040030),
('ramayana-6-40-31', 31, 'Yuddha Kanda, Sarga 40, Verse 31', 'चन्द्रश्च नाम द्रोणश्च पर्वतौ सागरोत्तमे।
अमृतं यत्र मथितं तत्र ते परमौषधी॥', 'candraś ca nāma droṇaś ca parvatau sāgarottame
amṛtaṃ yatra mathitaṃ tatra te paramauṣadhī', null, 6040031),
('ramayana-6-40-32', 32, 'Yuddha Kanda, Sarga 40, Verse 32', 'ते तत्र निहिते देवैः पर्वते परमौषधी।
अयं वायुसुतो राजन्हनूमांस्तत्र गच्छतु॥', 'te tatra nihite devaiḥ parvate paramauṣadhī
ayaṃ vāyusuto rājan hanūmāṃs tatra gacchatu', null, 6040032),
('ramayana-6-40-33', 33, 'Yuddha Kanda, Sarga 40, Verse 33', 'एतस्मिन्नन्तरे वायुर्मेघांश्चापि सविद्युतः।
पर्यस्यन्सागरे तोयं कम्पयन्निव पर्वतान्॥', 'etasminn antare vāyur meghāṃś cāpi savidyutaḥ
paryasyan sāgare toyaṃ kampayann iva parvatān', null, 6040033),
('ramayana-6-40-34', 34, 'Yuddha Kanda, Sarga 40, Verse 34', 'महता पक्षवातेन सर्वे द्वीपमहाद्रुमाः।
निपेतुर्भग्नविटपाः समूला लवणाम्भसि॥', 'mahatā pakṣavātena sarve dvīpamahādrumāḥ
nipetur bhagnaviṭapāḥ samūlā lavaṇāmbhasi', null, 6040034),
('ramayana-6-40-35', 35, 'Yuddha Kanda, Sarga 40, Verse 35', 'अभवन्पन्नगास्त्रस्ता भोगिनस्तत्रवासिनः।
शीघ्रं सर्वाणि यादांसि जग्मुश्च लवणार्णवम्॥', 'abhavan pannagās trastā bhoginas tatravāsinaḥ
śīghraṃ sarvāṇi yādāṃsi jagmuś ca lavaṇārṇavam', null, 6040035),
('ramayana-6-40-36', 36, 'Yuddha Kanda, Sarga 40, Verse 36', 'ततो मुहूर्तद्गरुडं वैनतेयं महाबलम्।
वानरा ददृशुः सर्वे ज्वलन्तमिव पावकम्॥', 'tato muhūrtad garuḍaṃ vainateyaṃ mahābalam
vānarā dadṛśuḥ sarve jvalantam iva pāvakam', null, 6040036),
('ramayana-6-40-37', 37, 'Yuddha Kanda, Sarga 40, Verse 37', 'तमागतमभिप्रेक्ष्य नागास्ते विप्रदुद्रुवुः।
यैस्तौ सत्पुरुषौ बद्धौ शरभूतैर्महाबलौ॥', 'tam āgatam abhiprekṣya nāgās te vipradudruvuḥ
yais tau satpuruṣau baddhau śarabhūtair mahābalau', null, 6040037),
('ramayana-6-40-38', 38, 'Yuddha Kanda, Sarga 40, Verse 38', 'ततः सुपर्णः काकुत्स्थौ दृष्ट्वा प्रत्यभिनन्द्य च।
विममर्श च पाणिभ्यां मुखे चन्द्रसमप्रभे॥', 'tataḥ suparṇaḥ kākutsthau dṛṣṭvā pratyabhinandya ca
vimamarśa ca pāṇibhyāṃ mukhe candrasamaprabhe', null, 6040038),
('ramayana-6-40-39', 39, 'Yuddha Kanda, Sarga 40, Verse 39', 'वैनतेयेन संस्पृष्टास्तयोः संरुरुहुर्व्रणाः।
सुवर्णे च तनू स्निग्धे तयोराशु बभूवतुः॥', 'vainateyena saṃspṛṣṭās tayoḥ saṃruruhur vraṇāḥ
suvarṇe ca tanū snigdhe tayor āśu babhūvatuḥ', null, 6040039),
('ramayana-6-40-40', 40, 'Yuddha Kanda, Sarga 40, Verse 40', 'तेजो वीर्यं बलं चौज उत्साहश्च महागुणाः।
प्रदर्शनं च बुद्धिश्च स्मृतिश्च द्विगुणं तयोः॥', 'tejo vīryaṃ balaṃ cauja utsāhaś ca mahāguṇāḥ
pradarśanaṃ ca buddhiś ca smṛtiś ca dviguṇaṃ tayoḥ', null, 6040040),
('ramayana-6-40-41', 41, 'Yuddha Kanda, Sarga 40, Verse 41', 'तावुत्थाप्य महावीर्यौ गरुडो वासवोपमौ।
उभौ तौ सस्वजे हृष्टौ रामश्चैनमुवाच ह॥', 'tāv utthāpya mahāvīryau garuḍo vāsavopamau
ubhau tau sasvaje hṛṣṭau rāmaś cainam uvāca ha', null, 6040041),
('ramayana-6-40-42', 42, 'Yuddha Kanda, Sarga 40, Verse 42', 'भवत्प्रसादाद्व्यसनं रावणिप्रभवं महत्।
आवामिह व्यतिक्रान्तौ शीघ्रं च बलिनौ कृतौ॥', 'bhavatprasādād vyasanaṃ rāvaṇiprabhavaṃ mahat
āvām iha vyatikrāntau śīghraṃ ca balinau kṛtau', null, 6040042),
('ramayana-6-40-43', 43, 'Yuddha Kanda, Sarga 40, Verse 43', 'यथा तातं दशरथं यथाजं च पितामहम्।
तथा भवन्तमासाद्य हृषयं मे प्रसीदति॥', 'yathā tātaṃ daśarathaṃ yathājaṃ ca pitāmaham
tathā bhavantam āsādya hṛṣayaṃ me prasīdati', null, 6040043),
('ramayana-6-40-44', 44, 'Yuddha Kanda, Sarga 40, Verse 44', 'को भवान्रूपसंपन्नो दिव्यस्रगनुलेपनः।
वसानो विरजे वस्त्रे दिव्याभरणभूषितः॥', 'ko bhavān rūpasaṃpanno divyasraganulepanaḥ
vasāno viraje vastre divyābharaṇabhūṣitaḥ', null, 6040044),
('ramayana-6-40-45', 45, 'Yuddha Kanda, Sarga 40, Verse 45', 'तमुवाच महातेजा वैनतेयो महाबलः।
पतत्रिराजः प्रीतात्मा हर्षपर्याकुलेक्षणः॥', 'tam uvāca mahātejā vainateyo mahābalaḥ
patatrirājaḥ prītātmā harṣaparyākulekṣaṇaḥ', null, 6040045),
('ramayana-6-40-46', 46, 'Yuddha Kanda, Sarga 40, Verse 46', 'अहं सखा ते काकुत्स्थ प्रियः प्राणो बहिश्चरः।
गरुत्मानिह संप्राप्तो युवयोः साह्यकारणात्॥', 'ahaṃ sakhā te kākutstha priyaḥ prāṇo bahiścaraḥ
garutmān iha saṃprāpto yuvayoḥ sāhyakāraṇāt', null, 6040046),
('ramayana-6-40-47', 47, 'Yuddha Kanda, Sarga 40, Verse 47', 'असुरा वा महावीर्या दानवा वा महाबलाः।
सुराश्चापि सगन्धर्वाः पुरस्कृत्य शतक्रतुम्॥', 'asurā vā mahāvīryā dānavā vā mahābalāḥ
surāś cāpi sagandharvāḥ puraskṛtya śatakratum', null, 6040047),
('ramayana-6-40-48', 48, 'Yuddha Kanda, Sarga 40, Verse 48', 'नेमं मोक्षयितुं शक्ताः शरबन्धं सुदारुणम्।
माया बलादिन्द्रजिता निर्मितं क्रूरकर्मणा॥', 'nemaṃ mokṣayituṃ śaktāḥ śarabandhaṃ sudāruṇam
māyā balād indrajitā nirmitaṃ krūrakarmaṇā', null, 6040048),
('ramayana-6-40-49', 49, 'Yuddha Kanda, Sarga 40, Verse 49', 'एते नागाः काद्रवेयास्तीक्ष्णदंष्ट्राविषोल्बणाः।
रक्षोमाया प्रभावेन शरा भूत्वा त्वदाश्रिताः॥', 'ete nāgāḥ kādraveyās tīkṣṇadaṃṣṭrāviṣolbaṇāḥ
rakṣomāyā prabhāvena śarā bhūtvā tvadāśritāḥ', null, 6040049),
('ramayana-6-40-50', 50, 'Yuddha Kanda, Sarga 40, Verse 50', 'सभाग्यश्चासि धर्मज्ञ राम सत्यपराक्रम।
लक्ष्मणेन सह भ्रात्रा समरे रिपुघातिना॥', 'sabhāgyaś cāsi dharmajña rāma satyaparākrama
lakṣmaṇena saha bhrātrā samare ripughātinā', null, 6040050),
('ramayana-6-40-51', 51, 'Yuddha Kanda, Sarga 40, Verse 51', 'इमं श्रुत्वा तु वृत्तान्तं त्वरमाणोऽहमागतः।
सहसा युवयोः स्नेहात्सखित्वमनुपालयन्॥', 'imaṃ śrutvā tu vṛttāntaṃ tvaramāṇo ''ham āgataḥ
sahasā yuvayoḥ snehāt sakhitvam anupālayan', null, 6040051),
('ramayana-6-40-52', 52, 'Yuddha Kanda, Sarga 40, Verse 52', 'मोक्षितौ च महाघोरादस्मात्सायकबन्धनात्।
अप्रमादश्च कर्तव्यो युवाभ्यां नित्यमेव हि॥', 'mokṣitau ca mahāghorād asmāt sāyakabandhanāt
apramādaś ca kartavyo yuvābhyāṃ nityam eva hi', null, 6040052),
('ramayana-6-40-53', 53, 'Yuddha Kanda, Sarga 40, Verse 53', 'प्रकृत्या राक्षसाः सर्वे संग्रामे कूटयोधिनः।
शूराणां शुद्धभावानां भवतामार्जवं बलम्॥', 'prakṛtyā rākṣasāḥ sarve saṃgrāme kūṭayodhinaḥ
śūrāṇāṃ śuddhabhāvānāṃ bhavatām ārjavaṃ balam', null, 6040053),
('ramayana-6-40-54', 54, 'Yuddha Kanda, Sarga 40, Verse 54', 'तन्न विश्वसितव्यं वो राक्षसानां रणाजिरे।
एतेनैवोपमानेन नित्यजिह्मा हि राक्षसाः॥', 'tan na viśvasitavyaṃ vo rākṣasānāṃ raṇājire
etenaivopamānena nityajihmā hi rākṣasāḥ', null, 6040054),
('ramayana-6-40-55', 55, 'Yuddha Kanda, Sarga 40, Verse 55', 'एवमुक्त्वा ततो रामं सुपर्णः सुमहाबलः।
परिष्वज्य सुहृत्स्निग्धमाप्रष्टुमुपचक्रमे॥', 'evam uktvā tato rāmaṃ suparṇaḥ sumahābalaḥ
pariṣvajya suhṛtsnigdham āpraṣṭum upacakrame', null, 6040055),
('ramayana-6-40-56', 56, 'Yuddha Kanda, Sarga 40, Verse 56', 'सखे राघव धर्मज्ञ रिपूणामपि वत्सल।
अभ्यनुज्ञातुमिच्छामि गमिष्यामि यथागतम्॥', 'sakhe rāghava dharmajña ripūṇām api vatsala
abhyanujñātum icchāmi gamiṣyāmi yathāgatam', null, 6040056),
('ramayana-6-40-57', 57, 'Yuddha Kanda, Sarga 40, Verse 57', 'बालवृद्धावशेषां तु लङ्कां कृत्वा शरोर्मिभिः।
रावणं च रिपुं हत्वा सीतां समुपलप्स्यसे॥', 'bālavṛddhāvaśeṣāṃ tu laṅkāṃ kṛtvā śarormibhiḥ
rāvaṇaṃ ca ripuṃ hatvā sītāṃ samupalapsyase', null, 6040057),
('ramayana-6-40-58', 58, 'Yuddha Kanda, Sarga 40, Verse 58', 'इत्येवमुक्त्वा वचनं सुपर्णः शीघ्रविक्रमः।
रामं च विरुजं कृत्वा मध्ये तेषां वनौकसाम्॥', 'ity evam uktvā vacanaṃ suparṇaḥ śīghravikramaḥ
rāmaṃ ca virujaṃ kṛtvā madhye teṣāṃ vanaukasām', null, 6040058),
('ramayana-6-40-59', 59, 'Yuddha Kanda, Sarga 40, Verse 59', 'प्रदक्षिणं ततः कृत्वा परिष्वज्य च वीर्यवान्।
जगामाकाशमाविश्य सुपर्णः पवनो यथा॥', 'pradakṣiṇaṃ tataḥ kṛtvā pariṣvajya ca vīryavān
jagāmākāśam āviśya suparṇaḥ pavano yathā', null, 6040059),
('ramayana-6-40-60', 60, 'Yuddha Kanda, Sarga 40, Verse 60', 'विरुजौ राघवौ दृष्ट्वा ततो वानरयूथपाः।
सिंहनादांस्तदा नेदुर्लाङ्गूलं दुधुवुश्च ते॥', 'virujau rāghavau dṛṣṭvā tato vānarayūthapāḥ
siṃhanādāṃs tadā nedur lāṅgūlaṃ dudhuvuś ca te', null, 6040060),
('ramayana-6-40-61', 61, 'Yuddha Kanda, Sarga 40, Verse 61', 'ततो भेरीः समाजघ्नुर्मृदङ्गांश्च व्यनादयन्।
दध्मुः शङ्खान्संप्रहृष्टाः क्ष्वेलन्त्यपि यथापुरम्॥', 'tato bherīḥ samājaghnur mṛdaṅgāṃś ca vyanādayan
dadhmuḥ śaṅkhān saṃprahṛṣṭāḥ kṣvelanty api yathāpuram', null, 6040061),
('ramayana-6-40-62', 62, 'Yuddha Kanda, Sarga 40, Verse 62', 'आस्फोट्यास्फोट्य विक्रान्ता वानरा नगयोधिनः।
द्रुमानुत्पाट्य विविधांस्तस्थुः शतसहस्रशः॥', 'āsphoṭyāsphoṭya vikrāntā vānarā nagayodhinaḥ
drumān utpāṭya vividhāṃs tasthuḥ śatasahasraśaḥ', null, 6040062),
('ramayana-6-40-63', 63, 'Yuddha Kanda, Sarga 40, Verse 63', 'विसृजन्तो महानादांस्त्रासयन्तो निशाचरान्।
लङ्काद्वाराण्युपाजग्मुर्योद्धुकामाः प्लवंगमाः॥', 'visṛjanto mahānādāṃs trāsayanto niśācarān
laṅkādvārāṇy upājagmur yoddhukāmāḥ plavaṃgamāḥ', null, 6040063),
('ramayana-6-40-64', 64, 'Yuddha Kanda, Sarga 40, Verse 64', 'ततस्तु भीमस्तुमुलो निनादो बभूव शाखामृगयूथपानाम्।
क्षये निदाघस्य यथा घनानां नादः सुभीमो नदतां निशीथे॥', 'tatas tu bhīmas tumulo ninādo babhūva śākhāmṛgayūthapānām
kṣaye nidāghasya yathā ghanānāṃ nādaḥ subhīmo nadatāṃ niśīthe', null, 6040064)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 41 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-41-1', 1, 'Yuddha Kanda, Sarga 41, Verse 1', 'तेषां सुतुमुलं शब्दं वानराणां तरस्विनाम्।
नर्दतां राक्षसैः सार्धं तदा शुश्राव रावणः॥', 'teṣāṃ sutumulaṃ śabdaṃ vānarāṇāṃ tarasvinām
nardatāṃ rākṣasaiḥ sārdhaṃ tadā śuśrāva rāvaṇaḥ', null, 6041001),
('ramayana-6-41-2', 2, 'Yuddha Kanda, Sarga 41, Verse 2', 'स्निग्धगम्भीरनिर्घोषं श्रुत्वा स निनदं भृशम्।
सचिवानां ततस्तेषां मध्ये वचनमब्रवीत्॥', 'snigdhagambhīranirghoṣaṃ śrutvā sa ninadaṃ bhṛśam
sacivānāṃ tatas teṣāṃ madhye vacanam abravīt', null, 6041002),
('ramayana-6-41-3', 3, 'Yuddha Kanda, Sarga 41, Verse 3', 'यथासौ संप्रहृष्टानां वानराणां समुत्थितः।
बहूनां सुमहान्नादो मेघानामिव गर्जताम्॥', 'yathāsau saṃprahṛṣṭānāṃ vānarāṇāṃ samutthitaḥ
bahūnāṃ sumahān nādo meghānām iva garjatām', null, 6041003),
('ramayana-6-41-4', 4, 'Yuddha Kanda, Sarga 41, Verse 4', 'व्यक्तं सुमहती प्रीतिरेतेषां नात्र संशयः।
तथा हि विपुलैर्नादैश्चुक्षुभे वरुणालयः॥', 'vyaktaṃ sumahatī prītir eteṣāṃ nātra saṃśayaḥ
tathā hi vipulair nādaiś cukṣubhe varuṇālayaḥ', null, 6041004),
('ramayana-6-41-5', 5, 'Yuddha Kanda, Sarga 41, Verse 5', 'तौ तु बद्धौ शरैस्तीष्क्णैर्भ्रातरौ रामलक्ष्मणौ।
अयं च सुमहान्नादः शङ्कां जनयतीव मे॥', 'tau tu baddhau śarais tīṣkṇair bhrātarau rāmalakṣmaṇau
ayaṃ ca sumahān nādaḥ śaṅkāṃ janayatīva me', null, 6041005),
('ramayana-6-41-6', 6, 'Yuddha Kanda, Sarga 41, Verse 6', 'एतत्तु वचनं चोक्त्वा मन्त्रिणो राक्षसेश्वरः।
उवाच नैरृतांस्तत्र समीपपरिवर्तिनः॥', 'etat tu vacanaṃ coktvā mantriṇo rākṣaseśvaraḥ
uvāca nairṛtāṃs tatra samīpaparivartinaḥ', null, 6041006),
('ramayana-6-41-7', 7, 'Yuddha Kanda, Sarga 41, Verse 7', 'ज्ञायतां तूर्णमेतषां सर्वेषां वनचारिणाम्।
शोककाले समुत्पन्ने हर्षकारणमुत्थितम्॥', 'jñāyatāṃ tūrṇam etaṣāṃ sarveṣāṃ vanacāriṇām
śokakāle samutpanne harṣakāraṇam utthitam', null, 6041007),
('ramayana-6-41-8', 8, 'Yuddha Kanda, Sarga 41, Verse 8', 'तथोक्तास्तेन संभ्रान्ताः प्राकारमधिरुह्य ते।
ददृशुः पालितां सेनां सुग्रीवेण महात्मना॥', 'tathoktās tena saṃbhrāntāḥ prākāram adhiruhya te
dadṛśuḥ pālitāṃ senāṃ sugrīveṇa mahātmanā', null, 6041008),
('ramayana-6-41-9', 9, 'Yuddha Kanda, Sarga 41, Verse 9', 'तौ च मुक्तौ सुघोरेण शरबन्धेन राघवौ।
समुत्थितौ महाभागौ विषेदुः प्रेक्ष्य राक्षसाः॥', 'tau ca muktau sughoreṇa śarabandhena rāghavau
samutthitau mahābhāgau viṣeduḥ prekṣya rākṣasāḥ', null, 6041009),
('ramayana-6-41-10', 10, 'Yuddha Kanda, Sarga 41, Verse 10', 'संत्रस्तहृदया सर्वे प्राकारादवरुह्य ते।
विषण्णवदनाः सर्वे राक्षसेन्द्रमुपस्थिताः॥', 'saṃtrastahṛdayā sarve prākārād avaruhya te
viṣaṇṇavadanāḥ sarve rākṣasendram upasthitāḥ', null, 6041010),
('ramayana-6-41-11', 11, 'Yuddha Kanda, Sarga 41, Verse 11', 'तदप्रियं दीनमुखा रावणस्य निशाचराः।
कृत्स्नं निवेदयामासुर्यथावद्वाक्यकोविदाः॥', 'tad apriyaṃ dīnamukhā rāvaṇasya niśācarāḥ
kṛtsnaṃ nivedayām āsur yathāvad vākyakovidāḥ', null, 6041011),
('ramayana-6-41-12', 12, 'Yuddha Kanda, Sarga 41, Verse 12', 'यौ ताविन्द्रजिता युद्धे भ्रातरौ रामलक्ष्मणौ।
निबद्धौ शरबन्धेन निष्प्रकम्पभुजौ कृतौ॥', 'yau tāv indrajitā yuddhe bhrātarau rāmalakṣmaṇau
nibaddhau śarabandhena niṣprakampabhujau kṛtau', null, 6041012),
('ramayana-6-41-13', 13, 'Yuddha Kanda, Sarga 41, Verse 13', 'विमुक्तौ शरबन्धेन तौ दृश्येते रणाजिरे।
पाशानिव गजौ छित्त्वा गजेन्द्रसमविक्रमौ॥', 'vimuktau śarabandhena tau dṛśyete raṇājire
pāśān iva gajau chittvā gajendrasamavikramau', null, 6041013),
('ramayana-6-41-14', 14, 'Yuddha Kanda, Sarga 41, Verse 14', 'तच्छ्रुत्वा वचनं तेषां राक्षसेन्द्रो महाबलः।
चिन्ताशोकसमाक्रान्तो विषण्णवदनोऽब्रवीत्॥', 'tac chrutvā vacanaṃ teṣāṃ rākṣasendro mahābalaḥ
cintāśokasamākrānto viṣaṇṇavadano ''bravīt', null, 6041014),
('ramayana-6-41-15', 15, 'Yuddha Kanda, Sarga 41, Verse 15', 'घोरैर्दत्तवरैर्बद्धौ शरैराशीविषोमपैः।
अमोघैः सूर्यसंकाशैः प्रमथ्येन्द्रजिता युधि॥', 'ghorair dattavarair baddhau śarair āśīviṣomapaiḥ
amoghaiḥ sūryasaṃkāśaiḥ pramathyendrajitā yudhi', null, 6041015),
('ramayana-6-41-16', 16, 'Yuddha Kanda, Sarga 41, Verse 16', 'तमस्त्रबन्धमासाद्य यदि मुक्तौ रिपू मम।
संशयस्थमिदं सर्वमनुपश्याम्यहं बलम्॥', 'tam astrabandham āsādya yadi muktau ripū mama
saṃśayastham idaṃ sarvam anupaśyāmy ahaṃ balam', null, 6041016),
('ramayana-6-41-17', 17, 'Yuddha Kanda, Sarga 41, Verse 17', 'निष्फलाः खलु संवृत्ताः शरा वासुकितेजसः।
आदत्तं यैस्तु संग्रामे रिपूणां मम जीवितम्॥', 'niṣphalāḥ khalu saṃvṛttāḥ śarā vāsukitejasaḥ
ādattaṃ yais tu saṃgrāme ripūṇāṃ mama jīvitam', null, 6041017),
('ramayana-6-41-18', 18, 'Yuddha Kanda, Sarga 41, Verse 18', 'एवमुक्त्वा तु संक्रुद्धो निश्वसन्नुरगो यथा।
अब्रवीद्रक्षसां मध्ये धूम्राक्षं नाम राकसं॥', 'evam uktvā tu saṃkruddho niśvasann urago yathā
abravīd rakṣasāṃ madhye dhūmrākṣaṃ nāma rākasaṃ', null, 6041018),
('ramayana-6-41-19', 19, 'Yuddha Kanda, Sarga 41, Verse 19', 'बलेन महता युक्तो रक्षसां भीमकर्मणाम्।
त्वं वधायाभिनिर्याहि रामस्य सह वानरैः॥', 'balena mahatā yukto rakṣasāṃ bhīmakarmaṇām
tvaṃ vadhāyābhiniryāhi rāmasya saha vānaraiḥ', null, 6041019),
('ramayana-6-41-20', 20, 'Yuddha Kanda, Sarga 41, Verse 20', 'एवमुक्तस्तु धूम्राक्षो राक्षसेन्द्रेण धीमता।
कृत्वा प्रणामं संहृष्टो निर्जगाम नृपालयात्॥', 'evam uktas tu dhūmrākṣo rākṣasendreṇa dhīmatā
kṛtvā praṇāmaṃ saṃhṛṣṭo nirjagāma nṛpālayāt', null, 6041020),
('ramayana-6-41-21', 21, 'Yuddha Kanda, Sarga 41, Verse 21', 'अभिनिष्क्रम्य तद्द्वारं बलाध्यक्षमुवाच ह।
त्वरयस्व बलं तूर्णं किं चिरेण युयुत्सतः॥', 'abhiniṣkramya taddvāraṃ balādhyakṣam uvāca ha
tvarayasva balaṃ tūrṇaṃ kiṃ cireṇa yuyutsataḥ', null, 6041021),
('ramayana-6-41-22', 22, 'Yuddha Kanda, Sarga 41, Verse 22', 'धूम्राक्षस्य वचः श्रुत्वा बलाध्यक्षो बलानुगः।
बलमुद्योजयामास रावणस्याज्ञया द्रुतम्॥', 'dhūmrākṣasya vacaḥ śrutvā balādhyakṣo balānugaḥ
balam udyojayām āsa rāvaṇasyājñayā drutam', null, 6041022),
('ramayana-6-41-23', 23, 'Yuddha Kanda, Sarga 41, Verse 23', 'ते बद्धघण्टा बलिनो घोररूपा निशाचराः।
विनर्दमानाः संहृष्टा धूम्राक्षं पर्यवारयन्॥', 'te baddhaghaṇṭā balino ghorarūpā niśācarāḥ
vinardamānāḥ saṃhṛṣṭā dhūmrākṣaṃ paryavārayan', null, 6041023),
('ramayana-6-41-24', 24, 'Yuddha Kanda, Sarga 41, Verse 24', 'विविधायुधहस्ताश्च शूलमुद्गरपाणयः।
गदाभिः पट्टसैर्दण्डैरायसैर्मुसलैर्भृशम्॥', 'vividhāyudhahastāś ca śūlamudgarapāṇayaḥ
gadābhiḥ paṭṭasair daṇḍair āyasair musalair bhṛśam', null, 6041024),
('ramayana-6-41-25', 25, 'Yuddha Kanda, Sarga 41, Verse 25', 'परिघैर्भिण्डिपालैश्च भल्लैः प्रासैः परश्वधैः।
निर्ययू राक्षसा घोरा नर्दन्तो जलदा यथा॥', 'parighair bhiṇḍipālaiś ca bhallaiḥ prāsaiḥ paraśvadhaiḥ
niryayū rākṣasā ghorā nardanto jaladā yathā', null, 6041025),
('ramayana-6-41-26', 26, 'Yuddha Kanda, Sarga 41, Verse 26', 'रथैः कवचिनस्त्वन्ये ध्वजैश्च समलंकृतैः।
सुवर्णजालविहितैः खरैश्च विविधाननैः॥', 'rathaiḥ kavacinas tv anye dhvajaiś ca samalaṃkṛtaiḥ
suvarṇajālavihitaiḥ kharaiś ca vividhānanaiḥ', null, 6041026),
('ramayana-6-41-27', 27, 'Yuddha Kanda, Sarga 41, Verse 27', 'हयैः परमशीघ्रैश्च गजेन्द्रैश्च मदोत्कटैः।
निर्ययू राक्षसव्याघ्रा व्याघ्रा इव दुरासदाः॥', 'hayaiḥ paramaśīghraiś ca gajendraiś ca madotkaṭaiḥ
niryayū rākṣasavyāghrā vyāghrā iva durāsadāḥ', null, 6041027),
('ramayana-6-41-28', 28, 'Yuddha Kanda, Sarga 41, Verse 28', 'वृकसिंहमुखैर्युक्तं खरैः कनकभूषणैः।
आरुरोह रथं दिव्यं धूम्राक्षः खरनिस्वनः॥', 'vṛkasiṃhamukhair yuktaṃ kharaiḥ kanakabhūṣaṇaiḥ
āruroha rathaṃ divyaṃ dhūmrākṣaḥ kharanisvanaḥ', null, 6041028),
('ramayana-6-41-29', 29, 'Yuddha Kanda, Sarga 41, Verse 29', 'स निर्यातो महावीर्यो धूम्राक्षो राक्षसैर्वृतः।
प्रहसन्पश्चिमद्वारं हनूमान्यत्र यूथपः॥', 'sa niryāto mahāvīryo dhūmrākṣo rākṣasair vṛtaḥ
prahasan paścimadvāraṃ hanūmān yatra yūthapaḥ', null, 6041029),
('ramayana-6-41-30', 30, 'Yuddha Kanda, Sarga 41, Verse 30', 'प्रयान्तं तु महाघोरं राक्षसं भीमदर्शनम्।
अन्तरिक्षगताः क्रूराः शकुनाः प्रत्यवारयन्॥', 'prayāntaṃ tu mahāghoraṃ rākṣasaṃ bhīmadarśanam
antarikṣagatāḥ krūrāḥ śakunāḥ pratyavārayan', null, 6041030),
('ramayana-6-41-31', 31, 'Yuddha Kanda, Sarga 41, Verse 31', 'रथशीर्षे महाभीमो गृध्रश्च निपपात ह।
ध्वजाग्रे ग्रथिताश्चैव निपेतुः कुणपाशनाः॥', 'rathaśīrṣe mahābhīmo gṛdhraś ca nipapāta ha
dhvajāgre grathitāś caiva nipetuḥ kuṇapāśanāḥ', null, 6041031),
('ramayana-6-41-32', 32, 'Yuddha Kanda, Sarga 41, Verse 32', 'रुधिरार्द्रो महाञ्श्वेतः कबन्धः पतितो भुवि।
विस्वरं चोत्सृजन्नादं धूम्राक्षस्य समीपतः॥', 'rudhirārdro mahāñ śvetaḥ kabandhaḥ patito bhuvi
visvaraṃ cotsṛjan nādaṃ dhūmrākṣasya samīpataḥ', null, 6041032),
('ramayana-6-41-33', 33, 'Yuddha Kanda, Sarga 41, Verse 33', 'ववर्ष रुधिरं देवः संचचाल च मेदिनी।
प्रतिलोमं ववौ वायुर्निर्घातसमनिस्वनः।
तिमिरौघावृतास्तत्र दिशश्च न चकाशिरे॥', 'vavarṣa rudhiraṃ devaḥ saṃcacāla ca medinī
pratilomaṃ vavau vāyur nirghātasamanisvanaḥ
timiraughāvṛtās tatra diśaś ca na cakāśire', null, 6041033),
('ramayana-6-41-34', 34, 'Yuddha Kanda, Sarga 41, Verse 34', 'स तूत्पातांस्ततो दृष्ट्वा राक्षसानां भयावहान्।
प्रादुर्भूतान्सुघोरांश्च धूम्राक्षो व्यथितोऽभवत्॥', 'sa tūtpātāṃs tato dṛṣṭvā rākṣasānāṃ bhayāvahān
prādurbhūtān sughorāṃś ca dhūmrākṣo vyathito ''bhavat', null, 6041034),
('ramayana-6-41-35', 35, 'Yuddha Kanda, Sarga 41, Verse 35', 'ततः सुभीमो बहुभिर्निशाचरैर्वृतोऽभिनिष्क्रम्य रणोत्सुको बली।
ददर्श तां राघवबाहुपालितां समुद्रकल्पां बहुवानरीं चमूम्॥', 'tataḥ subhīmo bahubhir niśācarair vṛto ''bhiniṣkramya raṇotsuko balī
dadarśa tāṃ rāghavabāhupālitāṃ samudrakalpāṃ bahuvānarīṃ camūm', null, 6041035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 42 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-42-1', 1, 'Yuddha Kanda, Sarga 42, Verse 1', 'धूम्राक्षं प्रेक्ष्य निर्यान्तं राक्षसं भीमनिस्वनम्।
विनेदुर्वानराः सर्वे प्रहृष्टा युद्धकाङ्क्षिणः॥', 'dhūmrākṣaṃ prekṣya niryāntaṃ rākṣasaṃ bhīmanisvanam
vinedur vānarāḥ sarve prahṛṣṭā yuddhakāṅkṣiṇaḥ', null, 6042001),
('ramayana-6-42-2', 2, 'Yuddha Kanda, Sarga 42, Verse 2', 'तेषां तु तुमुलं युद्धं संजज्ञे हरिरक्षसाम्।
अन्योन्यं पादपैर्घोरैर्निघ्नतं शूलमुद्गरैः॥', 'teṣāṃ tu tumulaṃ yuddhaṃ saṃjajñe harirakṣasām
anyonyaṃ pādapair ghorair nighnataṃ śūlamudgaraiḥ', null, 6042002),
('ramayana-6-42-3', 3, 'Yuddha Kanda, Sarga 42, Verse 3', 'राक्षसैर्वानरा घोरा विनिकृत्ताः समन्ततः।
वानरै राक्षसाश्चापि द्रुमैर्भूमौ समीकृताः॥', 'rākṣasair vānarā ghorā vinikṛttāḥ samantataḥ
vānarai rākṣasāś cāpi drumair bhūmau samīkṛtāḥ', null, 6042003),
('ramayana-6-42-4', 4, 'Yuddha Kanda, Sarga 42, Verse 4', 'राक्षसाश्चापि संक्रुद्धा वानरान्निशितैः शरैः।
विव्यधुर्घोरसंकाशैः कङ्कपत्रैरजिह्मगैः॥', 'rākṣasāś cāpi saṃkruddhā vānarān niśitaiḥ śaraiḥ
vivyadhur ghorasaṃkāśaiḥ kaṅkapatrair ajihmagaiḥ', null, 6042004),
('ramayana-6-42-5', 5, 'Yuddha Kanda, Sarga 42, Verse 5', 'ते गदाभिश्च भीमाभिः पट्टसैः कूटमुद्गरैः।
घोरैश्च परिघैश्चित्रैस्त्रिशूलैश्चापि संशितैः॥', 'te gadābhiś ca bhīmābhiḥ paṭṭasaiḥ kūṭamudgaraiḥ
ghoraiś ca parighaiś citrais triśūlaiś cāpi saṃśitaiḥ', null, 6042005),
('ramayana-6-42-6', 6, 'Yuddha Kanda, Sarga 42, Verse 6', 'विदार्यमाणा रक्षोभिर्वानरास्ते महाबलाः।
अमर्षाज्जनितोद्धर्षाश्चक्रुः कर्माण्यभीतवत्॥', 'vidāryamāṇā rakṣobhir vānarās te mahābalāḥ
amarṣāj janitoddharṣāś cakruḥ karmāṇy abhītavat', null, 6042006),
('ramayana-6-42-7', 7, 'Yuddha Kanda, Sarga 42, Verse 7', 'शरनिर्भिन्नगात्रास्ते शूलनिर्भिन्नदेहिनः।
जगृहुस्ते द्रुमांस्तत्र शिलाश्च हरियूथपाः॥', 'śaranirbhinnagātrās te śūlanirbhinnadehinaḥ
jagṛhus te drumāṃs tatra śilāś ca hariyūthapāḥ', null, 6042007),
('ramayana-6-42-8', 8, 'Yuddha Kanda, Sarga 42, Verse 8', 'ते भीमवेगा हरयो नर्दमानास्ततस्ततः।
ममन्थू राक्षसान्भीमान्नामानि च बभाषिरे॥', 'te bhīmavegā harayo nardamānās tatas tataḥ
mamanthū rākṣasān bhīmān nāmāni ca babhāṣire', null, 6042008),
('ramayana-6-42-9', 9, 'Yuddha Kanda, Sarga 42, Verse 9', 'तद्बभूवाद्भुतं घोरं युद्धं वानररक्षसाम्।
शिलाभिर्विविधाभिश्च बहुशाखैश्च पादपैः॥', 'tad babhūvādbhutaṃ ghoraṃ yuddhaṃ vānararakṣasām
śilābhir vividhābhiś ca bahuśākhaiś ca pādapaiḥ', null, 6042009),
('ramayana-6-42-10', 10, 'Yuddha Kanda, Sarga 42, Verse 10', 'राक्षसा मथिताः के चिद्वानरैर्जितकाशिभिः।
ववर्षू रुधिरं के चिन्मुखै रुधिरभोजनाः॥', 'rākṣasā mathitāḥ ke cid vānarair jitakāśibhiḥ
vavarṣū rudhiraṃ ke cin mukhai rudhirabhojanāḥ', null, 6042010),
('ramayana-6-42-11', 11, 'Yuddha Kanda, Sarga 42, Verse 11', 'पार्श्वेषु दारिताः के चित्के चिद्राशीकृता द्रुमैः।
शिलाभिश्चूर्णिताः के चित्के चिद्दन्तैर्विदारिताः॥', 'pārśveṣu dāritāḥ ke cit ke cid rāśīkṛtā drumaiḥ
śilābhiś cūrṇitāḥ ke cit ke cid dantair vidāritāḥ', null, 6042011),
('ramayana-6-42-12', 12, 'Yuddha Kanda, Sarga 42, Verse 12', 'ध्वजैर्विमथितैर्भग्नैः खरैश्च विनिपातितैः।
रथैर्विध्वंसितैश्चापि पतितै रजनीचरैः॥', 'dhvajair vimathitair bhagnaiḥ kharaiś ca vinipātitaiḥ
rathair vidhvaṃsitaiś cāpi patitai rajanīcaraiḥ', null, 6042012),
('ramayana-6-42-13', 13, 'Yuddha Kanda, Sarga 42, Verse 13', 'वानरैर्भीमविक्रान्तैराप्लुत्याप्लुत्य वेगितैः।
राक्षसाः करजैस्तीक्ष्णैर्मुखेषु विनिकर्तिताः॥', 'vānarair bhīmavikrāntair āplutyāplutya vegitaiḥ
rākṣasāḥ karajais tīkṣṇair mukheṣu vinikartitāḥ', null, 6042013),
('ramayana-6-42-14', 14, 'Yuddha Kanda, Sarga 42, Verse 14', 'विवर्णवदना भूयो विप्रकीर्णशिरोरुहाः।
मूढाः शोणितगन्धेन निपेतुर्धरणीतले॥', 'vivarṇavadanā bhūyo viprakīrṇaśiroruhāḥ
mūḍhāḥ śoṇitagandhena nipetur dharaṇītale', null, 6042014),
('ramayana-6-42-15', 15, 'Yuddha Kanda, Sarga 42, Verse 15', 'नये तु परमक्रुद्धा राक्षसा भीमविक्रमाः।
तलैरेवाभिधावन्ति वज्रस्पर्शसमैर्हरीन्॥', 'naye tu paramakruddhā rākṣasā bhīmavikramāḥ
talair evābhidhāvanti vajrasparśasamair harīn', null, 6042015),
('ramayana-6-42-16', 16, 'Yuddha Kanda, Sarga 42, Verse 16', 'वनरैरापतन्तस्ते वेगिता वेगवत्तरैः।
मुष्टिभिश्चरणैर्दन्तैः पादपैश्चापपोथिताः॥', 'vanarair āpatantas te vegitā vegavattaraiḥ
muṣṭibhiś caraṇair dantaiḥ pādapaiś cāpapothitāḥ', null, 6042016),
('ramayana-6-42-17', 17, 'Yuddha Kanda, Sarga 42, Verse 17', 'सन्यं तु विद्रुतं दृष्ट्वा धूम्राक्षो राक्षसर्षभः।
क्रोधेन कदनं चक्रे वानराणां युयुत्सताम्॥', 'sanyaṃ tu vidrutaṃ dṛṣṭvā dhūmrākṣo rākṣasarṣabhaḥ
krodhena kadanaṃ cakre vānarāṇāṃ yuyutsatām', null, 6042017),
('ramayana-6-42-18', 18, 'Yuddha Kanda, Sarga 42, Verse 18', 'प्रासैः प्रमथिताः के चिद्वानराः शोणितस्रवाः।
मुद्गरैराहताः के चित्पतिता धरणीतले॥', 'prāsaiḥ pramathitāḥ ke cid vānarāḥ śoṇitasravāḥ
mudgarair āhatāḥ ke cit patitā dharaṇītale', null, 6042018),
('ramayana-6-42-19', 19, 'Yuddha Kanda, Sarga 42, Verse 19', 'परिघैर्मथितः के चिद्भिण्डिपालैर्विदारिताः।
पट्टसैराहताः के चिद्विह्वलन्तो गतासवः॥', 'parighair mathitaḥ ke cid bhiṇḍipālair vidāritāḥ
paṭṭasair āhatāḥ ke cid vihvalanto gatāsavaḥ', null, 6042019),
('ramayana-6-42-20', 20, 'Yuddha Kanda, Sarga 42, Verse 20', 'के चिद्विनिहता भूमौ रुधिरार्द्रा वनौकसः।
के चिद्विद्राविता नष्टाः संक्रुद्धै राक्षसैर्युधि॥', 'ke cid vinihatā bhūmau rudhirārdrā vanaukasaḥ
ke cid vidrāvitā naṣṭāḥ saṃkruddhai rākṣasair yudhi', null, 6042020),
('ramayana-6-42-21', 21, 'Yuddha Kanda, Sarga 42, Verse 21', 'विभिन्नहृदयाः के चिदेकपार्श्वेन शायिताः।
विदारितास्त्रशूलै च के चिदान्त्रैर्विनिस्रुताः॥', 'vibhinnahṛdayāḥ ke cid ekapārśvena śāyitāḥ
vidāritāstraśūlai ca ke cid āntrair vinisrutāḥ', null, 6042021),
('ramayana-6-42-22', 22, 'Yuddha Kanda, Sarga 42, Verse 22', 'तत्सुभीमं महद्युद्धं हरिराकस संकुलम्।
प्रबभौ शस्त्रबहुलं शिलापादपसंकुलम्॥', 'tat subhīmaṃ mahad yuddhaṃ harirākasa saṃkulam
prababhau śastrabahulaṃ śilāpādapasaṃkulam', null, 6042022),
('ramayana-6-42-23', 23, 'Yuddha Kanda, Sarga 42, Verse 23', 'धनुर्ज्यातन्त्रिमधुरं हिक्कातालसमन्वितम्।
मन्द्रस्तनितसंगीतं युद्धगान्धर्वमाबभौ॥', 'dhanurjyātantrimadhuraṃ hikkātālasamanvitam
mandrastanitasaṃgītaṃ yuddhagāndharvam ābabhau', null, 6042023),
('ramayana-6-42-24', 24, 'Yuddha Kanda, Sarga 42, Verse 24', 'धूम्राक्षस्तु धनुष्पाणिर्वानरान्रणमूर्धनि।
हसन्विद्रावयामास दिशस्ताञ्शरवृष्टिभिः॥', 'dhūmrākṣas tu dhanuṣpāṇir vānarān raṇamūrdhani
hasan vidrāvayām āsa diśas tāñ śaravṛṣṭibhiḥ', null, 6042024),
('ramayana-6-42-25', 25, 'Yuddha Kanda, Sarga 42, Verse 25', 'धूम्राक्षेणार्दितं सैन्यं व्यथितं दृश्य मारुतिः।
अभ्यवर्तत संक्रुद्धः प्रगृह्य विपुलां शिलाम्॥', 'dhūmrākṣeṇārditaṃ sainyaṃ vyathitaṃ dṛśya mārutiḥ
abhyavartata saṃkruddhaḥ pragṛhya vipulāṃ śilām', null, 6042025),
('ramayana-6-42-26', 26, 'Yuddha Kanda, Sarga 42, Verse 26', 'क्रोधाद्द्विगुणताम्राक्षः पितृतुल्यपराक्रमः।
शिलां तां पातयामास धूम्राक्षस्य रथं प्रति॥', 'krodhād dviguṇatāmrākṣaḥ pitṛtulyaparākramaḥ
śilāṃ tāṃ pātayām āsa dhūmrākṣasya rathaṃ prati', null, 6042026),
('ramayana-6-42-27', 27, 'Yuddha Kanda, Sarga 42, Verse 27', 'आपतन्तीं शिलां दृष्ट्वा गदामुद्यम्य संभ्रमात्।
रथादाप्लुत्य वेगेन वसुधायां व्यतिष्ठत॥', 'āpatantīṃ śilāṃ dṛṣṭvā gadām udyamya saṃbhramāt
rathād āplutya vegena vasudhāyāṃ vyatiṣṭhata', null, 6042027),
('ramayana-6-42-28', 28, 'Yuddha Kanda, Sarga 42, Verse 28', 'सा प्रमथ्य रथं तस्य निपपात शिलाभुवि।
सचक्रकूबरं साश्वं सध्वजं सशरासनम्॥', 'sā pramathya rathaṃ tasya nipapāta śilābhuvi
sacakrakūbaraṃ sāśvaṃ sadhvajaṃ saśarāsanam', null, 6042028),
('ramayana-6-42-29', 29, 'Yuddha Kanda, Sarga 42, Verse 29', 'स भङ्क्त्वा तु रथं तस्य हनूमान्मारुतात्मजः।
रक्षसां कदनं चक्रे सस्कन्धविटपैर्द्रुमैः॥', 'sa bhaṅktvā tu rathaṃ tasya hanūmān mārutātmajaḥ
rakṣasāṃ kadanaṃ cakre saskandhaviṭapair drumaiḥ', null, 6042029),
('ramayana-6-42-30', 30, 'Yuddha Kanda, Sarga 42, Verse 30', 'विभिन्नशिरसो भूत्वा राक्षसाः शोणितोक्षिताः।
द्रुमैः प्रमथिताश्चान्ये निपेतुर्धरणीतले॥', 'vibhinnaśiraso bhūtvā rākṣasāḥ śoṇitokṣitāḥ
drumaiḥ pramathitāś cānye nipetur dharaṇītale', null, 6042030),
('ramayana-6-42-31', 31, 'Yuddha Kanda, Sarga 42, Verse 31', 'विद्राव्य राक्षसं सैन्यं हनूमान्मारुतात्मजः।
गिरेः शिखरमादाय धूम्राक्षमभिदुद्रुवे॥', 'vidrāvya rākṣasaṃ sainyaṃ hanūmān mārutātmajaḥ
gireḥ śikharam ādāya dhūmrākṣam abhidudruve', null, 6042031),
('ramayana-6-42-32', 32, 'Yuddha Kanda, Sarga 42, Verse 32', 'तमापतन्तं धूम्राक्षो गदामुद्यम्य वीर्यवान्।
विनर्दमानः सहसा हनूमन्तमभिद्रवत्॥', 'tam āpatantaṃ dhūmrākṣo gadām udyamya vīryavān
vinardamānaḥ sahasā hanūmantam abhidravat', null, 6042032),
('ramayana-6-42-33', 33, 'Yuddha Kanda, Sarga 42, Verse 33', 'ततः क्रुद्धस्तु वेगेन गदां तां बहुकण्टकाम्।
पातयामास धूम्राक्षो मस्तके तु हनूमतः॥', 'tataḥ kruddhas tu vegena gadāṃ tāṃ bahukaṇṭakām
pātayām āsa dhūmrākṣo mastake tu hanūmataḥ', null, 6042033),
('ramayana-6-42-34', 34, 'Yuddha Kanda, Sarga 42, Verse 34', 'ताडितः स तया तत्र गदया भीमरूपया।
स कपिर्मारुतबलस्तं प्रहारमचिन्तयन्।
धूम्राक्षस्य शिरो मध्ये गिरिशृङ्गमपातयत्॥', 'tāḍitaḥ sa tayā tatra gadayā bhīmarūpayā
sa kapir mārutabalas taṃ prahāram acintayan
dhūmrākṣasya śiro madhye giriśṛṅgam apātayat', null, 6042034),
('ramayana-6-42-35', 35, 'Yuddha Kanda, Sarga 42, Verse 35', 'स विह्वलितसर्वाङ्गो गिरिशृङ्गेण ताडितः।
पपात सहसा भूमौ विकीर्ण इव पर्वतः॥', 'sa vihvalitasarvāṅgo giriśṛṅgeṇa tāḍitaḥ
papāta sahasā bhūmau vikīrṇa iva parvataḥ', null, 6042035),
('ramayana-6-42-36', 36, 'Yuddha Kanda, Sarga 42, Verse 36', 'धूम्राक्षं निहतं दृष्ट्वा हतशेषा निशाचराः।
त्रस्ताः प्रविविशुर्लङ्कां वध्यमानाः प्लवंगमैः॥', 'dhūmrākṣaṃ nihataṃ dṛṣṭvā hataśeṣā niśācarāḥ
trastāḥ praviviśur laṅkāṃ vadhyamānāḥ plavaṃgamaiḥ', null, 6042036),
('ramayana-6-42-37', 37, 'Yuddha Kanda, Sarga 42, Verse 37', 'स तु पवनसुतो निहत्य शत्रुं क्षतजवहाः सरितश्च संविकीर्य।
रिपुवधजनितश्रमो महात्मा मुदमगमत्कपिभिश्च पूज्यमानः॥', 'sa tu pavanasuto nihatya śatruṃ kṣatajavahāḥ saritaś ca saṃvikīrya
ripuvadhajanitaśramo mahātmā mudam agamat kapibhiś ca pūjyamānaḥ', null, 6042037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 43 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-43-1', 1, 'Yuddha Kanda, Sarga 43, Verse 1', 'धूम्राक्षं निहतं श्रुत्वा रावणो राक्षसेश्वरः।
बलाध्यक्षमुवाचेदं कृताञ्जलिमुपस्थितम्॥', 'dhūmrākṣaṃ nihataṃ śrutvā rāvaṇo rākṣaseśvaraḥ
balādhyakṣam uvācedaṃ kṛtāñjalim upasthitam', null, 6043001),
('ramayana-6-43-2', 2, 'Yuddha Kanda, Sarga 43, Verse 2', 'शीघ्रं निर्यान्तु दुर्धर्षा राक्षसा भीमविक्रमाः।
अकम्पनं पुरस्कृत्य सर्वशस्त्रप्रकोविदम्॥', 'śīghraṃ niryāntu durdharṣā rākṣasā bhīmavikramāḥ
akampanaṃ puraskṛtya sarvaśastraprakovidam', null, 6043002),
('ramayana-6-43-3', 3, 'Yuddha Kanda, Sarga 43, Verse 3', 'ततो नानाप्रहरणा भीमाक्षा भीमदर्शनाः।
निष्पेतू राक्षसा मुख्या बलाध्यक्षप्रचोदिताः॥', 'tato nānāpraharaṇā bhīmākṣā bhīmadarśanāḥ
niṣpetū rākṣasā mukhyā balādhyakṣapracoditāḥ', null, 6043003),
('ramayana-6-43-4', 4, 'Yuddha Kanda, Sarga 43, Verse 4', 'रथमास्थाय विपुलं तप्तकाञ्चनकुण्डलः।
राकसैः संवृतो घोरैस्तदा निर्यात्यकम्पनः॥', 'ratham āsthāya vipulaṃ taptakāñcanakuṇḍalaḥ
rākasaiḥ saṃvṛto ghorais tadā niryāty akampanaḥ', null, 6043004),
('ramayana-6-43-5', 5, 'Yuddha Kanda, Sarga 43, Verse 5', 'न हि कम्पयितुं शक्यः सुरैरपि महामृधे।
अकम्पनस्ततस्तेषामादित्य इव तेजसा॥', 'na hi kampayituṃ śakyaḥ surair api mahāmṛdhe
akampanas tatas teṣām āditya iva tejasā', null, 6043005),
('ramayana-6-43-6', 6, 'Yuddha Kanda, Sarga 43, Verse 6', 'तस्य निधावमानस्य संरब्धस्य युयुत्सया।
अकस्माद्दैन्यमागच्छद्धयानां रथवाहिनाम्॥', 'tasya nidhāvamānasya saṃrabdhasya yuyutsayā
akasmād dainyam āgacchad dhayānāṃ rathavāhinām', null, 6043006),
('ramayana-6-43-7', 7, 'Yuddha Kanda, Sarga 43, Verse 7', 'व्यस्फुरन्नयनं चास्य सव्यं युद्धाभिनन्दिनः।
विवर्णो मुखवर्णश्च गद्गदश्चाभवत्स्वरः॥', 'vyasphuran nayanaṃ cāsya savyaṃ yuddhābhinandinaḥ
vivarṇo mukhavarṇaś ca gadgadaś cābhavat svaraḥ', null, 6043007),
('ramayana-6-43-8', 8, 'Yuddha Kanda, Sarga 43, Verse 8', 'अभवत्सुदिने चापि दुर्दिने रूक्षमारुतम्।
ऊचुः खगा मृगाः सर्वे वाचः क्रूरा भयावहाः॥', 'abhavat sudine cāpi durdine rūkṣamārutam
ūcuḥ khagā mṛgāḥ sarve vācaḥ krūrā bhayāvahāḥ', null, 6043008),
('ramayana-6-43-9', 9, 'Yuddha Kanda, Sarga 43, Verse 9', 'स सिंहोपचितस्कन्धः शार्दूलसमविक्रमः।
तानुत्पातानचिन्त्यैव निर्जगाम रणाजिरम्॥', 'sa siṃhopacitaskandhaḥ śārdūlasamavikramaḥ
tān utpātān acintyaiva nirjagāma raṇājiram', null, 6043009),
('ramayana-6-43-10', 10, 'Yuddha Kanda, Sarga 43, Verse 10', 'तदा निर्गच्छतस्तस्य रक्षसः सह राक्षसैः।
बभूव सुमहान्नादः क्षोभयन्निव सागरम्॥', 'tadā nirgacchatas tasya rakṣasaḥ saha rākṣasaiḥ
babhūva sumahān nādaḥ kṣobhayann iva sāgaram', null, 6043010),
('ramayana-6-43-11', 11, 'Yuddha Kanda, Sarga 43, Verse 11', 'तेन शब्देन वित्रस्ता वानराणां महाचमूः।
द्रुमशैलप्रहरणा योद्धुं समवतिष्ठत॥', 'tena śabdena vitrastā vānarāṇāṃ mahācamūḥ
drumaśailapraharaṇā yoddhuṃ samavatiṣṭhata', null, 6043011),
('ramayana-6-43-12', 12, 'Yuddha Kanda, Sarga 43, Verse 12', 'तेषां युद्धं महारौद्रं संजज्ञे कपिरक्षसाम्।
रामरावणयोरर्थे समभित्यक्तजीविनाम्॥', 'teṣāṃ yuddhaṃ mahāraudraṃ saṃjajñe kapirakṣasām
rāmarāvaṇayor arthe samabhityaktajīvinām', null, 6043012),
('ramayana-6-43-13', 13, 'Yuddha Kanda, Sarga 43, Verse 13', 'सर्वे ह्यतिबलाः शूराः सर्वे पर्वतसंनिभाः।
हरयो राक्षसाश्चैव परस्परजिघंसवः॥', 'sarve hy atibalāḥ śūrāḥ sarve parvatasaṃnibhāḥ
harayo rākṣasāś caiva parasparajighaṃsavaḥ', null, 6043013),
('ramayana-6-43-14', 14, 'Yuddha Kanda, Sarga 43, Verse 14', 'तेषां विनर्दातां शब्दः संयुगेऽतितरस्विनाम्।
शुश्रुवे सुमहान्क्रोधादन्योन्यमभिगर्जताम्॥', 'teṣāṃ vinardātāṃ śabdaḥ saṃyuge ''titarasvinām
śuśruve sumahān krodhād anyonyam abhigarjatām', null, 6043014),
('ramayana-6-43-15', 15, 'Yuddha Kanda, Sarga 43, Verse 15', 'रजश्चारुणवर्णाभं सुभीममभवद्भृशम्।
उद्धूतं हरिरक्षोभिः संरुरोध दिशो दश॥', 'rajaś cāruṇavarṇābhaṃ subhīmam abhavad bhṛśam
uddhūtaṃ harirakṣobhiḥ saṃrurodha diśo daśa', null, 6043015),
('ramayana-6-43-16', 16, 'Yuddha Kanda, Sarga 43, Verse 16', 'अन्योन्यं रजसा तेन कौशेयोद्धूतपाण्डुना।
संवृतानि च भूतानि ददृशुर्न रणाजिरे॥', 'anyonyaṃ rajasā tena kauśeyoddhūtapāṇḍunā
saṃvṛtāni ca bhūtāni dadṛśur na raṇājire', null, 6043016),
('ramayana-6-43-17', 17, 'Yuddha Kanda, Sarga 43, Verse 17', 'न ध्वजो न पताकावा वर्म वा तुरगोऽपि वा।
आयुधं स्यन्दनं वापि ददृशे तेन रेणुना॥', 'na dhvajo na patākāvā varma vā turago ''pi vā
āyudhaṃ syandanaṃ vāpi dadṛśe tena reṇunā', null, 6043017),
('ramayana-6-43-18', 18, 'Yuddha Kanda, Sarga 43, Verse 18', 'शब्दश्च सुमहांस्तेषां नर्दतामभिधावताम्।
श्रूयते तुमुले युद्धे न रूपाणि चकाशिरे॥', 'śabdaś ca sumahāṃs teṣāṃ nardatām abhidhāvatām
śrūyate tumule yuddhe na rūpāṇi cakāśire', null, 6043018),
('ramayana-6-43-19', 19, 'Yuddha Kanda, Sarga 43, Verse 19', 'हरीनेव सुसंक्रुद्धा हरयो जघ्नुराहवे।
राक्षसाश्चापि रक्षांसि निजघ्नुस्तिमिरे तदा॥', 'harīn eva susaṃkruddhā harayo jaghnur āhave
rākṣasāś cāpi rakṣāṃsi nijaghnus timire tadā', null, 6043019),
('ramayana-6-43-20', 20, 'Yuddha Kanda, Sarga 43, Verse 20', 'परांश्चैव विनिघ्नन्तः स्वांश्च वानरराक्षसाः।
रुधिरार्द्रं तदा चक्रुर्महीं पङ्कानुलेपनाम्॥', 'parāṃś caiva vinighnantaḥ svāṃś ca vānararākṣasāḥ
rudhirārdraṃ tadā cakrur mahīṃ paṅkānulepanām', null, 6043020),
('ramayana-6-43-21', 21, 'Yuddha Kanda, Sarga 43, Verse 21', 'ततस्तु रुधिरौघेण सिक्तं व्यपगतं रजः।
शरीरशवसंकीर्णा बभूव च वसुंधरा॥', 'tatas tu rudhiraugheṇa siktaṃ vyapagataṃ rajaḥ
śarīraśavasaṃkīrṇā babhūva ca vasuṃdharā', null, 6043021),
('ramayana-6-43-22', 22, 'Yuddha Kanda, Sarga 43, Verse 22', 'द्रुमशक्तिशिलाप्रासैर्गदापरिघतोमरैः।
हरयो राक्षसास्तूर्णं जघ्नुरन्योन्यमोजसा॥', 'drumaśaktiśilāprāsair gadāparighatomaraiḥ
harayo rākṣasās tūrṇaṃ jaghnur anyonyam ojasā', null, 6043022),
('ramayana-6-43-23', 23, 'Yuddha Kanda, Sarga 43, Verse 23', 'बाहुभिः परिघाकारैर्युध्यन्तः पर्वतोपमाः।
हरयो भीमकर्माणो राक्षसाञ्जघ्नुराहवे॥', 'bāhubhiḥ parighākārair yudhyantaḥ parvatopamāḥ
harayo bhīmakarmāṇo rākṣasāñ jaghnur āhave', null, 6043023),
('ramayana-6-43-24', 24, 'Yuddha Kanda, Sarga 43, Verse 24', 'राक्षसाश्चापि संक्रुद्धाः प्रासतोमरपाणयः।
कपीन्निजघ्निरे तत्र शस्त्रैः परमदारुणैः॥', 'rākṣasāś cāpi saṃkruddhāḥ prāsatomarapāṇayaḥ
kapīn nijaghnire tatra śastraiḥ paramadāruṇaiḥ', null, 6043024),
('ramayana-6-43-25', 25, 'Yuddha Kanda, Sarga 43, Verse 25', 'हरयस्त्वपि रक्षांसि महाद्रुममहाश्मभिः।
विदारयन्त्यभिक्रम्य शस्त्राण्याच्छिद्य वीर्यतः॥', 'harayas tv api rakṣāṃsi mahādrumamahāśmabhiḥ
vidārayanty abhikramya śastrāṇy ācchidya vīryataḥ', null, 6043025),
('ramayana-6-43-26', 26, 'Yuddha Kanda, Sarga 43, Verse 26', 'एतस्मिन्नन्तरे वीरा हरयः कुमुदो नलः।
मैन्दश्च परमक्रुद्धश्चक्रुर्वेगमनुत्तमम्॥', 'etasminn antare vīrā harayaḥ kumudo nalaḥ
maindaś ca paramakruddhaś cakrur vegam anuttamam', null, 6043026),
('ramayana-6-43-27', 27, 'Yuddha Kanda, Sarga 43, Verse 27', 'ते तु वृक्षैर्महावेगा राक्षसानां चमूमुखे।
कदनं सुमह चक्रुर्लीलया हरियूथपाः॥', 'te tu vṛkṣair mahāvegā rākṣasānāṃ camūmukhe
kadanaṃ sumaha cakrur līlayā hariyūthapāḥ', null, 6043027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 44 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-44-1', 1, 'Yuddha Kanda, Sarga 44, Verse 1', 'तद्दृष्ट्वा सुमहत्कर्म कृतं वानरसत्तमैः।
क्रोधमाहारयामास युधि तीव्रमकम्पनः॥', 'tad dṛṣṭvā sumahat karma kṛtaṃ vānarasattamaiḥ
krodham āhārayām āsa yudhi tīvram akampanaḥ', null, 6044001),
('ramayana-6-44-2', 2, 'Yuddha Kanda, Sarga 44, Verse 2', 'क्रोधमूर्छितरूपस्तु ध्नुवन्परमकार्मुकम्।
दृष्ट्वा तु कर्म शत्रूणां सारथिं वाक्यमब्रवीत्॥', 'krodhamūrchitarūpas tu dhnuvan paramakārmukam
dṛṣṭvā tu karma śatrūṇāṃ sārathiṃ vākyam abravīt', null, 6044002),
('ramayana-6-44-3', 3, 'Yuddha Kanda, Sarga 44, Verse 3', 'तत्रैव तावत्त्वरितं रथं प्रापय सारथे।
एतेऽत्र बहवो घ्नन्ति सुबहून्राक्षसान्रणे॥', 'tatraiva tāvat tvaritaṃ rathaṃ prāpaya sārathe
ete ''tra bahavo ghnanti subahūn rākṣasān raṇe', null, 6044003),
('ramayana-6-44-4', 4, 'Yuddha Kanda, Sarga 44, Verse 4', 'एतेऽत्र बलवन्तो हि भीमकायाश्च वानराः।
द्रुमशैलप्रहरणास्तिष्ठन्ति प्रमुखे मम॥', 'ete ''tra balavanto hi bhīmakāyāś ca vānarāḥ
drumaśailapraharaṇās tiṣṭhanti pramukhe mama', null, 6044004),
('ramayana-6-44-5', 5, 'Yuddha Kanda, Sarga 44, Verse 5', 'एतान्निहन्तुमिच्छामि समरश्लाघिनो ह्यहम्।
एतैः प्रमथितं सर्वं दृश्यते राक्षसं बलम्॥', 'etān nihantum icchāmi samaraślāghino hy aham
etaiḥ pramathitaṃ sarvaṃ dṛśyate rākṣasaṃ balam', null, 6044005),
('ramayana-6-44-6', 6, 'Yuddha Kanda, Sarga 44, Verse 6', 'ततः प्रजविताश्वेन रथेन रथिनां वरः।
हरीनभ्यहनत्क्रोधाच्छरजालैरकम्पनः॥', 'tataḥ prajavitāśvena rathena rathināṃ varaḥ
harīn abhyahanat krodhāc charajālair akampanaḥ', null, 6044006),
('ramayana-6-44-7', 7, 'Yuddha Kanda, Sarga 44, Verse 7', 'न स्थातुं वानराः शेकुः किं पुनर्योद्धुमाहवे।
अकम्पनशरैर्भग्नाः सर्व एव प्रदुद्रुवुः॥', 'na sthātuṃ vānarāḥ śekuḥ kiṃ punar yoddhum āhave
akampanaśarair bhagnāḥ sarva eva pradudruvuḥ', null, 6044007),
('ramayana-6-44-8', 8, 'Yuddha Kanda, Sarga 44, Verse 8', 'तान्मृत्युवशमापन्नानकम्पनवशं गतान्।
समीक्ष्य हनुमाञ्ज्ञातीनुपतस्थे महाबलः॥', 'tān mṛtyuvaśam āpannān akampanavaśaṃ gatān
samīkṣya hanumāñ jñātīn upatasthe mahābalaḥ', null, 6044008),
('ramayana-6-44-9', 9, 'Yuddha Kanda, Sarga 44, Verse 9', 'तं महाप्लवगं दृष्ट्वा सर्वे प्लवगयूथपाः।
समेत्य समरे वीराः सहिताः पर्यवारयन्॥', 'taṃ mahāplavagaṃ dṛṣṭvā sarve plavagayūthapāḥ
sametya samare vīrāḥ sahitāḥ paryavārayan', null, 6044009),
('ramayana-6-44-10', 10, 'Yuddha Kanda, Sarga 44, Verse 10', 'व्यवस्थितं हनूमन्तं ते दृष्ट्वा हरियूथपाः।
बभूवुर्बलवन्तो हि बलवन्तमुपाश्रिताः॥', 'vyavasthitaṃ hanūmantaṃ te dṛṣṭvā hariyūthapāḥ
babhūvur balavanto hi balavantam upāśritāḥ', null, 6044010),
('ramayana-6-44-11', 11, 'Yuddha Kanda, Sarga 44, Verse 11', 'अकम्पनस्तु शैलाभं हनूमन्तमवस्थितम्।
महेन्द्र इव धाराभिः शरैरभिववर्ष ह॥', 'akampanas tu śailābhaṃ hanūmantam avasthitam
mahendra iva dhārābhiḥ śarair abhivavarṣa ha', null, 6044011),
('ramayana-6-44-12', 12, 'Yuddha Kanda, Sarga 44, Verse 12', 'अचिन्तयित्वा बाणौघाञ्शरीरे पतिताञ्शितान्।
अकम्पनवधार्थाय मनो दध्रे महाबलः॥', 'acintayitvā bāṇaughāñ śarīre patitāñ śitān
akampanavadhārthāya mano dadhre mahābalaḥ', null, 6044012),
('ramayana-6-44-13', 13, 'Yuddha Kanda, Sarga 44, Verse 13', 'स प्रहस्य महातेजा हनूमान्मारुतात्मजः।
अभिदुद्राव तद्रक्षः कम्पयन्निव मेदिनीम्॥', 'sa prahasya mahātejā hanūmān mārutātmajaḥ
abhidudrāva tad rakṣaḥ kampayann iva medinīm', null, 6044013),
('ramayana-6-44-14', 14, 'Yuddha Kanda, Sarga 44, Verse 14', 'तस्याभिनर्दमानस्य दीप्यमानस्य तेजसा।
बभूव रूपं दुर्धर्षं दीप्तस्येव विभावसोः॥', 'tasyābhinardamānasya dīpyamānasya tejasā
babhūva rūpaṃ durdharṣaṃ dīptasyeva vibhāvasoḥ', null, 6044014),
('ramayana-6-44-15', 15, 'Yuddha Kanda, Sarga 44, Verse 15', 'आत्मानं त्वप्रहरणं ज्ञात्वा क्रोधसमन्वितः।
शैलमुत्पाटयामास वेगेन हरिपुंगवः॥', 'ātmānaṃ tv apraharaṇaṃ jñātvā krodhasamanvitaḥ
śailam utpāṭayām āsa vegena haripuṃgavaḥ', null, 6044015),
('ramayana-6-44-16', 16, 'Yuddha Kanda, Sarga 44, Verse 16', 'तं गृहीत्वा महाशैलं पाणिनैकेन मारुतिः।
विनद्य सुमहानादं भ्रामयामास वीर्यवान्॥', 'taṃ gṛhītvā mahāśailaṃ pāṇinaikena mārutiḥ
vinadya sumahānādaṃ bhrāmayām āsa vīryavān', null, 6044016),
('ramayana-6-44-17', 17, 'Yuddha Kanda, Sarga 44, Verse 17', 'ततस्तमभिदुद्राव राक्षसेन्द्रमकम्पनम्।
यथा हि नमुचिं संख्ये वज्रेणेव पुरंदरः॥', 'tatas tam abhidudrāva rākṣasendram akampanam
yathā hi namuciṃ saṃkhye vajreṇeva puraṃdaraḥ', null, 6044017),
('ramayana-6-44-18', 18, 'Yuddha Kanda, Sarga 44, Verse 18', 'अकम्पनस्तु तद्दृष्ट्वा गिरिशृङ्गं समुद्यतम्।
दूरादेव महाबाणैरर्धचन्द्रैर्व्यदारयत्॥', 'akampanas tu tad dṛṣṭvā giriśṛṅgaṃ samudyatam
dūrād eva mahābāṇair ardhacandrair vyadārayat', null, 6044018),
('ramayana-6-44-19', 19, 'Yuddha Kanda, Sarga 44, Verse 19', 'तत्पर्वताग्रमाकाशे रक्षोबाणविदारितम्।
विकीर्णं पतितं दृष्ट्वा हनूमान्क्रोधमूर्छितः॥', 'tat parvatāgram ākāśe rakṣobāṇavidāritam
vikīrṇaṃ patitaṃ dṛṣṭvā hanūmān krodhamūrchitaḥ', null, 6044019),
('ramayana-6-44-20', 20, 'Yuddha Kanda, Sarga 44, Verse 20', 'सोऽश्वकर्णं समासाद्य रोषदर्पान्वितो हरिः।
तूर्णमुत्पाटयामास महागिरिमिवोच्छ्रितम्॥', 'so ''śvakarṇaṃ samāsādya roṣadarpānvito hariḥ
tūrṇam utpāṭayām āsa mahāgirim ivocchritam', null, 6044020),
('ramayana-6-44-21', 21, 'Yuddha Kanda, Sarga 44, Verse 21', 'तं गृहीत्वा महास्कन्धं सोऽश्वकर्णं महाद्युतिः।
प्रहस्य परया प्रीत्या भ्रामयामास संयुगे॥', 'taṃ gṛhītvā mahāskandhaṃ so ''śvakarṇaṃ mahādyutiḥ
prahasya parayā prītyā bhrāmayām āsa saṃyuge', null, 6044021),
('ramayana-6-44-22', 22, 'Yuddha Kanda, Sarga 44, Verse 22', 'प्रधावन्नुरुवेगेन प्रभञ्जंस्तरसा द्रुमान्।
हनूमान्परमक्रुद्धश्चरणैर्दारयत्क्षितिम्॥', 'pradhāvann uruvegena prabhañjaṃs tarasā drumān
hanūmān paramakruddhaś caraṇair dārayat kṣitim', null, 6044022),
('ramayana-6-44-23', 23, 'Yuddha Kanda, Sarga 44, Verse 23', 'गजांश्च सगजारोहान्सरथान्रथिनस्तथा।
जघान हनुमान्धीमान्राक्षसांश्च पदातिकान्॥', 'gajāṃś ca sagajārohān sarathān rathinas tathā
jaghāna hanumān dhīmān rākṣasāṃś ca padātikān', null, 6044023),
('ramayana-6-44-24', 24, 'Yuddha Kanda, Sarga 44, Verse 24', 'तमन्तकमिव क्रुद्धं समरे प्राणहारिणम्।
हनूमन्तमभिप्रेक्ष्य राक्षसा विप्रदुद्रुवुः॥', 'tam antakam iva kruddhaṃ samare prāṇahāriṇam
hanūmantam abhiprekṣya rākṣasā vipradudruvuḥ', null, 6044024),
('ramayana-6-44-25', 25, 'Yuddha Kanda, Sarga 44, Verse 25', 'तमापतन्तं संक्रुद्धं राक्षसानां भयावहम्।
ददर्शाकम्पनो वीरश्चुक्रोध च ननाद च॥', 'tam āpatantaṃ saṃkruddhaṃ rākṣasānāṃ bhayāvaham
dadarśākampano vīraś cukrodha ca nanāda ca', null, 6044025),
('ramayana-6-44-26', 26, 'Yuddha Kanda, Sarga 44, Verse 26', 'स चतुर्दशभिर्बाणैः शितैर्देहविदारणैः।
निर्बिभेद हनूमन्तं महावीर्यमकम्पनः॥', 'sa caturdaśabhir bāṇaiḥ śitair dehavidāraṇaiḥ
nirbibheda hanūmantaṃ mahāvīryam akampanaḥ', null, 6044026),
('ramayana-6-44-27', 27, 'Yuddha Kanda, Sarga 44, Verse 27', 'स तथा प्रतिविद्धस्तु बह्वीभिः शरवृष्टिभिः।
हनूमान्ददृशे वीरः प्ररूढ इव सानुमान्॥', 'sa tathā pratividdhas tu bahvībhiḥ śaravṛṣṭibhiḥ
hanūmān dadṛśe vīraḥ prarūḍha iva sānumān', null, 6044027),
('ramayana-6-44-28', 28, 'Yuddha Kanda, Sarga 44, Verse 28', 'ततोऽन्यं वृक्षमुत्पाट्य कृत्वा वेगमनुत्तमम्।
शिरस्यभिजघानाशु राक्षसेन्द्रमकम्पनम्॥', 'tato ''nyaṃ vṛkṣam utpāṭya kṛtvā vegam anuttamam
śirasy abhijaghānāśu rākṣasendram akampanam', null, 6044028),
('ramayana-6-44-29', 29, 'Yuddha Kanda, Sarga 44, Verse 29', 'स वृक्षेण हतस्तेन सक्रोधेन महात्मना।
राक्षसो वानरेन्द्रेण पपात स ममार च॥', 'sa vṛkṣeṇa hatas tena sakrodhena mahātmanā
rākṣaso vānarendreṇa papāta sa mamāra ca', null, 6044029),
('ramayana-6-44-30', 30, 'Yuddha Kanda, Sarga 44, Verse 30', 'तं दृष्ट्वा निहतं भूमौ राक्षसेन्द्रमकम्पनम्।
व्यथिता राक्षसाः सर्वे क्षितिकम्प इव द्रुमाः॥', 'taṃ dṛṣṭvā nihataṃ bhūmau rākṣasendram akampanam
vyathitā rākṣasāḥ sarve kṣitikampa iva drumāḥ', null, 6044030),
('ramayana-6-44-31', 31, 'Yuddha Kanda, Sarga 44, Verse 31', 'त्यक्तप्रहरणाः सर्वे राक्षसास्ते पराजिताः।
लङ्कामभिययुस्त्रस्ता वानरैस्तैरभिद्रुताः॥', 'tyaktapraharaṇāḥ sarve rākṣasās te parājitāḥ
laṅkām abhiyayus trastā vānarais tair abhidrutāḥ', null, 6044031),
('ramayana-6-44-32', 32, 'Yuddha Kanda, Sarga 44, Verse 32', 'ते मुक्तकेशाः संभ्रान्ता भग्नमानाः पराजिताः।
स्रवच्छ्रमजलैरङ्गैः श्वसन्तो विप्रदुद्रुवुः॥', 'te muktakeśāḥ saṃbhrāntā bhagnamānāḥ parājitāḥ
sravacchramajalair aṅgaiḥ śvasanto vipradudruvuḥ', null, 6044032),
('ramayana-6-44-33', 33, 'Yuddha Kanda, Sarga 44, Verse 33', 'अन्योन्यं प्रममन्तुस्ते विविशुर्नगरं भयात्।
पृष्ठतस्ते सुसंमूढाः प्रेक्षमाणा मुहुर्मुहुः॥', 'anyonyaṃ pramamantus te viviśur nagaraṃ bhayāt
pṛṣṭhatas te susaṃmūḍhāḥ prekṣamāṇā muhur muhuḥ', null, 6044033),
('ramayana-6-44-34', 34, 'Yuddha Kanda, Sarga 44, Verse 34', 'तेषु लङ्कां प्रविष्टेषु राक्षसेषु महाबलाः।
समेत्य हरयः सर्वे हनूमन्तमपूजयन्॥', 'teṣu laṅkāṃ praviṣṭeṣu rākṣaseṣu mahābalāḥ
sametya harayaḥ sarve hanūmantam apūjayan', null, 6044034),
('ramayana-6-44-35', 35, 'Yuddha Kanda, Sarga 44, Verse 35', 'सोऽपि प्रहृष्टस्तान्सर्वान्हरीन्संप्रत्यपूजयत्।
हनूमान्सत्त्वसंपन्नो यथार्हमनुकूलतः॥', 'so ''pi prahṛṣṭas tān sarvān harīn saṃpratyapūjayat
hanūmān sattvasaṃpanno yathārham anukūlataḥ', null, 6044035),
('ramayana-6-44-36', 36, 'Yuddha Kanda, Sarga 44, Verse 36', 'विनेदुश्च यथा प्राणं हरयो जितकाशिनः।
चकर्षुश्च पुनस्तत्र सप्राणानेव राक्षसान्॥', 'vineduś ca yathā prāṇaṃ harayo jitakāśinaḥ
cakarṣuś ca punas tatra saprāṇān eva rākṣasān', null, 6044036),
('ramayana-6-44-37', 37, 'Yuddha Kanda, Sarga 44, Verse 37', 'स वीरशोभामभजन्महाकपिः समेत्य रक्षांसि निहत्य मारुतिः।
महासुरं भीमममित्रनाशनं यथैव विष्णुर्बलिनं चमूमुखे॥', 'sa vīraśobhām abhajan mahākapiḥ sametya rakṣāṃsi nihatya mārutiḥ
mahāsuraṃ bhīmam amitranāśanaṃ yathaiva viṣṇur balinaṃ camūmukhe', null, 6044037),
('ramayana-6-44-38', 38, 'Yuddha Kanda, Sarga 44, Verse 38', 'अपूजयन्देवगणास्तदा कपिं स्वयं च रामोऽतिबलश्च लक्ष्मणः।
तथैव सुग्रीवमुखाः प्लवंगमा विभीषणश्चैव महाबलस्तदा॥', 'apūjayan devagaṇās tadā kapiṃ svayaṃ ca rāmo ''tibalaś ca lakṣmaṇaḥ
tathaiva sugrīvamukhāḥ plavaṃgamā vibhīṣaṇaś caiva mahābalas tadā', null, 6044038)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 45 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-45-1', 1, 'Yuddha Kanda, Sarga 45, Verse 1', 'अकम्पनवधं श्रुत्वा क्रुद्धो वै राक्षसेश्वरः।
किं चिद्दीनमुखश्चापि सचिवांस्तानुदैक्षत॥', 'akampanavadhaṃ śrutvā kruddho vai rākṣaseśvaraḥ
kiṃ cid dīnamukhaś cāpi sacivāṃs tān udaikṣata', null, 6045001),
('ramayana-6-45-2', 2, 'Yuddha Kanda, Sarga 45, Verse 2', 'स तु ध्यात्वा मुहूर्तं तु मन्त्रिभिः संविचार्य च।
पुरीं परिययौ लङ्कां सर्वान्गुल्मानवेक्षितुम्॥', 'sa tu dhyātvā muhūrtaṃ tu mantribhiḥ saṃvicārya ca
purīṃ pariyayau laṅkāṃ sarvān gulmān avekṣitum', null, 6045002),
('ramayana-6-45-3', 3, 'Yuddha Kanda, Sarga 45, Verse 3', 'तां राक्षसगणैर्गुप्तां गुल्मैर्बहुभिरावृताम्।
ददर्श नगरीं लङ्कां पताकाध्वजमालिनीम्॥', 'tāṃ rākṣasagaṇair guptāṃ gulmair bahubhir āvṛtām
dadarśa nagarīṃ laṅkāṃ patākādhvajamālinīm', null, 6045003),
('ramayana-6-45-4', 4, 'Yuddha Kanda, Sarga 45, Verse 4', 'रुद्धां तु नगरीं दृष्ट्वा रावणो राक्षसेश्वरः।
उवाचामर्षितः काले प्रहस्तं युद्धकोविदम्॥', 'ruddhāṃ tu nagarīṃ dṛṣṭvā rāvaṇo rākṣaseśvaraḥ
uvācāmarṣitaḥ kāle prahastaṃ yuddhakovidam', null, 6045004),
('ramayana-6-45-5', 5, 'Yuddha Kanda, Sarga 45, Verse 5', 'पुरस्योपनिविष्टस्य सहसा पीडितस्य च।
नान्यं युद्धात्प्रपश्यामि मोक्षं युद्धविशारद॥', 'purasyopaniviṣṭasya sahasā pīḍitasya ca
nānyaṃ yuddhāt prapaśyāmi mokṣaṃ yuddhaviśārada', null, 6045005),
('ramayana-6-45-6', 6, 'Yuddha Kanda, Sarga 45, Verse 6', 'अहं वा कुम्भकर्णो वा त्वं वा सेनापतिर्मम।
इन्द्रजिद्वा निकुम्भो वा वहेयुर्भारमीदृशम्॥', 'ahaṃ vā kumbhakarṇo vā tvaṃ vā senāpatir mama
indrajid vā nikumbho vā vaheyur bhāram īdṛśam', null, 6045006),
('ramayana-6-45-7', 7, 'Yuddha Kanda, Sarga 45, Verse 7', 'स त्वं बलमितः शीघ्रमादाय परिगृह्य च।
विजयायाभिनिर्याहि यत्र सर्वे वनौकसः॥', 'sa tvaṃ balam itaḥ śīghram ādāya parigṛhya ca
vijayāyābhiniryāhi yatra sarve vanaukasaḥ', null, 6045007),
('ramayana-6-45-8', 8, 'Yuddha Kanda, Sarga 45, Verse 8', 'निर्याणादेव ते नूनं चपला हरिवाहिनी।
नर्दतां राक्षसेन्द्राणां श्रुत्वा नादं द्रविष्यति॥', 'niryāṇād eva te nūnaṃ capalā harivāhinī
nardatāṃ rākṣasendrāṇāṃ śrutvā nādaṃ draviṣyati', null, 6045008),
('ramayana-6-45-9', 9, 'Yuddha Kanda, Sarga 45, Verse 9', 'चपला ह्यविनीताश्च चलचित्ताश्च वानराः।
न सहिष्यन्ति ते नादं सिंहनादमिव द्विपाः॥', 'capalā hy avinītāś ca calacittāś ca vānarāḥ
na sahiṣyanti te nādaṃ siṃhanādam iva dvipāḥ', null, 6045009),
('ramayana-6-45-10', 10, 'Yuddha Kanda, Sarga 45, Verse 10', 'विद्रुते च बले तस्मिन्रामः सौमित्रिणा सह।
अवशस्ते निरालम्बः प्रहस्तवशमेष्यति॥', 'vidrute ca bale tasmin rāmaḥ saumitriṇā saha
avaśaste nirālambaḥ prahastavaśam eṣyati', null, 6045010),
('ramayana-6-45-11', 11, 'Yuddha Kanda, Sarga 45, Verse 11', 'आपत्संशयिता श्रेयो नात्र निःसंशयीकृता।
प्रतिलोमानुलोमं वा यद्वा नो मन्यसे हितम्॥', 'āpatsaṃśayitā śreyo nātra niḥsaṃśayīkṛtā
pratilomānulomaṃ vā yad vā no manyase hitam', null, 6045011),
('ramayana-6-45-12', 12, 'Yuddha Kanda, Sarga 45, Verse 12', 'रावणेनैवमुक्तस्तु प्रहस्तो वाहिनीपतिः।
राक्षसेन्द्रमुवाचेदमसुरेन्द्रमिवोशना॥', 'rāvaṇenaivam uktas tu prahasto vāhinīpatiḥ
rākṣasendram uvācedam asurendram ivośanā', null, 6045012),
('ramayana-6-45-13', 13, 'Yuddha Kanda, Sarga 45, Verse 13', 'राजन्मन्त्रितपूर्वं नः कुशलैः सह मन्त्रिभिः।
विवादश्चापि नो वृत्तः समवेक्ष्य परस्परम्॥', 'rājan mantritapūrvaṃ naḥ kuśalaiḥ saha mantribhiḥ
vivādaś cāpi no vṛttaḥ samavekṣya parasparam', null, 6045013),
('ramayana-6-45-14', 14, 'Yuddha Kanda, Sarga 45, Verse 14', 'प्रदानेन तु सीतायाः श्रेयो व्यवसितं मया।
अप्रदाने पुनर्युद्धं दृष्टमेतत्तथैव नः॥', 'pradānena tu sītāyāḥ śreyo vyavasitaṃ mayā
apradāne punar yuddhaṃ dṛṣṭam etat tathaiva naḥ', null, 6045014),
('ramayana-6-45-15', 15, 'Yuddha Kanda, Sarga 45, Verse 15', 'सोऽहं दानैश्च मानैश्च सततं पूजितस्त्वया।
सान्त्वैश्च विविधैः काले किं न कुर्यां प्रियं तव॥', 'so ''haṃ dānaiś ca mānaiś ca satataṃ pūjitas tvayā
sāntvaiś ca vividhaiḥ kāle kiṃ na kuryāṃ priyaṃ tava', null, 6045015),
('ramayana-6-45-16', 16, 'Yuddha Kanda, Sarga 45, Verse 16', 'न हि मे जीवितं रक्ष्यं पुत्रदारधनानि वा।
त्वं पश्य मां जुहूषन्तं त्वदर्थे जीवितं युधि॥', 'na hi me jīvitaṃ rakṣyaṃ putradāradhanāni vā
tvaṃ paśya māṃ juhūṣantaṃ tvadarthe jīvitaṃ yudhi', null, 6045016),
('ramayana-6-45-17', 17, 'Yuddha Kanda, Sarga 45, Verse 17', 'एवमुक्त्वा तु भर्तारं रावणं वाहिनीपतिः।
समानयत मे शीघ्रं राक्षसानां महद्बलम्॥', 'evam uktvā tu bhartāraṃ rāvaṇaṃ vāhinīpatiḥ
samānayata me śīghraṃ rākṣasānāṃ mahad balam', null, 6045017),
('ramayana-6-45-18', 18, 'Yuddha Kanda, Sarga 45, Verse 18', 'मद्बाणाशनिवेगेन हतानां तु रणाजिरे।
अद्य तृप्यन्तु मांसेन पक्षिणः काननौकसाम्॥', 'madbāṇāśanivegena hatānāṃ tu raṇājire
adya tṛpyantu māṃsena pakṣiṇaḥ kānanaukasām', null, 6045018),
('ramayana-6-45-19', 19, 'Yuddha Kanda, Sarga 45, Verse 19', 'इत्युक्तास्ते प्रहस्तेन बलाध्यक्षाः कृतत्वराः।
बलमुद्योजयामासुस्तस्मिन्राक्षसमन्दिरे॥', 'ity uktās te prahastena balādhyakṣāḥ kṛtatvarāḥ
balam udyojayām āsus tasmin rākṣasamandire', null, 6045019),
('ramayana-6-45-20', 20, 'Yuddha Kanda, Sarga 45, Verse 20', 'सा बभूव मुहूर्तेन तिग्मनानाविधायुधैः।
लङ्का राक्षसवीरैस्तैर्गजैरिव समाकुला॥', 'sā babhūva muhūrtena tigmanānāvidhāyudhaiḥ
laṅkā rākṣasavīrais tair gajair iva samākulā', null, 6045020),
('ramayana-6-45-21', 21, 'Yuddha Kanda, Sarga 45, Verse 21', 'हुताशनं तर्पयतां ब्राह्मणांश्च नमस्यताम्।
आज्यगन्धप्रतिवहः सुरभिर्मारुतो ववौ॥', 'hutāśanaṃ tarpayatāṃ brāhmaṇāṃś ca namasyatām
ājyagandhaprativahaḥ surabhir māruto vavau', null, 6045021),
('ramayana-6-45-22', 22, 'Yuddha Kanda, Sarga 45, Verse 22', 'स्रजश्च विविधाकारा जगृहुस्त्वभिमन्त्रिताः।
संग्रामसज्जाः संहृष्टा धारयन्राक्षसास्तदा॥', 'srajaś ca vividhākārā jagṛhus tv abhimantritāḥ
saṃgrāmasajjāḥ saṃhṛṣṭā dhārayan rākṣasās tadā', null, 6045022),
('ramayana-6-45-23', 23, 'Yuddha Kanda, Sarga 45, Verse 23', 'सधनुष्काः कवचिनो वेगादाप्लुत्य राक्षसाः।
रावणं प्रेक्ष्य राजानं प्रहस्तं पर्यवारयन्॥', 'sadhanuṣkāḥ kavacino vegād āplutya rākṣasāḥ
rāvaṇaṃ prekṣya rājānaṃ prahastaṃ paryavārayan', null, 6045023),
('ramayana-6-45-24', 24, 'Yuddha Kanda, Sarga 45, Verse 24', 'अथामन्त्र्य च राजानं भेरीमाहत्य भैरवाम्।
आरुरोह रथं दिव्यं प्रहस्तः सज्जकल्पितम्॥', 'athāmantrya ca rājānaṃ bherīm āhatya bhairavām
āruroha rathaṃ divyaṃ prahastaḥ sajjakalpitam', null, 6045024),
('ramayana-6-45-25', 25, 'Yuddha Kanda, Sarga 45, Verse 25', 'हयैर्महाजवैर्युक्तं सम्यक्सूतसुसंयुतम्।
महाजलदनिर्घोषं साक्षाच्चन्द्रार्कभास्वरम्॥', 'hayair mahājavair yuktaṃ samyak sūtasusaṃyutam
mahājaladanirghoṣaṃ sākṣāc candrārkabhāsvaram', null, 6045025),
('ramayana-6-45-26', 26, 'Yuddha Kanda, Sarga 45, Verse 26', 'उरगध्वजदुर्धर्षं सुवरूथं स्वपस्करम्।
सुवर्णजालसंयुक्तं प्रहसन्तमिव श्रिया॥', 'uragadhvajadurdharṣaṃ suvarūthaṃ svapaskaram
suvarṇajālasaṃyuktaṃ prahasantam iva śriyā', null, 6045026),
('ramayana-6-45-27', 27, 'Yuddha Kanda, Sarga 45, Verse 27', 'ततस्तं रथमास्थाय रावणार्पितशासनः।
लङ्काया निर्ययौ तूर्णं बलेन महता वृतः॥', 'tatas taṃ ratham āsthāya rāvaṇārpitaśāsanaḥ
laṅkāyā niryayau tūrṇaṃ balena mahatā vṛtaḥ', null, 6045027),
('ramayana-6-45-28', 28, 'Yuddha Kanda, Sarga 45, Verse 28', 'ततो दुंदुभिनिर्घोषः पर्जन्यनिनदोपमः।
शुश्रुवे शङ्खशब्दश्च प्रयाते वाहिनीपतौ॥', 'tato duṃdubhinirghoṣaḥ parjanyaninadopamaḥ
śuśruve śaṅkhaśabdaś ca prayāte vāhinīpatau', null, 6045028),
('ramayana-6-45-29', 29, 'Yuddha Kanda, Sarga 45, Verse 29', 'निनदन्तः स्वरान्घोरान्राक्षसा जग्मुरग्रतः।
भीमरूपा महाकायाः प्रहस्तस्य पुरःसराः॥', 'ninadantaḥ svarān ghorān rākṣasā jagmur agrataḥ
bhīmarūpā mahākāyāḥ prahastasya puraḥsarāḥ', null, 6045029),
('ramayana-6-45-30', 30, 'Yuddha Kanda, Sarga 45, Verse 30', 'व्यूढेनैव सुघोरेण पूर्वद्वारात्स निर्ययौ।
गजयूथनिकाशेन बलेन महता वृतः॥', 'vyūḍhenaiva sughoreṇa pūrvadvārāt sa niryayau
gajayūthanikāśena balena mahatā vṛtaḥ', null, 6045030),
('ramayana-6-45-31', 31, 'Yuddha Kanda, Sarga 45, Verse 31', 'सागरप्रतिमौघेन वृतस्तेन बलेन सः।
प्रहस्तो निर्ययौ तूर्णं क्रुद्धः कालान्तकोपमः॥', 'sāgarapratimaughena vṛtas tena balena saḥ
prahasto niryayau tūrṇaṃ kruddhaḥ kālāntakopamaḥ', null, 6045031),
('ramayana-6-45-32', 32, 'Yuddha Kanda, Sarga 45, Verse 32', 'तस्य निर्याण घोषेण राक्षसानां च नर्दताम्।
लङ्कायां सर्वभूतानि विनेदुर्विकृतैः स्वरैः॥', 'tasya niryāṇa ghoṣeṇa rākṣasānāṃ ca nardatām
laṅkāyāṃ sarvabhūtāni vinedur vikṛtaiḥ svaraiḥ', null, 6045032),
('ramayana-6-45-33', 33, 'Yuddha Kanda, Sarga 45, Verse 33', 'व्यभ्रमाकाशमाविश्य मांसशोणितभोजनाः।
मण्डलान्यपसव्यानि खगाश्चक्रू रथं प्रति॥', 'vyabhram ākāśam āviśya māṃsaśoṇitabhojanāḥ
maṇḍalāny apasavyāni khagāś cakrū rathaṃ prati', null, 6045033),
('ramayana-6-45-34', 34, 'Yuddha Kanda, Sarga 45, Verse 34', 'वमन्त्यः पावकज्वालाः शिवा घोरा ववाशिरे॥', 'vamantyaḥ pāvakajvālāḥ śivā ghorā vavāśire', null, 6045034),
('ramayana-6-45-35', 35, 'Yuddha Kanda, Sarga 45, Verse 35', 'अन्तरिक्षात्पपातोल्का वायुश्च परुषो ववौ।
अन्योन्यमभिसंरब्धा ग्रहाश्च न चकाशिरे॥', 'antarikṣāt papātolkā vāyuś ca paruṣo vavau
anyonyam abhisaṃrabdhā grahāś ca na cakāśire', null, 6045035),
('ramayana-6-45-36', 36, 'Yuddha Kanda, Sarga 45, Verse 36', 'ववर्षू रुधिरं चास्य सिषिचुश्च पुरःसरान्।
केतुमूर्धनि गृध्रोऽस्य विलीनो दक्षिणामुखः॥', 'vavarṣū rudhiraṃ cāsya siṣicuś ca puraḥsarān
ketumūrdhani gṛdhro ''sya vilīno dakṣiṇāmukhaḥ', null, 6045036),
('ramayana-6-45-37', 37, 'Yuddha Kanda, Sarga 45, Verse 37', 'सारथेर्बहुशश्चास्य संग्राममवगाहतः।
प्रतोदो न्यपतद्धस्तात्सूतस्य हयसादिनः॥', 'sārather bahuśaś cāsya saṃgrāmam avagāhataḥ
pratodo nyapatad dhastāt sūtasya hayasādinaḥ', null, 6045037),
('ramayana-6-45-38', 38, 'Yuddha Kanda, Sarga 45, Verse 38', 'निर्याण श्रीश्च यास्यासीद्भास्वरा च सुदुर्लभा।
सा ननाश मुहूर्तेन समे च स्खलिता हयाः॥', 'niryāṇa śrīś ca yāsyāsīd bhāsvarā ca sudurlabhā
sā nanāśa muhūrtena same ca skhalitā hayāḥ', null, 6045038),
('ramayana-6-45-39', 39, 'Yuddha Kanda, Sarga 45, Verse 39', 'प्रहस्तं त्वभिनिर्यान्तं प्रख्यात बलपौरुषम्।
युधि नानाप्रहरणा कपिसेनाभ्यवर्तत॥', 'prahastaṃ tv abhiniryāntaṃ prakhyāta balapauruṣam
yudhi nānāpraharaṇā kapisenābhyavartata', null, 6045039),
('ramayana-6-45-40', 40, 'Yuddha Kanda, Sarga 45, Verse 40', 'अथ घोषः सुतुमुलो हरीणां समजायत।
वृक्षानारुजतां चैव गुर्वीश्चागृह्णतां शिलाः॥', 'atha ghoṣaḥ sutumulo harīṇāṃ samajāyata
vṛkṣān ārujatāṃ caiva gurvīś cāgṛhṇatāṃ śilāḥ', null, 6045040),
('ramayana-6-45-41', 41, 'Yuddha Kanda, Sarga 45, Verse 41', 'उभे प्रमुदिते सैन्ये रक्षोगणवनौकसाम्।
वेगितानां समर्थानामन्योन्यवधकाङ्क्षिणाम्।
परस्परं चाह्वयतां निनादः श्रूयते महान्॥', 'ubhe pramudite sainye rakṣogaṇavanaukasām
vegitānāṃ samarthānām anyonyavadhakāṅkṣiṇām
parasparaṃ cāhvayatāṃ ninādaḥ śrūyate mahān', null, 6045041),
('ramayana-6-45-42', 42, 'Yuddha Kanda, Sarga 45, Verse 42', 'ततः प्रहस्तः कपिराजवाहिनीमभिप्रतस्थे विजयाय दुर्मतिः।
विवृद्धवेगां च विवेश तां चमूं यथा मुमूर्षुः शलभो विभावसुम्॥', 'tataḥ prahastaḥ kapirājavāhinīm abhipratasthe vijayāya durmatiḥ
vivṛddhavegāṃ ca viveśa tāṃ camūṃ yathā mumūrṣuḥ śalabho vibhāvasum', null, 6045042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 46 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-46-1', 1, 'Yuddha Kanda, Sarga 46, Verse 1', 'ततः प्रहस्तं निर्यान्तं भीमं भीमपराक्रमम्।
गर्जन्तं सुमहाकायं राक्षसैरभिसंवृतम्॥', 'tataḥ prahastaṃ niryāntaṃ bhīmaṃ bhīmaparākramam
garjantaṃ sumahākāyaṃ rākṣasair abhisaṃvṛtam', null, 6046001),
('ramayana-6-46-2', 2, 'Yuddha Kanda, Sarga 46, Verse 2', 'ददर्श महती सेना वानराणां बलीयसाम्।
अतिसंजातरोषाणां प्रहस्तमभिगर्जताम्॥', 'dadarśa mahatī senā vānarāṇāṃ balīyasām
atisaṃjātaroṣāṇāṃ prahastam abhigarjatām', null, 6046002),
('ramayana-6-46-3', 3, 'Yuddha Kanda, Sarga 46, Verse 3', 'खड्गशक्त्यष्टिबाणाश्च शूलानि मुसलानि च।
गदाश्च परिघाः प्रासा विविधाश्च परश्वधाः॥', 'khaḍgaśaktyaṣṭibāṇāś ca śūlāni musalāni ca
gadāś ca parighāḥ prāsā vividhāś ca paraśvadhāḥ', null, 6046003),
('ramayana-6-46-4', 4, 'Yuddha Kanda, Sarga 46, Verse 4', 'धनूंषि च विचित्राणि राक्षसानां जयैषिणाम्।
प्रगृहीतान्यशोभन्त वानरानभिधावताम्॥', 'dhanūṃṣi ca vicitrāṇi rākṣasānāṃ jayaiṣiṇām
pragṛhītāny aśobhanta vānarān abhidhāvatām', null, 6046004),
('ramayana-6-46-5', 5, 'Yuddha Kanda, Sarga 46, Verse 5', 'जगृहुः पादपांश्चापि पुष्पितान्वानरर्षभाः।
शिलाश्च विपुला दीर्घा योद्धुकामाः प्लवंगमाः॥', 'jagṛhuḥ pādapāṃś cāpi puṣpitān vānararṣabhāḥ
śilāś ca vipulā dīrghā yoddhukāmāḥ plavaṃgamāḥ', null, 6046005),
('ramayana-6-46-6', 6, 'Yuddha Kanda, Sarga 46, Verse 6', 'तेषामन्योन्यमासाद्य संग्रामः सुमहानभूत्।
बहूनामश्मवृष्टिं च शरवृष्टिं च वर्षताम्॥', 'teṣām anyonyam āsādya saṃgrāmaḥ sumahān abhūt
bahūnām aśmavṛṣṭiṃ ca śaravṛṣṭiṃ ca varṣatām', null, 6046006),
('ramayana-6-46-7', 7, 'Yuddha Kanda, Sarga 46, Verse 7', 'बहवो राक्षसा युद्धे बहून्वानरयूथपान्।
वानरा राक्षसांश्चापि निजघ्नुर्बहवो बहून्॥', 'bahavo rākṣasā yuddhe bahūn vānarayūthapān
vānarā rākṣasāṃś cāpi nijaghnur bahavo bahūn', null, 6046007),
('ramayana-6-46-8', 8, 'Yuddha Kanda, Sarga 46, Verse 8', 'शूलैः प्रमथिताः के चित्के चित्तु परमायुधैः।
परिघैराहताः के चित्के चिच्छिन्नाः परश्वधैः॥', 'śūlaiḥ pramathitāḥ ke cit ke cit tu paramāyudhaiḥ
parighair āhatāḥ ke cit ke cic chinnāḥ paraśvadhaiḥ', null, 6046008),
('ramayana-6-46-9', 9, 'Yuddha Kanda, Sarga 46, Verse 9', 'निरुच्छ्वासाः पुनः के चित्पतिता धरणीतले।
विभिन्नहृदयाः के चिदिषुसंतानसंदिताः॥', 'nirucchvāsāḥ punaḥ ke cit patitā dharaṇītale
vibhinnahṛdayāḥ ke cid iṣusaṃtānasaṃditāḥ', null, 6046009),
('ramayana-6-46-10', 10, 'Yuddha Kanda, Sarga 46, Verse 10', 'के चिद्द्विधाकृताः खड्गैः स्फुरन्तः पतिता भुवि।
वानरा राक्षसैः शूलैः पार्श्वतश्च विदारिताः॥', 'ke cid dvidhākṛtāḥ khaḍgaiḥ sphurantaḥ patitā bhuvi
vānarā rākṣasaiḥ śūlaiḥ pārśvataś ca vidāritāḥ', null, 6046010),
('ramayana-6-46-11', 11, 'Yuddha Kanda, Sarga 46, Verse 11', 'वानरैश्चापि संक्रुद्धै राक्षसौघाः समन्ततः।
पादपैर्गिरिशृङ्गैश्च संपिष्टा वसुधातले॥', 'vānaraiś cāpi saṃkruddhai rākṣasaughāḥ samantataḥ
pādapair giriśṛṅgaiś ca saṃpiṣṭā vasudhātale', null, 6046011),
('ramayana-6-46-12', 12, 'Yuddha Kanda, Sarga 46, Verse 12', 'वज्रस्पर्शतलैर्हस्तैर्मुष्टिभिश्च हता भृशम्।
वेमुः शोणितमास्येभ्यो विशीर्णदशनेक्षणः॥', 'vajrasparśatalair hastair muṣṭibhiś ca hatā bhṛśam
vemuḥ śoṇitam āsyebhyo viśīrṇadaśanekṣaṇaḥ', null, 6046012),
('ramayana-6-46-13', 13, 'Yuddha Kanda, Sarga 46, Verse 13', 'आर्तस्वरं च स्वनतां सिंहनादं च नर्दताम्।
बभूव तुमुलः शब्दो हरीणां रक्षसां युधि॥', 'ārtasvaraṃ ca svanatāṃ siṃhanādaṃ ca nardatām
babhūva tumulaḥ śabdo harīṇāṃ rakṣasāṃ yudhi', null, 6046013),
('ramayana-6-46-14', 14, 'Yuddha Kanda, Sarga 46, Verse 14', 'वानरा राक्षसाः क्रुद्धा वीरमार्गमनुव्रताः।
विवृत्तनयनाः क्रूराश्चक्रुः कर्माण्यभीतवत्॥', 'vānarā rākṣasāḥ kruddhā vīramārgam anuvratāḥ
vivṛttanayanāḥ krūrāś cakruḥ karmāṇy abhītavat', null, 6046014),
('ramayana-6-46-15', 15, 'Yuddha Kanda, Sarga 46, Verse 15', 'नरान्तकः कुम्भहनुर्महानादः समुन्नतः।
एते प्रहस्तसचिवाः सर्वे जघ्नुर्वनौकसः॥', 'narāntakaḥ kumbhahanur mahānādaḥ samunnataḥ
ete prahastasacivāḥ sarve jaghnur vanaukasaḥ', null, 6046015),
('ramayana-6-46-16', 16, 'Yuddha Kanda, Sarga 46, Verse 16', 'तेषामापततां शीघ्रं निघ्नतां चापि वानरान्।
द्विविदो गिरिशृङ्गेण जघानैकं नरान्तकम्॥', 'teṣām āpatatāṃ śīghraṃ nighnatāṃ cāpi vānarān
dvivido giriśṛṅgeṇa jaghānaikaṃ narāntakam', null, 6046016),
('ramayana-6-46-17', 17, 'Yuddha Kanda, Sarga 46, Verse 17', 'दुर्मुखः पुनरुत्पाट्य कपिः स विपुलद्रुमम्।
राक्षसं क्षिप्रहस्तस्तु समुन्नतमपोथयत्॥', 'durmukhaḥ punar utpāṭya kapiḥ sa vipuladrumam
rākṣasaṃ kṣiprahastas tu samunnatam apothayat', null, 6046017),
('ramayana-6-46-18', 18, 'Yuddha Kanda, Sarga 46, Verse 18', 'जाम्बवांस्तु सुसंक्रुद्धः प्रगृह्य महतीं शिलाम्।
पातयामास तेजस्वी महानादस्य वक्षसि॥', 'jāmbavāṃs tu susaṃkruddhaḥ pragṛhya mahatīṃ śilām
pātayām āsa tejasvī mahānādasya vakṣasi', null, 6046018),
('ramayana-6-46-19', 19, 'Yuddha Kanda, Sarga 46, Verse 19', 'अथ कुम्भहनुस्तत्र तारेणासाद्य वीर्यवान्।
वृक्षेणाभिहतो मूर्ध्नि प्राणांस्तत्याज राक्षसः॥', 'atha kumbhahanus tatra tāreṇāsādya vīryavān
vṛkṣeṇābhihato mūrdhni prāṇāṃs tatyāja rākṣasaḥ', null, 6046019),
('ramayana-6-46-20', 20, 'Yuddha Kanda, Sarga 46, Verse 20', 'अमृष्यमाणस्तत्कर्म प्रहस्तो रथमास्थितः।
चकार कदनं घोरं धनुष्पाणिर्वनौकसाम्॥', 'amṛṣyamāṇas tat karma prahasto ratham āsthitaḥ
cakāra kadanaṃ ghoraṃ dhanuṣpāṇir vanaukasām', null, 6046020),
('ramayana-6-46-21', 21, 'Yuddha Kanda, Sarga 46, Verse 21', 'आवर्त इव संजज्ञे उभयोः सेनयोस्तदा।
क्षुभितस्याप्रमेयस्य सागरस्येव निस्वनः॥', 'āvarta iva saṃjajñe ubhayoḥ senayos tadā
kṣubhitasyāprameyasya sāgarasyeva nisvanaḥ', null, 6046021),
('ramayana-6-46-22', 22, 'Yuddha Kanda, Sarga 46, Verse 22', 'महता हि शरौघेण प्रहस्तो युद्धकोविदः।
अर्दयामास संक्रुद्धो वानरान्परमाहवे॥', 'mahatā hi śaraugheṇa prahasto yuddhakovidaḥ
ardayām āsa saṃkruddho vānarān paramāhave', null, 6046022),
('ramayana-6-46-23', 23, 'Yuddha Kanda, Sarga 46, Verse 23', 'वानराणां शरीरैस्तु राक्षसानां च मेदिनी।
बभूव निचिता घोरा पतितैरिव पर्वतैः॥', 'vānarāṇāṃ śarīrais tu rākṣasānāṃ ca medinī
babhūva nicitā ghorā patitair iva parvataiḥ', null, 6046023),
('ramayana-6-46-24', 24, 'Yuddha Kanda, Sarga 46, Verse 24', 'सा महीरुधिरौघेण प्रच्छन्ना संप्रकाशते।
संछन्ना माधवे मासि पलाशैरिव पुष्पितैः॥', 'sā mahīrudhiraugheṇa pracchannā saṃprakāśate
saṃchannā mādhave māsi palāśair iva puṣpitaiḥ', null, 6046024),
('ramayana-6-46-25', 25, 'Yuddha Kanda, Sarga 46, Verse 25', 'हतवीरौघवप्रां तु भग्नायुधमहाद्रुमाम्।
शोणितौघमहातोयां यमसागरगामिनीम्॥', 'hatavīraughavaprāṃ tu bhagnāyudhamahādrumām
śoṇitaughamahātoyāṃ yamasāgaragāminīm', null, 6046025),
('ramayana-6-46-26', 26, 'Yuddha Kanda, Sarga 46, Verse 26', 'यकृत्प्लीहमहापङ्कां विनिकीर्णान्त्रशैवलाम्।
भिन्नकायशिरोमीनामङ्गावयवशाड्वलाम्॥', 'yakṛtplīhamahāpaṅkāṃ vinikīrṇāntraśaivalām
bhinnakāyaśiromīnām aṅgāvayavaśāḍvalām', null, 6046026),
('ramayana-6-46-27', 27, 'Yuddha Kanda, Sarga 46, Verse 27', 'गृध्रहंसगणाकीर्णां कङ्कसारससेविताम्।
मेधःफेनसमाकीर्णामार्तस्तनितनिस्वनाम्॥', 'gṛdhrahaṃsagaṇākīrṇāṃ kaṅkasārasasevitām
medhaḥphenasamākīrṇām ārtastanitanisvanām', null, 6046027),
('ramayana-6-46-28', 28, 'Yuddha Kanda, Sarga 46, Verse 28', 'तां कापुरुषदुस्तारां युद्धभूमिमयीं नदीम्।
नदीमिव घनापाये हंससारससेविताम्॥', 'tāṃ kāpuruṣadustārāṃ yuddhabhūmimayīṃ nadīm
nadīm iva ghanāpāye haṃsasārasasevitām', null, 6046028),
('ramayana-6-46-29', 29, 'Yuddha Kanda, Sarga 46, Verse 29', 'राक्षसाः कपिमुख्याश्च तेरुस्तां दुस्तरां नदीम्।
यथा पद्मरजोध्वस्तां नलिनीं गजयूथपाः॥', 'rākṣasāḥ kapimukhyāś ca terus tāṃ dustarāṃ nadīm
yathā padmarajodhvastāṃ nalinīṃ gajayūthapāḥ', null, 6046029),
('ramayana-6-46-30', 30, 'Yuddha Kanda, Sarga 46, Verse 30', 'ततः सृजन्तं बाणौघान्प्रहस्तं स्यन्दने स्थितम्।
ददर्श तरसा नीलो विनिघ्नन्तं प्लवंगमान्॥', 'tataḥ sṛjantaṃ bāṇaughān prahastaṃ syandane sthitam
dadarśa tarasā nīlo vinighnantaṃ plavaṃgamān', null, 6046030),
('ramayana-6-46-31', 31, 'Yuddha Kanda, Sarga 46, Verse 31', 'स तं परमदुर्धर्षमापतन्तं महाकपिः।
प्रहस्तं ताडयामास वृक्षमुत्पाट्य वीर्यवान्॥', 'sa taṃ paramadurdharṣam āpatantaṃ mahākapiḥ
prahastaṃ tāḍayām āsa vṛkṣam utpāṭya vīryavān', null, 6046031),
('ramayana-6-46-32', 32, 'Yuddha Kanda, Sarga 46, Verse 32', 'स तेनाभिहतः क्रुद्धो नदन्राक्षसपुंगवः।
ववर्ष शरवर्षाणि प्लवगानां चमूपतौ॥', 'sa tenābhihataḥ kruddho nadan rākṣasapuṃgavaḥ
vavarṣa śaravarṣāṇi plavagānāṃ camūpatau', null, 6046032),
('ramayana-6-46-33', 33, 'Yuddha Kanda, Sarga 46, Verse 33', 'अपारयन्वारयितुं प्रत्यगृह्णान्निमीलितः।
यथैव गोवृषो वर्षं शारदं शीघ्रमागतम्॥', 'apārayan vārayituṃ pratyagṛhṇān nimīlitaḥ
yathaiva govṛṣo varṣaṃ śāradaṃ śīghram āgatam', null, 6046033),
('ramayana-6-46-34', 34, 'Yuddha Kanda, Sarga 46, Verse 34', 'एवमेव प्रहस्तस्य शरवर्षं दुरासदम्।
निमीलिताक्षः सहसा नीलः सेहे सुदारुणम्॥', 'evam eva prahastasya śaravarṣaṃ durāsadam
nimīlitākṣaḥ sahasā nīlaḥ sehe sudāruṇam', null, 6046034),
('ramayana-6-46-35', 35, 'Yuddha Kanda, Sarga 46, Verse 35', 'रोषितः शरवर्षेण सालेन महता महान्।
प्रजघान हयान्नीलः प्रहस्तस्य मनोजवान्॥', 'roṣitaḥ śaravarṣeṇa sālena mahatā mahān
prajaghāna hayān nīlaḥ prahastasya manojavān', null, 6046035),
('ramayana-6-46-36', 36, 'Yuddha Kanda, Sarga 46, Verse 36', 'विधनुस्तु कृतस्तेन प्रहस्तो वाहिनीपतिः।
प्रगृह्य मुसलं घोरं स्यन्दनादवपुप्लुवे॥', 'vidhanus tu kṛtas tena prahasto vāhinīpatiḥ
pragṛhya musalaṃ ghoraṃ syandanād avapupluve', null, 6046036),
('ramayana-6-46-37', 37, 'Yuddha Kanda, Sarga 46, Verse 37', 'तावुभौ वाहिनीमुख्यौ जातरोषौ तरस्विनौ।
स्थितौ क्षतजदिग्धाङ्गौ प्रभिन्नाविव कुञ्जरौ॥', 'tāv ubhau vāhinīmukhyau jātaroṣau tarasvinau
sthitau kṣatajadigdhāṅgau prabhinnāv iva kuñjarau', null, 6046037),
('ramayana-6-46-38', 38, 'Yuddha Kanda, Sarga 46, Verse 38', 'उल्लिखन्तौ सुतीक्ष्णाभिर्दंष्ट्राभिरितरेतरम्।
सिंहशार्दूलसदृशौ सिंहशार्दूलचेष्टितौ॥', 'ullikhantau sutīkṣṇābhir daṃṣṭrābhir itaretaram
siṃhaśārdūlasadṛśau siṃhaśārdūlaceṣṭitau', null, 6046038),
('ramayana-6-46-39', 39, 'Yuddha Kanda, Sarga 46, Verse 39', 'विक्रान्तविजयौ वीरौ समरेष्वनिवर्तिनौ।
काङ्क्षमाणौ यशः प्राप्तुं वृत्रवासवयोः समौ॥', 'vikrāntavijayau vīrau samareṣv anivartinau
kāṅkṣamāṇau yaśaḥ prāptuṃ vṛtravāsavayoḥ samau', null, 6046039),
('ramayana-6-46-40', 40, 'Yuddha Kanda, Sarga 46, Verse 40', 'आजघान तदा नीलं ललाटे मुसलेन सः।
प्रहस्तः परमायस्तस्तस्य सुस्राव शोणितम्॥', 'ājaghāna tadā nīlaṃ lalāṭe musalena saḥ
prahastaḥ paramāyastas tasya susrāva śoṇitam', null, 6046040),
('ramayana-6-46-41', 41, 'Yuddha Kanda, Sarga 46, Verse 41', 'ततः शोणितदिग्धाङ्गः प्रगृह्य सुमहातरुम्।
प्रहस्तस्योरसि क्रुद्धो विससर्ज महाकपिः॥', 'tataḥ śoṇitadigdhāṅgaḥ pragṛhya sumahātarum
prahastasyorasi kruddho visasarja mahākapiḥ', null, 6046041),
('ramayana-6-46-42', 42, 'Yuddha Kanda, Sarga 46, Verse 42', 'तमचिन्त्यप्रहारं स प्रगृह्य मुसलं महत्।
अभिदुद्राव बलिनं बली नीलं प्लवंगमम्॥', 'tam acintyaprahāraṃ sa pragṛhya musalaṃ mahat
abhidudrāva balinaṃ balī nīlaṃ plavaṃgamam', null, 6046042),
('ramayana-6-46-43', 43, 'Yuddha Kanda, Sarga 46, Verse 43', 'तमुग्रवेगं संरब्धमापतन्तं महाकपिः।
ततः संप्रेक्ष्य जग्राह महावेगो महाशिलाम्॥', 'tam ugravegaṃ saṃrabdham āpatantaṃ mahākapiḥ
tataḥ saṃprekṣya jagrāha mahāvego mahāśilām', null, 6046043),
('ramayana-6-46-44', 44, 'Yuddha Kanda, Sarga 46, Verse 44', 'तस्य युद्धाभिकामस्य मृधे मुसलयोधिनः।
प्रहस्तस्य शिलां नीलो मूर्ध्नि तूर्णमपातयत्॥', 'tasya yuddhābhikāmasya mṛdhe musalayodhinaḥ
prahastasya śilāṃ nīlo mūrdhni tūrṇam apātayat', null, 6046044),
('ramayana-6-46-45', 45, 'Yuddha Kanda, Sarga 46, Verse 45', 'सा तेन कपिमुख्येन विमुक्ता महती शिला।
बिभेद बहुधा घोरा प्रहस्तस्य शिरस्तदा॥', 'sā tena kapimukhyena vimuktā mahatī śilā
bibheda bahudhā ghorā prahastasya śiras tadā', null, 6046045),
('ramayana-6-46-46', 46, 'Yuddha Kanda, Sarga 46, Verse 46', 'स गतासुर्गतश्रीको गतसत्त्वो गतेन्द्रियः।
पपात सहसा भूमौ छिन्नमूल इव द्रुमः॥', 'sa gatāsur gataśrīko gatasattvo gatendriyaḥ
papāta sahasā bhūmau chinnamūla iva drumaḥ', null, 6046046),
('ramayana-6-46-47', 47, 'Yuddha Kanda, Sarga 46, Verse 47', 'विभिन्नशिरसस्तस्य बहु सुस्रावशोणितम्।
शरीरादपि सुस्राव गिरेः प्रस्रवणं यथा॥', 'vibhinnaśirasas tasya bahu susrāvaśoṇitam
śarīrād api susrāva gireḥ prasravaṇaṃ yathā', null, 6046047),
('ramayana-6-46-48', 48, 'Yuddha Kanda, Sarga 46, Verse 48', 'हते प्रहस्ते नीलेन तदकम्प्यं महद्बलम्।
रक्षसामप्रहृष्टानां लङ्कामभिजगाम ह॥', 'hate prahaste nīlena tad akampyaṃ mahad balam
rakṣasām aprahṛṣṭānāṃ laṅkām abhijagāma ha', null, 6046048),
('ramayana-6-46-49', 49, 'Yuddha Kanda, Sarga 46, Verse 49', 'न शेकुः समवस्थातुं निहते वाहिनीपतौ।
सेतुबन्धं समासाद्य विशीर्णं सलिलं यथा॥', 'na śekuḥ samavasthātuṃ nihate vāhinīpatau
setubandhaṃ samāsādya viśīrṇaṃ salilaṃ yathā', null, 6046049),
('ramayana-6-46-50', 50, 'Yuddha Kanda, Sarga 46, Verse 50', 'हते तस्मिंश्चमूमुख्ये राक्षसस्ते निरुद्यमाः।
रक्षःपतिगृहं गत्वा ध्यानमूकत्वमागताः॥', 'hate tasmiṃś camūmukhye rākṣasas te nirudyamāḥ
rakṣaḥpatigṛhaṃ gatvā dhyānamūkatvam āgatāḥ', null, 6046050),
('ramayana-6-46-51', 51, 'Yuddha Kanda, Sarga 46, Verse 51', 'ततस्तु नीलो विजयी महाबलः प्रशस्यमानः स्वकृतेन कर्मणा।
समेत्य रामेण सलक्ष्मणेन प्रहृष्टरूपस्तु बभूव यूथपः॥', 'tatas tu nīlo vijayī mahābalaḥ praśasyamānaḥ svakṛtena karmaṇā
sametya rāmeṇa salakṣmaṇena prahṛṣṭarūpas tu babhūva yūthapaḥ', null, 6046051)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 47 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-47-1', 1, 'Yuddha Kanda, Sarga 47, Verse 1', 'तस्मिन्हते राक्षससैन्यपाले प्लवंगमानामृषभेण युद्धे।
भीमायुधं सागरतुल्यवेगं प्रदुद्रुवे राक्षसराजसैन्यम्॥', 'tasmin hate rākṣasasainyapāle plavaṃgamānām ṛṣabheṇa yuddhe
bhīmāyudhaṃ sāgaratulyavegaṃ pradudruve rākṣasarājasainyam', null, 6047001),
('ramayana-6-47-2', 2, 'Yuddha Kanda, Sarga 47, Verse 2', 'गत्वा तु रक्षोऽधिपतेः शशंसुः सेनापतिं पावकसूनुशस्तम्।
तच्चापि तेषां वचनं निशम्य रक्षोऽधिपः क्रोधवशं जगाम॥', 'gatvā tu rakṣo''dhipateḥ śaśaṃsuḥ senāpatiṃ pāvakasūnuśastam
tac cāpi teṣāṃ vacanaṃ niśamya rakṣo''dhipaḥ krodhavaśaṃ jagāma', null, 6047002),
('ramayana-6-47-3', 3, 'Yuddha Kanda, Sarga 47, Verse 3', 'संख्ये प्रहस्तं निहतं निशम्य शोकार्दितः क्रोधपरीतचेताः।
उवाच तान्नैरृतयोधमुख्यानिन्द्रो यथा चामरयोधमुख्यान्॥', 'saṃkhye prahastaṃ nihataṃ niśamya śokārditaḥ krodhaparītacetāḥ
uvāca tān nairṛtayodhamukhyān indro yathā cāmarayodhamukhyān', null, 6047003),
('ramayana-6-47-4', 4, 'Yuddha Kanda, Sarga 47, Verse 4', 'नावज्ञा रिपवे कार्या यैरिन्द्रबलसूदनः।
सूदितः सैन्यपालो मे सानुयात्रः सकुञ्जरः॥', 'nāvajñā ripave kāryā yair indrabalasūdanaḥ
sūditaḥ sainyapālo me sānuyātraḥ sakuñjaraḥ', null, 6047004),
('ramayana-6-47-5', 5, 'Yuddha Kanda, Sarga 47, Verse 5', 'सोऽहं रिपुविनाशाय विजयायाविचारयन्।
स्वयमेव गमिष्यामि रणशीर्षं तदद्भुतम्॥', 'so ''haṃ ripuvināśāya vijayāyāvicārayan
svayam eva gamiṣyāmi raṇaśīrṣaṃ tad adbhutam', null, 6047005),
('ramayana-6-47-6', 6, 'Yuddha Kanda, Sarga 47, Verse 6', 'अद्य तद्वानरानीकं रामं च सहलक्ष्मणम्।
निर्दहिष्यामि बाणौघैर्वनं दीप्तैरिवाग्निभिः॥', 'adya tad vānarānīkaṃ rāmaṃ ca sahalakṣmaṇam
nirdahiṣyāmi bāṇaughair vanaṃ dīptair ivāgnibhiḥ', null, 6047006),
('ramayana-6-47-7', 7, 'Yuddha Kanda, Sarga 47, Verse 7', 'स एवमुक्त्वा ज्वलनप्रकाशं रथं तुरंगोत्तमराजियुक्तम्।
प्रकाशमानं वपुषा ज्वलन्तं समारुरोहामरराजशत्रुः॥', 'sa evam uktvā jvalanaprakāśaṃ rathaṃ turaṃgottamarājiyuktam
prakāśamānaṃ vapuṣā jvalantaṃ samārurohāmararājaśatruḥ', null, 6047007),
('ramayana-6-47-8', 8, 'Yuddha Kanda, Sarga 47, Verse 8', 'स शङ्खभेरीपटह प्रणादैरास्फोटितक्ष्वेडितसिंहनादैः।
पुण्यैः स्तवैश्चाप्यभिपूज्यमानस्तदा ययौ राक्षसराजमुख्यः॥', 'sa śaṅkhabherīpaṭaha praṇādair āsphoṭitakṣveḍitasiṃhanādaiḥ
puṇyaiḥ stavaiś cāpy abhipūjyamānas tadā yayau rākṣasarājamukhyaḥ', null, 6047008),
('ramayana-6-47-9', 9, 'Yuddha Kanda, Sarga 47, Verse 9', 'स शैलजीमूतनिकाश रूपैर्मांसाशनैः पावकदीप्तनेत्रैः।
बभौ वृतो राक्षसराजमुख्यैर्भूतैर्वृतो रुद्र इवामरेशः॥', 'sa śailajīmūtanikāśa rūpair māṃsāśanaiḥ pāvakadīptanetraiḥ
babhau vṛto rākṣasarājamukhyair bhūtair vṛto rudra ivāmareśaḥ', null, 6047009),
('ramayana-6-47-10', 10, 'Yuddha Kanda, Sarga 47, Verse 10', 'ततो नगर्याः सहसा महौजा निष्क्रम्य तद्वानरसैन्यमुग्रम्।
महार्णवाभ्रस्तनितं ददर्श समुद्यतं पादपशैलहस्तम्॥', 'tato nagaryāḥ sahasā mahaujā niṣkramya tad vānarasainyam ugram
mahārṇavābhrastanitaṃ dadarśa samudyataṃ pādapaśailahastam', null, 6047010),
('ramayana-6-47-11', 11, 'Yuddha Kanda, Sarga 47, Verse 11', 'तद्राक्षसानीकमतिप्रचण्डमालोक्य रामो भुजगेन्द्रबाहुः।
विभीषणं शस्त्रभृतां वरिष्ठमुवाच सेनानुगतः पृथुश्रीः॥', 'tad rākṣasānīkam atipracaṇḍam ālokya rāmo bhujagendrabāhuḥ
vibhīṣaṇaṃ śastrabhṛtāṃ variṣṭham uvāca senānugataḥ pṛthuśrīḥ', null, 6047011),
('ramayana-6-47-12', 12, 'Yuddha Kanda, Sarga 47, Verse 12', 'नानापताकाध्वजशस्त्रजुष्टं प्रासासिशूलायुधचक्रजुष्टम्।
सैन्यं नगेन्द्रोपमनागजुष्टं कस्येदमक्षोभ्यमभीरुजुष्टम्॥', 'nānāpatākādhvajaśastrajuṣṭaṃ prāsāsiśūlāyudhacakrajuṣṭam
sainyaṃ nagendropamanāgajuṣṭaṃ kasyedam akṣobhyam abhīrujuṣṭam', null, 6047012),
('ramayana-6-47-13', 13, 'Yuddha Kanda, Sarga 47, Verse 13', 'ततस्तु रामस्य निशम्य वाक्यं विभीषणः शक्रसमानवीर्यः।
शशंस रामस्य बलप्रवेकं महात्मनां राक्षसपुंगवानाम्॥', 'tatas tu rāmasya niśamya vākyaṃ vibhīṣaṇaḥ śakrasamānavīryaḥ
śaśaṃsa rāmasya balapravekaṃ mahātmanāṃ rākṣasapuṃgavānām', null, 6047013),
('ramayana-6-47-14', 14, 'Yuddha Kanda, Sarga 47, Verse 14', 'योऽसौ गजस्कन्धगतो महात्मा नवोदितार्कोपमताम्रवक्त्रः।
प्रकम्पयन्नागशिरोऽभ्युपैति ह्यकम्पनं त्वेनमवेहि राजन्॥', 'yo ''sau gajaskandhagato mahātmā navoditārkopamatāmravaktraḥ
prakampayan nāgaśiro ''bhyupaiti hy akampanaṃ tv enam avehi rājan', null, 6047014),
('ramayana-6-47-15', 15, 'Yuddha Kanda, Sarga 47, Verse 15', 'योऽसौ रथस्थो मृगराजकेतुर्धून्वन्धनुः शक्रधनुःप्रकाशम्।
करीव भात्युग्रविवृत्तदंष्ट्रः स इन्द्रजिन्नाम वरप्रधानः॥', 'yo ''sau rathastho mṛgarājaketur dhūnvan dhanuḥ śakradhanuḥprakāśam
karīva bhāty ugravivṛttadaṃṣṭraḥ sa indrajin nāma varapradhānaḥ', null, 6047015),
('ramayana-6-47-16', 16, 'Yuddha Kanda, Sarga 47, Verse 16', 'यश्चैष विन्ध्यास्तमहेन्द्रकल्पो धन्वी रथस्थोऽतिरथोऽतिवीर्यः।
विस्फारयंश्चापमतुल्यमानं नाम्नातिकायोऽतिविवृद्धकायः॥', 'yaś caiṣa vindhyāstamahendrakalpo dhanvī rathastho ''tiratho ''tivīryaḥ
visphārayaṃś cāpam atulyamānaṃ nāmnātikāyo ''tivivṛddhakāyaḥ', null, 6047016),
('ramayana-6-47-17', 17, 'Yuddha Kanda, Sarga 47, Verse 17', 'योऽसौ नवार्कोदितताम्रचक्षुरारुह्य घण्टानिनदप्रणादम्।
गजं खरं गर्जति वै महात्मा महोदरो नाम स एष वीरः॥', 'yo ''sau navārkoditatāmracakṣur āruhya ghaṇṭāninadapraṇādam
gajaṃ kharaṃ garjati vai mahātmā mahodaro nāma sa eṣa vīraḥ', null, 6047017),
('ramayana-6-47-18', 18, 'Yuddha Kanda, Sarga 47, Verse 18', 'योऽसौ हयं काञ्चनचित्रभाण्डमारुह्य संध्याभ्रगिरिप्रकाशम्।
प्रासं समुद्यम्य मरीचिनद्धं पिशाच एषाशनितुल्यवेगः॥', 'yo ''sau hayaṃ kāñcanacitrabhāṇḍam āruhya saṃdhyābhragiriprakāśam
prāsaṃ samudyamya marīcinaddhaṃ piśāca eṣāśanitulyavegaḥ', null, 6047018),
('ramayana-6-47-19', 19, 'Yuddha Kanda, Sarga 47, Verse 19', 'यश्चैष शूलं निशितं प्रगृह्य विद्युत्प्रभं किंकरवज्रवेगम्।
वृषेन्द्रमास्थाय गिरिप्रकाशमायाति सोऽसौ त्रिशिरा यशस्वी॥', 'yaś caiṣa śūlaṃ niśitaṃ pragṛhya vidyutprabhaṃ kiṃkaravajravegam
vṛṣendram āsthāya giriprakāśam āyāti so ''sau triśirā yaśasvī', null, 6047019),
('ramayana-6-47-20', 20, 'Yuddha Kanda, Sarga 47, Verse 20', 'असौ च जीमूतनिकाश रूपः कुम्भः पृथुव्यूढसुजातवक्षाः।
समाहितः पन्नगराजकेतुर्विस्फारयन्भाति धनुर्विधून्वन्॥', 'asau ca jīmūtanikāśa rūpaḥ kumbhaḥ pṛthuvyūḍhasujātavakṣāḥ
samāhitaḥ pannagarājaketur visphārayan bhāti dhanur vidhūnvan', null, 6047020),
('ramayana-6-47-21', 21, 'Yuddha Kanda, Sarga 47, Verse 21', 'यश्चैष जाम्बूनदवज्रजुष्टं दीप्तं सधूमं परिघं प्रगृह्य।
आयाति रक्षोबलकेतुभूतः सोऽसौ निकुम्भोऽद्भुतघोरकर्मा॥', 'yaś caiṣa jāmbūnadavajrajuṣṭaṃ dīptaṃ sadhūmaṃ parighaṃ pragṛhya
āyāti rakṣobalaketubhūtaḥ so ''sau nikumbho ''dbhutaghorakarmā', null, 6047021),
('ramayana-6-47-22', 22, 'Yuddha Kanda, Sarga 47, Verse 22', 'यश्चैष चापासिशरौघजुष्टं पताकिनं पावकदीप्तरूपम्।
रथं समास्थाय विभात्युदग्रो नरान्तकोऽसौ नगशृङ्गयोधी॥', 'yaś caiṣa cāpāsiśaraughajuṣṭaṃ patākinaṃ pāvakadīptarūpam
rathaṃ samāsthāya vibhāty udagro narāntako ''sau nagaśṛṅgayodhī', null, 6047022),
('ramayana-6-47-23', 23, 'Yuddha Kanda, Sarga 47, Verse 23', 'यश्चैष नानाविधघोररूपैर्व्याघ्रोष्ट्रनागेन्द्रमृगेन्द्रवक्त्रैः।
भूतैर्वृतो भाति विवृत्तनेत्रैः सोऽसौ सुराणामपि दर्पहन्ता॥', 'yaś caiṣa nānāvidhaghorarūpair vyāghroṣṭranāgendramṛgendravaktraiḥ
bhūtair vṛto bhāti vivṛttanetraiḥ so ''sau surāṇām api darpahantā', null, 6047023),
('ramayana-6-47-24', 24, 'Yuddha Kanda, Sarga 47, Verse 24', 'यत्रैतदिन्दुप्रतिमं विभातिच्छत्त्रं सितं सूक्ष्मशलाकमग्र्यम्।
अत्रैष रक्षोऽधिपतिर्महात्मा भूतैर्वृतो रुद्र इवावभाति॥', 'yatraitad indupratimaṃ vibhātic chattraṃ sitaṃ sūkṣmaśalākam agryam
atraiṣa rakṣo''dhipatir mahātmā bhūtair vṛto rudra ivāvabhāti', null, 6047024),
('ramayana-6-47-25', 25, 'Yuddha Kanda, Sarga 47, Verse 25', 'असौ किरीटी चलकुण्डलास्यो नागेन्द्रविन्ध्योपमभीमकायः।
महेन्द्रवैवस्वतदर्पहन्ता रक्षोऽधिपः सूर्य इवावभाति॥', 'asau kirīṭī calakuṇḍalāsyo nāgendravindhyopamabhīmakāyaḥ
mahendravaivasvatadarpahantā rakṣo''dhipaḥ sūrya ivāvabhāti', null, 6047025),
('ramayana-6-47-26', 26, 'Yuddha Kanda, Sarga 47, Verse 26', 'प्रत्युवाच ततो रामो विभीषणमरिंदमम्।
अहो दीप्तो महातेजा रावणो राक्षसेश्वरः॥', 'pratyuvāca tato rāmo vibhīṣaṇam ariṃdamam
aho dīpto mahātejā rāvaṇo rākṣaseśvaraḥ', null, 6047026),
('ramayana-6-47-27', 27, 'Yuddha Kanda, Sarga 47, Verse 27', 'आदित्य इव दुष्प्रेक्ष्यो रश्मिभिर्भाति रावणः।
सुव्यक्तं लक्षये ह्यस्य रूपं तेजःसमावृतम्॥', 'āditya iva duṣprekṣyo raśmibhir bhāti rāvaṇaḥ
suvyaktaṃ lakṣaye hy asya rūpaṃ tejaḥsamāvṛtam', null, 6047027),
('ramayana-6-47-28', 28, 'Yuddha Kanda, Sarga 47, Verse 28', 'देवदानववीराणां वपुर्नैवंविधं भवेत्।
यादृशं राक्षसेन्द्रस्य वपुरेतत्प्रकाशते॥', 'devadānavavīrāṇāṃ vapur naivaṃvidhaṃ bhavet
yādṛśaṃ rākṣasendrasya vapur etat prakāśate', null, 6047028),
('ramayana-6-47-29', 29, 'Yuddha Kanda, Sarga 47, Verse 29', 'सर्वे पर्वतसंकाशाः सर्वे पर्वतयोधिनः।
सर्वे दीप्तायुधधरा योधश्चास्य महौजसः॥', 'sarve parvatasaṃkāśāḥ sarve parvatayodhinaḥ
sarve dīptāyudhadharā yodhaś cāsya mahaujasaḥ', null, 6047029),
('ramayana-6-47-30', 30, 'Yuddha Kanda, Sarga 47, Verse 30', 'भाति राक्षसराजोऽसौ प्रदीप्तैर्भीमविक्रमैः।
भूतैः परिवृतस्तीक्ष्णैर्देहवद्भिरिवान्तकः॥', 'bhāti rākṣasarājo ''sau pradīptair bhīmavikramaiḥ
bhūtaiḥ parivṛtas tīkṣṇair dehavadbhir ivāntakaḥ', null, 6047030),
('ramayana-6-47-31', 31, 'Yuddha Kanda, Sarga 47, Verse 31', 'एवमुक्त्वा ततो रामो धनुरादाय वीर्यवान्।
लक्ष्मणानुचरस्तस्थौ समुद्धृत्य शरोत्तमम्॥', 'evam uktvā tato rāmo dhanur ādāya vīryavān
lakṣmaṇānucaras tasthau samuddhṛtya śarottamam', null, 6047031),
('ramayana-6-47-32', 32, 'Yuddha Kanda, Sarga 47, Verse 32', 'ततः स रक्षोऽधिपतिर्महात्मा रक्षांसि तान्याह महाबलानि।
द्वारेषु चर्यागृहगोपुरेषु सुनिर्वृतास्तिष्ठत निर्विशङ्काः॥', 'tataḥ sa rakṣo''dhipatir mahātmā rakṣāṃsi tāny āha mahābalāni
dvāreṣu caryāgṛhagopureṣu sunirvṛtās tiṣṭhata nirviśaṅkāḥ', null, 6047032),
('ramayana-6-47-33', 33, 'Yuddha Kanda, Sarga 47, Verse 33', 'विसर्जयित्वा सहसा ततस्तान्गतेषु रक्षःसु यथानियोगम्।
व्यदारयद्वानरसागरौघं महाझषः पूर्ममिवार्णवौघम्॥', 'visarjayitvā sahasā tatas tān gateṣu rakṣaḥsu yathāniyogam
vyadārayad vānarasāgaraughaṃ mahājhaṣaḥ pūrmam ivārṇavaugham', null, 6047033),
('ramayana-6-47-34', 34, 'Yuddha Kanda, Sarga 47, Verse 34', 'तमापतन्तं सहसा समीक्ष्य दीप्तेषुचापं युधि राक्षसेन्द्रम्।
महत्समुत्पाट्य महीधराग्रं दुद्राव रक्षोऽधिपतिं हरीशः॥', 'tam āpatantaṃ sahasā samīkṣya dīpteṣucāpaṃ yudhi rākṣasendram
mahat samutpāṭya mahīdharāgraṃ dudrāva rakṣo''dhipatiṃ harīśaḥ', null, 6047034),
('ramayana-6-47-35', 35, 'Yuddha Kanda, Sarga 47, Verse 35', 'तच्छैलशृङ्गं बहुवृक्षसानुं प्रगृह्य चिक्षेप निशाचराय।
तमापतन्तं सहसा समीक्ष्य बिभेद बाणैस्तपनीयपुङ्खैः॥', 'tac chailaśṛṅgaṃ bahuvṛkṣasānuṃ pragṛhya cikṣepa niśācarāya
tam āpatantaṃ sahasā samīkṣya bibheda bāṇais tapanīyapuṅkhaiḥ', null, 6047035),
('ramayana-6-47-36', 36, 'Yuddha Kanda, Sarga 47, Verse 36', 'तस्मिन्प्रवृद्धोत्तमसानुवृक्षे शृङ्गे विकीर्णे पतिते पृथिव्याम्।
महाहिकल्पं शरमन्तकाभं समाददे राक्षसलोकनाथः॥', 'tasmin pravṛddhottamasānuvṛkṣe śṛṅge vikīrṇe patite pṛthivyām
mahāhikalpaṃ śaram antakābhaṃ samādade rākṣasalokanāthaḥ', null, 6047036),
('ramayana-6-47-37', 37, 'Yuddha Kanda, Sarga 47, Verse 37', 'स तं गृहीत्वानिलतुल्यवेगं सविस्फुलिङ्गज्वलनप्रकाशम्।
बाणं महेन्द्राशनितुल्यवेगं चिक्षेप सुग्रीववधाय रुष्टः॥', 'sa taṃ gṛhītvānilatulyavegaṃ savisphuliṅgajvalanaprakāśam
bāṇaṃ mahendrāśanitulyavegaṃ cikṣepa sugrīvavadhāya ruṣṭaḥ', null, 6047037),
('ramayana-6-47-38', 38, 'Yuddha Kanda, Sarga 47, Verse 38', 'स सायको रावणबाहुमुक्तः शक्राशनिप्रख्यवपुः शिताग्रः।
सुग्रीवमासाद्य बिभेद वेगाद्गुहेरिता क्रौचमिवोग्रशक्तिः॥', 'sa sāyako rāvaṇabāhumuktaḥ śakrāśaniprakhyavapuḥ śitāgraḥ
sugrīvam āsādya bibheda vegād guheritā kraucam ivograśaktiḥ', null, 6047038),
('ramayana-6-47-39', 39, 'Yuddha Kanda, Sarga 47, Verse 39', 'स सायकार्तो विपरीतचेताः कूजन्पृथिव्यां निपपात वीरः।
तं प्रेक्ष्य भूमौ पतितं विसंज्मं नेदुः प्रहृष्टा युधि यातुधानाः॥', 'sa sāyakārto viparītacetāḥ kūjan pṛthivyāṃ nipapāta vīraḥ
taṃ prekṣya bhūmau patitaṃ visaṃjmaṃ neduḥ prahṛṣṭā yudhi yātudhānāḥ', null, 6047039),
('ramayana-6-47-40', 40, 'Yuddha Kanda, Sarga 47, Verse 40', 'ततो गवाक्षो गवयः सुदंष्ट्रस्तथर्षभो ज्योतिमुखो नलश्च।
शैलान्समुद्यम्य विवृद्धकायाः प्रदुद्रुवुस्तं प्रति राक्षसेन्द्रम्॥', 'tato gavākṣo gavayaḥ sudaṃṣṭras tatharṣabho jyotimukho nalaś ca
śailān samudyamya vivṛddhakāyāḥ pradudruvus taṃ prati rākṣasendram', null, 6047040),
('ramayana-6-47-41', 41, 'Yuddha Kanda, Sarga 47, Verse 41', 'तेषां प्रहारान्स चकार मेघान्रक्षोऽधिपो बाणगणैः शिताग्रैः।
तान्वानरेन्द्रानपि बाणजालैर्बिभेद जाम्बूनदचित्रपुङ्खैः॥', 'teṣāṃ prahārān sa cakāra meghān rakṣo''dhipo bāṇagaṇaiḥ śitāgraiḥ
tān vānarendrān api bāṇajālair bibheda jāmbūnadacitrapuṅkhaiḥ', null, 6047041),
('ramayana-6-47-42', 42, 'Yuddha Kanda, Sarga 47, Verse 42', 'ते वानरेन्द्रास्त्रिदशारिबाणैर्भिन्ना निपेतुर्भुवि भीमरूपाः।
ततस्तु तद्वानरसैन्यमुग्रं प्रच्छादयामास स बाणजालैः॥', 'te vānarendrās tridaśāribāṇair bhinnā nipetur bhuvi bhīmarūpāḥ
tatas tu tad vānarasainyam ugraṃ pracchādayām āsa sa bāṇajālaiḥ', null, 6047042),
('ramayana-6-47-43', 43, 'Yuddha Kanda, Sarga 47, Verse 43', 'ते वध्यमानाः पतिताग्र्यवीरा नानद्यमाना भयशल्यविद्धाः।
शाखामृगा रावणसायकार्ता जग्मुः शरण्यं शरणं स्म रामम्॥', 'te vadhyamānāḥ patitāgryavīrā nānadyamānā bhayaśalyaviddhāḥ
śākhāmṛgā rāvaṇasāyakārtā jagmuḥ śaraṇyaṃ śaraṇaṃ sma rāmam', null, 6047043),
('ramayana-6-47-44', 44, 'Yuddha Kanda, Sarga 47, Verse 44', 'ततो महात्मा स धनुर्धनुष्मानादाय रामः सहरा जगाम।
तं लक्ष्मणः प्राञ्जलिरभ्युपेत्य उवाच वाक्यं परमार्थयुक्तम्॥', 'tato mahātmā sa dhanur dhanuṣmān ādāya rāmaḥ saharā jagāma
taṃ lakṣmaṇaḥ prāñjalir abhyupetya uvāca vākyaṃ paramārthayuktam', null, 6047044),
('ramayana-6-47-45', 45, 'Yuddha Kanda, Sarga 47, Verse 45', 'काममार्यः सुपर्याप्तो वधायास्य दुरात्मनः।
विधमिष्याम्यहं नीचमनुजानीहि मां विभो॥', 'kāmam āryaḥ suparyāpto vadhāyāsya durātmanaḥ
vidhamiṣyāmy ahaṃ nīcam anujānīhi māṃ vibho', null, 6047045),
('ramayana-6-47-46', 46, 'Yuddha Kanda, Sarga 47, Verse 46', 'तमब्रवीन्महातेजा रामः सत्यपराक्रमः।
गच्छ यत्नपरश्चापि भव लक्ष्मण संयुगे॥', 'tam abravīn mahātejā rāmaḥ satyaparākramaḥ
gaccha yatnaparaś cāpi bhava lakṣmaṇa saṃyuge', null, 6047046),
('ramayana-6-47-47', 47, 'Yuddha Kanda, Sarga 47, Verse 47', 'रावणो हि महावीर्यो रणेऽद्भुतपराक्रमः।
त्रैलोक्येनापि संक्रुद्धो दुष्प्रसह्यो न संशयः॥', 'rāvaṇo hi mahāvīryo raṇe ''dbhutaparākramaḥ
trailokyenāpi saṃkruddho duṣprasahyo na saṃśayaḥ', null, 6047047),
('ramayana-6-47-48', 48, 'Yuddha Kanda, Sarga 47, Verse 48', 'तस्य च्छिद्राणि मार्गस्व स्वच्छिद्राणि च गोपय।
चक्षुषा धनुषा यत्नाद्रक्षात्मानं समाहितः॥', 'tasya cchidrāṇi mārgasva svacchidrāṇi ca gopaya
cakṣuṣā dhanuṣā yatnād rakṣātmānaṃ samāhitaḥ', null, 6047048),
('ramayana-6-47-49', 49, 'Yuddha Kanda, Sarga 47, Verse 49', 'राघवस्य वचः श्रुत्वा संपरिष्वज्य पूज्य च।
अभिवाद्य ततो रामं ययौ सौमित्रिराहवम्॥', 'rāghavasya vacaḥ śrutvā saṃpariṣvajya pūjya ca
abhivādya tato rāmaṃ yayau saumitrir āhavam', null, 6047049),
('ramayana-6-47-50', 50, 'Yuddha Kanda, Sarga 47, Verse 50', 'स रावणं वारणहस्तबाहुर्ददर्श दीप्तोद्यतभीमचापम्।
प्रच्छादयन्तं शरवृष्टिजालैस्तान्वानरान्भिन्नविकीर्णदेहान्॥', 'sa rāvaṇaṃ vāraṇahastabāhur dadarśa dīptodyatabhīmacāpam
pracchādayantaṃ śaravṛṣṭijālais tān vānarān bhinnavikīrṇadehān', null, 6047050),
('ramayana-6-47-51', 51, 'Yuddha Kanda, Sarga 47, Verse 51', 'तमालोक्य महातेजा हनूमान्मारुतात्मजा।
निवार्य शरजालानि प्रदुद्राव स रावणम्॥', 'tam ālokya mahātejā hanūmān mārutātmajā
nivārya śarajālāni pradudrāva sa rāvaṇam', null, 6047051),
('ramayana-6-47-52', 52, 'Yuddha Kanda, Sarga 47, Verse 52', 'रथं तस्य समासाद्य भुजमुद्यम्य दक्षिणम्।
त्रासयन्रावणं धीमान्हनूमान्वाक्यमब्रवीत्॥', 'rathaṃ tasya samāsādya bhujam udyamya dakṣiṇam
trāsayan rāvaṇaṃ dhīmān hanūmān vākyam abravīt', null, 6047052),
('ramayana-6-47-53', 53, 'Yuddha Kanda, Sarga 47, Verse 53', 'देवदानवगन्धर्वा यक्षाश्च सह राक्षसैः।
अवध्यत्वात्त्वया भग्ना वानरेभ्यस्तु ते भयम्॥', 'devadānavagandharvā yakṣāś ca saha rākṣasaiḥ
avadhyatvāt tvayā bhagnā vānarebhyas tu te bhayam', null, 6047053),
('ramayana-6-47-54', 54, 'Yuddha Kanda, Sarga 47, Verse 54', 'एष मे दक्षिणो बाहुः पञ्चशाखः समुद्यतः।
विधमिष्यति ते देहाद्भूतात्मानं चिरोषितम्॥', 'eṣa me dakṣiṇo bāhuḥ pañcaśākhaḥ samudyataḥ
vidhamiṣyati te dehād bhūtātmānaṃ ciroṣitam', null, 6047054),
('ramayana-6-47-55', 55, 'Yuddha Kanda, Sarga 47, Verse 55', 'श्रुत्वा हनूमतो वाक्यं रावणो भीमविक्रमः।
संरक्तनयनः क्रोधादिदं वचनमब्रवीत्॥', 'śrutvā hanūmato vākyaṃ rāvaṇo bhīmavikramaḥ
saṃraktanayanaḥ krodhād idaṃ vacanam abravīt', null, 6047055),
('ramayana-6-47-56', 56, 'Yuddha Kanda, Sarga 47, Verse 56', 'क्षिप्रं प्रहर निःशङ्कं स्थिरां कीर्तिमवाप्नुहि।
ततस्त्वां ज्ञातिविक्रान्तं नाशयिष्यामि वानर॥', 'kṣipraṃ prahara niḥśaṅkaṃ sthirāṃ kīrtim avāpnuhi
tatas tvāṃ jñātivikrāntaṃ nāśayiṣyāmi vānara', null, 6047056),
('ramayana-6-47-57', 57, 'Yuddha Kanda, Sarga 47, Verse 57', 'रावणस्य वचः श्रुत्वा वायुसूनुर्वचोऽब्रवीत्।
प्रहृतं हि मया पूर्वमक्षं स्मर सुतं तव॥', 'rāvaṇasya vacaḥ śrutvā vāyusūnur vaco ''bravīt
prahṛtaṃ hi mayā pūrvam akṣaṃ smara sutaṃ tava', null, 6047057),
('ramayana-6-47-58', 58, 'Yuddha Kanda, Sarga 47, Verse 58', 'एवमुक्तो महातेजा रावणो राक्षसेश्वरः।
आजघानानिलसुतं तलेनोरसि वीर्यवान्॥', 'evam ukto mahātejā rāvaṇo rākṣaseśvaraḥ
ājaghānānilasutaṃ talenorasi vīryavān', null, 6047058),
('ramayana-6-47-59', 59, 'Yuddha Kanda, Sarga 47, Verse 59', 'स तलाभिहतस्तेन चचाल च मुहुर्मुहुः।
आजघानाभिसंक्रुद्धस्तलेनैवामरद्विषम्॥', 'sa talābhihatas tena cacāla ca muhur muhuḥ
ājaghānābhisaṃkruddhas talenaivāmaradviṣam', null, 6047059),
('ramayana-6-47-60', 60, 'Yuddha Kanda, Sarga 47, Verse 60', 'ततस्तलेनाभिहतो वानरेण महात्मना।
दशग्रीवः समाधूतो यथा भूमिचलेऽचलः॥', 'tatas talenābhihato vānareṇa mahātmanā
daśagrīvaḥ samādhūto yathā bhūmicale ''calaḥ', null, 6047060),
('ramayana-6-47-61', 61, 'Yuddha Kanda, Sarga 47, Verse 61', 'संग्रामे तं तथा दृष्ट्व रावणं तलताडितम्।
ऋषयो वानराः सिद्धा नेदुर्देवाः सहासुराः॥', 'saṃgrāme taṃ tathā dṛṣṭva rāvaṇaṃ talatāḍitam
ṛṣayo vānarāḥ siddhā nedur devāḥ sahāsurāḥ', null, 6047061),
('ramayana-6-47-62', 62, 'Yuddha Kanda, Sarga 47, Verse 62', 'अथाश्वस्य महातेजा रावणो वाक्यमब्रवीत्।
साधु वानरवीर्येण श्लाघनीयोऽसि मे रिपुः॥', 'athāśvasya mahātejā rāvaṇo vākyam abravīt
sādhu vānaravīryeṇa ślāghanīyo ''si me ripuḥ', null, 6047062),
('ramayana-6-47-63', 63, 'Yuddha Kanda, Sarga 47, Verse 63', 'रावणेनैवमुक्तस्तु मारुतिर्वाक्यमब्रवीत्।
धिगस्तु मम वीर्यं तु यत्त्वं जीवसि रावण॥', 'rāvaṇenaivam uktas tu mārutir vākyam abravīt
dhig astu mama vīryaṃ tu yat tvaṃ jīvasi rāvaṇa', null, 6047063),
('ramayana-6-47-64', 64, 'Yuddha Kanda, Sarga 47, Verse 64', 'सकृत्तु प्रहरेदानीं दुर्बुद्धे किं विकत्थसे।
ततस्त्वां मामको मुष्टिर्नयिष्यामि यथाक्षयम्।
ततो मारुतिवाक्येन क्रोधस्तस्य तदाज्वलत्॥', 'sakṛt tu praharedānīṃ durbuddhe kiṃ vikatthase
tatas tvāṃ māmako muṣṭir nayiṣyāmi yathākṣayam
tato mārutivākyena krodhas tasya tadājvalat', null, 6047064),
('ramayana-6-47-65', 65, 'Yuddha Kanda, Sarga 47, Verse 65', 'संरक्तनयनो यत्नान्मुष्टिमुद्यम्य दक्षिणम्।
पातयामास वेगेन वानरोरसि वीर्यवान्।
हनूमान्वक्षसि व्यूधे संचचाल हतः पुनः॥', 'saṃraktanayano yatnān muṣṭim udyamya dakṣiṇam
pātayām āsa vegena vānarorasi vīryavān
hanūmān vakṣasi vyūdhe saṃcacāla hataḥ punaḥ', null, 6047065),
('ramayana-6-47-66', 66, 'Yuddha Kanda, Sarga 47, Verse 66', 'विह्वलं तं तदा दृष्ट्वा हनूमन्तं महाबलम्।
रथेनातिरथः शीघ्रं नीलं प्रति समभ्यगात्॥', 'vihvalaṃ taṃ tadā dṛṣṭvā hanūmantaṃ mahābalam
rathenātirathaḥ śīghraṃ nīlaṃ prati samabhyagāt', null, 6047066),
('ramayana-6-47-67', 67, 'Yuddha Kanda, Sarga 47, Verse 67', 'पन्नगप्रतिमैर्भीमैः परमर्मातिभेदिभिः।
शरैरादीपयामास नीलं हरिचमूपतिम्॥', 'pannagapratimair bhīmaiḥ paramarmātibhedibhiḥ
śarair ādīpayām āsa nīlaṃ haricamūpatim', null, 6047067),
('ramayana-6-47-68', 68, 'Yuddha Kanda, Sarga 47, Verse 68', 'स शरौघसमायस्तो नीलः कपिचमूपतिः।
करेणैकेन शैलाग्रं रक्षोऽधिपतयेऽसृजत्॥', 'sa śaraughasamāyasto nīlaḥ kapicamūpatiḥ
kareṇaikena śailāgraṃ rakṣo''dhipataye ''sṛjat', null, 6047068),
('ramayana-6-47-69', 69, 'Yuddha Kanda, Sarga 47, Verse 69', 'हनूमानपि तेजस्वी समाश्वस्तो महामनाः।
विप्रेक्षमाणो युद्धेप्सुः सरोषमिदमब्रवीत्॥', 'hanūmān api tejasvī samāśvasto mahāmanāḥ
viprekṣamāṇo yuddhepsuḥ saroṣam idam abravīt', null, 6047069),
('ramayana-6-47-70', 70, 'Yuddha Kanda, Sarga 47, Verse 70', 'नीलेन सह संयुक्तं रावणं राक्षसेश्वरम्।
अन्येन युध्यमानस्य न युक्तमभिधावनम्॥', 'nīlena saha saṃyuktaṃ rāvaṇaṃ rākṣaseśvaram
anyena yudhyamānasya na yuktam abhidhāvanam', null, 6047070),
('ramayana-6-47-71', 71, 'Yuddha Kanda, Sarga 47, Verse 71', 'रावणोऽपि महातेजास्तच्छृङ्गं सप्तभिः शरैः।
आजघान सुतीक्ष्णाग्रैस्तद्विकीर्णं पपात ह॥', 'rāvaṇo ''pi mahātejās tac chṛṅgaṃ saptabhiḥ śaraiḥ
ājaghāna sutīkṣṇāgrais tad vikīrṇaṃ papāta ha', null, 6047071),
('ramayana-6-47-72', 72, 'Yuddha Kanda, Sarga 47, Verse 72', 'तद्विकीर्णं गिरेः शृङ्गं दृष्ट्वा हरिचमूपतिः।
कालाग्निरिव जज्वाल क्रोधेन परवीरहा॥', 'tad vikīrṇaṃ gireḥ śṛṅgaṃ dṛṣṭvā haricamūpatiḥ
kālāgnir iva jajvāla krodhena paravīrahā', null, 6047072),
('ramayana-6-47-73', 73, 'Yuddha Kanda, Sarga 47, Verse 73', 'सोऽश्वकर्णान्धवान्सालांश्चूतांश्चापि सुपुष्पितान्।
अन्यांश्च विविधान्वृक्षान्नीलश्चिक्षेप संयुगे॥', 'so ''śvakarṇān dhavān sālāṃś cūtāṃś cāpi supuṣpitān
anyāṃś ca vividhān vṛkṣān nīlaś cikṣepa saṃyuge', null, 6047073),
('ramayana-6-47-74', 74, 'Yuddha Kanda, Sarga 47, Verse 74', 'स तान्वृक्षान्समासाद्य प्रतिचिच्छेद रावणः।
अभ्यवर्षत्सुघोरेण शरवर्षेण पावकिम्॥', 'sa tān vṛkṣān samāsādya praticiccheda rāvaṇaḥ
abhyavarṣat sughoreṇa śaravarṣeṇa pāvakim', null, 6047074),
('ramayana-6-47-75', 75, 'Yuddha Kanda, Sarga 47, Verse 75', 'अभिवृष्टः शरौघेण मेघेनेव महाचलः।
ह्रस्वं कृत्वा तदा रूपं ध्वजाग्रे निपपात ह॥', 'abhivṛṣṭaḥ śaraugheṇa megheneva mahācalaḥ
hrasvaṃ kṛtvā tadā rūpaṃ dhvajāgre nipapāta ha', null, 6047075),
('ramayana-6-47-76', 76, 'Yuddha Kanda, Sarga 47, Verse 76', 'पावकात्मजमालोक्य ध्वजाग्रे समवस्थितम्।
जज्वाल रावणः क्रोधात्ततो नीलो ननाद ह॥', 'pāvakātmajam ālokya dhvajāgre samavasthitam
jajvāla rāvaṇaḥ krodhāt tato nīlo nanāda ha', null, 6047076),
('ramayana-6-47-77', 77, 'Yuddha Kanda, Sarga 47, Verse 77', 'ध्वजाग्रे धनुषश्चाग्रे किरीटाग्रे च तं हरिम्।
लक्ष्मणोऽथ हनूमांश्च दृष्ट्वा रामश्च विस्मिताः॥', 'dhvajāgre dhanuṣaś cāgre kirīṭāgre ca taṃ harim
lakṣmaṇo ''tha hanūmāṃś ca dṛṣṭvā rāmaś ca vismitāḥ', null, 6047077),
('ramayana-6-47-78', 78, 'Yuddha Kanda, Sarga 47, Verse 78', 'रावणोऽपि महातेजाः कपिलाघवविस्मितः।
अस्त्रमाहारयामास दीप्तमाग्नेयमद्भुतम्॥', 'rāvaṇo ''pi mahātejāḥ kapilāghavavismitaḥ
astram āhārayām āsa dīptam āgneyam adbhutam', null, 6047078),
('ramayana-6-47-79', 79, 'Yuddha Kanda, Sarga 47, Verse 79', 'ततस्ते चुक्रुशुर्हृष्टा लब्धलक्ष्याः प्लवंगमाः।
नीललाघवसंभ्रान्तं दृष्ट्वा रावणमाहवे॥', 'tatas te cukruśur hṛṣṭā labdhalakṣyāḥ plavaṃgamāḥ
nīlalāghavasaṃbhrāntaṃ dṛṣṭvā rāvaṇam āhave', null, 6047079),
('ramayana-6-47-80', 80, 'Yuddha Kanda, Sarga 47, Verse 80', 'वानराणां च नादेन संरब्धो रावणस्तदा।
संभ्रमाविष्टहृदयो न किं चित्प्रत्यपद्यत॥', 'vānarāṇāṃ ca nādena saṃrabdho rāvaṇas tadā
saṃbhramāviṣṭahṛdayo na kiṃ cit pratyapadyata', null, 6047080),
('ramayana-6-47-81', 81, 'Yuddha Kanda, Sarga 47, Verse 81', 'आग्नेयेनाथ संयुक्तं गृहीत्वा रावणः शरम्।
ध्वजशीर्षस्थितं नीलमुदैक्षत निशाचरः॥', 'āgneyenātha saṃyuktaṃ gṛhītvā rāvaṇaḥ śaram
dhvajaśīrṣasthitaṃ nīlam udaikṣata niśācaraḥ', null, 6047081),
('ramayana-6-47-82', 82, 'Yuddha Kanda, Sarga 47, Verse 82', 'ततोऽब्रवीन्महातेजा रावणो राक्षसेश्वरः।
कपे लाघवयुक्तोऽसि मायया परयानया॥', 'tato ''bravīn mahātejā rāvaṇo rākṣaseśvaraḥ
kape lāghavayukto ''si māyayā parayānayā', null, 6047082),
('ramayana-6-47-83', 83, 'Yuddha Kanda, Sarga 47, Verse 83', 'जीवितं खलु रक्षस्व यदि शक्नोषि वानर।
तानि तान्यात्मरूपाणि सृजसे त्वमनेकशः॥', 'jīvitaṃ khalu rakṣasva yadi śaknoṣi vānara
tāni tāny ātmarūpāṇi sṛjase tvam anekaśaḥ', null, 6047083),
('ramayana-6-47-84', 84, 'Yuddha Kanda, Sarga 47, Verse 84', 'तथापि त्वां मया मुक्तः सायकोऽस्त्रप्रयोजितः।
जीवितं परिरक्षन्तं जीविताद्भ्रंशयिष्यति॥', 'tathāpi tvāṃ mayā muktaḥ sāyako ''straprayojitaḥ
jīvitaṃ parirakṣantaṃ jīvitād bhraṃśayiṣyati', null, 6047084),
('ramayana-6-47-85', 85, 'Yuddha Kanda, Sarga 47, Verse 85', 'एवमुक्त्वा महाबाहू रावणो राक्षसेश्वरः।
संधाय बाणमस्त्रेण चमूपतिमताडयत्॥', 'evam uktvā mahābāhū rāvaṇo rākṣaseśvaraḥ
saṃdhāya bāṇam astreṇa camūpatim atāḍayat', null, 6047085),
('ramayana-6-47-86', 86, 'Yuddha Kanda, Sarga 47, Verse 86', 'सोऽस्त्रयुक्तेन बाणेन नीलो वक्षसि ताडितः।
निर्दह्यमानः सहसा निपपात महीतले॥', 'so ''strayuktena bāṇena nīlo vakṣasi tāḍitaḥ
nirdahyamānaḥ sahasā nipapāta mahītale', null, 6047086),
('ramayana-6-47-87', 87, 'Yuddha Kanda, Sarga 47, Verse 87', 'पितृमाहात्म्य संयोगादात्मनश्चापि तेजसा।
जानुभ्यामपतद्भूमौ न च प्राणैर्व्ययुज्यत॥', 'pitṛmāhātmya saṃyogād ātmanaś cāpi tejasā
jānubhyām apatad bhūmau na ca prāṇair vyayujyata', null, 6047087),
('ramayana-6-47-88', 88, 'Yuddha Kanda, Sarga 47, Verse 88', 'विसंज्ञं वानरं दृष्ट्वा दशग्रीवो रणोत्सुकः।
रथेनाम्बुदनादेन सौमित्रिमभिदुद्रुवे॥', 'visaṃjñaṃ vānaraṃ dṛṣṭvā daśagrīvo raṇotsukaḥ
rathenāmbudanādena saumitrim abhidudruve', null, 6047088),
('ramayana-6-47-89', 89, 'Yuddha Kanda, Sarga 47, Verse 89', 'तमाह सौमित्रिरदीनसत्त्वो विस्फारयन्तं धनुरप्रमेयम्।
अन्वेहि मामेव निशाचरेन्द्र न वानरांस्त्वं प्रति योद्धुमर्हसि॥', 'tam āha saumitrir adīnasattvo visphārayantaṃ dhanur aprameyam
anvehi mām eva niśācarendra na vānarāṃs tvaṃ prati yoddhum arhasi', null, 6047089),
('ramayana-6-47-90', 90, 'Yuddha Kanda, Sarga 47, Verse 90', 'स तस्य वाक्यं परिपूर्णघोषं ज्याशब्दमुग्रं च निशम्य राजा।
आसाद्य सौमित्रिमवस्थितं तं कोपान्वितं वाक्यमुवाच रक्षः॥', 'sa tasya vākyaṃ paripūrṇaghoṣaṃ jyāśabdam ugraṃ ca niśamya rājā
āsādya saumitrim avasthitaṃ taṃ kopānvitaṃ vākyam uvāca rakṣaḥ', null, 6047090),
('ramayana-6-47-91', 91, 'Yuddha Kanda, Sarga 47, Verse 91', 'दिष्ट्यासि मे राघव दृष्टिमार्गं प्राप्तोऽन्तगामी विपरीतबुद्धिः।
अस्मिन्क्षणे यास्यसि मृत्युदेशं संसाद्यमानो मम बाणजालैः॥', 'diṣṭyāsi me rāghava dṛṣṭimārgaṃ prāpto ''ntagāmī viparītabuddhiḥ
asmin kṣaṇe yāsyasi mṛtyudeśaṃ saṃsādyamāno mama bāṇajālaiḥ', null, 6047091),
('ramayana-6-47-92', 92, 'Yuddha Kanda, Sarga 47, Verse 92', 'तमाह सौमित्रिरविस्मयानो गर्जन्तमुद्वृत्तसिताग्रदंष्ट्रम्।
राजन्न गर्जन्ति महाप्रभावा विकत्थसे पापकृतां वरिष्ठ॥', 'tam āha saumitrir avismayāno garjantam udvṛttasitāgradaṃṣṭram
rājan na garjanti mahāprabhāvā vikatthase pāpakṛtāṃ variṣṭha', null, 6047092),
('ramayana-6-47-93', 93, 'Yuddha Kanda, Sarga 47, Verse 93', 'जानामि वीर्यं तव राक्षसेन्द्र बलं प्रतापं च पराक्रमं च।
अवस्थितोऽहं शरचापपाणिरागच्छ किं मोघविकत्थनेन॥', 'jānāmi vīryaṃ tava rākṣasendra balaṃ pratāpaṃ ca parākramaṃ ca
avasthito ''haṃ śaracāpapāṇir āgaccha kiṃ moghavikatthanena', null, 6047093),
('ramayana-6-47-94', 94, 'Yuddha Kanda, Sarga 47, Verse 94', 'स एवमुक्तः कुपितः ससर्ज रक्षोऽधिपः सप्तशरान्सुपुङ्खान्।
तांल्लक्ष्मणः काञ्चनचित्रपुङ्खैश्चिच्छेद बाणैर्निशिताग्रधारैः॥', 'sa evam uktaḥ kupitaḥ sasarja rakṣo''dhipaḥ saptaśarān supuṅkhān
tāṃl lakṣmaṇaḥ kāñcanacitrapuṅkhaiś ciccheda bāṇair niśitāgradhāraiḥ', null, 6047094),
('ramayana-6-47-95', 95, 'Yuddha Kanda, Sarga 47, Verse 95', 'तान्प्रेक्षमाणः सहसा निकृत्तान्निकृत्तभोगानिव पन्नगेन्द्रान्।
लङ्केश्वरः क्रोधवशं जगाम ससर्ज चान्यान्निशितान्पृषत्कान्॥', 'tān prekṣamāṇaḥ sahasā nikṛttān nikṛttabhogān iva pannagendrān
laṅkeśvaraḥ krodhavaśaṃ jagāma sasarja cānyān niśitān pṛṣatkān', null, 6047095),
('ramayana-6-47-96', 96, 'Yuddha Kanda, Sarga 47, Verse 96', 'स बाणवर्षं तु ववर्ष तीव्रं रामानुजः कार्मुकसंप्रयुक्तम्।
क्षुरार्धचन्द्रोत्तमकर्णिभल्लैः शरांश्च चिच्छेद न चुक्षुभे च॥', 'sa bāṇavarṣaṃ tu vavarṣa tīvraṃ rāmānujaḥ kārmukasaṃprayuktam
kṣurārdhacandrottamakarṇibhallaiḥ śarāṃś ca ciccheda na cukṣubhe ca', null, 6047096),
('ramayana-6-47-97', 97, 'Yuddha Kanda, Sarga 47, Verse 97', 'स लक्ष्मणश्चाशु शराञ्शिताग्रान्महेन्द्रवज्राशनितुल्यवेगान्।
संधाय चापे ज्वलनप्रकाशान्ससर्ज रक्षोऽधिपतेर्वधाय॥', 'sa lakṣmaṇaś cāśu śarāñ śitāgrān mahendravajrāśanitulyavegān
saṃdhāya cāpe jvalanaprakāśān sasarja rakṣo''dhipater vadhāya', null, 6047097),
('ramayana-6-47-98', 98, 'Yuddha Kanda, Sarga 47, Verse 98', 'स तान्प्रचिच्छेद हि राक्षसेन्द्रश्छित्त्वा च तांल्लक्ष्मणमाजघान।
शरेण कालाग्निसमप्रभेण स्वयम्भुदत्तेन ललाटदेशे॥', 'sa tān praciccheda hi rākṣasendraś chittvā ca tāṃl lakṣmaṇam ājaghāna
śareṇa kālāgnisamaprabheṇa svayambhudattena lalāṭadeśe', null, 6047098),
('ramayana-6-47-99', 99, 'Yuddha Kanda, Sarga 47, Verse 99', 'स लक्ष्मणो रावणसायकार्तश्चचाल चापं शिथिलं प्रगृह्य।
पुनश्च संज्ञां प्रतिलभ्य कृच्छ्राच्चिच्छेद चापं त्रिदशेन्द्रशत्रोः॥', 'sa lakṣmaṇo rāvaṇasāyakārtaś cacāla cāpaṃ śithilaṃ pragṛhya
punaś ca saṃjñāṃ pratilabhya kṛcchrāc ciccheda cāpaṃ tridaśendraśatroḥ', null, 6047099),
('ramayana-6-47-100', 100, 'Yuddha Kanda, Sarga 47, Verse 100', 'निकृत्तचापं त्रिभिराजघान बाणैस्तदा दाशरथिः शिताग्रैः।
स सायकार्तो विचचाल राजा कृच्छ्राच्च संज्ञां पुनराससाद॥', 'nikṛttacāpaṃ tribhir ājaghāna bāṇais tadā dāśarathiḥ śitāgraiḥ
sa sāyakārto vicacāla rājā kṛcchrāc ca saṃjñāṃ punar āsasāda', null, 6047100),
('ramayana-6-47-101', 101, 'Yuddha Kanda, Sarga 47, Verse 101', 'स कृत्तचापः शरताडितश्च स्वेदार्द्रगात्रो रुधिरावसिक्तः।
जग्राह शक्तिं समुदग्रशक्तिः स्वयम्भुदत्तां युधि देवशत्रुः॥', 'sa kṛttacāpaḥ śaratāḍitaś ca svedārdragātro rudhirāvasiktaḥ
jagrāha śaktiṃ samudagraśaktiḥ svayambhudattāṃ yudhi devaśatruḥ', null, 6047101),
('ramayana-6-47-102', 102, 'Yuddha Kanda, Sarga 47, Verse 102', 'स तां विधूमानलसंनिकाशां वित्रासनीं वानरवाहिनीनाम्।
चिक्षेप शक्तिं तरसा ज्वलन्तीं सौमित्रये राक्षसराष्ट्रनाथः॥', 'sa tāṃ vidhūmānalasaṃnikāśāṃ vitrāsanīṃ vānaravāhinīnām
cikṣepa śaktiṃ tarasā jvalantīṃ saumitraye rākṣasarāṣṭranāthaḥ', null, 6047102),
('ramayana-6-47-103', 103, 'Yuddha Kanda, Sarga 47, Verse 103', 'तामापतन्तीं भरतानुजोऽस्त्रैर्जघान बाणैश्च हुताग्निकल्पैः।
तथापि सा तस्य विवेश शक्तिर्भुजान्तरं दाशरथेर्विशालम्॥', 'tām āpatantīṃ bharatānujo ''strair jaghāna bāṇaiś ca hutāgnikalpaiḥ
tathāpi sā tasya viveśa śaktir bhujāntaraṃ dāśarather viśālam', null, 6047103),
('ramayana-6-47-104', 104, 'Yuddha Kanda, Sarga 47, Verse 104', 'शक्त्या ब्राम्या तु सौमित्रिस्ताडितस्तु स्तनान्तरे।
विष्णोरचिन्त्यं स्वं भागमात्मानं प्रत्यनुस्मरत्॥', 'śaktyā brāmyā tu saumitris tāḍitas tu stanāntare
viṣṇor acintyaṃ svaṃ bhāgam ātmānaṃ pratyanusmarat', null, 6047104),
('ramayana-6-47-105', 105, 'Yuddha Kanda, Sarga 47, Verse 105', 'ततो दानवदर्पघ्नं सौमित्रिं देवकण्टकः।
तं पीडयित्वा बाहुभ्यामप्रभुर्लङ्घनेऽभवत्॥', 'tato dānavadarpaghnaṃ saumitriṃ devakaṇṭakaḥ
taṃ pīḍayitvā bāhubhyām aprabhur laṅghane ''bhavat', null, 6047105),
('ramayana-6-47-106', 106, 'Yuddha Kanda, Sarga 47, Verse 106', 'हिमवान्मन्दरो मेरुस्त्रैलोक्यं वा सहामरैः।
शक्यं भुजाभ्यामुद्धर्तुं न संख्ये भरतानुजः॥', 'himavān mandaro merus trailokyaṃ vā sahāmaraiḥ
śakyaṃ bhujābhyām uddhartuṃ na saṃkhye bharatānujaḥ', null, 6047106),
('ramayana-6-47-107', 107, 'Yuddha Kanda, Sarga 47, Verse 107', 'अथैनं वैष्णवं भागं मानुषं देहमास्थितम्।
विसंज्ञं लक्ष्मणं दृष्ट्वा रावणो विस्मितोऽभवत्॥', 'athainaṃ vaiṣṇavaṃ bhāgaṃ mānuṣaṃ deham āsthitam
visaṃjñaṃ lakṣmaṇaṃ dṛṣṭvā rāvaṇo vismito ''bhavat', null, 6047107),
('ramayana-6-47-108', 108, 'Yuddha Kanda, Sarga 47, Verse 108', 'अथ वायुसुतः क्रुद्धो रावणं समभिद्रवत्।
आजघानोरसि क्रुद्धो वज्रकल्पेन मुष्टिना॥', 'atha vāyusutaḥ kruddho rāvaṇaṃ samabhidravat
ājaghānorasi kruddho vajrakalpena muṣṭinā', null, 6047108),
('ramayana-6-47-109', 109, 'Yuddha Kanda, Sarga 47, Verse 109', 'तेन मुष्टिप्रहारेण रावणो राक्षसेश्वरः।
जानुभ्यामपतद्भूमौ चचाल च पपात च॥', 'tena muṣṭiprahāreṇa rāvaṇo rākṣaseśvaraḥ
jānubhyām apatad bhūmau cacāla ca papāta ca', null, 6047109),
('ramayana-6-47-110', 110, 'Yuddha Kanda, Sarga 47, Verse 110', 'विसंज्ञं रावणं दृष्ट्वा समरे भीमविक्रमम्।
ऋषयो वानराश्चैव नेदुर्देवाः सवासवाः॥', 'visaṃjñaṃ rāvaṇaṃ dṛṣṭvā samare bhīmavikramam
ṛṣayo vānarāś caiva nedur devāḥ savāsavāḥ', null, 6047110),
('ramayana-6-47-111', 111, 'Yuddha Kanda, Sarga 47, Verse 111', 'हनूमानपि तेजस्वी लक्ष्मणं रावणार्दितम्।
अनयद्राघवाभ्याशं बाहुभ्यां परिगृह्य तम्॥', 'hanūmān api tejasvī lakṣmaṇaṃ rāvaṇārditam
anayad rāghavābhyāśaṃ bāhubhyāṃ parigṛhya tam', null, 6047111),
('ramayana-6-47-112', 112, 'Yuddha Kanda, Sarga 47, Verse 112', 'वायुसूनोः सुहृत्त्वेन भक्त्या परमया च सः।
शत्रूणामप्रकम्प्योऽपि लघुत्वमगमत्कपेः॥', 'vāyusūnoḥ suhṛttvena bhaktyā paramayā ca saḥ
śatrūṇām aprakampyo ''pi laghutvam agamat kapeḥ', null, 6047112),
('ramayana-6-47-113', 113, 'Yuddha Kanda, Sarga 47, Verse 113', 'तं समुत्सृज्य सा शक्तिः सौमित्रिं युधि दुर्जयम्।
रावणस्य रथे तस्मिन्स्थानं पुनरुपागमत्॥', 'taṃ samutsṛjya sā śaktiḥ saumitriṃ yudhi durjayam
rāvaṇasya rathe tasmin sthānaṃ punar upāgamat', null, 6047113),
('ramayana-6-47-114', 114, 'Yuddha Kanda, Sarga 47, Verse 114', 'रावणोऽपि महातेजाः प्राप्य संज्ञां महाहवे।
आददे निशितान्बाणाञ्जग्राह च महद्धनुः॥', 'rāvaṇo ''pi mahātejāḥ prāpya saṃjñāṃ mahāhave
ādade niśitān bāṇāñ jagrāha ca mahad dhanuḥ', null, 6047114),
('ramayana-6-47-115', 115, 'Yuddha Kanda, Sarga 47, Verse 115', 'आश्वस्तश्च विशल्यश्च लक्ष्मणः शत्रुसूदनः।
विष्णोर्भागममीमांस्यमात्मानं प्रत्यनुस्मरन्॥', 'āśvastaś ca viśalyaś ca lakṣmaṇaḥ śatrusūdanaḥ
viṣṇor bhāgam amīmāṃsyam ātmānaṃ pratyanusmaran', null, 6047115),
('ramayana-6-47-116', 116, 'Yuddha Kanda, Sarga 47, Verse 116', 'निपातितमहावीरां वानराणां महाचमूम्।
राघवस्तु रणे दृष्ट्वा रावणं समभिद्रवत्॥', 'nipātitamahāvīrāṃ vānarāṇāṃ mahācamūm
rāghavas tu raṇe dṛṣṭvā rāvaṇaṃ samabhidravat', null, 6047116),
('ramayana-6-47-117', 117, 'Yuddha Kanda, Sarga 47, Verse 117', 'अथैनमुपसंगम्य हनूमान्वाक्यमब्रवीत्।
मम पृष्ठं समारुह्य रक्षसं शास्तुमर्हसि॥', 'athainam upasaṃgamya hanūmān vākyam abravīt
mama pṛṣṭhaṃ samāruhya rakṣasaṃ śāstum arhasi', null, 6047117),
('ramayana-6-47-118', 118, 'Yuddha Kanda, Sarga 47, Verse 118', 'तच्छ्रुत्वा राघवो वाक्यं वायुपुत्रेण भाषितम्।
आरोहत्सहसा शूरो हनूमन्तं महाकपिम्।
रथस्थं रावणं संख्ये ददर्श मनुजाधिपः॥', 'tac chrutvā rāghavo vākyaṃ vāyuputreṇa bhāṣitam
ārohat sahasā śūro hanūmantaṃ mahākapim
rathasthaṃ rāvaṇaṃ saṃkhye dadarśa manujādhipaḥ', null, 6047118),
('ramayana-6-47-119', 119, 'Yuddha Kanda, Sarga 47, Verse 119', 'तमालोक्य महातेजाः प्रदुद्राव स राघवः।
वैरोचनमिव क्रुद्धो विष्णुरभ्युद्यतायुधः॥', 'tam ālokya mahātejāḥ pradudrāva sa rāghavaḥ
vairocanam iva kruddho viṣṇur abhyudyatāyudhaḥ', null, 6047119),
('ramayana-6-47-120', 120, 'Yuddha Kanda, Sarga 47, Verse 120', 'ज्याशब्दमकरोत्तीव्रं वज्रनिष्पेषनिस्वनम्।
गिरा गम्भीरया रामो राक्षसेन्द्रमुवाच ह॥', 'jyāśabdam akarot tīvraṃ vajraniṣpeṣanisvanam
girā gambhīrayā rāmo rākṣasendram uvāca ha', null, 6047120),
('ramayana-6-47-121', 121, 'Yuddha Kanda, Sarga 47, Verse 121', 'तिष्ठ तिष्ठ मम त्वं हि कृत्वा विप्रियमीदृशम्।
क्व नु राक्षसशार्दूल गतो मोक्षमवाप्स्यसि॥', 'tiṣṭha tiṣṭha mama tvaṃ hi kṛtvā vipriyam īdṛśam
kva nu rākṣasaśārdūla gato mokṣam avāpsyasi', null, 6047121),
('ramayana-6-47-122', 122, 'Yuddha Kanda, Sarga 47, Verse 122', 'यदीन्द्रवैवस्वत भास्करान्वा स्वयम्भुवैश्वानरशंकरान्वा।
गमिष्यसि त्वं दश वा दिशो वा तथापि मे नाद्य गतो विमोक्ष्यसे॥', 'yadīndravaivasvata bhāskarān vā svayambhuvaiśvānaraśaṃkarān vā
gamiṣyasi tvaṃ daśa vā diśo vā tathāpi me nādya gato vimokṣyase', null, 6047122),
('ramayana-6-47-123', 123, 'Yuddha Kanda, Sarga 47, Verse 123', 'यश्चैष शक्त्याभिहतस्त्वयाद्य इच्छन्विषादं सहसाभ्युपेतः।
स एष रक्षोगणराज मृत्युः सपुत्रदारस्य तवाद्य युद्धे॥', 'yaś caiṣa śaktyābhihatas tvayādya icchan viṣādaṃ sahasābhyupetaḥ
sa eṣa rakṣogaṇarāja mṛtyuḥ saputradārasya tavādya yuddhe', null, 6047123),
('ramayana-6-47-124', 124, 'Yuddha Kanda, Sarga 47, Verse 124', 'राघवस्य वचः श्रुत्वा राक्षसेन्द्रो महाकपिम्।
आजघान शरैस्तीक्ष्णैः कालानलशिखोपमैः॥', 'rāghavasya vacaḥ śrutvā rākṣasendro mahākapim
ājaghāna śarais tīkṣṇaiḥ kālānalaśikhopamaiḥ', null, 6047124),
('ramayana-6-47-125', 125, 'Yuddha Kanda, Sarga 47, Verse 125', 'राक्षसेनाहवे तस्य ताडितस्यापि सायकैः।
स्वभावतेजोयुक्तस्य भूयस्तेजो व्यवर्धत॥', 'rākṣasenāhave tasya tāḍitasyāpi sāyakaiḥ
svabhāvatejoyuktasya bhūyas tejo vyavardhata', null, 6047125),
('ramayana-6-47-126', 126, 'Yuddha Kanda, Sarga 47, Verse 126', 'ततो रामो महातेजा रावणेन कृतव्रणम्।
दृष्ट्वा प्लवगशार्दूलं क्रोधस्य वशमेयिवान्॥', 'tato rāmo mahātejā rāvaṇena kṛtavraṇam
dṛṣṭvā plavagaśārdūlaṃ krodhasya vaśam eyivān', null, 6047126),
('ramayana-6-47-127', 127, 'Yuddha Kanda, Sarga 47, Verse 127', 'तस्याभिसंक्रम्य रथं सचक्रं साश्वध्वजच्छत्रमहापताकम्।
ससारथिं साशनिशूलखड्गं रामः प्रचिच्छेद शरैः सुपुङ्खैः॥', 'tasyābhisaṃkramya rathaṃ sacakraṃ sāśvadhvajacchatramahāpatākam
sasārathiṃ sāśaniśūlakhaḍgaṃ rāmaḥ praciccheda śaraiḥ supuṅkhaiḥ', null, 6047127),
('ramayana-6-47-128', 128, 'Yuddha Kanda, Sarga 47, Verse 128', 'अथेन्द्रशत्रुं तरसा जघान बाणेन वज्राशनिसंनिभेन।
भुजान्तरे व्यूढसुजातरूपे वज्रेण मेरुं भगवानिवेन्द्रः॥', 'athendraśatruṃ tarasā jaghāna bāṇena vajrāśanisaṃnibhena
bhujāntare vyūḍhasujātarūpe vajreṇa meruṃ bhagavān ivendraḥ', null, 6047128),
('ramayana-6-47-129', 129, 'Yuddha Kanda, Sarga 47, Verse 129', 'यो वज्रपाताशनिसंनिपातान्न चुक्षुभे नापि चचाल राजा।
स रामबाणाभिहतो भृशार्तश्चचाल चापं च मुमोच वीरः॥', 'yo vajrapātāśanisaṃnipātān na cukṣubhe nāpi cacāla rājā
sa rāmabāṇābhihato bhṛśārtaś cacāla cāpaṃ ca mumoca vīraḥ', null, 6047129),
('ramayana-6-47-130', 130, 'Yuddha Kanda, Sarga 47, Verse 130', 'तं विह्वलन्तं प्रसमीक्ष्य रामः समाददे दीप्तमथार्धचन्द्रम्।
तेनार्कवर्णं सहसा किरीटं चिच्छेद रक्षोऽधिपतेर्महात्माः॥', 'taṃ vihvalantaṃ prasamīkṣya rāmaḥ samādade dīptam athārdhacandram
tenārkavarṇaṃ sahasā kirīṭaṃ ciccheda rakṣo''dhipater mahātmāḥ', null, 6047130),
('ramayana-6-47-131', 131, 'Yuddha Kanda, Sarga 47, Verse 131', 'तं निर्विषाशीविषसंनिकाशं शान्तार्चिषं सूर्यमिवाप्रकाशम्।
गतश्रियं कृत्तकिरीटकूटमुवाच रामो युधि राक्षसेन्द्रम्॥', 'taṃ nirviṣāśīviṣasaṃnikāśaṃ śāntārciṣaṃ sūryam ivāprakāśam
gataśriyaṃ kṛttakirīṭakūṭam uvāca rāmo yudhi rākṣasendram', null, 6047131),
('ramayana-6-47-132', 132, 'Yuddha Kanda, Sarga 47, Verse 132', 'कृतं त्वया कर्म महत्सुभीमं हतप्रवीरश्च कृतस्त्वयाहम्।
तस्मात्परिश्रान्त इति व्यवस्य न त्वं शरैर्मृत्युवशं नयामि॥', 'kṛtaṃ tvayā karma mahat subhīmaṃ hatapravīraś ca kṛtas tvayāham
tasmāt pariśrānta iti vyavasya na tvaṃ śarair mṛtyuvaśaṃ nayāmi', null, 6047132),
('ramayana-6-47-133', 133, 'Yuddha Kanda, Sarga 47, Verse 133', 'स एवमुक्तो हतदर्पहर्षो निकृत्तचापः स हताश्वसूतः।
शरार्दितः कृत्तमहाकिरीटो विवेश लङ्कां सहसा स्म राजा॥', 'sa evam ukto hatadarpaharṣo nikṛttacāpaḥ sa hatāśvasūtaḥ
śarārditaḥ kṛttamahākirīṭo viveśa laṅkāṃ sahasā sma rājā', null, 6047133),
('ramayana-6-47-134', 134, 'Yuddha Kanda, Sarga 47, Verse 134', 'तस्मिन्प्रविष्टे रजनीचरेन्द्रे महाबले दानवदेवशत्रौ।
हरीन्विशल्यान्सहलक्ष्मणेन चकार रामः परमाहवाग्रे॥', 'tasmin praviṣṭe rajanīcarendre mahābale dānavadevaśatrau
harīn viśalyān sahalakṣmaṇena cakāra rāmaḥ paramāhavāgre', null, 6047134),
('ramayana-6-47-135', 135, 'Yuddha Kanda, Sarga 47, Verse 135', 'तस्मिन्प्रभग्ने त्रिदशेन्द्रशत्रौ सुरासुरा भूतगणा दिशश्च।
ससागराः सर्षिमहोरगाश्च तथैव भूम्यम्बुचराश्च हृष्टाः॥', 'tasmin prabhagne tridaśendraśatrau surāsurā bhūtagaṇā diśaś ca
sasāgarāḥ sarṣimahoragāś ca tathaiva bhūmyambucarāś ca hṛṣṭāḥ', null, 6047135)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 48 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-48-1', 1, 'Yuddha Kanda, Sarga 48, Verse 1', 'स प्रविश्य पुरीं लङ्कां रामबाणभयार्दितः।
भग्नदर्पस्तदा राजा बभूव व्यथितेन्द्रियः॥', 'sa praviśya purīṃ laṅkāṃ rāmabāṇabhayārditaḥ
bhagnadarpas tadā rājā babhūva vyathitendriyaḥ', null, 6048001),
('ramayana-6-48-2', 2, 'Yuddha Kanda, Sarga 48, Verse 2', 'मातंग इव सिंहेन गरुडेनेव पन्नगः।
अभिभूतोऽभवद्राजा राघवेण महात्मना॥', 'mātaṃga iva siṃhena garuḍeneva pannagaḥ
abhibhūto ''bhavad rājā rāghaveṇa mahātmanā', null, 6048002),
('ramayana-6-48-3', 3, 'Yuddha Kanda, Sarga 48, Verse 3', 'ब्रह्मदण्डप्रकाशानां विद्युत्सदृशवर्चसाम्।
स्मरन्राघवबाणानां विव्यथे राक्षसेश्वरः॥', 'brahmadaṇḍaprakāśānāṃ vidyutsadṛśavarcasām
smaran rāghavabāṇānāṃ vivyathe rākṣaseśvaraḥ', null, 6048003),
('ramayana-6-48-4', 4, 'Yuddha Kanda, Sarga 48, Verse 4', 'स काञ्चनमयं दिव्यमाश्रित्य परमासनम्।
विक्प्रेक्षमाणो रक्षांसि रावणो वाक्यमब्रवीत्॥', 'sa kāñcanamayaṃ divyam āśritya paramāsanam
vikprekṣamāṇo rakṣāṃsi rāvaṇo vākyam abravīt', null, 6048004),
('ramayana-6-48-5', 5, 'Yuddha Kanda, Sarga 48, Verse 5', 'सर्वं तत्खलु मे मोघं यत्तप्तं परमं तपः।
यत्समानो महेन्द्रेण मानुषेणास्मि निर्जितः॥', 'sarvaṃ tat khalu me moghaṃ yat taptaṃ paramaṃ tapaḥ
yat samāno mahendreṇa mānuṣeṇāsmi nirjitaḥ', null, 6048005),
('ramayana-6-48-6', 6, 'Yuddha Kanda, Sarga 48, Verse 6', 'इदं तद्ब्रह्मणो घोरं वाक्यं मामभ्युपस्थितम्।
मानुषेभ्यो विजानीहि भयं त्वमिति तत्तथा॥', 'idaṃ tad brahmaṇo ghoraṃ vākyaṃ mām abhyupasthitam
mānuṣebhyo vijānīhi bhayaṃ tvam iti tat tathā', null, 6048006),
('ramayana-6-48-7', 7, 'Yuddha Kanda, Sarga 48, Verse 7', 'देवदानवगन्धर्वैर्यक्षराक्षसपन्नगैः।
अवध्यत्वं मया प्राप्तं मानुषेभ्यो न याचितम्॥', 'devadānavagandharvair yakṣarākṣasapannagaiḥ
avadhyatvaṃ mayā prāptaṃ mānuṣebhyo na yācitam', null, 6048007),
('ramayana-6-48-8', 8, 'Yuddha Kanda, Sarga 48, Verse 8', 'एतदेवाभ्युपागम्य यत्नं कर्तुमिहार्हथ।
राक्षसाश्चापि तिष्ठन्तु चर्यागोपुरमूर्धसु॥', 'etad evābhyupāgamya yatnaṃ kartum ihārhatha
rākṣasāś cāpi tiṣṭhantu caryāgopuramūrdhasu', null, 6048008),
('ramayana-6-48-9', 9, 'Yuddha Kanda, Sarga 48, Verse 9', 'स चाप्रतिमगम्भीरो देवदानवदर्पहा।
ब्रह्मशापाभिभूतस्तु कुम्भकर्णो विबोध्यताम्॥', 'sa cāpratimagambhīro devadānavadarpahā
brahmaśāpābhibhūtas tu kumbhakarṇo vibodhyatām', null, 6048009),
('ramayana-6-48-10', 10, 'Yuddha Kanda, Sarga 48, Verse 10', 'स पराजितमात्मानं प्रहस्तं च निषूदितम्।
ज्ञात्वा रक्षोबलं भीममादिदेश महाबलः॥', 'sa parājitam ātmānaṃ prahastaṃ ca niṣūditam
jñātvā rakṣobalaṃ bhīmam ādideśa mahābalaḥ', null, 6048010),
('ramayana-6-48-11', 11, 'Yuddha Kanda, Sarga 48, Verse 11', 'द्वारेषु यत्नः क्रियतां प्राकाराश्चाधिरुह्यताम्।
निद्रावशसमाविष्टः कुम्भकर्णो विबोध्यताम्॥', 'dvāreṣu yatnaḥ kriyatāṃ prākārāś cādhiruhyatām
nidrāvaśasamāviṣṭaḥ kumbhakarṇo vibodhyatām', null, 6048011),
('ramayana-6-48-12', 12, 'Yuddha Kanda, Sarga 48, Verse 12', 'नव षट्सप्त चाष्टौ च मासान्स्वपिति राक्षसः।
तं तु बोधयत क्षिप्रं कुम्भकर्णं महाबलम्॥', 'nava ṣaṭ sapta cāṣṭau ca māsān svapiti rākṣasaḥ
taṃ tu bodhayata kṣipraṃ kumbhakarṇaṃ mahābalam', null, 6048012),
('ramayana-6-48-13', 13, 'Yuddha Kanda, Sarga 48, Verse 13', 'स हि संख्ये महाबाहुः ककुदं सर्वरक्षसाम्।
वानरान्राजपुत्रौ च क्षिप्रमेव वधिष्यति॥', 'sa hi saṃkhye mahābāhuḥ kakudaṃ sarvarakṣasām
vānarān rājaputrau ca kṣipram eva vadhiṣyati', null, 6048013),
('ramayana-6-48-14', 14, 'Yuddha Kanda, Sarga 48, Verse 14', 'कुम्भकर्णः सदा शेते मूढो ग्राम्यसुखे रतः।
रामेणाभिनिरस्तस्य संग्रामोऽस्मिन्सुदारुणे॥', 'kumbhakarṇaḥ sadā śete mūḍho grāmyasukhe rataḥ
rāmeṇābhinirastasya saṃgrāmo ''smin sudāruṇe', null, 6048014),
('ramayana-6-48-15', 15, 'Yuddha Kanda, Sarga 48, Verse 15', 'भविष्यति न मे शोकः कुम्भकर्णे विबोधिते।
किं करिष्याम्यहं तेन शक्रतुल्यबलेन हि॥', 'bhaviṣyati na me śokaḥ kumbhakarṇe vibodhite
kiṃ kariṣyāmy ahaṃ tena śakratulyabalena hi', null, 6048015),
('ramayana-6-48-16', 16, 'Yuddha Kanda, Sarga 48, Verse 16', 'ईदृशे व्यसने प्राप्ते यो न साह्याय कल्पते।
ते तु तद्वचनं श्रुत्वा राक्षसेन्द्रस्य राक्षसाः॥', 'īdṛśe vyasane prāpte yo na sāhyāya kalpate
te tu tad vacanaṃ śrutvā rākṣasendrasya rākṣasāḥ', null, 6048016),
('ramayana-6-48-17', 17, 'Yuddha Kanda, Sarga 48, Verse 17', 'जग्मुः परमसंभ्रान्ताः कुम्भकर्णनिवेशनम्।
ते रावणसमादिष्टा मांसशोणितभोजनाः॥', 'jagmuḥ paramasaṃbhrāntāḥ kumbhakarṇaniveśanam
te rāvaṇasamādiṣṭā māṃsaśoṇitabhojanāḥ', null, 6048017),
('ramayana-6-48-18', 18, 'Yuddha Kanda, Sarga 48, Verse 18', 'गन्धमाल्यांस्तथा भक्ष्यानादाय सहसा ययुः।
तां प्रविश्य महाद्वारां सर्वतो योजनायताम्॥', 'gandhamālyāṃs tathā bhakṣyān ādāya sahasā yayuḥ
tāṃ praviśya mahādvārāṃ sarvato yojanāyatām', null, 6048018),
('ramayana-6-48-19', 19, 'Yuddha Kanda, Sarga 48, Verse 19', 'कुम्भकर्णगुहां रम्यां सर्वगन्धप्रवाहिनीम्।
प्रतिष्ठमानाः कृच्छ्रेण यत्नात्प्रविविशुर्गुहाम्॥', 'kumbhakarṇaguhāṃ ramyāṃ sarvagandhapravāhinīm
pratiṣṭhamānāḥ kṛcchreṇa yatnāt praviviśur guhām', null, 6048019),
('ramayana-6-48-20', 20, 'Yuddha Kanda, Sarga 48, Verse 20', 'तां प्रविश्य गुहां रम्यां शुभां काञ्चनकुट्टिमाम्।
ददृशुर्नैरृतव्याघ्रं शयानं भीमदर्शनम्॥', 'tāṃ praviśya guhāṃ ramyāṃ śubhāṃ kāñcanakuṭṭimām
dadṛśur nairṛtavyāghraṃ śayānaṃ bhīmadarśanam', null, 6048020),
('ramayana-6-48-21', 21, 'Yuddha Kanda, Sarga 48, Verse 21', 'ते तु तं विकृतं सुप्तं विकीर्णमिव पर्वतम्।
कुम्भकर्णं महानिद्रं सहिताः प्रत्यबोधयन्॥', 'te tu taṃ vikṛtaṃ suptaṃ vikīrṇam iva parvatam
kumbhakarṇaṃ mahānidraṃ sahitāḥ pratyabodhayan', null, 6048021),
('ramayana-6-48-22', 22, 'Yuddha Kanda, Sarga 48, Verse 22', 'ऊर्ध्वरोमाञ्चिततनुं श्वसन्तमिव पन्नगम्।
त्रासयन्तं महाश्वासैः शयानं भीमदर्शनम्॥', 'ūrdhvaromāñcitatanuṃ śvasantam iva pannagam
trāsayantaṃ mahāśvāsaiḥ śayānaṃ bhīmadarśanam', null, 6048022),
('ramayana-6-48-23', 23, 'Yuddha Kanda, Sarga 48, Verse 23', 'भीमनासापुटं तं तु पातालविपुलाननम्।
ददृशुर्नैरृतव्याघ्रं कुम्भकर्णं महाबलम्॥', 'bhīmanāsāpuṭaṃ taṃ tu pātālavipulānanam
dadṛśur nairṛtavyāghraṃ kumbhakarṇaṃ mahābalam', null, 6048023),
('ramayana-6-48-24', 24, 'Yuddha Kanda, Sarga 48, Verse 24', 'ततश्चक्रुर्महात्मानः कुम्भकर्णाग्रतस्तदा।
मांसानां मेरुसंकाशं राशिं परमतर्पणम्॥', 'tataś cakrur mahātmānaḥ kumbhakarṇāgratas tadā
māṃsānāṃ merusaṃkāśaṃ rāśiṃ paramatarpaṇam', null, 6048024),
('ramayana-6-48-25', 25, 'Yuddha Kanda, Sarga 48, Verse 25', 'मृगाणां महिषाणां च वराहाणां च संचयान्।
चक्रुर्नैरृतशार्दूला राशिमन्नस्य चाद्भुतम्॥', 'mṛgāṇāṃ mahiṣāṇāṃ ca varāhāṇāṃ ca saṃcayān
cakrur nairṛtaśārdūlā rāśimann asya cādbhutam', null, 6048025),
('ramayana-6-48-26', 26, 'Yuddha Kanda, Sarga 48, Verse 26', 'ततः शोणितकुम्भांश्च मद्यानि विविधानि च।
पुरस्तात्कुम्भकर्णस्य चक्रुस्त्रिदशशत्रवः॥', 'tataḥ śoṇitakumbhāṃś ca madyāni vividhāni ca
purastāt kumbhakarṇasya cakrus tridaśaśatravaḥ', null, 6048026),
('ramayana-6-48-27', 27, 'Yuddha Kanda, Sarga 48, Verse 27', 'लिलिपुश्च परार्ध्येन चन्दनेन परंतपम्।
दिव्यैराच्छादयामासुर्माल्यैर्गन्धैः सुगन्धिभिः॥', 'lilipuś ca parārdhyena candanena paraṃtapam
divyair ācchādayām āsur mālyair gandhaiḥ sugandhibhiḥ', null, 6048027),
('ramayana-6-48-28', 28, 'Yuddha Kanda, Sarga 48, Verse 28', 'धूपं सुगन्धं ससृजुस्तुष्टुवुश्च परंतपम्।
जलदा इव चोनेदुर्यातुधानाः सहस्रशः॥', 'dhūpaṃ sugandhaṃ sasṛjus tuṣṭuvuś ca paraṃtapam
jaladā iva conedur yātudhānāḥ sahasraśaḥ', null, 6048028),
('ramayana-6-48-29', 29, 'Yuddha Kanda, Sarga 48, Verse 29', 'शङ्खानापूरयामासुः शशाङ्कसदृशप्रभान्।
तुमुलं युगपच्चापि विनेदुश्चाप्यमर्षिताः॥', 'śaṅkhān āpūrayām āsuḥ śaśāṅkasadṛśaprabhān
tumulaṃ yugapac cāpi vineduś cāpy amarṣitāḥ', null, 6048029),
('ramayana-6-48-30', 30, 'Yuddha Kanda, Sarga 48, Verse 30', 'नेदुरास्फोटयामासुश्चिक्षिपुस्ते निशाचराः।
कुम्भकर्णविबोधार्थं चक्रुस्ते विपुलं स्वनम्॥', 'nedur āsphoṭayām āsuś cikṣipus te niśācarāḥ
kumbhakarṇavibodhārthaṃ cakrus te vipulaṃ svanam', null, 6048030),
('ramayana-6-48-31', 31, 'Yuddha Kanda, Sarga 48, Verse 31', 'सशङ्खभेरीपटहप्रणादमास्फोटितक्ष्वेडितसिंहनादम्।
दिशो द्रवन्तस्त्रिदिवं किरन्तः श्रुत्वा विहंगाः सहसा निपेतुः॥', 'saśaṅkhabherīpaṭahapraṇādam āsphoṭitakṣveḍitasiṃhanādam
diśo dravantas tridivaṃ kirantaḥ śrutvā vihaṃgāḥ sahasā nipetuḥ', null, 6048031),
('ramayana-6-48-32', 32, 'Yuddha Kanda, Sarga 48, Verse 32', 'यदा भृशं तैर्निनदैर्महात्मा न कुम्भकर्णो बुबुधे प्रसुप्तः।
ततो मुसुण्डीमुसलानि सर्वे रक्षोगणास्ते जगृहुर्गदाश्च॥', 'yadā bhṛśaṃ tair ninadair mahātmā na kumbhakarṇo bubudhe prasuptaḥ
tato musuṇḍīmusalāni sarve rakṣogaṇās te jagṛhur gadāś ca', null, 6048032),
('ramayana-6-48-33', 33, 'Yuddha Kanda, Sarga 48, Verse 33', 'तं शैलशृङ्गैर्मुसलैर्गदाभिर्वृक्षैस्तलैर्मुद्गरमुष्टिभिश्च।
सुखप्रसुप्तं भुवि कुम्भकर्णं रक्षांस्युदग्राणि तदा निजघ्नुः॥', 'taṃ śailaśṛṅgair musalair gadābhir vṛkṣais talair mudgaramuṣṭibhiś ca
sukhaprasuptaṃ bhuvi kumbhakarṇaṃ rakṣāṃsy udagrāṇi tadā nijaghnuḥ', null, 6048033),
('ramayana-6-48-34', 34, 'Yuddha Kanda, Sarga 48, Verse 34', 'तस्य निश्वासवातेन कुम्भकर्णस्य रक्षसः।
राक्षसा बलवन्तोऽपि स्थातुं नाशक्नुवन्पुरः॥', 'tasya niśvāsavātena kumbhakarṇasya rakṣasaḥ
rākṣasā balavanto ''pi sthātuṃ nāśaknuvan puraḥ', null, 6048034),
('ramayana-6-48-35', 35, 'Yuddha Kanda, Sarga 48, Verse 35', 'ततोऽस्य पुरतो गाढं राक्षसा भीमविक्रमाः।
मृदङ्गपणवान्भेरीः शङ्खकुम्भगणांस्तथा।
दशराक्षससाहस्रं युगपत्पर्यवादयन्॥', 'tato ''sya purato gāḍhaṃ rākṣasā bhīmavikramāḥ
mṛdaṅgapaṇavān bherīḥ śaṅkhakumbhagaṇāṃs tathā
daśarākṣasasāhasraṃ yugapat paryavādayan', null, 6048035),
('ramayana-6-48-36', 36, 'Yuddha Kanda, Sarga 48, Verse 36', 'नीलाञ्जनचयाकारं ते तु तं प्रत्यबोधयन्।
अभिघ्नन्तो नदन्तश्च नैव संविविदे तु सः॥', 'nīlāñjanacayākāraṃ te tu taṃ pratyabodhayan
abhighnanto nadantaś ca naiva saṃvivide tu saḥ', null, 6048036),
('ramayana-6-48-37', 37, 'Yuddha Kanda, Sarga 48, Verse 37', 'यदा चैनं न शेकुस्ते प्रतिबोधयितुं तदा।
ततो गुरुतरं यत्नं दारुणं समुपाक्रमन्॥', 'yadā cainaṃ na śekus te pratibodhayituṃ tadā
tato gurutaraṃ yatnaṃ dāruṇaṃ samupākraman', null, 6048037),
('ramayana-6-48-38', 38, 'Yuddha Kanda, Sarga 48, Verse 38', 'अश्वानुष्ट्रान्खरान्नागाञ्जघ्नुर्दण्डकशाङ्कुशैः।
भेरीशङ्खमृदङ्गांश्च सर्वप्राणैरवादयन्॥', 'aśvān uṣṭrān kharān nāgāñ jaghnur daṇḍakaśāṅkuśaiḥ
bherīśaṅkhamṛdaṅgāṃś ca sarvaprāṇair avādayan', null, 6048038),
('ramayana-6-48-39', 39, 'Yuddha Kanda, Sarga 48, Verse 39', 'निजघ्नुश्चास्य गात्राणि महाकाष्ठकटं करैः।
मुद्गरैर्मुसलैश्चैव सर्वप्राणसमुद्यतैः॥', 'nijaghnuś cāsya gātrāṇi mahākāṣṭhakaṭaṃ karaiḥ
mudgarair musalaiś caiva sarvaprāṇasamudyataiḥ', null, 6048039),
('ramayana-6-48-40', 40, 'Yuddha Kanda, Sarga 48, Verse 40', 'तेन शब्देन महता लङ्का समभिपूरिता।
सपर्वतवना सर्वा सोऽपि नैव प्रबुध्यते॥', 'tena śabdena mahatā laṅkā samabhipūritā
saparvatavanā sarvā so ''pi naiva prabudhyate', null, 6048040),
('ramayana-6-48-41', 41, 'Yuddha Kanda, Sarga 48, Verse 41', 'ततः सहस्रं भेरीणां युगपत्समहन्यत।
मृष्टकाञ्चनकोणानामसक्तानां समन्ततः॥', 'tataḥ sahasraṃ bherīṇāṃ yugapat samahanyata
mṛṣṭakāñcanakoṇānām asaktānāṃ samantataḥ', null, 6048041),
('ramayana-6-48-42', 42, 'Yuddha Kanda, Sarga 48, Verse 42', 'एवमप्यतिनिद्रस्तु यदा नैव प्रबुध्यत।
शापस्य वशमापन्नस्ततः क्रुद्धा निशाचराः॥', 'evam apy atinidras tu yadā naiva prabudhyata
śāpasya vaśam āpannas tataḥ kruddhā niśācarāḥ', null, 6048042),
('ramayana-6-48-43', 43, 'Yuddha Kanda, Sarga 48, Verse 43', 'महाक्रोधसमाविष्टाः सर्वे भीमपराक्रमाः।
तद्रक्षोबोधयिष्यन्तश्चक्रुरन्ये पराक्रमम्॥', 'mahākrodhasamāviṣṭāḥ sarve bhīmaparākramāḥ
tad rakṣobodhayiṣyantaś cakrur anye parākramam', null, 6048043),
('ramayana-6-48-44', 44, 'Yuddha Kanda, Sarga 48, Verse 44', 'अन्ये भेरीः समाजघ्नुरन्ये चक्रुर्महास्वनम्।
केशानन्ये प्रलुलुपुः कर्णावन्ये दशन्ति च।
न कुम्भकर्णः पस्पन्दे महानिद्रावशं गतः॥', 'anye bherīḥ samājaghnur anye cakrur mahāsvanam
keśān anye pralulupuḥ karṇāv anye daśanti ca
na kumbhakarṇaḥ paspande mahānidrāvaśaṃ gataḥ', null, 6048044),
('ramayana-6-48-45', 45, 'Yuddha Kanda, Sarga 48, Verse 45', 'अन्ये च बलिनस्तस्य कूटमुद्गरपाणयः।
मूर्ध्नि वक्षसि गात्रेषु पातयन्कूटमुद्गरान्॥', 'anye ca balinas tasya kūṭamudgarapāṇayaḥ
mūrdhni vakṣasi gātreṣu pātayan kūṭamudgarān', null, 6048045),
('ramayana-6-48-46', 46, 'Yuddha Kanda, Sarga 48, Verse 46', 'रज्जुबन्धनबद्धाभिः शतघ्नीभिश्च सर्वतः।
वध्यमानो महाकायो न प्राबुध्यत राक्षसः॥', 'rajjubandhanabaddhābhiḥ śataghnībhiś ca sarvataḥ
vadhyamāno mahākāyo na prābudhyata rākṣasaḥ', null, 6048046),
('ramayana-6-48-47', 47, 'Yuddha Kanda, Sarga 48, Verse 47', 'वारणानां सहस्रं तु शरीरेऽस्य प्रधावितम्।
कुम्भकर्णस्ततो बुद्धः स्पर्शं परमबुध्यत॥', 'vāraṇānāṃ sahasraṃ tu śarīre ''sya pradhāvitam
kumbhakarṇas tato buddhaḥ sparśaṃ param abudhyata', null, 6048047),
('ramayana-6-48-48', 48, 'Yuddha Kanda, Sarga 48, Verse 48', 'स पात्यमानैर्गिरिशृङ्गवृक्षैरचिन्तयंस्तान्विपुलान्प्रहारान्।
निद्राक्षयात्क्षुद्भयपीडितश्च विजृम्भमाणः सहसोत्पपात॥', 'sa pātyamānair giriśṛṅgavṛkṣair acintayaṃs tān vipulān prahārān
nidrākṣayāt kṣudbhayapīḍitaś ca vijṛmbhamāṇaḥ sahasotpapāta', null, 6048048),
('ramayana-6-48-49', 49, 'Yuddha Kanda, Sarga 48, Verse 49', 'स नागभोगाचलशृङ्गकल्पौ विक्षिप्य बाहू गिरिशृङ्गसारौ।
विवृत्य वक्त्रं वडवामुखाभं निशाचरोऽसौ विकृतं जजृम्भे॥', 'sa nāgabhogācalaśṛṅgakalpau vikṣipya bāhū giriśṛṅgasārau
vivṛtya vaktraṃ vaḍavāmukhābhaṃ niśācaro ''sau vikṛtaṃ jajṛmbhe', null, 6048049),
('ramayana-6-48-50', 50, 'Yuddha Kanda, Sarga 48, Verse 50', 'तस्य जाजृम्भमाणस्य वक्त्रं पातालसंनिभम्।
ददृशे मेरुशृङ्गाग्रे दिवाकर इवोदितः॥', 'tasya jājṛmbhamāṇasya vaktraṃ pātālasaṃnibham
dadṛśe meruśṛṅgāgre divākara ivoditaḥ', null, 6048050),
('ramayana-6-48-51', 51, 'Yuddha Kanda, Sarga 48, Verse 51', 'विजृम्भमाणोऽतिबलः प्रतिबुद्धो निशाचरः।
निश्वासश्चास्य संजज्ञे पर्वतादिव मारुतः॥', 'vijṛmbhamāṇo ''tibalaḥ pratibuddho niśācaraḥ
niśvāsaś cāsya saṃjajñe parvatād iva mārutaḥ', null, 6048051),
('ramayana-6-48-52', 52, 'Yuddha Kanda, Sarga 48, Verse 52', 'रूपमुत्तिष्ठतस्तस्य कुम्भकर्णस्य तद्बभौ।
तपान्ते सबलाकस्य मेघस्येव विवर्षतः॥', 'rūpam uttiṣṭhatas tasya kumbhakarṇasya tad babhau
tapānte sabalākasya meghasyeva vivarṣataḥ', null, 6048052),
('ramayana-6-48-53', 53, 'Yuddha Kanda, Sarga 48, Verse 53', 'तस्य दीप्ताग्निसदृशे विद्युत्सदृशवर्चसी।
ददृशाते महानेत्रे दीप्ताविव महाग्रहौ॥', 'tasya dīptāgnisadṛśe vidyutsadṛśavarcasī
dadṛśāte mahānetre dīptāv iva mahāgrahau', null, 6048053),
('ramayana-6-48-54', 54, 'Yuddha Kanda, Sarga 48, Verse 54', 'आदद्बुभुक्षितो मांसं शोणितं तृषितोऽपिबत्।
मेदः कुम्भं च मद्यं च पपौ शक्ररिपुस्तदा॥', 'ādad bubhukṣito māṃsaṃ śoṇitaṃ tṛṣito ''pibat
medaḥ kumbhaṃ ca madyaṃ ca papau śakraripus tadā', null, 6048054),
('ramayana-6-48-55', 55, 'Yuddha Kanda, Sarga 48, Verse 55', 'ततस्तृप्त इति ज्ञात्वा समुत्पेतुर्निशाचराः।
शिरोभिश्च प्रणम्यैनं सर्वतः पर्यवारयन्॥', 'tatas tṛpta iti jñātvā samutpetur niśācarāḥ
śirobhiś ca praṇamyainaṃ sarvataḥ paryavārayan', null, 6048055),
('ramayana-6-48-56', 56, 'Yuddha Kanda, Sarga 48, Verse 56', 'स सर्वान्सान्त्वयामास नैरृतान्नैरृतर्षभः।
बोधनाद्विस्मितश्चापि राक्षसानिदमब्रवीत्॥', 'sa sarvān sāntvayām āsa nairṛtān nairṛtarṣabhaḥ
bodhanād vismitaś cāpi rākṣasān idam abravīt', null, 6048056),
('ramayana-6-48-57', 57, 'Yuddha Kanda, Sarga 48, Verse 57', 'किमर्थमहमाहत्य भवद्भिः प्रतिबोधितः।
कच्चित्सुकुशलं राज्ञो भयं वा नेह किं चन॥', 'kimartham aham āhatya bhavadbhiḥ pratibodhitaḥ
kaccit sukuśalaṃ rājño bhayaṃ vā neha kiṃ cana', null, 6048057),
('ramayana-6-48-58', 58, 'Yuddha Kanda, Sarga 48, Verse 58', 'अथ वा ध्रुवमन्येभ्यो भयं परमुपस्थितम्।
यदर्थमेव त्वरितैर्भवद्भिः प्रतिबोधितः॥', 'atha vā dhruvam anyebhyo bhayaṃ param upasthitam
yadartham eva tvaritair bhavadbhiḥ pratibodhitaḥ', null, 6048058),
('ramayana-6-48-59', 59, 'Yuddha Kanda, Sarga 48, Verse 59', 'अद्य राक्षसराजस्य भयमुत्पाटयाम्यहम्।
पातयिष्ये महेन्द्रं वा शातयिष्ये तथानलम्॥', 'adya rākṣasarājasya bhayam utpāṭayāmy aham
pātayiṣye mahendraṃ vā śātayiṣye tathānalam', null, 6048059),
('ramayana-6-48-60', 60, 'Yuddha Kanda, Sarga 48, Verse 60', 'न ह्यल्पकारणे सुप्तं बोधयिष्यति मां भृशम्।
तदाख्यातार्थतत्त्वेन मत्प्रबोधनकारणम्॥', 'na hy alpakāraṇe suptaṃ bodhayiṣyati māṃ bhṛśam
tad ākhyātārthatattvena matprabodhanakāraṇam', null, 6048060),
('ramayana-6-48-61', 61, 'Yuddha Kanda, Sarga 48, Verse 61', 'एवं ब्रुवाणं संरब्धं कुम्भकर्णमरिंदमम्।
यूपाक्षः सचिवो राज्ञः कृताञ्जलिरुवाच ह॥', 'evaṃ bruvāṇaṃ saṃrabdhaṃ kumbhakarṇam ariṃdamam
yūpākṣaḥ sacivo rājñaḥ kṛtāñjalir uvāca ha', null, 6048061),
('ramayana-6-48-62', 62, 'Yuddha Kanda, Sarga 48, Verse 62', 'न नो देवकृतं किं चिद्भयमस्ति कदा चन।
न दैत्यदानवेभ्यो वा भयमस्ति हि तादृशम्।
यादृशं मानुषं राजन्भयमस्मानुपस्थितम्॥', 'na no devakṛtaṃ kiṃ cid bhayam asti kadā cana
na daityadānavebhyo vā bhayam asti hi tādṛśam
yādṛśaṃ mānuṣaṃ rājan bhayam asmān upasthitam', null, 6048062),
('ramayana-6-48-63', 63, 'Yuddha Kanda, Sarga 48, Verse 63', 'वानरैः पर्वताकारैर्लङ्केयं परिवारिता।
सीताहरणसंतप्ताद्रामान्नस्तुमुलं भयम्॥', 'vānaraiḥ parvatākārair laṅkeyaṃ parivāritā
sītāharaṇasaṃtaptād rāmān nas tumulaṃ bhayam', null, 6048063),
('ramayana-6-48-64', 64, 'Yuddha Kanda, Sarga 48, Verse 64', 'एकेन वानरेणेयं पूर्वं दग्धा महापुरी।
कुमारो निहतश्चाक्षः सानुयात्रः सकुञ्जरः॥', 'ekena vānareṇeyaṃ pūrvaṃ dagdhā mahāpurī
kumāro nihataś cākṣaḥ sānuyātraḥ sakuñjaraḥ', null, 6048064),
('ramayana-6-48-65', 65, 'Yuddha Kanda, Sarga 48, Verse 65', 'स्वयं रक्षोऽधिपश्चापि पौलस्त्यो देवकण्टकः।
मृतेति संयुगे मुक्तारामेणादित्यतेजसा॥', 'svayaṃ rakṣo''dhipaś cāpi paulastyo devakaṇṭakaḥ
mṛteti saṃyuge muktārāmeṇādityatejasā', null, 6048065),
('ramayana-6-48-66', 66, 'Yuddha Kanda, Sarga 48, Verse 66', 'यन्न देवैः कृतो राजा नापि दैत्यैर्न दानवैः।
कृतः स इह रामेण विमुक्तः प्राणसंशयात्॥', 'yan na devaiḥ kṛto rājā nāpi daityair na dānavaiḥ
kṛtaḥ sa iha rāmeṇa vimuktaḥ prāṇasaṃśayāt', null, 6048066),
('ramayana-6-48-67', 67, 'Yuddha Kanda, Sarga 48, Verse 67', 'स यूपाक्षवचः श्रुत्वा भ्रातुर्युधि पराजयम्।
कुम्भकर्णो विवृत्ताक्षो यूपाक्षमिदमब्रवीत्॥', 'sa yūpākṣavacaḥ śrutvā bhrātur yudhi parājayam
kumbhakarṇo vivṛttākṣo yūpākṣam idam abravīt', null, 6048067),
('ramayana-6-48-68', 68, 'Yuddha Kanda, Sarga 48, Verse 68', 'सर्वमद्यैव यूपाक्ष हरिसैन्यं सलक्ष्मणम्।
राघवं च रणे हत्वा पश्चाद्द्रक्ष्यामि रावणम्॥', 'sarvam adyaiva yūpākṣa harisainyaṃ salakṣmaṇam
rāghavaṃ ca raṇe hatvā paścād drakṣyāmi rāvaṇam', null, 6048068),
('ramayana-6-48-69', 69, 'Yuddha Kanda, Sarga 48, Verse 69', 'राक्षसांस्तर्पयिष्यामि हरीणां मांसशोणितैः।
रामलक्ष्मणयोश्चापि स्वयं पास्यामि शोणितम्॥', 'rākṣasāṃs tarpayiṣyāmi harīṇāṃ māṃsaśoṇitaiḥ
rāmalakṣmaṇayoś cāpi svayaṃ pāsyāmi śoṇitam', null, 6048069),
('ramayana-6-48-70', 70, 'Yuddha Kanda, Sarga 48, Verse 70', 'तत्तस्य वाक्यं ब्रुवतो निशम्य सगर्वितं रोषविवृद्धदोषम्।
महोदरो नैरृतयोधमुख्यः कृताञ्जलिर्वाक्यमिदं बभाषे॥', 'tat tasya vākyaṃ bruvato niśamya sagarvitaṃ roṣavivṛddhadoṣam
mahodaro nairṛtayodhamukhyaḥ kṛtāñjalir vākyam idaṃ babhāṣe', null, 6048070),
('ramayana-6-48-71', 71, 'Yuddha Kanda, Sarga 48, Verse 71', 'रावणस्य वचः श्रुत्वा गुणदोषु विमृश्य च।
पश्चादपि महाबाहो शत्रून्युधि विजेष्यसि॥', 'rāvaṇasya vacaḥ śrutvā guṇadoṣu vimṛśya ca
paścād api mahābāho śatrūn yudhi vijeṣyasi', null, 6048071),
('ramayana-6-48-72', 72, 'Yuddha Kanda, Sarga 48, Verse 72', 'महोदरवचः श्रुत्वा राक्षसैः परिवारितः।
कुम्भकर्णो महातेजाः संप्रतस्थे महाबलः॥', 'mahodaravacaḥ śrutvā rākṣasaiḥ parivāritaḥ
kumbhakarṇo mahātejāḥ saṃpratasthe mahābalaḥ', null, 6048072),
('ramayana-6-48-73', 73, 'Yuddha Kanda, Sarga 48, Verse 73', 'तं समुत्थाप्य भीमाक्षं भीमरूपपराक्रमम्।
राक्षसास्त्वरिता जग्मुर्दशग्रीवनिवेशनम्॥', 'taṃ samutthāpya bhīmākṣaṃ bhīmarūpaparākramam
rākṣasās tvaritā jagmur daśagrīvaniveśanam', null, 6048073),
('ramayana-6-48-74', 74, 'Yuddha Kanda, Sarga 48, Verse 74', 'ततो गत्वा दशग्रीवमासीनं परमासने।
ऊचुर्बद्धाञ्जलिपुटाः सर्व एव निशाचराः॥', 'tato gatvā daśagrīvam āsīnaṃ paramāsane
ūcur baddhāñjalipuṭāḥ sarva eva niśācarāḥ', null, 6048074),
('ramayana-6-48-75', 75, 'Yuddha Kanda, Sarga 48, Verse 75', 'प्रबुद्धः कुम्भकर्णोऽसौ भ्राता ते राक्षसर्षभ।
कथं तत्रैव निर्यातु द्रक्ष्यसे तमिहागतम्॥', 'prabuddhaḥ kumbhakarṇo ''sau bhrātā te rākṣasarṣabha
kathaṃ tatraiva niryātu drakṣyase tam ihāgatam', null, 6048075),
('ramayana-6-48-76', 76, 'Yuddha Kanda, Sarga 48, Verse 76', 'रावणस्त्वब्रवीद्धृष्टो यथान्यायं च पूजितम्।
द्रष्टुमेनमिहेच्छामि यथान्यायं च पूजितम्॥', 'rāvaṇas tv abravīd dhṛṣṭo yathānyāyaṃ ca pūjitam
draṣṭum enam ihecchāmi yathānyāyaṃ ca pūjitam', null, 6048076),
('ramayana-6-48-77', 77, 'Yuddha Kanda, Sarga 48, Verse 77', 'तथेत्युक्त्वा तु ते सर्वे पुनरागम्य राक्षसाः।
कुम्भकर्णमिदं वाक्यमूचू रावणचोदिताः॥', 'tathety uktvā tu te sarve punar āgamya rākṣasāḥ
kumbhakarṇam idaṃ vākyam ūcū rāvaṇacoditāḥ', null, 6048077),
('ramayana-6-48-78', 78, 'Yuddha Kanda, Sarga 48, Verse 78', 'द्रष्टुं त्वां काङ्क्षते राजा सर्वराक्षसपुंगवः।
गमने क्रियतां बुद्धिर्भ्रातरं संप्रहर्षय॥', 'draṣṭuṃ tvāṃ kāṅkṣate rājā sarvarākṣasapuṃgavaḥ
gamane kriyatāṃ buddhir bhrātaraṃ saṃpraharṣaya', null, 6048078),
('ramayana-6-48-79', 79, 'Yuddha Kanda, Sarga 48, Verse 79', 'कुम्भकर्णस्तु दुर्धर्षो भ्रातुराज्ञाय शासनम्।
तथेत्युक्त्वा महावीर्यः शयनादुत्पपात ह॥', 'kumbhakarṇas tu durdharṣo bhrātur ājñāya śāsanam
tathety uktvā mahāvīryaḥ śayanād utpapāta ha', null, 6048079),
('ramayana-6-48-80', 80, 'Yuddha Kanda, Sarga 48, Verse 80', 'प्रक्षाल्य वदनं हृष्टः स्नातः परमभूषितः।
पिपासुस्त्वरयामास पानं बलसमीरणम्॥', 'prakṣālya vadanaṃ hṛṣṭaḥ snātaḥ paramabhūṣitaḥ
pipāsus tvarayām āsa pānaṃ balasamīraṇam', null, 6048080),
('ramayana-6-48-81', 81, 'Yuddha Kanda, Sarga 48, Verse 81', 'ततस्ते त्वरितास्तस्य राज्षसा रावणाज्ञया।
मद्यं भक्ष्यांश्च विविधान्क्षिप्रमेवोपहारयन्॥', 'tatas te tvaritās tasya rājṣasā rāvaṇājñayā
madyaṃ bhakṣyāṃś ca vividhān kṣipram evopahārayan', null, 6048081),
('ramayana-6-48-82', 82, 'Yuddha Kanda, Sarga 48, Verse 82', 'पीत्वा घटसहस्रं स गमनायोपचक्रमे॥', 'pītvā ghaṭasahasraṃ sa gamanāyopacakrame', null, 6048082),
('ramayana-6-48-83', 83, 'Yuddha Kanda, Sarga 48, Verse 83', 'ईषत्समुत्कटो मत्तस्तेजोबलसमन्वितः।
कुम्भकर्णो बभौ हृष्टः कालान्तकयमोपमः॥', 'īṣatsamutkaṭo mattas tejobalasamanvitaḥ
kumbhakarṇo babhau hṛṣṭaḥ kālāntakayamopamaḥ', null, 6048083),
('ramayana-6-48-84', 84, 'Yuddha Kanda, Sarga 48, Verse 84', 'भ्रातुः स भवनं गच्छन्रक्षोबलसमन्वितः।
कुम्भकर्णः पदन्यासैरकम्पयत मेदिनीम्॥', 'bhrātuḥ sa bhavanaṃ gacchan rakṣobalasamanvitaḥ
kumbhakarṇaḥ padanyāsair akampayata medinīm', null, 6048084),
('ramayana-6-48-85', 85, 'Yuddha Kanda, Sarga 48, Verse 85', 'स राजमार्गं वपुषा प्रकाशयन्सहस्ररश्मिर्धरणीमिवांशुभिः।
जगाम तत्राञ्जलिमालया वृतः शतक्रतुर्गेहमिव स्वयम्भुवः॥', 'sa rājamārgaṃ vapuṣā prakāśayan sahasraraśmir dharaṇīm ivāṃśubhiḥ
jagāma tatrāñjalimālayā vṛtaḥ śatakratur geham iva svayambhuvaḥ', null, 6048085),
('ramayana-6-48-86', 86, 'Yuddha Kanda, Sarga 48, Verse 86', 'के चिच्छरण्यं शरणं स्म रामं व्रजन्ति के चिद्व्यथिताः पतन्ति।
के चिद्दिशः स्म व्यथिताः प्रयान्ति के चिद्भयार्ता भुवि शेरते स्म॥', 'ke cic charaṇyaṃ śaraṇaṃ sma rāmaṃ vrajanti ke cid vyathitāḥ patanti
ke cid diśaḥ sma vyathitāḥ prayānti ke cid bhayārtā bhuvi śerate sma', null, 6048086),
('ramayana-6-48-87', 87, 'Yuddha Kanda, Sarga 48, Verse 87', 'तमद्रिशृङ्गप्रतिमं किरीटिनं स्पृशन्तमादित्यमिवात्मतेजसा।
वनौकसः प्रेक्ष्य विवृद्धमद्भुतं भयार्दिता दुद्रुविरे ततस्ततः॥', 'tam adriśṛṅgapratimaṃ kirīṭinaṃ spṛśantam ādityam ivātmatejasā
vanaukasaḥ prekṣya vivṛddham adbhutaṃ bhayārditā dudruvire tatas tataḥ', null, 6048087)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 49 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-49-1', 1, 'Yuddha Kanda, Sarga 49, Verse 1', 'ततो रामो महातेजा धनुरादाय वीर्यवान्।
किरीटिनं महाकायं कुम्भकर्णं ददर्श ह॥', 'tato rāmo mahātejā dhanur ādāya vīryavān
kirīṭinaṃ mahākāyaṃ kumbhakarṇaṃ dadarśa ha', null, 6049001),
('ramayana-6-49-2', 2, 'Yuddha Kanda, Sarga 49, Verse 2', 'तं दृष्ट्वा राक्षसश्रेष्ठं पर्वताकारदर्शनम्।
क्रममाणमिवाकाशं पुरा नारायणं प्रभुम्॥', 'taṃ dṛṣṭvā rākṣasaśreṣṭhaṃ parvatākāradarśanam
kramamāṇam ivākāśaṃ purā nārāyaṇaṃ prabhum', null, 6049002),
('ramayana-6-49-3', 3, 'Yuddha Kanda, Sarga 49, Verse 3', 'सतोयाम्बुदसंकाशं काञ्चनाङ्गदभूषणम्।
दृष्ट्वा पुनः प्रदुद्राव वानराणां महाचमूः॥', 'satoyāmbudasaṃkāśaṃ kāñcanāṅgadabhūṣaṇam
dṛṣṭvā punaḥ pradudrāva vānarāṇāṃ mahācamūḥ', null, 6049003),
('ramayana-6-49-4', 4, 'Yuddha Kanda, Sarga 49, Verse 4', 'विद्रुतां वाहिनीं दृष्ट्वा वर्धमानं च राक्षसं।
सविस्मयमिदं रामो विभीषणमुवाच ह॥', 'vidrutāṃ vāhinīṃ dṛṣṭvā vardhamānaṃ ca rākṣasaṃ
savismayam idaṃ rāmo vibhīṣaṇam uvāca ha', null, 6049004),
('ramayana-6-49-5', 5, 'Yuddha Kanda, Sarga 49, Verse 5', 'कोऽसौ पर्वतसंकशः किरीटी हरिलोचनः।
लङ्कायां दृश्यते वीरः सविद्युदिव तोयदः॥', 'ko ''sau parvatasaṃkaśaḥ kirīṭī harilocanaḥ
laṅkāyāṃ dṛśyate vīraḥ savidyud iva toyadaḥ', null, 6049005),
('ramayana-6-49-6', 6, 'Yuddha Kanda, Sarga 49, Verse 6', 'पृथिव्याः केतुभूतोऽसौ महानेकोऽत्र दृश्यते।
यं दृष्ट्वा वानराः सर्वे विद्रवन्ति ततस्ततः॥', 'pṛthivyāḥ ketubhūto ''sau mahān eko ''tra dṛśyate
yaṃ dṛṣṭvā vānarāḥ sarve vidravanti tatas tataḥ', null, 6049006),
('ramayana-6-49-7', 7, 'Yuddha Kanda, Sarga 49, Verse 7', 'आचक्ष्व मे महान्कोऽसौ रक्षो वा यदि वासुरः।
न मयैवंविधं भूतं दृष्टपूर्वं कदा चन॥', 'ācakṣva me mahān ko ''sau rakṣo vā yadi vāsuraḥ
na mayaivaṃvidhaṃ bhūtaṃ dṛṣṭapūrvaṃ kadā cana', null, 6049007),
('ramayana-6-49-8', 8, 'Yuddha Kanda, Sarga 49, Verse 8', 'स पृष्टो राजपुत्रेण रामेणाक्लिष्टकारिणा।
विभीषणो महाप्राज्ञः काकुत्स्थमिदमब्रवीत्॥', 'sa pṛṣṭo rājaputreṇa rāmeṇākliṣṭakāriṇā
vibhīṣaṇo mahāprājñaḥ kākutstham idam abravīt', null, 6049008),
('ramayana-6-49-9', 9, 'Yuddha Kanda, Sarga 49, Verse 9', 'येन वैवस्वतो युद्धे वासवश्च पराजितः।
सैष विश्रवसः पुत्रः कुम्भकर्णः प्रतापवान्॥', 'yena vaivasvato yuddhe vāsavaś ca parājitaḥ
saiṣa viśravasaḥ putraḥ kumbhakarṇaḥ pratāpavān', null, 6049009),
('ramayana-6-49-10', 10, 'Yuddha Kanda, Sarga 49, Verse 10', 'एतेन देवा युधि दानवाश्च यक्षा भुजंगाः पिशिताशनाश्च।
गन्धर्वविद्याधरकिंनराश्च सहस्रशो राघव संप्रभग्नाः॥', 'etena devā yudhi dānavāś ca yakṣā bhujaṃgāḥ piśitāśanāś ca
gandharvavidyādharakiṃnarāś ca sahasraśo rāghava saṃprabhagnāḥ', null, 6049010),
('ramayana-6-49-11', 11, 'Yuddha Kanda, Sarga 49, Verse 11', 'शूलपाणिं विरूपाक्षं कुम्भकर्णं महाबलम्।
हन्तुं न शेकुस्त्रिदशाः कालोऽयमिति मोहिताः॥', 'śūlapāṇiṃ virūpākṣaṃ kumbhakarṇaṃ mahābalam
hantuṃ na śekus tridaśāḥ kālo ''yam iti mohitāḥ', null, 6049011),
('ramayana-6-49-12', 12, 'Yuddha Kanda, Sarga 49, Verse 12', 'प्रकृत्या ह्येष तेजस्वी कुम्भकर्णो महाबलः।
अन्येषां राक्षसेन्द्राणां वरदानकृतं बलम्॥', 'prakṛtyā hy eṣa tejasvī kumbhakarṇo mahābalaḥ
anyeṣāṃ rākṣasendrāṇāṃ varadānakṛtaṃ balam', null, 6049012),
('ramayana-6-49-13', 13, 'Yuddha Kanda, Sarga 49, Verse 13', 'एतेन जातमात्रेण क्षुधार्तेन महात्मना।
भक्षितानि सहस्राणि सत्त्वानां सुबहून्यपि॥', 'etena jātamātreṇa kṣudhārtena mahātmanā
bhakṣitāni sahasrāṇi sattvānāṃ subahūny api', null, 6049013),
('ramayana-6-49-14', 14, 'Yuddha Kanda, Sarga 49, Verse 14', 'तेषु संभक्ष्यमाणेषु प्रजा भयनिपीडिताः।
यान्ति स्म शरणं शक्रं तमप्यर्थं न्यवेदयन्॥', 'teṣu saṃbhakṣyamāṇeṣu prajā bhayanipīḍitāḥ
yānti sma śaraṇaṃ śakraṃ tam apy arthaṃ nyavedayan', null, 6049014),
('ramayana-6-49-15', 15, 'Yuddha Kanda, Sarga 49, Verse 15', 'स कुम्भकर्णं कुपितो महेन्द्रो जघान वज्रेण शितेन वज्री।
स शक्रवज्राभिहतो महात्मा चचाल कोपाच्च भृशं ननाद॥', 'sa kumbhakarṇaṃ kupito mahendro jaghāna vajreṇa śitena vajrī
sa śakravajrābhihato mahātmā cacāla kopāc ca bhṛśaṃ nanāda', null, 6049015),
('ramayana-6-49-16', 16, 'Yuddha Kanda, Sarga 49, Verse 16', 'तस्य नानद्यमानस्य कुम्भकर्णस्य धीमतः।
श्रुत्वा निनादं वित्रस्ता भूयो भूमिर्वितत्रसे॥', 'tasya nānadyamānasya kumbhakarṇasya dhīmataḥ
śrutvā ninādaṃ vitrastā bhūyo bhūmir vitatrase', null, 6049016),
('ramayana-6-49-17', 17, 'Yuddha Kanda, Sarga 49, Verse 17', 'ततः कोपान्महेन्द्रस्य कुम्भकर्णो महाबलः।
विकृष्यैरावताद्दन्तं जघानोरसि वासवम्॥', 'tataḥ kopān mahendrasya kumbhakarṇo mahābalaḥ
vikṛṣyairāvatād dantaṃ jaghānorasi vāsavam', null, 6049017),
('ramayana-6-49-18', 18, 'Yuddha Kanda, Sarga 49, Verse 18', 'कुम्भकर्णप्रहारार्तो विचचाल स वासवः।
ततो विषेदुः सहसा देवब्रह्मर्षिदानवाः॥', 'kumbhakarṇaprahārārto vicacāla sa vāsavaḥ
tato viṣeduḥ sahasā devabrahmarṣidānavāḥ', null, 6049018),
('ramayana-6-49-19', 19, 'Yuddha Kanda, Sarga 49, Verse 19', 'प्रजाभिः सह शक्रश्च ययौ स्थानं स्वयम्भुवः।
कुम्भकर्णस्य दौरात्म्यं शशंसुस्ते प्रजापतेः।
प्रजानां भक्षणं चापि देवानां चापि धर्षणम्॥', 'prajābhiḥ saha śakraś ca yayau sthānaṃ svayambhuvaḥ
kumbhakarṇasya daurātmyaṃ śaśaṃsus te prajāpateḥ
prajānāṃ bhakṣaṇaṃ cāpi devānāṃ cāpi dharṣaṇam', null, 6049019),
('ramayana-6-49-20', 20, 'Yuddha Kanda, Sarga 49, Verse 20', 'एवं प्रजा यदि त्वेष भक्षयिष्यति नित्यशः।
अचिरेणैव कालेन शून्यो लोको भविष्यति॥', 'evaṃ prajā yadi tv eṣa bhakṣayiṣyati nityaśaḥ
acireṇaiva kālena śūnyo loko bhaviṣyati', null, 6049020),
('ramayana-6-49-21', 21, 'Yuddha Kanda, Sarga 49, Verse 21', 'वासवस्य वचः श्रुत्वा सर्वलोकपितामहः।
रक्षांस्यावाहयामास कुम्भकर्णं ददर्श ह॥', 'vāsavasya vacaḥ śrutvā sarvalokapitāmahaḥ
rakṣāṃsy āvāhayām āsa kumbhakarṇaṃ dadarśa ha', null, 6049021),
('ramayana-6-49-22', 22, 'Yuddha Kanda, Sarga 49, Verse 22', 'कुम्भकर्णं समीक्ष्यैव वितत्रास प्रजापतिः।
दृष्ट्वा निश्वस्य चैवेदं स्वयम्भूरिदमब्रवीत्॥', 'kumbhakarṇaṃ samīkṣyaiva vitatrāsa prajāpatiḥ
dṛṣṭvā niśvasya caivedaṃ svayambhūr idam abravīt', null, 6049022),
('ramayana-6-49-23', 23, 'Yuddha Kanda, Sarga 49, Verse 23', 'ध्रुवं लोकविनाशाय पौरस्त्येनासि निर्मितः।
तस्मात्त्वमद्य प्रभृति मृतकल्पः शयिष्यसि।
ब्रह्मशापाभिभूतोऽथ निपपाताग्रतः प्रभोः॥', 'dhruvaṃ lokavināśāya paurastyenāsi nirmitaḥ
tasmāt tvam adya prabhṛti mṛtakalpaḥ śayiṣyasi
brahmaśāpābhibhūto ''tha nipapātāgrataḥ prabhoḥ', null, 6049023),
('ramayana-6-49-24', 24, 'Yuddha Kanda, Sarga 49, Verse 24', 'ततः परमसंभ्रान्तो रावणो वाक्यमब्रवीत्।
विवृद्धः काञ्चनो वृक्षः फलकाले निकृत्यते॥', 'tataḥ paramasaṃbhrānto rāvaṇo vākyam abravīt
vivṛddhaḥ kāñcano vṛkṣaḥ phalakāle nikṛtyate', null, 6049024),
('ramayana-6-49-25', 25, 'Yuddha Kanda, Sarga 49, Verse 25', 'न नप्तारं स्वकं न्याय्यं शप्तुमेवं प्रजापते।
न मिथ्यावचनश्च त्वं स्वप्स्यत्येष न संशयः।
कालस्तु क्रियतामस्य शयने जागरे तथा॥', 'na naptāraṃ svakaṃ nyāyyaṃ śaptum evaṃ prajāpate
na mithyāvacanaś ca tvaṃ svapsyaty eṣa na saṃśayaḥ
kālas tu kriyatām asya śayane jāgare tathā', null, 6049025),
('ramayana-6-49-26', 26, 'Yuddha Kanda, Sarga 49, Verse 26', 'रावणस्य वचः श्रुत्वा स्वयम्भूरिदमब्रवीत्।
शयिता ह्येष षण्मासानेकाहं जागरिष्यति॥', 'rāvaṇasya vacaḥ śrutvā svayambhūr idam abravīt
śayitā hy eṣa ṣaṇ māsān ekāhaṃ jāgariṣyati', null, 6049026),
('ramayana-6-49-27', 27, 'Yuddha Kanda, Sarga 49, Verse 27', 'एकेनाह्ना त्वसौ वीरश्चरन्भूमिं बुभुक्षितः।
व्यात्तास्यो भक्षयेल्लोकान्संक्रुद्ध इव पावकः॥', 'ekenāhnā tv asau vīraś caran bhūmiṃ bubhukṣitaḥ
vyāttāsyo bhakṣayel lokān saṃkruddha iva pāvakaḥ', null, 6049027),
('ramayana-6-49-28', 28, 'Yuddha Kanda, Sarga 49, Verse 28', 'सोऽसौ व्यसनमापन्नः कुम्भकर्णमबोधयत्।
त्वत्पराक्रमभीतश्च राजा संप्रति रावणः॥', 'so ''sau vyasanam āpannaḥ kumbhakarṇam abodhayat
tvatparākramabhītaś ca rājā saṃprati rāvaṇaḥ', null, 6049028),
('ramayana-6-49-29', 29, 'Yuddha Kanda, Sarga 49, Verse 29', 'स एष निर्गतो वीरः शिबिराद्भीमविक्रमः।
वानरान्भृशसंक्रुद्धो भक्षयन्परिधावति॥', 'sa eṣa nirgato vīraḥ śibirād bhīmavikramaḥ
vānarān bhṛśasaṃkruddho bhakṣayan paridhāvati', null, 6049029),
('ramayana-6-49-30', 30, 'Yuddha Kanda, Sarga 49, Verse 30', 'कुम्भकर्णं समीक्ष्यैव हरयो विप्रदुद्रुवुः।
कथमेनं रणे क्रुद्धं वारयिष्यन्ति वानराः॥', 'kumbhakarṇaṃ samīkṣyaiva harayo vipradudruvuḥ
katham enaṃ raṇe kruddhaṃ vārayiṣyanti vānarāḥ', null, 6049030),
('ramayana-6-49-31', 31, 'Yuddha Kanda, Sarga 49, Verse 31', 'उच्यन्तां वानराः सर्वे यन्त्रमेतत्समुच्छ्रितम्।
इति विज्ञाय हरयो भविष्यन्तीह निर्भयाः॥', 'ucyantāṃ vānarāḥ sarve yantram etat samucchritam
iti vijñāya harayo bhaviṣyantīha nirbhayāḥ', null, 6049031),
('ramayana-6-49-32', 32, 'Yuddha Kanda, Sarga 49, Verse 32', 'विभीषणवचः श्रुत्वा हेतुमत्सुमुखोद्गतम्।
उवाच राघवो वाक्यं नीलं सेनापतिं तदा॥', 'vibhīṣaṇavacaḥ śrutvā hetumat sumukhodgatam
uvāca rāghavo vākyaṃ nīlaṃ senāpatiṃ tadā', null, 6049032),
('ramayana-6-49-33', 33, 'Yuddha Kanda, Sarga 49, Verse 33', 'गच्छ सैन्यानि सर्वाणि व्यूह्य तिष्ठस्व पावके।
द्वाराण्यादाय लङ्कायाश्चर्याश्चाप्यथ संक्रमान्॥', 'gaccha sainyāni sarvāṇi vyūhya tiṣṭhasva pāvake
dvārāṇy ādāya laṅkāyāś caryāś cāpy atha saṃkramān', null, 6049033),
('ramayana-6-49-34', 34, 'Yuddha Kanda, Sarga 49, Verse 34', 'शैलशृङ्गाणि वृक्षांश्च शिलाश्चाप्युपसंहरन्।
तिष्ठन्तु वानराः सर्वे सायुधाः शैलपाणयः॥', 'śailaśṛṅgāṇi vṛkṣāṃś ca śilāś cāpy upasaṃharan
tiṣṭhantu vānarāḥ sarve sāyudhāḥ śailapāṇayaḥ', null, 6049034),
('ramayana-6-49-35', 35, 'Yuddha Kanda, Sarga 49, Verse 35', 'राघवेण समादिष्टो नीलो हरिचमूपतिः।
शशास वानरानीकं यथावत्कपिकुञ्जरः॥', 'rāghaveṇa samādiṣṭo nīlo haricamūpatiḥ
śaśāsa vānarānīkaṃ yathāvat kapikuñjaraḥ', null, 6049035),
('ramayana-6-49-36', 36, 'Yuddha Kanda, Sarga 49, Verse 36', 'ततो गवाक्षः शरभो हनुमानङ्गदो नलः।
शैलशृङ्गाणि शैलाभा गृहीत्वा द्वारमभ्ययुः॥', 'tato gavākṣaḥ śarabho hanumān aṅgado nalaḥ
śailaśṛṅgāṇi śailābhā gṛhītvā dvāram abhyayuḥ', null, 6049036),
('ramayana-6-49-37', 37, 'Yuddha Kanda, Sarga 49, Verse 37', 'ततो हरीणां तदनीकमुग्रं रराज शैलोद्यतवृक्षहस्तम्।
गिरेः समीपानुगतं यथैव महन्महाम्भोधरजालमुग्रम्॥', 'tato harīṇāṃ tad anīkam ugraṃ rarāja śailodyatavṛkṣahastam
gireḥ samīpānugataṃ yathaiva mahan mahāmbhodharajālam ugram', null, 6049037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 50 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-50-1', 1, 'Yuddha Kanda, Sarga 50, Verse 1', 'स तु राक्षसशार्दूलो निद्रामदसमाकुलः।
राजमार्गं श्रिया जुष्टं ययौ विपुलविक्रमः॥', 'sa tu rākṣasaśārdūlo nidrāmadasamākulaḥ
rājamārgaṃ śriyā juṣṭaṃ yayau vipulavikramaḥ', null, 6050001),
('ramayana-6-50-2', 2, 'Yuddha Kanda, Sarga 50, Verse 2', 'राक्षसानां सहस्रैश्च वृतः परमदुर्जयः।
गृहेभ्यः पुष्पवर्षेण कार्यमाणस्तदा ययौ॥', 'rākṣasānāṃ sahasraiś ca vṛtaḥ paramadurjayaḥ
gṛhebhyaḥ puṣpavarṣeṇa kāryamāṇas tadā yayau', null, 6050002),
('ramayana-6-50-3', 3, 'Yuddha Kanda, Sarga 50, Verse 3', 'स हेमजालविततं भानुभास्वरदर्शनम्।
ददर्श विपुलं रम्यं राक्षसेन्द्रनिवेशनम्॥', 'sa hemajālavitataṃ bhānubhāsvaradarśanam
dadarśa vipulaṃ ramyaṃ rākṣasendraniveśanam', null, 6050003),
('ramayana-6-50-4', 4, 'Yuddha Kanda, Sarga 50, Verse 4', 'स तत्तदा सूर्य इवाभ्रजालं प्रविश्य रक्षोऽधिपतेर्निवेशनम्।
ददर्श दूरेऽग्रजमासनस्थं स्वयम्भुवं शक्र इवासनस्थम्॥', 'sa tat tadā sūrya ivābhrajālaṃ praviśya rakṣo''dhipater niveśanam
dadarśa dūre ''grajam āsanasthaṃ svayambhuvaṃ śakra ivāsanastham', null, 6050004),
('ramayana-6-50-5', 5, 'Yuddha Kanda, Sarga 50, Verse 5', 'सोऽभिगम्य गृहं भ्रातुः कक्ष्यामभिविगाह्य च।
ददर्शोद्विग्नमासीनं विमाने पुष्पके गुरुम्॥', 'so ''bhigamya gṛhaṃ bhrātuḥ kakṣyām abhivigāhya ca
dadarśodvignam āsīnaṃ vimāne puṣpake gurum', null, 6050005),
('ramayana-6-50-6', 6, 'Yuddha Kanda, Sarga 50, Verse 6', 'अथ दृष्ट्वा दशग्रीवः कुम्भकर्णमुपस्थितम्।
तूर्णमुत्थाय संहृष्टः संनिकर्षमुपानयत्॥', 'atha dṛṣṭvā daśagrīvaḥ kumbhakarṇam upasthitam
tūrṇam utthāya saṃhṛṣṭaḥ saṃnikarṣam upānayat', null, 6050006),
('ramayana-6-50-7', 7, 'Yuddha Kanda, Sarga 50, Verse 7', 'अथासीनस्य पर्यङ्के कुम्भकर्णो महाबलः।
भ्रातुर्ववन्दे चरणां किं कृत्यमिति चाब्रवीत्।
उत्पत्य चैनं मुदितो रावणः परिषस्वजे॥', 'athāsīnasya paryaṅke kumbhakarṇo mahābalaḥ
bhrātur vavande caraṇāṃ kiṃ kṛtyam iti cābravīt
utpatya cainaṃ mudito rāvaṇaḥ pariṣasvaje', null, 6050007),
('ramayana-6-50-8', 8, 'Yuddha Kanda, Sarga 50, Verse 8', 'स भ्रात्रा संपरिष्वक्तो यथावच्चाभिनन्दितः।
कुम्भकर्णः शुभं दिव्यं प्रतिपेदे वरासनम्॥', 'sa bhrātrā saṃpariṣvakto yathāvac cābhinanditaḥ
kumbhakarṇaḥ śubhaṃ divyaṃ pratipede varāsanam', null, 6050008),
('ramayana-6-50-9', 9, 'Yuddha Kanda, Sarga 50, Verse 9', 'स तदासनमाश्रित्य कुम्भकर्णो महाबलः।
संरक्तनयनः कोपाद्रावणं वाक्यमब्रवीत्॥', 'sa tadāsanam āśritya kumbhakarṇo mahābalaḥ
saṃraktanayanaḥ kopād rāvaṇaṃ vākyam abravīt', null, 6050009),
('ramayana-6-50-10', 10, 'Yuddha Kanda, Sarga 50, Verse 10', 'किमर्थमहमादृत्य त्वया राजन्प्रबोधितः।
शंस कस्माद्भयं तेऽस्ति कोऽद्य प्रेतो भविष्यति॥', 'kimartham aham ādṛtya tvayā rājan prabodhitaḥ
śaṃsa kasmād bhayaṃ te ''sti ko ''dya preto bhaviṣyati', null, 6050010),
('ramayana-6-50-11', 11, 'Yuddha Kanda, Sarga 50, Verse 11', 'भ्रातरं रावणः क्रुद्धं कुम्भकर्णमवस्थितम्।
ईषत्तु परिवृत्ताभ्यां नेत्राभ्यां वाक्यमब्रवीत्॥', 'bhrātaraṃ rāvaṇaḥ kruddhaṃ kumbhakarṇam avasthitam
īṣat tu parivṛttābhyāṃ netrābhyāṃ vākyam abravīt', null, 6050011),
('ramayana-6-50-12', 12, 'Yuddha Kanda, Sarga 50, Verse 12', 'अद्य ते सुमहान्कालः शयानस्य महाबल।
सुखितस्त्वं न जानीषे मम रामकृतं भयम्॥', 'adya te sumahān kālaḥ śayānasya mahābala
sukhitas tvaṃ na jānīṣe mama rāmakṛtaṃ bhayam', null, 6050012),
('ramayana-6-50-13', 13, 'Yuddha Kanda, Sarga 50, Verse 13', 'एष दाशरथी रामः सुग्रीवसहितो बली।
समुद्रं सबलस्तीर्त्वा मूलं नः परिकृन्तति॥', 'eṣa dāśarathī rāmaḥ sugrīvasahito balī
samudraṃ sabalas tīrtvā mūlaṃ naḥ parikṛntati', null, 6050013),
('ramayana-6-50-14', 14, 'Yuddha Kanda, Sarga 50, Verse 14', 'हन्त पश्यस्व लङ्काया वनान्युपवनानि च।
सेतुना सुखमागम्य वानरैकार्णवं कृतम्॥', 'hanta paśyasva laṅkāyā vanāny upavanāni ca
setunā sukham āgamya vānaraikārṇavaṃ kṛtam', null, 6050014),
('ramayana-6-50-15', 15, 'Yuddha Kanda, Sarga 50, Verse 15', 'ये राक्षसा मुख्यतमा हतास्ते वानरैर्युधि।
वानराणां क्षयं युद्धे न पश्यामि कदा चन॥', 'ye rākṣasā mukhyatamā hatās te vānarair yudhi
vānarāṇāṃ kṣayaṃ yuddhe na paśyāmi kadā cana', null, 6050015),
('ramayana-6-50-16', 16, 'Yuddha Kanda, Sarga 50, Verse 16', 'सर्वक्षपितकोशं च स त्वमभ्यवपद्य माम्।
त्रायस्वेमां पुरीं लङ्कां बालवृद्धावशेषिताम्॥', 'sarvakṣapitakośaṃ ca sa tvam abhyavapadya mām
trāyasvemāṃ purīṃ laṅkāṃ bālavṛddhāvaśeṣitām', null, 6050016),
('ramayana-6-50-17', 17, 'Yuddha Kanda, Sarga 50, Verse 17', 'भ्रातुरर्थे महाबाहो कुरु कर्म सुदुष्करम्।
मयैवं नोक्तपूर्वो हि कश्चिद्भ्रातः परंतप।
त्वय्यस्ति मम च स्नेहः परा संभावना च मे॥', 'bhrātur arthe mahābāho kuru karma suduṣkaram
mayaivaṃ noktapūrvo hi kaś cid bhrātaḥ paraṃtapa
tvayy asti mama ca snehaḥ parā saṃbhāvanā ca me', null, 6050017),
('ramayana-6-50-18', 18, 'Yuddha Kanda, Sarga 50, Verse 18', 'देवासुरविमर्देषु बहुशो राक्षसर्षभ।
त्वया देवाः प्रतिव्यूह्य निर्जिताश्चासुरा युधि।
न हि ते सर्वभूतेषु दृश्यते सदृशो बली॥', 'devāsuravimardeṣu bahuśo rākṣasarṣabha
tvayā devāḥ prativyūhya nirjitāś cāsurā yudhi
na hi te sarvabhūteṣu dṛśyate sadṛśo balī', null, 6050018),
('ramayana-6-50-19', 19, 'Yuddha Kanda, Sarga 50, Verse 19', 'कुरुष्व मे प्रियहितमेतदुत्तमं यथाप्रियं प्रियरणबान्धवप्रिय।
स्वतेजसा विधम सपत्नवाहिनीं शरद्घनं पवन इवोद्यतो महान्॥', 'kuruṣva me priyahitam etad uttamaṃ yathāpriyaṃ priyaraṇabāndhavapriya
svatejasā vidhama sapatnavāhinīṃ śaradghanaṃ pavana ivodyato mahān', null, 6050019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 51 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-51-1', 1, 'Yuddha Kanda, Sarga 51, Verse 1', 'तस्य राक्षसराजस्य निशम्य परिदेवितम्।
कुम्भकर्णो बभाषेऽथ वचनं प्रजहास च॥', 'tasya rākṣasarājasya niśamya paridevitam
kumbhakarṇo babhāṣe ''tha vacanaṃ prajahāsa ca', null, 6051001),
('ramayana-6-51-2', 2, 'Yuddha Kanda, Sarga 51, Verse 2', 'दृष्टो दोषो हि योऽस्माभिः पुरा मन्त्रविनिर्णये।
हितेष्वनभियुक्तेन सोऽयमासादितस्त्वया॥', 'dṛṣṭo doṣo hi yo ''smābhiḥ purā mantravinirṇaye
hiteṣv anabhiyuktena so ''yam āsāditas tvayā', null, 6051002),
('ramayana-6-51-3', 3, 'Yuddha Kanda, Sarga 51, Verse 3', 'शीघ्रं खल्वभ्युपेतं त्वां फलं पापस्य कर्मणः।
निरयेष्वेव पतनं यथा दुष्कृतकर्मणः॥', 'śīghraṃ khalv abhyupetaṃ tvāṃ phalaṃ pāpasya karmaṇaḥ
nirayeṣv eva patanaṃ yathā duṣkṛtakarmaṇaḥ', null, 6051003),
('ramayana-6-51-4', 4, 'Yuddha Kanda, Sarga 51, Verse 4', 'प्रथमं वै महाराज कृत्यमेतदचिन्तितम्।
केवलं वीर्यदर्पेण नानुबन्धो विचारितः॥', 'prathamaṃ vai mahārāja kṛtyam etad acintitam
kevalaṃ vīryadarpeṇa nānubandho vicāritaḥ', null, 6051004),
('ramayana-6-51-5', 5, 'Yuddha Kanda, Sarga 51, Verse 5', 'यः पश्चात्पूर्वकार्याणि कुर्यादैश्वर्यमास्थितः।
पूर्वं चोत्तरकार्याणि न स वेद नयानयौ॥', 'yaḥ paścāt pūrvakāryāṇi kuryād aiśvaryam āsthitaḥ
pūrvaṃ cottarakāryāṇi na sa veda nayānayau', null, 6051005),
('ramayana-6-51-6', 6, 'Yuddha Kanda, Sarga 51, Verse 6', 'देशकालविहीनानि कर्माणि विपरीतवत्।
क्रियमाणानि दुष्यन्ति हवींष्यप्रयतेष्विव॥', 'deśakālavihīnāni karmāṇi viparītavat
kriyamāṇāni duṣyanti havīṃṣy aprayateṣv iva', null, 6051006),
('ramayana-6-51-7', 7, 'Yuddha Kanda, Sarga 51, Verse 7', 'त्रयाणां पञ्चधा योगं कर्मणां यः प्रपश्यति।
सचिवैः समयं कृत्वा स सभ्ये वर्तते पथि॥', 'trayāṇāṃ pañcadhā yogaṃ karmaṇāṃ yaḥ prapaśyati
sacivaiḥ samayaṃ kṛtvā sa sabhye vartate pathi', null, 6051007),
('ramayana-6-51-8', 8, 'Yuddha Kanda, Sarga 51, Verse 8', 'यथागमं च यो राजा समयं विचिकीर्षति।
बुध्यते सचिवान्बुद्ध्या सुहृदश्चानुपश्यति॥', 'yathāgamaṃ ca yo rājā samayaṃ vicikīrṣati
budhyate sacivān buddhyā suhṛdaś cānupaśyati', null, 6051008),
('ramayana-6-51-9', 9, 'Yuddha Kanda, Sarga 51, Verse 9', 'धर्ममर्थं च कामं च सर्वान्वा रक्षसां पते।
भजते पुरुषः काले त्रीणि द्वन्द्वानि वा पुनः॥', 'dharmam arthaṃ ca kāmaṃ ca sarvān vā rakṣasāṃ pate
bhajate puruṣaḥ kāle trīṇi dvandvāni vā punaḥ', null, 6051009),
('ramayana-6-51-10', 10, 'Yuddha Kanda, Sarga 51, Verse 10', 'त्रिषु चैतेषु यच्छ्रेष्ठं श्रुत्वा तन्नावबुध्यते।
राजा वा राजमात्रो वा व्यर्थं तस्य बहुश्रुतम्॥', 'triṣu caiteṣu yac chreṣṭhaṃ śrutvā tan nāvabudhyate
rājā vā rājamātro vā vyarthaṃ tasya bahuśrutam', null, 6051010),
('ramayana-6-51-11', 11, 'Yuddha Kanda, Sarga 51, Verse 11', 'उपप्रदानं सान्त्वं वा भेदं काले च विक्रमम्।
योगं च रक्षसां श्रेष्ठ तावुभौ च नयानयौ॥', 'upapradānaṃ sāntvaṃ vā bhedaṃ kāle ca vikramam
yogaṃ ca rakṣasāṃ śreṣṭha tāv ubhau ca nayānayau', null, 6051011),
('ramayana-6-51-12', 12, 'Yuddha Kanda, Sarga 51, Verse 12', 'काले धर्मार्थकामान्यः संमन्त्र्य सचिवैः सह।
निषेवेतात्मवांल्लोके न स व्यसनमाप्नुयात्॥', 'kāle dharmārthakāmān yaḥ saṃmantrya sacivaiḥ saha
niṣevetātmavāṃl loke na sa vyasanam āpnuyāt', null, 6051012),
('ramayana-6-51-13', 13, 'Yuddha Kanda, Sarga 51, Verse 13', 'हितानुबन्धमालोक्य कार्याकार्यमिहात्मनः।
राजा सहार्थतत्त्वज्ञैः सचिवैः सह जीवति॥', 'hitānubandham ālokya kāryākāryam ihātmanaḥ
rājā sahārthatattvajñaiḥ sacivaiḥ saha jīvati', null, 6051013),
('ramayana-6-51-14', 14, 'Yuddha Kanda, Sarga 51, Verse 14', 'अनभिज्ञाय शास्त्रार्थान्पुरुषाः पशुबुद्धयः।
प्रागल्भ्याद्वक्तुमिच्छन्ति मन्त्रेष्वभ्यन्तरीकृताः॥', 'anabhijñāya śāstrārthān puruṣāḥ paśubuddhayaḥ
prāgalbhyād vaktum icchanti mantreṣv abhyantarīkṛtāḥ', null, 6051014),
('ramayana-6-51-15', 15, 'Yuddha Kanda, Sarga 51, Verse 15', 'अशास्त्रविदुषां तेषां न कार्यमहितं वचः।
अर्थशास्त्रानभिज्ञानां विपुलां श्रियमिच्छताम्॥', 'aśāstraviduṣāṃ teṣāṃ na kāryam ahitaṃ vacaḥ
arthaśāstrānabhijñānāṃ vipulāṃ śriyam icchatām', null, 6051015),
('ramayana-6-51-16', 16, 'Yuddha Kanda, Sarga 51, Verse 16', 'अहितं च हिताकारं धार्ष्ट्याज्जल्पन्ति ये नराः।
अवेक्ष्य मन्त्रबाह्यास्ते कर्तव्याः कृत्यदूषणाः॥', 'ahitaṃ ca hitākāraṃ dhārṣṭyāj jalpanti ye narāḥ
avekṣya mantrabāhyās te kartavyāḥ kṛtyadūṣaṇāḥ', null, 6051016),
('ramayana-6-51-17', 17, 'Yuddha Kanda, Sarga 51, Verse 17', 'विनाशयन्तो भर्तारं सहिताः शत्रुभिर्बुधैः।
विपरीतानि कृत्यानि कारयन्तीह मन्त्रिणः॥', 'vināśayanto bhartāraṃ sahitāḥ śatrubhir budhaiḥ
viparītāni kṛtyāni kārayantīha mantriṇaḥ', null, 6051017),
('ramayana-6-51-18', 18, 'Yuddha Kanda, Sarga 51, Verse 18', 'तान्भर्ता मित्रसंकाशानमित्रान्मन्त्रनिर्णये।
व्यवहारेण जानीयात्सचिवानुपसंहितान्॥', 'tān bhartā mitrasaṃkāśān amitrān mantranirṇaye
vyavahāreṇa jānīyāt sacivān upasaṃhitān', null, 6051018),
('ramayana-6-51-19', 19, 'Yuddha Kanda, Sarga 51, Verse 19', 'चपलस्येह कृत्यानि सहसानुप्रधावतः।
छिद्रमन्ये प्रपद्यन्ते क्रौञ्चस्य खमिव द्विजाः॥', 'capalasyeha kṛtyāni sahasānupradhāvataḥ
chidram anye prapadyante krauñcasya kham iva dvijāḥ', null, 6051019),
('ramayana-6-51-20', 20, 'Yuddha Kanda, Sarga 51, Verse 20', 'यो हि शत्रुमवज्ञाय नात्मानमभिरक्षति।
अवाप्नोति हि सोऽनर्थान्स्थानाच्च व्यवरोप्यते॥', 'yo hi śatrum avajñāya nātmānam abhirakṣati
avāpnoti hi so ''narthān sthānāc ca vyavaropyate', null, 6051020),
('ramayana-6-51-21', 21, 'Yuddha Kanda, Sarga 51, Verse 21', 'तत्तु श्रुत्वा दशग्रीवः कुम्भकर्णस्य भाषितम्।
भ्रुकुटिं चैव संचक्रे क्रुद्धश्चैनमुवाच ह॥', 'tat tu śrutvā daśagrīvaḥ kumbhakarṇasya bhāṣitam
bhrukuṭiṃ caiva saṃcakre kruddhaś cainam uvāca ha', null, 6051021),
('ramayana-6-51-22', 22, 'Yuddha Kanda, Sarga 51, Verse 22', 'मान्यो गुरुरिवाचार्यः किं मां त्वमनुशासति।
किमेवं वाक्श्रमं कृत्वा काले युक्तं विधीयताम्॥', 'mānyo gurur ivācāryaḥ kiṃ māṃ tvam anuśāsati
kim evaṃ vākśramaṃ kṛtvā kāle yuktaṃ vidhīyatām', null, 6051022),
('ramayana-6-51-23', 23, 'Yuddha Kanda, Sarga 51, Verse 23', 'विभ्रमाच्चित्तमोहाद्वा बलवीर्याश्रयेण वा।
नाभिपन्नमिदानीं यद्व्यर्थास्तस्य पुनः कृथाः॥', 'vibhramāc cittamohād vā balavīryāśrayeṇa vā
nābhipannam idānīṃ yad vyarthās tasya punaḥ kṛthāḥ', null, 6051023),
('ramayana-6-51-24', 24, 'Yuddha Kanda, Sarga 51, Verse 24', 'अस्मिन्काले तु यद्युक्तं तदिदानीं विधीयताम्।
ममापनयजं दोषं विक्रमेण समीकुरु॥', 'asmin kāle tu yad yuktaṃ tad idānīṃ vidhīyatām
mamāpanayajaṃ doṣaṃ vikrameṇa samīkuru', null, 6051024),
('ramayana-6-51-25', 25, 'Yuddha Kanda, Sarga 51, Verse 25', 'यदि खल्वस्ति मे स्नेहो भ्रातृत्वं वावगच्छसि।
यदि वा कार्यमेतत्ते हृदि कार्यतमं मतम्॥', 'yadi khalv asti me sneho bhrātṛtvaṃ vāvagacchasi
yadi vā kāryam etat te hṛdi kāryatamaṃ matam', null, 6051025),
('ramayana-6-51-26', 26, 'Yuddha Kanda, Sarga 51, Verse 26', 'स सुहृद्यो विपन्नार्थं दीनमभ्यवपद्यते।
स बन्धुर्योऽपनीतेषु साहाय्यायोपकल्पते॥', 'sa suhṛdyo vipannārthaṃ dīnam abhyavapadyate
sa bandhur yo ''panīteṣu sāhāyyāyopakalpate', null, 6051026),
('ramayana-6-51-27', 27, 'Yuddha Kanda, Sarga 51, Verse 27', 'तमथैवं ब्रुवाणं तु वचनं धीरदारुणम्।
रुष्टोऽयमिति विज्ञाय शनैः श्लक्ष्णमुवाच ह॥', 'tam athaivaṃ bruvāṇaṃ tu vacanaṃ dhīradāruṇam
ruṣṭo ''yam iti vijñāya śanaiḥ ślakṣṇam uvāca ha', null, 6051027),
('ramayana-6-51-28', 28, 'Yuddha Kanda, Sarga 51, Verse 28', 'अतीव हि समालक्ष्य भ्रातरं क्षुभितेन्द्रियम्।
कुम्भकर्णः शनैर्वाक्यं बभाषे परिसान्त्वयन्॥', 'atīva hi samālakṣya bhrātaraṃ kṣubhitendriyam
kumbhakarṇaḥ śanair vākyaṃ babhāṣe parisāntvayan', null, 6051028),
('ramayana-6-51-29', 29, 'Yuddha Kanda, Sarga 51, Verse 29', 'अलं राक्षसराजेन्द्र संतापमुपपद्य ते।
रोषं च संपरित्यज्य स्वस्थो भवितुमर्हसि॥', 'alaṃ rākṣasarājendra saṃtāpam upapadya te
roṣaṃ ca saṃparityajya svastho bhavitum arhasi', null, 6051029),
('ramayana-6-51-30', 30, 'Yuddha Kanda, Sarga 51, Verse 30', 'नैतन्मनसि कर्तव्व्यं मयि जीवति पार्थिव।
तमहं नाशयिष्यामि यत्कृते परितप्यसे॥', 'naitan manasi kartavvyaṃ mayi jīvati pārthiva
tam ahaṃ nāśayiṣyāmi yatkṛte paritapyase', null, 6051030),
('ramayana-6-51-31', 31, 'Yuddha Kanda, Sarga 51, Verse 31', 'अवश्यं तु हितं वाच्यं सर्वावस्थं मया तव।
बन्धुभावादभिहितं भ्रातृस्नेहाच्च पार्थिव॥', 'avaśyaṃ tu hitaṃ vācyaṃ sarvāvasthaṃ mayā tava
bandhubhāvād abhihitaṃ bhrātṛsnehāc ca pārthiva', null, 6051031),
('ramayana-6-51-32', 32, 'Yuddha Kanda, Sarga 51, Verse 32', 'सदृशं यत्तु कालेऽस्मिन्कर्तुं स्निग्धेन बन्धुना।
शत्रूणां कदनं पश्य क्रियमाणं मया रणे॥', 'sadṛśaṃ yat tu kāle ''smin kartuṃ snigdhena bandhunā
śatrūṇāṃ kadanaṃ paśya kriyamāṇaṃ mayā raṇe', null, 6051032),
('ramayana-6-51-33', 33, 'Yuddha Kanda, Sarga 51, Verse 33', 'अद्य पश्य महाबाहो मया समरमूर्धनि।
हते रामे सह भ्रात्रा द्रवन्तीं हरिवाहिनीम्॥', 'adya paśya mahābāho mayā samaramūrdhani
hate rāme saha bhrātrā dravantīṃ harivāhinīm', null, 6051033),
('ramayana-6-51-34', 34, 'Yuddha Kanda, Sarga 51, Verse 34', 'अद्य रामस्य तद्दृष्ट्वा मयानीतं रणाच्छिरः।
सुखीभव महाबाहो सीता भवतु दुःखिता॥', 'adya rāmasya tad dṛṣṭvā mayānītaṃ raṇāc chiraḥ
sukhībhava mahābāho sītā bhavatu duḥkhitā', null, 6051034),
('ramayana-6-51-35', 35, 'Yuddha Kanda, Sarga 51, Verse 35', 'अद्य रामस्य पश्यन्तु निधनं सुमहत्प्रियम्।
लङ्कायां राक्षसाः सर्वे ये ते निहतबान्धवाः॥', 'adya rāmasya paśyantu nidhanaṃ sumahat priyam
laṅkāyāṃ rākṣasāḥ sarve ye te nihatabāndhavāḥ', null, 6051035),
('ramayana-6-51-36', 36, 'Yuddha Kanda, Sarga 51, Verse 36', 'अद्य शोकपरीतानां स्वबन्धुवधकारणात्।
शत्रोर्युधि विनाशेन करोम्यस्रप्रमार्जनम्॥', 'adya śokaparītānāṃ svabandhuvadhakāraṇāt
śatror yudhi vināśena karomy asrapramārjanam', null, 6051036),
('ramayana-6-51-37', 37, 'Yuddha Kanda, Sarga 51, Verse 37', 'अद्य पर्वतसंकाशं ससूर्यमिव तोयदम्।
विकीर्णं पश्य समरे सुग्रीवं प्लवगेश्वरम्॥', 'adya parvatasaṃkāśaṃ sasūryam iva toyadam
vikīrṇaṃ paśya samare sugrīvaṃ plavageśvaram', null, 6051037),
('ramayana-6-51-38', 38, 'Yuddha Kanda, Sarga 51, Verse 38', 'न परः प्रेषणीयस्ते युद्धायातुल विक्रम।
अहमुत्सादयिष्यामि शत्रूंस्तव महाबल॥', 'na paraḥ preṣaṇīyas te yuddhāyātula vikrama
aham utsādayiṣyāmi śatrūṃs tava mahābala', null, 6051038),
('ramayana-6-51-39', 39, 'Yuddha Kanda, Sarga 51, Verse 39', 'यदि शक्रो यदि यमो यदि पावकमारुतौ।
तानहं योधयिष्यामि कुबेर वरुणावपि॥', 'yadi śakro yadi yamo yadi pāvakamārutau
tān ahaṃ yodhayiṣyāmi kubera varuṇāv api', null, 6051039),
('ramayana-6-51-40', 40, 'Yuddha Kanda, Sarga 51, Verse 40', 'गिरिमात्रशरीरस्य शितशूलधरस्य मे।
नर्दतस्तीक्ष्णदंष्ट्रस्य बिभीयाच्च पुरंदरः॥', 'girimātraśarīrasya śitaśūladharasya me
nardatas tīkṣṇadaṃṣṭrasya bibhīyāc ca puraṃdaraḥ', null, 6051040),
('ramayana-6-51-41', 41, 'Yuddha Kanda, Sarga 51, Verse 41', 'अथ वा त्यक्तशस्त्रस्य मृद्गतस्तरसा रिपून्।
न मे प्रतिमुखे कश्चिच्छक्तः स्थातुं जिजीविषुः॥', 'atha vā tyaktaśastrasya mṛdgatas tarasā ripūn
na me pratimukhe kaś cic chaktaḥ sthātuṃ jijīviṣuḥ', null, 6051041),
('ramayana-6-51-42', 42, 'Yuddha Kanda, Sarga 51, Verse 42', 'नैव शक्त्या न गदया नासिना न शितैः शरैः।
हस्ताभ्यामेव संरब्धो हनिष्याम्यपि वज्रिणम्॥', 'naiva śaktyā na gadayā nāsinā na śitaiḥ śaraiḥ
hastābhyām eva saṃrabdho haniṣyāmy api vajriṇam', null, 6051042),
('ramayana-6-51-43', 43, 'Yuddha Kanda, Sarga 51, Verse 43', 'यदि मे मुष्टिवेगं स राघवोऽद्य सहिष्यति।
ततः पास्यन्ति बाणौघा रुधिरं राघवस्य ते॥', 'yadi me muṣṭivegaṃ sa rāghavo ''dya sahiṣyati
tataḥ pāsyanti bāṇaughā rudhiraṃ rāghavasya te', null, 6051043),
('ramayana-6-51-44', 44, 'Yuddha Kanda, Sarga 51, Verse 44', 'चिन्तया बाध्यसे राजन्किमर्थं मयि तिष्ठति।
सोऽहं शत्रुविनाशाय तव निर्यातुमुद्यतः॥', 'cintayā bādhyase rājan kimarthaṃ mayi tiṣṭhati
so ''haṃ śatruvināśāya tava niryātum udyataḥ', null, 6051044),
('ramayana-6-51-45', 45, 'Yuddha Kanda, Sarga 51, Verse 45', 'मुञ्च रामाद्भयं राजन्हनिष्यामीह संयुगे।
राघवं लक्ष्मणं चैव सुग्रीवं च महाबलम्।
असाधारणमिच्छामि तव दातुं महद्यशः॥', 'muñca rāmād bhayaṃ rājan haniṣyāmīha saṃyuge
rāghavaṃ lakṣmaṇaṃ caiva sugrīvaṃ ca mahābalam
asādhāraṇam icchāmi tava dātuṃ mahad yaśaḥ', null, 6051045),
('ramayana-6-51-46', 46, 'Yuddha Kanda, Sarga 51, Verse 46', 'वधेन ते दाशरथेः सुखावहं सुखं समाहर्तुमहं व्रजामि।
निहत्य रामं सहलक्ष्मणेन खादामि सर्वान्हरियूथमुख्यान्॥', 'vadhena te dāśaratheḥ sukhāvahaṃ sukhaṃ samāhartum ahaṃ vrajāmi
nihatya rāmaṃ sahalakṣmaṇena khādāmi sarvān hariyūthamukhyān', null, 6051046),
('ramayana-6-51-47', 47, 'Yuddha Kanda, Sarga 51, Verse 47', 'रमस्व कामं पिब चाग्र्यवारुणीं कुरुष्व कृत्यानि विनीयतां ज्वरः।
मयाद्य रामे गमिते यमक्षयं चिराय सीता वशगा भविष्यति॥', 'ramasva kāmaṃ piba cāgryavāruṇīṃ kuruṣva kṛtyāni vinīyatāṃ jvaraḥ
mayādya rāme gamite yamakṣayaṃ cirāya sītā vaśagā bhaviṣyati', null, 6051047)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 52 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-52-1', 1, 'Yuddha Kanda, Sarga 52, Verse 1', 'तदुक्तमतिकायस्य बलिनो बाहुशालिनः।
कुम्भकर्णस्य वचनं श्रुत्वोवाच महोदरः॥', 'tad uktam atikāyasya balino bāhuśālinaḥ
kumbhakarṇasya vacanaṃ śrutvovāca mahodaraḥ', null, 6052001),
('ramayana-6-52-2', 2, 'Yuddha Kanda, Sarga 52, Verse 2', 'कुम्भकर्णकुले जातो धृष्टः प्राकृतदर्शनः।
अवलिप्तो न शक्नोषि कृत्यं सर्वत्र वेदितुम्॥', 'kumbhakarṇakule jāto dhṛṣṭaḥ prākṛtadarśanaḥ
avalipto na śaknoṣi kṛtyaṃ sarvatra veditum', null, 6052002),
('ramayana-6-52-3', 3, 'Yuddha Kanda, Sarga 52, Verse 3', 'न हि राजा न जानीते कुम्भकर्ण नयानयौ।
त्वं तु कैशोरकाद्धृष्टः केवलं वक्तुमिच्छसि॥', 'na hi rājā na jānīte kumbhakarṇa nayānayau
tvaṃ tu kaiśorakād dhṛṣṭaḥ kevalaṃ vaktum icchasi', null, 6052003),
('ramayana-6-52-4', 4, 'Yuddha Kanda, Sarga 52, Verse 4', 'स्थानं वृद्धिं च हानिं च देशकालविभागवित्।
आत्मनश्च परेषां च बुध्यते राक्षसर्षभ॥', 'sthānaṃ vṛddhiṃ ca hāniṃ ca deśakālavibhāgavit
ātmanaś ca pareṣāṃ ca budhyate rākṣasarṣabha', null, 6052004),
('ramayana-6-52-5', 5, 'Yuddha Kanda, Sarga 52, Verse 5', 'यत्तु शक्यं बलवता कर्तुं प्राकृतबुद्धिना।
अनुपासितवृद्धेन कः कुर्यात्तादृशं बुधः॥', 'yat tu śakyaṃ balavatā kartuṃ prākṛtabuddhinā
anupāsitavṛddhena kaḥ kuryāt tādṛśaṃ budhaḥ', null, 6052005),
('ramayana-6-52-6', 6, 'Yuddha Kanda, Sarga 52, Verse 6', 'यांस्तु धर्मार्थकामांस्त्वं ब्रवीषि पृथगाश्रयान्।
अनुबोद्धुं स्वभावेन न हि लक्षणमस्ति ते॥', 'yāṃs tu dharmārthakāmāṃs tvaṃ bravīṣi pṛthag āśrayān
anuboddhuṃ svabhāvena na hi lakṣaṇam asti te', null, 6052006),
('ramayana-6-52-7', 7, 'Yuddha Kanda, Sarga 52, Verse 7', 'कर्म चैव हि सर्वेषां कारणानां प्रयोजनम्।
श्रेयः पापीयसां चात्र फलं भवति कर्मणाम्॥', 'karma caiva hi sarveṣāṃ kāraṇānāṃ prayojanam
śreyaḥ pāpīyasāṃ cātra phalaṃ bhavati karmaṇām', null, 6052007),
('ramayana-6-52-8', 8, 'Yuddha Kanda, Sarga 52, Verse 8', 'निःश्रेयस फलावेव धर्मार्थावितरावपि।
अधर्मानर्थयोः प्राप्तिः फलं च प्रत्यवायिकम्॥', 'niḥśreyasa phalāv eva dharmārthāv itarāv api
adharmānarthayoḥ prāptiḥ phalaṃ ca pratyavāyikam', null, 6052008),
('ramayana-6-52-9', 9, 'Yuddha Kanda, Sarga 52, Verse 9', 'ऐहलौकिकपारत्र्यं कर्म पुम्भिर्निषेव्यते।
कर्माण्यपि तु कल्प्यानि लभते काममास्थितः॥', 'aihalaukikapāratryaṃ karma pumbhir niṣevyate
karmāṇy api tu kalpyāni labhate kāmam āsthitaḥ', null, 6052009),
('ramayana-6-52-10', 10, 'Yuddha Kanda, Sarga 52, Verse 10', 'तत्र कॢप्तमिदं राज्ञा हृदि कार्यं मतं च नः।
शत्रौ हि साहसं यत्स्यात्किमिवात्रापनीयते॥', 'tatra kḷptam idaṃ rājñā hṛdi kāryaṃ mataṃ ca naḥ
śatrau hi sāhasaṃ yat syāt kim ivātrāpanīyate', null, 6052010),
('ramayana-6-52-11', 11, 'Yuddha Kanda, Sarga 52, Verse 11', 'एकस्यैवाभियाने तु हेतुर्यः प्रकृतस्त्वया।
तत्राप्यनुपपन्नं ते वक्ष्यामि यदसाधु च॥', 'ekasyaivābhiyāne tu hetur yaḥ prakṛtas tvayā
tatrāpy anupapannaṃ te vakṣyāmi yad asādhu ca', null, 6052011),
('ramayana-6-52-12', 12, 'Yuddha Kanda, Sarga 52, Verse 12', 'येन पूर्वं जनस्थाने बहवोऽतिबला हताः।
राक्षसा राघवं तं त्वं कथमेको जयिष्यसि॥', 'yena pūrvaṃ janasthāne bahavo ''tibalā hatāḥ
rākṣasā rāghavaṃ taṃ tvaṃ katham eko jayiṣyasi', null, 6052012),
('ramayana-6-52-13', 13, 'Yuddha Kanda, Sarga 52, Verse 13', 'ये पुरा निर्जितास्तेन जनस्थाने महौजसः।
राक्षसांस्तान्पुरे सर्वान्भीतानद्यापि पश्यसि॥', 'ye purā nirjitās tena janasthāne mahaujasaḥ
rākṣasāṃs tān pure sarvān bhītān adyāpi paśyasi', null, 6052013),
('ramayana-6-52-14', 14, 'Yuddha Kanda, Sarga 52, Verse 14', 'तं सिंहमिव संक्रुद्धं रामं दशरथात्मजम्।
सर्पं सुप्तमिवाबुद्ध्या प्रबोधयितुमिच्छसि॥', 'taṃ siṃham iva saṃkruddhaṃ rāmaṃ daśarathātmajam
sarpaṃ suptam ivābuddhyā prabodhayitum icchasi', null, 6052014),
('ramayana-6-52-15', 15, 'Yuddha Kanda, Sarga 52, Verse 15', 'ज्वलन्तं तेजसा नित्यं क्रोधेन च दुरासदम्।
कस्तं मृत्युमिवासह्यमासादयितुमर्हति॥', 'jvalantaṃ tejasā nityaṃ krodhena ca durāsadam
kas taṃ mṛtyum ivāsahyam āsādayitum arhati', null, 6052015),
('ramayana-6-52-16', 16, 'Yuddha Kanda, Sarga 52, Verse 16', 'संशयस्थमिदं सर्वं शत्रोः प्रतिसमासने।
एकस्य गमनं तत्र न हि मे रोचते तव॥', 'saṃśayastham idaṃ sarvaṃ śatroḥ pratisamāsane
ekasya gamanaṃ tatra na hi me rocate tava', null, 6052016),
('ramayana-6-52-17', 17, 'Yuddha Kanda, Sarga 52, Verse 17', 'हीनार्थस्तु समृद्धार्थं को रिपुं प्राकृतो यथा।
निश्चितं जीवितत्यागे वशमानेतुमिच्छति॥', 'hīnārthas tu samṛddhārthaṃ ko ripuṃ prākṛto yathā
niścitaṃ jīvitatyāge vaśam ānetum icchati', null, 6052017),
('ramayana-6-52-18', 18, 'Yuddha Kanda, Sarga 52, Verse 18', 'यस्य नास्ति मनुष्येषु सदृशो राक्षसोत्तम।
कथमाशंससे योद्धुं तुल्येनेन्द्रविवस्वतोः॥', 'yasya nāsti manuṣyeṣu sadṛśo rākṣasottama
katham āśaṃsase yoddhuṃ tulyenendravivasvatoḥ', null, 6052018),
('ramayana-6-52-19', 19, 'Yuddha Kanda, Sarga 52, Verse 19', 'एवमुक्त्वा तु संरब्धं कुम्भकर्णं महोदरः।
उवाच रक्षसां मध्ये रावणो लोकरावणम्॥', 'evam uktvā tu saṃrabdhaṃ kumbhakarṇaṃ mahodaraḥ
uvāca rakṣasāṃ madhye rāvaṇo lokarāvaṇam', null, 6052019),
('ramayana-6-52-20', 20, 'Yuddha Kanda, Sarga 52, Verse 20', 'लब्ध्वा पुनस्तां वैदेहीं किमर्थं त्वं प्रजल्पसि।
यदेच्छसि तदा सीता वशगा ते भविष्यति॥', 'labdhvā punas tāṃ vaidehīṃ kimarthaṃ tvaṃ prajalpasi
yadecchasi tadā sītā vaśagā te bhaviṣyati', null, 6052020),
('ramayana-6-52-21', 21, 'Yuddha Kanda, Sarga 52, Verse 21', 'दृष्टः कश्चिदुपायो मे सीतोपस्थानकारकः।
रुचितश्चेत्स्वया बुद्ध्या राक्षसेश्वर तं शृणु॥', 'dṛṣṭaḥ kaś cid upāyo me sītopasthānakārakaḥ
rucitaś cet svayā buddhyā rākṣaseśvara taṃ śṛṇu', null, 6052021),
('ramayana-6-52-22', 22, 'Yuddha Kanda, Sarga 52, Verse 22', 'अहं द्विजिह्वः संह्रादी कुम्भकर्णो वितर्दनः।
पञ्चरामवधायैते निर्यान्तीत्यवघोषय॥', 'ahaṃ dvijihvaḥ saṃhrādī kumbhakarṇo vitardanaḥ
pañcarāmavadhāyaite niryāntīty avaghoṣaya', null, 6052022),
('ramayana-6-52-23', 23, 'Yuddha Kanda, Sarga 52, Verse 23', 'ततो गत्वा वयं युद्धं दास्यामस्तस्य यत्नतः।
जेष्यामो यदि ते शत्रून्नोपायैः कृत्यमस्ति नः॥', 'tato gatvā vayaṃ yuddhaṃ dāsyāmas tasya yatnataḥ
jeṣyāmo yadi te śatrūn nopāyaiḥ kṛtyam asti naḥ', null, 6052023),
('ramayana-6-52-24', 24, 'Yuddha Kanda, Sarga 52, Verse 24', 'अथ जीवति नः शत्रुर्वयं च कृतसंयुगाः।
ततः समभिपत्स्यामो मनसा यत्समीक्षितुम्॥', 'atha jīvati naḥ śatrur vayaṃ ca kṛtasaṃyugāḥ
tataḥ samabhipatsyāmo manasā yat samīkṣitum', null, 6052024),
('ramayana-6-52-25', 25, 'Yuddha Kanda, Sarga 52, Verse 25', 'वयं युद्धादिहैष्यामो रुधिरेण समुक्षिताः।
विदार्य स्वतनुं बाणै रामनामाङ्कितैः शितैः॥', 'vayaṃ yuddhād ihaiṣyāmo rudhireṇa samukṣitāḥ
vidārya svatanuṃ bāṇai rāmanāmāṅkitaiḥ śitaiḥ', null, 6052025),
('ramayana-6-52-26', 26, 'Yuddha Kanda, Sarga 52, Verse 26', 'भक्षितो राघवोऽस्माभिर्लक्ष्मणश्चेति वादिनः।
तव पादौ ग्रहीष्यामस्त्वं नः काम प्रपूरय॥', 'bhakṣito rāghavo ''smābhir lakṣmaṇaś ceti vādinaḥ
tava pādau grahīṣyāmas tvaṃ naḥ kāma prapūraya', null, 6052026),
('ramayana-6-52-27', 27, 'Yuddha Kanda, Sarga 52, Verse 27', 'ततोऽवघोषय पुरे गजस्कन्धेन पार्थिव।
हतो रामः सह भ्रात्रा ससैन्य इति सर्वतः॥', 'tato ''vaghoṣaya pure gajaskandhena pārthiva
hato rāmaḥ saha bhrātrā sasainya iti sarvataḥ', null, 6052027),
('ramayana-6-52-28', 28, 'Yuddha Kanda, Sarga 52, Verse 28', 'प्रीतो नाम ततो भूत्वा भृत्यानां त्वमरिंदम।
भोगांश्च परिवारांश्च कामांश्च वसुदापय॥', 'prīto nāma tato bhūtvā bhṛtyānāṃ tvam ariṃdama
bhogāṃś ca parivārāṃś ca kāmāṃś ca vasudāpaya', null, 6052028),
('ramayana-6-52-29', 29, 'Yuddha Kanda, Sarga 52, Verse 29', 'ततो माल्यानि वासांसि वीराणामनुलेपनम्।
पेयं च बहु योधेभ्यः स्वयं च मुदितः पिब॥', 'tato mālyāni vāsāṃsi vīrāṇām anulepanam
peyaṃ ca bahu yodhebhyaḥ svayaṃ ca muditaḥ piba', null, 6052029),
('ramayana-6-52-30', 30, 'Yuddha Kanda, Sarga 52, Verse 30', 'ततोऽस्मिन्बहुलीभूते कौलीने सर्वतो गते।
प्रविश्याश्वास्य चापि त्वं सीतां रहसि सान्त्वय।
धनधान्यैश्च कामैश्च रत्नैश्चैनां प्रलोभय॥', 'tato ''smin bahulībhūte kaulīne sarvato gate
praviśyāśvāsya cāpi tvaṃ sītāṃ rahasi sāntvaya
dhanadhānyaiś ca kāmaiś ca ratnaiś caināṃ pralobhaya', null, 6052030),
('ramayana-6-52-31', 31, 'Yuddha Kanda, Sarga 52, Verse 31', 'अनयोपधया राजन्भयशोकानुबन्धया।
अकामा त्वद्वशं सीता नष्टनाथा गमिष्यति॥', 'anayopadhayā rājan bhayaśokānubandhayā
akāmā tvadvaśaṃ sītā naṣṭanāthā gamiṣyati', null, 6052031),
('ramayana-6-52-32', 32, 'Yuddha Kanda, Sarga 52, Verse 32', 'रञ्जनीयं हि भर्तारं विनष्टमवगम्य सा।
नैराश्यात्स्त्रीलघुत्वाच्च त्वद्वशं प्रतिपत्स्यते॥', 'rañjanīyaṃ hi bhartāraṃ vinaṣṭam avagamya sā
nairāśyāt strīlaghutvāc ca tvadvaśaṃ pratipatsyate', null, 6052032),
('ramayana-6-52-33', 33, 'Yuddha Kanda, Sarga 52, Verse 33', 'सा पुरा सुखसंवृद्धा सुखार्हा दुःखकर्षिता।
त्वय्यधीनः सुखं ज्ञात्वा सर्वथोपगमिष्यति॥', 'sā purā sukhasaṃvṛddhā sukhārhā duḥkhakarṣitā
tvayy adhīnaḥ sukhaṃ jñātvā sarvathopagamiṣyati', null, 6052033),
('ramayana-6-52-34', 34, 'Yuddha Kanda, Sarga 52, Verse 34', 'एतत्सुनीतं मम दर्शनेन रामं हि दृष्ट्वैव भवेदनर्थः।
इहैव ते सेत्स्यति मोत्सुको भूर्महानयुद्धेन सुखस्य लाभः॥', 'etat sunītaṃ mama darśanena rāmaṃ hi dṛṣṭvaiva bhaved anarthaḥ
ihaiva te setsyati motsuko bhūr mahān ayuddhena sukhasya lābhaḥ', null, 6052034),
('ramayana-6-52-35', 35, 'Yuddha Kanda, Sarga 52, Verse 35', 'अनष्टसैन्यो ह्यनवाप्तसंशयो रिपूनयुद्धेन जयञ्जनाधिप।
यशश्च पुण्यं च महन्महीपते श्रियं च कीर्तिं च चिरं समश्नुते॥', 'anaṣṭasainyo hy anavāptasaṃśayo ripūn ayuddhena jayañ janādhipa
yaśaś ca puṇyaṃ ca mahan mahīpate śriyaṃ ca kīrtiṃ ca ciraṃ samaśnute', null, 6052035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 53 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-53-1', 1, 'Yuddha Kanda, Sarga 53, Verse 1', 'स तथोक्तस्तु निर्भर्त्स्य कुम्भकर्णो महोदरम्।
अब्रवीद्राक्षसश्रेष्ठं भ्रातरं रावणं ततः॥', 'sa tathoktas tu nirbhartsya kumbhakarṇo mahodaram
abravīd rākṣasaśreṣṭhaṃ bhrātaraṃ rāvaṇaṃ tataḥ', null, 6053001),
('ramayana-6-53-2', 2, 'Yuddha Kanda, Sarga 53, Verse 2', 'सोऽहं तव भयं घोरं वधात्तस्य दुरात्मनः।
रामस्याद्य प्रमार्जामि निर्वैरस्त्वं सुखीभव॥', 'so ''haṃ tava bhayaṃ ghoraṃ vadhāt tasya durātmanaḥ
rāmasyādya pramārjāmi nirvairas tvaṃ sukhībhava', null, 6053002),
('ramayana-6-53-3', 3, 'Yuddha Kanda, Sarga 53, Verse 3', 'गर्जन्ति न वृथा शूर निर्जला इव तोयदाः।
पश्य संपाद्यमानं तु गर्जितं युधि कर्मणा॥', 'garjanti na vṛthā śūra nirjalā iva toyadāḥ
paśya saṃpādyamānaṃ tu garjitaṃ yudhi karmaṇā', null, 6053003),
('ramayana-6-53-4', 4, 'Yuddha Kanda, Sarga 53, Verse 4', 'न मर्षयति चात्मानं संभावयति नात्मना।
अदर्शयित्वा शूरास्तु कर्म कुर्वन्ति दुष्करम्॥', 'na marṣayati cātmānaṃ saṃbhāvayati nātmanā
adarśayitvā śūrās tu karma kurvanti duṣkaram', null, 6053004),
('ramayana-6-53-5', 5, 'Yuddha Kanda, Sarga 53, Verse 5', 'विक्लवानामबुद्धीनां राज्ञां पण्डितमानिनाम्।
शृण्वतामादित इदं त्वद्विधानां महोदर॥', 'viklavānām abuddhīnāṃ rājñāṃ paṇḍitamāninām
śṛṇvatām ādita idaṃ tvadvidhānāṃ mahodara', null, 6053005),
('ramayana-6-53-6', 6, 'Yuddha Kanda, Sarga 53, Verse 6', 'युद्धे कापुरुषैर्नित्यं भवद्भिः प्रियवादिभिः।
राजानमनुगच्छद्भिः कृत्यमेतद्विनाशितम्॥', 'yuddhe kāpuruṣair nityaṃ bhavadbhiḥ priyavādibhiḥ
rājānam anugacchadbhiḥ kṛtyam etad vināśitam', null, 6053006),
('ramayana-6-53-7', 7, 'Yuddha Kanda, Sarga 53, Verse 7', 'राजशेषा कृता लङ्का क्षीणः कोशो बलं हतम्।
राजानमिममासाद्य सुहृच्चिह्नममित्रकम्॥', 'rājaśeṣā kṛtā laṅkā kṣīṇaḥ kośo balaṃ hatam
rājānam imam āsādya suhṛccihnam amitrakam', null, 6053007),
('ramayana-6-53-8', 8, 'Yuddha Kanda, Sarga 53, Verse 8', 'एष निर्याम्यहं युद्धमुद्यतः शत्रुनिर्जये।
दुर्नयं भवतामद्य समीकर्तुं महाहवे॥', 'eṣa niryāmy ahaṃ yuddham udyataḥ śatrunirjaye
durnayaṃ bhavatām adya samīkartuṃ mahāhave', null, 6053008),
('ramayana-6-53-9', 9, 'Yuddha Kanda, Sarga 53, Verse 9', 'एवमुक्तवतो वाक्यं कुम्भकर्णस्य धीमतः।
प्रत्युवाच ततो वाक्यं प्रहसन्राक्षसाधिपः॥', 'evam uktavato vākyaṃ kumbhakarṇasya dhīmataḥ
pratyuvāca tato vākyaṃ prahasan rākṣasādhipaḥ', null, 6053009),
('ramayana-6-53-10', 10, 'Yuddha Kanda, Sarga 53, Verse 10', 'महोदरोऽयं रामात्तु परित्रस्तो न संशयः।
न हि रोचयते तात युद्धं युद्धविशारद॥', 'mahodaro ''yaṃ rāmāt tu paritrasto na saṃśayaḥ
na hi rocayate tāta yuddhaṃ yuddhaviśārada', null, 6053010),
('ramayana-6-53-11', 11, 'Yuddha Kanda, Sarga 53, Verse 11', 'कश्चिन्मे त्वत्समो नास्ति सौहृदेन बलेन च।
गच्छ शत्रुवधाय त्वं कुम्भकर्णजयाय च॥', 'kaś cin me tvatsamo nāsti sauhṛdena balena ca
gaccha śatruvadhāya tvaṃ kumbhakarṇajayāya ca', null, 6053011),
('ramayana-6-53-12', 12, 'Yuddha Kanda, Sarga 53, Verse 12', 'आददे निशितं शूलं वेगाच्छत्रुनिबर्हणः।
सर्वकालायसं दीप्तं तप्तकाञ्चनभूषणम्॥', 'ādade niśitaṃ śūlaṃ vegāc chatrunibarhaṇaḥ
sarvakālāyasaṃ dīptaṃ taptakāñcanabhūṣaṇam', null, 6053012),
('ramayana-6-53-13', 13, 'Yuddha Kanda, Sarga 53, Verse 13', 'इन्द्राशनिसमं भीमं वज्रप्रतिमगौरवम्।
देवदानवगन्धर्वयक्षकिंनरसूदनम्॥', 'indrāśanisamaṃ bhīmaṃ vajrapratimagauravam
devadānavagandharvayakṣakiṃnarasūdanam', null, 6053013),
('ramayana-6-53-14', 14, 'Yuddha Kanda, Sarga 53, Verse 14', 'रक्तमाल्य महादाम स्वतश्चोद्गतपावकम्।
आदाय निशितं शूलं शत्रुशोणितरञ्जितम्।
कुम्भकर्णो महातेजा रावणं वाक्यमब्रवीत्॥', 'raktamālya mahādāma svataś codgatapāvakam
ādāya niśitaṃ śūlaṃ śatruśoṇitarañjitam
kumbhakarṇo mahātejā rāvaṇaṃ vākyam abravīt', null, 6053014),
('ramayana-6-53-15', 15, 'Yuddha Kanda, Sarga 53, Verse 15', 'गमिष्याम्यहमेकाकी तिष्ठत्विह बलं महत्।
अद्य तान्क्षुधितः क्रुद्धो भक्षयिष्यामि वानरान्॥', 'gamiṣyāmy aham ekākī tiṣṭhatv iha balaṃ mahat
adya tān kṣudhitaḥ kruddho bhakṣayiṣyāmi vānarān', null, 6053015),
('ramayana-6-53-16', 16, 'Yuddha Kanda, Sarga 53, Verse 16', 'कुम्भकर्णवचः श्रुत्वा रावणो वाक्यमब्रवीत्।
सैन्यैः परिवृतो गच्छ शूलमुद्गलपाणिभिः॥', 'kumbhakarṇavacaḥ śrutvā rāvaṇo vākyam abravīt
sainyaiḥ parivṛto gaccha śūlamudgalapāṇibhiḥ', null, 6053016),
('ramayana-6-53-17', 17, 'Yuddha Kanda, Sarga 53, Verse 17', 'वानरा हि महात्मानः शीघ्राश्च व्यवसायिनः।
एकाकिनं प्रमत्तं वा नयेयुर्दशनैः क्षयम्॥', 'vānarā hi mahātmānaḥ śīghrāś ca vyavasāyinaḥ
ekākinaṃ pramattaṃ vā nayeyur daśanaiḥ kṣayam', null, 6053017),
('ramayana-6-53-18', 18, 'Yuddha Kanda, Sarga 53, Verse 18', 'तस्मात्परमदुर्धर्षैः सैन्यैः परिवृतो व्रज।
रक्षसामहितं सर्वं शत्रुपक्षं निसूदय॥', 'tasmāt paramadurdharṣaiḥ sainyaiḥ parivṛto vraja
rakṣasām ahitaṃ sarvaṃ śatrupakṣaṃ nisūdaya', null, 6053018),
('ramayana-6-53-19', 19, 'Yuddha Kanda, Sarga 53, Verse 19', 'अथासनात्समुत्पत्य स्रजं मणिकृतान्तराम्।
आबबन्ध महातेजाः कुम्भकर्णस्य रावणः॥', 'athāsanāt samutpatya srajaṃ maṇikṛtāntarām
ābabandha mahātejāḥ kumbhakarṇasya rāvaṇaḥ', null, 6053019),
('ramayana-6-53-20', 20, 'Yuddha Kanda, Sarga 53, Verse 20', 'अङ्गदानङ्गुलीवेष्टान्वराण्याभरणानि च।
हारं च शशिसंकाशमाबबन्ध महात्मनः॥', 'aṅgadān aṅgulīveṣṭān varāṇy ābharaṇāni ca
hāraṃ ca śaśisaṃkāśam ābabandha mahātmanaḥ', null, 6053020),
('ramayana-6-53-21', 21, 'Yuddha Kanda, Sarga 53, Verse 21', 'दिव्यानि च सुगन्धीनि माल्यदामानि रावणः।
श्रोत्रे चासज्जयामास श्रीमती चास्य कुण्डले॥', 'divyāni ca sugandhīni mālyadāmāni rāvaṇaḥ
śrotre cāsajjayām āsa śrīmatī cāsya kuṇḍale', null, 6053021),
('ramayana-6-53-22', 22, 'Yuddha Kanda, Sarga 53, Verse 22', 'काञ्चनाङ्गदकेयूरो निष्काभरणभूषितः।
कुम्भकर्णो बृहत्कर्णः सुहुतोऽग्निरिवाबभौ॥', 'kāñcanāṅgadakeyūro niṣkābharaṇabhūṣitaḥ
kumbhakarṇo bṛhatkarṇaḥ suhuto ''gnir ivābabhau', null, 6053022),
('ramayana-6-53-23', 23, 'Yuddha Kanda, Sarga 53, Verse 23', 'श्रोणीसूत्रेण महता मेचकेन विराजितः।
अमृतोत्पादने नद्धो भुजंगेनेव मन्दरः॥', 'śroṇīsūtreṇa mahatā mecakena virājitaḥ
amṛtotpādane naddho bhujaṃgeneva mandaraḥ', null, 6053023),
('ramayana-6-53-24', 24, 'Yuddha Kanda, Sarga 53, Verse 24', 'स काञ्चनं भारसहं निवातं विद्युत्प्रभं दीप्तमिवात्मभासा।
आबध्यमानः कवचं रराज संध्याभ्रसंवीत इवाद्रिराजः॥', 'sa kāñcanaṃ bhārasahaṃ nivātaṃ vidyutprabhaṃ dīptam ivātmabhāsā
ābadhyamānaḥ kavacaṃ rarāja saṃdhyābhrasaṃvīta ivādrirājaḥ', null, 6053024),
('ramayana-6-53-25', 25, 'Yuddha Kanda, Sarga 53, Verse 25', 'सर्वाभरणनद्धाङ्गः शूलपाणिः स राक्षसः।
त्रिविक्रमकृतोत्साहो नारायण इवाबभौ॥', 'sarvābharaṇanaddhāṅgaḥ śūlapāṇiḥ sa rākṣasaḥ
trivikramakṛtotsāho nārāyaṇa ivābabhau', null, 6053025),
('ramayana-6-53-26', 26, 'Yuddha Kanda, Sarga 53, Verse 26', 'भ्रातरं संपरिष्वज्य कृत्वा चापि प्रदक्षिणम्।
प्रणम्य शिरसा तस्मै संप्रतस्थे महाबलिः।
तमाशीर्भिः प्रशस्ताभिः प्रेषयामास रावणः॥', 'bhrātaraṃ saṃpariṣvajya kṛtvā cāpi pradakṣiṇam
praṇamya śirasā tasmai saṃpratasthe mahābaliḥ
tam āśīrbhiḥ praśastābhiḥ preṣayām āsa rāvaṇaḥ', null, 6053026),
('ramayana-6-53-27', 27, 'Yuddha Kanda, Sarga 53, Verse 27', 'शङ्खदुन्दुभिनिर्घोषैः सैन्यैश्चापि वरायुधैः।
तं गजैश्च तुरंगैश्च स्यन्दनैश्चाम्बुदस्वनैः।
अनुजग्मुर्महात्मानं रथिनो रथिनां वरम्॥', 'śaṅkhadundubhinirghoṣaiḥ sainyaiś cāpi varāyudhaiḥ
taṃ gajaiś ca turaṃgaiś ca syandanaiś cāmbudasvanaiḥ
anujagmur mahātmānaṃ rathino rathināṃ varam', null, 6053027),
('ramayana-6-53-28', 28, 'Yuddha Kanda, Sarga 53, Verse 28', 'सर्पैरुष्ट्रैः खरैरश्वैः सिंहद्विपमृगद्विजैः।
अनुजग्मुश्च तं घोरं कुम्भकर्णं महाबलम्॥', 'sarpair uṣṭraiḥ kharair aśvaiḥ siṃhadvipamṛgadvijaiḥ
anujagmuś ca taṃ ghoraṃ kumbhakarṇaṃ mahābalam', null, 6053028),
('ramayana-6-53-29', 29, 'Yuddha Kanda, Sarga 53, Verse 29', 'स पुष्पवर्णैरवकीर्यमाणो धृतातपत्रः शितशूलपाणिः।
मदोत्कटः शोणितगन्धमत्तो विनिर्ययौ दानवदेवशत्रुः॥', 'sa puṣpavarṇair avakīryamāṇo dhṛtātapatraḥ śitaśūlapāṇiḥ
madotkaṭaḥ śoṇitagandhamatto viniryayau dānavadevaśatruḥ', null, 6053029),
('ramayana-6-53-30', 30, 'Yuddha Kanda, Sarga 53, Verse 30', 'पदातयश बहवो महानादा महाबलाः।
अन्वयू राक्षसा भीमा भीमाक्षाः शस्त्रपाणयः॥', 'padātayaś a bahavo mahānādā mahābalāḥ
anvayū rākṣasā bhīmā bhīmākṣāḥ śastrapāṇayaḥ', null, 6053030),
('ramayana-6-53-31', 31, 'Yuddha Kanda, Sarga 53, Verse 31', 'रक्ताक्षाः सुमहाकाया नीलाञ्जनचयोपमाः।
शूरानुद्यम्य खड्गांश्च निशितांश्च परश्वधान्॥', 'raktākṣāḥ sumahākāyā nīlāñjanacayopamāḥ
śūrān udyamya khaḍgāṃś ca niśitāṃś ca paraśvadhān', null, 6053031),
('ramayana-6-53-32', 32, 'Yuddha Kanda, Sarga 53, Verse 32', 'बहुव्यामांश्च विपुलान्क्षेपणीयान्दुरासदान्।
तालस्कन्धांश्च विपुलान्क्षेपणीयान्दुरासदान्॥', 'bahuvyāmāṃś ca vipulān kṣepaṇīyān durāsadān
tālaskandhāṃś ca vipulān kṣepaṇīyān durāsadān', null, 6053032),
('ramayana-6-53-33', 33, 'Yuddha Kanda, Sarga 53, Verse 33', 'अथान्यद्वपुरादाय दारुणं लोमहर्षणम्।
निष्पपात महातेजाः कुम्भकर्णो महाबलः॥', 'athānyad vapur ādāya dāruṇaṃ lomaharṣaṇam
niṣpapāta mahātejāḥ kumbhakarṇo mahābalaḥ', null, 6053033),
('ramayana-6-53-34', 34, 'Yuddha Kanda, Sarga 53, Verse 34', 'धनुःशतपरीणाहः स षट्शतसमुच्छितः।
रौद्रः शकटचक्राक्षो महापर्वतसंनिभः॥', 'dhanuḥśataparīṇāhaḥ sa ṣaṭśatasamucchitaḥ
raudraḥ śakaṭacakrākṣo mahāparvatasaṃnibhaḥ', null, 6053034),
('ramayana-6-53-35', 35, 'Yuddha Kanda, Sarga 53, Verse 35', 'संनिपत्य च रक्षांसि दग्धशैलोपमो महान्।
कुम्भकर्णो महावक्त्रः प्रहसन्निदमब्रवीत्॥', 'saṃnipatya ca rakṣāṃsi dagdhaśailopamo mahān
kumbhakarṇo mahāvaktraḥ prahasann idam abravīt', null, 6053035),
('ramayana-6-53-36', 36, 'Yuddha Kanda, Sarga 53, Verse 36', 'अद्य वानरमुख्यानां तानि यूथानि भागशः।
निर्दहिष्यामि संक्रुद्धः शलभानिव पावकः॥', 'adya vānaramukhyānāṃ tāni yūthāni bhāgaśaḥ
nirdahiṣyāmi saṃkruddhaḥ śalabhān iva pāvakaḥ', null, 6053036),
('ramayana-6-53-37', 37, 'Yuddha Kanda, Sarga 53, Verse 37', 'नापराध्यन्ति मे कामं वानरा वनचारिणः।
जातिरस्मद्विधानां सा पुरोद्यानविभूषणम्॥', 'nāparādhyanti me kāmaṃ vānarā vanacāriṇaḥ
jātir asmadvidhānāṃ sā purodyānavibhūṣaṇam', null, 6053037),
('ramayana-6-53-38', 38, 'Yuddha Kanda, Sarga 53, Verse 38', 'पुररोधस्य मूलं तु राघवः सहलक्ष्मणः।
हते तस्मिन्हतं सर्वं तं वधिष्यामि संयुगे॥', 'purarodhasya mūlaṃ tu rāghavaḥ sahalakṣmaṇaḥ
hate tasmin hataṃ sarvaṃ taṃ vadhiṣyāmi saṃyuge', null, 6053038),
('ramayana-6-53-39', 39, 'Yuddha Kanda, Sarga 53, Verse 39', 'एवं तस्य ब्रुवाणस्य कुम्भकर्णस्य राक्षसाः।
नादं चक्रुर्महाघोरं कम्पयन्त इवार्णवम्॥', 'evaṃ tasya bruvāṇasya kumbhakarṇasya rākṣasāḥ
nādaṃ cakrur mahāghoraṃ kampayanta ivārṇavam', null, 6053039),
('ramayana-6-53-40', 40, 'Yuddha Kanda, Sarga 53, Verse 40', 'तस्य निष्पततस्तूर्णं कुम्भकर्णस्य धीमतः।
बभूवुर्घोररूपाणि निमित्तानि समन्ततः॥', 'tasya niṣpatatas tūrṇaṃ kumbhakarṇasya dhīmataḥ
babhūvur ghorarūpāṇi nimittāni samantataḥ', null, 6053040),
('ramayana-6-53-41', 41, 'Yuddha Kanda, Sarga 53, Verse 41', 'उल्काशनियुता मेघा विनेदुश्च सुदारुणाः।
ससागरवना चैव वसुधा समकम्पत॥', 'ulkāśaniyutā meghā vineduś ca sudāruṇāḥ
sasāgaravanā caiva vasudhā samakampata', null, 6053041),
('ramayana-6-53-42', 42, 'Yuddha Kanda, Sarga 53, Verse 42', 'घोररूपाः शिवा नेदुः सज्वालकवलैर्मुखैः।
मण्डलान्यपसव्यानि बबन्धुश्च विहंगमाः॥', 'ghorarūpāḥ śivā neduḥ sajvālakavalair mukhaiḥ
maṇḍalāny apasavyāni babandhuś ca vihaṃgamāḥ', null, 6053042),
('ramayana-6-53-43', 43, 'Yuddha Kanda, Sarga 53, Verse 43', 'निष्पपात च गृध्रेऽस्य शूले वै पथि गच्छतः।
प्रास्फुरन्नयनं चास्य सव्यो बाहुरकम्पत॥', 'niṣpapāta ca gṛdhre ''sya śūle vai pathi gacchataḥ
prāsphuran nayanaṃ cāsya savyo bāhur akampata', null, 6053043),
('ramayana-6-53-44', 44, 'Yuddha Kanda, Sarga 53, Verse 44', 'निष्पपात तदा चोक्ला ज्वलन्ती भीमनिस्वना।
आदित्यो निष्प्रभश्चासीन्न प्रवाति सुखोऽनिलः॥', 'niṣpapāta tadā coklā jvalantī bhīmanisvanā
ādityo niṣprabhaś cāsīn na pravāti sukho ''nilaḥ', null, 6053044),
('ramayana-6-53-45', 45, 'Yuddha Kanda, Sarga 53, Verse 45', 'अचिन्तयन्महोत्पातानुत्थितांल्लोमहर्षणान्।
निर्ययौ कुम्भकर्णस्तु कृतान्तबलचोदितः॥', 'acintayan mahotpātān utthitāṃl lomaharṣaṇān
niryayau kumbhakarṇas tu kṛtāntabalacoditaḥ', null, 6053045),
('ramayana-6-53-46', 46, 'Yuddha Kanda, Sarga 53, Verse 46', 'स लङ्घयित्वा प्राकारं पद्भ्यां पर्वतसंनिभः।
ददर्शाभ्रघनप्रख्यं वानरानीकमद्भुतम्॥', 'sa laṅghayitvā prākāraṃ padbhyāṃ parvatasaṃnibhaḥ
dadarśābhraghanaprakhyaṃ vānarānīkam adbhutam', null, 6053046),
('ramayana-6-53-47', 47, 'Yuddha Kanda, Sarga 53, Verse 47', 'ते दृष्ट्वा राक्षसश्रेष्ठं वानराः पर्वतोपमम्।
वायुनुन्ना इव घना ययुः सर्वा दिशस्तदा॥', 'te dṛṣṭvā rākṣasaśreṣṭhaṃ vānarāḥ parvatopamam
vāyununnā iva ghanā yayuḥ sarvā diśas tadā', null, 6053047),
('ramayana-6-53-48', 48, 'Yuddha Kanda, Sarga 53, Verse 48', 'तद्वानरानीकमतिप्रचण्डं दिशो द्रवद्भिन्नमिवाभ्रजालम्।
स कुम्भकर्णः समवेक्ष्य हर्षान्ननाद भूयो घनवद्घनाभः॥', 'tad vānarānīkam atipracaṇḍaṃ diśo dravad bhinnam ivābhrajālam
sa kumbhakarṇaḥ samavekṣya harṣān nanāda bhūyo ghanavad ghanābhaḥ', null, 6053048),
('ramayana-6-53-49', 49, 'Yuddha Kanda, Sarga 53, Verse 49', 'ते तस्य घोरं निनदं निशम्य यथा निनादं दिवि वारिदस्य।
पेतुर्धरण्यां बहवः प्लवंगा निकृत्तमूला इव सालवृक्षाः॥', 'te tasya ghoraṃ ninadaṃ niśamya yathā ninādaṃ divi vāridasya
petur dharaṇyāṃ bahavaḥ plavaṃgā nikṛttamūlā iva sālavṛkṣāḥ', null, 6053049),
('ramayana-6-53-50', 50, 'Yuddha Kanda, Sarga 53, Verse 50', 'विपुलपरिघवान्स कुम्भकर्णो रिपुनिधनाय विनिःसृतो महात्मा।
कपि गणभयमाददत्सुभीमं प्रभुरिव किंकरदण्डवान्युगान्ते॥', 'vipulaparighavān sa kumbhakarṇo ripunidhanāya viniḥsṛto mahātmā
kapi gaṇabhayam ādadat subhīmaṃ prabhur iva kiṃkaradaṇḍavān yugānte', null, 6053050)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 54 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-54-1', 1, 'Yuddha Kanda, Sarga 54, Verse 1', 'स ननाद महानादं समुद्रमभिनादयन्।
जनयन्निव निर्घातान्विधमन्निव पर्वतान्॥', 'sa nanāda mahānādaṃ samudram abhinādayan
janayann iva nirghātān vidhamann iva parvatān', null, 6054001),
('ramayana-6-54-2', 2, 'Yuddha Kanda, Sarga 54, Verse 2', 'तमवध्यं मघवता यमेन वरुणेन च।
प्रेक्ष्य भीमाक्षमायान्तं वानरा विप्रदुद्रुवुः॥', 'tam avadhyaṃ maghavatā yamena varuṇena ca
prekṣya bhīmākṣam āyāntaṃ vānarā vipradudruvuḥ', null, 6054002),
('ramayana-6-54-3', 3, 'Yuddha Kanda, Sarga 54, Verse 3', 'तांस्तु विद्रवतो दृष्ट्वा वालिपुत्रोऽङ्गदोऽब्रवीत्।
नलं नीलं गवाक्षं च कुमुदं च महाबलम्॥', 'tāṃs tu vidravato dṛṣṭvā vāliputro ''ṅgado ''bravīt
nalaṃ nīlaṃ gavākṣaṃ ca kumudaṃ ca mahābalam', null, 6054003),
('ramayana-6-54-4', 4, 'Yuddha Kanda, Sarga 54, Verse 4', 'आत्मानमत्र विस्मृत्य वीर्याण्यभिजनानि च।
क्व गच्छत भयत्रस्ताः प्राकृता हरयो यथा॥', 'ātmānam atra vismṛtya vīryāṇy abhijanāni ca
kva gacchata bhayatrastāḥ prākṛtā harayo yathā', null, 6054004),
('ramayana-6-54-5', 5, 'Yuddha Kanda, Sarga 54, Verse 5', 'साधु सौम्या निवर्तध्वं किं प्राणान्परिरक्षथ।
नालं युद्धाय वै रक्षो महतीयं विभीषिकाः॥', 'sādhu saumyā nivartadhvaṃ kiṃ prāṇān parirakṣatha
nālaṃ yuddhāya vai rakṣo mahatīyaṃ vibhīṣikāḥ', null, 6054005),
('ramayana-6-54-6', 6, 'Yuddha Kanda, Sarga 54, Verse 6', 'महतीमुत्थितामेनां राक्षसानां विभीषिकाम्।
विक्रमाद्विधमिष्यामो निवर्तध्वं प्लवंगमाः॥', 'mahatīm utthitām enāṃ rākṣasānāṃ vibhīṣikām
vikramād vidhamiṣyāmo nivartadhvaṃ plavaṃgamāḥ', null, 6054006),
('ramayana-6-54-7', 7, 'Yuddha Kanda, Sarga 54, Verse 7', 'कृच्छ्रेण तु समाश्वास्य संगम्य च ततस्ततः।
वृक्षाद्रिहस्ता हरयः संप्रतस्थू रणाजिरम्॥', 'kṛcchreṇa tu samāśvāsya saṃgamya ca tatas tataḥ
vṛkṣādrihastā harayaḥ saṃpratasthū raṇājiram', null, 6054007),
('ramayana-6-54-8', 8, 'Yuddha Kanda, Sarga 54, Verse 8', 'ते निवृत्य तु संक्रुद्धाः कुम्भकर्णं वनौकसः।
निजघ्नुः परमक्रुद्धाः समदा इव कुञ्जराः।
प्रांशुभिर्गिरिशृङ्गैश्च शिलाभिश्च महाबलाः॥', 'te nivṛtya tu saṃkruddhāḥ kumbhakarṇaṃ vanaukasaḥ
nijaghnuḥ paramakruddhāḥ samadā iva kuñjarāḥ
prāṃśubhir giriśṛṅgaiś ca śilābhiś ca mahābalāḥ', null, 6054008),
('ramayana-6-54-9', 9, 'Yuddha Kanda, Sarga 54, Verse 9', 'पादपैः पुष्पिताग्रैश्च हन्यमानो न कम्पते।
तस्य गात्रेषु पतिता भिद्यन्ते शतशः शिलाः।
पादपाः पुष्पिताग्राश्च भग्नाः पेतुर्महीतले॥', 'pādapaiḥ puṣpitāgraiś ca hanyamāno na kampate
tasya gātreṣu patitā bhidyante śataśaḥ śilāḥ
pādapāḥ puṣpitāgrāś ca bhagnāḥ petur mahītale', null, 6054009),
('ramayana-6-54-10', 10, 'Yuddha Kanda, Sarga 54, Verse 10', 'सोऽपि सैन्यानि संक्रुद्धो वानराणां महौजसाम्।
ममन्थ परमायत्तो वनान्यग्निरिवोत्थितः॥', 'so ''pi sainyāni saṃkruddho vānarāṇāṃ mahaujasām
mamantha paramāyatto vanāny agnir ivotthitaḥ', null, 6054010),
('ramayana-6-54-11', 11, 'Yuddha Kanda, Sarga 54, Verse 11', 'लोहितार्द्रास्तु बहवः शेरते वानरर्षभाः।
निरस्ताः पतिता भूमौ ताम्रपुष्पा इव द्रुमाः॥', 'lohitārdrās tu bahavaḥ śerate vānararṣabhāḥ
nirastāḥ patitā bhūmau tāmrapuṣpā iva drumāḥ', null, 6054011),
('ramayana-6-54-12', 12, 'Yuddha Kanda, Sarga 54, Verse 12', 'लङ्घयन्तः प्रधावन्तो वानरा नावलोकयन्।
के चित्समुद्रे पतिताः के चिद्गगनमाश्रिताः॥', 'laṅghayantaḥ pradhāvanto vānarā nāvalokayan
ke cit samudre patitāḥ ke cid gaganam āśritāḥ', null, 6054012),
('ramayana-6-54-13', 13, 'Yuddha Kanda, Sarga 54, Verse 13', 'वध्यमानास्तु ते वीरा राक्षसेन बलीयसा।
सागरं येन ते तीर्णाः पथा तेनैव दुद्रुवुः॥', 'vadhyamānās tu te vīrā rākṣasena balīyasā
sāgaraṃ yena te tīrṇāḥ pathā tenaiva dudruvuḥ', null, 6054013),
('ramayana-6-54-14', 14, 'Yuddha Kanda, Sarga 54, Verse 14', 'ते स्थलानि तथा निम्नं विषण्णवदना भयात्।
ऋक्षा वृक्षान्समारूढाः के चित्पर्वतमाश्रिताः॥', 'te sthalāni tathā nimnaṃ viṣaṇṇavadanā bhayāt
ṛkṣā vṛkṣān samārūḍhāḥ ke cit parvatam āśritāḥ', null, 6054014),
('ramayana-6-54-15', 15, 'Yuddha Kanda, Sarga 54, Verse 15', 'ममज्जुरर्णवे के चिद्गुहाः के चित्समाश्रिताः।
निषेदुः प्लवगाः के चित्के चिन्नैवावतस्थिरे॥', 'mamajjur arṇave ke cid guhāḥ ke cit samāśritāḥ
niṣeduḥ plavagāḥ ke cit ke cin naivāvatasthire', null, 6054015),
('ramayana-6-54-16', 16, 'Yuddha Kanda, Sarga 54, Verse 16', 'तान्समीक्ष्याङ्गदो भङ्गान्वानरानिदमब्रवीत्।
अवतिष्ठत युध्यामो निवर्तध्वं प्लवंगमाः॥', 'tān samīkṣyāṅgado bhaṅgān vānarān idam abravīt
avatiṣṭhata yudhyāmo nivartadhvaṃ plavaṃgamāḥ', null, 6054016),
('ramayana-6-54-17', 17, 'Yuddha Kanda, Sarga 54, Verse 17', 'भग्नानां वो न पश्यामि परिगम्य महीमिमाम्।
स्थानं सर्वे निवर्तध्वं किं प्राणान्परिरक्षथ॥', 'bhagnānāṃ vo na paśyāmi parigamya mahīm imām
sthānaṃ sarve nivartadhvaṃ kiṃ prāṇān parirakṣatha', null, 6054017),
('ramayana-6-54-18', 18, 'Yuddha Kanda, Sarga 54, Verse 18', 'निरायुधानां द्रवतामसंगगतिपौरुषाः।
दारा ह्यपहसिष्यन्ति स वै घातस्तु जीविताम्॥', 'nirāyudhānāṃ dravatām asaṃgagatipauruṣāḥ
dārā hy apahasiṣyanti sa vai ghātas tu jīvitām', null, 6054018),
('ramayana-6-54-19', 19, 'Yuddha Kanda, Sarga 54, Verse 19', 'कुलेषु जाताः सर्वे स्म विस्तीर्णेषु महत्सु च।
अनार्याः खलु यद्भीतास्त्यक्त्वा वीर्यं प्रधावत॥', 'kuleṣu jātāḥ sarve sma vistīrṇeṣu mahatsu ca
anāryāḥ khalu yad bhītās tyaktvā vīryaṃ pradhāvata', null, 6054019),
('ramayana-6-54-20', 20, 'Yuddha Kanda, Sarga 54, Verse 20', 'विकत्थनानि वो यानि यदा वै जनसंसदि।
तानि वः क्व च यतानि सोदग्राणि महान्ति च॥', 'vikatthanāni vo yāni yadā vai janasaṃsadi
tāni vaḥ kva ca yatāni sodagrāṇi mahānti ca', null, 6054020),
('ramayana-6-54-21', 21, 'Yuddha Kanda, Sarga 54, Verse 21', 'भीरुप्रवादाः श्रूयन्ते यस्तु जीवति धिक्कृतः।
मार्गः सत्पुरुषैर्जुष्टः सेव्यतां त्यज्यतां भयम्॥', 'bhīrupravādāḥ śrūyante yas tu jīvati dhikkṛtaḥ
mārgaḥ satpuruṣair juṣṭaḥ sevyatāṃ tyajyatāṃ bhayam', null, 6054021),
('ramayana-6-54-22', 22, 'Yuddha Kanda, Sarga 54, Verse 22', 'शयामहे वा निहताः पृथिव्यामल्पजीविताः।
दुष्प्रापं ब्रह्मलोकं वा प्राप्नुमो युधि सूदिताः।
संप्राप्नुयामः कीर्तिं वा निहत्य शत्रुमाहवे॥', 'śayāmahe vā nihatāḥ pṛthivyām alpajīvitāḥ
duṣprāpaṃ brahmalokaṃ vā prāpnumo yudhi sūditāḥ
saṃprāpnuyāmaḥ kīrtiṃ vā nihatya śatrum āhave', null, 6054022),
('ramayana-6-54-23', 23, 'Yuddha Kanda, Sarga 54, Verse 23', 'न कुम्भकर्णः काकुत्स्थं दृष्ट्वा जीवन्गमिष्यति।
दीप्यमानमिवासाद्य पतंगो ज्वलनं यथा॥', 'na kumbhakarṇaḥ kākutsthaṃ dṛṣṭvā jīvan gamiṣyati
dīpyamānam ivāsādya pataṃgo jvalanaṃ yathā', null, 6054023),
('ramayana-6-54-24', 24, 'Yuddha Kanda, Sarga 54, Verse 24', 'पलायनेन चोद्दिष्टाः प्राणान्रक्षामहे वयम्।
एकेन बहवो भग्ना यशो नाशं गमिष्यति॥', 'palāyanena coddiṣṭāḥ prāṇān rakṣāmahe vayam
ekena bahavo bhagnā yaśo nāśaṃ gamiṣyati', null, 6054024),
('ramayana-6-54-25', 25, 'Yuddha Kanda, Sarga 54, Verse 25', 'एवं ब्रुवाणं तं शूरमङ्गदं कनकाङ्गदम्।
द्रवमाणास्ततो वाक्यमूचुः शूरविगर्हितम्॥', 'evaṃ bruvāṇaṃ taṃ śūram aṅgadaṃ kanakāṅgadam
dravamāṇās tato vākyam ūcuḥ śūravigarhitam', null, 6054025),
('ramayana-6-54-26', 26, 'Yuddha Kanda, Sarga 54, Verse 26', 'कृतं नः कदनं घोरं कुम्भकर्णेन रक्षसा।
न स्थानकालो गच्छामो दयितं जीवितं हि नः॥', 'kṛtaṃ naḥ kadanaṃ ghoraṃ kumbhakarṇena rakṣasā
na sthānakālo gacchāmo dayitaṃ jīvitaṃ hi naḥ', null, 6054026),
('ramayana-6-54-27', 27, 'Yuddha Kanda, Sarga 54, Verse 27', 'एतावदुक्त्वा वचनं सर्वे ते भेजिरे दिशः।
भीमं भीमाक्षमायान्तं दृष्ट्वा वानरयूथपाः॥', 'etāvad uktvā vacanaṃ sarve te bhejire diśaḥ
bhīmaṃ bhīmākṣam āyāntaṃ dṛṣṭvā vānarayūthapāḥ', null, 6054027),
('ramayana-6-54-28', 28, 'Yuddha Kanda, Sarga 54, Verse 28', 'द्रवमाणास्तु ते वीरा अङ्गदेन वलीमुखाः।
सान्त्वैश्च बहुमानैश्च ततः सर्वे निवर्तिताः॥', 'dravamāṇās tu te vīrā aṅgadena valīmukhāḥ
sāntvaiś ca bahumānaiś ca tataḥ sarve nivartitāḥ', null, 6054028),
('ramayana-6-54-29', 29, 'Yuddha Kanda, Sarga 54, Verse 29', 'ऋषभशरभमैन्दधूम्रनीलाः कुमुदसुषेणगवाक्षरम्भताराः।
द्विविदपनसवायुपुत्रमुख्यास्त्वरिततराभिमुखं रणं प्रयाताः॥', 'ṛṣabhaśarabhamaindadhūmranīlāḥ kumudasuṣeṇagavākṣarambhatārāḥ
dvividapanasavāyuputramukhyās tvaritatarābhimukhaṃ raṇaṃ prayātāḥ', null, 6054029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 55 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-55-1', 1, 'Yuddha Kanda, Sarga 55, Verse 1', 'ते निवृत्ता महाकायाः श्रुत्वाङ्गदवचस्तदा।
नैष्ठिकीं बुद्धिमास्थाय सर्वे संग्रामकाङ्क्षिणः॥', 'te nivṛttā mahākāyāḥ śrutvāṅgadavacas tadā
naiṣṭhikīṃ buddhim āsthāya sarve saṃgrāmakāṅkṣiṇaḥ', null, 6055001),
('ramayana-6-55-2', 2, 'Yuddha Kanda, Sarga 55, Verse 2', 'समुदीरितवीर्यास्ते समारोपितविक्रमाः।
पर्यवस्थापिता वाक्यैरङ्गदेन वलीमुखाः॥', 'samudīritavīryās te samāropitavikramāḥ
paryavasthāpitā vākyair aṅgadena valīmukhāḥ', null, 6055002),
('ramayana-6-55-3', 3, 'Yuddha Kanda, Sarga 55, Verse 3', 'प्रयाताश्च गता हर्षं मरणे कृतनिश्चयाः।
चक्रुः सुतुमुलं युद्धं वानरास्त्यक्तजीविताः॥', 'prayātāś ca gatā harṣaṃ maraṇe kṛtaniścayāḥ
cakruḥ sutumulaṃ yuddhaṃ vānarās tyaktajīvitāḥ', null, 6055003),
('ramayana-6-55-4', 4, 'Yuddha Kanda, Sarga 55, Verse 4', 'अथ वृक्षान्महाकायाः सानूनि सुमहान्ति च।
वानरास्तूर्णमुद्यम्य कुम्भकर्णमभिद्रवन्॥', 'atha vṛkṣān mahākāyāḥ sānūni sumahānti ca
vānarās tūrṇam udyamya kumbhakarṇam abhidravan', null, 6055004),
('ramayana-6-55-5', 5, 'Yuddha Kanda, Sarga 55, Verse 5', 'स कुम्भकर्णः संक्रुद्धो गदामुद्यम्य वीर्यवान्।
अर्दयन्सुमहाकायः समन्ताद्व्याक्षिपद्रिपून्॥', 'sa kumbhakarṇaḥ saṃkruddho gadām udyamya vīryavān
ardayan sumahākāyaḥ samantād vyākṣipad ripūn', null, 6055005),
('ramayana-6-55-6', 6, 'Yuddha Kanda, Sarga 55, Verse 6', 'शतानि सप्त चाष्टौ च सहस्राणि च वानराः।
प्रकीर्णाः शेरते भूमौ कुम्भकर्णेन पोथिताः॥', 'śatāni sapta cāṣṭau ca sahasrāṇi ca vānarāḥ
prakīrṇāḥ śerate bhūmau kumbhakarṇena pothitāḥ', null, 6055006),
('ramayana-6-55-7', 7, 'Yuddha Kanda, Sarga 55, Verse 7', 'षोडशाष्टौ च दश च विंशत्त्रिंशत्तथैव च।
परिक्षिप्य च बाहुभ्यां खादन्विपरिधावति।
भक्षयन्भृशसंक्रुद्धो गरुडः पन्नगानिव॥', 'ṣoḍaśāṣṭau ca daśa ca viṃśat triṃśat tathaiva ca
parikṣipya ca bāhubhyāṃ khādan viparidhāvati
bhakṣayan bhṛśasaṃkruddho garuḍaḥ pannagān iva', null, 6055007),
('ramayana-6-55-8', 8, 'Yuddha Kanda, Sarga 55, Verse 8', 'हनूमाञ्शैलशृङ्गाणि वृक्षांश्च विविधान्बहून्।
ववर्ष कुम्भकर्णस्य शिरस्यम्बरमास्थितः॥', 'hanūmāñ śailaśṛṅgāṇi vṛkṣāṃś ca vividhān bahūn
vavarṣa kumbhakarṇasya śirasy ambaram āsthitaḥ', null, 6055008),
('ramayana-6-55-9', 9, 'Yuddha Kanda, Sarga 55, Verse 9', 'तानि पर्वतशृङ्गाणि शूलेन तु बिभेद ह।
बभञ्ज वृक्षवर्षं च कुम्भकर्णो महाबलः॥', 'tāni parvataśṛṅgāṇi śūlena tu bibheda ha
babhañja vṛkṣavarṣaṃ ca kumbhakarṇo mahābalaḥ', null, 6055009),
('ramayana-6-55-10', 10, 'Yuddha Kanda, Sarga 55, Verse 10', 'ततो हरीणां तदनीकमुग्रं दुद्राव शूलं निशितं प्रगृह्य।
तस्थौ ततोऽस्यापततः पुरस्तान्महीधराग्रं हनुमान्प्रगृह्य॥', 'tato harīṇāṃ tad anīkam ugraṃ dudrāva śūlaṃ niśitaṃ pragṛhya
tasthau tato ''syāpatataḥ purastān mahīdharāgraṃ hanumān pragṛhya', null, 6055010),
('ramayana-6-55-11', 11, 'Yuddha Kanda, Sarga 55, Verse 11', 'स कुम्भकर्णं कुपितो जघान वेगेन शैलोत्तमभीमकायम्।
स चुक्षुभे तेन तदाभिबूतो मेदार्द्रगात्रो रुधिरावसिक्तः॥', 'sa kumbhakarṇaṃ kupito jaghāna vegena śailottamabhīmakāyam
sa cukṣubhe tena tadābhibūto medārdragātro rudhirāvasiktaḥ', null, 6055011),
('ramayana-6-55-12', 12, 'Yuddha Kanda, Sarga 55, Verse 12', 'स शूलमाविध्य तडित्प्रकाशं गिरिं यथा प्रज्वलिताग्रशृङ्गम्।
बाह्वन्तरे मारुतिमाजघान गुहोऽचलं क्रौञ्चमिवोग्रशक्त्या॥', 'sa śūlam āvidhya taḍitprakāśaṃ giriṃ yathā prajvalitāgraśṛṅgam
bāhvantare mārutim ājaghāna guho ''calaṃ krauñcam ivograśaktyā', null, 6055012),
('ramayana-6-55-13', 13, 'Yuddha Kanda, Sarga 55, Verse 13', 'स शूलनिर्भिन्न महाभुजान्तरः प्रविह्वलः शोणितमुद्वमन्मुखात्।
ननाद भीमं हनुमान्महाहवे युगान्तमेघस्तनितस्वनोपमम्॥', 'sa śūlanirbhinna mahābhujāntaraḥ pravihvalaḥ śoṇitam udvaman mukhāt
nanāda bhīmaṃ hanumān mahāhave yugāntameghastanitasvanopamam', null, 6055013),
('ramayana-6-55-14', 14, 'Yuddha Kanda, Sarga 55, Verse 14', 'ततो विनेदुः सहसा प्रहृष्टा रक्षोगणास्तं व्यथितं समीक्ष्य।
प्लवंगमास्तु व्यथिता भयार्ताः प्रदुद्रुवुः संयति कुम्भकर्णात्॥', 'tato vineduḥ sahasā prahṛṣṭā rakṣogaṇās taṃ vyathitaṃ samīkṣya
plavaṃgamās tu vyathitā bhayārtāḥ pradudruvuḥ saṃyati kumbhakarṇāt', null, 6055014),
('ramayana-6-55-15', 15, 'Yuddha Kanda, Sarga 55, Verse 15', 'नीलश्चिक्षेप शैलाग्रं कुम्भकर्णाय धीमते।
तमापतन्तं संप्रेक्ष्य मुष्टिनाभिजघान ह॥', 'nīlaś cikṣepa śailāgraṃ kumbhakarṇāya dhīmate
tam āpatantaṃ saṃprekṣya muṣṭinābhijaghāna ha', null, 6055015),
('ramayana-6-55-16', 16, 'Yuddha Kanda, Sarga 55, Verse 16', 'मुष्टिप्रहाराभिहतं तच्छैलाग्रं व्यशीर्यत।
सविस्फुलिङ्गं सज्वालं निपपात महीतले॥', 'muṣṭiprahārābhihataṃ tac chailāgraṃ vyaśīryata
savisphuliṅgaṃ sajvālaṃ nipapāta mahītale', null, 6055016),
('ramayana-6-55-17', 17, 'Yuddha Kanda, Sarga 55, Verse 17', 'ऋषभः शरभो नीलो गवाक्षो गन्धमादनः।
पञ्चवानरशार्दूलाः कुम्भकर्णमुपाद्रवन्॥', 'ṛṣabhaḥ śarabho nīlo gavākṣo gandhamādanaḥ
pañcavānaraśārdūlāḥ kumbhakarṇam upādravan', null, 6055017),
('ramayana-6-55-18', 18, 'Yuddha Kanda, Sarga 55, Verse 18', 'शैलैर्वृक्षैस्तलैः पादैर्मुष्टिभिश्च महाबलाः।
कुम्भकर्णं महाकायं सर्वतोऽभिनिजघ्निरे॥', 'śailair vṛkṣais talaiḥ pādair muṣṭibhiś ca mahābalāḥ
kumbhakarṇaṃ mahākāyaṃ sarvato ''bhinijaghnire', null, 6055018),
('ramayana-6-55-19', 19, 'Yuddha Kanda, Sarga 55, Verse 19', 'स्पर्शानिव प्रहारांस्तान्वेदयानो न विव्यथे।
ऋषभं तु महावेगं बाहुभ्यां परिषस्वजे॥', 'sparśān iva prahārāṃs tān vedayāno na vivyathe
ṛṣabhaṃ tu mahāvegaṃ bāhubhyāṃ pariṣasvaje', null, 6055019),
('ramayana-6-55-20', 20, 'Yuddha Kanda, Sarga 55, Verse 20', 'कुम्भकर्णभुजाभ्यां तु पीडितो वानरर्षभः।
निपपातर्षभो भीमः प्रमुखागतशोणितः॥', 'kumbhakarṇabhujābhyāṃ tu pīḍito vānararṣabhaḥ
nipapātarṣabho bhīmaḥ pramukhāgataśoṇitaḥ', null, 6055020),
('ramayana-6-55-21', 21, 'Yuddha Kanda, Sarga 55, Verse 21', 'मुष्टिना शरभं हत्वा जानुना नीलमाहवे।
आजघान गवाक्षं च तलेनेन्द्ररिपुस्तदा॥', 'muṣṭinā śarabhaṃ hatvā jānunā nīlam āhave
ājaghāna gavākṣaṃ ca talenendraripus tadā', null, 6055021),
('ramayana-6-55-22', 22, 'Yuddha Kanda, Sarga 55, Verse 22', 'दत्तप्रहरव्यथिता मुमुहुः शोणितोक्षिताः।
निपेतुस्ते तु मेदिन्यां निकृत्ता इव किंशुकाः॥', 'dattapraharavyathitā mumuhuḥ śoṇitokṣitāḥ
nipetus te tu medinyāṃ nikṛttā iva kiṃśukāḥ', null, 6055022),
('ramayana-6-55-23', 23, 'Yuddha Kanda, Sarga 55, Verse 23', 'तेषु वानरमुख्येषु पतितेषु महात्मसु।
वानराणां सहस्राणि कुम्भकर्णं प्रदुद्रुवुः॥', 'teṣu vānaramukhyeṣu patiteṣu mahātmasu
vānarāṇāṃ sahasrāṇi kumbhakarṇaṃ pradudruvuḥ', null, 6055023),
('ramayana-6-55-24', 24, 'Yuddha Kanda, Sarga 55, Verse 24', 'तं शैलमिव शैलाभाः सर्वे तु प्लवगर्षभाः।
समारुह्य समुत्पत्य ददंशुश्च महाबलाः॥', 'taṃ śailam iva śailābhāḥ sarve tu plavagarṣabhāḥ
samāruhya samutpatya dadaṃśuś ca mahābalāḥ', null, 6055024),
('ramayana-6-55-25', 25, 'Yuddha Kanda, Sarga 55, Verse 25', 'तं नखैर्दशनैश्चापि मुष्टिभिर्जानुभिस्तथा।
कुम्भकर्णं महाकायं ते जघ्नुः प्लवगर्षभाः॥', 'taṃ nakhair daśanaiś cāpi muṣṭibhir jānubhis tathā
kumbhakarṇaṃ mahākāyaṃ te jaghnuḥ plavagarṣabhāḥ', null, 6055025),
('ramayana-6-55-26', 26, 'Yuddha Kanda, Sarga 55, Verse 26', 'स वानरसहस्रैस्तैराचितः पर्वतोपमः।
रराज राक्षसव्याघ्रो गिरिरात्मरुहैरिव॥', 'sa vānarasahasrais tair ācitaḥ parvatopamaḥ
rarāja rākṣasavyāghro girir ātmaruhair iva', null, 6055026),
('ramayana-6-55-27', 27, 'Yuddha Kanda, Sarga 55, Verse 27', 'बाहुभ्यां वानरान्सर्वान्प्रगृह्य स महाबलः।
भक्षयामास संक्रुद्धो गरुडः पन्नगानिव॥', 'bāhubhyāṃ vānarān sarvān pragṛhya sa mahābalaḥ
bhakṣayām āsa saṃkruddho garuḍaḥ pannagān iva', null, 6055027),
('ramayana-6-55-28', 28, 'Yuddha Kanda, Sarga 55, Verse 28', 'प्रक्षिप्ताः कुम्भकर्णेन वक्त्रे पातालसंनिभे।
नासा पुटाभ्यां निर्जग्मुः कर्णाभ्यां चैव वानराः॥', 'prakṣiptāḥ kumbhakarṇena vaktre pātālasaṃnibhe
nāsā puṭābhyāṃ nirjagmuḥ karṇābhyāṃ caiva vānarāḥ', null, 6055028),
('ramayana-6-55-29', 29, 'Yuddha Kanda, Sarga 55, Verse 29', 'भक्षयन्भृशसंक्रुद्धो हरीन्पर्वतसंनिभः।
बभञ्ज वानरान्सर्वान्संक्रुद्धो राक्षसोत्तमः॥', 'bhakṣayan bhṛśasaṃkruddho harīn parvatasaṃnibhaḥ
babhañja vānarān sarvān saṃkruddho rākṣasottamaḥ', null, 6055029),
('ramayana-6-55-30', 30, 'Yuddha Kanda, Sarga 55, Verse 30', 'मांसशोणितसंक्लेदां भूमिं कुर्वन्स राक्षसः।
चचार हरिसैन्येषु कालाग्निरिव मूर्छितः॥', 'māṃsaśoṇitasaṃkledāṃ bhūmiṃ kurvan sa rākṣasaḥ
cacāra harisainyeṣu kālāgnir iva mūrchitaḥ', null, 6055030),
('ramayana-6-55-31', 31, 'Yuddha Kanda, Sarga 55, Verse 31', 'वज्रहस्तो यथा शक्रः पाशहस्त इवान्तकः।
शूलहस्तो बभौ तस्मिन्कुम्भकर्णो महाबलः॥', 'vajrahasto yathā śakraḥ pāśahasta ivāntakaḥ
śūlahasto babhau tasmin kumbhakarṇo mahābalaḥ', null, 6055031),
('ramayana-6-55-32', 32, 'Yuddha Kanda, Sarga 55, Verse 32', 'यथा शुष्काण्यरण्यानि ग्रीष्मे दहति पावकः।
तथा वानरसैन्यानि कुम्भकर्णो विनिर्दहत्॥', 'yathā śuṣkāṇy araṇyāni grīṣme dahati pāvakaḥ
tathā vānarasainyāni kumbhakarṇo vinirdahat', null, 6055032),
('ramayana-6-55-33', 33, 'Yuddha Kanda, Sarga 55, Verse 33', 'ततस्ते वध्यमानास्तु हतयूथा विनायकाः।
वानरा भयसंविग्ना विनेदुर्विस्वरं भृशम्॥', 'tatas te vadhyamānās tu hatayūthā vināyakāḥ
vānarā bhayasaṃvignā vinedur visvaraṃ bhṛśam', null, 6055033),
('ramayana-6-55-34', 34, 'Yuddha Kanda, Sarga 55, Verse 34', 'अनेकशो वध्यमानाः कुम्भकर्णेन वानराः।
राघवं शरणं जग्मुर्व्यथिताः खिन्नचेतसः॥', 'anekaśo vadhyamānāḥ kumbhakarṇena vānarāḥ
rāghavaṃ śaraṇaṃ jagmur vyathitāḥ khinnacetasaḥ', null, 6055034),
('ramayana-6-55-35', 35, 'Yuddha Kanda, Sarga 55, Verse 35', 'तमापतन्तं संप्रेक्ष्य कुम्भकर्णं महाबलम्।
उत्पपात तदा वीरः सुग्रीवो वानराधिपः॥', 'tam āpatantaṃ saṃprekṣya kumbhakarṇaṃ mahābalam
utpapāta tadā vīraḥ sugrīvo vānarādhipaḥ', null, 6055035),
('ramayana-6-55-36', 36, 'Yuddha Kanda, Sarga 55, Verse 36', 'स पर्वताग्रमुत्क्षिप्य समाविध्य महाकपिः।
अभिदुद्राव वेगेन कुम्भकर्णं महाबलम्॥', 'sa parvatāgram utkṣipya samāvidhya mahākapiḥ
abhidudrāva vegena kumbhakarṇaṃ mahābalam', null, 6055036),
('ramayana-6-55-37', 37, 'Yuddha Kanda, Sarga 55, Verse 37', 'तमापतन्तं संप्रेक्ष्य कुम्भकर्णः प्लवंगमम्।
तस्थौ विवृतसर्वाङ्गो वानरेन्द्रस्य संमुखः॥', 'tam āpatantaṃ saṃprekṣya kumbhakarṇaḥ plavaṃgamam
tasthau vivṛtasarvāṅgo vānarendrasya saṃmukhaḥ', null, 6055037),
('ramayana-6-55-38', 38, 'Yuddha Kanda, Sarga 55, Verse 38', 'कपिशोणितदिग्धाङ्गं भक्षयन्तं महाकपीन्।
कुम्भकर्णं स्थितं दृष्ट्वा सुग्रीवो वाक्यमब्रवीत्॥', 'kapiśoṇitadigdhāṅgaṃ bhakṣayantaṃ mahākapīn
kumbhakarṇaṃ sthitaṃ dṛṣṭvā sugrīvo vākyam abravīt', null, 6055038),
('ramayana-6-55-39', 39, 'Yuddha Kanda, Sarga 55, Verse 39', 'पातिताश्च त्वया वीराः कृतं कर्म सुदुष्करम्।
भक्षितानि च सैन्यानि प्राप्तं ते परमं यशः॥', 'pātitāś ca tvayā vīrāḥ kṛtaṃ karma suduṣkaram
bhakṣitāni ca sainyāni prāptaṃ te paramaṃ yaśaḥ', null, 6055039),
('ramayana-6-55-40', 40, 'Yuddha Kanda, Sarga 55, Verse 40', 'त्यज तद्वानरानीकं प्राकृतैः किं करिष्यसि।
सहस्वैकं निपातं मे पर्वतस्यास्य राक्षस॥', 'tyaja tad vānarānīkaṃ prākṛtaiḥ kiṃ kariṣyasi
sahasvaikaṃ nipātaṃ me parvatasyāsya rākṣasa', null, 6055040),
('ramayana-6-55-41', 41, 'Yuddha Kanda, Sarga 55, Verse 41', 'तद्वाक्यं हरिराजस्य सत्त्वधैर्यसमन्वितम्।
श्रुत्वा राक्षसशार्दूलः कुम्भकर्णोऽब्रवीद्वचः॥', 'tad vākyaṃ harirājasya sattvadhairyasamanvitam
śrutvā rākṣasaśārdūlaḥ kumbhakarṇo ''bravīd vacaḥ', null, 6055041),
('ramayana-6-55-42', 42, 'Yuddha Kanda, Sarga 55, Verse 42', 'प्रजापतेस्तु पौत्रस्त्वं तथैवर्क्षरजःसुतः।
श्रुतपौरुषसंपन्नस्तस्माद्गर्जसि वानर॥', 'prajāpates tu pautras tvaṃ tathaivarkṣarajaḥsutaḥ
śrutapauruṣasaṃpannas tasmād garjasi vānara', null, 6055042),
('ramayana-6-55-43', 43, 'Yuddha Kanda, Sarga 55, Verse 43', 'स कुम्भकर्णस्य वचो निशम्य व्याविध्य शैलं सहसा मुमोच।
तेनाजघानोरसि कुम्भकर्णं शैलेन वज्राशनिसंनिभेन॥', 'sa kumbhakarṇasya vaco niśamya vyāvidhya śailaṃ sahasā mumoca
tenājaghānorasi kumbhakarṇaṃ śailena vajrāśanisaṃnibhena', null, 6055043),
('ramayana-6-55-44', 44, 'Yuddha Kanda, Sarga 55, Verse 44', 'तच्छैलशृङ्गं सहसा विकीर्णं भुजान्तरे तस्य तदा विशाले।
ततो विषेदुः सहसा प्लवंगमा रक्षोगणाश्चापि मुदा विनेदुः॥', 'tac chailaśṛṅgaṃ sahasā vikīrṇaṃ bhujāntare tasya tadā viśāle
tato viṣeduḥ sahasā plavaṃgamā rakṣogaṇāś cāpi mudā vineduḥ', null, 6055044),
('ramayana-6-55-45', 45, 'Yuddha Kanda, Sarga 55, Verse 45', 'स शैलशृङ्गाभिहतश्चुकोप ननाद कोपाच्च विवृत्य वक्त्रम्।
व्याविध्य शूलं च तडित्प्रकाशं चिक्षेप हर्यृक्षपतेर्वधाय॥', 'sa śailaśṛṅgābhihataś cukopa nanāda kopāc ca vivṛtya vaktram
vyāvidhya śūlaṃ ca taḍitprakāśaṃ cikṣepa haryṛkṣapater vadhāya', null, 6055045),
('ramayana-6-55-46', 46, 'Yuddha Kanda, Sarga 55, Verse 46', 'तत्कुम्भकर्णस्य भुजप्रविद्धं शूलं शितं काञ्चनदामजुष्टम्।
क्षिप्रं समुत्पत्य निगृह्य दोर्भ्यां बभञ्ज वेगेन सुतोऽनिलस्य॥', 'tat kumbhakarṇasya bhujapraviddhaṃ śūlaṃ śitaṃ kāñcanadāmajuṣṭam
kṣipraṃ samutpatya nigṛhya dorbhyāṃ babhañja vegena suto ''nilasya', null, 6055046),
('ramayana-6-55-47', 47, 'Yuddha Kanda, Sarga 55, Verse 47', 'कृतं भारसहस्रस्य शूलं कालायसं महत्।
बभञ्ज जनौमारोप्य प्रहृष्टः प्लवगर्षभः॥', 'kṛtaṃ bhārasahasrasya śūlaṃ kālāyasaṃ mahat
babhañja janaum āropya prahṛṣṭaḥ plavagarṣabhaḥ', null, 6055047),
('ramayana-6-55-48', 48, 'Yuddha Kanda, Sarga 55, Verse 48', 'स तत्तदा भग्नमवेक्ष्य शूलं चुकोप रक्षोऽधिपतिर्महात्मा।
उत्पाट्य लङ्कामलयात्स शृङ्गं जघान सुग्रीवमुपेत्य तेन॥', 'sa tat tadā bhagnam avekṣya śūlaṃ cukopa rakṣo''dhipatir mahātmā
utpāṭya laṅkāmalayāt sa śṛṅgaṃ jaghāna sugrīvam upetya tena', null, 6055048),
('ramayana-6-55-49', 49, 'Yuddha Kanda, Sarga 55, Verse 49', 'स शैलशृङ्गाभिहतो विसंज्ञः पपात भूमौ युधि वानरेन्द्रः।
तं प्रेक्ष्य भूमौ पतितं विसंज्ञं नेदुः प्रहृष्टा युधि यातुधानाः॥', 'sa śailaśṛṅgābhihato visaṃjñaḥ papāta bhūmau yudhi vānarendraḥ
taṃ prekṣya bhūmau patitaṃ visaṃjñaṃ neduḥ prahṛṣṭā yudhi yātudhānāḥ', null, 6055049),
('ramayana-6-55-50', 50, 'Yuddha Kanda, Sarga 55, Verse 50', 'तमभ्युपेत्याद्भुतघोरवीर्यं स कुम्भकर्णो युधि वानरेन्द्रम्।
जहार सुग्रीवमभिप्रगृह्य यथानिलो मेघमतिप्रचण्डः॥', 'tam abhyupetyādbhutaghoravīryaṃ sa kumbhakarṇo yudhi vānarendram
jahāra sugrīvam abhipragṛhya yathānilo megham atipracaṇḍaḥ', null, 6055050),
('ramayana-6-55-51', 51, 'Yuddha Kanda, Sarga 55, Verse 51', 'स तं महामेघनिकाशरूपमुत्पाट्य गच्छन्युधि कुम्भकर्णः।
रराज मेरुप्रतिमानरूपो मेरुर्यथात्युच्छ्रितघोरशृङ्गः॥', 'sa taṃ mahāmeghanikāśarūpam utpāṭya gacchan yudhi kumbhakarṇaḥ
rarāja merupratimānarūpo merur yathātyucchritaghoraśṛṅgaḥ', null, 6055051),
('ramayana-6-55-52', 52, 'Yuddha Kanda, Sarga 55, Verse 52', 'ततः समुत्पाट्य जगाम वीरः संस्तूयमानो युधि राक्षसेन्द्रैः।
शृण्वन्निनादं त्रिदशालयानां प्लवंगराजग्रहविस्मितानाम्॥', 'tataḥ samutpāṭya jagāma vīraḥ saṃstūyamāno yudhi rākṣasendraiḥ
śṛṇvan ninādaṃ tridaśālayānāṃ plavaṃgarājagrahavismitānām', null, 6055052),
('ramayana-6-55-53', 53, 'Yuddha Kanda, Sarga 55, Verse 53', 'ततस्तमादाय तदा स मेने हरीन्द्रमिन्द्रोपममिन्द्रवीर्यः।
अस्मिन्हृते सर्वमिदं हृतं स्यात्सराघवं सैन्यमितीन्द्रशत्रुः॥', 'tatas tam ādāya tadā sa mene harīndram indropamam indravīryaḥ
asmin hṛte sarvam idaṃ hṛtaṃ syāt sarāghavaṃ sainyam itīndraśatruḥ', null, 6055053),
('ramayana-6-55-54', 54, 'Yuddha Kanda, Sarga 55, Verse 54', 'विद्रुतां वाहिनीं दृष्ट्वा वानराणां ततस्ततः।
कुम्भकर्णेन सुग्रीवं गृहीतं चापि वानरम्॥', 'vidrutāṃ vāhinīṃ dṛṣṭvā vānarāṇāṃ tatas tataḥ
kumbhakarṇena sugrīvaṃ gṛhītaṃ cāpi vānaram', null, 6055054),
('ramayana-6-55-55', 55, 'Yuddha Kanda, Sarga 55, Verse 55', 'हनूमांश्चिन्तयामास मतिमान्मारुतात्मजः।
एवं गृहीते सुग्रीवे किं कर्तव्यं मया भवेत्॥', 'hanūmāṃś cintayām āsa matimān mārutātmajaḥ
evaṃ gṛhīte sugrīve kiṃ kartavyaṃ mayā bhavet', null, 6055055),
('ramayana-6-55-56', 56, 'Yuddha Kanda, Sarga 55, Verse 56', 'यद्वै न्याय्यं मया कर्तुं तत्करिष्यामि सर्वथा।
भूत्वा पर्वतसंकाशो नाशयिष्यामि राक्षसं॥', 'yad vai nyāyyaṃ mayā kartuṃ tat kariṣyāmi sarvathā
bhūtvā parvatasaṃkāśo nāśayiṣyāmi rākṣasaṃ', null, 6055056),
('ramayana-6-55-57', 57, 'Yuddha Kanda, Sarga 55, Verse 57', 'मया हते संयति कुम्भकर्णे महाबले मुष्टिविशीर्णदेहे।
विमोचिते वानरपार्थिवे च भवन्तु हृष्टाः प्रवगाः समग्राः॥', 'mayā hate saṃyati kumbhakarṇe mahābale muṣṭiviśīrṇadehe
vimocite vānarapārthive ca bhavantu hṛṣṭāḥ pravagāḥ samagrāḥ', null, 6055057),
('ramayana-6-55-58', 58, 'Yuddha Kanda, Sarga 55, Verse 58', 'अथ वा स्वयमप्येष मोक्षं प्राप्स्यति पार्थिवः।
गृहीतोऽयं यदि भवेत्त्रिदशैः सासुरोरगैः॥', 'atha vā svayam apy eṣa mokṣaṃ prāpsyati pārthivaḥ
gṛhīto ''yaṃ yadi bhavet tridaśaiḥ sāsuroragaiḥ', null, 6055058),
('ramayana-6-55-59', 59, 'Yuddha Kanda, Sarga 55, Verse 59', 'मन्ये न तावदात्मानं बुध्यते वानराधिपः।
शैलप्रहाराभिहतः कुम्भकर्णेन संयुगे॥', 'manye na tāvad ātmānaṃ budhyate vānarādhipaḥ
śailaprahārābhihataḥ kumbhakarṇena saṃyuge', null, 6055059),
('ramayana-6-55-60', 60, 'Yuddha Kanda, Sarga 55, Verse 60', 'अयं मुहूर्तात्सुग्रीवो लब्धसंज्ञो महाहवे।
आत्मनो वानराणां च यत्पथ्यं तत्करिष्यति॥', 'ayaṃ muhūrtāt sugrīvo labdhasaṃjño mahāhave
ātmano vānarāṇāṃ ca yat pathyaṃ tat kariṣyati', null, 6055060),
('ramayana-6-55-61', 61, 'Yuddha Kanda, Sarga 55, Verse 61', 'मया तु मोक्षितस्यास्य सुग्रीवस्य महात्मनः।
अप्रीतश्च भवेत्कष्टा कीर्तिनाशश्च शाश्वतः॥', 'mayā tu mokṣitasyāsya sugrīvasya mahātmanaḥ
aprītaś ca bhavet kaṣṭā kīrtināśaś ca śāśvataḥ', null, 6055061),
('ramayana-6-55-62', 62, 'Yuddha Kanda, Sarga 55, Verse 62', 'तस्मान्मुहूर्तं काङ्क्षिष्ये विक्रमं पार्थिवस्य नः।
भिन्नं च वानरानीकं तावदाश्वासयाम्यहम्॥', 'tasmān muhūrtaṃ kāṅkṣiṣye vikramaṃ pārthivasya naḥ
bhinnaṃ ca vānarānīkaṃ tāvad āśvāsayāmy aham', null, 6055062),
('ramayana-6-55-63', 63, 'Yuddha Kanda, Sarga 55, Verse 63', 'इत्येवं चिन्तयित्वा तु हनूमान्मारुतात्मजः।
भूयः संस्तम्भयामास वानराणां महाचमूम्॥', 'ity evaṃ cintayitvā tu hanūmān mārutātmajaḥ
bhūyaḥ saṃstambhayām āsa vānarāṇāṃ mahācamūm', null, 6055063),
('ramayana-6-55-64', 64, 'Yuddha Kanda, Sarga 55, Verse 64', 'स कुम्भकर्णोऽथ विवेश लङ्कां स्फुरन्तमादाय महाहरिं तम्।
विमानचर्यागृहगोपुरस्थैः पुष्पाग्र्यवर्षैरवकीर्यमाणः॥', 'sa kumbhakarṇo ''tha viveśa laṅkāṃ sphurantam ādāya mahāhariṃ tam
vimānacaryāgṛhagopurasthaiḥ puṣpāgryavarṣair avakīryamāṇaḥ', null, 6055064),
('ramayana-6-55-65', 65, 'Yuddha Kanda, Sarga 55, Verse 65', 'ततः स संज्ञामुपलभ्य कृच्छ्राद्बलीयसस्तस्य भुजान्तरस्थः।
अवेक्षमाणः पुरराजमार्गं विचिन्तयामास मुहुर्महात्मा॥', 'tataḥ sa saṃjñām upalabhya kṛcchrād balīyasas tasya bhujāntarasthaḥ
avekṣamāṇaḥ purarājamārgaṃ vicintayām āsa muhur mahātmā', null, 6055065),
('ramayana-6-55-66', 66, 'Yuddha Kanda, Sarga 55, Verse 66', 'एवं गृहीतेन कथं नु नाम शक्यं मया संप्रति कर्तुमद्य।
तथा करिष्यामि यथा हरीणां भविष्यतीष्टं च हितं च कार्यम्॥', 'evaṃ gṛhītena kathaṃ nu nāma śakyaṃ mayā saṃprati kartum adya
tathā kariṣyāmi yathā harīṇāṃ bhaviṣyatīṣṭaṃ ca hitaṃ ca kāryam', null, 6055066),
('ramayana-6-55-67', 67, 'Yuddha Kanda, Sarga 55, Verse 67', 'ततः कराग्रैः सहसा समेत्य राजा हरीणाममरेन्द्रशत्रोः।
नखैश्च कर्णौ दशनैश्च नासां ददंश पार्श्वेषु च कुम्भकर्णम्॥', 'tataḥ karāgraiḥ sahasā sametya rājā harīṇām amarendraśatroḥ
nakhaiś ca karṇau daśanaiś ca nāsāṃ dadaṃśa pārśveṣu ca kumbhakarṇam', null, 6055067),
('ramayana-6-55-68', 68, 'Yuddha Kanda, Sarga 55, Verse 68', 'स कुम्भकर्णौ हृतकर्णनासो विदारितस्तेन विमर्दितश्च।
रोषाभिभूतः क्षतजार्द्रगात्रः सुग्रीवमाविध्य पिपेष भूमौ॥', 'sa kumbhakarṇau hṛtakarṇanāso vidāritas tena vimarditaś ca
roṣābhibhūtaḥ kṣatajārdragātraḥ sugrīvam āvidhya pipeṣa bhūmau', null, 6055068),
('ramayana-6-55-69', 69, 'Yuddha Kanda, Sarga 55, Verse 69', 'स भूतले भीमबलाभिपिष्टः सुरारिभिस्तैरभिहन्यमानः।
जगाम खं वेगवदभ्युपेत्य पुनश्च रामेण समाजगाम॥', 'sa bhūtale bhīmabalābhipiṣṭaḥ surāribhis tair abhihanyamānaḥ
jagāma khaṃ vegavad abhyupetya punaś ca rāmeṇa samājagāma', null, 6055069),
('ramayana-6-55-70', 70, 'Yuddha Kanda, Sarga 55, Verse 70', 'कर्णनासा विहीनस्य कुम्भकर्णो महाबलः।
रराज शोणितोत्सिक्तो गिरिः प्रस्रवणैरिव॥', 'karṇanāsā vihīnasya kumbhakarṇo mahābalaḥ
rarāja śoṇitotsikto giriḥ prasravaṇair iva', null, 6055070),
('ramayana-6-55-71', 71, 'Yuddha Kanda, Sarga 55, Verse 71', 'ततः स पुर्याः सहसा महात्मा निष्क्रम्य तद्वानरसैन्यमुग्रम्।
बभक्ष रक्षो युधि कुम्भकर्णः प्रजा युगान्ताग्निरिव प्रदीप्तः॥', 'tataḥ sa puryāḥ sahasā mahātmā niṣkramya tad vānarasainyam ugram
babhakṣa rakṣo yudhi kumbhakarṇaḥ prajā yugāntāgnir iva pradīptaḥ', null, 6055071),
('ramayana-6-55-72', 72, 'Yuddha Kanda, Sarga 55, Verse 72', 'बुभुक्षितः शोणितमांसगृध्नुः प्रविश्य तद्वानरसैन्यमुग्रम्।
चखाद रक्षांसि हरीन्पिशाचानृक्षांश्च मोहाद्युधि कुम्भकर्णः॥', 'bubhukṣitaḥ śoṇitamāṃsagṛdhnuḥ praviśya tad vānarasainyam ugram
cakhāda rakṣāṃsi harīn piśācān ṛkṣāṃś ca mohād yudhi kumbhakarṇaḥ', null, 6055072),
('ramayana-6-55-73', 73, 'Yuddha Kanda, Sarga 55, Verse 73', 'एकं द्वौ त्रीन्बहून्क्रुद्धो वानरान्सह राक्षसैः।
समादायैकहस्तेन प्रचिक्षेप त्वरन्मुखे॥', 'ekaṃ dvau trīn bahūn kruddho vānarān saha rākṣasaiḥ
samādāyaikahastena pracikṣepa tvaran mukhe', null, 6055073),
('ramayana-6-55-74', 74, 'Yuddha Kanda, Sarga 55, Verse 74', 'संप्रस्रवंस्तदा मेदः शोणितं च महाबलः।
वध्यमानो नगेन्द्राग्रैर्भक्षयामास वानरान्।
ते भक्ष्यमाणा हरयो रामं जग्मुस्तदा गतिम्॥', 'saṃprasravaṃs tadā medaḥ śoṇitaṃ ca mahābalaḥ
vadhyamāno nagendrāgrair bhakṣayām āsa vānarān
te bhakṣyamāṇā harayo rāmaṃ jagmus tadā gatim', null, 6055074),
('ramayana-6-55-75', 75, 'Yuddha Kanda, Sarga 55, Verse 75', 'तस्मिन्काले सुमित्रायाः पुत्रः परबलार्दनः।
चकार लक्ष्मणः क्रुद्धो युद्धं परपुरंजयः॥', 'tasmin kāle sumitrāyāḥ putraḥ parabalārdanaḥ
cakāra lakṣmaṇaḥ kruddho yuddhaṃ parapuraṃjayaḥ', null, 6055075),
('ramayana-6-55-76', 76, 'Yuddha Kanda, Sarga 55, Verse 76', 'स कुम्भकर्णस्य शराञ्शरीरे सप्त वीर्यवान्।
निचखानाददे चान्यान्विससर्ज च लक्ष्मणः॥', 'sa kumbhakarṇasya śarāñ śarīre sapta vīryavān
nicakhānādade cānyān visasarja ca lakṣmaṇaḥ', null, 6055076),
('ramayana-6-55-77', 77, 'Yuddha Kanda, Sarga 55, Verse 77', 'अतिक्रम्य च सौमित्रिं कुम्भकर्णो महाबलः।
राममेवाभिदुद्राव दारयन्निव मेदिनीम्॥', 'atikramya ca saumitriṃ kumbhakarṇo mahābalaḥ
rāmam evābhidudrāva dārayann iva medinīm', null, 6055077),
('ramayana-6-55-78', 78, 'Yuddha Kanda, Sarga 55, Verse 78', 'अथ दाशरथी रामो रौद्रमस्त्रं प्रयोजयन्।
कुम्भकर्णस्य हृदये ससर्ज निशिताञ्शरान्॥', 'atha dāśarathī rāmo raudram astraṃ prayojayan
kumbhakarṇasya hṛdaye sasarja niśitāñ śarān', null, 6055078),
('ramayana-6-55-79', 79, 'Yuddha Kanda, Sarga 55, Verse 79', 'तस्य रामेण विद्धस्य सहसाभिप्रधावतः।
अङ्गारमिश्राः क्रुद्धस्य मुखान्निश्चेरुरर्चिषः॥', 'tasya rāmeṇa viddhasya sahasābhipradhāvataḥ
aṅgāramiśrāḥ kruddhasya mukhān niścerur arciṣaḥ', null, 6055079),
('ramayana-6-55-80', 80, 'Yuddha Kanda, Sarga 55, Verse 80', 'तस्योरसि निमग्नाश्च शरा बर्हिणवाससः।
हस्ताच्चास्य परिभ्रष्टा पपातोर्व्यां महागदा॥', 'tasyorasi nimagnāś ca śarā barhiṇavāsasaḥ
hastāc cāsya paribhraṣṭā papātorvyāṃ mahāgadā', null, 6055080),
('ramayana-6-55-81', 81, 'Yuddha Kanda, Sarga 55, Verse 81', 'स निरायुधमात्मानं यदा मेने महाबलः।
मुष्टिभ्यां चारणाभ्यां च चकार कदनं महत्॥', 'sa nirāyudham ātmānaṃ yadā mene mahābalaḥ
muṣṭibhyāṃ cāraṇābhyāṃ ca cakāra kadanaṃ mahat', null, 6055081),
('ramayana-6-55-82', 82, 'Yuddha Kanda, Sarga 55, Verse 82', 'स बाणैरतिविद्धाङ्गः क्षतजेन समुक्षितः।
रुधिरं परिसुस्राव गिरिः प्रस्रवणानिव॥', 'sa bāṇair atividdhāṅgaḥ kṣatajena samukṣitaḥ
rudhiraṃ parisusrāva giriḥ prasravaṇān iva', null, 6055082),
('ramayana-6-55-83', 83, 'Yuddha Kanda, Sarga 55, Verse 83', 'स तीव्रेण च कोपेन रुधिरेण च मूर्छितः।
वानरान्राक्षसानृक्षान्खादन्विपरिधावति॥', 'sa tīvreṇa ca kopena rudhireṇa ca mūrchitaḥ
vānarān rākṣasān ṛkṣān khādan viparidhāvati', null, 6055083),
('ramayana-6-55-84', 84, 'Yuddha Kanda, Sarga 55, Verse 84', 'तस्मिन्काले स धर्मात्मा लक्ष्मणो राममब्रवीत्।
कुम्भकर्णवधे युक्तो योगान्परिमृशन्बहून्॥', 'tasmin kāle sa dharmātmā lakṣmaṇo rāmam abravīt
kumbhakarṇavadhe yukto yogān parimṛśan bahūn', null, 6055084),
('ramayana-6-55-85', 85, 'Yuddha Kanda, Sarga 55, Verse 85', 'नैवायं वानरान्राजन्न विजानाति राक्षसान्।
मत्तः शोणितगन्धेन स्वान्परांश्चैव खादति॥', 'naivāyaṃ vānarān rājan na vijānāti rākṣasān
mattaḥ śoṇitagandhena svān parāṃś caiva khādati', null, 6055085),
('ramayana-6-55-86', 86, 'Yuddha Kanda, Sarga 55, Verse 86', 'साध्वेनमधिरोहन्तु सर्वतो वानरर्षभाः।
यूथपाश्च यथामुख्यास्तिष्ठन्त्वस्य समन्ततः॥', 'sādhv enam adhirohantu sarvato vānararṣabhāḥ
yūthapāś ca yathāmukhyās tiṣṭhantv asya samantataḥ', null, 6055086),
('ramayana-6-55-87', 87, 'Yuddha Kanda, Sarga 55, Verse 87', 'अप्ययं दुर्मतिः काले गुरुभारप्रपीडितः।
प्रपतन्राक्षसो भूमौ नान्यान्हन्यात्प्लवंगमान्॥', 'apy ayaṃ durmatiḥ kāle gurubhāraprapīḍitaḥ
prapatan rākṣaso bhūmau nānyān hanyāt plavaṃgamān', null, 6055087),
('ramayana-6-55-88', 88, 'Yuddha Kanda, Sarga 55, Verse 88', 'तस्य तद्वचनं श्रुत्वा राजपुत्रस्य धीमतः।
ते समारुरुहुर्हृष्टाः कुम्भकर्णं प्लवंगमाः॥', 'tasya tad vacanaṃ śrutvā rājaputrasya dhīmataḥ
te samāruruhur hṛṣṭāḥ kumbhakarṇaṃ plavaṃgamāḥ', null, 6055088),
('ramayana-6-55-89', 89, 'Yuddha Kanda, Sarga 55, Verse 89', 'कुम्भकर्णस्तु संक्रुद्धः समारूढः प्लवंगमैः।
व्यधूनयत्तान्वेगेन दुष्टहस्तीव हस्तिपान्॥', 'kumbhakarṇas tu saṃkruddhaḥ samārūḍhaḥ plavaṃgamaiḥ
vyadhūnayat tān vegena duṣṭahastīva hastipān', null, 6055089),
('ramayana-6-55-90', 90, 'Yuddha Kanda, Sarga 55, Verse 90', 'तान्दृष्ट्वा निर्धूतान्रामो रुष्टोऽयमिति राक्षसः।
समुत्पपात वेगेन धनुरुत्तममाददे॥', 'tān dṛṣṭvā nirdhūtān rāmo ruṣṭo ''yam iti rākṣasaḥ
samutpapāta vegena dhanur uttamam ādade', null, 6055090),
('ramayana-6-55-91', 91, 'Yuddha Kanda, Sarga 55, Verse 91', 'स चापमादाय भुजंगकल्पं दृढज्यमुग्रं तपनीयचित्रम्।
हरीन्समाश्वास्य समुत्पपात रामो निबद्धोत्तमतूणबाणः॥', 'sa cāpam ādāya bhujaṃgakalpaṃ dṛḍhajyam ugraṃ tapanīyacitram
harīn samāśvāsya samutpapāta rāmo nibaddhottamatūṇabāṇaḥ', null, 6055091),
('ramayana-6-55-92', 92, 'Yuddha Kanda, Sarga 55, Verse 92', 'स वानरगणैस्तैस्तु वृतः परमदुर्जयः।
लक्ष्मणानुचरो रामः संप्रतस्थे महाबलः॥', 'sa vānaragaṇais tais tu vṛtaḥ paramadurjayaḥ
lakṣmaṇānucaro rāmaḥ saṃpratasthe mahābalaḥ', null, 6055092),
('ramayana-6-55-93', 93, 'Yuddha Kanda, Sarga 55, Verse 93', 'स ददर्श महात्मानं किरीटिनमरिंदमम्।
शोणिताप्लुतसर्वाङ्गं कुम्भकर्णं महाबलम्॥', 'sa dadarśa mahātmānaṃ kirīṭinam ariṃdamam
śoṇitāplutasarvāṅgaṃ kumbhakarṇaṃ mahābalam', null, 6055093),
('ramayana-6-55-94', 94, 'Yuddha Kanda, Sarga 55, Verse 94', 'सर्वान्समभिधावन्तं यथारुष्टं दिशा गजम्।
मार्गमाणं हरीन्क्रुद्धं राक्षसैः परिवारितम्॥', 'sarvān samabhidhāvantaṃ yathāruṣṭaṃ diśā gajam
mārgamāṇaṃ harīn kruddhaṃ rākṣasaiḥ parivāritam', null, 6055094),
('ramayana-6-55-95', 95, 'Yuddha Kanda, Sarga 55, Verse 95', 'विन्ध्यमन्दरसंकाशं काञ्चनाङ्गदभूषणम्।
स्रवन्तं रुधिरं वक्त्राद्वर्षमेघमिवोत्थितम्॥', 'vindhyamandarasaṃkāśaṃ kāñcanāṅgadabhūṣaṇam
sravantaṃ rudhiraṃ vaktrād varṣamegham ivotthitam', null, 6055095),
('ramayana-6-55-96', 96, 'Yuddha Kanda, Sarga 55, Verse 96', 'जिह्वया परिलिह्यन्तं शोणितं शोणितोक्षितम्।
मृद्नन्तं वानरानीकं कालान्तकयमोपमम्॥', 'jihvayā parilihyantaṃ śoṇitaṃ śoṇitokṣitam
mṛdnantaṃ vānarānīkaṃ kālāntakayamopamam', null, 6055096),
('ramayana-6-55-97', 97, 'Yuddha Kanda, Sarga 55, Verse 97', 'तं दृष्ट्वा राक्षसश्रेष्ठं प्रदीप्तानलवर्चसं।
विस्फारयामास तदा कार्मुकं पुरुषर्षभः॥', 'taṃ dṛṣṭvā rākṣasaśreṣṭhaṃ pradīptānalavarcasaṃ
visphārayām āsa tadā kārmukaṃ puruṣarṣabhaḥ', null, 6055097),
('ramayana-6-55-98', 98, 'Yuddha Kanda, Sarga 55, Verse 98', 'स तस्य चापनिर्घोषात्कुपितो नैरृतर्षभः।
अमृष्यमाणस्तं घोषमभिदुद्राव राघवम्॥', 'sa tasya cāpanirghoṣāt kupito nairṛtarṣabhaḥ
amṛṣyamāṇas taṃ ghoṣam abhidudrāva rāghavam', null, 6055098),
('ramayana-6-55-99', 99, 'Yuddha Kanda, Sarga 55, Verse 99', 'ततस्तु वातोद्धतमेघकल्पं भुजंगराजोत्तमभोगबाहुम्।
तमापतन्तं धरणीधराभमुवाच रामो युधि कुम्भकर्णम्॥', 'tatas tu vātoddhatameghakalpaṃ bhujaṃgarājottamabhogabāhum
tam āpatantaṃ dharaṇīdharābham uvāca rāmo yudhi kumbhakarṇam', null, 6055099),
('ramayana-6-55-100', 100, 'Yuddha Kanda, Sarga 55, Verse 100', 'आगच्छ रक्षोऽधिपमा विषादमवस्थितोऽहं प्रगृहीतचापः।
अवेहि मां शक्रसपत्न राममयं मुहूर्ताद्भविता विचेताः॥', 'āgaccha rakṣo''dhipamā viṣādam avasthito ''haṃ pragṛhītacāpaḥ
avehi māṃ śakrasapatna rāmam ayaṃ muhūrtād bhavitā vicetāḥ', null, 6055100),
('ramayana-6-55-101', 101, 'Yuddha Kanda, Sarga 55, Verse 101', 'रामोऽयमिति विज्ञाय जहास विकृतस्वनम्।
पातयन्निव सर्वेषां हृदयानि वनौकसाम्॥', 'rāmo ''yam iti vijñāya jahāsa vikṛtasvanam
pātayann iva sarveṣāṃ hṛdayāni vanaukasām', null, 6055101),
('ramayana-6-55-102', 102, 'Yuddha Kanda, Sarga 55, Verse 102', 'प्रहस्य विकृतं भीमं स मेघस्वनितोपमम्।
कुम्भकर्णो महातेजा राघवं वाक्यमब्रवीत्॥', 'prahasya vikṛtaṃ bhīmaṃ sa meghasvanitopamam
kumbhakarṇo mahātejā rāghavaṃ vākyam abravīt', null, 6055102),
('ramayana-6-55-103', 103, 'Yuddha Kanda, Sarga 55, Verse 103', 'नाहं विराधो विज्ञेयो न कबन्धः खरो न च।
न वाली न च मारीचः कुम्भकर्णोऽहमागतः॥', 'nāhaṃ virādho vijñeyo na kabandhaḥ kharo na ca
na vālī na ca mārīcaḥ kumbhakarṇo ''ham āgataḥ', null, 6055103),
('ramayana-6-55-104', 104, 'Yuddha Kanda, Sarga 55, Verse 104', 'पश्य मे मुद्गरं घोरं सर्वकालायसं महत्।
अनेन निर्जिता देवा दानवाश्च मया पुरा॥', 'paśya me mudgaraṃ ghoraṃ sarvakālāyasaṃ mahat
anena nirjitā devā dānavāś ca mayā purā', null, 6055104),
('ramayana-6-55-105', 105, 'Yuddha Kanda, Sarga 55, Verse 105', 'विकर्णनास इति मां नावज्ञातुं त्वमर्हसि।
स्वल्पापि हि न मे पीडा कर्णनासाविनाशनात्॥', 'vikarṇanāsa iti māṃ nāvajñātuṃ tvam arhasi
svalpāpi hi na me pīḍā karṇanāsāvināśanāt', null, 6055105),
('ramayana-6-55-106', 106, 'Yuddha Kanda, Sarga 55, Verse 106', 'दर्शयेक्ष्वाकुशार्दूल वीर्यं गात्रेषु मे लघु।
ततस्त्वां भक्षयिष्यामि दृष्टपौरुषविक्रमम्॥', 'darśayekṣvākuśārdūla vīryaṃ gātreṣu me laghu
tatas tvāṃ bhakṣayiṣyāmi dṛṣṭapauruṣavikramam', null, 6055106),
('ramayana-6-55-107', 107, 'Yuddha Kanda, Sarga 55, Verse 107', 'स कुम्भकर्णस्य वचो निशम्य रामः सुपुङ्खान्विससर्ज बाणान्।
तैराहतो वज्रसमप्रवेगैर्न चुक्षुभे न व्यथते सुरारिः॥', 'sa kumbhakarṇasya vaco niśamya rāmaḥ supuṅkhān visasarja bāṇān
tair āhato vajrasamapravegair na cukṣubhe na vyathate surāriḥ', null, 6055107),
('ramayana-6-55-108', 108, 'Yuddha Kanda, Sarga 55, Verse 108', 'यैः सायकैः सालवरा निकृत्ता वाली हतो वानरपुंगवश्च।
ते कुम्भकर्णस्य तदा शरीरं वज्रोपमा न व्यथयां प्रचक्रुः॥', 'yaiḥ sāyakaiḥ sālavarā nikṛttā vālī hato vānarapuṃgavaś ca
te kumbhakarṇasya tadā śarīraṃ vajropamā na vyathayāṃ pracakruḥ', null, 6055108),
('ramayana-6-55-109', 109, 'Yuddha Kanda, Sarga 55, Verse 109', 'स वारिधारा इव सायकांस्तान्पिबञ्शरीरेण महेन्द्रशत्रुः।
जघान रामस्य शरप्रवेगं व्याविध्य तं मुद्गरमुग्रवेगम्॥', 'sa vāridhārā iva sāyakāṃs tān pibañ śarīreṇa mahendraśatruḥ
jaghāna rāmasya śarapravegaṃ vyāvidhya taṃ mudgaram ugravegam', null, 6055109),
('ramayana-6-55-110', 110, 'Yuddha Kanda, Sarga 55, Verse 110', 'ततस्तु रक्षः क्षतजानुलिप्तं वित्रासनं देवमहाचमूनाम्।
व्याविध्य तं मुद्गरमुग्रवेगं विद्रावयामास चमूं हरीणाम्॥', 'tatas tu rakṣaḥ kṣatajānuliptaṃ vitrāsanaṃ devamahācamūnām
vyāvidhya taṃ mudgaram ugravegaṃ vidrāvayām āsa camūṃ harīṇām', null, 6055110),
('ramayana-6-55-111', 111, 'Yuddha Kanda, Sarga 55, Verse 111', 'वायव्यमादाय ततो वरास्त्रं रामः प्रचिक्षेप निशाचराय।
समुद्गरं तेन जहार बाहुं स कृत्तबाहुस्तुमुलं ननाद॥', 'vāyavyam ādāya tato varāstraṃ rāmaḥ pracikṣepa niśācarāya
samudgaraṃ tena jahāra bāhuṃ sa kṛttabāhus tumulaṃ nanāda', null, 6055111),
('ramayana-6-55-112', 112, 'Yuddha Kanda, Sarga 55, Verse 112', 'स तस्य बाहुर्गिरिशृङ्गकल्पः समुद्गरो राघवबाणकृत्तः।
पपात तस्मिन्हरिराजसैन्ये जघान तां वानरवाहिनीं च॥', 'sa tasya bāhur giriśṛṅgakalpaḥ samudgaro rāghavabāṇakṛttaḥ
papāta tasmin harirājasainye jaghāna tāṃ vānaravāhinīṃ ca', null, 6055112),
('ramayana-6-55-113', 113, 'Yuddha Kanda, Sarga 55, Verse 113', 'ते वानरा भग्नहतावशेषाः पर्यन्तमाश्रित्य तदा विषण्णाः।
प्रवेपिताङ्गा ददृशुः सुघोरं नरेन्द्ररक्षोऽधिपसंनिपातम्॥', 'te vānarā bhagnahatāvaśeṣāḥ paryantam āśritya tadā viṣaṇṇāḥ
pravepitāṅgā dadṛśuḥ sughoraṃ narendrarakṣo''dhipasaṃnipātam', null, 6055113),
('ramayana-6-55-114', 114, 'Yuddha Kanda, Sarga 55, Verse 114', 'स कुम्भकर्णोऽस्त्रनिकृत्तबाहुर्महान्निकृत्ताग्र इवाचलेन्द्रः।
उत्पाटयामास करेण वृक्षं ततोऽभिदुद्राव रणे नरेन्द्रम्॥', 'sa kumbhakarṇo ''stranikṛttabāhur mahān nikṛttāgra ivācalendraḥ
utpāṭayām āsa kareṇa vṛkṣaṃ tato ''bhidudrāva raṇe narendram', null, 6055114),
('ramayana-6-55-115', 115, 'Yuddha Kanda, Sarga 55, Verse 115', 'तं तस्य बाहुं सह सालवृक्षं समुद्यतं पन्नगभोगकल्पम्।
ऐन्द्रास्त्रयुक्तेन जहार रामो बाणेन जाम्बूनदचित्रितेन॥', 'taṃ tasya bāhuṃ saha sālavṛkṣaṃ samudyataṃ pannagabhogakalpam
aindrāstrayuktena jahāra rāmo bāṇena jāmbūnadacitritena', null, 6055115),
('ramayana-6-55-116', 116, 'Yuddha Kanda, Sarga 55, Verse 116', 'स कुम्भकर्णस्य भुजो निकृत्तः पपात भूमौ गिरिसंनिकाशः।
विवेष्टमानो निजघान वृक्षाञ्शैलाञ्शिलावानरराक्षसांश्च॥', 'sa kumbhakarṇasya bhujo nikṛttaḥ papāta bhūmau girisaṃnikāśaḥ
viveṣṭamāno nijaghāna vṛkṣāñ śailāñ śilāvānararākṣasāṃś ca', null, 6055116),
('ramayana-6-55-117', 117, 'Yuddha Kanda, Sarga 55, Verse 117', 'तं छिन्नबाहुं समवेक्ष्य रामः समापतन्तं सहसा नदन्तम्।
द्वावर्धचन्द्रौ निशितौ प्रगृह्य चिच्छेद पादौ युधि राक्षसस्य॥', 'taṃ chinnabāhuṃ samavekṣya rāmaḥ samāpatantaṃ sahasā nadantam
dvāv ardhacandrau niśitau pragṛhya ciccheda pādau yudhi rākṣasasya', null, 6055117),
('ramayana-6-55-118', 118, 'Yuddha Kanda, Sarga 55, Verse 118', 'निकृत्तबाहुर्विनिकृत्तपादो विदार्य वक्त्रं वडवामुखाभम्।
दुद्राव रामं सहसाभिगर्जन्राहुर्यथा चन्द्रमिवान्तरिक्षे॥', 'nikṛttabāhur vinikṛttapādo vidārya vaktraṃ vaḍavāmukhābham
dudrāva rāmaṃ sahasābhigarjan rāhur yathā candram ivāntarikṣe', null, 6055118),
('ramayana-6-55-119', 119, 'Yuddha Kanda, Sarga 55, Verse 119', 'अपूरयत्तस्य मुखं शिताग्रै रामः शरैर्हेमपिनद्धपुङ्खैः।
स पूर्णवक्त्रो न शशाक वक्तुं चुकूज कृच्छ्रेण मुमोह चापि॥', 'apūrayat tasya mukhaṃ śitāgrai rāmaḥ śarair hemapinaddhapuṅkhaiḥ
sa pūrṇavaktro na śaśāka vaktuṃ cukūja kṛcchreṇa mumoha cāpi', null, 6055119),
('ramayana-6-55-120', 120, 'Yuddha Kanda, Sarga 55, Verse 120', 'अथाददे सूर्यमरीचिकल्पं स ब्रह्मदण्डान्तककालकल्पम्।
अरिष्टमैन्द्रं निशितं सुपुङ्खं रामः शरं मारुततुल्यवेगम्॥', 'athādade sūryamarīcikalpaṃ sa brahmadaṇḍāntakakālakalpam
ariṣṭam aindraṃ niśitaṃ supuṅkhaṃ rāmaḥ śaraṃ mārutatulyavegam', null, 6055120),
('ramayana-6-55-121', 121, 'Yuddha Kanda, Sarga 55, Verse 121', 'तं वज्रजाम्बूनदचारुपुङ्खं प्रदीप्तसूर्यज्वलनप्रकाशम्।
महेन्द्रवज्राशनितुल्यवेगं रामः प्रचिक्षेप निशाचराय॥', 'taṃ vajrajāmbūnadacārupuṅkhaṃ pradīptasūryajvalanaprakāśam
mahendravajrāśanitulyavegaṃ rāmaḥ pracikṣepa niśācarāya', null, 6055121),
('ramayana-6-55-122', 122, 'Yuddha Kanda, Sarga 55, Verse 122', 'स सायको राघवबाहुचोदितो दिशः स्वभासा दश संप्रकाशयन्।
विधूमवैश्वानरदीप्तदर्शनो जगाम शक्राशनितुल्यविक्रमः॥', 'sa sāyako rāghavabāhucodito diśaḥ svabhāsā daśa saṃprakāśayan
vidhūmavaiśvānaradīptadarśano jagāma śakrāśanitulyavikramaḥ', null, 6055122),
('ramayana-6-55-123', 123, 'Yuddha Kanda, Sarga 55, Verse 123', 'स तन्महापर्वतकूटसंनिभं विवृत्तदंष्ट्रं चलचारुकुण्डलम्।
चकर्त रक्षोऽधिपतेः शिरस्तदा यथैव वृत्रस्य पुरा पुरंदरः॥', 'sa tan mahāparvatakūṭasaṃnibhaṃ vivṛttadaṃṣṭraṃ calacārukuṇḍalam
cakarta rakṣo''dhipateḥ śiras tadā yathaiva vṛtrasya purā puraṃdaraḥ', null, 6055123),
('ramayana-6-55-124', 124, 'Yuddha Kanda, Sarga 55, Verse 124', 'तद्रामबाणाभिहतं पपात रक्षःशिरः पर्वतसंनिकाशम्।
बभञ्ज चर्यागृहगोपुराणि प्राकारमुच्चं तमपातयच्च॥', 'tad rāmabāṇābhihataṃ papāta rakṣaḥśiraḥ parvatasaṃnikāśam
babhañja caryāgṛhagopurāṇi prākāram uccaṃ tam apātayac ca', null, 6055124),
('ramayana-6-55-125', 125, 'Yuddha Kanda, Sarga 55, Verse 125', 'तच्चातिकायं हिमवत्प्रकाशं रक्षस्तदा तोयनिधौ पपात।
ग्राहान्महामीनचयान्भुजंगमान्ममर्द भूमिं च तथा विवेश॥', 'tac cātikāyaṃ himavatprakāśaṃ rakṣas tadā toyanidhau papāta
grāhān mahāmīnacayān bhujaṃgamān mamarda bhūmiṃ ca tathā viveśa', null, 6055125),
('ramayana-6-55-126', 126, 'Yuddha Kanda, Sarga 55, Verse 126', 'तस्मिर्हते ब्राह्मणदेवशत्रौ महाबले संयति कुम्भकर्णे।
चचाल भूर्भूमिधराश्च सर्वे हर्षाच्च देवास्तुमुलं प्रणेदुः॥', 'tasmir hate brāhmaṇadevaśatrau mahābale saṃyati kumbhakarṇe
cacāla bhūr bhūmidharāś ca sarve harṣāc ca devās tumulaṃ praṇeduḥ', null, 6055126),
('ramayana-6-55-127', 127, 'Yuddha Kanda, Sarga 55, Verse 127', 'ततस्तु देवर्षिमहर्षिपन्नगाः सुराश्च भूतानि सुपर्णगुह्यकाः।
सयक्षगन्धर्वगणा नभोगताः प्रहर्षिता राम पराक्रमेण॥', 'tatas tu devarṣimaharṣipannagāḥ surāś ca bhūtāni suparṇaguhyakāḥ
sayakṣagandharvagaṇā nabhogatāḥ praharṣitā rāma parākrameṇa', null, 6055127),
('ramayana-6-55-128', 128, 'Yuddha Kanda, Sarga 55, Verse 128', 'प्रहर्षमीयुर्बहवस्तु वानराः प्रबुद्धपद्मप्रतिमैरिवाननैः।
अपूजयन्राघवमिष्टभागिनं हते रिपौ भीमबले दुरासदे॥', 'praharṣam īyur bahavas tu vānarāḥ prabuddhapadmapratimair ivānanaiḥ
apūjayan rāghavam iṣṭabhāginaṃ hate ripau bhīmabale durāsade', null, 6055128),
('ramayana-6-55-129', 129, 'Yuddha Kanda, Sarga 55, Verse 129', 'स कुम्भकर्णं सुरसैन्यमर्दनं महत्सु युद्धेष्वपराजितश्रमम्।
ननन्द हत्वा भरताग्रजो रणे महासुरं वृत्रमिवामराधिपः॥', 'sa kumbhakarṇaṃ surasainyamardanaṃ mahatsu yuddheṣv aparājitaśramam
nananda hatvā bharatāgrajo raṇe mahāsuraṃ vṛtram ivāmarādhipaḥ', null, 6055129)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 56 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-56-1', 1, 'Yuddha Kanda, Sarga 56, Verse 1', 'कुम्भकर्णं हतं दृष्ट्वा राघवेण महात्मना।
राक्षसा राक्षसेन्द्राय रावणाय न्यवेदयन्॥', 'kumbhakarṇaṃ hataṃ dṛṣṭvā rāghaveṇa mahātmanā
rākṣasā rākṣasendrāya rāvaṇāya nyavedayan', null, 6056001),
('ramayana-6-56-2', 2, 'Yuddha Kanda, Sarga 56, Verse 2', 'श्रुत्वा विनिहतं संख्ये कुम्भकर्णं महाबलम्।
रावणः शोकसंतप्तो मुमोह च पपात च॥', 'śrutvā vinihataṃ saṃkhye kumbhakarṇaṃ mahābalam
rāvaṇaḥ śokasaṃtapto mumoha ca papāta ca', null, 6056002),
('ramayana-6-56-3', 3, 'Yuddha Kanda, Sarga 56, Verse 3', 'पितृव्यं निहतं श्रुत्वा देवान्तकनरान्तकौ।
त्रिशिराश्चातिकायश्च रुरुदुः शोकपीडिताः॥', 'pitṛvyaṃ nihataṃ śrutvā devāntakanarāntakau
triśirāś cātikāyaś ca ruruduḥ śokapīḍitāḥ', null, 6056003),
('ramayana-6-56-4', 4, 'Yuddha Kanda, Sarga 56, Verse 4', 'भ्रातरं निहतं श्रुत्वा रामेणाक्लिष्टकर्मणा।
महोदरमहापार्श्वौ शोकाक्रान्तौ बभूवतुः॥', 'bhrātaraṃ nihataṃ śrutvā rāmeṇākliṣṭakarmaṇā
mahodaramahāpārśvau śokākrāntau babhūvatuḥ', null, 6056004),
('ramayana-6-56-5', 5, 'Yuddha Kanda, Sarga 56, Verse 5', 'ततः कृच्छ्रात्समासाद्य संज्ञां राक्षसपुंगवः।
कुम्भकर्णवधाद्दीनो विललाप स रावणः॥', 'tataḥ kṛcchrāt samāsādya saṃjñāṃ rākṣasapuṃgavaḥ
kumbhakarṇavadhād dīno vilalāpa sa rāvaṇaḥ', null, 6056005),
('ramayana-6-56-6', 6, 'Yuddha Kanda, Sarga 56, Verse 6', 'हा वीर रिपुदर्पघ्न कुम्भकर्ण महाबल।
शत्रुसैन्यं प्रताप्यैकः क्व मां संत्यज्य गच्छसि॥', 'hā vīra ripudarpaghna kumbhakarṇa mahābala
śatrusainyaṃ pratāpyaikaḥ kva māṃ saṃtyajya gacchasi', null, 6056006),
('ramayana-6-56-7', 7, 'Yuddha Kanda, Sarga 56, Verse 7', 'इदानीं खल्वहं नास्मि यस्य मे पतितो भुजः।
दक्षिणो यं समाश्रित्य न बिभेमि सुरासुरान्॥', 'idānīṃ khalv ahaṃ nāsmi yasya me patito bhujaḥ
dakṣiṇo yaṃ samāśritya na bibhemi surāsurān', null, 6056007),
('ramayana-6-56-8', 8, 'Yuddha Kanda, Sarga 56, Verse 8', 'कथमेवंविधो वीरो देवदानवदर्पहा।
कालाग्निप्रतिमो ह्यद्य राघवेण रणे हतः॥', 'katham evaṃvidho vīro devadānavadarpahā
kālāgnipratimo hy adya rāghaveṇa raṇe hataḥ', null, 6056008),
('ramayana-6-56-9', 9, 'Yuddha Kanda, Sarga 56, Verse 9', 'यस्य ते वज्रनिष्पेषो न कुर्याद्व्यसनं सदा।
स कथं रामबाणार्तः प्रसुप्तोऽसि महीतले॥', 'yasya te vajraniṣpeṣo na kuryād vyasanaṃ sadā
sa kathaṃ rāmabāṇārtaḥ prasupto ''si mahītale', null, 6056009),
('ramayana-6-56-10', 10, 'Yuddha Kanda, Sarga 56, Verse 10', 'एते देवगणाः सार्धमृषिभिर्गगने स्थिताः।
निहतं त्वां रणे दृष्ट्वा निनदन्ति प्रहर्षिताः॥', 'ete devagaṇāḥ sārdham ṛṣibhir gagane sthitāḥ
nihataṃ tvāṃ raṇe dṛṣṭvā ninadanti praharṣitāḥ', null, 6056010),
('ramayana-6-56-11', 11, 'Yuddha Kanda, Sarga 56, Verse 11', 'ध्रुवमद्यैव संहृष्टा लब्धलक्ष्याः प्लवंगमाः।
आरोक्ष्यन्तीह दुर्गाणि लङ्काद्वाराणि सर्वशः॥', 'dhruvam adyaiva saṃhṛṣṭā labdhalakṣyāḥ plavaṃgamāḥ
ārokṣyantīha durgāṇi laṅkādvārāṇi sarvaśaḥ', null, 6056011),
('ramayana-6-56-12', 12, 'Yuddha Kanda, Sarga 56, Verse 12', 'राज्येन नास्ति मे कार्यं किं करिष्यामि सीतया।
कुम्भकर्णविहीनस्य जीविते नास्ति मे रतिः॥', 'rājyena nāsti me kāryaṃ kiṃ kariṣyāmi sītayā
kumbhakarṇavihīnasya jīvite nāsti me ratiḥ', null, 6056012),
('ramayana-6-56-13', 13, 'Yuddha Kanda, Sarga 56, Verse 13', 'यद्यहं भ्रातृहन्तारं न हन्मि युधि राघवम्।
ननु मे मरणं श्रेयो न चेदं व्यर्थजीवितम्॥', 'yady ahaṃ bhrātṛhantāraṃ na hanmi yudhi rāghavam
nanu me maraṇaṃ śreyo na cedaṃ vyarthajīvitam', null, 6056013),
('ramayana-6-56-14', 14, 'Yuddha Kanda, Sarga 56, Verse 14', 'अद्यैव तं गमिष्यामि देशं यत्रानुजो मम।
न हि भ्रातॄन्समुत्सृज्य क्षणं जीवितुमुत्सहे॥', 'adyaiva taṃ gamiṣyāmi deśaṃ yatrānujo mama
na hi bhrātṝn samutsṛjya kṣaṇaṃ jīvitum utsahe', null, 6056014),
('ramayana-6-56-15', 15, 'Yuddha Kanda, Sarga 56, Verse 15', 'देवा हि मां हसिष्यन्ति दृष्ट्वा पूर्वापकारिणम्।
कथमिन्द्रं जयिष्यामि कुम्भकर्णहते त्वयि॥', 'devā hi māṃ hasiṣyanti dṛṣṭvā pūrvāpakāriṇam
katham indraṃ jayiṣyāmi kumbhakarṇahate tvayi', null, 6056015),
('ramayana-6-56-16', 16, 'Yuddha Kanda, Sarga 56, Verse 16', 'तदिदं मामनुप्राप्तं विभीषणवचः शुभम्।
यदज्ञानान्मया तस्य न गृहीतं महात्मनः॥', 'tad idaṃ mām anuprāptaṃ vibhīṣaṇavacaḥ śubham
yad ajñānān mayā tasya na gṛhītaṃ mahātmanaḥ', null, 6056016),
('ramayana-6-56-17', 17, 'Yuddha Kanda, Sarga 56, Verse 17', 'विभीषणवचो यावत्कुम्भकर्णप्रहस्तयोः।
विनाशोऽयं समुत्पन्नो मां व्रीडयति दारुणः॥', 'vibhīṣaṇavaco yāvat kumbhakarṇaprahastayoḥ
vināśo ''yaṃ samutpanno māṃ vrīḍayati dāruṇaḥ', null, 6056017),
('ramayana-6-56-18', 18, 'Yuddha Kanda, Sarga 56, Verse 18', 'तस्यायं कर्मणः प्रातो विपाको मम शोकदः।
यन्मया धार्मिकः श्रीमान्स निरस्तो विभीषणः॥', 'tasyāyaṃ karmaṇaḥ prāto vipāko mama śokadaḥ
yan mayā dhārmikaḥ śrīmān sa nirasto vibhīṣaṇaḥ', null, 6056018),
('ramayana-6-56-19', 19, 'Yuddha Kanda, Sarga 56, Verse 19', 'इति बहुविधमाकुलान्तरात्मा कृपणमतीव विलप्य कुम्भकर्णम्।
न्यपतदथ दशाननो भृशार्तस्तमनुजमिन्द्ररिपुं हतं विदित्वा॥', 'iti bahuvidham ākulāntarātmā kṛpaṇam atīva vilapya kumbhakarṇam
nyapatad atha daśānano bhṛśārtas tam anujam indraripuṃ hataṃ viditvā', null, 6056019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 57 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-57-1', 1, 'Yuddha Kanda, Sarga 57, Verse 1', 'एवं विलपमानस्य रावणस्य दुरात्मनः।
श्रुत्वा शोकाभितप्तस्य त्रिशिरा वाक्यमब्रवीत्॥', 'evaṃ vilapamānasya rāvaṇasya durātmanaḥ
śrutvā śokābhitaptasya triśirā vākyam abravīt', null, 6057001),
('ramayana-6-57-2', 2, 'Yuddha Kanda, Sarga 57, Verse 2', 'एवमेव महावीर्यो हतो नस्तात मध्यमः।
न तु सत्पुरुषा राजन्विलपन्ति यथा भवान्॥', 'evam eva mahāvīryo hato nas tāta madhyamaḥ
na tu satpuruṣā rājan vilapanti yathā bhavān', null, 6057002),
('ramayana-6-57-3', 3, 'Yuddha Kanda, Sarga 57, Verse 3', 'नूनं त्रिभुवणस्यापि पर्याप्तस्त्वमसि प्रभो।
स कस्मात्प्राकृत इव शोकस्यात्मानमीदृशम्॥', 'nūnaṃ tribhuvaṇasyāpi paryāptas tvam asi prabho
sa kasmāt prākṛta iva śokasyātmānam īdṛśam', null, 6057003),
('ramayana-6-57-4', 4, 'Yuddha Kanda, Sarga 57, Verse 4', 'ब्रह्मदत्तास्ति ते शक्तिः कवचः सायको धनुः।
सहस्रखरसंयुक्तो रथो मेघसमस्वनः॥', 'brahmadattāsti te śaktiḥ kavacaḥ sāyako dhanuḥ
sahasrakharasaṃyukto ratho meghasamasvanaḥ', null, 6057004),
('ramayana-6-57-5', 5, 'Yuddha Kanda, Sarga 57, Verse 5', 'त्वयासकृद्विशस्त्रेण विशस्ता देवदानवाः।
स सर्वायुधसंपन्नो राघवं शास्तुमर्हसि॥', 'tvayāsakṛd viśastreṇa viśastā devadānavāḥ
sa sarvāyudhasaṃpanno rāghavaṃ śāstum arhasi', null, 6057005),
('ramayana-6-57-6', 6, 'Yuddha Kanda, Sarga 57, Verse 6', 'कामं तिष्ठ महाराजनिर्गमिष्याम्यहं रणम्।
उद्धरिष्यामि ते शत्रून्गरुडः पन्नगानिह॥', 'kāmaṃ tiṣṭha mahārājanirgamiṣyāmy ahaṃ raṇam
uddhariṣyāmi te śatrūn garuḍaḥ pannagān iha', null, 6057006),
('ramayana-6-57-7', 7, 'Yuddha Kanda, Sarga 57, Verse 7', 'शम्बरो देवराजेन नरको विष्णुना यथा।
तथाद्य शयिता रामो मया युधि निपातितः॥', 'śambaro devarājena narako viṣṇunā yathā
tathādya śayitā rāmo mayā yudhi nipātitaḥ', null, 6057007),
('ramayana-6-57-8', 8, 'Yuddha Kanda, Sarga 57, Verse 8', 'श्रुत्वा त्रिशिरसो वाक्यं रावणो राक्षसाधिपः।
पुनर्जातमिवात्मानं मन्यते कालचोदितः॥', 'śrutvā triśiraso vākyaṃ rāvaṇo rākṣasādhipaḥ
punar jātam ivātmānaṃ manyate kālacoditaḥ', null, 6057008),
('ramayana-6-57-9', 9, 'Yuddha Kanda, Sarga 57, Verse 9', 'श्रुत्वा त्रिशिरसो वाक्यं देवान्तकनरान्तकौ।
अतिकायश्च तेजस्वी बभूवुर्युद्धहर्षिताः॥', 'śrutvā triśiraso vākyaṃ devāntakanarāntakau
atikāyaś ca tejasvī babhūvur yuddhaharṣitāḥ', null, 6057009),
('ramayana-6-57-10', 10, 'Yuddha Kanda, Sarga 57, Verse 10', 'ततोऽहमहमित्येवं गर्जन्तो नैरृतर्षभाः।
रावणस्य सुता वीराः शक्रतुल्यपराक्रमाः॥', 'tato ''ham aham ity evaṃ garjanto nairṛtarṣabhāḥ
rāvaṇasya sutā vīrāḥ śakratulyaparākramāḥ', null, 6057010),
('ramayana-6-57-11', 11, 'Yuddha Kanda, Sarga 57, Verse 11', 'अन्तरिक्षचराः सर्वे सर्वे माया विशारदाः।
सर्वे त्रिदशदर्पघ्नाः सर्वे च रणदुर्मदाः॥', 'antarikṣacarāḥ sarve sarve māyā viśāradāḥ
sarve tridaśadarpaghnāḥ sarve ca raṇadurmadāḥ', null, 6057011),
('ramayana-6-57-12', 12, 'Yuddha Kanda, Sarga 57, Verse 12', 'सर्वेऽस्त्रबलसंपन्नाः सर्वे विस्तीर्ण कीर्तयः।
सर्वे समरमासाद्य न श्रूयन्ते स्म निर्जिताः॥', 'sarve ''strabalasaṃpannāḥ sarve vistīrṇa kīrtayaḥ
sarve samaram āsādya na śrūyante sma nirjitāḥ', null, 6057012),
('ramayana-6-57-13', 13, 'Yuddha Kanda, Sarga 57, Verse 13', 'सर्वेऽस्त्रविदुषो वीराः सर्वे युद्धविशारदाः।
सर्वे प्रवरजिज्ञानाः सर्वे लब्धवरास्तथा॥', 'sarve ''straviduṣo vīrāḥ sarve yuddhaviśāradāḥ
sarve pravarajijñānāḥ sarve labdhavarās tathā', null, 6057013),
('ramayana-6-57-14', 14, 'Yuddha Kanda, Sarga 57, Verse 14', 'स तैस्तथा भास्करतुल्यवर्चसैः सुतैर्वृतः शत्रुबलप्रमर्दनैः।
रराज राजा मघवान्यथामरैर्वृतो महादानवदर्पनाशनैः॥', 'sa tais tathā bhāskaratulyavarcasaiḥ sutair vṛtaḥ śatrubalapramardanaiḥ
rarāja rājā maghavān yathāmarair vṛto mahādānavadarpanāśanaiḥ', null, 6057014),
('ramayana-6-57-15', 15, 'Yuddha Kanda, Sarga 57, Verse 15', 'स पुत्रान्संपरिष्वज्य भूषयित्वा च भूषणैः।
आशीर्भिश्च प्रशस्ताभिः प्रेषयामास संयुगे॥', 'sa putrān saṃpariṣvajya bhūṣayitvā ca bhūṣaṇaiḥ
āśīrbhiś ca praśastābhiḥ preṣayām āsa saṃyuge', null, 6057015),
('ramayana-6-57-16', 16, 'Yuddha Kanda, Sarga 57, Verse 16', 'महोदरमहापार्श्वौ भ्रातरौ चापि रावणः।
रक्षणार्थं कुमाराणां प्रेषयामास संयुगे॥', 'mahodaramahāpārśvau bhrātarau cāpi rāvaṇaḥ
rakṣaṇārthaṃ kumārāṇāṃ preṣayām āsa saṃyuge', null, 6057016),
('ramayana-6-57-17', 17, 'Yuddha Kanda, Sarga 57, Verse 17', 'तेऽभिवाद्य महात्मानं रावणं रिपुरावणम्।
कृत्वा प्रदक्षिणं चैव महाकायाः प्रतस्थिरे॥', 'te ''bhivādya mahātmānaṃ rāvaṇaṃ ripurāvaṇam
kṛtvā pradakṣiṇaṃ caiva mahākāyāḥ pratasthire', null, 6057017),
('ramayana-6-57-18', 18, 'Yuddha Kanda, Sarga 57, Verse 18', 'सर्वौषधीभिर्गन्धैश्च समालभ्य महाबलाः।
निर्जग्मुर्नैरृतश्रेष्ठाः षडेते युद्धकाङ्क्षिणः॥', 'sarvauṣadhībhir gandhaiś ca samālabhya mahābalāḥ
nirjagmur nairṛtaśreṣṭhāḥ ṣaḍ ete yuddhakāṅkṣiṇaḥ', null, 6057018),
('ramayana-6-57-19', 19, 'Yuddha Kanda, Sarga 57, Verse 19', 'ततः सुदर्शनं नाम नीलजीमूतसंनिभम्।
ऐरावतकुले जातमारुरोह महोदरः॥', 'tataḥ sudarśanaṃ nāma nīlajīmūtasaṃnibham
airāvatakule jātam āruroha mahodaraḥ', null, 6057019),
('ramayana-6-57-20', 20, 'Yuddha Kanda, Sarga 57, Verse 20', 'सर्वायुधसमायुक्तं तूणीभिश्च स्वलंकृतम्।
रराज गजमास्थाय सवितेवास्तमूर्धनि॥', 'sarvāyudhasamāyuktaṃ tūṇībhiś ca svalaṃkṛtam
rarāja gajam āsthāya savitevāstamūrdhani', null, 6057020),
('ramayana-6-57-21', 21, 'Yuddha Kanda, Sarga 57, Verse 21', 'हयोत्तमसमायुक्तं सर्वायुधसमाकुलम्।
आरुरोह रथश्रेष्ठं त्रिशिरा रावणात्मजः॥', 'hayottamasamāyuktaṃ sarvāyudhasamākulam
āruroha rathaśreṣṭhaṃ triśirā rāvaṇātmajaḥ', null, 6057021),
('ramayana-6-57-22', 22, 'Yuddha Kanda, Sarga 57, Verse 22', 'त्रिशिरा रथमास्थाय विरराज धनुर्धरः।
सविद्युदुल्कः सज्वालः सेन्द्रचाप इवाम्बुदः॥', 'triśirā ratham āsthāya virarāja dhanurdharaḥ
savidyudulkaḥ sajvālaḥ sendracāpa ivāmbudaḥ', null, 6057022),
('ramayana-6-57-23', 23, 'Yuddha Kanda, Sarga 57, Verse 23', 'त्रिभिः किरीटैस्त्रिशिराः शुशुभे स रथोत्तमे।
हिमवानिव शैलेन्द्रस्त्रिभिः काञ्चनपर्वतैः॥', 'tribhiḥ kirīṭais triśirāḥ śuśubhe sa rathottame
himavān iva śailendras tribhiḥ kāñcanaparvataiḥ', null, 6057023),
('ramayana-6-57-24', 24, 'Yuddha Kanda, Sarga 57, Verse 24', 'अतिकायोऽपि तेजस्वी राक्षसेन्द्रसुतस्तदा।
आरुरोह रथश्रेष्ठं श्रेष्ठः सर्वधनुष्मताम्॥', 'atikāyo ''pi tejasvī rākṣasendrasutas tadā
āruroha rathaśreṣṭhaṃ śreṣṭhaḥ sarvadhanuṣmatām', null, 6057024),
('ramayana-6-57-25', 25, 'Yuddha Kanda, Sarga 57, Verse 25', 'सुचक्राक्षं सुसंयुक्तं सानुकर्षं सकूबरम्।
तूणीबाणासनैर्दीप्तं प्रासासि परिघाकुलम्॥', 'sucakrākṣaṃ susaṃyuktaṃ sānukarṣaṃ sakūbaram
tūṇībāṇāsanair dīptaṃ prāsāsi parighākulam', null, 6057025),
('ramayana-6-57-26', 26, 'Yuddha Kanda, Sarga 57, Verse 26', 'स काञ्चनविचित्रेण किरीटेन विराजता।
भूषणैश्च बभौ मेरुः प्रभाभिरिव भास्वरः॥', 'sa kāñcanavicitreṇa kirīṭena virājatā
bhūṣaṇaiś ca babhau meruḥ prabhābhir iva bhāsvaraḥ', null, 6057026),
('ramayana-6-57-27', 27, 'Yuddha Kanda, Sarga 57, Verse 27', 'स रराज रथे तस्मिन्राजसूनुर्महाबलः।
वृतो नैरृतशार्दूलैर्वज्रपाणिरिवामरैः॥', 'sa rarāja rathe tasmin rājasūnur mahābalaḥ
vṛto nairṛtaśārdūlair vajrapāṇir ivāmaraiḥ', null, 6057027),
('ramayana-6-57-28', 28, 'Yuddha Kanda, Sarga 57, Verse 28', 'हयमुच्चैःश्रवः प्रख्यं श्वेतं कनकभूषणम्।
मनोजवं महाकायमारुरोह नरान्तकः॥', 'hayam uccaiḥśravaḥ prakhyaṃ śvetaṃ kanakabhūṣaṇam
manojavaṃ mahākāyam āruroha narāntakaḥ', null, 6057028),
('ramayana-6-57-29', 29, 'Yuddha Kanda, Sarga 57, Verse 29', 'गृहीत्वा प्रासमुक्लाभं विरराज नरान्तकः।
शक्तिमादाय तेजस्वी गुहः शत्रुष्विवाहवे॥', 'gṛhītvā prāsam uklābhaṃ virarāja narāntakaḥ
śaktim ādāya tejasvī guhaḥ śatruṣv ivāhave', null, 6057029),
('ramayana-6-57-30', 30, 'Yuddha Kanda, Sarga 57, Verse 30', 'देवान्तकः समादाय परिघं वज्रभूषणम्।
परिगृह्य गिरिं दोर्भ्यां वपुर्विष्णोर्विडम्बयन्॥', 'devāntakaḥ samādāya parighaṃ vajrabhūṣaṇam
parigṛhya giriṃ dorbhyāṃ vapur viṣṇor viḍambayan', null, 6057030),
('ramayana-6-57-31', 31, 'Yuddha Kanda, Sarga 57, Verse 31', 'महापार्श्वो महातेजा गदामादाय वीर्यवान्।
विरराज गदापाणिः कुबेर इव संयुगे॥', 'mahāpārśvo mahātejā gadām ādāya vīryavān
virarāja gadāpāṇiḥ kubera iva saṃyuge', null, 6057031),
('ramayana-6-57-32', 32, 'Yuddha Kanda, Sarga 57, Verse 32', 'ते प्रतस्थुर्महात्मानो बलैरप्रतिमैर्वृताः।
सुरा इवामरावत्यां बलैरप्रतिमैर्वृताः॥', 'te pratasthur mahātmāno balair apratimair vṛtāḥ
surā ivāmarāvatyāṃ balair apratimair vṛtāḥ', null, 6057032),
('ramayana-6-57-33', 33, 'Yuddha Kanda, Sarga 57, Verse 33', 'तान्गजैश्च तुरंगैश्च रथैश्चाम्बुदनिस्वनैः।
अनुजग्मुर्महात्मानो राक्षसाः प्रवरायुधाः॥', 'tān gajaiś ca turaṃgaiś ca rathaiś cāmbudanisvanaiḥ
anujagmur mahātmāno rākṣasāḥ pravarāyudhāḥ', null, 6057033),
('ramayana-6-57-34', 34, 'Yuddha Kanda, Sarga 57, Verse 34', 'ते विरेजुर्महात्मानो कुमाराः सूर्यवर्चसः।
किरीटिनः श्रिया जुष्टा ग्रहा दीप्ता इवाम्बरे॥', 'te virejur mahātmāno kumārāḥ sūryavarcasaḥ
kirīṭinaḥ śriyā juṣṭā grahā dīptā ivāmbare', null, 6057034),
('ramayana-6-57-35', 35, 'Yuddha Kanda, Sarga 57, Verse 35', 'प्रगृहीता बभौ तेषां छत्राणामावलिः सिता।
शारदाभ्रप्रतीकाशां हंसावलिरिवाम्बरे॥', 'pragṛhītā babhau teṣāṃ chatrāṇām āvaliḥ sitā
śāradābhrapratīkāśāṃ haṃsāvalir ivāmbare', null, 6057035),
('ramayana-6-57-36', 36, 'Yuddha Kanda, Sarga 57, Verse 36', 'मरणं वापि निश्चित्य शत्रूणां वा पराजयम्।
इति कृत्वा मतिं वीरा निर्जग्मुः संयुगार्थिनः॥', 'maraṇaṃ vāpi niścitya śatrūṇāṃ vā parājayam
iti kṛtvā matiṃ vīrā nirjagmuḥ saṃyugārthinaḥ', null, 6057036),
('ramayana-6-57-37', 37, 'Yuddha Kanda, Sarga 57, Verse 37', 'जगर्जुश्च प्रणेदुश्च चिक्षिपुश्चापि सायकान्।
जहृषुश्च महात्मानो निर्यान्तो युद्धदुर्मदाः॥', 'jagarjuś ca praṇeduś ca cikṣipuś cāpi sāyakān
jahṛṣuś ca mahātmāno niryānto yuddhadurmadāḥ', null, 6057037),
('ramayana-6-57-38', 38, 'Yuddha Kanda, Sarga 57, Verse 38', 'क्ष्वेडितास्फोटनिनदैः संचचालेव मेदिनी।
रक्षसां सिंहनादैश्च पुस्फोटेव तदाम्बरम्॥', 'kṣveḍitāsphoṭaninadaiḥ saṃcacāleva medinī
rakṣasāṃ siṃhanādaiś ca pusphoṭeva tadāmbaram', null, 6057038),
('ramayana-6-57-39', 39, 'Yuddha Kanda, Sarga 57, Verse 39', 'तेऽभिनिष्क्रम्य मुदिता राक्षसेन्द्रा महाबलाः।
ददृशुर्वानरानीकं समुद्यतशिलानगम्॥', 'te ''bhiniṣkramya muditā rākṣasendrā mahābalāḥ
dadṛśur vānarānīkaṃ samudyataśilānagam', null, 6057039),
('ramayana-6-57-40', 40, 'Yuddha Kanda, Sarga 57, Verse 40', 'हरयोऽपि महात्मानो ददृशुर्नैरृतं बलम्।
हस्त्यश्वरथसंबाधं किङ्किणीशतनादितम्॥', 'harayo ''pi mahātmāno dadṛśur nairṛtaṃ balam
hastyaśvarathasaṃbādhaṃ kiṅkiṇīśatanāditam', null, 6057040),
('ramayana-6-57-41', 41, 'Yuddha Kanda, Sarga 57, Verse 41', 'नीलजीमूतसंकाशं समुद्यतमहायुधम्।
दीप्तानलरविप्रख्यैर्नैरृतैः सर्वतो वृतम्॥', 'nīlajīmūtasaṃkāśaṃ samudyatamahāyudham
dīptānalaraviprakhyair nairṛtaiḥ sarvato vṛtam', null, 6057041),
('ramayana-6-57-42', 42, 'Yuddha Kanda, Sarga 57, Verse 42', 'तद्दृष्ट्वा बलमायान्तं लब्धलक्ष्याः प्लवंगमाः।
समुद्यतमहाशैलाः संप्रणेदुर्मुहुर्मुहुः॥', 'tad dṛṣṭvā balam āyāntaṃ labdhalakṣyāḥ plavaṃgamāḥ
samudyatamahāśailāḥ saṃpraṇedur muhur muhuḥ', null, 6057042),
('ramayana-6-57-43', 43, 'Yuddha Kanda, Sarga 57, Verse 43', 'ततः समुद्घुष्टरवं निशम्य रक्षोगणा वानरयूथपानाम्।
अमृष्यमाणाः परहर्षमुग्रं महाबला भीमतरं विनेदुः॥', 'tataḥ samudghuṣṭaravaṃ niśamya rakṣogaṇā vānarayūthapānām
amṛṣyamāṇāḥ paraharṣam ugraṃ mahābalā bhīmataraṃ vineduḥ', null, 6057043),
('ramayana-6-57-44', 44, 'Yuddha Kanda, Sarga 57, Verse 44', 'ते राक्षसबलं घोरं प्रविश्य हरियूथपाः।
विचेरुरुद्यतैः शैलैर्नगाः शिखरिणो यथा॥', 'te rākṣasabalaṃ ghoraṃ praviśya hariyūthapāḥ
vicerur udyataiḥ śailair nagāḥ śikhariṇo yathā', null, 6057044),
('ramayana-6-57-45', 45, 'Yuddha Kanda, Sarga 57, Verse 45', 'के चिदाकाशमाविश्य के चिदुर्व्यां प्लवंगमाः।
रक्षःसैन्येषु संक्रुद्धाश्चेरुर्द्रुमशिलायुधाः॥', 'ke cid ākāśam āviśya ke cid urvyāṃ plavaṃgamāḥ
rakṣaḥsainyeṣu saṃkruddhāś cerur drumaśilāyudhāḥ', null, 6057045),
('ramayana-6-57-46', 46, 'Yuddha Kanda, Sarga 57, Verse 46', 'ते पादपशिलाशैलैश्चक्रुर्वृष्टिमनुत्तमाम्।
बाणौघैर्वार्यमाणाश्च हरयो भीमविक्रमाः॥', 'te pādapaśilāśailaiś cakrur vṛṣṭim anuttamām
bāṇaughair vāryamāṇāś ca harayo bhīmavikramāḥ', null, 6057046),
('ramayana-6-57-47', 47, 'Yuddha Kanda, Sarga 57, Verse 47', 'सिंहनादान्विनेदुश्च रणे राक्षसवानराः।
शिलाभिश्चूर्णयामासुर्यातुधानान्प्लवंगमाः॥', 'siṃhanādān vineduś ca raṇe rākṣasavānarāḥ
śilābhiś cūrṇayām āsur yātudhānān plavaṃgamāḥ', null, 6057047),
('ramayana-6-57-48', 48, 'Yuddha Kanda, Sarga 57, Verse 48', 'निजघ्नुः संयुगे क्रुद्धाः कवचाभरणावृतान्।
के चिद्रथगतान्वीरान्गजवाजिगतानपि॥', 'nijaghnuḥ saṃyuge kruddhāḥ kavacābharaṇāvṛtān
ke cid rathagatān vīrān gajavājigatān api', null, 6057048),
('ramayana-6-57-49', 49, 'Yuddha Kanda, Sarga 57, Verse 49', 'निजघ्नुः सहसाप्लुत्य यातुधानान्प्लवंगमाः।
शैलशृङ्गनिपातैश्च मुष्टिभिर्वान्तलोचनाः।
चेलुः पेतुश्च नेदुश्च तत्र राक्षसपुंगवाः॥', 'nijaghnuḥ sahasāplutya yātudhānān plavaṃgamāḥ
śailaśṛṅganipātaiś ca muṣṭibhir vāntalocanāḥ
celuḥ petuś ca neduś ca tatra rākṣasapuṃgavāḥ', null, 6057049),
('ramayana-6-57-50', 50, 'Yuddha Kanda, Sarga 57, Verse 50', 'ततः शैलैश्च खड्गैश्च विसृष्टैर्हरिराक्षसैः।
मुहूर्तेनावृता भूमिरभवच्छोणिताप्लुता॥', 'tataḥ śailaiś ca khaḍgaiś ca visṛṣṭair harirākṣasaiḥ
muhūrtenāvṛtā bhūmir abhavac choṇitāplutā', null, 6057050),
('ramayana-6-57-51', 51, 'Yuddha Kanda, Sarga 57, Verse 51', 'विकीर्णपर्वताकारै रक्षोभिररिमर्दनैः।
आक्षिप्ताः क्षिप्यमाणाश्च भग्नशूलाश्च वानरैः॥', 'vikīrṇaparvatākārai rakṣobhir arimardanaiḥ
ākṣiptāḥ kṣipyamāṇāś ca bhagnaśūlāś ca vānaraiḥ', null, 6057051),
('ramayana-6-57-52', 52, 'Yuddha Kanda, Sarga 57, Verse 52', 'वानरान्वानरैरेव जग्नुस्ते रजनीचराः।
राक्षसान्राक्षसैरेव जघ्नुस्ते वानरा अपि॥', 'vānarān vānarair eva jagnus te rajanīcarāḥ
rākṣasān rākṣasair eva jaghnus te vānarā api', null, 6057052),
('ramayana-6-57-53', 53, 'Yuddha Kanda, Sarga 57, Verse 53', 'आक्षिप्य च शिलास्तेषां निजघ्नू राक्षसा हरीन्।
तेषां चाच्छिद्य शस्त्राणि जघ्नू रक्षांसि वानराः॥', 'ākṣipya ca śilās teṣāṃ nijaghnū rākṣasā harīn
teṣāṃ cācchidya śastrāṇi jaghnū rakṣāṃsi vānarāḥ', null, 6057053),
('ramayana-6-57-54', 54, 'Yuddha Kanda, Sarga 57, Verse 54', 'निजघ्नुः शैलशूलास्त्रैर्विभिदुश्च परस्परम्।
सिंहनादान्विनेदुश्च रणे वानरराक्षसाः॥', 'nijaghnuḥ śailaśūlāstrair vibhiduś ca parasparam
siṃhanādān vineduś ca raṇe vānararākṣasāḥ', null, 6057054),
('ramayana-6-57-55', 55, 'Yuddha Kanda, Sarga 57, Verse 55', 'छिन्नवर्मतनुत्राणा राक्षसा वानरैर्हताः।
रुधिरं प्रस्रुतास्तत्र रससारमिव द्रुमाः॥', 'chinnavarmatanutrāṇā rākṣasā vānarair hatāḥ
rudhiraṃ prasrutās tatra rasasāram iva drumāḥ', null, 6057055),
('ramayana-6-57-56', 56, 'Yuddha Kanda, Sarga 57, Verse 56', 'रथेन च रथं चापि वारणेन च वारणम्।
हयेन च हयं के चिन्निजघ्नुर्वानरा रणे॥', 'rathena ca rathaṃ cāpi vāraṇena ca vāraṇam
hayena ca hayaṃ ke cin nijaghnur vānarā raṇe', null, 6057056),
('ramayana-6-57-57', 57, 'Yuddha Kanda, Sarga 57, Verse 57', 'क्षुरप्रैरर्धचन्द्रैश्च भल्लैश्च निशितैः शरैः।
राक्षसा वानरेन्द्राणां चिच्छिदुः पादपाञ्शिलाः॥', 'kṣuraprair ardhacandraiś ca bhallaiś ca niśitaiḥ śaraiḥ
rākṣasā vānarendrāṇāṃ cicchiduḥ pādapāñ śilāḥ', null, 6057057),
('ramayana-6-57-58', 58, 'Yuddha Kanda, Sarga 57, Verse 58', 'विकीर्णैः पर्वताग्रैश्च द्रुमैश्छिन्नैश्च संयुगे।
हतैश्च कपिरक्षोभिर्दुर्गमा वसुधाभवत्॥', 'vikīrṇaiḥ parvatāgraiś ca drumaiś chinnaiś ca saṃyuge
hataiś ca kapirakṣobhir durgamā vasudhābhavat', null, 6057058),
('ramayana-6-57-59', 59, 'Yuddha Kanda, Sarga 57, Verse 59', 'तस्मिन्प्रवृत्ते तुमुले विमर्दे प्रहृष्यमाणेषु वली मुखेषु।
निपात्यमानेषु च राक्षसेषु महर्षयो देवगणाश्च नेदुः॥', 'tasmin pravṛtte tumule vimarde prahṛṣyamāṇeṣu valī mukheṣu
nipātyamāneṣu ca rākṣaseṣu maharṣayo devagaṇāś ca neduḥ', null, 6057059),
('ramayana-6-57-60', 60, 'Yuddha Kanda, Sarga 57, Verse 60', 'ततो हयं मारुततुल्यवेगमारुह्य शक्तिं निशितां प्रगृह्य।
नरान्तको वानरराजसैन्यं महार्णवं मीन इवाविवेश॥', 'tato hayaṃ mārutatulyavegam āruhya śaktiṃ niśitāṃ pragṛhya
narāntako vānararājasainyaṃ mahārṇavaṃ mīna ivāviveśa', null, 6057060),
('ramayana-6-57-61', 61, 'Yuddha Kanda, Sarga 57, Verse 61', 'स वानरान्सप्तशतानि वीरः प्रासेन दीप्तेन विनिर्बिभेद।
एकः क्षणेनेन्द्ररिपुर्महात्मा जघान सैन्यं हरिपुंगवानाम्॥', 'sa vānarān saptaśatāni vīraḥ prāsena dīptena vinirbibheda
ekaḥ kṣaṇenendraripur mahātmā jaghāna sainyaṃ haripuṃgavānām', null, 6057061),
('ramayana-6-57-62', 62, 'Yuddha Kanda, Sarga 57, Verse 62', 'ददृशुश्च महात्मानं हयपृष्ठे प्रतिष्ठितम्।
चरन्तं हरिसैन्येषु विद्याधरमहर्षयः॥', 'dadṛśuś ca mahātmānaṃ hayapṛṣṭhe pratiṣṭhitam
carantaṃ harisainyeṣu vidyādharamaharṣayaḥ', null, 6057062),
('ramayana-6-57-63', 63, 'Yuddha Kanda, Sarga 57, Verse 63', 'स तस्य ददृशे मार्गो मांसशोणितकर्दमः।
पतितैः पर्वताकारैर्वानरैरभिसंवृतः॥', 'sa tasya dadṛśe mārgo māṃsaśoṇitakardamaḥ
patitaiḥ parvatākārair vānarair abhisaṃvṛtaḥ', null, 6057063),
('ramayana-6-57-64', 64, 'Yuddha Kanda, Sarga 57, Verse 64', 'यावद्विक्रमितुं बुद्धिं चक्रुः प्लवगपुंगवाः।
तावदेतानतिक्रम्य निर्बिभेद नरान्तकः॥', 'yāvad vikramituṃ buddhiṃ cakruḥ plavagapuṃgavāḥ
tāvad etān atikramya nirbibheda narāntakaḥ', null, 6057064),
('ramayana-6-57-65', 65, 'Yuddha Kanda, Sarga 57, Verse 65', 'ज्वलन्तं प्रासमुद्यम्य संग्रामान्ते नरान्तकः।
ददाह हरिसैन्यानि वनानीव विभावसुः॥', 'jvalantaṃ prāsam udyamya saṃgrāmānte narāntakaḥ
dadāha harisainyāni vanānīva vibhāvasuḥ', null, 6057065),
('ramayana-6-57-66', 66, 'Yuddha Kanda, Sarga 57, Verse 66', 'यावदुत्पाटयामासुर्वृक्षाञ्शैलान्वनौकसः।
तावत्प्रासहताः पेतुर्वज्रकृत्ता इवाचलाः॥', 'yāvad utpāṭayām āsur vṛkṣāñ śailān vanaukasaḥ
tāvat prāsahatāḥ petur vajrakṛttā ivācalāḥ', null, 6057066),
('ramayana-6-57-67', 67, 'Yuddha Kanda, Sarga 57, Verse 67', 'दिक्षु सर्वासु बलवान्विचचार नरान्तकः।
प्रमृद्नन्सर्वतो युद्धे प्रावृट्काले यथानिलः॥', 'dikṣu sarvāsu balavān vicacāra narāntakaḥ
pramṛdnan sarvato yuddhe prāvṛṭkāle yathānilaḥ', null, 6057067),
('ramayana-6-57-68', 68, 'Yuddha Kanda, Sarga 57, Verse 68', 'न शेकुर्धावितुं वीरा न स्थातुं स्पन्दितुं कुतः।
उत्पतन्तं स्थितं यान्तं सर्वान्विव्याध वीर्यवान्॥', 'na śekur dhāvituṃ vīrā na sthātuṃ spandituṃ kutaḥ
utpatantaṃ sthitaṃ yāntaṃ sarvān vivyādha vīryavān', null, 6057068),
('ramayana-6-57-69', 69, 'Yuddha Kanda, Sarga 57, Verse 69', 'एकेनान्तककल्पेन प्रासेनादित्यतेजसा।
भिन्नानि हरिसैन्यानि निपेतुर्धरणीतले॥', 'ekenāntakakalpena prāsenādityatejasā
bhinnāni harisainyāni nipetur dharaṇītale', null, 6057069),
('ramayana-6-57-70', 70, 'Yuddha Kanda, Sarga 57, Verse 70', 'वज्रनिष्पेषसदृशं प्रासस्याभिनिपातनम्।
न शेकुर्वानराः सोढुं ते विनेदुर्महास्वनम्॥', 'vajraniṣpeṣasadṛśaṃ prāsasyābhinipātanam
na śekur vānarāḥ soḍhuṃ te vinedur mahāsvanam', null, 6057070),
('ramayana-6-57-71', 71, 'Yuddha Kanda, Sarga 57, Verse 71', 'पततां हरिवीराणां रूपाणि प्रचकाशिरे।
वज्रभिन्नाग्रकूटानां शैलानां पततामिव॥', 'patatāṃ harivīrāṇāṃ rūpāṇi pracakāśire
vajrabhinnāgrakūṭānāṃ śailānāṃ patatām iva', null, 6057071),
('ramayana-6-57-72', 72, 'Yuddha Kanda, Sarga 57, Verse 72', 'ये तु पूर्वं महात्मानः कुम्भकर्णेन पातिताः।
तेऽस्वस्था वानरश्रेष्ठाः सुग्रीवमुपतस्थिरे॥', 'ye tu pūrvaṃ mahātmānaḥ kumbhakarṇena pātitāḥ
te ''svasthā vānaraśreṣṭhāḥ sugrīvam upatasthire', null, 6057072),
('ramayana-6-57-73', 73, 'Yuddha Kanda, Sarga 57, Verse 73', 'विप्रेक्षमाणः सुग्रीवो ददर्श हरिवाहिनीम्।
नरान्तकभयत्रस्तां विद्रवन्तीमितस्ततः॥', 'viprekṣamāṇaḥ sugrīvo dadarśa harivāhinīm
narāntakabhayatrastāṃ vidravantīm itas tataḥ', null, 6057073),
('ramayana-6-57-74', 74, 'Yuddha Kanda, Sarga 57, Verse 74', 'विद्रुतां वाहिनीं दृष्ट्वा स ददर्श नरान्तकम्।
गृहीतप्रासमायान्तं हयपृष्ठे प्रतिष्ठितम्॥', 'vidrutāṃ vāhinīṃ dṛṣṭvā sa dadarśa narāntakam
gṛhītaprāsam āyāntaṃ hayapṛṣṭhe pratiṣṭhitam', null, 6057074),
('ramayana-6-57-75', 75, 'Yuddha Kanda, Sarga 57, Verse 75', 'अथोवाच महातेजाः सुग्रीवो वानराधिपः।
कुमारमङ्गदं वीरं शक्रतुल्यपराक्रमम्॥', 'athovāca mahātejāḥ sugrīvo vānarādhipaḥ
kumāram aṅgadaṃ vīraṃ śakratulyaparākramam', null, 6057075),
('ramayana-6-57-76', 76, 'Yuddha Kanda, Sarga 57, Verse 76', 'गच्छैनं राक्षसं वीर योऽसौ तुरगमास्थितः।
क्षोभयन्तं हरिबलं क्षिप्रं प्राणैर्वियोजय॥', 'gacchainaṃ rākṣasaṃ vīra yo ''sau turagam āsthitaḥ
kṣobhayantaṃ haribalaṃ kṣipraṃ prāṇair viyojaya', null, 6057076),
('ramayana-6-57-77', 77, 'Yuddha Kanda, Sarga 57, Verse 77', 'स भर्तुर्वचनं श्रुत्वा निष्पपाताङ्गदस्तदा।
अनीकान्मेघसंकाशान्मेघानीकादिवांशुमान्॥', 'sa bhartur vacanaṃ śrutvā niṣpapātāṅgadas tadā
anīkān meghasaṃkāśān meghānīkād ivāṃśumān', null, 6057077),
('ramayana-6-57-78', 78, 'Yuddha Kanda, Sarga 57, Verse 78', 'शैलसंघातसंकाशो हरीणामुत्तमोऽङ्गदः।
रराजाङ्गदसंनद्धः सधातुरिव पर्वतः॥', 'śailasaṃghātasaṃkāśo harīṇām uttamo ''ṅgadaḥ
rarājāṅgadasaṃnaddhaḥ sadhātur iva parvataḥ', null, 6057078),
('ramayana-6-57-79', 79, 'Yuddha Kanda, Sarga 57, Verse 79', 'निरायुधो महातेजाः केवलं नखदंष्ट्रवान्।
नरान्तकमभिक्रम्य वालिपुत्रोऽब्रवीद्वचः॥', 'nirāyudho mahātejāḥ kevalaṃ nakhadaṃṣṭravān
narāntakam abhikramya vāliputro ''bravīd vacaḥ', null, 6057079),
('ramayana-6-57-80', 80, 'Yuddha Kanda, Sarga 57, Verse 80', 'तिष्ठ किं प्राकृतैरेभिर्हरिभिस्त्वं करिष्यसि।
अस्मिन्वज्रसमस्पर्शे प्रासं क्षिप ममोरसि॥', 'tiṣṭha kiṃ prākṛtair ebhir haribhis tvaṃ kariṣyasi
asmin vajrasamasparśe prāsaṃ kṣipa mamorasi', null, 6057080),
('ramayana-6-57-81', 81, 'Yuddha Kanda, Sarga 57, Verse 81', 'अङ्गदस्य वचः श्रुत्वा प्रचुक्रोध नरान्तकः।
संदश्य दशनैरोष्ठं निश्वस्य च भुजंगवत्॥', 'aṅgadasya vacaḥ śrutvā pracukrodha narāntakaḥ
saṃdaśya daśanair oṣṭhaṃ niśvasya ca bhujaṃgavat', null, 6057081),
('ramayana-6-57-82', 82, 'Yuddha Kanda, Sarga 57, Verse 82', 'स प्रासमाविध्य तदाङ्गदाय समुज्ज्वलन्तं सहसोत्ससर्ज।
स वालिपुत्रोरसि वज्रकल्पे बभूव भग्नो न्यपतच्च भूमौ॥', 'sa prāsam āvidhya tadāṅgadāya samujjvalantaṃ sahasotsasarja
sa vāliputrorasi vajrakalpe babhūva bhagno nyapatac ca bhūmau', null, 6057082),
('ramayana-6-57-83', 83, 'Yuddha Kanda, Sarga 57, Verse 83', 'तं प्रासमालोक्य तदा विभग्नं सुपर्णकृत्तोरगभोगकल्पम्।
तलं समुद्यम्य स वालिपुत्रस्तुरंगमस्याभिजघान मूर्ध्नि॥', 'taṃ prāsam ālokya tadā vibhagnaṃ suparṇakṛttoragabhogakalpam
talaṃ samudyamya sa vāliputras turaṃgamasyābhijaghāna mūrdhni', null, 6057083),
('ramayana-6-57-84', 84, 'Yuddha Kanda, Sarga 57, Verse 84', 'निमग्नपादः स्फुटिताक्षि तारो निष्क्रान्तजिह्वोऽचलसंनिकाशः।
स तस्य वाजी निपपात भूमौ तलप्रहारेण विकीर्णमूर्धा॥', 'nimagnapādaḥ sphuṭitākṣi tāro niṣkrāntajihvo ''calasaṃnikāśaḥ
sa tasya vājī nipapāta bhūmau talaprahāreṇa vikīrṇamūrdhā', null, 6057084),
('ramayana-6-57-85', 85, 'Yuddha Kanda, Sarga 57, Verse 85', 'नरान्तकः क्रोधवशं जगाम हतं तुरगं पतितं निरीक्ष्य।
स मुष्टिमुद्यम्य महाप्रभावो जघान शीर्षे युधि वालिपुत्रम्॥', 'narāntakaḥ krodhavaśaṃ jagāma hataṃ turagaṃ patitaṃ nirīkṣya
sa muṣṭim udyamya mahāprabhāvo jaghāna śīrṣe yudhi vāliputram', null, 6057085),
('ramayana-6-57-86', 86, 'Yuddha Kanda, Sarga 57, Verse 86', 'अथाङ्गदो मुष्टिविभिन्नमूर्धा सुस्राव तीव्रं रुधिरं भृशोष्णम्।
मुहुर्विजज्वाल मुमोह चापि संज्ञां समासाद्य विसिष्मिये च॥', 'athāṅgado muṣṭivibhinnamūrdhā susrāva tīvraṃ rudhiraṃ bhṛśoṣṇam
muhur vijajvāla mumoha cāpi saṃjñāṃ samāsādya visiṣmiye ca', null, 6057086),
('ramayana-6-57-87', 87, 'Yuddha Kanda, Sarga 57, Verse 87', 'अथाङ्गदो वज्रसमानवेगं संवर्त्य मुष्टिं गिरिशृङ्गकल्पम्।
निपातयामास तदा महात्मा नरान्तकस्योरसि वालिपुत्रः॥', 'athāṅgado vajrasamānavegaṃ saṃvartya muṣṭiṃ giriśṛṅgakalpam
nipātayām āsa tadā mahātmā narāntakasyorasi vāliputraḥ', null, 6057087),
('ramayana-6-57-88', 88, 'Yuddha Kanda, Sarga 57, Verse 88', 'स मुष्टिनिष्पिष्टविभिन्नवक्षा ज्वालां वमञ्शोणितदिग्धगात्रः।
नरान्तको भूमितले पपात यथाचलो वज्रनिपातभग्नः॥', 'sa muṣṭiniṣpiṣṭavibhinnavakṣā jvālāṃ vamañ śoṇitadigdhagātraḥ
narāntako bhūmitale papāta yathācalo vajranipātabhagnaḥ', null, 6057088),
('ramayana-6-57-89', 89, 'Yuddha Kanda, Sarga 57, Verse 89', 'अथान्तरिक्षे त्रिदशोत्तमानां वनौकसां चैव महाप्रणादः।
बभूव तस्मिन्निहतेऽग्र्यवीरे नरान्तके वालिसुतेन संख्ये॥', 'athāntarikṣe tridaśottamānāṃ vanaukasāṃ caiva mahāpraṇādaḥ
babhūva tasmin nihate ''gryavīre narāntake vālisutena saṃkhye', null, 6057089),
('ramayana-6-57-90', 90, 'Yuddha Kanda, Sarga 57, Verse 90', 'अथाङ्गदो राममनः प्रहर्षणं सुदुष्करं तं कृतवान्हि विक्रमम्।
विसिष्मिये सोऽप्यतिवीर्य विक्रमः पुनश्च युद्धे स बभूव हर्षितः॥', 'athāṅgado rāmamanaḥ praharṣaṇaṃ suduṣkaraṃ taṃ kṛtavān hi vikramam
visiṣmiye so ''py ativīrya vikramaḥ punaś ca yuddhe sa babhūva harṣitaḥ', null, 6057090)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 58 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-58-1', 1, 'Yuddha Kanda, Sarga 58, Verse 1', 'नरान्तकं हतं दृष्ट्वा चुक्रुशुर्नैरृतर्षभाः।
देवान्तकस्त्रिमूर्धा च पौलस्त्यश्च महोदरः॥', 'narāntakaṃ hataṃ dṛṣṭvā cukruśur nairṛtarṣabhāḥ
devāntakas trimūrdhā ca paulastyaś ca mahodaraḥ', null, 6058001),
('ramayana-6-58-2', 2, 'Yuddha Kanda, Sarga 58, Verse 2', 'आरूढो मेघसंकाशं वारणेन्द्रं महोदरः।
वालिपुत्रं महावीर्यमभिदुद्राव वीर्यवान्॥', 'ārūḍho meghasaṃkāśaṃ vāraṇendraṃ mahodaraḥ
vāliputraṃ mahāvīryam abhidudrāva vīryavān', null, 6058002),
('ramayana-6-58-3', 3, 'Yuddha Kanda, Sarga 58, Verse 3', 'भ्रातृव्यसनसंतप्तस्तदा देवान्तको बली।
आदाय परिघं दीप्तमङ्गदं समभिद्रवत्॥', 'bhrātṛvyasanasaṃtaptas tadā devāntako balī
ādāya parighaṃ dīptam aṅgadaṃ samabhidravat', null, 6058003),
('ramayana-6-58-4', 4, 'Yuddha Kanda, Sarga 58, Verse 4', 'रथमादित्यसंकाशं युक्तं परमवाजिभिः।
आस्थाय त्रिशिरा वीरो वालिपुत्रमथाभ्ययात्॥', 'ratham ādityasaṃkāśaṃ yuktaṃ paramavājibhiḥ
āsthāya triśirā vīro vāliputram athābhyayāt', null, 6058004),
('ramayana-6-58-5', 5, 'Yuddha Kanda, Sarga 58, Verse 5', 'स त्रिभिर्देवदर्पघ्नैर्नैरृतेन्द्रैरभिद्रुतः।
वृक्षमुत्पाटयामास महाविटपमङ्गदः॥', 'sa tribhir devadarpaghnair nairṛtendrair abhidrutaḥ
vṛkṣam utpāṭayām āsa mahāviṭapam aṅgadaḥ', null, 6058005),
('ramayana-6-58-6', 6, 'Yuddha Kanda, Sarga 58, Verse 6', 'देवान्तकाय तं वीरश्चिक्षेप सहसाङ्गदः।
महावृक्षं महाशाखं शक्रो दीप्तमिवाशनिम्॥', 'devāntakāya taṃ vīraś cikṣepa sahasāṅgadaḥ
mahāvṛkṣaṃ mahāśākhaṃ śakro dīptam ivāśanim', null, 6058006),
('ramayana-6-58-7', 7, 'Yuddha Kanda, Sarga 58, Verse 7', 'त्रिशिरास्तं प्रचिच्छेद शरैराशीविषोपमैः।
स वृक्षं कृत्तमालोक्य उत्पपात ततोऽङ्गदः॥', 'triśirās taṃ praciccheda śarair āśīviṣopamaiḥ
sa vṛkṣaṃ kṛttam ālokya utpapāta tato ''ṅgadaḥ', null, 6058007),
('ramayana-6-58-8', 8, 'Yuddha Kanda, Sarga 58, Verse 8', 'स ववर्ष ततो वृक्षाञ्शिलाश्च कपिकुञ्जरः।
तान्प्रचिच्छेद संक्रुद्धस्त्रिशिरा निशितैः शरैः॥', 'sa vavarṣa tato vṛkṣāñ śilāś ca kapikuñjaraḥ
tān praciccheda saṃkruddhas triśirā niśitaiḥ śaraiḥ', null, 6058008),
('ramayana-6-58-9', 9, 'Yuddha Kanda, Sarga 58, Verse 9', 'परिघाग्रेण तान्वृक्षान्बभञ्ज च सुरान्तकः।
त्रिशिराश्चाङ्गदं वीरमभिदुद्राव सायकैः॥', 'parighāgreṇa tān vṛkṣān babhañja ca surāntakaḥ
triśirāś cāṅgadaṃ vīram abhidudrāva sāyakaiḥ', null, 6058009),
('ramayana-6-58-10', 10, 'Yuddha Kanda, Sarga 58, Verse 10', 'गजेन समभिद्रुत्य वालिपुत्रं महोदरः।
जघानोरसि संक्रुद्धस्तोमरैर्वज्रसंनिभैः॥', 'gajena samabhidrutya vāliputraṃ mahodaraḥ
jaghānorasi saṃkruddhas tomarair vajrasaṃnibhaiḥ', null, 6058010),
('ramayana-6-58-11', 11, 'Yuddha Kanda, Sarga 58, Verse 11', 'देवान्तकश्च संक्रुद्धः परिघेण तदाङ्गदम्।
उपगम्याभिहत्याशु व्यपचक्राम वेगवान्॥', 'devāntakaś ca saṃkruddhaḥ parigheṇa tadāṅgadam
upagamyābhihatyāśu vyapacakrāma vegavān', null, 6058011),
('ramayana-6-58-12', 12, 'Yuddha Kanda, Sarga 58, Verse 12', 'स त्रिभिर्नैरृतश्रेष्ठैर्युगपत्समभिद्रुतः।
न विव्यथे महातेजा वालिपुत्रः प्रतापवान्॥', 'sa tribhir nairṛtaśreṣṭhair yugapat samabhidrutaḥ
na vivyathe mahātejā vāliputraḥ pratāpavān', null, 6058012),
('ramayana-6-58-13', 13, 'Yuddha Kanda, Sarga 58, Verse 13', 'तलेन भृशमुत्पत्य जघानास्य महागजम्।
पेततुर्लोचने तस्य विननाद स वारणः॥', 'talena bhṛśam utpatya jaghānāsya mahāgajam
petatur locane tasya vinanāda sa vāraṇaḥ', null, 6058013),
('ramayana-6-58-14', 14, 'Yuddha Kanda, Sarga 58, Verse 14', 'विषाणं चास्य निष्कृष्य वालिपुत्रो महाबलः।
देवान्तकमभिद्रुत्य ताडयामास संयुगे॥', 'viṣāṇaṃ cāsya niṣkṛṣya vāliputro mahābalaḥ
devāntakam abhidrutya tāḍayām āsa saṃyuge', null, 6058014),
('ramayana-6-58-15', 15, 'Yuddha Kanda, Sarga 58, Verse 15', 'स विह्वलितसर्वाङ्गो वातोद्धत इव द्रुमः।
लाक्षारससवर्णं च सुस्राव रुधिरं मुखात्॥', 'sa vihvalitasarvāṅgo vātoddhata iva drumaḥ
lākṣārasasavarṇaṃ ca susrāva rudhiraṃ mukhāt', null, 6058015),
('ramayana-6-58-16', 16, 'Yuddha Kanda, Sarga 58, Verse 16', 'अथाश्वास्य महातेजाः कृच्छ्राद्देवान्तको बली।
आविध्य परिघं घोरमाजघान तदाङ्गदम्॥', 'athāśvāsya mahātejāḥ kṛcchrād devāntako balī
āvidhya parighaṃ ghoram ājaghāna tadāṅgadam', null, 6058016),
('ramayana-6-58-17', 17, 'Yuddha Kanda, Sarga 58, Verse 17', 'परिघाभिहतश्चापि वानरेन्द्रात्मजस्तदा।
जानुभ्यां पतितो भूमौ पुनरेवोत्पपात ह॥', 'parighābhihataś cāpi vānarendrātmajas tadā
jānubhyāṃ patito bhūmau punar evotpapāta ha', null, 6058017),
('ramayana-6-58-18', 18, 'Yuddha Kanda, Sarga 58, Verse 18', 'समुत्पतन्तं त्रिशिरास्त्रिभिराशीविषोपमैः।
घोरैर्हरिपतेः पुत्रं ललाटेऽभिजघान ह॥', 'samutpatantaṃ triśirās tribhir āśīviṣopamaiḥ
ghorair haripateḥ putraṃ lalāṭe ''bhijaghāna ha', null, 6058018),
('ramayana-6-58-19', 19, 'Yuddha Kanda, Sarga 58, Verse 19', 'ततोऽङ्गदं परिक्षिप्तं त्रिभिर्नैरृतपुंगवैः।
हनूमानपि विज्ञाय नीलश्चापि प्रतस्थतुः॥', 'tato ''ṅgadaṃ parikṣiptaṃ tribhir nairṛtapuṃgavaiḥ
hanūmān api vijñāya nīlaś cāpi pratasthatuḥ', null, 6058019),
('ramayana-6-58-20', 20, 'Yuddha Kanda, Sarga 58, Verse 20', 'ततश्चिक्षेप शैलाग्रं नीलस्त्रिशिरसे तदा।
तद्रावणसुतो धीमान्बिभेद निशितैः शरैः॥', 'tataś cikṣepa śailāgraṃ nīlas triśirase tadā
tad rāvaṇasuto dhīmān bibheda niśitaiḥ śaraiḥ', null, 6058020),
('ramayana-6-58-21', 21, 'Yuddha Kanda, Sarga 58, Verse 21', 'तद्बाणशतनिर्भिन्नं विदारितशिलातलम्।
सविस्फुलिङ्गं सज्वालं निपपात गिरेः शिरः॥', 'tad bāṇaśatanirbhinnaṃ vidāritaśilātalam
savisphuliṅgaṃ sajvālaṃ nipapāta gireḥ śiraḥ', null, 6058021),
('ramayana-6-58-22', 22, 'Yuddha Kanda, Sarga 58, Verse 22', 'ततो जृम्भितमालोक्य हर्षाद्देवान्तकस्तदा।
परिघेणाभिदुद्राव मारुतात्मजमाहवे॥', 'tato jṛmbhitam ālokya harṣād devāntakas tadā
parigheṇābhidudrāva mārutātmajam āhave', null, 6058022),
('ramayana-6-58-23', 23, 'Yuddha Kanda, Sarga 58, Verse 23', 'तमापतन्तमुत्पत्य हनूमान्मारुतात्मजः।
आजघान तदा मूर्ध्नि वज्रवेगेन मुष्टिना॥', 'tam āpatantam utpatya hanūmān mārutātmajaḥ
ājaghāna tadā mūrdhni vajravegena muṣṭinā', null, 6058023),
('ramayana-6-58-24', 24, 'Yuddha Kanda, Sarga 58, Verse 24', 'स मुष्टिनिष्पिष्टविकीर्णमूर्धा निर्वान्तदन्ताक्षिविलम्बिजिह्वः।
देवान्तको राक्षसराजसूनुर्गतासुरुर्व्यां सहसा पपात॥', 'sa muṣṭiniṣpiṣṭavikīrṇamūrdhā nirvāntadantākṣivilambijihvaḥ
devāntako rākṣasarājasūnur gatāsur urvyāṃ sahasā papāta', null, 6058024),
('ramayana-6-58-25', 25, 'Yuddha Kanda, Sarga 58, Verse 25', 'तस्मिन्हते राक्षसयोधमुख्ये महाबले संयति देवशत्रौ।
क्रुद्धस्त्रिमूर्धा निशिताग्रमुग्रं ववर्ष नीलोरसि बाणवर्षम्॥', 'tasmin hate rākṣasayodhamukhye mahābale saṃyati devaśatrau
kruddhas trimūrdhā niśitāgram ugraṃ vavarṣa nīlorasi bāṇavarṣam', null, 6058025),
('ramayana-6-58-26', 26, 'Yuddha Kanda, Sarga 58, Verse 26', 'स तैः शरौघैरभिवर्ष्यमाणो विभिन्नगात्रः कपिसैन्यपालः।
नीलो बभूवाथ विसृष्टगात्रो विष्टम्भितस्तेन महाबलेन॥', 'sa taiḥ śaraughair abhivarṣyamāṇo vibhinnagātraḥ kapisainyapālaḥ
nīlo babhūvātha visṛṣṭagātro viṣṭambhitas tena mahābalena', null, 6058026),
('ramayana-6-58-27', 27, 'Yuddha Kanda, Sarga 58, Verse 27', 'ततस्तु नीलः प्रतिलभ्य संज्ञां शैलं समुत्पाट्य सवृक्षषण्डम्।
ततः समुत्पत्य भृशोग्रवेगो महोदरं तेन जघान मूर्ध्नि॥', 'tatas tu nīlaḥ pratilabhya saṃjñāṃ śailaṃ samutpāṭya savṛkṣaṣaṇḍam
tataḥ samutpatya bhṛśogravego mahodaraṃ tena jaghāna mūrdhni', null, 6058027),
('ramayana-6-58-28', 28, 'Yuddha Kanda, Sarga 58, Verse 28', 'ततः स शैलाभिनिपातभग्नो महोदरस्तेन सह द्विपेन।
विपोथितो भूमितले गतासुः पपात वर्जाभिहतो यथाद्रिः॥', 'tataḥ sa śailābhinipātabhagno mahodaras tena saha dvipena
vipothito bhūmitale gatāsuḥ papāta varjābhihato yathādriḥ', null, 6058028),
('ramayana-6-58-29', 29, 'Yuddha Kanda, Sarga 58, Verse 29', 'पितृव्यं निहतं दृष्ट्वा त्रिशिराश्चापमाददे।
हनूमन्तं च संक्रुद्धो विव्याध निशितैः शरैः॥', 'pitṛvyaṃ nihataṃ dṛṣṭvā triśirāś cāpam ādade
hanūmantaṃ ca saṃkruddho vivyādha niśitaiḥ śaraiḥ', null, 6058029),
('ramayana-6-58-30', 30, 'Yuddha Kanda, Sarga 58, Verse 30', 'हनूमांस्तु समुत्पत्य हयांस्त्रिशिरसस्तदा।
विददार नखैः क्रुद्धो गजेन्द्रं मृगराडिव॥', 'hanūmāṃs tu samutpatya hayāṃs triśirasas tadā
vidadāra nakhaiḥ kruddho gajendraṃ mṛgarāḍ iva', null, 6058030),
('ramayana-6-58-31', 31, 'Yuddha Kanda, Sarga 58, Verse 31', 'अथ शक्तिं समादाय कालरात्रिमिवान्तकः।
चिक्षेपानिलपुत्राय त्रिशिरा रावणात्मजः॥', 'atha śaktiṃ samādāya kālarātrim ivāntakaḥ
cikṣepānilaputrāya triśirā rāvaṇātmajaḥ', null, 6058031),
('ramayana-6-58-32', 32, 'Yuddha Kanda, Sarga 58, Verse 32', 'दिवि क्षिप्तामिवोल्कां तां शक्तिं क्षिप्तामसंगताम्।
गृहीत्वा हरिशार्दूलो बभञ्ज च ननाद च॥', 'divi kṣiptām ivolkāṃ tāṃ śaktiṃ kṣiptām asaṃgatām
gṛhītvā hariśārdūlo babhañja ca nanāda ca', null, 6058032),
('ramayana-6-58-33', 33, 'Yuddha Kanda, Sarga 58, Verse 33', 'तां दृष्ट्वा घोरसंकाशां शक्तिं भग्नां हनूमता।
प्रहृष्टा वानरगणा विनेदुर्जलदा इव॥', 'tāṃ dṛṣṭvā ghorasaṃkāśāṃ śaktiṃ bhagnāṃ hanūmatā
prahṛṣṭā vānaragaṇā vinedur jaladā iva', null, 6058033),
('ramayana-6-58-34', 34, 'Yuddha Kanda, Sarga 58, Verse 34', 'ततः खड्गं समुद्यम्य त्रिशिरा राक्षसोत्तमः।
निचखान तदा रोषाद्वानरेन्द्रस्य वक्षसि॥', 'tataḥ khaḍgaṃ samudyamya triśirā rākṣasottamaḥ
nicakhāna tadā roṣād vānarendrasya vakṣasi', null, 6058034),
('ramayana-6-58-35', 35, 'Yuddha Kanda, Sarga 58, Verse 35', 'खड्गप्रहाराभिहतो हनूमान्मारुतात्मजः।
आजघान त्रिमूर्धानं तलेनोरसि वीर्यवान्॥', 'khaḍgaprahārābhihato hanūmān mārutātmajaḥ
ājaghāna trimūrdhānaṃ talenorasi vīryavān', null, 6058035),
('ramayana-6-58-36', 36, 'Yuddha Kanda, Sarga 58, Verse 36', 'स तलभिहतस्तेन स्रस्तहस्ताम्बरो भुवि।
निपपात महातेजास्त्रिशिरास्त्यक्तचेतनः॥', 'sa talabhihatas tena srastahastāmbaro bhuvi
nipapāta mahātejās triśirās tyaktacetanaḥ', null, 6058036),
('ramayana-6-58-37', 37, 'Yuddha Kanda, Sarga 58, Verse 37', 'स तस्य पततः खड्गं समाच्छिद्य महाकपिः।
ननाद गिरिसंकाशस्त्रासयन्सर्वनैरृतान्॥', 'sa tasya patataḥ khaḍgaṃ samācchidya mahākapiḥ
nanāda girisaṃkāśas trāsayan sarvanairṛtān', null, 6058037),
('ramayana-6-58-38', 38, 'Yuddha Kanda, Sarga 58, Verse 38', 'अमृष्यमाणस्तं घोषमुत्पपात निशाचरः।
उत्पत्य च हनूमन्तं ताडयामास मुष्टिना॥', 'amṛṣyamāṇas taṃ ghoṣam utpapāta niśācaraḥ
utpatya ca hanūmantaṃ tāḍayām āsa muṣṭinā', null, 6058038),
('ramayana-6-58-39', 39, 'Yuddha Kanda, Sarga 58, Verse 39', 'तेन मुष्टिप्रहारेण संचुकोप महाकपिः।
कुपितश्च निजग्राह किरीटे राक्षसर्षभम्॥', 'tena muṣṭiprahāreṇa saṃcukopa mahākapiḥ
kupitaś ca nijagrāha kirīṭe rākṣasarṣabham', null, 6058039),
('ramayana-6-58-40', 40, 'Yuddha Kanda, Sarga 58, Verse 40', 'स तस्य शीर्षाण्यसिना शितेन किरीटजुष्टानि सकुण्डलानि।
क्रुद्धः प्रचिच्छेद सुतोऽनिलस्य त्वष्टुः सुतस्येव शिरांसि शक्रः॥', 'sa tasya śīrṣāṇy asinā śitena kirīṭajuṣṭāni sakuṇḍalāni
kruddhaḥ praciccheda suto ''nilasya tvaṣṭuḥ sutasyeva śirāṃsi śakraḥ', null, 6058040),
('ramayana-6-58-41', 41, 'Yuddha Kanda, Sarga 58, Verse 41', 'तान्यायताक्षाण्यगसंनिभानि प्रदीप्तवैश्वानरलोचनानि।
पेतुः शिरांसीन्द्ररिपोर्धरण्यां ज्योतींषि मुक्तानि यथार्कमार्गात्॥', 'tāny āyatākṣāṇy agasaṃnibhāni pradīptavaiśvānaralocanāni
petuḥ śirāṃsīndraripor dharaṇyāṃ jyotīṃṣi muktāni yathārkamārgāt', null, 6058041),
('ramayana-6-58-42', 42, 'Yuddha Kanda, Sarga 58, Verse 42', 'तस्मिन्हते देवरिपौ त्रिशीर्षे हनूमत शक्रपराक्रमेण।
नेदुः प्लवंगाः प्रचचाल भूमी रक्षांस्यथो दुद्रुविरे समन्तात्॥', 'tasmin hate devaripau triśīrṣe hanūmata śakraparākrameṇa
neduḥ plavaṃgāḥ pracacāla bhūmī rakṣāṃsy atho dudruvire samantāt', null, 6058042),
('ramayana-6-58-43', 43, 'Yuddha Kanda, Sarga 58, Verse 43', 'हतं त्रिशिरसं दृष्ट्वा तथैव च महोदरम्।
हतौ प्रेक्ष्य दुराधर्षौ देवान्तकनरान्तकौ॥', 'hataṃ triśirasaṃ dṛṣṭvā tathaiva ca mahodaram
hatau prekṣya durādharṣau devāntakanarāntakau', null, 6058043),
('ramayana-6-58-44', 44, 'Yuddha Kanda, Sarga 58, Verse 44', 'चुकोप परमामर्षी महापार्श्वो महाबलः।
जग्राहार्चिष्मतीं चापि गदां सर्वायसीं शुभाम्॥', 'cukopa paramāmarṣī mahāpārśvo mahābalaḥ
jagrāhārciṣmatīṃ cāpi gadāṃ sarvāyasīṃ śubhām', null, 6058044),
('ramayana-6-58-45', 45, 'Yuddha Kanda, Sarga 58, Verse 45', 'हेमपट्टपरिक्षिप्तां मांसशोणितलेपनाम्।
विराजमानां वपुषा शत्रुशोणितरञ्जिताम्॥', 'hemapaṭṭaparikṣiptāṃ māṃsaśoṇitalepanām
virājamānāṃ vapuṣā śatruśoṇitarañjitām', null, 6058045),
('ramayana-6-58-46', 46, 'Yuddha Kanda, Sarga 58, Verse 46', 'तेजसा संप्रदीप्ताग्रां रक्तमाल्यविभूषिताम्।
ऐरावतमहापद्मसार्वभौम भयावहाम्॥', 'tejasā saṃpradīptāgrāṃ raktamālyavibhūṣitām
airāvatamahāpadmasārvabhauma bhayāvahām', null, 6058046),
('ramayana-6-58-47', 47, 'Yuddha Kanda, Sarga 58, Verse 47', 'गदामादाय संक्रुद्धो महापार्श्वो महाबलः।
हरीन्समभिदुद्राव युगान्ताग्निरिव ज्वलन्॥', 'gadām ādāya saṃkruddho mahāpārśvo mahābalaḥ
harīn samabhidudrāva yugāntāgnir iva jvalan', null, 6058047),
('ramayana-6-58-48', 48, 'Yuddha Kanda, Sarga 58, Verse 48', 'अथर्षयः समुत्पत्य वानरो रवणानुजम्।
महापार्श्वमुपागम्य तस्थौ तस्याग्रतो बली॥', 'atharṣayaḥ samutpatya vānaro ravaṇānujam
mahāpārśvam upāgamya tasthau tasyāgrato balī', null, 6058048),
('ramayana-6-58-49', 49, 'Yuddha Kanda, Sarga 58, Verse 49', 'तं पुरस्तात्स्थितं दृष्ट्वा वानरं पर्वतोपमम्।
आजघानोरसि क्रुद्धो गदया वज्रकल्पया॥', 'taṃ purastāt sthitaṃ dṛṣṭvā vānaraṃ parvatopamam
ājaghānorasi kruddho gadayā vajrakalpayā', null, 6058049),
('ramayana-6-58-50', 50, 'Yuddha Kanda, Sarga 58, Verse 50', 'स तयाभिहतस्तेन गदया वानरर्षभः।
भिन्नवक्षाः समाधूतः सुस्राव रुधिरं बहु॥', 'sa tayābhihatas tena gadayā vānararṣabhaḥ
bhinnavakṣāḥ samādhūtaḥ susrāva rudhiraṃ bahu', null, 6058050),
('ramayana-6-58-51', 51, 'Yuddha Kanda, Sarga 58, Verse 51', 'स संप्राप्य चिरात्संज्ञामृषभो वानरर्षभः।
क्रुद्धो विस्फुरमाणौष्ठो महापार्श्वमुदैक्षत॥', 'sa saṃprāpya cirāt saṃjñām ṛṣabho vānararṣabhaḥ
kruddho visphuramāṇauṣṭho mahāpārśvam udaikṣata', null, 6058051),
('ramayana-6-58-52', 52, 'Yuddha Kanda, Sarga 58, Verse 52', 'तां गृहीत्वा गदां भीमामाविध्य च पुनः पुनः।
मत्तानीकं महापार्श्वं जघान रणमूर्धनि॥', 'tāṃ gṛhītvā gadāṃ bhīmām āvidhya ca punaḥ punaḥ
mattānīkaṃ mahāpārśvaṃ jaghāna raṇamūrdhani', null, 6058052),
('ramayana-6-58-53', 53, 'Yuddha Kanda, Sarga 58, Verse 53', 'स स्वया गदया भिन्नो विकीर्णदशनेक्षणः।
निपपात महापार्श्वो वज्राहत इवाचलः॥', 'sa svayā gadayā bhinno vikīrṇadaśanekṣaṇaḥ
nipapāta mahāpārśvo vajrāhata ivācalaḥ', null, 6058053),
('ramayana-6-58-54', 54, 'Yuddha Kanda, Sarga 58, Verse 54', 'तस्मिन्हते भ्रातरि रावणस्य तन्नैरृतानां बलमर्णवाभम्।
त्यक्तायुधं केवलजीवितार्थं दुद्राव भिन्नार्णवसंनिकाशम्॥', 'tasmin hate bhrātari rāvaṇasya tan nairṛtānāṃ balam arṇavābham
tyaktāyudhaṃ kevalajīvitārthaṃ dudrāva bhinnārṇavasaṃnikāśam', null, 6058054)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 59 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-59-1', 1, 'Yuddha Kanda, Sarga 59, Verse 1', 'स्वबलं व्यथितं दृष्ट्वा तुमुलं लोमहर्षणम्।
भ्रातॄंश्च निहतान्दृष्ट्वा शक्रतुल्यपराक्रमान्॥', 'svabalaṃ vyathitaṃ dṛṣṭvā tumulaṃ lomaharṣaṇam
bhrātṝṃś ca nihatān dṛṣṭvā śakratulyaparākramān', null, 6059001),
('ramayana-6-59-2', 2, 'Yuddha Kanda, Sarga 59, Verse 2', 'पितृव्यौ चापि संदृश्य समरे संनिषूदितौ।
महोदरमहापार्श्वौ भ्रातरौ राक्षसर्षभौ॥', 'pitṛvyau cāpi saṃdṛśya samare saṃniṣūditau
mahodaramahāpārśvau bhrātarau rākṣasarṣabhau', null, 6059002),
('ramayana-6-59-3', 3, 'Yuddha Kanda, Sarga 59, Verse 3', 'चुकोप च महातेजा ब्रह्मदत्तवरो युधि।
अतिकायोऽद्रिसंकाशो देवदानवदर्पहा॥', 'cukopa ca mahātejā brahmadattavaro yudhi
atikāyo ''drisaṃkāśo devadānavadarpahā', null, 6059003),
('ramayana-6-59-4', 4, 'Yuddha Kanda, Sarga 59, Verse 4', 'स भास्करसहस्रस्य संघातमिव भास्वरम्।
रथमास्थाय शक्रारिरभिदुद्राव वानरान्॥', 'sa bhāskarasahasrasya saṃghātam iva bhāsvaram
ratham āsthāya śakrārir abhidudrāva vānarān', null, 6059004),
('ramayana-6-59-5', 5, 'Yuddha Kanda, Sarga 59, Verse 5', 'स विस्फार्य महच्चापं किरीटी मृष्टकुण्डलः।
नाम विश्रावयामास ननाद च महास्वनम्॥', 'sa visphārya mahac cāpaṃ kirīṭī mṛṣṭakuṇḍalaḥ
nāma viśrāvayām āsa nanāda ca mahāsvanam', null, 6059005),
('ramayana-6-59-6', 6, 'Yuddha Kanda, Sarga 59, Verse 6', 'तेन सिंहप्रणादेन नामविश्रावणेन च।
ज्याशब्देन च भीमेन त्रासयामास वानरान्॥', 'tena siṃhapraṇādena nāmaviśrāvaṇena ca
jyāśabdena ca bhīmena trāsayām āsa vānarān', null, 6059006),
('ramayana-6-59-7', 7, 'Yuddha Kanda, Sarga 59, Verse 7', 'ते तस्य रूपमालोक्य यथा विष्णोस्त्रिविक्रमे।
भयार्ता वानराः सर्वे विद्रवन्ति दिशो दश॥', 'te tasya rūpam ālokya yathā viṣṇos trivikrame
bhayārtā vānarāḥ sarve vidravanti diśo daśa', null, 6059007),
('ramayana-6-59-8', 8, 'Yuddha Kanda, Sarga 59, Verse 8', 'तेऽतिकायं समासाद्य वानरा मूढचेतसः।
शरण्यं शरणं जग्मुर्लक्ष्मणाग्रजमाहवे॥', 'te ''tikāyaṃ samāsādya vānarā mūḍhacetasaḥ
śaraṇyaṃ śaraṇaṃ jagmur lakṣmaṇāgrajam āhave', null, 6059008),
('ramayana-6-59-9', 9, 'Yuddha Kanda, Sarga 59, Verse 9', 'ततोऽतिकायं काकुत्स्थो रथस्थं पर्वतोपमम्।
ददर्श धन्विनं दूराद्गर्जन्तं कालमेघवत्॥', 'tato ''tikāyaṃ kākutstho rathasthaṃ parvatopamam
dadarśa dhanvinaṃ dūrād garjantaṃ kālameghavat', null, 6059009),
('ramayana-6-59-10', 10, 'Yuddha Kanda, Sarga 59, Verse 10', 'स तं दृष्ट्वा महात्मानं राघवस्तु सुविस्मितः।
वानरान्सान्त्वयित्वा तु विभीषणमुवाच ह॥', 'sa taṃ dṛṣṭvā mahātmānaṃ rāghavas tu suvismitaḥ
vānarān sāntvayitvā tu vibhīṣaṇam uvāca ha', null, 6059010),
('ramayana-6-59-11', 11, 'Yuddha Kanda, Sarga 59, Verse 11', 'कोऽसौ पर्वतसंकाशो धनुष्मान्हरिलोचनः।
युक्ते हयसहस्रेण विशाले स्यन्दने स्थितः॥', 'ko ''sau parvatasaṃkāśo dhanuṣmān harilocanaḥ
yukte hayasahasreṇa viśāle syandane sthitaḥ', null, 6059011),
('ramayana-6-59-12', 12, 'Yuddha Kanda, Sarga 59, Verse 12', 'य एष निशितैः शूलैः सुतीक्ष्णैः प्रासतोमरैः।
अर्चिष्मद्भिर्वृतो भाति भूतैरिव महेश्वरः॥', 'ya eṣa niśitaiḥ śūlaiḥ sutīkṣṇaiḥ prāsatomaraiḥ
arciṣmadbhir vṛto bhāti bhūtair iva maheśvaraḥ', null, 6059012),
('ramayana-6-59-13', 13, 'Yuddha Kanda, Sarga 59, Verse 13', 'कालजिह्वाप्रकाशाभिर्य एषोऽभिविराजते।
आवृतो रथशक्तीभिर्विद्युद्भिरिव तोयदः॥', 'kālajihvāprakāśābhir ya eṣo ''bhivirājate
āvṛto rathaśaktībhir vidyudbhir iva toyadaḥ', null, 6059013),
('ramayana-6-59-14', 14, 'Yuddha Kanda, Sarga 59, Verse 14', 'धनूंसि चास्य सज्यानि हेमपृष्ठानि सर्वशः।
शोभयन्ति रथश्रेष्ठं शक्रपातमिवाम्बरम्॥', 'dhanūṃsi cāsya sajyāni hemapṛṣṭhāni sarvaśaḥ
śobhayanti rathaśreṣṭhaṃ śakrapātam ivāmbaram', null, 6059014),
('ramayana-6-59-15', 15, 'Yuddha Kanda, Sarga 59, Verse 15', 'क एष रक्षः शार्दूलो रणभूमिं विराजयन्।
अभ्येति रथिनां श्रेष्ठो रथेनादित्यतेजसा॥', 'ka eṣa rakṣaḥ śārdūlo raṇabhūmiṃ virājayan
abhyeti rathināṃ śreṣṭho rathenādityatejasā', null, 6059015),
('ramayana-6-59-16', 16, 'Yuddha Kanda, Sarga 59, Verse 16', 'ध्वजशृङ्गप्रतिष्ठेन राहुणाभिविराजते।
सूर्यरश्मिप्रभैर्बाणैर्दिशो दश विराजयन्॥', 'dhvajaśṛṅgapratiṣṭhena rāhuṇābhivirājate
sūryaraśmiprabhair bāṇair diśo daśa virājayan', null, 6059016),
('ramayana-6-59-17', 17, 'Yuddha Kanda, Sarga 59, Verse 17', 'त्रिणतं मेघनिर्ह्रादं हेमपृष्ठमलंकृतम्।
शतक्रतुधनुःप्रख्यं धनुश्चास्य विराजते॥', 'triṇataṃ meghanirhrādaṃ hemapṛṣṭham alaṃkṛtam
śatakratudhanuḥprakhyaṃ dhanuś cāsya virājate', null, 6059017),
('ramayana-6-59-18', 18, 'Yuddha Kanda, Sarga 59, Verse 18', 'सध्वजः सपताकश्च सानुकर्षो महारथः।
चतुःसादिसमायुक्तो मेघस्तनितनिस्वनः॥', 'sadhvajaḥ sapatākaś ca sānukarṣo mahārathaḥ
catuḥsādisamāyukto meghastanitanisvanaḥ', null, 6059018),
('ramayana-6-59-19', 19, 'Yuddha Kanda, Sarga 59, Verse 19', 'विंशतिर्दश चाष्टौ च तूणीररथमास्थिताः।
कार्मुकाणि च भीमानि ज्याश्च काञ्चनपिङ्गलाः॥', 'viṃśatir daśa cāṣṭau ca tūṇīraratham āsthitāḥ
kārmukāṇi ca bhīmāni jyāś ca kāñcanapiṅgalāḥ', null, 6059019),
('ramayana-6-59-20', 20, 'Yuddha Kanda, Sarga 59, Verse 20', 'द्वौ च खड्गौ रथगतौ पार्श्वस्थौ पार्श्वशोभिनौ।
चतुर्हस्तत्सरुचितौ व्यक्तहस्तदशायतौ॥', 'dvau ca khaḍgau rathagatau pārśvasthau pārśvaśobhinau
caturhastatsarucitau vyaktahastadaśāyatau', null, 6059020),
('ramayana-6-59-21', 21, 'Yuddha Kanda, Sarga 59, Verse 21', 'रक्तकण्ठगुणो धीरो महापर्वतसंनिभः।
कालः कालमहावक्त्रो मेघस्थ इव भास्करः॥', 'raktakaṇṭhaguṇo dhīro mahāparvatasaṃnibhaḥ
kālaḥ kālamahāvaktro meghastha iva bhāskaraḥ', null, 6059021),
('ramayana-6-59-22', 22, 'Yuddha Kanda, Sarga 59, Verse 22', 'काञ्चनाङ्गदनद्धाभ्यां भुजाभ्यामेष शोभते।
शृङ्गाभ्यामिव तुङ्गाभ्यां हिमवान्पर्वतोत्तमः॥', 'kāñcanāṅgadanaddhābhyāṃ bhujābhyām eṣa śobhate
śṛṅgābhyām iva tuṅgābhyāṃ himavān parvatottamaḥ', null, 6059022),
('ramayana-6-59-23', 23, 'Yuddha Kanda, Sarga 59, Verse 23', 'कुण्डलाभ्यां तु यस्यैतद्भाति वक्त्रं शुभेक्षणम्।
पुनर्वस्वन्तरगतं पूर्णबिम्बमिवैन्दवम्॥', 'kuṇḍalābhyāṃ tu yasyaitad bhāti vaktraṃ śubhekṣaṇam
punarvasvantaragataṃ pūrṇabimbam ivaindavam', null, 6059023),
('ramayana-6-59-24', 24, 'Yuddha Kanda, Sarga 59, Verse 24', 'आचक्ष्व मे महाबाहो त्वमेनं राक्षसोत्तमम्।
यं दृष्ट्वा वानराः सर्वे भयार्ता विद्रुता दिशः॥', 'ācakṣva me mahābāho tvam enaṃ rākṣasottamam
yaṃ dṛṣṭvā vānarāḥ sarve bhayārtā vidrutā diśaḥ', null, 6059024),
('ramayana-6-59-25', 25, 'Yuddha Kanda, Sarga 59, Verse 25', 'स पृष्ठो राजपुत्रेण रामेणामिततेजसा।
आचचक्षे महातेजा राघवाय विभीषणः॥', 'sa pṛṣṭho rājaputreṇa rāmeṇāmitatejasā
ācacakṣe mahātejā rāghavāya vibhīṣaṇaḥ', null, 6059025),
('ramayana-6-59-26', 26, 'Yuddha Kanda, Sarga 59, Verse 26', 'दशग्रीवो महातेजा राजा वैश्रवणानुजः।
भीमकर्मा महोत्साहो रावणो राक्षसाधिपः॥', 'daśagrīvo mahātejā rājā vaiśravaṇānujaḥ
bhīmakarmā mahotsāho rāvaṇo rākṣasādhipaḥ', null, 6059026),
('ramayana-6-59-27', 27, 'Yuddha Kanda, Sarga 59, Verse 27', 'तस्यासीद्वीर्यवान्पुत्रो रावणप्रतिमो रणे।
वृद्धसेवी श्रुतधरः सर्वास्त्रविदुषां वरः॥', 'tasyāsīd vīryavān putro rāvaṇapratimo raṇe
vṛddhasevī śrutadharaḥ sarvāstraviduṣāṃ varaḥ', null, 6059027),
('ramayana-6-59-28', 28, 'Yuddha Kanda, Sarga 59, Verse 28', 'अश्वपृष्ठे रथे नागे खड्गे धनुषि कर्षणे।
भेदे सान्त्वे च दाने च नये मन्त्रे च संमतः॥', 'aśvapṛṣṭhe rathe nāge khaḍge dhanuṣi karṣaṇe
bhede sāntve ca dāne ca naye mantre ca saṃmataḥ', null, 6059028),
('ramayana-6-59-29', 29, 'Yuddha Kanda, Sarga 59, Verse 29', 'यस्य बाहुं समाश्रित्य लङ्का भवति निर्भया।
तनयं धान्यमालिन्या अतिकायमिमं विदुः॥', 'yasya bāhuṃ samāśritya laṅkā bhavati nirbhayā
tanayaṃ dhānyamālinyā atikāyam imaṃ viduḥ', null, 6059029),
('ramayana-6-59-30', 30, 'Yuddha Kanda, Sarga 59, Verse 30', 'एतेनाराधितो ब्रह्मा तपसा भावितात्मना।
अस्त्राणि चाप्यवाप्तानि रिपवश्च पराजिताः॥', 'etenārādhito brahmā tapasā bhāvitātmanā
astrāṇi cāpy avāptāni ripavaś ca parājitāḥ', null, 6059030),
('ramayana-6-59-31', 31, 'Yuddha Kanda, Sarga 59, Verse 31', 'सुरासुरैरवध्यत्वं दत्तमस्मै स्वयम्भुवा।
एतच्च कवचं दिव्यं रथश्चैषोऽर्कभास्करः॥', 'surāsurair avadhyatvaṃ dattam asmai svayambhuvā
etac ca kavacaṃ divyaṃ rathaś caiṣo ''rkabhāskaraḥ', null, 6059031),
('ramayana-6-59-32', 32, 'Yuddha Kanda, Sarga 59, Verse 32', 'एतेन शतशो देवा दानवाश्च पराजिताः।
रक्षितानि च रक्षामि यक्षाश्चापि निषूदिताः॥', 'etena śataśo devā dānavāś ca parājitāḥ
rakṣitāni ca rakṣāmi yakṣāś cāpi niṣūditāḥ', null, 6059032),
('ramayana-6-59-33', 33, 'Yuddha Kanda, Sarga 59, Verse 33', 'वज्रं विष्टम्भितं येन बाणैरिन्द्रस्य धीमतः।
पाशः सलिलराजस्य युद्धे प्रतिहतस्तथा॥', 'vajraṃ viṣṭambhitaṃ yena bāṇair indrasya dhīmataḥ
pāśaḥ salilarājasya yuddhe pratihatas tathā', null, 6059033),
('ramayana-6-59-34', 34, 'Yuddha Kanda, Sarga 59, Verse 34', 'एषोऽतिकायो बलवान्राक्षसानामथर्षभः।
रावणस्य सुतो धीमान्देवदनव दर्पहा॥', 'eṣo ''tikāyo balavān rākṣasānām atharṣabhaḥ
rāvaṇasya suto dhīmān devadanava darpahā', null, 6059034),
('ramayana-6-59-35', 35, 'Yuddha Kanda, Sarga 59, Verse 35', 'तदस्मिन्क्रियतां यत्नः क्षिप्रं पुरुषपुंगव।
पुरा वानरसैन्यानि क्षयं नयति सायकैः॥', 'tad asmin kriyatāṃ yatnaḥ kṣipraṃ puruṣapuṃgava
purā vānarasainyāni kṣayaṃ nayati sāyakaiḥ', null, 6059035),
('ramayana-6-59-36', 36, 'Yuddha Kanda, Sarga 59, Verse 36', 'ततोऽतिकायो बलवान्प्रविश्य हरिवाहिनीम्।
विस्फारयामास धनुर्ननाद च पुनः पुनः॥', 'tato ''tikāyo balavān praviśya harivāhinīm
visphārayām āsa dhanur nanāda ca punaḥ punaḥ', null, 6059036),
('ramayana-6-59-37', 37, 'Yuddha Kanda, Sarga 59, Verse 37', 'तं भीमवपुषं दृष्ट्वा रथस्थं रथिनां वरम्।
अभिपेतुर्महात्मानो ये प्रधानाः प्लवंगमाः॥', 'taṃ bhīmavapuṣaṃ dṛṣṭvā rathasthaṃ rathināṃ varam
abhipetur mahātmāno ye pradhānāḥ plavaṃgamāḥ', null, 6059037),
('ramayana-6-59-38', 38, 'Yuddha Kanda, Sarga 59, Verse 38', 'कुमुदो द्विविदो मैन्दो नीलः शरभ एव च।
पादपैर्गिरिशृङ्गैश्च युगपत्समभिद्रवन्॥', 'kumudo dvivido maindo nīlaḥ śarabha eva ca
pādapair giriśṛṅgaiś ca yugapat samabhidravan', null, 6059038),
('ramayana-6-59-39', 39, 'Yuddha Kanda, Sarga 59, Verse 39', 'तेषां वृक्षांश्च शैलांश्च शरैः काञ्चनभूषणैः।
अतिकायो महातेजाश्चिच्छेदास्त्रविदां वरः॥', 'teṣāṃ vṛkṣāṃś ca śailāṃś ca śaraiḥ kāñcanabhūṣaṇaiḥ
atikāyo mahātejāś cicchedāstravidāṃ varaḥ', null, 6059039),
('ramayana-6-59-40', 40, 'Yuddha Kanda, Sarga 59, Verse 40', 'तांश्चैव सरान्स हरीञ्शरैः सर्वायसैर्बली।
विव्याधाभिमुखः संख्ये भीमकायो निशाचरः॥', 'tāṃś caiva sarān sa harīñ śaraiḥ sarvāyasair balī
vivyādhābhimukhaḥ saṃkhye bhīmakāyo niśācaraḥ', null, 6059040),
('ramayana-6-59-41', 41, 'Yuddha Kanda, Sarga 59, Verse 41', 'तेऽर्दिता बाणबर्षेण भिन्नगात्राः प्लवंगमाः।
न शेकुरतिकायस्य प्रतिकर्तुं महारणे॥', 'te ''rditā bāṇabarṣeṇa bhinnagātrāḥ plavaṃgamāḥ
na śekur atikāyasya pratikartuṃ mahāraṇe', null, 6059041),
('ramayana-6-59-42', 42, 'Yuddha Kanda, Sarga 59, Verse 42', 'तत्सैन्यं हरिवीराणां त्रासयामास राक्षसः।
मृगयूथमिव क्रुद्धो हरिर्यौवनमास्थितः॥', 'tat sainyaṃ harivīrāṇāṃ trāsayām āsa rākṣasaḥ
mṛgayūtham iva kruddho harir yauvanam āsthitaḥ', null, 6059042),
('ramayana-6-59-43', 43, 'Yuddha Kanda, Sarga 59, Verse 43', 'स राषसेन्द्रो हरिसैन्यमध्ये नायुध्यमानं निजघान कं चित्।
उपेत्य रामं सधनुः कलापी सगर्वितं वाक्यमिदं बभाषे॥', 'sa rāṣasendro harisainyamadhye nāyudhyamānaṃ nijaghāna kaṃ cit
upetya rāmaṃ sadhanuḥ kalāpī sagarvitaṃ vākyam idaṃ babhāṣe', null, 6059043),
('ramayana-6-59-44', 44, 'Yuddha Kanda, Sarga 59, Verse 44', 'रथे स्थितोऽहं शरचापपाणिर्न प्राकृतं कं चन योधयामि।
यस्यास्ति शक्तिर्व्यवसाय युक्ता ददातुं मे क्षिप्रमिहाद्य युद्धम्॥', 'rathe sthito ''haṃ śaracāpapāṇir na prākṛtaṃ kaṃ cana yodhayāmi
yasyāsti śaktir vyavasāya yuktā dadātuṃ me kṣipram ihādya yuddham', null, 6059044),
('ramayana-6-59-45', 45, 'Yuddha Kanda, Sarga 59, Verse 45', 'तत्तस्य वाक्यं ब्रुवतो निशम्य चुकोप सौमित्रिरमित्रहन्ता।
अमृष्यमाणश्च समुत्पपात जग्राह चापं च ततः स्मयित्वा॥', 'tat tasya vākyaṃ bruvato niśamya cukopa saumitrir amitrahantā
amṛṣyamāṇaś ca samutpapāta jagrāha cāpaṃ ca tataḥ smayitvā', null, 6059045),
('ramayana-6-59-46', 46, 'Yuddha Kanda, Sarga 59, Verse 46', 'क्रुद्धः सौमित्रिरुत्पत्य तूणादाक्षिप्य सायकम्।
पुरस्तादतिकायस्य विचकर्ष महद्धनुः॥', 'kruddhaḥ saumitrir utpatya tūṇād ākṣipya sāyakam
purastād atikāyasya vicakarṣa mahad dhanuḥ', null, 6059046),
('ramayana-6-59-47', 47, 'Yuddha Kanda, Sarga 59, Verse 47', 'पूरयन्स महीं शैलानाकाशं सागरं दिशः।
ज्याशब्दो लक्ष्मणस्योग्रस्त्रासयन्रजनीचरान्॥', 'pūrayan sa mahīṃ śailān ākāśaṃ sāgaraṃ diśaḥ
jyāśabdo lakṣmaṇasyogras trāsayan rajanīcarān', null, 6059047),
('ramayana-6-59-48', 48, 'Yuddha Kanda, Sarga 59, Verse 48', 'सौमित्रेश्चापनिर्घोषं श्रुत्वा प्रतिभयं तदा।
विसिष्मिये महातेजा राक्षसेन्द्रात्मजो बली॥', 'saumitreś cāpanirghoṣaṃ śrutvā pratibhayaṃ tadā
visiṣmiye mahātejā rākṣasendrātmajo balī', null, 6059048),
('ramayana-6-59-49', 49, 'Yuddha Kanda, Sarga 59, Verse 49', 'अथातिकायः कुपितो दृष्ट्वा लक्ष्मणमुत्थितम्।
आदाय निशितं बाणमिदं वचनमब्रवीत्॥', 'athātikāyaḥ kupito dṛṣṭvā lakṣmaṇam utthitam
ādāya niśitaṃ bāṇam idaṃ vacanam abravīt', null, 6059049),
('ramayana-6-59-50', 50, 'Yuddha Kanda, Sarga 59, Verse 50', 'बालस्त्वमसि सौमित्रे विक्रमेष्वविचक्षणः।
गच्छ किं कालसदृशं मां योधयितुमिच्छसि॥', 'bālas tvam asi saumitre vikrameṣv avicakṣaṇaḥ
gaccha kiṃ kālasadṛśaṃ māṃ yodhayitum icchasi', null, 6059050),
('ramayana-6-59-51', 51, 'Yuddha Kanda, Sarga 59, Verse 51', 'न हि मद्बाहुसृष्टानामस्त्राणां हिमवानपि।
सोढुमुत्सहते वेगमन्तरिक्षमथो मही॥', 'na hi madbāhusṛṣṭānām astrāṇāṃ himavān api
soḍhum utsahate vegam antarikṣam atho mahī', null, 6059051),
('ramayana-6-59-52', 52, 'Yuddha Kanda, Sarga 59, Verse 52', 'सुखप्रसुप्तं कालाग्निं प्रबोधयितुमिच्छसि।
न्यस्य चापं निवर्तस्व मा प्राणाञ्जहि मद्गतः॥', 'sukhaprasuptaṃ kālāgniṃ prabodhayitum icchasi
nyasya cāpaṃ nivartasva mā prāṇāñ jahi madgataḥ', null, 6059052),
('ramayana-6-59-53', 53, 'Yuddha Kanda, Sarga 59, Verse 53', 'अथ वा त्वं प्रतिष्टब्धो न निवर्तितुमिच्छसि।
तिष्ठ प्राणान्परित्यज्य गमिष्यसि यमक्षयम्॥', 'atha vā tvaṃ pratiṣṭabdho na nivartitum icchasi
tiṣṭha prāṇān parityajya gamiṣyasi yamakṣayam', null, 6059053),
('ramayana-6-59-54', 54, 'Yuddha Kanda, Sarga 59, Verse 54', 'पश्य मे निशितान्बाणानरिदर्पनिषूदनान्।
ईश्वरायुधसंकाशांस्तप्तकाञ्चनभूषणान्॥', 'paśya me niśitān bāṇān aridarpaniṣūdanān
īśvarāyudhasaṃkāśāṃs taptakāñcanabhūṣaṇān', null, 6059054),
('ramayana-6-59-55', 55, 'Yuddha Kanda, Sarga 59, Verse 55', 'एष ते सर्पसंकाशो बाणः पास्यति शोणितम्।
मृगराज इव क्रुद्धो नागराजस्य शोणितम्॥', 'eṣa te sarpasaṃkāśo bāṇaḥ pāsyati śoṇitam
mṛgarāja iva kruddho nāgarājasya śoṇitam', null, 6059055),
('ramayana-6-59-56', 56, 'Yuddha Kanda, Sarga 59, Verse 56', 'श्रुत्वातिकायस्य वचः सरोषं सगर्वितं संयति राजपुत्रः।
स संचुकोपातिबलो बृहच्छ्रीरुवाच वाक्यं च ततो महार्थम्॥', 'śrutvātikāyasya vacaḥ saroṣaṃ sagarvitaṃ saṃyati rājaputraḥ
sa saṃcukopātibalo bṛhacchrīr uvāca vākyaṃ ca tato mahārtham', null, 6059056),
('ramayana-6-59-57', 57, 'Yuddha Kanda, Sarga 59, Verse 57', 'न वाक्यमात्रेण भवान्प्रधानो न कत्थनात्सत्पुरुषा भवन्ति।
मयि स्थिते धन्विनि बाणपाणौ विदर्शयस्वात्मबलं दुरात्मन्॥', 'na vākyamātreṇa bhavān pradhāno na katthanāt satpuruṣā bhavanti
mayi sthite dhanvini bāṇapāṇau vidarśayasvātmabalaṃ durātman', null, 6059057),
('ramayana-6-59-58', 58, 'Yuddha Kanda, Sarga 59, Verse 58', 'कर्मणा सूचयात्मानं न विकत्थितुमर्हसि।
पौरुषेण तु यो युक्तः स तु शूर इति स्मृतः॥', 'karmaṇā sūcayātmānaṃ na vikatthitum arhasi
pauruṣeṇa tu yo yuktaḥ sa tu śūra iti smṛtaḥ', null, 6059058),
('ramayana-6-59-59', 59, 'Yuddha Kanda, Sarga 59, Verse 59', 'सर्वायुधसमायुक्तो धन्वी त्वं रथमास्थितः।
शरैर्वा यदि वाप्यस्त्रैर्दर्शयस्व पराक्रमम्॥', 'sarvāyudhasamāyukto dhanvī tvaṃ ratham āsthitaḥ
śarair vā yadi vāpy astrair darśayasva parākramam', null, 6059059),
('ramayana-6-59-60', 60, 'Yuddha Kanda, Sarga 59, Verse 60', 'ततः शिरस्ते निशितैः पातयिष्याम्यहं शरैः।
मारुतः कालसंपक्वं वृन्तात्तालफलं यथा॥', 'tataḥ śiras te niśitaiḥ pātayiṣyāmy ahaṃ śaraiḥ
mārutaḥ kālasaṃpakvaṃ vṛntāt tālaphalaṃ yathā', null, 6059060),
('ramayana-6-59-61', 61, 'Yuddha Kanda, Sarga 59, Verse 61', 'अद्य ते मामका बाणास्तप्तकाञ्चनभूषणाः।
पास्यन्ति रुधिरं गात्राद्बाणशल्यान्तरोत्थितम्॥', 'adya te māmakā bāṇās taptakāñcanabhūṣaṇāḥ
pāsyanti rudhiraṃ gātrād bāṇaśalyāntarotthitam', null, 6059061),
('ramayana-6-59-62', 62, 'Yuddha Kanda, Sarga 59, Verse 62', 'बालोऽयमिति विज्ञाय न मावज्ञातुमर्हसि।
बालो वा यदि वा वृद्धो मृत्युं जानीहि संयुगे॥', 'bālo ''yam iti vijñāya na māvajñātum arhasi
bālo vā yadi vā vṛddho mṛtyuṃ jānīhi saṃyuge', null, 6059062),
('ramayana-6-59-63', 63, 'Yuddha Kanda, Sarga 59, Verse 63', 'लक्ष्मणस्य वचः श्रुत्वा हेतुमत्परमार्थवत्।
अतिकायः प्रचुक्रोध बाणं चोत्तममाददे॥', 'lakṣmaṇasya vacaḥ śrutvā hetumat paramārthavat
atikāyaḥ pracukrodha bāṇaṃ cottamam ādade', null, 6059063),
('ramayana-6-59-64', 64, 'Yuddha Kanda, Sarga 59, Verse 64', 'ततो विद्याधरा भूता देवा दैत्या महर्षयः।
गुह्यकाश्च महात्मानस्तद्युद्धं ददृशुस्तदा॥', 'tato vidyādharā bhūtā devā daityā maharṣayaḥ
guhyakāś ca mahātmānas tad yuddhaṃ dadṛśus tadā', null, 6059064),
('ramayana-6-59-65', 65, 'Yuddha Kanda, Sarga 59, Verse 65', 'ततोऽतिकायः कुपितश्चापमारोप्य सायकम्।
लक्ष्मणस्य प्रचिक्षेप संक्षिपन्निव चाम्बरम्॥', 'tato ''tikāyaḥ kupitaś cāpam āropya sāyakam
lakṣmaṇasya pracikṣepa saṃkṣipann iva cāmbaram', null, 6059065),
('ramayana-6-59-66', 66, 'Yuddha Kanda, Sarga 59, Verse 66', 'तमापतन्तं निशितं शरमाशीविषोपमम्।
अर्धचन्द्रेण चिच्छेद लक्ष्मणः परवीरहा॥', 'tam āpatantaṃ niśitaṃ śaram āśīviṣopamam
ardhacandreṇa ciccheda lakṣmaṇaḥ paravīrahā', null, 6059066),
('ramayana-6-59-67', 67, 'Yuddha Kanda, Sarga 59, Verse 67', 'तं निकृत्तं शरं दृष्ट्वा कृत्तभोगमिवोरगम्।
अतिकायो भृशं क्रुद्धः पञ्चबाणान्समाददे॥', 'taṃ nikṛttaṃ śaraṃ dṛṣṭvā kṛttabhogam ivoragam
atikāyo bhṛśaṃ kruddhaḥ pañcabāṇān samādade', null, 6059067),
('ramayana-6-59-68', 68, 'Yuddha Kanda, Sarga 59, Verse 68', 'ताञ्शरान्संप्रचिक्षेप लक्ष्मणाय निशाचरः।
तानप्राप्ताञ्शरैस्तीक्ष्णैश्चिच्छेद भरतानुजः॥', 'tāñ śarān saṃpracikṣepa lakṣmaṇāya niśācaraḥ
tān aprāptāñ śarais tīkṣṇaiś ciccheda bharatānujaḥ', null, 6059068),
('ramayana-6-59-69', 69, 'Yuddha Kanda, Sarga 59, Verse 69', 'स तांश्छित्त्वा शरैस्तीक्ष्णैर्लक्ष्मणः परवीरहा।
आददे निशितं बाणं ज्वलन्तमिव तेजसा॥', 'sa tāṃś chittvā śarais tīkṣṇair lakṣmaṇaḥ paravīrahā
ādade niśitaṃ bāṇaṃ jvalantam iva tejasā', null, 6059069),
('ramayana-6-59-70', 70, 'Yuddha Kanda, Sarga 59, Verse 70', 'तमादाय धनुः श्रेष्ठे योजयामास लक्ष्मणः।
विचकर्ष च वेगेन विससर्ज च सायकम्॥', 'tam ādāya dhanuḥ śreṣṭhe yojayām āsa lakṣmaṇaḥ
vicakarṣa ca vegena visasarja ca sāyakam', null, 6059070),
('ramayana-6-59-71', 71, 'Yuddha Kanda, Sarga 59, Verse 71', 'पूर्णायतविसृष्टेन शरेणानत पर्वणा।
ललाटे राक्षसश्रेष्ठमाजघान स वीर्यवान्॥', 'pūrṇāyatavisṛṣṭena śareṇānata parvaṇā
lalāṭe rākṣasaśreṣṭham ājaghāna sa vīryavān', null, 6059071),
('ramayana-6-59-72', 72, 'Yuddha Kanda, Sarga 59, Verse 72', 'स ललाटे शरो मग्नस्तस्य भीमस्य रक्षसः।
ददृशे शोणितेनाक्तः पन्नगेन्द्र इवाहवे॥', 'sa lalāṭe śaro magnas tasya bhīmasya rakṣasaḥ
dadṛśe śoṇitenāktaḥ pannagendra ivāhave', null, 6059072),
('ramayana-6-59-73', 73, 'Yuddha Kanda, Sarga 59, Verse 73', 'राक्षसः प्रचकम्पे च लक्ष्मणेषु प्रकम्पितः।
रुद्रबाणहतं भीमं यथा त्रिपुरगोपुरम्॥', 'rākṣasaḥ pracakampe ca lakṣmaṇeṣu prakampitaḥ
rudrabāṇahataṃ bhīmaṃ yathā tripuragopuram', null, 6059073),
('ramayana-6-59-74', 74, 'Yuddha Kanda, Sarga 59, Verse 74', 'चिन्तयामास चाश्वस्य विमृश्य च महाबलः।
साधु बाणनिपातेन श्वाघनीयोऽसि मे रिपुः॥', 'cintayām āsa cāśvasya vimṛśya ca mahābalaḥ
sādhu bāṇanipātena śvāghanīyo ''si me ripuḥ', null, 6059074),
('ramayana-6-59-75', 75, 'Yuddha Kanda, Sarga 59, Verse 75', 'विचार्यैवं विनम्यास्यं विनम्य च भुजावुभौ।
स रथोपस्थमास्थाय रथेन प्रचचार ह॥', 'vicāryaivaṃ vinamyāsyaṃ vinamya ca bhujāv ubhau
sa rathopastham āsthāya rathena pracacāra ha', null, 6059075),
('ramayana-6-59-76', 76, 'Yuddha Kanda, Sarga 59, Verse 76', 'एकं त्रीन्पञ्च सप्तेति सायकान्राक्षसर्षभः।
आददे संदधे चापि विचकर्षोत्ससर्ज च॥', 'ekaṃ trīn pañca sapteti sāyakān rākṣasarṣabhaḥ
ādade saṃdadhe cāpi vicakarṣotsasarja ca', null, 6059076),
('ramayana-6-59-77', 77, 'Yuddha Kanda, Sarga 59, Verse 77', 'ते बाणाः कालसंकाशा राक्षसेन्द्रधनुश्च्युताः।
हेमपुङ्खा रविप्रख्याश्चक्रुर्दीप्तमिवाम्बरम्॥', 'te bāṇāḥ kālasaṃkāśā rākṣasendradhanuś cyutāḥ
hemapuṅkhā raviprakhyāś cakrur dīptam ivāmbaram', null, 6059077),
('ramayana-6-59-78', 78, 'Yuddha Kanda, Sarga 59, Verse 78', 'ततस्तान्राक्षसोत्सृष्टाञ्शरौघान्रावणानुजः।
असंभ्रान्तः प्रचिच्छेद निशितैर्बहुभिः शरैः॥', 'tatas tān rākṣasotsṛṣṭāñ śaraughān rāvaṇānujaḥ
asaṃbhrāntaḥ praciccheda niśitair bahubhiḥ śaraiḥ', null, 6059078),
('ramayana-6-59-79', 79, 'Yuddha Kanda, Sarga 59, Verse 79', 'ताञ्शरान्युधि संप्रेक्ष्य निकृत्तान्रावणात्मजः।
चुकोप त्रिदशेन्द्रारिर्जग्राह निशितं शरम्॥', 'tāñ śarān yudhi saṃprekṣya nikṛttān rāvaṇātmajaḥ
cukopa tridaśendrārir jagrāha niśitaṃ śaram', null, 6059079),
('ramayana-6-59-80', 80, 'Yuddha Kanda, Sarga 59, Verse 80', 'स संधाय महातेजास्तं बाणं सहसोत्सृजत्।
ततः सौमित्रिमायान्तमाजघान स्तनान्तरे॥', 'sa saṃdhāya mahātejās taṃ bāṇaṃ sahasotsṛjat
tataḥ saumitrim āyāntam ājaghāna stanāntare', null, 6059080),
('ramayana-6-59-81', 81, 'Yuddha Kanda, Sarga 59, Verse 81', 'अतिकायेन सौमित्रिस्ताडितो युधि वक्षसि।
सुस्राव रुधिरं तीव्रं मदं मत्त इव द्विपः॥', 'atikāyena saumitris tāḍito yudhi vakṣasi
susrāva rudhiraṃ tīvraṃ madaṃ matta iva dvipaḥ', null, 6059081),
('ramayana-6-59-82', 82, 'Yuddha Kanda, Sarga 59, Verse 82', 'स चकार तदात्मानं विशल्यं सहसा विभुः।
जग्राह च शरं तीष्णमस्त्रेणापि समादधे॥', 'sa cakāra tadātmānaṃ viśalyaṃ sahasā vibhuḥ
jagrāha ca śaraṃ tīṣṇam astreṇāpi samādadhe', null, 6059082),
('ramayana-6-59-83', 83, 'Yuddha Kanda, Sarga 59, Verse 83', 'आग्नेयेन तदास्त्रेण योजयामास सायकम्।
स जज्वाल तदा बाणो धनुश्चास्य महात्मनः॥', 'āgneyena tadāstreṇa yojayām āsa sāyakam
sa jajvāla tadā bāṇo dhanuś cāsya mahātmanaḥ', null, 6059083),
('ramayana-6-59-84', 84, 'Yuddha Kanda, Sarga 59, Verse 84', 'अतिकायोऽतितेजस्वी सौरमस्त्रं समाददे।
तेन बाणं भुजंगाभं हेमपुङ्खमयोजयत्॥', 'atikāyo ''titejasvī sauram astraṃ samādade
tena bāṇaṃ bhujaṃgābhaṃ hemapuṅkham ayojayat', null, 6059084),
('ramayana-6-59-85', 85, 'Yuddha Kanda, Sarga 59, Verse 85', 'ततस्तं ज्वलितं घोरं लक्ष्मणः शरमाहितम्।
अतिकायाय चिक्षेप कालदण्डमिवान्तकः॥', 'tatas taṃ jvalitaṃ ghoraṃ lakṣmaṇaḥ śaram āhitam
atikāyāya cikṣepa kāladaṇḍam ivāntakaḥ', null, 6059085),
('ramayana-6-59-86', 86, 'Yuddha Kanda, Sarga 59, Verse 86', 'आग्नेयेनाभिसंयुक्तं दृष्ट्वा बाणं निशाचरः।
उत्ससर्ज तदा बाणं दीप्तं सूर्यास्त्रयोजितम्॥', 'āgneyenābhisaṃyuktaṃ dṛṣṭvā bāṇaṃ niśācaraḥ
utsasarja tadā bāṇaṃ dīptaṃ sūryāstrayojitam', null, 6059086),
('ramayana-6-59-87', 87, 'Yuddha Kanda, Sarga 59, Verse 87', 'तावुभावम्बरे बाणावन्योन्यमभिजघ्नतुः।
तेजसा संप्रदीप्ताग्रौ क्रुद्धाविव भुजं गमौ॥', 'tāv ubhāv ambare bāṇāv anyonyam abhijaghnatuḥ
tejasā saṃpradīptāgrau kruddhāv iva bhujaṃ gamau', null, 6059087),
('ramayana-6-59-88', 88, 'Yuddha Kanda, Sarga 59, Verse 88', 'तावन्योन्यं विनिर्दह्य पेततुर्धरणीतले।
निरर्चिषौ भस्मकृतौ न भ्राजेते शरोत्तमौ॥', 'tāv anyonyaṃ vinirdahya petatur dharaṇītale
nirarciṣau bhasmakṛtau na bhrājete śarottamau', null, 6059088),
('ramayana-6-59-89', 89, 'Yuddha Kanda, Sarga 59, Verse 89', 'ततोऽतिकायः संक्रुद्धस्त्वस्त्रमैषीकमुत्सृजत्।
तत्प्रचिच्छेद सौमित्रिरस्त्रमैन्द्रेण वीर्यवान्॥', 'tato ''tikāyaḥ saṃkruddhas tv astram aiṣīkam utsṛjat
tat praciccheda saumitrir astram aindreṇa vīryavān', null, 6059089),
('ramayana-6-59-90', 90, 'Yuddha Kanda, Sarga 59, Verse 90', 'ऐषीकं निहतं दृष्ट्वा कुमारो रावणात्मजः।
याम्येनास्त्रेण संक्रुद्धो योजयामास सायकम्॥', 'aiṣīkaṃ nihataṃ dṛṣṭvā kumāro rāvaṇātmajaḥ
yāmyenāstreṇa saṃkruddho yojayām āsa sāyakam', null, 6059090),
('ramayana-6-59-91', 91, 'Yuddha Kanda, Sarga 59, Verse 91', 'ततस्तदस्त्रं चिक्षेप लक्ष्मणाय निशाचरः।
वायव्येन तदस्त्रं तु निजघान स लक्ष्मणः॥', 'tatas tad astraṃ cikṣepa lakṣmaṇāya niśācaraḥ
vāyavyena tad astraṃ tu nijaghāna sa lakṣmaṇaḥ', null, 6059091),
('ramayana-6-59-92', 92, 'Yuddha Kanda, Sarga 59, Verse 92', 'अथैनं शरधाराभिर्धाराभिरिव तोयदः।
अभ्यवर्षत संक्रुद्धो लक्ष्मणो रावणात्मजम्॥', 'athainaṃ śaradhārābhir dhārābhir iva toyadaḥ
abhyavarṣata saṃkruddho lakṣmaṇo rāvaṇātmajam', null, 6059092),
('ramayana-6-59-93', 93, 'Yuddha Kanda, Sarga 59, Verse 93', 'तेऽतिकायं समासाद्य कवचे वज्रभूषिते।
भग्नाग्रशल्याः सहसा पेतुर्बाणा महीतले॥', 'te ''tikāyaṃ samāsādya kavace vajrabhūṣite
bhagnāgraśalyāḥ sahasā petur bāṇā mahītale', null, 6059093),
('ramayana-6-59-94', 94, 'Yuddha Kanda, Sarga 59, Verse 94', 'तान्मोघानभिसंप्रेक्ष्य लक्ष्मणः परवीरहा।
अभ्यवर्षत बाणानां सहस्रेण महायशाः॥', 'tān moghān abhisaṃprekṣya lakṣmaṇaḥ paravīrahā
abhyavarṣata bāṇānāṃ sahasreṇa mahāyaśāḥ', null, 6059094),
('ramayana-6-59-95', 95, 'Yuddha Kanda, Sarga 59, Verse 95', 'स वर्ष्यमाणो बाणौघैरतिकायो महाबलः।
अवध्यकवचः संख्ये राक्षसो नैव विव्यथे॥', 'sa varṣyamāṇo bāṇaughair atikāyo mahābalaḥ
avadhyakavacaḥ saṃkhye rākṣaso naiva vivyathe', null, 6059095),
('ramayana-6-59-96', 96, 'Yuddha Kanda, Sarga 59, Verse 96', 'न शशाक रुजं कर्तुं युधि तस्य नरोत्तमः।
अथैनमभ्युपागम्य वायुर्वाक्यमुवाच ह॥', 'na śaśāka rujaṃ kartuṃ yudhi tasya narottamaḥ
athainam abhyupāgamya vāyur vākyam uvāca ha', null, 6059096),
('ramayana-6-59-97', 97, 'Yuddha Kanda, Sarga 59, Verse 97', 'ब्रह्मदत्तवरो ह्येष अवध्य कवचावृतः।
ब्राह्मेणास्त्रेण भिन्ध्येनमेष वध्यो हि नान्यथा॥', 'brahmadattavaro hy eṣa avadhya kavacāvṛtaḥ
brāhmeṇāstreṇa bhindhy enam eṣa vadhyo hi nānyathā', null, 6059097),
('ramayana-6-59-98', 98, 'Yuddha Kanda, Sarga 59, Verse 98', 'ततः स वायोर्वचनं निशम्य सौमित्रिरिन्द्रप्रतिमानवीर्यः।
समाददे बाणममोघवेगं तद्ब्राह्ममस्त्रं सहसा नियोज्य॥', 'tataḥ sa vāyor vacanaṃ niśamya saumitrir indrapratimānavīryaḥ
samādade bāṇam amoghavegaṃ tad brāhmam astraṃ sahasā niyojya', null, 6059098),
('ramayana-6-59-99', 99, 'Yuddha Kanda, Sarga 59, Verse 99', 'तस्मिन्वरास्त्रे तु नियुज्यमाने सौमित्रिणा बाणवरे शिताग्रे।
दिशः सचन्द्रार्कमहाग्रहाश्च नभश्च तत्रास ररास चोर्वी॥', 'tasmin varāstre tu niyujyamāne saumitriṇā bāṇavare śitāgre
diśaḥ sacandrārkamahāgrahāś ca nabhaś ca tatrāsa rarāsa corvī', null, 6059099),
('ramayana-6-59-100', 100, 'Yuddha Kanda, Sarga 59, Verse 100', 'तं ब्रह्मणोऽस्त्रेण नियुज्य चापे शरं सुपुङ्खं यमदूतकल्पम्।
सौमित्रिरिन्द्रारिसुतस्य तस्य ससर्ज बाणं युधि वज्रकल्पम्॥', 'taṃ brahmaṇo ''streṇa niyujya cāpe śaraṃ supuṅkhaṃ yamadūtakalpam
saumitrir indrārisutasya tasya sasarja bāṇaṃ yudhi vajrakalpam', null, 6059100),
('ramayana-6-59-101', 101, 'Yuddha Kanda, Sarga 59, Verse 101', 'तं लक्ष्मणोत्सृष्टममोघवेगं समापतन्तं ज्वलनप्रकाशम्।
सुवर्णवज्रोत्तमचित्रपुङ्खं तदातिकायः समरे ददर्श॥', 'taṃ lakṣmaṇotsṛṣṭam amoghavegaṃ samāpatantaṃ jvalanaprakāśam
suvarṇavajrottamacitrapuṅkhaṃ tadātikāyaḥ samare dadarśa', null, 6059101),
('ramayana-6-59-102', 102, 'Yuddha Kanda, Sarga 59, Verse 102', 'तं प्रेक्षमाणः सहसातिकायो जघान बाणैर्निशितैरनेकैः।
स सायकस्तस्य सुपर्णवेगस्तदातिवेगेन जगाम पार्श्वम्॥', 'taṃ prekṣamāṇaḥ sahasātikāyo jaghāna bāṇair niśitair anekaiḥ
sa sāyakas tasya suparṇavegas tadātivegena jagāma pārśvam', null, 6059102),
('ramayana-6-59-103', 103, 'Yuddha Kanda, Sarga 59, Verse 103', 'तमागतं प्रेक्ष्य तदातिकायो बाणं प्रदीप्तान्तककालकल्पम्।
जघान शक्त्यृष्टिगदाकुठारैः शूलैर्हलैश्चाप्यविपन्नचेष्टः॥', 'tam āgataṃ prekṣya tadātikāyo bāṇaṃ pradīptāntakakālakalpam
jaghāna śaktyṛṣṭigadākuṭhāraiḥ śūlair halaiś cāpy avipannaceṣṭaḥ', null, 6059103),
('ramayana-6-59-104', 104, 'Yuddha Kanda, Sarga 59, Verse 104', 'तान्यायुधान्यद्भुतविग्रहाणि मोघानि कृत्वा स शरोऽग्निदीप्तः।
प्रसह्य तस्यैव किरीटजुष्टं तदातिकायस्य शिरो जहार॥', 'tāny āyudhāny adbhutavigrahāṇi moghāni kṛtvā sa śaro ''gnidīptaḥ
prasahya tasyaiva kirīṭajuṣṭaṃ tadātikāyasya śiro jahāra', null, 6059104),
('ramayana-6-59-105', 105, 'Yuddha Kanda, Sarga 59, Verse 105', 'तच्छिरः सशिरस्त्राणं लक्ष्मणेषुप्रपीडितम्।
पपात सहसा भूमौ शृङ्गं हिमवतो यथा॥', 'tac chiraḥ saśiras trāṇaṃ lakṣmaṇeṣuprapīḍitam
papāta sahasā bhūmau śṛṅgaṃ himavato yathā', null, 6059105),
('ramayana-6-59-106', 106, 'Yuddha Kanda, Sarga 59, Verse 106', 'प्रहर्षयुक्ता बहवस्तु वानरा प्रबुद्धपद्मप्रतिमाननास्तदा।
अपूजयंल्लक्ष्मणमिष्टभागिनं हते रिपौ भीमबले दुरासदे॥', 'praharṣayuktā bahavas tu vānarā prabuddhapadmapratimānanās tadā
apūjayaṃl lakṣmaṇam iṣṭabhāginaṃ hate ripau bhīmabale durāsade', null, 6059106)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 60 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-60-1', 1, 'Yuddha Kanda, Sarga 60, Verse 1', 'ततो हतान्राक्षसपुंगवांस्तान्देवान्तकादित्रिशिरोऽतिकायान्।
रक्षोगणास्तत्र हतावशिष्टास्ते रावणाय त्वरितं शशंसुः॥', 'tato hatān rākṣasapuṃgavāṃs tān devāntakāditriśiro ''tikāyān
rakṣogaṇās tatra hatāvaśiṣṭās te rāvaṇāya tvaritaṃ śaśaṃsuḥ', null, 6060001),
('ramayana-6-60-2', 2, 'Yuddha Kanda, Sarga 60, Verse 2', 'ततो हतांस्तान्सहसा निशम्य राजा मुमोहाश्रुपरिप्लुताक्षः।
पुत्रक्षयं भ्रातृवधं च घोरं विचिन्त्य राजा विपुलं प्रदध्यौ॥', 'tato hatāṃs tān sahasā niśamya rājā mumohāśrupariplutākṣaḥ
putrakṣayaṃ bhrātṛvadhaṃ ca ghoraṃ vicintya rājā vipulaṃ pradadhyau', null, 6060002),
('ramayana-6-60-3', 3, 'Yuddha Kanda, Sarga 60, Verse 3', 'ततस्तु राजानमुदीक्ष्य दीनं शोकार्णवे संपरिपुप्लुवानम्।
अथर्षभो राक्षसराजसूनुरथेन्द्रजिद्वाक्यमिदं बभाषे॥', 'tatas tu rājānam udīkṣya dīnaṃ śokārṇave saṃparipupluvānam
atharṣabho rākṣasarājasūnur athendrajid vākyam idaṃ babhāṣe', null, 6060003),
('ramayana-6-60-4', 4, 'Yuddha Kanda, Sarga 60, Verse 4', 'न तात मोहं प्रतिगन्तुमर्हसि यत्रेन्द्रजिज्जीवति राक्षसेन्द्र।
नेन्द्रारिबाणाभिहतो हि कश्चित्प्राणान्समर्थः समरेऽभिधर्तुम्॥', 'na tāta mohaṃ pratigantum arhasi yatrendrajij jīvati rākṣasendra
nendrāribāṇābhihato hi kaś cit prāṇān samarthaḥ samare ''bhidhartum', null, 6060004),
('ramayana-6-60-5', 5, 'Yuddha Kanda, Sarga 60, Verse 5', 'पश्याद्य रामं सहलक्ष्मणेन मद्बाणनिर्भिन्नविकीर्णदेहम्।
गतायुषं भूमितले शयानं शरैः शितैराचितसर्वगात्रम्॥', 'paśyādya rāmaṃ sahalakṣmaṇena madbāṇanirbhinnavikīrṇadeham
gatāyuṣaṃ bhūmitale śayānaṃ śaraiḥ śitair ācitasarvagātram', null, 6060005),
('ramayana-6-60-6', 6, 'Yuddha Kanda, Sarga 60, Verse 6', 'इमां प्रतिज्ञां शृणु शक्रशत्रोः सुनिश्चितां पौरुषदैवयुक्ताम्।
अद्यैव रामं सहलक्ष्मणेन संतापयिष्यामि शरैरमोघैः॥', 'imāṃ pratijñāṃ śṛṇu śakraśatroḥ suniścitāṃ pauruṣadaivayuktām
adyaiva rāmaṃ sahalakṣmaṇena saṃtāpayiṣyāmi śarair amoghaiḥ', null, 6060006),
('ramayana-6-60-7', 7, 'Yuddha Kanda, Sarga 60, Verse 7', 'अद्येन्द्रवैवस्वतविष्णुमित्र साध्याश्विवैश्वानरचन्द्रसूर्याः।
द्रक्ष्यन्ति मे विक्रममप्रमेयं विष्णोरिवोग्रं बलियज्ञवाटे॥', 'adyendravaivasvataviṣṇumitra sādhyāśvivaiśvānaracandrasūryāḥ
drakṣyanti me vikramam aprameyaṃ viṣṇor ivograṃ baliyajñavāṭe', null, 6060007),
('ramayana-6-60-8', 8, 'Yuddha Kanda, Sarga 60, Verse 8', 'स एवमुक्त्वा त्रिदशेन्द्रशत्रुरापृच्छ्य राजानमदीनसत्त्वः।
समारुरोहानिलतुल्यवेगं रथं खरश्रेष्ठसमाधियुक्तम्॥', 'sa evam uktvā tridaśendraśatrur āpṛcchya rājānam adīnasattvaḥ
samārurohānilatulyavegaṃ rathaṃ kharaśreṣṭhasamādhiyuktam', null, 6060008),
('ramayana-6-60-9', 9, 'Yuddha Kanda, Sarga 60, Verse 9', 'समास्थाय महातेजा रथं हरिरथोपमम्।
जगाम सहसा तत्र यत्र युद्धमरिंदम॥', 'samāsthāya mahātejā rathaṃ harirathopamam
jagāma sahasā tatra yatra yuddham ariṃdama', null, 6060009),
('ramayana-6-60-10', 10, 'Yuddha Kanda, Sarga 60, Verse 10', 'तं प्रस्थितं महात्मानमनुजग्मुर्महाबलाः।
संहर्षमाणा बहवो धनुःप्रवरपाणयः॥', 'taṃ prasthitaṃ mahātmānam anujagmur mahābalāḥ
saṃharṣamāṇā bahavo dhanuḥpravarapāṇayaḥ', null, 6060010),
('ramayana-6-60-11', 11, 'Yuddha Kanda, Sarga 60, Verse 11', 'गजस्कन्धगताः के चित्के चित्परमवाजिभिः।
प्रासमुद्गरनिस्त्रिंश परश्वधगदाधराः॥', 'gajaskandhagatāḥ ke cit ke cit paramavājibhiḥ
prāsamudgaranistriṃśa paraśvadhagadādharāḥ', null, 6060011),
('ramayana-6-60-12', 12, 'Yuddha Kanda, Sarga 60, Verse 12', 'स शङ्खनिनदैर्भीमैर्भेरीणां च महास्वनैः।
जगाम त्रिदशेन्द्रारिः स्तूयमानो निशाचरैः॥', 'sa śaṅkhaninadair bhīmair bherīṇāṃ ca mahāsvanaiḥ
jagāma tridaśendrāriḥ stūyamāno niśācaraiḥ', null, 6060012),
('ramayana-6-60-13', 13, 'Yuddha Kanda, Sarga 60, Verse 13', 'स शङ्खशशिवर्णेन छत्रेण रिपुसादनः।
रराज परिपूर्णेन नभश्चन्द्रमसा यथा॥', 'sa śaṅkhaśaśivarṇena chatreṇa ripusādanaḥ
rarāja paripūrṇena nabhaś candramasā yathā', null, 6060013),
('ramayana-6-60-14', 14, 'Yuddha Kanda, Sarga 60, Verse 14', 'अवीज्यत ततो वीरो हैमैर्हेमविभूषितैः।
चारुचामरमुख्यैश्च मुख्यः सर्वधनुष्मताम्॥', 'avījyata tato vīro haimair hemavibhūṣitaiḥ
cārucāmaramukhyaiś ca mukhyaḥ sarvadhanuṣmatām', null, 6060014),
('ramayana-6-60-15', 15, 'Yuddha Kanda, Sarga 60, Verse 15', 'ततस्त्विन्द्रजिता लङ्का सूर्यप्रतिमतेजसा।
रराजाप्रतिवीर्येण द्यौरिवार्केण भास्वता॥', 'tatas tv indrajitā laṅkā sūryapratimatejasā
rarājāprativīryeṇa dyaur ivārkeṇa bhāsvatā', null, 6060015),
('ramayana-6-60-16', 16, 'Yuddha Kanda, Sarga 60, Verse 16', 'स तु दृष्ट्वा विनिर्यान्तं बलेन महता वृतम्।
राक्षसाधिपतिः श्रीमान्रावणः पुत्रमब्रवीत्॥', 'sa tu dṛṣṭvā viniryāntaṃ balena mahatā vṛtam
rākṣasādhipatiḥ śrīmān rāvaṇaḥ putram abravīt', null, 6060016),
('ramayana-6-60-17', 17, 'Yuddha Kanda, Sarga 60, Verse 17', 'त्वमप्रतिरथः पुत्र जितस्ते युधि वासवः।
किं पुनर्मानुषं धृष्यं न वधिष्यसि राघवम्॥', 'tvam apratirathaḥ putra jitas te yudhi vāsavaḥ
kiṃ punar mānuṣaṃ dhṛṣyaṃ na vadhiṣyasi rāghavam', null, 6060017),
('ramayana-6-60-18', 18, 'Yuddha Kanda, Sarga 60, Verse 18', 'तथोक्तो राक्षसेन्द्रेण प्रतिगृह्य महाशिषः।
रथेनाश्वयुजा वीरः शीघ्रं गत्वा निकुम्भिलाम्॥', 'tathokto rākṣasendreṇa pratigṛhya mahāśiṣaḥ
rathenāśvayujā vīraḥ śīghraṃ gatvā nikumbhilām', null, 6060018),
('ramayana-6-60-19', 19, 'Yuddha Kanda, Sarga 60, Verse 19', 'स संप्राप्य महातेजा युद्धभूमिमरिंदमः।
स्थापयामास रक्षांसि रथं प्रति समन्ततः॥', 'sa saṃprāpya mahātejā yuddhabhūmim ariṃdamaḥ
sthāpayām āsa rakṣāṃsi rathaṃ prati samantataḥ', null, 6060019),
('ramayana-6-60-20', 20, 'Yuddha Kanda, Sarga 60, Verse 20', 'ततस्तु हुतभोक्तारं हुतभुक्सदृशप्रभः।
जुहुवे राक्षसश्रेष्ठो मन्त्रवद्विधिवत्तदा॥', 'tatas tu hutabhoktāraṃ hutabhuk sadṛśaprabhaḥ
juhuve rākṣasaśreṣṭho mantravad vidhivat tadā', null, 6060020),
('ramayana-6-60-21', 21, 'Yuddha Kanda, Sarga 60, Verse 21', 'स हविर्जालसंस्कारैर्माल्यगन्धपुरस्कृतैः।
जुहुवे पावकं तत्र राक्षसेन्द्रः प्रतापवान्॥', 'sa havirjālasaṃskārair mālyagandhapuraskṛtaiḥ
juhuve pāvakaṃ tatra rākṣasendraḥ pratāpavān', null, 6060021),
('ramayana-6-60-22', 22, 'Yuddha Kanda, Sarga 60, Verse 22', 'शस्त्राणि शरपत्राणि समिधोऽथ विभीतकः।
लोहितानि च वासांसि स्रुवं कार्ष्णायसं तथा॥', 'śastrāṇi śarapatrāṇi samidho ''tha vibhītakaḥ
lohitāni ca vāsāṃsi sruvaṃ kārṣṇāyasaṃ tathā', null, 6060022),
('ramayana-6-60-23', 23, 'Yuddha Kanda, Sarga 60, Verse 23', 'स तत्राग्निं समास्तीर्य शरपत्रैः सतोमरैः।
छागस्य सर्वकृष्णस्य गलं जग्राह जीवतः॥', 'sa tatrāgniṃ samāstīrya śarapatraiḥ satomaraiḥ
chāgasya sarvakṛṣṇasya galaṃ jagrāha jīvataḥ', null, 6060023),
('ramayana-6-60-24', 24, 'Yuddha Kanda, Sarga 60, Verse 24', 'सकृदेव समिद्धस्य विधूमस्य महार्चिषः।
बभूवुस्तानि लिङ्गानि विजयं यान्यदर्शयन्॥', 'sakṛd eva samiddhasya vidhūmasya mahārciṣaḥ
babhūvus tāni liṅgāni vijayaṃ yāny adarśayan', null, 6060024),
('ramayana-6-60-25', 25, 'Yuddha Kanda, Sarga 60, Verse 25', 'प्रदक्षिणावर्तशिखस्तप्तकाञ्चनसंनिभः।
हविस्तत्प्रतिजग्राह पावकः स्वयमुत्थितः॥', 'pradakṣiṇāvartaśikhas taptakāñcanasaṃnibhaḥ
havis tat pratijagrāha pāvakaḥ svayam utthitaḥ', null, 6060025),
('ramayana-6-60-26', 26, 'Yuddha Kanda, Sarga 60, Verse 26', 'सोऽस्त्रमाहारयामास ब्राह्ममस्त्रविदां वरः।
धनुश्चात्मरथं चैव सर्वं तत्राभ्यमन्त्रयत्॥', 'so ''stram āhārayām āsa brāhmam astravidāṃ varaḥ
dhanuś cātmarathaṃ caiva sarvaṃ tatrābhyamantrayat', null, 6060026),
('ramayana-6-60-27', 27, 'Yuddha Kanda, Sarga 60, Verse 27', 'तस्मिन्नाहूयमानेऽस्त्रे हूयमाने च पावके।
सार्कग्रहेन्दु नक्षत्रं वितत्रास नभस्तलम्॥', 'tasminn āhūyamāne ''stre hūyamāne ca pāvake
sārkagrahendu nakṣatraṃ vitatrāsa nabhastalam', null, 6060027),
('ramayana-6-60-28', 28, 'Yuddha Kanda, Sarga 60, Verse 28', 'स पावकं पावकदीप्ततेजा हुत्वा महेन्द्रप्रतिमप्रभावः।
सचापबाणासिरथाश्वसूतः खेऽन्तर्दध आत्मानमचिन्त्यरूपः॥', 'sa pāvakaṃ pāvakadīptatejā hutvā mahendrapratimaprabhāvaḥ
sacāpabāṇāsirathāśvasūtaḥ khe ''ntardadha ātmānam acintyarūpaḥ', null, 6060028),
('ramayana-6-60-29', 29, 'Yuddha Kanda, Sarga 60, Verse 29', 'स सैन्यमुत्सृज्य समेत्य तूर्णं महारणे वानरवाहिनीषु।
अदृश्यमानः शरजालमुग्रं ववर्ष नीलाम्बुधरो यथाम्बु॥', 'sa sainyam utsṛjya sametya tūrṇaṃ mahāraṇe vānaravāhinīṣu
adṛśyamānaḥ śarajālam ugraṃ vavarṣa nīlāmbudharo yathāmbu', null, 6060029),
('ramayana-6-60-30', 30, 'Yuddha Kanda, Sarga 60, Verse 30', 'ते शक्रजिद्बाणविशीर्णदेहा मायाहता विस्वरमुन्नदन्तः।
रणे निपेतुर्हरयोऽद्रिकल्पा यथेन्द्रवज्राभिहता नगेन्द्राः॥', 'te śakrajidbāṇaviśīrṇadehā māyāhatā visvaram unnadantaḥ
raṇe nipetur harayo ''drikalpā yathendravajrābhihatā nagendrāḥ', null, 6060030),
('ramayana-6-60-31', 31, 'Yuddha Kanda, Sarga 60, Verse 31', 'ते केवलं संददृशुः शिताग्रान्बाणान्रणे वानरवाहिनीषु।
माया निगूढं च सुरेन्द्रशत्रुं न चात्र तं राक्षसमभ्यपश्यन्॥', 'te kevalaṃ saṃdadṛśuḥ śitāgrān bāṇān raṇe vānaravāhinīṣu
māyā nigūḍhaṃ ca surendraśatruṃ na cātra taṃ rākṣasam abhyapaśyan', null, 6060031),
('ramayana-6-60-32', 32, 'Yuddha Kanda, Sarga 60, Verse 32', 'ततः स रक्षोऽधिपतिर्महात्मा सर्वा दिशो बाणगणैः शिताग्रैः।
प्रच्छादयामास रविप्रकाशैर्विषादयामास च वानरेन्द्रान्॥', 'tataḥ sa rakṣo''dhipatir mahātmā sarvā diśo bāṇagaṇaiḥ śitāgraiḥ
pracchādayām āsa raviprakāśair viṣādayām āsa ca vānarendrān', null, 6060032),
('ramayana-6-60-33', 33, 'Yuddha Kanda, Sarga 60, Verse 33', 'स शूलनिस्त्रिंश परश्वधानि व्याविध्य दीप्तानलसंनिभानि।
सविस्फुलिङ्गोज्ज्वलपावकानि ववर्ष तीव्रं प्लवगेन्द्रसैन्ये॥', 'sa śūlanistriṃśa paraśvadhāni vyāvidhya dīptānalasaṃnibhāni
savisphuliṅgojjvalapāvakāni vavarṣa tīvraṃ plavagendrasainye', null, 6060033),
('ramayana-6-60-34', 34, 'Yuddha Kanda, Sarga 60, Verse 34', 'ततो ज्वलनसंकाशैः शितैर्वानरयूथपाः।
ताडिताः शक्रजिद्बाणैः प्रफुल्ला इव किंशुकाः॥', 'tato jvalanasaṃkāśaiḥ śitair vānarayūthapāḥ
tāḍitāḥ śakrajidbāṇaiḥ praphullā iva kiṃśukāḥ', null, 6060034),
('ramayana-6-60-35', 35, 'Yuddha Kanda, Sarga 60, Verse 35', 'अन्योन्यमभिसर्पन्तो निनदन्तश्च विस्वरम्।
राक्षसेन्द्रास्त्रनिर्भिन्ना निपेतुर्वानरर्षभाः॥', 'anyonyam abhisarpanto ninadantaś ca visvaram
rākṣasendrāstranirbhinnā nipetur vānararṣabhāḥ', null, 6060035),
('ramayana-6-60-36', 36, 'Yuddha Kanda, Sarga 60, Verse 36', 'उदीक्षमाणा गगनं के चिन्नेत्रेषु ताडिताः।
शरैर्विविशुरन्योन्यं पेतुश्च जगतीतले॥', 'udīkṣamāṇā gaganaṃ ke cin netreṣu tāḍitāḥ
śarair viviśur anyonyaṃ petuś ca jagatītale', null, 6060036),
('ramayana-6-60-37', 37, 'Yuddha Kanda, Sarga 60, Verse 37', 'हनूमन्तं च सुग्रीवमङ्गदं गन्धमादनम्।
जाम्बवन्तं सुषेणं च वेगदर्शिनमेव च॥', 'hanūmantaṃ ca sugrīvam aṅgadaṃ gandhamādanam
jāmbavantaṃ suṣeṇaṃ ca vegadarśinam eva ca', null, 6060037),
('ramayana-6-60-38', 38, 'Yuddha Kanda, Sarga 60, Verse 38', 'मैन्दं च द्विविदं नीलं गवाक्षं गजगोमुखौ।
केसरिं हरिलोमानं विद्युद्दंष्ट्रं च वानरम्॥', 'maindaṃ ca dvividaṃ nīlaṃ gavākṣaṃ gajagomukhau
kesariṃ harilomānaṃ vidyuddaṃṣṭraṃ ca vānaram', null, 6060038),
('ramayana-6-60-39', 39, 'Yuddha Kanda, Sarga 60, Verse 39', 'सूर्याननं ज्योतिमुखं तथा दधिमुखं हरिम्।
पावकाक्षं नलं चैव कुमुदं चैव वानरम्॥', 'sūryānanaṃ jyotimukhaṃ tathā dadhimukhaṃ harim
pāvakākṣaṃ nalaṃ caiva kumudaṃ caiva vānaram', null, 6060039),
('ramayana-6-60-40', 40, 'Yuddha Kanda, Sarga 60, Verse 40', 'प्रासैः शूलैः शितैर्बाणैरिन्द्रजिन्मन्त्रसंहितैः।
विव्याध हरिशार्दूलान्सर्वांस्तान्राक्षसोत्तमः॥', 'prāsaiḥ śūlaiḥ śitair bāṇair indrajinmantrasaṃhitaiḥ
vivyādha hariśārdūlān sarvāṃs tān rākṣasottamaḥ', null, 6060040),
('ramayana-6-60-41', 41, 'Yuddha Kanda, Sarga 60, Verse 41', 'स वै गदाभिर्हरियूथमुख्यान्निर्भिद्य बाणैस्तपनीयपुङ्खैः।
ववर्ष रामं शरवृष्टिजालैः सलक्ष्मणं भास्कररश्मिकल्पैः॥', 'sa vai gadābhir hariyūthamukhyān nirbhidya bāṇais tapanīyapuṅkhaiḥ
vavarṣa rāmaṃ śaravṛṣṭijālaiḥ salakṣmaṇaṃ bhāskararaśmikalpaiḥ', null, 6060041),
('ramayana-6-60-42', 42, 'Yuddha Kanda, Sarga 60, Verse 42', 'स बाणवर्षैरभिवर्ष्यमाणो धारानिपातानिव तान्विचिन्त्य।
समीक्षमाणः परमाद्भुतश्री रामस्तदा लक्ष्मणमित्युवाच॥', 'sa bāṇavarṣair abhivarṣyamāṇo dhārānipātān iva tān vicintya
samīkṣamāṇaḥ paramādbhutaśrī rāmas tadā lakṣmaṇam ity uvāca', null, 6060042),
('ramayana-6-60-43', 43, 'Yuddha Kanda, Sarga 60, Verse 43', 'असौ पुनर्लक्ष्मण राक्षसेन्द्रो ब्रह्मास्त्रमाश्रित्य सुरेन्द्रशत्रुः।
निपातयित्वा हरिसैन्यमुग्रमस्माञ्शरैरर्दयति प्रसक्तम्॥', 'asau punar lakṣmaṇa rākṣasendro brahmāstram āśritya surendraśatruḥ
nipātayitvā harisainyam ugram asmāñ śarair ardayati prasaktam', null, 6060043),
('ramayana-6-60-44', 44, 'Yuddha Kanda, Sarga 60, Verse 44', 'स्वयम्भुवा दत्तवरो महात्मा खमास्थितोऽन्तर्हितभीमकायः।
कथं नु शक्यो युधि नष्टदेहो निहन्तुमद्येन्द्रजिदुद्यतास्त्रः॥', 'svayambhuvā dattavaro mahātmā kham āsthito ''ntarhitabhīmakāyaḥ
kathaṃ nu śakyo yudhi naṣṭadeho nihantum adyendrajid udyatāstraḥ', null, 6060044),
('ramayana-6-60-45', 45, 'Yuddha Kanda, Sarga 60, Verse 45', 'मन्ये स्वयम्भूर्भगवानचिन्त्यो यस्यैतदस्त्रं प्रभवश्च योऽस्य।
बाणावपातांस्त्वमिहाद्य धीमन्मया सहाव्यग्रमनाः सहस्व॥', 'manye svayambhūr bhagavān acintyo yasyaitad astraṃ prabhavaś ca yo ''sya
bāṇāvapātāṃs tvam ihādya dhīman mayā sahāvyagramanāḥ sahasva', null, 6060045),
('ramayana-6-60-46', 46, 'Yuddha Kanda, Sarga 60, Verse 46', 'प्रच्छादयत्येष हि राक्षसेन्द्रः सर्वा दिशः सायकवृष्टिजालैः।
एतच्च सर्वं पतिताग्र्यवीरं न भ्राजते वानरराजसैन्यम्॥', 'pracchādayaty eṣa hi rākṣasendraḥ sarvā diśaḥ sāyakavṛṣṭijālaiḥ
etac ca sarvaṃ patitāgryavīraṃ na bhrājate vānararājasainyam', null, 6060046),
('ramayana-6-60-47', 47, 'Yuddha Kanda, Sarga 60, Verse 47', 'आवां तु दृष्ट्वा पतितौ विसंज्ञौ निवृत्तयुद्धौ हतरोषहर्षौ।
ध्रुवं प्रवेक्ष्यत्यमरारिवासं असौ समादाय रणाग्रलक्ष्मीम्॥', 'āvāṃ tu dṛṣṭvā patitau visaṃjñau nivṛttayuddhau hataroṣaharṣau
dhruvaṃ pravekṣyaty amarārivāsaṃ asau samādāya raṇāgralakṣmīm', null, 6060047),
('ramayana-6-60-48', 48, 'Yuddha Kanda, Sarga 60, Verse 48', 'ततस्तु ताविन्द्रजिदस्त्रजालैर्बभूवतुस्तत्र तदा विशस्तौ।
स चापि तौ तत्र विषादयित्वा ननाद हर्षाद्युधि राक्षसेन्द्रः॥', 'tatas tu tāv indrajid astrajālair babhūvatus tatra tadā viśastau
sa cāpi tau tatra viṣādayitvā nanāda harṣād yudhi rākṣasendraḥ', null, 6060048),
('ramayana-6-60-49', 49, 'Yuddha Kanda, Sarga 60, Verse 49', 'स तत्तदा वानरराजसैन्यं रामं च संख्ये सहलक्ष्मणेन।
विषादयित्वा सहसा विवेश पुरीं दशग्रीवभुजाभिगुप्ताम्॥', 'sa tat tadā vānararājasainyaṃ rāmaṃ ca saṃkhye sahalakṣmaṇena
viṣādayitvā sahasā viveśa purīṃ daśagrīvabhujābhiguptām', null, 6060049)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 61 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-61-1', 1, 'Yuddha Kanda, Sarga 61, Verse 1', 'तयोस्तदा सादितयो रणाग्रे मुमोह सैन्यं हरियूथपानाम्।
सुग्रीवनीलाङ्गदजाम्बवन्तो न चापि किं चित्प्रतिपेदिरे ते॥', 'tayos tadā sāditayo raṇāgre mumoha sainyaṃ hariyūthapānām
sugrīvanīlāṅgadajāmbavanto na cāpi kiṃ cit pratipedire te', null, 6061001),
('ramayana-6-61-2', 2, 'Yuddha Kanda, Sarga 61, Verse 2', 'ततो विषण्णं समवेक्ष्य सैन्यं विभीषणो बुद्धिमतां वरिष्ठः।
उवाच शाखामृगराजवीरानाश्वासयन्नप्रतिमैर्वचोभिः॥', 'tato viṣaṇṇaṃ samavekṣya sainyaṃ vibhīṣaṇo buddhimatāṃ variṣṭhaḥ
uvāca śākhāmṛgarājavīrān āśvāsayann apratimair vacobhiḥ', null, 6061002),
('ramayana-6-61-3', 3, 'Yuddha Kanda, Sarga 61, Verse 3', 'मा भैष्ट नास्त्यत्र विषादकालो यदार्यपुत्राववशौ विषण्णौ।
स्वयम्भुवो वाक्यमथोद्वहन्तौ यत्सादिताविन्द्रजिदस्त्रजालैः॥', 'mā bhaiṣṭa nāsty atra viṣādakālo yad āryaputrāv avaśau viṣaṇṇau
svayambhuvo vākyam athodvahantau yat sāditāv indrajidastrajālaiḥ', null, 6061003),
('ramayana-6-61-4', 4, 'Yuddha Kanda, Sarga 61, Verse 4', 'तस्मै तु दत्तं परमास्त्रमेतत्स्वयम्भुवा ब्राह्मममोघवेगम्।
तन्मानयन्तौ यदि राजपुत्रौ निपातितौ कोऽत्र विषादकालः॥', 'tasmai tu dattaṃ paramāstram etat svayambhuvā brāhmam amoghavegam
tan mānayantau yadi rājaputrau nipātitau ko ''tra viṣādakālaḥ', null, 6061004),
('ramayana-6-61-5', 5, 'Yuddha Kanda, Sarga 61, Verse 5', 'ब्राह्ममस्त्रं तदा धीमान्मानयित्वा तु मारुतिः।
विभीषणवचः श्रुत्वा हनूमांस्तमथाब्रवीत्॥', 'brāhmam astraṃ tadā dhīmān mānayitvā tu mārutiḥ
vibhīṣaṇavacaḥ śrutvā hanūmāṃs tam athābravīt', null, 6061005),
('ramayana-6-61-6', 6, 'Yuddha Kanda, Sarga 61, Verse 6', 'एतस्मिन्निहते सैन्ये वानराणां तरस्विनाम्।
यो यो धारयते प्राणांस्तं तमाश्वासयावहे॥', 'etasmin nihate sainye vānarāṇāṃ tarasvinām
yo yo dhārayate prāṇāṃs taṃ tam āśvāsayāvahe', null, 6061006),
('ramayana-6-61-7', 7, 'Yuddha Kanda, Sarga 61, Verse 7', 'तावुभौ युगपद्वीरौ हनूमद्राक्षसोत्तमौ।
उल्काहस्तौ तदा रात्रौ रणशीर्षे विचेरतुः॥', 'tāv ubhau yugapad vīrau hanūmad rākṣasottamau
ulkāhastau tadā rātrau raṇaśīrṣe viceratuḥ', null, 6061007),
('ramayana-6-61-8', 8, 'Yuddha Kanda, Sarga 61, Verse 8', 'छिन्नलाङ्गूलहस्तोरुपादाङ्गुलि शिरो धरैः।
स्रवद्भिः क्षतजं गात्रैः प्रस्रवद्भिः समन्ततः॥', 'chinnalāṅgūlahastorupādāṅguli śiro dharaiḥ
sravadbhiḥ kṣatajaṃ gātraiḥ prasravadbhiḥ samantataḥ', null, 6061008),
('ramayana-6-61-9', 9, 'Yuddha Kanda, Sarga 61, Verse 9', 'पतितैः पर्वताकारैर्वानरैरभिसंकुलाम्।
शस्त्रैश्च पतितैर्दीप्तैर्ददृशाते वसुंधराम्॥', 'patitaiḥ parvatākārair vānarair abhisaṃkulām
śastraiś ca patitair dīptair dadṛśāte vasuṃdharām', null, 6061009),
('ramayana-6-61-10', 10, 'Yuddha Kanda, Sarga 61, Verse 10', 'सुग्रीवमङ्गदं नीलं शरभं गन्धमादनम्।
जाम्बवन्तं सुषेणं च वेगदर्शनमाहुकम्॥', 'sugrīvam aṅgadaṃ nīlaṃ śarabhaṃ gandhamādanam
jāmbavantaṃ suṣeṇaṃ ca vegadarśanam āhukam', null, 6061010),
('ramayana-6-61-11', 11, 'Yuddha Kanda, Sarga 61, Verse 11', 'मैन्दं नलं ज्योतिमुखं द्विविदं पनसं तथा।
विभीषणो हनूमांश्च ददृशाते हतान्रणे॥', 'maindaṃ nalaṃ jyotimukhaṃ dvividaṃ panasaṃ tathā
vibhīṣaṇo hanūmāṃś ca dadṛśāte hatān raṇe', null, 6061011),
('ramayana-6-61-12', 12, 'Yuddha Kanda, Sarga 61, Verse 12', 'सप्तषष्टिर्हताः कोट्यो वानराणां तरस्विनाम्।
अह्नः पञ्चमशेषेण वल्लभेन स्वयम्भुवः॥', 'saptaṣaṣṭir hatāḥ koṭyo vānarāṇāṃ tarasvinām
ahnaḥ pañcamaśeṣeṇa vallabhena svayambhuvaḥ', null, 6061012),
('ramayana-6-61-13', 13, 'Yuddha Kanda, Sarga 61, Verse 13', 'सागरौघनिभं भीमं दृष्ट्वा बाणार्दितं बलम्।
मार्गते जाम्बवन्तं स्म हनूमान्सविभीषणः॥', 'sāgaraughanibhaṃ bhīmaṃ dṛṣṭvā bāṇārditaṃ balam
mārgate jāmbavantaṃ sma hanūmān savibhīṣaṇaḥ', null, 6061013),
('ramayana-6-61-14', 14, 'Yuddha Kanda, Sarga 61, Verse 14', 'स्वभावजरया युक्तं वृद्धं शरशतैश्चितम्।
प्रजापतिसुतं वीरं शाम्यन्तमिव पावकम्॥', 'svabhāvajarayā yuktaṃ vṛddhaṃ śaraśataiś citam
prajāpatisutaṃ vīraṃ śāmyantam iva pāvakam', null, 6061014),
('ramayana-6-61-15', 15, 'Yuddha Kanda, Sarga 61, Verse 15', 'दृष्ट्वा तमुपसंगम्य पौलस्त्यो वाक्यमब्रवीत्।
कच्चिदार्यशरैस्तीर्ष्णैर्न प्राणा ध्वंसितास्तव॥', 'dṛṣṭvā tam upasaṃgamya paulastyo vākyam abravīt
kaccid āryaśarais tīrṣṇair na prāṇā dhvaṃsitās tava', null, 6061015),
('ramayana-6-61-16', 16, 'Yuddha Kanda, Sarga 61, Verse 16', 'विभीषणवचः श्रुत्वा जाम्बवानृक्षपुंगवः।
कृच्छ्रादभ्युद्गिरन्वाक्यमिदं वचनमब्रवीत्॥', 'vibhīṣaṇavacaḥ śrutvā jāmbavān ṛkṣapuṃgavaḥ
kṛcchrād abhyudgiran vākyam idaṃ vacanam abravīt', null, 6061016),
('ramayana-6-61-17', 17, 'Yuddha Kanda, Sarga 61, Verse 17', 'नैरृतेन्द्रमहावीर्यस्वरेण त्वाभिलक्षये।
पीड्यमानः शितैर्बाणैर्न त्वां पश्यामि चक्षुषा॥', 'nairṛtendramahāvīryasvareṇa tvābhilakṣaye
pīḍyamānaḥ śitair bāṇair na tvāṃ paśyāmi cakṣuṣā', null, 6061017),
('ramayana-6-61-18', 18, 'Yuddha Kanda, Sarga 61, Verse 18', 'अञ्जना सुप्रजा येन मातरिश्वा च नैरृत।
हनूमान्वानरश्रेष्ठः प्राणान्धारयते क्व चित्॥', 'añjanā suprajā yena mātariśvā ca nairṛta
hanūmān vānaraśreṣṭhaḥ prāṇān dhārayate kva cit', null, 6061018),
('ramayana-6-61-19', 19, 'Yuddha Kanda, Sarga 61, Verse 19', 'श्रुत्वा जाम्बवतो वाक्यमुवाचेदं विभीषणः।
आर्यपुत्रावतिक्रम्य कस्मात्पृच्छसि मारुतिम्॥', 'śrutvā jāmbavato vākyam uvācedaṃ vibhīṣaṇaḥ
āryaputrāv atikramya kasmāt pṛcchasi mārutim', null, 6061019),
('ramayana-6-61-20', 20, 'Yuddha Kanda, Sarga 61, Verse 20', 'नैव राजनि सुग्रीवे नाङ्गदे नापि राघवे।
आर्य संदर्शितः स्नेहो यथा वायुसुते परः॥', 'naiva rājani sugrīve nāṅgade nāpi rāghave
ārya saṃdarśitaḥ sneho yathā vāyusute paraḥ', null, 6061020),
('ramayana-6-61-21', 21, 'Yuddha Kanda, Sarga 61, Verse 21', 'विभीषणवचः श्रुत्वा जाम्बवान्वाक्यमब्रवीत्।
शृणु नैरृतशार्दूल यस्मात्पृच्छामि मारुतिम्॥', 'vibhīṣaṇavacaḥ śrutvā jāmbavān vākyam abravīt
śṛṇu nairṛtaśārdūla yasmāt pṛcchāmi mārutim', null, 6061021),
('ramayana-6-61-22', 22, 'Yuddha Kanda, Sarga 61, Verse 22', 'तस्मिञ्जीवति वीरे तु हतमप्यहतं बलम्।
हनूमत्युज्झितप्राणे जीवन्तोऽपि वयं हताः॥', 'tasmiñ jīvati vīre tu hatam apy ahataṃ balam
hanūmaty ujjhitaprāṇe jīvanto ''pi vayaṃ hatāḥ', null, 6061022),
('ramayana-6-61-23', 23, 'Yuddha Kanda, Sarga 61, Verse 23', 'ध्रियते मारुतिस्तात मारुतप्रतिमो यदि।
वैश्वानरसमो वीर्ये जीविताशा ततो भवेत्॥', 'dhriyate mārutis tāta mārutapratimo yadi
vaiśvānarasamo vīrye jīvitāśā tato bhavet', null, 6061023),
('ramayana-6-61-24', 24, 'Yuddha Kanda, Sarga 61, Verse 24', 'ततो वृद्धमुपागम्य नियमेनाभ्यवादयत्।
गृह्य जाम्बवतः पादौ हनूमान्मारुतात्मजः॥', 'tato vṛddham upāgamya niyamenābhyavādayat
gṛhya jāmbavataḥ pādau hanūmān mārutātmajaḥ', null, 6061024),
('ramayana-6-61-25', 25, 'Yuddha Kanda, Sarga 61, Verse 25', 'श्रुत्वा हनुमतो वाक्यं तथापि व्यथितेन्द्रियः।
पुनर्जातमिवात्मानं स मेने ऋक्षपुंगवः॥', 'śrutvā hanumato vākyaṃ tathāpi vyathitendriyaḥ
punarjātam ivātmānaṃ sa mene ṛkṣapuṃgavaḥ', null, 6061025),
('ramayana-6-61-26', 26, 'Yuddha Kanda, Sarga 61, Verse 26', 'ततोऽब्रवीन्महातेजा हनूमन्तं स जाम्बवान्।
आगच्छ हरिशार्दूलवानरांस्त्रातुमर्हसि॥', 'tato ''bravīn mahātejā hanūmantaṃ sa jāmbavān
āgaccha hariśārdūlavānarāṃs trātum arhasi', null, 6061026),
('ramayana-6-61-27', 27, 'Yuddha Kanda, Sarga 61, Verse 27', 'नान्यो विक्रमपर्याप्तस्त्वमेषां परमः सखा।
त्वत्पराक्रमकालोऽयं नान्यं पश्यामि कञ्चन॥', 'nānyo vikramaparyāptas tvam eṣāṃ paramaḥ sakhā
tvatparākramakālo ''yaṃ nānyaṃ paśyāmi kañ cana', null, 6061027),
('ramayana-6-61-28', 28, 'Yuddha Kanda, Sarga 61, Verse 28', 'ऋक्षवानरवीराणामनीकानि प्रहर्षय।
विशल्यौ कुरु चाप्येतौ सादितौ रामलक्ष्मणौ॥', 'ṛkṣavānaravīrāṇām anīkāni praharṣaya
viśalyau kuru cāpy etau sāditau rāmalakṣmaṇau', null, 6061028),
('ramayana-6-61-29', 29, 'Yuddha Kanda, Sarga 61, Verse 29', 'गत्वा परममध्वानमुपर्युपरि सागरम्।
हिमवन्तं नगश्रेष्ठं हनूमन्गन्तुमर्हसि॥', 'gatvā paramam adhvānam upary upari sāgaram
himavantaṃ nagaśreṣṭhaṃ hanūman gantum arhasi', null, 6061029),
('ramayana-6-61-30', 30, 'Yuddha Kanda, Sarga 61, Verse 30', 'ततः काञ्चनमत्युग्रमृषभं पर्वतोत्तमम्।
कैलासशिखरं चापि द्रक्ष्यस्यरिनिषूदन॥', 'tataḥ kāñcanam atyugram ṛṣabhaṃ parvatottamam
kailāsaśikharaṃ cāpi drakṣyasy ariniṣūdana', null, 6061030),
('ramayana-6-61-31', 31, 'Yuddha Kanda, Sarga 61, Verse 31', 'तयोः शिखरयोर्मध्ये प्रदीप्तमतुलप्रभम्।
सर्वौषधियुतं वीर द्रक्ष्यस्यौषधिपर्वतम्॥', 'tayoḥ śikharayor madhye pradīptam atulaprabham
sarvauṣadhiyutaṃ vīra drakṣyasy auṣadhiparvatam', null, 6061031),
('ramayana-6-61-32', 32, 'Yuddha Kanda, Sarga 61, Verse 32', 'तस्य वानरशार्दूलचतस्रो मूर्ध्नि संभवाः।
द्रक्ष्यस्योषधयो दीप्ता दीपयन्त्यो दिशो दश॥', 'tasya vānaraśārdūlacatasro mūrdhni saṃbhavāḥ
drakṣyasy oṣadhayo dīptā dīpayantyo diśo daśa', null, 6061032),
('ramayana-6-61-33', 33, 'Yuddha Kanda, Sarga 61, Verse 33', 'मृतसंजीवनीं चैव विशल्यकरणीमपि।
सौवर्णकरणीं चैव संधानीं च महौषधीम्॥', 'mṛtasaṃjīvanīṃ caiva viśalyakaraṇīm api
sauvarṇakaraṇīṃ caiva saṃdhānīṃ ca mahauṣadhīm', null, 6061033),
('ramayana-6-61-34', 34, 'Yuddha Kanda, Sarga 61, Verse 34', 'ताः सर्वा हनुमन्गृह्य क्षिप्रमागन्तुमर्हसि।
आश्वासय हरीन्प्राणैर्योज्य गन्धवहात्मजः॥', 'tāḥ sarvā hanuman gṛhya kṣipram āgantum arhasi
āśvāsaya harīn prāṇair yojya gandhavahātmajaḥ', null, 6061034),
('ramayana-6-61-35', 35, 'Yuddha Kanda, Sarga 61, Verse 35', 'श्रुत्वा जाम्बवतो वाक्यं हनूमान्हरिपुंगवः।
आपूर्यत बलोद्धर्षैस्तोयवेगैरिवार्णवः॥', 'śrutvā jāmbavato vākyaṃ hanūmān haripuṃgavaḥ
āpūryata baloddharṣais toyavegair ivārṇavaḥ', null, 6061035),
('ramayana-6-61-36', 36, 'Yuddha Kanda, Sarga 61, Verse 36', 'स पर्वततटाग्रस्थः पीडयन्पर्वतोत्तरम्।
हनूमान्दृश्यते वीरो द्वितीय इव पर्वतः॥', 'sa parvatataṭāgrasthaḥ pīḍayan parvatottaram
hanūmān dṛśyate vīro dvitīya iva parvataḥ', null, 6061036),
('ramayana-6-61-37', 37, 'Yuddha Kanda, Sarga 61, Verse 37', 'हरिपादविनिर्भिन्नो निषसाद स पर्वतः।
न शशाक तदात्मानं सोढुं भृशनिपीडितः॥', 'haripādavinirbhinno niṣasāda sa parvataḥ
na śaśāka tadātmānaṃ soḍhuṃ bhṛśanipīḍitaḥ', null, 6061037),
('ramayana-6-61-38', 38, 'Yuddha Kanda, Sarga 61, Verse 38', 'तस्य पेतुर्नगा भूमौ हरिवेगाच्च जज्वलुः।
शृङ्गाणि च व्यकीर्यन्त पीडितस्य हनूमता॥', 'tasya petur nagā bhūmau harivegāc ca jajvaluḥ
śṛṅgāṇi ca vyakīryanta pīḍitasya hanūmatā', null, 6061038),
('ramayana-6-61-39', 39, 'Yuddha Kanda, Sarga 61, Verse 39', 'तस्मिन्संपीड्यमाने तु भग्नद्रुमशिलातले।
न शेकुर्वानराः स्थातुं घूर्णमाने नगोत्तमे॥', 'tasmin saṃpīḍyamāne tu bhagnadrumaśilātale
na śekur vānarāḥ sthātuṃ ghūrṇamāne nagottame', null, 6061039),
('ramayana-6-61-40', 40, 'Yuddha Kanda, Sarga 61, Verse 40', 'स घूर्णितमहाद्वारा प्रभग्नगृहगोपुरा।
लङ्का त्रासाकुला रात्रौ प्रनृत्तेवाभवत्तदा॥', 'sa ghūrṇitamahādvārā prabhagnagṛhagopurā
laṅkā trāsākulā rātrau pranṛttevābhavat tadā', null, 6061040),
('ramayana-6-61-41', 41, 'Yuddha Kanda, Sarga 61, Verse 41', 'पृथिवीधरसंकाशो निपीड्य धरणीधरम्।
पृथिवीं क्षोभयामास सार्णवां मारुतात्मजः॥', 'pṛthivīdharasaṃkāśo nipīḍya dharaṇīdharam
pṛthivīṃ kṣobhayām āsa sārṇavāṃ mārutātmajaḥ', null, 6061041),
('ramayana-6-61-42', 42, 'Yuddha Kanda, Sarga 61, Verse 42', 'पद्भ्यां तु शैलमापीड्य वडवामुखवन्मुखम्।
विवृत्योग्रं ननादोच्चैस्त्रासयन्निव राक्षसान्॥', 'padbhyāṃ tu śailam āpīḍya vaḍavāmukhavan mukham
vivṛtyograṃ nanādoccais trāsayann iva rākṣasān', null, 6061042),
('ramayana-6-61-43', 43, 'Yuddha Kanda, Sarga 61, Verse 43', 'तस्य नानद्यमानस्य श्रुत्वा निनदमद्भुतम्।
लङ्कास्था राक्षसाः सर्वे न शेकुः स्पन्दितुं भयात्॥', 'tasya nānadyamānasya śrutvā ninadam adbhutam
laṅkāsthā rākṣasāḥ sarve na śekuḥ spandituṃ bhayāt', null, 6061043),
('ramayana-6-61-44', 44, 'Yuddha Kanda, Sarga 61, Verse 44', 'नमस्कृत्वाथ रामाय मारुतिर्भीमविक्रमः।
राघवार्थे परं कर्म समैहत परंतपः॥', 'namaskṛtvātha rāmāya mārutir bhīmavikramaḥ
rāghavārthe paraṃ karma samaihata paraṃtapaḥ', null, 6061044),
('ramayana-6-61-45', 45, 'Yuddha Kanda, Sarga 61, Verse 45', 'स पुच्छमुद्यम्य भुजंगकल्पं विनम्य पृष्ठं श्रवणे निकुञ्च्य।
विवृत्य वक्त्रं वडवामुखाभमापुप्लुवे व्योम्नि स चण्डवेगः॥', 'sa puccham udyamya bhujaṃgakalpaṃ vinamya pṛṣṭhaṃ śravaṇe nikuñcya
vivṛtya vaktraṃ vaḍavāmukhābham āpupluve vyomni sa caṇḍavegaḥ', null, 6061045),
('ramayana-6-61-46', 46, 'Yuddha Kanda, Sarga 61, Verse 46', 'स वृक्षषण्डांस्तरसा जहार शैलाञ्शिलाः प्राकृतवानरांश्च।
बाहूरुवेगोद्धतसंप्रणुन्नास्ते क्षीणवेगाः सलिले निपेतुः॥', 'sa vṛkṣaṣaṇḍāṃs tarasā jahāra śailāñ śilāḥ prākṛtavānarāṃś ca
bāhūruvegoddhatasaṃpraṇunnās te kṣīṇavegāḥ salile nipetuḥ', null, 6061046),
('ramayana-6-61-47', 47, 'Yuddha Kanda, Sarga 61, Verse 47', 'स तौ प्रसार्योरगभोगकल्पौ भुजौ भुजंगारिनिकाशवीर्यः।
जगाम मेरुं नगराजमग्र्यं दिशः प्रकर्षन्निव वायुसूनुः॥', 'sa tau prasāryoragabhogakalpau bhujau bhujaṃgārinikāśavīryaḥ
jagāma meruṃ nagarājam agryaṃ diśaḥ prakarṣann iva vāyusūnuḥ', null, 6061047),
('ramayana-6-61-48', 48, 'Yuddha Kanda, Sarga 61, Verse 48', 'स सागरं घूर्णितवीचिमालं तदा भृशं भ्रामितसर्वसत्त्वम्।
समीक्षमाणः सहसा जगाम चक्रं यथा विष्णुकराग्रमुक्तम्॥', 'sa sāgaraṃ ghūrṇitavīcimālaṃ tadā bhṛśaṃ bhrāmitasarvasattvam
samīkṣamāṇaḥ sahasā jagāma cakraṃ yathā viṣṇukarāgramuktam', null, 6061048),
('ramayana-6-61-49', 49, 'Yuddha Kanda, Sarga 61, Verse 49', 'स पर्वतान्वृक्षगणान्सरांसि नदीस्तटाकानि पुरोत्तमानि।
स्फीताञ्जनांस्तानपि संप्रपश्यञ्जगाम वेगात्पितृतुल्यवेगः॥', 'sa parvatān vṛkṣagaṇān sarāṃsi nadīs taṭākāni purottamāni
sphītāñjanāṃs tān api saṃprapaśyañ jagāma vegāt pitṛtulyavegaḥ', null, 6061049),
('ramayana-6-61-50', 50, 'Yuddha Kanda, Sarga 61, Verse 50', 'आदित्यपथमाश्रित्य जगाम स गतश्रमः।
स ददर्श हरिश्रेष्ठो हिमवन्तं नगोत्तमम्॥', 'ādityapatham āśritya jagāma sa gataśramaḥ
sa dadarśa hariśreṣṭho himavantaṃ nagottamam', null, 6061050),
('ramayana-6-61-51', 51, 'Yuddha Kanda, Sarga 61, Verse 51', 'नानाप्रस्रवणोपेतं बहुकंदरनिर्झरम्।
श्वेताभ्रचयसंकाशैः शिखरैश्चारुदर्शनैः॥', 'nānāprasravaṇopetaṃ bahukaṃdaranirjharam
śvetābhracayasaṃkāśaiḥ śikharaiś cārudarśanaiḥ', null, 6061051),
('ramayana-6-61-52', 52, 'Yuddha Kanda, Sarga 61, Verse 52', 'स तं समासाद्य महानगेन्द्रमतिप्रवृद्धोत्तमघोरशृङ्गम्।
ददर्श पुण्यानि महाश्रमाणि सुरर्षिसंघोत्तमसेवितानि॥', 'sa taṃ samāsādya mahānagendram atipravṛddhottamaghoraśṛṅgam
dadarśa puṇyāni mahāśramāṇi surarṣisaṃghottamasevitāni', null, 6061052),
('ramayana-6-61-53', 53, 'Yuddha Kanda, Sarga 61, Verse 53', 'स ब्रह्मकोशं रजतालयं च शक्रालयं रुद्रशरप्रमोक्षम्।
हयाननं ब्रह्मशिरश्च दीप्तं ददर्श वैवस्वत किंकरांश्च॥', 'sa brahmakośaṃ rajatālayaṃ ca śakrālayaṃ rudraśarapramokṣam
hayānanaṃ brahmaśiraś ca dīptaṃ dadarśa vaivasvata kiṃkarāṃś ca', null, 6061053),
('ramayana-6-61-54', 54, 'Yuddha Kanda, Sarga 61, Verse 54', 'वज्रालयं वैश्वरणालयं च सूर्यप्रभं सूर्यनिबन्धनं च।
ब्रह्मासनं शंकरकार्मुकं च ददर्श नाभिं च वसुंधरायाः॥', 'vajrālayaṃ vaiśvaraṇālayaṃ ca sūryaprabhaṃ sūryanibandhanaṃ ca
brahmāsanaṃ śaṃkarakārmukaṃ ca dadarśa nābhiṃ ca vasuṃdharāyāḥ', null, 6061054),
('ramayana-6-61-55', 55, 'Yuddha Kanda, Sarga 61, Verse 55', 'कैलासमग्र्यं हिमवच्छिलां च तथर्षभं काञ्चनशैलमग्र्यम्।
स दीप्तसर्वौषधिसंप्रदीप्तं ददर्श सर्वौषधिपर्वतेन्द्रम्॥', 'kailāsam agryaṃ himavacchilāṃ ca tatharṣabhaṃ kāñcanaśailam agryam
sa dīptasarvauṣadhisaṃpradīptaṃ dadarśa sarvauṣadhiparvatendram', null, 6061055),
('ramayana-6-61-56', 56, 'Yuddha Kanda, Sarga 61, Verse 56', 'स तं समीक्ष्यानलरश्मिदीप्तं विसिष्मिये वासवदूतसूनुः।
आप्लुत्य तं चौषधिपर्वतेन्द्रं तत्रौषधीनां विचयं चकार॥', 'sa taṃ samīkṣyānalaraśmidīptaṃ visiṣmiye vāsavadūtasūnuḥ
āplutya taṃ cauṣadhiparvatendraṃ tatrauṣadhīnāṃ vicayaṃ cakāra', null, 6061056),
('ramayana-6-61-57', 57, 'Yuddha Kanda, Sarga 61, Verse 57', 'स योजनसहस्राणि समतीत्य महाकपिः।
दिव्यौषधिधरं शैलं व्यचरन्मारुतात्मजः॥', 'sa yojanasahasrāṇi samatītya mahākapiḥ
divyauṣadhidharaṃ śailaṃ vyacaran mārutātmajaḥ', null, 6061057),
('ramayana-6-61-58', 58, 'Yuddha Kanda, Sarga 61, Verse 58', 'महौषध्यस्तु ताः सर्वास्तस्मिन्पर्वतसत्तमे।
विज्ञायार्थिनमायान्तं ततो जग्मुरदर्शनम्॥', 'mahauṣadhyas tu tāḥ sarvās tasmin parvatasattame
vijñāyārthinam āyāntaṃ tato jagmur adarśanam', null, 6061058),
('ramayana-6-61-59', 59, 'Yuddha Kanda, Sarga 61, Verse 59', 'स ता महात्मा हनुमानपश्यंश्चुकोप कोपाच्च भृशं ननाद।
अमृष्यमाणोऽग्निनिकाशचक्षुर्महीधरेन्द्रं तमुवाच वाक्यम्॥', 'sa tā mahātmā hanumān apaśyaṃś cukopa kopāc ca bhṛśaṃ nanāda
amṛṣyamāṇo ''gninikāśacakṣur mahīdharendraṃ tam uvāca vākyam', null, 6061059),
('ramayana-6-61-60', 60, 'Yuddha Kanda, Sarga 61, Verse 60', 'किमेतदेवं सुविनिश्चितं ते यद्राघवे नासि कृतानुकम्पः।
पश्याद्य मद्बाहुबलाभिभूतो विकीर्णमात्मानमथो नगेन्द्र॥', 'kim etad evaṃ suviniścitaṃ te yad rāghave nāsi kṛtānukampaḥ
paśyādya madbāhubalābhibhūto vikīrṇam ātmānam atho nagendra', null, 6061060),
('ramayana-6-61-61', 61, 'Yuddha Kanda, Sarga 61, Verse 61', 'स तस्य शृङ्गं सनगं सनागं सकाञ्चनं धातुसहस्रजुष्टम्।
विकीर्णकूटं चलिताग्रसानुं प्रगृह्य वेगात्सहसोन्ममाथ॥', 'sa tasya śṛṅgaṃ sanagaṃ sanāgaṃ sakāñcanaṃ dhātusahasrajuṣṭam
vikīrṇakūṭaṃ calitāgrasānuṃ pragṛhya vegāt sahasonmamātha', null, 6061061),
('ramayana-6-61-62', 62, 'Yuddha Kanda, Sarga 61, Verse 62', 'स तं समुत्पाट्य खमुत्पपात वित्रास्य लोकान्ससुरान्सुरेन्द्रान्।
संस्तूयमानः खचरैरनेकैर्जगाम वेगाद्गरुडोग्रवीर्यः॥', 'sa taṃ samutpāṭya kham utpapāta vitrāsya lokān sasurān surendrān
saṃstūyamānaḥ khacarair anekair jagāma vegād garuḍogravīryaḥ', null, 6061062),
('ramayana-6-61-63', 63, 'Yuddha Kanda, Sarga 61, Verse 63', 'स भास्कराध्वानमनुप्रपन्नस्तद्भास्कराभं शिखरं प्रगृह्य।
बभौ तदा भास्करसंनिकाशो रवेः समीपे प्रतिभास्कराभः॥', 'sa bhāskarādhvānam anuprapannas tad bhāskarābhaṃ śikharaṃ pragṛhya
babhau tadā bhāskarasaṃnikāśo raveḥ samīpe pratibhāskarābhaḥ', null, 6061063),
('ramayana-6-61-64', 64, 'Yuddha Kanda, Sarga 61, Verse 64', 'स तेन शैलेन भृशं रराज शैलोपमो गन्धवहात्मजस्तु।
सहस्रधारेण सपावकेन चक्रेण खे विष्णुरिवोद्धृतेन॥', 'sa tena śailena bhṛśaṃ rarāja śailopamo gandhavahātmajas tu
sahasradhāreṇa sapāvakena cakreṇa khe viṣṇur ivoddhṛtena', null, 6061064),
('ramayana-6-61-65', 65, 'Yuddha Kanda, Sarga 61, Verse 65', 'तं वानराः प्रेक्ष्य तदा विनेदुः स तानपि प्रेक्ष्य मुदा ननाद।
तेषां समुद्घुष्टरवं निशम्य लङ्कालया भीमतरं विनेदुः॥', 'taṃ vānarāḥ prekṣya tadā vineduḥ sa tān api prekṣya mudā nanāda
teṣāṃ samudghuṣṭaravaṃ niśamya laṅkālayā bhīmataraṃ vineduḥ', null, 6061065),
('ramayana-6-61-66', 66, 'Yuddha Kanda, Sarga 61, Verse 66', 'ततो महात्मा निपपात तस्मिञ्शैलोत्तमे वानरसैन्यमध्ये।
हर्युत्तमेभ्यः शिरसाभिवाद्य विभीषणं तत्र च सस्वजे सः॥', 'tato mahātmā nipapāta tasmiñ śailottame vānarasainyamadhye
haryuttamebhyaḥ śirasābhivādya vibhīṣaṇaṃ tatra ca sasvaje saḥ', null, 6061066),
('ramayana-6-61-67', 67, 'Yuddha Kanda, Sarga 61, Verse 67', 'तावप्युभौ मानुषराजपुत्रौ तं गन्धमाघ्राय महौषधीनाम्।
बभूवतुस्तत्र तदा विशल्यावुत्तस्थुरन्ये च हरिप्रवीराः॥', 'tāv apy ubhau mānuṣarājaputrau taṃ gandham āghrāya mahauṣadhīnām
babhūvatus tatra tadā viśalyāv uttasthur anye ca haripravīrāḥ', null, 6061067),
('ramayana-6-61-68', 68, 'Yuddha Kanda, Sarga 61, Verse 68', 'ततो हरिर्गन्धवहात्मजस्तु तमोषधीशैलमुदग्रवीर्यः।
निनाय वेगाद्धिमवन्तमेव पुनश्च रामेण समाजगाम॥', 'tato harir gandhavahātmajas tu tam oṣadhīśailam udagravīryaḥ
nināya vegād dhimavantam eva punaś ca rāmeṇa samājagāma', null, 6061068)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 62 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-62-1', 1, 'Yuddha Kanda, Sarga 62, Verse 1', 'ततोऽब्रवीन्महातेजाः सुग्रीवो वानराधिपः।
अर्थ्यं विजापयंश्चापि हनूमन्तं महाबलम्॥', 'tato ''bravīn mahātejāḥ sugrīvo vānarādhipaḥ
arthyaṃ vijāpayaṃś cāpi hanūmantaṃ mahābalam', null, 6062001),
('ramayana-6-62-2', 2, 'Yuddha Kanda, Sarga 62, Verse 2', 'यतो हतः कुम्भकर्णः कुमाराश्च निषूदिताः।
नेदानीमुपनिर्हारं रावणो दातुमर्हति॥', 'yato hataḥ kumbhakarṇaḥ kumārāś ca niṣūditāḥ
nedānīm upanirhāraṃ rāvaṇo dātum arhati', null, 6062002),
('ramayana-6-62-3', 3, 'Yuddha Kanda, Sarga 62, Verse 3', 'ये ये महाबलाः सन्ति लघवश्च प्लवंगमाः।
लङ्कामभ्युत्पतन्त्वाशु गृह्योल्काः प्लवगर्षभाः॥', 'ye ye mahābalāḥ santi laghavaś ca plavaṃgamāḥ
laṅkām abhyutpatantv āśu gṛhyolkāḥ plavagarṣabhāḥ', null, 6062003),
('ramayana-6-62-4', 4, 'Yuddha Kanda, Sarga 62, Verse 4', 'ततोऽस्तं गत आदित्ये रौद्रे तस्मिन्निशामुखे।
लङ्कामभिमुखाः सोल्का जग्मुस्ते प्लवगर्षभाः॥', 'tato ''staṃ gata āditye raudre tasmin niśāmukhe
laṅkām abhimukhāḥ solkā jagmus te plavagarṣabhāḥ', null, 6062004),
('ramayana-6-62-5', 5, 'Yuddha Kanda, Sarga 62, Verse 5', 'उल्काहस्तैर्हरिगणैः सर्वतः समभिद्रुताः।
आरक्षस्था विरूपाक्षाः सहसा विप्रदुद्रुवुः॥', 'ulkāhastair harigaṇaiḥ sarvataḥ samabhidrutāḥ
ārakṣasthā virūpākṣāḥ sahasā vipradudruvuḥ', null, 6062005),
('ramayana-6-62-6', 6, 'Yuddha Kanda, Sarga 62, Verse 6', 'गोपुराट्ट प्रतोलीषु चर्यासु विविधासु च।
प्रासादेषु च संहृष्टाः ससृजुस्ते हुताशनम्॥', 'gopurāṭṭa pratolīṣu caryāsu vividhāsu ca
prāsādeṣu ca saṃhṛṣṭāḥ sasṛjus te hutāśanam', null, 6062006),
('ramayana-6-62-7', 7, 'Yuddha Kanda, Sarga 62, Verse 7', 'तेषां गृहसहस्राणि ददाह हुतभुक्तदा।
आवासान्राक्षसानां च सर्वेषां गृहमेधिनाम्॥', 'teṣāṃ gṛhasahasrāṇi dadāha hutabhuk tadā
āvāsān rākṣasānāṃ ca sarveṣāṃ gṛhamedhinām', null, 6062007),
('ramayana-6-62-8', 8, 'Yuddha Kanda, Sarga 62, Verse 8', 'हेमचित्रतनुत्राणां स्रग्दामाम्बरधारिणाम्।
सीधुपानचलाक्षाणां मदविह्वलगामिनाम्॥', 'hemacitratanutrāṇāṃ sragdāmāmbaradhāriṇām
sīdhupānacalākṣāṇāṃ madavihvalagāminām', null, 6062008),
('ramayana-6-62-9', 9, 'Yuddha Kanda, Sarga 62, Verse 9', 'कान्तालम्बितवस्त्राणां शत्रुसंजातमन्युनाम्।
गदाशूलासि हस्तानां खादतां पिबतामपि॥', 'kāntālambitavastrāṇāṃ śatrusaṃjātamanyunām
gadāśūlāsi hastānāṃ khādatāṃ pibatām api', null, 6062009),
('ramayana-6-62-10', 10, 'Yuddha Kanda, Sarga 62, Verse 10', 'शयनेषु महार्हेषु प्रसुप्तानां प्रियैः सह।
त्रस्तानां गच्छतां तूर्णं पुत्रानादाय सर्वतः॥', 'śayaneṣu mahārheṣu prasuptānāṃ priyaiḥ saha
trastānāṃ gacchatāṃ tūrṇaṃ putrān ādāya sarvataḥ', null, 6062010),
('ramayana-6-62-11', 11, 'Yuddha Kanda, Sarga 62, Verse 11', 'तेषां गृहसहस्राणि तदा लङ्कानिवासिनाम्।
अदहत्पावकस्तत्र जज्वाल च पुनः पुनः॥', 'teṣāṃ gṛhasahasrāṇi tadā laṅkānivāsinām
adahat pāvakas tatra jajvāla ca punaḥ punaḥ', null, 6062011),
('ramayana-6-62-12', 12, 'Yuddha Kanda, Sarga 62, Verse 12', 'सारवन्ति महार्हाणि गम्भीरगुणवन्ति च।
हेमचन्द्रार्धचन्द्राणि चन्द्रशालोन्नतानि च॥', 'sāravanti mahārhāṇi gambhīraguṇavanti ca
hemacandrārdhacandrāṇi candraśālonnatāni ca', null, 6062012),
('ramayana-6-62-13', 13, 'Yuddha Kanda, Sarga 62, Verse 13', 'रत्नचित्रगवाक्षाणि साधिष्ठानानि सर्वशः।
मणिविद्रुमचित्राणि स्पृशन्तीव च भास्करम्॥', 'ratnacitragavākṣāṇi sādhiṣṭhānāni sarvaśaḥ
maṇividrumacitrāṇi spṛśantīva ca bhāskaram', null, 6062013),
('ramayana-6-62-14', 14, 'Yuddha Kanda, Sarga 62, Verse 14', 'क्रौञ्चबर्हिणवीणानां भूषणानां च निस्वनैः।
नादितान्यचलाभानि वेश्मान्यग्निर्ददाह सः॥', 'krauñcabarhiṇavīṇānāṃ bhūṣaṇānāṃ ca nisvanaiḥ
nāditāny acalābhāni veśmāny agnir dadāha saḥ', null, 6062014),
('ramayana-6-62-15', 15, 'Yuddha Kanda, Sarga 62, Verse 15', 'ज्वलनेन परीतानि तोरणानि चकाशिरे।
विद्युद्भिरिव नद्धानि मेघजालानि घर्मगे॥', 'jvalanena parītāni toraṇāni cakāśire
vidyudbhir iva naddhāni meghajālāni gharmage', null, 6062015),
('ramayana-6-62-16', 16, 'Yuddha Kanda, Sarga 62, Verse 16', 'विमानेषु प्रसुप्ताश्च दह्यमाना वराङ्गनाः।
त्यक्ताभरणसंयोगा हाहेत्युच्चैर्विचुक्रुशः॥', 'vimāneṣu prasuptāś ca dahyamānā varāṅganāḥ
tyaktābharaṇasaṃyogā hāhety uccair vicukruśaḥ', null, 6062016),
('ramayana-6-62-17', 17, 'Yuddha Kanda, Sarga 62, Verse 17', 'तत्र चाग्निपरीतानि निपेतुर्भवनान्यपि।
वज्रिवज्रहतानीव शिखराणि महागिरेः॥', 'tatra cāgniparītāni nipetur bhavanāny api
vajrivajrahatānīva śikharāṇi mahāgireḥ', null, 6062017),
('ramayana-6-62-18', 18, 'Yuddha Kanda, Sarga 62, Verse 18', 'तानि निर्दह्यमानानि दूरतः प्रचकाशिरे।
हिमवच्छिखराणीव दीप्तौषधिवनानि च॥', 'tāni nirdahyamānāni dūrataḥ pracakāśire
himavacchikharāṇīva dīptauṣadhivanāni ca', null, 6062018),
('ramayana-6-62-19', 19, 'Yuddha Kanda, Sarga 62, Verse 19', 'हर्म्याग्रैर्दह्यमानैश्च ज्वालाप्रज्वलितैरपि।
रात्रौ सा दृश्यते लङ्का पुष्पितैरिव किंशुकैः॥', 'harmyāgrair dahyamānaiś ca jvālāprajvalitair api
rātrau sā dṛśyate laṅkā puṣpitair iva kiṃśukaiḥ', null, 6062019),
('ramayana-6-62-20', 20, 'Yuddha Kanda, Sarga 62, Verse 20', 'हस्त्यध्यक्षैर्गजैर्मुक्तैर्मुक्तैश्च तुरगैरपि।
बभूव लङ्का लोकान्ते भ्रान्तग्राह इवार्णवः॥', 'hastyadhyakṣair gajair muktair muktaiś ca turagair api
babhūva laṅkā lokānte bhrāntagrāha ivārṇavaḥ', null, 6062020),
('ramayana-6-62-21', 21, 'Yuddha Kanda, Sarga 62, Verse 21', 'अश्वं मुक्तं गजो दृष्ट्वा कच्चिद्भीतोऽपसर्पति।
भीतो भीतं गजं दृष्ट्वा क्व चिदश्वो निवर्तते॥', 'aśvaṃ muktaṃ gajo dṛṣṭvā kaccid bhīto ''pasarpati
bhīto bhītaṃ gajaṃ dṛṣṭvā kva cid aśvo nivartate', null, 6062021),
('ramayana-6-62-22', 22, 'Yuddha Kanda, Sarga 62, Verse 22', 'सा बभूव मुहूर्तेन हरिभिर्दीपिता पुरी।
लोकस्यास्य क्षये घोरे प्रदीप्तेव वसुंधरा॥', 'sā babhūva muhūrtena haribhir dīpitā purī
lokasyāsya kṣaye ghore pradīpteva vasuṃdharā', null, 6062022),
('ramayana-6-62-23', 23, 'Yuddha Kanda, Sarga 62, Verse 23', 'नारी जनस्य धूमेन व्याप्तस्योच्चैर्विनेदुषः।
स्वनो ज्वलनतप्तस्य शुश्रुवे दशयोजनम्॥', 'nārī janasya dhūmena vyāptasyoccair vineduṣaḥ
svano jvalanataptasya śuśruve daśayojanam', null, 6062023),
('ramayana-6-62-24', 24, 'Yuddha Kanda, Sarga 62, Verse 24', 'प्रदग्धकायानपरान्राक्षसान्निर्गतान्बहिः।
सहसाभ्युत्पतन्ति स्म हरयोऽथ युयुत्सवः॥', 'pradagdhakāyān aparān rākṣasān nirgatān bahiḥ
sahasābhyutpatanti sma harayo ''tha yuyutsavaḥ', null, 6062024),
('ramayana-6-62-25', 25, 'Yuddha Kanda, Sarga 62, Verse 25', 'उद्घुष्टं वानराणां च राक्षसानां च निस्वनः।
दिशो दश समुद्रं च पृथिवीं चान्वनादयत्॥', 'udghuṣṭaṃ vānarāṇāṃ ca rākṣasānāṃ ca nisvanaḥ
diśo daśa samudraṃ ca pṛthivīṃ cānvanādayat', null, 6062025),
('ramayana-6-62-26', 26, 'Yuddha Kanda, Sarga 62, Verse 26', 'विशल्यौ तु महात्मानौ तावुभौ रामलक्ष्मणौ।
असंभ्रान्तौ जगृहतुस्तावुभौ धनुषी वरे॥', 'viśalyau tu mahātmānau tāv ubhau rāmalakṣmaṇau
asaṃbhrāntau jagṛhatus tāv ubhau dhanuṣī vare', null, 6062026),
('ramayana-6-62-27', 27, 'Yuddha Kanda, Sarga 62, Verse 27', 'ततो विस्फारयाणस्य रामस्य धनुरुत्तमम्।
बभूव तुमुलः शब्दो राक्षसानां भयावहः॥', 'tato visphārayāṇasya rāmasya dhanur uttamam
babhūva tumulaḥ śabdo rākṣasānāṃ bhayāvahaḥ', null, 6062027),
('ramayana-6-62-28', 28, 'Yuddha Kanda, Sarga 62, Verse 28', 'अशोभत तदा रामो धनुर्विस्फारयन्महत्।
भगवानिव संक्रुद्धो भवो वेदमयं धनुः॥', 'aśobhata tadā rāmo dhanur visphārayan mahat
bhagavān iva saṃkruddho bhavo vedamayaṃ dhanuḥ', null, 6062028),
('ramayana-6-62-29', 29, 'Yuddha Kanda, Sarga 62, Verse 29', 'वानरोद्घुष्टघोषश्च राक्षसानां च निस्वनः।
ज्याशब्दश्चापि रामस्य त्रयं व्याप दिशो दश॥', 'vānarodghuṣṭaghoṣaś ca rākṣasānāṃ ca nisvanaḥ
jyāśabdaś cāpi rāmasya trayaṃ vyāpa diśo daśa', null, 6062029),
('ramayana-6-62-30', 30, 'Yuddha Kanda, Sarga 62, Verse 30', 'तस्य कार्मुकमुक्तैश्च शरैस्तत्पुरगोपुरम्।
कैलासशृङ्गप्रतिमं विकीर्णमपतद्भुवि॥', 'tasya kārmukamuktaiś ca śarais tatpuragopuram
kailāsaśṛṅgapratimaṃ vikīrṇam apatad bhuvi', null, 6062030),
('ramayana-6-62-31', 31, 'Yuddha Kanda, Sarga 62, Verse 31', 'ततो रामशरान्दृष्ट्वा विमानेषु गृहेषु च।
संनाहो राक्षसेन्द्राणां तुमुलः समपद्यत॥', 'tato rāmaśarān dṛṣṭvā vimāneṣu gṛheṣu ca
saṃnāho rākṣasendrāṇāṃ tumulaḥ samapadyata', null, 6062031),
('ramayana-6-62-32', 32, 'Yuddha Kanda, Sarga 62, Verse 32', 'तेषां संनह्यमानानां सिंहनादं च कुर्वताम्।
शर्वरी राक्षसेन्द्राणां रौद्रीव समपद्यत॥', 'teṣāṃ saṃnahyamānānāṃ siṃhanādaṃ ca kurvatām
śarvarī rākṣasendrāṇāṃ raudrīva samapadyata', null, 6062032),
('ramayana-6-62-33', 33, 'Yuddha Kanda, Sarga 62, Verse 33', 'आदिष्टा वानरेन्द्रास्ते सुग्रीवेण महात्मना।
आसन्ना द्वारमासाद्य युध्यध्वं प्लवगर्षभाः॥', 'ādiṣṭā vānarendrās te sugrīveṇa mahātmanā
āsannā dvāram āsādya yudhyadhvaṃ plavagarṣabhāḥ', null, 6062033),
('ramayana-6-62-34', 34, 'Yuddha Kanda, Sarga 62, Verse 34', 'यश्च वो वितथं कुर्यात्तत्र तत्र व्यवस्थितः।
स हन्तव्योऽभिसंप्लुत्य राजशासनदूषकः॥', 'yaś ca vo vitathaṃ kuryāt tatra tatra vyavasthitaḥ
sa hantavyo ''bhisaṃplutya rājaśāsanadūṣakaḥ', null, 6062034),
('ramayana-6-62-35', 35, 'Yuddha Kanda, Sarga 62, Verse 35', 'तेषु वानरमुख्येषु दीप्तोल्कोज्ज्वलपाणिषु।
स्थितेषु द्वारमासाद्य रावणं मन्युराविशत्॥', 'teṣu vānaramukhyeṣu dīptolkojjvalapāṇiṣu
sthiteṣu dvāram āsādya rāvaṇaṃ manyur āviśat', null, 6062035),
('ramayana-6-62-36', 36, 'Yuddha Kanda, Sarga 62, Verse 36', 'तस्य जृम्भितविक्षेपाद्व्यामिश्रा वै दिशो दश।
रूपवानिव रुद्रस्य मन्युर्गात्रेष्वदृश्यत॥', 'tasya jṛmbhitavikṣepād vyāmiśrā vai diśo daśa
rūpavān iva rudrasya manyur gātreṣv adṛśyata', null, 6062036),
('ramayana-6-62-37', 37, 'Yuddha Kanda, Sarga 62, Verse 37', 'स निकुम्भं च कुम्भं च कुम्भकर्णात्मजावुभौ।
प्रेषयामास संक्रुद्धो राक्षसैर्बहुभिः सह॥', 'sa nikumbhaṃ ca kumbhaṃ ca kumbhakarṇātmajāv ubhau
preṣayām āsa saṃkruddho rākṣasair bahubhiḥ saha', null, 6062037),
('ramayana-6-62-38', 38, 'Yuddha Kanda, Sarga 62, Verse 38', 'शशास चैव तान्सर्वान्राक्षसान्राक्षसेश्वरः।
राक्षसा गच्छतात्रैव सिंहनादं च नादयन्॥', 'śaśāsa caiva tān sarvān rākṣasān rākṣaseśvaraḥ
rākṣasā gacchatātraiva siṃhanādaṃ ca nādayan', null, 6062038),
('ramayana-6-62-39', 39, 'Yuddha Kanda, Sarga 62, Verse 39', 'ततस्तु चोदितास्तेन राक्षसा ज्वलितायुधाः।
लङ्काया निर्ययुर्वीराः प्रणदन्तः पुनः पुनः॥', 'tatas tu coditās tena rākṣasā jvalitāyudhāḥ
laṅkāyā niryayur vīrāḥ praṇadantaḥ punaḥ punaḥ', null, 6062039),
('ramayana-6-62-40', 40, 'Yuddha Kanda, Sarga 62, Verse 40', 'भीमाश्वरथमातंगं नानापत्ति समाकुलम्।
दीप्तशूलगदाखड्गप्रासतोमरकार्मुकम्॥', 'bhīmāśvarathamātaṃgaṃ nānāpatti samākulam
dīptaśūlagadākhaḍgaprāsatomarakārmukam', null, 6062040),
('ramayana-6-62-41', 41, 'Yuddha Kanda, Sarga 62, Verse 41', 'तद्राक्षसबलं घोरं भीमविक्रमपौरुषम्।
ददृशे ज्वलितप्रासं किङ्किणीशतनादितम्॥', 'tad rākṣasabalaṃ ghoraṃ bhīmavikramapauruṣam
dadṛśe jvalitaprāsaṃ kiṅkiṇīśatanāditam', null, 6062041),
('ramayana-6-62-42', 42, 'Yuddha Kanda, Sarga 62, Verse 42', 'हेमजालाचितभुजं व्यावेष्टितपरश्वधम्।
व्याघूर्णितमहाशस्त्रं बाणसंसक्तकार्मुकम्॥', 'hemajālācitabhujaṃ vyāveṣṭitaparaśvadham
vyāghūrṇitamahāśastraṃ bāṇasaṃsaktakārmukam', null, 6062042),
('ramayana-6-62-43', 43, 'Yuddha Kanda, Sarga 62, Verse 43', 'गन्धमाल्यमधूत्सेकसंमोदित महानिलम्।
घोरं शूरजनाकीर्णं महाम्बुधरनिस्वनम्॥', 'gandhamālyamadhūtsekasaṃmodita mahānilam
ghoraṃ śūrajanākīrṇaṃ mahāmbudharanisvanam', null, 6062043),
('ramayana-6-62-44', 44, 'Yuddha Kanda, Sarga 62, Verse 44', 'तं दृष्ट्वा बलमायान्तं राक्षसानां सुदारुणम्।
संचचाल प्लवंगानां बलमुच्चैर्ननाद च॥', 'taṃ dṛṣṭvā balam āyāntaṃ rākṣasānāṃ sudāruṇam
saṃcacāla plavaṃgānāṃ balam uccair nanāda ca', null, 6062044),
('ramayana-6-62-45', 45, 'Yuddha Kanda, Sarga 62, Verse 45', 'जवेनाप्लुत्य च पुनस्तद्राक्षसबलं महत्।
अभ्ययात्प्रत्यरिबलं पतंग इव पावकम्॥', 'javenāplutya ca punas tad rākṣasabalaṃ mahat
abhyayāt pratyaribalaṃ pataṃga iva pāvakam', null, 6062045),
('ramayana-6-62-46', 46, 'Yuddha Kanda, Sarga 62, Verse 46', 'तेषां भुजपरामर्शव्यामृष्टपरिघाशनि।
राक्षसानां बलं श्रेष्ठं भूयस्तरमशोभत॥', 'teṣāṃ bhujaparāmarśavyāmṛṣṭaparighāśani
rākṣasānāṃ balaṃ śreṣṭhaṃ bhūyastaram aśobhata', null, 6062046),
('ramayana-6-62-47', 47, 'Yuddha Kanda, Sarga 62, Verse 47', 'तथैवाप्यपरे तेषां कपीनामसिभिः शितैः।
प्रवीरानभितो जघ्नुर्घोररूपा निशाचराः॥', 'tathaivāpy apare teṣāṃ kapīnām asibhiḥ śitaiḥ
pravīrān abhito jaghnur ghorarūpā niśācarāḥ', null, 6062047),
('ramayana-6-62-48', 48, 'Yuddha Kanda, Sarga 62, Verse 48', 'घ्नन्तमन्यं जघानान्यः पातयन्तमपातयत्।
गर्हमाणं जगर्हान्ये दशन्तमपरेऽदशत्॥', 'ghnantam anyaṃ jaghānānyaḥ pātayantam apātayat
garhamāṇaṃ jagarhānye daśantam apare ''daśat', null, 6062048),
('ramayana-6-62-49', 49, 'Yuddha Kanda, Sarga 62, Verse 49', 'देहीत्यन्ये ददात्यन्यो ददामीत्यपरः पुनः।
किं क्लेशयसि तिष्ठेति तत्रान्योन्यं बभाषिरे॥', 'dehīty anye dadāty anyo dadāmīty aparaḥ punaḥ
kiṃ kleśayasi tiṣṭheti tatrānyonyaṃ babhāṣire', null, 6062049),
('ramayana-6-62-50', 50, 'Yuddha Kanda, Sarga 62, Verse 50', 'समुद्यतमहाप्रासं मुष्टिशूलासिसंकुलम्।
प्रावर्तत महारौद्रं युद्धं वानररक्षसाम्॥', 'samudyatamahāprāsaṃ muṣṭiśūlāsisaṃkulam
prāvartata mahāraudraṃ yuddhaṃ vānararakṣasām', null, 6062050),
('ramayana-6-62-51', 51, 'Yuddha Kanda, Sarga 62, Verse 51', 'वानरान्दश सप्तेति राक्षसा अभ्यपातयन्।
राक्षसान्दशसप्तेति वानरा जघ्नुराहवे॥', 'vānarān daśa sapteti rākṣasā abhyapātayan
rākṣasān daśasapteti vānarā jaghnur āhave', null, 6062051),
('ramayana-6-62-52', 52, 'Yuddha Kanda, Sarga 62, Verse 52', 'विस्रस्तकेशरसनं विमुक्तकवचध्वजम्।
बलं राक्षसमालम्ब्य वानराः पर्यवारयन्॥', 'visrastakeśarasanaṃ vimuktakavacadhvajam
balaṃ rākṣasam ālambya vānarāḥ paryavārayan', null, 6062052)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 63 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-63-1', 1, 'Yuddha Kanda, Sarga 63, Verse 1', 'प्रवृत्ते संकुले तस्मिन्घोरे वीरजनक्षये।
अङ्गदः कम्पनं वीरमाससाद रणोत्सुकः॥', 'pravṛtte saṃkule tasmin ghore vīrajanakṣaye
aṅgadaḥ kampanaṃ vīram āsasāda raṇotsukaḥ', null, 6063001),
('ramayana-6-63-2', 2, 'Yuddha Kanda, Sarga 63, Verse 2', 'आहूय सोऽङ्गदं कोपात्ताडयामास वेगितः।
गदया कम्पनः पूर्वं स चचाल भृशाहतः॥', 'āhūya so ''ṅgadaṃ kopāt tāḍayām āsa vegitaḥ
gadayā kampanaḥ pūrvaṃ sa cacāla bhṛśāhataḥ', null, 6063002),
('ramayana-6-63-3', 3, 'Yuddha Kanda, Sarga 63, Verse 3', 'स संज्ञां प्राप्य तेजस्वी चिक्षेप शिखरं गिरेः।
अर्दितश्च प्रहारेण कम्पनः पतितो भुवि॥', 'sa saṃjñāṃ prāpya tejasvī cikṣepa śikharaṃ gireḥ
arditaś ca prahāreṇa kampanaḥ patito bhuvi', null, 6063003),
('ramayana-6-63-4', 4, 'Yuddha Kanda, Sarga 63, Verse 4', 'हतप्रवीरा व्यथिता राक्षसेन्द्रचमूस्तदा।
जगामाभिमुखी सा तु कुम्भकर्णसुतो यतः।
आपतन्तीं च वेगेन कुम्भस्तां सान्त्वयच्चमूम्॥', 'hatapravīrā vyathitā rākṣasendracamūs tadā
jagāmābhimukhī sā tu kumbhakarṇasuto yataḥ
āpatantīṃ ca vegena kumbhas tāṃ sāntvayac camūm', null, 6063004),
('ramayana-6-63-5', 5, 'Yuddha Kanda, Sarga 63, Verse 5', 'स धनुर्धन्विनां श्रेष्ठः प्रगृह्य सुसमाहितः।
मुमोचाशीविषप्रख्याञ्शरान्देहविदारणान्॥', 'sa dhanur dhanvināṃ śreṣṭhaḥ pragṛhya susamāhitaḥ
mumocāśīviṣaprakhyāñ śarān dehavidāraṇān', null, 6063005),
('ramayana-6-63-6', 6, 'Yuddha Kanda, Sarga 63, Verse 6', 'तस्य तच्छुशुभे भूयः सशरं धनुरुत्तमम्।
विद्युदैरावतार्चिष्मद्द्वितीयेन्द्रधनुर्यथा॥', 'tasya tac chuśubhe bhūyaḥ saśaraṃ dhanur uttamam
vidyudairāvatārciṣmad dvitīyendradhanur yathā', null, 6063006),
('ramayana-6-63-7', 7, 'Yuddha Kanda, Sarga 63, Verse 7', 'आकर्णकृष्टमुक्तेन जघान द्विविदं तदा।
तेन हाटकपुङ्खेन पत्रिणा पत्रवाससा॥', 'ākarṇakṛṣṭamuktena jaghāna dvividaṃ tadā
tena hāṭakapuṅkhena patriṇā patravāsasā', null, 6063007),
('ramayana-6-63-8', 8, 'Yuddha Kanda, Sarga 63, Verse 8', 'सहसाभिहतस्तेन विप्रमुक्तपदः स्फुरन्।
निपपाताद्रिकूटाभो विह्वलः प्लवगोत्तमः॥', 'sahasābhihatas tena vipramuktapadaḥ sphuran
nipapātādrikūṭābho vihvalaḥ plavagottamaḥ', null, 6063008),
('ramayana-6-63-9', 9, 'Yuddha Kanda, Sarga 63, Verse 9', 'मैन्दस्तु भ्रातरं दृष्ट्वा भग्नं तत्र महाहवे।
अभिदुद्राव वेगेन प्रगृह्य महतीं शिलाम्॥', 'maindas tu bhrātaraṃ dṛṣṭvā bhagnaṃ tatra mahāhave
abhidudrāva vegena pragṛhya mahatīṃ śilām', null, 6063009),
('ramayana-6-63-10', 10, 'Yuddha Kanda, Sarga 63, Verse 10', 'तां शिलां तु प्रचिक्षेप राक्षसाय महाबलः।
बिभेद तां शिलां कुम्भः प्रसन्नैः पञ्चभिः शरैः॥', 'tāṃ śilāṃ tu pracikṣepa rākṣasāya mahābalaḥ
bibheda tāṃ śilāṃ kumbhaḥ prasannaiḥ pañcabhiḥ śaraiḥ', null, 6063010),
('ramayana-6-63-11', 11, 'Yuddha Kanda, Sarga 63, Verse 11', 'संधाय चान्यं सुमुखं शरमाशीविषोपमम्।
आजघान महातेजा वक्षसि द्विविदाग्रजम्॥', 'saṃdhāya cānyaṃ sumukhaṃ śaram āśīviṣopamam
ājaghāna mahātejā vakṣasi dvividāgrajam', null, 6063011),
('ramayana-6-63-12', 12, 'Yuddha Kanda, Sarga 63, Verse 12', 'स तु तेन प्रहारेण मैन्दो वानरयूथपः।
मर्मण्यभिहतस्तेन पपात भुवि मूर्छितः॥', 'sa tu tena prahāreṇa maindo vānarayūthapaḥ
marmaṇy abhihatas tena papāta bhuvi mūrchitaḥ', null, 6063012),
('ramayana-6-63-13', 13, 'Yuddha Kanda, Sarga 63, Verse 13', 'अङ्गदो मातुलौ दृष्ट्वा पतितौ तौ महाबलौ।
अभिदुद्राव वेगेन कुम्भमुद्यतकार्मुकम्॥', 'aṅgado mātulau dṛṣṭvā patitau tau mahābalau
abhidudrāva vegena kumbham udyatakārmukam', null, 6063013),
('ramayana-6-63-14', 14, 'Yuddha Kanda, Sarga 63, Verse 14', 'तमापतन्तं विव्याध कुम्भः पञ्चभिरायसैः।
त्रिभिश्चान्यैः शितैर्बाणैर्मातंगमिव तोमरैः॥', 'tam āpatantaṃ vivyādha kumbhaḥ pañcabhir āyasaiḥ
tribhiś cānyaiḥ śitair bāṇair mātaṃgam iva tomaraiḥ', null, 6063014),
('ramayana-6-63-15', 15, 'Yuddha Kanda, Sarga 63, Verse 15', 'सोऽङ्गदं विविधैर्बाणैः कुम्भो विव्याध वीर्यवान्।
अकुण्ठधारैर्निशितैस्तीक्ष्णैः कनकभूषणैः॥', 'so ''ṅgadaṃ vividhair bāṇaiḥ kumbho vivyādha vīryavān
akuṇṭhadhārair niśitais tīkṣṇaiḥ kanakabhūṣaṇaiḥ', null, 6063015),
('ramayana-6-63-16', 16, 'Yuddha Kanda, Sarga 63, Verse 16', 'अङ्गदः प्रतिविद्धाङ्गो वालिपुत्रो न कम्पते।
शिलापादपवर्षाणि तस्य मूर्ध्नि ववर्ष ह॥', 'aṅgadaḥ pratividdhāṅgo vāliputro na kampate
śilāpādapavarṣāṇi tasya mūrdhni vavarṣa ha', null, 6063016),
('ramayana-6-63-17', 17, 'Yuddha Kanda, Sarga 63, Verse 17', 'स प्रचिच्छेद तान्सर्वान्बिभेद च पुनः शिलाः।
कुम्भकर्णात्मजः श्रीमान्वालिपुत्रसमीरितान्॥', 'sa praciccheda tān sarvān bibheda ca punaḥ śilāḥ
kumbhakarṇātmajaḥ śrīmān vāliputrasamīritān', null, 6063017),
('ramayana-6-63-18', 18, 'Yuddha Kanda, Sarga 63, Verse 18', 'आपतन्तं च संप्रेक्ष्य कुम्भो वानरयूथपम्।
भ्रुवोर्विव्याध बाणाभ्यामुल्काभ्यामिव कुञ्जरम्॥', 'āpatantaṃ ca saṃprekṣya kumbho vānarayūthapam
bhruvor vivyādha bāṇābhyām ulkābhyām iva kuñjaram', null, 6063018),
('ramayana-6-63-19', 19, 'Yuddha Kanda, Sarga 63, Verse 19', 'अङ्गदः पाणिना नेत्रे पिधाय रुधिरोक्षिते।
सालमासन्नमेकेन परिजग्राह पाणिना॥', 'aṅgadaḥ pāṇinā netre pidhāya rudhirokṣite
sālam āsannam ekena parijagrāha pāṇinā', null, 6063019),
('ramayana-6-63-20', 20, 'Yuddha Kanda, Sarga 63, Verse 20', 'तमिन्द्रकेतुप्रतिमं वृक्षं मन्दरसंनिभम्।
समुत्सृजन्तं वेगेन पश्यतां सर्वरक्षसाम्॥', 'tam indraketupratimaṃ vṛkṣaṃ mandarasaṃnibham
samutsṛjantaṃ vegena paśyatāṃ sarvarakṣasām', null, 6063020),
('ramayana-6-63-21', 21, 'Yuddha Kanda, Sarga 63, Verse 21', 'स चिच्छेद शितैर्बाणैः सप्तभिः कायभेदनैः।
अङ्गदो विव्यथेऽभीक्ष्णं ससाद च मुमोह च॥', 'sa ciccheda śitair bāṇaiḥ saptabhiḥ kāyabhedanaiḥ
aṅgado vivyathe ''bhīkṣṇaṃ sasāda ca mumoha ca', null, 6063021),
('ramayana-6-63-22', 22, 'Yuddha Kanda, Sarga 63, Verse 22', 'अङ्गदं व्यथितं दृष्ट्वा सीदन्तमिव सागरे।
दुरासदं हरिश्रेष्ठा राघवाय न्यवेदयन्॥', 'aṅgadaṃ vyathitaṃ dṛṣṭvā sīdantam iva sāgare
durāsadaṃ hariśreṣṭhā rāghavāya nyavedayan', null, 6063022),
('ramayana-6-63-23', 23, 'Yuddha Kanda, Sarga 63, Verse 23', 'रामस्तु व्यथितं श्रुत्वा वालिपुत्रं महाहवे।
व्यादिदेश हरिश्रेष्ठाञ्जाम्बवत्प्रमुखांस्ततः॥', 'rāmas tu vyathitaṃ śrutvā vāliputraṃ mahāhave
vyādideśa hariśreṣṭhāñ jāmbavatpramukhāṃs tataḥ', null, 6063023),
('ramayana-6-63-24', 24, 'Yuddha Kanda, Sarga 63, Verse 24', 'ते तु वानरशार्दूलाः श्रुत्वा रामस्य शासनम्।
अभिपेतुः सुसंक्रुद्धाः कुम्भमुद्यतकार्मुकम्॥', 'te tu vānaraśārdūlāḥ śrutvā rāmasya śāsanam
abhipetuḥ susaṃkruddhāḥ kumbham udyatakārmukam', null, 6063024),
('ramayana-6-63-25', 25, 'Yuddha Kanda, Sarga 63, Verse 25', 'ततो द्रुमशिलाहस्ताः कोपसंरक्तलोचनाः।
रिरक्षिषन्तोऽभ्यपतन्नङ्गदं वानरर्षभाः॥', 'tato drumaśilāhastāḥ kopasaṃraktalocanāḥ
rirakṣiṣanto ''bhyapatann aṅgadaṃ vānararṣabhāḥ', null, 6063025),
('ramayana-6-63-26', 26, 'Yuddha Kanda, Sarga 63, Verse 26', 'जाम्बवांश्च सुषेणश्च वेगदर्शी च वानरः।
कुम्भकर्णात्मजं वीरं क्रुद्धाः समभिदुद्रुवुः॥', 'jāmbavāṃś ca suṣeṇaś ca vegadarśī ca vānaraḥ
kumbhakarṇātmajaṃ vīraṃ kruddhāḥ samabhidudruvuḥ', null, 6063026),
('ramayana-6-63-27', 27, 'Yuddha Kanda, Sarga 63, Verse 27', 'समीक्ष्यातततस्तांस्तु वानरेन्द्रान्महाबलान्।
आववार शरौघेण नगेनेव जलाशयम्॥', 'samīkṣyātatatas tāṃs tu vānarendrān mahābalān
āvavāra śaraugheṇa nageneva jalāśayam', null, 6063027),
('ramayana-6-63-28', 28, 'Yuddha Kanda, Sarga 63, Verse 28', 'तस्य बाणचयं प्राप्य न शोकेरतिवर्तितुम्।
वानरेन्द्रा महात्मानो वेलामिव महोदधिः॥', 'tasya bāṇacayaṃ prāpya na śoker ativartitum
vānarendrā mahātmāno velām iva mahodadhiḥ', null, 6063028),
('ramayana-6-63-29', 29, 'Yuddha Kanda, Sarga 63, Verse 29', 'तांस्तु दृष्ट्वा हरिगणाञ्शरवृष्टिभिरर्दितान्।
अङ्गदं पृष्ठतः कृत्वा भ्रातृजं प्लवगेश्वरः॥', 'tāṃs tu dṛṣṭvā harigaṇāñ śaravṛṣṭibhir arditān
aṅgadaṃ pṛṣṭhataḥ kṛtvā bhrātṛjaṃ plavageśvaraḥ', null, 6063029),
('ramayana-6-63-30', 30, 'Yuddha Kanda, Sarga 63, Verse 30', 'अभिदुद्राव वेगेन सुग्रीवः कुम्भमाहवे।
शैलसानु चरं नागं वेगवानिव केसरी॥', 'abhidudrāva vegena sugrīvaḥ kumbham āhave
śailasānu caraṃ nāgaṃ vegavān iva kesarī', null, 6063030),
('ramayana-6-63-31', 31, 'Yuddha Kanda, Sarga 63, Verse 31', 'उत्पाट्य च महाशैलानश्वकर्णान्धवान्बहून्।
अन्यांश्च विविधान्वृक्षांश्चिक्षेप च महाबलः॥', 'utpāṭya ca mahāśailān aśvakarṇān dhavān bahūn
anyāṃś ca vividhān vṛkṣāṃś cikṣepa ca mahābalaḥ', null, 6063031),
('ramayana-6-63-32', 32, 'Yuddha Kanda, Sarga 63, Verse 32', 'तां छादयन्तीमाकाशं वृक्षवृष्टिं दुरासदाम्।
कुम्भकर्णात्मजः श्रीमांश्चिच्छेद निशितैः शरैः॥', 'tāṃ chādayantīm ākāśaṃ vṛkṣavṛṣṭiṃ durāsadām
kumbhakarṇātmajaḥ śrīmāṃś ciccheda niśitaiḥ śaraiḥ', null, 6063032),
('ramayana-6-63-33', 33, 'Yuddha Kanda, Sarga 63, Verse 33', 'अभिलक्ष्येण तीव्रेण कुम्भेन निशितैः शरैः।
आचितास्ते द्रुमा रेजुर्यथा घोराः शतघ्नयः॥', 'abhilakṣyeṇa tīvreṇa kumbhena niśitaiḥ śaraiḥ
ācitās te drumā rejur yathā ghorāḥ śataghnayaḥ', null, 6063033),
('ramayana-6-63-34', 34, 'Yuddha Kanda, Sarga 63, Verse 34', 'द्रुमवर्षं तु तच्छिन्नं दृष्ट्वा कुम्भेन वीर्यवान्।
वानराधिपतिः श्रीमान्महासत्त्वो न विव्यथे॥', 'drumavarṣaṃ tu tac chinnaṃ dṛṣṭvā kumbhena vīryavān
vānarādhipatiḥ śrīmān mahāsattvo na vivyathe', null, 6063034),
('ramayana-6-63-35', 35, 'Yuddha Kanda, Sarga 63, Verse 35', 'निर्भिद्यमानः सहसा सहमानश्च ताञ्शरान्।
कुम्भस्य धनुराक्षिप्य बभञ्जेन्द्रधनुःप्रभम्॥', 'nirbhidyamānaḥ sahasā sahamānaś ca tāñ śarān
kumbhasya dhanur ākṣipya babhañjendradhanuḥprabham', null, 6063035),
('ramayana-6-63-36', 36, 'Yuddha Kanda, Sarga 63, Verse 36', 'अवप्लुत्य ततः शीघ्रं कृत्वा कर्म सुदुष्करम्।
अब्रवीत्कुपितः कुम्भं भग्नशृङ्गमिव द्विपम्॥', 'avaplutya tataḥ śīghraṃ kṛtvā karma suduṣkaram
abravīt kupitaḥ kumbhaṃ bhagnaśṛṅgam iva dvipam', null, 6063036),
('ramayana-6-63-37', 37, 'Yuddha Kanda, Sarga 63, Verse 37', 'निकुम्भाग्रज वीर्यं ते बाणवेगं तदद्भुतम्।
संनतिश्च प्रभावश्च तव वा रावणस्य वा॥', 'nikumbhāgraja vīryaṃ te bāṇavegaṃ tad adbhutam
saṃnatiś ca prabhāvaś ca tava vā rāvaṇasya vā', null, 6063037),
('ramayana-6-63-38', 38, 'Yuddha Kanda, Sarga 63, Verse 38', 'प्रह्रादबलिवृत्रघ्नकुबेरवरुणोपम।
एकस्त्वमनुजातोऽसि पितरं बलवत्तरः॥', 'prahrādabalivṛtraghnakuberavaruṇopama
ekas tvam anujāto ''si pitaraṃ balavattaraḥ', null, 6063038),
('ramayana-6-63-39', 39, 'Yuddha Kanda, Sarga 63, Verse 39', 'त्वामेवैकं महाबाहुं शूलहस्तमरिंदमम्।
त्रिदशा नातिवर्तन्ते जितेन्द्रियमिवाधयः॥', 'tvām evaikaṃ mahābāhuṃ śūlahastam ariṃdamam
tridaśā nātivartante jitendriyam ivādhayaḥ', null, 6063039),
('ramayana-6-63-40', 40, 'Yuddha Kanda, Sarga 63, Verse 40', 'वरदानात्पितृव्यस्ते सहते देवदानवान्।
कुम्भकर्णस्तु वीर्येण सहते च सुरासुरान्॥', 'varadānāt pitṛvyas te sahate devadānavān
kumbhakarṇas tu vīryeṇa sahate ca surāsurān', null, 6063040),
('ramayana-6-63-41', 41, 'Yuddha Kanda, Sarga 63, Verse 41', 'धनुषीन्द्रजितस्तुल्यः प्रतापे रावणस्य च।
त्वमद्य रक्षसां लोके श्रेष्ठोऽसि बलवीर्यतः॥', 'dhanuṣīndrajitas tulyaḥ pratāpe rāvaṇasya ca
tvam adya rakṣasāṃ loke śreṣṭho ''si balavīryataḥ', null, 6063041),
('ramayana-6-63-42', 42, 'Yuddha Kanda, Sarga 63, Verse 42', 'महाविमर्दं समरे मया सह तवाद्भुतम्।
अद्य भूतानि पश्यन्तु शक्रशम्बरयोरिव॥', 'mahāvimardaṃ samare mayā saha tavādbhutam
adya bhūtāni paśyantu śakraśambarayor iva', null, 6063042),
('ramayana-6-63-43', 43, 'Yuddha Kanda, Sarga 63, Verse 43', 'कृतमप्रतिमं कर्म दर्शितं चास्त्रकौशलम्।
पातिता हरिवीराश्च त्वयैते भीमविक्रमाः॥', 'kṛtam apratimaṃ karma darśitaṃ cāstrakauśalam
pātitā harivīrāś ca tvayaite bhīmavikramāḥ', null, 6063043),
('ramayana-6-63-44', 44, 'Yuddha Kanda, Sarga 63, Verse 44', 'उपालम्भभयाच्चापि नासि वीर मया हतः।
कृतकर्मा परिश्रान्तो विश्रान्तः पश्य मे बलम्॥', 'upālambhabhayāc cāpi nāsi vīra mayā hataḥ
kṛtakarmā pariśrānto viśrāntaḥ paśya me balam', null, 6063044),
('ramayana-6-63-45', 45, 'Yuddha Kanda, Sarga 63, Verse 45', 'तेन सुग्रीववाक्येन सावमानेन मानितः।
अग्नेराज्यहुतस्येव तेजस्तस्याभ्यवर्धत॥', 'tena sugrīvavākyena sāvamānena mānitaḥ
agner ājyahutasyeva tejas tasyābhyavardhata', null, 6063045),
('ramayana-6-63-46', 46, 'Yuddha Kanda, Sarga 63, Verse 46', 'ततः कुम्भः समुत्पत्य सुग्रीवमभिपद्य च।
आजघानोरसि क्रुद्धो वज्रवेगेन मुष्टिना॥', 'tataḥ kumbhaḥ samutpatya sugrīvam abhipadya ca
ājaghānorasi kruddho vajravegena muṣṭinā', null, 6063046),
('ramayana-6-63-47', 47, 'Yuddha Kanda, Sarga 63, Verse 47', 'तस्य चर्म च पुस्फोट संजज्ञे चास्य शोणितम्।
स च मुष्टिर्महावेगः प्रतिजघ्नेऽस्थिमण्डले॥', 'tasya carma ca pusphoṭa saṃjajñe cāsya śoṇitam
sa ca muṣṭir mahāvegaḥ pratijaghne ''sthimaṇḍale', null, 6063047),
('ramayana-6-63-48', 48, 'Yuddha Kanda, Sarga 63, Verse 48', 'तदा वेगेन तत्रासीत्तेजः प्रज्वालितं मुहुः।
वज्रनिष्पेषसंजातज्वाला मेरौ यथा गिरौ॥', 'tadā vegena tatrāsīt tejaḥ prajvālitaṃ muhuḥ
vajraniṣpeṣasaṃjātajvālā merau yathā girau', null, 6063048),
('ramayana-6-63-49', 49, 'Yuddha Kanda, Sarga 63, Verse 49', 'स तत्राभिहतस्तेन सुग्रीवो वानरर्षभः।
मुष्टिं संवर्तयामास वज्रकल्पं महाबलः॥', 'sa tatrābhihatas tena sugrīvo vānararṣabhaḥ
muṣṭiṃ saṃvartayām āsa vajrakalpaṃ mahābalaḥ', null, 6063049),
('ramayana-6-63-50', 50, 'Yuddha Kanda, Sarga 63, Verse 50', 'अर्चिःसहस्रविकचं रविमण्डलसप्रभम्।
स मुष्टिं पातयामास कुम्भस्योरसि वीर्यवान्॥', 'arciḥsahasravikacaṃ ravimaṇḍalasaprabham
sa muṣṭiṃ pātayām āsa kumbhasyorasi vīryavān', null, 6063050),
('ramayana-6-63-51', 51, 'Yuddha Kanda, Sarga 63, Verse 51', 'मुष्टिनाभिहतस्तेन निपपाताशु राक्षसः।
लोहिताङ्ग इवाकाशाद्दीप्तरश्मिर्यदृच्छया॥', 'muṣṭinābhihatas tena nipapātāśu rākṣasaḥ
lohitāṅga ivākāśād dīptaraśmir yadṛcchayā', null, 6063051),
('ramayana-6-63-52', 52, 'Yuddha Kanda, Sarga 63, Verse 52', 'कुम्भस्य पततो रूपं भग्नस्योरसि मुष्टिना।
बभौ रुद्राभिपन्नस्य यथारूपं गवां पतेः॥', 'kumbhasya patato rūpaṃ bhagnasyorasi muṣṭinā
babhau rudrābhipannasya yathārūpaṃ gavāṃ pateḥ', null, 6063052),
('ramayana-6-63-53', 53, 'Yuddha Kanda, Sarga 63, Verse 53', 'तस्मिन्हते भीमपराक्रमेण प्लवंगमानामृषभेण युद्धे।
मही सशैला सवना चचाल भयं च रक्षांस्यधिकं विवेश॥', 'tasmin hate bhīmaparākrameṇa plavaṃgamānām ṛṣabheṇa yuddhe
mahī saśailā savanā cacāla bhayaṃ ca rakṣāṃsy adhikaṃ viveśa', null, 6063053)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 64 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-64-1', 1, 'Yuddha Kanda, Sarga 64, Verse 1', 'निकुम्भो भ्रातरं दृष्ट्वा सुग्रीवेण निपातितम्।
प्रदहन्निव कोपेन वानरेन्द्रमवैक्षत॥', 'nikumbho bhrātaraṃ dṛṣṭvā sugrīveṇa nipātitam
pradahann iva kopena vānarendram avaikṣata', null, 6064001),
('ramayana-6-64-2', 2, 'Yuddha Kanda, Sarga 64, Verse 2', 'ततः स्रग्दामसंनद्धं दत्तपञ्चाङ्गुलं शुभम्।
आददे परिघं वीरो नगेन्द्रशिखरोपमम्॥', 'tataḥ sragdāmasaṃnaddhaṃ dattapañcāṅgulaṃ śubham
ādade parighaṃ vīro nagendraśikharopamam', null, 6064002),
('ramayana-6-64-3', 3, 'Yuddha Kanda, Sarga 64, Verse 3', 'हेमपट्टपरिक्षिप्तं वज्रविद्रुमभूषितम्।
यमदण्डोपमं भीमं रक्षसां भयनाशनम्॥', 'hemapaṭṭaparikṣiptaṃ vajravidrumabhūṣitam
yamadaṇḍopamaṃ bhīmaṃ rakṣasāṃ bhayanāśanam', null, 6064003),
('ramayana-6-64-4', 4, 'Yuddha Kanda, Sarga 64, Verse 4', 'तमाविध्य महातेजाः शक्रध्वजसमं रणे।
विननाद विवृत्तास्यो निकुम्भो भीमविक्रमः॥', 'tam āvidhya mahātejāḥ śakradhvajasamaṃ raṇe
vinanāda vivṛttāsyo nikumbho bhīmavikramaḥ', null, 6064004),
('ramayana-6-64-5', 5, 'Yuddha Kanda, Sarga 64, Verse 5', 'उरोगतेन निष्केण भुजस्थैरङ्गदैरपि।
कुण्डलाभ्यां च मृष्टाभ्यां मालया च विचित्रया॥', 'urogatena niṣkeṇa bhujasthair aṅgadair api
kuṇḍalābhyāṃ ca mṛṣṭābhyāṃ mālayā ca vicitrayā', null, 6064005),
('ramayana-6-64-6', 6, 'Yuddha Kanda, Sarga 64, Verse 6', 'निकुम्भो भूषणैर्भाति तेन स्म परिघेण च।
यथेन्द्रधनुषा मेघः सविद्युत्स्तनयित्नुमान्॥', 'nikumbho bhūṣaṇair bhāti tena sma parigheṇa ca
yathendradhanuṣā meghaḥ savidyutstanayitnumān', null, 6064006),
('ramayana-6-64-7', 7, 'Yuddha Kanda, Sarga 64, Verse 7', 'परिघाग्रेण पुस्फोट वातग्रन्थिर्महात्मनः।
प्रजज्वाल सघोषश्च विधूम इव पावकः॥', 'parighāgreṇa pusphoṭa vātagranthir mahātmanaḥ
prajajvāla saghoṣaś ca vidhūma iva pāvakaḥ', null, 6064007),
('ramayana-6-64-8', 8, 'Yuddha Kanda, Sarga 64, Verse 8', 'नगर्या विटपावत्या गन्धर्वभवनोत्तमैः।
सह चैवामरावत्या सर्वैश्च भवनैः सह॥', 'nagaryā viṭapāvatyā gandharvabhavanottamaiḥ
saha caivāmarāvatyā sarvaiś ca bhavanaiḥ saha', null, 6064008),
('ramayana-6-64-9', 9, 'Yuddha Kanda, Sarga 64, Verse 9', 'सतारागणनक्षत्रं सचन्द्रं समहाग्रहम्।
निकुम्भपरिघाघूर्णं भ्रमतीव नभस्तलम्॥', 'satārāgaṇanakṣatraṃ sacandraṃ samahāgraham
nikumbhaparighāghūrṇaṃ bhramatīva nabhastalam', null, 6064009),
('ramayana-6-64-10', 10, 'Yuddha Kanda, Sarga 64, Verse 10', 'दुरासदश्च संजज्ञे परिघाभरणप्रभः।
क्रोधेन्धनो निकुम्भाग्निर्युगान्ताग्निरिवोत्थितः॥', 'durāsadaś ca saṃjajñe parighābharaṇaprabhaḥ
krodhendhano nikumbhāgnir yugāntāgnir ivotthitaḥ', null, 6064010),
('ramayana-6-64-11', 11, 'Yuddha Kanda, Sarga 64, Verse 11', 'राक्षसा वानराश्चापि न शेकुः स्पन्दितुं भयात्।
हनूमंस्तु विवृत्योरस्तस्थौ प्रमुखतो बली॥', 'rākṣasā vānarāś cāpi na śekuḥ spandituṃ bhayāt
hanūmaṃs tu vivṛtyoras tasthau pramukhato balī', null, 6064011),
('ramayana-6-64-12', 12, 'Yuddha Kanda, Sarga 64, Verse 12', 'परिघोपमबाहुस्तु परिघं भास्करप्रभम्।
बली बलवतस्तस्य पातयामास वक्षसि॥', 'parighopamabāhus tu parighaṃ bhāskaraprabham
balī balavatas tasya pātayām āsa vakṣasi', null, 6064012),
('ramayana-6-64-13', 13, 'Yuddha Kanda, Sarga 64, Verse 13', 'स्थिरे तस्योरसि व्यूढे परिघः शतधा कृतः।
विशीर्यमाणः सहसा उल्का शतमिवाम्बरे॥', 'sthire tasyorasi vyūḍhe parighaḥ śatadhā kṛtaḥ
viśīryamāṇaḥ sahasā ulkā śatam ivāmbare', null, 6064013),
('ramayana-6-64-14', 14, 'Yuddha Kanda, Sarga 64, Verse 14', 'स तु तेन प्रहारेण चचाल च महाकपिः।
परिघेण समाधूतो यथा भूमिचलेऽचलः॥', 'sa tu tena prahāreṇa cacāla ca mahākapiḥ
parigheṇa samādhūto yathā bhūmicale ''calaḥ', null, 6064014),
('ramayana-6-64-15', 15, 'Yuddha Kanda, Sarga 64, Verse 15', 'स तथाभिहतस्तेन हनूमान्प्लवगोत्तमः।
मुष्टिं संवर्तयामास बलेनातिमहाबलः॥', 'sa tathābhihatas tena hanūmān plavagottamaḥ
muṣṭiṃ saṃvartayām āsa balenātimahābalaḥ', null, 6064015),
('ramayana-6-64-16', 16, 'Yuddha Kanda, Sarga 64, Verse 16', 'तमुद्यम्य महातेजा निकुम्भोरसि वीर्यवान्।
अभिचिक्षेप वेगेन वेगवान्वायुविक्रमः॥', 'tam udyamya mahātejā nikumbhorasi vīryavān
abhicikṣepa vegena vegavān vāyuvikramaḥ', null, 6064016),
('ramayana-6-64-17', 17, 'Yuddha Kanda, Sarga 64, Verse 17', 'ततः पुस्फोट चर्मास्य प्रसुस्राव च शोणितम्।
मुष्टिना तेन संजज्ञे ज्वाला विद्युदिवोत्थिता॥', 'tataḥ pusphoṭa carmāsya prasusrāva ca śoṇitam
muṣṭinā tena saṃjajñe jvālā vidyud ivotthitā', null, 6064017),
('ramayana-6-64-18', 18, 'Yuddha Kanda, Sarga 64, Verse 18', 'स तु तेन प्रहारेण निकुम्भो विचचाल ह।
स्वस्थश्चापि निजग्राह हनूमन्तं महाबलम्॥', 'sa tu tena prahāreṇa nikumbho vicacāla ha
svasthaś cāpi nijagrāha hanūmantaṃ mahābalam', null, 6064018),
('ramayana-6-64-19', 19, 'Yuddha Kanda, Sarga 64, Verse 19', 'विचुक्रुशुस्तदा संख्ये भीमं लङ्कानिवासिनः।
निकुम्भेनोद्धृतं दृष्ट्वा हनूमन्तं महाबलम्॥', 'vicukruśus tadā saṃkhye bhīmaṃ laṅkānivāsinaḥ
nikumbhenoddhṛtaṃ dṛṣṭvā hanūmantaṃ mahābalam', null, 6064019),
('ramayana-6-64-20', 20, 'Yuddha Kanda, Sarga 64, Verse 20', 'स तथा ह्रियमाणोऽपि कुम्भकर्णात्मजेन हि।
आजघानानिलसुतो वज्रवेगेन मुष्टिना॥', 'sa tathā hriyamāṇo ''pi kumbhakarṇātmajena hi
ājaghānānilasuto vajravegena muṣṭinā', null, 6064020),
('ramayana-6-64-21', 21, 'Yuddha Kanda, Sarga 64, Verse 21', 'आत्मानं मोचयित्वाथ क्षितावभ्यवपद्यत।
हनूमानुन्ममथाशु निकुम्भं मारुतात्मजः॥', 'ātmānaṃ mocayitvātha kṣitāv abhyavapadyata
hanūmān unmamathāśu nikumbhaṃ mārutātmajaḥ', null, 6064021),
('ramayana-6-64-22', 22, 'Yuddha Kanda, Sarga 64, Verse 22', 'निक्षिप्य परमायत्तो निकुम्भं निष्पिपेष च।
उत्पत्य चास्य वेगेन पपातोरसि वीर्यवान्॥', 'nikṣipya paramāyatto nikumbhaṃ niṣpipeṣa ca
utpatya cāsya vegena papātorasi vīryavān', null, 6064022),
('ramayana-6-64-23', 23, 'Yuddha Kanda, Sarga 64, Verse 23', 'परिगृह्य च बाहुभ्यां परिवृत्य शिरोधराम्।
उत्पाटयामास शिरो भैरवं नदतो महत्॥', 'parigṛhya ca bāhubhyāṃ parivṛtya śirodharām
utpāṭayām āsa śiro bhairavaṃ nadato mahat', null, 6064023),
('ramayana-6-64-24', 24, 'Yuddha Kanda, Sarga 64, Verse 24', 'अथ विनदति सादिते निकुम्भे पवनसुतेन रणे बभूव युद्धम्।
दशरथसुतराक्षसेन्द्रचम्वोर्भृशतरमागतरोषयोः सुभीमम्॥', 'atha vinadati sādite nikumbhe pavanasutena raṇe babhūva yuddham
daśarathasutarākṣasendracamvor bhṛśataram āgataroṣayoḥ subhīmam', null, 6064024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 65 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-65-1', 1, 'Yuddha Kanda, Sarga 65, Verse 1', 'निकुम्भं च हतं श्रुत्वा कुम्भं च विनिपातितम्।
रावणः परमामर्षी प्रजज्वालानलो यथा॥', 'nikumbhaṃ ca hataṃ śrutvā kumbhaṃ ca vinipātitam
rāvaṇaḥ paramāmarṣī prajajvālānalo yathā', null, 6065001),
('ramayana-6-65-2', 2, 'Yuddha Kanda, Sarga 65, Verse 2', 'नैरृतः क्रोधशोकाभ्यां द्वाभ्यां तु परिमूर्छितः।
खरपुत्रं विशालाक्षं मकराक्षमचोदयत्॥', 'nairṛtaḥ krodhaśokābhyāṃ dvābhyāṃ tu parimūrchitaḥ
kharaputraṃ viśālākṣaṃ makarākṣam acodayat', null, 6065002),
('ramayana-6-65-3', 3, 'Yuddha Kanda, Sarga 65, Verse 3', 'गच्छ पुत्र मयाज्ञप्तो बलेनाभिसमन्वितः।
राघवं लक्ष्मणं चैव जहि तौ सवनौकसौ॥', 'gaccha putra mayājñapto balenābhisamanvitaḥ
rāghavaṃ lakṣmaṇaṃ caiva jahi tau savanaukasau', null, 6065003),
('ramayana-6-65-4', 4, 'Yuddha Kanda, Sarga 65, Verse 4', 'रावणस्य वचः श्रुत्वा शूरो मानी खरात्मजः।
बाढमित्यब्रवीद्धृष्टो मकराक्षो निशाचरः॥', 'rāvaṇasya vacaḥ śrutvā śūro mānī kharātmajaḥ
bāḍham ity abravīd dhṛṣṭo makarākṣo niśācaraḥ', null, 6065004),
('ramayana-6-65-5', 5, 'Yuddha Kanda, Sarga 65, Verse 5', 'सोऽभिवाद्य दशग्रीवं कृत्वा चापि प्रदक्षिणम्।
निर्जगाम गृहाच्छुभ्राद्रावणस्याज्ञया बली॥', 'so ''bhivādya daśagrīvaṃ kṛtvā cāpi pradakṣiṇam
nirjagāma gṛhāc chubhrād rāvaṇasyājñayā balī', null, 6065005),
('ramayana-6-65-6', 6, 'Yuddha Kanda, Sarga 65, Verse 6', 'समीपस्थं बलाध्यक्षं खरपुत्रोऽब्रवीदिदम्।
रथमानीयतां शीघ्रं सैन्यं चानीयतां त्वरात्॥', 'samīpasthaṃ balādhyakṣaṃ kharaputro ''bravīd idam
ratham ānīyatāṃ śīghraṃ sainyaṃ cānīyatāṃ tvarāt', null, 6065006),
('ramayana-6-65-7', 7, 'Yuddha Kanda, Sarga 65, Verse 7', 'तस्य तद्वचनं श्रुत्वा बलाध्यक्षो निशाचरः।
स्यन्दनं च बलं चैव समीपं प्रत्यपादयत्॥', 'tasya tad vacanaṃ śrutvā balādhyakṣo niśācaraḥ
syandanaṃ ca balaṃ caiva samīpaṃ pratyapādayat', null, 6065007),
('ramayana-6-65-8', 8, 'Yuddha Kanda, Sarga 65, Verse 8', 'प्रदक्षिणं रथं कृत्वा आरुरोह निशाचरः।
सूतं संचोदयामास शीघ्रं मे रथमावह॥', 'pradakṣiṇaṃ rathaṃ kṛtvā āruroha niśācaraḥ
sūtaṃ saṃcodayām āsa śīghraṃ me ratham āvaha', null, 6065008),
('ramayana-6-65-9', 9, 'Yuddha Kanda, Sarga 65, Verse 9', 'अथ तान्राक्षसान्सर्वान्मकराक्षोऽब्रवीदिदम्।
यूयं सर्वे प्रयुध्यध्वं पुरस्तान्मम राक्षसाः॥', 'atha tān rākṣasān sarvān makarākṣo ''bravīd idam
yūyaṃ sarve prayudhyadhvaṃ purastān mama rākṣasāḥ', null, 6065009),
('ramayana-6-65-10', 10, 'Yuddha Kanda, Sarga 65, Verse 10', 'अहं राक्षसराजेन रावणेन महात्मना।
आज्ञप्तः समरे हन्तुं तावुभौ रामलक्ष्मणौ॥', 'ahaṃ rākṣasarājena rāvaṇena mahātmanā
ājñaptaḥ samare hantuṃ tāv ubhau rāmalakṣmaṇau', null, 6065010),
('ramayana-6-65-11', 11, 'Yuddha Kanda, Sarga 65, Verse 11', 'अद्य रामं वधिष्यामि लक्ष्मणं च निशाचराः।
शाखामृगं च सुग्रीवं वानरांश्च शरोत्तमैः॥', 'adya rāmaṃ vadhiṣyāmi lakṣmaṇaṃ ca niśācarāḥ
śākhāmṛgaṃ ca sugrīvaṃ vānarāṃś ca śarottamaiḥ', null, 6065011),
('ramayana-6-65-12', 12, 'Yuddha Kanda, Sarga 65, Verse 12', 'अद्य शूलनिपातैश्च वानराणां महाचमूम्।
प्रदहिष्यामि संप्राप्तां शुष्केन्धनमिवानलः॥', 'adya śūlanipātaiś ca vānarāṇāṃ mahācamūm
pradahiṣyāmi saṃprāptāṃ śuṣkendhanam ivānalaḥ', null, 6065012),
('ramayana-6-65-13', 13, 'Yuddha Kanda, Sarga 65, Verse 13', 'मकराक्षस्य तच्छ्रुत्वा वचनं ते निशाचराः।
सर्वे नानायुधोपेता बलवन्तः समाहिताः॥', 'makarākṣasya tac chrutvā vacanaṃ te niśācarāḥ
sarve nānāyudhopetā balavantaḥ samāhitāḥ', null, 6065013),
('ramayana-6-65-14', 14, 'Yuddha Kanda, Sarga 65, Verse 14', 'ते कामरूपिणः शूरा दंष्ट्रिणः पिङ्गलेक्षणाः।
मातंगा इव नर्दन्तो ध्वस्तकेशा भयानकाः॥', 'te kāmarūpiṇaḥ śūrā daṃṣṭriṇaḥ piṅgalekṣaṇāḥ
mātaṃgā iva nardanto dhvastakeśā bhayānakāḥ', null, 6065014),
('ramayana-6-65-15', 15, 'Yuddha Kanda, Sarga 65, Verse 15', 'परिवार्य महाकाया महाकायं खरात्मजम्।
अभिजग्मुस्तदा हृष्टाश्चालयन्तो वसुंधराम्॥', 'parivārya mahākāyā mahākāyaṃ kharātmajam
abhijagmus tadā hṛṣṭāś cālayanto vasuṃdharām', null, 6065015),
('ramayana-6-65-16', 16, 'Yuddha Kanda, Sarga 65, Verse 16', 'शङ्खभेरीसहस्राणामाहतानां समन्ततः।
क्ष्वेडितास्फोटितानां च ततः शब्दो महानभूत्॥', 'śaṅkhabherīsahasrāṇām āhatānāṃ samantataḥ
kṣveḍitāsphoṭitānāṃ ca tataḥ śabdo mahān abhūt', null, 6065016),
('ramayana-6-65-17', 17, 'Yuddha Kanda, Sarga 65, Verse 17', 'प्रभ्रष्टोऽथ करात्तस्य प्रतोदः सारथेस्तदा।
पपात सहसा चैव ध्वजस्तस्य च रक्षसः॥', 'prabhraṣṭo ''tha karāt tasya pratodaḥ sārathes tadā
papāta sahasā caiva dhvajas tasya ca rakṣasaḥ', null, 6065017),
('ramayana-6-65-18', 18, 'Yuddha Kanda, Sarga 65, Verse 18', 'तस्य ते रथसंयुक्ता हया विक्रमवर्जिताः।
चरणैराकुलैर्गत्वा दीनाः सास्रमुखा ययुः॥', 'tasya te rathasaṃyuktā hayā vikramavarjitāḥ
caraṇair ākulair gatvā dīnāḥ sāsramukhā yayuḥ', null, 6065018),
('ramayana-6-65-19', 19, 'Yuddha Kanda, Sarga 65, Verse 19', 'प्रवाति पवनस्तस्य सपांसुः खरदारुणः।
निर्याणे तस्य रौद्रस्य मकराक्षस्य दुर्मतेः॥', 'pravāti pavanas tasya sapāṃsuḥ kharadāruṇaḥ
niryāṇe tasya raudrasya makarākṣasya durmateḥ', null, 6065019),
('ramayana-6-65-20', 20, 'Yuddha Kanda, Sarga 65, Verse 20', 'तानि दृष्ट्वा निमित्तानि राक्षसा वीर्यवत्तमाः।
अचिन्त्यनिर्गताः सर्वे यत्र तौ रामलक्ष्मणौ॥', 'tāni dṛṣṭvā nimittāni rākṣasā vīryavattamāḥ
acintyanirgatāḥ sarve yatra tau rāmalakṣmaṇau', null, 6065020),
('ramayana-6-65-21', 21, 'Yuddha Kanda, Sarga 65, Verse 21', 'घनगजमहिषाङ्गतुल्यवर्णाः समरमुखेष्वसकृद्गदासिभिन्नाः।
अहमहमिति युद्धकौशलास्ते रजनिचराः परिबभ्रमुर्नदन्तः॥', 'ghanagajamahiṣāṅgatulyavarṇāḥ samaramukheṣv asakṛd gadāsibhinnāḥ
aham aham iti yuddhakauśalās te rajanicarāḥ paribabhramur nadantaḥ', null, 6065021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 66 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-66-1', 1, 'Yuddha Kanda, Sarga 66, Verse 1', 'निर्गतं मकराक्षं ते दृष्ट्वा वानरपुंगवाः।
आप्लुत्य सहसा सर्वे योद्धुकामा व्यवस्थिताः॥', 'nirgataṃ makarākṣaṃ te dṛṣṭvā vānarapuṃgavāḥ
āplutya sahasā sarve yoddhukāmā vyavasthitāḥ', null, 6066001),
('ramayana-6-66-2', 2, 'Yuddha Kanda, Sarga 66, Verse 2', 'ततः प्रवृत्तं सुमहत्तद्युद्धं लोमहर्षणम्।
निशाचरैः प्लवंगानां देवानां दानवैरिव॥', 'tataḥ pravṛttaṃ sumahat tad yuddhaṃ lomaharṣaṇam
niśācaraiḥ plavaṃgānāṃ devānāṃ dānavair iva', null, 6066002),
('ramayana-6-66-3', 3, 'Yuddha Kanda, Sarga 66, Verse 3', 'वृक्षशूलनिपातैश्च शिलापरिघपातनैः।
अन्योन्यं मर्दयन्ति स्म तदा कपिनिशाचराः॥', 'vṛkṣaśūlanipātaiś ca śilāparighapātanaiḥ
anyonyaṃ mardayanti sma tadā kapiniśācarāḥ', null, 6066003),
('ramayana-6-66-4', 4, 'Yuddha Kanda, Sarga 66, Verse 4', 'शक्तिशूलगदाखड्गैस्तोमरैश्च निशाचराः।
पट्टसैर्भिन्दिपालैश्च बाणपातैः समन्ततः॥', 'śaktiśūlagadākhaḍgais tomaraiś ca niśācarāḥ
paṭṭasair bhindipālaiś ca bāṇapātaiḥ samantataḥ', null, 6066004),
('ramayana-6-66-5', 5, 'Yuddha Kanda, Sarga 66, Verse 5', 'पाशमुद्गरदण्डैश्च निर्घातैश्चापरैस्तथा।
कदनं कपिसिंहानां चक्रुस्ते रजनीचराः॥', 'pāśamudgaradaṇḍaiś ca nirghātaiś cāparais tathā
kadanaṃ kapisiṃhānāṃ cakrus te rajanīcarāḥ', null, 6066005),
('ramayana-6-66-6', 6, 'Yuddha Kanda, Sarga 66, Verse 6', 'बाणौघैरर्दिताश्चापि खरपुत्रेण वानराः।
संभ्रान्तमनसः सर्वे दुद्रुवुर्भयपीडिताः॥', 'bāṇaughair arditāś cāpi kharaputreṇa vānarāḥ
saṃbhrāntamanasaḥ sarve dudruvur bhayapīḍitāḥ', null, 6066006),
('ramayana-6-66-7', 7, 'Yuddha Kanda, Sarga 66, Verse 7', 'तान्दृष्ट्वा राक्षसाः सर्वे द्रवमाणान्वनौकसः।
नेदुस्ते सिंहवद्धृष्टा राक्षसा जितकाशिनः॥', 'tān dṛṣṭvā rākṣasāḥ sarve dravamāṇān vanaukasaḥ
nedus te siṃhavad dhṛṣṭā rākṣasā jitakāśinaḥ', null, 6066007),
('ramayana-6-66-8', 8, 'Yuddha Kanda, Sarga 66, Verse 8', 'विद्रवत्सु तदा तेषु वानरेषु समन्ततः।
रामस्तान्वारयामास शरवर्षेण राक्षसान्॥', 'vidravatsu tadā teṣu vānareṣu samantataḥ
rāmas tān vārayām āsa śaravarṣeṇa rākṣasān', null, 6066008),
('ramayana-6-66-9', 9, 'Yuddha Kanda, Sarga 66, Verse 9', 'वारितान्राक्षसान्दृष्ट्वा मकराक्षो निशाचरः।
क्रोधानलसमाविष्टो वचनं चेदमब्रवीत्॥', 'vāritān rākṣasān dṛṣṭvā makarākṣo niśācaraḥ
krodhān alasam āviṣṭo vacanaṃ cedam abravīt', null, 6066009),
('ramayana-6-66-10', 10, 'Yuddha Kanda, Sarga 66, Verse 10', 'तिष्ठ राम मया सार्धं द्वन्द्वयुद्धं ददामि ते।
त्याजयिष्यामि ते प्राणान्धनुर्मुक्तैः शितैः शरैः॥', 'tiṣṭha rāma mayā sārdhaṃ dvandvayuddhaṃ dadāmi te
tyājayiṣyāmi te prāṇān dhanurmuktaiḥ śitaiḥ śaraiḥ', null, 6066010),
('ramayana-6-66-11', 11, 'Yuddha Kanda, Sarga 66, Verse 11', 'यत्तदा दण्डकारण्ये पितरं हतवान्मम।
मदग्रतः स्वकर्मस्थं स्मृत्वा रोषोऽभिवर्धते॥', 'yat tadā daṇḍakāraṇye pitaraṃ hatavān mama
madagrataḥ svakarmasthaṃ smṛtvā roṣo ''bhivardhate', null, 6066011),
('ramayana-6-66-12', 12, 'Yuddha Kanda, Sarga 66, Verse 12', 'दह्यन्ते भृशमङ्गानि दुरात्मन्मम राघव।
यन्मयासि न दृष्टस्त्वं तस्मिन्काले महावने॥', 'dahyante bhṛśam aṅgāni durātman mama rāghava
yan mayāsi na dṛṣṭas tvaṃ tasmin kāle mahāvane', null, 6066012),
('ramayana-6-66-13', 13, 'Yuddha Kanda, Sarga 66, Verse 13', 'दिष्ट्यासि दर्शनं राम मम त्वं प्राप्तवानिह।
काङ्क्षितोऽसि क्षुधार्तस्य सिंहस्येवेतरो मृगः॥', 'diṣṭyāsi darśanaṃ rāma mama tvaṃ prāptavān iha
kāṅkṣito ''si kṣudhārtasya siṃhasyevetaro mṛgaḥ', null, 6066013),
('ramayana-6-66-14', 14, 'Yuddha Kanda, Sarga 66, Verse 14', 'अद्य मद्बाणवेगेन प्रेतराड्विषयं गतः।
ये त्वया निहताः शूराः सह तैस्त्वं समेष्यसि॥', 'adya madbāṇavegena pretarāḍ viṣayaṃ gataḥ
ye tvayā nihatāḥ śūrāḥ saha tais tvaṃ sameṣyasi', null, 6066014),
('ramayana-6-66-15', 15, 'Yuddha Kanda, Sarga 66, Verse 15', 'बहुनात्र किमुक्तेन शृणु राम वचो मम।
पश्यन्तु सकला लोकास्त्वां मां चैव रणाजिरे॥', 'bahunātra kim uktena śṛṇu rāma vaco mama
paśyantu sakalā lokās tvāṃ māṃ caiva raṇājire', null, 6066015),
('ramayana-6-66-16', 16, 'Yuddha Kanda, Sarga 66, Verse 16', 'अस्त्रैर्वा गदया वापि बाहुभ्यां वा महाहवे।
अभ्यस्तं येन वा राम तेन वा वर्ततां युधि॥', 'astrair vā gadayā vāpi bāhubhyāṃ vā mahāhave
abhyastaṃ yena vā rāma tena vā vartatāṃ yudhi', null, 6066016),
('ramayana-6-66-17', 17, 'Yuddha Kanda, Sarga 66, Verse 17', 'मकराक्षवचः श्रुत्वा रामो दशरथात्मजः।
अब्रवीत्प्रहसन्वाक्यमुत्तरोत्तरवादिनम्॥', 'makarākṣavacaḥ śrutvā rāmo daśarathātmajaḥ
abravīt prahasan vākyam uttarottaravādinam', null, 6066017),
('ramayana-6-66-18', 18, 'Yuddha Kanda, Sarga 66, Verse 18', 'चतुर्दशसहस्राणि रक्षसां त्वत्पिता च यः।
त्रिशिरा दूषणश्चापि दण्डके निहता मया॥', 'caturdaśasahasrāṇi rakṣasāṃ tvatpitā ca yaḥ
triśirā dūṣaṇaś cāpi daṇḍake nihatā mayā', null, 6066018),
('ramayana-6-66-19', 19, 'Yuddha Kanda, Sarga 66, Verse 19', 'स्वाशितास्तव मांसेन गृध्रगोमायुवायसाः।
भविष्यन्त्यद्य वै पाप तीक्ष्णतुण्डनखाङ्कुशाः॥', 'svāśitās tava māṃsena gṛdhragomāyuvāyasāḥ
bhaviṣyanty adya vai pāpa tīkṣṇatuṇḍanakhāṅkuśāḥ', null, 6066019),
('ramayana-6-66-20', 20, 'Yuddha Kanda, Sarga 66, Verse 20', 'एवमुक्तस्तु रामेण खरपुत्रो निशाचरः।
बाणौघानसृजत्तस्मै राघवाय रणाजिरे॥', 'evam uktas tu rāmeṇa kharaputro niśācaraḥ
bāṇaughān asṛjat tasmai rāghavāya raṇājire', null, 6066020),
('ramayana-6-66-21', 21, 'Yuddha Kanda, Sarga 66, Verse 21', 'ताञ्शराञ्शरवर्षेण रामश्चिच्छेद नैकधा।
निपेतुर्भुवि ते छिन्ना रुक्मपुङ्खाः सहस्रशः॥', 'tāñ śarāñ śaravarṣeṇa rāmaś ciccheda naikadhā
nipetur bhuvi te chinnā rukmapuṅkhāḥ sahasraśaḥ', null, 6066021),
('ramayana-6-66-22', 22, 'Yuddha Kanda, Sarga 66, Verse 22', 'तद्युद्धमभवत्तत्र समेत्यान्योन्यमोजसा।
खर राक्षसपुत्रस्य सूनोर्दशरथस्य च॥', 'tad yuddham abhavat tatra sametyānyonyam ojasā
khara rākṣasaputrasya sūnor daśarathasya ca', null, 6066022),
('ramayana-6-66-23', 23, 'Yuddha Kanda, Sarga 66, Verse 23', 'जीमूतयोरिवाकाशे शब्दो ज्यातलयोस्तदा।
धनुर्मुक्तः स्वनोत्कृष्टः श्रूयते च रणाजिरे॥', 'jīmūtayor ivākāśe śabdo jyātalayos tadā
dhanur muktaḥ svanotkṛṣṭaḥ śrūyate ca raṇājire', null, 6066023),
('ramayana-6-66-24', 24, 'Yuddha Kanda, Sarga 66, Verse 24', 'देवदानवगन्धर्वाः किंनराश्च महोरगाः।
अन्तरिक्षगताः सर्वे द्रष्टुकामास्तदद्भुतम्॥', 'devadānavagandharvāḥ kiṃnarāś ca mahoragāḥ
antarikṣagatāḥ sarve draṣṭukāmās tad adbhutam', null, 6066024),
('ramayana-6-66-25', 25, 'Yuddha Kanda, Sarga 66, Verse 25', 'विद्धमन्योन्यगात्रेषु द्विगुणं वर्धते बलम्।
कृतप्रतिकृतान्योन्यं कुर्वाते तौ रणाजिरे॥', 'viddham anyonyagātreṣu dviguṇaṃ vardhate balam
kṛtapratikṛtānyonyaṃ kurvāte tau raṇājire', null, 6066025),
('ramayana-6-66-26', 26, 'Yuddha Kanda, Sarga 66, Verse 26', 'राममुक्तास्तु बाणौघान्राक्षसस्त्वच्छिनद्रणे।
रक्षोमुक्तांस्तु रामो वै नैकधा प्राच्छिनच्छरैः॥', 'rāmam uktās tu bāṇaughān rākṣasas tv acchinad raṇe
rakṣomuktāṃs tu rāmo vai naikadhā prācchinac charaiḥ', null, 6066026),
('ramayana-6-66-27', 27, 'Yuddha Kanda, Sarga 66, Verse 27', 'बाणौघवितताः सर्वा दिशश्च विदिशस्तथा।
संछन्ना वसुधा चैव समन्तान्न प्रकाशते॥', 'bāṇaughavitatāḥ sarvā diśaś ca vidiśas tathā
saṃchannā vasudhā caiva samantān na prakāśate', null, 6066027),
('ramayana-6-66-28', 28, 'Yuddha Kanda, Sarga 66, Verse 28', 'ततः क्रुद्धो महाबाहुर्धनुश्चिच्छेद रक्षसः।
अष्टाभिरथ नाराचैः सूतं विव्याध राघवः।
भित्त्वा शरै रथं रामो रथाश्वान्समपातयत्॥', 'tataḥ kruddho mahābāhur dhanuś ciccheda rakṣasaḥ
aṣṭābhir atha nārācaiḥ sūtaṃ vivyādha rāghavaḥ
bhittvā śarai rathaṃ rāmo rathāśvān samapātayat', null, 6066028),
('ramayana-6-66-29', 29, 'Yuddha Kanda, Sarga 66, Verse 29', 'विरथो वसुधां तिष्ठन्मकराक्षो निशाचरः।
अतिष्ठद्वसुधां रक्षः शूलं जग्राह पाणिना।
त्रासनं सर्वभूतानां युगान्ताग्निसमप्रभम्॥', 'viratho vasudhāṃ tiṣṭhan makarākṣo niśācaraḥ
atiṣṭhad vasudhāṃ rakṣaḥ śūlaṃ jagrāha pāṇinā
trāsanaṃ sarvabhūtānāṃ yugāntāgnisamaprabham', null, 6066029),
('ramayana-6-66-30', 30, 'Yuddha Kanda, Sarga 66, Verse 30', 'विभ्राम्य च महच्छूलं प्रज्वलन्तं निशाचरः।
स क्रोधात्प्राहिणोत्तस्मै राघवाय महाहवे॥', 'vibhrāmya ca mahac chūlaṃ prajvalantaṃ niśācaraḥ
sa krodhāt prāhiṇot tasmai rāghavāya mahāhave', null, 6066030),
('ramayana-6-66-31', 31, 'Yuddha Kanda, Sarga 66, Verse 31', 'तमापतन्तं ज्वलितं खरपुत्रकराच्च्युतम्।
बाणैस्तु त्रिभिराकाशे शूलं चिच्छेद राघवः॥', 'tam āpatantaṃ jvalitaṃ kharaputrakarāc cyutam
bāṇais tu tribhir ākāśe śūlaṃ ciccheda rāghavaḥ', null, 6066031),
('ramayana-6-66-32', 32, 'Yuddha Kanda, Sarga 66, Verse 32', 'सच्छिन्नो नैकधा शूलो दिव्यहाटकमण्डितः।
व्यशीर्यत महोक्लेव रामबाणार्दितो भुवि॥', 'sacchinno naikadhā śūlo divyahāṭakamaṇḍitaḥ
vyaśīryata mahokleva rāmabāṇārdito bhuvi', null, 6066032),
('ramayana-6-66-33', 33, 'Yuddha Kanda, Sarga 66, Verse 33', 'तच्छूलं निहतं दृष्ट्वा रामेणाद्भुतकर्मणा।
साधु साध्विति भूतानि व्याहरन्ति नभोगताः॥', 'tac chūlaṃ nihataṃ dṛṣṭvā rāmeṇādbhutakarmaṇā
sādhu sādhv iti bhūtāni vyāharanti nabhogatāḥ', null, 6066033),
('ramayana-6-66-34', 34, 'Yuddha Kanda, Sarga 66, Verse 34', 'तद्दृष्ट्वा निहतं शूलं मकराक्षो निशाचरः।
मुष्टिमुद्यम्य काकुत्स्थं तिष्ठ तिष्ठेति चाब्रवीत्॥', 'tad dṛṣṭvā nihataṃ śūlaṃ makarākṣo niśācaraḥ
muṣṭim udyamya kākutsthaṃ tiṣṭha tiṣṭheti cābravīt', null, 6066034),
('ramayana-6-66-35', 35, 'Yuddha Kanda, Sarga 66, Verse 35', 'स तं दृष्ट्वा पतन्तं वै प्रहस्य रघुनन्दनः।
पावकास्त्रं ततो रामः संदधे स्वशरासने॥', 'sa taṃ dṛṣṭvā patantaṃ vai prahasya raghunandanaḥ
pāvakāstraṃ tato rāmaḥ saṃdadhe svaśarāsane', null, 6066035),
('ramayana-6-66-36', 36, 'Yuddha Kanda, Sarga 66, Verse 36', 'तेनास्त्रेण हतं रक्षः काकुत्स्थेन तदा रणे।
संछिन्नहृदयं तत्र पपात च ममार च॥', 'tenāstreṇa hataṃ rakṣaḥ kākutsthena tadā raṇe
saṃchinnahṛdayaṃ tatra papāta ca mamāra ca', null, 6066036),
('ramayana-6-66-37', 37, 'Yuddha Kanda, Sarga 66, Verse 37', 'दृष्ट्वा ते राक्षसाः सर्वे मकराक्षस्य पातनम्।
लङ्कामेव प्रधावन्त रामबालार्दितास्तदा॥', 'dṛṣṭvā te rākṣasāḥ sarve makarākṣasya pātanam
laṅkām eva pradhāvanta rāmabālārditās tadā', null, 6066037),
('ramayana-6-66-38', 38, 'Yuddha Kanda, Sarga 66, Verse 38', 'दशरथनृपपुत्रबाणवेगै रजनिचरं निहतं खरात्मजं तम्।
ददृशुरथ च देवताः प्रहृष्टा गिरिमिव वज्रहतं यथा विशीर्णम्॥', 'daśarathanṛpaputrabāṇavegai rajanicaraṃ nihataṃ kharātmajaṃ tam
dadṛśur atha ca devatāḥ prahṛṣṭā girim iva vajrahataṃ yathā viśīrṇam', null, 6066038)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 67 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-67-1', 1, 'Yuddha Kanda, Sarga 67, Verse 1', 'मकराक्षं हतं श्रुत्वा रावणः समितिंजयः।
आदिदेशाथ संक्रुद्धो रणायेन्द्रजितं सुतम्॥', 'makarākṣaṃ hataṃ śrutvā rāvaṇaḥ samitiṃjayaḥ
ādideśātha saṃkruddho raṇāyendrajitaṃ sutam', null, 6067001),
('ramayana-6-67-2', 2, 'Yuddha Kanda, Sarga 67, Verse 2', 'जहि वीर महावीर्यौ भ्रातरौ रामलक्ष्मणौ।
अदृश्यो दृश्यमानो वा सर्वथा त्वं बलाधिकः॥', 'jahi vīra mahāvīryau bhrātarau rāmalakṣmaṇau
adṛśyo dṛśyamāno vā sarvathā tvaṃ balādhikaḥ', null, 6067002),
('ramayana-6-67-3', 3, 'Yuddha Kanda, Sarga 67, Verse 3', 'त्वमप्रतिमकर्माणमिन्द्रं जयसि संयुगे।
किं पुनर्मानुषौ दृष्ट्वा न वधिष्यसि संयुगे॥', 'tvam apratimakarmāṇam indraṃ jayasi saṃyuge
kiṃ punar mānuṣau dṛṣṭvā na vadhiṣyasi saṃyuge', null, 6067003),
('ramayana-6-67-4', 4, 'Yuddha Kanda, Sarga 67, Verse 4', 'तथोक्तो राक्षसेन्द्रेण प्रतिगृह्य पितुर्वचः।
यज्ञभूमौ स विधिवत्पावकं जुहुवे न्द्रजित्॥', 'tathokto rākṣasendreṇa pratigṛhya pitur vacaḥ
yajñabhūmau sa vidhivat pāvakaṃ juhuve ndrajit', null, 6067004),
('ramayana-6-67-5', 5, 'Yuddha Kanda, Sarga 67, Verse 5', 'जुह्वतश्चापि तत्राग्निं रक्तोष्णीषधराः स्त्रियः।
आजग्मुस्तत्र संभ्रान्ता राक्षस्यो यत्र रावणिः॥', 'juhvataś cāpi tatrāgniṃ raktoṣṇīṣadharāḥ striyaḥ
ājagmus tatra saṃbhrāntā rākṣasyo yatra rāvaṇiḥ', null, 6067005),
('ramayana-6-67-6', 6, 'Yuddha Kanda, Sarga 67, Verse 6', 'शस्त्राणि शरपत्राणि समिधोऽथ विभीतकाः।
लोहितानि च वासांसि स्रुवं कार्ष्णायसं तथा॥', 'śastrāṇi śarapatrāṇi samidho ''tha vibhītakāḥ
lohitāni ca vāsāṃsi sruvaṃ kārṣṇāyasaṃ tathā', null, 6067006),
('ramayana-6-67-7', 7, 'Yuddha Kanda, Sarga 67, Verse 7', 'सर्वतोऽग्निं समास्तीर्य शरपत्रैः समन्ततः।
छागस्य सर्वकृष्णस्य गलं जग्राह जीवतः॥', 'sarvato ''gniṃ samāstīrya śarapatraiḥ samantataḥ
chāgasya sarvakṛṣṇasya galaṃ jagrāha jīvataḥ', null, 6067007),
('ramayana-6-67-8', 8, 'Yuddha Kanda, Sarga 67, Verse 8', 'चरुहोमसमिद्धस्य विधूमस्य महार्चिषः।
बभूवुस्तानि लिङ्गानि विजयं दर्शयन्ति च॥', 'caruhomasamiddhasya vidhūmasya mahārciṣaḥ
babhūvus tāni liṅgāni vijayaṃ darśayanti ca', null, 6067008),
('ramayana-6-67-9', 9, 'Yuddha Kanda, Sarga 67, Verse 9', 'प्रदक्षिणावर्तशिखस्तप्तहाटकसंनिभः।
हविस्तत्प्रतिजग्राह पावकः स्वयमुत्थितः॥', 'pradakṣiṇāvartaśikhas taptahāṭakasaṃnibhaḥ
havis tat pratijagrāha pāvakaḥ svayam utthitaḥ', null, 6067009),
('ramayana-6-67-10', 10, 'Yuddha Kanda, Sarga 67, Verse 10', 'हुत्वाग्निं तर्पयित्वाथ देवदानवराक्षसान्।
आरुरोह रथश्रेष्ठमन्तर्धानगतं शुभम्॥', 'hutvāgniṃ tarpayitvātha devadānavarākṣasān
āruroha rathaśreṣṭham antardhānagataṃ śubham', null, 6067010),
('ramayana-6-67-11', 11, 'Yuddha Kanda, Sarga 67, Verse 11', 'स वाजिभिश्चतुर्भिस्तु बाणैश्च निशितैर्युतः।
आरोपितमहाचापः शुशुभे स्यन्दनोत्तमे॥', 'sa vājibhiś caturbhis tu bāṇaiś ca niśitair yutaḥ
āropitamahācāpaḥ śuśubhe syandanottame', null, 6067011),
('ramayana-6-67-12', 12, 'Yuddha Kanda, Sarga 67, Verse 12', 'जाज्वल्यमानो वपुषा तपनीयपरिच्छदः।
शरैश्चन्द्रार्धचन्द्रैश्च स रथः समलंकृतः॥', 'jājvalyamāno vapuṣā tapanīyaparicchadaḥ
śaraiś candrārdhacandraiś ca sa rathaḥ samalaṃkṛtaḥ', null, 6067012),
('ramayana-6-67-13', 13, 'Yuddha Kanda, Sarga 67, Verse 13', 'जाम्बूनदमहाकम्बुर्दीप्तपावकसंनिभः।
बभूवेन्द्रजितः केतुर्वैदूर्यसमलंकृतः॥', 'jāmbūnadamahākambur dīptapāvakasaṃnibhaḥ
babhūvendrajitaḥ ketur vaidūryasamalaṃkṛtaḥ', null, 6067013),
('ramayana-6-67-14', 14, 'Yuddha Kanda, Sarga 67, Verse 14', 'तेन चादित्यकल्पेन ब्रह्मास्त्रेण च पालितः।
स बभूव दुराधर्षो रावणिः सुमहाबलः॥', 'tena cādityakalpena brahmāstreṇa ca pālitaḥ
sa babhūva durādharṣo rāvaṇiḥ sumahābalaḥ', null, 6067014),
('ramayana-6-67-15', 15, 'Yuddha Kanda, Sarga 67, Verse 15', 'सोऽभिनिर्याय नगरादिन्द्रजित्समितिंजयः।
हुत्वाग्निं राक्षसैर्मन्त्रैरन्तर्धानगतोऽब्रवीत्॥', 'so ''bhiniryāya nagarād indrajit samitiṃjayaḥ
hutvāgniṃ rākṣasair mantrair antardhānagato ''bravīt', null, 6067015),
('ramayana-6-67-16', 16, 'Yuddha Kanda, Sarga 67, Verse 16', 'अद्य हत्वाहवे यौ तौ मिथ्या प्रव्रजितौ वने।
जयं पित्रे प्रदास्यामि रावणाय रणाधिकम्॥', 'adya hatvāhave yau tau mithyā pravrajitau vane
jayaṃ pitre pradāsyāmi rāvaṇāya raṇādhikam', null, 6067016),
('ramayana-6-67-17', 17, 'Yuddha Kanda, Sarga 67, Verse 17', 'कृत्वा निर्वानरामुर्वीं हत्वा रामं सलक्ष्मणम्।
करिष्ये परमां प्रीतिमित्युक्त्वान्तरधीयत॥', 'kṛtvā nirvānarām urvīṃ hatvā rāmaṃ salakṣmaṇam
kariṣye paramāṃ prītim ity uktvāntaradhīyata', null, 6067017),
('ramayana-6-67-18', 18, 'Yuddha Kanda, Sarga 67, Verse 18', 'आपपाताथ संक्रुद्धो दशग्रीवेण चोदितः।
तीक्ष्णकार्मुकनाराचैस्तीक्ष्णस्त्विन्द्ररिपू रणे॥', 'āpapātātha saṃkruddho daśagrīveṇa coditaḥ
tīkṣṇakārmukanārācais tīkṣṇas tv indraripū raṇe', null, 6067018),
('ramayana-6-67-19', 19, 'Yuddha Kanda, Sarga 67, Verse 19', 'स ददर्श महावीर्यौ नागौ त्रिशिरसाविव।
सृजन्ताविषुजालानि वीरौ वानरमध्यगौ॥', 'sa dadarśa mahāvīryau nāgau triśirasāv iva
sṛjantāv iṣujālāni vīrau vānaramadhyagau', null, 6067019),
('ramayana-6-67-20', 20, 'Yuddha Kanda, Sarga 67, Verse 20', 'इमौ ताविति संचिन्त्य सज्यं कृत्वा च कार्मुकम्।
संततानेषुधाराभिः पर्जन्य इव वृष्टिमान्॥', 'imau tāv iti saṃcintya sajyaṃ kṛtvā ca kārmukam
saṃtatāneṣudhārābhiḥ parjanya iva vṛṣṭimān', null, 6067020),
('ramayana-6-67-21', 21, 'Yuddha Kanda, Sarga 67, Verse 21', 'स तु वैहायसं प्राप्य सरथो रामलक्ष्मणौ।
अचक्षुर्विषये तिष्ठन्विव्याध निशितैः शरैः॥', 'sa tu vaihāyasaṃ prāpya saratho rāmalakṣmaṇau
acakṣur viṣaye tiṣṭhan vivyādha niśitaiḥ śaraiḥ', null, 6067021),
('ramayana-6-67-22', 22, 'Yuddha Kanda, Sarga 67, Verse 22', 'तौ तस्य शरवेगेन परीतौ रामलक्ष्मणौ।
धनुषी सशरे कृत्वा दिव्यमस्त्रं प्रचक्रतुः॥', 'tau tasya śaravegena parītau rāmalakṣmaṇau
dhanuṣī saśare kṛtvā divyam astraṃ pracakratuḥ', null, 6067022),
('ramayana-6-67-23', 23, 'Yuddha Kanda, Sarga 67, Verse 23', 'प्रच्छादयन्तौ गगनं शरजालैर्महाबलौ।
तमस्त्रैः सुरसंकाशौ नैव पस्पर्शतुः शरैः॥', 'pracchādayantau gaganaṃ śarajālair mahābalau
tam astraiḥ surasaṃkāśau naiva pasparśatuḥ śaraiḥ', null, 6067023),
('ramayana-6-67-24', 24, 'Yuddha Kanda, Sarga 67, Verse 24', 'स हि धूमान्धकारं च चक्रे प्रच्छादयन्नभः।
दिशश्चान्तर्दधे श्रीमान्नीहारतमसावृतः॥', 'sa hi dhūmāndhakāraṃ ca cakre pracchādayan nabhaḥ
diśaś cāntardadhe śrīmān nīhāratamasāvṛtaḥ', null, 6067024),
('ramayana-6-67-25', 25, 'Yuddha Kanda, Sarga 67, Verse 25', 'नैव ज्यातलनिर्घोषो न च नेमिखुरस्वनः।
शुश्रुवे चरतस्तस्य न च रूपं प्रकाशते॥', 'naiva jyātalanirghoṣo na ca nemikhurasvanaḥ
śuśruve caratas tasya na ca rūpaṃ prakāśate', null, 6067025),
('ramayana-6-67-26', 26, 'Yuddha Kanda, Sarga 67, Verse 26', 'घनान्धकारे तिमिरे शरवर्षमिवाद्भुतम्।
स ववर्ष महाबाहुर्नाराचशरवृष्टिभिः॥', 'ghanāndhakāre timire śaravarṣam ivādbhutam
sa vavarṣa mahābāhur nārācaśaravṛṣṭibhiḥ', null, 6067026),
('ramayana-6-67-27', 27, 'Yuddha Kanda, Sarga 67, Verse 27', 'स रामं सूर्यसंकाशैः शरैर्दत्तवरो भृशम्।
विव्याध समरे क्रुद्धः सर्वगात्रेषु रावणिः॥', 'sa rāmaṃ sūryasaṃkāśaiḥ śarair dattavaro bhṛśam
vivyādha samare kruddhaḥ sarvagātreṣu rāvaṇiḥ', null, 6067027),
('ramayana-6-67-28', 28, 'Yuddha Kanda, Sarga 67, Verse 28', 'तौ हन्यमानौ नाराचैर्धाराभिरिव पर्वतौ।
हेमपुङ्खान्नरव्याघ्रौ तिग्मान्मुमुचतुः शरान्॥', 'tau hanyamānau nārācair dhārābhir iva parvatau
hemapuṅkhān naravyāghrau tigmān mumucatuḥ śarān', null, 6067028),
('ramayana-6-67-29', 29, 'Yuddha Kanda, Sarga 67, Verse 29', 'अन्तरिक्षं समासाद्य रावणिं कङ्कपत्रिणः।
निकृत्य पतगा भूमौ पेतुस्ते शोणितोक्षिताः॥', 'antarikṣaṃ samāsādya rāvaṇiṃ kaṅkapatriṇaḥ
nikṛtya patagā bhūmau petus te śoṇitokṣitāḥ', null, 6067029),
('ramayana-6-67-30', 30, 'Yuddha Kanda, Sarga 67, Verse 30', 'अतिमात्रं शरौघेण पीड्यमानौ नरोत्तमौ।
तानिषून्पततो भल्लैरनेकैर्निचकर्ततुः॥', 'atimātraṃ śaraugheṇa pīḍyamānau narottamau
tān iṣūn patato bhallair anekair nicakartatuḥ', null, 6067030),
('ramayana-6-67-31', 31, 'Yuddha Kanda, Sarga 67, Verse 31', 'यतो हि ददृशाते तौ शरान्निपतिताञ्शितान्।
ततस्ततो दाशरथी ससृजातेऽस्त्रमुत्तमम्॥', 'yato hi dadṛśāte tau śarān nipatitāñ śitān
tatas tato dāśarathī sasṛjāte ''stram uttamam', null, 6067031),
('ramayana-6-67-32', 32, 'Yuddha Kanda, Sarga 67, Verse 32', 'रावणिस्तु दिशः सर्वा रथेनातिरथः पतन्।
विव्याध तौ दाशरथी लघ्वस्त्रो निशितैः शरैः॥', 'rāvaṇis tu diśaḥ sarvā rathenātirathaḥ patan
vivyādha tau dāśarathī laghv astro niśitaiḥ śaraiḥ', null, 6067032),
('ramayana-6-67-33', 33, 'Yuddha Kanda, Sarga 67, Verse 33', 'तेनातिविद्धौ तौ वीरौ रुक्मपुङ्खैः सुसंहतैः।
बभूवतुर्दाशरथी पुष्पिताविव किंशुकौ॥', 'tenātividdhau tau vīrau rukmapuṅkhaiḥ susaṃhataiḥ
babhūvatur dāśarathī puṣpitāv iva kiṃśukau', null, 6067033),
('ramayana-6-67-34', 34, 'Yuddha Kanda, Sarga 67, Verse 34', 'नास्य वेद गतिं कश्चिन्न च रूपं धनुः शरान्।
न चान्यद्विदितं किं चित्सूर्यस्येवाभ्रसंप्लवे॥', 'nāsya veda gatiṃ kaś cin na ca rūpaṃ dhanuḥ śarān
na cānyad viditaṃ kiṃ cit sūryasyevābhrasaṃplave', null, 6067034),
('ramayana-6-67-35', 35, 'Yuddha Kanda, Sarga 67, Verse 35', 'तेन विद्धाश्च हरयो निहताश्च गतासवः।
बभूवुः शतशस्तत्र पतिता धरणीतले॥', 'tena viddhāś ca harayo nihatāś ca gatāsavaḥ
babhūvuḥ śataśas tatra patitā dharaṇītale', null, 6067035),
('ramayana-6-67-36', 36, 'Yuddha Kanda, Sarga 67, Verse 36', 'लक्ष्मणस्तु सुसंक्रुद्धो भ्रातरं वाक्यमब्रवीत्।
ब्राह्ममस्त्रं प्रयोक्ष्यामि वधार्थं सर्वरक्षसाम्॥', 'lakṣmaṇas tu susaṃkruddho bhrātaraṃ vākyam abravīt
brāhmam astraṃ prayokṣyāmi vadhārthaṃ sarvarakṣasām', null, 6067036),
('ramayana-6-67-37', 37, 'Yuddha Kanda, Sarga 67, Verse 37', 'तमुवाच ततो रामो लक्ष्मणं शुभलक्षणम्।
नैकस्य हेतो रक्षांसि पृथिव्यां हन्तुमर्हसि॥', 'tam uvāca tato rāmo lakṣmaṇaṃ śubhalakṣaṇam
naikasya heto rakṣāṃsi pṛthivyāṃ hantum arhasi', null, 6067037),
('ramayana-6-67-38', 38, 'Yuddha Kanda, Sarga 67, Verse 38', 'अयुध्यमानं प्रच्छन्नं प्राञ्जलिं शरणागतम्।
पलायन्तं प्रमत्तं वा न त्वं हन्तुमिहार्हसि॥', 'ayudhyamānaṃ pracchannaṃ prāñjaliṃ śaraṇāgatam
palāyantaṃ pramattaṃ vā na tvaṃ hantum ihārhasi', null, 6067038),
('ramayana-6-67-39', 39, 'Yuddha Kanda, Sarga 67, Verse 39', 'अस्यैव तु वधे यत्नं करिष्यावो महाबल।
आदेक्ष्यावो महावेगानस्त्रानाशीविषोपमान्॥', 'asyaiva tu vadhe yatnaṃ kariṣyāvo mahābala
ādekṣyāvo mahāvegān astrān āśīviṣopamān', null, 6067039),
('ramayana-6-67-40', 40, 'Yuddha Kanda, Sarga 67, Verse 40', 'तमेनं मायिनं क्षुद्रमन्तर्हितरथं बलात्।
राक्षसं निहनिष्यन्ति दृष्ट्वा वानरयूथपाः॥', 'tam enaṃ māyinaṃ kṣudram antarhitarathaṃ balāt
rākṣasaṃ nihaniṣyanti dṛṣṭvā vānarayūthapāḥ', null, 6067040),
('ramayana-6-67-41', 41, 'Yuddha Kanda, Sarga 67, Verse 41', 'यद्येष भूमिं विशते दिवं वा रसातलं वापि नभस्तलं वा।
एवं निगूढोऽपि ममास्त्रदग्धः पतिष्यते भूमितले गतासुः॥', 'yady eṣa bhūmiṃ viśate divaṃ vā rasātalaṃ vāpi nabhastalaṃ vā
evaṃ nigūḍho ''pi mamāstradagdhaḥ patiṣyate bhūmitale gatāsuḥ', null, 6067041),
('ramayana-6-67-42', 42, 'Yuddha Kanda, Sarga 67, Verse 42', 'इत्येवमुक्त्वा वचनं महात्मा रघुप्रवीरः प्लवगर्षभैर्वृतः।
वधाय रौद्रस्य नृशंसकर्मणस्तदा महात्मा त्वरितं निरीक्षते॥', 'ity evam uktvā vacanaṃ mahātmā raghupravīraḥ plavagarṣabhair vṛtaḥ
vadhāya raudrasya nṛśaṃsakarmaṇas tadā mahātmā tvaritaṃ nirīkṣate', null, 6067042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 68 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-68-1', 1, 'Yuddha Kanda, Sarga 68, Verse 1', 'विज्ञाय तु मनस्तस्य राघवस्य महात्मनः।
संनिवृत्याहवात्तस्मात्प्रविवेश पुरं ततः॥', 'vijñāya tu manas tasya rāghavasya mahātmanaḥ
saṃnivṛtyāhavāt tasmāt praviveśa puraṃ tataḥ', null, 6068001),
('ramayana-6-68-2', 2, 'Yuddha Kanda, Sarga 68, Verse 2', 'सोऽनुस्मृत्य वधं तेषां राक्षसानां तरस्विनाम्।
क्रोधताम्रेक्षणः शूरो निर्जगाम महाद्युतिः॥', 'so ''nusmṛtya vadhaṃ teṣāṃ rākṣasānāṃ tarasvinām
krodhatāmrekṣaṇaḥ śūro nirjagāma mahādyutiḥ', null, 6068002),
('ramayana-6-68-3', 3, 'Yuddha Kanda, Sarga 68, Verse 3', 'स पश्चिमेन द्वारेण निर्ययौ राक्षसैर्वृतः।
इन्द्रजित्तु महावीर्यः पौलस्त्यो देवकण्टकः॥', 'sa paścimena dvāreṇa niryayau rākṣasair vṛtaḥ
indrajit tu mahāvīryaḥ paulastyo devakaṇṭakaḥ', null, 6068003),
('ramayana-6-68-4', 4, 'Yuddha Kanda, Sarga 68, Verse 4', 'इन्द्रजित्तु ततो दृष्ट्वा भ्रातरौ रामलक्ष्मणौ।
रणायाभ्युद्यतौ वीरौ मायां प्रादुष्करोत्तदा॥', 'indrajit tu tato dṛṣṭvā bhrātarau rāmalakṣmaṇau
raṇāyābhyudyatau vīrau māyāṃ prāduṣkarot tadā', null, 6068004),
('ramayana-6-68-5', 5, 'Yuddha Kanda, Sarga 68, Verse 5', 'इन्द्रजित्तु रथे स्थाप्य सीतां मायामयीं तदा।
बलेन महतावृत्य तस्या वधमरोचयत्॥', 'indrajit tu rathe sthāpya sītāṃ māyāmayīṃ tadā
balena mahatāvṛtya tasyā vadham arocayat', null, 6068005),
('ramayana-6-68-6', 6, 'Yuddha Kanda, Sarga 68, Verse 6', 'मोहनार्थं तु सर्वेषां बुद्धिं कृत्वा सुदुर्मतिः।
हन्तुं सीतां व्यवसितो वानराभिमुखो ययौ॥', 'mohanārthaṃ tu sarveṣāṃ buddhiṃ kṛtvā sudurmatiḥ
hantuṃ sītāṃ vyavasito vānarābhimukho yayau', null, 6068006),
('ramayana-6-68-7', 7, 'Yuddha Kanda, Sarga 68, Verse 7', 'तं दृष्ट्वा त्वभिनिर्यान्तं नगर्याः काननौकसः।
उत्पेतुरभिसंक्रुद्धाः शिलाहस्ता युयुत्सवः॥', 'taṃ dṛṣṭvā tv abhiniryāntaṃ nagaryāḥ kānanaukasaḥ
utpetur abhisaṃkruddhāḥ śilāhastā yuyutsavaḥ', null, 6068007),
('ramayana-6-68-8', 8, 'Yuddha Kanda, Sarga 68, Verse 8', 'हनूमान्पुरतस्तेषां जगाम कपिकुञ्जरः।
प्रगृह्य सुमहच्छृङ्गं पर्वतस्य दुरासदम्॥', 'hanūmān puratas teṣāṃ jagāma kapikuñjaraḥ
pragṛhya sumahac chṛṅgaṃ parvatasya durāsadam', null, 6068008),
('ramayana-6-68-9', 9, 'Yuddha Kanda, Sarga 68, Verse 9', 'स ददर्श हतानन्दां सीतामिन्द्रजितो रथे।
एकवेणीधरां दीनामुपवासकृशाननाम्॥', 'sa dadarśa hatānandāṃ sītām indrajito rathe
ekaveṇīdharāṃ dīnām upavāsakṛśānanām', null, 6068009),
('ramayana-6-68-10', 10, 'Yuddha Kanda, Sarga 68, Verse 10', 'परिक्लिष्टैकवसनाममृजां राघवप्रियाम्।
रजोमलाभ्यामालिप्तैः सर्वगात्रैर्वरस्त्रियम्॥', 'parikliṣṭaikavasanām amṛjāṃ rāghavapriyām
rajomalābhyām āliptaiḥ sarvagātrair varastriyam', null, 6068010),
('ramayana-6-68-11', 11, 'Yuddha Kanda, Sarga 68, Verse 11', 'तां निरीक्ष्य मुहूर्तं तु मैथिलीमध्यवस्य च।
बाष्पपर्याकुलमुखो हनूमान्व्यथितोऽभवत्॥', 'tāṃ nirīkṣya muhūrtaṃ tu maithilīm adhyavasya ca
bāṣpaparyākulamukho hanūmān vyathito ''bhavat', null, 6068011),
('ramayana-6-68-12', 12, 'Yuddha Kanda, Sarga 68, Verse 12', 'अब्रवीत्तां तु शोकार्तां निरानन्दां तपस्विनाम्।
दृष्ट्वा रथे स्तितां सीतां राक्षसेन्द्रसुताश्रिताम्॥', 'abravīt tāṃ tu śokārtāṃ nirānandāṃ tapasvinām
dṛṣṭvā rathe stitāṃ sītāṃ rākṣasendrasutāśritām', null, 6068012),
('ramayana-6-68-13', 13, 'Yuddha Kanda, Sarga 68, Verse 13', 'किं समर्थितमस्येति चिन्तयन्स महाकपिः।
सह तैर्वानरश्रेष्ठैरभ्यधावत रावणिम्॥', 'kiṃ samarthitam asyeti cintayan sa mahākapiḥ
saha tair vānaraśreṣṭhair abhyadhāvata rāvaṇim', null, 6068013),
('ramayana-6-68-14', 14, 'Yuddha Kanda, Sarga 68, Verse 14', 'तद्वानरबलं दृष्ट्वा रावणिः क्रोधमूर्छितः।
कृत्वा विशोकं निस्त्रिंशं मूर्ध्नि सीतां परामृशत्॥', 'tad vānarabalaṃ dṛṣṭvā rāvaṇiḥ krodhamūrchitaḥ
kṛtvā viśokaṃ nistriṃśaṃ mūrdhni sītāṃ parāmṛśat', null, 6068014),
('ramayana-6-68-15', 15, 'Yuddha Kanda, Sarga 68, Verse 15', 'तं स्त्रियं पश्यतां तेषां ताडयामास रावणिः।
क्रोशन्तीं राम रामेति मायया योजितां रथे॥', 'taṃ striyaṃ paśyatāṃ teṣāṃ tāḍayām āsa rāvaṇiḥ
krośantīṃ rāma rāmeti māyayā yojitāṃ rathe', null, 6068015),
('ramayana-6-68-16', 16, 'Yuddha Kanda, Sarga 68, Verse 16', 'गृहीतमूर्धजां दृष्ट्वा हनूमान्दैन्यमागतः।
दुःखजं वारिनेत्राभ्यामुत्सृजन्मारुतात्मजः।
अब्रवीत्परुषं वाक्यं क्रोधाद्रक्षोऽधिपात्मजम्॥', 'gṛhītamūrdhajāṃ dṛṣṭvā hanūmān dainyam āgataḥ
duḥkhajaṃ vārinetrābhyām utsṛjan mārutātmajaḥ
abravīt paruṣaṃ vākyaṃ krodhād rakṣo''dhipātmajam', null, 6068016),
('ramayana-6-68-17', 17, 'Yuddha Kanda, Sarga 68, Verse 17', 'दुरात्मन्नात्मनाशाय केशपक्षे परामृशः।
ब्रह्मर्षीणां कुले जातो राक्षसीं योनिमाश्रितः।
धिक्त्वां पापसमाचारं यस्य ते मतिरीदृशी॥', 'durātmann ātmanāśāya keśapakṣe parāmṛśaḥ
brahmarṣīṇāṃ kule jāto rākṣasīṃ yonim āśritaḥ
dhik tvāṃ pāpasamācāraṃ yasya te matir īdṛśī', null, 6068017),
('ramayana-6-68-18', 18, 'Yuddha Kanda, Sarga 68, Verse 18', 'नृशंसानार्य दुर्वृत्त क्षुद्र पापपराक्रम।
अनार्यस्येदृशं कर्म घृणा ते नास्ति निर्घृण॥', 'nṛśaṃsānārya durvṛtta kṣudra pāpaparākrama
anāryasyedṛśaṃ karma ghṛṇā te nāsti nirghṛṇa', null, 6068018),
('ramayana-6-68-19', 19, 'Yuddha Kanda, Sarga 68, Verse 19', 'च्युता गृहाच्च राज्याच्च रामहस्ताच्च मैथिली।
किं तवैषापराद्धा हि यदेनां हन्तुमिच्छसि॥', 'cyutā gṛhāc ca rājyāc ca rāmahastāc ca maithilī
kiṃ tavaiṣāparāddhā hi yad enāṃ hantum icchasi', null, 6068019),
('ramayana-6-68-20', 20, 'Yuddha Kanda, Sarga 68, Verse 20', 'सीतां च हत्वा न चिरं जीविष्यसि कथं चन।
वधार्हकर्मणानेन मम हस्तगतो ह्यसि॥', 'sītāṃ ca hatvā na ciraṃ jīviṣyasi kathaṃ cana
vadhārhakarmaṇānena mama hastagato hy asi', null, 6068020),
('ramayana-6-68-21', 21, 'Yuddha Kanda, Sarga 68, Verse 21', 'ये च स्त्रीघातिनां लोका लोकवध्यैश्च कुत्सिताः।
इह जीवितमुत्सृज्य प्रेत्य तान्प्रतिलप्स्यसे॥', 'ye ca strīghātināṃ lokā lokavadhyaiś ca kutsitāḥ
iha jīvitam utsṛjya pretya tān pratilapsyase', null, 6068021),
('ramayana-6-68-22', 22, 'Yuddha Kanda, Sarga 68, Verse 22', 'इति ब्रुवाणो हनुमान्सायुधैर्हरिभिर्वृतः।
अभ्यधावत संक्रुद्धो राक्षसेन्द्रसुतं प्रति॥', 'iti bruvāṇo hanumān sāyudhair haribhir vṛtaḥ
abhyadhāvata saṃkruddho rākṣasendrasutaṃ prati', null, 6068022),
('ramayana-6-68-23', 23, 'Yuddha Kanda, Sarga 68, Verse 23', 'आपतन्तं महावीर्यं तदनीकं वनौकसाम्।
रक्षसां भीमवेगानामनीकेन न्यवारयत्॥', 'āpatantaṃ mahāvīryaṃ tad anīkaṃ vanaukasām
rakṣasāṃ bhīmavegānām anīkena nyavārayat', null, 6068023),
('ramayana-6-68-24', 24, 'Yuddha Kanda, Sarga 68, Verse 24', 'स तां बाणसहस्रेण विक्षोभ्य हरिवाहिनीम्।
हरिश्रेष्ठं हनूमन्तमिन्द्रजित्प्रत्युवाच ह॥', 'sa tāṃ bāṇasahasreṇa vikṣobhya harivāhinīm
hariśreṣṭhaṃ hanūmantam indrajit pratyuvāca ha', null, 6068024),
('ramayana-6-68-25', 25, 'Yuddha Kanda, Sarga 68, Verse 25', 'सुग्रीवस्त्वं च रामश्च यन्निमित्तमिहागताः।
तां हनिष्यामि वैदेहीमद्यैव तव पश्यतः॥', 'sugrīvas tvaṃ ca rāmaś ca yannimittam ihāgatāḥ
tāṃ haniṣyāmi vaidehīm adyaiva tava paśyataḥ', null, 6068025),
('ramayana-6-68-26', 26, 'Yuddha Kanda, Sarga 68, Verse 26', 'इमां हत्वा ततो रामं लक्ष्मणं त्वां च वानर।
सुग्रीवं च वधिष्यामि तं चानार्यं विभीषणम्॥', 'imāṃ hatvā tato rāmaṃ lakṣmaṇaṃ tvāṃ ca vānara
sugrīvaṃ ca vadhiṣyāmi taṃ cānāryaṃ vibhīṣaṇam', null, 6068026),
('ramayana-6-68-27', 27, 'Yuddha Kanda, Sarga 68, Verse 27', 'न हन्तव्याः स्त्रियश्चेति यद्ब्रवीषि प्लवंगम।
पीडा करममित्राणां यत्स्यात्कर्तव्यमेत तत्॥', 'na hantavyāḥ striyaś ceti yad bravīṣi plavaṃgama
pīḍā karam amitrāṇāṃ yat syāt kartavyam eta tat', null, 6068027),
('ramayana-6-68-28', 28, 'Yuddha Kanda, Sarga 68, Verse 28', 'तमेवमुक्त्वा रुदतीं सीतां मायामयीं ततः।
शितधारेण खड्गेन निजघानेन्द्रजित्स्वयम्॥', 'tam evam uktvā rudatīṃ sītāṃ māyāmayīṃ tataḥ
śitadhāreṇa khaḍgena nijaghānendrajit svayam', null, 6068028),
('ramayana-6-68-29', 29, 'Yuddha Kanda, Sarga 68, Verse 29', 'यज्ञोपवीतमार्गेण छिन्ना तेन तपस्विनी।
सा पृथिव्यां पृथुश्रोणी पपात प्रियदर्शना॥', 'yajñopavītamārgeṇa chinnā tena tapasvinī
sā pṛthivyāṃ pṛthuśroṇī papāta priyadarśanā', null, 6068029),
('ramayana-6-68-30', 30, 'Yuddha Kanda, Sarga 68, Verse 30', 'तामिन्द्रजित्स्त्रियं हत्वा हनूमन्तमुवाच ह।
मया रामस्य पश्येमां कोपेन च निषूदिताम्॥', 'tām indrajitstriyaṃ hatvā hanūmantam uvāca ha
mayā rāmasya paśyemāṃ kopena ca niṣūditām', null, 6068030),
('ramayana-6-68-31', 31, 'Yuddha Kanda, Sarga 68, Verse 31', 'ततः खड्गेन महता हत्वा तामिन्द्रजित्स्वयम्।
हृष्टः स रथमास्थाय विननाद महास्वनम्॥', 'tataḥ khaḍgena mahatā hatvā tām indrajit svayam
hṛṣṭaḥ sa ratham āsthāya vinanāda mahāsvanam', null, 6068031),
('ramayana-6-68-32', 32, 'Yuddha Kanda, Sarga 68, Verse 32', 'वानराः शुश्रुवुः शब्दमदूरे प्रत्यवस्थिताः।
व्यादितास्यस्य नदतस्तद्दुर्गं संश्रितस्य तु॥', 'vānarāḥ śuśruvuḥ śabdam adūre pratyavasthitāḥ
vyāditāsyasya nadatas tad durgaṃ saṃśritasya tu', null, 6068032),
('ramayana-6-68-33', 33, 'Yuddha Kanda, Sarga 68, Verse 33', 'तथा तु सीतां विनिहत्य दुर्मतिः प्रहृष्टचेताः स बभूव रावणिः।
तं हृष्टरूपं समुदीक्ष्य वानरा विषण्णरूपाः समभिप्रदुद्रुवुः॥', 'tathā tu sītāṃ vinihatya durmatiḥ prahṛṣṭacetāḥ sa babhūva rāvaṇiḥ
taṃ hṛṣṭarūpaṃ samudīkṣya vānarā viṣaṇṇarūpāḥ samabhipradudruvuḥ', null, 6068033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 69 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-69-1', 1, 'Yuddha Kanda, Sarga 69, Verse 1', 'श्रुत्वा तं भीमनिर्ह्रादं शक्राशनिसमस्वनम्।
वीक्षमाणा दिशः सर्वा दुद्रुवुर्वानरर्षभाः॥', 'śrutvā taṃ bhīmanirhrādaṃ śakrāśanisamasvanam
vīkṣamāṇā diśaḥ sarvā dudruvur vānararṣabhāḥ', null, 6069001),
('ramayana-6-69-2', 2, 'Yuddha Kanda, Sarga 69, Verse 2', 'तानुवाच ततः सर्वान्हनूमान्मारुतात्मजः।
विषण्णवदनान्दीनांस्त्रस्तान्विद्रवतः पृथक्॥', 'tān uvāca tataḥ sarvān hanūmān mārutātmajaḥ
viṣaṇṇavadanān dīnāṃs trastān vidravataḥ pṛthak', null, 6069002),
('ramayana-6-69-3', 3, 'Yuddha Kanda, Sarga 69, Verse 3', 'कस्माद्विषण्णवदना विद्रवध्वं प्लवंगमाः।
त्यक्तयुद्धसमुत्साहाः शूरत्वं क्व नु वो गतम्॥', 'kasmād viṣaṇṇavadanā vidravadhvaṃ plavaṃgamāḥ
tyaktayuddhasamutsāhāḥ śūratvaṃ kva nu vo gatam', null, 6069003),
('ramayana-6-69-4', 4, 'Yuddha Kanda, Sarga 69, Verse 4', 'पृष्ठतोऽनुव्रजध्वं मामग्रतो यान्तमाहवे।
शूरैरभिजनोपेतैरयुक्तं हि निवर्तितुम्॥', 'pṛṣṭhato ''nuvrajadhvaṃ mām agrato yāntam āhave
śūrair abhijanopetair ayuktaṃ hi nivartitum', null, 6069004),
('ramayana-6-69-5', 5, 'Yuddha Kanda, Sarga 69, Verse 5', 'एवमुक्ताः सुसंक्रुद्धा वायुपुत्रेण धीमता।
शैलशृङ्गान्द्रुमांश्चैव जगृहुर्हृष्टमानसाः॥', 'evam uktāḥ susaṃkruddhā vāyuputreṇa dhīmatā
śailaśṛṅgān drumāṃś caiva jagṛhur hṛṣṭamānasāḥ', null, 6069005),
('ramayana-6-69-6', 6, 'Yuddha Kanda, Sarga 69, Verse 6', 'अभिपेतुश्च गर्जन्तो राक्षसान्वानरर्षभाः।
परिवार्य हनूमन्तमन्वयुश्च महाहवे॥', 'abhipetuś ca garjanto rākṣasān vānararṣabhāḥ
parivārya hanūmantam anvayuś ca mahāhave', null, 6069006),
('ramayana-6-69-7', 7, 'Yuddha Kanda, Sarga 69, Verse 7', 'स तैर्वानरमुख्यैस्तु हनूमान्सर्वतो वृतः।
हुताशन इवार्चिष्मानदहच्छत्रुवाहिनीम्॥', 'sa tair vānaramukhyais tu hanūmān sarvato vṛtaḥ
hutāśana ivārciṣmān adahac chatruvāhinīm', null, 6069007),
('ramayana-6-69-8', 8, 'Yuddha Kanda, Sarga 69, Verse 8', 'स राक्षसानां कदनं चकार सुमहाकपिः।
वृतो वानरसैन्येन कालान्तकयमोपमः॥', 'sa rākṣasānāṃ kadanaṃ cakāra sumahākapiḥ
vṛto vānarasainyena kālāntakayamopamaḥ', null, 6069008),
('ramayana-6-69-9', 9, 'Yuddha Kanda, Sarga 69, Verse 9', 'स तु शोकेन चाविष्टः क्रोधेन च महाकपिः।
हनूमान्रावणि रथे महतीं पातयच्छिलाम्॥', 'sa tu śokena cāviṣṭaḥ krodhena ca mahākapiḥ
hanūmān rāvaṇi rathe mahatīṃ pātayac chilām', null, 6069009),
('ramayana-6-69-10', 10, 'Yuddha Kanda, Sarga 69, Verse 10', 'तामापतन्तीं दृष्ट्वैव रथः सारथिना तदा।
विधेयाश्व समायुक्तः सुदूरमपवाहितः॥', 'tām āpatantīṃ dṛṣṭvaiva rathaḥ sārathinā tadā
vidheyāśva samāyuktaḥ sudūram apavāhitaḥ', null, 6069010),
('ramayana-6-69-11', 11, 'Yuddha Kanda, Sarga 69, Verse 11', 'तमिन्द्रजितमप्राप्य रथथं सहसारथिम्।
विवेश धरणीं भित्त्वा सा शिलाव्यर्थमुद्यता॥', 'tam indrajitam aprāpya rathathaṃ sahasārathim
viveśa dharaṇīṃ bhittvā sā śilāvyartham udyatā', null, 6069011),
('ramayana-6-69-12', 12, 'Yuddha Kanda, Sarga 69, Verse 12', 'पतितायां शिलायां तु रक्षसां व्यथिता चमूः।
तमभ्यधावञ्शतशो नदन्तः काननौकसः॥', 'patitāyāṃ śilāyāṃ tu rakṣasāṃ vyathitā camūḥ
tam abhyadhāvañ śataśo nadantaḥ kānanaukasaḥ', null, 6069012),
('ramayana-6-69-13', 13, 'Yuddha Kanda, Sarga 69, Verse 13', 'ते द्रुमांश्च महाकाया गिरिशृङ्गाणि चोद्यताः।
चिक्षिपुर्द्विषतां मध्ये वानरा भीमविक्रमाः॥', 'te drumāṃś ca mahākāyā giriśṛṅgāṇi codyatāḥ
cikṣipur dviṣatāṃ madhye vānarā bhīmavikramāḥ', null, 6069013),
('ramayana-6-69-14', 14, 'Yuddha Kanda, Sarga 69, Verse 14', 'वानरैर्तैर्महावीर्यैर्घोररूपा निशाचराः।
वीर्यादभिहता वृक्षैर्व्यवेष्टन्त रणक्षितौ॥', 'vānarair tair mahāvīryair ghorarūpā niśācarāḥ
vīryād abhihatā vṛkṣair vyaveṣṭanta raṇakṣitau', null, 6069014),
('ramayana-6-69-15', 15, 'Yuddha Kanda, Sarga 69, Verse 15', 'स्वसैन्यमभिवीक्ष्याथ वानरार्दितमिन्द्रजित्।
प्रगृहीतायुधः क्रुद्धः परानभिमुखो ययौ॥', 'svasainyam abhivīkṣyātha vānarārditam indrajit
pragṛhītāyudhaḥ kruddhaḥ parān abhimukho yayau', null, 6069015),
('ramayana-6-69-16', 16, 'Yuddha Kanda, Sarga 69, Verse 16', 'स शरौघानवसृजन्स्वसैन्येनाभिसंवृतः।
जघान कपिशार्दूलान्सुबहून्दृष्टविक्रमः॥', 'sa śaraughān avasṛjan svasainyenābhisaṃvṛtaḥ
jaghāna kapiśārdūlān subahūn dṛṣṭavikramaḥ', null, 6069016),
('ramayana-6-69-17', 17, 'Yuddha Kanda, Sarga 69, Verse 17', 'शूलैरशनिभिः खड्गैः पट्टसैः कूटमुद्गरैः।
ते चाप्यनुचरांस्तस्य वानरा जघ्नुराहवे॥', 'śūlair aśanibhiḥ khaḍgaiḥ paṭṭasaiḥ kūṭamudgaraiḥ
te cāpy anucarāṃs tasya vānarā jaghnur āhave', null, 6069017),
('ramayana-6-69-18', 18, 'Yuddha Kanda, Sarga 69, Verse 18', 'सस्कन्धविटपैः सालैः शिलाभिश्च महाबलैः।
हनूमान्कदनं चक्रे रक्षसां भीमकर्मणाम्॥', 'saskandhaviṭapaiḥ sālaiḥ śilābhiś ca mahābalaiḥ
hanūmān kadanaṃ cakre rakṣasāṃ bhīmakarmaṇām', null, 6069018),
('ramayana-6-69-19', 19, 'Yuddha Kanda, Sarga 69, Verse 19', 'स निवार्य परानीकमब्रवीत्तान्वनौकसः।
हनूमान्संनिवर्तध्वं न नः साध्यमिदं बलम्॥', 'sa nivārya parānīkam abravīt tān vanaukasaḥ
hanūmān saṃnivartadhvaṃ na naḥ sādhyam idaṃ balam', null, 6069019),
('ramayana-6-69-20', 20, 'Yuddha Kanda, Sarga 69, Verse 20', 'त्यक्त्वा प्राणान्विचेष्टन्तो राम प्रियचिकीर्षवः।
यन्निमित्तं हि युध्यामो हता सा जनकात्मजा॥', 'tyaktvā prāṇān viceṣṭanto rāma priyacikīrṣavaḥ
yannimittaṃ hi yudhyāmo hatā sā janakātmajā', null, 6069020),
('ramayana-6-69-21', 21, 'Yuddha Kanda, Sarga 69, Verse 21', 'इममर्थं हि विज्ञाप्य रामं सुग्रीवमेव च।
तौ यत्प्रतिविधास्येते तत्करिष्यामहे वयम्॥', 'imam arthaṃ hi vijñāpya rāmaṃ sugrīvam eva ca
tau yat pratividhāsyete tat kariṣyāmahe vayam', null, 6069021),
('ramayana-6-69-22', 22, 'Yuddha Kanda, Sarga 69, Verse 22', 'इत्युक्त्वा वानरश्रेष्ठो वारयन्सर्ववानरान्।
शनैः शनैरसंत्रस्तः सबलः स न्यवर्तत॥', 'ity uktvā vānaraśreṣṭho vārayan sarvavānarān
śanaiḥ śanair asaṃtrastaḥ sabalaḥ sa nyavartata', null, 6069022),
('ramayana-6-69-23', 23, 'Yuddha Kanda, Sarga 69, Verse 23', 'स तु प्रेक्ष्य हनूमन्तं व्रजन्तं यत्र राघवः।
निकुम्भिलामधिष्ठाय पावकं जुहुवे न्द्रजित्॥', 'sa tu prekṣya hanūmantaṃ vrajantaṃ yatra rāghavaḥ
nikumbhilām adhiṣṭhāya pāvakaṃ juhuve ndrajit', null, 6069023),
('ramayana-6-69-24', 24, 'Yuddha Kanda, Sarga 69, Verse 24', 'यज्ञभूम्यां तु विधिवत्पावकस्तेन रक्षसा।
हूयमानः प्रजज्वाल होमशोणितभुक्तदा॥', 'yajñabhūmyāṃ tu vidhivat pāvakas tena rakṣasā
hūyamānaḥ prajajvāla homaśoṇitabhuk tadā', null, 6069024),
('ramayana-6-69-25', 25, 'Yuddha Kanda, Sarga 69, Verse 25', 'सोऽर्चिः पिनद्धो ददृशे होमशोणिततर्पितः।
संध्यागत इवादित्यः स तीव्राग्निः समुत्थितः॥', 'so ''rciḥ pinaddho dadṛśe homaśoṇitatarpitaḥ
saṃdhyāgata ivādityaḥ sa tīvrāgniḥ samutthitaḥ', null, 6069025),
('ramayana-6-69-26', 26, 'Yuddha Kanda, Sarga 69, Verse 26', 'अथेन्द्रजिद्राक्षसभूतये तु जुहाव हव्यं विधिना विधानवत्।
दृष्ट्वा व्यतिष्ठन्त च राक्षसास्ते महासमूहेषु नयानयज्ञाः॥', 'athendrajid rākṣasabhūtaye tu juhāva havyaṃ vidhinā vidhānavat
dṛṣṭvā vyatiṣṭhanta ca rākṣasās te mahāsamūheṣu nayānayajñāḥ', null, 6069026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 70 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-70-1', 1, 'Yuddha Kanda, Sarga 70, Verse 1', 'राघवश्चापि विपुलं तं राक्षसवनौकसाम्।
श्रुत्वा संग्रामनिर्घोषं जाम्बवन्तमुवाच ह॥', 'rāghavaś cāpi vipulaṃ taṃ rākṣasavanaukasām
śrutvā saṃgrāmanirghoṣaṃ jāmbavantam uvāca ha', null, 6070001),
('ramayana-6-70-2', 2, 'Yuddha Kanda, Sarga 70, Verse 2', 'सौम्य नूनं हनुमता कृतं कर्म सुदुष्करम्।
श्रूयते हि यथा भीमः सुमहानायुधस्वनः॥', 'saumya nūnaṃ hanumatā kṛtaṃ karma suduṣkaram
śrūyate hi yathā bhīmaḥ sumahān āyudhasvanaḥ', null, 6070002),
('ramayana-6-70-3', 3, 'Yuddha Kanda, Sarga 70, Verse 3', 'तद्गच्छ कुरु साहाय्यं स्वबलेनाभिसंवृतः।
क्षिप्रमृष्कपते तस्य कपिश्रेष्ठस्य युध्यतः॥', 'tad gaccha kuru sāhāyyaṃ svabalenābhisaṃvṛtaḥ
kṣipram ṛṣkapate tasya kapiśreṣṭhasya yudhyataḥ', null, 6070003),
('ramayana-6-70-4', 4, 'Yuddha Kanda, Sarga 70, Verse 4', 'ऋक्षराजस्तथेत्युक्त्वा स्वेनानीकेन संवृतः।
आगच्छत्पश्चिमद्वारं हनूमान्यत्र वानरः॥', 'ṛkṣarājas tathety uktvā svenānīkena saṃvṛtaḥ
āgacchat paścimadvāraṃ hanūmān yatra vānaraḥ', null, 6070004),
('ramayana-6-70-5', 5, 'Yuddha Kanda, Sarga 70, Verse 5', 'अथायान्तं हनूमन्तं ददर्शर्क्षपतिः पथि।
वानरैः कृतसंग्रामैः श्वसद्भिरभिसंवृतम्॥', 'athāyāntaṃ hanūmantaṃ dadarśarkṣapatiḥ pathi
vānaraiḥ kṛtasaṃgrāmaiḥ śvasadbhir abhisaṃvṛtam', null, 6070005),
('ramayana-6-70-6', 6, 'Yuddha Kanda, Sarga 70, Verse 6', 'दृष्ट्वा पथि हनूमांश्च तदृष्कबलमुद्यतम्।
नीलमेघनिभं भीमं संनिवार्य न्यवर्तत॥', 'dṛṣṭvā pathi hanūmāṃś ca tad ṛṣkabalam udyatam
nīlameghanibhaṃ bhīmaṃ saṃnivārya nyavartata', null, 6070006),
('ramayana-6-70-7', 7, 'Yuddha Kanda, Sarga 70, Verse 7', 'स तेन हरिसैन्येन संनिकर्षं महायशाः।
शीघ्रमागम्य रामाय दुःखितो वाक्यमब्रवीत्॥', 'sa tena harisainyena saṃnikarṣaṃ mahāyaśāḥ
śīghram āgamya rāmāya duḥkhito vākyam abravīt', null, 6070007),
('ramayana-6-70-8', 8, 'Yuddha Kanda, Sarga 70, Verse 8', 'समरे युध्यमानानामस्माकं प्रेक्षतां च सः।
जघान रुदतीं सीतामिन्द्रजिद्रावणात्मजः॥', 'samare yudhyamānānām asmākaṃ prekṣatāṃ ca saḥ
jaghāna rudatīṃ sītām indrajid rāvaṇātmajaḥ', null, 6070008),
('ramayana-6-70-9', 9, 'Yuddha Kanda, Sarga 70, Verse 9', 'उद्भ्रान्तचित्तस्तां दृष्ट्वा विषण्णोऽहमरिंदम।
तदहं भवतो वृत्तं विज्ञापयितुमागतः॥', 'udbhrāntacittas tāṃ dṛṣṭvā viṣaṇṇo ''ham ariṃdama
tad ahaṃ bhavato vṛttaṃ vijñāpayitum āgataḥ', null, 6070009),
('ramayana-6-70-10', 10, 'Yuddha Kanda, Sarga 70, Verse 10', 'तस्य तद्वचनं श्रुत्वा राघवः शोकमूर्छितः।
निपपात तदा भूमौ छिन्नमूल इव द्रुमः॥', 'tasya tad vacanaṃ śrutvā rāghavaḥ śokamūrchitaḥ
nipapāta tadā bhūmau chinnamūla iva drumaḥ', null, 6070010),
('ramayana-6-70-11', 11, 'Yuddha Kanda, Sarga 70, Verse 11', 'तं भूमौ देवसंकाशं पतितं दृश्य राघवम्।
अभिपेतुः समुत्पत्य सर्वतः कपिसत्तमाः॥', 'taṃ bhūmau devasaṃkāśaṃ patitaṃ dṛśya rāghavam
abhipetuḥ samutpatya sarvataḥ kapisattamāḥ', null, 6070011),
('ramayana-6-70-12', 12, 'Yuddha Kanda, Sarga 70, Verse 12', 'असिञ्चन्सलिलैश्चैनं पद्मोत्पलसुगन्धिभिः।
प्रदहन्तमसह्यं च सहसाग्निमिवोत्थितम्॥', 'asiñcan salilaiś cainaṃ padmotpalasugandhibhiḥ
pradahantam asahyaṃ ca sahasāgnim ivotthitam', null, 6070012),
('ramayana-6-70-13', 13, 'Yuddha Kanda, Sarga 70, Verse 13', 'तं लक्ष्मणोऽथ बाहुभ्यां परिष्वज्य सुदुःखितः।
उवाच राममस्वस्थं वाक्यं हेत्वर्थसंहितम्॥', 'taṃ lakṣmaṇo ''tha bāhubhyāṃ pariṣvajya suduḥkhitaḥ
uvāca rāmam asvasthaṃ vākyaṃ hetvarthasaṃhitam', null, 6070013),
('ramayana-6-70-14', 14, 'Yuddha Kanda, Sarga 70, Verse 14', 'शुभे वर्त्मनि तिष्ठन्तं त्वामार्यविजितेन्द्रियम्।
अनर्थेभ्यो न शक्नोति त्रातुं धर्मो निरर्थकः॥', 'śubhe vartmani tiṣṭhantaṃ tvām āryavijitendriyam
anarthebhyo na śaknoti trātuṃ dharmo nirarthakaḥ', null, 6070014),
('ramayana-6-70-15', 15, 'Yuddha Kanda, Sarga 70, Verse 15', 'भूतानां स्थावराणां च जङ्गमानां च दर्शनम्।
यथास्ति न तथा धर्मस्तेन नास्तीति मे मतिः॥', 'bhūtānāṃ sthāvarāṇāṃ ca jaṅgamānāṃ ca darśanam
yathāsti na tathā dharmas tena nāstīti me matiḥ', null, 6070015),
('ramayana-6-70-16', 16, 'Yuddha Kanda, Sarga 70, Verse 16', 'यथैव स्थावरं व्यक्तं जङ्गमं च तथाविधम्।
नायमर्थस्तथा युक्तस्त्वद्विधो न विपद्यते॥', 'yathaiva sthāvaraṃ vyaktaṃ jaṅgamaṃ ca tathāvidham
nāyam arthas tathā yuktas tvadvidho na vipadyate', null, 6070016),
('ramayana-6-70-17', 17, 'Yuddha Kanda, Sarga 70, Verse 17', 'यद्यधर्मो भवेद्भूतो रावणो नरकं व्रजेत्।
भवांश्च धर्मसंयुक्तो नैवं व्यसनमाप्नुयात्॥', 'yady adharmo bhaved bhūto rāvaṇo narakaṃ vrajet
bhavāṃś ca dharmasaṃyukto naivaṃ vyasanam āpnuyāt', null, 6070017),
('ramayana-6-70-18', 18, 'Yuddha Kanda, Sarga 70, Verse 18', 'तस्य च व्यसनाभावाद्व्यसनं च गते त्वयि।
धर्मेणोपलभेद्धर्ममधर्मं चाप्यधर्मतः॥', 'tasya ca vyasanābhāvād vyasanaṃ ca gate tvayi
dharmeṇopalabhed dharmam adharmaṃ cāpy adharmataḥ', null, 6070018),
('ramayana-6-70-19', 19, 'Yuddha Kanda, Sarga 70, Verse 19', 'यदि धर्मेण युज्येरन्नाधर्मरुचयो जनाः।
धर्मेण चरतां धर्मस्तथा चैषां फलं भवेत्॥', 'yadi dharmeṇa yujyeran nādharmarucayo janāḥ
dharmeṇa caratāṃ dharmas tathā caiṣāṃ phalaṃ bhavet', null, 6070019),
('ramayana-6-70-20', 20, 'Yuddha Kanda, Sarga 70, Verse 20', 'यस्मादर्था विवर्धन्ते येष्वधर्मः प्रतिष्ठितः।
क्लिश्यन्ते धर्मशीलाश्च तस्मादेतौ निरर्थकौ॥', 'yasmād arthā vivardhante yeṣv adharmaḥ pratiṣṭhitaḥ
kliśyante dharmaśīlāś ca tasmād etau nirarthakau', null, 6070020),
('ramayana-6-70-21', 21, 'Yuddha Kanda, Sarga 70, Verse 21', 'वध्यन्ते पापकर्माणो यद्यधर्मेण राघव।
वधकर्महतो धर्मः स हतः कं वधिष्यति॥', 'vadhyante pāpakarmāṇo yady adharmeṇa rāghava
vadhakarmahato dharmaḥ sa hataḥ kaṃ vadhiṣyati', null, 6070021),
('ramayana-6-70-22', 22, 'Yuddha Kanda, Sarga 70, Verse 22', 'अथ वा विहितेनायं हन्यते हन्ति वा परम्।
विधिरालिप्यते तेन न स पापेन कर्मणा॥', 'atha vā vihitenāyaṃ hanyate hanti vā param
vidhir ālipyate tena na sa pāpena karmaṇā', null, 6070022),
('ramayana-6-70-23', 23, 'Yuddha Kanda, Sarga 70, Verse 23', 'अदृष्टप्रतिकारेण अव्यक्तेनासता सता।
कथं शक्यं परं प्राप्तुं धर्मेणारिविकर्शन॥', 'adṛṣṭapratikāreṇa avyaktenāsatā satā
kathaṃ śakyaṃ paraṃ prāptuṃ dharmeṇārivikarśana', null, 6070023),
('ramayana-6-70-24', 24, 'Yuddha Kanda, Sarga 70, Verse 24', 'यदि सत्स्यात्सतां मुख्य नासत्स्यात्तव किं चन।
त्वया यदीदृशं प्राप्तं तस्मात्सन्नोपपद्यते॥', 'yadi sat syāt satāṃ mukhya nāsat syāt tava kiṃ cana
tvayā yadīdṛśaṃ prāptaṃ tasmāt san nopapadyate', null, 6070024),
('ramayana-6-70-25', 25, 'Yuddha Kanda, Sarga 70, Verse 25', 'अथ वा दुर्बलः क्लीबो बलं धर्मोऽनुवर्तते।
दुर्बलो हृतमर्यादो न सेव्य इति मे मतिः॥', 'atha vā durbalaḥ klībo balaṃ dharmo ''nuvartate
durbalo hṛtamaryādo na sevya iti me matiḥ', null, 6070025),
('ramayana-6-70-26', 26, 'Yuddha Kanda, Sarga 70, Verse 26', 'बलस्य यदि चेद्धर्मो गुणभूतः पराक्रमे।
धर्ममुत्सृज्य वर्तस्व यथा धर्मे तथा बले॥', 'balasya yadi ced dharmo guṇabhūtaḥ parākrame
dharmam utsṛjya vartasva yathā dharme tathā bale', null, 6070026),
('ramayana-6-70-27', 27, 'Yuddha Kanda, Sarga 70, Verse 27', 'अथ चेत्सत्यवचनं धर्मः किल परंतप।
अनृतस्त्वय्यकरुणः किं न बद्धस्त्वया पिता॥', 'atha cet satyavacanaṃ dharmaḥ kila paraṃtapa
anṛtas tvayy akaruṇaḥ kiṃ na baddhas tvayā pitā', null, 6070027),
('ramayana-6-70-28', 28, 'Yuddha Kanda, Sarga 70, Verse 28', 'यदि धर्मो भवेद्भूत अधर्मो वा परंतप।
न स्म हत्वा मुनिं वज्री कुर्यादिज्यां शतक्रतुः॥', 'yadi dharmo bhaved bhūta adharmo vā paraṃtapa
na sma hatvā muniṃ vajrī kuryād ijyāṃ śatakratuḥ', null, 6070028),
('ramayana-6-70-29', 29, 'Yuddha Kanda, Sarga 70, Verse 29', 'अधर्मसंश्रितो धर्मो विनाशयति राघव।
सर्वमेतद्यथाकामं काकुत्स्थ कुरुते नरः॥', 'adharmasaṃśrito dharmo vināśayati rāghava
sarvam etad yathākāmaṃ kākutstha kurute naraḥ', null, 6070029),
('ramayana-6-70-30', 30, 'Yuddha Kanda, Sarga 70, Verse 30', 'मम चेदं मतं तात धर्मोऽयमिति राघव।
धर्ममूलं त्वया छिन्नं राज्यमुत्सृजता तदा॥', 'mama cedaṃ mataṃ tāta dharmo ''yam iti rāghava
dharmamūlaṃ tvayā chinnaṃ rājyam utsṛjatā tadā', null, 6070030),
('ramayana-6-70-31', 31, 'Yuddha Kanda, Sarga 70, Verse 31', 'अर्थेभ्यो हि विवृद्धेभ्यः संवृद्धेभ्यस्ततस्ततः।
क्रियाः सर्वाः प्रवर्तन्ते पर्वतेभ्य इवापगाः॥', 'arthebhyo hi vivṛddhebhyaḥ saṃvṛddhebhyas tatas tataḥ
kriyāḥ sarvāḥ pravartante parvatebhya ivāpagāḥ', null, 6070031),
('ramayana-6-70-32', 32, 'Yuddha Kanda, Sarga 70, Verse 32', 'अर्थेन हि वियुक्तस्य पुरुषस्याल्पतेजसः।
व्युच्छिद्यन्ते क्रियाः सर्वा ग्रीष्मे कुसरितो यथा॥', 'arthena hi viyuktasya puruṣasyālpatejasaḥ
vyucchidyante kriyāḥ sarvā grīṣme kusarito yathā', null, 6070032),
('ramayana-6-70-33', 33, 'Yuddha Kanda, Sarga 70, Verse 33', 'सोऽयमर्थं परित्यज्य सुखकामः सुखैधितः।
पापमारभते कर्तुं तथा दोषः प्रवर्तते॥', 'so ''yam arthaṃ parityajya sukhakāmaḥ sukhaidhitaḥ
pāpam ārabhate kartuṃ tathā doṣaḥ pravartate', null, 6070033),
('ramayana-6-70-34', 34, 'Yuddha Kanda, Sarga 70, Verse 34', 'यस्यार्थास्तस्य मित्राणि यस्यार्थास्तस्य बान्धवः।
यस्यार्थाः स पुमांल्लोके यस्यार्थाः स च पण्डितः॥', 'yasyārthās tasya mitrāṇi yasyārthās tasya bāndhavaḥ
yasyārthāḥ sa pumāṃl loke yasyārthāḥ sa ca paṇḍitaḥ', null, 6070034),
('ramayana-6-70-35', 35, 'Yuddha Kanda, Sarga 70, Verse 35', 'यस्यार्थाः स च विक्रान्तो यस्यार्थाः स च बुद्धिमान्।
यस्यार्थाः स महाभागो यस्यार्थाः स महागुणः॥', 'yasyārthāḥ sa ca vikrānto yasyārthāḥ sa ca buddhimān
yasyārthāḥ sa mahābhāgo yasyārthāḥ sa mahāguṇaḥ', null, 6070035),
('ramayana-6-70-36', 36, 'Yuddha Kanda, Sarga 70, Verse 36', 'अर्थस्यैते परित्यागे दोषाः प्रव्याहृता मया।
राज्यमुत्सृजता वीर येन बुद्धिस्त्वया कृता॥', 'arthasyaite parityāge doṣāḥ pravyāhṛtā mayā
rājyam utsṛjatā vīra yena buddhis tvayā kṛtā', null, 6070036),
('ramayana-6-70-37', 37, 'Yuddha Kanda, Sarga 70, Verse 37', 'यस्यार्था धर्मकामार्थास्तस्य सर्वं प्रदक्षिणम्।
अधनेनार्थकामेन नार्थः शक्यो विचिन्वता॥', 'yasyārthā dharmakāmārthās tasya sarvaṃ pradakṣiṇam
adhanenārthakāmena nārthaḥ śakyo vicinvatā', null, 6070037),
('ramayana-6-70-38', 38, 'Yuddha Kanda, Sarga 70, Verse 38', 'हर्षः कामश्च दर्पश्च धर्मः क्रोधः शमो दमः।
अर्थादेतानि सर्वाणि प्रवर्तन्ते नराधिप॥', 'harṣaḥ kāmaś ca darpaś ca dharmaḥ krodhaḥ śamo damaḥ
arthād etāni sarvāṇi pravartante narādhipa', null, 6070038),
('ramayana-6-70-39', 39, 'Yuddha Kanda, Sarga 70, Verse 39', 'येषां नश्यत्ययं लोकश्चरतां धर्मचारिणाम्।
तेऽर्थास्त्वयि न दृश्यन्ते दुर्दिनेषु यथा ग्रहाः॥', 'yeṣāṃ naśyaty ayaṃ lokaś caratāṃ dharmacāriṇām
te ''rthās tvayi na dṛśyante durdineṣu yathā grahāḥ', null, 6070039),
('ramayana-6-70-40', 40, 'Yuddha Kanda, Sarga 70, Verse 40', 'त्वयि प्रव्रजिते वीर गुरोश्च वचने स्थिते।
रक्षसापहृता भार्या प्राणैः प्रियतरा तव॥', 'tvayi pravrajite vīra guroś ca vacane sthite
rakṣasāpahṛtā bhāryā prāṇaiḥ priyatarā tava', null, 6070040),
('ramayana-6-70-41', 41, 'Yuddha Kanda, Sarga 70, Verse 41', 'तदद्य विपुलं वीर दुःखमिन्द्रजिता कृतम्।
कर्मणा व्यपनेष्यामि तस्मादुत्तिष्ठ राघव॥', 'tad adya vipulaṃ vīra duḥkham indrajitā kṛtam
karmaṇā vyapaneṣyāmi tasmād uttiṣṭha rāghava', null, 6070041),
('ramayana-6-70-42', 42, 'Yuddha Kanda, Sarga 70, Verse 42', 'अयमनघ तवोदितः प्रियार्थं जनकसुता निधनं निरीक्ष्य रुष्टः।
सहयगजरथां सराक्षसेन्द्रां भृशमिषुभिर्विनिपातयामि लङ्काम्॥', 'ayam anagha tavoditaḥ priyārthaṃ janakasutā nidhanaṃ nirīkṣya ruṣṭaḥ
sahayagajarathāṃ sarākṣasendrāṃ bhṛśam iṣubhir vinipātayāmi laṅkām', null, 6070042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 71 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-71-1', 1, 'Yuddha Kanda, Sarga 71, Verse 1', 'राममाश्वासयाने तु लक्ष्मणे भ्रातृवत्सले।
निक्षिप्य गुल्मान्स्वस्थाने तत्रागच्छद्विभीषणः॥', 'rāmam āśvāsayāne tu lakṣmaṇe bhrātṛvatsale
nikṣipya gulmān svasthāne tatrāgacchad vibhīṣaṇaḥ', null, 6071001),
('ramayana-6-71-2', 2, 'Yuddha Kanda, Sarga 71, Verse 2', 'नानाप्रहरणैर्वीरैश्चतुर्भिः सचिवैर्वृतः।
नीलाञ्जनचयाकारैर्मातंगैरिव यूथपः॥', 'nānāpraharaṇair vīraiś caturbhiḥ sacivair vṛtaḥ
nīlāñjanacayākārair mātaṃgair iva yūthapaḥ', null, 6071002),
('ramayana-6-71-3', 3, 'Yuddha Kanda, Sarga 71, Verse 3', 'सोऽभिगम्य महात्मानं राघवं शोकलालसं।
वानरांश्चैव ददृशे बाष्पपर्याकुलेक्षणान्॥', 'so ''bhigamya mahātmānaṃ rāghavaṃ śokalālasaṃ
vānarāṃś caiva dadṛśe bāṣpaparyākulekṣaṇān', null, 6071003),
('ramayana-6-71-4', 4, 'Yuddha Kanda, Sarga 71, Verse 4', 'राघवं च महात्मानमिक्ष्वाकुकुलनन्दनम्।
ददर्श मोहमापन्नं लक्ष्मणस्याङ्कमाश्रितम्॥', 'rāghavaṃ ca mahātmānam ikṣvākukulanandanam
dadarśa moham āpannaṃ lakṣmaṇasyāṅkam āśritam', null, 6071004),
('ramayana-6-71-5', 5, 'Yuddha Kanda, Sarga 71, Verse 5', 'व्रीडितं शोकसंतप्तं दृष्ट्वा रामं विभीषणः।
अन्तर्दुःखेन दीनात्मा किमेतदिति सोऽब्रवीत्॥', 'vrīḍitaṃ śokasaṃtaptaṃ dṛṣṭvā rāmaṃ vibhīṣaṇaḥ
antarduḥkhena dīnātmā kim etad iti so ''bravīt', null, 6071005),
('ramayana-6-71-6', 6, 'Yuddha Kanda, Sarga 71, Verse 6', 'विभीषण मुखं दृष्ट्वा सुग्रीवं तांश्च वानरान्।
उवाच लक्ष्मणो वाक्यमिदं बाष्पपरिप्लुतः॥', 'vibhīṣaṇa mukhaṃ dṛṣṭvā sugrīvaṃ tāṃś ca vānarān
uvāca lakṣmaṇo vākyam idaṃ bāṣpapariplutaḥ', null, 6071006),
('ramayana-6-71-7', 7, 'Yuddha Kanda, Sarga 71, Verse 7', 'हतामिन्द्रजिता सीतामिह श्रुत्वैव राघवः।
हनूमद्वचनात्सौम्य ततो मोहमुपागतः॥', 'hatām indrajitā sītām iha śrutvaiva rāghavaḥ
hanūmad vacanāt saumya tato moham upāgataḥ', null, 6071007),
('ramayana-6-71-8', 8, 'Yuddha Kanda, Sarga 71, Verse 8', 'कथयन्तं तु सौमित्रिं संनिवार्य विभीषणः।
पुष्कलार्थमिदं वाक्यं विसंज्ञं राममब्रवीत्॥', 'kathayantaṃ tu saumitriṃ saṃnivārya vibhīṣaṇaḥ
puṣkalārtham idaṃ vākyaṃ visaṃjñaṃ rāmam abravīt', null, 6071008),
('ramayana-6-71-9', 9, 'Yuddha Kanda, Sarga 71, Verse 9', 'मनुजेन्द्रार्तरूपेण यदुक्तस्त्वं हनूमता।
तदयुक्तमहं मन्ये सागरस्येव शोषणम्॥', 'manujendrārtarūpeṇa yad uktas tvaṃ hanūmatā
tad ayuktam ahaṃ manye sāgarasyeva śoṣaṇam', null, 6071009),
('ramayana-6-71-10', 10, 'Yuddha Kanda, Sarga 71, Verse 10', 'अभिप्रायं तु जानामि रावणस्य दुरात्मनः।
सीतां प्रति महाबाहो न च घातं करिष्यति॥', 'abhiprāyaṃ tu jānāmi rāvaṇasya durātmanaḥ
sītāṃ prati mahābāho na ca ghātaṃ kariṣyati', null, 6071010),
('ramayana-6-71-11', 11, 'Yuddha Kanda, Sarga 71, Verse 11', 'याच्यमानः सुबहुशो मया हितचिकीर्षुणा।
वैदेहीमुत्सृजस्वेति न च तत्कृतवान्वचः॥', 'yācyamānaḥ subahuśo mayā hitacikīrṣuṇā
vaidehīm utsṛjasveti na ca tat kṛtavān vacaḥ', null, 6071011),
('ramayana-6-71-12', 12, 'Yuddha Kanda, Sarga 71, Verse 12', 'नैव साम्ना न भेदेन न दानेन कुतो युधा।
सा द्रष्टुमपि शक्येत नैव चान्येन केन चित्॥', 'naiva sāmnā na bhedena na dānena kuto yudhā
sā draṣṭum api śakyeta naiva cānyena kena cit', null, 6071012),
('ramayana-6-71-13', 13, 'Yuddha Kanda, Sarga 71, Verse 13', 'वानरान्मोहयित्वा तु प्रतियातः स राक्षसः।
चैत्यं निकुम्भिलां नाम यत्र होमं करिष्यति॥', 'vānarān mohayitvā tu pratiyātaḥ sa rākṣasaḥ
caityaṃ nikumbhilāṃ nāma yatra homaṃ kariṣyati', null, 6071013),
('ramayana-6-71-14', 14, 'Yuddha Kanda, Sarga 71, Verse 14', 'हुतवानुपयातो हि देवैरपि सवासवैः।
दुराधर्षो भवत्येष संग्रामे रावणात्मजः॥', 'hutavān upayāto hi devair api savāsavaiḥ
durādharṣo bhavaty eṣa saṃgrāme rāvaṇātmajaḥ', null, 6071014),
('ramayana-6-71-15', 15, 'Yuddha Kanda, Sarga 71, Verse 15', 'तेन मोहयता नूनमेषा माया प्रयोजिता।
विघ्नमन्विच्छता तात वानराणां पराक्रमे।
ससैन्यास्तत्र गच्छामो यावत्तन्न समाप्यते॥', 'tena mohayatā nūnam eṣā māyā prayojitā
vighnam anvicchatā tāta vānarāṇāṃ parākrame
sasainyās tatra gacchāmo yāvat tan na samāpyate', null, 6071015),
('ramayana-6-71-16', 16, 'Yuddha Kanda, Sarga 71, Verse 16', 'त्यजेमं नरशार्दूलमिथ्या संतापमागतम्।
सीदते हि बलं सर्वं दृष्ट्वा त्वां शोककर्शितम्॥', 'tyajemaṃ naraśārdūlamithyā saṃtāpam āgatam
sīdate hi balaṃ sarvaṃ dṛṣṭvā tvāṃ śokakarśitam', null, 6071016),
('ramayana-6-71-17', 17, 'Yuddha Kanda, Sarga 71, Verse 17', 'इह त्वं स्वस्थ हृदयस्तिष्ठ सत्त्वसमुच्छ्रितः।
लक्ष्मणं प्रेषयास्माभिः सह सैन्यानुकर्षिभिः॥', 'iha tvaṃ svastha hṛdayas tiṣṭha sattvasamucchritaḥ
lakṣmaṇaṃ preṣayāsmābhiḥ saha sainyānukarṣibhiḥ', null, 6071017),
('ramayana-6-71-18', 18, 'Yuddha Kanda, Sarga 71, Verse 18', 'एष तं नरशार्दूलो रावणिं निशितैः शरैः।
त्याजयिष्यति तत्कर्म ततो वध्यो भविष्यति॥', 'eṣa taṃ naraśārdūlo rāvaṇiṃ niśitaiḥ śaraiḥ
tyājayiṣyati tat karma tato vadhyo bhaviṣyati', null, 6071018),
('ramayana-6-71-19', 19, 'Yuddha Kanda, Sarga 71, Verse 19', 'तस्यैते निशितास्तीक्ष्णाः पत्रिपत्राङ्गवाजिनः।
पतत्रिण इवासौम्याः शराः पास्यन्ति शोणितम्॥', 'tasyaite niśitās tīkṣṇāḥ patripatrāṅgavājinaḥ
patatriṇa ivāsaumyāḥ śarāḥ pāsyanti śoṇitam', null, 6071019),
('ramayana-6-71-20', 20, 'Yuddha Kanda, Sarga 71, Verse 20', 'तत्संदिश महाबाहो लक्ष्मणं शुभलक्षणम्।
राक्षसस्य विनाशाय वज्रं वज्रधरो यथा॥', 'tat saṃdiśa mahābāho lakṣmaṇaṃ śubhalakṣaṇam
rākṣasasya vināśāya vajraṃ vajradharo yathā', null, 6071020),
('ramayana-6-71-21', 21, 'Yuddha Kanda, Sarga 71, Verse 21', 'मनुजवर न कालविप्रकर्षो रिपुनिधनं प्रति यत्क्षमोऽद्य कर्तुम्।
त्वमतिसृज रिपोर्वधाय बाणीमसुरपुरोन्मथने यथा महेन्द्रः॥', 'manujavara na kālaviprakarṣo ripunidhanaṃ prati yat kṣamo ''dya kartum
tvam atisṛja ripor vadhāya bāṇīm asurapuronmathane yathā mahendraḥ', null, 6071021),
('ramayana-6-71-22', 22, 'Yuddha Kanda, Sarga 71, Verse 22', 'समाप्तकर्मा हि स राक्षसेन्द्रो भवत्यदृश्यः समरे सुरासुरैः।
युयुत्सता तेन समाप्तकर्मणा भवेत्सुराणामपि संशयो महान्॥', 'samāptakarmā hi sa rākṣasendro bhavaty adṛśyaḥ samare surāsuraiḥ
yuyutsatā tena samāptakarmaṇā bhavet surāṇām api saṃśayo mahān', null, 6071022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 72 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-72-1', 1, 'Yuddha Kanda, Sarga 72, Verse 1', 'तस्य तद्वचनं श्रुत्वा राघवः शोककर्शितः।
नोपधारयते व्यक्तं यदुक्तं तेन रक्षसा॥', 'tasya tad vacanaṃ śrutvā rāghavaḥ śokakarśitaḥ
nopadhārayate vyaktaṃ yad uktaṃ tena rakṣasā', null, 6072001),
('ramayana-6-72-2', 2, 'Yuddha Kanda, Sarga 72, Verse 2', 'ततो धैर्यमवष्टभ्य रामः परपुरंजयः।
विभीषणमुपासीनमुवाच कपिसंनिधौ॥', 'tato dhairyam avaṣṭabhya rāmaḥ parapuraṃjayaḥ
vibhīṣaṇam upāsīnam uvāca kapisaṃnidhau', null, 6072002),
('ramayana-6-72-3', 3, 'Yuddha Kanda, Sarga 72, Verse 3', 'नैरृताधिपते वाक्यं यदुक्तं ते विभीषण।
भूयस्तच्छ्रोतुमिच्छामि ब्रूहि यत्ते विवक्षितम्॥', 'nairṛtādhipate vākyaṃ yad uktaṃ te vibhīṣaṇa
bhūyas tac chrotum icchāmi brūhi yat te vivakṣitam', null, 6072003),
('ramayana-6-72-4', 4, 'Yuddha Kanda, Sarga 72, Verse 4', 'राघवस्य वचः श्रुत्वा वाक्यं वाक्यविशारदः।
यत्तत्पुनरिदं वाक्यं बभाषे स विभीषणः॥', 'rāghavasya vacaḥ śrutvā vākyaṃ vākyaviśāradaḥ
yat tat punar idaṃ vākyaṃ babhāṣe sa vibhīṣaṇaḥ', null, 6072004),
('ramayana-6-72-5', 5, 'Yuddha Kanda, Sarga 72, Verse 5', 'यथाज्ञप्तं महाबाहो त्वया गुल्मनिवेशनम्।
तत्तथानुष्ठितं वीर त्वद्वाक्यसमनन्तरम्॥', 'yathājñaptaṃ mahābāho tvayā gulmaniveśanam
tat tathānuṣṭhitaṃ vīra tvadvākyasamanantaram', null, 6072005),
('ramayana-6-72-6', 6, 'Yuddha Kanda, Sarga 72, Verse 6', 'तान्यनीकानि सर्वाणि विभक्तानि समन्ततः।
विन्यस्ता यूथपाश्चैव यथान्यायं विभागशः॥', 'tāny anīkāni sarvāṇi vibhaktāni samantataḥ
vinyastā yūthapāś caiva yathānyāyaṃ vibhāgaśaḥ', null, 6072006),
('ramayana-6-72-7', 7, 'Yuddha Kanda, Sarga 72, Verse 7', 'भूयस्तु मम विजाप्यं तच्छृणुष्व महायशः।
त्वय्यकारणसंतप्ते संतप्तहृदया वयम्॥', 'bhūyas tu mama vijāpyaṃ tac chṛṇuṣva mahāyaśaḥ
tvayy akāraṇasaṃtapte saṃtaptahṛdayā vayam', null, 6072007),
('ramayana-6-72-8', 8, 'Yuddha Kanda, Sarga 72, Verse 8', 'त्यज राजन्निमं शोकं मिथ्या संतापमागतम्।
तदियं त्यज्यतां चिन्ता शत्रुहर्षविवर्धनी॥', 'tyaja rājann imaṃ śokaṃ mithyā saṃtāpam āgatam
tad iyaṃ tyajyatāṃ cintā śatruharṣavivardhanī', null, 6072008),
('ramayana-6-72-9', 9, 'Yuddha Kanda, Sarga 72, Verse 9', 'उद्यमः क्रियतां वीर हर्षः समुपसेव्यताम्।
प्राप्तव्या यदि ते सीता हन्तव्यश्च निशाचराः॥', 'udyamaḥ kriyatāṃ vīra harṣaḥ samupasevyatām
prāptavyā yadi te sītā hantavyaś ca niśācarāḥ', null, 6072009),
('ramayana-6-72-10', 10, 'Yuddha Kanda, Sarga 72, Verse 10', 'रघुनन्दन वक्ष्यामि श्रूयतां मे हितं वचः।
साध्वयं यातु सौमित्रिर्बलेन महता वृतः।
निकुम्भिलायां संप्राप्य हन्तुं रावणिमाहवे॥', 'raghunandana vakṣyāmi śrūyatāṃ me hitaṃ vacaḥ
sādhv ayaṃ yātu saumitrir balena mahatā vṛtaḥ
nikumbhilāyāṃ saṃprāpya hantuṃ rāvaṇim āhave', null, 6072010),
('ramayana-6-72-11', 11, 'Yuddha Kanda, Sarga 72, Verse 11', 'धनुर्मण्डलनिर्मुक्तैराशीविषविषोपमैः।
शरैर्हन्तुं महेष्वासो रावणिं समितिंजयः॥', 'dhanurmaṇḍalanirmuktair āśīviṣaviṣopamaiḥ
śarair hantuṃ maheṣvāso rāvaṇiṃ samitiṃjayaḥ', null, 6072011),
('ramayana-6-72-12', 12, 'Yuddha Kanda, Sarga 72, Verse 12', 'तेन वीरेण तपसा वरदानात्स्वयम्भुतः।
अस्त्रं ब्रह्मशिरः प्राप्तं कामगाश्च तुरंगमाः॥', 'tena vīreṇa tapasā varadānāt svayambhutaḥ
astraṃ brahmaśiraḥ prāptaṃ kāmagāś ca turaṃgamāḥ', null, 6072012),
('ramayana-6-72-13', 13, 'Yuddha Kanda, Sarga 72, Verse 13', 'निकुम्भिलामसंप्राप्तमहुताग्निं च यो रिपुः।
त्वामाततायिनं हन्यादिन्द्रशत्रो स ते वधः।
इत्येवं विहितो राजन्वधस्तस्यैव धीमतः॥', 'nikumbhilām asaṃprāptam ahutāgniṃ ca yo ripuḥ
tvām ātatāyinaṃ hanyād indraśatro sa te vadhaḥ
ity evaṃ vihito rājan vadhas tasyaiva dhīmataḥ', null, 6072013),
('ramayana-6-72-14', 14, 'Yuddha Kanda, Sarga 72, Verse 14', 'वधायेन्द्रजितो राम तं दिशस्व महाबलम्।
हते तस्मिन्हतं विद्धि रावणं ससुहृज्जनम्॥', 'vadhāyendrajito rāma taṃ diśasva mahābalam
hate tasmin hataṃ viddhi rāvaṇaṃ sasuhṛjjanam', null, 6072014),
('ramayana-6-72-15', 15, 'Yuddha Kanda, Sarga 72, Verse 15', 'विभीषणवचः श्रुत्व रामो वाक्यमथाब्रवीत्।
जानामि तस्य रौद्रस्य मायां सत्यपराक्रम॥', 'vibhīṣaṇavacaḥ śrutva rāmo vākyam athābravīt
jānāmi tasya raudrasya māyāṃ satyaparākrama', null, 6072015),
('ramayana-6-72-16', 16, 'Yuddha Kanda, Sarga 72, Verse 16', 'स हि ब्रह्मास्त्रवित्प्राज्ञो महामायो महाबलः।
करोत्यसंज्ञान्संग्रामे देवान्सवरुणानपि॥', 'sa hi brahmāstravit prājño mahāmāyo mahābalaḥ
karoty asaṃjñān saṃgrāme devān savaruṇān api', null, 6072016),
('ramayana-6-72-17', 17, 'Yuddha Kanda, Sarga 72, Verse 17', 'तस्यान्तरिक्षे चरतो रथस्थस्य महायशः।
न गतिर्ज्ञायते वीरसूर्यस्येवाभ्रसंप्लवे॥', 'tasyāntarikṣe carato rathasthasya mahāyaśaḥ
na gatir jñāyate vīrasūryasyevābhrasaṃplave', null, 6072017),
('ramayana-6-72-18', 18, 'Yuddha Kanda, Sarga 72, Verse 18', 'राघवस्तु रिपोर्ज्ञात्वा मायावीर्यं दुरात्मनः।
लक्ष्मणं कीर्तिसंपन्नमिदं वचनमब्रवीत्॥', 'rāghavas tu ripor jñātvā māyāvīryaṃ durātmanaḥ
lakṣmaṇaṃ kīrtisaṃpannam idaṃ vacanam abravīt', null, 6072018),
('ramayana-6-72-19', 19, 'Yuddha Kanda, Sarga 72, Verse 19', 'यद्वानरेन्द्रस्य बलं तेन सर्वेण संवृतः।
हनूमत्प्रमुखैश्चैव यूथपैः सहलक्ष्मण॥', 'yad vānarendrasya balaṃ tena sarveṇa saṃvṛtaḥ
hanūmatpramukhaiś caiva yūthapaiḥ sahalakṣmaṇa', null, 6072019),
('ramayana-6-72-20', 20, 'Yuddha Kanda, Sarga 72, Verse 20', 'जाम्बवेनर्क्षपतिना सह सैन्येन संवृतः।
जहि तं राक्षससुतं मायाबलविशारदम्॥', 'jāmbavenarkṣapatinā saha sainyena saṃvṛtaḥ
jahi taṃ rākṣasasutaṃ māyābalaviśāradam', null, 6072020),
('ramayana-6-72-21', 21, 'Yuddha Kanda, Sarga 72, Verse 21', 'अयं त्वां सचिवैः सार्धं महात्मा रजनीचरः।
अभिज्ञस्तस्य देशस्य पृष्ठतोऽनुगमिष्यति॥', 'ayaṃ tvāṃ sacivaiḥ sārdhaṃ mahātmā rajanīcaraḥ
abhijñas tasya deśasya pṛṣṭhato ''nugamiṣyati', null, 6072021),
('ramayana-6-72-22', 22, 'Yuddha Kanda, Sarga 72, Verse 22', 'राघवस्य वचः श्रुत्वा लक्ष्मणः सविभीषणः।
जग्राह कार्मुकं श्रेष्ठमन्यद्भीमपराक्रमः॥', 'rāghavasya vacaḥ śrutvā lakṣmaṇaḥ savibhīṣaṇaḥ
jagrāha kārmukaṃ śreṣṭham anyad bhīmaparākramaḥ', null, 6072022),
('ramayana-6-72-23', 23, 'Yuddha Kanda, Sarga 72, Verse 23', 'संनद्धः कवची खड्गी स शरी हेमचापधृक्।
रामपादावुपस्पृश्य हृष्टः सौमित्रिरब्रवीत्॥', 'saṃnaddhaḥ kavacī khaḍgī sa śarī hemacāpadhṛk
rāmapādāv upaspṛśya hṛṣṭaḥ saumitrir abravīt', null, 6072023),
('ramayana-6-72-24', 24, 'Yuddha Kanda, Sarga 72, Verse 24', 'अद्य मत्कार्मुकोन्मुखाः शरा निर्भिद्य रावणिम्।
लङ्कामभिपतिष्यन्ति हंसाः पुष्करिणीमिव॥', 'adya matkārmukonmukhāḥ śarā nirbhidya rāvaṇim
laṅkām abhipatiṣyanti haṃsāḥ puṣkariṇīm iva', null, 6072024),
('ramayana-6-72-25', 25, 'Yuddha Kanda, Sarga 72, Verse 25', 'अद्यैव तस्य रौद्रस्य शरीरं मामकाः शराः।
विधमिष्यन्ति हत्वा तं महाचापगुणच्युताः॥', 'adyaiva tasya raudrasya śarīraṃ māmakāḥ śarāḥ
vidhamiṣyanti hatvā taṃ mahācāpaguṇacyutāḥ', null, 6072025),
('ramayana-6-72-26', 26, 'Yuddha Kanda, Sarga 72, Verse 26', 'स एवमुक्त्वा द्युतिमान्वचनं भ्रातुरग्रतः।
स रावणिवधाकाङ्क्षी लक्ष्मणस्त्वरितो ययौ॥', 'sa evam uktvā dyutimān vacanaṃ bhrātur agrataḥ
sa rāvaṇivadhākāṅkṣī lakṣmaṇas tvarito yayau', null, 6072026),
('ramayana-6-72-27', 27, 'Yuddha Kanda, Sarga 72, Verse 27', 'सोऽभिवाद्य गुरोः पादौ कृत्वा चापि प्रदक्षिणम्।
निकुम्भिलामभिययौ चैत्यं रावणिपालितम्॥', 'so ''bhivādya guroḥ pādau kṛtvā cāpi pradakṣiṇam
nikumbhilām abhiyayau caityaṃ rāvaṇipālitam', null, 6072027),
('ramayana-6-72-28', 28, 'Yuddha Kanda, Sarga 72, Verse 28', 'विभीषणेन सहितो राजपुत्रः प्रतापवान्।
कृतस्वस्त्ययनो भ्रात्रा लक्ष्मणस्त्वरितो ययौ॥', 'vibhīṣaṇena sahito rājaputraḥ pratāpavān
kṛtasvastyayano bhrātrā lakṣmaṇas tvarito yayau', null, 6072028),
('ramayana-6-72-29', 29, 'Yuddha Kanda, Sarga 72, Verse 29', 'वानराणां सहस्रैस्तु हनूमान्बहुभिर्वृतः।
विभीषणः सहामात्यस्तदा लक्ष्मणमन्वगात्॥', 'vānarāṇāṃ sahasrais tu hanūmān bahubhir vṛtaḥ
vibhīṣaṇaḥ sahāmātyas tadā lakṣmaṇam anvagāt', null, 6072029),
('ramayana-6-72-30', 30, 'Yuddha Kanda, Sarga 72, Verse 30', 'महता हरिसैन्येन सवेगमभिसंवृतः।
ऋक्षराजबलं चैव ददर्श पथि विष्ठितम्॥', 'mahatā harisainyena savegam abhisaṃvṛtaḥ
ṛkṣarājabalaṃ caiva dadarśa pathi viṣṭhitam', null, 6072030),
('ramayana-6-72-31', 31, 'Yuddha Kanda, Sarga 72, Verse 31', 'स गत्वा दूरमध्वानं सौमित्रिर्मित्रनन्दनः।
राक्षसेन्द्रबलं दूरादपश्यद्व्यूहमास्थितम्॥', 'sa gatvā dūram adhvānaṃ saumitrir mitranandanaḥ
rākṣasendrabalaṃ dūrād apaśyad vyūham āsthitam', null, 6072031),
('ramayana-6-72-32', 32, 'Yuddha Kanda, Sarga 72, Verse 32', 'स संप्राप्य धनुष्पाणिर्मायायोगमरिंदम।
तस्थौ ब्रह्मविधानेन विजेतुं रघुनन्दनः॥', 'sa saṃprāpya dhanuṣpāṇir māyāyogam ariṃdama
tasthau brahmavidhānena vijetuṃ raghunandanaḥ', null, 6072032),
('ramayana-6-72-33', 33, 'Yuddha Kanda, Sarga 72, Verse 33', 'विविधममलशस्त्रभास्वरं तद्ध्वजगहनं विपुलं महारथैश्च।
प्रतिभयतममप्रमेयवेगं तिमिरमिव द्विषतां बलं विवेश॥', 'vividham amalaśastrabhāsvaraṃ tad dhvajagahanaṃ vipulaṃ mahārathaiś ca
pratibhayatamam aprameyavegaṃ timiram iva dviṣatāṃ balaṃ viveśa', null, 6072033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 73 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-73-1', 1, 'Yuddha Kanda, Sarga 73, Verse 1', 'अथ तस्यामवस्थायां लक्ष्मणं रावणानुजः।
परेषामहितं वाक्यमर्थसाधकमब्रवीत्॥', 'atha tasyām avasthāyāṃ lakṣmaṇaṃ rāvaṇānujaḥ
pareṣām ahitaṃ vākyam arthasādhakam abravīt', null, 6073001),
('ramayana-6-73-2', 2, 'Yuddha Kanda, Sarga 73, Verse 2', 'अस्यानीकस्य महतो भेदने यतलक्ष्मण।
राक्षसेन्द्रसुतोऽप्यत्र भिन्ने दृश्यो भविष्यति॥', 'asyānīkasya mahato bhedane yatalakṣmaṇa
rākṣasendrasuto ''py atra bhinne dṛśyo bhaviṣyati', null, 6073002),
('ramayana-6-73-3', 3, 'Yuddha Kanda, Sarga 73, Verse 3', 'स त्वमिन्द्राशनिप्रख्यैः शरैरवकिरन्परान्।
अभिद्रवाशु यावद्वै नैतत्कर्म समाप्यते॥', 'sa tvam indrāśaniprakhyaiḥ śarair avakiran parān
abhidravāśu yāvad vai naitat karma samāpyate', null, 6073003),
('ramayana-6-73-4', 4, 'Yuddha Kanda, Sarga 73, Verse 4', 'जहि वीरदुरात्मानं मायापरमधार्मिकम्।
रावणिं क्रूरकर्माणं सर्वलोकभयावहम्॥', 'jahi vīradurātmānaṃ māyāparam adhārmikam
rāvaṇiṃ krūrakarmāṇaṃ sarvalokabhayāvaham', null, 6073004),
('ramayana-6-73-5', 5, 'Yuddha Kanda, Sarga 73, Verse 5', 'विभीषणवचः श्रुत्वा लक्ष्मणः शुभलक्षणः।
ववर्ष शरवर्षाणि राक्षसेन्द्रसुतं प्रति॥', 'vibhīṣaṇavacaḥ śrutvā lakṣmaṇaḥ śubhalakṣaṇaḥ
vavarṣa śaravarṣāṇi rākṣasendrasutaṃ prati', null, 6073005),
('ramayana-6-73-6', 6, 'Yuddha Kanda, Sarga 73, Verse 6', 'ऋक्षाः शाखामृगाश्चैव द्रुमाद्रिवरयोधिनः।
अभ्यधावन्त सहितास्तदनीकमवस्थितम्॥', 'ṛkṣāḥ śākhāmṛgāś caiva drumādrivarayodhinaḥ
abhyadhāvanta sahitās tad anīkam avasthitam', null, 6073006),
('ramayana-6-73-7', 7, 'Yuddha Kanda, Sarga 73, Verse 7', 'राक्षसाश्च शितैर्बाणैरसिभिः शक्तितोमरैः।
उद्यतैः समवर्तन्त कपिसैन्यजिघांसवः॥', 'rākṣasāś ca śitair bāṇair asibhiḥ śaktitomaraiḥ
udyataiḥ samavartanta kapisainyajighāṃsavaḥ', null, 6073007),
('ramayana-6-73-8', 8, 'Yuddha Kanda, Sarga 73, Verse 8', 'स संप्रहारस्तुमुलः संजज्ञे कपिरक्षसाम्।
शब्देन महता लङ्कां नादयन्वै समन्ततः॥', 'sa saṃprahāras tumulaḥ saṃjajñe kapirakṣasām
śabdena mahatā laṅkāṃ nādayan vai samantataḥ', null, 6073008),
('ramayana-6-73-9', 9, 'Yuddha Kanda, Sarga 73, Verse 9', 'शस्त्रैर्बहुविधाकारैः शितैर्बाणैश्च पादपैः।
उद्यतैर्गिरिशृङ्गैश्च घोरैराकाशमावृतम्॥', 'śastrair bahuvidhākāraiḥ śitair bāṇaiś ca pādapaiḥ
udyatair giriśṛṅgaiś ca ghorair ākāśam āvṛtam', null, 6073009),
('ramayana-6-73-10', 10, 'Yuddha Kanda, Sarga 73, Verse 10', 'ते राक्षसा वानरेषु विकृताननबाहवः।
निवेशयन्तः शस्त्राणि चक्रुस्ते सुमहद्भयम्॥', 'te rākṣasā vānareṣu vikṛtānanabāhavaḥ
niveśayantaḥ śastrāṇi cakrus te sumahad bhayam', null, 6073010),
('ramayana-6-73-11', 11, 'Yuddha Kanda, Sarga 73, Verse 11', 'तथैव सकलैर्वृक्षैर्गिरिशृङ्गैश्च वानराः।
अभिजघ्नुर्निजघ्नुश्च समरे राक्षसर्षभान्॥', 'tathaiva sakalair vṛkṣair giriśṛṅgaiś ca vānarāḥ
abhijaghnur nijaghnuś ca samare rākṣasarṣabhān', null, 6073011),
('ramayana-6-73-12', 12, 'Yuddha Kanda, Sarga 73, Verse 12', 'ऋक्षवानरमुख्यैश्च महाकायैर्महाबलैः।
रक्षसां वध्यमानानां महद्भयमजायत॥', 'ṛkṣavānaramukhyaiś ca mahākāyair mahābalaiḥ
rakṣasāṃ vadhyamānānāṃ mahad bhayam ajāyata', null, 6073012),
('ramayana-6-73-13', 13, 'Yuddha Kanda, Sarga 73, Verse 13', 'स्वमनीकं विषण्णं तु श्रुत्वा शत्रुभिरर्दितम्।
उदतिष्ठत दुर्धर्षस्तत्कर्मण्यननुष्ठिते॥', 'svam anīkaṃ viṣaṇṇaṃ tu śrutvā śatrubhir arditam
udatiṣṭhata durdharṣas tat karmaṇy ananuṣṭhite', null, 6073013),
('ramayana-6-73-14', 14, 'Yuddha Kanda, Sarga 73, Verse 14', 'वृक्षान्धकारान्निष्क्रम्य जातक्रोधः स रावणिः।
आरुरोह रथं सज्जं पूर्वयुक्तं स राक्षसः॥', 'vṛkṣāndhakārān niṣkramya jātakrodhaḥ sa rāvaṇiḥ
āruroha rathaṃ sajjaṃ pūrvayuktaṃ sa rākṣasaḥ', null, 6073014),
('ramayana-6-73-15', 15, 'Yuddha Kanda, Sarga 73, Verse 15', 'स भीमकार्मुकशरः कृष्णाञ्जनचयोपमः।
रक्तास्यनयनः क्रूरो बभौ मृत्युरिवान्तकः॥', 'sa bhīmakārmukaśaraḥ kṛṣṇāñjanacayopamaḥ
raktāsyanayanaḥ krūro babhau mṛtyur ivāntakaḥ', null, 6073015),
('ramayana-6-73-16', 16, 'Yuddha Kanda, Sarga 73, Verse 16', 'दृष्ट्वैव तु रथस्थं तं पर्यवर्तत तद्बलम्।
रक्षसां भीमवेगानां लक्ष्मणेन युयुत्सताम्॥', 'dṛṣṭvaiva tu rathasthaṃ taṃ paryavartata tad balam
rakṣasāṃ bhīmavegānāṃ lakṣmaṇena yuyutsatām', null, 6073016),
('ramayana-6-73-17', 17, 'Yuddha Kanda, Sarga 73, Verse 17', 'तस्मिन्काले तु हनुमानुद्यम्य सुदुरासदम्।
धरणीधरसंकाशी महावृक्षमरिंदमः॥', 'tasmin kāle tu hanumān udyamya sudurāsadam
dharaṇīdharasaṃkāśī mahāvṛkṣam ariṃdamaḥ', null, 6073017),
('ramayana-6-73-18', 18, 'Yuddha Kanda, Sarga 73, Verse 18', 'स राक्षसानां तत्सैन्यं कालाग्निरिव निर्दहन्।
चकार बहुभिर्वृक्षैर्निःसंज्ञं युधि वानरः॥', 'sa rākṣasānāṃ tat sainyaṃ kālāgnir iva nirdahan
cakāra bahubhir vṛkṣair niḥsaṃjñaṃ yudhi vānaraḥ', null, 6073018),
('ramayana-6-73-19', 19, 'Yuddha Kanda, Sarga 73, Verse 19', 'विध्वंसयन्तं तरसा दृष्ट्वैव पवनात्मजम्।
राक्षसानां सहस्राणि हनूमन्तमवाकिरन्॥', 'vidhvaṃsayantaṃ tarasā dṛṣṭvaiva pavanātmajam
rākṣasānāṃ sahasrāṇi hanūmantam avākiran', null, 6073019),
('ramayana-6-73-20', 20, 'Yuddha Kanda, Sarga 73, Verse 20', 'शितशूलधराः शूलैरसिभिश्चासिपाणयः।
शक्तिभिः शक्तिहस्ताश्च पट्टसैः पट्टसायुधाः॥', 'śitaśūladharāḥ śūlair asibhiś cāsipāṇayaḥ
śaktibhiḥ śaktihastāś ca paṭṭasaiḥ paṭṭasāyudhāḥ', null, 6073020),
('ramayana-6-73-21', 21, 'Yuddha Kanda, Sarga 73, Verse 21', 'परिघैश्च गदाभिश्च कुन्तैश्च शुभदर्शनैः।
शतशश्च शतघ्नीभिरायसैरपि मुद्गरैः॥', 'parighaiś ca gadābhiś ca kuntaiś ca śubhadarśanaiḥ
śataśaś ca śataghnībhir āyasair api mudgaraiḥ', null, 6073021),
('ramayana-6-73-22', 22, 'Yuddha Kanda, Sarga 73, Verse 22', 'घोरैः परशुभिश्चैव भिण्डिपालैश्च राक्षसाः।
मुष्टिभिर्वज्रवेगैश्च तलैरशनिसंनिभैः॥', 'ghoraiḥ paraśubhiś caiva bhiṇḍipālaiś ca rākṣasāḥ
muṣṭibhir vajravegaiś ca talair aśanisaṃnibhaiḥ', null, 6073022),
('ramayana-6-73-23', 23, 'Yuddha Kanda, Sarga 73, Verse 23', 'अभिजघ्नुः समासाद्य समन्तात्पर्वतोपमम्।
तेषामपि च संक्रुद्धश्चकार कदनं महत्॥', 'abhijaghnuḥ samāsādya samantāt parvatopamam
teṣām api ca saṃkruddhaś cakāra kadanaṃ mahat', null, 6073023),
('ramayana-6-73-24', 24, 'Yuddha Kanda, Sarga 73, Verse 24', 'स ददर्श कपिश्रेष्ठमचलोपममिन्द्रजित्।
सूदयानममित्रघ्नममित्रान्पवनात्मजम्॥', 'sa dadarśa kapiśreṣṭham acalopamam indrajit
sūdayānam amitraghnam amitrān pavanātmajam', null, 6073024),
('ramayana-6-73-25', 25, 'Yuddha Kanda, Sarga 73, Verse 25', 'स सारथिमुवाचेदं याहि यत्रैष वानरः।
क्षयमेव हि नः कुर्याद्राक्षसानामुपेक्षितः॥', 'sa sārathim uvācedaṃ yāhi yatraiṣa vānaraḥ
kṣayam eva hi naḥ kuryād rākṣasānām upekṣitaḥ', null, 6073025),
('ramayana-6-73-26', 26, 'Yuddha Kanda, Sarga 73, Verse 26', 'इत्युक्तः सारथिस्तेन ययौ यत्र स मारुतिः।
वहन्परमदुर्धर्षं स्थितमिन्द्रजितं रथे॥', 'ity uktaḥ sārathis tena yayau yatra sa mārutiḥ
vahan paramadurdharṣaṃ sthitam indrajitaṃ rathe', null, 6073026),
('ramayana-6-73-27', 27, 'Yuddha Kanda, Sarga 73, Verse 27', 'सोऽभ्युपेत्य शरान्खड्गान्पट्टसासिपरश्वधान्।
अभ्यवर्षत दुर्धर्षः कपिमूर्ध्नि स राक्षसः॥', 'so ''bhyupetya śarān khaḍgān paṭṭasāsiparaśvadhān
abhyavarṣata durdharṣaḥ kapimūrdhni sa rākṣasaḥ', null, 6073027),
('ramayana-6-73-28', 28, 'Yuddha Kanda, Sarga 73, Verse 28', 'तानि शस्त्राणि घोराणि प्रतिगृह्य स मारुतिः।
रोषेण महताविषो वाक्यं चेदमुवाच ह॥', 'tāni śastrāṇi ghorāṇi pratigṛhya sa mārutiḥ
roṣeṇa mahatāviṣo vākyaṃ cedam uvāca ha', null, 6073028),
('ramayana-6-73-29', 29, 'Yuddha Kanda, Sarga 73, Verse 29', 'युध्यस्व यदि शूरोऽसि रावणात्मज दुर्मते।
वायुपुत्रं समासाद्य न जीवन्प्रतियास्यसि॥', 'yudhyasva yadi śūro ''si rāvaṇātmaja durmate
vāyuputraṃ samāsādya na jīvan pratiyāsyasi', null, 6073029),
('ramayana-6-73-30', 30, 'Yuddha Kanda, Sarga 73, Verse 30', 'बाहुभ्यां संप्रयुध्यस्व यदि मे द्वन्द्वमाहवे।
वेगं सहस्व दुर्बुद्धे ततस्त्वं रक्षसां वरः॥', 'bāhubhyāṃ saṃprayudhyasva yadi me dvandvam āhave
vegaṃ sahasva durbuddhe tatas tvaṃ rakṣasāṃ varaḥ', null, 6073030),
('ramayana-6-73-31', 31, 'Yuddha Kanda, Sarga 73, Verse 31', 'हनूमन्तं जिघांसन्तं समुद्यतशरासनम्।
रावणात्मजमाचष्टे लक्ष्मणाय विभीषणः॥', 'hanūmantaṃ jighāṃsantaṃ samudyataśarāsanam
rāvaṇātmajam ācaṣṭe lakṣmaṇāya vibhīṣaṇaḥ', null, 6073031),
('ramayana-6-73-32', 32, 'Yuddha Kanda, Sarga 73, Verse 32', 'यस्तु वासवनिर्जेता रावणस्यात्मसंभवः।
स एष रथमास्थाय हनूमन्तं जिघांसति॥', 'yas tu vāsavanirjetā rāvaṇasyātmasaṃbhavaḥ
sa eṣa ratham āsthāya hanūmantaṃ jighāṃsati', null, 6073032),
('ramayana-6-73-33', 33, 'Yuddha Kanda, Sarga 73, Verse 33', 'तमप्रतिमसंस्थानैः शरैः शत्रुविदारणैः।
जीवितान्तकरैर्घोरैः सौमित्रे रावणिं जहि॥', 'tam apratimasaṃsthānaiḥ śaraiḥ śatruvidāraṇaiḥ
jīvitāntakarair ghoraiḥ saumitre rāvaṇiṃ jahi', null, 6073033),
('ramayana-6-73-34', 34, 'Yuddha Kanda, Sarga 73, Verse 34', 'इत्येवमुक्तस्तु तदा महात्मा विभीषणेनारिविभीषणेन।
ददर्श तं पर्वतसंनिकाशं रथस्थितं भीमबलं दुरासदम्॥', 'ity evam uktas tu tadā mahātmā vibhīṣaṇenārivibhīṣaṇena
dadarśa taṃ parvatasaṃnikāśaṃ rathasthitaṃ bhīmabalaṃ durāsadam', null, 6073034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 74 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-74-1', 1, 'Yuddha Kanda, Sarga 74, Verse 1', 'एवमुक्त्वा तु सौमित्रिं जातहर्षो विभीषणः।
धनुष्पाणिनमादाय त्वरमाणो जगाम सः॥', 'evam uktvā tu saumitriṃ jātaharṣo vibhīṣaṇaḥ
dhanuṣpāṇinam ādāya tvaramāṇo jagāma saḥ', null, 6074001),
('ramayana-6-74-2', 2, 'Yuddha Kanda, Sarga 74, Verse 2', 'अविदूरं ततो गत्वा प्रविश्य च महद्वनम्।
दर्शयामास तत्कर्म लक्ष्मणाय विभीषणः॥', 'avidūraṃ tato gatvā praviśya ca mahad vanam
darśayām āsa tat karma lakṣmaṇāya vibhīṣaṇaḥ', null, 6074002),
('ramayana-6-74-3', 3, 'Yuddha Kanda, Sarga 74, Verse 3', 'नीलजीमूतसंकाशं न्यग्रोधं भीमदर्शनम्।
तेजस्वी रावणभ्राता लक्ष्मणाय न्यवेदयत्॥', 'nīlajīmūtasaṃkāśaṃ nyagrodhaṃ bhīmadarśanam
tejasvī rāvaṇabhrātā lakṣmaṇāya nyavedayat', null, 6074003),
('ramayana-6-74-4', 4, 'Yuddha Kanda, Sarga 74, Verse 4', 'इहोपहारं भूतानां बलवान्रावणातजः।
उपहृत्य ततः पश्चात्संग्राममभिवर्तते॥', 'ihopahāraṃ bhūtānāṃ balavān rāvaṇātajaḥ
upahṛtya tataḥ paścāt saṃgrāmam abhivartate', null, 6074004),
('ramayana-6-74-5', 5, 'Yuddha Kanda, Sarga 74, Verse 5', 'अदृश्यः सर्वभूतानां ततो भवति राक्षसः।
निहन्ति समरे शत्रून्बध्नाति च शरोत्तमैः॥', 'adṛśyaḥ sarvabhūtānāṃ tato bhavati rākṣasaḥ
nihanti samare śatrūn badhnāti ca śarottamaiḥ', null, 6074005),
('ramayana-6-74-6', 6, 'Yuddha Kanda, Sarga 74, Verse 6', 'तमप्रविष्टं न्यग्रोधं बलिनं रावणात्मजम्।
विध्वंसय शरैस्तीक्ष्णैः सरथं साश्वसारथिम्॥', 'tam apraviṣṭaṃ nyagrodhaṃ balinaṃ rāvaṇātmajam
vidhvaṃsaya śarais tīkṣṇaiḥ sarathaṃ sāśvasārathim', null, 6074006),
('ramayana-6-74-7', 7, 'Yuddha Kanda, Sarga 74, Verse 7', 'तथेत्युक्त्वा महातेजाः सौमित्रिर्मित्रनन्दनः।
बभूवावस्थितस्तत्र चित्रं विस्फारयन्धनुः॥', 'tathety uktvā mahātejāḥ saumitrir mitranandanaḥ
babhūvāvasthitas tatra citraṃ visphārayan dhanuḥ', null, 6074007),
('ramayana-6-74-8', 8, 'Yuddha Kanda, Sarga 74, Verse 8', 'स रथेनाग्निवर्णेन बलवान्रावणात्मजः।
इन्द्रजित्कवची खड्गी सध्वजः प्रत्यदृश्यत॥', 'sa rathenāgnivarṇena balavān rāvaṇātmajaḥ
indrajit kavacī khaḍgī sadhvajaḥ pratyadṛśyata', null, 6074008),
('ramayana-6-74-9', 9, 'Yuddha Kanda, Sarga 74, Verse 9', 'तमुवाच महातेजाः पौलस्त्यमपराजितम्।
समाह्वये त्वां समरे सम्यग्युद्धं प्रयच्छ मे॥', 'tam uvāca mahātejāḥ paulastyam aparājitam
samāhvaye tvāṃ samare samyag yuddhaṃ prayaccha me', null, 6074009),
('ramayana-6-74-10', 10, 'Yuddha Kanda, Sarga 74, Verse 10', 'एवमुक्तो महातेजा मनस्वी रावणात्मजः।
अब्रवीत्परुषं वाक्यं तत्र दृष्ट्वा विभीषणम्॥', 'evam ukto mahātejā manasvī rāvaṇātmajaḥ
abravīt paruṣaṃ vākyaṃ tatra dṛṣṭvā vibhīṣaṇam', null, 6074010),
('ramayana-6-74-11', 11, 'Yuddha Kanda, Sarga 74, Verse 11', 'इह त्वं जातसंवृद्धः साक्षाद्भ्राता पितुर्मम।
कथं द्रुह्यसि पुत्रस्य पितृव्यो मम राक्षस॥', 'iha tvaṃ jātasaṃvṛddhaḥ sākṣād bhrātā pitur mama
kathaṃ druhyasi putrasya pitṛvyo mama rākṣasa', null, 6074011),
('ramayana-6-74-12', 12, 'Yuddha Kanda, Sarga 74, Verse 12', 'न ज्ञातित्वं न सौहार्दं न जातिस्तव दुर्मते।
प्रमाणं न च सोदर्यं न धर्मो धर्मदूषण॥', 'na jñātitvaṃ na sauhārdaṃ na jātis tava durmate
pramāṇaṃ na ca sodaryaṃ na dharmo dharmadūṣaṇa', null, 6074012),
('ramayana-6-74-13', 13, 'Yuddha Kanda, Sarga 74, Verse 13', 'शोच्यस्त्वमसि दुर्बुद्धे निन्दनीयश्च साधुभिः।
यस्त्वं स्वजनमुत्सृज्य परभृत्यत्वमागतः॥', 'śocyas tvam asi durbuddhe nindanīyaś ca sādhubhiḥ
yas tvaṃ svajanam utsṛjya parabhṛtyatvam āgataḥ', null, 6074013),
('ramayana-6-74-14', 14, 'Yuddha Kanda, Sarga 74, Verse 14', 'नैतच्छिथिलया बुद्ध्या त्वं वेत्सि महदन्तरम्।
क्व च स्वजनसंवासः क्व च नीचपराश्रयः॥', 'naitac chithilayā buddhyā tvaṃ vetsi mahad antaram
kva ca svajanasaṃvāsaḥ kva ca nīcaparāśrayaḥ', null, 6074014),
('ramayana-6-74-15', 15, 'Yuddha Kanda, Sarga 74, Verse 15', 'गुणवान्वा परजनः स्वजनो निर्गुणोऽपि वा।
निर्गुणः स्वजनः श्रेयान्यः परः पर एव सः॥', 'guṇavān vā parajanaḥ svajano nirguṇo ''pi vā
nirguṇaḥ svajanaḥ śreyān yaḥ paraḥ para eva saḥ', null, 6074015),
('ramayana-6-74-16', 16, 'Yuddha Kanda, Sarga 74, Verse 16', 'निरनुक्रोशता चेयं यादृशी ते निशाचर।
स्वजनेन त्वया शक्यं परुषं रावणानुज॥', 'niranukrośatā ceyaṃ yādṛśī te niśācara
svajanena tvayā śakyaṃ paruṣaṃ rāvaṇānuja', null, 6074016),
('ramayana-6-74-17', 17, 'Yuddha Kanda, Sarga 74, Verse 17', 'इत्युक्तो भ्रातृपुत्रेण प्रत्युवाच विभीषणः।
अजानन्निव मच्छीलं किं राक्षस विकत्थसे॥', 'ity ukto bhrātṛputreṇa pratyuvāca vibhīṣaṇaḥ
ajānann iva macchīlaṃ kiṃ rākṣasa vikatthase', null, 6074017),
('ramayana-6-74-18', 18, 'Yuddha Kanda, Sarga 74, Verse 18', 'राक्षसेन्द्रसुतासाधो पारुष्यं त्यज गौरवात्।
कुले यद्यप्यहं जातो रक्षसां क्रूरकर्मणाम्।
गुणोऽयं प्रथमो नॄणां तन्मे शीलमराक्षसं॥', 'rākṣasendrasutāsādho pāruṣyaṃ tyaja gauravāt
kule yady apy ahaṃ jāto rakṣasāṃ krūrakarmaṇām
guṇo ''yaṃ prathamo nṝṇāṃ tan me śīlam arākṣasaṃ', null, 6074018),
('ramayana-6-74-19', 19, 'Yuddha Kanda, Sarga 74, Verse 19', 'न रमे दारुणेनाहं न चाधर्मेण वै रमे।
भ्रात्रा विषमशीलेन कथं भ्राता निरस्यते॥', 'na rame dāruṇenāhaṃ na cādharmeṇa vai rame
bhrātrā viṣamaśīlena kathaṃ bhrātā nirasyate', null, 6074019),
('ramayana-6-74-20', 20, 'Yuddha Kanda, Sarga 74, Verse 20', 'परस्वानां च हरणं परदाराभिमर्शनम्।
सुहृदामतिशङ्कां च त्रयो दोषाः क्षयावहाः॥', 'parasvānāṃ ca haraṇaṃ paradārābhimarśanam
suhṛdām atiśaṅkāṃ ca trayo doṣāḥ kṣayāvahāḥ', null, 6074020),
('ramayana-6-74-21', 21, 'Yuddha Kanda, Sarga 74, Verse 21', 'महर्षीणां वधो घोरः सर्वदेवैश्च विग्रहः।
अभिमानश्च कोपश्च वैरित्वं प्रतिकूलता॥', 'maharṣīṇāṃ vadho ghoraḥ sarvadevaiś ca vigrahaḥ
abhimānaś ca kopaś ca vairitvaṃ pratikūlatā', null, 6074021),
('ramayana-6-74-22', 22, 'Yuddha Kanda, Sarga 74, Verse 22', 'एते दोषा मम भ्रातुर्जीवितैश्वर्यनाशनाः।
गुणान्प्रच्छादयामासुः पर्वतानिव तोयदाः॥', 'ete doṣā mama bhrātur jīvitaiśvaryanāśanāḥ
guṇān pracchādayām āsuḥ parvatān iva toyadāḥ', null, 6074022),
('ramayana-6-74-23', 23, 'Yuddha Kanda, Sarga 74, Verse 23', 'दोषैरेतैः परित्यक्तो मया भ्राता पिता तव।
नेयमस्ति पुरी लङ्का न च त्वं न च ते पिता॥', 'doṣair etaiḥ parityakto mayā bhrātā pitā tava
neyam asti purī laṅkā na ca tvaṃ na ca te pitā', null, 6074023),
('ramayana-6-74-24', 24, 'Yuddha Kanda, Sarga 74, Verse 24', 'अतिमानी च बालश्च दुर्विनीतश्च राक्षस।
बद्धस्त्वं कालपाशेन ब्रूहि मां यद्यदिच्छसि॥', 'atimānī ca bālaś ca durvinītaś ca rākṣasa
baddhas tvaṃ kālapāśena brūhi māṃ yad yad icchasi', null, 6074024),
('ramayana-6-74-25', 25, 'Yuddha Kanda, Sarga 74, Verse 25', 'अद्य ते व्यसनं प्राप्तं किमिह त्वं तु वक्ष्यसि।
प्रवेष्टुं न त्वया शक्यो न्यग्रोधो राक्षसाधम॥', 'adya te vyasanaṃ prāptaṃ kim iha tvaṃ tu vakṣyasi
praveṣṭuṃ na tvayā śakyo nyagrodho rākṣasādhama', null, 6074025),
('ramayana-6-74-26', 26, 'Yuddha Kanda, Sarga 74, Verse 26', 'धर्षयित्वा तु काकुत्स्थौ न शक्यं जीवितुं त्वया।
युध्यस्व नरदेवेन लक्ष्मणेन रणे सह।
हतस्त्वं देवता कार्यं करिष्यसि यमक्षये॥', 'dharṣayitvā tu kākutsthau na śakyaṃ jīvituṃ tvayā
yudhyasva naradevena lakṣmaṇena raṇe saha
hatas tvaṃ devatā kāryaṃ kariṣyasi yamakṣaye', null, 6074026),
('ramayana-6-74-27', 27, 'Yuddha Kanda, Sarga 74, Verse 27', 'निदर्शयस्वात्मबलं समुद्यतं कुरुष्व सर्वायुधसायकव्ययम्।
न लक्ष्मणस्यैत्य हि बाणगोचरं त्वमद्य जीवन्सबलो गमिष्यसि॥', 'nidarśayasvātmabalaṃ samudyataṃ kuruṣva sarvāyudhasāyakavyayam
na lakṣmaṇasyaitya hi bāṇagocaraṃ tvam adya jīvan sabalo gamiṣyasi', null, 6074027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 75 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-75-1', 1, 'Yuddha Kanda, Sarga 75, Verse 1', 'विभीषण वचः श्रुत्वा रावणिः क्रोधमूर्छितः।
अब्रवीत्परुषं वाक्यं वेगेनाभ्युत्पपात ह॥', 'vibhīṣaṇa vacaḥ śrutvā rāvaṇiḥ krodhamūrchitaḥ
abravīt paruṣaṃ vākyaṃ vegenābhyutpapāta ha', null, 6075001),
('ramayana-6-75-2', 2, 'Yuddha Kanda, Sarga 75, Verse 2', 'उद्यतायुधनिस्त्रिंशो रथे तु समलंकृते।
कालाश्वयुक्ते महति स्थितः कालान्तकोपमः॥', 'udyatāyudhanistriṃśo rathe tu samalaṃkṛte
kālāśvayukte mahati sthitaḥ kālāntakopamaḥ', null, 6075002),
('ramayana-6-75-3', 3, 'Yuddha Kanda, Sarga 75, Verse 3', 'महाप्रमाणमुद्यम्य विपुलं वेगवद्दृढम्।
धनुर्भीमं परामृश्य शरांश्चामित्रनाशनान्॥', 'mahāpramāṇam udyamya vipulaṃ vegavad dṛḍham
dhanur bhīmaṃ parāmṛśya śarāṃś cāmitranāśanān', null, 6075003),
('ramayana-6-75-4', 4, 'Yuddha Kanda, Sarga 75, Verse 4', 'उवाचैनं समारब्धः सौमित्रिं सविभीषणम्।
तांश्च वानरशार्दूलान्पश्यध्वं मे पराक्रमम्॥', 'uvācainaṃ samārabdhaḥ saumitriṃ savibhīṣaṇam
tāṃś ca vānaraśārdūlān paśyadhvaṃ me parākramam', null, 6075004),
('ramayana-6-75-5', 5, 'Yuddha Kanda, Sarga 75, Verse 5', 'अद्य मत्कार्मुकोत्सृष्टं शरवर्षं दुरासदम्।
मुक्तं वर्षमिवाकाशे वारयिष्यथ संयुगे॥', 'adya matkārmukotsṛṣṭaṃ śaravarṣaṃ durāsadam
muktaṃ varṣam ivākāśe vārayiṣyatha saṃyuge', null, 6075005),
('ramayana-6-75-6', 6, 'Yuddha Kanda, Sarga 75, Verse 6', 'अद्य वो मामका बाणा महाकार्मुकनिःसृताः।
विधमिष्यन्ति गात्राणि तूलराशिमिवानलः॥', 'adya vo māmakā bāṇā mahākārmukaniḥsṛtāḥ
vidhamiṣyanti gātrāṇi tūlarāśim ivānalaḥ', null, 6075006),
('ramayana-6-75-7', 7, 'Yuddha Kanda, Sarga 75, Verse 7', 'तीक्ष्णसायकनिर्भिन्नाञ्शूलशक्त्यृष्टितोमरैः।
अद्य वो गमयिष्यामि सर्वानेव यमक्षयम्॥', 'tīkṣṇasāyakanirbhinnāñ śūlaśaktyṛṣṭitomaraiḥ
adya vo gamayiṣyāmi sarvān eva yamakṣayam', null, 6075007),
('ramayana-6-75-8', 8, 'Yuddha Kanda, Sarga 75, Verse 8', 'क्षिपतः शरवर्षाणि क्षिप्रहस्तस्य मे युधि।
जीमूतस्येव नदतः कः स्थास्यति ममाग्रतः॥', 'kṣipataḥ śaravarṣāṇi kṣiprahastasya me yudhi
jīmūtasyeva nadataḥ kaḥ sthāsyati mamāgrataḥ', null, 6075008),
('ramayana-6-75-9', 9, 'Yuddha Kanda, Sarga 75, Verse 9', 'तच्छ्रुत्वा राक्षसेन्द्रस्य गर्जितं लक्ष्मणस्तदा।
अभीतवदनः क्रुद्धो रावणिं वाक्यमब्रवीत्॥', 'tac chrutvā rākṣasendrasya garjitaṃ lakṣmaṇas tadā
abhītavadanaḥ kruddho rāvaṇiṃ vākyam abravīt', null, 6075009),
('ramayana-6-75-10', 10, 'Yuddha Kanda, Sarga 75, Verse 10', 'उक्तश्च दुर्गमः पारः कार्याणां राक्षस त्वया।
कार्याणां कर्मणा पारं यो गच्छति स बुद्धिमान्॥', 'uktaś ca durgamaḥ pāraḥ kāryāṇāṃ rākṣasa tvayā
kāryāṇāṃ karmaṇā pāraṃ yo gacchati sa buddhimān', null, 6075010),
('ramayana-6-75-11', 11, 'Yuddha Kanda, Sarga 75, Verse 11', 'स त्वमर्थस्य हीनार्थो दुरवापस्य केन चित्।
वचो व्याहृत्य जानीषे कृतार्थोऽस्मीति दुर्मते॥', 'sa tvam arthasya hīnārtho duravāpasya kena cit
vaco vyāhṛtya jānīṣe kṛtārtho ''smīti durmate', null, 6075011),
('ramayana-6-75-12', 12, 'Yuddha Kanda, Sarga 75, Verse 12', 'अन्तर्धानगतेनाजौ यस्त्वयाचरितस्तदा।
तस्कराचरितो मार्गो नैष वीरनिषेवितः॥', 'antardhānagatenājau yas tvayācaritas tadā
taskarācarito mārgo naiṣa vīraniṣevitaḥ', null, 6075012),
('ramayana-6-75-13', 13, 'Yuddha Kanda, Sarga 75, Verse 13', 'यथा बाणपथं प्राप्य स्थितोऽहं तव राक्षस।
दर्शयस्वाद्य तत्तेजो वाचा त्वं किं विकत्थसे॥', 'yathā bāṇapathaṃ prāpya sthito ''haṃ tava rākṣasa
darśayasvādya tat tejo vācā tvaṃ kiṃ vikatthase', null, 6075013),
('ramayana-6-75-14', 14, 'Yuddha Kanda, Sarga 75, Verse 14', 'एवमुक्तो धनुर्भीमं परामृश्य महाबलः।
ससर्जे निशितान्बाणानिन्द्रजित्समिजिंजय॥', 'evam ukto dhanur bhīmaṃ parāmṛśya mahābalaḥ
sasarje niśitān bāṇān indrajit samijiṃjaya', null, 6075014),
('ramayana-6-75-15', 15, 'Yuddha Kanda, Sarga 75, Verse 15', 'ते निसृष्टा महावेगाः शराः सर्पविषोपमाः।
संप्राप्य लक्ष्मणं पेतुः श्वसन्त इव पन्नगाः॥', 'te nisṛṣṭā mahāvegāḥ śarāḥ sarpaviṣopamāḥ
saṃprāpya lakṣmaṇaṃ petuḥ śvasanta iva pannagāḥ', null, 6075015),
('ramayana-6-75-16', 16, 'Yuddha Kanda, Sarga 75, Verse 16', 'शरैरतिमहावेगैर्वेगवान्रावणात्मजः।
सौमित्रिमिन्द्रजिद्युद्धे विव्याध शुभलक्षणम्॥', 'śarair atimahāvegair vegavān rāvaṇātmajaḥ
saumitrim indrajid yuddhe vivyādha śubhalakṣaṇam', null, 6075016),
('ramayana-6-75-17', 17, 'Yuddha Kanda, Sarga 75, Verse 17', 'स शरैरतिविद्धाङ्गो रुधिरेण समुक्षितः।
शुशुभे लक्ष्मणः श्रीमान्विधूम इव पावकः॥', 'sa śarair atividdhāṅgo rudhireṇa samukṣitaḥ
śuśubhe lakṣmaṇaḥ śrīmān vidhūma iva pāvakaḥ', null, 6075017),
('ramayana-6-75-18', 18, 'Yuddha Kanda, Sarga 75, Verse 18', 'इन्द्रजित्त्वात्मनः कर्म प्रसमीक्ष्याधिगम्य च।
विनद्य सुमहानादमिदं वचनमब्रवीत्॥', 'indrajit tv ātmanaḥ karma prasamīkṣyādhigamya ca
vinadya sumahānādam idaṃ vacanam abravīt', null, 6075018),
('ramayana-6-75-19', 19, 'Yuddha Kanda, Sarga 75, Verse 19', 'पत्रिणः शितधारास्ते शरा मत्कार्मुकच्युताः।
आदास्यन्तेऽद्य सौमित्रे जीवितं जीवितान्तगाः॥', 'patriṇaḥ śitadhārās te śarā matkārmukacyutāḥ
ādāsyante ''dya saumitre jīvitaṃ jīvitāntagāḥ', null, 6075019),
('ramayana-6-75-20', 20, 'Yuddha Kanda, Sarga 75, Verse 20', 'अद्य गोमायुसंघाश्च श्येनसंघाश्च लक्ष्मण।
गृध्राश्च निपतन्तु त्वां गतासुं निहतं मया॥', 'adya gomāyusaṃghāś ca śyenasaṃghāś ca lakṣmaṇa
gṛdhrāś ca nipatantu tvāṃ gatāsuṃ nihataṃ mayā', null, 6075020),
('ramayana-6-75-21', 21, 'Yuddha Kanda, Sarga 75, Verse 21', 'क्षत्रबन्धुः सदानार्यो रामः परमदुर्मतिः।
भक्तं भ्रातरमद्यैव त्वां द्रक्ष्यति मया हतम्॥', 'kṣatrabandhuḥ sadānāryo rāmaḥ paramadurmatiḥ
bhaktaṃ bhrātaram adyaiva tvāṃ drakṣyati mayā hatam', null, 6075021),
('ramayana-6-75-22', 22, 'Yuddha Kanda, Sarga 75, Verse 22', 'विशस्तकवचं भूमौ व्यपविद्धशरासनम्।
हृतोत्तमाङ्गं सौमित्रे त्वामद्य निहतं मया॥', 'viśastakavacaṃ bhūmau vyapaviddhaśarāsanam
hṛtottamāṅgaṃ saumitre tvām adya nihataṃ mayā', null, 6075022),
('ramayana-6-75-23', 23, 'Yuddha Kanda, Sarga 75, Verse 23', 'इति ब्रुवाणं संरब्धं परुषं रावणात्मजम्।
हेतुमद्वाक्यमत्यर्थं लक्ष्मणः प्रत्युवाच ह॥', 'iti bruvāṇaṃ saṃrabdhaṃ paruṣaṃ rāvaṇātmajam
hetumadvākyam atyarthaṃ lakṣmaṇaḥ pratyuvāca ha', null, 6075023),
('ramayana-6-75-24', 24, 'Yuddha Kanda, Sarga 75, Verse 24', 'अकृत्वा कत्थसे कर्म किमर्थमिह राक्षस।
कुरु तत्कर्म येनाहं श्रद्दध्यां तव कत्थनम्॥', 'akṛtvā katthase karma kimartham iha rākṣasa
kuru tat karma yenāhaṃ śraddadhyāṃ tava katthanam', null, 6075024),
('ramayana-6-75-25', 25, 'Yuddha Kanda, Sarga 75, Verse 25', 'अनुक्त्वा परुषं वाक्यं किं चिदप्यनवक्षिपन्।
अविकत्थन्वधिष्यामि त्वां पश्य पुरुषादन॥', 'anuktvā paruṣaṃ vākyaṃ kiṃ cid apy anavakṣipan
avikatthan vadhiṣyāmi tvāṃ paśya puruṣādana', null, 6075025),
('ramayana-6-75-26', 26, 'Yuddha Kanda, Sarga 75, Verse 26', 'इत्युक्त्वा पञ्चनाराचानाकर्णापूरिताञ्शरान्।
निचखान महावेगांल्लक्ष्मणो राक्षसोरसि॥', 'ity uktvā pañcanārācān ākarṇāpūritāñ śarān
nicakhāna mahāvegāṃl lakṣmaṇo rākṣasorasi', null, 6075026),
('ramayana-6-75-27', 27, 'Yuddha Kanda, Sarga 75, Verse 27', 'स शरैराहतस्तेन सरोषो रावणात्मजः।
सुप्रयुक्तैस्त्रिभिर्बाणैः प्रतिविव्याध लक्ष्मणम्॥', 'sa śarair āhatas tena saroṣo rāvaṇātmajaḥ
suprayuktais tribhir bāṇaiḥ prativivyādha lakṣmaṇam', null, 6075027),
('ramayana-6-75-28', 28, 'Yuddha Kanda, Sarga 75, Verse 28', 'स बभूव महाभीमो नरराक्षससिंहयोः।
विमर्दस्तुमुलो युद्धे परस्परवधैषिणोः॥', 'sa babhūva mahābhīmo nararākṣasasiṃhayoḥ
vimardas tumulo yuddhe parasparavadhaiṣiṇoḥ', null, 6075028),
('ramayana-6-75-29', 29, 'Yuddha Kanda, Sarga 75, Verse 29', 'उभौ हि बलसंपन्नावुभौ विक्रमशालिनौ।
उभावपि सुविक्रान्तौ सर्वशस्त्रास्त्रकोविदौ॥', 'ubhau hi balasaṃpannāv ubhau vikramaśālinau
ubhāv api suvikrāntau sarvaśastrāstrakovidau', null, 6075029),
('ramayana-6-75-30', 30, 'Yuddha Kanda, Sarga 75, Verse 30', 'उभौ परमदुर्जेयावतुल्यबलतेजसौ।
युयुधाते महावीरौ ग्रहाविव नभो गतौ॥', 'ubhau paramadurjeyāv atulyabalatejasau
yuyudhāte mahāvīrau grahāv iva nabho gatau', null, 6075030),
('ramayana-6-75-31', 31, 'Yuddha Kanda, Sarga 75, Verse 31', 'बलवृत्राविव हि तौ युधि वै दुष्प्रधर्षणौ।
युयुधाते महात्मानौ तदा केसरिणाविव॥', 'balavṛtrāv iva hi tau yudhi vai duṣpradharṣaṇau
yuyudhāte mahātmānau tadā kesariṇāv iva', null, 6075031),
('ramayana-6-75-32', 32, 'Yuddha Kanda, Sarga 75, Verse 32', 'बहूनवसृजन्तौ हि मार्गणौघानवस्थितौ।
नरराक्षससिंहौ तौ प्रहृष्टावभ्ययुध्यताम्॥', 'bahūn avasṛjantau hi mārgaṇaughān avasthitau
nararākṣasasiṃhau tau prahṛṣṭāv abhyayudhyatām', null, 6075032),
('ramayana-6-75-33', 33, 'Yuddha Kanda, Sarga 75, Verse 33', 'सुसंप्रहृष्टौ नरराक्षसोत्तमौ जयैषिणौ मार्गणचापधारिणौ।
परस्परं तौ प्रववर्षतुर्भृशं शरौघवर्षेण बलाहकाविव॥', 'susaṃprahṛṣṭau nararākṣasottamau jayaiṣiṇau mārgaṇacāpadhāriṇau
parasparaṃ tau pravavarṣatur bhṛśaṃ śaraughavarṣeṇa balāhakāv iva', null, 6075033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 76 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-76-1', 1, 'Yuddha Kanda, Sarga 76, Verse 1', 'ततः शरं दाशरथिः संधायामित्रकर्शनः।
ससर्ज राक्षसेन्द्राय क्रुद्धः सर्प इव श्वसन्॥', 'tataḥ śaraṃ dāśarathiḥ saṃdhāyāmitrakarśanaḥ
sasarja rākṣasendrāya kruddhaḥ sarpa iva śvasan', null, 6076001),
('ramayana-6-76-2', 2, 'Yuddha Kanda, Sarga 76, Verse 2', 'तस्य ज्यातलनिर्घोषं स श्रुत्वा रावणात्मजः।
विवर्णवदनो भूत्वा लक्ष्मणं समुदैक्षत॥', 'tasya jyātalanirghoṣaṃ sa śrutvā rāvaṇātmajaḥ
vivarṇavadano bhūtvā lakṣmaṇaṃ samudaikṣata', null, 6076002),
('ramayana-6-76-3', 3, 'Yuddha Kanda, Sarga 76, Verse 3', 'तं विषण्णमुखं दृष्ट्वा राक्षसं रावणात्मजम्।
सौमित्रिं युद्धसंसक्तं प्रत्युवाच विभीषणः॥', 'taṃ viṣaṇṇamukhaṃ dṛṣṭvā rākṣasaṃ rāvaṇātmajam
saumitriṃ yuddhasaṃsaktaṃ pratyuvāca vibhīṣaṇaḥ', null, 6076003),
('ramayana-6-76-4', 4, 'Yuddha Kanda, Sarga 76, Verse 4', 'निमित्तान्यनुपश्यामि यान्यस्मिन्रावणात्मजे।
त्वर तेन महाबाहो भग्न एष न संशयः॥', 'nimittāny anupaśyāmi yāny asmin rāvaṇātmaje
tvara tena mahābāho bhagna eṣa na saṃśayaḥ', null, 6076004),
('ramayana-6-76-5', 5, 'Yuddha Kanda, Sarga 76, Verse 5', 'ततः संधाय सौमित्रिः शरानग्निशिखोपमान्।
मुमोच निशितांस्तस्मै सर्वानिव विषोल्बणान्॥', 'tataḥ saṃdhāya saumitriḥ śarān agniśikhopamān
mumoca niśitāṃs tasmai sarvān iva viṣolbaṇān', null, 6076005),
('ramayana-6-76-6', 6, 'Yuddha Kanda, Sarga 76, Verse 6', 'शक्राशनिसमस्पर्शैर्लक्ष्मणेनाहतः शरैः।
मुहूर्तमभवन्मूढः सर्वसंक्षुभितेन्द्रियः॥', 'śakrāśanisamasparśair lakṣmaṇenāhataḥ śaraiḥ
muhūrtam abhavan mūḍhaḥ sarvasaṃkṣubhitendriyaḥ', null, 6076006),
('ramayana-6-76-7', 7, 'Yuddha Kanda, Sarga 76, Verse 7', 'उपलभ्य मुहूर्तेन संज्ञां प्रत्यागतेन्द्रियः।
ददर्शावस्थितं वीरं वीरो दशरथात्मजम्॥', 'upalabhya muhūrtena saṃjñāṃ pratyāgatendriyaḥ
dadarśāvasthitaṃ vīraṃ vīro daśarathātmajam', null, 6076007),
('ramayana-6-76-8', 8, 'Yuddha Kanda, Sarga 76, Verse 8', 'सोऽभिचक्राम सौमित्रिं रोषात्संरक्तलोचनः।
अब्रवीच्चैनमासाद्य पुनः स परुषं वचः॥', 'so ''bhicakrāma saumitriṃ roṣāt saṃraktalocanaḥ
abravīc cainam āsādya punaḥ sa paruṣaṃ vacaḥ', null, 6076008),
('ramayana-6-76-9', 9, 'Yuddha Kanda, Sarga 76, Verse 9', 'किं न स्मरसि तद्युद्धे प्रथमे मत्पराक्रमम्।
निबद्धस्त्वं सह भ्रात्रा यदा युधि विचेष्टसे॥', 'kiṃ na smarasi tad yuddhe prathame matparākramam
nibaddhas tvaṃ saha bhrātrā yadā yudhi viceṣṭase', null, 6076009),
('ramayana-6-76-10', 10, 'Yuddha Kanda, Sarga 76, Verse 10', 'युवा खलु महायुद्धे शक्राशनिसमैः शरैः।
शायिनौ प्रथमं भूमौ विसंज्ञौ सपुरःसरौ॥', 'yuvā khalu mahāyuddhe śakrāśanisamaiḥ śaraiḥ
śāyinau prathamaṃ bhūmau visaṃjñau sapuraḥsarau', null, 6076010),
('ramayana-6-76-11', 11, 'Yuddha Kanda, Sarga 76, Verse 11', 'स्मृतिर्वा नास्ति ते मन्ये व्यक्तं वा यमसादनम्।
गन्तुमिच्छसि यस्मात्त्वं मां धर्षयितुमिच्छसि॥', 'smṛtir vā nāsti te manye vyaktaṃ vā yamasādanam
gantum icchasi yasmāt tvaṃ māṃ dharṣayitum icchasi', null, 6076011),
('ramayana-6-76-12', 12, 'Yuddha Kanda, Sarga 76, Verse 12', 'यदि ते प्रथमे युद्धे न दृष्टो मत्पराक्रमः।
अद्य त्वां दर्शयिष्यामि तिष्ठेदानीं व्यवस्थितः॥', 'yadi te prathame yuddhe na dṛṣṭo matparākramaḥ
adya tvāṃ darśayiṣyāmi tiṣṭhedānīṃ vyavasthitaḥ', null, 6076012),
('ramayana-6-76-13', 13, 'Yuddha Kanda, Sarga 76, Verse 13', 'इत्युक्त्वा सप्तभिर्बाणैरभिविव्याध लक्ष्मणम्।
दशभिश्च हनूमन्तं तीक्ष्णधारैः शरोत्तमैः॥', 'ity uktvā saptabhir bāṇair abhivivyādha lakṣmaṇam
daśabhiś ca hanūmantaṃ tīkṣṇadhāraiḥ śarottamaiḥ', null, 6076013),
('ramayana-6-76-14', 14, 'Yuddha Kanda, Sarga 76, Verse 14', 'ततः शरशतेनैव सुप्रयुक्तेन वीर्यवान्।
क्रोधाद्द्विगुणसंरब्धो निर्बिभेद विभीषणम्॥', 'tataḥ śaraśatenaiva suprayuktena vīryavān
krodhād dviguṇasaṃrabdho nirbibheda vibhīṣaṇam', null, 6076014),
('ramayana-6-76-15', 15, 'Yuddha Kanda, Sarga 76, Verse 15', 'तद्दृष्ट्वेन्द्रजितः कर्म कृतं रामानुजस्तदा।
अचिन्तयित्वा प्रहसन्नैतत्किं चिदिति ब्रुवन्॥', 'tad dṛṣṭvendrajitaḥ karma kṛtaṃ rāmānujas tadā
acintayitvā prahasan naitat kiṃ cid iti bruvan', null, 6076015),
('ramayana-6-76-16', 16, 'Yuddha Kanda, Sarga 76, Verse 16', 'मुमोच स शरान्घोरान्संगृह्य नरपुंगवः।
अभीतवदनः क्रुद्धो रावणिं लक्ष्मणो युधि॥', 'mumoca sa śarān ghorān saṃgṛhya narapuṃgavaḥ
abhītavadanaḥ kruddho rāvaṇiṃ lakṣmaṇo yudhi', null, 6076016),
('ramayana-6-76-17', 17, 'Yuddha Kanda, Sarga 76, Verse 17', 'नैवं रणगतः शूराः प्रहरन्ति निशाचर।
लघवश्चाल्पवीर्याश्च सुखा हीमे शरास्तव॥', 'naivaṃ raṇagataḥ śūrāḥ praharanti niśācara
laghavaś cālpavīryāś ca sukhā hīme śarās tava', null, 6076017),
('ramayana-6-76-18', 18, 'Yuddha Kanda, Sarga 76, Verse 18', 'नैवं शूरास्तु युध्यन्ते समरे जयकाङ्क्षिणः।
इत्येवं तं ब्रुवाणस्तु शरवर्षैरवाकिरत्॥', 'naivaṃ śūrās tu yudhyante samare jayakāṅkṣiṇaḥ
ity evaṃ taṃ bruvāṇas tu śaravarṣair avākirat', null, 6076018),
('ramayana-6-76-19', 19, 'Yuddha Kanda, Sarga 76, Verse 19', 'तस्य बाणैस्तु विध्वस्तं कवचं हेमभूषितम्।
व्यशीर्यत रथोपस्थे ताराजालमिवाम्बरात्॥', 'tasya bāṇais tu vidhvastaṃ kavacaṃ hemabhūṣitam
vyaśīryata rathopasthe tārājālam ivāmbarāt', null, 6076019),
('ramayana-6-76-20', 20, 'Yuddha Kanda, Sarga 76, Verse 20', 'विधूतवर्मा नाराचैर्बभूव स कृतव्रणः।
इन्द्रजित्समरे शूरः प्ररूढ इव सानुमान्॥', 'vidhūtavarmā nārācair babhūva sa kṛtavraṇaḥ
indrajit samare śūraḥ prarūḍha iva sānumān', null, 6076020),
('ramayana-6-76-21', 21, 'Yuddha Kanda, Sarga 76, Verse 21', 'अभीक्ष्णं निश्वसन्तौ हि युध्येतां तुमुलं युधि।
शरसंकृत्तसर्वाङ्गो सर्वतो रुधिरोक्षितौ॥', 'abhīkṣṇaṃ niśvasantau hi yudhyetāṃ tumulaṃ yudhi
śarasaṃkṛttasarvāṅgo sarvato rudhirokṣitau', null, 6076021),
('ramayana-6-76-22', 22, 'Yuddha Kanda, Sarga 76, Verse 22', 'अस्त्राण्यस्त्रविदां श्रेष्ठौ दर्शयन्तौ पुनः पुनः।
शरानुच्चावचाकारानन्तरिक्षे बबन्धतुः॥', 'astrāṇy astravidāṃ śreṣṭhau darśayantau punaḥ punaḥ
śarān uccāvacākārān antarikṣe babandhatuḥ', null, 6076022),
('ramayana-6-76-23', 23, 'Yuddha Kanda, Sarga 76, Verse 23', 'व्यपेतदोषमस्यन्तौ लघुचित्रं च सुष्ठु च।
उभौ तु तुमुलं घोरं चक्रतुर्नरराक्षसौ॥', 'vyapetadoṣam asyantau laghucitraṃ ca suṣṭhu ca
ubhau tu tumulaṃ ghoraṃ cakratur nararākṣasau', null, 6076023),
('ramayana-6-76-24', 24, 'Yuddha Kanda, Sarga 76, Verse 24', 'तयोः पृथक्पृथग्भीमः शुश्रुवे तलनिस्वनः।
सुघोरयोर्निष्टनतोर्गगने मेघयोरिव॥', 'tayoḥ pṛthakpṛthag bhīmaḥ śuśruve talanisvanaḥ
sughorayor niṣṭanator gagane meghayor iva', null, 6076024),
('ramayana-6-76-25', 25, 'Yuddha Kanda, Sarga 76, Verse 25', 'ते गात्रयोर्निपतिता रुक्मपुङ्खाः शरा युधि।
असृग्दिग्धा विनिष्पेतुर्विविशुर्धरणीतलम्॥', 'te gātrayor nipatitā rukmapuṅkhāḥ śarā yudhi
asṛgdigdhā viniṣpetur viviśur dharaṇītalam', null, 6076025),
('ramayana-6-76-26', 26, 'Yuddha Kanda, Sarga 76, Verse 26', 'अन्यैः सुनिशितैः शस्त्रैराकाशे संजघट्टिरे।
बभञ्जुश्चिच्छिदुश्चापि तयोर्बाणाः सहस्रशः॥', 'anyaiḥ suniśitaiḥ śastrair ākāśe saṃjaghaṭṭire
babhañjuś cicchiduś cāpi tayor bāṇāḥ sahasraśaḥ', null, 6076026),
('ramayana-6-76-27', 27, 'Yuddha Kanda, Sarga 76, Verse 27', 'स बभूव रणे घोरस्तयोर्बाणमयश्चयः।
अग्निभ्यामिव दीप्ताभ्यां सत्रे कुशमयश्चयः॥', 'sa babhūva raṇe ghoras tayor bāṇamayaś cayaḥ
agnibhyām iva dīptābhyāṃ satre kuśamayaś cayaḥ', null, 6076027),
('ramayana-6-76-28', 28, 'Yuddha Kanda, Sarga 76, Verse 28', 'तयोः कृतव्रणौ देहौ शुशुभाते महात्मनोः।
सपुष्पाविव निष्पत्रौ वने शाल्मलिकुंशुकौ॥', 'tayoḥ kṛtavraṇau dehau śuśubhāte mahātmanoḥ
sapuṣpāv iva niṣpatrau vane śālmalikuṃśukau', null, 6076028),
('ramayana-6-76-29', 29, 'Yuddha Kanda, Sarga 76, Verse 29', 'चक्रतुस्तुमुलं घोरं संनिपातं मुहुर्मुहुः।
इन्द्रजिल्लक्ष्मणश्चैव परस्परजयैषिणौ॥', 'cakratus tumulaṃ ghoraṃ saṃnipātaṃ muhur muhuḥ
indrajil lakṣmaṇaś caiva parasparajayaiṣiṇau', null, 6076029),
('ramayana-6-76-30', 30, 'Yuddha Kanda, Sarga 76, Verse 30', 'लक्ष्मणो रावणिं युद्धे रावणिश्चापि लक्ष्मणम्।
अन्योन्यं तावभिघ्नन्तौ न श्रमं प्रत्यपद्यताम्॥', 'lakṣmaṇo rāvaṇiṃ yuddhe rāvaṇiś cāpi lakṣmaṇam
anyonyaṃ tāv abhighnantau na śramaṃ pratyapadyatām', null, 6076030),
('ramayana-6-76-31', 31, 'Yuddha Kanda, Sarga 76, Verse 31', 'बाणजालैः शरीरस्थैरवगाढैस्तरस्विनौ।
शुशुभाते महावीरौ विरूढाविव पर्वतौ॥', 'bāṇajālaiḥ śarīrasthair avagāḍhais tarasvinau
śuśubhāte mahāvīrau virūḍhāv iva parvatau', null, 6076031),
('ramayana-6-76-32', 32, 'Yuddha Kanda, Sarga 76, Verse 32', 'तयो रुधिरसिक्तानि संवृतानि शरैर्भृशम्।
बभ्राजुः सर्वगात्राणि ज्वलन्त इव पावकाः॥', 'tayo rudhirasiktāni saṃvṛtāni śarair bhṛśam
babhrājuḥ sarvagātrāṇi jvalanta iva pāvakāḥ', null, 6076032),
('ramayana-6-76-33', 33, 'Yuddha Kanda, Sarga 76, Verse 33', 'तयोरथ महान्कालो व्यतीयाद्युध्यमानयोः।
न च तौ युद्धवैमुख्यं श्रमं वाप्युपजग्मतुः॥', 'tayor atha mahān kālo vyatīyād yudhyamānayoḥ
na ca tau yuddhavaimukhyaṃ śramaṃ vāpy upajagmatuḥ', null, 6076033),
('ramayana-6-76-34', 34, 'Yuddha Kanda, Sarga 76, Verse 34', 'अथ समरपरिश्रमं निहन्तुं समरमुखेष्वजितस्य लक्ष्मणस्य।
प्रियहितमुपपादयन्महौजाः समरमुपेत्य विभीषणोऽवतस्थे॥', 'atha samarapariśramaṃ nihantuṃ samaramukheṣv ajitasya lakṣmaṇasya
priyahitam upapādayan mahaujāḥ samaram upetya vibhīṣaṇo ''vatasthe', null, 6076034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 77 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-77-1', 1, 'Yuddha Kanda, Sarga 77, Verse 1', 'युध्यमानौ तु तौ दृष्ट्वा प्रसक्तौ नरराक्षसौ।
शूरः स रावणभ्राता तस्थौ संग्राममूर्धनि॥', 'yudhyamānau tu tau dṛṣṭvā prasaktau nararākṣasau
śūraḥ sa rāvaṇabhrātā tasthau saṃgrāmamūrdhani', null, 6077001),
('ramayana-6-77-2', 2, 'Yuddha Kanda, Sarga 77, Verse 2', 'ततो विस्फारयामास महद्धनुरवस्थितः।
उत्ससर्ज च तीक्ष्णाग्रान्राक्षसेषु महाशरान्॥', 'tato visphārayām āsa mahad dhanur avasthitaḥ
utsasarja ca tīkṣṇāgrān rākṣaseṣu mahāśarān', null, 6077002),
('ramayana-6-77-3', 3, 'Yuddha Kanda, Sarga 77, Verse 3', 'ते शराः शिखिसंकाशा निपतन्तः समाहिताः।
राक्षसान्दारयामासुर्वज्रा इव महागिरीन्॥', 'te śarāḥ śikhisaṃkāśā nipatantaḥ samāhitāḥ
rākṣasān dārayām āsur vajrā iva mahāgirīn', null, 6077003),
('ramayana-6-77-4', 4, 'Yuddha Kanda, Sarga 77, Verse 4', 'विभीषणस्यानुचरास्तेऽपि शूलासिपट्टसैः।
चिच्छेदुः समरे वीरान्राक्षसान्राक्षसोत्तमाः॥', 'vibhīṣaṇasyānucarās te ''pi śūlāsipaṭṭasaiḥ
ciccheduḥ samare vīrān rākṣasān rākṣasottamāḥ', null, 6077004),
('ramayana-6-77-5', 5, 'Yuddha Kanda, Sarga 77, Verse 5', 'राक्षसैस्तैः परिवृतः स तदा तु विभीषणः।
बभौ मध्ये प्रहृष्टानां कलभानामिव द्विपः॥', 'rākṣasais taiḥ parivṛtaḥ sa tadā tu vibhīṣaṇaḥ
babhau madhye prahṛṣṭānāṃ kalabhānām iva dvipaḥ', null, 6077005),
('ramayana-6-77-6', 6, 'Yuddha Kanda, Sarga 77, Verse 6', 'ततः संचोदयानो वै हरीन्रक्षोरणप्रियान्।
उवाच वचनं काले कालज्ञो रक्षसां वरः॥', 'tataḥ saṃcodayāno vai harīn rakṣoraṇapriyān
uvāca vacanaṃ kāle kālajño rakṣasāṃ varaḥ', null, 6077006),
('ramayana-6-77-7', 7, 'Yuddha Kanda, Sarga 77, Verse 7', 'एकोऽयं राक्षसेन्द्रस्य परायणमिव स्थितः।
एतच्छेषं बलं तस्य किं तिष्ठत हरीश्वराः॥', 'eko ''yaṃ rākṣasendrasya parāyaṇam iva sthitaḥ
etac cheṣaṃ balaṃ tasya kiṃ tiṣṭhata harīśvarāḥ', null, 6077007),
('ramayana-6-77-8', 8, 'Yuddha Kanda, Sarga 77, Verse 8', 'अस्मिन्विनिहते पापे राक्षसे रणमूर्धनि।
रावणं वर्जयित्वा तु शेषमस्य बलं हतम्॥', 'asmin vinihate pāpe rākṣase raṇamūrdhani
rāvaṇaṃ varjayitvā tu śeṣam asya balaṃ hatam', null, 6077008),
('ramayana-6-77-9', 9, 'Yuddha Kanda, Sarga 77, Verse 9', 'प्रहस्तो निहतो वीरो निकुम्भश्च महाबलः।
कुम्भकर्णश्च कुम्भश्च धूम्राक्षश्च निशाचरः॥', 'prahasto nihato vīro nikumbhaś ca mahābalaḥ
kumbhakarṇaś ca kumbhaś ca dhūmrākṣaś ca niśācaraḥ', null, 6077009),
('ramayana-6-77-10', 10, 'Yuddha Kanda, Sarga 77, Verse 10', 'अकम्पनः सुपार्श्वश्च चक्रमाली च राक्षसः।
कम्पनः सत्त्ववन्तश्च देवान्तकनरान्तकौ॥', 'akampanaḥ supārśvaś ca cakramālī ca rākṣasaḥ
kampanaḥ sattvavantaś ca devāntakanarāntakau', null, 6077010),
('ramayana-6-77-11', 11, 'Yuddha Kanda, Sarga 77, Verse 11', 'एतान्निहत्यातिबलान्बहून्राक्षससत्तमान्।
बाहुभ्यां सागरं तीर्त्वा लङ्घ्यतां गोष्पदं लघु॥', 'etān nihatyātibalān bahūn rākṣasasattamān
bāhubhyāṃ sāgaraṃ tīrtvā laṅghyatāṃ goṣpadaṃ laghu', null, 6077011),
('ramayana-6-77-12', 12, 'Yuddha Kanda, Sarga 77, Verse 12', 'एतावदिह शेषं वो जेतव्यमिह वानराः।
हताः सर्वे समागम्य राक्षसा बलदर्पिताः॥', 'etāvad iha śeṣaṃ vo jetavyam iha vānarāḥ
hatāḥ sarve samāgamya rākṣasā baladarpitāḥ', null, 6077012),
('ramayana-6-77-13', 13, 'Yuddha Kanda, Sarga 77, Verse 13', 'अयुक्तं निधनं कर्तुं पुत्रस्य जनितुर्मम।
घृणामपास्य रामार्थे निहन्यां भ्रातुरात्मजम्॥', 'ayuktaṃ nidhanaṃ kartuṃ putrasya janitur mama
ghṛṇām apāsya rāmārthe nihanyāṃ bhrātur ātmajam', null, 6077013),
('ramayana-6-77-14', 14, 'Yuddha Kanda, Sarga 77, Verse 14', 'हन्तुकामस्य मे बाष्पं चक्शुश्चैव निरुध्यते।
तदेवैष महाबाहुर्लक्ष्मणः शमयिष्यति।
वानरा घ्नन्तुं संभूय भृत्यानस्य समीपगान्॥', 'hantukāmasya me bāṣpaṃ cakśuś caiva nirudhyate
tad evaiṣa mahābāhur lakṣmaṇaḥ śamayiṣyati
vānarā ghnantuṃ saṃbhūya bhṛtyān asya samīpagān', null, 6077014),
('ramayana-6-77-15', 15, 'Yuddha Kanda, Sarga 77, Verse 15', 'इति तेनातियशसा राक्षसेनाभिचोदिताः।
वानरेन्द्रा जहृषिरे लाङ्गलानि च विव्यधुः॥', 'iti tenātiyaśasā rākṣasenābhicoditāḥ
vānarendrā jahṛṣire lāṅgalāni ca vivyadhuḥ', null, 6077015),
('ramayana-6-77-16', 16, 'Yuddha Kanda, Sarga 77, Verse 16', 'ततस्ते कपिशार्दूलाः क्ष्वेडन्तश्च मुहुर्मुहुः।
मुमुचुर्विविधान्नादान्मेघान्दृष्ट्वेव बर्हिणः॥', 'tatas te kapiśārdūlāḥ kṣveḍantaś ca muhur muhuḥ
mumucur vividhān nādān meghān dṛṣṭveva barhiṇaḥ', null, 6077016),
('ramayana-6-77-17', 17, 'Yuddha Kanda, Sarga 77, Verse 17', 'जाम्बवानपि तैः सर्वैः स्वयूथैरभिसंवृतः।
अश्मभिस्ताडयामास नखैर्दन्तैश्च राक्षसान्॥', 'jāmbavān api taiḥ sarvaiḥ svayūthair abhisaṃvṛtaḥ
aśmabhis tāḍayām āsa nakhair dantaiś ca rākṣasān', null, 6077017),
('ramayana-6-77-18', 18, 'Yuddha Kanda, Sarga 77, Verse 18', 'निघ्नन्तमृक्षाधिपतिं राक्षसास्ते महाबलाः।
परिवव्रुर्भयं त्यक्त्वा तमनेकविधायुधाः॥', 'nighnantam ṛkṣādhipatiṃ rākṣasās te mahābalāḥ
parivavrur bhayaṃ tyaktvā tam anekavidhāyudhāḥ', null, 6077018),
('ramayana-6-77-19', 19, 'Yuddha Kanda, Sarga 77, Verse 19', 'शरैः परशुभिस्तीक्ष्णैः पट्टसैर्यष्टितोमरैः।
जाम्बवन्तं मृधे जघ्नुर्निघ्नन्तं राक्षसीं चमूम्॥', 'śaraiḥ paraśubhis tīkṣṇaiḥ paṭṭasair yaṣṭitomaraiḥ
jāmbavantaṃ mṛdhe jaghnur nighnantaṃ rākṣasīṃ camūm', null, 6077019),
('ramayana-6-77-20', 20, 'Yuddha Kanda, Sarga 77, Verse 20', 'स संप्रहारस्तुमुलः संजज्ञे कपिराक्षसाम्।
देवासुराणां क्रुद्धानां यथा भीमो महास्वनः॥', 'sa saṃprahāras tumulaḥ saṃjajñe kapirākṣasām
devāsurāṇāṃ kruddhānāṃ yathā bhīmo mahāsvanaḥ', null, 6077020),
('ramayana-6-77-21', 21, 'Yuddha Kanda, Sarga 77, Verse 21', 'हनूमानपि संक्रुद्धः सालमुत्पाट्य पर्वतात्।
रक्षसां कदनं चक्रे समासाद्य सहस्रशः॥', 'hanūmān api saṃkruddhaḥ sālam utpāṭya parvatāt
rakṣasāṃ kadanaṃ cakre samāsādya sahasraśaḥ', null, 6077021),
('ramayana-6-77-22', 22, 'Yuddha Kanda, Sarga 77, Verse 22', 'स दत्त्वा तुमुलं युद्धं पितृव्यस्येन्द्रजिद्युधि।
लक्ष्मणं परवीरघ्नं पुनरेवाभ्यधावत॥', 'sa dattvā tumulaṃ yuddhaṃ pitṛvyasyendrajid yudhi
lakṣmaṇaṃ paravīraghnaṃ punar evābhyadhāvata', null, 6077022),
('ramayana-6-77-23', 23, 'Yuddha Kanda, Sarga 77, Verse 23', 'तौ प्रयुद्धौ तदा वीरौ मृधे लक्ष्मणराक्षसौ।
शरौघानभिवर्षन्तौ जघ्नतुस्तौ परस्परम्॥', 'tau prayuddhau tadā vīrau mṛdhe lakṣmaṇarākṣasau
śaraughān abhivarṣantau jaghnatus tau parasparam', null, 6077023),
('ramayana-6-77-24', 24, 'Yuddha Kanda, Sarga 77, Verse 24', 'अभीक्ष्णमन्तर्दधतुः शरजालैर्महाबलौ।
चन्द्रादित्याविवोष्णान्ते यथा मेघैस्तरस्विनौ॥', 'abhīkṣṇam antardadhatuḥ śarajālair mahābalau
candrādityāv ivoṣṇānte yathā meghais tarasvinau', null, 6077024),
('ramayana-6-77-25', 25, 'Yuddha Kanda, Sarga 77, Verse 25', 'न ह्यादानं न संधानं धनुषो वा परिग्रहः।
न विप्रमोक्षो बाणानां न विकर्षो न विग्रहः॥', 'na hy ādānaṃ na saṃdhānaṃ dhanuṣo vā parigrahaḥ
na vipramokṣo bāṇānāṃ na vikarṣo na vigrahaḥ', null, 6077025),
('ramayana-6-77-26', 26, 'Yuddha Kanda, Sarga 77, Verse 26', 'न मुष्टिप्रतिसंधानं न लक्ष्यप्रतिपादनम्।
अदृश्यत तयोस्तत्र युध्यतोः पाणिलाघवात्॥', 'na muṣṭipratisaṃdhānaṃ na lakṣyapratipādanam
adṛśyata tayos tatra yudhyatoḥ pāṇilāghavāt', null, 6077026),
('ramayana-6-77-27', 27, 'Yuddha Kanda, Sarga 77, Verse 27', 'चापवेगप्रमुक्तैश्च बाणजालैः समन्ततः।
अन्तरिक्षेऽभिसंछन्ने न रूपाणि चकाशिरे।
तमसा पिहितं सर्वमासीद्भीमतरं महत्॥', 'cāpavegapramuktaiś ca bāṇajālaiḥ samantataḥ
antarikṣe ''bhisaṃchanne na rūpāṇi cakāśire
tamasā pihitaṃ sarvam āsīd bhīmataraṃ mahat', null, 6077027),
('ramayana-6-77-28', 28, 'Yuddha Kanda, Sarga 77, Verse 28', 'न तदानीं ववौ वायुर्न जज्वाल च पावकः।
स्वस्त्यस्तु लोकेभ्य इति जजल्पश्च महर्षयः।
संपेतुश्चात्र संप्राप्ता गन्धर्वाः सह चारणैः॥', 'na tadānīṃ vavau vāyur na jajvāla ca pāvakaḥ
svastyas tu lokebhya iti jajalpaś ca maharṣayaḥ
saṃpetuś cātra saṃprāptā gandharvāḥ saha cāraṇaiḥ', null, 6077028),
('ramayana-6-77-29', 29, 'Yuddha Kanda, Sarga 77, Verse 29', 'अथ राक्षससिंहस्य कृष्णान्कनकभूषणान्।
शरैश्चतुर्भिः सौमित्रिर्विव्याध चतुरो हयान्॥', 'atha rākṣasasiṃhasya kṛṣṇān kanakabhūṣaṇān
śaraiś caturbhiḥ saumitrir vivyādha caturo hayān', null, 6077029),
('ramayana-6-77-30', 30, 'Yuddha Kanda, Sarga 77, Verse 30', 'ततोऽपरेण भल्लेन सूतस्य विचरिष्यतः।
लाघवाद्राघवः श्रीमाञ्शिरः कायादपाहरत्॥', 'tato ''pareṇa bhallena sūtasya vicariṣyataḥ
lāghavād rāghavaḥ śrīmāñ śiraḥ kāyād apāharat', null, 6077030),
('ramayana-6-77-31', 31, 'Yuddha Kanda, Sarga 77, Verse 31', 'निहतं सारथिं दृष्ट्वा समरे रावणात्मजः।
प्रजहौ समरोद्धर्षं विषण्णः स बभूव ह॥', 'nihataṃ sārathiṃ dṛṣṭvā samare rāvaṇātmajaḥ
prajahau samaroddharṣaṃ viṣaṇṇaḥ sa babhūva ha', null, 6077031),
('ramayana-6-77-32', 32, 'Yuddha Kanda, Sarga 77, Verse 32', 'विषण्णवदनं दृष्ट्वा राक्षसं हरियूथपाः।
ततः परमसंहृष्टो लक्ष्मणं चाभ्यपूजयन्॥', 'viṣaṇṇavadanaṃ dṛṣṭvā rākṣasaṃ hariyūthapāḥ
tataḥ paramasaṃhṛṣṭo lakṣmaṇaṃ cābhyapūjayan', null, 6077032),
('ramayana-6-77-33', 33, 'Yuddha Kanda, Sarga 77, Verse 33', 'ततः प्रमाथी शरभो रभसो गन्धमादनः।
अमृष्यमाणाश्चत्वारश्चक्रुर्वेगं हरीश्वराः॥', 'tataḥ pramāthī śarabho rabhaso gandhamādanaḥ
amṛṣyamāṇāś catvāraś cakrur vegaṃ harīśvarāḥ', null, 6077033),
('ramayana-6-77-34', 34, 'Yuddha Kanda, Sarga 77, Verse 34', 'ते चास्य हयमुख्येषु तूर्णमुत्पत्य वानराः।
चतुर्षु सुमहावीर्या निपेतुर्भीमविक्रमाः॥', 'te cāsya hayamukhyeṣu tūrṇam utpatya vānarāḥ
caturṣu sumahāvīryā nipetur bhīmavikramāḥ', null, 6077034),
('ramayana-6-77-35', 35, 'Yuddha Kanda, Sarga 77, Verse 35', 'तेषामधिष्ठितानां तैर्वानरैः पर्वतोपमैः।
मुखेभ्यो रुधिरं व्यक्तं हयानां समवर्तत॥', 'teṣām adhiṣṭhitānāṃ tair vānaraiḥ parvatopamaiḥ
mukhebhyo rudhiraṃ vyaktaṃ hayānāṃ samavartata', null, 6077035),
('ramayana-6-77-36', 36, 'Yuddha Kanda, Sarga 77, Verse 36', 'ते निहत्य हयांस्तस्य प्रमथ्य च महारथम्।
पुनरुत्पत्य वेगेन तस्थुर्लक्ष्मणपार्श्वतः॥', 'te nihatya hayāṃs tasya pramathya ca mahāratham
punar utpatya vegena tasthur lakṣmaṇapārśvataḥ', null, 6077036),
('ramayana-6-77-37', 37, 'Yuddha Kanda, Sarga 77, Verse 37', 'स हताश्वादवप्लुत्य रथान्मथितसारथेः।
शरवर्षेण सौमित्रिमभ्यधावत रावणिः॥', 'sa hatāśvād avaplutya rathān mathitasāratheḥ
śaravarṣeṇa saumitrim abhyadhāvata rāvaṇiḥ', null, 6077037),
('ramayana-6-77-38', 38, 'Yuddha Kanda, Sarga 77, Verse 38', 'ततो महेन्द्रप्रतिमः स लक्ष्मणः पदातिनं तं निशितैः शरोत्तमैः।
सृजन्तमादौ निशिताञ्शरोत्तमान्भृशं तदा बाणगणैर्न्यवारयत्॥', 'tato mahendrapratimaḥ sa lakṣmaṇaḥ padātinaṃ taṃ niśitaiḥ śarottamaiḥ
sṛjantam ādau niśitāñ śarottamān bhṛśaṃ tadā bāṇagaṇair nyavārayat', null, 6077038)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 78 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-78-1', 1, 'Yuddha Kanda, Sarga 78, Verse 1', 'स हताश्वो महातेजा भूमौ तिष्ठन्निशाचरः।
इन्द्रजित्परमक्रुद्धः संप्रजज्वाल तेजसा॥', 'sa hatāśvo mahātejā bhūmau tiṣṭhan niśācaraḥ
indrajit paramakruddhaḥ saṃprajajvāla tejasā', null, 6078001),
('ramayana-6-78-2', 2, 'Yuddha Kanda, Sarga 78, Verse 2', 'तौ धन्विनौ जिघांसन्तावन्योन्यमिषुभिर्भृशम्।
विजयेनाभिनिष्क्रान्तौ वने गजवृषाविव॥', 'tau dhanvinau jighāṃsantāv anyonyam iṣubhir bhṛśam
vijayenābhiniṣkrāntau vane gajavṛṣāv iva', null, 6078002),
('ramayana-6-78-3', 3, 'Yuddha Kanda, Sarga 78, Verse 3', 'निबर्हयन्तश्चान्योन्यं ते राक्षसवनौकसः।
भर्तारं न जहुर्युद्धे संपतन्तस्ततस्ततः॥', 'nibarhayantaś cānyonyaṃ te rākṣasavanaukasaḥ
bhartāraṃ na jahur yuddhe saṃpatantas tatas tataḥ', null, 6078003),
('ramayana-6-78-4', 4, 'Yuddha Kanda, Sarga 78, Verse 4', 'स लक्ष्मणं समुद्दिश्य परं लाघवमास्थितः।
ववर्ष शरवर्षाणि वर्षाणीव पुरंदरः॥', 'sa lakṣmaṇaṃ samuddiśya paraṃ lāghavam āsthitaḥ
vavarṣa śaravarṣāṇi varṣāṇīva puraṃdaraḥ', null, 6078004),
('ramayana-6-78-5', 5, 'Yuddha Kanda, Sarga 78, Verse 5', 'मुक्तमिन्द्रजिता तत्तु शरवर्षमरिंदमः।
अवारयदसंभ्रान्तो लक्ष्मणः सुदुरासदम्॥', 'muktam indrajitā tat tu śaravarṣam ariṃdamaḥ
avārayad asaṃbhrānto lakṣmaṇaḥ sudurāsadam', null, 6078005),
('ramayana-6-78-6', 6, 'Yuddha Kanda, Sarga 78, Verse 6', 'अभेद्यकचनं मत्वा लक्ष्मणं रावणात्मजः।
ललाटे लक्ष्मणं बाणैः सुपुङ्खैस्त्रिभिरिन्द्रजित्।
अविध्यत्परमक्रुद्धः शीघ्रमस्त्रं प्रदर्शयन्॥', 'abhedyakacanaṃ matvā lakṣmaṇaṃ rāvaṇātmajaḥ
lalāṭe lakṣmaṇaṃ bāṇaiḥ supuṅkhais tribhir indrajit
avidhyat paramakruddhaḥ śīghram astraṃ pradarśayan', null, 6078006),
('ramayana-6-78-7', 7, 'Yuddha Kanda, Sarga 78, Verse 7', 'तैः पृषत्कैर्ललाटस्थैः शुशुभे रघुनन्दनः।
रणाग्रे समरश्लाघी त्रिशृङ्ग इव पर्वतः॥', 'taiḥ pṛṣatkair lalāṭasthaiḥ śuśubhe raghunandanaḥ
raṇāgre samaraślāghī triśṛṅga iva parvataḥ', null, 6078007),
('ramayana-6-78-8', 8, 'Yuddha Kanda, Sarga 78, Verse 8', 'स तथाप्यर्दितो बाणै राक्षसेन महामृधे।
तमाशु प्रतिविव्याध लक्ष्मणः पनभिः शरैः॥', 'sa tathāpy ardito bāṇai rākṣasena mahāmṛdhe
tam āśu prativivyādha lakṣmaṇaḥ panabhiḥ śaraiḥ', null, 6078008),
('ramayana-6-78-9', 9, 'Yuddha Kanda, Sarga 78, Verse 9', 'लक्ष्मणेन्द्रजितौ वीरौ महाबलशरासनौ।
अन्योन्यं जघ्नतुर्बाणैर्विशिखैर्भीमविक्रमौ॥', 'lakṣmaṇendrajitau vīrau mahābalaśarāsanau
anyonyaṃ jaghnatur bāṇair viśikhair bhīmavikramau', null, 6078009),
('ramayana-6-78-10', 10, 'Yuddha Kanda, Sarga 78, Verse 10', 'तौ परस्परमभ्येत्य सर्वगात्रेषु धन्विनौ।
घोरैर्विव्यधतुर्बाणैः कृतभावावुभौ जये॥', 'tau parasparam abhyetya sarvagātreṣu dhanvinau
ghorair vivyadhatur bāṇaiḥ kṛtabhāvāv ubhau jaye', null, 6078010),
('ramayana-6-78-11', 11, 'Yuddha Kanda, Sarga 78, Verse 11', 'तस्मै दृढतरं क्रुद्धो हताश्वाय विभीषणः।
वज्रस्पर्शसमान्पञ्च ससर्जोरसि मार्गणान्॥', 'tasmai dṛḍhataraṃ kruddho hatāśvāya vibhīṣaṇaḥ
vajrasparśasamān pañca sasarjorasi mārgaṇān', null, 6078011),
('ramayana-6-78-12', 12, 'Yuddha Kanda, Sarga 78, Verse 12', 'ते तस्य कायं निर्भिद्य रुक्मपुङ्खा निमित्तगाः।
बभूवुर्लोहितादिग्धा रक्ता इव महोरगाः॥', 'te tasya kāyaṃ nirbhidya rukmapuṅkhā nimittagāḥ
babhūvur lohitādigdhā raktā iva mahoragāḥ', null, 6078012),
('ramayana-6-78-13', 13, 'Yuddha Kanda, Sarga 78, Verse 13', 'स पितृव्यस्य संक्रुद्ध इन्द्रजिच्छरमाददे।
उत्तमं रक्षसां मध्ये यमदत्तं महाबलः॥', 'sa pitṛvyasya saṃkruddha indrajic charam ādade
uttamaṃ rakṣasāṃ madhye yamadattaṃ mahābalaḥ', null, 6078013),
('ramayana-6-78-14', 14, 'Yuddha Kanda, Sarga 78, Verse 14', 'तं समीक्ष्य महातेजा महेषुं तेन संहितम्।
लक्ष्मणोऽप्याददे बाणमन्यं भीमपराक्रमः॥', 'taṃ samīkṣya mahātejā maheṣuṃ tena saṃhitam
lakṣmaṇo ''py ādade bāṇam anyaṃ bhīmaparākramaḥ', null, 6078014),
('ramayana-6-78-15', 15, 'Yuddha Kanda, Sarga 78, Verse 15', 'कुबेरेण स्वयं स्वप्ने यद्दत्तममितात्मना।
दुर्जयं दुर्विषह्यं च सेन्द्रैरपि सुरासुरैः॥', 'kubereṇa svayaṃ svapne yad dattam amitātmanā
durjayaṃ durviṣahyaṃ ca sendrair api surāsuraiḥ', null, 6078015),
('ramayana-6-78-16', 16, 'Yuddha Kanda, Sarga 78, Verse 16', 'ताभ्यां तौ धनुषि श्रेष्ठे संहितौ सायकोत्तमौ।
विकृष्यमाणौ वीराभ्यां भृशं जज्वलतुः श्रिया॥', 'tābhyāṃ tau dhanuṣi śreṣṭhe saṃhitau sāyakottamau
vikṛṣyamāṇau vīrābhyāṃ bhṛśaṃ jajvalatuḥ śriyā', null, 6078016),
('ramayana-6-78-17', 17, 'Yuddha Kanda, Sarga 78, Verse 17', 'तौ भासयन्तावाकाशं धनुर्भ्यां विशिखौ च्युतौ।
मुखेन मुखमाहत्य संनिपेततुरोजसा॥', 'tau bhāsayantāv ākāśaṃ dhanurbhyāṃ viśikhau cyutau
mukhena mukham āhatya saṃnipetatur ojasā', null, 6078017),
('ramayana-6-78-18', 18, 'Yuddha Kanda, Sarga 78, Verse 18', 'तौ महाग्रहसंकाशावन्योन्यं संनिपत्य च।
संग्रामे शतधा यातौ मेदिन्यां विनिपेततुः॥', 'tau mahāgrahasaṃkāśāv anyonyaṃ saṃnipatya ca
saṃgrāme śatadhā yātau medinyāṃ vinipetatuḥ', null, 6078018),
('ramayana-6-78-19', 19, 'Yuddha Kanda, Sarga 78, Verse 19', 'शरौ प्रतिहतौ दृष्ट्वा तावुभौ रणमूर्धनि।
व्रीडितो जातरोषौ च लक्ष्मणेन्द्रजितावुभौ॥', 'śarau pratihatau dṛṣṭvā tāv ubhau raṇamūrdhani
vrīḍito jātaroṣau ca lakṣmaṇendrajitāv ubhau', null, 6078019),
('ramayana-6-78-20', 20, 'Yuddha Kanda, Sarga 78, Verse 20', 'सुसंरब्धस्तु सौमित्रिरस्त्रं वारुणमाददे।
रौद्रं महेद्रजिद्युद्धे व्यसृजद्युधि विष्ठितः॥', 'susaṃrabdhas tu saumitrir astraṃ vāruṇam ādade
raudraṃ mahedrajid yuddhe vyasṛjad yudhi viṣṭhitaḥ', null, 6078020),
('ramayana-6-78-21', 21, 'Yuddha Kanda, Sarga 78, Verse 21', 'तयोः सुतुमुलं युद्धं संबभूवाद्भुतोपमम्।
गगनस्थानि भूतानि लक्ष्मणं पर्यवारयन्॥', 'tayoḥ sutumulaṃ yuddhaṃ saṃbabhūvādbhutopamam
gaganasthāni bhūtāni lakṣmaṇaṃ paryavārayan', null, 6078021),
('ramayana-6-78-22', 22, 'Yuddha Kanda, Sarga 78, Verse 22', 'भैरवाभिरुते भीमे युद्धे वानरराक्षसाम्।
भूतैर्बहुभिराकाशं विस्मितैरावृतं बभौ॥', 'bhairavābhirute bhīme yuddhe vānararākṣasām
bhūtair bahubhir ākāśaṃ vismitair āvṛtaṃ babhau', null, 6078022),
('ramayana-6-78-23', 23, 'Yuddha Kanda, Sarga 78, Verse 23', 'ऋषयः पितरो देवा गन्धर्वा गरुणोरगाः।
शतक्रतुं पुरस्कृत्य ररक्षुर्लक्ष्मणं रणे॥', 'ṛṣayaḥ pitaro devā gandharvā garuṇoragāḥ
śatakratuṃ puraskṛtya rarakṣur lakṣmaṇaṃ raṇe', null, 6078023),
('ramayana-6-78-24', 24, 'Yuddha Kanda, Sarga 78, Verse 24', 'अथान्यं मार्गणश्रेष्ठं संदधे रावणानुजः।
हुताशनसमस्पर्शं रावणात्मजदारुणम्॥', 'athānyaṃ mārgaṇaśreṣṭhaṃ saṃdadhe rāvaṇānujaḥ
hutāśanasamasparśaṃ rāvaṇātmajadāruṇam', null, 6078024),
('ramayana-6-78-25', 25, 'Yuddha Kanda, Sarga 78, Verse 25', 'सुपत्रमनुवृत्ताङ्गं सुपर्वाणं सुसंस्थितम्।
सुवर्णविकृतं वीरः शरीरान्तकरं शरम्॥', 'supatram anuvṛttāṅgaṃ suparvāṇaṃ susaṃsthitam
suvarṇavikṛtaṃ vīraḥ śarīrāntakaraṃ śaram', null, 6078025),
('ramayana-6-78-26', 26, 'Yuddha Kanda, Sarga 78, Verse 26', 'दुरावारं दुर्विषहं राक्षसानां भयावहम्।
आशीविषविषप्रख्यं देवसंघैः समर्चितम्॥', 'durāvāraṃ durviṣahaṃ rākṣasānāṃ bhayāvaham
āśīviṣaviṣaprakhyaṃ devasaṃghaiḥ samarcitam', null, 6078026),
('ramayana-6-78-27', 27, 'Yuddha Kanda, Sarga 78, Verse 27', 'येन शक्रो महातेजा दानवानजयत्प्रभुः।
पुरा देवासुरे युद्धे वीर्यवान्हरिवाहनः॥', 'yena śakro mahātejā dānavān ajayat prabhuḥ
purā devāsure yuddhe vīryavān harivāhanaḥ', null, 6078027),
('ramayana-6-78-28', 28, 'Yuddha Kanda, Sarga 78, Verse 28', 'तदैन्द्रमस्त्रं सौमित्रिः संयुगेष्वपराजितम्।
शरश्रेष्ठं धनुः श्रेष्ठे नरश्रेष्ठोऽभिसंदधे॥', 'tad aindram astraṃ saumitriḥ saṃyugeṣv aparājitam
śaraśreṣṭhaṃ dhanuḥ śreṣṭhe naraśreṣṭho ''bhisaṃdadhe', null, 6078028),
('ramayana-6-78-29', 29, 'Yuddha Kanda, Sarga 78, Verse 29', 'संधायामित्रदलनं विचकर्ष शरासनम्।
सज्यमायम्य दुर्धर्शः कालो लोकक्षये यथा॥', 'saṃdhāyāmitradalanaṃ vicakarṣa śarāsanam
sajyam āyamya durdharśaḥ kālo lokakṣaye yathā', null, 6078029),
('ramayana-6-78-30', 30, 'Yuddha Kanda, Sarga 78, Verse 30', 'संधाय धनुषि श्रेष्ठे विकर्षन्निदमब्रवीत्।
लक्ष्मीवांल्लक्ष्मणो वाक्यमर्थसाधकमात्मनः॥', 'saṃdhāya dhanuṣi śreṣṭhe vikarṣann idam abravīt
lakṣmīvāṃl lakṣmaṇo vākyam arthasādhakam ātmanaḥ', null, 6078030),
('ramayana-6-78-31', 31, 'Yuddha Kanda, Sarga 78, Verse 31', 'धर्मात्मा सत्यसंधश्च रामो दाशरथिर्यदि।
पौरुषे चाप्रतिद्वन्द्वस्तदेनं जहि रावणिम्॥', 'dharmātmā satyasaṃdhaś ca rāmo dāśarathir yadi
pauruṣe cāpratidvandvas tad enaṃ jahi rāvaṇim', null, 6078031),
('ramayana-6-78-32', 32, 'Yuddha Kanda, Sarga 78, Verse 32', 'इत्युक्त्वा बाणमाकर्णं विकृष्य तमजिह्मगम्।
लक्ष्मणः समरे वीरः ससर्जेन्द्रजितं प्रति।
ऐन्द्रास्त्रेण समायुज्य लक्ष्मणः परवीरहा॥', 'ity uktvā bāṇam ākarṇaṃ vikṛṣya tam ajihmagam
lakṣmaṇaḥ samare vīraḥ sasarjendrajitaṃ prati
aindrāstreṇa samāyujya lakṣmaṇaḥ paravīrahā', null, 6078032),
('ramayana-6-78-33', 33, 'Yuddha Kanda, Sarga 78, Verse 33', 'तच्छिरः सशिरस्त्राणं श्रीमज्ज्वलितकुण्डलम्।
प्रमथ्येन्द्रजितः कायात्पपात धरणीतले॥', 'tac chiraḥ saśiras trāṇaṃ śrīmaj jvalitakuṇḍalam
pramathyendrajitaḥ kāyāt papāta dharaṇītale', null, 6078033),
('ramayana-6-78-34', 34, 'Yuddha Kanda, Sarga 78, Verse 34', 'तद्राक्षसतनूजस्य छिन्नस्कन्धं शिरो महत्।
तपनीयनिभं भूमौ ददृशे रुधिरोक्षितम्॥', 'tad rākṣasatanūjasya chinnaskandhaṃ śiro mahat
tapanīyanibhaṃ bhūmau dadṛśe rudhirokṣitam', null, 6078034),
('ramayana-6-78-35', 35, 'Yuddha Kanda, Sarga 78, Verse 35', 'हतस्तु निपपाताशु धरण्यां रावणात्मजः।
कवची सशिरस्त्राणो विध्वस्तः सशरासनः॥', 'hatas tu nipapātāśu dharaṇyāṃ rāvaṇātmajaḥ
kavacī saśirastrāṇo vidhvastaḥ saśarāsanaḥ', null, 6078035),
('ramayana-6-78-36', 36, 'Yuddha Kanda, Sarga 78, Verse 36', 'चुक्रुशुस्ते ततः सर्वे वानराः सविभीषणाः।
हृष्यन्तो निहते तस्मिन्देवा वृत्रवधे यथा॥', 'cukruśus te tataḥ sarve vānarāḥ savibhīṣaṇāḥ
hṛṣyanto nihate tasmin devā vṛtravadhe yathā', null, 6078036),
('ramayana-6-78-37', 37, 'Yuddha Kanda, Sarga 78, Verse 37', 'अथान्तरिक्षे भूतानामृषीणां च महात्मनाम्।
अभिजज्ञे च संनादो गन्धर्वाप्सरसामपि॥', 'athāntarikṣe bhūtānām ṛṣīṇāṃ ca mahātmanām
abhijajñe ca saṃnādo gandharvāpsarasām api', null, 6078037),
('ramayana-6-78-38', 38, 'Yuddha Kanda, Sarga 78, Verse 38', 'पतितं समभिज्ञाय राक्षसी सा महाचमूः।
वध्यमाना दिशो भेजे हरिभिर्जितकाशिभिः॥', 'patitaṃ samabhijñāya rākṣasī sā mahācamūḥ
vadhyamānā diśo bheje haribhir jitakāśibhiḥ', null, 6078038),
('ramayana-6-78-39', 39, 'Yuddha Kanda, Sarga 78, Verse 39', 'वनरैर्वध्यमानास्ते शस्त्राण्युत्सृज्य राक्षसाः।
लङ्कामभिमुखाः सर्वे नष्टसंज्ञाः प्रधाविताः॥', 'vanarair vadhyamānās te śastrāṇy utsṛjya rākṣasāḥ
laṅkām abhimukhāḥ sarve naṣṭasaṃjñāḥ pradhāvitāḥ', null, 6078039),
('ramayana-6-78-40', 40, 'Yuddha Kanda, Sarga 78, Verse 40', 'दुद्रुवुर्बहुधा भीता राक्षसाः शतशो दिशः।
त्यक्त्वा प्रहरणान्सर्वे पट्टसासिपरश्वधान्॥', 'dudruvur bahudhā bhītā rākṣasāḥ śataśo diśaḥ
tyaktvā praharaṇān sarve paṭṭasāsiparaśvadhān', null, 6078040),
('ramayana-6-78-41', 41, 'Yuddha Kanda, Sarga 78, Verse 41', 'के चिल्लङ्कां परित्रस्ताः प्रविष्टा वानरार्दिताः।
समुद्रे पतिताः के चित्के चित्पर्वतमाश्रिताः॥', 'ke cil laṅkāṃ paritrastāḥ praviṣṭā vānarārditāḥ
samudre patitāḥ ke cit ke cit parvatam āśritāḥ', null, 6078041),
('ramayana-6-78-42', 42, 'Yuddha Kanda, Sarga 78, Verse 42', 'हतमिन्द्रजितं दृष्ट्वा शयानं समरक्षितौ।
राक्षसानां सहस्रेषु न कश्चित्प्रत्यदृश्यत॥', 'hatam indrajitaṃ dṛṣṭvā śayānaṃ samarakṣitau
rākṣasānāṃ sahasreṣu na kaś cit pratyadṛśyata', null, 6078042),
('ramayana-6-78-43', 43, 'Yuddha Kanda, Sarga 78, Verse 43', 'यथास्तं गत आदित्ये नावतिष्ठन्ति रश्मयः।
तथा तस्मिन्निपतिते राक्षसास्ते गता दिशः॥', 'yathāstaṃ gata āditye nāvatiṣṭhanti raśmayaḥ
tathā tasmin nipatite rākṣasās te gatā diśaḥ', null, 6078043),
('ramayana-6-78-44', 44, 'Yuddha Kanda, Sarga 78, Verse 44', 'शान्तरक्श्मिरिवादित्यो निर्वाण इव पावकः।
स बभूव महातेजा व्यपास्त गतजीवितः॥', 'śāntarakśmir ivādityo nirvāṇa iva pāvakaḥ
sa babhūva mahātejā vyapāsta gatajīvitaḥ', null, 6078044),
('ramayana-6-78-45', 45, 'Yuddha Kanda, Sarga 78, Verse 45', 'प्रशान्तपीडा बहुलो विनष्टारिः प्रहर्षवान्।
बभूव लोकः पतिते राक्षसेन्द्रसुते तदा॥', 'praśāntapīḍā bahulo vinaṣṭāriḥ praharṣavān
babhūva lokaḥ patite rākṣasendrasute tadā', null, 6078045),
('ramayana-6-78-46', 46, 'Yuddha Kanda, Sarga 78, Verse 46', 'हर्षं च शक्रो भगवान्सह सर्वैः सुरर्षभैः।
जगाम निहते तस्मिन्राक्षसे पापकर्मणि॥', 'harṣaṃ ca śakro bhagavān saha sarvaiḥ surarṣabhaiḥ
jagāma nihate tasmin rākṣase pāpakarmaṇi', null, 6078046),
('ramayana-6-78-47', 47, 'Yuddha Kanda, Sarga 78, Verse 47', 'शुद्धा आपो नभश्चैव जहृषुर्दैत्यदानवाः।
आजग्मुः पतिते तस्मिन्सर्वलोकभयावहे॥', 'śuddhā āpo nabhaś caiva jahṛṣur daityadānavāḥ
ājagmuḥ patite tasmin sarvalokabhayāvahe', null, 6078047),
('ramayana-6-78-48', 48, 'Yuddha Kanda, Sarga 78, Verse 48', 'ऊचुश्च सहिताः सर्वे देवगन्धर्वदानवाः।
विज्वराः शान्तकलुषा ब्राह्मणा विचरन्त्विति॥', 'ūcuś ca sahitāḥ sarve devagandharvadānavāḥ
vijvarāḥ śāntakaluṣā brāhmaṇā vicarantv iti', null, 6078048),
('ramayana-6-78-49', 49, 'Yuddha Kanda, Sarga 78, Verse 49', 'ततोऽभ्यनन्दन्संहृष्टाः समरे हरियूथपाः।
तमप्रतिबलं दृष्ट्वा हतं नैरृतपुंगवम्॥', 'tato ''bhyanandan saṃhṛṣṭāḥ samare hariyūthapāḥ
tam apratibalaṃ dṛṣṭvā hataṃ nairṛtapuṃgavam', null, 6078049),
('ramayana-6-78-50', 50, 'Yuddha Kanda, Sarga 78, Verse 50', 'विभीषणो हनूमांश्च जाम्बवांश्चर्क्षयूथपः।
विजयेनाभिनन्दन्तस्तुष्टुवुश्चापि लक्ष्मणम्॥', 'vibhīṣaṇo hanūmāṃś ca jāmbavāṃś carkṣayūthapaḥ
vijayenābhinandantas tuṣṭuvuś cāpi lakṣmaṇam', null, 6078050),
('ramayana-6-78-51', 51, 'Yuddha Kanda, Sarga 78, Verse 51', 'क्ष्वेडन्तश्च नदन्तश्च गर्जन्तश्च प्लवंगमाः।
लब्धलक्षा रघुसुतं परिवार्योपतस्थिरे॥', 'kṣveḍantaś ca nadantaś ca garjantaś ca plavaṃgamāḥ
labdhalakṣā raghusutaṃ parivāryopatasthire', null, 6078051),
('ramayana-6-78-52', 52, 'Yuddha Kanda, Sarga 78, Verse 52', 'लाङ्गूलानि प्रविध्यन्तः स्फोटयन्तश्च वानराः।
लक्ष्मणो जयतीत्येवं वाक्यं व्यश्रावयंस्तदा॥', 'lāṅgūlāni pravidhyantaḥ sphoṭayantaś ca vānarāḥ
lakṣmaṇo jayatīty evaṃ vākyaṃ vyaśrāvayaṃs tadā', null, 6078052),
('ramayana-6-78-53', 53, 'Yuddha Kanda, Sarga 78, Verse 53', 'अन्योन्यं च समाश्लिष्य कपयो हृष्टमानसाः।
चक्रुरुच्चावचगुणा राघवाश्रयजाः कथाः॥', 'anyonyaṃ ca samāśliṣya kapayo hṛṣṭamānasāḥ
cakrur uccāvacaguṇā rāghavāśrayajāḥ kathāḥ', null, 6078053),
('ramayana-6-78-54', 54, 'Yuddha Kanda, Sarga 78, Verse 54', 'तदसुकरमथाभिवीक्ष्य हृष्टाः प्रियसुहृदो युधि लक्ष्मणस्य कर्म।
परममुपलभन्मनःप्रहर्षं विनिहतमिन्द्ररिपुं निशम्य देवाः॥', 'tad asukaram athābhivīkṣya hṛṣṭāḥ priyasuhṛdo yudhi lakṣmaṇasya karma
paramam upalabhan manaḥpraharṣaṃ vinihatam indraripuṃ niśamya devāḥ', null, 6078054)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 79 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-79-1', 1, 'Yuddha Kanda, Sarga 79, Verse 1', 'रुधिरक्लिन्नगात्रस्तु लक्ष्मणः शुभलक्षणः।
बभूव हृष्टस्तं हत्वा शक्रजेतारमाहवे॥', 'rudhiraklinnagātras tu lakṣmaṇaḥ śubhalakṣaṇaḥ
babhūva hṛṣṭas taṃ hatvā śakrajetāram āhave', null, 6079001),
('ramayana-6-79-2', 2, 'Yuddha Kanda, Sarga 79, Verse 2', 'ततः स जाम्बवन्तं च हनूमन्तं च वीर्यवान्।
संनिवर्त्य महातेजास्तांश्च सर्वान्वनौकसः॥', 'tataḥ sa jāmbavantaṃ ca hanūmantaṃ ca vīryavān
saṃnivartya mahātejās tāṃś ca sarvān vanaukasaḥ', null, 6079002),
('ramayana-6-79-3', 3, 'Yuddha Kanda, Sarga 79, Verse 3', 'आजगाम ततः शीघ्रं यत्र सुग्रीवराघवौ।
विभीषणमवष्टभ्य हनूमन्तं च लक्ष्मणः॥', 'ājagāma tataḥ śīghraṃ yatra sugrīvarāghavau
vibhīṣaṇam avaṣṭabhya hanūmantaṃ ca lakṣmaṇaḥ', null, 6079003),
('ramayana-6-79-4', 4, 'Yuddha Kanda, Sarga 79, Verse 4', 'ततो राममभिक्रम्य सौमित्रिरभिवाद्य च।
तस्थौ भ्रातृसमीपस्थः शक्रस्येन्द्रानुजो यथा।
आचचक्षे तदा वीरो घोरमिन्द्रजितो वधम्॥', 'tato rāmam abhikramya saumitrir abhivādya ca
tasthau bhrātṛsamīpasthaḥ śakrasyendrānujo yathā
ācacakṣe tadā vīro ghoram indrajito vadham', null, 6079004),
('ramayana-6-79-5', 5, 'Yuddha Kanda, Sarga 79, Verse 5', 'रावणस्तु शिरश्छिन्नं लक्ष्मणेन महात्मना।
न्यवेदयत रामाय तदा हृष्टो विभीषणः॥', 'rāvaṇas tu śiraś chinnaṃ lakṣmaṇena mahātmanā
nyavedayata rāmāya tadā hṛṣṭo vibhīṣaṇaḥ', null, 6079005),
('ramayana-6-79-6', 6, 'Yuddha Kanda, Sarga 79, Verse 6', 'उपवेश्य तमुत्सङ्गे परिष्वज्यावपीडितम्।
मूर्ध्नि चैनमुपाघ्राय भूयः संस्पृश्य च त्वरन्।
उवाच लक्ष्मणं वाक्यमाश्वास्य पुरुषर्षभः॥', 'upaveśya tam utsaṅge pariṣvajyāvapīḍitam
mūrdhni cainam upāghrāya bhūyaḥ saṃspṛśya ca tvaran
uvāca lakṣmaṇaṃ vākyam āśvāsya puruṣarṣabhaḥ', null, 6079006),
('ramayana-6-79-7', 7, 'Yuddha Kanda, Sarga 79, Verse 7', 'कृतं परमकल्याणं कर्म दुष्करकारिणा।
निरमित्रः कृतोऽस्म्यद्य निर्यास्यति हि रावणः।
बलव्यूहेन महता श्रुत्वा पुत्रं निपातितम्॥', 'kṛtaṃ paramakalyāṇaṃ karma duṣkarakāriṇā
niramitraḥ kṛto ''smy adya niryāsyati hi rāvaṇaḥ
balavyūhena mahatā śrutvā putraṃ nipātitam', null, 6079007),
('ramayana-6-79-8', 8, 'Yuddha Kanda, Sarga 79, Verse 8', 'तं पुत्रवधसंतप्तं निर्यान्तं राक्षसाधिपम्।
बलेनावृत्य महता निहनिष्यामि दुर्जयम्॥', 'taṃ putravadhasaṃtaptaṃ niryāntaṃ rākṣasādhipam
balenāvṛtya mahatā nihaniṣyāmi durjayam', null, 6079008),
('ramayana-6-79-9', 9, 'Yuddha Kanda, Sarga 79, Verse 9', 'त्वया लक्ष्मण नाथेन सीता च पृथिवी च मे।
न दुष्प्रापा हते त्वद्य शक्रजेतरि चाहवे॥', 'tvayā lakṣmaṇa nāthena sītā ca pṛthivī ca me
na duṣprāpā hate tv adya śakrajetari cāhave', null, 6079009),
('ramayana-6-79-10', 10, 'Yuddha Kanda, Sarga 79, Verse 10', 'स तं भ्रातरमाश्वास्य पारिष्वज्य च राघवः।
रामः सुषेणं मुदितः समाभाष्येदमब्रवीत्॥', 'sa taṃ bhrātaram āśvāsya pāriṣvajya ca rāghavaḥ
rāmaḥ suṣeṇaṃ muditaḥ samābhāṣyedam abravīt', null, 6079010),
('ramayana-6-79-11', 11, 'Yuddha Kanda, Sarga 79, Verse 11', 'सशल्योऽयं महाप्राज्ञः सौमित्रिर्मित्रवत्सलः।
यथा भवति सुस्वस्थस्तथा त्वं समुपाचर।
विशल्यः क्रियतां क्षिप्रं सौमित्रिः सविभीषणः॥', 'saśalyo ''yaṃ mahāprājñaḥ saumitrir mitravatsalaḥ
yathā bhavati susvasthas tathā tvaṃ samupācara
viśalyaḥ kriyatāṃ kṣipraṃ saumitriḥ savibhīṣaṇaḥ', null, 6079011),
('ramayana-6-79-12', 12, 'Yuddha Kanda, Sarga 79, Verse 12', 'कृष वानरसैन्यानां शूराणां द्रुमयोधिनाम्।
ये चान्येऽत्र च युध्यन्तः सशल्या व्रणिनस्तथा।
तेऽपि सर्वे प्रयत्नेन क्रियन्तां सुखिनस्त्वया॥', 'kṛṣa vānarasainyānāṃ śūrāṇāṃ drumayodhinām
ye cānye ''tra ca yudhyantaḥ saśalyā vraṇinas tathā
te ''pi sarve prayatnena kriyantāṃ sukhinas tvayā', null, 6079012),
('ramayana-6-79-13', 13, 'Yuddha Kanda, Sarga 79, Verse 13', 'एवमुक्तः स रामेण महात्मा हरियूथपः।
लक्ष्मणाय ददौ नस्तः सुषेणः परमौषधम्॥', 'evam uktaḥ sa rāmeṇa mahātmā hariyūthapaḥ
lakṣmaṇāya dadau nastaḥ suṣeṇaḥ paramauṣadham', null, 6079013),
('ramayana-6-79-14', 14, 'Yuddha Kanda, Sarga 79, Verse 14', 'स तस्य गन्धमाघ्राय विशल्यः समपद्यत।
तदा निर्वेदनश्चैव संरूढव्रण एव च॥', 'sa tasya gandham āghrāya viśalyaḥ samapadyata
tadā nirvedanaś caiva saṃrūḍhavraṇa eva ca', null, 6079014),
('ramayana-6-79-15', 15, 'Yuddha Kanda, Sarga 79, Verse 15', 'विभीषण मुखानां च सुहृदां राघवाज्ञया।
सर्ववानरमुख्यानां चिकित्सां स तदाकरोत्॥', 'vibhīṣaṇa mukhānāṃ ca suhṛdāṃ rāghavājñayā
sarvavānaramukhyānāṃ cikitsāṃ sa tadākarot', null, 6079015),
('ramayana-6-79-16', 16, 'Yuddha Kanda, Sarga 79, Verse 16', 'ततः प्रकृतिमापन्नो हृतशल्यो गतव्यथः।
सौमित्रिर्मुदितस्तत्र क्षणेन विगतज्वरः॥', 'tataḥ prakṛtim āpanno hṛtaśalyo gatavyathaḥ
saumitrir muditas tatra kṣaṇena vigatajvaraḥ', null, 6079016),
('ramayana-6-79-17', 17, 'Yuddha Kanda, Sarga 79, Verse 17', 'तथैव रामः प्लवगाधिपस्तदा विभीषणश्चर्क्षपतिश्च जाम्बवान्।
अवेक्ष्य सौमित्रिमरोगमुत्थितं मुदा ससैन्यः सुचिरं जहर्षिरे॥', 'tathaiva rāmaḥ plavagādhipas tadā vibhīṣaṇaś carkṣapatiś ca jāmbavān
avekṣya saumitrim arogam utthitaṃ mudā sasainyaḥ suciraṃ jaharṣire', null, 6079017),
('ramayana-6-79-18', 18, 'Yuddha Kanda, Sarga 79, Verse 18', 'अपूजयत्कर्म स लक्ष्मणस्य सुदुष्करं दाशरथिर्महात्मा।
हृष्टा बभूवुर्युधि यूथपेन्द्रा निशम्य तं शक्रजितं निपातितम्॥', 'apūjayat karma sa lakṣmaṇasya suduṣkaraṃ dāśarathir mahātmā
hṛṣṭā babhūvur yudhi yūthapendrā niśamya taṃ śakrajitaṃ nipātitam', null, 6079018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 80 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-80-1', 1, 'Yuddha Kanda, Sarga 80, Verse 1', 'ततः पौलस्त्य सचिवाः श्रुत्वा चेन्द्रजितं हतम्।
आचचक्षुरभिज्ञाय दशग्रीवाय सव्यथाः॥', 'tataḥ paulastya sacivāḥ śrutvā cendrajitaṃ hatam
ācacakṣur abhijñāya daśagrīvāya savyathāḥ', null, 6080001),
('ramayana-6-80-2', 2, 'Yuddha Kanda, Sarga 80, Verse 2', 'युद्धे हतो महाराज लक्ष्मणेन तवात्मजः।
विभीषणसहायेन मिषतां नो महाद्युते॥', 'yuddhe hato mahārāja lakṣmaṇena tavātmajaḥ
vibhīṣaṇasahāyena miṣatāṃ no mahādyute', null, 6080002),
('ramayana-6-80-3', 3, 'Yuddha Kanda, Sarga 80, Verse 3', 'शूरः शूरेण संगम्य संयुगेष्वपराजितः।
लक्ष्णनेन हतः शूरः पुत्रस्ते विबुधेन्द्रजित्॥', 'śūraḥ śūreṇa saṃgamya saṃyugeṣv aparājitaḥ
lakṣṇanena hataḥ śūraḥ putras te vibudhendrajit', null, 6080003),
('ramayana-6-80-4', 4, 'Yuddha Kanda, Sarga 80, Verse 4', 'स तं प्रतिभयं श्रुत्वा वधं पुत्रस्य दारुणम्।
घोरमिन्द्रजितः संख्ये कश्मलं प्राविशन्महत्॥', 'sa taṃ pratibhayaṃ śrutvā vadhaṃ putrasya dāruṇam
ghoram indrajitaḥ saṃkhye kaśmalaṃ prāviśan mahat', null, 6080004),
('ramayana-6-80-5', 5, 'Yuddha Kanda, Sarga 80, Verse 5', 'उपलभ्य चिरात्संज्ञां राजा राक्षसपुंगवः।
पुत्रशोकार्दितो दीनो विललापाकुलेन्द्रियः॥', 'upalabhya cirāt saṃjñāṃ rājā rākṣasapuṃgavaḥ
putraśokārdito dīno vilalāpākulendriyaḥ', null, 6080005),
('ramayana-6-80-6', 6, 'Yuddha Kanda, Sarga 80, Verse 6', 'हा राक्षसचमूमुख्य मम वत्स महारथ।
जित्वेन्द्रं कथमद्य त्वं लक्ष्मणस्य वशं गतः॥', 'hā rākṣasacamūmukhya mama vatsa mahāratha
jitvendraṃ katham adya tvaṃ lakṣmaṇasya vaśaṃ gataḥ', null, 6080006),
('ramayana-6-80-7', 7, 'Yuddha Kanda, Sarga 80, Verse 7', 'ननु त्वमिषुभिः क्रुद्धो भिन्द्याः कालान्तकावपि।
मन्दरस्यापि शृङ्गाणि किं पुनर्लक्ष्मणं रणे॥', 'nanu tvam iṣubhiḥ kruddho bhindyāḥ kālāntakāv api
mandarasyāpi śṛṅgāṇi kiṃ punar lakṣmaṇaṃ raṇe', null, 6080007),
('ramayana-6-80-8', 8, 'Yuddha Kanda, Sarga 80, Verse 8', 'अद्य वैवस्वतो राजा भूयो बहुमतो मम।
येनाद्य त्वं महाबाहो संयुक्तः कालधर्मणा॥', 'adya vaivasvato rājā bhūyo bahumato mama
yenādya tvaṃ mahābāho saṃyuktaḥ kāladharmaṇā', null, 6080008),
('ramayana-6-80-9', 9, 'Yuddha Kanda, Sarga 80, Verse 9', 'एष पन्थाः सुयोधानां सर्वामरगणेष्वपि।
यः कृते हन्यते भर्तुः स पुमान्स्वर्गमृच्छति॥', 'eṣa panthāḥ suyodhānāṃ sarvāmaragaṇeṣv api
yaḥ kṛte hanyate bhartuḥ sa pumān svargam ṛcchati', null, 6080009),
('ramayana-6-80-10', 10, 'Yuddha Kanda, Sarga 80, Verse 10', 'अद्य देवगणाः सर्वे लोकपालास्तथर्षयः।
हतमिन्द्रजितं दृष्ट्वा सुखं स्वप्स्यन्ति निर्भयाः॥', 'adya devagaṇāḥ sarve lokapālās tatharṣayaḥ
hatam indrajitaṃ dṛṣṭvā sukhaṃ svapsyanti nirbhayāḥ', null, 6080010),
('ramayana-6-80-11', 11, 'Yuddha Kanda, Sarga 80, Verse 11', 'अद्य लोकास्त्रयः कृत्स्नाः पृथिवी च सकानना।
एकेनेन्द्रजिता हीना शूण्येव प्रतिभाति मे॥', 'adya lokās trayaḥ kṛtsnāḥ pṛthivī ca sakānanā
ekenendrajitā hīnā śūṇyeva pratibhāti me', null, 6080011),
('ramayana-6-80-12', 12, 'Yuddha Kanda, Sarga 80, Verse 12', 'अद्य नैरृतकन्यायां श्रोष्याम्यन्तःपुरे रवम्।
करेणुसंघस्य यथा निनादं गिरिगह्वरे॥', 'adya nairṛtakanyāyāṃ śroṣyāmy antaḥpure ravam
kareṇusaṃghasya yathā ninādaṃ girigahvare', null, 6080012),
('ramayana-6-80-13', 13, 'Yuddha Kanda, Sarga 80, Verse 13', 'यौवराज्यं च लङ्कां च रक्षांसि च परंतप।
मातरं मां च भार्यां च क्व गतोऽसि विहाय नः॥', 'yauvarājyaṃ ca laṅkāṃ ca rakṣāṃsi ca paraṃtapa
mātaraṃ māṃ ca bhāryāṃ ca kva gato ''si vihāya naḥ', null, 6080013),
('ramayana-6-80-14', 14, 'Yuddha Kanda, Sarga 80, Verse 14', 'मम नाम त्वया वीर गतस्य यमसादनम्।
प्रेतकार्याणि कार्याणि विपरीते हि वर्तसे॥', 'mama nāma tvayā vīra gatasya yamasādanam
pretakāryāṇi kāryāṇi viparīte hi vartase', null, 6080014),
('ramayana-6-80-15', 15, 'Yuddha Kanda, Sarga 80, Verse 15', 'स त्वं जीवति सुग्रीवे राघवे च सलक्ष्मणे।
मम शल्यमनुद्धृत्य क्व गतोऽसि विहाय नः॥', 'sa tvaṃ jīvati sugrīve rāghave ca salakṣmaṇe
mama śalyam anuddhṛtya kva gato ''si vihāya naḥ', null, 6080015),
('ramayana-6-80-16', 16, 'Yuddha Kanda, Sarga 80, Verse 16', 'एवमादिविलापार्तं रावणं राक्षसाधिपम्।
आविवेश महान्कोपः पुत्रव्यसनसंभवः॥', 'evamādivilāpārtaṃ rāvaṇaṃ rākṣasādhipam
āviveśa mahān kopaḥ putravyasanasaṃbhavaḥ', null, 6080016),
('ramayana-6-80-17', 17, 'Yuddha Kanda, Sarga 80, Verse 17', 'घोरं प्रकृत्या रूपं तत्तस्य क्रोधाग्निमूर्छितम्।
बभूव रूपं रुद्रस्य क्रुद्धस्येव दुरासदम्॥', 'ghoraṃ prakṛtyā rūpaṃ tat tasya krodhāgnimūrchitam
babhūva rūpaṃ rudrasya kruddhasyeva durāsadam', null, 6080017),
('ramayana-6-80-18', 18, 'Yuddha Kanda, Sarga 80, Verse 18', 'तस्य क्रुद्धस्य नेत्राभ्यां प्रापतन्नस्रबिन्दवः।
दीप्ताभ्यामिव दीपाभ्यां सार्चिषः स्नेहबिन्दवः॥', 'tasya kruddhasya netrābhyāṃ prāpatann asrabindavaḥ
dīptābhyām iva dīpābhyāṃ sārciṣaḥ snehabindavaḥ', null, 6080018),
('ramayana-6-80-19', 19, 'Yuddha Kanda, Sarga 80, Verse 19', 'दन्तान्विदशतस्तस्य श्रूयते दशनस्वनः।
यन्त्रस्यावेष्ट्यमानस्य महतो दानवैरिव॥', 'dantān vidaśatas tasya śrūyate daśanasvanaḥ
yantrasyāveṣṭyamānasya mahato dānavair iva', null, 6080019),
('ramayana-6-80-20', 20, 'Yuddha Kanda, Sarga 80, Verse 20', 'कालाग्निरिव संक्रुद्धो यां यां दिशमवैक्षत।
तस्यां तस्यां भयत्रस्ता राक्षसाः संनिलिल्यिरे॥', 'kālāgnir iva saṃkruddho yāṃ yāṃ diśam avaikṣata
tasyāṃ tasyāṃ bhayatrastā rākṣasāḥ saṃnililyire', null, 6080020),
('ramayana-6-80-21', 21, 'Yuddha Kanda, Sarga 80, Verse 21', 'तमन्तकमिव क्रुद्धं चराचरचिखादिषुम्।
वीक्षमाणं दिशः सर्वा राक्षसा नोपचक्रमुः॥', 'tam antakam iva kruddhaṃ carācaracikhādiṣum
vīkṣamāṇaṃ diśaḥ sarvā rākṣasā nopacakramuḥ', null, 6080021),
('ramayana-6-80-22', 22, 'Yuddha Kanda, Sarga 80, Verse 22', 'ततः परमसंक्रुद्धो रावणो राक्षसाधिपः।
अब्रवीद्रक्षसां मध्ये संस्तम्भयिषुराहवे॥', 'tataḥ paramasaṃkruddho rāvaṇo rākṣasādhipaḥ
abravīd rakṣasāṃ madhye saṃstambhayiṣur āhave', null, 6080022),
('ramayana-6-80-23', 23, 'Yuddha Kanda, Sarga 80, Verse 23', 'मया वर्षसहस्राणि चरित्वा दुश्चरं तपः।
तेषु तेष्ववकाशेषु स्वयम्भूः परितोषितः॥', 'mayā varṣasahasrāṇi caritvā duścaraṃ tapaḥ
teṣu teṣv avakāśeṣu svayambhūḥ paritoṣitaḥ', null, 6080023),
('ramayana-6-80-24', 24, 'Yuddha Kanda, Sarga 80, Verse 24', 'तस्यैव तपसो व्युष्ट्या प्रसादाच्च स्वयम्भुवः।
नासुरेभ्यो न देवेभ्यो भयं मम कदा चन॥', 'tasyaiva tapaso vyuṣṭyā prasādāc ca svayambhuvaḥ
nāsurebhyo na devebhyo bhayaṃ mama kadā cana', null, 6080024),
('ramayana-6-80-25', 25, 'Yuddha Kanda, Sarga 80, Verse 25', 'कवचं ब्रह्मदत्तं मे यदादित्यसमप्रभम्।
देवासुरविमर्देषु न भिन्नं वज्रशक्तिभिः॥', 'kavacaṃ brahmadattaṃ me yad ādityasamaprabham
devāsuravimardeṣu na bhinnaṃ vajraśaktibhiḥ', null, 6080025),
('ramayana-6-80-26', 26, 'Yuddha Kanda, Sarga 80, Verse 26', 'तेन मामद्य संयुक्तं रथस्थमिह संयुगे।
प्रतीयात्कोऽद्य मामाजौ साक्षादपि पुरंदरः॥', 'tena mām adya saṃyuktaṃ rathastham iha saṃyuge
pratīyāt ko ''dya mām ājau sākṣād api puraṃdaraḥ', null, 6080026),
('ramayana-6-80-27', 27, 'Yuddha Kanda, Sarga 80, Verse 27', 'यत्तदाभिप्रसन्नेन सशरं कार्मुकं महत्।
देवासुरविमर्देषु मम दत्तं स्वयम्भुवा॥', 'yat tadābhiprasannena saśaraṃ kārmukaṃ mahat
devāsuravimardeṣu mama dattaṃ svayambhuvā', null, 6080027),
('ramayana-6-80-28', 28, 'Yuddha Kanda, Sarga 80, Verse 28', 'अद्य तूर्यशतैर्भीमं धनुरुत्थाप्यतां महत्।
रामलक्ष्मणयोरेव वधाय परमाहवे॥', 'adya tūryaśatair bhīmaṃ dhanur utthāpyatāṃ mahat
rāmalakṣmaṇayor eva vadhāya paramāhave', null, 6080028),
('ramayana-6-80-29', 29, 'Yuddha Kanda, Sarga 80, Verse 29', 'स पुत्रवधसंतप्तः शूरः क्रोधवशं गतः।
समीक्ष्य रावणो बुद्ध्या सीतां हन्तुं व्यवस्यत॥', 'sa putravadhasaṃtaptaḥ śūraḥ krodhavaśaṃ gataḥ
samīkṣya rāvaṇo buddhyā sītāṃ hantuṃ vyavasyata', null, 6080029),
('ramayana-6-80-30', 30, 'Yuddha Kanda, Sarga 80, Verse 30', 'प्रत्यवेक्ष्य तु ताम्राक्षः सुघोरो घोरदर्शनान्।
दीनो दीनस्वरान्सर्वांस्तानुवाच निशाचरान्॥', 'pratyavekṣya tu tāmrākṣaḥ sughoro ghoradarśanān
dīno dīnasvarān sarvāṃs tān uvāca niśācarān', null, 6080030),
('ramayana-6-80-31', 31, 'Yuddha Kanda, Sarga 80, Verse 31', 'मायया मम वत्सेन वञ्चनार्थं वनौकसाम्।
किं चिदेव हतं तत्र सीतेयमिति दर्शितम्॥', 'māyayā mama vatsena vañcanārthaṃ vanaukasām
kiṃ cid eva hataṃ tatra sīteyam iti darśitam', null, 6080031),
('ramayana-6-80-32', 32, 'Yuddha Kanda, Sarga 80, Verse 32', 'तदिदं सत्यमेवाहं करिष्ये प्रियमात्मनः।
वैदेहीं नाशयिष्यामि क्षत्रबन्धुमनुव्रताम्।
इत्येवमुक्त्वा सचिवान्खड्गमाशु परामृशत्॥', 'tad idaṃ satyam evāhaṃ kariṣye priyam ātmanaḥ
vaidehīṃ nāśayiṣyāmi kṣatrabandhum anuvratām
ity evam uktvā sacivān khaḍgam āśu parāmṛśat', null, 6080032),
('ramayana-6-80-33', 33, 'Yuddha Kanda, Sarga 80, Verse 33', 'उद्धृत्य गुणसंपन्नं विमलाम्बरवर्चसं।
निष्पपात स वेगेन सभायाः सचिवैर्वृतः॥', 'uddhṛtya guṇasaṃpannaṃ vimalāmbaravarcasaṃ
niṣpapāta sa vegena sabhāyāḥ sacivair vṛtaḥ', null, 6080033),
('ramayana-6-80-34', 34, 'Yuddha Kanda, Sarga 80, Verse 34', 'रावणः पुत्रशोकेन भृशमाकुलचेतनः।
संक्रुद्धः खड्गमादाय सहसा यत्र मैथिली॥', 'rāvaṇaḥ putraśokena bhṛśam ākulacetanaḥ
saṃkruddhaḥ khaḍgam ādāya sahasā yatra maithilī', null, 6080034),
('ramayana-6-80-35', 35, 'Yuddha Kanda, Sarga 80, Verse 35', 'व्रजन्तं राक्षसं प्रेक्ष्य सिंहनादं प्रचुक्रुशुः।
ऊचुश्चान्योन्यमाश्लिष्य संक्रुद्धं प्रेक्ष्य राक्षसाः॥', 'vrajantaṃ rākṣasaṃ prekṣya siṃhanādaṃ pracukruśuḥ
ūcuś cānyonyam āśliṣya saṃkruddhaṃ prekṣya rākṣasāḥ', null, 6080035),
('ramayana-6-80-36', 36, 'Yuddha Kanda, Sarga 80, Verse 36', 'अद्यैनं तावुभौ दृष्ट्वा भ्रातरौ प्रव्यथिष्यतः।
लोकपाला हि चत्वारः क्रुद्धेनानेन निर्जिताः।
बहवः शत्रवश्चान्ये संयुगेष्वभिपातिताः॥', 'adyainaṃ tāv ubhau dṛṣṭvā bhrātarau pravyathiṣyataḥ
lokapālā hi catvāraḥ kruddhenānena nirjitāḥ
bahavaḥ śatravaś cānye saṃyugeṣv abhipātitāḥ', null, 6080036),
('ramayana-6-80-37', 37, 'Yuddha Kanda, Sarga 80, Verse 37', 'तेषां संजल्पमानानामशोकवनिकां गताम्।
अभिदुद्राव वैदेहीं रावणः क्रोधमूर्छितः॥', 'teṣāṃ saṃjalpamānānām aśokavanikāṃ gatām
abhidudrāva vaidehīṃ rāvaṇaḥ krodhamūrchitaḥ', null, 6080037),
('ramayana-6-80-38', 38, 'Yuddha Kanda, Sarga 80, Verse 38', 'वार्यमाणः सुसंक्रुद्धः सुहृद्भिर्हितबुद्धिभिः।
अभ्यधावत संक्रुद्धः खे ग्रहो रोहिणीमिव॥', 'vāryamāṇaḥ susaṃkruddhaḥ suhṛdbhir hitabuddhibhiḥ
abhyadhāvata saṃkruddhaḥ khe graho rohiṇīm iva', null, 6080038),
('ramayana-6-80-39', 39, 'Yuddha Kanda, Sarga 80, Verse 39', 'मैथिली रक्ष्यमाणा तु राक्षसीभिरनिन्दिता।
ददर्श राक्षसं क्रुद्धं निस्त्रिंशवरधारिणम्॥', 'maithilī rakṣyamāṇā tu rākṣasībhir aninditā
dadarśa rākṣasaṃ kruddhaṃ nistriṃśavaradhāriṇam', null, 6080039),
('ramayana-6-80-40', 40, 'Yuddha Kanda, Sarga 80, Verse 40', 'तं निशाम्य सनिस्त्रिंशं व्यथिता जनकात्मजा।
निवार्यमाणं बहुशः सुहृद्भिरनिवर्तिनम्॥', 'taṃ niśāmya sanistriṃśaṃ vyathitā janakātmajā
nivāryamāṇaṃ bahuśaḥ suhṛdbhir anivartinam', null, 6080040),
('ramayana-6-80-41', 41, 'Yuddha Kanda, Sarga 80, Verse 41', 'यथायं मामभिक्रुद्धः समभिद्रवति स्वयम्।
वधिष्यति सनाथां मामनाथामिव दुर्मतिः॥', 'yathāyaṃ mām abhikruddhaḥ samabhidravati svayam
vadhiṣyati sanāthāṃ mām anāthām iva durmatiḥ', null, 6080041),
('ramayana-6-80-42', 42, 'Yuddha Kanda, Sarga 80, Verse 42', 'बहुशश्चोदयामास भर्तारं मामनुव्रताम्।
भार्या भव रमस्येति प्रत्याख्यातोऽभवन्मया॥', 'bahuśaś codayām āsa bhartāraṃ mām anuvratām
bhāryā bhava ramasyeti pratyākhyāto ''bhavan mayā', null, 6080042),
('ramayana-6-80-43', 43, 'Yuddha Kanda, Sarga 80, Verse 43', 'सोऽयं मामनुपस्थानाद्व्यक्तं नैराश्यमागतः।
क्रोधमोहसमाविष्टो निहन्तुं मां समुद्यतः॥', 'so ''yaṃ mām anupasthānād vyaktaṃ nairāśyam āgataḥ
krodhamohasamāviṣṭo nihantuṃ māṃ samudyataḥ', null, 6080043),
('ramayana-6-80-44', 44, 'Yuddha Kanda, Sarga 80, Verse 44', 'अथ वा तौ नरव्याघ्रौ भ्रातरौ रामलक्ष्मणौ।
मन्निमित्तमनार्येण समरेऽद्य निपातितौ।
अहो धिन्मन्निमित्तोऽयं विनाशो राजपुत्रयोः॥', 'atha vā tau naravyāghrau bhrātarau rāmalakṣmaṇau
mannimittam anāryeṇa samare ''dya nipātitau
aho dhin mannimitto ''yaṃ vināśo rājaputrayoḥ', null, 6080044),
('ramayana-6-80-45', 45, 'Yuddha Kanda, Sarga 80, Verse 45', 'हनूमतो हि तद्वाक्यं न कृतं क्षुद्रया मया।
यद्यहं तस्य पृष्ठेन तदायासमनिन्दिता।
नाद्यैवमनुशोचेयं भर्तुरङ्कगता सती॥', 'hanūmato hi tadvākyaṃ na kṛtaṃ kṣudrayā mayā
yady ahaṃ tasya pṛṣṭhena tadāyāsam aninditā
nādyaivam anuśoceyaṃ bhartur aṅkagatā satī', null, 6080045),
('ramayana-6-80-46', 46, 'Yuddha Kanda, Sarga 80, Verse 46', 'मन्ये तु हृदयं तस्याः कौसल्यायाः फलिष्यति।
एकपुत्रा यदा पुत्रं विनष्टं श्रोष्यते युधि॥', 'manye tu hṛdayaṃ tasyāḥ kausalyāyāḥ phaliṣyati
ekaputrā yadā putraṃ vinaṣṭaṃ śroṣyate yudhi', null, 6080046),
('ramayana-6-80-47', 47, 'Yuddha Kanda, Sarga 80, Verse 47', 'सा हि जन्म च बाल्यं च यौवनं च महात्मनः।
धर्मकार्याणि रूपं च रुदती संस्रमिष्यति॥', 'sā hi janma ca bālyaṃ ca yauvanaṃ ca mahātmanaḥ
dharmakāryāṇi rūpaṃ ca rudatī saṃsramiṣyati', null, 6080047),
('ramayana-6-80-48', 48, 'Yuddha Kanda, Sarga 80, Verse 48', 'निराशा निहते पुत्रे दत्त्वा श्राद्धमचेतना।
अग्निमारोक्ष्यते नूनमपो वापि प्रवेक्ष्यति॥', 'nirāśā nihate putre dattvā śrāddham acetanā
agnim ārokṣyate nūnam apo vāpi pravekṣyati', null, 6080048),
('ramayana-6-80-49', 49, 'Yuddha Kanda, Sarga 80, Verse 49', 'धिगस्तु कुब्जामसतीं मन्थरां पापनिश्चयाम्।
यन्निमित्तमिदं दुःखं कौसल्या प्रतिपत्स्यते॥', 'dhig astu kubjām asatīṃ mantharāṃ pāpaniścayām
yannimittam idaṃ duḥkhaṃ kausalyā pratipatsyate', null, 6080049),
('ramayana-6-80-50', 50, 'Yuddha Kanda, Sarga 80, Verse 50', 'इत्येवं मैथिलीं दृष्ट्वा विलपन्तीं तपस्विनीम्।
रोहिणीमिव चन्द्रेण विना ग्रहवशं गताम्॥', 'ity evaṃ maithilīṃ dṛṣṭvā vilapantīṃ tapasvinīm
rohiṇīm iva candreṇa vinā grahavaśaṃ gatām', null, 6080050),
('ramayana-6-80-51', 51, 'Yuddha Kanda, Sarga 80, Verse 51', 'सुपार्श्वो नाम मेधावी रावणं राक्षसेश्वरम्।
निवार्यमाणं सचिवैरिदं वचनमब्रवीत्॥', 'supārśvo nāma medhāvī rāvaṇaṃ rākṣaseśvaram
nivāryamāṇaṃ sacivair idaṃ vacanam abravīt', null, 6080051),
('ramayana-6-80-52', 52, 'Yuddha Kanda, Sarga 80, Verse 52', 'कथं नाम दशग्रीव साक्षाद्वैश्रवणानुज।
हन्तुमिच्छसि वैदेहीं क्रोधाद्धर्ममपास्य हि॥', 'kathaṃ nāma daśagrīva sākṣād vaiśravaṇānuja
hantum icchasi vaidehīṃ krodhād dharmam apāsya hi', null, 6080052),
('ramayana-6-80-53', 53, 'Yuddha Kanda, Sarga 80, Verse 53', 'वेद विद्याव्रत स्नातः स्वधर्मनिरतः सदा।
स्त्रियाः कस्माद्वधं वीर मन्यसे राक्षसेश्वर॥', 'veda vidyāvrata snātaḥ svadharmanirataḥ sadā
striyāḥ kasmād vadhaṃ vīra manyase rākṣaseśvara', null, 6080053),
('ramayana-6-80-54', 54, 'Yuddha Kanda, Sarga 80, Verse 54', 'मैथिलीं रूपसंपन्नां प्रत्यवेक्षस्व पार्थिव।
त्वमेव तु सहास्माभी राघवे क्रोधमुत्सृज॥', 'maithilīṃ rūpasaṃpannāṃ pratyavekṣasva pārthiva
tvam eva tu sahāsmābhī rāghave krodham utsṛja', null, 6080054),
('ramayana-6-80-55', 55, 'Yuddha Kanda, Sarga 80, Verse 55', 'अभ्युत्थानं त्वमद्यैव कृष्णपक्षचतुर्दशीम्।
कृत्वा निर्याह्यमावास्यां विजयाय बलैर्वृतः॥', 'abhyutthānaṃ tvam adyaiva kṛṣṇapakṣacaturdaśīm
kṛtvā niryāhy amāvāsyāṃ vijayāya balair vṛtaḥ', null, 6080055),
('ramayana-6-80-56', 56, 'Yuddha Kanda, Sarga 80, Verse 56', 'शूरो धीमान्रथी खड्गी रथप्रवरमास्थितः।
हत्वा दाशरथिं रामं भवान्प्राप्स्यति मैथिलीम्॥', 'śūro dhīmān rathī khaḍgī rathapravaram āsthitaḥ
hatvā dāśarathiṃ rāmaṃ bhavān prāpsyati maithilīm', null, 6080056),
('ramayana-6-80-57', 57, 'Yuddha Kanda, Sarga 80, Verse 57', 'स तद्दुरात्मा सुहृदा निवेदितं वचः सुधर्म्यं प्रतिगृह्य रावणः।
गृहं जगामाथ ततश्च वीर्यवान्पुनः सभां च प्रययौ सुहृद्वृतः॥', 'sa tad durātmā suhṛdā niveditaṃ vacaḥ sudharmyaṃ pratigṛhya rāvaṇaḥ
gṛhaṃ jagāmātha tataś ca vīryavān punaḥ sabhāṃ ca prayayau suhṛdvṛtaḥ', null, 6080057)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 81 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-81-1', 1, 'Yuddha Kanda, Sarga 81, Verse 1', 'स प्रविश्य सभां राजा दीनः परमदुःखितः।
निषसादासने मुख्ये सिंहः क्रुद्ध इव श्वसन्॥', 'sa praviśya sabhāṃ rājā dīnaḥ paramaduḥkhitaḥ
niṣasādāsane mukhye siṃhaḥ kruddha iva śvasan', null, 6081001),
('ramayana-6-81-2', 2, 'Yuddha Kanda, Sarga 81, Verse 2', 'अब्रवीच्च तदा सर्वान्बलमुख्यान्महाबलः।
रावणः प्राञ्जलीन्वाक्यं पुत्रव्यसनकर्शितः॥', 'abravīc ca tadā sarvān balamukhyān mahābalaḥ
rāvaṇaḥ prāñjalīn vākyaṃ putravyasanakarśitaḥ', null, 6081002),
('ramayana-6-81-3', 3, 'Yuddha Kanda, Sarga 81, Verse 3', 'सर्वे भवन्तः सर्वेण हस्त्यश्वेन समावृताः।
निर्यान्तु रथसंघैश्च पादातैश्चोपशोभिताः॥', 'sarve bhavantaḥ sarveṇa hastyaśvena samāvṛtāḥ
niryāntu rathasaṃghaiś ca pādātaiś copaśobhitāḥ', null, 6081003),
('ramayana-6-81-4', 4, 'Yuddha Kanda, Sarga 81, Verse 4', 'एकं रामं परिक्षिप्य समरे हन्तुमर्हथ।
प्रहृष्टा शरवर्षेण प्रावृट्काल इवाम्बुदाः॥', 'ekaṃ rāmaṃ parikṣipya samare hantum arhatha
prahṛṣṭā śaravarṣeṇa prāvṛṭkāla ivāmbudāḥ', null, 6081004),
('ramayana-6-81-5', 5, 'Yuddha Kanda, Sarga 81, Verse 5', 'अथ वाहं शरैर्तीक्ष्णैर्भिन्नगात्रं महारणे।
भवद्भिः श्वो निहन्तास्मि रामं लोकस्य पश्यतः॥', 'atha vāhaṃ śarair tīkṣṇair bhinnagātraṃ mahāraṇe
bhavadbhiḥ śvo nihantāsmi rāmaṃ lokasya paśyataḥ', null, 6081005),
('ramayana-6-81-6', 6, 'Yuddha Kanda, Sarga 81, Verse 6', 'इत्येवं राक्षसेन्द्रस्य वाक्यमादाय राक्षसाः।
निर्ययुस्ते रथैः शीघ्रं नागानीकैश्च संवृताः॥', 'ity evaṃ rākṣasendrasya vākyam ādāya rākṣasāḥ
niryayus te rathaiḥ śīghraṃ nāgānīkaiś ca saṃvṛtāḥ', null, 6081006),
('ramayana-6-81-7', 7, 'Yuddha Kanda, Sarga 81, Verse 7', 'स संग्रामो महाभीमः सूर्यस्योदयनं प्रति।
रक्षसां वानराणां च तुमुलः समपद्यत॥', 'sa saṃgrāmo mahābhīmaḥ sūryasyodayanaṃ prati
rakṣasāṃ vānarāṇāṃ ca tumulaḥ samapadyata', null, 6081007),
('ramayana-6-81-8', 8, 'Yuddha Kanda, Sarga 81, Verse 8', 'ते गदाभिर्विचित्राभिः प्रासैः खड्गैः परश्वधैः।
अन्योन्यं समरे जघ्नुस्तदा वानरराक्षसाः॥', 'te gadābhir vicitrābhiḥ prāsaiḥ khaḍgaiḥ paraśvadhaiḥ
anyonyaṃ samare jaghnus tadā vānararākṣasāḥ', null, 6081008),
('ramayana-6-81-9', 9, 'Yuddha Kanda, Sarga 81, Verse 9', 'मातंगरथकूलस्य वाजिमत्स्या ध्वजद्रुमाः।
शरीरसंघाटवहाः प्रसस्रुः शोणितापगाः॥', 'mātaṃgarathakūlasya vājimatsyā dhvajadrumāḥ
śarīrasaṃghāṭavahāḥ prasasruḥ śoṇitāpagāḥ', null, 6081009),
('ramayana-6-81-10', 10, 'Yuddha Kanda, Sarga 81, Verse 10', 'ध्वजवर्मरथानश्वान्नानाप्रहरणानि च।
आप्लुत्याप्लुत्य समरे वानरेन्द्रा बभञ्जिरे॥', 'dhvajavarmarathān aśvān nānāpraharaṇāni ca
āplutyāplutya samare vānarendrā babhañjire', null, 6081010),
('ramayana-6-81-11', 11, 'Yuddha Kanda, Sarga 81, Verse 11', 'केशान्कर्णललाटांश्च नासिकाश्च प्लवंगमाः।
रक्षसां दशनैस्तीक्ष्णैर्नखैश्चापि व्यकर्तयन्॥', 'keśān karṇalalāṭāṃś ca nāsikāś ca plavaṃgamāḥ
rakṣasāṃ daśanais tīkṣṇair nakhaiś cāpi vyakartayan', null, 6081011),
('ramayana-6-81-12', 12, 'Yuddha Kanda, Sarga 81, Verse 12', 'एकैकं राक्षसं संख्ये शतं वानरपुंगवाः।
अभ्यधावन्त फलिनं वृक्षं शकुनयो यथा॥', 'ekaikaṃ rākṣasaṃ saṃkhye śataṃ vānarapuṃgavāḥ
abhyadhāvanta phalinaṃ vṛkṣaṃ śakunayo yathā', null, 6081012),
('ramayana-6-81-13', 13, 'Yuddha Kanda, Sarga 81, Verse 13', 'तथा गदाभिर्गुर्वीभिः प्रासैः खड्गैः परश्वधैः।
निर्जघ्नुर्वानरान्घोरान्राक्षसाः पर्वतोपमाः॥', 'tathā gadābhir gurvībhiḥ prāsaiḥ khaḍgaiḥ paraśvadhaiḥ
nirjaghnur vānarān ghorān rākṣasāḥ parvatopamāḥ', null, 6081013),
('ramayana-6-81-14', 14, 'Yuddha Kanda, Sarga 81, Verse 14', 'राक्षसैर्वध्यमानानां वानराणां महाचमूः।
शरण्यं शरणं याता रामं दशरथात्मजम्॥', 'rākṣasair vadhyamānānāṃ vānarāṇāṃ mahācamūḥ
śaraṇyaṃ śaraṇaṃ yātā rāmaṃ daśarathātmajam', null, 6081014),
('ramayana-6-81-15', 15, 'Yuddha Kanda, Sarga 81, Verse 15', 'ततो रामो महातेजा धनुरादाय वीर्यवान्।
प्रविश्य राक्षसं सैन्यं शरवर्षं ववर्ष ह॥', 'tato rāmo mahātejā dhanur ādāya vīryavān
praviśya rākṣasaṃ sainyaṃ śaravarṣaṃ vavarṣa ha', null, 6081015),
('ramayana-6-81-16', 16, 'Yuddha Kanda, Sarga 81, Verse 16', 'प्रविष्टं तु तदा रामं मेघाः सूर्यमिवाम्बरे।
नाभिजग्मुर्महाघोरं निर्दहन्तं शराग्निना॥', 'praviṣṭaṃ tu tadā rāmaṃ meghāḥ sūryam ivāmbare
nābhijagmur mahāghoraṃ nirdahantaṃ śarāgninā', null, 6081016),
('ramayana-6-81-17', 17, 'Yuddha Kanda, Sarga 81, Verse 17', 'कृतान्येव सुघोराणि रामेण रजनीचराः।
रणे रामस्य ददृशुः कर्माण्यसुकराणि च॥', 'kṛtāny eva sughorāṇi rāmeṇa rajanīcarāḥ
raṇe rāmasya dadṛśuḥ karmāṇy asukarāṇi ca', null, 6081017),
('ramayana-6-81-18', 18, 'Yuddha Kanda, Sarga 81, Verse 18', 'चालयन्तं महानीकं विधमन्तं महारथान्।
ददृशुस्ते न वै रामं वातं वनगतं यथा॥', 'cālayantaṃ mahānīkaṃ vidhamantaṃ mahārathān
dadṛśus te na vai rāmaṃ vātaṃ vanagataṃ yathā', null, 6081018),
('ramayana-6-81-19', 19, 'Yuddha Kanda, Sarga 81, Verse 19', 'छिन्नं भिन्नं शरैर्दग्धं प्रभग्नं शस्त्रपीडितम्।
बलं रामेण ददृशुर्न रमं शीघ्रकारिणम्॥', 'chinnaṃ bhinnaṃ śarair dagdhaṃ prabhagnaṃ śastrapīḍitam
balaṃ rāmeṇa dadṛśur na ramaṃ śīghrakāriṇam', null, 6081019),
('ramayana-6-81-20', 20, 'Yuddha Kanda, Sarga 81, Verse 20', 'प्रहरन्तं शरीरेषु न ते पश्यन्ति राघवम्।
इन्द्रियार्थेषु तिष्ठन्तं भूतात्मानमिव प्रजाः॥', 'praharantaṃ śarīreṣu na te paśyanti rāghavam
indriyārtheṣu tiṣṭhantaṃ bhūtātmānam iva prajāḥ', null, 6081020),
('ramayana-6-81-21', 21, 'Yuddha Kanda, Sarga 81, Verse 21', 'एष हन्ति गजानीकमेष हन्ति महारथान्।
एष हन्ति शरैस्तीक्ष्णैः पदातीन्वाजिभिः सह॥', 'eṣa hanti gajānīkam eṣa hanti mahārathān
eṣa hanti śarais tīkṣṇaiḥ padātīn vājibhiḥ saha', null, 6081021),
('ramayana-6-81-22', 22, 'Yuddha Kanda, Sarga 81, Verse 22', 'इति ते राक्षसाः सर्वे रामस्य सदृशान्रणे।
अन्योन्यकुपिता जघ्नुः सादृश्याद्राघवस्य ते॥', 'iti te rākṣasāḥ sarve rāmasya sadṛśān raṇe
anyonyakupitā jaghnuḥ sādṛśyād rāghavasya te', null, 6081022),
('ramayana-6-81-23', 23, 'Yuddha Kanda, Sarga 81, Verse 23', 'न ते ददृशिरे रामं दहन्तमरिवाहिनीम्।
मोहिताः परमास्त्रेण गान्धर्वेण महात्मना॥', 'na te dadṛśire rāmaṃ dahantam arivāhinīm
mohitāḥ paramāstreṇa gāndharveṇa mahātmanā', null, 6081023),
('ramayana-6-81-24', 24, 'Yuddha Kanda, Sarga 81, Verse 24', 'ते तु रामसहस्राणि रणे पश्यन्ति राक्षसाः।
पुनः पश्यन्ति काकुत्स्थमेकमेव महाहवे॥', 'te tu rāmasahasrāṇi raṇe paśyanti rākṣasāḥ
punaḥ paśyanti kākutstham ekam eva mahāhave', null, 6081024),
('ramayana-6-81-25', 25, 'Yuddha Kanda, Sarga 81, Verse 25', 'भ्रमन्तीं काञ्चनीं कोटिं कार्मुकस्य महात्मनः।
अलातचक्रप्रतिमां ददृशुस्ते न राघवम्॥', 'bhramantīṃ kāñcanīṃ koṭiṃ kārmukasya mahātmanaḥ
alātacakrapratimāṃ dadṛśus te na rāghavam', null, 6081025),
('ramayana-6-81-26', 26, 'Yuddha Kanda, Sarga 81, Verse 26', 'शरीरनाभि सत्त्वार्चिः शरीरं नेमिकार्मुकम्।
ज्याघोषतलनिर्घोषं तेजोबुद्धिगुणप्रभम्॥', 'śarīranābhi sattvārciḥ śarīraṃ nemikārmukam
jyāghoṣatalanirghoṣaṃ tejobuddhiguṇaprabham', null, 6081026),
('ramayana-6-81-27', 27, 'Yuddha Kanda, Sarga 81, Verse 27', 'दिव्यास्त्रगुणपर्यन्तं निघ्नन्तं युधि राक्षसान्।
ददृशू रामचक्रं तत्कालचक्रमिव प्रजाः॥', 'divyāstraguṇaparyantaṃ nighnantaṃ yudhi rākṣasān
dadṛśū rāmacakraṃ tat kālacakram iva prajāḥ', null, 6081027),
('ramayana-6-81-28', 28, 'Yuddha Kanda, Sarga 81, Verse 28', 'अनीकं दशसाहस्रं रथानां वातरंहसाम्।
अष्टादशसहस्राणि कुञ्जराणां तरस्विनाम्॥', 'anīkaṃ daśasāhasraṃ rathānāṃ vātaraṃhasām
aṣṭādaśasahasrāṇi kuñjarāṇāṃ tarasvinām', null, 6081028),
('ramayana-6-81-29', 29, 'Yuddha Kanda, Sarga 81, Verse 29', 'चतुर्दशसहस्राणि सारोहाणां च वाजिनाम्।
पूर्णे शतसहस्रे द्वे राक्षसानां पदातिनाम्॥', 'caturdaśasahasrāṇi sārohāṇāṃ ca vājinām
pūrṇe śatasahasre dve rākṣasānāṃ padātinām', null, 6081029),
('ramayana-6-81-30', 30, 'Yuddha Kanda, Sarga 81, Verse 30', 'दिवसस्याष्टमे भागे शरैरग्निशिखोपमैः।
हतान्येकेन रामेण रक्षसां कामरूपिणाम्॥', 'divasasyāṣṭame bhāge śarair agniśikhopamaiḥ
hatāny ekena rāmeṇa rakṣasāṃ kāmarūpiṇām', null, 6081030),
('ramayana-6-81-31', 31, 'Yuddha Kanda, Sarga 81, Verse 31', 'ते हताश्वा हतरथाः श्रान्ता विमथितध्वजाः।
अभिपेतुः पुरीं लङ्कां हतशेषा निशाचराः॥', 'te hatāśvā hatarathāḥ śrāntā vimathitadhvajāḥ
abhipetuḥ purīṃ laṅkāṃ hataśeṣā niśācarāḥ', null, 6081031),
('ramayana-6-81-32', 32, 'Yuddha Kanda, Sarga 81, Verse 32', 'हतैर्गजपदात्यश्वैस्तद्बभूव रणाजिरम्।
आक्रीडभूमी रुद्रस्य क्रुद्धस्येव पिनाकिनः॥', 'hatair gajapadāty aśvais tad babhūva raṇājiram
ākrīḍabhūmī rudrasya kruddhasyeva pinākinaḥ', null, 6081032),
('ramayana-6-81-33', 33, 'Yuddha Kanda, Sarga 81, Verse 33', 'ततो देवाः सगन्धर्वाः सिद्धाश्च परमर्षयः।
साधु साध्विति रामस्य तत्कर्म समपूजयन्॥', 'tato devāḥ sagandharvāḥ siddhāś ca paramarṣayaḥ
sādhu sādhv iti rāmasya tat karma samapūjayan', null, 6081033),
('ramayana-6-81-34', 34, 'Yuddha Kanda, Sarga 81, Verse 34', 'अब्रवीच्च तदा रामः सुग्रीवं प्रत्यनन्तरम्।
एतदस्त्रबलं दिव्यं मम वा त्र्यम्बकस्य वा॥', 'abravīc ca tadā rāmaḥ sugrīvaṃ pratyanantaram
etad astrabalaṃ divyaṃ mama vā tryambakasya vā', null, 6081034),
('ramayana-6-81-35', 35, 'Yuddha Kanda, Sarga 81, Verse 35', 'निहत्य तां राक्षसवाहिनीं तु रामस्तदा शक्रसमो महात्मा।
अस्त्रेषु शस्त्रेषु जितक्लमश्च संस्तूयते देवगणैः प्रहृष्टैः॥', 'nihatya tāṃ rākṣasavāhinīṃ tu rāmas tadā śakrasamo mahātmā
astreṣu śastreṣu jitaklamaś ca saṃstūyate devagaṇaiḥ prahṛṣṭaiḥ', null, 6081035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 82 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-82-1', 1, 'Yuddha Kanda, Sarga 82, Verse 1', 'तानि नागसहस्राणि सारोहाणां च वाजिनाम्।
रथानां चाग्निवर्णानां सध्वजानां सहस्रशः॥', 'tāni nāgasahasrāṇi sārohāṇāṃ ca vājinām
rathānāṃ cāgnivarṇānāṃ sadhvajānāṃ sahasraśaḥ', null, 6082001),
('ramayana-6-82-2', 2, 'Yuddha Kanda, Sarga 82, Verse 2', 'राक्षसानां सहस्राणि गदापरिघयोधिनाम्।
काञ्चनध्वजचित्राणां शूराणां कामरूपिणाम्॥', 'rākṣasānāṃ sahasrāṇi gadāparighayodhinām
kāñcanadhvajacitrāṇāṃ śūrāṇāṃ kāmarūpiṇām', null, 6082002),
('ramayana-6-82-3', 3, 'Yuddha Kanda, Sarga 82, Verse 3', 'निहतानि शरैस्तीक्ष्णैस्तप्तकाञ्चनभूषणैः।
रावणेन प्रयुक्तानि रामेणाक्लिष्टकर्मणा॥', 'nihatāni śarais tīkṣṇais taptakāñcanabhūṣaṇaiḥ
rāvaṇena prayuktāni rāmeṇākliṣṭakarmaṇā', null, 6082003),
('ramayana-6-82-4', 4, 'Yuddha Kanda, Sarga 82, Verse 4', 'दृष्ट्वा श्रुत्वा च संभ्रान्ता हतशेषा निशाचराः।
राक्षस्यश्च समागम्य दीनाश्चिन्तापरिप्लुताः॥', 'dṛṣṭvā śrutvā ca saṃbhrāntā hataśeṣā niśācarāḥ
rākṣasyaś ca samāgamya dīnāś cintāpariplutāḥ', null, 6082004),
('ramayana-6-82-5', 5, 'Yuddha Kanda, Sarga 82, Verse 5', 'विधवा हतपुत्राश्च क्रोशन्त्यो हतबान्धवाः।
राक्षस्यः सह संगम्य दुःखार्ताः पर्यदेवयन्॥', 'vidhavā hataputrāś ca krośantyo hatabāndhavāḥ
rākṣasyaḥ saha saṃgamya duḥkhārtāḥ paryadevayan', null, 6082005),
('ramayana-6-82-6', 6, 'Yuddha Kanda, Sarga 82, Verse 6', 'कथं शूर्पणखा वृद्धा कराला निर्णतोदरी।
आससाद वने रामं कन्दर्पमिव रूपिणम्॥', 'kathaṃ śūrpaṇakhā vṛddhā karālā nirṇatodarī
āsasāda vane rāmaṃ kandarpam iva rūpiṇam', null, 6082006),
('ramayana-6-82-7', 7, 'Yuddha Kanda, Sarga 82, Verse 7', 'सुकुमारं महासत्त्वं सर्वभूतहिते रतम्।
तं दृष्ट्वा लोकवध्या सा हीनरूपा प्रकामिता॥', 'sukumāraṃ mahāsattvaṃ sarvabhūtahite ratam
taṃ dṛṣṭvā lokavadhyā sā hīnarūpā prakāmitā', null, 6082007),
('ramayana-6-82-8', 8, 'Yuddha Kanda, Sarga 82, Verse 8', 'कथं सर्वगुणैर्हीना गुणवन्तं महौजसं।
सुमुखं दुर्मुखी रामं कामयामास राक्षसी॥', 'kathaṃ sarvaguṇair hīnā guṇavantaṃ mahaujasaṃ
sumukhaṃ durmukhī rāmaṃ kāmayām āsa rākṣasī', null, 6082008),
('ramayana-6-82-9', 9, 'Yuddha Kanda, Sarga 82, Verse 9', 'जनस्यास्याल्पभाग्यत्वात्पलिनी श्वेतमूर्धजा।
अकार्यमपहास्यं च सर्वलोकविगर्हितम्॥', 'janasyāsyālpabhāgyatvāt palinī śvetamūrdhajā
akāryam apahāsyaṃ ca sarvalokavigarhitam', null, 6082009),
('ramayana-6-82-10', 10, 'Yuddha Kanda, Sarga 82, Verse 10', 'राक्षसानां विनाशाय दूषणस्य खरस्य च।
चकाराप्रतिरूपा सा राघवस्य प्रधर्षणम्॥', 'rākṣasānāṃ vināśāya dūṣaṇasya kharasya ca
cakārāpratirūpā sā rāghavasya pradharṣaṇam', null, 6082010),
('ramayana-6-82-11', 11, 'Yuddha Kanda, Sarga 82, Verse 11', 'तन्निमित्तमिदं वैरं रावणेन कृतं महत्।
वधाय नीता सा सीता दशग्रीवेण रक्षसा॥', 'tan nimittam idaṃ vairaṃ rāvaṇena kṛtaṃ mahat
vadhāya nītā sā sītā daśagrīveṇa rakṣasā', null, 6082011),
('ramayana-6-82-12', 12, 'Yuddha Kanda, Sarga 82, Verse 12', 'न च सीतां दशग्रीवः प्राप्नोति जनकात्मजाम्।
बद्धं बलवता वैरमक्षयं राघवेण ह॥', 'na ca sītāṃ daśagrīvaḥ prāpnoti janakātmajām
baddhaṃ balavatā vairam akṣayaṃ rāghaveṇa ha', null, 6082012),
('ramayana-6-82-13', 13, 'Yuddha Kanda, Sarga 82, Verse 13', 'वैदेहीं प्रार्थयानं तं विराधं प्रेक्ष्य राक्षसं।
हतमेकेन रामेण पर्याप्तं तन्निदर्शनम्॥', 'vaidehīṃ prārthayānaṃ taṃ virādhaṃ prekṣya rākṣasaṃ
hatam ekena rāmeṇa paryāptaṃ tannidarśanam', null, 6082013),
('ramayana-6-82-14', 14, 'Yuddha Kanda, Sarga 82, Verse 14', 'चतुर्दशसहस्राणि रक्षसां भीमकर्मणाम्।
निहतानि जनस्थाने शरैरग्निशिखोपमैः॥', 'caturdaśasahasrāṇi rakṣasāṃ bhīmakarmaṇām
nihatāni janasthāne śarair agniśikhopamaiḥ', null, 6082014),
('ramayana-6-82-15', 15, 'Yuddha Kanda, Sarga 82, Verse 15', 'खरश्च निहतः संख्ये दूषणस्त्रिशिरास्तथा।
शरैरादित्यसंकाशैः पर्याप्तं तन्निदर्शनम्॥', 'kharaś ca nihataḥ saṃkhye dūṣaṇas triśirās tathā
śarair ādityasaṃkāśaiḥ paryāptaṃ tannidarśanam', null, 6082015),
('ramayana-6-82-16', 16, 'Yuddha Kanda, Sarga 82, Verse 16', 'हतो योजनबाहुश्च कबन्धो रुधिराशनः।
क्रोधार्तो विनदन्सोऽथ पर्याप्तं तन्निदर्शनम्॥', 'hato yojanabāhuś ca kabandho rudhirāśanaḥ
krodhārto vinadan so ''tha paryāptaṃ tannidarśanam', null, 6082016),
('ramayana-6-82-17', 17, 'Yuddha Kanda, Sarga 82, Verse 17', 'जघान बलिनं रामः सहस्रनयनात्मजम्।
बालिनं मेघसंकाशं पर्याप्तं तन्निदर्शनम्॥', 'jaghāna balinaṃ rāmaḥ sahasranayanātmajam
bālinaṃ meghasaṃkāśaṃ paryāptaṃ tannidarśanam', null, 6082017),
('ramayana-6-82-18', 18, 'Yuddha Kanda, Sarga 82, Verse 18', 'ऋश्यमूके वसञ्शैले दीनो भग्नमनोरथः।
सुग्रीवः स्थापितो राज्ये पर्याप्तं तन्निदर्शनम्॥', 'ṛśyamūke vasañ śaile dīno bhagnamanorathaḥ
sugrīvaḥ sthāpito rājye paryāptaṃ tannidarśanam', null, 6082018),
('ramayana-6-82-19', 19, 'Yuddha Kanda, Sarga 82, Verse 19', 'धर्मार्थसहितं वाक्यं सर्वेषां रक्षसां हितम्।
युक्तं विभीषणेनोक्तं मोहात्तस्य न रोचते॥', 'dharmārthasahitaṃ vākyaṃ sarveṣāṃ rakṣasāṃ hitam
yuktaṃ vibhīṣaṇenoktaṃ mohāt tasya na rocate', null, 6082019),
('ramayana-6-82-20', 20, 'Yuddha Kanda, Sarga 82, Verse 20', 'विभीषणवचः कुर्याद्यदि स्म धनदानुजः।
श्मशानभूता दुःखार्ता नेयं लङ्का पुरी भवेत्॥', 'vibhīṣaṇavacaḥ kuryād yadi sma dhanadānujaḥ
śmaśānabhūtā duḥkhārtā neyaṃ laṅkā purī bhavet', null, 6082020),
('ramayana-6-82-21', 21, 'Yuddha Kanda, Sarga 82, Verse 21', 'कुम्भकर्णं हतं श्रुत्वा राघवेण महाबलम्।
प्रियं चेन्द्रजितं पुत्रं रावणो नावबुध्यते॥', 'kumbhakarṇaṃ hataṃ śrutvā rāghaveṇa mahābalam
priyaṃ cendrajitaṃ putraṃ rāvaṇo nāvabudhyate', null, 6082021),
('ramayana-6-82-22', 22, 'Yuddha Kanda, Sarga 82, Verse 22', 'मम पुत्रो मम भ्राता मम भर्ता रणे हतः।
इत्येवं श्रूयते शब्दो राक्षसानां कुले कुले॥', 'mama putro mama bhrātā mama bhartā raṇe hataḥ
ity evaṃ śrūyate śabdo rākṣasānāṃ kule kule', null, 6082022),
('ramayana-6-82-23', 23, 'Yuddha Kanda, Sarga 82, Verse 23', 'रथाश्चाश्वाश्च नागाश्च हताः शतसहस्रशः।
रणे रामेण शूरेण राक्षसाश्च पदातयः॥', 'rathāś cāśvāś ca nāgāś ca hatāḥ śatasahasraśaḥ
raṇe rāmeṇa śūreṇa rākṣasāś ca padātayaḥ', null, 6082023),
('ramayana-6-82-24', 24, 'Yuddha Kanda, Sarga 82, Verse 24', 'रुद्रो वा यदि वा विष्णुर्महेन्द्रो वा शतक्रतुः।
हन्ति नो रामरूपेण यदि वा स्वयमन्तकः॥', 'rudro vā yadi vā viṣṇur mahendro vā śatakratuḥ
hanti no rāmarūpeṇa yadi vā svayam antakaḥ', null, 6082024),
('ramayana-6-82-25', 25, 'Yuddha Kanda, Sarga 82, Verse 25', 'हतप्रवीरा रामेण निराशा जीविते वयम्।
अपश्यन्त्यो भयस्यान्तमनाथा विलपामहे॥', 'hatapravīrā rāmeṇa nirāśā jīvite vayam
apaśyantyo bhayasyāntam anāthā vilapāmahe', null, 6082025),
('ramayana-6-82-26', 26, 'Yuddha Kanda, Sarga 82, Verse 26', 'रामहस्ताद्दशग्रीवः शूरो दत्तवरो युधि।
इदं भयं महाघोरमुत्पन्नं नावबुध्यते॥', 'rāmahastād daśagrīvaḥ śūro dattavaro yudhi
idaṃ bhayaṃ mahāghoram utpannaṃ nāvabudhyate', null, 6082026),
('ramayana-6-82-27', 27, 'Yuddha Kanda, Sarga 82, Verse 27', 'न देवा न च गन्धर्वा न पिशाचा न राक्षसाः।
उपसृष्टं परित्रातुं शक्ता रामेण संयुगे॥', 'na devā na ca gandharvā na piśācā na rākṣasāḥ
upasṛṣṭaṃ paritrātuṃ śaktā rāmeṇa saṃyuge', null, 6082027),
('ramayana-6-82-28', 28, 'Yuddha Kanda, Sarga 82, Verse 28', 'उत्पाताश्चापि दृश्यन्ते रावणस्य रणे रणे।
कथयिष्यन्ति रामेण रावणस्य निबर्हणम्॥', 'utpātāś cāpi dṛśyante rāvaṇasya raṇe raṇe
kathayiṣyanti rāmeṇa rāvaṇasya nibarhaṇam', null, 6082028),
('ramayana-6-82-29', 29, 'Yuddha Kanda, Sarga 82, Verse 29', 'पितामहेन प्रीतेन देवदानवराक्षसैः।
रावणस्याभयं दत्तं मानुषेभ्यो न याचितम्॥', 'pitāmahena prītena devadānavarākṣasaiḥ
rāvaṇasyābhayaṃ dattaṃ mānuṣebhyo na yācitam', null, 6082029),
('ramayana-6-82-30', 30, 'Yuddha Kanda, Sarga 82, Verse 30', 'तदिदं मानुषान्मन्ये प्राप्तं निःसंशयं भयम्।
जीवितान्तकरं घोरं रक्षसां रावणस्य च॥', 'tad idaṃ mānuṣān manye prāptaṃ niḥsaṃśayaṃ bhayam
jīvitāntakaraṃ ghoraṃ rakṣasāṃ rāvaṇasya ca', null, 6082030),
('ramayana-6-82-31', 31, 'Yuddha Kanda, Sarga 82, Verse 31', 'पीड्यमानास्तु बलिना वरदानेन रक्षसा।
दीप्तैस्तपोभिर्विबुधाः पितामहमपूजयन्॥', 'pīḍyamānās tu balinā varadānena rakṣasā
dīptais tapobhir vibudhāḥ pitāmaham apūjayan', null, 6082031),
('ramayana-6-82-32', 32, 'Yuddha Kanda, Sarga 82, Verse 32', 'देवतानां हितार्थाय महात्मा वै पितामहः।
उवाच देवताः सर्वा इदं तुष्टो महद्वचः॥', 'devatānāṃ hitārthāya mahātmā vai pitāmahaḥ
uvāca devatāḥ sarvā idaṃ tuṣṭo mahad vacaḥ', null, 6082032),
('ramayana-6-82-33', 33, 'Yuddha Kanda, Sarga 82, Verse 33', 'अद्य प्रभृति लोकांस्त्रीन्सर्वे दानवराक्षसाः।
भयेन प्रावृता नित्यं विचरिष्यन्ति शाश्वतम्॥', 'adya prabhṛti lokāṃs trīn sarve dānavarākṣasāḥ
bhayena prāvṛtā nityaṃ vicariṣyanti śāśvatam', null, 6082033),
('ramayana-6-82-34', 34, 'Yuddha Kanda, Sarga 82, Verse 34', 'दैवतैस्तु समागम्य सर्वैश्चेन्द्रपुरोगमैः।
वृषध्वजस्त्रिपुरहा महादेवः प्रसादितः॥', 'daivatais tu samāgamya sarvaiś cendrapurogamaiḥ
vṛṣadhvajas tripurahā mahādevaḥ prasāditaḥ', null, 6082034),
('ramayana-6-82-35', 35, 'Yuddha Kanda, Sarga 82, Verse 35', 'प्रसन्नस्तु महादेवो देवानेतद्वचोऽब्रवीत्।
उत्पत्स्यति हितार्थं वो नारी रक्षःक्षयावहा॥', 'prasannas tu mahādevo devān etad vaco ''bravīt
utpatsyati hitārthaṃ vo nārī rakṣaḥkṣayāvahā', null, 6082035),
('ramayana-6-82-36', 36, 'Yuddha Kanda, Sarga 82, Verse 36', 'एषा देवैः प्रयुक्ता तु क्षुद्यथा दानवान्पुरा।
भक्षयिष्यति नः सीता राक्षसघ्नी सरावणान्॥', 'eṣā devaiḥ prayuktā tu kṣud yathā dānavān purā
bhakṣayiṣyati naḥ sītā rākṣasaghnī sarāvaṇān', null, 6082036),
('ramayana-6-82-37', 37, 'Yuddha Kanda, Sarga 82, Verse 37', 'रावणस्यापनीतेन दुर्विनीतस्य दुर्मतेः।
अयं निष्टानको घोरः शोकेन समभिप्लुतः॥', 'rāvaṇasyāpanītena durvinītasya durmateḥ
ayaṃ niṣṭānako ghoraḥ śokena samabhiplutaḥ', null, 6082037),
('ramayana-6-82-38', 38, 'Yuddha Kanda, Sarga 82, Verse 38', 'तं न पश्यामहे लोके यो नः शरणदो भवेत्।
राघवेणोपसृष्टानां कालेनेव युगक्षये॥', 'taṃ na paśyāmahe loke yo naḥ śaraṇado bhavet
rāghaveṇopasṛṣṭānāṃ kāleneva yugakṣaye', null, 6082038),
('ramayana-6-82-39', 39, 'Yuddha Kanda, Sarga 82, Verse 39', 'इतीव सर्वा रजनीचरस्त्रियः परस्परं संपरिरभ्य बाहुभिः।
विषेदुरार्तातिभयाभिपीडिता विनेदुरुच्चैश्च तदा सुदारुणम्॥', 'itīva sarvā rajanīcarastriyaḥ parasparaṃ saṃparirabhya bāhubhiḥ
viṣedur ārtātibhayābhipīḍitā vinedur uccaiś ca tadā sudāruṇam', null, 6082039)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 83 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-83-1', 1, 'Yuddha Kanda, Sarga 83, Verse 1', 'आर्तानां राक्षसीनां तु लङ्कायां वै कुले कुले।
रावणः करुणं शब्दं शुश्राव परिवेदितम्॥', 'ārtānāṃ rākṣasīnāṃ tu laṅkāyāṃ vai kule kule
rāvaṇaḥ karuṇaṃ śabdaṃ śuśrāva pariveditam', null, 6083001),
('ramayana-6-83-2', 2, 'Yuddha Kanda, Sarga 83, Verse 2', 'स तु दीर्घं विनिश्वस्य मुहूर्तं ध्यानमास्थितः।
बभूव परमक्रुद्धो रावणो भीमदर्शनः॥', 'sa tu dīrghaṃ viniśvasya muhūrtaṃ dhyānam āsthitaḥ
babhūva paramakruddho rāvaṇo bhīmadarśanaḥ', null, 6083002),
('ramayana-6-83-3', 3, 'Yuddha Kanda, Sarga 83, Verse 3', 'संदश्य दशनैरोष्ठं क्रोधसंरक्तलोचनः।
राक्षसैरपि दुर्दर्शः कालाग्निरिव मूर्छितः॥', 'saṃdaśya daśanair oṣṭhaṃ krodhasaṃraktalocanaḥ
rākṣasair api durdarśaḥ kālāgnir iva mūrchitaḥ', null, 6083003),
('ramayana-6-83-4', 4, 'Yuddha Kanda, Sarga 83, Verse 4', 'उवाच च समीपस्थान्राक्षसान्राक्षसेश्वरः।
भयाव्यक्तकथांस्तत्र निर्दहन्निव चक्षुषा॥', 'uvāca ca samīpasthān rākṣasān rākṣaseśvaraḥ
bhayāvyaktakathāṃs tatra nirdahann iva cakṣuṣā', null, 6083004),
('ramayana-6-83-5', 5, 'Yuddha Kanda, Sarga 83, Verse 5', 'महोदरं महापार्श्वं विरूपाक्षं च राक्षसं।
शीघ्रं वदत सैन्यानि निर्यातेति ममाज्ञया॥', 'mahodaraṃ mahāpārśvaṃ virūpākṣaṃ ca rākṣasaṃ
śīghraṃ vadata sainyāni niryāteti mamājñayā', null, 6083005),
('ramayana-6-83-6', 6, 'Yuddha Kanda, Sarga 83, Verse 6', 'तस्य तद्वचनं श्रुत्वा राक्षसास्ते भयार्दिताः।
चोदयामासुरव्यग्रान्राक्षसांस्तान्नृपाज्ञया॥', 'tasya tad vacanaṃ śrutvā rākṣasās te bhayārditāḥ
codayām āsur avyagrān rākṣasāṃs tān nṛpājñayā', null, 6083006),
('ramayana-6-83-7', 7, 'Yuddha Kanda, Sarga 83, Verse 7', 'ते तु सर्वे तथेत्युक्त्वा राक्षसा घोरदर्शनाः।
कृतस्वस्त्ययनाः सर्वे रावणाभिमुखा ययुः॥', 'te tu sarve tathety uktvā rākṣasā ghoradarśanāḥ
kṛtasvastyayanāḥ sarve rāvaṇābhimukhā yayuḥ', null, 6083007),
('ramayana-6-83-8', 8, 'Yuddha Kanda, Sarga 83, Verse 8', 'प्रतिपूज्य यथान्यायं रावणं ते महारथाः।
तस्थुः प्राञ्जलयः सर्वे भर्तुर्विजयकाङ्क्षिणः॥', 'pratipūjya yathānyāyaṃ rāvaṇaṃ te mahārathāḥ
tasthuḥ prāñjalayaḥ sarve bhartur vijayakāṅkṣiṇaḥ', null, 6083008),
('ramayana-6-83-9', 9, 'Yuddha Kanda, Sarga 83, Verse 9', 'अथोवाच प्रहस्यैतान्रावणः क्रोधमूर्छितः।
महोदरमहापार्श्वौ विरूपाक्षं च राक्षसं॥', 'athovāca prahasyaitān rāvaṇaḥ krodhamūrchitaḥ
mahodaramahāpārśvau virūpākṣaṃ ca rākṣasaṃ', null, 6083009),
('ramayana-6-83-10', 10, 'Yuddha Kanda, Sarga 83, Verse 10', 'अद्य बाणैर्धनुर्मुक्तैर्युगान्तादित्यसंनिभैः।
राघवं लक्ष्मणं चैव नेष्यामि यमसाधनम्॥', 'adya bāṇair dhanurmuktair yugāntādityasaṃnibhaiḥ
rāghavaṃ lakṣmaṇaṃ caiva neṣyāmi yamasādhanam', null, 6083010),
('ramayana-6-83-11', 11, 'Yuddha Kanda, Sarga 83, Verse 11', 'खरस्य कुम्भकर्णस्य प्रहस्तेन्द्रजितोस्तथा।
करिष्यामि प्रतीकारमद्य शत्रुवधादहम्॥', 'kharasya kumbhakarṇasya prahastendrajitos tathā
kariṣyāmi pratīkāram adya śatruvadhād aham', null, 6083011),
('ramayana-6-83-12', 12, 'Yuddha Kanda, Sarga 83, Verse 12', 'नैवान्तरिक्षं न दिशो न नद्यो नापि सागरः।
प्रकाशत्वं गमिष्यन्ति मद्बाणजलदावृताः॥', 'naivāntarikṣaṃ na diśo na nadyo nāpi sāgaraḥ
prakāśatvaṃ gamiṣyanti madbāṇajaladāvṛtāḥ', null, 6083012),
('ramayana-6-83-13', 13, 'Yuddha Kanda, Sarga 83, Verse 13', 'अद्य वानरयूथानां तानि यूथानि भागशः।
धनुःसमुद्रादुद्भूतैर्मथिष्यामि शरोर्मिभिः॥', 'adya vānarayūthānāṃ tāni yūthāni bhāgaśaḥ
dhanuḥsamudrād udbhūtair mathiṣyāmi śarormibhiḥ', null, 6083013),
('ramayana-6-83-14', 14, 'Yuddha Kanda, Sarga 83, Verse 14', 'व्याकोशपद्मचक्राणि पद्मकेसरवर्चसाम्।
अद्य यूथतटाकानि गजवत्प्रमथाम्यहम्॥', 'vyākośapadmacakrāṇi padmakesaravarcasām
adya yūthataṭākāni gajavat pramathāmy aham', null, 6083014),
('ramayana-6-83-15', 15, 'Yuddha Kanda, Sarga 83, Verse 15', 'सशरैरद्य वदनैः संख्ये वानरयूथपाः।
मण्डयिष्यन्ति वसुधां सनालैरिव पङ्कलैः॥', 'saśarair adya vadanaiḥ saṃkhye vānarayūthapāḥ
maṇḍayiṣyanti vasudhāṃ sanālair iva paṅkalaiḥ', null, 6083015),
('ramayana-6-83-16', 16, 'Yuddha Kanda, Sarga 83, Verse 16', 'अद्य युद्धप्रचण्डानां हरीणां द्रुमयोधिनाम्।
मुक्तेनैकेषुणा युद्धे भेत्स्यामि च शतंशतम्॥', 'adya yuddhapracaṇḍānāṃ harīṇāṃ drumayodhinām
muktenaikeṣuṇā yuddhe bhetsyāmi ca śataṃśatam', null, 6083016),
('ramayana-6-83-17', 17, 'Yuddha Kanda, Sarga 83, Verse 17', 'हतो भर्ता हतो भ्राता यासां च तनया हताः।
वधेनाद्य रिपोस्तासां कर्मोम्यस्रप्रमार्जनम्॥', 'hato bhartā hato bhrātā yāsāṃ ca tanayā hatāḥ
vadhenādya ripos tāsāṃ karmomy asrapramārjanam', null, 6083017),
('ramayana-6-83-18', 18, 'Yuddha Kanda, Sarga 83, Verse 18', 'अद्य मद्बाणनिर्भिन्नैः प्रकीर्णैर्गतचेतनैः।
करोमि वानरैर्युद्धे यत्नावेक्ष्यतलां महीम्॥', 'adya madbāṇanirbhinnaiḥ prakīrṇair gatacetanaiḥ
karomi vānarair yuddhe yatnāvekṣyatalāṃ mahīm', null, 6083018),
('ramayana-6-83-19', 19, 'Yuddha Kanda, Sarga 83, Verse 19', 'अद्य गोमायवो गृध्रा ये च मांसाशिनोऽपरे।
सर्वांस्तांस्तर्पयिष्यामि शत्रुमांसैः शरार्दितैः॥', 'adya gomāyavo gṛdhrā ye ca māṃsāśino ''pare
sarvāṃs tāṃs tarpayiṣyāmi śatrumāṃsaiḥ śarārditaiḥ', null, 6083019),
('ramayana-6-83-20', 20, 'Yuddha Kanda, Sarga 83, Verse 20', 'कल्प्यतां मे रथशीघ्रं क्षिप्रमानीयतां धनुः।
अनुप्रयान्तु मां युद्धे येऽवशिष्टा निशाचराः॥', 'kalpyatāṃ me rathaśīghraṃ kṣipram ānīyatāṃ dhanuḥ
anuprayāntu māṃ yuddhe ye ''vaśiṣṭā niśācarāḥ', null, 6083020),
('ramayana-6-83-21', 21, 'Yuddha Kanda, Sarga 83, Verse 21', 'तस्य तद्वचनं श्रुत्वा महापार्श्वोऽब्रवीद्वचः।
बलाध्यक्षान्स्थितांस्तत्र बलं संत्वर्यतामिति॥', 'tasya tad vacanaṃ śrutvā mahāpārśvo ''bravīd vacaḥ
balādhyakṣān sthitāṃs tatra balaṃ saṃtvaryatām iti', null, 6083021),
('ramayana-6-83-22', 22, 'Yuddha Kanda, Sarga 83, Verse 22', 'बलाध्यक्षास्तु संरब्धा राक्षसांस्तान्गृहाद्गृहात्।
चोदयन्तः परिययुर्लङ्कां लघुपराक्रमाः॥', 'balādhyakṣās tu saṃrabdhā rākṣasāṃs tān gṛhād gṛhāt
codayantaḥ pariyayur laṅkāṃ laghuparākramāḥ', null, 6083022),
('ramayana-6-83-23', 23, 'Yuddha Kanda, Sarga 83, Verse 23', 'ततो मुहूर्तान्निष्पेतू राक्षसा भीमविक्रमाः।
नर्दन्तो भीमवदना नानाप्रहरणैर्भुजैः॥', 'tato muhūrtān niṣpetū rākṣasā bhīmavikramāḥ
nardanto bhīmavadanā nānāpraharaṇair bhujaiḥ', null, 6083023),
('ramayana-6-83-24', 24, 'Yuddha Kanda, Sarga 83, Verse 24', 'असिभिः पट्टसैः शूलैर्गलाभिर्मुसलैर्हलैः।
शक्तिभिस्तीक्ष्णधाराभिर्महद्भिः कूटमुद्गरैः॥', 'asibhiḥ paṭṭasaiḥ śūlair galābhir musalair halaiḥ
śaktibhis tīkṣṇadhārābhir mahadbhiḥ kūṭamudgaraiḥ', null, 6083024),
('ramayana-6-83-25', 25, 'Yuddha Kanda, Sarga 83, Verse 25', 'यष्टिभिर्विमलैश्चक्रैर्निशितैश्च परश्वधैः।
भिण्डिपालैः शतघ्नीभिरन्यैश्चापि वरायुधैः॥', 'yaṣṭibhir vimalaiś cakrair niśitaiś ca paraśvadhaiḥ
bhiṇḍipālaiḥ śataghnībhir anyaiś cāpi varāyudhaiḥ', null, 6083025),
('ramayana-6-83-26', 26, 'Yuddha Kanda, Sarga 83, Verse 26', 'अथानयन्बलाध्यक्षाश्चत्वारो रावणाज्ञया।
द्रुतं सूतसमायुक्तं युक्ताष्टतुरगं रथम्॥', 'athānayan balādhyakṣāś catvāro rāvaṇājñayā
drutaṃ sūtasamāyuktaṃ yuktāṣṭaturagaṃ ratham', null, 6083026),
('ramayana-6-83-27', 27, 'Yuddha Kanda, Sarga 83, Verse 27', 'आरुरोह रथं दिव्यं दीप्यमानं स्वतेजसा।
रावणः सत्त्वगाम्भीर्याद्दारयन्निव मेदिनीम्॥', 'āruroha rathaṃ divyaṃ dīpyamānaṃ svatejasā
rāvaṇaḥ sattvagāmbhīryād dārayann iva medinīm', null, 6083027),
('ramayana-6-83-28', 28, 'Yuddha Kanda, Sarga 83, Verse 28', 'रावणेनाभ्यनुज्ञातौ महापार्श्वमहोदरौ।
विरूपाक्षश्च दुर्धर्षो रथानारुरुहुस्तदा॥', 'rāvaṇenābhyanujñātau mahāpārśvamahodarau
virūpākṣaś ca durdharṣo rathān āruruhus tadā', null, 6083028),
('ramayana-6-83-29', 29, 'Yuddha Kanda, Sarga 83, Verse 29', 'ते तु हृष्टा विनर्दन्तो भिन्दन्त इव मेदिनीम्।
नादं घोरं विमुञ्चन्तो निर्ययुर्जयकाङ्क्षिणः॥', 'te tu hṛṣṭā vinardanto bhindanta iva medinīm
nādaṃ ghoraṃ vimuñcanto niryayur jayakāṅkṣiṇaḥ', null, 6083029),
('ramayana-6-83-30', 30, 'Yuddha Kanda, Sarga 83, Verse 30', 'ततो युद्धाय तेजस्वी रक्षोगणबलैर्वृतः।
निर्ययावुद्यतधनुः कालान्तकयमोमपः॥', 'tato yuddhāya tejasvī rakṣogaṇabalair vṛtaḥ
niryayāv udyatadhanuḥ kālāntakayamomapaḥ', null, 6083030),
('ramayana-6-83-31', 31, 'Yuddha Kanda, Sarga 83, Verse 31', 'ततः प्रजवनाश्वेन रथेन स महारथः।
द्वारेण निर्ययौ तेन यत्र तौ रामलक्ष्मणौ॥', 'tataḥ prajavanāśvena rathena sa mahārathaḥ
dvāreṇa niryayau tena yatra tau rāmalakṣmaṇau', null, 6083031),
('ramayana-6-83-32', 32, 'Yuddha Kanda, Sarga 83, Verse 32', 'ततो नष्टप्रभः सूर्यो दिशश्च तिमिरावृताः।
द्विजाश्च नेदुर्घोराश्च संचचाल च मेदिनी॥', 'tato naṣṭaprabhaḥ sūryo diśaś ca timirāvṛtāḥ
dvijāś ca nedur ghorāś ca saṃcacāla ca medinī', null, 6083032),
('ramayana-6-83-33', 33, 'Yuddha Kanda, Sarga 83, Verse 33', 'ववर्ष रुधिरं देवश्चस्खलुश्च तुरंगमाः।
ध्वजाग्रे न्यपतद्गृध्रो विनेदुश्चाशिवं शिवाः॥', 'vavarṣa rudhiraṃ devaś caskhaluś ca turaṃgamāḥ
dhvajāgre nyapatad gṛdhro vineduś cāśivaṃ śivāḥ', null, 6083033),
('ramayana-6-83-34', 34, 'Yuddha Kanda, Sarga 83, Verse 34', 'नयनं चास्फुरद्वामं सव्यो बाहुरकम्पत।
विवर्णवदनश्चासीत्किं चिदभ्रश्यत स्वरः॥', 'nayanaṃ cāsphurad vāmaṃ savyo bāhur akampata
vivarṇavadanaś cāsīt kiṃ cid abhraśyata svaraḥ', null, 6083034),
('ramayana-6-83-35', 35, 'Yuddha Kanda, Sarga 83, Verse 35', 'ततो निष्पततो युद्धे दशग्रीवस्य रक्षसः।
रणे निधनशंसीनि रूपाण्येतानि जज्ञिरे॥', 'tato niṣpatato yuddhe daśagrīvasya rakṣasaḥ
raṇe nidhanaśaṃsīni rūpāṇy etāni jajñire', null, 6083035),
('ramayana-6-83-36', 36, 'Yuddha Kanda, Sarga 83, Verse 36', 'अन्तरिक्षात्पपातोल्का निर्घातसमनिस्वना।
विनेदुरशिवं गृध्रा वायसैरनुनादिताः॥', 'antarikṣāt papātolkā nirghātasamanisvanā
vinedur aśivaṃ gṛdhrā vāyasair anunāditāḥ', null, 6083036),
('ramayana-6-83-37', 37, 'Yuddha Kanda, Sarga 83, Verse 37', 'एतानचिन्तयन्घोरानुत्पातान्समुपस्थितान्।
निर्ययौ रावणो मोहाद्वधार्थी कालचोदितः॥', 'etān acintayan ghorān utpātān samupasthitān
niryayau rāvaṇo mohād vadhārthī kālacoditaḥ', null, 6083037),
('ramayana-6-83-38', 38, 'Yuddha Kanda, Sarga 83, Verse 38', 'तेषां तु रथघोषेण राक्षसानां महात्मनाम्।
वानराणामपि चमूर्युद्धायैवाभ्यवर्तत॥', 'teṣāṃ tu rathaghoṣeṇa rākṣasānāṃ mahātmanām
vānarāṇām api camūr yuddhāyaivābhyavartata', null, 6083038),
('ramayana-6-83-39', 39, 'Yuddha Kanda, Sarga 83, Verse 39', 'तेषां सुतुमुलं युद्धं बभूव कपिरक्षसाम्।
अन्योन्यमाह्वयानानां क्रुद्धानां जयमिच्छताम्॥', 'teṣāṃ sutumulaṃ yuddhaṃ babhūva kapirakṣasām
anyonyam āhvayānānāṃ kruddhānāṃ jayam icchatām', null, 6083039),
('ramayana-6-83-40', 40, 'Yuddha Kanda, Sarga 83, Verse 40', 'ततः क्रुद्धो दशग्रीवः शरैः काञ्चनभूषणैः।
वानराणामनीकेषु चकार कदनं महत्॥', 'tataḥ kruddho daśagrīvaḥ śaraiḥ kāñcanabhūṣaṇaiḥ
vānarāṇām anīkeṣu cakāra kadanaṃ mahat', null, 6083040),
('ramayana-6-83-41', 41, 'Yuddha Kanda, Sarga 83, Verse 41', 'निकृत्तशिरसः के चिद्रावणेन वलीमुखाः।
निरुच्छ्वासा हताः के चित्के चित्पार्श्वेषु दारिताः।
के चिद्विभिन्नशिरसः के चिच्चक्षुर्विवर्जिताः॥', 'nikṛttaśirasaḥ ke cid rāvaṇena valīmukhāḥ
nirucchvāsā hatāḥ ke cit ke cit pārśveṣu dāritāḥ
ke cid vibhinnaśirasaḥ ke cic cakṣurvivarjitāḥ', null, 6083041),
('ramayana-6-83-42', 42, 'Yuddha Kanda, Sarga 83, Verse 42', 'दशाननः क्रोधविवृत्तनेत्रो यतो यतोऽभ्येति रथेन संख्ये।
ततस्ततस्तस्य शरप्रवेगं सोढुं न शेकुर्हरियूथपास्ते॥', 'daśānanaḥ krodhavivṛttanetro yato yato ''bhyeti rathena saṃkhye
tatas tatas tasya śarapravegaṃ soḍhuṃ na śekur hariyūthapās te', null, 6083042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 84 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-84-1', 1, 'Yuddha Kanda, Sarga 84, Verse 1', 'तथा तैः कृत्तगात्रैस्तु दशग्रीवेण मार्गणैः।
बभूव वसुधा तत्र प्रकीर्णा हरिभिर्वृता॥', 'tathā taiḥ kṛttagātrais tu daśagrīveṇa mārgaṇaiḥ
babhūva vasudhā tatra prakīrṇā haribhir vṛtā', null, 6084001),
('ramayana-6-84-2', 2, 'Yuddha Kanda, Sarga 84, Verse 2', 'रावणस्याप्रसह्यं तं शरसंपातमेकतः।
न शेकुः सहितुं दीप्तं पतंगा इव पावकम्॥', 'rāvaṇasyāprasahyaṃ taṃ śarasaṃpātam ekataḥ
na śekuḥ sahituṃ dīptaṃ pataṃgā iva pāvakam', null, 6084002),
('ramayana-6-84-3', 3, 'Yuddha Kanda, Sarga 84, Verse 3', 'तेऽर्दिता निशितैर्बाणैः क्रोशन्तो विप्रदुद्रुवुः।
पावकार्चिःसमाविष्टा दह्यमाना यथा गजाः॥', 'te ''rditā niśitair bāṇaiḥ krośanto vipradudruvuḥ
pāvakārciḥsamāviṣṭā dahyamānā yathā gajāḥ', null, 6084003),
('ramayana-6-84-4', 4, 'Yuddha Kanda, Sarga 84, Verse 4', 'प्लवंगानामनीकानि महाभ्राणीव मारुतः।
स ययौ समरे तस्मिन्विधमन्रावणः शरैः॥', 'plavaṃgānām anīkāni mahābhrāṇīva mārutaḥ
sa yayau samare tasmin vidhaman rāvaṇaḥ śaraiḥ', null, 6084004),
('ramayana-6-84-5', 5, 'Yuddha Kanda, Sarga 84, Verse 5', 'कदनं तरसा कृत्वा राक्षसेन्द्रो वनौकसाम्।
आससाद ततो युद्धे राघवं त्वरितस्तदा॥', 'kadanaṃ tarasā kṛtvā rākṣasendro vanaukasām
āsasāda tato yuddhe rāghavaṃ tvaritas tadā', null, 6084005),
('ramayana-6-84-6', 6, 'Yuddha Kanda, Sarga 84, Verse 6', 'सुग्रीवस्तान्कपीन्दृष्ट्वा भग्नान्विद्रवतो रणे।
गुल्मे सुषेणं निक्षिप्य चक्रे युद्धे द्रुतं मनः॥', 'sugrīvas tān kapīn dṛṣṭvā bhagnān vidravato raṇe
gulme suṣeṇaṃ nikṣipya cakre yuddhe drutaṃ manaḥ', null, 6084006),
('ramayana-6-84-7', 7, 'Yuddha Kanda, Sarga 84, Verse 7', 'आत्मनः सदृशं वीरं स तं निक्षिप्य वानरम्।
सुग्रीवोऽभिमुखः शत्रुं प्रतस्थे पादपायुधः॥', 'ātmanaḥ sadṛśaṃ vīraṃ sa taṃ nikṣipya vānaram
sugrīvo ''bhimukhaḥ śatruṃ pratasthe pādapāyudhaḥ', null, 6084007),
('ramayana-6-84-8', 8, 'Yuddha Kanda, Sarga 84, Verse 8', 'पार्श्वतः पृष्ठतश्चास्य सर्वे यूथाधिपाः स्वयम्।
अनुजह्रुर्महाशैलान्विविधांश्च महाद्रुमान्॥', 'pārśvataḥ pṛṣṭhataś cāsya sarve yūthādhipāḥ svayam
anujahrur mahāśailān vividhāṃś ca mahādrumān', null, 6084008),
('ramayana-6-84-9', 9, 'Yuddha Kanda, Sarga 84, Verse 9', 'स नदन्युधि सुग्रीवः स्वरेण महता महान्।
पातयन्विविधांश्चान्याञ्जघानोत्तमराक्षसान्॥', 'sa nadan yudhi sugrīvaḥ svareṇa mahatā mahān
pātayan vividhāṃś cānyāñ jaghānottamarākṣasān', null, 6084009),
('ramayana-6-84-10', 10, 'Yuddha Kanda, Sarga 84, Verse 10', 'ममर्द च महाकायो राक्षसान्वानरेश्वरः।
युगान्तसमये वायुः प्रवृद्धानगमानिव॥', 'mamarda ca mahākāyo rākṣasān vānareśvaraḥ
yugāntasamaye vāyuḥ pravṛddhān agamān iva', null, 6084010),
('ramayana-6-84-11', 11, 'Yuddha Kanda, Sarga 84, Verse 11', 'राक्षसानामनीकेषु शैलवर्षं ववर्ष ह।
अश्मवर्षं यथा मेघः पक्षिसंघेषु कानने॥', 'rākṣasānām anīkeṣu śailavarṣaṃ vavarṣa ha
aśmavarṣaṃ yathā meghaḥ pakṣisaṃgheṣu kānane', null, 6084011),
('ramayana-6-84-12', 12, 'Yuddha Kanda, Sarga 84, Verse 12', 'कपिराजविमुक्तैस्तैः शैलवर्षैस्तु राक्षसाः।
विकीर्णशिरसः पेतुर्निकृत्ता इव पर्वताः॥', 'kapirājavimuktais taiḥ śailavarṣais tu rākṣasāḥ
vikīrṇaśirasaḥ petur nikṛttā iva parvatāḥ', null, 6084012),
('ramayana-6-84-13', 13, 'Yuddha Kanda, Sarga 84, Verse 13', 'अथ संक्षीयमाणेषु राक्षसेषु समन्ततः।
सुग्रीवेण प्रभग्नेषु पतत्सु विनदत्सु च॥', 'atha saṃkṣīyamāṇeṣu rākṣaseṣu samantataḥ
sugrīveṇa prabhagneṣu patatsu vinadatsu ca', null, 6084013),
('ramayana-6-84-14', 14, 'Yuddha Kanda, Sarga 84, Verse 14', 'विरूपाक्षः स्वकं नाम धन्वी विश्राव्य राक्षसः।
रथादाप्लुत्य दुर्धर्षो गजस्कन्धमुपारुहत्॥', 'virūpākṣaḥ svakaṃ nāma dhanvī viśrāvya rākṣasaḥ
rathād āplutya durdharṣo gajaskandham upāruhat', null, 6084014),
('ramayana-6-84-15', 15, 'Yuddha Kanda, Sarga 84, Verse 15', 'स तं द्विरदमारुह्य विरूपाक्षो महारथः।
विनदन्भीमनिर्ह्रालं वानरानभ्यधावत॥', 'sa taṃ dviradam āruhya virūpākṣo mahārathaḥ
vinadan bhīmanirhrālaṃ vānarān abhyadhāvata', null, 6084015),
('ramayana-6-84-16', 16, 'Yuddha Kanda, Sarga 84, Verse 16', 'सुग्रीवे स शरान्घोरान्विससर्ज चमूमुखे।
स्थापयामासा चोद्विग्नान्राक्षसान्संप्रहर्षयन्॥', 'sugrīve sa śarān ghorān visasarja camūmukhe
sthāpayām āsā codvignān rākṣasān saṃpraharṣayan', null, 6084016),
('ramayana-6-84-17', 17, 'Yuddha Kanda, Sarga 84, Verse 17', 'सोऽतिविद्धः शितैर्बाणैः कपीन्द्रस्तेन रक्षसा।
चुक्रोध च महाक्रोधो वधे चास्य मनो दधे॥', 'so ''tividdhaḥ śitair bāṇaiḥ kapīndras tena rakṣasā
cukrodha ca mahākrodho vadhe cāsya mano dadhe', null, 6084017),
('ramayana-6-84-18', 18, 'Yuddha Kanda, Sarga 84, Verse 18', 'ततः पादपमुद्धृत्य शूरः संप्रधने हरिः।
अभिपत्य जघानास्य प्रमुखे तं महागजम्॥', 'tataḥ pādapam uddhṛtya śūraḥ saṃpradhane hariḥ
abhipatya jaghānāsya pramukhe taṃ mahāgajam', null, 6084018),
('ramayana-6-84-19', 19, 'Yuddha Kanda, Sarga 84, Verse 19', 'स तु प्रहाराभिहतः सुग्रीवेण महागजः।
अपासर्पद्धनुर्मात्रं निषसाद ननाद च॥', 'sa tu prahārābhihataḥ sugrīveṇa mahāgajaḥ
apāsarpad dhanurmātraṃ niṣasāda nanāda ca', null, 6084019),
('ramayana-6-84-20', 20, 'Yuddha Kanda, Sarga 84, Verse 20', 'गजात्तु मथितात्तूर्णमपक्रम्य स वीर्यवान्।
राक्षसोऽभिमुखः शत्रुं प्रत्युद्गम्य ततः कपिम्॥', 'gajāt tu mathitāt tūrṇam apakramya sa vīryavān
rākṣaso ''bhimukhaḥ śatruṃ pratyudgamya tataḥ kapim', null, 6084020),
('ramayana-6-84-21', 21, 'Yuddha Kanda, Sarga 84, Verse 21', 'आर्षभं चर्मखड्गं च प्रगृह्य लघुविक्रमः।
भर्त्सयन्निव सुग्रीवमाससाद व्यवस्थितम्॥', 'ārṣabhaṃ carmakhaḍgaṃ ca pragṛhya laghuvikramaḥ
bhartsayann iva sugrīvam āsasāda vyavasthitam', null, 6084021),
('ramayana-6-84-22', 22, 'Yuddha Kanda, Sarga 84, Verse 22', 'स हि तस्याभिसंक्रुद्धः प्रगृह्य महतीं शिलाम्।
विरूपाक्षाय चिक्षेप सुग्रीवो जलदोपमाम्॥', 'sa hi tasyābhisaṃkruddhaḥ pragṛhya mahatīṃ śilām
virūpākṣāya cikṣepa sugrīvo jaladopamām', null, 6084022),
('ramayana-6-84-23', 23, 'Yuddha Kanda, Sarga 84, Verse 23', 'स तां शिलामापतन्तीं दृष्ट्वा राक्षसपुंगवः।
अपक्रम्य सुविक्रान्तः खड्गेन प्राहरत्तदा॥', 'sa tāṃ śilām āpatantīṃ dṛṣṭvā rākṣasapuṃgavaḥ
apakramya suvikrāntaḥ khaḍgena prāharat tadā', null, 6084023),
('ramayana-6-84-24', 24, 'Yuddha Kanda, Sarga 84, Verse 24', 'तेन खड्गेन संक्रुद्धः सुग्रीवस्य चमूमुखे।
कवचं पातयामास स खड्गाभिहतोऽपतत्॥', 'tena khaḍgena saṃkruddhaḥ sugrīvasya camūmukhe
kavacaṃ pātayām āsa sa khaḍgābhihato ''patat', null, 6084024),
('ramayana-6-84-25', 25, 'Yuddha Kanda, Sarga 84, Verse 25', 'स समुत्थाय पतितः कपिस्तस्य व्यसर्जयत्।
तलप्रहारमशनेः समानं भीमनिस्वनम्॥', 'sa samutthāya patitaḥ kapis tasya vyasarjayat
talaprahāram aśaneḥ samānaṃ bhīmanisvanam', null, 6084025),
('ramayana-6-84-26', 26, 'Yuddha Kanda, Sarga 84, Verse 26', 'तलप्रहारं तद्रक्षः सुग्रीवेण समुद्यतम्।
नैपुण्यान्मोचयित्वैनं मुष्टिनोरस्यताडयत्॥', 'talaprahāraṃ tad rakṣaḥ sugrīveṇa samudyatam
naipuṇyān mocayitvainaṃ muṣṭinorasy atāḍayat', null, 6084026),
('ramayana-6-84-27', 27, 'Yuddha Kanda, Sarga 84, Verse 27', 'ततस्तु संक्रुद्धतरः सुग्रीवो वानरेश्वरः।
मोक्षितं चात्मनो दृष्ट्वा प्रहारं तेन रक्षसा॥', 'tatas tu saṃkruddhataraḥ sugrīvo vānareśvaraḥ
mokṣitaṃ cātmano dṛṣṭvā prahāraṃ tena rakṣasā', null, 6084027),
('ramayana-6-84-28', 28, 'Yuddha Kanda, Sarga 84, Verse 28', 'स ददर्शान्तरं तस्य विरूपाक्षस्य वानरः।
ततो न्यपातयत्क्रोधाच्छङ्खदेशे महातलम्॥', 'sa dadarśāntaraṃ tasya virūpākṣasya vānaraḥ
tato nyapātayat krodhāc chaṅkhadeśe mahātalam', null, 6084028),
('ramayana-6-84-29', 29, 'Yuddha Kanda, Sarga 84, Verse 29', 'महेन्द्राशनिकल्पेन तलेनाभिहतः क्षितौ।
पपात रुधिरक्लिन्नः शोणितं स समुद्वमन्॥', 'mahendrāśanikalpena talenābhihataḥ kṣitau
papāta rudhiraklinnaḥ śoṇitaṃ sa samudvaman', null, 6084029),
('ramayana-6-84-30', 30, 'Yuddha Kanda, Sarga 84, Verse 30', 'विवृत्तनयनं क्रोधात्सफेनरुधिराप्लुतम्।
ददृशुस्ते विरूपाक्षं विरूपाक्षतरं कृतम्॥', 'vivṛttanayanaṃ krodhāt saphenarudhirāplutam
dadṛśus te virūpākṣaṃ virūpākṣataraṃ kṛtam', null, 6084030),
('ramayana-6-84-31', 31, 'Yuddha Kanda, Sarga 84, Verse 31', 'स्फुरन्तं परिवर्जन्तं पार्श्वेन रुधिरोक्षितम्।
करुणं च विनर्दान्तं ददृशुः कपयो रिपुम्॥', 'sphurantaṃ parivarjantaṃ pārśvena rudhirokṣitam
karuṇaṃ ca vinardāntaṃ dadṛśuḥ kapayo ripum', null, 6084031),
('ramayana-6-84-32', 32, 'Yuddha Kanda, Sarga 84, Verse 32', 'तथा तु तौ संयति संप्रयुक्तौ तरस्विनौ वानरराक्षसानाम्।
बलार्णवौ सस्वनतुः सभीमं महार्णवौ द्वाविव भिन्नवेलौ॥', 'tathā tu tau saṃyati saṃprayuktau tarasvinau vānararākṣasānām
balārṇavau sasvanatuḥ sabhīmaṃ mahārṇavau dvāv iva bhinnavelau', null, 6084032),
('ramayana-6-84-33', 33, 'Yuddha Kanda, Sarga 84, Verse 33', 'विनाशितं प्रेक्ष्य विरूपनेत्रं महाबलं तं हरिपार्थिवेन।
बलं समस्तं कपिराक्षसानामुन्मत्तगङ्गाप्रतिमं बभूव॥', 'vināśitaṃ prekṣya virūpanetraṃ mahābalaṃ taṃ haripārthivena
balaṃ samastaṃ kapirākṣasānām unmattagaṅgāpratimaṃ babhūva', null, 6084033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 85 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-85-1', 1, 'Yuddha Kanda, Sarga 85, Verse 1', 'हन्यमाने बले तूर्णमन्योन्यं ते महामृधे।
सरसीव महाघर्मे सूपक्षीणे बभूवतुः॥', 'hanyamāne bale tūrṇam anyonyaṃ te mahāmṛdhe
sarasīva mahāgharme sūpakṣīṇe babhūvatuḥ', null, 6085001),
('ramayana-6-85-2', 2, 'Yuddha Kanda, Sarga 85, Verse 2', 'स्वबलस्य विघातेन विरूपाक्षवधेन च।
बभूव द्विगुणं क्रुद्धो रावणो राक्षसाधिपः॥', 'svabalasya vighātena virūpākṣavadhena ca
babhūva dviguṇaṃ kruddho rāvaṇo rākṣasādhipaḥ', null, 6085002),
('ramayana-6-85-3', 3, 'Yuddha Kanda, Sarga 85, Verse 3', 'प्रक्षीणं तु बलं दृष्ट्वा वध्यमानं वलीमुखैः।
बभूवास्य व्यथा युद्धे प्रेक्ष्य दैवविपर्ययम्॥', 'prakṣīṇaṃ tu balaṃ dṛṣṭvā vadhyamānaṃ valīmukhaiḥ
babhūvāsya vyathā yuddhe prekṣya daivaviparyayam', null, 6085003),
('ramayana-6-85-4', 4, 'Yuddha Kanda, Sarga 85, Verse 4', 'उवाच च समीपस्थं महोदरमरिंदमम्।
अस्मिन्काले महाबाहो जयाशा त्वयि मे स्थिता॥', 'uvāca ca samīpasthaṃ mahodaram ariṃdamam
asmin kāle mahābāho jayāśā tvayi me sthitā', null, 6085004),
('ramayana-6-85-5', 5, 'Yuddha Kanda, Sarga 85, Verse 5', 'जहि शत्रुचमूं वीर दर्शयाद्य पराक्रमम्।
भर्तृपिण्डस्य कालोऽयं निर्वेष्टुं साधु युध्यताम्॥', 'jahi śatrucamūṃ vīra darśayādya parākramam
bhartṛpiṇḍasya kālo ''yaṃ nirveṣṭuṃ sādhu yudhyatām', null, 6085005),
('ramayana-6-85-6', 6, 'Yuddha Kanda, Sarga 85, Verse 6', 'एवमुक्तस्तथेत्युक्त्वा राक्षसेन्द्रं महोदरः।
प्रविवेशारिसेनां स पतंग इव पावकम्॥', 'evam uktas tathety uktvā rākṣasendraṃ mahodaraḥ
praviveśārisenāṃ sa pataṃga iva pāvakam', null, 6085006),
('ramayana-6-85-7', 7, 'Yuddha Kanda, Sarga 85, Verse 7', 'ततः स कदनं चक्रे वानराणां महाबलः।
भर्तृवाक्येन तेजस्वी स्वेन वीर्येण चोदितः॥', 'tataḥ sa kadanaṃ cakre vānarāṇāṃ mahābalaḥ
bhartṛvākyena tejasvī svena vīryeṇa coditaḥ', null, 6085007),
('ramayana-6-85-8', 8, 'Yuddha Kanda, Sarga 85, Verse 8', 'प्रभग्नां समरे दृष्ट्वा वानराणां महाचमूम्।
अभिदुद्राव सुग्रीवो महोदरमनन्तरम्॥', 'prabhagnāṃ samare dṛṣṭvā vānarāṇāṃ mahācamūm
abhidudrāva sugrīvo mahodaram anantaram', null, 6085008),
('ramayana-6-85-9', 9, 'Yuddha Kanda, Sarga 85, Verse 9', 'प्रगृह्य विपुलां घोरां महीधरसमां शिलाम्।
चिक्षेप च महातेजास्तद्वधाय हरीश्वरः॥', 'pragṛhya vipulāṃ ghorāṃ mahīdharasamāṃ śilām
cikṣepa ca mahātejās tad vadhāya harīśvaraḥ', null, 6085009),
('ramayana-6-85-10', 10, 'Yuddha Kanda, Sarga 85, Verse 10', 'तामापतन्तीं सहसा शिलां दृष्ट्वा महोदरः।
असंभ्रान्तस्ततो बाणैर्निर्बिभेद दुरासदाम्॥', 'tām āpatantīṃ sahasā śilāṃ dṛṣṭvā mahodaraḥ
asaṃbhrāntas tato bāṇair nirbibheda durāsadām', null, 6085010),
('ramayana-6-85-11', 11, 'Yuddha Kanda, Sarga 85, Verse 11', 'रक्षसा तेन बाणौघैर्निकृत्ता सा सहस्रधा।
निपपात शिला भूमौ गृध्रचक्रमिवाकुलम्॥', 'rakṣasā tena bāṇaughair nikṛttā sā sahasradhā
nipapāta śilā bhūmau gṛdhracakram ivākulam', null, 6085011),
('ramayana-6-85-12', 12, 'Yuddha Kanda, Sarga 85, Verse 12', 'तां तु भिन्नां शिलां दृष्ट्वा सुग्रीवः क्रोधमूर्छितः।
सालमुत्पाट्य चिक्षेप रक्षसे रणमूर्धनि।
शरैश्च विददारैनं शूरः परपुरंजयः॥', 'tāṃ tu bhinnāṃ śilāṃ dṛṣṭvā sugrīvaḥ krodhamūrchitaḥ
sālam utpāṭya cikṣepa rakṣase raṇamūrdhani
śaraiś ca vidadārainaṃ śūraḥ parapuraṃjayaḥ', null, 6085012),
('ramayana-6-85-13', 13, 'Yuddha Kanda, Sarga 85, Verse 13', 'स ददर्श ततः क्रुद्धः परिघं पतितं भुवि।
आविध्य तु स तं दीप्तं परिघं तस्य दर्शयन्।
परिघाग्रेण वेगेन जघानास्य हयोत्तमान्॥', 'sa dadarśa tataḥ kruddhaḥ parighaṃ patitaṃ bhuvi
āvidhya tu sa taṃ dīptaṃ parighaṃ tasya darśayan
parighāgreṇa vegena jaghānāsya hayottamān', null, 6085013),
('ramayana-6-85-14', 14, 'Yuddha Kanda, Sarga 85, Verse 14', 'तस्माद्धतहयाद्वीरः सोऽवप्लुत्य महारथात्।
गदां जग्राह संक्रुद्धो राक्षसोऽथ महोदरः॥', 'tasmād dhatahayād vīraḥ so ''vaplutya mahārathāt
gadāṃ jagrāha saṃkruddho rākṣaso ''tha mahodaraḥ', null, 6085014),
('ramayana-6-85-15', 15, 'Yuddha Kanda, Sarga 85, Verse 15', 'गदापरिघहस्तौ तौ युधि वीरौ समीयतुः।
नर्दन्तौ गोवृषप्रख्यौ घनाविव सविद्युतौ॥', 'gadāparighahastau tau yudhi vīrau samīyatuḥ
nardantau govṛṣaprakhyau ghanāv iva savidyutau', null, 6085015),
('ramayana-6-85-16', 16, 'Yuddha Kanda, Sarga 85, Verse 16', 'आजघान गदां तस्य परिघेण हरीश्वरः।
पपात स गदोद्भिन्नः परिघस्तस्य भूतले॥', 'ājaghāna gadāṃ tasya parigheṇa harīśvaraḥ
papāta sa gadodbhinnaḥ parighas tasya bhūtale', null, 6085016),
('ramayana-6-85-17', 17, 'Yuddha Kanda, Sarga 85, Verse 17', 'ततो जग्राह तेजस्वी सुग्रीवो वसुधातलात्।
आयसं मुसलं घोरं सर्वतो हेमभूषितम्॥', 'tato jagrāha tejasvī sugrīvo vasudhātalāt
āyasaṃ musalaṃ ghoraṃ sarvato hemabhūṣitam', null, 6085017),
('ramayana-6-85-18', 18, 'Yuddha Kanda, Sarga 85, Verse 18', 'तं समुद्यम्य चिक्षेप सोऽप्यन्यां व्याक्षिपद्गदाम्।
भिन्नावन्योन्यमासाद्य पेततुर्धरणीतले॥', 'taṃ samudyamya cikṣepa so ''py anyāṃ vyākṣipad gadām
bhinnāv anyonyam āsādya petatur dharaṇītale', null, 6085018),
('ramayana-6-85-19', 19, 'Yuddha Kanda, Sarga 85, Verse 19', 'ततो भग्नप्रहरणौ मुष्टिभ्यां तौ समीयतुः।
तेजोबलसमाविष्टौ दीप्ताविव हुताशनौ॥', 'tato bhagnapraharaṇau muṣṭibhyāṃ tau samīyatuḥ
tejobalasamāviṣṭau dīptāv iva hutāśanau', null, 6085019),
('ramayana-6-85-20', 20, 'Yuddha Kanda, Sarga 85, Verse 20', 'जघ्नतुस्तौ तदान्योन्यं नेदतुश्च पुनः पुनः।
तलैश्चान्योन्यमाहत्य पेततुर्धरणीतले॥', 'jaghnatus tau tadānyonyaṃ nedatuś ca punaḥ punaḥ
talaiś cānyonyam āhatya petatur dharaṇītale', null, 6085020),
('ramayana-6-85-21', 21, 'Yuddha Kanda, Sarga 85, Verse 21', 'उत्पेततुस्ततस्तूर्णं जघ्नतुश्च परस्परम्।
भुजैश्चिक्षेपतुर्वीरावन्योन्यमपराजितौ॥', 'utpetatus tatas tūrṇaṃ jaghnatuś ca parasparam
bhujaiś cikṣepatur vīrāv anyonyam aparājitau', null, 6085021),
('ramayana-6-85-22', 22, 'Yuddha Kanda, Sarga 85, Verse 22', 'आजहार तदा खड्गमदूरपरिवर्तिनम्।
राक्षसश्चर्मणा सार्धं महावेगो महोदरः॥', 'ājahāra tadā khaḍgam adūraparivartinam
rākṣasaś carmaṇā sārdhaṃ mahāvego mahodaraḥ', null, 6085022),
('ramayana-6-85-23', 23, 'Yuddha Kanda, Sarga 85, Verse 23', 'तथैव च महाखड्गं चर्मणा पतितं सह।
जग्राह वानरश्रेष्ठः सुग्रीवो वेगवत्तरः॥', 'tathaiva ca mahākhaḍgaṃ carmaṇā patitaṃ saha
jagrāha vānaraśreṣṭhaḥ sugrīvo vegavattaraḥ', null, 6085023),
('ramayana-6-85-24', 24, 'Yuddha Kanda, Sarga 85, Verse 24', 'तौ तु रोषपरीताङ्गौ नर्दन्तावभ्यधावताम्।
उद्यतासी रणे हृष्टौ युधि शस्त्रविशारदौ॥', 'tau tu roṣaparītāṅgau nardantāv abhyadhāvatām
udyatāsī raṇe hṛṣṭau yudhi śastraviśāradau', null, 6085024),
('ramayana-6-85-25', 25, 'Yuddha Kanda, Sarga 85, Verse 25', 'दक्षिणं मण्डलं चोभौ तौ तूर्णं संपरीयतुः।
अन्योन्यमभिसंक्रुद्धौ जये प्रणिहितावुभौ॥', 'dakṣiṇaṃ maṇḍalaṃ cobhau tau tūrṇaṃ saṃparīyatuḥ
anyonyam abhisaṃkruddhau jaye praṇihitāv ubhau', null, 6085025),
('ramayana-6-85-26', 26, 'Yuddha Kanda, Sarga 85, Verse 26', 'स तु शूरो महावेगो वीर्यश्लाघी महोदरः।
महाचर्मणि तं खड्गं पातयामास दुर्मतिः॥', 'sa tu śūro mahāvego vīryaślāghī mahodaraḥ
mahācarmaṇi taṃ khaḍgaṃ pātayām āsa durmatiḥ', null, 6085026),
('ramayana-6-85-27', 27, 'Yuddha Kanda, Sarga 85, Verse 27', 'लग्नमुत्कर्षतः खड्गं खड्गेन कपिकुञ्जरः।
जहार सशिरस्त्राणं कुण्डलोपहितं शिरः॥', 'lagnam utkarṣataḥ khaḍgaṃ khaḍgena kapikuñjaraḥ
jahāra saśiras trāṇaṃ kuṇḍalopahitaṃ śiraḥ', null, 6085027),
('ramayana-6-85-28', 28, 'Yuddha Kanda, Sarga 85, Verse 28', 'निकृत्तशिरसस्तस्य पतितस्य महीतले।
तद्बलं राक्षसेन्द्रस्य दृष्ट्वा तत्र न तिष्ठति॥', 'nikṛttaśirasas tasya patitasya mahītale
tad balaṃ rākṣasendrasya dṛṣṭvā tatra na tiṣṭhati', null, 6085028),
('ramayana-6-85-29', 29, 'Yuddha Kanda, Sarga 85, Verse 29', 'हत्वा तं वानरैः सार्धं ननाद मुदितो हरिः।
चुक्रोध च दशग्रीवो बभौ हृष्टश्च राघवः॥', 'hatvā taṃ vānaraiḥ sārdhaṃ nanāda mudito hariḥ
cukrodha ca daśagrīvo babhau hṛṣṭaś ca rāghavaḥ', null, 6085029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 86 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-86-1', 1, 'Yuddha Kanda, Sarga 86, Verse 1', 'महोदरे तु निहते महापार्श्वो महाबलः।
अङ्गदस्य चमूं भीमां क्षोभयामास सायकैः॥', 'mahodare tu nihate mahāpārśvo mahābalaḥ
aṅgadasya camūṃ bhīmāṃ kṣobhayām āsa sāyakaiḥ', null, 6086001),
('ramayana-6-86-2', 2, 'Yuddha Kanda, Sarga 86, Verse 2', 'स वानराणां मुख्यानामुत्तमाङ्गानि सर्वशः।
पातयामास कायेभ्यः फलं वृन्तादिवानिलः॥', 'sa vānarāṇāṃ mukhyānām uttamāṅgāni sarvaśaḥ
pātayām āsa kāyebhyaḥ phalaṃ vṛntād ivānilaḥ', null, 6086002),
('ramayana-6-86-3', 3, 'Yuddha Kanda, Sarga 86, Verse 3', 'केषां चिदिषुभिर्बाहून्स्कन्धांश्चिछेद राक्षसः।
वानराणां सुसंक्रुद्धः पार्श्वं केषां व्यदारयत्॥', 'keṣāṃ cid iṣubhir bāhūn skandhāṃś cicheda rākṣasaḥ
vānarāṇāṃ susaṃkruddhaḥ pārśvaṃ keṣāṃ vyadārayat', null, 6086003),
('ramayana-6-86-4', 4, 'Yuddha Kanda, Sarga 86, Verse 4', 'तेऽर्दिता बाणवर्षेण महापार्श्वेन वानराः।
विषादविमुखाः सर्वे बभूवुर्गतचेतसः॥', 'te ''rditā bāṇavarṣeṇa mahāpārśvena vānarāḥ
viṣādavimukhāḥ sarve babhūvur gatacetasaḥ', null, 6086004),
('ramayana-6-86-5', 5, 'Yuddha Kanda, Sarga 86, Verse 5', 'निरीक्ष्य बलमुद्विग्नमङ्गदो राक्षसार्दितम्।
वेगं चक्रे महाबाहुः समुद्र इव पर्वणि॥', 'nirīkṣya balam udvignam aṅgado rākṣasārditam
vegaṃ cakre mahābāhuḥ samudra iva parvaṇi', null, 6086005),
('ramayana-6-86-6', 6, 'Yuddha Kanda, Sarga 86, Verse 6', 'आयसं परिघं गृह्य सूर्यरश्मिसमप्रभम्।
समरे वानरश्रेष्ठो महापार्श्वे न्यपातयत्॥', 'āyasaṃ parighaṃ gṛhya sūryaraśmisamaprabham
samare vānaraśreṣṭho mahāpārśve nyapātayat', null, 6086006),
('ramayana-6-86-7', 7, 'Yuddha Kanda, Sarga 86, Verse 7', 'स तु तेन प्रहारेण महापार्श्वो विचेतनः।
ससूतः स्यन्दनात्तस्माद्विसंज्ञः प्रापतद्भुवि॥', 'sa tu tena prahāreṇa mahāpārśvo vicetanaḥ
sasūtaḥ syandanāt tasmād visaṃjñaḥ prāpatad bhuvi', null, 6086007),
('ramayana-6-86-8', 8, 'Yuddha Kanda, Sarga 86, Verse 8', 'सर्क्षराजस्तु तेजस्वी नीलाञ्जनचयोपमः।
निष्पत्य सुमहावीर्यः स्वाद्यूथान्मेघसंनिभात्॥', 'sarkṣarājas tu tejasvī nīlāñjanacayopamaḥ
niṣpatya sumahāvīryaḥ svād yūthān meghasaṃnibhāt', null, 6086008),
('ramayana-6-86-9', 9, 'Yuddha Kanda, Sarga 86, Verse 9', 'प्रगृह्य गिरिशृङ्गाभां क्रुद्धः स विपुलां शिलाम्।
अश्वाञ्जघान तरसा स्यन्दनं च बभञ्ज तम्॥', 'pragṛhya giriśṛṅgābhāṃ kruddhaḥ sa vipulāṃ śilām
aśvāñ jaghāna tarasā syandanaṃ ca babhañja tam', null, 6086009),
('ramayana-6-86-10', 10, 'Yuddha Kanda, Sarga 86, Verse 10', 'मुहूर्ताल्लब्धसंज्ञस्तु महापार्श्वो महाबलः।
अङ्गदं बहुभिर्बाणैर्भूयस्तं प्रत्यविध्यत॥', 'muhūrtāl labdhasaṃjñas tu mahāpārśvo mahābalaḥ
aṅgadaṃ bahubhir bāṇair bhūyas taṃ pratyavidhyata', null, 6086010),
('ramayana-6-86-11', 11, 'Yuddha Kanda, Sarga 86, Verse 11', 'जाम्बवन्तं त्रिभिर्बाणैराजघान स्तनान्तरे।
ऋक्षराजं गवाक्षं च जघान बहुभिः शरैः॥', 'jāmbavantaṃ tribhir bāṇair ājaghāna stanāntare
ṛkṣarājaṃ gavākṣaṃ ca jaghāna bahubhiḥ śaraiḥ', null, 6086011),
('ramayana-6-86-12', 12, 'Yuddha Kanda, Sarga 86, Verse 12', 'गवाक्षं जाम्बवन्तं च स दृष्ट्वा शरपीडितौ।
जग्राह परिघं घोरमङ्गदः क्रोधमूर्छितः॥', 'gavākṣaṃ jāmbavantaṃ ca sa dṛṣṭvā śarapīḍitau
jagrāha parighaṃ ghoram aṅgadaḥ krodhamūrchitaḥ', null, 6086012),
('ramayana-6-86-13', 13, 'Yuddha Kanda, Sarga 86, Verse 13', 'तस्याङ्गदः प्रकुपितो राक्षसस्य तमायसं।
दूरस्थितस्य परिघं रविरश्मिसमप्रभम्॥', 'tasyāṅgadaḥ prakupito rākṣasasya tam āyasaṃ
dūrasthitasya parighaṃ raviraśmisamaprabham', null, 6086013),
('ramayana-6-86-14', 14, 'Yuddha Kanda, Sarga 86, Verse 14', 'द्वाभ्यां भुजाभ्यां संगृह्य भ्रामयित्वा च वेगवान्।
महापार्श्वाय चिक्षेप वधार्थं वालिनः सुतः॥', 'dvābhyāṃ bhujābhyāṃ saṃgṛhya bhrāmayitvā ca vegavān
mahāpārśvāya cikṣepa vadhārthaṃ vālinaḥ sutaḥ', null, 6086014),
('ramayana-6-86-15', 15, 'Yuddha Kanda, Sarga 86, Verse 15', 'स तु क्षिप्तो बलवता परिघस्तस्य रक्षसः।
धनुश्च सशरं हस्ताच्छिरस्त्रं चाप्यपातयत्॥', 'sa tu kṣipto balavatā parighas tasya rakṣasaḥ
dhanuś ca saśaraṃ hastāc chirastraṃ cāpy apātayat', null, 6086015),
('ramayana-6-86-16', 16, 'Yuddha Kanda, Sarga 86, Verse 16', 'तं समासाद्य वेगेन वालिपुत्रः प्रतापवान्।
तलेनाभ्यहनत्क्रुद्धः कर्णमूले सकुण्डले॥', 'taṃ samāsādya vegena vāliputraḥ pratāpavān
talenābhyahanat kruddhaḥ karṇamūle sakuṇḍale', null, 6086016),
('ramayana-6-86-17', 17, 'Yuddha Kanda, Sarga 86, Verse 17', 'स तु क्रुद्धो महावेगो महापार्श्वो महाद्युतिः।
करेणैकेन जग्राह सुमहान्तं परश्वधम्॥', 'sa tu kruddho mahāvego mahāpārśvo mahādyutiḥ
kareṇaikena jagrāha sumahāntaṃ paraśvadham', null, 6086017),
('ramayana-6-86-18', 18, 'Yuddha Kanda, Sarga 86, Verse 18', 'तं तैलधौतं विमलं शैलसारमयं दृढम्।
राक्षसः परमक्रुद्धो वालिपुत्रे न्यपातयत्॥', 'taṃ tailadhautaṃ vimalaṃ śailasāramayaṃ dṛḍham
rākṣasaḥ paramakruddho vāliputre nyapātayat', null, 6086018),
('ramayana-6-86-19', 19, 'Yuddha Kanda, Sarga 86, Verse 19', 'तेन वामांसफलके भृशं प्रत्यवपातितम्।
अङ्गदो मोक्षयामास सरोषः स परश्वधम्॥', 'tena vāmāṃsaphalake bhṛśaṃ pratyavapātitam
aṅgado mokṣayām āsa saroṣaḥ sa paraśvadham', null, 6086019),
('ramayana-6-86-20', 20, 'Yuddha Kanda, Sarga 86, Verse 20', 'स वीरो वज्रसंकाशमङ्गदो मुष्टिमात्मनः।
संवर्तयन्सुसंक्रुद्धः पितुस्तुल्यपराक्रमः॥', 'sa vīro vajrasaṃkāśam aṅgado muṣṭim ātmanaḥ
saṃvartayan susaṃkruddhaḥ pitus tulyaparākramaḥ', null, 6086020),
('ramayana-6-86-21', 21, 'Yuddha Kanda, Sarga 86, Verse 21', 'राक्षसस्य स्तनाभ्याशे मर्मज्ञो हृदयं प्रति।
इन्द्राशनिसमस्पर्शं स मुष्टिं विन्यपातयत्॥', 'rākṣasasya stanābhyāśe marmajño hṛdayaṃ prati
indrāśanisamasparśaṃ sa muṣṭiṃ vinyapātayat', null, 6086021),
('ramayana-6-86-22', 22, 'Yuddha Kanda, Sarga 86, Verse 22', 'तेन तस्य निपातेन राक्षसस्य महामृधे।
पफाल हृदयं चाशु स पपात हतो भुवि॥', 'tena tasya nipātena rākṣasasya mahāmṛdhe
paphāla hṛdayaṃ cāśu sa papāta hato bhuvi', null, 6086022),
('ramayana-6-86-23', 23, 'Yuddha Kanda, Sarga 86, Verse 23', 'तस्मिन्निपतिते भूमौ तत्सैन्यं संप्रचुक्षुभे।
अभवच्च महान्क्रोधः समरे रावणस्य तु॥', 'tasmin nipatite bhūmau tat sainyaṃ saṃpracukṣubhe
abhavac ca mahān krodhaḥ samare rāvaṇasya tu', null, 6086023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 87 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-87-1', 1, 'Yuddha Kanda, Sarga 87, Verse 1', 'महोदरमहापार्श्वौ हतौ दृष्ट्वा तु राक्षसौ।
तस्मिंश्च निहते वीरे विरूपाक्षे महाबले॥', 'mahodaramahāpārśvau hatau dṛṣṭvā tu rākṣasau
tasmiṃś ca nihate vīre virūpākṣe mahābale', null, 6087001),
('ramayana-6-87-2', 2, 'Yuddha Kanda, Sarga 87, Verse 2', 'आविवेश महान्क्रोधो रावणं तु महामृधे।
सूतं संचोदयामास वाक्यं चेदमुवाच ह॥', 'āviveśa mahān krodho rāvaṇaṃ tu mahāmṛdhe
sūtaṃ saṃcodayām āsa vākyaṃ cedam uvāca ha', null, 6087002),
('ramayana-6-87-3', 3, 'Yuddha Kanda, Sarga 87, Verse 3', 'निहतानाममात्यानां रुद्धस्य नगरस्य च।
दुःखमेषोऽपनेष्यामि हत्वा तौ रामलक्ष्मणौ॥', 'nihatānām amātyānāṃ ruddhasya nagarasya ca
duḥkham eṣo ''paneṣyāmi hatvā tau rāmalakṣmaṇau', null, 6087003),
('ramayana-6-87-4', 4, 'Yuddha Kanda, Sarga 87, Verse 4', 'रामवृक्षं रणे हन्मि सीतापुष्पफलप्रदम्।
प्रशाखा यस्य सुग्रीवो जाम्बवान्कुमुदो नलः॥', 'rāmavṛkṣaṃ raṇe hanmi sītāpuṣpaphalapradam
praśākhā yasya sugrīvo jāmbavān kumudo nalaḥ', null, 6087004),
('ramayana-6-87-5', 5, 'Yuddha Kanda, Sarga 87, Verse 5', 'स दिशो दश घोषेण रथस्यातिरथो महान्।
नादयन्प्रययौ तूर्णं राघवं चाभ्यवर्तत॥', 'sa diśo daśa ghoṣeṇa rathasyātiratho mahān
nādayan prayayau tūrṇaṃ rāghavaṃ cābhyavartata', null, 6087005),
('ramayana-6-87-6', 6, 'Yuddha Kanda, Sarga 87, Verse 6', 'पूरिता तेन शब्देन सनदीगिरिकानना।
संचचाल मही सर्वा सवराहमृगद्विपा॥', 'pūritā tena śabdena sanadīgirikānanā
saṃcacāla mahī sarvā savarāhamṛgadvipā', null, 6087006),
('ramayana-6-87-7', 7, 'Yuddha Kanda, Sarga 87, Verse 7', 'तामसं सुमहाघोरं चकारास्त्रं सुदारुणम्।
निर्ददाह कपीन्सर्वांस्ते प्रपेतुः समन्ततः॥', 'tāmasaṃ sumahāghoraṃ cakārāstraṃ sudāruṇam
nirdadāha kapīn sarvāṃs te prapetuḥ samantataḥ', null, 6087007),
('ramayana-6-87-8', 8, 'Yuddha Kanda, Sarga 87, Verse 8', 'तान्यनीकान्यनेकानि रावणस्य शरोत्तमैः।
दृष्ट्वा भग्नानि शतशो राघवः पर्यवस्थितः॥', 'tāny anīkāny anekāni rāvaṇasya śarottamaiḥ
dṛṣṭvā bhagnāni śataśo rāghavaḥ paryavasthitaḥ', null, 6087008),
('ramayana-6-87-9', 9, 'Yuddha Kanda, Sarga 87, Verse 9', 'स ददर्श ततो रामं तिष्ठन्तमपराजितम्।
लक्ष्मणेन सह भ्रात्रा विष्णुना वासवं यथा॥', 'sa dadarśa tato rāmaṃ tiṣṭhantam aparājitam
lakṣmaṇena saha bhrātrā viṣṇunā vāsavaṃ yathā', null, 6087009),
('ramayana-6-87-10', 10, 'Yuddha Kanda, Sarga 87, Verse 10', 'आलिखन्तमिवाकाशमवष्टभ्य महद्धनुः।
पद्मपत्रविशालाक्षं दीर्घबाहुमरिंदमम्॥', 'ālikhantam ivākāśam avaṣṭabhya mahad dhanuḥ
padmapatraviśālākṣaṃ dīrghabāhum ariṃdamam', null, 6087010),
('ramayana-6-87-11', 11, 'Yuddha Kanda, Sarga 87, Verse 11', 'वानरांश्च रणे भग्नानापतन्तं च रावणम्।
समीक्ष्य राघवो हृष्टो मध्ये जग्राह कार्मुकम्॥', 'vānarāṃś ca raṇe bhagnān āpatantaṃ ca rāvaṇam
samīkṣya rāghavo hṛṣṭo madhye jagrāha kārmukam', null, 6087011),
('ramayana-6-87-12', 12, 'Yuddha Kanda, Sarga 87, Verse 12', 'विस्फारयितुमारेभे ततः स धनुरुत्तमम्।
महावेगं महानादं निर्भिन्दन्निव मेदिनीम्॥', 'visphārayitum ārebhe tataḥ sa dhanur uttamam
mahāvegaṃ mahānādaṃ nirbhindann iva medinīm', null, 6087012),
('ramayana-6-87-13', 13, 'Yuddha Kanda, Sarga 87, Verse 13', 'तयोः शरपथं प्राप्य रावणो राजपुत्रयोः।
स बभूव यथा राहुः समीपे शशिसूर्ययोः॥', 'tayoḥ śarapathaṃ prāpya rāvaṇo rājaputrayoḥ
sa babhūva yathā rāhuḥ samīpe śaśisūryayoḥ', null, 6087013),
('ramayana-6-87-14', 14, 'Yuddha Kanda, Sarga 87, Verse 14', 'रावणस्य च बाणौघै रामविस्फरितेन च।
शब्देन राक्षसास्तेन पेतुश्च शतशस्तदा॥', 'rāvaṇasya ca bāṇaughai rāmavispharitena ca
śabdena rākṣasās tena petuś ca śataśas tadā', null, 6087014),
('ramayana-6-87-15', 15, 'Yuddha Kanda, Sarga 87, Verse 15', 'तमिच्छन्प्रथमं योद्धुं लक्ष्मणो निशितैः शरैः।
मुमोच धनुरायम्य शरानग्निशिखोपमान्॥', 'tam icchan prathamaṃ yoddhuṃ lakṣmaṇo niśitaiḥ śaraiḥ
mumoca dhanur āyamya śarān agniśikhopamān', null, 6087015),
('ramayana-6-87-16', 16, 'Yuddha Kanda, Sarga 87, Verse 16', 'तान्मुक्तमात्रानाकाशे लक्ष्मणेन धनुष्मता।
बाणान्बाणैर्महातेजा रावणः प्रत्यवारयत्॥', 'tān muktamātrān ākāśe lakṣmaṇena dhanuṣmatā
bāṇān bāṇair mahātejā rāvaṇaḥ pratyavārayat', null, 6087016),
('ramayana-6-87-17', 17, 'Yuddha Kanda, Sarga 87, Verse 17', 'एकमेकेन बाणेन त्रिभिस्त्रीन्दशभिर्दश।
लक्ष्मणस्य प्रचिच्छेद दर्शयन्पाणिलाघवम्॥', 'ekam ekena bāṇena tribhis trīn daśabhir daśa
lakṣmaṇasya praciccheda darśayan pāṇilāghavam', null, 6087017),
('ramayana-6-87-18', 18, 'Yuddha Kanda, Sarga 87, Verse 18', 'अभ्यतिक्रम्य सौमित्रिं रावणः समितिंजयः।
आससाद ततो रामं स्थितं शैलमिवाचलम्॥', 'abhyatikramya saumitriṃ rāvaṇaḥ samitiṃjayaḥ
āsasāda tato rāmaṃ sthitaṃ śailam ivācalam', null, 6087018),
('ramayana-6-87-19', 19, 'Yuddha Kanda, Sarga 87, Verse 19', 'स संख्ये राममासाद्य क्रोधसंरक्तलोचनः।
व्यसृजच्छरवर्षानि रावणो राघवोपरि॥', 'sa saṃkhye rāmam āsādya krodhasaṃraktalocanaḥ
vyasṛjac charavarṣāni rāvaṇo rāghavopari', null, 6087019),
('ramayana-6-87-20', 20, 'Yuddha Kanda, Sarga 87, Verse 20', 'शरधारास्ततो रामो रावणस्य धनुश्च्युताः।
दृष्ट्वैवापतिताः शीघ्रं भल्लाञ्जग्राह सत्वरम्॥', 'śaradhārās tato rāmo rāvaṇasya dhanuścyutāḥ
dṛṣṭvaivāpatitāḥ śīghraṃ bhallāñ jagrāha satvaram', null, 6087020),
('ramayana-6-87-21', 21, 'Yuddha Kanda, Sarga 87, Verse 21', 'ताञ्शरौघांस्ततो भल्लैस्तीक्ष्णैश्चिच्छेद राघवः।
दीप्यमानान्महावेगान्क्रुद्धानाशीविषानिव॥', 'tāñ śaraughāṃs tato bhallais tīkṣṇaiś ciccheda rāghavaḥ
dīpyamānān mahāvegān kruddhān āśīviṣān iva', null, 6087021),
('ramayana-6-87-22', 22, 'Yuddha Kanda, Sarga 87, Verse 22', 'राघवो रावणं तूर्णं रावणो राघवं तथा।
अन्योन्यं विविधैस्तीक्ष्णैः शरैरभिववर्षतुः॥', 'rāghavo rāvaṇaṃ tūrṇaṃ rāvaṇo rāghavaṃ tathā
anyonyaṃ vividhais tīkṣṇaiḥ śarair abhivavarṣatuḥ', null, 6087022),
('ramayana-6-87-23', 23, 'Yuddha Kanda, Sarga 87, Verse 23', 'चेरतुश्च चिरं चित्रं मण्डलं सव्यदक्षिणम्।
बाणवेगान्समुदीक्ष्य समरेष्वपराजितौ॥', 'ceratuś ca ciraṃ citraṃ maṇḍalaṃ savyadakṣiṇam
bāṇavegān samudīkṣya samareṣv aparājitau', null, 6087023),
('ramayana-6-87-24', 24, 'Yuddha Kanda, Sarga 87, Verse 24', 'तयोर्भूतानि वित्रेषुर्युगपत्संप्रयुध्यतोः।
रौद्रयोः सायकमुचोर्यमान्तकनिकाशयोः॥', 'tayor bhūtāni vitreṣur yugapat saṃprayudhyatoḥ
raudrayoḥ sāyakamucor yamāntakanikāśayoḥ', null, 6087024),
('ramayana-6-87-25', 25, 'Yuddha Kanda, Sarga 87, Verse 25', 'संततं विविधैर्बाणैर्बभूव गगनं तदा।
घनैरिवातपापाये विद्युन्मालासमाकुलैः॥', 'saṃtataṃ vividhair bāṇair babhūva gaganaṃ tadā
ghanair ivātapāpāye vidyunmālāsamākulaiḥ', null, 6087025),
('ramayana-6-87-26', 26, 'Yuddha Kanda, Sarga 87, Verse 26', 'गवाक्षितमिवाकाशं बभूव शूरवृष्टिभिः।
महावेगैः सुतीक्ष्णाग्रैर्गृध्रपत्रैः सुवाजितैः॥', 'gavākṣitam ivākāśaṃ babhūva śūravṛṣṭibhiḥ
mahāvegaiḥ sutīkṣṇāgrair gṛdhrapatraiḥ suvājitaiḥ', null, 6087026),
('ramayana-6-87-27', 27, 'Yuddha Kanda, Sarga 87, Verse 27', 'शरान्धकारं तौ भीमं चक्रतुः परमं तदा।
गतेऽस्तं तपने चापि महामेघाविवोत्थितौ॥', 'śarāndhakāraṃ tau bhīmaṃ cakratuḥ paramaṃ tadā
gate ''staṃ tapane cāpi mahāmeghāv ivotthitau', null, 6087027),
('ramayana-6-87-28', 28, 'Yuddha Kanda, Sarga 87, Verse 28', 'बभूव तुमुलं युद्धमन्योन्यवधकाङ्क्षिणोः।
अनासाद्यमचिन्त्यं च वृत्रवासवयोरिव॥', 'babhūva tumulaṃ yuddham anyonyavadhakāṅkṣiṇoḥ
anāsādyam acintyaṃ ca vṛtravāsavayor iva', null, 6087028),
('ramayana-6-87-29', 29, 'Yuddha Kanda, Sarga 87, Verse 29', 'उभौ हि परमेष्वासावुभौ शस्त्रविशारदौ।
उभौ चास्त्रविदां मुख्यावुभौ युद्धे विचेरतुः॥', 'ubhau hi parameṣvāsāv ubhau śastraviśāradau
ubhau cāstravidāṃ mukhyāv ubhau yuddhe viceratuḥ', null, 6087029),
('ramayana-6-87-30', 30, 'Yuddha Kanda, Sarga 87, Verse 30', 'उभौ हि येन व्रजतस्तेन तेन शरोर्मयः।
ऊर्मयो वायुना विद्धा जग्मुः सागरयोरिव॥', 'ubhau hi yena vrajatas tena tena śarormayaḥ
ūrmayo vāyunā viddhā jagmuḥ sāgarayor iva', null, 6087030),
('ramayana-6-87-31', 31, 'Yuddha Kanda, Sarga 87, Verse 31', 'ततः संसक्तहस्तस्तु रावणो लोकरावणः।
नाराचमालां रामस्य ललाटे प्रत्यमुञ्चत॥', 'tataḥ saṃsaktahastas tu rāvaṇo lokarāvaṇaḥ
nārācamālāṃ rāmasya lalāṭe pratyamuñcata', null, 6087031),
('ramayana-6-87-32', 32, 'Yuddha Kanda, Sarga 87, Verse 32', 'रौद्रचापप्रयुक्तां तां नीलोत्पलदलप्रभाम्।
शिरसा धारयन्रामो न व्यथां प्रत्यपद्यत॥', 'raudracāpaprayuktāṃ tāṃ nīlotpaladalaprabhām
śirasā dhārayan rāmo na vyathāṃ pratyapadyata', null, 6087032),
('ramayana-6-87-33', 33, 'Yuddha Kanda, Sarga 87, Verse 33', 'अथ मन्त्रानपि जपन्रौद्रमस्त्रमुदीरयन्।
शरान्भूयः समादाय रामः क्रोधसमन्वितः॥', 'atha mantrān api japan raudram astram udīrayan
śarān bhūyaḥ samādāya rāmaḥ krodhasamanvitaḥ', null, 6087033),
('ramayana-6-87-34', 34, 'Yuddha Kanda, Sarga 87, Verse 34', 'मुमोच च महातेजाश्चापमायम्य वीर्यवान्।
ताञ्शरान्राक्षसेन्द्राय चिक्षेपाच्छिन्नसायकः॥', 'mumoca ca mahātejāś cāpam āyamya vīryavān
tāñ śarān rākṣasendrāya cikṣepācchinnasāyakaḥ', null, 6087034),
('ramayana-6-87-35', 35, 'Yuddha Kanda, Sarga 87, Verse 35', 'ते महामेघसंकाशे कवचे पतिताः शराः।
अवध्ये राक्षसेन्द्रस्य न व्यथां जनयंस्तदा॥', 'te mahāmeghasaṃkāśe kavace patitāḥ śarāḥ
avadhye rākṣasendrasya na vyathāṃ janayaṃs tadā', null, 6087035),
('ramayana-6-87-36', 36, 'Yuddha Kanda, Sarga 87, Verse 36', 'पुनरेवाथ तं रामो रथस्थं राक्षसाधिपम्।
ललाटे परमास्त्रेण सर्वास्त्रकुशलोऽभिनत्॥', 'punar evātha taṃ rāmo rathasthaṃ rākṣasādhipam
lalāṭe paramāstreṇa sarvāstrakuśalo ''bhinat', null, 6087036),
('ramayana-6-87-37', 37, 'Yuddha Kanda, Sarga 87, Verse 37', 'ते भित्त्वा बाणरूपाणि पञ्चशीर्षा इवोरगाः।
श्वसन्तो विविशुर्भूमिं रावणप्रतिकूलताः॥', 'te bhittvā bāṇarūpāṇi pañcaśīrṣā ivoragāḥ
śvasanto viviśur bhūmiṃ rāvaṇapratikūlatāḥ', null, 6087037),
('ramayana-6-87-38', 38, 'Yuddha Kanda, Sarga 87, Verse 38', 'निहत्य राघवस्यास्त्रं रावणः क्रोधमूर्छितः।
आसुरं सुमहाघोरमन्यदस्त्रं समाददे॥', 'nihatya rāghavasyāstraṃ rāvaṇaḥ krodhamūrchitaḥ
āsuraṃ sumahāghoram anyad astraṃ samādade', null, 6087038),
('ramayana-6-87-39', 39, 'Yuddha Kanda, Sarga 87, Verse 39', 'सिंहव्याघ्रमुखांश्चान्यान्कङ्ककाकमुखानपि।
गृध्रश्येनमुखांश्चापि सृगालवदनांस्तथा॥', 'siṃhavyāghramukhāṃś cānyān kaṅkakākamukhān api
gṛdhraśyenamukhāṃś cāpi sṛgālavadanāṃs tathā', null, 6087039),
('ramayana-6-87-40', 40, 'Yuddha Kanda, Sarga 87, Verse 40', 'ईहामृगमुखांश्चान्यान्व्यादितास्यान्भयावहान्।
पञ्चास्यांल्लेलिहानांश्च ससर्ज निशिताञ्शरान्॥', 'īhāmṛgamukhāṃś cānyān vyāditāsyān bhayāvahān
pañcāsyāṃl lelihānāṃś ca sasarja niśitāñ śarān', null, 6087040),
('ramayana-6-87-41', 41, 'Yuddha Kanda, Sarga 87, Verse 41', 'शरान्खरमुखांश्चान्यान्वराहमुखसंस्थितान्।
श्वानकुक्कुटवक्त्रांश्च मकराशीविषाननान्॥', 'śarān kharamukhāṃś cānyān varāhamukhasaṃsthitān
śvānakukkuṭavaktrāṃś ca makarāśīviṣānanān', null, 6087041),
('ramayana-6-87-42', 42, 'Yuddha Kanda, Sarga 87, Verse 42', 'एतांश्चान्यांश्च मायाभिः ससर्ज निशिताञ्शरान्।
रामं प्रति महातेजाः क्रुद्धः सर्प इव श्वसन्॥', 'etāṃś cānyāṃś ca māyābhiḥ sasarja niśitāñ śarān
rāmaṃ prati mahātejāḥ kruddhaḥ sarpa iva śvasan', null, 6087042),
('ramayana-6-87-43', 43, 'Yuddha Kanda, Sarga 87, Verse 43', 'आसुरेण समाविष्टः सोऽस्त्रेण रघुनन्दनः।
ससर्जास्त्रं महोत्साहः पावकं पावकोपमः॥', 'āsureṇa samāviṣṭaḥ so ''streṇa raghunandanaḥ
sasarjāstraṃ mahotsāhaḥ pāvakaṃ pāvakopamaḥ', null, 6087043),
('ramayana-6-87-44', 44, 'Yuddha Kanda, Sarga 87, Verse 44', 'अग्निदीप्तमुखान्बाणांस्तथा सूर्यमुखानपि।
चन्द्रार्धचन्द्रवक्त्रांश्च धूमकेतुमुखानपि॥', 'agnidīptamukhān bāṇāṃs tathā sūryamukhān api
candrārdhacandravaktrāṃś ca dhūmaketumukhān api', null, 6087044),
('ramayana-6-87-45', 45, 'Yuddha Kanda, Sarga 87, Verse 45', 'ग्रहनक्षत्रवर्णांश्च महोल्कामुखसंस्थितान्।
विद्युज्जिह्वोपमांश्चान्यान्ससर्ज निशिताञ्शरान्॥', 'grahanakṣatravarṇāṃś ca maholkāmukhasaṃsthitān
vidyujjihvopamāṃś cānyān sasarja niśitāñ śarān', null, 6087045),
('ramayana-6-87-46', 46, 'Yuddha Kanda, Sarga 87, Verse 46', 'ते रावणशरा घोरा राघवास्त्रसमाहताः।
विलयं जग्मुराकाशे जग्मुश्चैव सहस्रशः॥', 'te rāvaṇaśarā ghorā rāghavāstrasamāhatāḥ
vilayaṃ jagmur ākāśe jagmuś caiva sahasraśaḥ', null, 6087046),
('ramayana-6-87-47', 47, 'Yuddha Kanda, Sarga 87, Verse 47', 'तदस्त्रं निहतं दृष्ट्वा रामेणाक्लिष्टकर्मणा।
हृष्टा नेदुस्ततः सर्वे कपयः कामरूपिणः॥', 'tad astraṃ nihataṃ dṛṣṭvā rāmeṇākliṣṭakarmaṇā
hṛṣṭā nedus tataḥ sarve kapayaḥ kāmarūpiṇaḥ', null, 6087047)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 88 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-88-1', 1, 'Yuddha Kanda, Sarga 88, Verse 1', 'तस्मिन्प्रतिहतेऽस्त्रे तु रावणो राक्षसाधिपः।
क्रोधं च द्विगुणं चक्रे क्रोधाच्चास्त्रमनन्तरम्॥', 'tasmin pratihate ''stre tu rāvaṇo rākṣasādhipaḥ
krodhaṃ ca dviguṇaṃ cakre krodhāc cāstram anantaram', null, 6088001),
('ramayana-6-88-2', 2, 'Yuddha Kanda, Sarga 88, Verse 2', 'मयेन विहितं रौद्रमन्यदस्त्रं महाद्युतिः।
उत्स्रष्टुं रावणो घोरं राघवाय प्रचक्रमे॥', 'mayena vihitaṃ raudram anyad astraṃ mahādyutiḥ
utsraṣṭuṃ rāvaṇo ghoraṃ rāghavāya pracakrame', null, 6088002),
('ramayana-6-88-3', 3, 'Yuddha Kanda, Sarga 88, Verse 3', 'ततः शूलानि निश्चेरुर्गदाश्च मुसलानि च।
कार्मुकाद्दीप्यमानानि वज्रसाराणि सर्वशः॥', 'tataḥ śūlāni niścerur gadāś ca musalāni ca
kārmukād dīpyamānāni vajrasārāṇi sarvaśaḥ', null, 6088003),
('ramayana-6-88-4', 4, 'Yuddha Kanda, Sarga 88, Verse 4', 'कूटमुद्गरपाशाश्च दीप्ताश्चाशनयस्तथा।
निष्पेतुर्विविधास्तीक्ष्णा वाता इव युगक्षये॥', 'kūṭamudgarapāśāś ca dīptāś cāśanayas tathā
niṣpetur vividhās tīkṣṇā vātā iva yugakṣaye', null, 6088004),
('ramayana-6-88-5', 5, 'Yuddha Kanda, Sarga 88, Verse 5', 'तदस्त्रं राघवः श्रीमानुत्तमास्त्रविदां वरः।
जघान परमास्त्रेण गन्धर्वेण महाद्युतिः॥', 'tad astraṃ rāghavaḥ śrīmān uttamāstravidāṃ varaḥ
jaghāna paramāstreṇa gandharveṇa mahādyutiḥ', null, 6088005),
('ramayana-6-88-6', 6, 'Yuddha Kanda, Sarga 88, Verse 6', 'तस्मिन्प्रतिहतेऽस्त्रे तु राघवेण महात्मना।
रावणः क्रोधताम्राक्षः सौरमस्त्रमुदीरयत्॥', 'tasmin pratihate ''stre tu rāghaveṇa mahātmanā
rāvaṇaḥ krodhatāmrākṣaḥ sauram astram udīrayat', null, 6088006),
('ramayana-6-88-7', 7, 'Yuddha Kanda, Sarga 88, Verse 7', 'ततश्चक्राणि निष्पेतुर्भास्वराणि महान्ति च।
कार्मुकाद्भीमवेगस्य दशग्रीवस्य धीमतः॥', 'tataś cakrāṇi niṣpetur bhāsvarāṇi mahānti ca
kārmukād bhīmavegasya daśagrīvasya dhīmataḥ', null, 6088007),
('ramayana-6-88-8', 8, 'Yuddha Kanda, Sarga 88, Verse 8', 'तैरासीद्गगनं दीप्तं संपतद्भिरितस्ततः।
पतद्भिश्च दिशो दीप्तैश्चन्द्रसूर्यग्रहैरिव॥', 'tair āsīd gaganaṃ dīptaṃ saṃpatadbhir itas tataḥ
patadbhiś ca diśo dīptaiś candrasūryagrahair iva', null, 6088008),
('ramayana-6-88-9', 9, 'Yuddha Kanda, Sarga 88, Verse 9', 'तानि चिच्छेद बाणौघैश्चक्राणि तु स राघवः।
आयुधानि विचित्राणि रावणस्य चमूमुखे॥', 'tāni ciccheda bāṇaughaiś cakrāṇi tu sa rāghavaḥ
āyudhāni vicitrāṇi rāvaṇasya camūmukhe', null, 6088009),
('ramayana-6-88-10', 10, 'Yuddha Kanda, Sarga 88, Verse 10', 'तदस्त्रं तु हतं दृष्ट्वा रावणो राक्षसाधिपः।
विव्याध दशभिर्बाणै रामं सर्वेषु मर्मसु॥', 'tad astraṃ tu hataṃ dṛṣṭvā rāvaṇo rākṣasādhipaḥ
vivyādha daśabhir bāṇai rāmaṃ sarveṣu marmasu', null, 6088010),
('ramayana-6-88-11', 11, 'Yuddha Kanda, Sarga 88, Verse 11', 'स विद्धो दशभिर्बाणैर्महाकार्मुकनिःसृतैः।
रावणेन महातेजा न प्राकम्पत राघवः॥', 'sa viddho daśabhir bāṇair mahākārmukaniḥsṛtaiḥ
rāvaṇena mahātejā na prākampata rāghavaḥ', null, 6088011),
('ramayana-6-88-12', 12, 'Yuddha Kanda, Sarga 88, Verse 12', 'ततो विव्याध गात्रेषु सर्वेषु समितिंजयः।
राघवस्तु सुसंक्रुद्धो रावणं बहुभिः शरैः॥', 'tato vivyādha gātreṣu sarveṣu samitiṃjayaḥ
rāghavas tu susaṃkruddho rāvaṇaṃ bahubhiḥ śaraiḥ', null, 6088012),
('ramayana-6-88-13', 13, 'Yuddha Kanda, Sarga 88, Verse 13', 'एतस्मिन्नन्तरे क्रुद्धो राघवस्यानुजो बली।
लक्ष्मणः सायकान्सप्त जग्राह परवीरहा॥', 'etasminn antare kruddho rāghavasyānujo balī
lakṣmaṇaḥ sāyakān sapta jagrāha paravīrahā', null, 6088013),
('ramayana-6-88-14', 14, 'Yuddha Kanda, Sarga 88, Verse 14', 'तैः सायकैर्महावेगै रावणस्य महाद्युतिः।
ध्वजं मनुष्यशीर्षं तु तस्य चिच्छेद नैकधा॥', 'taiḥ sāyakair mahāvegai rāvaṇasya mahādyutiḥ
dhvajaṃ manuṣyaśīrṣaṃ tu tasya ciccheda naikadhā', null, 6088014),
('ramayana-6-88-15', 15, 'Yuddha Kanda, Sarga 88, Verse 15', 'सारथेश्चापि बाणेन शिरो ज्वलितकुण्डलम्।
जहार लक्ष्मणः श्रीमान्नैरृतस्य महाबलः॥', 'sāratheś cāpi bāṇena śiro jvalitakuṇḍalam
jahāra lakṣmaṇaḥ śrīmān nairṛtasya mahābalaḥ', null, 6088015),
('ramayana-6-88-16', 16, 'Yuddha Kanda, Sarga 88, Verse 16', 'तस्य बाणैश्च चिच्छेद धनुर्गजकरोपमम्।
लक्ष्मणो राक्षसेन्द्रस्य पञ्चभिर्निशितैः शरैः॥', 'tasya bāṇaiś ca ciccheda dhanur gajakaropamam
lakṣmaṇo rākṣasendrasya pañcabhir niśitaiḥ śaraiḥ', null, 6088016),
('ramayana-6-88-17', 17, 'Yuddha Kanda, Sarga 88, Verse 17', 'नीलमेघनिभांश्चास्य सदश्वान्पर्वतोपमान्।
जघानाप्लुत्य गदया रावणस्य विभीषणः॥', 'nīlameghanibhāṃś cāsya sadaśvān parvatopamān
jaghānāplutya gadayā rāvaṇasya vibhīṣaṇaḥ', null, 6088017),
('ramayana-6-88-18', 18, 'Yuddha Kanda, Sarga 88, Verse 18', 'हताश्वाद्वेगवान्वेगादवप्लुत्य महारथात्।
क्रोधमाहारयत्तीव्रं भ्रातरं प्रति रावणः॥', 'hatāśvād vegavān vegād avaplutya mahārathāt
krodham āhārayat tīvraṃ bhrātaraṃ prati rāvaṇaḥ', null, 6088018),
('ramayana-6-88-19', 19, 'Yuddha Kanda, Sarga 88, Verse 19', 'ततः शक्तिं महाशक्तिर्दीप्तां दीप्ताशनीमिव।
विभीषणाय चिक्षेप राक्षसेन्द्रः प्रतापवान्॥', 'tataḥ śaktiṃ mahāśaktir dīptāṃ dīptāśanīm iva
vibhīṣaṇāya cikṣepa rākṣasendraḥ pratāpavān', null, 6088019),
('ramayana-6-88-20', 20, 'Yuddha Kanda, Sarga 88, Verse 20', 'अप्राप्तामेव तां बाणैस्त्रिभिश्चिच्छेद लक्ष्मणः।
अथोदतिष्ठत्संनादो वानराणां तदा रणे॥', 'aprāptām eva tāṃ bāṇais tribhiś ciccheda lakṣmaṇaḥ
athodatiṣṭhat saṃnādo vānarāṇāṃ tadā raṇe', null, 6088020),
('ramayana-6-88-21', 21, 'Yuddha Kanda, Sarga 88, Verse 21', 'सा पपात त्रिधा छिन्ना शक्तिः काञ्चनमालिनी।
सविस्फुलिङ्गा ज्वलिता महोल्केव दिवश्च्युता॥', 'sā papāta tridhā chinnā śaktiḥ kāñcanamālinī
savisphuliṅgā jvalitā maholkeva divaś cyutā', null, 6088021),
('ramayana-6-88-22', 22, 'Yuddha Kanda, Sarga 88, Verse 22', 'ततः संभाविततरां कालेनापि दुरासदाम्।
जग्राह विपुलां शक्तिं दीप्यमानां स्वतेजसा॥', 'tataḥ saṃbhāvitatarāṃ kālenāpi durāsadām
jagrāha vipulāṃ śaktiṃ dīpyamānāṃ svatejasā', null, 6088022),
('ramayana-6-88-23', 23, 'Yuddha Kanda, Sarga 88, Verse 23', 'सा वेगिना बलवता रावणेन दुरात्मना।
जज्वाल सुमहाघोरा शक्राशनिसमप्रभा॥', 'sā veginā balavatā rāvaṇena durātmanā
jajvāla sumahāghorā śakrāśanisamaprabhā', null, 6088023),
('ramayana-6-88-24', 24, 'Yuddha Kanda, Sarga 88, Verse 24', 'एतस्मिन्नन्तरे वीरो लक्ष्मणस्तं विभीषणम्।
प्राणसंशयमापन्नं तूर्णमेवाभ्यपद्यत॥', 'etasminn antare vīro lakṣmaṇas taṃ vibhīṣaṇam
prāṇasaṃśayam āpannaṃ tūrṇam evābhyapadyata', null, 6088024),
('ramayana-6-88-25', 25, 'Yuddha Kanda, Sarga 88, Verse 25', 'तं विमोक्षयितुं वीरश्चापमायम्य लक्ष्मणः।
रावणं शक्तिहस्तं तं शरवर्षैरवाकिरत्॥', 'taṃ vimokṣayituṃ vīraś cāpam āyamya lakṣmaṇaḥ
rāvaṇaṃ śaktihastaṃ taṃ śaravarṣair avākirat', null, 6088025),
('ramayana-6-88-26', 26, 'Yuddha Kanda, Sarga 88, Verse 26', 'कीर्यमाणः शरौघेण विसृष्टेन महात्मना।
न प्रहर्तुं मनश्चक्रे विमुखीकृतविक्रमः॥', 'kīryamāṇaḥ śaraugheṇa visṛṣṭena mahātmanā
na prahartuṃ manaś cakre vimukhīkṛtavikramaḥ', null, 6088026),
('ramayana-6-88-27', 27, 'Yuddha Kanda, Sarga 88, Verse 27', 'मोक्षितं भ्रातरं दृष्ट्वा लक्ष्मणेन स रावणः।
लक्ष्मणाभिमुखस्तिष्ठन्निदं वचनमब्रवीत्॥', 'mokṣitaṃ bhrātaraṃ dṛṣṭvā lakṣmaṇena sa rāvaṇaḥ
lakṣmaṇābhimukhas tiṣṭhann idaṃ vacanam abravīt', null, 6088027),
('ramayana-6-88-28', 28, 'Yuddha Kanda, Sarga 88, Verse 28', 'मोक्षितस्ते बलश्लाघिन्यस्मादेवं विभीषणः।
विमुच्य राक्षसं शक्तिस्त्वयीयं विनिपात्यते॥', 'mokṣitas te balaślāghin yasmād evaṃ vibhīṣaṇaḥ
vimucya rākṣasaṃ śaktis tvayīyaṃ vinipātyate', null, 6088028),
('ramayana-6-88-29', 29, 'Yuddha Kanda, Sarga 88, Verse 29', 'एषा ते हृदयं भित्त्वा शक्तिर्लोहितलक्षणा।
मद्बाहुपरिघोत्सृष्टा प्राणानादाय यास्यति॥', 'eṣā te hṛdayaṃ bhittvā śaktir lohitalakṣaṇā
madbāhuparighotsṛṣṭā prāṇān ādāya yāsyati', null, 6088029),
('ramayana-6-88-30', 30, 'Yuddha Kanda, Sarga 88, Verse 30', 'इत्येवमुक्त्वा तां शक्तिमष्टघण्टां महास्वनाम्।
मयेन मायाविहिताममोघां शत्रुघातिनीम्॥', 'ity evam uktvā tāṃ śaktim aṣṭaghaṇṭāṃ mahāsvanām
mayena māyāvihitām amoghāṃ śatrughātinīm', null, 6088030),
('ramayana-6-88-31', 31, 'Yuddha Kanda, Sarga 88, Verse 31', 'लक्ष्मणाय समुद्दिश्य ज्वलन्तीमिव तेजसा।
रावणः परमक्रुद्धश्चिक्षेप च ननाद च॥', 'lakṣmaṇāya samuddiśya jvalantīm iva tejasā
rāvaṇaḥ paramakruddhaś cikṣepa ca nanāda ca', null, 6088031),
('ramayana-6-88-32', 32, 'Yuddha Kanda, Sarga 88, Verse 32', 'सा क्षिप्ता भीमवेगेन शक्राशनिसमस्वना।
शक्तिरभ्यपतद्वेगाल्लक्ष्मणं रणमूर्धनि॥', 'sā kṣiptā bhīmavegena śakrāśanisamasvanā
śaktir abhyapatad vegāl lakṣmaṇaṃ raṇamūrdhani', null, 6088032),
('ramayana-6-88-33', 33, 'Yuddha Kanda, Sarga 88, Verse 33', 'तामनुव्याहरच्छक्तिमापतन्तीं स राघवः।
स्वस्त्यस्तु लक्ष्मणायेति मोघा भव हतोद्यमा॥', 'tām anuvyāharac chaktim āpatantīṃ sa rāghavaḥ
svastyas tu lakṣmaṇāyeti moghā bhava hatodyamā', null, 6088033),
('ramayana-6-88-34', 34, 'Yuddha Kanda, Sarga 88, Verse 34', 'न्यपतत्सा महावेगा लक्ष्मणस्य महोरसि।
जिह्वेवोरगराजस्य दीप्यमाना महाद्युतिः॥', 'nyapatat sā mahāvegā lakṣmaṇasya mahorasi
jihvevoragarājasya dīpyamānā mahādyutiḥ', null, 6088034),
('ramayana-6-88-35', 35, 'Yuddha Kanda, Sarga 88, Verse 35', 'ततो रावणवेगेन सुदूरमवगाढया।
शक्त्या निर्भिन्नहृदयः पपात भुवि लक्ष्मणः॥', 'tato rāvaṇavegena sudūram avagāḍhayā
śaktyā nirbhinnahṛdayaḥ papāta bhuvi lakṣmaṇaḥ', null, 6088035),
('ramayana-6-88-36', 36, 'Yuddha Kanda, Sarga 88, Verse 36', 'तदवस्थं समीपस्थो लक्ष्मणं प्रेक्ष्य राघवः।
भ्रातृस्नेहान्महातेजा विषण्णहृदयोऽभवत्॥', 'tadavasthaṃ samīpastho lakṣmaṇaṃ prekṣya rāghavaḥ
bhrātṛsnehān mahātejā viṣaṇṇahṛdayo ''bhavat', null, 6088036),
('ramayana-6-88-37', 37, 'Yuddha Kanda, Sarga 88, Verse 37', 'स मुहूर्तमनुध्याय बाष्पव्याकुललोचनः।
बभूव संरब्धतरो युगान्त इव पावकः॥', 'sa muhūrtam anudhyāya bāṣpavyākulalocanaḥ
babhūva saṃrabdhataro yugānta iva pāvakaḥ', null, 6088037),
('ramayana-6-88-38', 38, 'Yuddha Kanda, Sarga 88, Verse 38', 'न विषादस्य कालोऽयमिति संचिन्त्य राघवः।
चक्रे सुतुमुलं युद्धं रावणस्य वधे धृतः॥', 'na viṣādasya kālo ''yam iti saṃcintya rāghavaḥ
cakre sutumulaṃ yuddhaṃ rāvaṇasya vadhe dhṛtaḥ', null, 6088038),
('ramayana-6-88-39', 39, 'Yuddha Kanda, Sarga 88, Verse 39', 'स ददर्श ततो रामः शक्त्या भिन्नं महाहवे।
लक्ष्मणं रुधिरादिग्धं सपन्नगमिवाचलम्॥', 'sa dadarśa tato rāmaḥ śaktyā bhinnaṃ mahāhave
lakṣmaṇaṃ rudhirādigdhaṃ sapannagam ivācalam', null, 6088039),
('ramayana-6-88-40', 40, 'Yuddha Kanda, Sarga 88, Verse 40', 'तामपि प्रहितां शक्तिं रावणेन बलीयसा।
यत्नतस्ते हरिश्रेष्ठा न शेकुरवमर्दितुम्।
अर्दिताश्चैव बाणौघैः क्षिप्रहस्तेन रक्षसा॥', 'tām api prahitāṃ śaktiṃ rāvaṇena balīyasā
yatnatas te hariśreṣṭhā na śekur avamarditum
arditāś caiva bāṇaughaiḥ kṣiprahastena rakṣasā', null, 6088040),
('ramayana-6-88-41', 41, 'Yuddha Kanda, Sarga 88, Verse 41', 'सौमित्रिं सा विनिर्भिद्य प्रविष्टा धरणीतलम्।
तां कराभ्यां परामृश्य रामः शक्तिं भयावहाम्।
बभञ्ज समरे क्रुद्धो बलवद्विचकर्ष च॥', 'saumitriṃ sā vinirbhidya praviṣṭā dharaṇītalam
tāṃ karābhyāṃ parāmṛśya rāmaḥ śaktiṃ bhayāvahām
babhañja samare kruddho balavad vicakarṣa ca', null, 6088041),
('ramayana-6-88-42', 42, 'Yuddha Kanda, Sarga 88, Verse 42', 'तस्य निष्कर्षतः शक्तिं रावणेन बलीयसा।
शराः सर्वेषु गात्रेषु पातिता मर्मभेदिनः॥', 'tasya niṣkarṣataḥ śaktiṃ rāvaṇena balīyasā
śarāḥ sarveṣu gātreṣu pātitā marmabhedinaḥ', null, 6088042),
('ramayana-6-88-43', 43, 'Yuddha Kanda, Sarga 88, Verse 43', 'अचिन्तयित्वा तान्बाणान्समाश्लिष्य च लक्ष्मणम्।
अब्रवीच्च हनूमन्तं सुग्रीवं चैव राघवः।
लक्ष्मणं परिवार्येह तिष्ठध्वं वानरोत्तमाः॥', 'acintayitvā tān bāṇān samāśliṣya ca lakṣmaṇam
abravīc ca hanūmantaṃ sugrīvaṃ caiva rāghavaḥ
lakṣmaṇaṃ parivāryeha tiṣṭhadhvaṃ vānarottamāḥ', null, 6088043),
('ramayana-6-88-44', 44, 'Yuddha Kanda, Sarga 88, Verse 44', 'पराक्रमस्य कालोऽयं संप्राप्तो मे चिरेप्सितः।
पापात्मायं दशग्रीवो वध्यतां पापनिश्चयः।
काङ्क्षितः स्तोककस्येव घर्मान्ते मेघदर्शनम्॥', 'parākramasya kālo ''yaṃ saṃprāpto me cirepsitaḥ
pāpātmāyaṃ daśagrīvo vadhyatāṃ pāpaniścayaḥ
kāṅkṣitaḥ stokakasyeva gharmānte meghadarśanam', null, 6088044),
('ramayana-6-88-45', 45, 'Yuddha Kanda, Sarga 88, Verse 45', 'अस्मिन्मुहूर्ते नचिरात्सत्यं प्रतिशृणोमि वः।
अरावणमरामं वा जगद्द्रक्ष्यथ वानराः॥', 'asmin muhūrte nacirāt satyaṃ pratiśṛṇomi vaḥ
arāvaṇam arāmaṃ vā jagad drakṣyatha vānarāḥ', null, 6088045),
('ramayana-6-88-46', 46, 'Yuddha Kanda, Sarga 88, Verse 46', 'राज्यनाशं वने वासं दण्डके परिधावनम्।
वैदेह्याश्च परामर्शं रक्षोभिश्च समागमम्॥', 'rājyanāśaṃ vane vāsaṃ daṇḍake paridhāvanam
vaidehyāś ca parāmarśaṃ rakṣobhiś ca samāgamam', null, 6088046),
('ramayana-6-88-47', 47, 'Yuddha Kanda, Sarga 88, Verse 47', 'प्राप्तं दुःखं महद्घोरं क्लेशं च निरयोपमम्।
अद्य सर्वमहं त्यक्ष्ये हत्वा तं रावणं रणे॥', 'prāptaṃ duḥkhaṃ mahad ghoraṃ kleśaṃ ca nirayopamam
adya sarvam ahaṃ tyakṣye hatvā taṃ rāvaṇaṃ raṇe', null, 6088047),
('ramayana-6-88-48', 48, 'Yuddha Kanda, Sarga 88, Verse 48', 'यदर्थं वानरं सैन्यं समानीतमिदं मया।
सुग्रीवश्च कृतो राज्ये निहत्वा वालिनं रणे॥', 'yadarthaṃ vānaraṃ sainyaṃ samānītam idaṃ mayā
sugrīvaś ca kṛto rājye nihatvā vālinaṃ raṇe', null, 6088048),
('ramayana-6-88-49', 49, 'Yuddha Kanda, Sarga 88, Verse 49', 'यदर्थं सागरः क्रान्तः सेतुर्बद्धश्च सागरे।
सोऽयमद्य रणे पापश्चक्षुर्विषयमागतः॥', 'yadarthaṃ sāgaraḥ krāntaḥ setur baddhaś ca sāgare
so ''yam adya raṇe pāpaś cakṣurviṣayam āgataḥ', null, 6088049),
('ramayana-6-88-50', 50, 'Yuddha Kanda, Sarga 88, Verse 50', 'चक्षुर्विषयमागम्य नायं जीवितुमर्हति।
दृष्टिं दृष्टिविषस्येव सर्पस्य मम रावणः॥', 'cakṣurviṣayam āgamya nāyaṃ jīvitum arhati
dṛṣṭiṃ dṛṣṭiviṣasyeva sarpasya mama rāvaṇaḥ', null, 6088050),
('ramayana-6-88-51', 51, 'Yuddha Kanda, Sarga 88, Verse 51', 'स्वस्थाः पश्यत दुर्धर्षा युद्धं वानरपुंगवाः।
आसीनाः पर्वताग्रेषु ममेदं रावणस्य च॥', 'svasthāḥ paśyata durdharṣā yuddhaṃ vānarapuṃgavāḥ
āsīnāḥ parvatāgreṣu mamedaṃ rāvaṇasya ca', null, 6088051),
('ramayana-6-88-52', 52, 'Yuddha Kanda, Sarga 88, Verse 52', 'अद्य रामस्य रामत्वं पश्यन्तु मम संयुगे।
त्रयो लोकाः सगन्धर्वाः सदेवाः सर्षिचारणाः॥', 'adya rāmasya rāmatvaṃ paśyantu mama saṃyuge
trayo lokāḥ sagandharvāḥ sadevāḥ sarṣicāraṇāḥ', null, 6088052),
('ramayana-6-88-53', 53, 'Yuddha Kanda, Sarga 88, Verse 53', 'अद्य कर्म करिष्यामि यल्लोकाः सचराचराः।
सदेवाः कथयिष्यन्ति यावद्भूमिर्धरिष्यति॥', 'adya karma kariṣyāmi yal lokāḥ sacarācarāḥ
sadevāḥ kathayiṣyanti yāvad bhūmir dhariṣyati', null, 6088053),
('ramayana-6-88-54', 54, 'Yuddha Kanda, Sarga 88, Verse 54', 'एवमुक्त्वा शितैर्बाणैस्तप्तकाञ्चनभूषणैः।
आजघान दशग्रीवं रणे रामः समाहितः॥', 'evam uktvā śitair bāṇais taptakāñcanabhūṣaṇaiḥ
ājaghāna daśagrīvaṃ raṇe rāmaḥ samāhitaḥ', null, 6088054),
('ramayana-6-88-55', 55, 'Yuddha Kanda, Sarga 88, Verse 55', 'अथ प्रदीप्तैर्नाराचैर्मुसलैश्चापि रावणः।
अभ्यवर्षत्तदा रामं धाराभिरिव तोयदः॥', 'atha pradīptair nārācair musalaiś cāpi rāvaṇaḥ
abhyavarṣat tadā rāmaṃ dhārābhir iva toyadaḥ', null, 6088055),
('ramayana-6-88-56', 56, 'Yuddha Kanda, Sarga 88, Verse 56', 'रामरावणमुक्तानामन्योन्यमभिनिघ्नताम्।
शराणां च शराणां च बभूव तुमुलः स्वनः॥', 'rāmarāvaṇamuktānām anyonyam abhinighnatām
śarāṇāṃ ca śarāṇāṃ ca babhūva tumulaḥ svanaḥ', null, 6088056),
('ramayana-6-88-57', 57, 'Yuddha Kanda, Sarga 88, Verse 57', 'ते भिन्नाश्च विकीर्णाश्च रामरावणयोः शराः।
अन्तरिक्षात्प्रदीप्ताग्रा निपेतुर्धरणीतले॥', 'te bhinnāś ca vikīrṇāś ca rāmarāvaṇayoḥ śarāḥ
antarikṣāt pradīptāgrā nipetur dharaṇītale', null, 6088057),
('ramayana-6-88-58', 58, 'Yuddha Kanda, Sarga 88, Verse 58', 'तयोर्ज्यातलनिर्घोषो रामरावणयोर्महान्।
त्रासनः सर्वबूतानां स बभूवाद्भुतोपमः॥', 'tayor jyātalanirghoṣo rāmarāvaṇayor mahān
trāsanaḥ sarvabūtānāṃ sa babhūvādbhutopamaḥ', null, 6088058),
('ramayana-6-88-59', 59, 'Yuddha Kanda, Sarga 88, Verse 59', 'स कीर्यमाणः शरजालवृष्टिभिर्महात्मना दीप्तधनुष्मतार्दितः।
भयात्प्रदुद्राव समेत्य रावणो यथानिलेनाभिहतो बलाहकः॥', 'sa kīryamāṇaḥ śarajālavṛṣṭibhir mahātmanā dīptadhanuṣmatārditaḥ
bhayāt pradudrāva sametya rāvaṇo yathānilenābhihato balāhakaḥ', null, 6088059)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 89 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-89-1', 1, 'Yuddha Kanda, Sarga 89, Verse 1', 'स दत्त्वा तुमुलं युद्धं रावणस्य दुरात्मनः।
विसृजन्नेव बाणौघान्सुषेणं वाक्यमब्रवीत्॥', 'sa dattvā tumulaṃ yuddhaṃ rāvaṇasya durātmanaḥ
visṛjann eva bāṇaughān suṣeṇaṃ vākyam abravīt', null, 6089001),
('ramayana-6-89-2', 2, 'Yuddha Kanda, Sarga 89, Verse 2', 'एष रावणवेगेन लक्ष्मणः पतितः क्षितौ।
सर्पवद्वेष्टते वीरो मम शोकमुदीरयन्॥', 'eṣa rāvaṇavegena lakṣmaṇaḥ patitaḥ kṣitau
sarpavad veṣṭate vīro mama śokam udīrayan', null, 6089002),
('ramayana-6-89-3', 3, 'Yuddha Kanda, Sarga 89, Verse 3', 'शोणितार्द्रमिमं वीरं प्राणैरिष्टतरं मम।
पश्यतो मम का शक्तिर्योद्धुं पर्याकुलात्मनः॥', 'śoṇitārdram imaṃ vīraṃ prāṇair iṣṭataraṃ mama
paśyato mama kā śaktir yoddhuṃ paryākulātmanaḥ', null, 6089003),
('ramayana-6-89-4', 4, 'Yuddha Kanda, Sarga 89, Verse 4', 'अयं स समरश्लाघी भ्राता मे शुभलक्षणः।
यदि पञ्चत्वमापन्नः प्राणैर्मे किं सुखेन वा॥', 'ayaṃ sa samaraślāghī bhrātā me śubhalakṣaṇaḥ
yadi pañcatvam āpannaḥ prāṇair me kiṃ sukhena vā', null, 6089004),
('ramayana-6-89-5', 5, 'Yuddha Kanda, Sarga 89, Verse 5', 'लज्जतीव हि मे वीर्यं भ्रश्यतीव कराद्धनुः।
सायका व्यवसीदन्ति दृष्टिर्बाष्पवशं गता।
चिन्ता मे वर्धते तीव्रा मुमूर्षा चोपजायते॥', 'lajjatīva hi me vīryaṃ bhraśyatīva karād dhanuḥ
sāyakā vyavasīdanti dṛṣṭir bāṣpavaśaṃ gatā
cintā me vardhate tīvrā mumūrṣā copajāyate', null, 6089005),
('ramayana-6-89-6', 6, 'Yuddha Kanda, Sarga 89, Verse 6', 'भ्रातरं निहतं दृष्ट्वा रावणेन दुरात्मना।
परं विषादमापन्नो विललापाकुलेन्द्रियः॥', 'bhrātaraṃ nihataṃ dṛṣṭvā rāvaṇena durātmanā
paraṃ viṣādam āpanno vilalāpākulendriyaḥ', null, 6089006),
('ramayana-6-89-7', 7, 'Yuddha Kanda, Sarga 89, Verse 7', 'न हि युद्धेन मे कार्यं नैव प्राणैर्न सीतया।
भ्रातरं निहतं दृष्ट्वा लक्ष्मणं रणपांसुषु॥', 'na hi yuddhena me kāryaṃ naiva prāṇair na sītayā
bhrātaraṃ nihataṃ dṛṣṭvā lakṣmaṇaṃ raṇapāṃsuṣu', null, 6089007),
('ramayana-6-89-8', 8, 'Yuddha Kanda, Sarga 89, Verse 8', 'किं मे राज्येन किं प्राणैर्युद्धे कार्यं न विद्यते।
यत्रायं निहतः शेते रणमूर्धनि लक्ष्मणः॥', 'kiṃ me rājyena kiṃ prāṇair yuddhe kāryaṃ na vidyate
yatrāyaṃ nihataḥ śete raṇamūrdhani lakṣmaṇaḥ', null, 6089008),
('ramayana-6-89-9', 9, 'Yuddha Kanda, Sarga 89, Verse 9', 'राममाश्वासयन्वीरः सुषेणो वाक्यमब्रवीत्।
न मृतोऽयं महाबाहुर्लक्ष्मणो लक्ष्मिवर्धनः॥', 'rāmam āśvāsayan vīraḥ suṣeṇo vākyam abravīt
na mṛto ''yaṃ mahābāhur lakṣmaṇo lakṣmivardhanaḥ', null, 6089009),
('ramayana-6-89-10', 10, 'Yuddha Kanda, Sarga 89, Verse 10', 'न चास्य विकृतं वक्त्रं नापि श्यामं न निष्प्रभम्।
सुप्रभं च प्रसन्नं च मुखमस्याभिलक्ष्यते॥', 'na cāsya vikṛtaṃ vaktraṃ nāpi śyāmaṃ na niṣprabham
suprabhaṃ ca prasannaṃ ca mukham asyābhilakṣyate', null, 6089010),
('ramayana-6-89-11', 11, 'Yuddha Kanda, Sarga 89, Verse 11', 'पद्मरक्ततलौ हस्तौ सुप्रसन्ने च लोचने।
एवं न विद्यते रूपं गतासूनां विशां पते।
मां विषादं कृथा वीर सप्राणोऽयमरिंदम॥', 'padmaraktatalau hastau suprasanne ca locane
evaṃ na vidyate rūpaṃ gatāsūnāṃ viśāṃ pate
māṃ viṣādaṃ kṛthā vīra saprāṇo ''yam ariṃdama', null, 6089011),
('ramayana-6-89-12', 12, 'Yuddha Kanda, Sarga 89, Verse 12', 'आख्यास्यते प्रसुप्तस्य स्रस्तगात्रस्य भूतले।
सोच्छ्वासं हृदयं वीर कम्पमानं मुहुर्मुहुः॥', 'ākhyāsyate prasuptasya srastagātrasya bhūtale
socchvāsaṃ hṛdayaṃ vīra kampamānaṃ muhur muhuḥ', null, 6089012),
('ramayana-6-89-13', 13, 'Yuddha Kanda, Sarga 89, Verse 13', 'एवमुक्त्वा तु वाक्यज्ञः सुषेणो राघवं वचः।
समीपस्थमुवाचेदं हनूमन्तमभित्वरन्॥', 'evam uktvā tu vākyajñaḥ suṣeṇo rāghavaṃ vacaḥ
samīpastham uvācedaṃ hanūmantam abhitvaran', null, 6089013),
('ramayana-6-89-14', 14, 'Yuddha Kanda, Sarga 89, Verse 14', 'सौम्य शीघ्रमितो गत्वा शैलमोषधिपर्वतम्।
पूर्वं हि कथितो योऽसौ वीर जाम्बवता शुभः॥', 'saumya śīghram ito gatvā śailam oṣadhiparvatam
pūrvaṃ hi kathito yo ''sau vīra jāmbavatā śubhaḥ', null, 6089014),
('ramayana-6-89-15', 15, 'Yuddha Kanda, Sarga 89, Verse 15', 'दक्षिणे शिखरे तस्य जातामोषधिमानय।
विशल्यकरणी नाम विशल्यकरणीं शुभाम्॥', 'dakṣiṇe śikhare tasya jātām oṣadhim ānaya
viśalyakaraṇī nāma viśalyakaraṇīṃ śubhām', null, 6089015),
('ramayana-6-89-16', 16, 'Yuddha Kanda, Sarga 89, Verse 16', 'सौवर्णकरणीं चापि तथा संजीवनीमपि।
संधानकरणीं चापि गत्वा शीघ्रमिहानय।
संजीवनार्थं वीरस्य लक्ष्मणस्य महात्मनः॥', 'sauvarṇakaraṇīṃ cāpi tathā saṃjīvanīm api
saṃdhānakaraṇīṃ cāpi gatvā śīghram ihānaya
saṃjīvanārthaṃ vīrasya lakṣmaṇasya mahātmanaḥ', null, 6089016),
('ramayana-6-89-17', 17, 'Yuddha Kanda, Sarga 89, Verse 17', 'इत्येवमुक्तो हनुमान्गत्वा चौषधिपर्वतम्।
चिन्तामभ्यगमच्छ्रीमानजानंस्ता महौषधीः॥', 'ity evam ukto hanumān gatvā cauṣadhiparvatam
cintām abhyagamac chrīmān ajānaṃs tā mahauṣadhīḥ', null, 6089017),
('ramayana-6-89-18', 18, 'Yuddha Kanda, Sarga 89, Verse 18', 'तस्य बुद्धिः समुत्पन्ना मारुतेरमितौजसः।
इदमेव गमिष्यामि गृहीत्वा शिखरं गिरेः॥', 'tasya buddhiḥ samutpannā māruter amitaujasaḥ
idam eva gamiṣyāmi gṛhītvā śikharaṃ gireḥ', null, 6089018),
('ramayana-6-89-19', 19, 'Yuddha Kanda, Sarga 89, Verse 19', 'अगृह्य यदि गच्छामि विशल्यकरणीमहम्।
कालात्ययेन दोषः स्याद्वैक्लव्यं च महद्भवेत्॥', 'agṛhya yadi gacchāmi viśalyakaraṇīm aham
kālātyayena doṣaḥ syād vaiklavyaṃ ca mahad bhavet', null, 6089019),
('ramayana-6-89-20', 20, 'Yuddha Kanda, Sarga 89, Verse 20', 'इति संचिन्त्य हनुमान्गत्वा क्षिप्रं महाबलः।
उत्पपात गृहीत्वा तु हनूमाञ्शिखरं गिरेः॥', 'iti saṃcintya hanumān gatvā kṣipraṃ mahābalaḥ
utpapāta gṛhītvā tu hanūmāñ śikharaṃ gireḥ', null, 6089020),
('ramayana-6-89-21', 21, 'Yuddha Kanda, Sarga 89, Verse 21', 'ओषधीर्नावगछामि ता अहं हरिपुंगव।
तदिदं शिखरं कृत्स्नं गिरेस्तस्याहृतं मया॥', 'oṣadhīr nāvagachāmi tā ahaṃ haripuṃgava
tad idaṃ śikharaṃ kṛtsnaṃ gires tasyāhṛtaṃ mayā', null, 6089021),
('ramayana-6-89-22', 22, 'Yuddha Kanda, Sarga 89, Verse 22', 'एवं कथयमानं तं प्रशस्य पवनात्मजम्।
सुषेणो वानरश्रेष्ठो जग्राहोत्पाट्य चौषधीः॥', 'evaṃ kathayamānaṃ taṃ praśasya pavanātmajam
suṣeṇo vānaraśreṣṭho jagrāhotpāṭya cauṣadhīḥ', null, 6089022),
('ramayana-6-89-23', 23, 'Yuddha Kanda, Sarga 89, Verse 23', 'ततः संक्षोदयित्वा तामोषधिं वानरोत्तमः।
लक्ष्मणस्य ददौ नस्तः सुषेणः सुमहाद्युतिः॥', 'tataḥ saṃkṣodayitvā tām oṣadhiṃ vānarottamaḥ
lakṣmaṇasya dadau nastaḥ suṣeṇaḥ sumahādyutiḥ', null, 6089023),
('ramayana-6-89-24', 24, 'Yuddha Kanda, Sarga 89, Verse 24', 'सशल्यः स समाघ्राय लक्ष्मणः परवीरहा।
विशल्यो विरुजः शीघ्रमुदतिष्ठन्महीतलात्॥', 'saśalyaḥ sa samāghrāya lakṣmaṇaḥ paravīrahā
viśalyo virujaḥ śīghram udatiṣṭhan mahītalāt', null, 6089024),
('ramayana-6-89-25', 25, 'Yuddha Kanda, Sarga 89, Verse 25', 'समुत्थितं ते हरयो भूतलात्प्रेक्ष्य लक्ष्मणम्।
साधु साध्विति सुप्रीताः सुषेणं प्रत्यपूजयन्॥', 'samutthitaṃ te harayo bhūtalāt prekṣya lakṣmaṇam
sādhu sādhv iti suprītāḥ suṣeṇaṃ pratyapūjayan', null, 6089025),
('ramayana-6-89-26', 26, 'Yuddha Kanda, Sarga 89, Verse 26', 'एह्येहीत्यब्रवीद्रामो लक्ष्मणं परवीरहा।
सस्वजे स्नेहगाढं च बाष्पपर्याकुलेक्षणः॥', 'ehy ehīty abravīd rāmo lakṣmaṇaṃ paravīrahā
sasvaje snehagāḍhaṃ ca bāṣpaparyākulekṣaṇaḥ', null, 6089026),
('ramayana-6-89-27', 27, 'Yuddha Kanda, Sarga 89, Verse 27', 'अब्रवीच्च परिष्वज्य सौमित्रिं राघवस्तदा।
दिष्ट्या त्वां वीर पश्यामि मरणात्पुनरागतम्॥', 'abravīc ca pariṣvajya saumitriṃ rāghavas tadā
diṣṭyā tvāṃ vīra paśyāmi maraṇāt punar āgatam', null, 6089027),
('ramayana-6-89-28', 28, 'Yuddha Kanda, Sarga 89, Verse 28', 'न हि मे जीवितेनार्थः सीतया च जयेन वा।
को हि मे जीवितेनार्थस्त्वयि पञ्चत्वमागते॥', 'na hi me jīvitenārthaḥ sītayā ca jayena vā
ko hi me jīvitenārthas tvayi pañcatvam āgate', null, 6089028),
('ramayana-6-89-29', 29, 'Yuddha Kanda, Sarga 89, Verse 29', 'इत्येवं वदतस्तस्य राघवस्य महात्मनः।
खिन्नः शिथिलया वाचा लक्ष्मणो वाक्यमब्रवीत्॥', 'ity evaṃ vadatas tasya rāghavasya mahātmanaḥ
khinnaḥ śithilayā vācā lakṣmaṇo vākyam abravīt', null, 6089029),
('ramayana-6-89-30', 30, 'Yuddha Kanda, Sarga 89, Verse 30', 'तां प्रतिज्ञां प्रतिज्ञाय पुरा सत्यपराक्रम।
लघुः कश्चिदिवासत्त्वो नैवं वक्तुमिहार्हसि॥', 'tāṃ pratijñāṃ pratijñāya purā satyaparākrama
laghuḥ kaś cid ivāsattvo naivaṃ vaktum ihārhasi', null, 6089030),
('ramayana-6-89-31', 31, 'Yuddha Kanda, Sarga 89, Verse 31', 'न प्रतिज्ञां हि कुर्वन्ति वितथां साधवोऽनघ।
लक्षणं हि महत्त्वस्य प्रतिज्ञापरिपालनम्॥', 'na pratijñāṃ hi kurvanti vitathāṃ sādhavo ''nagha
lakṣaṇaṃ hi mahat tv asya pratijñāparipālanam', null, 6089031),
('ramayana-6-89-32', 32, 'Yuddha Kanda, Sarga 89, Verse 32', 'नैराश्यमुपगन्तुं ते तदलं मत्कृतेऽनघ।
वधेन रावणस्याद्य प्रतिज्ञामनुपालय॥', 'nairāśyam upagantuṃ te tad alaṃ matkṛte ''nagha
vadhena rāvaṇasyādya pratijñām anupālaya', null, 6089032),
('ramayana-6-89-33', 33, 'Yuddha Kanda, Sarga 89, Verse 33', 'न जीवन्यास्यते शत्रुस्तव बाणपथं गतः।
नर्दतस्तीक्ष्णदंष्ट्रस्य सिंहस्येव महागजः॥', 'na jīvan yāsyate śatrus tava bāṇapathaṃ gataḥ
nardatas tīkṣṇadaṃṣṭrasya siṃhasyeva mahāgajaḥ', null, 6089033),
('ramayana-6-89-34', 34, 'Yuddha Kanda, Sarga 89, Verse 34', 'अहं तु वधमिच्छामि शीघ्रमस्य दुरात्मनः।
यावदस्तं न यात्येष कृतकर्मा दिवाकरः॥', 'ahaṃ tu vadham icchāmi śīghram asya durātmanaḥ
yāvad astaṃ na yāty eṣa kṛtakarmā divākaraḥ', null, 6089034)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 90 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-90-1', 1, 'Yuddha Kanda, Sarga 90, Verse 1', 'लक्ष्मणेन तु तद्वाक्यमुक्तं श्रुत्वा स राघवः।
रावणाय शरान्घोरान्विससर्ज चमूमुखे॥', 'lakṣmaṇena tu tad vākyam uktaṃ śrutvā sa rāghavaḥ
rāvaṇāya śarān ghorān visasarja camūmukhe', null, 6090001),
('ramayana-6-90-2', 2, 'Yuddha Kanda, Sarga 90, Verse 2', 'दशग्रीवो रथस्थस्तु रामं वज्रोपमैः शरैः।
आजघान महाघोरैर्धाराभिरिव तोयदः॥', 'daśagrīvo rathasthas tu rāmaṃ vajropamaiḥ śaraiḥ
ājaghāna mahāghorair dhārābhir iva toyadaḥ', null, 6090002),
('ramayana-6-90-3', 3, 'Yuddha Kanda, Sarga 90, Verse 3', 'दीप्तपावकसंकाशैः शरैः काञ्चनभूषणैः।
निर्बिभेद रणे रामो दशग्रीवं समाहितः॥', 'dīptapāvakasaṃkāśaiḥ śaraiḥ kāñcanabhūṣaṇaiḥ
nirbibheda raṇe rāmo daśagrīvaṃ samāhitaḥ', null, 6090003),
('ramayana-6-90-4', 4, 'Yuddha Kanda, Sarga 90, Verse 4', 'भूमिस्थितस्य रामस्य रथस्थस्य च रक्षसः।
न समं युद्धमित्याहुर्देवगन्धर्वदानवाः॥', 'bhūmisthitasya rāmasya rathasthasya ca rakṣasaḥ
na samaṃ yuddham ity āhur devagandharvadānavāḥ', null, 6090004),
('ramayana-6-90-5', 5, 'Yuddha Kanda, Sarga 90, Verse 5', 'ततः काञ्चनचित्राङ्गः किंकिणीशतभूषितः।
तरुणादित्यसंकाशो वैदूर्यमयकूबरः॥', 'tataḥ kāñcanacitrāṅgaḥ kiṃkiṇīśatabhūṣitaḥ
taruṇādityasaṃkāśo vaidūryamayakūbaraḥ', null, 6090005),
('ramayana-6-90-6', 6, 'Yuddha Kanda, Sarga 90, Verse 6', 'सदश्वैः काञ्चनापीडैर्युक्तः श्वेतप्रकीर्णकैः।
हरिभिः सूर्यसंकाशैर्हेमजालविभूषितैः॥', 'sadaśvaiḥ kāñcanāpīḍair yuktaḥ śvetaprakīrṇakaiḥ
haribhiḥ sūryasaṃkāśair hemajālavibhūṣitaiḥ', null, 6090006),
('ramayana-6-90-7', 7, 'Yuddha Kanda, Sarga 90, Verse 7', 'रुक्मवेणुध्वजः श्रीमान्देवराजरथो वरः।
अभ्यवर्तत काकुत्स्थमवतीर्य त्रिविष्टपात्॥', 'rukmaveṇudhvajaḥ śrīmān devarājaratho varaḥ
abhyavartata kākutstham avatīrya triviṣṭapāt', null, 6090007),
('ramayana-6-90-8', 8, 'Yuddha Kanda, Sarga 90, Verse 8', 'अब्रवीच्च तदा रामं सप्रतोदो रथे स्थितः।
प्राञ्जलिर्मातलिर्वाक्यं सहस्राक्षस्य सारथिः॥', 'abravīc ca tadā rāmaṃ sapratodo rathe sthitaḥ
prāñjalir mātalir vākyaṃ sahasrākṣasya sārathiḥ', null, 6090008),
('ramayana-6-90-9', 9, 'Yuddha Kanda, Sarga 90, Verse 9', 'सहस्राक्षेण काकुत्स्थ रथोऽयं विजयाय ते।
दत्तस्तव महासत्त्व श्रीमाञ्शत्रुनिबर्हणः॥', 'sahasrākṣeṇa kākutstha ratho ''yaṃ vijayāya te
dattas tava mahāsattva śrīmāñ śatrunibarhaṇaḥ', null, 6090009),
('ramayana-6-90-10', 10, 'Yuddha Kanda, Sarga 90, Verse 10', 'इदमैन्द्रं महच्चापं कवचं चाग्निसंनिभम्।
शराश्चादित्यसंकाशाः शक्तिश्च विमला शिताः॥', 'idam aindraṃ mahaccāpaṃ kavacaṃ cāgnisaṃnibham
śarāś cādityasaṃkāśāḥ śaktiś ca vimalā śitāḥ', null, 6090010),
('ramayana-6-90-11', 11, 'Yuddha Kanda, Sarga 90, Verse 11', 'आरुह्येमं रथं वीर राक्षसं जहि रावणम्।
मया सारथिना राम महेन्द्र इव दानवान्॥', 'āruhyemaṃ rathaṃ vīra rākṣasaṃ jahi rāvaṇam
mayā sārathinā rāma mahendra iva dānavān', null, 6090011),
('ramayana-6-90-12', 12, 'Yuddha Kanda, Sarga 90, Verse 12', 'इत्युक्तः स परिक्रम्य रथं तमभिवाद्य च।
आरुरोह तदा रामो लोकांल्लक्ष्म्या विराजयन्॥', 'ity uktaḥ sa parikramya rathaṃ tam abhivādya ca
āruroha tadā rāmo lokāṃl lakṣmyā virājayan', null, 6090012),
('ramayana-6-90-13', 13, 'Yuddha Kanda, Sarga 90, Verse 13', 'तद्बभूवाद्भुतं युद्धं द्वैरथं लोमहर्षणम्।
रामस्य च महाबाहो रावणस्य च रक्षसः॥', 'tad babhūvādbhutaṃ yuddhaṃ dvairathaṃ lomaharṣaṇam
rāmasya ca mahābāho rāvaṇasya ca rakṣasaḥ', null, 6090013),
('ramayana-6-90-14', 14, 'Yuddha Kanda, Sarga 90, Verse 14', 'स गान्धर्वेण गान्धर्वं दैवं दैवेन राघवः।
अस्त्रं राक्षसराजस्य जघान परमास्त्रवित्॥', 'sa gāndharveṇa gāndharvaṃ daivaṃ daivena rāghavaḥ
astraṃ rākṣasarājasya jaghāna paramāstravit', null, 6090014),
('ramayana-6-90-15', 15, 'Yuddha Kanda, Sarga 90, Verse 15', 'अस्त्रं तु परमं घोरं राक्षसं राकसाधिपः।
ससर्ज परमक्रुद्धः पुनरेव निशाचरः॥', 'astraṃ tu paramaṃ ghoraṃ rākṣasaṃ rākasādhipaḥ
sasarja paramakruddhaḥ punar eva niśācaraḥ', null, 6090015),
('ramayana-6-90-16', 16, 'Yuddha Kanda, Sarga 90, Verse 16', 'ते रावणधनुर्मुक्ताः शराः काञ्चनभूषणाः।
अभ्यवर्तन्त काकुत्स्थं सर्पा भूत्वा महाविषाः॥', 'te rāvaṇadhanurmuktāḥ śarāḥ kāñcanabhūṣaṇāḥ
abhyavartanta kākutsthaṃ sarpā bhūtvā mahāviṣāḥ', null, 6090016),
('ramayana-6-90-17', 17, 'Yuddha Kanda, Sarga 90, Verse 17', 'ते दीप्तवदना दीप्तं वमन्तो ज्वलनं मुखैः।
राममेवाभ्यवर्तन्त व्यादितास्या भयानकाः॥', 'te dīptavadanā dīptaṃ vamanto jvalanaṃ mukhaiḥ
rāmam evābhyavartanta vyāditāsyā bhayānakāḥ', null, 6090017),
('ramayana-6-90-18', 18, 'Yuddha Kanda, Sarga 90, Verse 18', 'तैर्वासुकिसमस्पर्शैर्दीप्तभोगैर्महाविषैः।
दिशश्च संतताः सर्वाः प्रदिशश्च समावृताः॥', 'tair vāsukisamasparśair dīptabhogair mahāviṣaiḥ
diśaś ca saṃtatāḥ sarvāḥ pradiśaś ca samāvṛtāḥ', null, 6090018),
('ramayana-6-90-19', 19, 'Yuddha Kanda, Sarga 90, Verse 19', 'तान्दृष्ट्वा पन्नगान्रामः समापतत आहवे।
अस्त्रं गारुत्मतं घोरं प्रादुश्चक्रे भयावहम्॥', 'tān dṛṣṭvā pannagān rāmaḥ samāpatata āhave
astraṃ gārutmataṃ ghoraṃ prāduścakre bhayāvaham', null, 6090019),
('ramayana-6-90-20', 20, 'Yuddha Kanda, Sarga 90, Verse 20', 'ते राघवधनुर्मुक्ता रुक्मपुङ्खाः शिखिप्रभाः।
सुपर्णाः काञ्चना भूत्वा विचेरुः सर्पशत्रवः॥', 'te rāghavadhanurmuktā rukmapuṅkhāḥ śikhiprabhāḥ
suparṇāḥ kāñcanā bhūtvā viceruḥ sarpaśatravaḥ', null, 6090020),
('ramayana-6-90-21', 21, 'Yuddha Kanda, Sarga 90, Verse 21', 'ते तान्सर्वाञ्शराञ्जघ्नुः सर्परूपान्महाजवान्।
सुपर्णरूपा रामस्य विशिखाः कामरूपिणः॥', 'te tān sarvāñ śarāñ jaghnuḥ sarparūpān mahājavān
suparṇarūpā rāmasya viśikhāḥ kāmarūpiṇaḥ', null, 6090021),
('ramayana-6-90-22', 22, 'Yuddha Kanda, Sarga 90, Verse 22', 'अस्त्रे प्रतिहते क्रुद्धो रावणो राक्षसाधिपः।
अभ्यवर्षत्तदा रामं घोराभिः शरवृष्टिभिः॥', 'astre pratihate kruddho rāvaṇo rākṣasādhipaḥ
abhyavarṣat tadā rāmaṃ ghorābhiḥ śaravṛṣṭibhiḥ', null, 6090022),
('ramayana-6-90-23', 23, 'Yuddha Kanda, Sarga 90, Verse 23', 'ततः शरसहस्रेण राममक्लिष्टकारिणम्।
अर्दयित्वा शरौघेण मातलिं प्रत्यविध्यत॥', 'tataḥ śarasahasreṇa rāmam akliṣṭakāriṇam
ardayitvā śaraugheṇa mātaliṃ pratyavidhyata', null, 6090023),
('ramayana-6-90-24', 24, 'Yuddha Kanda, Sarga 90, Verse 24', 'पातयित्वा रथोपस्थे रथात्केतुं च काञ्चनम्।
ऐन्द्रानभिजघानाश्वाञ्शरजालेन रावणः॥', 'pātayitvā rathopasthe rathāt ketuṃ ca kāñcanam
aindrān abhijaghānāśvāñ śarajālena rāvaṇaḥ', null, 6090024),
('ramayana-6-90-25', 25, 'Yuddha Kanda, Sarga 90, Verse 25', 'विषेदुर्देवगन्धर्वा दानवाश्चारणैः सह।
राममार्तं तदा दृष्ट्वा सिद्धाश्च परमर्षयः॥', 'viṣedur devagandharvā dānavāś cāraṇaiḥ saha
rāmam ārtaṃ tadā dṛṣṭvā siddhāś ca paramarṣayaḥ', null, 6090025),
('ramayana-6-90-26', 26, 'Yuddha Kanda, Sarga 90, Verse 26', 'व्यथिता वानरेन्द्राश्च बभूवुः सविभीषणाः।
रामचन्द्रमसं दृष्ट्वा ग्रस्तं रावणराहुणा॥', 'vyathitā vānarendrāś ca babhūvuḥ savibhīṣaṇāḥ
rāmacandramasaṃ dṛṣṭvā grastaṃ rāvaṇarāhuṇā', null, 6090026),
('ramayana-6-90-27', 27, 'Yuddha Kanda, Sarga 90, Verse 27', 'प्राजापत्यं च नक्षत्रं रोहिणीं शशिनः प्रियाम्।
समाक्रम्य बुधस्तस्थौ प्रजानामशुभावहः॥', 'prājāpatyaṃ ca nakṣatraṃ rohiṇīṃ śaśinaḥ priyām
samākramya budhas tasthau prajānām aśubhāvahaḥ', null, 6090027),
('ramayana-6-90-28', 28, 'Yuddha Kanda, Sarga 90, Verse 28', 'सधूमपरिवृत्तोर्मिः प्रज्वलन्निव सागरः।
उत्पपात तदा क्रुद्धः स्पृशन्निव दिवाकरम्॥', 'sadhūmaparivṛttormiḥ prajvalann iva sāgaraḥ
utpapāta tadā kruddhaḥ spṛśann iva divākaram', null, 6090028),
('ramayana-6-90-29', 29, 'Yuddha Kanda, Sarga 90, Verse 29', 'शस्त्रवर्णः सुपरुषो मन्दरश्मिर्दिवाकरः।
अदृश्यत कबन्धाङ्गः संसक्तो धूमकेतुना॥', 'śastravarṇaḥ suparuṣo mandaraśmir divākaraḥ
adṛśyata kabandhāṅgaḥ saṃsakto dhūmaketunā', null, 6090029),
('ramayana-6-90-30', 30, 'Yuddha Kanda, Sarga 90, Verse 30', 'कोसलानां च नक्षत्रं व्यक्तमिन्द्राग्निदैवतम्।
आक्रम्याङ्गारकस्तस्थौ विशाखामपि चाम्बरे॥', 'kosalānāṃ ca nakṣatraṃ vyaktam indrāgnidaivatam
ākramyāṅgārakas tasthau viśākhām api cāmbare', null, 6090030),
('ramayana-6-90-31', 31, 'Yuddha Kanda, Sarga 90, Verse 31', 'दशास्यो विंशतिभुजः प्रगृहीतशरासनः।
अदृश्यत दशग्रीवो मैनाक इव पर्वतः॥', 'daśāsyo viṃśatibhujaḥ pragṛhītaśarāsanaḥ
adṛśyata daśagrīvo maināka iva parvataḥ', null, 6090031),
('ramayana-6-90-32', 32, 'Yuddha Kanda, Sarga 90, Verse 32', 'निरस्यमानो रामस्तु दशग्रीवेण रक्षसा।
नाशकदभिसंधातुं सायकान्रणमूर्धनि॥', 'nirasyamāno rāmas tu daśagrīveṇa rakṣasā
nāśakad abhisaṃdhātuṃ sāyakān raṇamūrdhani', null, 6090032),
('ramayana-6-90-33', 33, 'Yuddha Kanda, Sarga 90, Verse 33', 'स कृत्वा भ्रुकुटीं क्रुद्धः किं चित्संरक्तलोचनः।
जगाम सुमहाक्रोधं निर्दहन्निव चक्षुषा॥', 'sa kṛtvā bhrukuṭīṃ kruddhaḥ kiṃ cit saṃraktalocanaḥ
jagāma sumahākrodhaṃ nirdahann iva cakṣuṣā', null, 6090033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 91 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-91-1', 1, 'Yuddha Kanda, Sarga 91, Verse 1', 'तस्य क्रुद्धस्य वदनं दृष्ट्वा रामस्य धीमतः।
सर्वभूतानि वित्रेषुः प्राकम्पत च मेदिनी॥', 'tasya kruddhasya vadanaṃ dṛṣṭvā rāmasya dhīmataḥ
sarvabhūtāni vitreṣuḥ prākampata ca medinī', null, 6091001),
('ramayana-6-91-2', 2, 'Yuddha Kanda, Sarga 91, Verse 2', 'सिंहशार्दूलवाञ्शैलः संचचालाचलद्रुमः।
बभूव चापि क्षुभितः समुद्रः सरितां पतिः॥', 'siṃhaśārdūlavāñ śailaḥ saṃcacālācaladrumaḥ
babhūva cāpi kṣubhitaḥ samudraḥ saritāṃ patiḥ', null, 6091002),
('ramayana-6-91-3', 3, 'Yuddha Kanda, Sarga 91, Verse 3', 'खगाश्च खरनिर्घोषा गगने परुषस्वनाः।
औत्पातिका विनर्दन्तः समन्तात्परिचक्रमुः॥', 'khagāś ca kharanirghoṣā gagane paruṣasvanāḥ
autpātikā vinardantaḥ samantāt paricakramuḥ', null, 6091003),
('ramayana-6-91-4', 4, 'Yuddha Kanda, Sarga 91, Verse 4', 'रामं दृष्ट्वा सुसंक्रुद्धमुत्पातांश्च सुदारुणान्।
वित्रेषुः सर्वभूतानि रावणस्याविशद्भयम्॥', 'rāmaṃ dṛṣṭvā susaṃkruddham utpātāṃś ca sudāruṇān
vitreṣuḥ sarvabhūtāni rāvaṇasyāviśad bhayam', null, 6091004),
('ramayana-6-91-5', 5, 'Yuddha Kanda, Sarga 91, Verse 5', 'विमानस्थास्तदा देवा गन्धर्वाश्च महोरगाः।
ऋषिदानवदैत्याश्च गरुत्मन्तश्च खेचराः॥', 'vimānasthās tadā devā gandharvāś ca mahoragāḥ
ṛṣidānavadaityāś ca garutmantaś ca khecarāḥ', null, 6091005),
('ramayana-6-91-6', 6, 'Yuddha Kanda, Sarga 91, Verse 6', 'ददृशुस्ते तदा युद्धं लोकसंवर्तसंस्थितम्।
नानाप्रहरणैर्भीमैः शूरयोः संप्रयुध्यतोः॥', 'dadṛśus te tadā yuddhaṃ lokasaṃvartasaṃsthitam
nānāpraharaṇair bhīmaiḥ śūrayoḥ saṃprayudhyatoḥ', null, 6091006),
('ramayana-6-91-7', 7, 'Yuddha Kanda, Sarga 91, Verse 7', 'ऊचुः सुरासुराः सर्वे तदा विग्रहमागताः।
प्रेक्षमाणा महायुद्धं वाक्यं भक्त्या प्रहृष्टवत्॥', 'ūcuḥ surāsurāḥ sarve tadā vigraham āgatāḥ
prekṣamāṇā mahāyuddhaṃ vākyaṃ bhaktyā prahṛṣṭavat', null, 6091007),
('ramayana-6-91-8', 8, 'Yuddha Kanda, Sarga 91, Verse 8', 'दशग्रीवं जयेत्याहुरसुराः समवस्थिताः।
देवा राममथोचुस्ते त्वं जयेति पुनः पुनः॥', 'daśagrīvaṃ jayety āhur asurāḥ samavasthitāḥ
devā rāmam athocus te tvaṃ jayeti punaḥ punaḥ', null, 6091008),
('ramayana-6-91-9', 9, 'Yuddha Kanda, Sarga 91, Verse 9', 'एतस्मिन्नन्तरे क्रोधाद्राघवस्य स रावणः।
प्रहर्तुकामो दुष्टात्मा स्पृशन्प्रहरणं महत्॥', 'etasminn antare krodhād rāghavasya sa rāvaṇaḥ
prahartukāmo duṣṭātmā spṛśan praharaṇaṃ mahat', null, 6091009),
('ramayana-6-91-10', 10, 'Yuddha Kanda, Sarga 91, Verse 10', 'वज्रसारं महानादं सर्वशत्रुनिबर्हणम्।
शैलशृङ्गनिभैः कूटैश्चितं दृष्टिभयावहम्॥', 'vajrasāraṃ mahānādaṃ sarvaśatrunibarhaṇam
śailaśṛṅganibhaiḥ kūṭaiś citaṃ dṛṣṭibhayāvaham', null, 6091010),
('ramayana-6-91-11', 11, 'Yuddha Kanda, Sarga 91, Verse 11', 'सधूममिव तीक्ष्णाग्रं युगान्ताग्निचयोपमम्।
अतिरौद्रमनासाद्यं कालेनापि दुरासदम्॥', 'sadhūmam iva tīkṣṇāgraṃ yugāntāgnicayopamam
atiraudram anāsādyaṃ kālenāpi durāsadam', null, 6091011),
('ramayana-6-91-12', 12, 'Yuddha Kanda, Sarga 91, Verse 12', 'त्रासनं सर्वभूतानां दारणं भेदनं तथा।
प्रदीप्त इव रोषेण शूलं जग्राह रावणः॥', 'trāsanaṃ sarvabhūtānāṃ dāraṇaṃ bhedanaṃ tathā
pradīpta iva roṣeṇa śūlaṃ jagrāha rāvaṇaḥ', null, 6091012),
('ramayana-6-91-13', 13, 'Yuddha Kanda, Sarga 91, Verse 13', 'तच्छूलं परमक्रुद्धो मध्ये जग्राह वीर्यवान्।
अनेकैः समरे शूरै राक्षसैः परिवारितः॥', 'tac chūlaṃ paramakruddho madhye jagrāha vīryavān
anekaiḥ samare śūrai rākṣasaiḥ parivāritaḥ', null, 6091013),
('ramayana-6-91-14', 14, 'Yuddha Kanda, Sarga 91, Verse 14', 'समुद्यम्य महाकायो ननाद युधि भैरवम्।
संरक्तनयनो रोषात्स्वसैन्यमभिहर्षयन्॥', 'samudyamya mahākāyo nanāda yudhi bhairavam
saṃraktanayano roṣāt svasainyam abhiharṣayan', null, 6091014),
('ramayana-6-91-15', 15, 'Yuddha Kanda, Sarga 91, Verse 15', 'पृथिवीं चान्तरिक्षं च दिशश्च प्रदिशस्तथा।
प्राकम्पयत्तदा शब्दो राक्षसेन्द्रस्य दारुणः॥', 'pṛthivīṃ cāntarikṣaṃ ca diśaś ca pradiśas tathā
prākampayat tadā śabdo rākṣasendrasya dāruṇaḥ', null, 6091015),
('ramayana-6-91-16', 16, 'Yuddha Kanda, Sarga 91, Verse 16', 'अतिनादस्य नादेन तेन तस्य दुरात्मनः।
सर्वभूतानि वित्रेषुः सागरश्च प्रचुक्षुभे॥', 'atinādasya nādena tena tasya durātmanaḥ
sarvabhūtāni vitreṣuḥ sāgaraś ca pracukṣubhe', null, 6091016),
('ramayana-6-91-17', 17, 'Yuddha Kanda, Sarga 91, Verse 17', 'स गृहीत्वा महावीर्यः शूलं तद्रावणो महत्।
विनद्य सुमहानादं रामं परुषमब्रवीत्॥', 'sa gṛhītvā mahāvīryaḥ śūlaṃ tad rāvaṇo mahat
vinadya sumahānādaṃ rāmaṃ paruṣam abravīt', null, 6091017),
('ramayana-6-91-18', 18, 'Yuddha Kanda, Sarga 91, Verse 18', 'शूलोऽयं वज्रसारस्ते राम रोषान्मयोद्यतः।
तव भ्रातृसहायस्य सद्यः प्राणान्हरिष्यति॥', 'śūlo ''yaṃ vajrasāras te rāma roṣān mayodyataḥ
tava bhrātṛsahāyasya sadyaḥ prāṇān hariṣyati', null, 6091018),
('ramayana-6-91-19', 19, 'Yuddha Kanda, Sarga 91, Verse 19', 'रक्षसामद्य शूराणां निहतानां चमूमुखे।
त्वां निहत्य रणश्लाघिन्करोमि तरसा समम्॥', 'rakṣasām adya śūrāṇāṃ nihatānāṃ camūmukhe
tvāṃ nihatya raṇaślāghin karomi tarasā samam', null, 6091019),
('ramayana-6-91-20', 20, 'Yuddha Kanda, Sarga 91, Verse 20', 'तिष्ठेदानीं निहन्मि त्वामेष शूलेन राघव।
एवमुक्त्वा स चिक्षेप तच्छूलं राक्षसाधिपः॥', 'tiṣṭhedānīṃ nihanmi tvām eṣa śūlena rāghava
evam uktvā sa cikṣepa tac chūlaṃ rākṣasādhipaḥ', null, 6091020),
('ramayana-6-91-21', 21, 'Yuddha Kanda, Sarga 91, Verse 21', 'आपतन्तं शरौघेण वारयामास राघवः।
उत्पतन्तं युगान्ताग्निं जलौघैरिव वासवः॥', 'āpatantaṃ śaraugheṇa vārayām āsa rāghavaḥ
utpatantaṃ yugāntāgniṃ jalaughair iva vāsavaḥ', null, 6091021),
('ramayana-6-91-22', 22, 'Yuddha Kanda, Sarga 91, Verse 22', 'निर्ददाह स तान्बाणान्रामकार्मुकनिःसृतान्।
रावणस्य महाशूलः पतंगानिव पावकः॥', 'nirdadāha sa tān bāṇān rāmakārmukaniḥsṛtān
rāvaṇasya mahāśūlaḥ pataṃgān iva pāvakaḥ', null, 6091022),
('ramayana-6-91-23', 23, 'Yuddha Kanda, Sarga 91, Verse 23', 'तान्दृष्ट्वा भस्मसाद्भूताञ्शूलसंस्पर्शचूर्णितान्।
सायकानन्तरिक्षस्थान्राघवः क्रोधमाहरत्॥', 'tān dṛṣṭvā bhasmasād bhūtāñ śūlasaṃsparśacūrṇitān
sāyakān antarikṣasthān rāghavaḥ krodham āharat', null, 6091023),
('ramayana-6-91-24', 24, 'Yuddha Kanda, Sarga 91, Verse 24', 'स तां मातलिनानीतां शक्तिं वासवनिर्मिताम्।
जग्राह परमक्रुद्धो राघवो रघुनन्दनः॥', 'sa tāṃ mātalinānītāṃ śaktiṃ vāsavanirmitām
jagrāha paramakruddho rāghavo raghunandanaḥ', null, 6091024),
('ramayana-6-91-25', 25, 'Yuddha Kanda, Sarga 91, Verse 25', 'सा तोलिता बलवता शक्तिर्घण्टाकृतस्वना।
नभः प्रज्वालयामास युगान्तोल्केव सप्रभा॥', 'sā tolitā balavatā śaktir ghaṇṭākṛtasvanā
nabhaḥ prajvālayām āsa yugāntolkeva saprabhā', null, 6091025),
('ramayana-6-91-26', 26, 'Yuddha Kanda, Sarga 91, Verse 26', 'सा क्षिप्ता राक्षसेन्द्रस्य तस्मिञ्शूले पपात ह।
भिन्नः शक्त्या महाञ्शूलो निपपात गतद्युतिः॥', 'sā kṣiptā rākṣasendrasya tasmiñ śūle papāta ha
bhinnaḥ śaktyā mahāñ śūlo nipapāta gatadyutiḥ', null, 6091026),
('ramayana-6-91-27', 27, 'Yuddha Kanda, Sarga 91, Verse 27', 'निर्बिभेद ततो बाणैर्हयानस्य महाजवान्।
रामस्तीक्ष्णैर्महावेगैर्वज्रकल्पैः शितैः शरैः॥', 'nirbibheda tato bāṇair hayān asya mahājavān
rāmas tīkṣṇair mahāvegair vajrakalpaiḥ śitaiḥ śaraiḥ', null, 6091027),
('ramayana-6-91-28', 28, 'Yuddha Kanda, Sarga 91, Verse 28', 'निर्बिभेदोरसि तदा रावणं निशितैः शरैः।
राघवः परमायत्तो ललाटे पत्रिभिस्त्रिभिः॥', 'nirbibhedorasi tadā rāvaṇaṃ niśitaiḥ śaraiḥ
rāghavaḥ paramāyatto lalāṭe patribhis tribhiḥ', null, 6091028),
('ramayana-6-91-29', 29, 'Yuddha Kanda, Sarga 91, Verse 29', 'स शरैर्भिन्नसर्वाङ्गो गात्रप्रस्रुतशोणितः।
राक्षसेन्द्रः समूहस्थः फुल्लाशोक इवाबभौ॥', 'sa śarair bhinnasarvāṅgo gātraprasrutaśoṇitaḥ
rākṣasendraḥ samūhasthaḥ phullāśoka ivābabhau', null, 6091029),
('ramayana-6-91-30', 30, 'Yuddha Kanda, Sarga 91, Verse 30', 'स रामबाणैरतिविद्धगात्रो निशाचरेन्द्रः क्षतजार्द्रगात्रः।
जगाम खेदं च समाजमध्ये क्रोधं च चक्रे सुभृशं तदानीम्॥', 'sa rāmabāṇair atividdhagātro niśācarendraḥ kṣatajārdragātraḥ
jagāma khedaṃ ca samājamadhye krodhaṃ ca cakre subhṛśaṃ tadānīm', null, 6091030)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 92 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-92-1', 1, 'Yuddha Kanda, Sarga 92, Verse 1', 'स तु तेन तदा क्रोधात्काकुत्स्थेनार्दितो रणे।
रावणः समरश्लाघी महाक्रोधमुपागमत्॥', 'sa tu tena tadā krodhāt kākutsthenārdito raṇe
rāvaṇaḥ samaraślāghī mahākrodham upāgamat', null, 6092001),
('ramayana-6-92-2', 2, 'Yuddha Kanda, Sarga 92, Verse 2', 'स दीप्तनयनो रोषाच्चापमायम्य वीर्यवान्।
अभ्यर्दयत्सुसंक्रुद्धो राघवं परमाहवे॥', 'sa dīptanayano roṣāc cāpam āyamya vīryavān
abhyardayat susaṃkruddho rāghavaṃ paramāhave', null, 6092002),
('ramayana-6-92-3', 3, 'Yuddha Kanda, Sarga 92, Verse 3', 'बाणधारासहस्रैस्तु स तोयद इवाम्बरात्।
राघवं रावणो बाणैस्तटाकमिव पूरयत्॥', 'bāṇadhārāsahasrais tu sa toyada ivāmbarāt
rāghavaṃ rāvaṇo bāṇais taṭākam iva pūrayat', null, 6092003),
('ramayana-6-92-4', 4, 'Yuddha Kanda, Sarga 92, Verse 4', 'पूरितः शरजालेन धनुर्मुक्तेन संयुगे।
महागिरिरिवाकम्प्यः काकुस्थो न प्रकम्पते॥', 'pūritaḥ śarajālena dhanurmuktena saṃyuge
mahāgirir ivākampyaḥ kākustho na prakampate', null, 6092004),
('ramayana-6-92-5', 5, 'Yuddha Kanda, Sarga 92, Verse 5', 'स शरैः शरजालानि वारयन्समरे स्थितः।
गभस्तीनिव सूर्यस्य प्रतिजग्राह वीर्यवान्॥', 'sa śaraiḥ śarajālāni vārayan samare sthitaḥ
gabhastīn iva sūryasya pratijagrāha vīryavān', null, 6092005),
('ramayana-6-92-6', 6, 'Yuddha Kanda, Sarga 92, Verse 6', 'ततः शरसहस्राणि क्षिप्रहस्तो निशाचरः।
निजघानोरसि क्रुद्धो राघवस्य महात्मनः॥', 'tataḥ śarasahasrāṇi kṣiprahasto niśācaraḥ
nijaghānorasi kruddho rāghavasya mahātmanaḥ', null, 6092006),
('ramayana-6-92-7', 7, 'Yuddha Kanda, Sarga 92, Verse 7', 'स शोणितसमादिग्धः समरे लक्ष्मणाग्रजः।
दृष्टः फुल्ल इवारण्ये सुमहान्किंशुकद्रुमः॥', 'sa śoṇitasamādigdhaḥ samare lakṣmaṇāgrajaḥ
dṛṣṭaḥ phulla ivāraṇye sumahān kiṃśukadrumaḥ', null, 6092007),
('ramayana-6-92-8', 8, 'Yuddha Kanda, Sarga 92, Verse 8', 'शराभिघातसंरब्धः सोऽपि जग्राह सायकान्।
काकुत्स्थः सुमहातेजा युगान्तादित्यवर्चसः॥', 'śarābhighātasaṃrabdhaḥ so ''pi jagrāha sāyakān
kākutsthaḥ sumahātejā yugāntādityavarcasaḥ', null, 6092008),
('ramayana-6-92-9', 9, 'Yuddha Kanda, Sarga 92, Verse 9', 'ततोऽन्योन्यं सुसंरब्धावुभौ तौ रामरावणौ।
शरान्धकारे समरे नोपालक्षयतां तदा॥', 'tato ''nyonyaṃ susaṃrabdhāv ubhau tau rāmarāvaṇau
śarāndhakāre samare nopālakṣayatāṃ tadā', null, 6092009),
('ramayana-6-92-10', 10, 'Yuddha Kanda, Sarga 92, Verse 10', 'ततः क्रोधसमाविष्टो रामो दशरथात्मजः।
उवाच रावणं वीरः प्रहस्य परुषं वचः॥', 'tataḥ krodhasamāviṣṭo rāmo daśarathātmajaḥ
uvāca rāvaṇaṃ vīraḥ prahasya paruṣaṃ vacaḥ', null, 6092010),
('ramayana-6-92-11', 11, 'Yuddha Kanda, Sarga 92, Verse 11', 'मम भार्या जनस्थानादज्ञानाद्राक्षसाधम।
हृता ते विवशा यस्मात्तस्मात्त्वं नासि वीर्यवान्॥', 'mama bhāryā janasthānād ajñānād rākṣasādhama
hṛtā te vivaśā yasmāt tasmāt tvaṃ nāsi vīryavān', null, 6092011),
('ramayana-6-92-12', 12, 'Yuddha Kanda, Sarga 92, Verse 12', 'मया विरहितां दीनां वर्तमानां महावने।
वैदेहीं प्रसभं हृत्वा शूरोऽहमिति मन्यसे॥', 'mayā virahitāṃ dīnāṃ vartamānāṃ mahāvane
vaidehīṃ prasabhaṃ hṛtvā śūro ''ham iti manyase', null, 6092012),
('ramayana-6-92-13', 13, 'Yuddha Kanda, Sarga 92, Verse 13', 'स्त्रीषु शूर विनाथासु परदाराभिमर्शके।
कृत्वा कापुरुषं कर्म शूरोऽहमिति मन्यसे॥', 'strīṣu śūra vināthāsu paradārābhimarśake
kṛtvā kāpuruṣaṃ karma śūro ''ham iti manyase', null, 6092013),
('ramayana-6-92-14', 14, 'Yuddha Kanda, Sarga 92, Verse 14', 'भिन्नमर्याद निर्लज्ज चारित्रेष्वनवस्थित।
दर्पान्मृत्युमुपादाय शूरोऽहमिति मन्यसे॥', 'bhinnamaryāda nirlajja cāritreṣv anavasthita
darpān mṛtyum upādāya śūro ''ham iti manyase', null, 6092014),
('ramayana-6-92-15', 15, 'Yuddha Kanda, Sarga 92, Verse 15', 'शूरेण धनदभ्रात्रा बलैः समुदितेन च।
श्लाघनीयं यशस्यं च कृतं कर्म महत्त्वया॥', 'śūreṇa dhanadabhrātrā balaiḥ samuditena ca
ślāghanīyaṃ yaśasyaṃ ca kṛtaṃ karma mahat tvayā', null, 6092015),
('ramayana-6-92-16', 16, 'Yuddha Kanda, Sarga 92, Verse 16', 'उत्सेकेनाभिपन्नस्य गर्हितस्याहितस्य च।
कर्मणः प्राप्नुहीदानीं तस्याद्य सुमहत्फलम्॥', 'utsekenābhipannasya garhitasyāhitasya ca
karmaṇaḥ prāpnuhīdānīṃ tasyādya sumahat phalam', null, 6092016),
('ramayana-6-92-17', 17, 'Yuddha Kanda, Sarga 92, Verse 17', 'शूरोऽहमिति चात्मानमवगच्छसि दुर्मते।
नैव लज्जास्ति ते सीतां चोरवद्व्यपकर्षतः॥', 'śūro ''ham iti cātmānam avagacchasi durmate
naiva lajjāsti te sītāṃ coravad vyapakarṣataḥ', null, 6092017),
('ramayana-6-92-18', 18, 'Yuddha Kanda, Sarga 92, Verse 18', 'यदि मत्संनिधौ सीता धर्षिता स्यात्त्वया बलात्।
भ्रातरं तु खरं पश्येस्तदा मत्सायकैर्हतः॥', 'yadi matsaṃnidhau sītā dharṣitā syāt tvayā balāt
bhrātaraṃ tu kharaṃ paśyes tadā matsāyakair hataḥ', null, 6092018),
('ramayana-6-92-19', 19, 'Yuddha Kanda, Sarga 92, Verse 19', 'दिष्ट्यासि मम दुष्टात्मंश्चक्षुर्विषयमागतः।
अद्य त्वां सायकैस्तीक्ष्णैर्नयामि यमसादनम्॥', 'diṣṭyāsi mama duṣṭātmaṃś cakṣurviṣayam āgataḥ
adya tvāṃ sāyakais tīkṣṇair nayāmi yamasādanam', null, 6092019),
('ramayana-6-92-20', 20, 'Yuddha Kanda, Sarga 92, Verse 20', 'अद्य ते मच्छरैश्छिन्नं शिरो ज्वलितकुण्डलम्।
क्रव्यादा व्यपकर्षन्तु विकीर्णं रणपांसुषु॥', 'adya te maccharaiś chinnaṃ śiro jvalitakuṇḍalam
kravyādā vyapakarṣantu vikīrṇaṃ raṇapāṃsuṣu', null, 6092020),
('ramayana-6-92-21', 21, 'Yuddha Kanda, Sarga 92, Verse 21', 'निपत्योरसि गृध्रास्ते क्षितौ क्षिप्तस्य रावण।
पिबन्तु रुधिरं तर्षाद्बाणशल्यान्तरोथितम्॥', 'nipatyorasi gṛdhrās te kṣitau kṣiptasya rāvaṇa
pibantu rudhiraṃ tarṣād bāṇaśalyāntarothitam', null, 6092021),
('ramayana-6-92-22', 22, 'Yuddha Kanda, Sarga 92, Verse 22', 'अद्य मद्बाणाभिन्नस्य गतासोः पतितस्य ते।
कर्षन्त्वन्त्राणि पतगा गरुत्मन्त इवोरगान्॥', 'adya madbāṇābhinnasya gatāsoḥ patitasya te
karṣantv antrāṇi patagā garutmanta ivoragān', null, 6092022),
('ramayana-6-92-23', 23, 'Yuddha Kanda, Sarga 92, Verse 23', 'इत्येवं स वदन्वीरो रामः शत्रुनिबर्हणः।
राक्षसेन्द्रं समीपस्थं शरवर्षैरवाकिरत्॥', 'ity evaṃ sa vadan vīro rāmaḥ śatrunibarhaṇaḥ
rākṣasendraṃ samīpasthaṃ śaravarṣair avākirat', null, 6092023),
('ramayana-6-92-24', 24, 'Yuddha Kanda, Sarga 92, Verse 24', 'बभूव द्विगुणं वीर्यं बलं हर्षश्च संयुगे।
रामस्यास्त्रबलं चैव शत्रोर्निधनकाङ्क्षिणः॥', 'babhūva dviguṇaṃ vīryaṃ balaṃ harṣaś ca saṃyuge
rāmasyāstrabalaṃ caiva śatror nidhanakāṅkṣiṇaḥ', null, 6092024),
('ramayana-6-92-25', 25, 'Yuddha Kanda, Sarga 92, Verse 25', 'प्रादुर्बभूवुरस्त्राणि सर्वाणि विदितात्मनः।
प्रहर्षाच्च महातेजाः शीघ्रहस्ततरोऽभवत्॥', 'prādurbabhūvur astrāṇi sarvāṇi viditātmanaḥ
praharṣāc ca mahātejāḥ śīghrahastataro ''bhavat', null, 6092025),
('ramayana-6-92-26', 26, 'Yuddha Kanda, Sarga 92, Verse 26', 'शुभान्येतानि चिह्नानि विज्ञायात्मगतानि सः।
भूय एवार्दयद्रामो रावणं राक्षसान्तकृत्॥', 'śubhāny etāni cihnāni vijñāyātmagatāni saḥ
bhūya evārdayad rāmo rāvaṇaṃ rākṣasāntakṛt', null, 6092026),
('ramayana-6-92-27', 27, 'Yuddha Kanda, Sarga 92, Verse 27', 'हरीणां चाश्मनिकरैः शरवर्षैश्च राघवात्।
हन्यमानो दशग्रीवो विघूर्णहृदयोऽभवत्॥', 'harīṇāṃ cāśmanikaraiḥ śaravarṣaiś ca rāghavāt
hanyamāno daśagrīvo vighūrṇahṛdayo ''bhavat', null, 6092027),
('ramayana-6-92-28', 28, 'Yuddha Kanda, Sarga 92, Verse 28', 'यदा च शस्त्रं नारेभे न व्यकर्षच्छरासनम्।
नास्य प्रत्यकरोद्वीर्यं विक्लवेनान्तरात्मना॥', 'yadā ca śastraṃ nārebhe na vyakarṣac charāsanam
nāsya pratyakarod vīryaṃ viklavenāntarātmanā', null, 6092028),
('ramayana-6-92-29', 29, 'Yuddha Kanda, Sarga 92, Verse 29', 'क्षिप्ताश्चापि शरास्तेन शस्त्राणि विविधानि च।
न रणार्थाय वर्तन्ते मृत्युकालेऽभिवर्ततः॥', 'kṣiptāś cāpi śarās tena śastrāṇi vividhāni ca
na raṇārthāya vartante mṛtyukāle ''bhivartataḥ', null, 6092029),
('ramayana-6-92-30', 30, 'Yuddha Kanda, Sarga 92, Verse 30', 'सूतस्तु रथनेतास्य तदवस्थं निरीक्ष्य तम्।
शनैर्युद्धादसंभान्तो रथं तस्यापवाहयत्॥', 'sūtas tu rathanetāsya tadavasthaṃ nirīkṣya tam
śanair yuddhād asaṃbhānto rathaṃ tasyāpavāhayat', null, 6092030)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 93 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-93-1', 1, 'Yuddha Kanda, Sarga 93, Verse 1', 'स तु मोहात्सुसंक्रुद्धः कृतान्तबलचोदितः।
क्रोधसंरक्तनयनो रावणो सूतमब्रवीत्॥', 'sa tu mohāt susaṃkruddhaḥ kṛtāntabalacoditaḥ
krodhasaṃraktanayano rāvaṇo sūtam abravīt', null, 6093001),
('ramayana-6-93-2', 2, 'Yuddha Kanda, Sarga 93, Verse 2', 'हीनवीर्यमिवाशक्तं पौरुषेण विवर्जितम्।
भीरुं लघुमिवासत्त्वं विहीनमिव तेजसा॥', 'hīnavīryam ivāśaktaṃ pauruṣeṇa vivarjitam
bhīruṃ laghum ivāsattvaṃ vihīnam iva tejasā', null, 6093002),
('ramayana-6-93-3', 3, 'Yuddha Kanda, Sarga 93, Verse 3', 'विमुक्तमिव मायाभिरस्त्रैरिव बहिष्कृतम्।
मामवज्ञाय दुर्बुद्धे स्वया बुद्ध्या विचेष्टसे॥', 'vimuktam iva māyābhir astrair iva bahiṣkṛtam
mām avajñāya durbuddhe svayā buddhyā viceṣṭase', null, 6093003),
('ramayana-6-93-4', 4, 'Yuddha Kanda, Sarga 93, Verse 4', 'किमर्थं मामवज्ञाय मच्छन्दमनवेक्ष्य च।
त्वया शत्रुसमक्षं मे रथोऽयमपवाहितः॥', 'kimarthaṃ mām avajñāya macchandam anavekṣya ca
tvayā śatrusamakṣaṃ me ratho ''yam apavāhitaḥ', null, 6093004),
('ramayana-6-93-5', 5, 'Yuddha Kanda, Sarga 93, Verse 5', 'त्वयाद्य हि ममानार्य चिरकालसमार्जितम्।
यशो वीर्यं च तेजश्च प्रत्ययश्च विनाशितः॥', 'tvayādya hi mamānārya cirakālasamārjitam
yaśo vīryaṃ ca tejaś ca pratyayaś ca vināśitaḥ', null, 6093005),
('ramayana-6-93-6', 6, 'Yuddha Kanda, Sarga 93, Verse 6', 'शत्रोः प्रख्यातवीर्यस्य रञ्जनीयस्य विक्रमैः।
पश्यतो युद्धलुब्धोऽहं कृतः कापुरुषस्त्वया॥', 'śatroḥ prakhyātavīryasya rañjanīyasya vikramaiḥ
paśyato yuddhalubdho ''haṃ kṛtaḥ kāpuruṣas tvayā', null, 6093006),
('ramayana-6-93-7', 7, 'Yuddha Kanda, Sarga 93, Verse 7', 'यस्त्वं रथमिमं मोहान्न चोद्वहसि दुर्मते।
सत्योऽयं प्रतितर्को मे परेण त्वमुपस्कृतः॥', 'yas tvaṃ ratham imaṃ mohān na codvahasi durmate
satyo ''yaṃ pratitarko me pareṇa tvam upaskṛtaḥ', null, 6093007),
('ramayana-6-93-8', 8, 'Yuddha Kanda, Sarga 93, Verse 8', 'न हीदं विद्यते कर्म सुहृदो हितकाङ्क्षिणः।
रिपूणां सदृशं चैतन्न त्वयैतत्स्वनुष्ठितम्॥', 'na hīdaṃ vidyate karma suhṛdo hitakāṅkṣiṇaḥ
ripūṇāṃ sadṛśaṃ caitan na tvayaitat svanuṣṭhitam', null, 6093008),
('ramayana-6-93-9', 9, 'Yuddha Kanda, Sarga 93, Verse 9', 'निवर्तय रथं शीघ्रं यावन्नापैति मे रिपुः।
यदि वाप्युषितोऽसि त्वं स्मर्यन्ते यदि वा गुणाः॥', 'nivartaya rathaṃ śīghraṃ yāvan nāpaiti me ripuḥ
yadi vāpy uṣito ''si tvaṃ smaryante yadi vā guṇāḥ', null, 6093009),
('ramayana-6-93-10', 10, 'Yuddha Kanda, Sarga 93, Verse 10', 'एवं परुषमुक्तस्तु हितबुद्धिरबुद्धिना।
अब्रवीद्रावणं सूतो हितं सानुनयं वचः॥', 'evaṃ paruṣam uktas tu hitabuddhir abuddhinā
abravīd rāvaṇaṃ sūto hitaṃ sānunayaṃ vacaḥ', null, 6093010),
('ramayana-6-93-11', 11, 'Yuddha Kanda, Sarga 93, Verse 11', 'न भीतोऽस्मि न मूढोऽस्मि नोपजप्तोऽस्मि शत्रुभिः।
न प्रमत्तो न निःस्नेहो विस्मृता न च सत्क्रिया॥', 'na bhīto ''smi na mūḍho ''smi nopajapto ''smi śatrubhiḥ
na pramatto na niḥsneho vismṛtā na ca satkriyā', null, 6093011),
('ramayana-6-93-12', 12, 'Yuddha Kanda, Sarga 93, Verse 12', 'मया तु हितकामेन यशश्च परिरक्षता।
स्नेहप्रस्कन्नमनसा प्रियमित्यप्रियं कृतम्॥', 'mayā tu hitakāmena yaśaś ca parirakṣatā
snehapraskannamanasā priyam ity apriyaṃ kṛtam', null, 6093012),
('ramayana-6-93-13', 13, 'Yuddha Kanda, Sarga 93, Verse 13', 'नास्मिन्नर्थे महाराज त्वं मां प्रियहिते रतम्।
कश्चिल्लघुरिवानार्यो दोषतो गन्तुमर्हसि॥', 'nāsminn arthe mahārāja tvaṃ māṃ priyahite ratam
kaś cil laghur ivānāryo doṣato gantum arhasi', null, 6093013),
('ramayana-6-93-14', 14, 'Yuddha Kanda, Sarga 93, Verse 14', 'श्रूयतामभिधास्यामि यन्निमित्तं मया रथः।
नदीवेग इवाम्भोभिः संयुगे विनिवर्तितः॥', 'śrūyatām abhidhāsyāmi yannimittaṃ mayā rathaḥ
nadīvega ivāmbhobhiḥ saṃyuge vinivartitaḥ', null, 6093014),
('ramayana-6-93-15', 15, 'Yuddha Kanda, Sarga 93, Verse 15', 'श्रमं तवावगच्छामि महता रणकर्मणा।
न हि ते वीर सौमुख्यं प्रहर्षं वोपधारये॥', 'śramaṃ tavāvagacchāmi mahatā raṇakarmaṇā
na hi te vīra saumukhyaṃ praharṣaṃ vopadhāraye', null, 6093015),
('ramayana-6-93-16', 16, 'Yuddha Kanda, Sarga 93, Verse 16', 'रथोद्वहनखिन्नाश्च त इमे रथवाजिनः।
दीना घर्मपरिश्रान्ता गावो वर्षहता इव॥', 'rathodvahanakhinnāś ca ta ime rathavājinaḥ
dīnā gharmapariśrāntā gāvo varṣahatā iva', null, 6093016),
('ramayana-6-93-17', 17, 'Yuddha Kanda, Sarga 93, Verse 17', 'निमित्तानि च भूयिष्ठं यानि प्रादुर्भवन्ति नः।
तेषु तेष्वभिपन्नेषु लक्षयाम्यप्रदक्षिणम्॥', 'nimittāni ca bhūyiṣṭhaṃ yāni prādurbhavanti naḥ
teṣu teṣv abhipanneṣu lakṣayāmy apradakṣiṇam', null, 6093017),
('ramayana-6-93-18', 18, 'Yuddha Kanda, Sarga 93, Verse 18', 'देशकालौ च विज्ञेयौ लक्षणानीङ्गितानि च।
दैन्यं हर्षश्च खेदश्च रथिनश्च बलाबलम्॥', 'deśakālau ca vijñeyau lakṣaṇānīṅgitāni ca
dainyaṃ harṣaś ca khedaś ca rathinaś ca balābalam', null, 6093018),
('ramayana-6-93-19', 19, 'Yuddha Kanda, Sarga 93, Verse 19', 'स्थलनिम्नानि भूमेश्च समानि विषमाणि च।
युद्धकालश्च विज्ञेयः परस्यान्तरदर्शनम्॥', 'sthalanimnāni bhūmeś ca samāni viṣamāṇi ca
yuddhakālaś ca vijñeyaḥ parasyāntaradarśanam', null, 6093019),
('ramayana-6-93-20', 20, 'Yuddha Kanda, Sarga 93, Verse 20', 'उपयानापयाने च स्थानं प्रत्यपसर्पणम्।
सर्वमेतद्रथस्थेन ज्ञेयं रथकुटुम्बिना॥', 'upayānāpayāne ca sthānaṃ pratyapasarpaṇam
sarvam etad rathasthena jñeyaṃ rathakuṭumbinā', null, 6093020),
('ramayana-6-93-21', 21, 'Yuddha Kanda, Sarga 93, Verse 21', 'तव विश्रामहेतोस्तु तथैषां रथवाजिनाम्।
रौद्रं वर्जयता खेदं क्षमं कृतमिदं मया॥', 'tava viśrāmahetos tu tathaiṣāṃ rathavājinām
raudraṃ varjayatā khedaṃ kṣamaṃ kṛtam idaṃ mayā', null, 6093021),
('ramayana-6-93-22', 22, 'Yuddha Kanda, Sarga 93, Verse 22', 'न मया स्वेच्छया वीर रथोऽयमपवाहितः।
भर्तृस्नेहपरीतेन मयेदं यत्कृतं विभो॥', 'na mayā svecchayā vīra ratho ''yam apavāhitaḥ
bhartṛsnehaparītena mayedaṃ yatkṛtaṃ vibho', null, 6093022),
('ramayana-6-93-23', 23, 'Yuddha Kanda, Sarga 93, Verse 23', 'आज्ञापय यथातत्त्वं वक्ष्यस्यरिनिषूदन।
तत्करिष्याम्यहं वीरं गतानृण्येन चेतसा॥', 'ājñāpaya yathātattvaṃ vakṣyasy ariniṣūdana
tat kariṣyāmy ahaṃ vīraṃ gatānṛṇyena cetasā', null, 6093023),
('ramayana-6-93-24', 24, 'Yuddha Kanda, Sarga 93, Verse 24', 'संतुष्टस्तेन वाक्येन रावणस्तस्य सारथेः।
प्रशस्यैनं बहुविधं युद्धलुब्धोऽब्रवीदिदम्॥', 'saṃtuṣṭas tena vākyena rāvaṇas tasya sāratheḥ
praśasyainaṃ bahuvidhaṃ yuddhalubdho ''bravīd idam', null, 6093024),
('ramayana-6-93-25', 25, 'Yuddha Kanda, Sarga 93, Verse 25', 'रथं शीघ्रमिमं सूत राघवाभिमुखं कुरु।
नाहत्वा समरे शत्रून्निवर्तिष्यति रावणः॥', 'rathaṃ śīghram imaṃ sūta rāghavābhimukhaṃ kuru
nāhatvā samare śatrūn nivartiṣyati rāvaṇaḥ', null, 6093025),
('ramayana-6-93-26', 26, 'Yuddha Kanda, Sarga 93, Verse 26', 'एवमुक्त्वा ततस्तुष्टो रावणो राक्षसेश्वरः।
ददौ तस्य शुभं ह्येकं हस्ताभरणमुत्तमम्॥', 'evam uktvā tatas tuṣṭo rāvaṇo rākṣaseśvaraḥ
dadau tasya śubhaṃ hy ekaṃ hastābharaṇam uttamam', null, 6093026),
('ramayana-6-93-27', 27, 'Yuddha Kanda, Sarga 93, Verse 27', 'ततो द्रुतं रावणवाक्यचोदितः प्रचोदयामास हयान्स सारथिः।
स राक्षसेन्द्रस्य ततो महारथः क्षणेन रामस्य रणाग्रतोऽभवत्॥', 'tato drutaṃ rāvaṇavākyacoditaḥ pracodayām āsa hayān sa sārathiḥ
sa rākṣasendrasya tato mahārathaḥ kṣaṇena rāmasya raṇāgrato ''bhavat', null, 6093027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 94 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-94-1', 1, 'Yuddha Kanda, Sarga 94, Verse 1', 'तमापतन्तं सहसा स्वनवन्तं महाध्वजम्।
रथं राक्षसराजस्य नरराजो ददर्श ह॥', 'tam āpatantaṃ sahasā svanavantaṃ mahādhvajam
rathaṃ rākṣasarājasya nararājo dadarśa ha', null, 6094001),
('ramayana-6-94-2', 2, 'Yuddha Kanda, Sarga 94, Verse 2', 'कृष्णवाजिसमायुक्तं युक्तं रौद्रेण वर्चसा।
तडित्पताकागहनं दर्शितेन्द्रायुधायुधम्।
शरधारा विमुञ्चन्तं धारासारमिवान्बुदम्॥', 'kṛṣṇavājisamāyuktaṃ yuktaṃ raudreṇa varcasā
taḍitpatākāgahanaṃ darśitendrāyudhāyudham
śaradhārā vimuñcantaṃ dhārāsāram ivānbudam', null, 6094002),
('ramayana-6-94-3', 3, 'Yuddha Kanda, Sarga 94, Verse 3', 'तं दृष्ट्वा मेघसंकाशमापतन्तं रथं रिपोः।
गिरेर्वज्राभिमृष्टस्य दीर्यतः सदृशस्वनम्।
उवाच मातलिं रामः सहस्राक्षस्य सारथिम्॥', 'taṃ dṛṣṭvā meghasaṃkāśam āpatantaṃ rathaṃ ripoḥ
girer vajrābhimṛṣṭasya dīryataḥ sadṛśasvanam
uvāca mātaliṃ rāmaḥ sahasrākṣasya sārathim', null, 6094003),
('ramayana-6-94-4', 4, 'Yuddha Kanda, Sarga 94, Verse 4', 'मातले पश्य संरब्धमापतन्तं रथं रिपोः।
यथापसव्यं पतता वेगेन महता पुनः।
समरे हन्तुमात्मानं तथानेन कृता मतिः॥', 'mātale paśya saṃrabdham āpatantaṃ rathaṃ ripoḥ
yathāpasavyaṃ patatā vegena mahatā punaḥ
samare hantum ātmānaṃ tathānena kṛtā matiḥ', null, 6094004),
('ramayana-6-94-5', 5, 'Yuddha Kanda, Sarga 94, Verse 5', 'तदप्रमादमातिष्ठ प्रत्युद्गच्छ रथं रिपोः।
विध्वंसयितुमिच्छामि वायुर्मेघमिवोत्थितम्॥', 'tad apramādam ātiṣṭha pratyudgaccha rathaṃ ripoḥ
vidhvaṃsayitum icchāmi vāyur megham ivotthitam', null, 6094005),
('ramayana-6-94-6', 6, 'Yuddha Kanda, Sarga 94, Verse 6', 'अविक्लवमसंभ्रान्तमव्यग्रहृदयेक्षणम्।
रश्मिसंचारनियतं प्रचोदय रथं द्रुतम्॥', 'aviklavam asaṃbhrāntam avyagrahṛdayekṣaṇam
raśmisaṃcāraniyataṃ pracodaya rathaṃ drutam', null, 6094006),
('ramayana-6-94-7', 7, 'Yuddha Kanda, Sarga 94, Verse 7', 'कामं न त्वं समाधेयः पुरंदररथोचितः।
युयुत्सुरहमेकाग्रः स्मारये त्वां न शिक्षये॥', 'kāmaṃ na tvaṃ samādheyaḥ puraṃdararathocitaḥ
yuyutsur aham ekāgraḥ smāraye tvāṃ na śikṣaye', null, 6094007),
('ramayana-6-94-8', 8, 'Yuddha Kanda, Sarga 94, Verse 8', 'परितुष्टः स रामस्य तेन वाक्येन मातलिः।
प्रचोदयामास रथं सुरसारथिसत्तमः॥', 'parituṣṭaḥ sa rāmasya tena vākyena mātaliḥ
pracodayām āsa rathaṃ surasārathisattamaḥ', null, 6094008),
('ramayana-6-94-9', 9, 'Yuddha Kanda, Sarga 94, Verse 9', 'अपसव्यं ततः कुर्वन्रावणस्य महारथम्।
चक्रोत्क्षिप्तेन रजसा रावणं व्यवधूनयत्॥', 'apasavyaṃ tataḥ kurvan rāvaṇasya mahāratham
cakrotkṣiptena rajasā rāvaṇaṃ vyavadhūnayat', null, 6094009),
('ramayana-6-94-10', 10, 'Yuddha Kanda, Sarga 94, Verse 10', 'ततः क्रुद्धो दशग्रीवस्ताम्रविस्फारितेक्षणः।
रथप्रतिमुखं रामं सायकैरवधूनयत्॥', 'tataḥ kruddho daśagrīvas tāmravisphāritekṣaṇaḥ
rathapratimukhaṃ rāmaṃ sāyakair avadhūnayat', null, 6094010),
('ramayana-6-94-11', 11, 'Yuddha Kanda, Sarga 94, Verse 11', 'धर्षणामर्षितो रामो धैर्यं रोषेण लङ्घयन्।
जग्राह सुमहावेगमैन्द्रं युधि शरासनम्।
शरांश्च सुमहातेजाः सूर्यरश्मिसमप्रभान्॥', 'dharṣaṇāmarṣito rāmo dhairyaṃ roṣeṇa laṅghayan
jagrāha sumahāvegam aindraṃ yudhi śarāsanam
śarāṃś ca sumahātejāḥ sūryaraśmisamaprabhān', null, 6094011),
('ramayana-6-94-12', 12, 'Yuddha Kanda, Sarga 94, Verse 12', 'तदुपोढं महद्युद्धमन्योन्यवधकाङ्क्षिणोः।
परस्पराभिमुखयोर्दृप्तयोरिव सिंहयोः॥', 'tad upoḍhaṃ mahad yuddham anyonyavadhakāṅkṣiṇoḥ
parasparābhimukhayor dṛptayor iva siṃhayoḥ', null, 6094012),
('ramayana-6-94-13', 13, 'Yuddha Kanda, Sarga 94, Verse 13', 'ततो देवाः सगन्धर्वाः सिद्धाश्च परमर्षयः।
समीयुर्द्वैरथं द्रष्टुं रावणक्षयकाङ्क्षिणः॥', 'tato devāḥ sagandharvāḥ siddhāś ca paramarṣayaḥ
samīyur dvairathaṃ draṣṭuṃ rāvaṇakṣayakāṅkṣiṇaḥ', null, 6094013),
('ramayana-6-94-14', 14, 'Yuddha Kanda, Sarga 94, Verse 14', 'समुत्पेतुरथोत्पाता दारुणा लोमहर्षणाः।
रावणस्य विनाशाय राघवस्य जयाय च॥', 'samutpetur athotpātā dāruṇā lomaharṣaṇāḥ
rāvaṇasya vināśāya rāghavasya jayāya ca', null, 6094014),
('ramayana-6-94-15', 15, 'Yuddha Kanda, Sarga 94, Verse 15', 'ववर्ष रुधिरं देवो रावणस्य रथोपरि।
वाता मण्डलिनस्तीव्रा अपसव्यं प्रचक्रमुः॥', 'vavarṣa rudhiraṃ devo rāvaṇasya rathopari
vātā maṇḍalinas tīvrā apasavyaṃ pracakramuḥ', null, 6094015),
('ramayana-6-94-16', 16, 'Yuddha Kanda, Sarga 94, Verse 16', 'महद्गृध्रकुलं चास्य भ्रममाणं नभस्तले।
येन येन रथो याति तेन तेन प्रधावति॥', 'mahad gṛdhrakulaṃ cāsya bhramamāṇaṃ nabhastale
yena yena ratho yāti tena tena pradhāvati', null, 6094016),
('ramayana-6-94-17', 17, 'Yuddha Kanda, Sarga 94, Verse 17', 'संध्यया चावृता लङ्का जपापुष्पनिकाशया।
दृश्यते संप्रदीतेव दिवसेऽपि वसुंधरा॥', 'saṃdhyayā cāvṛtā laṅkā japāpuṣpanikāśayā
dṛśyate saṃpradīteva divase ''pi vasuṃdharā', null, 6094017),
('ramayana-6-94-18', 18, 'Yuddha Kanda, Sarga 94, Verse 18', 'सनिर्घाता महोल्काश्च संप्रचेतुर्महास्वनाः।
विषादयन्त्यो रक्षांसि रावणस्य तदाहिताः॥', 'sanirghātā maholkāś ca saṃpracetur mahāsvanāḥ
viṣādayantyo rakṣāṃsi rāvaṇasya tadāhitāḥ', null, 6094018),
('ramayana-6-94-19', 19, 'Yuddha Kanda, Sarga 94, Verse 19', 'रावणश्च यतस्तत्र प्रचचाल वसुंधरा।
रक्षसां च प्रहरतां गृहीता इव बाहवः॥', 'rāvaṇaś ca yatas tatra pracacāla vasuṃdharā
rakṣasāṃ ca praharatāṃ gṛhītā iva bāhavaḥ', null, 6094019),
('ramayana-6-94-20', 20, 'Yuddha Kanda, Sarga 94, Verse 20', 'ताम्राः पीताः सिताः श्वेताः पतिताः सूर्यरश्मयः।
दृश्यन्ते रावणस्याङ्गे पर्वतस्येव धातवः॥', 'tāmrāḥ pītāḥ sitāḥ śvetāḥ patitāḥ sūryaraśmayaḥ
dṛśyante rāvaṇasyāṅge parvatasyeva dhātavaḥ', null, 6094020),
('ramayana-6-94-21', 21, 'Yuddha Kanda, Sarga 94, Verse 21', 'गृध्रैरनुगताश्चास्य वमन्त्यो ज्वलनं मुखैः।
प्रणेदुर्मुखमीक्षन्त्यः संरब्धमशिवं शिवाः॥', 'gṛdhrair anugatāś cāsya vamantyo jvalanaṃ mukhaiḥ
praṇedur mukham īkṣantyaḥ saṃrabdham aśivaṃ śivāḥ', null, 6094021),
('ramayana-6-94-22', 22, 'Yuddha Kanda, Sarga 94, Verse 22', 'प्रतिकूलं ववौ वायू रणे पांसून्समुत्किरन्।
तस्य राक्षसराजस्य कुर्वन्दृष्टिविलोपनम्॥', 'pratikūlaṃ vavau vāyū raṇe pāṃsūn samutkiran
tasya rākṣasarājasya kurvan dṛṣṭivilopanam', null, 6094022),
('ramayana-6-94-23', 23, 'Yuddha Kanda, Sarga 94, Verse 23', 'निपेतुरिन्द्राशनयः सैन्ये चास्य समन्ततः।
दुर्विषह्य स्वना घोरा विना जलधरस्वनम्॥', 'nipetur indrāśanayaḥ sainye cāsya samantataḥ
durviṣahya svanā ghorā vinā jaladharasvanam', null, 6094023),
('ramayana-6-94-24', 24, 'Yuddha Kanda, Sarga 94, Verse 24', 'दिशश्च प्रदिशः सर्वा बभूवुस्तिमिरावृताः।
पांसुवर्षेण महता दुर्दर्शं च नभोऽभवत्॥', 'diśaś ca pradiśaḥ sarvā babhūvus timirāvṛtāḥ
pāṃsuvarṣeṇa mahatā durdarśaṃ ca nabho ''bhavat', null, 6094024),
('ramayana-6-94-25', 25, 'Yuddha Kanda, Sarga 94, Verse 25', 'कुर्वन्त्यः कलहं घोरं सारिकास्तद्रथं प्रति।
निपेतुः शतशस्तत्र दारुणा दारुणस्वनाः॥', 'kurvantyaḥ kalahaṃ ghoraṃ sārikās tadrathaṃ prati
nipetuḥ śataśas tatra dāruṇā dāruṇasvanāḥ', null, 6094025),
('ramayana-6-94-26', 26, 'Yuddha Kanda, Sarga 94, Verse 26', 'जघनेभ्यः स्फुलिङ्गांश्च नेत्रेभ्योऽश्रूणि संततम्।
मुमुचुस्तस्य तुरगास्तुल्यमग्निं च वारि च॥', 'jaghanebhyaḥ sphuliṅgāṃś ca netrebhyo ''śrūṇi saṃtatam
mumucus tasya turagās tulyam agniṃ ca vāri ca', null, 6094026),
('ramayana-6-94-27', 27, 'Yuddha Kanda, Sarga 94, Verse 27', 'एवं प्रकारा बहवः समुत्पाता भयावहाः।
रावणस्य विनाशाय दारुणाः संप्रजज्ञिरे॥', 'evaṃ prakārā bahavaḥ samutpātā bhayāvahāḥ
rāvaṇasya vināśāya dāruṇāḥ saṃprajajñire', null, 6094027),
('ramayana-6-94-28', 28, 'Yuddha Kanda, Sarga 94, Verse 28', 'रामस्यापि निमित्तानि सौम्यानि च शिवानि च।
बभूवुर्जयशंसीनि प्रादुर्भूतानि सर्वशः॥', 'rāmasyāpi nimittāni saumyāni ca śivāni ca
babhūvur jayaśaṃsīni prādurbhūtāni sarvaśaḥ', null, 6094028),
('ramayana-6-94-29', 29, 'Yuddha Kanda, Sarga 94, Verse 29', 'ततो निरीक्ष्यात्मगतानि राघवो रणे निमित्तानि निमित्तकोविदः।
जगाम हर्षं च परां च निर्वृतिं चकार युद्धेऽभ्यधिकं च विक्रमम्॥', 'tato nirīkṣyātmagatāni rāghavo raṇe nimittāni nimittakovidaḥ
jagāma harṣaṃ ca parāṃ ca nirvṛtiṃ cakāra yuddhe ''bhyadhikaṃ ca vikramam', null, 6094029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 95 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-95-1', 1, 'Yuddha Kanda, Sarga 95, Verse 1', 'ततः प्रवृत्तं सुक्रूरं रामरावणयोस्तदा।
सुमहद्द्वैरथं युद्धं सर्वलोकभयावहम्॥', 'tataḥ pravṛttaṃ sukrūraṃ rāmarāvaṇayos tadā
sumahad dvairathaṃ yuddhaṃ sarvalokabhayāvaham', null, 6095001),
('ramayana-6-95-2', 2, 'Yuddha Kanda, Sarga 95, Verse 2', 'ततो राक्षससैन्यं च हरीणां च महद्बलम्।
प्रगृहीतप्रहरणं निश्चेष्टं समतिष्ठत॥', 'tato rākṣasasainyaṃ ca harīṇāṃ ca mahad balam
pragṛhītapraharaṇaṃ niśceṣṭaṃ samatiṣṭhata', null, 6095002),
('ramayana-6-95-3', 3, 'Yuddha Kanda, Sarga 95, Verse 3', 'संप्रयुद्धौ ततो दृष्ट्वा बलवन्नरराक्षसौ।
व्याक्षिप्तहृदयाः सर्वे परं विस्मयमागताः॥', 'saṃprayuddhau tato dṛṣṭvā balavan nararākṣasau
vyākṣiptahṛdayāḥ sarve paraṃ vismayam āgatāḥ', null, 6095003),
('ramayana-6-95-4', 4, 'Yuddha Kanda, Sarga 95, Verse 4', 'नानाप्रहरणैर्व्यग्रैर्भुजैर्विस्मितबुद्धयः।
तस्थुः प्रेक्ष्य च संग्रामं नाभिजघ्नुः परस्परम्॥', 'nānāpraharaṇair vyagrair bhujair vismitabuddhayaḥ
tasthuḥ prekṣya ca saṃgrāmaṃ nābhijaghnuḥ parasparam', null, 6095004),
('ramayana-6-95-5', 5, 'Yuddha Kanda, Sarga 95, Verse 5', 'रक्षसां रावणं चापि वानराणां च राघवम्।
पश्यतां विस्मिताक्षाणां सैन्यं चित्रमिवाबभौ॥', 'rakṣasāṃ rāvaṇaṃ cāpi vānarāṇāṃ ca rāghavam
paśyatāṃ vismitākṣāṇāṃ sainyaṃ citram ivābabhau', null, 6095005),
('ramayana-6-95-6', 6, 'Yuddha Kanda, Sarga 95, Verse 6', 'तौ तु तत्र निमित्तानि दृष्ट्वा राघवरावणौ।
कृतबुद्धी स्थिरामर्षौ युयुधाते अभीतवत्॥', 'tau tu tatra nimittāni dṛṣṭvā rāghavarāvaṇau
kṛtabuddhī sthirāmarṣau yuyudhāte abhītavat', null, 6095006),
('ramayana-6-95-7', 7, 'Yuddha Kanda, Sarga 95, Verse 7', 'जेतव्यमिति काकुत्स्थो मर्तव्यमिति रावणः।
धृतौ स्ववीर्यसर्वस्वं युद्धेऽदर्शयतां तदा॥', 'jetavyam iti kākutstho martavyam iti rāvaṇaḥ
dhṛtau svavīryasarvasvaṃ yuddhe ''darśayatāṃ tadā', null, 6095007),
('ramayana-6-95-8', 8, 'Yuddha Kanda, Sarga 95, Verse 8', 'ततः क्रोधाद्दशग्रीवः शरान्संधाय वीर्यवान्।
मुमोच ध्वजमुद्दिश्य राघवस्य रथे स्थितम्॥', 'tataḥ krodhād daśagrīvaḥ śarān saṃdhāya vīryavān
mumoca dhvajam uddiśya rāghavasya rathe sthitam', null, 6095008),
('ramayana-6-95-9', 9, 'Yuddha Kanda, Sarga 95, Verse 9', 'ते शरास्तमनासाद्य पुरंदररथध्वजम्।
रक्तशक्तिं परामृश्य निपेतुर्धरणीतले॥', 'te śarās tam anāsādya puraṃdararathadhvajam
raktaśaktiṃ parāmṛśya nipetur dharaṇītale', null, 6095009),
('ramayana-6-95-10', 10, 'Yuddha Kanda, Sarga 95, Verse 10', 'ततो रामोऽभिसंक्रुद्धश्चापमायम्य वीर्यवान्।
कृतप्रतिकृतं कर्तुं मनसा संप्रचक्रमे॥', 'tato rāmo ''bhisaṃkruddhaś cāpam āyamya vīryavān
kṛtapratikṛtaṃ kartuṃ manasā saṃpracakrame', null, 6095010),
('ramayana-6-95-11', 11, 'Yuddha Kanda, Sarga 95, Verse 11', 'रावणध्वजमुद्दिश्य मुमोच निशितं शरम्।
महासर्पमिवासह्यं ज्वलन्तं स्वेन तेजसा॥', 'rāvaṇadhvajam uddiśya mumoca niśitaṃ śaram
mahāsarpam ivāsahyaṃ jvalantaṃ svena tejasā', null, 6095011),
('ramayana-6-95-12', 12, 'Yuddha Kanda, Sarga 95, Verse 12', 'जगाम स महीं भित्त्वा दशग्रीवध्वजं शरः।
स निकृत्तोऽपतद्भूमौ रावणस्य रथध्वजः॥', 'jagāma sa mahīṃ bhittvā daśagrīvadhvajaṃ śaraḥ
sa nikṛtto ''patad bhūmau rāvaṇasya rathadhvajaḥ', null, 6095012),
('ramayana-6-95-13', 13, 'Yuddha Kanda, Sarga 95, Verse 13', 'ध्वजस्योन्मथनं दृष्ट्वा रावणः सुमहाबलः।
क्रोधजेनाग्निना संख्ये प्रदीप्त इव चाभवत्॥', 'dhvajasyonmathanaṃ dṛṣṭvā rāvaṇaḥ sumahābalaḥ
krodhajenāgninā saṃkhye pradīpta iva cābhavat', null, 6095013),
('ramayana-6-95-14', 14, 'Yuddha Kanda, Sarga 95, Verse 14', 'स रोषवशमापन्नः शरवर्षं महद्वमन्।
रामस्य तुरगान्दिव्याञ्शरैर्विव्याध रावणः॥', 'sa roṣavaśam āpannaḥ śaravarṣaṃ mahad vaman
rāmasya turagān divyāñ śarair vivyādha rāvaṇaḥ', null, 6095014),
('ramayana-6-95-15', 15, 'Yuddha Kanda, Sarga 95, Verse 15', 'ते विद्धा हरयस्तस्य नास्खलन्नापि बभ्रमुः।
बभूवुः स्वस्थहृदयाः पद्मनालैरिवाहताः॥', 'te viddhā harayas tasya nāskhalan nāpi babhramuḥ
babhūvuḥ svasthahṛdayāḥ padmanālair ivāhatāḥ', null, 6095015),
('ramayana-6-95-16', 16, 'Yuddha Kanda, Sarga 95, Verse 16', 'तेषामसंभ्रमं दृष्ट्वा वाजिनां रावणस्तदा।
भूय एव सुसंक्रुद्धः शरवर्षं मुमोच ह॥', 'teṣām asaṃbhramaṃ dṛṣṭvā vājināṃ rāvaṇas tadā
bhūya eva susaṃkruddhaḥ śaravarṣaṃ mumoca ha', null, 6095016),
('ramayana-6-95-17', 17, 'Yuddha Kanda, Sarga 95, Verse 17', 'गदाश्च परिघांश्चैव चक्राणि मुसलानि च।
गिरिशृङ्गाणि वृक्षांश्च तथा शूलपरश्वधान्॥', 'gadāś ca parighāṃś caiva cakrāṇi musalāni ca
giriśṛṅgāṇi vṛkṣāṃś ca tathā śūlaparaśvadhān', null, 6095017),
('ramayana-6-95-18', 18, 'Yuddha Kanda, Sarga 95, Verse 18', 'मायाविहितमेतत्तु शस्त्रवर्षमपातयत्।
सहस्रशस्ततो बाणानश्रान्तहृदयोद्यमः॥', 'māyāvihitam etat tu śastravarṣam apātayat
sahasraśas tato bāṇān aśrāntahṛdayodyamaḥ', null, 6095018),
('ramayana-6-95-19', 19, 'Yuddha Kanda, Sarga 95, Verse 19', 'तुमुलं त्रासजननं भीमं भीमप्रतिस्वनम्।
दुर्धर्षमभवद्युद्धे नैकशस्त्रमयं महत्॥', 'tumulaṃ trāsajananaṃ bhīmaṃ bhīmapratisvanam
durdharṣam abhavad yuddhe naikaśastramayaṃ mahat', null, 6095019),
('ramayana-6-95-20', 20, 'Yuddha Kanda, Sarga 95, Verse 20', 'विमुच्य राघवरथं समन्ताद्वानरे बले।
सायकैरन्तरिक्षं च चकाराशु निरन्तरम्।
मुमोच च दशग्रीवो निःसङ्गेनान्तरात्मना॥', 'vimucya rāghavarathaṃ samantād vānare bale
sāyakair antarikṣaṃ ca cakārāśu nirantaram
mumoca ca daśagrīvo niḥsaṅgenāntarātmanā', null, 6095020),
('ramayana-6-95-21', 21, 'Yuddha Kanda, Sarga 95, Verse 21', 'व्यायच्छमानं तं दृष्ट्वा तत्परं रावणं रणे।
प्रहसन्निव काकुत्स्थः संदधे सायकाञ्शितान्॥', 'vyāyacchamānaṃ taṃ dṛṣṭvā tatparaṃ rāvaṇaṃ raṇe
prahasann iva kākutsthaḥ saṃdadhe sāyakāñ śitān', null, 6095021),
('ramayana-6-95-22', 22, 'Yuddha Kanda, Sarga 95, Verse 22', 'स मुमोच ततो बाणान्रणे शतसहस्रशः।
तान्दृष्ट्वा रावणश्चक्रे स्वशरैः खं निरन्तरम्॥', 'sa mumoca tato bāṇān raṇe śatasahasraśaḥ
tān dṛṣṭvā rāvaṇaś cakre svaśaraiḥ khaṃ nirantaram', null, 6095022),
('ramayana-6-95-23', 23, 'Yuddha Kanda, Sarga 95, Verse 23', 'ततस्ताभ्यां प्रयुक्तेन शरवर्षेण भास्वता।
शरबद्धमिवाभाति द्वितीयं भास्वदम्बरम्॥', 'tatas tābhyāṃ prayuktena śaravarṣeṇa bhāsvatā
śarabaddham ivābhāti dvitīyaṃ bhāsvad ambaram', null, 6095023),
('ramayana-6-95-24', 24, 'Yuddha Kanda, Sarga 95, Verse 24', 'नानिमित्तोऽभवद्बाणो नातिभेत्ता न निष्फलः।
तथा विसृजतोर्बाणान्रामरावणयोर्मृधे॥', 'nānimitto ''bhavad bāṇo nātibhettā na niṣphalaḥ
tathā visṛjator bāṇān rāmarāvaṇayor mṛdhe', null, 6095024),
('ramayana-6-95-25', 25, 'Yuddha Kanda, Sarga 95, Verse 25', 'प्रायुध्येतामविच्छिन्नमस्यन्तौ सव्यदक्षिणम्।
चक्रतुस्तौ शरौघैस्तु निरुच्छ्वासमिवाम्बरम्॥', 'prāyudhyetām avicchinnam asyantau savyadakṣiṇam
cakratus tau śaraughais tu nirucchvāsam ivāmbaram', null, 6095025),
('ramayana-6-95-26', 26, 'Yuddha Kanda, Sarga 95, Verse 26', 'रावणस्य हयान्रामो हयान्रामस्य रावणः।
जघ्नतुस्तौ तदान्योन्यं कृतानुकृतकारिणौ॥', 'rāvaṇasya hayān rāmo hayān rāmasya rāvaṇaḥ
jaghnatus tau tadānyonyaṃ kṛtānukṛtakāriṇau', null, 6095026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 96 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-96-1', 1, 'Yuddha Kanda, Sarga 96, Verse 1', 'तौ तथा युध्यमानौ तु समरे रामरावणौ।
ददृशुः सर्वभूतानि विस्मितेनान्तरात्मना॥', 'tau tathā yudhyamānau tu samare rāmarāvaṇau
dadṛśuḥ sarvabhūtāni vismitenāntarātmanā', null, 6096001),
('ramayana-6-96-2', 2, 'Yuddha Kanda, Sarga 96, Verse 2', 'अर्दयन्तौ तु समरे तयोस्तौ स्यन्दनोत्तमौ।
परस्परवधे युक्तौ घोररूपौ बभूवतुः॥', 'ardayantau tu samare tayos tau syandanottamau
parasparavadhe yuktau ghorarūpau babhūvatuḥ', null, 6096002),
('ramayana-6-96-3', 3, 'Yuddha Kanda, Sarga 96, Verse 3', 'मण्डलानि च वीथीश्च गतप्रत्यागतानि च।
दर्शयन्तौ बहुविधां सूतौ सारथ्यजां गतिम्॥', 'maṇḍalāni ca vīthīś ca gatapratyāgatāni ca
darśayantau bahuvidhāṃ sūtau sārathyajāṃ gatim', null, 6096003),
('ramayana-6-96-4', 4, 'Yuddha Kanda, Sarga 96, Verse 4', 'अर्दयन्रावणं रामो राघवं चापि रावणः।
गतिवेगं समापन्नौ प्रवर्तन निवर्तने॥', 'ardayan rāvaṇaṃ rāmo rāghavaṃ cāpi rāvaṇaḥ
gativegaṃ samāpannau pravartana nivartane', null, 6096004),
('ramayana-6-96-5', 5, 'Yuddha Kanda, Sarga 96, Verse 5', 'क्षिपतोः शरजालानि तयोस्तौ स्यन्दनोत्तमौ।
चेरतुः संयुगमहीं सासारौ जलदाविव॥', 'kṣipatoḥ śarajālāni tayos tau syandanottamau
ceratuḥ saṃyugamahīṃ sāsārau jaladāv iva', null, 6096005),
('ramayana-6-96-6', 6, 'Yuddha Kanda, Sarga 96, Verse 6', 'दर्शयित्वा तदा तौ तु गतिं बहुविधां रणे।
परस्परस्याभिमुखौ पुनरेव च तस्थतुः॥', 'darśayitvā tadā tau tu gatiṃ bahuvidhāṃ raṇe
parasparasyābhimukhau punar eva ca tasthatuḥ', null, 6096006),
('ramayana-6-96-7', 7, 'Yuddha Kanda, Sarga 96, Verse 7', 'धुरं धुरेण रथयोर्वक्त्रं वक्त्रेण वाजिनाम्।
पताकाश्च पताकाभिः समेयुः स्थितयोस्तदा॥', 'dhuraṃ dhureṇa rathayor vaktraṃ vaktreṇa vājinām
patākāś ca patākābhiḥ sameyuḥ sthitayos tadā', null, 6096007),
('ramayana-6-96-8', 8, 'Yuddha Kanda, Sarga 96, Verse 8', 'रावणस्य ततो रामो धनुर्मुक्तैः शितैः शरैः।
चतुर्भिश्चतुरो दीप्तान्हयान्प्रत्यपसर्पयत्॥', 'rāvaṇasya tato rāmo dhanurmuktaiḥ śitaiḥ śaraiḥ
caturbhiś caturo dīptān hayān pratyapasarpayat', null, 6096008),
('ramayana-6-96-9', 9, 'Yuddha Kanda, Sarga 96, Verse 9', 'स क्रोधवशमापन्नो हयानामपसर्पणे।
मुमोच निशितान्बाणान्राघवाय निशाचरः॥', 'sa krodhavaśam āpanno hayānām apasarpaṇe
mumoca niśitān bāṇān rāghavāya niśācaraḥ', null, 6096009),
('ramayana-6-96-10', 10, 'Yuddha Kanda, Sarga 96, Verse 10', 'सोऽतिविद्धो बलवता दशग्रीवेण राघवः।
जगाम न विकारं च न चापि व्यथितोऽभवत्॥', 'so ''tividdho balavatā daśagrīveṇa rāghavaḥ
jagāma na vikāraṃ ca na cāpi vyathito ''bhavat', null, 6096010),
('ramayana-6-96-11', 11, 'Yuddha Kanda, Sarga 96, Verse 11', 'चिक्षेप च पुनर्बाणान्वज्रपातसमस्वनान्।
सारथिं वज्रहस्तस्य समुद्दिश्य निशाचरः॥', 'cikṣepa ca punar bāṇān vajrapātasamasvanān
sārathiṃ vajrahastasya samuddiśya niśācaraḥ', null, 6096011),
('ramayana-6-96-12', 12, 'Yuddha Kanda, Sarga 96, Verse 12', 'मातलेस्तु महावेगाः शरीरे पतिताः शराः।
न सूक्ष्ममपि संमोहं व्यथां वा प्रददुर्युधि॥', 'mātales tu mahāvegāḥ śarīre patitāḥ śarāḥ
na sūkṣmam api saṃmohaṃ vyathāṃ vā pradadur yudhi', null, 6096012),
('ramayana-6-96-13', 13, 'Yuddha Kanda, Sarga 96, Verse 13', 'तया धर्षणया क्रोद्धो मातलेर्न तथात्मनः।
चकार शरजालेन राघवो विमुखं रिपुम्॥', 'tayā dharṣaṇayā kroddho mātaler na tathātmanaḥ
cakāra śarajālena rāghavo vimukhaṃ ripum', null, 6096013),
('ramayana-6-96-14', 14, 'Yuddha Kanda, Sarga 96, Verse 14', 'विंशतिं त्रिंशतं षष्टिं शतशोऽथ सहस्रशः।
मुमोच राघवो वीरः सायकान्स्यन्दने रिपोः॥', 'viṃśatiṃ triṃśataṃ ṣaṣṭiṃ śataśo ''tha sahasraśaḥ
mumoca rāghavo vīraḥ sāyakān syandane ripoḥ', null, 6096014),
('ramayana-6-96-15', 15, 'Yuddha Kanda, Sarga 96, Verse 15', 'गदानां मुसलानां च परिघाणां च निस्वनैः।
शराणां पुङ्खवातैश्च क्षुभिताः सप्तसागराः॥', 'gadānāṃ musalānāṃ ca parighāṇāṃ ca nisvanaiḥ
śarāṇāṃ puṅkhavātaiś ca kṣubhitāḥ saptasāgarāḥ', null, 6096015),
('ramayana-6-96-16', 16, 'Yuddha Kanda, Sarga 96, Verse 16', 'क्षुब्धानां सागराणां च पातालतलवासिनः।
व्यथिताः पन्नगाः सर्वे दानवाश्च सहस्रशः॥', 'kṣubdhānāṃ sāgarāṇāṃ ca pātālatalavāsinaḥ
vyathitāḥ pannagāḥ sarve dānavāś ca sahasraśaḥ', null, 6096016),
('ramayana-6-96-17', 17, 'Yuddha Kanda, Sarga 96, Verse 17', 'चकम्पे मेदिनी कृत्स्ना सशैलवनकानना।
भास्करो निष्प्रभश्चाभून्न ववौ चापि मारुतः॥', 'cakampe medinī kṛtsnā saśailavanakānanā
bhāskaro niṣprabhaś cābhūn na vavau cāpi mārutaḥ', null, 6096017),
('ramayana-6-96-18', 18, 'Yuddha Kanda, Sarga 96, Verse 18', 'ततो देवाः सगन्धर्वाः सिद्धाश्च परमर्षयः।
चिन्तामापेदिरे सर्वे सकिंनरमहोरगाः॥', 'tato devāḥ sagandharvāḥ siddhāś ca paramarṣayaḥ
cintām āpedire sarve sakiṃnaramahoragāḥ', null, 6096018),
('ramayana-6-96-19', 19, 'Yuddha Kanda, Sarga 96, Verse 19', 'स्वस्ति गोब्राह्मणेभ्योऽस्तु लोकास्तिष्ठन्तु शाश्वताः।
जयतां राघवः संख्ये रावणं राक्षसेश्वरम्॥', 'svasti gobrāhmaṇebhyo ''stu lokās tiṣṭhantu śāśvatāḥ
jayatāṃ rāghavaḥ saṃkhye rāvaṇaṃ rākṣaseśvaram', null, 6096019),
('ramayana-6-96-20', 20, 'Yuddha Kanda, Sarga 96, Verse 20', 'ततः क्रुद्धो महाबाहू रघूणां कीर्तिवर्धनः।
संधाय धनुषा रामः क्षुरमाशीविषोपमम्।
रावणस्य शिरोऽच्छिन्दच्छ्रीमज्ज्वलितकुण्डलम्॥', 'tataḥ kruddho mahābāhū raghūṇāṃ kīrtivardhanaḥ
saṃdhāya dhanuṣā rāmaḥ kṣuram āśīviṣopamam
rāvaṇasya śiro ''cchindac chrīmaj jvalitakuṇḍalam', null, 6096020),
('ramayana-6-96-21', 21, 'Yuddha Kanda, Sarga 96, Verse 21', 'तच्छिरः पतितं भूमौ दृष्टं लोकैस्त्रिभिस्तदा।
तस्यैव सदृशं चान्यद्रावणस्योत्थितं शिरः॥', 'tac chiraḥ patitaṃ bhūmau dṛṣṭaṃ lokais tribhis tadā
tasyaiva sadṛśaṃ cānyad rāvaṇasyotthitaṃ śiraḥ', null, 6096021),
('ramayana-6-96-22', 22, 'Yuddha Kanda, Sarga 96, Verse 22', 'तत्क्षिप्रं क्षिप्रहस्तेन रामेण क्षिप्रकारिणा।
द्वितीयं रावणशिरश्छिन्नं संयति सायकैः॥', 'tat kṣipraṃ kṣiprahastena rāmeṇa kṣiprakāriṇā
dvitīyaṃ rāvaṇaśiraś chinnaṃ saṃyati sāyakaiḥ', null, 6096022),
('ramayana-6-96-23', 23, 'Yuddha Kanda, Sarga 96, Verse 23', 'छिन्नमात्रं च तच्छीर्षं पुनरन्यत्स्म दृश्यते।
तदप्यशनिसंकाशैश्छिन्नं रामेण सायकैः॥', 'chinnamātraṃ ca tac chīrṣaṃ punar anyat sma dṛśyate
tad apy aśanisaṃkāśaiś chinnaṃ rāmeṇa sāyakaiḥ', null, 6096023),
('ramayana-6-96-24', 24, 'Yuddha Kanda, Sarga 96, Verse 24', 'एवमेव शतं छिन्नं शिरसां तुल्यवर्चसाम्।
न चैव रावणस्यान्तो दृश्यते जीवितक्षये॥', 'evam eva śataṃ chinnaṃ śirasāṃ tulyavarcasām
na caiva rāvaṇasyānto dṛśyate jīvitakṣaye', null, 6096024),
('ramayana-6-96-25', 25, 'Yuddha Kanda, Sarga 96, Verse 25', 'ततः सर्वास्त्रविद्वीरः कौसल्यानन्दिवर्धनः।
मार्गणैर्बहुभिर्युक्तश्चिन्तयामास राघवः॥', 'tataḥ sarvāstravid vīraḥ kausalyānandivardhanaḥ
mārgaṇair bahubhir yuktaś cintayām āsa rāghavaḥ', null, 6096025),
('ramayana-6-96-26', 26, 'Yuddha Kanda, Sarga 96, Verse 26', 'मारीचो निहतो यैस्तु खरो यैस्तु सुदूषणः।
क्रञ्चारण्ये विराधस्तु कबन्धो दण्डका वने॥', 'mārīco nihato yais tu kharo yais tu sudūṣaṇaḥ
krañcāraṇye virādhas tu kabandho daṇḍakā vane', null, 6096026),
('ramayana-6-96-27', 27, 'Yuddha Kanda, Sarga 96, Verse 27', 'त इमे सायकाः सर्वे युद्धे प्रत्ययिका मम।
किं नु तत्कारणं येन रावणे मन्दतेजसः॥', 'ta ime sāyakāḥ sarve yuddhe pratyayikā mama
kiṃ nu tat kāraṇaṃ yena rāvaṇe mandatejasaḥ', null, 6096027),
('ramayana-6-96-28', 28, 'Yuddha Kanda, Sarga 96, Verse 28', 'इति चिन्तापरश्चासीदप्रमत्तश्च संयुगे।
ववर्ष शरवर्षाणि राघवो रावणोरसि॥', 'iti cintāparaś cāsīd apramattaś ca saṃyuge
vavarṣa śaravarṣāṇi rāghavo rāvaṇorasi', null, 6096028),
('ramayana-6-96-29', 29, 'Yuddha Kanda, Sarga 96, Verse 29', 'रावणोऽपि ततः क्रुद्धो रथस्थो राक्षसेश्वरः।
गदामुसलवर्षेण रामं प्रत्यर्दयद्रणे॥', 'rāvaṇo ''pi tataḥ kruddho rathastho rākṣaseśvaraḥ
gadāmusalavarṣeṇa rāmaṃ pratyardayad raṇe', null, 6096029),
('ramayana-6-96-30', 30, 'Yuddha Kanda, Sarga 96, Verse 30', 'देवदानवयक्षाणां पिशाचोरगरक्षसाम्।
पश्यतां तन्महद्युद्धं सर्वरात्रमवर्तत॥', 'devadānavayakṣāṇāṃ piśācoragarakṣasām
paśyatāṃ tan mahad yuddhaṃ sarvarātram avartata', null, 6096030),
('ramayana-6-96-31', 31, 'Yuddha Kanda, Sarga 96, Verse 31', 'नैव रत्रिं न दिवसं न मुहूर्तं न चक्षणम्।
रामरावणयोर्युद्धं विराममुपगच्छति॥', 'naiva ratriṃ na divasaṃ na muhūrtaṃ na cakṣaṇam
rāmarāvaṇayor yuddhaṃ virāmam upagacchati', null, 6096031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 97 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-97-1', 1, 'Yuddha Kanda, Sarga 97, Verse 1', 'अथ संस्मारयामास राघवं मातलिस्तदा।
अजानन्निव किं वीर त्वमेनमनुवर्तसे॥', 'atha saṃsmārayām āsa rāghavaṃ mātalis tadā
ajānann iva kiṃ vīra tvam enam anuvartase', null, 6097001),
('ramayana-6-97-2', 2, 'Yuddha Kanda, Sarga 97, Verse 2', 'विसृजास्मै वधाय त्वमस्त्रं पैतामहं प्रभो।
विनाशकालः कथितो यः सुरैः सोऽद्य वर्तते॥', 'visṛjāsmai vadhāya tvam astraṃ paitāmahaṃ prabho
vināśakālaḥ kathito yaḥ suraiḥ so ''dya vartate', null, 6097002),
('ramayana-6-97-3', 3, 'Yuddha Kanda, Sarga 97, Verse 3', 'ततः संस्मारितो रामस्तेन वाक्येन मातलेः।
जग्राह स शरं दीप्तं निश्वसन्तमिवोरगम्॥', 'tataḥ saṃsmārito rāmas tena vākyena mātaleḥ
jagrāha sa śaraṃ dīptaṃ niśvasantam ivoragam', null, 6097003),
('ramayana-6-97-4', 4, 'Yuddha Kanda, Sarga 97, Verse 4', 'यमस्मै प्रथमं प्रादादगस्त्यो भगवानृषिः।
ब्रह्मदत्तं महद्बाणममोघं युधि वीर्यवान्॥', 'yam asmai prathamaṃ prādād agastyo bhagavān ṛṣiḥ
brahmadattaṃ mahad bāṇam amoghaṃ yudhi vīryavān', null, 6097004),
('ramayana-6-97-5', 5, 'Yuddha Kanda, Sarga 97, Verse 5', 'ब्रह्मणा निर्मितं पूर्वमिन्द्रार्थममितौजसा।
दत्तं सुरपतेः पूर्वं त्रिलोकजयकाङ्क्षिणः॥', 'brahmaṇā nirmitaṃ pūrvam indrārtham amitaujasā
dattaṃ surapateḥ pūrvaṃ trilokajayakāṅkṣiṇaḥ', null, 6097005),
('ramayana-6-97-6', 6, 'Yuddha Kanda, Sarga 97, Verse 6', 'यस्य वाजेषु पवनः फले पावकभास्करौ।
शरीरमाकाशमयं गौरवे मेरुमन्दरौ॥', 'yasya vājeṣu pavanaḥ phale pāvakabhāskarau
śarīram ākāśamayaṃ gaurave merumandarau', null, 6097006),
('ramayana-6-97-7', 7, 'Yuddha Kanda, Sarga 97, Verse 7', 'जाज्वल्यमानं वपुषा सुपुङ्खं हेमभूषितम्।
तेजसा सर्वभूतानां कृतं भास्करवर्चसं॥', 'jājvalyamānaṃ vapuṣā supuṅkhaṃ hemabhūṣitam
tejasā sarvabhūtānāṃ kṛtaṃ bhāskaravarcasaṃ', null, 6097007),
('ramayana-6-97-8', 8, 'Yuddha Kanda, Sarga 97, Verse 8', 'सधूममिव कालाग्निं दीप्तमाशीविषं यथा।
रथनागाश्ववृन्दानां भेदनं क्षिप्रकारिणम्॥', 'sadhūmam iva kālāgniṃ dīptam āśīviṣaṃ yathā
rathanāgāśvavṛndānāṃ bhedanaṃ kṣiprakāriṇam', null, 6097008),
('ramayana-6-97-9', 9, 'Yuddha Kanda, Sarga 97, Verse 9', 'द्वाराणां परिघाणां च गिरीणामपि भेदनम्।
नानारुधिरसिक्ताङ्गं मेदोदिग्धं सुदारुणम्॥', 'dvārāṇāṃ parighāṇāṃ ca girīṇām api bhedanam
nānārudhirasiktāṅgaṃ medodigdhaṃ sudāruṇam', null, 6097009),
('ramayana-6-97-10', 10, 'Yuddha Kanda, Sarga 97, Verse 10', 'वज्रसारं महानादं नानासमितिदारुणम्।
सर्ववित्रासनं भीमं श्वसन्तमिव पन्नगम्॥', 'vajrasāraṃ mahānādaṃ nānāsamitidāruṇam
sarvavitrāsanaṃ bhīmaṃ śvasantam iva pannagam', null, 6097010),
('ramayana-6-97-11', 11, 'Yuddha Kanda, Sarga 97, Verse 11', 'कङ्कगृध्रबलानां च गोमायुगणरक्षसाम्।
नित्यं भक्षप्रदं युद्धे यमरूपं भयावहम्॥', 'kaṅkagṛdhrabalānāṃ ca gomāyugaṇarakṣasām
nityaṃ bhakṣapradaṃ yuddhe yamarūpaṃ bhayāvaham', null, 6097011),
('ramayana-6-97-12', 12, 'Yuddha Kanda, Sarga 97, Verse 12', 'नन्दनं वानरेन्द्राणां रक्षसामवसादनम्।
वाजितं विविधैर्वाजैश्चारुचित्रैर्गरुत्मतः॥', 'nandanaṃ vānarendrāṇāṃ rakṣasām avasādanam
vājitaṃ vividhair vājaiś cārucitrair garutmataḥ', null, 6097012),
('ramayana-6-97-13', 13, 'Yuddha Kanda, Sarga 97, Verse 13', 'तमुत्तमेषुं लोकानामिक्ष्वाकुभयनाशनम्।
द्विषतां कीर्तिहरणं प्रहर्षकरमात्मनः॥', 'tam uttameṣuṃ lokānām ikṣvākubhayanāśanam
dviṣatāṃ kīrtiharaṇaṃ praharṣakaram ātmanaḥ', null, 6097013),
('ramayana-6-97-14', 14, 'Yuddha Kanda, Sarga 97, Verse 14', 'अभिमन्त्र्य ततो रामस्तं महेषुं महाबलः।
वेदप्रोक्तेन विधिना संदधे कार्मुके बली॥', 'abhimantrya tato rāmas taṃ maheṣuṃ mahābalaḥ
vedaproktena vidhinā saṃdadhe kārmuke balī', null, 6097014),
('ramayana-6-97-15', 15, 'Yuddha Kanda, Sarga 97, Verse 15', 'स रावणाय संक्रुद्धो भृशमायम्य कार्मुकम्।
चिक्षेप परमायत्तस्तं शरं मर्मघातिनम्॥', 'sa rāvaṇāya saṃkruddho bhṛśam āyamya kārmukam
cikṣepa param āyattas taṃ śaraṃ marmaghātinam', null, 6097015),
('ramayana-6-97-16', 16, 'Yuddha Kanda, Sarga 97, Verse 16', 'स वज्र इव दुर्धर्षो वज्रबाहुविसर्जितः।
कृतान्त इव चावार्यो न्यपतद्रावणोरसि॥', 'sa vajra iva durdharṣo vajrabāhuvisarjitaḥ
kṛtānta iva cāvāryo nyapatad rāvaṇorasi', null, 6097016),
('ramayana-6-97-17', 17, 'Yuddha Kanda, Sarga 97, Verse 17', 'स विसृष्टो महावेगः शरीरान्तकरः शरः।
बिभेद हृदयं तस्य रावणस्य दुरात्मनः॥', 'sa visṛṣṭo mahāvegaḥ śarīrāntakaraḥ śaraḥ
bibheda hṛdayaṃ tasya rāvaṇasya durātmanaḥ', null, 6097017),
('ramayana-6-97-18', 18, 'Yuddha Kanda, Sarga 97, Verse 18', 'रुधिराक्तः स वेगेन जीवितान्तकरः शरः।
रावणस्य हरन्प्राणान्विवेश धरणीतलम्॥', 'rudhirāktaḥ sa vegena jīvitāntakaraḥ śaraḥ
rāvaṇasya haran prāṇān viveśa dharaṇītalam', null, 6097018),
('ramayana-6-97-19', 19, 'Yuddha Kanda, Sarga 97, Verse 19', 'स शरो रावणं हत्वा रुधिरार्द्रकृतच्छविः।
कृतकर्मा निभृतवत्स्वतूणीं पुनराविशत्॥', 'sa śaro rāvaṇaṃ hatvā rudhirārdrakṛtacchaviḥ
kṛtakarmā nibhṛtavat svatūṇīṃ punar āviśat', null, 6097019),
('ramayana-6-97-20', 20, 'Yuddha Kanda, Sarga 97, Verse 20', 'तस्य हस्ताद्धतस्याशु कार्मुकं तत्ससायकम्।
निपपात सह प्राणैर्भ्रश्यमानस्य जीवितात्॥', 'tasya hastād dhatasyāśu kārmukaṃ tat sasāyakam
nipapāta saha prāṇair bhraśyamānasya jīvitāt', null, 6097020),
('ramayana-6-97-21', 21, 'Yuddha Kanda, Sarga 97, Verse 21', 'गतासुर्भीमवेगस्तु नैरृतेन्द्रो महाद्युतिः।
पपात स्यन्दनाद्भूमौ वृत्रो वज्रहतो यथा॥', 'gatāsur bhīmavegas tu nairṛtendro mahādyutiḥ
papāta syandanād bhūmau vṛtro vajrahato yathā', null, 6097021),
('ramayana-6-97-22', 22, 'Yuddha Kanda, Sarga 97, Verse 22', 'तं दृष्ट्वा पतितं भूमौ हतशेषा निशाचराः।
हतनाथा भयत्रस्ताः सर्वतः संप्रदुद्रुवुः॥', 'taṃ dṛṣṭvā patitaṃ bhūmau hataśeṣā niśācarāḥ
hatanāthā bhayatrastāḥ sarvataḥ saṃpradudruvuḥ', null, 6097022),
('ramayana-6-97-23', 23, 'Yuddha Kanda, Sarga 97, Verse 23', 'नर्दन्तश्चाभिपेतुस्तान्वानरा द्रुमयोधिनः।
दशग्रीववधं दृष्ट्वा विजयं राघवस्य च॥', 'nardantaś cābhipetus tān vānarā drumayodhinaḥ
daśagrīvavadhaṃ dṛṣṭvā vijayaṃ rāghavasya ca', null, 6097023),
('ramayana-6-97-24', 24, 'Yuddha Kanda, Sarga 97, Verse 24', 'अर्दिता वानरैर्हृष्टैर्लङ्कामभ्यपतन्भयात्।
हताश्रयत्वात्करुणैर्बाष्पप्रस्रवणैर्मुखैः॥', 'arditā vānarair hṛṣṭair laṅkām abhyapatan bhayāt
hatāśrayatvāt karuṇair bāṣpaprasravaṇair mukhaiḥ', null, 6097024),
('ramayana-6-97-25', 25, 'Yuddha Kanda, Sarga 97, Verse 25', 'ततो विनेदुः संहृष्टा वानरा जितकाशिनः।
वदन्तो राघवजयं रावणस्य च तं वधम्॥', 'tato vineduḥ saṃhṛṣṭā vānarā jitakāśinaḥ
vadanto rāghavajayaṃ rāvaṇasya ca taṃ vadham', null, 6097025),
('ramayana-6-97-26', 26, 'Yuddha Kanda, Sarga 97, Verse 26', 'अथान्तरिक्षे व्यनदत्सौम्यस्त्रिदशदुन्दुभिः।
दिव्यगन्धवहस्तत्र मारुतः सुसुखो ववौ॥', 'athāntarikṣe vyanadat saumyas tridaśadundubhiḥ
divyagandhavahas tatra mārutaḥ susukho vavau', null, 6097026),
('ramayana-6-97-27', 27, 'Yuddha Kanda, Sarga 97, Verse 27', 'निपपातान्तरिक्षाच्च पुष्पवृष्टिस्तदा भुवि।
किरन्ती राघवरथं दुरवापा मनोहराः॥', 'nipapātāntarikṣāc ca puṣpavṛṣṭis tadā bhuvi
kirantī rāghavarathaṃ duravāpā manoharāḥ', null, 6097027),
('ramayana-6-97-28', 28, 'Yuddha Kanda, Sarga 97, Verse 28', 'राघवस्तवसंयुक्ता गगने च विशुश्रुवे।
साधु साध्विति वागग्र्या देवतानां महात्मनाम्॥', 'rāghavastavasaṃyuktā gagane ca viśuśruve
sādhu sādhv iti vāg agryā devatānāṃ mahātmanām', null, 6097028),
('ramayana-6-97-29', 29, 'Yuddha Kanda, Sarga 97, Verse 29', 'आविवेश महान्हर्षो देवानां चारणैः सह।
रावणे निहते रौद्रे सर्वलोकभयंकरे॥', 'āviveśa mahān harṣo devānāṃ cāraṇaiḥ saha
rāvaṇe nihate raudre sarvalokabhayaṃkare', null, 6097029),
('ramayana-6-97-30', 30, 'Yuddha Kanda, Sarga 97, Verse 30', 'ततः सकामं सुग्रीवमङ्गदं च महाबलम्।
चकार राघवः प्रीतो हत्वा राक्षसपुंगवम्॥', 'tataḥ sakāmaṃ sugrīvam aṅgadaṃ ca mahābalam
cakāra rāghavaḥ prīto hatvā rākṣasapuṃgavam', null, 6097030),
('ramayana-6-97-31', 31, 'Yuddha Kanda, Sarga 97, Verse 31', 'ततः प्रजग्मुः प्रशमं मरुद्गणा दिशः प्रसेदुर्विमलं नभोऽभवत्।
मही चकम्पे न च मारुता ववुः स्थिरप्रभश्चाप्यभवद्दिवाकरः॥', 'tataḥ prajagmuḥ praśamaṃ marudgaṇā diśaḥ prasedur vimalaṃ nabho ''bhavat
mahī cakampe na ca mārutā vavuḥ sthiraprabhaś cāpy abhavad divākaraḥ', null, 6097031),
('ramayana-6-97-32', 32, 'Yuddha Kanda, Sarga 97, Verse 32', 'ततस्तु सुग्रीवविभीषणादयः सुहृद्विशेषाः सहलक्ष्मणास्तदा।
समेत्य हृष्टा विजयेन राघवं रणेऽभिरामं विधिनाभ्यपूजयन्॥', 'tatas tu sugrīvavibhīṣaṇādayaḥ suhṛdviśeṣāḥ sahalakṣmaṇās tadā
sametya hṛṣṭā vijayena rāghavaṃ raṇe ''bhirāmaṃ vidhinābhyapūjayan', null, 6097032),
('ramayana-6-97-33', 33, 'Yuddha Kanda, Sarga 97, Verse 33', 'स तु निहतरिपुः स्थिरप्रतिज्ञः स्वजनबलाभिवृतो रणे रराज।
रघुकुलनृपनन्दनो महौजास्त्रिदशगणैरभिसंवृतो यथेन्द्रः॥', 'sa tu nihataripuḥ sthirapratijñaḥ svajanabalābhivṛto raṇe rarāja
raghukulanṛpanandano mahaujās tridaśagaṇair abhisaṃvṛto yathendraḥ', null, 6097033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 98 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-98-1', 1, 'Yuddha Kanda, Sarga 98, Verse 1', 'रावणं निहतं श्रुत्वा राघवेण महात्मना।
अन्तःपुराद्विनिष्पेतू राक्षस्यः शोककर्शिताः॥', 'rāvaṇaṃ nihataṃ śrutvā rāghaveṇa mahātmanā
antaḥpurād viniṣpetū rākṣasyaḥ śokakarśitāḥ', null, 6098001),
('ramayana-6-98-2', 2, 'Yuddha Kanda, Sarga 98, Verse 2', 'वार्यमाणाः सुबहुशो वृष्टन्त्यः क्षितिपांसुषु।
विमुक्तकेश्यो दुःखार्ता गावो वत्सहता यथा॥', 'vāryamāṇāḥ subahuśo vṛṣṭantyaḥ kṣitipāṃsuṣu
vimuktakeśyo duḥkhārtā gāvo vatsahatā yathā', null, 6098002),
('ramayana-6-98-3', 3, 'Yuddha Kanda, Sarga 98, Verse 3', 'उत्तरेण विनिष्क्रम्य द्वारेण सह राक्षसैः।
प्रविश्यायोधनं घोरं विचिन्वन्त्यो हतं पतिम्॥', 'uttareṇa viniṣkramya dvāreṇa saha rākṣasaiḥ
praviśyāyodhanaṃ ghoraṃ vicinvantyo hataṃ patim', null, 6098003),
('ramayana-6-98-4', 4, 'Yuddha Kanda, Sarga 98, Verse 4', 'आर्यपुत्रेति वादिन्यो हा नाथेति च सर्वशः।
परिपेतुः कबन्धाङ्कां महीं शोणितकर्दमाम्॥', 'āryaputreti vādinyo hā nātheti ca sarvaśaḥ
paripetuḥ kabandhāṅkāṃ mahīṃ śoṇitakardamām', null, 6098004),
('ramayana-6-98-5', 5, 'Yuddha Kanda, Sarga 98, Verse 5', 'ता बाष्पपरिपूर्णाक्ष्यो भर्तृशोकपराजिताः।
करेण्व इव नर्दन्त्यो विनेदुर्हतयूथपाः॥', 'tā bāṣpaparipūrṇākṣyo bhartṛśokaparājitāḥ
kareṇva iva nardantyo vinedur hatayūthapāḥ', null, 6098005),
('ramayana-6-98-6', 6, 'Yuddha Kanda, Sarga 98, Verse 6', 'ददृशुस्ता महाकायं महावीर्यं महाद्युतिम्।
रावणं निहतं भूमौ नीलाञ्जनचयोपमम्॥', 'dadṛśus tā mahākāyaṃ mahāvīryaṃ mahādyutim
rāvaṇaṃ nihataṃ bhūmau nīlāñjanacayopamam', null, 6098006),
('ramayana-6-98-7', 7, 'Yuddha Kanda, Sarga 98, Verse 7', 'ताः पतिं सहसा दृष्ट्वा शयानं रणपांसुषु।
निपेतुस्तस्य गात्रेषु छिन्ना वनलता इव॥', 'tāḥ patiṃ sahasā dṛṣṭvā śayānaṃ raṇapāṃsuṣu
nipetus tasya gātreṣu chinnā vanalatā iva', null, 6098007),
('ramayana-6-98-8', 8, 'Yuddha Kanda, Sarga 98, Verse 8', 'बहुमानात्परिष्वज्य का चिदेनं रुरोद ह।
चरणौ का चिदालिङ्ग्य का चित्कण्ठेऽवलम्ब्य च॥', 'bahumānāt pariṣvajya kā cid enaṃ ruroda ha
caraṇau kā cid āliṅgya kā cit kaṇṭhe ''valambya ca', null, 6098008),
('ramayana-6-98-9', 9, 'Yuddha Kanda, Sarga 98, Verse 9', 'उद्धृत्य च भुजौ का चिद्भूमौ स्म परिवर्तते।
हतस्य वदनं दृष्ट्वा का चिन्मोहमुपागमत्॥', 'uddhṛtya ca bhujau kā cid bhūmau sma parivartate
hatasya vadanaṃ dṛṣṭvā kā cin moham upāgamat', null, 6098009),
('ramayana-6-98-10', 10, 'Yuddha Kanda, Sarga 98, Verse 10', 'का चिदङ्के शिरः कृत्वा रुरोद मुखमीक्षती।
स्नापयन्ती मुखं बाष्पैस्तुषारैरिव पङ्कजम्॥', 'kā cid aṅke śiraḥ kṛtvā ruroda mukham īkṣatī
snāpayantī mukhaṃ bāṣpais tuṣārair iva paṅkajam', null, 6098010),
('ramayana-6-98-11', 11, 'Yuddha Kanda, Sarga 98, Verse 11', 'एवमार्ताः पतिं दृष्ट्वा रावणं निहतं भुवि।
चुक्रुशुर्बहुधा शोकाद्भूयस्ताः पर्यदेवयन्॥', 'evam ārtāḥ patiṃ dṛṣṭvā rāvaṇaṃ nihataṃ bhuvi
cukruśur bahudhā śokād bhūyas tāḥ paryadevayan', null, 6098011),
('ramayana-6-98-12', 12, 'Yuddha Kanda, Sarga 98, Verse 12', 'येन वित्रासितः शक्रो येन वित्रासितो यमः।
येन वैश्रवणो राजा पुष्पकेण वियोजितः॥', 'yena vitrāsitaḥ śakro yena vitrāsito yamaḥ
yena vaiśravaṇo rājā puṣpakeṇa viyojitaḥ', null, 6098012),
('ramayana-6-98-13', 13, 'Yuddha Kanda, Sarga 98, Verse 13', 'गन्धर्वाणामृषीणां च सुराणां च महात्मनाम्।
भयं येन महद्दत्तं सोऽयं शेते रणे हतः॥', 'gandharvāṇām ṛṣīṇāṃ ca surāṇāṃ ca mahātmanām
bhayaṃ yena mahad dattaṃ so ''yaṃ śete raṇe hataḥ', null, 6098013),
('ramayana-6-98-14', 14, 'Yuddha Kanda, Sarga 98, Verse 14', 'असुरेभ्यः सुरेभ्यो वा पन्नगेभ्योऽपि वा तथा।
न भयं यो विजानाति तस्येदं मानुषाद्भयम्॥', 'asurebhyaḥ surebhyo vā pannagebhyo ''pi vā tathā
na bhayaṃ yo vijānāti tasyedaṃ mānuṣād bhayam', null, 6098014),
('ramayana-6-98-15', 15, 'Yuddha Kanda, Sarga 98, Verse 15', 'अवध्यो देवतानां यस्तथा दानवरक्षसाम्।
हतः सोऽयं रणे शेते मानुषेण पदातिना॥', 'avadhyo devatānāṃ yas tathā dānavarakṣasām
hataḥ so ''yaṃ raṇe śete mānuṣeṇa padātinā', null, 6098015),
('ramayana-6-98-16', 16, 'Yuddha Kanda, Sarga 98, Verse 16', 'यो न शक्यः सुरैर्हन्तुं न यक्षैर्नासुरैस्तथा।
सोऽयं कश्चिदिवासत्त्वो मृत्युं मर्त्येन लम्भितः॥', 'yo na śakyaḥ surair hantuṃ na yakṣair nāsurais tathā
so ''yaṃ kaś cid ivāsattvo mṛtyuṃ martyena lambhitaḥ', null, 6098016),
('ramayana-6-98-17', 17, 'Yuddha Kanda, Sarga 98, Verse 17', 'एवं वदन्त्यो बहुधा रुरुदुस्तस्य ताः स्त्रियः।
भूय एव च दुःखार्ता विलेपुश्च पुनः पुनः॥', 'evaṃ vadantyo bahudhā rurudus tasya tāḥ striyaḥ
bhūya eva ca duḥkhārtā vilepuś ca punaḥ punaḥ', null, 6098017),
('ramayana-6-98-18', 18, 'Yuddha Kanda, Sarga 98, Verse 18', 'अशृण्वता तु सुहृदां सततं हितवादिनाम्।
एताः सममिदानीं ते वयमात्मा च पातिताः॥', 'aśṛṇvatā tu suhṛdāṃ satataṃ hitavādinām
etāḥ samam idānīṃ te vayam ātmā ca pātitāḥ', null, 6098018),
('ramayana-6-98-19', 19, 'Yuddha Kanda, Sarga 98, Verse 19', 'ब्रुवाणोऽपि हितं वाक्यमिष्टो भ्राता विभीषणः।
धृष्टं परुषितो मोहात्त्वयात्मवधकाङ्क्षिणा॥', 'bruvāṇo ''pi hitaṃ vākyam iṣṭo bhrātā vibhīṣaṇaḥ
dhṛṣṭaṃ paruṣito mohāt tvayātmavadhakāṅkṣiṇā', null, 6098019),
('ramayana-6-98-20', 20, 'Yuddha Kanda, Sarga 98, Verse 20', 'यदि निर्यातिता ते स्यात्सीता रामाय मैथिली।
न नः स्याद्व्यसनं घोरमिदं मूलहरं महत्॥', 'yadi niryātitā te syāt sītā rāmāya maithilī
na naḥ syād vyasanaṃ ghoram idaṃ mūlaharaṃ mahat', null, 6098020),
('ramayana-6-98-21', 21, 'Yuddha Kanda, Sarga 98, Verse 21', 'वृत्तकामो भवेद्भ्राता रामो मित्रकुलं भवेत्।
वयं चाविधवाः सर्वाः सकामा न च शत्रवः॥', 'vṛttakāmo bhaved bhrātā rāmo mitrakulaṃ bhavet
vayaṃ cāvidhavāḥ sarvāḥ sakāmā na ca śatravaḥ', null, 6098021),
('ramayana-6-98-22', 22, 'Yuddha Kanda, Sarga 98, Verse 22', 'त्वया पुनर्नृशंसेन सीतां संरुन्धता बलात्।
राक्षसा वयमात्मा च त्रयं तुलं निपातितम्॥', 'tvayā punar nṛśaṃsena sītāṃ saṃrundhatā balāt
rākṣasā vayam ātmā ca trayaṃ tulaṃ nipātitam', null, 6098022),
('ramayana-6-98-23', 23, 'Yuddha Kanda, Sarga 98, Verse 23', 'न कामकारः कामं वा तव राक्षसपुंगव।
दैवं चेष्टयते सर्वं हतं दैवेन हन्यते॥', 'na kāmakāraḥ kāmaṃ vā tava rākṣasapuṃgava
daivaṃ ceṣṭayate sarvaṃ hataṃ daivena hanyate', null, 6098023),
('ramayana-6-98-24', 24, 'Yuddha Kanda, Sarga 98, Verse 24', 'वानराणां विनाशोऽयं राक्षसानां च ते रणे।
तव चैव महाबाहो दैवयोगादुपागतः॥', 'vānarāṇāṃ vināśo ''yaṃ rākṣasānāṃ ca te raṇe
tava caiva mahābāho daivayogād upāgataḥ', null, 6098024),
('ramayana-6-98-25', 25, 'Yuddha Kanda, Sarga 98, Verse 25', 'नैवार्थेन न कामेन विक्रमेण न चाज्ञया।
शक्या दैवगतिर्लोके निवर्तयितुमुद्यता॥', 'naivārthena na kāmena vikrameṇa na cājñayā
śakyā daivagatir loke nivartayitum udyatā', null, 6098025),
('ramayana-6-98-26', 26, 'Yuddha Kanda, Sarga 98, Verse 26', 'विलेपुरेवं दीनास्ता राक्षसाधिपयोषितः।
कुरर्य इव दुःखार्ता बाष्पपर्याकुलेक्षणाः॥', 'vilepur evaṃ dīnās tā rākṣasādhipayoṣitaḥ
kurarya iva duḥkhārtā bāṣpaparyākulekṣaṇāḥ', null, 6098026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 99 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-99-1', 1, 'Yuddha Kanda, Sarga 99, Verse 1', 'तासां विलपमानानां तथा राक्षसयोषिताम्।
ज्येष्ठा पत्नी प्रिया दीना भर्तारं समुदैक्षत॥', 'tāsāṃ vilapamānānāṃ tathā rākṣasayoṣitām
jyeṣṭhā patnī priyā dīnā bhartāraṃ samudaikṣata', null, 6099001),
('ramayana-6-99-2', 2, 'Yuddha Kanda, Sarga 99, Verse 2', 'दशग्रीवं हतं दृष्ट्वा रामेणाचिन्त्यकर्मणा।
पतिं मन्दोदरी तत्र कृपणा पर्यदेवयत्॥', 'daśagrīvaṃ hataṃ dṛṣṭvā rāmeṇācintyakarmaṇā
patiṃ mandodarī tatra kṛpaṇā paryadevayat', null, 6099002),
('ramayana-6-99-3', 3, 'Yuddha Kanda, Sarga 99, Verse 3', 'ननु नाम महाबाहो तव वैश्रवणानुज।
क्रुद्धस्य प्रमुखे स्थातुं त्रस्यत्यपि पुरंदरः॥', 'nanu nāma mahābāho tava vaiśravaṇānuja
kruddhasya pramukhe sthātuṃ trasyaty api puraṃdaraḥ', null, 6099003),
('ramayana-6-99-4', 4, 'Yuddha Kanda, Sarga 99, Verse 4', 'ऋषयश्च महीदेवा गन्धर्वाश्च यशस्विनः।
ननु नाम तवोद्वेगाच्चारणाश्च दिशो गताः॥', 'ṛṣayaś ca mahīdevā gandharvāś ca yaśasvinaḥ
nanu nāma tavodvegāc cāraṇāś ca diśo gatāḥ', null, 6099004),
('ramayana-6-99-5', 5, 'Yuddha Kanda, Sarga 99, Verse 5', 'स त्वं मानुषमात्रेण रामेण युधि निर्जितः।
न व्यपत्रपसे राजन्किमिदं राक्षसर्षभ॥', 'sa tvaṃ mānuṣamātreṇa rāmeṇa yudhi nirjitaḥ
na vyapatrapase rājan kim idaṃ rākṣasarṣabha', null, 6099005),
('ramayana-6-99-6', 6, 'Yuddha Kanda, Sarga 99, Verse 6', 'कथं त्रैलोक्यमाक्रम्य श्रिया वीर्येण चान्वितम्।
अविषह्यं जघान त्वां मानुषो वनगोचरः॥', 'kathaṃ trailokyam ākramya śriyā vīryeṇa cānvitam
aviṣahyaṃ jaghāna tvāṃ mānuṣo vanagocaraḥ', null, 6099006),
('ramayana-6-99-7', 7, 'Yuddha Kanda, Sarga 99, Verse 7', 'मानुषाणामविषये चरतः कामरूपिणः।
विनाशस्तव रामेण संयुगे नोपपद्यते॥', 'mānuṣāṇām aviṣaye carataḥ kāmarūpiṇaḥ
vināśas tava rāmeṇa saṃyuge nopapadyate', null, 6099007),
('ramayana-6-99-8', 8, 'Yuddha Kanda, Sarga 99, Verse 8', 'न चैतत्कर्म रामस्य श्रद्दधामि चमूमुखे।
सर्वतः समुपेतस्य तव तेनाभिमर्शनम्॥', 'na caitat karma rāmasya śraddadhāmi camūmukhe
sarvataḥ samupetasya tava tenābhimarśanam', null, 6099008),
('ramayana-6-99-9', 9, 'Yuddha Kanda, Sarga 99, Verse 9', 'इन्द्रियाणि पुरा जित्वा जितं त्रिभुवणं त्वया।
स्मरद्भिरिव तद्वैरमिन्द्रियैरेव निर्जितः॥', 'indriyāṇi purā jitvā jitaṃ tribhuvaṇaṃ tvayā
smaradbhir iva tad vairam indriyair eva nirjitaḥ', null, 6099009),
('ramayana-6-99-10', 10, 'Yuddha Kanda, Sarga 99, Verse 10', 'अथ वा रामरूपेण वासवः स्वयमागतः।
मायां तव विनाशाय विधायाप्रतितर्किताम्॥', 'atha vā rāmarūpeṇa vāsavaḥ svayam āgataḥ
māyāṃ tava vināśāya vidhāyāpratitarkitām', null, 6099010),
('ramayana-6-99-11', 11, 'Yuddha Kanda, Sarga 99, Verse 11', 'यदैव हि जनस्थाने राक्षसैर्बहुभिर्वृतः।
खरस्तव हतो भ्राता तदैवासौ न मानुषः॥', 'yadaiva hi janasthāne rākṣasair bahubhir vṛtaḥ
kharas tava hato bhrātā tadaivāsau na mānuṣaḥ', null, 6099011),
('ramayana-6-99-12', 12, 'Yuddha Kanda, Sarga 99, Verse 12', 'यदैव नगरीं लङ्कां दुष्प्रवेषां सुरैरपि।
प्रविष्टो हनुमान्वीर्यात्तदैव व्यथिता वयम्॥', 'yadaiva nagarīṃ laṅkāṃ duṣpraveṣāṃ surair api
praviṣṭo hanumān vīryāt tadaiva vyathitā vayam', null, 6099012),
('ramayana-6-99-13', 13, 'Yuddha Kanda, Sarga 99, Verse 13', 'क्रियतामविरोधश्च राघवेणेति यन्मया।
उच्यमानो न गृह्णासि तस्येयं व्युष्टिरागता॥', 'kriyatām avirodhaś ca rāghaveṇeti yan mayā
ucyamāno na gṛhṇāsi tasyeyaṃ vyuṣṭir āgatā', null, 6099013),
('ramayana-6-99-14', 14, 'Yuddha Kanda, Sarga 99, Verse 14', 'अकस्माच्चाभिकामोऽसि सीतां राक्षसपुंगव।
ऐश्वर्यस्य विनाशाय देहस्य स्वजनस्य च॥', 'akasmāc cābhikāmo ''si sītāṃ rākṣasapuṃgava
aiśvaryasya vināśāya dehasya svajanasya ca', null, 6099014),
('ramayana-6-99-15', 15, 'Yuddha Kanda, Sarga 99, Verse 15', 'अरुन्धत्या विशिष्टां तां रोहिण्याश्चापि दुर्मते।
सीतां धर्षयता मान्यां त्वया ह्यसदृशं कृतम्॥', 'arundhatyā viśiṣṭāṃ tāṃ rohiṇyāś cāpi durmate
sītāṃ dharṣayatā mānyāṃ tvayā hy asadṛśaṃ kṛtam', null, 6099015),
('ramayana-6-99-16', 16, 'Yuddha Kanda, Sarga 99, Verse 16', 'न कुलेन न रूपेण न दाक्षिण्येन मैथिली।
मयाधिका वा तुल्या वा त्वं तु मोहान्न बुध्यसे॥', 'na kulena na rūpeṇa na dākṣiṇyena maithilī
mayādhikā vā tulyā vā tvaṃ tu mohān na budhyase', null, 6099016),
('ramayana-6-99-17', 17, 'Yuddha Kanda, Sarga 99, Verse 17', 'सर्वथा सर्वभूतानां नास्ति मृत्युरलक्षणः।
तव तावदयं मृत्युर्मैथिलीकृतलक्षणः॥', 'sarvathā sarvabhūtānāṃ nāsti mṛtyur alakṣaṇaḥ
tava tāvad ayaṃ mṛtyur maithilīkṛtalakṣaṇaḥ', null, 6099017),
('ramayana-6-99-18', 18, 'Yuddha Kanda, Sarga 99, Verse 18', 'मैथिली सह रामेण विशोका विहरिष्यति।
अल्पपुण्या त्वहं घोरे पतिता शोकसागरे॥', 'maithilī saha rāmeṇa viśokā vihariṣyati
alpapuṇyā tv ahaṃ ghore patitā śokasāgare', null, 6099018),
('ramayana-6-99-19', 19, 'Yuddha Kanda, Sarga 99, Verse 19', 'कैलासे मन्दरे मेरौ तथा चैत्ररथे वने।
देवोद्यानेषु सर्वेषु विहृत्य सहिता त्वया॥', 'kailāse mandare merau tathā caitrarathe vane
devodyāneṣu sarveṣu vihṛtya sahitā tvayā', null, 6099019),
('ramayana-6-99-20', 20, 'Yuddha Kanda, Sarga 99, Verse 20', 'विमानेनानुरूपेण या याम्यतुलया श्रिया।
पश्यन्ती विविधान्देशांस्तांस्तांश्चित्रस्रगम्बरा।
भ्रंशिता कामभोगेभ्यः सास्मि वीरवधात्तव॥', 'vimānenānurūpeṇa yā yāmy atulayā śriyā
paśyantī vividhān deśāṃs tāṃs tāṃś citrasragambarā
bhraṃśitā kāmabhogebhyaḥ sāsmi vīravadhāt tava', null, 6099020),
('ramayana-6-99-21', 21, 'Yuddha Kanda, Sarga 99, Verse 21', 'सत्यवाक्स महाभागो देवरो मे यदब्रवीत्।
अयं राक्षसमुख्यानां विनाशः पर्युपस्थितः॥', 'satyavāk sa mahābhāgo devaro me yad abravīt
ayaṃ rākṣasamukhyānāṃ vināśaḥ paryupasthitaḥ', null, 6099021),
('ramayana-6-99-22', 22, 'Yuddha Kanda, Sarga 99, Verse 22', 'कामक्रोधसमुत्थेन व्यसनेन प्रसङ्गिना।
त्वया कृतमिदं सर्वमनाथं रक्षसां कुलम्॥', 'kāmakrodhasamutthena vyasanena prasaṅginā
tvayā kṛtam idaṃ sarvam anāthaṃ rakṣasāṃ kulam', null, 6099022),
('ramayana-6-99-23', 23, 'Yuddha Kanda, Sarga 99, Verse 23', 'न हि त्वं शोचितव्यो मे प्रख्यातबलपौरुषः।
स्त्रीस्वभावात्तु मे बुद्धिः कारुण्ये परिवर्तते॥', 'na hi tvaṃ śocitavyo me prakhyātabalapauruṣaḥ
strīsvabhāvāt tu me buddhiḥ kāruṇye parivartate', null, 6099023),
('ramayana-6-99-24', 24, 'Yuddha Kanda, Sarga 99, Verse 24', 'सुकृतं दुष्कृतं च त्वं गृहीत्वा स्वां गतिं गतः।
आत्मानमनुशोचामि त्वद्वियोगेन दुःखिताम्॥', 'sukṛtaṃ duṣkṛtaṃ ca tvaṃ gṛhītvā svāṃ gatiṃ gataḥ
ātmānam anuśocāmi tvadviyogena duḥkhitām', null, 6099024),
('ramayana-6-99-25', 25, 'Yuddha Kanda, Sarga 99, Verse 25', 'नीलजीमूतसंकाशः पीताम्बरशुभाङ्गदः।
सर्वगात्राणि विक्षिप्य किं शेषे रुधिराप्लुतः।
प्रसुप्त इव शोकार्तां किं मां न प्रतिभाषसे॥', 'nīlajīmūtasaṃkāśaḥ pītāmbaraśubhāṅgadaḥ
sarvagātrāṇi vikṣipya kiṃ śeṣe rudhirāplutaḥ
prasupta iva śokārtāṃ kiṃ māṃ na pratibhāṣase', null, 6099025),
('ramayana-6-99-26', 26, 'Yuddha Kanda, Sarga 99, Verse 26', 'महावीर्यस्य दक्षस्य संयुगेष्वपलायिनः।
यातुधानस्य दौहित्रीं किं त्वं मां नाभ्युदीक्षसे॥', 'mahāvīryasya dakṣasya saṃyugeṣv apalāyinaḥ
yātudhānasya dauhitrīṃ kiṃ tvaṃ māṃ nābhyudīkṣase', null, 6099026),
('ramayana-6-99-27', 27, 'Yuddha Kanda, Sarga 99, Verse 27', 'येन सूदयसे शत्रून्समरे सूर्यवर्चसा।
वज्रो वज्रधरस्येव सोऽयं ते सततार्चितः॥', 'yena sūdayase śatrūn samare sūryavarcasā
vajro vajradharasyeva so ''yaṃ te satatārcitaḥ', null, 6099027),
('ramayana-6-99-28', 28, 'Yuddha Kanda, Sarga 99, Verse 28', 'रणे शत्रुप्रहरणो हेमजालपरिष्कृतः।
परिघो व्यवकीर्णस्ते बाणैश्छिन्नः सहस्रधा॥', 'raṇe śatrupraharaṇo hemajālapariṣkṛtaḥ
parigho vyavakīrṇas te bāṇaiś chinnaḥ sahasradhā', null, 6099028),
('ramayana-6-99-29', 29, 'Yuddha Kanda, Sarga 99, Verse 29', 'धिगस्तु हृदयं यस्या ममेदं न सहस्रधा।
त्वयि पञ्चत्वमापन्ने फलते शोकपीडितम्॥', 'dhig astu hṛdayaṃ yasyā mamedaṃ na sahasradhā
tvayi pañcatvam āpanne phalate śokapīḍitam', null, 6099029),
('ramayana-6-99-30', 30, 'Yuddha Kanda, Sarga 99, Verse 30', 'एतस्मिन्नन्तरे रामो विभीषणमुवाच ह।
संस्कारः क्रियतां भ्रातुः स्त्रियश्चैता निवर्तय॥', 'etasminn antare rāmo vibhīṣaṇam uvāca ha
saṃskāraḥ kriyatāṃ bhrātuḥ striyaś caitā nivartaya', null, 6099030),
('ramayana-6-99-31', 31, 'Yuddha Kanda, Sarga 99, Verse 31', 'तं प्रश्रितस्ततो रामं श्रुतवाक्यो विभीषणः।
विमृश्य बुद्ध्या धर्मज्ञो धर्मार्थसहितं वचः।
रामस्यैवानुवृत्त्यर्थमुत्तरं प्रत्यभाषत॥', 'taṃ praśritas tato rāmaṃ śrutavākyo vibhīṣaṇaḥ
vimṛśya buddhyā dharmajño dharmārthasahitaṃ vacaḥ
rāmasyaivānuvṛttyartham uttaraṃ pratyabhāṣata', null, 6099031),
('ramayana-6-99-32', 32, 'Yuddha Kanda, Sarga 99, Verse 32', 'त्यक्तधर्मव्रतं क्रूरं नृशंसमनृतं तथा।
नाहमर्होऽस्मि संस्कर्तुं परदाराभिमर्शकम्॥', 'tyaktadharmavrataṃ krūraṃ nṛśaṃsam anṛtaṃ tathā
nāham arho ''smi saṃskartuṃ paradārābhimarśakam', null, 6099032),
('ramayana-6-99-33', 33, 'Yuddha Kanda, Sarga 99, Verse 33', 'भ्रातृरूपो हि मे शत्रुरेष सर्वाहिते रतः।
रावणो नार्हते पूजां पूज्योऽपि गुरुगौरवात्॥', 'bhrātṛrūpo hi me śatrur eṣa sarvāhite rataḥ
rāvaṇo nārhate pūjāṃ pūjyo ''pi gurugauravāt', null, 6099033),
('ramayana-6-99-34', 34, 'Yuddha Kanda, Sarga 99, Verse 34', 'नृशंस इति मां राम वक्ष्यन्ति मनुजा भुवि।
श्रुत्वा तस्य गुणान्सर्वे वक्ष्यन्ति सुकृतं पुनः॥', 'nṛśaṃsa iti māṃ rāma vakṣyanti manujā bhuvi
śrutvā tasya guṇān sarve vakṣyanti sukṛtaṃ punaḥ', null, 6099034),
('ramayana-6-99-35', 35, 'Yuddha Kanda, Sarga 99, Verse 35', 'तच्छ्रुत्वा परमप्रीतो रामो धर्मभृतां वरः।
विभीषणमुवाचेदं वाक्यज्ञो वाक्यकोविदम्॥', 'tac chrutvā paramaprīto rāmo dharmabhṛtāṃ varaḥ
vibhīṣaṇam uvācedaṃ vākyajño vākyakovidam', null, 6099035),
('ramayana-6-99-36', 36, 'Yuddha Kanda, Sarga 99, Verse 36', 'तवापि मे प्रियं कार्यं त्वत्प्रभवाच्च मे जितम्।
अवश्यं तु क्षमं वाच्यो मया त्वं राक्षसेश्वर॥', 'tavāpi me priyaṃ kāryaṃ tvatprabhavāc ca me jitam
avaśyaṃ tu kṣamaṃ vācyo mayā tvaṃ rākṣaseśvara', null, 6099036),
('ramayana-6-99-37', 37, 'Yuddha Kanda, Sarga 99, Verse 37', 'अधर्मानृतसंयुक्तः काममेष निशाचरः।
तेजस्वी बलवाञ्शूरः संग्रामेषु च नित्यशः॥', 'adharmānṛtasaṃyuktaḥ kāmam eṣa niśācaraḥ
tejasvī balavāñ śūraḥ saṃgrāmeṣu ca nityaśaḥ', null, 6099037),
('ramayana-6-99-38', 38, 'Yuddha Kanda, Sarga 99, Verse 38', 'शतक्रतुमुखैर्देवैः श्रूयते न पराजितः।
महात्मा बलसंपन्नो रावणो लोकरावणः॥', 'śatakratumukhair devaiḥ śrūyate na parājitaḥ
mahātmā balasaṃpanno rāvaṇo lokarāvaṇaḥ', null, 6099038),
('ramayana-6-99-39', 39, 'Yuddha Kanda, Sarga 99, Verse 39', 'मरणान्तानि वैराणि निर्वृत्तं नः प्रयोजनम्।
क्रियतामस्य संस्कारो ममाप्येष यथा तव॥', 'maraṇāntāni vairāṇi nirvṛttaṃ naḥ prayojanam
kriyatām asya saṃskāro mamāpy eṣa yathā tava', null, 6099039),
('ramayana-6-99-40', 40, 'Yuddha Kanda, Sarga 99, Verse 40', 'त्वत्सकाशान्महाबाहो संस्कारं विधिपूर्वकम्।
क्षिप्रमर्हति धर्मज्ञ त्वं यशोभाग्भविष्यसि॥', 'tvatsakāśān mahābāho saṃskāraṃ vidhipūrvakam
kṣipram arhati dharmajña tvaṃ yaśobhāg bhaviṣyasi', null, 6099040),
('ramayana-6-99-41', 41, 'Yuddha Kanda, Sarga 99, Verse 41', 'राघवस्य वचः श्रुत्वा त्वरमाणो विभीषणः।
संस्कारेणानुरूपेण योजयामास रावणम्॥', 'rāghavasya vacaḥ śrutvā tvaramāṇo vibhīṣaṇaḥ
saṃskāreṇānurūpeṇa yojayām āsa rāvaṇam', null, 6099041),
('ramayana-6-99-42', 42, 'Yuddha Kanda, Sarga 99, Verse 42', 'स ददौ पावकं तस्य विधियुक्तं विभीषणः।
ताः स्त्रियोऽनुनयामास सान्त्वमुक्त्वा पुनः पुनः॥', 'sa dadau pāvakaṃ tasya vidhiyuktaṃ vibhīṣaṇaḥ
tāḥ striyo ''nunayām āsa sāntvam uktvā punaḥ punaḥ', null, 6099042),
('ramayana-6-99-43', 43, 'Yuddha Kanda, Sarga 99, Verse 43', 'प्रविष्टासु च सर्वासु राक्षसीषु विभीषणः।
रामपार्श्वमुपागम्य तदातिष्ठद्विनीतवत्॥', 'praviṣṭāsu ca sarvāsu rākṣasīṣu vibhīṣaṇaḥ
rāmapārśvam upāgamya tadātiṣṭhad vinītavat', null, 6099043),
('ramayana-6-99-44', 44, 'Yuddha Kanda, Sarga 99, Verse 44', 'रामोऽपि सह सैन्येन ससुग्रीवः सलक्ष्मणः।
हर्षं लेभे रिपुं हत्वा यथा वृत्रं शतक्रतुः॥', 'rāmo ''pi saha sainyena sasugrīvaḥ salakṣmaṇaḥ
harṣaṃ lebhe ripuṃ hatvā yathā vṛtraṃ śatakratuḥ', null, 6099044)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 100 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-100-1', 1, 'Yuddha Kanda, Sarga 100, Verse 1', 'ते रावणवधं दृष्ट्वा देवगन्धर्वदानवाः।
जग्मुस्तैस्तैर्विमानैः स्वैः कथयन्तः शुभाः कथाः॥', 'te rāvaṇavadhaṃ dṛṣṭvā devagandharvadānavāḥ
jagmus tais tair vimānaiḥ svaiḥ kathayantaḥ śubhāḥ kathāḥ', null, 6100001),
('ramayana-6-100-2', 2, 'Yuddha Kanda, Sarga 100, Verse 2', 'रावणस्य वधं घोरं राघवस्य पराक्रमम्।
सुयुद्धं वानराणां च सुग्रीवस्य च मन्त्रितम्॥', 'rāvaṇasya vadhaṃ ghoraṃ rāghavasya parākramam
suyuddhaṃ vānarāṇāṃ ca sugrīvasya ca mantritam', null, 6100002),
('ramayana-6-100-3', 3, 'Yuddha Kanda, Sarga 100, Verse 3', 'अनुरागं च वीर्यं च सौमित्रेर्लक्ष्मणस्य च।
कथयन्तो महाभागा जग्मुर्हृष्टा यथागतम्॥', 'anurāgaṃ ca vīryaṃ ca saumitrer lakṣmaṇasya ca
kathayanto mahābhāgā jagmur hṛṣṭā yathāgatam', null, 6100003),
('ramayana-6-100-4', 4, 'Yuddha Kanda, Sarga 100, Verse 4', 'राघवस्तु रथं दिव्यमिन्द्रदत्तं शिखिप्रभम्।
अनुज्ञाय महाभागो मातलिं प्रत्यपूजयत्॥', 'rāghavas tu rathaṃ divyam indradattaṃ śikhiprabham
anujñāya mahābhāgo mātaliṃ pratyapūjayat', null, 6100004),
('ramayana-6-100-5', 5, 'Yuddha Kanda, Sarga 100, Verse 5', 'राघवेणाभ्यनुज्ञातो मातलिः शक्रसारथिः।
दिव्यं तं रथमास्थाय दिवमेवारुरोह सः॥', 'rāghaveṇābhyanujñāto mātaliḥ śakrasārathiḥ
divyaṃ taṃ ratham āsthāya divam evāruroha saḥ', null, 6100005),
('ramayana-6-100-6', 6, 'Yuddha Kanda, Sarga 100, Verse 6', 'तस्मिंस्तु दिवमारूढे सुरसारथिसत्तमे।
राघवः परमप्रीतः सुग्रीवं परिषस्वजे॥', 'tasmiṃs tu divam ārūḍhe surasārathisattame
rāghavaḥ paramaprītaḥ sugrīvaṃ pariṣasvaje', null, 6100006),
('ramayana-6-100-7', 7, 'Yuddha Kanda, Sarga 100, Verse 7', 'परिष्वज्य च सुग्रीवं लक्ष्मणेनाभिवादितः।
पूज्यमानो हरिश्रेष्ठैराजगाम बलालयम्॥', 'pariṣvajya ca sugrīvaṃ lakṣmaṇenābhivāditaḥ
pūjyamāno hariśreṣṭhair ājagāma balālayam', null, 6100007),
('ramayana-6-100-8', 8, 'Yuddha Kanda, Sarga 100, Verse 8', 'अब्रवीच्च तदा रामः समीपपरिवर्तिनम्।
सौमित्रिं सत्त्वसंपन्नं लक्ष्मणं दीप्ततेजसं॥', 'abravīc ca tadā rāmaḥ samīpaparivartinam
saumitriṃ sattvasaṃpannaṃ lakṣmaṇaṃ dīptatejasaṃ', null, 6100008),
('ramayana-6-100-9', 9, 'Yuddha Kanda, Sarga 100, Verse 9', 'विभीषणमिमं सौम्य लङ्कायामभिषेचय।
अनुरक्तं च भक्तं च मम चैवोपकारिणम्॥', 'vibhīṣaṇam imaṃ saumya laṅkāyām abhiṣecaya
anuraktaṃ ca bhaktaṃ ca mama caivopakāriṇam', null, 6100009),
('ramayana-6-100-10', 10, 'Yuddha Kanda, Sarga 100, Verse 10', 'एष मे परमः कामो यदिमं रावणानुजम्।
लङ्कायां सौम्य पश्येयमभिषिक्तं विभीषणम्॥', 'eṣa me paramaḥ kāmo yad imaṃ rāvaṇānujam
laṅkāyāṃ saumya paśyeyam abhiṣiktaṃ vibhīṣaṇam', null, 6100010),
('ramayana-6-100-11', 11, 'Yuddha Kanda, Sarga 100, Verse 11', 'एवमुक्तस्तु सौमित्री राघवेण महात्मना।
तथेत्युक्त्वा तु संहृष्टः सौवर्णं घटमाददे॥', 'evam uktas tu saumitrī rāghaveṇa mahātmanā
tathety uktvā tu saṃhṛṣṭaḥ sauvarṇaṃ ghaṭam ādade', null, 6100011),
('ramayana-6-100-12', 12, 'Yuddha Kanda, Sarga 100, Verse 12', 'घटेन तेन सौमित्रिरभ्यषिञ्चद्विभीषणम्।
लङ्कायां रक्षसां मध्ये राजानं रामशासनात्॥', 'ghaṭena tena saumitrir abhyaṣiñcad vibhīṣaṇam
laṅkāyāṃ rakṣasāṃ madhye rājānaṃ rāmaśāsanāt', null, 6100012),
('ramayana-6-100-13', 13, 'Yuddha Kanda, Sarga 100, Verse 13', 'अभ्यषिञ्चत्स धर्मात्मा शुद्धात्मानं विभीषणम्।
तस्यामात्या जहृषिरे भक्ता ये चास्य राक्षसाः॥', 'abhyaṣiñcat sa dharmātmā śuddhātmānaṃ vibhīṣaṇam
tasyāmātyā jahṛṣire bhaktā ye cāsya rākṣasāḥ', null, 6100013),
('ramayana-6-100-14', 14, 'Yuddha Kanda, Sarga 100, Verse 14', 'दृष्ट्वाभिषिक्तं लङ्कायां राक्षसेन्द्रं विभीषणम्।
राघवः परमां प्रीतिं जगाम सहलक्ष्मणः॥', 'dṛṣṭvābhiṣiktaṃ laṅkāyāṃ rākṣasendraṃ vibhīṣaṇam
rāghavaḥ paramāṃ prītiṃ jagāma sahalakṣmaṇaḥ', null, 6100014),
('ramayana-6-100-15', 15, 'Yuddha Kanda, Sarga 100, Verse 15', 'स तद्राज्यं महत्प्राप्य रामदत्तं विभीषणः।
प्रकृतीः सान्त्वयित्वा च ततो राममुपागमत्॥', 'sa tad rājyaṃ mahat prāpya rāmadattaṃ vibhīṣaṇaḥ
prakṛtīḥ sāntvayitvā ca tato rāmam upāgamat', null, 6100015),
('ramayana-6-100-16', 16, 'Yuddha Kanda, Sarga 100, Verse 16', 'अक्षतान्मोदकांल्लाजान्दिव्याः सुमनसस्तथा।
आजह्रुरथ संहृष्टाः पौरास्तस्मै निशाचराः॥', 'akṣatān modakāṃl lājān divyāḥ sumanasas tathā
ājahrur atha saṃhṛṣṭāḥ paurās tasmai niśācarāḥ', null, 6100016),
('ramayana-6-100-17', 17, 'Yuddha Kanda, Sarga 100, Verse 17', 'स तान्गृहीत्वा दुर्धर्षो राघवाय न्यवेदयत्।
मङ्गल्यं मङ्गलं सर्वं लक्ष्मणाय च वीर्यवान्॥', 'sa tān gṛhītvā durdharṣo rāghavāya nyavedayat
maṅgalyaṃ maṅgalaṃ sarvaṃ lakṣmaṇāya ca vīryavān', null, 6100017),
('ramayana-6-100-18', 18, 'Yuddha Kanda, Sarga 100, Verse 18', 'कृतकार्यं समृद्धार्थं दृष्ट्वा रामो विभीषणम्।
प्रतिजग्राह तत्सर्वं तस्यैव प्रियकाम्यया॥', 'kṛtakāryaṃ samṛddhārthaṃ dṛṣṭvā rāmo vibhīṣaṇam
pratijagrāha tat sarvaṃ tasyaiva priyakāmyayā', null, 6100018),
('ramayana-6-100-19', 19, 'Yuddha Kanda, Sarga 100, Verse 19', 'ततः शैलोपमं वीरं प्राञ्जलिं पार्श्वतः स्थितम्।
अब्रवीद्राघवो वाक्यं हनूमन्तं प्लवंगमम्॥', 'tataḥ śailopamaṃ vīraṃ prāñjaliṃ pārśvataḥ sthitam
abravīd rāghavo vākyaṃ hanūmantaṃ plavaṃgamam', null, 6100019),
('ramayana-6-100-20', 20, 'Yuddha Kanda, Sarga 100, Verse 20', 'अनुमान्य महाराजमिमं सौम्य विभीषणम्।
प्रविश्य रावणगृहं विनयेनोपसृत्य च॥', 'anumānya mahārājam imaṃ saumya vibhīṣaṇam
praviśya rāvaṇagṛhaṃ vinayenopasṛtya ca', null, 6100020),
('ramayana-6-100-21', 21, 'Yuddha Kanda, Sarga 100, Verse 21', 'वैदेह्या मां कुशलिनं ससुग्रीवं सलक्ष्मणम्।
आचक्ष्व जयतां श्रेष्ठ रावणं च मया हतम्॥', 'vaidehyā māṃ kuśalinaṃ sasugrīvaṃ salakṣmaṇam
ācakṣva jayatāṃ śreṣṭha rāvaṇaṃ ca mayā hatam', null, 6100021),
('ramayana-6-100-22', 22, 'Yuddha Kanda, Sarga 100, Verse 22', 'प्रियमेतदुदाहृत्य मैथिल्यास्त्वं हरीश्वर।
प्रतिगृह्य च संदेशमुपावर्तितुमर्हसि॥', 'priyam etad udāhṛtya maithilyās tvaṃ harīśvara
pratigṛhya ca saṃdeśam upāvartitum arhasi', null, 6100022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 101 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-101-1', 1, 'Yuddha Kanda, Sarga 101, Verse 1', 'इति प्रतिसमादिष्टो हनूमान्मारुतात्मजः।
प्रविवेश पुरीं लङ्कां पूज्यमानो निशाचरैः॥', 'iti pratisamādiṣṭo hanūmān mārutātmajaḥ
praviveśa purīṃ laṅkāṃ pūjyamāno niśācaraiḥ', null, 6101001),
('ramayana-6-101-2', 2, 'Yuddha Kanda, Sarga 101, Verse 2', 'प्रविश्य तु महातेजा रावणस्य निवेशनम्।
ददर्श शशिना हीनां सातङ्कामिव रोहिणीम्॥', 'praviśya tu mahātejā rāvaṇasya niveśanam
dadarśa śaśinā hīnāṃ sātaṅkām iva rohiṇīm', null, 6101002),
('ramayana-6-101-3', 3, 'Yuddha Kanda, Sarga 101, Verse 3', 'निभृतः प्रणतः प्रह्वः सोऽभिगम्याभिवाद्य च।
रामस्य वचनं सर्वमाख्यातुमुपचक्रमे॥', 'nibhṛtaḥ praṇataḥ prahvaḥ so ''bhigamyābhivādya ca
rāmasya vacanaṃ sarvam ākhyātum upacakrame', null, 6101003),
('ramayana-6-101-4', 4, 'Yuddha Kanda, Sarga 101, Verse 4', 'वैदेहि कुशली रामः ससुग्रीवः सलक्ष्मणः।
कुशलं चाह सिद्धार्थो हतशत्रुररिंदमः॥', 'vaidehi kuśalī rāmaḥ sasugrīvaḥ salakṣmaṇaḥ
kuśalaṃ cāha siddhārtho hataśatrur ariṃdamaḥ', null, 6101004),
('ramayana-6-101-5', 5, 'Yuddha Kanda, Sarga 101, Verse 5', 'विभीषणसहायेन रामेण हरिभिः सह।
निहतो रावणो देवि लक्ष्मणस्य नयेन च॥', 'vibhīṣaṇasahāyena rāmeṇa haribhiḥ saha
nihato rāvaṇo devi lakṣmaṇasya nayena ca', null, 6101005),
('ramayana-6-101-6', 6, 'Yuddha Kanda, Sarga 101, Verse 6', 'पृष्ट्वा च कुशलं रामो वीरस्त्वां रघुनन्दनः।
अब्रवीत्परमप्रीतः कृतार्थेनान्तरात्मना॥', 'pṛṣṭvā ca kuśalaṃ rāmo vīras tvāṃ raghunandanaḥ
abravīt paramaprītaḥ kṛtārthenāntarātmanā', null, 6101006),
('ramayana-6-101-7', 7, 'Yuddha Kanda, Sarga 101, Verse 7', 'प्रियमाख्यामि ते देवि त्वां तु भूयः सभाजये।
दिष्ट्या जीवसि धर्मज्ञे जयेन मम संयुगे॥', 'priyam ākhyāmi te devi tvāṃ tu bhūyaḥ sabhājaye
diṣṭyā jīvasi dharmajñe jayena mama saṃyuge', null, 6101007),
('ramayana-6-101-8', 8, 'Yuddha Kanda, Sarga 101, Verse 8', 'लब्धो नो विजयः सीते स्वस्था भव गतव्यथा।
रावणः स हतः शत्रुर्लङ्का चेयं वशे स्थिता॥', 'labdho no vijayaḥ sīte svasthā bhava gatavyathā
rāvaṇaḥ sa hataḥ śatrur laṅkā ceyaṃ vaśe sthitā', null, 6101008),
('ramayana-6-101-9', 9, 'Yuddha Kanda, Sarga 101, Verse 9', 'मया ह्यलब्धनिद्रेण धृतेन तव निर्जये।
प्रतिज्ञैषा विनिस्तीर्णा बद्ध्वा सेतुं महोदधौ॥', 'mayā hy alabdhanidreṇa dhṛtena tava nirjaye
pratijñaiṣā vinistīrṇā baddhvā setuṃ mahodadhau', null, 6101009),
('ramayana-6-101-10', 10, 'Yuddha Kanda, Sarga 101, Verse 10', 'संभ्रमश्च न कर्तव्यो वर्तन्त्या रावणालये।
विभीषणविधेयं हि लङ्कैश्वर्यमिदं कृतम्॥', 'saṃbhramaś ca na kartavyo vartantyā rāvaṇālaye
vibhīṣaṇavidheyaṃ hi laṅkaiśvaryam idaṃ kṛtam', null, 6101010),
('ramayana-6-101-11', 11, 'Yuddha Kanda, Sarga 101, Verse 11', 'तदाश्वसिहि विश्वस्ता स्वगृहे परिवर्तसे।
अयं चाभ्येति संहृष्टस्त्वद्दर्शनसमुत्सुकः॥', 'tad āśvasihi viśvastā svagṛhe parivartase
ayaṃ cābhyeti saṃhṛṣṭas tvaddarśanasamutsukaḥ', null, 6101011),
('ramayana-6-101-12', 12, 'Yuddha Kanda, Sarga 101, Verse 12', 'एवमुक्ता समुत्पत्य सीता शशिनिभानना।
प्रहर्षेणावरुद्धा सा व्याजहार न किं चन॥', 'evam uktā samutpatya sītā śaśinibhānanā
praharṣeṇāvaruddhā sā vyājahāra na kiṃ cana', null, 6101012),
('ramayana-6-101-13', 13, 'Yuddha Kanda, Sarga 101, Verse 13', 'अब्रवीच्च हरिश्रेष्ठः सीतामप्रतिजल्पतीम्।
किं त्वं चिन्तयसे देवि किं च मां नाभिभाषसे॥', 'abravīc ca hariśreṣṭhaḥ sītām apratijalpatīm
kiṃ tvaṃ cintayase devi kiṃ ca māṃ nābhibhāṣase', null, 6101013),
('ramayana-6-101-14', 14, 'Yuddha Kanda, Sarga 101, Verse 14', 'एवमुक्ता हनुमता सीता धर्मे व्यवस्थिता।
अब्रवीत्परमप्रीता हर्षगद्गदया गिरा॥', 'evam uktā hanumatā sītā dharme vyavasthitā
abravīt paramaprītā harṣagadgadayā girā', null, 6101014),
('ramayana-6-101-15', 15, 'Yuddha Kanda, Sarga 101, Verse 15', 'प्रियमेतदुपश्रुत्य भर्तुर्विजयसंश्रितम्।
प्रहर्षवशमापन्ना निर्वाक्यास्मि क्षणान्तरम्॥', 'priyam etad upaśrutya bhartur vijayasaṃśritam
praharṣavaśam āpannā nirvākyāsmi kṣaṇāntaram', null, 6101015),
('ramayana-6-101-16', 16, 'Yuddha Kanda, Sarga 101, Verse 16', 'न हि पश्यामि सदृशं चिन्तयन्ती प्लवंगम।
मत्प्रियाख्यानकस्येह तव प्रत्यभिनन्दनम्॥', 'na hi paśyāmi sadṛśaṃ cintayantī plavaṃgama
matpriyākhyānakasyeha tava pratyabhinandanam', null, 6101016),
('ramayana-6-101-17', 17, 'Yuddha Kanda, Sarga 101, Verse 17', 'न च पश्यामि तत्सौम्य पृथिव्यामपि वानर।
सदृशं मत्प्रियाख्याने तव दातुं भवेत्समम्॥', 'na ca paśyāmi tat saumya pṛthivyām api vānara
sadṛśaṃ matpriyākhyāne tava dātuṃ bhavet samam', null, 6101017),
('ramayana-6-101-18', 18, 'Yuddha Kanda, Sarga 101, Verse 18', 'हिरण्यं वा सुवर्णं वा रत्नानि विविधानि च।
राज्यं वा त्रिषु लोकेषु नैतदर्हति भाषितुम्॥', 'hiraṇyaṃ vā suvarṇaṃ vā ratnāni vividhāni ca
rājyaṃ vā triṣu lokeṣu naitad arhati bhāṣitum', null, 6101018),
('ramayana-6-101-19', 19, 'Yuddha Kanda, Sarga 101, Verse 19', 'एवमुक्तस्तु वैदेह्या प्रत्युवाच प्लवंगमः।
प्रगृहीताञ्जलिर्वाक्यं सीतायाः प्रमुखे स्थितः॥', 'evam uktas tu vaidehyā pratyuvāca plavaṃgamaḥ
pragṛhītāñjalir vākyaṃ sītāyāḥ pramukhe sthitaḥ', null, 6101019),
('ramayana-6-101-20', 20, 'Yuddha Kanda, Sarga 101, Verse 20', 'भर्तुः प्रियहिते युक्ते भर्तुर्विजयकाङ्क्षिणि।
स्निग्धमेवंविधं वाक्यं त्वमेवार्हसि भाषितुम्॥', 'bhartuḥ priyahite yukte bhartur vijayakāṅkṣiṇi
snigdham evaṃvidhaṃ vākyaṃ tvam evārhasi bhāṣitum', null, 6101020),
('ramayana-6-101-21', 21, 'Yuddha Kanda, Sarga 101, Verse 21', 'तवैतद्वचनं सौम्ये सारवत्स्निग्धमेव च।
रत्नौघाद्विविधाच्चापि देवराज्याद्विशिष्यते॥', 'tavaitad vacanaṃ saumye sāravat snigdham eva ca
ratnaughād vividhāc cāpi devarājyād viśiṣyate', null, 6101021),
('ramayana-6-101-22', 22, 'Yuddha Kanda, Sarga 101, Verse 22', 'अर्थतश्च मया प्राप्ता देवराज्यादयो गुणाः।
हतशत्रुं विजयिनं रामं पश्यामि यत्स्थितम्॥', 'arthataś ca mayā prāptā devarājyādayo guṇāḥ
hataśatruṃ vijayinaṃ rāmaṃ paśyāmi yat sthitam', null, 6101022),
('ramayana-6-101-23', 23, 'Yuddha Kanda, Sarga 101, Verse 23', 'इमास्तु खलु राक्षस्यो यदि त्वमनुमन्यसे।
हन्तुमिच्छाम्यहं सर्वा याभिस्त्वं तर्जिता पुरा॥', 'imās tu khalu rākṣasyo yadi tvam anumanyase
hantum icchāmy ahaṃ sarvā yābhis tvaṃ tarjitā purā', null, 6101023),
('ramayana-6-101-24', 24, 'Yuddha Kanda, Sarga 101, Verse 24', 'क्लिश्यन्तीं पतिदेवां त्वामशोकवनिकां गताम्।
घोररूपसमाचाराः क्रूराः क्रूरतरेक्षणाः॥', 'kliśyantīṃ patidevāṃ tvām aśokavanikāṃ gatām
ghorarūpasamācārāḥ krūrāḥ krūratarekṣaṇāḥ', null, 6101024),
('ramayana-6-101-25', 25, 'Yuddha Kanda, Sarga 101, Verse 25', 'राक्षस्यो दारुणकथा वरमेतं प्रयच्छ मे।
इच्छामि विविधैर्घातैर्हन्तुमेताः सुदारुणाः॥', 'rākṣasyo dāruṇakathā varam etaṃ prayaccha me
icchāmi vividhair ghātair hantum etāḥ sudāruṇāḥ', null, 6101025),
('ramayana-6-101-26', 26, 'Yuddha Kanda, Sarga 101, Verse 26', 'मुष्टिभिः पाणिभिश्चैव चरणैश्चैव शोभने।
घोरैर्जानुप्रहारैश्च दशनानां च पातनैः॥', 'muṣṭibhiḥ pāṇibhiś caiva caraṇaiś caiva śobhane
ghorair jānuprahāraiś ca daśanānāṃ ca pātanaiḥ', null, 6101026),
('ramayana-6-101-27', 27, 'Yuddha Kanda, Sarga 101, Verse 27', 'भक्षणैः कर्णनासानां केशानां लुञ्चनैस्तथा।
भृशं शुष्कमुखीभिश्च दारुणैर्लङ्घनैर्हतैः॥', 'bhakṣaṇaiḥ karṇanāsānāṃ keśānāṃ luñcanais tathā
bhṛśaṃ śuṣkamukhībhiś ca dāruṇair laṅghanair hataiḥ', null, 6101027),
('ramayana-6-101-28', 28, 'Yuddha Kanda, Sarga 101, Verse 28', 'एवंप्रकारैर्बहुभिर्विप्रकारैर्यशस्विनि।
हन्तुमिच्छाम्यहं देवि तवेमाः कृतकिल्बिषाः॥', 'evaṃprakārair bahubhir viprakārair yaśasvini
hantum icchāmy ahaṃ devi tavemāḥ kṛtakilbiṣāḥ', null, 6101028),
('ramayana-6-101-29', 29, 'Yuddha Kanda, Sarga 101, Verse 29', 'एवमुक्ता महुमता वैदेही जनकात्मजा।
उवाच धर्मसहितं हनूमन्तं यशस्विनी॥', 'evam uktā mahumatā vaidehī janakātmajā
uvāca dharmasahitaṃ hanūmantaṃ yaśasvinī', null, 6101029),
('ramayana-6-101-30', 30, 'Yuddha Kanda, Sarga 101, Verse 30', 'राजसंश्रयवश्यानां कुर्वतीनां पराज्ञया।
विधेयानां च दासीनां कः कुप्येद्वानरोत्तम॥', 'rājasaṃśrayavaśyānāṃ kurvatīnāṃ parājñayā
vidheyānāṃ ca dāsīnāṃ kaḥ kupyed vānarottama', null, 6101030),
('ramayana-6-101-31', 31, 'Yuddha Kanda, Sarga 101, Verse 31', 'भाग्यवैषम्ययोगेन पुरा दुश्चरितेन च।
मयैतत्प्राप्यते सर्वं स्वकृतं ह्युपभुज्यते॥', 'bhāgyavaiṣamyayogena purā duścaritena ca
mayaitat prāpyate sarvaṃ svakṛtaṃ hy upabhujyate', null, 6101031),
('ramayana-6-101-32', 32, 'Yuddha Kanda, Sarga 101, Verse 32', 'प्राप्तव्यं तु दशायोगान्मयैतदिति निश्चितम्।
दासीनां रावणस्याहं मर्षयामीह दुर्बला॥', 'prāptavyaṃ tu daśāyogān mayaitad iti niścitam
dāsīnāṃ rāvaṇasyāhaṃ marṣayāmīha durbalā', null, 6101032),
('ramayana-6-101-33', 33, 'Yuddha Kanda, Sarga 101, Verse 33', 'आज्ञप्ता रावणेनैता राक्षस्यो मामतर्जयन्।
हते तस्मिन्न कुर्युर्हि तर्जनं वानरोत्तम॥', 'ājñaptā rāvaṇenaitā rākṣasyo mām atarjayan
hate tasmin na kuryur hi tarjanaṃ vānarottama', null, 6101033),
('ramayana-6-101-34', 34, 'Yuddha Kanda, Sarga 101, Verse 34', 'अयं व्याघ्रसमीपे तु पुराणो धर्मसंहितः।
ऋक्षेण गीतः श्लोको मे तं निबोध प्लवंगम॥', 'ayaṃ vyāghrasamīpe tu purāṇo dharmasaṃhitaḥ
ṛkṣeṇa gītaḥ śloko me taṃ nibodha plavaṃgama', null, 6101034),
('ramayana-6-101-35', 35, 'Yuddha Kanda, Sarga 101, Verse 35', 'न परः पापमादत्ते परेषां पापकर्मणाम्।
समयो रक्षितव्यस्तु सन्तश्चारित्रभूषणाः॥', 'na paraḥ pāpam ādatte pareṣāṃ pāpakarmaṇām
samayo rakṣitavyas tu santaś cāritrabhūṣaṇāḥ', null, 6101035),
('ramayana-6-101-36', 36, 'Yuddha Kanda, Sarga 101, Verse 36', 'पापानां वा शुभानां वा वधार्हाणां प्लवंगम।
कार्यं कारुण्यमार्येण न कश्चिन्नापराध्यति॥', 'pāpānāṃ vā śubhānāṃ vā vadhārhāṇāṃ plavaṃgama
kāryaṃ kāruṇyam āryeṇa na kaś cin nāparādhyati', null, 6101036),
('ramayana-6-101-37', 37, 'Yuddha Kanda, Sarga 101, Verse 37', 'लोकहिंसाविहाराणां रक्षसां कामरूपिणम्।
कुर्वतामपि पापानि नैव कार्यमशोभनम्॥', 'lokahiṃsāvihārāṇāṃ rakṣasāṃ kāmarūpiṇam
kurvatām api pāpāni naiva kāryam aśobhanam', null, 6101037),
('ramayana-6-101-38', 38, 'Yuddha Kanda, Sarga 101, Verse 38', 'एवमुक्तस्तु हनुमान्सीतया वाक्यकोविदः।
प्रत्युवाच ततः सीतां रामपत्नीं यशस्विनीम्॥', 'evam uktas tu hanumān sītayā vākyakovidaḥ
pratyuvāca tataḥ sītāṃ rāmapatnīṃ yaśasvinīm', null, 6101038),
('ramayana-6-101-39', 39, 'Yuddha Kanda, Sarga 101, Verse 39', 'युक्ता रामस्य भवती धर्मपत्नी यशस्विनी।
प्रतिसंदिश मां देवि गमिष्ये यत्र राघवः॥', 'yuktā rāmasya bhavatī dharmapatnī yaśasvinī
pratisaṃdiśa māṃ devi gamiṣye yatra rāghavaḥ', null, 6101039),
('ramayana-6-101-40', 40, 'Yuddha Kanda, Sarga 101, Verse 40', 'एवमुक्ता हनुमता वैदेही जनकात्मजा।
अब्रवीद्द्रष्टुमिच्छामि भर्तारं वानरोत्तम॥', 'evam uktā hanumatā vaidehī janakātmajā
abravīd draṣṭum icchāmi bhartāraṃ vānarottama', null, 6101040),
('ramayana-6-101-41', 41, 'Yuddha Kanda, Sarga 101, Verse 41', 'तस्यास्तद्वचनं श्रुत्वा हनुमान्पवनात्मजः।
हर्षयन्मैथिलीं वाक्यमुवाचेदं महाद्युतिः॥', 'tasyās tad vacanaṃ śrutvā hanumān pavanātmajaḥ
harṣayan maithilīṃ vākyam uvācedaṃ mahādyutiḥ', null, 6101041),
('ramayana-6-101-42', 42, 'Yuddha Kanda, Sarga 101, Verse 42', 'पूर्णचन्द्राननं रामं द्रक्ष्यस्यार्ये सलक्ष्मणम्।
स्थिरमित्रं हतामित्रं शचीव त्रिदशेश्वरम्॥', 'pūrṇacandrānanaṃ rāmaṃ drakṣyasy ārye salakṣmaṇam
sthiramitraṃ hatāmitraṃ śacīva tridaśeśvaram', null, 6101042),
('ramayana-6-101-43', 43, 'Yuddha Kanda, Sarga 101, Verse 43', 'तामेवमुक्त्वा राजन्तीं सीतां साक्षादिव श्रियम्।
आजगाम महावेगो हनूमान्यत्र राघवः॥', 'tām evam uktvā rājantīṃ sītāṃ sākṣād iva śriyam
ājagāma mahāvego hanūmān yatra rāghavaḥ', null, 6101043)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 102 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-102-1', 1, 'Yuddha Kanda, Sarga 102, Verse 1', 'स उवाच महाप्रज्ञमभिगम्य प्लवंगमः।
रामं वचनमर्थज्ञो वरं सर्वधनुष्मताम्॥', 'sa uvāca mahāprajñam abhigamya plavaṃgamaḥ
rāmaṃ vacanam arthajño varaṃ sarvadhanuṣmatām', null, 6102001),
('ramayana-6-102-2', 2, 'Yuddha Kanda, Sarga 102, Verse 2', 'यन्निमित्तोऽयमारम्भः कर्मणां च फलोदयः।
तां देवीं शोकसंतप्तां मैथिलीं द्रष्टुमर्हसि॥', 'yannimitto ''yam ārambhaḥ karmaṇāṃ ca phalodayaḥ
tāṃ devīṃ śokasaṃtaptāṃ maithilīṃ draṣṭum arhasi', null, 6102002),
('ramayana-6-102-3', 3, 'Yuddha Kanda, Sarga 102, Verse 3', 'सा हि शोकसमाविष्टा बाष्पपर्याकुलेक्षणा।
मैथिली विजयं श्रुत्वा तव हर्षमुपागमत्॥', 'sā hi śokasamāviṣṭā bāṣpaparyākulekṣaṇā
maithilī vijayaṃ śrutvā tava harṣam upāgamat', null, 6102003),
('ramayana-6-102-4', 4, 'Yuddha Kanda, Sarga 102, Verse 4', 'पूर्वकात्प्रत्ययाच्चाहमुक्तो विश्वस्तया तया।
भर्तारं द्रष्टुमिच्छामि कृतार्थं सहलक्ष्मणम्॥', 'pūrvakāt pratyayāc cāham ukto viśvastayā tayā
bhartāraṃ draṣṭum icchāmi kṛtārthaṃ sahalakṣmaṇam', null, 6102004),
('ramayana-6-102-5', 5, 'Yuddha Kanda, Sarga 102, Verse 5', 'एवमुक्तो हनुमता रामो धर्मभृतां वरः।
अगच्छत्सहसा ध्यानमासीद्बाष्पपरिप्लुतः॥', 'evam ukto hanumatā rāmo dharmabhṛtāṃ varaḥ
agacchat sahasā dhyānam āsīd bāṣpapariplutaḥ', null, 6102005),
('ramayana-6-102-6', 6, 'Yuddha Kanda, Sarga 102, Verse 6', 'दीर्घमुष्णं च निश्वस्य मेदिनीमवलोकयन्।
उवाच मेघसंकाशं विभीषणमुपस्थितम्॥', 'dīrgham uṣṇaṃ ca niśvasya medinīm avalokayan
uvāca meghasaṃkāśaṃ vibhīṣaṇam upasthitam', null, 6102006),
('ramayana-6-102-7', 7, 'Yuddha Kanda, Sarga 102, Verse 7', 'दिव्याङ्गरागां वैदेहीं दिव्याभरणभूषिताम्।
इह सीतां शिरःस्नातामुपस्थापय माचिरम्॥', 'divyāṅgarāgāṃ vaidehīṃ divyābharaṇabhūṣitām
iha sītāṃ śiraḥsnātām upasthāpaya māciram', null, 6102007),
('ramayana-6-102-8', 8, 'Yuddha Kanda, Sarga 102, Verse 8', 'एवमुक्तस्तु रामेण त्वरमाणो विभीषणः।
प्रविश्यान्तःपुरं सीतां स्त्रीभिः स्वाभिरचोदयत्॥', 'evam uktas tu rāmeṇa tvaramāṇo vibhīṣaṇaḥ
praviśyāntaḥpuraṃ sītāṃ strībhiḥ svābhir acodayat', null, 6102008),
('ramayana-6-102-9', 9, 'Yuddha Kanda, Sarga 102, Verse 9', 'दिव्याङ्गरागा वैदेही दिव्याभरणभूषिता।
यानमारोह भद्रं ते भर्ता त्वां द्रष्टुमिच्छति॥', 'divyāṅgarāgā vaidehī divyābharaṇabhūṣitā
yānam āroha bhadraṃ te bhartā tvāṃ draṣṭum icchati', null, 6102009),
('ramayana-6-102-10', 10, 'Yuddha Kanda, Sarga 102, Verse 10', 'एवमुक्ता तु वैदेही प्रत्युवाच विभीषणम्।
अस्नाता द्रष्टुमिच्छामि भर्तारं राक्षसाधिप॥', 'evam uktā tu vaidehī pratyuvāca vibhīṣaṇam
asnātā draṣṭum icchāmi bhartāraṃ rākṣasādhipa', null, 6102010),
('ramayana-6-102-11', 11, 'Yuddha Kanda, Sarga 102, Verse 11', 'तस्यास्तद्वचनं श्रुत्वा प्रत्युवाच विभीषणः।
यथाह रामो भर्ता ते तत्तथा कर्तुमर्हसि॥', 'tasyās tad vacanaṃ śrutvā pratyuvāca vibhīṣaṇaḥ
yathāha rāmo bhartā te tat tathā kartum arhasi', null, 6102011),
('ramayana-6-102-12', 12, 'Yuddha Kanda, Sarga 102, Verse 12', 'तस्य तद्वचनं श्रुत्वा मैथिली भर्तृदेवता।
भर्तृभक्तिव्रता साध्वी तथेति प्रत्यभाषत॥', 'tasya tad vacanaṃ śrutvā maithilī bhartṛdevatā
bhartṛbhaktivratā sādhvī tatheti pratyabhāṣata', null, 6102012),
('ramayana-6-102-13', 13, 'Yuddha Kanda, Sarga 102, Verse 13', 'ततः सीतां शिरःस्नातां युवतीभिरलंकृताम्।
महार्हाभरणोपेतां महार्हाम्बरधारिणीम्॥', 'tataḥ sītāṃ śiraḥsnātāṃ yuvatībhir alaṃkṛtām
mahārhābharaṇopetāṃ mahārhāmbaradhāriṇīm', null, 6102013),
('ramayana-6-102-14', 14, 'Yuddha Kanda, Sarga 102, Verse 14', 'आरोप्य शिबिकां दीप्तां परार्ध्याम्बरसंवृताम्।
रक्षोभिर्बहुभिर्गुप्तामाजहार विभीषणः॥', 'āropya śibikāṃ dīptāṃ parārdhyāmbarasaṃvṛtām
rakṣobhir bahubhir guptām ājahāra vibhīṣaṇaḥ', null, 6102014),
('ramayana-6-102-15', 15, 'Yuddha Kanda, Sarga 102, Verse 15', 'सोऽभिगम्य महात्मानं ज्ञात्वाभिध्यानमास्थितम्।
प्रणतश्च प्रहृष्टश्च प्राप्तां सीतां न्यवेदयत्॥', 'so ''bhigamya mahātmānaṃ jñātvābhidhyānam āsthitam
praṇataś ca prahṛṣṭaś ca prāptāṃ sītāṃ nyavedayat', null, 6102015),
('ramayana-6-102-16', 16, 'Yuddha Kanda, Sarga 102, Verse 16', 'तामागतामुपश्रुत्य रक्षोगृहचिरोषिताम्।
हर्षो दैन्यं च रोषश्च त्रयं राघवमाविशत्॥', 'tām āgatām upaśrutya rakṣogṛhaciroṣitām
harṣo dainyaṃ ca roṣaś ca trayaṃ rāghavam āviśat', null, 6102016),
('ramayana-6-102-17', 17, 'Yuddha Kanda, Sarga 102, Verse 17', 'ततः पार्श्वगतं दृष्ट्वा सविमर्शं विचारयन्।
विभीषणमिदं वाक्यमहृष्टो राघवोऽब्रवीत्॥', 'tataḥ pārśvagataṃ dṛṣṭvā savimarśaṃ vicārayan
vibhīṣaṇam idaṃ vākyam ahṛṣṭo rāghavo ''bravīt', null, 6102017),
('ramayana-6-102-18', 18, 'Yuddha Kanda, Sarga 102, Verse 18', 'राक्षसाधिपते सौम्य नित्यं मद्विजये रत।
वैदेही संनिकर्षं मे शीघ्रं समुपगच्छतु॥', 'rākṣasādhipate saumya nityaṃ madvijaye rata
vaidehī saṃnikarṣaṃ me śīghraṃ samupagacchatu', null, 6102018),
('ramayana-6-102-19', 19, 'Yuddha Kanda, Sarga 102, Verse 19', 'स तद्वचनमाज्ञाय राघवस्य विभीषणः।
तूर्णमुत्सारणे यत्नं कारयामास सर्वतः॥', 'sa tad vacanam ājñāya rāghavasya vibhīṣaṇaḥ
tūrṇam utsāraṇe yatnaṃ kārayām āsa sarvataḥ', null, 6102019),
('ramayana-6-102-20', 20, 'Yuddha Kanda, Sarga 102, Verse 20', 'कञ्चुकोष्णीषिणस्तत्र वेत्रझर्झरपाणयः।
उत्सारयन्तः पुरुषाः समन्तात्परिचक्रमुः॥', 'kañcukoṣṇīṣiṇas tatra vetrajharjharapāṇayaḥ
utsārayantaḥ puruṣāḥ samantāt paricakramuḥ', null, 6102020),
('ramayana-6-102-21', 21, 'Yuddha Kanda, Sarga 102, Verse 21', 'ऋक्षाणां वानराणां च राक्षसानां च सर्वतः।
वृन्दान्युत्सार्यमाणानि दूरमुत्ससृजुस्ततः॥', 'ṛkṣāṇāṃ vānarāṇāṃ ca rākṣasānāṃ ca sarvataḥ
vṛndāny utsāryamāṇāni dūram utsasṛjus tataḥ', null, 6102021),
('ramayana-6-102-22', 22, 'Yuddha Kanda, Sarga 102, Verse 22', 'तेषामुत्सार्यमाणानां सर्वेषां ध्वनिरुत्थितः।
वायुनोद्वर्तमानस्य सागरस्येव निस्वनः॥', 'teṣām utsāryamāṇānāṃ sarveṣāṃ dhvanir utthitaḥ
vāyunodvartamānasya sāgarasyeva nisvanaḥ', null, 6102022),
('ramayana-6-102-23', 23, 'Yuddha Kanda, Sarga 102, Verse 23', 'उत्सार्यमाणांस्तान्दृष्ट्वा समन्ताज्जातसंभ्रमान्।
दाक्षिण्यात्तदमर्षाच्च वारयामास राघवः॥', 'utsāryamāṇāṃs tān dṛṣṭvā samantāj jātasaṃbhramān
dākṣiṇyāt tadamarṣāc ca vārayām āsa rāghavaḥ', null, 6102023),
('ramayana-6-102-24', 24, 'Yuddha Kanda, Sarga 102, Verse 24', 'संरब्धश्चाब्रवीद्रामश्चक्षुषा प्रदहन्निव।
विभीषणं महाप्राज्ञं सोपालम्भमिदं वचः॥', 'saṃrabdhaś cābravīd rāmaś cakṣuṣā pradahann iva
vibhīṣaṇaṃ mahāprājñaṃ sopālambham idaṃ vacaḥ', null, 6102024),
('ramayana-6-102-25', 25, 'Yuddha Kanda, Sarga 102, Verse 25', 'किमर्थं मामनादृत्य कृश्यतेऽयं त्वया जनः।
निवर्तयैनमुद्योगं जनोऽयं स्वजनो मम॥', 'kimarthaṃ mām anādṛtya kṛśyate ''yaṃ tvayā janaḥ
nivartayainam udyogaṃ jano ''yaṃ svajano mama', null, 6102025),
('ramayana-6-102-26', 26, 'Yuddha Kanda, Sarga 102, Verse 26', 'न गृहाणि न वस्त्राणि न प्राकारास्तिरस्क्रियाः।
नेदृशा राजसत्कारा वृत्तमावरणं स्त्रियः॥', 'na gṛhāṇi na vastrāṇi na prākārās tiraskriyāḥ
nedṛśā rājasatkārā vṛttam āvaraṇaṃ striyaḥ', null, 6102026),
('ramayana-6-102-27', 27, 'Yuddha Kanda, Sarga 102, Verse 27', 'व्यसनेषु न कृच्छ्रेषु न युद्धे न स्वयंवरे।
न क्रतौ नो विवाहे च दर्शनं दुष्यते स्त्रियः॥', 'vyasaneṣu na kṛcchreṣu na yuddhe na svayaṃvare
na kratau no vivāhe ca darśanaṃ duṣyate striyaḥ', null, 6102027),
('ramayana-6-102-28', 28, 'Yuddha Kanda, Sarga 102, Verse 28', 'सैषा युद्धगता चैव कृच्छ्रे महति च स्थिता।
दर्शनेऽस्या न दोषः स्यान्मत्समीपे विशेषतः॥', 'saiṣā yuddhagatā caiva kṛcchre mahati ca sthitā
darśane ''syā na doṣaḥ syān matsamīpe viśeṣataḥ', null, 6102028),
('ramayana-6-102-29', 29, 'Yuddha Kanda, Sarga 102, Verse 29', 'तदानय समीपं मे शीघ्रमेनां विभीषण।
सीता पश्यतु मामेषा सुहृद्गणवृतं स्थितम्॥', 'tad ānaya samīpaṃ me śīghram enāṃ vibhīṣaṇa
sītā paśyatu mām eṣā suhṛdgaṇavṛtaṃ sthitam', null, 6102029),
('ramayana-6-102-30', 30, 'Yuddha Kanda, Sarga 102, Verse 30', 'एवमुक्तस्तु रामेण सविमर्शो विभीषणः।
रामस्योपानयत्सीतां संनिकर्षं विनीतवत्॥', 'evam uktas tu rāmeṇa savimarśo vibhīṣaṇaḥ
rāmasyopānayat sītāṃ saṃnikarṣaṃ vinītavat', null, 6102030),
('ramayana-6-102-31', 31, 'Yuddha Kanda, Sarga 102, Verse 31', 'ततो लक्ष्मणसुग्रीवौ हनूमांश्च प्लवंगमः।
निशम्य वाक्यं रामस्य बभूवुर्व्यथिता भृशम्॥', 'tato lakṣmaṇasugrīvau hanūmāṃś ca plavaṃgamaḥ
niśamya vākyaṃ rāmasya babhūvur vyathitā bhṛśam', null, 6102031),
('ramayana-6-102-32', 32, 'Yuddha Kanda, Sarga 102, Verse 32', 'कलत्रनिरपेक्षैश्च इङ्गितैरस्य दारुणैः।
अप्रीतमिव सीतायां तर्कयन्ति स्म राघवम्॥', 'kalatranirapekṣaiś ca iṅgitair asya dāruṇaiḥ
aprītam iva sītāyāṃ tarkayanti sma rāghavam', null, 6102032),
('ramayana-6-102-33', 33, 'Yuddha Kanda, Sarga 102, Verse 33', 'लज्जया त्ववलीयन्ती स्वेषु गात्रेषु मैथिली।
विभीषणेनानुगता भर्तारं साभ्यवर्तत॥', 'lajjayā tv avalīyantī sveṣu gātreṣu maithilī
vibhīṣaṇenānugatā bhartāraṃ sābhyavartata', null, 6102033),
('ramayana-6-102-34', 34, 'Yuddha Kanda, Sarga 102, Verse 34', 'सा वस्त्रसंरुद्धमुखी लज्जया जनसंसदि।
रुरोदासाद्य भर्तारमार्यपुत्रेति भाषिणी॥', 'sā vastrasaṃruddhamukhī lajjayā janasaṃsadi
rurodāsādya bhartāram āryaputreti bhāṣiṇī', null, 6102034),
('ramayana-6-102-35', 35, 'Yuddha Kanda, Sarga 102, Verse 35', 'विस्मयाच्च प्रहर्षाच्च स्नेहाच्च परिदेवता।
उदैक्षत मुखं भर्तुः सौम्यं सौम्यतरानना॥', 'vismayāc ca praharṣāc ca snehāc ca paridevatā
udaikṣata mukhaṃ bhartuḥ saumyaṃ saumyatarānanā', null, 6102035),
('ramayana-6-102-36', 36, 'Yuddha Kanda, Sarga 102, Verse 36', 'अथ समपनुदन्मनःक्लमं सा सुचिरमदृष्टमुदीक्ष्य वै प्रियस्य।
वदनमुदितपूर्णचन्द्रकान्तं विमलशशाङ्कनिभानना तदासीत्॥', 'atha samapanudan manaḥklamaṃ sā suciram adṛṣṭam udīkṣya vai priyasya
vadanam uditapūrṇacandrakāntaṃ vimalaśaśāṅkanibhānanā tadāsīt', null, 6102036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 103 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-103-1', 1, 'Yuddha Kanda, Sarga 103, Verse 1', 'तां तु पार्श्वे स्थितां प्रह्वां रामः संप्रेक्ष्य मैथिलीम्।
हृदयान्तर्गतक्रोधो व्याहर्तुमुपचक्रमे॥', 'tāṃ tu pārśve sthitāṃ prahvāṃ rāmaḥ saṃprekṣya maithilīm
hṛdayāntargatakrodho vyāhartum upacakrame', null, 6103001),
('ramayana-6-103-2', 2, 'Yuddha Kanda, Sarga 103, Verse 2', 'एषासि निर्जिता भद्रे शत्रुं जित्वा मया रणे।
पौरुषाद्यदनुष्ठेयं तदेतदुपपादितम्॥', 'eṣāsi nirjitā bhadre śatruṃ jitvā mayā raṇe
pauruṣād yad anuṣṭheyaṃ tad etad upapāditam', null, 6103002),
('ramayana-6-103-3', 3, 'Yuddha Kanda, Sarga 103, Verse 3', 'गतोऽस्म्यन्तममर्षस्य धर्षणा संप्रमार्जिता।
अवमानश्च शत्रुश्च मया युगपदुद्धृतौ॥', 'gato ''smy antam amarṣasya dharṣaṇā saṃpramārjitā
avamānaś ca śatruś ca mayā yugapad uddhṛtau', null, 6103003),
('ramayana-6-103-4', 4, 'Yuddha Kanda, Sarga 103, Verse 4', 'अद्य मे पौरुषं दृष्टमद्य मे सफलः श्रमः।
अद्य तीर्णप्रतिज्ञत्वात्प्रभवामीह चात्मनः॥', 'adya me pauruṣaṃ dṛṣṭam adya me saphalaḥ śramaḥ
adya tīrṇapratijñatvāt prabhavāmīha cātmanaḥ', null, 6103004),
('ramayana-6-103-5', 5, 'Yuddha Kanda, Sarga 103, Verse 5', 'या त्वं विरहिता नीता चलचित्तेन रक्षसा।
दैवसंपादितो दोषो मानुषेण मया जितः॥', 'yā tvaṃ virahitā nītā calacittena rakṣasā
daivasaṃpādito doṣo mānuṣeṇa mayā jitaḥ', null, 6103005),
('ramayana-6-103-6', 6, 'Yuddha Kanda, Sarga 103, Verse 6', 'संप्राप्तमवमानं यस्तेजसा न प्रमार्जति।
कस्तस्य पुरुषार्थोऽस्ति पुरुषस्याल्पतेजसः॥', 'saṃprāptam avamānaṃ yas tejasā na pramārjati
kas tasya puruṣārtho ''sti puruṣasyālpatejasaḥ', null, 6103006),
('ramayana-6-103-7', 7, 'Yuddha Kanda, Sarga 103, Verse 7', 'लङ्घनं च समुद्रस्य लङ्कायाश्चावमर्दनम्।
सफलं तस्य तच्छ्लाघ्यमद्य कर्म हनूमतः॥', 'laṅghanaṃ ca samudrasya laṅkāyāś cāvamardanam
saphalaṃ tasya tac chlāghyam adya karma hanūmataḥ', null, 6103007),
('ramayana-6-103-8', 8, 'Yuddha Kanda, Sarga 103, Verse 8', 'युद्धे विक्रमतश्चैव हितं मन्त्रयतश्च मे।
सुग्रीवस्य ससैन्यस्य सफलोऽद्य परिश्रमः॥', 'yuddhe vikramataś caiva hitaṃ mantrayataś ca me
sugrīvasya sasainyasya saphalo ''dya pariśramaḥ', null, 6103008),
('ramayana-6-103-9', 9, 'Yuddha Kanda, Sarga 103, Verse 9', 'निर्गुणं भ्रातरं त्यक्त्वा यो मां स्वयमुपस्थितः।
विभीषणस्य भक्तस्य सफलोऽद्य परिश्रमः॥', 'nirguṇaṃ bhrātaraṃ tyaktvā yo māṃ svayam upasthitaḥ
vibhīṣaṇasya bhaktasya saphalo ''dya pariśramaḥ', null, 6103009),
('ramayana-6-103-10', 10, 'Yuddha Kanda, Sarga 103, Verse 10', 'इत्येवं ब्रुवतस्तस्य सीता रामस्य तद्वचः।
मृगीवोत्फुल्लनयना बभूवाश्रुपरिप्लुता॥', 'ity evaṃ bruvatas tasya sītā rāmasya tad vacaḥ
mṛgīvotphullanayanā babhūvāśrupariplutā', null, 6103010),
('ramayana-6-103-11', 11, 'Yuddha Kanda, Sarga 103, Verse 11', 'पश्यतस्तां तु रामस्य भूयः क्रोधोऽभ्यवर्तत।
प्रभूताज्यावसिक्तस्य पावकस्येव दीप्यतः॥', 'paśyatas tāṃ tu rāmasya bhūyaḥ krodho ''bhyavartata
prabhūtājyāvasiktasya pāvakasyeva dīpyataḥ', null, 6103011),
('ramayana-6-103-12', 12, 'Yuddha Kanda, Sarga 103, Verse 12', 'स बद्ध्वा भ्रुकुटिं वक्त्रे तिर्यक्प्रेक्षितलोचनः।
अब्रवीत्परुषं सीतां मध्ये वानररक्षसाम्॥', 'sa baddhvā bhrukuṭiṃ vaktre tiryakprekṣitalocanaḥ
abravīt paruṣaṃ sītāṃ madhye vānararakṣasām', null, 6103012),
('ramayana-6-103-13', 13, 'Yuddha Kanda, Sarga 103, Verse 13', 'यत्कर्तव्यं मनुष्येण धर्षणां परिमार्जता।
तत्कृतं सकलं सीते शत्रुहस्तादमर्षणात्॥', 'yat kartavyaṃ manuṣyeṇa dharṣaṇāṃ parimārjatā
tat kṛtaṃ sakalaṃ sīte śatruhastād amarṣaṇāt', null, 6103013),
('ramayana-6-103-14', 14, 'Yuddha Kanda, Sarga 103, Verse 14', 'निर्जिता जीवलोकस्य तपसा भावितात्मना।
अगस्त्येन दुराधर्षा मुनिना दक्षिणेव दिक्॥', 'nirjitā jīvalokasya tapasā bhāvitātmanā
agastyena durādharṣā muninā dakṣiṇeva dik', null, 6103014),
('ramayana-6-103-15', 15, 'Yuddha Kanda, Sarga 103, Verse 15', 'विदितश्चास्तु भद्रं ते योऽयं रणपरिश्रमः।
स तीर्णः सुहृदां वीर्यान्न त्वदर्थं मया कृतः॥', 'viditaś cāstu bhadraṃ te yo ''yaṃ raṇapariśramaḥ
sa tīrṇaḥ suhṛdāṃ vīryān na tvadarthaṃ mayā kṛtaḥ', null, 6103015),
('ramayana-6-103-16', 16, 'Yuddha Kanda, Sarga 103, Verse 16', 'रक्षता तु मया वृत्तमपवादं च सर्वशः।
प्रख्यातस्यात्मवंशस्य न्यङ्गं च परिमार्जता॥', 'rakṣatā tu mayā vṛttam apavādaṃ ca sarvaśaḥ
prakhyātasyātmavaṃśasya nyaṅgaṃ ca parimārjatā', null, 6103016),
('ramayana-6-103-17', 17, 'Yuddha Kanda, Sarga 103, Verse 17', 'प्राप्तचारित्रसंदेहा मम प्रतिमुखे स्थिता।
दीपो नेत्रातुरस्येव प्रतिकूलासि मे दृढम्॥', 'prāptacāritrasaṃdehā mama pratimukhe sthitā
dīpo netrāturasyeva pratikūlāsi me dṛḍham', null, 6103017),
('ramayana-6-103-18', 18, 'Yuddha Kanda, Sarga 103, Verse 18', 'तद्गच्छ ह्यभ्यनुज्ञाता यतेष्टं जनकात्मजे।
एता दश दिशो भद्रे कार्यमस्ति न मे त्वया॥', 'tad gaccha hy abhyanujñātā yateṣṭaṃ janakātmaje
etā daśa diśo bhadre kāryam asti na me tvayā', null, 6103018),
('ramayana-6-103-19', 19, 'Yuddha Kanda, Sarga 103, Verse 19', 'कः पुमान्हि कुले जातः स्त्रियं परगृहोषिताम्।
तेजस्वि पुनरादद्यात्सुहृल्लेखेन चेतसा॥', 'kaḥ pumān hi kule jātaḥ striyaṃ paragṛhoṣitām
tejasvi punar ādadyāt suhṛllekhena cetasā', null, 6103019),
('ramayana-6-103-20', 20, 'Yuddha Kanda, Sarga 103, Verse 20', 'रावणाङ्कपरिभ्रष्टां दृष्टां दुष्टेन चक्षुषा।
कथं त्वां पुनरादद्यां कुलं व्यपदिशन्महत्॥', 'rāvaṇāṅkaparibhraṣṭāṃ dṛṣṭāṃ duṣṭena cakṣuṣā
kathaṃ tvāṃ punarādadyāṃ kulaṃ vyapadiśan mahat', null, 6103020),
('ramayana-6-103-21', 21, 'Yuddha Kanda, Sarga 103, Verse 21', 'तदर्थं निर्जिता मे त्वं यशः प्रत्याहृतं मया।
नास्ति मे त्वय्यभिष्वङ्गो यथेष्टं गम्यतामितः॥', 'tadarthaṃ nirjitā me tvaṃ yaśaḥ pratyāhṛtaṃ mayā
nāsti me tvayy abhiṣvaṅgo yatheṣṭaṃ gamyatām itaḥ', null, 6103021),
('ramayana-6-103-22', 22, 'Yuddha Kanda, Sarga 103, Verse 22', 'इति प्रव्याहृतं भद्रे मयैतत्कृतबुद्धिना।
लक्ष्मणे भरते वा त्वं कुरु बुद्धिं यथासुखम्॥', 'iti pravyāhṛtaṃ bhadre mayaitat kṛtabuddhinā
lakṣmaṇe bharate vā tvaṃ kuru buddhiṃ yathāsukham', null, 6103022),
('ramayana-6-103-23', 23, 'Yuddha Kanda, Sarga 103, Verse 23', 'सुग्रीवे वानरेन्द्रे वा राक्षसेन्द्रे विभीषणे।
निवेशय मनः सीते यथा वा सुखमात्मनः॥', 'sugrīve vānarendre vā rākṣasendre vibhīṣaṇe
niveśaya manaḥ sīte yathā vā sukham ātmanaḥ', null, 6103023),
('ramayana-6-103-24', 24, 'Yuddha Kanda, Sarga 103, Verse 24', 'न हि त्वां रावणो दृष्ट्वा दिव्यरूपां मनोरमाम्।
मर्षयते चिरं सीते स्वगृहे परिवर्तिनीम्॥', 'na hi tvāṃ rāvaṇo dṛṣṭvā divyarūpāṃ manoramām
marṣayate ciraṃ sīte svagṛhe parivartinīm', null, 6103024),
('ramayana-6-103-25', 25, 'Yuddha Kanda, Sarga 103, Verse 25', 'ततः प्रियार्हश्वरणा तदप्रियं प्रियादुपश्रुत्य चिरस्य मैथिली।
मुमोच बाष्पं सुभृशं प्रवेपिता गजेन्द्रहस्ताभिहतेव वल्लरी॥', 'tataḥ priyārhaśvaraṇā tad apriyaṃ priyād upaśrutya cirasya maithilī
mumoca bāṣpaṃ subhṛśaṃ pravepitā gajendrahastābhihateva vallarī', null, 6103025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 104 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-104-1', 1, 'Yuddha Kanda, Sarga 104, Verse 1', 'एवमुक्ता तु वैदेही परुषं लोमहर्षणम्।
राघवेण सरोषेण भृशं प्रव्यथिताभवत्॥', 'evam uktā tu vaidehī paruṣaṃ lomaharṣaṇam
rāghaveṇa saroṣeṇa bhṛśaṃ pravyathitābhavat', null, 6104001),
('ramayana-6-104-2', 2, 'Yuddha Kanda, Sarga 104, Verse 2', 'सा तदश्रुतपूर्वं हि जने महति मैथिली।
श्रुत्वा भर्तृवचो रूक्षं लज्जया व्रीडिताभवत्॥', 'sā tad aśrutapūrvaṃ hi jane mahati maithilī
śrutvā bhartṛvaco rūkṣaṃ lajjayā vrīḍitābhavat', null, 6104002),
('ramayana-6-104-3', 3, 'Yuddha Kanda, Sarga 104, Verse 3', 'प्रविशन्तीव गात्राणि स्वान्येव जनकात्मजा।
वाक्शल्यैस्तैः सशल्येव भृशमश्रूण्यवर्तयत्॥', 'praviśantīva gātrāṇi svāny eva janakātmajā
vākśalyais taiḥ saśalyeva bhṛśam aśrūṇy avartayat', null, 6104003),
('ramayana-6-104-4', 4, 'Yuddha Kanda, Sarga 104, Verse 4', 'ततो बाष्पपरिक्लिष्टं प्रमार्जन्ती स्वमाननम्।
शनैर्गद्गदया वाचा भर्तारमिदमब्रवीत्॥', 'tato bāṣpaparikliṣṭaṃ pramārjantī svam ānanam
śanair gadgadayā vācā bhartāram idam abravīt', null, 6104004),
('ramayana-6-104-5', 5, 'Yuddha Kanda, Sarga 104, Verse 5', 'किं मामसदृशं वाक्यमीदृशं श्रोत्रदारुणम्।
रूक्षं श्रावयसे वीर प्राकृतः प्राकृतामिव॥', 'kiṃ mām asadṛśaṃ vākyam īdṛśaṃ śrotradāruṇam
rūkṣaṃ śrāvayase vīra prākṛtaḥ prākṛtām iva', null, 6104005),
('ramayana-6-104-6', 6, 'Yuddha Kanda, Sarga 104, Verse 6', 'न तथास्मि महाबाहो यथा त्वमवगच्छसि।
प्रत्ययं गच्छ मे स्वेन चारित्रेणैव ते शपे॥', 'na tathāsmi mahābāho yathā tvam avagacchasi
pratyayaṃ gaccha me svena cāritreṇaiva te śape', null, 6104006),
('ramayana-6-104-7', 7, 'Yuddha Kanda, Sarga 104, Verse 7', 'पृथक्स्त्रीणां प्रचारेण जातिं त्वं परिशङ्कसे।
परित्यजेमां शङ्कां तु यदि तेऽहं परीक्षिता॥', 'pṛthak strīṇāṃ pracāreṇa jātiṃ tvaṃ pariśaṅkase
parityajemāṃ śaṅkāṃ tu yadi te ''haṃ parīkṣitā', null, 6104007),
('ramayana-6-104-8', 8, 'Yuddha Kanda, Sarga 104, Verse 8', 'यद्यहं गात्रसंस्पर्शं गतास्मि विवशा प्रभो।
कामकारो न मे तत्र दैवं तत्रापराध्यति॥', 'yady ahaṃ gātrasaṃsparśaṃ gatāsmi vivaśā prabho
kāmakāro na me tatra daivaṃ tatrāparādhyati', null, 6104008),
('ramayana-6-104-9', 9, 'Yuddha Kanda, Sarga 104, Verse 9', 'मदधीनं तु यत्तन्मे हृदयं त्वयि वर्तते।
पराधीनेषु गात्रेषु किं करिष्याम्यनीश्वरा॥', 'madadhīnaṃ tu yat tan me hṛdayaṃ tvayi vartate
parādhīneṣu gātreṣu kiṃ kariṣyāmy anīśvarā', null, 6104009),
('ramayana-6-104-10', 10, 'Yuddha Kanda, Sarga 104, Verse 10', 'सहसंवृद्धभावाच्च संसर्गेण च मानद।
यद्यहं ते न विज्ञाता हता तेनास्मि शाश्वतम्॥', 'sahasaṃvṛddhabhāvāc ca saṃsargeṇa ca mānada
yady ahaṃ te na vijñātā hatā tenāsmi śāśvatam', null, 6104010),
('ramayana-6-104-11', 11, 'Yuddha Kanda, Sarga 104, Verse 11', 'प्रेषितस्ते यदा वीरो हनूमानवलोककः।
लङ्कास्थाहं त्वया वीर किं तदा न विसर्जिता॥', 'preṣitas te yadā vīro hanūmān avalokakaḥ
laṅkāsthāhaṃ tvayā vīra kiṃ tadā na visarjitā', null, 6104011),
('ramayana-6-104-12', 12, 'Yuddha Kanda, Sarga 104, Verse 12', 'प्रत्यक्षं वानरेन्द्रस्य त्वद्वाक्यसमनन्तरम्।
त्वया संत्यक्तया वीर त्यक्तं स्याज्जीवितं मया॥', 'pratyakṣaṃ vānarendrasya tvadvākyasamanantaram
tvayā saṃtyaktayā vīra tyaktaṃ syāj jīvitaṃ mayā', null, 6104012),
('ramayana-6-104-13', 13, 'Yuddha Kanda, Sarga 104, Verse 13', 'न वृथा ते श्रमोऽयं स्यात्संशये न्यस्य जीवितम्।
सुहृज्जनपरिक्लेशो न चायं निष्फलस्तव॥', 'na vṛthā te śramo ''yaṃ syāt saṃśaye nyasya jīvitam
suhṛjjanaparikleśo na cāyaṃ niṣphalas tava', null, 6104013),
('ramayana-6-104-14', 14, 'Yuddha Kanda, Sarga 104, Verse 14', 'त्वया तु नरशार्दूल क्रोधमेवानुवर्तता।
लघुनेव मनुष्येण स्त्रीत्वमेव पुरस्कृतम्॥', 'tvayā tu naraśārdūla krodham evānuvartatā
laghuneva manuṣyeṇa strītvam eva puraskṛtam', null, 6104014),
('ramayana-6-104-15', 15, 'Yuddha Kanda, Sarga 104, Verse 15', 'अपदेशेन जनकान्नोत्पत्तिर्वसुधातलात्।
मम वृत्तं च वृत्तज्ञ बहु ते न पुरस्कृतम्॥', 'apadeśena janakān notpattir vasudhātalāt
mama vṛttaṃ ca vṛttajña bahu te na puraskṛtam', null, 6104015),
('ramayana-6-104-16', 16, 'Yuddha Kanda, Sarga 104, Verse 16', 'न प्रमाणीकृतः पाणिर्बाल्ये बालेन पीडितः।
मम भक्तिश्च शीलं च सर्वं ते पृष्ठतः कृतम्॥', 'na pramāṇīkṛtaḥ pāṇir bālye bālena pīḍitaḥ
mama bhaktiś ca śīlaṃ ca sarvaṃ te pṛṣṭhataḥ kṛtam', null, 6104016),
('ramayana-6-104-17', 17, 'Yuddha Kanda, Sarga 104, Verse 17', 'एवं ब्रुवाणा रुदती बाष्पगद्गदभाषिणी।
अब्रवील्लक्ष्मणं सीता दीनं ध्यानपरं स्थितम्॥', 'evaṃ bruvāṇā rudatī bāṣpagadgadabhāṣiṇī
abravīl lakṣmaṇaṃ sītā dīnaṃ dhyānaparaṃ sthitam', null, 6104017),
('ramayana-6-104-18', 18, 'Yuddha Kanda, Sarga 104, Verse 18', 'चितां मे कुरु सौमित्रे व्यसनस्यास्य भेषजम्।
मिथ्यापवादोपहता नाहं जीवितुमुत्सहे॥', 'citāṃ me kuru saumitre vyasanasyāsya bheṣajam
mithyāpavādopahatā nāhaṃ jīvitum utsahe', null, 6104018),
('ramayana-6-104-19', 19, 'Yuddha Kanda, Sarga 104, Verse 19', 'अप्रीतस्य गुणैर्भर्तुस्त्यक्तया जनसंसदि।
या क्षमा मे गतिर्गन्तुं प्रवेक्ष्ये हव्यवाहनम्॥', 'aprītasya guṇair bhartus tyaktayā janasaṃsadi
yā kṣamā me gatir gantuṃ pravekṣye havyavāhanam', null, 6104019),
('ramayana-6-104-20', 20, 'Yuddha Kanda, Sarga 104, Verse 20', 'एवमुक्तस्तु वैदेह्या लक्ष्मणः परवीरहा।
अमर्षवशमापन्नो राघवाननमैक्षत॥', 'evam uktas tu vaidehyā lakṣmaṇaḥ paravīrahā
amarṣavaśam āpanno rāghavānanam aikṣata', null, 6104020),
('ramayana-6-104-21', 21, 'Yuddha Kanda, Sarga 104, Verse 21', 'स विज्ञाय मनश्छन्दं रामस्याकारसूचितम्।
चितां चकार सौमित्रिर्मते रामस्य वीर्यवान्॥', 'sa vijñāya manaśchandaṃ rāmasyākārasūcitam
citāṃ cakāra saumitrir mate rāmasya vīryavān', null, 6104021),
('ramayana-6-104-22', 22, 'Yuddha Kanda, Sarga 104, Verse 22', 'अधोमुखं ततो रामं शनैः कृत्वा प्रदक्षिणम्।
उपासर्पत वैदेही दीप्यमानं हुताशनम्॥', 'adhomukhaṃ tato rāmaṃ śanaiḥ kṛtvā pradakṣiṇam
upāsarpata vaidehī dīpyamānaṃ hutāśanam', null, 6104022),
('ramayana-6-104-23', 23, 'Yuddha Kanda, Sarga 104, Verse 23', 'प्रणम्य देवताभ्यश्च ब्राह्मणेभ्यश्च मैथिली।
बद्धाञ्जलिपुटा चेदमुवाचाग्निसमीपतः॥', 'praṇamya devatābhyaś ca brāhmaṇebhyaś ca maithilī
baddhāñjalipuṭā cedam uvācāgnisamīpataḥ', null, 6104023),
('ramayana-6-104-24', 24, 'Yuddha Kanda, Sarga 104, Verse 24', 'यथा मे हृदयं नित्यं नापसर्पति राघवात्।
तथा लोकस्य साक्षी मां सर्वतः पातु पावकः॥', 'yathā me hṛdayaṃ nityaṃ nāpasarpati rāghavāt
tathā lokasya sākṣī māṃ sarvataḥ pātu pāvakaḥ', null, 6104024),
('ramayana-6-104-25', 25, 'Yuddha Kanda, Sarga 104, Verse 25', 'एवमुक्त्वा तु वैदेही परिक्रम्य हुताशनम्।
विवेश ज्वलनं दीप्तं निःसङ्गेनान्तरात्मना॥', 'evam uktvā tu vaidehī parikramya hutāśanam
viveśa jvalanaṃ dīptaṃ niḥsaṅgenāntarātmanā', null, 6104025),
('ramayana-6-104-26', 26, 'Yuddha Kanda, Sarga 104, Verse 26', 'जनः स सुमहांस्तत्र बालवृद्धसमाकुलः।
ददर्श मैथिलीं तत्र प्रविशन्तीं हुताशनम्॥', 'janaḥ sa sumahāṃs tatra bālavṛddhasamākulaḥ
dadarśa maithilīṃ tatra praviśantīṃ hutāśanam', null, 6104026),
('ramayana-6-104-27', 27, 'Yuddha Kanda, Sarga 104, Verse 27', 'तस्यामग्निं विशन्त्यां तु हाहेति विपुलः स्वनः।
रक्षसां वानराणां च संबभूवाद्भुतोपमः॥', 'tasyām agniṃ viśantyāṃ tu hāheti vipulaḥ svanaḥ
rakṣasāṃ vānarāṇāṃ ca saṃbabhūvādbhutopamaḥ', null, 6104027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 105 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-105-1', 1, 'Yuddha Kanda, Sarga 105, Verse 1', 'ततो वैश्रवणो राजा यमश्चामित्रकर्शनः।
सहस्राक्षो महेन्द्रश्च वरुणश्च परंतपः॥', 'tato vaiśravaṇo rājā yamaś cāmitrakarśanaḥ
sahasrākṣo mahendraś ca varuṇaś ca paraṃtapaḥ', null, 6105001),
('ramayana-6-105-2', 2, 'Yuddha Kanda, Sarga 105, Verse 2', 'षडर्धनयनः श्रीमान्महादेवो वृषध्वजः।
कर्ता सर्वस्य लोकस्य ब्रह्मा ब्रह्मविदां वरः॥', 'ṣaḍardhanayanaḥ śrīmān mahādevo vṛṣadhvajaḥ
kartā sarvasya lokasya brahmā brahmavidāṃ varaḥ', null, 6105002),
('ramayana-6-105-3', 3, 'Yuddha Kanda, Sarga 105, Verse 3', 'एते सर्वे समागम्य विमानैः सूर्यसंनिभैः।
आगम्य नगरीं लङ्कामभिजग्मुश्च राघवम्॥', 'ete sarve samāgamya vimānaiḥ sūryasaṃnibhaiḥ
āgamya nagarīṃ laṅkām abhijagmuś ca rāghavam', null, 6105003),
('ramayana-6-105-4', 4, 'Yuddha Kanda, Sarga 105, Verse 4', 'ततः सहस्ताभरणान्प्रगृह्य विपुलान्भुजान्।
अब्रुवंस्त्रिदशश्रेष्ठाः प्राञ्जलिं राघवं स्थितम्॥', 'tataḥ sahastābharaṇān pragṛhya vipulān bhujān
abruvaṃs tridaśaśreṣṭhāḥ prāñjaliṃ rāghavaṃ sthitam', null, 6105004),
('ramayana-6-105-5', 5, 'Yuddha Kanda, Sarga 105, Verse 5', 'कर्ता सर्वस्य लोकस्य श्रेष्ठो ज्ञानवतां वरः।
उपेक्षसे कथं सीतां पतन्तीं हव्यवाहने।
कथं देवगणश्रेष्ठमात्मानं नावबुध्यसे॥', 'kartā sarvasya lokasya śreṣṭho jñānavatāṃ varaḥ
upekṣase kathaṃ sītāṃ patantīṃ havyavāhane
kathaṃ devagaṇaśreṣṭham ātmānaṃ nāvabudhyase', null, 6105005),
('ramayana-6-105-6', 6, 'Yuddha Kanda, Sarga 105, Verse 6', 'ऋतधामा वसुः पूर्वं वसूनां च प्रजापतिः।
त्वं त्रयाणां हि लोकानामादिकर्ता स्वयंप्रभुः॥', 'ṛtadhāmā vasuḥ pūrvaṃ vasūnāṃ ca prajāpatiḥ
tvaṃ trayāṇāṃ hi lokānām ādikartā svayaṃprabhuḥ', null, 6105006),
('ramayana-6-105-7', 7, 'Yuddha Kanda, Sarga 105, Verse 7', 'रुद्राणामष्टमो रुद्रः साध्यानामपि पञ्चमः।
अश्विनौ चापि ते कर्णौ चन्द्रसूर्यौ च चक्षुषी॥', 'rudrāṇām aṣṭamo rudraḥ sādhyānām api pañcamaḥ
aśvinau cāpi te karṇau candrasūryau ca cakṣuṣī', null, 6105007),
('ramayana-6-105-8', 8, 'Yuddha Kanda, Sarga 105, Verse 8', 'अन्ते चादौ च लोकानां दृश्यसे त्वं परंतप।
उपेक्षसे च वैदेहीं मानुषः प्राकृतो यथा॥', 'ante cādau ca lokānāṃ dṛśyase tvaṃ paraṃtapa
upekṣase ca vaidehīṃ mānuṣaḥ prākṛto yathā', null, 6105008),
('ramayana-6-105-9', 9, 'Yuddha Kanda, Sarga 105, Verse 9', 'इत्युक्तो लोकपालैस्तैः स्वामी लोकस्य राघवः।
अब्रवीत्त्रिदशश्रेष्ठान्रामो धर्मभृतां वरः॥', 'ity ukto lokapālais taiḥ svāmī lokasya rāghavaḥ
abravīt tridaśaśreṣṭhān rāmo dharmabhṛtāṃ varaḥ', null, 6105009),
('ramayana-6-105-10', 10, 'Yuddha Kanda, Sarga 105, Verse 10', 'आत्मानं मानुषं मन्ये रामं दशरथात्मजम्।
योऽहं यस्य यतश्चाहं भगवांस्तद्ब्रवीतु मे॥', 'ātmānaṃ mānuṣaṃ manye rāmaṃ daśarathātmajam
yo ''haṃ yasya yataś cāhaṃ bhagavāṃs tad bravītu me', null, 6105010),
('ramayana-6-105-11', 11, 'Yuddha Kanda, Sarga 105, Verse 11', 'इति ब्रुवाणं काकुत्स्थं ब्रह्मा ब्रह्मविदां वरः।
अब्रवीच्छृणु मे राम सत्यं सत्यपराक्रम॥', 'iti bruvāṇaṃ kākutsthaṃ brahmā brahmavidāṃ varaḥ
abravīc chṛṇu me rāma satyaṃ satyaparākrama', null, 6105011),
('ramayana-6-105-12', 12, 'Yuddha Kanda, Sarga 105, Verse 12', 'भवान्नारायणो देवः श्रीमांश्चक्रायुधो विभुः।
एकशृङ्गो वराहस्त्वं भूतभव्यसपत्नजित्॥', 'bhavān nārāyaṇo devaḥ śrīmāṃś cakrāyudho vibhuḥ
ekaśṛṅgo varāhas tvaṃ bhūtabhavyasapatnajit', null, 6105012),
('ramayana-6-105-13', 13, 'Yuddha Kanda, Sarga 105, Verse 13', 'अक्षरं ब्रह्मसत्यं च मध्ये चान्ते च राघव।
लोकानां त्वं परो धर्मो विष्वक्सेनश्चतुर्भुजः॥', 'akṣaraṃ brahmasatyaṃ ca madhye cānte ca rāghava
lokānāṃ tvaṃ paro dharmo viṣvaksenaś caturbhujaḥ', null, 6105013),
('ramayana-6-105-14', 14, 'Yuddha Kanda, Sarga 105, Verse 14', 'शार्ङ्गधन्वा हृषीकेशः पुरुषः पुरुषोत्तमः।
अजितः खड्गधृग्विष्णुः कृष्णश्चैव बृहद्बलः॥', 'śārṅgadhanvā hṛṣīkeśaḥ puruṣaḥ puruṣottamaḥ
ajitaḥ khaḍgadhṛg viṣṇuḥ kṛṣṇaś caiva bṛhadbalaḥ', null, 6105014),
('ramayana-6-105-15', 15, 'Yuddha Kanda, Sarga 105, Verse 15', 'सेनानीर्ग्रामणीश्च त्वं बुद्धिः सत्त्वं क्षमा दमः।
प्रभवश्चाप्ययश्च त्वमुपेन्द्रो मधुसूदनः॥', 'senānīr grāmaṇīś ca tvaṃ buddhiḥ sattvaṃ kṣamā damaḥ
prabhavaś cāpyayaś ca tvam upendro madhusūdanaḥ', null, 6105015),
('ramayana-6-105-16', 16, 'Yuddha Kanda, Sarga 105, Verse 16', 'इन्द्रकर्मा महेन्द्रस्त्वं पद्मनाभो रणान्तकृत्।
शरण्यं शरणं च त्वामाहुर्दिव्या महर्षयः॥', 'indrakarmā mahendras tvaṃ padmanābho raṇāntakṛt
śaraṇyaṃ śaraṇaṃ ca tvām āhur divyā maharṣayaḥ', null, 6105016),
('ramayana-6-105-17', 17, 'Yuddha Kanda, Sarga 105, Verse 17', 'सहस्रशृङ्गो वेदात्मा शतजिह्वो महर्षभः।
त्वं यज्ञस्त्वं वषट्कारस्त्वमोंकारः परंतप॥', 'sahasraśṛṅgo vedātmā śatajihvo maharṣabhaḥ
tvaṃ yajñas tvaṃ vaṣaṭkāras tvam oṃkāraḥ paraṃtapa', null, 6105017),
('ramayana-6-105-18', 18, 'Yuddha Kanda, Sarga 105, Verse 18', 'प्रभवं निधनं वा ते न विदुः को भवानिति।
दृश्यसे सर्वभूतेषु ब्राह्मणेषु च गोषु च॥', 'prabhavaṃ nidhanaṃ vā te na viduḥ ko bhavān iti
dṛśyase sarvabhūteṣu brāhmaṇeṣu ca goṣu ca', null, 6105018),
('ramayana-6-105-19', 19, 'Yuddha Kanda, Sarga 105, Verse 19', 'दिक्षु सर्वासु गगने पर्वतेषु वनेषु च।
सहस्रचरणः श्रीमाञ्शतशीर्षः सहस्रधृक्॥', 'dikṣu sarvāsu gagane parvateṣu vaneṣu ca
sahasracaraṇaḥ śrīmāñ śataśīrṣaḥ sahasradhṛk', null, 6105019),
('ramayana-6-105-20', 20, 'Yuddha Kanda, Sarga 105, Verse 20', 'त्वं धारयसि भूतानि वसुधां च सपर्वताम्।
अन्ते पृथिव्याः सलिले दृश्यसे त्वं महोरगः॥', 'tvaṃ dhārayasi bhūtāni vasudhāṃ ca saparvatām
ante pṛthivyāḥ salile dṛśyase tvaṃ mahoragaḥ', null, 6105020),
('ramayana-6-105-21', 21, 'Yuddha Kanda, Sarga 105, Verse 21', 'त्रींल्लोकान्धारयन्राम देवगन्धर्वदानवान्।
अहं ते हृदयं राम जिह्वा देवी सरस्वती॥', 'trīṃl lokān dhārayan rāma devagandharvadānavān
ahaṃ te hṛdayaṃ rāma jihvā devī sarasvatī', null, 6105021),
('ramayana-6-105-22', 22, 'Yuddha Kanda, Sarga 105, Verse 22', 'देवा गात्रेषु लोमानि निर्मिता ब्रह्मणा प्रभो।
निमेषस्तेऽभवद्रात्रिरुन्मेषस्तेऽभवद्दिवा॥', 'devā gātreṣu lomāni nirmitā brahmaṇā prabho
nimeṣas te ''bhavad rātrir unmeṣas te ''bhavad divā', null, 6105022),
('ramayana-6-105-23', 23, 'Yuddha Kanda, Sarga 105, Verse 23', 'संस्कारास्तेऽभवन्वेदा न तदस्ति त्वया विना।
जगत्सर्वं शरीरं ते स्थैर्यं ते वसुधातलम्॥', 'saṃskārās te ''bhavan vedā na tad asti tvayā vinā
jagat sarvaṃ śarīraṃ te sthairyaṃ te vasudhātalam', null, 6105023),
('ramayana-6-105-24', 24, 'Yuddha Kanda, Sarga 105, Verse 24', 'अग्निः कोपः प्रसादस्ते सोमः श्रीवत्सलक्षण।
त्वया लोकास्त्रयः क्रान्ताः पुराणे विक्रमैस्त्रिभिः॥', 'agniḥ kopaḥ prasādas te somaḥ śrīvatsalakṣaṇa
tvayā lokās trayaḥ krāntāḥ purāṇe vikramais tribhiḥ', null, 6105024),
('ramayana-6-105-25', 25, 'Yuddha Kanda, Sarga 105, Verse 25', 'महेन्द्रश्च कृतो राजा बलिं बद्ध्वा महासुरम्।
सीता लक्ष्मीर्भवान्विष्णुर्देवः कृष्णः प्रजापतिः॥', 'mahendraś ca kṛto rājā baliṃ baddhvā mahāsuram
sītā lakṣmīr bhavān viṣṇur devaḥ kṛṣṇaḥ prajāpatiḥ', null, 6105025),
('ramayana-6-105-26', 26, 'Yuddha Kanda, Sarga 105, Verse 26', 'वधार्थं रावणस्येह प्रविष्टो मानुषीं तनुम्।
तदिदं नः कृतं कार्यं त्वया धर्मभृतां वर॥', 'vadhārthaṃ rāvaṇasyeha praviṣṭo mānuṣīṃ tanum
tad idaṃ naḥ kṛtaṃ kāryaṃ tvayā dharmabhṛtāṃ vara', null, 6105026),
('ramayana-6-105-27', 27, 'Yuddha Kanda, Sarga 105, Verse 27', 'निहतो रावणो राम प्रहृष्टो दिवमाक्रम।
अमोघं बलवीर्यं ते अमोघस्ते पराक्रमः॥', 'nihato rāvaṇo rāma prahṛṣṭo divam ākrama
amoghaṃ balavīryaṃ te amoghas te parākramaḥ', null, 6105027),
('ramayana-6-105-28', 28, 'Yuddha Kanda, Sarga 105, Verse 28', 'अमोघास्ते भविष्यन्ति भक्तिमन्तश्च ये नराः।
ये त्वां देवं ध्रुवं भक्ताः पुराणं पुरुषोत्तमम्॥', 'amoghās te bhaviṣyanti bhaktimantaś ca ye narāḥ
ye tvāṃ devaṃ dhruvaṃ bhaktāḥ purāṇaṃ puruṣottamam', null, 6105028),
('ramayana-6-105-29', 29, 'Yuddha Kanda, Sarga 105, Verse 29', 'ये नराः कीर्तयिष्यन्ति नास्ति तेषां पराभवः॥', 'ye narāḥ kīrtayiṣyanti nāsti teṣāṃ parābhavaḥ', null, 6105029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 106 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-106-1', 1, 'Yuddha Kanda, Sarga 106, Verse 1', 'एतच्छ्रुत्वा शुभं वाक्यं पितामहसमीरितम्।
अङ्केनादाय वैदेहीमुत्पपात विभावसुः॥', 'etac chrutvā śubhaṃ vākyaṃ pitāmahasamīritam
aṅkenādāya vaidehīm utpapāta vibhāvasuḥ', null, 6106001),
('ramayana-6-106-2', 2, 'Yuddha Kanda, Sarga 106, Verse 2', 'तरुणादित्यसंकाशां तप्तकाञ्चनभूषणाम्।
रक्ताम्बरधरां बालां नीलकुञ्चितमूर्धजाम्॥', 'taruṇādityasaṃkāśāṃ taptakāñcanabhūṣaṇām
raktāmbaradharāṃ bālāṃ nīlakuñcitamūrdhajām', null, 6106002),
('ramayana-6-106-3', 3, 'Yuddha Kanda, Sarga 106, Verse 3', 'अक्लिष्टमाल्याभरणां तथा रूपां मनस्विनीम्।
ददौ रामाय वैदेहीमङ्के कृत्वा विभावसुः॥', 'akliṣṭamālyābharaṇāṃ tathā rūpāṃ manasvinīm
dadau rāmāya vaidehīm aṅke kṛtvā vibhāvasuḥ', null, 6106003),
('ramayana-6-106-4', 4, 'Yuddha Kanda, Sarga 106, Verse 4', 'अब्रवीच्च तदा रामं साक्षी लोकस्य पावकः।
एषा ते राम वैदेही पापमस्या न विद्यते॥', 'abravīc ca tadā rāmaṃ sākṣī lokasya pāvakaḥ
eṣā te rāma vaidehī pāpam asyā na vidyate', null, 6106004),
('ramayana-6-106-5', 5, 'Yuddha Kanda, Sarga 106, Verse 5', 'नैव वाचा न मनसा नानुध्यानान्न चक्षुषा।
सुवृत्ता वृत्तशौण्डीरा न त्वामतिचचार ह॥', 'naiva vācā na manasā nānudhyānān na cakṣuṣā
suvṛttā vṛttaśauṇḍīrā na tvām aticacāra ha', null, 6106005),
('ramayana-6-106-6', 6, 'Yuddha Kanda, Sarga 106, Verse 6', 'रावणेनापनीतैषा वीर्योत्सिक्तेन रक्षसा।
त्वया विरहिता दीना विवशा निर्जनाद्वनात्॥', 'rāvaṇenāpanītaiṣā vīryotsiktena rakṣasā
tvayā virahitā dīnā vivaśā nirjanād vanāt', null, 6106006),
('ramayana-6-106-7', 7, 'Yuddha Kanda, Sarga 106, Verse 7', 'रुद्धा चान्तःपुरे गुप्ता त्वक्चित्ता त्वत्परायणा।
रक्षिता राक्षसी संघैर्विकृतैर्घोरदर्शनैः॥', 'ruddhā cāntaḥpure guptā tvakcittā tvatparāyaṇā
rakṣitā rākṣasī saṃghair vikṛtair ghoradarśanaiḥ', null, 6106007),
('ramayana-6-106-8', 8, 'Yuddha Kanda, Sarga 106, Verse 8', 'प्रलोभ्यमाना विविधं भर्त्स्यमाना च मैथिली।
नाचिन्तयत तद्रक्षस्त्वद्गतेनान्तरात्मना॥', 'pralobhyamānā vividhaṃ bhartsyamānā ca maithilī
nācintayata tad rakṣas tvadgatenāntarātmanā', null, 6106008),
('ramayana-6-106-9', 9, 'Yuddha Kanda, Sarga 106, Verse 9', 'विशुद्धभावां निष्पापां प्रतिगृह्णीष्व राघव।
न किं चिदभिधातव्यमहमाज्ञापयामि ते॥', 'viśuddhabhāvāṃ niṣpāpāṃ pratigṛhṇīṣva rāghava
na kiṃ cid abhidhātavyam aham ājñāpayāmi te', null, 6106009),
('ramayana-6-106-10', 10, 'Yuddha Kanda, Sarga 106, Verse 10', 'एवमुक्तो महातेजा धृतिमान्दृढविक्रमः।
अब्रवीत्त्रिदशश्रेष्ठं रामो धर्मभृतां वरः॥', 'evam ukto mahātejā dhṛtimān dṛḍhavikramaḥ
abravīt tridaśaśreṣṭhaṃ rāmo dharmabhṛtāṃ varaḥ', null, 6106010),
('ramayana-6-106-11', 11, 'Yuddha Kanda, Sarga 106, Verse 11', 'अवश्यं त्रिषु लोकेषु सीता पावनमर्हति।
दीर्घकालोषिता चेयं रावणान्तःपुरे शुभा॥', 'avaśyaṃ triṣu lokeṣu sītā pāvanam arhati
dīrghakāloṣitā ceyaṃ rāvaṇāntaḥpure śubhā', null, 6106011),
('ramayana-6-106-12', 12, 'Yuddha Kanda, Sarga 106, Verse 12', 'बालिशः खलु कामात्मा रामो दशरथात्मजः।
इति वक्ष्यन्ति मां सन्तो जानकीमविशोध्य हि॥', 'bāliśaḥ khalu kāmātmā rāmo daśarathātmajaḥ
iti vakṣyanti māṃ santo jānakīm aviśodhya hi', null, 6106012),
('ramayana-6-106-13', 13, 'Yuddha Kanda, Sarga 106, Verse 13', 'अनन्यहृदयां भक्तां मच्चित्तपरिरक्षणीम्।
अहमप्यवगच्छामि मैथिलीं जनकात्मजाम्॥', 'ananyahṛdayāṃ bhaktāṃ maccittaparirakṣaṇīm
aham apy avagacchāmi maithilīṃ janakātmajām', null, 6106013),
('ramayana-6-106-14', 14, 'Yuddha Kanda, Sarga 106, Verse 14', 'प्रत्ययार्थं तु लोकानां त्रयाणां सत्यसंश्रयः।
उपेक्षे चापि वैदेहीं प्रविशन्तीं हुताशनम्॥', 'pratyayārthaṃ tu lokānāṃ trayāṇāṃ satyasaṃśrayaḥ
upekṣe cāpi vaidehīṃ praviśantīṃ hutāśanam', null, 6106014),
('ramayana-6-106-15', 15, 'Yuddha Kanda, Sarga 106, Verse 15', 'इमामपि विशालाक्षीं रक्षितां स्वेन तेजसा।
रावणो नातिवर्तेत वेलामिव महोदधिः॥', 'imām api viśālākṣīṃ rakṣitāṃ svena tejasā
rāvaṇo nātivarteta velām iva mahodadhiḥ', null, 6106015),
('ramayana-6-106-16', 16, 'Yuddha Kanda, Sarga 106, Verse 16', 'न हि शक्तः स दुष्टात्मा मनसापि हि मैथिलीम्।
प्रधर्षयितुमप्राप्तां दीप्तामग्निशिखामिव॥', 'na hi śaktaḥ sa duṣṭātmā manasāpi hi maithilīm
pradharṣayitum aprāptāṃ dīptām agniśikhām iva', null, 6106016),
('ramayana-6-106-17', 17, 'Yuddha Kanda, Sarga 106, Verse 17', 'नेयमर्हति चैश्वर्यं रावणान्तःपुरे शुभा।
अनन्या हि मया सीतां भास्करेण प्रभा यथा॥', 'neyam arhati caiśvaryaṃ rāvaṇāntaḥpure śubhā
ananyā hi mayā sītāṃ bhāskareṇa prabhā yathā', null, 6106017),
('ramayana-6-106-18', 18, 'Yuddha Kanda, Sarga 106, Verse 18', 'विशुद्धा त्रिषु लोकेषु मैथिली जनकात्मजा।
न हि हातुमियं शक्या कीर्तिरात्मवता यथा॥', 'viśuddhā triṣu lokeṣu maithilī janakātmajā
na hi hātum iyaṃ śakyā kīrtir ātmavatā yathā', null, 6106018),
('ramayana-6-106-19', 19, 'Yuddha Kanda, Sarga 106, Verse 19', 'अवश्यं च मया कार्यं सर्वेषां वो वचो हितम्।
स्निग्धानां लोकमान्यानामेवं च ब्रुवतां हितम्॥', 'avaśyaṃ ca mayā kāryaṃ sarveṣāṃ vo vaco hitam
snigdhānāṃ lokamānyānām evaṃ ca bruvatāṃ hitam', null, 6106019),
('ramayana-6-106-20', 20, 'Yuddha Kanda, Sarga 106, Verse 20', 'इतीदमुक्त्वा वचनं महाबलैः प्रशस्यमानः स्वकृतेन कर्मणा।
समेत्य रामः प्रियया महाबलः सुखं सुखार्होऽनुबभूव राघवः॥', 'itīdam uktvā vacanaṃ mahābalaiḥ praśasyamānaḥ svakṛtena karmaṇā
sametya rāmaḥ priyayā mahābalaḥ sukhaṃ sukhārho ''nubabhūva rāghavaḥ', null, 6106020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 107 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-107-1', 1, 'Yuddha Kanda, Sarga 107, Verse 1', 'एतच्छ्रुत्वा शुभं वाक्यं राघवेण सुभाषितम्।
इदं शुभतरं वाक्यं व्याजहार महेश्वरः॥', 'etac chrutvā śubhaṃ vākyaṃ rāghaveṇa subhāṣitam
idaṃ śubhataraṃ vākyaṃ vyājahāra maheśvaraḥ', null, 6107001),
('ramayana-6-107-2', 2, 'Yuddha Kanda, Sarga 107, Verse 2', 'पुष्कराक्ष महाबाहो महावक्षः परंतप।
दिष्ट्या कृतमिदं कर्म त्वया शस्त्रभृतां वर॥', 'puṣkarākṣa mahābāho mahāvakṣaḥ paraṃtapa
diṣṭyā kṛtam idaṃ karma tvayā śastrabhṛtāṃ vara', null, 6107002),
('ramayana-6-107-3', 3, 'Yuddha Kanda, Sarga 107, Verse 3', 'दिष्ट्या सर्वस्य लोकस्य प्रवृद्धं दारुणं तमः।
अपावृत्तं त्वया संख्ये राम रावणजं भयम्॥', 'diṣṭyā sarvasya lokasya pravṛddhaṃ dāruṇaṃ tamaḥ
apāvṛttaṃ tvayā saṃkhye rāma rāvaṇajaṃ bhayam', null, 6107003),
('ramayana-6-107-4', 4, 'Yuddha Kanda, Sarga 107, Verse 4', 'आश्वास्य भरतं दीनं कौसल्यां च यशस्विनीम्।
कैकेयीं च सुमित्रां च दृष्ट्वा लक्ष्मणमातरम्॥', 'āśvāsya bharataṃ dīnaṃ kausalyāṃ ca yaśasvinīm
kaikeyīṃ ca sumitrāṃ ca dṛṣṭvā lakṣmaṇamātaram', null, 6107004),
('ramayana-6-107-5', 5, 'Yuddha Kanda, Sarga 107, Verse 5', 'प्राप्य राज्यमयोध्यायां नन्दयित्वा सुहृज्जनम्।
इक्ष्वाकूणां कुले वंशं स्थापयित्वा महाबल॥', 'prāpya rājyam ayodhyāyāṃ nandayitvā suhṛjjanam
ikṣvākūṇāṃ kule vaṃśaṃ sthāpayitvā mahābala', null, 6107005),
('ramayana-6-107-6', 6, 'Yuddha Kanda, Sarga 107, Verse 6', 'इष्ट्वा तुरगमेधेन प्राप्य चानुत्तमं यशः।
ब्राह्मणेभ्यो धनं दत्त्वा त्रिदिवं गन्तुमर्हसि॥', 'iṣṭvā turagamedhena prāpya cānuttamaṃ yaśaḥ
brāhmaṇebhyo dhanaṃ dattvā tridivaṃ gantum arhasi', null, 6107006),
('ramayana-6-107-7', 7, 'Yuddha Kanda, Sarga 107, Verse 7', 'एष राजा विमानस्थः पिता दशरथस्तव।
काकुत्स्थ मानुषे लोके गुरुस्तव महायशाः॥', 'eṣa rājā vimānasthaḥ pitā daśarathas tava
kākutstha mānuṣe loke gurus tava mahāyaśāḥ', null, 6107007),
('ramayana-6-107-8', 8, 'Yuddha Kanda, Sarga 107, Verse 8', 'इन्द्रलोकं गतः श्रीमांस्त्वया पुत्रेण तारितः।
लक्ष्मणेन सह भ्रात्रा त्वमेनमभिवादय॥', 'indralokaṃ gataḥ śrīmāṃs tvayā putreṇa tāritaḥ
lakṣmaṇena saha bhrātrā tvam enam abhivādaya', null, 6107008),
('ramayana-6-107-9', 9, 'Yuddha Kanda, Sarga 107, Verse 9', 'महादेववचः श्रुत्वा काकुत्स्थः सहलक्ष्मणः।
विमानशिखरस्थस्य प्रणाममकरोत्पितुः॥', 'mahādevavacaḥ śrutvā kākutsthaḥ sahalakṣmaṇaḥ
vimānaśikharasthasya praṇāmam akarot pituḥ', null, 6107009),
('ramayana-6-107-10', 10, 'Yuddha Kanda, Sarga 107, Verse 10', 'दीप्यमानं स्वयां लक्ष्म्या विरजोऽम्बरधारिणम्।
लक्ष्मणेन सह भ्रात्रा ददर्श पितरं प्रभुः॥', 'dīpyamānaṃ svayāṃ lakṣmyā virajo''mbaradhāriṇam
lakṣmaṇena saha bhrātrā dadarśa pitaraṃ prabhuḥ', null, 6107010),
('ramayana-6-107-11', 11, 'Yuddha Kanda, Sarga 107, Verse 11', 'हर्षेण महताविष्टो विमानस्थो महीपतिः।
प्राणैः प्रियतरं दृष्ट्वा पुत्रं दशरथस्तदा॥', 'harṣeṇa mahatāviṣṭo vimānastho mahīpatiḥ
prāṇaiḥ priyataraṃ dṛṣṭvā putraṃ daśarathas tadā', null, 6107011),
('ramayana-6-107-12', 12, 'Yuddha Kanda, Sarga 107, Verse 12', 'आरोप्याङ्कं महाबाहुर्वरासनगतः प्रभुः।
बाहुभ्यां संपरिष्वज्य ततो वाक्यं समाददे॥', 'āropyāṅkaṃ mahābāhur varāsanagataḥ prabhuḥ
bāhubhyāṃ saṃpariṣvajya tato vākyaṃ samādade', null, 6107012),
('ramayana-6-107-13', 13, 'Yuddha Kanda, Sarga 107, Verse 13', 'न मे स्वर्गो बहुमतः संमानश्च सुरर्षिभिः।
त्वया राम विहीनस्य सत्यं प्रतिशृणोमि ते॥', 'na me svargo bahumataḥ saṃmānaś ca surarṣibhiḥ
tvayā rāma vihīnasya satyaṃ pratiśṛṇomi te', null, 6107013),
('ramayana-6-107-14', 14, 'Yuddha Kanda, Sarga 107, Verse 14', 'कैकेय्या यानि चोक्तानि वाक्यानि वदतां वर।
तव प्रव्राजनार्थानि स्थितानि हृदये मम॥', 'kaikeyyā yāni coktāni vākyāni vadatāṃ vara
tava pravrājanārthāni sthitāni hṛdaye mama', null, 6107014),
('ramayana-6-107-15', 15, 'Yuddha Kanda, Sarga 107, Verse 15', 'त्वां तु दृष्ट्वा कुशलिनं परिष्वज्य सलक्ष्मणम्।
अद्य दुःखाद्विमुक्तोऽस्मि नीहारादिव भास्करः॥', 'tvāṃ tu dṛṣṭvā kuśalinaṃ pariṣvajya salakṣmaṇam
adya duḥkhād vimukto ''smi nīhārād iva bhāskaraḥ', null, 6107015),
('ramayana-6-107-16', 16, 'Yuddha Kanda, Sarga 107, Verse 16', 'तारितोऽहं त्वया पुत्र सुपुत्रेण महात्मना।
अष्टावक्रेण धर्मात्मा तारितो ब्राह्मणो यथा॥', 'tārito ''haṃ tvayā putra suputreṇa mahātmanā
aṣṭāvakreṇa dharmātmā tārito brāhmaṇo yathā', null, 6107016),
('ramayana-6-107-17', 17, 'Yuddha Kanda, Sarga 107, Verse 17', 'इदानीं च विजानामि यथा सौम्य सुरेश्वरैः।
वधार्थं रावणस्येह विहितं पुरुषोत्तमम्॥', 'idānīṃ ca vijānāmi yathā saumya sureśvaraiḥ
vadhārthaṃ rāvaṇasyeha vihitaṃ puruṣottamam', null, 6107017),
('ramayana-6-107-18', 18, 'Yuddha Kanda, Sarga 107, Verse 18', 'सिद्धार्था खलु कौसल्या या त्वां राम गृहं गतम्।
वनान्निवृत्तं संहृष्टा द्रक्ष्यते शत्रुसूदन॥', 'siddhārthā khalu kausalyā yā tvāṃ rāma gṛhaṃ gatam
vanān nivṛttaṃ saṃhṛṣṭā drakṣyate śatrusūdana', null, 6107018),
('ramayana-6-107-19', 19, 'Yuddha Kanda, Sarga 107, Verse 19', 'सिद्धार्थाः खलु ते राम नरा ये त्वां पुरीं गतम्।
जलार्द्रमभिषिक्तं च द्रक्ष्यन्ति वसुधाधिपम्॥', 'siddhārthāḥ khalu te rāma narā ye tvāṃ purīṃ gatam
jalārdram abhiṣiktaṃ ca drakṣyanti vasudhādhipam', null, 6107019),
('ramayana-6-107-20', 20, 'Yuddha Kanda, Sarga 107, Verse 20', 'अनुरक्तेन बलिना शुचिना धर्मचारिणा।
इच्छेयं त्वामहं द्रष्टुं भरतेन समागतम्॥', 'anuraktena balinā śucinā dharmacāriṇā
iccheyaṃ tvām ahaṃ draṣṭuṃ bharatena samāgatam', null, 6107020),
('ramayana-6-107-21', 21, 'Yuddha Kanda, Sarga 107, Verse 21', 'चतुर्दशसमाः सौम्य वने निर्यापितास्त्वया।
वसता सीतया सार्धं लक्ष्मणेन च धीमता॥', 'caturdaśasamāḥ saumya vane niryāpitās tvayā
vasatā sītayā sārdhaṃ lakṣmaṇena ca dhīmatā', null, 6107021),
('ramayana-6-107-22', 22, 'Yuddha Kanda, Sarga 107, Verse 22', 'निवृत्तवनवासोऽसि प्रतिज्ञा सफला कृता।
रावणं च रणे हत्वा देवास्ते परितोषिताः॥', 'nivṛttavanavāso ''si pratijñā saphalā kṛtā
rāvaṇaṃ ca raṇe hatvā devās te paritoṣitāḥ', null, 6107022),
('ramayana-6-107-23', 23, 'Yuddha Kanda, Sarga 107, Verse 23', 'कृतं कर्म यशः श्लाघ्यं प्राप्तं ते शत्रुसूदन।
भ्रातृभिः सह राज्यस्थो दीर्घमायुरवाप्नुहि॥', 'kṛtaṃ karma yaśaḥ ślāghyaṃ prāptaṃ te śatrusūdana
bhrātṛbhiḥ saha rājyastho dīrgham āyur avāpnuhi', null, 6107023),
('ramayana-6-107-24', 24, 'Yuddha Kanda, Sarga 107, Verse 24', 'इति ब्रुवाणं राजानं रामः प्राञ्जलिरब्रवीत्।
कुरु प्रसादं धर्मज्ञ कैकेय्या भरतस्य च॥', 'iti bruvāṇaṃ rājānaṃ rāmaḥ prāñjalir abravīt
kuru prasādaṃ dharmajña kaikeyyā bharatasya ca', null, 6107024),
('ramayana-6-107-25', 25, 'Yuddha Kanda, Sarga 107, Verse 25', 'सपुत्रां त्वां त्यजामीति यदुक्ता कैकयी त्वया।
स शापः कैकयीं घोरः सपुत्रां न स्पृशेत्प्रभो॥', 'saputrāṃ tvāṃ tyajāmīti yad uktā kaikayī tvayā
sa śāpaḥ kaikayīṃ ghoraḥ saputrāṃ na spṛśet prabho', null, 6107025),
('ramayana-6-107-26', 26, 'Yuddha Kanda, Sarga 107, Verse 26', 'स तथेति महाराजो राममुक्त्वा कृताञ्जलिम्।
लक्ष्मणं च परिष्वज्य पुनर्वाक्यमुवाच ह॥', 'sa tatheti mahārājo rāmam uktvā kṛtāñjalim
lakṣmaṇaṃ ca pariṣvajya punar vākyam uvāca ha', null, 6107026),
('ramayana-6-107-27', 27, 'Yuddha Kanda, Sarga 107, Verse 27', 'रामं शुश्रूषता भक्त्या वैदेह्या सह सीतया।
कृता मम महाप्रीतिः प्राप्तं धर्मफलं च ते॥', 'rāmaṃ śuśrūṣatā bhaktyā vaidehyā saha sītayā
kṛtā mama mahāprītiḥ prāptaṃ dharmaphalaṃ ca te', null, 6107027),
('ramayana-6-107-28', 28, 'Yuddha Kanda, Sarga 107, Verse 28', 'धर्मं प्राप्स्यसि धर्मज्ञ यशश्च विपुलं भुवि।
रामे प्रसन्ने स्वर्गं च महिमानं तथैव च॥', 'dharmaṃ prāpsyasi dharmajña yaśaś ca vipulaṃ bhuvi
rāme prasanne svargaṃ ca mahimānaṃ tathaiva ca', null, 6107028),
('ramayana-6-107-29', 29, 'Yuddha Kanda, Sarga 107, Verse 29', 'रामं शुश्रूष भद्रं ते सुमित्रानन्दवर्धन।
रामः सर्वस्य लोकस्य शुभेष्वभिरतः सदा॥', 'rāmaṃ śuśrūṣa bhadraṃ te sumitrānandavardhana
rāmaḥ sarvasya lokasya śubheṣv abhirataḥ sadā', null, 6107029),
('ramayana-6-107-30', 30, 'Yuddha Kanda, Sarga 107, Verse 30', 'एते सेन्द्रास्त्रयो लोकाः सिद्धाश्च परमर्षयः।
अभिगम्य महात्मानमर्चन्ति पुरुषोत्तमम्॥', 'ete sendrās trayo lokāḥ siddhāś ca paramarṣayaḥ
abhigamya mahātmānam arcanti puruṣottamam', null, 6107030),
('ramayana-6-107-31', 31, 'Yuddha Kanda, Sarga 107, Verse 31', 'एतत्तदुक्तमव्यक्तमक्षरं ब्रह्मनिर्मितम्।
देवानां हृदयं सौम्य गुह्यं रामः परंतपः॥', 'etat tad uktam avyaktam akṣaraṃ brahmanirmitam
devānāṃ hṛdayaṃ saumya guhyaṃ rāmaḥ paraṃtapaḥ', null, 6107031),
('ramayana-6-107-32', 32, 'Yuddha Kanda, Sarga 107, Verse 32', 'अवाप्तं धर्मचरणं यशश्च विपुलं त्वया।
रामं शुश्रूषता भक्त्या वैदेह्या सह सीतया॥', 'avāptaṃ dharmacaraṇaṃ yaśaś ca vipulaṃ tvayā
rāmaṃ śuśrūṣatā bhaktyā vaidehyā saha sītayā', null, 6107032),
('ramayana-6-107-33', 33, 'Yuddha Kanda, Sarga 107, Verse 33', 'स तथोक्त्वा महाबाहुर्लक्ष्मणं प्राञ्जलिं स्थितम्।
उवाच राजा धर्मात्मा वैदेहीं वचनं शुभम्॥', 'sa tathoktvā mahābāhur lakṣmaṇaṃ prāñjaliṃ sthitam
uvāca rājā dharmātmā vaidehīṃ vacanaṃ śubham', null, 6107033),
('ramayana-6-107-34', 34, 'Yuddha Kanda, Sarga 107, Verse 34', 'कर्तव्यो न तु वैदेहि मन्युस्त्यागमिमं प्रति।
रामेण त्वद्विशुद्ध्यर्थं कृतमेतद्धितैषिणा॥', 'kartavyo na tu vaidehi manyus tyāgam imaṃ prati
rāmeṇa tvadviśuddhyarthaṃ kṛtam etad dhitaiṣiṇā', null, 6107034),
('ramayana-6-107-35', 35, 'Yuddha Kanda, Sarga 107, Verse 35', 'न त्वं सुभ्रु समाधेया पतिशुश्रूवणं प्रति।
अवश्यं तु मया वाच्यमेष ते दैवतं परम्॥', 'na tvaṃ subhru samādheyā patiśuśrūvaṇaṃ prati
avaśyaṃ tu mayā vācyam eṣa te daivataṃ param', null, 6107035),
('ramayana-6-107-36', 36, 'Yuddha Kanda, Sarga 107, Verse 36', 'इति प्रतिसमादिश्य पुत्रौ सीतां तथा स्नुषाम्।
इन्द्रलोकं विमानेन ययौ दशरथो ज्वलन्॥', 'iti pratisamādiśya putrau sītāṃ tathā snuṣām
indralokaṃ vimānena yayau daśaratho jvalan', null, 6107036)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 108 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-108-1', 1, 'Yuddha Kanda, Sarga 108, Verse 1', 'प्रतिप्रयाते काकुत्स्थे महेन्द्रः पाकशासनः।
अब्रवीत्परमप्रीतो राघवं प्राञ्जलिं स्थितम्॥', 'pratiprayāte kākutsthe mahendraḥ pākaśāsanaḥ
abravīt paramaprīto rāghavaṃ prāñjaliṃ sthitam', null, 6108001),
('ramayana-6-108-2', 2, 'Yuddha Kanda, Sarga 108, Verse 2', 'अमोघं दर्शनं राम तवास्माकं परंतप।
प्रीतियुक्तोऽस्मि तेन त्वं ब्रूहि यन्मनसेच्छसि॥', 'amoghaṃ darśanaṃ rāma tavāsmākaṃ paraṃtapa
prītiyukto ''smi tena tvaṃ brūhi yan manasecchasi', null, 6108002),
('ramayana-6-108-3', 3, 'Yuddha Kanda, Sarga 108, Verse 3', 'एवमुक्तस्तु काकुत्स्थः प्रत्युवाच कृताञ्जलिः।
लक्ष्मणेन सह भ्रात्रा सीतया चापि भार्यया॥', 'evam uktas tu kākutsthaḥ pratyuvāca kṛtāñjaliḥ
lakṣmaṇena saha bhrātrā sītayā cāpi bhāryayā', null, 6108003),
('ramayana-6-108-4', 4, 'Yuddha Kanda, Sarga 108, Verse 4', 'यदि प्रीतिः समुत्पन्ना मयि सर्वसुरेश्वर।
वक्ष्यामि कुरु मे सत्यं वचनं वदतां वर॥', 'yadi prītiḥ samutpannā mayi sarvasureśvara
vakṣyāmi kuru me satyaṃ vacanaṃ vadatāṃ vara', null, 6108004),
('ramayana-6-108-5', 5, 'Yuddha Kanda, Sarga 108, Verse 5', 'मम हेतोः पराक्रान्ता ये गता यमसादनम्।
ते सर्वे जीवितं प्राप्य समुत्तिष्ठन्तु वानराः॥', 'mama hetoḥ parākrāntā ye gatā yamasādanam
te sarve jīvitaṃ prāpya samuttiṣṭhantu vānarāḥ', null, 6108005),
('ramayana-6-108-6', 6, 'Yuddha Kanda, Sarga 108, Verse 6', 'मत्प्रियेष्वभिरक्ताश्च न मृत्युं गणयन्ति च।
त्वत्प्रसादात्समेयुस्ते वरमेतदहं वृणे॥', 'matpriyeṣv abhiraktāś ca na mṛtyuṃ gaṇayanti ca
tvatprasādāt sameyus te varam etad ahaṃ vṛṇe', null, 6108006),
('ramayana-6-108-7', 7, 'Yuddha Kanda, Sarga 108, Verse 7', 'नीरुजान्निर्व्रणांश्चैव संपन्नबलपौरुषान्।
गोलाङ्गूलांस्तथैवर्क्षान्द्रष्टुमिच्छामि मानद॥', 'nīrujān nirvraṇāṃś caiva saṃpannabalapauruṣān
golāṅgūlāṃs tathaivarkṣān draṣṭum icchāmi mānada', null, 6108007),
('ramayana-6-108-8', 8, 'Yuddha Kanda, Sarga 108, Verse 8', 'अकाले चापि मुख्यानि मूलानि च फलानि च।
नद्यश्च विमलास्तत्र तिष्ठेयुर्यत्र वानराः॥', 'akāle cāpi mukhyāni mūlāni ca phalāni ca
nadyaś ca vimalās tatra tiṣṭheyur yatra vānarāḥ', null, 6108008),
('ramayana-6-108-9', 9, 'Yuddha Kanda, Sarga 108, Verse 9', 'श्रुत्वा तु वचनं तस्य राघवस्य महात्मनः।
महेन्द्रः प्रत्युवाचेदं वचनं प्रीतिलक्षणम्॥', 'śrutvā tu vacanaṃ tasya rāghavasya mahātmanaḥ
mahendraḥ pratyuvācedaṃ vacanaṃ prītilakṣaṇam', null, 6108009),
('ramayana-6-108-10', 10, 'Yuddha Kanda, Sarga 108, Verse 10', 'महानयं वरस्तात त्वयोक्तो रघुनन्दन।
समुत्थास्यन्ति हरयः सुप्ता निद्राक्षये यथा॥', 'mahān ayaṃ varas tāta tvayokto raghunandana
samutthāsyanti harayaḥ suptā nidrākṣaye yathā', null, 6108010),
('ramayana-6-108-11', 11, 'Yuddha Kanda, Sarga 108, Verse 11', 'सुहृद्भिर्बान्धवैश्चैव ज्ञातिभिः स्वजनेन च।
सर्व एव समेष्यन्ति संयुक्ताः परया मुदा॥', 'suhṛdbhir bāndhavaiś caiva jñātibhiḥ svajanena ca
sarva eva sameṣyanti saṃyuktāḥ parayā mudā', null, 6108011),
('ramayana-6-108-12', 12, 'Yuddha Kanda, Sarga 108, Verse 12', 'अकाले पुष्पशबलाः फलवन्तश्च पादपाः।
भविष्यन्ति महेष्वास नद्यश्च सलिलायुताः॥', 'akāle puṣpaśabalāḥ phalavantaś ca pādapāḥ
bhaviṣyanti maheṣvāsa nadyaś ca salilāyutāḥ', null, 6108012),
('ramayana-6-108-13', 13, 'Yuddha Kanda, Sarga 108, Verse 13', 'सव्रणैः प्रथमं गात्रैः संवृतैर्निव्रणैः पुनः।
बभूवुर्वानराः सर्वे किमेतदिति विस्मितः॥', 'savraṇaiḥ prathamaṃ gātraiḥ saṃvṛtair nivraṇaiḥ punaḥ
babhūvur vānarāḥ sarve kim etad iti vismitaḥ', null, 6108013),
('ramayana-6-108-14', 14, 'Yuddha Kanda, Sarga 108, Verse 14', 'काकुत्स्थं परिपूर्णार्थं दृष्ट्वा सर्वे सुरोत्तमाः।
ऊचुस्ते प्रथमं स्तुत्वा स्तवार्हं सहलक्ष्मणम्॥', 'kākutsthaṃ paripūrṇārthaṃ dṛṣṭvā sarve surottamāḥ
ūcus te prathamaṃ stutvā stavārhaṃ sahalakṣmaṇam', null, 6108014),
('ramayana-6-108-15', 15, 'Yuddha Kanda, Sarga 108, Verse 15', 'गच्छायोध्यामितो वीर विसर्जय च वानरान्।
मैथिलीं सान्त्वयस्वैनामनुरक्तां तपस्विनीम्॥', 'gacchāyodhyām ito vīra visarjaya ca vānarān
maithilīṃ sāntvayasvainām anuraktāṃ tapasvinīm', null, 6108015),
('ramayana-6-108-16', 16, 'Yuddha Kanda, Sarga 108, Verse 16', 'भ्रातरं पश्य भरतं त्वच्छोकाद्व्रतचारिणम्।
अभिषेचय चात्मानं पौरान्गत्वा प्रहर्षय॥', 'bhrātaraṃ paśya bharataṃ tvacchokād vratacāriṇam
abhiṣecaya cātmānaṃ paurān gatvā praharṣaya', null, 6108016),
('ramayana-6-108-17', 17, 'Yuddha Kanda, Sarga 108, Verse 17', 'एवमुक्त्वा तमामन्त्र्य रामं सौमित्रिणा सह।
विमानैः सूर्यसंकाशैर्हृष्टा जग्मुः सुरा दिवम्॥', 'evam uktvā tam āmantrya rāmaṃ saumitriṇā saha
vimānaiḥ sūryasaṃkāśair hṛṣṭā jagmuḥ surā divam', null, 6108017),
('ramayana-6-108-18', 18, 'Yuddha Kanda, Sarga 108, Verse 18', 'अभिवाद्य च काकुत्स्थः सर्वांस्तांस्त्रिदशोत्तमान्।
लक्ष्मणेन सह भ्रात्रा वासमाज्ञापयत्तदा॥', 'abhivādya ca kākutsthaḥ sarvāṃs tāṃs tridaśottamān
lakṣmaṇena saha bhrātrā vāsam ājñāpayat tadā', null, 6108018),
('ramayana-6-108-19', 19, 'Yuddha Kanda, Sarga 108, Verse 19', 'ततस्तु सा लक्ष्मणरामपालिता महाचमूर्हृष्टजना यशस्विनी।
श्रिया ज्वलन्ती विरराज सर्वतो निशाप्रणीतेव हि शीतरश्मिना॥', 'tatas tu sā lakṣmaṇarāmapālitā mahācamūr hṛṣṭajanā yaśasvinī
śriyā jvalantī virarāja sarvato niśāpraṇīteva hi śītaraśminā', null, 6108019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 109 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-109-1', 1, 'Yuddha Kanda, Sarga 109, Verse 1', 'तां रात्रिमुषितं रामं सुखोत्थितमरिंदमम्।
अब्रवीत्प्राञ्जलिर्वाक्यं जयं पृष्ट्वा विभीषणः॥', 'tāṃ rātrim uṣitaṃ rāmaṃ sukhotthitam ariṃdamam
abravīt prāñjalir vākyaṃ jayaṃ pṛṣṭvā vibhīṣaṇaḥ', null, 6109001),
('ramayana-6-109-2', 2, 'Yuddha Kanda, Sarga 109, Verse 2', 'स्नानानि चाङ्गरागाणि वस्त्राण्याभरणानि च।
चन्दनानि च दिव्यानि माल्यानि विविधानि च॥', 'snānāni cāṅgarāgāṇi vastrāṇy ābharaṇāni ca
candanāni ca divyāni mālyāni vividhāni ca', null, 6109002),
('ramayana-6-109-3', 3, 'Yuddha Kanda, Sarga 109, Verse 3', 'अलंकारविदश्चेमा नार्यः पद्मनिभेक्षणाः।
उपस्थितास्त्वां विधिवत्स्नापयिष्यन्ति राघव॥', 'alaṃkāravidaś cemā nāryaḥ padmanibhekṣaṇāḥ
upasthitās tvāṃ vidhivat snāpayiṣyanti rāghava', null, 6109003),
('ramayana-6-109-4', 4, 'Yuddha Kanda, Sarga 109, Verse 4', 'एवमुक्तस्तु काकुत्स्थः प्रत्युवाच विभीषणम्।
हरीन्सुग्रीवमुख्यांस्त्वं स्नानेनोपनिमन्त्रय॥', 'evam uktas tu kākutsthaḥ pratyuvāca vibhīṣaṇam
harīn sugrīvamukhyāṃs tvaṃ snānenopanimantraya', null, 6109004),
('ramayana-6-109-5', 5, 'Yuddha Kanda, Sarga 109, Verse 5', 'स तु ताम्यति धर्मात्मा ममहेतोः सुखोचितः।
सुकुमारो महाबाहुः कुमारः सत्यसंश्रवः॥', 'sa tu tāmyati dharmātmā mamahetoḥ sukhocitaḥ
sukumāro mahābāhuḥ kumāraḥ satyasaṃśravaḥ', null, 6109005),
('ramayana-6-109-6', 6, 'Yuddha Kanda, Sarga 109, Verse 6', 'तं विना कैकेयीपुत्रं भरतं धर्मचारिणम्।
न मे स्नानं बहुमतं वस्त्राण्याभरणानि च॥', 'taṃ vinā kaikeyīputraṃ bharataṃ dharmacāriṇam
na me snānaṃ bahumataṃ vastrāṇy ābharaṇāni ca', null, 6109006),
('ramayana-6-109-7', 7, 'Yuddha Kanda, Sarga 109, Verse 7', 'इत एव पथा क्षिप्रं प्रतिगच्छाम तां पुरीम्।
अयोध्यामायतो ह्येष पन्थाः परमदुर्गमः॥', 'ita eva pathā kṣipraṃ pratigacchāma tāṃ purīm
ayodhyām āyato hy eṣa panthāḥ paramadurgamaḥ', null, 6109007),
('ramayana-6-109-8', 8, 'Yuddha Kanda, Sarga 109, Verse 8', 'एवमुक्तस्तु काकुत्स्थं प्रत्युवाच विभीषणः।
अह्ना त्वां प्रापयिष्यामि तां पुरीं पार्थिवात्मज॥', 'evam uktas tu kākutsthaṃ pratyuvāca vibhīṣaṇaḥ
ahnā tvāṃ prāpayiṣyāmi tāṃ purīṃ pārthivātmaja', null, 6109008),
('ramayana-6-109-9', 9, 'Yuddha Kanda, Sarga 109, Verse 9', 'पुष्पकं नाम भद्रं ते विमानं सूर्यसंनिभम्।
मम भ्रातुः कुबेरस्य रावणेनाहृतं बलात्॥', 'puṣpakaṃ nāma bhadraṃ te vimānaṃ sūryasaṃnibham
mama bhrātuḥ kuberasya rāvaṇenāhṛtaṃ balāt', null, 6109009),
('ramayana-6-109-10', 10, 'Yuddha Kanda, Sarga 109, Verse 10', 'तदिदं मेघसंकाशं विमानमिह तिष्ठति।
तेन यास्यसि यानेन त्वमयोध्यां गजज्वरः॥', 'tad idaṃ meghasaṃkāśaṃ vimānam iha tiṣṭhati
tena yāsyasi yānena tvam ayodhyāṃ gajajvaraḥ', null, 6109010),
('ramayana-6-109-11', 11, 'Yuddha Kanda, Sarga 109, Verse 11', 'अहं ते यद्यनुग्राह्यो यदि स्मरसि मे गुणान्।
वस तावदिह प्राज्ञ यद्यस्ति मयि सौहृदम्॥', 'ahaṃ te yady anugrāhyo yadi smarasi me guṇān
vasa tāvad iha prājña yady asti mayi sauhṛdam', null, 6109011),
('ramayana-6-109-12', 12, 'Yuddha Kanda, Sarga 109, Verse 12', 'लक्ष्मणेन सह भ्रात्रा वैदेह्या चापि भार्यया।
अर्चितः सर्वकामैस्त्वं ततो राम गमिष्यसि॥', 'lakṣmaṇena saha bhrātrā vaidehyā cāpi bhāryayā
arcitaḥ sarvakāmais tvaṃ tato rāma gamiṣyasi', null, 6109012),
('ramayana-6-109-13', 13, 'Yuddha Kanda, Sarga 109, Verse 13', 'प्रीतियुक्तस्तु मे राम ससैन्यः ससुहृद्गणः।
सत्क्रियां विहितां तावद्गृहाण त्वं मयोद्यताम्॥', 'prītiyuktas tu me rāma sasainyaḥ sasuhṛdgaṇaḥ
satkriyāṃ vihitāṃ tāvad gṛhāṇa tvaṃ mayodyatām', null, 6109013),
('ramayana-6-109-14', 14, 'Yuddha Kanda, Sarga 109, Verse 14', 'प्रणयाद्बहुमानाच्च सौहृदेन च राघव।
प्रसादयामि प्रेष्योऽहं न खल्वाज्ञापयामि ते॥', 'praṇayād bahumānāc ca sauhṛdena ca rāghava
prasādayāmi preṣyo ''haṃ na khalv ājñāpayāmi te', null, 6109014),
('ramayana-6-109-15', 15, 'Yuddha Kanda, Sarga 109, Verse 15', 'एवमुक्तस्ततो रामः प्रत्युवाच विभीषणम्।
रक्षसां वानराणां च सर्वेषां चोपशृण्वताम्॥', 'evam uktas tato rāmaḥ pratyuvāca vibhīṣaṇam
rakṣasāṃ vānarāṇāṃ ca sarveṣāṃ copaśṛṇvatām', null, 6109015),
('ramayana-6-109-16', 16, 'Yuddha Kanda, Sarga 109, Verse 16', 'पूजितोऽहं त्वया वीर साचिव्येन परंतप।
सर्वात्मना च चेष्टिभिः सौहृदेनोत्तमेन च॥', 'pūjito ''haṃ tvayā vīra sācivyena paraṃtapa
sarvātmanā ca ceṣṭibhiḥ sauhṛdenottamena ca', null, 6109016),
('ramayana-6-109-17', 17, 'Yuddha Kanda, Sarga 109, Verse 17', 'न खल्वेतन्न कुर्यां ते वचनं राक्षसेश्वर।
तं तु मे भ्रातरं द्रष्टुं भरतं त्वरते मनः॥', 'na khalv etan na kuryāṃ te vacanaṃ rākṣaseśvara
taṃ tu me bhrātaraṃ draṣṭuṃ bharataṃ tvarate manaḥ', null, 6109017),
('ramayana-6-109-18', 18, 'Yuddha Kanda, Sarga 109, Verse 18', 'मां निवर्तयितुं योऽसौ चित्रकूटमुपागतः।
शिरसा याचतो यस्य वचनं न कृतं मया॥', 'māṃ nivartayituṃ yo ''sau citrakūṭam upāgataḥ
śirasā yācato yasya vacanaṃ na kṛtaṃ mayā', null, 6109018),
('ramayana-6-109-19', 19, 'Yuddha Kanda, Sarga 109, Verse 19', 'कौसल्यां च सुमित्रां च कैकेयीं च यशस्विनीम्।
गुरूंश्च सुहृदश्चैव पौरांश्च तनयैः सह॥', 'kausalyāṃ ca sumitrāṃ ca kaikeyīṃ ca yaśasvinīm
gurūṃś ca suhṛdaś caiva paurāṃś ca tanayaiḥ saha', null, 6109019),
('ramayana-6-109-20', 20, 'Yuddha Kanda, Sarga 109, Verse 20', 'उपस्थापय मे क्षिप्रं विमानं राक्षसेश्वर।
कृतकार्यस्य मे वासः कथं चिदिह संमतः॥', 'upasthāpaya me kṣipraṃ vimānaṃ rākṣaseśvara
kṛtakāryasya me vāsaḥ kathaṃ cid iha saṃmataḥ', null, 6109020),
('ramayana-6-109-21', 21, 'Yuddha Kanda, Sarga 109, Verse 21', 'अनुजानीहि मां सौम्य पूजितोऽस्मि विभीषण।
मन्युर्न खलु कर्तव्यस्त्वरितस्त्वानुमानये॥', 'anujānīhi māṃ saumya pūjito ''smi vibhīṣaṇa
manyur na khalu kartavyas tvaritas tvānumānaye', null, 6109021),
('ramayana-6-109-22', 22, 'Yuddha Kanda, Sarga 109, Verse 22', 'ततः काञ्चनचित्राङ्गं वैदूर्यमणिवेदिकम्।
कूटागारैः परिक्षिप्तं सर्वतो रजतप्रभम्॥', 'tataḥ kāñcanacitrāṅgaṃ vaidūryamaṇivedikam
kūṭāgāraiḥ parikṣiptaṃ sarvato rajataprabham', null, 6109022),
('ramayana-6-109-23', 23, 'Yuddha Kanda, Sarga 109, Verse 23', 'पाण्डुराभिः पताकाभिर्ध्वजैश्च समलंकृतम्।
शोभितं काञ्चनैर्हर्म्यैर्हेमपद्मविभूषितम्॥', 'pāṇḍurābhiḥ patākābhir dhvajaiś ca samalaṃkṛtam
śobhitaṃ kāñcanair harmyair hemapadmavibhūṣitam', null, 6109023),
('ramayana-6-109-24', 24, 'Yuddha Kanda, Sarga 109, Verse 24', 'प्रकीर्णं किङ्किणीजालैर्मुक्तामणिगवाक्षितम्।
घण्टाजालैः परिक्षिप्तं सर्वतो मधुरस्वनम्॥', 'prakīrṇaṃ kiṅkiṇījālair muktāmaṇigavākṣitam
ghaṇṭājālaiḥ parikṣiptaṃ sarvato madhurasvanam', null, 6109024),
('ramayana-6-109-25', 25, 'Yuddha Kanda, Sarga 109, Verse 25', 'तन्मेरुशिखराकारं निर्मितं विश्वकर्मणा।
बहुभिर्भूषितं हर्म्यैर्मुक्तारजतसंनिभौ॥', 'tan meruśikharākāraṃ nirmitaṃ viśvakarmaṇā
bahubhir bhūṣitaṃ harmyair muktārajatasaṃnibhau', null, 6109025),
('ramayana-6-109-26', 26, 'Yuddha Kanda, Sarga 109, Verse 26', 'तलैः स्फटिकचित्राङ्गैर्वैदूर्यैश्च वरासनैः।
महार्हास्तरणोपेतैरुपपन्नं महाधनैः॥', 'talaiḥ sphaṭikacitrāṅgair vaidūryaiś ca varāsanaiḥ
mahārhāstaraṇopetair upapannaṃ mahādhanaiḥ', null, 6109026),
('ramayana-6-109-27', 27, 'Yuddha Kanda, Sarga 109, Verse 27', 'उपस्थितमनाधृष्यं तद्विमानं मनोजवम्।
निवेदयित्वा रामाय तस्थौ तत्र विभीषणः॥', 'upasthitam anādhṛṣyaṃ tad vimānaṃ manojavam
nivedayitvā rāmāya tasthau tatra vibhīṣaṇaḥ', null, 6109027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 110 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-110-1', 1, 'Yuddha Kanda, Sarga 110, Verse 1', 'उपस्थितं तु तं दृष्ट्वा पुष्पकं पुष्पभूषितम्।
अविदूरे स्थितं रामं प्रत्युवाच विभीषणः॥', 'upasthitaṃ tu taṃ dṛṣṭvā puṣpakaṃ puṣpabhūṣitam
avidūre sthitaṃ rāmaṃ pratyuvāca vibhīṣaṇaḥ', null, 6110001),
('ramayana-6-110-2', 2, 'Yuddha Kanda, Sarga 110, Verse 2', 'स तु बद्धाञ्जलिः प्रह्वो विनीतो राक्षसेश्वरः।
अब्रवीत्त्वरयोपेतः किं करोमीति राघवम्॥', 'sa tu baddhāñjaliḥ prahvo vinīto rākṣaseśvaraḥ
abravīt tvarayopetaḥ kiṃ karomīti rāghavam', null, 6110002),
('ramayana-6-110-3', 3, 'Yuddha Kanda, Sarga 110, Verse 3', 'तमब्रवीन्महातेजा लक्ष्मणस्योपशृण्वतः।
विमृश्य राघवो वाक्यमिदं स्नेहपुरस्कृतम्॥', 'tam abravīn mahātejā lakṣmaṇasyopaśṛṇvataḥ
vimṛśya rāghavo vākyam idaṃ snehapuraskṛtam', null, 6110003),
('ramayana-6-110-4', 4, 'Yuddha Kanda, Sarga 110, Verse 4', 'कृतप्रयत्नकर्माणो विभीषण वनौकसः।
रत्नैरर्थैश्च विविभैर्भूषणैश्चाभिपूजय॥', 'kṛtaprayatnakarmāṇo vibhīṣaṇa vanaukasaḥ
ratnair arthaiś ca vivibhair bhūṣaṇaiś cābhipūjaya', null, 6110004),
('ramayana-6-110-5', 5, 'Yuddha Kanda, Sarga 110, Verse 5', 'सहैभिरर्दिता लङ्का निर्जिता राक्षसेश्वर।
हृष्टैः प्राणभयं त्यक्त्वा संग्रामेष्वनिवर्तिभिः॥', 'sahaibhir arditā laṅkā nirjitā rākṣaseśvara
hṛṣṭaiḥ prāṇabhayaṃ tyaktvā saṃgrāmeṣv anivartibhiḥ', null, 6110005),
('ramayana-6-110-6', 6, 'Yuddha Kanda, Sarga 110, Verse 6', 'एवं संमानिताश्चेमे मानार्हा मानद त्वया।
भविष्यन्ति कृतज्ञेन निर्वृता हरियूथपाः॥', 'evaṃ saṃmānitāś ceme mānārhā mānada tvayā
bhaviṣyanti kṛtajñena nirvṛtā hariyūthapāḥ', null, 6110006),
('ramayana-6-110-7', 7, 'Yuddha Kanda, Sarga 110, Verse 7', 'त्यागिनं संग्रहीतारं सानुक्रोशं यशस्विनम्।
यतस्त्वामवगच्छन्ति ततः संबोधयामि ते॥', 'tyāginaṃ saṃgrahītāraṃ sānukrośaṃ yaśasvinam
yatas tvām avagacchanti tataḥ saṃbodhayāmi te', null, 6110007),
('ramayana-6-110-8', 8, 'Yuddha Kanda, Sarga 110, Verse 8', 'एवमुक्तस्तु रामेण वानरांस्तान्विभीषणः।
रत्नार्थैः संविभागेन सर्वानेवान्वपूजयत्॥', 'evam uktas tu rāmeṇa vānarāṃs tān vibhīṣaṇaḥ
ratnārthaiḥ saṃvibhāgena sarvān evānvapūjayat', null, 6110008),
('ramayana-6-110-9', 9, 'Yuddha Kanda, Sarga 110, Verse 9', 'ततस्तान्पूजितान्दृष्ट्वा रत्नैरर्थैश्च यूथपान्।
आरुरोह ततो रामस्तद्विमानमनुत्तमम्॥', 'tatas tān pūjitān dṛṣṭvā ratnair arthaiś ca yūthapān
āruroha tato rāmas tad vimānam anuttamam', null, 6110009),
('ramayana-6-110-10', 10, 'Yuddha Kanda, Sarga 110, Verse 10', 'अङ्केनादाय वैदेहीं लज्जमानां यशस्विनीम्।
लक्ष्मणेन सह भ्रात्रा विक्रान्तेन धनुष्मता॥', 'aṅkenādāya vaidehīṃ lajjamānāṃ yaśasvinīm
lakṣmaṇena saha bhrātrā vikrāntena dhanuṣmatā', null, 6110010),
('ramayana-6-110-11', 11, 'Yuddha Kanda, Sarga 110, Verse 11', 'अब्रवीच्च विमानस्थः काकुत्स्थः सर्ववानरान्।
सुग्रीवं च महावीर्यं राक्षसं च विभीषणम्॥', 'abravīc ca vimānasthaḥ kākutsthaḥ sarvavānarān
sugrīvaṃ ca mahāvīryaṃ rākṣasaṃ ca vibhīṣaṇam', null, 6110011),
('ramayana-6-110-12', 12, 'Yuddha Kanda, Sarga 110, Verse 12', 'मित्रकार्यं कृतमिदं भवद्भिर्वानरोत्तमाः।
अनुज्ञाता मया सर्वे यथेष्टं प्रतिगच्छत॥', 'mitrakāryaṃ kṛtam idaṃ bhavadbhir vānarottamāḥ
anujñātā mayā sarve yatheṣṭaṃ pratigacchata', null, 6110012),
('ramayana-6-110-13', 13, 'Yuddha Kanda, Sarga 110, Verse 13', 'यत्तु कार्यं वयस्येन सुहृदा वा परंतप।
कृतं सुग्रीव तत्सर्वं भवता धर्मभीरुणा।
किष्किन्धां प्रतियाह्याशु स्वसैन्येनाभिसंवृतः॥', 'yat tu kāryaṃ vayasyena suhṛdā vā paraṃtapa
kṛtaṃ sugrīva tat sarvaṃ bhavatā dharmabhīruṇā
kiṣkindhāṃ pratiyāhy āśu svasainyenābhisaṃvṛtaḥ', null, 6110013),
('ramayana-6-110-14', 14, 'Yuddha Kanda, Sarga 110, Verse 14', 'स्वराज्ये वस लङ्कायां मया दत्ते विभीषण।
न त्वां धर्षयितुं शक्ताः सेन्द्रा अपि दिवौकसः॥', 'svarājye vasa laṅkāyāṃ mayā datte vibhīṣaṇa
na tvāṃ dharṣayituṃ śaktāḥ sendrā api divaukasaḥ', null, 6110014),
('ramayana-6-110-15', 15, 'Yuddha Kanda, Sarga 110, Verse 15', 'अयोध्यां प्रतियास्यामि राजधानीं पितुर्मम।
अभ्यनुज्ञातुमिच्छामि सर्वानामन्त्रयामि वः॥', 'ayodhyāṃ pratiyāsyāmi rājadhānīṃ pitur mama
abhyanujñātum icchāmi sarvān āmantrayāmi vaḥ', null, 6110015),
('ramayana-6-110-16', 16, 'Yuddha Kanda, Sarga 110, Verse 16', 'एवमुक्तास्तु रामेण वानरास्ते महाबलाः।
ऊचुः प्राञ्जलयो रामं राक्षसश्च विभीषणः।
अयोध्यां गन्तुमिच्छामः सर्वान्नयतु नो भवान्॥', 'evam uktās tu rāmeṇa vānarās te mahābalāḥ
ūcuḥ prāñjalayo rāmaṃ rākṣasaś ca vibhīṣaṇaḥ
ayodhyāṃ gantum icchāmaḥ sarvān nayatu no bhavān', null, 6110016),
('ramayana-6-110-17', 17, 'Yuddha Kanda, Sarga 110, Verse 17', 'दृष्ट्वा त्वामभिषेकार्द्रं कौसल्यामभिवाद्य च।
अचिरेणागमिष्यामः स्वान्गृहान्नृपतेः सुत॥', 'dṛṣṭvā tvām abhiṣekārdraṃ kausalyām abhivādya ca
acireṇāgamiṣyāmaḥ svān gṛhān nṛpateḥ suta', null, 6110017),
('ramayana-6-110-18', 18, 'Yuddha Kanda, Sarga 110, Verse 18', 'एवमुक्तस्तु धर्मात्मा वानरैः सविभीषणैः।
अब्रवीद्राघवः श्रीमान्ससुग्रीवविभीषणान्॥', 'evam uktas tu dharmātmā vānaraiḥ savibhīṣaṇaiḥ
abravīd rāghavaḥ śrīmān sasugrīvavibhīṣaṇān', null, 6110018),
('ramayana-6-110-19', 19, 'Yuddha Kanda, Sarga 110, Verse 19', 'प्रियात्प्रियतरं लब्धं यदहं ससुहृज्जनः।
सर्वैर्भवद्भिः सहितः प्रीतिं लप्स्ये पुरीं गतः॥', 'priyāt priyataraṃ labdhaṃ yad ahaṃ sasuhṛjjanaḥ
sarvair bhavadbhiḥ sahitaḥ prītiṃ lapsye purīṃ gataḥ', null, 6110019),
('ramayana-6-110-20', 20, 'Yuddha Kanda, Sarga 110, Verse 20', 'क्षिप्रमारोह सुग्रीव विमानं वानरैः सह।
त्वमध्यारोह सामात्यो राक्षसेन्द्रविभीषण॥', 'kṣipram āroha sugrīva vimānaṃ vānaraiḥ saha
tvam adhyāroha sāmātyo rākṣasendravibhīṣaṇa', null, 6110020),
('ramayana-6-110-21', 21, 'Yuddha Kanda, Sarga 110, Verse 21', 'ततस्तत्पुष्पकं दिव्यं सुग्रीवः सह सेनया।
अध्यारोहत्त्वरञ्शीघ्रं सामात्यश्च विभीषणः॥', 'tatas tat puṣpakaṃ divyaṃ sugrīvaḥ saha senayā
adhyārohat tvarañ śīghraṃ sāmātyaś ca vibhīṣaṇaḥ', null, 6110021),
('ramayana-6-110-22', 22, 'Yuddha Kanda, Sarga 110, Verse 22', 'तेष्वारूढेषु सर्वेषु कौबेरं परमासनम्।
राघवेणाभ्यनुज्ञातमुत्पपात विहायसं॥', 'teṣv ārūḍheṣu sarveṣu kauberaṃ paramāsanam
rāghaveṇābhyanujñātam utpapāta vihāyasaṃ', null, 6110022),
('ramayana-6-110-23', 23, 'Yuddha Kanda, Sarga 110, Verse 23', 'ययौ तेन विमानेन हंसयुक्तेन भास्वता।
प्रहृष्टश्च प्रतीतश्च बभौ रामः कुबेरवत्॥', 'yayau tena vimānena haṃsayuktena bhāsvatā
prahṛṣṭaś ca pratītaś ca babhau rāmaḥ kuberavat', null, 6110023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 111 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-111-1', 1, 'Yuddha Kanda, Sarga 111, Verse 1', 'अनुज्ञातं तु रामेण तद्विमानमनुत्तमम्।
उत्पपात महामेघः श्वसनेनोद्धतो यथा॥', 'anujñātaṃ tu rāmeṇa tad vimānam anuttamam
utpapāta mahāmeghaḥ śvasanenoddhato yathā', null, 6111001),
('ramayana-6-111-2', 2, 'Yuddha Kanda, Sarga 111, Verse 2', 'पातयित्वा ततश्चक्षुः सर्वतो रघुनन्दनः।
अब्रवीन्मैथिलीं सीतां रामः शशिनिभाननाम्॥', 'pātayitvā tataś cakṣuḥ sarvato raghunandanaḥ
abravīn maithilīṃ sītāṃ rāmaḥ śaśinibhānanām', null, 6111002),
('ramayana-6-111-3', 3, 'Yuddha Kanda, Sarga 111, Verse 3', 'कैलासशिखराकारे त्रिकूटशिखरे स्थिताम्।
लङ्कामीक्षस्व वैदेहि निर्मितां विश्वकर्मणा॥', 'kailāsaśikharākāre trikūṭaśikhare sthitām
laṅkām īkṣasva vaidehi nirmitāṃ viśvakarmaṇā', null, 6111003),
('ramayana-6-111-4', 4, 'Yuddha Kanda, Sarga 111, Verse 4', 'एतदायोधनं पश्य मांसशोणितकर्दमम्।
हरीणां राक्षसानां च सीते विशसनं महत्॥', 'etad āyodhanaṃ paśya māṃsaśoṇitakardamam
harīṇāṃ rākṣasānāṃ ca sīte viśasanaṃ mahat', null, 6111004),
('ramayana-6-111-5', 5, 'Yuddha Kanda, Sarga 111, Verse 5', 'तवहेतोर्विशालाक्षि रावणो निहतो मया।
कुम्भकर्णोऽत्र निहतः प्रहस्तश्च निशाचरः॥', 'tavahetor viśālākṣi rāvaṇo nihato mayā
kumbhakarṇo ''tra nihataḥ prahastaś ca niśācaraḥ', null, 6111005),
('ramayana-6-111-6', 6, 'Yuddha Kanda, Sarga 111, Verse 6', 'लक्ष्मणेनेन्द्रजिच्चात्र रावणिर्निहतो रणे।
विरूपाक्षश्च दुष्प्रेक्ष्यो महापार्श्वमहोदरौ॥', 'lakṣmaṇenendrajic cātra rāvaṇir nihato raṇe
virūpākṣaś ca duṣprekṣyo mahāpārśvamahodarau', null, 6111006),
('ramayana-6-111-7', 7, 'Yuddha Kanda, Sarga 111, Verse 7', 'अकम्पनश्च निहतो बलिनोऽन्ये च राक्षसाः।
त्रिशिराश्चातिकायश्च देवान्तकनरान्तकौ॥', 'akampanaś ca nihato balino ''nye ca rākṣasāḥ
triśirāś cātikāyaś ca devāntakanarāntakau', null, 6111007),
('ramayana-6-111-8', 8, 'Yuddha Kanda, Sarga 111, Verse 8', 'अत्र मन्दोदरी नाम भार्या तं पर्यदेवयत्।
सपत्नीनां सहस्रेण सास्रेण परिवारिता॥', 'atra mandodarī nāma bhāryā taṃ paryadevayat
sapatnīnāṃ sahasreṇa sāsreṇa parivāritā', null, 6111008),
('ramayana-6-111-9', 9, 'Yuddha Kanda, Sarga 111, Verse 9', 'एतत्तु दृश्यते तीर्थं समुद्रस्य वरानने।
यत्र सागरमुत्तीर्य तां रात्रिमुषिता वयम्॥', 'etat tu dṛśyate tīrthaṃ samudrasya varānane
yatra sāgaram uttīrya tāṃ rātrim uṣitā vayam', null, 6111009),
('ramayana-6-111-10', 10, 'Yuddha Kanda, Sarga 111, Verse 10', 'एष सेतुर्मया बद्धः सागरे सलिलार्णवे।
तवहेतोर्विशालाक्षि नलसेतुः सुदुष्करः॥', 'eṣa setur mayā baddhaḥ sāgare salilārṇave
tavahetor viśālākṣi nalasetuḥ suduṣkaraḥ', null, 6111010),
('ramayana-6-111-11', 11, 'Yuddha Kanda, Sarga 111, Verse 11', 'पश्य सागरमक्षोभ्यं वैदेहि वरुणालयम्।
अपारमभिगर्जन्तं शङ्खशुक्तिनिषेवितम्॥', 'paśya sāgaram akṣobhyaṃ vaidehi varuṇālayam
apāram abhigarjantaṃ śaṅkhaśuktiniṣevitam', null, 6111011),
('ramayana-6-111-12', 12, 'Yuddha Kanda, Sarga 111, Verse 12', 'हिरण्यनाभं शैलेन्द्रं काञ्चनं पश्य मैथिलि।
विश्रमार्थं हनुमतो भित्त्वा सागरमुत्थितम्॥', 'hiraṇyanābhaṃ śailendraṃ kāñcanaṃ paśya maithili
viśramārthaṃ hanumato bhittvā sāgaram utthitam', null, 6111012),
('ramayana-6-111-13', 13, 'Yuddha Kanda, Sarga 111, Verse 13', 'अत्र राक्षसराजोऽयमाजगाम विभीषणः॥', 'atra rākṣasarājo ''yam ājagāma vibhīṣaṇaḥ', null, 6111013),
('ramayana-6-111-14', 14, 'Yuddha Kanda, Sarga 111, Verse 14', 'एषा सा दृश्यते सीते किष्किन्धा चित्रकानना।
सुग्रीवस्य पुरी रम्या यत्र वाली मया हतः॥', 'eṣā sā dṛśyate sīte kiṣkindhā citrakānanā
sugrīvasya purī ramyā yatra vālī mayā hataḥ', null, 6111014),
('ramayana-6-111-15', 15, 'Yuddha Kanda, Sarga 111, Verse 15', 'दृश्यतेऽसौ महान्सीते सविद्युदिव तोयदः।
ऋश्यमूको गिरिश्रेष्ठः काञ्चनैर्धातुभिर्वृतः॥', 'dṛśyate ''sau mahān sīte savidyud iva toyadaḥ
ṛśyamūko giriśreṣṭhaḥ kāñcanair dhātubhir vṛtaḥ', null, 6111015),
('ramayana-6-111-16', 16, 'Yuddha Kanda, Sarga 111, Verse 16', 'अत्राहं वानरेन्द्रेण सुग्रीवेण समागतः।
समयश्च कृतः सीते वधार्थं वालिनो मया॥', 'atrāhaṃ vānarendreṇa sugrīveṇa samāgataḥ
samayaś ca kṛtaḥ sīte vadhārthaṃ vālino mayā', null, 6111016),
('ramayana-6-111-17', 17, 'Yuddha Kanda, Sarga 111, Verse 17', 'एषा सा दृश्यते पम्पा नलिनी चित्रकानना।
त्वया विहीनो यत्राहं विललाप सुदुःखितः॥', 'eṣā sā dṛśyate pampā nalinī citrakānanā
tvayā vihīno yatrāhaṃ vilalāpa suduḥkhitaḥ', null, 6111017),
('ramayana-6-111-18', 18, 'Yuddha Kanda, Sarga 111, Verse 18', 'अस्यास्तीरे मया दृष्टा शबरी धर्मचारिणी।
अत्र योजनबाहुश्च कबन्धो निहतो मया॥', 'asyās tīre mayā dṛṣṭā śabarī dharmacāriṇī
atra yojanabāhuś ca kabandho nihato mayā', null, 6111018),
('ramayana-6-111-19', 19, 'Yuddha Kanda, Sarga 111, Verse 19', 'दृश्यतेऽसौ जनस्थाने सीते श्रीमान्वनस्पतिः।
यत्र युद्धं महद्वृत्तं तवहेतोर्विलासिनि।
रावणस्य नृशंसस्य जटायोश्च महात्मनः॥', 'dṛśyate ''sau janasthāne sīte śrīmān vanaspatiḥ
yatra yuddhaṃ mahad vṛttaṃ tavahetor vilāsini
rāvaṇasya nṛśaṃsasya jaṭāyoś ca mahātmanaḥ', null, 6111019),
('ramayana-6-111-20', 20, 'Yuddha Kanda, Sarga 111, Verse 20', 'खरश्च निहतश्संख्ये दूषणश्च निपातितः।
त्रिशिराश्च महावीर्यो मया बाणैरजिह्मगैः॥', 'kharaś ca nihataś saṃkhye dūṣaṇaś ca nipātitaḥ
triśirāś ca mahāvīryo mayā bāṇair ajihmagaiḥ', null, 6111020),
('ramayana-6-111-21', 21, 'Yuddha Kanda, Sarga 111, Verse 21', 'पर्णशाला तथा चित्रा दृश्यते शुभदर्शना।
यत्र त्वं राक्षसेन्द्रेण रावणेन हृता बलात्॥', 'parṇaśālā tathā citrā dṛśyate śubhadarśanā
yatra tvaṃ rākṣasendreṇa rāvaṇena hṛtā balāt', null, 6111021),
('ramayana-6-111-22', 22, 'Yuddha Kanda, Sarga 111, Verse 22', 'एषा गोदावरी रम्या प्रसन्नसलिला शिवा।
अगस्त्यस्याश्रमो ह्येष दृश्यते पश्य मैथिलि॥', 'eṣā godāvarī ramyā prasannasalilā śivā
agastyasyāśramo hy eṣa dṛśyate paśya maithili', null, 6111022),
('ramayana-6-111-23', 23, 'Yuddha Kanda, Sarga 111, Verse 23', 'वैदेहि दृश्यते चात्र शरभङ्गाश्रमो महान्।
उपयातः सहस्राक्षो यत्र शक्रः पुरंदरः॥', 'vaidehi dṛśyate cātra śarabhaṅgāśramo mahān
upayātaḥ sahasrākṣo yatra śakraḥ puraṃdaraḥ', null, 6111023),
('ramayana-6-111-24', 24, 'Yuddha Kanda, Sarga 111, Verse 24', 'एते ते तापसावासा दृश्यन्ते तनुमध्यमे।
अत्रिः कुलपतिर्यत्र सूर्यवैश्वानरप्रभः।
अत्र सीते त्वया दृष्टा तापसी धर्मचारिणी॥', 'ete te tāpasāvāsā dṛśyante tanumadhyame
atriḥ kulapatir yatra sūryavaiśvānaraprabhaḥ
atra sīte tvayā dṛṣṭā tāpasī dharmacāriṇī', null, 6111024),
('ramayana-6-111-25', 25, 'Yuddha Kanda, Sarga 111, Verse 25', 'अस्मिन्देशे महाकायो विराधो निहतो मया॥', 'asmin deśe mahākāyo virādho nihato mayā', null, 6111025),
('ramayana-6-111-26', 26, 'Yuddha Kanda, Sarga 111, Verse 26', 'असौ सुतनुशैलेन्द्रश्चित्रकूटः प्रकाशते।
यत्र मां कैकयीपुत्रः प्रसादयितुमागतः॥', 'asau sutanuśailendraś citrakūṭaḥ prakāśate
yatra māṃ kaikayīputraḥ prasādayitum āgataḥ', null, 6111026),
('ramayana-6-111-27', 27, 'Yuddha Kanda, Sarga 111, Verse 27', 'एषा सा यमुना दूराद्दृश्यते चित्रकानना।
भरद्वाजाश्रमो यत्र श्रीमानेष प्रकाशते॥', 'eṣā sā yamunā dūrād dṛśyate citrakānanā
bharadvājāśramo yatra śrīmān eṣa prakāśate', null, 6111027),
('ramayana-6-111-28', 28, 'Yuddha Kanda, Sarga 111, Verse 28', 'एषा त्रिपथगा गङ्गा दृश्यते वरवर्णिनि।
शृङ्गवेरपुरं चैतद्गुहो यत्र समागतः॥', 'eṣā tripathagā gaṅgā dṛśyate varavarṇini
śṛṅgaverapuraṃ caitad guho yatra samāgataḥ', null, 6111028),
('ramayana-6-111-29', 29, 'Yuddha Kanda, Sarga 111, Verse 29', 'एषा सा दृश्यतेऽयोध्या राजधानी पितुर्मम।
अयोध्यां कुरु वैदेहि प्रणामं पुनरागता॥', 'eṣā sā dṛśyate ''yodhyā rājadhānī pitur mama
ayodhyāṃ kuru vaidehi praṇāmaṃ punar āgatā', null, 6111029),
('ramayana-6-111-30', 30, 'Yuddha Kanda, Sarga 111, Verse 30', 'ततस्ते वानराः सर्वे राक्षसश्च विभीषणः।
उत्पत्योत्पत्य ददृशुस्तां पुरीं शुभदर्शनाम्॥', 'tatas te vānarāḥ sarve rākṣasaś ca vibhīṣaṇaḥ
utpatyotpatya dadṛśus tāṃ purīṃ śubhadarśanām', null, 6111030),
('ramayana-6-111-31', 31, 'Yuddha Kanda, Sarga 111, Verse 31', 'ततस्तु तां पाण्डुरहर्म्यमालिनीं विशालकक्ष्यां गजवाजिसंकुलाम्।
पुरीमयोध्यां ददृशुः प्लवंगमाः पुरीं महेन्द्रस्य यथामरावतीम्॥', 'tatas tu tāṃ pāṇḍuraharmyamālinīṃ viśālakakṣyāṃ gajavājisaṃkulām
purīm ayodhyāṃ dadṛśuḥ plavaṃgamāḥ purīṃ mahendrasya yathāmarāvatīm', null, 6111031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 112 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-112-1', 1, 'Yuddha Kanda, Sarga 112, Verse 1', 'पूर्णे चतुर्दशे वर्षे पञ्चभ्यां लक्ष्मणाग्रजः।
भरद्वाजाश्रमं प्राप्य ववन्दे नियतो मुनिम्॥', 'pūrṇe caturdaśe varṣe pañcabhyāṃ lakṣmaṇāgrajaḥ
bharadvājāśramaṃ prāpya vavande niyato munim', null, 6112001),
('ramayana-6-112-2', 2, 'Yuddha Kanda, Sarga 112, Verse 2', 'सोऽपृच्छदभिवाद्यैनं भरद्वाजं तपोधनम्।
शृणोषि क चिद्भगवन्सुभिक्षानामयं पुरे।
कच्चिच्च युक्तो भरतो जीवन्त्यपि च मातरः॥', 'so ''pṛcchad abhivādyainaṃ bharadvājaṃ tapodhanam
śṛṇoṣi ka cid bhagavan subhikṣānāmayaṃ pure
kaccic ca yukto bharato jīvanty api ca mātaraḥ', null, 6112002),
('ramayana-6-112-3', 3, 'Yuddha Kanda, Sarga 112, Verse 3', 'एवमुक्तस्तु रामेण भरद्वाजो महामुनिः।
प्रत्युवाच रघुश्रेष्ठं स्मितपूर्वं प्रहृष्टवत्॥', 'evam uktas tu rāmeṇa bharadvājo mahāmuniḥ
pratyuvāca raghuśreṣṭhaṃ smitapūrvaṃ prahṛṣṭavat', null, 6112003),
('ramayana-6-112-4', 4, 'Yuddha Kanda, Sarga 112, Verse 4', 'पङ्कदिग्धस्तु भरतो जटिलस्त्वां प्रतीक्षते।
पादुके ते पुरस्कृत्य सर्वं च कुशलं गृहे॥', 'paṅkadigdhas tu bharato jaṭilas tvāṃ pratīkṣate
pāduke te puraskṛtya sarvaṃ ca kuśalaṃ gṛhe', null, 6112004),
('ramayana-6-112-5', 5, 'Yuddha Kanda, Sarga 112, Verse 5', 'त्वां पुरा चीरवसनं प्रविशन्तं महावनम्।
स्त्रीतृतीयं च्युतं राज्याद्धर्मकामं च केवलम्॥', 'tvāṃ purā cīravasanaṃ praviśantaṃ mahāvanam
strītṛtīyaṃ cyutaṃ rājyād dharmakāmaṃ ca kevalam', null, 6112005),
('ramayana-6-112-6', 6, 'Yuddha Kanda, Sarga 112, Verse 6', 'पदातिं त्यक्तसर्वस्वं पितुर्वचनकारिणम्।
स्वर्गभोगैः परित्यक्तं स्वर्गच्युतमिवामरम्॥', 'padātiṃ tyaktasarvasvaṃ pitur vacanakāriṇam
svargabhogaiḥ parityaktaṃ svargacyutam ivāmaram', null, 6112006),
('ramayana-6-112-7', 7, 'Yuddha Kanda, Sarga 112, Verse 7', 'दृष्ट्वा तु करुणा पूर्वं ममासीत्समितिंजय।
कैकेयीवचने युक्तं वन्यमूलफलाशनम्॥', 'dṛṣṭvā tu karuṇā pūrvaṃ mamāsīt samitiṃjaya
kaikeyīvacane yuktaṃ vanyamūlaphalāśanam', null, 6112007),
('ramayana-6-112-8', 8, 'Yuddha Kanda, Sarga 112, Verse 8', 'साम्प्रतं सुसमृद्धार्थं समित्रगणबान्धवम्।
समीक्ष्य विजितारिं त्वां मम प्रीतिरनुत्तमा॥', 'sāmprataṃ susamṛddhārthaṃ samitragaṇabāndhavam
samīkṣya vijitāriṃ tvāṃ mama prītir anuttamā', null, 6112008),
('ramayana-6-112-9', 9, 'Yuddha Kanda, Sarga 112, Verse 9', 'सर्वं च सुखदुःखं ते विदितं मम राघव।
यत्त्वया विपुलं प्राप्तं जनस्थानवधादिकम्॥', 'sarvaṃ ca sukhaduḥkhaṃ te viditaṃ mama rāghava
yat tvayā vipulaṃ prāptaṃ janasthānavadhādikam', null, 6112009),
('ramayana-6-112-10', 10, 'Yuddha Kanda, Sarga 112, Verse 10', 'ब्राह्मणार्थे नियुक्तस्य रक्षतः सर्वतापसान्।
मारीचदर्शनं चैव सीतोन्मथनमेव च॥', 'brāhmaṇārthe niyuktasya rakṣataḥ sarvatāpasān
mārīcadarśanaṃ caiva sītonmathanam eva ca', null, 6112010),
('ramayana-6-112-11', 11, 'Yuddha Kanda, Sarga 112, Verse 11', 'कबन्धदर्शनं चैव पम्पाभिगमनं तथा।
सुग्रीवेण च ते सख्यं यच्च वाली हतस्त्वया॥', 'kabandhadarśanaṃ caiva pampābhigamanaṃ tathā
sugrīveṇa ca te sakhyaṃ yac ca vālī hatas tvayā', null, 6112011),
('ramayana-6-112-12', 12, 'Yuddha Kanda, Sarga 112, Verse 12', 'मार्गणं चैव वैदेह्याः कर्म वातात्मजस्य च।
विदितायां च वैदेह्यां नलसेतुर्यथा कृतः।
यथा च दीपिता लङ्का प्रहृष्टैर्हरियूथपैः॥', 'mārgaṇaṃ caiva vaidehyāḥ karma vātātmajasya ca
viditāyāṃ ca vaidehyāṃ nalasetur yathā kṛtaḥ
yathā ca dīpitā laṅkā prahṛṣṭair hariyūthapaiḥ', null, 6112012),
('ramayana-6-112-13', 13, 'Yuddha Kanda, Sarga 112, Verse 13', 'सपुत्रबान्धवामात्यः सबलः सह वाहनः।
यथा च निहतः संख्ये रावणो देवकण्टकः॥', 'saputrabāndhavāmātyaḥ sabalaḥ saha vāhanaḥ
yathā ca nihataḥ saṃkhye rāvaṇo devakaṇṭakaḥ', null, 6112013),
('ramayana-6-112-14', 14, 'Yuddha Kanda, Sarga 112, Verse 14', 'समागमश्च त्रिदशैर्यथादत्तश्च ते वरः।
सर्वं ममैतद्विदितं तपसा धर्मवत्सल॥', 'samāgamaś ca tridaśair yathādattaś ca te varaḥ
sarvaṃ mamaitad viditaṃ tapasā dharmavatsala', null, 6112014),
('ramayana-6-112-15', 15, 'Yuddha Kanda, Sarga 112, Verse 15', 'अहमप्यत्र ते दद्मि वरं शस्त्रभृतां वर।
अर्घ्यं प्रतिगृहाणेदमयोध्यां श्वो गमिष्यसि॥', 'aham apy atra te dadmi varaṃ śastrabhṛtāṃ vara
arghyaṃ pratigṛhāṇedam ayodhyāṃ śvo gamiṣyasi', null, 6112015),
('ramayana-6-112-16', 16, 'Yuddha Kanda, Sarga 112, Verse 16', 'तस्य तच्छिरसा वाक्यं प्रतिगृह्य नृपात्मजः।
बाढमित्येव संहृष्टः श्रीमान्वरमयाचत॥', 'tasya tac chirasā vākyaṃ pratigṛhya nṛpātmajaḥ
bāḍham ity eva saṃhṛṣṭaḥ śrīmān varam ayācata', null, 6112016),
('ramayana-6-112-17', 17, 'Yuddha Kanda, Sarga 112, Verse 17', 'अकालफलिनो वृक्षाः सर्वे चापि मधुस्रवाः।
भवन्तु मार्गे भगवन्नयोध्यां प्रति गच्छतः॥', 'akālaphalino vṛkṣāḥ sarve cāpi madhusravāḥ
bhavantu mārge bhagavann ayodhyāṃ prati gacchataḥ', null, 6112017),
('ramayana-6-112-18', 18, 'Yuddha Kanda, Sarga 112, Verse 18', 'निष्फलाः फलिनश्चासन्विपुष्पाः पुष्पशालिनः।
शुष्काः समग्रपत्रास्ते नगाश्चैव मधुस्रवाः॥', 'niṣphalāḥ phalinaś cāsan vipuṣpāḥ puṣpaśālinaḥ
śuṣkāḥ samagrapatrās te nagāś caiva madhusravāḥ', null, 6112018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 113 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-113-1', 1, 'Yuddha Kanda, Sarga 113, Verse 1', 'अयोध्यां तु समालोक्य चिन्तयामास राघवः।
चिन्तयित्वा ततो दृष्टिं वानरेषु न्यपातयत्॥', 'ayodhyāṃ tu samālokya cintayām āsa rāghavaḥ
cintayitvā tato dṛṣṭiṃ vānareṣu nyapātayat', null, 6113001),
('ramayana-6-113-2', 2, 'Yuddha Kanda, Sarga 113, Verse 2', 'प्रियकामः प्रियं रामस्ततस्त्वरितविक्रमम्।
उवाच धीमांस्तेजस्वी हनूमन्तं प्लवंगमम्॥', 'priyakāmaḥ priyaṃ rāmas tatas tvaritavikramam
uvāca dhīmāṃs tejasvī hanūmantaṃ plavaṃgamam', null, 6113002),
('ramayana-6-113-3', 3, 'Yuddha Kanda, Sarga 113, Verse 3', 'अयोध्यां त्वरितो गच्छ क्षिप्रं त्वं प्लवगोत्तम।
जानीहि कच्चित्कुशली जनो नृपतिमन्दिरे॥', 'ayodhyāṃ tvarito gaccha kṣipraṃ tvaṃ plavagottama
jānīhi kaccit kuśalī jano nṛpatimandire', null, 6113003),
('ramayana-6-113-4', 4, 'Yuddha Kanda, Sarga 113, Verse 4', 'शृङ्गवेरपुरं प्राप्य गुहं गहनगोचरम्।
निषादाधिपतिं ब्रूहि कुशलं वचनान्मम॥', 'śṛṅgaverapuraṃ prāpya guhaṃ gahanagocaram
niṣādādhipatiṃ brūhi kuśalaṃ vacanān mama', null, 6113004),
('ramayana-6-113-5', 5, 'Yuddha Kanda, Sarga 113, Verse 5', 'श्रुत्वा तु मां कुशलिनमरोगं विगतज्वरम्।
भविष्यति गुहः प्रीतः स ममात्मसमः सखा॥', 'śrutvā tu māṃ kuśalinam arogaṃ vigatajvaram
bhaviṣyati guhaḥ prītaḥ sa mamātmasamaḥ sakhā', null, 6113005),
('ramayana-6-113-6', 6, 'Yuddha Kanda, Sarga 113, Verse 6', 'अयोध्यायाश्च ते मार्गं प्रवृत्तिं भरतस्य च।
निवेदयिष्यति प्रीतो निषादाधिपतिर्गुहः॥', 'ayodhyāyāś ca te mārgaṃ pravṛttiṃ bharatasya ca
nivedayiṣyati prīto niṣādādhipatir guhaḥ', null, 6113006),
('ramayana-6-113-7', 7, 'Yuddha Kanda, Sarga 113, Verse 7', 'भरतस्तु त्वया वाच्यः कुशलं वचनान्मम।
सिद्धार्थं शंस मां तस्मै सभार्यं सहलक्ष्मणम्॥', 'bharatas tu tvayā vācyaḥ kuśalaṃ vacanān mama
siddhārthaṃ śaṃsa māṃ tasmai sabhāryaṃ sahalakṣmaṇam', null, 6113007),
('ramayana-6-113-8', 8, 'Yuddha Kanda, Sarga 113, Verse 8', 'हरणं चापि वैदेह्या रावणेन बलीयसा।
सुग्रीवेण च संवादं वालिनश्च वधं रणे॥', 'haraṇaṃ cāpi vaidehyā rāvaṇena balīyasā
sugrīveṇa ca saṃvādaṃ vālinaś ca vadhaṃ raṇe', null, 6113008),
('ramayana-6-113-9', 9, 'Yuddha Kanda, Sarga 113, Verse 9', 'मैथिल्यन्वेषणं चैव यथा चाधिगता त्वया।
लङ्घयित्वा महातोयमापगापतिमव्ययम्॥', 'maithilyanveṣaṇaṃ caiva yathā cādhigatā tvayā
laṅghayitvā mahātoyam āpagāpatim avyayam', null, 6113009),
('ramayana-6-113-10', 10, 'Yuddha Kanda, Sarga 113, Verse 10', 'उपयानं समुद्रस्य सागरस्य च दर्शनम्।
यथा च कारितः सेतू रावणश्च यथा हतः॥', 'upayānaṃ samudrasya sāgarasya ca darśanam
yathā ca kāritaḥ setū rāvaṇaś ca yathā hataḥ', null, 6113010),
('ramayana-6-113-11', 11, 'Yuddha Kanda, Sarga 113, Verse 11', 'वरदानं महेन्द्रेण ब्रह्मणा वरुणेन च।
महादेवप्रसादाच्च पित्रा मम समागमम्॥', 'varadānaṃ mahendreṇa brahmaṇā varuṇena ca
mahādevaprasādāc ca pitrā mama samāgamam', null, 6113011),
('ramayana-6-113-12', 12, 'Yuddha Kanda, Sarga 113, Verse 12', 'जित्वा शत्रुगणान्रामः प्राप्य चानुत्तमं यशः।
उपयाति समृद्धार्थः सह मित्रैर्महाबलः॥', 'jitvā śatrugaṇān rāmaḥ prāpya cānuttamaṃ yaśaḥ
upayāti samṛddhārthaḥ saha mitrair mahābalaḥ', null, 6113012),
('ramayana-6-113-13', 13, 'Yuddha Kanda, Sarga 113, Verse 13', 'एतच्छ्रुत्वा यमाकारं भजते भरतस्ततः।
स च ते वेदितव्यः स्यात्सर्वं यच्चापि मां प्रति॥', 'etac chrutvā yamākāraṃ bhajate bharatas tataḥ
sa ca te veditavyaḥ syāt sarvaṃ yac cāpi māṃ prati', null, 6113013),
('ramayana-6-113-14', 14, 'Yuddha Kanda, Sarga 113, Verse 14', 'ज्ञेयाः सर्वे च वृत्तान्ता भरतस्येङ्गितानि च।
तत्त्वेन मुखवर्णेन दृष्ट्या व्याभाषणेन च॥', 'jñeyāḥ sarve ca vṛttāntā bharatasyeṅgitāni ca
tattvena mukhavarṇena dṛṣṭyā vyābhāṣaṇena ca', null, 6113014),
('ramayana-6-113-15', 15, 'Yuddha Kanda, Sarga 113, Verse 15', 'सर्वकामसमृद्धं हि हस्त्यश्वरथसंकुलम्।
पितृपैतामहं राज्यं कस्य नावर्तयेन्मनः॥', 'sarvakāmasamṛddhaṃ hi hastyaśvarathasaṃkulam
pitṛpaitāmahaṃ rājyaṃ kasya nāvartayen manaḥ', null, 6113015),
('ramayana-6-113-16', 16, 'Yuddha Kanda, Sarga 113, Verse 16', 'संगत्या भरतः श्रीमान्राज्येनार्थी स्वयं भवेत्।
प्रशास्तु वसुधां सर्वामखिलां रघुनन्दनः॥', 'saṃgatyā bharataḥ śrīmān rājyenārthī svayaṃ bhavet
praśāstu vasudhāṃ sarvām akhilāṃ raghunandanaḥ', null, 6113016),
('ramayana-6-113-17', 17, 'Yuddha Kanda, Sarga 113, Verse 17', 'तस्य बुद्धिं च विज्ञाय व्यवसायं च वानर।
यावन्न दूरं याताः स्मः क्षिप्रमागन्तुमर्हसि॥', 'tasya buddhiṃ ca vijñāya vyavasāyaṃ ca vānara
yāvan na dūraṃ yātāḥ smaḥ kṣipram āgantum arhasi', null, 6113017),
('ramayana-6-113-18', 18, 'Yuddha Kanda, Sarga 113, Verse 18', 'इति प्रतिसमादिष्टो हनूमान्मारुतात्मजः।
मानुषं धारयन्रूपमयोध्यां त्वरितो ययौ॥', 'iti pratisamādiṣṭo hanūmān mārutātmajaḥ
mānuṣaṃ dhārayan rūpam ayodhyāṃ tvarito yayau', null, 6113018),
('ramayana-6-113-19', 19, 'Yuddha Kanda, Sarga 113, Verse 19', 'लङ्घयित्वा पितृपथं भुजगेन्द्रालयं शुभम्।
गङ्गायमुनयोर्भीमं संनिपातमतीत्य च॥', 'laṅghayitvā pitṛpathaṃ bhujagendrālayaṃ śubham
gaṅgāyamunayor bhīmaṃ saṃnipātam atītya ca', null, 6113019),
('ramayana-6-113-20', 20, 'Yuddha Kanda, Sarga 113, Verse 20', 'शृङ्गवेरपुरं प्राप्य गुहमासाद्य वीर्यवान्।
स वाचा शुभया हृष्टो हनूमानिदमब्रवीत्॥', 'śṛṅgaverapuraṃ prāpya guham āsādya vīryavān
sa vācā śubhayā hṛṣṭo hanūmān idam abravīt', null, 6113020),
('ramayana-6-113-21', 21, 'Yuddha Kanda, Sarga 113, Verse 21', 'सखा तु तव काकुत्स्थो रामः सत्यपराक्रमः।
ससीतः सह सौमित्रिः स त्वां कुशलमब्रवीत्॥', 'sakhā tu tava kākutstho rāmaḥ satyaparākramaḥ
sasītaḥ saha saumitriḥ sa tvāṃ kuśalam abravīt', null, 6113021),
('ramayana-6-113-22', 22, 'Yuddha Kanda, Sarga 113, Verse 22', 'पञ्चमीमद्य रजनीमुषित्वा वचनान्मुनेः।
भरद्वाजाभ्यनुज्ञातं द्रक्ष्यस्यद्यैव राघवम्॥', 'pañcamīm adya rajanīm uṣitvā vacanān muneḥ
bharadvājābhyanujñātaṃ drakṣyasy adyaiva rāghavam', null, 6113022),
('ramayana-6-113-23', 23, 'Yuddha Kanda, Sarga 113, Verse 23', 'एवमुक्त्वा महातेजाः संप्रहृष्टतनूरुहः।
उत्पपात महावेगो वेगवानविचारयन्॥', 'evam uktvā mahātejāḥ saṃprahṛṣṭatanūruhaḥ
utpapāta mahāvego vegavān avicārayan', null, 6113023),
('ramayana-6-113-24', 24, 'Yuddha Kanda, Sarga 113, Verse 24', 'सोऽपश्यद्रामतीर्थं च नदीं वालुकिनीं तथा।
गोमतीं तां च सोऽपश्यद्भीमं सालवनं तथा॥', 'so ''paśyad rāmatīrthaṃ ca nadīṃ vālukinīṃ tathā
gomatīṃ tāṃ ca so ''paśyad bhīmaṃ sālavanaṃ tathā', null, 6113024),
('ramayana-6-113-25', 25, 'Yuddha Kanda, Sarga 113, Verse 25', 'स गत्वा दूरमध्वानं त्वरितः कपिकुञ्जरः।
आससाद द्रुमान्फुल्लान्नन्दिग्रामसमीपजान्॥', 'sa gatvā dūram adhvānaṃ tvaritaḥ kapikuñjaraḥ
āsasāda drumān phullān nandigrāmasamīpajān', null, 6113025),
('ramayana-6-113-26', 26, 'Yuddha Kanda, Sarga 113, Verse 26', 'क्रोशमात्रे त्वयोध्यायाश्चीरकृष्णाजिनाम्बरम्।
ददर्श भरतं दीनं कृशमाश्रमवासिनम्॥', 'krośamātre tv ayodhyāyāś cīrakṛṣṇājināmbaram
dadarśa bharataṃ dīnaṃ kṛśam āśramavāsinam', null, 6113026),
('ramayana-6-113-27', 27, 'Yuddha Kanda, Sarga 113, Verse 27', 'जटिलं मलदिग्धाङ्गं भ्रातृव्यसनकर्शितम्।
फलमूलाशिनं दान्तं तापसं धर्मचारिणम्॥', 'jaṭilaṃ maladigdhāṅgaṃ bhrātṛvyasanakarśitam
phalamūlāśinaṃ dāntaṃ tāpasaṃ dharmacāriṇam', null, 6113027),
('ramayana-6-113-28', 28, 'Yuddha Kanda, Sarga 113, Verse 28', 'समुन्नतजटाभारं वल्कलाजिनवाससं।
नियतं भावितात्मानं ब्रह्मर्षिसमतेजसं॥', 'samunnatajaṭābhāraṃ valkalājinavāsasaṃ
niyataṃ bhāvitātmānaṃ brahmarṣisamatejasaṃ', null, 6113028),
('ramayana-6-113-29', 29, 'Yuddha Kanda, Sarga 113, Verse 29', 'पादुके ते पुरस्कृत्य शासन्तं वै वसुंधराम्।
चतुर्वर्ण्यस्य लोकस्य त्रातारं सर्वतो भयात्॥', 'pāduke te puraskṛtya śāsantaṃ vai vasuṃdharām
caturvarṇyasya lokasya trātāraṃ sarvato bhayāt', null, 6113029),
('ramayana-6-113-30', 30, 'Yuddha Kanda, Sarga 113, Verse 30', 'उपस्थितममात्यैश्च शुचिभिश्च पुरोहितैः।
बलमुख्यैश्च युक्तैश्च काषायाम्बरधारिभिः॥', 'upasthitam amātyaiś ca śucibhiś ca purohitaiḥ
balamukhyaiś ca yuktaiś ca kāṣāyāmbaradhāribhiḥ', null, 6113030),
('ramayana-6-113-31', 31, 'Yuddha Kanda, Sarga 113, Verse 31', 'न हि ते राजपुत्रं तं चीरकृष्णाजिनाम्बरम्।
परिमोक्तुं व्यवस्यन्ति पौरा वै धर्मवत्सलाः॥', 'na hi te rājaputraṃ taṃ cīrakṛṣṇājināmbaram
parimoktuṃ vyavasyanti paurā vai dharmavatsalāḥ', null, 6113031),
('ramayana-6-113-32', 32, 'Yuddha Kanda, Sarga 113, Verse 32', 'तं धर्ममिव धर्मज्ञं देववन्तमिवापरम्।
उवाच प्राञ्जलिर्वाक्यं हनूमान्मारुतात्मजः॥', 'taṃ dharmam iva dharmajñaṃ devavantam ivāparam
uvāca prāñjalir vākyaṃ hanūmān mārutātmajaḥ', null, 6113032),
('ramayana-6-113-33', 33, 'Yuddha Kanda, Sarga 113, Verse 33', 'वसन्तं दण्डकारण्ये यं त्वं चीरजटाधरम्।
अनुशोचसि काकुत्स्थं स त्वा कुशलमब्रवीत्॥', 'vasantaṃ daṇḍakāraṇye yaṃ tvaṃ cīrajaṭādharam
anuśocasi kākutsthaṃ sa tvā kuśalam abravīt', null, 6113033),
('ramayana-6-113-34', 34, 'Yuddha Kanda, Sarga 113, Verse 34', 'प्रियमाख्यामि ते देव शोकं त्यक्ष्यसि दारुणम्।
अस्मिन्मुहूर्ते भ्रात्रा त्वं रामेण सह संगतः॥', 'priyam ākhyāmi te deva śokaṃ tyakṣyasi dāruṇam
asmin muhūrte bhrātrā tvaṃ rāmeṇa saha saṃgataḥ', null, 6113034),
('ramayana-6-113-35', 35, 'Yuddha Kanda, Sarga 113, Verse 35', 'निहत्य रावणं रामः प्रतिलभ्य च मैथिलीम्।
उपयाति समृद्धार्थः सह मित्रैर्महाबलैः॥', 'nihatya rāvaṇaṃ rāmaḥ pratilabhya ca maithilīm
upayāti samṛddhārthaḥ saha mitrair mahābalaiḥ', null, 6113035),
('ramayana-6-113-36', 36, 'Yuddha Kanda, Sarga 113, Verse 36', 'लक्ष्मणश्च महातेजा वैदेही च यशस्विनी।
सीता समग्रा रामेण महेन्द्रेण शची यथा॥', 'lakṣmaṇaś ca mahātejā vaidehī ca yaśasvinī
sītā samagrā rāmeṇa mahendreṇa śacī yathā', null, 6113036),
('ramayana-6-113-37', 37, 'Yuddha Kanda, Sarga 113, Verse 37', 'एवमुक्तो हनुमता भरतः कैकयीसुतः।
पपात सहसा हृष्टो हर्षान्मोहं जगाम ह॥', 'evam ukto hanumatā bharataḥ kaikayīsutaḥ
papāta sahasā hṛṣṭo harṣān mohaṃ jagāma ha', null, 6113037),
('ramayana-6-113-38', 38, 'Yuddha Kanda, Sarga 113, Verse 38', 'ततो मुहूर्तादुत्थाय प्रत्याश्वस्य च राघवः।
हनूमन्तमुवाचेदं भरतः प्रियवादिनम्॥', 'tato muhūrtād utthāya pratyāśvasya ca rāghavaḥ
hanūmantam uvācedaṃ bharataḥ priyavādinam', null, 6113038),
('ramayana-6-113-39', 39, 'Yuddha Kanda, Sarga 113, Verse 39', 'अशोकजैः प्रीतिमयैः कपिमालिङ्ग्य संभ्रमात्।
सिषेच भरतः श्रीमान्विपुलैरश्रुबिन्दुभिः॥', 'aśokajaiḥ prītimayaiḥ kapim āliṅgya saṃbhramāt
siṣeca bharataḥ śrīmān vipulair aśrubindubhiḥ', null, 6113039),
('ramayana-6-113-40', 40, 'Yuddha Kanda, Sarga 113, Verse 40', 'देवो वा मानुषो वा त्वमनुक्रोशादिहागतः।
प्रियाख्यानस्य ते सौम्य ददामि ब्रुवतः प्रियम्॥', 'devo vā mānuṣo vā tvam anukrośād ihāgataḥ
priyākhyānasya te saumya dadāmi bruvataḥ priyam', null, 6113040),
('ramayana-6-113-41', 41, 'Yuddha Kanda, Sarga 113, Verse 41', 'गवां शतसहस्रं च ग्रामाणां च शतं परम्।
सकुण्डलाः शुभाचारा भार्याः कन्याश्च षोडश॥', 'gavāṃ śatasahasraṃ ca grāmāṇāṃ ca śataṃ param
sakuṇḍalāḥ śubhācārā bhāryāḥ kanyāś ca ṣoḍaśa', null, 6113041),
('ramayana-6-113-42', 42, 'Yuddha Kanda, Sarga 113, Verse 42', 'हेमवर्णाः सुनासोरूः शशिसौम्याननाः स्त्रियः।
सर्वाभरणसंपन्ना संपन्नाः कुलजातिभिः॥', 'hemavarṇāḥ sunāsorūḥ śaśisaumyānanāḥ striyaḥ
sarvābharaṇasaṃpannā saṃpannāḥ kulajātibhiḥ', null, 6113042),
('ramayana-6-113-43', 43, 'Yuddha Kanda, Sarga 113, Verse 43', 'निशम्य रामागमनं नृपात्मजः कपिप्रवीरस्य तदाद्भुतोपमम्।
प्रहर्षितो रामदिदृक्षयाभवत्पुनश्च हर्षादिदमब्रवीद्वचः॥', 'niśamya rāmāgamanaṃ nṛpātmajaḥ kapipravīrasya tadādbhutopamam
praharṣito rāmadidṛkṣayābhavat punaś ca harṣād idam abravīd vacaḥ', null, 6113043)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 114 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-114-1', 1, 'Yuddha Kanda, Sarga 114, Verse 1', 'बहूनि नाम वर्षाणि गतस्य सुमहद्वनम्।
शृणोम्यहं प्रीतिकरं मम नाथस्य कीर्तनम्॥', 'bahūni nāma varṣāṇi gatasya sumahad vanam
śṛṇomy ahaṃ prītikaraṃ mama nāthasya kīrtanam', null, 6114001),
('ramayana-6-114-2', 2, 'Yuddha Kanda, Sarga 114, Verse 2', 'कल्याणी बत गाथेयं लौकिकी प्रतिभाति मे।
एति जीवन्तमानन्दो नरं वर्षशतादपि॥', 'kalyāṇī bata gātheyaṃ laukikī pratibhāti me
eti jīvantam ānando naraṃ varṣaśatād api', null, 6114002),
('ramayana-6-114-3', 3, 'Yuddha Kanda, Sarga 114, Verse 3', 'राघवस्य हरीणां च कथमासीत्समागमः।
कस्मिन्देशे किमाश्रित्य तत्त्वमाख्याहि पृच्छतः॥', 'rāghavasya harīṇāṃ ca katham āsīt samāgamaḥ
kasmin deśe kim āśritya tat tvam ākhyāhi pṛcchataḥ', null, 6114003),
('ramayana-6-114-4', 4, 'Yuddha Kanda, Sarga 114, Verse 4', 'स पृष्टो राजपुत्रेण बृस्यां समुपवेशितः।
आचचक्षे ततः सर्वं रामस्य चरितं वने॥', 'sa pṛṣṭo rājaputreṇa bṛsyāṃ samupaveśitaḥ
ācacakṣe tataḥ sarvaṃ rāmasya caritaṃ vane', null, 6114004),
('ramayana-6-114-5', 5, 'Yuddha Kanda, Sarga 114, Verse 5', 'यथा प्रव्रजितो रामो मातुर्दत्ते वरे तव।
यथा च पुत्रशोकेन राजा दशरथो मृतः॥', 'yathā pravrajito rāmo mātur datte vare tava
yathā ca putraśokena rājā daśaratho mṛtaḥ', null, 6114005),
('ramayana-6-114-6', 6, 'Yuddha Kanda, Sarga 114, Verse 6', 'यथा दूतैस्त्वमानीतस्तूर्णं राजगृहात्प्रभो।
त्वयायोध्यां प्रविष्टेन यथा राज्यं न चेप्सितम्॥', 'yathā dūtais tvam ānītas tūrṇaṃ rājagṛhāt prabho
tvayāyodhyāṃ praviṣṭena yathā rājyaṃ na cepsitam', null, 6114006),
('ramayana-6-114-7', 7, 'Yuddha Kanda, Sarga 114, Verse 7', 'चित्रकूटं गिरिं गत्वा राज्येनामित्रकर्शनः।
निमन्त्रितस्त्वया भ्राता धर्ममाचरिता सताम्॥', 'citrakūṭaṃ giriṃ gatvā rājyenāmitrakarśanaḥ
nimantritas tvayā bhrātā dharmam ācaritā satām', null, 6114007),
('ramayana-6-114-8', 8, 'Yuddha Kanda, Sarga 114, Verse 8', 'स्थितेन राज्ञो वचने यथा राज्यं विसर्जितम्।
आर्यस्य पादुके गृह्य यथासि पुनरागतः॥', 'sthitena rājño vacane yathā rājyaṃ visarjitam
āryasya pāduke gṛhya yathāsi punar āgataḥ', null, 6114008),
('ramayana-6-114-9', 9, 'Yuddha Kanda, Sarga 114, Verse 9', 'सर्वमेतन्महाबाहो यथावद्विदितं तव।
त्वयि प्रतिप्रयाते तु यद्वृत्तं तन्निबोध मे॥', 'sarvam etan mahābāho yathāvad viditaṃ tava
tvayi pratiprayāte tu yad vṛttaṃ tan nibodha me', null, 6114009),
('ramayana-6-114-10', 10, 'Yuddha Kanda, Sarga 114, Verse 10', 'अपयाते त्वयि तदा समुद्भ्रान्तमृगद्विजम्।
प्रविवेशाथ विजनं सुमहद्दण्डकावनम्॥', 'apayāte tvayi tadā samudbhrāntamṛgadvijam
praviveśātha vijanaṃ sumahad daṇḍakāvanam', null, 6114010),
('ramayana-6-114-11', 11, 'Yuddha Kanda, Sarga 114, Verse 11', 'तेषां पुरस्ताद्बलवान्गच्छतां गहने वने।
विनदन्सुमहानादं विराधः प्रत्यदृश्यत॥', 'teṣāṃ purastād balavān gacchatāṃ gahane vane
vinadan sumahānādaṃ virādhaḥ pratyadṛśyata', null, 6114011),
('ramayana-6-114-12', 12, 'Yuddha Kanda, Sarga 114, Verse 12', 'तमुत्क्षिप्य महानादमूर्ध्वबाहुमधोमुखम्।
निखाते प्रक्षिपन्ति स्म नदन्तमिव कुञ्जरम्॥', 'tam utkṣipya mahānādam ūrdhvabāhum adhomukham
nikhāte prakṣipanti sma nadantam iva kuñjaram', null, 6114012),
('ramayana-6-114-13', 13, 'Yuddha Kanda, Sarga 114, Verse 13', 'तत्कृत्वा दुष्करं कर्म भ्रातरौ रामलक्ष्मणौ।
सायाह्ने शरभङ्गस्य रम्यमाश्रममीयतुः॥', 'tat kṛtvā duṣkaraṃ karma bhrātarau rāmalakṣmaṇau
sāyāhne śarabhaṅgasya ramyam āśramam īyatuḥ', null, 6114013),
('ramayana-6-114-14', 14, 'Yuddha Kanda, Sarga 114, Verse 14', 'शरभङ्गे दिवं प्राप्ते रामः सत्यपराक्रमः।
अभिवाद्य मुनीन्सर्वाञ्जनस्थानमुपागमत्॥', 'śarabhaṅge divaṃ prāpte rāmaḥ satyaparākramaḥ
abhivādya munīn sarvāñ janasthānam upāgamat', null, 6114014),
('ramayana-6-114-15', 15, 'Yuddha Kanda, Sarga 114, Verse 15', 'चतुर्दशसहस्राणि रक्षसां भीमकर्मणाम्।
हतानि वसता तत्र राघवेण महात्मना॥', 'caturdaśasahasrāṇi rakṣasāṃ bhīmakarmaṇām
hatāni vasatā tatra rāghaveṇa mahātmanā', null, 6114015),
('ramayana-6-114-16', 16, 'Yuddha Kanda, Sarga 114, Verse 16', 'ततः पश्चाच्छूर्पणखा रामपार्श्वमुपागता।
ततो रामेण संदिष्टो लक्ष्मणः सहसोत्थितः॥', 'tataḥ paścāc chūrpaṇakhā rāmapārśvam upāgatā
tato rāmeṇa saṃdiṣṭo lakṣmaṇaḥ sahasotthitaḥ', null, 6114016),
('ramayana-6-114-17', 17, 'Yuddha Kanda, Sarga 114, Verse 17', 'प्रगृह्य खड्गं चिच्छेद कर्णनासे महाबलः।
ततस्तेनार्दिता बाला रावणं समुपागता॥', 'pragṛhya khaḍgaṃ ciccheda karṇanāse mahābalaḥ
tatas tenārditā bālā rāvaṇaṃ samupāgatā', null, 6114017),
('ramayana-6-114-18', 18, 'Yuddha Kanda, Sarga 114, Verse 18', 'रावणानुचरो घोरो मारीचो नाम राक्षसः।
लोभयामास वैदेहीं भूत्वा रत्नमयो मृगः॥', 'rāvaṇānucaro ghoro mārīco nāma rākṣasaḥ
lobhayām āsa vaidehīṃ bhūtvā ratnamayo mṛgaḥ', null, 6114018),
('ramayana-6-114-19', 19, 'Yuddha Kanda, Sarga 114, Verse 19', 'सा राममब्रवीद्दृष्ट्वा वैदेही गृह्यतामिति।
अहो मनोहरः कान्त आश्रमे नो भविष्यति॥', 'sā rāmam abravīd dṛṣṭvā vaidehī gṛhyatām iti
aho manoharaḥ kānta āśrame no bhaviṣyati', null, 6114019),
('ramayana-6-114-20', 20, 'Yuddha Kanda, Sarga 114, Verse 20', 'ततो रामो धनुष्पाणिर्धावन्तमनुधावति।
स तं जघान धावन्तं शरेणानतपर्वणा॥', 'tato rāmo dhanuṣpāṇir dhāvantam anudhāvati
sa taṃ jaghāna dhāvantaṃ śareṇānataparvaṇā', null, 6114020),
('ramayana-6-114-21', 21, 'Yuddha Kanda, Sarga 114, Verse 21', 'अथ सौम्या दशग्रीवो मृगं याते तु राघवे।
लक्ष्मणे चापि निष्क्रान्ते प्रविवेशाश्रमं तदा।
जग्राह तरसा सीतां ग्रहः खे रोहिणीमिव॥', 'atha saumyā daśagrīvo mṛgaṃ yāte tu rāghave
lakṣmaṇe cāpi niṣkrānte praviveśāśramaṃ tadā
jagrāha tarasā sītāṃ grahaḥ khe rohiṇīm iva', null, 6114021),
('ramayana-6-114-22', 22, 'Yuddha Kanda, Sarga 114, Verse 22', 'त्रातुकामं ततो युद्धे हत्वा गृध्रं जटायुषम्।
प्रगृह्य सीतां सहसा जगामाशु स रावणः॥', 'trātukāmaṃ tato yuddhe hatvā gṛdhraṃ jaṭāyuṣam
pragṛhya sītāṃ sahasā jagāmāśu sa rāvaṇaḥ', null, 6114022),
('ramayana-6-114-23', 23, 'Yuddha Kanda, Sarga 114, Verse 23', 'ततस्त्वद्भुतसंकाशाः स्थिताः पर्वतमूर्धनि।
सीतां गृहीत्वा गच्छन्तं वानराः पर्वतोपमाः।
ददृशुर्विस्मितास्तत्र रावणं राक्षसाधिपम्॥', 'tatas tv adbhutasaṃkāśāḥ sthitāḥ parvatamūrdhani
sītāṃ gṛhītvā gacchantaṃ vānarāḥ parvatopamāḥ
dadṛśur vismitās tatra rāvaṇaṃ rākṣasādhipam', null, 6114023),
('ramayana-6-114-24', 24, 'Yuddha Kanda, Sarga 114, Verse 24', 'प्रविवेर्श तदा लङ्कां रावणो लोकरावणः॥', 'praviverśa tadā laṅkāṃ rāvaṇo lokarāvaṇaḥ', null, 6114024),
('ramayana-6-114-25', 25, 'Yuddha Kanda, Sarga 114, Verse 25', 'तां सुवर्णपरिक्रान्ते शुभे महति वेश्मनि।
प्रवेश्य मैथिलीं वाक्यैः सान्त्वयामास रावणः॥', 'tāṃ suvarṇaparikrānte śubhe mahati veśmani
praveśya maithilīṃ vākyaiḥ sāntvayām āsa rāvaṇaḥ', null, 6114025),
('ramayana-6-114-26', 26, 'Yuddha Kanda, Sarga 114, Verse 26', 'निवर्तमानः काकुत्स्थो दृष्ट्वा गृध्रं प्रविव्यथे॥', 'nivartamānaḥ kākutstho dṛṣṭvā gṛdhraṃ pravivyathe', null, 6114026),
('ramayana-6-114-27', 27, 'Yuddha Kanda, Sarga 114, Verse 27', 'गृध्रं हतं तदा दग्ध्वा रामः प्रियसखं पितुः।
गोदावरीमनुचरन्वनोद्देशांश्च पुष्पितान्।
आसेदतुर्महारण्ये कबन्धं नाम राक्षसं॥', 'gṛdhraṃ hataṃ tadā dagdhvā rāmaḥ priyasakhaṃ pituḥ
godāvarīm anucaran vanoddeśāṃś ca puṣpitān
āsedatur mahāraṇye kabandhaṃ nāma rākṣasaṃ', null, 6114027),
('ramayana-6-114-28', 28, 'Yuddha Kanda, Sarga 114, Verse 28', 'ततः कबन्धवचनाद्रामः सत्यपराक्रमः।
ऋश्यमूकं गिरिं गत्वा सुग्रीवेण समागतः॥', 'tataḥ kabandhavacanād rāmaḥ satyaparākramaḥ
ṛśyamūkaṃ giriṃ gatvā sugrīveṇa samāgataḥ', null, 6114028),
('ramayana-6-114-29', 29, 'Yuddha Kanda, Sarga 114, Verse 29', 'तयोः समागमः पूर्वं प्रीत्या हार्दो व्यजायत।
इतरेतर संवादात्प्रगाढः प्रणयस्तयोः॥', 'tayoḥ samāgamaḥ pūrvaṃ prītyā hārdo vyajāyata
itaretara saṃvādāt pragāḍhaḥ praṇayas tayoḥ', null, 6114029),
('ramayana-6-114-30', 30, 'Yuddha Kanda, Sarga 114, Verse 30', 'रामः स्वबाहुवीर्येण स्वराज्यं प्रत्यपादयत्।
वालिनं समरे हत्वा महाकायं महाबलम्॥', 'rāmaḥ svabāhuvīryeṇa svarājyaṃ pratyapādayat
vālinaṃ samare hatvā mahākāyaṃ mahābalam', null, 6114030),
('ramayana-6-114-31', 31, 'Yuddha Kanda, Sarga 114, Verse 31', 'सुग्रीवः स्थापितो राज्ये सहितः सर्ववानरैः।
रामाय प्रतिजानीते राजपुत्र्यास्तु मार्गणम्॥', 'sugrīvaḥ sthāpito rājye sahitaḥ sarvavānaraiḥ
rāmāya pratijānīte rājaputryās tu mārgaṇam', null, 6114031),
('ramayana-6-114-32', 32, 'Yuddha Kanda, Sarga 114, Verse 32', 'आदिष्टा वानरेन्द्रेण सुग्रीवेण महात्मना।
दशकोट्यः प्लवंगानां सर्वाः प्रस्थापिता दिशः॥', 'ādiṣṭā vānarendreṇa sugrīveṇa mahātmanā
daśakoṭyaḥ plavaṃgānāṃ sarvāḥ prasthāpitā diśaḥ', null, 6114032),
('ramayana-6-114-33', 33, 'Yuddha Kanda, Sarga 114, Verse 33', 'तेषां नो विप्रनष्टानां विन्ध्ये पर्वतसत्तमे।
भृशं शोकाभितप्तानां महान्कालोऽत्यवर्तत॥', 'teṣāṃ no vipranaṣṭānāṃ vindhye parvatasattame
bhṛśaṃ śokābhitaptānāṃ mahān kālo ''tyavartata', null, 6114033),
('ramayana-6-114-34', 34, 'Yuddha Kanda, Sarga 114, Verse 34', 'भ्राता तु गृध्रराजस्य संपातिर्नाम वीर्यवान्।
समाख्याति स्म वसतिं सीताया रावणालये॥', 'bhrātā tu gṛdhrarājasya saṃpātir nāma vīryavān
samākhyāti sma vasatiṃ sītāyā rāvaṇālaye', null, 6114034),
('ramayana-6-114-35', 35, 'Yuddha Kanda, Sarga 114, Verse 35', 'सोऽहं दुःखपरीतानां दुःखं तज्ज्ञातिनां नुदन्।
आत्मवीर्यं समास्थाय योजनानां शतं प्लुतः॥', 'so ''haṃ duḥkhaparītānāṃ duḥkhaṃ tajjñātināṃ nudan
ātmavīryaṃ samāsthāya yojanānāṃ śataṃ plutaḥ', null, 6114035),
('ramayana-6-114-36', 36, 'Yuddha Kanda, Sarga 114, Verse 36', 'तत्राहमेकामद्राक्षमशोकवनिकां गताम्।
कौशेयवस्त्रां मलिनां निरानन्दां दृढव्रताम्॥', 'tatrāham ekām adrākṣam aśokavanikāṃ gatām
kauśeyavastrāṃ malināṃ nirānandāṃ dṛḍhavratām', null, 6114036),
('ramayana-6-114-37', 37, 'Yuddha Kanda, Sarga 114, Verse 37', 'तया समेत्य विधिवत्पृष्ट्वा सर्वमनिन्दिताम्।
अभिज्ञानं मणिं लब्ध्वा चरितार्थोऽहमागतः॥', 'tayā sametya vidhivat pṛṣṭvā sarvam aninditām
abhijñānaṃ maṇiṃ labdhvā caritārtho ''ham āgataḥ', null, 6114037),
('ramayana-6-114-38', 38, 'Yuddha Kanda, Sarga 114, Verse 38', 'मया च पुनरागम्य रामस्याक्लिष्टकर्मणः।
अभिज्ञानं मया दत्तमर्चिष्मान्स महामणिः॥', 'mayā ca punar āgamya rāmasyākliṣṭakarmaṇaḥ
abhijñānaṃ mayā dattam arciṣmān sa mahāmaṇiḥ', null, 6114038),
('ramayana-6-114-39', 39, 'Yuddha Kanda, Sarga 114, Verse 39', 'श्रुत्वा तां मैथिलीं हृष्टस्त्वाशशंसे स जीवितम्।
जीवितान्तमनुप्राप्तः पीत्वामृतमिवातुरः॥', 'śrutvā tāṃ maithilīṃ hṛṣṭas tv āśaśaṃse sa jīvitam
jīvitāntam anuprāptaḥ pītvāmṛtam ivāturaḥ', null, 6114039),
('ramayana-6-114-40', 40, 'Yuddha Kanda, Sarga 114, Verse 40', 'उद्योजयिष्यन्नुद्योगं दध्रे लङ्कावधे मनः।
जिघांसुरिव लोकांस्ते सर्वांल्लोकान्विभावसुः॥', 'udyojayiṣyann udyogaṃ dadhre laṅkāvadhe manaḥ
jighāṃsur iva lokāṃs te sarvāṃl lokān vibhāvasuḥ', null, 6114040),
('ramayana-6-114-41', 41, 'Yuddha Kanda, Sarga 114, Verse 41', 'ततः समुद्रमासाद्य नलं सेतुमकारयत्।
अतरत्कपिवीराणां वाहिनी तेन सेतुना॥', 'tataḥ samudram āsādya nalaṃ setum akārayat
atarat kapivīrāṇāṃ vāhinī tena setunā', null, 6114041),
('ramayana-6-114-42', 42, 'Yuddha Kanda, Sarga 114, Verse 42', 'प्रहस्तमवधीन्नीलः कुम्भकर्णं तु राघवः।
लक्ष्मणो रावणसुतं स्वयं रामस्तु रावणम्॥', 'prahastam avadhīn nīlaḥ kumbhakarṇaṃ tu rāghavaḥ
lakṣmaṇo rāvaṇasutaṃ svayaṃ rāmas tu rāvaṇam', null, 6114042),
('ramayana-6-114-43', 43, 'Yuddha Kanda, Sarga 114, Verse 43', 'स शक्रेण समागम्य यमेन वरुणेन च।
सुरर्षिभिश्च काकुत्स्थो वरांल्लेभे परंतपः॥', 'sa śakreṇa samāgamya yamena varuṇena ca
surarṣibhiś ca kākutstho varāṃl lebhe paraṃtapaḥ', null, 6114043),
('ramayana-6-114-44', 44, 'Yuddha Kanda, Sarga 114, Verse 44', 'स तु दत्तवरः प्रीत्या वानरैश्च समागतः।
पुष्पकेण विमानेन किष्किन्धामभ्युपागमत्॥', 'sa tu dattavaraḥ prītyā vānaraiś ca samāgataḥ
puṣpakeṇa vimānena kiṣkindhām abhyupāgamat', null, 6114044),
('ramayana-6-114-45', 45, 'Yuddha Kanda, Sarga 114, Verse 45', 'तं गङ्गां पुनरासाद्य वसन्तं मुनिसंनिधौ।
अविघ्नं पुष्ययोगेन श्वो रामं द्रष्टुमर्हसि॥', 'taṃ gaṅgāṃ punar āsādya vasantaṃ munisaṃnidhau
avighnaṃ puṣyayogena śvo rāmaṃ draṣṭum arhasi', null, 6114045),
('ramayana-6-114-46', 46, 'Yuddha Kanda, Sarga 114, Verse 46', 'ततः स सत्यं हनुमद्वचो महन्निशम्य हृष्टो भरतः कृताञ्जलिः।
उवाच वाणीं मनसः प्रहर्षिणी चिरस्य पूर्णः खलु मे मनोरथः॥', 'tataḥ sa satyaṃ hanumadvaco mahan niśamya hṛṣṭo bharataḥ kṛtāñjaliḥ
uvāca vāṇīṃ manasaḥ praharṣiṇī cirasya pūrṇaḥ khalu me manorathaḥ', null, 6114046)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 115 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-115-1', 1, 'Yuddha Kanda, Sarga 115, Verse 1', 'श्रुत्वा तु परमानन्दं भरतः सत्यविक्रमः।
हृष्टमाज्ञापयामास शत्रुघ्नं परवीरहा॥', 'śrutvā tu param ānandaṃ bharataḥ satyavikramaḥ
hṛṣṭam ājñāpayām āsa śatrughnaṃ paravīrahā', null, 6115001),
('ramayana-6-115-2', 2, 'Yuddha Kanda, Sarga 115, Verse 2', 'दैवतानि च सर्वाणि चैत्यानि नगरस्य च।
सुगन्धमाल्यैर्वादित्रैरर्चन्तु शुचयो नराः॥', 'daivatāni ca sarvāṇi caityāni nagarasya ca
sugandhamālyair vāditrair arcantu śucayo narāḥ', null, 6115002),
('ramayana-6-115-3', 3, 'Yuddha Kanda, Sarga 115, Verse 3', 'राजदारास्तथामात्याः सैन्याः सेनागणाङ्गनाः।
अभिनिर्यान्तु रामस्य द्रष्टुं शशिनिभं मुखम्॥', 'rājadārās tathāmātyāḥ sainyāḥ senāgaṇāṅganāḥ
abhiniryāntu rāmasya draṣṭuṃ śaśinibhaṃ mukham', null, 6115003),
('ramayana-6-115-4', 4, 'Yuddha Kanda, Sarga 115, Verse 4', 'भरतस्य वचः श्रुत्वा शत्रुघ्नः परवीरहा।
विष्टीरनेकसाहस्रीश्चोदयामास वीर्यवान्॥', 'bharatasya vacaḥ śrutvā śatrughnaḥ paravīrahā
viṣṭīr anekasāhasrīś codayām āsa vīryavān', null, 6115004),
('ramayana-6-115-5', 5, 'Yuddha Kanda, Sarga 115, Verse 5', 'समीकुरुत निम्नानि विषमाणि समानि च।
स्थानानि च निरस्यन्तां नन्दिग्रामादितः परम्॥', 'samīkuruta nimnāni viṣamāṇi samāni ca
sthānāni ca nirasyantāṃ nandigrāmād itaḥ param', null, 6115005),
('ramayana-6-115-6', 6, 'Yuddha Kanda, Sarga 115, Verse 6', 'सिञ्चन्तु पृथिवीं कृत्स्नां हिमशीतेन वारिणा।
ततोऽभ्यवकिरंस्त्वन्ये लाजैः पुष्पैश्च सर्वतः॥', 'siñcantu pṛthivīṃ kṛtsnāṃ himaśītena vāriṇā
tato ''bhyavakiraṃs tv anye lājaiḥ puṣpaiś ca sarvataḥ', null, 6115006),
('ramayana-6-115-7', 7, 'Yuddha Kanda, Sarga 115, Verse 7', 'समुच्छ्रितपताकास्तु रथ्याः पुरवरोत्तमे।
शोभयन्तु च वेश्मानि सूर्यस्योदयनं प्रति॥', 'samucchritapatākās tu rathyāḥ puravarottame
śobhayantu ca veśmāni sūryasyodayanaṃ prati', null, 6115007),
('ramayana-6-115-8', 8, 'Yuddha Kanda, Sarga 115, Verse 8', 'स्रग्दाममुक्तपुष्पैश्च सुगन्धैः पञ्चवर्णकैः।
राजमार्गमसंबाधं किरन्तु शतशो नराः॥', 'sragdāmamuktapuṣpaiś ca sugandhaiḥ pañcavarṇakaiḥ
rājamārgam asaṃbādhaṃ kirantu śataśo narāḥ', null, 6115008),
('ramayana-6-115-9', 9, 'Yuddha Kanda, Sarga 115, Verse 9', 'मत्तैर्नागसहस्रैश्च शातकुम्भविभूषितः।
अपरे हेमकक्ष्याभिः सगजाभिः करेणुभिः।
निर्ययुस्त्वरया युक्ता रथैश्च सुमहारथाः॥', 'mattair nāgasahasraiś ca śātakumbhavibhūṣitaḥ
apare hemakakṣyābhiḥ sagajābhiḥ kareṇubhiḥ
niryayus tvarayā yuktā rathaiś ca sumahārathāḥ', null, 6115009),
('ramayana-6-115-10', 10, 'Yuddha Kanda, Sarga 115, Verse 10', 'ततो यानान्युपारूढाः सर्वा दशरथस्त्रियः।
कौसल्यां प्रमुखे कृत्वा सुमित्रां चापि निर्ययुः॥', 'tato yānāny upārūḍhāḥ sarvā daśarathastriyaḥ
kausalyāṃ pramukhe kṛtvā sumitrāṃ cāpi niryayuḥ', null, 6115010),
('ramayana-6-115-11', 11, 'Yuddha Kanda, Sarga 115, Verse 11', 'अश्वानां खुरशब्देन रथनेमिस्वनेन च।
शङ्खदुन्दुभिनादेन संचचालेव मेदिनी॥', 'aśvānāṃ khuraśabdena rathanemisvanena ca
śaṅkhadundubhinādena saṃcacāleva medinī', null, 6115011),
('ramayana-6-115-12', 12, 'Yuddha Kanda, Sarga 115, Verse 12', 'कृत्स्नं च नगरं तत्तु नन्दिग्राममुपागमत्।
द्विजातिमुख्यैर्धर्मात्मा श्रेणीमुख्यैः सनैगमैः॥', 'kṛtsnaṃ ca nagaraṃ tat tu nandigrāmam upāgamat
dvijātimukhyair dharmātmā śreṇīmukhyaiḥ sanaigamaiḥ', null, 6115012),
('ramayana-6-115-13', 13, 'Yuddha Kanda, Sarga 115, Verse 13', 'माल्यमोदक हस्तैश्च मन्त्रिभिर्भरतो वृतः।
शङ्खभेरीनिनादैश्च बन्दिभिश्चाभिवन्दितः॥', 'mālyamodaka hastaiś ca mantribhir bharato vṛtaḥ
śaṅkhabherīninādaiś ca bandibhiś cābhivanditaḥ', null, 6115013),
('ramayana-6-115-14', 14, 'Yuddha Kanda, Sarga 115, Verse 14', 'आर्यपादौ गृहीत्वा तु शिरसा धर्मकोविदः।
पाण्डुरं छत्रमादाय शुक्लमाल्योपशोभितम्॥', 'āryapādau gṛhītvā tu śirasā dharmakovidaḥ
pāṇḍuraṃ chatram ādāya śuklamālyopaśobhitam', null, 6115014),
('ramayana-6-115-15', 15, 'Yuddha Kanda, Sarga 115, Verse 15', 'शुक्ले च वालव्यजने राजार्हे हेमभूषिते।
उपवासकृशो दीनश्चीरकृष्णाजिनाम्बरः॥', 'śukle ca vālavyajane rājārhe hemabhūṣite
upavāsakṛśo dīnaś cīrakṛṣṇājināmbaraḥ', null, 6115015),
('ramayana-6-115-16', 16, 'Yuddha Kanda, Sarga 115, Verse 16', 'भ्रातुरागमनं श्रुत्वा तत्पूर्वं हर्षमागतः।
प्रत्युद्ययौ तदा रामं महात्मा सचिवैः सह॥', 'bhrātur āgamanaṃ śrutvā tat pūrvaṃ harṣam āgataḥ
pratyudyayau tadā rāmaṃ mahātmā sacivaiḥ saha', null, 6115016),
('ramayana-6-115-17', 17, 'Yuddha Kanda, Sarga 115, Verse 17', 'समीक्ष्य भरतो वाक्यमुवाच पवनात्मजम्।
कच्चिन्न खलु कापेयी सेव्यते चलचित्तता।
न हि पश्यामि काकुत्स्थं राममार्यं परंतपम्॥', 'samīkṣya bharato vākyam uvāca pavanātmajam
kaccin na khalu kāpeyī sevyate calacittatā
na hi paśyāmi kākutsthaṃ rāmam āryaṃ paraṃtapam', null, 6115017),
('ramayana-6-115-18', 18, 'Yuddha Kanda, Sarga 115, Verse 18', 'अथैवमुक्ते वचने हनूमानिदमब्रवीत्।
अर्थं विज्ञापयन्नेव भरतं सत्यविक्रमम्॥', 'athaivam ukte vacane hanūmān idam abravīt
arthaṃ vijñāpayann eva bharataṃ satyavikramam', null, 6115018),
('ramayana-6-115-19', 19, 'Yuddha Kanda, Sarga 115, Verse 19', 'सदा फलान्कुसुमितान्वृक्षान्प्राप्य मधुस्रवान्।
भरद्वाजप्रसादेन मत्तभ्रमरनादितान्॥', 'sadā phalān kusumitān vṛkṣān prāpya madhusravān
bharadvājaprasādena mattabhramaranāditān', null, 6115019),
('ramayana-6-115-20', 20, 'Yuddha Kanda, Sarga 115, Verse 20', 'तस्य चैष वरो दत्तो वासवेन परंतप।
ससैन्यस्य तदातिथ्यं कृतं सर्वगुणान्वितम्॥', 'tasya caiṣa varo datto vāsavena paraṃtapa
sasainyasya tadātithyaṃ kṛtaṃ sarvaguṇānvitam', null, 6115020),
('ramayana-6-115-21', 21, 'Yuddha Kanda, Sarga 115, Verse 21', 'निस्वनः श्रूयते भीमः प्रहृष्टानां वनौकसाम्।
मन्ये वानरसेना सा नदीं तरति गोमतीम्॥', 'nisvanaḥ śrūyate bhīmaḥ prahṛṣṭānāṃ vanaukasām
manye vānarasenā sā nadīṃ tarati gomatīm', null, 6115021),
('ramayana-6-115-22', 22, 'Yuddha Kanda, Sarga 115, Verse 22', 'रजोवर्षं समुद्भूतं पश्य वालुकिनीं प्रति।
मन्ये सालवनं रम्यं लोलयन्ति प्लवंगमाः॥', 'rajovarṣaṃ samudbhūtaṃ paśya vālukinīṃ prati
manye sālavanaṃ ramyaṃ lolayanti plavaṃgamāḥ', null, 6115022),
('ramayana-6-115-23', 23, 'Yuddha Kanda, Sarga 115, Verse 23', 'तदेतद्दृश्यते दूराद्विमलं चन्द्रसंनिभम्।
विमानं पुष्पकं दिव्यं मनसा ब्रह्मनिर्मितम्॥', 'tad etad dṛśyate dūrād vimalaṃ candrasaṃnibham
vimānaṃ puṣpakaṃ divyaṃ manasā brahmanirmitam', null, 6115023),
('ramayana-6-115-24', 24, 'Yuddha Kanda, Sarga 115, Verse 24', 'रावणं बान्धवैः सार्धं हत्वा लब्धं महात्मना।
धनदस्य प्रसादेन दिव्यमेतन्मनोजवम्॥', 'rāvaṇaṃ bāndhavaiḥ sārdhaṃ hatvā labdhaṃ mahātmanā
dhanadasya prasādena divyam etan manojavam', null, 6115024),
('ramayana-6-115-25', 25, 'Yuddha Kanda, Sarga 115, Verse 25', 'एतस्मिन्भ्रातरौ वीरौ वैदेह्या सह राघवौ।
सुग्रीवश्च महातेजा राक्षसेन्द्रो विभीषणः॥', 'etasmin bhrātarau vīrau vaidehyā saha rāghavau
sugrīvaś ca mahātejā rākṣasendro vibhīṣaṇaḥ', null, 6115025),
('ramayana-6-115-26', 26, 'Yuddha Kanda, Sarga 115, Verse 26', 'ततो हर्षसमुद्भूतो निस्वनो दिवमस्पृशत्।
स्त्रीबालयुववृद्धानां रामोऽयमिति कीर्तितः॥', 'tato harṣasamudbhūto nisvano divam aspṛśat
strībālayuvavṛddhānāṃ rāmo ''yam iti kīrtitaḥ', null, 6115026),
('ramayana-6-115-27', 27, 'Yuddha Kanda, Sarga 115, Verse 27', 'रथकुञ्जरवाजिभ्यस्तेऽवतीर्य महीं गताः।
ददृशुस्तं विमानस्थं नराः सोममिवाम्बरे॥', 'rathakuñjaravājibhyas te ''vatīrya mahīṃ gatāḥ
dadṛśus taṃ vimānasthaṃ narāḥ somam ivāmbare', null, 6115027),
('ramayana-6-115-28', 28, 'Yuddha Kanda, Sarga 115, Verse 28', 'प्राञ्जलिर्भरतो भूत्वा प्रहृष्टो राघवोन्मुखः।
स्वागतेन यथार्थेन ततो राममपूजयत्॥', 'prāñjalir bharato bhūtvā prahṛṣṭo rāghavonmukhaḥ
svāgatena yathārthena tato rāmam apūjayat', null, 6115028),
('ramayana-6-115-29', 29, 'Yuddha Kanda, Sarga 115, Verse 29', 'मनसा ब्रह्मणा सृष्टे विमाने लक्ष्मणाग्रजः।
रराज पृथुदीर्घाक्षो वज्रपाणिरिवापरः॥', 'manasā brahmaṇā sṛṣṭe vimāne lakṣmaṇāgrajaḥ
rarāja pṛthudīrghākṣo vajrapāṇir ivāparaḥ', null, 6115029),
('ramayana-6-115-30', 30, 'Yuddha Kanda, Sarga 115, Verse 30', 'ततो विमानाग्रगतं भरतो भ्रातरं तदा।
ववन्दे प्रणतो रामं मेरुस्थमिव भास्करम्॥', 'tato vimānāgragataṃ bharato bhrātaraṃ tadā
vavande praṇato rāmaṃ merustham iva bhāskaram', null, 6115030),
('ramayana-6-115-31', 31, 'Yuddha Kanda, Sarga 115, Verse 31', 'आरोपितो विमानं तद्भरतः सत्यविक्रमः।
राममासाद्य मुदितः पुनरेवाभ्यवादयत्॥', 'āropito vimānaṃ tad bharataḥ satyavikramaḥ
rāmam āsādya muditaḥ punar evābhyavādayat', null, 6115031),
('ramayana-6-115-32', 32, 'Yuddha Kanda, Sarga 115, Verse 32', 'तं समुत्थाप्य काकुत्स्थश्चिरस्याक्षिपथं गतम्।
अङ्के भरतमारोप्य मुदितः परिषष्वजे॥', 'taṃ samutthāpya kākutsthaś cirasyākṣipathaṃ gatam
aṅke bharatam āropya muditaḥ pariṣaṣvaje', null, 6115032),
('ramayana-6-115-33', 33, 'Yuddha Kanda, Sarga 115, Verse 33', 'ततो लक्ष्मणमासाद्य वैदेहीं च परंतपः।
अभ्यवादयत प्रीतो भरतो नाम चाब्रवीत्॥', 'tato lakṣmaṇam āsādya vaidehīṃ ca paraṃtapaḥ
abhyavādayata prīto bharato nāma cābravīt', null, 6115033),
('ramayana-6-115-34', 34, 'Yuddha Kanda, Sarga 115, Verse 34', 'सुग्रीवं कैकयी पुत्रो जाम्बवन्तं तथाङ्गदम्।
मैन्दं च द्विविदं नीलमृषभं चैव सस्वजे॥', 'sugrīvaṃ kaikayī putro jāmbavantaṃ tathāṅgadam
maindaṃ ca dvividaṃ nīlam ṛṣabhaṃ caiva sasvaje', null, 6115034),
('ramayana-6-115-35', 35, 'Yuddha Kanda, Sarga 115, Verse 35', 'ते कृत्वा मानुषं रूपं वानराः कामरूपिणः।
कुशलं पर्यपृच्छन्त प्रहृष्टा भरतं तदा॥', 'te kṛtvā mānuṣaṃ rūpaṃ vānarāḥ kāmarūpiṇaḥ
kuśalaṃ paryapṛcchanta prahṛṣṭā bharataṃ tadā', null, 6115035),
('ramayana-6-115-36', 36, 'Yuddha Kanda, Sarga 115, Verse 36', 'विभीषणं च भरतः सान्त्वयन्वाक्यमब्रवीत्।
दिष्ट्या त्वया सहायेन कृतं कर्म सुदुष्करम्॥', 'vibhīṣaṇaṃ ca bharataḥ sāntvayan vākyam abravīt
diṣṭyā tvayā sahāyena kṛtaṃ karma suduṣkaram', null, 6115036),
('ramayana-6-115-37', 37, 'Yuddha Kanda, Sarga 115, Verse 37', 'शत्रुघ्नश्च तदा राममभिवाद्य सलक्ष्मणम्।
सीतायाश्चरणौ पश्चाद्ववन्दे विनयान्वितः॥', 'śatrughnaś ca tadā rāmam abhivādya salakṣmaṇam
sītāyāś caraṇau paścād vavande vinayānvitaḥ', null, 6115037),
('ramayana-6-115-38', 38, 'Yuddha Kanda, Sarga 115, Verse 38', 'रामो मातरमासाद्य विषण्णं शोककर्शिताम्।
जग्राह प्रणतः पादौ मनो मातुः प्रसादयन्॥', 'rāmo mātaram āsādya viṣaṇṇaṃ śokakarśitām
jagrāha praṇataḥ pādau mano mātuḥ prasādayan', null, 6115038),
('ramayana-6-115-39', 39, 'Yuddha Kanda, Sarga 115, Verse 39', 'अभिवाद्य सुमित्रां च कैकेयीं च यशस्विनीम्।
स मातॄश्च तदा सर्वाः पुरोहितमुपागमत्॥', 'abhivādya sumitrāṃ ca kaikeyīṃ ca yaśasvinīm
sa mātṝś ca tadā sarvāḥ purohitam upāgamat', null, 6115039),
('ramayana-6-115-40', 40, 'Yuddha Kanda, Sarga 115, Verse 40', 'स्वागतं ते महाबाहो कौसल्यानन्दवर्धन।
इति प्राञ्जलयः सर्वे नागरा राममब्रुवन्॥', 'svāgataṃ te mahābāho kausalyānandavardhana
iti prāñjalayaḥ sarve nāgarā rāmam abruvan', null, 6115040),
('ramayana-6-115-41', 41, 'Yuddha Kanda, Sarga 115, Verse 41', 'तन्यञ्जलिसहस्राणि प्रगृहीतानि नागरैः।
आकोशानीव पद्मानि ददर्श भरताग्रजः॥', 'tany añjalisahasrāṇi pragṛhītāni nāgaraiḥ
ākośānīva padmāni dadarśa bharatāgrajaḥ', null, 6115041),
('ramayana-6-115-42', 42, 'Yuddha Kanda, Sarga 115, Verse 42', 'पादुके ते तु रामस्य गृहीत्वा भरतः स्वयम्।
चरणाभ्यां नरेन्द्रस्य योजयामास धर्मवित्॥', 'pāduke te tu rāmasya gṛhītvā bharataḥ svayam
caraṇābhyāṃ narendrasya yojayām āsa dharmavit', null, 6115042),
('ramayana-6-115-43', 43, 'Yuddha Kanda, Sarga 115, Verse 43', 'अब्रवीच्च तदा रामं भरतः स कृताञ्जलिः।
एतत्ते रक्षितं राजन्राज्यं निर्यातितं मया॥', 'abravīc ca tadā rāmaṃ bharataḥ sa kṛtāñjaliḥ
etat te rakṣitaṃ rājan rājyaṃ niryātitaṃ mayā', null, 6115043),
('ramayana-6-115-44', 44, 'Yuddha Kanda, Sarga 115, Verse 44', 'अद्य जन्म कृतार्थं मे संवृत्तश्च मनोरथः।
यस्त्वां पश्यामि राजानमयोध्यां पुनरागतम्॥', 'adya janma kṛtārthaṃ me saṃvṛttaś ca manorathaḥ
yas tvāṃ paśyāmi rājānam ayodhyāṃ punar āgatam', null, 6115044),
('ramayana-6-115-45', 45, 'Yuddha Kanda, Sarga 115, Verse 45', 'अवेक्षतां भवान्कोशं कोष्ठागारं पुरं बलम्।
भवतस्तेजसा सर्वं कृतं दशगुणं मया॥', 'avekṣatāṃ bhavān kośaṃ koṣṭhāgāraṃ puraṃ balam
bhavatas tejasā sarvaṃ kṛtaṃ daśaguṇaṃ mayā', null, 6115045),
('ramayana-6-115-46', 46, 'Yuddha Kanda, Sarga 115, Verse 46', 'तथा ब्रुवाणं भरतं दृष्ट्वा तं भ्रातृवत्सलम्।
मुमुचुर्वानरा बाष्पं राक्षसश्च विभीषणः॥', 'tathā bruvāṇaṃ bharataṃ dṛṣṭvā taṃ bhrātṛvatsalam
mumucur vānarā bāṣpaṃ rākṣasaś ca vibhīṣaṇaḥ', null, 6115046),
('ramayana-6-115-47', 47, 'Yuddha Kanda, Sarga 115, Verse 47', 'ततः प्रहर्षाद्भरतमङ्कमारोप्य राघवः।
ययौ तेन विमानेन ससैन्यो भरताश्रमम्॥', 'tataḥ praharṣād bharatam aṅkam āropya rāghavaḥ
yayau tena vimānena sasainyo bharatāśramam', null, 6115047),
('ramayana-6-115-48', 48, 'Yuddha Kanda, Sarga 115, Verse 48', 'भरताश्रममासाद्य ससैन्यो राघवस्तदा।
अवतीर्य विमानाग्रादवतस्थे महीतले॥', 'bharatāśramam āsādya sasainyo rāghavas tadā
avatīrya vimānāgrād avatasthe mahītale', null, 6115048),
('ramayana-6-115-49', 49, 'Yuddha Kanda, Sarga 115, Verse 49', 'अब्रवीच्च तदा रामस्तद्विमानमनुत्तमम्।
वह वैश्रवणं देवमनुजानामि गम्यताम्॥', 'abravīc ca tadā rāmas tadvimānam anuttamam
vaha vaiśravaṇaṃ devam anujānāmi gamyatām', null, 6115049),
('ramayana-6-115-50', 50, 'Yuddha Kanda, Sarga 115, Verse 50', 'ततो रामाभ्यनुज्ञातं तद्विमानमनुत्तमम्।
उत्तरां दिशमुद्दिश्य जगाम धनदालयम्॥', 'tato rāmābhyanujñātaṃ tadvimānam anuttamam
uttarāṃ diśam uddiśya jagāma dhanadālayam', null, 6115050),
('ramayana-6-115-51', 51, 'Yuddha Kanda, Sarga 115, Verse 51', 'पुरोहितस्यात्मसमस्य राघवो बृहस्पतेः शक्र इवामराधिपः।
निपीड्य पादौ पृथगासने शुभे सहैव तेनोपविवेश वीर्यवान्॥', 'purohitasyātmasamasya rāghavo bṛhaspateḥ śakra ivāmarādhipaḥ
nipīḍya pādau pṛthag āsane śubhe sahaiva tenopaviveśa vīryavān', null, 6115051)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 116 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 6 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-6-116-1', 1, 'Yuddha Kanda, Sarga 116, Verse 1', 'शिरस्यञ्जलिमादाय कैकेयीनन्दिवर्धनः।
बभाषे भरतो ज्येष्ठं रामं सत्यपराक्रमम्॥', 'śirasy añjalim ādāya kaikeyīnandivardhanaḥ
babhāṣe bharato jyeṣṭhaṃ rāmaṃ satyaparākramam', null, 6116001),
('ramayana-6-116-2', 2, 'Yuddha Kanda, Sarga 116, Verse 2', 'पूजिता मामिका माता दत्तं राज्यमिदं मम।
तद्ददामि पुनस्तुभ्यं यथा त्वमददा मम॥', 'pūjitā māmikā mātā dattaṃ rājyam idaṃ mama
tad dadāmi punas tubhyaṃ yathā tvam adadā mama', null, 6116002),
('ramayana-6-116-3', 3, 'Yuddha Kanda, Sarga 116, Verse 3', 'धुरमेकाकिना न्यस्तामृषभेण बलीयसा।
किशोरवद्गुरुं भारं न वोढुमहमुत्सहे॥', 'dhuram ekākinā nyastām ṛṣabheṇa balīyasā
kiśoravad guruṃ bhāraṃ na voḍhum aham utsahe', null, 6116003),
('ramayana-6-116-4', 4, 'Yuddha Kanda, Sarga 116, Verse 4', 'वारिवेगेन महता भिन्नः सेतुरिव क्षरन्।
दुर्बन्धनमिदं मन्ये राज्यच्छिद्रमसंवृतम्॥', 'vārivegena mahatā bhinnaḥ setur iva kṣaran
durbandhanam idaṃ manye rājyacchidram asaṃvṛtam', null, 6116004),
('ramayana-6-116-5', 5, 'Yuddha Kanda, Sarga 116, Verse 5', 'गतिं खर इवाश्वस्य हंसस्येव च वायसः।
नान्वेतुमुत्सहे देव तव मार्गमरिंदम॥', 'gatiṃ khara ivāśvasya haṃsasyeva ca vāyasaḥ
nānvetum utsahe deva tava mārgam ariṃdama', null, 6116005),
('ramayana-6-116-6', 6, 'Yuddha Kanda, Sarga 116, Verse 6', 'यथा च रोपितो वृक्षो जातश्चान्तर्निवेशने।
महांश्च सुदुरारोहो महास्कन्धः प्रशाखवान्॥', 'yathā ca ropito vṛkṣo jātaś cāntarniveśane
mahāṃś ca sudurāroho mahāskandhaḥ praśākhavān', null, 6116006),
('ramayana-6-116-7', 7, 'Yuddha Kanda, Sarga 116, Verse 7', 'शीर्येत पुष्पितो भूत्वा न फलानि प्रदर्शयेत्।
तस्य नानुभवेदर्थं यस्य हेतोः स रोप्यते॥', 'śīryeta puṣpito bhūtvā na phalāni pradarśayet
tasya nānubhaved arthaṃ yasya hetoḥ sa ropyate', null, 6116007),
('ramayana-6-116-8', 8, 'Yuddha Kanda, Sarga 116, Verse 8', 'एषोपमा महाबाहो त्वमर्थं वेत्तुमर्हसि।
यद्यस्मान्मनुजेन्द्र त्वं भक्तान्भृत्यान्न शाधि हि॥', 'eṣopamā mahābāho tvam arthaṃ vettum arhasi
yady asmān manujendra tvaṃ bhaktān bhṛtyān na śādhi hi', null, 6116008),
('ramayana-6-116-9', 9, 'Yuddha Kanda, Sarga 116, Verse 9', 'जगदद्याभिषिक्तं त्वामनुपश्यतु सर्वतः।
प्रतपन्तमिवादित्यं मध्याह्ने दीप्ततेजसं॥', 'jagad adyābhiṣiktaṃ tvām anupaśyatu sarvataḥ
pratapantam ivādityaṃ madhyāhne dīptatejasaṃ', null, 6116009),
('ramayana-6-116-10', 10, 'Yuddha Kanda, Sarga 116, Verse 10', 'तूर्यसंघातनिर्घोषैः काञ्चीनूपुरनिस्वनैः।
मधुरैर्गीतशब्दैश्च प्रतिबुध्यस्व शेष्व च॥', 'tūryasaṃghātanirghoṣaiḥ kāñcīnūpuranisvanaiḥ
madhurair gītaśabdaiś ca pratibudhyasva śeṣva ca', null, 6116010),
('ramayana-6-116-11', 11, 'Yuddha Kanda, Sarga 116, Verse 11', 'यावदावर्तते चक्रं यावती च वसुंधरा।
तावत्त्वमिह सर्वस्य स्वामित्वमभिवर्तय॥', 'yāvad āvartate cakraṃ yāvatī ca vasuṃdharā
tāvat tvam iha sarvasya svāmitvam abhivartaya', null, 6116011),
('ramayana-6-116-12', 12, 'Yuddha Kanda, Sarga 116, Verse 12', 'भरतस्य वचः श्रुत्वा रामः परपुरंजयः।
तथेति प्रतिजग्राह निषसादासने शुभे॥', 'bharatasya vacaḥ śrutvā rāmaḥ parapuraṃjayaḥ
tatheti pratijagrāha niṣasādāsane śubhe', null, 6116012),
('ramayana-6-116-13', 13, 'Yuddha Kanda, Sarga 116, Verse 13', 'ततः शत्रुघ्नवचनान्निपुणाः श्मश्रुवर्धकाः।
सुखहस्ताः सुशीघ्राश्च राघवं पर्युपासत॥', 'tataḥ śatrughnavacanān nipuṇāḥ śmaśruvardhakāḥ
sukhahastāḥ suśīghrāś ca rāghavaṃ paryupāsata', null, 6116013),
('ramayana-6-116-14', 14, 'Yuddha Kanda, Sarga 116, Verse 14', 'पूर्वं तु भरते स्नाते लक्ष्मणे च महाबले।
सुग्रीवे वानरेन्द्रे च राक्षसेन्द्रे विभीषणे॥', 'pūrvaṃ tu bharate snāte lakṣmaṇe ca mahābale
sugrīve vānarendre ca rākṣasendre vibhīṣaṇe', null, 6116014),
('ramayana-6-116-15', 15, 'Yuddha Kanda, Sarga 116, Verse 15', 'विशोधितजटः स्नातश्चित्रमाल्यानुलेपनः।
महार्हवसनोपेतस्तस्थौ तत्र श्रिया ज्वलन्॥', 'viśodhitajaṭaḥ snātaś citramālyānulepanaḥ
mahārhavasanopetas tasthau tatra śriyā jvalan', null, 6116015),
('ramayana-6-116-16', 16, 'Yuddha Kanda, Sarga 116, Verse 16', 'प्रतिकर्म च रामस्य कारयामास वीर्यवान्।
लक्ष्मणस्य च लक्ष्मीवानिक्ष्वाकुकुलवर्धनः॥', 'pratikarma ca rāmasya kārayām āsa vīryavān
lakṣmaṇasya ca lakṣmīvān ikṣvākukulavardhanaḥ', null, 6116016),
('ramayana-6-116-17', 17, 'Yuddha Kanda, Sarga 116, Verse 17', 'प्रतिकर्म च सीतायाः सर्वा दशरथस्त्रियः।
आत्मनैव तदा चक्रुर्मनस्विन्यो मनोहरम्॥', 'pratikarma ca sītāyāḥ sarvā daśarathastriyaḥ
ātmanaiva tadā cakrur manasvinyo manoharam', null, 6116017),
('ramayana-6-116-18', 18, 'Yuddha Kanda, Sarga 116, Verse 18', 'ततो राघवपत्नीनां सर्वासामेव शोभनम्।
चकार यत्नात्कौसल्या प्रहृष्टा पुत्रवत्सला॥', 'tato rāghavapatnīnāṃ sarvāsām eva śobhanam
cakāra yatnāt kausalyā prahṛṣṭā putravatsalā', null, 6116018),
('ramayana-6-116-19', 19, 'Yuddha Kanda, Sarga 116, Verse 19', 'ततः शत्रुघ्नवचनात्सुमन्त्रो नाम सारथिः।
योजयित्वाभिचक्राम रथं सर्वाङ्गशोभनम्॥', 'tataḥ śatrughnavacanāt sumantro nāma sārathiḥ
yojayitvābhicakrāma rathaṃ sarvāṅgaśobhanam', null, 6116019),
('ramayana-6-116-20', 20, 'Yuddha Kanda, Sarga 116, Verse 20', 'अर्कमण्डलसंकाशं दिव्यं दृष्ट्वा रथं स्थितम्।
आरुरोह महाबाहू रामः सत्यपराक्रमः॥', 'arkamaṇḍalasaṃkāśaṃ divyaṃ dṛṣṭvā rathaṃ sthitam
āruroha mahābāhū rāmaḥ satyaparākramaḥ', null, 6116020),
('ramayana-6-116-21', 21, 'Yuddha Kanda, Sarga 116, Verse 21', 'अयोध्यायां तु सचिवा राज्ञो दशरथस्य ये।
पुरोहितं पुरस्कृत्य मन्त्रयामासुरर्थवत्॥', 'ayodhyāyāṃ tu sacivā rājño daśarathasya ye
purohitaṃ puraskṛtya mantrayām āsur arthavat', null, 6116021),
('ramayana-6-116-22', 22, 'Yuddha Kanda, Sarga 116, Verse 22', 'मन्त्रयन्रामवृद्ध्यर्थं वृत्त्यर्थं नगरस्य च।
सर्वमेवाभिषेकार्थं जयार्हस्य महात्मनः।
कर्तुमर्हथ रामस्य यद्यन्मङ्गलपूर्वकम्॥', 'mantrayan rāmavṛddhyarthaṃ vṛttyarthaṃ nagarasya ca
sarvam evābhiṣekārthaṃ jayārhasya mahātmanaḥ
kartum arhatha rāmasya yad yan maṅgalapūrvakam', null, 6116022),
('ramayana-6-116-23', 23, 'Yuddha Kanda, Sarga 116, Verse 23', 'इति ते मन्त्रिणः सर्वे संदिश्य तु पुरोहितम्।
नगरान्निर्ययुस्तूर्णं रामदर्शनबुद्धयः॥', 'iti te mantriṇaḥ sarve saṃdiśya tu purohitam
nagarān niryayus tūrṇaṃ rāmadarśanabuddhayaḥ', null, 6116023),
('ramayana-6-116-24', 24, 'Yuddha Kanda, Sarga 116, Verse 24', 'हरियुक्तं सहस्राक्षो रथमिन्द्र इवानघः।
प्रययौ रथमास्थाय रामो नगरमुत्तमम्॥', 'hariyuktaṃ sahasrākṣo ratham indra ivānaghaḥ
prayayau ratham āsthāya rāmo nagaram uttamam', null, 6116024),
('ramayana-6-116-25', 25, 'Yuddha Kanda, Sarga 116, Verse 25', 'जग्राह भरतो रश्मीञ्शत्रुघ्नश्छत्रमाददे।
लक्ष्मणो व्यजनं तस्य मूर्ध्नि संपर्यवीजयत्॥', 'jagrāha bharato raśmīñ śatrughnaś chatram ādade
lakṣmaṇo vyajanaṃ tasya mūrdhni saṃparyavījayat', null, 6116025),
('ramayana-6-116-26', 26, 'Yuddha Kanda, Sarga 116, Verse 26', 'श्वेतं च वालव्यजनं सुग्रीवो वानरेश्वरः।
अपरं चन्द्रसंकाशं राक्षसेन्द्रो विभीषणः॥', 'śvetaṃ ca vālavyajanaṃ sugrīvo vānareśvaraḥ
aparaṃ candrasaṃkāśaṃ rākṣasendro vibhīṣaṇaḥ', null, 6116026),
('ramayana-6-116-27', 27, 'Yuddha Kanda, Sarga 116, Verse 27', 'ऋषिसंघैर्तदाकाशे देवैश्च समरुद्गणैः।
स्तूयमानस्य रामस्य शुश्रुवे मधुरध्वनिः॥', 'ṛṣisaṃghair tadākāśe devaiś ca samarudgaṇaiḥ
stūyamānasya rāmasya śuśruve madhuradhvaniḥ', null, 6116027),
('ramayana-6-116-28', 28, 'Yuddha Kanda, Sarga 116, Verse 28', 'ततः शत्रुंजयं नाम कुञ्जरं पर्वतोपमम्।
आरुरोह महातेजाः सुग्रीवो वानरेश्वरः॥', 'tataḥ śatruṃjayaṃ nāma kuñjaraṃ parvatopamam
āruroha mahātejāḥ sugrīvo vānareśvaraḥ', null, 6116028),
('ramayana-6-116-29', 29, 'Yuddha Kanda, Sarga 116, Verse 29', 'नवनागसहस्राणि ययुरास्थाय वानराः।
मानुषं विग्रहं कृत्वा सर्वाभरणभूषिताः॥', 'navanāgasahasrāṇi yayur āsthāya vānarāḥ
mānuṣaṃ vigrahaṃ kṛtvā sarvābharaṇabhūṣitāḥ', null, 6116029),
('ramayana-6-116-30', 30, 'Yuddha Kanda, Sarga 116, Verse 30', 'शङ्खशब्दप्रणादैश्च दुन्दुभीनां च निस्वनैः।
प्रययू पुरुषव्याघ्रस्तां पुरीं हर्म्यमालिनीम्॥', 'śaṅkhaśabdapraṇādaiś ca dundubhīnāṃ ca nisvanaiḥ
prayayū puruṣavyāghras tāṃ purīṃ harmyamālinīm', null, 6116030),
('ramayana-6-116-31', 31, 'Yuddha Kanda, Sarga 116, Verse 31', 'ददृशुस्ते समायान्तं राघवं सपुरःसरम्।
विराजमानं वपुषा रथेनातिरथं तदा॥', 'dadṛśus te samāyāntaṃ rāghavaṃ sapuraḥsaram
virājamānaṃ vapuṣā rathenātirathaṃ tadā', null, 6116031),
('ramayana-6-116-32', 32, 'Yuddha Kanda, Sarga 116, Verse 32', 'ते वर्धयित्वा काकुत्स्थं रामेण प्रतिनन्दिताः।
अनुजग्मुर्महात्मानं भ्रातृभिः परिवारितम्॥', 'te vardhayitvā kākutsthaṃ rāmeṇa pratinanditāḥ
anujagmur mahātmānaṃ bhrātṛbhiḥ parivāritam', null, 6116032),
('ramayana-6-116-33', 33, 'Yuddha Kanda, Sarga 116, Verse 33', 'अमात्यैर्ब्राह्मणैश्चैव तथा प्रकृतिभिर्वृतः।
श्रिया विरुरुचे रामो नक्षत्रैरिव चन्द्रमाः॥', 'amātyair brāhmaṇaiś caiva tathā prakṛtibhir vṛtaḥ
śriyā viruruce rāmo nakṣatrair iva candramāḥ', null, 6116033),
('ramayana-6-116-34', 34, 'Yuddha Kanda, Sarga 116, Verse 34', 'स पुरोगामिभिस्तूर्यैस्तालस्वस्तिकपाणिभिः।
प्रव्याहरद्भिर्मुदितैर्मङ्गलानि ययौ वृतः॥', 'sa purogāmibhis tūryais tālasvastikapāṇibhiḥ
pravyāharadbhir muditair maṅgalāni yayau vṛtaḥ', null, 6116034),
('ramayana-6-116-35', 35, 'Yuddha Kanda, Sarga 116, Verse 35', 'अक्षतं जातरूपं च गावः कन्यास्तथा द्विजाः।
नरा मोदकहस्ताश्च रामस्य पुरतो ययुः॥', 'akṣataṃ jātarūpaṃ ca gāvaḥ kanyās tathā dvijāḥ
narā modakahastāś ca rāmasya purato yayuḥ', null, 6116035),
('ramayana-6-116-36', 36, 'Yuddha Kanda, Sarga 116, Verse 36', 'सख्यं च रामः सुग्रीवे प्रभावं चानिलात्मजे।
वानराणां च तत्कर्म व्याचचक्षेऽथ मन्त्रिणाम्।
श्रुत्वा च विस्मयं जग्मुरयोध्यापुरवासिनः॥', 'sakhyaṃ ca rāmaḥ sugrīve prabhāvaṃ cānilātmaje
vānarāṇāṃ ca tat karma vyācacakṣe ''tha mantriṇām
śrutvā ca vismayaṃ jagmur ayodhyāpuravāsinaḥ', null, 6116036),
('ramayana-6-116-37', 37, 'Yuddha Kanda, Sarga 116, Verse 37', 'द्युतिमानेतदाख्याय रामो वानरसंवृतः।
हृष्टपुष्टजनाकीर्णामयोध्यां प्रविवेश ह॥', 'dyutimān etad ākhyāya rāmo vānarasaṃvṛtaḥ
hṛṣṭapuṣṭajanākīrṇām ayodhyāṃ praviveśa ha', null, 6116037),
('ramayana-6-116-38', 38, 'Yuddha Kanda, Sarga 116, Verse 38', 'ततो ह्यभ्युच्छ्रयन्पौराः पताकास्ते गृहे गृहे।
ऐक्ष्वाकाध्युषितं रम्यमाससाद पितुर्गृहम्॥', 'tato hy abhyucchrayan paurāḥ patākās te gṛhe gṛhe
aikṣvākādhyuṣitaṃ ramyam āsasāda pitur gṛham', null, 6116038),
('ramayana-6-116-39', 39, 'Yuddha Kanda, Sarga 116, Verse 39', 'पितुर्भवनमासाद्य प्रविश्य च महात्मनः।
कौसल्यां च सुमित्रां च कैकेयीं चाभ्यवादयत्॥', 'pitur bhavanam āsādya praviśya ca mahātmanaḥ
kausalyāṃ ca sumitrāṃ ca kaikeyīṃ cābhyavādayat', null, 6116039),
('ramayana-6-116-40', 40, 'Yuddha Kanda, Sarga 116, Verse 40', 'अथाब्रवीद्राजपुत्रो भरतं धर्मिणां वरम्।
अथोपहितया वाचा मधुरं रघुनन्दनः॥', 'athābravīd rājaputro bharataṃ dharmiṇāṃ varam
athopahitayā vācā madhuraṃ raghunandanaḥ', null, 6116040),
('ramayana-6-116-41', 41, 'Yuddha Kanda, Sarga 116, Verse 41', 'यच्च मद्भवनं श्रेष्ठं साशोकवनिकं महत्।
मुक्तावैदूर्यसंकीर्णं सुग्रीवस्य निवेदय॥', 'yac ca madbhavanaṃ śreṣṭhaṃ sāśokavanikaṃ mahat
muktāvaidūryasaṃkīrṇaṃ sugrīvasya nivedaya', null, 6116041),
('ramayana-6-116-42', 42, 'Yuddha Kanda, Sarga 116, Verse 42', 'तस्य तद्वचनं श्रुत्वा भरतः सत्यविक्रमः।
पाणौ गृहीत्वा सुग्रीवं प्रविवेश तमालयम्॥', 'tasya tad vacanaṃ śrutvā bharataḥ satyavikramaḥ
pāṇau gṛhītvā sugrīvaṃ praviveśa tam ālayam', null, 6116042),
('ramayana-6-116-43', 43, 'Yuddha Kanda, Sarga 116, Verse 43', 'ततस्तैलप्रदीपांश्च पर्यङ्कास्तरणानि च।
गृहीत्वा विविशुः क्षिप्रं शत्रुघ्नेन प्रचोदिताः॥', 'tatas tailapradīpāṃś ca paryaṅkāstaraṇāni ca
gṛhītvā viviśuḥ kṣipraṃ śatrughnena pracoditāḥ', null, 6116043),
('ramayana-6-116-44', 44, 'Yuddha Kanda, Sarga 116, Verse 44', 'उवाच च महातेजाः सुग्रीवं राघवानुजः।
अभिषेकाय रामस्य दूतानाज्ञापय प्रभो॥', 'uvāca ca mahātejāḥ sugrīvaṃ rāghavānujaḥ
abhiṣekāya rāmasya dūtān ājñāpaya prabho', null, 6116044),
('ramayana-6-116-45', 45, 'Yuddha Kanda, Sarga 116, Verse 45', 'सौवर्णान्वानरेन्द्राणां चतुर्णां चतुरो घटान्।
ददौ क्षिप्रं स सुग्रीवः सर्वरत्नविभूषितान्॥', 'sauvarṇān vānarendrāṇāṃ caturṇāṃ caturo ghaṭān
dadau kṣipraṃ sa sugrīvaḥ sarvaratnavibhūṣitān', null, 6116045),
('ramayana-6-116-46', 46, 'Yuddha Kanda, Sarga 116, Verse 46', 'यथा प्रत्यूषसमये चतुर्णां सागराम्भसाम्।
पूर्णैर्घटैः प्रतीक्षध्वं तथा कुरुत वानराः॥', 'yathā pratyūṣasamaye caturṇāṃ sāgarāmbhasām
pūrṇair ghaṭaiḥ pratīkṣadhvaṃ tathā kuruta vānarāḥ', null, 6116046),
('ramayana-6-116-47', 47, 'Yuddha Kanda, Sarga 116, Verse 47', 'एवमुक्ता महात्मानो वानरा वारणोपमाः।
उत्पेतुर्गगनं शीघ्रं गरुडा इव शीघ्रगाः॥', 'evam uktā mahātmāno vānarā vāraṇopamāḥ
utpetur gaganaṃ śīghraṃ garuḍā iva śīghragāḥ', null, 6116047),
('ramayana-6-116-48', 48, 'Yuddha Kanda, Sarga 116, Verse 48', 'जाम्बवांश्च हनूमांश्च वेगदर्शी च वानरः।
ऋषभश्चैव कलशाञ्जलपूर्णानथानयन्।
नदीशतानां पञ्चानां जले कुम्भैरुपाहरन्॥', 'jāmbavāṃś ca hanūmāṃś ca vegadarśī ca vānaraḥ
ṛṣabhaś caiva kalaśāñ jalapūrṇān athānayan
nadīśatānāṃ pañcānāṃ jale kumbhair upāharan', null, 6116048),
('ramayana-6-116-49', 49, 'Yuddha Kanda, Sarga 116, Verse 49', 'पूर्वात्समुद्रात्कलशं जलपूर्णमथानयत्।
सुषेणः सत्त्वसंपन्नः सर्वरत्नविभूषितम्॥', 'pūrvāt samudrāt kalaśaṃ jalapūrṇam athānayat
suṣeṇaḥ sattvasaṃpannaḥ sarvaratnavibhūṣitam', null, 6116049),
('ramayana-6-116-50', 50, 'Yuddha Kanda, Sarga 116, Verse 50', 'ऋषभो दक्षिणात्तूर्णं समुद्राज्जलमाहरत्॥', 'ṛṣabho dakṣiṇāt tūrṇaṃ samudrāj jalam āharat', null, 6116050),
('ramayana-6-116-51', 51, 'Yuddha Kanda, Sarga 116, Verse 51', 'रक्तचन्दनकर्पूरैः संवृतं काञ्चनं घटम्।
गवयः पश्चिमात्तोयमाजहार महार्णवात्॥', 'raktacandanakarpūraiḥ saṃvṛtaṃ kāñcanaṃ ghaṭam
gavayaḥ paścimāt toyam ājahāra mahārṇavāt', null, 6116051),
('ramayana-6-116-52', 52, 'Yuddha Kanda, Sarga 116, Verse 52', 'रत्नकुम्भेन महता शीतं मारुतविक्रमः।
उत्तराच्च जलं शीघ्रं गरुडानिलविक्रमः॥', 'ratnakumbhena mahatā śītaṃ mārutavikramaḥ
uttarāc ca jalaṃ śīghraṃ garuḍānilavikramaḥ', null, 6116052),
('ramayana-6-116-53', 53, 'Yuddha Kanda, Sarga 116, Verse 53', 'अभिषेकाय रामस्य शत्रुघ्नः सचिवैः सह।
पुरोहिताय श्रेष्ठाय सुहृद्भ्यश्च न्यवेदयत्॥', 'abhiṣekāya rāmasya śatrughnaḥ sacivaiḥ saha
purohitāya śreṣṭhāya suhṛdbhyaś ca nyavedayat', null, 6116053),
('ramayana-6-116-54', 54, 'Yuddha Kanda, Sarga 116, Verse 54', 'ततः स प्रयतो वृद्धो वसिष्ठो ब्राह्मणैः सह।
रामं रत्नमयो पीठे सहसीतं न्यवेशयत्॥', 'tataḥ sa prayato vṛddho vasiṣṭho brāhmaṇaiḥ saha
rāmaṃ ratnamayo pīṭhe sahasītaṃ nyaveśayat', null, 6116054),
('ramayana-6-116-55', 55, 'Yuddha Kanda, Sarga 116, Verse 55', 'वसिष्ठो वामदेवश्च जाबालिरथ काश्यपः।
कात्यायनः सुयज्ञश्च गौतमो विजयस्तथा॥', 'vasiṣṭho vāmadevaś ca jābālir atha kāśyapaḥ
kātyāyanaḥ suyajñaś ca gautamo vijayas tathā', null, 6116055),
('ramayana-6-116-56', 56, 'Yuddha Kanda, Sarga 116, Verse 56', 'अभ्यषिञ्चन्नरव्याघ्रं प्रसन्नेन सुगन्धिना।
सलिलेन सहस्राक्षं वसवो वासवं यथा॥', 'abhyaṣiñcan naravyāghraṃ prasannena sugandhinā
salilena sahasrākṣaṃ vasavo vāsavaṃ yathā', null, 6116056),
('ramayana-6-116-57', 57, 'Yuddha Kanda, Sarga 116, Verse 57', 'ऋत्विग्भिर्ब्राह्मणैः पूर्वं कन्याभिर्मन्त्रिभिस्तथा।
योधैश्चैवाभ्यषिञ्चंस्ते संप्रहृष्टाः सनैगमैः॥', 'ṛtvigbhir brāhmaṇaiḥ pūrvaṃ kanyābhir mantribhis tathā
yodhaiś caivābhyaṣiñcaṃs te saṃprahṛṣṭāḥ sanaigamaiḥ', null, 6116057),
('ramayana-6-116-58', 58, 'Yuddha Kanda, Sarga 116, Verse 58', 'सर्वौषधिरसैश्चापि दैवतैर्नभसि स्थितैः।
चतुर्हिर्लोकपालैश्च सर्वैर्देवैश्च संगतैः॥', 'sarvauṣadhirasaiś cāpi daivatair nabhasi sthitaiḥ
caturhir lokapālaiś ca sarvair devaiś ca saṃgataiḥ', null, 6116058),
('ramayana-6-116-59', 59, 'Yuddha Kanda, Sarga 116, Verse 59', 'छत्रं तस्य च जग्राह शत्रुघ्नः पाण्डुरं शुभम्।
श्वेतं च वालव्यजनं सुग्रीवो वानरेश्वरः।
अपरं चन्द्रसंकाशं राक्षसेन्द्रो विभीषणः॥', 'chatraṃ tasya ca jagrāha śatrughnaḥ pāṇḍuraṃ śubham
śvetaṃ ca vālavyajanaṃ sugrīvo vānareśvaraḥ
aparaṃ candrasaṃkāśaṃ rākṣasendro vibhīṣaṇaḥ', null, 6116059),
('ramayana-6-116-60', 60, 'Yuddha Kanda, Sarga 116, Verse 60', 'मालां ज्वलन्तीं वपुषा काञ्चनीं शतपुष्कराम्।
राघवाय ददौ वायुर्वासवेन प्रचोदितः॥', 'mālāṃ jvalantīṃ vapuṣā kāñcanīṃ śatapuṣkarām
rāghavāya dadau vāyur vāsavena pracoditaḥ', null, 6116060),
('ramayana-6-116-61', 61, 'Yuddha Kanda, Sarga 116, Verse 61', 'सर्वरत्नसमायुक्तं मणिरत्नविभूषितम्।
मुक्ताहारं नरेन्द्राय ददौ शक्रप्रचोदितः॥', 'sarvaratnasamāyuktaṃ maṇiratnavibhūṣitam
muktāhāraṃ narendrāya dadau śakrapracoditaḥ', null, 6116061),
('ramayana-6-116-62', 62, 'Yuddha Kanda, Sarga 116, Verse 62', 'प्रजगुर्देवगन्धर्वा ननृतुश्चाप्सरो गणाः।
अभिषेके तदर्हस्य तदा रामस्य धीमतः॥', 'prajagur devagandharvā nanṛtuś cāpsaro gaṇāḥ
abhiṣeke tad arhasya tadā rāmasya dhīmataḥ', null, 6116062),
('ramayana-6-116-63', 63, 'Yuddha Kanda, Sarga 116, Verse 63', 'भूमिः सस्यवती चैव फलवन्तश्च पादपाः।
गन्धवन्ति च पुष्पाणि बभूवू राघवोत्सवे॥', 'bhūmiḥ sasyavatī caiva phalavantaś ca pādapāḥ
gandhavanti ca puṣpāṇi babhūvū rāghavotsave', null, 6116063),
('ramayana-6-116-64', 64, 'Yuddha Kanda, Sarga 116, Verse 64', 'सहस्रशतमश्वानां धेनूनां च गवां तथा।
ददौ शतं वृषान्पूर्वं द्विजेभ्यो मनुजर्षभः॥', 'sahasraśatam aśvānāṃ dhenūnāṃ ca gavāṃ tathā
dadau śataṃ vṛṣān pūrvaṃ dvijebhyo manujarṣabhaḥ', null, 6116064),
('ramayana-6-116-65', 65, 'Yuddha Kanda, Sarga 116, Verse 65', 'त्रिंशत्कोटीर्हिरण्यस्य ब्राह्मणेभ्यो ददौ पुनः।
नानाभरणवस्त्राणि महार्हाणि च राघवः॥', 'triṃśatkoṭīr hiraṇyasya brāhmaṇebhyo dadau punaḥ
nānābharaṇavastrāṇi mahārhāṇi ca rāghavaḥ', null, 6116065),
('ramayana-6-116-66', 66, 'Yuddha Kanda, Sarga 116, Verse 66', 'अर्करश्मिप्रतीकाशां काञ्चनीं मणिविग्रहाम्।
सुग्रीवाय स्रजं दिव्यां प्रायच्छन्मनुजर्षभः॥', 'arkaraśmipratīkāśāṃ kāñcanīṃ maṇivigrahām
sugrīvāya srajaṃ divyāṃ prāyacchan manujarṣabhaḥ', null, 6116066),
('ramayana-6-116-67', 67, 'Yuddha Kanda, Sarga 116, Verse 67', 'वैदूर्यमणिचित्रे च वज्ररत्नविभूषिते।
वालिपुत्राय धृतिमानङ्गदायाङ्गदे ददौ॥', 'vaidūryamaṇicitre ca vajraratnavibhūṣite
vāliputrāya dhṛtimān aṅgadāyāṅgade dadau', null, 6116067),
('ramayana-6-116-68', 68, 'Yuddha Kanda, Sarga 116, Verse 68', 'मणिप्रवरजुष्टं च मुक्ताहारमनुत्तमम्।
सीतायै प्रददौ रामश्चन्द्ररश्मिसमप्रभम्॥', 'maṇipravarajuṣṭaṃ ca muktāhāram anuttamam
sītāyai pradadau rāmaś candraraśmisamaprabham', null, 6116068),
('ramayana-6-116-69', 69, 'Yuddha Kanda, Sarga 116, Verse 69', 'अरजे वाससी दिव्ये शुभान्याभरणानि च।
अवेक्षमाणा वैदेही प्रददौ वायुसूनवे॥', 'araje vāsasī divye śubhāny ābharaṇāni ca
avekṣamāṇā vaidehī pradadau vāyusūnave', null, 6116069),
('ramayana-6-116-70', 70, 'Yuddha Kanda, Sarga 116, Verse 70', 'अवमुच्यात्मनः कण्ठाद्धारं जनकनन्दिनी।
अवैक्षत हरीन्सर्वान्भर्तारं च मुहुर्मुहुः॥', 'avamucyātmanaḥ kaṇṭhād dhāraṃ janakanandinī
avaikṣata harīn sarvān bhartāraṃ ca muhur muhuḥ', null, 6116070),
('ramayana-6-116-71', 71, 'Yuddha Kanda, Sarga 116, Verse 71', 'तामिङ्गितज्ञः संप्रेक्ष्य बभाषे जनकात्मजाम्।
प्रदेहि सुभगे हारं यस्य तुष्टासि भामिनि॥', 'tām iṅgitajñaḥ saṃprekṣya babhāṣe janakātmajām
pradehi subhage hāraṃ yasya tuṣṭāsi bhāmini', null, 6116071),
('ramayana-6-116-72', 72, 'Yuddha Kanda, Sarga 116, Verse 72', 'पौरुषं विक्रमो बुद्धिर्यस्मिन्नेतानि नित्यदा।
ददौ सा वायुपुत्राय तं हारमसितेक्षणा॥', 'pauruṣaṃ vikramo buddhir yasminn etāni nityadā
dadau sā vāyuputrāya taṃ hāram asitekṣaṇā', null, 6116072),
('ramayana-6-116-73', 73, 'Yuddha Kanda, Sarga 116, Verse 73', 'हनूमांस्तेन हारेण शुशुभे वानरर्षभः।
चन्द्रांशुचयगौरेण श्वेताभ्रेण यथाचलः॥', 'hanūmāṃs tena hāreṇa śuśubhe vānararṣabhaḥ
candrāṃśucayagaureṇa śvetābhreṇa yathācalaḥ', null, 6116073),
('ramayana-6-116-74', 74, 'Yuddha Kanda, Sarga 116, Verse 74', 'ततो द्विविद मैन्दाभ्यां नीलाय च परंतपः।
सर्वान्कामगुणान्वीक्ष्य प्रददौ वसुधाधिपः॥', 'tato dvivida maindābhyāṃ nīlāya ca paraṃtapaḥ
sarvān kāmaguṇān vīkṣya pradadau vasudhādhipaḥ', null, 6116074),
('ramayana-6-116-75', 75, 'Yuddha Kanda, Sarga 116, Verse 75', 'सर्ववानरवृद्धाश्च ये चान्ये वानरेश्वराः।
वासोभिर्भूषणैश्चैव यथार्हं प्रतिपूजिताः॥', 'sarvavānaravṛddhāś ca ye cānye vānareśvarāḥ
vāsobhir bhūṣaṇaiś caiva yathārhaṃ pratipūjitāḥ', null, 6116075),
('ramayana-6-116-76', 76, 'Yuddha Kanda, Sarga 116, Verse 76', 'यथार्हं पूजिताः सर्वे कामै रत्नैश्च पुष्कलैर्।
प्रहृष्टमनसः सर्वे जग्मुरेव यथागतम्॥', 'yathārhaṃ pūjitāḥ sarve kāmai ratnaiś ca puṣkalair
prahṛṣṭamanasaḥ sarve jagmur eva yathāgatam', null, 6116076),
('ramayana-6-116-77', 77, 'Yuddha Kanda, Sarga 116, Verse 77', 'राघवः परमोदारः शशास परया मुदा।
उवाच लक्ष्मणं रामो धर्मज्ञं धर्मवत्सलः॥', 'rāghavaḥ paramodāraḥ śaśāsa parayā mudā
uvāca lakṣmaṇaṃ rāmo dharmajñaṃ dharmavatsalaḥ', null, 6116077),
('ramayana-6-116-78', 78, 'Yuddha Kanda, Sarga 116, Verse 78', 'आतिष्ठ धर्मज्ञ मया सहेमां गां पूर्वराजाध्युषितां बलेन।
तुल्यं मया त्वं पितृभिर्धृता या तां यौवराज्ये धुरमुद्वहस्व॥', 'ātiṣṭha dharmajña mayā sahemāṃ gāṃ pūrvarājādhyuṣitāṃ balena
tulyaṃ mayā tvaṃ pitṛbhir dhṛtā yā tāṃ yauvarājye dhuram udvahasva', null, 6116078),
('ramayana-6-116-79', 79, 'Yuddha Kanda, Sarga 116, Verse 79', 'सर्वात्मना पर्यनुनीयमानो यदा न सौमित्रिरुपैति योगम्।
नियुज्यमानो भुवि यौवराज्ये ततोऽभ्यषिञ्चद्भरतं महात्मा॥', 'sarvātmanā paryanunīyamāno yadā na saumitrir upaiti yogam
niyujyamāno bhuvi yauvarājye tato ''bhyaṣiñcad bharataṃ mahātmā', null, 6116079),
('ramayana-6-116-80', 80, 'Yuddha Kanda, Sarga 116, Verse 80', 'राघवश्चापि धर्मात्मा प्राप्य राज्यमनुत्तमम्।
ईजे बहुविधैर्यज्ञैः ससुहृद्भ्रातृबान्धवः॥', 'rāghavaś cāpi dharmātmā prāpya rājyam anuttamam
īje bahuvidhair yajñaiḥ sasuhṛdbhrātṛbāndhavaḥ', null, 6116080),
('ramayana-6-116-81', 81, 'Yuddha Kanda, Sarga 116, Verse 81', 'पौण्डरीकाश्वमेधाभ्यां वाजपेयेन चासकृत्।
अन्यैश्च विविधैर्यज्ञैरयजत्पार्थिवर्षभः॥', 'pauṇḍarīkāśvamedhābhyāṃ vājapeyena cāsakṛt
anyaiś ca vividhair yajñair ayajat pārthivarṣabhaḥ', null, 6116081),
('ramayana-6-116-82', 82, 'Yuddha Kanda, Sarga 116, Verse 82', 'राज्यं दशसहस्राणि प्राप्य वर्षाणि राघवः।
शताश्वमेधानाजह्रे सदश्वान्भूरिदक्षिणान्॥', 'rājyaṃ daśasahasrāṇi prāpya varṣāṇi rāghavaḥ
śatāśvamedhān ājahre sadaśvān bhūridakṣiṇān', null, 6116082),
('ramayana-6-116-83', 83, 'Yuddha Kanda, Sarga 116, Verse 83', 'आजानुलम्बिबाहुश्च महास्कन्धः प्रतापवान्।
लक्ष्मणानुचरो रामः पृथिवीमन्वपालयत्॥', 'ājānulambibāhuś ca mahāskandhaḥ pratāpavān
lakṣmaṇānucaro rāmaḥ pṛthivīm anvapālayat', null, 6116083),
('ramayana-6-116-84', 84, 'Yuddha Kanda, Sarga 116, Verse 84', 'न पर्यदेवन्विधवा न च व्यालकृतं भयम्।
न व्याधिजं भयं वापि रामे राज्यं प्रशासति॥', 'na paryadevan vidhavā na ca vyālakṛtaṃ bhayam
na vyādhijaṃ bhayaṃ vāpi rāme rājyaṃ praśāsati', null, 6116084),
('ramayana-6-116-85', 85, 'Yuddha Kanda, Sarga 116, Verse 85', 'निर्दस्युरभवल्लोको नानर्थः कं चिदस्पृशत्।
न च स्म वृद्धा बालानां प्रेतकार्याणि कुर्वते॥', 'nirdasyur abhaval loko nānarthaḥ kaṃ cid aspṛśat
na ca sma vṛddhā bālānāṃ pretakāryāṇi kurvate', null, 6116085),
('ramayana-6-116-86', 86, 'Yuddha Kanda, Sarga 116, Verse 86', 'सर्वं मुदितमेवासीत्सर्वो धर्मपरोऽभवत्।
राममेवानुपश्यन्तो नाभ्यहिंसन्परस्परम्॥', 'sarvaṃ muditam evāsīt sarvo dharmaparo ''bhavat
rāmam evānupaśyanto nābhyahiṃsan parasparam', null, 6116086),
('ramayana-6-116-87', 87, 'Yuddha Kanda, Sarga 116, Verse 87', 'आसन्वर्षसहस्राणि तथा पुत्रसहस्रिणः।
निरामया विशोकाश्च रामे राज्यं प्रशासति॥', 'āsan varṣasahasrāṇi tathā putrasahasriṇaḥ
nirāmayā viśokāś ca rāme rājyaṃ praśāsati', null, 6116087),
('ramayana-6-116-88', 88, 'Yuddha Kanda, Sarga 116, Verse 88', 'नित्यपुष्पा नित्यफलास्तरवः स्कन्धविस्तृताः।
कालवर्षी च पर्जन्यः सुखस्पर्शश्च मारुतः॥', 'nityapuṣpā nityaphalās taravaḥ skandhavistṛtāḥ
kālavarṣī ca parjanyaḥ sukhasparśaś ca mārutaḥ', null, 6116088),
('ramayana-6-116-89', 89, 'Yuddha Kanda, Sarga 116, Verse 89', 'स्वकर्मसु प्रवर्तन्ते तुष्ठाः स्वैरेव कर्मभिः।
आसन्प्रजा धर्मपरा रामे शासति नानृताः॥', 'svakarmasu pravartante tuṣṭhāḥ svair eva karmabhiḥ
āsan prajā dharmaparā rāme śāsati nānṛtāḥ', null, 6116089),
('ramayana-6-116-90', 90, 'Yuddha Kanda, Sarga 116, Verse 90', 'सर्वे लक्षणसंपन्नाः सर्वे धर्मपरायणाः।
दशवर्षसहस्राणि रामो राज्यमकारयत्॥', 'sarve lakṣaṇasaṃpannāḥ sarve dharmaparāyaṇāḥ
daśavarṣasahasrāṇi rāmo rājyam akārayat', null, 6116090)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);

