insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 1 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-1-1', 1, 'Uttara Kanda, Sarga 1, Verse 1', 'प्राप्तराज्यस्य रामस्य राक्षसानां वधे कृते।
आजग्मुरृषयः सर्वे राघवं प्रतिनन्दितुम्॥', 'prāptarājyasya rāmasya rākṣasānāṃ vadhe kṛte
ājagmur ṛṣayaḥ sarve rāghavaṃ pratinanditum', null, 7001001),
('ramayana-7-1-2', 2, 'Uttara Kanda, Sarga 1, Verse 2', 'कौशिकोऽथ यवक्रीतो रैभ्यश्च्यवन एव च।
कण्वो मेधातिथेः पुत्रः पूर्वस्यां दिशि ये श्रिताः॥', 'kauśiko ''tha yavakrīto raibhyaś cyavana eva ca
kaṇvo medhātitheḥ putraḥ pūrvasyāṃ diśi ye śritāḥ', null, 7001002),
('ramayana-7-1-3', 3, 'Uttara Kanda, Sarga 1, Verse 3', 'स्वस्त्यात्रेयश्च भगवान्नमुचिः प्रमुचुस्तथा।
आजग्मुस्ते सहागस्त्या ये श्रिता दक्षिणां दिशम्॥', 'svastyātreyaś ca bhagavān namuciḥ pramucus tathā
ājagmus te sahāgastyā ye śritā dakṣiṇāṃ diśam', null, 7001003),
('ramayana-7-1-4', 4, 'Uttara Kanda, Sarga 1, Verse 4', 'पृषद्गुः कवषो धौम्यो रौद्रेयश्च महानृषिः।
तेऽप्याजग्मुः सशिष्या वै ये श्रिताः पश्चिमां दिशम्॥', 'pṛṣadguḥ kavaṣo dhaumyo raudreyaś ca mahān ṛṣiḥ
te ''py ājagmuḥ saśiṣyā vai ye śritāḥ paścimāṃ diśam', null, 7001004),
('ramayana-7-1-5', 5, 'Uttara Kanda, Sarga 1, Verse 5', 'वसिष्ठः कश्यपोऽथात्रिर्विश्वामित्रोऽथ गौतमः।
जमदग्निर्भरद्वाजस्तेऽपि सप्तमहर्षयः॥', 'vasiṣṭhaḥ kaśyapo ''thātrir viśvāmitro ''tha gautamaḥ
jamadagnir bharadvājas te ''pi saptamaharṣayaḥ', null, 7001005),
('ramayana-7-1-6', 6, 'Uttara Kanda, Sarga 1, Verse 6', 'संप्राप्यैते महात्मानो राघवस्य निवेशनम्।
विष्ठिताः प्रतिहारार्थं हुताशनसमप्रभाः॥', 'saṃprāpyaite mahātmāno rāghavasya niveśanam
viṣṭhitāḥ pratihārārthaṃ hutāśanasamaprabhāḥ', null, 7001006),
('ramayana-7-1-7', 7, 'Uttara Kanda, Sarga 1, Verse 7', 'प्रतिहारस्ततस्तूर्णमगस्त्यवचनादथ।
समीपं राघवस्याशु प्रविवेश महात्मनः॥', 'pratihāras tatas tūrṇam agastyavacanād atha
samīpaṃ rāghavasyāśu praviveśa mahātmanaḥ', null, 7001007),
('ramayana-7-1-8', 8, 'Uttara Kanda, Sarga 1, Verse 8', 'स रामं दृश्य सहसा पूर्णचन्द्रसमद्युतिम्।
अगस्त्यं कथयामास संप्रातमृषिभिः सह॥', 'sa rāmaṃ dṛśya sahasā pūrṇacandrasamadyutim
agastyaṃ kathayām āsa saṃprātam ṛṣibhiḥ saha', null, 7001008),
('ramayana-7-1-9', 9, 'Uttara Kanda, Sarga 1, Verse 9', 'श्रुत्वा प्राप्तान्मुनींस्तांस्तु बालसूर्यसमप्रभान्।
तदोवाच नृपो द्वाःस्थं प्रवेशय यथासुखम्॥', 'śrutvā prāptān munīṃs tāṃs tu bālasūryasamaprabhān
tadovāca nṛpo dvāḥsthaṃ praveśaya yathāsukham', null, 7001009),
('ramayana-7-1-10', 10, 'Uttara Kanda, Sarga 1, Verse 10', 'दृष्ट्वा प्राप्तान्मुनींस्तांस्तु प्रत्युत्थाय कृताञ्जलिः।
रामोऽभिवाद्य प्रयत आसनान्यादिदेश ह॥', 'dṛṣṭvā prāptān munīṃs tāṃs tu pratyutthāya kṛtāñjaliḥ
rāmo ''bhivādya prayata āsanāny ādideśa ha', null, 7001010),
('ramayana-7-1-11', 11, 'Uttara Kanda, Sarga 1, Verse 11', 'तेषु काञ्चनचित्रेषु स्वास्तीर्णेषु सुखेषु च।
यथार्हमुपविष्टास्ते आसनेष्वृषिपुंगवाः॥', 'teṣu kāñcanacitreṣu svāstīrṇeṣu sukheṣu ca
yathārham upaviṣṭās te āsaneṣv ṛṣipuṃgavāḥ', null, 7001011),
('ramayana-7-1-12', 12, 'Uttara Kanda, Sarga 1, Verse 12', 'रामेण कुशलं पृष्टाः सशिष्याः सपुरोगमाः।
महर्षयो वेदविदो रामं वचनमब्रुवन्॥', 'rāmeṇa kuśalaṃ pṛṣṭāḥ saśiṣyāḥ sapurogamāḥ
maharṣayo vedavido rāmaṃ vacanam abruvan', null, 7001012),
('ramayana-7-1-13', 13, 'Uttara Kanda, Sarga 1, Verse 13', 'कुशलं नो महाबाहो सर्वत्र रघुनन्दन।
त्वां तु दिष्ट्या कुशलिनं पश्यामो हतशात्रवम्॥', 'kuśalaṃ no mahābāho sarvatra raghunandana
tvāṃ tu diṣṭyā kuśalinaṃ paśyāmo hataśātravam', null, 7001013),
('ramayana-7-1-14', 14, 'Uttara Kanda, Sarga 1, Verse 14', 'न हि भारः स ते राम रावणो राक्षसेश्वरः।
सधनुस्त्वं हि लोकांस्त्रीन्विजयेथा न संशयः॥', 'na hi bhāraḥ sa te rāma rāvaṇo rākṣaseśvaraḥ
sadhanus tvaṃ hi lokāṃs trīn vijayethā na saṃśayaḥ', null, 7001014),
('ramayana-7-1-15', 15, 'Uttara Kanda, Sarga 1, Verse 15', 'दिष्ट्या त्वया हतो राम रावणः पुत्रपौत्रवान्।
दिष्ट्या विजयिनं त्वाद्य पश्यामः सह भार्यया॥', 'diṣṭyā tvayā hato rāma rāvaṇaḥ putrapautravān
diṣṭyā vijayinaṃ tvādya paśyāmaḥ saha bhāryayā', null, 7001015),
('ramayana-7-1-16', 16, 'Uttara Kanda, Sarga 1, Verse 16', 'दिष्ट्या प्रहस्तो विकटो विरूपाक्षो महोदरः।
अकम्पनश्च दुर्धर्षो निहतास्ते निशाचराः॥', 'diṣṭyā prahasto vikaṭo virūpākṣo mahodaraḥ
akampanaś ca durdharṣo nihatās te niśācarāḥ', null, 7001016),
('ramayana-7-1-17', 17, 'Uttara Kanda, Sarga 1, Verse 17', 'यस्य प्रमाणाद्विपुलं प्रमाणं नेह विद्यते।
दिष्ट्या ते समरे राम कुम्भकर्णो निपातितः॥', 'yasya pramāṇād vipulaṃ pramāṇaṃ neha vidyate
diṣṭyā te samare rāma kumbhakarṇo nipātitaḥ', null, 7001017),
('ramayana-7-1-18', 18, 'Uttara Kanda, Sarga 1, Verse 18', 'दिष्ट्या त्वं राक्षसेन्द्रेण द्वन्द्वयुद्धमुपागतः।
देवतानामवध्येन विजयं प्राप्तवानसि॥', 'diṣṭyā tvaṃ rākṣasendreṇa dvandvayuddham upāgataḥ
devatānām avadhyena vijayaṃ prāptavān asi', null, 7001018),
('ramayana-7-1-19', 19, 'Uttara Kanda, Sarga 1, Verse 19', 'संख्ये तस्य न किं चित्तु रावणस्य पराभवः।
द्वन्द्वयुद्धमनुप्राप्तो दिष्ट्या ते रावणिर्हतः॥', 'saṃkhye tasya na kiṃ cit tu rāvaṇasya parābhavaḥ
dvandvayuddham anuprāpto diṣṭyā te rāvaṇir hataḥ', null, 7001019),
('ramayana-7-1-20', 20, 'Uttara Kanda, Sarga 1, Verse 20', 'दिष्ट्या तस्य महाबाहो कालस्येवाभिधावतः।
मुक्तः सुररिपोर्वीर प्राप्तश्च विजयस्त्वया॥', 'diṣṭyā tasya mahābāho kālasyevābhidhāvataḥ
muktaḥ suraripor vīra prāptaś ca vijayas tvayā', null, 7001020),
('ramayana-7-1-21', 21, 'Uttara Kanda, Sarga 1, Verse 21', 'विस्मयस्त्वेष नः सौम्य संश्रुत्येन्द्रजितं हतम्।
अवध्यः सर्वभूतानां महामायाधरो युधि॥', 'vismayas tv eṣa naḥ saumya saṃśrutyendrajitaṃ hatam
avadhyaḥ sarvabhūtānāṃ mahāmāyādharo yudhi', null, 7001021),
('ramayana-7-1-22', 22, 'Uttara Kanda, Sarga 1, Verse 22', 'दत्त्वा पुण्यामिमां वीर सौम्यामभयदक्षिणाम्।
दिष्ट्या वर्धसि काकुत्स्थ जयेनामित्रकर्शन॥', 'dattvā puṇyām imāṃ vīra saumyām abhayadakṣiṇām
diṣṭyā vardhasi kākutstha jayenāmitrakarśana', null, 7001022),
('ramayana-7-1-23', 23, 'Uttara Kanda, Sarga 1, Verse 23', 'श्रुत्वा तु वचनं तेषामृषीणां भावितात्मनाम्।
विस्मयं परमं गत्वा रामः प्राञ्जलिरब्रवीत्॥', 'śrutvā tu vacanaṃ teṣām ṛṣīṇāṃ bhāvitātmanām
vismayaṃ paramaṃ gatvā rāmaḥ prāñjalir abravīt', null, 7001023),
('ramayana-7-1-24', 24, 'Uttara Kanda, Sarga 1, Verse 24', 'भवन्तः कुम्भकर्णं च रावणं च निशाचरम्।
अतिक्रम्य महावीर्यौ किं प्रशंसथ रावणिम्॥', 'bhavantaḥ kumbhakarṇaṃ ca rāvaṇaṃ ca niśācaram
atikramya mahāvīryau kiṃ praśaṃsatha rāvaṇim', null, 7001024),
('ramayana-7-1-25', 25, 'Uttara Kanda, Sarga 1, Verse 25', 'महोदरं प्रहस्तं च विरूपाक्षं च राक्षसं।
अतिक्रम्य महावीर्यान्किं प्रशंसथ रावणिम्॥', 'mahodaraṃ prahastaṃ ca virūpākṣaṃ ca rākṣasaṃ
atikramya mahāvīryān kiṃ praśaṃsatha rāvaṇim', null, 7001025),
('ramayana-7-1-26', 26, 'Uttara Kanda, Sarga 1, Verse 26', 'कीदृशो वै प्रभावोऽस्य किं बलं कः पराक्रमः।
केन वा कारणेनैष रावणादतिरिच्यते॥', 'kīdṛśo vai prabhāvo ''sya kiṃ balaṃ kaḥ parākramaḥ
kena vā kāraṇenaiṣa rāvaṇād atiricyate', null, 7001026),
('ramayana-7-1-27', 27, 'Uttara Kanda, Sarga 1, Verse 27', 'शक्यं यदि मया श्रोतुं न खल्वाज्ञापयामि वः।
यदि गुह्यं न चेद्वक्तुं श्रोतुमिच्छामि कथ्यताम्।
कथं शक्रो जितस्तेन कथं लब्धवरश्च सः॥', 'śakyaṃ yadi mayā śrotuṃ na khalv ājñāpayāmi vaḥ
yadi guhyaṃ na ced vaktuṃ śrotum icchāmi kathyatām
kathaṃ śakro jitas tena kathaṃ labdhavaraś ca saḥ', null, 7001027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 2 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-2-1', 1, 'Uttara Kanda, Sarga 2, Verse 1', 'तस्य तद्वचनं श्रुत्वा राघवस्य महात्मनः।
कुम्भयोनिर्महातेजा वाक्यमेतदुवाच ह॥', 'tasya tad vacanaṃ śrutvā rāghavasya mahātmanaḥ
kumbhayonir mahātejā vākyam etad uvāca ha', null, 7002001),
('ramayana-7-2-2', 2, 'Uttara Kanda, Sarga 2, Verse 2', 'शृणु राजन्यथावृत्तं यस्य तेजोबलं महत्।
जघान च रिपून्युद्धे यथावध्यश्च शत्रुभिः॥', 'śṛṇu rājan yathāvṛttaṃ yasya tejobalaṃ mahat
jaghāna ca ripūn yuddhe yathāvadhyaś ca śatrubhiḥ', null, 7002002),
('ramayana-7-2-3', 3, 'Uttara Kanda, Sarga 2, Verse 3', 'अहं ते रावणस्येदं कुलं जन्म च राघव।
वरप्रदानं च तथा तस्मै दत्तं ब्रवीमि ते॥', 'ahaṃ te rāvaṇasyedaṃ kulaṃ janma ca rāghava
varapradānaṃ ca tathā tasmai dattaṃ bravīmi te', null, 7002003),
('ramayana-7-2-4', 4, 'Uttara Kanda, Sarga 2, Verse 4', 'पुरा कृतयुगे राम प्रजापतिसुतः प्रभुः।
पुलस्त्यो नाम ब्रह्मर्षिः साक्षादिव पितामहः॥', 'purā kṛtayuge rāma prajāpatisutaḥ prabhuḥ
pulastyo nāma brahmarṣiḥ sākṣād iva pitāmahaḥ', null, 7002004),
('ramayana-7-2-5', 5, 'Uttara Kanda, Sarga 2, Verse 5', 'नानुकीर्त्या गुणास्तस्य धर्मतः शीलतस्तथा।
प्रजापतेः पुत्र इति वक्तुं शक्यं हि नामतः॥', 'nānukīrtyā guṇās tasya dharmataḥ śīlatas tathā
prajāpateḥ putra iti vaktuṃ śakyaṃ hi nāmataḥ', null, 7002005),
('ramayana-7-2-6', 6, 'Uttara Kanda, Sarga 2, Verse 6', 'स तु धर्मप्रसङ्गेन मेरोः पार्श्वे महागिरेः।
तृणबिन्द्वाश्रमं गत्वा न्यवसन्मुनिपुंगवः॥', 'sa tu dharmaprasaṅgena meroḥ pārśve mahāgireḥ
tṛṇabindvāśramaṃ gatvā nyavasan munipuṃgavaḥ', null, 7002006),
('ramayana-7-2-7', 7, 'Uttara Kanda, Sarga 2, Verse 7', 'तपस्तेपे स धर्मात्मा स्वाध्यायनियतेन्द्रियः।
गत्वाश्रमपदं तस्य विघ्नं कुर्वन्ति कन्यकाः॥', 'tapas tepe sa dharmātmā svādhyāyaniyatendriyaḥ
gatvāśramapadaṃ tasya vighnaṃ kurvanti kanyakāḥ', null, 7002007),
('ramayana-7-2-8', 8, 'Uttara Kanda, Sarga 2, Verse 8', 'देवपन्नगकन्याश्च राजर्षितनयाश्च याः।
क्रीडन्त्योऽप्सरसश्चैव तं देशमुपपेदिरे॥', 'devapannagakanyāś ca rājarṣitanayāś ca yāḥ
krīḍantyo ''psarasaś caiva taṃ deśam upapedire', null, 7002008),
('ramayana-7-2-9', 9, 'Uttara Kanda, Sarga 2, Verse 9', 'सर्वर्तुषूपभोग्यत्वाद्रम्यत्वात्काननस्य च।
नित्यशस्तास्तु तं देशं गत्वा क्रीडन्ति कन्यकाः॥', 'sarvartuṣūpabhogyatvād ramyatvāt kānanasya ca
nityaśas tās tu taṃ deśaṃ gatvā krīḍanti kanyakāḥ', null, 7002009),
('ramayana-7-2-10', 10, 'Uttara Kanda, Sarga 2, Verse 10', 'अथ रुष्टो महातेजा व्याजहार महामुनिः।
या मे दर्शनमागच्छेत्सा गर्भं धारयिष्यति॥', 'atha ruṣṭo mahātejā vyājahāra mahāmuniḥ
yā me darśanam āgacchet sā garbhaṃ dhārayiṣyati', null, 7002010),
('ramayana-7-2-11', 11, 'Uttara Kanda, Sarga 2, Verse 11', 'तास्तु सर्वाः प्रतिगताः श्रुत्वा वाक्यं महात्मनः।
ब्रह्मशापभयाद्भीतास्तं देशं नोपचक्रमुः॥', 'tās tu sarvāḥ pratigatāḥ śrutvā vākyaṃ mahātmanaḥ
brahmaśāpabhayād bhītās taṃ deśaṃ nopacakramuḥ', null, 7002011),
('ramayana-7-2-12', 12, 'Uttara Kanda, Sarga 2, Verse 12', 'तृणबिन्दोस्तु राजर्षेस्तनया न शृणोति तत्।
गत्वाश्रमपदं तस्य विचचार सुनिर्भया॥', 'tṛṇabindos tu rājarṣes tanayā na śṛṇoti tat
gatvāśramapadaṃ tasya vicacāra sunirbhayā', null, 7002012),
('ramayana-7-2-13', 13, 'Uttara Kanda, Sarga 2, Verse 13', 'तस्मिन्नेव तु काले स प्राजापत्यो महानृषिः।
स्वाध्यायमकरोत्तत्र तपसा द्योतितप्रभः॥', 'tasminn eva tu kāle sa prājāpatyo mahān ṛṣiḥ
svādhyāyam akarot tatra tapasā dyotitaprabhaḥ', null, 7002013),
('ramayana-7-2-14', 14, 'Uttara Kanda, Sarga 2, Verse 14', 'सा तु वेदध्वनिं श्रुत्वा दृष्ट्वा चैव तपोधनम्।
अभवत्पाण्डुदेहा सा सुव्यञ्जितशरीरजा॥', 'sā tu vedadhvaniṃ śrutvā dṛṣṭvā caiva tapodhanam
abhavat pāṇḍudehā sā suvyañjitaśarīrajā', null, 7002014),
('ramayana-7-2-15', 15, 'Uttara Kanda, Sarga 2, Verse 15', 'दृष्ट्वा परमसंविग्ना सा तु तद्रूपमात्मनः।
इदं मे किं न्विति ज्ञात्वा पितुर्गत्वाग्रतः स्थिता॥', 'dṛṣṭvā paramasaṃvignā sā tu tadrūpam ātmanaḥ
idaṃ me kiṃ nv iti jñātvā pitur gatvāgrataḥ sthitā', null, 7002015),
('ramayana-7-2-16', 16, 'Uttara Kanda, Sarga 2, Verse 16', 'तां तु दृष्ट्वा तथा भूतां तृणबिन्दुरथाब्रवीत्।
किं त्वमेतत्त्वसदृशं धारयस्यात्मनो वपुः॥', 'tāṃ tu dṛṣṭvā tathā bhūtāṃ tṛṇabindur athābravīt
kiṃ tvam etat tv asadṛśaṃ dhārayasy ātmano vapuḥ', null, 7002016),
('ramayana-7-2-17', 17, 'Uttara Kanda, Sarga 2, Verse 17', 'सा तु कृत्वाञ्जलिं दीना कन्योवाच तपोधनम्।
न जाने कारणं तात येन मे रूपमीदृशम्॥', 'sā tu kṛtvāñjaliṃ dīnā kanyovāca tapodhanam
na jāne kāraṇaṃ tāta yena me rūpam īdṛśam', null, 7002017),
('ramayana-7-2-18', 18, 'Uttara Kanda, Sarga 2, Verse 18', 'किं तु पूर्वं गतास्म्येका महर्षेर्भावितात्मनः।
पुलस्त्यस्याश्रमं दिव्यमन्वेष्टुं स्वसखीजनम्॥', 'kiṃ tu pūrvaṃ gatāsmy ekā maharṣer bhāvitātmanaḥ
pulastyasyāśramaṃ divyam anveṣṭuṃ svasakhījanam', null, 7002018),
('ramayana-7-2-19', 19, 'Uttara Kanda, Sarga 2, Verse 19', 'न च पश्याम्यहं तत्र कां चिदप्यागतां सखीम्।
रूपस्य तु विपर्यासं दृष्ट्वा चाहमिहागता॥', 'na ca paśyāmy ahaṃ tatra kāṃ cid apy āgatāṃ sakhīm
rūpasya tu viparyāsaṃ dṛṣṭvā cāham ihāgatā', null, 7002019),
('ramayana-7-2-20', 20, 'Uttara Kanda, Sarga 2, Verse 20', 'तृणबिन्दुस्तु राजर्षिस्तपसा द्योतितप्रभः।
ध्यानं विवेश तच्चापि अपश्यदृषिकर्मजम्॥', 'tṛṇabindus tu rājarṣis tapasā dyotitaprabhaḥ
dhyānaṃ viveśa tac cāpi apaśyad ṛṣikarmajam', null, 7002020),
('ramayana-7-2-21', 21, 'Uttara Kanda, Sarga 2, Verse 21', 'स तु विज्ञाय तं शापं महर्षेर्भावितात्मनः।
गृहीत्वा तनयां गत्वा पुलस्त्यमिदमब्रवीत्॥', 'sa tu vijñāya taṃ śāpaṃ maharṣer bhāvitātmanaḥ
gṛhītvā tanayāṃ gatvā pulastyam idam abravīt', null, 7002021),
('ramayana-7-2-22', 22, 'Uttara Kanda, Sarga 2, Verse 22', 'भगवंस्तनयां मे त्वं गुणैः स्वैरेव भूषिताम्।
भिक्षां प्रतिगृहाणेमां महर्षे स्वयमुद्यताम्॥', 'bhagavaṃs tanayāṃ me tvaṃ guṇaiḥ svair eva bhūṣitām
bhikṣāṃ pratigṛhāṇemāṃ maharṣe svayam udyatām', null, 7002022),
('ramayana-7-2-23', 23, 'Uttara Kanda, Sarga 2, Verse 23', 'तपश्चरणयुक्तस्य श्राम्यमाणेन्द्रियस्य ते।
शुश्रूषातत्परा नित्यं भविष्यति न संशयः॥', 'tapaścaraṇayuktasya śrāmyamāṇendriyasya te
śuśrūṣātatparā nityaṃ bhaviṣyati na saṃśayaḥ', null, 7002023),
('ramayana-7-2-24', 24, 'Uttara Kanda, Sarga 2, Verse 24', 'तं ब्रुवाणं तु तद्वाक्यं राजर्षिं धार्मिकं तदा।
जिघृक्षुरब्रवीत्कन्यां बाढमित्येव स द्विजः॥', 'taṃ bruvāṇaṃ tu tadvākyaṃ rājarṣiṃ dhārmikaṃ tadā
jighṛkṣur abravīt kanyāṃ bāḍham ity eva sa dvijaḥ', null, 7002024),
('ramayana-7-2-25', 25, 'Uttara Kanda, Sarga 2, Verse 25', 'दत्त्वा तु स गतो राजा स्वमाश्रमपदं तदा।
सापि तत्रावसत्कन्या तोषयन्ती पतिं गुणैः।
प्रीतः स तु महातेजा वाक्यमेतदुवाच ह॥', 'dattvā tu sa gato rājā svam āśramapadaṃ tadā
sāpi tatrāvasat kanyā toṣayantī patiṃ guṇaiḥ
prītaḥ sa tu mahātejā vākyam etad uvāca ha', null, 7002025),
('ramayana-7-2-26', 26, 'Uttara Kanda, Sarga 2, Verse 26', 'परितुष्टोऽस्मि भद्रं ते गुणानां संपदा भृशम्।
तस्मात्ते विरमाम्यद्य पुत्रमात्मसमं गुणैः।
उभयोर्वंशकर्तारं पौलस्त्य इति विश्रुतम्॥', 'parituṣṭo ''smi bhadraṃ te guṇānāṃ saṃpadā bhṛśam
tasmāt te viramāmy adya putram ātmasamaṃ guṇaiḥ
ubhayor vaṃśakartāraṃ paulastya iti viśrutam', null, 7002026),
('ramayana-7-2-27', 27, 'Uttara Kanda, Sarga 2, Verse 27', 'यस्मात्तु विश्रुतो वेदस्त्वयेहाभ्यस्यतो मम।
तस्मात्स विश्रवा नाम भविष्यति न संशयः॥', 'yasmāt tu viśruto vedas tvayehābhyasyato mama
tasmāt sa viśravā nāma bhaviṣyati na saṃśayaḥ', null, 7002027),
('ramayana-7-2-28', 28, 'Uttara Kanda, Sarga 2, Verse 28', 'एवमुक्ता तु सा कन्या प्रहृष्टेनान्तरात्मना।
अचिरेणैव कालेन सूता विश्रवसं सुतम्॥', 'evam uktā tu sā kanyā prahṛṣṭenāntarātmanā
acireṇaiva kālena sūtā viśravasaṃ sutam', null, 7002028),
('ramayana-7-2-29', 29, 'Uttara Kanda, Sarga 2, Verse 29', 'स तु लोकत्रये ख्यातः शौचधर्मसमन्वितः।
पितेव तपसा युक्तो विश्रवा मुनिपुंगवः॥', 'sa tu lokatraye khyātaḥ śaucadharmasamanvitaḥ
piteva tapasā yukto viśravā munipuṃgavaḥ', null, 7002029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 3 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-3-1', 1, 'Uttara Kanda, Sarga 3, Verse 1', 'अथ पुत्रः पुलस्त्यस्य विश्रवा मुनिपुंगवः।
अचिरेणैव कालेन पितेव तपसि स्थितः॥', 'atha putraḥ pulastyasya viśravā munipuṃgavaḥ
acireṇaiva kālena piteva tapasi sthitaḥ', null, 7003001),
('ramayana-7-3-2', 2, 'Uttara Kanda, Sarga 3, Verse 2', 'सत्यवाञ्शीलवान्दक्षः स्वाध्यायनिरतः शुचिः।
सर्वभोगेष्वसंसक्तो नित्यं धर्मपरायणः॥', 'satyavāñ śīlavān dakṣaḥ svādhyāyanirataḥ śuciḥ
sarvabhogeṣv asaṃsakto nityaṃ dharmaparāyaṇaḥ', null, 7003002),
('ramayana-7-3-3', 3, 'Uttara Kanda, Sarga 3, Verse 3', 'ज्ञात्वा तस्य तु तद्वृत्तं भरद्वाजो महानृषिः।
ददौ विश्रवसे भार्यां स्वां सुतां देववर्णिनीम्॥', 'jñātvā tasya tu tadvṛttaṃ bharadvājo mahān ṛṣiḥ
dadau viśravase bhāryāṃ svāṃ sutāṃ devavarṇinīm', null, 7003003),
('ramayana-7-3-4', 4, 'Uttara Kanda, Sarga 3, Verse 4', 'प्रतिगृह्य तु धर्मेण भरद्वाजसुतां तदा।
मुदा परमया युक्तो विश्रवा मुनिपुंगवः॥', 'pratigṛhya tu dharmeṇa bharadvājasutāṃ tadā
mudā paramayā yukto viśravā munipuṃgavaḥ', null, 7003004),
('ramayana-7-3-5', 5, 'Uttara Kanda, Sarga 3, Verse 5', 'स तस्यां वीर्यसंपन्नमपत्यं परमाद्भुतम्।
जनयामास धर्मात्मा सर्वैर्ब्रह्मगुणैर्युतम्॥', 'sa tasyāṃ vīryasaṃpannam apatyaṃ paramādbhutam
janayām āsa dharmātmā sarvair brahmaguṇair yutam', null, 7003005),
('ramayana-7-3-6', 6, 'Uttara Kanda, Sarga 3, Verse 6', 'तस्मिञ्जाते तु संहृष्टः स बभूव पितामहः।
नाम चास्याकरोत्प्रीतः सार्धं देवर्षिभिस्तदा॥', 'tasmiñ jāte tu saṃhṛṣṭaḥ sa babhūva pitāmahaḥ
nāma cāsyākarot prītaḥ sārdhaṃ devarṣibhis tadā', null, 7003006),
('ramayana-7-3-7', 7, 'Uttara Kanda, Sarga 3, Verse 7', 'यस्माद्विश्रवसोऽपत्यं सादृश्याद्विश्रवा इव।
तस्माद्वैश्रवणो नाम भविष्यत्येष विश्रुतः॥', 'yasmād viśravaso ''patyaṃ sādṛśyād viśravā iva
tasmād vaiśravaṇo nāma bhaviṣyaty eṣa viśrutaḥ', null, 7003007),
('ramayana-7-3-8', 8, 'Uttara Kanda, Sarga 3, Verse 8', 'स तु वैश्रवणस्तत्र तपोवनगतस्तदा।
अवर्धत महातेजा हुताहुतिरिवानलः॥', 'sa tu vaiśravaṇas tatra tapovanagatas tadā
avardhata mahātejā hutāhutir ivānalaḥ', null, 7003008),
('ramayana-7-3-9', 9, 'Uttara Kanda, Sarga 3, Verse 9', 'तस्याश्रमपदस्थस्य बुद्धिर्जज्ञे महात्मनः।
चरिष्ये नियतो धर्मं धर्मो हि परमा गतिः॥', 'tasyāśramapadasthasya buddhir jajñe mahātmanaḥ
cariṣye niyato dharmaṃ dharmo hi paramā gatiḥ', null, 7003009),
('ramayana-7-3-10', 10, 'Uttara Kanda, Sarga 3, Verse 10', 'स तु वर्षसहस्राणि तपस्तप्त्वा महावने।
पूर्णे वर्षसहस्रे तु तं तं विधिमवर्तत॥', 'sa tu varṣasahasrāṇi tapas taptvā mahāvane
pūrṇe varṣasahasre tu taṃ taṃ vidhim avartata', null, 7003010),
('ramayana-7-3-11', 11, 'Uttara Kanda, Sarga 3, Verse 11', 'जलाशी मारुताहारो निराहारस्तथैव च।
एवं वर्षसहस्राणि जग्मुस्तान्येव वर्षवत्॥', 'jalāśī mārutāhāro nirāhāras tathaiva ca
evaṃ varṣasahasrāṇi jagmus tāny eva varṣavat', null, 7003011),
('ramayana-7-3-12', 12, 'Uttara Kanda, Sarga 3, Verse 12', 'अथ प्रीतो महातेजाः सेन्द्रैः सुरगणैः सह।
गत्वा तस्याश्रमपदं ब्रह्मेदं वाक्यमब्रवीत्॥', 'atha prīto mahātejāḥ sendraiḥ suragaṇaiḥ saha
gatvā tasyāśramapadaṃ brahmedaṃ vākyam abravīt', null, 7003012),
('ramayana-7-3-13', 13, 'Uttara Kanda, Sarga 3, Verse 13', 'परितुष्टोऽस्मि ते वत्स कर्मणानेन सुव्रत।
वरं वृणीष्व भद्रं ते वरार्हस्त्वं हि मे मतः॥', 'parituṣṭo ''smi te vatsa karmaṇānena suvrata
varaṃ vṛṇīṣva bhadraṃ te varārhas tvaṃ hi me mataḥ', null, 7003013),
('ramayana-7-3-14', 14, 'Uttara Kanda, Sarga 3, Verse 14', 'अथाब्रवीद्वैश्रवणः पितामहमुपस्थितम्।
भगवंल्लोकपालत्वमिच्छेयं वित्तरक्षणम्॥', 'athābravīd vaiśravaṇaḥ pitāmaham upasthitam
bhagavaṃl lokapālatvam iccheyaṃ vittarakṣaṇam', null, 7003014),
('ramayana-7-3-15', 15, 'Uttara Kanda, Sarga 3, Verse 15', 'ततोऽब्रवीद्वैश्रवणं परितुष्टेन चेतसा।
ब्रह्मा सुरगणैः सार्धं बाढमित्येव हृष्टवत्॥', 'tato ''bravīd vaiśravaṇaṃ parituṣṭena cetasā
brahmā suragaṇaiḥ sārdhaṃ bāḍham ity eva hṛṣṭavat', null, 7003015),
('ramayana-7-3-16', 16, 'Uttara Kanda, Sarga 3, Verse 16', 'अहं हि लोकपालानां चतुर्थं स्रष्टुमुद्यतः।
यमेन्द्रवरुणानां हि पदं यत्तव चेप्सितम्॥', 'ahaṃ hi lokapālānāṃ caturthaṃ sraṣṭum udyataḥ
yamendravaruṇānāṃ hi padaṃ yat tava cepsitam', null, 7003016),
('ramayana-7-3-17', 17, 'Uttara Kanda, Sarga 3, Verse 17', 'तत्कृतं गच्छ धर्मज्ञ धनेशत्वमवाप्नुहि।
यमेन्द्रवरुणानां हि चतुर्थोऽद्य भविष्यसि॥', 'tatkṛtaṃ gaccha dharmajña dhaneśatvam avāpnuhi
yamendravaruṇānāṃ hi caturtho ''dya bhaviṣyasi', null, 7003017),
('ramayana-7-3-18', 18, 'Uttara Kanda, Sarga 3, Verse 18', 'एतच्च पुष्पकं नाम विमानं सूर्यसंनिभम्।
प्रतिगृह्णीष्व यानार्थं त्रिदशैः समतां व्रज॥', 'etac ca puṣpakaṃ nāma vimānaṃ sūryasaṃnibham
pratigṛhṇīṣva yānārthaṃ tridaśaiḥ samatāṃ vraja', null, 7003018),
('ramayana-7-3-19', 19, 'Uttara Kanda, Sarga 3, Verse 19', 'स्वस्ति तेऽस्तु गमिष्यामः सर्व एव यथागतम्।
कृतकृत्या वयं तात दत्त्वा तव महावरम्॥', 'svasti te ''stu gamiṣyāmaḥ sarva eva yathāgatam
kṛtakṛtyā vayaṃ tāta dattvā tava mahāvaram', null, 7003019),
('ramayana-7-3-20', 20, 'Uttara Kanda, Sarga 3, Verse 20', 'गतेषु ब्रह्मपूर्वेषु देवेष्वथ नभस्तलम्।
धनेशः पितरं प्राह विनयात्प्रणतो वचः॥', 'gateṣu brahmapūrveṣu deveṣv atha nabhastalam
dhaneśaḥ pitaraṃ prāha vinayāt praṇato vacaḥ', null, 7003020),
('ramayana-7-3-21', 21, 'Uttara Kanda, Sarga 3, Verse 21', 'भगवंल्लब्धवानस्मि वरं कमलयोनितः।
निवासं न तु मे देवो विदधे स प्रजापतिः॥', 'bhagavaṃl labdhavān asmi varaṃ kamalayonitaḥ
nivāsaṃ na tu me devo vidadhe sa prajāpatiḥ', null, 7003021),
('ramayana-7-3-22', 22, 'Uttara Kanda, Sarga 3, Verse 22', 'तत्पश्य भगवन्कं चिद्देशं वासाय नः प्रभो।
न च पीडा भवेद्यत्र प्राणिनो यस्य कस्य चित्॥', 'tat paśya bhagavan kaṃ cid deśaṃ vāsāya naḥ prabho
na ca pīḍā bhaved yatra prāṇino yasya kasya cit', null, 7003022),
('ramayana-7-3-23', 23, 'Uttara Kanda, Sarga 3, Verse 23', 'एवमुक्तस्तु पुत्रेण विश्रवा मुनिपुंगवः।
वचनं प्राह धर्मज्ञ श्रूयतामिति धर्मवित्॥', 'evam uktas tu putreṇa viśravā munipuṃgavaḥ
vacanaṃ prāha dharmajña śrūyatām iti dharmavit', null, 7003023),
('ramayana-7-3-24', 24, 'Uttara Kanda, Sarga 3, Verse 24', 'लङ्का नाम पुरी रम्या निर्मिता विश्वकर्मणा।
राक्षसानां निवासार्थं यथेन्द्रस्यामरावती॥', 'laṅkā nāma purī ramyā nirmitā viśvakarmaṇā
rākṣasānāṃ nivāsārthaṃ yathendrasyāmarāvatī', null, 7003024),
('ramayana-7-3-25', 25, 'Uttara Kanda, Sarga 3, Verse 25', 'रमणीया पुरी सा हि रुक्मवैदूर्यतोरणा।
राक्षसैः सा परित्यक्ता पुरा विष्णुभयार्दितैः।
शून्या रक्षोगणैः सर्वै रसातलतलं गतैः॥', 'ramaṇīyā purī sā hi rukmavaidūryatoraṇā
rākṣasaiḥ sā parityaktā purā viṣṇubhayārditaiḥ
śūnyā rakṣogaṇaiḥ sarvai rasātalatalaṃ gataiḥ', null, 7003025),
('ramayana-7-3-26', 26, 'Uttara Kanda, Sarga 3, Verse 26', 'स त्वं तत्र निवासाय रोचयस्व मतिं स्वकाम्।
निर्दोषस्तत्र ते वासो न च बाधास्ति कस्य चित्॥', 'sa tvaṃ tatra nivāsāya rocayasva matiṃ svakām
nirdoṣas tatra te vāso na ca bādhāsti kasya cit', null, 7003026),
('ramayana-7-3-27', 27, 'Uttara Kanda, Sarga 3, Verse 27', 'एतच्छ्रुत्वा तु धर्मात्मा धर्मिष्ठं वचनं पितुः।
निवेशयामास तदा लङ्कां पर्वतमूर्धनि॥', 'etac chrutvā tu dharmātmā dharmiṣṭhaṃ vacanaṃ pituḥ
niveśayām āsa tadā laṅkāṃ parvatamūrdhani', null, 7003027),
('ramayana-7-3-28', 28, 'Uttara Kanda, Sarga 3, Verse 28', 'नैरृतानां सहस्रैस्तु हृष्टैः प्रमुदितैः सदा।
अचिरेणैककालेन संपूर्णा तस्य शासनात्॥', 'nairṛtānāṃ sahasrais tu hṛṣṭaiḥ pramuditaiḥ sadā
acireṇaikakālena saṃpūrṇā tasya śāsanāt', null, 7003028),
('ramayana-7-3-29', 29, 'Uttara Kanda, Sarga 3, Verse 29', 'अथ तत्रावसत्प्रीतो धर्मात्मा नैरृताधिपः।
समुद्रपरिधानायां लङ्कायां विश्रवात्मजः॥', 'atha tatrāvasat prīto dharmātmā nairṛtādhipaḥ
samudraparidhānāyāṃ laṅkāyāṃ viśravātmajaḥ', null, 7003029),
('ramayana-7-3-30', 30, 'Uttara Kanda, Sarga 3, Verse 30', 'काले काले विनीतात्मा पुष्पकेण धनेश्वरः।
अभ्यगच्छत्सुसंहृष्टः पितरं मातरं च सः॥', 'kāle kāle vinītātmā puṣpakeṇa dhaneśvaraḥ
abhyagacchat susaṃhṛṣṭaḥ pitaraṃ mātaraṃ ca saḥ', null, 7003030),
('ramayana-7-3-31', 31, 'Uttara Kanda, Sarga 3, Verse 31', 'स देवगन्धर्वगणैरभिष्टुतस्तथैव सिद्धैः सह चारणैरपि।
गभस्तिभिः सूर्य इवौजसा वृतः पितुः समीपं प्रययौ श्रिया वृतः॥', 'sa devagandharvagaṇair abhiṣṭutas tathaiva siddhaiḥ saha cāraṇair api
gabhastibhiḥ sūrya ivaujasā vṛtaḥ pituḥ samīpaṃ prayayau śriyā vṛtaḥ', null, 7003031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 4 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-4-1', 1, 'Uttara Kanda, Sarga 4, Verse 1', 'श्रुत्वागस्त्येरितं वाक्यं रामो विस्मयमागतः।
पूर्वमासीत्तु लङ्कायां रक्षसामिति संभवः॥', 'śrutvāgastyeritaṃ vākyaṃ rāmo vismayam āgataḥ
pūrvam āsīt tu laṅkāyāṃ rakṣasām iti saṃbhavaḥ', null, 7004001),
('ramayana-7-4-2', 2, 'Uttara Kanda, Sarga 4, Verse 2', 'ततः शिरः कम्पयित्वा त्रेताग्निसमविग्रहम्।
अगस्त्यं तं मुहुर्दृष्ट्वा स्मयमानोऽभ्यभाषत॥', 'tataḥ śiraḥ kampayitvā tretāgnisamavigraham
agastyaṃ taṃ muhur dṛṣṭvā smayamāno ''bhyabhāṣata', null, 7004002),
('ramayana-7-4-3', 3, 'Uttara Kanda, Sarga 4, Verse 3', 'भगवन्पूर्वमप्येषा लङ्कासीत्पिशिताशिनाम्।
इतीदं भवतः श्रुत्वा विस्मयो जनितो मम॥', 'bhagavan pūrvam apy eṣā laṅkāsīt piśitāśinām
itīdaṃ bhavataḥ śrutvā vismayo janito mama', null, 7004003),
('ramayana-7-4-4', 4, 'Uttara Kanda, Sarga 4, Verse 4', 'पुलस्त्यवंशादुद्भूता राक्षसा इति नः श्रुतम्।
इदानीमन्यतश्चापि संभवः कीर्तितस्त्वया॥', 'pulastyavaṃśād udbhūtā rākṣasā iti naḥ śrutam
idānīm anyataś cāpi saṃbhavaḥ kīrtitas tvayā', null, 7004004),
('ramayana-7-4-5', 5, 'Uttara Kanda, Sarga 4, Verse 5', 'रावणात्कुम्भकर्णाच्च प्रहस्ताद्विकटादपि।
रावणस्य च पुत्रेभ्यः किं नु ते बलवत्तराः॥', 'rāvaṇāt kumbhakarṇāc ca prahastād vikaṭād api
rāvaṇasya ca putrebhyaḥ kiṃ nu te balavattarāḥ', null, 7004005),
('ramayana-7-4-6', 6, 'Uttara Kanda, Sarga 4, Verse 6', 'क एषां पूर्वको ब्रह्मन्किंनामा किंतपोबलः।
अपराधं च कं प्राप्य विष्णुना द्राविताः पुरा॥', 'ka eṣāṃ pūrvako brahman kiṃnāmā kiṃtapobalaḥ
aparādhaṃ ca kaṃ prāpya viṣṇunā drāvitāḥ purā', null, 7004006),
('ramayana-7-4-7', 7, 'Uttara Kanda, Sarga 4, Verse 7', 'एतद्विस्तरतः सर्वं कथयस्व ममानघ।
कौतूहलं कृतं मह्यं नुद भानुर्यथा तमः॥', 'etad vistarataḥ sarvaṃ kathayasva mamānagha
kautūhalaṃ kṛtaṃ mahyaṃ nuda bhānur yathā tamaḥ', null, 7004007),
('ramayana-7-4-8', 8, 'Uttara Kanda, Sarga 4, Verse 8', 'राघवस्य तु तच्छ्रुत्वा संस्कारालंकृतं वचः।
ईषद्विस्मयमानस्तमगस्त्यः प्राह राघवम्॥', 'rāghavasya tu tac chrutvā saṃskārālaṃkṛtaṃ vacaḥ
īṣadvismayamānas tam agastyaḥ prāha rāghavam', null, 7004008),
('ramayana-7-4-9', 9, 'Uttara Kanda, Sarga 4, Verse 9', 'प्रजापतिः पुरा सृष्ट्वा अपः सलिलसंभवः।
तासां गोपायने सत्त्वानसृजत्पद्मसंभवः॥', 'prajāpatiḥ purā sṛṣṭvā apaḥ salilasaṃbhavaḥ
tāsāṃ gopāyane sattvān asṛjat padmasaṃbhavaḥ', null, 7004009),
('ramayana-7-4-10', 10, 'Uttara Kanda, Sarga 4, Verse 10', 'ते सत्त्वाः सत्त्वकर्तारं विनीतवदुपस्थिताः।
किं कुर्म इति भाषन्तः क्षुत्पिपासाभयार्दिताः॥', 'te sattvāḥ sattvakartāraṃ vinītavad upasthitāḥ
kiṃ kurma iti bhāṣantaḥ kṣutpipāsābhayārditāḥ', null, 7004010),
('ramayana-7-4-11', 11, 'Uttara Kanda, Sarga 4, Verse 11', 'प्रजापतिस्तु तान्याह सत्त्वानि प्रहसन्निव।
आभाष्य वाचा यत्नेन रक्षध्वमिति मानदः॥', 'prajāpatis tu tāny āha sattvāni prahasann iva
ābhāṣya vācā yatnena rakṣadhvam iti mānadaḥ', null, 7004011),
('ramayana-7-4-12', 12, 'Uttara Kanda, Sarga 4, Verse 12', 'रक्षाम इति तत्रान्यैर्यक्षामेति तथापरैः।
भुङ्क्षिताभुङ्क्षितैरुक्तस्ततस्तानाह भूतकृत्॥', 'rakṣāma iti tatrānyair yakṣāmeti tathāparaiḥ
bhuṅkṣitābhuṅkṣitair uktas tatas tān āha bhūtakṛt', null, 7004012),
('ramayana-7-4-13', 13, 'Uttara Kanda, Sarga 4, Verse 13', 'रक्षाम इति यैरुक्तं राक्षसास्ते भवन्तु वः।
यक्षाम इति यैरुक्तं ते वै यक्षा भवन्तु वः॥', 'rakṣāma iti yair uktaṃ rākṣasās te bhavantu vaḥ
yakṣāma iti yair uktaṃ te vai yakṣā bhavantu vaḥ', null, 7004013),
('ramayana-7-4-14', 14, 'Uttara Kanda, Sarga 4, Verse 14', 'तत्र हेतिः प्रहेतिश्च भ्रातरौ राक्षसर्षभौ।
मधुकैटभसंकाशौ बभूवतुररिंदमौ॥', 'tatra hetiḥ prahetiś ca bhrātarau rākṣasarṣabhau
madhukaiṭabhasaṃkāśau babhūvatur ariṃdamau', null, 7004014),
('ramayana-7-4-15', 15, 'Uttara Kanda, Sarga 4, Verse 15', 'प्रहेतिर्धार्मिकस्तत्र न दारान्सोऽभिकाङ्क्षति।
हेतिर्दारक्रियार्थं तु यत्नं परमथाकरोत्॥', 'prahetir dhārmikas tatra na dārān so ''bhikāṅkṣati
hetir dārakriyārthaṃ tu yatnaṃ param athākarot', null, 7004015),
('ramayana-7-4-16', 16, 'Uttara Kanda, Sarga 4, Verse 16', 'स कालभगिनीं कन्यां भयां नाम भयावहाम्।
उदावहदमेयात्मा स्वयमेव महामतिः॥', 'sa kālabhaginīṃ kanyāṃ bhayāṃ nāma bhayāvahām
udāvahad ameyātmā svayam eva mahāmatiḥ', null, 7004016),
('ramayana-7-4-17', 17, 'Uttara Kanda, Sarga 4, Verse 17', 'स तस्यां जनयामास हेती राक्षसपुंगवः।
पुत्रं पुत्रवतां श्रेष्ठो विद्युत्केश इति श्रुतम्॥', 'sa tasyāṃ janayām āsa hetī rākṣasapuṃgavaḥ
putraṃ putravatāṃ śreṣṭho vidyutkeśa iti śrutam', null, 7004017),
('ramayana-7-4-18', 18, 'Uttara Kanda, Sarga 4, Verse 18', 'विद्युत्केशो हेतिपुत्रः प्रदीप्ताग्निसमप्रभः।
व्यवर्धत महातेजास्तोयमध्य इवाम्बुजम्॥', 'vidyutkeśo hetiputraḥ pradīptāgnisamaprabhaḥ
vyavardhata mahātejās toyamadhya ivāmbujam', null, 7004018),
('ramayana-7-4-19', 19, 'Uttara Kanda, Sarga 4, Verse 19', 'स यदा यौवनं भद्रमनुप्राप्तो निशाचरः।
ततो दारक्रियां तस्य कर्तुं व्यवसितः पिता॥', 'sa yadā yauvanaṃ bhadram anuprāpto niśācaraḥ
tato dārakriyāṃ tasya kartuṃ vyavasitaḥ pitā', null, 7004019),
('ramayana-7-4-20', 20, 'Uttara Kanda, Sarga 4, Verse 20', 'संध्यादुहितरं सोऽथ संध्यातुल्यां प्रभावतः।
वरयामास पुत्रार्थं हेती राक्षसपुंगवः॥', 'saṃdhyāduhitaraṃ so ''tha saṃdhyātulyāṃ prabhāvataḥ
varayām āsa putrārthaṃ hetī rākṣasapuṃgavaḥ', null, 7004020),
('ramayana-7-4-21', 21, 'Uttara Kanda, Sarga 4, Verse 21', 'अवश्यमेव दातव्या परस्मै सेति संध्यया।
चिन्तयित्वा सुता दत्ता विद्युत्केशाय राघव॥', 'avaśyam eva dātavyā parasmai seti saṃdhyayā
cintayitvā sutā dattā vidyutkeśāya rāghava', null, 7004021),
('ramayana-7-4-22', 22, 'Uttara Kanda, Sarga 4, Verse 22', 'संध्यायास्तनयां लब्ध्वा विद्युत्केशो निशाचरः।
रमते स तया सार्धं पौलोम्या मघवानिव॥', 'saṃdhyāyās tanayāṃ labdhvā vidyutkeśo niśācaraḥ
ramate sa tayā sārdhaṃ paulomyā maghavān iva', null, 7004022),
('ramayana-7-4-23', 23, 'Uttara Kanda, Sarga 4, Verse 23', 'केन चित्त्वथ कालेन राम सालकटंकटा।
विद्युत्केशाद्गर्भमाप घनराजिरिवार्णवात्॥', 'kena cit tv atha kālena rāma sālakaṭaṃkaṭā
vidyutkeśād garbham āpa ghanarājir ivārṇavāt', null, 7004023),
('ramayana-7-4-24', 24, 'Uttara Kanda, Sarga 4, Verse 24', 'ततः सा राक्षसी गर्भं घनगर्भसमप्रभम्।
प्रसूता मन्दरं गत्वा गङ्गा गर्भमिवाग्निजम्॥', 'tataḥ sā rākṣasī garbhaṃ ghanagarbhasamaprabham
prasūtā mandaraṃ gatvā gaṅgā garbham ivāgnijam', null, 7004024),
('ramayana-7-4-25', 25, 'Uttara Kanda, Sarga 4, Verse 25', 'तमुत्सृज्य तु सा गर्भं विद्युत्केशाद्रतार्थिनी।
रेमे सा पतिना सार्धं विस्मृत्य सुतमात्मजम्॥', 'tam utsṛjya tu sā garbhaṃ vidyutkeśād ratārthinī
reme sā patinā sārdhaṃ vismṛtya sutam ātmajam', null, 7004025),
('ramayana-7-4-26', 26, 'Uttara Kanda, Sarga 4, Verse 26', 'तयोत्सृष्टः स तु शिशुः शरदर्कसमद्युतिः।
पाणिमास्ये समाधाय रुरोद घनराडिव॥', 'tayotsṛṣṭaḥ sa tu śiśuḥ śaradarkasamadyutiḥ
pāṇim āsye samādhāya ruroda ghanarāḍ iva', null, 7004026),
('ramayana-7-4-27', 27, 'Uttara Kanda, Sarga 4, Verse 27', 'अथोपरिष्टाद्गच्छन्वै वृषभस्थो हरः प्रभुः।
अपश्यदुमया सार्धं रुदन्तं राक्षसात्मजम्॥', 'athopariṣṭād gacchan vai vṛṣabhastho haraḥ prabhuḥ
apaśyad umayā sārdhaṃ rudantaṃ rākṣasātmajam', null, 7004027),
('ramayana-7-4-28', 28, 'Uttara Kanda, Sarga 4, Verse 28', 'कारुण्यभावात्पार्वत्या भवस्त्रिपुरहा ततः।
तं राक्षसात्मजं चक्रे मातुरेव वयः समम्॥', 'kāruṇyabhāvāt pārvatyā bhavas tripurahā tataḥ
taṃ rākṣasātmajaṃ cakre mātur eva vayaḥ samam', null, 7004028),
('ramayana-7-4-29', 29, 'Uttara Kanda, Sarga 4, Verse 29', 'अमरं चैव तं कृत्वा महादेवोऽक्षयोऽव्ययः।
पुरमाकाशगं प्रादात्पार्वत्याः प्रियकाम्यया॥', 'amaraṃ caiva taṃ kṛtvā mahādevo ''kṣayo ''vyayaḥ
puram ākāśagaṃ prādāt pārvatyāḥ priyakāmyayā', null, 7004029),
('ramayana-7-4-30', 30, 'Uttara Kanda, Sarga 4, Verse 30', 'उमयापि वरो दत्तो राक्षसीनां नृपात्मज।
सद्योपलब्धिर्गर्भस्य प्रसूतिः सद्य एव च।
सद्य एव वयःप्राप्तिर्मातुरेव वयः समम्॥', 'umayāpi varo datto rākṣasīnāṃ nṛpātmaja
sadyopalabdhir garbhasya prasūtiḥ sadya eva ca
sadya eva vayaḥprāptir mātur eva vayaḥ samam', null, 7004030),
('ramayana-7-4-31', 31, 'Uttara Kanda, Sarga 4, Verse 31', 'ततः सुकेशो वरदानगर्वितः श्रियं प्रभोः प्राप्य हरस्य पार्श्वतः।
चचार सर्वत्र महामतिः खगः खगं पुरं प्राप्य पुरंदरो यथा॥', 'tataḥ sukeśo varadānagarvitaḥ śriyaṃ prabhoḥ prāpya harasya pārśvataḥ
cacāra sarvatra mahāmatiḥ khagaḥ khagaṃ puraṃ prāpya puraṃdaro yathā', null, 7004031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 5 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-5-1', 1, 'Uttara Kanda, Sarga 5, Verse 1', 'सुकेशं धार्मिकं दृष्ट्वा वरलब्धं च राक्षसं।
ग्रामणीर्नाम गन्धर्वो विश्वावसुसमप्रभः॥', 'sukeśaṃ dhārmikaṃ dṛṣṭvā varalabdhaṃ ca rākṣasaṃ
grāmaṇīr nāma gandharvo viśvāvasusamaprabhaḥ', null, 7005001),
('ramayana-7-5-2', 2, 'Uttara Kanda, Sarga 5, Verse 2', 'तस्य देववती नाम द्वितीया श्रीरिवात्मजा।
तां सुकेशाय धर्मेण ददौ दक्षः श्रियं यथा॥', 'tasya devavatī nāma dvitīyā śrīr ivātmajā
tāṃ sukeśāya dharmeṇa dadau dakṣaḥ śriyaṃ yathā', null, 7005002),
('ramayana-7-5-3', 3, 'Uttara Kanda, Sarga 5, Verse 3', 'वरदानकृतैश्वर्यं सा तं प्राप्य पतिं प्रियम्।
आसीद्देववती तुष्टा धनं प्राप्येव निर्धनः॥', 'varadānakṛtaiśvaryaṃ sā taṃ prāpya patiṃ priyam
āsīd devavatī tuṣṭā dhanaṃ prāpyeva nirdhanaḥ', null, 7005003),
('ramayana-7-5-4', 4, 'Uttara Kanda, Sarga 5, Verse 4', 'स तया सह संयुक्तो रराज रजनीचरः।
अञ्जनादभिनिष्क्रान्तः करेण्वेव महागजः॥', 'sa tayā saha saṃyukto rarāja rajanīcaraḥ
añjanād abhiniṣkrāntaḥ kareṇveva mahāgajaḥ', null, 7005004),
('ramayana-7-5-5', 5, 'Uttara Kanda, Sarga 5, Verse 5', 'देववत्यां सुकेशस्तु जनयामास राघव।
त्रींस्त्रिनेत्रसमान्पुत्रान्राक्षसान्राक्षसाधिपः।
माल्यवन्तं सुमालिं च मालिं च बलिनां वरम्॥', 'devavatyāṃ sukeśas tu janayām āsa rāghava
trīṃs trinetrasamān putrān rākṣasān rākṣasādhipaḥ
mālyavantaṃ sumāliṃ ca māliṃ ca balināṃ varam', null, 7005005),
('ramayana-7-5-6', 6, 'Uttara Kanda, Sarga 5, Verse 6', 'त्रयो लोका इवाव्यग्राः स्थितास्त्रय इवाग्नयः।
त्रयो मन्त्रा इवात्युग्रास्त्रयो घोरा इवामयाः॥', 'trayo lokā ivāvyagrāḥ sthitās traya ivāgnayaḥ
trayo mantrā ivātyugrās trayo ghorā ivāmayāḥ', null, 7005006),
('ramayana-7-5-7', 7, 'Uttara Kanda, Sarga 5, Verse 7', 'त्रयः सुकेशस्य सुतास्त्रेताग्निसमवर्चसः।
विवृद्धिमगमंस्तत्र व्याधयोपेक्षिता इव॥', 'trayaḥ sukeśasya sutās tretāgnisamavarcasaḥ
vivṛddhim agamaṃs tatra vyādhayopekṣitā iva', null, 7005007),
('ramayana-7-5-8', 8, 'Uttara Kanda, Sarga 5, Verse 8', 'वरप्राप्तिं पितुस्ते तु ज्ञात्वैश्वर्यं ततो महत्।
तपस्तप्तुं गता मेरुं भ्रातरः कृतनिश्चयाः॥', 'varaprāptiṃ pitus te tu jñātvaiśvaryaṃ tato mahat
tapas taptuṃ gatā meruṃ bhrātaraḥ kṛtaniścayāḥ', null, 7005008),
('ramayana-7-5-9', 9, 'Uttara Kanda, Sarga 5, Verse 9', 'प्रगृह्य नियमान्घोरान्राक्षसा नृपसत्तम।
विचेरुस्ते तपो घोरं सर्वभूतभयावहम्॥', 'pragṛhya niyamān ghorān rākṣasā nṛpasattama
vicerus te tapo ghoraṃ sarvabhūtabhayāvaham', null, 7005009),
('ramayana-7-5-10', 10, 'Uttara Kanda, Sarga 5, Verse 10', 'सत्यार्जवदमोपेतैस्तपोभिर्भुवि दुष्करैः।
संतापयन्तस्त्रींल्लोकान्सदेवासुरमानुषान्॥', 'satyārjavadamopetais tapobhir bhuvi duṣkaraiḥ
saṃtāpayantas trīṃl lokān sadevāsuramānuṣān', null, 7005010),
('ramayana-7-5-11', 11, 'Uttara Kanda, Sarga 5, Verse 11', 'ततो विभुश्चतुर्वक्त्रो विमानवरमास्थितः।
सुकेशपुत्रानामन्त्र्य वरदोऽस्मीत्यभाषत॥', 'tato vibhuś caturvaktro vimānavaram āsthitaḥ
sukeśaputrān āmantrya varado ''smīty abhāṣata', null, 7005011),
('ramayana-7-5-12', 12, 'Uttara Kanda, Sarga 5, Verse 12', 'ब्रह्माणं वरदं ज्ञात्वा सेन्द्रैर्देवगणैर्वृतम्।
ऊचुः प्राञ्जलयः सर्वे वेपमाना इव द्रुमाः॥', 'brahmāṇaṃ varadaṃ jñātvā sendrair devagaṇair vṛtam
ūcuḥ prāñjalayaḥ sarve vepamānā iva drumāḥ', null, 7005012),
('ramayana-7-5-13', 13, 'Uttara Kanda, Sarga 5, Verse 13', 'तपसाराधितो देव यदि नो दिशसे वरम्।
अजेयाः शत्रुहन्तारस्तथैव चिरजीविनः।
प्रभविष्णवो भवामेति परस्परमनुव्रताः॥', 'tapasārādhito deva yadi no diśase varam
ajeyāḥ śatruhantāras tathaiva cirajīvinaḥ
prabhaviṣṇavo bhavāmeti parasparam anuvratāḥ', null, 7005013),
('ramayana-7-5-14', 14, 'Uttara Kanda, Sarga 5, Verse 14', 'एवं भविष्यतीत्युक्त्वा सुकेशतनयान्प्रभुः।
प्रययौ ब्रह्मलोकाय ब्रह्मा ब्राह्मणवत्सलः॥', 'evaṃ bhaviṣyatīty uktvā sukeśatanayān prabhuḥ
prayayau brahmalokāya brahmā brāhmaṇavatsalaḥ', null, 7005014),
('ramayana-7-5-15', 15, 'Uttara Kanda, Sarga 5, Verse 15', 'वरं लब्ध्वा ततः सर्वे राम रात्रिंचरास्तदा।
सुरासुरान्प्रबाधन्ते वरदानात्सुनिर्भयाः॥', 'varaṃ labdhvā tataḥ sarve rāma rātriṃcarās tadā
surāsurān prabādhante varadānāt sunirbhayāḥ', null, 7005015),
('ramayana-7-5-16', 16, 'Uttara Kanda, Sarga 5, Verse 16', 'तैर्वध्यमानास्त्रिदशाः सर्षिसंघाः सचारणाः।
त्रातारं नाधिगच्छन्ति निरयस्था यथा नराः॥', 'tair vadhyamānās tridaśāḥ sarṣisaṃghāḥ sacāraṇāḥ
trātāraṃ nādhigacchanti nirayasthā yathā narāḥ', null, 7005016),
('ramayana-7-5-17', 17, 'Uttara Kanda, Sarga 5, Verse 17', 'अथ ते विश्वकर्माणं शिल्पिनां वरमव्ययम्।
ऊचुः समेत्य संहृष्टा राक्षसा रघुसत्तम॥', 'atha te viśvakarmāṇaṃ śilpināṃ varam avyayam
ūcuḥ sametya saṃhṛṣṭā rākṣasā raghusattama', null, 7005017),
('ramayana-7-5-18', 18, 'Uttara Kanda, Sarga 5, Verse 18', 'गृहकर्ता भवानेव देवानां हृदयेप्सितम्।
अस्माकमपि तावत्त्वं गृहं कुरु महामते॥', 'gṛhakartā bhavān eva devānāṃ hṛdayepsitam
asmākam api tāvat tvaṃ gṛhaṃ kuru mahāmate', null, 7005018),
('ramayana-7-5-19', 19, 'Uttara Kanda, Sarga 5, Verse 19', 'हिमवन्तं समाश्रित्य मेरुं मन्दरमेव वा।
महेश्वरगृहप्रख्यं गृहं नः क्रियतां महत्॥', 'himavantaṃ samāśritya meruṃ mandaram eva vā
maheśvaragṛhaprakhyaṃ gṛhaṃ naḥ kriyatāṃ mahat', null, 7005019),
('ramayana-7-5-20', 20, 'Uttara Kanda, Sarga 5, Verse 20', 'विश्वकर्मा ततस्तेषां राक्षसानां महाभुजः।
निवासं कथयामास शक्रस्येवामरावतीम्॥', 'viśvakarmā tatas teṣāṃ rākṣasānāṃ mahābhujaḥ
nivāsaṃ kathayām āsa śakrasyevāmarāvatīm', null, 7005020),
('ramayana-7-5-21', 21, 'Uttara Kanda, Sarga 5, Verse 21', 'दक्षिणस्योदधेस्तीरे त्रिकूटो नाम पर्वतः।
शिखरे तस्य शैलस्य मध्यमेऽम्बुदसंनिभे।
शकुनैरपि दुष्प्रापे टङ्कच्छिन्नचतुर्दिशि॥', 'dakṣiṇasyodadhes tīre trikūṭo nāma parvataḥ
śikhare tasya śailasya madhyame ''mbudasaṃnibhe
śakunair api duṣprāpe ṭaṅkacchinnacaturdiśi', null, 7005021),
('ramayana-7-5-22', 22, 'Uttara Kanda, Sarga 5, Verse 22', 'त्रिंशद्योजनविस्तीर्णा स्वर्णप्राकारतोरणा।
मया लङ्केति नगरी शक्राज्ञप्तेन निर्मिता॥', 'triṃśadyojanavistīrṇā svarṇaprākāratoraṇā
mayā laṅketi nagarī śakrājñaptena nirmitā', null, 7005022),
('ramayana-7-5-23', 23, 'Uttara Kanda, Sarga 5, Verse 23', 'तस्यां वसत दुर्धर्षाः पुर्यां राक्षससत्तमाः।
अमरावतीं समासाद्य सेन्द्रा इव दिवौकसः॥', 'tasyāṃ vasata durdharṣāḥ puryāṃ rākṣasasattamāḥ
amarāvatīṃ samāsādya sendrā iva divaukasaḥ', null, 7005023),
('ramayana-7-5-24', 24, 'Uttara Kanda, Sarga 5, Verse 24', 'लङ्कादुर्गं समासाद्य राक्षसैर्बहुभिर्वृताः।
भविष्यथ दुराधर्षाः शत्रूणां शत्रुसूदनाः॥', 'laṅkādurgaṃ samāsādya rākṣasair bahubhir vṛtāḥ
bhaviṣyatha durādharṣāḥ śatrūṇāṃ śatrusūdanāḥ', null, 7005024),
('ramayana-7-5-25', 25, 'Uttara Kanda, Sarga 5, Verse 25', 'विश्वकर्मवचः श्रुत्वा ततस्ते राम राक्षसाः।
सहस्रानुचरा गत्वा लङ्कां तामवसन्पुरीम्॥', 'viśvakarmavacaḥ śrutvā tatas te rāma rākṣasāḥ
sahasrānucarā gatvā laṅkāṃ tām avasan purīm', null, 7005025),
('ramayana-7-5-26', 26, 'Uttara Kanda, Sarga 5, Verse 26', 'दृढप्राकारपरिखां हैमैर्गृहशतैर्वृताम्।
लङ्कामवाप्य ते हृष्टा विहरन्ति निशाचराः॥', 'dṛḍhaprākāraparikhāṃ haimair gṛhaśatair vṛtām
laṅkām avāpya te hṛṣṭā viharanti niśācarāḥ', null, 7005026),
('ramayana-7-5-27', 27, 'Uttara Kanda, Sarga 5, Verse 27', 'नर्मदा नाम गन्धर्वी नानाधर्मसमेधिता।
तस्याः कन्यात्रयं ह्यासीद्धीश्रीकीर्तिसमद्युति॥', 'narmadā nāma gandharvī nānādharmasamedhitā
tasyāḥ kanyātrayaṃ hy āsīd dhīśrīkīrtisamadyuti', null, 7005027),
('ramayana-7-5-28', 28, 'Uttara Kanda, Sarga 5, Verse 28', 'ज्येष्ठक्रमेण सा तेषां राक्षसानामराक्षसी।
कन्यास्ताः प्रददौ हृष्टा पूर्णचन्द्रनिभाननाः॥', 'jyeṣṭhakrameṇa sā teṣāṃ rākṣasānām arākṣasī
kanyās tāḥ pradadau hṛṣṭā pūrṇacandranibhānanāḥ', null, 7005028),
('ramayana-7-5-29', 29, 'Uttara Kanda, Sarga 5, Verse 29', 'त्रयाणां राक्षसेन्द्राणां तिस्रो गन्धर्वकन्यकाः।
मात्रा दत्ता महाभागा नक्षत्रे भगदैवते॥', 'trayāṇāṃ rākṣasendrāṇāṃ tisro gandharvakanyakāḥ
mātrā dattā mahābhāgā nakṣatre bhagadaivate', null, 7005029),
('ramayana-7-5-30', 30, 'Uttara Kanda, Sarga 5, Verse 30', 'कृतदारास्तु ते राम सुकेशतनयाः प्रभो।
भार्याभिः सह चिक्रीडुरप्सरोभिरिवामराः॥', 'kṛtadārās tu te rāma sukeśatanayāḥ prabho
bhāryābhiḥ saha cikrīḍur apsarobhir ivāmarāḥ', null, 7005030),
('ramayana-7-5-31', 31, 'Uttara Kanda, Sarga 5, Verse 31', 'तत्र माल्यवतो भार्या सुन्दरी नाम सुन्दरी।
स तस्यां जनयामास यदपत्यं निबोध तत्॥', 'tatra mālyavato bhāryā sundarī nāma sundarī
sa tasyāṃ janayām āsa yad apatyaṃ nibodha tat', null, 7005031),
('ramayana-7-5-32', 32, 'Uttara Kanda, Sarga 5, Verse 32', 'वज्रमुष्टिर्विरूपाक्षो दुर्मुखश्चैव राक्षसः।
सुप्तघ्नो यज्ञकोपश्च मत्तोन्मत्तौ तथैव च।
अनला चाभवत्कन्या सुन्दर्यां राम सुन्दरी॥', 'vajramuṣṭir virūpākṣo durmukhaś caiva rākṣasaḥ
suptaghno yajñakopaś ca mattonmattau tathaiva ca
analā cābhavat kanyā sundaryāṃ rāma sundarī', null, 7005032),
('ramayana-7-5-33', 33, 'Uttara Kanda, Sarga 5, Verse 33', 'सुमालिनोऽपि भार्यासीत्पूर्णचन्द्रनिभानना।
नाम्ना केतुमती नाम प्राणेभ्योऽपि गरीयसी॥', 'sumālino ''pi bhāryāsīt pūrṇacandranibhānanā
nāmnā ketumatī nāma prāṇebhyo ''pi garīyasī', null, 7005033),
('ramayana-7-5-34', 34, 'Uttara Kanda, Sarga 5, Verse 34', 'सुमाली जनयामास यदपत्यं निशाचरः।
केतुमत्यां महाराज तन्निबोधानुपूर्वशः॥', 'sumālī janayām āsa yad apatyaṃ niśācaraḥ
ketumatyāṃ mahārāja tan nibodhānupūrvaśaḥ', null, 7005034),
('ramayana-7-5-35', 35, 'Uttara Kanda, Sarga 5, Verse 35', 'प्रहस्तोऽकम्पनैश्चैव विकटः कालकार्मुकः।
धूम्राक्शश्चाथ दण्डश्च सुपार्श्वश्च महाबलः॥', 'prahasto ''kampanaiś caiva vikaṭaḥ kālakārmukaḥ
dhūmrākśaś cātha daṇḍaś ca supārśvaś ca mahābalaḥ', null, 7005035),
('ramayana-7-5-36', 36, 'Uttara Kanda, Sarga 5, Verse 36', 'संह्रादिः प्रघसश्चैव भासकर्णश्च राक्षसः।
राका पुष्पोत्कटा चैव कैकसी च शुचिस्मिता।
कुम्भीनसी च इत्येते सुमालेः प्रसवाः स्मृताः॥', 'saṃhrādiḥ praghasaś caiva bhāsakarṇaś ca rākṣasaḥ
rākā puṣpotkaṭā caiva kaikasī ca śucismitā
kumbhīnasī ca ity ete sumāleḥ prasavāḥ smṛtāḥ', null, 7005036),
('ramayana-7-5-37', 37, 'Uttara Kanda, Sarga 5, Verse 37', 'मालेस्तु वसुदा नाम गन्धर्वी रूपशालिनी।
भार्यासीत्पद्मपत्राक्षी स्वक्षी यक्षीवरोपमा॥', 'māles tu vasudā nāma gandharvī rūpaśālinī
bhāryāsīt padmapatrākṣī svakṣī yakṣīvaropamā', null, 7005037),
('ramayana-7-5-38', 38, 'Uttara Kanda, Sarga 5, Verse 38', 'सुमालेरनुजस्तस्यां जनयामास यत्प्रभो।
अपत्यं कथ्यमानं तन्मया त्वं शृणु राघव॥', 'sumāler anujas tasyāṃ janayām āsa yat prabho
apatyaṃ kathyamānaṃ tan mayā tvaṃ śṛṇu rāghava', null, 7005038),
('ramayana-7-5-39', 39, 'Uttara Kanda, Sarga 5, Verse 39', 'अनलश्चानिलश्चैव हरः संपातिरेव च।
एते विभीषणामात्या मालेयास्ते निशाचराः॥', 'analaś cānilaś caiva haraḥ saṃpātir eva ca
ete vibhīṣaṇāmātyā māleyās te niśācarāḥ', null, 7005039),
('ramayana-7-5-40', 40, 'Uttara Kanda, Sarga 5, Verse 40', 'ततस्तु ते राक्षसपुंगवास्त्रयो निशाचरैः पुत्रशतैश्च संवृताः।
सुरान्सहेन्द्रानृषिनागदानवान्बबाधिरे ते बलवीर्यदर्पिताः॥', 'tatas tu te rākṣasapuṃgavās trayo niśācaraiḥ putraśataiś ca saṃvṛtāḥ
surān sahendrān ṛṣināgadānavān babādhire te balavīryadarpitāḥ', null, 7005040),
('ramayana-7-5-41', 41, 'Uttara Kanda, Sarga 5, Verse 41', 'जगद्भ्रमन्तोऽनिलवद्दुरासदा रणे च मृत्युप्रतिमाः समाहिताः।
वरप्रदानादभिगर्विता भृशं क्रतुक्रियाणां प्रशमंकराः सदा॥', 'jagad bhramanto ''nilavad durāsadā raṇe ca mṛtyupratimāḥ samāhitāḥ
varapradānād abhigarvitā bhṛśaṃ kratukriyāṇāṃ praśamaṃkarāḥ sadā', null, 7005041)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 6 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-6-1', 1, 'Uttara Kanda, Sarga 6, Verse 1', 'तैर्वध्यमाना देवाश्च ऋषयश्च तपोधनाः।
भयार्ताः शरणं जग्मुर्देवदेवं महेश्वरम्॥', 'tair vadhyamānā devāś ca ṛṣayaś ca tapodhanāḥ
bhayārtāḥ śaraṇaṃ jagmur devadevaṃ maheśvaram', null, 7006001),
('ramayana-7-6-2', 2, 'Uttara Kanda, Sarga 6, Verse 2', 'ते समेत्य तु कामारिं त्रिपुरारिं त्रिलोचनम्।
ऊचुः प्राञ्जलयो देवा भयगद्गदभाषिणः॥', 'te sametya tu kāmāriṃ tripurāriṃ trilocanam
ūcuḥ prāñjalayo devā bhayagadgadabhāṣiṇaḥ', null, 7006002),
('ramayana-7-6-3', 3, 'Uttara Kanda, Sarga 6, Verse 3', 'सुकेशपुत्रैर्भगवन्पितामहवरोद्धतैः।
प्रजाध्यक्ष प्रजाः सर्वा बाध्यन्ते रिपुबाधन॥', 'sukeśaputrair bhagavan pitāmahavaroddhataiḥ
prajādhyakṣa prajāḥ sarvā bādhyante ripubādhana', null, 7006003),
('ramayana-7-6-4', 4, 'Uttara Kanda, Sarga 6, Verse 4', 'शरण्यान्यशरण्यानि आश्रमाणि कृतानि नः।
स्वर्गाच्च च्यावितः शक्रः स्वर्गे क्रीडन्ति शक्रवत्॥', 'śaraṇyāny aśaraṇyāni āśramāṇi kṛtāni naḥ
svargāc ca cyāvitaḥ śakraḥ svarge krīḍanti śakravat', null, 7006004),
('ramayana-7-6-5', 5, 'Uttara Kanda, Sarga 6, Verse 5', 'अहं विष्णुरहं रुद्रो ब्रह्माहं देवराडहम्।
अहं यमोऽहं वरुणश्चन्द्रोऽहं रविरप्यहम्॥', 'ahaṃ viṣṇur ahaṃ rudro brahmāhaṃ devarāḍ aham
ahaṃ yamo ''haṃ varuṇaś candro ''haṃ ravir apy aham', null, 7006005),
('ramayana-7-6-6', 6, 'Uttara Kanda, Sarga 6, Verse 6', 'इति ते राक्षसा देव वरदानेन दर्पिताः।
बाधन्ते समरोद्धर्षा ये च तेषां पुरःसराः॥', 'iti te rākṣasā deva varadānena darpitāḥ
bādhante samaroddharṣā ye ca teṣāṃ puraḥsarāḥ', null, 7006006),
('ramayana-7-6-7', 7, 'Uttara Kanda, Sarga 6, Verse 7', 'तन्नो देवभयार्तानामभयं दातुमर्हसि।
अशिवं वपुरास्थाय जहि दैवतकण्टकान्॥', 'tan no devabhayārtānām abhayaṃ dātum arhasi
aśivaṃ vapur āsthāya jahi daivatakaṇṭakān', null, 7006007),
('ramayana-7-6-8', 8, 'Uttara Kanda, Sarga 6, Verse 8', 'इत्युक्तस्तु सुरैः सर्वैः कपर्दी नीललोहितः।
सुकेशं प्रति सापेक्ष आह देवगणान्प्रभुः॥', 'ity uktas tu suraiḥ sarvaiḥ kapardī nīlalohitaḥ
sukeśaṃ prati sāpekṣa āha devagaṇān prabhuḥ', null, 7006008),
('ramayana-7-6-9', 9, 'Uttara Kanda, Sarga 6, Verse 9', 'नाहं तान्निहनिष्यामि अवध्या मम तेऽसुराः।
किं तु मन्त्रं प्रदास्यामि यो वै तान्निहनिष्यति॥', 'nāhaṃ tān nihaniṣyāmi avadhyā mama te ''surāḥ
kiṃ tu mantraṃ pradāsyāmi yo vai tān nihaniṣyati', null, 7006009),
('ramayana-7-6-10', 10, 'Uttara Kanda, Sarga 6, Verse 10', 'एवमेव समुद्योगं पुरस्कृत्य सुरर्षभाः।
गच्छन्तु शरणं विष्णुं हनिष्यति स तान्प्रभुः॥', 'evam eva samudyogaṃ puraskṛtya surarṣabhāḥ
gacchantu śaraṇaṃ viṣṇuṃ haniṣyati sa tān prabhuḥ', null, 7006010),
('ramayana-7-6-11', 11, 'Uttara Kanda, Sarga 6, Verse 11', 'ततस्ते जयशब्देन प्रतिनन्द्य महेश्वरम्।
विष्णोः समीपमाजग्मुर्निशाचरभयार्दिताः॥', 'tatas te jayaśabdena pratinandya maheśvaram
viṣṇoḥ samīpam ājagmur niśācarabhayārditāḥ', null, 7006011),
('ramayana-7-6-12', 12, 'Uttara Kanda, Sarga 6, Verse 12', 'शङ्खचक्रधरं देवं प्रणम्य बहुमान्य च।
ऊचुः संभ्रान्तवद्वाक्यं सुकेशतनयार्दिताः॥', 'śaṅkhacakradharaṃ devaṃ praṇamya bahumānya ca
ūcuḥ saṃbhrāntavad vākyaṃ sukeśatanayārditāḥ', null, 7006012),
('ramayana-7-6-13', 13, 'Uttara Kanda, Sarga 6, Verse 13', 'सुकेशतनयैर्देवत्रिभिस्त्रेताग्निसंनिभैः।
आक्रम्य वरदानेन स्थानान्यपहृतानि नः॥', 'sukeśatanayair devatribhis tretāgnisaṃnibhaiḥ
ākramya varadānena sthānāny apahṛtāni naḥ', null, 7006013),
('ramayana-7-6-14', 14, 'Uttara Kanda, Sarga 6, Verse 14', 'लङ्का नाम पुरी दुर्गा त्रिकूटशिखरे स्थिता।
तत्र स्थिताः प्रबाधन्ते सर्वान्नः क्षणदाचराः॥', 'laṅkā nāma purī durgā trikūṭaśikhare sthitā
tatra sthitāḥ prabādhante sarvān naḥ kṣaṇadācarāḥ', null, 7006014),
('ramayana-7-6-15', 15, 'Uttara Kanda, Sarga 6, Verse 15', 'स त्वमस्मत्प्रियार्थं तु जहि तान्मधुसूदन।
चक्रकृत्तास्यकमलान्निवेदय यमाय वै॥', 'sa tvam asmatpriyārthaṃ tu jahi tān madhusūdana
cakrakṛttāsyakamalān nivedaya yamāya vai', null, 7006015),
('ramayana-7-6-16', 16, 'Uttara Kanda, Sarga 6, Verse 16', 'भयेष्वभयदोऽस्माकं नान्योऽस्ति भवता समः।
नुद त्वं नो भयं देव नीहारमिव भास्करः॥', 'bhayeṣv abhayado ''smākaṃ nānyo ''sti bhavatā samaḥ
nuda tvaṃ no bhayaṃ deva nīhāram iva bhāskaraḥ', null, 7006016),
('ramayana-7-6-17', 17, 'Uttara Kanda, Sarga 6, Verse 17', 'इत्येवं दैवतैरुक्तो देवदेवो जनार्दनः।
अभयं भयदोऽरीणां दत्त्वा देवानुवाच ह॥', 'ity evaṃ daivatair ukto devadevo janārdanaḥ
abhayaṃ bhayado ''rīṇāṃ dattvā devān uvāca ha', null, 7006017),
('ramayana-7-6-18', 18, 'Uttara Kanda, Sarga 6, Verse 18', 'सुकेशं राक्षसं जाने ईशान वरदर्पितम्।
तांश्चास्य तनयाञ्जाने येषां ज्येष्ठः स माल्यवान्॥', 'sukeśaṃ rākṣasaṃ jāne īśāna varadarpitam
tāṃś cāsya tanayāñ jāne yeṣāṃ jyeṣṭhaḥ sa mālyavān', null, 7006018),
('ramayana-7-6-19', 19, 'Uttara Kanda, Sarga 6, Verse 19', 'तानहं समतिक्रान्तमर्यादान्राक्षसाधमान्।
सूदयिष्यामि संग्रामे सुरा भवत विज्वराः॥', 'tān ahaṃ samatikrāntamaryādān rākṣasādhamān
sūdayiṣyāmi saṃgrāme surā bhavata vijvarāḥ', null, 7006019),
('ramayana-7-6-20', 20, 'Uttara Kanda, Sarga 6, Verse 20', 'इत्युक्तास्ते सुराः सर्वे विष्णुना प्रभविष्णुना।
यथा वासं ययुर्हृष्टाः प्रशमन्तो जनार्दनम्॥', 'ity uktās te surāḥ sarve viṣṇunā prabhaviṣṇunā
yathā vāsaṃ yayur hṛṣṭāḥ praśamanto janārdanam', null, 7006020),
('ramayana-7-6-21', 21, 'Uttara Kanda, Sarga 6, Verse 21', 'विबुधानां समुद्योगं माल्यवान्स निशाचरः।
श्रुत्वा तौ भ्रातरौ वीराविदं वचनमब्रवीत्॥', 'vibudhānāṃ samudyogaṃ mālyavān sa niśācaraḥ
śrutvā tau bhrātarau vīrāv idaṃ vacanam abravīt', null, 7006021),
('ramayana-7-6-22', 22, 'Uttara Kanda, Sarga 6, Verse 22', 'अमरा ऋषयश्चैव संहत्य किल शंकरम्।
अस्मद्वधं परीप्सन्त इदमूचुस्त्रिलोचनम्॥', 'amarā ṛṣayaś caiva saṃhatya kila śaṃkaram
asmadvadhaṃ parīpsanta idam ūcus trilocanam', null, 7006022),
('ramayana-7-6-23', 23, 'Uttara Kanda, Sarga 6, Verse 23', 'सुकेशतनया देव वरदानबलोद्धताः।
बाधन्तेऽस्मान्समुद्युक्ता घोररूपाः पदे पदे॥', 'sukeśatanayā deva varadānabaloddhatāḥ
bādhante ''smān samudyuktā ghorarūpāḥ pade pade', null, 7006023),
('ramayana-7-6-24', 24, 'Uttara Kanda, Sarga 6, Verse 24', 'राक्षसैरभिभूताः स्म न शक्ताः स्म उमापते।
स्वेषु वेश्मसु संस्थातुं भयात्तेषां दुरात्मनाम्॥', 'rākṣasair abhibhūtāḥ sma na śaktāḥ sma umāpate
sveṣu veśmasu saṃsthātuṃ bhayāt teṣāṃ durātmanām', null, 7006024),
('ramayana-7-6-25', 25, 'Uttara Kanda, Sarga 6, Verse 25', 'तदस्माकं हितार्थे त्वं जहि तांस्तांस्त्रिलोचन।
राक्षसान्हुंकृतेनैव दह प्रदहतां वर॥', 'tad asmākaṃ hitārthe tvaṃ jahi tāṃs tāṃs trilocana
rākṣasān huṃkṛtenaiva daha pradahatāṃ vara', null, 7006025),
('ramayana-7-6-26', 26, 'Uttara Kanda, Sarga 6, Verse 26', 'इत्येवं त्रिदशैरुक्तो निशम्यान्धकसूदनः।
शिरः करं च धुन्वान इदं वचनमब्रवीत्॥', 'ity evaṃ tridaśair ukto niśamyāndhakasūdanaḥ
śiraḥ karaṃ ca dhunvāna idaṃ vacanam abravīt', null, 7006026),
('ramayana-7-6-27', 27, 'Uttara Kanda, Sarga 6, Verse 27', 'अवध्या मम ते देवाः सुकेशतनया रणे।
मन्त्रं तु वः प्रदास्यामि यो वै तान्निहनिष्यति॥', 'avadhyā mama te devāḥ sukeśatanayā raṇe
mantraṃ tu vaḥ pradāsyāmi yo vai tān nihaniṣyati', null, 7006027),
('ramayana-7-6-28', 28, 'Uttara Kanda, Sarga 6, Verse 28', 'यः स चक्रगदापाणिः पीतवासा जनार्दनः।
हनिष्यति स तान्युद्धे शरणं तं प्रपद्यथ॥', 'yaḥ sa cakragadāpāṇiḥ pītavāsā janārdanaḥ
haniṣyati sa tān yuddhe śaraṇaṃ taṃ prapadyatha', null, 7006028),
('ramayana-7-6-29', 29, 'Uttara Kanda, Sarga 6, Verse 29', 'हरान्नावाप्य ते कामं कामारिमभिवाद्य च।
नारायणालयं प्राप्तास्तस्मै सर्वं न्यवेदयन्॥', 'harān nāvāpya te kāmaṃ kāmārim abhivādya ca
nārāyaṇālayaṃ prāptās tasmai sarvaṃ nyavedayan', null, 7006029),
('ramayana-7-6-30', 30, 'Uttara Kanda, Sarga 6, Verse 30', 'ततो नारायणेनोक्ता देवा इन्द्रपुरोगमाः।
सुरारीन्सूदयिष्यामि सुरा भवत विज्वराः॥', 'tato nārāyaṇenoktā devā indrapurogamāḥ
surārīn sūdayiṣyāmi surā bhavata vijvarāḥ', null, 7006030),
('ramayana-7-6-31', 31, 'Uttara Kanda, Sarga 6, Verse 31', 'देवानां भयभीतानां हरिणा राक्षसर्षभौ।
प्रतिज्ञातो वधोऽस्माकं तच्चिन्तयथ यत्क्षमम्॥', 'devānāṃ bhayabhītānāṃ hariṇā rākṣasarṣabhau
pratijñāto vadho ''smākaṃ tac cintayatha yat kṣamam', null, 7006031),
('ramayana-7-6-32', 32, 'Uttara Kanda, Sarga 6, Verse 32', 'हिरण्यकशिपोर्मृत्युरन्येषां च सुरद्विषाम्।
दुःखं नारायणं जेतुं यो नो हन्तुमभीप्सति॥', 'hiraṇyakaśipor mṛtyur anyeṣāṃ ca suradviṣām
duḥkhaṃ nārāyaṇaṃ jetuṃ yo no hantum abhīpsati', null, 7006032),
('ramayana-7-6-33', 33, 'Uttara Kanda, Sarga 6, Verse 33', 'ततः सुमाली माली च श्रुत्वा माल्यवतो वचः।
ऊचतुर्भ्रातरं ज्येष्ठं भगांशाविव वासवम्॥', 'tataḥ sumālī mālī ca śrutvā mālyavato vacaḥ
ūcatur bhrātaraṃ jyeṣṭhaṃ bhagāṃśāv iva vāsavam', null, 7006033),
('ramayana-7-6-34', 34, 'Uttara Kanda, Sarga 6, Verse 34', 'स्वधीतं दत्तमिष्टं च ऐश्वर्यं परिपालितम्।
आयुर्निरामयं प्राप्तं स्वधर्मः स्थापितश्च नः॥', 'svadhītaṃ dattam iṣṭaṃ ca aiśvaryaṃ paripālitam
āyur nirāmayaṃ prāptaṃ svadharmaḥ sthāpitaś ca naḥ', null, 7006034),
('ramayana-7-6-35', 35, 'Uttara Kanda, Sarga 6, Verse 35', 'देवसागरमक्षोभ्यं शस्त्रौघैः प्रविगाह्य च।
जिता देवा रणे नित्यं न नो मृत्युकृतं भयम्॥', 'devasāgaram akṣobhyaṃ śastraughaiḥ pravigāhya ca
jitā devā raṇe nityaṃ na no mṛtyukṛtaṃ bhayam', null, 7006035),
('ramayana-7-6-36', 36, 'Uttara Kanda, Sarga 6, Verse 36', 'नारायणश्च रुद्रश्च शक्रश्चापि यमस्तथा।
अस्माकं प्रमुखे स्थातुं सर्व एव हि बिभ्यति॥', 'nārāyaṇaś ca rudraś ca śakraś cāpi yamas tathā
asmākaṃ pramukhe sthātuṃ sarva eva hi bibhyati', null, 7006036),
('ramayana-7-6-37', 37, 'Uttara Kanda, Sarga 6, Verse 37', 'विष्णोर्दोषश्च नास्त्यत्र कारणं राक्षसेश्वर।
देवानामेव दोषेण विष्णोः प्रचलितं मनः॥', 'viṣṇor doṣaś ca nāsty atra kāraṇaṃ rākṣaseśvara
devānām eva doṣeṇa viṣṇoḥ pracalitaṃ manaḥ', null, 7006037),
('ramayana-7-6-38', 38, 'Uttara Kanda, Sarga 6, Verse 38', 'तस्मादद्य समुद्युक्ताः सर्वसैन्यसमावृताः।
देवानेव जिघांसामो येभ्यो दोषः समुत्थितः॥', 'tasmād adya samudyuktāḥ sarvasainyasamāvṛtāḥ
devān eva jighāṃsāmo yebhyo doṣaḥ samutthitaḥ', null, 7006038),
('ramayana-7-6-39', 39, 'Uttara Kanda, Sarga 6, Verse 39', 'इति माली सुमाली च माल्यवानग्रजः प्रभुः।
उद्योगं घोषयित्वाथ राक्षसाः सर्व एव ते।
युद्धाय निर्ययुः क्रुद्धा जम्भवृत्रबला इव॥', 'iti mālī sumālī ca mālyavān agrajaḥ prabhuḥ
udyogaṃ ghoṣayitvātha rākṣasāḥ sarva eva te
yuddhāya niryayuḥ kruddhā jambhavṛtrabalā iva', null, 7006039),
('ramayana-7-6-40', 40, 'Uttara Kanda, Sarga 6, Verse 40', 'स्यन्दनैर्वारणेन्द्रैश्च हयैश्च गिरिसंनिभैः।
खरैर्गोभिरथोष्ट्रैश्च शिंशुमारैर्भुजं गमैः॥', 'syandanair vāraṇendraiś ca hayaiś ca girisaṃnibhaiḥ
kharair gobhir athoṣṭraiś ca śiṃśumārair bhujaṃ gamaiḥ', null, 7006040),
('ramayana-7-6-41', 41, 'Uttara Kanda, Sarga 6, Verse 41', 'मकरैः कच्छपैर्मीनैर्विहंगैर्गरुडोपमैः।
सिंहैर्व्याघ्रैर्वराहैश्च सृमरैश्चमरैरपि॥', 'makaraiḥ kacchapair mīnair vihaṃgair garuḍopamaiḥ
siṃhair vyāghrair varāhaiś ca sṛmaraiś camarair api', null, 7006041),
('ramayana-7-6-42', 42, 'Uttara Kanda, Sarga 6, Verse 42', 'त्यक्त्वा लङ्कां ततः सर्वे राक्षसा बलगर्विताः।
प्रयाता देवलोकाय योद्धुं दैवतशत्रवः॥', 'tyaktvā laṅkāṃ tataḥ sarve rākṣasā balagarvitāḥ
prayātā devalokāya yoddhuṃ daivataśatravaḥ', null, 7006042),
('ramayana-7-6-43', 43, 'Uttara Kanda, Sarga 6, Verse 43', 'लङ्काविपर्ययं दृष्ट्वा यानि लङ्कालयान्यथ।
भूतानि भयदर्शीनि विमनस्कानि सर्वशः॥', 'laṅkāviparyayaṃ dṛṣṭvā yāni laṅkālayāny atha
bhūtāni bhayadarśīni vimanaskāni sarvaśaḥ', null, 7006043),
('ramayana-7-6-44', 44, 'Uttara Kanda, Sarga 6, Verse 44', 'भौमास्तथान्तरिक्षाश्च कालाज्ञप्ता भयावहाः।
उत्पाता राक्षसेन्द्राणामभावायोत्थिता द्रुतम्॥', 'bhaumās tathāntarikṣāś ca kālājñaptā bhayāvahāḥ
utpātā rākṣasendrāṇām abhāvāyotthitā drutam', null, 7006044),
('ramayana-7-6-45', 45, 'Uttara Kanda, Sarga 6, Verse 45', 'अस्थीनि मेघा वर्षन्ति उष्णं शोणितमेव च।
वेलां समुद्रोऽप्युत्क्रान्तश्चलन्ते चाचलोत्तमाः॥', 'asthīni meghā varṣanti uṣṇaṃ śoṇitam eva ca
velāṃ samudro ''py utkrāntaś calante cācalottamāḥ', null, 7006045),
('ramayana-7-6-46', 46, 'Uttara Kanda, Sarga 6, Verse 46', 'अट्टहासान्विमुञ्चन्तो घननादसमस्वनान्।
भूताः परिपतन्ति स्म नृत्यमानाः सहस्रशः॥', 'aṭṭahāsān vimuñcanto ghananādasamasvanān
bhūtāḥ paripatanti sma nṛtyamānāḥ sahasraśaḥ', null, 7006046),
('ramayana-7-6-47', 47, 'Uttara Kanda, Sarga 6, Verse 47', 'गृध्रचक्रं महच्चापि ज्वलनोद्गारिभिर्मुखैः।
राक्षसानामुपरि वै भ्रमते कालचक्रवत्॥', 'gṛdhracakraṃ mahac cāpi jvalanodgāribhir mukhaiḥ
rākṣasānām upari vai bhramate kālacakravat', null, 7006047),
('ramayana-7-6-48', 48, 'Uttara Kanda, Sarga 6, Verse 48', 'तानचिन्त्यमहोत्पातान्राक्षसा बलगर्विताः।
यन्त्येव न निवर्तन्ते मृत्युपाशावपाशिताः॥', 'tān acintyamahotpātān rākṣasā balagarvitāḥ
yanty eva na nivartante mṛtyupāśāvapāśitāḥ', null, 7006048),
('ramayana-7-6-49', 49, 'Uttara Kanda, Sarga 6, Verse 49', 'माल्यवांश्च सुमाली च माली च रजनीचराः।
आसन्पुरःसरास्तेषां क्रतूनामिव पावकाः॥', 'mālyavāṃś ca sumālī ca mālī ca rajanīcarāḥ
āsan puraḥsarās teṣāṃ kratūnām iva pāvakāḥ', null, 7006049),
('ramayana-7-6-50', 50, 'Uttara Kanda, Sarga 6, Verse 50', 'माल्यवन्तं तु ते सर्वे माल्यवन्तमिवाचलम्।
निशाचरा आश्रयन्ते धातारमिव देहिनः॥', 'mālyavantaṃ tu te sarve mālyavantam ivācalam
niśācarā āśrayante dhātāram iva dehinaḥ', null, 7006050),
('ramayana-7-6-51', 51, 'Uttara Kanda, Sarga 6, Verse 51', 'तद्बलं राक्षसेन्द्राणां महाभ्रघननादितम्।
जयेप्सया देवलोकं ययौ माली वशे स्थितम्॥', 'tad balaṃ rākṣasendrāṇāṃ mahābhraghananāditam
jayepsayā devalokaṃ yayau mālī vaśe sthitam', null, 7006051),
('ramayana-7-6-52', 52, 'Uttara Kanda, Sarga 6, Verse 52', 'राक्षसानां समुद्योगं तं तु नारायणः प्रभुः।
देवदूतादुपश्रुत्य दध्रे युद्धे ततो मनः॥', 'rākṣasānāṃ samudyogaṃ taṃ tu nārāyaṇaḥ prabhuḥ
devadūtād upaśrutya dadhre yuddhe tato manaḥ', null, 7006052),
('ramayana-7-6-53', 53, 'Uttara Kanda, Sarga 6, Verse 53', 'स देवसिद्धर्षिमहोरगैश्च गन्धर्वमुख्याप्सरसोपगीतः।
समाससादामरशत्रुसैन्यं चक्रासिसीरप्रवरादिधारी॥', 'sa devasiddharṣimahoragaiś ca gandharvamukhyāpsarasopagītaḥ
samāsasādāmaraśatrusainyaṃ cakrāsisīrapravarādidhārī', null, 7006053),
('ramayana-7-6-54', 54, 'Uttara Kanda, Sarga 6, Verse 54', 'सुपर्णपक्षानिलनुन्नपक्षं भ्रमत्पताकं प्रविकीर्णशस्त्रम्।
चचाल तद्राक्षसराजसैन्यं चलोपलो नील इवाचलेन्द्रः॥', 'suparṇapakṣānilanunnapakṣaṃ bhramatpatākaṃ pravikīrṇaśastram
cacāla tad rākṣasarājasainyaṃ calopalo nīla ivācalendraḥ', null, 7006054),
('ramayana-7-6-55', 55, 'Uttara Kanda, Sarga 6, Verse 55', 'तथ शितैः शोणितमांसरूषितैर्युगान्तवैश्वानरतुल्यविग्रहैः।
निशाचराः संपरिवार्य माधवं वरायुधैर्निर्बिभिदुः सहस्रशः॥', 'tatha śitaiḥ śoṇitamāṃsarūṣitair yugāntavaiśvānaratulyavigrahaiḥ
niśācarāḥ saṃparivārya mādhavaṃ varāyudhair nirbibhiduḥ sahasraśaḥ', null, 7006055)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 7 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-7-1', 1, 'Uttara Kanda, Sarga 7, Verse 1', 'नारायणगिरिं ते तु गर्जन्तो राक्षसाम्बुदाः।
अवर्षन्निषुवर्षेण वर्षेणाद्रिमिवाम्बुदाः॥', 'nārāyaṇagiriṃ te tu garjanto rākṣasāmbudāḥ
avarṣann iṣuvarṣeṇa varṣeṇādrim ivāmbudāḥ', null, 7007001),
('ramayana-7-7-2', 2, 'Uttara Kanda, Sarga 7, Verse 2', 'श्यामावदातस्तैर्विष्णुर्नीलैर्नक्तंचरोत्तमैः।
वृतोऽञ्जनगिरीवासीद्वर्षमाणैः पयोधरैः॥', 'śyāmāvadātas tair viṣṇur nīlair naktaṃcarottamaiḥ
vṛto ''ñjanagirīvāsīd varṣamāṇaiḥ payodharaiḥ', null, 7007002),
('ramayana-7-7-3', 3, 'Uttara Kanda, Sarga 7, Verse 3', 'शलभा इव केदारं मशका इव पर्वतम्।
यथामृतघटं जीवा मकरा इव चार्णवम्॥', 'śalabhā iva kedāraṃ maśakā iva parvatam
yathāmṛtaghaṭaṃ jīvā makarā iva cārṇavam', null, 7007003),
('ramayana-7-7-4', 4, 'Uttara Kanda, Sarga 7, Verse 4', 'तथा रक्षोधनुर्मुक्ता वज्रानिलमनोजवाः।
हरिं विशन्ति स्म शरा लोकास्तमिव पर्यये॥', 'tathā rakṣodhanur muktā vajrānilamanojavāḥ
hariṃ viśanti sma śarā lokāstam iva paryaye', null, 7007004),
('ramayana-7-7-5', 5, 'Uttara Kanda, Sarga 7, Verse 5', 'स्यन्दनैः स्यन्दनगता गजैश्च गजधूर्गताः।
अश्वारोहाः सदश्वैश्च पादाताश्चाम्बरे चराः॥', 'syandanaiḥ syandanagatā gajaiś ca gajadhūr gatāḥ
aśvārohāḥ sadaśvaiś ca pādātāś cāmbare carāḥ', null, 7007005),
('ramayana-7-7-6', 6, 'Uttara Kanda, Sarga 7, Verse 6', 'राक्षसेन्द्रा गिरिनिभाः शरशक्त्यृष्टितोमरैः।
निरुच्छ्वासं हरिं चक्रुः प्राणायाम इव द्विजम्॥', 'rākṣasendrā girinibhāḥ śaraśaktyṛṣṭitomaraiḥ
nirucchvāsaṃ hariṃ cakruḥ prāṇāyāma iva dvijam', null, 7007006),
('ramayana-7-7-7', 7, 'Uttara Kanda, Sarga 7, Verse 7', 'निशाचरैस्तुद्यमानो मीनैरिव महातिमिः।
शार्ङ्गमायम्य गात्राणि राक्षसानां महाहवे॥', 'niśācarais tudyamāno mīnair iva mahātimiḥ
śārṅgam āyamya gātrāṇi rākṣasānāṃ mahāhave', null, 7007007),
('ramayana-7-7-8', 8, 'Uttara Kanda, Sarga 7, Verse 8', 'शरैः पूर्णायतोत्सृष्टैर्वज्रवक्त्रैर्मनोजवैः।
चिच्छेद तिलशो विष्णुः शतशोऽथ सहस्रशः॥', 'śaraiḥ pūrṇāyatotsṛṣṭair vajravaktrair manojavaiḥ
ciccheda tilaśo viṣṇuḥ śataśo ''tha sahasraśaḥ', null, 7007008),
('ramayana-7-7-9', 9, 'Uttara Kanda, Sarga 7, Verse 9', 'विद्राव्य शरवर्षं तं वर्षं वायुरिवोत्थितम्।
पाञ्चजन्यं महाशङ्खं प्रदध्मौ पुरुषोत्तमः॥', 'vidrāvya śaravarṣaṃ taṃ varṣaṃ vāyur ivotthitam
pāñcajanyaṃ mahāśaṅkhaṃ pradadhmau puruṣottamaḥ', null, 7007009),
('ramayana-7-7-10', 10, 'Uttara Kanda, Sarga 7, Verse 10', 'सोऽम्बुजो हरिणा ध्मातः सर्वप्राणेन शङ्खराट्।
ररास भीमनिह्रादो युगान्ते जलदो यथा॥', 'so ''mbujo hariṇā dhmātaḥ sarvaprāṇena śaṅkharāṭ
rarāsa bhīmanihrādo yugānte jalado yathā', null, 7007010),
('ramayana-7-7-11', 11, 'Uttara Kanda, Sarga 7, Verse 11', 'शङ्खराजरवः सोऽथ त्रासयामास राक्षसान्।
मृगराज इवारण्ये समदानिव कुञ्जरान्॥', 'śaṅkharājaravaḥ so ''tha trāsayām āsa rākṣasān
mṛgarāja ivāraṇye samadān iva kuñjarān', null, 7007011),
('ramayana-7-7-12', 12, 'Uttara Kanda, Sarga 7, Verse 12', 'न शेकुरश्वाः संस्थातुं विमदाः कुञ्जराभवन्।
स्यन्दनेभ्यश्च्युता योधाः शङ्खरावितदुर्बलाः॥', 'na śekur aśvāḥ saṃsthātuṃ vimadāḥ kuñjarābhavan
syandanebhyaś cyutā yodhāḥ śaṅkharāvitadurbalāḥ', null, 7007012),
('ramayana-7-7-13', 13, 'Uttara Kanda, Sarga 7, Verse 13', 'शार्ङ्गचापविनिर्मुक्ता वज्रतुल्याननाः शराः।
विदार्य तानि रक्षांसि सुपुङ्खा विविशुः क्षितिम्॥', 'śārṅgacāpavinirmuktā vajratulyānanāḥ śarāḥ
vidārya tāni rakṣāṃsi supuṅkhā viviśuḥ kṣitim', null, 7007013),
('ramayana-7-7-14', 14, 'Uttara Kanda, Sarga 7, Verse 14', 'भिद्यमानाः शरैश्चान्ये नारायणधनुश्च्युतैः।
निपेतू राक्षसा भीमाः शैला वज्रहता इव॥', 'bhidyamānāḥ śaraiś cānye nārāyaṇadhanuścyutaiḥ
nipetū rākṣasā bhīmāḥ śailā vajrahatā iva', null, 7007014),
('ramayana-7-7-15', 15, 'Uttara Kanda, Sarga 7, Verse 15', 'व्रणैर्व्रणकरारीणामधोक्षजशरोद्भवैः।
असृक्क्षरन्ति धाराभिः स्वर्णधारामिवाचलाः॥', 'vraṇair vraṇakarārīṇām adhokṣajaśarodbhavaiḥ
asṛk kṣaranti dhārābhiḥ svarṇadhārām ivācalāḥ', null, 7007015),
('ramayana-7-7-16', 16, 'Uttara Kanda, Sarga 7, Verse 16', 'शङ्खराजरवश्चापि शार्ङ्गचापरवस्तथा।
राक्षसानां रवांश्चापि ग्रसते वैष्णवो रवः॥', 'śaṅkharājaravaś cāpi śārṅgacāparavas tathā
rākṣasānāṃ ravāṃś cāpi grasate vaiṣṇavo ravaḥ', null, 7007016),
('ramayana-7-7-17', 17, 'Uttara Kanda, Sarga 7, Verse 17', 'सूर्यादिव करा घोरा ऊर्मयः सागरादिव।
पर्वतादिव नागेन्द्रा वार्योघा इव चाम्बुदात्॥', 'sūryād iva karā ghorā ūrmayaḥ sāgarād iva
parvatād iva nāgendrā vāryoghā iva cāmbudāt', null, 7007017),
('ramayana-7-7-18', 18, 'Uttara Kanda, Sarga 7, Verse 18', 'तथा बाणा विनिर्मुक्ताः शार्ङ्गान्नरायणेरिताः।
निर्धावन्तीषवस्तूर्णं शतशोऽथ सहस्रशः॥', 'tathā bāṇā vinirmuktāḥ śārṅgān narāyaṇeritāḥ
nirdhāvantīṣavas tūrṇaṃ śataśo ''tha sahasraśaḥ', null, 7007018),
('ramayana-7-7-19', 19, 'Uttara Kanda, Sarga 7, Verse 19', 'शरभेण यथा सिंहाः सिंहेन द्विरदा यथा।
द्विरदेन यथा व्याघ्रा व्याघ्रेण द्वीपिनो यथा॥', 'śarabheṇa yathā siṃhāḥ siṃhena dviradā yathā
dviradena yathā vyāghrā vyāghreṇa dvīpino yathā', null, 7007019),
('ramayana-7-7-20', 20, 'Uttara Kanda, Sarga 7, Verse 20', 'द्वीपिना च यथा श्वानः शुना मार्जारका यथा।
मार्जारेण यथा सर्पाः सर्पेण च यथाखवः॥', 'dvīpinā ca yathā śvānaḥ śunā mārjārakā yathā
mārjāreṇa yathā sarpāḥ sarpeṇa ca yathākhavaḥ', null, 7007020),
('ramayana-7-7-21', 21, 'Uttara Kanda, Sarga 7, Verse 21', 'तथा ते राक्षसा युद्धे विष्णुना प्रभविष्णुना।
द्रवन्ति द्राविताश्चैव शायिताश्च महीतले॥', 'tathā te rākṣasā yuddhe viṣṇunā prabhaviṣṇunā
dravanti drāvitāś caiva śāyitāś ca mahītale', null, 7007021),
('ramayana-7-7-22', 22, 'Uttara Kanda, Sarga 7, Verse 22', 'राक्षसानां सहस्राणि निहत्य मधुसूदनः।
वारिजं नादयामास तोयदं सुरराडिव॥', 'rākṣasānāṃ sahasrāṇi nihatya madhusūdanaḥ
vārijaṃ nādayām āsa toyadaṃ surarāḍ iva', null, 7007022),
('ramayana-7-7-23', 23, 'Uttara Kanda, Sarga 7, Verse 23', 'नारायणशरग्रस्तं शङ्खनादसुविह्वलम्।
ययौ लङ्कामभिमुखं प्रभग्नं राक्षसं बलम्॥', 'nārāyaṇaśaragrastaṃ śaṅkhanādasuvihvalam
yayau laṅkām abhimukhaṃ prabhagnaṃ rākṣasaṃ balam', null, 7007023),
('ramayana-7-7-24', 24, 'Uttara Kanda, Sarga 7, Verse 24', 'प्रभग्ने राक्षसबले नारायणशराहते।
सुमाली शरवर्षेण आववार रणे हरिम्॥', 'prabhagne rākṣasabale nārāyaṇaśarāhate
sumālī śaravarṣeṇa āvavāra raṇe harim', null, 7007024),
('ramayana-7-7-25', 25, 'Uttara Kanda, Sarga 7, Verse 25', 'उत्क्षिप्य हेमाभरणं करं करमिव द्विपः।
ररास राक्षसो हर्षात्सतडित्तोयदो यथा॥', 'utkṣipya hemābharaṇaṃ karaṃ karam iva dvipaḥ
rarāsa rākṣaso harṣāt sataḍit toyado yathā', null, 7007025),
('ramayana-7-7-26', 26, 'Uttara Kanda, Sarga 7, Verse 26', 'सुमालेर्नर्दतस्तस्य शिरो ज्वलितकुण्डलम्।
चिच्छेद यन्तुरश्वाश्च भ्रान्तास्तस्य तु रक्षसः॥', 'sumāler nardatas tasya śiro jvalitakuṇḍalam
ciccheda yantur aśvāś ca bhrāntās tasya tu rakṣasaḥ', null, 7007026),
('ramayana-7-7-27', 27, 'Uttara Kanda, Sarga 7, Verse 27', 'तैरश्वैर्भ्राम्यते भ्रान्तैः सुमाली राक्षसेश्वरः।
इन्द्रियाश्वैर्यथा भ्रान्तैर्धृतिहीनो यथा नरः॥', 'tair aśvair bhrāmyate bhrāntaiḥ sumālī rākṣaseśvaraḥ
indriyāśvair yathā bhrāntair dhṛtihīno yathā naraḥ', null, 7007027),
('ramayana-7-7-28', 28, 'Uttara Kanda, Sarga 7, Verse 28', 'माली चाभ्यद्रवद्युद्धे प्रगृह्य सशरं धनुः।
मालेर्धनुश्च्युता बाणाः कार्तस्वरविभूषिताः।
विविशुर्हरिमासाद्य क्रौञ्चं पत्ररथा इव॥', 'mālī cābhyadravad yuddhe pragṛhya saśaraṃ dhanuḥ
māler dhanuścyutā bāṇāḥ kārtasvaravibhūṣitāḥ
viviśur harim āsādya krauñcaṃ patrarathā iva', null, 7007028),
('ramayana-7-7-29', 29, 'Uttara Kanda, Sarga 7, Verse 29', 'अर्द्यमानः शरैः सोऽथ मालिमुक्तैः सहस्रशः।
चुक्षुभे न रणे विष्णुर्जितेन्द्रिय इवाधिभिः॥', 'ardyamānaḥ śaraiḥ so ''tha mālimuktaiḥ sahasraśaḥ
cukṣubhe na raṇe viṣṇur jitendriya ivādhibhiḥ', null, 7007029),
('ramayana-7-7-30', 30, 'Uttara Kanda, Sarga 7, Verse 30', 'अथ मौर्वी स्वनं कृत्वा भगवान्भूतभावनः।
मालिनं प्रति बाणौघान्ससर्जासिगदाधरः॥', 'atha maurvī svanaṃ kṛtvā bhagavān bhūtabhāvanaḥ
mālinaṃ prati bāṇaughān sasarjāsigadādharaḥ', null, 7007030),
('ramayana-7-7-31', 31, 'Uttara Kanda, Sarga 7, Verse 31', 'ते मालिदेहमासाद्य वज्रविद्युत्प्रभाः शराः।
पिबन्ति रुधिरं तस्य नागा इव पुरामृतम्॥', 'te mālideham āsādya vajravidyutprabhāḥ śarāḥ
pibanti rudhiraṃ tasya nāgā iva purāmṛtam', null, 7007031),
('ramayana-7-7-32', 32, 'Uttara Kanda, Sarga 7, Verse 32', 'मालिनं विमुखं कृत्वा मालिमौलिं हरिर्बलात्।
रथं च सध्वजं चापं वाजिनश्च न्यपातयत्॥', 'mālinaṃ vimukhaṃ kṛtvā mālimauliṃ harir balāt
rathaṃ ca sadhvajaṃ cāpaṃ vājinaś ca nyapātayat', null, 7007032),
('ramayana-7-7-33', 33, 'Uttara Kanda, Sarga 7, Verse 33', 'विरथस्तु गदां गृह्य माली नक्तंचरोत्तमः।
आपुप्लुवे गदापाणिर्गिर्यग्रादिव केषरी॥', 'virathas tu gadāṃ gṛhya mālī naktaṃcarottamaḥ
āpupluve gadāpāṇir giryagrād iva keṣarī', null, 7007033),
('ramayana-7-7-34', 34, 'Uttara Kanda, Sarga 7, Verse 34', 'स तया गरुडं संख्ये ईशानमिव चान्तकः।
ललाटदेशेऽभ्यहनद्वज्रेणेन्द्रो यथाचलम्॥', 'sa tayā garuḍaṃ saṃkhye īśānam iva cāntakaḥ
lalāṭadeśe ''bhyahanad vajreṇendro yathācalam', null, 7007034),
('ramayana-7-7-35', 35, 'Uttara Kanda, Sarga 7, Verse 35', 'गदयाभिहतस्तेन मालिना गरुडो भृशम्।
रणात्पराङ्मुखं देवं कृतवान्वेदनातुरः॥', 'gadayābhihatas tena mālinā garuḍo bhṛśam
raṇāt parāṅmukhaṃ devaṃ kṛtavān vedanāturaḥ', null, 7007035),
('ramayana-7-7-36', 36, 'Uttara Kanda, Sarga 7, Verse 36', 'पराङ्मुखे कृते देवे मालिना गरुडेन वै।
उदतिष्ठन्महानादो रक्षसामभिनर्दताम्॥', 'parāṅmukhe kṛte deve mālinā garuḍena vai
udatiṣṭhan mahānādo rakṣasām abhinardatām', null, 7007036),
('ramayana-7-7-37', 37, 'Uttara Kanda, Sarga 7, Verse 37', 'रक्षसां नदतां नादं श्रुत्वा हरिहयानुजः।
पराङ्मुखोऽप्युत्ससर्ज चक्रं मालिजिघांसया॥', 'rakṣasāṃ nadatāṃ nādaṃ śrutvā harihayānujaḥ
parāṅmukho ''py utsasarja cakraṃ mālijighāṃsayā', null, 7007037),
('ramayana-7-7-38', 38, 'Uttara Kanda, Sarga 7, Verse 38', 'तत्सूर्यमण्डलाभासं स्वभासा भासयन्नभः।
कालचक्रनिभं चक्रं मालेः शीर्षमपातयत्॥', 'tat sūryamaṇḍalābhāsaṃ svabhāsā bhāsayan nabhaḥ
kālacakranibhaṃ cakraṃ māleḥ śīrṣam apātayat', null, 7007038),
('ramayana-7-7-39', 39, 'Uttara Kanda, Sarga 7, Verse 39', 'तच्छिरो राक्षसेन्द्रस्य चक्रोत्कृत्तं विभीषणम्।
पपात रुधिरोद्गारि पुरा राहुशिरो यथा॥', 'tacchiro rākṣasendrasya cakrotkṛttaṃ vibhīṣaṇam
papāta rudhirodgāri purā rāhuśiro yathā', null, 7007039),
('ramayana-7-7-40', 40, 'Uttara Kanda, Sarga 7, Verse 40', 'ततः सुरैः सुसंहृष्टैः सर्वप्राणसमीरितः।
सिंहनादरवो मुक्तः साधु देवेति वादिभिः॥', 'tataḥ suraiḥ susaṃhṛṣṭaiḥ sarvaprāṇasamīritaḥ
siṃhanādaravo muktaḥ sādhu deveti vādibhiḥ', null, 7007040),
('ramayana-7-7-41', 41, 'Uttara Kanda, Sarga 7, Verse 41', 'मालिनं निहतं दृष्ट्वा सुमाली मल्यवानपि।
सबलौ शोकसंतप्तौ लङ्कां प्रति विधावितौ॥', 'mālinaṃ nihataṃ dṛṣṭvā sumālī malyavān api
sabalau śokasaṃtaptau laṅkāṃ prati vidhāvitau', null, 7007041),
('ramayana-7-7-42', 42, 'Uttara Kanda, Sarga 7, Verse 42', 'गरुडस्तु समाश्वस्तः संनिवृत्य महामनाः।
राक्षसान्द्रावयामास पक्षवातेन कोपितः॥', 'garuḍas tu samāśvastaḥ saṃnivṛtya mahāmanāḥ
rākṣasān drāvayām āsa pakṣavātena kopitaḥ', null, 7007042),
('ramayana-7-7-43', 43, 'Uttara Kanda, Sarga 7, Verse 43', 'नारायणोऽपीषुवराशनीभिर्विदारयामास धनुःप्रमुक्तैः।
नक्तंचरान्मुक्तविधूतकेशान्यथाशनीभिः सतडिन्महेन्द्रः॥', 'nārāyaṇo ''pīṣuvarāśanībhir vidārayām āsa dhanuḥpramuktaiḥ
naktaṃcarān muktavidhūtakeśān yathāśanībhiḥ sataḍinmahendraḥ', null, 7007043),
('ramayana-7-7-44', 44, 'Uttara Kanda, Sarga 7, Verse 44', 'भिन्नातपत्रं पतमानशस्त्रं शरैरपध्वस्तविशीर्णदेहम्।
विनिःसृतान्त्रं भयलोलनेत्रं बलं तदुन्मत्तनिभं बभूव॥', 'bhinnātapatraṃ patamānaśastraṃ śarair apadhvastaviśīrṇadeham
viniḥsṛtāntraṃ bhayalolanetraṃ balaṃ tad unmattanibhaṃ babhūva', null, 7007044),
('ramayana-7-7-45', 45, 'Uttara Kanda, Sarga 7, Verse 45', 'सिंहार्दितानामिव कुञ्जराणां निशाचराणां सह कुञ्जराणाम्।
रवाश्च वेगाश्च समं बभूवुः पुराणसिंहेन विमर्दितानाम्॥', 'siṃhārditānām iva kuñjarāṇāṃ niśācarāṇāṃ saha kuñjarāṇām
ravāś ca vegāś ca samaṃ babhūvuḥ purāṇasiṃhena vimarditānām', null, 7007045),
('ramayana-7-7-46', 46, 'Uttara Kanda, Sarga 7, Verse 46', 'संछाद्यमाना हरिबाणजालैः स्वबाणजालानि समुत्सृजन्तः।
धावन्ति नक्तंचरकालमेघा वायुप्रणुन्ना इव कालमेघाः॥', 'saṃchādyamānā haribāṇajālaiḥ svabāṇajālāni samutsṛjantaḥ
dhāvanti naktaṃcarakālameghā vāyupraṇunnā iva kālameghāḥ', null, 7007046),
('ramayana-7-7-47', 47, 'Uttara Kanda, Sarga 7, Verse 47', 'चक्रप्रहारैर्विनिकृत्तशीर्षाः संचूर्णिताङ्गाश्च गदाप्रहारैः।
असिप्रहारैर्बहुधा विभक्ताः पतन्ति शैला इव राक्षसेन्द्राः॥', 'cakraprahārair vinikṛttaśīrṣāḥ saṃcūrṇitāṅgāś ca gadāprahāraiḥ
asiprahārair bahudhā vibhaktāḥ patanti śailā iva rākṣasendrāḥ', null, 7007047),
('ramayana-7-7-48', 48, 'Uttara Kanda, Sarga 7, Verse 48', 'चक्रकृत्तास्यकमला गदासंचूर्णितोरसः।
लाङ्गलग्लपितग्रीवा मुसलैर्भिन्नमस्तकाः॥', 'cakrakṛttāsyakamalā gadāsaṃcūrṇitorasaḥ
lāṅgalaglapitagrīvā musalair bhinnamastakāḥ', null, 7007048),
('ramayana-7-7-49', 49, 'Uttara Kanda, Sarga 7, Verse 49', 'के चिच्चैवासिना छिन्नास्तथान्ये शरताडिताः।
निपेतुरम्बरात्तूर्णं राक्षसाः सागराम्भसि॥', 'ke cic caivāsinā chinnās tathānye śaratāḍitāḥ
nipetur ambarāt tūrṇaṃ rākṣasāḥ sāgarāmbhasi', null, 7007049),
('ramayana-7-7-50', 50, 'Uttara Kanda, Sarga 7, Verse 50', 'तदाम्बरं विगलितहारकुण्डलैर्निशाचरैर्नीलबलाहकोपमैः।
निपात्यमानैर्ददृशे निरन्तरं निपात्यमानैरिव नीलपर्वतैः॥', 'tadāmbaraṃ vigalitahārakuṇḍalair niśācarair nīlabalāhakopamaiḥ
nipātyamānair dadṛśe nirantaraṃ nipātyamānair iva nīlaparvataiḥ', null, 7007050)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 8 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-8-1', 1, 'Uttara Kanda, Sarga 8, Verse 1', 'हन्यमाने बले तस्मिन्पद्मनाभेन पृष्ठतः।
माल्यवान्संनिवृत्तोऽथ वेलातिग इवार्णवः॥', 'hanyamāne bale tasmin padmanābhena pṛṣṭhataḥ
mālyavān saṃnivṛtto ''tha velātiga ivārṇavaḥ', null, 7008001),
('ramayana-7-8-2', 2, 'Uttara Kanda, Sarga 8, Verse 2', 'संरक्तनयनः कोपाच्चलन्मौलिर्निशाचरः।
पद्मनाभमिदं प्राह वचनं परुषं तदा॥', 'saṃraktanayanaḥ kopāc calan maulir niśācaraḥ
padmanābham idaṃ prāha vacanaṃ paruṣaṃ tadā', null, 7008002),
('ramayana-7-8-3', 3, 'Uttara Kanda, Sarga 8, Verse 3', 'नारायण न जानीषे क्षत्रधर्मं सनातनम्।
अयुद्धमनसो भग्नान्योऽस्मान्हंसि यथेतरः॥', 'nārāyaṇa na jānīṣe kṣatradharmaṃ sanātanam
ayuddhamanaso bhagnān yo ''smān haṃsi yathetaraḥ', null, 7008003),
('ramayana-7-8-4', 4, 'Uttara Kanda, Sarga 8, Verse 4', 'पराङ्मुखवधं पापं यः करोति सुरेश्वर।
स हन्ता न गतः स्वर्गं लभते पुण्यकर्मणाम्॥', 'parāṅmukhavadhaṃ pāpaṃ yaḥ karoti sureśvara
sa hantā na gataḥ svargaṃ labhate puṇyakarmaṇām', null, 7008004),
('ramayana-7-8-5', 5, 'Uttara Kanda, Sarga 8, Verse 5', 'युद्धश्रद्धाथ वा तेऽस्ति शङ्खचक्रगदाधर।
अहं स्थितोऽस्मि पश्यामि बलं दर्शय यत्तव॥', 'yuddhaśraddhātha vā te ''sti śaṅkhacakragadādhara
ahaṃ sthito ''smi paśyāmi balaṃ darśaya yat tava', null, 7008005),
('ramayana-7-8-6', 6, 'Uttara Kanda, Sarga 8, Verse 6', 'उवाच राक्षसेन्द्रं तं देवराजानुजो बली।
युष्मत्तो भयभीतानां देवानां वै मयाभयम्।
राक्षसोत्सादनं दत्तं तदेतदनुपाल्यते॥', 'uvāca rākṣasendraṃ taṃ devarājānujo balī
yuṣmatto bhayabhītānāṃ devānāṃ vai mayābhayam
rākṣasotsādanaṃ dattaṃ tad etad anupālyate', null, 7008006),
('ramayana-7-8-7', 7, 'Uttara Kanda, Sarga 8, Verse 7', 'प्राणैरपि प्रियं कार्यं देवानां हि सदा मया।
सोऽहं वो निहनिष्यामि रसातलगतानपि॥', 'prāṇair api priyaṃ kāryaṃ devānāṃ hi sadā mayā
so ''haṃ vo nihaniṣyāmi rasātalagatān api', null, 7008007),
('ramayana-7-8-8', 8, 'Uttara Kanda, Sarga 8, Verse 8', 'देवमेवं ब्रुवाणं तु रक्ताम्बुरुहलोचनम्।
शक्त्या बिभेद संक्रुद्धो राक्षसेन्द्रो ररास च॥', 'devam evaṃ bruvāṇaṃ tu raktāmburuhalocanam
śaktyā bibheda saṃkruddho rākṣasendro rarāsa ca', null, 7008008),
('ramayana-7-8-9', 9, 'Uttara Kanda, Sarga 8, Verse 9', 'माल्यवद्भुजनिर्मुक्ता शक्तिर्घण्टाकृतस्वना।
हरेरुरसि बभ्राज मेघस्थेव शतह्रदा॥', 'mālyavad bhujanirmuktā śaktir ghaṇṭākṛtasvanā
harer urasi babhrāja meghastheva śatahradā', null, 7008009),
('ramayana-7-8-10', 10, 'Uttara Kanda, Sarga 8, Verse 10', 'ततस्तामेव चोत्कृष्य शक्तिं शक्तिधरप्रियः।
माल्यवन्तं समुद्दिश्य चिक्षेपाम्बुरुहेक्षणः॥', 'tatas tām eva cotkṛṣya śaktiṃ śaktidharapriyaḥ
mālyavantaṃ samuddiśya cikṣepāmburuhekṣaṇaḥ', null, 7008010),
('ramayana-7-8-11', 11, 'Uttara Kanda, Sarga 8, Verse 11', 'स्कन्दोत्सृष्टेव सा शक्तिर्गोविन्दकरनिःसृता।
काङ्क्षन्ती राक्षसं प्रायान्महोल्केवाञ्जनाचलम्॥', 'skandotsṛṣṭeva sā śaktir govindakaraniḥsṛtā
kāṅkṣantī rākṣasaṃ prāyān maholkevāñjanācalam', null, 7008011),
('ramayana-7-8-12', 12, 'Uttara Kanda, Sarga 8, Verse 12', 'सा तस्योरसि विस्तीर्णे हारभासावभासिते।
अपतद्राक्षसेन्द्रस्य गिरिकूट इवाशनिः॥', 'sā tasyorasi vistīrṇe hārabhāsāvabhāsite
apatad rākṣasendrasya girikūṭa ivāśaniḥ', null, 7008012),
('ramayana-7-8-13', 13, 'Uttara Kanda, Sarga 8, Verse 13', 'तया भिन्नतनुत्राणाः प्राविशद्विपुलं तमः।
माल्यवान्पुनराश्वस्तस्तस्थौ गिरिरिवाचलः॥', 'tayā bhinnatanutrāṇāḥ prāviśad vipulaṃ tamaḥ
mālyavān punar āśvastas tasthau girir ivācalaḥ', null, 7008013),
('ramayana-7-8-14', 14, 'Uttara Kanda, Sarga 8, Verse 14', 'ततः कार्ष्णायसं शूलं कण्टकैर्बहुभिश्चितम्।
प्रगृह्याभ्यहनद्देवं स्तनयोरन्तरे दृढम्॥', 'tataḥ kārṣṇāyasaṃ śūlaṃ kaṇṭakair bahubhiś citam
pragṛhyābhyahanad devaṃ stanayor antare dṛḍham', null, 7008014),
('ramayana-7-8-15', 15, 'Uttara Kanda, Sarga 8, Verse 15', 'तथैव रणरक्तस्तु मुष्टिना वासवानुजम्।
ताडयित्वा धनुर्मात्रमपक्रान्तो निशाचरः॥', 'tathaiva raṇaraktas tu muṣṭinā vāsavānujam
tāḍayitvā dhanurmātram apakrānto niśācaraḥ', null, 7008015),
('ramayana-7-8-16', 16, 'Uttara Kanda, Sarga 8, Verse 16', 'ततोऽम्बरे महाञ्शब्दः साधु साध्विति चोत्थितः।
आहत्य राक्षसो विष्णुं गरुडं चाप्यताडयत्॥', 'tato ''mbare mahāñ śabdaḥ sādhu sādhv iti cotthitaḥ
āhatya rākṣaso viṣṇuṃ garuḍaṃ cāpy atāḍayat', null, 7008016),
('ramayana-7-8-17', 17, 'Uttara Kanda, Sarga 8, Verse 17', 'वैनतेयस्ततः क्रुद्धः पक्षवातेन राक्षसं।
व्यपोहद्बलवान्वायुः शुष्कपर्णचयं यथा॥', 'vainateyas tataḥ kruddhaḥ pakṣavātena rākṣasaṃ
vyapohad balavān vāyuḥ śuṣkaparṇacayaṃ yathā', null, 7008017),
('ramayana-7-8-18', 18, 'Uttara Kanda, Sarga 8, Verse 18', 'द्विजेन्द्रपक्षवातेन द्रावितं दृश्य पूर्वजम्।
सुमाली स्वबलैः सार्धं लङ्कामभिमुखो ययौ॥', 'dvijendrapakṣavātena drāvitaṃ dṛśya pūrvajam
sumālī svabalaiḥ sārdhaṃ laṅkām abhimukho yayau', null, 7008018),
('ramayana-7-8-19', 19, 'Uttara Kanda, Sarga 8, Verse 19', 'पक्षवातबलोद्धूतो माल्यवानपि राक्षसः।
स्वबलेन समागम्य ययौ लङ्कां ह्रिया वृतः॥', 'pakṣavātabaloddhūto mālyavān api rākṣasaḥ
svabalena samāgamya yayau laṅkāṃ hriyā vṛtaḥ', null, 7008019),
('ramayana-7-8-20', 20, 'Uttara Kanda, Sarga 8, Verse 20', 'एवं ते राक्षसा राम हरिणा कमलेक्षण।
बहुशः संयुगे भग्ना हतप्रवरनायकाः॥', 'evaṃ te rākṣasā rāma hariṇā kamalekṣaṇa
bahuśaḥ saṃyuge bhagnā hatapravaranāyakāḥ', null, 7008020),
('ramayana-7-8-21', 21, 'Uttara Kanda, Sarga 8, Verse 21', 'अशक्नुवन्तस्ते विष्णुं प्रतियोद्धुं भयार्दिताः।
त्यक्त्वा लङ्कां गता वस्तुं पातालं सहपत्नयः॥', 'aśaknuvantas te viṣṇuṃ pratiyoddhuṃ bhayārditāḥ
tyaktvā laṅkāṃ gatā vastuṃ pātālaṃ sahapatnayaḥ', null, 7008021),
('ramayana-7-8-22', 22, 'Uttara Kanda, Sarga 8, Verse 22', 'सुमालिनं समासाद्य राक्षसं रघुनन्दन।
स्थिताः प्रख्यातवीर्यास्ते वंशे सालकटङ्कटे॥', 'sumālinaṃ samāsādya rākṣasaṃ raghunandana
sthitāḥ prakhyātavīryās te vaṃśe sālakaṭaṅkaṭe', null, 7008022),
('ramayana-7-8-23', 23, 'Uttara Kanda, Sarga 8, Verse 23', 'ये त्वया निहतास्ते वै पौलस्त्या नाम राक्षसाः।
सुमाली माल्यवान्माली ये च तेषां पुरःसराः।
सर्व एते महाभाग रावणाद्बलवत्तराः॥', 'ye tvayā nihatās te vai paulastyā nāma rākṣasāḥ
sumālī mālyavān mālī ye ca teṣāṃ puraḥsarāḥ
sarva ete mahābhāga rāvaṇād balavattarāḥ', null, 7008023),
('ramayana-7-8-24', 24, 'Uttara Kanda, Sarga 8, Verse 24', 'न चान्यो रक्षसां हन्ता सुरेष्वपि पुरंजय।
ऋते नारायणं देवं शङ्खचक्रगदाधरम्॥', 'na cānyo rakṣasāṃ hantā sureṣv api puraṃjaya
ṛte nārāyaṇaṃ devaṃ śaṅkhacakragadādharam', null, 7008024),
('ramayana-7-8-25', 25, 'Uttara Kanda, Sarga 8, Verse 25', 'भवान्नारायणो देवश्चतुर्बाहुः सनातनः।
राक्षसान्हन्तुमुत्पन्नो अजेयः प्रभुरव्ययः॥', 'bhavān nārāyaṇo devaś caturbāhuḥ sanātanaḥ
rākṣasān hantum utpanno ajeyaḥ prabhur avyayaḥ', null, 7008025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 9 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-9-1', 1, 'Uttara Kanda, Sarga 9, Verse 1', 'कस्य चित्त्वथ कालस्य सुमाली नाम राक्षसः।
रसातलान्मर्त्यलोकं सर्वं वै विचचार ह॥', 'kasya cit tv atha kālasya sumālī nāma rākṣasaḥ
rasātalān martyalokaṃ sarvaṃ vai vicacāra ha', null, 7009001),
('ramayana-7-9-2', 2, 'Uttara Kanda, Sarga 9, Verse 2', 'नीलजीमूतसंकाशस्तप्तकाञ्चनकुण्डलः।
कन्यां दुहितरं गृह्य विना पद्ममिव श्रियम्।
अथापश्यत्स गच्छन्तं पुष्पकेण धनेश्वरम्॥', 'nīlajīmūtasaṃkāśas taptakāñcanakuṇḍalaḥ
kanyāṃ duhitaraṃ gṛhya vinā padmam iva śriyam
athāpaśyat sa gacchantaṃ puṣpakeṇa dhaneśvaram', null, 7009002),
('ramayana-7-9-3', 3, 'Uttara Kanda, Sarga 9, Verse 3', 'तं दृष्ट्वामरसंकाशं गच्छन्तं पावकोपमम्।
अथाब्ब्रवीत्सुतां रक्षः कैकसीं नाम नामतः॥', 'taṃ dṛṣṭvāmarasaṃkāśaṃ gacchantaṃ pāvakopamam
athābbravīt sutāṃ rakṣaḥ kaikasīṃ nāma nāmataḥ', null, 7009003),
('ramayana-7-9-4', 4, 'Uttara Kanda, Sarga 9, Verse 4', 'पुत्रि प्रदानकालोऽयं यौवनं तेऽतिवर्तते।
त्वत्कृते च वयं सर्वे यन्त्रिता धर्मबुद्धयः॥', 'putri pradānakālo ''yaṃ yauvanaṃ te ''tivartate
tvatkṛte ca vayaṃ sarve yantritā dharmabuddhayaḥ', null, 7009004),
('ramayana-7-9-5', 5, 'Uttara Kanda, Sarga 9, Verse 5', 'त्वं हि सर्वगुणोपेता श्रीः सपद्मेव पुत्रिके।
प्रत्याख्यानाच्च भीतैस्त्वं न वरैः प्रतिगृह्यसे॥', 'tvaṃ hi sarvaguṇopetā śrīḥ sapadmeva putrike
pratyākhyānāc ca bhītais tvaṃ na varaiḥ pratigṛhyase', null, 7009005),
('ramayana-7-9-6', 6, 'Uttara Kanda, Sarga 9, Verse 6', 'कन्यापितृत्वं दुःखं हि सर्वेषां मानकाङ्क्षिणाम्।
न ज्ञायते च कः कन्यां वरयेदिति पुत्रिके॥', 'kanyāpitṛtvaṃ duḥkhaṃ hi sarveṣāṃ mānakāṅkṣiṇām
na jñāyate ca kaḥ kanyāṃ varayed iti putrike', null, 7009006),
('ramayana-7-9-7', 7, 'Uttara Kanda, Sarga 9, Verse 7', 'मातुः कुलं पितृकुलं यत्र चैव प्रदीयते।
कुलत्रयं सदा कन्या संशये स्थाप्य तिष्ठति॥', 'mātuḥ kulaṃ pitṛkulaṃ yatra caiva pradīyate
kulatrayaṃ sadā kanyā saṃśaye sthāpya tiṣṭhati', null, 7009007),
('ramayana-7-9-8', 8, 'Uttara Kanda, Sarga 9, Verse 8', 'सा त्वं मुनिवरश्रेष्ठं प्रजापतिकुलोद्भवम्।
गच्छ विश्रवसं पुत्रि पौलस्त्यं वरय स्वयम्॥', 'sā tvaṃ munivaraśreṣṭhaṃ prajāpatikulodbhavam
gaccha viśravasaṃ putri paulastyaṃ varaya svayam', null, 7009008),
('ramayana-7-9-9', 9, 'Uttara Kanda, Sarga 9, Verse 9', 'ईदृशास्ते भविष्यन्ति पुत्राः पुत्रि न संशयः।
तेजसा भास्करसमा यादृशोऽयं धनेश्वरः॥', 'īdṛśās te bhaviṣyanti putrāḥ putri na saṃśayaḥ
tejasā bhāskarasamā yādṛśo ''yaṃ dhaneśvaraḥ', null, 7009009),
('ramayana-7-9-10', 10, 'Uttara Kanda, Sarga 9, Verse 10', 'एतस्मिन्नन्तरे राम पुलस्त्यतनयो द्विजः।
अग्निहोत्रमुपातिष्ठच्चतुर्थ इव पावकः॥', 'etasminn antare rāma pulastyatanayo dvijaḥ
agnihotram upātiṣṭhac caturtha iva pāvakaḥ', null, 7009010),
('ramayana-7-9-11', 11, 'Uttara Kanda, Sarga 9, Verse 11', 'सा तु तां दारुणां वेलामचिन्त्य पितृगौरवात्।
उपसृत्याग्रतस्तस्य चरणाधोमुखी स्थिता॥', 'sā tu tāṃ dāruṇāṃ velām acintya pitṛgauravāt
upasṛtyāgratas tasya caraṇādhomukhī sthitā', null, 7009011),
('ramayana-7-9-12', 12, 'Uttara Kanda, Sarga 9, Verse 12', 'स तु तां वीक्ष्य सुश्रोणीं पूर्णचन्द्रनिभाननाम्।
अब्रवीत्परमोदारो दीप्यमान इवौजसा॥', 'sa tu tāṃ vīkṣya suśroṇīṃ pūrṇacandranibhānanām
abravīt paramodāro dīpyamāna ivaujasā', null, 7009012),
('ramayana-7-9-13', 13, 'Uttara Kanda, Sarga 9, Verse 13', 'भद्रे कस्यासि दुहिता कुतो वा त्वमिहागता।
किं कार्यं कस्य वा हेतोस्तत्त्वतो ब्रूहि शोभने॥', 'bhadre kasyāsi duhitā kuto vā tvam ihāgatā
kiṃ kāryaṃ kasya vā hetos tattvato brūhi śobhane', null, 7009013),
('ramayana-7-9-14', 14, 'Uttara Kanda, Sarga 9, Verse 14', 'एवमुक्ता तु सा कन्या कृताञ्जलिरथाब्रवीत्।
आत्मप्रभावेन मुने ज्ञातुमर्हसि मे मतम्॥', 'evam uktā tu sā kanyā kṛtāñjalir athābravīt
ātmaprabhāvena mune jñātum arhasi me matam', null, 7009014),
('ramayana-7-9-15', 15, 'Uttara Kanda, Sarga 9, Verse 15', 'किं तु विद्धि हि मां ब्रह्मञ्शासनात्पितुरागताम्।
कैकसी नाम नाम्नाहं शेषं त्वं ज्ञातुमर्हसि॥', 'kiṃ tu viddhi hi māṃ brahmañ śāsanāt pitur āgatām
kaikasī nāma nāmnāhaṃ śeṣaṃ tvaṃ jñātum arhasi', null, 7009015),
('ramayana-7-9-16', 16, 'Uttara Kanda, Sarga 9, Verse 16', 'स तु गत्वा मुनिर्ध्यानं वाक्यमेतदुवाच ह।
विज्ञातं ते मया भद्रे कारणं यन्मनोगतम्॥', 'sa tu gatvā munir dhyānaṃ vākyam etad uvāca ha
vijñātaṃ te mayā bhadre kāraṇaṃ yan manogatam', null, 7009016),
('ramayana-7-9-17', 17, 'Uttara Kanda, Sarga 9, Verse 17', 'दारुणायां तु वेलायां यस्मात्त्वं मामुपस्थिता।
शृणु तस्मात्सुतान्भद्रे यादृशाञ्जनयिष्यसि॥', 'dāruṇāyāṃ tu velāyāṃ yasmāt tvaṃ mām upasthitā
śṛṇu tasmāt sutān bhadre yādṛśāñ janayiṣyasi', null, 7009017),
('ramayana-7-9-18', 18, 'Uttara Kanda, Sarga 9, Verse 18', 'दारुणान्दारुणाकारान्दारुणाभिजनप्रियान्।
प्रसविष्यसि सुश्रोणि राक्षसान्क्रूरकर्मणः॥', 'dāruṇān dāruṇākārān dāruṇābhijanapriyān
prasaviṣyasi suśroṇi rākṣasān krūrakarmaṇaḥ', null, 7009018),
('ramayana-7-9-19', 19, 'Uttara Kanda, Sarga 9, Verse 19', 'सा तु तद्वचनं श्रुत्वा प्रणिपत्याब्रवीद्वचः।
भगवन्नेदृशाः पुत्रास्त्वत्तोऽर्हा ब्रह्मयोनितः॥', 'sā tu tad vacanaṃ śrutvā praṇipatyābravīd vacaḥ
bhagavan nedṛśāḥ putrās tvatto ''rhā brahmayonitaḥ', null, 7009019),
('ramayana-7-9-20', 20, 'Uttara Kanda, Sarga 9, Verse 20', 'अथाब्रवीन्मुनिस्तत्र पश्चिमो यस्तवात्मजः।
मम वंशानुरूपश्च धर्मात्मा च भविष्यति॥', 'athābravīn munis tatra paścimo yas tavātmajaḥ
mama vaṃśānurūpaś ca dharmātmā ca bhaviṣyati', null, 7009020),
('ramayana-7-9-21', 21, 'Uttara Kanda, Sarga 9, Verse 21', 'एवमुक्ता तु सा कन्या राम कालेन केन चित्।
जनयामास बीभत्सं रक्षोरूपं सुदारुणम्॥', 'evam uktā tu sā kanyā rāma kālena kena cit
janayām āsa bībhatsaṃ rakṣorūpaṃ sudāruṇam', null, 7009021),
('ramayana-7-9-22', 22, 'Uttara Kanda, Sarga 9, Verse 22', 'दशशीर्षं महादंष्ट्रं नीलाञ्जनचयोपमम्।
ताम्रौष्ठं विंशतिभुजं महास्यं दीप्तमूर्धजम्॥', 'daśaśīrṣaṃ mahādaṃṣṭraṃ nīlāñjanacayopamam
tāmrauṣṭhaṃ viṃśatibhujaṃ mahāsyaṃ dīptamūrdhajam', null, 7009022),
('ramayana-7-9-23', 23, 'Uttara Kanda, Sarga 9, Verse 23', 'जातमात्रे ततस्तस्मिन्सज्वालकवलाः शिवाः।
क्रव्यादाश्चापसव्यानि मण्डलानि प्रचक्रिरे॥', 'jātamātre tatas tasmin sajvālakavalāḥ śivāḥ
kravyādāś cāpasavyāni maṇḍalāni pracakrire', null, 7009023),
('ramayana-7-9-24', 24, 'Uttara Kanda, Sarga 9, Verse 24', 'ववर्ष रुधिरं देवो मेघाश्च खरनिस्वनाः।
प्रबभौ न च खे सूर्यो महोल्काश्चापतन्भुवि॥', 'vavarṣa rudhiraṃ devo meghāś ca kharanisvanāḥ
prababhau na ca khe sūryo maholkāś cāpatan bhuvi', null, 7009024),
('ramayana-7-9-25', 25, 'Uttara Kanda, Sarga 9, Verse 25', 'अथ नामाकरोत्तस्य पितामहसमः पिता।
दशशीर्षः प्रसूतोऽयं दशग्रीवो भविष्यति॥', 'atha nāmākarot tasya pitāmahasamaḥ pitā
daśaśīrṣaḥ prasūto ''yaṃ daśagrīvo bhaviṣyati', null, 7009025),
('ramayana-7-9-26', 26, 'Uttara Kanda, Sarga 9, Verse 26', 'तस्य त्वनन्तरं जातः कुम्भकर्णो महाबलः।
प्रमाणाद्यस्य विपुलं प्रमाणं नेह विद्यते॥', 'tasya tv anantaraṃ jātaḥ kumbhakarṇo mahābalaḥ
pramāṇād yasya vipulaṃ pramāṇaṃ neha vidyate', null, 7009026),
('ramayana-7-9-27', 27, 'Uttara Kanda, Sarga 9, Verse 27', 'ततः शूर्पणखा नाम संजज्ञे विकृतानना।
विभीषणश्च धर्मात्मा कैकस्याः पश्चिमः सुतः॥', 'tataḥ śūrpaṇakhā nāma saṃjajñe vikṛtānanā
vibhīṣaṇaś ca dharmātmā kaikasyāḥ paścimaḥ sutaḥ', null, 7009027),
('ramayana-7-9-28', 28, 'Uttara Kanda, Sarga 9, Verse 28', 'ते तु तत्र महारण्ये ववृधुः सुमहौजसः।
तेषां क्रूरो दशग्रीवो लोकोद्वेगकरोऽभवत्॥', 'te tu tatra mahāraṇye vavṛdhuḥ sumahaujasaḥ
teṣāṃ krūro daśagrīvo lokodvegakaro ''bhavat', null, 7009028),
('ramayana-7-9-29', 29, 'Uttara Kanda, Sarga 9, Verse 29', 'कुम्भकर्णः प्रमत्तस्तु महर्षीन्धर्मसंश्रितान्।
त्रैलोक्यं त्रासयन्दुष्टो भक्षयन्विचचार ह॥', 'kumbhakarṇaḥ pramattas tu maharṣīn dharmasaṃśritān
trailokyaṃ trāsayan duṣṭo bhakṣayan vicacāra ha', null, 7009029),
('ramayana-7-9-30', 30, 'Uttara Kanda, Sarga 9, Verse 30', 'विभीषणस्तु धर्मात्मा नित्यं धर्मपथे स्थितः।
स्वाध्यायनियताहार उवास नियतेन्द्रियः॥', 'vibhīṣaṇas tu dharmātmā nityaṃ dharmapathe sthitaḥ
svādhyāyaniyatāhāra uvāsa niyatendriyaḥ', null, 7009030),
('ramayana-7-9-31', 31, 'Uttara Kanda, Sarga 9, Verse 31', 'अथ वित्तेश्वरो देवस्तत्र कालेन केन चित्।
आगच्छत्पितरं द्रष्टुं पुष्पकेण महौजसं॥', 'atha vitteśvaro devas tatra kālena kena cit
āgacchat pitaraṃ draṣṭuṃ puṣpakeṇa mahaujasaṃ', null, 7009031),
('ramayana-7-9-32', 32, 'Uttara Kanda, Sarga 9, Verse 32', 'तं दृष्ट्वा कैकसी तत्र ज्वलन्तमिव तेजसा।
आस्थाय राक्षसीं बुद्धिं दशग्रीवमुवाच ह॥', 'taṃ dṛṣṭvā kaikasī tatra jvalantam iva tejasā
āsthāya rākṣasīṃ buddhiṃ daśagrīvam uvāca ha', null, 7009032),
('ramayana-7-9-33', 33, 'Uttara Kanda, Sarga 9, Verse 33', 'पुत्रवैश्रवणं पश्य भ्रातरं तेजसा वृतम्।
भ्रातृभावे समे चापि पश्यात्मानं त्वमीदृशम्॥', 'putravaiśravaṇaṃ paśya bhrātaraṃ tejasā vṛtam
bhrātṛbhāve same cāpi paśyātmānaṃ tvam īdṛśam', null, 7009033),
('ramayana-7-9-34', 34, 'Uttara Kanda, Sarga 9, Verse 34', 'दशग्रीव तथा यत्नं कुरुष्वामितविक्रम।
यथा भवसि मे पुत्र शीघ्रं वैश्वरणोपमः॥', 'daśagrīva tathā yatnaṃ kuruṣvāmitavikrama
yathā bhavasi me putra śīghraṃ vaiśvaraṇopamaḥ', null, 7009034),
('ramayana-7-9-35', 35, 'Uttara Kanda, Sarga 9, Verse 35', 'मातुस्तद्वचनं श्रुत्वा दशग्रीवः प्रतापवान्।
अमर्षमतुलं लेभे प्रतिज्ञां चाकरोत्तदा॥', 'mātus tad vacanaṃ śrutvā daśagrīvaḥ pratāpavān
amarṣam atulaṃ lebhe pratijñāṃ cākarot tadā', null, 7009035),
('ramayana-7-9-36', 36, 'Uttara Kanda, Sarga 9, Verse 36', 'सत्यं ते प्रतिजानामि तुल्यो भ्रात्राधिकोऽपि वा।
भविष्याम्यचिरान्मातः संतापं त्यज हृद्गतम्॥', 'satyaṃ te pratijānāmi tulyo bhrātrādhiko ''pi vā
bhaviṣyāmy acirān mātaḥ saṃtāpaṃ tyaja hṛdgatam', null, 7009036),
('ramayana-7-9-37', 37, 'Uttara Kanda, Sarga 9, Verse 37', 'ततः क्रोधेन तेनैव दशग्रीवः सहानुजः।
प्राप्स्यामि तपसा काममिति कृत्वाध्यवस्य च।
आगच्छदात्मसिद्ध्यर्थं गोकर्णस्याश्रमं शुभम्॥', 'tataḥ krodhena tenaiva daśagrīvaḥ sahānujaḥ
prāpsyāmi tapasā kāmam iti kṛtvādhyavasya ca
āgacchad ātmasiddhyarthaṃ gokarṇasyāśramaṃ śubham', null, 7009037)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 10 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-10-1', 1, 'Uttara Kanda, Sarga 10, Verse 1', 'अथाब्रवीद्द्विजं रामः कथं ते भ्रातरो वने।
कीदृशं तु तदा ब्रह्मंस्तपश्चेरुर्महाव्रताः॥', 'athābravīd dvijaṃ rāmaḥ kathaṃ te bhrātaro vane
kīdṛśaṃ tu tadā brahmaṃs tapaś cerur mahāvratāḥ', null, 7010001),
('ramayana-7-10-2', 2, 'Uttara Kanda, Sarga 10, Verse 2', 'अगस्त्यस्त्वब्रवीत्तत्र रामं प्रयत मानसं।
तांस्तान्धर्मविधींस्तत्र भ्रातरस्ते समाविशन्॥', 'agastyas tv abravīt tatra rāmaṃ prayata mānasaṃ
tāṃs tān dharmavidhīṃs tatra bhrātaras te samāviśan', null, 7010002),
('ramayana-7-10-3', 3, 'Uttara Kanda, Sarga 10, Verse 3', 'कुम्भकर्णस्तदा यत्तो नित्यं धर्मपरायणः।
तताप ग्रैष्मिके काले पञ्चस्वग्निष्ववस्थितः॥', 'kumbhakarṇas tadā yatto nityaṃ dharmaparāyaṇaḥ
tatāpa graiṣmike kāle pañcasv agniṣv avasthitaḥ', null, 7010003),
('ramayana-7-10-4', 4, 'Uttara Kanda, Sarga 10, Verse 4', 'वर्षे मेघोदकक्लिन्नो वीरासनमसेवत।
नित्यं च शैशिरे काले जलमध्यप्रतिश्रयः॥', 'varṣe meghodakaklinno vīrāsanam asevata
nityaṃ ca śaiśire kāle jalamadhyapratiśrayaḥ', null, 7010004),
('ramayana-7-10-5', 5, 'Uttara Kanda, Sarga 10, Verse 5', 'एवं वर्षसहस्राणि दश तस्यातिचक्रमुः।
धर्मे प्रयतमानस्य सत्पथे निष्ठितस्य च॥', 'evaṃ varṣasahasrāṇi daśa tasyāticakramuḥ
dharme prayatamānasya satpathe niṣṭhitasya ca', null, 7010005),
('ramayana-7-10-6', 6, 'Uttara Kanda, Sarga 10, Verse 6', 'विभीषणस्तु धर्मात्मा नित्यं धर्मपरः शुचिः।
पञ्चवर्षसहस्राणि पादेनैकेन तस्थिवान्॥', 'vibhīṣaṇas tu dharmātmā nityaṃ dharmaparaḥ śuciḥ
pañcavarṣasahasrāṇi pādenaikena tasthivān', null, 7010006),
('ramayana-7-10-7', 7, 'Uttara Kanda, Sarga 10, Verse 7', 'समाप्ते नियमे तस्य ननृतुश्चाप्सरोगणाः।
पपात पुष्पवर्षं च क्षुभिताश्चापि देवताः॥', 'samāpte niyame tasya nanṛtuś cāpsarogaṇāḥ
papāta puṣpavarṣaṃ ca kṣubhitāś cāpi devatāḥ', null, 7010007),
('ramayana-7-10-8', 8, 'Uttara Kanda, Sarga 10, Verse 8', 'पञ्चवर्षसहस्राणि सूर्यं चैवान्ववर्तत।
तस्थौ चोर्ध्वशिरो बाहुः स्वाध्यायधृतमानसः॥', 'pañcavarṣasahasrāṇi sūryaṃ caivānvavartata
tasthau cordhvaśiro bāhuḥ svādhyāyadhṛtamānasaḥ', null, 7010008),
('ramayana-7-10-9', 9, 'Uttara Kanda, Sarga 10, Verse 9', 'एवं विभीषणस्यापि गतानि नियतात्मनः।
दशवर्षसहस्राणि स्वर्गस्थस्येव नन्दने॥', 'evaṃ vibhīṣaṇasyāpi gatāni niyatātmanaḥ
daśavarṣasahasrāṇi svargasthasyeva nandane', null, 7010009),
('ramayana-7-10-10', 10, 'Uttara Kanda, Sarga 10, Verse 10', 'दशवर्षसहस्रं तु निराहारो दशाननः।
पूर्णे वर्षसहस्रे तु शिरश्चाग्नौ जुहाव सः॥', 'daśavarṣasahasraṃ tu nirāhāro daśānanaḥ
pūrṇe varṣasahasre tu śiraś cāgnau juhāva saḥ', null, 7010010),
('ramayana-7-10-11', 11, 'Uttara Kanda, Sarga 10, Verse 11', 'एवं वर्षसहस्राणि नव तस्यातिचक्रमुः।
शिरांसि नव चाप्यस्य प्रविष्टानि हुताशनम्॥', 'evaṃ varṣasahasrāṇi nava tasyāticakramuḥ
śirāṃsi nava cāpy asya praviṣṭāni hutāśanam', null, 7010011),
('ramayana-7-10-12', 12, 'Uttara Kanda, Sarga 10, Verse 12', 'अथ वर्षसहस्रे तु दशमे दशमं शिरः।
छेत्तुकामः स धर्मात्मा प्राप्तश्चात्र पितामहः॥', 'atha varṣasahasre tu daśame daśamaṃ śiraḥ
chettukāmaḥ sa dharmātmā prāptaś cātra pitāmahaḥ', null, 7010012),
('ramayana-7-10-13', 13, 'Uttara Kanda, Sarga 10, Verse 13', 'पितामहस्तु सुप्रीतः सार्धं देवैरुपस्थितः।
वत्स वत्स दशग्रीव प्रीतोऽस्मीत्यभ्यभाषत॥', 'pitāmahas tu suprītaḥ sārdhaṃ devair upasthitaḥ
vatsa vatsa daśagrīva prīto ''smīty abhyabhāṣata', null, 7010013),
('ramayana-7-10-14', 14, 'Uttara Kanda, Sarga 10, Verse 14', 'शीघ्रं वरय धर्मज्ञ वरो यस्तेऽभिकाङ्क्षितः।
किं ते कामं करोम्यद्य न वृथा ते परिश्रमः॥', 'śīghraṃ varaya dharmajña varo yas te ''bhikāṅkṣitaḥ
kiṃ te kāmaṃ karomy adya na vṛthā te pariśramaḥ', null, 7010014),
('ramayana-7-10-15', 15, 'Uttara Kanda, Sarga 10, Verse 15', 'ततोऽब्रवीद्दशग्रीवः प्रहृष्टेनान्तरात्मना।
प्रणम्य शिरसा देवं हर्षगद्गदया गिरा॥', 'tato ''bravīd daśagrīvaḥ prahṛṣṭenāntarātmanā
praṇamya śirasā devaṃ harṣagadgadayā girā', null, 7010015),
('ramayana-7-10-16', 16, 'Uttara Kanda, Sarga 10, Verse 16', 'भगवन्प्राणिनां नित्यं नान्यत्र मरणाद्भयम्।
नास्ति मृत्युसमः शत्रुरमरत्वमतो वृणे॥', 'bhagavan prāṇināṃ nityaṃ nānyatra maraṇād bhayam
nāsti mṛtyusamaḥ śatrur amaratvam ato vṛṇe', null, 7010016),
('ramayana-7-10-17', 17, 'Uttara Kanda, Sarga 10, Verse 17', 'सुपर्णनागयक्षाणां दैत्यदानवरक्षसाम्।
अवध्यः स्यां प्रजाध्यक्ष देवतानां च शाश्वतम्॥', 'suparṇanāgayakṣāṇāṃ daityadānavarakṣasām
avadhyaḥ syāṃ prajādhyakṣa devatānāṃ ca śāśvatam', null, 7010017),
('ramayana-7-10-18', 18, 'Uttara Kanda, Sarga 10, Verse 18', 'न हि चिन्ता ममान्येषु प्राणिष्वमरपूजित।
तृणभूता हि मे सर्वे प्राणिनो मानुषादयः॥', 'na hi cintā mamānyeṣu prāṇiṣv amarapūjita
tṛṇabhūtā hi me sarve prāṇino mānuṣādayaḥ', null, 7010018),
('ramayana-7-10-19', 19, 'Uttara Kanda, Sarga 10, Verse 19', 'एवमुक्तस्तु धर्मात्मा दशग्रीवेण रक्षसा।
उवाच वचनं राम सह देवैः पितामहः॥', 'evam uktas tu dharmātmā daśagrīveṇa rakṣasā
uvāca vacanaṃ rāma saha devaiḥ pitāmahaḥ', null, 7010019),
('ramayana-7-10-20', 20, 'Uttara Kanda, Sarga 10, Verse 20', 'भविष्यत्येवमेवैतत्तव राक्षसपुंगव।
शृणु चापि वचो भूयः प्रीतस्येह शुभं मम॥', 'bhaviṣyaty evam evaitat tava rākṣasapuṃgava
śṛṇu cāpi vaco bhūyaḥ prītasyeha śubhaṃ mama', null, 7010020),
('ramayana-7-10-21', 21, 'Uttara Kanda, Sarga 10, Verse 21', 'हुतानि यानि शीर्षाणि पूर्वमग्नौ त्वयानघ।
पुनस्तानि भविष्यन्ति तथैव तव राक्षस॥', 'hutāni yāni śīrṣāṇi pūrvam agnau tvayānagha
punas tāni bhaviṣyanti tathaiva tava rākṣasa', null, 7010021),
('ramayana-7-10-22', 22, 'Uttara Kanda, Sarga 10, Verse 22', 'एवं पितामहोक्तस्य दशग्रीवस्य रक्षसः।
अग्नौ हुतानि शीर्षाणि यानि तान्युत्थितानि वै॥', 'evaṃ pitāmahoktasya daśagrīvasya rakṣasaḥ
agnau hutāni śīrṣāṇi yāni tāny utthitāni vai', null, 7010022),
('ramayana-7-10-23', 23, 'Uttara Kanda, Sarga 10, Verse 23', 'एवमुक्त्व्वा तु तं राम दशग्रीवं प्रजापतिः।
विभीषणमथोवाच वाक्यं लोकपितामहः॥', 'evam uktvvā tu taṃ rāma daśagrīvaṃ prajāpatiḥ
vibhīṣaṇam athovāca vākyaṃ lokapitāmahaḥ', null, 7010023),
('ramayana-7-10-24', 24, 'Uttara Kanda, Sarga 10, Verse 24', 'विभीषण त्वया वत्स धर्मसंहितबुद्धिना।
परितुष्टोऽस्मि धर्मज्ञ वरं वरय सुव्रत॥', 'vibhīṣaṇa tvayā vatsa dharmasaṃhitabuddhinā
parituṣṭo ''smi dharmajña varaṃ varaya suvrata', null, 7010024),
('ramayana-7-10-25', 25, 'Uttara Kanda, Sarga 10, Verse 25', 'विभीषणस्तु धर्मात्मा वचनं प्राह साञ्जलिः।
वृतः सर्वगुणैर्नित्यं चन्द्रमा इव रश्मिभिः॥', 'vibhīṣaṇas tu dharmātmā vacanaṃ prāha sāñjaliḥ
vṛtaḥ sarvaguṇair nityaṃ candramā iva raśmibhiḥ', null, 7010025),
('ramayana-7-10-26', 26, 'Uttara Kanda, Sarga 10, Verse 26', 'भगवन्कृतकृत्योऽहं यन्मे लोकगुरुः स्वयम्।
प्रीतो यदि त्वं दातव्यं वरं मे शृणु सुव्रत॥', 'bhagavan kṛtakṛtyo ''haṃ yan me lokaguruḥ svayam
prīto yadi tvaṃ dātavyaṃ varaṃ me śṛṇu suvrata', null, 7010026),
('ramayana-7-10-27', 27, 'Uttara Kanda, Sarga 10, Verse 27', 'या या मे जायते बुद्धिर्येषु येष्वाश्रमेष्विह।
सा सा भवतु धर्मिष्ठा तं तं धर्मं च पालये॥', 'yā yā me jāyate buddhir yeṣu yeṣv āśrameṣv iha
sā sā bhavatu dharmiṣṭhā taṃ taṃ dharmaṃ ca pālaye', null, 7010027),
('ramayana-7-10-28', 28, 'Uttara Kanda, Sarga 10, Verse 28', 'एष मे परमोदार वरः परमको मतः।
न हि धर्माभिरक्तानां लोके किं चन दुर्लभम्॥', 'eṣa me paramodāra varaḥ paramako mataḥ
na hi dharmābhiraktānāṃ loke kiṃ cana durlabham', null, 7010028),
('ramayana-7-10-29', 29, 'Uttara Kanda, Sarga 10, Verse 29', 'अथ प्रजापतिः प्रीतो विभीषणमुवाच ह।
धर्मिष्ठस्त्वं यथा वत्स तथा चैतद्भविष्यति॥', 'atha prajāpatiḥ prīto vibhīṣaṇam uvāca ha
dharmiṣṭhas tvaṃ yathā vatsa tathā caitad bhaviṣyati', null, 7010029),
('ramayana-7-10-30', 30, 'Uttara Kanda, Sarga 10, Verse 30', 'यस्माद्राक्षसयोनौ ते जातस्यामित्रकर्षण।
नाधर्मे जायते बुद्धिरमरत्वं ददामि ते॥', 'yasmād rākṣasayonau te jātasyāmitrakarṣaṇa
nādharme jāyate buddhir amaratvaṃ dadāmi te', null, 7010030),
('ramayana-7-10-31', 31, 'Uttara Kanda, Sarga 10, Verse 31', 'कुम्भकर्णाय तु वरं प्रयच्छन्तमरिंदम।
प्रजापतिं सुराः सर्वे वाक्यं प्राञ्जलयोऽब्रुवन्॥', 'kumbhakarṇāya tu varaṃ prayacchantam ariṃdama
prajāpatiṃ surāḥ sarve vākyaṃ prāñjalayo ''bruvan', null, 7010031),
('ramayana-7-10-32', 32, 'Uttara Kanda, Sarga 10, Verse 32', 'न तावत्कुम्भकर्णाय प्रदातव्यो वरस्त्वया।
जानीषे हि यथा लोकांस्त्रासयत्येष दुर्मतिः॥', 'na tāvat kumbhakarṇāya pradātavyo varas tvayā
jānīṣe hi yathā lokāṃs trāsayaty eṣa durmatiḥ', null, 7010032),
('ramayana-7-10-33', 33, 'Uttara Kanda, Sarga 10, Verse 33', 'नन्दनेऽप्सरसः सप्त महेन्द्रानुचरा दश।
अनेन भक्षिता ब्रह्मनृषयो मानुषास्तथा॥', 'nandane ''psarasaḥ sapta mahendrānucarā daśa
anena bhakṣitā brahman ṛṣayo mānuṣās tathā', null, 7010033),
('ramayana-7-10-34', 34, 'Uttara Kanda, Sarga 10, Verse 34', 'वरव्याजेन मोहोऽस्मै दीयताममितप्रभ।
लोकानां स्वस्ति चैव स्याद्भवेदस्य च संनतिः॥', 'varavyājena moho ''smai dīyatām amitaprabha
lokānāṃ svasti caiva syād bhaved asya ca saṃnatiḥ', null, 7010034),
('ramayana-7-10-35', 35, 'Uttara Kanda, Sarga 10, Verse 35', 'एवमुक्तः सुरैर्ब्रह्माचिन्तयत्पद्मसंभवः।
चिन्तिता चोपतस्थेऽस्य पार्श्वं देवी सरस्वती॥', 'evam uktaḥ surair brahmācintayat padmasaṃbhavaḥ
cintitā copatasthe ''sya pārśvaṃ devī sarasvatī', null, 7010035),
('ramayana-7-10-36', 36, 'Uttara Kanda, Sarga 10, Verse 36', 'प्राञ्जलिः सा तु पर्श्वस्था प्राह वाक्यं सरस्वती।
इयमस्म्यागता देवकिं कार्यं करवाण्यहम्॥', 'prāñjaliḥ sā tu parśvasthā prāha vākyaṃ sarasvatī
iyam asmy āgatā devakiṃ kāryaṃ karavāṇy aham', null, 7010036),
('ramayana-7-10-37', 37, 'Uttara Kanda, Sarga 10, Verse 37', 'प्रजापतिस्तु तां प्राप्तां प्राह वाक्यं सरस्वतीम्।
वाणि त्वं राक्षसेन्द्रस्य भव या देवतेप्सिता॥', 'prajāpatis tu tāṃ prāptāṃ prāha vākyaṃ sarasvatīm
vāṇi tvaṃ rākṣasendrasya bhava yā devatepsitā', null, 7010037),
('ramayana-7-10-38', 38, 'Uttara Kanda, Sarga 10, Verse 38', 'तथेत्युक्त्वा प्रविष्टा सा प्रजापतिरथाब्रवीत्।
कुम्भकर्ण महाबाहो वरं वरय यो मतः॥', 'tathety uktvā praviṣṭā sā prajāpatir athābravīt
kumbhakarṇa mahābāho varaṃ varaya yo mataḥ', null, 7010038),
('ramayana-7-10-39', 39, 'Uttara Kanda, Sarga 10, Verse 39', 'कुम्भकर्णस्तु तद्वाक्यं श्रुत्वा वचनमब्रवीत्।
स्वप्तुं वर्षाण्यनेकानि देवदेव ममेप्सितम्॥', 'kumbhakarṇas tu tad vākyaṃ śrutvā vacanam abravīt
svaptuṃ varṣāṇy anekāni devadeva mamepsitam', null, 7010039),
('ramayana-7-10-40', 40, 'Uttara Kanda, Sarga 10, Verse 40', 'एवमस्त्विति तं चोक्त्वा सह देवैः पितामहः।
देवी सरस्वती चैव मुक्त्वा तं प्रययौ दिवम्॥', 'evam astv iti taṃ coktvā saha devaiḥ pitāmahaḥ
devī sarasvatī caiva muktvā taṃ prayayau divam', null, 7010040),
('ramayana-7-10-41', 41, 'Uttara Kanda, Sarga 10, Verse 41', 'कुम्भकर्णस्तु दुष्टात्मा चिन्तयामास दुःखितः।
कीर्दृशं किं न्विदं वाक्यं ममाद्य वदनाच्च्युतम्॥', 'kumbhakarṇas tu duṣṭātmā cintayām āsa duḥkhitaḥ
kīrdṛśaṃ kiṃ nv idaṃ vākyaṃ mamādya vadanāc cyutam', null, 7010041),
('ramayana-7-10-42', 42, 'Uttara Kanda, Sarga 10, Verse 42', 'एवं लब्धवराः सर्वे भ्रातरो दीप्ततेजसः।
श्लेष्मातकवनं गत्वा तत्र ते न्यवसन्सुखम्॥', 'evaṃ labdhavarāḥ sarve bhrātaro dīptatejasaḥ
śleṣmātakavanaṃ gatvā tatra te nyavasan sukham', null, 7010042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 11 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-11-1', 1, 'Uttara Kanda, Sarga 11, Verse 1', 'सुमाली वरलब्धांस्तु ज्ञात्वा तान्वै निशाचरान्।
उदतिष्ठद्भयं त्यक्त्वा सानुगः स रसातलात्॥', 'sumālī varalabdhāṃs tu jñātvā tān vai niśācarān
udatiṣṭhad bhayaṃ tyaktvā sānugaḥ sa rasātalāt', null, 7011001),
('ramayana-7-11-2', 2, 'Uttara Kanda, Sarga 11, Verse 2', 'मारीचश्च प्रहस्तश्च विरूपाक्षो महोदरः।
उदतिष्ठन्सुसंरब्धाः सचिवास्तस्य रक्षसः॥', 'mārīcaś ca prahastaś ca virūpākṣo mahodaraḥ
udatiṣṭhan susaṃrabdhāḥ sacivās tasya rakṣasaḥ', null, 7011002),
('ramayana-7-11-3', 3, 'Uttara Kanda, Sarga 11, Verse 3', 'सुमाली चैव तैः सर्वैर्वृतो राक्षसपुंगवैः।
अभिगम्य दशग्रीवं परिष्वज्येदमब्रवीत्॥', 'sumālī caiva taiḥ sarvair vṛto rākṣasapuṃgavaiḥ
abhigamya daśagrīvaṃ pariṣvajyedam abravīt', null, 7011003),
('ramayana-7-11-4', 4, 'Uttara Kanda, Sarga 11, Verse 4', 'दिष्ट्या ते पुत्रसंप्राप्तश्चिन्तितोऽयं मनोरथः।
यस्त्वं त्रिभुवणश्रेष्ठाल्लब्धवान्वरमीदृशम्॥', 'diṣṭyā te putrasaṃprāptaś cintito ''yaṃ manorathaḥ
yas tvaṃ tribhuvaṇaśreṣṭhāl labdhavān varam īdṛśam', null, 7011004),
('ramayana-7-11-5', 5, 'Uttara Kanda, Sarga 11, Verse 5', 'यत्कृते च वयं लङ्कां त्यक्त्वा याता रसातलम्।
तद्गतं नो महाबाहो महद्विष्णुकृतं भयम्॥', 'yatkṛte ca vayaṃ laṅkāṃ tyaktvā yātā rasātalam
tad gataṃ no mahābāho mahad viṣṇukṛtaṃ bhayam', null, 7011005),
('ramayana-7-11-6', 6, 'Uttara Kanda, Sarga 11, Verse 6', 'असकृत्तेन भग्ना हि परित्यज्य स्वमालयम्।
विद्रुताः सहिताः सर्वे प्रविष्टाः स्म रसातलम्॥', 'asakṛt tena bhagnā hi parityajya svam ālayam
vidrutāḥ sahitāḥ sarve praviṣṭāḥ sma rasātalam', null, 7011006),
('ramayana-7-11-7', 7, 'Uttara Kanda, Sarga 11, Verse 7', 'अस्मदीया च लङ्केयं नगरी राक्षसोषिता।
निवेशिता तव भ्रात्रा धनाध्यक्षेण धीमता॥', 'asmadīyā ca laṅkeyaṃ nagarī rākṣasoṣitā
niveśitā tava bhrātrā dhanādhyakṣeṇa dhīmatā', null, 7011007),
('ramayana-7-11-8', 8, 'Uttara Kanda, Sarga 11, Verse 8', 'यदि नामात्र शक्यं स्यात्साम्ना दानेन वानघ।
तरसा वा महाबाहो प्रत्यानेतुं कृतं भवेत्॥', 'yadi nāmātra śakyaṃ syāt sāmnā dānena vānagha
tarasā vā mahābāho pratyānetuṃ kṛtaṃ bhavet', null, 7011008),
('ramayana-7-11-9', 9, 'Uttara Kanda, Sarga 11, Verse 9', 'त्वं च लङ्केश्वरस्तात भविष्यसि न संशयः।
सर्वेषां नः प्रभुश्चैव भविष्यसि महाबल॥', 'tvaṃ ca laṅkeśvaras tāta bhaviṣyasi na saṃśayaḥ
sarveṣāṃ naḥ prabhuś caiva bhaviṣyasi mahābala', null, 7011009),
('ramayana-7-11-10', 10, 'Uttara Kanda, Sarga 11, Verse 10', 'अथाब्रवीद्दशग्रीवो मातामहमुपस्थितम्।
वित्तेशो गुरुरस्माकं नार्हस्येवं प्रभाषितुम्॥', 'athābravīd daśagrīvo mātāmaham upasthitam
vitteśo gurur asmākaṃ nārhasy evaṃ prabhāṣitum', null, 7011010),
('ramayana-7-11-11', 11, 'Uttara Kanda, Sarga 11, Verse 11', 'उक्तवन्तं तथा वाक्यं दशग्रीवं निशाचरः।
प्रहस्तः प्रश्रितं वाक्यमिदमाह सकारणम्॥', 'uktavantaṃ tathā vākyaṃ daśagrīvaṃ niśācaraḥ
prahastaḥ praśritaṃ vākyam idam āha sakāraṇam', null, 7011011),
('ramayana-7-11-12', 12, 'Uttara Kanda, Sarga 11, Verse 12', 'दशग्रीव महाबाहो नार्हस्त्वं वक्तुमीदृशम्।
सौभ्रात्रं नास्ति शूराणां शृणु चेदं वचो मम॥', 'daśagrīva mahābāho nārhas tvaṃ vaktum īdṛśam
saubhrātraṃ nāsti śūrāṇāṃ śṛṇu cedaṃ vaco mama', null, 7011012),
('ramayana-7-11-13', 13, 'Uttara Kanda, Sarga 11, Verse 13', 'अदितिश्च दितिश्चैव भगिन्यौ सहिते किल।
भार्ये परमरूपिण्यौ कश्यपस्य प्रजापतेः॥', 'aditiś ca ditiś caiva bhaginyau sahite kila
bhārye paramarūpiṇyau kaśyapasya prajāpateḥ', null, 7011013),
('ramayana-7-11-14', 14, 'Uttara Kanda, Sarga 11, Verse 14', 'अदितिर्जनयामास देवांस्त्रिभुवणेश्वरान्।
दितिस्त्वजनयद्दैत्यान्कश्यपस्यात्मसंभवान्॥', 'aditir janayām āsa devāṃs tribhuvaṇeśvarān
ditis tv ajanayad daityān kaśyapasyātmasaṃbhavān', null, 7011014),
('ramayana-7-11-15', 15, 'Uttara Kanda, Sarga 11, Verse 15', 'दैत्यानां किल धर्मज्ञ पुरेयं सवनार्णवा।
सपर्वता मही वीर तेऽभवन्प्रभविष्णवः॥', 'daityānāṃ kila dharmajña pureyaṃ savanārṇavā
saparvatā mahī vīra te ''bhavan prabhaviṣṇavaḥ', null, 7011015),
('ramayana-7-11-16', 16, 'Uttara Kanda, Sarga 11, Verse 16', 'निहत्य तांस्तु समरे विष्णुना प्रभविष्णुना।
देवानां वशमानीतं त्रैलोक्यमिदमव्ययम्॥', 'nihatya tāṃs tu samare viṣṇunā prabhaviṣṇunā
devānāṃ vaśam ānītaṃ trailokyam idam avyayam', null, 7011016),
('ramayana-7-11-17', 17, 'Uttara Kanda, Sarga 11, Verse 17', 'नैतदेको भवानेव करिष्यति विपर्ययम्।
सुरैराचरितं पूर्वं कुरुष्वैतद्वचो मम॥', 'naitad eko bhavān eva kariṣyati viparyayam
surair ācaritaṃ pūrvaṃ kuruṣvaitad vaco mama', null, 7011017),
('ramayana-7-11-18', 18, 'Uttara Kanda, Sarga 11, Verse 18', 'एवमुक्तो दशग्रीवः प्रहस्तेन दुरात्मना।
चिन्तयित्वा मुहूर्तं वै बाढमित्येव सोऽब्रवीत्॥', 'evam ukto daśagrīvaḥ prahastena durātmanā
cintayitvā muhūrtaṃ vai bāḍham ity eva so ''bravīt', null, 7011018),
('ramayana-7-11-19', 19, 'Uttara Kanda, Sarga 11, Verse 19', 'स तु तेनैव हर्षेण तस्मिन्नहनि वीर्यवान्।
वनं गतो दशग्रीवः सह तैः क्षणदाचरैः॥', 'sa tu tenaiva harṣeṇa tasminn ahani vīryavān
vanaṃ gato daśagrīvaḥ saha taiḥ kṣaṇadācaraiḥ', null, 7011019),
('ramayana-7-11-20', 20, 'Uttara Kanda, Sarga 11, Verse 20', 'त्रिकूटस्थः स तु तदा दशग्रीवो निशाचरः।
प्रेषयामास दौत्येन प्रहस्तं वाक्यकोविदम्॥', 'trikūṭasthaḥ sa tu tadā daśagrīvo niśācaraḥ
preṣayām āsa dautyena prahastaṃ vākyakovidam', null, 7011020),
('ramayana-7-11-21', 21, 'Uttara Kanda, Sarga 11, Verse 21', 'प्रहस्त शीघ्रं गत्वा त्वं ब्रूहि नैरृतपुंगवम्।
वचनान्मम वित्तेशं सामपूर्वमिदं वचः॥', 'prahasta śīghraṃ gatvā tvaṃ brūhi nairṛtapuṃgavam
vacanān mama vitteśaṃ sāmapūrvam idaṃ vacaḥ', null, 7011021),
('ramayana-7-11-22', 22, 'Uttara Kanda, Sarga 11, Verse 22', 'इयं लङ्का पुरी राजन्राक्षसानां महात्मनाम्।
त्वया निवेशिता सौम्य नैतद्युक्तं तवानघ॥', 'iyaṃ laṅkā purī rājan rākṣasānāṃ mahātmanām
tvayā niveśitā saumya naitad yuktaṃ tavānagha', null, 7011022),
('ramayana-7-11-23', 23, 'Uttara Kanda, Sarga 11, Verse 23', 'तद्भवान्यदि साम्नैतां दद्यादतुलविक्रम।
कृता भवेन्मम प्रीतिर्धर्मश्चैवानुपालितः॥', 'tad bhavān yadi sāmnaitāṃ dadyād atulavikrama
kṛtā bhaven mama prītir dharmaś caivānupālitaḥ', null, 7011023),
('ramayana-7-11-24', 24, 'Uttara Kanda, Sarga 11, Verse 24', 'इत्युक्तः स तदा गत्वा प्रहस्तो वाक्यकोविदः।
दशग्रीववचः सर्वं वित्तेशाय न्यवेदयत्॥', 'ity uktaḥ sa tadā gatvā prahasto vākyakovidaḥ
daśagrīvavacaḥ sarvaṃ vitteśāya nyavedayat', null, 7011024),
('ramayana-7-11-25', 25, 'Uttara Kanda, Sarga 11, Verse 25', 'प्रहस्तादपि संश्रुत्य देवो वैश्रवणो वचः।
प्रत्युवाच प्रहस्तं तं वाक्यं वाक्यविशारदः॥', 'prahastād api saṃśrutya devo vaiśravaṇo vacaḥ
pratyuvāca prahastaṃ taṃ vākyaṃ vākyaviśāradaḥ', null, 7011025),
('ramayana-7-11-26', 26, 'Uttara Kanda, Sarga 11, Verse 26', 'ब्रूहि गच्छ दशग्रीवं पुरी राज्यं च यन्मम।
तवाप्येतन्महाबाहो भुङ्क्ष्वैतद्धतकण्टकम्॥', 'brūhi gaccha daśagrīvaṃ purī rājyaṃ ca yan mama
tavāpy etan mahābāho bhuṅkṣvaitad dhatakaṇṭakam', null, 7011026),
('ramayana-7-11-27', 27, 'Uttara Kanda, Sarga 11, Verse 27', 'सर्वं कर्तास्मि भद्रं ते राक्षसेश वचोऽचिरात्।
किं तु तावत्प्रतीक्षस्व पितुर्यावन्निवेदये॥', 'sarvaṃ kartāsmi bhadraṃ te rākṣaseśa vaco ''cirāt
kiṃ tu tāvat pratīkṣasva pitur yāvan nivedaye', null, 7011027),
('ramayana-7-11-28', 28, 'Uttara Kanda, Sarga 11, Verse 28', 'एवमुक्त्वा धनाध्यक्षो जगाम पितुरन्तिकम्।
अभिवाद्य गुरुं प्राह रावणस्य यदीप्सितम्॥', 'evam uktvā dhanādhyakṣo jagāma pitur antikam
abhivādya guruṃ prāha rāvaṇasya yadīpsitam', null, 7011028),
('ramayana-7-11-29', 29, 'Uttara Kanda, Sarga 11, Verse 29', 'एष तात दशग्रीवो दूतं प्रेषितवान्मम।
दीयतां नगरी लङ्का पूर्वं रक्षोगणोषिता।
मयात्र यदनुष्ठेयं तन्ममाचक्ष्व सुव्रत॥', 'eṣa tāta daśagrīvo dūtaṃ preṣitavān mama
dīyatāṃ nagarī laṅkā pūrvaṃ rakṣogaṇoṣitā
mayātra yad anuṣṭheyaṃ tan mamācakṣva suvrata', null, 7011029),
('ramayana-7-11-30', 30, 'Uttara Kanda, Sarga 11, Verse 30', 'ब्रह्मर्षिस्त्वेवमुक्तोऽसौ विश्रवा मुनिपुंगवः।
उवाच धनदं वाक्यं शृणु पुत्र वचो मम॥', 'brahmarṣis tv evam ukto ''sau viśravā munipuṃgavaḥ
uvāca dhanadaṃ vākyaṃ śṛṇu putra vaco mama', null, 7011030),
('ramayana-7-11-31', 31, 'Uttara Kanda, Sarga 11, Verse 31', 'दशग्रीवो महाबाहुरुक्तवान्मम संनिधौ।
मया निर्भर्त्सितश्चासीद्बहुधोक्तः सुदुर्मतिः॥', 'daśagrīvo mahābāhur uktavān mama saṃnidhau
mayā nirbhartsitaś cāsīd bahudhoktaḥ sudurmatiḥ', null, 7011031),
('ramayana-7-11-32', 32, 'Uttara Kanda, Sarga 11, Verse 32', 'स क्रोधेन मया चोक्तो ध्वंसस्वेति पुनः पुनः।
श्रेयोऽभियुक्तं धर्म्यं च शृणु पुत्र वचो मम॥', 'sa krodhena mayā cokto dhvaṃsasveti punaḥ punaḥ
śreyo''bhiyuktaṃ dharmyaṃ ca śṛṇu putra vaco mama', null, 7011032),
('ramayana-7-11-33', 33, 'Uttara Kanda, Sarga 11, Verse 33', 'वरप्रदानसंमूढो मान्यामान्यं सुदुर्मतिः।
न वेत्ति मम शापाच्च प्रकृतिं दारुणां गतः॥', 'varapradānasaṃmūḍho mānyāmānyaṃ sudurmatiḥ
na vetti mama śāpāc ca prakṛtiṃ dāruṇāṃ gataḥ', null, 7011033),
('ramayana-7-11-34', 34, 'Uttara Kanda, Sarga 11, Verse 34', 'तस्माद्गच्छ महाबाहो कैलासं धरणीधरम्।
निवेशय निवासार्थं त्यज लङ्कां सहानुगः॥', 'tasmād gaccha mahābāho kailāsaṃ dharaṇīdharam
niveśaya nivāsārthaṃ tyaja laṅkāṃ sahānugaḥ', null, 7011034),
('ramayana-7-11-35', 35, 'Uttara Kanda, Sarga 11, Verse 35', 'तत्र मन्दाकिनी रम्या नदीनां प्रवरा नदी।
काञ्चनैः सूर्यसंकाशैः पङ्कजैः संवृतोदका॥', 'tatra mandākinī ramyā nadīnāṃ pravarā nadī
kāñcanaiḥ sūryasaṃkāśaiḥ paṅkajaiḥ saṃvṛtodakā', null, 7011035),
('ramayana-7-11-36', 36, 'Uttara Kanda, Sarga 11, Verse 36', 'न हि क्षमं त्वया तेन वैरं धनदरक्षसा।
जानीषे हि यथानेन लब्धः परमको वरः॥', 'na hi kṣamaṃ tvayā tena vairaṃ dhanadarakṣasā
jānīṣe hi yathānena labdhaḥ paramako varaḥ', null, 7011036),
('ramayana-7-11-37', 37, 'Uttara Kanda, Sarga 11, Verse 37', 'एवमुक्तो गृहीत्वा तु तद्वचः पितृगौरवात्।
सदार पौरः सामात्यः सवाहनधनो गतः॥', 'evam ukto gṛhītvā tu tad vacaḥ pitṛgauravāt
sadāra pauraḥ sāmātyaḥ savāhanadhano gataḥ', null, 7011037),
('ramayana-7-11-38', 38, 'Uttara Kanda, Sarga 11, Verse 38', 'प्रहस्तस्तु दशग्रीवं गत्वा सर्वं न्यवेदयत्।
शून्या सा नगरी लङ्का त्रिंशद्योजनमायता।
प्रविश्य तां सहास्माभिः स्वधर्मं तत्र पालय॥', 'prahastas tu daśagrīvaṃ gatvā sarvaṃ nyavedayat
śūnyā sā nagarī laṅkā triṃśadyojanam āyatā
praviśya tāṃ sahāsmābhiḥ svadharmaṃ tatra pālaya', null, 7011038),
('ramayana-7-11-39', 39, 'Uttara Kanda, Sarga 11, Verse 39', 'एवमुक्तः प्रहस्तेन रावणो राक्षसस्तदा।
विवेश नगरीं लङ्कां सभ्राता सबलानुगः॥', 'evam uktaḥ prahastena rāvaṇo rākṣasas tadā
viveśa nagarīṃ laṅkāṃ sabhrātā sabalānugaḥ', null, 7011039),
('ramayana-7-11-40', 40, 'Uttara Kanda, Sarga 11, Verse 40', 'स चाभिषिक्तः क्षणदाचरैस्तदा निवेशयामास पुरीं दशाननः।
निकामपूर्णा च बभूव सा पुरी निशाचरैर्नीलबलाहकोपमैः॥', 'sa cābhiṣiktaḥ kṣaṇadācarais tadā niveśayām āsa purīṃ daśānanaḥ
nikāmapūrṇā ca babhūva sā purī niśācarair nīlabalāhakopamaiḥ', null, 7011040),
('ramayana-7-11-41', 41, 'Uttara Kanda, Sarga 11, Verse 41', 'धनेश्वरस्त्वथ पितृवाक्यगौरवान्न्यवेशयच्छशिविमले गिरौ पुरीम्।
स्वलंकृतैर्भवनवरैर्विभूषितां पुरंदरस्येव तदामरावतीम्॥', 'dhaneśvaras tv atha pitṛvākyagauravān nyaveśayac chaśivimale girau purīm
svalaṃkṛtair bhavanavarair vibhūṣitāṃ puraṃdarasyeva tadāmarāvatīm', null, 7011041)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 12 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-12-1', 1, 'Uttara Kanda, Sarga 12, Verse 1', 'राक्षसेन्द्रोऽभिषिक्तस्तु भ्रातृभ्यां सहितस्तदा।
ततः प्रदानं राक्षस्या भगिन्याः समचिन्तयत्॥', 'rākṣasendro ''bhiṣiktas tu bhrātṛbhyāṃ sahitas tadā
tataḥ pradānaṃ rākṣasyā bhaginyāḥ samacintayat', null, 7012001),
('ramayana-7-12-2', 2, 'Uttara Kanda, Sarga 12, Verse 2', 'ददौ तां कालकेयाय दानवेन्द्राय राक्षसीम्।
स्वसां शूर्पणखां नाम विद्युज्जिह्वाय नामतः॥', 'dadau tāṃ kālakeyāya dānavendrāya rākṣasīm
svasāṃ śūrpaṇakhāṃ nāma vidyujjihvāya nāmataḥ', null, 7012002),
('ramayana-7-12-3', 3, 'Uttara Kanda, Sarga 12, Verse 3', 'अथ दत्त्वा स्वसारं स मृगयां पर्यटन्नृपः।
तत्रापश्यत्ततो राम मयं नाम दितेः सुतम्॥', 'atha dattvā svasāraṃ sa mṛgayāṃ paryaṭan nṛpaḥ
tatrāpaśyat tato rāma mayaṃ nāma diteḥ sutam', null, 7012003),
('ramayana-7-12-4', 4, 'Uttara Kanda, Sarga 12, Verse 4', 'कन्यासहायं तं दृष्ट्वा दशग्रीवो निशाचरः।
अपृच्छत्को भवनेको निर्मनुष्य मृगे वने॥', 'kanyāsahāyaṃ taṃ dṛṣṭvā daśagrīvo niśācaraḥ
apṛcchat ko bhavan eko nirmanuṣya mṛge vane', null, 7012004),
('ramayana-7-12-5', 5, 'Uttara Kanda, Sarga 12, Verse 5', 'मयस्त्वथाब्रवीद्राम पृच्छन्तं तं निशाचरम्।
श्रूयतां सर्वमाख्यास्ये यथावृत्तमिदं मम॥', 'mayas tv athābravīd rāma pṛcchantaṃ taṃ niśācaram
śrūyatāṃ sarvam ākhyāsye yathāvṛttam idaṃ mama', null, 7012005),
('ramayana-7-12-6', 6, 'Uttara Kanda, Sarga 12, Verse 6', 'हेमा नामाप्सरास्तात श्रुतपूर्वा यदि त्वया।
दैवतैर्मम सा दत्ता पौलोमीव शतक्रतोः॥', 'hemā nāmāpsarās tāta śrutapūrvā yadi tvayā
daivatair mama sā dattā paulomīva śatakratoḥ', null, 7012006),
('ramayana-7-12-7', 7, 'Uttara Kanda, Sarga 12, Verse 7', 'तस्यां सक्तमनास्तात पञ्चवर्षशतान्यहम्।
सा च दैवत कार्येण गता वर्षं चतुर्दशम्॥', 'tasyāṃ saktamanās tāta pañcavarṣaśatāny aham
sā ca daivata kāryeṇa gatā varṣaṃ caturdaśam', null, 7012007),
('ramayana-7-12-8', 8, 'Uttara Kanda, Sarga 12, Verse 8', 'तस्याः कृते च हेमायाः सर्वं हेमपुरं मया।
वज्रवैदूर्यचित्रं च मायया निर्मितं तदा॥', 'tasyāḥ kṛte ca hemāyāḥ sarvaṃ hemapuraṃ mayā
vajravaidūryacitraṃ ca māyayā nirmitaṃ tadā', null, 7012008),
('ramayana-7-12-9', 9, 'Uttara Kanda, Sarga 12, Verse 9', 'तत्राहमरतिं विन्दंस्तया हीनः सुदुःखितः।
तस्मात्पुराद्दुहितरं गृहीत्वा वनमागतः॥', 'tatrāham aratiṃ vindaṃs tayā hīnaḥ suduḥkhitaḥ
tasmāt purād duhitaraṃ gṛhītvā vanam āgataḥ', null, 7012009),
('ramayana-7-12-10', 10, 'Uttara Kanda, Sarga 12, Verse 10', 'इयं ममात्मजा राजंस्तस्याः कुक्षौ विवर्धिता।
भर्तारमनया सार्धमस्याः प्राप्तोऽस्मि मार्गितुम्॥', 'iyaṃ mamātmajā rājaṃs tasyāḥ kukṣau vivardhitā
bhartāram anayā sārdham asyāḥ prāpto ''smi mārgitum', null, 7012010),
('ramayana-7-12-11', 11, 'Uttara Kanda, Sarga 12, Verse 11', 'कन्यापितृत्वं दुःखं हि नराणां मानकाङ्क्षिणाम्।
कन्या हि द्वे कुले नित्यं संशये स्थाप्य तिष्ठति॥', 'kanyāpitṛtvaṃ duḥkhaṃ hi narāṇāṃ mānakāṅkṣiṇām
kanyā hi dve kule nityaṃ saṃśaye sthāpya tiṣṭhati', null, 7012011),
('ramayana-7-12-12', 12, 'Uttara Kanda, Sarga 12, Verse 12', 'द्वौ सुतौ तु मम त्वस्यां भार्यायां संबभूवतुः।
मायावी प्रथमस्तात दुन्दुभिस्तदनन्तरम्॥', 'dvau sutau tu mama tv asyāṃ bhāryāyāṃ saṃbabhūvatuḥ
māyāvī prathamas tāta dundubhis tadanantaram', null, 7012012),
('ramayana-7-12-13', 13, 'Uttara Kanda, Sarga 12, Verse 13', 'एतत्ते सर्वमाख्यातं याथातथ्येन पृच्छतः।
त्वामिदानीं कथं तात जानीयां को भवानिति॥', 'etat te sarvam ākhyātaṃ yāthātathyena pṛcchataḥ
tvām idānīṃ kathaṃ tāta jānīyāṃ ko bhavān iti', null, 7012013),
('ramayana-7-12-14', 14, 'Uttara Kanda, Sarga 12, Verse 14', 'एवमुक्तो राक्षसेन्द्रो विनीतमिदमब्रवीत्।
अहं पौलस्त्य तनयो दशग्रीवश्च नामतः॥', 'evam ukto rākṣasendro vinītam idam abravīt
ahaṃ paulastya tanayo daśagrīvaś ca nāmataḥ', null, 7012014),
('ramayana-7-12-15', 15, 'Uttara Kanda, Sarga 12, Verse 15', 'ब्रह्मर्षेस्तं सुतं ज्ञात्वा मयो हर्षमुपागतः।
दातुं दुहितरं तस्य रोचयामास तत्र वै॥', 'brahmarṣes taṃ sutaṃ jñātvā mayo harṣam upāgataḥ
dātuṃ duhitaraṃ tasya rocayām āsa tatra vai', null, 7012015),
('ramayana-7-12-16', 16, 'Uttara Kanda, Sarga 12, Verse 16', 'प्रहसन्प्राह दैत्येन्द्रो राक्षसेन्द्रमिदं वचः।
इयं ममात्मजा राजन्हेमयाप्सरसा धृता।
कन्या मन्दोदरी नाम पत्न्यर्थं प्रतिगृह्यताम्॥', 'prahasan prāha daityendro rākṣasendram idaṃ vacaḥ
iyaṃ mamātmajā rājan hemayāpsarasā dhṛtā
kanyā mandodarī nāma patnyarthaṃ pratigṛhyatām', null, 7012016),
('ramayana-7-12-17', 17, 'Uttara Kanda, Sarga 12, Verse 17', 'बाढमित्येव तं राम दशग्रीवोऽभ्यभाषत।
प्रज्वाल्य तत्र चैवाग्निमकरोत्पाणिसंग्रहम्॥', 'bāḍham ity eva taṃ rāma daśagrīvo ''bhyabhāṣata
prajvālya tatra caivāgnim akarot pāṇisaṃgraham', null, 7012017),
('ramayana-7-12-18', 18, 'Uttara Kanda, Sarga 12, Verse 18', 'न हि तस्य मयो राम शापाभिज्ञस्तपोधनात्।
विदित्वा तेन सा दत्ता तस्य पैतामहं कुलम्॥', 'na hi tasya mayo rāma śāpābhijñas tapodhanāt
viditvā tena sā dattā tasya paitāmahaṃ kulam', null, 7012018),
('ramayana-7-12-19', 19, 'Uttara Kanda, Sarga 12, Verse 19', 'अमोघां तस्य शक्तिं च प्रददौ परमाद्भुताम्।
परेण तपसा लब्धां जघ्निवांल्लक्ष्मणं यया॥', 'amoghāṃ tasya śaktiṃ ca pradadau paramādbhutām
pareṇa tapasā labdhāṃ jaghnivāṃl lakṣmaṇaṃ yayā', null, 7012019),
('ramayana-7-12-20', 20, 'Uttara Kanda, Sarga 12, Verse 20', 'एवं स कृतदारो वै लङ्कायामीश्वरः प्रभुः।
गत्वा तु नगरं भार्ये भ्रातृभ्यां समुदावहत्॥', 'evaṃ sa kṛtadāro vai laṅkāyām īśvaraḥ prabhuḥ
gatvā tu nagaraṃ bhārye bhrātṛbhyāṃ samudāvahat', null, 7012020),
('ramayana-7-12-21', 21, 'Uttara Kanda, Sarga 12, Verse 21', 'वैरोचनस्य दौहित्रीं वज्रज्वालेति नामतः।
तां भार्यां कुम्भकर्णस्य रावणः समुदावहत्॥', 'vairocanasya dauhitrīṃ vajrajvāleti nāmataḥ
tāṃ bhāryāṃ kumbhakarṇasya rāvaṇaḥ samudāvahat', null, 7012021),
('ramayana-7-12-22', 22, 'Uttara Kanda, Sarga 12, Verse 22', 'गन्धर्वराजस्य सुतां शैलूषस्य महात्मन।
सरमा नाम धर्मज्ञो लेभे भार्यां विभीषणः॥', 'gandharvarājasya sutāṃ śailūṣasya mahātmana
saramā nāma dharmajño lebhe bhāryāṃ vibhīṣaṇaḥ', null, 7012022),
('ramayana-7-12-23', 23, 'Uttara Kanda, Sarga 12, Verse 23', 'तीरे तु सरसः सा वै संजज्ञे मानसस्य च।
मानसं च सरस्तात ववृधे जलदागमे॥', 'tīre tu sarasaḥ sā vai saṃjajñe mānasasya ca
mānasaṃ ca saras tāta vavṛdhe jaladāgame', null, 7012023),
('ramayana-7-12-24', 24, 'Uttara Kanda, Sarga 12, Verse 24', 'मात्रा तु तस्याः कन्यायाः स्नेहनाक्रन्दितं वचः।
सरो मा वर्धतेत्युक्तं ततः सा सरमाभवत्॥', 'mātrā tu tasyāḥ kanyāyāḥ snehanākranditaṃ vacaḥ
saro mā vardhatety uktaṃ tataḥ sā saramābhavat', null, 7012024),
('ramayana-7-12-25', 25, 'Uttara Kanda, Sarga 12, Verse 25', 'एवं ते कृतदारा वै रेमिरे तत्र राक्षसाः।
स्वां स्वां भार्यामुपादाय गन्धर्वा इव नन्दने॥', 'evaṃ te kṛtadārā vai remire tatra rākṣasāḥ
svāṃ svāṃ bhāryām upādāya gandharvā iva nandane', null, 7012025),
('ramayana-7-12-26', 26, 'Uttara Kanda, Sarga 12, Verse 26', 'ततो मन्दोदरी पुत्रं मेघनादमसूयत।
स एष इन्द्रजिन्नाम युष्माभिरभिधीयते॥', 'tato mandodarī putraṃ meghanādam asūyata
sa eṣa indrajin nāma yuṣmābhir abhidhīyate', null, 7012026),
('ramayana-7-12-27', 27, 'Uttara Kanda, Sarga 12, Verse 27', 'जातमात्रेण हि पुरा तेन राक्षससूनुना।
रुदता सुमहान्मुक्तो नादो जलधरोपमः॥', 'jātamātreṇa hi purā tena rākṣasasūnunā
rudatā sumahān mukto nādo jaladharopamaḥ', null, 7012027),
('ramayana-7-12-28', 28, 'Uttara Kanda, Sarga 12, Verse 28', 'जडीकृतायां लङ्कायां तेन नादेन तस्य वै।
पिता तस्याकरोन्नाम मेघनाद इति स्वयम्॥', 'jaḍīkṛtāyāṃ laṅkāyāṃ tena nādena tasya vai
pitā tasyākaron nāma meghanāda iti svayam', null, 7012028),
('ramayana-7-12-29', 29, 'Uttara Kanda, Sarga 12, Verse 29', 'सोऽवर्धत तदा राम रावणान्तःपुरे शुभे।
रक्ष्यमाणो वरस्त्रीभिश्छन्नः काष्ठैरिवानलः॥', 'so ''vardhata tadā rāma rāvaṇāntaḥpure śubhe
rakṣyamāṇo varastrībhiś channaḥ kāṣṭhair ivānalaḥ', null, 7012029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 13 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-13-1', 1, 'Uttara Kanda, Sarga 13, Verse 1', 'अथ लोकेश्वरोत्सृष्टा तत्र कालेन केन चित्।
निद्रा समभवत्तीव्रा कुम्भकर्णस्य रूपिणी॥', 'atha lokeśvarotsṛṣṭā tatra kālena kena cit
nidrā samabhavat tīvrā kumbhakarṇasya rūpiṇī', null, 7013001),
('ramayana-7-13-2', 2, 'Uttara Kanda, Sarga 13, Verse 2', 'ततो भ्रातरमासीनं कुम्भकर्णोऽब्रवीद्वचः।
निद्रा मां बाधते राजन्कारयस्व ममालयम्॥', 'tato bhrātaram āsīnaṃ kumbhakarṇo ''bravīd vacaḥ
nidrā māṃ bādhate rājan kārayasva mamālayam', null, 7013002),
('ramayana-7-13-3', 3, 'Uttara Kanda, Sarga 13, Verse 3', 'विनियुक्तास्ततो राज्ञा शिल्पिनो विश्वकर्मवत्।
अकुर्वन्कुम्भकर्णस्य कैलाससममालयम्॥', 'viniyuktās tato rājñā śilpino viśvakarmavat
akurvan kumbhakarṇasya kailāsasamam ālayam', null, 7013003),
('ramayana-7-13-4', 4, 'Uttara Kanda, Sarga 13, Verse 4', 'विस्तीर्णं योजनं शुभ्रं ततो द्विगुणमायतम्।
दर्शनीयं निराबाधं कुम्भकर्णस्य चक्रिरे॥', 'vistīrṇaṃ yojanaṃ śubhraṃ tato dviguṇam āyatam
darśanīyaṃ nirābādhaṃ kumbhakarṇasya cakrire', null, 7013004),
('ramayana-7-13-5', 5, 'Uttara Kanda, Sarga 13, Verse 5', 'स्फाटिकैः काञ्चनैश्चित्रैः स्तम्भैः सर्वत्र शोभितम्।
वैदूर्यकृतशोभं च किङ्किणीजालकं तथा॥', 'sphāṭikaiḥ kāñcanaiś citraiḥ stambhaiḥ sarvatra śobhitam
vaidūryakṛtaśobhaṃ ca kiṅkiṇījālakaṃ tathā', null, 7013005),
('ramayana-7-13-6', 6, 'Uttara Kanda, Sarga 13, Verse 6', 'दन्ततोरणविन्यस्तं वज्रस्फटिकवेदिकम्।
सर्वर्तुसुखदं नित्यं मेरोः पुण्यां गुहामिव॥', 'dantatoraṇavinyastaṃ vajrasphaṭikavedikam
sarvartusukhadaṃ nityaṃ meroḥ puṇyāṃ guhām iva', null, 7013006),
('ramayana-7-13-7', 7, 'Uttara Kanda, Sarga 13, Verse 7', 'तत्र निद्रां समाविष्टः कुम्भकर्णो निशाचरः।
बहून्यब्दसहस्राणि शयानो नावबुध्यते॥', 'tatra nidrāṃ samāviṣṭaḥ kumbhakarṇo niśācaraḥ
bahūny abdasahasrāṇi śayāno nāvabudhyate', null, 7013007),
('ramayana-7-13-8', 8, 'Uttara Kanda, Sarga 13, Verse 8', 'निद्राभिभूते तु तदा कुम्भकर्णे दशाननः।
देवर्षियक्षगन्धर्वान्बाधते स्म स नित्यशः॥', 'nidrābhibhūte tu tadā kumbhakarṇe daśānanaḥ
devarṣiyakṣagandharvān bādhate sma sa nityaśaḥ', null, 7013008),
('ramayana-7-13-9', 9, 'Uttara Kanda, Sarga 13, Verse 9', 'उद्यानानि विचित्राणि नन्दनादीनि यानि च।
तानि गत्वा सुसंक्रुद्धो भिनत्ति स्म दशाननः॥', 'udyānāni vicitrāṇi nandanādīni yāni ca
tāni gatvā susaṃkruddho bhinatti sma daśānanaḥ', null, 7013009),
('ramayana-7-13-10', 10, 'Uttara Kanda, Sarga 13, Verse 10', 'नदीं गज इव क्रीडन्वृक्षान्वायुरिव क्षिपन्।
नगान्वज्र इव सृष्टो विध्वंसयति नित्यशः॥', 'nadīṃ gaja iva krīḍan vṛkṣān vāyur iva kṣipan
nagān vajra iva sṛṣṭo vidhvaṃsayati nityaśaḥ', null, 7013010),
('ramayana-7-13-11', 11, 'Uttara Kanda, Sarga 13, Verse 11', 'तथा वृत्तं तु विज्ञाय दशग्रीवं धनेश्वरः।
कुलानुरूपं धर्मज्ञ वृत्तं संस्मृत्य चात्मनः॥', 'tathā vṛttaṃ tu vijñāya daśagrīvaṃ dhaneśvaraḥ
kulānurūpaṃ dharmajña vṛttaṃ saṃsmṛtya cātmanaḥ', null, 7013011),
('ramayana-7-13-12', 12, 'Uttara Kanda, Sarga 13, Verse 12', 'सौभ्रात्रदर्शनार्थं तु दूतं वैश्वरणस्तदा।
लङ्कां संप्रेषयामास दशग्रीवस्य वै हितम्॥', 'saubhrātradarśanārthaṃ tu dūtaṃ vaiśvaraṇas tadā
laṅkāṃ saṃpreṣayām āsa daśagrīvasya vai hitam', null, 7013012),
('ramayana-7-13-13', 13, 'Uttara Kanda, Sarga 13, Verse 13', 'स गत्वा नगरीं लङ्कामाससाद विभीषणम्।
मानितस्तेन धर्मेण पृष्ठश्चागमनं प्रति॥', 'sa gatvā nagarīṃ laṅkām āsasāda vibhīṣaṇam
mānitas tena dharmeṇa pṛṣṭhaś cāgamanaṃ prati', null, 7013013),
('ramayana-7-13-14', 14, 'Uttara Kanda, Sarga 13, Verse 14', 'पृष्ट्वा च कुशलं राज्ञो ज्ञातीनपि च बान्धवान्।
सभायां दर्शयामास तमासीनं दशाननम्॥', 'pṛṣṭvā ca kuśalaṃ rājño jñātīn api ca bāndhavān
sabhāyāṃ darśayām āsa tam āsīnaṃ daśānanam', null, 7013014),
('ramayana-7-13-15', 15, 'Uttara Kanda, Sarga 13, Verse 15', 'स दृष्ट्वा तत्र राजानं दीप्यमानं स्वतेजसा।
जयेन चाभिसंपूज्य तूष्णीमासीन्मुहूर्तकम्॥', 'sa dṛṣṭvā tatra rājānaṃ dīpyamānaṃ svatejasā
jayena cābhisaṃpūjya tūṣṇīm āsīn muhūrtakam', null, 7013015),
('ramayana-7-13-16', 16, 'Uttara Kanda, Sarga 13, Verse 16', 'तस्योपनीते पर्यङ्के वरास्तरणसंवृते।
उपविश्य दशग्रीवं दूतो वाक्यमथाब्रवीत्॥', 'tasyopanīte paryaṅke varāstaraṇasaṃvṛte
upaviśya daśagrīvaṃ dūto vākyam athābravīt', null, 7013016),
('ramayana-7-13-17', 17, 'Uttara Kanda, Sarga 13, Verse 17', 'राजन्वदामि ते सर्वं भ्राता तव यदब्रवीत्।
उभयोः सदृशं सौम्य वृत्तस्य च कुलस्य च॥', 'rājan vadāmi te sarvaṃ bhrātā tava yad abravīt
ubhayoḥ sadṛśaṃ saumya vṛttasya ca kulasya ca', null, 7013017),
('ramayana-7-13-18', 18, 'Uttara Kanda, Sarga 13, Verse 18', 'साधु पर्याप्तमेतावत्कृतश्चारित्रसंग्रहः।
साधु धर्मे व्यवस्थानं क्रियतां यदि शक्यते॥', 'sādhu paryāptam etāvat kṛtaś cāritrasaṃgrahaḥ
sādhu dharme vyavasthānaṃ kriyatāṃ yadi śakyate', null, 7013018),
('ramayana-7-13-19', 19, 'Uttara Kanda, Sarga 13, Verse 19', 'दृष्टं मे नन्दनं भग्नमृषयो निहताः श्रुताः।
देवानां तु समुद्योगस्त्वत्तो राजञ्श्रुतश्च मे॥', 'dṛṣṭaṃ me nandanaṃ bhagnam ṛṣayo nihatāḥ śrutāḥ
devānāṃ tu samudyogas tvatto rājañ śrutaś ca me', null, 7013019),
('ramayana-7-13-20', 20, 'Uttara Kanda, Sarga 13, Verse 20', 'निराकृतश्च बहुशस्त्वयाहं राक्षसाधिप।
अपराद्धा हि बाल्याच्च रक्षणीयाः स्वबान्धवाः॥', 'nirākṛtaś ca bahuśas tvayāhaṃ rākṣasādhipa
aparāddhā hi bālyāc ca rakṣaṇīyāḥ svabāndhavāḥ', null, 7013020),
('ramayana-7-13-21', 21, 'Uttara Kanda, Sarga 13, Verse 21', 'अहं तु हिमवत्पृष्ठं गतो धर्ममुपासितुम्।
रौद्रं व्रतं समास्थाय नियतो नियतेन्द्रियः॥', 'ahaṃ tu himavatpṛṣṭhaṃ gato dharmam upāsitum
raudraṃ vrataṃ samāsthāya niyato niyatendriyaḥ', null, 7013021),
('ramayana-7-13-22', 22, 'Uttara Kanda, Sarga 13, Verse 22', 'तत्र देवो मया दृष्टः सह देव्योमया प्रभुः।
सव्यं चक्षुर्मया चैव तत्र देव्यां निपातितम्॥', 'tatra devo mayā dṛṣṭaḥ saha devyomayā prabhuḥ
savyaṃ cakṣur mayā caiva tatra devyāṃ nipātitam', null, 7013022),
('ramayana-7-13-23', 23, 'Uttara Kanda, Sarga 13, Verse 23', 'का न्वियं स्यादिति शुभा न खल्वन्येन हेतुना।
रूपं ह्यनुपमं कृत्वा तत्र क्रीडति पार्वती॥', 'kā nv iyaṃ syād iti śubhā na khalv anyena hetunā
rūpaṃ hy anupamaṃ kṛtvā tatra krīḍati pārvatī', null, 7013023),
('ramayana-7-13-24', 24, 'Uttara Kanda, Sarga 13, Verse 24', 'ततो देव्याः प्रभावेन दग्धं सव्यं ममेक्षणम्।
रेणुध्वस्तमिव ज्योतिः पिङ्गलत्वमुपागतम्॥', 'tato devyāḥ prabhāvena dagdhaṃ savyaṃ mamekṣaṇam
reṇudhvastam iva jyotiḥ piṅgalatvam upāgatam', null, 7013024),
('ramayana-7-13-25', 25, 'Uttara Kanda, Sarga 13, Verse 25', 'ततोऽहमन्यद्विस्तीर्णं गत्वा तस्य गिरेस्तटम्।
पूर्णं वर्षशतान्यष्टौ समवाप महाव्रतम्॥', 'tato ''ham anyad vistīrṇaṃ gatvā tasya gires taṭam
pūrṇaṃ varṣaśatāny aṣṭau samavāpa mahāvratam', null, 7013025),
('ramayana-7-13-26', 26, 'Uttara Kanda, Sarga 13, Verse 26', 'समाप्ते नियमे तस्मिंस्तत्र देवो महेश्वरः।
प्रीतः प्रीतेन मनसा प्राह वाक्यमिदं प्रभुः॥', 'samāpte niyame tasmiṃs tatra devo maheśvaraḥ
prītaḥ prītena manasā prāha vākyam idaṃ prabhuḥ', null, 7013026),
('ramayana-7-13-27', 27, 'Uttara Kanda, Sarga 13, Verse 27', 'प्रीतोऽस्मि तव धर्मज्ञ तपसानेन सुव्रत।
मया चैतद्व्रतं चीर्णं त्वया चैव धनाधिप॥', 'prīto ''smi tava dharmajña tapasānena suvrata
mayā caitad vrataṃ cīrṇaṃ tvayā caiva dhanādhipa', null, 7013027),
('ramayana-7-13-28', 28, 'Uttara Kanda, Sarga 13, Verse 28', 'तृतीयः पुरुषो नास्ति यश्चरेद्व्रतमीदृशम्।
व्रतं सुदुश्चरं ह्येतन्मयैवोत्पादितं पुरा॥', 'tṛtīyaḥ puruṣo nāsti yaś cared vratam īdṛśam
vrataṃ suduścaraṃ hy etan mayaivotpāditaṃ purā', null, 7013028),
('ramayana-7-13-29', 29, 'Uttara Kanda, Sarga 13, Verse 29', 'तत्सखित्वं मया सार्धं रोचयस्व धनेश्वर।
तपसा निर्जितत्वाद्धि सखा भव ममानघ॥', 'tat sakhitvaṃ mayā sārdhaṃ rocayasva dhaneśvara
tapasā nirjitatvād dhi sakhā bhava mamānagha', null, 7013029),
('ramayana-7-13-30', 30, 'Uttara Kanda, Sarga 13, Verse 30', 'देव्या दग्धं प्रभावेन यच्च साव्यं तवेक्षणम्।
एकाक्षि पिङ्गलेत्येव नाम स्थास्यति शाश्वतम्॥', 'devyā dagdhaṃ prabhāvena yac ca sāvyaṃ tavekṣaṇam
ekākṣi piṅgalety eva nāma sthāsyati śāśvatam', null, 7013030),
('ramayana-7-13-31', 31, 'Uttara Kanda, Sarga 13, Verse 31', 'एवं तेन सखित्वं च प्राप्यानुज्ञां च शंकरात्।
आगम्य च श्रुतोऽयं मे तव पापविनिश्चयः॥', 'evaṃ tena sakhitvaṃ ca prāpyānujñāṃ ca śaṃkarāt
āgamya ca śruto ''yaṃ me tava pāpaviniścayaḥ', null, 7013031),
('ramayana-7-13-32', 32, 'Uttara Kanda, Sarga 13, Verse 32', 'तदधर्मिष्ठसंयोगान्निवर्त कुलदूषण।
चिन्त्यते हि वधोपायः सर्षिसंघैः सुरैस्तव॥', 'tadadharmiṣṭhasaṃyogān nivarta kuladūṣaṇa
cintyate hi vadhopāyaḥ sarṣisaṃghaiḥ surais tava', null, 7013032),
('ramayana-7-13-33', 33, 'Uttara Kanda, Sarga 13, Verse 33', 'एवमुक्तो दशग्रीवः क्रुद्धः संरक्तलोचनः।
हस्तान्दन्तांश संपीड्य वाक्यमेतदुवाच ह॥', 'evam ukto daśagrīvaḥ kruddhaḥ saṃraktalocanaḥ
hastān dantāṃś a saṃpīḍya vākyam etad uvāca ha', null, 7013033),
('ramayana-7-13-34', 34, 'Uttara Kanda, Sarga 13, Verse 34', 'विज्ञातं ते मया दूत वाक्यं यत्त्वं प्रभाषसे।
नैव त्वमसि नैवासौ भ्रात्रा येनासि प्रेषितः॥', 'vijñātaṃ te mayā dūta vākyaṃ yat tvaṃ prabhāṣase
naiva tvam asi naivāsau bhrātrā yenāsi preṣitaḥ', null, 7013034),
('ramayana-7-13-35', 35, 'Uttara Kanda, Sarga 13, Verse 35', 'हितं न स ममैतद्धि ब्रवीति धनरक्षकः।
महेश्वरसखित्वं तु मूढ श्रावयसे किल॥', 'hitaṃ na sa mamaitad dhi bravīti dhanarakṣakaḥ
maheśvarasakhitvaṃ tu mūḍha śrāvayase kila', null, 7013035),
('ramayana-7-13-36', 36, 'Uttara Kanda, Sarga 13, Verse 36', 'न हन्तव्यो गुरुर्ज्येष्ठो ममायमिति मन्यते।
तस्य त्विदानीं श्रुत्वा मे वाक्यमेषा कृता मतिः॥', 'na hantavyo gurur jyeṣṭho mamāyam iti manyate
tasya tv idānīṃ śrutvā me vākyam eṣā kṛtā matiḥ', null, 7013036),
('ramayana-7-13-37', 37, 'Uttara Kanda, Sarga 13, Verse 37', 'त्रींल्लोकानपि जेष्यामि बाहुवीर्यमुपाश्रितः।
एतन्मुहूर्तमेषोऽहं तस्यैकस्य कृते च वै।
चतुरो लोकपालांस्तान्नयिष्यामि यमक्षयम्॥', 'trīṃl lokān api jeṣyāmi bāhuvīryam upāśritaḥ
etan muhūrtam eṣo ''haṃ tasyaikasya kṛte ca vai
caturo lokapālāṃs tān nayiṣyāmi yamakṣayam', null, 7013037),
('ramayana-7-13-38', 38, 'Uttara Kanda, Sarga 13, Verse 38', 'एवमुक्त्वा तु लङ्केशो दूतं खड्गेन जघ्निवान्।
ददौ भक्षयितुं ह्येनं राक्षसानां दुरात्मनाम्॥', 'evam uktvā tu laṅkeśo dūtaṃ khaḍgena jaghnivān
dadau bhakṣayituṃ hy enaṃ rākṣasānāṃ durātmanām', null, 7013038),
('ramayana-7-13-39', 39, 'Uttara Kanda, Sarga 13, Verse 39', 'ततः कृतस्वस्त्ययनो रथमारुह्य रावणः।
त्रैलोक्यविजयाकाङ्क्षी ययौ तत्र धनेश्वरः॥', 'tataḥ kṛtasvastyayano ratham āruhya rāvaṇaḥ
trailokyavijayākāṅkṣī yayau tatra dhaneśvaraḥ', null, 7013039)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 14 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-14-1', 1, 'Uttara Kanda, Sarga 14, Verse 1', 'ततः स सचिवैः सार्धं षड्भिर्नित्यं बलोत्कटैः।
महोदरप्रहस्ताभ्यां मारीचशुकसारणैः॥', 'tataḥ sa sacivaiḥ sārdhaṃ ṣaḍbhir nityaṃ balotkaṭaiḥ
mahodaraprahastābhyāṃ mārīcaśukasāraṇaiḥ', null, 7014001),
('ramayana-7-14-2', 2, 'Uttara Kanda, Sarga 14, Verse 2', 'धूम्राक्षेण च वीरेण नित्यं समरगृध्नुना।
वृतः संप्रययौ श्रीमान्क्रोधाल्लोकान्दहन्निव॥', 'dhūmrākṣeṇa ca vīreṇa nityaṃ samaragṛdhnunā
vṛtaḥ saṃprayayau śrīmān krodhāl lokān dahann iva', null, 7014002),
('ramayana-7-14-3', 3, 'Uttara Kanda, Sarga 14, Verse 3', 'पुराणि स नदीः शैलान्वनान्युपवनानि च।
अतिक्रम्य मुहूर्तेन कैलासं गिरिमाविशत्॥', 'purāṇi sa nadīḥ śailān vanāny upavanāni ca
atikramya muhūrtena kailāsaṃ girim āviśat', null, 7014003),
('ramayana-7-14-4', 4, 'Uttara Kanda, Sarga 14, Verse 4', 'तं निविष्टं गिरौ तस्मिन्राक्षसेन्द्रं निशम्य तु।
राज्ञो भ्रातायमित्युक्त्वा गता यत्र धनेश्वरः॥', 'taṃ niviṣṭaṃ girau tasmin rākṣasendraṃ niśamya tu
rājño bhrātāyam ity uktvā gatā yatra dhaneśvaraḥ', null, 7014004),
('ramayana-7-14-5', 5, 'Uttara Kanda, Sarga 14, Verse 5', 'गत्वा तु सर्वमाचख्युर्भ्रातुस्तस्य विनिश्चयम्।
अनुज्ञाता ययुश्चैव युद्धाय धनदेन ते॥', 'gatvā tu sarvam ācakhyur bhrātus tasya viniścayam
anujñātā yayuś caiva yuddhāya dhanadena te', null, 7014005),
('ramayana-7-14-6', 6, 'Uttara Kanda, Sarga 14, Verse 6', 'ततो बलस्य संक्षोभः सागरस्येव वर्धतः।
अभून्नैरृतराजस्य गिरिं संचालयन्निव॥', 'tato balasya saṃkṣobhaḥ sāgarasyeva vardhataḥ
abhūn nairṛtarājasya giriṃ saṃcālayann iva', null, 7014006),
('ramayana-7-14-7', 7, 'Uttara Kanda, Sarga 14, Verse 7', 'ततो युद्धं समभवद्यक्षराक्षससंकुलम्।
व्यथिताश्चाभवंस्तत्र सचिवास्तस्य रक्षसः॥', 'tato yuddhaṃ samabhavad yakṣarākṣasasaṃkulam
vyathitāś cābhavaṃs tatra sacivās tasya rakṣasaḥ', null, 7014007),
('ramayana-7-14-8', 8, 'Uttara Kanda, Sarga 14, Verse 8', 'तं दृष्ट्वा तादृशं सैन्यं दशग्रीवो निशाचरः।
हर्षान्नादं ततः कृत्वा रोषात्समभिवर्तत॥', 'taṃ dṛṣṭvā tādṛśaṃ sainyaṃ daśagrīvo niśācaraḥ
harṣān nādaṃ tataḥ kṛtvā roṣāt samabhivartata', null, 7014008),
('ramayana-7-14-9', 9, 'Uttara Kanda, Sarga 14, Verse 9', 'ये तु ते राक्षसेन्द्रस्य सचिवा घोरविक्रमः।
ते सहस्रं सहस्राणामेकैकं समयोधयन्॥', 'ye tu te rākṣasendrasya sacivā ghoravikramaḥ
te sahasraṃ sahasrāṇām ekaikaṃ samayodhayan', null, 7014009),
('ramayana-7-14-10', 10, 'Uttara Kanda, Sarga 14, Verse 10', 'ततो गदाभिः परिघैरसिभिः शक्तितोमरैः।
वध्यमानो दशग्रीवस्तत्सैन्यं समगाहत॥', 'tato gadābhiḥ parighair asibhiḥ śaktitomaraiḥ
vadhyamāno daśagrīvas tat sainyaṃ samagāhata', null, 7014010),
('ramayana-7-14-11', 11, 'Uttara Kanda, Sarga 14, Verse 11', 'तैर्निरुच्छ्वासवत्तत्र वध्यमानो दशाननः।
वर्षमाणैरिव घनैर्यक्षेन्द्रैः संनिरुध्यत॥', 'tair nirucchvāsavat tatra vadhyamāno daśānanaḥ
varṣamāṇair iva ghanair yakṣendraiḥ saṃnirudhyata', null, 7014011),
('ramayana-7-14-12', 12, 'Uttara Kanda, Sarga 14, Verse 12', 'स दुरात्मा समुद्यम्य कालदण्डोपमां गदाम्।
प्रविवेश ततः सैन्यं नयन्यक्षान्यमक्षयम्॥', 'sa durātmā samudyamya kāladaṇḍopamāṃ gadām
praviveśa tataḥ sainyaṃ nayan yakṣān yamakṣayam', null, 7014012),
('ramayana-7-14-13', 13, 'Uttara Kanda, Sarga 14, Verse 13', 'स कक्षमिव विस्तीर्णं शुष्केन्धनसमाकुलम्।
वातेनाग्निरिवायत्तोऽदहत्सैन्यं सुदारुणम्॥', 'sa kakṣam iva vistīrṇaṃ śuṣkendhanasamākulam
vātenāgnir ivāyatto ''dahat sainyaṃ sudāruṇam', null, 7014013),
('ramayana-7-14-14', 14, 'Uttara Kanda, Sarga 14, Verse 14', 'तैस्तु तस्य मृधेऽमात्यैर्महोदरशुकादिभिः।
अल्पावशिष्टास्ते यक्षाः कृता वातैरिवाम्बुदाः॥', 'tais tu tasya mṛdhe ''mātyair mahodaraśukādibhiḥ
alpāvaśiṣṭās te yakṣāḥ kṛtā vātair ivāmbudāḥ', null, 7014014),
('ramayana-7-14-15', 15, 'Uttara Kanda, Sarga 14, Verse 15', 'के चित्त्वायुधभग्नाङ्गाः पतिताः समरक्षितौ।
ओष्ठान्स्वदशनैस्तीक्ष्णैर्दंशन्तो भुवि पातिताः॥', 'ke cit tv āyudhabhagnāṅgāḥ patitāḥ samarakṣitau
oṣṭhān svadaśanais tīkṣṇair daṃśanto bhuvi pātitāḥ', null, 7014015),
('ramayana-7-14-16', 16, 'Uttara Kanda, Sarga 14, Verse 16', 'भयादन्योन्यमालिङ्ग्य भ्रष्टशस्त्रा रणाजिरे।
निषेदुस्ते तदा यक्षाः कूला जलहता इव॥', 'bhayād anyonyam āliṅgya bhraṣṭaśastrā raṇājire
niṣedus te tadā yakṣāḥ kūlā jalahatā iva', null, 7014016),
('ramayana-7-14-17', 17, 'Uttara Kanda, Sarga 14, Verse 17', 'हतानां स्वर्गसंस्थानां युध्यतां पृथिवीतले।
प्रेक्षतामृषिसंघानां न बभूवान्तरं दिवि॥', 'hatānāṃ svargasaṃsthānāṃ yudhyatāṃ pṛthivītale
prekṣatām ṛṣisaṃghānāṃ na babhūvāntaraṃ divi', null, 7014017),
('ramayana-7-14-18', 18, 'Uttara Kanda, Sarga 14, Verse 18', 'एतस्मिन्नन्तरे राम विस्तीर्णबलवाहनः।
अगमत्सुमहान्यक्षो नाम्ना संयोधकण्टकः॥', 'etasminn antare rāma vistīrṇabalavāhanaḥ
agamat sumahān yakṣo nāmnā saṃyodhakaṇṭakaḥ', null, 7014018),
('ramayana-7-14-19', 19, 'Uttara Kanda, Sarga 14, Verse 19', 'तेन यक्षेण मारीचो विष्णुनेव समाहतः।
पतितः पृथिवीं भेजे क्षीणपुण्य इवाम्बरात्॥', 'tena yakṣeṇa mārīco viṣṇuneva samāhataḥ
patitaḥ pṛthivīṃ bheje kṣīṇapuṇya ivāmbarāt', null, 7014019),
('ramayana-7-14-20', 20, 'Uttara Kanda, Sarga 14, Verse 20', 'प्राप्तसंज्ञो मुहूर्तेन विश्रम्य च निशाचरः।
तं यक्षं योधयामास स च भग्नः प्रदुद्रुवे॥', 'prāptasaṃjño muhūrtena viśramya ca niśācaraḥ
taṃ yakṣaṃ yodhayām āsa sa ca bhagnaḥ pradudruve', null, 7014020),
('ramayana-7-14-21', 21, 'Uttara Kanda, Sarga 14, Verse 21', 'ततः काञ्चनचित्राङ्गं वैदूर्यरजतोक्षितम्।
मर्यादां द्वारपालानां तोरणं तत्समाविशत्॥', 'tataḥ kāñcanacitrāṅgaṃ vaidūryarajatokṣitam
maryādāṃ dvārapālānāṃ toraṇaṃ tat samāviśat', null, 7014021),
('ramayana-7-14-22', 22, 'Uttara Kanda, Sarga 14, Verse 22', 'ततो राम दशग्रीवं प्रविशन्तं निशाचरम्।
सूर्यभानुरिति ख्यातो द्वारपालो न्यवारयत्॥', 'tato rāma daśagrīvaṃ praviśantaṃ niśācaram
sūryabhānur iti khyāto dvārapālo nyavārayat', null, 7014022),
('ramayana-7-14-23', 23, 'Uttara Kanda, Sarga 14, Verse 23', 'ततस्तोरणमुत्पाट्य तेन यक्षेण ताडितः।
राक्षसो यक्षसृष्टेन तोरणेन समाहतः।
न क्षितिं प्रययौ राम वरात्सलिलयोनिनः॥', 'tatas toraṇam utpāṭya tena yakṣeṇa tāḍitaḥ
rākṣaso yakṣasṛṣṭena toraṇena samāhataḥ
na kṣitiṃ prayayau rāma varāt salilayoninaḥ', null, 7014023),
('ramayana-7-14-24', 24, 'Uttara Kanda, Sarga 14, Verse 24', 'स तु तेनैव तं यक्षं तोरणेन समाहनत्।
नादृश्यत तदा यक्षो भस्म तेन कृतस्तु सः॥', 'sa tu tenaiva taṃ yakṣaṃ toraṇena samāhanat
nādṛśyata tadā yakṣo bhasma tena kṛtas tu saḥ', null, 7014024),
('ramayana-7-14-25', 25, 'Uttara Kanda, Sarga 14, Verse 25', 'ततः प्रदुद्रुवुः सर्वे यक्षा दृष्ट्वा पराक्रमम्।
ततो नदीर्गुहाश्चैव विविशुर्भयपीडिताः॥', 'tataḥ pradudruvuḥ sarve yakṣā dṛṣṭvā parākramam
tato nadīr guhāś caiva viviśur bhayapīḍitāḥ', null, 7014025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 15 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-15-1', 1, 'Uttara Kanda, Sarga 15, Verse 1', 'ततस्तान्विद्रुतान्दृष्ट्वा यक्षाञ्शतसहस्रशः।
स्वयमेव धनाध्यक्षो निर्जगाम रणं प्रति॥', 'tatas tān vidrutān dṛṣṭvā yakṣāñ śatasahasraśaḥ
svayam eva dhanādhyakṣo nirjagāma raṇaṃ prati', null, 7015001),
('ramayana-7-15-2', 2, 'Uttara Kanda, Sarga 15, Verse 2', 'तत्र माणिचारो नाम यक्षः परमदुर्जयः।
वृतो यक्षसहस्रैः स चतुर्भिः समयोधयत्॥', 'tatra māṇicāro nāma yakṣaḥ paramadurjayaḥ
vṛto yakṣasahasraiḥ sa caturbhiḥ samayodhayat', null, 7015002),
('ramayana-7-15-3', 3, 'Uttara Kanda, Sarga 15, Verse 3', 'ते गदामुसलप्रासशक्तितोमरमुद्गरैः।
अभिघ्नन्तो रणे यक्षा राक्षसानभिदुद्रुवुः॥', 'te gadāmusalaprāsaśaktitomaramudgaraiḥ
abhighnanto raṇe yakṣā rākṣasān abhidudruvuḥ', null, 7015003),
('ramayana-7-15-4', 4, 'Uttara Kanda, Sarga 15, Verse 4', 'ततः प्रहस्तेन तदा सहस्रं निहतं रणे।
महोदरेण गदया सहस्रमपरं हतम्॥', 'tataḥ prahastena tadā sahasraṃ nihataṃ raṇe
mahodareṇa gadayā sahasram aparaṃ hatam', null, 7015004),
('ramayana-7-15-5', 5, 'Uttara Kanda, Sarga 15, Verse 5', 'क्रुद्धेन च तदा राम मारीचेन दुरात्मना।
निमेषान्तरमात्रेण द्वे सहस्रे निपातिते॥', 'kruddhena ca tadā rāma mārīcena durātmanā
nimeṣāntaramātreṇa dve sahasre nipātite', null, 7015005),
('ramayana-7-15-6', 6, 'Uttara Kanda, Sarga 15, Verse 6', 'धूम्राक्षेण समागम्य माणिभद्रो महारणे।
मुसलेनोरसि क्रोधात्ताडितो न च कम्पितः॥', 'dhūmrākṣeṇa samāgamya māṇibhadro mahāraṇe
musalenorasi krodhāt tāḍito na ca kampitaḥ', null, 7015006),
('ramayana-7-15-7', 7, 'Uttara Kanda, Sarga 15, Verse 7', 'ततो गदां समाविध्य माणिभद्रेण राक्षसः।
धूम्राक्षस्ताडितो मूर्ध्नि विह्वलो निपपात ह॥', 'tato gadāṃ samāvidhya māṇibhadreṇa rākṣasaḥ
dhūmrākṣas tāḍito mūrdhni vihvalo nipapāta ha', null, 7015007),
('ramayana-7-15-8', 8, 'Uttara Kanda, Sarga 15, Verse 8', 'धूम्राक्षं ताडितं दृष्ट्वा पतितं शोणितोक्षितम्।
अभ्यधावत्सुसंक्रुद्धो माणिभद्रं दशाननः॥', 'dhūmrākṣaṃ tāḍitaṃ dṛṣṭvā patitaṃ śoṇitokṣitam
abhyadhāvat susaṃkruddho māṇibhadraṃ daśānanaḥ', null, 7015008),
('ramayana-7-15-9', 9, 'Uttara Kanda, Sarga 15, Verse 9', 'तं क्रुद्धमभिधावन्तं युगान्ताग्निमिवोत्थितम्।
शक्तिभिस्ताडयामास तिसृभिर्यक्षपुंगवः॥', 'taṃ kruddham abhidhāvantaṃ yugāntāgnim ivotthitam
śaktibhis tāḍayām āsa tisṛbhir yakṣapuṃgavaḥ', null, 7015009),
('ramayana-7-15-10', 10, 'Uttara Kanda, Sarga 15, Verse 10', 'ततो राक्षसराजेन ताडितो गदया रणे।
तस्य तेन प्रहारेण मुकुटः पार्श्वमागतः।
तदा प्रभृति यक्षोऽसौ पार्श्वमौलिरिति स्मृतः॥', 'tato rākṣasarājena tāḍito gadayā raṇe
tasya tena prahāreṇa mukuṭaḥ pārśvam āgataḥ
tadā prabhṛti yakṣo ''sau pārśvamaulir iti smṛtaḥ', null, 7015010),
('ramayana-7-15-11', 11, 'Uttara Kanda, Sarga 15, Verse 11', 'तस्मिंस्तु विमुखे यक्षे माणिभद्रे महात्मनि।
संनादः सुमहान्राम तस्मिञ्शैले व्यवर्धत॥', 'tasmiṃs tu vimukhe yakṣe māṇibhadre mahātmani
saṃnādaḥ sumahān rāma tasmiñ śaile vyavardhata', null, 7015011),
('ramayana-7-15-12', 12, 'Uttara Kanda, Sarga 15, Verse 12', 'ततो दूरात्प्रददृशे धनाध्यक्षो गदाधरः।
शुक्रप्रोष्टःपदाभ्यां च शङ्खपद्मसमावृतः॥', 'tato dūrāt pradadṛśe dhanādhyakṣo gadādharaḥ
śukraproṣṭaḥpadābhyāṃ ca śaṅkhapadmasamāvṛtaḥ', null, 7015012),
('ramayana-7-15-13', 13, 'Uttara Kanda, Sarga 15, Verse 13', 'स दृष्ट्वा भ्रातरं संख्ये शापाद्विभ्रष्टगौरवम्।
उवाच वचनं धीमान्युक्तं पैतामहे कुले॥', 'sa dṛṣṭvā bhrātaraṃ saṃkhye śāpād vibhraṣṭagauravam
uvāca vacanaṃ dhīmān yuktaṃ paitāmahe kule', null, 7015013),
('ramayana-7-15-14', 14, 'Uttara Kanda, Sarga 15, Verse 14', 'मया त्वं वार्यमाणोऽपि नावगच्छसि दुर्मते।
पश्चादस्य फलं प्राप्य ज्ञास्यसे निरयं गतः॥', 'mayā tvaṃ vāryamāṇo ''pi nāvagacchasi durmate
paścād asya phalaṃ prāpya jñāsyase nirayaṃ gataḥ', null, 7015014),
('ramayana-7-15-15', 15, 'Uttara Kanda, Sarga 15, Verse 15', 'यो हि मोहाद्विषं पीत्वा नावगच्छति मानवः।
परिणामे स वि मूढो जानीते कर्मणः फलम्॥', 'yo hi mohād viṣaṃ pītvā nāvagacchati mānavaḥ
pariṇāme sa vi mūḍho jānīte karmaṇaḥ phalam', null, 7015015),
('ramayana-7-15-16', 16, 'Uttara Kanda, Sarga 15, Verse 16', 'दैवतानि हि नन्दन्ति धर्मयुक्तेन केन चित्।
येन त्वमीदृशं भावं नीतस्तच्च न बुध्यसे॥', 'daivatāni hi nandanti dharmayuktena kena cit
yena tvam īdṛśaṃ bhāvaṃ nītas tac ca na budhyase', null, 7015016),
('ramayana-7-15-17', 17, 'Uttara Kanda, Sarga 15, Verse 17', 'यो हि मातॄः पितॄन्भ्रातॄनाचर्यांश्चावमन्यते।
स पश्यति फलं तस्य प्रेतराजवशं गतः॥', 'yo hi mātṝḥ pitṝn bhrātṝn ācaryāṃś cāvamanyate
sa paśyati phalaṃ tasya pretarājavaśaṃ gataḥ', null, 7015017),
('ramayana-7-15-18', 18, 'Uttara Kanda, Sarga 15, Verse 18', 'अध्रुवे हि शरीरे यो न करोति तपोऽर्जनम्।
स पश्चात्तप्यते मूढो मृतो दृष्ट्वात्मनो गतिम्॥', 'adhruve hi śarīre yo na karoti tapo ''rjanam
sa paścāt tapyate mūḍho mṛto dṛṣṭvātmano gatim', null, 7015018),
('ramayana-7-15-19', 19, 'Uttara Kanda, Sarga 15, Verse 19', 'कस्य चिन्न हि दुर्बुधेश्छन्दतो जायते मतिः।
यादृशं कुरुते कर्म तादृशं फलमश्नुते॥', 'kasya cin na hi durbudheś chandato jāyate matiḥ
yādṛśaṃ kurute karma tādṛśaṃ phalam aśnute', null, 7015019),
('ramayana-7-15-20', 20, 'Uttara Kanda, Sarga 15, Verse 20', 'बुद्धिं रूपं बलं वित्तं पुत्रान्माहात्म्यमेव च।
प्रप्नुवन्ति नराः सर्वं स्वकृतैः पूर्वकर्मभिः॥', 'buddhiṃ rūpaṃ balaṃ vittaṃ putrān māhātmyam eva ca
prapnuvanti narāḥ sarvaṃ svakṛtaiḥ pūrvakarmabhiḥ', null, 7015020),
('ramayana-7-15-21', 21, 'Uttara Kanda, Sarga 15, Verse 21', 'एवं निरयगामी त्वं यस्य ते मतिरीदृशी।
न त्वां समभिभाषिष्ये दुर्वृत्तस्यैष निर्णयः॥', 'evaṃ nirayagāmī tvaṃ yasya te matir īdṛśī
na tvāṃ samabhibhāṣiṣye durvṛttasyaiṣa nirṇayaḥ', null, 7015021),
('ramayana-7-15-22', 22, 'Uttara Kanda, Sarga 15, Verse 22', 'एवमुक्त्वा ततस्तेन तस्यामात्याः समाहताः।
मारीचप्रमुखाः सर्वे विमुखा विप्रदुद्रुवुः॥', 'evam uktvā tatas tena tasyāmātyāḥ samāhatāḥ
mārīcapramukhāḥ sarve vimukhā vipradudruvuḥ', null, 7015022),
('ramayana-7-15-23', 23, 'Uttara Kanda, Sarga 15, Verse 23', 'ततस्तेन दशग्रीवो यक्षेन्द्रेण महात्मना।
गदयाभिहतो मूर्ध्नि न च स्थानाद्व्यकम्पत॥', 'tatas tena daśagrīvo yakṣendreṇa mahātmanā
gadayābhihato mūrdhni na ca sthānād vyakampata', null, 7015023),
('ramayana-7-15-24', 24, 'Uttara Kanda, Sarga 15, Verse 24', 'ततस्तौ राम निघ्नन्तावन्योन्यं परमाहवे।
न विह्वलौ न च श्रान्तौ बभूवतुरमर्षणैः॥', 'tatas tau rāma nighnantāv anyonyaṃ paramāhave
na vihvalau na ca śrāntau babhūvatur amarṣaṇaiḥ', null, 7015024),
('ramayana-7-15-25', 25, 'Uttara Kanda, Sarga 15, Verse 25', 'आग्नेयमस्त्रं स ततो मुमोच धनदो रणे।
वारुणेन दशग्रीवस्तदस्त्रं प्रत्यवारयत्॥', 'āgneyam astraṃ sa tato mumoca dhanado raṇe
vāruṇena daśagrīvas tad astraṃ pratyavārayat', null, 7015025),
('ramayana-7-15-26', 26, 'Uttara Kanda, Sarga 15, Verse 26', 'ततो मायां प्रविष्टः स राक्षसीं राक्षसेश्वरः।
जघान मूर्ध्नि धनदं व्याविध्य महतीं गदाम्॥', 'tato māyāṃ praviṣṭaḥ sa rākṣasīṃ rākṣaseśvaraḥ
jaghāna mūrdhni dhanadaṃ vyāvidhya mahatīṃ gadām', null, 7015026),
('ramayana-7-15-27', 27, 'Uttara Kanda, Sarga 15, Verse 27', 'एवं स तेनाभिहतो विह्वलः शोणितोक्षितः।
कृत्तमूल इवाशोको निपपात धनाधिपः॥', 'evaṃ sa tenābhihato vihvalaḥ śoṇitokṣitaḥ
kṛttamūla ivāśoko nipapāta dhanādhipaḥ', null, 7015027),
('ramayana-7-15-28', 28, 'Uttara Kanda, Sarga 15, Verse 28', 'ततः पद्मादिभिस्तत्र निधिभिः स धनाधिपः।
नन्दनं वनमानीय धनदो श्वासितस्तदा॥', 'tataḥ padmādibhis tatra nidhibhiḥ sa dhanādhipaḥ
nandanaṃ vanam ānīya dhanado śvāsitas tadā', null, 7015028),
('ramayana-7-15-29', 29, 'Uttara Kanda, Sarga 15, Verse 29', 'ततो निर्जित्य तं राम धनदं राक्षसाधिपः।
पुष्पकं तस्य जग्राह विमानं जयलक्षणम्॥', 'tato nirjitya taṃ rāma dhanadaṃ rākṣasādhipaḥ
puṣpakaṃ tasya jagrāha vimānaṃ jayalakṣaṇam', null, 7015029),
('ramayana-7-15-30', 30, 'Uttara Kanda, Sarga 15, Verse 30', 'काञ्चनस्तम्भसंवीतं वैदूर्यमणितोरणम्।
मुक्ताजालप्रतिच्छन्नं सर्वकामफलद्रुमम्॥', 'kāñcanastambhasaṃvītaṃ vaidūryamaṇitoraṇam
muktājālapraticchannaṃ sarvakāmaphaladrumam', null, 7015030),
('ramayana-7-15-31', 31, 'Uttara Kanda, Sarga 15, Verse 31', 'तत्तु राजा समारुह्य कामगं वीर्यनिर्जितम्।
जित्वा वैश्रवणं देवं कैलासादवरोहत॥', 'tat tu rājā samāruhya kāmagaṃ vīryanirjitam
jitvā vaiśravaṇaṃ devaṃ kailāsād avarohata', null, 7015031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 16 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-16-1', 1, 'Uttara Kanda, Sarga 16, Verse 1', 'स जित्वा भ्रातरं राम धनदं राक्षसाधिपः।
महासेनप्रसूतिं तु ययौ शरवणं ततः॥', 'sa jitvā bhrātaraṃ rāma dhanadaṃ rākṣasādhipaḥ
mahāsenaprasūtiṃ tu yayau śaravaṇaṃ tataḥ', null, 7016001),
('ramayana-7-16-2', 2, 'Uttara Kanda, Sarga 16, Verse 2', 'अथापश्यद्दशग्रीवो रौक्मं शरवणं तदा।
गभस्तिजालसंवीतं द्वितीयमिव भास्करम्॥', 'athāpaśyad daśagrīvo raukmaṃ śaravaṇaṃ tadā
gabhastijālasaṃvītaṃ dvitīyam iva bhāskaram', null, 7016002),
('ramayana-7-16-3', 3, 'Uttara Kanda, Sarga 16, Verse 3', 'पर्वतं स समासाद्य किं चिद्रम्यवनान्तरम्।
अपश्यत्पुष्पकं तत्र राम विष्टम्भितं दिवि॥', 'parvataṃ sa samāsādya kiṃ cid ramyavanāntaram
apaśyat puṣpakaṃ tatra rāma viṣṭambhitaṃ divi', null, 7016003),
('ramayana-7-16-4', 4, 'Uttara Kanda, Sarga 16, Verse 4', 'विष्टब्धं पुष्पकं दृष्ट्वा कामगं ह्यगमं कृतम्।
राक्षसश्चिन्तयामास सचिवैस्तैः समावृतः॥', 'viṣṭabdhaṃ puṣpakaṃ dṛṣṭvā kāmagaṃ hy agamaṃ kṛtam
rākṣasaś cintayām āsa sacivais taiḥ samāvṛtaḥ', null, 7016004),
('ramayana-7-16-5', 5, 'Uttara Kanda, Sarga 16, Verse 5', 'किमिदं यन्निमित्तं मे न च गच्छति पुष्पकम्।
पर्वतस्योपरिस्थस्य कस्य कर्म त्विदं भवेत्॥', 'kim idaṃ yannimittaṃ me na ca gacchati puṣpakam
parvatasyoparisthasya kasya karma tv idaṃ bhavet', null, 7016005),
('ramayana-7-16-6', 6, 'Uttara Kanda, Sarga 16, Verse 6', 'ततोऽब्रवीद्दशग्रीवं मारीचो बुद्धिकोविदः।
नैतन्निष्कारणं राजन्पुष्पकोऽयं न गच्छति॥', 'tato ''bravīd daśagrīvaṃ mārīco buddhikovidaḥ
naitan niṣkāraṇaṃ rājan puṣpako ''yaṃ na gacchati', null, 7016006),
('ramayana-7-16-7', 7, 'Uttara Kanda, Sarga 16, Verse 7', 'ततः पार्श्वमुपागम्य भवस्यानुचरो बली।
नन्दीश्वर उवाचेदं राक्षसेन्द्रमशङ्कितः॥', 'tataḥ pārśvam upāgamya bhavasyānucaro balī
nandīśvara uvācedaṃ rākṣasendram aśaṅkitaḥ', null, 7016007),
('ramayana-7-16-8', 8, 'Uttara Kanda, Sarga 16, Verse 8', 'निवर्तस्व दशग्रीव शैले क्रीडति शंकरः॥', 'nivartasva daśagrīva śaile krīḍati śaṃkaraḥ', null, 7016008),
('ramayana-7-16-9', 9, 'Uttara Kanda, Sarga 16, Verse 9', 'सुपर्णनागयक्षाणां दैत्यदानवरक्षसाम्।
प्राणिनामेव सर्वेषामगम्यः पर्वतः कृतः॥', 'suparṇanāgayakṣāṇāṃ daityadānavarakṣasām
prāṇinām eva sarveṣām agamyaḥ parvataḥ kṛtaḥ', null, 7016009),
('ramayana-7-16-10', 10, 'Uttara Kanda, Sarga 16, Verse 10', 'स रोषात्ताम्रनयनः पुष्पकादवरुह्य च।
कोऽयं शंकर इत्युक्त्वा शैलमूलमुपागमत्॥', 'sa roṣāt tāmranayanaḥ puṣpakād avaruhya ca
ko ''yaṃ śaṃkara ity uktvā śailamūlam upāgamat', null, 7016010),
('ramayana-7-16-11', 11, 'Uttara Kanda, Sarga 16, Verse 11', 'नन्दीश्वरमथापश्यदविदूरस्थितं प्रभुम्।
दीप्तं शूलमवष्टभ्य द्वितीयमिव शंकरम्॥', 'nandīśvaram athāpaśyad avidūrasthitaṃ prabhum
dīptaṃ śūlam avaṣṭabhya dvitīyam iva śaṃkaram', null, 7016011),
('ramayana-7-16-12', 12, 'Uttara Kanda, Sarga 16, Verse 12', 'स वानरमुखं दृष्ट्वा तमवज्ञाय राक्षसः।
प्रहासं मुमुचे मौर्ख्यात्सतोय इव तोयदः॥', 'sa vānaramukhaṃ dṛṣṭvā tam avajñāya rākṣasaḥ
prahāsaṃ mumuce maurkhyāt satoya iva toyadaḥ', null, 7016012),
('ramayana-7-16-13', 13, 'Uttara Kanda, Sarga 16, Verse 13', 'संक्रुद्धो भगवान्नन्दी शंकरस्यापरा तनुः।
अब्रवीद्राक्षसं तत्र दशग्रीवमुपस्थितम्॥', 'saṃkruddho bhagavān nandī śaṃkarasyāparā tanuḥ
abravīd rākṣasaṃ tatra daśagrīvam upasthitam', null, 7016013),
('ramayana-7-16-14', 14, 'Uttara Kanda, Sarga 16, Verse 14', 'यस्माद्वानरमूर्तिं मां दृष्ट्वा राक्षसदुर्मते।
मौर्ख्यात्त्वमवजानीषे परिहासं च मुञ्चसि॥', 'yasmād vānaramūrtiṃ māṃ dṛṣṭvā rākṣasadurmate
maurkhyāt tvam avajānīṣe parihāsaṃ ca muñcasi', null, 7016014),
('ramayana-7-16-15', 15, 'Uttara Kanda, Sarga 16, Verse 15', 'तस्मान्मद्रूपसंयुक्ता मद्वीर्यसमतेजसः।
उत्पत्स्यन्ते वधार्थं हि कुलस्य तव वानराः॥', 'tasmān madrūpasaṃyuktā madvīryasamatejasaḥ
utpatsyante vadhārthaṃ hi kulasya tava vānarāḥ', null, 7016015),
('ramayana-7-16-16', 16, 'Uttara Kanda, Sarga 16, Verse 16', 'किं त्विदानीं मया शक्यं कर्तुं यत्त्वां निशाचर।
न हन्तव्यो हतस्त्वं हि पूर्वमेव स्वकर्मभिः॥', 'kiṃ tv idānīṃ mayā śakyaṃ kartuṃ yat tvāṃ niśācara
na hantavyo hatas tvaṃ hi pūrvam eva svakarmabhiḥ', null, 7016016),
('ramayana-7-16-17', 17, 'Uttara Kanda, Sarga 16, Verse 17', 'अचिन्तयित्वा स तदा नन्दिवाक्यं निशाचरः।
पर्वतं तं समासाद्य वाक्यमेतदुवाच ह॥', 'acintayitvā sa tadā nandivākyaṃ niśācaraḥ
parvataṃ taṃ samāsādya vākyam etad uvāca ha', null, 7016017),
('ramayana-7-16-18', 18, 'Uttara Kanda, Sarga 16, Verse 18', 'पुष्पकस्य गतिश्छिन्ना यत्कृते मम गच्छतः।
तदेतच्छैलमुन्मूलं करोमि तव गोपते॥', 'puṣpakasya gatiś chinnā yatkṛte mama gacchataḥ
tad etac chailam unmūlaṃ karomi tava gopate', null, 7016018),
('ramayana-7-16-19', 19, 'Uttara Kanda, Sarga 16, Verse 19', 'केन प्रभावेन भवस्तत्र क्रीडति राजवत्।
विज्ञातव्यं न जानीषे भयस्थानमुपस्थितम्॥', 'kena prabhāvena bhavas tatra krīḍati rājavat
vijñātavyaṃ na jānīṣe bhayasthānam upasthitam', null, 7016019),
('ramayana-7-16-20', 20, 'Uttara Kanda, Sarga 16, Verse 20', 'एवमुक्त्वा ततो राजन्भुजान्प्रक्षिप्य पर्वते।
तोलयामास तं शैलं समृगव्यालपादपम्॥', 'evam uktvā tato rājan bhujān prakṣipya parvate
tolayām āsa taṃ śailaṃ samṛgavyālapādapam', null, 7016020),
('ramayana-7-16-21', 21, 'Uttara Kanda, Sarga 16, Verse 21', 'ततो राम महादेवः प्रहसन्वीक्ष्य तत्कृतम्।
पादाङ्गुष्ठेन तं शैलं पीडयामास लीलया॥', 'tato rāma mahādevaḥ prahasan vīkṣya tatkṛtam
pādāṅguṣṭhena taṃ śailaṃ pīḍayām āsa līlayā', null, 7016021),
('ramayana-7-16-22', 22, 'Uttara Kanda, Sarga 16, Verse 22', 'ततस्ते पीडितास्तस्य शैलस्याधो गता भुजाः।
विस्मिताश्चाभवंस्तत्र सचिवास्तस्य रक्षसः॥', 'tatas te pīḍitās tasya śailasyādho gatā bhujāḥ
vismitāś cābhavaṃs tatra sacivās tasya rakṣasaḥ', null, 7016022),
('ramayana-7-16-23', 23, 'Uttara Kanda, Sarga 16, Verse 23', 'रक्षसा तेन रोषाच्च भुजानां पीडनात्तथा।
मुक्तो विरावः सुमहांस्त्रैलोक्यं येन पूरितम्॥', 'rakṣasā tena roṣāc ca bhujānāṃ pīḍanāt tathā
mukto virāvaḥ sumahāṃs trailokyaṃ yena pūritam', null, 7016023),
('ramayana-7-16-24', 24, 'Uttara Kanda, Sarga 16, Verse 24', 'मानुषाः शब्दवित्रस्ता मेनिरे लोकसंक्षयम्।
देवताश्चापि संक्षुब्धाश्चलिताः स्वेषु कर्मसु॥', 'mānuṣāḥ śabdavitrastā menire lokasaṃkṣayam
devatāś cāpi saṃkṣubdhāś calitāḥ sveṣu karmasu', null, 7016024),
('ramayana-7-16-25', 25, 'Uttara Kanda, Sarga 16, Verse 25', 'ततः प्रीतो महादेवः शैलाग्रे विष्ठितस्तदा।
मुक्त्वा तस्य भुजान्राजन्प्राह वाक्यं दशाननम्॥', 'tataḥ prīto mahādevaḥ śailāgre viṣṭhitas tadā
muktvā tasya bhujān rājan prāha vākyaṃ daśānanam', null, 7016025),
('ramayana-7-16-26', 26, 'Uttara Kanda, Sarga 16, Verse 26', 'प्रीतोऽस्मि तव वीर्याच्च शौण्डीर्याच्च निशाचर।
रवतो वेदना मुक्तः स्वरः परमदारुणः॥', 'prīto ''smi tava vīryāc ca śauṇḍīryāc ca niśācara
ravato vedanā muktaḥ svaraḥ paramadāruṇaḥ', null, 7016026),
('ramayana-7-16-27', 27, 'Uttara Kanda, Sarga 16, Verse 27', 'यस्माल्लोकत्रयं त्वेतद्रावितं भयमागतम्।
तस्मात्त्वं रावणो नाम नाम्ना तेन भविष्यसि॥', 'yasmāl lokatrayaṃ tv etad rāvitaṃ bhayam āgatam
tasmāt tvaṃ rāvaṇo nāma nāmnā tena bhaviṣyasi', null, 7016027),
('ramayana-7-16-28', 28, 'Uttara Kanda, Sarga 16, Verse 28', 'देवता मानुषा यक्षा ये चान्ये जगतीतले।
एवं त्वामभिधास्यन्ति रावणं लोकरावणम्॥', 'devatā mānuṣā yakṣā ye cānye jagatītale
evaṃ tvām abhidhāsyanti rāvaṇaṃ lokarāvaṇam', null, 7016028),
('ramayana-7-16-29', 29, 'Uttara Kanda, Sarga 16, Verse 29', 'गच्छ पौलस्त्य विस्रब्धः पथा येन त्वमिच्छसि।
मया त्वमभ्यनुज्ञातो राक्षसाधिप गम्यताम्॥', 'gaccha paulastya visrabdhaḥ pathā yena tvam icchasi
mayā tvam abhyanujñāto rākṣasādhipa gamyatām', null, 7016029),
('ramayana-7-16-30', 30, 'Uttara Kanda, Sarga 16, Verse 30', 'साक्षान्महेश्वरेणैवं कृतनामा स रावणः।
अभिवाद्य महादेवं विमानं तत्समारुहत्॥', 'sākṣān maheśvareṇaivaṃ kṛtanāmā sa rāvaṇaḥ
abhivādya mahādevaṃ vimānaṃ tat samāruhat', null, 7016030),
('ramayana-7-16-31', 31, 'Uttara Kanda, Sarga 16, Verse 31', 'ततो महीतले राम परिचक्राम रावणः।
क्षत्रियान्सुमहावीर्यान्बाधमानस्ततस्ततः॥', 'tato mahītale rāma paricakrāma rāvaṇaḥ
kṣatriyān sumahāvīryān bādhamānas tatas tataḥ', null, 7016031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 17 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-17-1', 1, 'Uttara Kanda, Sarga 17, Verse 1', 'अथ राजन्महाबाहुर्विचरन्स महीतलम्।
हिमवद्वनमासाद्य परिचक्राम रावणः॥', 'atha rājan mahābāhur vicaran sa mahītalam
himavadvanam āsādya paricakrāma rāvaṇaḥ', null, 7017001),
('ramayana-7-17-2', 2, 'Uttara Kanda, Sarga 17, Verse 2', 'तत्रापश्यत वै कन्यां कृष्टाजिनजटाधराम्।
आर्षेण विधिना युक्तां तपन्तीं देवतामिव॥', 'tatrāpaśyata vai kanyāṃ kṛṣṭājinajaṭādharām
ārṣeṇa vidhinā yuktāṃ tapantīṃ devatām iva', null, 7017002),
('ramayana-7-17-3', 3, 'Uttara Kanda, Sarga 17, Verse 3', 'स दृष्ट्वा रूपसंपन्नां कन्यां तां सुमहाव्रताम्।
काममोहपरीतात्मा पप्रच्छ प्रहसन्निव॥', 'sa dṛṣṭvā rūpasaṃpannāṃ kanyāṃ tāṃ sumahāvratām
kāmamohaparītātmā papraccha prahasann iva', null, 7017003),
('ramayana-7-17-4', 4, 'Uttara Kanda, Sarga 17, Verse 4', 'किमिदं वर्तसे भद्रे विरुद्धं यौवनस्य ते।
न हि युक्ता तवैतस्य रूपस्येयं प्रतिक्रिया॥', 'kim idaṃ vartase bhadre viruddhaṃ yauvanasya te
na hi yuktā tavaitasya rūpasyeyaṃ pratikriyā', null, 7017004),
('ramayana-7-17-5', 5, 'Uttara Kanda, Sarga 17, Verse 5', 'कस्यासि दुहिता भद्रे को वा भर्ता तवानघे।
पृच्छतः शंस मे शीघ्रं को वा हेतुस्तपोऽर्जने॥', 'kasyāsi duhitā bhadre ko vā bhartā tavānaghe
pṛcchataḥ śaṃsa me śīghraṃ ko vā hetus tapo''rjane', null, 7017005),
('ramayana-7-17-6', 6, 'Uttara Kanda, Sarga 17, Verse 6', 'एवमुक्ता तु सा कन्या तेनानार्येण रक्षसा।
अब्रवीद्विधिवत्कृत्वा तस्यातिथ्यं तपोधना॥', 'evam uktā tu sā kanyā tenānāryeṇa rakṣasā
abravīd vidhivat kṛtvā tasyātithyaṃ tapodhanā', null, 7017006),
('ramayana-7-17-7', 7, 'Uttara Kanda, Sarga 17, Verse 7', 'कुशध्वजो नाम पिता ब्रह्मर्षिर्मम धार्मिकः।
बृहस्पतिसुतः श्रीमान्बुद्ध्या तुल्यो बृहस्पतेः॥', 'kuśadhvajo nāma pitā brahmarṣir mama dhārmikaḥ
bṛhaspatisutaḥ śrīmān buddhyā tulyo bṛhaspateḥ', null, 7017007),
('ramayana-7-17-8', 8, 'Uttara Kanda, Sarga 17, Verse 8', 'तस्याहं कुर्वतो नित्यं वेदाभ्यासं महात्मनः।
संभूता वान्मयी कन्या नाम्ना वेदवती स्मृता॥', 'tasyāhaṃ kurvato nityaṃ vedābhyāsaṃ mahātmanaḥ
saṃbhūtā vānmayī kanyā nāmnā vedavatī smṛtā', null, 7017008),
('ramayana-7-17-9', 9, 'Uttara Kanda, Sarga 17, Verse 9', 'ततो देवाः सगन्धर्वा यक्षराक्षसपन्नगाः।
ते चापि गत्वा पितरं वरणं रोचयन्ति मे॥', 'tato devāḥ sagandharvā yakṣarākṣasapannagāḥ
te cāpi gatvā pitaraṃ varaṇaṃ rocayanti me', null, 7017009),
('ramayana-7-17-10', 10, 'Uttara Kanda, Sarga 17, Verse 10', 'न च मां स पिता तेभ्यो दत्तवान्राक्षसेश्वर।
कारणं तद्वदिष्यामि निशामय महाभुज॥', 'na ca māṃ sa pitā tebhyo dattavān rākṣaseśvara
kāraṇaṃ tad vadiṣyāmi niśāmaya mahābhuja', null, 7017010),
('ramayana-7-17-11', 11, 'Uttara Kanda, Sarga 17, Verse 11', 'पितुस्तु मम जामाता विष्णुः किल सुरोत्तमः।
अभिप्रेतस्त्रिलोकेशस्तस्मान्नान्यस्य मे पिताः॥', 'pitus tu mama jāmātā viṣṇuḥ kila surottamaḥ
abhipretas trilokeśas tasmān nānyasya me pitāḥ', null, 7017011),
('ramayana-7-17-12', 12, 'Uttara Kanda, Sarga 17, Verse 12', 'दातुमिच्छति धर्मात्मा तच्छ्रुत्वा बलदर्पितः।
शम्भुर्नाम ततो राजा दैत्यानां कुपितोऽभवत्।
तेन रात्रौ प्रसुप्तो मे पिता पापेन हिंसितः॥', 'dātum icchati dharmātmā tac chrutvā baladarpitaḥ
śambhur nāma tato rājā daityānāṃ kupito ''bhavat
tena rātrau prasupto me pitā pāpena hiṃsitaḥ', null, 7017012),
('ramayana-7-17-13', 13, 'Uttara Kanda, Sarga 17, Verse 13', 'ततो मे जननी दीना तच्छरीरं पितुर्मम।
परिष्वज्य महाभागा प्रविष्टा दहनं सह॥', 'tato me jananī dīnā tac charīraṃ pitur mama
pariṣvajya mahābhāgā praviṣṭā dahanaṃ saha', null, 7017013),
('ramayana-7-17-14', 14, 'Uttara Kanda, Sarga 17, Verse 14', 'ततो मनोरथं सत्यं पितुर्नारायणं प्रति।
करोमीति ममेच्छा च हृदये साधु विष्ठिता॥', 'tato manorathaṃ satyaṃ pitur nārāyaṇaṃ prati
karomīti mamecchā ca hṛdaye sādhu viṣṭhitā', null, 7017014),
('ramayana-7-17-15', 15, 'Uttara Kanda, Sarga 17, Verse 15', 'अहं प्रेतगतस्यापि करिष्ये काङ्क्षितं पितुः।
इति प्रतिज्ञामारुह्य चरामि विपुलं तपः॥', 'ahaṃ pretagatasyāpi kariṣye kāṅkṣitaṃ pituḥ
iti pratijñām āruhya carāmi vipulaṃ tapaḥ', null, 7017015),
('ramayana-7-17-16', 16, 'Uttara Kanda, Sarga 17, Verse 16', 'एतत्ते सर्वमाख्यातं मया राक्षसपुंगव।
आश्रितां विद्धि मां धर्मं नारायणपतीच्छया॥', 'etat te sarvam ākhyātaṃ mayā rākṣasapuṃgava
āśritāṃ viddhi māṃ dharmaṃ nārāyaṇapatīcchayā', null, 7017016),
('ramayana-7-17-17', 17, 'Uttara Kanda, Sarga 17, Verse 17', 'विज्ञातस्त्वं हि मे राजन्गच्छ पौलस्त्यनन्दन।
जानामि तपसा सर्वं त्रैलोक्ये यद्धि वर्तते॥', 'vijñātas tvaṃ hi me rājan gaccha paulastyanandana
jānāmi tapasā sarvaṃ trailokye yad dhi vartate', null, 7017017),
('ramayana-7-17-18', 18, 'Uttara Kanda, Sarga 17, Verse 18', 'सोऽब्रवीद्रावणस्तत्र तां कन्यां सुमहाव्रताम्।
अवरुह्य विमानाग्रात्कन्दर्पशरपीडितः॥', 'so ''bravīd rāvaṇas tatra tāṃ kanyāṃ sumahāvratām
avaruhya vimānāgrāt kandarpaśarapīḍitaḥ', null, 7017018),
('ramayana-7-17-19', 19, 'Uttara Kanda, Sarga 17, Verse 19', 'अवलिप्तासि सुश्रोणि यस्यास्ते मतिरीदृशी।
वृद्धानां मृगशावाक्षि भ्राजते धर्मसंचयः॥', 'avaliptāsi suśroṇi yasyās te matir īdṛśī
vṛddhānāṃ mṛgaśāvākṣi bhrājate dharmasaṃcayaḥ', null, 7017019),
('ramayana-7-17-20', 20, 'Uttara Kanda, Sarga 17, Verse 20', 'त्वं सर्वगुणसंपन्ना नार्हसे कर्तुमीदृशम्।
त्रैलोक्यसुन्दरी भीरु यौवने वार्धकं विधिम्॥', 'tvaṃ sarvaguṇasaṃpannā nārhase kartum īdṛśam
trailokyasundarī bhīru yauvane vārdhakaṃ vidhim', null, 7017020),
('ramayana-7-17-21', 21, 'Uttara Kanda, Sarga 17, Verse 21', 'कश्च तावदसौ यं त्वं विष्णुरित्यभिभाषसे।
वीर्येण तपसा चैव भोगेन च बलेन च।
न मयासौ समो भद्रे यं त्वं कामयसेऽङ्गने॥', 'kaś ca tāvad asau yaṃ tvaṃ viṣṇur ity abhibhāṣase
vīryeṇa tapasā caiva bhogena ca balena ca
na mayāsau samo bhadre yaṃ tvaṃ kāmayase ''ṅgane', null, 7017021),
('ramayana-7-17-22', 22, 'Uttara Kanda, Sarga 17, Verse 22', 'म मैवमिति सा कन्या तमुवाच निशाचरम्।
मूर्धजेषु च तां रक्षः कराग्रेण परामृशत्॥', 'ma maivam iti sā kanyā tam uvāca niśācaram
mūrdhajeṣu ca tāṃ rakṣaḥ karāgreṇa parāmṛśat', null, 7017022),
('ramayana-7-17-23', 23, 'Uttara Kanda, Sarga 17, Verse 23', 'ततो वेदवती क्रुद्धा केशान्हस्तेन साच्छिनत्।
उवाचाग्निं समाधाय मरणाय कृतत्वरा॥', 'tato vedavatī kruddhā keśān hastena sācchinat
uvācāgniṃ samādhāya maraṇāya kṛtatvarā', null, 7017023),
('ramayana-7-17-24', 24, 'Uttara Kanda, Sarga 17, Verse 24', 'धर्षितायास्त्वयानार्य नेदानीं मम जीवितम्।
रक्षस्तस्मात्प्रवेक्ष्यामि पश्यतस्ते हुताशनम्॥', 'dharṣitāyās tvayānārya nedānīṃ mama jīvitam
rakṣas tasmāt pravekṣyāmi paśyatas te hutāśanam', null, 7017024),
('ramayana-7-17-25', 25, 'Uttara Kanda, Sarga 17, Verse 25', 'यस्मात्तु धर्षिता चाहमपापा चाप्यनाथवत्।
तस्मात्तव वधार्थं वै समुत्पत्स्याम्यहं पुनः॥', 'yasmāt tu dharṣitā cāham apāpā cāpy anāthavat
tasmāt tava vadhārthaṃ vai samutpatsyāmy ahaṃ punaḥ', null, 7017025),
('ramayana-7-17-26', 26, 'Uttara Kanda, Sarga 17, Verse 26', 'न हि शक्यः स्त्रिया पाप हन्तुं त्वं तु विशेषतः।
शापे त्वयि मयोत्सृष्टे तपसश्च व्ययो भवेत्॥', 'na hi śakyaḥ striyā pāpa hantuṃ tvaṃ tu viśeṣataḥ
śāpe tvayi mayotsṛṣṭe tapasaś ca vyayo bhavet', null, 7017026),
('ramayana-7-17-27', 27, 'Uttara Kanda, Sarga 17, Verse 27', 'यदि त्वस्ति मया किं चित्कृतं दत्तं हुतं तथा।
तेन ह्ययोनिजा साध्वी भवेयं धर्मिणः सुता॥', 'yadi tv asti mayā kiṃ cit kṛtaṃ dattaṃ hutaṃ tathā
tena hy ayonijā sādhvī bhaveyaṃ dharmiṇaḥ sutā', null, 7017027),
('ramayana-7-17-28', 28, 'Uttara Kanda, Sarga 17, Verse 28', 'एवमुक्त्वा प्रविष्टा सा ज्वलन्तं वै हुताशनम्।
पपात च दिवो दिव्या पुष्पवृष्टिः समन्ततः॥', 'evam uktvā praviṣṭā sā jvalantaṃ vai hutāśanam
papāta ca divo divyā puṣpavṛṣṭiḥ samantataḥ', null, 7017028),
('ramayana-7-17-29', 29, 'Uttara Kanda, Sarga 17, Verse 29', 'पूर्वं क्रोधहतः शत्रुर्ययासौ निहतस्त्वया।
समुपाश्रित्य शैलाभं तव वीर्यममानुषम्॥', 'pūrvaṃ krodhahataḥ śatrur yayāsau nihatas tvayā
samupāśritya śailābhaṃ tava vīryam amānuṣam', null, 7017029),
('ramayana-7-17-30', 30, 'Uttara Kanda, Sarga 17, Verse 30', 'एवमेषा महाभागा मर्त्येषूत्पद्यते पुनः।
क्षेत्रे हलमुखग्रस्ते वेद्यामग्निशिखोपमा॥', 'evam eṣā mahābhāgā martyeṣūtpadyate punaḥ
kṣetre halamukhagraste vedyām agniśikhopamā', null, 7017030),
('ramayana-7-17-31', 31, 'Uttara Kanda, Sarga 17, Verse 31', 'एषा वेदवती नाम पूर्वमासीत्कृते युगे।
त्रेतायुगमनुप्राप्य वधार्थं तस्य रक्षसः।
सीतोत्पन्नेति सीतैषा मानुषैः पुनरुच्यते॥', 'eṣā vedavatī nāma pūrvam āsīt kṛte yuge
tretāyugam anuprāpya vadhārthaṃ tasya rakṣasaḥ
sītotpanneti sītaiṣā mānuṣaiḥ punar ucyate', null, 7017031)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 18 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-18-1', 1, 'Uttara Kanda, Sarga 18, Verse 1', 'प्रविष्टायां हुताशं तु वेदवत्यां स रावणः।
पुष्पकं तत्समारुह्य परिचक्राम मेदिनीम्॥', 'praviṣṭāyāṃ hutāśaṃ tu vedavatyāṃ sa rāvaṇaḥ
puṣpakaṃ tat samāruhya paricakrāma medinīm', null, 7018001),
('ramayana-7-18-2', 2, 'Uttara Kanda, Sarga 18, Verse 2', 'ततो मरुत्तं नृपतिं यजन्तं सह दैवतैः।
उशीरबीजमासाद्य ददर्श स तु राक्षसः॥', 'tato maruttaṃ nṛpatiṃ yajantaṃ saha daivataiḥ
uśīrabījam āsādya dadarśa sa tu rākṣasaḥ', null, 7018002),
('ramayana-7-18-3', 3, 'Uttara Kanda, Sarga 18, Verse 3', 'संवर्तो नाम ब्रह्मर्षिर्भ्राता साक्षाद्बृहस्पतेः।
याजयामास धर्मज्ञः सर्वैर्ब्रह्मगणैर्वृतः॥', 'saṃvarto nāma brahmarṣir bhrātā sākṣād bṛhaspateḥ
yājayām āsa dharmajñaḥ sarvair brahmagaṇair vṛtaḥ', null, 7018003),
('ramayana-7-18-4', 4, 'Uttara Kanda, Sarga 18, Verse 4', 'दृष्ट्वा देवास्तु तद्रक्षो वरदानेन दुर्जयम्।
तां तां योनिं समापन्नास्तस्य धर्षणभीरवः॥', 'dṛṣṭvā devās tu tad rakṣo varadānena durjayam
tāṃ tāṃ yoniṃ samāpannās tasya dharṣaṇabhīravaḥ', null, 7018004),
('ramayana-7-18-5', 5, 'Uttara Kanda, Sarga 18, Verse 5', 'इन्द्रो मयूरः संवृत्तो धर्मराजस्तु वायसः।
कृकलासो धनाध्यक्षो हंसो वै वरुणोऽभवत्॥', 'indro mayūraḥ saṃvṛtto dharmarājas tu vāyasaḥ
kṛkalāso dhanādhyakṣo haṃso vai varuṇo ''bhavat', null, 7018005),
('ramayana-7-18-6', 6, 'Uttara Kanda, Sarga 18, Verse 6', 'तं च राजानमासाद्य रावणो राक्षसाधिपः।
प्राह युद्धं प्रयच्चेति निर्जितोऽस्मीति वा वद॥', 'taṃ ca rājānam āsādya rāvaṇo rākṣasādhipaḥ
prāha yuddhaṃ prayacceti nirjito ''smīti vā vada', null, 7018006),
('ramayana-7-18-7', 7, 'Uttara Kanda, Sarga 18, Verse 7', 'ततो मरुत्तो नृपतिः को भवानित्युवाच तम्।
अवहासं ततो मुक्त्वा राक्षसो वाक्यमब्रवीत्॥', 'tato marutto nṛpatiḥ ko bhavān ity uvāca tam
avahāsaṃ tato muktvā rākṣaso vākyam abravīt', null, 7018007),
('ramayana-7-18-8', 8, 'Uttara Kanda, Sarga 18, Verse 8', 'अकुतूहलभावेन प्रीतोऽस्मि तव पार्थिव।
धनदस्यानुजं यो मां नावगच्छसि रावणम्॥', 'akutūhalabhāvena prīto ''smi tava pārthiva
dhanadasyānujaṃ yo māṃ nāvagacchasi rāvaṇam', null, 7018008),
('ramayana-7-18-9', 9, 'Uttara Kanda, Sarga 18, Verse 9', 'त्रिषु लोकेषु कः सोऽस्ति यो न जानाति मे बलम्।
भ्रातरं येन निर्जित्य विमानमिदमाहृतम्॥', 'triṣu lokeṣu kaḥ so ''sti yo na jānāti me balam
bhrātaraṃ yena nirjitya vimānam idam āhṛtam', null, 7018009),
('ramayana-7-18-10', 10, 'Uttara Kanda, Sarga 18, Verse 10', 'ततो मरुत्तो नृपतिस्तं राक्षसमथाब्रवीत्।
धन्यः खलु भवान्येन ज्येष्ठो भ्राता रणे जितः॥', 'tato marutto nṛpatis taṃ rākṣasam athābravīt
dhanyaḥ khalu bhavān yena jyeṣṭho bhrātā raṇe jitaḥ', null, 7018010),
('ramayana-7-18-11', 11, 'Uttara Kanda, Sarga 18, Verse 11', 'नाधर्मसहितं श्लाघ्यं न लोकप्रतिसंहितम्।
कर्म दौरात्म्यकं कृत्वा श्लाघसे भ्रातृनिर्जयात्॥', 'nādharmasahitaṃ ślāghyaṃ na lokapratisaṃhitam
karma daurātmyakaṃ kṛtvā ślāghase bhrātṛnirjayāt', null, 7018011),
('ramayana-7-18-12', 12, 'Uttara Kanda, Sarga 18, Verse 12', 'किं त्वं प्राक्केवलं धर्मं चरित्वा लब्धवान्वरम्।
श्रुतपूर्वं हि न मया यादृशं भाषसे स्वयम्॥', 'kiṃ tvaṃ prāk kevalaṃ dharmaṃ caritvā labdhavān varam
śrutapūrvaṃ hi na mayā yādṛśaṃ bhāṣase svayam', null, 7018012),
('ramayana-7-18-13', 13, 'Uttara Kanda, Sarga 18, Verse 13', 'ततः शरासनं गृह्य सायकांश्च स पार्थिवः।
रणाय निर्ययौ क्रुद्धः संवर्तो मार्गमावृणोत्॥', 'tataḥ śarāsanaṃ gṛhya sāyakāṃś ca sa pārthivaḥ
raṇāya niryayau kruddhaḥ saṃvarto mārgam āvṛṇot', null, 7018013),
('ramayana-7-18-14', 14, 'Uttara Kanda, Sarga 18, Verse 14', 'सोऽब्रवीत्स्नेहसंयुक्तं मरुत्तं तं महानृषिः।
श्रोतव्यं यदि मद्वाक्यं संप्रहारो न ते क्षमः॥', 'so ''bravīt snehasaṃyuktaṃ maruttaṃ taṃ mahān ṛṣiḥ
śrotavyaṃ yadi madvākyaṃ saṃprahāro na te kṣamaḥ', null, 7018014),
('ramayana-7-18-15', 15, 'Uttara Kanda, Sarga 18, Verse 15', 'माहेश्वरमिदं सत्रमसमाप्तं कुलं दहेत्।
दीक्षितस्य कुतो युद्धं क्रूरत्वं दीक्षिते कुतः॥', 'māheśvaram idaṃ satram asamāptaṃ kulaṃ dahet
dīkṣitasya kuto yuddhaṃ krūratvaṃ dīkṣite kutaḥ', null, 7018015),
('ramayana-7-18-16', 16, 'Uttara Kanda, Sarga 18, Verse 16', 'संशयश्च रणे नित्यं राक्षसश्चैष दुर्जयः।
स निवृत्तो गुरोर्वाक्यान्मरुत्तः पृथिवीपतिः।
विसृज्य सशरं चापं स्वस्थो मखमुखोऽभवत्॥', 'saṃśayaś ca raṇe nityaṃ rākṣasaś caiṣa durjayaḥ
sa nivṛtto guror vākyān maruttaḥ pṛthivīpatiḥ
visṛjya saśaraṃ cāpaṃ svastho makhamukho ''bhavat', null, 7018016),
('ramayana-7-18-17', 17, 'Uttara Kanda, Sarga 18, Verse 17', 'ततस्तं निर्जितं मत्वा घोषयामास वै शुकः।
रावणो जितवांश्चेति हर्षान्नादं च मुक्तवान्॥', 'tatas taṃ nirjitaṃ matvā ghoṣayām āsa vai śukaḥ
rāvaṇo jitavāṃś ceti harṣān nādaṃ ca muktavān', null, 7018017),
('ramayana-7-18-18', 18, 'Uttara Kanda, Sarga 18, Verse 18', 'तान्भक्षयित्वा तत्रस्थान्महर्षीन्यज्ञमागतान्।
वितृप्तो रुधिरैस्तेषां पुनः संप्रययौ महीम्॥', 'tān bhakṣayitvā tatrasthān maharṣīn yajñam āgatān
vitṛpto rudhirais teṣāṃ punaḥ saṃprayayau mahīm', null, 7018018),
('ramayana-7-18-19', 19, 'Uttara Kanda, Sarga 18, Verse 19', 'रावणे तु गते देवाः सेन्द्राश्चैव दिवौकसः।
ततः स्वां योनिमासाद्य तानि सत्त्वान्यथाब्रुवन्॥', 'rāvaṇe tu gate devāḥ sendrāś caiva divaukasaḥ
tataḥ svāṃ yonim āsādya tāni sattvāny athābruvan', null, 7018019),
('ramayana-7-18-20', 20, 'Uttara Kanda, Sarga 18, Verse 20', 'हर्षात्तदाब्रवीदिन्द्रो मयूरं नीलबर्हिणम्।
प्रीतोऽस्मि तव धर्मज्ञ उपकाराद्विहंगम॥', 'harṣāt tadābravīd indro mayūraṃ nīlabarhiṇam
prīto ''smi tava dharmajña upakārād vihaṃgama', null, 7018020),
('ramayana-7-18-21', 21, 'Uttara Kanda, Sarga 18, Verse 21', 'मम नेत्रसहस्रं यत्तत्ते बर्हे भविष्यति।
वर्षमाणे मयि मुदं प्राप्स्यसे प्रीतिलक्षणम्॥', 'mama netrasahasraṃ yat tat te barhe bhaviṣyati
varṣamāṇe mayi mudaṃ prāpsyase prītilakṣaṇam', null, 7018021),
('ramayana-7-18-22', 22, 'Uttara Kanda, Sarga 18, Verse 22', 'नीलाः किल पुरा बर्हा मयूराणां नराधिप।
सुराधिपाद्वरं प्राप्य गताः सर्वे विचित्रताम्॥', 'nīlāḥ kila purā barhā mayūrāṇāṃ narādhipa
surādhipād varaṃ prāpya gatāḥ sarve vicitratām', null, 7018022),
('ramayana-7-18-23', 23, 'Uttara Kanda, Sarga 18, Verse 23', 'धर्मराजोऽब्रवीद्राम प्राग्वंशे वायसं स्थितम्।
पक्षिंस्तवास्मि सुप्रीतः प्रीतस्य च वचः शृणु॥', 'dharmarājo ''bravīd rāma prāgvaṃśe vāyasaṃ sthitam
pakṣiṃs tavāsmi suprītaḥ prītasya ca vacaḥ śṛṇu', null, 7018023),
('ramayana-7-18-24', 24, 'Uttara Kanda, Sarga 18, Verse 24', 'यथान्ये विविधै रोगैः पीड्यन्ते प्राणिनो मया।
ते न ते प्रभविष्यन्ति मयि प्रीते न संशयः॥', 'yathānye vividhai rogaiḥ pīḍyante prāṇino mayā
te na te prabhaviṣyanti mayi prīte na saṃśayaḥ', null, 7018024),
('ramayana-7-18-25', 25, 'Uttara Kanda, Sarga 18, Verse 25', 'मृत्युतस्ते भयं नास्ति वरान्मम विहंगम।
यावत्त्वां न वधिष्यन्ति नरास्तावद्भविष्यसि॥', 'mṛtyutas te bhayaṃ nāsti varān mama vihaṃgama
yāvat tvāṃ na vadhiṣyanti narās tāvad bhaviṣyasi', null, 7018025),
('ramayana-7-18-26', 26, 'Uttara Kanda, Sarga 18, Verse 26', 'ये च मद्विषयस्थास्तु मानवाः क्षुधयार्दिताः।
त्वयि भुक्ते तु तृप्तास्ते भविष्यन्ति सबान्धवाः॥', 'ye ca madviṣayasthās tu mānavāḥ kṣudhayārditāḥ
tvayi bhukte tu tṛptās te bhaviṣyanti sabāndhavāḥ', null, 7018026),
('ramayana-7-18-27', 27, 'Uttara Kanda, Sarga 18, Verse 27', 'वरुणस्त्वब्रवीद्धंसं गङ्गातोयविचारिणम्।
श्रूयतां प्रीतिसंयुक्तं वचः पत्ररथेश्वर॥', 'varuṇas tv abravīd dhaṃsaṃ gaṅgātoyavicāriṇam
śrūyatāṃ prītisaṃyuktaṃ vacaḥ patraratheśvara', null, 7018027),
('ramayana-7-18-28', 28, 'Uttara Kanda, Sarga 18, Verse 28', 'वर्णो मनोहरः सौम्यश्चन्द्रमण्डलसंनिभः।
भविष्यति तवोदग्रः शुक्लफेनसमप्रभः॥', 'varṇo manoharaḥ saumyaś candramaṇḍalasaṃnibhaḥ
bhaviṣyati tavodagraḥ śuklaphenasamaprabhaḥ', null, 7018028),
('ramayana-7-18-29', 29, 'Uttara Kanda, Sarga 18, Verse 29', 'मच्छरीरं समासाद्य कान्तो नित्यं भविष्यसि।
प्राप्स्यसे चातुलां प्रीतिमेतन्मे प्रीतिलक्षणम्॥', 'maccharīraṃ samāsādya kānto nityaṃ bhaviṣyasi
prāpsyase cātulāṃ prītim etan me prītilakṣaṇam', null, 7018029),
('ramayana-7-18-30', 30, 'Uttara Kanda, Sarga 18, Verse 30', 'हंसानां हि पुरा राम न वर्णः सर्वपाण्डुरः।
पक्षा नीलाग्रसंवीताः क्रोडाः शष्पाग्रनिर्मलाः॥', 'haṃsānāṃ hi purā rāma na varṇaḥ sarvapāṇḍuraḥ
pakṣā nīlāgrasaṃvītāḥ kroḍāḥ śaṣpāgranirmalāḥ', null, 7018030),
('ramayana-7-18-31', 31, 'Uttara Kanda, Sarga 18, Verse 31', 'अथाब्रवीद्वैश्रवणः कृकलासं गिरौ स्थितम्।
हैरण्यं संप्रयच्छामि वर्णं प्रीतिस्तवाप्यहम्॥', 'athābravīd vaiśravaṇaḥ kṛkalāsaṃ girau sthitam
hairaṇyaṃ saṃprayacchāmi varṇaṃ prītis tavāpy aham', null, 7018031),
('ramayana-7-18-32', 32, 'Uttara Kanda, Sarga 18, Verse 32', 'सद्रव्यं च शिरो नित्यं भविष्यति तवाक्षयम्।
एष काञ्चनको वर्णो मत्प्रीत्या ते भविष्यति॥', 'sadravyaṃ ca śiro nityaṃ bhaviṣyati tavākṣayam
eṣa kāñcanako varṇo matprītyā te bhaviṣyati', null, 7018032),
('ramayana-7-18-33', 33, 'Uttara Kanda, Sarga 18, Verse 33', 'एवं दत्त्वा वरांस्तेभ्यस्तस्मिन्यज्ञोत्सवे सुराः।
निवृत्ते सह राज्ञा वै पुनः स्वभवनं गताः॥', 'evaṃ dattvā varāṃs tebhyas tasmin yajñotsave surāḥ
nivṛtte saha rājñā vai punaḥ svabhavanaṃ gatāḥ', null, 7018033)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 19 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-19-1', 1, 'Uttara Kanda, Sarga 19, Verse 1', 'अथ जित्वा मरुत्तं स प्रययौ राक्षसाधिपः।
नगराणि नरेन्द्राणां युद्धकाङ्क्षी दशाननः॥', 'atha jitvā maruttaṃ sa prayayau rākṣasādhipaḥ
nagarāṇi narendrāṇāṃ yuddhakāṅkṣī daśānanaḥ', null, 7019001),
('ramayana-7-19-2', 2, 'Uttara Kanda, Sarga 19, Verse 2', 'स समासाद्य राजेन्द्रान्महेन्द्रवरुणोपमान्।
अब्रवीद्राक्षसेन्द्रस्तु युद्धं मे दीयतामिति॥', 'sa samāsādya rājendrān mahendravaruṇopamān
abravīd rākṣasendras tu yuddhaṃ me dīyatām iti', null, 7019002),
('ramayana-7-19-3', 3, 'Uttara Kanda, Sarga 19, Verse 3', 'निर्जिताः स्मेति वा ब्रूत एषो हि मम निश्चयः।
अन्यथा कुर्वतामेवं मोक्षो वो नोपपद्यते॥', 'nirjitāḥ smeti vā brūta eṣo hi mama niścayaḥ
anyathā kurvatām evaṃ mokṣo vo nopapadyate', null, 7019003),
('ramayana-7-19-4', 4, 'Uttara Kanda, Sarga 19, Verse 4', 'ततस्तु बहवः प्राज्ञाः पार्थिवा धर्मणिश्चयाः।
निर्जिताः स्मेत्यभाषन्त ज्ञात्वा वरबलं रिपोः॥', 'tatas tu bahavaḥ prājñāḥ pārthivā dharmaṇiścayāḥ
nirjitāḥ smety abhāṣanta jñātvā varabalaṃ ripoḥ', null, 7019004),
('ramayana-7-19-5', 5, 'Uttara Kanda, Sarga 19, Verse 5', 'दुष्यन्तः सुरथो गाधिर्गयो राजा पुरूरवाः।
एते सर्वेऽब्रुवंस्तात निर्जिताः स्मेति पार्थिवाः॥', 'duṣyantaḥ suratho gādhir gayo rājā purūravāḥ
ete sarve ''bruvaṃs tāta nirjitāḥ smeti pārthivāḥ', null, 7019005),
('ramayana-7-19-6', 6, 'Uttara Kanda, Sarga 19, Verse 6', 'अथायोध्यां समासाद्य रावणो राक्षसाधिपः।
सुगुप्तामनरण्येन शक्रेणेवामरावतीम्॥', 'athāyodhyāṃ samāsādya rāvaṇo rākṣasādhipaḥ
suguptām anaraṇyena śakreṇevāmarāvatīm', null, 7019006),
('ramayana-7-19-7', 7, 'Uttara Kanda, Sarga 19, Verse 7', 'प्राह राजानमासाद्य युद्धं मे संप्रदीयताम्।
निर्जितोऽस्मीति वा ब्रूहि ममैतदिह शासनम्॥', 'prāha rājānam āsādya yuddhaṃ me saṃpradīyatām
nirjito ''smīti vā brūhi mamaitad iha śāsanam', null, 7019007),
('ramayana-7-19-8', 8, 'Uttara Kanda, Sarga 19, Verse 8', 'अनरण्यः सुसंक्रुद्धो राक्षसेन्द्रमथाब्रवीत्।
दीयते द्वन्द्वयुद्धं ते राक्षसाधिपते मया॥', 'anaraṇyaḥ susaṃkruddho rākṣasendram athābravīt
dīyate dvandvayuddhaṃ te rākṣasādhipate mayā', null, 7019008),
('ramayana-7-19-9', 9, 'Uttara Kanda, Sarga 19, Verse 9', 'अथ पूर्वं श्रुतार्थेन सज्जितं सुमहद्धि यत्।
निष्क्रामत्तन्नरेन्द्रस्य बलं रक्षोवधोद्यतम्॥', 'atha pūrvaṃ śrutārthena sajjitaṃ sumahad dhi yat
niṣkrāmat tan narendrasya balaṃ rakṣovadhodyatam', null, 7019009),
('ramayana-7-19-10', 10, 'Uttara Kanda, Sarga 19, Verse 10', 'नागानां बहुसाहस्रं वाजिनामयुतं तथा।
महीं संछाद्य निष्क्रान्तं सपदातिरथं क्षणात्॥', 'nāgānāṃ bahusāhasraṃ vājinām ayutaṃ tathā
mahīṃ saṃchādya niṣkrāntaṃ sapadātirathaṃ kṣaṇāt', null, 7019010),
('ramayana-7-19-11', 11, 'Uttara Kanda, Sarga 19, Verse 11', 'तद्रावणबलं प्राप्य बलं तस्य महीपतेः।
प्राणश्यत तदा राजन्हव्यं हुतमिवानले॥', 'tad rāvaṇabalaṃ prāpya balaṃ tasya mahīpateḥ
prāṇaśyata tadā rājan havyaṃ hutam ivānale', null, 7019011),
('ramayana-7-19-12', 12, 'Uttara Kanda, Sarga 19, Verse 12', 'सोऽपश्यत नरेन्द्रस्तु नश्यमानं महद्बलम्।
महार्णवं समासाद्य यथा पञ्चापगा जलम्॥', 'so ''paśyata narendras tu naśyamānaṃ mahad balam
mahārṇavaṃ samāsādya yathā pañcāpagā jalam', null, 7019012),
('ramayana-7-19-13', 13, 'Uttara Kanda, Sarga 19, Verse 13', 'ततः शक्रधनुःप्रख्यं धनुर्विस्फारयन्स्वयम्।
आसदाद नरेन्द्रास्तं रावणं क्रोधमूर्छितः॥', 'tataḥ śakradhanuḥprakhyaṃ dhanur visphārayan svayam
āsadāda narendrās taṃ rāvaṇaṃ krodhamūrchitaḥ', null, 7019013),
('ramayana-7-19-14', 14, 'Uttara Kanda, Sarga 19, Verse 14', 'ततो बाणशतान्यष्टौ पातयामास मूर्धनि।
तस्य राक्षसराजस्य इक्ष्वाकुकुलनन्दनः॥', 'tato bāṇaśatāny aṣṭau pātayām āsa mūrdhani
tasya rākṣasarājasya ikṣvākukulanandanaḥ', null, 7019014),
('ramayana-7-19-15', 15, 'Uttara Kanda, Sarga 19, Verse 15', 'तस्य बाणाः पतन्तस्ते चक्रिरे न क्षतं क्व चित्।
वारिधारा इवाभ्रेभ्यः पतन्त्यो नगमूर्धनि॥', 'tasya bāṇāḥ patantas te cakrire na kṣataṃ kva cit
vāridhārā ivābhrebhyaḥ patantyo nagamūrdhani', null, 7019015),
('ramayana-7-19-16', 16, 'Uttara Kanda, Sarga 19, Verse 16', 'ततो राक्षसराजेन क्रुद्धेन नृपतिस्तदा।
तलेन भिहतो मूर्ध्नि स रथान्निपपात ह॥', 'tato rākṣasarājena kruddhena nṛpatis tadā
talena bhihato mūrdhni sa rathān nipapāta ha', null, 7019016),
('ramayana-7-19-17', 17, 'Uttara Kanda, Sarga 19, Verse 17', 'स राजा पतितो भूमौ विह्वलाङ्गः प्रवेपितः।
वज्रदग्ध इवारण्ये सालो निपतितो महान्॥', 'sa rājā patito bhūmau vihvalāṅgaḥ pravepitaḥ
vajradagdha ivāraṇye sālo nipatito mahān', null, 7019017),
('ramayana-7-19-18', 18, 'Uttara Kanda, Sarga 19, Verse 18', 'तं प्रहस्याब्रवीद्रक्ष इक्ष्वाकुं पृथिवीपतिम्।
किमिदानीं त्वया प्राप्तं फलं मां प्रति युध्यता॥', 'taṃ prahasyābravīd rakṣa ikṣvākuṃ pṛthivīpatim
kim idānīṃ tvayā prāptaṃ phalaṃ māṃ prati yudhyatā', null, 7019018),
('ramayana-7-19-19', 19, 'Uttara Kanda, Sarga 19, Verse 19', 'त्रैलोक्ये नास्ति यो द्वन्द्वं मम दद्यान्नराधिप।
शङ्के प्रमत्तो भोगेषु न शृणोषि बलं मम॥', 'trailokye nāsti yo dvandvaṃ mama dadyān narādhipa
śaṅke pramatto bhogeṣu na śṛṇoṣi balaṃ mama', null, 7019019),
('ramayana-7-19-20', 20, 'Uttara Kanda, Sarga 19, Verse 20', 'तस्यैवं ब्रुवतो राजा मन्दासुर्वाक्यमब्रवीत्।
किं शक्यमिह कर्तुं वै यत्कालो दुरतिक्रमः॥', 'tasyaivaṃ bruvato rājā mandāsur vākyam abravīt
kiṃ śakyam iha kartuṃ vai yat kālo duratikramaḥ', null, 7019020),
('ramayana-7-19-21', 21, 'Uttara Kanda, Sarga 19, Verse 21', 'न ह्यहं निर्जितो रक्षस्त्वया चात्मप्रशंसिना।
कालेनेह विपन्नोऽहं हेतुभूतस्तु मे भवान्॥', 'na hy ahaṃ nirjito rakṣas tvayā cātmapraśaṃsinā
kāleneha vipanno ''haṃ hetubhūtas tu me bhavān', null, 7019021),
('ramayana-7-19-22', 22, 'Uttara Kanda, Sarga 19, Verse 22', 'किं त्विदानीं मया शक्यं कर्तुं प्राणपरिक्षये।
इक्ष्वाकुपरिभावित्वाद्वचो वक्ष्यामि राक्षस॥', 'kiṃ tv idānīṃ mayā śakyaṃ kartuṃ prāṇaparikṣaye
ikṣvākuparibhāvitvād vaco vakṣyāmi rākṣasa', null, 7019022),
('ramayana-7-19-23', 23, 'Uttara Kanda, Sarga 19, Verse 23', 'यदि दत्तं यदि हुतं यदि मे सुकृतं तपः।
यदि गुप्ताः प्रजाः सम्यक्तथा सत्यं वचोऽस्तु मे॥', 'yadi dattaṃ yadi hutaṃ yadi me sukṛtaṃ tapaḥ
yadi guptāḥ prajāḥ samyak tathā satyaṃ vaco ''stu me', null, 7019023),
('ramayana-7-19-24', 24, 'Uttara Kanda, Sarga 19, Verse 24', 'उत्पत्स्यते कुले ह्यस्मिन्निक्ष्वाकूणां महात्मनाम्।
राजा परमतेजस्वी यस्ते प्राणान्हरिष्यति॥', 'utpatsyate kule hy asminn ikṣvākūṇāṃ mahātmanām
rājā paramatejasvī yas te prāṇān hariṣyati', null, 7019024),
('ramayana-7-19-25', 25, 'Uttara Kanda, Sarga 19, Verse 25', 'ततो जलधरोदग्रस्ताडितो देवदुन्दुभिः।
तस्मिन्नुदाहृते शापे पुष्पवृष्टिश्च खाच्च्युता॥', 'tato jaladharodagras tāḍito devadundubhiḥ
tasminn udāhṛte śāpe puṣpavṛṣṭiś ca khāc cyutā', null, 7019025),
('ramayana-7-19-26', 26, 'Uttara Kanda, Sarga 19, Verse 26', 'ततः स राजा राजेन्द्र गतः स्थानं त्रिविष्टपम्।
स्वर्गते च नृपे राम राक्षसः स न्यवर्तत॥', 'tataḥ sa rājā rājendra gataḥ sthānaṃ triviṣṭapam
svargate ca nṛpe rāma rākṣasaḥ sa nyavartata', null, 7019026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 20 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-20-1', 1, 'Uttara Kanda, Sarga 20, Verse 1', 'ततो वित्रासयन्मर्त्यान्पृथिव्यां राक्षसाधिपः।
आससाद घने तस्मिन्नारदं मुनिसत्तमम्॥', 'tato vitrāsayan martyān pṛthivyāṃ rākṣasādhipaḥ
āsasāda ghane tasmin nāradaṃ munisattamam', null, 7020001),
('ramayana-7-20-2', 2, 'Uttara Kanda, Sarga 20, Verse 2', 'नारदस्तु महातेजा देवर्षिरमितप्रभः।
अब्रवीन्मेघपृष्ठस्थो रावणं पुष्पके स्थितम्॥', 'nāradas tu mahātejā devarṣir amitaprabhaḥ
abravīn meghapṛṣṭhastho rāvaṇaṃ puṣpake sthitam', null, 7020002),
('ramayana-7-20-3', 3, 'Uttara Kanda, Sarga 20, Verse 3', 'राक्षसाधिपते सौम्य तिष्ठ विश्रवसः सुत।
प्रीतोऽस्म्यभिजनोपेत विक्रमैरूर्जितैस्तव॥', 'rākṣasādhipate saumya tiṣṭha viśravasaḥ suta
prīto ''smy abhijanopeta vikramair ūrjitais tava', null, 7020003),
('ramayana-7-20-4', 4, 'Uttara Kanda, Sarga 20, Verse 4', 'विष्णुना दैत्यघातैश्च तार्क्ष्यस्योरगधर्षणैः।
त्वया समरमर्दैश्च भृशं हि परितोषितः॥', 'viṣṇunā daityaghātaiś ca tārkṣyasyoragadharṣaṇaiḥ
tvayā samaramardaiś ca bhṛśaṃ hi paritoṣitaḥ', null, 7020004),
('ramayana-7-20-5', 5, 'Uttara Kanda, Sarga 20, Verse 5', 'किं चिद्वक्ष्यामि तावत्ते श्रोतव्यं श्रोष्यसे यदि।
श्रुत्वा चानन्तरं कार्यं त्वया राक्षसपुंगव॥', 'kiṃ cid vakṣyāmi tāvat te śrotavyaṃ śroṣyase yadi
śrutvā cānantaraṃ kāryaṃ tvayā rākṣasapuṃgava', null, 7020005),
('ramayana-7-20-6', 6, 'Uttara Kanda, Sarga 20, Verse 6', 'किमयं वध्यते लोकस्त्वयावध्येन दैवतैः।
हत एव ह्ययं लोको यदा मृत्युवशं गतः॥', 'kim ayaṃ vadhyate lokas tvayāvadhyena daivataiḥ
hata eva hy ayaṃ loko yadā mṛtyuvaśaṃ gataḥ', null, 7020006),
('ramayana-7-20-7', 7, 'Uttara Kanda, Sarga 20, Verse 7', 'पश्य तावन्महाबाहो राक्षसेश्वरमानुषम्।
लोकमेनं विचित्रार्थं यस्य न ज्ञायते गतिः॥', 'paśya tāvan mahābāho rākṣaseśvaramānuṣam
lokam enaṃ vicitrārthaṃ yasya na jñāyate gatiḥ', null, 7020007),
('ramayana-7-20-8', 8, 'Uttara Kanda, Sarga 20, Verse 8', 'क्व चिद्वादित्रनृत्तानि सेव्यन्ते मुदितैर्जनैः।
रुद्यते चापरैरार्तैर्धाराश्रुनयनाननैः॥', 'kva cid vāditranṛttāni sevyante muditair janaiḥ
rudyate cāparair ārtair dhārāśrunayanānanaiḥ', null, 7020008),
('ramayana-7-20-9', 9, 'Uttara Kanda, Sarga 20, Verse 9', 'माता पितृसुतस्नेहैर्भार्या बन्धुमनोरमैः।
मोहेनायं जनो ध्वस्तः क्लेशं स्वं नावबुध्यते॥', 'mātā pitṛsutasnehair bhāryā bandhumanoramaiḥ
mohenāyaṃ jano dhvastaḥ kleśaṃ svaṃ nāvabudhyate', null, 7020009),
('ramayana-7-20-10', 10, 'Uttara Kanda, Sarga 20, Verse 10', 'तत्किमेवं परिक्लिश्य लोकं मोहनिराकृतम्।
जित एव त्वया सौम्य मर्त्यलोको न संशयः॥', 'tat kim evaṃ parikliśya lokaṃ mohanirākṛtam
jita eva tvayā saumya martyaloko na saṃśayaḥ', null, 7020010),
('ramayana-7-20-11', 11, 'Uttara Kanda, Sarga 20, Verse 11', 'एवमुक्तस्तु लङ्केशो दीप्यमान इवौजसा।
अब्रवीन्नारदं तत्र संप्रहस्याभिवाद्य च॥', 'evam uktas tu laṅkeśo dīpyamāna ivaujasā
abravīn nāradaṃ tatra saṃprahasyābhivādya ca', null, 7020011),
('ramayana-7-20-12', 12, 'Uttara Kanda, Sarga 20, Verse 12', 'महर्षे देवगन्धर्वविहार समरप्रिय।
अहं खलूद्यतो गन्तुं विजयार्थी रसातलम्॥', 'maharṣe devagandharvavihāra samarapriya
ahaṃ khalūdyato gantuṃ vijayārthī rasātalam', null, 7020012),
('ramayana-7-20-13', 13, 'Uttara Kanda, Sarga 20, Verse 13', 'ततो लोकत्रयं जित्वा स्थाप्य नागान्सुरान्वशे।
समुद्रममृतार्थं वै मथिष्यामि रसालयम्॥', 'tato lokatrayaṃ jitvā sthāpya nāgān surān vaśe
samudram amṛtārthaṃ vai mathiṣyāmi rasālayam', null, 7020013),
('ramayana-7-20-14', 14, 'Uttara Kanda, Sarga 20, Verse 14', 'अथाब्रवीद्दशग्रीवं नारदो भगवानृषिः।
क्व खल्विदानीं मार्गेण त्वयानेन गमिष्यते॥', 'athābravīd daśagrīvaṃ nārado bhagavān ṛṣiḥ
kva khalv idānīṃ mārgeṇa tvayānena gamiṣyate', null, 7020014),
('ramayana-7-20-15', 15, 'Uttara Kanda, Sarga 20, Verse 15', 'अयं खलु सुदुर्गम्यः पितृराज्ञः पुरं प्रति।
मार्गो गच्छति दुर्धर्षो यमस्यामित्रकर्शन॥', 'ayaṃ khalu sudurgamyaḥ pitṛrājñaḥ puraṃ prati
mārgo gacchati durdharṣo yamasyāmitrakarśana', null, 7020015),
('ramayana-7-20-16', 16, 'Uttara Kanda, Sarga 20, Verse 16', 'स तु शारदमेघाभं मुक्त्वा हासं दशाननः।
उवाच कृतमित्येव वचनं चेदमब्रवीत्॥', 'sa tu śāradameghābhaṃ muktvā hāsaṃ daśānanaḥ
uvāca kṛtam ity eva vacanaṃ cedam abravīt', null, 7020016),
('ramayana-7-20-17', 17, 'Uttara Kanda, Sarga 20, Verse 17', 'तस्मादेष महाब्रह्मन्वैवस्वतवधोद्यतः।
गच्छामि दक्षिणामाशां यत्र सूर्यात्मजो नृपः॥', 'tasmād eṣa mahābrahman vaivasvatavadhodyataḥ
gacchāmi dakṣiṇām āśāṃ yatra sūryātmajo nṛpaḥ', null, 7020017),
('ramayana-7-20-18', 18, 'Uttara Kanda, Sarga 20, Verse 18', 'मया हि भगवन्क्रोधात्प्रतिज्ञातं रणार्थिना।
अवजेष्यामि चतुरो लोकपालानिति प्रभो॥', 'mayā hi bhagavan krodhāt pratijñātaṃ raṇārthinā
avajeṣyāmi caturo lokapālān iti prabho', null, 7020018),
('ramayana-7-20-19', 19, 'Uttara Kanda, Sarga 20, Verse 19', 'तेनैष प्रस्थितोऽहं वै पितृराजपुरं प्रति।
प्राणिसंक्लेशकर्तारं योजयिष्यामि मृत्युना॥', 'tenaiṣa prasthito ''haṃ vai pitṛrājapuraṃ prati
prāṇisaṃkleśakartāraṃ yojayiṣyāmi mṛtyunā', null, 7020019),
('ramayana-7-20-20', 20, 'Uttara Kanda, Sarga 20, Verse 20', 'एवमुक्त्वा दशग्रीवो मुनिं तमभिवाद्य च।
प्रययौ दक्षिणामाशां प्रहृष्टैः सह मन्त्रिभिः॥', 'evam uktvā daśagrīvo muniṃ tam abhivādya ca
prayayau dakṣiṇām āśāṃ prahṛṣṭaiḥ saha mantribhiḥ', null, 7020020),
('ramayana-7-20-21', 21, 'Uttara Kanda, Sarga 20, Verse 21', 'नारदस्तु महातेजा मुहूर्तं ध्यानमास्थितः।
चिन्तयामास विप्रेन्द्रो विधूम इव पावकः॥', 'nāradas tu mahātejā muhūrtaṃ dhyānam āsthitaḥ
cintayām āsa viprendro vidhūma iva pāvakaḥ', null, 7020021),
('ramayana-7-20-22', 22, 'Uttara Kanda, Sarga 20, Verse 22', 'येन लोकास्त्रयः सेन्द्राः क्लिश्यन्ते सचराचराः।
क्षीणे चायुषि धर्मे च स कालो हिंस्यते कथम्॥', 'yena lokās trayaḥ sendrāḥ kliśyante sacarācarāḥ
kṣīṇe cāyuṣi dharme ca sa kālo hiṃsyate katham', null, 7020022),
('ramayana-7-20-23', 23, 'Uttara Kanda, Sarga 20, Verse 23', 'यस्य नित्यं त्रयो लोका विद्रवन्ति भयार्दिताः।
तं कथं राक्षसेन्द्रोऽसौ स्वयमेवाभिगच्छति॥', 'yasya nityaṃ trayo lokā vidravanti bhayārditāḥ
taṃ kathaṃ rākṣasendro ''sau svayam evābhigacchati', null, 7020023),
('ramayana-7-20-24', 24, 'Uttara Kanda, Sarga 20, Verse 24', 'यो विधाता च धाता च सुकृते दुष्कृते यथा।
त्रैलोक्यं विजितं येन तं कथं नु विजेष्यति॥', 'yo vidhātā ca dhātā ca sukṛte duṣkṛte yathā
trailokyaṃ vijitaṃ yena taṃ kathaṃ nu vijeṣyati', null, 7020024),
('ramayana-7-20-25', 25, 'Uttara Kanda, Sarga 20, Verse 25', 'अपरं किं नु कृत्वैवं विधानं संविधास्यति।
कौतूहलसमुत्पन्नो यास्यामि यमसादनम्॥', 'aparaṃ kiṃ nu kṛtvaivaṃ vidhānaṃ saṃvidhāsyati
kautūhalasamutpanno yāsyāmi yamasādanam', null, 7020025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 21 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-21-1', 1, 'Uttara Kanda, Sarga 21, Verse 1', 'एवं संचिन्त्य विप्रेन्द्रो जगाम लघुविक्रमः।
आख्यातुं तद्यथावृत्तं यमस्य सदनं प्रति॥', 'evaṃ saṃcintya viprendro jagāma laghuvikramaḥ
ākhyātuṃ tad yathāvṛttaṃ yamasya sadanaṃ prati', null, 7021001),
('ramayana-7-21-2', 2, 'Uttara Kanda, Sarga 21, Verse 2', 'अपश्यत्स यमं तत्र देवमग्निपुरस्कृतम्।
विधानमुपतिष्ठन्तं प्राणिनो यस्य यादृशम्॥', 'apaśyat sa yamaṃ tatra devam agnipuraskṛtam
vidhānam upatiṣṭhantaṃ prāṇino yasya yādṛśam', null, 7021002),
('ramayana-7-21-3', 3, 'Uttara Kanda, Sarga 21, Verse 3', 'स तु दृष्ट्वा यमः प्राप्तं महर्षिं तत्र नारदम्।
अब्रवीत्सुखमासीनमर्घ्यमावेद्य धर्मतः॥', 'sa tu dṛṣṭvā yamaḥ prāptaṃ maharṣiṃ tatra nāradam
abravīt sukham āsīnam arghyam āvedya dharmataḥ', null, 7021003),
('ramayana-7-21-4', 4, 'Uttara Kanda, Sarga 21, Verse 4', 'कच्चित्क्षेमं नु देवर्षे कच्चिद्धर्मो न नश्यति।
किमागमनकृत्यं ते देवगन्धर्वसेवित॥', 'kaccit kṣemaṃ nu devarṣe kaccid dharmo na naśyati
kim āgamanakṛtyaṃ te devagandharvasevita', null, 7021004),
('ramayana-7-21-5', 5, 'Uttara Kanda, Sarga 21, Verse 5', 'अब्रवीत्तु तदा वाक्यं नारदो भगवानृषिः।
श्रूयतामभिधास्यामि विधानं च विधीयताम्॥', 'abravīt tu tadā vākyaṃ nārado bhagavān ṛṣiḥ
śrūyatām abhidhāsyāmi vidhānaṃ ca vidhīyatām', null, 7021005),
('ramayana-7-21-6', 6, 'Uttara Kanda, Sarga 21, Verse 6', 'एष नाम्ना दशग्रीवः पितृराज निशाचरः।
उपयाति वशं नेतुं विक्रमैस्त्वां सुदुर्जयम्॥', 'eṣa nāmnā daśagrīvaḥ pitṛrāja niśācaraḥ
upayāti vaśaṃ netuṃ vikramais tvāṃ sudurjayam', null, 7021006),
('ramayana-7-21-7', 7, 'Uttara Kanda, Sarga 21, Verse 7', 'एतेन कारणेनाहं त्वरितोऽस्म्यागतः प्रभो।
दण्डप्रहरणस्याद्य तव किं नु करिष्यति॥', 'etena kāraṇenāhaṃ tvarito ''smy āgataḥ prabho
daṇḍapraharaṇasyādya tava kiṃ nu kariṣyati', null, 7021007),
('ramayana-7-21-8', 8, 'Uttara Kanda, Sarga 21, Verse 8', 'एतस्मिन्नन्तरे दूरादंशुमन्तमिवोदितम्।
ददृशे दिव्यमायान्तं विमानं तस्य रक्षसः॥', 'etasminn antare dūrād aṃśumantam ivoditam
dadṛśe divyam āyāntaṃ vimānaṃ tasya rakṣasaḥ', null, 7021008),
('ramayana-7-21-9', 9, 'Uttara Kanda, Sarga 21, Verse 9', 'तं देशं प्रभया तस्य पुष्पकस्य महाबलः।
कृत्वा वितिमिरं सर्वं समीपं समवर्तत॥', 'taṃ deśaṃ prabhayā tasya puṣpakasya mahābalaḥ
kṛtvā vitimiraṃ sarvaṃ samīpaṃ samavartata', null, 7021009),
('ramayana-7-21-10', 10, 'Uttara Kanda, Sarga 21, Verse 10', 'स त्वपश्यन्महाबाहुर्दशग्रीवस्ततस्ततः।
प्राणिनः सुकृतं कर्म भुञ्जानांश्चैव दुष्कृतम्॥', 'sa tv apaśyan mahābāhur daśagrīvas tatas tataḥ
prāṇinaḥ sukṛtaṃ karma bhuñjānāṃś caiva duṣkṛtam', null, 7021010),
('ramayana-7-21-11', 11, 'Uttara Kanda, Sarga 21, Verse 11', 'ततस्तान्वध्यमानांस्तु कर्मभिर्दुष्कृतैः स्वकैः।
रावणो मोचयामास विक्रमेण बलाद्बली॥', 'tatas tān vadhyamānāṃs tu karmabhir duṣkṛtaiḥ svakaiḥ
rāvaṇo mocayām āsa vikrameṇa balād balī', null, 7021011),
('ramayana-7-21-12', 12, 'Uttara Kanda, Sarga 21, Verse 12', 'प्रेतेषु मुच्यमानेषु राक्षसेन बलीयसा।
प्रेतगोपाः सुसंरब्धा राक्षसेन्द्रमभिद्रवन्॥', 'preteṣu mucyamāneṣu rākṣasena balīyasā
pretagopāḥ susaṃrabdhā rākṣasendram abhidravan', null, 7021012),
('ramayana-7-21-13', 13, 'Uttara Kanda, Sarga 21, Verse 13', 'ते प्रासैः परिघैः शूलैर्मुद्गरैः शक्तितोमरैः।
पुष्पकं समवर्षन्त शूराः शतसहस्रशः॥', 'te prāsaiḥ parighaiḥ śūlair mudgaraiḥ śaktitomaraiḥ
puṣpakaṃ samavarṣanta śūrāḥ śatasahasraśaḥ', null, 7021013),
('ramayana-7-21-14', 14, 'Uttara Kanda, Sarga 21, Verse 14', 'तस्यासनानि प्रासादान्वेदिकास्तरणानि च।
पुष्पकस्य बभञ्जुस्ते शीघ्रं मधुकरा इव॥', 'tasyāsanāni prāsādān vedikāstaraṇāni ca
puṣpakasya babhañjus te śīghraṃ madhukarā iva', null, 7021014),
('ramayana-7-21-15', 15, 'Uttara Kanda, Sarga 21, Verse 15', 'देवनिष्ठानभूतं तद्विमानं पुष्पकं मृधे।
भज्यमानं तथैवासीदक्षयं ब्रह्मतेजसा॥', 'devaniṣṭhānabhūtaṃ tad vimānaṃ puṣpakaṃ mṛdhe
bhajyamānaṃ tathaivāsīd akṣayaṃ brahmatejasā', null, 7021015),
('ramayana-7-21-16', 16, 'Uttara Kanda, Sarga 21, Verse 16', 'ततस्ते रावणामात्या यथाकामं यथाबलम्।
अयुध्यन्त महावीर्याः स च राजा दशाननः॥', 'tatas te rāvaṇāmātyā yathākāmaṃ yathābalam
ayudhyanta mahāvīryāḥ sa ca rājā daśānanaḥ', null, 7021016),
('ramayana-7-21-17', 17, 'Uttara Kanda, Sarga 21, Verse 17', 'ते तु शोणितदिग्धाङ्गाः सर्वशस्त्रसमाहताः।
अमात्या राक्षसेन्द्रस्य चक्रुरायोधनं महत्॥', 'te tu śoṇitadigdhāṅgāḥ sarvaśastrasamāhatāḥ
amātyā rākṣasendrasya cakrur āyodhanaṃ mahat', null, 7021017),
('ramayana-7-21-18', 18, 'Uttara Kanda, Sarga 21, Verse 18', 'अन्योन्यं च महाभागा जघ्नुः प्रहरणैर्युधि।
यमस्य च महत्सैन्यं राक्षसस्य च मन्त्रिणः॥', 'anyonyaṃ ca mahābhāgā jaghnuḥ praharaṇair yudhi
yamasya ca mahat sainyaṃ rākṣasasya ca mantriṇaḥ', null, 7021018),
('ramayana-7-21-19', 19, 'Uttara Kanda, Sarga 21, Verse 19', 'अमात्यांस्तांस्तु संत्यज्य राक्षसस्य महौजसः।
तमेव समधावन्त शूलवर्षैर्दशाननम्॥', 'amātyāṃs tāṃs tu saṃtyajya rākṣasasya mahaujasaḥ
tam eva samadhāvanta śūlavarṣair daśānanam', null, 7021019),
('ramayana-7-21-20', 20, 'Uttara Kanda, Sarga 21, Verse 20', 'ततः शोणितदिग्धाङ्गः प्रहारैर्जर्जरीकृतः।
विमाने राक्षसश्रेष्ठः फुल्लाशोक इवाबभौ॥', 'tataḥ śoṇitadigdhāṅgaḥ prahārair jarjarīkṛtaḥ
vimāne rākṣasaśreṣṭhaḥ phullāśoka ivābabhau', null, 7021020),
('ramayana-7-21-21', 21, 'Uttara Kanda, Sarga 21, Verse 21', 'स शूलानि गदाः प्रासाञ्शक्तितोमरसायकान्।
मुसलानि शिलावृक्षान्मुमोचास्त्रबलाद्बली॥', 'sa śūlāni gadāḥ prāsāñ śaktitomarasāyakān
musalāni śilāvṛkṣān mumocāstrabalād balī', null, 7021021),
('ramayana-7-21-22', 22, 'Uttara Kanda, Sarga 21, Verse 22', 'तांस्तु सर्वान्समाक्षिप्य तदस्त्रमपहत्य च।
जघ्नुस्ते राक्षसं घोरमेकं शतसहस्रकः॥', 'tāṃs tu sarvān samākṣipya tad astram apahatya ca
jaghnus te rākṣasaṃ ghoram ekaṃ śatasahasrakaḥ', null, 7021022),
('ramayana-7-21-23', 23, 'Uttara Kanda, Sarga 21, Verse 23', 'परिवार्य च तं सर्वे शैलं मेघोत्करा इव।
भिन्दिपालैश्च शूलैश्च निरुच्छ्वासमकारयन्॥', 'parivārya ca taṃ sarve śailaṃ meghotkarā iva
bhindipālaiś ca śūlaiś ca nirucchvāsam akārayan', null, 7021023),
('ramayana-7-21-24', 24, 'Uttara Kanda, Sarga 21, Verse 24', 'विमुक्तकवचः क्रुद्धो सिक्तः शोणितविस्रवैः।
स पुष्पकं परित्यज्य पृथिव्यामवतिष्ठत॥', 'vimuktakavacaḥ kruddho siktaḥ śoṇitavisravaiḥ
sa puṣpakaṃ parityajya pṛthivyām avatiṣṭhata', null, 7021024),
('ramayana-7-21-25', 25, 'Uttara Kanda, Sarga 21, Verse 25', 'ततः स कार्मुकी बाणी पृथिव्यां राक्षसाधिपः।
लब्धसंज्ञो मुहूर्तेन क्रुद्धस्तस्थौ यथान्तकः॥', 'tataḥ sa kārmukī bāṇī pṛthivyāṃ rākṣasādhipaḥ
labdhasaṃjño muhūrtena kruddhas tasthau yathāntakaḥ', null, 7021025),
('ramayana-7-21-26', 26, 'Uttara Kanda, Sarga 21, Verse 26', 'ततः पाशुपतं दिव्यमस्त्रं संधाय कार्मुके।
तिष्ठ तिष्ठेति तानुक्त्वा तच्चापं व्यपकर्षत॥', 'tataḥ pāśupataṃ divyam astraṃ saṃdhāya kārmuke
tiṣṭha tiṣṭheti tān uktvā tac cāpaṃ vyapakarṣata', null, 7021026),
('ramayana-7-21-27', 27, 'Uttara Kanda, Sarga 21, Verse 27', 'ज्वालामाली स तु शरः क्रव्यादानुगतो रणे।
मुक्तो गुल्मान्द्रुमांश्चैव भस्मकृत्वा प्रधावति॥', 'jvālāmālī sa tu śaraḥ kravyādānugato raṇe
mukto gulmān drumāṃś caiva bhasmakṛtvā pradhāvati', null, 7021027),
('ramayana-7-21-28', 28, 'Uttara Kanda, Sarga 21, Verse 28', 'ते तस्य तेजसा दग्धाः सैन्या वैवस्वतस्य तु।
रणे तस्मिन्निपतिता दावदग्धा नगा इव॥', 'te tasya tejasā dagdhāḥ sainyā vaivasvatasya tu
raṇe tasmin nipatitā dāvadagdhā nagā iva', null, 7021028),
('ramayana-7-21-29', 29, 'Uttara Kanda, Sarga 21, Verse 29', 'ततः स सचिवैः सार्धं राक्षसो भीमविक्रमः।
ननाद सुमहानादं कम्पयन्निव मेदिनीम्॥', 'tataḥ sa sacivaiḥ sārdhaṃ rākṣaso bhīmavikramaḥ
nanāda sumahānādaṃ kampayann iva medinīm', null, 7021029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 22 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-22-1', 1, 'Uttara Kanda, Sarga 22, Verse 1', 'स तु तस्य महानादं श्रुत्वा वैवस्वतो यमः।
शत्रुं विजयिनं मेने स्वबलस्य च संक्षयम्॥', 'sa tu tasya mahānādaṃ śrutvā vaivasvato yamaḥ
śatruṃ vijayinaṃ mene svabalasya ca saṃkṣayam', null, 7022001),
('ramayana-7-22-2', 2, 'Uttara Kanda, Sarga 22, Verse 2', 'स तु योधान्हतान्मत्वा क्रोधपर्याकुलेक्षणः।
अब्रवीत्त्वरितं सूतं रथः समुपनीयताम्॥', 'sa tu yodhān hatān matvā krodhaparyākulekṣaṇaḥ
abravīt tvaritaṃ sūtaṃ rathaḥ samupanīyatām', null, 7022002),
('ramayana-7-22-3', 3, 'Uttara Kanda, Sarga 22, Verse 3', 'तस्य सूतो रथं दिव्यमुपस्थाप्य महास्वनम्।
स्थितः स च महातेजा आरुरोह महारथम्॥', 'tasya sūto rathaṃ divyam upasthāpya mahāsvanam
sthitaḥ sa ca mahātejā āruroha mahāratham', null, 7022003),
('ramayana-7-22-4', 4, 'Uttara Kanda, Sarga 22, Verse 4', 'पाशमुद्गरहस्तश्च मृत्युस्तस्याग्रतो स्थितः।
येन संक्षिप्यते सर्वं त्रैलोक्यं सचराचरम्॥', 'pāśamudgarahastaś ca mṛtyus tasyāgrato sthitaḥ
yena saṃkṣipyate sarvaṃ trailokyaṃ sacarācaram', null, 7022004),
('ramayana-7-22-5', 5, 'Uttara Kanda, Sarga 22, Verse 5', 'कालदण्डश्च पार्श्वस्थो मूर्तिमान्स्यन्दने स्थितः।
यमप्रहरणं दिव्यं प्रज्वलन्निव तेजसा॥', 'kāladaṇḍaś ca pārśvastho mūrtimān syandane sthitaḥ
yamapraharaṇaṃ divyaṃ prajvalann iva tejasā', null, 7022005),
('ramayana-7-22-6', 6, 'Uttara Kanda, Sarga 22, Verse 6', 'ततो लोकास्त्रयस्त्रस्ताः कम्पन्ते च दिवौकसः।
कालं क्रुद्धं तदा दृष्ट्वा लोकत्रयभयावहम्॥', 'tato lokās trayas trastāḥ kampante ca divaukasaḥ
kālaṃ kruddhaṃ tadā dṛṣṭvā lokatrayabhayāvaham', null, 7022006),
('ramayana-7-22-7', 7, 'Uttara Kanda, Sarga 22, Verse 7', 'दृष्ट्वा तु ते तं विकृतं रथं मृत्युसमन्वितम्।
सचिवा राक्षसेन्द्रस्य सर्वलोकभयावहम्॥', 'dṛṣṭvā tu te taṃ vikṛtaṃ rathaṃ mṛtyusamanvitam
sacivā rākṣasendrasya sarvalokabhayāvaham', null, 7022007),
('ramayana-7-22-8', 8, 'Uttara Kanda, Sarga 22, Verse 8', 'लघुसत्त्वतया सर्वे नष्टसंज्ञा भयार्दिताः।
नात्र योद्धुं समर्थाः स्म इत्युक्त्वा विप्रदुद्रुवुः॥', 'laghusattvatayā sarve naṣṭasaṃjñā bhayārditāḥ
nātra yoddhuṃ samarthāḥ sma ity uktvā vipradudruvuḥ', null, 7022008),
('ramayana-7-22-9', 9, 'Uttara Kanda, Sarga 22, Verse 9', 'स तु तं तादृशं दृष्ट्वा रथं लोकभयावहम्।
नाक्षुभ्यत तदा रक्षो व्यथा चैवास्य नाभवत्॥', 'sa tu taṃ tādṛśaṃ dṛṣṭvā rathaṃ lokabhayāvaham
nākṣubhyata tadā rakṣo vyathā caivāsya nābhavat', null, 7022009),
('ramayana-7-22-10', 10, 'Uttara Kanda, Sarga 22, Verse 10', 'स तु रावणमासाद्य विसृजञ्शक्तितोमरान्।
यमो मर्माणि संक्रुद्धो राक्षसस्य न्यकृन्तत॥', 'sa tu rāvaṇam āsādya visṛjañ śaktitomarān
yamo marmāṇi saṃkruddho rākṣasasya nyakṛntata', null, 7022010),
('ramayana-7-22-11', 11, 'Uttara Kanda, Sarga 22, Verse 11', 'रावणस्तु स्थितः स्वस्थः शरवर्षं मुमोच ह।
तस्मिन्वैवस्वतरथे तोयवर्षमिवाम्बुदः॥', 'rāvaṇas tu sthitaḥ svasthaḥ śaravarṣaṃ mumoca ha
tasmin vaivasvatarathe toyavarṣam ivāmbudaḥ', null, 7022011),
('ramayana-7-22-12', 12, 'Uttara Kanda, Sarga 22, Verse 12', 'ततो महाशक्तिशतैः पात्यमानैर्महोरसि।
प्रतिकर्तुं स नाशक्नोद्राक्षसः शल्यपीडितः॥', 'tato mahāśaktiśataiḥ pātyamānair mahorasi
pratikartuṃ sa nāśaknod rākṣasaḥ śalyapīḍitaḥ', null, 7022012),
('ramayana-7-22-13', 13, 'Uttara Kanda, Sarga 22, Verse 13', 'नानाप्रहरणैरेवं यमेनामित्रकर्शिना।
सप्तरात्रं कृते संख्ये न भग्नो विजितोऽपि वा॥', 'nānāpraharaṇair evaṃ yamenāmitrakarśinā
saptarātraṃ kṛte saṃkhye na bhagno vijito ''pi vā', null, 7022013),
('ramayana-7-22-14', 14, 'Uttara Kanda, Sarga 22, Verse 14', 'ततोऽभवत्पुनर्युद्धं यमराक्षसयोस्तदा।
विजयाकाङ्क्षिणोस्तत्र समरेष्वनिवर्तिनोः॥', 'tato ''bhavat punar yuddhaṃ yamarākṣasayos tadā
vijayākāṅkṣiṇos tatra samareṣv anivartinoḥ', null, 7022014),
('ramayana-7-22-15', 15, 'Uttara Kanda, Sarga 22, Verse 15', 'ततो देवाः सगन्धर्वाः सिद्धाश्च परमर्षयः।
प्रजापतिं पुरस्कृत्य ददृशुस्तद्रणाजिरम्॥', 'tato devāḥ sagandharvāḥ siddhāś ca paramarṣayaḥ
prajāpatiṃ puraskṛtya dadṛśus tad raṇājiram', null, 7022015),
('ramayana-7-22-16', 16, 'Uttara Kanda, Sarga 22, Verse 16', 'संवर्त इव लोकानामभवद्युध्यतोस्तयोः।
राक्षसानां च मुख्यस्य प्रेतानामीश्वरस्य च॥', 'saṃvarta iva lokānām abhavad yudhyatos tayoḥ
rākṣasānāṃ ca mukhyasya pretānām īśvarasya ca', null, 7022016),
('ramayana-7-22-17', 17, 'Uttara Kanda, Sarga 22, Verse 17', 'राक्षसेन्द्रस्ततः क्रुद्धश्चापमायम्य संयुगे।
निरन्तरमिवाकाशं कुर्वन्बाणान्मुमोच ह॥', 'rākṣasendras tataḥ kruddhaś cāpam āyamya saṃyuge
nirantaram ivākāśaṃ kurvan bāṇān mumoca ha', null, 7022017),
('ramayana-7-22-18', 18, 'Uttara Kanda, Sarga 22, Verse 18', 'मृत्युं चतुर्भिर्विशिखैः सूतं सप्तभिरर्दयत्।
यमं शरसहस्रेण शीघ्रं मर्मस्वताडयत्॥', 'mṛtyuṃ caturbhir viśikhaiḥ sūtaṃ saptabhir ardayat
yamaṃ śarasahasreṇa śīghraṃ marmasv atāḍayat', null, 7022018),
('ramayana-7-22-19', 19, 'Uttara Kanda, Sarga 22, Verse 19', 'ततः क्रुद्धस्य सहसा यमस्याभिविनिःसृतः।
ज्वालामालो विनिश्वासो वदनात्क्रोधपावकः॥', 'tataḥ kruddhasya sahasā yamasyābhiviniḥsṛtaḥ
jvālāmālo viniśvāso vadanāt krodhapāvakaḥ', null, 7022019),
('ramayana-7-22-20', 20, 'Uttara Kanda, Sarga 22, Verse 20', 'ततोऽपश्यंस्तदाश्चर्यं देवदानवराक्षसाः।
क्रोधजं पावकं दीप्तं दिधक्षन्तं रिपोर्बलम्॥', 'tato ''paśyaṃs tadāścaryaṃ devadānavarākṣasāḥ
krodhajaṃ pāvakaṃ dīptaṃ didhakṣantaṃ ripor balam', null, 7022020),
('ramayana-7-22-21', 21, 'Uttara Kanda, Sarga 22, Verse 21', 'मृत्युस्तु परमक्रुद्धो वैवस्वतमथाब्रवीत्।
मुञ्च मां देव शीघ्रं त्वं निहन्मि समरे रिपुम्॥', 'mṛtyus tu paramakruddho vaivasvatam athābravīt
muñca māṃ deva śīghraṃ tvaṃ nihanmi samare ripum', null, 7022021),
('ramayana-7-22-22', 22, 'Uttara Kanda, Sarga 22, Verse 22', 'नरकः शम्बरो वृत्रः शम्भुः कार्तस्वरो बली।
नमुचिर्विरोचनश्चैव तावुभौ मधुकैटभौ॥', 'narakaḥ śambaro vṛtraḥ śambhuḥ kārtasvaro balī
namucir virocanaś caiva tāv ubhau madhukaiṭabhau', null, 7022022),
('ramayana-7-22-23', 23, 'Uttara Kanda, Sarga 22, Verse 23', 'एते चान्ये च बहवो बलवन्तो दुरासदाः।
विनिपन्ना मया दृष्टाः का चिन्तास्मिन्निशाचरे॥', 'ete cānye ca bahavo balavanto durāsadāḥ
vinipannā mayā dṛṣṭāḥ kā cintāsmin niśācare', null, 7022023),
('ramayana-7-22-24', 24, 'Uttara Kanda, Sarga 22, Verse 24', 'मुञ्च मां साधु धर्मज्ञ यावदेनं निहन्म्यहम्।
न हि कश्चिन्मया दृष्टो मुहूर्तमपि जीवति॥', 'muñca māṃ sādhu dharmajña yāvad enaṃ nihanmy aham
na hi kaś cin mayā dṛṣṭo muhūrtam api jīvati', null, 7022024),
('ramayana-7-22-25', 25, 'Uttara Kanda, Sarga 22, Verse 25', 'बलं मम न खल्वेतन्मर्यादैषा निसर्गतः।
संस्पृष्टो हि मया कश्चिन्न जीवेदिति निश्चयः॥', 'balaṃ mama na khalv etan maryādaiṣā nisargataḥ
saṃspṛṣṭo hi mayā kaś cin na jīved iti niścayaḥ', null, 7022025),
('ramayana-7-22-26', 26, 'Uttara Kanda, Sarga 22, Verse 26', 'एतत्तु वचनं श्रुत्वा धर्मराजः प्रतापवान्।
अब्रवीत्तत्र तं मृत्युमयमेनं निहन्म्यहम्॥', 'etat tu vacanaṃ śrutvā dharmarājaḥ pratāpavān
abravīt tatra taṃ mṛtyumayam enaṃ nihanmy aham', null, 7022026),
('ramayana-7-22-27', 27, 'Uttara Kanda, Sarga 22, Verse 27', 'ततः संरक्तनयनः क्रुद्धो वैवस्वतः प्रभुः।
कालदण्डममोघं तं तोलयामास पाणिना॥', 'tataḥ saṃraktanayanaḥ kruddho vaivasvataḥ prabhuḥ
kāladaṇḍam amoghaṃ taṃ tolayām āsa pāṇinā', null, 7022027),
('ramayana-7-22-28', 28, 'Uttara Kanda, Sarga 22, Verse 28', 'यस्य पार्श्वेषु निश्छिद्राः कालपाशाः प्रतिष्ठिताः।
पावकस्पर्शसंकाशो मुद्गरो मूर्तिमान्स्थितः॥', 'yasya pārśveṣu niśchidrāḥ kālapāśāḥ pratiṣṭhitāḥ
pāvakasparśasaṃkāśo mudgaro mūrtimān sthitaḥ', null, 7022028),
('ramayana-7-22-29', 29, 'Uttara Kanda, Sarga 22, Verse 29', 'दर्शनादेव यः प्राणान्प्राणिनामुपरुध्यति।
किं पुनस्ताडनाद्वापि पीडनाद्वापि देहिनः॥', 'darśanād eva yaḥ prāṇān prāṇinām uparudhyati
kiṃ punas tāḍanād vāpi pīḍanād vāpi dehinaḥ', null, 7022029),
('ramayana-7-22-30', 30, 'Uttara Kanda, Sarga 22, Verse 30', 'स ज्वालापरिवारस्तु पिबन्निव निशाचरम्।
करस्पृष्टो बलवता दण्डः क्रुद्धः सुदारुणः॥', 'sa jvālāparivāras tu pibann iva niśācaram
karaspṛṣṭo balavatā daṇḍaḥ kruddhaḥ sudāruṇaḥ', null, 7022030),
('ramayana-7-22-31', 31, 'Uttara Kanda, Sarga 22, Verse 31', 'ततो विदुद्रुवुः सर्वे सत्त्वास्तस्माद्रणाजिरात्।
सुराश्च क्षुभिता दृष्ट्वा कालदण्डोद्यतं यमम्॥', 'tato vidudruvuḥ sarve sattvās tasmād raṇājirāt
surāś ca kṣubhitā dṛṣṭvā kāladaṇḍodyataṃ yamam', null, 7022031),
('ramayana-7-22-32', 32, 'Uttara Kanda, Sarga 22, Verse 32', 'तस्मिन्प्रहर्तुकामे तु दण्डमुद्यम्य रावणम्।
यमं पितामहः साक्षाद्दर्शयित्वेदमब्रवीत्॥', 'tasmin prahartukāme tu daṇḍam udyamya rāvaṇam
yamaṃ pitāmahaḥ sākṣād darśayitvedam abravīt', null, 7022032),
('ramayana-7-22-33', 33, 'Uttara Kanda, Sarga 22, Verse 33', 'वैवस्वत महाबाहो न खल्वतुलविक्रम।
प्रहर्तव्यं त्वयैतेन दण्डेनास्मिन्निशाचरे॥', 'vaivasvata mahābāho na khalv atulavikrama
prahartavyaṃ tvayaitena daṇḍenāsmin niśācare', null, 7022033),
('ramayana-7-22-34', 34, 'Uttara Kanda, Sarga 22, Verse 34', 'वरः खलु मया दत्तस्तस्य त्रिदशपुंगव।
तत्त्वया नानृतं कार्यं यन्मया व्याहृतं वचः॥', 'varaḥ khalu mayā dattas tasya tridaśapuṃgava
tat tvayā nānṛtaṃ kāryaṃ yan mayā vyāhṛtaṃ vacaḥ', null, 7022034),
('ramayana-7-22-35', 35, 'Uttara Kanda, Sarga 22, Verse 35', 'अमोघो ह्येष सर्वासां प्रजानां विनिपातने।
कालदण्डो मया सृष्टः पूर्वं मृत्युपुरस्कृतः॥', 'amogho hy eṣa sarvāsāṃ prajānāṃ vinipātane
kāladaṇḍo mayā sṛṣṭaḥ pūrvaṃ mṛtyupuraskṛtaḥ', null, 7022035),
('ramayana-7-22-36', 36, 'Uttara Kanda, Sarga 22, Verse 36', 'तन्न खल्वेष ते सौम्य पात्यो राक्षसमूर्धनि।
न ह्यस्मिन्पतिते कश्चिन्मुहूर्तमपि जीवति॥', 'tan na khalv eṣa te saumya pātyo rākṣasamūrdhani
na hy asmin patite kaś cin muhūrtam api jīvati', null, 7022036),
('ramayana-7-22-37', 37, 'Uttara Kanda, Sarga 22, Verse 37', 'यदि ह्यस्मिन्निपतिते न म्रियेतैष राक्षसः।
म्रियेत वा दशग्रीवस्तथाप्युभयतोऽनृतम्॥', 'yadi hy asmin nipatite na mriyetaiṣa rākṣasaḥ
mriyeta vā daśagrīvas tathāpy ubhayato ''nṛtam', null, 7022037),
('ramayana-7-22-38', 38, 'Uttara Kanda, Sarga 22, Verse 38', 'राक्षसेन्द्रान्नियच्छाद्य दण्डमेनं वधोद्यतम्।
सत्यं मम कुरुष्वेदं लोकांस्त्वं समवेक्ष्य च॥', 'rākṣasendrān niyacchādya daṇḍam enaṃ vadhodyatam
satyaṃ mama kuruṣvedaṃ lokāṃs tvaṃ samavekṣya ca', null, 7022038),
('ramayana-7-22-39', 39, 'Uttara Kanda, Sarga 22, Verse 39', 'एवमुक्तस्तु धर्मात्मा प्रत्युवाच यमस्तदा।
एष व्यावर्तितो दण्डः प्रभविष्णुर्भवान्हि नः॥', 'evam uktas tu dharmātmā pratyuvāca yamas tadā
eṣa vyāvartito daṇḍaḥ prabhaviṣṇur bhavān hi naḥ', null, 7022039),
('ramayana-7-22-40', 40, 'Uttara Kanda, Sarga 22, Verse 40', 'किं त्विदानीं मया शक्यं कर्तुं रणगतेन हि।
यन्मया यन्न हन्तव्यो राक्षसो वरदर्पितः॥', 'kiṃ tv idānīṃ mayā śakyaṃ kartuṃ raṇagatena hi
yan mayā yan na hantavyo rākṣaso varadarpitaḥ', null, 7022040),
('ramayana-7-22-41', 41, 'Uttara Kanda, Sarga 22, Verse 41', 'एष तस्मात्प्रणश्यामि दर्शनादस्य रक्षसः।
इत्युक्त्वा सरथः साश्वस्तत्रैवान्तरधीयत॥', 'eṣa tasmāt praṇaśyāmi darśanād asya rakṣasaḥ
ity uktvā sarathaḥ sāśvas tatraivāntaradhīyata', null, 7022041),
('ramayana-7-22-42', 42, 'Uttara Kanda, Sarga 22, Verse 42', 'दशग्रीवस्तु तं जित्वा नाम विश्राव्य चात्मनः।
पुष्पकेण तु संहृष्टो निष्क्रान्तो यमसादनात्॥', 'daśagrīvas tu taṃ jitvā nāma viśrāvya cātmanaḥ
puṣpakeṇa tu saṃhṛṣṭo niṣkrānto yamasādanāt', null, 7022042),
('ramayana-7-22-43', 43, 'Uttara Kanda, Sarga 22, Verse 43', 'ततो वैवस्वतो देवैः सह ब्रह्मपुरोगमैः।
जगाम त्रिदिवं हृष्टो नारदश्च महामुनिः॥', 'tato vaivasvato devaiḥ saha brahmapurogamaiḥ
jagāma tridivaṃ hṛṣṭo nāradaś ca mahāmuniḥ', null, 7022043)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 23 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-23-1', 1, 'Uttara Kanda, Sarga 23, Verse 1', 'स तु जित्वा दशग्रीवो यमं त्रिदशपुंगवम्।
रावणस्तु जयश्लाघी स्वसहायान्ददर्श ह॥', 'sa tu jitvā daśagrīvo yamaṃ tridaśapuṃgavam
rāvaṇas tu jayaślāghī svasahāyān dadarśa ha', null, 7023001),
('ramayana-7-23-2', 2, 'Uttara Kanda, Sarga 23, Verse 2', 'जयेन वर्धयित्वा च मारीचप्रमुखास्ततः।
पुष्पकं भेजिरे सर्वे सान्त्विता रवणेन ह॥', 'jayena vardhayitvā ca mārīcapramukhās tataḥ
puṣpakaṃ bhejire sarve sāntvitā ravaṇena ha', null, 7023002),
('ramayana-7-23-3', 3, 'Uttara Kanda, Sarga 23, Verse 3', 'ततो रसातलं हृष्टः प्रविष्टः पयसो निधिम्।
दैत्योरग गणाध्युष्टं वरुणेन सुरक्षितम्॥', 'tato rasātalaṃ hṛṣṭaḥ praviṣṭaḥ payaso nidhim
daityoraga gaṇādhyuṣṭaṃ varuṇena surakṣitam', null, 7023003),
('ramayana-7-23-4', 4, 'Uttara Kanda, Sarga 23, Verse 4', 'स तु भोगवतीं गत्वा पुरीं वासुकिपालिताम्।
स्थाप्य नागान्वशे कृत्वा ययौ मणिमतीं पुरीम्॥', 'sa tu bhogavatīṃ gatvā purīṃ vāsukipālitām
sthāpya nāgān vaśe kṛtvā yayau maṇimatīṃ purīm', null, 7023004),
('ramayana-7-23-5', 5, 'Uttara Kanda, Sarga 23, Verse 5', 'निवातकवचास्तत्र दैत्या लब्धवरा वसन्।
राक्षसस्तान्समासाद्य युद्धेन समुपाह्वयत्॥', 'nivātakavacās tatra daityā labdhavarā vasan
rākṣasas tān samāsādya yuddhena samupāhvayat', null, 7023005),
('ramayana-7-23-6', 6, 'Uttara Kanda, Sarga 23, Verse 6', 'ते तु सर्वे सुविक्रान्ता दैतेया बलशालिनः।
नानाप्रहरणास्तत्र प्रयुद्धा युद्धदुर्मदाः॥', 'te tu sarve suvikrāntā daiteyā balaśālinaḥ
nānāpraharaṇās tatra prayuddhā yuddhadurmadāḥ', null, 7023006),
('ramayana-7-23-7', 7, 'Uttara Kanda, Sarga 23, Verse 7', 'तेषां तु युध्यमानानां साग्रः संवत्सरो गतः।
न चान्यतरयोस्तत्र विजयो वा क्षयोऽपि वा॥', 'teṣāṃ tu yudhyamānānāṃ sāgraḥ saṃvatsaro gataḥ
na cānyatarayos tatra vijayo vā kṣayo ''pi vā', null, 7023007),
('ramayana-7-23-8', 8, 'Uttara Kanda, Sarga 23, Verse 8', 'ततः पितामहस्तत्र त्रैलोक्यगतिरव्ययः।
आजगाम द्रुतं देवो विमानवरमास्थितः॥', 'tataḥ pitāmahas tatra trailokyagatir avyayaḥ
ājagāma drutaṃ devo vimānavaram āsthitaḥ', null, 7023008),
('ramayana-7-23-9', 9, 'Uttara Kanda, Sarga 23, Verse 9', 'निवातकवचानां तु निवार्य रणकर्म तत्।
वृद्धः पितामहो वाक्यमुवाच विदितार्थवत्॥', 'nivātakavacānāṃ tu nivārya raṇakarma tat
vṛddhaḥ pitāmaho vākyam uvāca viditārthavat', null, 7023009),
('ramayana-7-23-10', 10, 'Uttara Kanda, Sarga 23, Verse 10', 'न ह्ययं रावणो युद्धे शक्यो जेतुं सुरासुरैः।
न भवन्तः क्षयं नेतुं शक्याः सेन्द्रैः सुरासुरैः॥', 'na hy ayaṃ rāvaṇo yuddhe śakyo jetuṃ surāsuraiḥ
na bhavantaḥ kṣayaṃ netuṃ śakyāḥ sendraiḥ surāsuraiḥ', null, 7023010),
('ramayana-7-23-11', 11, 'Uttara Kanda, Sarga 23, Verse 11', 'राक्षसस्य सखित्वं वै भवद्भिः सह रोचते।
अविभक्ता हि सर्वार्थाः सुहृदां नात्र संशयः॥', 'rākṣasasya sakhitvaṃ vai bhavadbhiḥ saha rocate
avibhaktā hi sarvārthāḥ suhṛdāṃ nātra saṃśayaḥ', null, 7023011),
('ramayana-7-23-12', 12, 'Uttara Kanda, Sarga 23, Verse 12', 'ततोऽग्निसाक्षिकं सख्यं कृतवांस्तत्र रावणः।
निवातकवचैः सार्धं प्रीतिमानभवत्तदा॥', 'tato ''gnisākṣikaṃ sakhyaṃ kṛtavāṃs tatra rāvaṇaḥ
nivātakavacaiḥ sārdhaṃ prītimān abhavat tadā', null, 7023012),
('ramayana-7-23-13', 13, 'Uttara Kanda, Sarga 23, Verse 13', 'अर्चितस्तैर्यथान्यायं संवत्सरसुखोषितः।
स्वपुरान्निर्विशेषं च पूजां प्राप्तो दशाननः॥', 'arcitas tair yathānyāyaṃ saṃvatsarasukhoṣitaḥ
svapurān nirviśeṣaṃ ca pūjāṃ prāpto daśānanaḥ', null, 7023013),
('ramayana-7-23-14', 14, 'Uttara Kanda, Sarga 23, Verse 14', 'स तूपधार्य मायानां शतमेकोनमात्मवान्।
सलिलेन्द्रपुरान्वेषी स बभ्राम रसातलम्॥', 'sa tūpadhārya māyānāṃ śatam ekonam ātmavān
salilendrapurānveṣī sa babhrāma rasātalam', null, 7023014),
('ramayana-7-23-15', 15, 'Uttara Kanda, Sarga 23, Verse 15', 'ततोऽश्मनगरं नाम कालकेयाभिरक्षितम्।
तं विजित्य मुहूर्तेन जघ्ने दैत्यांश्चतुःशतम्॥', 'tato ''śmanagaraṃ nāma kālakeyābhirakṣitam
taṃ vijitya muhūrtena jaghne daityāṃś catuḥśatam', null, 7023015),
('ramayana-7-23-16', 16, 'Uttara Kanda, Sarga 23, Verse 16', 'ततः पाण्डुरमेघाभं कैलासमिव संस्थितम्।
वरुणस्यालयं दिव्यमपश्यद्राक्षसाधिपः॥', 'tataḥ pāṇḍurameghābhaṃ kailāsam iva saṃsthitam
varuṇasyālayaṃ divyam apaśyad rākṣasādhipaḥ', null, 7023016),
('ramayana-7-23-17', 17, 'Uttara Kanda, Sarga 23, Verse 17', 'क्षरन्तीं च पयो नित्यं सुरभिं गामवस्थिताम्।
यस्याः पयोविनिष्यन्दात्क्षीरोदो नाम सागरः॥', 'kṣarantīṃ ca payo nityaṃ surabhiṃ gām avasthitām
yasyāḥ payoviniṣyandāt kṣīrodo nāma sāgaraḥ', null, 7023017),
('ramayana-7-23-18', 18, 'Uttara Kanda, Sarga 23, Verse 18', 'यस्माच्चन्द्रः प्रभवति शीतरश्मिः प्रजाहितः।
यं समासाद्य जीवन्ति फेनपाः परमर्षयः।
अमृतं यत्र चोत्पन्नं सुरा चापि सुराशिनाम्॥', 'yasmāc candraḥ prabhavati śītaraśmiḥ prajāhitaḥ
yaṃ samāsādya jīvanti phenapāḥ paramarṣayaḥ
amṛtaṃ yatra cotpannaṃ surā cāpi surāśinām', null, 7023018),
('ramayana-7-23-19', 19, 'Uttara Kanda, Sarga 23, Verse 19', 'यां ब्रुवन्ति नरा लोके सुरभिं नाम नामतः।
प्रदक्षिणं तु तां कृत्वा रावणः परमाद्भुताम्।
प्रविवेश महाघोरं गुप्तं बहुविधैर्बलैः॥', 'yāṃ bruvanti narā loke surabhiṃ nāma nāmataḥ
pradakṣiṇaṃ tu tāṃ kṛtvā rāvaṇaḥ paramādbhutām
praviveśa mahāghoraṃ guptaṃ bahuvidhair balaiḥ', null, 7023019),
('ramayana-7-23-20', 20, 'Uttara Kanda, Sarga 23, Verse 20', 'ततो धाराशताकीर्णं शारदाभ्रनिभं तदा।
नित्यप्रहृष्टं ददृशे वरुणस्य गृहोत्तमम्॥', 'tato dhārāśatākīrṇaṃ śāradābhranibhaṃ tadā
nityaprahṛṣṭaṃ dadṛśe varuṇasya gṛhottamam', null, 7023020),
('ramayana-7-23-21', 21, 'Uttara Kanda, Sarga 23, Verse 21', 'ततो हत्वा बलाध्यक्षान्समरे तैश्च ताडितः।
अब्रवीत्क्व गतो यो वो राजा शीघ्रं निवेद्यताम्॥', 'tato hatvā balādhyakṣān samare taiś ca tāḍitaḥ
abravīt kva gato yo vo rājā śīghraṃ nivedyatām', null, 7023021),
('ramayana-7-23-22', 22, 'Uttara Kanda, Sarga 23, Verse 22', 'युद्धार्थी रावणः प्राप्तस्तस्य युद्धं प्रदीयताम्।
वद वा न भयं तेऽस्ति निर्जितोऽस्मीति साञ्जलिः॥', 'yuddhārthī rāvaṇaḥ prāptas tasya yuddhaṃ pradīyatām
vada vā na bhayaṃ te ''sti nirjito ''smīti sāñjaliḥ', null, 7023022),
('ramayana-7-23-23', 23, 'Uttara Kanda, Sarga 23, Verse 23', 'एतस्मिन्नन्तरे क्रुद्धा वरुणस्य महात्मनः।
पुत्राः पौत्राश्च निष्क्रामन्गौश्च पुष्कर एव च॥', 'etasminn antare kruddhā varuṇasya mahātmanaḥ
putrāḥ pautrāś ca niṣkrāman gauś ca puṣkara eva ca', null, 7023023),
('ramayana-7-23-24', 24, 'Uttara Kanda, Sarga 23, Verse 24', 'ते तु वीर्यगुणोपेता बलैः परिवृताः स्वकैः।
युक्त्वा रथान्कामगमानुद्यद्भास्करवर्चसः॥', 'te tu vīryaguṇopetā balaiḥ parivṛtāḥ svakaiḥ
yuktvā rathān kāmagamān udyadbhāskaravarcasaḥ', null, 7023024),
('ramayana-7-23-25', 25, 'Uttara Kanda, Sarga 23, Verse 25', 'ततो युद्धं समभवद्दारुणं लोमहर्षणम्।
सलिलेन्द्रस्य पुत्राणां रावणस्य च रक्षसः॥', 'tato yuddhaṃ samabhavad dāruṇaṃ lomaharṣaṇam
salilendrasya putrāṇāṃ rāvaṇasya ca rakṣasaḥ', null, 7023025),
('ramayana-7-23-26', 26, 'Uttara Kanda, Sarga 23, Verse 26', 'अमात्यैस्तु महावीर्यैर्दशग्रीवस्य रक्षसः।
वारुणं तद्बलं कृत्स्नं क्षणेन विनिपातितम्॥', 'amātyais tu mahāvīryair daśagrīvasya rakṣasaḥ
vāruṇaṃ tad balaṃ kṛtsnaṃ kṣaṇena vinipātitam', null, 7023026),
('ramayana-7-23-27', 27, 'Uttara Kanda, Sarga 23, Verse 27', 'समीक्ष्य स्वबलं संख्ये वरुणस्या सुतास्तदा।
अर्दिताः शरजालेन निवृत्ता रणकर्मणः॥', 'samīkṣya svabalaṃ saṃkhye varuṇasyā sutās tadā
arditāḥ śarajālena nivṛttā raṇakarmaṇaḥ', null, 7023027),
('ramayana-7-23-28', 28, 'Uttara Kanda, Sarga 23, Verse 28', 'महीतलगतास्ते तु रावणं दृश्य पुष्पके।
आकाशमाशु विविशुः स्यन्दनैः शीघ्रगामिभिः॥', 'mahītalagatās te tu rāvaṇaṃ dṛśya puṣpake
ākāśam āśu viviśuḥ syandanaiḥ śīghragāmibhiḥ', null, 7023028),
('ramayana-7-23-29', 29, 'Uttara Kanda, Sarga 23, Verse 29', 'महदासीत्ततस्तेषां तुल्यं स्थानमवाप्य तत्।
आकाशयुद्धं तुमुलं देवदानवयोरिव॥', 'mahad āsīt tatas teṣāṃ tulyaṃ sthānam avāpya tat
ākāśayuddhaṃ tumulaṃ devadānavayor iva', null, 7023029),
('ramayana-7-23-30', 30, 'Uttara Kanda, Sarga 23, Verse 30', 'ततस्ते रावणं युद्धे शरैः पावकसंनिभैः।
विमुखीकृत्य संहृष्टा विनेदुर्विविधान्रवान्॥', 'tatas te rāvaṇaṃ yuddhe śaraiḥ pāvakasaṃnibhaiḥ
vimukhīkṛtya saṃhṛṣṭā vinedur vividhān ravān', null, 7023030),
('ramayana-7-23-31', 31, 'Uttara Kanda, Sarga 23, Verse 31', 'ततो महोदरः क्रुद्धो राजानं दृश्य धर्षितम्।
त्यक्त्वा मृत्युभयं वीरो युद्धकाङ्क्षी व्यलोकयत्॥', 'tato mahodaraḥ kruddho rājānaṃ dṛśya dharṣitam
tyaktvā mṛtyubhayaṃ vīro yuddhakāṅkṣī vyalokayat', null, 7023031),
('ramayana-7-23-32', 32, 'Uttara Kanda, Sarga 23, Verse 32', 'तेन तेषां हया ये च कामगाः पवनोपमाः।
महोदरेण गदया हतास्ते प्रययुः क्षितिम्॥', 'tena teṣāṃ hayā ye ca kāmagāḥ pavanopamāḥ
mahodareṇa gadayā hatās te prayayuḥ kṣitim', null, 7023032),
('ramayana-7-23-33', 33, 'Uttara Kanda, Sarga 23, Verse 33', 'तेषां वरुणसूनूनां हत्वा योधान्हयांश्च तान्।
मुमोचाशु महानादं विरथान्प्रेक्ष्य तान्स्थितान्॥', 'teṣāṃ varuṇasūnūnāṃ hatvā yodhān hayāṃś ca tān
mumocāśu mahānādaṃ virathān prekṣya tān sthitān', null, 7023033),
('ramayana-7-23-34', 34, 'Uttara Kanda, Sarga 23, Verse 34', 'ते तु तेषां रथाः साश्वाः सह सारथिभिर्वरैः।
महोदरेण निहताः पतिताः पृथिवीतले॥', 'te tu teṣāṃ rathāḥ sāśvāḥ saha sārathibhir varaiḥ
mahodareṇa nihatāḥ patitāḥ pṛthivītale', null, 7023034),
('ramayana-7-23-35', 35, 'Uttara Kanda, Sarga 23, Verse 35', 'ते तु त्यक्त्वा रथान्पुत्रा वरुणस्य महात्मनः।
आकाशे विष्ठिताः शूराः स्वप्रभावान्न विव्यथुः॥', 'te tu tyaktvā rathān putrā varuṇasya mahātmanaḥ
ākāśe viṣṭhitāḥ śūrāḥ svaprabhāvān na vivyathuḥ', null, 7023035),
('ramayana-7-23-36', 36, 'Uttara Kanda, Sarga 23, Verse 36', 'धनूंषि कृत्वा सज्यानि विनिर्भिद्य महोदरम्।
रावणं समरे क्रुद्धाः सहिताः समभिद्रवन्॥', 'dhanūṃṣi kṛtvā sajyāni vinirbhidya mahodaram
rāvaṇaṃ samare kruddhāḥ sahitāḥ samabhidravan', null, 7023036),
('ramayana-7-23-37', 37, 'Uttara Kanda, Sarga 23, Verse 37', 'ततः क्रुद्धो दशग्रीवः कालाग्निरिव विष्ठितः।
शरवर्षं महावेगं तेषां मर्मस्वपातयत्॥', 'tataḥ kruddho daśagrīvaḥ kālāgnir iva viṣṭhitaḥ
śaravarṣaṃ mahāvegaṃ teṣāṃ marmasv apātayat', null, 7023037),
('ramayana-7-23-38', 38, 'Uttara Kanda, Sarga 23, Verse 38', 'मुसलानि विचित्राणि ततो भल्लशतानि च।
पट्टसांश्चैव शक्तीश्च शतघ्नीस्तोमरांस्तथा।
पातयामास दुर्धर्षस्तेषामुपरि विष्ठितः॥', 'musalāni vicitrāṇi tato bhallaśatāni ca
paṭṭasāṃś caiva śaktīś ca śataghnīs tomarāṃs tathā
pātayām āsa durdharṣas teṣām upari viṣṭhitaḥ', null, 7023038),
('ramayana-7-23-39', 39, 'Uttara Kanda, Sarga 23, Verse 39', 'अथ विद्धास्तु ते वीरा विनिष्पेतुः पदातयः॥', 'atha viddhās tu te vīrā viniṣpetuḥ padātayaḥ', null, 7023039),
('ramayana-7-23-40', 40, 'Uttara Kanda, Sarga 23, Verse 40', 'ततो रक्षो महानादं मुक्त्वा हन्ति स्म वारुणान्।
नानाप्रहरणैर्घोरैर्धारापातैरिवाम्बुदः॥', 'tato rakṣo mahānādaṃ muktvā hanti sma vāruṇān
nānāpraharaṇair ghorair dhārāpātair ivāmbudaḥ', null, 7023040),
('ramayana-7-23-41', 41, 'Uttara Kanda, Sarga 23, Verse 41', 'ततस्ते विमुखाः सर्वे पतिता धरणीतले।
रणात्स्वपुरुषैः शीघ्रं गृहाण्येव प्रवेशिताः॥', 'tatas te vimukhāḥ sarve patitā dharaṇītale
raṇāt svapuruṣaiḥ śīghraṃ gṛhāṇy eva praveśitāḥ', null, 7023041),
('ramayana-7-23-42', 42, 'Uttara Kanda, Sarga 23, Verse 42', 'तानब्रवीत्ततो रक्षो वरुणाय निवेद्यताम्।
रावणं चाब्रवीन्मन्त्री प्रभासो नाम वारुणः॥', 'tān abravīt tato rakṣo varuṇāya nivedyatām
rāvaṇaṃ cābravīn mantrī prabhāso nāma vāruṇaḥ', null, 7023042),
('ramayana-7-23-43', 43, 'Uttara Kanda, Sarga 23, Verse 43', 'गतः खलु महातेजा ब्रह्मलोकं जलेश्वरः।
गान्धर्वं वरुणः श्रोतुं यं त्वमाह्वयसे युधि॥', 'gataḥ khalu mahātejā brahmalokaṃ jaleśvaraḥ
gāndharvaṃ varuṇaḥ śrotuṃ yaṃ tvam āhvayase yudhi', null, 7023043),
('ramayana-7-23-44', 44, 'Uttara Kanda, Sarga 23, Verse 44', 'तत्किं तव वृथा वीर परिश्राम्य गते नृपे।
ये तु संनिहिता वीराः कुमारास्ते पराजिताः॥', 'tat kiṃ tava vṛthā vīra pariśrāmya gate nṛpe
ye tu saṃnihitā vīrāḥ kumārās te parājitāḥ', null, 7023044),
('ramayana-7-23-45', 45, 'Uttara Kanda, Sarga 23, Verse 45', 'राक्षसेन्द्रस्तु तच्छ्रुत्वा नाम विश्राव्य चात्मनः।
हर्षान्नादं विमुञ्चन्वै निष्क्रान्तो वरुणालयात्॥', 'rākṣasendras tu tac chrutvā nāma viśrāvya cātmanaḥ
harṣān nādaṃ vimuñcan vai niṣkrānto varuṇālayāt', null, 7023045),
('ramayana-7-23-46', 46, 'Uttara Kanda, Sarga 23, Verse 46', 'आगतस्तु पथा येन तेनैव विनिवृत्य सः।
लङ्कामभिमुखो रक्षो नभस्तलगतो ययौ॥', 'āgatas tu pathā yena tenaiva vinivṛtya saḥ
laṅkām abhimukho rakṣo nabhastalagato yayau', null, 7023046)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 24 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-24-1', 1, 'Uttara Kanda, Sarga 24, Verse 1', 'निवर्तमानः संहृष्टो रावणः स दुरात्मवान्।
जह्रे पथि नरेन्द्रर्षिदेवगन्धर्वकन्यकाः॥', 'nivartamānaḥ saṃhṛṣṭo rāvaṇaḥ sa durātmavān
jahre pathi narendrarṣidevagandharvakanyakāḥ', null, 7024001),
('ramayana-7-24-2', 2, 'Uttara Kanda, Sarga 24, Verse 2', 'दर्शनीयां हि यां रक्षः कन्यां स्त्रीं वाथ पश्यति।
हत्वा बन्धुजनं तस्या विमाने संन्यवेशयत्॥', 'darśanīyāṃ hi yāṃ rakṣaḥ kanyāṃ strīṃ vātha paśyati
hatvā bandhujanaṃ tasyā vimāne saṃnyaveśayat', null, 7024002),
('ramayana-7-24-3', 3, 'Uttara Kanda, Sarga 24, Verse 3', 'तत्र पन्नगयक्षाणां मानुषाणां च रक्षसाम्।
दैत्यानां दानवानां च कन्या जग्राह रावणः॥', 'tatra pannagayakṣāṇāṃ mānuṣāṇāṃ ca rakṣasām
daityānāṃ dānavānāṃ ca kanyā jagrāha rāvaṇaḥ', null, 7024003),
('ramayana-7-24-4', 4, 'Uttara Kanda, Sarga 24, Verse 4', 'दीर्घकेश्यः सुचार्वङ्ग्यः पूर्णचन्द्रनिभाननाः।
शोकायत्तास्तरुण्यश्च समस्ता स्तननम्रिताः॥', 'dīrghakeśyaḥ sucārvaṅgyaḥ pūrṇacandranibhānanāḥ
śokāyattās taruṇyaś ca samastā stananamritāḥ', null, 7024004),
('ramayana-7-24-5', 5, 'Uttara Kanda, Sarga 24, Verse 5', 'तुल्यमग्न्यर्चिषां तत्र शोकाग्निभयसंभवम्।
प्रवेपमाना दुःखार्ता मुमुचुर्बाष्पजं जलम्॥', 'tulyam agnyarciṣāṃ tatra śokāgnibhayasaṃbhavam
pravepamānā duḥkhārtā mumucur bāṣpajaṃ jalam', null, 7024005),
('ramayana-7-24-6', 6, 'Uttara Kanda, Sarga 24, Verse 6', 'तासां निश्वसमानानां निश्वसैः संप्रदीपितम्।
अग्निहोत्रमिवाभाति संनिरुद्धाग्निपुष्पकम्॥', 'tāsāṃ niśvasamānānāṃ niśvasaiḥ saṃpradīpitam
agnihotram ivābhāti saṃniruddhāgnipuṣpakam', null, 7024006),
('ramayana-7-24-7', 7, 'Uttara Kanda, Sarga 24, Verse 7', 'का चिद्दध्यौ सुदुःखार्ता हन्यादपि हि मामयम्।
स्मृत्वा मातॄः पितॄन्भ्रातॄन्पुत्रान्वै श्वशुरानपि।
दुःखशोकसमाविष्टा विलेपुः सहिताः स्त्रियः॥', 'kā cid dadhyau suduḥkhārtā hanyād api hi mām ayam
smṛtvā mātṝḥ pitṝn bhrātṝn putrān vai śvaśurān api
duḥkhaśokasamāviṣṭā vilepuḥ sahitāḥ striyaḥ', null, 7024007),
('ramayana-7-24-8', 8, 'Uttara Kanda, Sarga 24, Verse 8', 'कथं नु खलु मे पुत्रः करिष्यति मया विना।
कथं माता कथं भ्राता निमग्नाः शोकसागरे॥', 'kathaṃ nu khalu me putraḥ kariṣyati mayā vinā
kathaṃ mātā kathaṃ bhrātā nimagnāḥ śokasāgare', null, 7024008),
('ramayana-7-24-9', 9, 'Uttara Kanda, Sarga 24, Verse 9', 'हा कथं नु करिष्यामि भर्तारं दैवतं विना।
मृत्यो प्रसीद याचे त्वां नय मां यमसादनम्॥', 'hā kathaṃ nu kariṣyāmi bhartāraṃ daivataṃ vinā
mṛtyo prasīda yāce tvāṃ naya māṃ yamasādanam', null, 7024009),
('ramayana-7-24-10', 10, 'Uttara Kanda, Sarga 24, Verse 10', 'किं नु मे दुष्कृतं कर्म कृतं देहान्तरे पुरा।
ततोऽस्मि धर्षितानेन पतिता शोकसागरे॥', 'kiṃ nu me duṣkṛtaṃ karma kṛtaṃ dehāntare purā
tato ''smi dharṣitānena patitā śokasāgare', null, 7024010),
('ramayana-7-24-11', 11, 'Uttara Kanda, Sarga 24, Verse 11', 'न खल्विदानीं पश्यामि दुःखस्यान्तमिहात्मनः।
अहो धिन्मानुषांल्लोकान्नास्ति खल्वधमः परः॥', 'na khalv idānīṃ paśyāmi duḥkhasyāntam ihātmanaḥ
aho dhin mānuṣāṃl lokān nāsti khalv adhamaḥ paraḥ', null, 7024011),
('ramayana-7-24-12', 12, 'Uttara Kanda, Sarga 24, Verse 12', 'यद्दुर्बला बलवता बान्धवा रावणेन मे।
उदितेनैव सूर्येण तारका इव नाशिताः॥', 'yad durbalā balavatā bāndhavā rāvaṇena me
uditenaiva sūryeṇa tārakā iva nāśitāḥ', null, 7024012),
('ramayana-7-24-13', 13, 'Uttara Kanda, Sarga 24, Verse 13', 'अहो सुबलवद्रक्षो वधोपायेषु रज्यते।
अहो दुर्वृत्तमात्मानं स्वयमेव न बुध्यते॥', 'aho subalavad rakṣo vadhopāyeṣu rajyate
aho durvṛttam ātmānaṃ svayam eva na budhyate', null, 7024013),
('ramayana-7-24-14', 14, 'Uttara Kanda, Sarga 24, Verse 14', 'सर्वथा सदृशस्तावद्विक्रमोऽस्य दुरात्मनः।
इदं त्वसदृशं कर्म परदाराभिमर्शनम्॥', 'sarvathā sadṛśas tāvad vikramo ''sya durātmanaḥ
idaṃ tv asadṛśaṃ karma paradārābhimarśanam', null, 7024014),
('ramayana-7-24-15', 15, 'Uttara Kanda, Sarga 24, Verse 15', 'यस्मादेष परख्यासु स्त्रीषु रज्यति दुर्मतिः।
तस्माद्धि स्त्रीकृतेनैव वधं प्राप्स्यति वारणः॥', 'yasmād eṣa parakhyāsu strīṣu rajyati durmatiḥ
tasmād dhi strīkṛtenaiva vadhaṃ prāpsyati vāraṇaḥ', null, 7024015),
('ramayana-7-24-16', 16, 'Uttara Kanda, Sarga 24, Verse 16', 'शप्तः स्त्रीभिः स तु तदा हततेजाः सुनिष्प्रभ।
पतिव्रताभिः साध्वीभिः स्थिताभिः साधु वर्त्मनि॥', 'śaptaḥ strībhiḥ sa tu tadā hatatejāḥ suniṣprabha
pativratābhiḥ sādhvībhiḥ sthitābhiḥ sādhu vartmani', null, 7024016),
('ramayana-7-24-17', 17, 'Uttara Kanda, Sarga 24, Verse 17', 'एवं विलपमानासु रावणो राक्षसाधिपः।
प्रविवेश पुरीं लङ्कां पूज्यमानो निशाचरैः॥', 'evaṃ vilapamānāsu rāvaṇo rākṣasādhipaḥ
praviveśa purīṃ laṅkāṃ pūjyamāno niśācaraiḥ', null, 7024017),
('ramayana-7-24-18', 18, 'Uttara Kanda, Sarga 24, Verse 18', 'ततो राक्षसराजस्य स्वसा परमदुःखिता।
पादयोः पतिता तस्य वक्तुमेवोपचक्रमे॥', 'tato rākṣasarājasya svasā paramaduḥkhitā
pādayoḥ patitā tasya vaktum evopacakrame', null, 7024018),
('ramayana-7-24-19', 19, 'Uttara Kanda, Sarga 24, Verse 19', 'ततः स्वसारमुत्थाप्य रावणः परिसान्त्वयन्।
अब्रवीत्किमिदं भद्रे वक्तुमर्हसि मे द्रुतम्॥', 'tataḥ svasāram utthāpya rāvaṇaḥ parisāntvayan
abravīt kim idaṃ bhadre vaktum arhasi me drutam', null, 7024019),
('ramayana-7-24-20', 20, 'Uttara Kanda, Sarga 24, Verse 20', 'सा बाष्पपरिरुद्धाक्षी राक्षसी वाक्यमब्रवीत्।
हतास्मि विधवा राजंस्त्वया बलवता कृता॥', 'sā bāṣpapariruddhākṣī rākṣasī vākyam abravīt
hatāsmi vidhavā rājaṃs tvayā balavatā kṛtā', null, 7024020),
('ramayana-7-24-21', 21, 'Uttara Kanda, Sarga 24, Verse 21', 'एते विर्यात्त्वया राजन्दैत्या विनिहता रणे।
कालकेया इति ख्याता महाबलपराक्रमाः॥', 'ete viryāt tvayā rājan daityā vinihatā raṇe
kālakeyā iti khyātā mahābalaparākramāḥ', null, 7024021),
('ramayana-7-24-22', 22, 'Uttara Kanda, Sarga 24, Verse 22', 'तत्र मे निहतो भर्ता गरीयाञ्जीवितादपि।
स त्वया दयितस्तत्र भ्रात्रा शत्रुसमेन वै॥', 'tatra me nihato bhartā garīyāñ jīvitād api
sa tvayā dayitas tatra bhrātrā śatrusamena vai', null, 7024022),
('ramayana-7-24-23', 23, 'Uttara Kanda, Sarga 24, Verse 23', 'या त्वयास्मि हता राजन्स्वयमेवेह बन्धुना।
दुःखं वैधव्यशब्दं च दत्तं भोक्ष्याम्यहं त्वया॥', 'yā tvayāsmi hatā rājan svayam eveha bandhunā
duḥkhaṃ vaidhavyaśabdaṃ ca dattaṃ bhokṣyāmy ahaṃ tvayā', null, 7024023),
('ramayana-7-24-24', 24, 'Uttara Kanda, Sarga 24, Verse 24', 'ननु नाम त्वया रक्ष्यो जामाता समरेष्वपि।
तं निहत्य रणे राजन्स्वयमेव न लज्जसे॥', 'nanu nāma tvayā rakṣyo jāmātā samareṣv api
taṃ nihatya raṇe rājan svayam eva na lajjase', null, 7024024),
('ramayana-7-24-25', 25, 'Uttara Kanda, Sarga 24, Verse 25', 'एवमुक्तस्तया रक्षो भगिन्या क्रोशमानया।
अब्रवीत्सान्त्वयित्वा तां सामपूर्वमिदं वचः॥', 'evam uktas tayā rakṣo bhaginyā krośamānayā
abravīt sāntvayitvā tāṃ sāmapūrvam idaṃ vacaḥ', null, 7024025),
('ramayana-7-24-26', 26, 'Uttara Kanda, Sarga 24, Verse 26', 'अलं वत्से विषादेन न भेतव्यं च सर्वशः।
मानदानविशेषैस्त्वां तोषयिष्यामि नित्यशः॥', 'alaṃ vatse viṣādena na bhetavyaṃ ca sarvaśaḥ
mānadānaviśeṣais tvāṃ toṣayiṣyāmi nityaśaḥ', null, 7024026),
('ramayana-7-24-27', 27, 'Uttara Kanda, Sarga 24, Verse 27', 'युद्धे प्रमत्तो व्याक्षिप्तो जयकाङ्क्षी क्षिपञ्शरान्।
नावगच्छामि युद्धेषु स्वान्परान्वाप्यहं शुभे।
तेनासौ निहतः संख्ये मया भर्ता तव स्वसः॥', 'yuddhe pramatto vyākṣipto jayakāṅkṣī kṣipañ śarān
nāvagacchāmi yuddheṣu svān parān vāpy ahaṃ śubhe
tenāsau nihataḥ saṃkhye mayā bhartā tava svasaḥ', null, 7024027),
('ramayana-7-24-28', 28, 'Uttara Kanda, Sarga 24, Verse 28', 'अस्मिन्काले तु यत्प्राप्तं तत्करिष्यामि ते हितम्।
भ्रातुरैश्वर्यसंस्थस्य खरस्य भव पार्श्वतः॥', 'asmin kāle tu yat prāptaṃ tat kariṣyāmi te hitam
bhrātur aiśvaryasaṃsthasya kharasya bhava pārśvataḥ', null, 7024028),
('ramayana-7-24-29', 29, 'Uttara Kanda, Sarga 24, Verse 29', 'चतुर्दशानां भ्राता ते सहस्राणां भविष्यति।
प्रभुः प्रयाणे दाने च राक्षसानां महौजसाम्॥', 'caturdaśānāṃ bhrātā te sahasrāṇāṃ bhaviṣyati
prabhuḥ prayāṇe dāne ca rākṣasānāṃ mahaujasām', null, 7024029),
('ramayana-7-24-30', 30, 'Uttara Kanda, Sarga 24, Verse 30', 'तत्र मातृष्वसुः पुत्रो भ्राता तव खरः प्रभुः।
भविष्यति सदा कुर्वन्यद्वक्ष्यसि वचः स्वयम्॥', 'tatra mātṛṣvasuḥ putro bhrātā tava kharaḥ prabhuḥ
bhaviṣyati sadā kurvan yad vakṣyasi vacaḥ svayam', null, 7024030),
('ramayana-7-24-31', 31, 'Uttara Kanda, Sarga 24, Verse 31', 'शीघ्रं गच्छत्वयं शूरो दण्डकान्परिरक्षितुम्।
दूषणोऽस्य बलाध्यक्षो भविष्यति महाबलः॥', 'śīghraṃ gacchatv ayaṃ śūro daṇḍakān parirakṣitum
dūṣaṇo ''sya balādhyakṣo bhaviṣyati mahābalaḥ', null, 7024031),
('ramayana-7-24-32', 32, 'Uttara Kanda, Sarga 24, Verse 32', 'स हि शप्तो वनोद्देशः क्रुद्धेनोशनसा पुरा।
राक्षसानामयं वासो भविष्यति न संशयः॥', 'sa hi śapto vanoddeśaḥ kruddhenośanasā purā
rākṣasānām ayaṃ vāso bhaviṣyati na saṃśayaḥ', null, 7024032),
('ramayana-7-24-33', 33, 'Uttara Kanda, Sarga 24, Verse 33', 'एवमुक्त्वा दशग्रीवः सैन्यं तस्यादिदेश ह।
चतुर्दश सहस्राणि रक्षसां कामरूपिणाम्॥', 'evam uktvā daśagrīvaḥ sainyaṃ tasyādideśa ha
caturdaśa sahasrāṇi rakṣasāṃ kāmarūpiṇām', null, 7024033),
('ramayana-7-24-34', 34, 'Uttara Kanda, Sarga 24, Verse 34', 'स तैः सर्वैः परिवृतो राक्षसैर्घोरदर्शनैः।
खरः संप्रययौ शीघ्रं दण्डकानकुतोभयः॥', 'sa taiḥ sarvaiḥ parivṛto rākṣasair ghoradarśanaiḥ
kharaḥ saṃprayayau śīghraṃ daṇḍakān akutobhayaḥ', null, 7024034),
('ramayana-7-24-35', 35, 'Uttara Kanda, Sarga 24, Verse 35', 'स तत्र कारयामास राज्यं निहतकण्टकम्।
सा च शूर्पणखा प्रीता न्यवसद्दण्डकावने॥', 'sa tatra kārayām āsa rājyaṃ nihatakaṇṭakam
sā ca śūrpaṇakhā prītā nyavasad daṇḍakāvane', null, 7024035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 25 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-25-1', 1, 'Uttara Kanda, Sarga 25, Verse 1', 'स तु दत्त्वा दशग्रीवो वनं घोरं खरस्य तत्।
भगिनीं च समाश्वास्य हृष्टः स्वस्थतरोऽभवत्॥', 'sa tu dattvā daśagrīvo vanaṃ ghoraṃ kharasya tat
bhaginīṃ ca samāśvāsya hṛṣṭaḥ svasthataro ''bhavat', null, 7025001),
('ramayana-7-25-2', 2, 'Uttara Kanda, Sarga 25, Verse 2', 'ततो निकुम्भिला नाम लङ्कायाः काननं महत्।
महात्मा राक्षसेन्द्रस्तत्प्रविवेश सहानुगः॥', 'tato nikumbhilā nāma laṅkāyāḥ kānanaṃ mahat
mahātmā rākṣasendras tat praviveśa sahānugaḥ', null, 7025002),
('ramayana-7-25-3', 3, 'Uttara Kanda, Sarga 25, Verse 3', 'तत्र यूपशताकीर्णं सौम्यचैत्योपशोभितम्।
ददर्श विष्ठितं यज्ञं संप्रदीप्तमिव श्रिया॥', 'tatra yūpaśatākīrṇaṃ saumyacaityopaśobhitam
dadarśa viṣṭhitaṃ yajñaṃ saṃpradīptam iva śriyā', null, 7025003),
('ramayana-7-25-4', 4, 'Uttara Kanda, Sarga 25, Verse 4', 'ततः कृष्णाजिनधरं कमण्डलुशिखाध्वजम्।
ददर्श स्वसुतं तत्र मेघनादमरिंदमम्॥', 'tataḥ kṛṣṇājinadharaṃ kamaṇḍaluśikhādhvajam
dadarśa svasutaṃ tatra meghanādam ariṃdamam', null, 7025004),
('ramayana-7-25-5', 5, 'Uttara Kanda, Sarga 25, Verse 5', 'रक्षःपतिः समासाद्य समाश्लिष्य च बाहुभिः।
अब्रवीत्किमिदं वत्स वर्तते तद्ब्रवीहि मे॥', 'rakṣaḥpatiḥ samāsādya samāśliṣya ca bāhubhiḥ
abravīt kim idaṃ vatsa vartate tad bravīhi me', null, 7025005),
('ramayana-7-25-6', 6, 'Uttara Kanda, Sarga 25, Verse 6', 'उशना त्वब्रवीत्तत्र गुरुर्यज्ञसमृद्धये।
रावणं राक्षसश्रेष्ठं द्विजश्रेष्ठो महातपाः॥', 'uśanā tv abravīt tatra gurur yajñasamṛddhaye
rāvaṇaṃ rākṣasaśreṣṭhaṃ dvijaśreṣṭho mahātapāḥ', null, 7025006),
('ramayana-7-25-7', 7, 'Uttara Kanda, Sarga 25, Verse 7', 'अहमाख्यामि ते राजञ्श्रूयतां सर्वमेव च।
यज्ञास्ते सप्त पुत्रेण प्राप्ताः सुबहुविस्तराः॥', 'aham ākhyāmi te rājañ śrūyatāṃ sarvam eva ca
yajñās te sapta putreṇa prāptāḥ subahuvistarāḥ', null, 7025007),
('ramayana-7-25-8', 8, 'Uttara Kanda, Sarga 25, Verse 8', 'अग्निष्टोमोऽश्वमेधश्च यज्ञो बहुसुवर्णकः।
राजसूयस्तथा यज्ञो गोमेधो वैष्णवस्तथा॥', 'agniṣṭomo ''śvamedhaś ca yajño bahusuvarṇakaḥ
rājasūyas tathā yajño gomedho vaiṣṇavas tathā', null, 7025008),
('ramayana-7-25-9', 9, 'Uttara Kanda, Sarga 25, Verse 9', 'माहेश्वरे प्रवृत्ते तु यज्ञे पुम्भिः सुदुर्लभे।
वरांस्ते लब्धवान्पुत्रः साक्षात्पशुपतेरिह॥', 'māheśvare pravṛtte tu yajñe pumbhiḥ sudurlabhe
varāṃs te labdhavān putraḥ sākṣāt paśupater iha', null, 7025009),
('ramayana-7-25-10', 10, 'Uttara Kanda, Sarga 25, Verse 10', 'कामगं स्यन्दनं दिव्यमन्तरिक्षचरं ध्रुवम्।
मायां च तामसीं नाम यया संपद्यते तमः॥', 'kāmagaṃ syandanaṃ divyam antarikṣacaraṃ dhruvam
māyāṃ ca tāmasīṃ nāma yayā saṃpadyate tamaḥ', null, 7025010),
('ramayana-7-25-11', 11, 'Uttara Kanda, Sarga 25, Verse 11', 'एतया किल संग्रामे मायया राक्षसेश्वर।
प्रयुद्धस्य गतिः शक्या न हि ज्ञातुं सुरासुरैः॥', 'etayā kila saṃgrāme māyayā rākṣaseśvara
prayuddhasya gatiḥ śakyā na hi jñātuṃ surāsuraiḥ', null, 7025011),
('ramayana-7-25-12', 12, 'Uttara Kanda, Sarga 25, Verse 12', 'अक्षयाविषुधी बाणैश्चापं चापि सुदुर्जयम्।
अस्त्रं च बलवत्सौम्य शत्रुविध्वंसनं रणे॥', 'akṣayāv iṣudhī bāṇaiś cāpaṃ cāpi sudurjayam
astraṃ ca balavat saumya śatruvidhvaṃsanaṃ raṇe', null, 7025012),
('ramayana-7-25-13', 13, 'Uttara Kanda, Sarga 25, Verse 13', 'एतान्सर्वान्वरांल्लब्ध्वा पुत्रस्तेऽयं दशानन।
अद्य यज्ञसमाप्तौ च त्वत्प्रतीक्षः स्थितो अहम्॥', 'etān sarvān varāṃl labdhvā putras te ''yaṃ daśānana
adya yajñasamāptau ca tvatpratīkṣaḥ sthito aham', null, 7025013),
('ramayana-7-25-14', 14, 'Uttara Kanda, Sarga 25, Verse 14', 'ततोऽब्रवीद्दशग्रीवो न शोभनमिदं कृतम्।
पूजिताः शत्रवो यस्माद्द्रव्यैरिन्द्रपुरोगमाः॥', 'tato ''bravīd daśagrīvo na śobhanam idaṃ kṛtam
pūjitāḥ śatravo yasmād dravyair indrapurogamāḥ', null, 7025014),
('ramayana-7-25-15', 15, 'Uttara Kanda, Sarga 25, Verse 15', 'एहीदानीं कृतं यद्धि तदकर्तुं न शक्यते।
आगच्छ सौम्य गच्छामः स्वमेव भवनं प्रति॥', 'ehīdānīṃ kṛtaṃ yad dhi tad akartuṃ na śakyate
āgaccha saumya gacchāmaḥ svam eva bhavanaṃ prati', null, 7025015),
('ramayana-7-25-16', 16, 'Uttara Kanda, Sarga 25, Verse 16', 'ततो गत्वा दशग्रीवः सपुत्रः सविभीषणः।
स्त्रियोऽवतारयामास सर्वास्ता बाष्पविक्लवाः॥', 'tato gatvā daśagrīvaḥ saputraḥ savibhīṣaṇaḥ
striyo ''vatārayām āsa sarvās tā bāṣpaviklavāḥ', null, 7025016),
('ramayana-7-25-17', 17, 'Uttara Kanda, Sarga 25, Verse 17', 'लक्षिण्यो रत्नबूताश्च देवदानवरक्षसाम्।
नानाभूषणसंपन्ना ज्वलन्त्यः स्वेन तेजसा॥', 'lakṣiṇyo ratnabūtāś ca devadānavarakṣasām
nānābhūṣaṇasaṃpannā jvalantyaḥ svena tejasā', null, 7025017),
('ramayana-7-25-18', 18, 'Uttara Kanda, Sarga 25, Verse 18', 'विभीषणस्तु ता नारीर्दृष्ट्वा शोकसमाकुलाः।
तस्य तां च मतिं ज्ञात्वा धर्मात्मा वाक्यमब्रवीत्॥', 'vibhīṣaṇas tu tā nārīr dṛṣṭvā śokasamākulāḥ
tasya tāṃ ca matiṃ jñātvā dharmātmā vākyam abravīt', null, 7025018),
('ramayana-7-25-19', 19, 'Uttara Kanda, Sarga 25, Verse 19', 'ईदृशैस्तैः समाचारैर्यशोऽर्थकुलनाशनैः।
धर्षणं प्राणिनां दत्त्वा स्वमतेन विचेष्टसे॥', 'īdṛśais taiḥ samācārair yaśo''rthakulanāśanaiḥ
dharṣaṇaṃ prāṇināṃ dattvā svamatena viceṣṭase', null, 7025019),
('ramayana-7-25-20', 20, 'Uttara Kanda, Sarga 25, Verse 20', 'ज्ञातीन्वै धर्षयित्वेमास्त्वयानीता वराङ्गनाः।
त्वामतिक्रम्य मधुना राजन्कुम्भीनसी हृता॥', 'jñātīn vai dharṣayitvemās tvayānītā varāṅganāḥ
tvām atikramya madhunā rājan kumbhīnasī hṛtā', null, 7025020),
('ramayana-7-25-21', 21, 'Uttara Kanda, Sarga 25, Verse 21', 'रावणस्त्वब्रवीद्वाक्यं नावगच्छामि किं त्विदम्।
को वायं यस्त्वयाख्यातो मधुरित्येव नामतः॥', 'rāvaṇas tv abravīd vākyaṃ nāvagacchāmi kiṃ tv idam
ko vāyaṃ yas tvayākhyāto madhur ity eva nāmataḥ', null, 7025021),
('ramayana-7-25-22', 22, 'Uttara Kanda, Sarga 25, Verse 22', 'विभीषणस्तु संक्रुद्धो भ्रातरं वाक्यमब्रवीत्।
श्रूयतामस्य पापस्य कर्मणः फलमागतम्॥', 'vibhīṣaṇas tu saṃkruddho bhrātaraṃ vākyam abravīt
śrūyatām asya pāpasya karmaṇaḥ phalam āgatam', null, 7025022),
('ramayana-7-25-23', 23, 'Uttara Kanda, Sarga 25, Verse 23', 'मातामहस्य योऽस्माकं ज्येष्ठो भ्राता सुमालिनः।
माल्यवानिति विख्यातो वृद्धप्राज्ञो निशाचरः॥', 'mātāmahasya yo ''smākaṃ jyeṣṭho bhrātā sumālinaḥ
mālyavān iti vikhyāto vṛddhaprājño niśācaraḥ', null, 7025023),
('ramayana-7-25-24', 24, 'Uttara Kanda, Sarga 25, Verse 24', 'पितुर्ज्येष्ठो जनन्याश्च अस्माकं त्वार्यकोऽभवत्।
तस्य कुम्भीनसी नाम दुहितुर्दुहिताभवत्॥', 'pitur jyeṣṭho jananyāś ca asmākaṃ tv āryako ''bhavat
tasya kumbhīnasī nāma duhitur duhitābhavat', null, 7025024),
('ramayana-7-25-25', 25, 'Uttara Kanda, Sarga 25, Verse 25', 'मातृष्वसुरथास्माकं सा कन्या चानलोद्भवा।
भवत्यस्माकमेषा वै भ्रातॄणां धर्मतः स्वसा॥', 'mātṛṣvasur athāsmākaṃ sā kanyā cānalodbhavā
bhavaty asmākam eṣā vai bhrātṝṇāṃ dharmataḥ svasā', null, 7025025),
('ramayana-7-25-26', 26, 'Uttara Kanda, Sarga 25, Verse 26', 'सा हृता मधुना राजन्राक्षसेन बलीयसा।
यज्ञप्रवृत्ते पुत्रे ते मयि चान्तर्जलोषिते॥', 'sā hṛtā madhunā rājan rākṣasena balīyasā
yajñapravṛtte putre te mayi cāntarjaloṣite', null, 7025026),
('ramayana-7-25-27', 27, 'Uttara Kanda, Sarga 25, Verse 27', 'निहत्य राक्षसश्रेष्ठानमात्यांस्तव संमतान्।
धर्षयित्वा हृता राजन्गुप्ता ह्यन्तःपुरे तव॥', 'nihatya rākṣasaśreṣṭhān amātyāṃs tava saṃmatān
dharṣayitvā hṛtā rājan guptā hy antaḥpure tava', null, 7025027),
('ramayana-7-25-28', 28, 'Uttara Kanda, Sarga 25, Verse 28', 'श्रुत्वा त्वेतन्महाराज क्षान्तमेव हतो न सः।
यस्मादवश्यं दातव्या कन्या भर्त्रे हि दातृभिः।
अस्मिन्नेवाभिसंप्राप्तं लोके विदितमस्तु ते॥', 'śrutvā tv etan mahārāja kṣāntam eva hato na saḥ
yasmād avaśyaṃ dātavyā kanyā bhartre hi dātṛbhiḥ
asminn evābhisaṃprāptaṃ loke viditam astu te', null, 7025028),
('ramayana-7-25-29', 29, 'Uttara Kanda, Sarga 25, Verse 29', 'ततोऽब्रवीद्दशग्रीवः क्रुद्धः संरक्तलोचनः।
कल्प्यतां मे रथः शीघ्रं शूराः सज्जीभवन्तु च॥', 'tato ''bravīd daśagrīvaḥ kruddhaḥ saṃraktalocanaḥ
kalpyatāṃ me rathaḥ śīghraṃ śūrāḥ sajjībhavantu ca', null, 7025029),
('ramayana-7-25-30', 30, 'Uttara Kanda, Sarga 25, Verse 30', 'भ्राता मे कुम्भकर्णश्च ये च मुख्या निशाचराः।
वाहनान्यधिरोहन्तु नानाप्रहरणायुधाः॥', 'bhrātā me kumbhakarṇaś ca ye ca mukhyā niśācarāḥ
vāhanāny adhirohantu nānāpraharaṇāyudhāḥ', null, 7025030),
('ramayana-7-25-31', 31, 'Uttara Kanda, Sarga 25, Verse 31', 'अद्य तं समरे हत्वा मधुं रावणनिर्भयम्।
इन्द्रलोकं गमिष्यामि युद्धकाङ्क्षी सुहृद्वृतः॥', 'adya taṃ samare hatvā madhuṃ rāvaṇanirbhayam
indralokaṃ gamiṣyāmi yuddhakāṅkṣī suhṛdvṛtaḥ', null, 7025031),
('ramayana-7-25-32', 32, 'Uttara Kanda, Sarga 25, Verse 32', 'ततो विजित्य त्रिदिवं वशे स्थाप्य पुरंदरम्।
निर्वृतो विहरिष्यामि त्रैलोक्यैश्वर्यशोभितः॥', 'tato vijitya tridivaṃ vaśe sthāpya puraṃdaram
nirvṛto vihariṣyāmi trailokyaiśvaryaśobhitaḥ', null, 7025032),
('ramayana-7-25-33', 33, 'Uttara Kanda, Sarga 25, Verse 33', 'अक्षौहिणीसहस्राणि चत्वार्युग्राणि रक्षसाम्।
नानाप्रहरणान्याशु निर्ययुर्युद्धकाङ्क्षिणाम्॥', 'akṣauhiṇīsahasrāṇi catvāry ugrāṇi rakṣasām
nānāpraharaṇāny āśu niryayur yuddhakāṅkṣiṇām', null, 7025033),
('ramayana-7-25-34', 34, 'Uttara Kanda, Sarga 25, Verse 34', 'इन्द्रजित्त्वग्रतः सैन्यं सैनिकान्परिगृह्य च।
रावणो मध्यतः शूरः कुम्भकर्णश्च पृष्ठतः॥', 'indrajit tv agrataḥ sainyaṃ sainikān parigṛhya ca
rāvaṇo madhyataḥ śūraḥ kumbhakarṇaś ca pṛṣṭhataḥ', null, 7025034),
('ramayana-7-25-35', 35, 'Uttara Kanda, Sarga 25, Verse 35', 'विभीषणस्तु धर्मात्मा लङ्कायां धर्ममाचरत्।
ते तु सर्वे महाभागा ययुर्मधुपुरं प्रति॥', 'vibhīṣaṇas tu dharmātmā laṅkāyāṃ dharmam ācarat
te tu sarve mahābhāgā yayur madhupuraṃ prati', null, 7025035),
('ramayana-7-25-36', 36, 'Uttara Kanda, Sarga 25, Verse 36', 'रथैर्नागैः खरैरुष्ट्रैर्हयैर्दीप्तैर्महोरगैः।
राक्षसाः प्रययुः सर्वे कृत्वाकाशं निरन्तरम्॥', 'rathair nāgaiḥ kharair uṣṭrair hayair dīptair mahoragaiḥ
rākṣasāḥ prayayuḥ sarve kṛtvākāśaṃ nirantaram', null, 7025036),
('ramayana-7-25-37', 37, 'Uttara Kanda, Sarga 25, Verse 37', 'दैत्याश्च शतशस्तत्र कृतवैराः सुरैः सह।
रावणं प्रेक्ष्य गच्छन्तमन्वगच्छन्त पृष्ठतः॥', 'daityāś ca śataśas tatra kṛtavairāḥ suraiḥ saha
rāvaṇaṃ prekṣya gacchantam anvagacchanta pṛṣṭhataḥ', null, 7025037),
('ramayana-7-25-38', 38, 'Uttara Kanda, Sarga 25, Verse 38', 'स तु गत्वा मधुपुरं प्रविश्य च दशाननः।
न ददर्श मधुं तत्र भगिनीं तत्र दृष्टवान्॥', 'sa tu gatvā madhupuraṃ praviśya ca daśānanaḥ
na dadarśa madhuṃ tatra bhaginīṃ tatra dṛṣṭavān', null, 7025038),
('ramayana-7-25-39', 39, 'Uttara Kanda, Sarga 25, Verse 39', 'सा प्रह्वा प्राञ्जलिर्भूत्वा शिरसा पादयोर्गता।
तस्य राक्षसराजस्य त्रस्ता कुम्भीनसी स्वसा॥', 'sā prahvā prāñjalir bhūtvā śirasā pādayor gatā
tasya rākṣasarājasya trastā kumbhīnasī svasā', null, 7025039),
('ramayana-7-25-40', 40, 'Uttara Kanda, Sarga 25, Verse 40', 'तां समुत्थापयामास न भेतव्यमिति ब्रुवन्।
रावणो राक्षसश्रेष्ठः किं चापि करवाणि ते॥', 'tāṃ samutthāpayām āsa na bhetavyam iti bruvan
rāvaṇo rākṣasaśreṣṭhaḥ kiṃ cāpi karavāṇi te', null, 7025040),
('ramayana-7-25-41', 41, 'Uttara Kanda, Sarga 25, Verse 41', 'साब्रवीद्यदि मे राजन्प्रसन्नस्त्वं महाबल।
भर्तारं न ममेहाद्य हन्तुमर्हसि मानद॥', 'sābravīd yadi me rājan prasannas tvaṃ mahābala
bhartāraṃ na mamehādya hantum arhasi mānada', null, 7025041),
('ramayana-7-25-42', 42, 'Uttara Kanda, Sarga 25, Verse 42', 'सत्यवाग्भव राजेन्द्र मामवेक्षस्व याचतीम्।
त्वया ह्युक्तं महाबाहो न भेतव्यमिति स्वयम्॥', 'satyavāg bhava rājendra mām avekṣasva yācatīm
tvayā hy uktaṃ mahābāho na bhetavyam iti svayam', null, 7025042),
('ramayana-7-25-43', 43, 'Uttara Kanda, Sarga 25, Verse 43', 'रावणस्त्वब्रवीद्धृष्टः स्वसारं तत्र संस्थिताम्।
क्व चासौ तव भर्ता वै मम शीघ्रं निवेद्यताम्॥', 'rāvaṇas tv abravīd dhṛṣṭaḥ svasāraṃ tatra saṃsthitām
kva cāsau tava bhartā vai mama śīghraṃ nivedyatām', null, 7025043),
('ramayana-7-25-44', 44, 'Uttara Kanda, Sarga 25, Verse 44', 'सह तेन गमिष्यामि सुरलोकं जयाय वै।
तव कारुण्यसौहार्दान्निवृत्तोऽस्मि मधोर्वधात्॥', 'saha tena gamiṣyāmi suralokaṃ jayāya vai
tava kāruṇyasauhārdān nivṛtto ''smi madhor vadhāt', null, 7025044),
('ramayana-7-25-45', 45, 'Uttara Kanda, Sarga 25, Verse 45', 'इत्युक्ता सा प्रसुप्तं तं समुत्थाप्य निशाचरम्।
अब्रवीत्संप्रहृष्टेव राक्षसी सुविपश्चितम्॥', 'ity uktā sā prasuptaṃ taṃ samutthāpya niśācaram
abravīt saṃprahṛṣṭeva rākṣasī suvipaścitam', null, 7025045),
('ramayana-7-25-46', 46, 'Uttara Kanda, Sarga 25, Verse 46', 'एष प्राप्तो दशग्रीवो मम भ्राता निशाचरः।
सुरलोकजयाकाङ्क्षी साहाय्ये त्वां वृणोति च॥', 'eṣa prāpto daśagrīvo mama bhrātā niśācaraḥ
suralokajayākāṅkṣī sāhāyye tvāṃ vṛṇoti ca', null, 7025046),
('ramayana-7-25-47', 47, 'Uttara Kanda, Sarga 25, Verse 47', 'तदस्य त्वं सहायार्थं सबन्धुर्गच्छ राक्षस।
स्निग्धस्य भजमानस्य युक्तमर्थाय कल्पितुम्॥', 'tad asya tvaṃ sahāyārthaṃ sabandhur gaccha rākṣasa
snigdhasya bhajamānasya yuktam arthāya kalpitum', null, 7025047),
('ramayana-7-25-48', 48, 'Uttara Kanda, Sarga 25, Verse 48', 'तस्यास्तद्वचनं श्रुत्वा तथेत्याह मधुर्वचः।
ददर्श राक्षसश्रेष्ठं यथान्यायमुपेत्य सः॥', 'tasyās tad vacanaṃ śrutvā tathety āha madhur vacaḥ
dadarśa rākṣasaśreṣṭhaṃ yathānyāyam upetya saḥ', null, 7025048),
('ramayana-7-25-49', 49, 'Uttara Kanda, Sarga 25, Verse 49', 'पूजयामास धर्मेण रावणं राक्षसाधिपम्।
प्राप्तपूजो दशग्रीवो मधुवेश्मनि वीर्यवान्।
तत्र चैकां निशामुष्य गमनायोपचक्रमे॥', 'pūjayām āsa dharmeṇa rāvaṇaṃ rākṣasādhipam
prāptapūjo daśagrīvo madhuveśmani vīryavān
tatra caikāṃ niśām uṣya gamanāyopacakrame', null, 7025049),
('ramayana-7-25-50', 50, 'Uttara Kanda, Sarga 25, Verse 50', 'ततः कैलासमासाद्य शैलं वैश्रवणालयम्।
राक्षसेन्द्रो महेन्द्राभः सेनामुपनिवेशयत्॥', 'tataḥ kailāsam āsādya śailaṃ vaiśravaṇālayam
rākṣasendro mahendrābhaḥ senām upaniveśayat', null, 7025050)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 26 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-26-1', 1, 'Uttara Kanda, Sarga 26, Verse 1', 'स तु तत्र दशग्रीवः सह सैन्येन वीर्यवान्।
अस्तं प्राप्ते दिनकरे निवासं समरोचयत्॥', 'sa tu tatra daśagrīvaḥ saha sainyena vīryavān
astaṃ prāpte dinakare nivāsaṃ samarocayat', null, 7026001),
('ramayana-7-26-2', 2, 'Uttara Kanda, Sarga 26, Verse 2', 'उदिते विमले चन्द्रे तुल्यपर्वतवर्चसि।
स ददर्श गुणांस्तत्र चन्द्रपादोपशोभितान्॥', 'udite vimale candre tulyaparvatavarcasi
sa dadarśa guṇāṃs tatra candrapādopaśobhitān', null, 7026002),
('ramayana-7-26-3', 3, 'Uttara Kanda, Sarga 26, Verse 3', 'कर्णिकारवनैर्दिव्यैः कदम्बगहनैस्तथा।
पद्मिनीभिश्च फुल्लाभिर्मन्दाकिन्या जलैरपि॥', 'karṇikāravanair divyaiḥ kadambagahanais tathā
padminībhiś ca phullābhir mandākinyā jalair api', null, 7026003),
('ramayana-7-26-4', 4, 'Uttara Kanda, Sarga 26, Verse 4', 'घण्टानामिव संनादः शुश्रुवे मधुरस्वनः।
अप्सरोगणसंघनां गायतां धनदालये॥', 'ghaṇṭānām iva saṃnādaḥ śuśruve madhurasvanaḥ
apsarogaṇasaṃghanāṃ gāyatāṃ dhanadālaye', null, 7026004),
('ramayana-7-26-5', 5, 'Uttara Kanda, Sarga 26, Verse 5', 'पुष्पवर्षाणि मुञ्चन्तो नगाः पवनताडिताः।
शैलं तं वासयन्तीव मधुमाधवगन्धिनः॥', 'puṣpavarṣāṇi muñcanto nagāḥ pavanatāḍitāḥ
śailaṃ taṃ vāsayantīva madhumādhavagandhinaḥ', null, 7026005),
('ramayana-7-26-6', 6, 'Uttara Kanda, Sarga 26, Verse 6', 'मधुपुष्परजःपृक्तं गन्धमादाय पुष्कलम्।
प्रववौ वर्धयन्कामं रावणस्य सुखोऽनिलः॥', 'madhupuṣparajaḥpṛktaṃ gandham ādāya puṣkalam
pravavau vardhayan kāmaṃ rāvaṇasya sukho ''nilaḥ', null, 7026006),
('ramayana-7-26-7', 7, 'Uttara Kanda, Sarga 26, Verse 7', 'गेयात्पुष्पसमृद्ध्या च शैत्याद्वायोर्गुणैर्गिरेः।
प्रवृत्तायां रजन्यां च चन्द्रस्योदयनेन च॥', 'geyāt puṣpasamṛddhyā ca śaityād vāyor guṇair gireḥ
pravṛttāyāṃ rajanyāṃ ca candrasyodayanena ca', null, 7026007),
('ramayana-7-26-8', 8, 'Uttara Kanda, Sarga 26, Verse 8', 'रावणः सुमहावीर्यः कामबाणवशं गतः।
विनिश्वस्य विनिश्वस्य शशिनं समवैक्षत॥', 'rāvaṇaḥ sumahāvīryaḥ kāmabāṇavaśaṃ gataḥ
viniśvasya viniśvasya śaśinaṃ samavaikṣata', null, 7026008),
('ramayana-7-26-9', 9, 'Uttara Kanda, Sarga 26, Verse 9', 'एतस्मिन्नन्तरे तत्र दिव्यपुष्पविभूषिता।
सर्वाप्सरोवरा रम्भा पूर्णचन्द्रनिभानना॥', 'etasminn antare tatra divyapuṣpavibhūṣitā
sarvāpsarovarā rambhā pūrṇacandranibhānanā', null, 7026009),
('ramayana-7-26-10', 10, 'Uttara Kanda, Sarga 26, Verse 10', 'कृतैर्विशेषकैरार्द्रैः षडर्तुकुसुमोत्सवैः।
नीलं सतोयमेघाभं वस्त्रं समवगुण्ठिता॥', 'kṛtair viśeṣakair ārdraiḥ ṣaḍartukusumotsavaiḥ
nīlaṃ satoyameghābhaṃ vastraṃ samavaguṇṭhitā', null, 7026010),
('ramayana-7-26-11', 11, 'Uttara Kanda, Sarga 26, Verse 11', 'यस्य वक्त्रं शशिनिभं भ्रुवौ चापनिभे शुभे।
ऊरू करिकराकारौ करौ पल्लवकोमलौ।
सैन्यमध्येन गच्छन्ती रावणेनोपलक्षिता॥', 'yasya vaktraṃ śaśinibhaṃ bhruvau cāpanibhe śubhe
ūrū karikarākārau karau pallavakomalau
sainyamadhyena gacchantī rāvaṇenopalakṣitā', null, 7026011),
('ramayana-7-26-12', 12, 'Uttara Kanda, Sarga 26, Verse 12', 'तां समुत्थाय रक्षेन्द्रः कामबाणबलार्दितः।
करे गृहीत्वा गच्छन्तीं स्मयमानोऽभ्यभाषत॥', 'tāṃ samutthāya rakṣendraḥ kāmabāṇabalārditaḥ
kare gṛhītvā gacchantīṃ smayamāno ''bhyabhāṣata', null, 7026012),
('ramayana-7-26-13', 13, 'Uttara Kanda, Sarga 26, Verse 13', 'क्व गच्छसि वरारोहे कां सिद्धिं भजसे स्वयम्।
कस्याभ्युदयकालोऽयं यस्त्वां समुपभोक्ष्यते॥', 'kva gacchasi varārohe kāṃ siddhiṃ bhajase svayam
kasyābhyudayakālo ''yaṃ yas tvāṃ samupabhokṣyate', null, 7026013),
('ramayana-7-26-14', 14, 'Uttara Kanda, Sarga 26, Verse 14', 'तवाननरसस्याद्य पद्मोत्पलसुगन्धिनः।
सुधामृतरसस्येव कोऽद्य तृप्तिं गमिष्यति॥', 'tavānanarasasyādya padmotpalasugandhinaḥ
sudhāmṛtarasasyeva ko ''dya tṛptiṃ gamiṣyati', null, 7026014),
('ramayana-7-26-15', 15, 'Uttara Kanda, Sarga 26, Verse 15', 'स्वर्णकुम्भनिभौ पीनौ शुभौ भीरु निरन्तरौ।
कस्योरस्थलसंस्पर्शं दास्यतस्ते कुचाविमौ॥', 'svarṇakumbhanibhau pīnau śubhau bhīru nirantarau
kasyorasthalasaṃsparśaṃ dāsyatas te kucāv imau', null, 7026015),
('ramayana-7-26-16', 16, 'Uttara Kanda, Sarga 26, Verse 16', 'सुवर्णचक्रप्रतिमं स्वर्णदामचितं पृथु।
अध्यारोक्ष्यति कस्तेऽद्य स्वर्गं जघनरूपिणम्॥', 'suvarṇacakrapratimaṃ svarṇadāmacitaṃ pṛthu
adhyārokṣyati kas te ''dya svargaṃ jaghanarūpiṇam', null, 7026016),
('ramayana-7-26-17', 17, 'Uttara Kanda, Sarga 26, Verse 17', 'मद्विशिष्टः पुमान्कोऽन्यः शक्रो विष्णुरथाश्विनौ।
मामतीत्य हि यस्य त्वं यासि भीरु न शोभनम्॥', 'madviśiṣṭaḥ pumān ko ''nyaḥ śakro viṣṇur athāśvinau
mām atītya hi yasya tvaṃ yāsi bhīru na śobhanam', null, 7026017),
('ramayana-7-26-18', 18, 'Uttara Kanda, Sarga 26, Verse 18', 'विश्रम त्वं पृथुश्रोणि शिलातलमिदं शुभम्।
त्रैलोक्ये यः प्रभुश्चैव तुल्यो मम न विद्यते॥', 'viśrama tvaṃ pṛthuśroṇi śilātalam idaṃ śubham
trailokye yaḥ prabhuś caiva tulyo mama na vidyate', null, 7026018),
('ramayana-7-26-19', 19, 'Uttara Kanda, Sarga 26, Verse 19', 'तदेष प्राञ्जलिः प्रह्वो याचते त्वां दशाननः।
यः प्रभुश्चापि भर्ता च त्रैलोक्यस्य भजस्व माम्॥', 'tad eṣa prāñjaliḥ prahvo yācate tvāṃ daśānanaḥ
yaḥ prabhuś cāpi bhartā ca trailokyasya bhajasva mām', null, 7026019),
('ramayana-7-26-20', 20, 'Uttara Kanda, Sarga 26, Verse 20', 'एवमुक्ताब्रवीद्रम्भा वेपमाना कृताञ्जलिः।
प्रसीद नार्हसे वक्तुमीदृशं त्वं हि मे गुरुः॥', 'evam uktābravīd rambhā vepamānā kṛtāñjaliḥ
prasīda nārhase vaktum īdṛśaṃ tvaṃ hi me guruḥ', null, 7026020),
('ramayana-7-26-21', 21, 'Uttara Kanda, Sarga 26, Verse 21', 'अन्येभ्योऽपि त्वया रक्ष्या प्राप्नुयां धर्षणं यदि।
धर्मतश्च स्नुषा तेऽहं तत्त्वमेतद्ब्रवीमि ते॥', 'anyebhyo ''pi tvayā rakṣyā prāpnuyāṃ dharṣaṇaṃ yadi
dharmataś ca snuṣā te ''haṃ tattvam etad bravīmi te', null, 7026021),
('ramayana-7-26-22', 22, 'Uttara Kanda, Sarga 26, Verse 22', 'अब्रवीत्तां दशग्रीवश्चरणाधोमुखीं स्थिताम्।
सुतस्य यदि मे भार्या ततस्त्वं मे स्नुषा भवेः॥', 'abravīt tāṃ daśagrīvaś caraṇādhomukhīṃ sthitām
sutasya yadi me bhāryā tatas tvaṃ me snuṣā bhaveḥ', null, 7026022),
('ramayana-7-26-23', 23, 'Uttara Kanda, Sarga 26, Verse 23', 'बाढमित्येव सा रम्भा प्राह रावणमुत्तरम्।
धर्मतस्ते सुतस्याहं भार्या राक्षसपुंगव॥', 'bāḍham ity eva sā rambhā prāha rāvaṇam uttaram
dharmatas te sutasyāhaṃ bhāryā rākṣasapuṃgava', null, 7026023),
('ramayana-7-26-24', 24, 'Uttara Kanda, Sarga 26, Verse 24', 'पुत्रः प्रियतरः प्राणैर्भ्रातुर्वैश्रवणस्य ते।
ख्यातो यस्त्रिषु लोकेषु नलकूबर इत्यसौ॥', 'putraḥ priyataraḥ prāṇair bhrātur vaiśravaṇasya te
khyāto yas triṣu lokeṣu nalakūbara ity asau', null, 7026024),
('ramayana-7-26-25', 25, 'Uttara Kanda, Sarga 26, Verse 25', 'धर्मतो यो भवेद्विप्रः क्षत्रियो वीर्यतो भवेत्।
क्रोधाद्यश्च भवेदग्निः क्षान्त्या च वसुधासमः॥', 'dharmato yo bhaved vipraḥ kṣatriyo vīryato bhavet
krodhād yaś ca bhaved agniḥ kṣāntyā ca vasudhāsamaḥ', null, 7026025),
('ramayana-7-26-26', 26, 'Uttara Kanda, Sarga 26, Verse 26', 'तस्यास्मि कृतसंकेता लोकपालसुतस्य वै।
तमुद्दिश्य च मे सर्वं विभूषणमिदं कृतम्॥', 'tasyāsmi kṛtasaṃketā lokapālasutasya vai
tam uddiśya ca me sarvaṃ vibhūṣaṇam idaṃ kṛtam', null, 7026026),
('ramayana-7-26-27', 27, 'Uttara Kanda, Sarga 26, Verse 27', 'यस्य तस्य हि नान्यस्य भावो मां प्रति तिष्ठति।
तेन सत्येन मां राजन्मोक्तुमर्हस्यरिंदम॥', 'yasya tasya hi nānyasya bhāvo māṃ prati tiṣṭhati
tena satyena māṃ rājan moktum arhasy ariṃdama', null, 7026027),
('ramayana-7-26-28', 28, 'Uttara Kanda, Sarga 26, Verse 28', 'स हि तिष्ठति धर्मात्मा साम्प्रतं मत्समुत्सुकः।
तन्न विघ्नं सुतस्येह कर्तुमर्हसि मुञ्च माम्॥', 'sa hi tiṣṭhati dharmātmā sāmprataṃ matsamutsukaḥ
tan na vighnaṃ sutasyeha kartum arhasi muñca mām', null, 7026028),
('ramayana-7-26-29', 29, 'Uttara Kanda, Sarga 26, Verse 29', 'सद्भिराचरितं मार्गं गच्छ राक्षसपुंगव।
माननीयो मया हि त्वं लालनीया तथास्मि ते॥', 'sadbhir ācaritaṃ mārgaṃ gaccha rākṣasapuṃgava
mānanīyo mayā hi tvaṃ lālanīyā tathāsmi te', null, 7026029),
('ramayana-7-26-30', 30, 'Uttara Kanda, Sarga 26, Verse 30', 'एवं ब्रुवाणां रम्भां तां धर्मार्थसहितं वचः।
निर्भर्त्स्य राक्षसो मोहात्प्रतिगृह्य बलाद्बली।
काममोहाभिसंरब्धो मैथुनायोपचक्रमे॥', 'evaṃ bruvāṇāṃ rambhāṃ tāṃ dharmārthasahitaṃ vacaḥ
nirbhartsya rākṣaso mohāt pratigṛhya balād balī
kāmamohābhisaṃrabdho maithunāyopacakrame', null, 7026030),
('ramayana-7-26-31', 31, 'Uttara Kanda, Sarga 26, Verse 31', 'सा विमुक्ता ततो रम्भा भ्रष्टमाल्यविभूषणा।
गजेन्द्राक्रीडमथिता नदीवाकुलतां गता॥', 'sā vimuktā tato rambhā bhraṣṭamālyavibhūṣaṇā
gajendrākrīḍamathitā nadīvākulatāṃ gatā', null, 7026031),
('ramayana-7-26-32', 32, 'Uttara Kanda, Sarga 26, Verse 32', 'सा वेपमाना लज्जन्ती भीता करकृताञ्जलिः।
नलकूबरमासाद्य पादयोर्निपपात ह॥', 'sā vepamānā lajjantī bhītā karakṛtāñjaliḥ
nalakūbaram āsādya pādayor nipapāta ha', null, 7026032),
('ramayana-7-26-33', 33, 'Uttara Kanda, Sarga 26, Verse 33', 'तदवस्थां च तां दृष्ट्वा महात्मा नलकूबरः।
अब्रवीत्किमिदं भद्रे पादयोः पतितासि मे॥', 'tadavasthāṃ ca tāṃ dṛṣṭvā mahātmā nalakūbaraḥ
abravīt kim idaṃ bhadre pādayoḥ patitāsi me', null, 7026033),
('ramayana-7-26-34', 34, 'Uttara Kanda, Sarga 26, Verse 34', 'सा तु निश्वसमाना च वेपमानाथ साञ्जलिः।
तस्मै सर्वं यथातथ्यमाख्यातुमुपचक्रमे॥', 'sā tu niśvasamānā ca vepamānātha sāñjaliḥ
tasmai sarvaṃ yathātathyam ākhyātum upacakrame', null, 7026034),
('ramayana-7-26-35', 35, 'Uttara Kanda, Sarga 26, Verse 35', 'एष देव दशग्रीवः प्राप्तो गन्तुं त्रिविष्टपम्।
तेन सैन्यसहायेन निशेह परिणाम्यते॥', 'eṣa deva daśagrīvaḥ prāpto gantuṃ triviṣṭapam
tena sainyasahāyena niśeha pariṇāmyate', null, 7026035),
('ramayana-7-26-36', 36, 'Uttara Kanda, Sarga 26, Verse 36', 'आयान्ती तेन दृष्टास्मि त्वत्सकाशमरिंदम।
गृहीत्वा तेन पृष्टास्मि कस्य त्वमिति रक्षसा॥', 'āyāntī tena dṛṣṭāsmi tvatsakāśam ariṃdama
gṛhītvā tena pṛṣṭāsmi kasya tvam iti rakṣasā', null, 7026036),
('ramayana-7-26-37', 37, 'Uttara Kanda, Sarga 26, Verse 37', 'मया तु सर्वं यत्सत्यं तद्धि तस्मै निवेदितम्।
काममोहाभिभूतात्मा नाश्रौषीत्तद्वचो मम॥', 'mayā tu sarvaṃ yat satyaṃ tad dhi tasmai niveditam
kāmamohābhibhūtātmā nāśrauṣīt tad vaco mama', null, 7026037),
('ramayana-7-26-38', 38, 'Uttara Kanda, Sarga 26, Verse 38', 'याच्यमानो मया देव स्नुषा तेऽहमिति प्रभो।
तत्सर्वं पृष्ठतः कृत्वा बलात्तेनास्मि धर्षिता॥', 'yācyamāno mayā deva snuṣā te ''ham iti prabho
tat sarvaṃ pṛṣṭhataḥ kṛtvā balāt tenāsmi dharṣitā', null, 7026038),
('ramayana-7-26-39', 39, 'Uttara Kanda, Sarga 26, Verse 39', 'एवं त्वमपराधं मे क्षन्तुमर्हसि मानद।
न हि तुल्यं बलं सौम्य स्त्रियाश्च पुरुषस्य च॥', 'evaṃ tvam aparādhaṃ me kṣantum arhasi mānada
na hi tulyaṃ balaṃ saumya striyāś ca puruṣasya ca', null, 7026039),
('ramayana-7-26-40', 40, 'Uttara Kanda, Sarga 26, Verse 40', 'एवं श्रुत्वा तु संक्रुद्धस्तदा वैश्वरणात्मजः।
धर्षणां तां परां श्रुत्वा ध्यानं संप्रविवेश ह॥', 'evaṃ śrutvā tu saṃkruddhas tadā vaiśvaraṇātmajaḥ
dharṣaṇāṃ tāṃ parāṃ śrutvā dhyānaṃ saṃpraviveśa ha', null, 7026040),
('ramayana-7-26-41', 41, 'Uttara Kanda, Sarga 26, Verse 41', 'तस्य तत्कर्म विज्ञाय तदा वैश्रवणात्मजः।
मुहूर्ताद्रोषताम्राक्षस्तोयं जग्राह पाणिना॥', 'tasya tat karma vijñāya tadā vaiśravaṇātmajaḥ
muhūrtād roṣatāmrākṣas toyaṃ jagrāha pāṇinā', null, 7026041),
('ramayana-7-26-42', 42, 'Uttara Kanda, Sarga 26, Verse 42', 'गृहीत्वा सलिलं दिव्यमुपस्पृश्य यथाविधि।
उत्ससर्ज तदा शापं राक्षसेन्द्राय दारुणम्॥', 'gṛhītvā salilaṃ divyam upaspṛśya yathāvidhi
utsasarja tadā śāpaṃ rākṣasendrāya dāruṇam', null, 7026042),
('ramayana-7-26-43', 43, 'Uttara Kanda, Sarga 26, Verse 43', 'अकामा तेन यस्मात्त्वं बलाद्भद्रे प्रधर्षिता।
तस्मात्स युवतीमन्यां नाकामामुपयास्यति॥', 'akāmā tena yasmāt tvaṃ balād bhadre pradharṣitā
tasmāt sa yuvatīm anyāṃ nākāmām upayāsyati', null, 7026043),
('ramayana-7-26-44', 44, 'Uttara Kanda, Sarga 26, Verse 44', 'यदा त्वकामां कामार्तो धर्षयिष्यति योषितम्।
मूर्धा तु सप्तधा तस्य शकलीभविता तदा॥', 'yadā tv akāmāṃ kāmārto dharṣayiṣyati yoṣitam
mūrdhā tu saptadhā tasya śakalībhavitā tadā', null, 7026044),
('ramayana-7-26-45', 45, 'Uttara Kanda, Sarga 26, Verse 45', 'तस्मिन्नुदाहृते शापे ज्वलिताग्निसमप्रभे।
देवदुन्दुभयो नेदुः पुष्पवृष्टिश्च खाच्च्युता॥', 'tasminn udāhṛte śāpe jvalitāgnisamaprabhe
devadundubhayo neduḥ puṣpavṛṣṭiś ca khāc cyutā', null, 7026045),
('ramayana-7-26-46', 46, 'Uttara Kanda, Sarga 26, Verse 46', 'प्रजापतिमुखाश्चापि सर्वे देवाः प्रहर्षिताः।
ज्ञात्वा लोकगतिं सर्वां तस्य मृत्युं च रक्षसः॥', 'prajāpatimukhāś cāpi sarve devāḥ praharṣitāḥ
jñātvā lokagatiṃ sarvāṃ tasya mṛtyuṃ ca rakṣasaḥ', null, 7026046),
('ramayana-7-26-47', 47, 'Uttara Kanda, Sarga 26, Verse 47', 'श्रुत्वा तु स दशग्रीवस्तं शापं रोमहर्षणम्।
नारीषु मैथुनं भावं नाकामास्वभ्यरोचयत्॥', 'śrutvā tu sa daśagrīvas taṃ śāpaṃ romaharṣaṇam
nārīṣu maithunaṃ bhāvaṃ nākāmāsv abhyarocayat', null, 7026047)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 27 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-27-1', 1, 'Uttara Kanda, Sarga 27, Verse 1', 'कैलासं लङ्घयित्वाथ दशग्रीवः सराक्षसः।
आससाद महातेजा इन्द्रलोकं निशाचरः॥', 'kailāsaṃ laṅghayitvātha daśagrīvaḥ sarākṣasaḥ
āsasāda mahātejā indralokaṃ niśācaraḥ', null, 7027001),
('ramayana-7-27-2', 2, 'Uttara Kanda, Sarga 27, Verse 2', 'तस्य राक्षससैन्यस्य समन्तादुपयास्यतः।
देवलोकं ययौ शब्दो भिद्यमानार्णवोपमः॥', 'tasya rākṣasasainyasya samantād upayāsyataḥ
devalokaṃ yayau śabdo bhidyamānārṇavopamaḥ', null, 7027002),
('ramayana-7-27-3', 3, 'Uttara Kanda, Sarga 27, Verse 3', 'श्रुत्वा तु रावणं प्राप्तमिन्द्रः संचलितासनः।
अब्रवीत्तत्र तान्देवान्सर्वानेव समागतान्॥', 'śrutvā tu rāvaṇaṃ prāptam indraḥ saṃcalitāsanaḥ
abravīt tatra tān devān sarvān eva samāgatān', null, 7027003),
('ramayana-7-27-4', 4, 'Uttara Kanda, Sarga 27, Verse 4', 'आदित्यान्सवसून्रुद्रान्विश्वान्साध्यान्मरुद्गणान्।
सज्जीभवत युद्धार्थं रावणस्य दुरात्मनः॥', 'ādityān savasūn rudrān viśvān sādhyān marudgaṇān
sajjībhavata yuddhārthaṃ rāvaṇasya durātmanaḥ', null, 7027004),
('ramayana-7-27-5', 5, 'Uttara Kanda, Sarga 27, Verse 5', 'एवमुक्तास्तु शक्रेण देवाः शक्रसमा युधि।
संनह्यन्त महासत्त्वा युद्धश्रद्धासमन्विताः॥', 'evam uktās tu śakreṇa devāḥ śakrasamā yudhi
saṃnahyanta mahāsattvā yuddhaśraddhāsamanvitāḥ', null, 7027005),
('ramayana-7-27-6', 6, 'Uttara Kanda, Sarga 27, Verse 6', 'स तु दीनः परित्रस्तो महेन्द्रो रावणं प्रति।
विष्णोः समीपमागत्य वाक्यमेतदुवाच ह॥', 'sa tu dīnaḥ paritrasto mahendro rāvaṇaṃ prati
viṣṇoḥ samīpam āgatya vākyam etad uvāca ha', null, 7027006),
('ramayana-7-27-7', 7, 'Uttara Kanda, Sarga 27, Verse 7', 'विष्णो कथं करिष्यामो महावीर्यपराक्रम।
असौ हि बलवान्रक्षो युद्धार्थमभिवर्तते॥', 'viṣṇo kathaṃ kariṣyāmo mahāvīryaparākrama
asau hi balavān rakṣo yuddhārtham abhivartate', null, 7027007),
('ramayana-7-27-8', 8, 'Uttara Kanda, Sarga 27, Verse 8', 'वरप्रदानाद्बलवान्न खल्वन्येन हेतुना।
तच्च सत्यं हि कर्तव्यं वाक्यं देव प्रजापतेः॥', 'varapradānād balavān na khalv anyena hetunā
tac ca satyaṃ hi kartavyaṃ vākyaṃ deva prajāpateḥ', null, 7027008),
('ramayana-7-27-9', 9, 'Uttara Kanda, Sarga 27, Verse 9', 'तद्यथा नमुचिर्वृत्रो बलिर्नरकशम्बरौ।
त्वन्मतं समवष्टभ्य यथा दग्धास्तथा कुरु॥', 'tad yathā namucir vṛtro balir narakaśambarau
tvan mataṃ samavaṣṭabhya yathā dagdhās tathā kuru', null, 7027009),
('ramayana-7-27-10', 10, 'Uttara Kanda, Sarga 27, Verse 10', 'न ह्यन्यो देव देवानामापत्सु सुमहाबल।
गतिः परायणं वास्ति त्वामृते पुरुषोत्तम॥', 'na hy anyo deva devānām āpatsu sumahābala
gatiḥ parāyaṇaṃ vāsti tvām ṛte puruṣottama', null, 7027010),
('ramayana-7-27-11', 11, 'Uttara Kanda, Sarga 27, Verse 11', 'त्वं हि नारायणः श्रीमान्पद्मनाभः सनातनः।
त्वयाहं स्थापितश्चैव देवराज्ये सनातने॥', 'tvaṃ hi nārāyaṇaḥ śrīmān padmanābhaḥ sanātanaḥ
tvayāhaṃ sthāpitaś caiva devarājye sanātane', null, 7027011),
('ramayana-7-27-12', 12, 'Uttara Kanda, Sarga 27, Verse 12', 'तदाख्याहि यथातत्त्वं देवदेव मम स्वयम्।
असिचक्रसहायस्त्वं युध्यसे संयुगे रिपुम्॥', 'tad ākhyāhi yathātattvaṃ devadeva mama svayam
asicakrasahāyas tvaṃ yudhyase saṃyuge ripum', null, 7027012),
('ramayana-7-27-13', 13, 'Uttara Kanda, Sarga 27, Verse 13', 'एवमुक्तः स शक्रेण देवो नारायणः प्रभुः।
अब्रवीन्न परित्रासः कार्यस्ते श्रूयतां च मे॥', 'evam uktaḥ sa śakreṇa devo nārāyaṇaḥ prabhuḥ
abravīn na paritrāsaḥ kāryas te śrūyatāṃ ca me', null, 7027013),
('ramayana-7-27-14', 14, 'Uttara Kanda, Sarga 27, Verse 14', 'न तावदेष दुर्वृत्तः शक्यो दैवतदानवैः।
हन्तुं युधि समासाद्य वरदानेन दुर्जयः॥', 'na tāvad eṣa durvṛttaḥ śakyo daivatadānavaiḥ
hantuṃ yudhi samāsādya varadānena durjayaḥ', null, 7027014),
('ramayana-7-27-15', 15, 'Uttara Kanda, Sarga 27, Verse 15', 'सर्वथा तु महत्कर्म करिष्यति बलोत्कटः।
रक्षः पुत्रसहायोऽसौ दृष्टमेतन्निसर्गतः॥', 'sarvathā tu mahat karma kariṣyati balotkaṭaḥ
rakṣaḥ putrasahāyo ''sau dṛṣṭam etan nisargataḥ', null, 7027015),
('ramayana-7-27-16', 16, 'Uttara Kanda, Sarga 27, Verse 16', 'ब्रवीषि यत्तु मां शक्र संयुगे योत्स्यसीति ह।
नैवाहं प्रतियोत्स्ये तं रावणं राक्षसाधिपम्॥', 'bravīṣi yat tu māṃ śakra saṃyuge yotsyasīti ha
naivāhaṃ pratiyotsye taṃ rāvaṇaṃ rākṣasādhipam', null, 7027016),
('ramayana-7-27-17', 17, 'Uttara Kanda, Sarga 27, Verse 17', 'अनिहत्य रिपुं विष्णुर्न हि प्रतिनिवर्तते।
दुर्लभश्चैष कामोऽद्य वरमासाद्य राक्षसे॥', 'anihatya ripuṃ viṣṇur na hi pratinivartate
durlabhaś caiṣa kāmo ''dya varam āsādya rākṣase', null, 7027017),
('ramayana-7-27-18', 18, 'Uttara Kanda, Sarga 27, Verse 18', 'प्रतिजानामि देवेन्द्र त्वत्समीपं शतक्रतो।
राक्षसस्याहमेवास्य भविता मृत्युकारणम्॥', 'pratijānāmi devendra tvatsamīpaṃ śatakrato
rākṣasasyāham evāsya bhavitā mṛtyukāraṇam', null, 7027018),
('ramayana-7-27-19', 19, 'Uttara Kanda, Sarga 27, Verse 19', 'अहमेनं वधिष्यामि रावणं ससुतं युधि।
देवतास्तोषयिष्यामि ज्ञात्वा कालमुपस्थितम्॥', 'aham enaṃ vadhiṣyāmi rāvaṇaṃ sasutaṃ yudhi
devatās toṣayiṣyāmi jñātvā kālam upasthitam', null, 7027019),
('ramayana-7-27-20', 20, 'Uttara Kanda, Sarga 27, Verse 20', 'एतस्मिन्नन्तरे नादः शुश्रुवे रजनीक्षये।
तस्य रावणसैन्यस्य प्रयुद्धस्य समन्ततः॥', 'etasminn antare nādaḥ śuśruve rajanīkṣaye
tasya rāvaṇasainyasya prayuddhasya samantataḥ', null, 7027020),
('ramayana-7-27-21', 21, 'Uttara Kanda, Sarga 27, Verse 21', 'अथ युद्धं समभवद्देवराक्षसयोस्तदा।
घोरं तुमुलनिर्ह्रादं नानाप्रहरणायुधम्॥', 'atha yuddhaṃ samabhavad devarākṣasayos tadā
ghoraṃ tumulanirhrādaṃ nānāpraharaṇāyudham', null, 7027021),
('ramayana-7-27-22', 22, 'Uttara Kanda, Sarga 27, Verse 22', 'एतस्मिन्नन्तरे शूरा राक्षसा घोरदर्शनाः।
युद्धार्थमभ्यधावन्त सचिवा रावणाज्ञया॥', 'etasminn antare śūrā rākṣasā ghoradarśanāḥ
yuddhārtham abhyadhāvanta sacivā rāvaṇājñayā', null, 7027022),
('ramayana-7-27-23', 23, 'Uttara Kanda, Sarga 27, Verse 23', 'मारीचश्च प्रहस्तश्च महापार्श्वमहोदरौ।
अकम्पनो निकुम्भश्च शुकः सारण एव च॥', 'mārīcaś ca prahastaś ca mahāpārśvamahodarau
akampano nikumbhaś ca śukaḥ sāraṇa eva ca', null, 7027023),
('ramayana-7-27-24', 24, 'Uttara Kanda, Sarga 27, Verse 24', 'संह्रादिर्धूमकेतुश्च महादंष्ट्रो महामुखः।
जम्बुमाली महामाली विरूपाक्षश्च राक्षसः॥', 'saṃhrādir dhūmaketuś ca mahādaṃṣṭro mahāmukhaḥ
jambumālī mahāmālī virūpākṣaś ca rākṣasaḥ', null, 7027024),
('ramayana-7-27-25', 25, 'Uttara Kanda, Sarga 27, Verse 25', 'एतैः सर्वैर्महावीर्यैर्वृतो राक्षसपुंगवः।
रावणस्यार्यकः सैन्यं सुमाली प्रविवेश ह॥', 'etaiḥ sarvair mahāvīryair vṛto rākṣasapuṃgavaḥ
rāvaṇasyāryakaḥ sainyaṃ sumālī praviveśa ha', null, 7027025),
('ramayana-7-27-26', 26, 'Uttara Kanda, Sarga 27, Verse 26', 'स हि देवगणान्सर्वान्नानाप्रहरणैः शितैः।
विध्वंसयति संक्रुद्धः सह तैः क्षणदाचरैः॥', 'sa hi devagaṇān sarvān nānāpraharaṇaiḥ śitaiḥ
vidhvaṃsayati saṃkruddhaḥ saha taiḥ kṣaṇadācaraiḥ', null, 7027026),
('ramayana-7-27-27', 27, 'Uttara Kanda, Sarga 27, Verse 27', 'एतस्मिन्नन्तरे शूरो वसूनामष्टमो वसुः।
सावित्र इति विख्यातः प्रविवेश महारणम्॥', 'etasminn antare śūro vasūnām aṣṭamo vasuḥ
sāvitra iti vikhyātaḥ praviveśa mahāraṇam', null, 7027027),
('ramayana-7-27-28', 28, 'Uttara Kanda, Sarga 27, Verse 28', 'ततो युद्धं समभवत्सुराणां राक्षसैः सह।
क्रुद्धानां रक्षसां कीर्तिं समरेष्वनिवर्तिनाम्॥', 'tato yuddhaṃ samabhavat surāṇāṃ rākṣasaiḥ saha
kruddhānāṃ rakṣasāṃ kīrtiṃ samareṣv anivartinām', null, 7027028),
('ramayana-7-27-29', 29, 'Uttara Kanda, Sarga 27, Verse 29', 'ततस्ते राक्षसाः शूरा देवांस्तान्समरे स्थितान्।
नानाप्रहरणैर्घोरैर्जघ्नुः शतसहस्रशः॥', 'tatas te rākṣasāḥ śūrā devāṃs tān samare sthitān
nānāpraharaṇair ghorair jaghnuḥ śatasahasraśaḥ', null, 7027029),
('ramayana-7-27-30', 30, 'Uttara Kanda, Sarga 27, Verse 30', 'सुरास्तु राक्षसान्घोरान्महावीर्यान्स्वतेजसा।
समरे विविधैः शस्त्रैरनयन्यमसादनम्॥', 'surās tu rākṣasān ghorān mahāvīryān svatejasā
samare vividhaiḥ śastrair anayan yamasādanam', null, 7027030),
('ramayana-7-27-31', 31, 'Uttara Kanda, Sarga 27, Verse 31', 'एतस्मिन्नन्तरे शूरः सुमाली नाम राक्षसः।
नानाप्रहरणैः क्रुद्धो रणमेवाभ्यवर्तत॥', 'etasminn antare śūraḥ sumālī nāma rākṣasaḥ
nānāpraharaṇaiḥ kruddho raṇam evābhyavartata', null, 7027031),
('ramayana-7-27-32', 32, 'Uttara Kanda, Sarga 27, Verse 32', 'देवानां तद्बलं सर्वं नानाप्रहरणैः शितैः।
विध्वंसयति संक्रुद्धो वायुर्जलधरानिव॥', 'devānāṃ tad balaṃ sarvaṃ nānāpraharaṇaiḥ śitaiḥ
vidhvaṃsayati saṃkruddho vāyur jaladharān iva', null, 7027032),
('ramayana-7-27-33', 33, 'Uttara Kanda, Sarga 27, Verse 33', 'ते महाबाणवर्षैश्च शूलैः प्रासैश्च दारुणैः।
पीड्यमानाः सुराः सर्वे न व्यतिष्ठन्समाहिताः॥', 'te mahābāṇavarṣaiś ca śūlaiḥ prāsaiś ca dāruṇaiḥ
pīḍyamānāḥ surāḥ sarve na vyatiṣṭhan samāhitāḥ', null, 7027033),
('ramayana-7-27-34', 34, 'Uttara Kanda, Sarga 27, Verse 34', 'ततो विद्राव्यमाणेषु त्रिदशेषु सुमालिना।
वसूनामष्टमो देवः सावित्रो व्यवतिष्ठत॥', 'tato vidrāvyamāṇeṣu tridaśeṣu sumālinā
vasūnām aṣṭamo devaḥ sāvitro vyavatiṣṭhata', null, 7027034),
('ramayana-7-27-35', 35, 'Uttara Kanda, Sarga 27, Verse 35', 'संवृतः स्वैरनीकैस्तु प्रहरन्तं निशाचरम्।
विक्रमेण महातेजा वारयामास संयुगे॥', 'saṃvṛtaḥ svair anīkais tu praharantaṃ niśācaram
vikrameṇa mahātejā vārayām āsa saṃyuge', null, 7027035),
('ramayana-7-27-36', 36, 'Uttara Kanda, Sarga 27, Verse 36', 'सुमत्तयोस्तयोरासीद्युद्धं लोके सुदारुणम्।
सुमालिनो वसोश्चैव समरेष्वनिवर्तिनोः॥', 'sumattayos tayor āsīd yuddhaṃ loke sudāruṇam
sumālino vasoś caiva samareṣv anivartinoḥ', null, 7027036),
('ramayana-7-27-37', 37, 'Uttara Kanda, Sarga 27, Verse 37', 'ततस्तस्य महाबाणैर्वसुना सुमहात्मना।
महान्स पन्नगरथः क्षणेन विनिपातितः॥', 'tatas tasya mahābāṇair vasunā sumahātmanā
mahān sa pannagarathaḥ kṣaṇena vinipātitaḥ', null, 7027037),
('ramayana-7-27-38', 38, 'Uttara Kanda, Sarga 27, Verse 38', 'हत्वा तु संयुगे तस्य रथं बाणशतैः शितैः।
गदां तस्य वधार्थाय वसुर्जग्राह पाणिना॥', 'hatvā tu saṃyuge tasya rathaṃ bāṇaśataiḥ śitaiḥ
gadāṃ tasya vadhārthāya vasur jagrāha pāṇinā', null, 7027038),
('ramayana-7-27-39', 39, 'Uttara Kanda, Sarga 27, Verse 39', 'तां प्रदीप्तां प्रगृह्याशु कालदण्डनिभां शुभाम्।
तस्य मूर्धनि सावित्रः सुमालेर्विनिपातयत्॥', 'tāṃ pradīptāṃ pragṛhyāśu kāladaṇḍanibhāṃ śubhām
tasya mūrdhani sāvitraḥ sumāler vinipātayat', null, 7027039),
('ramayana-7-27-40', 40, 'Uttara Kanda, Sarga 27, Verse 40', 'तस्य मूर्धनि सोल्काभा पतन्ती च तदा बभौ।
सहस्राक्षसमुत्सृष्टा गिराविव महाशनिः॥', 'tasya mūrdhani solkābhā patantī ca tadā babhau
sahasrākṣasamutsṛṣṭā girāv iva mahāśaniḥ', null, 7027040),
('ramayana-7-27-41', 41, 'Uttara Kanda, Sarga 27, Verse 41', 'तस्य नैवास्थि कायो वा न मांसं ददृशे तदा।
गदया भस्मसाद्भूतो रणे तस्मिन्निपातितः॥', 'tasya naivāsthi kāyo vā na māṃsaṃ dadṛśe tadā
gadayā bhasmasādbhūto raṇe tasmin nipātitaḥ', null, 7027041),
('ramayana-7-27-42', 42, 'Uttara Kanda, Sarga 27, Verse 42', 'तं दृष्ट्वा निहतं संख्ये राक्षसास्ते समन्ततः।
दुद्रुवुः सहिताः सर्वे क्रोशमाना महास्वनम्॥', 'taṃ dṛṣṭvā nihataṃ saṃkhye rākṣasās te samantataḥ
dudruvuḥ sahitāḥ sarve krośamānā mahāsvanam', null, 7027042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 28 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-28-1', 1, 'Uttara Kanda, Sarga 28, Verse 1', 'सुमालिनं हतं दृष्ट्वा वसुना भस्मसात्कृतम्।
विद्रुतं चापि स्वं सैन्यं लक्षयित्वार्दितं शरैः॥', 'sumālinaṃ hataṃ dṛṣṭvā vasunā bhasmasātkṛtam
vidrutaṃ cāpi svaṃ sainyaṃ lakṣayitvārditaṃ śaraiḥ', null, 7028001),
('ramayana-7-28-2', 2, 'Uttara Kanda, Sarga 28, Verse 2', 'ततः स बलवान्क्रुद्धो रावणस्य सुतो युधि।
निवर्त्य राक्षसान्सर्वान्मेघनादो व्यतिष्ठत॥', 'tataḥ sa balavān kruddho rāvaṇasya suto yudhi
nivartya rākṣasān sarvān meghanādo vyatiṣṭhata', null, 7028002),
('ramayana-7-28-3', 3, 'Uttara Kanda, Sarga 28, Verse 3', 'स रथेनाग्निवर्णेन कामगेन महारथः।
अभिदुद्राव सेनां तां वनान्यग्निरिव ज्वलन्॥', 'sa rathenāgnivarṇena kāmagena mahārathaḥ
abhidudrāva senāṃ tāṃ vanāny agnir iva jvalan', null, 7028003),
('ramayana-7-28-4', 4, 'Uttara Kanda, Sarga 28, Verse 4', 'ततः प्रविशतस्तस्य विविधायुधधारिणः।
विदुद्रुवुर्दिशः सर्वा देवास्तस्य च दर्शनात्॥', 'tataḥ praviśatas tasya vividhāyudhadhāriṇaḥ
vidudruvur diśaḥ sarvā devās tasya ca darśanāt', null, 7028004),
('ramayana-7-28-5', 5, 'Uttara Kanda, Sarga 28, Verse 5', 'न तत्रावस्थितः कश्चिद्रणे तस्य युयुत्सतः।
सर्वानाविध्य वित्रस्तान्दृष्ट्वा शक्रोऽभ्यभाषत॥', 'na tatrāvasthitaḥ kaś cid raṇe tasya yuyutsataḥ
sarvān āvidhya vitrastān dṛṣṭvā śakro ''bhyabhāṣata', null, 7028005),
('ramayana-7-28-6', 6, 'Uttara Kanda, Sarga 28, Verse 6', 'न भेतव्यं न गन्तव्यं निवर्तध्वं रणं प्रति।
एष गच्छति मे पुत्रो युद्धार्थमपराजितः॥', 'na bhetavyaṃ na gantavyaṃ nivartadhvaṃ raṇaṃ prati
eṣa gacchati me putro yuddhārtham aparājitaḥ', null, 7028006),
('ramayana-7-28-7', 7, 'Uttara Kanda, Sarga 28, Verse 7', 'ततः शक्रसुतो देवो जयन्त इति विश्रुतः।
रथेनाद्भुतकल्पेन संग्राममभिवर्तत॥', 'tataḥ śakrasuto devo jayanta iti viśrutaḥ
rathenādbhutakalpena saṃgrāmam abhivartata', null, 7028007),
('ramayana-7-28-8', 8, 'Uttara Kanda, Sarga 28, Verse 8', 'ततस्ते त्रिदशाः सर्वे परिवार्य शचीसुतम्।
रावणस्य सुतं युद्धे समासाद्य व्यवस्थिताः॥', 'tatas te tridaśāḥ sarve parivārya śacīsutam
rāvaṇasya sutaṃ yuddhe samāsādya vyavasthitāḥ', null, 7028008),
('ramayana-7-28-9', 9, 'Uttara Kanda, Sarga 28, Verse 9', 'तेषां युद्धं महदभूत्सदृशं देवरक्षसाम्।
कृते महेन्द्रपुत्रस्य राक्षसेन्द्रसुतस्य च॥', 'teṣāṃ yuddhaṃ mahad abhūt sadṛśaṃ devarakṣasām
kṛte mahendraputrasya rākṣasendrasutasya ca', null, 7028009),
('ramayana-7-28-10', 10, 'Uttara Kanda, Sarga 28, Verse 10', 'ततो मातलिपुत्रे तु गोमुखे राक्षसात्मजः।
सारथौ पातयामास शरान्काञ्चनभूषणान्॥', 'tato mātaliputre tu gomukhe rākṣasātmajaḥ
sārathau pātayām āsa śarān kāñcanabhūṣaṇān', null, 7028010),
('ramayana-7-28-11', 11, 'Uttara Kanda, Sarga 28, Verse 11', 'शचीसुतस्त्वपि तथा जयन्तस्तस्य सारथिम्।
तं चैव रावणिं क्रुद्धः प्रत्यविध्यद्रणाजिरे॥', 'śacīsutas tv api tathā jayantas tasya sārathim
taṃ caiva rāvaṇiṃ kruddhaḥ pratyavidhyad raṇājire', null, 7028011),
('ramayana-7-28-12', 12, 'Uttara Kanda, Sarga 28, Verse 12', 'ततः क्रुद्धो महातेजा रक्षो विस्फारितेक्षणः।
रावणिः शक्रपुत्रं तं शरवर्षैरवाकिरत्॥', 'tataḥ kruddho mahātejā rakṣo visphāritekṣaṇaḥ
rāvaṇiḥ śakraputraṃ taṃ śaravarṣair avākirat', null, 7028012),
('ramayana-7-28-13', 13, 'Uttara Kanda, Sarga 28, Verse 13', 'ततः प्रगृह्य शस्त्राणि सारवन्ति महान्ति च।
शतघ्नीस्तोमरान्प्रासान्गदाखड्गपरश्वधान्।
सुमहान्त्यद्रिशृङ्गाणि पातयामास रावणिः॥', 'tataḥ pragṛhya śastrāṇi sāravanti mahānti ca
śataghnīs tomarān prāsān gadākhaḍgaparaśvadhān
sumahānty adriśṛṅgāṇi pātayām āsa rāvaṇiḥ', null, 7028013),
('ramayana-7-28-14', 14, 'Uttara Kanda, Sarga 28, Verse 14', 'ततः प्रव्यथिता लोकाः संजज्ञे च तमो महत्।
तस्य रावणपुत्रस्य तदा शत्रूनभिघ्नतः॥', 'tataḥ pravyathitā lokāḥ saṃjajñe ca tamo mahat
tasya rāvaṇaputrasya tadā śatrūn abhighnataḥ', null, 7028014),
('ramayana-7-28-15', 15, 'Uttara Kanda, Sarga 28, Verse 15', 'ततस्तद्दैवतबलं समन्तात्तं शचीसुतम्।
बहुप्रकारमस्वस्थं तत्र तत्र स्म धावति॥', 'tatas tad daivatabalaṃ samantāt taṃ śacīsutam
bahuprakāram asvasthaṃ tatra tatra sma dhāvati', null, 7028015),
('ramayana-7-28-16', 16, 'Uttara Kanda, Sarga 28, Verse 16', 'नाभ्यजानंस्तदान्योन्यं शत्रून्वा दैवतानि वा।
तत्र तत्र विपर्यस्तं समन्तात्परिधावितम्॥', 'nābhyajānaṃs tadānyonyaṃ śatrūn vā daivatāni vā
tatra tatra viparyastaṃ samantāt paridhāvitam', null, 7028016),
('ramayana-7-28-17', 17, 'Uttara Kanda, Sarga 28, Verse 17', 'एतस्मिन्नन्तरे शूरः पुलोमा नाम वीर्यवान्।
दैतेयस्तेन संगृह्य शचीपुत्रोऽपवाहितः॥', 'etasminn antare śūraḥ pulomā nāma vīryavān
daiteyas tena saṃgṛhya śacīputro ''pavāhitaḥ', null, 7028017),
('ramayana-7-28-18', 18, 'Uttara Kanda, Sarga 28, Verse 18', 'गृहीत्वा तं तु नप्तारं प्रविष्टः स महोदधिम्।
मातामहोऽर्यकस्तस्य पौलोमी येन सा शची॥', 'gṛhītvā taṃ tu naptāraṃ praviṣṭaḥ sa mahodadhim
mātāmaho ''ryakas tasya paulomī yena sā śacī', null, 7028018),
('ramayana-7-28-19', 19, 'Uttara Kanda, Sarga 28, Verse 19', 'प्रणाशं दृश्य तु सुरा जयन्तस्यातिदारुणम्।
व्यथिताश्चाप्रहृष्टाश्च समन्ताद्विप्रदुद्रुवुः॥', 'praṇāśaṃ dṛśya tu surā jayantasyātidāruṇam
vyathitāś cāprahṛṣṭāś ca samantād vipradudruvuḥ', null, 7028019),
('ramayana-7-28-20', 20, 'Uttara Kanda, Sarga 28, Verse 20', 'रावणिस्त्वथ संहृष्टो बलैः परिवृतः स्वकैः।
अभ्यधावत देवांस्तान्मुमोच च महास्वनम्॥', 'rāvaṇis tv atha saṃhṛṣṭo balaiḥ parivṛtaḥ svakaiḥ
abhyadhāvata devāṃs tān mumoca ca mahāsvanam', null, 7028020),
('ramayana-7-28-21', 21, 'Uttara Kanda, Sarga 28, Verse 21', 'दृष्ट्वा प्रणाशं पुत्रस्य रावणेश्चापि विक्रमम्।
मातलिं प्राह देवेन्द्रो रथः समुपनीयताम्॥', 'dṛṣṭvā praṇāśaṃ putrasya rāvaṇeś cāpi vikramam
mātaliṃ prāha devendro rathaḥ samupanīyatām', null, 7028021),
('ramayana-7-28-22', 22, 'Uttara Kanda, Sarga 28, Verse 22', 'स तु दिव्यो महाभीमः सज्ज एव महारथः।
उपस्थितो मातलिना वाह्यमानो मनोजवः॥', 'sa tu divyo mahābhīmaḥ sajja eva mahārathaḥ
upasthito mātalinā vāhyamāno manojavaḥ', null, 7028022),
('ramayana-7-28-23', 23, 'Uttara Kanda, Sarga 28, Verse 23', 'ततो मेघा रथे तस्मिंस्तडिद्वन्तो महास्वनाः।
अग्रतो वायुचपला गच्छन्तो व्यनदंस्तदा॥', 'tato meghā rathe tasmiṃs taḍidvanto mahāsvanāḥ
agrato vāyucapalā gacchanto vyanadaṃs tadā', null, 7028023),
('ramayana-7-28-24', 24, 'Uttara Kanda, Sarga 28, Verse 24', 'नानावाद्यानि वाद्यन्त स्तुतयश्च समाहिताः।
ननृतुश्चाप्सरःसंघाः प्रयाते वासवे रणम्॥', 'nānāvādyāni vādyanta stutayaś ca samāhitāḥ
nanṛtuś cāpsaraḥsaṃghāḥ prayāte vāsave raṇam', null, 7028024),
('ramayana-7-28-25', 25, 'Uttara Kanda, Sarga 28, Verse 25', 'रुद्रैर्वसुभिरादित्यैः साध्यैश्च समरुद्गणैः।
वृतो नानाप्रहरणैर्निर्ययौ त्रिदशाधिपः॥', 'rudrair vasubhir ādityaiḥ sādhyaiś ca samarudgaṇaiḥ
vṛto nānāpraharaṇair niryayau tridaśādhipaḥ', null, 7028025),
('ramayana-7-28-26', 26, 'Uttara Kanda, Sarga 28, Verse 26', 'निर्गच्छतस्तु शक्रस्य परुषं पवनो ववौ।
भास्करो निष्प्रभश्चासीन्महोल्काश्च प्रपेदिरे॥', 'nirgacchatas tu śakrasya paruṣaṃ pavano vavau
bhāskaro niṣprabhaś cāsīn maholkāś ca prapedire', null, 7028026),
('ramayana-7-28-27', 27, 'Uttara Kanda, Sarga 28, Verse 27', 'एतस्मिन्नन्तरे शूरो दशग्रीवः प्रतापवान्।
आरुरोह रथं दिव्यं निर्मितं विश्वकर्मणा॥', 'etasminn antare śūro daśagrīvaḥ pratāpavān
āruroha rathaṃ divyaṃ nirmitaṃ viśvakarmaṇā', null, 7028027),
('ramayana-7-28-28', 28, 'Uttara Kanda, Sarga 28, Verse 28', 'पन्नगैः सुमहाकायैर्वेष्टितं लोमहर्षणैः।
येषां निश्वासवातेन प्रदीप्तमिव संयुगम्॥', 'pannagaiḥ sumahākāyair veṣṭitaṃ lomaharṣaṇaiḥ
yeṣāṃ niśvāsavātena pradīptam iva saṃyugam', null, 7028028),
('ramayana-7-28-29', 29, 'Uttara Kanda, Sarga 28, Verse 29', 'दैत्यैर्निशाचरैः शूरै रथः संपरिवारितः।
समराभिमुखो दिव्यो महेन्द्रमभिवर्तत॥', 'daityair niśācaraiḥ śūrai rathaḥ saṃparivāritaḥ
samarābhimukho divyo mahendram abhivartata', null, 7028029),
('ramayana-7-28-30', 30, 'Uttara Kanda, Sarga 28, Verse 30', 'पुत्रं तं वारयित्वासौ स्वयमेव व्यवस्थितः।
सोऽपि युद्धाद्विनिष्क्रम्य रावणिः समुपाविशत्॥', 'putraṃ taṃ vārayitvāsau svayam eva vyavasthitaḥ
so ''pi yuddhād viniṣkramya rāvaṇiḥ samupāviśat', null, 7028030),
('ramayana-7-28-31', 31, 'Uttara Kanda, Sarga 28, Verse 31', 'ततो युद्धं प्रवृत्तं तु सुराणां राक्षसैः सह।
शस्त्राभिवर्षणं घोरं मेघानामिव संयुगे॥', 'tato yuddhaṃ pravṛttaṃ tu surāṇāṃ rākṣasaiḥ saha
śastrābhivarṣaṇaṃ ghoraṃ meghānām iva saṃyuge', null, 7028031),
('ramayana-7-28-32', 32, 'Uttara Kanda, Sarga 28, Verse 32', 'कुम्भकर्णस्तु दुष्टात्मा नानाप्रहरणोद्यतः।
नाज्ञायत तदा युद्धे सह केनाप्ययुध्यत॥', 'kumbhakarṇas tu duṣṭātmā nānāpraharaṇodyataḥ
nājñāyata tadā yuddhe saha kenāpy ayudhyata', null, 7028032),
('ramayana-7-28-33', 33, 'Uttara Kanda, Sarga 28, Verse 33', 'दन्तैर्भुजाभ्यां पद्भ्यां च शक्तितोमरसायकैः।
येन केनैव संरब्धस्ताडयामास वै सुरान्॥', 'dantair bhujābhyāṃ padbhyāṃ ca śaktitomarasāyakaiḥ
yena kenaiva saṃrabdhas tāḍayām āsa vai surān', null, 7028033),
('ramayana-7-28-34', 34, 'Uttara Kanda, Sarga 28, Verse 34', 'ततो रुद्रैर्महाभागैः सहादित्यैर्निशाचरः।
प्रयुद्धस्तैश्च संग्रामे कृत्तः शस्त्रैर्निरन्तरम्॥', 'tato rudrair mahābhāgaiḥ sahādityair niśācaraḥ
prayuddhas taiś ca saṃgrāme kṛttaḥ śastrair nirantaram', null, 7028034),
('ramayana-7-28-35', 35, 'Uttara Kanda, Sarga 28, Verse 35', 'ततस्तद्राक्षसं सैन्यं त्रिदशैः समरुद्गणैः।
रणे विद्रावितं सर्वं नानाप्रहरणैः शितैः॥', 'tatas tad rākṣasaṃ sainyaṃ tridaśaiḥ samarudgaṇaiḥ
raṇe vidrāvitaṃ sarvaṃ nānāpraharaṇaiḥ śitaiḥ', null, 7028035),
('ramayana-7-28-36', 36, 'Uttara Kanda, Sarga 28, Verse 36', 'के चिद्विनिहताः शस्त्रैर्वेष्टन्ति स्म महीतले।
वाहनेष्ववसक्ताश्च स्थिता एवापरे रणे॥', 'ke cid vinihatāḥ śastrair veṣṭanti sma mahītale
vāhaneṣv avasaktāś ca sthitā evāpare raṇe', null, 7028036),
('ramayana-7-28-37', 37, 'Uttara Kanda, Sarga 28, Verse 37', 'रथान्नागान्खरानुष्ट्रान्पन्नगांस्तुरगांस्तथा।
शिंशुमारान्वराहांश्च पिशाचवदनांस्तथा॥', 'rathān nāgān kharān uṣṭrān pannagāṃs turagāṃs tathā
śiṃśumārān varāhāṃś ca piśācavadanāṃs tathā', null, 7028037),
('ramayana-7-28-38', 38, 'Uttara Kanda, Sarga 28, Verse 38', 'तान्समालिङ्ग्य बाहुभ्यां विष्टब्धाः के चिदुच्छ्रिताः।
देवैस्तु शस्त्रसंविद्धा मम्रिरे च निशाचराः॥', 'tān samāliṅgya bāhubhyāṃ viṣṭabdhāḥ ke cid ucchritāḥ
devais tu śastrasaṃviddhā mamrire ca niśācarāḥ', null, 7028038),
('ramayana-7-28-39', 39, 'Uttara Kanda, Sarga 28, Verse 39', 'चित्रकर्म इवाभाति स तेषां रणसंप्लवः।
निहतानां प्रमत्तानां राक्षसानां महीतले॥', 'citrakarma ivābhāti sa teṣāṃ raṇasaṃplavaḥ
nihatānāṃ pramattānāṃ rākṣasānāṃ mahītale', null, 7028039),
('ramayana-7-28-40', 40, 'Uttara Kanda, Sarga 28, Verse 40', 'शोणितोदक निष्यन्दाकङ्कगृध्रसमाकुला।
प्रवृत्ता संयुगमुखे शस्त्रग्राहवती नदी॥', 'śoṇitodaka niṣyandākaṅkagṛdhrasamākulā
pravṛttā saṃyugamukhe śastragrāhavatī nadī', null, 7028040),
('ramayana-7-28-41', 41, 'Uttara Kanda, Sarga 28, Verse 41', 'एतस्मिन्नन्तरे क्रुद्धो दशग्रीवः प्रतापवान्।
निरीक्ष्य तद्बलं सर्वं दैवतैर्विनिपातितम्॥', 'etasminn antare kruddho daśagrīvaḥ pratāpavān
nirīkṣya tad balaṃ sarvaṃ daivatair vinipātitam', null, 7028041),
('ramayana-7-28-42', 42, 'Uttara Kanda, Sarga 28, Verse 42', 'स तं प्रतिविगाह्याशु प्रवृद्धं सैन्यसागरम्।
त्रिदशान्समरे निघ्नञ्शक्रमेवाभ्यवर्तत॥', 'sa taṃ prativigāhyāśu pravṛddhaṃ sainyasāgaram
tridaśān samare nighnañ śakram evābhyavartata', null, 7028042),
('ramayana-7-28-43', 43, 'Uttara Kanda, Sarga 28, Verse 43', 'ततः शक्रो महच्चापं विस्फार्य सुमहास्वनम्।
यस्य विस्फारघोषेण स्वनन्ति स्म दिशो दश॥', 'tataḥ śakro mahac cāpaṃ visphārya sumahāsvanam
yasya visphāraghoṣeṇa svananti sma diśo daśa', null, 7028043),
('ramayana-7-28-44', 44, 'Uttara Kanda, Sarga 28, Verse 44', 'तद्विकृष्य महच्चापमिन्द्रो रावणमूर्धनि।
निपातयामास शरान्पावकादित्यवर्चसः॥', 'tad vikṛṣya mahac cāpam indro rāvaṇamūrdhani
nipātayām āsa śarān pāvakādityavarcasaḥ', null, 7028044),
('ramayana-7-28-45', 45, 'Uttara Kanda, Sarga 28, Verse 45', 'तथैव च महाबाहुर्दशग्रीवो व्यवस्थितः।
शक्रं कार्मुकविभ्रष्टैः शरवर्षैरवाकिरत्॥', 'tathaiva ca mahābāhur daśagrīvo vyavasthitaḥ
śakraṃ kārmukavibhraṣṭaiḥ śaravarṣair avākirat', null, 7028045),
('ramayana-7-28-46', 46, 'Uttara Kanda, Sarga 28, Verse 46', 'प्रयुध्यतोरथ तयोर्बाणवर्षैः समन्ततः।
नाज्ञायत तदा किं चित्सर्वं हि तमसा वृतम्॥', 'prayudhyator atha tayor bāṇavarṣaiḥ samantataḥ
nājñāyata tadā kiṃ cit sarvaṃ hi tamasā vṛtam', null, 7028046)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 29 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-29-1', 1, 'Uttara Kanda, Sarga 29, Verse 1', 'ततस्तमसि संजाते राक्षसा दैवतैः सह।
अयुध्यन्त बलोन्मत्ताः सूदयन्तः परस्परम्॥', 'tatas tamasi saṃjāte rākṣasā daivataiḥ saha
ayudhyanta balonmattāḥ sūdayantaḥ parasparam', null, 7029001),
('ramayana-7-29-2', 2, 'Uttara Kanda, Sarga 29, Verse 2', 'ततस्तु देवसैन्येन राक्षसानां महद्बलम्।
दशांशं स्थापितं युद्धे शेषं नीतं यमक्षयम्॥', 'tatas tu devasainyena rākṣasānāṃ mahad balam
daśāṃśaṃ sthāpitaṃ yuddhe śeṣaṃ nītaṃ yamakṣayam', null, 7029002),
('ramayana-7-29-3', 3, 'Uttara Kanda, Sarga 29, Verse 3', 'तस्मिंस्तु तमसा नद्धे सर्वे ते देवराक्षसाः।
अन्योन्यं नाभ्यजानन्त युध्यमानाः परस्परम्॥', 'tasmiṃs tu tamasā naddhe sarve te devarākṣasāḥ
anyonyaṃ nābhyajānanta yudhyamānāḥ parasparam', null, 7029003),
('ramayana-7-29-4', 4, 'Uttara Kanda, Sarga 29, Verse 4', 'इन्द्रश्च रावणश्चैव रावणिश्च महाबलः।
तस्मिंस्तमोजालवृते मोहमीयुर्न ते त्रयः॥', 'indraś ca rāvaṇaś caiva rāvaṇiś ca mahābalaḥ
tasmiṃs tamojālavṛte moham īyur na te trayaḥ', null, 7029004),
('ramayana-7-29-5', 5, 'Uttara Kanda, Sarga 29, Verse 5', 'स तु दृष्ट्वा बलं सर्वं निहतं रावणो रणे।
क्रोधमभ्यागमत्तीव्रं महानादं च मुक्तवान्॥', 'sa tu dṛṣṭvā balaṃ sarvaṃ nihataṃ rāvaṇo raṇe
krodham abhyāgamat tīvraṃ mahānādaṃ ca muktavān', null, 7029005),
('ramayana-7-29-6', 6, 'Uttara Kanda, Sarga 29, Verse 6', 'क्रोधात्सूतं च दुर्धर्षः स्यन्दनस्थमुवाच ह।
परसैन्यस्य मध्येन यावदन्तं नयस्व माम्॥', 'krodhāt sūtaṃ ca durdharṣaḥ syandanastham uvāca ha
parasainyasya madhyena yāvadantaṃ nayasva mām', null, 7029006),
('ramayana-7-29-7', 7, 'Uttara Kanda, Sarga 29, Verse 7', 'अद्यैतांस्त्रिदशान्सर्वान्विक्रमैः समरे स्वयम्।
नानाशस्त्रैर्महासारैर्नाशयामि नभस्तलात्॥', 'adyaitāṃs tridaśān sarvān vikramaiḥ samare svayam
nānāśastrair mahāsārair nāśayāmi nabhastalāt', null, 7029007),
('ramayana-7-29-8', 8, 'Uttara Kanda, Sarga 29, Verse 8', 'अहमिन्द्रं वधिष्यामि वरुणं धनदं यमम्।
त्रिदशान्विनिहत्याशु स्वयं स्थास्याम्यथोपरि॥', 'aham indraṃ vadhiṣyāmi varuṇaṃ dhanadaṃ yamam
tridaśān vinihatyāśu svayaṃ sthāsyāmy athopari', null, 7029008),
('ramayana-7-29-9', 9, 'Uttara Kanda, Sarga 29, Verse 9', 'विषादो न च कर्तव्यः शीघ्रं वाहय मे रथम्।
द्विः खलु त्वां ब्रवीम्यद्य यावदन्तं नयस्व माम्॥', 'viṣādo na ca kartavyaḥ śīghraṃ vāhaya me ratham
dviḥ khalu tvāṃ bravīmy adya yāvadantaṃ nayasva mām', null, 7029009),
('ramayana-7-29-10', 10, 'Uttara Kanda, Sarga 29, Verse 10', 'अयं स नन्दनोद्देशो यत्र वर्तामहे वयम्।
नय मामद्य तत्र त्वमुदयो यत्र पर्वतः॥', 'ayaṃ sa nandanoddeśo yatra vartāmahe vayam
naya mām adya tatra tvam udayo yatra parvataḥ', null, 7029010),
('ramayana-7-29-11', 11, 'Uttara Kanda, Sarga 29, Verse 11', 'तस्य तद्वचनं श्रुत्वा तुरगान्स मनोजवान्।
आदिदेशाथ शत्रूणां मध्येनैव च सारथिः॥', 'tasya tad vacanaṃ śrutvā turagān sa manojavān
ādideśātha śatrūṇāṃ madhyenaiva ca sārathiḥ', null, 7029011),
('ramayana-7-29-12', 12, 'Uttara Kanda, Sarga 29, Verse 12', 'तस्य तं निश्चयं ज्ञात्वा शक्रो देवेश्वरस्तदा।
रथस्थः समरस्थांस्तान्देवान्वाक्यमथाब्रवीत्॥', 'tasya taṃ niścayaṃ jñātvā śakro deveśvaras tadā
rathasthaḥ samarasthāṃs tān devān vākyam athābravīt', null, 7029012),
('ramayana-7-29-13', 13, 'Uttara Kanda, Sarga 29, Verse 13', 'सुराः शृणुत मद्वाक्यं यत्तावन्मम रोचते।
जीवन्नेव दशग्रीवः साधु रक्षो निगृह्यताम्॥', 'surāḥ śṛṇuta madvākyaṃ yat tāvan mama rocate
jīvann eva daśagrīvaḥ sādhu rakṣo nigṛhyatām', null, 7029013),
('ramayana-7-29-14', 14, 'Uttara Kanda, Sarga 29, Verse 14', 'एष ह्यतिबलः सैन्ये रथेन पवनौजसा।
गमिष्यति प्रवृद्धोर्मिः समुद्र इव पर्वणि॥', 'eṣa hy atibalaḥ sainye rathena pavanaujasā
gamiṣyati pravṛddhormiḥ samudra iva parvaṇi', null, 7029014),
('ramayana-7-29-15', 15, 'Uttara Kanda, Sarga 29, Verse 15', 'न ह्येष हन्तुं शक्योऽद्य वरदानात्सुनिर्भयः।
तद्ग्रहीष्यामहे रक्षो यत्ता भवत संयुगे॥', 'na hy eṣa hantuṃ śakyo ''dya varadānāt sunirbhayaḥ
tad grahīṣyāmahe rakṣo yattā bhavata saṃyuge', null, 7029015),
('ramayana-7-29-16', 16, 'Uttara Kanda, Sarga 29, Verse 16', 'यथा बलिं निगृह्यैतत्त्रैलोक्यं भुज्यते मया।
एवमेतस्य पापस्य निग्रहो मम रोचते॥', 'yathā baliṃ nigṛhyaitat trailokyaṃ bhujyate mayā
evam etasya pāpasya nigraho mama rocate', null, 7029016),
('ramayana-7-29-17', 17, 'Uttara Kanda, Sarga 29, Verse 17', 'ततोऽन्यं देशमास्थाय शक्रः संत्यज्य रावणम्।
अयुध्यत महातेजा राक्षसान्नाशयन्रणे॥', 'tato ''nyaṃ deśam āsthāya śakraḥ saṃtyajya rāvaṇam
ayudhyata mahātejā rākṣasān nāśayan raṇe', null, 7029017),
('ramayana-7-29-18', 18, 'Uttara Kanda, Sarga 29, Verse 18', 'उत्तरेण दशग्रीवः प्रविवेशानिवर्तितः।
दक्षिणेन तु पार्श्वेन प्रविवेश शतक्रतुः॥', 'uttareṇa daśagrīvaḥ praviveśānivartitaḥ
dakṣiṇena tu pārśvena praviveśa śatakratuḥ', null, 7029018),
('ramayana-7-29-19', 19, 'Uttara Kanda, Sarga 29, Verse 19', 'ततः स योजनशतं प्रविष्टो राक्षसाधिपः।
देवतानां बलं कृत्स्नं शरवर्षैरवाकिरत्॥', 'tataḥ sa yojanaśataṃ praviṣṭo rākṣasādhipaḥ
devatānāṃ balaṃ kṛtsnaṃ śaravarṣair avākirat', null, 7029019),
('ramayana-7-29-20', 20, 'Uttara Kanda, Sarga 29, Verse 20', 'ततः शक्रो निरीक्ष्याथ प्रविष्टं तं बलं स्वकम्।
न्यवर्तयदसंभ्रान्तः समावृत्य दशाननम्॥', 'tataḥ śakro nirīkṣyātha praviṣṭaṃ taṃ balaṃ svakam
nyavartayad asaṃbhrāntaḥ samāvṛtya daśānanam', null, 7029020),
('ramayana-7-29-21', 21, 'Uttara Kanda, Sarga 29, Verse 21', 'एतस्मिन्नन्तरे नादो मुक्तो दानवराक्षसैः।
हा हताः स्मेति तं दृष्ट्वा ग्रस्तं शक्रेण रावणम्॥', 'etasminn antare nādo mukto dānavarākṣasaiḥ
hā hatāḥ smeti taṃ dṛṣṭvā grastaṃ śakreṇa rāvaṇam', null, 7029021),
('ramayana-7-29-22', 22, 'Uttara Kanda, Sarga 29, Verse 22', 'ततो रथं समारुह्य रावणिः क्रोधमूर्छितः।
तत्सैन्यमतिसंक्रुद्धः प्रविवेश सुदारुणम्॥', 'tato rathaṃ samāruhya rāvaṇiḥ krodhamūrchitaḥ
tat sainyam atisaṃkruddhaḥ praviveśa sudāruṇam', null, 7029022),
('ramayana-7-29-23', 23, 'Uttara Kanda, Sarga 29, Verse 23', 'स तां प्रविश्य मायां तु दत्तां गोपतिना पुरा।
अदृश्यः सर्वभूतानां तत्सैन्यं समवाकिरत्॥', 'sa tāṃ praviśya māyāṃ tu dattāṃ gopatinā purā
adṛśyaḥ sarvabhūtānāṃ tat sainyaṃ samavākirat', null, 7029023),
('ramayana-7-29-24', 24, 'Uttara Kanda, Sarga 29, Verse 24', 'ततः स देवान्संत्यज्य शक्रमेवाभ्ययाद्द्रुतम्।
महेन्द्रश्च महातेजा न ददर्श सुतं रिपोः॥', 'tataḥ sa devān saṃtyajya śakram evābhyayād drutam
mahendraś ca mahātejā na dadarśa sutaṃ ripoḥ', null, 7029024),
('ramayana-7-29-25', 25, 'Uttara Kanda, Sarga 29, Verse 25', 'स मातलिं हयांश्चैव ताडयित्वा शरोत्तमैः।
महेन्द्रं बाणवर्षेण शीघ्रहस्तो ह्यवाकिरत्॥', 'sa mātaliṃ hayāṃś caiva tāḍayitvā śarottamaiḥ
mahendraṃ bāṇavarṣeṇa śīghrahasto hy avākirat', null, 7029025),
('ramayana-7-29-26', 26, 'Uttara Kanda, Sarga 29, Verse 26', 'ततः शक्रो रथं त्यक्त्व विसृज्य च स मातलिम्।
ऐरावतं समारुह्य मृगयामास रावणिम्॥', 'tataḥ śakro rathaṃ tyaktva visṛjya ca sa mātalim
airāvataṃ samāruhya mṛgayām āsa rāvaṇim', null, 7029026),
('ramayana-7-29-27', 27, 'Uttara Kanda, Sarga 29, Verse 27', 'स तु माया बलाद्रक्षः संग्रामे नाभ्यदृश्यत।
किरमाणः शरौघेन महेन्द्रममितौजसं॥', 'sa tu māyā balād rakṣaḥ saṃgrāme nābhyadṛśyata
kiramāṇaḥ śaraughena mahendram amitaujasaṃ', null, 7029027),
('ramayana-7-29-28', 28, 'Uttara Kanda, Sarga 29, Verse 28', 'स तं यदा परिश्रान्तमिन्द्रं मेनेऽथ रावणिः।
तदैनं मायया बद्ध्वा स्वसैन्यमभितोऽनयत्॥', 'sa taṃ yadā pariśrāntam indraṃ mene ''tha rāvaṇiḥ
tadainaṃ māyayā baddhvā svasainyam abhito ''nayat', null, 7029028),
('ramayana-7-29-29', 29, 'Uttara Kanda, Sarga 29, Verse 29', 'तं दृष्ट्वाथ बलात्तस्मिन्माययापहृतं रणे।
महेन्द्रममराः सर्वे किं न्वेतदिति चुक्रुशुः।
न हि दृश्यति विद्यावान्मायया येन नीयते॥', 'taṃ dṛṣṭvātha balāt tasmin māyayāpahṛtaṃ raṇe
mahendram amarāḥ sarve kiṃ nv etad iti cukruśuḥ
na hi dṛśyati vidyāvān māyayā yena nīyate', null, 7029029),
('ramayana-7-29-30', 30, 'Uttara Kanda, Sarga 29, Verse 30', 'एतस्मिन्नन्तरे चापि सर्वे सुरगणास्तदा।
अभ्यद्रवन्सुसंक्रुद्धा रावणं शस्त्रवृष्टिभिः॥', 'etasminn antare cāpi sarve suragaṇās tadā
abhyadravan susaṃkruddhā rāvaṇaṃ śastravṛṣṭibhiḥ', null, 7029030),
('ramayana-7-29-31', 31, 'Uttara Kanda, Sarga 29, Verse 31', 'रावणस्तु समासाद्य वस्वादित्यमरुद्गणान्।
न शशाक रणे स्थातुं न योद्धुं शस्त्रपीडितः॥', 'rāvaṇas tu samāsādya vasvādityamarudgaṇān
na śaśāka raṇe sthātuṃ na yoddhuṃ śastrapīḍitaḥ', null, 7029031),
('ramayana-7-29-32', 32, 'Uttara Kanda, Sarga 29, Verse 32', 'तं तु दृष्ट्वा परिश्रान्तं प्रहारैर्जर्जरच्छविम्।
रावणिः पितरं युद्धेऽदर्शनस्थोऽब्रवीदिदम्॥', 'taṃ tu dṛṣṭvā pariśrāntaṃ prahārair jarjaracchavim
rāvaṇiḥ pitaraṃ yuddhe ''darśanastho ''bravīd idam', null, 7029032),
('ramayana-7-29-33', 33, 'Uttara Kanda, Sarga 29, Verse 33', 'आगच्छ तात गच्छावो निवृत्तं रणकर्म तत्।
जितं ते विदितं भोऽस्तु स्वस्थो भव गतज्वरः॥', 'āgaccha tāta gacchāvo nivṛttaṃ raṇakarma tat
jitaṃ te viditaṃ bho ''stu svastho bhava gatajvaraḥ', null, 7029033),
('ramayana-7-29-34', 34, 'Uttara Kanda, Sarga 29, Verse 34', 'अयं हि सुरसैन्यस्य त्रैलोक्यस्य च यः प्रभुः।
स गृहीतो मया शक्रो भग्नमानाः सुराः कृताः॥', 'ayaṃ hi surasainyasya trailokyasya ca yaḥ prabhuḥ
sa gṛhīto mayā śakro bhagnamānāḥ surāḥ kṛtāḥ', null, 7029034),
('ramayana-7-29-35', 35, 'Uttara Kanda, Sarga 29, Verse 35', 'यथेष्टं भुङ्क्ष्व त्रैलोक्यं निगृह्य रिपुमोजसा।
वृथा ते किं श्रमं कृत्वा युद्धं हि तव निष्फलम्॥', 'yatheṣṭaṃ bhuṅkṣva trailokyaṃ nigṛhya ripum ojasā
vṛthā te kiṃ śramaṃ kṛtvā yuddhaṃ hi tava niṣphalam', null, 7029035),
('ramayana-7-29-36', 36, 'Uttara Kanda, Sarga 29, Verse 36', 'स दैवतबलात्तस्मान्निवृत्तो रणकर्मणः।
तच्छ्रुत्वा रावणेर्वाक्यं स्वस्थचेता दशाननः॥', 'sa daivatabalāt tasmān nivṛtto raṇakarmaṇaḥ
tac chrutvā rāvaṇer vākyaṃ svasthacetā daśānanaḥ', null, 7029036),
('ramayana-7-29-37', 37, 'Uttara Kanda, Sarga 29, Verse 37', 'अथ रणविगतज्वरः प्रभुर्विजयमवाप्य निशाचराधिपः।
भवनमभि ततो जगाम हृष्टः स्वसुतमवाप्य च वाक्यमब्रवीत्॥', 'atha raṇavigatajvaraḥ prabhur vijayam avāpya niśācarādhipaḥ
bhavanam abhi tato jagāma hṛṣṭaḥ svasutam avāpya ca vākyam abravīt', null, 7029037),
('ramayana-7-29-38', 38, 'Uttara Kanda, Sarga 29, Verse 38', 'अतिबलसदृशैः पराक्रमैस्तैर्मम कुलमानविवर्धनं कृतम्।
यदमरसमविक्रम त्वया त्रिदशपतिस्त्रिदशाश्च निर्जिताः॥', 'atibalasadṛśaiḥ parākramais tair mama kulamānavivardhanaṃ kṛtam
yad amarasamavikrama tvayā tridaśapatis tridaśāś ca nirjitāḥ', null, 7029038),
('ramayana-7-29-39', 39, 'Uttara Kanda, Sarga 29, Verse 39', 'त्वरितमुपनयस्व वासवं नगरमितो व्रज सैन्यसंवृतः।
अहमपि तव गच्छतो द्रुतं सह सचिवैरनुयामि पृष्ठतः॥', 'tvaritam upanayasva vāsavaṃ nagaram ito vraja sainyasaṃvṛtaḥ
aham api tava gacchato drutaṃ saha sacivair anuyāmi pṛṣṭhataḥ', null, 7029039),
('ramayana-7-29-40', 40, 'Uttara Kanda, Sarga 29, Verse 40', 'अथ स बलवृतः सवाहनस्त्रिदशपतिं परिगृह्य रावणिः।
स्वभवनमुपगम्य राक्षसो मुदितमना विससर्ज राक्षसान्॥', 'atha sa balavṛtaḥ savāhanas tridaśapatiṃ parigṛhya rāvaṇiḥ
svabhavanam upagamya rākṣaso muditamanā visasarja rākṣasān', null, 7029040)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 30 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-30-1', 1, 'Uttara Kanda, Sarga 30, Verse 1', 'जिते महेन्द्रेऽतिबले रावणस्य सुतेन वै।
प्रजापतिं पुरस्कृत्य गता लङ्कां सुरास्तदा॥', 'jite mahendre ''tibale rāvaṇasya sutena vai
prajāpatiṃ puraskṛtya gatā laṅkāṃ surās tadā', null, 7030001),
('ramayana-7-30-2', 2, 'Uttara Kanda, Sarga 30, Verse 2', 'तं रावणं समासाद्य पुत्रभ्रातृभिरावृतम्।
अब्रवीद्गगने तिष्ठन्सान्त्वपूर्वं प्रजापतिः॥', 'taṃ rāvaṇaṃ samāsādya putrabhrātṛbhir āvṛtam
abravīd gagane tiṣṭhan sāntvapūrvaṃ prajāpatiḥ', null, 7030002),
('ramayana-7-30-3', 3, 'Uttara Kanda, Sarga 30, Verse 3', 'वत्स रावण तुष्टोऽस्मि तव पुत्रस्य संयुगे।
अहोऽस्य विक्रमौदार्यं तव तुल्योऽधिकोऽपि वा॥', 'vatsa rāvaṇa tuṣṭo ''smi tava putrasya saṃyuge
aho ''sya vikramaudāryaṃ tava tulyo ''dhiko ''pi vā', null, 7030003),
('ramayana-7-30-4', 4, 'Uttara Kanda, Sarga 30, Verse 4', 'जितं हि भवता सर्वं त्रैलोक्यं स्वेन तेजसा।
कृता प्रतिज्ञा सफला प्रीतोऽस्मि स्वसुतेन वै॥', 'jitaṃ hi bhavatā sarvaṃ trailokyaṃ svena tejasā
kṛtā pratijñā saphalā prīto ''smi svasutena vai', null, 7030004),
('ramayana-7-30-5', 5, 'Uttara Kanda, Sarga 30, Verse 5', 'अयं च पुत्रोऽतिबलस्तव रावणरावणिः।
इन्द्रजित्त्विति विख्यातो जगत्येष भविष्यति॥', 'ayaṃ ca putro ''tibalas tava rāvaṇarāvaṇiḥ
indrajit tv iti vikhyāto jagaty eṣa bhaviṣyati', null, 7030005),
('ramayana-7-30-6', 6, 'Uttara Kanda, Sarga 30, Verse 6', 'बलवाञ्शत्रुनिर्जेता भविष्यत्येष राक्षसः।
यमाश्रित्य त्वया राजन्स्थापितास्त्रिदशा वशे॥', 'balavāñ śatrunirjetā bhaviṣyaty eṣa rākṣasaḥ
yam āśritya tvayā rājan sthāpitās tridaśā vaśe', null, 7030006),
('ramayana-7-30-7', 7, 'Uttara Kanda, Sarga 30, Verse 7', 'तन्मुच्यतां महाबाहो महेन्द्रः पाकशासनः।
किं चास्य मोक्षणार्थाय प्रयच्छन्ति दिवौकसः॥', 'tan mucyatāṃ mahābāho mahendraḥ pākaśāsanaḥ
kiṃ cāsya mokṣaṇārthāya prayacchanti divaukasaḥ', null, 7030007),
('ramayana-7-30-8', 8, 'Uttara Kanda, Sarga 30, Verse 8', 'अथाब्रवीन्महातेजा इन्द्रजित्समितिंजयः।
अमरत्वमहं देव वृणोमीहास्य मोक्षणे॥', 'athābravīn mahātejā indrajit samitiṃjayaḥ
amaratvam ahaṃ deva vṛṇomīhāsya mokṣaṇe', null, 7030008),
('ramayana-7-30-9', 9, 'Uttara Kanda, Sarga 30, Verse 9', 'अब्रवीत्तु तदा देवो रावणिं कमलोद्भवः।
नास्ति सर्वामरत्वं हि केषां चित्प्राणिनां भुवि॥', 'abravīt tu tadā devo rāvaṇiṃ kamalodbhavaḥ
nāsti sarvāmaratvaṃ hi keṣāṃ cit prāṇināṃ bhuvi', null, 7030009),
('ramayana-7-30-10', 10, 'Uttara Kanda, Sarga 30, Verse 10', 'अथाब्रवीत्स तत्रस्थमिन्द्रजित्पद्मसंभवम्।
श्रूयतां या भवेत्सिद्धिः शतक्रतुविमोक्षणे॥', 'athābravīt sa tatrastham indrajit padmasaṃbhavam
śrūyatāṃ yā bhavet siddhiḥ śatakratuvimokṣaṇe', null, 7030010),
('ramayana-7-30-11', 11, 'Uttara Kanda, Sarga 30, Verse 11', 'ममेष्टं नित्यशो देव हव्यैः संपूज्य पावकम्।
संग्राममवतर्तुं वै शत्रुनिर्जयकाङ्क्षिणः॥', 'mameṣṭaṃ nityaśo deva havyaiḥ saṃpūjya pāvakam
saṃgrāmam avatartuṃ vai śatrunirjayakāṅkṣiṇaḥ', null, 7030011),
('ramayana-7-30-12', 12, 'Uttara Kanda, Sarga 30, Verse 12', 'तस्मिंश्चेदसमाप्ते तु जप्यहोमे विभावसोः।
युध्येयं देव संग्रामे तदा मे स्याद्विनाशनम्॥', 'tasmiṃś ced asamāpte tu japyahome vibhāvasoḥ
yudhyeyaṃ deva saṃgrāme tadā me syād vināśanam', null, 7030012),
('ramayana-7-30-13', 13, 'Uttara Kanda, Sarga 30, Verse 13', 'सर्वो हि तपसा चैव वृणोत्यमरतां पुमान्।
विक्रमेण मया त्वेतदमरत्वं प्रवर्तितम्॥', 'sarvo hi tapasā caiva vṛṇoty amaratāṃ pumān
vikrameṇa mayā tv etad amaratvaṃ pravartitam', null, 7030013),
('ramayana-7-30-14', 14, 'Uttara Kanda, Sarga 30, Verse 14', 'एवमस्त्विति तं प्राह वाक्यं देवः प्रजापतिः।
मुक्तश्चेन्द्रजिता शक्रो गताश्च त्रिदिवं सुराः॥', 'evam astv iti taṃ prāha vākyaṃ devaḥ prajāpatiḥ
muktaś cendrajitā śakro gatāś ca tridivaṃ surāḥ', null, 7030014),
('ramayana-7-30-15', 15, 'Uttara Kanda, Sarga 30, Verse 15', 'एतस्मिन्नन्तरे शक्रो दीनो भ्रष्टाम्बरस्रजः।
राम चिन्तापरीतात्मा ध्यानतत्परतां गतः॥', 'etasminn antare śakro dīno bhraṣṭāmbarasrajaḥ
rāma cintāparītātmā dhyānatatparatāṃ gataḥ', null, 7030015),
('ramayana-7-30-16', 16, 'Uttara Kanda, Sarga 30, Verse 16', 'तं तु दृष्ट्वा तथाभूतं प्राह देवः प्रजापतिः।
शक्रक्रतो किमुत्कण्ठां करोषि स्मर दुष्कृतम्॥', 'taṃ tu dṛṣṭvā tathābhūtaṃ prāha devaḥ prajāpatiḥ
śakrakrato kim utkaṇṭhāṃ karoṣi smara duṣkṛtam', null, 7030016),
('ramayana-7-30-17', 17, 'Uttara Kanda, Sarga 30, Verse 17', 'अमरेन्द्र मया बह्व्यः प्रजाः सृष्टाः पुरा प्रभो।
एकवर्णाः समाभाषा एकरूपाश्च सर्वशः॥', 'amarendra mayā bahvyaḥ prajāḥ sṛṣṭāḥ purā prabho
ekavarṇāḥ samābhāṣā ekarūpāś ca sarvaśaḥ', null, 7030017),
('ramayana-7-30-18', 18, 'Uttara Kanda, Sarga 30, Verse 18', 'तासां नास्ति विशेषो हि दर्शने लक्षणेऽपि वा।
ततोऽहमेकाग्रमनास्ताः प्रजाः पर्यचिन्तयम्॥', 'tāsāṃ nāsti viśeṣo hi darśane lakṣaṇe ''pi vā
tato ''ham ekāgramanās tāḥ prajāḥ paryacintayam', null, 7030018),
('ramayana-7-30-19', 19, 'Uttara Kanda, Sarga 30, Verse 19', 'सोऽहं तासां विशेषार्थं स्त्रियमेकां विनिर्ममे।
यद्यत्प्रजानां प्रत्यङ्गं विशिष्टं तत्तदुद्धृतम्॥', 'so ''haṃ tāsāṃ viśeṣārthaṃ striyam ekāṃ vinirmame
yad yat prajānāṃ pratyaṅgaṃ viśiṣṭaṃ tat tad uddhṛtam', null, 7030019),
('ramayana-7-30-20', 20, 'Uttara Kanda, Sarga 30, Verse 20', 'ततो मया रूपगुणैरहल्या स्त्री विनिर्मिता।
अहल्येत्येव च मया तस्या नाम प्रवर्तितम्॥', 'tato mayā rūpaguṇair ahalyā strī vinirmitā
ahalyety eva ca mayā tasyā nāma pravartitam', null, 7030020),
('ramayana-7-30-21', 21, 'Uttara Kanda, Sarga 30, Verse 21', 'निर्मितायां तु देवेन्द्र तस्यां नार्यां सुरर्षभ।
भविष्यतीति कस्यैषा मम चिन्ता ततोऽभवत्॥', 'nirmitāyāṃ tu devendra tasyāṃ nāryāṃ surarṣabha
bhaviṣyatīti kasyaiṣā mama cintā tato ''bhavat', null, 7030021),
('ramayana-7-30-22', 22, 'Uttara Kanda, Sarga 30, Verse 22', 'त्वं तु शक्र तदा नारीं जानीषे मनसा प्रभो।
स्थानाधिकतया पत्नी ममैषेति पुरंदर॥', 'tvaṃ tu śakra tadā nārīṃ jānīṣe manasā prabho
sthānādhikatayā patnī mamaiṣeti puraṃdara', null, 7030022),
('ramayana-7-30-23', 23, 'Uttara Kanda, Sarga 30, Verse 23', 'सा मया न्यासभूता तु गौतमस्य महात्मनः।
न्यस्ता बहूनि वर्षाणि तेन निर्यातिता च सा॥', 'sā mayā nyāsabhūtā tu gautamasya mahātmanaḥ
nyastā bahūni varṣāṇi tena niryātitā ca sā', null, 7030023),
('ramayana-7-30-24', 24, 'Uttara Kanda, Sarga 30, Verse 24', 'ततस्तस्य परिज्ञाय मया स्थैर्यं महामुनेः।
ज्ञात्वा तपसि सिद्धिं च पत्न्यर्थं स्पर्शिता तदा॥', 'tatas tasya parijñāya mayā sthairyaṃ mahāmuneḥ
jñātvā tapasi siddhiṃ ca patnyarthaṃ sparśitā tadā', null, 7030024),
('ramayana-7-30-25', 25, 'Uttara Kanda, Sarga 30, Verse 25', 'स तया सह धर्मात्मा रमते स्म महामुनिः।
आसन्निराशा देवास्तु गौतमे दत्तया तया॥', 'sa tayā saha dharmātmā ramate sma mahāmuniḥ
āsan nirāśā devās tu gautame dattayā tayā', null, 7030025),
('ramayana-7-30-26', 26, 'Uttara Kanda, Sarga 30, Verse 26', 'त्वं क्रुद्धस्त्विह कामात्मा गत्वा तस्याश्रमं मुनेः।
दृष्टवांश्च तदा तां स्त्रीं दीप्तामग्निशिखामिव॥', 'tvaṃ kruddhas tv iha kāmātmā gatvā tasyāśramaṃ muneḥ
dṛṣṭavāṃś ca tadā tāṃ strīṃ dīptām agniśikhām iva', null, 7030026),
('ramayana-7-30-27', 27, 'Uttara Kanda, Sarga 30, Verse 27', 'सा त्वया धर्षिता शक्र कामार्तेन समन्युना।
दृष्टस्त्वं च तदा तेन आश्रमे परमर्षिणा॥', 'sā tvayā dharṣitā śakra kāmārtena samanyunā
dṛṣṭas tvaṃ ca tadā tena āśrame paramarṣiṇā', null, 7030027),
('ramayana-7-30-28', 28, 'Uttara Kanda, Sarga 30, Verse 28', 'ततः क्रुद्धेन तेनासि शप्तः परमतेजसा।
गतोऽसि येन देवेन्द्र दशाभागविपर्ययम्॥', 'tataḥ kruddhena tenāsi śaptaḥ paramatejasā
gato ''si yena devendra daśābhāgaviparyayam', null, 7030028),
('ramayana-7-30-29', 29, 'Uttara Kanda, Sarga 30, Verse 29', 'यस्मान्मे धर्षिता पत्नी त्वया वासव निर्भयम्।
तस्मात्त्वं समरे राजञ्शत्रुहस्तं गमिष्यसि॥', 'yasmān me dharṣitā patnī tvayā vāsava nirbhayam
tasmāt tvaṃ samare rājañ śatruhastaṃ gamiṣyasi', null, 7030029),
('ramayana-7-30-30', 30, 'Uttara Kanda, Sarga 30, Verse 30', 'अयं तु भावो दुर्बुद्धे यस्त्वयेह प्रवर्तितः।
मानुषेष्वपि सर्वेषु भविष्यति न संशयः॥', 'ayaṃ tu bhāvo durbuddhe yas tvayeha pravartitaḥ
mānuṣeṣv api sarveṣu bhaviṣyati na saṃśayaḥ', null, 7030030),
('ramayana-7-30-31', 31, 'Uttara Kanda, Sarga 30, Verse 31', 'तत्राधर्मः सुबलवान्समुत्थास्यति यो महान्।
तत्रार्धं तस्य यः कर्ता त्वय्यर्धं निपतिष्यति॥', 'tatrādharmaḥ subalavān samutthāsyati yo mahān
tatrārdhaṃ tasya yaḥ kartā tvayy ardhaṃ nipatiṣyati', null, 7030031),
('ramayana-7-30-32', 32, 'Uttara Kanda, Sarga 30, Verse 32', 'न च ते स्थावरं स्थानं भविष्यति पुरंदर।
एतेनाधर्मयोगेन यस्त्वयेह प्रवर्तितः॥', 'na ca te sthāvaraṃ sthānaṃ bhaviṣyati puraṃdara
etenādharmayogena yas tvayeha pravartitaḥ', null, 7030032),
('ramayana-7-30-33', 33, 'Uttara Kanda, Sarga 30, Verse 33', 'यश्च यश्च सुरेन्द्रः स्याद्ध्रुवः स न भविष्यति।
एष शापो मया मुक्त इत्यसौ त्वां तदाब्रवीत्॥', 'yaś ca yaś ca surendraḥ syād dhruvaḥ sa na bhaviṣyati
eṣa śāpo mayā mukta ity asau tvāṃ tadābravīt', null, 7030033),
('ramayana-7-30-34', 34, 'Uttara Kanda, Sarga 30, Verse 34', 'तां तु भार्यां विनिर्भर्त्स्य सोऽब्रवीत्सुमहातपाः।
दुर्विनीते विनिध्वंस ममाश्रमसमीपतः॥', 'tāṃ tu bhāryāṃ vinirbhartsya so ''bravīt sumahātapāḥ
durvinīte vinidhvaṃsa mamāśramasamīpataḥ', null, 7030034),
('ramayana-7-30-35', 35, 'Uttara Kanda, Sarga 30, Verse 35', 'रूपयौवनसंपन्ना यस्मात्त्वमनवस्थिता।
तस्माद्रूपवती लोके न त्वमेका भविष्यसि॥', 'rūpayauvanasaṃpannā yasmāt tvam anavasthitā
tasmād rūpavatī loke na tvam ekā bhaviṣyasi', null, 7030035),
('ramayana-7-30-36', 36, 'Uttara Kanda, Sarga 30, Verse 36', 'रूपं च तत्प्रजाः सर्वा गमिष्यन्ति सुदुर्लभम्।
यत्तवेदं समाश्रित्य विभ्रमेऽयमुपस्थितः॥', 'rūpaṃ ca tat prajāḥ sarvā gamiṣyanti sudurlabham
yat tavedaṃ samāśritya vibhrame ''yam upasthitaḥ', null, 7030036),
('ramayana-7-30-37', 37, 'Uttara Kanda, Sarga 30, Verse 37', 'तदा प्रभृति भूयिष्ठं प्रजा रूपसमन्विताः।
शापोत्सर्गाद्धि तस्येदं मुनेः सर्वमुपागतम्॥', 'tadā prabhṛti bhūyiṣṭhaṃ prajā rūpasamanvitāḥ
śāpotsargād dhi tasyedaṃ muneḥ sarvam upāgatam', null, 7030037),
('ramayana-7-30-38', 38, 'Uttara Kanda, Sarga 30, Verse 38', 'तत्स्मर त्वं महाबाहो दुष्कृतं यत्त्वया कृतम्।
येन त्वं ग्रहणं शत्रोर्गतो नान्येन वासव॥', 'tat smara tvaṃ mahābāho duṣkṛtaṃ yat tvayā kṛtam
yena tvaṃ grahaṇaṃ śatror gato nānyena vāsava', null, 7030038),
('ramayana-7-30-39', 39, 'Uttara Kanda, Sarga 30, Verse 39', 'शीघ्रं यजस्व यज्ञं त्वं वैष्णवं सुसमाहितः।
पावितस्तेन यज्ञेन यास्यसि त्रिदिवं ततः॥', 'śīghraṃ yajasva yajñaṃ tvaṃ vaiṣṇavaṃ susamāhitaḥ
pāvitas tena yajñena yāsyasi tridivaṃ tataḥ', null, 7030039),
('ramayana-7-30-40', 40, 'Uttara Kanda, Sarga 30, Verse 40', 'पुत्रश्च तव देवेन्द्र न विनष्टो महारणे।
नीतः संनिहितश्चैव अर्यकेण महोदधौ॥', 'putraś ca tava devendra na vinaṣṭo mahāraṇe
nītaḥ saṃnihitaś caiva aryakeṇa mahodadhau', null, 7030040),
('ramayana-7-30-41', 41, 'Uttara Kanda, Sarga 30, Verse 41', 'एतच्छ्रुत्वा महेन्द्रस्तु यज्ञमिष्ट्वा च वैष्णवम्।
पुनस्त्रिदिवमाक्रामदन्वशासच्च देवताः॥', 'etac chrutvā mahendras tu yajñam iṣṭvā ca vaiṣṇavam
punas tridivam ākrāmad anvaśāsac ca devatāḥ', null, 7030041),
('ramayana-7-30-42', 42, 'Uttara Kanda, Sarga 30, Verse 42', 'एतदिन्द्रजितो राम बलं यत्कीर्तितं मया।
निर्जितस्तेन देवेन्द्रः प्राणिनोऽन्ये च किं पुनः॥', 'etad indrajito rāma balaṃ yat kīrtitaṃ mayā
nirjitas tena devendraḥ prāṇino ''nye ca kiṃ punaḥ', null, 7030042)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 31 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-31-1', 1, 'Uttara Kanda, Sarga 31, Verse 1', 'ततो रामो महातेजा विस्मयात्पुनरेव हि।
उवाच प्रणतो वाक्यमगस्त्यमृषिसत्तमम्॥', 'tato rāmo mahātejā vismayāt punar eva hi
uvāca praṇato vākyam agastyam ṛṣisattamam', null, 7031001),
('ramayana-7-31-2', 2, 'Uttara Kanda, Sarga 31, Verse 2', 'भगवन्किं तदा लोकाः शून्या आसन्द्विजोत्तम।
धर्षणां यत्र न प्राप्तो रावणो राक्षसेश्वरः॥', 'bhagavan kiṃ tadā lokāḥ śūnyā āsan dvijottama
dharṣaṇāṃ yatra na prāpto rāvaṇo rākṣaseśvaraḥ', null, 7031002),
('ramayana-7-31-3', 3, 'Uttara Kanda, Sarga 31, Verse 3', 'उताहो हीनवीर्यास्ते बभुवुः पृथिवीक्षितः।
बहिष्कृता वरास्त्रैश्च बहवो निर्जिता नृपाः॥', 'utāho hīnavīryās te babhuvuḥ pṛthivīkṣitaḥ
bahiṣkṛtā varāstraiś ca bahavo nirjitā nṛpāḥ', null, 7031003),
('ramayana-7-31-4', 4, 'Uttara Kanda, Sarga 31, Verse 4', 'राघवस्य वचः श्रुत्वा अगस्त्यो भगवानृषिः।
उवाच रामं प्रहसन्पितामह इवेश्वरम्॥', 'rāghavasya vacaḥ śrutvā agastyo bhagavān ṛṣiḥ
uvāca rāmaṃ prahasan pitāmaha iveśvaram', null, 7031004),
('ramayana-7-31-5', 5, 'Uttara Kanda, Sarga 31, Verse 5', 'स एवं बाधमानस्तु पार्थिवान्पार्थिवर्षभ।
चचार रावणो राम पृथिव्यां पृथिवीपते॥', 'sa evaṃ bādhamānas tu pārthivān pārthivarṣabha
cacāra rāvaṇo rāma pṛthivyāṃ pṛthivīpate', null, 7031005),
('ramayana-7-31-6', 6, 'Uttara Kanda, Sarga 31, Verse 6', 'ततो माहिष्मतीं नाम पुरीं स्वर्गपुरीप्रभाम्।
संप्राप्तो यत्र साम्निध्यं परमं वसुरेतसः॥', 'tato māhiṣmatīṃ nāma purīṃ svargapurīprabhām
saṃprāpto yatra sāmnidhyaṃ paramaṃ vasuretasaḥ', null, 7031006),
('ramayana-7-31-7', 7, 'Uttara Kanda, Sarga 31, Verse 7', 'तुल्य आसीन्नृपस्तस्य प्रतापाद्वसुरेतसः।
अर्जुनो नाम यस्याग्निः शरकुण्डे शयः सदा॥', 'tulya āsīn nṛpas tasya pratāpād vasuretasaḥ
arjuno nāma yasyāgniḥ śarakuṇḍe śayaḥ sadā', null, 7031007),
('ramayana-7-31-8', 8, 'Uttara Kanda, Sarga 31, Verse 8', 'तमेव दिवसं सोऽथ हैहयाधिपतिर्बली।
अर्जुनो नर्मदां रन्तुं गतः स्त्रीभिः सहेश्वरः॥', 'tam eva divasaṃ so ''tha haihayādhipatir balī
arjuno narmadāṃ rantuṃ gataḥ strībhiḥ saheśvaraḥ', null, 7031008),
('ramayana-7-31-9', 9, 'Uttara Kanda, Sarga 31, Verse 9', 'रावणो राक्षसेन्द्रस्तु तस्यामात्यानपृच्छत।
क्वार्जुनो वो नृपः सोऽद्य शीघ्रमाख्यातुमर्हथ॥', 'rāvaṇo rākṣasendras tu tasyāmātyān apṛcchata
kvārjuno vo nṛpaḥ so ''dya śīghram ākhyātum arhatha', null, 7031009),
('ramayana-7-31-10', 10, 'Uttara Kanda, Sarga 31, Verse 10', 'रावणोऽहमनुप्राप्तो युद्धेप्सुर्नृवरेण तु।
ममागमनमव्यग्रैर्युष्माभिः संनिवेद्यताम्॥', 'rāvaṇo ''ham anuprāpto yuddhepsur nṛvareṇa tu
mamāgamanam avyagrair yuṣmābhiḥ saṃnivedyatām', null, 7031010),
('ramayana-7-31-11', 11, 'Uttara Kanda, Sarga 31, Verse 11', 'इत्येवं रावणेनोक्तास्तेऽमात्याः सुविपश्चितः।
अब्रुवन्राक्षसपतिमसाम्निध्यं महीपतेः॥', 'ity evaṃ rāvaṇenoktās te ''mātyāḥ suvipaścitaḥ
abruvan rākṣasapatim asāmnidhyaṃ mahīpateḥ', null, 7031011),
('ramayana-7-31-12', 12, 'Uttara Kanda, Sarga 31, Verse 12', 'श्रुत्वा विश्रवसः पुत्रः पौराणामर्जुनं गतम्।
अपसृत्यागतो विन्ध्यं हिमवत्संनिभं गिरिम्॥', 'śrutvā viśravasaḥ putraḥ paurāṇām arjunaṃ gatam
apasṛtyāgato vindhyaṃ himavatsaṃnibhaṃ girim', null, 7031012),
('ramayana-7-31-13', 13, 'Uttara Kanda, Sarga 31, Verse 13', 'स तमभ्रमिवाविष्टमुद्भ्रान्तमिव मेदिनीम्।
अपश्यद्रावणो विन्ध्यमालिखन्तमिवाम्बरम्॥', 'sa tam abhram ivāviṣṭam udbhrāntam iva medinīm
apaśyad rāvaṇo vindhyam ālikhantam ivāmbaram', null, 7031013),
('ramayana-7-31-14', 14, 'Uttara Kanda, Sarga 31, Verse 14', 'सहस्रशिखरोपेतं सिंहाध्युषितकन्दरम्।
प्रपात पतितैः शीतैः साट्टहासमिवाम्बुभिः॥', 'sahasraśikharopetaṃ siṃhādhyuṣitakandaram
prapāta patitaiḥ śītaiḥ sāṭṭahāsam ivāmbubhiḥ', null, 7031014),
('ramayana-7-31-15', 15, 'Uttara Kanda, Sarga 31, Verse 15', 'देवदानवगन्धर्वैः साप्सरोगणकिंनरैः।
साह स्त्रीभिः क्रीडमानैः स्वर्गभूतं महोच्छ्रयम्॥', 'devadānavagandharvaiḥ sāpsarogaṇakiṃnaraiḥ
sāha strībhiḥ krīḍamānaiḥ svargabhūtaṃ mahocchrayam', null, 7031015),
('ramayana-7-31-16', 16, 'Uttara Kanda, Sarga 31, Verse 16', 'नदीभिः स्यन्दमानाभिरगतिप्रतिमं जलम्।
स्फुटीभिश्चलजिह्वाभिर्वमन्तमिव विष्ठितम्॥', 'nadībhiḥ syandamānābhir agatipratimaṃ jalam
sphuṭībhiś calajihvābhir vamantam iva viṣṭhitam', null, 7031016),
('ramayana-7-31-17', 17, 'Uttara Kanda, Sarga 31, Verse 17', 'उल्कावन्तं दरीवन्तं हिमवत्संनिभं गिरिम्।
पश्यमानस्ततो विन्ध्यं रावणो नर्मदां ययौ॥', 'ulkāvantaṃ darīvantaṃ himavatsaṃnibhaṃ girim
paśyamānas tato vindhyaṃ rāvaṇo narmadāṃ yayau', null, 7031017),
('ramayana-7-31-18', 18, 'Uttara Kanda, Sarga 31, Verse 18', 'चलोपलजलां पुण्यां पश्चिमोदधिगामिनीम्।
महिषैः सृमरैः सिंहैः शार्दूलर्क्षगजोत्तमैः।
उष्णाभितप्तैस्तृषितैः संक्षोभितजलाशयाम्॥', 'calopalajalāṃ puṇyāṃ paścimodadhigāminīm
mahiṣaiḥ sṛmaraiḥ siṃhaiḥ śārdūlarkṣagajottamaiḥ
uṣṇābhitaptais tṛṣitaiḥ saṃkṣobhitajalāśayām', null, 7031018),
('ramayana-7-31-19', 19, 'Uttara Kanda, Sarga 31, Verse 19', 'चक्रवाकैः सकारण्डैः सहंसजलकुक्कुटैः।
सारसैश्च सदामत्तैः कोकूजद्भिः समावृताम्॥', 'cakravākaiḥ sakāraṇḍaiḥ sahaṃsajalakukkuṭaiḥ
sārasaiś ca sadāmattaiḥ kokūjadbhiḥ samāvṛtām', null, 7031019),
('ramayana-7-31-20', 20, 'Uttara Kanda, Sarga 31, Verse 20', 'फुल्लद्रुमकृतोत्तंसां चक्रवाकयुगस्तनीम्।
विस्तीर्णपुलिनश्रोणीं हंसावलिसुमेखलाम्॥', 'phulladrumakṛtottaṃsāṃ cakravākayugastanīm
vistīrṇapulinaśroṇīṃ haṃsāvalisumekhalām', null, 7031020),
('ramayana-7-31-21', 21, 'Uttara Kanda, Sarga 31, Verse 21', 'पुष्परेण्वनुलिप्ताङ्गीं जलफेनामलांशुकाम्।
जलावगाहसंस्पर्शां फुल्लोत्पलशुभेक्षणाम्॥', 'puṣpareṇvanuliptāṅgīṃ jalaphenāmalāṃśukām
jalāvagāhasaṃsparśāṃ phullotpalaśubhekṣaṇām', null, 7031021),
('ramayana-7-31-22', 22, 'Uttara Kanda, Sarga 31, Verse 22', 'पुष्पकादवरुह्याशु नर्मदां सरितां वराम्।
इष्टामिव वरां नारीमवगाह्य दशाननः॥', 'puṣpakād avaruhyāśu narmadāṃ saritāṃ varām
iṣṭām iva varāṃ nārīm avagāhya daśānanaḥ', null, 7031022),
('ramayana-7-31-23', 23, 'Uttara Kanda, Sarga 31, Verse 23', 'स तस्याः पुलिने रम्ये नानाकुसुमशोभिते।
उपोपविष्टः सचिवैः सार्धं राक्षसपुंगवः।
नर्मदा दर्शजं हर्षमाप्तवान्राक्षसेश्वरः॥', 'sa tasyāḥ puline ramye nānākusumaśobhite
upopaviṣṭaḥ sacivaiḥ sārdhaṃ rākṣasapuṃgavaḥ
narmadā darśajaṃ harṣam āptavān rākṣaseśvaraḥ', null, 7031023),
('ramayana-7-31-24', 24, 'Uttara Kanda, Sarga 31, Verse 24', 'ततः सलीलं प्रहसान्रावणो राक्षसाधिपः।
उवाच सचिवांस्तत्र मारीचशुकसारणान्॥', 'tataḥ salīlaṃ prahasān rāvaṇo rākṣasādhipaḥ
uvāca sacivāṃs tatra mārīcaśukasāraṇān', null, 7031024),
('ramayana-7-31-25', 25, 'Uttara Kanda, Sarga 31, Verse 25', 'एष रश्मिसहस्रेण जगत्कृत्वेव काञ्चनम्।
तीक्ष्णतापकरः सूर्यो नभसो मध्यमास्थितः।
मामासीनं विदित्वेह चन्द्रायाति दिवाकरः॥', 'eṣa raśmisahasreṇa jagat kṛtveva kāñcanam
tīkṣṇatāpakaraḥ sūryo nabhaso madhyam āsthitaḥ
mām āsīnaṃ viditveha candrāyāti divākaraḥ', null, 7031025),
('ramayana-7-31-26', 26, 'Uttara Kanda, Sarga 31, Verse 26', 'नर्मदा जलशीतश्च सुगन्धिः श्रमनाशनः।
मद्भयादनिलो ह्येष वात्यसौ सुसमाहितः॥', 'narmadā jalaśītaś ca sugandhiḥ śramanāśanaḥ
madbhayād anilo hy eṣa vāty asau susamāhitaḥ', null, 7031026),
('ramayana-7-31-27', 27, 'Uttara Kanda, Sarga 31, Verse 27', 'इयं चापि सरिच्छ्रेष्ठा नर्मदा नर्म वर्धिनी।
लीनमीनविहंगोर्मिः सभयेवाङ्गना स्थिता॥', 'iyaṃ cāpi saricchreṣṭhā narmadā narma vardhinī
līnamīnavihaṃgormiḥ sabhayevāṅganā sthitā', null, 7031027),
('ramayana-7-31-28', 28, 'Uttara Kanda, Sarga 31, Verse 28', 'तद्भवन्तः क्षताः शस्त्रैर्नृपैरिन्द्रसमैर्युधि।
चन्दनस्य रसेनेव रुधिरेण समुक्षिताः॥', 'tad bhavantaḥ kṣatāḥ śastrair nṛpair indrasamair yudhi
candanasya raseneva rudhireṇa samukṣitāḥ', null, 7031028),
('ramayana-7-31-29', 29, 'Uttara Kanda, Sarga 31, Verse 29', 'ते यूयमवगाहध्वं नर्मदां शर्मदां नृणाम्।
महापद्ममुखा मत्ता गङ्गामिव महागजाः॥', 'te yūyam avagāhadhvaṃ narmadāṃ śarmadāṃ nṛṇām
mahāpadmamukhā mattā gaṅgām iva mahāgajāḥ', null, 7031029),
('ramayana-7-31-30', 30, 'Uttara Kanda, Sarga 31, Verse 30', 'अस्यां स्नात्वा महानद्यां पाप्मानं विप्रमोक्ष्यथ॥', 'asyāṃ snātvā mahānadyāṃ pāpmānaṃ vipramokṣyatha', null, 7031030),
('ramayana-7-31-31', 31, 'Uttara Kanda, Sarga 31, Verse 31', 'अहमप्यत्र पुलिने शरदिन्दुसमप्रभे।
पुष्पोपहरं शनकैः करिष्यामि उमापतेः॥', 'aham apy atra puline śaradindusamaprabhe
puṣpopaharaṃ śanakaiḥ kariṣyāmi umāpateḥ', null, 7031031),
('ramayana-7-31-32', 32, 'Uttara Kanda, Sarga 31, Verse 32', 'रावणेनैवमुक्तास्तु मारीचशुकसारणाः।
समहोदरधूम्राक्षा नर्मदामवगाहिरे॥', 'rāvaṇenaivam uktās tu mārīcaśukasāraṇāḥ
samahodaradhūmrākṣā narmadām avagāhire', null, 7031032),
('ramayana-7-31-33', 33, 'Uttara Kanda, Sarga 31, Verse 33', 'राक्षसेन्द्रगजैस्तैस्तु क्षोभ्यते नर्मदा नदी।
वामनाञ्जनपद्माद्यैर्गङ्गा इव महागजैः॥', 'rākṣasendragajais tais tu kṣobhyate narmadā nadī
vāmanāñjanapadmādyair gaṅgā iva mahāgajaiḥ', null, 7031033),
('ramayana-7-31-34', 34, 'Uttara Kanda, Sarga 31, Verse 34', 'ततस्ते राक्षसाः स्नात्वा नर्मदाया वराम्भसि।
उत्तीर्य पुष्पाण्याजह्रुर्बल्यर्थं रावणस्य तु॥', 'tatas te rākṣasāḥ snātvā narmadāyā varāmbhasi
uttīrya puṣpāṇy ājahrur balyarthaṃ rāvaṇasya tu', null, 7031034),
('ramayana-7-31-35', 35, 'Uttara Kanda, Sarga 31, Verse 35', 'नर्मदा पुलिने रम्ये शुभ्राभ्रसदृशप्रभे।
राक्षसेन्द्रैर्मुहूर्तेन कृतः पुष्पमयो गिरिः॥', 'narmadā puline ramye śubhrābhrasadṛśaprabhe
rākṣasendrair muhūrtena kṛtaḥ puṣpamayo giriḥ', null, 7031035),
('ramayana-7-31-36', 36, 'Uttara Kanda, Sarga 31, Verse 36', 'पुष्पेषूपहृतेष्वेव रावणो राक्षसेश्वरः।
अवतीर्णो नदीं स्नातुं गङ्गामिव महागजः॥', 'puṣpeṣūpahṛteṣv eva rāvaṇo rākṣaseśvaraḥ
avatīrṇo nadīṃ snātuṃ gaṅgām iva mahāgajaḥ', null, 7031036),
('ramayana-7-31-37', 37, 'Uttara Kanda, Sarga 31, Verse 37', 'तत्र स्नात्वा च विधिवज्जप्त्वा जप्यमनुत्तमम्।
नर्मदा सलिलात्तस्मादुत्ततार स रावणः॥', 'tatra snātvā ca vidhivaj japtvā japyam anuttamam
narmadā salilāt tasmād uttatāra sa rāvaṇaḥ', null, 7031037),
('ramayana-7-31-38', 38, 'Uttara Kanda, Sarga 31, Verse 38', 'रावणं प्राञ्जलिं यान्तमन्वयुः सप्तराक्षसाः।
यत्र यत्र स याति स्म रावणो राक्षसाधिपः।
जाम्बूनदमयं लिङ्गं तत्र तत्र स्म नीयते॥', 'rāvaṇaṃ prāñjaliṃ yāntam anvayuḥ saptarākṣasāḥ
yatra yatra sa yāti sma rāvaṇo rākṣasādhipaḥ
jāmbūnadamayaṃ liṅgaṃ tatra tatra sma nīyate', null, 7031038),
('ramayana-7-31-39', 39, 'Uttara Kanda, Sarga 31, Verse 39', 'वालुकवेदिमध्ये तु तल्लिङ्गं स्थाप्य रावणः।
अर्चयामास गन्धैश्च पुष्पैश्चामृतगन्धिभिः॥', 'vālukavedimadhye tu tal liṅgaṃ sthāpya rāvaṇaḥ
arcayām āsa gandhaiś ca puṣpaiś cāmṛtagandhibhiḥ', null, 7031039),
('ramayana-7-31-40', 40, 'Uttara Kanda, Sarga 31, Verse 40', 'ततः सतामार्तिहरं हरं परं वरप्रदं चन्द्रमयूखभूषणम्।
समर्चयित्वा स निशाचरो जगौ प्रसार्य हस्तान्प्रणनर्त चायतान्॥', 'tataḥ satām ārtiharaṃ haraṃ paraṃ varapradaṃ candramayūkhabhūṣaṇam
samarcayitvā sa niśācaro jagau prasārya hastān praṇanarta cāyatān', null, 7031040)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 32 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-32-1', 1, 'Uttara Kanda, Sarga 32, Verse 1', 'नर्मदा पुलिने यत्र राक्षसेन्द्रः स रावणः।
पुष्पोपहारं कुरुते तस्माद्देशाददूरतः॥', 'narmadā puline yatra rākṣasendraḥ sa rāvaṇaḥ
puṣpopahāraṃ kurute tasmād deśād adūrataḥ', null, 7032001),
('ramayana-7-32-2', 2, 'Uttara Kanda, Sarga 32, Verse 2', 'अर्जुनो जयतां श्रेष्ठो माहिष्मत्याः पतिः प्रभुः।
क्रीडिते सह नारीभिर्नर्मदातोयमाश्रितः॥', 'arjuno jayatāṃ śreṣṭho māhiṣmatyāḥ patiḥ prabhuḥ
krīḍite saha nārībhir narmadātoyam āśritaḥ', null, 7032002),
('ramayana-7-32-3', 3, 'Uttara Kanda, Sarga 32, Verse 3', 'तासां मध्यगतो राज रराज स ततोऽर्जुनः।
करेणूनां सहस्रस्य मध्यस्थ इव कुञ्जरः॥', 'tāsāṃ madhyagato rāja rarāja sa tato ''rjunaḥ
kareṇūnāṃ sahasrasya madhyastha iva kuñjaraḥ', null, 7032003),
('ramayana-7-32-4', 4, 'Uttara Kanda, Sarga 32, Verse 4', 'जिज्ञासुः स तु बाहूनां सहस्रस्योत्तमं बलम्।
रुरोध नर्मदा वेगं बाहुभिः स तदार्जुनः॥', 'jijñāsuḥ sa tu bāhūnāṃ sahasrasyottamaṃ balam
rurodha narmadā vegaṃ bāhubhiḥ sa tadārjunaḥ', null, 7032004),
('ramayana-7-32-5', 5, 'Uttara Kanda, Sarga 32, Verse 5', 'कार्तवीर्यभुजासेतुं तज्जलं प्राप्य निर्मलम्।
कूलापहारं कुर्वाणं प्रतिस्रोतः प्रधावति॥', 'kārtavīryabhujāsetuṃ taj jalaṃ prāpya nirmalam
kūlāpahāraṃ kurvāṇaṃ pratisrotaḥ pradhāvati', null, 7032005),
('ramayana-7-32-6', 6, 'Uttara Kanda, Sarga 32, Verse 6', 'समीननक्रमकरः सपुष्पकुशसंस्तरः।
स नर्मदाम्भसो वेगः प्रावृट्काल इवाबभौ॥', 'samīnanakramakaraḥ sapuṣpakuśasaṃstaraḥ
sa narmadāmbhaso vegaḥ prāvṛṭkāla ivābabhau', null, 7032006),
('ramayana-7-32-7', 7, 'Uttara Kanda, Sarga 32, Verse 7', 'स वेगः कार्तवीर्येण संप्रेषिट इवाम्भसः।
पुष्पोपहारं तत्सर्वं रावणस्य जहार ह॥', 'sa vegaḥ kārtavīryeṇa saṃpreṣiṭa ivāmbhasaḥ
puṣpopahāraṃ tat sarvaṃ rāvaṇasya jahāra ha', null, 7032007),
('ramayana-7-32-8', 8, 'Uttara Kanda, Sarga 32, Verse 8', 'रावणोऽर्धसमाप्तं तु उत्सृज्य नियमं तदा।
नर्मदां पश्यते कान्तां प्रतिकूलां यथा प्रियाम्॥', 'rāvaṇo ''rdhasamāptaṃ tu utsṛjya niyamaṃ tadā
narmadāṃ paśyate kāntāṃ pratikūlāṃ yathā priyām', null, 7032008),
('ramayana-7-32-9', 9, 'Uttara Kanda, Sarga 32, Verse 9', 'पश्चिमेन तु तं दृष्ट्वा सागरोद्गारसंनिभम्।
वर्धन्तमम्भसो वेगं पूर्वामाशां प्रविश्य तु॥', 'paścimena tu taṃ dṛṣṭvā sāgarodgārasaṃnibham
vardhantam ambhaso vegaṃ pūrvām āśāṃ praviśya tu', null, 7032009),
('ramayana-7-32-10', 10, 'Uttara Kanda, Sarga 32, Verse 10', 'ततोऽनुद्भ्रान्तशकुनां स्वाभाव्ये परमे स्थिताम्।
निर्विकाराङ्गनाभासां पश्यते रावणो नदीम्॥', 'tato ''nudbhrāntaśakunāṃ svābhāvye parame sthitām
nirvikārāṅganābhāsāṃ paśyate rāvaṇo nadīm', null, 7032010),
('ramayana-7-32-11', 11, 'Uttara Kanda, Sarga 32, Verse 11', 'सव्येतरकराङ्गुल्या सशब्दं च दशाननः।
वेगप्रभवमन्वेष्टुं सोऽदिशच्छुकसारणौ॥', 'savyetarakarāṅgulyā saśabdaṃ ca daśānanaḥ
vegaprabhavam anveṣṭuṃ so ''diśac chukasāraṇau', null, 7032011),
('ramayana-7-32-12', 12, 'Uttara Kanda, Sarga 32, Verse 12', 'तौ तु रावणसंदिष्टौ भ्रातरौ शुकसारणौ।
व्योमान्तरचरौ वीरौ प्रस्थितौ पश्चिमोन्मुखौ॥', 'tau tu rāvaṇasaṃdiṣṭau bhrātarau śukasāraṇau
vyomāntaracarau vīrau prasthitau paścimonmukhau', null, 7032012),
('ramayana-7-32-13', 13, 'Uttara Kanda, Sarga 32, Verse 13', 'अर्धयोजनमात्रं तु गत्वा तौ तु निशाचरौ।
पश्येतां पुरुषं तोये क्रीडन्तं सहयोषितम्॥', 'ardhayojanamātraṃ tu gatvā tau tu niśācarau
paśyetāṃ puruṣaṃ toye krīḍantaṃ sahayoṣitam', null, 7032013),
('ramayana-7-32-14', 14, 'Uttara Kanda, Sarga 32, Verse 14', 'बृहत्सालप्रतीकशं तोयव्याकुलमूर्धजम्।
मदरक्तान्तनयनं मदनाकारवर्चसं॥', 'bṛhatsālapratīkaśaṃ toyavyākulamūrdhajam
madaraktāntanayanaṃ madanākāravarcasaṃ', null, 7032014),
('ramayana-7-32-15', 15, 'Uttara Kanda, Sarga 32, Verse 15', 'नदीं बाहुसहस्रेण रुन्धन्तमरिमर्दनम्।
गिरिं पादसहस्रेण रुन्धन्तमिव मेदिनीम्॥', 'nadīṃ bāhusahasreṇa rundhantam arimardanam
giriṃ pādasahasreṇa rundhantam iva medinīm', null, 7032015),
('ramayana-7-32-16', 16, 'Uttara Kanda, Sarga 32, Verse 16', 'बालानां वरनारीणां सहस्रेणाभिसंवृतम्।
समदानां करेणूनां सहस्रेणेव कुञ्जरम्॥', 'bālānāṃ varanārīṇāṃ sahasreṇābhisaṃvṛtam
samadānāṃ kareṇūnāṃ sahasreṇeva kuñjaram', null, 7032016),
('ramayana-7-32-17', 17, 'Uttara Kanda, Sarga 32, Verse 17', 'तमद्भुततमं दृष्ट्वा राक्षसौ शुकसारणौ।
संनिवृत्तावुपागम्य रावणं तमथोचतुः॥', 'tam adbhutatamaṃ dṛṣṭvā rākṣasau śukasāraṇau
saṃnivṛttāv upāgamya rāvaṇaṃ tam athocatuḥ', null, 7032017),
('ramayana-7-32-18', 18, 'Uttara Kanda, Sarga 32, Verse 18', 'बृहत्सालप्रतीकाशः कोऽप्यसौ राक्षसेश्वर।
नर्मदां रोधवद्रुद्ध्वा क्रीडापयति योषितः॥', 'bṛhatsālapratīkāśaḥ ko ''py asau rākṣaseśvara
narmadāṃ rodhavad ruddhvā krīḍāpayati yoṣitaḥ', null, 7032018),
('ramayana-7-32-19', 19, 'Uttara Kanda, Sarga 32, Verse 19', 'तेन बाहुसहस्रेण संनिरुद्धजला नदी।
सागरोद्गारसंकाशानुद्गारान्सृजते मुहुः॥', 'tena bāhusahasreṇa saṃniruddhajalā nadī
sāgarodgārasaṃkāśān udgārān sṛjate muhuḥ', null, 7032019),
('ramayana-7-32-20', 20, 'Uttara Kanda, Sarga 32, Verse 20', 'इत्येवं भाषमाणौ तौ निशम्य शुकसारणौ।
रावणोऽर्जुन इत्युक्त्वा उत्तस्थौ युद्धलालसः॥', 'ity evaṃ bhāṣamāṇau tau niśamya śukasāraṇau
rāvaṇo ''rjuna ity uktvā uttasthau yuddhalālasaḥ', null, 7032020),
('ramayana-7-32-21', 21, 'Uttara Kanda, Sarga 32, Verse 21', 'अर्जुनाभिमुखे तस्मिन्प्रस्थिते राक्षसेश्वरे।
सकृदेव कृतो रावः सरक्तः प्रेषितो घनैः॥', 'arjunābhimukhe tasmin prasthite rākṣaseśvare
sakṛd eva kṛto rāvaḥ saraktaḥ preṣito ghanaiḥ', null, 7032021),
('ramayana-7-32-22', 22, 'Uttara Kanda, Sarga 32, Verse 22', 'महोदरमहापार्श्वधूम्राक्षशुकसारणैः।
संवृतो राक्षसेन्द्रस्तु तत्रागाद्यत्र सोऽर्जुनः॥', 'mahodaramahāpārśvadhūmrākṣaśukasāraṇaiḥ
saṃvṛto rākṣasendras tu tatrāgād yatra so ''rjunaḥ', null, 7032022),
('ramayana-7-32-23', 23, 'Uttara Kanda, Sarga 32, Verse 23', 'नातिदीर्घेण कालेन स ततो राक्षसो बली।
तं नर्मदा ह्रदं भीममाजगामाञ्जनप्रभः॥', 'nātidīrgheṇa kālena sa tato rākṣaso balī
taṃ narmadā hradaṃ bhīmam ājagāmāñjanaprabhaḥ', null, 7032023),
('ramayana-7-32-24', 24, 'Uttara Kanda, Sarga 32, Verse 24', 'स तत्र स्त्रीपरिवृतं वाशिताभिरिव द्विपम्।
नरेन्द्रं पश्यते राजा राक्षसानां तदार्जुनम्॥', 'sa tatra strīparivṛtaṃ vāśitābhir iva dvipam
narendraṃ paśyate rājā rākṣasānāṃ tadārjunam', null, 7032024),
('ramayana-7-32-25', 25, 'Uttara Kanda, Sarga 32, Verse 25', 'स रोषाद्रक्तनयनो राक्षसेन्द्रो बलोद्धतः।
इत्येवमर्जुनामात्यानाह गम्भीरया गिरा॥', 'sa roṣād raktanayano rākṣasendro baloddhataḥ
ity evam arjunāmātyān āha gambhīrayā girā', null, 7032025),
('ramayana-7-32-26', 26, 'Uttara Kanda, Sarga 32, Verse 26', 'अमात्याः क्षिप्रमाख्यात हैहयस्य नृपस्य वै।
युद्धार्थं समनुप्राप्तो रावणो नाम नामतः॥', 'amātyāḥ kṣipram ākhyāta haihayasya nṛpasya vai
yuddhārthaṃ samanuprāpto rāvaṇo nāma nāmataḥ', null, 7032026),
('ramayana-7-32-27', 27, 'Uttara Kanda, Sarga 32, Verse 27', 'रावणस्य वचः श्रुत्वा मन्त्रिणोऽथार्जुनस्य ते।
उत्तस्थुः सायुधास्तं च रावणं वाक्यमब्रुवन्॥', 'rāvaṇasya vacaḥ śrutvā mantriṇo ''thārjunasya te
uttasthuḥ sāyudhās taṃ ca rāvaṇaṃ vākyam abruvan', null, 7032027),
('ramayana-7-32-28', 28, 'Uttara Kanda, Sarga 32, Verse 28', 'युद्धस्य कालो विज्ञातः साधु भोः साधु रावण।
यः क्षीबं स्त्रीवृतं चैव योद्धुमिच्छसि नो नृपम्।
वाशितामध्यगं मत्तं शार्दूल इव कुञ्जरम्॥', 'yuddhasya kālo vijñātaḥ sādhu bhoḥ sādhu rāvaṇa
yaḥ kṣībaṃ strīvṛtaṃ caiva yoddhum icchasi no nṛpam
vāśitāmadhyagaṃ mattaṃ śārdūla iva kuñjaram', null, 7032028),
('ramayana-7-32-29', 29, 'Uttara Kanda, Sarga 32, Verse 29', 'क्षमस्वाद्य दशग्रीव उष्यतां रजनी त्वया।
युद्धश्रद्धा तु यद्यस्ति श्वस्तात समरेऽर्जुनम्॥', 'kṣamasvādya daśagrīva uṣyatāṃ rajanī tvayā
yuddhaśraddhā tu yady asti śvas tāta samare ''rjunam', null, 7032029),
('ramayana-7-32-30', 30, 'Uttara Kanda, Sarga 32, Verse 30', 'यदि वापि त्वरा तुभ्यं युद्धतृष्णासमावृता।
निहत्यास्मांस्ततो युद्धमर्जुनेनोपयास्यसि॥', 'yadi vāpi tvarā tubhyaṃ yuddhatṛṣṇāsamāvṛtā
nihatyāsmāṃs tato yuddham arjunenopayāsyasi', null, 7032030),
('ramayana-7-32-31', 31, 'Uttara Kanda, Sarga 32, Verse 31', 'ततस्ते रावणामात्यैरमात्याः पार्थिवस्य तु।
सूदिताश्चापि ते युद्धे भक्षिताश्च बुभुक्षितैः॥', 'tatas te rāvaṇāmātyair amātyāḥ pārthivasya tu
sūditāś cāpi te yuddhe bhakṣitāś ca bubhukṣitaiḥ', null, 7032031),
('ramayana-7-32-32', 32, 'Uttara Kanda, Sarga 32, Verse 32', 'ततो हलहलाशब्दो नर्मदा तिर आबभौ।
अर्जुनस्यानुयात्राणां रावणस्य च मन्त्रिणाम्॥', 'tato halahalāśabdo narmadā tira ābabhau
arjunasyānuyātrāṇāṃ rāvaṇasya ca mantriṇām', null, 7032032),
('ramayana-7-32-33', 33, 'Uttara Kanda, Sarga 32, Verse 33', 'इषुभिस्तोमरैः शूलैर्वज्रकल्पैः सकर्षणैः।
सरावणानर्दयन्तः समन्तात्समभिद्रुताः॥', 'iṣubhis tomaraiḥ śūlair vajrakalpaiḥ sakarṣaṇaiḥ
sarāvaṇān ardayantaḥ samantāt samabhidrutāḥ', null, 7032033),
('ramayana-7-32-34', 34, 'Uttara Kanda, Sarga 32, Verse 34', 'हैहयाधिपयोधानां वेग आसीत्सुदारुणः।
सनक्रमीनमकरसमुद्रस्येव निस्वनः॥', 'haihayādhipayodhānāṃ vega āsīt sudāruṇaḥ
sanakramīnamakarasamudrasyeva nisvanaḥ', null, 7032034),
('ramayana-7-32-35', 35, 'Uttara Kanda, Sarga 32, Verse 35', 'रावणस्य तु तेऽमात्याः प्रहस्तशुकसारणाः।
कार्तवीर्यबलं क्रुद्धा निर्दहन्त्यग्नितेजसः॥', 'rāvaṇasya tu te ''mātyāḥ prahastaśukasāraṇāḥ
kārtavīryabalaṃ kruddhā nirdahanty agnitejasaḥ', null, 7032035),
('ramayana-7-32-36', 36, 'Uttara Kanda, Sarga 32, Verse 36', 'अर्जुनाय तु तत्कर्म रावणस्य समन्त्रिणः।
क्रीडमानाय कथितं पुरुषैर्द्वाररक्षिभिः॥', 'arjunāya tu tat karma rāvaṇasya samantriṇaḥ
krīḍamānāya kathitaṃ puruṣair dvārarakṣibhiḥ', null, 7032036),
('ramayana-7-32-37', 37, 'Uttara Kanda, Sarga 32, Verse 37', 'उक्त्वा न भेतव्यमिति स्त्रीजनं स ततोऽर्जुनः।
उत्ततार जलात्तस्माद्गङ्गातोयादिवाञ्जनः॥', 'uktvā na bhetavyam iti strījanaṃ sa tato ''rjunaḥ
uttatāra jalāt tasmād gaṅgātoyād ivāñjanaḥ', null, 7032037),
('ramayana-7-32-38', 38, 'Uttara Kanda, Sarga 32, Verse 38', 'क्रोधदूषितनेत्रस्तु स ततोऽर्जुन पावकः।
प्रजज्वाल महाघोरो युगान्त इव पावकः॥', 'krodhadūṣitanetras tu sa tato ''rjuna pāvakaḥ
prajajvāla mahāghoro yugānta iva pāvakaḥ', null, 7032038),
('ramayana-7-32-39', 39, 'Uttara Kanda, Sarga 32, Verse 39', 'स तूर्णतरमादाय वरहेमाङ्गदो गदाम्।
अभिद्रवति रक्षांसि तमांसीव दिवाकरः॥', 'sa tūrṇataram ādāya varahemāṅgado gadām
abhidravati rakṣāṃsi tamāṃsīva divākaraḥ', null, 7032039),
('ramayana-7-32-40', 40, 'Uttara Kanda, Sarga 32, Verse 40', 'बाहुविक्षेपकरणां समुद्यम्य महागदाम्।
गारुडं वेगमास्थाय आपपातैव सोऽर्जुनः॥', 'bāhuvikṣepakaraṇāṃ samudyamya mahāgadām
gāruḍaṃ vegam āsthāya āpapātaiva so ''rjunaḥ', null, 7032040),
('ramayana-7-32-41', 41, 'Uttara Kanda, Sarga 32, Verse 41', 'तस्य मर्गं समावृत्य विन्ध्योऽर्कस्येव पर्वतः।
स्थितो विन्ध्य इवाकम्प्यः प्रहस्तो मुसलायुधः॥', 'tasya margaṃ samāvṛtya vindhyo ''rkasyeva parvataḥ
sthito vindhya ivākampyaḥ prahasto musalāyudhaḥ', null, 7032041),
('ramayana-7-32-42', 42, 'Uttara Kanda, Sarga 32, Verse 42', 'ततोऽस्य मुसलं घोरं लोहबद्धं मदोद्धतः।
प्रहस्तः प्रेषयन्क्रुद्धो ररास च यथाम्बुदः॥', 'tato ''sya musalaṃ ghoraṃ lohabaddhaṃ madoddhataḥ
prahastaḥ preṣayan kruddho rarāsa ca yathāmbudaḥ', null, 7032042),
('ramayana-7-32-43', 43, 'Uttara Kanda, Sarga 32, Verse 43', 'तस्याग्रे मुसलस्याग्निरशोकापीडसंनिभः।
प्रहस्तकरमुक्तस्य बभूव प्रदहन्निव॥', 'tasyāgre musalasyāgnir aśokāpīḍasaṃnibhaḥ
prahastakaramuktasya babhūva pradahann iva', null, 7032043),
('ramayana-7-32-44', 44, 'Uttara Kanda, Sarga 32, Verse 44', 'आधावमानं मुसलं कार्तवीर्यस्तदार्जुनः।
निपुणं वञ्चयामास सगदो गजविक्रमः॥', 'ādhāvamānaṃ musalaṃ kārtavīryas tadārjunaḥ
nipuṇaṃ vañcayām āsa sagado gajavikramaḥ', null, 7032044),
('ramayana-7-32-45', 45, 'Uttara Kanda, Sarga 32, Verse 45', 'ततस्तमभिदुद्राव प्रहस्तं हैहयाधिपः।
भ्रामयाणो गदां गुर्वीं पञ्चबाहुशतोच्छ्रयाम्॥', 'tatas tam abhidudrāva prahastaṃ haihayādhipaḥ
bhrāmayāṇo gadāṃ gurvīṃ pañcabāhuśatocchrayām', null, 7032045),
('ramayana-7-32-46', 46, 'Uttara Kanda, Sarga 32, Verse 46', 'तेनाहतोऽतिवेगेन प्रहस्तो गदया तदा।
निपपात स्थितः शैलो वज्रिवज्रहतो यथा॥', 'tenāhato ''tivegena prahasto gadayā tadā
nipapāta sthitaḥ śailo vajrivajrahato yathā', null, 7032046),
('ramayana-7-32-47', 47, 'Uttara Kanda, Sarga 32, Verse 47', 'प्रहस्तं पतितं दृष्ट्वा मारीचशुकसारणाः।
समहोदरधूम्राक्षा अपसृप्ता रणाजिरात्॥', 'prahastaṃ patitaṃ dṛṣṭvā mārīcaśukasāraṇāḥ
samahodaradhūmrākṣā apasṛptā raṇājirāt', null, 7032047),
('ramayana-7-32-48', 48, 'Uttara Kanda, Sarga 32, Verse 48', 'अपक्रान्तेष्वमात्येषु प्रहस्ते च निपातिते।
रावणोऽभ्यद्रवत्तूर्णमर्जुनं नृपसत्तमम्॥', 'apakrānteṣv amātyeṣu prahaste ca nipātite
rāvaṇo ''bhyadravat tūrṇam arjunaṃ nṛpasattamam', null, 7032048),
('ramayana-7-32-49', 49, 'Uttara Kanda, Sarga 32, Verse 49', 'सहस्रबाहोस्तद्युद्धं विंशद्बाहोश्च दारुणम्।
नृपराक्षसयोस्तत्र आरब्धं लोमहर्षणम्॥', 'sahasrabāhos tad yuddhaṃ viṃśadbāhoś ca dāruṇam
nṛparākṣasayos tatra ārabdhaṃ lomaharṣaṇam', null, 7032049),
('ramayana-7-32-50', 50, 'Uttara Kanda, Sarga 32, Verse 50', 'सागराविव संक्षुब्धौ चलमूलाविवाचलौ।
तेजोयुक्ताविवादित्यौ प्रदहन्ताविवानलौ॥', 'sāgarāv iva saṃkṣubdhau calamūlāv ivācalau
tejoyuktāv ivādityau pradahantāv ivānalau', null, 7032050),
('ramayana-7-32-51', 51, 'Uttara Kanda, Sarga 32, Verse 51', 'बलोद्धतौ यथा नागौ वाशितार्थे यथा वृषौ।
मेघाविव विनर्दन्तौ सिंहाविव बलोत्कटौ॥', 'baloddhatau yathā nāgau vāśitārthe yathā vṛṣau
meghāv iva vinardantau siṃhāv iva balotkaṭau', null, 7032051),
('ramayana-7-32-52', 52, 'Uttara Kanda, Sarga 32, Verse 52', 'रुद्रकालाविव क्रुद्धौ तौ तथा राक्षसार्जुनौ।
परस्परं गदाभ्यां तौ ताडयामासतुर्भृशम्॥', 'rudrakālāv iva kruddhau tau tathā rākṣasārjunau
parasparaṃ gadābhyāṃ tau tāḍayām āsatur bhṛśam', null, 7032052),
('ramayana-7-32-53', 53, 'Uttara Kanda, Sarga 32, Verse 53', 'वज्रप्रहारानचला यथा घोरान्विषेहिरे।
गदाप्रहारांस्तद्वत्तौ सहेते नरराक्षसौ॥', 'vajraprahārān acalā yathā ghorān viṣehire
gadāprahārāṃs tadvat tau sahete nararākṣasau', null, 7032053),
('ramayana-7-32-54', 54, 'Uttara Kanda, Sarga 32, Verse 54', 'यथाशनिरवेभ्यस्तु जायते वै प्रतिश्रुतिः।
तथा ताभ्यां गदापातैर्दिशः सर्वाः प्रतिश्रुताः॥', 'yathāśaniravebhyas tu jāyate vai pratiśrutiḥ
tathā tābhyāṃ gadāpātair diśaḥ sarvāḥ pratiśrutāḥ', null, 7032054),
('ramayana-7-32-55', 55, 'Uttara Kanda, Sarga 32, Verse 55', 'अर्जुनस्य गदा सा तु पात्यमानाहितोरसि।
काञ्चनाभं नभश्चक्रे विद्युत्सौदामनी यथा॥', 'arjunasya gadā sā tu pātyamānāhitorasi
kāñcanābhaṃ nabhaś cakre vidyutsaudāmanī yathā', null, 7032055),
('ramayana-7-32-56', 56, 'Uttara Kanda, Sarga 32, Verse 56', 'तथैव रावणेनापि पात्यमाना मुहुर्मुहुः।
अर्जुनोरसि निर्भाति गदोल्केव महागिरौ॥', 'tathaiva rāvaṇenāpi pātyamānā muhur muhuḥ
arjunorasi nirbhāti gadolkeva mahāgirau', null, 7032056),
('ramayana-7-32-57', 57, 'Uttara Kanda, Sarga 32, Verse 57', 'नार्जुनः खेदमाप्नोति न राक्षसगणेश्वरः।
सममासीत्तयोर्युद्धं यथा पूर्वं बलीन्द्रयोः॥', 'nārjunaḥ khedam āpnoti na rākṣasagaṇeśvaraḥ
samam āsīt tayor yuddhaṃ yathā pūrvaṃ balīndrayoḥ', null, 7032057),
('ramayana-7-32-58', 58, 'Uttara Kanda, Sarga 32, Verse 58', 'शृङ्गैर्महर्षभौ यद्वद्दन्ताग्रैरिव कुञ्जरौ।
परस्परं विनिघ्नन्तौ नरराक्षससत्तमौ॥', 'śṛṅgair maharṣabhau yadvad dantāgrair iva kuñjarau
parasparaṃ vinighnantau nararākṣasasattamau', null, 7032058),
('ramayana-7-32-59', 59, 'Uttara Kanda, Sarga 32, Verse 59', 'ततोऽर्जुनेन क्रुद्धेन सर्वप्राणेन सा गदा।
स्तनयोरन्तरे मुक्ता रावणस्य महाहवे॥', 'tato ''rjunena kruddhena sarvaprāṇena sā gadā
stanayor antare muktā rāvaṇasya mahāhave', null, 7032059),
('ramayana-7-32-60', 60, 'Uttara Kanda, Sarga 32, Verse 60', 'वरदानकृतत्राणे सा गदा रावणोरसि।
दुर्बलेव यथा सेना द्विधाभूतापतत्क्षितौ॥', 'varadānakṛtatrāṇe sā gadā rāvaṇorasi
durbaleva yathā senā dvidhābhūtāpatat kṣitau', null, 7032060),
('ramayana-7-32-61', 61, 'Uttara Kanda, Sarga 32, Verse 61', 'स त्वर्जुनप्रमुक्तेन गदापातेन रावणः।
अपासर्पद्धनुर्मात्रं निषसाद च निष्टनन्॥', 'sa tv arjunapramuktena gadāpātena rāvaṇaḥ
apāsarpad dhanurmātraṃ niṣasāda ca niṣṭanan', null, 7032061),
('ramayana-7-32-62', 62, 'Uttara Kanda, Sarga 32, Verse 62', 'स विह्वलं तदालक्ष्य दशग्रीवं ततोऽर्जुनः।
सहसा प्रतिजग्राह गरुत्मानिव पन्नगम्॥', 'sa vihvalaṃ tad ālakṣya daśagrīvaṃ tato ''rjunaḥ
sahasā pratijagrāha garutmān iva pannagam', null, 7032062),
('ramayana-7-32-63', 63, 'Uttara Kanda, Sarga 32, Verse 63', 'स तं बाहुसहस्रेण बलाद्गृह्य दशाननम्।
बबन्ध बलवान्राजा बलिं नारायणो यथा॥', 'sa taṃ bāhusahasreṇa balād gṛhya daśānanam
babandha balavān rājā baliṃ nārāyaṇo yathā', null, 7032063),
('ramayana-7-32-64', 64, 'Uttara Kanda, Sarga 32, Verse 64', 'बध्यमाने दशग्रीवे सिद्धचारणदेवताः।
साध्वीति वादिनः पुष्पैः किरन्त्यर्जुनमूर्धनि॥', 'badhyamāne daśagrīve siddhacāraṇadevatāḥ
sādhvīti vādinaḥ puṣpaiḥ kiranty arjunamūrdhani', null, 7032064),
('ramayana-7-32-65', 65, 'Uttara Kanda, Sarga 32, Verse 65', 'व्याघ्रो मृगमिवादाय सिंहराडिव दन्तिनम्।
ररास हैहयो राजा हर्षादम्बुदवन्मुहुः॥', 'vyāghro mṛgam ivādāya siṃharāḍ iva dantinam
rarāsa haihayo rājā harṣād ambudavan muhuḥ', null, 7032065),
('ramayana-7-32-66', 66, 'Uttara Kanda, Sarga 32, Verse 66', 'प्रहस्तस्तु समाश्वस्तो दृष्ट्वा बद्धं दशाननम्।
सह तै राकसैः क्रुद्ध अभिदुद्राव पार्थिवम्॥', 'prahastas tu samāśvasto dṛṣṭvā baddhaṃ daśānanam
saha tai rākasaiḥ kruddha abhidudrāva pārthivam', null, 7032066),
('ramayana-7-32-67', 67, 'Uttara Kanda, Sarga 32, Verse 67', 'नक्तंचराणां वेगस्तु तेषामापततां बभौ।
उद्धृत आतपापाये समुद्राणामिवाद्भुतः॥', 'naktaṃcarāṇāṃ vegas tu teṣām āpatatāṃ babhau
uddhṛta ātapāpāye samudrāṇām ivādbhutaḥ', null, 7032067),
('ramayana-7-32-68', 68, 'Uttara Kanda, Sarga 32, Verse 68', 'मुञ्च मुञ्चेति भाषन्तस्तिष्ठ तिष्ठेति चासकृत्।
मुसलानि च शूलानि उत्ससर्जुस्तदार्जुने॥', 'muñca muñceti bhāṣantas tiṣṭha tiṣṭheti cāsakṛt
musalāni ca śūlāni utsasarjus tadārjune', null, 7032068),
('ramayana-7-32-69', 69, 'Uttara Kanda, Sarga 32, Verse 69', 'अप्राप्तान्येव तान्याशु असंभ्रान्तस्तदार्जुनः।
आयुधान्यमरारीणां जग्राह रिपुसूदनः॥', 'aprāptāny eva tāny āśu asaṃbhrāntas tadārjunaḥ
āyudhāny amarārīṇāṃ jagrāha ripusūdanaḥ', null, 7032069),
('ramayana-7-32-70', 70, 'Uttara Kanda, Sarga 32, Verse 70', 'ततस्तैरेव रक्षांसि दुर्धरैः प्रवरायुधैः।
भित्त्वा विद्रावयामास वायुरम्बुधरानिव॥', 'tatas tair eva rakṣāṃsi durdharaiḥ pravarāyudhaiḥ
bhittvā vidrāvayām āsa vāyur ambudharān iva', null, 7032070),
('ramayana-7-32-71', 71, 'Uttara Kanda, Sarga 32, Verse 71', 'राक्षसांस्त्रासयित्वा तु कार्तवीर्यार्जुनस्तदा।
रावणं गृह्य नगरं प्रविवेश सुहृद्वृतः॥', 'rākṣasāṃs trāsayitvā tu kārtavīryārjunas tadā
rāvaṇaṃ gṛhya nagaraṃ praviveśa suhṛdvṛtaḥ', null, 7032071),
('ramayana-7-32-72', 72, 'Uttara Kanda, Sarga 32, Verse 72', 'स कीर्यमाणः कुसुमाक्षतोत्करैर्द्विजैः सपौरैः पुरुहूतसंनिभः।
तदार्जुनः संप्रविवेश तां पुरीं बलिं निगृह्यैव सहस्रलोचनः॥', 'sa kīryamāṇaḥ kusumākṣatotkarair dvijaiḥ sapauraiḥ puruhūtasaṃnibhaḥ
tadārjunaḥ saṃpraviveśa tāṃ purīṃ baliṃ nigṛhyaiva sahasralocanaḥ', null, 7032072)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 33 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-33-1', 1, 'Uttara Kanda, Sarga 33, Verse 1', 'रावणग्रहणं तत्तु वायुग्रहणसंनिभम्।
ऋषिः पुलस्त्यः शुश्राव कथितं दिवि दैवतैः॥', 'rāvaṇagrahaṇaṃ tat tu vāyugrahaṇasaṃnibham
ṛṣiḥ pulastyaḥ śuśrāva kathitaṃ divi daivataiḥ', null, 7033001),
('ramayana-7-33-2', 2, 'Uttara Kanda, Sarga 33, Verse 2', 'ततः पुत्रसुतस्नेहात्कम्प्यमानो महाधृतिः।
माहिष्मतीपतिं द्रष्टुमाजगाम महानृषिः॥', 'tataḥ putrasutasnehāt kampyamāno mahādhṛtiḥ
māhiṣmatīpatiṃ draṣṭum ājagāma mahān ṛṣiḥ', null, 7033002),
('ramayana-7-33-3', 3, 'Uttara Kanda, Sarga 33, Verse 3', 'स वायुमार्गमास्थाय वायुतुल्यगतिर्द्विजः।
पुरीं माहिष्मतीं प्राप्तो मनःसंतापविक्रमः॥', 'sa vāyumārgam āsthāya vāyutulyagatir dvijaḥ
purīṃ māhiṣmatīṃ prāpto manaḥsaṃtāpavikramaḥ', null, 7033003),
('ramayana-7-33-4', 4, 'Uttara Kanda, Sarga 33, Verse 4', 'सोऽमरावतिसंकाशां हृष्टपुष्टजनावृताम्।
प्रविवेश पुरीं ब्रह्मा इन्द्रस्येवामरावतीम्॥', 'so ''marāvatisaṃkāśāṃ hṛṣṭapuṣṭajanāvṛtām
praviveśa purīṃ brahmā indrasyevāmarāvatīm', null, 7033004),
('ramayana-7-33-5', 5, 'Uttara Kanda, Sarga 33, Verse 5', 'पादचारमिवादित्यं निष्पतन्तं सुदुर्दृशम्।
ततस्ते प्रत्यभिज्ञाय अर्जुनाय न्यवेदयन्॥', 'pādacāram ivādityaṃ niṣpatantaṃ sudurdṛśam
tatas te pratyabhijñāya arjunāya nyavedayan', null, 7033005),
('ramayana-7-33-6', 6, 'Uttara Kanda, Sarga 33, Verse 6', 'पुलस्त्य इति तं श्रुत्वा वचनं हैहयाधिपः।
शिरस्यञ्जलिमुद्धृत्य प्रत्युद्गच्छद्द्विजोत्तमम्॥', 'pulastya iti taṃ śrutvā vacanaṃ haihayādhipaḥ
śirasy añjalim uddhṛtya pratyudgacchad dvijottamam', null, 7033006),
('ramayana-7-33-7', 7, 'Uttara Kanda, Sarga 33, Verse 7', 'पुरोहितोऽस्य गृह्यार्घ्यं मधुपर्कं तथैव च।
पुरस्तात्प्रययौ राज्ञ इन्द्रस्येव बृहस्पतिः॥', 'purohito ''sya gṛhyārghyaṃ madhuparkaṃ tathaiva ca
purastāt prayayau rājña indrasyeva bṛhaspatiḥ', null, 7033007),
('ramayana-7-33-8', 8, 'Uttara Kanda, Sarga 33, Verse 8', 'ततस्तमृषिमायान्तमुद्यन्तमिव भास्करम्।
अर्जुनो दृश्य संप्राप्तं ववन्देन्द्र इवेश्वरम्॥', 'tatas tam ṛṣim āyāntam udyantam iva bhāskaram
arjuno dṛśya saṃprāptaṃ vavandendra iveśvaram', null, 7033008),
('ramayana-7-33-9', 9, 'Uttara Kanda, Sarga 33, Verse 9', 'स तस्य मधुपर्कं च पाद्यमर्घ्यं च दापयन्।
पुलस्त्यमाह राजेन्द्रो हर्षगद्गदया गिरा॥', 'sa tasya madhuparkaṃ ca pādyam arghyaṃ ca dāpayan
pulastyam āha rājendro harṣagadgadayā girā', null, 7033009),
('ramayana-7-33-10', 10, 'Uttara Kanda, Sarga 33, Verse 10', 'अद्येयममरावत्या तुल्या माहिष्मती कृता।
अद्याहं तु द्विजेन्द्रेन्द्र यस्मात्पश्यामि दुर्दृशम्॥', 'adyeyam amarāvatyā tulyā māhiṣmatī kṛtā
adyāhaṃ tu dvijendrendra yasmāt paśyāmi durdṛśam', null, 7033010),
('ramayana-7-33-11', 11, 'Uttara Kanda, Sarga 33, Verse 11', 'अद्य मे कुशलं देव अद्य मे कुलमुद्धृतम्।
यत्ते देवगणैर्वन्द्यौ वन्देऽहं चरणाविमौ॥', 'adya me kuśalaṃ deva adya me kulam uddhṛtam
yat te devagaṇair vandyau vande ''haṃ caraṇāv imau', null, 7033011),
('ramayana-7-33-12', 12, 'Uttara Kanda, Sarga 33, Verse 12', 'इदं राज्यमिमे पुत्रा इमे दारा इमे वयम्।
ब्रह्मन्किं कुर्म किं कार्यमाज्ञापयतु नो भवान्॥', 'idaṃ rājyam ime putrā ime dārā ime vayam
brahman kiṃ kurma kiṃ kāryam ājñāpayatu no bhavān', null, 7033012),
('ramayana-7-33-13', 13, 'Uttara Kanda, Sarga 33, Verse 13', 'तं धर्मेऽग्निषु भृत्येषु शिवं पृष्ट्वाथ पार्थिवम्।
पुलस्त्योवाच राजानं हैहयानां तदार्जुनम्॥', 'taṃ dharme ''gniṣu bhṛtyeṣu śivaṃ pṛṣṭvātha pārthivam
pulastyovāca rājānaṃ haihayānāṃ tadārjunam', null, 7033013),
('ramayana-7-33-14', 14, 'Uttara Kanda, Sarga 33, Verse 14', 'राजेन्द्रामलपद्माक्षपूर्णचन्द्रनिभानन।
अतुलं ते बलं येन दशग्रीवस्त्वया जितः॥', 'rājendrāmalapadmākṣapūrṇacandranibhānana
atulaṃ te balaṃ yena daśagrīvas tvayā jitaḥ', null, 7033014),
('ramayana-7-33-15', 15, 'Uttara Kanda, Sarga 33, Verse 15', 'भयाद्यस्यावतिष्ठेतां निष्पन्दौ सागरानिलौ।
सोऽयमद्य त्वया बद्धः पौत्रो मेऽतीवदुर्जयः॥', 'bhayād yasyāvatiṣṭhetāṃ niṣpandau sāgarānilau
so ''yam adya tvayā baddhaḥ pautro me ''tīvadurjayaḥ', null, 7033015),
('ramayana-7-33-16', 16, 'Uttara Kanda, Sarga 33, Verse 16', 'तत्पुत्रक यशः स्फीतं नाम विश्रावितं त्वया।
मद्वाक्याद्याच्यमानोऽद्य मुञ्च वत्स दशाननम्॥', 'tat putraka yaśaḥ sphītaṃ nāma viśrāvitaṃ tvayā
madvākyād yācyamāno ''dya muñca vatsa daśānanam', null, 7033016),
('ramayana-7-33-17', 17, 'Uttara Kanda, Sarga 33, Verse 17', 'पुलस्त्याज्ञां स गृह्याथ अकिंचनवचोऽर्जुनः।
मुमोच पार्थिवेन्द्रेन्द्रो राक्षसेन्द्रं प्रहृष्टवत्॥', 'pulastyājñāṃ sa gṛhyātha akiṃcanavaco ''rjunaḥ
mumoca pārthivendrendro rākṣasendraṃ prahṛṣṭavat', null, 7033017),
('ramayana-7-33-18', 18, 'Uttara Kanda, Sarga 33, Verse 18', 'स तं प्रमुक्त्वा त्रिदशारिमर्जुनः प्रपूज्य दिव्याभरणस्रगम्बरैः।
अहिंसाकं सख्यमुपेत्य साग्निकं प्रणम्य स ब्रह्मसुतं गृहं ययौ॥', 'sa taṃ pramuktvā tridaśārim arjunaḥ prapūjya divyābharaṇasragambaraiḥ
ahiṃsākaṃ sakhyam upetya sāgnikaṃ praṇamya sa brahmasutaṃ gṛhaṃ yayau', null, 7033018),
('ramayana-7-33-19', 19, 'Uttara Kanda, Sarga 33, Verse 19', 'पुलस्त्येनापि संगम्य राक्षसेन्द्रः प्रतापवान्।
परिष्वङ्गकृतातिथ्यो लज्जमानो विसर्जितः॥', 'pulastyenāpi saṃgamya rākṣasendraḥ pratāpavān
pariṣvaṅgakṛtātithyo lajjamāno visarjitaḥ', null, 7033019),
('ramayana-7-33-20', 20, 'Uttara Kanda, Sarga 33, Verse 20', 'पितामहसुतश्चापि पुलस्त्यो मुनिसत्तमः।
मोचयित्वा दशग्रीवं ब्रह्मलोकं जगाम सः॥', 'pitāmahasutaś cāpi pulastyo munisattamaḥ
mocayitvā daśagrīvaṃ brahmalokaṃ jagāma saḥ', null, 7033020),
('ramayana-7-33-21', 21, 'Uttara Kanda, Sarga 33, Verse 21', 'एवं स रावणः प्राप्तः कार्तवीर्यात्तु धर्षणात्।
पुलस्त्यवचनाच्चापि पुनर्मोक्षमवाप्तवान्॥', 'evaṃ sa rāvaṇaḥ prāptaḥ kārtavīryāt tu dharṣaṇāt
pulastyavacanāc cāpi punar mokṣam avāptavān', null, 7033021),
('ramayana-7-33-22', 22, 'Uttara Kanda, Sarga 33, Verse 22', 'एवं बलिभ्यो बलिनः सन्ति राघवनन्दन।
नावज्ञा परतः कार्या य इच्छेच्छ्रेय आत्मनः॥', 'evaṃ balibhyo balinaḥ santi rāghavanandana
nāvajñā parataḥ kāryā ya icchec chreya ātmanaḥ', null, 7033022),
('ramayana-7-33-23', 23, 'Uttara Kanda, Sarga 33, Verse 23', 'ततः स राजा पिशिताशनानां सहस्रबाहोरुपलभ्य मैत्रीम्।
पुनर्नराणां कदनं चकार चचार सर्वां पृथिवीं च दर्पात्॥', 'tataḥ sa rājā piśitāśanānāṃ sahasrabāhor upalabhya maitrīm
punar narāṇāṃ kadanaṃ cakāra cacāra sarvāṃ pṛthivīṃ ca darpāt', null, 7033023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 34 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-34-1', 1, 'Uttara Kanda, Sarga 34, Verse 1', 'अर्जुनेन विमुक्तस्तु रावणो राक्षसाधिपः।
चचार पृथिवीं सर्वामनिर्विण्णस्तथा कृतः॥', 'arjunena vimuktas tu rāvaṇo rākṣasādhipaḥ
cacāra pṛthivīṃ sarvām anirviṇṇas tathā kṛtaḥ', null, 7034001),
('ramayana-7-34-2', 2, 'Uttara Kanda, Sarga 34, Verse 2', 'राक्षसं वा मनुष्यं वा शृणुते यं बलाधिकम्।
रावणस्तं समासाद्य युद्धे ह्वयति दर्पितः॥', 'rākṣasaṃ vā manuṣyaṃ vā śṛṇute yaṃ balādhikam
rāvaṇas taṃ samāsādya yuddhe hvayati darpitaḥ', null, 7034002),
('ramayana-7-34-3', 3, 'Uttara Kanda, Sarga 34, Verse 3', 'ततः कदा चित्किष्किन्धां नगरीं वालिपालिताम्।
गत्वाह्वयति युद्धाय वालिनं हेममालिनम्॥', 'tataḥ kadā cit kiṣkindhāṃ nagarīṃ vālipālitām
gatvāhvayati yuddhāya vālinaṃ hemamālinam', null, 7034003),
('ramayana-7-34-4', 4, 'Uttara Kanda, Sarga 34, Verse 4', 'ततस्तं वानरामात्यस्तारस्तारापिता प्रभुः।
उवाच रावणं वाक्यं युद्धप्रेप्सुमुपागतम्॥', 'tatas taṃ vānarāmātyas tāras tārāpitā prabhuḥ
uvāca rāvaṇaṃ vākyaṃ yuddhaprepsum upāgatam', null, 7034004),
('ramayana-7-34-5', 5, 'Uttara Kanda, Sarga 34, Verse 5', 'राक्षसेन्द्र गतो वाली यस्ते प्रतिबलो भवेत्।
नान्यः प्रमुखतः स्थातुं तव शक्तः प्लवंगमः॥', 'rākṣasendra gato vālī yas te pratibalo bhavet
nānyaḥ pramukhataḥ sthātuṃ tava śaktaḥ plavaṃgamaḥ', null, 7034005),
('ramayana-7-34-6', 6, 'Uttara Kanda, Sarga 34, Verse 6', 'चतुर्भ्योऽपि समुद्रेभ्यः संध्यामन्वास्य रावण।
इमं मुहूर्तमायाति वाली तिष्ठ मुहूर्तकम्॥', 'caturbhyo ''pi samudrebhyaḥ saṃdhyām anvāsya rāvaṇa
imaṃ muhūrtam āyāti vālī tiṣṭha muhūrtakam', null, 7034006),
('ramayana-7-34-7', 7, 'Uttara Kanda, Sarga 34, Verse 7', 'एतानस्थिचयान्पश्य य एते शङ्खपाण्डुराः।
युद्धार्थिनामिमे राजन्वानराधिपतेजसा॥', 'etān asthicayān paśya ya ete śaṅkhapāṇḍurāḥ
yuddhārthinām ime rājan vānarādhipatejasā', null, 7034007),
('ramayana-7-34-8', 8, 'Uttara Kanda, Sarga 34, Verse 8', 'यद्वामृतरसः पीतस्त्वया रावणराक्षस।
तथा वालिनमासाद्य तदन्तं तव जीवितम्॥', 'yad vāmṛtarasaḥ pītas tvayā rāvaṇarākṣasa
tathā vālinam āsādya tadantaṃ tava jīvitam', null, 7034008),
('ramayana-7-34-9', 9, 'Uttara Kanda, Sarga 34, Verse 9', 'अथ वा त्वरसे मर्तुं गच्छ दक्षिणसागरम्।
वालिनं द्रक्ष्यसे तत्र भूमिष्ठमिव भास्करम्॥', 'atha vā tvarase martuṃ gaccha dakṣiṇasāgaram
vālinaṃ drakṣyase tatra bhūmiṣṭham iva bhāskaram', null, 7034009),
('ramayana-7-34-10', 10, 'Uttara Kanda, Sarga 34, Verse 10', 'स तु तारं विनिर्भर्त्स्य रावणो राक्षसेश्वरः।
पुष्पकं तत्समारुह्य प्रययौ दक्षिणार्णवम्॥', 'sa tu tāraṃ vinirbhartsya rāvaṇo rākṣaseśvaraḥ
puṣpakaṃ tat samāruhya prayayau dakṣiṇārṇavam', null, 7034010),
('ramayana-7-34-11', 11, 'Uttara Kanda, Sarga 34, Verse 11', 'तत्र हेमगिरिप्रख्यं तरुणार्कनिभाननम्।
रावणो वालिनं दृष्ट्वा संध्योपासनतत्परम्॥', 'tatra hemagiriprakhyaṃ taruṇārkanibhānanam
rāvaṇo vālinaṃ dṛṣṭvā saṃdhyopāsanatatparam', null, 7034011),
('ramayana-7-34-12', 12, 'Uttara Kanda, Sarga 34, Verse 12', 'पुष्पकादवरुह्याथ रावणोऽञ्जनसंनिभः।
ग्रहीतुं वालिनं तूर्णं निःशब्दपदमाद्रवत्॥', 'puṣpakād avaruhyātha rāvaṇo ''ñjanasaṃnibhaḥ
grahītuṃ vālinaṃ tūrṇaṃ niḥśabdapadam ādravat', null, 7034012),
('ramayana-7-34-13', 13, 'Uttara Kanda, Sarga 34, Verse 13', 'यदृच्छयोन्मीलयता वालिनापि स रावणः।
पापाभिप्रायवान्दृष्टश्चकार न च संभ्रमम्॥', 'yadṛcchayonmīlayatā vālināpi sa rāvaṇaḥ
pāpābhiprāyavān dṛṣṭaś cakāra na ca saṃbhramam', null, 7034013),
('ramayana-7-34-14', 14, 'Uttara Kanda, Sarga 34, Verse 14', 'शशमालक्ष्य सिंहो वा पन्नगं गरुडो यथा।
न चिन्तयति तं वाली रावणं पापनिश्चयम्॥', 'śaśam ālakṣya siṃho vā pannagaṃ garuḍo yathā
na cintayati taṃ vālī rāvaṇaṃ pāpaniścayam', null, 7034014),
('ramayana-7-34-15', 15, 'Uttara Kanda, Sarga 34, Verse 15', 'जिघृक्षमाणमद्यैनं रावणं पापबुद्धिनम्।
कक्षावलम्बिनं कृत्वा गमिष्यामि महार्णवान्॥', 'jighṛkṣamāṇam adyainaṃ rāvaṇaṃ pāpabuddhinam
kakṣāvalambinaṃ kṛtvā gamiṣyāmi mahārṇavān', null, 7034015),
('ramayana-7-34-16', 16, 'Uttara Kanda, Sarga 34, Verse 16', 'द्रक्ष्यन्त्यरिं ममाङ्कस्थं स्रंसितोरुकराम्बरम्।
लम्बमानं दशग्रीवं गरुडस्येव पन्नगम्॥', 'drakṣyanty ariṃ mamāṅkasthaṃ sraṃsitorukarāmbaram
lambamānaṃ daśagrīvaṃ garuḍasyeva pannagam', null, 7034016),
('ramayana-7-34-17', 17, 'Uttara Kanda, Sarga 34, Verse 17', 'इत्येवं मतिमास्थाय वाली कर्णमुपाश्रितः।
जपन्वै नैगमान्मन्त्रांस्तस्थौ पर्वतराडिव॥', 'ity evaṃ matim āsthāya vālī karṇam upāśritaḥ
japan vai naigamān mantrāṃs tasthau parvatarāḍ iva', null, 7034017),
('ramayana-7-34-18', 18, 'Uttara Kanda, Sarga 34, Verse 18', 'तावन्योन्यं जिघृक्षन्तौ हरिराक्षसपार्थिवौ।
प्रयत्नवन्तौ तत्कर्म ईहतुर्बलदर्पितौ॥', 'tāv anyonyaṃ jighṛkṣantau harirākṣasapārthivau
prayatnavantau tat karma īhatur baladarpitau', null, 7034018),
('ramayana-7-34-19', 19, 'Uttara Kanda, Sarga 34, Verse 19', 'हस्तग्राह्यं तु तं मत्वा पादशब्देन रावणम्।
पराङ्मुखोऽपि जग्राह वाली सर्पमिवाण्डजः॥', 'hastagrāhyaṃ tu taṃ matvā pādaśabdena rāvaṇam
parāṅmukho ''pi jagrāha vālī sarpam ivāṇḍajaḥ', null, 7034019),
('ramayana-7-34-20', 20, 'Uttara Kanda, Sarga 34, Verse 20', 'ग्रहीतुकामं तं गृह्य रक्षसामीश्वरं हरिः।
खमुत्पपात वेगेन कृत्वा कक्षावलम्बिनम्॥', 'grahītukāmaṃ taṃ gṛhya rakṣasām īśvaraṃ hariḥ
kham utpapāta vegena kṛtvā kakṣāvalambinam', null, 7034020),
('ramayana-7-34-21', 21, 'Uttara Kanda, Sarga 34, Verse 21', 'स तं पीड्दयमानस्तु वितुदन्तं नखैर्मुहुः।
जहार रावणं वाली पवनस्तोयदं यथा॥', 'sa taṃ pīḍdayamānas tu vitudantaṃ nakhair muhuḥ
jahāra rāvaṇaṃ vālī pavanas toyadaṃ yathā', null, 7034021),
('ramayana-7-34-22', 22, 'Uttara Kanda, Sarga 34, Verse 22', 'अथ ते राक्षसामात्या ह्रियमाणे दशानने।
मुमोक्षयिषवो घोरा रवमाणा ह्यभिद्रवन्॥', 'atha te rākṣasāmātyā hriyamāṇe daśānane
mumokṣayiṣavo ghorā ravamāṇā hy abhidravan', null, 7034022),
('ramayana-7-34-23', 23, 'Uttara Kanda, Sarga 34, Verse 23', 'अन्वीयमानस्तैर्वाली भ्राजतेऽम्बरमध्यगः।
अन्वीयमानो मेघौघैरम्बरस्थ इवांशुमान्॥', 'anvīyamānas tair vālī bhrājate ''mbaramadhyagaḥ
anvīyamāno meghaughair ambarastha ivāṃśumān', null, 7034023),
('ramayana-7-34-24', 24, 'Uttara Kanda, Sarga 34, Verse 24', 'तेऽशक्नुवन्तः संप्राप्तं वालिनं राक्षसोत्तमाः।
तस्य बाहूरुवेगेन परिश्रान्तः पतन्ति च॥', 'te ''śaknuvantaḥ saṃprāptaṃ vālinaṃ rākṣasottamāḥ
tasya bāhūruvegena pariśrāntaḥ patanti ca', null, 7034024),
('ramayana-7-34-25', 25, 'Uttara Kanda, Sarga 34, Verse 25', 'वालिमार्गादपाक्रामन्पर्वतेन्द्रा हि गच्छतः॥', 'vālimārgād apākrāman parvatendrā hi gacchataḥ', null, 7034025),
('ramayana-7-34-26', 26, 'Uttara Kanda, Sarga 34, Verse 26', 'अपक्षिगणसंपातो वानरेन्द्रो महाजवः।
क्रमशः सागरान्सर्वान्संध्याकालमवन्दत॥', 'apakṣigaṇasaṃpāto vānarendro mahājavaḥ
kramaśaḥ sāgarān sarvān saṃdhyākālam avandata', null, 7034026),
('ramayana-7-34-27', 27, 'Uttara Kanda, Sarga 34, Verse 27', 'सभाज्यमानो भूतैस्तु खेचरैः खेचरो हरिः।
पश्चिमं सागरं वाली आजगाम सरावणः॥', 'sabhājyamāno bhūtais tu khecaraiḥ khecaro hariḥ
paścimaṃ sāgaraṃ vālī ājagāma sarāvaṇaḥ', null, 7034027),
('ramayana-7-34-28', 28, 'Uttara Kanda, Sarga 34, Verse 28', 'तत्र संध्यामुपासित्वा स्नात्वा जप्त्वा च वानरः।
उत्तरं सागरं प्रायाद्वहमानो दशाननम्॥', 'tatra saṃdhyām upāsitvā snātvā japtvā ca vānaraḥ
uttaraṃ sāgaraṃ prāyād vahamāno daśānanam', null, 7034028),
('ramayana-7-34-29', 29, 'Uttara Kanda, Sarga 34, Verse 29', 'उत्तरे सागरे संध्यामुपासित्वा दशाननम्।
वहमानोऽगमद्वाली पूर्वमम्बुमहानिधिम्॥', 'uttare sāgare saṃdhyām upāsitvā daśānanam
vahamāno ''gamad vālī pūrvam ambumahānidhim', null, 7034029),
('ramayana-7-34-30', 30, 'Uttara Kanda, Sarga 34, Verse 30', 'तत्रापि संध्यामन्वास्य वासविः स हरीश्वरः।
किष्किन्धाभिमुखो गृह्य रावणं पुनरागमत्॥', 'tatrāpi saṃdhyām anvāsya vāsaviḥ sa harīśvaraḥ
kiṣkindhābhimukho gṛhya rāvaṇaṃ punar āgamat', null, 7034030),
('ramayana-7-34-31', 31, 'Uttara Kanda, Sarga 34, Verse 31', 'चतुर्ष्वपि समुद्रेषु संध्यामन्वास्य वानरः।
रावणोद्वहनश्रान्तः किष्किन्धोपवनेऽपतत्॥', 'caturṣv api samudreṣu saṃdhyām anvāsya vānaraḥ
rāvaṇodvahanaśrāntaḥ kiṣkindhopavane ''patat', null, 7034031),
('ramayana-7-34-32', 32, 'Uttara Kanda, Sarga 34, Verse 32', 'रावणं तु मुमोचाथ स्वकक्षात्कपिसत्तमः।
कुतस्त्वमिति चोवाच प्रहसन्रावणं प्रति॥', 'rāvaṇaṃ tu mumocātha svakakṣāt kapisattamaḥ
kutas tvam iti covāca prahasan rāvaṇaṃ prati', null, 7034032),
('ramayana-7-34-33', 33, 'Uttara Kanda, Sarga 34, Verse 33', 'विस्मयं तु महद्गत्वा श्रमलोकनिरीक्षणः।
राक्षसेशो हरीशं तमिदं वचनमब्रवीत्॥', 'vismayaṃ tu mahad gatvā śramalokanirīkṣaṇaḥ
rākṣaseśo harīśaṃ tam idaṃ vacanam abravīt', null, 7034033),
('ramayana-7-34-34', 34, 'Uttara Kanda, Sarga 34, Verse 34', 'वानरेन्द्र महेन्द्राभ राक्षसेन्द्रोऽस्मि रावणः।
युद्धेप्सुरहं संप्राप्तः स चाद्यासादितस्त्वया॥', 'vānarendra mahendrābha rākṣasendro ''smi rāvaṇaḥ
yuddhepsur ahaṃ saṃprāptaḥ sa cādyāsāditas tvayā', null, 7034034),
('ramayana-7-34-35', 35, 'Uttara Kanda, Sarga 34, Verse 35', 'अहो बलमहो वीर्यमहो गम्भीरता च ते।
येनाहं पशुवद्गृह्य भ्रामितश्चतुरोऽर्णवान्॥', 'aho balam aho vīryam aho gambhīratā ca te
yenāhaṃ paśuvad gṛhya bhrāmitaś caturo ''rṇavān', null, 7034035),
('ramayana-7-34-36', 36, 'Uttara Kanda, Sarga 34, Verse 36', 'एवमश्रान्तवद्वीर शीघ्रमेव च वानर।
मां चैवोद्वहमानस्तु कोऽन्यो वीरः क्रमिष्यति॥', 'evam aśrāntavad vīra śīghram eva ca vānara
māṃ caivodvahamānas tu ko ''nyo vīraḥ kramiṣyati', null, 7034036),
('ramayana-7-34-37', 37, 'Uttara Kanda, Sarga 34, Verse 37', 'त्रयाणामेव भूतानां गतिरेषा प्लवंगम।
मनोऽनिलसुपर्णानां तव वा नात्र संशयः॥', 'trayāṇām eva bhūtānāṃ gatir eṣā plavaṃgama
mano''nilasuparṇānāṃ tava vā nātra saṃśayaḥ', null, 7034037),
('ramayana-7-34-38', 38, 'Uttara Kanda, Sarga 34, Verse 38', 'सोऽहं दृष्टबलस्तुभ्यमिच्छामि हरिपुंगव।
त्वया सह चिरं सख्यं सुस्निग्धं पावकाग्रतः॥', 'so ''haṃ dṛṣṭabalas tubhyam icchāmi haripuṃgava
tvayā saha ciraṃ sakhyaṃ susnigdhaṃ pāvakāgrataḥ', null, 7034038),
('ramayana-7-34-39', 39, 'Uttara Kanda, Sarga 34, Verse 39', 'दाराः पुत्राः पुरं राष्ट्रं भोगाच्छादनभोजनम्।
सर्वमेवाविभक्तं नौ भविष्यति हरीश्वर॥', 'dārāḥ putrāḥ puraṃ rāṣṭraṃ bhogācchādanabhojanam
sarvam evāvibhaktaṃ nau bhaviṣyati harīśvara', null, 7034039),
('ramayana-7-34-40', 40, 'Uttara Kanda, Sarga 34, Verse 40', 'ततः प्रज्वालयित्वाग्निं तावुभौ हरिराक्षसौ।
भ्रातृत्वमुपसंपन्नौ परिष्वज्य परस्परम्॥', 'tataḥ prajvālayitvāgniṃ tāv ubhau harirākṣasau
bhrātṛtvam upasaṃpannau pariṣvajya parasparam', null, 7034040),
('ramayana-7-34-41', 41, 'Uttara Kanda, Sarga 34, Verse 41', 'अन्योन्यं लम्बितकरौ ततस्तौ हरिराक्षसौ।
किष्किन्धां विशतुर्हृष्टौ सिंहौ गिरिगुहामिव॥', 'anyonyaṃ lambitakarau tatas tau harirākṣasau
kiṣkindhāṃ viśatur hṛṣṭau siṃhau giriguhām iva', null, 7034041),
('ramayana-7-34-42', 42, 'Uttara Kanda, Sarga 34, Verse 42', 'स तत्र मासमुषितः सुग्रीव इव रावणः।
अमात्यैरागतैर्नीचस्त्रैलोक्योत्सादनार्थिभिः॥', 'sa tatra māsam uṣitaḥ sugrīva iva rāvaṇaḥ
amātyair āgatair nīcas trailokyotsādanārthibhiḥ', null, 7034042),
('ramayana-7-34-43', 43, 'Uttara Kanda, Sarga 34, Verse 43', 'एवमेतत्पुरावृत्तं वालिना रावणः प्रभो।
धर्षितश्च कृतश्चापि भ्राता पावकसंनिधौ॥', 'evam etat purāvṛttaṃ vālinā rāvaṇaḥ prabho
dharṣitaś ca kṛtaś cāpi bhrātā pāvakasaṃnidhau', null, 7034043),
('ramayana-7-34-44', 44, 'Uttara Kanda, Sarga 34, Verse 44', 'बलमप्रतिमं राम वालिनोऽभवदुत्तमम्।
सोऽपि तया विनिर्दग्धः शलभो वह्निना यथा॥', 'balam apratimaṃ rāma vālino ''bhavad uttamam
so ''pi tayā vinirdagdhaḥ śalabho vahninā yathā', null, 7034044)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 35 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-35-1', 1, 'Uttara Kanda, Sarga 35, Verse 1', 'अपृच्छत ततो रामो दक्षिणाशालयं मुनिम्।
प्राञ्जलिर्विनयोपेत इदमाह वचोऽर्थवत्॥', 'apṛcchata tato rāmo dakṣiṇāśālayaṃ munim
prāñjalir vinayopeta idam āha vaco ''rthavat', null, 7035001),
('ramayana-7-35-2', 2, 'Uttara Kanda, Sarga 35, Verse 2', 'अतुलं बलमेताभ्यां वालिनो रावणस्य च।
न त्वेतौ हनुमद्वीर्यैः समाविति मतिर्मम॥', 'atulaṃ balam etābhyāṃ vālino rāvaṇasya ca
na tv etau hanumadvīryaiḥ samāv iti matir mama', null, 7035002),
('ramayana-7-35-3', 3, 'Uttara Kanda, Sarga 35, Verse 3', 'शौर्यं दाक्ष्यं बलं धैर्यं प्राज्ञता नयसाधनम्।
विक्रमश्च प्रभावश्च हनूमति कृतालयाः॥', 'śauryaṃ dākṣyaṃ balaṃ dhairyaṃ prājñatā nayasādhanam
vikramaś ca prabhāvaś ca hanūmati kṛtālayāḥ', null, 7035003),
('ramayana-7-35-4', 4, 'Uttara Kanda, Sarga 35, Verse 4', 'दृष्ट्वोदधिं विषीदन्तीं तदैष कपिवाहिनीम्।
समाश्वास्य कपीन्भूयो योजनानां शतं प्लुतः॥', 'dṛṣṭvodadhiṃ viṣīdantīṃ tadaiṣa kapivāhinīm
samāśvāsya kapīn bhūyo yojanānāṃ śataṃ plutaḥ', null, 7035004),
('ramayana-7-35-5', 5, 'Uttara Kanda, Sarga 35, Verse 5', 'धर्षयित्वा पुरीं लङ्कां रावणान्तःपुरं तथा।
दृष्ट्वा संभाषिता चापि सीता विश्वासिता तथा॥', 'dharṣayitvā purīṃ laṅkāṃ rāvaṇāntaḥpuraṃ tathā
dṛṣṭvā saṃbhāṣitā cāpi sītā viśvāsitā tathā', null, 7035005),
('ramayana-7-35-6', 6, 'Uttara Kanda, Sarga 35, Verse 6', 'सेनाग्रगा मन्त्रिसुताः किंकरा रावणात्मजः।
एते हनुमता तत्र एकेन विनिपातिताः॥', 'senāgragā mantrisutāḥ kiṃkarā rāvaṇātmajaḥ
ete hanumatā tatra ekena vinipātitāḥ', null, 7035006),
('ramayana-7-35-7', 7, 'Uttara Kanda, Sarga 35, Verse 7', 'भूयो बन्धाद्विमुक्तेन संभाषित्वा दशाननम्।
लङ्का भस्मीकृता तेन पावकेनेव मेदिनी॥', 'bhūyo bandhād vimuktena saṃbhāṣitvā daśānanam
laṅkā bhasmīkṛtā tena pāvakeneva medinī', null, 7035007),
('ramayana-7-35-8', 8, 'Uttara Kanda, Sarga 35, Verse 8', 'न कालस्य न शक्रस्य न विष्णोर्वित्तपस्य च।
कर्माणि तानि श्रूयन्ते यानि युद्धे हनूमतः॥', 'na kālasya na śakrasya na viṣṇor vittapasya ca
karmāṇi tāni śrūyante yāni yuddhe hanūmataḥ', null, 7035008),
('ramayana-7-35-9', 9, 'Uttara Kanda, Sarga 35, Verse 9', 'एतस्य बाहुवीर्येण लङ्का सीता च लक्ष्मणः।
प्राप्तो मया जयश्चैव राज्यं मित्राणि बान्धवाः॥', 'etasya bāhuvīryeṇa laṅkā sītā ca lakṣmaṇaḥ
prāpto mayā jayaś caiva rājyaṃ mitrāṇi bāndhavāḥ', null, 7035009),
('ramayana-7-35-10', 10, 'Uttara Kanda, Sarga 35, Verse 10', 'हनूमान्यदि मे न स्याद्वानराधिपतेः सखा।
प्रवृत्तमपि को वेत्तुं जानक्याः शक्तिमान्भवेत्॥', 'hanūmān yadi me na syād vānarādhipateḥ sakhā
pravṛttam api ko vettuṃ jānakyāḥ śaktimān bhavet', null, 7035010),
('ramayana-7-35-11', 11, 'Uttara Kanda, Sarga 35, Verse 11', 'किमर्थं वाली चैतेन सुग्रीवप्रियकाम्यया।
तदा वैरे समुत्पन्ने न दग्धो वीरुधो यथा॥', 'kimarthaṃ vālī caitena sugrīvapriyakāmyayā
tadā vaire samutpanne na dagdho vīrudho yathā', null, 7035011),
('ramayana-7-35-12', 12, 'Uttara Kanda, Sarga 35, Verse 12', 'न हि वेदितवान्मन्ये हनूमानात्मनो बलम्।
यद्दृष्टवाञ्जीवितेष्टं क्लिश्यन्तं वानराधिपम्॥', 'na hi veditavān manye hanūmān ātmano balam
yad dṛṣṭavāñ jīviteṣṭaṃ kliśyantaṃ vānarādhipam', null, 7035012),
('ramayana-7-35-13', 13, 'Uttara Kanda, Sarga 35, Verse 13', 'एतन्मे भगवन्सर्वं हनूमति महामुने।
विस्तरेण यथातत्त्वं कथयामरपूजित॥', 'etan me bhagavan sarvaṃ hanūmati mahāmune
vistareṇa yathātattvaṃ kathayāmarapūjita', null, 7035013),
('ramayana-7-35-14', 14, 'Uttara Kanda, Sarga 35, Verse 14', 'राघवस्य वचः श्रुत्वा हेतुयुक्तमृषिस्ततः।
हनूमतः समक्षं तमिदं वचनमब्रवीत्॥', 'rāghavasya vacaḥ śrutvā hetuyuktam ṛṣis tataḥ
hanūmataḥ samakṣaṃ tam idaṃ vacanam abravīt', null, 7035014),
('ramayana-7-35-15', 15, 'Uttara Kanda, Sarga 35, Verse 15', 'सत्यमेतद्रघुश्रेष्ठ यद्ब्रवीषि हनूमतः।
न बले विद्यते तुल्यो न गतौ न मतौ परः॥', 'satyam etad raghuśreṣṭha yad bravīṣi hanūmataḥ
na bale vidyate tulyo na gatau na matau paraḥ', null, 7035015),
('ramayana-7-35-16', 16, 'Uttara Kanda, Sarga 35, Verse 16', 'अमोघशापैः शापस्तु दत्तोऽस्य ऋषिभिः पुरा।
न वेदिता बलं येन बली सन्नरिमर्दनः॥', 'amoghaśāpaiḥ śāpas tu datto ''sya ṛṣibhiḥ purā
na veditā balaṃ yena balī sann arimardanaḥ', null, 7035016),
('ramayana-7-35-17', 17, 'Uttara Kanda, Sarga 35, Verse 17', 'बाल्येऽप्येतेन यत्कर्म कृतं राम महाबल।
तन्न वर्णयितुं शक्यमतिबालतयास्य ते॥', 'bālye ''py etena yat karma kṛtaṃ rāma mahābala
tan na varṇayituṃ śakyam atibālatayāsya te', null, 7035017),
('ramayana-7-35-18', 18, 'Uttara Kanda, Sarga 35, Verse 18', 'यदि वास्ति त्वभिप्रायस्तच्छ्रोतुं तव राघव।
समाधाय मतिं राम निशामय वदाम्यहम्॥', 'yadi vāsti tv abhiprāyas tac chrotuṃ tava rāghava
samādhāya matiṃ rāma niśāmaya vadāmy aham', null, 7035018),
('ramayana-7-35-19', 19, 'Uttara Kanda, Sarga 35, Verse 19', 'सूर्यदत्तवरस्वर्णः सुमेरुर्नाम पर्वतः।
यत्र राज्यं प्रशास्त्यस्य केषरी नाम वै पिता॥', 'sūryadattavarasvarṇaḥ sumerur nāma parvataḥ
yatra rājyaṃ praśāsty asya keṣarī nāma vai pitā', null, 7035019),
('ramayana-7-35-20', 20, 'Uttara Kanda, Sarga 35, Verse 20', 'तस्य भार्या बभूवेष्टा ह्यञ्जनेति परिश्रुता।
जनयामास तस्यां वै वायुरात्मजमुत्तमम्॥', 'tasya bhāryā babhūveṣṭā hy añjaneti pariśrutā
janayām āsa tasyāṃ vai vāyur ātmajam uttamam', null, 7035020),
('ramayana-7-35-21', 21, 'Uttara Kanda, Sarga 35, Verse 21', 'शालिशूकसमाभासं प्रासूतेमं तदाञ्जना।
फलान्याहर्तुकामा वै निष्क्रान्ता गहने चरा॥', 'śāliśūkasamābhāsaṃ prāsūtemaṃ tadāñjanā
phalāny āhartukāmā vai niṣkrāntā gahane carā', null, 7035021),
('ramayana-7-35-22', 22, 'Uttara Kanda, Sarga 35, Verse 22', 'एष मातुर्वियोगाच्च क्षुधया च भृशार्दितः।
रुरोद शिशुरत्यर्थं शिशुः शरभराडिव॥', 'eṣa mātur viyogāc ca kṣudhayā ca bhṛśārditaḥ
ruroda śiśur atyarthaṃ śiśuḥ śarabharāḍ iva', null, 7035022),
('ramayana-7-35-23', 23, 'Uttara Kanda, Sarga 35, Verse 23', 'ततोद्यन्तं विवस्वन्तं जपापुष्पोत्करोपमम्।
ददृशे फललोभाच्च उत्पपात रविं प्रति॥', 'tatodyantaṃ vivasvantaṃ japāpuṣpotkaropamam
dadṛśe phalalobhāc ca utpapāta raviṃ prati', null, 7035023),
('ramayana-7-35-24', 24, 'Uttara Kanda, Sarga 35, Verse 24', 'बालार्काभिमुखो बालो बालार्क इव मूर्तिमान्।
ग्रहीतुकामो बालार्कं प्लवतेऽम्बरमध्यगः॥', 'bālārkābhimukho bālo bālārka iva mūrtimān
grahītukāmo bālārkaṃ plavate ''mbaramadhyagaḥ', null, 7035024),
('ramayana-7-35-25', 25, 'Uttara Kanda, Sarga 35, Verse 25', 'एतस्मिन्प्लवमाने तु शिशुभावे हनूमति।
देवदानवसिद्धानां विस्मयः सुमहानभूत्॥', 'etasmin plavamāne tu śiśubhāve hanūmati
devadānavasiddhānāṃ vismayaḥ sumahān abhūt', null, 7035025),
('ramayana-7-35-26', 26, 'Uttara Kanda, Sarga 35, Verse 26', 'नाप्येवं वेगवान्वायुर्गरुडो न मनस्तथा।
यथायं वायुपुत्रस्तु क्रमतेऽम्बरमुत्तमम्॥', 'nāpy evaṃ vegavān vāyur garuḍo na manas tathā
yathāyaṃ vāyuputras tu kramate ''mbaram uttamam', null, 7035026),
('ramayana-7-35-27', 27, 'Uttara Kanda, Sarga 35, Verse 27', 'यदि तावच्छिशोरस्य ईदृशौ गतिविक्रमौ।
यौवनं बलमासाद्य कथं वेगो भविष्यति॥', 'yadi tāvac chiśor asya īdṛśau gativikramau
yauvanaṃ balam āsādya kathaṃ vego bhaviṣyati', null, 7035027),
('ramayana-7-35-28', 28, 'Uttara Kanda, Sarga 35, Verse 28', 'तमनुप्लवते वायुः प्लवन्तं पुत्रमात्मनः।
सूर्यदाहभयाद्रक्षंस्तुषारचयशीतलः॥', 'tam anuplavate vāyuḥ plavantaṃ putram ātmanaḥ
sūryadāhabhayād rakṣaṃs tuṣāracayaśītalaḥ', null, 7035028),
('ramayana-7-35-29', 29, 'Uttara Kanda, Sarga 35, Verse 29', 'बहुयोजनसाहस्रं क्रमत्येष ततोऽम्बरम्।
पितुर्बलाच्च बाल्याच्च भास्कराभ्याशमागतः॥', 'bahuyojanasāhasraṃ kramaty eṣa tato ''mbaram
pitur balāc ca bālyāc ca bhāskarābhyāśam āgataḥ', null, 7035029),
('ramayana-7-35-30', 30, 'Uttara Kanda, Sarga 35, Verse 30', 'शिशुरेष त्वदोषज्ञ इति मत्वा दिवाकरः।
कार्यं चात्र समायत्तमित्येवं न ददाह सः॥', 'śiśur eṣa tv adoṣajña iti matvā divākaraḥ
kāryaṃ cātra samāyattam ity evaṃ na dadāha saḥ', null, 7035030),
('ramayana-7-35-31', 31, 'Uttara Kanda, Sarga 35, Verse 31', 'यमेव दिवसं ह्येष ग्रहीतुं भास्करं प्लुतः।
तमेव दिवसं राहुर्जिघृक्षति दिवाकरम्॥', 'yam eva divasaṃ hy eṣa grahītuṃ bhāskaraṃ plutaḥ
tam eva divasaṃ rāhur jighṛkṣati divākaram', null, 7035031),
('ramayana-7-35-32', 32, 'Uttara Kanda, Sarga 35, Verse 32', 'अनेन च परामृष्टो राम सूर्यरथोपरि।
अपक्रान्तस्ततस्त्रस्तो राहुश्चन्द्रार्कमर्दनः॥', 'anena ca parāmṛṣṭo rāma sūryarathopari
apakrāntas tatas trasto rāhuś candrārkamardanaḥ', null, 7035032),
('ramayana-7-35-33', 33, 'Uttara Kanda, Sarga 35, Verse 33', 'स इन्द्रभवनं गत्वा सरोषः सिंहिकासुतः।
अब्रवीद्भ्रुकुटीं कृत्वा देवं देवगणैर्वृतम्॥', 'sa indrabhavanaṃ gatvā saroṣaḥ siṃhikāsutaḥ
abravīd bhrukuṭīṃ kṛtvā devaṃ devagaṇair vṛtam', null, 7035033),
('ramayana-7-35-34', 34, 'Uttara Kanda, Sarga 35, Verse 34', 'बुभुक्षापनयं दत्त्वा चन्द्रार्कौ मम वासव।
किमिदं तत्त्वया दत्तमन्यस्य बलवृत्रहन्॥', 'bubhukṣāpanayaṃ dattvā candrārkau mama vāsava
kim idaṃ tat tvayā dattam anyasya balavṛtrahan', null, 7035034),
('ramayana-7-35-35', 35, 'Uttara Kanda, Sarga 35, Verse 35', 'अद्याहं पर्वकाले तु जिघृक्षुः सूर्यमागतः।
अथान्यो राहुरासाद्य जग्राह सहसा रविम्॥', 'adyāhaṃ parvakāle tu jighṛkṣuḥ sūryam āgataḥ
athānyo rāhur āsādya jagrāha sahasā ravim', null, 7035035),
('ramayana-7-35-36', 36, 'Uttara Kanda, Sarga 35, Verse 36', 'स राहोर्वचनं श्रुत्वा वासवः संभ्रमान्वितः।
उत्पपातासनं हित्वा उद्वहन्काञ्चनस्रजम्॥', 'sa rāhor vacanaṃ śrutvā vāsavaḥ saṃbhramānvitaḥ
utpapātāsanaṃ hitvā udvahan kāñcanasrajam', null, 7035036),
('ramayana-7-35-37', 37, 'Uttara Kanda, Sarga 35, Verse 37', 'ततः कैलासकूटाभं चतुर्दन्तं मदस्रवम्।
शृङ्गारकारिणं प्रांशुं स्वर्णघण्टाट्टहासिनम्॥', 'tataḥ kailāsakūṭābhaṃ caturdantaṃ madasravam
śṛṅgārakāriṇaṃ prāṃśuṃ svarṇaghaṇṭāṭṭahāsinam', null, 7035037),
('ramayana-7-35-38', 38, 'Uttara Kanda, Sarga 35, Verse 38', 'इन्द्रः करीन्द्रमारुह्य राहुं कृत्वा पुरःसरम्।
प्रायाद्यत्राभवत्सूर्यः सहानेन हनूमता॥', 'indraḥ karīndram āruhya rāhuṃ kṛtvā puraḥsaram
prāyād yatrābhavat sūryaḥ sahānena hanūmatā', null, 7035038),
('ramayana-7-35-39', 39, 'Uttara Kanda, Sarga 35, Verse 39', 'अथातिरभसेनागाद्राहुरुत्सृज्य वासवम्।
अनेन च स वै दृष्ट आधावञ्शैलकूटवत्॥', 'athātirabhasenāgād rāhur utsṛjya vāsavam
anena ca sa vai dṛṣṭa ādhāvañ śailakūṭavat', null, 7035039),
('ramayana-7-35-40', 40, 'Uttara Kanda, Sarga 35, Verse 40', 'ततः सूर्यं समुत्सृज्य राहुमेवमवेक्ष्य च।
उत्पपात पुनर्व्योम ग्रहीतुं सिंहिकासुतम्॥', 'tataḥ sūryaṃ samutsṛjya rāhum evam avekṣya ca
utpapāta punar vyoma grahītuṃ siṃhikāsutam', null, 7035040),
('ramayana-7-35-41', 41, 'Uttara Kanda, Sarga 35, Verse 41', 'उत्सृज्यार्कमिमं राम आधावन्तं प्लवंगमम्।
दृष्ट्वा राहुः परावृत्य मुखशेषः पराङ्मुखः॥', 'utsṛjyārkam imaṃ rāma ādhāvantaṃ plavaṃgamam
dṛṣṭvā rāhuḥ parāvṛtya mukhaśeṣaḥ parāṅmukhaḥ', null, 7035041),
('ramayana-7-35-42', 42, 'Uttara Kanda, Sarga 35, Verse 42', 'इन्द्रमाशंसमानस्तु त्रातारं सिंहिकासुतः।
इन्द्र इन्द्रेति संत्रासान्मुहुर्मुहुरभाषत॥', 'indram āśaṃsamānas tu trātāraṃ siṃhikāsutaḥ
indra indreti saṃtrāsān muhur muhur abhāṣata', null, 7035042),
('ramayana-7-35-43', 43, 'Uttara Kanda, Sarga 35, Verse 43', 'राहोर्विक्रोशमानस्य प्रागेवालक्षितः स्वरः।
श्रुत्वेन्द्रोवाच मा भैषीरयमेनं निहन्म्यहम्॥', 'rāhor vikrośamānasya prāg evālakṣitaḥ svaraḥ
śrutvendrovāca mā bhaiṣīr ayam enaṃ nihanmy aham', null, 7035043),
('ramayana-7-35-44', 44, 'Uttara Kanda, Sarga 35, Verse 44', 'ऐरावतं ततो दृष्ट्वा महत्तदिदमित्यपि।
फलं तं हस्तिराजानमभिदुद्राव मारुतिः॥', 'airāvataṃ tato dṛṣṭvā mahat tad idam ity api
phalaṃ taṃ hastirājānam abhidudrāva mārutiḥ', null, 7035044),
('ramayana-7-35-45', 45, 'Uttara Kanda, Sarga 35, Verse 45', 'तदास्य धावतो रूपमैरावतजिघृक्षया।
मुहूर्तमभवद्घोरमिन्द्राग्न्योरिव भास्वरम्॥', 'tadāsya dhāvato rūpam airāvatajighṛkṣayā
muhūrtam abhavad ghoram indrāgnyor iva bhāsvaram', null, 7035045),
('ramayana-7-35-46', 46, 'Uttara Kanda, Sarga 35, Verse 46', 'एवमाधावमानं तु नातिक्रुद्धः शचीपतिः।
हस्तान्तेनातिमुक्तेन कुलिशेनाभ्यताडयत्॥', 'evam ādhāvamānaṃ tu nātikruddhaḥ śacīpatiḥ
hastāntenātimuktena kuliśenābhyatāḍayat', null, 7035046),
('ramayana-7-35-47', 47, 'Uttara Kanda, Sarga 35, Verse 47', 'ततो गिरौ पपातैष इन्द्रवज्राभिताडितः।
पतमानस्य चैतस्य वामो हनुरभज्यत॥', 'tato girau papātaiṣa indravajrābhitāḍitaḥ
patamānasya caitasya vāmo hanur abhajyata', null, 7035047),
('ramayana-7-35-48', 48, 'Uttara Kanda, Sarga 35, Verse 48', 'तस्मिंस्तु पतिते बाले वज्रताडनविह्वले।
चुक्रोधेन्द्राय पवनः प्रजानामशिवाय च॥', 'tasmiṃs tu patite bāle vajratāḍanavihvale
cukrodhendrāya pavanaḥ prajānām aśivāya ca', null, 7035048),
('ramayana-7-35-49', 49, 'Uttara Kanda, Sarga 35, Verse 49', 'विण्मूत्राशयमावृत्य प्रजास्वन्तर्गतः प्रभुः।
रुरोध सर्वभूतानि यथा वर्षाणि वासवः॥', 'viṇmūtrāśayam āvṛtya prajāsv antargataḥ prabhuḥ
rurodha sarvabhūtāni yathā varṣāṇi vāsavaḥ', null, 7035049),
('ramayana-7-35-50', 50, 'Uttara Kanda, Sarga 35, Verse 50', 'वायुप्रकोपाद्भूतानि निरुच्छ्वासानि सर्वतः।
संधिभिर्भज्यमानानि काष्ठभूतानि जज्ञिरे॥', 'vāyuprakopād bhūtāni nirucchvāsāni sarvataḥ
saṃdhibhir bhajyamānāni kāṣṭhabhūtāni jajñire', null, 7035050),
('ramayana-7-35-51', 51, 'Uttara Kanda, Sarga 35, Verse 51', 'निःस्वधं निर्वषट्कारं निष्क्रियं धर्मवर्जितम्।
वायुप्रकोपात्त्रैलोक्यं निरयस्थमिवाबभौ॥', 'niḥsvadhaṃ nirvaṣaṭkāraṃ niṣkriyaṃ dharmavarjitam
vāyuprakopāt trailokyaṃ nirayastham ivābabhau', null, 7035051),
('ramayana-7-35-52', 52, 'Uttara Kanda, Sarga 35, Verse 52', 'ततः प्रजाः सगन्धर्वाः सदेवासुरमानुषाः।
प्रजापतिं समाधावन्नसुखार्ताः सुखैषिणः॥', 'tataḥ prajāḥ sagandharvāḥ sadevāsuramānuṣāḥ
prajāpatiṃ samādhāvann asukhārtāḥ sukhaiṣiṇaḥ', null, 7035052),
('ramayana-7-35-53', 53, 'Uttara Kanda, Sarga 35, Verse 53', 'ऊचुः प्राञ्जलयो देवा दरोदरनिभोदराः।
त्वया स्म भगवन्सृष्टाः प्रजानाथ चतुर्विधाः॥', 'ūcuḥ prāñjalayo devā darodaranibhodarāḥ
tvayā sma bhagavan sṛṣṭāḥ prajānātha caturvidhāḥ', null, 7035053),
('ramayana-7-35-54', 54, 'Uttara Kanda, Sarga 35, Verse 54', 'त्वया दत्तोऽयमस्माकमायुषः पवनः पतिः।
सोऽस्मान्प्राणेश्वरो भूत्वा कस्मादेषोऽद्य सत्तम॥', 'tvayā datto ''yam asmākam āyuṣaḥ pavanaḥ patiḥ
so ''smān prāṇeśvaro bhūtvā kasmād eṣo ''dya sattama', null, 7035054),
('ramayana-7-35-55', 55, 'Uttara Kanda, Sarga 35, Verse 55', 'रुरोध दुःखं जनयन्नन्तःपुर इव स्त्रियः।
तस्मात्त्वां शरणं प्राप्ता वायुनोपहता विभो॥', 'rurodha duḥkhaṃ janayann antaḥpura iva striyaḥ
tasmāt tvāṃ śaraṇaṃ prāptā vāyunopahatā vibho', null, 7035055),
('ramayana-7-35-56', 56, 'Uttara Kanda, Sarga 35, Verse 56', 'वायुसंरोधजं दुःखमिदं नो नुद शत्रुहन्॥', 'vāyusaṃrodhajaṃ duḥkham idaṃ no nuda śatruhan', null, 7035056),
('ramayana-7-35-57', 57, 'Uttara Kanda, Sarga 35, Verse 57', 'एतत्प्रजानां श्रुत्वा तु प्रजानाथः प्रजापतिः।
कारणादिति तानुक्त्वा प्रजाः पुनरभाषत॥', 'etat prajānāṃ śrutvā tu prajānāthaḥ prajāpatiḥ
kāraṇād iti tān uktvā prajāḥ punar abhāṣata', null, 7035057),
('ramayana-7-35-58', 58, 'Uttara Kanda, Sarga 35, Verse 58', 'यस्मिन्वः कारणे वायुश्चुक्रोध च रुरोध च।
प्रजाः शृणुध्वं तत्सर्वं श्रोतव्यं चात्मनः क्षमम्॥', 'yasmin vaḥ kāraṇe vāyuś cukrodha ca rurodha ca
prajāḥ śṛṇudhvaṃ tat sarvaṃ śrotavyaṃ cātmanaḥ kṣamam', null, 7035058),
('ramayana-7-35-59', 59, 'Uttara Kanda, Sarga 35, Verse 59', 'पुत्रस्तस्यामरेशेन इन्द्रेणाद्य निपातितः।
राहोर्वचनमाज्ञाय राज्ञा वः कोपितोऽनिलः॥', 'putras tasyāmareśena indreṇādya nipātitaḥ
rāhor vacanam ājñāya rājñā vaḥ kopito ''nilaḥ', null, 7035059),
('ramayana-7-35-60', 60, 'Uttara Kanda, Sarga 35, Verse 60', 'अशरीरः शरीरेषु वायुश्चरति पालयन्।
शरीरं हि विना वायुं समतां याति रेणुभिः॥', 'aśarīraḥ śarīreṣu vāyuś carati pālayan
śarīraṃ hi vinā vāyuṃ samatāṃ yāti reṇubhiḥ', null, 7035060),
('ramayana-7-35-61', 61, 'Uttara Kanda, Sarga 35, Verse 61', 'वायुः प्राणाः सुखं वायुर्वायुः सर्वमिदं जगत्।
वायुना संपरित्यक्तं न सुखं विन्दते जगत्॥', 'vāyuḥ prāṇāḥ sukhaṃ vāyur vāyuḥ sarvam idaṃ jagat
vāyunā saṃparityaktaṃ na sukhaṃ vindate jagat', null, 7035061),
('ramayana-7-35-62', 62, 'Uttara Kanda, Sarga 35, Verse 62', 'अद्यैव च परित्यक्तं वायुना जगदायुषा।
अद्यैवेमे निरुच्छ्वासाः काष्ठकुड्योपमाः स्थिताः॥', 'adyaiva ca parityaktaṃ vāyunā jagad āyuṣā
adyaiveme nirucchvāsāḥ kāṣṭhakuḍyopamāḥ sthitāḥ', null, 7035062),
('ramayana-7-35-63', 63, 'Uttara Kanda, Sarga 35, Verse 63', 'तद्यामस्तत्र यत्रास्ते मारुतो रुक्प्रदो हि वः।
मा विनाशं गमिष्याम अप्रसाद्यादितेः सुतम्॥', 'tad yāmas tatra yatrāste māruto rukprado hi vaḥ
mā vināśaṃ gamiṣyāma aprasādyāditeḥ sutam', null, 7035063),
('ramayana-7-35-64', 64, 'Uttara Kanda, Sarga 35, Verse 64', 'ततः प्रजाभिः सहितः प्रजापतिः सदेवगन्धर्वभुजंगगुह्यकः।
जगाम तत्रास्यति यत्र मारुतः सुतं सुरेन्द्राभिहतं प्रगृह्य सः॥', 'tataḥ prajābhiḥ sahitaḥ prajāpatiḥ sadevagandharvabhujaṃgaguhyakaḥ
jagāma tatrāsyati yatra mārutaḥ sutaṃ surendrābhihataṃ pragṛhya saḥ', null, 7035064),
('ramayana-7-35-65', 65, 'Uttara Kanda, Sarga 35, Verse 65', 'ततोऽर्कवैश्वानरकाञ्चनप्रभं सुतं तदोत्सङ्गगतं सदागतेः।
चतुर्मुखो वीक्ष्य कृपामथाकरोत्सदेवसिद्धर्षिभुजंगराक्षसः॥', 'tato ''rkavaiśvānarakāñcanaprabhaṃ sutaṃ tadotsaṅgagataṃ sadāgateḥ
caturmukho vīkṣya kṛpām athākarot sadevasiddharṣibhujaṃgarākṣasaḥ', null, 7035065)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 36 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-36-1', 1, 'Uttara Kanda, Sarga 36, Verse 1', 'ततः पितामहं दृष्ट्वा वायुः पुत्रवधार्दितः।
शिशुकं तं समादाय उत्तस्थौ धातुरग्रतः॥', 'tataḥ pitāmahaṃ dṛṣṭvā vāyuḥ putravadhārditaḥ
śiśukaṃ taṃ samādāya uttasthau dhātur agrataḥ', null, 7036001),
('ramayana-7-36-2', 2, 'Uttara Kanda, Sarga 36, Verse 2', 'चलत्कुण्डलमौलिस्रक्तपनीयविभूषणः।
पादयोर्न्यपतद्वायुस्तिस्रोऽवस्थाय वेधसे॥', 'calatkuṇḍalamaulisraktapanīyavibhūṣaṇaḥ
pādayor nyapatad vāyus tisro ''vasthāya vedhase', null, 7036002),
('ramayana-7-36-3', 3, 'Uttara Kanda, Sarga 36, Verse 3', 'तं तु वेदविदाद्यस्तु लम्बाभरणशोभिना।
वायुमुत्थाप्य हस्तेन शिशुं तं परिमृष्टवान्॥', 'taṃ tu vedavidādyas tu lambābharaṇaśobhinā
vāyum utthāpya hastena śiśuṃ taṃ parimṛṣṭavān', null, 7036003),
('ramayana-7-36-4', 4, 'Uttara Kanda, Sarga 36, Verse 4', 'स्पृष्टमात्रस्ततः सोऽथ सलीलं पद्मजन्मना।
जलसिक्तं यथा सस्यं पुनर्जीवितमाप्तवान्॥', 'spṛṣṭamātras tataḥ so ''tha salīlaṃ padmajanmanā
jalasiktaṃ yathā sasyaṃ punar jīvitam āptavān', null, 7036004),
('ramayana-7-36-5', 5, 'Uttara Kanda, Sarga 36, Verse 5', 'प्राणवन्तमिमं दृष्ट्वा प्राणो गन्धवहो मुदा।
चचार सर्वभूतेषु संनिरुद्धं यथापुरा॥', 'prāṇavantam imaṃ dṛṣṭvā prāṇo gandhavaho mudā
cacāra sarvabhūteṣu saṃniruddhaṃ yathāpurā', null, 7036005),
('ramayana-7-36-6', 6, 'Uttara Kanda, Sarga 36, Verse 6', 'मरुद्रोगविनिर्मुक्ताः प्रजा वै मुदिताभवन्।
शीतवातविनिर्मुक्ताः पद्मिन्य इव साम्बुजाः॥', 'marudrogavinirmuktāḥ prajā vai muditābhavan
śītavātavinirmuktāḥ padminya iva sāmbujāḥ', null, 7036006),
('ramayana-7-36-7', 7, 'Uttara Kanda, Sarga 36, Verse 7', 'ततस्त्रियुग्मस्त्रिककुत्त्रिधामा त्रिदशार्चितः।
उवाच देवता ब्रह्मा मारुतप्रियकाम्यया॥', 'tatas triyugmas trikakut tridhāmā tridaśārcitaḥ
uvāca devatā brahmā mārutapriyakāmyayā', null, 7036007),
('ramayana-7-36-8', 8, 'Uttara Kanda, Sarga 36, Verse 8', 'भो महेन्द्राग्निवरुणधनेश्वरमहेश्वराः।
जानतामपि तत्सर्वं हितं वक्ष्यामि श्रूयताम्॥', 'bho mahendrāgnivaruṇadhaneśvaramaheśvarāḥ
jānatām api tat sarvaṃ hitaṃ vakṣyāmi śrūyatām', null, 7036008),
('ramayana-7-36-9', 9, 'Uttara Kanda, Sarga 36, Verse 9', 'अनेन शिशुना कार्यं कर्तव्यं वो भविष्यति।
ददतास्य वरान्सर्वे मारुतस्यास्य तुष्टिदान्॥', 'anena śiśunā kāryaṃ kartavyaṃ vo bhaviṣyati
dadatāsya varān sarve mārutasyāsya tuṣṭidān', null, 7036009),
('ramayana-7-36-10', 10, 'Uttara Kanda, Sarga 36, Verse 10', 'ततः सहस्रनयनः प्रीतिरक्तः शुभाननः।
कुशे शयमयीं मालां समुत्क्षिप्येदमब्रवीत्॥', 'tataḥ sahasranayanaḥ prītiraktaḥ śubhānanaḥ
kuśe śayamayīṃ mālāṃ samutkṣipyedam abravīt', null, 7036010),
('ramayana-7-36-11', 11, 'Uttara Kanda, Sarga 36, Verse 11', 'मत्करोत्सृष्टवज्रेण हनुरस्य यथा क्षतः।
नाम्नैष कपिशार्दूलो भविता हनुमानिति॥', 'matkarotsṛṣṭavajreṇa hanur asya yathā kṣataḥ
nāmnaiṣa kapiśārdūlo bhavitā hanumān iti', null, 7036011),
('ramayana-7-36-12', 12, 'Uttara Kanda, Sarga 36, Verse 12', 'अहमेवास्य दास्यामि परमं वरमुत्तमम्।
अतः प्रभृति वज्रस्य ममावध्यो भविष्यति॥', 'aham evāsya dāsyāmi paramaṃ varam uttamam
ataḥ prabhṛti vajrasya mamāvadhyo bhaviṣyati', null, 7036012),
('ramayana-7-36-13', 13, 'Uttara Kanda, Sarga 36, Verse 13', 'मार्ताण्डस्त्वब्रवीत्तत्र भगवांस्तिमिरापहः।
तेजसोऽस्य मदीयस्य ददामि शतिकां कलाम्॥', 'mārtāṇḍas tv abravīt tatra bhagavāṃs timirāpahaḥ
tejaso ''sya madīyasya dadāmi śatikāṃ kalām', null, 7036013),
('ramayana-7-36-14', 14, 'Uttara Kanda, Sarga 36, Verse 14', 'यदा तु शास्त्राण्यध्येतुं शक्तिरस्य भविष्यति।
तदास्य शास्त्रं दास्यामि येन वाग्मी भविष्यति॥', 'yadā tu śāstrāṇy adhyetuṃ śaktir asya bhaviṣyati
tadāsya śāstraṃ dāsyāmi yena vāgmī bhaviṣyati', null, 7036014),
('ramayana-7-36-15', 15, 'Uttara Kanda, Sarga 36, Verse 15', 'वरुणश्च वरं प्रादान्नास्य मृत्युर्भविष्यति।
वर्षायुतशतेनापि मत्पाशादुदकादपि॥', 'varuṇaś ca varaṃ prādān nāsya mṛtyur bhaviṣyati
varṣāyutaśatenāpi matpāśād udakād api', null, 7036015),
('ramayana-7-36-16', 16, 'Uttara Kanda, Sarga 36, Verse 16', 'यमोऽपि दण्डावध्यत्वमरोगत्वं च नित्यशः।
दिशतेऽस्य वरं तुष्ट अविषादं च संयुगे॥', 'yamo ''pi daṇḍāvadhyatvam arogatvaṃ ca nityaśaḥ
diśate ''sya varaṃ tuṣṭa aviṣādaṃ ca saṃyuge', null, 7036016),
('ramayana-7-36-17', 17, 'Uttara Kanda, Sarga 36, Verse 17', 'गदेयं मामिका नैनं संयुगेषु वधिष्यति।
इत्येवं वरदः प्राह तदा ह्येकाक्षिपिङ्गलः॥', 'gadeyaṃ māmikā nainaṃ saṃyugeṣu vadhiṣyati
ity evaṃ varadaḥ prāha tadā hy ekākṣipiṅgalaḥ', null, 7036017),
('ramayana-7-36-18', 18, 'Uttara Kanda, Sarga 36, Verse 18', 'मत्तो मदायुधानां च न वध्योऽयं भविष्यति।
इत्येवं शंकरेणापि दत्तोऽस्य परमो वरः॥', 'matto madāyudhānāṃ ca na vadhyo ''yaṃ bhaviṣyati
ity evaṃ śaṃkareṇāpi datto ''sya paramo varaḥ', null, 7036018),
('ramayana-7-36-19', 19, 'Uttara Kanda, Sarga 36, Verse 19', 'सर्वेषां ब्रह्मदण्डानामवध्योऽयं भविष्यति।
दीर्घायुश्च महात्मा च इति ब्रह्माब्रवीद्वचः॥', 'sarveṣāṃ brahmadaṇḍānām avadhyo ''yaṃ bhaviṣyati
dīrghāyuś ca mahātmā ca iti brahmābravīd vacaḥ', null, 7036019),
('ramayana-7-36-20', 20, 'Uttara Kanda, Sarga 36, Verse 20', 'विश्वकर्मा तु दृष्ट्वैनं बालसूर्योपमं शिशुम्।
शिल्पिनां प्रवरः प्राह वरमस्य महामतिः॥', 'viśvakarmā tu dṛṣṭvainaṃ bālasūryopamaṃ śiśum
śilpināṃ pravaraḥ prāha varam asya mahāmatiḥ', null, 7036020),
('ramayana-7-36-21', 21, 'Uttara Kanda, Sarga 36, Verse 21', 'विनिर्मितानि देवानामायुधानीह यानि तु।
तेषां संग्रामकाले तु अवध्योऽयं भविष्यति॥', 'vinirmitāni devānām āyudhānīha yāni tu
teṣāṃ saṃgrāmakāle tu avadhyo ''yaṃ bhaviṣyati', null, 7036021),
('ramayana-7-36-22', 22, 'Uttara Kanda, Sarga 36, Verse 22', 'ततः सुराणां तु वरैर्दृष्ट्वा ह्येनमलंकृतम्।
चतुर्मुखस्तुष्टमुखो वायुमाह जगद्गुरुः॥', 'tataḥ surāṇāṃ tu varair dṛṣṭvā hy enam alaṃkṛtam
caturmukhas tuṣṭamukho vāyum āha jagadguruḥ', null, 7036022),
('ramayana-7-36-23', 23, 'Uttara Kanda, Sarga 36, Verse 23', 'अमित्राणां भयकरो मित्राणामभयंकरः।
अजेयो भविता तेऽत्र पुत्रो मारुतमारुतिः॥', 'amitrāṇāṃ bhayakaro mitrāṇām abhayaṃkaraḥ
ajeyo bhavitā te ''tra putro mārutamārutiḥ', null, 7036023),
('ramayana-7-36-24', 24, 'Uttara Kanda, Sarga 36, Verse 24', 'रावणोत्सादनार्थानि रामप्रीतिकराणि च।
रोमहर्षकराण्येष कर्ता कर्माणि संयुगे॥', 'rāvaṇotsādanārthāni rāmaprītikarāṇi ca
romaharṣakarāṇy eṣa kartā karmāṇi saṃyuge', null, 7036024),
('ramayana-7-36-25', 25, 'Uttara Kanda, Sarga 36, Verse 25', 'एवमुक्त्वा तमामन्त्र्य मारुतं तेऽमरैः सह।
यथागतं ययुः सर्वे पितामहपुरोगमाः॥', 'evam uktvā tam āmantrya mārutaṃ te ''maraiḥ saha
yathāgataṃ yayuḥ sarve pitāmahapurogamāḥ', null, 7036025),
('ramayana-7-36-26', 26, 'Uttara Kanda, Sarga 36, Verse 26', 'सोऽपि गन्धवहः पुत्रं प्रगृह्य गृहमानयत्।
अञ्जनायास्तमाख्याय वरं दत्तं विनिःसृतः॥', 'so ''pi gandhavahaḥ putraṃ pragṛhya gṛham ānayat
añjanāyāstam ākhyāya varaṃ dattaṃ viniḥsṛtaḥ', null, 7036026),
('ramayana-7-36-27', 27, 'Uttara Kanda, Sarga 36, Verse 27', 'प्राप्य राम वरानेष वरदानबलान्वितः।
बलेनात्मनि संस्थेन सोऽपूर्यत यथार्णवः॥', 'prāpya rāma varān eṣa varadānabalānvitaḥ
balenātmani saṃsthena so ''pūryata yathārṇavaḥ', null, 7036027),
('ramayana-7-36-28', 28, 'Uttara Kanda, Sarga 36, Verse 28', 'बलेनापूर्यमाणो हि एष वानरपुंगवः।
आश्रमेषु महर्षीणामपराध्यति निर्भयः॥', 'balenāpūryamāṇo hi eṣa vānarapuṃgavaḥ
āśrameṣu maharṣīṇām aparādhyati nirbhayaḥ', null, 7036028),
('ramayana-7-36-29', 29, 'Uttara Kanda, Sarga 36, Verse 29', 'स्रुग्भाण्डानग्निहोत्रं च वल्कलानां च संचयान्।
भग्नविच्छिन्नविध्वस्तान्सुशान्तानां करोत्ययम्॥', 'srugbhāṇḍān agnihotraṃ ca valkalānāṃ ca saṃcayān
bhagnavicchinnavidhvastān suśāntānāṃ karoty ayam', null, 7036029),
('ramayana-7-36-30', 30, 'Uttara Kanda, Sarga 36, Verse 30', 'सर्वेषां ब्रह्मदण्डानामवध्यं ब्रह्मणा कृतम्।
जानन्त ऋषयस्तं वै क्षमन्ते तस्य नित्यशः॥', 'sarveṣāṃ brahmadaṇḍānām avadhyaṃ brahmaṇā kṛtam
jānanta ṛṣayas taṃ vai kṣamante tasya nityaśaḥ', null, 7036030),
('ramayana-7-36-31', 31, 'Uttara Kanda, Sarga 36, Verse 31', 'यदा केषरिणा त्वेष वायुना साञ्जनेन च।
प्रतिषिद्धोऽपि मर्यादां लङ्घयत्येव वानरः॥', 'yadā keṣariṇā tv eṣa vāyunā sāñjanena ca
pratiṣiddho ''pi maryādāṃ laṅghayaty eva vānaraḥ', null, 7036031),
('ramayana-7-36-32', 32, 'Uttara Kanda, Sarga 36, Verse 32', 'ततो महर्षयः क्रुद्धा भृग्वङ्गिरसवंशजाः।
शेपुरेनं रघुश्रेष्ठ नातिक्रुद्धातिमन्यवः॥', 'tato maharṣayaḥ kruddhā bhṛgvaṅgirasavaṃśajāḥ
śepur enaṃ raghuśreṣṭha nātikruddhātimanyavaḥ', null, 7036032),
('ramayana-7-36-33', 33, 'Uttara Kanda, Sarga 36, Verse 33', 'बाधसे यत्समाश्रित्य बलमस्मान्प्लवंगम।
तद्दीर्घकालं वेत्तासि नास्माकं शापमोहितः॥', 'bādhase yat samāśritya balam asmān plavaṃgama
tad dīrghakālaṃ vettāsi nāsmākaṃ śāpamohitaḥ', null, 7036033),
('ramayana-7-36-34', 34, 'Uttara Kanda, Sarga 36, Verse 34', 'ततस्तु हृततेजौजा महर्षिवचनौजसा।
एषो श्रमाणि नात्येति मृदुभावगतश्चरन्॥', 'tatas tu hṛtatejaujā maharṣivacanaujasā
eṣo śramāṇi nātyeti mṛdubhāvagataś caran', null, 7036034),
('ramayana-7-36-35', 35, 'Uttara Kanda, Sarga 36, Verse 35', 'अथ ऋक्षरजा नाम वालिसुग्रीवयोः पिता।
सर्ववानरराजासीत्तेजसा इव भास्करः॥', 'atha ṛkṣarajā nāma vālisugrīvayoḥ pitā
sarvavānararājāsīt tejasā iva bhāskaraḥ', null, 7036035),
('ramayana-7-36-36', 36, 'Uttara Kanda, Sarga 36, Verse 36', 'स तु राज्यं चिरं कृत्वा वानराणां हरीश्वरः।
ततस्त्वर्क्षरजा नाम कालधर्मेण संगतः॥', 'sa tu rājyaṃ ciraṃ kṛtvā vānarāṇāṃ harīśvaraḥ
tatas tvarkṣarajā nāma kāladharmeṇa saṃgataḥ', null, 7036036),
('ramayana-7-36-37', 37, 'Uttara Kanda, Sarga 36, Verse 37', 'तस्मिन्नस्तमिते वाली मन्त्रिभिर्मन्त्रकोविदैः।
पित्र्ये पदे कृतो राजा सुग्रीवो वालिनः पदे॥', 'tasminn astamite vālī mantribhir mantrakovidaiḥ
pitrye pade kṛto rājā sugrīvo vālinaḥ pade', null, 7036037),
('ramayana-7-36-38', 38, 'Uttara Kanda, Sarga 36, Verse 38', 'सुग्रीवेण समं त्वस्य अद्वैधं छिद्रवर्जितम्।
अहार्यं सख्यमभवदनिलस्य यथाग्निना॥', 'sugrīveṇa samaṃ tv asya advaidhaṃ chidravarjitam
ahāryaṃ sakhyam abhavad anilasya yathāgninā', null, 7036038),
('ramayana-7-36-39', 39, 'Uttara Kanda, Sarga 36, Verse 39', 'एष शापवशादेव न वेदबलमात्मनः।
वालिसुग्रीवयोर्वैरं यदा राम समुत्थितम्॥', 'eṣa śāpavaśād eva na vedabalam ātmanaḥ
vālisugrīvayor vairaṃ yadā rāma samutthitam', null, 7036039),
('ramayana-7-36-40', 40, 'Uttara Kanda, Sarga 36, Verse 40', 'न ह्येष राम सुग्रीवो भ्राम्यमाणोऽपि वालिना।
वेदयानो न च ह्येष बलमात्मनि मारुतिः॥', 'na hy eṣa rāma sugrīvo bhrāmyamāṇo ''pi vālinā
vedayāno na ca hy eṣa balam ātmani mārutiḥ', null, 7036040),
('ramayana-7-36-41', 41, 'Uttara Kanda, Sarga 36, Verse 41', 'पराक्रमोत्साहमतिप्रतापैः सौशील्यमाधुर्यनयानयैश्च।
गाम्भीर्यचातुर्यसुवीर्यधैर्यैर्हनूमतः कोऽप्यधिकोऽस्ति लोके॥', 'parākramotsāhamatipratāpaiḥ sauśīlyamādhuryanayānayaiś ca
gāmbhīryacāturyasuvīryadhairyair hanūmataḥ ko ''py adhiko ''sti loke', null, 7036041),
('ramayana-7-36-42', 42, 'Uttara Kanda, Sarga 36, Verse 42', 'असौ पुरा व्याकरणं ग्रहीष्यन्सूर्योन्मुखः पृष्ठगमः कपीन्द्रः।
उद्यद्गिरेरस्तगिरिं जगाम ग्रन्थं महद्धारयदप्रमेयः॥', 'asau purā vyākaraṇaṃ grahīṣyan sūryonmukhaḥ pṛṣṭhagamaḥ kapīndraḥ
udyadgirer astagiriṃ jagāma granthaṃ mahad dhārayad aprameyaḥ', null, 7036042),
('ramayana-7-36-43', 43, 'Uttara Kanda, Sarga 36, Verse 43', 'प्रवीविविक्षोरिव सागरस्य लोकान्दिधक्षोरिव पावकस्य।
लोकक्षयेष्वेव यथान्तकस्य हनूमतः स्थास्यति कः पुरस्तात्॥', 'pravīvivikṣor iva sāgarasya lokān didhakṣor iva pāvakasya
lokakṣayeṣv eva yathāntakasya hanūmataḥ sthāsyati kaḥ purastāt', null, 7036043),
('ramayana-7-36-44', 44, 'Uttara Kanda, Sarga 36, Verse 44', 'एषोऽपि चान्ये च महाकपीन्द्राः सुग्रीवमैन्दद्विविदाः सनीलाः।
सतारतारेयनलाः सरम्भास्त्वत्कारणाद्राम सुरैर्हि सृष्टाः॥', 'eṣo ''pi cānye ca mahākapīndrāḥ sugrīvamaindadvividāḥ sanīlāḥ
satāratāreyanalāḥ sarambhās tvatkāraṇād rāma surair hi sṛṣṭāḥ', null, 7036044),
('ramayana-7-36-45', 45, 'Uttara Kanda, Sarga 36, Verse 45', 'तदेतत्कथितं सर्वं यन्मां त्वं परिपृच्छसि।
हनूमतो बालभावे कर्मैतत्कथितं मया॥', 'tad etat kathitaṃ sarvaṃ yan māṃ tvaṃ paripṛcchasi
hanūmato bālabhāve karmaitat kathitaṃ mayā', null, 7036045),
('ramayana-7-36-46', 46, 'Uttara Kanda, Sarga 36, Verse 46', 'दृष्टः संभाषितश्चासि राम गच्छमहे वयम्।
एवमुक्त्वा गताः सर्वे ऋषयस्ते यथागतम्॥', 'dṛṣṭaḥ saṃbhāṣitaś cāsi rāma gacchamahe vayam
evam uktvā gatāḥ sarve ṛṣayas te yathāgatam', null, 7036046)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 37 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-37-1', 1, 'Uttara Kanda, Sarga 37, Verse 1', 'विमृश्य च ततो रामो वयस्यमकुतोभयम्।
प्रतर्दनं काशिपतिं परिष्वज्येदमब्रवीत्॥', 'vimṛśya ca tato rāmo vayasyam akutobhayam
pratardanaṃ kāśipatiṃ pariṣvajyedam abravīt', null, 7037001),
('ramayana-7-37-2', 2, 'Uttara Kanda, Sarga 37, Verse 2', 'दर्शिता भवता प्रीतिर्दर्शितं सौहृदं परम्।
उद्योगश्च कृतो राजन्भरतेन त्वया सह॥', 'darśitā bhavatā prītir darśitaṃ sauhṛdaṃ param
udyogaś ca kṛto rājan bharatena tvayā saha', null, 7037002),
('ramayana-7-37-3', 3, 'Uttara Kanda, Sarga 37, Verse 3', 'तद्भवानद्य काशेयीं पुरीं वाराणसीं व्रज।
रमणीयां त्वया गुप्तां सुप्राकारां सुतोरणाम्॥', 'tad bhavān adya kāśeyīṃ purīṃ vārāṇasīṃ vraja
ramaṇīyāṃ tvayā guptāṃ suprākārāṃ sutoraṇām', null, 7037003),
('ramayana-7-37-4', 4, 'Uttara Kanda, Sarga 37, Verse 4', 'एतावदुक्त्वा उत्थाय काकुत्स्थः परमासनात्।
पर्यष्वजत धर्मात्मा निरन्तरमुरोगतम्॥', 'etāvad uktvā utthāya kākutsthaḥ paramāsanāt
paryaṣvajata dharmātmā nirantaram urogatam', null, 7037004),
('ramayana-7-37-5', 5, 'Uttara Kanda, Sarga 37, Verse 5', 'विसृज्य तं वयस्यं स स्वागतान्पृथिवीपतीन्।
प्रहसन्राघवो वाक्यमुवाच मधुराक्षरम्॥', 'visṛjya taṃ vayasyaṃ sa svāgatān pṛthivīpatīn
prahasan rāghavo vākyam uvāca madhurākṣaram', null, 7037005),
('ramayana-7-37-6', 6, 'Uttara Kanda, Sarga 37, Verse 6', 'भवतां प्रीतिरव्यग्रा तेजसा परिरक्षिता।
धर्मश्च नियतो नित्यं सत्यं च भवतां सदा॥', 'bhavatāṃ prītir avyagrā tejasā parirakṣitā
dharmaś ca niyato nityaṃ satyaṃ ca bhavatāṃ sadā', null, 7037006),
('ramayana-7-37-7', 7, 'Uttara Kanda, Sarga 37, Verse 7', 'युष्माकं च प्रभावेन तेजसा च महात्मनाम्।
हतो दुरात्मा दुर्बुद्धी रावणो राक्षसाधिपः॥', 'yuṣmākaṃ ca prabhāvena tejasā ca mahātmanām
hato durātmā durbuddhī rāvaṇo rākṣasādhipaḥ', null, 7037007),
('ramayana-7-37-8', 8, 'Uttara Kanda, Sarga 37, Verse 8', 'हेतुमात्रमहं तत्र भवतां तेजसां हतः।
रावणः सगणो युद्धे सपुत्रः सहबान्धवः॥', 'hetumātram ahaṃ tatra bhavatāṃ tejasāṃ hataḥ
rāvaṇaḥ sagaṇo yuddhe saputraḥ sahabāndhavaḥ', null, 7037008),
('ramayana-7-37-9', 9, 'Uttara Kanda, Sarga 37, Verse 9', 'भवन्तश्च समानीता भरतेन महात्मना।
श्रुत्वा जनकराजस्य कानने तनयां हृताम्॥', 'bhavantaś ca samānītā bharatena mahātmanā
śrutvā janakarājasya kānane tanayāṃ hṛtām', null, 7037009),
('ramayana-7-37-10', 10, 'Uttara Kanda, Sarga 37, Verse 10', 'उद्युक्तानां च सर्वेषां पार्थिवानां महात्मनाम्।
कालो ह्यतीतः सुमहान्गमने रोचतां मतिः॥', 'udyuktānāṃ ca sarveṣāṃ pārthivānāṃ mahātmanām
kālo hy atītaḥ sumahān gamane rocatāṃ matiḥ', null, 7037010),
('ramayana-7-37-11', 11, 'Uttara Kanda, Sarga 37, Verse 11', 'प्रत्यूचुस्तं च राजानो हर्षेण महतान्विताः।
दिष्ट्या त्वं विजयी राम राज्यं चापि प्रतिष्ठितम्॥', 'pratyūcus taṃ ca rājāno harṣeṇa mahatānvitāḥ
diṣṭyā tvaṃ vijayī rāma rājyaṃ cāpi pratiṣṭhitam', null, 7037011),
('ramayana-7-37-12', 12, 'Uttara Kanda, Sarga 37, Verse 12', 'दिष्ट्या प्रत्याहृता सीता दिष्ट्या शत्रुः पराजितः।
एष नः परमः काम एषा नः कीर्तिरुत्तमा॥', 'diṣṭyā pratyāhṛtā sītā diṣṭyā śatruḥ parājitaḥ
eṣa naḥ paramaḥ kāma eṣā naḥ kīrtir uttamā', null, 7037012),
('ramayana-7-37-13', 13, 'Uttara Kanda, Sarga 37, Verse 13', 'यत्त्वां विजयिनं राम पश्यामो हतशात्रवम्।
उपपन्नं च काकुत्स्थ यत्त्वमस्मान्प्रशंससि॥', 'yat tvāṃ vijayinaṃ rāma paśyāmo hataśātravam
upapannaṃ ca kākutstha yat tvam asmān praśaṃsasi', null, 7037013),
('ramayana-7-37-14', 14, 'Uttara Kanda, Sarga 37, Verse 14', 'प्रशंसार्हा हि जानन्ति प्रशंसां वक्तुमीदृशीम्।
आपृच्छामो गमिष्यामो हृदिस्थो नः सदा भवान्॥', 'praśaṃsārhā hi jānanti praśaṃsāṃ vaktum īdṛśīm
āpṛcchāmo gamiṣyāmo hṛdistho naḥ sadā bhavān', null, 7037014),
('ramayana-7-37-15', 15, 'Uttara Kanda, Sarga 37, Verse 15', 'भवेच्च ते महाराज प्रीतिरस्मासु नित्यदा॥', 'bhavec ca te mahārāja prītir asmāsu nityadā', null, 7037015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 38 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-38-1', 1, 'Uttara Kanda, Sarga 38, Verse 1', 'ते प्रयाता महात्मानः पार्थिवाः सर्वतो दिशम्।
कम्पयन्तो महीं वीराः स्वपुराणि प्रहृष्टवत्॥', 'te prayātā mahātmānaḥ pārthivāḥ sarvato diśam
kampayanto mahīṃ vīrāḥ svapurāṇi prahṛṣṭavat', null, 7038001),
('ramayana-7-38-2', 2, 'Uttara Kanda, Sarga 38, Verse 2', 'अक्षौहिणी सहस्रैस्ते समवेतास्त्वनेकशः।
हृष्टाः प्रतिगताः सर्वे राघवार्थे समागताः॥', 'akṣauhiṇī sahasrais te samavetās tv anekaśaḥ
hṛṣṭāḥ pratigatāḥ sarve rāghavārthe samāgatāḥ', null, 7038002),
('ramayana-7-38-3', 3, 'Uttara Kanda, Sarga 38, Verse 3', 'ऊचुश्चैव महीपाला बलदर्पसमन्विताः।
न नाम रावणं युद्धे पश्यामः पुरतः स्थितम्॥', 'ūcuś caiva mahīpālā baladarpasamanvitāḥ
na nāma rāvaṇaṃ yuddhe paśyāmaḥ purataḥ sthitam', null, 7038003),
('ramayana-7-38-4', 4, 'Uttara Kanda, Sarga 38, Verse 4', 'भरतेन वयं पश्चात्समानीता निरर्थकम्।
हता हि राक्षसास्तत्र पार्थिवैः स्युर्न संशयः॥', 'bharatena vayaṃ paścāt samānītā nirarthakam
hatā hi rākṣasās tatra pārthivaiḥ syur na saṃśayaḥ', null, 7038004),
('ramayana-7-38-5', 5, 'Uttara Kanda, Sarga 38, Verse 5', 'रामस्य बाहुवीर्येण पालिता लक्ष्मणस्य च।
सुखं पारे समुद्रस्य युध्येम विगतज्वराः॥', 'rāmasya bāhuvīryeṇa pālitā lakṣmaṇasya ca
sukhaṃ pāre samudrasya yudhyema vigatajvarāḥ', null, 7038005),
('ramayana-7-38-6', 6, 'Uttara Kanda, Sarga 38, Verse 6', 'एताश्चान्याश्च राजानः कथास्तत्र सहस्रशः।
कथयन्तः स्वराष्ट्राणि विविशुस्ते महारथाः॥', 'etāś cānyāś ca rājānaḥ kathās tatra sahasraśaḥ
kathayantaḥ svarāṣṭrāṇi viviśus te mahārathāḥ', null, 7038006),
('ramayana-7-38-7', 7, 'Uttara Kanda, Sarga 38, Verse 7', 'यथापुराणि ते गत्वा रत्नानि विविधानि च।
रामाय प्रियकामार्थमुपहारान्नृपा ददुः॥', 'yathāpurāṇi te gatvā ratnāni vividhāni ca
rāmāya priyakāmārtham upahārān nṛpā daduḥ', null, 7038007),
('ramayana-7-38-8', 8, 'Uttara Kanda, Sarga 38, Verse 8', 'अश्वान्रत्नानि वस्त्राणि हस्तिनश्च मदोत्कटान्।
चन्दनानि च दिव्यानि दिव्यान्याभरणानि च॥', 'aśvān ratnāni vastrāṇi hastinaś ca madotkaṭān
candanāni ca divyāni divyāny ābharaṇāni ca', null, 7038008),
('ramayana-7-38-9', 9, 'Uttara Kanda, Sarga 38, Verse 9', 'भरतो लक्ष्मणश्चैव शत्रुघ्नश्च महारथः।
आदाय तानि रत्नानि अयोध्यामगमन्पुनः॥', 'bharato lakṣmaṇaś caiva śatrughnaś ca mahārathaḥ
ādāya tāni ratnāni ayodhyām agaman punaḥ', null, 7038009),
('ramayana-7-38-10', 10, 'Uttara Kanda, Sarga 38, Verse 10', 'आगताश्च पुरीं रम्यामयोध्यां पुरुषर्षभाः।
ददुः सर्वाणि रत्नानि राघवाय महात्मने॥', 'āgatāś ca purīṃ ramyām ayodhyāṃ puruṣarṣabhāḥ
daduḥ sarvāṇi ratnāni rāghavāya mahātmane', null, 7038010),
('ramayana-7-38-11', 11, 'Uttara Kanda, Sarga 38, Verse 11', 'प्रतिगृह्य च तत्सर्वं प्रीतियुक्तः स राघवः।
सर्वाणि तानि प्रददौ सुग्रीवाय महात्मने॥', 'pratigṛhya ca tat sarvaṃ prītiyuktaḥ sa rāghavaḥ
sarvāṇi tāni pradadau sugrīvāya mahātmane', null, 7038011),
('ramayana-7-38-12', 12, 'Uttara Kanda, Sarga 38, Verse 12', 'विभीषणाय च ददौ ये चान्ये ऋक्षवानराः।
हनूमत्प्रमुखा वीरा राक्षसाश्च महाबलाः॥', 'vibhīṣaṇāya ca dadau ye cānye ṛkṣavānarāḥ
hanūmatpramukhā vīrā rākṣasāś ca mahābalāḥ', null, 7038012),
('ramayana-7-38-13', 13, 'Uttara Kanda, Sarga 38, Verse 13', 'ते सर्वे हृष्टमनसो रामदत्तानि तान्यथ।
शिरोभिर्धारयामासुर्बाहुभिश्च महाबलाः॥', 'te sarve hṛṣṭamanaso rāmadattāni tāny atha
śirobhir dhārayām āsur bāhubhiś ca mahābalāḥ', null, 7038013),
('ramayana-7-38-14', 14, 'Uttara Kanda, Sarga 38, Verse 14', 'पपुश्चैव सुगन्धीनि मधूनि विविधानि च।
मांसानि च सुमृष्टानि फलान्यास्वादयन्ति च॥', 'papuś caiva sugandhīni madhūni vividhāni ca
māṃsāni ca sumṛṣṭāni phalāny āsvādayanti ca', null, 7038014),
('ramayana-7-38-15', 15, 'Uttara Kanda, Sarga 38, Verse 15', 'एवं तेषां निवसतां मासः साग्रो गतस्तदा।
मुहूर्तमिव तत्सर्वं रामभक्त्या समर्थयन्॥', 'evaṃ teṣāṃ nivasatāṃ māsaḥ sāgro gatas tadā
muhūrtam iva tat sarvaṃ rāmabhaktyā samarthayan', null, 7038015),
('ramayana-7-38-16', 16, 'Uttara Kanda, Sarga 38, Verse 16', 'रेमे रामः स तैः सार्धं वानरैः कामरूपिभिः।
राजभिश्च महावीर्यै राक्षसैश्च महाबलैः॥', 'reme rāmaḥ sa taiḥ sārdhaṃ vānaraiḥ kāmarūpibhiḥ
rājabhiś ca mahāvīryai rākṣasaiś ca mahābalaiḥ', null, 7038016),
('ramayana-7-38-17', 17, 'Uttara Kanda, Sarga 38, Verse 17', 'एवं तेषां ययौ मासो द्वितीयः शैशिरः सुखम्।
वानराणां प्रहृष्टानां राक्षसानां च सर्वशः॥', 'evaṃ teṣāṃ yayau māso dvitīyaḥ śaiśiraḥ sukham
vānarāṇāṃ prahṛṣṭānāṃ rākṣasānāṃ ca sarvaśaḥ', null, 7038017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 39 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-39-1', 1, 'Uttara Kanda, Sarga 39, Verse 1', 'तथा स्म तेषां वसतामृक्षवानररक्षसाम्।
राघवस्तु महातेजाः सुग्रीवमिदमब्रवीत्॥', 'tathā sma teṣāṃ vasatām ṛkṣavānararakṣasām
rāghavas tu mahātejāḥ sugrīvam idam abravīt', null, 7039001),
('ramayana-7-39-2', 2, 'Uttara Kanda, Sarga 39, Verse 2', 'गम्यतां सौम्य किष्किन्धां दुराधर्षं सुरासुरैः।
पालयस्व सहामात्यै राज्यं निहतकण्टकम्॥', 'gamyatāṃ saumya kiṣkindhāṃ durādharṣaṃ surāsuraiḥ
pālayasva sahāmātyai rājyaṃ nihatakaṇṭakam', null, 7039002),
('ramayana-7-39-3', 3, 'Uttara Kanda, Sarga 39, Verse 3', 'अङ्गदं च महाबाहो प्रीत्या परमयान्वितः।
पश्य त्वं हनुमन्तं च नलं च सुमहाबलम्॥', 'aṅgadaṃ ca mahābāho prītyā paramayānvitaḥ
paśya tvaṃ hanumantaṃ ca nalaṃ ca sumahābalam', null, 7039003),
('ramayana-7-39-4', 4, 'Uttara Kanda, Sarga 39, Verse 4', 'सुषेणं श्वशुरं शूरं तारं च बलिनां वरम्।
कुमुदं चैव दुर्धर्षं नीलं च सुमहाबलम्॥', 'suṣeṇaṃ śvaśuraṃ śūraṃ tāraṃ ca balināṃ varam
kumudaṃ caiva durdharṣaṃ nīlaṃ ca sumahābalam', null, 7039004),
('ramayana-7-39-5', 5, 'Uttara Kanda, Sarga 39, Verse 5', 'वीरं शतबलिं चैव मैन्दं द्विविदमेव च।
गजं गवाक्षं गवयं शरभं च महाबलम्॥', 'vīraṃ śatabaliṃ caiva maindaṃ dvividam eva ca
gajaṃ gavākṣaṃ gavayaṃ śarabhaṃ ca mahābalam', null, 7039005),
('ramayana-7-39-6', 6, 'Uttara Kanda, Sarga 39, Verse 6', 'ऋक्षराजं च दुर्धर्षं जाम्बवन्तं महाबलम्।
पश्य प्रीतिसमायुक्तो गन्धमादनमेव च॥', 'ṛkṣarājaṃ ca durdharṣaṃ jāmbavantaṃ mahābalam
paśya prītisamāyukto gandhamādanam eva ca', null, 7039006),
('ramayana-7-39-7', 7, 'Uttara Kanda, Sarga 39, Verse 7', 'ये चान्ये सुमहात्मानो मदर्थे त्यक्तजीविताः।
पश्य त्वं प्रीतिसंयुक्तो मा चैषां विप्रियं कृथाः॥', 'ye cānye sumahātmāno madarthe tyaktajīvitāḥ
paśya tvaṃ prītisaṃyukto mā caiṣāṃ vipriyaṃ kṛthāḥ', null, 7039007),
('ramayana-7-39-8', 8, 'Uttara Kanda, Sarga 39, Verse 8', 'एवमुक्त्वा च सुग्रीवं प्रशस्य च पुनः पुनः।
विभीषणमथोवाच रामो मधुरया गिरा॥', 'evam uktvā ca sugrīvaṃ praśasya ca punaḥ punaḥ
vibhīṣaṇam athovāca rāmo madhurayā girā', null, 7039008),
('ramayana-7-39-9', 9, 'Uttara Kanda, Sarga 39, Verse 9', 'तङ्कां प्रशाधि धर्मेण संमतो ह्यसि पार्थिव।
पुरस्य राक्षसानां च भ्रातुर्वैश्वरणस्य च॥', 'taṅkāṃ praśādhi dharmeṇa saṃmato hy asi pārthiva
purasya rākṣasānāṃ ca bhrātur vaiśvaraṇasya ca', null, 7039009),
('ramayana-7-39-10', 10, 'Uttara Kanda, Sarga 39, Verse 10', 'मा च बुद्धिमधर्मे त्वं कुर्या राजन्कथं चन।
बुद्धिमन्तो हि राजानो ध्रुवमश्नन्ति मेदिनीम्॥', 'mā ca buddhim adharme tvaṃ kuryā rājan kathaṃ cana
buddhimanto hi rājāno dhruvam aśnanti medinīm', null, 7039010),
('ramayana-7-39-11', 11, 'Uttara Kanda, Sarga 39, Verse 11', 'अहं च नित्यशो राजन्सुग्रीवसहितस्त्वया।
स्मर्तव्यः परया प्रीत्या गच्छ त्वं विगतज्वरः॥', 'ahaṃ ca nityaśo rājan sugrīvasahitas tvayā
smartavyaḥ parayā prītyā gaccha tvaṃ vigatajvaraḥ', null, 7039011),
('ramayana-7-39-12', 12, 'Uttara Kanda, Sarga 39, Verse 12', 'रामस्य भाषितं श्रुत्वा ऋष्कवानरराक्षसाः।
साधु साध्विति काकुत्स्थं प्रशशंसुः पुनः पुनः॥', 'rāmasya bhāṣitaṃ śrutvā ṛṣkavānararākṣasāḥ
sādhu sādhv iti kākutsthaṃ praśaśaṃsuḥ punaḥ punaḥ', null, 7039012),
('ramayana-7-39-13', 13, 'Uttara Kanda, Sarga 39, Verse 13', 'तव बुद्धिर्महाबाहो वीर्यमद्भुतमेव च।
माधुर्यं परमं राम स्वयम्भोरिव नित्यदा॥', 'tava buddhir mahābāho vīryam adbhutam eva ca
mādhuryaṃ paramaṃ rāma svayambhor iva nityadā', null, 7039013),
('ramayana-7-39-14', 14, 'Uttara Kanda, Sarga 39, Verse 14', 'तेषामेवं ब्रुवाणानां वानराणां च रक्षसाम्।
हनूमत्प्रणतो भूत्वा राघवं वाक्यमब्रवीत्॥', 'teṣām evaṃ bruvāṇānāṃ vānarāṇāṃ ca rakṣasām
hanūmatpraṇato bhūtvā rāghavaṃ vākyam abravīt', null, 7039014),
('ramayana-7-39-15', 15, 'Uttara Kanda, Sarga 39, Verse 15', 'स्नेहो मे परमो राजंस्त्वयि नित्यं प्रतिष्ठितः।
भक्तिश्च नियता वीर भावो नान्यत्र गच्छति॥', 'sneho me paramo rājaṃs tvayi nityaṃ pratiṣṭhitaḥ
bhaktiś ca niyatā vīra bhāvo nānyatra gacchati', null, 7039015),
('ramayana-7-39-16', 16, 'Uttara Kanda, Sarga 39, Verse 16', 'यावद्रामकथां वीर श्रोष्येऽहं पृथिवीतले।
तावच्छरीरे वत्स्यन्तु मम प्राणा न संशयः॥', 'yāvad rāmakathāṃ vīra śroṣye ''haṃ pṛthivītale
tāvac charīre vatsyantu mama prāṇā na saṃśayaḥ', null, 7039016),
('ramayana-7-39-17', 17, 'Uttara Kanda, Sarga 39, Verse 17', 'एवं ब्रुवाणं राजेन्द्रो हनूमन्तमथासनात्।
उत्थाय च परिष्वज्य वाक्यमेतदुवाच ह॥', 'evaṃ bruvāṇaṃ rājendro hanūmantam athāsanāt
utthāya ca pariṣvajya vākyam etad uvāca ha', null, 7039017),
('ramayana-7-39-18', 18, 'Uttara Kanda, Sarga 39, Verse 18', 'एवमेतत्कपिश्रेष्ठ भविता नात्र संशयः।
लोका हि यावत्स्थास्यन्ति तावत्स्थास्यति मे कथा॥', 'evam etat kapiśreṣṭha bhavitā nātra saṃśayaḥ
lokā hi yāvat sthāsyanti tāvat sthāsyati me kathā', null, 7039018),
('ramayana-7-39-19', 19, 'Uttara Kanda, Sarga 39, Verse 19', 'चरिष्यति कथा यावल्लोकानेषा हि मामिका।
तावच्छरीरे वत्स्यन्ति प्राणास्तव न संशयः॥', 'cariṣyati kathā yāval lokān eṣā hi māmikā
tāvac charīre vatsyanti prāṇās tava na saṃśayaḥ', null, 7039019),
('ramayana-7-39-20', 20, 'Uttara Kanda, Sarga 39, Verse 20', 'ततोऽस्य हारं चन्द्राभं मुच्य कण्ठात्स राघवः।
वैदूर्यतरलं स्नेहादाबबन्धे हनूमति॥', 'tato ''sya hāraṃ candrābhaṃ mucya kaṇṭhāt sa rāghavaḥ
vaidūryataralaṃ snehād ābabandhe hanūmati', null, 7039020),
('ramayana-7-39-21', 21, 'Uttara Kanda, Sarga 39, Verse 21', 'तेनोरसि निबद्धेन हारेण स महाकपिः।
रराज हेमशैलेन्द्रश्चन्द्रेणाक्रान्तमस्तकः॥', 'tenorasi nibaddhena hāreṇa sa mahākapiḥ
rarāja hemaśailendraś candreṇākrāntamastakaḥ', null, 7039021),
('ramayana-7-39-22', 22, 'Uttara Kanda, Sarga 39, Verse 22', 'श्रुत्वा तु राघवस्यैतदुत्थायोत्थाय वानराः।
प्रणम्य शिरसा पादौ प्रजग्मुस्ते महाबलाः॥', 'śrutvā tu rāghavasyaitad utthāyotthāya vānarāḥ
praṇamya śirasā pādau prajagmus te mahābalāḥ', null, 7039022),
('ramayana-7-39-23', 23, 'Uttara Kanda, Sarga 39, Verse 23', 'सुग्रीवश्चैव रामेण परिष्वक्तो महाभुजः।
विभीषणश्च धर्मात्मा निरन्तरमुरोगतः॥', 'sugrīvaś caiva rāmeṇa pariṣvakto mahābhujaḥ
vibhīṣaṇaś ca dharmātmā nirantaram urogataḥ', null, 7039023),
('ramayana-7-39-24', 24, 'Uttara Kanda, Sarga 39, Verse 24', 'सर्वे च ते बाष्पगलाः साश्रुनेत्रा विचेतसः।
संमूढा इव दुःखेन त्यजन्ते राघवं तदा॥', 'sarve ca te bāṣpagalāḥ sāśrunetrā vicetasaḥ
saṃmūḍhā iva duḥkhena tyajante rāghavaṃ tadā', null, 7039024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 40 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-40-1', 1, 'Uttara Kanda, Sarga 40, Verse 1', 'विसृज्य च महाबाहुरृक्षवानरराक्षसान्।
भ्रातृभिः सहितो रामः प्रमुमोद सुखी सुखम्॥', 'visṛjya ca mahābāhur ṛkṣavānararākṣasān
bhrātṛbhiḥ sahito rāmaḥ pramumoda sukhī sukham', null, 7040001),
('ramayana-7-40-2', 2, 'Uttara Kanda, Sarga 40, Verse 2', 'अथापराह्णसमये भ्रातृभिः सह राघवः।
शुश्राव मधुरां वाणीमन्तरिक्षात्प्रभाषिताम्॥', 'athāparāhṇasamaye bhrātṛbhiḥ saha rāghavaḥ
śuśrāva madhurāṃ vāṇīm antarikṣāt prabhāṣitām', null, 7040002),
('ramayana-7-40-3', 3, 'Uttara Kanda, Sarga 40, Verse 3', 'सौम्य राम निरीक्षस्व सौम्येन वदनेन माम्।
कैलासशिखरात्प्राप्तं विद्धि मां पुष्करं प्रभो॥', 'saumya rāma nirīkṣasva saumyena vadanena mām
kailāsaśikharāt prāptaṃ viddhi māṃ puṣkaraṃ prabho', null, 7040003),
('ramayana-7-40-4', 4, 'Uttara Kanda, Sarga 40, Verse 4', 'तव शासनमाज्ञाय गतोऽस्मि धनदं प्रति।
उपस्थातुं नरश्रेष्ठ स च मां प्रत्यभाषत॥', 'tava śāsanam ājñāya gato ''smi dhanadaṃ prati
upasthātuṃ naraśreṣṭha sa ca māṃ pratyabhāṣata', null, 7040004),
('ramayana-7-40-5', 5, 'Uttara Kanda, Sarga 40, Verse 5', 'निर्जितस्त्वं नरेन्द्रेण राघवेण महात्मना।
निहत्य युधि दुर्धर्षं रावणं राक्षसाधिपम्॥', 'nirjitas tvaṃ narendreṇa rāghaveṇa mahātmanā
nihatya yudhi durdharṣaṃ rāvaṇaṃ rākṣasādhipam', null, 7040005),
('ramayana-7-40-6', 6, 'Uttara Kanda, Sarga 40, Verse 6', 'ममापि परमा प्रीतिर्हते तस्मिन्दुरात्मनि।
रावणे सगणे सौम्य सपुत्रामात्यबान्धवे॥', 'mamāpi paramā prītir hate tasmin durātmani
rāvaṇe sagaṇe saumya saputrāmātyabāndhave', null, 7040006),
('ramayana-7-40-7', 7, 'Uttara Kanda, Sarga 40, Verse 7', 'स त्वं रामेण लङ्कायां निर्जितः परमात्मना।
वह सौम्य तमेव त्वमहमाज्ञापयामि ते॥', 'sa tvaṃ rāmeṇa laṅkāyāṃ nirjitaḥ paramātmanā
vaha saumya tam eva tvam aham ājñāpayāmi te', null, 7040007),
('ramayana-7-40-8', 8, 'Uttara Kanda, Sarga 40, Verse 8', 'एष मे परमः कामो यत्त्वं राघवनन्दनम्।
वहेर्लोकस्य संयानं गच्छस्व विगतज्वरः॥', 'eṣa me paramaḥ kāmo yat tvaṃ rāghavanandanam
vaher lokasya saṃyānaṃ gacchasva vigatajvaraḥ', null, 7040008),
('ramayana-7-40-9', 9, 'Uttara Kanda, Sarga 40, Verse 9', 'तच्छासनमहं ज्ञात्वा धनदस्य महात्मनः।
त्वत्सकाशं पुनः प्राप्तः स एवं प्रतिगृह्ण माम्॥', 'tacchāsanam ahaṃ jñātvā dhanadasya mahātmanaḥ
tvatsakāśaṃ punaḥ prāptaḥ sa evaṃ pratigṛhṇa mām', null, 7040009),
('ramayana-7-40-10', 10, 'Uttara Kanda, Sarga 40, Verse 10', 'बाढमित्येव काकुत्स्थः पुष्पकं समपूजयत्।
लाजाक्षतैश्च पुष्पैश्च गन्धैश्च सुसुगन्धिभिः॥', 'bāḍham ity eva kākutsthaḥ puṣpakaṃ samapūjayat
lājākṣataiś ca puṣpaiś ca gandhaiś ca susugandhibhiḥ', null, 7040010),
('ramayana-7-40-11', 11, 'Uttara Kanda, Sarga 40, Verse 11', 'गम्यतां च यथाकाममागच्छेस्त्वं यदा स्मरे।
एवमस्त्विति रामेण विसृष्टः पुष्पकः पुनः।
अभिप्रेतां दिशं प्रायात्पुष्पकः पुष्पभूषितः॥', 'gamyatāṃ ca yathākāmam āgacches tvaṃ yadā smare
evam astv iti rāmeṇa visṛṣṭaḥ puṣpakaḥ punaḥ
abhipretāṃ diśaṃ prāyāt puṣpakaḥ puṣpabhūṣitaḥ', null, 7040011),
('ramayana-7-40-12', 12, 'Uttara Kanda, Sarga 40, Verse 12', 'एवमन्तर्हिते तस्मिन्पुष्पके विविधात्मनि।
भरतः प्राञ्जलिर्वाक्यमुवाच रघुनन्दनम्॥', 'evam antarhite tasmin puṣpake vividhātmani
bharataḥ prāñjalir vākyam uvāca raghunandanam', null, 7040012),
('ramayana-7-40-13', 13, 'Uttara Kanda, Sarga 40, Verse 13', 'अत्यद्भुतानि दृश्यन्ते त्वयि राज्यं प्रशासति।
अमानुषाणां सत्त्वानां व्याहृतानि मुहुर्मुहुः॥', 'atyadbhutāni dṛśyante tvayi rājyaṃ praśāsati
amānuṣāṇāṃ sattvānāṃ vyāhṛtāni muhur muhuḥ', null, 7040013),
('ramayana-7-40-14', 14, 'Uttara Kanda, Sarga 40, Verse 14', 'अनामयाच्च मर्त्यानां साग्रो मासो गतो ह्ययम्।
जीर्णानामपि सत्त्वानां मृत्युर्नायाति राघव॥', 'anāmayāc ca martyānāṃ sāgro māso gato hy ayam
jīrṇānām api sattvānāṃ mṛtyur nāyāti rāghava', null, 7040014),
('ramayana-7-40-15', 15, 'Uttara Kanda, Sarga 40, Verse 15', 'पुत्रान्नार्यः प्रसूयन्ते वपुष्मन्तश्च मानवाः।
हर्षश्चाभ्यधिको राजञ्जनस्य पुरवासिनः॥', 'putrān nāryaḥ prasūyante vapuṣmantaś ca mānavāḥ
harṣaś cābhyadhiko rājañ janasya puravāsinaḥ', null, 7040015),
('ramayana-7-40-16', 16, 'Uttara Kanda, Sarga 40, Verse 16', 'काले च वासवो वर्षं पातयत्यमृतोपमम्।
वायवश्चापि वायन्ते स्पर्शवन्तः सुखप्रदाः॥', 'kāle ca vāsavo varṣaṃ pātayaty amṛtopamam
vāyavaś cāpi vāyante sparśavantaḥ sukhapradāḥ', null, 7040016),
('ramayana-7-40-17', 17, 'Uttara Kanda, Sarga 40, Verse 17', 'ईदृशो नश्चिरं राजा भवत्विति नरेश्वर।
कथयन्ति पुरे पौरा जना जनपदेषु च॥', 'īdṛśo naś ciraṃ rājā bhavatv iti nareśvara
kathayanti pure paurā janā janapadeṣu ca', null, 7040017),
('ramayana-7-40-18', 18, 'Uttara Kanda, Sarga 40, Verse 18', 'एता वाचः सुमधुरा भरतेन समीरिताः।
श्रुत्वा रामो मुदा युक्तः प्रमुमोद सुखी सुखम्॥', 'etā vācaḥ sumadhurā bharatena samīritāḥ
śrutvā rāmo mudā yuktaḥ pramumoda sukhī sukham', null, 7040018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 41 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-41-1', 1, 'Uttara Kanda, Sarga 41, Verse 1', 'स विसृज्य ततो रामः पुष्पकं हेमभूषितम्।
प्रविवेश महाबाहुरशोकवनिकां तदा॥', 'sa visṛjya tato rāmaḥ puṣpakaṃ hemabhūṣitam
praviveśa mahābāhur aśokavanikāṃ tadā', null, 7041001),
('ramayana-7-41-2', 2, 'Uttara Kanda, Sarga 41, Verse 2', 'चन्दनागरुचूतैश्च तुङ्गकालेयकैरपि।
देवदारुवनैश्चापि समन्तादुपशोभिताम्॥', 'candanāgarucūtaiś ca tuṅgakāleyakair api
devadāruvanaiś cāpi samantād upaśobhitām', null, 7041002),
('ramayana-7-41-3', 3, 'Uttara Kanda, Sarga 41, Verse 3', 'प्रियङ्गुभिः कदम्बैश्च तथा कुरबकैरपि।
जम्बूभिः पाटलीभिश्च कोविदारैश्च संवृताम्॥', 'priyaṅgubhiḥ kadambaiś ca tathā kurabakair api
jambūbhiḥ pāṭalībhiś ca kovidāraiś ca saṃvṛtām', null, 7041003),
('ramayana-7-41-4', 4, 'Uttara Kanda, Sarga 41, Verse 4', 'सर्वदा कुसुमै रम्यैः फलवद्भिर्मनोरमैः।
चारुपल्लवपुष्पाढ्यैर्मत्तभ्रमरसंकुलैः॥', 'sarvadā kusumai ramyaiḥ phalavadbhir manoramaiḥ
cārupallavapuṣpāḍhyair mattabhramarasaṃkulaiḥ', null, 7041004),
('ramayana-7-41-5', 5, 'Uttara Kanda, Sarga 41, Verse 5', 'कोकिलैर्भृङ्गराजैश्च नानावर्णैश्च पक्षिभिः।
शोभितां शतशश्चित्रैश्चूतवृक्षावतंसकैः॥', 'kokilair bhṛṅgarājaiś ca nānāvarṇaiś ca pakṣibhiḥ
śobhitāṃ śataśaś citraiś cūtavṛkṣāvataṃsakaiḥ', null, 7041005),
('ramayana-7-41-6', 6, 'Uttara Kanda, Sarga 41, Verse 6', 'शातकुम्भनिभाः के चित्के चिदग्निशिखोपमाः।
नीलाञ्जननिभाश्चान्ये भान्ति तत्र स्म पादपाः॥', 'śātakumbhanibhāḥ ke cit ke cid agniśikhopamāḥ
nīlāñjananibhāś cānye bhānti tatra sma pādapāḥ', null, 7041006),
('ramayana-7-41-7', 7, 'Uttara Kanda, Sarga 41, Verse 7', 'दीर्घिका विविधाकाराः पूर्णाः परमवारिणा।
महार्हमणिसोपानस्फटिकान्तरकुट्टिमाः॥', 'dīrghikā vividhākārāḥ pūrṇāḥ paramavāriṇā
mahārhamaṇisopānasphaṭikāntarakuṭṭimāḥ', null, 7041007),
('ramayana-7-41-8', 8, 'Uttara Kanda, Sarga 41, Verse 8', 'फुल्लपद्मोत्पलवनाश्चक्रवाकोपशोभिताः।
प्राकारैर्विविधाकारैः शोभिताश्च शिलातलैः॥', 'phullapadmotpalavanāś cakravākopaśobhitāḥ
prākārair vividhākāraiḥ śobhitāś ca śilātalaiḥ', null, 7041008),
('ramayana-7-41-9', 9, 'Uttara Kanda, Sarga 41, Verse 9', 'तत्र तत्र वनोद्देशे वैदूर्यमणिसंनिभैः।
शाद्वलैः परमोपेताः पुष्पितद्रुमसंयुताः॥', 'tatra tatra vanoddeśe vaidūryamaṇisaṃnibhaiḥ
śādvalaiḥ paramopetāḥ puṣpitadrumasaṃyutāḥ', null, 7041009),
('ramayana-7-41-10', 10, 'Uttara Kanda, Sarga 41, Verse 10', 'नन्दनं हि यथेन्द्रस्य ब्राह्मं चैत्ररथं यथा।
तथारूपं हि रामस्य काननं तन्निवेशितम्॥', 'nandanaṃ hi yathendrasya brāhmaṃ caitrarathaṃ yathā
tathārūpaṃ hi rāmasya kānanaṃ tan niveśitam', null, 7041010),
('ramayana-7-41-11', 11, 'Uttara Kanda, Sarga 41, Verse 11', 'बह्वासनगृहोपेतां लतागृहसमावृताम्।
अशोकवनिकां स्फीतां प्रविश्य रघुनन्दनः॥', 'bahvāsanagṛhopetāṃ latāgṛhasamāvṛtām
aśokavanikāṃ sphītāṃ praviśya raghunandanaḥ', null, 7041011),
('ramayana-7-41-12', 12, 'Uttara Kanda, Sarga 41, Verse 12', 'आसने तु शुभाकारे पुष्पस्तबकभूषिते।
कुथास्तरणसंवीते रामः संनिषसाद ह॥', 'āsane tu śubhākāre puṣpastabakabhūṣite
kuthāstaraṇasaṃvīte rāmaḥ saṃniṣasāda ha', null, 7041012),
('ramayana-7-41-13', 13, 'Uttara Kanda, Sarga 41, Verse 13', 'सीतां संगृह्य बाहुभ्यां मधुमैरेयमुत्तमम्।
पाययामास काकुत्स्थः शचीमिन्द्रो यथामृतम्॥', 'sītāṃ saṃgṛhya bāhubhyāṃ madhumaireyam uttamam
pāyayām āsa kākutsthaḥ śacīm indro yathāmṛtam', null, 7041013),
('ramayana-7-41-14', 14, 'Uttara Kanda, Sarga 41, Verse 14', 'मांसानि च विचित्राणि फलानि विविधानि च।
रामस्याभ्यवहारार्थं किंकरास्तूर्णमाहरन्॥', 'māṃsāni ca vicitrāṇi phalāni vividhāni ca
rāmasyābhyavahārārthaṃ kiṃkarās tūrṇam āharan', null, 7041014),
('ramayana-7-41-15', 15, 'Uttara Kanda, Sarga 41, Verse 15', 'उपनृत्यन्ति राजानं नृत्यगीतविशारदाः।
बालाश्च रूपवत्यश्च स्त्रियः पानवशं गताः॥', 'upanṛtyanti rājānaṃ nṛtyagītaviśāradāḥ
bālāś ca rūpavatyaś ca striyaḥ pānavaśaṃ gatāḥ', null, 7041015),
('ramayana-7-41-16', 16, 'Uttara Kanda, Sarga 41, Verse 16', 'एवं रामो मुदा युक्तः सीतां सुरुचिराननाम्।
रमयामास वैदेहीमहन्यहनि देववत्॥', 'evaṃ rāmo mudā yuktaḥ sītāṃ surucirānanām
ramayām āsa vaidehīm ahany ahani devavat', null, 7041016),
('ramayana-7-41-17', 17, 'Uttara Kanda, Sarga 41, Verse 17', 'तथा तु रममाणस्य तस्यैवं शिशिरः शुभः।
अत्यक्रामन्नरेन्द्रस्य राघवस्य महात्मनः॥', 'tathā tu ramamāṇasya tasyaivaṃ śiśiraḥ śubhaḥ
atyakrāman narendrasya rāghavasya mahātmanaḥ', null, 7041017),
('ramayana-7-41-18', 18, 'Uttara Kanda, Sarga 41, Verse 18', 'पूर्वाह्णे पौरकृत्यानि कृत्वा धर्मेण धर्मवित्।
शेषं दिवसभागार्धमन्तःपुरगतोऽभवत्॥', 'pūrvāhṇe paurakṛtyāni kṛtvā dharmeṇa dharmavit
śeṣaṃ divasabhāgārdham antaḥpuragato ''bhavat', null, 7041018),
('ramayana-7-41-19', 19, 'Uttara Kanda, Sarga 41, Verse 19', 'सीता च देवकार्याणि कृत्वा पौर्वाह्णिकानि तु।
श्वश्रूणामविशेषेण सर्वासां प्राञ्जलिः स्थिता॥', 'sītā ca devakāryāṇi kṛtvā paurvāhṇikāni tu
śvaśrūṇām aviśeṣeṇa sarvāsāṃ prāñjaliḥ sthitā', null, 7041019),
('ramayana-7-41-20', 20, 'Uttara Kanda, Sarga 41, Verse 20', 'ततो राममुपागच्छद्विचित्रबहुभूषणा।
त्रिविष्टपे सहस्राक्षमुपविष्टं यथा शची॥', 'tato rāmam upāgacchad vicitrabahubhūṣaṇā
triviṣṭape sahasrākṣam upaviṣṭaṃ yathā śacī', null, 7041020),
('ramayana-7-41-21', 21, 'Uttara Kanda, Sarga 41, Verse 21', 'दृष्ट्वा तु राघवः पत्नीं कल्याणेन समन्विताम्।
प्रहर्षमतुलं लेभे साधु साध्विति चाब्रवीत्॥', 'dṛṣṭvā tu rāghavaḥ patnīṃ kalyāṇena samanvitām
praharṣam atulaṃ lebhe sādhu sādhv iti cābravīt', null, 7041021),
('ramayana-7-41-22', 22, 'Uttara Kanda, Sarga 41, Verse 22', 'अपत्यलाभो वैदेहि ममायं समुपस्थितः।
किमिच्छसि हि तद्ब्रूहि कः कामः क्रियतां तव॥', 'apatyalābho vaidehi mamāyaṃ samupasthitaḥ
kim icchasi hi tad brūhi kaḥ kāmaḥ kriyatāṃ tava', null, 7041022),
('ramayana-7-41-23', 23, 'Uttara Kanda, Sarga 41, Verse 23', 'प्रहसन्ती तु वैदेही रामं वाक्यमथाब्रवीत्।
तपोवनानि पुण्यानि द्रष्टुमिच्छामि राघव॥', 'prahasantī tu vaidehī rāmaṃ vākyam athābravīt
tapovanāni puṇyāni draṣṭum icchāmi rāghava', null, 7041023),
('ramayana-7-41-24', 24, 'Uttara Kanda, Sarga 41, Verse 24', 'गङ्गातीरे निविष्टानि ऋषीणां पुण्यकर्मणाम्।
फलमूलाशिनां वीर पादमूलेषु वर्तितुम्॥', 'gaṅgātīre niviṣṭāni ṛṣīṇāṃ puṇyakarmaṇām
phalamūlāśināṃ vīra pādamūleṣu vartitum', null, 7041024),
('ramayana-7-41-25', 25, 'Uttara Kanda, Sarga 41, Verse 25', 'एष मे परमः कामो यन्मूलफलभोजिषु।
अप्येकरात्रं काकुत्स्थ वसेयं पुण्यशालिषु॥', 'eṣa me paramaḥ kāmo yan mūlaphalabhojiṣu
apy ekarātraṃ kākutstha vaseyaṃ puṇyaśāliṣu', null, 7041025),
('ramayana-7-41-26', 26, 'Uttara Kanda, Sarga 41, Verse 26', 'तथेति च प्रतिज्ञातं रामेणाक्लिष्टकर्मणा।
विस्रब्धा भव वैदेहि श्वो गमिष्यस्यसंशयम्॥', 'tatheti ca pratijñātaṃ rāmeṇākliṣṭakarmaṇā
visrabdhā bhava vaidehi śvo gamiṣyasy asaṃśayam', null, 7041026),
('ramayana-7-41-27', 27, 'Uttara Kanda, Sarga 41, Verse 27', 'एवमुक्त्वा तु काकुत्स्थो मैथिलीं जनकात्मजाम्।
मध्यकक्षान्तरं रामो निर्जगाम सुहृद्वृतः॥', 'evam uktvā tu kākutstho maithilīṃ janakātmajām
madhyakakṣāntaraṃ rāmo nirjagāma suhṛdvṛtaḥ', null, 7041027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 42 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-42-1', 1, 'Uttara Kanda, Sarga 42, Verse 1', 'तत्रोपविष्टं राजानमुपासन्ते विचक्षणाः।
कथानां बहुरूपाणां हास्यकाराः समन्ततः॥', 'tatropaviṣṭaṃ rājānam upāsante vicakṣaṇāḥ
kathānāṃ bahurūpāṇāṃ hāsyakārāḥ samantataḥ', null, 7042001),
('ramayana-7-42-2', 2, 'Uttara Kanda, Sarga 42, Verse 2', 'विजयो मधुमत्तश्च काश्यपः पिङ्गलः कुशः।
सुराजिः कालियो भद्रो दन्तवक्रः समागधः॥', 'vijayo madhumattaś ca kāśyapaḥ piṅgalaḥ kuśaḥ
surājiḥ kāliyo bhadro dantavakraḥ samāgadhaḥ', null, 7042002),
('ramayana-7-42-3', 3, 'Uttara Kanda, Sarga 42, Verse 3', 'एते कथा बहुविधा परिहाससमन्विताः।
कथयन्ति स्म संहृष्टा राघवस्य महात्मनः॥', 'ete kathā bahuvidhā parihāsasamanvitāḥ
kathayanti sma saṃhṛṣṭā rāghavasya mahātmanaḥ', null, 7042003),
('ramayana-7-42-4', 4, 'Uttara Kanda, Sarga 42, Verse 4', 'ततः कथायां कस्यां चिद्राघवः समभाषत।
काः कथा नगरे भद्र वर्तन्ते विषयेषु च॥', 'tataḥ kathāyāṃ kasyāṃ cid rāghavaḥ samabhāṣata
kāḥ kathā nagare bhadra vartante viṣayeṣu ca', null, 7042004),
('ramayana-7-42-5', 5, 'Uttara Kanda, Sarga 42, Verse 5', 'मामाश्रितानि कान्याहुः पौरजानपदा जनाः।
किं च सीतां समाश्रित्य भरतं किं नु लक्ष्मणम्॥', 'mām āśritāni kāny āhuḥ paurajānapadā janāḥ
kiṃ ca sītāṃ samāśritya bharataṃ kiṃ nu lakṣmaṇam', null, 7042005),
('ramayana-7-42-6', 6, 'Uttara Kanda, Sarga 42, Verse 6', 'किं नु शत्रुघ्नमाश्रित्य कैकेयीं मातरं च मे।
वक्तव्यतां च राजानो नवे राज्ये व्रजन्ति हि॥', 'kiṃ nu śatrughnam āśritya kaikeyīṃ mātaraṃ ca me
vaktavyatāṃ ca rājāno nave rājye vrajanti hi', null, 7042006),
('ramayana-7-42-7', 7, 'Uttara Kanda, Sarga 42, Verse 7', 'एवमुक्ते तु रामेण भद्रः प्राञ्जलिरब्रवीत्।
स्थिताः कथाः शुभा राजन्वर्तन्ते पुरवासिनाम्॥', 'evam ukte tu rāmeṇa bhadraḥ prāñjalir abravīt
sthitāḥ kathāḥ śubhā rājan vartante puravāsinām', null, 7042007),
('ramayana-7-42-8', 8, 'Uttara Kanda, Sarga 42, Verse 8', 'अयं तु विजयः सौम्य दशग्रीववधाश्रितः।
भूयिष्ठं स्वपुरे पौरैः कथ्यते पुरुषर्षभ॥', 'ayaṃ tu vijayaḥ saumya daśagrīvavadhāśritaḥ
bhūyiṣṭhaṃ svapure pauraiḥ kathyate puruṣarṣabha', null, 7042008),
('ramayana-7-42-9', 9, 'Uttara Kanda, Sarga 42, Verse 9', 'एवमुक्तस्तु भद्रेण राघवो वाक्यमब्रवीत्।
कथयस्व यथातथ्यं सर्वं निरवशेषतः॥', 'evam uktas tu bhadreṇa rāghavo vākyam abravīt
kathayasva yathātathyaṃ sarvaṃ niravaśeṣataḥ', null, 7042009),
('ramayana-7-42-10', 10, 'Uttara Kanda, Sarga 42, Verse 10', 'शुभाशुभानि वाक्यानि यान्याहुः पुरवासिनः।
श्रुत्वेदानीं शुभं कुर्यां न कुर्यामशुभानि च॥', 'śubhāśubhāni vākyāni yāny āhuḥ puravāsinaḥ
śrutvedānīṃ śubhaṃ kuryāṃ na kuryām aśubhāni ca', null, 7042010),
('ramayana-7-42-11', 11, 'Uttara Kanda, Sarga 42, Verse 11', 'कथयस्व च विस्रब्धो निर्भयो विगतज्वरः।
कथयन्ते यथा पौरा जना जनपदेषु च॥', 'kathayasva ca visrabdho nirbhayo vigatajvaraḥ
kathayante yathā paurā janā janapadeṣu ca', null, 7042011),
('ramayana-7-42-12', 12, 'Uttara Kanda, Sarga 42, Verse 12', 'राघवेणैवमुक्तस्तु भद्रः सुरुचिरं वचः।
प्रत्युवाच महाबाहुं प्राञ्जलिः सुसमाहितः॥', 'rāghaveṇaivam uktas tu bhadraḥ suruciraṃ vacaḥ
pratyuvāca mahābāhuṃ prāñjaliḥ susamāhitaḥ', null, 7042012),
('ramayana-7-42-13', 13, 'Uttara Kanda, Sarga 42, Verse 13', 'शृणु राजन्यथा पौराः कथयन्ति शुभाशुभम्।
चत्वरापणरथ्यासु वनेषूपवनेषु च॥', 'śṛṇu rājan yathā paurāḥ kathayanti śubhāśubham
catvarāpaṇarathyāsu vaneṣūpavaneṣu ca', null, 7042013),
('ramayana-7-42-14', 14, 'Uttara Kanda, Sarga 42, Verse 14', 'दुष्करं कृतवान्रामः समुद्रे सेतुबन्धनम्।
अकृतं पूर्वकैः कैश्चिद्देवैरपि सदानवैः॥', 'duṣkaraṃ kṛtavān rāmaḥ samudre setubandhanam
akṛtaṃ pūrvakaiḥ kaiś cid devair api sadānavaiḥ', null, 7042014),
('ramayana-7-42-15', 15, 'Uttara Kanda, Sarga 42, Verse 15', 'रावणश्च दुराधर्षो हतः सबलवाहनः।
वानराश्च वशं नीता ऋक्षाश्च सह राक्षसैः॥', 'rāvaṇaś ca durādharṣo hataḥ sabalavāhanaḥ
vānarāś ca vaśaṃ nītā ṛkṣāś ca saha rākṣasaiḥ', null, 7042015),
('ramayana-7-42-16', 16, 'Uttara Kanda, Sarga 42, Verse 16', 'हत्वा च रावणं युद्धे सीतामाहृत्य राघवः।
अमर्षं पृष्ठतः कृत्वा स्ववेश्म पुनरानयत्॥', 'hatvā ca rāvaṇaṃ yuddhe sītām āhṛtya rāghavaḥ
amarṣaṃ pṛṣṭhataḥ kṛtvā svaveśma punar ānayat', null, 7042016),
('ramayana-7-42-17', 17, 'Uttara Kanda, Sarga 42, Verse 17', 'कीदृशं हृदये तस्य सीतासंभोगजं सुखम्।
अङ्कमारोप्य हि पुरा रावणेन बलाद्धृताम्॥', 'kīdṛśaṃ hṛdaye tasya sītāsaṃbhogajaṃ sukham
aṅkam āropya hi purā rāvaṇena balād dhṛtām', null, 7042017),
('ramayana-7-42-18', 18, 'Uttara Kanda, Sarga 42, Verse 18', 'लङ्कामपि पुनर्नीतामशोकवनिकां गताम्।
रक्षसां वशमापन्नां कथं रामो न कुत्सते॥', 'laṅkām api punar nītām aśokavanikāṃ gatām
rakṣasāṃ vaśam āpannāṃ kathaṃ rāmo na kutsate', null, 7042018),
('ramayana-7-42-19', 19, 'Uttara Kanda, Sarga 42, Verse 19', 'अस्माकमपि दारेषु सहनीयं भविष्यति।
यथा हि कुरुते राजा प्रजा तमनुवर्तते॥', 'asmākam api dāreṣu sahanīyaṃ bhaviṣyati
yathā hi kurute rājā prajā tam anuvartate', null, 7042019),
('ramayana-7-42-20', 20, 'Uttara Kanda, Sarga 42, Verse 20', 'एवं बहुविधा वाचो वदन्ति पुरवासिनः।
नगरेषु च सर्वेषु राजञ्जनपदेषु च॥', 'evaṃ bahuvidhā vāco vadanti puravāsinaḥ
nagareṣu ca sarveṣu rājañ janapadeṣu ca', null, 7042020),
('ramayana-7-42-21', 21, 'Uttara Kanda, Sarga 42, Verse 21', 'तस्यैतद्भाषितं श्रुत्वा राघवः परमार्तवत्।
उवाच सर्वान्सुहृदः कथमेतन्निवेद्यताम्॥', 'tasyaitad bhāṣitaṃ śrutvā rāghavaḥ paramārtavat
uvāca sarvān suhṛdaḥ katham etan nivedyatām', null, 7042021),
('ramayana-7-42-22', 22, 'Uttara Kanda, Sarga 42, Verse 22', 'सर्वे तु शिरसा भूमावभिवाद्य प्रणम्य च।
प्रत्यूचू राघवं दीनमेवमेतन्न संशयः॥', 'sarve tu śirasā bhūmāv abhivādya praṇamya ca
pratyūcū rāghavaṃ dīnam evam etan na saṃśayaḥ', null, 7042022),
('ramayana-7-42-23', 23, 'Uttara Kanda, Sarga 42, Verse 23', 'श्रुत्वा तु वाक्यं काकुत्स्थः सर्वेषां समुदीरितम्।
विसर्जयामास तदा सर्वांस्ताञ्शत्रुतापनः॥', 'śrutvā tu vākyaṃ kākutsthaḥ sarveṣāṃ samudīritam
visarjayām āsa tadā sarvāṃs tāñ śatrutāpanaḥ', null, 7042023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 43 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-43-1', 1, 'Uttara Kanda, Sarga 43, Verse 1', 'विसृज्य तु सुहृद्वर्गं बुद्ध्या निश्चित्य राघवः।
समीपे द्वाःस्थमासीनमिदं वचनमब्रवीत्॥', 'visṛjya tu suhṛdvargaṃ buddhyā niścitya rāghavaḥ
samīpe dvāḥstham āsīnam idaṃ vacanam abravīt', null, 7043001),
('ramayana-7-43-2', 2, 'Uttara Kanda, Sarga 43, Verse 2', 'शीघ्रमानय सौमित्रिं लक्ष्मणं शुभलक्षणम्।
भरतं च महाबाहुं शत्रुघ्नं चापराजितम्॥', 'śīghram ānaya saumitriṃ lakṣmaṇaṃ śubhalakṣaṇam
bharataṃ ca mahābāhuṃ śatrughnaṃ cāparājitam', null, 7043002),
('ramayana-7-43-3', 3, 'Uttara Kanda, Sarga 43, Verse 3', 'रामस्य भाषितं श्रुत्वा द्वाःस्थो मूर्ध्नि कृताञ्जलिः।
लक्ष्मणस्य गृहं गत्वा प्रविवेशानिवारितः॥', 'rāmasya bhāṣitaṃ śrutvā dvāḥstho mūrdhni kṛtāñjaliḥ
lakṣmaṇasya gṛhaṃ gatvā praviveśānivāritaḥ', null, 7043003),
('ramayana-7-43-4', 4, 'Uttara Kanda, Sarga 43, Verse 4', 'उवाच च तदा वाक्यं वर्धयित्वा कृताञ्जलिः।
द्रष्टुमिच्छति राजा त्वां गम्यतां तत्र मा चिरम्॥', 'uvāca ca tadā vākyaṃ vardhayitvā kṛtāñjaliḥ
draṣṭum icchati rājā tvāṃ gamyatāṃ tatra mā ciram', null, 7043004),
('ramayana-7-43-5', 5, 'Uttara Kanda, Sarga 43, Verse 5', 'बाढमित्येव सौमित्रिः श्रुत्वा राघवशासनम्।
प्राद्रवद्रथमारुह्य राघवस्य निवेशनम्॥', 'bāḍham ity eva saumitriḥ śrutvā rāghavaśāsanam
prādravad ratham āruhya rāghavasya niveśanam', null, 7043005),
('ramayana-7-43-6', 6, 'Uttara Kanda, Sarga 43, Verse 6', 'प्रयान्तं लक्ष्मणं दृष्ट्वा द्वाःस्थो भरतमन्तिकात्।
उवाच प्राञ्जलिर्वाक्यं राजा त्वां द्रष्टुमिच्छति॥', 'prayāntaṃ lakṣmaṇaṃ dṛṣṭvā dvāḥstho bharatam antikāt
uvāca prāñjalir vākyaṃ rājā tvāṃ draṣṭum icchati', null, 7043006),
('ramayana-7-43-7', 7, 'Uttara Kanda, Sarga 43, Verse 7', 'भरतस्तु वचः श्रुत्वा द्वाःस्थाद्रामसमीरितम्।
उत्पपातासनात्तूर्णं पद्भ्यामेव ततोऽगमत्॥', 'bharatas tu vacaḥ śrutvā dvāḥsthād rāmasamīritam
utpapātāsanāt tūrṇaṃ padbhyām eva tato ''gamat', null, 7043007),
('ramayana-7-43-8', 8, 'Uttara Kanda, Sarga 43, Verse 8', 'दृष्ट्वा प्रयान्तं भरतं त्वरमाणः कृताञ्जलिः।
शत्रुघ्नभवनं गत्वा ततो वाक्यं जगाद ह॥', 'dṛṣṭvā prayāntaṃ bharataṃ tvaramāṇaḥ kṛtāñjaliḥ
śatrughnabhavanaṃ gatvā tato vākyaṃ jagāda ha', null, 7043008),
('ramayana-7-43-9', 9, 'Uttara Kanda, Sarga 43, Verse 9', 'एह्यागच्छ रघुश्रेष्ठ राजा त्वां द्रष्टुमिच्छति।
गतो हि लक्ष्मणः पूर्वं भरतश्च महायशाः॥', 'ehy āgaccha raghuśreṣṭha rājā tvāṃ draṣṭum icchati
gato hi lakṣmaṇaḥ pūrvaṃ bharataś ca mahāyaśāḥ', null, 7043009),
('ramayana-7-43-10', 10, 'Uttara Kanda, Sarga 43, Verse 10', 'श्रुत्वा तु वचनं तस्य शत्रुघ्नो रामशासनम्।
शिरसा वन्द्य धरणीं प्रययौ यत्र राघवः॥', 'śrutvā tu vacanaṃ tasya śatrughno rāmaśāsanam
śirasā vandya dharaṇīṃ prayayau yatra rāghavaḥ', null, 7043010),
('ramayana-7-43-11', 11, 'Uttara Kanda, Sarga 43, Verse 11', 'कुमारानागताञ्श्रुत्वा चिन्ताव्याकुलितेन्द्रियः।
अवाक्शिरा दीनमना द्वाःस्थं वचनमब्रवीत्॥', 'kumārān āgatāñ śrutvā cintāvyākulitendriyaḥ
avākśirā dīnamanā dvāḥsthaṃ vacanam abravīt', null, 7043011),
('ramayana-7-43-12', 12, 'Uttara Kanda, Sarga 43, Verse 12', 'प्रवेशय कुमारांस्त्वं मत्समीपं त्वरान्वितः।
एतेषु जीवितं मह्यमेते प्राणा बहिश्चराः॥', 'praveśaya kumārāṃs tvaṃ matsamīpaṃ tvarānvitaḥ
eteṣu jīvitaṃ mahyam ete prāṇā bahiścarāḥ', null, 7043012),
('ramayana-7-43-13', 13, 'Uttara Kanda, Sarga 43, Verse 13', 'आज्ञप्तास्तु नरेन्द्रेण कुमाराः शुक्लवाससः।
प्रह्वाः प्राञ्जलयो भूत्वा विविशुस्ते समाहिताः॥', 'ājñaptās tu narendreṇa kumārāḥ śuklavāsasaḥ
prahvāḥ prāñjalayo bhūtvā viviśus te samāhitāḥ', null, 7043013),
('ramayana-7-43-14', 14, 'Uttara Kanda, Sarga 43, Verse 14', 'ते तु दृष्ट्वा मुखं तस्य सग्रहं शशिनं यथा।
संध्यागतमिवादित्यं प्रभया परिवर्जितम्॥', 'te tu dṛṣṭvā mukhaṃ tasya sagrahaṃ śaśinaṃ yathā
saṃdhyāgatam ivādityaṃ prabhayā parivarjitam', null, 7043014),
('ramayana-7-43-15', 15, 'Uttara Kanda, Sarga 43, Verse 15', 'बाष्पपूर्णे च नयने दृष्ट्वा रामस्य धीमतः।
हतशोभं यथा पद्मं मुखं वीक्ष्य च तस्य ते॥', 'bāṣpapūrṇe ca nayane dṛṣṭvā rāmasya dhīmataḥ
hataśobhaṃ yathā padmaṃ mukhaṃ vīkṣya ca tasya te', null, 7043015),
('ramayana-7-43-16', 16, 'Uttara Kanda, Sarga 43, Verse 16', 'ततोऽभिवाद्य त्वरिताः पादौ रामस्य मूर्धभिः।
तस्थुः समाहिताः सर्वे रामश्चाश्रूण्यवर्तयत्॥', 'tato ''bhivādya tvaritāḥ pādau rāmasya mūrdhabhiḥ
tasthuḥ samāhitāḥ sarve rāmaś cāśrūṇy avartayat', null, 7043016),
('ramayana-7-43-17', 17, 'Uttara Kanda, Sarga 43, Verse 17', 'तान्परिष्वज्य बाहुभ्यामुत्थाप्य च महाभुजः।
आसनेष्वाध्वमित्युक्त्वा ततो वाक्यं जगाद ह॥', 'tān pariṣvajya bāhubhyām utthāpya ca mahābhujaḥ
āsaneṣv ādhvam ity uktvā tato vākyaṃ jagāda ha', null, 7043017),
('ramayana-7-43-18', 18, 'Uttara Kanda, Sarga 43, Verse 18', 'भवन्तो मम सर्वस्वं भवन्तो मम जीवितम्।
भवद्भिश्च कृतं राज्यं पालयामि नरेश्वराः॥', 'bhavanto mama sarvasvaṃ bhavanto mama jīvitam
bhavadbhiś ca kṛtaṃ rājyaṃ pālayāmi nareśvarāḥ', null, 7043018),
('ramayana-7-43-19', 19, 'Uttara Kanda, Sarga 43, Verse 19', 'भवन्तः कृतशास्त्रार्था बुद्धौ च परिनिष्ठिताः।
संभूय च मदर्थोऽयमन्वेष्टव्यो नरेश्वराः॥', 'bhavantaḥ kṛtaśāstrārthā buddhau ca pariniṣṭhitāḥ
saṃbhūya ca madartho ''yam anveṣṭavyo nareśvarāḥ', null, 7043019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 44 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-44-1', 1, 'Uttara Kanda, Sarga 44, Verse 1', 'तेषां समुपविष्टानां सर्वेषां दीनचेतसाम्।
उवाच वाक्यं काकुत्स्थो मुखेन परिशुष्यता॥', 'teṣāṃ samupaviṣṭānāṃ sarveṣāṃ dīnacetasām
uvāca vākyaṃ kākutstho mukhena pariśuṣyatā', null, 7044001),
('ramayana-7-44-2', 2, 'Uttara Kanda, Sarga 44, Verse 2', 'सर्वे शृणुत भद्रं वो मा कुरुध्वं मनोऽन्यथा।
पौराणां मम सीतायां यादृशी वर्तते कथा॥', 'sarve śṛṇuta bhadraṃ vo mā kurudhvaṃ mano ''nyathā
paurāṇāṃ mama sītāyāṃ yādṛśī vartate kathā', null, 7044002),
('ramayana-7-44-3', 3, 'Uttara Kanda, Sarga 44, Verse 3', 'पौरापवादः सुमहांस्तथा जनपदस्य च।
वर्तते मयि बीभत्सः स मे मर्माणि कृन्तति॥', 'paurāpavādaḥ sumahāṃs tathā janapadasya ca
vartate mayi bībhatsaḥ sa me marmāṇi kṛntati', null, 7044003),
('ramayana-7-44-4', 4, 'Uttara Kanda, Sarga 44, Verse 4', 'अहं किल कुले जात इक्ष्वाकूणां महात्मनाम्।
सीतां पापसमाचारामानयेयं कथं पुरे॥', 'ahaṃ kila kule jāta ikṣvākūṇāṃ mahātmanām
sītāṃ pāpasamācārām ānayeyaṃ kathaṃ pure', null, 7044004),
('ramayana-7-44-5', 5, 'Uttara Kanda, Sarga 44, Verse 5', 'जानासि हि यथा सौम्य दण्डके विजने वने।
रावणेन हृता सीता स च विध्वंसितो मया॥', 'jānāsi hi yathā saumya daṇḍake vijane vane
rāvaṇena hṛtā sītā sa ca vidhvaṃsito mayā', null, 7044005),
('ramayana-7-44-6', 6, 'Uttara Kanda, Sarga 44, Verse 6', 'प्रत्यक्षं तव सौमित्रे देवानां हव्यवाहनः।
अपापां मैथिलीमाह वायुश्चाकाशगोचरः॥', 'pratyakṣaṃ tava saumitre devānāṃ havyavāhanaḥ
apāpāṃ maithilīm āha vāyuś cākāśagocaraḥ', null, 7044006),
('ramayana-7-44-7', 7, 'Uttara Kanda, Sarga 44, Verse 7', 'चन्द्रादित्यौ च शंसेते सुराणां संनिधौ पुरा।
ऋषीणां चैव सर्वेषामपापां जनकात्मजाम्॥', 'candrādityau ca śaṃsete surāṇāṃ saṃnidhau purā
ṛṣīṇāṃ caiva sarveṣām apāpāṃ janakātmajām', null, 7044007),
('ramayana-7-44-8', 8, 'Uttara Kanda, Sarga 44, Verse 8', 'एवं शुद्धसमाचारा देवगन्धर्वसंनिधौ।
लङ्काद्वीपे महेन्द्रेण मम हस्ते निवेशिता॥', 'evaṃ śuddhasamācārā devagandharvasaṃnidhau
laṅkādvīpe mahendreṇa mama haste niveśitā', null, 7044008),
('ramayana-7-44-9', 9, 'Uttara Kanda, Sarga 44, Verse 9', 'अन्तरात्मा च मे वेत्ति सीतां शुद्धां यशस्विनीम्।
ततो गृहीत्वा वैदेहीमयोध्यामहमागतः॥', 'antarātmā ca me vetti sītāṃ śuddhāṃ yaśasvinīm
tato gṛhītvā vaidehīm ayodhyām aham āgataḥ', null, 7044009),
('ramayana-7-44-10', 10, 'Uttara Kanda, Sarga 44, Verse 10', 'अयं तु मे महान्वादः शोकश्च हृदि वर्तते।
पौरापवादः सुमहांस्तथा जनपदस्य च॥', 'ayaṃ tu me mahān vādaḥ śokaś ca hṛdi vartate
paurāpavādaḥ sumahāṃs tathā janapadasya ca', null, 7044010),
('ramayana-7-44-11', 11, 'Uttara Kanda, Sarga 44, Verse 11', 'अकीर्तिर्यस्य गीयेत लोके भूतस्य कस्य चित्।
पतत्येवाधमांल्लोकान्यावच्छब्दः स कीर्त्यते॥', 'akīrtir yasya gīyeta loke bhūtasya kasya cit
pataty evādhamāṃl lokān yāvac chabdaḥ sa kīrtyate', null, 7044011),
('ramayana-7-44-12', 12, 'Uttara Kanda, Sarga 44, Verse 12', 'अकीर्तिर्निन्द्यते दैवैः कीर्तिर्देवेषु पूज्यते।
कीर्त्यर्थं च समारम्भः सर्व एव महात्मनाम्॥', 'akīrtir nindyate daivaiḥ kīrtir deveṣu pūjyate
kīrtyarthaṃ ca samārambhaḥ sarva eva mahātmanām', null, 7044012),
('ramayana-7-44-13', 13, 'Uttara Kanda, Sarga 44, Verse 13', 'अप्यहं जीवितं जह्यां युष्मान्वा पुरुषर्षभाः।
अपवादभयाद्भीतः किं पुनर्जनकात्मजाम्॥', 'apy ahaṃ jīvitaṃ jahyāṃ yuṣmān vā puruṣarṣabhāḥ
apavādabhayād bhītaḥ kiṃ punar janakātmajām', null, 7044013),
('ramayana-7-44-14', 14, 'Uttara Kanda, Sarga 44, Verse 14', 'तस्माद्भवन्तः पश्यन्तु पतितं शोकसागरे।
न हि पश्याम्यहं भूयः किं चिद्दुःखमतोऽधिकम्॥', 'tasmād bhavantaḥ paśyantu patitaṃ śokasāgare
na hi paśyāmy ahaṃ bhūyaḥ kiṃ cid duḥkham ato ''dhikam', null, 7044014),
('ramayana-7-44-15', 15, 'Uttara Kanda, Sarga 44, Verse 15', 'श्वस्त्वं प्रभाते सौमित्रे सुमन्त्राधिष्ठितं रथम्।
आरुह्य सीतामारोप्य विषयान्ते समुत्सृज॥', 'śvas tvaṃ prabhāte saumitre sumantrādhiṣṭhitaṃ ratham
āruhya sītām āropya viṣayānte samutsṛja', null, 7044015),
('ramayana-7-44-16', 16, 'Uttara Kanda, Sarga 44, Verse 16', 'गङ्गायास्तु परे पारे वाल्मीकेः सुमहात्मनः।
आश्रमो दिव्यसंकाशस्तमसातीरमाश्रितः॥', 'gaṅgāyās tu pare pāre vālmīkeḥ sumahātmanaḥ
āśramo divyasaṃkāśas tamasātīram āśritaḥ', null, 7044016),
('ramayana-7-44-17', 17, 'Uttara Kanda, Sarga 44, Verse 17', 'तत्रैनां विजने कक्षे विसृज्य रघुनन्दन।
शीघ्रमागच्छ सौमित्रे कुरुष्व वचनं मम॥', 'tatraināṃ vijane kakṣe visṛjya raghunandana
śīghram āgaccha saumitre kuruṣva vacanaṃ mama', null, 7044017),
('ramayana-7-44-18', 18, 'Uttara Kanda, Sarga 44, Verse 18', 'न चास्मि प्रतिवक्तव्यः सीतां प्रति कथं चन।
अप्रीतिः परमा मह्यं भवेत्तु प्रतिवारिते॥', 'na cāsmi prativaktavyaḥ sītāṃ prati kathaṃ cana
aprītiḥ paramā mahyaṃ bhavet tu prativārite', null, 7044018),
('ramayana-7-44-19', 19, 'Uttara Kanda, Sarga 44, Verse 19', 'शापिताश्च मया यूयं भुजाभ्यां जीवितेन च।
ये मां वाक्यान्तरे ब्रूयुरनुनेतुं कथं चन॥', 'śāpitāś ca mayā yūyaṃ bhujābhyāṃ jīvitena ca
ye māṃ vākyāntare brūyur anunetuṃ kathaṃ cana', null, 7044019),
('ramayana-7-44-20', 20, 'Uttara Kanda, Sarga 44, Verse 20', 'मानयन्तु भवन्तो मां यदि मच्छासने स्थिताः।
इतोऽद्य नीयतां सीता कुरुष्व वचनं मम॥', 'mānayantu bhavanto māṃ yadi macchāsane sthitāḥ
ito ''dya nīyatāṃ sītā kuruṣva vacanaṃ mama', null, 7044020),
('ramayana-7-44-21', 21, 'Uttara Kanda, Sarga 44, Verse 21', 'पूर्वमुक्तोऽहमनया गङ्गातीरे महाश्रमान्।
पश्येयमिति तस्याश्च कामः संवर्त्यतामयम्॥', 'pūrvam ukto ''ham anayā gaṅgātīre mahāśramān
paśyeyam iti tasyāś ca kāmaḥ saṃvartyatām ayam', null, 7044021),
('ramayana-7-44-22', 22, 'Uttara Kanda, Sarga 44, Verse 22', 'एवमुक्त्वा तु काकुत्स्थो बाष्पेण पिहितेक्षणः।
प्रविवेश स धर्मात्मा भ्रातृभिः परिवारितः॥', 'evam uktvā tu kākutstho bāṣpeṇa pihitekṣaṇaḥ
praviveśa sa dharmātmā bhrātṛbhiḥ parivāritaḥ', null, 7044022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 45 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-45-1', 1, 'Uttara Kanda, Sarga 45, Verse 1', 'ततो रजन्यां व्युष्टायां लक्ष्मणो दीनचेतनः।
सुमन्त्रमब्रवीद्वाक्यं मुखेन परिशुष्यता॥', 'tato rajanyāṃ vyuṣṭāyāṃ lakṣmaṇo dīnacetanaḥ
sumantram abravīd vākyaṃ mukhena pariśuṣyatā', null, 7045001),
('ramayana-7-45-2', 2, 'Uttara Kanda, Sarga 45, Verse 2', 'सारथे तुरगाञ्शीघ्रं योजयस्व रथोत्तमे।
स्वास्तीर्णं राजभवनात्सीतायाश्चासनं शुभम्॥', 'sārathe turagāñ śīghraṃ yojayasva rathottame
svāstīrṇaṃ rājabhavanāt sītāyāś cāsanaṃ śubham', null, 7045002),
('ramayana-7-45-3', 3, 'Uttara Kanda, Sarga 45, Verse 3', 'सीता हि राजभवनादाश्रमं पुण्यकर्मणाम्।
मया नेया महर्षीणां शीघ्रमानीयतां रथः॥', 'sītā hi rājabhavanād āśramaṃ puṇyakarmaṇām
mayā neyā maharṣīṇāṃ śīghram ānīyatāṃ rathaḥ', null, 7045003),
('ramayana-7-45-4', 4, 'Uttara Kanda, Sarga 45, Verse 4', 'सुमन्त्रस्तु तथेत्युक्त्वा युक्तं परमवाजिभिः।
रथं सुरुचिरप्रख्यं स्वास्तीर्णं सुखशय्यया॥', 'sumantras tu tathety uktvā yuktaṃ paramavājibhiḥ
rathaṃ suruciraprakhyaṃ svāstīrṇaṃ sukhaśayyayā', null, 7045004),
('ramayana-7-45-5', 5, 'Uttara Kanda, Sarga 45, Verse 5', 'आदायोवाच सौमित्रिं मित्राणां हर्षवर्धनम्।
रथोऽयं समनुप्राप्तो यत्कार्यं क्रियतां प्रभो॥', 'ādāyovāca saumitriṃ mitrāṇāṃ harṣavardhanam
ratho ''yaṃ samanuprāpto yat kāryaṃ kriyatāṃ prabho', null, 7045005),
('ramayana-7-45-6', 6, 'Uttara Kanda, Sarga 45, Verse 6', 'एवमुक्तः सुमन्त्रेण राजवेश्म स लक्ष्मणः।
प्रविश्य सीतामासाद्य व्याजहार नरर्षभः॥', 'evam uktaḥ sumantreṇa rājaveśma sa lakṣmaṇaḥ
praviśya sītām āsādya vyājahāra nararṣabhaḥ', null, 7045006),
('ramayana-7-45-7', 7, 'Uttara Kanda, Sarga 45, Verse 7', 'गङ्गातीरे मया देवि मुनीनामाश्रमे शुभे।
शीघ्रं गत्वोपनेयासि शासनात्पार्थिवस्य नः॥', 'gaṅgātīre mayā devi munīnām āśrame śubhe
śīghraṃ gatvopaneyāsi śāsanāt pārthivasya naḥ', null, 7045007),
('ramayana-7-45-8', 8, 'Uttara Kanda, Sarga 45, Verse 8', 'एवमुक्ता तु वैदेही लक्ष्मणेन महात्मना।
प्रहर्षमतुलं लेभे गमनं चाभ्यरोचयत्॥', 'evam uktā tu vaidehī lakṣmaṇena mahātmanā
praharṣam atulaṃ lebhe gamanaṃ cābhyarocayat', null, 7045008),
('ramayana-7-45-9', 9, 'Uttara Kanda, Sarga 45, Verse 9', 'वासांसि च महार्हाणि रत्नानि विविधानि च।
गृहीत्वा तानि वैदेही गमनायोपचक्रमे॥', 'vāsāṃsi ca mahārhāṇi ratnāni vividhāni ca
gṛhītvā tāni vaidehī gamanāyopacakrame', null, 7045009),
('ramayana-7-45-10', 10, 'Uttara Kanda, Sarga 45, Verse 10', 'इमानि मुनिपत्नीनां दास्याम्याभरणान्यहम्।
सौमित्रिस्तु तथेत्युक्त्वा रथमारोप्य मैथिलीम्।
प्रययौ शीघ्रतुरगो रामस्याज्ञामनुस्मरन्॥', 'imāni munipatnīnāṃ dāsyāmy ābharaṇāny aham
saumitris tu tathety uktvā ratham āropya maithilīm
prayayau śīghraturago rāmasyājñām anusmaran', null, 7045010),
('ramayana-7-45-11', 11, 'Uttara Kanda, Sarga 45, Verse 11', 'अब्रवीच्च तदा सीता लक्ष्मणं लक्ष्मिवर्धनम्।
अशुभानि बहून्यद्य पश्यामि रघुनन्दन॥', 'abravīc ca tadā sītā lakṣmaṇaṃ lakṣmivardhanam
aśubhāni bahūny adya paśyāmi raghunandana', null, 7045011),
('ramayana-7-45-12', 12, 'Uttara Kanda, Sarga 45, Verse 12', 'नयनं मे स्फुरत्यद्य गात्रोत्कम्पश्च जायते।
हृदयं चैव सौमित्रे अस्वस्थमिव लक्षये॥', 'nayanaṃ me sphuraty adya gātrotkampaś ca jāyate
hṛdayaṃ caiva saumitre asvastham iva lakṣaye', null, 7045012),
('ramayana-7-45-13', 13, 'Uttara Kanda, Sarga 45, Verse 13', 'औत्सुक्यं परमं चापि अधृतिश्च परा मम।
शून्यामिव च पश्यामि पृथिवीं पृथुलोचन॥', 'autsukyaṃ paramaṃ cāpi adhṛtiś ca parā mama
śūnyām iva ca paśyāmi pṛthivīṃ pṛthulocana', null, 7045013),
('ramayana-7-45-14', 14, 'Uttara Kanda, Sarga 45, Verse 14', 'अपि स्वस्ति भवेत्तस्य भ्रातुस्ते भ्रातृभिः सह।
श्वश्रूणां चैव मे वीर सर्वासामविशेषतः॥', 'api svasti bhavet tasya bhrātus te bhrātṛbhiḥ saha
śvaśrūṇāṃ caiva me vīra sarvāsām aviśeṣataḥ', null, 7045014),
('ramayana-7-45-15', 15, 'Uttara Kanda, Sarga 45, Verse 15', 'पुरे जनपदे चैव कुशलं प्राणिनामपि।
इत्यञ्जलिकृता सीता देवता अभ्ययाचत॥', 'pure janapade caiva kuśalaṃ prāṇinām api
ity añjalikṛtā sītā devatā abhyayācata', null, 7045015),
('ramayana-7-45-16', 16, 'Uttara Kanda, Sarga 45, Verse 16', 'लक्ष्मणोऽर्थं तु तं श्रुत्वा शिरसा वन्द्य मैथिलीम्।
शिवमित्यब्रवीद्धृष्टो हृदयेन विशुष्यता॥', 'lakṣmaṇo ''rthaṃ tu taṃ śrutvā śirasā vandya maithilīm
śivam ity abravīd dhṛṣṭo hṛdayena viśuṣyatā', null, 7045016),
('ramayana-7-45-17', 17, 'Uttara Kanda, Sarga 45, Verse 17', 'ततो वासमुपागम्य गोमतीतीर आश्रमे।
प्रभाते पुनरुत्थाय सौमित्रिः सूतमब्रवीत्॥', 'tato vāsam upāgamya gomatītīra āśrame
prabhāte punar utthāya saumitriḥ sūtam abravīt', null, 7045017),
('ramayana-7-45-18', 18, 'Uttara Kanda, Sarga 45, Verse 18', 'योजयस्व रथं शीघ्रमद्य भागीरथीजलम्।
शिरसा धारयिष्यामि त्र्यम्बकः पर्वते यथा॥', 'yojayasva rathaṃ śīghram adya bhāgīrathījalam
śirasā dhārayiṣyāmi tryambakaḥ parvate yathā', null, 7045018),
('ramayana-7-45-19', 19, 'Uttara Kanda, Sarga 45, Verse 19', 'सोऽश्वान्विचारयित्वाशु रथे युक्त्वा मनोजवान्।
आरोहस्वेति वैदेहीं सूतः प्राञ्जलिरब्रवीत्॥', 'so ''śvān vicārayitvāśu rathe yuktvā manojavān
ārohasveti vaidehīṃ sūtaḥ prāñjalir abravīt', null, 7045019),
('ramayana-7-45-20', 20, 'Uttara Kanda, Sarga 45, Verse 20', 'सा तु सूतस्य वचनादारुरोह रथोत्तमम्।
सीता सौमित्रिणा सार्धं सुमन्त्रेण च धीमता॥', 'sā tu sūtasya vacanād āruroha rathottamam
sītā saumitriṇā sārdhaṃ sumantreṇa ca dhīmatā', null, 7045020),
('ramayana-7-45-21', 21, 'Uttara Kanda, Sarga 45, Verse 21', 'अथार्धदिवसं गत्वा भागीरथ्या जलाशयम्।
निरीक्ष्य लक्ष्मणो दीनः प्ररुरोद महास्वनम्॥', 'athārdhadivasaṃ gatvā bhāgīrathyā jalāśayam
nirīkṣya lakṣmaṇo dīnaḥ praruroda mahāsvanam', null, 7045021),
('ramayana-7-45-22', 22, 'Uttara Kanda, Sarga 45, Verse 22', 'सीता तु परमायत्ता दृष्ट्वा लक्ष्मणमातुरम्।
उवाच वाक्यं धर्मज्ञ किमिदं रुद्यते त्वया॥', 'sītā tu paramāyattā dṛṣṭvā lakṣmaṇam āturam
uvāca vākyaṃ dharmajña kim idaṃ rudyate tvayā', null, 7045022),
('ramayana-7-45-23', 23, 'Uttara Kanda, Sarga 45, Verse 23', 'जाह्नवीतीरमासाद्य चिराभिलषितं मम।
हर्षकाले किमर्थं मां विषादयसि लक्ष्मण॥', 'jāhnavītīram āsādya cirābhilaṣitaṃ mama
harṣakāle kim arthaṃ māṃ viṣādayasi lakṣmaṇa', null, 7045023),
('ramayana-7-45-24', 24, 'Uttara Kanda, Sarga 45, Verse 24', 'नित्यं त्वं रामपादेषु वर्तसे पुरुषर्षभ।
कच्चिद्विनाकृतस्तेन द्विरात्रे शोकमागतः॥', 'nityaṃ tvaṃ rāmapādeṣu vartase puruṣarṣabha
kaccid vinākṛtas tena dvirātre śokam āgataḥ', null, 7045024),
('ramayana-7-45-25', 25, 'Uttara Kanda, Sarga 45, Verse 25', 'ममापि दयितो रामो जीवितेनापि लक्ष्मण।
न चाहमेवं शोचामि मैवं त्वं बालिशो भव॥', 'mamāpi dayito rāmo jīvitenāpi lakṣmaṇa
na cāham evaṃ śocāmi maivaṃ tvaṃ bāliśo bhava', null, 7045025),
('ramayana-7-45-26', 26, 'Uttara Kanda, Sarga 45, Verse 26', 'तारयस्व च मां गङ्गां दर्शयस्व च तापसान्।
ततो धनानि वासांसि दास्याम्याभरणानि च॥', 'tārayasva ca māṃ gaṅgāṃ darśayasva ca tāpasān
tato dhanāni vāsāṃsi dāsyāmy ābharaṇāni ca', null, 7045026),
('ramayana-7-45-27', 27, 'Uttara Kanda, Sarga 45, Verse 27', 'ततः कृत्वा महर्षीणां यथार्हमभिवादनम्।
तत्र चैकां निशामुष्य यास्यामस्तां पुरीं पुनः॥', 'tataḥ kṛtvā maharṣīṇāṃ yathārham abhivādanam
tatra caikāṃ niśām uṣya yāsyāmas tāṃ purīṃ punaḥ', null, 7045027),
('ramayana-7-45-28', 28, 'Uttara Kanda, Sarga 45, Verse 28', 'तस्यास्तद्वचनं श्रुत्वा प्रमृज्य नयने शुभे।
तितीर्षुर्लक्ष्मणो गङ्गां शुभां नावमुपाहरत्॥', 'tasyās tad vacanaṃ śrutvā pramṛjya nayane śubhe
titīrṣur lakṣmaṇo gaṅgāṃ śubhāṃ nāvam upāharat', null, 7045028)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 46 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-46-1', 1, 'Uttara Kanda, Sarga 46, Verse 1', 'अथ नावं सुविस्तीर्णां नैषादीं राघवानुजः।
आरुरोह समायुक्तां पूर्वमारोप्य मैथिलीम्॥', 'atha nāvaṃ suvistīrṇāṃ naiṣādīṃ rāghavānujaḥ
āruroha samāyuktāṃ pūrvam āropya maithilīm', null, 7046001),
('ramayana-7-46-2', 2, 'Uttara Kanda, Sarga 46, Verse 2', 'सुमन्त्रं चैव सरथं स्थीयतामिति लक्ष्मणः।
उवाच शोकसंतप्तः प्रयाहीति च नाविकम्॥', 'sumantraṃ caiva sarathaṃ sthīyatām iti lakṣmaṇaḥ
uvāca śokasaṃtaptaḥ prayāhīti ca nāvikam', null, 7046002),
('ramayana-7-46-3', 3, 'Uttara Kanda, Sarga 46, Verse 3', 'ततस्तीरमुपागम्य भागीरथ्याः स लक्ष्मणः।
उवाच मैथिलीं वाक्यं प्राञ्जलिर्बाष्पगद्गदः॥', 'tatas tīram upāgamya bhāgīrathyāḥ sa lakṣmaṇaḥ
uvāca maithilīṃ vākyaṃ prāñjalir bāṣpagadgadaḥ', null, 7046003),
('ramayana-7-46-4', 4, 'Uttara Kanda, Sarga 46, Verse 4', 'हृद्गतं मे महच्छल्यं यदस्म्यार्येण धीमता।
अस्मिन्निमित्ते वैदेहि लोकस्य वचनीकृतः॥', 'hṛdgataṃ me mahac chalyaṃ yad asmy āryeṇa dhīmatā
asmin nimitte vaidehi lokasya vacanīkṛtaḥ', null, 7046004),
('ramayana-7-46-5', 5, 'Uttara Kanda, Sarga 46, Verse 5', 'श्रेयो हि मरणं मेऽद्य मृत्योर्वा यत्परं भवेत्।
न चास्मिन्नीदृशे कार्ये नियोज्यो लोकनिन्दिते॥', 'śreyo hi maraṇaṃ me ''dya mṛtyor vā yat paraṃ bhavet
na cāsminn īdṛśe kārye niyojyo lokanindite', null, 7046005),
('ramayana-7-46-6', 6, 'Uttara Kanda, Sarga 46, Verse 6', 'प्रसीद न च मे रोषं कर्तुमर्हसि सुव्रते।
इत्यञ्जलिकृतो भूमौ निपपात स लक्ष्मणः॥', 'prasīda na ca me roṣaṃ kartum arhasi suvrate
ity añjalikṛto bhūmau nipapāta sa lakṣmaṇaḥ', null, 7046006),
('ramayana-7-46-7', 7, 'Uttara Kanda, Sarga 46, Verse 7', 'रुदन्तं प्राञ्जलिं दृष्ट्वा काङ्क्षन्तं मृत्युमात्मनः।
मैथिली भृशसंविग्ना लक्ष्मणं वाक्यमब्रवीत्॥', 'rudantaṃ prāñjaliṃ dṛṣṭvā kāṅkṣantaṃ mṛtyum ātmanaḥ
maithilī bhṛśasaṃvignā lakṣmaṇaṃ vākyam abravīt', null, 7046007),
('ramayana-7-46-8', 8, 'Uttara Kanda, Sarga 46, Verse 8', 'किमिदं नावगच्छामि ब्रूहि तत्त्वेन लक्ष्मण।
पश्यामि त्वां च न स्वस्थमपि क्षेमं महीपतेः॥', 'kim idaṃ nāvagacchāmi brūhi tattvena lakṣmaṇa
paśyāmi tvāṃ ca na svastham api kṣemaṃ mahīpateḥ', null, 7046008),
('ramayana-7-46-9', 9, 'Uttara Kanda, Sarga 46, Verse 9', 'शापितोऽसि नरेन्द्रेण यत्त्वं संतापमात्मनः।
तद्ब्रूयाः संनिधौ मह्यमहमाज्ञापयामि ते॥', 'śāpito ''si narendreṇa yat tvaṃ saṃtāpam ātmanaḥ
tad brūyāḥ saṃnidhau mahyam aham ājñāpayāmi te', null, 7046009),
('ramayana-7-46-10', 10, 'Uttara Kanda, Sarga 46, Verse 10', 'वैदेह्या चोद्यमानस्तु लक्ष्मणो दीनचेतनः।
अवाङ्मुखो बाष्पगलो वाक्यमेतदुवाच ह॥', 'vaidehyā codyamānas tu lakṣmaṇo dīnacetanaḥ
avāṅmukho bāṣpagalo vākyam etad uvāca ha', null, 7046010),
('ramayana-7-46-11', 11, 'Uttara Kanda, Sarga 46, Verse 11', 'श्रुत्वा परिषदो मध्ये अपवादं सुदारुणम्।
पुरे जनपदे चैव त्वत्कृते जनकात्मजे॥', 'śrutvā pariṣado madhye apavādaṃ sudāruṇam
pure janapade caiva tvatkṛte janakātmaje', null, 7046011),
('ramayana-7-46-12', 12, 'Uttara Kanda, Sarga 46, Verse 12', 'न तानि वचनीयानि मया देवि तवाग्रतः।
यानि राज्ञा हृदि न्यस्तान्यमर्षः पृष्ठतः कृतः॥', 'na tāni vacanīyāni mayā devi tavāgrataḥ
yāni rājñā hṛdi nyastāny amarṣaḥ pṛṣṭhataḥ kṛtaḥ', null, 7046012),
('ramayana-7-46-13', 13, 'Uttara Kanda, Sarga 46, Verse 13', 'सा त्वं त्यक्ता नृपतिना निर्दोषा मम संनिधौ।
पौरापवादभीतेन ग्राह्यं देवि न तेऽन्यथा॥', 'sā tvaṃ tyaktā nṛpatinā nirdoṣā mama saṃnidhau
paurāpavādabhītena grāhyaṃ devi na te ''nyathā', null, 7046013),
('ramayana-7-46-14', 14, 'Uttara Kanda, Sarga 46, Verse 14', 'आश्रमान्तेषु च मया त्यक्तव्या त्वं भविष्यसि।
राज्ञः शासनमाज्ञाय तवैवं किल दौर्हृदम्॥', 'āśramānteṣu ca mayā tyaktavyā tvaṃ bhaviṣyasi
rājñaḥ śāsanam ājñāya tavaivaṃ kila daurhṛdam', null, 7046014),
('ramayana-7-46-15', 15, 'Uttara Kanda, Sarga 46, Verse 15', 'तदेतज्जाह्नवीतीरे ब्रह्मर्षीणां तपोवनम्।
पुण्यं च रमणीयं च मा विषादं कृथाः शुभे॥', 'tad etaj jāhnavītīre brahmarṣīṇāṃ tapovanam
puṇyaṃ ca ramaṇīyaṃ ca mā viṣādaṃ kṛthāḥ śubhe', null, 7046015),
('ramayana-7-46-16', 16, 'Uttara Kanda, Sarga 46, Verse 16', 'राज्ञो दशरथस्यैष पितुर्मे मुनिपुंगवः।
सखा परमको विप्रो वाल्मीकिः सुमहायशाः॥', 'rājño daśarathasyaiṣa pitur me munipuṃgavaḥ
sakhā paramako vipro vālmīkiḥ sumahāyaśāḥ', null, 7046016),
('ramayana-7-46-17', 17, 'Uttara Kanda, Sarga 46, Verse 17', 'पादच्छायामुपागम्य सुखमस्य महात्मनः।
उपवासपरैकाग्रा वस त्वं जनकात्मजे॥', 'pādacchāyām upāgamya sukham asya mahātmanaḥ
upavāsaparaikāgrā vasa tvaṃ janakātmaje', null, 7046017),
('ramayana-7-46-18', 18, 'Uttara Kanda, Sarga 46, Verse 18', 'पतिव्रतात्वमास्थाय रामं कृत्वा सदा हृदि।
श्रेयस्ते परमं देवि तथा कृत्वा भविष्यति॥', 'pativratātvam āsthāya rāmaṃ kṛtvā sadā hṛdi
śreyas te paramaṃ devi tathā kṛtvā bhaviṣyati', null, 7046018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 47 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-47-1', 1, 'Uttara Kanda, Sarga 47, Verse 1', 'लक्ष्मणस्य वचः श्रुत्वा दारुणं जनकात्मजा।
परं विषादमागम्य वैदेही निपपात ह॥', 'lakṣmaṇasya vacaḥ śrutvā dāruṇaṃ janakātmajā
paraṃ viṣādam āgamya vaidehī nipapāta ha', null, 7047001),
('ramayana-7-47-2', 2, 'Uttara Kanda, Sarga 47, Verse 2', 'सा मुहूर्तमिवासंज्ञा बाष्पव्याकुलितेक्षणा।
लक्ष्मणं दीनया वाचा उवाच जनकात्मजा॥', 'sā muhūrtam ivāsaṃjñā bāṣpavyākulitekṣaṇā
lakṣmaṇaṃ dīnayā vācā uvāca janakātmajā', null, 7047002),
('ramayana-7-47-3', 3, 'Uttara Kanda, Sarga 47, Verse 3', 'मामिकेयं तनुर्नूनं सृष्टा दुःखाय लक्ष्मण।
धात्रा यस्यास्तथा मेऽद्य दुःखमूर्तिः प्रदृश्यते॥', 'māmikeyaṃ tanur nūnaṃ sṛṣṭā duḥkhāya lakṣmaṇa
dhātrā yasyās tathā me ''dya duḥkhamūrtiḥ pradṛśyate', null, 7047003),
('ramayana-7-47-4', 4, 'Uttara Kanda, Sarga 47, Verse 4', 'किं नु पापं कृतं पूर्वं को वा दारैर्वियोजितः।
याहं शुद्धसमाचारा त्यक्ता नृपतिना सती॥', 'kiṃ nu pāpaṃ kṛtaṃ pūrvaṃ ko vā dārair viyojitaḥ
yāhaṃ śuddhasamācārā tyaktā nṛpatinā satī', null, 7047004),
('ramayana-7-47-5', 5, 'Uttara Kanda, Sarga 47, Verse 5', 'पुराहमाश्रमे वासं रामपादानुवर्तिनी।
अनुरुध्यापि सौमित्रे दुःखे विपरिवर्तिनी॥', 'purāham āśrame vāsaṃ rāmapādānuvartinī
anurudhyāpi saumitre duḥkhe viparivartinī', null, 7047005),
('ramayana-7-47-6', 6, 'Uttara Kanda, Sarga 47, Verse 6', 'सा कथं ह्याश्रमे सौम्य वत्स्यामि विजनीकृता।
आख्यास्यामि च कस्याहं दुःखं दुःखपरायणा॥', 'sā kathaṃ hy āśrame saumya vatsyāmi vijanīkṛtā
ākhyāsyāmi ca kasyāhaṃ duḥkhaṃ duḥkhaparāyaṇā', null, 7047006),
('ramayana-7-47-7', 7, 'Uttara Kanda, Sarga 47, Verse 7', 'किं च वक्ष्यामि मुनिषु किं मयापकृतं नृपे।
कस्मिन्वा कारणे त्यक्ता राघवेण महात्मना॥', 'kiṃ ca vakṣyāmi muniṣu kiṃ mayāpakṛtaṃ nṛpe
kasmin vā kāraṇe tyaktā rāghaveṇa mahātmanā', null, 7047007),
('ramayana-7-47-8', 8, 'Uttara Kanda, Sarga 47, Verse 8', 'न खल्वद्यैव सौमित्रे जीवितं जाह्नवीजले।
त्यजेयं राजवंशस्तु भर्तुर्मे परिहास्यते॥', 'na khalv adyaiva saumitre jīvitaṃ jāhnavījale
tyajeyaṃ rājavaṃśas tu bhartur me parihāsyate', null, 7047008),
('ramayana-7-47-9', 9, 'Uttara Kanda, Sarga 47, Verse 9', 'यथाज्ञां कुरु सौमित्रे त्यज मां दुःखभागिनीम्।
निदेशे स्थीयतां राज्ञः शृणु चेदं वचो मम॥', 'yathājñāṃ kuru saumitre tyaja māṃ duḥkhabhāginīm
nideśe sthīyatāṃ rājñaḥ śṛṇu cedaṃ vaco mama', null, 7047009),
('ramayana-7-47-10', 10, 'Uttara Kanda, Sarga 47, Verse 10', 'श्वश्रूणामविशेषेण प्राञ्जलिः प्रग्रहेण च।
शिरसा वन्द्य चरणौ कुशलं ब्रूहि पार्थिवम्॥', 'śvaśrūṇām aviśeṣeṇa prāñjaliḥ pragraheṇa ca
śirasā vandya caraṇau kuśalaṃ brūhi pārthivam', null, 7047010),
('ramayana-7-47-11', 11, 'Uttara Kanda, Sarga 47, Verse 11', 'यथा भ्रातृषु वर्तेथास्तथा पौरेषु नित्यदा।
परमो ह्येष धर्मः स्यादेषा कीर्तिरनुत्तमा॥', 'yathā bhrātṛṣu vartethās tathā paureṣu nityadā
paramo hy eṣa dharmaḥ syād eṣā kīrtir anuttamā', null, 7047011),
('ramayana-7-47-12', 12, 'Uttara Kanda, Sarga 47, Verse 12', 'यत्त्वं पौरजनं राजन्धर्मेण समवाप्नुयाः।
अहं तु नानुशोचामि स्वशरीरं नरर्षभ।
यथापवादं पौराणां तथैव रघुनन्दन॥', 'yat tvaṃ paurajanaṃ rājan dharmeṇa samavāpnuyāḥ
ahaṃ tu nānuśocāmi svaśarīraṃ nararṣabha
yathāpavādaṃ paurāṇāṃ tathaiva raghunandana', null, 7047012),
('ramayana-7-47-13', 13, 'Uttara Kanda, Sarga 47, Verse 13', 'एवं ब्रुवन्त्यां सीतायां लक्ष्मणो दीनचेतनः।
शिरसा धरणीं गत्वा व्याहर्तुं न शशाक ह॥', 'evaṃ bruvantyāṃ sītāyāṃ lakṣmaṇo dīnacetanaḥ
śirasā dharaṇīṃ gatvā vyāhartuṃ na śaśāka ha', null, 7047013),
('ramayana-7-47-14', 14, 'Uttara Kanda, Sarga 47, Verse 14', 'प्रदक्षिणं च कृत्वा स रुदन्नेव महास्वनम्।
आरुरोह पुनर्नावं नाविकं चाभ्यचोदयत्॥', 'pradakṣiṇaṃ ca kṛtvā sa rudann eva mahāsvanam
āruroha punar nāvaṃ nāvikaṃ cābhyacodayat', null, 7047014),
('ramayana-7-47-15', 15, 'Uttara Kanda, Sarga 47, Verse 15', 'स गत्वा चोत्तरं कूलं शोकभारसमन्वितः।
संमूढ इव दुःखेन रथमध्यारुहद्द्रुतम्॥', 'sa gatvā cottaraṃ kūlaṃ śokabhārasamanvitaḥ
saṃmūḍha iva duḥkhena ratham adhyāruhad drutam', null, 7047015),
('ramayana-7-47-16', 16, 'Uttara Kanda, Sarga 47, Verse 16', 'मुहुर्मुहुरपावृत्य दृष्ट्वा सीतामनाथवत्।
वेष्टन्तीं परतीरस्थां लक्ष्मणः प्रययावथ॥', 'muhur muhur apāvṛtya dṛṣṭvā sītām anāthavat
veṣṭantīṃ paratīrasthāṃ lakṣmaṇaḥ prayayāv atha', null, 7047016),
('ramayana-7-47-17', 17, 'Uttara Kanda, Sarga 47, Verse 17', 'दूरस्थं रथमालोक्य लक्ष्मणं च मुहुर्मुहुः।
निरीक्षमाणामुद्विग्नां सीतां शोकः समाविशत्॥', 'dūrasthaṃ ratham ālokya lakṣmaṇaṃ ca muhur muhuḥ
nirīkṣamāṇām udvignāṃ sītāṃ śokaḥ samāviśat', null, 7047017),
('ramayana-7-47-18', 18, 'Uttara Kanda, Sarga 47, Verse 18', 'सा दुःखभारावनता तपस्विनी यशोधरा नाथमपश्यती सती।
रुरोद सा बर्हिणनादिते वने महास्वनं दुःखपरायणा सती॥', 'sā duḥkhabhārāvanatā tapasvinī yaśodharā nātham apaśyatī satī
ruroda sā barhiṇanādite vane mahāsvanaṃ duḥkhaparāyaṇā satī', null, 7047018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 48 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-48-1', 1, 'Uttara Kanda, Sarga 48, Verse 1', 'सीतां तु रुदतीं दृष्ट्वा ये तत्र मुनिदारकाः।
प्राद्रवन्यत्र भगवानास्ते वाल्मीकिरग्र्यधीः॥', 'sītāṃ tu rudatīṃ dṛṣṭvā ye tatra munidārakāḥ
prādravan yatra bhagavān āste vālmīkir agryadhīḥ', null, 7048001),
('ramayana-7-48-2', 2, 'Uttara Kanda, Sarga 48, Verse 2', 'अभिवाद्य मुनेः पादौ मुनिपुत्रा महर्षये।
सर्वे निवेदयामासुस्तस्यास्तु रुदितस्वनम्॥', 'abhivādya muneḥ pādau muniputrā maharṣaye
sarve nivedayām āsus tasyās tu ruditasvanam', null, 7048002),
('ramayana-7-48-3', 3, 'Uttara Kanda, Sarga 48, Verse 3', 'अदृष्टपूर्वा भगवन्कस्याप्येषा महात्मनः।
पत्नी श्रीरिव संमोहाद्विरौति विकृतस्वरा॥', 'adṛṣṭapūrvā bhagavan kasyāpy eṣā mahātmanaḥ
patnī śrīr iva saṃmohād virauti vikṛtasvarā', null, 7048003),
('ramayana-7-48-4', 4, 'Uttara Kanda, Sarga 48, Verse 4', 'भगवन्साधु पश्येमां देवतामिव खाच्च्युताम्।
न ह्येनां मानुषीं विद्मः सत्क्रियास्याः प्रयुज्यताम्॥', 'bhagavan sādhu paśyemāṃ devatām iva khāc cyutām
na hy enāṃ mānuṣīṃ vidmaḥ satkriyāsyāḥ prayujyatām', null, 7048004),
('ramayana-7-48-5', 5, 'Uttara Kanda, Sarga 48, Verse 5', 'तेषां तद्वचनं श्रुत्वा बुद्ध्या निश्चित्य धर्मवित्।
तपसा लब्धचक्षुष्मान्प्राद्रवद्यत्र मैथिली॥', 'teṣāṃ tad vacanaṃ śrutvā buddhyā niścitya dharmavit
tapasā labdhacakṣuṣmān prādravad yatra maithilī', null, 7048005),
('ramayana-7-48-6', 6, 'Uttara Kanda, Sarga 48, Verse 6', 'तं तु देशमभिप्रेत्य किं चित्पद्भ्यां महामुनिः।
अर्घ्यमादाय रुचिरं जाह्वनीतीरमाश्रितः।
ददर्श राघवस्येष्टां पत्नीं सीतामनाथवत्॥', 'taṃ tu deśam abhipretya kiṃ cit padbhyāṃ mahāmuniḥ
arghyam ādāya ruciraṃ jāhvanītīram āśritaḥ
dadarśa rāghavasyeṣṭāṃ patnīṃ sītām anāthavat', null, 7048006),
('ramayana-7-48-7', 7, 'Uttara Kanda, Sarga 48, Verse 7', 'तां सीतां शोकभारार्तां वाल्मीकिर्मुनिपुंगवः।
उवाच मधुरां वाणीं ह्लादयन्निव तेजसा॥', 'tāṃ sītāṃ śokabhārārtāṃ vālmīkir munipuṃgavaḥ
uvāca madhurāṃ vāṇīṃ hlādayann iva tejasā', null, 7048007),
('ramayana-7-48-8', 8, 'Uttara Kanda, Sarga 48, Verse 8', 'स्नुषा दशरथस्य त्वं रामस्य महिषी सती।
जनकस्य सुता राज्ञः स्वागतं ते पतिव्रते॥', 'snuṣā daśarathasya tvaṃ rāmasya mahiṣī satī
janakasya sutā rājñaḥ svāgataṃ te pativrate', null, 7048008),
('ramayana-7-48-9', 9, 'Uttara Kanda, Sarga 48, Verse 9', 'आयान्त्येवासि विज्ञाता मया धर्मसमाधिना।
कारणं चैव सर्वं मे हृदयेनोपलक्षितम्॥', 'āyānty evāsi vijñātā mayā dharmasamādhinā
kāraṇaṃ caiva sarvaṃ me hṛdayenopalakṣitam', null, 7048009),
('ramayana-7-48-10', 10, 'Uttara Kanda, Sarga 48, Verse 10', 'अपापां वेद्मि सीते त्वां तपोलब्धेन चक्षुषा।
विशुद्धभावा वैदेहि साम्प्रतं मयि वर्तसे॥', 'apāpāṃ vedmi sīte tvāṃ tapolabdhena cakṣuṣā
viśuddhabhāvā vaidehi sāmprataṃ mayi vartase', null, 7048010),
('ramayana-7-48-11', 11, 'Uttara Kanda, Sarga 48, Verse 11', 'आश्रमस्याविदूरे मे तापस्यस्तपसि स्थिताः।
तास्त्वां वत्से यथा वत्सं पालयिष्यन्ति नित्यशः॥', 'āśramasyāvidūre me tāpasyas tapasi sthitāḥ
tās tvāṃ vatse yathā vatsaṃ pālayiṣyanti nityaśaḥ', null, 7048011),
('ramayana-7-48-12', 12, 'Uttara Kanda, Sarga 48, Verse 12', 'इदमर्घ्यं प्रतीच्छ त्वं विस्रब्धा विगतज्वरा।
यथा स्वगृहमभ्येत्य विषादं चैव मा कृथाः॥', 'idam arghyaṃ pratīccha tvaṃ visrabdhā vigatajvarā
yathā svagṛham abhyetya viṣādaṃ caiva mā kṛthāḥ', null, 7048012),
('ramayana-7-48-13', 13, 'Uttara Kanda, Sarga 48, Verse 13', 'श्रुत्वा तु भाषितं सीता मुनेः परममद्भुतम्।
शिरसा वन्द्य चरणौ तथेत्याह कृताञ्जलिः॥', 'śrutvā tu bhāṣitaṃ sītā muneḥ paramam adbhutam
śirasā vandya caraṇau tathety āha kṛtāñjaliḥ', null, 7048013),
('ramayana-7-48-14', 14, 'Uttara Kanda, Sarga 48, Verse 14', 'तं प्रयान्तं मुनिं सीता प्राञ्जलिः पृष्ठतोऽन्वगात्।
अन्वयाद्यत्र तापस्यो धर्मनित्याः समाहिताः॥', 'taṃ prayāntaṃ muniṃ sītā prāñjaliḥ pṛṣṭhato ''nvagāt
anvayād yatra tāpasyo dharmanityāḥ samāhitāḥ', null, 7048014),
('ramayana-7-48-15', 15, 'Uttara Kanda, Sarga 48, Verse 15', 'तं दृष्ट्वा मुनिमायान्तं वैदेह्यानुगतं तदा।
उपाजग्मुर्मुदा युक्ता वचनं चेदमब्रुवन्॥', 'taṃ dṛṣṭvā munim āyāntaṃ vaidehyānugataṃ tadā
upājagmur mudā yuktā vacanaṃ cedam abruvan', null, 7048015),
('ramayana-7-48-16', 16, 'Uttara Kanda, Sarga 48, Verse 16', 'स्वागतं ते मुनिश्रेष्ठ चिरस्यागमनं प्रभो।
अभिवादयामः सर्वास्त्वामुच्यतां किं च कुर्महे॥', 'svāgataṃ te muniśreṣṭha cirasyāgamanaṃ prabho
abhivādayāmaḥ sarvās tvām ucyatāṃ kiṃ ca kurmahe', null, 7048016),
('ramayana-7-48-17', 17, 'Uttara Kanda, Sarga 48, Verse 17', 'तासां तद्वचनं श्रुत्वा वाल्मीकिरिदमब्रवीत्।
सीतेयं समनुप्राप्ता पत्नी रामस्य धीमतः॥', 'tāsāṃ tad vacanaṃ śrutvā vālmīkir idam abravīt
sīteyaṃ samanuprāptā patnī rāmasya dhīmataḥ', null, 7048017),
('ramayana-7-48-18', 18, 'Uttara Kanda, Sarga 48, Verse 18', 'स्नुषा दशरथस्यैषा जनकस्य सुता सती।
अपापा पतिना त्यक्ता परिपाल्या मया सदा॥', 'snuṣā daśarathasyaiṣā janakasya sutā satī
apāpā patinā tyaktā paripālyā mayā sadā', null, 7048018),
('ramayana-7-48-19', 19, 'Uttara Kanda, Sarga 48, Verse 19', 'इमां भवत्यः पश्यन्तु स्नेहेन परमेण ह।
गौरवान्मम वाक्यस्य पूज्या वोऽस्तु विशेषतः॥', 'imāṃ bhavatyaḥ paśyantu snehena parameṇa ha
gauravān mama vākyasya pūjyā vo ''stu viśeṣataḥ', null, 7048019),
('ramayana-7-48-20', 20, 'Uttara Kanda, Sarga 48, Verse 20', 'मुहुर्मुहुश्च वैदेहीं परिसान्त्व्य महायशाः।
स्वमाश्रमं शिष्यवृतः पुनरायान्महातपाः॥', 'muhur muhuś ca vaidehīṃ parisāntvya mahāyaśāḥ
svam āśramaṃ śiṣyavṛtaḥ punar āyān mahātapāḥ', null, 7048020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 49 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-49-1', 1, 'Uttara Kanda, Sarga 49, Verse 1', 'दृष्ट्वा तु मैथिलीं सीतामाश्रमं संप्रवेशिताम्।
संतापमकरोद्घोरं लक्ष्मणो दीनचेतनः॥', 'dṛṣṭvā tu maithilīṃ sītām āśramaṃ saṃpraveśitām
saṃtāpam akarod ghoraṃ lakṣmaṇo dīnacetanaḥ', null, 7049001),
('ramayana-7-49-2', 2, 'Uttara Kanda, Sarga 49, Verse 2', 'अब्रवीच्च महातेजाः सुमन्त्रं मन्त्रसारथिम्।
सीतासंतापजं दुःखं पश्य रामस्य धीमतः॥', 'abravīc ca mahātejāḥ sumantraṃ mantrasārathim
sītāsaṃtāpajaṃ duḥkhaṃ paśya rāmasya dhīmataḥ', null, 7049002),
('ramayana-7-49-3', 3, 'Uttara Kanda, Sarga 49, Verse 3', 'अतो दुःखतरं किं नु राघवस्य भविष्यति।
पत्नीं शुद्धसमाचारां विसृज्य जनकात्मजाम्॥', 'ato duḥkhataraṃ kiṃ nu rāghavasya bhaviṣyati
patnīṃ śuddhasamācārāṃ visṛjya janakātmajām', null, 7049003),
('ramayana-7-49-4', 4, 'Uttara Kanda, Sarga 49, Verse 4', 'व्यक्तं दैवादहं मन्ये राघवस्य विनाभवम्।
वैदेह्या सारथे सार्धं दैवं हि दुरतिक्रमम्॥', 'vyaktaṃ daivād ahaṃ manye rāghavasya vinābhavam
vaidehyā sārathe sārdhaṃ daivaṃ hi duratikramam', null, 7049004),
('ramayana-7-49-5', 5, 'Uttara Kanda, Sarga 49, Verse 5', 'यो हि देवान्सगन्धर्वानसुरान्सह राक्षसैः।
निहन्याद्राघवः क्रुद्धः स दैवमनुवर्तते॥', 'yo hi devān sagandharvān asurān saha rākṣasaiḥ
nihanyād rāghavaḥ kruddhaḥ sa daivam anuvartate', null, 7049005),
('ramayana-7-49-6', 6, 'Uttara Kanda, Sarga 49, Verse 6', 'पुरा मम पितुर्वाक्यैर्दण्डके विजने वने।
उषितो नववर्षाणि पञ्च चैव सुदारुणे॥', 'purā mama pitur vākyair daṇḍake vijane vane
uṣito navavarṣāṇi pañca caiva sudāruṇe', null, 7049006),
('ramayana-7-49-7', 7, 'Uttara Kanda, Sarga 49, Verse 7', 'ततो दुःखतरं भूयः सीताया विप्रवासनम्।
पौराणां वचनं श्रुत्वा नृशंसं प्रतिभाति मे॥', 'tato duḥkhataraṃ bhūyaḥ sītāyā vipravāsanam
paurāṇāṃ vacanaṃ śrutvā nṛśaṃsaṃ pratibhāti me', null, 7049007),
('ramayana-7-49-8', 8, 'Uttara Kanda, Sarga 49, Verse 8', 'को नु धर्माश्रयः सूत कर्मण्यस्मिन्यशोहरे।
मैथिलीं प्रति संप्राप्तः पौरैर्हीनार्थवादिभिः॥', 'ko nu dharmāśrayaḥ sūta karmaṇy asmin yaśohare
maithilīṃ prati saṃprāptaḥ paurair hīnārthavādibhiḥ', null, 7049008),
('ramayana-7-49-9', 9, 'Uttara Kanda, Sarga 49, Verse 9', 'एता बहुविधा वाचः श्रुत्वा लक्ष्मणभाषिताः।
सुमन्त्रः प्राञ्जलिर्भूत्वा वाक्यमेतदुवाच ह॥', 'etā bahuvidhā vācaḥ śrutvā lakṣmaṇabhāṣitāḥ
sumantraḥ prāñjalir bhūtvā vākyam etad uvāca ha', null, 7049009),
('ramayana-7-49-10', 10, 'Uttara Kanda, Sarga 49, Verse 10', 'न संतापस्त्वया कार्यः सौमित्रे मैथिलीं प्रति।
दृष्टमेतत्पुरा विप्रैः पितुस्ते लक्ष्मणाग्रतः॥', 'na saṃtāpas tvayā kāryaḥ saumitre maithilīṃ prati
dṛṣṭam etat purā vipraiḥ pitus te lakṣmaṇāgrataḥ', null, 7049010),
('ramayana-7-49-11', 11, 'Uttara Kanda, Sarga 49, Verse 11', 'भविष्यति दृढं रामो दुःखप्रायोऽल्पसौख्यवान्।
त्वां चैव मैथिलीं चैव शत्रुघ्नभरतौ तथा।
संत्यजिष्यति धर्मात्मा कालेन महता महान्॥', 'bhaviṣyati dṛḍhaṃ rāmo duḥkhaprāyo ''lpasaukhyavān
tvāṃ caiva maithilīṃ caiva śatrughnabharatau tathā
saṃtyajiṣyati dharmātmā kālena mahatā mahān', null, 7049011),
('ramayana-7-49-12', 12, 'Uttara Kanda, Sarga 49, Verse 12', 'न त्विदं त्वयि वक्तव्यं सौमित्रे भरतेऽपि वा।
राज्ञा वोऽव्याहृतं वाक्यं दुर्वासा यदुवाच ह॥', 'na tv idaṃ tvayi vaktavyaṃ saumitre bharate ''pi vā
rājñā vo ''vyāhṛtaṃ vākyaṃ durvāsā yad uvāca ha', null, 7049012),
('ramayana-7-49-13', 13, 'Uttara Kanda, Sarga 49, Verse 13', 'महाराजसमीपे च मम चैव नरर्षभ।
ऋषिणा व्याहृतं वाक्यं वसिष्ठस्य च संनिधौ॥', 'mahārājasamīpe ca mama caiva nararṣabha
ṛṣiṇā vyāhṛtaṃ vākyaṃ vasiṣṭhasya ca saṃnidhau', null, 7049013),
('ramayana-7-49-14', 14, 'Uttara Kanda, Sarga 49, Verse 14', 'ऋषेस्तु वचनं श्रुत्वा मामाह पुरुषर्षभः।
सूत न क्व चिदेवं ते वक्तव्यं जनसंनिधौ॥', 'ṛṣes tu vacanaṃ śrutvā mām āha puruṣarṣabhaḥ
sūta na kva cid evaṃ te vaktavyaṃ janasaṃnidhau', null, 7049014),
('ramayana-7-49-15', 15, 'Uttara Kanda, Sarga 49, Verse 15', 'तस्याहं लोकपालस्य वाक्यं तत्सुसमाहितः।
नैव जात्वनृतं कुर्यामिति मे सौम्य दर्शनम्॥', 'tasyāhaṃ lokapālasya vākyaṃ tat susamāhitaḥ
naiva jātv anṛtaṃ kuryām iti me saumya darśanam', null, 7049015),
('ramayana-7-49-16', 16, 'Uttara Kanda, Sarga 49, Verse 16', 'सर्वथा नास्त्यवक्तव्यं मया सौम्य तवाग्रतः।
यदि ते श्रवणे श्रद्धा श्रूयतां रघुनन्दन॥', 'sarvathā nāsty avaktavyaṃ mayā saumya tavāgrataḥ
yadi te śravaṇe śraddhā śrūyatāṃ raghunandana', null, 7049016),
('ramayana-7-49-17', 17, 'Uttara Kanda, Sarga 49, Verse 17', 'यद्यप्यहं नरेन्द्रेण रहस्यं श्रावितः पुरा।
तच्चाप्युदाहरिष्यामि दैवं हि दुरतिक्रमम्॥', 'yady apy ahaṃ narendreṇa rahasyaṃ śrāvitaḥ purā
tac cāpy udāhariṣyāmi daivaṃ hi duratikramam', null, 7049017),
('ramayana-7-49-18', 18, 'Uttara Kanda, Sarga 49, Verse 18', 'तच्छ्रुत्वा भाषितं तस्य गम्भीरार्थपदं महत्।
तथ्यं ब्रूहीति सौमित्रिः सूतं वाक्यमथाब्रवीत्॥', 'tac chrutvā bhāṣitaṃ tasya gambhīrārthapadaṃ mahat
tathyaṃ brūhīti saumitriḥ sūtaṃ vākyam athābravīt', null, 7049018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 50 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-50-1', 1, 'Uttara Kanda, Sarga 50, Verse 1', 'तथा संचोदितः सूतो लक्ष्मणेन महात्मना।
तद्वाक्यमृषिणा प्रोक्तं व्याहर्तुमुपचक्रमे॥', 'tathā saṃcoditaḥ sūto lakṣmaṇena mahātmanā
tad vākyam ṛṣiṇā proktaṃ vyāhartum upacakrame', null, 7050001),
('ramayana-7-50-2', 2, 'Uttara Kanda, Sarga 50, Verse 2', 'पुरा नाम्ना हि दुर्वासा अत्रेः पुत्रो महामुनिः।
वसिष्ठस्याश्रमे पुण्ये स वार्षिक्यमुवास ह॥', 'purā nāmnā hi durvāsā atreḥ putro mahāmuniḥ
vasiṣṭhasyāśrame puṇye sa vārṣikyam uvāsa ha', null, 7050002),
('ramayana-7-50-3', 3, 'Uttara Kanda, Sarga 50, Verse 3', 'तमाश्रमं महातेजाः पिता ते सुमहायशाः।
पुरोधसं महात्मानं दिदृक्षुरगमत्स्वयम्॥', 'tam āśramaṃ mahātejāḥ pitā te sumahāyaśāḥ
purodhasaṃ mahātmānaṃ didṛkṣur agamat svayam', null, 7050003),
('ramayana-7-50-4', 4, 'Uttara Kanda, Sarga 50, Verse 4', 'स दृष्ट्वा सूर्यसंकाशं ज्वलन्तमिव तेजसा।
उपविष्टं वसिष्ठस्य सव्ये पार्श्वे महामुनिम्।
तौ मुनी तापसश्रेष्ठौ विनीतस्त्वभ्यवादयत्॥', 'sa dṛṣṭvā sūryasaṃkāśaṃ jvalantam iva tejasā
upaviṣṭaṃ vasiṣṭhasya savye pārśve mahāmunim
tau munī tāpasaśreṣṭhau vinītas tv abhyavādayat', null, 7050004),
('ramayana-7-50-5', 5, 'Uttara Kanda, Sarga 50, Verse 5', 'स ताभ्यां पूजितो राजा स्वागतेनासनेन च।
पाद्येन फलमूलैश्च सोऽप्यास्ते मुनिभिः सह॥', 'sa tābhyāṃ pūjito rājā svāgatenāsanena ca
pādyena phalamūlaiś ca so ''py āste munibhiḥ saha', null, 7050005),
('ramayana-7-50-6', 6, 'Uttara Kanda, Sarga 50, Verse 6', 'तेषां तत्रोपविष्टानां तास्ताः सुमधुराः कथाः।
बभूवुः परमर्षीणां मध्यादित्यगतेऽहनि॥', 'teṣāṃ tatropaviṣṭānāṃ tās tāḥ sumadhurāḥ kathāḥ
babhūvuḥ paramarṣīṇāṃ madhyādityagate ''hani', null, 7050006),
('ramayana-7-50-7', 7, 'Uttara Kanda, Sarga 50, Verse 7', 'ततः कथायां कस्यां चित्प्राञ्जलिः प्रग्रहो नृपः।
उवाच तं महात्मानमत्रेः पुत्रं तपोधनम्॥', 'tataḥ kathāyāṃ kasyāṃ cit prāñjaliḥ pragraho nṛpaḥ
uvāca taṃ mahātmānam atreḥ putraṃ tapodhanam', null, 7050007),
('ramayana-7-50-8', 8, 'Uttara Kanda, Sarga 50, Verse 8', 'भगवन्किंप्रमाणेन मम वंशो भविष्यति।
किमायुश्च हि मे रामः पुत्राश्चान्ये किमायुषः॥', 'bhagavan kiṃpramāṇena mama vaṃśo bhaviṣyati
kimāyuś ca hi me rāmaḥ putrāś cānye kimāyuṣaḥ', null, 7050008),
('ramayana-7-50-9', 9, 'Uttara Kanda, Sarga 50, Verse 9', 'रामस्य च सुता ये स्युस्तेषामायुः कियद्भवेत्।
काम्यया भगवन्ब्रूहि वंशस्यास्य गतिं मम॥', 'rāmasya ca sutā ye syus teṣām āyuḥ kiyad bhavet
kāmyayā bhagavan brūhi vaṃśasyāsya gatiṃ mama', null, 7050009),
('ramayana-7-50-10', 10, 'Uttara Kanda, Sarga 50, Verse 10', 'तच्छ्रुत्वा व्याहृतं वाक्यं राज्ञो दशरथस्य तु।
दुर्वासाः सुमहातेजा व्याहर्तुमुपचक्रमे॥', 'tac chrutvā vyāhṛtaṃ vākyaṃ rājño daśarathasya tu
durvāsāḥ sumahātejā vyāhartum upacakrame', null, 7050010),
('ramayana-7-50-11', 11, 'Uttara Kanda, Sarga 50, Verse 11', 'अयोध्यायाः पती रामो दीर्घकालं भविष्यति।
सुखिनश्च समृद्धाश्च भविष्यन्त्यस्य चानुजाः॥', 'ayodhyāyāḥ patī rāmo dīrghakālaṃ bhaviṣyati
sukhinaś ca samṛddhāś ca bhaviṣyanty asya cānujāḥ', null, 7050011),
('ramayana-7-50-12', 12, 'Uttara Kanda, Sarga 50, Verse 12', 'कस्मिंश्चित्करणे त्वां च मैथिलीं च यशस्विनीम्।
संत्यजिष्यति धर्मात्मा कालेन महता किल॥', 'kasmiṃś cit karaṇe tvāṃ ca maithilīṃ ca yaśasvinīm
saṃtyajiṣyati dharmātmā kālena mahatā kila', null, 7050012),
('ramayana-7-50-13', 13, 'Uttara Kanda, Sarga 50, Verse 13', 'दशवर्षसहस्रणि दशवर्षशतानि च।
रामो राज्यमुपासित्वा ब्रह्मलोकं गमिष्यति॥', 'daśavarṣasahasraṇi daśavarṣaśatāni ca
rāmo rājyam upāsitvā brahmalokaṃ gamiṣyati', null, 7050013),
('ramayana-7-50-14', 14, 'Uttara Kanda, Sarga 50, Verse 14', 'समृद्धैर्हयमेधैश्च इष्ट्वा परपुरंजयः।
राजवंशांश्च काकुत्स्थो बहून्संस्थापयिष्यति॥', 'samṛddhair hayamedhaiś ca iṣṭvā parapuraṃjayaḥ
rājavaṃśāṃś ca kākutstho bahūn saṃsthāpayiṣyati', null, 7050014),
('ramayana-7-50-15', 15, 'Uttara Kanda, Sarga 50, Verse 15', 'स सर्वमखिलं राज्ञो वंशस्यास्य गतागतम्।
आख्याय सुमहातेजास्तूष्णीमासीन्महाद्युतिः॥', 'sa sarvam akhilaṃ rājño vaṃśasyāsya gatāgatam
ākhyāya sumahātejās tūṣṇīm āsīn mahādyutiḥ', null, 7050015),
('ramayana-7-50-16', 16, 'Uttara Kanda, Sarga 50, Verse 16', 'तूष्णींभूते मुनौ तस्मिन्राजा दशरथस्तदा।
अभिवाद्य महात्मानौ पुनरायात्पुरोत्तमम्॥', 'tūṣṇīṃbhūte munau tasmin rājā daśarathas tadā
abhivādya mahātmānau punar āyāt purottamam', null, 7050016),
('ramayana-7-50-17', 17, 'Uttara Kanda, Sarga 50, Verse 17', 'एतद्वचो मया तत्र मुनिना व्याहृतं पुरा।
श्रुतं हृदि च निक्षिप्तं नान्यथा तद्भविष्यति॥', 'etad vaco mayā tatra muninā vyāhṛtaṃ purā
śrutaṃ hṛdi ca nikṣiptaṃ nānyathā tad bhaviṣyati', null, 7050017),
('ramayana-7-50-18', 18, 'Uttara Kanda, Sarga 50, Verse 18', 'एवं गते न संतापं गन्तुमर्हसि राघव।
सीतार्थे राघवार्थे वा दृढो भव नरोत्तम॥', 'evaṃ gate na saṃtāpaṃ gantum arhasi rāghava
sītārthe rāghavārthe vā dṛḍho bhava narottama', null, 7050018),
('ramayana-7-50-19', 19, 'Uttara Kanda, Sarga 50, Verse 19', 'तच्छ्रुत्वा व्याहृतं वाक्यं सूतस्य परमाद्भुतम्।
प्रहर्षमतुलं लेभे साधु साध्विति चाब्रवीत्॥', 'tac chrutvā vyāhṛtaṃ vākyaṃ sūtasya paramādbhutam
praharṣam atulaṃ lebhe sādhu sādhv iti cābravīt', null, 7050019),
('ramayana-7-50-20', 20, 'Uttara Kanda, Sarga 50, Verse 20', 'तयोः संवदतोरेवं सूतलक्ष्मणयोः पथि।
अस्तमर्को गतो वासं गोमत्यां तावथोषतुः॥', 'tayoḥ saṃvadator evaṃ sūtalakṣmaṇayoḥ pathi
astam arko gato vāsaṃ gomatyāṃ tāv athoṣatuḥ', null, 7050020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 51 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-51-1', 1, 'Uttara Kanda, Sarga 51, Verse 1', 'तत्र तां रजनीमुष्य गोमत्यां रघुनन्दनः।
प्रभाते पुनरुत्थाय लक्ष्मणः प्रययौ तदा॥', 'tatra tāṃ rajanīm uṣya gomatyāṃ raghunandanaḥ
prabhāte punar utthāya lakṣmaṇaḥ prayayau tadā', null, 7051001),
('ramayana-7-51-2', 2, 'Uttara Kanda, Sarga 51, Verse 2', 'ततोऽर्धदिवसे प्राप्ते प्रविवेश महारथः।
अयोध्यां रत्नसंपूर्णां हृष्टपुष्टजनावृताम्॥', 'tato ''rdhadivase prāpte praviveśa mahārathaḥ
ayodhyāṃ ratnasaṃpūrṇāṃ hṛṣṭapuṣṭajanāvṛtām', null, 7051002),
('ramayana-7-51-3', 3, 'Uttara Kanda, Sarga 51, Verse 3', 'सौमित्रिस्तु परं दैन्यं जगाम सुमहामतिः।
रामपादौ समासाद्य वक्ष्यामि किमहं गतः॥', 'saumitris tu paraṃ dainyaṃ jagāma sumahāmatiḥ
rāmapādau samāsādya vakṣyāmi kim ahaṃ gataḥ', null, 7051003),
('ramayana-7-51-4', 4, 'Uttara Kanda, Sarga 51, Verse 4', 'तस्यैवं चिन्तयानस्य भवनं शशिसंनिभम्।
रामस्य परमोदारं पुरस्तात्समदृश्यत॥', 'tasyaivaṃ cintayānasya bhavanaṃ śaśisaṃnibham
rāmasya paramodāraṃ purastāt samadṛśyata', null, 7051004),
('ramayana-7-51-5', 5, 'Uttara Kanda, Sarga 51, Verse 5', 'राज्ञस्तु भवनद्वारि सोऽवतीर्य नरोत्तमः।
अवाङ्मुखो दीनमनाः प्राविवेशानिवारितः॥', 'rājñas tu bhavanadvāri so ''vatīrya narottamaḥ
avāṅmukho dīnamanāḥ prāviveśānivāritaḥ', null, 7051005),
('ramayana-7-51-6', 6, 'Uttara Kanda, Sarga 51, Verse 6', 'स दृष्ट्वा राघवं दीनमासीनं परमासने।
नेत्राभ्यामश्रुपूर्णाभ्यां ददर्शाग्रजमग्रतः॥', 'sa dṛṣṭvā rāghavaṃ dīnam āsīnaṃ paramāsane
netrābhyām aśrupūrṇābhyāṃ dadarśāgrajam agrataḥ', null, 7051006),
('ramayana-7-51-7', 7, 'Uttara Kanda, Sarga 51, Verse 7', 'जग्राह चरणौ तस्य लक्ष्मणो दीनचेतनः।
उवाच दीनया वाचा प्राञ्जलिः सुसमाहितः॥', 'jagrāha caraṇau tasya lakṣmaṇo dīnacetanaḥ
uvāca dīnayā vācā prāñjaliḥ susamāhitaḥ', null, 7051007),
('ramayana-7-51-8', 8, 'Uttara Kanda, Sarga 51, Verse 8', 'आर्यस्याज्ञां पुरस्कृत्य विसृज्य जनकात्मजाम्।
गङ्गातीरे यथोद्दिष्टे वाल्मीकेराश्रमे शुभे।
पुनरस्म्यागतो वीर पादमूलमुपासितुम्॥', 'āryasyājñāṃ puraskṛtya visṛjya janakātmajām
gaṅgātīre yathoddiṣṭe vālmīker āśrame śubhe
punar asmy āgato vīra pādamūlam upāsitum', null, 7051008),
('ramayana-7-51-9', 9, 'Uttara Kanda, Sarga 51, Verse 9', 'मा शुचः पुरुषव्याघ्र कालस्य गतिरीदृशी।
त्वद्विधा न हि शोचन्ति सत्त्ववन्तो मनस्विनः॥', 'mā śucaḥ puruṣavyāghra kālasya gatir īdṛśī
tvadvidhā na hi śocanti sattvavanto manasvinaḥ', null, 7051009),
('ramayana-7-51-10', 10, 'Uttara Kanda, Sarga 51, Verse 10', 'सर्वे क्षयान्ता निचयाः पतनान्ताः समुच्छ्रयाः।
संयोगा विप्रयोगान्ता मरणान्तं च जीवितम्॥', 'sarve kṣayāntā nicayāḥ patanāntāḥ samucchrayāḥ
saṃyogā viprayogāntā maraṇāntaṃ ca jīvitam', null, 7051010),
('ramayana-7-51-11', 11, 'Uttara Kanda, Sarga 51, Verse 11', 'शक्तस्त्वमात्मनात्मानं विजेतुं मनसैव हि।
लोकान्सर्वांश्च काकुत्स्थ किं पुनर्दुःखमीदृशम्॥', 'śaktas tvam ātmanātmānaṃ vijetuṃ manasaiva hi
lokān sarvāṃś ca kākutstha kiṃ punar duḥkham īdṛśam', null, 7051011),
('ramayana-7-51-12', 12, 'Uttara Kanda, Sarga 51, Verse 12', 'नेदृशेषु विमुह्यन्ति त्वद्विधाः पुरुषर्षभाः।
यदर्थं मैथिली त्यक्ता अपवादभयान्नृप॥', 'nedṛśeṣu vimuhyanti tvadvidhāḥ puruṣarṣabhāḥ
yadarthaṃ maithilī tyaktā apavādabhayān nṛpa', null, 7051012),
('ramayana-7-51-13', 13, 'Uttara Kanda, Sarga 51, Verse 13', 'स त्वं पुरुषशार्दूल धैर्येण सुसमाहितः।
त्यजेमां दुर्बलां बुद्धिं संतापं मा कुरुष्व ह॥', 'sa tvaṃ puruṣaśārdūla dhairyeṇa susamāhitaḥ
tyajemāṃ durbalāṃ buddhiṃ saṃtāpaṃ mā kuruṣva ha', null, 7051013),
('ramayana-7-51-14', 14, 'Uttara Kanda, Sarga 51, Verse 14', 'एवमुक्तस्तु काकुत्स्थो लक्ष्मणेन महात्मना।
उवाच परया प्रीत्या सौमित्रिं मित्रवत्सलम्॥', 'evam uktas tu kākutstho lakṣmaṇena mahātmanā
uvāca parayā prītyā saumitriṃ mitravatsalam', null, 7051014),
('ramayana-7-51-15', 15, 'Uttara Kanda, Sarga 51, Verse 15', 'एवमेतन्नरश्रेष्ठ यथा वदसि लक्ष्मण।
परितोषश्च मे वीर मम कार्यानुशासने॥', 'evam etan naraśreṣṭha yathā vadasi lakṣmaṇa
paritoṣaś ca me vīra mama kāryānuśāsane', null, 7051015),
('ramayana-7-51-16', 16, 'Uttara Kanda, Sarga 51, Verse 16', 'निर्वृतिश्च कृता सौम्य संतापश्च निराकृतः।
भवद्वाक्यैः सुमधुरैरनुनीतोऽस्मि लक्ष्मण॥', 'nirvṛtiś ca kṛtā saumya saṃtāpaś ca nirākṛtaḥ
bhavadvākyaiḥ sumadhurair anunīto ''smi lakṣmaṇa', null, 7051016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 52 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-52-1', 1, 'Uttara Kanda, Sarga 52, Verse 1', 'ततः सुमन्त्रस्त्वागम्य राघवं वाक्यमब्रवीत्।
एते निवारिता राजन्द्वारि तिष्ठन्ति तापसाः॥', 'tataḥ sumantras tv āgamya rāghavaṃ vākyam abravīt
ete nivāritā rājan dvāri tiṣṭhanti tāpasāḥ', null, 7052001),
('ramayana-7-52-2', 2, 'Uttara Kanda, Sarga 52, Verse 2', 'भार्गवं च्यवनं नाम पुरस्कृत्य महर्षयः।
दर्शनं ते महाराज चोदयन्ति कृतत्वराः।
प्रीयमाणा नरव्याघ्र यमुनातीरवासिनः॥', 'bhārgavaṃ cyavanaṃ nāma puraskṛtya maharṣayaḥ
darśanaṃ te mahārāja codayanti kṛtatvarāḥ
prīyamāṇā naravyāghra yamunātīravāsinaḥ', null, 7052002),
('ramayana-7-52-3', 3, 'Uttara Kanda, Sarga 52, Verse 3', 'तस्य तद्वचनं श्रुत्वा रामः प्रोवाच धर्मवित्।
प्रवेश्यन्तां महात्मानो भार्गवप्रमुखा द्विजाः॥', 'tasya tad vacanaṃ śrutvā rāmaḥ provāca dharmavit
praveśyantāṃ mahātmāno bhārgavapramukhā dvijāḥ', null, 7052003),
('ramayana-7-52-4', 4, 'Uttara Kanda, Sarga 52, Verse 4', 'राज्ञस्त्वाज्ञां पुरस्कृत्य द्वाःस्थो मूर्ध्नि कृताञ्जलिः।
प्रवेशयामास ततस्तापसान्संमतान्बहून्॥', 'rājñas tv ājñāṃ puraskṛtya dvāḥstho mūrdhni kṛtāñjaliḥ
praveśayām āsa tatas tāpasān saṃmatān bahūn', null, 7052004),
('ramayana-7-52-5', 5, 'Uttara Kanda, Sarga 52, Verse 5', 'शतं समधिकं तत्र दीप्यमानं स्वतेजसा।
प्रविष्टं राजभवनं तापसानां महात्मनाम्॥', 'śataṃ samadhikaṃ tatra dīpyamānaṃ svatejasā
praviṣṭaṃ rājabhavanaṃ tāpasānāṃ mahātmanām', null, 7052005),
('ramayana-7-52-6', 6, 'Uttara Kanda, Sarga 52, Verse 6', 'ते द्विजाः पूर्णकलशैः सर्वतीर्थाम्बु सत्कृतम्।
गृहीत्वा फलमूलं च रामस्याभ्याहरन्बहु॥', 'te dvijāḥ pūrṇakalaśaiḥ sarvatīrthāmbu satkṛtam
gṛhītvā phalamūlaṃ ca rāmasyābhyāharan bahu', null, 7052006),
('ramayana-7-52-7', 7, 'Uttara Kanda, Sarga 52, Verse 7', 'प्रतिगृह्य तु तत्सर्वं रामः प्रीतिपुरस्कृतः।
तीर्थोदकानि सर्वाणि फलानि विविधानि च॥', 'pratigṛhya tu tat sarvaṃ rāmaḥ prītipuraskṛtaḥ
tīrthodakāni sarvāṇi phalāni vividhāni ca', null, 7052007),
('ramayana-7-52-8', 8, 'Uttara Kanda, Sarga 52, Verse 8', 'उवाच च महाबाहुः सर्वानेव महामुनीन्।
इमान्यासनमुख्यानि यथार्हमुपविश्यताम्॥', 'uvāca ca mahābāhuḥ sarvān eva mahāmunīn
imāny āsanamukhyāni yathārham upaviśyatām', null, 7052008),
('ramayana-7-52-9', 9, 'Uttara Kanda, Sarga 52, Verse 9', 'रामस्य भाषितं श्रुत्वा सर्व एव महर्षयः।
बृसीषु रुचिराख्यासु निषेदुः काञ्चनीषु ते॥', 'rāmasya bhāṣitaṃ śrutvā sarva eva maharṣayaḥ
bṛsīṣu rucirākhyāsu niṣeduḥ kāñcanīṣu te', null, 7052009),
('ramayana-7-52-10', 10, 'Uttara Kanda, Sarga 52, Verse 10', 'उपविष्टानृषींस्तत्र दृष्ट्वा परपुरंजयः।
प्रयतः प्राञ्जलिर्भूत्वा राघवो वाक्यमब्रवीत्॥', 'upaviṣṭān ṛṣīṃs tatra dṛṣṭvā parapuraṃjayaḥ
prayataḥ prāñjalir bhūtvā rāghavo vākyam abravīt', null, 7052010),
('ramayana-7-52-11', 11, 'Uttara Kanda, Sarga 52, Verse 11', 'किमागमनकार्यं वः किं करोमि तपोधनाः।
आज्ञाप्योऽहं महर्षीणां सर्वकामकरः सुखम्॥', 'kim āgamanakāryaṃ vaḥ kiṃ karomi tapodhanāḥ
ājñāpyo ''haṃ maharṣīṇāṃ sarvakāmakaraḥ sukham', null, 7052011),
('ramayana-7-52-12', 12, 'Uttara Kanda, Sarga 52, Verse 12', 'इदं राज्यं च सकलं जीवितं च हृदि स्थितम्।
सर्वमेतद्द्विजार्थं मे सत्यमेतद्ब्रवीमि वः॥', 'idaṃ rājyaṃ ca sakalaṃ jīvitaṃ ca hṛdi sthitam
sarvam etad dvijārthaṃ me satyam etad bravīmi vaḥ', null, 7052012),
('ramayana-7-52-13', 13, 'Uttara Kanda, Sarga 52, Verse 13', 'तस्य तद्वचनं श्रुत्वा साधुवादो महानभूत्।
ऋषीणामुग्रतपसां यमुनातीरवासिनाम्॥', 'tasya tad vacanaṃ śrutvā sādhuvādo mahān abhūt
ṛṣīṇām ugratapasāṃ yamunātīravāsinām', null, 7052013),
('ramayana-7-52-14', 14, 'Uttara Kanda, Sarga 52, Verse 14', 'ऊचुश्च ते महात्मानो हर्षेण महतान्विताः।
उपपन्नं नरश्रेष्ठ तवैव भुवि नान्यतः॥', 'ūcuś ca te mahātmāno harṣeṇa mahatānvitāḥ
upapannaṃ naraśreṣṭha tavaiva bhuvi nānyataḥ', null, 7052014),
('ramayana-7-52-15', 15, 'Uttara Kanda, Sarga 52, Verse 15', 'बहवः पार्थिवा राजन्नतिक्रान्ता महाबलाः।
कार्यगौरवमश्रुत्वा प्रतिज्ञां नाभ्यरोचयन्॥', 'bahavaḥ pārthivā rājann atikrāntā mahābalāḥ
kāryagauravam aśrutvā pratijñāṃ nābhyarocayan', null, 7052015),
('ramayana-7-52-16', 16, 'Uttara Kanda, Sarga 52, Verse 16', 'त्वया पुनर्ब्राह्मणगौरवादियं कृता प्रतिज्ञा ह्यनवेक्ष्य कारणम्।
कुरुष्व कर्ता ह्यसि नात्र संशयो महाभयात्त्रातुमृषींस्त्वमर्हसि॥', 'tvayā punar brāhmaṇagauravād iyaṃ kṛtā pratijñā hy anavekṣya kāraṇam
kuruṣva kartā hy asi nātra saṃśayo mahābhayāt trātum ṛṣīṃs tvam arhasi', null, 7052016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 53 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-53-1', 1, 'Uttara Kanda, Sarga 53, Verse 1', 'ब्रुवद्भिरेवमृषिभिः काकुत्स्थो वाक्यमब्रवीत्।
किं कार्यं ब्रूत भवतां भयं नाशयितास्मि वः॥', 'bruvadbhir evam ṛṣibhiḥ kākutstho vākyam abravīt
kiṃ kāryaṃ brūta bhavatāṃ bhayaṃ nāśayitāsmi vaḥ', null, 7053001),
('ramayana-7-53-2', 2, 'Uttara Kanda, Sarga 53, Verse 2', 'तथा वदति काकुत्स्थे भार्गवो वाक्यमब्रवीत्।
भयं नः शृणु यन्मूलं देशस्य च नरेश्वर॥', 'tathā vadati kākutsthe bhārgavo vākyam abravīt
bhayaṃ naḥ śṛṇu yan mūlaṃ deśasya ca nareśvara', null, 7053002),
('ramayana-7-53-3', 3, 'Uttara Kanda, Sarga 53, Verse 3', 'पूर्वं कृतयुगे राम दैतेयः सुमहाबलः।
लोलापुत्रोऽभवज्ज्येष्ठो मधुर्नाम महासुरः॥', 'pūrvaṃ kṛtayuge rāma daiteyaḥ sumahābalaḥ
lolāputro ''bhavaj jyeṣṭho madhur nāma mahāsuraḥ', null, 7053003),
('ramayana-7-53-4', 4, 'Uttara Kanda, Sarga 53, Verse 4', 'ब्रह्मण्यश्च शरण्यश्च बुद्ध्या च परिनिष्ठितः।
सुरैश्च परमोदारैः प्रीतिस्तस्यातुलाभवत्॥', 'brahmaṇyaś ca śaraṇyaś ca buddhyā ca pariniṣṭhitaḥ
suraiś ca paramodāraiḥ prītis tasyātulābhavat', null, 7053004),
('ramayana-7-53-5', 5, 'Uttara Kanda, Sarga 53, Verse 5', 'स मधुर्वीर्यसंपन्नो धर्मे च सुसमाहितः।
बहुमानाच्च रुद्रेण दत्तस्तस्याद्भुतो वरः॥', 'sa madhur vīryasaṃpanno dharme ca susamāhitaḥ
bahumānāc ca rudreṇa dattas tasyādbhuto varaḥ', null, 7053005),
('ramayana-7-53-6', 6, 'Uttara Kanda, Sarga 53, Verse 6', 'शूलं शूलाद्विनिष्कृष्य महावीर्यं महाप्रभम्।
ददौ महात्मा सुप्रीतो वाक्यं चैतदुवाच ह॥', 'śūlaṃ śūlād viniṣkṛṣya mahāvīryaṃ mahāprabham
dadau mahātmā suprīto vākyaṃ caitad uvāca ha', null, 7053006),
('ramayana-7-53-7', 7, 'Uttara Kanda, Sarga 53, Verse 7', 'त्वयायमतुलो धर्मो मत्प्रसादात्कृतः शुभः।
प्रीत्या परमया युक्तो ददाम्यायुधमुत्तमम्॥', 'tvayāyam atulo dharmo matprasādāt kṛtaḥ śubhaḥ
prītyā paramayā yukto dadāmy āyudham uttamam', null, 7053007),
('ramayana-7-53-8', 8, 'Uttara Kanda, Sarga 53, Verse 8', 'यावत्सुरैश्च विप्रैश्च न विरुध्येर्महासुर।
तावच्छूलं तवेदं स्यादन्यथा नाशमाप्नुयात्॥', 'yāvat suraiś ca vipraiś ca na virudhyer mahāsura
tāvac chūlaṃ tavedaṃ syād anyathā nāśam āpnuyāt', null, 7053008),
('ramayana-7-53-9', 9, 'Uttara Kanda, Sarga 53, Verse 9', 'यश्च त्वामभियुञ्जीत युद्धाय विगतज्वरः।
तं शूलं भस्मसात्कृत्वा पुनरेष्यति ते करम्॥', 'yaś ca tvām abhiyuñjīta yuddhāya vigatajvaraḥ
taṃ śūlaṃ bhasmasāt kṛtvā punar eṣyati te karam', null, 7053009),
('ramayana-7-53-10', 10, 'Uttara Kanda, Sarga 53, Verse 10', 'एवं रुद्राद्वरं लब्ध्वा भूय एव महासुरः।
प्रणिपत्य महादेवं वाक्यमेतदुवाच ह॥', 'evaṃ rudrād varaṃ labdhvā bhūya eva mahāsuraḥ
praṇipatya mahādevaṃ vākyam etad uvāca ha', null, 7053010),
('ramayana-7-53-11', 11, 'Uttara Kanda, Sarga 53, Verse 11', 'भगवन्मम वंशस्य शूलमेतदनुत्तमम्।
भवेत्तु सततं देव सुराणामीश्वरो ह्यसि॥', 'bhagavan mama vaṃśasya śūlam etad anuttamam
bhavet tu satataṃ deva surāṇām īśvaro hy asi', null, 7053011),
('ramayana-7-53-12', 12, 'Uttara Kanda, Sarga 53, Verse 12', 'तं ब्रुवाणं मधुं देवः सर्वभूतपतिः शिवः।
प्रत्युवाच महादेवो नैतदेवं भविष्यति॥', 'taṃ bruvāṇaṃ madhuṃ devaḥ sarvabhūtapatiḥ śivaḥ
pratyuvāca mahādevo naitad evaṃ bhaviṣyati', null, 7053012),
('ramayana-7-53-13', 13, 'Uttara Kanda, Sarga 53, Verse 13', 'मा भूत्ते विफला वाणी मत्प्रसादकृता शुभा।
भवतः पुत्रमेकं तु शूलमेतद्गमिष्यति॥', 'mā bhūt te viphalā vāṇī matprasādakṛtā śubhā
bhavataḥ putram ekaṃ tu śūlam etad gamiṣyati', null, 7053013),
('ramayana-7-53-14', 14, 'Uttara Kanda, Sarga 53, Verse 14', 'यावत्करस्थः शूलोऽयं भविष्यति सुतस्य ते।
अवध्यः सर्वभूतानां शूलहस्तो भविष्यति॥', 'yāvat karasthaḥ śūlo ''yaṃ bhaviṣyati sutasya te
avadhyaḥ sarvabhūtānāṃ śūlahasto bhaviṣyati', null, 7053014),
('ramayana-7-53-15', 15, 'Uttara Kanda, Sarga 53, Verse 15', 'एवं मधुर्वरं लब्ध्वा देवात्सुमहदद्भुतम्।
भवनं चासुरश्रेष्ठः कारयामास सुप्रभम्॥', 'evaṃ madhur varaṃ labdhvā devāt sumahad adbhutam
bhavanaṃ cāsuraśreṣṭhaḥ kārayām āsa suprabham', null, 7053015),
('ramayana-7-53-16', 16, 'Uttara Kanda, Sarga 53, Verse 16', 'तस्य पत्नी महाभागा प्रिया कुम्भीनसी हि या।
विश्वावसोरपत्यं सा ह्यनलायां महाप्रभा॥', 'tasya patnī mahābhāgā priyā kumbhīnasī hi yā
viśvāvasor apatyaṃ sā hy analāyāṃ mahāprabhā', null, 7053016),
('ramayana-7-53-17', 17, 'Uttara Kanda, Sarga 53, Verse 17', 'तस्याः पुत्रो महावीर्यो लवणो नाम दारुणः।
बाल्यात्प्रभृति दुष्टात्मा पापान्येव समाचरत्॥', 'tasyāḥ putro mahāvīryo lavaṇo nāma dāruṇaḥ
bālyāt prabhṛti duṣṭātmā pāpāny eva samācarat', null, 7053017),
('ramayana-7-53-18', 18, 'Uttara Kanda, Sarga 53, Verse 18', 'तं पुत्रं दुर्विनीतं तु दृष्ट्वा दुःखसमन्वितः।
मधुः स शोकमापेदे न चैनं किं चिदब्रवीत्॥', 'taṃ putraṃ durvinītaṃ tu dṛṣṭvā duḥkhasamanvitaḥ
madhuḥ sa śokam āpede na cainaṃ kiṃ cid abravīt', null, 7053018),
('ramayana-7-53-19', 19, 'Uttara Kanda, Sarga 53, Verse 19', 'स विहाय इमं लोकं प्रविष्टो वरुणालयम्।
शूलं निवेश्य लवणे वरं तस्मै न्यवेदयत्॥', 'sa vihāya imaṃ lokaṃ praviṣṭo varuṇālayam
śūlaṃ niveśya lavaṇe varaṃ tasmai nyavedayat', null, 7053019),
('ramayana-7-53-20', 20, 'Uttara Kanda, Sarga 53, Verse 20', 'स प्रभावेन शूलस्य दौरात्म्येनात्मनस्तथा।
संतापयति लोकांस्त्रीन्विशेषेण तु तापसान्॥', 'sa prabhāvena śūlasya daurātmyenātmanas tathā
saṃtāpayati lokāṃs trīn viśeṣeṇa tu tāpasān', null, 7053020),
('ramayana-7-53-21', 21, 'Uttara Kanda, Sarga 53, Verse 21', 'एवंप्रभावो लवणः शूलं चैव तथाविधम्।
श्रुत्वा प्रमाणं काकुत्स्थ त्वं हि नः परमा गतिः॥', 'evaṃprabhāvo lavaṇaḥ śūlaṃ caiva tathāvidham
śrutvā pramāṇaṃ kākutstha tvaṃ hi naḥ paramā gatiḥ', null, 7053021),
('ramayana-7-53-22', 22, 'Uttara Kanda, Sarga 53, Verse 22', 'बहवः पार्थिवा राम भयार्तैरृषिभिः पुरा।
अभयं याचिता वीर त्रातारं न च विद्महे॥', 'bahavaḥ pārthivā rāma bhayārtair ṛṣibhiḥ purā
abhayaṃ yācitā vīra trātāraṃ na ca vidmahe', null, 7053022),
('ramayana-7-53-23', 23, 'Uttara Kanda, Sarga 53, Verse 23', 'ते वयं रावणं श्रुत्वा हतं सबलवाहनम्।
त्रातारं विद्महे राम नान्यं भुवि नराधिपम्।
तत्परित्रातुमिच्छामो लवणाद्भयपीडिताः॥', 'te vayaṃ rāvaṇaṃ śrutvā hataṃ sabalavāhanam
trātāraṃ vidmahe rāma nānyaṃ bhuvi narādhipam
tat paritrātum icchāmo lavaṇād bhayapīḍitāḥ', null, 7053023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 54 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-54-1', 1, 'Uttara Kanda, Sarga 54, Verse 1', 'तथोक्ते तानृषीन्रामः प्रत्युवाच कृताञ्जलिः।
किमाहारः किमाचारो लवणः क्व च वर्तते॥', 'tathokte tān ṛṣīn rāmaḥ pratyuvāca kṛtāñjaliḥ
kimāhāraḥ kimācāro lavaṇaḥ kva ca vartate', null, 7054001),
('ramayana-7-54-2', 2, 'Uttara Kanda, Sarga 54, Verse 2', 'राघवस्य वचः श्रुत्वा ऋषयः सर्व एव ते।
ततो निवेदयामासुर्लवणो ववृधे यथा॥', 'rāghavasya vacaḥ śrutvā ṛṣayaḥ sarva eva te
tato nivedayām āsur lavaṇo vavṛdhe yathā', null, 7054002),
('ramayana-7-54-3', 3, 'Uttara Kanda, Sarga 54, Verse 3', 'आहारः सर्वसत्त्वानि विशेषेण च तापसाः।
आचारो रौद्रता नित्यं वासो मधुवने सदा॥', 'āhāraḥ sarvasattvāni viśeṣeṇa ca tāpasāḥ
ācāro raudratā nityaṃ vāso madhuvane sadā', null, 7054003),
('ramayana-7-54-4', 4, 'Uttara Kanda, Sarga 54, Verse 4', 'हत्वा दशसहस्राणि सिंहव्याघ्रमृगद्विपान्।
मानुषांश्चैव कुरुते नित्यमाहारमाह्निकम्॥', 'hatvā daśasahasrāṇi siṃhavyāghramṛgadvipān
mānuṣāṃś caiva kurute nityam āhāram āhnikam', null, 7054004),
('ramayana-7-54-5', 5, 'Uttara Kanda, Sarga 54, Verse 5', 'ततोऽपराणि सत्त्वानि खादते स महाबलः।
संहारे समनुप्राप्ते व्यादितास्य इवान्तकः॥', 'tato ''parāṇi sattvāni khādate sa mahābalaḥ
saṃhāre samanuprāpte vyāditāsya ivāntakaḥ', null, 7054005),
('ramayana-7-54-6', 6, 'Uttara Kanda, Sarga 54, Verse 6', 'तच्छ्रुत्वा राघवो वाक्यमुवाच स महामुनीन्।
घातयिष्यामि तद्रक्षो व्यपगच्छतु वो भयम्॥', 'tac chrutvā rāghavo vākyam uvāca sa mahāmunīn
ghātayiṣyāmi tad rakṣo vyapagacchatu vo bhayam', null, 7054006),
('ramayana-7-54-7', 7, 'Uttara Kanda, Sarga 54, Verse 7', 'तथा तेषां प्रतिज्ञाय मुनीनामुग्रतेजसाम्।
स भ्रातॄन्सहितान्सर्वानुवाच रघुनन्दनः॥', 'tathā teṣāṃ pratijñāya munīnām ugratejasām
sa bhrātṝn sahitān sarvān uvāca raghunandanaḥ', null, 7054007),
('ramayana-7-54-8', 8, 'Uttara Kanda, Sarga 54, Verse 8', 'को हन्ता लवणं वीराः कस्यांशः स विधीयताम्।
भरतस्य महाबाहोः शत्रुघ्नस्याथ वा पुनः॥', 'ko hantā lavaṇaṃ vīrāḥ kasyāṃśaḥ sa vidhīyatām
bharatasya mahābāhoḥ śatrughnasyātha vā punaḥ', null, 7054008),
('ramayana-7-54-9', 9, 'Uttara Kanda, Sarga 54, Verse 9', 'राघवेणैवमुक्तस्तु भरतो वाक्यमब्रवीत्।
अहमेनं वधिष्यामि ममांशः स विधीयताम्॥', 'rāghaveṇaivam uktas tu bharato vākyam abravīt
aham enaṃ vadhiṣyāmi mamāṃśaḥ sa vidhīyatām', null, 7054009),
('ramayana-7-54-10', 10, 'Uttara Kanda, Sarga 54, Verse 10', 'भरतस्य वचः श्रुत्वा शौर्यवीर्यसमन्वितम्।
लक्ष्मणावरजस्तस्थौ हित्वा सौवर्णमासनम्॥', 'bharatasya vacaḥ śrutvā śauryavīryasamanvitam
lakṣmaṇāvarajas tasthau hitvā sauvarṇam āsanam', null, 7054010),
('ramayana-7-54-11', 11, 'Uttara Kanda, Sarga 54, Verse 11', 'शत्रुघ्नस्त्वब्रवीद्वाक्यं प्रणिपत्य नराधिपम्।
कृतकर्मा महाबाहुर्मध्यमो रघुनन्दनः॥', 'śatrughnas tv abravīd vākyaṃ praṇipatya narādhipam
kṛtakarmā mahābāhur madhyamo raghunandanaḥ', null, 7054011),
('ramayana-7-54-12', 12, 'Uttara Kanda, Sarga 54, Verse 12', 'आर्येण हि पुरा शून्या अयोध्या रक्षिता पुरी।
संतापं हृदये कृत्वा आर्यस्यागमनं प्रति॥', 'āryeṇa hi purā śūnyā ayodhyā rakṣitā purī
saṃtāpaṃ hṛdaye kṛtvā āryasyāgamanaṃ prati', null, 7054012),
('ramayana-7-54-13', 13, 'Uttara Kanda, Sarga 54, Verse 13', 'दुःखानि च बहूनीह अनुभूतानि पार्थिव।
शयानो दुःखशय्यासु नन्दिग्रामे महात्मना॥', 'duḥkhāni ca bahūnīha anubhūtāni pārthiva
śayāno duḥkhaśayyāsu nandigrāme mahātmanā', null, 7054013),
('ramayana-7-54-14', 14, 'Uttara Kanda, Sarga 54, Verse 14', 'फलमूलाशनो भूत्वा जटाचीरधरस्तथा।
अनुभूयेदृशं दुःखमेष राघवनन्दनः।
प्रेष्ये मयि स्थिते राजन्न भूयः क्लेशमाप्नुयात्॥', 'phalamūlāśano bhūtvā jaṭācīradharas tathā
anubhūyedṛśaṃ duḥkham eṣa rāghavanandanaḥ
preṣye mayi sthite rājan na bhūyaḥ kleśam āpnuyāt', null, 7054014),
('ramayana-7-54-15', 15, 'Uttara Kanda, Sarga 54, Verse 15', 'तथा ब्रुवति शत्रुघ्ने राघवः पुनरब्रवीत्।
एवं भवतु काकुत्स्थ क्रियतां मम शासनम्॥', 'tathā bruvati śatrughne rāghavaḥ punar abravīt
evaṃ bhavatu kākutstha kriyatāṃ mama śāsanam', null, 7054015),
('ramayana-7-54-16', 16, 'Uttara Kanda, Sarga 54, Verse 16', 'राज्ये त्वामभिषेक्ष्यामि मधोस्तु नगरे शुभे।
निवेशय महाबाहो भरतं यद्यवेक्षसे॥', 'rājye tvām abhiṣekṣyāmi madhos tu nagare śubhe
niveśaya mahābāho bharataṃ yady avekṣase', null, 7054016),
('ramayana-7-54-17', 17, 'Uttara Kanda, Sarga 54, Verse 17', 'शूरस्त्वं कृतविद्यश्च समर्थः संनिवेशने।
नगरं मधुना जुष्टं तथा जनपदाञ्शुभान्॥', 'śūras tvaṃ kṛtavidyaś ca samarthaḥ saṃniveśane
nagaraṃ madhunā juṣṭaṃ tathā janapadāñ śubhān', null, 7054017),
('ramayana-7-54-18', 18, 'Uttara Kanda, Sarga 54, Verse 18', 'यो हि वंशं समुत्पाट्य पार्थिवस्य पुनः क्षये।
न विधत्ते नृपं तत्र नरकं स निगच्छति॥', 'yo hi vaṃśaṃ samutpāṭya pārthivasya punaḥ kṣaye
na vidhatte nṛpaṃ tatra narakaṃ sa nigacchati', null, 7054018),
('ramayana-7-54-19', 19, 'Uttara Kanda, Sarga 54, Verse 19', 'स त्वं हत्वा मधुसुतं लवणं पापनिश्चयम्।
राज्यं प्रशाधि धर्मेण वाक्यं मे यद्यवेक्षसे॥', 'sa tvaṃ hatvā madhusutaṃ lavaṇaṃ pāpaniścayam
rājyaṃ praśādhi dharmeṇa vākyaṃ me yady avekṣase', null, 7054019),
('ramayana-7-54-20', 20, 'Uttara Kanda, Sarga 54, Verse 20', 'उत्तरं च न वक्तव्यं शूर वाक्यान्तरे मम।
बालेन पूर्वजस्याज्ञा कर्तव्या नात्र संशयः॥', 'uttaraṃ ca na vaktavyaṃ śūra vākyāntare mama
bālena pūrvajasyājñā kartavyā nātra saṃśayaḥ', null, 7054020),
('ramayana-7-54-21', 21, 'Uttara Kanda, Sarga 54, Verse 21', 'अभिषेकं च काकुत्स्थ प्रतीच्छस्व मयोद्यतम्।
वसिष्ठप्रमुखैर्विप्रैर्विधिमन्त्रपुरस्कृतम्॥', 'abhiṣekaṃ ca kākutstha pratīcchasva mayodyatam
vasiṣṭhapramukhair viprair vidhimantrapuraskṛtam', null, 7054021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 55 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-55-1', 1, 'Uttara Kanda, Sarga 55, Verse 1', 'एवमुक्तस्तु रामेण परां व्रीडामुपागतः।
शत्रुघ्नो वीर्यसंपन्नो मन्दं मन्दमुवाच ह॥', 'evam uktas tu rāmeṇa parāṃ vrīḍām upāgataḥ
śatrughno vīryasaṃpanno mandaṃ mandam uvāca ha', null, 7055001),
('ramayana-7-55-2', 2, 'Uttara Kanda, Sarga 55, Verse 2', 'अवश्यं करणीयं च शासनं पुरुषर्षभ।
तव चैव महाभाग शासनं दुरतिक्रमम्।
अयं कामकरो राजंस्तवास्मि पुरुषर्षभ॥', 'avaśyaṃ karaṇīyaṃ ca śāsanaṃ puruṣarṣabha
tava caiva mahābhāga śāsanaṃ duratikramam
ayaṃ kāmakaro rājaṃs tavāsmi puruṣarṣabha', null, 7055002),
('ramayana-7-55-3', 3, 'Uttara Kanda, Sarga 55, Verse 3', 'एवमुक्ते तु शूरेण शत्रुघ्नेन महात्मना।
उवाच रामः संहृष्टो लक्ष्मणं भरतं तथा॥', 'evam ukte tu śūreṇa śatrughnena mahātmanā
uvāca rāmaḥ saṃhṛṣṭo lakṣmaṇaṃ bharataṃ tathā', null, 7055003),
('ramayana-7-55-4', 4, 'Uttara Kanda, Sarga 55, Verse 4', 'संभारानभिषेकस्य आनयध्वं समाहिताः।
अद्यैव पुरुषव्याघ्रमभिषेक्ष्यामि दुर्जयम्॥', 'saṃbhārān abhiṣekasya ānayadhvaṃ samāhitāḥ
adyaiva puruṣavyāghram abhiṣekṣyāmi durjayam', null, 7055004),
('ramayana-7-55-5', 5, 'Uttara Kanda, Sarga 55, Verse 5', 'पुरोधसं च काकुत्स्थौ नैगमानृत्विजस्तथा।
मन्त्रिणश्चैव मे सर्वानानयध्वं ममाज्ञया॥', 'purodhasaṃ ca kākutsthau naigamān ṛtvijas tathā
mantriṇaś caiva me sarvān ānayadhvaṃ mamājñayā', null, 7055005),
('ramayana-7-55-6', 6, 'Uttara Kanda, Sarga 55, Verse 6', 'राज्ञः शासनमाज्ञाय तथाकुर्वन्महारथाः।
अभिषेकसमारम्भं पुरस्कृत्य पुरोधसं।
प्रविष्टा राजभवनं पुरंदरगृहोपमम्॥', 'rājñaḥ śāsanam ājñāya tathākurvan mahārathāḥ
abhiṣekasamārambhaṃ puraskṛtya purodhasaṃ
praviṣṭā rājabhavanaṃ puraṃdaragṛhopamam', null, 7055006),
('ramayana-7-55-7', 7, 'Uttara Kanda, Sarga 55, Verse 7', 'ततोऽभिषेको ववृधे शत्रुघ्नस्य महात्मनः।
संप्रहर्षकरः श्रीमान्राघवस्य पुरस्य च॥', 'tato ''bhiṣeko vavṛdhe śatrughnasya mahātmanaḥ
saṃpraharṣakaraḥ śrīmān rāghavasya purasya ca', null, 7055007),
('ramayana-7-55-8', 8, 'Uttara Kanda, Sarga 55, Verse 8', 'ततोऽभिषिक्तं शत्रुघ्नमङ्कमारोप्य राघवः।
उवाच मधुरां वाणीं तेजस्तस्याभिपूरयन्॥', 'tato ''bhiṣiktaṃ śatrughnam aṅkam āropya rāghavaḥ
uvāca madhurāṃ vāṇīṃ tejas tasyābhipūrayan', null, 7055008),
('ramayana-7-55-9', 9, 'Uttara Kanda, Sarga 55, Verse 9', 'अयं शरस्त्वमोघस्ते दिव्यः परपुरंजयः।
अनेन लवणं सौम्य हन्तासि रघुनन्दन॥', 'ayaṃ śaras tv amoghas te divyaḥ parapuraṃjayaḥ
anena lavaṇaṃ saumya hantāsi raghunandana', null, 7055009),
('ramayana-7-55-10', 10, 'Uttara Kanda, Sarga 55, Verse 10', 'सृष्टः शरोऽयं काकुत्स्थ यदा शेते महार्णवे।
स्वयम्भूरजितो देवो यं नापश्यन्सुरासुराः॥', 'sṛṣṭaḥ śaro ''yaṃ kākutstha yadā śete mahārṇave
svayambhūr ajito devo yaṃ nāpaśyan surāsurāḥ', null, 7055010),
('ramayana-7-55-11', 11, 'Uttara Kanda, Sarga 55, Verse 11', 'अदृश्यः सर्वभूतानां तेनायं हि शरोत्तमः।
सृष्टः क्रोधाभिभूतेन विनाशार्थं दुरात्मनोः।
मधुकैटभयोर्वीर विघाते वर्तमानयोः॥', 'adṛśyaḥ sarvabhūtānāṃ tenāyaṃ hi śarottamaḥ
sṛṣṭaḥ krodhābhibhūtena vināśārthaṃ durātmanoḥ
madhukaiṭabhayor vīra vighāte vartamānayoḥ', null, 7055011),
('ramayana-7-55-12', 12, 'Uttara Kanda, Sarga 55, Verse 12', 'स्रष्टुकामेन लोकांस्त्रींस्तौ चानेन हतौ युधि।
अनेन शरमुख्येन ततो लोकांश्चकार सः॥', 'sraṣṭukāmena lokāṃs trīṃs tau cānena hatau yudhi
anena śaramukhyena tato lokāṃś cakāra saḥ', null, 7055012),
('ramayana-7-55-13', 13, 'Uttara Kanda, Sarga 55, Verse 13', 'नायं मया शरः पूर्वं रावणस्य वधार्थिना।
मुक्तः शत्रुघ्न भूतानां महांस्त्रासो भवेदिति॥', 'nāyaṃ mayā śaraḥ pūrvaṃ rāvaṇasya vadhārthinā
muktaḥ śatrughna bhūtānāṃ mahāṃs trāso bhaved iti', null, 7055013),
('ramayana-7-55-14', 14, 'Uttara Kanda, Sarga 55, Verse 14', 'यच्च तस्य महच्छूलं त्र्यम्बकेण महात्मना।
दत्तं शत्रुविनाशाय मधोरायुधमुत्तमम्॥', 'yac ca tasya mahac chūlaṃ tryambakeṇa mahātmanā
dattaṃ śatruvināśāya madhor āyudham uttamam', null, 7055014),
('ramayana-7-55-15', 15, 'Uttara Kanda, Sarga 55, Verse 15', 'तत्संनिक्षिप्य भवने पूज्यमानं पुनः पुनः।
दिशः सर्वाः समालोक्य प्राप्नोत्याहारमात्मनः॥', 'tat saṃnikṣipya bhavane pūjyamānaṃ punaḥ punaḥ
diśaḥ sarvāḥ samālokya prāpnoty āhāram ātmanaḥ', null, 7055015),
('ramayana-7-55-16', 16, 'Uttara Kanda, Sarga 55, Verse 16', 'यदा तु युद्धमाकाङ्क्षन्कश्चिदेनं समाह्वयेत्।
तदा शूलं गृहीत्वा तद्भस्म रक्षः करोति तम्॥', 'yadā tu yuddham ākāṅkṣan kaś cid enaṃ samāhvayet
tadā śūlaṃ gṛhītvā tad bhasma rakṣaḥ karoti tam', null, 7055016),
('ramayana-7-55-17', 17, 'Uttara Kanda, Sarga 55, Verse 17', 'स त्वं पुरुषशार्दूल तमायुधविवर्जितम्।
अप्रविष्टपुरं पूर्वं द्वारि तिष्ठ धृतायुधः॥', 'sa tvaṃ puruṣaśārdūla tam āyudhavivarjitam
apraviṣṭapuraṃ pūrvaṃ dvāri tiṣṭha dhṛtāyudhaḥ', null, 7055017),
('ramayana-7-55-18', 18, 'Uttara Kanda, Sarga 55, Verse 18', 'अप्रविष्टं च भवनं युद्धाय पुरुषर्षभ।
आह्वयेथा महाबाहो ततो हन्तासि राक्षसं॥', 'apraviṣṭaṃ ca bhavanaṃ yuddhāya puruṣarṣabha
āhvayethā mahābāho tato hantāsi rākṣasaṃ', null, 7055018),
('ramayana-7-55-19', 19, 'Uttara Kanda, Sarga 55, Verse 19', 'अन्यथा क्रियमाणे तु अवध्यः स भविष्यति।
यदि त्वेवं कृते वीर विनाशमुपयास्यति॥', 'anyathā kriyamāṇe tu avadhyaḥ sa bhaviṣyati
yadi tv evaṃ kṛte vīra vināśam upayāsyati', null, 7055019),
('ramayana-7-55-20', 20, 'Uttara Kanda, Sarga 55, Verse 20', 'एतत्ते सर्वमाख्यातं शूलस्य च विपर्ययम्।
श्रीमतः शितिकण्ठस्य कृत्यं हि दुरतिक्रमम्॥', 'etat te sarvam ākhyātaṃ śūlasya ca viparyayam
śrīmataḥ śitikaṇṭhasya kṛtyaṃ hi duratikramam', null, 7055020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 56 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-56-1', 1, 'Uttara Kanda, Sarga 56, Verse 1', 'एवमुक्त्वा तु काकुत्स्थं प्रशस्य च पुनः पुनः।
पुनरेवापरं वाक्यमुवाच रघुनन्दनः॥', 'evam uktvā tu kākutsthaṃ praśasya ca punaḥ punaḥ
punar evāparaṃ vākyam uvāca raghunandanaḥ', null, 7056001),
('ramayana-7-56-2', 2, 'Uttara Kanda, Sarga 56, Verse 2', 'इमान्यश्वसहस्राणि चत्वारि पुरुषर्षभ।
रथानां च सहस्रे द्वे गजानां शतमेव च॥', 'imāny aśvasahasrāṇi catvāri puruṣarṣabha
rathānāṃ ca sahasre dve gajānāṃ śatam eva ca', null, 7056002),
('ramayana-7-56-3', 3, 'Uttara Kanda, Sarga 56, Verse 3', 'अन्तरापणवीथ्यश्च नानापण्योपशोभिताः।
अनुगच्छन्तु शत्रुघ्न तथैव नटनर्तकाः॥', 'antarāpaṇavīthyaś ca nānāpaṇyopaśobhitāḥ
anugacchantu śatrughna tathaiva naṭanartakāḥ', null, 7056003),
('ramayana-7-56-4', 4, 'Uttara Kanda, Sarga 56, Verse 4', 'हिरण्यस्य सुवर्णस्य अयुतं पुरुषर्षभ।
गृहीत्वा गच्छ शत्रुघ्न पर्याप्तधनवाहनः॥', 'hiraṇyasya suvarṇasya ayutaṃ puruṣarṣabha
gṛhītvā gaccha śatrughna paryāptadhanavāhanaḥ', null, 7056004),
('ramayana-7-56-5', 5, 'Uttara Kanda, Sarga 56, Verse 5', 'बलं च सुभृतं वीर हृष्टपुष्टमनुत्तमम्।
संभाष्य संप्रदानेन रञ्जयस्व नरोत्तम॥', 'balaṃ ca subhṛtaṃ vīra hṛṣṭapuṣṭam anuttamam
saṃbhāṣya saṃpradānena rañjayasva narottama', null, 7056005),
('ramayana-7-56-6', 6, 'Uttara Kanda, Sarga 56, Verse 6', 'न ह्यर्थास्तत्र तिष्ठन्ति न दारा न च बान्धवाः।
सुप्रीतो भृत्यवर्गस्तु यत्र तिष्ठति राघव॥', 'na hy arthās tatra tiṣṭhanti na dārā na ca bāndhavāḥ
suprīto bhṛtyavargas tu yatra tiṣṭhati rāghava', null, 7056006),
('ramayana-7-56-7', 7, 'Uttara Kanda, Sarga 56, Verse 7', 'अतो हृष्टजनाकीर्णां प्रस्थाप्य महतीं चमूम्।
एक एव धनुष्पानिस्तद्गच्छ त्वं मधोर्वनम्॥', 'ato hṛṣṭajanākīrṇāṃ prasthāpya mahatīṃ camūm
eka eva dhanuṣpānis tad gaccha tvaṃ madhor vanam', null, 7056007),
('ramayana-7-56-8', 8, 'Uttara Kanda, Sarga 56, Verse 8', 'यथा त्वां न प्रजानाति गच्छन्तं युद्धकाङ्क्षिणम्।
लवणस्तु मधोः पुत्रस्तथा गच्छेरशङ्कितः॥', 'yathā tvāṃ na prajānāti gacchantaṃ yuddhakāṅkṣiṇam
lavaṇas tu madhoḥ putras tathā gaccher aśaṅkitaḥ', null, 7056008),
('ramayana-7-56-9', 9, 'Uttara Kanda, Sarga 56, Verse 9', 'न तस्य मृत्युरन्योऽस्ति कश्चिद्धि पुरुषर्षभ।
दर्शनं योऽभिगच्छेत स वध्यो लवणेन हि॥', 'na tasya mṛtyur anyo ''sti kaś cid dhi puruṣarṣabha
darśanaṃ yo ''bhigaccheta sa vadhyo lavaṇena hi', null, 7056009),
('ramayana-7-56-10', 10, 'Uttara Kanda, Sarga 56, Verse 10', 'स ग्रीष्मे व्यपयाते तु वर्षरात्र उपस्थिते।
हन्यास्त्वं लवणं सौम्य स हि कालोऽस्य दुर्मतेः॥', 'sa grīṣme vyapayāte tu varṣarātra upasthite
hanyās tvaṃ lavaṇaṃ saumya sa hi kālo ''sya durmateḥ', null, 7056010),
('ramayana-7-56-11', 11, 'Uttara Kanda, Sarga 56, Verse 11', 'महर्षींस्तु पुरस्कृत्य प्रयान्तु तव सैनिकाः।
यथा ग्रीष्मावशेषेण तरेयुर्जाह्नवीजलम्॥', 'maharṣīṃs tu puraskṛtya prayāntu tava sainikāḥ
yathā grīṣmāvaśeṣeṇa tareyur jāhnavījalam', null, 7056011),
('ramayana-7-56-12', 12, 'Uttara Kanda, Sarga 56, Verse 12', 'ततः स्थाप्य बलं सर्वं नदीतीरे समाहितः।
अग्रतो धनुषा सार्धं गच्छ त्वं लघुविक्रम॥', 'tataḥ sthāpya balaṃ sarvaṃ nadītīre samāhitaḥ
agrato dhanuṣā sārdhaṃ gaccha tvaṃ laghuvikrama', null, 7056012),
('ramayana-7-56-13', 13, 'Uttara Kanda, Sarga 56, Verse 13', 'एवमुक्तस्तु रामेण शत्रुघ्नस्तान्महाबलान्।
सेनामुख्यान्समानीय ततो वाक्यमुवाच ह॥', 'evam uktas tu rāmeṇa śatrughnas tān mahābalān
senāmukhyān samānīya tato vākyam uvāca ha', null, 7056013),
('ramayana-7-56-14', 14, 'Uttara Kanda, Sarga 56, Verse 14', 'एते वो गणिता वासा यत्र यत्र निवत्स्यथ।
स्थातव्यं चाविरोधेन यथा बाधा न कस्य चित्॥', 'ete vo gaṇitā vāsā yatra yatra nivatsyatha
sthātavyaṃ cāvirodhena yathā bādhā na kasya cit', null, 7056014),
('ramayana-7-56-15', 15, 'Uttara Kanda, Sarga 56, Verse 15', 'तथा तांस्तु समाज्ञाप्य निर्याप्य च महद्बलम्।
कौसल्यां च सुमित्रां च कैकेयीं चाभ्यवादयत्॥', 'tathā tāṃs tu samājñāpya niryāpya ca mahad balam
kausalyāṃ ca sumitrāṃ ca kaikeyīṃ cābhyavādayat', null, 7056015),
('ramayana-7-56-16', 16, 'Uttara Kanda, Sarga 56, Verse 16', 'रामं प्रदक्षिणं कृत्वा शिरसाभिप्रणम्य च।
राणेण चाभ्यनुज्ञातः शत्रुघ्नः शत्रुतापनः॥', 'rāmaṃ pradakṣiṇaṃ kṛtvā śirasābhipraṇamya ca
rāṇeṇa cābhyanujñātaḥ śatrughnaḥ śatrutāpanaḥ', null, 7056016),
('ramayana-7-56-17', 17, 'Uttara Kanda, Sarga 56, Verse 17', 'लक्ष्मणं भरतं चैव प्रणिपत्य कृताञ्जलिः।
पुरोधसं वसिष्ठं च शत्रुघ्नः प्रयतात्मवान्।
प्रदक्षिणमथो कृत्वा निर्जगाम महाबलः॥', 'lakṣmaṇaṃ bharataṃ caiva praṇipatya kṛtāñjaliḥ
purodhasaṃ vasiṣṭhaṃ ca śatrughnaḥ prayatātmavān
pradakṣiṇam atho kṛtvā nirjagāma mahābalaḥ', null, 7056017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 57 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-57-1', 1, 'Uttara Kanda, Sarga 57, Verse 1', 'प्रस्थाप्य तद्बलं सर्वं मासमात्रोषितः पथि।
एक एवाशु शत्रुघ्नो जगाम त्वरितस्तदा॥', 'prasthāpya tad balaṃ sarvaṃ māsamātroṣitaḥ pathi
eka evāśu śatrughno jagāma tvaritas tadā', null, 7057001),
('ramayana-7-57-2', 2, 'Uttara Kanda, Sarga 57, Verse 2', 'द्विरात्रमन्तरे शूर उष्य राघवनन्दनः।
वाल्मीकेराश्रमं पुण्यमगच्छद्वासमुत्तमम्॥', 'dvirātram antare śūra uṣya rāghavanandanaḥ
vālmīker āśramaṃ puṇyam agacchad vāsam uttamam', null, 7057002),
('ramayana-7-57-3', 3, 'Uttara Kanda, Sarga 57, Verse 3', 'सोऽभिवाद्य महात्मानं वाल्मीकिं मुनिसत्तमम्।
कृताञ्जलिरथो भूत्वा वाक्यमेतदुवाच ह॥', 'so ''bhivādya mahātmānaṃ vālmīkiṃ munisattamam
kṛtāñjalir atho bhūtvā vākyam etad uvāca ha', null, 7057003),
('ramayana-7-57-4', 4, 'Uttara Kanda, Sarga 57, Verse 4', 'भगवन्वस्तुमिच्छामि गुरोः कृत्यादिहागतः।
श्वः प्रभाते गमिष्यामि प्रतीचीं वारुणीं दिशम्॥', 'bhagavan vastum icchāmi guroḥ kṛtyād ihāgataḥ
śvaḥ prabhāte gamiṣyāmi pratīcīṃ vāruṇīṃ diśam', null, 7057004),
('ramayana-7-57-5', 5, 'Uttara Kanda, Sarga 57, Verse 5', 'शत्रुघ्नस्य वचः श्रुत्वा प्रहस्य मुनिपुंगवः।
प्रत्युवाच महात्मानं स्वागतं ते महायशः॥', 'śatrughnasya vacaḥ śrutvā prahasya munipuṃgavaḥ
pratyuvāca mahātmānaṃ svāgataṃ te mahāyaśaḥ', null, 7057005),
('ramayana-7-57-6', 6, 'Uttara Kanda, Sarga 57, Verse 6', 'स्वमाश्रममिदं सौम्य राघवाणां कुलस्य ह।
आसनं पाद्यमर्घ्यं च निर्विशङ्कः प्रतीच्छ मे॥', 'svam āśramam idaṃ saumya rāghavāṇāṃ kulasya ha
āsanaṃ pādyam arghyaṃ ca nirviśaṅkaḥ pratīccha me', null, 7057006),
('ramayana-7-57-7', 7, 'Uttara Kanda, Sarga 57, Verse 7', 'प्रतिगृह्य ततः पूजां फलमूलं च भोजनम्।
भक्षयामास काकुत्स्थस्तृप्तिं च परमां गतः॥', 'pratigṛhya tataḥ pūjāṃ phalamūlaṃ ca bhojanam
bhakṣayām āsa kākutsthas tṛptiṃ ca paramāṃ gataḥ', null, 7057007),
('ramayana-7-57-8', 8, 'Uttara Kanda, Sarga 57, Verse 8', 'स तु भुक्त्वा महाबाहुर्महर्षिं तमुवाच ह।
पूर्वं यज्ञविभूतीयं कस्याश्रमसमीपतः॥', 'sa tu bhuktvā mahābāhur maharṣiṃ tam uvāca ha
pūrvaṃ yajñavibhūtīyaṃ kasyāśramasamīpataḥ', null, 7057008),
('ramayana-7-57-9', 9, 'Uttara Kanda, Sarga 57, Verse 9', 'तस्य तद्भाषितं श्रुत्वा वाल्मीकिर्वाक्यमब्रवीत्।
शत्रुघ्न शृणु यस्येदं बभूवायतनं पुरा॥', 'tasya tadbhāṣitaṃ śrutvā vālmīkir vākyam abravīt
śatrughna śṛṇu yasyedaṃ babhūvāyatanaṃ purā', null, 7057009),
('ramayana-7-57-10', 10, 'Uttara Kanda, Sarga 57, Verse 10', 'युष्माकं पूर्वको राजा सुदासस्य महात्मनः।
पुत्रो मित्रसहो नाम वीर्यवानतिधार्मिकः॥', 'yuṣmākaṃ pūrvako rājā sudāsasya mahātmanaḥ
putro mitrasaho nāma vīryavān atidhārmikaḥ', null, 7057010),
('ramayana-7-57-11', 11, 'Uttara Kanda, Sarga 57, Verse 11', 'स बाल एव सौदासो मृगयामुपचक्रमे।
चञ्चूर्यमाणं ददृशे स शूरो राक्षसद्वयम्॥', 'sa bāla eva saudāso mṛgayām upacakrame
cañcūryamāṇaṃ dadṛśe sa śūro rākṣasadvayam', null, 7057011),
('ramayana-7-57-12', 12, 'Uttara Kanda, Sarga 57, Verse 12', 'शार्दूलरूपिणौ घोरौ मृगान्बहुसहस्रशः।
भक्षयाणावसंतुष्टौ पर्याप्तिं च न जग्मतुः॥', 'śārdūlarūpiṇau ghorau mṛgān bahusahasraśaḥ
bhakṣayāṇāv asaṃtuṣṭau paryāptiṃ ca na jagmatuḥ', null, 7057012),
('ramayana-7-57-13', 13, 'Uttara Kanda, Sarga 57, Verse 13', 'स तु तौ राक्षसौ दृष्ट्वा निर्मृगं च वनं कृतम्।
क्रोधेन महताविष्टो जघानैकं महेषुणा॥', 'sa tu tau rākṣasau dṛṣṭvā nirmṛgaṃ ca vanaṃ kṛtam
krodhena mahatāviṣṭo jaghānaikaṃ maheṣuṇā', null, 7057013),
('ramayana-7-57-14', 14, 'Uttara Kanda, Sarga 57, Verse 14', 'विनिपात्य तमेकं तु सौदासः पुरुषर्षभः।
विज्वरो विगतामर्षो हतं रक्षोऽभ्यवैक्षत॥', 'vinipātya tam ekaṃ tu saudāsaḥ puruṣarṣabhaḥ
vijvaro vigatāmarṣo hataṃ rakṣo ''bhyavaikṣata', null, 7057014),
('ramayana-7-57-15', 15, 'Uttara Kanda, Sarga 57, Verse 15', 'निरीक्षमाणं तं दृष्ट्वा सहायस्तस्य रक्षसः।
संतापमकरोद्घोरं सौदासं चेदमब्रवीत्॥', 'nirīkṣamāṇaṃ taṃ dṛṣṭvā sahāyas tasya rakṣasaḥ
saṃtāpam akarod ghoraṃ saudāsaṃ cedam abravīt', null, 7057015),
('ramayana-7-57-16', 16, 'Uttara Kanda, Sarga 57, Verse 16', 'यस्मादनपराद्धं त्वं सहायं मम जघ्निवान्।
तस्मात्तवापि पापिष्ठ प्रदास्यामि प्रतिक्रियाम्॥', 'yasmād anaparāddhaṃ tvaṃ sahāyaṃ mama jaghnivān
tasmāt tavāpi pāpiṣṭha pradāsyāmi pratikriyām', null, 7057016),
('ramayana-7-57-17', 17, 'Uttara Kanda, Sarga 57, Verse 17', 'एवमुक्त्वा तु तं रक्षस्तत्रैवान्तरधीयत।
कालपर्याययोगेन राजा मित्रसहोऽभवत्॥', 'evam uktvā tu taṃ rakṣas tatraivāntaradhīyata
kālaparyāyayogena rājā mitrasaho ''bhavat', null, 7057017),
('ramayana-7-57-18', 18, 'Uttara Kanda, Sarga 57, Verse 18', 'राजापि यजते यज्ञं तस्याश्रमसमीपतः।
अश्वमेधं महायज्ञं तं वसिष्ठोऽभ्यपालयत्॥', 'rājāpi yajate yajñaṃ tasyāśramasamīpataḥ
aśvamedhaṃ mahāyajñaṃ taṃ vasiṣṭho ''bhyapālayat', null, 7057018),
('ramayana-7-57-19', 19, 'Uttara Kanda, Sarga 57, Verse 19', 'तत्र यज्ञो महानासीद्बहुवर्षगणायुतान्।
समृद्धः परया लक्ष्म्या देवयज्ञसमोऽभवत्॥', 'tatra yajño mahān āsīd bahuvarṣagaṇāyutān
samṛddhaḥ parayā lakṣmyā devayajñasamo ''bhavat', null, 7057019),
('ramayana-7-57-20', 20, 'Uttara Kanda, Sarga 57, Verse 20', 'अथावसाने यज्ञस्य पूर्ववैरमनुस्मरन्।
वसिष्ठरूपी राजानमिति होवाच राक्षसः॥', 'athāvasāne yajñasya pūrvavairam anusmaran
vasiṣṭharūpī rājānam iti hovāca rākṣasaḥ', null, 7057020),
('ramayana-7-57-21', 21, 'Uttara Kanda, Sarga 57, Verse 21', 'अद्य यज्ञावसानान्ते सामिषं भोजनं मम।
दीयतामिति शीघ्रं वै नात्र कार्या विचारणा॥', 'adya yajñāvasānānte sāmiṣaṃ bhojanaṃ mama
dīyatām iti śīghraṃ vai nātra kāryā vicāraṇā', null, 7057021),
('ramayana-7-57-22', 22, 'Uttara Kanda, Sarga 57, Verse 22', 'तच्छ्रुत्वा व्याहृतं वाक्यं रक्षसा कामरूपिणा।
भक्षसंस्कारकुशलमुवाच पृथिवीपतिः॥', 'tac chrutvā vyāhṛtaṃ vākyaṃ rakṣasā kāmarūpiṇā
bhakṣasaṃskārakuśalam uvāca pṛthivīpatiḥ', null, 7057022),
('ramayana-7-57-23', 23, 'Uttara Kanda, Sarga 57, Verse 23', 'हविष्यं सामिषं स्वादु यथा भवति भोजनम्।
तथा कुरुष्व शीघ्रं वै परितुष्येद्यथा गुरुः॥', 'haviṣyaṃ sāmiṣaṃ svādu yathā bhavati bhojanam
tathā kuruṣva śīghraṃ vai parituṣyed yathā guruḥ', null, 7057023),
('ramayana-7-57-24', 24, 'Uttara Kanda, Sarga 57, Verse 24', 'शासनात्पार्थिवेन्द्रस्य सूदः संभ्रान्तमानसः।
स च रक्षः पुनस्तत्र सूदवेषमथाकरोत्॥', 'śāsanāt pārthivendrasya sūdaḥ saṃbhrāntamānasaḥ
sa ca rakṣaḥ punas tatra sūdaveṣam athākarot', null, 7057024),
('ramayana-7-57-25', 25, 'Uttara Kanda, Sarga 57, Verse 25', 'स मानुषमथो मांसं पार्थिवाय न्यवेदयत्।
इदं स्वादुहविष्यं च सामिषं चान्नमाहृतम्॥', 'sa mānuṣam atho māṃsaṃ pārthivāya nyavedayat
idaṃ svāduhaviṣyaṃ ca sāmiṣaṃ cānnam āhṛtam', null, 7057025),
('ramayana-7-57-26', 26, 'Uttara Kanda, Sarga 57, Verse 26', 'स भोजनं वसिष्ठाय पत्न्या सार्धमुपाहरत्।
मदयन्त्या नरव्याघ्र सामिषं रक्षसा हृतम्॥', 'sa bhojanaṃ vasiṣṭhāya patnyā sārdham upāharat
madayantyā naravyāghra sāmiṣaṃ rakṣasā hṛtam', null, 7057026),
('ramayana-7-57-27', 27, 'Uttara Kanda, Sarga 57, Verse 27', 'ज्ञात्वा तदामिषं विप्रो मानुषं भोजनाहृतम्।
क्रोधेन महताविष्टो व्याहर्तुमुपचक्रमे॥', 'jñātvā tadāmiṣaṃ vipro mānuṣaṃ bhojanāhṛtam
krodhena mahatāviṣṭo vyāhartum upacakrame', null, 7057027),
('ramayana-7-57-28', 28, 'Uttara Kanda, Sarga 57, Verse 28', 'यस्मात्त्वं भोजनं राजन्ममैतद्दातुमिच्छसि।
तस्माद्भोजनमेतत्ते भविष्यति न संशयः॥', 'yasmāt tvaṃ bhojanaṃ rājan mamaitad dātum icchasi
tasmād bhojanam etat te bhaviṣyati na saṃśayaḥ', null, 7057028),
('ramayana-7-57-29', 29, 'Uttara Kanda, Sarga 57, Verse 29', 'स राजा सह पत्न्या वै प्रणिपत्य मुहुर्मुहुः।
पुनर्वसिष्ठं प्रोवाच यदुक्तं ब्रह्मरूपिणा॥', 'sa rājā saha patnyā vai praṇipatya muhur muhuḥ
punar vasiṣṭhaṃ provāca yad uktaṃ brahmarūpiṇā', null, 7057029),
('ramayana-7-57-30', 30, 'Uttara Kanda, Sarga 57, Verse 30', 'तच्छ्रुता पार्थिवेन्द्रस्य रक्षसा विकृतं च तत्।
पुनः प्रोवाच राजानं वसिष्ठः पुरुषर्षभम्॥', 'tac chrutā pārthivendrasya rakṣasā vikṛtaṃ ca tat
punaḥ provāca rājānaṃ vasiṣṭhaḥ puruṣarṣabham', null, 7057030),
('ramayana-7-57-31', 31, 'Uttara Kanda, Sarga 57, Verse 31', 'मया रोषपरीतेन यदिदं व्याहृतं वचः।
नैतच्छक्यं वृथा कर्तुं प्रदास्यामि च ते वरम्॥', 'mayā roṣaparītena yad idaṃ vyāhṛtaṃ vacaḥ
naitac chakyaṃ vṛthā kartuṃ pradāsyāmi ca te varam', null, 7057031),
('ramayana-7-57-32', 32, 'Uttara Kanda, Sarga 57, Verse 32', 'कालो द्वादश वर्षाणि शापस्यास्य भविष्यति।
मत्प्रसादाच्च राजेन्द्र अतीतं न स्मरिष्यसि॥', 'kālo dvādaśa varṣāṇi śāpasyāsya bhaviṣyati
matprasādāc ca rājendra atītaṃ na smariṣyasi', null, 7057032),
('ramayana-7-57-33', 33, 'Uttara Kanda, Sarga 57, Verse 33', 'एवं स राजा तं शापमुपभुज्यारिमर्दनः।
प्रतिलेभे पुना राज्यं प्रजाश्चैवान्वपालयत्॥', 'evaṃ sa rājā taṃ śāpam upabhujyārimardanaḥ
pratilebhe punā rājyaṃ prajāś caivānvapālayat', null, 7057033),
('ramayana-7-57-34', 34, 'Uttara Kanda, Sarga 57, Verse 34', 'तस्य कल्माषपादस्य यज्ञस्यायतनं शुभम्।
आश्रमस्य समीपेऽस्मिन्यस्मिन्पृच्छसि राघव॥', 'tasya kalmāṣapādasya yajñasyāyatanaṃ śubham
āśramasya samīpe ''smin yasmin pṛcchasi rāghava', null, 7057034),
('ramayana-7-57-35', 35, 'Uttara Kanda, Sarga 57, Verse 35', 'तस्य तां पार्थिवेन्द्रस्य कथां श्रुत्वा सुदारुणाम्।
विवेश पर्णशालायां महर्षिमभिवाद्य च॥', 'tasya tāṃ pārthivendrasya kathāṃ śrutvā sudāruṇām
viveśa parṇaśālāyāṃ maharṣim abhivādya ca', null, 7057035)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 58 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-58-1', 1, 'Uttara Kanda, Sarga 58, Verse 1', 'यामेव रात्रिं शत्रुघ्न पर्णशालां समाविशत्।
तामेव रात्रिं सीतापि प्रसूता दारकद्वयम्॥', 'yām eva rātriṃ śatrughna parṇaśālāṃ samāviśat
tām eva rātriṃ sītāpi prasūtā dārakadvayam', null, 7058001),
('ramayana-7-58-2', 2, 'Uttara Kanda, Sarga 58, Verse 2', 'ततोऽर्धरात्रसमये बालका मुनिदारकाः।
वाल्मीकेः प्रियमाचख्युः सीतायाः प्रसवं शुभम्।
तस्य रक्षां महातेजः कुरु भूतविनाशिनीम्॥', 'tato ''rdharātrasamaye bālakā munidārakāḥ
vālmīkeḥ priyam ācakhyuḥ sītāyāḥ prasavaṃ śubham
tasya rakṣāṃ mahātejaḥ kuru bhūtavināśinīm', null, 7058002),
('ramayana-7-58-3', 3, 'Uttara Kanda, Sarga 58, Verse 3', 'तेषां तद्वचनं श्रुत्वा मुनिर्हर्षमुपागमत्।
भूतघ्नीं चाकरोत्ताभ्यां रक्षां रक्षोविनाशिनीम्॥', 'teṣāṃ tad vacanaṃ śrutvā munir harṣam upāgamat
bhūtaghnīṃ cākarot tābhyāṃ rakṣāṃ rakṣovināśinīm', null, 7058003),
('ramayana-7-58-4', 4, 'Uttara Kanda, Sarga 58, Verse 4', 'कुशमुष्टिमुपादाय लवं चैव तु स द्विजः।
वाल्मीकिः प्रददौ ताभ्यां रक्षां भूतविनाशिनीम्॥', 'kuśamuṣṭim upādāya lavaṃ caiva tu sa dvijaḥ
vālmīkiḥ pradadau tābhyāṃ rakṣāṃ bhūtavināśinīm', null, 7058004),
('ramayana-7-58-5', 5, 'Uttara Kanda, Sarga 58, Verse 5', 'यस्तयोः पूर्वजो जातः स कुशैर्मन्त्रसंस्कृतैः।
निर्मार्जनीयस्तु भवेत्कुश इत्यस्य नामतः॥', 'yas tayoḥ pūrvajo jātaḥ sa kuśair mantrasaṃskṛtaiḥ
nirmārjanīyas tu bhavet kuśa ity asya nāmataḥ', null, 7058005),
('ramayana-7-58-6', 6, 'Uttara Kanda, Sarga 58, Verse 6', 'यश्चापरो भवेत्ताभ्यां लवेन सुसमाहितः।
निर्मार्जनीयो वृद्धाभिर्लवश्चेति स नामतः॥', 'yaś cāparo bhavet tābhyāṃ lavena susamāhitaḥ
nirmārjanīyo vṛddhābhir lavaś ceti sa nāmataḥ', null, 7058006),
('ramayana-7-58-7', 7, 'Uttara Kanda, Sarga 58, Verse 7', 'एवं कुशलवौ नाम्ना तावुभौ यमजातकौ।
मत्कृतभ्यां च नामभ्यां ख्यातियुक्तौ भविष्यतः॥', 'evaṃ kuśalavau nāmnā tāv ubhau yamajātakau
matkṛtabhyāṃ ca nāmabhyāṃ khyātiyuktau bhaviṣyataḥ', null, 7058007),
('ramayana-7-58-8', 8, 'Uttara Kanda, Sarga 58, Verse 8', 'ते रक्षां जगृहुस्तां च मुनिहस्तात्समाहिताः।
अकुर्वंश्च ततो रक्षां तयोर्विगतकल्मषाः॥', 'te rakṣāṃ jagṛhus tāṃ ca munihastāt samāhitāḥ
akurvaṃś ca tato rakṣāṃ tayor vigatakalmaṣāḥ', null, 7058008),
('ramayana-7-58-9', 9, 'Uttara Kanda, Sarga 58, Verse 9', 'तथा तां क्रियमाणां तु रक्षां गोत्रं च नाम च।
संकीर्तनं च रामस्य सीतायाः प्रसवौ शुभौ॥', 'tathā tāṃ kriyamāṇāṃ tu rakṣāṃ gotraṃ ca nāma ca
saṃkīrtanaṃ ca rāmasya sītāyāḥ prasavau śubhau', null, 7058009),
('ramayana-7-58-10', 10, 'Uttara Kanda, Sarga 58, Verse 10', 'अर्धरात्रे तु शत्रुघ्नः शुश्राव सुमहत्प्रियम्।
पर्णशालां गतो रात्रौ दिष्ट्या दिष्ट्येति चाब्रवीत्॥', 'ardharātre tu śatrughnaḥ śuśrāva sumahat priyam
parṇaśālāṃ gato rātrau diṣṭyā diṣṭyeti cābravīt', null, 7058010),
('ramayana-7-58-11', 11, 'Uttara Kanda, Sarga 58, Verse 11', 'तथ तस्य प्रहृष्टस्य शत्रुघ्नस्य महात्मनः।
व्यतीता वार्षिकी रात्रिः श्रावणी लघुविक्रमा॥', 'tatha tasya prahṛṣṭasya śatrughnasya mahātmanaḥ
vyatītā vārṣikī rātriḥ śrāvaṇī laghuvikramā', null, 7058011),
('ramayana-7-58-12', 12, 'Uttara Kanda, Sarga 58, Verse 12', 'प्रभाते तु महावीर्यः कृत्वा पौर्वाह्णिकं क्रमम्।
मुनिं प्राञ्जलिरामन्त्र्य प्रायात्पश्चान्मुखः पुनः॥', 'prabhāte tu mahāvīryaḥ kṛtvā paurvāhṇikaṃ kramam
muniṃ prāñjalir āmantrya prāyāt paścānmukhaḥ punaḥ', null, 7058012),
('ramayana-7-58-13', 13, 'Uttara Kanda, Sarga 58, Verse 13', 'स गत्वा यमुनातीरं सप्तरात्रोषितः पथि।
ऋषीणां पुण्यकीर्तीनामाश्रमे वासमभ्ययात्॥', 'sa gatvā yamunātīraṃ saptarātroṣitaḥ pathi
ṛṣīṇāṃ puṇyakīrtīnām āśrame vāsam abhyayāt', null, 7058013),
('ramayana-7-58-14', 14, 'Uttara Kanda, Sarga 58, Verse 14', 'स तत्र मुनिभिः सार्धं भार्गवप्रमुखैर्नृपः।
कथाभिर्बहुरूपाभिर्वासं चक्रे महायशाः॥', 'sa tatra munibhiḥ sārdhaṃ bhārgavapramukhair nṛpaḥ
kathābhir bahurūpābhir vāsaṃ cakre mahāyaśāḥ', null, 7058014)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 59 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-59-1', 1, 'Uttara Kanda, Sarga 59, Verse 1', 'अथ रात्र्यां प्रवृत्तायां शत्रुघ्नो भृगुनन्दनम्।
पप्रच्छ च्यवनं विप्रं लवणस्य बलाबलम्॥', 'atha rātryāṃ pravṛttāyāṃ śatrughno bhṛgunandanam
papraccha cyavanaṃ vipraṃ lavaṇasya balābalam', null, 7059001),
('ramayana-7-59-2', 2, 'Uttara Kanda, Sarga 59, Verse 2', 'शूलस्य च बलं ब्रह्मन्के च पूर्वं निपातिताः।
अनेन शूलमुखेन द्वन्द्वयुद्धमुपागताः॥', 'śūlasya ca balaṃ brahman ke ca pūrvaṃ nipātitāḥ
anena śūlamukhena dvandvayuddham upāgatāḥ', null, 7059002),
('ramayana-7-59-3', 3, 'Uttara Kanda, Sarga 59, Verse 3', 'तस्य तद्भाषितं श्रुत्वा शत्रुघ्नस्य महात्मनः।
प्रत्युवाच महातेजाश्च्यवनो रघुनन्दनम्॥', 'tasya tadbhāṣitaṃ śrutvā śatrughnasya mahātmanaḥ
pratyuvāca mahātejāś cyavano raghunandanam', null, 7059003),
('ramayana-7-59-4', 4, 'Uttara Kanda, Sarga 59, Verse 4', 'असंख्येयानि कर्माणि यान्यस्य पुरुषर्षभ।
इक्ष्वाकुवंशप्रभवे यद्वृत्तं तच्छृणुष्व मे॥', 'asaṃkhyeyāni karmāṇi yāny asya puruṣarṣabha
ikṣvākuvaṃśaprabhave yad vṛttaṃ tac chṛṇuṣva me', null, 7059004),
('ramayana-7-59-5', 5, 'Uttara Kanda, Sarga 59, Verse 5', 'अयोध्यायां पुरा राजा युवनाश्वसुतो बली।
मान्धाता इति विख्यातस्त्रिषु लोकेषु वीर्यवान्॥', 'ayodhyāyāṃ purā rājā yuvanāśvasuto balī
māndhātā iti vikhyātas triṣu lokeṣu vīryavān', null, 7059005),
('ramayana-7-59-6', 6, 'Uttara Kanda, Sarga 59, Verse 6', 'स कृत्वा पृथिवीं कृत्स्नां शासने पृथिवीपतिः।
सुरलोकमथो जेतुमुद्योगमकरोन्नृपः॥', 'sa kṛtvā pṛthivīṃ kṛtsnāṃ śāsane pṛthivīpatiḥ
suralokam atho jetum udyogam akaron nṛpaḥ', null, 7059006),
('ramayana-7-59-7', 7, 'Uttara Kanda, Sarga 59, Verse 7', 'इन्द्रस्य तु भयं तीव्रं सुराणां च महात्मनाम्।
मान्धातरि कृतोद्योगे देवलोकजिगीषया॥', 'indrasya tu bhayaṃ tīvraṃ surāṇāṃ ca mahātmanām
māndhātari kṛtodyoge devalokajigīṣayā', null, 7059007),
('ramayana-7-59-8', 8, 'Uttara Kanda, Sarga 59, Verse 8', 'अर्धासनेन शक्रस्य राज्यार्धेन च पार्थिवः।
वन्द्यमानः सुरगणैः प्रतिज्ञामध्यरोहत॥', 'ardhāsanena śakrasya rājyārdhena ca pārthivaḥ
vandyamānaḥ suragaṇaiḥ pratijñām adhyarohata', null, 7059008),
('ramayana-7-59-9', 9, 'Uttara Kanda, Sarga 59, Verse 9', 'तस्य पापमभिप्रायं विदित्वा पाकशासनः।
सान्त्वपूर्वमिदं वाक्यमुवाच युवनाश्वजम्॥', 'tasya pāpam abhiprāyaṃ viditvā pākaśāsanaḥ
sāntvapūrvam idaṃ vākyam uvāca yuvanāśvajam', null, 7059009),
('ramayana-7-59-10', 10, 'Uttara Kanda, Sarga 59, Verse 10', 'राजा त्वं मानुषे लोके न तावत्पुरुषर्षभ।
अकृत्वा पृथिवीं वश्यां देवराज्यमिहेच्छसि॥', 'rājā tvaṃ mānuṣe loke na tāvat puruṣarṣabha
akṛtvā pṛthivīṃ vaśyāṃ devarājyam ihecchasi', null, 7059010),
('ramayana-7-59-11', 11, 'Uttara Kanda, Sarga 59, Verse 11', 'यदि वीर समग्रा ते मेदिनी निखिला वशे।
देवराज्यं कुरुष्वेह सभृत्यबलवाहनः॥', 'yadi vīra samagrā te medinī nikhilā vaśe
devarājyaṃ kuruṣveha sabhṛtyabalavāhanaḥ', null, 7059011),
('ramayana-7-59-12', 12, 'Uttara Kanda, Sarga 59, Verse 12', 'इन्द्रमेवं ब्रुवाणं तु मान्धाता वाक्यमब्रवीत्।
क्व मे शक्र प्रतिहतं शासनं पृथिवीतले॥', 'indram evaṃ bruvāṇaṃ tu māndhātā vākyam abravīt
kva me śakra pratihataṃ śāsanaṃ pṛthivītale', null, 7059012),
('ramayana-7-59-13', 13, 'Uttara Kanda, Sarga 59, Verse 13', 'तमुवाच सहस्राक्षो लवणो नाम राक्षसः।
मधुपुत्रो मधुवने नाज्ञां ते कुरुतेऽनघ॥', 'tam uvāca sahasrākṣo lavaṇo nāma rākṣasaḥ
madhuputro madhuvane nājñāṃ te kurute ''nagha', null, 7059013),
('ramayana-7-59-14', 14, 'Uttara Kanda, Sarga 59, Verse 14', 'तच्छ्रुत्वा विप्रियं घोरं सहस्राक्षेण भाषितम्।
व्रीडितोऽवाङ्मुखो राजा व्याहर्तुं न शशाक ह॥', 'tac chrutvā vipriyaṃ ghoraṃ sahasrākṣeṇa bhāṣitam
vrīḍito ''vāṅmukho rājā vyāhartuṃ na śaśāka ha', null, 7059014),
('ramayana-7-59-15', 15, 'Uttara Kanda, Sarga 59, Verse 15', 'आमन्त्र्य तु सहस्राक्षं ह्रिया किं चिदवाङ्मुखः।
पुनरेवागमच्छ्रीमानिमं लोकं नरेश्वरः॥', 'āmantrya tu sahasrākṣaṃ hriyā kiṃ cid avāṅmukhaḥ
punar evāgamac chrīmān imaṃ lokaṃ nareśvaraḥ', null, 7059015),
('ramayana-7-59-16', 16, 'Uttara Kanda, Sarga 59, Verse 16', 'स कृत्वा हृदयेऽमर्षं सभृत्यबलवाहनः।
आजगाम मधोः पुत्रं वशे कर्तुमनिन्दितः॥', 'sa kṛtvā hṛdaye ''marṣaṃ sabhṛtyabalavāhanaḥ
ājagāma madhoḥ putraṃ vaśe kartum aninditaḥ', null, 7059016),
('ramayana-7-59-17', 17, 'Uttara Kanda, Sarga 59, Verse 17', 'स काङ्क्षमाणो लवणं युद्धाय पुरुषर्षभः।
दूतं संप्रेषयामास सकाशं लवणस्य सः॥', 'sa kāṅkṣamāṇo lavaṇaṃ yuddhāya puruṣarṣabhaḥ
dūtaṃ saṃpreṣayām āsa sakāśaṃ lavaṇasya saḥ', null, 7059017),
('ramayana-7-59-18', 18, 'Uttara Kanda, Sarga 59, Verse 18', 'स गत्वा विप्रियाण्याह बहूनि मधुनः सुतम्।
वदन्तमेवं तं दूतं भक्षयामास राक्षसः॥', 'sa gatvā vipriyāṇy āha bahūni madhunaḥ sutam
vadantam evaṃ taṃ dūtaṃ bhakṣayām āsa rākṣasaḥ', null, 7059018),
('ramayana-7-59-19', 19, 'Uttara Kanda, Sarga 59, Verse 19', 'चिरायमाणे दूते तु राजा क्रोधसमन्वितः।
अर्दयामास तद्रक्षः शरवृष्ट्या समन्ततः॥', 'cirāyamāṇe dūte tu rājā krodhasamanvitaḥ
ardayām āsa tad rakṣaḥ śaravṛṣṭyā samantataḥ', null, 7059019),
('ramayana-7-59-20', 20, 'Uttara Kanda, Sarga 59, Verse 20', 'ततः प्रहस्य लवणः शूलं जग्राह पाणिना।
वधाय सानुबन्धस्य मुमोचायुधमुत्तमम्॥', 'tataḥ prahasya lavaṇaḥ śūlaṃ jagrāha pāṇinā
vadhāya sānubandhasya mumocāyudham uttamam', null, 7059020),
('ramayana-7-59-21', 21, 'Uttara Kanda, Sarga 59, Verse 21', 'तच्छूलं दीप्यमानं तु सभृत्यबलवाहनम्।
भस्मीकृत्य नृपं भूयो लवणस्यागमत्करम्॥', 'tac chūlaṃ dīpyamānaṃ tu sabhṛtyabalavāhanam
bhasmīkṛtya nṛpaṃ bhūyo lavaṇasyāgamat karam', null, 7059021),
('ramayana-7-59-22', 22, 'Uttara Kanda, Sarga 59, Verse 22', 'एवं स राजा सुमहान्हतः सबलवाहनः।
शूलस्य च बलं वीर अप्रमेयमनुत्तमम्॥', 'evaṃ sa rājā sumahān hataḥ sabalavāhanaḥ
śūlasya ca balaṃ vīra aprameyam anuttamam', null, 7059022),
('ramayana-7-59-23', 23, 'Uttara Kanda, Sarga 59, Verse 23', 'श्वः प्रभाते तु लवणं वधिष्यसि न संशयः।
अगृहीतायुधं क्षिप्रं ध्रुवो हि विजयस्तव॥', 'śvaḥ prabhāte tu lavaṇaṃ vadhiṣyasi na saṃśayaḥ
agṛhītāyudhaṃ kṣipraṃ dhruvo hi vijayas tava', null, 7059023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 60 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-60-1', 1, 'Uttara Kanda, Sarga 60, Verse 1', 'कथां कथयतां तेषां जयं चाकाङ्क्षतां शुभम्।
व्यतीता रजनी शीघ्रं शत्रुघ्नस्य महात्मनः॥', 'kathāṃ kathayatāṃ teṣāṃ jayaṃ cākāṅkṣatāṃ śubham
vyatītā rajanī śīghraṃ śatrughnasya mahātmanaḥ', null, 7060001),
('ramayana-7-60-2', 2, 'Uttara Kanda, Sarga 60, Verse 2', 'ततः प्रभाते विमले तस्मिन्काले स राक्षसः।
निर्गतस्तु पुराद्वीरो भक्षाहारप्रचोदितः॥', 'tataḥ prabhāte vimale tasmin kāle sa rākṣasaḥ
nirgatas tu purād vīro bhakṣāhārapracoditaḥ', null, 7060002),
('ramayana-7-60-3', 3, 'Uttara Kanda, Sarga 60, Verse 3', 'एतस्मिन्नन्तरे शूरः शत्रुघ्नो यमुनां नदीम्।
तीर्त्वा मधुपुरद्वारि धनुष्पाणिरतिष्ठत॥', 'etasminn antare śūraḥ śatrughno yamunāṃ nadīm
tīrtvā madhupuradvāri dhanuṣpāṇir atiṣṭhata', null, 7060003),
('ramayana-7-60-4', 4, 'Uttara Kanda, Sarga 60, Verse 4', 'ततोऽर्धदिवसे प्राप्ते क्रूरकर्मा स राक्षसः।
आगच्छद्बहुसहस्रं प्राणिनामुद्वहन्भरम्॥', 'tato ''rdhadivase prāpte krūrakarmā sa rākṣasaḥ
āgacchad bahusahasraṃ prāṇinām udvahan bharam', null, 7060004),
('ramayana-7-60-5', 5, 'Uttara Kanda, Sarga 60, Verse 5', 'ततो ददर्श शत्रुघ्नं स्थितं द्वारि धृतायुधम्।
तमुवाच ततो रक्षः किमनेन करिष्यसि॥', 'tato dadarśa śatrughnaṃ sthitaṃ dvāri dhṛtāyudham
tam uvāca tato rakṣaḥ kim anena kariṣyasi', null, 7060005),
('ramayana-7-60-6', 6, 'Uttara Kanda, Sarga 60, Verse 6', 'ईदृशानां सहस्राणि सायुधानां नराधम।
भक्षितानि मया रोषात्कालमाकाङ्क्षसे नु किम्॥', 'īdṛśānāṃ sahasrāṇi sāyudhānāṃ narādhama
bhakṣitāni mayā roṣāt kālam ākāṅkṣase nu kim', null, 7060006),
('ramayana-7-60-7', 7, 'Uttara Kanda, Sarga 60, Verse 7', 'आहारश्चाप्यसंपूर्णो ममायं पुरुषाधम।
स्वयं प्रविष्टो नु मुखं कथमासाद्य दुर्मते॥', 'āhāraś cāpy asaṃpūrṇo mamāyaṃ puruṣādhama
svayaṃ praviṣṭo nu mukhaṃ katham āsādya durmate', null, 7060007),
('ramayana-7-60-8', 8, 'Uttara Kanda, Sarga 60, Verse 8', 'तस्यैवं भाषमाणस्य हसतश्च मुहुर्मुहुः।
शत्रुघ्नो वीर्यसंपन्नो रोषादश्रूण्यवर्तयत्॥', 'tasyaivaṃ bhāṣamāṇasya hasataś ca muhur muhuḥ
śatrughno vīryasaṃpanno roṣād aśrūṇy avartayat', null, 7060008),
('ramayana-7-60-9', 9, 'Uttara Kanda, Sarga 60, Verse 9', 'तस्य रोषाभिभूतस्य शत्रुघ्नस्य महात्मनः।
तेजोमया मरीच्यस्तु सर्वगात्रैर्विनिष्पतन्॥', 'tasya roṣābhibhūtasya śatrughnasya mahātmanaḥ
tejomayā marīcyas tu sarvagātrair viniṣpatan', null, 7060009),
('ramayana-7-60-10', 10, 'Uttara Kanda, Sarga 60, Verse 10', 'उवाच च सुसंक्रुद्धः शत्रुघ्नस्तं निशाचरम्।
योद्धुमिच्छामि दुर्बुद्धे द्वन्द्वयुद्धं त्वया सह॥', 'uvāca ca susaṃkruddhaḥ śatrughnas taṃ niśācaram
yoddhum icchāmi durbuddhe dvandvayuddhaṃ tvayā saha', null, 7060010),
('ramayana-7-60-11', 11, 'Uttara Kanda, Sarga 60, Verse 11', 'पुत्रो दशरथस्याहं भ्राता रामस्य धीमतः।
शत्रुघ्नो नाम शत्रुघ्नो वधाकाङ्क्षी तवागतः॥', 'putro daśarathasyāhaṃ bhrātā rāmasya dhīmataḥ
śatrughno nāma śatrughno vadhākāṅkṣī tavāgataḥ', null, 7060011),
('ramayana-7-60-12', 12, 'Uttara Kanda, Sarga 60, Verse 12', 'तस्य मे युद्धकामस्य द्वन्द्वयुद्धं प्रदीयताम्।
शत्रुस्त्वं सर्वजीवानां न मे जीवन्गमिष्यसि॥', 'tasya me yuddhakāmasya dvandvayuddhaṃ pradīyatām
śatrus tvaṃ sarvajīvānāṃ na me jīvan gamiṣyasi', null, 7060012),
('ramayana-7-60-13', 13, 'Uttara Kanda, Sarga 60, Verse 13', 'तस्मिंस्तथा ब्रुवाणे तु राक्षसः प्रहसन्निव।
प्रत्युवाच नरश्रेष्ठं दिष्ट्या प्राप्तोऽसि दुर्मते॥', 'tasmiṃs tathā bruvāṇe tu rākṣasaḥ prahasann iva
pratyuvāca naraśreṣṭhaṃ diṣṭyā prāpto ''si durmate', null, 7060013),
('ramayana-7-60-14', 14, 'Uttara Kanda, Sarga 60, Verse 14', 'मम मातृष्वसुर्भ्राता रावणो नाम राक्षसः।
हतो रामेण दुर्बुद्धे स्त्रीहेतोः पुरुषाधम॥', 'mama mātṛṣvasur bhrātā rāvaṇo nāma rākṣasaḥ
hato rāmeṇa durbuddhe strīhetoḥ puruṣādhama', null, 7060014),
('ramayana-7-60-15', 15, 'Uttara Kanda, Sarga 60, Verse 15', 'तच्च सर्वं मया क्षान्तं रावणस्य कुलक्षयम्।
अवज्ञां पुरतः कृत्वा मया यूयं विशेषतः॥', 'tac ca sarvaṃ mayā kṣāntaṃ rāvaṇasya kulakṣayam
avajñāṃ purataḥ kṛtvā mayā yūyaṃ viśeṣataḥ', null, 7060015),
('ramayana-7-60-16', 16, 'Uttara Kanda, Sarga 60, Verse 16', 'न हताश्च हि मे सर्वे परिभूतास्तृणं यथा।
भूताश्चैव भविष्याश्च यूयं च पुरुषाधमाः॥', 'na hatāś ca hi me sarve paribhūtās tṛṇaṃ yathā
bhūtāś caiva bhaviṣyāś ca yūyaṃ ca puruṣādhamāḥ', null, 7060016),
('ramayana-7-60-17', 17, 'Uttara Kanda, Sarga 60, Verse 17', 'तस्य ते युद्धकामस्य युद्धं दास्यामि दुर्मते।
ईप्सितं यादृशं तुभ्यं सज्जये यावदायुधम्॥', 'tasya te yuddhakāmasya yuddhaṃ dāsyāmi durmate
īpsitaṃ yādṛśaṃ tubhyaṃ sajjaye yāvad āyudham', null, 7060017),
('ramayana-7-60-18', 18, 'Uttara Kanda, Sarga 60, Verse 18', 'तमुवाचाथ शत्रुघ्नः क्व मे जीवन्गमिष्यसि।
दुर्बलोऽप्यागतः शत्रुर्न मोक्तव्यः कृतात्मना॥', 'tam uvācātha śatrughnaḥ kva me jīvan gamiṣyasi
durbalo ''py āgataḥ śatrur na moktavyaḥ kṛtātmanā', null, 7060018),
('ramayana-7-60-19', 19, 'Uttara Kanda, Sarga 60, Verse 19', 'यो हि विक्लवया बुद्ध्या प्रसरं शत्रवे ददौ।
स हतो मन्दबुद्धित्वाद्यथा कापुरुषस्तथा॥', 'yo hi viklavayā buddhyā prasaraṃ śatrave dadau
sa hato mandabuddhitvād yathā kāpuruṣas tathā', null, 7060019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 61 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-61-1', 1, 'Uttara Kanda, Sarga 61, Verse 1', 'तच्छ्रुत्वा भाषितं तस्य शत्रुघ्नस्य महात्मनः।
क्रोधमाहारयत्तीव्रं तिष्ठ तिष्ठेति चाब्रवीत्॥', 'tac chrutvā bhāṣitaṃ tasya śatrughnasya mahātmanaḥ
krodham āhārayat tīvraṃ tiṣṭha tiṣṭheti cābravīt', null, 7061001),
('ramayana-7-61-2', 2, 'Uttara Kanda, Sarga 61, Verse 2', 'पाणौ पाणिं विनिष्पिष्य दन्तान्कटकटाय्य च।
लवणो रघुशार्दूलमाह्वयामास चासकृत्॥', 'pāṇau pāṇiṃ viniṣpiṣya dantān kaṭakaṭāyya ca
lavaṇo raghuśārdūlam āhvayām āsa cāsakṛt', null, 7061002),
('ramayana-7-61-3', 3, 'Uttara Kanda, Sarga 61, Verse 3', 'तं ब्रुवाणं तथा वाक्यं लवणं घोरविक्रमम्।
शत्रुघ्नो देव शत्रुघ्न इदं वचनमब्रवीत्॥', 'taṃ bruvāṇaṃ tathā vākyaṃ lavaṇaṃ ghoravikramam
śatrughno deva śatrughna idaṃ vacanam abravīt', null, 7061003),
('ramayana-7-61-4', 4, 'Uttara Kanda, Sarga 61, Verse 4', 'शत्रुघ्नो न तदा जातो यदान्ये निर्जितास्त्वया।
तदद्य बाणाभिहतो व्रज तं यमसादनम्॥', 'śatrughno na tadā jāto yadānye nirjitās tvayā
tad adya bāṇābhihato vraja taṃ yamasādanam', null, 7061004),
('ramayana-7-61-5', 5, 'Uttara Kanda, Sarga 61, Verse 5', 'ऋषयोऽप्यद्य पापात्मन्मया त्वां निहतं रणे।
पश्यन्तु विप्रा विद्वांसस्त्रिदशा इव रावणम्॥', 'ṛṣayo ''py adya pāpātman mayā tvāṃ nihataṃ raṇe
paśyantu viprā vidvāṃsas tridaśā iva rāvaṇam', null, 7061005),
('ramayana-7-61-6', 6, 'Uttara Kanda, Sarga 61, Verse 6', 'त्वयि मद्बाणनिर्दग्धे पतितेऽद्य निशाचर।
पुरं जनपदं चापि क्षेममेतद्भविष्यति॥', 'tvayi madbāṇanirdagdhe patite ''dya niśācara
puraṃ janapadaṃ cāpi kṣemam etad bhaviṣyati', null, 7061006),
('ramayana-7-61-7', 7, 'Uttara Kanda, Sarga 61, Verse 7', 'अद्य मद्बाहुनिष्क्रान्तः शरो वज्रनिभाननः।
प्रवेक्ष्यते ते हृदयं पद्ममंशुरिवार्कजः॥', 'adya madbāhuniṣkrāntaḥ śaro vajranibhānanaḥ
pravekṣyate te hṛdayaṃ padmam aṃśur ivārkajaḥ', null, 7061007),
('ramayana-7-61-8', 8, 'Uttara Kanda, Sarga 61, Verse 8', 'एवमुक्तो महावृक्षं लवणः क्रोधमूर्छितः।
शत्रुघ्नोरसि चिक्षेप तं शूरः शतधाच्छिनत्॥', 'evam ukto mahāvṛkṣaṃ lavaṇaḥ krodhamūrchitaḥ
śatrughnorasi cikṣepa taṃ śūraḥ śatadhācchinat', null, 7061008),
('ramayana-7-61-9', 9, 'Uttara Kanda, Sarga 61, Verse 9', 'तद्दृष्ट्वा विफलं कर्म राक्षसः पुनरेव तु।
पादपान्सुबहून्गृह्य शत्रुघ्ने व्यसृजद्बली॥', 'tad dṛṣṭvā viphalaṃ karma rākṣasaḥ punar eva tu
pādapān subahūn gṛhya śatrughne vyasṛjad balī', null, 7061009),
('ramayana-7-61-10', 10, 'Uttara Kanda, Sarga 61, Verse 10', 'शत्रुघ्नश्चापि तेजस्वी वृक्षानापततो बहून्।
त्रिभिश्चतुर्भिरेकैकं चिच्छेद नतपर्वभिः॥', 'śatrughnaś cāpi tejasvī vṛkṣān āpatato bahūn
tribhiś caturbhir ekaikaṃ ciccheda nataparvabhiḥ', null, 7061010),
('ramayana-7-61-11', 11, 'Uttara Kanda, Sarga 61, Verse 11', 'ततो बाणमयं वर्षं व्यसृजद्राक्षसोरसि।
शत्रुघ्नो वीर्यसंपन्नो विव्यथे न च राक्षसः॥', 'tato bāṇamayaṃ varṣaṃ vyasṛjad rākṣasor asi
śatrughno vīryasaṃpanno vivyathe na ca rākṣasaḥ', null, 7061011),
('ramayana-7-61-12', 12, 'Uttara Kanda, Sarga 61, Verse 12', 'ततः प्रहस्य लवणो वृक्षमुत्पाट्य लीलया।
शिरस्यभ्यहनच्छूरं स्रस्ताङ्गः स मुमोह वै॥', 'tataḥ prahasya lavaṇo vṛkṣam utpāṭya līlayā
śirasy abhyahanac chūraṃ srastāṅgaḥ sa mumoha vai', null, 7061012),
('ramayana-7-61-13', 13, 'Uttara Kanda, Sarga 61, Verse 13', 'तस्मिन्निपतिते वीरे हाहाकारो महानभूत्।
ऋषीणां देव संघानां गन्धर्वाप्सरसामपि॥', 'tasmin nipatite vīre hāhākāro mahān abhūt
ṛṣīṇāṃ deva saṃghānāṃ gandharvāpsarasām api', null, 7061013),
('ramayana-7-61-14', 14, 'Uttara Kanda, Sarga 61, Verse 14', 'तमवज्ञाय तु हतं शत्रुघ्नं भुवि पातितम्।
रक्षो लब्धान्तरमपि न विवेश स्वमालयम्॥', 'tam avajñāya tu hataṃ śatrughnaṃ bhuvi pātitam
rakṣo labdhāntaram api na viveśa svam ālayam', null, 7061014),
('ramayana-7-61-15', 15, 'Uttara Kanda, Sarga 61, Verse 15', 'नापि शूलं प्रजग्राह तं दृष्ट्वा भुवि पातितम्।
ततो हत इति ज्ञात्वा तान्भक्षान्समुदावहत्॥', 'nāpi śūlaṃ prajagrāha taṃ dṛṣṭvā bhuvi pātitam
tato hata iti jñātvā tān bhakṣān samudāvahat', null, 7061015),
('ramayana-7-61-16', 16, 'Uttara Kanda, Sarga 61, Verse 16', 'मुहूर्ताल्लब्धसंज्ञस्तु पुनस्तस्थौ धृतायुधः।
शत्रुघ्नो राक्षसद्वारि ऋषिभिः संप्रपूजितः॥', 'muhūrtāl labdhasaṃjñas tu punas tasthau dhṛtāyudhaḥ
śatrughno rākṣasadvāri ṛṣibhiḥ saṃprapūjitaḥ', null, 7061016),
('ramayana-7-61-17', 17, 'Uttara Kanda, Sarga 61, Verse 17', 'ततो दिव्यममोघं तं जग्राह शरमुत्तमम्।
ज्वलन्तं तेजसा घोरं पूरयन्तं दिशो दश॥', 'tato divyam amoghaṃ taṃ jagrāha śaram uttamam
jvalantaṃ tejasā ghoraṃ pūrayantaṃ diśo daśa', null, 7061017),
('ramayana-7-61-18', 18, 'Uttara Kanda, Sarga 61, Verse 18', 'वज्राननं वज्रवेगं मेरुमन्दर गौरवम्।
नतं पर्वसु सर्वेषु संयुगेष्वपराजितम्॥', 'vajrānanaṃ vajravegaṃ merumandara gauravam
nataṃ parvasu sarveṣu saṃyugeṣv aparājitam', null, 7061018),
('ramayana-7-61-19', 19, 'Uttara Kanda, Sarga 61, Verse 19', 'असृक्चन्दनदिग्धाङ्गं चारुपत्रं पतत्रिणम्।
दानवेन्द्राचलेन्द्राणामसुराणां च दारुणम्॥', 'asṛkcandanadigdhāṅgaṃ cārupatraṃ patatriṇam
dānavendrācalendrāṇām asurāṇāṃ ca dāruṇam', null, 7061019),
('ramayana-7-61-20', 20, 'Uttara Kanda, Sarga 61, Verse 20', 'तं दीप्तमिव कालाग्निं युगान्ते समुपस्थिते।
दृष्ट्वा सर्वाणि भूतानि परित्रासमुपागमन्॥', 'taṃ dīptam iva kālāgniṃ yugānte samupasthite
dṛṣṭvā sarvāṇi bhūtāni paritrāsam upāgaman', null, 7061020),
('ramayana-7-61-21', 21, 'Uttara Kanda, Sarga 61, Verse 21', 'सदेवासुरगन्धर्वं समुनिं साप्सरोगणम्।
जगद्धि सर्वमस्वस्थं पितामहमुपस्थितम्॥', 'sadevāsuragandharvaṃ samuniṃ sāpsarogaṇam
jagad dhi sarvam asvasthaṃ pitāmaham upasthitam', null, 7061021),
('ramayana-7-61-22', 22, 'Uttara Kanda, Sarga 61, Verse 22', 'ऊचुश्च देवदेवेशं वरदं प्रपितामहम्।
कच्चिल्लोकक्षयो देव प्राप्तो वा युगसंकयः॥', 'ūcuś ca devadeveśaṃ varadaṃ prapitāmaham
kaccil lokakṣayo deva prāpto vā yugasaṃkayaḥ', null, 7061022),
('ramayana-7-61-23', 23, 'Uttara Kanda, Sarga 61, Verse 23', 'नेदृशं दृष्टपूर्वं न श्रुतं वा प्रपितामह।
देवानां भयसंमोहो लोकानां संक्षयः प्रभो॥', 'nedṛśaṃ dṛṣṭapūrvaṃ na śrutaṃ vā prapitāmaha
devānāṃ bhayasaṃmoho lokānāṃ saṃkṣayaḥ prabho', null, 7061023),
('ramayana-7-61-24', 24, 'Uttara Kanda, Sarga 61, Verse 24', 'तेषां तद्वचनं श्रुत्वा ब्रह्मा लोकपितामनः।
भयकारणमाचष्टे देवानामभयंकरः॥', 'teṣāṃ tad vacanaṃ śrutvā brahmā lokapitāmanaḥ
bhayakāraṇam ācaṣṭe devānām abhayaṃkaraḥ', null, 7061024),
('ramayana-7-61-25', 25, 'Uttara Kanda, Sarga 61, Verse 25', 'वधाय लवणस्याजौ शरः शत्रुघ्नधारितः।
तेजसा यस्य सर्वे स्म संमूढाः सुरसत्तमाः॥', 'vadhāya lavaṇasyājau śaraḥ śatrughnadhāritaḥ
tejasā yasya sarve sma saṃmūḍhāḥ surasattamāḥ', null, 7061025),
('ramayana-7-61-26', 26, 'Uttara Kanda, Sarga 61, Verse 26', 'एषो हि पूर्वं देवस्य लोककर्तुः सनातनः।
शरस्तेजोमयो वत्सा येन वै भयमागतम्॥', 'eṣo hi pūrvaṃ devasya lokakartuḥ sanātanaḥ
śaras tejomayo vatsā yena vai bhayam āgatam', null, 7061026),
('ramayana-7-61-27', 27, 'Uttara Kanda, Sarga 61, Verse 27', 'एष वै कैटभस्यार्थे मधुनश्च महाशरः।
सृष्टो महात्मना तेन वधार्थं दैत्ययोस्तयोः॥', 'eṣa vai kaiṭabhasyārthe madhunaś ca mahāśaraḥ
sṛṣṭo mahātmanā tena vadhārthaṃ daityayos tayoḥ', null, 7061027),
('ramayana-7-61-28', 28, 'Uttara Kanda, Sarga 61, Verse 28', 'एवमेतं प्रजानीध्वं विष्णोस्तेजोमयं शरम्।
एषा चैव तनुः पूर्वा विष्णोस्तस्य महात्मनः॥', 'evam etaṃ prajānīdhvaṃ viṣṇos tejomayaṃ śaram
eṣā caiva tanuḥ pūrvā viṣṇos tasya mahātmanaḥ', null, 7061028),
('ramayana-7-61-29', 29, 'Uttara Kanda, Sarga 61, Verse 29', 'इतो गच्छता पश्यध्वं वध्यमानं महात्मना।
रामानुजेन वीरेण लवणं राक्षसोत्तमम्॥', 'ito gacchatā paśyadhvaṃ vadhyamānaṃ mahātmanā
rāmānujena vīreṇa lavaṇaṃ rākṣasottamam', null, 7061029),
('ramayana-7-61-30', 30, 'Uttara Kanda, Sarga 61, Verse 30', 'तस्य ते देवदेवस्य निशम्य मधुरां गिरम्।
आजग्मुर्यत्र युध्येते शत्रुघ्नलवणावुभौ॥', 'tasya te devadevasya niśamya madhurāṃ giram
ājagmur yatra yudhyete śatrughnalavaṇāv ubhau', null, 7061030),
('ramayana-7-61-31', 31, 'Uttara Kanda, Sarga 61, Verse 31', 'तं शरं दिव्यसंकाशं शत्रुघ्नकरधारितम्।
ददृशुः सर्वभूतानि युगान्ताग्निमिवोत्थितम्॥', 'taṃ śaraṃ divyasaṃkāśaṃ śatrughnakaradhāritam
dadṛśuḥ sarvabhūtāni yugāntāgnim ivotthitam', null, 7061031),
('ramayana-7-61-32', 32, 'Uttara Kanda, Sarga 61, Verse 32', 'आकाशमावृतं दृष्ट्वा देवैर्हि रघुनन्दनः।
सिंहनादं मुहुः कृत्वा ददर्श लवणं पुनः॥', 'ākāśam āvṛtaṃ dṛṣṭvā devair hi raghunandanaḥ
siṃhanādaṃ muhuḥ kṛtvā dadarśa lavaṇaṃ punaḥ', null, 7061032),
('ramayana-7-61-33', 33, 'Uttara Kanda, Sarga 61, Verse 33', 'आहूतश्च ततस्तेन शत्रुघ्नेन महात्मना।
लवणः क्रोधसंयुक्तो युद्धाय समुपस्थितः॥', 'āhūtaś ca tatas tena śatrughnena mahātmanā
lavaṇaḥ krodhasaṃyukto yuddhāya samupasthitaḥ', null, 7061033),
('ramayana-7-61-34', 34, 'Uttara Kanda, Sarga 61, Verse 34', 'आकर्णात्स विकृष्याथ तद्धनुर्धन्विनां वरः।
स मुमोच महाबाणं लवणस्य महोरसि।
उरस्तस्य विदार्याशु प्रविवेश रसातलम्॥', 'ākarṇāt sa vikṛṣyātha tad dhanur dhanvināṃ varaḥ
sa mumoca mahābāṇaṃ lavaṇasya mahorasi
uras tasya vidāryāśu praviveśa rasātalam', null, 7061034),
('ramayana-7-61-35', 35, 'Uttara Kanda, Sarga 61, Verse 35', 'गत्वा रसातलं दिव्यं शरो विबुधपूजितः।
पुनरेवागमत्तूर्णमिक्ष्वाकुकुलनन्दनम्॥', 'gatvā rasātalaṃ divyaṃ śaro vibudhapūjitaḥ
punar evāgamat tūrṇam ikṣvākukulanandanam', null, 7061035),
('ramayana-7-61-36', 36, 'Uttara Kanda, Sarga 61, Verse 36', 'शत्रुघ्नशरनिर्भिन्नो लवणः स निशाचरः।
पपात सहसा भूमौ वज्राहत इवाचलः॥', 'śatrughnaśaranirbhinno lavaṇaḥ sa niśācaraḥ
papāta sahasā bhūmau vajrāhata ivācalaḥ', null, 7061036),
('ramayana-7-61-37', 37, 'Uttara Kanda, Sarga 61, Verse 37', 'तच्च दिव्यं महच्छूलं हते लवणराक्षसे।
पश्यतां सर्वभूतानां रुद्रस्य वशमन्वगात्॥', 'tac ca divyaṃ mahac chūlaṃ hate lavaṇarākṣase
paśyatāṃ sarvabhūtānāṃ rudrasya vaśam anvagāt', null, 7061037),
('ramayana-7-61-38', 38, 'Uttara Kanda, Sarga 61, Verse 38', 'एकेषुपातेन भयं निहत्य लोकत्रयस्यास्य रघुप्रवीरः।
विनिर्बभावुद्यतचापबाणस्तमः प्रणुद्येव सहस्ररश्मिः॥', 'ekeṣupātena bhayaṃ nihatya lokatrayasyāsya raghupravīraḥ
vinirbabhāv udyatacāpabāṇas tamaḥ praṇudyeva sahasraraśmiḥ', null, 7061038)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 62 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-62-1', 1, 'Uttara Kanda, Sarga 62, Verse 1', 'हते तु लवणे देवाः सेन्द्राः साग्निपुरोगमाः।
ऊचुः सुमधुरां वाणीं शत्रुघ्नां शत्रुतापनम्॥', 'hate tu lavaṇe devāḥ sendrāḥ sāgnipurogamāḥ
ūcuḥ sumadhurāṃ vāṇīṃ śatrughnāṃ śatrutāpanam', null, 7062001),
('ramayana-7-62-2', 2, 'Uttara Kanda, Sarga 62, Verse 2', 'दिष्ट्या ते विजयो वत्स दिष्ट्य लवणराक्षसः।
हतः पुरुषशार्दूलवरं वरय राघव॥', 'diṣṭyā te vijayo vatsa diṣṭya lavaṇarākṣasaḥ
hataḥ puruṣaśārdūlavaraṃ varaya rāghava', null, 7062002),
('ramayana-7-62-3', 3, 'Uttara Kanda, Sarga 62, Verse 3', 'वरदाः स्म महाबाहो सर्व एव समागताः।
विजयाकाङ्क्षिणस्तुभ्यममोघं दर्शनं हि नः॥', 'varadāḥ sma mahābāho sarva eva samāgatāḥ
vijayākāṅkṣiṇas tubhyam amoghaṃ darśanaṃ hi naḥ', null, 7062003),
('ramayana-7-62-4', 4, 'Uttara Kanda, Sarga 62, Verse 4', 'देवानां भाषितं श्रुत्वा शूरो मूर्ध्नि कृताञ्जलिः।
प्रत्युवाच महाबाहुः शत्रुघ्नः प्रयतात्मवान्॥', 'devānāṃ bhāṣitaṃ śrutvā śūro mūrdhni kṛtāñjaliḥ
pratyuvāca mahābāhuḥ śatrughnaḥ prayatātmavān', null, 7062004),
('ramayana-7-62-5', 5, 'Uttara Kanda, Sarga 62, Verse 5', 'इमां मधुपुरीं रम्यां मधुरां देव निर्मिताम्।
निवेशं प्रप्नुयां शीघ्रमेष मेऽस्तु वरो मतः॥', 'imāṃ madhupurīṃ ramyāṃ madhurāṃ deva nirmitām
niveśaṃ prapnuyāṃ śīghram eṣa me ''stu varo mataḥ', null, 7062005),
('ramayana-7-62-6', 6, 'Uttara Kanda, Sarga 62, Verse 6', 'तं देवाः प्रीतमनसो बाढमित्येव राघवम्।
भविष्यति पुरी रम्या शूरसेना न संशयः॥', 'taṃ devāḥ prītamanaso bāḍham ity eva rāghavam
bhaviṣyati purī ramyā śūrasenā na saṃśayaḥ', null, 7062006),
('ramayana-7-62-7', 7, 'Uttara Kanda, Sarga 62, Verse 7', 'ते तथोक्त्वा महात्मानो दिवमारुरुहुस्तदा।
शत्रुघ्नोऽपि महातेजास्तां सेनां समुपानयत्॥', 'te tathoktvā mahātmāno divam āruruhus tadā
śatrughno ''pi mahātejās tāṃ senāṃ samupānayat', null, 7062007),
('ramayana-7-62-8', 8, 'Uttara Kanda, Sarga 62, Verse 8', 'सा सेन शीघ्रमागच्छच्छ्रुत्वा शत्रुघ्नशासनम्।
निवेशनं च शत्रुघ्नः शासनेन समारभत्॥', 'sā sena śīghram āgacchac chrutvā śatrughnaśāsanam
niveśanaṃ ca śatrughnaḥ śāsanena samārabhat', null, 7062008),
('ramayana-7-62-9', 9, 'Uttara Kanda, Sarga 62, Verse 9', 'सा पुरी दिव्यसंकाशा वर्षे द्वादशमे शुभा।
निविष्टा शूरसेनानां विषयश्चाकुतोभयः॥', 'sā purī divyasaṃkāśā varṣe dvādaśame śubhā
niviṣṭā śūrasenānāṃ viṣayaś cākutobhayaḥ', null, 7062009),
('ramayana-7-62-10', 10, 'Uttara Kanda, Sarga 62, Verse 10', 'क्षेत्राणि सस्य युक्तानि काले वर्षति वासवः।
अरोगा वीरपुरुषा शत्रुघ्नभुजपालिता॥', 'kṣetrāṇi sasya yuktāni kāle varṣati vāsavaḥ
arogā vīrapuruṣā śatrughnabhujapālitā', null, 7062010),
('ramayana-7-62-11', 11, 'Uttara Kanda, Sarga 62, Verse 11', 'अर्धचन्द्रप्रतीकाशा यमुनातीरशोभिता।
शोभिता गृहमुख्यैश्च शोभिता चत्वरापणैः॥', 'ardhacandrapratīkāśā yamunātīraśobhitā
śobhitā gṛhamukhyaiś ca śobhitā catvarāpaṇaiḥ', null, 7062011),
('ramayana-7-62-12', 12, 'Uttara Kanda, Sarga 62, Verse 12', 'यच्च तेन महच्छून्यं लवणेन कृतं पुरा।
शोभयामास तद्वीरो नानापण्यसमृद्धिभिः॥', 'yac ca tena mahac chūnyaṃ lavaṇena kṛtaṃ purā
śobhayām āsa tad vīro nānāpaṇyasamṛddhibhiḥ', null, 7062012),
('ramayana-7-62-13', 13, 'Uttara Kanda, Sarga 62, Verse 13', 'तां समृद्धां समृद्धार्थः शत्रुघ्नो भरतानुजः।
निरीक्ष्य परमप्रीतः परं हर्षमुपागमत्॥', 'tāṃ samṛddhāṃ samṛddhārthaḥ śatrughno bharatānujaḥ
nirīkṣya paramaprītaḥ paraṃ harṣam upāgamat', null, 7062013),
('ramayana-7-62-14', 14, 'Uttara Kanda, Sarga 62, Verse 14', 'तस्य बुद्धिः समुत्पन्ना निवेश्य मधुरां पुरीम्।
रामपादौ निरीक्षेयं वर्षे द्वादशमे शुभे॥', 'tasya buddhiḥ samutpannā niveśya madhurāṃ purīm
rāmapādau nirīkṣeyaṃ varṣe dvādaśame śubhe', null, 7062014)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 63 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-63-1', 1, 'Uttara Kanda, Sarga 63, Verse 1', 'ततो द्वादशमे वर्षे शत्रुघ्नो रामपालिताम्।
अयोध्यां चकमे गन्तुमल्पभृत्यबलानुगः॥', 'tato dvādaśame varṣe śatrughno rāmapālitām
ayodhyāṃ cakame gantum alpabhṛtyabalānugaḥ', null, 7063001),
('ramayana-7-63-2', 2, 'Uttara Kanda, Sarga 63, Verse 2', 'मन्त्रिणो बलमुख्यांश्च निवर्त्य च पुरोधसं।
जगाम रथमुख्येन हययुक्तेन भास्वता॥', 'mantriṇo balamukhyāṃś ca nivartya ca purodhasaṃ
jagāma rathamukhyena hayayuktena bhāsvatā', null, 7063002),
('ramayana-7-63-3', 3, 'Uttara Kanda, Sarga 63, Verse 3', 'स गत्वा गणितान्वासान्सप्ताष्टौ रघुनन्दनः।
अयोध्यामगमत्तूर्णं राघवोत्सुकदर्शनः॥', 'sa gatvā gaṇitān vāsān saptāṣṭau raghunandanaḥ
ayodhyām agamat tūrṇaṃ rāghavotsukadarśanaḥ', null, 7063003),
('ramayana-7-63-4', 4, 'Uttara Kanda, Sarga 63, Verse 4', 'स प्रविश्य पुरीं रम्यां श्रीमानिक्ष्वाकुनन्दनः।
प्रविवेश महाबाहुर्यत्र रामो महाद्युतिः॥', 'sa praviśya purīṃ ramyāṃ śrīmān ikṣvākunandanaḥ
praviveśa mahābāhur yatra rāmo mahādyutiḥ', null, 7063004),
('ramayana-7-63-5', 5, 'Uttara Kanda, Sarga 63, Verse 5', 'सोऽभिवाद्य महात्मानं ज्वलन्तमिव तेजसा।
उवाच प्राञ्जलिर्भूत्वा रामं सत्यपराक्रमम्॥', 'so ''bhivādya mahātmānaṃ jvalantam iva tejasā
uvāca prāñjalir bhūtvā rāmaṃ satyaparākramam', null, 7063005),
('ramayana-7-63-6', 6, 'Uttara Kanda, Sarga 63, Verse 6', 'यदाज्ञप्तं महाराज सर्वं तत्कृतवानहम्।
हतः स लवणः पापः पुरी सा च निवेशिता॥', 'yad ājñaptaṃ mahārāja sarvaṃ tat kṛtavān aham
hataḥ sa lavaṇaḥ pāpaḥ purī sā ca niveśitā', null, 7063006),
('ramayana-7-63-7', 7, 'Uttara Kanda, Sarga 63, Verse 7', 'द्वादशं च गतं वर्षं त्वां विना रघुनन्दन।
नोत्सहेयमहं वस्तुं त्वया विरहितो नृप॥', 'dvādaśaṃ ca gataṃ varṣaṃ tvāṃ vinā raghunandana
notsaheyam ahaṃ vastuṃ tvayā virahito nṛpa', null, 7063007),
('ramayana-7-63-8', 8, 'Uttara Kanda, Sarga 63, Verse 8', 'स मे प्रसादं काकुत्स्थ कुरुष्वामितविक्रम।
मातृहीनो यथा वत्सस्त्वां विना प्रवसाम्यहम्॥', 'sa me prasādaṃ kākutstha kuruṣvāmitavikrama
mātṛhīno yathā vatsas tvāṃ vinā pravasāmy aham', null, 7063008),
('ramayana-7-63-9', 9, 'Uttara Kanda, Sarga 63, Verse 9', 'एवं ब्रुवाणं शत्रुघ्नं परिष्वज्येदमब्रवीत्।
मा विषादं कृथा वीर नैतत्क्षत्रिय चेष्टितम्॥', 'evaṃ bruvāṇaṃ śatrughnaṃ pariṣvajyedam abravīt
mā viṣādaṃ kṛthā vīra naitat kṣatriya ceṣṭitam', null, 7063009),
('ramayana-7-63-10', 10, 'Uttara Kanda, Sarga 63, Verse 10', 'नावसीदन्ति राजानो विप्रवासेषु राघव।
प्रजाश्च परिपाल्या हि क्षत्रधर्मेण राघव॥', 'nāvasīdanti rājāno vipravāseṣu rāghava
prajāś ca paripālyā hi kṣatradharmeṇa rāghava', null, 7063010),
('ramayana-7-63-11', 11, 'Uttara Kanda, Sarga 63, Verse 11', 'काले काले च मां वीर अयोध्यामवलोकितुम्।
आगच्छ त्वं नरश्रेष्ठ गन्तासि च पुरं तव॥', 'kāle kāle ca māṃ vīra ayodhyām avalokitum
āgaccha tvaṃ naraśreṣṭha gantāsi ca puraṃ tava', null, 7063011),
('ramayana-7-63-12', 12, 'Uttara Kanda, Sarga 63, Verse 12', 'ममापि त्वं सुदयितः प्राणैरपि न संशयः।
अवश्यं करणीयं च राज्यस्य परिपालनम्॥', 'mamāpi tvaṃ sudayitaḥ prāṇair api na saṃśayaḥ
avaśyaṃ karaṇīyaṃ ca rājyasya paripālanam', null, 7063012),
('ramayana-7-63-13', 13, 'Uttara Kanda, Sarga 63, Verse 13', 'तस्मात्त्वं वस काकुत्स्थ पञ्चरात्रं मया सह।
ऊर्ध्वं गन्तासि मधुरां सभृत्यबलवाहनः॥', 'tasmāt tvaṃ vasa kākutstha pañcarātraṃ mayā saha
ūrdhvaṃ gantāsi madhurāṃ sabhṛtyabalavāhanaḥ', null, 7063013),
('ramayana-7-63-14', 14, 'Uttara Kanda, Sarga 63, Verse 14', 'रामस्यैतद्वचः श्रुत्वा धर्मयुक्तं मनोऽनुगम्।
शत्रुघ्नो दीनया वाचा बाढमित्येव चाब्रवीत्॥', 'rāmasyaitad vacaḥ śrutvā dharmayuktaṃ mano''nugam
śatrughno dīnayā vācā bāḍham ity eva cābravīt', null, 7063014),
('ramayana-7-63-15', 15, 'Uttara Kanda, Sarga 63, Verse 15', 'स पञ्चरात्रं काकुत्स्थो राघवस्य यथाज्ञया।
उष्य तत्र महेष्वासो गमनायोपचक्रमे॥', 'sa pañcarātraṃ kākutstho rāghavasya yathājñayā
uṣya tatra maheṣvāso gamanāyopacakrame', null, 7063015),
('ramayana-7-63-16', 16, 'Uttara Kanda, Sarga 63, Verse 16', 'आमन्त्र्य तु महात्मानं रामं सत्यपराक्रमम्।
भरतं लक्ष्मणं चैव महारथमुपारुहत्॥', 'āmantrya tu mahātmānaṃ rāmaṃ satyaparākramam
bharataṃ lakṣmaṇaṃ caiva mahāratham upāruhat', null, 7063016),
('ramayana-7-63-17', 17, 'Uttara Kanda, Sarga 63, Verse 17', 'दूरं ताभ्यामनुगतो लक्ष्मणेन महात्मना।
भरतेन च शत्रुघ्नो जगामाशु पुरीं तदा॥', 'dūraṃ tābhyām anugato lakṣmaṇena mahātmanā
bharatena ca śatrughno jagāmāśu purīṃ tadā', null, 7063017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 64 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-64-1', 1, 'Uttara Kanda, Sarga 64, Verse 1', 'प्रस्थाप्य तु स शत्रुघ्नं भ्रातृभ्यां सह राघवः।
प्रमुमोद सुखी राज्यं धर्मेण परिपालयन्॥', 'prasthāpya tu sa śatrughnaṃ bhrātṛbhyāṃ saha rāghavaḥ
pramumoda sukhī rājyaṃ dharmeṇa paripālayan', null, 7064001),
('ramayana-7-64-2', 2, 'Uttara Kanda, Sarga 64, Verse 2', 'ततः कतिपयाहःसु वृद्धो जानपदो द्विजः।
शवं बालमुपादाय राजद्वारमुपागमत्॥', 'tataḥ katipayāhaḥsu vṛddho jānapado dvijaḥ
śavaṃ bālam upādāya rājadvāram upāgamat', null, 7064002),
('ramayana-7-64-3', 3, 'Uttara Kanda, Sarga 64, Verse 3', 'रुदन्बहुविधा वाचः स्नेहाक्षरसमन्विताः।
असकृत्पुत्रपुत्रेति वाक्यमेतदुवाच ह॥', 'rudan bahuvidhā vācaḥ snehākṣarasamanvitāḥ
asakṛt putraputreti vākyam etad uvāca ha', null, 7064003),
('ramayana-7-64-4', 4, 'Uttara Kanda, Sarga 64, Verse 4', 'किं नु मे दुष्कृतं कर्म पूर्वं देहान्तरे कृतम्।
यदहं पुत्रमेकं त्वां पश्यामि निधनं गतम्॥', 'kiṃ nu me duṣkṛtaṃ karma pūrvaṃ dehāntare kṛtam
yad ahaṃ putram ekaṃ tvāṃ paśyāmi nidhanaṃ gatam', null, 7064004),
('ramayana-7-64-5', 5, 'Uttara Kanda, Sarga 64, Verse 5', 'अप्राप्तयौवनं बालं पञ्चवर्षसमन्वितम्।
अकाले कालमापन्नं दुःखाय मम पुत्रक॥', 'aprāptayauvanaṃ bālaṃ pañcavarṣasamanvitam
akāle kālam āpannaṃ duḥkhāya mama putraka', null, 7064005),
('ramayana-7-64-6', 6, 'Uttara Kanda, Sarga 64, Verse 6', 'अल्पैरहोभिर्निधनं गमिष्यामि न संशयः।
अहं च जननी चैव तव शोकेन पुत्रक॥', 'alpair ahobhir nidhanaṃ gamiṣyāmi na saṃśayaḥ
ahaṃ ca jananī caiva tava śokena putraka', null, 7064006),
('ramayana-7-64-7', 7, 'Uttara Kanda, Sarga 64, Verse 7', 'न स्मराम्यनृतं ह्युक्तं न च हिंसां स्मराम्यहम्।
केन मे दुष्कृतेनाद्य बाल एव ममात्मजः।
अकृत्वा पितृकार्याणि नीतो वैवस्वतक्षयम्॥', 'na smarāmy anṛtaṃ hy uktaṃ na ca hiṃsāṃ smarāmy aham
kena me duṣkṛtenādya bāla eva mamātmajaḥ
akṛtvā pitṛkāryāṇi nīto vaivasvatakṣayam', null, 7064007),
('ramayana-7-64-8', 8, 'Uttara Kanda, Sarga 64, Verse 8', 'नेदृशं दृष्टपूर्वं मे श्रुतं वा घोरदर्शनम्।
मृत्युरप्राप्तकालानां रामस्य विषये यथा॥', 'nedṛśaṃ dṛṣṭapūrvaṃ me śrutaṃ vā ghoradarśanam
mṛtyur aprāptakālānāṃ rāmasya viṣaye yathā', null, 7064008),
('ramayana-7-64-9', 9, 'Uttara Kanda, Sarga 64, Verse 9', 'रामस्य दुष्कृतं किं चिन्महदस्ति न संशयः।
त्वं राजञ्जीवयस्वैनं बालं मृत्युवशं गतम्॥', 'rāmasya duṣkṛtaṃ kiṃ cin mahad asti na saṃśayaḥ
tvaṃ rājañ jīvayasvainaṃ bālaṃ mṛtyuvaśaṃ gatam', null, 7064009),
('ramayana-7-64-10', 10, 'Uttara Kanda, Sarga 64, Verse 10', 'भ्रातृभिः सहितो राजन्दीर्घमायुरवाप्नुहि।
उषिताः स्म सुखं राज्ये तवास्मिन्सुमहाबल॥', 'bhrātṛbhiḥ sahito rājan dīrgham āyur avāpnuhi
uṣitāḥ sma sukhaṃ rājye tavāsmin sumahābala', null, 7064010),
('ramayana-7-64-11', 11, 'Uttara Kanda, Sarga 64, Verse 11', 'संप्रत्यनाथो विषय इक्ष्वाकूणां महात्मनाम्।
रामं नाथमिहासाद्य बालान्तकरणं नृपम्॥', 'saṃpraty anātho viṣaya ikṣvākūṇāṃ mahātmanām
rāmaṃ nātham ihāsādya bālāntakaraṇaṃ nṛpam', null, 7064011),
('ramayana-7-64-12', 12, 'Uttara Kanda, Sarga 64, Verse 12', 'राजदोषैर्विपद्यन्ते प्रजा ह्यविधिपालिताः।
असद्वृत्ते तु नृपतावकाले म्रियते जनः॥', 'rājadoṣair vipadyante prajā hy avidhipālitāḥ
asadvṛtte tu nṛpatāv akāle mriyate janaḥ', null, 7064012),
('ramayana-7-64-13', 13, 'Uttara Kanda, Sarga 64, Verse 13', 'यदा पुरेष्वयुक्तानि जना जनपदेशु च।
कुर्वते न च रक्षास्ति तदाकालकृतं भयम्॥', 'yadā pureṣv ayuktāni janā janapadeśu ca
kurvate na ca rakṣāsti tadākālakṛtaṃ bhayam', null, 7064013),
('ramayana-7-64-14', 14, 'Uttara Kanda, Sarga 64, Verse 14', 'सव्यक्तं राजदोषोऽयं भविष्यति न संशयः।
पुरे जनपदे वापि तदा बालवधो ह्ययम्॥', 'savyaktaṃ rājadoṣo ''yaṃ bhaviṣyati na saṃśayaḥ
pure janapade vāpi tadā bālavadho hy ayam', null, 7064014),
('ramayana-7-64-15', 15, 'Uttara Kanda, Sarga 64, Verse 15', 'एवं बहुविधैर्वाक्यैर्निन्दयानो मुहुर्मुहुः।
राजानं दुःखसंतप्तः सुतं तमुपगूहति॥', 'evaṃ bahuvidhair vākyair nindayāno muhur muhuḥ
rājānaṃ duḥkhasaṃtaptaḥ sutaṃ tam upagūhati', null, 7064015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 65 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-65-1', 1, 'Uttara Kanda, Sarga 65, Verse 1', 'तथा तु करुणं तस्य द्विजस्य परिदेवितम्।
शुश्राव राघवः सर्वं दुःखशोकसमन्वितम्॥', 'tathā tu karuṇaṃ tasya dvijasya paridevitam
śuśrāva rāghavaḥ sarvaṃ duḥkhaśokasamanvitam', null, 7065001),
('ramayana-7-65-2', 2, 'Uttara Kanda, Sarga 65, Verse 2', 'स दुःखेन सुसंतप्तो मन्त्रिणः समुपाह्वयत्।
वसिष्ठं वामदेवं च भ्रातॄंश्च सहनैगमान्॥', 'sa duḥkhena susaṃtapto mantriṇaḥ samupāhvayat
vasiṣṭhaṃ vāmadevaṃ ca bhrātṝṃś ca sahanaigamān', null, 7065002),
('ramayana-7-65-3', 3, 'Uttara Kanda, Sarga 65, Verse 3', 'ततो द्विजा वसिष्ठेन सार्धमष्टौ प्रवेशिताः।
राजानं देवसंकाशं वर्धस्वेति ततोऽब्रुवन्॥', 'tato dvijā vasiṣṭhena sārdham aṣṭau praveśitāḥ
rājānaṃ devasaṃkāśaṃ vardhasveti tato ''bruvan', null, 7065003),
('ramayana-7-65-4', 4, 'Uttara Kanda, Sarga 65, Verse 4', 'मार्कण्डेयोऽथ मौद्गल्यो वामदेवश्च काश्यपः।
कात्यायनोऽथ जाबालिर्गौतमो नारदस्तथा॥', 'mārkaṇḍeyo ''tha maudgalyo vāmadevaś ca kāśyapaḥ
kātyāyano ''tha jābālir gautamo nāradas tathā', null, 7065004),
('ramayana-7-65-5', 5, 'Uttara Kanda, Sarga 65, Verse 5', 'एते द्विजर्षभाः सर्वे आगनेषूपवेशिताः।
मन्त्रिणो नैगमाश्चैव यथार्हमनुकूलतः॥', 'ete dvijarṣabhāḥ sarve āganeṣūpaveśitāḥ
mantriṇo naigamāś caiva yathārham anukūlataḥ', null, 7065005),
('ramayana-7-65-6', 6, 'Uttara Kanda, Sarga 65, Verse 6', 'तेषां समुपविष्टानां सर्वेषां दीप्ततेजसाम्।
रघवः सर्वमाचष्टे द्विजो यस्मात्प्ररोदिति॥', 'teṣāṃ samupaviṣṭānāṃ sarveṣāṃ dīptatejasām
raghavaḥ sarvam ācaṣṭe dvijo yasmāt praroditi', null, 7065006),
('ramayana-7-65-7', 7, 'Uttara Kanda, Sarga 65, Verse 7', 'तस्य तद्वचनं श्रुत्वा राज्ञो दीनस्य नारदः।
प्रत्युवाच शुभं वाक्यमृषीणां संनिधौ नृपम्॥', 'tasya tad vacanaṃ śrutvā rājño dīnasya nāradaḥ
pratyuvāca śubhaṃ vākyam ṛṣīṇāṃ saṃnidhau nṛpam', null, 7065007),
('ramayana-7-65-8', 8, 'Uttara Kanda, Sarga 65, Verse 8', 'शृणु राजन्यथाकाले प्राप्तोऽयं बालसंक्षयः।
श्रुत्वा कर्तव्यतां वीर कुरुष्व रघुनन्दन॥', 'śṛṇu rājan yathākāle prāpto ''yaṃ bālasaṃkṣayaḥ
śrutvā kartavyatāṃ vīra kuruṣva raghunandana', null, 7065008),
('ramayana-7-65-9', 9, 'Uttara Kanda, Sarga 65, Verse 9', 'पुरा कृतयुगे राम ब्राह्मणा वै तपस्विनः।
अब्राह्मणस्तदा राजन्न तपस्वी कथं चन॥', 'purā kṛtayuge rāma brāhmaṇā vai tapasvinaḥ
abrāhmaṇas tadā rājan na tapasvī kathaṃ cana', null, 7065009),
('ramayana-7-65-10', 10, 'Uttara Kanda, Sarga 65, Verse 10', 'तस्मिन्युगे प्रज्वलिते ब्रह्मभूते अनावृते।
अमृत्यवस्तदा सर्वे जज्ञिरे दीर्घदर्शिनः॥', 'tasmin yuge prajvalite brahmabhūte anāvṛte
amṛtyavas tadā sarve jajñire dīrghadarśinaḥ', null, 7065010),
('ramayana-7-65-11', 11, 'Uttara Kanda, Sarga 65, Verse 11', 'ततस्त्रेतायुगं नाम मानवानां वपुष्मताम्।
क्षत्रिया यत्र जायन्ते पूर्वेण तपसान्विताः॥', 'tatas tretāyugaṃ nāma mānavānāṃ vapuṣmatām
kṣatriyā yatra jāyante pūrveṇa tapasānvitāḥ', null, 7065011),
('ramayana-7-65-12', 12, 'Uttara Kanda, Sarga 65, Verse 12', 'वीर्येण तपसा चैव तेऽधिकाः पूर्वजन्मनि।
मानवा ये महात्मानस्तस्मिंस्त्रेतायुगे युगे॥', 'vīryeṇa tapasā caiva te ''dhikāḥ pūrvajanmani
mānavā ye mahātmānas tasmiṃs tretāyuge yuge', null, 7065012),
('ramayana-7-65-13', 13, 'Uttara Kanda, Sarga 65, Verse 13', 'ब्रह्मक्षत्रं तु तत्सर्वं यत्पूर्वमपरं च यत्।
युगयोरुभयोरासीत्समवीर्यसमन्वितम्॥', 'brahmakṣatraṃ tu tat sarvaṃ yat pūrvam aparaṃ ca yat
yugayor ubhayor āsīt samavīryasamanvitam', null, 7065013),
('ramayana-7-65-14', 14, 'Uttara Kanda, Sarga 65, Verse 14', 'अपश्यन्तस्तु ते सर्वे विशेषमधिकं ततः।
स्थापनं चक्रिरे तत्र चातुर्वर्ण्यस्य सर्वतः॥', 'apaśyantas tu te sarve viśeṣam adhikaṃ tataḥ
sthāpanaṃ cakrire tatra cāturvarṇyasya sarvataḥ', null, 7065014),
('ramayana-7-65-15', 15, 'Uttara Kanda, Sarga 65, Verse 15', 'अधर्मः पादमेकं तु पातयत्पृथिवीतले।
अधर्मेण हि संयुक्तास्तेन मन्दाभवन्द्विजाः॥', 'adharmaḥ pādam ekaṃ tu pātayat pṛthivītale
adharmeṇa hi saṃyuktās tena mandābhavan dvijāḥ', null, 7065015),
('ramayana-7-65-16', 16, 'Uttara Kanda, Sarga 65, Verse 16', 'ततः प्रादुष्कृतं पूर्वमायुषः परिनिष्ठितम्।
शुभान्येवाचरंल्लोकाः सत्यधर्मपरायणाः॥', 'tataḥ prāduṣkṛtaṃ pūrvam āyuṣaḥ pariniṣṭhitam
śubhāny evācaraṃl lokāḥ satyadharmaparāyaṇāḥ', null, 7065016),
('ramayana-7-65-17', 17, 'Uttara Kanda, Sarga 65, Verse 17', 'त्रेतायुगे त्ववर्तन्त ब्राह्मणाः क्षत्रियश्च ये।
तपोऽतप्यन्त ते सर्वे शुश्रूषामपरे जनाः॥', 'tretāyuge tv avartanta brāhmaṇāḥ kṣatriyaś ca ye
tapo ''tapyanta te sarve śuśrūṣām apare janāḥ', null, 7065017),
('ramayana-7-65-18', 18, 'Uttara Kanda, Sarga 65, Verse 18', 'स धर्मः परमस्तेषां वैश्यशूद्रमथागमत्।
पूजां च सर्ववर्णानां शूद्राश्चक्रुर्विशेषतः॥', 'sa dharmaḥ paramas teṣāṃ vaiśyaśūdram athāgamat
pūjāṃ ca sarvavarṇānāṃ śūdrāś cakrur viśeṣataḥ', null, 7065018),
('ramayana-7-65-19', 19, 'Uttara Kanda, Sarga 65, Verse 19', 'ततः पादमधर्मस्य द्वितीयमवतारयत्।
ततो द्वापरसंख्या सा युगस्य समजायत॥', 'tataḥ pādam adharmasya dvitīyam avatārayat
tato dvāparasaṃkhyā sā yugasya samajāyata', null, 7065019),
('ramayana-7-65-20', 20, 'Uttara Kanda, Sarga 65, Verse 20', 'तस्मिन्द्वापरसंख्ये तु वर्तमाने युगक्षये।
अधर्मश्चानृतं चैव ववृधे पुरुषर्षभ॥', 'tasmin dvāparasaṃkhye tu vartamāne yugakṣaye
adharmaś cānṛtaṃ caiva vavṛdhe puruṣarṣabha', null, 7065020),
('ramayana-7-65-21', 21, 'Uttara Kanda, Sarga 65, Verse 21', 'तस्मिन्द्वापरसंख्याते तपो वैश्यान्समाविशत्।
न शूद्रो लभते धर्ममुग्रं तप्तं नरर्षभ॥', 'tasmin dvāparasaṃkhyāte tapo vaiśyān samāviśat
na śūdro labhate dharmam ugraṃ taptaṃ nararṣabha', null, 7065021),
('ramayana-7-65-22', 22, 'Uttara Kanda, Sarga 65, Verse 22', 'हीनवर्णो नरश्रेष्ठ तप्यते सुमहत्तपः।
भविष्या शूद्रयोन्यां हि तपश्चर्या कलौ युगे॥', 'hīnavarṇo naraśreṣṭha tapyate sumahat tapaḥ
bhaviṣyā śūdrayonyāṃ hi tapaścaryā kalau yuge', null, 7065022),
('ramayana-7-65-23', 23, 'Uttara Kanda, Sarga 65, Verse 23', 'अधर्मः परमो राम द्वापरे शूद्रधारितः।
स वै विषयपर्यन्ते तव राजन्महातपाः।
शूद्रस्तप्यति दुर्बुद्धिस्तेन बालवधो ह्ययम्॥', 'adharmaḥ paramo rāma dvāpare śūdradhāritaḥ
sa vai viṣayaparyante tava rājan mahātapāḥ
śūdras tapyati durbuddhis tena bālavadho hy ayam', null, 7065023),
('ramayana-7-65-24', 24, 'Uttara Kanda, Sarga 65, Verse 24', 'यो ह्यधर्ममकार्यं वा विषये पार्थिवस्य हि।
करोति राजशार्दूल पुरे वा दुर्मतिर्नरः।
क्षिप्रं हि नरकं याति स च राजा न संशयः॥', 'yo hy adharmam akāryaṃ vā viṣaye pārthivasya hi
karoti rājaśārdūla pure vā durmatir naraḥ
kṣipraṃ hi narakaṃ yāti sa ca rājā na saṃśayaḥ', null, 7065024),
('ramayana-7-65-25', 25, 'Uttara Kanda, Sarga 65, Verse 25', 'स त्वं पुरुषशार्दूल मार्गस्व विषयं स्वकम्।
दुष्कृतं यत्र पश्येथास्तत्र यत्नं समाचर॥', 'sa tvaṃ puruṣaśārdūla mārgasva viṣayaṃ svakam
duṣkṛtaṃ yatra paśyethās tatra yatnaṃ samācara', null, 7065025),
('ramayana-7-65-26', 26, 'Uttara Kanda, Sarga 65, Verse 26', 'एवं ते धर्मवृद्धिश्च नृणां चायुर्विवर्धनम्।
भविष्यति नरश्रेष्ठ बालस्यास्य च जीवितम्॥', 'evaṃ te dharmavṛddhiś ca nṛṇāṃ cāyurvivardhanam
bhaviṣyati naraśreṣṭha bālasyāsya ca jīvitam', null, 7065026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 66 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-66-1', 1, 'Uttara Kanda, Sarga 66, Verse 1', 'नारदस्य तु तद्वाक्यं श्रुत्वामृतमयं यथा।
प्रहर्षमतुलं लेभे लक्ष्मणं चेदमब्रवीत्॥', 'nāradasya tu tad vākyaṃ śrutvāmṛtamayaṃ yathā
praharṣam atulaṃ lebhe lakṣmaṇaṃ cedam abravīt', null, 7066001),
('ramayana-7-66-2', 2, 'Uttara Kanda, Sarga 66, Verse 2', 'गच्छ सौम्य द्विजश्रेष्ठं समाश्वासय लक्ष्मण।
बालस्य च शरीरं तत्तैलद्रोण्यां निधापय॥', 'gaccha saumya dvijaśreṣṭhaṃ samāśvāsaya lakṣmaṇa
bālasya ca śarīraṃ tat tailadroṇyāṃ nidhāpaya', null, 7066002),
('ramayana-7-66-3', 3, 'Uttara Kanda, Sarga 66, Verse 3', 'गन्धैश्च परमोदारैस्तैलैश्च सुसुगन्धिभिः।
यथा न क्षीयते बालस्तथा सौम्य विधीयताम्॥', 'gandhaiś ca paramodārais tailaiś ca susugandhibhiḥ
yathā na kṣīyate bālas tathā saumya vidhīyatām', null, 7066003),
('ramayana-7-66-4', 4, 'Uttara Kanda, Sarga 66, Verse 4', 'यथा शरीरे बालस्य गुप्तस्याक्लिष्टकर्मणः।
विपत्तिः परिभेदो वा भवेन्न च तथा कुरु॥', 'yathā śarīre bālasya guptasyākliṣṭakarmaṇaḥ
vipattiḥ paribhedo vā bhaven na ca tathā kuru', null, 7066004),
('ramayana-7-66-5', 5, 'Uttara Kanda, Sarga 66, Verse 5', 'तथा संदिश्य काकुत्स्थो लक्ष्मणं शुभलक्षणम्।
मनसा पुष्पकं दध्यावागच्छेति महायशाः॥', 'tathā saṃdiśya kākutstho lakṣmaṇaṃ śubhalakṣaṇam
manasā puṣpakaṃ dadhyāv āgaccheti mahāyaśāḥ', null, 7066005),
('ramayana-7-66-6', 6, 'Uttara Kanda, Sarga 66, Verse 6', 'इङ्गितं स तु विज्ञाय पुष्पको हेमभूषितः।
आजगाम मुहूर्तेन संपीपं राघवस्य वै॥', 'iṅgitaṃ sa tu vijñāya puṣpako hemabhūṣitaḥ
ājagāma muhūrtena saṃpīpaṃ rāghavasya vai', null, 7066006),
('ramayana-7-66-7', 7, 'Uttara Kanda, Sarga 66, Verse 7', 'सोऽब्रवीत्प्रणतो भूत्वा अयमस्मि नराधिप।
वश्यस्तव महाबाहो किंकरः समुपस्थितः॥', 'so ''bravīt praṇato bhūtvā ayam asmi narādhipa
vaśyas tava mahābāho kiṃkaraḥ samupasthitaḥ', null, 7066007),
('ramayana-7-66-8', 8, 'Uttara Kanda, Sarga 66, Verse 8', 'भाषितं रुचिरं श्रुत्वा पुष्पकस्य नराधिपः।
अभिवाद्य महर्षीस्तान्विमानं सोऽध्यरोहत॥', 'bhāṣitaṃ ruciraṃ śrutvā puṣpakasya narādhipaḥ
abhivādya maharṣīs tān vimānaṃ so ''dhyarohata', null, 7066008),
('ramayana-7-66-9', 9, 'Uttara Kanda, Sarga 66, Verse 9', 'धनुर्गृहीत्वा तूणीं च खग्दं च रुचिरप्रभम्।
निक्षिप्य नगरे वीरौ सौमित्रिभरतावुभौ॥', 'dhanur gṛhītvā tūṇīṃ ca khagdaṃ ca ruciraprabham
nikṣipya nagare vīrau saumitribharatāv ubhau', null, 7066009),
('ramayana-7-66-10', 10, 'Uttara Kanda, Sarga 66, Verse 10', 'प्रायात्प्रतीचीं स मरून्विचिन्वंश्च समन्ततः।
उत्तरामगमच्छ्रीमान्दिशं हिमवदावृतम्॥', 'prāyāt pratīcīṃ sa marūn vicinvaṃś ca samantataḥ
uttarām agamac chrīmān diśaṃ himavadāvṛtam', null, 7066010),
('ramayana-7-66-11', 11, 'Uttara Kanda, Sarga 66, Verse 11', 'अपश्यमानस्तत्रापि स्वल्पमप्यथ दुष्कृतम्।
पूर्वामपि दिशं सर्वामथापश्यन्नराधिपः॥', 'apaśyamānas tatrāpi svalpam apy atha duṣkṛtam
pūrvām api diśaṃ sarvām athāpaśyan narādhipaḥ', null, 7066011),
('ramayana-7-66-12', 12, 'Uttara Kanda, Sarga 66, Verse 12', 'दक्षिणां दिशमाक्रामत्ततो राजर्षिनन्दनः।
शैवलस्योत्तरे पार्श्वे ददर्श सुमहत्सरः॥', 'dakṣiṇāṃ diśam ākrāmat tato rājarṣinandanaḥ
śaivalasyottare pārśve dadarśa sumahat saraḥ', null, 7066012),
('ramayana-7-66-13', 13, 'Uttara Kanda, Sarga 66, Verse 13', 'तस्मिन्सरसि तप्यन्तं तापसं सुमहत्तपः।
ददर्श राघवः श्रीमांल्लम्बमानमधो मुखम्॥', 'tasmin sarasi tapyantaṃ tāpasaṃ sumahat tapaḥ
dadarśa rāghavaḥ śrīmāṃl lambamānam adho mukham', null, 7066013),
('ramayana-7-66-14', 14, 'Uttara Kanda, Sarga 66, Verse 14', 'अथैनं समुपागम्य तप्यन्तं तप उत्तमम्।
उवाच राघवो वाक्यं धन्यस्त्वमसि सुव्रत॥', 'athainaṃ samupāgamya tapyantaṃ tapa uttamam
uvāca rāghavo vākyaṃ dhanyas tvam asi suvrata', null, 7066014),
('ramayana-7-66-15', 15, 'Uttara Kanda, Sarga 66, Verse 15', 'कस्यां योन्यां तपोवृद्धवर्तसे दृढविक्रम।
कौतूहलात्त्वां पृच्छामि रामो दाशरथिर्ह्यहम्॥', 'kasyāṃ yonyāṃ tapovṛddhavartase dṛḍhavikrama
kautūhalāt tvāṃ pṛcchāmi rāmo dāśarathir hy aham', null, 7066015),
('ramayana-7-66-16', 16, 'Uttara Kanda, Sarga 66, Verse 16', 'मनीषितस्ते को न्वर्थः स्वर्गलाभो वराश्रयः।
यमश्रित्य तपस्तप्तं श्रोतुमिच्छामि तापस॥', 'manīṣitas te ko nv arthaḥ svargalābho varāśrayaḥ
yam aśritya tapas taptaṃ śrotum icchāmi tāpasa', null, 7066016),
('ramayana-7-66-17', 17, 'Uttara Kanda, Sarga 66, Verse 17', 'ब्राह्मणो वासि भद्रं ते क्षत्रियो वासि दुर्जयः।
वैश्यो वा यदि वा शूद्रः सत्यमेतद्ब्रवीहि मे॥', 'brāhmaṇo vāsi bhadraṃ te kṣatriyo vāsi durjayaḥ
vaiśyo vā yadi vā śūdraḥ satyam etad bravīhi me', null, 7066017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 67 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-67-1', 1, 'Uttara Kanda, Sarga 67, Verse 1', 'तस्य तद्वचनं श्रुत्वा रामस्याक्लिष्टकर्मणः।
अवाक्शिरास्तथाभूतो वाक्यमेतदुवाच ह॥', 'tasya tad vacanaṃ śrutvā rāmasyākliṣṭakarmaṇaḥ
avākśirās tathābhūto vākyam etad uvāca ha', null, 7067001),
('ramayana-7-67-2', 2, 'Uttara Kanda, Sarga 67, Verse 2', 'शूद्रयोन्यां प्रसूतोऽस्मि तप उग्रं समास्थितः।
देवत्वं प्रार्थये राम सशरीरो महायशः॥', 'śūdrayonyāṃ prasūto ''smi tapa ugraṃ samāsthitaḥ
devatvaṃ prārthaye rāma saśarīro mahāyaśaḥ', null, 7067002),
('ramayana-7-67-3', 3, 'Uttara Kanda, Sarga 67, Verse 3', 'न मिथ्याहं वदे राजन्देवलोकजिगीषया।
शूद्रं मां विद्धि काकुत्स्थ शम्बूकं नाम नामतः॥', 'na mithyāhaṃ vade rājan devalokajigīṣayā
śūdraṃ māṃ viddhi kākutstha śambūkaṃ nāma nāmataḥ', null, 7067003),
('ramayana-7-67-4', 4, 'Uttara Kanda, Sarga 67, Verse 4', 'भाषतस्तस्य शूद्रस्य खड्गं सुरुचिरप्रभम्।
निष्कृष्य कोशाद्विमलं शिरश्चिच्छेद राघवः॥', 'bhāṣatas tasya śūdrasya khaḍgaṃ suruciraprabham
niṣkṛṣya kośād vimalaṃ śiraś ciccheda rāghavaḥ', null, 7067004),
('ramayana-7-67-5', 5, 'Uttara Kanda, Sarga 67, Verse 5', 'तस्मिन्मुहूर्ते बालोऽसौ जीवेन समयुज्यत॥', 'tasmin muhūrte bālo ''sau jīvena samayujyata', null, 7067005),
('ramayana-7-67-6', 6, 'Uttara Kanda, Sarga 67, Verse 6', 'ततोऽगस्त्याश्रमपदं रामः कमललोचनः।
स गत्वा विनयेनैव तं नत्वा मुमुदे सुखी॥', 'tato ''gastyāśramapadaṃ rāmaḥ kamalalocanaḥ
sa gatvā vinayenaiva taṃ natvā mumude sukhī', null, 7067006),
('ramayana-7-67-7', 7, 'Uttara Kanda, Sarga 67, Verse 7', 'सोऽभिवाद्य महात्मानं ज्वलन्तमिव तेजसा।
आतिथ्यं परमं प्राप्य निषसाद नराधिपः॥', 'so ''bhivādya mahātmānaṃ jvalantam iva tejasā
ātithyaṃ paramaṃ prāpya niṣasāda narādhipaḥ', null, 7067007),
('ramayana-7-67-8', 8, 'Uttara Kanda, Sarga 67, Verse 8', 'तमुवाच महातेजाः कुम्भयोनिर्महातपाः।
स्वागतं ते नरश्रेष्ठ दिष्ट्या प्राप्तोऽसि राघव॥', 'tam uvāca mahātejāḥ kumbhayonir mahātapāḥ
svāgataṃ te naraśreṣṭha diṣṭyā prāpto ''si rāghava', null, 7067008),
('ramayana-7-67-9', 9, 'Uttara Kanda, Sarga 67, Verse 9', 'त्वं मे बहुमतो राम गुणैर्बहुभिरुत्तमैः।
अतिथिः पूजनीयश्च माम राजन्हृदि स्थितः॥', 'tvaṃ me bahumato rāma guṇair bahubhir uttamaiḥ
atithiḥ pūjanīyaś ca māma rājan hṛdi sthitaḥ', null, 7067009),
('ramayana-7-67-10', 10, 'Uttara Kanda, Sarga 67, Verse 10', 'सुरा हि कथयन्ति त्वामागतं शूद्रघातिनम्।
ब्राह्मणस्य तु धर्मेण त्वया जीवापितः सुतः॥', 'surā hi kathayanti tvām āgataṃ śūdraghātinam
brāhmaṇasya tu dharmeṇa tvayā jīvāpitaḥ sutaḥ', null, 7067010),
('ramayana-7-67-11', 11, 'Uttara Kanda, Sarga 67, Verse 11', 'उष्यतां चेह रजनीं सकाशे मम राघव।
प्रभाते पुष्पकेण त्वं गन्ता स्वपुरमेव हि॥', 'uṣyatāṃ ceha rajanīṃ sakāśe mama rāghava
prabhāte puṣpakeṇa tvaṃ gantā svapuram eva hi', null, 7067011),
('ramayana-7-67-12', 12, 'Uttara Kanda, Sarga 67, Verse 12', 'इदं चाभरणं सौम्य निर्मितं विश्वकर्मणा।
दिव्यं दिव्येन वपुषा दीप्यमानं स्वतेजसा।
प्रतिगृह्णीष्व काकुत्स्थ मत्प्रियं कुरु राघव॥', 'idaṃ cābharaṇaṃ saumya nirmitaṃ viśvakarmaṇā
divyaṃ divyena vapuṣā dīpyamānaṃ svatejasā
pratigṛhṇīṣva kākutstha matpriyaṃ kuru rāghava', null, 7067012),
('ramayana-7-67-13', 13, 'Uttara Kanda, Sarga 67, Verse 13', 'दत्तस्य हि पुनर्दानं सुमहत्फलमुच्यते।
तस्मात्प्रदास्ये विधिवत्तत्प्रतीच्छ नरर्षभ॥', 'dattasya hi punar dānaṃ sumahat phalam ucyate
tasmāt pradāsye vidhivat tat pratīccha nararṣabha', null, 7067013),
('ramayana-7-67-14', 14, 'Uttara Kanda, Sarga 67, Verse 14', 'तद्रामः प्रतिजग्राह मुनेस्तस्य महात्मनः।
दिव्यमाभरणं चित्रं प्रदीप्तमिव भास्करम्॥', 'tad rāmaḥ pratijagrāha munes tasya mahātmanaḥ
divyam ābharaṇaṃ citraṃ pradīptam iva bhāskaram', null, 7067014),
('ramayana-7-67-15', 15, 'Uttara Kanda, Sarga 67, Verse 15', 'प्रतिगृह्य ततो रामस्तदाभरणमुत्तमम्।
आगमं तस्य दिव्यस्य प्रष्टुमेवोपचक्रमे॥', 'pratigṛhya tato rāmas tad ābharaṇam uttamam
āgamaṃ tasya divyasya praṣṭum evopacakrame', null, 7067015),
('ramayana-7-67-16', 16, 'Uttara Kanda, Sarga 67, Verse 16', 'अत्यद्भुतमिदं ब्रह्मन्वपुषा युक्तमुत्तमम्।
कथं भगवता प्राप्तं कुतो वा केन वाहृतम्॥', 'atyadbhutam idaṃ brahman vapuṣā yuktam uttamam
kathaṃ bhagavatā prāptaṃ kuto vā kena vāhṛtam', null, 7067016),
('ramayana-7-67-17', 17, 'Uttara Kanda, Sarga 67, Verse 17', 'कुतूहलतया ब्रह्मन्पृच्छामि त्वां महायशः।
आश्चर्याणां बहूनां हि निधिः परमको भवान्॥', 'kutūhalatayā brahman pṛcchāmi tvāṃ mahāyaśaḥ
āścaryāṇāṃ bahūnāṃ hi nidhiḥ paramako bhavān', null, 7067017),
('ramayana-7-67-18', 18, 'Uttara Kanda, Sarga 67, Verse 18', 'एवं ब्रुवति काकुत्स्थे मुनिर्वाक्यमथाब्रवीत्।
शृणु राम यथावृत्तं पुरा त्रेतायुगे गते॥', 'evaṃ bruvati kākutsthe munir vākyam athābravīt
śṛṇu rāma yathāvṛttaṃ purā tretāyuge gate', null, 7067018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 68 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-68-1', 1, 'Uttara Kanda, Sarga 68, Verse 1', 'पुरा त्रेतायुगे ह्यासीदरण्यं बहुविस्तरम्।
समन्ताद्योजनशतं निर्मृगं पक्षिवर्जितम्॥', 'purā tretāyuge hy āsīd araṇyaṃ bahuvistaram
samantād yojanaśataṃ nirmṛgaṃ pakṣivarjitam', null, 7068001),
('ramayana-7-68-2', 2, 'Uttara Kanda, Sarga 68, Verse 2', 'तस्मिन्निर्मानुषेऽरण्ये कुर्वाणस्तप उत्तमम्।
अहमाक्रमितुं शौम्य तदरण्यमुपागमम्॥', 'tasmin nirmānuṣe ''raṇye kurvāṇas tapa uttamam
aham ākramituṃ śaumya tad araṇyam upāgamam', null, 7068002),
('ramayana-7-68-3', 3, 'Uttara Kanda, Sarga 68, Verse 3', 'तस्य रूपमरण्यस्य निर्देष्टुं न शशाक ह।
फलमूलैः सुखास्वादैर्बहुरूपैश्च पादपैः॥', 'tasya rūpam araṇyasya nirdeṣṭuṃ na śaśāka ha
phalamūlaiḥ sukhāsvādair bahurūpaiś ca pādapaiḥ', null, 7068003),
('ramayana-7-68-4', 4, 'Uttara Kanda, Sarga 68, Verse 4', 'तस्यारण्यस्य मध्ये तु सरो योजनमायतम्।
पद्मोत्पलसमाकीर्णं समतिक्रान्तशैवलम्॥', 'tasyāraṇyasya madhye tu saro yojanam āyatam
padmotpalasamākīrṇaṃ samatikrāntaśaivalam', null, 7068004),
('ramayana-7-68-5', 5, 'Uttara Kanda, Sarga 68, Verse 5', 'तदाश्चर्यमिवात्यर्थं सुखास्वादमनुत्तमम्।
अरजस्कं तथाक्षोभ्यं श्रीमत्पक्षिगणायुतम्॥', 'tad āścaryam ivātyarthaṃ sukhāsvādam anuttamam
arajaskaṃ tathākṣobhyaṃ śrīmatpakṣigaṇāyutam', null, 7068005),
('ramayana-7-68-6', 6, 'Uttara Kanda, Sarga 68, Verse 6', 'तस्मिन्सरःसमीपे तु महदद्भुतमाश्रमम्।
पुराणं पुण्यमत्यर्थं तपस्विजनवर्जितम्॥', 'tasmin saraḥsamīpe tu mahad adbhutam āśramam
purāṇaṃ puṇyam atyarthaṃ tapasvijanavarjitam', null, 7068006),
('ramayana-7-68-7', 7, 'Uttara Kanda, Sarga 68, Verse 7', 'तत्राहमवसं रात्रिं नैदाघीं पुरुषर्षभ।
प्रभाते काल्यमुत्थाय सरस्तदुपचक्रमे॥', 'tatrāham avasaṃ rātriṃ naidāghīṃ puruṣarṣabha
prabhāte kālyam utthāya saras tad upacakrame', null, 7068007),
('ramayana-7-68-8', 8, 'Uttara Kanda, Sarga 68, Verse 8', 'अथापश्यं शवं तत्र सुपुष्टमजरं क्व चित्।
तिष्ठन्तं परया लक्ष्म्या तस्मिंस्तोयाशये नृप॥', 'athāpaśyaṃ śavaṃ tatra supuṣṭam ajaraṃ kva cit
tiṣṭhantaṃ parayā lakṣmyā tasmiṃs toyāśaye nṛpa', null, 7068008),
('ramayana-7-68-9', 9, 'Uttara Kanda, Sarga 68, Verse 9', 'तमर्थं चिन्तयानोऽहं मुहूर्तं तत्र राघव।
विष्ठितोऽस्मि सरस्तीरे किं न्विदं स्यादिति प्रभो॥', 'tam arthaṃ cintayāno ''haṃ muhūrtaṃ tatra rāghava
viṣṭhito ''smi sarastīre kiṃ nv idaṃ syād iti prabho', null, 7068009),
('ramayana-7-68-10', 10, 'Uttara Kanda, Sarga 68, Verse 10', 'अथापश्यं मुहूर्तात्तु दिव्यमद्भुतदर्शनम्।
विमानं परमोदारं हंसयुक्तं मनोजवम्॥', 'athāpaśyaṃ muhūrtāt tu divyam adbhutadarśanam
vimānaṃ paramodāraṃ haṃsayuktaṃ manojavam', null, 7068010),
('ramayana-7-68-11', 11, 'Uttara Kanda, Sarga 68, Verse 11', 'अत्यर्थं स्वर्गिणं तत्र विमाने रघुनन्दन।
उपास्तेऽप्सरसां वीर सहस्रं दिव्यभूषणम्।
गान्ति गेयानि रम्याणि वादयन्ति तथापराः॥', 'atyarthaṃ svargiṇaṃ tatra vimāne raghunandana
upāste ''psarasāṃ vīra sahasraṃ divyabhūṣaṇam
gānti geyāni ramyāṇi vādayanti tathāparāḥ', null, 7068011),
('ramayana-7-68-12', 12, 'Uttara Kanda, Sarga 68, Verse 12', 'पश्यतो मे तदा राम विमानादवरुह्य च।
तं शवं भक्षयामास स स्वर्गी रघुनन्दन॥', 'paśyato me tadā rāma vimānād avaruhya ca
taṃ śavaṃ bhakṣayām āsa sa svargī raghunandana', null, 7068012),
('ramayana-7-68-13', 13, 'Uttara Kanda, Sarga 68, Verse 13', 'ततो भुक्त्वा यथाकामं मांसं बहु च सुष्ठु च।
अवतीर्य सरः स्वर्गी संस्प्रष्टुमुपचक्रमे॥', 'tato bhuktvā yathākāmaṃ māṃsaṃ bahu ca suṣṭhu ca
avatīrya saraḥ svargī saṃspraṣṭum upacakrame', null, 7068013),
('ramayana-7-68-14', 14, 'Uttara Kanda, Sarga 68, Verse 14', 'उपस्पृश्य यथान्यायं स स्वर्गी पुरुषर्षभ।
आरोढुमुपचक्राम विमानवरमुत्तमम्॥', 'upaspṛśya yathānyāyaṃ sa svargī puruṣarṣabha
āroḍhum upacakrāma vimānavaram uttamam', null, 7068014),
('ramayana-7-68-15', 15, 'Uttara Kanda, Sarga 68, Verse 15', 'तमहं देवसंकाशमारोहन्तमुदीक्ष्य वै।
अथाहमब्रुवं वाक्यं तमेव पुरुषर्षभ॥', 'tam ahaṃ devasaṃkāśam ārohantam udīkṣya vai
athāham abruvaṃ vākyaṃ tam eva puruṣarṣabha', null, 7068015),
('ramayana-7-68-16', 16, 'Uttara Kanda, Sarga 68, Verse 16', 'को भवान्देवसंकाश आहारश्च विगर्हितः।
त्वयायं भुज्यते सौम्य किं कर्थं वक्तुमर्हसि॥', 'ko bhavān devasaṃkāśa āhāraś ca vigarhitaḥ
tvayāyaṃ bhujyate saumya kiṃ karthaṃ vaktum arhasi', null, 7068016),
('ramayana-7-68-17', 17, 'Uttara Kanda, Sarga 68, Verse 17', 'आश्चर्यमीदृशो भावो भास्वरो देवसंमतः।
आहारो गर्हितः सौम्य श्रोतुमिच्छामि तत्त्वतः॥', 'āścaryam īdṛśo bhāvo bhāsvaro devasaṃmataḥ
āhāro garhitaḥ saumya śrotum icchāmi tattvataḥ', null, 7068017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 69 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-69-1', 1, 'Uttara Kanda, Sarga 69, Verse 1', 'भुक्त्वा तु भाषितं वाक्यं मम राम शुभाक्षरम्।
प्राञ्जलिः प्रत्युवाचेदं स स्वर्गी रघुनन्दन॥', 'bhuktvā tu bhāṣitaṃ vākyaṃ mama rāma śubhākṣaram
prāñjaliḥ pratyuvācedaṃ sa svargī raghunandana', null, 7069001),
('ramayana-7-69-2', 2, 'Uttara Kanda, Sarga 69, Verse 2', 'शृणु ब्रह्मन्यथावृत्तं ममैतत्सुखदुःखयोः।
दुरतिक्रमणीयं हि यथा पृच्छसि मां द्विज॥', 'śṛṇu brahman yathāvṛttaṃ mamaitat sukhaduḥkhayoḥ
duratikramaṇīyaṃ hi yathā pṛcchasi māṃ dvija', null, 7069002),
('ramayana-7-69-3', 3, 'Uttara Kanda, Sarga 69, Verse 3', 'पुरा वैदर्भको राजा पिता मम महायशाः।
सुदेव इति विख्यातस्त्रिषु लोकेषु वीर्यवान्॥', 'purā vaidarbhako rājā pitā mama mahāyaśāḥ
sudeva iti vikhyātas triṣu lokeṣu vīryavān', null, 7069003),
('ramayana-7-69-4', 4, 'Uttara Kanda, Sarga 69, Verse 4', 'तस्य पुत्रद्वयं ब्रह्मन्द्वाभ्यां स्त्रीभ्यामजायत।
अहं श्वेत इति ख्यातो यवीयान्सुरथोऽभवत्॥', 'tasya putradvayaṃ brahman dvābhyāṃ strībhyām ajāyata
ahaṃ śveta iti khyāto yavīyān suratho ''bhavat', null, 7069004),
('ramayana-7-69-5', 5, 'Uttara Kanda, Sarga 69, Verse 5', 'ततः पितरि स्वर्याते पौरा मामभ्यषेचयन्।
तत्राहं कृतवान्राज्यं धर्मेण सुसमाहितः॥', 'tataḥ pitari svaryāte paurā mām abhyaṣecayan
tatrāhaṃ kṛtavān rājyaṃ dharmeṇa susamāhitaḥ', null, 7069005),
('ramayana-7-69-6', 6, 'Uttara Kanda, Sarga 69, Verse 6', 'एवं वर्षसहस्राणि समतीतानि सुव्रत।
राज्यं कारयतो ब्रह्मन्प्रजा धर्मेण रक्षतः॥', 'evaṃ varṣasahasrāṇi samatītāni suvrata
rājyaṃ kārayato brahman prajā dharmeṇa rakṣataḥ', null, 7069006),
('ramayana-7-69-7', 7, 'Uttara Kanda, Sarga 69, Verse 7', 'सोऽहं निमित्ते कस्मिंश्चिद्विज्ञातायुर्द्विजोत्तम।
कालधर्मं हृदि न्यस्य ततो वनमुपागमम्॥', 'so ''haṃ nimitte kasmiṃś cid vijñātāyur dvijottama
kāladharmaṃ hṛdi nyasya tato vanam upāgamam', null, 7069007),
('ramayana-7-69-8', 8, 'Uttara Kanda, Sarga 69, Verse 8', 'सोऽहं वनमिदं दुर्गं मृगपक्षिविवर्जितम्।
तपश्चर्तुं प्रविष्टोऽस्मि समीपे सरसः शुभे॥', 'so ''haṃ vanam idaṃ durgaṃ mṛgapakṣivivarjitam
tapaś cartuṃ praviṣṭo ''smi samīpe sarasaḥ śubhe', null, 7069008),
('ramayana-7-69-9', 9, 'Uttara Kanda, Sarga 69, Verse 9', 'भ्रातरं सुरथं राज्ये अभिषिच्य नराधिपम्।
इदं सरः समासाद्य तपस्तप्तं मया चिरम्॥', 'bhrātaraṃ surathaṃ rājye abhiṣicya narādhipam
idaṃ saraḥ samāsādya tapas taptaṃ mayā ciram', null, 7069009),
('ramayana-7-69-10', 10, 'Uttara Kanda, Sarga 69, Verse 10', 'सोऽहं वर्षसहस्राणि तपस्त्रीणि महामुने।
तप्त्वा सुदुष्करं प्राप्तो ब्रह्मलोकमनुत्तमम्॥', 'so ''haṃ varṣasahasrāṇi tapas trīṇi mahāmune
taptvā suduṣkaraṃ prāpto brahmalokam anuttamam', null, 7069010),
('ramayana-7-69-11', 11, 'Uttara Kanda, Sarga 69, Verse 11', 'ततो मां स्वर्गसंस्थं वै क्षुत्पिपासे द्विजोत्तम।
बाधेते परमोदार ततोऽहं व्यथितेन्द्रियः॥', 'tato māṃ svargasaṃsthaṃ vai kṣutpipāse dvijottama
bādhete paramodāra tato ''haṃ vyathitendriyaḥ', null, 7069011),
('ramayana-7-69-12', 12, 'Uttara Kanda, Sarga 69, Verse 12', 'गत्वा त्रिभुवणश्रेष्ठं पितामहमुवाच ह।
भगवन्ब्रह्मलोकोऽयं क्षुत्पिपासाविवर्जितः॥', 'gatvā tribhuvaṇaśreṣṭhaṃ pitāmaham uvāca ha
bhagavan brahmaloko ''yaṃ kṣutpipāsāvivarjitaḥ', null, 7069012),
('ramayana-7-69-13', 13, 'Uttara Kanda, Sarga 69, Verse 13', 'कस्येयं कर्मणः प्राप्तिः क्षुत्पिपासावशोऽस्मि यत्।
आहारः कश्च मे देव तन्मे ब्रूहि पितामह॥', 'kasyeyaṃ karmaṇaḥ prāptiḥ kṣutpipāsāvaśo ''smi yat
āhāraḥ kaś ca me deva tan me brūhi pitāmaha', null, 7069013),
('ramayana-7-69-14', 14, 'Uttara Kanda, Sarga 69, Verse 14', 'पितामहस्तु मामाह तवाहारः सुदेवज।
स्वादूनि स्वानि मांसानि तानि भक्षय नित्यशः॥', 'pitāmahas tu mām āha tavāhāraḥ sudevaja
svādūni svāni māṃsāni tāni bhakṣaya nityaśaḥ', null, 7069014),
('ramayana-7-69-15', 15, 'Uttara Kanda, Sarga 69, Verse 15', 'स्वशरीरं त्वया पुष्टं कुर्वता तप उत्तमम्।
अनुप्तं रोहते श्वेत न कदा चिन्महामते॥', 'svaśarīraṃ tvayā puṣṭaṃ kurvatā tapa uttamam
anuptaṃ rohate śveta na kadā cin mahāmate', null, 7069015),
('ramayana-7-69-16', 16, 'Uttara Kanda, Sarga 69, Verse 16', 'दत्तं न तेऽस्ति सूक्ष्मोऽपि वने सत्त्वनिषेविते।
तेन स्वर्गगतो वत्स बाध्यसे क्षुत्पिपासया॥', 'dattaṃ na te ''sti sūkṣmo ''pi vane sattvaniṣevite
tena svargagato vatsa bādhyase kṣutpipāsayā', null, 7069016),
('ramayana-7-69-17', 17, 'Uttara Kanda, Sarga 69, Verse 17', 'स त्वं सुपुष्टमाहारैः स्वशरीरमनुत्तमम्।
भक्षयस्वामृतरसं सा ते तृप्तिर्भविष्यति॥', 'sa tvaṃ supuṣṭam āhāraiḥ svaśarīram anuttamam
bhakṣayasvāmṛtarasaṃ sā te tṛptir bhaviṣyati', null, 7069017),
('ramayana-7-69-18', 18, 'Uttara Kanda, Sarga 69, Verse 18', 'यदा तु तद्वनं श्वेत अगस्त्यः सुमहानृषिः।
आक्रमिष्यति दुर्धर्षस्तदा कृच्छाद्विमोक्ष्यसे॥', 'yadā tu tad vanaṃ śveta agastyaḥ sumahān ṛṣiḥ
ākramiṣyati durdharṣas tadā kṛcchād vimokṣyase', null, 7069018),
('ramayana-7-69-19', 19, 'Uttara Kanda, Sarga 69, Verse 19', 'स हि तारयितुं सौम्य शक्तः सुरगणानपि।
किं पुनस्त्वां महाबाहो क्षुत्पिपासावशं गतम्॥', 'sa hi tārayituṃ saumya śaktaḥ suragaṇān api
kiṃ punas tvāṃ mahābāho kṣutpipāsāvaśaṃ gatam', null, 7069019),
('ramayana-7-69-20', 20, 'Uttara Kanda, Sarga 69, Verse 20', 'सोऽहं भगवतः श्रुत्वा देवदेवस्य निश्चयम्।
आहारं गर्हितं कुर्मि स्वशरीरं द्विजोत्तम॥', 'so ''haṃ bhagavataḥ śrutvā devadevasya niścayam
āhāraṃ garhitaṃ kurmi svaśarīraṃ dvijottama', null, 7069020),
('ramayana-7-69-21', 21, 'Uttara Kanda, Sarga 69, Verse 21', 'बहून्वर्षगणान्ब्रह्मन्भुज्यमानमिदं मया।
क्षयं नाभ्येति ब्रह्मर्षे तृप्तिश्चापि ममोत्तमा॥', 'bahūn varṣagaṇān brahman bhujyamānam idaṃ mayā
kṣayaṃ nābhyeti brahmarṣe tṛptiś cāpi mamottamā', null, 7069021),
('ramayana-7-69-22', 22, 'Uttara Kanda, Sarga 69, Verse 22', 'तस्य मे कृच्छ्रभूतस्य कृच्छ्रादस्माद्विमोक्षय।
अन्येषामगतिर्ह्यत्र कुम्भयोनिमृते द्विजम्॥', 'tasya me kṛcchrabhūtasya kṛcchrād asmād vimokṣaya
anyeṣām agatir hy atra kumbhayonim ṛte dvijam', null, 7069022),
('ramayana-7-69-23', 23, 'Uttara Kanda, Sarga 69, Verse 23', 'इदमाभरणं सौम्य तारणार्थं द्विजोत्तम।
प्रतिगृह्णीष्व ब्रह्मर्षे प्रसादं कर्तुमर्हसि॥', 'idam ābharaṇaṃ saumya tāraṇārthaṃ dvijottama
pratigṛhṇīṣva brahmarṣe prasādaṃ kartum arhasi', null, 7069023),
('ramayana-7-69-24', 24, 'Uttara Kanda, Sarga 69, Verse 24', 'तस्याहं स्वर्गिणो वाक्यं श्रुत्वा दुःखसमन्वितम्।
तारणायोपजग्राह तदाभरणमुत्तमम्॥', 'tasyāhaṃ svargiṇo vākyaṃ śrutvā duḥkhasamanvitam
tāraṇāyopajagrāha tad ābharaṇam uttamam', null, 7069024),
('ramayana-7-69-25', 25, 'Uttara Kanda, Sarga 69, Verse 25', 'मया प्रतिगृहीते तु तस्मिन्नाभरणे शुभे।
मानुषः पूर्वको देहो राजर्षेः स ननाश ह॥', 'mayā pratigṛhīte tu tasminn ābharaṇe śubhe
mānuṣaḥ pūrvako deho rājarṣeḥ sa nanāśa ha', null, 7069025),
('ramayana-7-69-26', 26, 'Uttara Kanda, Sarga 69, Verse 26', 'प्रनष्टे तु शरीरेऽसौ राजर्षिः परया मुदा।
तृप्तः प्रमुदितो राजा जगाम त्रिदिवं पुनः॥', 'pranaṣṭe tu śarīre ''sau rājarṣiḥ parayā mudā
tṛptaḥ pramudito rājā jagāma tridivaṃ punaḥ', null, 7069026),
('ramayana-7-69-27', 27, 'Uttara Kanda, Sarga 69, Verse 27', 'तेनेदं शक्रतुल्येन दिव्यमाभरणं मम।
तस्मिन्निमित्ते काकुत्स्थ दत्तमद्भुतदर्शनम्॥', 'tenedaṃ śakratulyena divyam ābharaṇaṃ mama
tasmin nimitte kākutstha dattam adbhutadarśanam', null, 7069027)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 70 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-70-1', 1, 'Uttara Kanda, Sarga 70, Verse 1', 'तदद्भुततमं वाक्यं श्रुत्वागस्त्यस्य राघवः।
गौरवाद्विस्मयाच्चैव भूयः प्रष्टुं प्रचक्रमे॥', 'tad adbhutatamaṃ vākyaṃ śrutvāgastyasya rāghavaḥ
gauravād vismayāc caiva bhūyaḥ praṣṭuṃ pracakrame', null, 7070001),
('ramayana-7-70-2', 2, 'Uttara Kanda, Sarga 70, Verse 2', 'भगवंस्तद्वनं घोरं तपस्तप्यति यत्र सः।
श्वेतो वैदर्भको राजा कथं तदमृगद्विजम्॥', 'bhagavaṃs tad vanaṃ ghoraṃ tapas tapyati yatra saḥ
śveto vaidarbhako rājā kathaṃ tad amṛgadvijam', null, 7070002),
('ramayana-7-70-3', 3, 'Uttara Kanda, Sarga 70, Verse 3', 'निःसत्त्वं च वनं जातं शून्यं मनुजवर्जितम्।
तपश्चर्तुं प्रविष्टः स श्रोतुमिच्छामि तत्त्वतः॥', 'niḥsattvaṃ ca vanaṃ jātaṃ śūnyaṃ manujavarjitam
tapaś cartuṃ praviṣṭaḥ sa śrotum icchāmi tattvataḥ', null, 7070003),
('ramayana-7-70-4', 4, 'Uttara Kanda, Sarga 70, Verse 4', 'रामस्य भाषितं श्रुत्वा कौतूहलसमन्वितम्।
वाक्यं परमतेजस्वी वक्तुमेवोपचक्रमे॥', 'rāmasya bhāṣitaṃ śrutvā kautūhalasamanvitam
vākyaṃ paramatejasvī vaktum evopacakrame', null, 7070004),
('ramayana-7-70-5', 5, 'Uttara Kanda, Sarga 70, Verse 5', 'पुरा कृतयुगे राम मनुर्दण्डधरः प्रभुः।
तस्य पुत्रो महानासीदिक्ष्वाकुः कुलवर्धनः॥', 'purā kṛtayuge rāma manur daṇḍadharaḥ prabhuḥ
tasya putro mahān āsīd ikṣvākuḥ kulavardhanaḥ', null, 7070005),
('ramayana-7-70-6', 6, 'Uttara Kanda, Sarga 70, Verse 6', 'तं पुत्रं पूर्वके राज्ये निक्षिप्य भुवि दुर्जयम्।
पृथिव्यां राजवंशानां भव कर्तेत्युवाच ह॥', 'taṃ putraṃ pūrvake rājye nikṣipya bhuvi durjayam
pṛthivyāṃ rājavaṃśānāṃ bhava kartety uvāca ha', null, 7070006),
('ramayana-7-70-7', 7, 'Uttara Kanda, Sarga 70, Verse 7', 'तथेति च प्रतिज्ञातं पितुः पुत्रेण राघव।
ततः परमसंहृष्टो मनुः पुनरुवाच ह॥', 'tatheti ca pratijñātaṃ pituḥ putreṇa rāghava
tataḥ paramasaṃhṛṣṭo manuḥ punar uvāca ha', null, 7070007),
('ramayana-7-70-8', 8, 'Uttara Kanda, Sarga 70, Verse 8', 'प्रीतोऽस्मि परमोदारकर्ता चासि न संशयः।
दण्डेन च प्रजा रक्ष मा च दण्डमकारणे॥', 'prīto ''smi paramodārakartā cāsi na saṃśayaḥ
daṇḍena ca prajā rakṣa mā ca daṇḍam akāraṇe', null, 7070008),
('ramayana-7-70-9', 9, 'Uttara Kanda, Sarga 70, Verse 9', 'अपराधिषु यो दण्डः पात्यते मानवेषु वै।
स दण्डो विधिवन्मुक्तः स्वर्गं नयति पार्थिवम्॥', 'aparādhiṣu yo daṇḍaḥ pātyate mānaveṣu vai
sa daṇḍo vidhivan muktaḥ svargaṃ nayati pārthivam', null, 7070009),
('ramayana-7-70-10', 10, 'Uttara Kanda, Sarga 70, Verse 10', 'तस्माद्दण्डे महाबाहो यत्नवान्भव पुत्रक।
धर्मो हि परमो लोके कुर्वतस्ते भविष्यति॥', 'tasmād daṇḍe mahābāho yatnavān bhava putraka
dharmo hi paramo loke kurvatas te bhaviṣyati', null, 7070010),
('ramayana-7-70-11', 11, 'Uttara Kanda, Sarga 70, Verse 11', 'इति तं बहु संदिश्य मनुः पुत्रं समाधिना।
जगाम त्रिदिवं हृष्टो ब्रह्मलोकमनुत्तमम्॥', 'iti taṃ bahu saṃdiśya manuḥ putraṃ samādhinā
jagāma tridivaṃ hṛṣṭo brahmalokam anuttamam', null, 7070011),
('ramayana-7-70-12', 12, 'Uttara Kanda, Sarga 70, Verse 12', 'प्रयाते त्रिदिवे तस्मिन्निक्ष्वाकुरमितप्रभः।
जनयिष्ये कथं पुत्रानिति चिन्तापरोऽभवत्॥', 'prayāte tridive tasminn ikṣvākur amitaprabhaḥ
janayiṣye kathaṃ putrān iti cintāparo ''bhavat', null, 7070012),
('ramayana-7-70-13', 13, 'Uttara Kanda, Sarga 70, Verse 13', 'कर्मभिर्बहुरूपैश्च तैस्तैर्मनुसुतः सुतान्।
जनयामास धर्मात्मा शतं देवसुतोपमान्॥', 'karmabhir bahurūpaiś ca tais tair manusutaḥ sutān
janayām āsa dharmātmā śataṃ devasutopamān', null, 7070013),
('ramayana-7-70-14', 14, 'Uttara Kanda, Sarga 70, Verse 14', 'तेषामवरजस्तात सर्वेषां रघुनन्दन।
मूढश्चाकृतिविद्यश्च न शुश्रूषति पूर्वजान्॥', 'teṣām avarajas tāta sarveṣāṃ raghunandana
mūḍhaś cākṛtividyaś ca na śuśrūṣati pūrvajān', null, 7070014),
('ramayana-7-70-15', 15, 'Uttara Kanda, Sarga 70, Verse 15', 'नाम तस्य च दण्डेति पिता चक्रेऽल्पतेजसः।
अवश्यं दण्डपतनं शरीरेऽस्य भविष्यति॥', 'nāma tasya ca daṇḍeti pitā cakre ''lpatejasaḥ
avaśyaṃ daṇḍapatanaṃ śarīre ''sya bhaviṣyati', null, 7070015),
('ramayana-7-70-16', 16, 'Uttara Kanda, Sarga 70, Verse 16', 'स पश्यमानस्तं दोषं घोरं पुत्रस्य राघव।
विन्ध्यशैवलयोर्मध्ये राज्यं प्रादादरिंदम॥', 'sa paśyamānas taṃ doṣaṃ ghoraṃ putrasya rāghava
vindhyaśaivalayor madhye rājyaṃ prādād ariṃdama', null, 7070016),
('ramayana-7-70-17', 17, 'Uttara Kanda, Sarga 70, Verse 17', 'स दण्डस्तत्र राजाभूद्रम्ये पर्वतरोधसि।
पुरं चाप्रतिमं राम न्यवेशयदनुत्तमम्॥', 'sa daṇḍas tatra rājābhūd ramye parvatarodhasi
puraṃ cāpratimaṃ rāma nyaveśayad anuttamam', null, 7070017),
('ramayana-7-70-18', 18, 'Uttara Kanda, Sarga 70, Verse 18', 'पुरस्य चाकरोन्नाम मधुमन्तमिति प्रभो।
पुरोहितं चोशनसं वरयामास सुव्रतम्॥', 'purasya cākaron nāma madhumantam iti prabho
purohitaṃ cośanasaṃ varayām āsa suvratam', null, 7070018),
('ramayana-7-70-19', 19, 'Uttara Kanda, Sarga 70, Verse 19', 'एवं स राजा तद्राज्यं कारयत्सपुरोहितः।
प्रहृष्टमनुजाकीर्णं देवराज्यं यथा दिवि॥', 'evaṃ sa rājā tad rājyaṃ kārayat sapurohitaḥ
prahṛṣṭamanujākīrṇaṃ devarājyaṃ yathā divi', null, 7070019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 71 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-71-1', 1, 'Uttara Kanda, Sarga 71, Verse 1', 'एतदाख्याय रामाय महर्षिः कुम्भसंभवः।
अस्यामेवापरं वाक्यं कथायामुपचक्रमे॥', 'etad ākhyāya rāmāya maharṣiḥ kumbhasaṃbhavaḥ
asyām evāparaṃ vākyaṃ kathāyām upacakrame', null, 7071001),
('ramayana-7-71-2', 2, 'Uttara Kanda, Sarga 71, Verse 2', 'ततः स दण्डः काकुत्स्थ बहुवर्षगणायुतम्।
अकरोत्तत्र मन्दात्मा राज्यं निहतकण्टकम्॥', 'tataḥ sa daṇḍaḥ kākutstha bahuvarṣagaṇāyutam
akarot tatra mandātmā rājyaṃ nihatakaṇṭakam', null, 7071002),
('ramayana-7-71-3', 3, 'Uttara Kanda, Sarga 71, Verse 3', 'अथ काले तु कस्मिंश्चिद्राजा भार्गवमाश्रमम्।
रमणीयमुपाक्रामच्चैत्रे मासि मनोरमे॥', 'atha kāle tu kasmiṃś cid rājā bhārgavam āśramam
ramaṇīyam upākrāmac caitre māsi manorame', null, 7071003),
('ramayana-7-71-4', 4, 'Uttara Kanda, Sarga 71, Verse 4', 'तत्र भार्गवकन्यां स रूपेणाप्रतिमां भुवि।
विचरन्तीं वनोद्देशे दण्डोऽपश्यदनुत्तमाम्॥', 'tatra bhārgavakanyāṃ sa rūpeṇāpratimāṃ bhuvi
vicarantīṃ vanoddeśe daṇḍo ''paśyad anuttamām', null, 7071004),
('ramayana-7-71-5', 5, 'Uttara Kanda, Sarga 71, Verse 5', 'स दृष्ट्वा तां सुदुर्मेधा अनङ्गशरपीडितः।
अभिगम्य सुसंविग्नः कन्यां वचनमब्रवीत्॥', 'sa dṛṣṭvā tāṃ sudurmedhā anaṅgaśarapīḍitaḥ
abhigamya susaṃvignaḥ kanyāṃ vacanam abravīt', null, 7071005),
('ramayana-7-71-6', 6, 'Uttara Kanda, Sarga 71, Verse 6', 'कुतस्त्वमसि सुश्रोणि कस्य वासि सुता शुभे।
पीडितोऽहमनङ्गेन पृच्छामि त्वां सुमध्यमे॥', 'kutas tvam asi suśroṇi kasya vāsi sutā śubhe
pīḍito ''ham anaṅgena pṛcchāmi tvāṃ sumadhyame', null, 7071006),
('ramayana-7-71-7', 7, 'Uttara Kanda, Sarga 71, Verse 7', 'तस्य त्वेवं ब्रुवाणस्य मोहोन्मत्तस्य कामिनः।
भार्गवी प्रत्युवाचेदं वचः सानुनयं नृपम्॥', 'tasya tv evaṃ bruvāṇasya mohonmattasya kāminaḥ
bhārgavī pratyuvācedaṃ vacaḥ sānunayaṃ nṛpam', null, 7071007),
('ramayana-7-71-8', 8, 'Uttara Kanda, Sarga 71, Verse 8', 'भार्गवस्य सुतां विद्धि देवस्याक्लिष्टकर्मणः।
अरजां नाम राजेन्द्र ज्येष्ठामाश्रमवासिनीम्॥', 'bhārgavasya sutāṃ viddhi devasyākliṣṭakarmaṇaḥ
arajāṃ nāma rājendra jyeṣṭhām āśramavāsinīm', null, 7071008),
('ramayana-7-71-9', 9, 'Uttara Kanda, Sarga 71, Verse 9', 'गुरुः पिता मे राजेन्द्र त्वं च शिष्यो महात्मनः।
व्यसनं सुमहत्क्रुद्धः स ते दद्यान्महातपाः॥', 'guruḥ pitā me rājendra tvaṃ ca śiṣyo mahātmanaḥ
vyasanaṃ sumahat kruddhaḥ sa te dadyān mahātapāḥ', null, 7071009),
('ramayana-7-71-10', 10, 'Uttara Kanda, Sarga 71, Verse 10', 'यदि वात्र मया कार्यं धर्मदृष्टेन सत्पथा।
वरयस्व नृप श्रेष्ठ पितरं मे महाद्युतिम्॥', 'yadi vātra mayā kāryaṃ dharmadṛṣṭena satpathā
varayasva nṛpa śreṣṭha pitaraṃ me mahādyutim', null, 7071010),
('ramayana-7-71-11', 11, 'Uttara Kanda, Sarga 71, Verse 11', 'अन्यथा तु फलं तुभ्यं भवेद्घोराभिसंहितम्।
क्रोधेन हि पिता मेऽसौ त्रैलोक्यमपि निर्दहेत्॥', 'anyathā tu phalaṃ tubhyaṃ bhaved ghorābhisaṃhitam
krodhena hi pitā me ''sau trailokyam api nirdahet', null, 7071011),
('ramayana-7-71-12', 12, 'Uttara Kanda, Sarga 71, Verse 12', 'एवं ब्रुवाणामरजां दण्डः कामशरार्दितः।
प्रत्युवाच मदोन्मत्तः शिरस्याधाय सोऽञ्जलिम्॥', 'evaṃ bruvāṇām arajāṃ daṇḍaḥ kāmaśarārditaḥ
pratyuvāca madonmattaḥ śirasy ādhāya so ''ñjalim', null, 7071012),
('ramayana-7-71-13', 13, 'Uttara Kanda, Sarga 71, Verse 13', 'प्रसादं कुरु सुश्रोणि न कालं क्षेप्तुमर्हसि।
त्वत्कृते हि मम प्राणा विदीर्यन्ते शुभानने॥', 'prasādaṃ kuru suśroṇi na kālaṃ kṣeptum arhasi
tvatkṛte hi mama prāṇā vidīryante śubhānane', null, 7071013),
('ramayana-7-71-14', 14, 'Uttara Kanda, Sarga 71, Verse 14', 'त्वां प्राप्य हि वधो वापि पापं वापि सुदारुणम्।
भक्तं भजस्व मां भीरु भजमानं सुविह्वलम्॥', 'tvāṃ prāpya hi vadho vāpi pāpaṃ vāpi sudāruṇam
bhaktaṃ bhajasva māṃ bhīru bhajamānaṃ suvihvalam', null, 7071014),
('ramayana-7-71-15', 15, 'Uttara Kanda, Sarga 71, Verse 15', 'एवमुक्त्वा तु तां कन्यां दोर्भ्यां गृह्य बलाद्बली।
विस्फुरन्तीं यथाकामं मैथुनायोपचक्रमे॥', 'evam uktvā tu tāṃ kanyāṃ dorbhyāṃ gṛhya balād balī
visphurantīṃ yathākāmaṃ maithunāyopacakrame', null, 7071015),
('ramayana-7-71-16', 16, 'Uttara Kanda, Sarga 71, Verse 16', 'तमनर्थं महाघोरं दण्डः कृत्वा सुदारुणम्।
नगरं प्रययौ चाशु मधुमन्तमनुत्तमम्॥', 'tam anarthaṃ mahāghoraṃ daṇḍaḥ kṛtvā sudāruṇam
nagaraṃ prayayau cāśu madhumantam anuttamam', null, 7071016),
('ramayana-7-71-17', 17, 'Uttara Kanda, Sarga 71, Verse 17', 'अरजापि रुदन्ती सा आश्रमस्याविदूरतः।
प्रतीक्षते सुसंत्रस्ता पितरं देवसंनिभम्॥', 'arajāpi rudantī sā āśramasyāvidūrataḥ
pratīkṣate susaṃtrastā pitaraṃ devasaṃnibham', null, 7071017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 72 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-72-1', 1, 'Uttara Kanda, Sarga 72, Verse 1', 'स मुहूर्तादुपश्रुत्य देवर्षिरमितप्रभः।
स्वमाश्रमं शिष्य वृतः क्षुधार्तः संन्यवर्तत॥', 'sa muhūrtād upaśrutya devarṣir amitaprabhaḥ
svam āśramaṃ śiṣya vṛtaḥ kṣudhārtaḥ saṃnyavartata', null, 7072001),
('ramayana-7-72-2', 2, 'Uttara Kanda, Sarga 72, Verse 2', 'सोऽपश्यदरजां दीनां रजसा समभिप्लुताम्।
ज्योत्स्नामिवारुणग्रस्तां प्रत्यूषे न विराजतीम्॥', 'so ''paśyad arajāṃ dīnāṃ rajasā samabhiplutām
jyotsnām ivāruṇagrastāṃ pratyūṣe na virājatīm', null, 7072002),
('ramayana-7-72-3', 3, 'Uttara Kanda, Sarga 72, Verse 3', 'तस्य रोषः समभवत्क्षुधार्तस्य विशेषतः।
निर्दहन्निव लोकांस्त्रीञ्शिष्यांश्चेदमुवाच ह॥', 'tasya roṣaḥ samabhavat kṣudhārtasya viśeṣataḥ
nirdahann iva lokāṃs trīñ śiṣyāṃś cedam uvāca ha', null, 7072003),
('ramayana-7-72-4', 4, 'Uttara Kanda, Sarga 72, Verse 4', 'पश्यध्वं विपरीतस्य दण्डस्याविदितात्मनः।
विपत्तिं घोरसंकाशां क्रुद्धामग्निशिखामिव॥', 'paśyadhvaṃ viparītasya daṇḍasyāviditātmanaḥ
vipattiṃ ghorasaṃkāśāṃ kruddhām agniśikhām iva', null, 7072004),
('ramayana-7-72-5', 5, 'Uttara Kanda, Sarga 72, Verse 5', 'क्षयोऽस्य दुर्मतेः प्राप्तः सानुगस्य दुरात्मनः।
यः प्रदीप्तां हुताशस्य शिखां वै स्प्रष्टुमिच्छति॥', 'kṣayo ''sya durmateḥ prāptaḥ sānugasya durātmanaḥ
yaḥ pradīptāṃ hutāśasya śikhāṃ vai spraṣṭum icchati', null, 7072005),
('ramayana-7-72-6', 6, 'Uttara Kanda, Sarga 72, Verse 6', 'यस्मात्स कृतवान्पापमीदृशं घोरदर्शनम्।
तस्मात्प्राप्स्यति दुर्मेधाः फलं पापस्य कर्मणः॥', 'yasmāt sa kṛtavān pāpam īdṛśaṃ ghoradarśanam
tasmāt prāpsyati durmedhāḥ phalaṃ pāpasya karmaṇaḥ', null, 7072006),
('ramayana-7-72-7', 7, 'Uttara Kanda, Sarga 72, Verse 7', 'सप्तरात्रेण राजासौ सभृत्यबलवाहनः।
पापकर्मसमाचारो वधं प्राप्स्यति दुर्मतिः॥', 'saptarātreṇa rājāsau sabhṛtyabalavāhanaḥ
pāpakarmasamācāro vadhaṃ prāpsyati durmatiḥ', null, 7072007),
('ramayana-7-72-8', 8, 'Uttara Kanda, Sarga 72, Verse 8', 'समन्ताद्योजनशतं विषयं चास्य दुर्मतेः।
धक्ष्यते पांसुवर्षेण महता पाकशासनः॥', 'samantād yojanaśataṃ viṣayaṃ cāsya durmateḥ
dhakṣyate pāṃsuvarṣeṇa mahatā pākaśāsanaḥ', null, 7072008),
('ramayana-7-72-9', 9, 'Uttara Kanda, Sarga 72, Verse 9', 'सर्वसत्त्वानि यानीह स्थावराणि चराणि च।
महता पांसुवर्षेण नाशं यास्यन्ति सर्वशः॥', 'sarvasattvāni yānīha sthāvarāṇi carāṇi ca
mahatā pāṃsuvarṣeṇa nāśaṃ yāsyanti sarvaśaḥ', null, 7072009),
('ramayana-7-72-10', 10, 'Uttara Kanda, Sarga 72, Verse 10', 'दण्डस्य विषयो यावत्तावत्सर्वसमुच्छ्रयः।
पांसुभुत इवालक्ष्यः सप्तरात्राद्भविष्यति॥', 'daṇḍasya viṣayo yāvat tāvat sarvasamucchrayaḥ
pāṃsubhuta ivālakṣyaḥ saptarātrād bhaviṣyati', null, 7072010),
('ramayana-7-72-11', 11, 'Uttara Kanda, Sarga 72, Verse 11', 'इत्युक्त्वा क्रोधसंतपस्तमाश्रमनिवासिनम्।
जनं जनपदान्तेषु स्थीयतामिति चाब्रवीत्॥', 'ity uktvā krodhasaṃtapas tam āśramanivāsinam
janaṃ janapadānteṣu sthīyatām iti cābravīt', null, 7072011),
('ramayana-7-72-12', 12, 'Uttara Kanda, Sarga 72, Verse 12', 'श्रुत्वा तूशसनो वाक्यं स आश्रमावसथो जनः।
निष्क्रान्तो विषयात्तस्य स्थानं चक्रेऽथ बाह्यतः॥', 'śrutvā tūśasano vākyaṃ sa āśramāvasatho janaḥ
niṣkrānto viṣayāt tasya sthānaṃ cakre ''tha bāhyataḥ', null, 7072012),
('ramayana-7-72-13', 13, 'Uttara Kanda, Sarga 72, Verse 13', 'स तथोक्त्वा मुनिजनमरजामिदमब्रवीत्।
इहैव वस दुर्मेधे आश्रमे सुसमाहिता॥', 'sa tathoktvā munijanam arajām idam abravīt
ihaiva vasa durmedhe āśrame susamāhitā', null, 7072013),
('ramayana-7-72-14', 14, 'Uttara Kanda, Sarga 72, Verse 14', 'इदं योजनपर्यन्तं सरः सुरुचिरप्रभम्।
अरजे विज्वरा भुङ्क्ष्व कालश्चात्र प्रतीक्ष्यताम्॥', 'idaṃ yojanaparyantaṃ saraḥ suruciraprabham
araje vijvarā bhuṅkṣva kālaś cātra pratīkṣyatām', null, 7072014),
('ramayana-7-72-15', 15, 'Uttara Kanda, Sarga 72, Verse 15', 'त्वत्समीपे तु ये सत्त्वा वासमेष्यन्ति तां निशाम्।
अवध्याः पांसुवर्षेण ते भविष्यन्ति नित्यदा॥', 'tvatsamīpe tu ye sattvā vāsam eṣyanti tāṃ niśām
avadhyāḥ pāṃsuvarṣeṇa te bhaviṣyanti nityadā', null, 7072015),
('ramayana-7-72-16', 16, 'Uttara Kanda, Sarga 72, Verse 16', 'इत्युक्त्वा भार्गवो वासमन्यत्र समुपाक्रमत्।
सप्ताहाद्भस्मसाद्भूतं यथोक्तं ब्रह्मवादिना॥', 'ity uktvā bhārgavo vāsam anyatra samupākramat
saptāhād bhasmasādbhūtaṃ yathoktaṃ brahmavādinā', null, 7072016),
('ramayana-7-72-17', 17, 'Uttara Kanda, Sarga 72, Verse 17', 'तस्यासौ दण्डविषयो विन्ध्यशैवलसानुषु।
शप्तो ब्रह्मर्षिणा तेन पुरा वैधर्मके कृते॥', 'tasyāsau daṇḍaviṣayo vindhyaśaivalasānuṣu
śapto brahmarṣiṇā tena purā vaidharmake kṛte', null, 7072017),
('ramayana-7-72-18', 18, 'Uttara Kanda, Sarga 72, Verse 18', 'ततः प्रभृति काकुत्स्थ दण्डकारण्यमुच्यते।
तपस्विनः स्थिता यत्र जनस्थानमथोऽभवत्॥', 'tataḥ prabhṛti kākutstha daṇḍakāraṇyam ucyate
tapasvinaḥ sthitā yatra janasthānam atho ''bhavat', null, 7072018),
('ramayana-7-72-19', 19, 'Uttara Kanda, Sarga 72, Verse 19', 'एतत्ते सर्वमाख्यातं यन्मां पृच्छसि राघव।
संध्यामुपासितुं वीर समयो ह्यतिवर्तते॥', 'etat te sarvam ākhyātaṃ yan māṃ pṛcchasi rāghava
saṃdhyām upāsituṃ vīra samayo hy ativartate', null, 7072019),
('ramayana-7-72-20', 20, 'Uttara Kanda, Sarga 72, Verse 20', 'एते महर्षयः सर्वे पूर्णकुम्भाः समन्ततः।
कृतोदको नरव्याघ्र आदित्यं पर्युपासते॥', 'ete maharṣayaḥ sarve pūrṇakumbhāḥ samantataḥ
kṛtodako naravyāghra ādityaṃ paryupāsate', null, 7072020),
('ramayana-7-72-21', 21, 'Uttara Kanda, Sarga 72, Verse 21', 'स तैरृषिभिरभ्यस्तः सहितैर्ब्रह्मसत्तमैः।
रविरस्तं गतो राम गच्छोदकमुपस्पृश॥', 'sa tair ṛṣibhir abhyastaḥ sahitair brahmasattamaiḥ
ravir astaṃ gato rāma gacchodakam upaspṛśa', null, 7072021)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 73 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-73-1', 1, 'Uttara Kanda, Sarga 73, Verse 1', 'ऋषेर्वचनमाज्ञाय रामः संध्यामुपासितुम्।
उपाक्रामत्सरः पुण्यमप्सरोभिर्निषेवितम्॥', 'ṛṣer vacanam ājñāya rāmaḥ saṃdhyām upāsitum
upākrāmat saraḥ puṇyam apsarobhir niṣevitam', null, 7073001),
('ramayana-7-73-2', 2, 'Uttara Kanda, Sarga 73, Verse 2', 'तत्रोदकमुपस्पृष्श्य संध्यामन्वास्य पश्चिमाम्।
आश्रमं प्राविशद्रामः कुम्भयोनेर्महात्मनः॥', 'tatrodakam upaspṛṣśya saṃdhyām anvāsya paścimām
āśramaṃ prāviśad rāmaḥ kumbhayoner mahātmanaḥ', null, 7073002),
('ramayana-7-73-3', 3, 'Uttara Kanda, Sarga 73, Verse 3', 'अस्यागस्त्यो बहुगुणं फलमूलं तथौषधीः।
शाकानि च पवित्राणि भोजनार्थमकल्पयत्॥', 'asyāgastyo bahuguṇaṃ phalamūlaṃ tathauṣadhīḥ
śākāni ca pavitrāṇi bhojanārtham akalpayat', null, 7073003),
('ramayana-7-73-4', 4, 'Uttara Kanda, Sarga 73, Verse 4', 'स भुक्तवान्नरश्रेष्ठस्तदन्नममृतोपमम्।
प्रीतश्च परितुष्टश्च तां रात्रिं समुपावसत्॥', 'sa bhuktavān naraśreṣṭhas tad annam amṛtopamam
prītaś ca parituṣṭaś ca tāṃ rātriṃ samupāvasat', null, 7073004),
('ramayana-7-73-5', 5, 'Uttara Kanda, Sarga 73, Verse 5', 'प्रभाते काल्यमुत्थाय कृत्वाह्निकमरिंदमः।
ऋषिं समभिचक्राम गमनाय रघूत्तमः॥', 'prabhāte kālyam utthāya kṛtvāhnikam ariṃdamaḥ
ṛṣiṃ samabhicakrāma gamanāya raghūttamaḥ', null, 7073005),
('ramayana-7-73-6', 6, 'Uttara Kanda, Sarga 73, Verse 6', 'अभिवाद्याब्रवीद्रामो महर्षिं कुम्भसंभवम्।
आपृच्छे त्वां गमिष्यामि मामनुज्ञातुमर्हसि॥', 'abhivādyābravīd rāmo maharṣiṃ kumbhasaṃbhavam
āpṛcche tvāṃ gamiṣyāmi mām anujñātum arhasi', null, 7073006),
('ramayana-7-73-7', 7, 'Uttara Kanda, Sarga 73, Verse 7', 'धन्योऽस्म्यनुगृहीतोऽस्मि दर्शनेन महात्मनः।
द्रष्टुं चैवागमिष्यामि पावनार्थमिहात्मनः॥', 'dhanyo ''smy anugṛhīto ''smi darśanena mahātmanaḥ
draṣṭuṃ caivāgamiṣyāmi pāvanārtham ihātmanaḥ', null, 7073007),
('ramayana-7-73-8', 8, 'Uttara Kanda, Sarga 73, Verse 8', 'तथा वदति काकुत्स्थे वाक्यमद्भुतदर्शनम्।
उवाच परमप्रीतो धर्मनेत्रस्तपोधनः॥', 'tathā vadati kākutsthe vākyam adbhutadarśanam
uvāca paramaprīto dharmanetras tapodhanaḥ', null, 7073008),
('ramayana-7-73-9', 9, 'Uttara Kanda, Sarga 73, Verse 9', 'अत्यद्भुतमिदं वाक्यं तव राम शुभाक्षरम्।
पावनः सर्वलोकानां त्वमेव रघुनन्दन॥', 'atyadbhutam idaṃ vākyaṃ tava rāma śubhākṣaram
pāvanaḥ sarvalokānāṃ tvam eva raghunandana', null, 7073009),
('ramayana-7-73-10', 10, 'Uttara Kanda, Sarga 73, Verse 10', 'मुहूर्तमपि राम त्वां ये नु पश्यन्ति के चन।
पाविताः स्वर्गभूतास्ते पूज्यन्ते दिवि दैवतैः॥', 'muhūrtam api rāma tvāṃ ye nu paśyanti ke cana
pāvitāḥ svargabhūtās te pūjyante divi daivataiḥ', null, 7073010),
('ramayana-7-73-11', 11, 'Uttara Kanda, Sarga 73, Verse 11', 'ये च त्वां घोरचक्षुर्भिरीक्षन्ते प्राणिनो भुवि।
हतास्ते यमदण्डेन सद्यो निरयगामिनः॥', 'ye ca tvāṃ ghoracakṣurbhir īkṣante prāṇino bhuvi
hatās te yamadaṇḍena sadyo nirayagāminaḥ', null, 7073011),
('ramayana-7-73-12', 12, 'Uttara Kanda, Sarga 73, Verse 12', 'गच्छ चारिष्टमव्यग्रः पन्थानमकुतोभयम्।
प्रशाधि राज्यं धर्मेण गतिर्हि जगतो भवान्॥', 'gaccha cāriṣṭam avyagraḥ panthānam akutobhayam
praśādhi rājyaṃ dharmeṇa gatir hi jagato bhavān', null, 7073012),
('ramayana-7-73-13', 13, 'Uttara Kanda, Sarga 73, Verse 13', 'एवमुक्तस्तु मुनिना प्राञ्जलिः प्र्पग्रहो नृपः।
अभ्यवादयत प्राज्ञस्तमृषिं पुण्यशीलिनम्॥', 'evam uktas tu muninā prāñjaliḥ prpagraho nṛpaḥ
abhyavādayata prājñas tam ṛṣiṃ puṇyaśīlinam', null, 7073013),
('ramayana-7-73-14', 14, 'Uttara Kanda, Sarga 73, Verse 14', 'अभिवाद्य मुनिश्रेष्ठं तांश्च सर्वांस्तपोधनान्।
अध्यारोहत्तदव्यग्रः पुष्पकं हेमभूषितम्॥', 'abhivādya muniśreṣṭhaṃ tāṃś ca sarvāṃs tapodhanān
adhyārohat tad avyagraḥ puṣpakaṃ hemabhūṣitam', null, 7073014),
('ramayana-7-73-15', 15, 'Uttara Kanda, Sarga 73, Verse 15', 'तं प्रयान्तं मुनिगणा आशीर्वादैः समन्ततः।
अपूजयन्महेन्द्राभं सहस्राक्षमिवामराः॥', 'taṃ prayāntaṃ munigaṇā āśīrvādaiḥ samantataḥ
apūjayan mahendrābhaṃ sahasrākṣam ivāmarāḥ', null, 7073015),
('ramayana-7-73-16', 16, 'Uttara Kanda, Sarga 73, Verse 16', 'स्वस्थः स ददृशे रामः पुष्पके हेमभूषिते।
शशी मेघसमीपस्थो यथा जलधरागमे॥', 'svasthaḥ sa dadṛśe rāmaḥ puṣpake hemabhūṣite
śaśī meghasamīpastho yathā jaladharāgame', null, 7073016),
('ramayana-7-73-17', 17, 'Uttara Kanda, Sarga 73, Verse 17', 'ततोऽर्धदिवसे प्राप्ते पूज्यमानस्ततस्ततः।
अयोध्यां प्राप्य काकुत्स्थो विमानादवरोहत॥', 'tato ''rdhadivase prāpte pūjyamānas tatas tataḥ
ayodhyāṃ prāpya kākutstho vimānād avarohata', null, 7073017),
('ramayana-7-73-18', 18, 'Uttara Kanda, Sarga 73, Verse 18', 'ततो विसृज्य रुचिरं पुष्पकं कामगामिनम्।
कक्ष्यान्तरविनिक्षिप्तं द्वाःस्थं रामोऽब्रवीद्वचः॥', 'tato visṛjya ruciraṃ puṣpakaṃ kāmagāminam
kakṣyāntaravinikṣiptaṃ dvāḥsthaṃ rāmo ''bravīd vacaḥ', null, 7073018),
('ramayana-7-73-19', 19, 'Uttara Kanda, Sarga 73, Verse 19', 'लक्ष्मणं भरतं चैव गत्वा तौ लघुविक्रमौ।
ममागमनमाख्याय शब्दापय च मां चिरम्॥', 'lakṣmaṇaṃ bharataṃ caiva gatvā tau laghuvikramau
mamāgamanam ākhyāya śabdāpaya ca māṃ ciram', null, 7073019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 74 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-74-1', 1, 'Uttara Kanda, Sarga 74, Verse 1', 'तच्छ्रुत्वा भाषितं तस्य रामस्याक्लिष्टकर्मणः।
द्वाःस्थः कुमारावाहूय राघवाय न्यवेदयत्॥', 'tac chrutvā bhāṣitaṃ tasya rāmasyākliṣṭakarmaṇaḥ
dvāḥsthaḥ kumārāv āhūya rāghavāya nyavedayat', null, 7074001),
('ramayana-7-74-2', 2, 'Uttara Kanda, Sarga 74, Verse 2', 'दृष्ट्वा तु राघवः प्राप्तौ प्रियौ भरतलक्ष्मणौ।
परिष्वज्य ततो रामो वाक्यमेतदुवाच ह॥', 'dṛṣṭvā tu rāghavaḥ prāptau priyau bharatalakṣmaṇau
pariṣvajya tato rāmo vākyam etad uvāca ha', null, 7074002),
('ramayana-7-74-3', 3, 'Uttara Kanda, Sarga 74, Verse 3', 'कृतं मया यथातथ्यं द्विजकार्यमनुत्तमम्।
धर्मसेतुमतो भूयः कर्तुमिच्छामि राघवौ॥', 'kṛtaṃ mayā yathātathyaṃ dvijakāryam anuttamam
dharmasetumato bhūyaḥ kartum icchāmi rāghavau', null, 7074003),
('ramayana-7-74-4', 4, 'Uttara Kanda, Sarga 74, Verse 4', 'युवाभ्यामात्मभूताभ्यां राजसूयमनुत्तमम्।
सहितो यष्टुमिच्छामि तत्र धर्मो हि शाश्वतः॥', 'yuvābhyām ātmabhūtābhyāṃ rājasūyam anuttamam
sahito yaṣṭum icchāmi tatra dharmo hi śāśvataḥ', null, 7074004),
('ramayana-7-74-5', 5, 'Uttara Kanda, Sarga 74, Verse 5', 'इष्ट्वा तु राजसूयेन मित्रः शत्रुनिबर्हणः।
सुहुतेन सुयज्ञेन वरुणत्वमुपागमत्॥', 'iṣṭvā tu rājasūyena mitraḥ śatrunibarhaṇaḥ
suhutena suyajñena varuṇatvam upāgamat', null, 7074005),
('ramayana-7-74-6', 6, 'Uttara Kanda, Sarga 74, Verse 6', 'सोमश्च राजसूयेन इष्ट्वा धर्मेण धर्मवित्।
प्राप्तश्च सर्वलोकानां कीर्तिं स्थानं च शाश्वतम्॥', 'somaś ca rājasūyena iṣṭvā dharmeṇa dharmavit
prāptaś ca sarvalokānāṃ kīrtiṃ sthānaṃ ca śāśvatam', null, 7074006),
('ramayana-7-74-7', 7, 'Uttara Kanda, Sarga 74, Verse 7', 'अस्मिन्नहनि यच्छ्रेयश्चिन्त्यतां तन्मया सह।
हितं चायति युक्तं च प्रयतौ वक्तुमर्हथ॥', 'asminn ahani yac chreyaś cintyatāṃ tan mayā saha
hitaṃ cāyati yuktaṃ ca prayatau vaktum arhatha', null, 7074007),
('ramayana-7-74-8', 8, 'Uttara Kanda, Sarga 74, Verse 8', 'श्रुता तु राघवस्यैतद्वाक्यं वाक्यविशारदः।
भरतः प्राञ्जलिर्भूत्वा वाक्यमेतदुवाच ह॥', 'śrutā tu rāghavasyaitad vākyaṃ vākyaviśāradaḥ
bharataḥ prāñjalir bhūtvā vākyam etad uvāca ha', null, 7074008),
('ramayana-7-74-9', 9, 'Uttara Kanda, Sarga 74, Verse 9', 'त्वयि धर्मः परः साधो त्वयि सर्वा वसुंधरा।
प्रतिष्ठिता महाबाहो यशश्चामितविक्रम॥', 'tvayi dharmaḥ paraḥ sādho tvayi sarvā vasuṃdharā
pratiṣṭhitā mahābāho yaśaś cāmitavikrama', null, 7074009),
('ramayana-7-74-10', 10, 'Uttara Kanda, Sarga 74, Verse 10', 'महीपालाश्च सर्वे त्वां प्रजापतिमिवामराः।
निरीक्षन्ते महात्मानो लोकनाथं यथा वयम्॥', 'mahīpālāś ca sarve tvāṃ prajāpatim ivāmarāḥ
nirīkṣante mahātmāno lokanāthaṃ yathā vayam', null, 7074010),
('ramayana-7-74-11', 11, 'Uttara Kanda, Sarga 74, Verse 11', 'प्रजाश्च पितृवद्राजन्पश्यन्ति त्वां महाबल।
पृथिव्यां गतिभूतोऽसि प्राणिनामपि राघव॥', 'prajāś ca pitṛvad rājan paśyanti tvāṃ mahābala
pṛthivyāṃ gatibhūto ''si prāṇinām api rāghava', null, 7074011),
('ramayana-7-74-12', 12, 'Uttara Kanda, Sarga 74, Verse 12', 'स त्वमेवंविधं यज्ञमाहर्तासि कथं नृप।
पृथिव्यां राजवंशानां विनाशो यत्र दृश्यते॥', 'sa tvam evaṃvidhaṃ yajñam āhartāsi kathaṃ nṛpa
pṛthivyāṃ rājavaṃśānāṃ vināśo yatra dṛśyate', null, 7074012),
('ramayana-7-74-13', 13, 'Uttara Kanda, Sarga 74, Verse 13', 'पृथिव्यां ये च पुरुषा राजन्पौरुषमागताः।
सर्वेषां भविता तत्र क्षयः सर्वान्तकोपमः॥', 'pṛthivyāṃ ye ca puruṣā rājan pauruṣam āgatāḥ
sarveṣāṃ bhavitā tatra kṣayaḥ sarvāntakopamaḥ', null, 7074013),
('ramayana-7-74-14', 14, 'Uttara Kanda, Sarga 74, Verse 14', 'स त्वं पुरुषशार्दूल गुणैरतुलविक्रम।
पृथिवीं नार्हसे हन्तुं वशे हि तव वर्तते॥', 'sa tvaṃ puruṣaśārdūla guṇair atulavikrama
pṛthivīṃ nārhase hantuṃ vaśe hi tava vartate', null, 7074014),
('ramayana-7-74-15', 15, 'Uttara Kanda, Sarga 74, Verse 15', 'भरतस्य तु तद्वाक्यं श्रुत्वामृतमयं यथा।
प्रहर्षमतुलं लेभे रामः सत्यपराक्रमः॥', 'bharatasya tu tad vākyaṃ śrutvāmṛtamayaṃ yathā
praharṣam atulaṃ lebhe rāmaḥ satyaparākramaḥ', null, 7074015),
('ramayana-7-74-16', 16, 'Uttara Kanda, Sarga 74, Verse 16', 'उवाच च शुभां वाणीं कैकेय्या नन्दिवर्धनम्।
प्रीतोऽस्मि परितुष्टोऽस्मि तवाद्य वचनेन हि॥', 'uvāca ca śubhāṃ vāṇīṃ kaikeyyā nandivardhanam
prīto ''smi parituṣṭo ''smi tavādya vacanena hi', null, 7074016),
('ramayana-7-74-17', 17, 'Uttara Kanda, Sarga 74, Verse 17', 'इदं वचनमक्लीबं त्वया धर्मसमाहितम्।
व्याहृतं पुरुषव्याघ्र पृथिव्याः परिपालनम्॥', 'idaṃ vacanam aklībaṃ tvayā dharmasamāhitam
vyāhṛtaṃ puruṣavyāghra pṛthivyāḥ paripālanam', null, 7074017),
('ramayana-7-74-18', 18, 'Uttara Kanda, Sarga 74, Verse 18', 'एष तस्मादभिप्रायाद्राजसूयात्क्रतूत्तमान्।
निवर्तयामि धर्मज्ञ तव सुव्याहृतेन वै॥', 'eṣa tasmād abhiprāyād rājasūyāt kratūttamān
nivartayāmi dharmajña tava suvyāhṛtena vai', null, 7074018),
('ramayana-7-74-19', 19, 'Uttara Kanda, Sarga 74, Verse 19', 'प्रजानां पालनं धर्मो राज्ञां यज्ञेन संमितः।
तस्माच्छृणोमि ते वाक्यं साधूक्तं सुसमाहितम्॥', 'prajānāṃ pālanaṃ dharmo rājñāṃ yajñena saṃmitaḥ
tasmāc chṛṇomi te vākyaṃ sādhūktaṃ susamāhitam', null, 7074019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 75 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-75-1', 1, 'Uttara Kanda, Sarga 75, Verse 1', 'तथोक्तवति रामे तु भरते च महात्मनि।
लक्ष्मणोऽपि शुभं वाक्यमुवाच रघुनन्दनम्॥', 'tathoktavati rāme tu bharate ca mahātmani
lakṣmaṇo ''pi śubhaṃ vākyam uvāca raghunandanam', null, 7075001),
('ramayana-7-75-2', 2, 'Uttara Kanda, Sarga 75, Verse 2', 'अश्वमेधो महायज्ञः पावनः सर्वपाप्मनाम्।
पावनस्तव दुर्धर्षो रोचतां क्रतुपुंगवः॥', 'aśvamedho mahāyajñaḥ pāvanaḥ sarvapāpmanām
pāvanas tava durdharṣo rocatāṃ kratupuṃgavaḥ', null, 7075002),
('ramayana-7-75-3', 3, 'Uttara Kanda, Sarga 75, Verse 3', 'श्रूयते हि पुरावृत्तं वासवे सुमहात्मनि।
ब्रह्महत्यावृतः शक्रो हयमेधेन पावितः॥', 'śrūyate hi purāvṛttaṃ vāsave sumahātmani
brahmahatyāvṛtaḥ śakro hayamedhena pāvitaḥ', null, 7075003),
('ramayana-7-75-4', 4, 'Uttara Kanda, Sarga 75, Verse 4', 'पुरा किल महाबाहो देवासुरसमागमे।
वृत्रो नाम महानासीद्दैतेयो लोकसंमतः॥', 'purā kila mahābāho devāsurasamāgame
vṛtro nāma mahān āsīd daiteyo lokasaṃmataḥ', null, 7075004),
('ramayana-7-75-5', 5, 'Uttara Kanda, Sarga 75, Verse 5', 'विस्तीर्णा योजनशतमुच्छ्रितस्त्रिगुणं ततः।
अनुरागेण लोकांस्त्रीन्स्नेहात्पश्यति सर्वतः॥', 'vistīrṇā yojanaśatam ucchritas triguṇaṃ tataḥ
anurāgeṇa lokāṃs trīn snehāt paśyati sarvataḥ', null, 7075005),
('ramayana-7-75-6', 6, 'Uttara Kanda, Sarga 75, Verse 6', 'धर्मज्ञश्च कृतज्ञश्च बुद्ध्या च परिनिष्ठितः।
शशास पृथिवीं सर्वां धर्मेण सुसमाहितः॥', 'dharmajñaś ca kṛtajñaś ca buddhyā ca pariniṣṭhitaḥ
śaśāsa pṛthivīṃ sarvāṃ dharmeṇa susamāhitaḥ', null, 7075006),
('ramayana-7-75-7', 7, 'Uttara Kanda, Sarga 75, Verse 7', 'तस्मिन्प्रशासति तदा सर्वकामदुघा मही।
रसवन्ति प्रसूतानि मूलानि च फलानि च॥', 'tasmin praśāsati tadā sarvakāmadughā mahī
rasavanti prasūtāni mūlāni ca phalāni ca', null, 7075007),
('ramayana-7-75-8', 8, 'Uttara Kanda, Sarga 75, Verse 8', 'अकृष्टपच्या पृथिवी सुसंपन्ना महात्मनः।
स राज्यं तादृशं भुङ्क्ते स्फीतमद्भुतदर्शनम्॥', 'akṛṣṭapacyā pṛthivī susaṃpannā mahātmanaḥ
sa rājyaṃ tādṛśaṃ bhuṅkte sphītam adbhutadarśanam', null, 7075008),
('ramayana-7-75-9', 9, 'Uttara Kanda, Sarga 75, Verse 9', 'तस्य बुद्धिः समुत्पन्ना तपः कुर्यामनुत्तमम्।
तपो हि परमं श्रेयस्तपो हि परमं सुखम्॥', 'tasya buddhiḥ samutpannā tapaḥ kuryām anuttamam
tapo hi paramaṃ śreyas tapo hi paramaṃ sukham', null, 7075009),
('ramayana-7-75-10', 10, 'Uttara Kanda, Sarga 75, Verse 10', 'स निक्षिप्य सुतं ज्येष्ठं पौरेषु परमेश्वरम्।
तप उग्रमुपातिष्ठत्तापयन्सर्वदेवताः॥', 'sa nikṣipya sutaṃ jyeṣṭhaṃ paureṣu parameśvaram
tapa ugram upātiṣṭhat tāpayan sarvadevatāḥ', null, 7075010),
('ramayana-7-75-11', 11, 'Uttara Kanda, Sarga 75, Verse 11', 'तपस्तप्यति वृत्रे तु वासवः परमार्तवत्।
विष्णुं समुपसंक्रम्य वाक्यमेतदुवाच ह॥', 'tapas tapyati vṛtre tu vāsavaḥ paramārtavat
viṣṇuṃ samupasaṃkramya vākyam etad uvāca ha', null, 7075011),
('ramayana-7-75-12', 12, 'Uttara Kanda, Sarga 75, Verse 12', 'तपस्यता महाबाहो लोका वृत्रेण निर्जिताः।
बलवान्स हि धर्मात्मा नैनं शक्ष्यामि बाधितुम्॥', 'tapasyatā mahābāho lokā vṛtreṇa nirjitāḥ
balavān sa hi dharmātmā nainaṃ śakṣyāmi bādhitum', null, 7075012),
('ramayana-7-75-13', 13, 'Uttara Kanda, Sarga 75, Verse 13', 'यद्यसौ तप आतिष्ठेद्भूय एव सुरेश्वर।
यावल्लोका धरिष्यन्ति तावदस्य वशानुगाः॥', 'yady asau tapa ātiṣṭhed bhūya eva sureśvara
yāval lokā dhariṣyanti tāvad asya vaśānugāḥ', null, 7075013),
('ramayana-7-75-14', 14, 'Uttara Kanda, Sarga 75, Verse 14', 'त्वं चैनं परमोदारमुपेक्षसि महाबल।
क्षणं हि न भवेद्वृत्रः क्रुद्धे त्वयि सुरेश्वर॥', 'tvaṃ cainaṃ paramodāram upekṣasi mahābala
kṣaṇaṃ hi na bhaved vṛtraḥ kruddhe tvayi sureśvara', null, 7075014),
('ramayana-7-75-15', 15, 'Uttara Kanda, Sarga 75, Verse 15', 'यदा हि प्रीतिसंयोगं त्वया विष्णो समागतः।
तदा प्रभृति लोकानां नाथत्वमुपलब्धवान्॥', 'yadā hi prītisaṃyogaṃ tvayā viṣṇo samāgataḥ
tadā prabhṛti lokānāṃ nāthatvam upalabdhavān', null, 7075015),
('ramayana-7-75-16', 16, 'Uttara Kanda, Sarga 75, Verse 16', 'स त्वं प्रसादं लोकानां कुरुष्व सुमहायशः।
त्वत्कृतेन हि सर्वं स्यात्प्रशान्तमजरं जगत्॥', 'sa tvaṃ prasādaṃ lokānāṃ kuruṣva sumahāyaśaḥ
tvatkṛtena hi sarvaṃ syāt praśāntam ajaraṃ jagat', null, 7075016),
('ramayana-7-75-17', 17, 'Uttara Kanda, Sarga 75, Verse 17', 'इमे हि सर्वे विष्णो त्वां निरीक्षन्ते दिवौकसः।
वृत्रघतेन महता एषां साह्यं कुरुष्व ह॥', 'ime hi sarve viṣṇo tvāṃ nirīkṣante divaukasaḥ
vṛtraghatena mahatā eṣāṃ sāhyaṃ kuruṣva ha', null, 7075017),
('ramayana-7-75-18', 18, 'Uttara Kanda, Sarga 75, Verse 18', 'त्वया हि नित्यशः साह्यं कृतमेषां महात्मनाम्।
असह्यमिदमन्येषामगतीनां गतिर्भवान्॥', 'tvayā hi nityaśaḥ sāhyaṃ kṛtam eṣāṃ mahātmanām
asahyam idam anyeṣām agatīnāṃ gatir bhavān', null, 7075018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 76 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-76-1', 1, 'Uttara Kanda, Sarga 76, Verse 1', 'लक्ष्मणस्य तु तद्वाक्यं श्रुत्वा शत्रुनिबर्हणः।
वृत्रघातमशेषेण कथयेत्याह लक्ष्मणम्॥', 'lakṣmaṇasya tu tad vākyaṃ śrutvā śatrunibarhaṇaḥ
vṛtraghātam aśeṣeṇa kathayety āha lakṣmaṇam', null, 7076001),
('ramayana-7-76-2', 2, 'Uttara Kanda, Sarga 76, Verse 2', 'राघवेणैवमुक्तस्तु सुमित्रानन्दवर्धनः।
भूय एव कथां दिव्यां कथयामास लक्ष्मणः॥', 'rāghaveṇaivam uktas tu sumitrānandavardhanaḥ
bhūya eva kathāṃ divyāṃ kathayām āsa lakṣmaṇaḥ', null, 7076002),
('ramayana-7-76-3', 3, 'Uttara Kanda, Sarga 76, Verse 3', 'सहस्राक्षवचः श्रुत्वा सर्वेषां च दिवौकसाम्।
विष्णुर्देवानुवाचेदं सर्वानिन्द्रपुरोगमान्॥', 'sahasrākṣavacaḥ śrutvā sarveṣāṃ ca divaukasām
viṣṇur devān uvācedaṃ sarvān indrapurogamān', null, 7076003),
('ramayana-7-76-4', 4, 'Uttara Kanda, Sarga 76, Verse 4', 'पूर्वं सौहृदबद्धोऽस्मि वृत्रस्य सुमहात्मनः।
तेन युष्मत्प्रियार्थं वै नाहं हन्मि महासुरम्॥', 'pūrvaṃ sauhṛdabaddho ''smi vṛtrasya sumahātmanaḥ
tena yuṣmat priyārthaṃ vai nāhaṃ hanmi mahāsuram', null, 7076004),
('ramayana-7-76-5', 5, 'Uttara Kanda, Sarga 76, Verse 5', 'अवश्यं करणीयं च भवतां सुखमुत्तमम्।
तस्मादुपायमाख्यास्ये येन वृत्रं हनिष्यथ॥', 'avaśyaṃ karaṇīyaṃ ca bhavatāṃ sukham uttamam
tasmād upāyam ākhyāsye yena vṛtraṃ haniṣyatha', null, 7076005),
('ramayana-7-76-6', 6, 'Uttara Kanda, Sarga 76, Verse 6', 'त्रिधा भूतं करिष्येऽहमात्मानं सुरसत्तमाः।
तेन वृत्रं सहस्राक्षो हनिष्यति न संशयः॥', 'tridhā bhūtaṃ kariṣye ''ham ātmānaṃ surasattamāḥ
tena vṛtraṃ sahasrākṣo haniṣyati na saṃśayaḥ', null, 7076006),
('ramayana-7-76-7', 7, 'Uttara Kanda, Sarga 76, Verse 7', 'एकोऽंशो वासवं यातु द्वितीयो वज्रमेव तु।
तृतीयो भूतलं शक्रस्ततो वृत्रं हनिष्यति॥', 'eko ''ṃśo vāsavaṃ yātu dvitīyo vajram eva tu
tṛtīyo bhūtalaṃ śakras tato vṛtraṃ haniṣyati', null, 7076007),
('ramayana-7-76-8', 8, 'Uttara Kanda, Sarga 76, Verse 8', 'तथा ब्रुवति देवेशे देवा वाक्यमथाब्रुवन्।
एवमेतन्न संदेहो यथा वदसि दैत्यहन्॥', 'tathā bruvati deveśe devā vākyam athābruvan
evam etan na saṃdeho yathā vadasi daityahan', null, 7076008),
('ramayana-7-76-9', 9, 'Uttara Kanda, Sarga 76, Verse 9', 'भद्रं तेऽस्तु गमिष्यामो वृत्रासुरवधैषिणः।
भजस्व परमोदारवासवं स्वेन तेजसा॥', 'bhadraṃ te ''stu gamiṣyāmo vṛtrāsuravadhaiṣiṇaḥ
bhajasva paramodāravāsavaṃ svena tejasā', null, 7076009),
('ramayana-7-76-10', 10, 'Uttara Kanda, Sarga 76, Verse 10', 'ततः सर्वे महात्मानः सहस्राक्षपुरोगमाः।
तदरण्यमुपाक्रामन्यत्र वृत्रो महासुरः॥', 'tataḥ sarve mahātmānaḥ sahasrākṣapurogamāḥ
tad araṇyam upākrāman yatra vṛtro mahāsuraḥ', null, 7076010),
('ramayana-7-76-11', 11, 'Uttara Kanda, Sarga 76, Verse 11', 'तेऽपश्यंस्तेजसा भूतं तपन्तमसुरोत्तमम्।
पिबन्तमिव लोकांस्त्रीन्निर्दहन्तमिवाम्बरम्॥', 'te ''paśyaṃs tejasā bhūtaṃ tapantam asurottamam
pibantam iva lokāṃs trīn nirdahantam ivāmbaram', null, 7076011),
('ramayana-7-76-12', 12, 'Uttara Kanda, Sarga 76, Verse 12', 'दृष्ट्वैव चासुरश्रेष्ठं देवास्त्रासमुपागमन्।
कथमेनं वधिष्यामः कथं न स्यात्पराजयः॥', 'dṛṣṭvaiva cāsuraśreṣṭhaṃ devās trāsam upāgaman
katham enaṃ vadhiṣyāmaḥ kathaṃ na syāt parājayaḥ', null, 7076012),
('ramayana-7-76-13', 13, 'Uttara Kanda, Sarga 76, Verse 13', 'तेषां चिन्तयतां तत्र सहस्राक्षः पुरंदरः।
वज्रं प्रगृह्य बाहुभ्यां प्रहिणोद्वृत्रमूर्धनि॥', 'teṣāṃ cintayatāṃ tatra sahasrākṣaḥ puraṃdaraḥ
vajraṃ pragṛhya bāhubhyāṃ prahiṇod vṛtramūrdhani', null, 7076013),
('ramayana-7-76-14', 14, 'Uttara Kanda, Sarga 76, Verse 14', 'कालाग्निनेव घोरेण दीप्तेनेव महार्चिषा।
प्रतप्तं वृत्रशिरसि जगत्त्रासमुपागमत्॥', 'kālāgnineva ghoreṇa dīpteneva mahārciṣā
prataptaṃ vṛtraśirasi jagat trāsam upāgamat', null, 7076014),
('ramayana-7-76-15', 15, 'Uttara Kanda, Sarga 76, Verse 15', 'असंभाव्यं वधं तस्य वृत्रस्य विबुधाधिपः।
चिन्तयानो जगामाशु लोकस्यान्तं महायशाः॥', 'asaṃbhāvyaṃ vadhaṃ tasya vṛtrasya vibudhādhipaḥ
cintayāno jagāmāśu lokasyāntaṃ mahāyaśāḥ', null, 7076015),
('ramayana-7-76-16', 16, 'Uttara Kanda, Sarga 76, Verse 16', 'तमिन्द्रं ब्रह्महत्याशु गच्छन्तमनुगच्छति।
अपतच्चास्य गात्रेषु तमिन्द्रं दुःखमाविशत्॥', 'tam indraṃ brahmahatyāśu gacchantam anugacchati
apatac cāsya gātreṣu tam indraṃ duḥkham āviśat', null, 7076016),
('ramayana-7-76-17', 17, 'Uttara Kanda, Sarga 76, Verse 17', 'हतारयः प्रनष्टेन्द्रा देवाः साग्निपुरोगमाः।
विष्णुं त्रिभुवणश्रेष्ठं मुहुर्मुहुरपूजयन्॥', 'hatārayaḥ pranaṣṭendrā devāḥ sāgnipurogamāḥ
viṣṇuṃ tribhuvaṇaśreṣṭhaṃ muhur muhur apūjayan', null, 7076017),
('ramayana-7-76-18', 18, 'Uttara Kanda, Sarga 76, Verse 18', 'त्वं गतिः परमा देव पूर्वजो जगतः प्रभुः।
रथार्थं सर्वभूतानां विष्णुत्वमुपजग्मिवान्॥', 'tvaṃ gatiḥ paramā deva pūrvajo jagataḥ prabhuḥ
rathārthaṃ sarvabhūtānāṃ viṣṇutvam upajagmivān', null, 7076018),
('ramayana-7-76-19', 19, 'Uttara Kanda, Sarga 76, Verse 19', 'हतश्चायं त्वया वृत्रो ब्रह्महत्या च वासवम्।
बाधते सुरशार्दूल मोक्षं तस्य विनिर्दिश॥', 'hataś cāyaṃ tvayā vṛtro brahmahatyā ca vāsavam
bādhate suraśārdūla mokṣaṃ tasya vinirdiśa', null, 7076019),
('ramayana-7-76-20', 20, 'Uttara Kanda, Sarga 76, Verse 20', 'तेषां तद्वचनं श्रुत्वा देवानां विष्णुरब्रवीत्।
मामेव यजतां शक्रः पावयिष्यामि वज्रिणम्॥', 'teṣāṃ tad vacanaṃ śrutvā devānāṃ viṣṇur abravīt
mām eva yajatāṃ śakraḥ pāvayiṣyāmi vajriṇam', null, 7076020),
('ramayana-7-76-21', 21, 'Uttara Kanda, Sarga 76, Verse 21', 'पुण्येन हयमेधेन मामिष्ट्वा पाकशासनः।
पुनरेष्यति देवानामिन्द्रत्वमकुतोभयः॥', 'puṇyena hayamedhena mām iṣṭvā pākaśāsanaḥ
punar eṣyati devānām indratvam akutobhayaḥ', null, 7076021),
('ramayana-7-76-22', 22, 'Uttara Kanda, Sarga 76, Verse 22', 'एवं संदिश्य देवानां तां वाणीममृतोपमा।
जगाम विष्णुर्देवेशः स्तूयमानस्त्रिविष्टपम्॥', 'evaṃ saṃdiśya devānāṃ tāṃ vāṇīm amṛtopamā
jagāma viṣṇur deveśaḥ stūyamānas triviṣṭapam', null, 7076022)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 77 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-77-1', 1, 'Uttara Kanda, Sarga 77, Verse 1', 'तथा वृत्रवधं सर्वमखिलेन स लक्ष्मणः।
कथयित्वा नरश्रेष्ठः कथाशेषमुपाक्रमत्॥', 'tathā vṛtravadhaṃ sarvam akhilena sa lakṣmaṇaḥ
kathayitvā naraśreṣṭhaḥ kathāśeṣam upākramat', null, 7077001),
('ramayana-7-77-2', 2, 'Uttara Kanda, Sarga 77, Verse 2', 'ततो हते महावीर्ये वृत्रे देवभयंकरे।
ब्रह्महत्यावृतः शक्रः संज्ञां लेभे न वृत्रहा॥', 'tato hate mahāvīrye vṛtre devabhayaṃkare
brahmahatyāvṛtaḥ śakraḥ saṃjñāṃ lebhe na vṛtrahā', null, 7077002),
('ramayana-7-77-3', 3, 'Uttara Kanda, Sarga 77, Verse 3', 'सोऽन्तमाश्रित्य लोकानां नष्टसंज्ञो विचेतनः।
कालं तत्रावसत्कं चिद्वेष्टमानो यथोरगः॥', 'so ''ntam āśritya lokānāṃ naṣṭasaṃjño vicetanaḥ
kālaṃ tatrāvasat kaṃ cid veṣṭamāno yathoragaḥ', null, 7077003),
('ramayana-7-77-4', 4, 'Uttara Kanda, Sarga 77, Verse 4', 'अथ नष्टे सहस्राक्षे उद्विग्नमभवज्जगत्।
भूमिश्च ध्वस्तसंकाशा निःस्नेहा शुष्ककानना॥', 'atha naṣṭe sahasrākṣe udvignam abhavaj jagat
bhūmiś ca dhvastasaṃkāśā niḥsnehā śuṣkakānanā', null, 7077004),
('ramayana-7-77-5', 5, 'Uttara Kanda, Sarga 77, Verse 5', 'निःस्रोतसश्चाम्बुवाहा ह्रदाश्च सरितस्तथा।
संक्षोभश्चैव सत्त्वानामनावृष्टिकृतोऽभवत्॥', 'niḥsrotasaś cāmbuvāhā hradāś ca saritas tathā
saṃkṣobhaś caiva sattvānām anāvṛṣṭikṛto ''bhavat', null, 7077005),
('ramayana-7-77-6', 6, 'Uttara Kanda, Sarga 77, Verse 6', 'क्षीयमाणे तु लोकेऽस्मिन्संभ्रान्तमनसः सुराः।
यदुक्तं विष्णुना पूर्वं तं यज्ञं समुपानयन्॥', 'kṣīyamāṇe tu loke ''smin saṃbhrāntamanasaḥ surāḥ
yad uktaṃ viṣṇunā pūrvaṃ taṃ yajñaṃ samupānayan', null, 7077006),
('ramayana-7-77-7', 7, 'Uttara Kanda, Sarga 77, Verse 7', 'ततः सर्वे सुरगणाः सोपाध्यायाः सहर्षिभिः।
तं देशं सहिता जग्मुर्यत्रेन्द्रो भयमोहितः॥', 'tataḥ sarve suragaṇāḥ sopādhyāyāḥ saharṣibhiḥ
taṃ deśaṃ sahitā jagmur yatrendro bhayamohitaḥ', null, 7077007),
('ramayana-7-77-8', 8, 'Uttara Kanda, Sarga 77, Verse 8', 'ते तु दृष्ट्वा सहस्राक्षं मोहितं ब्रह्महत्यया।
तं पुरस्कृत्य देवेशमश्वमेधं प्रचक्रिरे॥', 'te tu dṛṣṭvā sahasrākṣaṃ mohitaṃ brahmahatyayā
taṃ puraskṛtya deveśam aśvamedhaṃ pracakrire', null, 7077008),
('ramayana-7-77-9', 9, 'Uttara Kanda, Sarga 77, Verse 9', 'ततोऽश्वमेधः सुमहान्महेन्द्रस्य महात्मनः।
ववृधे ब्रह्महत्यायाः पावनार्थं नरेश्वर॥', 'tato ''śvamedhaḥ sumahān mahendrasya mahātmanaḥ
vavṛdhe brahmahatyāyāḥ pāvanārthaṃ nareśvara', null, 7077009),
('ramayana-7-77-10', 10, 'Uttara Kanda, Sarga 77, Verse 10', 'ततो यज्ञसमाप्तौ तु ब्रह्महत्या महात्मनः।
अभिगम्याब्रवीद्वाक्यं क्व मे स्थानं विधास्यथ॥', 'tato yajñasamāptau tu brahmahatyā mahātmanaḥ
abhigamyābravīd vākyaṃ kva me sthānaṃ vidhāsyatha', null, 7077010),
('ramayana-7-77-11', 11, 'Uttara Kanda, Sarga 77, Verse 11', 'ते तामूचुस्ततो देवास्तुष्टाः प्रीतिसमन्विताः।
चतुर्धा विभजात्मानमात्मनैव दुरासदे॥', 'te tām ūcus tato devās tuṣṭāḥ prītisamanvitāḥ
caturdhā vibhajātmānam ātmanaiva durāsade', null, 7077011),
('ramayana-7-77-12', 12, 'Uttara Kanda, Sarga 77, Verse 12', 'देवानां भाषितं श्रुत्वा ब्रह्महत्या महात्मनाम्।
संनिधौ स्थानमन्यत्र वरयामास दुर्वसा॥', 'devānāṃ bhāṣitaṃ śrutvā brahmahatyā mahātmanām
saṃnidhau sthānam anyatra varayām āsa durvasā', null, 7077012),
('ramayana-7-77-13', 13, 'Uttara Kanda, Sarga 77, Verse 13', 'एकेनांशेन वत्स्यामि पूर्णोदासु नदीषु वै।
द्वितीयेन तु वृक्षेषु सत्यमेतद्ब्रवीमि वः॥', 'ekenāṃśena vatsyāmi pūrṇodāsu nadīṣu vai
dvitīyena tu vṛkṣeṣu satyam etad bravīmi vaḥ', null, 7077013),
('ramayana-7-77-14', 14, 'Uttara Kanda, Sarga 77, Verse 14', 'योऽयमंशस्तृतीयो मे स्त्रीषु यौवनशालिषु।
त्रिरात्रं दर्पपर्णासु वसिष्ये दर्पघातिनी॥', 'yo ''yam aṃśas tṛtīyo me strīṣu yauvanaśāliṣu
trirātraṃ darpaparṇāsu vasiṣye darpaghātinī', null, 7077014),
('ramayana-7-77-15', 15, 'Uttara Kanda, Sarga 77, Verse 15', 'हन्तारो ब्राह्मणान्ये तु प्रेक्षापूर्वमदूषकान्।
तांश्चतुर्थेन भागेन संश्रयिष्ये सुरर्षभाः॥', 'hantāro brāhmaṇān ye tu prekṣāpūrvam adūṣakān
tāṃś caturthena bhāgena saṃśrayiṣye surarṣabhāḥ', null, 7077015),
('ramayana-7-77-16', 16, 'Uttara Kanda, Sarga 77, Verse 16', 'प्रत्यूचुस्तां ततो देवा यथा वदसि दुर्वसे।
तथा भवतु तत्सर्वं साधयस्व यथेप्सितम्॥', 'pratyūcus tāṃ tato devā yathā vadasi durvase
tathā bhavatu tat sarvaṃ sādhayasva yathepsitam', null, 7077016),
('ramayana-7-77-17', 17, 'Uttara Kanda, Sarga 77, Verse 17', 'ततः प्रीत्यान्विता देवाः सहस्राक्षं ववन्दिरे।
विज्वरः पूतपाप्मा च वासवः समपद्यत॥', 'tataḥ prītyānvitā devāḥ sahasrākṣaṃ vavandire
vijvaraḥ pūtapāpmā ca vāsavaḥ samapadyata', null, 7077017),
('ramayana-7-77-18', 18, 'Uttara Kanda, Sarga 77, Verse 18', 'प्रशान्तं च जगत्सर्वं सहस्राक्षे प्रतिष्ठते।
यज्ञं चाद्भुतसंकाशं तदा शक्रोऽभ्यपूजयत्॥', 'praśāntaṃ ca jagat sarvaṃ sahasrākṣe pratiṣṭhate
yajñaṃ cādbhutasaṃkāśaṃ tadā śakro ''bhyapūjayat', null, 7077018),
('ramayana-7-77-19', 19, 'Uttara Kanda, Sarga 77, Verse 19', 'ईदृशो ह्यश्वमेधस्य प्रभावो रघुनन्दन।
यजस्व सुमहाभाग हयमेधेन पार्थिव॥', 'īdṛśo hy aśvamedhasya prabhāvo raghunandana
yajasva sumahābhāga hayamedhena pārthiva', null, 7077019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 78 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-78-1', 1, 'Uttara Kanda, Sarga 78, Verse 1', 'तच्छ्रुत्वा लक्ष्मणेनोक्तं वाक्यं वाक्यविशारदः।
प्रत्युवाच महातेजाः प्रहसन्राघवो वचः॥', 'tac chrutvā lakṣmaṇenoktaṃ vākyaṃ vākyaviśāradaḥ
pratyuvāca mahātejāḥ prahasan rāghavo vacaḥ', null, 7078001),
('ramayana-7-78-2', 2, 'Uttara Kanda, Sarga 78, Verse 2', 'एवमेतन्नरश्रेष्ठ यथा वदसि लक्ष्मण।
वृत्रघातमशेषेण वाजिमेधफलं च यत्॥', 'evam etan naraśreṣṭha yathā vadasi lakṣmaṇa
vṛtraghātam aśeṣeṇa vājimedhaphalaṃ ca yat', null, 7078002),
('ramayana-7-78-3', 3, 'Uttara Kanda, Sarga 78, Verse 3', 'श्रूयते हि पुरा सौम्य कर्दमस्य प्रजापतेः।
पुत्रो बाह्लीश्वरः श्रीमानिलो नाम सुधार्मिकः॥', 'śrūyate hi purā saumya kardamasya prajāpateḥ
putro bāhlīśvaraḥ śrīmān ilo nāma sudhārmikaḥ', null, 7078003),
('ramayana-7-78-4', 4, 'Uttara Kanda, Sarga 78, Verse 4', 'स राजा पृथिवीं सर्वां वशे कृत्वा महायशाः।
राज्यं चैव नरव्याघ्र पुत्रवत्पर्यपालयत्॥', 'sa rājā pṛthivīṃ sarvāṃ vaśe kṛtvā mahāyaśāḥ
rājyaṃ caiva naravyāghra putravat paryapālayat', null, 7078004),
('ramayana-7-78-5', 5, 'Uttara Kanda, Sarga 78, Verse 5', 'सुरैश्च परमोदारैर्दैतेयैश्च महासुरैः।
नागराक्षसगन्धर्वैर्यक्षैश्च सुमहात्मभिः॥', 'suraiś ca paramodārair daiteyaiś ca mahāsuraiḥ
nāgarākṣasagandharvair yakṣaiś ca sumahātmabhiḥ', null, 7078005),
('ramayana-7-78-6', 6, 'Uttara Kanda, Sarga 78, Verse 6', 'पूज्यते नित्यशः सौम्य भयार्तै रघुनन्दन।
अबिभ्यंश्च त्रयो लोकाः सरोषस्य महात्मनः॥', 'pūjyate nityaśaḥ saumya bhayārtai raghunandana
abibhyaṃś ca trayo lokāḥ saroṣasya mahātmanaḥ', null, 7078006),
('ramayana-7-78-7', 7, 'Uttara Kanda, Sarga 78, Verse 7', 'स राजा तादृशो ह्यासीद्धर्मे वीर्ये च निष्ठितः।
बुद्ध्या च परमोदारो बाह्लीकानां महायशाः॥', 'sa rājā tādṛśo hy āsīd dharme vīrye ca niṣṭhitaḥ
buddhyā ca paramodāro bāhlīkānāṃ mahāyaśāḥ', null, 7078007),
('ramayana-7-78-8', 8, 'Uttara Kanda, Sarga 78, Verse 8', 'स प्रचक्रे महाबाहुर्मृगयां रुचिरे वने।
चैत्रे मनोरमे मासि सभृत्यबलवाहनः॥', 'sa pracakre mahābāhur mṛgayāṃ rucire vane
caitre manorame māsi sabhṛtyabalavāhanaḥ', null, 7078008),
('ramayana-7-78-9', 9, 'Uttara Kanda, Sarga 78, Verse 9', 'प्रजघ्ने स नृपोऽरण्ये मृगाञ्शतसहस्रशः।
हत्वैव तृप्तिर्नाभूच्च राज्ञस्तस्य महात्मनः॥', 'prajaghne sa nṛpo ''raṇye mṛgāñ śatasahasraśaḥ
hatvaiva tṛptir nābhūc ca rājñas tasya mahātmanaḥ', null, 7078009),
('ramayana-7-78-10', 10, 'Uttara Kanda, Sarga 78, Verse 10', 'नानामृगाणामयुतं वध्यमानं महात्मना।
यत्र जातो महासेनस्तं देशमुपचक्रमे॥', 'nānāmṛgāṇām ayutaṃ vadhyamānaṃ mahātmanā
yatra jāto mahāsenas taṃ deśam upacakrame', null, 7078010),
('ramayana-7-78-11', 11, 'Uttara Kanda, Sarga 78, Verse 11', 'तस्मिंस्तु देवदेवेशः शैलराजसुतां हरः।
रमयामास दुर्धर्षैः सर्वैरनुचरैः सह॥', 'tasmiṃs tu devadeveśaḥ śailarājasutāṃ haraḥ
ramayām āsa durdharṣaiḥ sarvair anucaraiḥ saha', null, 7078011),
('ramayana-7-78-12', 12, 'Uttara Kanda, Sarga 78, Verse 12', 'कृत्वा स्त्रीभूतमात्मानमुमेशो गोपतिध्वजः।
देव्याः प्रियचिकीर्षुः स तस्मिन्पर्वतनिर्झरे॥', 'kṛtvā strībhūtam ātmānam umeśo gopatidhvajaḥ
devyāḥ priyacikīrṣuḥ sa tasmin parvatanirjhare', null, 7078012),
('ramayana-7-78-13', 13, 'Uttara Kanda, Sarga 78, Verse 13', 'ये च तत्र वनोद्देशे सत्त्वाः पुरुषवादिनः।
यच्च किं चन तत्सर्वं नारीसंज्ञं बभूव ह॥', 'ye ca tatra vanoddeśe sattvāḥ puruṣavādinaḥ
yac ca kiṃ cana tat sarvaṃ nārīsaṃjñaṃ babhūva ha', null, 7078013),
('ramayana-7-78-14', 14, 'Uttara Kanda, Sarga 78, Verse 14', 'एतस्मिन्नन्तरे राजा स इलः कर्दमात्मजः।
निघ्नन्मृगसहस्राणि तं देशमुपचक्रमे॥', 'etasminn antare rājā sa ilaḥ kardamātmajaḥ
nighnan mṛgasahasrāṇi taṃ deśam upacakrame', null, 7078014),
('ramayana-7-78-15', 15, 'Uttara Kanda, Sarga 78, Verse 15', 'स दृष्ट्वा स्त्रीकृतं सर्वं सव्यालमृगपक्षिणम्।
आत्मानं सानुगं चैव स्त्रीभूतं रघुनन्दन॥', 'sa dṛṣṭvā strīkṛtaṃ sarvaṃ savyālamṛgapakṣiṇam
ātmānaṃ sānugaṃ caiva strībhūtaṃ raghunandana', null, 7078015),
('ramayana-7-78-16', 16, 'Uttara Kanda, Sarga 78, Verse 16', 'तस्य दुःखं महत्त्वासीद्दृष्ट्वात्मानं तथा गतम्।
उमापतेश्च तत्कर्म ज्ञात्वा त्रासमुपागमत्॥', 'tasya duḥkhaṃ mahat tv āsīd dṛṣṭvātmānaṃ tathā gatam
umāpateś ca tat karma jñātvā trāsam upāgamat', null, 7078016),
('ramayana-7-78-17', 17, 'Uttara Kanda, Sarga 78, Verse 17', 'ततो देवं महात्मानं शितिकण्ठं कपर्दिनम्।
जगाम शरणं राजा सभृत्यबलवाहनः॥', 'tato devaṃ mahātmānaṃ śitikaṇṭhaṃ kapardinam
jagāma śaraṇaṃ rājā sabhṛtyabalavāhanaḥ', null, 7078017),
('ramayana-7-78-18', 18, 'Uttara Kanda, Sarga 78, Verse 18', 'ततः प्रहस्य वरदः सह देव्या महायशाः।
प्रजापतिसुतं वाक्यमुवाच वरदः स्वयम्॥', 'tataḥ prahasya varadaḥ saha devyā mahāyaśāḥ
prajāpatisutaṃ vākyam uvāca varadaḥ svayam', null, 7078018),
('ramayana-7-78-19', 19, 'Uttara Kanda, Sarga 78, Verse 19', 'उत्तिष्ठोत्तिष्ठ राजर्षे कार्दमेय महाबल।
पुरुषत्वमृते सौम्य वरं वरय सुव्रत॥', 'uttiṣṭhottiṣṭha rājarṣe kārdameya mahābala
puruṣatvam ṛte saumya varaṃ varaya suvrata', null, 7078019),
('ramayana-7-78-20', 20, 'Uttara Kanda, Sarga 78, Verse 20', 'ततः स राजा शोकार्ताः प्रत्याख्यातो महात्मना।
न स जग्राह स्त्रीभूतो वरमन्यं सुरोत्तमात्॥', 'tataḥ sa rājā śokārtāḥ pratyākhyāto mahātmanā
na sa jagrāha strībhūto varam anyaṃ surottamāt', null, 7078020),
('ramayana-7-78-21', 21, 'Uttara Kanda, Sarga 78, Verse 21', 'ततः शोकेन महता शैलराजसुतां नृपः।
प्रणिपत्य महादेवीं सर्वेणैवान्तरात्मना॥', 'tataḥ śokena mahatā śailarājasutāṃ nṛpaḥ
praṇipatya mahādevīṃ sarveṇaivāntarātmanā', null, 7078021),
('ramayana-7-78-22', 22, 'Uttara Kanda, Sarga 78, Verse 22', 'ईशे वराणां वरदे लोकानामसि भामिनि।
अमोघदर्शने देवि भजे सौम्ये नमोऽस्तु ते॥', 'īśe varāṇāṃ varade lokānām asi bhāmini
amoghadarśane devi bhaje saumye namo ''stu te', null, 7078022),
('ramayana-7-78-23', 23, 'Uttara Kanda, Sarga 78, Verse 23', 'हृद्गतं तस्य राजर्षेर्विज्ञाय हरसंनिधौ।
प्रत्युवाच शुभं वाक्यं देवी रुद्रस्य संमता॥', 'hṛdgataṃ tasya rājarṣer vijñāya harasaṃnidhau
pratyuvāca śubhaṃ vākyaṃ devī rudrasya saṃmatā', null, 7078023),
('ramayana-7-78-24', 24, 'Uttara Kanda, Sarga 78, Verse 24', 'अर्धस्य देवो वरदो वरार्धस्य तथा ह्यहम्।
तस्मादर्धं गृहाण त्वं स्त्रीपुंसोर्यावदिच्छसि॥', 'ardhasya devo varado varārdhasya tathā hy aham
tasmād ardhaṃ gṛhāṇa tvaṃ strīpuṃsor yāvad icchasi', null, 7078024),
('ramayana-7-78-25', 25, 'Uttara Kanda, Sarga 78, Verse 25', 'तदद्भुततमं श्रुत्वा देव्या वरमनुत्तमम्।
संप्रहृष्टमना भूत्वा राजा वाक्यमथाब्रवीत्॥', 'tad adbhutatamaṃ śrutvā devyā varam anuttamam
saṃprahṛṣṭamanā bhūtvā rājā vākyam athābravīt', null, 7078025),
('ramayana-7-78-26', 26, 'Uttara Kanda, Sarga 78, Verse 26', 'यदि देवि प्रसन्ना मे रूपेणाप्रतिमा भुवि।
मासं स्त्रीत्वमुपासित्वा मासं स्यां पुरुषः पुनः॥', 'yadi devi prasannā me rūpeṇāpratimā bhuvi
māsaṃ strītvam upāsitvā māsaṃ syāṃ puruṣaḥ punaḥ', null, 7078026),
('ramayana-7-78-27', 27, 'Uttara Kanda, Sarga 78, Verse 27', 'ईप्सितं तस्य विज्ञाय देवी सुरुचिरानना।
प्रत्युवाच शुभं वाक्यमेवमेतद्भविष्यति॥', 'īpsitaṃ tasya vijñāya devī surucirānanā
pratyuvāca śubhaṃ vākyam evam etad bhaviṣyati', null, 7078027),
('ramayana-7-78-28', 28, 'Uttara Kanda, Sarga 78, Verse 28', 'राजन्पुरुषभूतस्त्वं स्त्रीभावं न स्मरिष्यसि।
स्त्रीभूतश्चापरं मासं न स्मरिष्यसि पौरुषम्॥', 'rājan puruṣabhūtas tvaṃ strībhāvaṃ na smariṣyasi
strībhūtaś cāparaṃ māsaṃ na smariṣyasi pauruṣam', null, 7078028),
('ramayana-7-78-29', 29, 'Uttara Kanda, Sarga 78, Verse 29', 'एवं स राजा पुरुषो मामं भूत्वाथ कार्दमिः।
त्रैलोक्यसुन्दरी नारी मासमेकमिलाभवत्॥', 'evaṃ sa rājā puruṣo māmaṃ bhūtvātha kārdamiḥ
trailokyasundarī nārī māsam ekam ilābhavat', null, 7078029)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 79 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-79-1', 1, 'Uttara Kanda, Sarga 79, Verse 1', 'तां कथामिलसंबद्धां रामेण समुदीरिताम्।
लक्ष्मणो भरतश्चैव श्रुत्वा परमविस्मितौ॥', 'tāṃ kathām ilasaṃbaddhāṃ rāmeṇa samudīritām
lakṣmaṇo bharataś caiva śrutvā paramavismitau', null, 7079001),
('ramayana-7-79-2', 2, 'Uttara Kanda, Sarga 79, Verse 2', 'तौ रामं प्राञ्जलीभूत्वा तस्य राज्ञो महात्मनः।
विस्तरं तस्य भावस्य तदा पप्रच्छतुः पुनः॥', 'tau rāmaṃ prāñjalībhūtvā tasya rājño mahātmanaḥ
vistaraṃ tasya bhāvasya tadā papracchatuḥ punaḥ', null, 7079002),
('ramayana-7-79-3', 3, 'Uttara Kanda, Sarga 79, Verse 3', 'कथं स राजा स्त्रीभूतो वर्तयामास दुर्गतिम्।
पुरुषो वा यदा भूतः कां वृत्तिं वर्तयत्यसौ॥', 'kathaṃ sa rājā strībhūto vartayām āsa durgatim
puruṣo vā yadā bhūtaḥ kāṃ vṛttiṃ vartayaty asau', null, 7079003),
('ramayana-7-79-4', 4, 'Uttara Kanda, Sarga 79, Verse 4', 'तयोस्तद्भाषितं श्रुत्वा कौतूहलसमन्वितम्।
कथयामास काकुत्ष्ठस्तस्य राज्ञो यथा गतम्॥', 'tayos tad bhāṣitaṃ śrutvā kautūhalasamanvitam
kathayām āsa kākutṣṭhas tasya rājño yathā gatam', null, 7079004),
('ramayana-7-79-5', 5, 'Uttara Kanda, Sarga 79, Verse 5', 'तमेव प्रथमं मासं स्त्रीभूत्वा लोकसुन्दरी।
ताभिः परिवृता स्त्रीभिर्येऽस्य पूर्वं पदानुगाः॥', 'tam eva prathamaṃ māsaṃ strībhūtvā lokasundarī
tābhiḥ parivṛtā strībhir ye ''sya pūrvaṃ padānugāḥ', null, 7079005),
('ramayana-7-79-6', 6, 'Uttara Kanda, Sarga 79, Verse 6', 'तत्काननं विगाह्याशु विजह्रे लोकसुन्दरी।
द्रुमगुल्मलताकीर्णं पद्भ्यां पद्मदलेक्षणा॥', 'tat kānanaṃ vigāhyāśu vijahre lokasundarī
drumagulmalatākīrṇaṃ padbhyāṃ padmadalekṣaṇā', null, 7079006),
('ramayana-7-79-7', 7, 'Uttara Kanda, Sarga 79, Verse 7', 'वाहनानि च सर्वाणि संत्यक्त्वा वै समन्ततः।
पर्वताभोगविवरे तस्मिन्रेमे इला तदा॥', 'vāhanāni ca sarvāṇi saṃtyaktvā vai samantataḥ
parvatābhogavivare tasmin reme ilā tadā', null, 7079007),
('ramayana-7-79-8', 8, 'Uttara Kanda, Sarga 79, Verse 8', 'अथ तस्मिन्वनोद्देशे पर्वतस्याविदूरतः।
सरः सुरुचिरप्रख्यं नानापक्षिगणायुतम्॥', 'atha tasmin vanoddeśe parvatasyāvidūrataḥ
saraḥ suruciraprakhyaṃ nānāpakṣigaṇāyutam', null, 7079008),
('ramayana-7-79-9', 9, 'Uttara Kanda, Sarga 79, Verse 9', 'ददर्श सा इला तस्मिन्बुधं सोमसुतं तदा।
ज्वलन्तं स्वेन वपुषा पूर्णं सोममिवोदितम्॥', 'dadarśa sā ilā tasmin budhaṃ somasutaṃ tadā
jvalantaṃ svena vapuṣā pūrṇaṃ somam ivoditam', null, 7079009),
('ramayana-7-79-10', 10, 'Uttara Kanda, Sarga 79, Verse 10', 'तपन्तं च तपस्तीव्रमम्भोमध्ये दुरासदम्।
यशक्सरं कामगमं तारुण्ये पर्यवस्थितम्॥', 'tapantaṃ ca tapas tīvram ambhomadhye durāsadam
yaśak saraṃ kāmagamaṃ tāruṇye paryavasthitam', null, 7079010),
('ramayana-7-79-11', 11, 'Uttara Kanda, Sarga 79, Verse 11', 'सा तं जलाशयं सर्वं क्षोभयामास विस्मिता।
सह तैः पूर पुरुषैः स्त्रीभूतै रघुनन्दन॥', 'sā taṃ jalāśayaṃ sarvaṃ kṣobhayām āsa vismitā
saha taiḥ pūra puruṣaiḥ strībhūtai raghunandana', null, 7079011),
('ramayana-7-79-12', 12, 'Uttara Kanda, Sarga 79, Verse 12', 'बुधस्तु तां निरीक्ष्यैव कामबाणाभिपीडितः।
नोपलेभे तदात्मानं चचाल च तदाम्भसि॥', 'budhas tu tāṃ nirīkṣyaiva kāmabāṇābhipīḍitaḥ
nopalebhe tadātmānaṃ cacāla ca tadāmbhasi', null, 7079012),
('ramayana-7-79-13', 13, 'Uttara Kanda, Sarga 79, Verse 13', 'इलां निरीक्षमाणः स त्रैलोक्याभ्यधिकां शुभाम्।
चिन्तां समभ्यतिक्रामत्का न्वियं देवताधिका॥', 'ilāṃ nirīkṣamāṇaḥ sa trailokyābhyadhikāṃ śubhām
cintāṃ samabhyatikrāmat kā nv iyaṃ devatādhikā', null, 7079013),
('ramayana-7-79-14', 14, 'Uttara Kanda, Sarga 79, Verse 14', 'न देवीषु न नागीषु नासुरीष्वप्सरःसु च।
दृष्टपूर्वा मया का चिद्रूपेणैतेन शोभिता॥', 'na devīṣu na nāgīṣu nāsurīṣv apsaraḥsu ca
dṛṣṭapūrvā mayā kā cid rūpeṇaitena śobhitā', null, 7079014),
('ramayana-7-79-15', 15, 'Uttara Kanda, Sarga 79, Verse 15', 'सदृशीयं मम भवेद्यदि नान्यपरिग्रहा।
इति बुद्धिं समास्थाय जलात्स्थलमुपागमत्॥', 'sadṛśīyaṃ mama bhaved yadi nānyaparigrahā
iti buddhiṃ samāsthāya jalāt sthalam upāgamat', null, 7079015),
('ramayana-7-79-16', 16, 'Uttara Kanda, Sarga 79, Verse 16', 'स आश्रमं समुपागम्य चतस्रः प्रमदास्ततः।
शब्दापयत धर्मात्मा ताश्चैनं च ववन्दिरे॥', 'sa āśramaṃ samupāgamya catasraḥ pramadās tataḥ
śabdāpayata dharmātmā tāś cainaṃ ca vavandire', null, 7079016),
('ramayana-7-79-17', 17, 'Uttara Kanda, Sarga 79, Verse 17', 'स ताः पप्रच्छ धर्मात्म कस्यैषा लोकसुन्दरी।
किमर्थमागता चेह सत्यमाख्यात माचिरम्॥', 'sa tāḥ papraccha dharmātma kasyaiṣā lokasundarī
kimartham āgatā ceha satyam ākhyāta māciram', null, 7079017),
('ramayana-7-79-18', 18, 'Uttara Kanda, Sarga 79, Verse 18', 'शुभं तु तस्य तद्वाक्यं मधुरं मधुराक्षरम्।
श्रुत्वा तु ताः स्त्रियः सर्वा ऊचुर्मधुरया गिरा॥', 'śubhaṃ tu tasya tadvākyaṃ madhuraṃ madhurākṣaram
śrutvā tu tāḥ striyaḥ sarvā ūcur madhurayā girā', null, 7079018),
('ramayana-7-79-19', 19, 'Uttara Kanda, Sarga 79, Verse 19', 'अस्माकमेषा सुश्रोणी प्रभुत्वे वर्तते सदा।
अपतिः काननान्तेषु सहास्माभिरटत्यसौ॥', 'asmākam eṣā suśroṇī prabhutve vartate sadā
apatiḥ kānanānteṣu sahāsmābhir aṭaty asau', null, 7079019),
('ramayana-7-79-20', 20, 'Uttara Kanda, Sarga 79, Verse 20', 'तद्वाक्यमव्यक्तपदं तासां स्त्रीणां निशम्य तु।
विद्यामावर्तनीं पुण्यामावर्तयत स द्विजः॥', 'tad vākyam avyaktapadaṃ tāsāṃ strīṇāṃ niśamya tu
vidyām āvartanīṃ puṇyām āvartayata sa dvijaḥ', null, 7079020),
('ramayana-7-79-21', 21, 'Uttara Kanda, Sarga 79, Verse 21', 'सोऽर्थं विदित्वा निखिलं तस्य राज्ञो यथागतम्।
सर्वा एव स्त्रियस्ताश्च बभाषे मुनिपुंगवः॥', 'so ''rthaṃ viditvā nikhilaṃ tasya rājño yathāgatam
sarvā eva striyas tāś ca babhāṣe munipuṃgavaḥ', null, 7079021),
('ramayana-7-79-22', 22, 'Uttara Kanda, Sarga 79, Verse 22', 'अत्र किं पुरुषा भद्रा अवसञ्शैलरोधसि।
वत्स्यथास्मिन्गिरौ यूयमवकाशो विधीयताम्॥', 'atra kiṃ puruṣā bhadrā avasañ śailarodhasi
vatsyathāsmin girau yūyam avakāśo vidhīyatām', null, 7079022),
('ramayana-7-79-23', 23, 'Uttara Kanda, Sarga 79, Verse 23', 'मूलपुत्रफलैः सर्वा वर्तयिष्यथ नित्यदा।
स्त्रियः किम्पुरुषान्नाम भर्तॄन्समुपलप्स्यथ॥', 'mūlaputraphalaiḥ sarvā vartayiṣyatha nityadā
striyaḥ kimpuruṣān nāma bhartṝn samupalapsyatha', null, 7079023),
('ramayana-7-79-24', 24, 'Uttara Kanda, Sarga 79, Verse 24', 'ताः श्रुत्वा सोमपुत्रस्य वाचं किंपुरुषीकृताः।
उपासां चक्रिरे शैलं बह्व्यस्ता बहुधा तदा॥', 'tāḥ śrutvā somaputrasya vācaṃ kiṃpuruṣīkṛtāḥ
upāsāṃ cakrire śailaṃ bahvyas tā bahudhā tadā', null, 7079024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 80 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-80-1', 1, 'Uttara Kanda, Sarga 80, Verse 1', 'श्रुत्वा किम्पुरुषोत्पत्तिं लक्ष्मणो भरतस्तदा।
आश्चर्यमिति चाब्रूतामुभौ रामं जनेश्वरम्॥', 'śrutvā kimpuruṣotpattiṃ lakṣmaṇo bharatas tadā
āścaryam iti cābrūtām ubhau rāmaṃ janeśvaram', null, 7080001),
('ramayana-7-80-2', 2, 'Uttara Kanda, Sarga 80, Verse 2', 'अथ रामः कथामेतां भूय एव महायशाः।
कथयामास धर्मात्मा प्रजापतिसुतस्य वै॥', 'atha rāmaḥ kathām etāṃ bhūya eva mahāyaśāḥ
kathayām āsa dharmātmā prajāpatisutasya vai', null, 7080002),
('ramayana-7-80-3', 3, 'Uttara Kanda, Sarga 80, Verse 3', 'सर्वास्ता विद्रुता दृष्ट्वा किंनरीरृषिसत्तमः।
उवाच रूपसंपन्नां तां स्त्रियं प्रहसन्निव॥', 'sarvās tā vidrutā dṛṣṭvā kiṃnarīr ṛṣisattamaḥ
uvāca rūpasaṃpannāṃ tāṃ striyaṃ prahasann iva', null, 7080003),
('ramayana-7-80-4', 4, 'Uttara Kanda, Sarga 80, Verse 4', 'सोमस्याहं सुदयितः सुतः सुरुचिरानने।
भजस्व मां वरारोहे भक्त्या स्निग्धेन चक्षुषा॥', 'somasyāhaṃ sudayitaḥ sutaḥ surucirānane
bhajasva māṃ varārohe bhaktyā snigdhena cakṣuṣā', null, 7080004),
('ramayana-7-80-5', 5, 'Uttara Kanda, Sarga 80, Verse 5', 'तस्य तद्वचनं श्रुत्वा शून्ये स्वजनवर्जिता।
इला सुरुचिरप्रख्यं प्रत्युवाच महाग्रहम्॥', 'tasya tad vacanaṃ śrutvā śūnye svajanavarjitā
ilā suruciraprakhyaṃ pratyuvāca mahāgraham', null, 7080005),
('ramayana-7-80-6', 6, 'Uttara Kanda, Sarga 80, Verse 6', 'अहं कामकरी सौम्य तवास्मि वशवर्तिनी।
प्रशाधि मां सोमसुत यथेच्छसि तथा कुरु॥', 'ahaṃ kāmakarī saumya tavāsmi vaśavartinī
praśādhi māṃ somasuta yathecchasi tathā kuru', null, 7080006),
('ramayana-7-80-7', 7, 'Uttara Kanda, Sarga 80, Verse 7', 'तस्यास्तदद्भुतप्रख्यं श्रुत्वा हर्षसमन्वितः।
स वै कामी सह तया रेमे चन्द्रमसः सुतः॥', 'tasyās tad adbhutaprakhyaṃ śrutvā harṣasamanvitaḥ
sa vai kāmī saha tayā reme candramasaḥ sutaḥ', null, 7080007),
('ramayana-7-80-8', 8, 'Uttara Kanda, Sarga 80, Verse 8', 'बुधस्य माधवो मासस्तामिलां रुचिराननाम्।
गतो रमयतोऽत्यर्थं क्षणवत्तस्य कामिनः॥', 'budhasya mādhavo māsas tām ilāṃ rucirānanām
gato ramayato ''tyarthaṃ kṣaṇavat tasya kāminaḥ', null, 7080008),
('ramayana-7-80-9', 9, 'Uttara Kanda, Sarga 80, Verse 9', 'अथ मासे तु संपूर्णे पूर्णेन्दुसदृशाननः।
प्रजापतिसुतः श्रीमाञ्शयने प्रत्यबुध्यत॥', 'atha māse tu saṃpūrṇe pūrṇendusadṛśānanaḥ
prajāpatisutaḥ śrīmāñ śayane pratyabudhyata', null, 7080009),
('ramayana-7-80-10', 10, 'Uttara Kanda, Sarga 80, Verse 10', 'सोऽपश्यत्सोमजं तत्र तप्यन्तं सलिलाशये।
ऊर्ध्वबाहुं निरालम्बं तं राजा प्रत्यभाषत॥', 'so ''paśyat somajaṃ tatra tapyantaṃ salilāśaye
ūrdhvabāhuṃ nirālambaṃ taṃ rājā pratyabhāṣata', null, 7080010),
('ramayana-7-80-11', 11, 'Uttara Kanda, Sarga 80, Verse 11', 'भगवन्पर्वतं दुर्गं प्रविष्टोऽस्मि सहानुगः।
न च पश्यामि तत्सैन्यं क्व नु ते मामका गताः॥', 'bhagavan parvataṃ durgaṃ praviṣṭo ''smi sahānugaḥ
na ca paśyāmi tat sainyaṃ kva nu te māmakā gatāḥ', null, 7080011),
('ramayana-7-80-12', 12, 'Uttara Kanda, Sarga 80, Verse 12', 'तच्छ्रुत्वा तस्य राजर्षेर्नष्टसंज्ञस्य भाषितम्।
प्रत्युवाच शुभं वाक्यं सान्त्वयन्परया गिरा॥', 'tac chrutvā tasya rājarṣer naṣṭasaṃjñasya bhāṣitam
pratyuvāca śubhaṃ vākyaṃ sāntvayan parayā girā', null, 7080012),
('ramayana-7-80-13', 13, 'Uttara Kanda, Sarga 80, Verse 13', 'अश्मवर्षेण महता भृत्यास्ते विनिपातिताः।
त्वं चाश्रमपदे सुप्तो वातवर्षभयार्दितः॥', 'aśmavarṣeṇa mahatā bhṛtyās te vinipātitāḥ
tvaṃ cāśramapade supto vātavarṣabhayārditaḥ', null, 7080013),
('ramayana-7-80-14', 14, 'Uttara Kanda, Sarga 80, Verse 14', 'समाश्वसिहि भद्रं ते निर्भयो विगतज्वरः।
फलमूलाशनो वीर वस चेह यथासुखम्॥', 'samāśvasihi bhadraṃ te nirbhayo vigatajvaraḥ
phalamūlāśano vīra vasa ceha yathāsukham', null, 7080014),
('ramayana-7-80-15', 15, 'Uttara Kanda, Sarga 80, Verse 15', 'स राजा तेन वाक्येन प्रत्याश्वस्तो महायशाः।
प्रत्युवाच शुभं वाक्यं दीनो भृत्यजनक्षयात्॥', 'sa rājā tena vākyena pratyāśvasto mahāyaśāḥ
pratyuvāca śubhaṃ vākyaṃ dīno bhṛtyajanakṣayāt', null, 7080015),
('ramayana-7-80-16', 16, 'Uttara Kanda, Sarga 80, Verse 16', 'त्यक्ष्याम्यहं स्वकं राज्यं नाहं भृत्यैर्विना कृतः।
वर्तयेयं क्षणं ब्रह्मन्समनुज्ञातुमर्हसि॥', 'tyakṣyāmy ahaṃ svakaṃ rājyaṃ nāhaṃ bhṛtyair vinā kṛtaḥ
vartayeyaṃ kṣaṇaṃ brahman samanujñātum arhasi', null, 7080016),
('ramayana-7-80-17', 17, 'Uttara Kanda, Sarga 80, Verse 17', 'सुतो धर्मपरो ब्रह्मञ्ज्येष्ठो मम महायशाः।
शशबिन्दुरिति ख्यातः स मे राज्यं प्रपत्स्यते॥', 'suto dharmaparo brahmañ jyeṣṭho mama mahāyaśāḥ
śaśabindur iti khyātaḥ sa me rājyaṃ prapatsyate', null, 7080017),
('ramayana-7-80-18', 18, 'Uttara Kanda, Sarga 80, Verse 18', 'न हि शक्ष्याम्यहं गत्वा भृत्यदारान्सुखान्वितान्।
प्रतिवक्तुं महातेजः किं चिदप्यशुभं वचः॥', 'na hi śakṣyāmy ahaṃ gatvā bhṛtyadārān sukhānvitān
prativaktuṃ mahātejaḥ kiṃ cid apy aśubhaṃ vacaḥ', null, 7080018),
('ramayana-7-80-19', 19, 'Uttara Kanda, Sarga 80, Verse 19', 'तथा ब्रुवति राजेन्द्रे बुधः परममद्भुतम्।
सान्त्वपूर्वमथोवाच वासस्त इह रोचताम्॥', 'tathā bruvati rājendre budhaḥ paramam adbhutam
sāntvapūrvam athovāca vāsas ta iha rocatām', null, 7080019),
('ramayana-7-80-20', 20, 'Uttara Kanda, Sarga 80, Verse 20', 'न संतापस्त्वया कार्यः कार्दमेय महाबल।
संवत्सरोषितस्येह कारयिष्यामि ते हितम्॥', 'na saṃtāpas tvayā kāryaḥ kārdameya mahābala
saṃvatsaroṣitasyeha kārayiṣyāmi te hitam', null, 7080020),
('ramayana-7-80-21', 21, 'Uttara Kanda, Sarga 80, Verse 21', 'तस्य तद्वचनं श्रुत्वा बुधस्याक्लिष्टकर्मणः।
वासाय विदधे बुद्धिं यदुक्तं ब्रह्मवादिना॥', 'tasya tad vacanaṃ śrutvā budhasyākliṣṭakarmaṇaḥ
vāsāya vidadhe buddhiṃ yad uktaṃ brahmavādinā', null, 7080021),
('ramayana-7-80-22', 22, 'Uttara Kanda, Sarga 80, Verse 22', 'मासं स स्त्री तदा भूत्वा रमयत्यनिशं शुभा।
मासं पुरुषभावेन धर्मबुद्धिं चकार सः॥', 'māsaṃ sa strī tadā bhūtvā ramayaty aniśaṃ śubhā
māsaṃ puruṣabhāvena dharmabuddhiṃ cakāra saḥ', null, 7080022),
('ramayana-7-80-23', 23, 'Uttara Kanda, Sarga 80, Verse 23', 'ततः स नवमे मासि इला सोमसुतात्मजम्।
जनयामास सुश्रोणी पुरूरवसमात्मजम्॥', 'tataḥ sa navame māsi ilā somasutātmajam
janayām āsa suśroṇī purūravasam ātmajam', null, 7080023),
('ramayana-7-80-24', 24, 'Uttara Kanda, Sarga 80, Verse 24', 'जातमात्रं तु सुश्रोणी पितुर्हस्ते न्यवेशयत्।
बुधस्य समवर्णाभमिलापुत्रं महाबलम्॥', 'jātamātraṃ tu suśroṇī pitur haste nyaveśayat
budhasya samavarṇābham ilāputraṃ mahābalam', null, 7080024),
('ramayana-7-80-25', 25, 'Uttara Kanda, Sarga 80, Verse 25', 'बुधोऽपि पुरुषीभूतं समाश्वास्य नराधिपम्।
कथाभी रमयामास धर्मयुक्ताभिरात्मवान्॥', 'budho ''pi puruṣībhūtaṃ samāśvāsya narādhipam
kathābhī ramayām āsa dharmayuktābhir ātmavān', null, 7080025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 81 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-81-1', 1, 'Uttara Kanda, Sarga 81, Verse 1', 'तथोक्तवति रामे तु तस्य जन्म तदद्भुतम्।
उवाच लक्ष्मणो भूयो भरतश्च महायशाः॥', 'tathoktavati rāme tu tasya janma tad adbhutam
uvāca lakṣmaṇo bhūyo bharataś ca mahāyaśāḥ', null, 7081001),
('ramayana-7-81-2', 2, 'Uttara Kanda, Sarga 81, Verse 2', 'सा प्रिया सोमपुत्रस्य संवत्सरमथोषिता।
अकरोत्किं नरश्रेष्ठ तत्त्वं शंसितुमर्हसि॥', 'sā priyā somaputrasya saṃvatsaram athoṣitā
akarot kiṃ naraśreṣṭha tat tvaṃ śaṃsitum arhasi', null, 7081002),
('ramayana-7-81-3', 3, 'Uttara Kanda, Sarga 81, Verse 3', 'तयोस्तद्वाक्यमाधुर्यं निशम्य परिपृच्छतोः।
रामः पुनरुवाचेमां प्रजापतिसुते कथाम्॥', 'tayos tad vākyamādhuryaṃ niśamya paripṛcchatoḥ
rāmaḥ punar uvācemāṃ prajāpatisute kathām', null, 7081003),
('ramayana-7-81-4', 4, 'Uttara Kanda, Sarga 81, Verse 4', 'पुरुषत्वं गते शूरे बुधः परमबुद्धिमान्।
संवर्तं परमोदारमाजुहाव महायशाः॥', 'puruṣatvaṃ gate śūre budhaḥ paramabuddhimān
saṃvartaṃ paramodāram ājuhāva mahāyaśāḥ', null, 7081004),
('ramayana-7-81-5', 5, 'Uttara Kanda, Sarga 81, Verse 5', 'च्यवनं भृगुपुत्रं च मुनिं चारिष्टनेमिनम्।
प्रमोदनं मोदकरं ततो दुर्वाससं मुनिम्॥', 'cyavanaṃ bhṛguputraṃ ca muniṃ cāriṣṭaneminam
pramodanaṃ modakaraṃ tato durvāsasaṃ munim', null, 7081005),
('ramayana-7-81-6', 6, 'Uttara Kanda, Sarga 81, Verse 6', 'एतान्सर्वान्समानीय वाक्यज्ञस्तत्त्वदर्शिनः।
उवाच सर्वान्सुहृदो धैर्येण सुसमाहितः॥', 'etān sarvān samānīya vākyajñas tattvadarśinaḥ
uvāca sarvān suhṛdo dhairyeṇa susamāhitaḥ', null, 7081006),
('ramayana-7-81-7', 7, 'Uttara Kanda, Sarga 81, Verse 7', 'अयं राजा महाबाहुः कर्दमस्य इलः सुतः।
जानीतैनं यथा भूतं श्रेयो ह्यस्य विधीयताम्॥', 'ayaṃ rājā mahābāhuḥ kardamasya ilaḥ sutaḥ
jānītainaṃ yathā bhūtaṃ śreyo hy asya vidhīyatām', null, 7081007),
('ramayana-7-81-8', 8, 'Uttara Kanda, Sarga 81, Verse 8', 'तेषां संवदतामेव तमाश्रममुपागमत्।
कर्दमः सुमहातेजा द्विजैः सह महात्मभिः॥', 'teṣāṃ saṃvadatām eva tam āśramam upāgamat
kardamaḥ sumahātejā dvijaiḥ saha mahātmabhiḥ', null, 7081008),
('ramayana-7-81-9', 9, 'Uttara Kanda, Sarga 81, Verse 9', 'पुलस्त्यश्च क्रतुश्चैव वषट्कारस्तथैव च।
ओंकारश्च महातेजास्तमाश्रममुपागमन्॥', 'pulastyaś ca kratuś caiva vaṣaṭkāras tathaiva ca
oṃkāraś ca mahātejās tam āśramam upāgaman', null, 7081009),
('ramayana-7-81-10', 10, 'Uttara Kanda, Sarga 81, Verse 10', 'ते सर्वे हृष्टमनसः परस्परसमागमे।
हितैषिणो बाह्लि पतेः पृथग्वाक्यमथाब्रुवन्॥', 'te sarve hṛṣṭamanasaḥ parasparasamāgame
hitaiṣiṇo bāhli pateḥ pṛthag vākyam athābruvan', null, 7081010),
('ramayana-7-81-11', 11, 'Uttara Kanda, Sarga 81, Verse 11', 'कर्दमस्त्वब्रवीद्वाक्यं सुतार्थं परमं हितम्।
द्विजाः शृणुत मद्वाक्यं यच्छ्रेयः पार्थिवस्य हि॥', 'kardamas tv abravīd vākyaṃ sutārthaṃ paramaṃ hitam
dvijāḥ śṛṇuta madvākyaṃ yac chreyaḥ pārthivasya hi', null, 7081011),
('ramayana-7-81-12', 12, 'Uttara Kanda, Sarga 81, Verse 12', 'नान्यं पश्यामि भैषज्यमन्तरेण वृषध्वजम्।
नाश्वमेधात्परो यज्ञः प्रियश्चैव महात्मनः॥', 'nānyaṃ paśyāmi bhaiṣajyam antareṇa vṛṣadhvajam
nāśvamedhāt paro yajñaḥ priyaś caiva mahātmanaḥ', null, 7081012),
('ramayana-7-81-13', 13, 'Uttara Kanda, Sarga 81, Verse 13', 'तस्माद्यजामहे सर्वे पार्थिवार्थे दुरासदम्।
कर्दमेनैवमुक्तास्तु सर्व एव द्विजर्षभाः।
रोचयन्ति स्म तं यज्ञं रुद्रस्याराधनं प्रति॥', 'tasmād yajāmahe sarve pārthivārthe durāsadam
kardamenaivam uktās tu sarva eva dvijarṣabhāḥ
rocayanti sma taṃ yajñaṃ rudrasyārādhanaṃ prati', null, 7081013),
('ramayana-7-81-14', 14, 'Uttara Kanda, Sarga 81, Verse 14', 'संवर्तस्य तु राजर्षिः शिष्यः परपुरंजयः।
मरुत्त इति विख्यातस्तं यज्ञं समुपाहरत्॥', 'saṃvartasya tu rājarṣiḥ śiṣyaḥ parapuraṃjayaḥ
marutta iti vikhyātas taṃ yajñaṃ samupāharat', null, 7081014),
('ramayana-7-81-15', 15, 'Uttara Kanda, Sarga 81, Verse 15', 'ततो यज्ञो महानासीद्बुधाश्रमसमीपतः।
रुद्रश्च परमं तोषमाजगाम महायशाः॥', 'tato yajño mahān āsīd budhāśramasamīpataḥ
rudraś ca paramaṃ toṣam ājagāma mahāyaśāḥ', null, 7081015),
('ramayana-7-81-16', 16, 'Uttara Kanda, Sarga 81, Verse 16', 'अथ यज्ञसमाप्तौ तु प्रीतः परमया मुदा।
उमापतिर्द्विजान्सर्वानुवाचेदमिलां प्रति॥', 'atha yajñasamāptau tu prītaḥ paramayā mudā
umāpatir dvijān sarvān uvācedam ilāṃ prati', null, 7081016),
('ramayana-7-81-17', 17, 'Uttara Kanda, Sarga 81, Verse 17', 'प्रीतोऽस्मि हयमेधेन भक्त्या च द्विजसत्तमाः।
अस्य बाह्लिपतेश्चैव किं करोमि प्रियं शुभम्॥', 'prīto ''smi hayamedhena bhaktyā ca dvijasattamāḥ
asya bāhlipateś caiva kiṃ karomi priyaṃ śubham', null, 7081017),
('ramayana-7-81-18', 18, 'Uttara Kanda, Sarga 81, Verse 18', 'तथा वदति देवेशे द्विजास्ते सुसमाहिताः।
प्रसादयन्ति देवेशं यथा स्यात्पुरुषस्त्विला॥', 'tathā vadati deveśe dvijās te susamāhitāḥ
prasādayanti deveśaṃ yathā syāt puruṣas tv ilā', null, 7081018),
('ramayana-7-81-19', 19, 'Uttara Kanda, Sarga 81, Verse 19', 'ततः प्रीतमना रुद्रः पुरुषत्वं ददौ पुनः।
इलायै सुमहातेजा दत्त्वा चान्तरधीयत॥', 'tataḥ prītamanā rudraḥ puruṣatvaṃ dadau punaḥ
ilāyai sumahātejā dattvā cāntaradhīyata', null, 7081019),
('ramayana-7-81-20', 20, 'Uttara Kanda, Sarga 81, Verse 20', 'निवृत्ते हयमेधे तु गते चादर्शनं हरे।
यथागतं द्विजाः सर्वे अगच्छन्दीर्घदर्शिनः॥', 'nivṛtte hayamedhe tu gate cādarśanaṃ hare
yathāgataṃ dvijāḥ sarve agacchan dīrghadarśinaḥ', null, 7081020),
('ramayana-7-81-21', 21, 'Uttara Kanda, Sarga 81, Verse 21', 'राजा तु बाह्लिमुत्सृज्य मध्यदेशे ह्यनुत्तमम्।
निवेशयामास पुरं प्रतिष्ठानं यशस्करम्॥', 'rājā tu bāhlim utsṛjya madhyadeśe hy anuttamam
niveśayām āsa puraṃ pratiṣṭhānaṃ yaśaskaram', null, 7081021),
('ramayana-7-81-22', 22, 'Uttara Kanda, Sarga 81, Verse 22', 'शशबिन्दुस्तु राजासीद्बाह्ल्यां परपुरंजयः।
प्रतिष्ठान इलो राजा प्रजापतिसुतो बली॥', 'śaśabindus tu rājāsīd bāhlyāṃ parapuraṃjayaḥ
pratiṣṭhāna ilo rājā prajāpatisuto balī', null, 7081022),
('ramayana-7-81-23', 23, 'Uttara Kanda, Sarga 81, Verse 23', 'स काले प्राप्तवांल्लोकमिलो ब्राह्ममनुत्तमम्।
ऐलः पुरूरवा राजा प्रतिष्ठानमवाप्तवान्॥', 'sa kāle prāptavāṃl lokam ilo brāhmam anuttamam
ailaḥ purūravā rājā pratiṣṭhānam avāptavān', null, 7081023),
('ramayana-7-81-24', 24, 'Uttara Kanda, Sarga 81, Verse 24', 'ईदृशो ह्यश्वमेधस्य प्रभावः पुरुषर्षभौ।
स्त्रीभूतः पौरुषं लेभे यच्चान्यदपि दुर्लभम्॥', 'īdṛśo hy aśvamedhasya prabhāvaḥ puruṣarṣabhau
strībhūtaḥ pauruṣaṃ lebhe yac cānyad api durlabham', null, 7081024)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 82 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-82-1', 1, 'Uttara Kanda, Sarga 82, Verse 1', 'एतदाख्याय काकुत्स्थो भ्रातृह्याममितप्रभः।
लक्ष्मणं पुनारेवाह धर्मयुक्तमिदं वचः॥', 'etad ākhyāya kākutstho bhrātṛhyām amitaprabhaḥ
lakṣmaṇaṃ punār evāha dharmayuktam idaṃ vacaḥ', null, 7082001),
('ramayana-7-82-2', 2, 'Uttara Kanda, Sarga 82, Verse 2', 'वसिष्ठं वामदेवं च जाबालिमथ कश्यपम्।
द्विजांश्च सर्वप्रवरानश्वमेधपुरस्कृतान्॥', 'vasiṣṭhaṃ vāmadevaṃ ca jābālim atha kaśyapam
dvijāṃś ca sarvapravarān aśvamedhapuraskṛtān', null, 7082002),
('ramayana-7-82-3', 3, 'Uttara Kanda, Sarga 82, Verse 3', 'एतान्सर्वान्समाहूय मन्त्रयित्वा च लक्ष्मण।
हयं लक्ष्मणसंपन्नं विमोक्ष्यामि समाधिना॥', 'etān sarvān samāhūya mantrayitvā ca lakṣmaṇa
hayaṃ lakṣmaṇasaṃpannaṃ vimokṣyāmi samādhinā', null, 7082003),
('ramayana-7-82-4', 4, 'Uttara Kanda, Sarga 82, Verse 4', 'तद्वाक्यं राघवेणोक्तं श्रुत्वा त्वरितविक्रमः।
द्विजान्सर्वान्समाहूय दर्शयामास राघवम्॥', 'tad vākyaṃ rāghaveṇoktaṃ śrutvā tvaritavikramaḥ
dvijān sarvān samāhūya darśayām āsa rāghavam', null, 7082004),
('ramayana-7-82-5', 5, 'Uttara Kanda, Sarga 82, Verse 5', 'ते दृष्ट्वा देवसंकाशं कृतपादाभिवन्दनम्।
राघवं सुदुराधर्षमाशीर्भिः समपूजयन्॥', 'te dṛṣṭvā devasaṃkāśaṃ kṛtapādābhivandanam
rāghavaṃ sudurādharṣam āśīrbhiḥ samapūjayan', null, 7082005),
('ramayana-7-82-6', 6, 'Uttara Kanda, Sarga 82, Verse 6', 'प्राञ्जलिस्तु ततो भूत्वा राघवो द्विजसात्तमान्।
उवाच धर्मसंयुक्तमश्वमेधाश्रितं वचः॥', 'prāñjalis tu tato bhūtvā rāghavo dvijasāttamān
uvāca dharmasaṃyuktam aśvamedhāśritaṃ vacaḥ', null, 7082006),
('ramayana-7-82-7', 7, 'Uttara Kanda, Sarga 82, Verse 7', 'स तेषां द्विजमुख्यानां वाक्यमद्भुतदर्शनम्।
अश्वमेधाश्रितं श्रुत्वा भृशं प्रीतोऽभवत्तदा॥', 'sa teṣāṃ dvijamukhyānāṃ vākyam adbhutadarśanam
aśvamedhāśritaṃ śrutvā bhṛśaṃ prīto ''bhavat tadā', null, 7082007),
('ramayana-7-82-8', 8, 'Uttara Kanda, Sarga 82, Verse 8', 'विज्ञाय तु मतं तेषां रामो लक्ष्मणमब्रवीत्।
प्रेषयस्व महाबाहो सुग्रीवाय महात्मने॥', 'vijñāya tu mataṃ teṣāṃ rāmo lakṣmaṇam abravīt
preṣayasva mahābāho sugrīvāya mahātmane', null, 7082008),
('ramayana-7-82-9', 9, 'Uttara Kanda, Sarga 82, Verse 9', 'शीघ्रं महद्भिर्हरिभिर्बहिभिश्च तदाश्रयैः।
सार्धमागच्छ भद्रं ते अनुभोक्तुं मखोत्तमम्॥', 'śīghraṃ mahadbhir haribhir bahibhiś ca tadāśrayaiḥ
sārdham āgaccha bhadraṃ te anubhoktuṃ makhottamam', null, 7082009),
('ramayana-7-82-10', 10, 'Uttara Kanda, Sarga 82, Verse 10', 'विभीषणश्च रक्षोभिः कामगैर्बहुभिर्वृतः।
अश्वमेधं महाबाहुः प्राप्नोतु लघुविक्रमः॥', 'vibhīṣaṇaś ca rakṣobhiḥ kāmagair bahubhir vṛtaḥ
aśvamedhaṃ mahābāhuḥ prāpnotu laghuvikramaḥ', null, 7082010),
('ramayana-7-82-11', 11, 'Uttara Kanda, Sarga 82, Verse 11', 'राजानश्च नरव्याघ्र ये मे प्रियचिकीर्षवः।
सानुगाः क्षिप्रमायान्तु यज्ञभूमिमनुत्तमाम्॥', 'rājānaś ca naravyāghra ye me priyacikīrṣavaḥ
sānugāḥ kṣipram āyāntu yajñabhūmim anuttamām', null, 7082011),
('ramayana-7-82-12', 12, 'Uttara Kanda, Sarga 82, Verse 12', 'देशान्तरगता ये च द्विजा धर्मपरायणाः।
निमन्त्रयस्व तान्सर्वानश्वमेधाय लक्ष्मण॥', 'deśāntaragatā ye ca dvijā dharmaparāyaṇāḥ
nimantrayasva tān sarvān aśvamedhāya lakṣmaṇa', null, 7082012),
('ramayana-7-82-13', 13, 'Uttara Kanda, Sarga 82, Verse 13', 'ऋषयश्चा महाबाहो आहूयन्तां तपोधनाः।
देशान्तरगता ये च सदाराश्च महर्षयः॥', 'ṛṣayaś cā mahābāho āhūyantāṃ tapodhanāḥ
deśāntaragatā ye ca sadārāś ca maharṣayaḥ', null, 7082013),
('ramayana-7-82-14', 14, 'Uttara Kanda, Sarga 82, Verse 14', 'यज्ञवाटश्च सुमहान्गोमत्या नैमिषे वने।
आज्ञाप्यतां महाबाहो तद्धि पुण्यमनुत्तमम्॥', 'yajñavāṭaś ca sumahān gomatyā naimiṣe vane
ājñāpyatāṃ mahābāho tad dhi puṇyam anuttamam', null, 7082014),
('ramayana-7-82-15', 15, 'Uttara Kanda, Sarga 82, Verse 15', 'शतं वाहसहस्राणां तण्डुलानां वपुष्मताम्।
अयुतं तिलमुद्गस्य प्रयात्वग्रे महाबल॥', 'śataṃ vāhasahasrāṇāṃ taṇḍulānāṃ vapuṣmatām
ayutaṃ tilamudgasya prayātv agre mahābala', null, 7082015),
('ramayana-7-82-16', 16, 'Uttara Kanda, Sarga 82, Verse 16', 'सुवर्णकोट्यो बहुला हिरण्यस्य शतोत्तराः।
अग्रतो भरतः कृत्वा गच्छत्वग्रे महामतिः॥', 'suvarṇakoṭyo bahulā hiraṇyasya śatottarāḥ
agrato bharataḥ kṛtvā gacchatv agre mahāmatiḥ', null, 7082016),
('ramayana-7-82-17', 17, 'Uttara Kanda, Sarga 82, Verse 17', 'अन्तरापणवीथ्यश्च सर्वांश्च नटनर्तकान्।
नैगमान्बालवृद्धांश्च द्विजांश्च सुसमाहितान्॥', 'antarāpaṇavīthyaś ca sarvāṃś ca naṭanartakān
naigamān bālavṛddhāṃś ca dvijāṃś ca susamāhitān', null, 7082017),
('ramayana-7-82-18', 18, 'Uttara Kanda, Sarga 82, Verse 18', 'कर्मान्तिकांश्च कुशलाञ्शिल्पिनश्च सुपण्डितान्।
मातरश्चैव मे सर्वाः कुमारान्तःपुराणि च॥', 'karmāntikāṃś ca kuśalāñ śilpinaś ca supaṇḍitān
mātaraś caiva me sarvāḥ kumārāntaḥpurāṇi ca', null, 7082018),
('ramayana-7-82-19', 19, 'Uttara Kanda, Sarga 82, Verse 19', 'काञ्चनीं मम पत्नीं च दीक्षार्हां यज्ञकर्मणि।
अग्रतो भरतः कृत्वा गच्छत्वग्रे महामतिः॥', 'kāñcanīṃ mama patnīṃ ca dīkṣārhāṃ yajñakarmaṇi
agrato bharataḥ kṛtvā gacchatv agre mahāmatiḥ', null, 7082019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 83 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-83-1', 1, 'Uttara Kanda, Sarga 83, Verse 1', 'तत्सर्वमखिलेनाशु प्रस्थाप्य भरताग्रजः।
हयं लक्ष्मणसंपन्नं कृष्णसारं मुमोच ह॥', 'tat sarvam akhilenāśu prasthāpya bharatāgrajaḥ
hayaṃ lakṣmaṇasaṃpannaṃ kṛṣṇasāraṃ mumoca ha', null, 7083001),
('ramayana-7-83-2', 2, 'Uttara Kanda, Sarga 83, Verse 2', 'ऋत्विग्भिर्लक्ष्मणं सार्धमश्वे च विनियुज्य सः।
ततोऽभ्यगच्छत्काकुत्स्थः सह सैन्येन नैमिषम्॥', 'ṛtvigbhir lakṣmaṇaṃ sārdham aśve ca viniyujya saḥ
tato ''bhyagacchat kākutsthaḥ saha sainyena naimiṣam', null, 7083002),
('ramayana-7-83-3', 3, 'Uttara Kanda, Sarga 83, Verse 3', 'यज्ञवाटं महाबाहुर्दृष्ट्वा परममद्भुतम्।
प्रहर्षमतुलं लेभे श्रीमानिति च सोऽब्रवीत्॥', 'yajñavāṭaṃ mahābāhur dṛṣṭvā paramam adbhutam
praharṣam atulaṃ lebhe śrīmān iti ca so ''bravīt', null, 7083003),
('ramayana-7-83-4', 4, 'Uttara Kanda, Sarga 83, Verse 4', 'नैमिषे वसतस्तस्य सर्व एव नराधिपाः।
आजग्मुः सर्वराष्ट्रेभ्यस्तान्रामः प्रत्यपूजयत्॥', 'naimiṣe vasatas tasya sarva eva narādhipāḥ
ājagmuḥ sarvarāṣṭrebhyas tān rāmaḥ pratyapūjayat', null, 7083004),
('ramayana-7-83-5', 5, 'Uttara Kanda, Sarga 83, Verse 5', 'उपकार्यान्महार्हांश्च पार्थिवानां महात्मनाम्।
सानुगानां नरश्रेष्ठो व्यादिदेश महाद्युतिः॥', 'upakāryān mahārhāṃś ca pārthivānāṃ mahātmanām
sānugānāṃ naraśreṣṭho vyādideśa mahādyutiḥ', null, 7083005),
('ramayana-7-83-6', 6, 'Uttara Kanda, Sarga 83, Verse 6', 'अन्नपानानि वस्त्राणि सानुगानां महात्मनाम्।
भरतः संददावाशु शत्रुघ्नसहितस्तदा॥', 'annapānāni vastrāṇi sānugānāṃ mahātmanām
bharataḥ saṃdadāv āśu śatrughnasahitas tadā', null, 7083006),
('ramayana-7-83-7', 7, 'Uttara Kanda, Sarga 83, Verse 7', 'वानराश्च महात्मानः सुग्रीवसहितास्तदा।
विप्राणां प्रणताः सर्वे चक्रिरे परिवेषणम्॥', 'vānarāś ca mahātmānaḥ sugrīvasahitās tadā
viprāṇāṃ praṇatāḥ sarve cakrire pariveṣaṇam', null, 7083007),
('ramayana-7-83-8', 8, 'Uttara Kanda, Sarga 83, Verse 8', 'विभीषणश्च रक्षोभिः स्रग्विभिर्बहुभिर्वृतः।
ऋषीणामुग्रतपसां किंकरः पर्युपस्थितः॥', 'vibhīṣaṇaś ca rakṣobhiḥ sragvibhir bahubhir vṛtaḥ
ṛṣīṇām ugratapasāṃ kiṃkaraḥ paryupasthitaḥ', null, 7083008),
('ramayana-7-83-9', 9, 'Uttara Kanda, Sarga 83, Verse 9', 'एवं सुविहितो यज्ञो हयमेधोऽभ्यवर्तत।
लक्ष्मणेनाभिगुप्ता च हयचर्या प्रवर्तिता॥', 'evaṃ suvihito yajño hayamedho ''bhyavartata
lakṣmaṇenābhiguptā ca hayacaryā pravartitā', null, 7083009),
('ramayana-7-83-10', 10, 'Uttara Kanda, Sarga 83, Verse 10', 'नान्यः शब्दोऽभवत्तत्र हयमेधे महात्मनः।
छन्दतो देहि विस्रब्धो यावत्तुष्यन्ति याचकाः।
तावद्वानररक्षोभिर्दत्तमेवाभ्यदृश्यत॥', 'nānyaḥ śabdo ''bhavat tatra hayamedhe mahātmanaḥ
chandato dehi visrabdho yāvat tuṣyanti yācakāḥ
tāvad vānararakṣobhir dattam evābhyadṛśyata', null, 7083010),
('ramayana-7-83-11', 11, 'Uttara Kanda, Sarga 83, Verse 11', 'न कश्चिन्मलिनस्तत्र दीनो वाप्यथ वा कृशः।
तस्मिन्यज्ञवरे राज्ञो हृष्टपुष्टजनावृते॥', 'na kaś cin malinas tatra dīno vāpy atha vā kṛśaḥ
tasmin yajñavare rājño hṛṣṭapuṣṭajanāvṛte', null, 7083011),
('ramayana-7-83-12', 12, 'Uttara Kanda, Sarga 83, Verse 12', 'ये च तत्र महात्मानो मुनयश्चिरजीविनः।
नास्मरंस्तादृशं यज्ञं दानौघसमलंकृतम्॥', 'ye ca tatra mahātmāno munayaś cirajīvinaḥ
nāsmaraṃs tādṛśaṃ yajñaṃ dānaughasamalaṃkṛtam', null, 7083012),
('ramayana-7-83-13', 13, 'Uttara Kanda, Sarga 83, Verse 13', 'रजतानां सुवर्णानां रत्नानामथ वाससाम्।
अनिशं दीयमानानां नान्तः समुपदृश्यते॥', 'rajatānāṃ suvarṇānāṃ ratnānām atha vāsasām
aniśaṃ dīyamānānāṃ nāntaḥ samupadṛśyate', null, 7083013),
('ramayana-7-83-14', 14, 'Uttara Kanda, Sarga 83, Verse 14', 'न शक्रस्य न सोमस्य यमस्य वरुणस्य वा।
ईदृशो दृष्टपूर्वो न एवमूचुस्तपोधनाः॥', 'na śakrasya na somasya yamasya varuṇasya vā
īdṛśo dṛṣṭapūrvo na evam ūcus tapodhanāḥ', null, 7083014),
('ramayana-7-83-15', 15, 'Uttara Kanda, Sarga 83, Verse 15', 'सर्वत्र वानरास्तस्थुः सर्वत्रैव च राक्षसाः।
वासो धनानि कामिभ्यः पूर्णहस्ता ददुर्भृशम्॥', 'sarvatra vānarās tasthuḥ sarvatraiva ca rākṣasāḥ
vāso dhanāni kāmibhyaḥ pūrṇahastā dadur bhṛśam', null, 7083015),
('ramayana-7-83-16', 16, 'Uttara Kanda, Sarga 83, Verse 16', 'ईदृशो राजसिंहस्य यज्ञः सर्वगुणान्वितः।
संवत्सरमथो साग्रं वर्तते न च हीयते॥', 'īdṛśo rājasiṃhasya yajñaḥ sarvaguṇānvitaḥ
saṃvatsaram atho sāgraṃ vartate na ca hīyate', null, 7083016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 84 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-84-1', 1, 'Uttara Kanda, Sarga 84, Verse 1', 'वर्तमाने तथाभूते यज्ञे परमकेऽद्भुते।
सशिष्य आजगामाशु वाल्मीकिर्मुनिपुंगवः॥', 'vartamāne tathābhūte yajñe paramake ''dbhute
saśiṣya ājagāmāśu vālmīkir munipuṃgavaḥ', null, 7084001),
('ramayana-7-84-2', 2, 'Uttara Kanda, Sarga 84, Verse 2', 'स दृष्ट्वा दिव्यसंकाशं यज्ञमद्भुतदर्शनम्।
एकान्ते ऋषिवाटानां चकार उटजाञ्शुभान्॥', 'sa dṛṣṭvā divyasaṃkāśaṃ yajñam adbhutadarśanam
ekānte ṛṣivāṭānāṃ cakāra uṭajāñ śubhān', null, 7084002),
('ramayana-7-84-3', 3, 'Uttara Kanda, Sarga 84, Verse 3', 'स शिष्यावब्रवीद्धृष्टो युवां गत्वा समाहितौ।
कृत्स्नं रामायणं काव्यं गायतां परया मुदा॥', 'sa śiṣyāv abravīd dhṛṣṭo yuvāṃ gatvā samāhitau
kṛtsnaṃ rāmāyaṇaṃ kāvyaṃ gāyatāṃ parayā mudā', null, 7084003),
('ramayana-7-84-4', 4, 'Uttara Kanda, Sarga 84, Verse 4', 'ऋषिवाटेषु पुण्येषु ब्राह्मणावसथेषु च।
रथ्यासु राजमार्गेषु पार्थिवानां गृहेषु च॥', 'ṛṣivāṭeṣu puṇyeṣu brāhmaṇāvasatheṣu ca
rathyāsu rājamārgeṣu pārthivānāṃ gṛheṣu ca', null, 7084004),
('ramayana-7-84-5', 5, 'Uttara Kanda, Sarga 84, Verse 5', 'रामस्य भवनद्वारि यत्र कर्म च वर्तते।
ऋत्विजामग्रतश्चैव तत्र गेयं विशेषतः॥', 'rāmasya bhavanadvāri yatra karma ca vartate
ṛtvijām agrataś caiva tatra geyaṃ viśeṣataḥ', null, 7084005),
('ramayana-7-84-6', 6, 'Uttara Kanda, Sarga 84, Verse 6', 'इमानि च फलान्यत्र स्वादूनि विविधानि च।
जातानि पर्वताग्रेषु आस्वाद्यास्वाद्य गीयताम्॥', 'imāni ca phalāny atra svādūni vividhāni ca
jātāni parvatāgreṣu āsvādyāsvādya gīyatām', null, 7084006),
('ramayana-7-84-7', 7, 'Uttara Kanda, Sarga 84, Verse 7', 'न यास्यथः श्रमं वत्सौ भक्षयित्वा फलानि वै।
मूलानि च सुमृष्टानि नगरात्परिहास्यथ॥', 'na yāsyathaḥ śramaṃ vatsau bhakṣayitvā phalāni vai
mūlāni ca sumṛṣṭāni nagarāt parihāsyatha', null, 7084007),
('ramayana-7-84-8', 8, 'Uttara Kanda, Sarga 84, Verse 8', 'यदि शब्दापयेद्रामः श्रवणाय महीपतिः।
ऋषीणामुपविष्टानां ततो गेयं प्रवर्तताम्॥', 'yadi śabdāpayed rāmaḥ śravaṇāya mahīpatiḥ
ṛṣīṇām upaviṣṭānāṃ tato geyaṃ pravartatām', null, 7084008),
('ramayana-7-84-9', 9, 'Uttara Kanda, Sarga 84, Verse 9', 'दिवसे विंशतिः सर्गा गेया वै परया मुदा।
प्रमाणैर्बहुभिस्तत्र यथोद्दिष्टं मया पुरा॥', 'divase viṃśatiḥ sargā geyā vai parayā mudā
pramāṇair bahubhis tatra yathoddiṣṭaṃ mayā purā', null, 7084009),
('ramayana-7-84-10', 10, 'Uttara Kanda, Sarga 84, Verse 10', 'लोभश्चापि न कर्तव्यः स्वल्पोऽपि धनकाङ्क्षया।
किं धनेनाश्रमस्थानां फलमूलोपभोगिनाम्॥', 'lobhaś cāpi na kartavyaḥ svalpo ''pi dhanakāṅkṣayā
kiṃ dhanenāśramasthānāṃ phalamūlopabhoginām', null, 7084010),
('ramayana-7-84-11', 11, 'Uttara Kanda, Sarga 84, Verse 11', 'यदि पृच्छेत्स काकुत्स्थो युवां कस्येति दारकौ।
वाल्मीकेरथ शिष्यौ हि ब्रूतामेवं नराधिपम्॥', 'yadi pṛcchet sa kākutstho yuvāṃ kasyeti dārakau
vālmīker atha śiṣyau hi brūtām evaṃ narādhipam', null, 7084011),
('ramayana-7-84-12', 12, 'Uttara Kanda, Sarga 84, Verse 12', 'इमास्तन्त्रीः सुमधुराः स्थानं वा पूर्वदर्शितम्।
मूर्छयित्वा सुमधुरं गायेतां विगतज्वरौ॥', 'imās tantrīḥ sumadhurāḥ sthānaṃ vā pūrvadarśitam
mūrchayitvā sumadhuraṃ gāyetāṃ vigatajvarau', null, 7084012),
('ramayana-7-84-13', 13, 'Uttara Kanda, Sarga 84, Verse 13', 'आदिप्रभृति गेयं स्यान्न चावज्ञाय पार्थिवम्।
पिता हि सर्वभूतानां राजा भवति धर्मतः॥', 'ādiprabhṛti geyaṃ syān na cāvajñāya pārthivam
pitā hi sarvabhūtānāṃ rājā bhavati dharmataḥ', null, 7084013),
('ramayana-7-84-14', 14, 'Uttara Kanda, Sarga 84, Verse 14', 'तद्युवां हृष्टमनसौ श्वः प्रभाते समाधिना।
गायेतां मधुरं गेयं तन्त्रीलयसमन्वितम्॥', 'tad yuvāṃ hṛṣṭamanasau śvaḥ prabhāte samādhinā
gāyetāṃ madhuraṃ geyaṃ tantrīlayasamanvitam', null, 7084014),
('ramayana-7-84-15', 15, 'Uttara Kanda, Sarga 84, Verse 15', 'इति संदिश्य बहुशो मुनिः प्राचेतसस्तदा।
वाल्मीकिः परमोदारस्तूष्णीमासीन्महायशाः॥', 'iti saṃdiśya bahuśo muniḥ prācetasas tadā
vālmīkiḥ paramodāras tūṣṇīm āsīn mahāyaśāḥ', null, 7084015),
('ramayana-7-84-16', 16, 'Uttara Kanda, Sarga 84, Verse 16', 'तामद्भुतां तौ हृदये कुमारौ निवेश्य वाणीमृषिभाषितां शुभाम्।
समुत्सुकौ तौ सुखमूषतुर्निशां यथाश्विनौ भार्गवनीतिसंस्कृतौ॥', 'tām adbhutāṃ tau hṛdaye kumārau niveśya vāṇīm ṛṣibhāṣitāṃ śubhām
samutsukau tau sukham ūṣatur niśāṃ yathāśvinau bhārgavanītisaṃskṛtau', null, 7084016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 85 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-85-1', 1, 'Uttara Kanda, Sarga 85, Verse 1', 'तौ रजन्यां प्रभातायां स्नातौ हुतहुताशनौ।
यथोक्तमृषिणा पूर्वं तत्र तत्राभ्यगायताम्॥', 'tau rajanyāṃ prabhātāyāṃ snātau hutahutāśanau
yathoktam ṛṣiṇā pūrvaṃ tatra tatrābhyagāyatām', null, 7085001),
('ramayana-7-85-2', 2, 'Uttara Kanda, Sarga 85, Verse 2', 'तां स शुश्राव काकुत्स्थः पूर्वचर्यां ततस्ततः।
अपूर्वां पाठ्य जातिं च गेयेन समलंकृताम्॥', 'tāṃ sa śuśrāva kākutsthaḥ pūrvacaryāṃ tatas tataḥ
apūrvāṃ pāṭhya jātiṃ ca geyena samalaṃkṛtām', null, 7085002),
('ramayana-7-85-3', 3, 'Uttara Kanda, Sarga 85, Verse 3', 'प्रमाणैर्बहुभिर्बद्धां तन्त्रीलयसमन्विताम्।
बालाभ्यां राघवः श्रुत्वा कौतूहलपरोऽभवत्॥', 'pramāṇair bahubhir baddhāṃ tantrīlayasamanvitām
bālābhyāṃ rāghavaḥ śrutvā kautūhalaparo ''bhavat', null, 7085003),
('ramayana-7-85-4', 4, 'Uttara Kanda, Sarga 85, Verse 4', 'अथ कर्मान्तरे राजा समानीय महामुनीन्।
पार्थिवांश्च नरव्याघ्रः पण्डितान्नैगमांस्तथा॥', 'atha karmāntare rājā samānīya mahāmunīn
pārthivāṃś ca naravyāghraḥ paṇḍitān naigamāṃs tathā', null, 7085004),
('ramayana-7-85-5', 5, 'Uttara Kanda, Sarga 85, Verse 5', 'पौराणिकाञ्शब्दवितो ये च वृद्धा द्विजातयः।
एतान्सर्वान्समानीय गातारौ समवेशयत्॥', 'paurāṇikāñ śabdavito ye ca vṛddhā dvijātayaḥ
etān sarvān samānīya gātārau samaveśayat', null, 7085005),
('ramayana-7-85-6', 6, 'Uttara Kanda, Sarga 85, Verse 6', 'हृष्टा ऋषिगणास्तत्र पार्थिवाश्च महौजसः।
पिबन्त इव चक्षुर्भ्यां राजानं गायकौ च तौ॥', 'hṛṣṭā ṛṣigaṇās tatra pārthivāś ca mahaujasaḥ
pibanta iva cakṣurbhyāṃ rājānaṃ gāyakau ca tau', null, 7085006),
('ramayana-7-85-7', 7, 'Uttara Kanda, Sarga 85, Verse 7', 'परस्परमथोचुस्ते सर्व एव समं ततः।
उभौ रामस्य सदृशौ बिम्बाद्बिम्बमिवोद्धृतौ॥', 'parasparam athocus te sarva eva samaṃ tataḥ
ubhau rāmasya sadṛśau bimbād bimbam ivoddhṛtau', null, 7085007),
('ramayana-7-85-8', 8, 'Uttara Kanda, Sarga 85, Verse 8', 'जटिलौ यदि न स्यातां न वल्कलधरौ यदि।
विशेषं नाधिगच्छामो गायतो राघवस्य च॥', 'jaṭilau yadi na syātāṃ na valkaladharau yadi
viśeṣaṃ nādhigacchāmo gāyato rāghavasya ca', null, 7085008),
('ramayana-7-85-9', 9, 'Uttara Kanda, Sarga 85, Verse 9', 'तेषां संवदतामेवं श्रोतॄणां हर्षवर्धनम्।
गेयं प्रचक्रतुस्तत्र तावुभौ मुनिदारकौ॥', 'teṣāṃ saṃvadatām evaṃ śrotṝṇāṃ harṣavardhanam
geyaṃ pracakratus tatra tāv ubhau munidārakau', null, 7085009),
('ramayana-7-85-10', 10, 'Uttara Kanda, Sarga 85, Verse 10', 'ततः प्रवृत्तं मधुरं गान्धर्वमतिमानुषम्।
न च तृप्तिं ययुः सर्वे श्रोतारो गेय संपदा॥', 'tataḥ pravṛttaṃ madhuraṃ gāndharvam atimānuṣam
na ca tṛptiṃ yayuḥ sarve śrotāro geya saṃpadā', null, 7085010),
('ramayana-7-85-11', 11, 'Uttara Kanda, Sarga 85, Verse 11', 'प्रवृत्तमादितः पूर्वं सर्गान्नारददर्शनात्।
ततः प्रभृति सर्गांश्च यावद्विंशत्यगायताम्॥', 'pravṛttam āditaḥ pūrvaṃ sargān nāradadarśanāt
tataḥ prabhṛti sargāṃś ca yāvadviṃśaty agāyatām', null, 7085011),
('ramayana-7-85-12', 12, 'Uttara Kanda, Sarga 85, Verse 12', 'ततोऽपराह्णसमये राघवः समभाषत।
श्रुत्वा विंशतिसर्गांस्तान्भरतं भ्रातृवत्सलः॥', 'tato ''parāhṇasamaye rāghavaḥ samabhāṣata
śrutvā viṃśatisargāṃs tān bharataṃ bhrātṛvatsalaḥ', null, 7085012),
('ramayana-7-85-13', 13, 'Uttara Kanda, Sarga 85, Verse 13', 'अष्टादश सहस्राणि सुवर्णस्य महात्मनोः।
ददस्व शीघ्रं काकुत्स्थ बालयोर्मा वृथा श्रमः॥', 'aṣṭādaśa sahasrāṇi suvarṇasya mahātmanoḥ
dadasva śīghraṃ kākutstha bālayor mā vṛthā śramaḥ', null, 7085013),
('ramayana-7-85-14', 14, 'Uttara Kanda, Sarga 85, Verse 14', 'दीयमानं सुवर्णं तन्नागृह्णीतां कुशीलवौ।
ऊचतुश्च महात्मानौ किमनेनेति विस्मितौ॥', 'dīyamānaṃ suvarṇaṃ tan nāgṛhṇītāṃ kuśīlavau
ūcatuś ca mahātmānau kim aneneti vismitau', null, 7085014),
('ramayana-7-85-15', 15, 'Uttara Kanda, Sarga 85, Verse 15', 'वन्येन फलमूलेन निरतु स्वो वनौकसौ।
सुवर्णेन हिरण्येन किं करिष्यावहे वने॥', 'vanyena phalamūlena niratu svo vanaukasau
suvarṇena hiraṇyena kiṃ kariṣyāvahe vane', null, 7085015),
('ramayana-7-85-16', 16, 'Uttara Kanda, Sarga 85, Verse 16', 'तथा तयोः प्रब्रुवतोः कौतूहलसमन्विताः।
श्रोतारश्चैव रामश्च सर्व एव सुविस्मिताः॥', 'tathā tayoḥ prabruvatoḥ kautūhalasamanvitāḥ
śrotāraś caiva rāmaś ca sarva eva suvismitāḥ', null, 7085016),
('ramayana-7-85-17', 17, 'Uttara Kanda, Sarga 85, Verse 17', 'तस्य चैवागमं रामः काव्यस्य श्रोतुमुत्सुकः।
पप्रच्छ तौ महातेजास्तावुभौ मुनिदारकौ॥', 'tasya caivāgamaṃ rāmaḥ kāvyasya śrotum utsukaḥ
papraccha tau mahātejās tāv ubhau munidārakau', null, 7085017),
('ramayana-7-85-18', 18, 'Uttara Kanda, Sarga 85, Verse 18', 'किंप्रमाणमिदं काव्यं का प्रतिष्ठा महात्मनः।
कर्ता काव्यस्य महतः को वासौ मुनिपुंगवः॥', 'kiṃpramāṇam idaṃ kāvyaṃ kā pratiṣṭhā mahātmanaḥ
kartā kāvyasya mahataḥ ko vāsau munipuṃgavaḥ', null, 7085018),
('ramayana-7-85-19', 19, 'Uttara Kanda, Sarga 85, Verse 19', 'पृच्छन्तं राघवं वाक्यमूचतुर्मुनिदारकौ।
वाल्मीकिर्भगवान्कर्ता संप्राप्तो यज्ञसंनिधिम्।
येनेदं चरितं तुभ्यमशेषं संप्रदर्शितम्॥', 'pṛcchantaṃ rāghavaṃ vākyam ūcatur munidārakau
vālmīkir bhagavān kartā saṃprāpto yajñasaṃnidhim
yenedaṃ caritaṃ tubhyam aśeṣaṃ saṃpradarśitam', null, 7085019),
('ramayana-7-85-20', 20, 'Uttara Kanda, Sarga 85, Verse 20', 'आदिप्रभृति राजेन्द्र पञ्चसर्ग शतानि च।
प्रतिष्ठा जीवितं यावत्तावद्राजञ्शुभाशुभम्॥', 'ādiprabhṛti rājendra pañcasarga śatāni ca
pratiṣṭhā jīvitaṃ yāvat tāvad rājañ śubhāśubham', null, 7085020),
('ramayana-7-85-21', 21, 'Uttara Kanda, Sarga 85, Verse 21', 'यदि बुद्धिः कृता राजञ्श्रवणाय महारथ।
कर्मान्तरे क्षणी हूतस्तच्छृणुष्व सहानुजः॥', 'yadi buddhiḥ kṛtā rājañ śravaṇāya mahāratha
karmāntare kṣaṇī hūtas tac chṛṇuṣva sahānujaḥ', null, 7085021),
('ramayana-7-85-22', 22, 'Uttara Kanda, Sarga 85, Verse 22', 'बाढमित्यब्रवीद्रामस्तौ चानुज्ञाप्य राघवम्।
प्रहृष्टौ जग्मतुर्वासं यत्रासौ मुनिपुंगवः॥', 'bāḍham ity abravīd rāmas tau cānujñāpya rāghavam
prahṛṣṭau jagmatur vāsaṃ yatrāsau munipuṃgavaḥ', null, 7085022),
('ramayana-7-85-23', 23, 'Uttara Kanda, Sarga 85, Verse 23', 'रामोऽपि मुनिभिः सार्धं पार्थिवैश्च महात्मभिः।
श्रुत्वा तद्गीतमाधुर्यं कर्मशालामुपागमत्॥', 'rāmo ''pi munibhiḥ sārdhaṃ pārthivaiś ca mahātmabhiḥ
śrutvā tad gītamādhuryaṃ karmaśālām upāgamat', null, 7085023)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 86 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-86-1', 1, 'Uttara Kanda, Sarga 86, Verse 1', 'रामो बहून्यहान्येव तद्गीतं परमाद्भुतम्।
शुश्राव मुनिभिः सार्धं राजभिः सह वानरैः॥', 'rāmo bahūny ahāny eva tad gītaṃ paramādbhutam
śuśrāva munibhiḥ sārdhaṃ rājabhiḥ saha vānaraiḥ', null, 7086001),
('ramayana-7-86-2', 2, 'Uttara Kanda, Sarga 86, Verse 2', 'तस्मिन्गीते तु विज्ञाय सीतापुत्रौ कुशीलवौ।
तस्याः परिषदो मध्ये रामो वचनमब्रवीत्॥', 'tasmin gīte tu vijñāya sītāputrau kuśīlavau
tasyāḥ pariṣado madhye rāmo vacanam abravīt', null, 7086002),
('ramayana-7-86-3', 3, 'Uttara Kanda, Sarga 86, Verse 3', 'मद्वचो ब्रूत गच्छध्वमिति भगवतोऽन्तिकम्॥', 'madvaco brūta gacchadhvam iti bhagavato ''ntikam', null, 7086003),
('ramayana-7-86-4', 4, 'Uttara Kanda, Sarga 86, Verse 4', 'यदि शुद्धसमाचारा यदि वा वीतकल्मषा।
करोत्विहात्मनः शुद्धिमनुमान्य महामुनिम्॥', 'yadi śuddhasamācārā yadi vā vītakalmaṣā
karotv ihātmanaḥ śuddhim anumānya mahāmunim', null, 7086004),
('ramayana-7-86-5', 5, 'Uttara Kanda, Sarga 86, Verse 5', 'छन्दं मुनेस्तु विज्ञाय सीतायाश्च मनोगतम्।
प्रत्ययं दातुकामायास्ततः शंसत मे लघु॥', 'chandaṃ munes tu vijñāya sītāyāś ca manogatam
pratyayaṃ dātukāmāyās tataḥ śaṃsata me laghu', null, 7086005),
('ramayana-7-86-6', 6, 'Uttara Kanda, Sarga 86, Verse 6', 'श्वः प्रभाते तु शपथं मैथिली जनकात्मजा।
करोतु परिषन्मध्ये शोधनार्थं ममेह च॥', 'śvaḥ prabhāte tu śapathaṃ maithilī janakātmajā
karotu pariṣanmadhye śodhanārthaṃ mameha ca', null, 7086006),
('ramayana-7-86-7', 7, 'Uttara Kanda, Sarga 86, Verse 7', 'श्रुत्वा तु राघवस्यैतद्वचः परममद्भुतम्।
दूताः संप्रययुर्वाटं यत्रास्ते मुनिपुंगवः॥', 'śrutvā tu rāghavasyaitad vacaḥ paramam adbhutam
dūtāḥ saṃprayayur vāṭaṃ yatrāste munipuṃgavaḥ', null, 7086007),
('ramayana-7-86-8', 8, 'Uttara Kanda, Sarga 86, Verse 8', 'ते प्रणम्य महात्मानं ज्वलन्तममितप्रभम्।
ऊचुस्ते राम वाक्यानि मृदूनि मधुराणि च॥', 'te praṇamya mahātmānaṃ jvalantam amitaprabham
ūcus te rāma vākyāni mṛdūni madhurāṇi ca', null, 7086008),
('ramayana-7-86-9', 9, 'Uttara Kanda, Sarga 86, Verse 9', 'तेषां तद्भाषितं श्रुत्वा रामस्य च मनोगतम्।
विज्ञाय सुमहातेजा मुनिर्वाक्यमथाब्रवीत्॥', 'teṣāṃ tad bhāṣitaṃ śrutvā rāmasya ca manogatam
vijñāya sumahātejā munir vākyam athābravīt', null, 7086009),
('ramayana-7-86-10', 10, 'Uttara Kanda, Sarga 86, Verse 10', 'एवं भवतु भद्रं वो यथा तुष्यति राघवः।
तथा करिष्यते सीता दैवतं हि पतिः स्त्रियाः॥', 'evaṃ bhavatu bhadraṃ vo yathā tuṣyati rāghavaḥ
tathā kariṣyate sītā daivataṃ hi patiḥ striyāḥ', null, 7086010),
('ramayana-7-86-11', 11, 'Uttara Kanda, Sarga 86, Verse 11', 'तथोक्ता मुनिना सर्वे रामदूता महौजसः।
प्रत्येत्य राघवं सर्वे मुनिवाक्यं बभाषिरे॥', 'tathoktā muninā sarve rāmadūtā mahaujasaḥ
pratyetya rāghavaṃ sarve munivākyaṃ babhāṣire', null, 7086011),
('ramayana-7-86-12', 12, 'Uttara Kanda, Sarga 86, Verse 12', 'ततः प्रहृष्टः काकुत्स्थः श्रुत्वा वाक्यं महात्मनः।
ऋषींस्तत्र समेतांश्च राज्ञश्चैवाभ्यभाषत॥', 'tataḥ prahṛṣṭaḥ kākutsthaḥ śrutvā vākyaṃ mahātmanaḥ
ṛṣīṃs tatra sametāṃś ca rājñaś caivābhyabhāṣata', null, 7086012),
('ramayana-7-86-13', 13, 'Uttara Kanda, Sarga 86, Verse 13', 'भगवन्तः सशिष्या वै सानुगश्च नराधिपाः।
पश्यन्तु सीताशपथं यश्चैवान्योऽभिकाङ्क्षते॥', 'bhagavantaḥ saśiṣyā vai sānugaś ca narādhipāḥ
paśyantu sītāśapathaṃ yaś caivānyo ''bhikāṅkṣate', null, 7086013),
('ramayana-7-86-14', 14, 'Uttara Kanda, Sarga 86, Verse 14', 'तस्य तद्वचनं श्रुत्वा राघवस्य महात्मनः।
सर्वेषमृषिमुख्यानां साधुवादो महानभूत्॥', 'tasya tad vacanaṃ śrutvā rāghavasya mahātmanaḥ
sarveṣam ṛṣimukhyānāṃ sādhuvādo mahān abhūt', null, 7086014),
('ramayana-7-86-15', 15, 'Uttara Kanda, Sarga 86, Verse 15', 'राजानश्च महात्मानः प्रशंसन्ति स्म राघवम्।
उपपन्नं नरश्रेष्ठ त्वय्येव भुवि नान्यतः॥', 'rājānaś ca mahātmānaḥ praśaṃsanti sma rāghavam
upapannaṃ naraśreṣṭha tvayy eva bhuvi nānyataḥ', null, 7086015),
('ramayana-7-86-16', 16, 'Uttara Kanda, Sarga 86, Verse 16', 'एवं विनिश्चयं कृत्वा श्वोभूत इति राघवः।
विसर्जयामास तदा सर्वांस्ताञ्शत्रुसूदनः॥', 'evaṃ viniścayaṃ kṛtvā śvobhūta iti rāghavaḥ
visarjayām āsa tadā sarvāṃs tāñ śatrusūdanaḥ', null, 7086016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 87 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-87-1', 1, 'Uttara Kanda, Sarga 87, Verse 1', 'तस्यां रजन्यां व्युष्टायां यज्ञवाटगतो नृपः।
ऋषीन्सर्वान्महातेजाः शब्दापयति राघवः॥', 'tasyāṃ rajanyāṃ vyuṣṭāyāṃ yajñavāṭagato nṛpaḥ
ṛṣīn sarvān mahātejāḥ śabdāpayati rāghavaḥ', null, 7087001),
('ramayana-7-87-2', 2, 'Uttara Kanda, Sarga 87, Verse 2', 'वसिष्ठो वामदेवश्च जाबालिरथ काश्यपः।
विश्वामित्रो दीर्घतपा दुर्वासाश्च महातपाः॥', 'vasiṣṭho vāmadevaś ca jābālir atha kāśyapaḥ
viśvāmitro dīrghatapā durvāsāś ca mahātapāḥ', null, 7087002),
('ramayana-7-87-3', 3, 'Uttara Kanda, Sarga 87, Verse 3', 'अगस्त्योऽथ तथाशक्तिर्भार्गवश्चैव वामनः।
मार्कण्डेयश्च दीर्घायुर्मौद्गल्यश्च महातपाः॥', 'agastyo ''tha tathāśaktir bhārgavaś caiva vāmanaḥ
mārkaṇḍeyaś ca dīrghāyur maudgalyaś ca mahātapāḥ', null, 7087003),
('ramayana-7-87-4', 4, 'Uttara Kanda, Sarga 87, Verse 4', 'भार्गवश्च्यवनश्चैव शतानन्दश्च धर्मवित्।
भरद्वाजश्च तेजस्वी अग्निपुत्रश्च सुप्रभः॥', 'bhārgavaś cyavanaś caiva śatānandaś ca dharmavit
bharadvājaś ca tejasvī agniputraś ca suprabhaḥ', null, 7087004),
('ramayana-7-87-5', 5, 'Uttara Kanda, Sarga 87, Verse 5', 'एते चान्ये च मुनयो बहवः संशितव्रताः।
राजानश्च नरव्याघ्राः सर्व एव समागताः॥', 'ete cānye ca munayo bahavaḥ saṃśitavratāḥ
rājānaś ca naravyāghrāḥ sarva eva samāgatāḥ', null, 7087005),
('ramayana-7-87-6', 6, 'Uttara Kanda, Sarga 87, Verse 6', 'राक्षसाश्च महावीर्या वानराश्च महाबलाः।
समाजग्मुर्महात्मानः सर्व एव कुतूहलात्॥', 'rākṣasāś ca mahāvīryā vānarāś ca mahābalāḥ
samājagmur mahātmānaḥ sarva eva kutūhalāt', null, 7087006),
('ramayana-7-87-7', 7, 'Uttara Kanda, Sarga 87, Verse 7', 'क्षत्रियाश्चैव वैश्याश्च शूद्राश्चैव सहस्रशः।
सीताशपथवीक्षार्थं सर्व एव समागताः॥', 'kṣatriyāś caiva vaiśyāś ca śūdrāś caiva sahasraśaḥ
sītāśapathavīkṣārthaṃ sarva eva samāgatāḥ', null, 7087007),
('ramayana-7-87-8', 8, 'Uttara Kanda, Sarga 87, Verse 8', 'तथा समागतं सर्वमश्वभूतमिवाचलम्।
श्रुत्वा मुनिवरस्तूर्णं ससीतः समुपागमत्॥', 'tathā samāgataṃ sarvam aśvabhūtam ivācalam
śrutvā munivaras tūrṇaṃ sasītaḥ samupāgamat', null, 7087008),
('ramayana-7-87-9', 9, 'Uttara Kanda, Sarga 87, Verse 9', 'तमृषिं पृष्ठतः सीता सान्वगच्छदवाङ्मुखी।
कृताञ्जलिर्बाष्पगला कृत्वा रामं मनोगतम्॥', 'tam ṛṣiṃ pṛṣṭhataḥ sītā sānvagacchad avāṅmukhī
kṛtāñjalir bāṣpagalā kṛtvā rāmaṃ manogatam', null, 7087009),
('ramayana-7-87-10', 10, 'Uttara Kanda, Sarga 87, Verse 10', 'तां दृष्ट्वा श्रीमिवायान्तीं ब्रह्माणमनुगामिनीम्।
वाल्मीकेः पृष्ठतः सीतां साधुकारो महानभूत्॥', 'tāṃ dṛṣṭvā śrīm ivāyāntīṃ brahmāṇam anugāminīm
vālmīkeḥ pṛṣṭhataḥ sītāṃ sādhukāro mahān abhūt', null, 7087010),
('ramayana-7-87-11', 11, 'Uttara Kanda, Sarga 87, Verse 11', 'ततो हलहला शब्दः सर्वेषामेवमाबभौ।
दुःखजेन विशालेन शोकेनाकुलितात्मनाम्॥', 'tato halahalā śabdaḥ sarveṣām evam ābabhau
duḥkhajena viśālena śokenākulitātmanām', null, 7087011),
('ramayana-7-87-12', 12, 'Uttara Kanda, Sarga 87, Verse 12', 'साधु सीतेति के चित्तु साधु रामेति चापरे।
उभावेव तु तत्रान्ये साधु साध्विति चाब्रुवन्॥', 'sādhu sīteti ke cit tu sādhu rāmeti cāpare
ubhāv eva tu tatrānye sādhu sādhv iti cābruvan', null, 7087012),
('ramayana-7-87-13', 13, 'Uttara Kanda, Sarga 87, Verse 13', 'ततो मध्यं जनौघानां प्रविश्य मुनिपुंगवः।
सीतासहायो वाल्मीकिरिति होवाच राघवम्॥', 'tato madhyaṃ janaughānāṃ praviśya munipuṃgavaḥ
sītāsahāyo vālmīkir iti hovāca rāghavam', null, 7087013),
('ramayana-7-87-14', 14, 'Uttara Kanda, Sarga 87, Verse 14', 'इयं दाशरथे सीता सुव्रता धर्मचारिणी।
अपापा ते परित्यक्ता ममाश्रमसमीपतः॥', 'iyaṃ dāśarathe sītā suvratā dharmacāriṇī
apāpā te parityaktā mamāśramasamīpataḥ', null, 7087014),
('ramayana-7-87-15', 15, 'Uttara Kanda, Sarga 87, Verse 15', 'लोकापवादभीतस्य तव राम महाव्रत।
प्रत्ययं दास्यते सीता तामनुज्ञातुमर्हसि॥', 'lokāpavādabhītasya tava rāma mahāvrata
pratyayaṃ dāsyate sītā tām anujñātum arhasi', null, 7087015),
('ramayana-7-87-16', 16, 'Uttara Kanda, Sarga 87, Verse 16', 'इमौ च जानकी पुत्रावुभौ च यमजातकौ।
सुतौ तवैव दुर्धर्षो सत्यमेतद्ब्रवीमि ते॥', 'imau ca jānakī putrāv ubhau ca yamajātakau
sutau tavaiva durdharṣo satyam etad bravīmi te', null, 7087016),
('ramayana-7-87-17', 17, 'Uttara Kanda, Sarga 87, Verse 17', 'प्रचेतसोऽहं दशमः पुत्रो राघवनन्दन।
न स्मराम्यनृतं वाक्यं तथेमौ तव पुत्रकौ॥', 'pracetaso ''haṃ daśamaḥ putro rāghavanandana
na smarāmy anṛtaṃ vākyaṃ tathemau tava putrakau', null, 7087017),
('ramayana-7-87-18', 18, 'Uttara Kanda, Sarga 87, Verse 18', 'बहुवर्षसहस्राणि तपश्चर्या मया कृता।
तस्याः फलमुपाश्नीयामपापा मैथिली यथा॥', 'bahuvarṣasahasrāṇi tapaścaryā mayā kṛtā
tasyāḥ phalam upāśnīyām apāpā maithilī yathā', null, 7087018),
('ramayana-7-87-19', 19, 'Uttara Kanda, Sarga 87, Verse 19', 'अहं पञ्चसु भूतेषु मनःषष्ठेषु राघव।
विचिन्त्य सीतां शुद्धेति न्यगृह्णां वननिर्झरे॥', 'ahaṃ pañcasu bhūteṣu manaḥṣaṣṭheṣu rāghava
vicintya sītāṃ śuddheti nyagṛhṇāṃ vananirjhare', null, 7087019),
('ramayana-7-87-20', 20, 'Uttara Kanda, Sarga 87, Verse 20', 'इयं शुद्धसमाचारा अपापा पतिदेवता।
लोकापवादभीतस्य दास्यति प्रत्ययं तव॥', 'iyaṃ śuddhasamācārā apāpā patidevatā
lokāpavādabhītasya dāsyati pratyayaṃ tava', null, 7087020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 88 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-88-1', 1, 'Uttara Kanda, Sarga 88, Verse 1', 'वाल्मीकिनैवमुक्तस्तु राघवः प्रत्यभाषत।
प्राञ्जलिर्जगतो मध्ये दृष्ट्वा तां देववर्णिनीम्॥', 'vālmīkinaivam uktas tu rāghavaḥ pratyabhāṣata
prāñjalir jagato madhye dṛṣṭvā tāṃ devavarṇinīm', null, 7088001),
('ramayana-7-88-2', 2, 'Uttara Kanda, Sarga 88, Verse 2', 'एवमेतन्महाभाग यथा वदसि धर्मवित्।
प्रत्ययो हि मम ब्रह्मंस्तव वाक्यैरकल्मषैः॥', 'evam etan mahābhāga yathā vadasi dharmavit
pratyayo hi mama brahmaṃs tava vākyair akalmaṣaiḥ', null, 7088002),
('ramayana-7-88-3', 3, 'Uttara Kanda, Sarga 88, Verse 3', 'प्रत्ययो हि पुरा दत्तो वैदेह्या सुरसंनिधौ।
सेयं लोकभयाद्ब्रह्मन्नपापेत्यभिजानता।
परित्यक्ता मया सीता तद्भवान्क्षन्तुमर्हति॥', 'pratyayo hi purā datto vaidehyā surasaṃnidhau
seyaṃ lokabhayād brahmann apāpety abhijānatā
parityaktā mayā sītā tad bhavān kṣantum arhati', null, 7088003),
('ramayana-7-88-4', 4, 'Uttara Kanda, Sarga 88, Verse 4', 'जानामि चेमौ पुत्रौ मे यमजातौ कुशीलवौ।
शुद्धायां जगतो मध्ये मैथिल्यां प्रीतिरस्तु मे॥', 'jānāmi cemau putrau me yamajātau kuśīlavau
śuddhāyāṃ jagato madhye maithilyāṃ prītir astu me', null, 7088004),
('ramayana-7-88-5', 5, 'Uttara Kanda, Sarga 88, Verse 5', 'अभिप्रायं तु विज्ञाय रामस्य सुरसत्तमाः।
पितामहं पुरस्कृत्य सर्व एव समागताः॥', 'abhiprāyaṃ tu vijñāya rāmasya surasattamāḥ
pitāmahaṃ puraskṛtya sarva eva samāgatāḥ', null, 7088005),
('ramayana-7-88-6', 6, 'Uttara Kanda, Sarga 88, Verse 6', 'आदित्या वसवो रुद्रा विश्वे देशा मरुद्गणाः।
अश्विनावृषिगन्धर्वा अप्सराणां गणास्तथा।
साध्याश्च देवाः सर्वे ते सर्वे च परमर्षयः॥', 'ādityā vasavo rudrā viśve deśā marudgaṇāḥ
aśvināv ṛṣigandharvā apsarāṇāṃ gaṇās tathā
sādhyāś ca devāḥ sarve te sarve ca paramarṣayaḥ', null, 7088006),
('ramayana-7-88-7', 7, 'Uttara Kanda, Sarga 88, Verse 7', 'ततो वायुः शुभः पुण्यो दिव्यगन्धो मनोरमः।
तं जनौघं सुरश्रेष्ठो ह्लादयामास सर्वतः॥', 'tato vāyuḥ śubhaḥ puṇyo divyagandho manoramaḥ
taṃ janaughaṃ suraśreṣṭho hlādayām āsa sarvataḥ', null, 7088007),
('ramayana-7-88-8', 8, 'Uttara Kanda, Sarga 88, Verse 8', 'तदद्भुतमिवाचिन्त्यं निरीक्षन्ते समाहिताः।
मानवाः सर्वराष्ट्रेभ्यः पूर्वं कृतयुगे यथा॥', 'tad adbhutam ivācintyaṃ nirīkṣante samāhitāḥ
mānavāḥ sarvarāṣṭrebhyaḥ pūrvaṃ kṛtayuge yathā', null, 7088008),
('ramayana-7-88-9', 9, 'Uttara Kanda, Sarga 88, Verse 9', 'सर्वान्समागतान्दृष्ट्वा सीता काषायवासिनी।
अब्रवीत्प्राञ्जलिर्वाक्यमधोदृष्टिरवान्मुखी॥', 'sarvān samāgatān dṛṣṭvā sītā kāṣāyavāsinī
abravīt prāñjalir vākyam adhodṛṣṭir avānmukhī', null, 7088009),
('ramayana-7-88-10', 10, 'Uttara Kanda, Sarga 88, Verse 10', 'यथाहं राघवादन्यं मनसापि न चिन्तये।
तथा मे माधवी देवी विवरं दातुमर्हति॥', 'yathāhaṃ rāghavād anyaṃ manasāpi na cintaye
tathā me mādhavī devī vivaraṃ dātum arhati', null, 7088010),
('ramayana-7-88-11', 11, 'Uttara Kanda, Sarga 88, Verse 11', 'तथा शपन्त्यां वैदेह्यां प्रादुरासीत्तदद्भुतम्।
भूतलादुत्थितं दिव्यं सिंहासनमनुत्तमम्॥', 'tathā śapantyāṃ vaidehyāṃ prādurāsīt tad adbhutam
bhūtalād utthitaṃ divyaṃ siṃhāsanam anuttamam', null, 7088011),
('ramayana-7-88-12', 12, 'Uttara Kanda, Sarga 88, Verse 12', 'ध्रियमाणं शिरोभिस्तन्नागैरमितविक्रमैः।
दिव्यं दिव्येन वपुषा सर्वरत्नविभूषितम्॥', 'dhriyamāṇaṃ śirobhis tan nāgair amitavikramaiḥ
divyaṃ divyena vapuṣā sarvaratnavibhūṣitam', null, 7088012),
('ramayana-7-88-13', 13, 'Uttara Kanda, Sarga 88, Verse 13', 'तस्मिंस्तु धरणी देवी बाहुभ्यां गृह्य मैथिलीम्।
स्वागतेनाभिनन्द्यैनामासने चोपवेषयत्॥', 'tasmiṃs tu dharaṇī devī bāhubhyāṃ gṛhya maithilīm
svāgatenābhinandyainām āsane copaveṣayat', null, 7088013),
('ramayana-7-88-14', 14, 'Uttara Kanda, Sarga 88, Verse 14', 'तामासनगतां दृष्ट्वा प्रविशन्तीं रसातलम्।
पुण्यवृष्टिरविच्छिन्ना दिव्या सीतामवाकिरत्॥', 'tām āsanagatāṃ dṛṣṭvā praviśantīṃ rasātalam
puṇyavṛṣṭir avicchinnā divyā sītām avākirat', null, 7088014),
('ramayana-7-88-15', 15, 'Uttara Kanda, Sarga 88, Verse 15', 'साधुकारश्च सुमहान्देवानां सहसोत्थितः।
साधु साध्विति वै सीते यस्यास्ते शीलमीदृशम्॥', 'sādhukāraś ca sumahān devānāṃ sahasotthitaḥ
sādhu sādhv iti vai sīte yasyās te śīlam īdṛśam', null, 7088015),
('ramayana-7-88-16', 16, 'Uttara Kanda, Sarga 88, Verse 16', 'एवं बहुविधा वाचो ह्यन्तरिक्षगताः सुराः।
व्याजह्रुर्हृष्टमनसो दृष्ट्वा सीताप्रवेशनम्॥', 'evaṃ bahuvidhā vāco hy antarikṣagatāḥ surāḥ
vyājahrur hṛṣṭamanaso dṛṣṭvā sītāpraveśanam', null, 7088016),
('ramayana-7-88-17', 17, 'Uttara Kanda, Sarga 88, Verse 17', 'यज्ञवाटगताश्चापि मुनयः सर्व एव ते।
राजानश्च नरव्याघ्रा विस्मयान्नोपरेमिरे॥', 'yajñavāṭagatāś cāpi munayaḥ sarva eva te
rājānaś ca naravyāghrā vismayān noparemire', null, 7088017),
('ramayana-7-88-18', 18, 'Uttara Kanda, Sarga 88, Verse 18', 'अन्तरिक्षे च भूमौ च सर्वे स्थावरजङ्गमाः।
दानवाश्च महाकायाः पाताले पन्नगाधिपाः॥', 'antarikṣe ca bhūmau ca sarve sthāvarajaṅgamāḥ
dānavāś ca mahākāyāḥ pātāle pannagādhipāḥ', null, 7088018),
('ramayana-7-88-19', 19, 'Uttara Kanda, Sarga 88, Verse 19', 'के चिद्विनेदुः संहृष्टाः के चिद्ध्यानपरायणाः।
के चिद्रामं निरीक्षन्ते के चित्सीतामचेतनाः॥', 'ke cid vineduḥ saṃhṛṣṭāḥ ke cid dhyānaparāyaṇāḥ
ke cid rāmaṃ nirīkṣante ke cit sītām acetanāḥ', null, 7088019),
('ramayana-7-88-20', 20, 'Uttara Kanda, Sarga 88, Verse 20', 'सीताप्रवेशनं दृष्ट्वा तेषामासीत्समागमः।
तं मुहूर्तमिवात्यर्थं सर्वं संमोहितं जगत्॥', 'sītāpraveśanaṃ dṛṣṭvā teṣām āsīt samāgamaḥ
taṃ muhūrtam ivātyarthaṃ sarvaṃ saṃmohitaṃ jagat', null, 7088020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 89 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-89-1', 1, 'Uttara Kanda, Sarga 89, Verse 1', 'तदावसाने यज्ञस्य रामः परमदुर्मनाः।
अपश्यमानो वैदेहीं मेने शून्यमिदं जगत्।
शोकेन परमायत्तो न शान्तिं मनसागमत्॥', 'tadāvasāne yajñasya rāmaḥ paramadurmanāḥ
apaśyamāno vaidehīṃ mene śūnyam idaṃ jagat
śokena paramāyatto na śāntiṃ manasāgamat', null, 7089001),
('ramayana-7-89-2', 2, 'Uttara Kanda, Sarga 89, Verse 2', 'विसृज्य पार्थिवान्सर्वानृक्षवानरराक्षसान्।
जनौघं ब्रह्ममुख्यानां वित्तपूर्णं व्यसर्जयत्॥', 'visṛjya pārthivān sarvān ṛkṣavānararākṣasān
janaughaṃ brahmamukhyānāṃ vittapūrṇaṃ vyasarjayat', null, 7089002),
('ramayana-7-89-3', 3, 'Uttara Kanda, Sarga 89, Verse 3', 'ततो विसृज्य तान्सर्वान्रामो राजीवलोचनः।
हृदि कृत्वा तदा सीतामयोध्यां प्रविवेश सः॥', 'tato visṛjya tān sarvān rāmo rājīvalocanaḥ
hṛdi kṛtvā tadā sītām ayodhyāṃ praviveśa saḥ', null, 7089003),
('ramayana-7-89-4', 4, 'Uttara Kanda, Sarga 89, Verse 4', 'न सीतायाः परां भार्यां वव्रे स रघुनन्दनः।
यज्ञे यज्ञे च पत्न्यर्थं जानकी काञ्चनी भवत्॥', 'na sītāyāḥ parāṃ bhāryāṃ vavre sa raghunandanaḥ
yajñe yajñe ca patnyarthaṃ jānakī kāñcanī bhavat', null, 7089004),
('ramayana-7-89-5', 5, 'Uttara Kanda, Sarga 89, Verse 5', 'दशवर्षसहस्राणि वाजिमेधमुपाकरोत्।
वाजपेयान्दशगुणांस्तथा बहुसुवर्णकान्॥', 'daśavarṣasahasrāṇi vājimedham upākarot
vājapeyān daśaguṇāṃs tathā bahusuvarṇakān', null, 7089005),
('ramayana-7-89-6', 6, 'Uttara Kanda, Sarga 89, Verse 6', 'अग्निष्टोमातिरात्राभ्यां गोसवैश्च महाधनैः।
ईजे क्रतुभिरन्यैश्च स श्रीमानाप्तदक्षिणैः॥', 'agniṣṭomātirātrābhyāṃ gosavaiś ca mahādhanaiḥ
īje kratubhir anyaiś ca sa śrīmān āptadakṣiṇaiḥ', null, 7089006),
('ramayana-7-89-7', 7, 'Uttara Kanda, Sarga 89, Verse 7', 'एवं स कालः सुमहान्राज्यस्थस्य महात्मनः।
धर्मे प्रयतमानस्य व्यतीयाद्राघवस्य तु॥', 'evaṃ sa kālaḥ sumahān rājyasthasya mahātmanaḥ
dharme prayatamānasya vyatīyād rāghavasya tu', null, 7089007),
('ramayana-7-89-8', 8, 'Uttara Kanda, Sarga 89, Verse 8', 'ऋक्षवानररक्षांसि स्थिता रामस्य शासने।
अनुरज्यन्ति राजानो अहन्यहनि राघवम्॥', 'ṛkṣavānararakṣāṃsi sthitā rāmasya śāsane
anurajyanti rājāno ahany ahani rāghavam', null, 7089008),
('ramayana-7-89-9', 9, 'Uttara Kanda, Sarga 89, Verse 9', 'काले वर्षति पर्जन्यः सुभिक्षं विमला दिशः।
हृष्टपुष्टजनाकीर्णं पुरं जनपदस्तथा॥', 'kāle varṣati parjanyaḥ subhikṣaṃ vimalā diśaḥ
hṛṣṭapuṣṭajanākīrṇaṃ puraṃ janapadas tathā', null, 7089009),
('ramayana-7-89-10', 10, 'Uttara Kanda, Sarga 89, Verse 10', 'नाकाले म्रियते कश्चिन्न व्याधिः प्राणिनां तदा।
नाधर्मश्चाभवत्कश्चिद्रामे राज्यं प्रशासति॥', 'nākāle mriyate kaś cin na vyādhiḥ prāṇināṃ tadā
nādharmaś cābhavat kaś cid rāme rājyaṃ praśāsati', null, 7089010),
('ramayana-7-89-11', 11, 'Uttara Kanda, Sarga 89, Verse 11', 'अथ दीर्घस्य कालस्य राममाता यशस्विनी।
पुत्रपौत्रैः परिवृता कालधर्ममुपागमत्॥', 'atha dīrghasya kālasya rāmamātā yaśasvinī
putrapautraiḥ parivṛtā kāladharmam upāgamat', null, 7089011),
('ramayana-7-89-12', 12, 'Uttara Kanda, Sarga 89, Verse 12', 'अन्वियाय सुमित्रापि कैकेयी च यशस्विनी।
धर्मं कृत्वा बहुविधं त्रिदिवे पर्यवस्थिता॥', 'anviyāya sumitrāpi kaikeyī ca yaśasvinī
dharmaṃ kṛtvā bahuvidhaṃ tridive paryavasthitā', null, 7089012),
('ramayana-7-89-13', 13, 'Uttara Kanda, Sarga 89, Verse 13', 'सर्वाः प्रतिष्ठिताः स्वर्गे राज्ञा दशरथेन च।
समागता महाभागाः सह धर्मं च लेभिरे॥', 'sarvāḥ pratiṣṭhitāḥ svarge rājñā daśarathena ca
samāgatā mahābhāgāḥ saha dharmaṃ ca lebhire', null, 7089013),
('ramayana-7-89-14', 14, 'Uttara Kanda, Sarga 89, Verse 14', 'तासां रामो महादानं काले काले प्रयच्छति।
मातॄणामविशेषेण ब्राह्मणेषु तपस्विषु॥', 'tāsāṃ rāmo mahādānaṃ kāle kāle prayacchati
mātṝṇām aviśeṣeṇa brāhmaṇeṣu tapasviṣu', null, 7089014),
('ramayana-7-89-15', 15, 'Uttara Kanda, Sarga 89, Verse 15', 'पित्र्याणि बहुरत्नानि यज्ञान्परमदुस्तरान्।
चकार रामो धर्मात्मा पितॄन्देवान्विवर्धयन्॥', 'pitryāṇi bahuratnāni yajñān paramadustarān
cakāra rāmo dharmātmā pitṝn devān vivardhayan', null, 7089015)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 90 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-90-1', 1, 'Uttara Kanda, Sarga 90, Verse 1', 'कस्य चित्त्वथ कालस्य युधाजित्केकयो नृपः।
स्वगुरुं प्रेषयामास राघवाय महात्मने॥', 'kasya cit tv atha kālasya yudhājit kekayo nṛpaḥ
svaguruṃ preṣayām āsa rāghavāya mahātmane', null, 7090001),
('ramayana-7-90-2', 2, 'Uttara Kanda, Sarga 90, Verse 2', 'गार्ग्यमङ्गिरसः पुत्रं ब्रह्मर्षिममितप्रभम्।
दश चाश्वसहस्राणि प्रीतिदानमनुत्तमम्॥', 'gārgyam aṅgirasaḥ putraṃ brahmarṣim amitaprabham
daśa cāśvasahasrāṇi prītidānam anuttamam', null, 7090002),
('ramayana-7-90-3', 3, 'Uttara Kanda, Sarga 90, Verse 3', 'कम्बलानि च रत्नानि चित्रवस्त्रमथोत्तमम्।
रामाय प्रददौ राजा बहून्याभरणानि च॥', 'kambalāni ca ratnāni citravastram athottamam
rāmāya pradadau rājā bahūny ābharaṇāni ca', null, 7090003),
('ramayana-7-90-4', 4, 'Uttara Kanda, Sarga 90, Verse 4', 'श्रुत्वा तु राघवो गार्ग्यं महर्षिं समुपागतम्।
मातुलस्याश्वपतिनः प्रियं दूतमुपागतम्॥', 'śrutvā tu rāghavo gārgyaṃ maharṣiṃ samupāgatam
mātulasyāśvapatinaḥ priyaṃ dūtam upāgatam', null, 7090004),
('ramayana-7-90-5', 5, 'Uttara Kanda, Sarga 90, Verse 5', 'प्रत्युद्गम्य च काकुत्स्थः क्रोशमात्रं सहानुगः।
गार्ग्यं संपूजयामास धनं तत्प्रतिगृह्य च॥', 'pratyudgamya ca kākutsthaḥ krośamātraṃ sahānugaḥ
gārgyaṃ saṃpūjayām āsa dhanaṃ tat pratigṛhya ca', null, 7090005),
('ramayana-7-90-6', 6, 'Uttara Kanda, Sarga 90, Verse 6', 'पृष्ट्वा च प्रीतिदं सर्वं कुशलं मातुलस्य च।
उपविष्टं महाभागं रामः प्रष्टुं प्रचक्रमे॥', 'pṛṣṭvā ca prītidaṃ sarvaṃ kuśalaṃ mātulasya ca
upaviṣṭaṃ mahābhāgaṃ rāmaḥ praṣṭuṃ pracakrame', null, 7090006),
('ramayana-7-90-7', 7, 'Uttara Kanda, Sarga 90, Verse 7', 'किमाह मतुलो वाक्यं यदर्थं भगवानिह।
प्राप्तो वाक्यविदां श्रेष्ठ साक्षादिव बृहस्पतिः॥', 'kim āha matulo vākyaṃ yadarthaṃ bhagavān iha
prāpto vākyavidāṃ śreṣṭha sākṣād iva bṛhaspatiḥ', null, 7090007),
('ramayana-7-90-8', 8, 'Uttara Kanda, Sarga 90, Verse 8', 'रामस्य भाषितं श्रुत्वा ब्रह्मर्षिः कार्यविस्तरम्।
वक्तुमद्भुतसंकाशं राघवायोपचक्रमे॥', 'rāmasya bhāṣitaṃ śrutvā brahmarṣiḥ kāryavistaram
vaktum adbhutasaṃkāśaṃ rāghavāyopacakrame', null, 7090008),
('ramayana-7-90-9', 9, 'Uttara Kanda, Sarga 90, Verse 9', 'मातुलस्ते महाबाहो वाक्यमाह नरर्षभ।
युधाजित्प्रीतिसंयुक्तं श्रूयतां यदि रोचते॥', 'mātulas te mahābāho vākyam āha nararṣabha
yudhājit prītisaṃyuktaṃ śrūyatāṃ yadi rocate', null, 7090009),
('ramayana-7-90-10', 10, 'Uttara Kanda, Sarga 90, Verse 10', 'अयं गन्धर्वविषयः फलमूलोपशोभितः।
सिन्धोरुभयतः पार्श्वे देशः परमशोभनः॥', 'ayaṃ gandharvaviṣayaḥ phalamūlopaśobhitaḥ
sindhor ubhayataḥ pārśve deśaḥ paramaśobhanaḥ', null, 7090010),
('ramayana-7-90-11', 11, 'Uttara Kanda, Sarga 90, Verse 11', 'तं च रक्षन्ति गन्धर्वाः सायुधा युद्धकोविदाः।
शैलूषस्य सुता वीरास्तिस्रः कोट्यो महाबलाः॥', 'taṃ ca rakṣanti gandharvāḥ sāyudhā yuddhakovidāḥ
śailūṣasya sutā vīrās tisraḥ koṭyo mahābalāḥ', null, 7090011),
('ramayana-7-90-12', 12, 'Uttara Kanda, Sarga 90, Verse 12', 'तान्विनिर्जित्य काकुत्स्थ गन्धर्वविषयं शुभम्।
निवेशय महाबाहो द्वे पुरे सुसमाहितः॥', 'tān vinirjitya kākutstha gandharvaviṣayaṃ śubham
niveśaya mahābāho dve pure susamāhitaḥ', null, 7090012),
('ramayana-7-90-13', 13, 'Uttara Kanda, Sarga 90, Verse 13', 'अन्यस्य न गतिस्तत्र देशश्चायं सुशोभनः।
रोचतां ते महाबाहो नाहं त्वामनृतं वदे॥', 'anyasya na gatis tatra deśaś cāyaṃ suśobhanaḥ
rocatāṃ te mahābāho nāhaṃ tvām anṛtaṃ vade', null, 7090013),
('ramayana-7-90-14', 14, 'Uttara Kanda, Sarga 90, Verse 14', 'तच्छ्रुत्वा राघवः प्रीतो महर्षेर्मातुलस्य च।
उवाच बाढमित्येवं भरतं चान्ववैक्षत॥', 'tac chrutvā rāghavaḥ prīto maharṣer mātulasya ca
uvāca bāḍham ity evaṃ bharataṃ cānvavaikṣata', null, 7090014),
('ramayana-7-90-15', 15, 'Uttara Kanda, Sarga 90, Verse 15', 'सोऽब्रवीद्राघवः प्रीतः प्राञ्जलिप्रग्रहो द्विजम्।
इमौ कुमारौ तं देशं ब्रह्मर्षे विजयिष्यतः॥', 'so ''bravīd rāghavaḥ prītaḥ prāñjalipragraho dvijam
imau kumārau taṃ deśaṃ brahmarṣe vijayiṣyataḥ', null, 7090015),
('ramayana-7-90-16', 16, 'Uttara Kanda, Sarga 90, Verse 16', 'भरतस्यात्मजौ वीरौ तक्षः पुष्कल एव च।
मातुलेन सुगुप्तौ तौ धर्मेण च समाहितौ॥', 'bharatasyātmajau vīrau takṣaḥ puṣkala eva ca
mātulena suguptau tau dharmeṇa ca samāhitau', null, 7090016),
('ramayana-7-90-17', 17, 'Uttara Kanda, Sarga 90, Verse 17', 'भरतं चाग्रतः कृत्वा कुमारौ सबलानुगौ।
निहत्य गन्धर्वसुतान्द्वे पुरे विभजिष्यतः॥', 'bharataṃ cāgrataḥ kṛtvā kumārau sabalānugau
nihatya gandharvasutān dve pure vibhajiṣyataḥ', null, 7090017),
('ramayana-7-90-18', 18, 'Uttara Kanda, Sarga 90, Verse 18', 'निवेश्य ते पुरवरे आत्माजौ संनिवेश्य च।
आगमिष्यति मे भूयः सकाशमतिधार्मिकः॥', 'niveśya te puravare ātmājau saṃniveśya ca
āgamiṣyati me bhūyaḥ sakāśam atidhārmikaḥ', null, 7090018),
('ramayana-7-90-19', 19, 'Uttara Kanda, Sarga 90, Verse 19', 'ब्रह्मर्षिमेवमुक्त्वा तु भरतं सबलानुगम्।
आज्ञापयामास तदा कुमारौ चाभ्यषेचयत्॥', 'brahmarṣim evam uktvā tu bharataṃ sabalānugam
ājñāpayām āsa tadā kumārau cābhyaṣecayat', null, 7090019),
('ramayana-7-90-20', 20, 'Uttara Kanda, Sarga 90, Verse 20', 'नक्षत्रेण च सौम्येन पुरस्कृत्याङ्गिरः सुतम्।
भरतः सह सैन्येन कुमाराभ्यां च निर्ययौ॥', 'nakṣatreṇa ca saumyena puraskṛtyāṅgiraḥ sutam
bharataḥ saha sainyena kumārābhyāṃ ca niryayau', null, 7090020),
('ramayana-7-90-21', 21, 'Uttara Kanda, Sarga 90, Verse 21', 'सा सेना शक्रयुक्तेव नरगान्निर्ययावथ।
राघवानुगता दूरं दुराधर्षा सुरासुरैः॥', 'sā senā śakrayukteva naragān niryayāv atha
rāghavānugatā dūraṃ durādharṣā surāsuraiḥ', null, 7090021),
('ramayana-7-90-22', 22, 'Uttara Kanda, Sarga 90, Verse 22', 'मांसाशीनि च सत्त्वानि रक्षांसि सुमहान्ति च।
अनुजग्मुश्च भरतं रुधिरस्य पिपासया॥', 'māṃsāśīni ca sattvāni rakṣāṃsi sumahānti ca
anujagmuś ca bharataṃ rudhirasya pipāsayā', null, 7090022),
('ramayana-7-90-23', 23, 'Uttara Kanda, Sarga 90, Verse 23', 'भूतग्रामाश्च बहवो मांसभक्षाः सुदारुणाः।
गन्धर्वपुत्रमांसानि भोक्तुकामाः सहस्रशः॥', 'bhūtagrāmāś ca bahavo māṃsabhakṣāḥ sudāruṇāḥ
gandharvaputramāṃsāni bhoktukāmāḥ sahasraśaḥ', null, 7090023),
('ramayana-7-90-24', 24, 'Uttara Kanda, Sarga 90, Verse 24', 'सिंहव्याघ्रसृगालानां खेचराणां च पक्षिणाम्।
बहूनि वै सहस्राणि सेनाया ययुरग्रतः॥', 'siṃhavyāghrasṛgālānāṃ khecarāṇāṃ ca pakṣiṇām
bahūni vai sahasrāṇi senāyā yayur agrataḥ', null, 7090024),
('ramayana-7-90-25', 25, 'Uttara Kanda, Sarga 90, Verse 25', 'अध्यर्धमासमुषिता पथि सेना निरामया।
हृष्टपुष्टजनाकीर्णा केकयं समुपागमत्॥', 'adhyardhamāsam uṣitā pathi senā nirāmayā
hṛṣṭapuṣṭajanākīrṇā kekayaṃ samupāgamat', null, 7090025)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 91 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-91-1', 1, 'Uttara Kanda, Sarga 91, Verse 1', 'श्रुत्वा सेनापतिं प्राप्तं भरतं केकयाधिपः।
युधाजिद्गार्ग्यसहितं परां प्रीतिमुपागमत्॥', 'śrutvā senāpatiṃ prāptaṃ bharataṃ kekayādhipaḥ
yudhājid gārgyasahitaṃ parāṃ prītim upāgamat', null, 7091001),
('ramayana-7-91-2', 2, 'Uttara Kanda, Sarga 91, Verse 2', 'स निर्ययौ जनौघेन महता केकयाधिपः।
त्वरमाणोऽभिचक्राम गन्धर्वान्देवरूपिणः॥', 'sa niryayau janaughena mahatā kekayādhipaḥ
tvaramāṇo ''bhicakrāma gandharvān devarūpiṇaḥ', null, 7091002),
('ramayana-7-91-3', 3, 'Uttara Kanda, Sarga 91, Verse 3', 'भरतश्च युधाजिच्च समेतौ लघुविक्रमौ।
गन्धर्वनगरं प्राप्तौ सबलौ सपदानुगौ॥', 'bharataś ca yudhājic ca sametau laghuvikramau
gandharvanagaraṃ prāptau sabalau sapadānugau', null, 7091003),
('ramayana-7-91-4', 4, 'Uttara Kanda, Sarga 91, Verse 4', 'श्रुत्वा तु भरतं प्राप्तं गन्धर्वास्ते समागताः।
योद्धुकामा महावीर्या विनदन्तः समन्ततः॥', 'śrutvā tu bharataṃ prāptaṃ gandharvās te samāgatāḥ
yoddhukāmā mahāvīryā vinadantaḥ samantataḥ', null, 7091004),
('ramayana-7-91-5', 5, 'Uttara Kanda, Sarga 91, Verse 5', 'ततः समभवद्युद्धं तुमुलं लोमहर्षणम्।
सप्तरात्रं महाभीमं न चान्यतरयोर्जयः॥', 'tataḥ samabhavad yuddhaṃ tumulaṃ lomaharṣaṇam
saptarātraṃ mahābhīmaṃ na cānyatarayor jayaḥ', null, 7091005),
('ramayana-7-91-6', 6, 'Uttara Kanda, Sarga 91, Verse 6', 'ततो रामानुजः क्रुद्धः कालस्यास्त्रं सुदारुणम्।
संवर्तं नाम भरतो गन्धर्वेष्वभ्ययोजयत्॥', 'tato rāmānujaḥ kruddhaḥ kālasyāstraṃ sudāruṇam
saṃvartaṃ nāma bharato gandharveṣv abhyayojayat', null, 7091006),
('ramayana-7-91-7', 7, 'Uttara Kanda, Sarga 91, Verse 7', 'ते बद्धाः कालपाशेन संवर्तेन विदारिताः।
क्षणेनाभिहतास्तिस्रस्तत्र कोट्यो महात्मना॥', 'te baddhāḥ kālapāśena saṃvartena vidāritāḥ
kṣaṇenābhihatās tisras tatra koṭyo mahātmanā', null, 7091007),
('ramayana-7-91-8', 8, 'Uttara Kanda, Sarga 91, Verse 8', 'तं घातं घोरसंकाशं न स्मरन्ति दिवौकसः।
निमेषान्तरमात्रेण तादृशानां महात्मनाम्॥', 'taṃ ghātaṃ ghorasaṃkāśaṃ na smaranti divaukasaḥ
nimeṣāntaramātreṇa tādṛśānāṃ mahātmanām', null, 7091008),
('ramayana-7-91-9', 9, 'Uttara Kanda, Sarga 91, Verse 9', 'हतेषु तेषु वीरेषु भरतः कैकयीसुतः।
निवेशयामास तदा समृद्धे द्वे पुरोत्तमे।
तक्षं तक्षशिलायां तु पुष्करं पुष्करावतौ॥', 'hateṣu teṣu vīreṣu bharataḥ kaikayīsutaḥ
niveśayām āsa tadā samṛddhe dve purottame
takṣaṃ takṣaśilāyāṃ tu puṣkaraṃ puṣkarāvatau', null, 7091009),
('ramayana-7-91-10', 10, 'Uttara Kanda, Sarga 91, Verse 10', 'गन्धर्वदेशो रुचिरो गान्धारविषयश्च सः।
वर्षैः पञ्चभिराकीर्णो विषयैर्नागरैस्तथा॥', 'gandharvadeśo ruciro gāndhāraviṣayaś ca saḥ
varṣaiḥ pañcabhir ākīrṇo viṣayair nāgarais tathā', null, 7091010),
('ramayana-7-91-11', 11, 'Uttara Kanda, Sarga 91, Verse 11', 'धनरत्नौघसंपूर्णो काननैरुपशोभिते।
अन्योन्यसंघर्षकृते स्पर्धया गुणविस्तरे॥', 'dhanaratnaughasaṃpūrṇo kānanair upaśobhite
anyonyasaṃgharṣakṛte spardhayā guṇavistare', null, 7091011),
('ramayana-7-91-12', 12, 'Uttara Kanda, Sarga 91, Verse 12', 'उभे सुरुचिरप्रख्ये व्यवहारैरकल्मषैः।
उद्यानयानौघवृते सुविभक्तान्तरापणे॥', 'ubhe suruciraprakhye vyavahārair akalmaṣaiḥ
udyānayānaughavṛte suvibhaktāntarāpaṇe', null, 7091012),
('ramayana-7-91-13', 13, 'Uttara Kanda, Sarga 91, Verse 13', 'उभे पुरवरे रम्ये विस्तरैरुपशोभिते।
गृहमुख्यैः सुरुचिरैर्विमानैः समवर्णिभिः॥', 'ubhe puravare ramye vistarair upaśobhite
gṛhamukhyaiḥ surucirair vimānaiḥ samavarṇibhiḥ', null, 7091013),
('ramayana-7-91-14', 14, 'Uttara Kanda, Sarga 91, Verse 14', 'शोभिते शोभनीयैश्च देवायतनविस्तरैः।
निवेश्य पञ्चभिर्वर्षैर्भरतो राघवानुजः।
पुनरायान्महाबाहुरयोध्यां कैकयीसुतः॥', 'śobhite śobhanīyaiś ca devāyatanavistaraiḥ
niveśya pañcabhir varṣair bharato rāghavānujaḥ
punar āyān mahābāhur ayodhyāṃ kaikayīsutaḥ', null, 7091014),
('ramayana-7-91-15', 15, 'Uttara Kanda, Sarga 91, Verse 15', 'सोऽभिवाद्य महात्मानं साक्षाद्धर्ममिवापरम्।
राघवं भरतः श्रीमान्ब्रह्माणमिव वासवः॥', 'so ''bhivādya mahātmānaṃ sākṣād dharmam ivāparam
rāghavaṃ bharataḥ śrīmān brahmāṇam iva vāsavaḥ', null, 7091015),
('ramayana-7-91-16', 16, 'Uttara Kanda, Sarga 91, Verse 16', 'शशंस च यथावृत्तं गन्धर्ववधमुत्तमम्।
निवेशनं च देशस्य श्रुत्वा प्रीतोऽस्य राघवः॥', 'śaśaṃsa ca yathāvṛttaṃ gandharvavadham uttamam
niveśanaṃ ca deśasya śrutvā prīto ''sya rāghavaḥ', null, 7091016)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 92 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-92-1', 1, 'Uttara Kanda, Sarga 92, Verse 1', 'तच्छ्रुत्वा हर्षमापेदे राघवो भ्रातृभिः सह।
वाक्यं चाद्भुतसंकाशं भ्रातॄन्प्रोवाच राघवः॥', 'tac chrutvā harṣam āpede rāghavo bhrātṛbhiḥ saha
vākyaṃ cādbhutasaṃkāśaṃ bhrātṝn provāca rāghavaḥ', null, 7092001),
('ramayana-7-92-2', 2, 'Uttara Kanda, Sarga 92, Verse 2', 'इमौ कुमारौ सौमित्रे तव धर्मविशारदौ।
अङ्गदश्चन्द्रकेतुश्च राज्यार्हौ दृढधन्विनौ॥', 'imau kumārau saumitre tava dharmaviśāradau
aṅgadaś candraketuś ca rājyārhau dṛḍhadhanvinau', null, 7092002),
('ramayana-7-92-3', 3, 'Uttara Kanda, Sarga 92, Verse 3', 'इमौ राज्येऽभिषेक्ष्यामि देशः साधु विधीयताम्।
रमणीयो ह्यसंबाधो रमेतां यत्र धन्विनौ॥', 'imau rājye ''bhiṣekṣyāmi deśaḥ sādhu vidhīyatām
ramaṇīyo hy asaṃbādho rametāṃ yatra dhanvinau', null, 7092003),
('ramayana-7-92-4', 4, 'Uttara Kanda, Sarga 92, Verse 4', 'न राज्ञां यत्र पीदा स्यान्नाश्रमाणां विनाशनम्।
स देशो दृश्यतां सौम्य नापराध्यामहे यथा॥', 'na rājñāṃ yatra pīdā syān nāśramāṇāṃ vināśanam
sa deśo dṛśyatāṃ saumya nāparādhyāmahe yathā', null, 7092004),
('ramayana-7-92-5', 5, 'Uttara Kanda, Sarga 92, Verse 5', 'तथोक्तवति रामे तु भरतः प्रत्युवाच ह।
अयं कारापथो देशः सुरमण्यो निरामयः॥', 'tathoktavati rāme tu bharataḥ pratyuvāca ha
ayaṃ kārāpatho deśaḥ suramaṇyo nirāmayaḥ', null, 7092005),
('ramayana-7-92-6', 6, 'Uttara Kanda, Sarga 92, Verse 6', 'निवेश्यतां तत्र पुरमङ्गदस्य महात्मनः।
चन्द्रकेतोश्च रुचिरं चन्द्रकान्तं निरामयम्॥', 'niveśyatāṃ tatra puram aṅgadasya mahātmanaḥ
candraketoś ca ruciraṃ candrakāntaṃ nirāmayam', null, 7092006),
('ramayana-7-92-7', 7, 'Uttara Kanda, Sarga 92, Verse 7', 'तद्वाक्यं भरतेनोक्तं प्रतिजग्राह राघवः।
तं च कृता वशे देशमङ्गदस्य न्यवेशयत्॥', 'tad vākyaṃ bharatenoktaṃ pratijagrāha rāghavaḥ
taṃ ca kṛtā vaśe deśam aṅgadasya nyaveśayat', null, 7092007),
('ramayana-7-92-8', 8, 'Uttara Kanda, Sarga 92, Verse 8', 'अङ्गदीया पुरी रम्या अङ्गदस्य निवेशिता।
रमणीया सुगुप्ता च रामेणाक्लिष्टकर्मणा॥', 'aṅgadīyā purī ramyā aṅgadasya niveśitā
ramaṇīyā suguptā ca rāmeṇākliṣṭakarmaṇā', null, 7092008),
('ramayana-7-92-9', 9, 'Uttara Kanda, Sarga 92, Verse 9', 'चन्द्रकेतुस्तु मल्लस्य मल्लभूम्यां निवेशिता।
चन्द्रकान्तेति विख्याता दिव्या स्वर्गपुरी यथा॥', 'candraketus tu mallasya mallabhūmyāṃ niveśitā
candrakānteti vikhyātā divyā svargapurī yathā', null, 7092009),
('ramayana-7-92-10', 10, 'Uttara Kanda, Sarga 92, Verse 10', 'ततो रामः परां प्रीतिं भरतो लक्ष्मणस्तथा।
ययुर्युधि दुराधर्षा अभिषेकं च चक्रिरे॥', 'tato rāmaḥ parāṃ prītiṃ bharato lakṣmaṇas tathā
yayur yudhi durādharṣā abhiṣekaṃ ca cakrire', null, 7092010),
('ramayana-7-92-11', 11, 'Uttara Kanda, Sarga 92, Verse 11', 'अभिषिच्य कुमारौ द्वौ प्रस्थाप्य सबलानुगौ।
अङ्गदं पश्चिमा भूमिं चन्द्रकेतुमुदङ्मुखम्॥', 'abhiṣicya kumārau dvau prasthāpya sabalānugau
aṅgadaṃ paścimā bhūmiṃ candraketum udaṅmukham', null, 7092011),
('ramayana-7-92-12', 12, 'Uttara Kanda, Sarga 92, Verse 12', 'अङ्गदं चापि सौमित्रिर्लक्ष्मणोऽनुजगाम ह।
चन्द्रकेतोस्तु भरतः पार्ष्णिग्राहो बभूव ह॥', 'aṅgadaṃ cāpi saumitrir lakṣmaṇo ''nujagāma ha
candraketos tu bharataḥ pārṣṇigrāho babhūva ha', null, 7092012),
('ramayana-7-92-13', 13, 'Uttara Kanda, Sarga 92, Verse 13', 'लक्ष्मणस्त्वङ्गदीयायां संवत्सरमथोषितः।
पुत्रे स्थिते दुराधर्षे अयोध्यां पुनरागमत्॥', 'lakṣmaṇas tv aṅgadīyāyāṃ saṃvatsaram athoṣitaḥ
putre sthite durādharṣe ayodhyāṃ punar āgamat', null, 7092013),
('ramayana-7-92-14', 14, 'Uttara Kanda, Sarga 92, Verse 14', 'भरतोऽपि तथैवोष्य संवत्सरमथाधिकम्।
अयोध्यां पुनरगम्य रामपादावुपागमत्॥', 'bharato ''pi tathaivoṣya saṃvatsaram athādhikam
ayodhyāṃ punar agamya rāmapādāv upāgamat', null, 7092014),
('ramayana-7-92-15', 15, 'Uttara Kanda, Sarga 92, Verse 15', 'उभौ सौमित्रिभरतौ रामपादावनुव्रतौ।
कालं गतमपि स्नेहान्न जज्ञातेऽतिधार्मिकौ॥', 'ubhau saumitribharatau rāmapādāv anuvratau
kālaṃ gatam api snehān na jajñāte ''tidhārmikau', null, 7092015),
('ramayana-7-92-16', 16, 'Uttara Kanda, Sarga 92, Verse 16', 'एवं वर्षसहस्राणि दशतेषां ययुस्तदा।
धर्मे प्रयतमानानां पौरकार्येषु नित्यदा॥', 'evaṃ varṣasahasrāṇi daśateṣāṃ yayus tadā
dharme prayatamānānāṃ paurakāryeṣu nityadā', null, 7092016),
('ramayana-7-92-17', 17, 'Uttara Kanda, Sarga 92, Verse 17', 'विहृत्य लाकं परिपूर्णमानसाः श्रिया वृता धर्मपथे परे स्थिताः।
त्रयः समिद्धा इव दीप्ततेजसा हुताग्नयः साधु महाध्वरे त्रयः॥', 'vihṛtya lākaṃ paripūrṇamānasāḥ śriyā vṛtā dharmapathe pare sthitāḥ
trayaḥ samiddhā iva dīptatejasā hutāgnayaḥ sādhu mahādhvare trayaḥ', null, 7092017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 93 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-93-1', 1, 'Uttara Kanda, Sarga 93, Verse 1', 'कस्य चित्त्वथ कालस्य रामे धर्मपथे स्थिते।
कालस्तापसरूपेण राजद्वारमुपागमत्॥', 'kasya cit tv atha kālasya rāme dharmapathe sthite
kālas tāpasarūpeṇa rājadvāram upāgamat', null, 7093001),
('ramayana-7-93-2', 2, 'Uttara Kanda, Sarga 93, Verse 2', 'सोऽब्रवील्लक्ष्मणं वाक्यं धृतिमन्तं यशस्विनम्।
मां निवेदय रामाय संप्राप्तं कार्यगौरवात्॥', 'so ''bravīl lakṣmaṇaṃ vākyaṃ dhṛtimantaṃ yaśasvinam
māṃ nivedaya rāmāya saṃprāptaṃ kāryagauravāt', null, 7093002),
('ramayana-7-93-3', 3, 'Uttara Kanda, Sarga 93, Verse 3', 'दूतो ह्यतिबलस्याहं महर्षेरमितौजसः।
रामं दिदृक्षुरायातः कार्येण हि महाबल॥', 'dūto hy atibalasyāhaṃ maharṣer amitaujasaḥ
rāmaṃ didṛkṣur āyātaḥ kāryeṇa hi mahābala', null, 7093003),
('ramayana-7-93-4', 4, 'Uttara Kanda, Sarga 93, Verse 4', 'तस्य तद्वचनं श्रुत्वा सौमित्रिस्त्वरयान्वितः।
न्यवेदयत रामाय तापसस्य विवक्षितम्॥', 'tasya tad vacanaṃ śrutvā saumitris tvarayānvitaḥ
nyavedayata rāmāya tāpasasya vivakṣitam', null, 7093004),
('ramayana-7-93-5', 5, 'Uttara Kanda, Sarga 93, Verse 5', 'जयस्व राजन्धर्मेण उभौ लोकौ महाद्युते।
दूतस्त्वां द्रष्टुमायातस्तपस्वी भास्करप्रभः॥', 'jayasva rājan dharmeṇa ubhau lokau mahādyute
dūtas tvāṃ draṣṭum āyātas tapasvī bhāskaraprabhaḥ', null, 7093005),
('ramayana-7-93-6', 6, 'Uttara Kanda, Sarga 93, Verse 6', 'तद्वाक्यं लक्ष्मणेनोक्तं श्रुत्वा राम उवाच ह।
प्रवेश्यतां मुनिस्तात महौजास्तस्य वाक्यधृक्॥', 'tad vākyaṃ lakṣmaṇenoktaṃ śrutvā rāma uvāca ha
praveśyatāṃ munis tāta mahaujās tasya vākyadhṛk', null, 7093006),
('ramayana-7-93-7', 7, 'Uttara Kanda, Sarga 93, Verse 7', 'सौमित्रिस्तु तथेत्युक्त्वा प्रावेशयत तं मुनिम्।
ज्वलन्तमिव तेजोभिः प्रदहन्तमिवांशुभिः॥', 'saumitris tu tathety uktvā prāveśayata taṃ munim
jvalantam iva tejobhiḥ pradahantam ivāṃśubhiḥ', null, 7093007),
('ramayana-7-93-8', 8, 'Uttara Kanda, Sarga 93, Verse 8', 'सोऽभिगम्य रघुश्रेष्ठं दीप्यमानं स्वतेजसा।
ऋषिर्मधुरया वाचा वर्धस्वेत्याह राघवम्॥', 'so ''bhigamya raghuśreṣṭhaṃ dīpyamānaṃ svatejasā
ṛṣir madhurayā vācā vardhasvety āha rāghavam', null, 7093008),
('ramayana-7-93-9', 9, 'Uttara Kanda, Sarga 93, Verse 9', 'तस्मै रामो महातेजाः पूजामर्घ्य पुरोगमाम्।
ददौ कुशलमव्यग्रं प्रष्टुं चैवोपचक्रमे॥', 'tasmai rāmo mahātejāḥ pūjām arghya purogamām
dadau kuśalam avyagraṃ praṣṭuṃ caivopacakrame', null, 7093009),
('ramayana-7-93-10', 10, 'Uttara Kanda, Sarga 93, Verse 10', 'पृष्ठश्च कुशलं तेन रामेण वदतां वरः।
आसने काञ्चने दिव्ये निषसाद महायशाः॥', 'pṛṣṭhaś ca kuśalaṃ tena rāmeṇa vadatāṃ varaḥ
āsane kāñcane divye niṣasāda mahāyaśāḥ', null, 7093010),
('ramayana-7-93-11', 11, 'Uttara Kanda, Sarga 93, Verse 11', 'तमुवाच ततो रामः स्वागतं ते महामुने।
प्रापयस्व च वाक्यानि यतो दूतस्त्वमागतः॥', 'tam uvāca tato rāmaḥ svāgataṃ te mahāmune
prāpayasva ca vākyāni yato dūtas tvam āgataḥ', null, 7093011),
('ramayana-7-93-12', 12, 'Uttara Kanda, Sarga 93, Verse 12', 'चोदितो राजसिंहेन मुनिर्वाक्यमुदीरयत्।
द्वन्द्वमेतत्प्रवक्तव्यं न च चक्षुर्हतं वचः॥', 'codito rājasiṃhena munir vākyam udīrayat
dvandvam etat pravaktavyaṃ na ca cakṣur hataṃ vacaḥ', null, 7093012),
('ramayana-7-93-13', 13, 'Uttara Kanda, Sarga 93, Verse 13', 'यः शृणोति निरीक्षेद्वा स वध्यस्तव राघव।
भवेद्वै मुनिमुख्यस्य वचनं यद्यवेक्षसे॥', 'yaḥ śṛṇoti nirīkṣed vā sa vadhyas tava rāghava
bhaved vai munimukhyasya vacanaṃ yady avekṣase', null, 7093013),
('ramayana-7-93-14', 14, 'Uttara Kanda, Sarga 93, Verse 14', 'तथेति च प्रतिज्ञाय रामो लक्ष्मणमब्रवीत्।
द्वारि तिष्ठ महाबाहो प्रतिहारं विसर्जय॥', 'tatheti ca pratijñāya rāmo lakṣmaṇam abravīt
dvāri tiṣṭha mahābāho pratihāraṃ visarjaya', null, 7093014),
('ramayana-7-93-15', 15, 'Uttara Kanda, Sarga 93, Verse 15', 'स मे वध्यः खलु भवेत्कथां द्वन्द्वसमीरिताम्।
ऋषेर्मम च सौमित्रे पश्येद्वा शृणुया च यः॥', 'sa me vadhyaḥ khalu bhavet kathāṃ dvandvasamīritām
ṛṣer mama ca saumitre paśyed vā śṛṇuyā ca yaḥ', null, 7093015),
('ramayana-7-93-16', 16, 'Uttara Kanda, Sarga 93, Verse 16', 'ततो निक्षिप्य काकुत्स्थो लक्ष्मणं द्वारसंग्रहे।
तमुवाच मुनिं वाक्यं कथयस्वेति राघवः॥', 'tato nikṣipya kākutstho lakṣmaṇaṃ dvārasaṃgrahe
tam uvāca muniṃ vākyaṃ kathayasveti rāghavaḥ', null, 7093016),
('ramayana-7-93-17', 17, 'Uttara Kanda, Sarga 93, Verse 17', 'यत्ते मनीषितं वाक्यं येन वासि समाहितः।
कथयस्व विशङ्कस्त्वं ममापि हृदि वर्तते॥', 'yat te manīṣitaṃ vākyaṃ yena vāsi samāhitaḥ
kathayasva viśaṅkas tvaṃ mamāpi hṛdi vartate', null, 7093017)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 94 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-94-1', 1, 'Uttara Kanda, Sarga 94, Verse 1', 'शृणु राम महाबाहो यदर्थमहमाहतः।
पितामहेन देवेन प्रेषितोऽस्मि महाबल॥', 'śṛṇu rāma mahābāho yadartham aham āhataḥ
pitāmahena devena preṣito ''smi mahābala', null, 7094001),
('ramayana-7-94-2', 2, 'Uttara Kanda, Sarga 94, Verse 2', 'तवाहं पूर्वके भावे पुत्रः परपुरंजय।
मायासंभावितो वीर कालः सर्वसमाहरः॥', 'tavāhaṃ pūrvake bhāve putraḥ parapuraṃjaya
māyāsaṃbhāvito vīra kālaḥ sarvasamāharaḥ', null, 7094002),
('ramayana-7-94-3', 3, 'Uttara Kanda, Sarga 94, Verse 3', 'पितामहश्च भगवानाह लोकपतिः प्रभुः।
समयस्ते महाबाहो स्वर्लोकान्परिरक्षितुम्॥', 'pitāmahaś ca bhagavān āha lokapatiḥ prabhuḥ
samayas te mahābāho svarlokān parirakṣitum', null, 7094003),
('ramayana-7-94-4', 4, 'Uttara Kanda, Sarga 94, Verse 4', 'संक्षिप्य च पुरा लोकान्मायया स्वयमेव हि।
महार्णवे शयानोऽप्सु मां त्वं पूर्वमजीजनः॥', 'saṃkṣipya ca purā lokān māyayā svayam eva hi
mahārṇave śayāno ''psu māṃ tvaṃ pūrvam ajījanaḥ', null, 7094004),
('ramayana-7-94-5', 5, 'Uttara Kanda, Sarga 94, Verse 5', 'भोगवन्तं ततो नागमनन्तमुदके शयम्।
मायया जनयित्वा त्वं द्वौ च सत्त्वौ महाबलौ॥', 'bhogavantaṃ tato nāgam anantam udake śayam
māyayā janayitvā tvaṃ dvau ca sattvau mahābalau', null, 7094005),
('ramayana-7-94-6', 6, 'Uttara Kanda, Sarga 94, Verse 6', 'मधुं च कैटभं चैव ययोरस्थिचयैर्वृता।
इयं पर्वतसंबाधा मेदिनी चाभवन्मही॥', 'madhuṃ ca kaiṭabhaṃ caiva yayor asthicayair vṛtā
iyaṃ parvatasaṃbādhā medinī cābhavan mahī', null, 7094006),
('ramayana-7-94-7', 7, 'Uttara Kanda, Sarga 94, Verse 7', 'पद्मे दिव्यार्कसंकाशे नाभ्यामुत्पाद्य मामपि।
प्राजापत्यं त्वया कर्म सर्वं मयि निवेशितम्॥', 'padme divyārkasaṃkāśe nābhyām utpādya mām api
prājāpatyaṃ tvayā karma sarvaṃ mayi niveśitam', null, 7094007),
('ramayana-7-94-8', 8, 'Uttara Kanda, Sarga 94, Verse 8', 'सोऽहं संन्यस्तभारो हि त्वामुपासे जगत्पतिम्।
रक्षां विधत्स्व भूतेषु मम तेजः करो भवान्॥', 'so ''haṃ saṃnyastabhāro hi tvām upāse jagatpatim
rakṣāṃ vidhatsva bhūteṣu mama tejaḥ karo bhavān', null, 7094008),
('ramayana-7-94-9', 9, 'Uttara Kanda, Sarga 94, Verse 9', 'ततस्त्वमपि दुर्धर्षस्तस्माद्भावात्सनातनात्।
रक्षार्थं सर्वभूतानां विष्णुत्वमुपजग्मिवान्॥', 'tatas tvam api durdharṣas tasmād bhāvāt sanātanāt
rakṣārthaṃ sarvabhūtānāṃ viṣṇutvam upajagmivān', null, 7094009),
('ramayana-7-94-10', 10, 'Uttara Kanda, Sarga 94, Verse 10', 'अदित्यां वीर्यवान्पुत्रो भ्रातॄणां हर्षवर्धनः।
समुत्पन्नेषु कृत्येषु लोकसाह्याय कल्पसे॥', 'adityāṃ vīryavān putro bhrātṝṇāṃ harṣavardhanaḥ
samutpanneṣu kṛtyeṣu lokasāhyāya kalpase', null, 7094010),
('ramayana-7-94-11', 11, 'Uttara Kanda, Sarga 94, Verse 11', 'स त्वं वित्रास्यमानासु प्रजासु जगतां वर।
रावणस्य वधाकाङ्क्षी मानुषेषु मनोऽदधाः॥', 'sa tvaṃ vitrāsyamānāsu prajāsu jagatāṃ vara
rāvaṇasya vadhākāṅkṣī mānuṣeṣu mano ''dadhāḥ', null, 7094011),
('ramayana-7-94-12', 12, 'Uttara Kanda, Sarga 94, Verse 12', 'दशवर्षसहस्राणि दशवर्षशतानि च।
कृत्वा वासस्य नियतिं स्वयमेवात्मनः पुरा॥', 'daśavarṣasahasrāṇi daśavarṣaśatāni ca
kṛtvā vāsasya niyatiṃ svayam evātmanaḥ purā', null, 7094012),
('ramayana-7-94-13', 13, 'Uttara Kanda, Sarga 94, Verse 13', 'स त्वं मनोमयः पुत्रः पूर्णायुर्मानुषेष्विह।
कालो नरवरश्रेष्ठ समीपमुपवर्तितुम्॥', 'sa tvaṃ manomayaḥ putraḥ pūrṇāyur mānuṣeṣv iha
kālo naravaraśreṣṭha samīpam upavartitum', null, 7094013),
('ramayana-7-94-14', 14, 'Uttara Kanda, Sarga 94, Verse 14', 'यदि भूयो महाराज प्रजा इच्छस्युपासितुम्।
वस वा वीर भद्रं ते एवमाह पितामहः॥', 'yadi bhūyo mahārāja prajā icchasy upāsitum
vasa vā vīra bhadraṃ te evam āha pitāmahaḥ', null, 7094014),
('ramayana-7-94-15', 15, 'Uttara Kanda, Sarga 94, Verse 15', 'अथ वा विजिगीषा ते सुरलोकाय राघव।
सनाथा विष्णुना देवा भवन्तु विगतज्वराः॥', 'atha vā vijigīṣā te suralokāya rāghava
sanāthā viṣṇunā devā bhavantu vigatajvarāḥ', null, 7094015),
('ramayana-7-94-16', 16, 'Uttara Kanda, Sarga 94, Verse 16', 'श्रुत्वा पितामहेनोक्तं वाक्यं कालसमीरितम्।
राघवः प्रहसन्वाक्यं सर्वसंहारमब्रवीत्॥', 'śrutvā pitāmahenoktaṃ vākyaṃ kālasamīritam
rāghavaḥ prahasan vākyaṃ sarvasaṃhāram abravīt', null, 7094016),
('ramayana-7-94-17', 17, 'Uttara Kanda, Sarga 94, Verse 17', 'श्रुतं मे देवदेवस्य वाक्यं परममद्भुतम्।
प्रीतिर्हि महती जाता तवागमनसंभवा॥', 'śrutaṃ me devadevasya vākyaṃ paramam adbhutam
prītir hi mahatī jātā tavāgamanasaṃbhavā', null, 7094017),
('ramayana-7-94-18', 18, 'Uttara Kanda, Sarga 94, Verse 18', 'भद्रं तेऽस्तु गमिष्यामि यत एवाहमागतः।
हृद्गतो ह्यसि संप्राप्तो न मेऽस्त्यत्र विचारणा॥', 'bhadraṃ te ''stu gamiṣyāmi yata evāham āgataḥ
hṛd gato hy asi saṃprāpto na me ''sty atra vicāraṇā', null, 7094018),
('ramayana-7-94-19', 19, 'Uttara Kanda, Sarga 94, Verse 19', 'मया हि सर्वकृत्येषु देवानां वशवर्तिनाम्।
स्थातव्यं सर्वसंहारे यथा ह्याह पितामहः॥', 'mayā hi sarvakṛtyeṣu devānāṃ vaśavartinām
sthātavyaṃ sarvasaṃhāre yathā hy āha pitāmahaḥ', null, 7094019)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 95 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-95-1', 1, 'Uttara Kanda, Sarga 95, Verse 1', 'तथा तयोः कथयतोर्दुर्वासा भगवानृषिः।
रामस्य दर्शनाकाङ्क्षी राजद्वारमुपागमत्॥', 'tathā tayoḥ kathayator durvāsā bhagavān ṛṣiḥ
rāmasya darśanākāṅkṣī rājadvāram upāgamat', null, 7095001),
('ramayana-7-95-2', 2, 'Uttara Kanda, Sarga 95, Verse 2', 'सोऽभिगम्य च सौमित्रिमुवाच ऋषिसत्तमः।
रामं दर्शय मे शीघ्रं पुरा मेऽर्थोऽतिवर्तते॥', 'so ''bhigamya ca saumitrim uvāca ṛṣisattamaḥ
rāmaṃ darśaya me śīghraṃ purā me ''rtho ''tivartate', null, 7095002),
('ramayana-7-95-3', 3, 'Uttara Kanda, Sarga 95, Verse 3', 'मुनेस्तु भाषितं श्रुत्वा लक्ष्मणः परवीरहा।
अभिवाद्य महात्मानं वाक्यमेतदुवाच ह॥', 'munes tu bhāṣitaṃ śrutvā lakṣmaṇaḥ paravīrahā
abhivādya mahātmānaṃ vākyam etad uvāca ha', null, 7095003),
('ramayana-7-95-4', 4, 'Uttara Kanda, Sarga 95, Verse 4', 'किं कार्यं ब्रूहि भगवन्को वार्थः किं करोम्यहम्।
व्यग्रो हि राघवो ब्रह्मन्मुहूर्तं वा प्रतीक्षताम्॥', 'kiṃ kāryaṃ brūhi bhagavan ko vārthaḥ kiṃ karomy aham
vyagro hi rāghavo brahman muhūrtaṃ vā pratīkṣatām', null, 7095004),
('ramayana-7-95-5', 5, 'Uttara Kanda, Sarga 95, Verse 5', 'तच्छ्रुत्वा ऋषिशार्दूलः क्रोधेन कलुषीकृतः।
उवाच लक्ष्मणं वाक्यं निर्दहन्निव चक्षुषा॥', 'tac chrutvā ṛṣiśārdūlaḥ krodhena kaluṣīkṛtaḥ
uvāca lakṣmaṇaṃ vākyaṃ nirdahann iva cakṣuṣā', null, 7095005),
('ramayana-7-95-6', 6, 'Uttara Kanda, Sarga 95, Verse 6', 'अस्मिन्क्षणे मां सौमित्रे रामाय प्रतिवेदय।
विषयं त्वां पुरं चैव शपिष्ये राघवं तथा॥', 'asmin kṣaṇe māṃ saumitre rāmāya prativedaya
viṣayaṃ tvāṃ puraṃ caiva śapiṣye rāghavaṃ tathā', null, 7095006),
('ramayana-7-95-7', 7, 'Uttara Kanda, Sarga 95, Verse 7', 'भरतं चैव सौमित्रे युष्माकं या च संततिः।
न हि शक्ष्याम्यहं भूयो मन्युं धारयितुं हृदि॥', 'bharataṃ caiva saumitre yuṣmākaṃ yā ca saṃtatiḥ
na hi śakṣyāmy ahaṃ bhūyo manyuṃ dhārayituṃ hṛdi', null, 7095007),
('ramayana-7-95-8', 8, 'Uttara Kanda, Sarga 95, Verse 8', 'तच्छ्रुत्वा घोरसंकाशं वाक्यं तस्य महात्मनः।
चिन्तयामास मनसा तस्य वाक्यस्य निश्चयम्॥', 'tac chrutvā ghorasaṃkāśaṃ vākyaṃ tasya mahātmanaḥ
cintayām āsa manasā tasya vākyasya niścayam', null, 7095008),
('ramayana-7-95-9', 9, 'Uttara Kanda, Sarga 95, Verse 9', 'एकस्य मरणं मेऽस्तु मा भूत्सर्वविनाशनम्।
इति बुद्ध्या विनिश्चित्य राघवाय न्यवेदयत्॥', 'ekasya maraṇaṃ me ''stu mā bhūt sarvavināśanam
iti buddhyā viniścitya rāghavāya nyavedayat', null, 7095009),
('ramayana-7-95-10', 10, 'Uttara Kanda, Sarga 95, Verse 10', 'लक्ष्मणस्य वचः श्रुत्वा रामः कालं विसृज्य च।
निष्पत्य त्वरितं राजा अत्रेः पुत्रं ददर्श ह॥', 'lakṣmaṇasya vacaḥ śrutvā rāmaḥ kālaṃ visṛjya ca
niṣpatya tvaritaṃ rājā atreḥ putraṃ dadarśa ha', null, 7095010),
('ramayana-7-95-11', 11, 'Uttara Kanda, Sarga 95, Verse 11', 'सोऽभिवाद्य महात्मानं ज्वलन्तमिव तेजसा।
किं कार्यमिति काकुत्स्थः कृताञ्जलिरभाषत॥', 'so ''bhivādya mahātmānaṃ jvalantam iva tejasā
kiṃ kāryam iti kākutsthaḥ kṛtāñjalir abhāṣata', null, 7095011),
('ramayana-7-95-12', 12, 'Uttara Kanda, Sarga 95, Verse 12', 'तद्वाक्यं राघवेण्णोक्तं श्रुत्वा मुनिवरः प्रभुः।
प्रत्याह रामं दुर्वासाः श्रूयतां धर्मवत्सल॥', 'tad vākyaṃ rāghaveṇṇoktaṃ śrutvā munivaraḥ prabhuḥ
pratyāha rāmaṃ durvāsāḥ śrūyatāṃ dharmavatsala', null, 7095012),
('ramayana-7-95-13', 13, 'Uttara Kanda, Sarga 95, Verse 13', 'अद्य वर्षसहस्रस्य समाप्तिर्मम राघव।
सोऽहं भोजनमिच्छामि यथासिद्धं तवानघ॥', 'adya varṣasahasrasya samāptir mama rāghava
so ''haṃ bhojanam icchāmi yathāsiddhaṃ tavānagha', null, 7095013),
('ramayana-7-95-14', 14, 'Uttara Kanda, Sarga 95, Verse 14', 'तच्छ्रुत्वा वचनं रामो हर्षेण महतान्वितः।
भोजनं मुनिमुख्याय यथासिद्धमुपाहरत्॥', 'tac chrutvā vacanaṃ rāmo harṣeṇa mahatānvitaḥ
bhojanaṃ munimukhyāya yathāsiddham upāharat', null, 7095014),
('ramayana-7-95-15', 15, 'Uttara Kanda, Sarga 95, Verse 15', 'स तु भुक्त्वा मुनिश्रेष्ठस्तदन्नममृतोपमम्।
साधु रामेति संभाष्य स्वमाश्रममुपागमत्॥', 'sa tu bhuktvā muniśreṣṭhas tad annam amṛtopamam
sādhu rāmeti saṃbhāṣya svam āśramam upāgamat', null, 7095015),
('ramayana-7-95-16', 16, 'Uttara Kanda, Sarga 95, Verse 16', 'तस्मिन्गते महातेजा राघवः प्रीतमानसः।
संस्मृत्य कालवाक्यानि ततो दुःखमुपेयिवान्॥', 'tasmin gate mahātejā rāghavaḥ prītamānasaḥ
saṃsmṛtya kālavākyāni tato duḥkham upeyivān', null, 7095016),
('ramayana-7-95-17', 17, 'Uttara Kanda, Sarga 95, Verse 17', 'दुःखेन च सुसंतप्तः स्मृत्वा तद्घोरदर्शनम्।
अवान्मुखो दीनमना व्याहर्तुं न शशाक ह॥', 'duḥkhena ca susaṃtaptaḥ smṛtvā tad ghoradarśanam
avānmukho dīnamanā vyāhartuṃ na śaśāka ha', null, 7095017),
('ramayana-7-95-18', 18, 'Uttara Kanda, Sarga 95, Verse 18', 'ततो बुद्ध्या विनिश्चित्य कालवाक्यानि राघवः।
नैतदस्तीति चोक्त्वा स तूष्णीमासीन्महायशाः॥', 'tato buddhyā viniścitya kālavākyāni rāghavaḥ
naitad astīti coktvā sa tūṣṇīm āsīn mahāyaśāḥ', null, 7095018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 96 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-96-1', 1, 'Uttara Kanda, Sarga 96, Verse 1', 'अवाङ्मुखमथो दीनं दृष्ट्वा सोममिवाप्लुतम्।
राघवं लक्ष्मणो वाक्यं हृष्टो मधुरमब्रवीत्॥', 'avāṅmukham atho dīnaṃ dṛṣṭvā somam ivāplutam
rāghavaṃ lakṣmaṇo vākyaṃ hṛṣṭo madhuram abravīt', null, 7096001),
('ramayana-7-96-2', 2, 'Uttara Kanda, Sarga 96, Verse 2', 'न संतापं महाबाहो मदर्थं कर्तुमर्हसि।
पूर्वनिर्माणबद्धा हि कालस्य गतिरीदृशी॥', 'na saṃtāpaṃ mahābāho madarthaṃ kartum arhasi
pūrvanirmāṇabaddhā hi kālasya gatir īdṛśī', null, 7096002),
('ramayana-7-96-3', 3, 'Uttara Kanda, Sarga 96, Verse 3', 'जहि मां सौम्य विस्रब्दः प्रतिज्ञां परिपालय।
हीनप्रतिज्ञाः काकुत्स्थ प्रयान्ति नरकं नराः॥', 'jahi māṃ saumya visrabdaḥ pratijñāṃ paripālaya
hīnapratijñāḥ kākutstha prayānti narakaṃ narāḥ', null, 7096003),
('ramayana-7-96-4', 4, 'Uttara Kanda, Sarga 96, Verse 4', 'यदि प्रीतिर्महाराज यद्यनुग्राह्यता मयि।
जहि मां निर्विशङ्कस्त्वं धर्मं वर्धय राघव॥', 'yadi prītir mahārāja yady anugrāhyatā mayi
jahi māṃ nirviśaṅkas tvaṃ dharmaṃ vardhaya rāghava', null, 7096004),
('ramayana-7-96-5', 5, 'Uttara Kanda, Sarga 96, Verse 5', 'लक्ष्मणेन तथोक्तस्तु रामः प्रचलितेन्द्रियः।
मन्त्रिणः समुपानीय तथैव च पुरोधसं॥', 'lakṣmaṇena tathoktas tu rāmaḥ pracalitendriyaḥ
mantriṇaḥ samupānīya tathaiva ca purodhasaṃ', null, 7096005),
('ramayana-7-96-6', 6, 'Uttara Kanda, Sarga 96, Verse 6', 'अब्रवीच्च यथावृत्तं तेषां मध्ये नराधिपः।
दुर्वासोऽभिगमं चैव प्रतिज्ञां तापसस्य च॥', 'abravīc ca yathāvṛttaṃ teṣāṃ madhye narādhipaḥ
durvāso''bhigamaṃ caiva pratijñāṃ tāpasasya ca', null, 7096006),
('ramayana-7-96-7', 7, 'Uttara Kanda, Sarga 96, Verse 7', 'तच्छ्रुत्वा मन्त्रिणः सर्वे सोपाध्यायाः समासत।
वसिष्ठस्तु महातेजा वाक्यमेतदुवाच ह॥', 'tac chrutvā mantriṇaḥ sarve sopādhyāyāḥ samāsata
vasiṣṭhas tu mahātejā vākyam etad uvāca ha', null, 7096007),
('ramayana-7-96-8', 8, 'Uttara Kanda, Sarga 96, Verse 8', 'दृष्टमेतन्महाबाहो क्षयं ते लोमहर्षणम्।
लक्ष्मणेन वियोगश्च तव राम महायशः॥', 'dṛṣṭam etan mahābāho kṣayaṃ te lomaharṣaṇam
lakṣmaṇena viyogaś ca tava rāma mahāyaśaḥ', null, 7096008),
('ramayana-7-96-9', 9, 'Uttara Kanda, Sarga 96, Verse 9', 'त्यजैनं बलवान्कालो मा प्रतिज्ञां वृथा कृथाः।
विनष्टायां प्रतिज्ञायां धर्मो हि विलयं व्रजेत्॥', 'tyajainaṃ balavān kālo mā pratijñāṃ vṛthā kṛthāḥ
vinaṣṭāyāṃ pratijñāyāṃ dharmo hi vilayaṃ vrajet', null, 7096009),
('ramayana-7-96-10', 10, 'Uttara Kanda, Sarga 96, Verse 10', 'ततो धर्मे विनष्टे तु त्रैलोक्ये सचराचरम्।
सदेवर्षिगणं सर्वं विनश्येत न संशयः॥', 'tato dharme vinaṣṭe tu trailokye sacarācaram
sadevarṣigaṇaṃ sarvaṃ vinaśyeta na saṃśayaḥ', null, 7096010),
('ramayana-7-96-11', 11, 'Uttara Kanda, Sarga 96, Verse 11', 'स त्वं पुरुषशार्दूल त्रैलोक्यस्याभिपालनम्।
लक्ष्मणस्य वधेनाद्य जगत्स्वस्थं कुरुष्व ह॥', 'sa tvaṃ puruṣaśārdūla trailokyasyābhipālanam
lakṣmaṇasya vadhenādya jagat svasthaṃ kuruṣva ha', null, 7096011),
('ramayana-7-96-12', 12, 'Uttara Kanda, Sarga 96, Verse 12', 'तेषां तत्समवेतानां वाक्यं धर्मार्थसंहितम्।
श्रुत्वा परिषदो मध्ये रामो लक्ष्मणमब्रवीत्॥', 'teṣāṃ tat samavetānāṃ vākyaṃ dharmārthasaṃhitam
śrutvā pariṣado madhye rāmo lakṣmaṇam abravīt', null, 7096012),
('ramayana-7-96-13', 13, 'Uttara Kanda, Sarga 96, Verse 13', 'विसर्जये त्वां सौमित्रे मा भूद्धर्मविपर्ययः।
त्यागो वधो वा विहितः साधूनामुभयं समम्॥', 'visarjaye tvāṃ saumitre mā bhūd dharmaviparyayaḥ
tyāgo vadho vā vihitaḥ sādhūnām ubhayaṃ samam', null, 7096013),
('ramayana-7-96-14', 14, 'Uttara Kanda, Sarga 96, Verse 14', 'रामेण भाषिते वाक्ये बाष्पव्याकुलितेक्षणः।
लक्ष्मणस्त्वरितः प्रायात्स्वगृहं न विवेश ह॥', 'rāmeṇa bhāṣite vākye bāṣpavyākulitekṣaṇaḥ
lakṣmaṇas tvaritaḥ prāyāt svagṛhaṃ na viveśa ha', null, 7096014),
('ramayana-7-96-15', 15, 'Uttara Kanda, Sarga 96, Verse 15', 'स गत्वा सरयूतीरमुपस्पृश्य कृताञ्जलिः।
निगृह्य सर्वस्रोतांसि निःश्वासं न मुमोच ह॥', 'sa gatvā sarayūtīram upaspṛśya kṛtāñjaliḥ
nigṛhya sarvasrotāṃsi niḥśvāsaṃ na mumoca ha', null, 7096015),
('ramayana-7-96-16', 16, 'Uttara Kanda, Sarga 96, Verse 16', 'अनुच्छ्वसन्तं युक्तं तं सशक्राः साप्सरोगणाः।
देवाः सर्षिगणाः सर्वे पुष्पैरवकिरंस्तदा॥', 'anucchvasantaṃ yuktaṃ taṃ saśakrāḥ sāpsarogaṇāḥ
devāḥ sarṣigaṇāḥ sarve puṣpair avakiraṃs tadā', null, 7096016),
('ramayana-7-96-17', 17, 'Uttara Kanda, Sarga 96, Verse 17', 'अदृश्यं सर्वमनुजैः सशरीरं महाबलम्।
प्रगृह्य लक्ष्मणं शक्रो दिवं संप्रविवेश ह॥', 'adṛśyaṃ sarvam anujaiḥ saśarīraṃ mahābalam
pragṛhya lakṣmaṇaṃ śakro divaṃ saṃpraviveśa ha', null, 7096017),
('ramayana-7-96-18', 18, 'Uttara Kanda, Sarga 96, Verse 18', 'ततो विष्णोश्चतुर्भागमागतं सुरसत्तमाः।
हृष्टाः प्रमुदिताः सर्वेऽपूजयनृषिभिः सह॥', 'tato viṣṇoś caturbhāgam āgataṃ surasattamāḥ
hṛṣṭāḥ pramuditāḥ sarve ''pūjayan ṛṣibhiḥ saha', null, 7096018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 97 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-97-1', 1, 'Uttara Kanda, Sarga 97, Verse 1', 'विसृज्य लक्ष्मणं रामो दुःखशोकसमन्वितः।
पुरोधसं मन्त्रिणश्च नैगमांश्चेदमब्रवीत्॥', 'visṛjya lakṣmaṇaṃ rāmo duḥkhaśokasamanvitaḥ
purodhasaṃ mantriṇaś ca naigamāṃś cedam abravīt', null, 7097001),
('ramayana-7-97-2', 2, 'Uttara Kanda, Sarga 97, Verse 2', 'अद्य राज्येऽभिषेक्ष्यामि भरतं धर्मवत्सलम्।
अयोध्यायां पतिं वीरं ततो यास्याम्यहं वनम्॥', 'adya rājye ''bhiṣekṣyāmi bharataṃ dharmavatsalam
ayodhyāyāṃ patiṃ vīraṃ tato yāsyāmy ahaṃ vanam', null, 7097002),
('ramayana-7-97-3', 3, 'Uttara Kanda, Sarga 97, Verse 3', 'प्रवेशयत संभारान्मा भूत्कालात्ययो यथा।
अद्यैवाहं गमिष्यामि लक्ष्मणेन गतां गतिम्॥', 'praveśayata saṃbhārān mā bhūt kālātyayo yathā
adyaivāhaṃ gamiṣyāmi lakṣmaṇena gatāṃ gatim', null, 7097003),
('ramayana-7-97-4', 4, 'Uttara Kanda, Sarga 97, Verse 4', 'तच्छ्रुत्वा राघवेणोक्तं सर्वाः प्रकृतयो भृशम्।
मूर्धभिः प्रणता भूमौ गतसत्त्वा इवाभवन्॥', 'tac chrutvā rāghaveṇoktaṃ sarvāḥ prakṛtayo bhṛśam
mūrdhabhiḥ praṇatā bhūmau gatasattvā ivābhavan', null, 7097004),
('ramayana-7-97-5', 5, 'Uttara Kanda, Sarga 97, Verse 5', 'भरतश्च विसंज्ञोऽभूच्छ्रुत्वा रामस्य भाषितम्।
राज्यं विगर्हयामास राघवं चेदमब्रवीत्॥', 'bharataś ca visaṃjño ''bhūc chrutvā rāmasya bhāṣitam
rājyaṃ vigarhayām āsa rāghavaṃ cedam abravīt', null, 7097005),
('ramayana-7-97-6', 6, 'Uttara Kanda, Sarga 97, Verse 6', 'सत्येन हि शपे राजन्स्वर्गलोके न चैव हि।
न कामये यथा राज्यं त्वां विना रघुनन्दन॥', 'satyena hi śape rājan svargaloke na caiva hi
na kāmaye yathā rājyaṃ tvāṃ vinā raghunandana', null, 7097006),
('ramayana-7-97-7', 7, 'Uttara Kanda, Sarga 97, Verse 7', 'इमौ कुशीलवौ राजन्नभिषिञ्च नराधिप।
कोसलेषु कुशं वीरमुत्तरेषु तथा लवम्॥', 'imau kuśīlavau rājann abhiṣiñca narādhipa
kosaleṣu kuśaṃ vīram uttareṣu tathā lavam', null, 7097007),
('ramayana-7-97-8', 8, 'Uttara Kanda, Sarga 97, Verse 8', 'शत्रुघ्नस्य तु गच्छन्तु दूतास्त्वरितविक्रमाः।
इदं गमनमस्माकं स्वर्गायाख्यान्तु माचिरम्॥', 'śatrughnasya tu gacchantu dūtās tvaritavikramāḥ
idaṃ gamanam asmākaṃ svargāyākhyāntu māciram', null, 7097008),
('ramayana-7-97-9', 9, 'Uttara Kanda, Sarga 97, Verse 9', 'तच्छ्रुत्वा भरतेनोक्तं दृष्ट्वा चापि ह्यधो मुखान्।
पौरान्दुःखेन संतप्तान्वसिष्ठो वाक्यमब्रवीत्॥', 'tac chrutvā bharatenoktaṃ dṛṣṭvā cāpi hy adho mukhān
paurān duḥkhena saṃtaptān vasiṣṭho vākyam abravīt', null, 7097009),
('ramayana-7-97-10', 10, 'Uttara Kanda, Sarga 97, Verse 10', 'वत्स राम इमाः पश्य धरणीं प्रकृतीर्गताः।
ज्ञात्वैषामीप्सितं कार्यं मा चैषां विप्रियं कृथाः॥', 'vatsa rāma imāḥ paśya dharaṇīṃ prakṛtīr gatāḥ
jñātvaiṣām īpsitaṃ kāryaṃ mā caiṣāṃ vipriyaṃ kṛthāḥ', null, 7097010),
('ramayana-7-97-11', 11, 'Uttara Kanda, Sarga 97, Verse 11', 'वसिष्ठस्य तु वाक्येन उत्थाप्य प्रकृतीजनम्।
किं करोमीति काकुत्स्थः सर्वान्वचनमब्रवीत्॥', 'vasiṣṭhasya tu vākyena utthāpya prakṛtījanam
kiṃ karomīti kākutsthaḥ sarvān vacanam abravīt', null, 7097011),
('ramayana-7-97-12', 12, 'Uttara Kanda, Sarga 97, Verse 12', 'ततः सर्वाः प्रकृतयो रामं वचनमब्रुवन्।
गच्छन्तमनुगच्छामो यतो राम गमिष्यसि॥', 'tataḥ sarvāḥ prakṛtayo rāmaṃ vacanam abruvan
gacchantam anugacchāmo yato rāma gamiṣyasi', null, 7097012),
('ramayana-7-97-13', 13, 'Uttara Kanda, Sarga 97, Verse 13', 'एषा नः परमा प्रीतिरेष धर्मः परो मतः।
हृद्गता नः सदा तुष्टिस्तवानुगमने दृढा॥', 'eṣā naḥ paramā prītir eṣa dharmaḥ paro mataḥ
hṛdgatā naḥ sadā tuṣṭis tavānugamane dṛḍhā', null, 7097013),
('ramayana-7-97-14', 14, 'Uttara Kanda, Sarga 97, Verse 14', 'पौरेषु यदि ते प्रीतिर्यदि स्नेहो ह्यनुत्तमः।
सपुत्रदाराः काकुत्स्थ समं गच्छाम सत्पथम्॥', 'paureṣu yadi te prītir yadi sneho hy anuttamaḥ
saputradārāḥ kākutstha samaṃ gacchāma satpatham', null, 7097014),
('ramayana-7-97-15', 15, 'Uttara Kanda, Sarga 97, Verse 15', 'तपोवनं वा दुर्गं वा नदीमम्भोनिधिं तथा।
वयं ते यदि न त्याज्याः सर्वान्नो नय ईश्वर॥', 'tapovanaṃ vā durgaṃ vā nadīm ambhonidhiṃ tathā
vayaṃ te yadi na tyājyāḥ sarvān no naya īśvara', null, 7097015),
('ramayana-7-97-16', 16, 'Uttara Kanda, Sarga 97, Verse 16', 'स तेषां निश्चयं ज्ञात्वा कृतान्तं च निरीक्ष्यच।
पौराणां दृढभक्तिं च बाढमित्येव सोऽब्रवीत्॥', 'sa teṣāṃ niścayaṃ jñātvā kṛtāntaṃ ca nirīkṣyaca
paurāṇāṃ dṛḍhabhaktiṃ ca bāḍham ity eva so ''bravīt', null, 7097016),
('ramayana-7-97-17', 17, 'Uttara Kanda, Sarga 97, Verse 17', 'एवं विनिश्चयं कृत्वा तस्मिन्नहनि राघवः।
कोसलेषु कुशं वीरमुत्तरेषु तथा लवम्॥', 'evaṃ viniścayaṃ kṛtvā tasminn ahani rāghavaḥ
kosaleṣu kuśaṃ vīram uttareṣu tathā lavam', null, 7097017),
('ramayana-7-97-18', 18, 'Uttara Kanda, Sarga 97, Verse 18', 'अभिषिञ्चन्महात्मानावुभावेव कुशीलवौ।
रथानां तु सहस्राणि त्रीणि नागायुतानि च॥', 'abhiṣiñcan mahātmānāv ubhāv eva kuśīlavau
rathānāṃ tu sahasrāṇi trīṇi nāgāyutāni ca', null, 7097018),
('ramayana-7-97-19', 19, 'Uttara Kanda, Sarga 97, Verse 19', 'दश चाश्वसहस्राणि एकैकस्य धनं ददौ।
बहुरत्नौ बहुधनौ हृष्टपुष्टजनावृतौ॥', 'daśa cāśvasahasrāṇi ekaikasya dhanaṃ dadau
bahuratnau bahudhanau hṛṣṭapuṣṭajanāvṛtau', null, 7097019),
('ramayana-7-97-20', 20, 'Uttara Kanda, Sarga 97, Verse 20', 'अभिषिच्य तु तौ वीरौ प्रस्थाप्य स्वपुरे तथा।
दूतान्संप्रेषयामास शत्रुघ्नाय महात्मने॥', 'abhiṣicya tu tau vīrau prasthāpya svapure tathā
dūtān saṃpreṣayām āsa śatrughnāya mahātmane', null, 7097020)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 98 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-98-1', 1, 'Uttara Kanda, Sarga 98, Verse 1', 'ते दूता रामवाक्येन चोदिता लघुविक्रमाः।
प्रजग्मुर्मधुरां शीघ्रं चक्रुर्वासं न चाध्वनि॥', 'te dūtā rāmavākyena coditā laghuvikramāḥ
prajagmur madhurāṃ śīghraṃ cakrur vāsaṃ na cādhvani', null, 7098001),
('ramayana-7-98-2', 2, 'Uttara Kanda, Sarga 98, Verse 2', 'ततस्त्रिभिरहो रात्रैः संप्राप्य मधुरामथ।
शत्रुघ्नाय यथावृत्तमाचख्युः सर्वमेव तत्॥', 'tatas tribhir aho rātraiḥ saṃprāpya madhurām atha
śatrughnāya yathāvṛttam ācakhyuḥ sarvam eva tat', null, 7098002),
('ramayana-7-98-3', 3, 'Uttara Kanda, Sarga 98, Verse 3', 'लक्ष्मणस्य परित्यागं प्रतिज्ञां राघवस्य च।
पुत्रयोरभिषेकं च पौरानुगमनं तथा॥', 'lakṣmaṇasya parityāgaṃ pratijñāṃ rāghavasya ca
putrayor abhiṣekaṃ ca paurānugamanaṃ tathā', null, 7098003),
('ramayana-7-98-4', 4, 'Uttara Kanda, Sarga 98, Verse 4', 'कुशस्य नगरी रम्या विन्ध्यपर्वतरोधसि।
कुशावतीति नाम्ना सा कृता रामेण धीमता॥', 'kuśasya nagarī ramyā vindhyaparvatarodhasi
kuśāvatīti nāmnā sā kṛtā rāmeṇa dhīmatā', null, 7098004),
('ramayana-7-98-5', 5, 'Uttara Kanda, Sarga 98, Verse 5', 'श्राविता च पुरी रम्या श्रावतीति लवस्य च।
अयोध्यां विजनां चैव भरतं राघवानुगम्॥', 'śrāvitā ca purī ramyā śrāvatīti lavasya ca
ayodhyāṃ vijanāṃ caiva bharataṃ rāghavānugam', null, 7098005),
('ramayana-7-98-6', 6, 'Uttara Kanda, Sarga 98, Verse 6', 'एवं सर्वं निवेद्याशु शत्रुघ्नाय महात्मने।
विरेमुस्ते ततो दूतास्त्वर राजन्निति ब्रुवन्॥', 'evaṃ sarvaṃ nivedyāśu śatrughnāya mahātmane
viremus te tato dūtās tvara rājann iti bruvan', null, 7098006),
('ramayana-7-98-7', 7, 'Uttara Kanda, Sarga 98, Verse 7', 'श्रुत्वा तं घोरसंकाशं कुलक्षयमुपस्थितम्।
प्रकृतीस्तु समानीय काञ्चनं च पुरोहितम्॥', 'śrutvā taṃ ghorasaṃkāśaṃ kulakṣayam upasthitam
prakṛtīs tu samānīya kāñcanaṃ ca purohitam', null, 7098007),
('ramayana-7-98-8', 8, 'Uttara Kanda, Sarga 98, Verse 8', 'तेषां सर्वं यथावृत्तमाख्याय रघुनन्दनः।
आत्मनश्च विपर्यासं भविष्यं भ्रातृभिः सह॥', 'teṣāṃ sarvaṃ yathāvṛttam ākhyāya raghunandanaḥ
ātmanaś ca viparyāsaṃ bhaviṣyaṃ bhrātṛbhiḥ saha', null, 7098008),
('ramayana-7-98-9', 9, 'Uttara Kanda, Sarga 98, Verse 9', 'ततः पुत्रद्वयं वीरः सोऽभ्यषिञ्चन्नराधिपः।
सुबाहुर्मधुरां लेभे शत्रुघाती च वैदिशम्॥', 'tataḥ putradvayaṃ vīraḥ so ''bhyaṣiñcan narādhipaḥ
subāhur madhurāṃ lebhe śatrughātī ca vaidiśam', null, 7098009),
('ramayana-7-98-10', 10, 'Uttara Kanda, Sarga 98, Verse 10', 'द्विधाकृत्वा तु तां सेनां माधुरीं पुत्रयोर्द्वयोः।
धनधान्यसमायुक्तौ स्थापयामास पार्थिवौ॥', 'dvidhākṛtvā tu tāṃ senāṃ mādhurīṃ putrayor dvayoḥ
dhanadhānyasamāyuktau sthāpayām āsa pārthivau', null, 7098010),
('ramayana-7-98-11', 11, 'Uttara Kanda, Sarga 98, Verse 11', 'ततो विसृज्य राजानं वैदिशे शत्रुघातिनम्।
जगाम त्वरितोऽयोध्यां रथेनैकेन राघवः॥', 'tato visṛjya rājānaṃ vaidiśe śatrughātinam
jagāma tvarito ''yodhyāṃ rathenaikena rāghavaḥ', null, 7098011),
('ramayana-7-98-12', 12, 'Uttara Kanda, Sarga 98, Verse 12', 'स ददर्श महात्मानं ज्वलन्तमिव पावकम्।
क्षौमसूक्ष्माम्बरधरं मुनिभिः सार्धमक्षयैः॥', 'sa dadarśa mahātmānaṃ jvalantam iva pāvakam
kṣaumasūkṣmāmbaradharaṃ munibhiḥ sārdham akṣayaiḥ', null, 7098012),
('ramayana-7-98-13', 13, 'Uttara Kanda, Sarga 98, Verse 13', 'सोऽभिवाद्य ततो रामं प्राञ्जलिः प्रयतेन्द्रियः।
उवाच वाक्यं धर्मज्ञो धर्ममेवानुचिन्तयन्॥', 'so ''bhivādya tato rāmaṃ prāñjaliḥ prayatendriyaḥ
uvāca vākyaṃ dharmajño dharmam evānucintayan', null, 7098013),
('ramayana-7-98-14', 14, 'Uttara Kanda, Sarga 98, Verse 14', 'कृत्वाभिषेकं सुतयोर्युक्तं राघवयोर्धनैः।
तवानुगमने राजन्विद्धि मां कृतनिश्चयम्॥', 'kṛtvābhiṣekaṃ sutayor yuktaṃ rāghavayor dhanaiḥ
tavānugamane rājan viddhi māṃ kṛtaniścayam', null, 7098014),
('ramayana-7-98-15', 15, 'Uttara Kanda, Sarga 98, Verse 15', 'न चान्यदत्र वक्तव्यं दुस्तरं तव शासनम्।
त्यक्तुं नार्हसि मां वीर भक्तिमन्तं विशेषतः॥', 'na cānyad atra vaktavyaṃ dustaraṃ tava śāsanam
tyaktuṃ nārhasi māṃ vīra bhaktimantaṃ viśeṣataḥ', null, 7098015),
('ramayana-7-98-16', 16, 'Uttara Kanda, Sarga 98, Verse 16', 'तस्य तां बुद्धिमक्लीबां विज्ञाय रघुनन्दनः।
बाढमित्येव शत्रुघ्नं रामो वचनमब्रवीत्॥', 'tasya tāṃ buddhim aklībāṃ vijñāya raghunandanaḥ
bāḍham ity eva śatrughnaṃ rāmo vacanam abravīt', null, 7098016),
('ramayana-7-98-17', 17, 'Uttara Kanda, Sarga 98, Verse 17', 'तस्य वाक्यस्य वाक्यान्ते वानराः कामरूपिणः।
ऋक्षराक्षससंघाश्च समापेतुरनेकशः॥', 'tasya vākyasya vākyānte vānarāḥ kāmarūpiṇaḥ
ṛkṣarākṣasasaṃghāś ca samāpetur anekaśaḥ', null, 7098017),
('ramayana-7-98-18', 18, 'Uttara Kanda, Sarga 98, Verse 18', 'देवपुत्रा ऋषिसुता गन्धर्वाणां सुतास्तथा।
राम क्षयं विदित्वा ते सर्व एव समागताः॥', 'devaputrā ṛṣisutā gandharvāṇāṃ sutās tathā
rāma kṣayaṃ viditvā te sarva eva samāgatāḥ', null, 7098018),
('ramayana-7-98-19', 19, 'Uttara Kanda, Sarga 98, Verse 19', 'ते राममभिवाद्याहुः सर्व एव समागताः।
तवानुगमने राजन्संप्राप्ताः स्म महायशः॥', 'te rāmam abhivādyāhuḥ sarva eva samāgatāḥ
tavānugamane rājan saṃprāptāḥ sma mahāyaśaḥ', null, 7098019),
('ramayana-7-98-20', 20, 'Uttara Kanda, Sarga 98, Verse 20', 'यदि राम विनास्माभिर्गच्छेस्त्वं पुरुषर्षभ।
यमदण्डमिवोद्यम्य त्वया स्म विनिपातिताः॥', 'yadi rāma vināsmābhir gacches tvaṃ puruṣarṣabha
yamadaṇḍam ivodyamya tvayā sma vinipātitāḥ', null, 7098020),
('ramayana-7-98-21', 21, 'Uttara Kanda, Sarga 98, Verse 21', 'एवं तेषां वचः श्रुत्वा ऋष्कवानररक्षसाम्।
विभीषणमथोवाच मधुरं श्लक्ष्णया गिरा॥', 'evaṃ teṣāṃ vacaḥ śrutvā ṛṣkavānararakṣasām
vibhīṣaṇam athovāca madhuraṃ ślakṣṇayā girā', null, 7098021),
('ramayana-7-98-22', 22, 'Uttara Kanda, Sarga 98, Verse 22', 'यावत्प्रजा धरिष्यन्ति तावत्त्वं वै विभीषण।
राक्षसेन्द्र महावीर्य लङ्कास्थः स्वं धरिष्यसि॥', 'yāvat prajā dhariṣyanti tāvat tvaṃ vai vibhīṣaṇa
rākṣasendra mahāvīrya laṅkāsthaḥ svaṃ dhariṣyasi', null, 7098022),
('ramayana-7-98-23', 23, 'Uttara Kanda, Sarga 98, Verse 23', 'प्रजाः संरक्ष धर्मेण नोत्तरं वक्तुमर्हसि॥', 'prajāḥ saṃrakṣa dharmeṇa nottaraṃ vaktum arhasi', null, 7098023),
('ramayana-7-98-24', 24, 'Uttara Kanda, Sarga 98, Verse 24', 'तमेवमुक्त्वा काकुत्स्थो हनूमन्तमथाब्रवीत्।
जीविते कृतबुद्धिस्त्वं मा प्रतिज्ञां विलोपय॥', 'tam evam uktvā kākutstho hanūmantam athābravīt
jīvite kṛtabuddhis tvaṃ mā pratijñāṃ vilopaya', null, 7098024),
('ramayana-7-98-25', 25, 'Uttara Kanda, Sarga 98, Verse 25', 'मत्कथाः प्रचरिष्यन्ति यावल्लोके हरीश्वर।
तावत्त्वं धारयन्प्राणान्प्रतिज्ञामनुपालय॥', 'matkathāḥ pracariṣyanti yāval loke harīśvara
tāvat tvaṃ dhārayan prāṇān pratijñām anupālaya', null, 7098025),
('ramayana-7-98-26', 26, 'Uttara Kanda, Sarga 98, Verse 26', 'तथैवमुक्त्वा काकुत्स्थः सर्वांस्तानृक्षवानरान्।
मया सार्धं प्रयातेति तदा तान्राघवोऽब्रवीत्॥', 'tathaivam uktvā kākutsthaḥ sarvāṃs tān ṛkṣavānarān
mayā sārdhaṃ prayāteti tadā tān rāghavo ''bravīt', null, 7098026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 99 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-99-1', 1, 'Uttara Kanda, Sarga 99, Verse 1', 'प्रभातायां तु शर्वर्यां पृथुवक्षा महायशाः।
रामः कमलपत्राक्षः पुरोधसमथाब्रवीत्॥', 'prabhātāyāṃ tu śarvaryāṃ pṛthuvakṣā mahāyaśāḥ
rāmaḥ kamalapatrākṣaḥ purodhasam athābravīt', null, 7099001),
('ramayana-7-99-2', 2, 'Uttara Kanda, Sarga 99, Verse 2', 'अग्निहोत्रं व्रजत्वग्रे सर्पिर्ज्वलितपावकम्।
वाजपेयातपत्रं च शोभयानं महापथम्॥', 'agnihotraṃ vrajatv agre sarpir jvalitapāvakam
vājapeyātapatraṃ ca śobhayānaṃ mahāpatham', null, 7099002),
('ramayana-7-99-3', 3, 'Uttara Kanda, Sarga 99, Verse 3', 'ततो वसिष्ठस्तेजस्वी सर्वं निरवशेषतः।
चकार विधिवद्धर्म्यं महाप्रास्थानिकं विधिम्॥', 'tato vasiṣṭhas tejasvī sarvaṃ niravaśeṣataḥ
cakāra vidhivad dharmyaṃ mahāprāsthānikaṃ vidhim', null, 7099003),
('ramayana-7-99-4', 4, 'Uttara Kanda, Sarga 99, Verse 4', 'ततः क्षौमाम्बरधरो ब्रह्म चावर्तयन्परम्।
कुशान्गृहीत्वा पाणिभ्यां प्रसज्य प्रययावथ॥', 'tataḥ kṣaumāmbaradharo brahma cāvartayan param
kuśān gṛhītvā pāṇibhyāṃ prasajya prayayāv atha', null, 7099004),
('ramayana-7-99-5', 5, 'Uttara Kanda, Sarga 99, Verse 5', 'अव्याहरन्क्व चित्किं चिन्निश्चेष्टो निःसुखः पथि।
निर्जगाम गृहात्तस्माद्दीप्यमानो यथांशुमान्॥', 'avyāharan kva cit kiṃ cin niśceṣṭo niḥsukhaḥ pathi
nirjagāma gṛhāt tasmād dīpyamāno yathāṃśumān', null, 7099005),
('ramayana-7-99-6', 6, 'Uttara Kanda, Sarga 99, Verse 6', 'रामस्य पार्श्वे सव्ये तु पद्मा श्रीः सुसमाहिता।
दक्षिणे ह्रीर्विशालाक्षी व्यवसायस्तथाग्रतः॥', 'rāmasya pārśve savye tu padmā śrīḥ susamāhitā
dakṣiṇe hrīr viśālākṣī vyavasāyas tathāgrataḥ', null, 7099006),
('ramayana-7-99-7', 7, 'Uttara Kanda, Sarga 99, Verse 7', 'शरा नानाविधाश्चापि धनुरायतविग्रहम्।
अनुव्रजन्ति काकुत्स्थं सर्वे पुरुषविग्रहाः॥', 'śarā nānāvidhāś cāpi dhanur āyatavigraham
anuvrajanti kākutsthaṃ sarve puruṣavigrahāḥ', null, 7099007),
('ramayana-7-99-8', 8, 'Uttara Kanda, Sarga 99, Verse 8', 'वेदा ब्राह्मणरूपेण सावित्री सर्वरक्षिणी।
ओंकारोऽथ वषट्कारः सर्वे राममनुव्रताः॥', 'vedā brāhmaṇarūpeṇa sāvitrī sarvarakṣiṇī
oṃkāro ''tha vaṣaṭkāraḥ sarve rāmam anuvratāḥ', null, 7099008),
('ramayana-7-99-9', 9, 'Uttara Kanda, Sarga 99, Verse 9', 'ऋषयश्च महात्मानः सर्व एव महीसुराः।
अन्वगच्छन्त काकुत्स्थं स्वर्गद्वारमुपागतम्॥', 'ṛṣayaś ca mahātmānaḥ sarva eva mahīsurāḥ
anvagacchanta kākutsthaṃ svargadvāram upāgatam', null, 7099009),
('ramayana-7-99-10', 10, 'Uttara Kanda, Sarga 99, Verse 10', 'तं यान्तमनुयान्ति स्म अन्तःपुरचराः स्त्रियः।
सवृद्धबालदासीकाः सवर्षवरकिंकराः॥', 'taṃ yāntam anuyānti sma antaḥpuracarāḥ striyaḥ
savṛddhabāladāsīkāḥ savarṣavarakiṃkarāḥ', null, 7099010),
('ramayana-7-99-11', 11, 'Uttara Kanda, Sarga 99, Verse 11', 'सान्तःपुरश्च भरतः शत्रुघ्नसहितो ययौ।
रामव्रतमुपागम्य राघवं समनुव्रताः॥', 'sāntaḥpuraś ca bharataḥ śatrughnasahito yayau
rāmavratam upāgamya rāghavaṃ samanuvratāḥ', null, 7099011),
('ramayana-7-99-12', 12, 'Uttara Kanda, Sarga 99, Verse 12', 'ततो विप्रा महात्मानः साग्निहोत्राः समाहिताः।
सपुत्रदाराः काकुत्स्थमन्वगच्छन्महामतिम्॥', 'tato viprā mahātmānaḥ sāgnihotrāḥ samāhitāḥ
saputradārāḥ kākutstham anvagacchan mahāmatim', null, 7099012),
('ramayana-7-99-13', 13, 'Uttara Kanda, Sarga 99, Verse 13', 'मन्त्रिणो भृत्यवर्गाश्च सपुत्राः सहबान्धवाः।
सानुगा राघवं सर्वे अन्वगच्छन्प्रहृष्टवत्॥', 'mantriṇo bhṛtyavargāś ca saputrāḥ sahabāndhavāḥ
sānugā rāghavaṃ sarve anvagacchan prahṛṣṭavat', null, 7099013),
('ramayana-7-99-14', 14, 'Uttara Kanda, Sarga 99, Verse 14', 'ततः सर्वाः प्रकृतयो हृष्टपुष्टजनावृताः।
अनुजग्मुः प्रगच्छन्तं राघवं गुणरञ्जिताः॥', 'tataḥ sarvāḥ prakṛtayo hṛṣṭapuṣṭajanāvṛtāḥ
anujagmuḥ pragacchantaṃ rāghavaṃ guṇarañjitāḥ', null, 7099014),
('ramayana-7-99-15', 15, 'Uttara Kanda, Sarga 99, Verse 15', 'स्नातं प्रमुदितं सर्वं हृष्टपुष्पमनुत्तमम्।
दृप्तं किलिकिलाशब्दैः सर्वं राममनुव्रतम्॥', 'snātaṃ pramuditaṃ sarvaṃ hṛṣṭapuṣpam anuttamam
dṛptaṃ kilikilāśabdaiḥ sarvaṃ rāmam anuvratam', null, 7099015),
('ramayana-7-99-16', 16, 'Uttara Kanda, Sarga 99, Verse 16', 'न तत्र कश्चिद्दीनोऽभूद्व्रीडितो वापि दुःखितः।
हृष्टं प्रमुदितं सर्वं बभूव परमाद्भुतम्॥', 'na tatra kaś cid dīno ''bhūd vrīḍito vāpi duḥkhitaḥ
hṛṣṭaṃ pramuditaṃ sarvaṃ babhūva paramādbhutam', null, 7099016),
('ramayana-7-99-17', 17, 'Uttara Kanda, Sarga 99, Verse 17', 'द्रष्टुकामोऽथ निर्याणं राज्ञो जानपदो जनः।
संप्राप्तः सोऽपि दृष्ट्वैव सह सर्वैरनुव्रतः॥', 'draṣṭukāmo ''tha niryāṇaṃ rājño jānapado janaḥ
saṃprāptaḥ so ''pi dṛṣṭvaiva saha sarvair anuvrataḥ', null, 7099017),
('ramayana-7-99-18', 18, 'Uttara Kanda, Sarga 99, Verse 18', 'ऋक्षवानररक्षांसि जनाश्च पुरवासिनः।
अगछन्परया भक्त्या पृष्ठतः सुसमाहिताः॥', 'ṛkṣavānararakṣāṃsi janāś ca puravāsinaḥ
agachan parayā bhaktyā pṛṣṭhataḥ susamāhitāḥ', null, 7099018)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status)
select x.id, 'valmiki-ramayana', (select id from sections where scripture_id = 'valmiki-ramayana' and level = 2 and number = 100 and parent_id = (select id from sections where scripture_id = 'valmiki-ramayana' and level = 1 and number = 7 and parent_id is null)), x.n, x.reference, x.sanskrit, x.transliteration, x.speaker, x.sort_key, false, 'gretil-ramayana-ce', 'draft'
from (values
('ramayana-7-100-1', 1, 'Uttara Kanda, Sarga 100, Verse 1', 'अध्यर्धयोजनं गत्वा नदीं पश्चान्मुखाश्रिताम्।
सरयूं पुण्यसलिलां ददर्श रघुनन्दनः॥', 'adhyardhayojanaṃ gatvā nadīṃ paścān mukhāśritām
sarayūṃ puṇyasalilāṃ dadarśa raghunandanaḥ', null, 7100001),
('ramayana-7-100-2', 2, 'Uttara Kanda, Sarga 100, Verse 2', 'अथ तस्मिन्मुहूर्ते तु ब्रह्मा लोकपितामहः।
सर्वैः परिवृतो देवैरृषिभिश्च महात्मभिः॥', 'atha tasmin muhūrte tu brahmā lokapitāmahaḥ
sarvaiḥ parivṛto devair ṛṣibhiś ca mahātmabhiḥ', null, 7100002),
('ramayana-7-100-3', 3, 'Uttara Kanda, Sarga 100, Verse 3', 'आययौ यत्र काकुत्स्थः स्वर्गाय समुपस्थितः।
विमानशतकोटीभिर्दिव्याभिरभिसंवृतः॥', 'āyayau yatra kākutsthaḥ svargāya samupasthitaḥ
vimānaśatakoṭībhir divyābhir abhisaṃvṛtaḥ', null, 7100003),
('ramayana-7-100-4', 4, 'Uttara Kanda, Sarga 100, Verse 4', 'पपात पुष्पवृष्टिश्च वायुमुक्ता महौघवत्॥', 'papāta puṣpavṛṣṭiś ca vāyumuktā mahaughavat', null, 7100004),
('ramayana-7-100-5', 5, 'Uttara Kanda, Sarga 100, Verse 5', 'तस्मिंस्तूर्यशताकीर्णे गन्धर्वाप्सरसंकुले।
सरयूसलिलं रामः पद्भ्यां समुपचक्रमे॥', 'tasmiṃs tūryaśatākīrṇe gandharvāpsarasaṃkule
sarayūsalilaṃ rāmaḥ padbhyāṃ samupacakrame', null, 7100005),
('ramayana-7-100-6', 6, 'Uttara Kanda, Sarga 100, Verse 6', 'ततः पितामहो वाणीमन्तरिक्षादभाषत।
आगच्छ विष्णो भद्रं ते दिष्ट्या प्राप्तोऽसि राघव॥', 'tataḥ pitāmaho vāṇīm antarikṣād abhāṣata
āgaccha viṣṇo bhadraṃ te diṣṭyā prāpto ''si rāghava', null, 7100006),
('ramayana-7-100-7', 7, 'Uttara Kanda, Sarga 100, Verse 7', 'भ्रातृभिः सह देवाभैः प्रविशस्व स्वकां तनुम्।
वैष्णवीं तां महातेजस्तदाकाशं सनातनम्॥', 'bhrātṛbhiḥ saha devābhaiḥ praviśasva svakāṃ tanum
vaiṣṇavīṃ tāṃ mahātejas tad ākāśaṃ sanātanam', null, 7100007),
('ramayana-7-100-8', 8, 'Uttara Kanda, Sarga 100, Verse 8', 'त्वं हि लोकगतिर्देव न त्वां के चित्प्रजानते।
ऋते मायां विशालाक्ष तव पूर्वपरिग्रहाम्॥', 'tvaṃ hi lokagatir deva na tvāṃ ke cit prajānate
ṛte māyāṃ viśālākṣa tava pūrvaparigrahām', null, 7100008),
('ramayana-7-100-9', 9, 'Uttara Kanda, Sarga 100, Verse 9', 'त्वमचिन्त्यं महद्भूतमक्षयं सर्वसंग्रहम्।
यामिच्छसि महातेजस्तां तनुं प्रविश स्वयम्॥', 'tvam acintyaṃ mahad bhūtam akṣayaṃ sarvasaṃgraham
yām icchasi mahātejas tāṃ tanuṃ praviśa svayam', null, 7100009),
('ramayana-7-100-10', 10, 'Uttara Kanda, Sarga 100, Verse 10', 'पितामहवचः श्रुत्वा विनिश्चित्य महामतिः।
विवेश वैष्णवं तेजः सशरीरः सहानुजः॥', 'pitāmahavacaḥ śrutvā viniścitya mahāmatiḥ
viveśa vaiṣṇavaṃ tejaḥ saśarīraḥ sahānujaḥ', null, 7100010),
('ramayana-7-100-11', 11, 'Uttara Kanda, Sarga 100, Verse 11', 'ततो विष्णुगतं देवं पूजयन्ति स्म देवताः।
साध्या मरुद्गणाश्चैव सेन्द्राः साग्निपुरोगमाः॥', 'tato viṣṇugataṃ devaṃ pūjayanti sma devatāḥ
sādhyā marudgaṇāś caiva sendrāḥ sāgnipurogamāḥ', null, 7100011),
('ramayana-7-100-12', 12, 'Uttara Kanda, Sarga 100, Verse 12', 'ये च दिव्या ऋषिगणा गन्धर्वाप्सरसश्च याः।
सुपर्णनागयक्षाश्च दैत्यदानवराक्षसाः॥', 'ye ca divyā ṛṣigaṇā gandharvāpsarasaś ca yāḥ
suparṇanāgayakṣāś ca daityadānavarākṣasāḥ', null, 7100012),
('ramayana-7-100-13', 13, 'Uttara Kanda, Sarga 100, Verse 13', 'सर्वं हृष्टं प्रमुदितं सर्वं पूर्णमनोरथम्।
साधु साध्विति तत्सर्वं त्रिदिवं गतकल्मषम्॥', 'sarvaṃ hṛṣṭaṃ pramuditaṃ sarvaṃ pūrṇamanoratham
sādhu sādhv iti tat sarvaṃ tridivaṃ gatakalmaṣam', null, 7100013),
('ramayana-7-100-14', 14, 'Uttara Kanda, Sarga 100, Verse 14', 'अथ विष्णुर्महातेजाः पितामहमुवाच ह।
एषां लोकाञ्जनौघानां दातुमर्हसि सुव्रत॥', 'atha viṣṇur mahātejāḥ pitāmaham uvāca ha
eṣāṃ lokāñ janaughānāṃ dātum arhasi suvrata', null, 7100014),
('ramayana-7-100-15', 15, 'Uttara Kanda, Sarga 100, Verse 15', 'इमे हि सर्वे स्नेहान्मामनुयाता मनस्विनः।
भक्ता भाजयितव्याश्च त्यक्तात्मानश्च मत्कृते॥', 'ime hi sarve snehān mām anuyātā manasvinaḥ
bhaktā bhājayitavyāś ca tyaktātmānaś ca matkṛte', null, 7100015),
('ramayana-7-100-16', 16, 'Uttara Kanda, Sarga 100, Verse 16', 'तच्छ्रुत्वा विष्णुवचनं ब्रह्मा लोकगुरुः प्रभुः।
लोकान्सान्तानिकान्नाम यास्यन्तीमे समागताः॥', 'tac chrutvā viṣṇuvacanaṃ brahmā lokaguruḥ prabhuḥ
lokān sāntānikān nāma yāsyantīme samāgatāḥ', null, 7100016),
('ramayana-7-100-17', 17, 'Uttara Kanda, Sarga 100, Verse 17', 'यच्च तिर्यग्गतं किं चिद्राममेवानुचिन्तयत्।
प्राणांस्त्यक्ष्यति भक्त्या वै संताने तु निवत्स्यति।
सर्वैरेव गुणैर्युक्ते ब्रह्मलोकादनन्तरे॥', 'yac ca tiryaggataṃ kiṃ cid rāmam evānucintayat
prāṇāṃs tyakṣyati bhaktyā vai saṃtāne tu nivatsyati
sarvair eva guṇair yukte brahmalokād anantare', null, 7100017),
('ramayana-7-100-18', 18, 'Uttara Kanda, Sarga 100, Verse 18', 'वानराश्च स्वकां योनिमृक्षाश्चैव तथा ययुः॥', 'vānarāś ca svakāṃ yonim ṛkṣāś caiva tathā yayuḥ', null, 7100018),
('ramayana-7-100-19', 19, 'Uttara Kanda, Sarga 100, Verse 19', 'येभ्यो विनिःसृता ये ये सुरादिभ्यः सुसंभवाः।
ऋषिभ्यो नागयक्षेभ्यस्तांस्तानेव प्रपेदिरे॥', 'yebhyo viniḥsṛtā ye ye surādibhyaḥ susaṃbhavāḥ
ṛṣibhyo nāgayakṣebhyas tāṃs tān eva prapedire', null, 7100019),
('ramayana-7-100-20', 20, 'Uttara Kanda, Sarga 100, Verse 20', 'तथोक्तवति देवेशे गोप्रतारमुपागताः।
भेजिरे सरयूं सर्वे हर्षपूर्णाश्रुविक्लवाः॥', 'tathoktavati deveśe gopratāram upāgatāḥ
bhejire sarayūṃ sarve harṣapūrṇāśruviklavāḥ', null, 7100020),
('ramayana-7-100-21', 21, 'Uttara Kanda, Sarga 100, Verse 21', 'अवगाह्य जलं यो यः प्राणी ह्यासीत्प्रहृष्टवत्।
मानुषं देहमुत्सृज्य विमानं सोऽध्यरोहत॥', 'avagāhya jalaṃ yo yaḥ prāṇī hy āsīt prahṛṣṭavat
mānuṣaṃ deham utsṛjya vimānaṃ so ''dhyarohata', null, 7100021),
('ramayana-7-100-22', 22, 'Uttara Kanda, Sarga 100, Verse 22', 'तिर्यग्योनिगताश्चापि संप्राप्ताः सरयूजलम्।
दिव्या दिव्येन वपुषा देवा दीप्ता इवाभवन्॥', 'tiryagyonigatāś cāpi saṃprāptāḥ sarayūjalam
divyā divyena vapuṣā devā dīptā ivābhavan', null, 7100022),
('ramayana-7-100-23', 23, 'Uttara Kanda, Sarga 100, Verse 23', 'गत्वा तु सरयूतोयं स्थावराणि चराणि च।
प्राप्य तत्तोयविक्लेदं देवलोकमुपागमन्॥', 'gatvā tu sarayūtoyaṃ sthāvarāṇi carāṇi ca
prāpya tat toyavikledaṃ devalokam upāgaman', null, 7100023),
('ramayana-7-100-24', 24, 'Uttara Kanda, Sarga 100, Verse 24', 'देवानां यस्य या योनिर्वानरा ऋष्कराक्षसाः।
तामेव विविशुः सर्वे देहान्निक्षिप्य चाम्भसि॥', 'devānāṃ yasya yā yonir vānarā ṛṣkarākṣasāḥ
tām eva viviśuḥ sarve dehān nikṣipya cāmbhasi', null, 7100024),
('ramayana-7-100-25', 25, 'Uttara Kanda, Sarga 100, Verse 25', 'तथा स्वर्गगतं सर्वं कृत्वा लोकगुरुर्दिवम्।
जगाम त्रिदशैः सार्धं हृष्टैर्हृष्टो महामतिः॥', 'tathā svargagataṃ sarvaṃ kṛtvā lokagurur divam
jagāma tridaśaiḥ sārdhaṃ hṛṣṭair hṛṣṭo mahāmatiḥ', null, 7100025),
('ramayana-7-100-26', 26, 'Uttara Kanda, Sarga 100, Verse 26', 'एतावदेव आख्यानं सोत्तरं ब्रह्मपूजितम्।
रामायणमिति ख्यातं मुख्यं वाल्मीकिना कृतम्॥', 'etāvad eva ākhyānaṃ sottaraṃ brahmapūjitam
rāmāyaṇam iti khyātaṃ mukhyaṃ vālmīkinā kṛtam', null, 7100026)
) as x(id, n, reference, sanskrit, transliteration, speaker, sort_key);

